__reload_all = true
local System = require("System.System")
local readonly = System.readonly
local Text_AvgDialog = readonly({
  AvgDialog_100303_Content_1 = {
    Text = "Huu... huu... Tidak benar... masih tidak benar..."
  },
  AvgDialog_100303_Content_10 = {
    Text = "Mengapa, jelas-jelas ada di depan mata, tetapi mengapa aku masih tidak bisa menemukannya..."
  },
  AvgDialog_100303_Content_11 = {
    Text = "Jangan terburu-buru, Pikman. Jika Muse sudah memberi tahu kamu, pasti jawabannya sudah sangat dekat. Pikirkan baik-baik, adakah yang kamu lewatkan."
  },
  AvgDialog_100303_Content_12 = {
    Text = "Sebelum itu, bangkitlah dulu… sss…"
  },
  AvgDialog_100303_Content_13 = {
    Text = "Kamu tiba-tiba menarik kembali tangan yang ingin membantunya berdiri. Di dalam tubuhnya yang panas bagaikan aliran lava."
  },
  AvgDialog_100303_Content_14 = {
    Text = "Ternyata, itu adalah perbuatan baik Thais lagi..."
  },
  AvgDialog_100303_Content_15 = {
    Text = "Thais… ah! Ya! Kenapa aku tidak memikirkannya! Kenapa aku bisa melewatkannya!!"
  },
  AvgDialog_100303_Content_16 = {
    Text = "Dia tiba-tiba duduk tegak, hampir melihatmu dengan mata yang bisa membakar."
  },
  AvgDialog_100303_Content_17 = {
    Text = "Keinginan yang paling gila... Betul sekali! Saya mengerti, saya mengerti..."
  },
  AvgDialog_100303_Content_18 = {
    Text = "Dia begitu bersemangat hingga lupa untuk berdiri, merangkak dengan tangan dan kaki mendekatimu."
  },
  AvgDialog_100303_Content_19 = {
    Text = "Penjaga, bisakah kamu sekali lagi menjadi modelku? Hanya sekali! Cukup sekali!"
  },
  AvgDialog_100303_Content_2 = {Text = "Pikman?"},
  AvgDialog_100303_Content_20 = {
    Text = "Aku tahu apa yang ingin kau lakukan, pasti tidak..."
  },
  AvgDialog_100303_Content_21 = {
    Text = "Pasangan mata Pigman yang gelisah dan memohon dengan merah di bawah cahaya redup berkilau sedikit. Kata penolakan tak mampu keluar lagi."
  },
  AvgDialog_100303_Content_22 = {
    Text = "……Baiklah. Jika hanya untuk berperan sebagai model. Apakah saya tetap duduk di sofa itu?"
  },
  AvgDialog_100303_Content_23 = {
    Text = "Tidak, tidak, tidak, Penjaga, bagaimana mungkin menciptakan lukisan seperti itu di dalam studio seni?!"
  },
  AvgDialog_100303_Content_25 = {
    Text = "Ini... dunia dalam lukisanmu?"
  },
  AvgDialog_100303_Content_26 = {
    Text = "Benar! Itu adalah upacara perayaan para ghoul!"
  },
  AvgDialog_100303_Content_27 = {
    Text = "Aku menciptakannya, tetapi aku belum pernah menyelesaikannya. Di tengah-tengahnya kurang sepasang tokoh utama. Mereka mewakili keinginan yang paling primitif dan paling gila di alam semesta ini, keinginan yang telah aku lupakan……"
  },
  AvgDialog_100303_Content_28 = {
    Text = "Saya belum menemukan model yang cukup untuk menjadi karakter utama, hingga sekarang......"
  },
  AvgDialog_100303_Content_29 = {
    Text = "Pikman masih dalam posisi berlutut, menyeret lututnya mendekat kepadamu."
  },
  AvgDialog_100303_Content_3 = {
    Text = "Studio Pigman yang gelap lebih berantakan daripada sebelumnya, banyak lembar kertas kulit yang dipenuhi warna dan garis berserakan di setiap sudut studio, seolah baru saja mengalami perang yang aneh."
  },
  AvgDialog_100303_Content_30 = {
    Text = "Tolong, Penjaga... berikan saya Muse!"
  },
  AvgDialog_100303_Content_31 = {
    Text = "Kamu bisa meminta saya melakukan apa saja! Hanya sekali, sekali saja! Tolong bawalah saya menyelesaikan lukisan ini..."
  },
  AvgDialog_100303_Content_32 = {
    Text = "Tanpa ragu lagi, Anda menghela napas dan mendekatinya."
  },
  AvgDialog_100303_Content_33 = {
    Text = "Dia mengangkat kepalanya, membuka matanya lebar-lebar menatapmu. Itu adalah sepasang mata dari binatang buas atau peliharaan, serakah, haus, patuh, setia. Dia sedang merayu, memohon perintah yang membawanya ke Muse."
  },
  AvgDialog_100303_Content_34 = {
    Text = "Bisa melakukan apa saja... Jadi, saya perlu berpikir baik-baik..."
  },
  AvgDialog_100303_Content_35 = {
    Text = "Kamu perlahan-lahan meletakkan tanganmu di wajah Pikman. Napasnya yang panas dan tubuhnya menjadi patuh. Tidak tahu apakah kamu yang menjinakannya, ataukah ia yang melelehkanmu."
  },
  AvgDialog_100303_Content_36 = {
    Text = "Suara ghaib mulai menghilang, berasal dari suara primitif yang kasar dari kedua protagonis, memenuhi seluruh dunia dalam lukisan."
  },
  AvgDialog_100303_Content_37 = {
    Text = "Itu adalah suara dari muses."
  },
  AvgDialog_100303_Content_4 = {
    Text = "Dia yang berpakaian acak-acakan berlutut di tanah, menghapus dengan gila di atas selembar kertas kosong, hampir merusak kertas tersebut. Cat yang terpercik membanjiri tubuhnya, seperti seorang pemuja yang sedang mengadakan ritual liar."
  },
  AvgDialog_100303_Content_5 = {
    Text = "Apa yang terjadi…"
  },
  AvgDialog_100303_Content_6 = {
    Text = "Aku mendengar, Penjaga! Aku mendengar suara Muse memanggil! Tepat di telingaku!"
  },
  AvgDialog_100303_Content_7 = {
    Text = "Mataku, tanganku, jantungku, setiap sel di seluruh tubuhku, semua bergetar karena suaranya!"
  },
  AvgDialog_100303_Content_8 = {
    Text = "Hanya satu langkah lagi! Aku hanya selangkah lagi menuju seni terbesar!"
  },
  AvgDialog_100303_Content_9 = {
    Text = "Tapi saya tidak dapat menemukan... Pembunuhan, penaklukan, makan yang rakus, keserakahan, pemborosan, ketiadaan... Saya sudah menggambarkan semua Kegilaan, tetapi saya masih belum menemukan itu..."
  },
  AvgDialog_100588_Content_1 = {
    Text = "Sebuah bayangan gelap perlahan muncul di hadapanmu."
  },
  AvgDialog_100588_Content_2 = {
    Text = "[Serangan]???"
  },
  AvgDialog_100588_Content_3 = {
    Text = [[
Kau telah menyebabkan 677 poin kerusakan! Kau merasa telah menimbulkan total 27.188 poin kerusakan padanya.
Semua orang telah menyebabkan total 14.636.643.707 poin kerusakan padanya, tetapi dia masih belum jatuh.]]
  },
  AvgDialog_100588_Content_4 = {Text = "[Lanjut]"},
  AvgDialog_100588_Content_5 = {
    Text = "Kau merasa pernah datang ke sini…\nDi bawah tatapan bayangan, kesadaranmu mulai kabur."
  },
  AvgDialog_100588_Content_6 = {Text = "[Tidur]"},
  AvgDialog_100629_Content_1 = {
    Text = "Tidak lama setelah itu, dunia ini tidak lagi kesulitan oleh korosi, umat manusia berkembang pesat, dan kemudian Universitas Missage menghentikan sebuah kereta di bawah langit berbintang…"
  },
  AvgDialog_10120_Content_1 = {
    Text = [[
Lindungi instrumen di tanganmu dengan baik, berhati-hatilah terhadap pencemaran akibat pelarutan. 
 Dalam pertempuran yang akan datang, itu sangat diperlukan.]]
  },
  AvgDialog_10120_Content_2 = {
    Text = "Tahan <Yellow:Kartu perintah>, seret ke <Yellow:Area perintah pusat>, dan berikan instruksi tindakan kepada saya."
  },
  AvgDialog_10121_Content_1 = {
    Text = "<Yellow:Perak>? Tidak disangka di sini…"
  },
  AvgDialog_10121_Content_2 = {
    Text = "Membuat kunci perak, menghubungkan Pembangun, menyediakan energi roh…\nSemua aktivitas Mythag sangat terkait dengan<Yellow:Perak>."
  },
  AvgDialog_10121_Content_3 = {
    Text = [[
Bahkan sejumlah kecil <Yellow:Perak>, memiliki nilai luar biasa bagi penelitian Mythag.
Kumpulkan semuanya jika memungkinkan.]]
  },
  AvgDialog_10122_Content_1 = {
    Text = "Menunda-nunda hanya akan merugikan kita. Kita harus menyelesaikan ini dengan cepat."
  },
  AvgDialog_10122_Content_2 = {
    Text = [[
Ini adalah <Yellow:"Pedang Ratu"> yang telah aku pelajari sejak kecil.
Dengan serangan ini, aku akan mengakhirinya!]]
  },
  AvgDialog_10123_Content_1 = {
    Text = "Kalian melewati pintu kecil di bawah menara jam, memasuki sebuah lorong tertutup yang tersembunyi."
  },
  AvgDialog_10123_Content_11 = {
    Text = "Gerbang perlahan terbuka, pemandangan tempat Tabu untuk pertama kalinya terungkap di hadapan kalian."
  },
  AvgDialog_10123_Content_13 = {
    Text = "Bagian bawah tubuh-Nya terendam dalam lumpur hitam, kegelapan yang melahap segalanya membuat-Nya tampak semakin cemerlang dan memukau, putih bersih tanpa cacat."
  },
  AvgDialog_10123_Content_14 = {
    Text = "Dalam kebingungan, sosok non-manusia di depan matamu perlahan bertumpang tindih dengan siluet wanita muda yang kamu lihat saat terpaku di dalam Kuil Kunci."
  },
  AvgDialog_10123_Content_15 = {
    Text = "Dia tidak memiliki wajah, namun dari postur tubuh-Nya yang tegak, kau merasakan semacam rasa belas kasihan."
  },
  AvgDialog_10123_Content_16 = {
    Text = "Yang Tertinggi, Yang Paling Suci, Yang Paling Baik, Yang Paling Indah."
  },
  AvgDialog_10123_Content_17 = {
    Text = "<Shake:Kamu... datang...>"
  },
  AvgDialog_10123_Content_18 = {
    Text = "Monster putih mengeluarkan suara serak, mirip dengan raungan, dan juga seperti ratapan."
  },
  AvgDialog_10123_Content_19 = {
    Text = "Itu bukan bahasa manusia, namun kamu memahami makna dari perkataan-Nya."
  },
  AvgDialog_10123_Content_2 = {
    Text = "Boneka memimpin jalan di depan, langkahnya menghantam permukaan logam, menghasilkan gema yang kosong."
  },
  AvgDialog_10123_Content_20 = {
    Text = "Segalanya di depan mata tiba-tiba menjadi buram. Kamu berkedip, dan cairan hangat mengalir melewati pipi."
  },
  AvgDialog_10123_Content_21 = {
    Text = "Apakah itu air mata? Tapi mengapa? Apa yang membuatmu merasa sesak di dada dan mata terasa perih?"
  },
  AvgDialog_10123_Content_22 = {
    Text = "……<Yellow:Tawil>?"
  },
  AvgDialog_10123_Content_23 = {
    Text = "Kata-kata yang diucapkan oleh Boneka membuat ekspresi Ramona berubah."
  },
  AvgDialog_10123_Content_24 = {
    Text = "Tawil? Apakah dia salah satu pendiri, Pembangun Tawil?"
  },
  AvgDialog_10123_Content_25 = {
    Text = "Kamu juga ingat. \n Di dalam <Blue:《Sejarah Mythag》>, nama itu muncul bersama dengan dua nama lainnya."
  },
  AvgDialog_10123_Content_26 = {
    Text = "Tahun Hongji ke-90, <Blue:Ward Phillips>, <Blue:Keralkesh>, dan <Blue:Tawil> mendirikan <Blue:Perguruan tinggi mythag (Mythag College)>."
  },
  AvgDialog_10123_Content_27 = {
    Text = "Itulah tempat di mana kamu berada sekarang, pendahulu dari <Blue:Universitas Mythag (Mythag University)>."
  },
  AvgDialog_10123_Content_28 = {
    Text = "Sang Penjaga Rahasia."
  },
  AvgDialog_10123_Content_29 = {Text = "Saya ada."},
  AvgDialog_10123_Content_3 = {
    Text = "Aku baru pertama kali tahu, ternyata ada lorong rahasia seperti ini di bawah menara jam…"
  },
  AvgDialog_10123_Content_30 = {
    Text = "Kamu bisa berdiri di sini sekarang, bukan diusir oleh Tawil. Hal ini menunjukkan bahwa takdirmu sudah erat terhubung dengan masa depan Mythag."
  },
  AvgDialog_10123_Content_31 = {
    Text = "Jadi, kamu memenuhi syarat untuk mendengar informasi yang akan aku sampaikan selanjutnya."
  },
  AvgDialog_10123_Content_32 = {
    Text = "Ini adalah rahasia terdalam Universitas Mythag. \nTawil — sang pendiri Universitas Mythag — bukan manusia, juga bukan Pembangun."
  },
  AvgDialog_10123_Content_33 = {
    Text = "Dia adalah makhluk dari Dimensi lain. Saat pertama kali muncul, Dia hanya terdengar sebagai bisikan oleh Kepala Sekolah Generasi Pertama, Phillips."
  },
  AvgDialog_10123_Content_34 = {
    Text = "Bertentangan dengan pemahaman bahwa \"Tawil adalah Pembangun,\" teknologi Pembangun yang menyempurnakan Perak, <Yellow:Bangun mayat yang beresonansi dengan kehendak tinggi>, lahir berkat bimbingan Tawil."
  },
  AvgDialog_10123_Content_35 = {
    Text = "Tawil meramalkan kedatangan Pelarutan dan masa depan kehancuran dunia, menyampaikan \"Kebenaran\" pertama, dan jatuh ke dalam tidur setelah berdirinya Perguruan Tinggi Mythag."
  },
  AvgDialog_10123_Content_36 = {
    Text = "Menurut catatan Tuan Phillips, ini adalah cara keberadaan \"tidak ada\" yang dipilih oleh Tawil untuk menghindari \"diamati\"."
  },
  AvgDialog_10123_Content_37 = {
    Text = "Hanya ketika \"variabel\" muncul, Dia akan \"bangkit\" kembali melalui \"kebangkitan\" ——"
  },
  AvgDialog_10123_Content_38 = {
    Text = "Cepat lihat!"
  },
  AvgDialog_10123_Content_39 = {
    Text = "Seolah-olah menjadi pertanda kedatangan suatu Tabu dan Clades, \"Tawil\"mengeluarkan teriakan melengkung yang menusuk gendang telinga."
  },
  AvgDialog_10123_Content_4 = {
    Text = [[
Seperti yang diketahui orang, saya rasa itu tidak perlu disebut sebagai jalan rahasia.
Lorong ini menghubungkan ke <Yellow:Kolam hitam>, yang merupakan fondasi dari Mythag.]]
  },
  AvgDialog_10123_Content_40 = {
    Text = "Dengan getaran seperti anak burung yang menetas, enam sayap perak raksasa terentang ke samping dari Tubuh-Nya."
  },
  AvgDialog_10123_Content_41 = {
    Text = "Ujung sayap terus meneteskan tetesan cairan perak, yang jatuh berderai-derai ke dalam kolam air hitam."
  },
  AvgDialog_10123_Content_42 = {
    Text = "Cairan perak menyatu ke dalam Kolam Hitam, saat itu riak di kolam bergelombang, Tubuh yang Terlulur hitam dan bengkok bergerak keluar."
  },
  AvgDialog_10123_Content_43 = {
    Text = "Monster yang cacat mengabaikan hukum fisika dan menerjang keluar dari Kolam Hitam, beberapa di antaranya menyerbu ke arah kalian, sementara yang lain menuju alun-alun di luar Menara Jam."
  },
  AvgDialog_10123_Content_44 = {
    Text = "<Shake:Akhirnya… menemukan… kamu… sudah…>"
  },
  AvgDialog_10123_Content_45 = {
    Text = "Hentikan Dia! Hanya dengan menghentikan-Nya, kita bisa memutus sumber monster!"
  },
  AvgDialog_10123_Content_5 = {
    Text = "Jika bukan karena adanya <Yellow:inti> yang disebut <Yellow:Perak raksasa> di dasar Kolam Hitam, hanya mengandalkan Roh manusia yang lemah untuk mempertahankan Bangun di dunia nyata, teknologi Pembangun Mythag mungkin akan tertinggal beberapa dekade dari sekarang."
  },
  AvgDialog_10123_Content_6 = {
    Text = "Jadi, Pembangun yang tidak terhubung Tautan tidak diizinkan meninggalkan Mythag, apakah ini juga karena khawatir kami akan jatuh ke dalam Kegilaan?"
  },
  AvgDialog_10123_Content_7 = {
    Text = [[
Tidak sepenuhnya begitu. 
Kalau saja setiap Pembangun seperti kamu, Ogier.]]
  },
  AvgDialog_10123_Content_8 = {
    Text = "Baik, kita sudah tiba."
  },
  AvgDialog_10123_Content_9 = {
    Text = [[
Sambil berkata, Boneka menekan sebuah tombol yang tidak mencolok di sisi lorong. 
Dengan bunyi 'ding', pintu terbuka lebar, kalian melangkah ke ruang sempit dengan cahaya redup.]]
  },
  AvgDialog_10124_Content_1 = {
    Text = "Tampaknya kamu sudah menemukan negaranya. Selanjutnya, komando akan kuserahkan padamu, Penjaga!"
  },
  AvgDialog_10125_Content_1 = {
    Text = "Hah, maaf, sekarang tidak ada waktu untuk menunggu kau beradaptasi."
  },
  AvgDialog_10125_Content_10 = {
    Text = "Ramona sangat terkejut. Dalam memori, sepertinya kamu belum pernah melihatnya begitu cemas sebelumnya."
  },
  AvgDialog_10125_Content_11 = {
    Text = "Suara gadis yang dibanjiri masalah bergetar, tampak sedikit lelah."
  },
  AvgDialog_10125_Content_12 = {
    Text = "Kamu mengenalnya, dia adalah Profesor Boneka yang terkenal sulit diajak berkomunikasi, bernaung di bawah <Blue:Bangun Research Institute>. Dengan kata lain, dia bukan personel pertempuran."
  },
  AvgDialog_10125_Content_13 = {
    Text = "Kalau tidak, apakah saya datang ke sini untuk berlibur?"
  },
  AvgDialog_10125_Content_14 = {
    Text = "Dia menutup matanya sejenak, lalu menyemangati dirinya."
  },
  AvgDialog_10125_Content_15 = {
    Text = "Makam Kunci ternyata juga diserang? Di sini dekat pintu belakang, kalian harus segera pergi."
  },
  AvgDialog_10125_Content_16 = {
    Text = "Kami bisa membantu! %player% dapat menghubungkan kita semua, lalu memimpin——"
  },
  AvgDialog_10125_Content_17 = {
    Text = [[
Ramona. 
 Itu adalah kewajiban kita, %player% hanyalah seorang pemula yang baru saja menyelesaikan pendidikan pra-sekolah.]]
  },
  AvgDialog_10125_Content_18 = {
    Text = "Tetapi %player% sudah terhubung dengan saya melalui Tautan, saya tahu {Male=dia,Female=dia} bisa…… Saya percaya {Male=dia,Female=dia} bisa!"
  },
  AvgDialog_10125_Content_19 = {
    Text = "Boneka mengamati kamu dari atas ke bawah, lalu memasang wajah serius ke arah Ramona."
  },
  AvgDialog_10125_Content_2 = {
    Text = "Varian abnormal tiba di Key Mound sebelum alarm berbunyi, kemungkinan besar <Blue:Penghalang Kabut> di perimeter Mythag sudah tidak berfungsi."
  },
  AvgDialog_10125_Content_20 = {
    Text = [[
Jika saya tidak salah, upacara sumpah seharusnya belum selesai. 
{Male=dia,Female=dia} belum diberikan Kunci perak, bukan?]]
  },
  AvgDialog_10125_Content_21 = {
    Text = "Selanjutnya, kita akan memasuki zona terlarang Mythag. Masuk tanpa izin ke zona terlarang seperti apa tingkat kecelakaannya? Aku pikir kamu yang dibesarkan di sini sejak kecil sudah memahaminya."
  },
  AvgDialog_10125_Content_22 = {
    Text = [[
Kondisinya mendesak, kita tidak punya pilihan lain, bukan? 
Lagipula, %player% bukanlah pendatang baru biasa, {Male=dia,Female=dia} adalah satu-satunya Penjaga.]]
  },
  AvgDialog_10125_Content_23 = {
    Text = "Kau harus ingat, tentang <Yellow: ledakan besar Akut> setahun yang lalu. Jika bukan karena {Male=dia,Female=dia} yang menghubungkan semua pembangun sendirian, aku tidak akan bisa berdiri di sini berdebat denganmu."
  },
  AvgDialog_10125_Content_24 = {
    Text = "Gadis berambut merah muda tidak menjawab, melainkan berbalik ke arahmu."
  },
  AvgDialog_10125_Content_25 = {
    Text = "Aku tahu kau pernah melihat sekilas apa yang ada di dalam <Yellow:\"pintu\">. Namun, baik masa depan dunia maupun inti Mythag mungkin lebih mengerikan daripada yang kau bayangkan."
  },
  AvgDialog_10125_Content_26 = {
    Text = "Kami menghadapi fenomena yang dapat menyebabkan kehancuran terhadap keberadaan materi itu sendiri. Begitu terkontaminasi oleh <Yellow:Pelarutan>, segala sesuatu dari dirimu akan lenyap tanpa bekas."
  },
  AvgDialog_10125_Content_27 = {
    Text = "Nama yang kamu ukir di batu nisan selama upacara sumpah juga akan berubah menjadi sebongkah lumpur hitam, tanpa ada seorang pun yang mengingatnya."
  },
  AvgDialog_10125_Content_28 = {
    Text = "Jawab aku, apakah kamu sudah benar-benar siap?"
  },
  AvgDialog_10125_Content_29 = {
    Text = "Boneka menatapmu dengan dingin, nadanya tanpa emosi."
  },
  AvgDialog_10125_Content_3 = {
    Text = [[
<Blue:William> Kakak Senior tahu hari ini ada ritual di Makam Kunci, tapi bala bantuan belum datang, ditambah dengan suara lonceng... 
 Kita harus cari cara untuk bertemu mereka, <Yellow:memberantas sumber gangguan>.]]
  },
  AvgDialog_10125_Content_30 = {
    Text = "Dia tampak tidak memiliki ekspresi, tetapi dari dasar murid matanya yang seperti es, kamu bisa melihat api yang berkobar dengan ganas."
  },
  AvgDialog_10125_Content_31 = {
    Text = "Jawaban Anda adalah——"
  },
  AvgDialog_10125_Content_32 = {
    Text = "Nisan saya, sekarang berdiri di tengah Key Mound."
  },
  AvgDialog_10125_Content_33 = {
    Text = [[
Kamu adalah anggota Mythag.
Mungkin sejak di Akut, kamu sudah menjadi salah satunya.]]
  },
  AvgDialog_10125_Content_34 = {
    Text = "Di sini ada sesuatu yang hanya bisa aku lakukan."
  },
  AvgDialog_10125_Content_35 = {
    Text = "Keputusan ini mungkin terlihat sedikit terburu-buru, tetapi siapa yang bisa menjamin bahwa setiap momen dalam hidup selalu dipersiapkan dengan sempurna?"
  },
  AvgDialog_10125_Content_36 = {Text = "Baiklah."},
  AvgDialog_10125_Content_37 = {
    Text = "Saya, sebagai kepala sekolah keenam Mythag <Blue:Oliver Elsi>, memberikan kunci perak bernomor K-0617 ini kepadamu."
  },
  AvgDialog_10125_Content_39 = {
    Text = [[
Boneka mengeluarkan kunci perak dari kotak kecil yang presisi dan memasangnya di dada Anda. 
 Kunci perak berkilauan, sensasi yang familiar memenuhi rongga dada.]]
  },
  AvgDialog_10125_Content_4 = {Text = "Apa itu?!"},
  AvgDialog_10125_Content_40 = {
    Text = "Mulai sekarang, dengan gelar Penjaga, engkau akan bersama ribuan guru dan siswa di Mythag."
  },
  AvgDialog_10125_Content_42 = {
    Text = "Sekarang, buat tautan denganku."
  },
  AvgDialog_10125_Content_43 = {
    Text = [[
Kamu dengan hati-hati mengaktifkan Kunci Perak sesuai dengan pelatihan.
Cahaya perak berkilauan, Tautan Roh seperti ribuan benang tak terlihat menghubungkan indra kamu dan Boneka.]]
  },
  AvgDialog_10125_Content_44 = {
    Text = [[
Seolah-olah aliran listrik tersambung, "prak" sebuah suara, tak terhitung banyaknya informasi cahaya dan bayangan memasuki pikiran. 
 Kamu terguncang oleh debaran jantung yang kuat, hampir tidak bisa berdiri tegak.]]
  },
  AvgDialog_10125_Content_45 = {
    Text = "Boneka, kamu…"
  },
  AvgDialog_10125_Content_46 = {
    Text = "Kedatanganmu sangat tepat, Penjaga.\nAku dan Ogier… sudah hampir kehabisan tenaga."
  },
  AvgDialog_10125_Content_47 = {
    Text = "Kamu tetap di sini untuk beristirahat, aku dan Ramona akan memberikan dukungan kepada Ogier dalam pertempuran."
  },
  AvgDialog_10125_Content_48 = {
    Text = "Tenang. Meskipun Roh-mu bisa bertahan, luka Ramona tidak cocok untuk segera terjun ke Pertempuran."
  },
  AvgDialog_10125_Content_49 = {
    Text = "Anak itu masih bisa bertahan sebentar, ikuti aku dulu."
  },
  AvgDialog_10125_Content_6 = {
    Text = "Di ujung pandangan, pemuda berambut emas mengangkat perisai raksasa hitam yang tidak sesuai dengan posturnya, sedang menahan serangan dari seorang pejuang pedang ganda yang gesit."
  },
  AvgDialog_10125_Content_7 = {
    Text = "Dia menggunakan Perisai untuk melindungi gadis berambut panjang merah muda di belakangnya dengan kuat, namun terus terdesak mundur."
  },
  AvgDialog_10125_Content_8 = {
    Text = "Tunggu… orang yang sedang menyerang… adalah <Yellow:Pembangun> Lotan?!"
  },
  AvgDialog_10125_Content_9 = {
    Text = "Boneka? <Blue:Menara Jam> tidak terkendali?!"
  },
  AvgDialog_10126_Content_1 = {
    Text = "Ketika hidup berkurang hingga 0, kekuatan roh tidak akan mampu mendukung instrumen untuk terus menjelajahi <Yellow:Domain>. Demi menjamin keselamatan personel tempur, instrumen akan memaksa Anda keluar dari pertempuran."
  },
  AvgDialog_10126_Content_2 = {
    Text = "Kali ini situasinya mendesak, saya telah menyesuaikan daya alat tersebut. Alat itu akan mengeluarkan daya berdasarkan kesehatan fisik Penjaga yang stabil dan penuh dengan Aliemus."
  },
  AvgDialog_10126_Content_3 = {
    Text = "Pendekatan ini sangat berbahaya, namun kita tidak punya pilihan selain mencobanya. Sekarang, gunakan Muliakan untuk mengakhiri pertarungan ini!"
  },
  AvgDialog_10127_Content_1 = {
    Text = "Betapa hangatnya... Tautan roh sangat stabil, Roh dan Hidupmu belum pernah sekuat hari ini."
  },
  AvgDialog_10127_Content_2 = {
    Text = [[
Kamu tidak bisa begitu saja menyerah, <Yellow:Penjaga satu-satunya di dunia>. 
 Kami masih mengandalkanmu untuk melakukan penyelidikan dan mencatat semua sejarah yang telah dihapus oleh pelarutan.]]
  },
  AvgDialog_10127_Content_3 = {
    Text = "Kekhawatiran di matanya menghilang, Ramona dengan setengah bercanda membentuk senyuman yang menenangkan di sudut bibirnya."
  },
  AvgDialog_10127_Content_4 = {
    Text = "Suara hujan yang merata memenuhi langit dan bumi."
  },
  AvgDialog_10127_Content_5 = {
    Text = "<Red: Gelisah, nyeri, sesak napas> namun saat tetesan air hujan jatuh, dada terasa penuh."
  },
  AvgDialog_10127_Content_7 = {Text = "Ramona!"},
  AvgDialog_10127_Content_9 = {
    Text = "Lonceng berbunyi."
  },
  AvgDialog_10128_Content_1 = {
    Text = "Hati-hati, mereka memasuki mode serangan kuat!"
  },
  AvgDialog_10128_Content_2 = {
    Text = [[
Takut apa, aku masih di sini. 
Penjaga, biarkan aku menjalankan <Yellow:"Operasi luar">.]]
  },
  AvgDialog_10129_Content_1 = {
    Text = "Aktifkan Kunci perak, %player%."
  },
  AvgDialog_10129_Content_2 = {
    Text = "Kunci perak berkilauan, sebuah pemandangan halusinasi tiba-tiba muncul, dan secara bertahap menyatu dengan realitas di depan mata."
  },
  AvgDialog_10129_Content_3 = {
    Text = "Rasa pusing membuat pikiran menjadi kaku, seperti ada sirene meraung di dalam otak, suara Boneka juga mulai terdengar semakin jauh…"
  },
  AvgDialog_10129_Content_4 = {
    Text = "Kamu berusaha menenangkan pikiranmu, memilah-milah informasi yang diberikan oleh Boneka dari kebisingan dan keriuhan."
  },
  AvgDialog_10129_Content_5 = {
    Text = "Tahukah kamu? Yang ada di depan matamu sekarang adalah Domain —— sebuah area khusus yang terbentuk bersama oleh <Yellow:Dimensi Mimpi> dan <Yellow:Dimensi Realitas>."
  },
  AvgDialog_10129_Content_6 = {
    Text = "Mythag memproyeksikan sebagian <Blue:Persimpangan> di dalam Domain untuk menstabilkan pikiran Penyelidik yang cenderung menuju kegilaan, membantu Pembangun menyembuhkan luka."
  },
  AvgDialog_10129_Content_7 = {
    Text = "Namun, intervensi manusia memiliki efek yang terbatas di dalam Domain. Kami tidak dapat menjamin lokasi munculnya <Blue:Persimpangan>. Segalanya masih bergantung pada kemampuanmu untuk beradaptasi dengan situasi."
  },
  AvgDialog_10129_Content_8 = {
    Text = "Sekarang, pergilah ke <Blue:Persimpangan> terdekat dan bantu Ramona menyembuhkan lukanya."
  },
  AvgDialog_10130_Content_10 = {
    Text = "Selama nama masih terukir di prasasti, keberadaan kita tidak akan pernah dihapus oleh @2."
  },
  AvgDialog_10130_Content_11 = {
    Text = "Suara yang lembut bercampur dengan raungan yang terdistorsi bergema di dalam pikiran."
  },
  AvgDialog_10130_Content_12 = {
    Text = "Aku akan menjadi asistenmu, menemanimu hingga akhir dari jalan ini…<Yellow:Semoga Kunci perak membimbing jalan ke depan.>"
  },
  AvgDialog_10130_Content_13 = {
    Text = [[
Apa kabar, %player%?
Sejak tadi, ekspresi wajahmu tampak tidak baik. Apakah kamu butuh aku antar ke ruang kesehatan?]]
  },
  AvgDialog_10130_Content_14 = {
    Text = "Suara yang segar dan tajam membuat pikiran lebih jernih, dan perasaan pusing secara bertahap mulai memudar."
  },
  AvgDialog_10130_Content_15 = {
    Text = "Tidak apa-apa, hanya sedikit pusing, sudah mereda."
  },
  AvgDialog_10130_Content_16 = {
    Text = [[
Hmm, untuk lebih aman, mari kita tautkan.
Sebagai asisten dan juga sebagai mitraku, mengonfirmasi statusmu selalu merupakan tanggung jawabku.]]
  },
  AvgDialog_10130_Content_17 = {
    Text = "Sekarang? Di sini?"
  },
  AvgDialog_10130_Content_18 = {
    Text = "Sedikit lebih awal, tapi tidak masalah, kan?"
  },
  AvgDialog_10130_Content_19 = {
    Text = "Sejak satu tahun yang lalu, aku sudah sangat menantikan hari ini."
  },
  AvgDialog_10130_Content_2 = {
    Text = "Selamat datang di Universitas Mythag, %player%."
  },
  AvgDialog_10130_Content_21 = {
    Text = "Gerimis membasahi ujung jarinya, aliran listrik yang lemah menembus sarung tangan, mengalir secara terselubung melalui kulitmu dan ujung jarinya."
  },
  AvgDialog_10130_Content_22 = {
    Text = "Perasaan yang tak terdefinisikan mengalir melalui arus listrik dan menyentuh sarafmu, yaitu kegembiraan, keceriaan, kegelisahan, dan…"
  },
  AvgDialog_10130_Content_23 = {
    Text = "...<Yellow:Keinginan>."
  },
  AvgDialog_10130_Content_3 = {
    Text = "Atau mungkin... selamat datang, kamu secara resmi melangkah ke sisi lain dari dunia."
  },
  AvgDialog_10130_Content_4 = {
    Text = "Aku sudah kembali."
  },
  AvgDialog_10130_Content_5 = {
    Text = "Kehadiranmu bisa dikatakan sudah sangat dinantikan. Dalam waktu kurang dari dua hari, William akan memberikan kita <Yellow:Misi Penyelidikan Clades>."
  },
  AvgDialog_10130_Content_6 = {
    Text = "Dia tidak akan memaafkanmu, Penjaga yang hanya muncul sekali dalam seratus tahun."
  },
  AvgDialog_10130_Content_7 = {
    Text = "Semoga tugas lapangan @1-mu tidak serumit kursus kalkulus yang sangat bergantung pada <Blue:asisten> ini."
  },
  AvgDialog_10130_Content_8 = {
    Text = "Tidak disangka akan menghadiri pemakamanku sendiri."
  },
  AvgDialog_10130_Content_9 = {
    Text = "Menerima kematian membuat kita tidak lagi takut akan kematian."
  },
  AvgDialog_10131_Content_1 = {
    Text = "Sekarang, aku dan Ogier juga turun ke medan perang."
  },
  AvgDialog_10131_Content_2 = {
    Text = "Saya bisa merasakan melalui Tautan bahwa kondisi kamu dan Ogier belum cukup untuk…"
  },
  AvgDialog_10131_Content_3 = {
    Text = [[
Tidak apa-apa, Penjaga. 
Ksatria ada untuk melindungi semua orang. Ogier pasti bisa bertahan!]]
  },
  AvgDialog_10131_Content_4 = {
    Text = "Tidak perlu khawatir, sekarang ada kamu untuk menstabilkan pikiran. Kami tidak akan kehilangan kendali dan bisa memanfaatkan Aliemus semaksimal mungkin."
  },
  AvgDialog_10131_Content_5 = {
    Text = "Asalkan mengumpulkan cukup Aliemus, saya bisa memulihkan kondisi."
  },
  AvgDialog_10131_Content_6 = {
    Text = [[
Jangan ragu lagi, Penjaga. 
 Apakah kita bisa menembus kepungan selanjutnya, itu tergantung pada komando Anda.]]
  },
  AvgDialog_10131_Content_7 = {
    Text = "Mari aku saksikan—masa depan Mythag, akan bergantung pada komando seperti apa."
  },
  AvgDialog_10132_Content_1 = {
    Text = "Hah, hanya dengan kalian saja, berani berpikir untuk menghancurkan planet ini?"
  },
  AvgDialog_10132_Content_2 = {
    Text = "Masih jauh dari cukup! Apa pun yang tersisa, bawa semuanya!"
  },
  AvgDialog_10133_Content_1 = {
    Text = "Selesai... sudah... kah...?"
  },
  AvgDialog_10133_Content_10 = {
    Text = "Dia mengulurkan tangannya, dengan lembut menyentuh kunci perak di dadamu."
  },
  AvgDialog_10133_Content_11 = {
    Text = "Kunci perak itu berkilau merespons dengan cahaya redup."
  },
  AvgDialog_10133_Content_12 = {
    Text = "Kaulah variabelnya, jawaban dari awal mula sekaligus akhir dari segalanya."
  },
  AvgDialog_10133_Content_13 = {
    Text = "Semoga kau, adalah titik balik dari segalanya……"
  },
  AvgDialog_10133_Content_15 = {
    Text = "Monster putih bersayap enam, wanita dengan ekspresi datar, monster lumpur yang melakukan serangan ke segala arah, bayangan hitam Pembangun yang berteriak melengkung…"
  },
  AvgDialog_10133_Content_16 = {
    Text = "Semuanya melebur menjadi genangan air hitam, lalu menghilang tanpa jejak."
  },
  AvgDialog_10133_Content_17 = {
    Text = "Mengabaikan teriakan Ramona dan Boneka, kamu memegang kunci perak sambil menatap ke arah yang tinggi, menatap ke dalam \"pintu\" di mana \"Tawil\"kembali."
  },
  AvgDialog_10133_Content_18 = {
    Text = "Kamu jelas mengingat wajah yang baru saja kamu lihat. \nBaik itu ekspresi dingin, kontur alis dan mata, maupun lengkungan bibirnya, semuanya sama dengan Ramona——"
  },
  AvgDialog_10133_Content_19 = {
    Text = "——Persis sama."
  },
  AvgDialog_10133_Content_2 = {
    Text = "\"Tavi\" masih berdiri diam di tempat, hanya saja sikapnya tidak lagi setenang sebelumnya."
  },
  AvgDialog_10133_Content_20 = {
    Text = [[
Dua hari kemudian

Pemakaman Kunci]]
  },
  AvgDialog_10133_Content_21 = {
    Text = "…Universitas Mythag adalah pelopor dalam melawan Pelarutan, merupakan Garis pertahanan penting untuk menjaga masa depan umat manusia."
  },
  AvgDialog_10133_Content_22 = {
    Text = "Selama tiga ratus tahun, Universitas Mythag telah membayar harga yang mahal untuk melindungi kehidupan damai manusia dari ancaman Pelarutan."
  },
  AvgDialog_10133_Content_23 = {
    Text = "Pemakaman ini adalah tempat peristirahatan terakhir yang telah kami siapkan sebelumnya, juga merupakan tekad para guru dan siswa Mythag untuk mengorbankan Hidup demi kelangsungan umat manusia."
  },
  AvgDialog_10133_Content_24 = {
    Text = "Pidato terus berlanjut. Czort menutup matanya, menghela napas, dan embusan uap putih yang dikeluarkannya lenyap di antara rintik hujan."
  },
  AvgDialog_10133_Content_25 = {
    Text = "...Saya pikir, di antara banyak angkatan baru, tidak ada yang lebih memahami beban dari kalimat ini daripada kalian."
  },
  AvgDialog_10133_Content_26 = {
    Text = "Selama tiga ratus tahun ini, di Kolam Hitam pernah beberapa kali muncul keberadaan abnormal seperti Perak, Pelarutan, dan tubuh bermutasi lainnya. Namun, mutasi dengan tingkat seperti ini terjadi untuk pertama kalinya."
  },
  AvgDialog_10133_Content_27 = {
    Text = "Banyak orang yang tidak pernah kembali lagi."
  },
  AvgDialog_10133_Content_28 = {
    Text = "Orang yang berbicara adalah Czort, dekan sementara Mythag Institute of Life Sciences. Konon, dia bisa melihat makhluk asing dan merupakan murid kesayangan dekan sebelumnya."
  },
  AvgDialog_10133_Content_29 = {
    Text = "Acara yang terkait dengan pelarutan selalu disertai dengan kecelakaan, kegilaan, dan kematian. Inilah pengalaman yang tak terhindarkan di jalan kita ini."
  },
  AvgDialog_10133_Content_3 = {
    Text = "Sebelum yang lain menyadarinya, Dia tiba-tiba membentangkan sayap perak-Nya dan menerjang ke arah Ramona."
  },
  AvgDialog_10133_Content_30 = {
    Text = [[
Kamu memahami makna di balik kata-kata Czort.
Tidak ada seorang pun di bawah nisan di depanmu.]]
  },
  AvgDialog_10133_Content_31 = {
    Text = "Di atas nisan, cairan hitam mengalir perlahan."
  },
  AvgDialog_10133_Content_33 = {
    Text = "Setelah upacara selesai, Tuan Mulia Dexter mengundangmu ke kantornya."
  },
  AvgDialog_10133_Content_34 = {
    Text = [[
"Nama 'Dexter' sudah tidak asing lagi bagimu, ini adalah nama keluarga Ramona." 
 "Tuan Mulia Dexter" ini adalah profesormu, juga ayah angkat Ramona.]]
  },
  AvgDialog_10133_Content_35 = {
    Text = "Saya melihat bagian ini di laporan, ada sesuatu yang ingin kumohonkan padamu."
  },
  AvgDialog_10133_Content_36 = {
    Text = "Tentang penampilan \"Tawil\"... bisakah kamu merahasiakannya dari Ramona?"
  },
  AvgDialog_10133_Content_37 = {Text = "Kenapa?"},
  AvgDialog_10133_Content_38 = {
    Text = "Bagaimana ya... penyebab di baliknya cukup rumit, sulit untuk dijelaskan dalam waktu singkat."
  },
  AvgDialog_10133_Content_39 = {
    Text = "Namun, cepat atau lambat aku akan memberitahunya. Hanya saja, bukan sekarang."
  },
  AvgDialog_10133_Content_4 = {
    Text = "Waktu seakan-akan membeku"
  },
  AvgDialog_10133_Content_40 = {
    Text = "Ini bukan karena pertimbangan kebutuhan kerahasiaan Mythag, melainkan permintaan seorang ayah yang ingin melindungi putrinya."
  },
  AvgDialog_10133_Content_41 = {
    Text = "Tolong, beri kami sedikit waktu, bisa kan?"
  },
  AvgDialog_10133_Content_42 = {
    Text = "Meskipun kamu ingin mengetahui kebenaran, kamu tetap mengangguk setuju."
  },
  AvgDialog_10133_Content_43 = {
    Text = [[
Terima kasih atas pengertiannya. 
Ngomong-ngomong, baru-baru ini ada kiriman wiski campuran istimewa yang tiba. Aku sudah meminta seseorang diam-diam menyisihkan dua botol untukku.]]
  },
  AvgDialog_10133_Content_44 = {
    Text = "Ambilah, ajak Ramona bersama, rasakan sedikit rasa orang dewasa — anggap saja sebagai upacara penyambutan khusus untukmu, bagaimana?"
  },
  AvgDialog_10133_Content_45 = {
    Text = [[
Mungkin tidak sesuai, Tuan Mulia Dexter. 
Pelarutan tidak akan berhenti menyebar saat kita beristirahat.]]
  },
  AvgDialog_10133_Content_46 = {
    Text = [[
Astaga, William ternyata menemukan tempat ini juga. 
Kalau begitu, aku tidak bisa menyelamatkanmu, Nak.]]
  },
  AvgDialog_10133_Content_47 = {
    Text = "Dokumen sudah dirapikan, kamu bisa bersiap untuk bertugas, Penjaga baru."
  },
  AvgDialog_10133_Content_48 = {
    Text = "Semoga Kunci Perak menuntun jalanmu."
  },
  AvgDialog_10133_Content_5 = {
    Text = "Kamu melesat dengan kecepatan maksimal yang bisa dicapai, dan berhasil berdiri tepat di depan Ramona."
  },
  AvgDialog_10133_Content_6 = {
    Text = "Monster putih itu menatapmu langsung."
  },
  AvgDialog_10133_Content_7 = {
    Text = "Dengan tubuh pucatnya yang tanpa wajah, diam-diam memandangimu."
  },
  AvgDialog_10133_Content_9 = {
    Text = "Yang muncul di hadapanmu adalah wajah seorang wanita dengan ekspresi dingin."
  },
  AvgDialog_10134_Content_1 = {
    Text = "Hei, kau ini, cepatlah, biarkan aku melepaskan <Yellow:\"Pisau Pemberontak\">."
  },
  AvgDialog_10134_Content_2 = {
    Text = [[
Tunggu, Penjaga.
Lepaskan dulu "Serangan", bangkitkan semangat darah Lotan, mampu mengurangi <Yellow:"Pedang Uggal"> konsumsi aritmetika.]]
  },
  AvgDialog_10134_Content_3 = {
    Text = [[
Kombinasi instruksi yang tepat dapat membuat serangan kita lebih efisien. 
 Taktik terletak dalam instruksi, Penjaga. Pikirkan dengan matang.]]
  },
  AvgDialog_10135_Content_1 = {
    Text = "Hati-hati, jangan mendekat! Perisai saya hampir tidak bisa menahan lagi!"
  },
  AvgDialog_10135_Content_10 = {
    Text = "Selain aku, tidak ada orang lain yang bisa melakukannya, kamu tahu."
  },
  AvgDialog_10135_Content_11 = {
    Text = "Ketika memuji saya, mereka bilang \"sekali dalam seratus tahun\", tetapi ketika benar-benar menghadapi krisis, mereka memperlakukan saya seperti hiasan belaka. Ini tidaklah pantas."
  },
  AvgDialog_10135_Content_12 = {
    Text = "Ada risiko yang harus dihadapi."
  },
  AvgDialog_10135_Content_13 = {
    Text = "Kami tidak punya pilihan lain. Terlalu banyak orang di sini yang kehilangan kendali. Jika kita tidak melawan, kita hanya akan ditelan oleh kegilaan."
  },
  AvgDialog_10135_Content_14 = {
    Text = [[
Lagipula, hanya dengan kekuatan kita berdua, mustahil untuk menembus kepungan di sisi Menara Jam. 
 Kita membutuhkan bantuan, membutuhkan kekuatan dari Pembangun untuk bangun.]]
  },
  AvgDialog_10135_Content_15 = {
    Text = "Ramona, bantu aku."
  },
  AvgDialog_10135_Content_16 = {
    Text = "Karena kamu begitu bersikeras... sebagai \"partner\", aku juga tidak memiliki alasan lebih untuk menghentikanmu."
  },
  AvgDialog_10135_Content_17 = {
    Text = "Ramona, siap bertarung kapan saja!"
  },
  AvgDialog_10135_Content_2 = {
    Text = "Hanya terdengar suara \"gong\", pedang kembar Lotan sekali lagi menghancurkan perisai raksasa yang terbentuk dari cairan hitam yang mengental."
  },
  AvgDialog_10135_Content_3 = {
    Text = "Tidak cukup! Tidak cukup! Ayo bangkitkan gelombang besar! Beri aku pertempuran yang memuaskan!"
  },
  AvgDialog_10135_Content_4 = {
    Text = "Pembangun bernama Lotan mengayunkan dua pedangnya, berulang kali menyerang Ogier. Kekuatannya menunjukkan realitas yang kejam — dia sudah sepenuhnya kehilangan kendali."
  },
  AvgDialog_10135_Content_5 = {
    Text = "Melihat situasi ini, kita hanya bisa ..."
  },
  AvgDialog_10135_Content_6 = {
    Text = "Ramona, tolong bantu aku menekan Lotan!"
  },
  AvgDialog_10135_Content_7 = {
    Text = "Apa kamu akan..."
  },
  AvgDialog_10135_Content_8 = {
    Text = "Aku akan menghubunginya!"
  },
  AvgDialog_10135_Content_9 = {
    Text = "Jangan bercanda, kegagalan kontrol Pembangun akan beresonansi dengan frekuensi tinggi melalui Tautan dengan Penyelidik, bahkan untukmu juga ——"
  },
  AvgDialog_10136_Content_1 = {
    Text = "Ini adalah... <Yellow:\"Pedang Pemberontak\"> yang menjadi kebanggaan Lotan, akan melancarkan serangan multi-segmen dalam sekejap!"
  },
  AvgDialog_10136_Content_2 = {
    Text = "Menghadapi serangan ini… gunakan <Yellow:\"Analisis penyerangan\"> untuk menghindari kelemahan utama, ini lebih aman."
  },
  AvgDialog_10137_Content_1 = {
    Text = "Kalian tidak bisa menghentikanku! … Manusia yang tak tahu malu …"
  },
  AvgDialog_10137_Content_2 = {
    Text = "Kamu menyentuh kunci perak yang baru saja diperoleh, getaran lemah terasa, mendorongmu untuk menyelesaikan Resonansi dengan Lotan."
  },
  AvgDialog_10137_Content_4 = {
    Text = "<Shake:Andai tahu akan seperti ini… aku takkan pernah membuat perjanjian dengan kalian…>"
  },
  AvgDialog_10137_Content_5 = {
    Text = "Ramona mendekati Lotan dan mengulurkan tangan kepada Lotan."
  },
  AvgDialog_10137_Content_6 = {
    Text = "Saya tahu, saat Anda dibangkitkan, Mythag pernah berjanji kepada Anda, akan bertarung bersama Anda… bertarung hingga akhir planet ini."
  },
  AvgDialog_10137_Content_7 = {
    Text = "Kami tidak pernah berniat melanggar janji. Selama tiga ratus tahun ini dan tiga ratus tahun yang akan datang, kami akan terus menanggung beban ini."
  },
  AvgDialog_10137_Content_8 = {
    Text = "Lotan, pertempuran yang kamu nantikan dengan penuh semangat sudah di depan mata."
  },
  AvgDialog_10138_Content_1 = {
    Text = "Tetap waspada, itu akan melancarkan serangan. Kerusakan ini bisa menjadi fatal bagi saya saat ini."
  },
  AvgDialog_10138_Content_2 = {
    Text = "Saya percaya kamu akan membuat pilihan yang rasional. Untuk tindakan ronde ini, pilih saja <Yellow:\"Pertahanan\">."
  },
  AvgDialog_10139_Content_1 = {
    Text = [[
Terima kasih, Penjaga Rahasia. Kau menyelamatkanku sekali lagi.
Kalau bukan karena tautan ini, mungkin nyawaku sudah di ujung tanduk sekarang.]]
  },
  AvgDialog_10139_Content_2 = {
    Text = "Sekarang bukan saatnya untuk membicarakan ini——"
  },
  AvgDialog_10139_Content_3 = {
    Text = [[
Selama percakapan, kegelapan misterius telah menyebar di sekitar kalian. 
 Teriakan terus bergema tanpa henti, teman sekelas dari pelajaran kemarin terus berubah menjadi cairan hitam pekat.]]
  },
  AvgDialog_10139_Content_4 = {
    Text = "Saya sudah membagikan <Yellow:Niat> musuh yang terdeteksi oleh Kunci perak melalui Tautan kepadamu, hati-hati, ia akan segera menyerang!"
  },
  AvgDialog_10140_Content_1 = {
    Text = [[
Apakah kamu merasakan Aliemus yang mengalir di tubuhku, Penjaga?
Berkat penekanan Kekuatan roh-mu, jika tidak, itu akan membuatku jatuh ke dalam kegilaan seperti Lotan.]]
  },
  AvgDialog_10140_Content_2 = {
    Text = "Namun sekarang, itu dapat digunakan untuk kepentingan kita."
  },
  AvgDialog_10140_Content_3 = {
    Text = "Lihat ke arah aliran Aliemus… Ya, lihat ke <Blue:pojok kiri atas> perangkat instruksi."
  },
  AvgDialog_10140_Content_4 = {
    Text = [[
Lepaskan mulia, laksanakan <Yellow:"Deduksi mundus"> saya!
Dalam melawan D-lendir, <Yellow: hanya dengan respons yang tepat terhadap agresi, bisa mendapatkan peluang terbesar>.]]
  },
  AvgDialog_10141_Content_1 = {
    Text = "Astaga, Lotan akan melepaskan <Yellow:Muliakan>… hanya dengan instruksi ini…"
  },
  AvgDialog_10141_Content_2 = {
    Text = "Kunci perak terhubung dengan Roh-mu, pemahaman kuatmu, bahkan kenanganmu, dapat membuatnya bergetar dengan Kekuatan yang unik."
  },
  AvgDialog_10141_Content_3 = {
    Text = "Lihat instrumen di <Blue:pojok kiri bawah>! Kekuatan Kunci perak sudah penuh, <Yellow:Geng> sudah siap."
  },
  AvgDialog_10141_Content_4 = {
    Text = "Genggam erat kunci perak, nyanyikan mantra rahasia… lepaskan <Yellow:Geng>, berikan saya lebih banyak ruang taktis!"
  },
  AvgDialog_10142_Content_2 = {
    Text = "Jangan melamun selama upacara penting seperti ini, <Yellow:Penjaga>, giliranmu berikutnya untuk dianugerahi Kunci perak."
  },
  AvgDialog_10142_Content_3 = {
    Text = "Mendirikan nisan kita sendiri sebagai bukti tekad kami untuk <Yellow:melawan pelarutan> dengan hidup kami — ini bukan hanya tradisi Mythag, tetapi juga tanda berakhirnya studi pra-sekolah dan menjadi penyelidik resmi."
  },
  AvgDialog_10142_Content_4 = {
    Text = "Jika sudah siap, ukirlah nama kamu pada batu nisan."
  },
  AvgDialog_116003_Content_1 = {
    Text = "Bersamaan dengan lukisan pohon rumahmu yang hancur, segalanya di sekeliling juga meleleh dalam distorsi."
  },
  AvgDialog_116003_Content_10 = {
    Text = "Tetapi, aku tidak ingin ini hanya menjadi sebuah mimpi."
  },
  AvgDialog_116003_Content_11 = {
    Text = "Aku ingin kembali ke Mythag, ingin bertemu mereka lagi."
  },
  AvgDialog_116003_Content_12 = {
    Text = "……jawaban yang sudah terduga."
  },
  AvgDialog_116003_Content_13 = {
    Text = "Tapi kali ini, setelah kau menunjukkan tekadmu, aku akhirnya bisa merasa tenang."
  },
  AvgDialog_116003_Content_14 = {
    Text = "%player%, tekadmu lebih tangguh dan kuat dari yang aku bayangkan... cukup untuk melawan Dia dan kekacauan serta kegilaan dunia ini."
  },
  AvgDialog_116003_Content_15 = {
    Text = "Kamu menggelengkan kepala, memandang Clementine dalam mimpi indah yang akan sepenuhnya hancur."
  },
  AvgDialog_116003_Content_16 = {
    Text = "Tidak, kamu salah, kehendak seseorang pasti ada batasnya."
  },
  AvgDialog_116003_Content_17 = {
    Text = "Aku bisa bertahan sampai sekarang berkat dukungan dari setiap orang di Mythag."
  },
  AvgDialog_116003_Content_18 = {
    Text = "\"Mereka dari dunia itu\"bersama-sama membangun mimpi indah ini untukmu, dan kamu, dengan tegas ingin menjadikan mimpi indah ini menjadi kenyataan di dunia ini."
  },
  AvgDialog_116003_Content_19 = {
    Text = "Mendengar kata-katamu, melihat wajah seriusmu, clementine tersenyum, menunjukkan senyuman yang santai."
  },
  AvgDialog_116003_Content_2 = {
    Text = "Kau sendiri yang menghancurkan mimpi indahmu."
  },
  AvgDialog_116003_Content_20 = {
    Text = "Ya, kamu masih punya \"mereka\", ada Tawil... dan juga saya."
  },
  AvgDialog_116003_Content_21 = {
    Text = "Benar. Aku sejak awal tidak sendirian."
  },
  AvgDialog_116003_Content_22 = {
    Text = [[
Dalam pemandangan yang terus mencair, terdengar jeritan, itu adalah Tawil yang merespon kata-katamu.
Dia selalu ada.]]
  },
  AvgDialog_116003_Content_23 = {
    Text = "Jadi, sekarang, %player%, mimpimu yang menjadi milikmu benar-benar berakhir."
  },
  AvgDialog_116003_Content_24 = {
    Text = "Sebagai ungkapan terima kasih atas kerjasama perawatan kali ini, aku memberikanmu sebuah hadiah kecil, semoga kau menyukainya."
  },
  AvgDialog_116003_Content_25 = {
    Text = "Bersamaan dengan kata-kata terakhir Clementine, mimpi itu benar-benar hancur—"
  },
  AvgDialog_116003_Content_26 = {
    Text = "Langit hitam tinggi muncul di depanmu, membawa kabut kelabu, dan kekejaman dunia ini."
  },
  AvgDialog_116003_Content_27 = {
    Text = [[
Dan di telapak tanganmu, ada sebuah foto.
Sebuah foto yang diambil di 'Mimpi Indah Palsu', yang seharusnya tidak ada dalam realitas yang kejam.]]
  },
  AvgDialog_116003_Content_28 = {
    Text = "Pantai, voli, perayaan, satu-satunya yang berbeda dari ingatan adalah Ramona."
  },
  AvgDialog_116003_Content_29 = {
    Text = [[
Wajah yang dikenal tersenyum tenang, seolah telah melintasi waktu dan ruang, menatapmu.
Seperti berada di depan matamu.]]
  },
  AvgDialog_116003_Content_3 = {
    Text = "Sejak memutuskan untuk membangun mimpi ini dengan kekuatan mereka, saya tahu hari ini akan tiba."
  },
  AvgDialog_116003_Content_30 = {
    Text = "<Small:ramona……>"
  },
  AvgDialog_116003_Content_31 = {
    Text = "Kamu meletakkan tanganmu di atas foto, perasaan haru dan keraguan membanjiri hatimu."
  },
  AvgDialog_116003_Content_32 = {
    Text = "<Shake: mengapa itu Ramona……>"
  },
  AvgDialog_116003_Content_33 = {
    Text = [[
Pertanyaanmu tidak mendapatkan jawaban.
Di dunia yang dipenuhi kabut abu-abu, hanya matahari hitam yang diam tetap seperti semula.]]
  },
  AvgDialog_116003_Content_34 = {
    Text = "Bagaimanapun juga……"
  },
  AvgDialog_116003_Content_35 = {
    Text = "Kamu meletakkan foto di dadamu, di posisi jantung, dan menutup mata."
  },
  AvgDialog_116003_Content_36 = {
    Text = "Bagaimanapun juga, saya tidak sendirian."
  },
  AvgDialog_116003_Content_37 = {
    Text = "Kemudian, kamu membuka mata, menatap matahari hitam yang tergantung di atas, dan melangkah maju dengan tegas."
  },
  AvgDialog_116003_Content_38 = {
    Text = "Dunia ini masih runtuh, diawasi oleh teror yang tidak dapat dijelaskan, dalam bahaya, tetapi……"
  },
  AvgDialog_116003_Content_39 = {
    Text = "<Big:Kau pada akhirnya akan menemukan cara untuk menyelamatkannya>"
  },
  AvgDialog_116003_Content_4 = {
    Text = "Aku hanya tidak menyangka bahwa itu akan datang secepat ini, dan aku juga tidak menyangka bahwa kamu akan begitu tegas."
  },
  AvgDialog_116003_Content_5 = {
    Text = "Sebenarnya... aku pernah ragu, aku pernah menghindar. Ketika di tepi laut."
  },
  AvgDialog_116003_Content_6 = {
    Text = "Jadi, mengapa tidak melanjutkan tenggelam di sini? Apakah tempat ini tidak cukup indah, tidak cukup bahagia?"
  },
  AvgDialog_116003_Content_7 = {
    Text = "Kamu diam, mengingat gambar pohon rumah sendiri."
  },
  AvgDialog_116003_Content_8 = {
    Text = "Tidak dapat dipungkiri, ini memang sebuah mimpi indah. Tetapi……"
  },
  AvgDialog_116003_Content_9 = {
    Text = "Secara bertahap, pemandangan di kepala kamu bukan lagi lukisan, tetapi benar-benar Mythag, benar-benar doll, Ramona, Lotan dan Ogier."
  },
  AvgDialog_117499_Content_1 = {
    Text = "<Shake:Terlalu banyak……>"
  },
  AvgDialog_117499_Content_2 = {
    Text = "Di bawah langit yang gelap, badai ikan seolah tidak ada habisnya. Kamu melihat sekeliling, di sudut tergantung tangga logam berkarat, dan kamu hati-hati mendaki ke platform lantai dua."
  },
  AvgDialog_117499_Content_3 = {
    Text = "Di sini bisa bersembunyi sejenak."
  },
  AvgDialog_117499_Content_4 = {
    Text = "Sebuah aura misterius disertai dengan suara gesekan yang membuat gigi Anda ngilu menarik perhatian Anda."
  },
  AvgDialog_117499_Content_5 = {
    Text = "Tunggu, itu di sana..."
  },
  AvgDialog_117500_Content_1 = {Text = "Belenggu"},
  AvgDialog_117500_Content_100 = {
    Text = [[
Murphy menggeleng lemah, matanya yang kehilangan cahaya mencari-cari posisimu.
Ia menghadapimu, bibirnya yang pecah akibat kehilangan darah rapat-rapat, memaksakan senyuman pudar.]]
  },
  AvgDialog_117500_Content_101 = {
    Text = "Kau datang... aku pikir... aku tidak mungkin bertemu denganmu..."
  },
  AvgDialog_117500_Content_102 = {
    Text = "Badannya tiba-tiba miring tajam, air asin yang dingin dan pahit mengalir deras ke dalam ruang kabin."
  },
  AvgDialog_117500_Content_103 = {
    Text = "Ada apa ini?!"
  },
  AvgDialog_117500_Content_104 = {
    Text = "Kapal terdampar?"
  },
  AvgDialog_117500_Content_105 = {
    Text = "Tidak mungkin, badan kapal Paladise terlalu dalam, bahkan jika kabin terkena karang dan bocor, tidak mungkin dalam waktu singkat bisa tenggelam sampai ke lantai atas…"
  },
  AvgDialog_117500_Content_106 = {
    Text = "Kecuali jika…"
  },
  AvgDialog_117500_Content_107 = {
    Text = "William berlari ke jendela kapal, pemandangan yang terlihat seperti khayalan yang paling konyol. Kapal Parades mulai tenggelam dengan kecepatan yang luar biasa."
  },
  AvgDialog_117500_Content_108 = {
    Text = "Seolah paus raksasa menarik perahu kecil, ada kekuatan besar yang tidak bisa dilawan, menyeret kapal Paradais ke dasar laut dengan cepat tanpa ampun."
  },
  AvgDialog_117500_Content_109 = {Text = "Aah——"},
  AvgDialog_117500_Content_11 = {
    Text = "Kamu membuka matamu lagi. Lembut, hangat, terasa akrab."
  },
  AvgDialog_117500_Content_110 = {
    Text = "Di bawah goyangan keras, rantai yang menembus telapak tangan Murphy tiba-tiba patah."
  },
  AvgDialog_117500_Content_111 = {
    Text = "Telapak tangan yang lembab dan lengket meraba bagian punggung tanganmu, dia menahan rasa sakit dari luka tembus telapak, perlahan menggenggam tanganmu, saling berpandangan."
  },
  AvgDialog_117500_Content_112 = {
    Text = "Dia ragu-ragu, kata-katanya mengandung aroma karat, tidak tahu apakah itu dari air laut atau darah."
  },
  AvgDialog_117500_Content_113 = {
    Text = "Selamatkan aku……Jika memang kamu, pasti bisa……"
  },
  AvgDialog_117500_Content_114 = {
    Text = "Kata-kata terakhir tenggelam bersama air yang merendam ruang kapal, masuk ke dalam kegelapan."
  },
  AvgDialog_117500_Content_12 = {
    Text = "<Small: Zik, apa kita benar-benar harus menunggu orang ini sampai dia terbangun?>"
  },
  AvgDialog_117500_Content_13 = {
    Text = "<Small: Goliath, tidak boleh meragukan perintah Ibu Dewa.>"
  },
  AvgDialog_117500_Content_14 = {
    Text = "<Small: Lebih tenang, Tuan Goliath, pagi ini, Ibu Dewa memanggil Nyonya Pengajar untuk memberi pengajaran cukup lama...>"
  },
  AvgDialog_117500_Content_15 = {
    Text = "Pertengkaran dengan suara rendah terdengar dari balik tirai."
  },
  AvgDialog_117500_Content_16 = {
    Text = "Hek, hek..."
  },
  AvgDialog_117500_Content_17 = {
    Text = "Kau sudah bangun? Semua orang menunggumu."
  },
  AvgDialog_117500_Content_18 = {
    Text = "<faros> mulai menggulung tirai."
  },
  AvgDialog_117500_Content_19 = {
    Text = "Apakah ini…… saya diselamatkan lagi?"
  },
  AvgDialog_117500_Content_2 = {
    Text = "……Laba-laba?"
  },
  AvgDialog_117500_Content_20 = {
    Text = "Orang yang selamat dari malapetaka. Kami tidak memiliki kewajiban untuk menjawab semua pertanyaanmu."
  },
  AvgDialog_117500_Content_21 = {
    Text = "Sesuai perintah ibu dewa, Pelaut telah menunggu kebangkitan Anda untuk waktu yang lama."
  },
  AvgDialog_117500_Content_22 = {
    Text = "Ini adalah jus lemon yang disiapkan oleh ibu dewa untuk saya. Minum dengan penuh rasa syukur, manusia."
  },
  AvgDialog_117500_Content_23 = {
    Text = "Karena Dia sudah selamat, maka saya akan kembali ke posisi pemandu. Kerajaan Dewa sedang memanggil saya."
  },
  AvgDialog_117500_Content_25 = {
    Text = "……………"
  },
  AvgDialog_117500_Content_26 = {
    Text = "Apakah ini terjadi di dunia nyata, ataukah ini mimpi buruk saat saya tenggelam di dalam air..."
  },
  AvgDialog_117500_Content_27 = {
    Text = "(Harus mencari cara untuk memverifikasi.)"
  },
  AvgDialog_117500_Content_28 = {
    Text = "Jika saya tidak salah ingat, orang terakhir yang saya lihat…"
  },
  AvgDialog_117500_Content_29 = {
    Text = "Kau menginjakkan kaki di atas dek."
  },
  AvgDialog_117500_Content_3 = {
    Text = "Seekor laba-laba kecil berwarna ungu gelap menatapmu. Ketika melihatmu bangun, ia mengangkat kakinya dan menyapamu."
  },
  AvgDialog_117500_Content_30 = {
    Text = "<Shake:Halo——Kak William——>"
  },
  AvgDialog_117500_Content_31 = {
    Text = "<Shake:Jangan bersembunyi——Saya tahu Anda di sini——>"
  },
  AvgDialog_117500_Content_32 = {
    Text = "Di dek hanya terdengar suara gelombang tenang, teriakanmu menyebar dalam kabut pagi."
  },
  AvgDialog_117500_Content_33 = {
    Text = "(Ah, ternyata hanya mimpiku saja...)"
  },
  AvgDialog_117500_Content_34 = {Text = "Uwaa!"},
  AvgDialog_117500_Content_35 = {
    Text = "Pintu tersembunyi di dek di bawah kakimu tiba-tiba terbuka, kamu terjatuh ke dalam kegelapan dengan suara \"dou\"."
  },
  AvgDialog_117500_Content_36 = {
    Text = "Sekumpulan jerami mengurangi dampak dari jatuhmu."
  },
  AvgDialog_117500_Content_37 = {
    Text = "Sudah lama tidak bertemu, Penjaga."
  },
  AvgDialog_117500_Content_38 = {
    Text = "Kamu mengenalku... kamu adalah William senior dari dunia yang dulu..."
  },
  AvgDialog_117500_Content_39 = {
    Text = "William mengabaikan nada terkejutmu dan justru terlihat murung."
  },
  AvgDialog_117500_Content_4 = {
    Text = "Tumpukan kain tipis dan kain beludru di atas dek berkarat. Seorang wanita yang memegang pemintal menatapmu dengan tajam."
  },
  AvgDialog_117500_Content_40 = {
    Text = "Saya tidak ingat pernah mengajarkan Anda cara bertindak sekencang itu di markas musuh di Miryag."
  },
  AvgDialog_117500_Content_41 = {
    Text = "Bahkan Dekan czort yang terkenal karena sikapnya yang sembrono mungkin tidak akan mendukung pilihanmu."
  },
  AvgDialog_117500_Content_42 = {
    Text = "Aroma pohon cedar yang familiar, postur yang tegak, nada yang tegas."
  },
  AvgDialog_117500_Content_43 = {
    Text = "Senior William……"
  },
  AvgDialog_117500_Content_44 = {
    Text = "Sebelum menyelesaikan masalah penting, sebenarnya aku tidak berniat muncul di depanmu."
  },
  AvgDialog_117500_Content_45 = {
    Text = "Tapi kecerobohanmu memaksaku untuk mengubah strategi."
  },
  AvgDialog_117500_Content_46 = {
    Text = "Tahukah kamu bahwa aku selalu mengejarmu?"
  },
  AvgDialog_117500_Content_47 = {
    Text = "William tidak menjawab pertanyaan itu, hanya memberimu tatapan tajam yang seperti berkata \"Apakah kau menganggapku bodoh?\""
  },
  AvgDialog_117500_Content_48 = {
    Text = "Kami sudah berada di kapal yang sama, dan tidak mungkin untuk menghindari. Lebih baik saya langsung menjelaskan situasinya agar tidak ada halangan yang tidak perlu."
  },
  AvgDialog_117500_Content_49 = {
    Text = "Sebelum itu, bisakah Anda berbagi informasi yang Anda kuasai?"
  },
  AvgDialog_117500_Content_5 = {
    Text = "Kali ini, dia tidak menghela napas, tidak berbicara, hanya diam."
  },
  AvgDialog_117500_Content_51 = {
    Text = "……………"
  },
  AvgDialog_117500_Content_52 = {
    Text = "Dari dijadikan tempurung otak oleh doll: inferno, terjebak di lembaga penanganan Roh oleh Clementine, hingga pemandangan kota kuburan, dan terakhir di kapal Paradis mengalami \"Mimpi Buruk\"."
  },
  AvgDialog_117500_Content_53 = {
    Text = "Kau akan menceritakan semua pengalamanmu, William mendengarkan dengan serius, sesekali mengangguk sebagai tanda bahwa dia tetap fokus."
  },
  AvgDialog_117500_Content_54 = {
    Text = "Ketika menceritakan tentang William di masa kecil yang pernah kau lihat, kau ragu sejenak, tetapi William hanya mengangkat tangan memberiisyarat untuk melanjutkan."
  },
  AvgDialog_117500_Content_55 = {
    Text = "Informasi yang kau berikan sangat berguna."
  },
  AvgDialog_117500_Content_56 = {
    Text = "William senior, bisakah kamu sekarang memberi tahu saya, apa yang sebenarnya kamu kejar?"
  },
  AvgDialog_117500_Content_57 = {
    Text = "William berpikir sejenak."
  },
  AvgDialog_117500_Content_58 = {
    Text = "Biarkan aku berpikir tentang dari mana harus memulai."
  },
  AvgDialog_117500_Content_59 = {
    Text = "Sejak terjebak di dunia ini, aku terus mengeksplorasi dua pertanyaan: mengapa aku terjebak di sini, dan bagaimana caranya kembali ke dunia asal?"
  },
  AvgDialog_117500_Content_6 = {
    Text = "Kenapa, aku jelas ingat aku diserang oleh tak terhitung banyaknya Pelaut, dan kemudian……"
  },
  AvgDialog_117500_Content_60 = {
    Text = "William dengan serius mengeluarkan Kunci perak yang disimpannya di dada, tatapannya mengungkapkan rasa nostalgia."
  },
  AvgDialog_117500_Content_61 = {
    Text = "Kunci perak ini adalah yang saya kembalikan sendiri, berasal dari rekan saya yang dulu, Fengol... banyak yang bilang saya adalah penyelidik paling legendaris di Mythag, tetapi menurut saya itu hanya karena dia meninggal terlalu muda."
  },
  AvgDialog_117500_Content_62 = {
    Text = "Hingga terjatuh ke dimensi ini, aku baru mengerti, ia hanya lebih awal memahami inti dunia, dan berperang sebagai perintis di garis depan melawan Pelarutan."
  },
  AvgDialog_117500_Content_63 = {
    Text = "Dia telah melacak rahasia yang menghubungkan dua dunia, dan meninggalkan petunjuk penting — satu patung gading."
  },
  AvgDialog_117500_Content_64 = {
    Text = "Seperti biasa, dia selalu lebih dulu dari saya."
  },
  AvgDialog_117500_Content_65 = {
    Text = "William terlihat murung, menggelengkan kepala dan mengembalikan Kunci perak ke dalam pelukannya."
  },
  AvgDialog_117500_Content_66 = {
    Text = "……Apakah kamu pernah melihat patung gading di tangan Myriam atau Murphy?"
  },
  AvgDialog_117500_Content_67 = {
    Text = "Kau mengangguk."
  },
  AvgDialog_117500_Content_68 = {
    Text = "Jika semuanya berkembang seperti terakhir kali, di dek di atas kepala kita, Murphy sedang mengadakan ritual dengan patung ini."
  },
  AvgDialog_117500_Content_69 = {
    Text = "Patung gading itu tampaknya memiliki hubungan yang rumit dengan hakikat dunia ini."
  },
  AvgDialog_117500_Content_7 = {
    Text = "Kau merasakan tubuhmu. Meskipun rasa sakit ilusi masih ada, tidak ada bekas luka yang tersisa di permukaan tubuhmu, pertarungan besar yang kau alami sebelum pingsan sepertinya tidak pernah terjadi."
  },
  AvgDialog_117500_Content_70 = {
    Text = "Jadi, untuk kembali, kita harus memperoleh patung gading dan melakukan analisis serta penelitian terhadapnya."
  },
  AvgDialog_117500_Content_71 = {
    Text = "Setelah upacara berakhir, patung gading seharusnya kembali ke kamar Murphy..."
  },
  AvgDialog_117500_Content_72 = {
    Text = "Di dalamnya sangat tenang, seharusnya tidak ada orang di dalamnya……"
  },
  AvgDialog_117500_Content_73 = {
    Text = "Lebih baik berhati-hati, kita harus menghindari konflik yang tidak perlu."
  },
  AvgDialog_117500_Content_74 = {
    Text = "Baiklah, mari kita lihat sedikit."
  },
  AvgDialog_117500_Content_75 = {
    Text = "Kau dengan hati-hati mendorong pintu sedikit."
  },
  AvgDialog_117500_Content_77 = {
    Text = "Aliran udara yang tercampur bau aneh mengalir ke hidungmu, dan kamu menyadari bahwa kamu secara tidak sadar mengambil napas dalam-dalam."
  },
  AvgDialog_117500_Content_78 = {Text = "Ada apa?"},
  AvgDialog_117500_Content_79 = {Text = "Suara."},
  AvgDialog_117500_Content_8 = {
    Text = "Apakah itu... mimpi buruk?"
  },
  AvgDialog_117500_Content_80 = {
    Text = "Akhirnya suara muncul di dalam ruangan yang tenang."
  },
  AvgDialog_117500_Content_81 = {
    Text = "Suara tetesan air."
  },
  AvgDialog_117500_Content_82 = {
    Text = "Tik-tik, suara air mengalir ke genangan kecil yang baru terbentuk."
  },
  AvgDialog_117500_Content_83 = {
    Text = [[
Delapan tali besi kencang menjalar dari anggota tubuh Murphy, mengikatnya dengan erat.
Rongga dadanya dilubangi dengan lubang darah besar.]]
  },
  AvgDialog_117500_Content_84 = {
    Text = "Darah mengalir dari luka yang mencolok, menetes ke dalam genangan darah yang perlahan terbentuk, yang merupakan sumber suara detakan yang bergema di telinga kamu."
  },
  AvgDialog_117500_Content_85 = {
    Text = "Murphy......!"
  },
  AvgDialog_117500_Content_86 = {
    Text = "Kau datang terlambat."
  },
  AvgDialog_117500_Content_87 = {
    Text = "Jantung seolah-olah dicengkeram oleh tangan tak terlihat, rasa sakit yang familiar dan menyakitkan itu menyertai serpihan ingatan menusuk dengan keras."
  },
  AvgDialog_117500_Content_88 = {
    Text = "Cahaya yang terlalu menyilaukan menusuk mata, membuat air mata mengalir tanpa bisa dikendalikan."
  },
  AvgDialog_117500_Content_89 = {
    Text = "Cairan keruh mengalir habis, dan mata akhirnya bisa fokus kembali pada gadis itu."
  },
  AvgDialog_117500_Content_9 = {
    Text = "Wanita itu mengangguk tanpa suara, sosoknya menghilang dalam kabut yang samar."
  },
  AvgDialog_117500_Content_90 = {
    Text = "Mata pisaunya menembus dalam ke arah dada, gadis yang mandi di bawah cahaya bulan membuka matanya."
  },
  AvgDialog_117500_Content_91 = {
    Text = "Bulan purnama yang melambangkan kematian sudah sangat dekat, namun di wajah muda itu tidak terlihat sedikit pun rasa takut."
  },
  AvgDialog_117500_Content_92 = {
    Text = "Aku berhasil... aku berhasil."
  },
  AvgDialog_117500_Content_93 = {
    Text = "Aku... menembus-Nya... Dia tidak akan dilahirkan lagi..."
  },
  AvgDialog_117500_Content_94 = {
    Text = "Dengan cara ini..."
  },
  AvgDialog_117500_Content_95 = {
    Text = "Tangan yang erat memegang gagang pisau terkulai lemas, cairan berwarna merah segar, kental, dan pekat mengalir deras dari mulut luka, mengalir melewati celah jari-jari dan masuk ke laut."
  },
  AvgDialog_117500_Content_96 = {
    Text = "Hek, hek..."
  },
  AvgDialog_117500_Content_97 = {
    Text = "Kau adalah... orang itu dalam mimpi..."
  },
  AvgDialog_117500_Content_98 = {
    Text = "Jangan bicara dulu! Aku akan membantumu…"
  },
  AvgDialog_117500_Content_99 = {
    Text = "Kau dengan cemas mencoba tanpa hasil, rantai bergetar nyaring akibat rasa sakit Murphy."
  },
  AvgDialog_117501_Content_10 = {
    Text = "Mengapa Ibu Dewi bertanya seperti itu?"
  },
  AvgDialog_117501_Content_11 = {
    Text = "Tadi malam, saya bermimpi."
  },
  AvgDialog_117501_Content_12 = {
    Text = "Di dalam mimpi, aku menggunakan belati ritual itu…"
  },
  AvgDialog_117501_Content_13 = {
    Text = [[
Dia mengangkat tangannya dan menunjuk belati yang selalu dibawa Miariam.
Panjang mata pisaunya berkilau dengan cahaya mempesona, memancarkan cahaya yang angker seperti racun.]]
  },
  AvgDialog_117501_Content_14 = {
    Text = "Menembus dadanya sendiri."
  },
  AvgDialog_117501_Content_15 = {
    Text = "\"Dia tidak akan dilahirkan......\""
  },
  AvgDialog_117501_Content_16 = {
    Text = "Murphy bergumam, ujung jarinya perlahan menggaruk bekas luka yang penuh darah di dadanya."
  },
  AvgDialog_117501_Content_17 = {
    Text = "Ini adalah mimpi buruk yang tidak nyata."
  },
  AvgDialog_117501_Content_18 = {
    Text = "Miryam maju dan berlutut di depan lutut murphy, telapak tangannya menyentuh punggung tangannya sebagai tanda penghiburan."
  },
  AvgDialog_117501_Content_19 = {
    Text = "Tenangkanlah, hasrat abadi dari Pelaut telah tercapai, Dia ada, Dia telah turun di dunia ini."
  },
  AvgDialog_117501_Content_2 = {
    Text = "bisikan mimpi"
  },
  AvgDialog_117501_Content_20 = {
    Text = "Dan kamu dan aku akan mencapai kerajaan dewa yang abadi, berbagi kemuliaan ilahi di hadapan takhta-Nya."
  },
  AvgDialog_117501_Content_21 = {
    Text = "Kata-katanya seperti doa di depan Altar, penuh dengan rasa hormat dan devosi."
  },
  AvgDialog_117501_Content_22 = {
    Text = "Jika kita tidak dapat mencapai Ranah dewa? Saya maksud, jika…"
  },
  AvgDialog_117501_Content_23 = {
    Text = "Miryam segera memotong pertanyaan ragu murphy."
  },
  AvgDialog_117501_Content_24 = {
    Text = [[
Dalam ramalan Raja Dewa tidak ada hal-hal semacam ini yang disampaikan.
Momen selaras berikutnya akan terjadi besok, darah-Nya pasti akan membimbing kami menuju Tanah yang Dijanjikan.]]
  },
  AvgDialog_117501_Content_25 = {
    Text = "Murphy mengernyit."
  },
  AvgDialog_117501_Content_26 = {
    Text = "Saya perlu beristirahat, Miryam, kau juga pulang dan istirahatlah."
  },
  AvgDialog_117501_Content_27 = {
    Text = "Saya akan berdoa untuk Ibu Dewa sampai fajar, memohon agar Anda tidur nyenyak semalam."
  },
  AvgDialog_117501_Content_28 = {
    Text = "Murphy tidak menjawab, tatapan dalam mengikuti sosok Miryam hingga suara pintu yang tertutup terdengar."
  },
  AvgDialog_117501_Content_29 = {
    Text = "Dia berbalik dengan lesu ke arah altar dalam bayangan, menutup mata dan berdoa."
  },
  AvgDialog_117501_Content_3 = {
    Text = "Dewa Ibu yang mulia, kamu sudah di sini menatap lampu lagi."
  },
  AvgDialog_117501_Content_30 = {
    Text = "Besok, hari yang Selaras…"
  },
  AvgDialog_117501_Content_31 = {
    Text = [[
Lambang aneh di altar tidak memberinya respon sedikit pun, diam seperti fosil di bawah lapisan es.
Murphy tampak terbangun dengan tekad.]]
  },
  AvgDialog_117501_Content_32 = {
    Text = "Untuk kelanjutan mimpi ini……"
  },
  AvgDialog_117501_Content_33 = {
    Text = "Dia mengulurkan lengan rampingnya yang tertutup oleh kain hitam yang tebal, mengangkat belati ritualnya —"
  },
  AvgDialog_117501_Content_34 = {
    Text = "Di bawah bayangan nyala lilin, bayangan pisaunya tertancap keras ke dalam pelukan yang tertidur di altar."
  },
  AvgDialog_117501_Content_35 = {
    Text = [[
Dengan suara "_puff_" yang lengket, terdengar suara daging kental yang ditembus.
Cairan hitam pekat perlahan menyebar, membasahi jubah beludru dengan simbol Pelaut yang mencolok.]]
  },
  AvgDialog_117501_Content_36 = {
    Text = "Sekali lagi malam akan segera turun..."
  },
  AvgDialog_117501_Content_37 = {
    Text = "Dia menghela napas lega, menutup matanya, tetapi yang menyerangnya bukanlah kegelapan yang tak berujung, melainkan mimpi kemarin."
  },
  AvgDialog_117501_Content_39 = {
    Text = "(Momen saat ditusuk di dada, orang yang muncul di sampingku...)"
  },
  AvgDialog_117501_Content_4 = {
    Text = "Istirahatlah lebih awal, besok adalah hari ketika Selaras, Anda masih perlu menunjukkan jalan kepada Pelaut dengan darah suci Anda."
  },
  AvgDialog_117501_Content_40 = {
    Text = "(Sepertinya tidak pernah melihatnya, tapi ada sedikit kerinduan...)"
  },
  AvgDialog_117501_Content_41 = {
    Text = "……Laba-laba?"
  },
  AvgDialog_117501_Content_42 = {
    Text = "Seekor laba-laba kecil berwarna ungu gelap di tiang kapal menatapmu. Ketika melihatmu bangun, ia mengangkat kakinya dan menyapamu."
  },
  AvgDialog_117501_Content_43 = {
    Text = "Di dalam mimpi, sepertinya aku mendengar suara lagu…"
  },
  AvgDialog_117501_Content_44 = {
    Text = "Suara lembut yang seolah-olah nyanyian nimfa bergetar, terus berputar di telingamu."
  },
  AvgDialog_117501_Content_45 = {
    Text = "Anak-anak tragis, pola takdir telah dijalin, kalian akan menempuh perjalanan yang sudah ditentukan."
  },
  AvgDialog_117501_Content_46 = {
    Text = "Dan kamu, tamu dari dimensi lain——"
  },
  AvgDialog_117501_Content_47 = {
    Text = "Saat bintang Selaras kembali datang, mohon buatlah akhir dari siklus tragis ini."
  },
  AvgDialog_117501_Content_48 = {
    Text = "Dengan sebuah keluhan panjang, ilusi wanita itu menghilang."
  },
  AvgDialog_117501_Content_49 = {Text = "?!"},
  AvgDialog_117501_Content_5 = {
    Text = "Murphy menatap tajam nyala api yang melompat dari lampu, kain hitam bergetar mengikuti gerakannya, menciptakan ilusi gaun di dinding kapal."
  },
  AvgDialog_117501_Content_50 = {
    Text = "Setelah rasa ketakutan sekejap menghilang, baru kau menenangkan diri dan mengamati lingkungan sekitarmu."
  },
  AvgDialog_117501_Content_51 = {
    Text = "Apakah ini…… di mana saya?"
  },
  AvgDialog_117501_Content_52 = {
    Text = "Kasur yang lembut. Ruang yang aman tertutup oleh kain hitam. Aroma sage dan dupa yang samar mengapung di udara."
  },
  AvgDialog_117501_Content_53 = {
    Text = "Sebelum ini… aku…"
  },
  AvgDialog_117501_Content_54 = {
    Text = "Doll! Dapatkah kamu menerima sinyal? Doll?"
  },
  AvgDialog_117501_Content_55 = {
    Text = "Jangan berteriak, kamu mengganggu penerima gelombang suara saya."
  },
  AvgDialog_117501_Content_56 = {
    Text = "Saya mengejar kapal yang ditumpangi William yang diceritakan oleh nelayan! Namun kapal itu masuk ke dalam badai!"
  },
  AvgDialog_117501_Content_57 = {
    Text = "Kalimat berikutnya adalah…"
  },
  AvgDialog_117501_Content_58 = {
    Text = "Saya akan mengejarnya!"
  },
  AvgDialog_117501_Content_59 = {
    Text = "Dengan perahu nelayan kecilmu ini? Melawan jurang laut di Kepulauan Bermuda? Apa kamu tidak takut terbalik di dalamnya?"
  },
  AvgDialog_117501_Content_6 = {
    Text = "Miryam, apakah kau pernah bermimpi?"
  },
  AvgDialog_117501_Content_60 = {
    Text = "Tidak boleh kehilangan jejak lagi, ini adalah satu-satunya informasi yang nyata dan efektif yang kita dapatkan dalam beberapa bulan!"
  },
  AvgDialog_117501_Content_61 = {
    Text = "Semoga Kunci perak membimbing jalan di depan!"
  },
  AvgDialog_117501_Content_62 = {
    Text = "Tidak ada suara \"semoga Kunci perak memandu kita\" dari seberang komunikasi, digantikan oleh suara arus listrik yang terputus dari tautan."
  },
  AvgDialog_117501_Content_63 = {
    Text = "Yang menyambutmu adalah ombak besar yang menggelegar dan gelap tanpa akhir yang segera mengikutinya——"
  },
  AvgDialog_117501_Content_64 = {
    Text = "Tiga bulan lalu, setelah mengejar berita tentang pria berambut emas yang misterius di pelabuhan Innsmouth, Anda mengikuti jejak William."
  },
  AvgDialog_117501_Content_65 = {
    Text = "Belakangan ini, kamu akhirnya melihat bendera kapal yang digambarkan oleh para nelayan di permukaan laut, tetapi arahmu direnggut oleh badai yang tiba-tiba."
  },
  AvgDialog_117501_Content_66 = {
    Text = "Ketika membuka mata lagi, pemandangan di depan adalah apa yang akan kau lihat."
  },
  AvgDialog_117501_Content_67 = {
    Text = "Kau sudah bangun? Semua orang menunggumu."
  },
  AvgDialog_117501_Content_68 = {
    Text = "Tirai hitam diangkat dengan ringan, suara wanita yang familiar namun asing datang bersamanya."
  },
  AvgDialog_117501_Content_69 = {
    Text = "Semua orang...? Siapa...?"
  },
  AvgDialog_117501_Content_7 = {
    Text = "Tentu saja. Di antara ribuan mimpi, yang besar Lemuria muncul dari lautan dalam, terulang kembali di bawah sinar matahari."
  },
  AvgDialog_117501_Content_70 = {
    Text = "Empat wajah akrab secara aneh mengelilingi di depan ranjangmu."
  },
  AvgDialog_117501_Content_71 = {
    Text = "Sesuai perintah ibu dewa, Pelaut telah menunggu kebangkitan Anda untuk waktu yang lama. Ayo, minum obat baik yang disiapkan oleh ibu dewa ini."
  },
  AvgDialog_117501_Content_72 = {
    Text = "Caecus membawa sebuah gelas kaca yang diukir dengan indah, cairan kuning keruh yang mengganggu."
  },
  AvgDialog_117501_Content_73 = {
    Text = "Di dalam sini adalah……?"
  },
  AvgDialog_117501_Content_74 = {
    Text = "Orang yang selamat dari malapetaka, jangan bertanya-tanya lagi."
  },
  AvgDialog_117501_Content_75 = {
    Text = "Ini diperintahkan oleh ibu dewa. Minumlah dengan rasa syukur, manusia."
  },
  AvgDialog_117501_Content_76 = {
    Text = "Di bawah tatapan banyak orang, kamu dengan hati-hati menghirup sedikit."
  },
  AvgDialog_117501_Content_77 = {
    Text = "Puff——sangat asam——! Apakah ini jus lemon murni?!"
  },
  AvgDialog_117501_Content_78 = {
    Text = "Kamu terkejut dan duduk, alismu berkerut."
  },
  AvgDialog_117501_Content_79 = {
    Text = "Karena Dia sudah selamat, saya ingin pergi ke dek untuk menerima indra. Kerajaan Dewa sedang memanggil saya."
  },
  AvgDialog_117501_Content_8 = {
    Text = "Cahaya abadi tersebar di lautan jauh， menunjukkan arah baru untuk kita."
  },
  AvgDialog_117501_Content_80 = {
    Text = "(Dunia ini dan aku, pasti ada yang sudah gila...)"
  },
  AvgDialog_117501_Content_81 = {
    Text = "Sekadar bertanya… di mana ini?…"
  },
  AvgDialog_117501_Content_82 = {
    Text = "Kapal pesiar Parades, satu-satunya dan yang terpenting \"taman bermain\" di laut bagi Pelaut."
  },
  AvgDialog_117501_Content_83 = {
    Text = "Kami sedang berlayar menuju Ranah dewa yang abadi, Lemuria."
  },
  AvgDialog_117501_Content_9 = {
    Text = "Miryam memberi jawaban hampir secara intuitif, diiringi dengan pertanyaan yang tidak dapat disembunyikan tanda kebingungan."
  },
  AvgDialog_117502_Content_10 = {
    Text = "Dalam cahaya terakhir sebelum pandangan terbenam dalam kegelapan mutlak, kamu melihat sebuah sosok melintas."
  },
  AvgDialog_117502_Content_11 = {
    Text = "Sekelompok rambut emas yang cerah, lengan mekanik yang rumit berkilau dengan cahaya logam."
  },
  AvgDialog_117502_Content_12 = {
    Text = "William… senior…"
  },
  AvgDialog_117502_Content_2 = {
    Text = "……………"
  },
  AvgDialog_117502_Content_3 = {
    Text = "Seberapa lama kau telah bertarung di antara ikan-ikan yang berbau amis?"
  },
  AvgDialog_117502_Content_4 = {
    Text = "Satu jam? Satu hari? Atau waktu yang mungkin tidak dapat dihitung?"
  },
  AvgDialog_117502_Content_5 = {
    Text = "(Upacara adalah waktu bagi Pelaut untuk berkumpul, memasuki saat ini... adalah keputusan impulsif yang salah.)"
  },
  AvgDialog_117502_Content_6 = {
    Text = "Sentuhan licin telah menjadi kebiasaan hingga mati rasa, bau amis dari lendir tidak lagi mengganggu rongga hidung yang sesak."
  },
  AvgDialog_117502_Content_7 = {
    Text = "(Jika bisa datang lagi... Sayang sekali...)"
  },
  AvgDialog_117502_Content_8 = {
    Text = [[
Kamu berusaha mengangkat kunci perak, inti yang bersinar terang dari masa lalu mulai bergetar.
Kamu hampir terjatuh dan meludahkan darah.]]
  },
  AvgDialog_117502_Content_9 = {
    Text = "(Sudah... sampai batas... maaf... tidak bisa melarikan diri...)"
  },
  AvgDialog_117503_Content_1 = {
    Text = "Seorang Pelancong"
  },
  AvgDialog_117503_Content_10 = {
    Text = "Jantung tiba-tiba mengetuk irama gelisah, Anda secara naluriah membuka mulut, hanya karena Anda sudah tahu siapa pemilik wajah di balik kain hitam itu."
  },
  AvgDialog_117503_Content_100 = {
    Text = "Sekawan ikan menembus batas permukaan, bergelut, kejang-kejang dalam udara lengket, dengan bau amis dan lengket menghujani Anda bertubi-tubi."
  },
  AvgDialog_117503_Content_101 = {
    Text = "Disertai suara aneh yang membuat kepala terasa merinding, tubuh setengah busuk melompat tanpa tujuan di atas dek, dan lendir busuk yang tersisa mengeluarkan bau menyengat yang menyengat."
  },
  AvgDialog_117503_Content_102 = {
    Text = "Tentakel tipis dan rapuh merobek perutnya yang pucat, dan tiba-tiba merayap menuju kamu——"
  },
  AvgDialog_117503_Content_11 = {
    Text = "<Shake: Murphy...>"
  },
  AvgDialog_117503_Content_12 = {
    Text = "Di antara kepulan, kulitnya yang pucat tampak, putih seperti debu yang hampir hancur."
  },
  AvgDialog_117503_Content_13 = {
    Text = "Berani sekali! Bagaimana berani kamu menyebut nama Ibu Dewi!"
  },
  AvgDialog_117503_Content_14 = {
    Text = "Tidak apa-apa, Caecus, {Male=dia,Female=dia} adalah tamu di surga, dan akan bergabung dalam perjalanan besar kami."
  },
  AvgDialog_117503_Content_15 = {
    Text = "Lima pasang mata memandang Anda dengan tajam, membuat semua kata yang ingin Anda ucapkan tertahan di perut Anda."
  },
  AvgDialog_117503_Content_16 = {
    Text = "……Murphy, bolehkah aku bicara sendirian denganmu?"
  },
  AvgDialog_117503_Content_18 = {
    Text = "……………"
  },
  AvgDialog_117503_Content_19 = {Text = "Murphy…"},
  AvgDialog_117503_Content_2 = {
    Text = "Gadis yang berbicara denganmu duduk diam di ujung tempat tidurmu, dengan kain hitam berkerut yang samar menutupi wajahnya."
  },
  AvgDialog_117503_Content_20 = {
    Text = "Jika kamu belum mengorganisir bahasa dengan baik, saya punya satu pertanyaan yang ingin saya tanyakan."
  },
  AvgDialog_117503_Content_21 = {
    Text = "Mengapa kamu datang ke Paradise? Sejauh yang aku tahu, untuk mendekati Paradise, seseorang harus masuk ke dalam badai terlebih dahulu."
  },
  AvgDialog_117503_Content_22 = {
    Text = "Bersedia mengambil risiko seperti ini, pasti ada sesuatu yang kau inginkan."
  },
  AvgDialog_117503_Content_23 = {
    Text = "Dengan kata lain... apakah kalian pernah melihat seorang pria yang setengah kepala lebih tinggi dariku, dengan rambut emas?"
  },
  AvgDialog_117503_Content_24 = {
    Text = "Murphy melirikmu sebentar, mengeluarkan suara ejekan."
  },
  AvgDialog_117503_Content_25 = {
    Text = "Melihat tinggi badanmu, kemungkinan ada banyak orang seperti itu di antara awak kapal."
  },
  AvgDialog_117503_Content_26 = {
    Text = "Tidak, kamu hanya perlu melihatnya sekilas…… dia memiliki Lengan mekanik satu, tampan, dengan aroma harum cedar yang lembut."
  },
  AvgDialog_117503_Content_27 = {
    Text = "……Nah, saya bisa memastikan bahwa saya tidak pernah melihatnya.\nPara awak kapal selalu mengeluarkan bau amis yang kotor dan menyengat."
  },
  AvgDialog_117503_Content_28 = {
    Text = "Jadi, Murphy, ada satu hal penting lagi."
  },
  AvgDialog_117503_Content_29 = {Text = "Hm?"},
  AvgDialog_117503_Content_3 = {
    Text = "(Suara yang sangat familiar... Siapa ini...)"
  },
  AvgDialog_117503_Content_30 = {
    Text = "Apakah kamu akan melarikan diri bersamaku?"
  },
  AvgDialog_117503_Content_31 = {Text = "Hah?!"},
  AvgDialog_117503_Content_32 = {
    Text = [[
Murphy tersentak oleh kata-katamu, lalu kemarahan terlihat di pipinya.
Ia berusaha menahan emosinya, mengeluarkan tawa mengejek.]]
  },
  AvgDialog_117503_Content_33 = {
    Text = "Melarikan diri, maksudnya apa?"
  },
  AvgDialog_117503_Content_34 = {
    Text = "Secara harfiah, kita harus mencari cara untuk meninggalkan kapal ini dan terlepas dari kekuasaan Pelaut."
  },
  AvgDialog_117503_Content_35 = {
    Text = "Kenapa aku harus melarikan diri bersamamu?"
  },
  AvgDialog_117503_Content_36 = {
    Text = "Karena kau tidak suka kehidupan di sini."
  },
  AvgDialog_117503_Content_37 = {
    Text = "Kamu tidak menyukai doktrin yang diciptakan Miryam, tidak suka sembahyang palsu para pengikutnya, dan tidak tertarik pada kemewahan yang ilusif itu."
  },
  AvgDialog_117503_Content_38 = {
    Text = "Kepala Murphy perlahan menunduk."
  },
  AvgDialog_117503_Content_39 = {
    Text = "Melihat dia terdiam, kamu segera menambah percikan api."
  },
  AvgDialog_117503_Content_4 = {
    Text = "Kau dengan lengan yang nyeri memaksakan diri menyangga tubuh bagian atas, mencoba mengendalikan situasi lingkungan saat ini."
  },
  AvgDialog_117503_Content_40 = {
    Text = "Di dunia lain, aku telah melihatmu, aku mengenalmu, kita telah melalui keadaan yang serupa, dan akhirnya, kau juga berhasil melarikan diri dari sarang iblis..."
  },
  AvgDialog_117503_Content_41 = {Text = "Hmph……"},
  AvgDialog_117503_Content_42 = {
    Text = "Salah, salah! Kamu sangat salah!"
  },
  AvgDialog_117503_Content_43 = {Text = "Murphy…?"},
  AvgDialog_117503_Content_44 = {
    Text = "Reaksi Murphy sepenuhnya di luar dugaan Anda, dia tertawa pelan."
  },
  AvgDialog_117503_Content_45 = {
    Text = "Tawa itu semakin liar, hingga dalam ruangan hanya terdengar suara tertawanya yang berlebihan."
  },
  AvgDialog_117503_Content_46 = {
    Text = [[
Setelah beberapa saat, dia tampaknya akhirnya lelah tertawa, suara tawanya tiba-tiba terhenti.
Dia mengangkat kepala, menatap tajam padamu.]]
  },
  AvgDialog_117503_Content_47 = {
    Text = "Bayi Dewa berkembang dalam dadaku, aku yang terhormat sebagai Ibu Dewa, dicintai oleh banyak orang, mengapa harus mengikuti orang-orang fana seperti kalian untuk \"melarikan diri\"?"
  },
  AvgDialog_117503_Content_48 = {
    Text = "Tetapi, ketika Dewa lahir, kamu akan mati..."
  },
  AvgDialog_117503_Content_49 = {
    Text = "Tidak perlu menunggu lagi, orang bodoh."
  },
  AvgDialog_117503_Content_5 = {
    Text = "Bodoh, jangan bergerak sembarangan."
  },
  AvgDialog_117503_Content_50 = {
    Text = "Murphy menggendong sebuah bungkusan aneh, yang awalnya adalah bagian kepala bayi, mengkristal dengan gumpalan darah dan daging berwarna ungu kebiruan yang tampak akrab."
  },
  AvgDialog_117503_Content_51 = {
    Text = "Bay bayi suci?!"
  },
  AvgDialog_117503_Content_52 = {
    Text = "Dari siluet yang kau kenali, itu adalah dewa cacat yang dipanggil oleh ritual kelahiran kapal Sonael."
  },
  AvgDialog_117503_Content_53 = {
    Text = "Di dunia ini, bayi suci telah lahir? Tapi, mengapa… sangat kecil?!"
  },
  AvgDialog_117503_Content_54 = {
    Text = "Mengapa itu bisa sekecil ini... sungguh pertanyaan yang konyol."
  },
  AvgDialog_117503_Content_55 = {
    Text = "Jika ia selalu sekecil ini, maka tidak akan menjadi seperti balon hidrogen yang ditiup oleh kekuatan raksasa, yang dengan rakus menarik energi dari induknya, dengan sekuat tenaga mengisi, mengembung, dan menekan di dadaku…"
  },
  AvgDialog_117503_Content_56 = {
    Text = "Lalu, pada saat induk mati, kehancuran, pecah, menjadi abu..."
  },
  AvgDialog_117503_Content_57 = {
    Text = "Kau telah melihatnya, inilah bayi suci yang aku lahirkan."
  },
  AvgDialog_117503_Content_58 = {
    Text = "Kau menyebut ini... Dewa?"
  },
  AvgDialog_117503_Content_59 = {
    Text = "Bagaimana dengan itu? Siapa yang pernah melihat seperti apa Dewa yang lahir dari mulut Pelaut?"
  },
  AvgDialog_117503_Content_6 = {
    Text = "Gadis itu gelisah berdiri, kain hitam yang menutupinya bergetar dengan tidak tenang."
  },
  AvgDialog_117503_Content_60 = {
    Text = "Siapa yang bisa memastikan bahwa daging dan darah busuk yang ada di tangan kita bukanlah Dewa yang sebenarnya?"
  },
  AvgDialog_117503_Content_61 = {
    Text = "Suara pertanyaan menggema seperti guntur, meledak di dalam kepalamu."
  },
  AvgDialog_117503_Content_62 = {
    Text = "Saya bukan Murphy yang Anda kenal, saya adalah Ibu Dewa Pelaut, satu-satunya orang yang darahnya bersatu dengan-Nya."
  },
  AvgDialog_117503_Content_63 = {
    Text = [[
Sebagai catatan untukmu... Jangan buat aku menyesal telah membawamu ke surga.
Sekarang, biarkan aku sejenak tenang, bawa pikiran konyolmu keluar dari ruangan ini.]]
  },
  AvgDialog_117503_Content_64 = {
    Text = "Kau berkeliaran di atas kapal Paradais dengan mengingat kenangan masa lalu, para pelaut ikan kecil bergegas tanpa memperhatikanmu."
  },
  AvgDialog_117503_Content_65 = {
    Text = "Sampai di samping Ruang kekuatan, kamu melihat dua sosok yang familiar."
  },
  AvgDialog_117503_Content_66 = {
    Text = "Anak muda, berbaik hati, seranglah!"
  },
  AvgDialog_117503_Content_67 = {Text = "Baik!"},
  AvgDialog_117503_Content_68 = {
    Text = "Ding dang—!"
  },
  AvgDialog_117503_Content_69 = {
    Text = "Masih berhasil dihalau...? Kejam, jika terus begini, sampai kapan aku bisa membantu Tuan Goliath menyerang......"
  },
  AvgDialog_117503_Content_7 = {
    Text = "Kapal Parades telah melihat banyak pasien yang sensitif terhadap lingkungan laut, sebelum beradaptasi dengan \"taman bermain\", jangan goyangkan spiritualitas secara dramatik."
  },
  AvgDialog_117503_Content_70 = {
    Text = "Tenang saja, anak muda, dindingnya tipis. Jika ketahuan orang, kita berdua tidak bisa kabur."
  },
  AvgDialog_117503_Content_71 = {
    Text = "Tuan Goliath, Anda jelas-jelas telah mengatakan bahwa darah kita berasal dari para kuat, seharusnya kita tidak takut....."
  },
  AvgDialog_117503_Content_72 = {
    Text = "Bocah nakal, bahkan para yang kuat pun terkadang harus bergantung pada orang lain. Di atas kapal ini, kita harus berpura-pura mendengarkan wanita gila itu."
  },
  AvgDialog_117503_Content_73 = {Text = "Tapi..."},
  AvgDialog_117503_Content_74 = {
    Text = "Kurangi omong kosong, seseorang datang."
  },
  AvgDialog_117503_Content_75 = {
    Text = "Tubuh raksasa melangkah keluar dari Bayangan Ruang kekuatan, suara pisau besar yang menggergaji tanah hampir menutupi deru ruang kapal."
  },
  AvgDialog_117503_Content_76 = {
    Text = "Bertemu lagi, nak kecil."
  },
  AvgDialog_117503_Content_77 = {
    Text = "Goliath... bagaimana saya bisa sampai di kapal ini?"
  },
  AvgDialog_117503_Content_78 = {
    Text = "Seharusnya kau bertanya pada dirimu sendiri, di wilayah miryam tidak menyambut pengunjung biasa, apalagi kapal kecil yang tiba-tiba bertabrakan."
  },
  AvgDialog_117503_Content_79 = {
    Text = "Tidak tahu bagaimana keberuntunganmu, tetapi gadis kecil itu beberapa hari yang lalu tiba-tiba berbalik, tidak mau membiarkan kita menyentuhmu."
  },
  AvgDialog_117503_Content_8 = {
    Text = "Menghadapi kamu, sepasang mata merah yang tampak familiar."
  },
  AvgDialog_117503_Content_80 = {
    Text = "Atau wanita itu mungkin akan menangkapmu untuk melebur Perak, karena di dunia yang sudah mati ini, Perak bisa dibilang semakin sedikit."
  },
  AvgDialog_117503_Content_81 = {
    Text = "Kalau begitu, posisi Anda bagaimana? Goliath yang saya kenal bukanlah orang yang dapat dipermainkan seperti itu."
  },
  AvgDialog_117503_Content_82 = {
    Text = "Anak kecil, Anda baru saja naik ke kapal ini, masih banyak hal yang belum Anda ketahui."
  },
  AvgDialog_117503_Content_83 = {
    Text = "Kau hanya perlu mengingat satu hal: wanita gila itu sekarang sepenuhnya tunduk pada Sang Ibu. Segala sesuatu di kapal ini ditentukan oleh gadis kecil itu."
  },
  AvgDialog_117503_Content_84 = {
    Text = "Jangan coba melanggar keinginannya—setidaknya jangan sampai dia menyadarinya."
  },
  AvgDialog_117503_Content_85 = {
    Text = "Yang lainnya, biarlah aku beritahu kamu ketika kita bertemu lagi di lain kesempatan."
  },
  AvgDialog_117503_Content_86 = {
    Text = "Saya perlu memikirkan dengan baik… mari kita pergi ke dek untuk merasakan angin laut."
  },
  AvgDialog_117503_Content_87 = {
    Text = "Kau berdiri sendirian di buritan kapal, memandangi jauh ke depan."
  },
  AvgDialog_117503_Content_88 = {
    Text = "Permukaan laut terselimuti kabut putih tipis, pelayaran kapal pesiar memecah suara hiruk-pikuk laut dan suara mesin dengan tenang dan stabil."
  },
  AvgDialog_117503_Content_89 = {
    Text = "Kau menghirup dalam-dalam udara laut yang campur dengan aroma asin, mencoba merajut pemikiran yang kacau."
  },
  AvgDialog_117503_Content_9 = {
    Text = "——Dongdong, dongdong——"
  },
  AvgDialog_117503_Content_90 = {
    Text = "Saya mengejar kapal William ke dalam badai, mengalami kecelakaan, diselamatkan oleh kapal pelaut……"
  },
  AvgDialog_117503_Content_91 = {
    Text = "Kelahiran bayi suci telah terjadi, Murphy menjadi Ibu Suci dari Pelaut, miryam sedang mengumpulkan perak, goliath sedang merencanakan sesuatu di bayangan……"
  },
  AvgDialog_117503_Content_92 = {
    Text = "<Shake:krek——>"
  },
  AvgDialog_117503_Content_93 = {
    Text = "Eh, suara apa itu?"
  },
  AvgDialog_117503_Content_94 = {
    Text = "Kau menoleh untuk mencari asal suara, tetapi dek itu sunyi, tidak terlihat setetes pun bekas kehidupan."
  },
  AvgDialog_117503_Content_95 = {
    Text = "(Apakah ini hanya ilusiku?)"
  },
  AvgDialog_117503_Content_96 = {
    Text = "<Shake:Klik klik klik——>"
  },
  AvgDialog_117503_Content_97 = {Text = "Eh?!"},
  AvgDialog_117503_Content_98 = {
    Text = "Di kedalaman bawah air， banyak tubuh kecil yang terbentang di permukaan laut， cahaya keruh yang mengapung mengingatkan pada ruam kulit manusia."
  },
  AvgDialog_117503_Content_99 = {
    Text = "Ini semua... adalah... ikan?"
  },
  AvgDialog_117504_Content_1 = {
    Text = "Seremoni navigasi"
  },
  AvgDialog_117504_Content_10 = {
    Text = "Saya dan Faros sedang mempersiapkan upacara penuntun, makhluk spiritual tentu berkumpul, menjadi makanan untuk upacara."
  },
  AvgDialog_117504_Content_100 = {
    Text = "Suara itu memanggil Anda—"
  },
  AvgDialog_117504_Content_101 = {
    Text = "<Italic:<Red:Tolong aku>>"
  },
  AvgDialog_117504_Content_102 = {
    Text = "Dorongan yang tak tertahankan membuatmu melompat dari tiang kapal."
  },
  AvgDialog_117504_Content_103 = {
    Text = "Kau harus menggenggam tangannya, membebaskannya dari ritual berdarah ini."
  },
  AvgDialog_117504_Content_104 = {
    Text = "Murphy, jangan lanjutkan ritual itu! Kamu akan mati! Ayo lari bersamaku!"
  },
  AvgDialog_117504_Content_105 = {
    Text = "Kau gila? Berani menodai ibu dewa!"
  },
  AvgDialog_117504_Content_106 = {
    Text = "Saya bukan Murphy yang Anda kenal, saya sudah mengambil pilihan saya!"
  },
  AvgDialog_117504_Content_107 = {
    Text = "Meskipun kamu bukan murphy yang aku kenal, aku sudah melihat banyak awakener dari sumber lainnya - Roda takdir: waktu purba, Helot: catena, doll: inferno……"
  },
  AvgDialog_117504_Content_108 = {
    Text = "Mereka terjebak dalam kegilaan, hanya mengalami lebih banyak ketidakberuntungan dalam perjalanan mereka. Pengalaman tidak akan mengubah warna hati mereka."
  },
  AvgDialog_117504_Content_109 = {
    Text = "Jangan terus terjebak dalam kesesatan, mari kabur bersamaku!"
  },
  AvgDialog_117504_Content_11 = {
    Text = "Upacara penuntun?"
  },
  AvgDialog_117504_Content_110 = {
    Text = "Melarikan diri...? Kita bisa melarikan diri ke mana?"
  },
  AvgDialog_117504_Content_111 = {
    Text = "Tempat ini sudah menjadi dunia yang paling sempurna, setiap usaha untuk melarikan diri hanya akan terjerat dalam siklus yang lebih mendalam dan lebih putus asa."
  },
  AvgDialog_117504_Content_112 = {
    Text = "Lihatlah di belakangmu, ombak besar yang mengamuk."
  },
  AvgDialog_117504_Content_113 = {
    Text = "Bersama dengan mendidihnya permukaan laut, ribuan Pelaut dan ular air mengerumuni patung gading yang pucat, membawa perasaan tertekan yang tak berujung."
  },
  AvgDialog_117504_Content_114 = {
    Text = "Ibu Dewa… tolong maafkan aku tidak bisa lagi mengikuti perintahmu, tidak bisa lagi menahan tindakan menodai Dewa ini."
  },
  AvgDialog_117504_Content_115 = {
    Text = "Miryam berlutut di depan kapal, memberikan penghormatan yang penuh rasa hormat ke arah permukaan laut yang terpisah."
  },
  AvgDialog_117504_Content_116 = {
    Text = "Dewa di atas, bagi orang yang penuh dengan iman. Para penodai yang berusaha menghalangi upacara telah muncul."
  },
  AvgDialog_117504_Content_117 = {
    Text = "Silakan menghukum para penjahat yang berani menghina Sang Ibu Tuhan."
  },
  AvgDialog_117504_Content_118 = {
    Text = "Mereka menginjak tangga tak terlihat yang dibentuk oleh gelombang laut, dengan langkah yang licin dan aneh, diam-diam menginjak geladak kapal pesiar."
  },
  AvgDialog_117504_Content_119 = {
    Text = "<Big:<Shake:Pergilah, gigit mereka, robek mereka!!>>"
  },
  AvgDialog_117504_Content_12 = {
    Text = "Ibu Dewi akan membimbing kami, mencapai Lemuria yang mengapung."
  },
  AvgDialog_117504_Content_13 = {
    Text = "Melihat wajahmu yang bingung, wajah Miryam menjadi sangat lembut."
  },
  AvgDialog_117504_Content_14 = {
    Text = "Kamu pasti memiliki banyak keraguan, jangan khawatir, atas perintah Ibu dewa, aku akan menjawab semuanya untukmu."
  },
  AvgDialog_117504_Content_15 = {
    Text = "……Jujur saja, perubahan sikapmu sudah cukup mengejutkan."
  },
  AvgDialog_117504_Content_16 = {
    Text = "Merefleksikan masa lalu, konflik antara dirimu dan Pelaut tidak ada gunanya."
  },
  AvgDialog_117504_Content_17 = {
    Text = "Bagaimana mungkin, aku pernah menyaksikan Pelaut melaksanakan ritual jahat..."
  },
  AvgDialog_117504_Content_18 = {
    Text = "Itu adalah kesalahpahaman. Pelaut mengadakan ritual rahasia untuk mengumpulkan energi yang diperlukan untuk menjaga kapal ini berlayar."
  },
  AvgDialog_117504_Content_19 = {
    Text = "Dalam momen di mana sebagian besar manusia telah menjadi debu, kadar perak yang terakumulasi di berbagai lokasi cukup untuk memenuhi kebutuhan kami."
  },
  AvgDialog_117504_Content_2 = {
    Text = "Di antara baunya yang menyengat, wanita berpakaian ungu mengernyitkan dahi dan berbalik ke arah Faros di sampingnya."
  },
  AvgDialog_117504_Content_20 = {
    Text = "Oleh karena itu, Pelaut menyelami Nekropolis, menjaring Perak yang diekstrak dari para yang telah tiada. Namun tindakan ini bertentangan dengan kebiasaan Dulcein, sang penguasa Nekropolis, yang mengkonsumsi tubuh."
  },
  AvgDialog_117504_Content_21 = {
    Text = "Berdasarkan pemahaman kami tentang Universitas Mythag, kalian juga menggunakan perak yang dimurnikan sebagai sumber energi, kan?"
  },
  AvgDialog_117504_Content_22 = {
    Text = "Kunci perak yang ada di dadamu terbuat dari perak."
  },
  AvgDialog_117504_Content_23 = {
    Text = "Kamu tidak bisa menerimanya untuk saat ini, tetapi juga tidak dapat membantah, hanya bisa alihkan pembicaraan."
  },
  AvgDialog_117504_Content_24 = {
    Text = "Miryam...... apa tujuanmu dan Pelaut?"
  },
  AvgDialog_117504_Content_25 = {
    Text = "Tentu saja, untuk membangun kembali ranah dewa, menghidupkan kembali Lemuria."
  },
  AvgDialog_117504_Content_26 = {
    Text = "Di saat tuhan kita sudah turun, tidak ada yang lebih penting daripada kembali ke ranah dewa dan mengembalikan kejayaan Lemuria."
  },
  AvgDialog_117504_Content_27 = {
    Text = "Kedatangan yang kau maksud adalah... tulu?"
  },
  AvgDialog_117504_Content_28 = {
    Text = "Kesadarannya masih dalam keadaan setengah bermimpi, tetapi Ia pasti akan menjalankan janjinya, memimpin kami kembali ke Ranah Dewa."
  },
  AvgDialog_117504_Content_29 = {
    Text = "Lemuria...... di mana?"
  },
  AvgDialog_117504_Content_3 = {
    Text = "Kumpulkan spiritualitas di sini."
  },
  AvgDialog_117504_Content_30 = {
    Text = "Di atas langit, di bawah laut. Wahyu tidak mengungkapkan lebih banyak."
  },
  AvgDialog_117504_Content_31 = {
    Text = "Setelah mengucapkan kata sandi ini, Miryam terdiam."
  },
  AvgDialog_117504_Content_32 = {
    Text = "Faros yang telah mengumpulkan semua perak memegang kotak kayu yang penuh dengan perak, berdiri di samping Miryam."
  },
  AvgDialog_117504_Content_33 = {
    Text = "<faros>， kenapa kamu bergabung dengan <Pelaut>?"
  },
  AvgDialog_117504_Content_34 = {
    Text = "Ini masih perlu ditanyakan? Karena negara lautan ada di sana. Negara lautan memanggilku."
  },
  AvgDialog_117504_Content_35 = {
    Text = "Ke mana pun saya pergi, saya bisa mendengar suara panggilan-Nya, seperti ombak yang datang dan pergi hari demi hari."
  },
  AvgDialog_117504_Content_36 = {
    Text = "Dia menatap jauh, kata-katanya hanyalah kehampaan."
  },
  AvgDialog_117504_Content_37 = {
    Text = "Tergantung situasinya, hari ini seharusnya adalah cuaca yang baik. Lihat, matahari akan segera terbit."
  },
  AvgDialog_117504_Content_38 = {
    Text = "Matahari......"
  },
  AvgDialog_117504_Content_39 = {
    Text = "Kau mengikuti arah pandangannya -"
  },
  AvgDialog_117504_Content_4 = {
    Text = "Ya, Tuan Pendeta."
  },
  AvgDialog_117504_Content_40 = {
    Text = "Dengung, dengung. Suara detak jantungmu hampir menghancurkan gendang telinga."
  },
  AvgDialog_117504_Content_41 = {
    Text = "<Shake: Tunggu, di langit... di mana matahari?>"
  },
  AvgDialog_117504_Content_42 = {
    Text = "Matahari? Bukankah matahari ada di sana?"
  },
  AvgDialog_117504_Content_43 = {
    Text = "Tidak, tidak, bukan matahari ini!"
  },
  AvgDialog_117504_Content_44 = {
    Text = "Di permukaan laut, terbit matahari yang seharusnya kau impikan, memancarkan cahaya lembut di balik kabut tipis."
  },
  AvgDialog_117504_Content_45 = {
    Text = "Bukan matahari ini? Matahari mana lagi yang ada?"
  },
  AvgDialog_117504_Content_46 = {
    Text = "Cahaya yang hangat seolah memancarkan panas yang luar biasa, membuat Anda kehilangan akal, tenggorokan kering, kata-kata yang terucap pun sulit dimengerti."
  },
  AvgDialog_117504_Content_47 = {
    Text = "Seharusnya matahari itu berwarna hitam dan tidak bercahaya!"
  },
  AvgDialog_117504_Content_48 = {
    Text = "Saya tidak pernah mendengar, melihat apa itu matahari hitam..."
  },
  AvgDialog_117504_Content_49 = {
    Text = "<faros>， tahun ini tahun berapa?"
  },
  AvgDialog_117504_Content_5 = {
    Text = "<faros> berlutut di tanah， memungut sisa bangkai yang bau satu per satu."
  },
  AvgDialog_117504_Content_50 = {
    Text = "Tahun 1920. Ada yang salah?"
  },
  AvgDialog_117504_Content_51 = {
    Text = "Bukan masa banjir…aku memang berada di dunia baru..."
  },
  AvgDialog_117504_Content_52 = {
    Text = "Jangan teralihkan perhatiannya, Ibu Tuhan datang."
  },
  AvgDialog_117504_Content_53 = {
    Text = "Sebagai tamu yang disetujui oleh Ibu Dewi, aku akan memberimu izin untuk mengamati upacara pelayaran yang paling megah ini."
  },
  AvgDialog_117504_Content_54 = {
    Text = "Tapi jangan sekali-kali meninggalkan tempat ini, jika tidak aku pasti akan menampilkan penodai sebagai contoh."
  },
  AvgDialog_117504_Content_55 = {
    Text = "Sekelompok kecil berwarna hitam ungu datang dari ekor kapal pesiar, langkah mereka aneh dan sinkron, merayap menuju dek di bawah kaki kalian."
  },
  AvgDialog_117504_Content_56 = {
    Text = "Gadis yang terdepan mengenakan pakaian putih yang suram, memeluk suatu beban yang bengkak dan gemuk, ekspresi di bawah kain hitamnya samar dan sulit dikenali."
  },
  AvgDialog_117504_Content_58 = {
    Text = "Antrian dengan cepat berhenti di buritan kapal, setiap pion hitam sepertinya sudah akrab dengan titik jatuhnya."
  },
  AvgDialog_117504_Content_59 = {
    Text = "Sepasang kaki telanjang memasuki jalur sempit yang ditinggalkan untuknya, di belakangnya, ribuan fragmen perak kecil jatuh berjatuhan."
  },
  AvgDialog_117504_Content_6 = {
    Text = "Dia memancarkan cahaya lembut dari dahinya, beberapa detik kemudian, sekolah ikan hanya menyisakan sisa-sisa perak."
  },
  AvgDialog_117504_Content_60 = {
    Text = "Terima kasih kepada ibu baptis yang telah menganugerahi kami darah pusar! Kami pasti akan menelan api jiwa, meminum doa darah, menjadikan ribuan jiwa yang taat sebagai mercusuar!"
  },
  AvgDialog_117504_Content_61 = {
    Text = "Makhluk-makhluk merangkak di tanah, berebut mengambil mutiara perak di lantai."
  },
  AvgDialog_117504_Content_62 = {
    Text = "……Myriam……"
  },
  AvgDialog_117504_Content_63 = {
    Text = "Miryam dengan hormat menunduk, di tengah piring perak berbahan kain hitam yang digenggamnya, terletak sebuah belati yang bersinar cemerlang."
  },
  AvgDialog_117504_Content_64 = {
    Text = "Kepada Dewa Ibu yang terhormat, mohon tarik garis keturunan Raja Dewa, pandu Pelaut yang tersesat, tunjukkan kepada kami keberadaan Lemuria."
  },
  AvgDialog_117504_Content_65 = {
    Text = "Gadis itu mengambil belati."
  },
  AvgDialog_117504_Content_66 = {
    Text = "Kepada Raja Dewa yang terhormat…"
  },
  AvgDialog_117504_Content_67 = {
    Text = "Belati menembus selimut, tetesan darah kental seolah memiliki kesadaran sendiri mengembun di udara."
  },
  AvgDialog_117504_Content_68 = {
    Text = "<Change>Saya dengan darah dewa sebagai pemandu."
  },
  AvgDialog_117504_Content_69 = {
    Text = "Semua pengikut berlutut di tanah, kedua tangan menghadap ke langit, dengan sebuah pisau kecil yang tipis memotong pergelangan tangan kiri yang terbalut sisik."
  },
  AvgDialog_117504_Content_7 = {
    Text = "Miryam...... ikan terbang ini...... apakah kau dan faros yang memanggilnya?"
  },
  AvgDialog_117504_Content_70 = {
    Text = "Ribuan benang perak melilit bola darah, menyebar dari pergelangan ratusan pengikut, mengikuti jejak yang tak tertangkap menuju satu lokasi."
  },
  AvgDialog_117504_Content_71 = {
    Text = "<Change>Jadikan semesta sebagai persembahan."
  },
  AvgDialog_117504_Content_72 = {
    Text = "Tetesan darah hitam berputar, mengkristal, melompat ke dalam sebuah Patung gading yang berwarna putih susu, meresap membentuk jaringan darah yang halus."
  },
  AvgDialog_117504_Content_73 = {
    Text = "Patung gading seolah diaktifkan oleh kekuatan hidup, melambung melewati monster besi, mendarat langsung ke dalam lautan yang sunyi."
  },
  AvgDialog_117504_Content_74 = {
    Text = "<Change>Mohon sobek ilusi laut yang dalam, tuntun kami langsung menuju kerajaan Anda."
  },
  AvgDialog_117504_Content_75 = {
    Text = "Seketika laut dan langit bergetar, seantero lautan mengamuk , mengeluarkan suara mengerang seperti makhluk raksasa melahirkan."
  },
  AvgDialog_117504_Content_76 = {
    Text = "Gelombang angin menari, merintih, membentuk dinding gelombang yang bergetar."
  },
  AvgDialog_117504_Content_77 = {
    Text = "Ibu Dewi, jumlah jiwa ini tampaknya sedikit kurang..."
  },
  AvgDialog_117504_Content_78 = {
    Text = "Tidak apa-apa."
  },
  AvgDialog_117504_Content_79 = {
    Text = "Gadis itu menurunkan cadarnya, menoleh ke arah yang menyembah."
  },
  AvgDialog_117504_Content_8 = {
    Text = "Miryam sepertinya baru menyadari keberadaanmu, sedikit memiringkan kepala, mengarahkan pandangannya ke arahmu."
  },
  AvgDialog_117504_Content_80 = {
    Text = "Mohon, Sang Ibu Tuhan, berikan darah suci!"
  },
  AvgDialog_117504_Content_81 = {
    Text = "<Big:<Shake:Semoga Ibu Tuhan memberi darah suci!>>"
  },
  AvgDialog_117504_Content_82 = {
    Text = "Suara semakin meningkat, di tengah seruan itu, jari-jari sang gadis mengarah ke dadanya."
  },
  AvgDialog_117504_Content_83 = {
    Text = "Kuku-kukunya tajam seperti mata pisau, merobek dada sepanjang bekas luka ungu, memperlihatkan satu-satunya jantung yang tersisa."
  },
  AvgDialog_117504_Content_84 = {
    Text = "<Shake:Apakah kamu menangkap, berburu! Jika aku mempersembahkan darah dan carne de Dewi, kamu pasti untukku membangun tangga mundur ke Ranah dewa!>"
  },
  AvgDialog_117504_Content_85 = {
    Text = "Pengikut menyerbu secara bersamaan. Sirip dan penjepit aneh mereka tidak sabar menggapai tubuh ramping Sang Ibu."
  },
  AvgDialog_117504_Content_86 = {
    Text = "Mereka menyerap darahnya dan memakan dagingnya. Jalur merah yang membara mulai berkembang pesat, berdesak-desakan masuk ke dalam deep sea."
  },
  AvgDialog_117504_Content_87 = {
    Text = "Merah darah berkembang biak secara gila-gilaan dengan titik jatuh patung sebagai pusatnya, ombak membeku menjadi jutaan karang darah."
  },
  AvgDialog_117504_Content_88 = {
    Text = "Ritual telah selesai! Pergi!"
  },
  AvgDialog_117504_Content_89 = {
    Text = "Dia melangkah di atas tubuh Pelaut yang terhimpit di depan gadis itu, membungkus Tubuh Murphy dengan jubah hitam. Di bawah jubah, sungai darah masih mengalir deras."
  },
  AvgDialog_117504_Content_9 = {
    Text = "Bukankah kamu seharusnya berada di ruang istirahat Ibu dewa? Kenapa…"
  },
  AvgDialog_117504_Content_90 = {
    Text = "Lemuria! Lemuria! Darah Ibu Tuhan telah menandai jalan menuju Lemuria!"
  },
  AvgDialog_117504_Content_91 = {
    Text = "Di tengah ribuan garis darah, kau melihat sehelai garis perak yang aneh. Garis perak itu tumbuh dari dadamu, terus melambai ke atas, memanjang..."
  },
  AvgDialog_117504_Content_92 = {
    Text = "Hingga di suatu tempat yang tidak diketahui di luar langit."
  },
  AvgDialog_117504_Content_93 = {
    Text = "Gadis itu sepertinya juga menyadari keberadaan benang perak itu, dia menengadah, Murid-nya bergetar tiba-tiba, tatapan ketakutannya menusuk ke arahmu."
  },
  AvgDialog_117504_Content_95 = {
    Text = "Ketika tatapan saling bertemu, kekuatan besar yang tak terlihat menarikmu, tidak mengindahkan perlawananmu, membuatmu terjatuh ke dalam ilusi menakutkan seperti mimpi buruk."
  },
  AvgDialog_117504_Content_96 = {
    Text = "……Itu adalah matahari hitam yang tidak bersih yang telah kamu lihat."
  },
  AvgDialog_117504_Content_97 = {
    Text = "Suara gendang?"
  },
  AvgDialog_117504_Content_98 = {
    Text = "Tidak, itu suara detak jantung."
  },
  AvgDialog_117504_Content_99 = {
    Text = "Panjang, terengah-engah, di ambang kematian, sudah lenyap sejak zaman purba namun terbangun setelah mimpi panjang..."
  },
  AvgDialog_118123_Content_1 = {
    Text = "Kesatria Kincir Angin"
  },
  AvgDialog_118123_Content_10 = {
    Text = "Hanya dengan memiliki harapan seperti itu, saya memberi kesempatan kepada orang ini."
  },
  AvgDialog_118123_Content_11 = {
    Text = "(Hasilnya tetap, tidak ada gunanya...)"
  },
  AvgDialog_118123_Content_12 = {
    Text = "Ternyata…… aku memang harus membantu!"
  },
  AvgDialog_118123_Content_13 = {
    Text = "Berlarilah seperti lalat tanpa kepala! Kamu ini sebenarnya mau kemana!"
  },
  AvgDialog_118123_Content_14 = {
    Text = "Seperti yang dikatakan senior William barusan, perahu penyelamat dari dek ke ruang bawah!"
  },
  AvgDialog_118123_Content_15 = {
    Text = "Pemandangan di dek begitu terbuka, aku lihat kamu ingin memberi makan penjaga laut dengan dirimu!"
  },
  AvgDialog_118123_Content_16 = {
    Text = "Dalam siklus sebelumnya, orang yang memberi makan ikan ternyata adalah diri Anda sendiri!"
  },
  AvgDialog_118123_Content_17 = {
    Text = "Sial, jangan membantah Ibu Dewa! Sekarang juga, lari ke ruang kemudi, di sana ada struktur yang bisa menuju kabin penyelamatan!"
  },
  AvgDialog_118123_Content_18 = {
    Text = "Tolong turunkan aku, rambutku sudah berantakan seperti sarang burung!"
  },
  AvgDialog_118123_Content_19 = {
    Text = "Kau adalah sandera pentingku, ini bukan saatnya memikirkan citra! Jadi, silakan bersabar lagi, Yang Ibu Dewa!"
  },
  AvgDialog_118123_Content_2 = {
    Text = "Kamu melompat turun, merasakan angin tajam memotong kedua pipimu, lalu tali di pinggangmu tiba-tiba mengencang, menghentikan penurunanmu."
  },
  AvgDialog_118123_Content_20 = {
    Text = "<Shake: Hati-hati, pengejar miryam sudah mendekat!>"
  },
  AvgDialog_118123_Content_3 = {
    Text = "Hei! Apa yang kamu lakukan!"
  },
  AvgDialog_118123_Content_4 = {
    Text = "Kau mencabut pisau kecil, memotong tali, lalu melompat turun ke tanah."
  },
  AvgDialog_118123_Content_5 = {
    Text = "Kau berencana untuk melarikan diri tanpa menghiraukanku? Mereka akan segera mengejarmu kan!"
  },
  AvgDialog_118123_Content_6 = {
    Text = "Aah aaah, benar-benar bodoh!"
  },
  AvgDialog_118123_Content_7 = {
    Text = "Saya tidak tahu kenapa, saya malah sedikit berharap pada idiot ini."
  },
  AvgDialog_118123_Content_8 = {
    Text = "Pelarian {Male=dia,Female=dia} kali ini, lebih ceroboh dibandingkan dengan setiap usaha yang saya lakukan di masa lalu."
  },
  AvgDialog_118123_Content_9 = {
    Text = "Jika di dunia ini juga ada <Yellow:%player%>, apakah arah cerita akan berbeda?"
  },
  AvgDialog_118124_Content_1 = {
    Text = "Kau merobek tirai, mengikat Murphy yang mencengkeram."
  },
  AvgDialog_118124_Content_10 = {
    Text = "Jika kamu mengamati tiga orang di sini, kamu akan tahu bahwa putri itu adalah orang lain."
  },
  AvgDialog_118124_Content_11 = {
    Text = "William mengikatkan tali dengan erat di pinggangmu dan Murphy."
  },
  AvgDialog_118124_Content_12 = {
    Text = "Jaga baik-baik putri, jangan sampai kehilangan dia! Ada perahu penyelamat di bilik bawah, kita bertemu di sana!"
  },
  AvgDialog_118124_Content_13 = {
    Text = "Tiga, dua, satu, lompat!"
  },
  AvgDialog_118124_Content_2 = {
    Text = "Beres! Jangan bergerak sembarangan, hati-hati jangan sampai terluka!"
  },
  AvgDialog_118124_Content_3 = {
    Text = "Sangat menjengkelkan! Jika ini terus berlanjut, aku akan menggigitmu!"
  },
  AvgDialog_118124_Content_4 = {
    Text = "Masih begini, tidak berpura-pura memang lebih cocok untukmu, Murphy."
  },
  AvgDialog_118124_Content_5 = {
    Text = "Kurangi omong kosong! Setelah aku mendapatkan kembali kebebasan, aku akan menghukummu karena menghina Ibu Dewa!"
  },
  AvgDialog_118124_Content_6 = {
    Text = "Namun, apa suara langkah di luar semakin intens?"
  },
  AvgDialog_118124_Content_7 = {
    Text = "Suara langkah kaki yang \"_puff-puff_\" bersatu menjadi gelombang, terus menerus tubuh kecil yang kekar menghantam pintu ruang tamu, mengeluarkan suara berdebam."
  },
  AvgDialog_118124_Content_8 = {
    Text = "Ayo, kita keluar melalui jendela! Ambil ini, dan melompat ke dek!"
  },
  AvgDialog_118124_Content_9 = {
    Text = "Mengikat tali dengan sprei…? William, kau terlihat seperti putri pelari dari cerita dongeng."
  },
  AvgDialog_118125_Content_1 = {
    Text = "Putri Menara"
  },
  AvgDialog_118125_Content_10 = {
    Text = "Kamu memperhatikan dengan saksama, benang yang putus ada dua, dan roda pemintal masih melilit empat lingkaran benang."
  },
  AvgDialog_118125_Content_11 = {
    Text = "Saya masih memiliki empat kesempatan lagi…… bukan?"
  },
  AvgDialog_118125_Content_12 = {
    Text = "Dia mengangguk, lalu menggelengkan kepala."
  },
  AvgDialog_118125_Content_13 = {
    Text = "Saya pernah mendengar suaramu, kamu bukan tidak bisa berbicara... kamu tidak diizinkan untuk mengucapkan apa pun...?"
  },
  AvgDialog_118125_Content_14 = {
    Text = "Dia membuka mulutnya, tetapi hanya mengeluarkan keheningan yang abadi."
  },
  AvgDialog_118125_Content_15 = {
    Text = "Dia menatap jauh ke langit, kamu mengikuti tatapannya dan melihat jauh ke arah sana."
  },
  AvgDialog_118125_Content_16 = {
    Text = "Di sana hanya ada satu matahari hitam yang terendam dalam air."
  },
  AvgDialog_118125_Content_17 = {
    Text = "Hah, hah...!"
  },
  AvgDialog_118125_Content_18 = {
    Text = "Kamu terbangun dengan terkejut, batuk keras karena rasa sakit tenggelam."
  },
  AvgDialog_118125_Content_19 = {
    Text = "Sekali lagi... siklus..."
  },
  AvgDialog_118125_Content_2 = {
    Text = "Angin laut membawa rasa asin dan pahit yang mengganggu saat masuk ke mulut."
  },
  AvgDialog_118125_Content_20 = {
    Text = "Orang-orang di kerajaan laut bisa terkejut, acuh tak acuh, atau menunjukkan kepedulian yang nyata atau palsu, semua itu terhalang oleh dinding berat. Yang tersisa dalam pikiran hanya wajah Murphy sebelum akhir siklus terakhir."
  },
  AvgDialog_118125_Content_21 = {
    Text = "Selamatkan aku……Jika memang kamu, pasti bisa……"
  },
  AvgDialog_118125_Content_22 = {
    Text = "Lalu kegelapan menelan segala sesuatu, menjadi keraguan yang tak dapat dihilangkan dalam benak."
  },
  AvgDialog_118125_Content_23 = {
    Text = "Bagaimanapun, Anda perlu bertemu dengan William terlebih dahulu."
  },
  AvgDialog_118125_Content_24 = {
    Text = "Goliath dan Miryam berjalan di sepanjang koridor yang kosong, langkah kaki mereka menghasilkan kembali."
  },
  AvgDialog_118125_Content_25 = {
    Text = "Melalui fresko patung Bunda dalam gaya Baroque, lampu kecil pengganti lampu dinding kuningan, dan kamar tidur yang sunyi."
  },
  AvgDialog_118125_Content_26 = {
    Text = "Mereka tidak bersentuhan, tidak berbicara, suasana tegang mengelilingi keduanya."
  },
  AvgDialog_118125_Content_27 = {
    Text = "Miryam berhenti di pintu ruang kapten, berbalik dan mendorong pintu terbuka."
  },
  AvgDialog_118125_Content_28 = {
    Text = "Goliath melangkah beberapa langkah maju, berdiri di belakangnya."
  },
  AvgDialog_118125_Content_29 = {
    Text = "Hei, Miryam. Gadis kecil itu sedang menipumu."
  },
  AvgDialog_118125_Content_30 = {
    Text = "Ada apa? Pada waktu seperti ini, seharusnya kamu menjaga ruang kemudi, kan?"
  },
  AvgDialog_118125_Content_31 = {
    Text = "Seandainya wanita yang menjaga ruang kekuatan itu sedikit kurang sempurna, aku akan menanyakan padamu."
  },
  AvgDialog_118125_Content_32 = {
    Text = "Jangan bicarakan hal-hal yang tidak penting, Caecus itu sedang melihat, kru bodoh itu tidak bisa membuat gelombang."
  },
  AvgDialog_118125_Content_33 = {
    Text = "Hanya ada satu masalah, gadis kecil itu sedang berbohong padamu."
  },
  AvgDialog_118125_Content_34 = {
    Text = "Perishite, mencetuskan omong kosong mengenai Ibu Dewa, tidak seperti kebiasaanmu."
  },
  AvgDialog_118125_Content_35 = {
    Text = "Tahukah kamu bahwa kapal ini tidak akan pernah sampai ke Lemuria?"
  },
  AvgDialog_118125_Content_36 = {
    Text = "……Goliath."
  },
  AvgDialog_118125_Content_37 = {
    Text = "Kamu hanya anjing peliharaanku; selama aku belum memerintahkanmu untuk mengarahkan pedang besar itu ke musuh, tidak ada ruang bagimu untuk mengoceh di sini."
  },
  AvgDialog_118125_Content_38 = {
    Text = "Sebelum berlabuh, Anda hanya perlu mengurus para pelaut di kapal, jangan biarkan mereka mengganggu tidur si Ibu Tuhan."
  },
  AvgDialog_118125_Content_39 = {
    Text = "Jika ada hal yang perlu kamu ketahui…"
  },
  AvgDialog_118125_Content_4 = {
    Text = "Wanita yang memegang jari putar memandangmu dengan ekspresi sedih."
  },
  AvgDialog_118125_Content_40 = {
    Text = "<Shake: Jika kapal ini memiliki sedikit kesempatan untuk mencapai Lemuria, itu semua karena cahaya Ibu Dewa.>"
  },
  AvgDialog_118125_Content_41 = {
    Text = "Tsk, wanita bau yang keras kepala..."
  },
  AvgDialog_118125_Content_42 = {
    Text = "Aku sudah mengucapkan kata-kata baik dan buruk sebelumnya."
  },
  AvgDialog_118125_Content_43 = {
    Text = "Untuk hal yang akan datang, kamu tidak dapat menyalahkan aku."
  },
  AvgDialog_118125_Content_44 = {
    Text = "Caecus, jalankan rencana."
  },
  AvgDialog_118125_Content_45 = {Text = "Di sini!"},
  AvgDialog_118125_Content_46 = {
    Text = "Sebelum ritual selesai, rampas kendali utama kapal."
  },
  AvgDialog_118125_Content_47 = {
    Text = "Kau bersikap ragu di atas dek, berusaha mencari petunjuk yang mungkin mengarah ke tempat persembunyian William."
  },
  AvgDialog_118125_Content_48 = {
    Text = "Jika saya tidak salah ingat, ada di posisi ini…"
  },
  AvgDialog_118125_Content_49 = {
    Text = "Kau membuka pintu papan melalui celah di dek, lalu menggigit gigi dan melompat turun."
  },
  AvgDialog_118125_Content_5 = {
    Text = "Apakah ada yang ingin kau bicarakan denganku?"
  },
  AvgDialog_118125_Content_50 = {
    Text = "<Shake: Puh, pelah...>"
  },
  AvgDialog_118125_Content_51 = {
    Text = "Kau batuk, mengeluarkan rumput liar yang terjebak di mulutmu, menyesali pilihan cara mendarat yang kau buat."
  },
  AvgDialog_118125_Content_52 = {
    Text = "Senior William, jangan bersembunyi, saya tahu kamu di sini!"
  },
  AvgDialog_118125_Content_53 = {
    Text = "Setelah beberapa saat, terdengar beberapa suara dari belakang tumpukan jerami."
  },
  AvgDialog_118125_Content_54 = {
    Text = "Ini tidak masuk akal."
  },
  AvgDialog_118125_Content_55 = {
    Text = "……Jika kamu memiliki kemampuan untuk melokalisasi saya dengan tepat, di jalanan London kamu seharusnya sudah mengejar saya."
  },
  AvgDialog_118125_Content_56 = {
    Text = "Baiklah, cerita yang baik… apa yang kau alami setelah menaiki kapal ini?"
  },
  AvgDialog_118125_Content_58 = {
    Text = "Kamu menceritakan kisah reinkarnasi dengan singkat."
  },
  AvgDialog_118125_Content_59 = {
    Text = [[
Maaf, saat ritual dimulai, tidak ada waktu lagi.
Kak William, kita harus mengatasi penyergapan di ruang Murphy sebelum itu.]]
  },
  AvgDialog_118125_Content_6 = {
    Text = "Wanita itu mengangguk."
  },
  AvgDialog_118125_Content_60 = {
    Text = "Ayo, lewat jalan ini, di sini tidak ada mata-mata."
  },
  AvgDialog_118125_Content_61 = {
    Text = "Maksudmu, Goliath sedang merencanakan pemberontakan, dan aku harus sembunyi bersamamu."
  },
  AvgDialog_118125_Content_62 = {
    Text = "Dan semua ini, apakah karena kamu mengalami pemulihan waktu, sehingga kamu mengetahuinya?"
  },
  AvgDialog_118125_Content_63 = {
    Text = "Terlalu absurd, terlalu bodoh... kecuali jika jiwaku kehilangan kendali...<Shake:Hmm...>"
  },
  AvgDialog_118125_Content_64 = {
    Text = "Maaf, tidak ada ruang untuk kekasaranmu di sini."
  },
  AvgDialog_118125_Content_65 = {
    Text = "Kak William!"
  },
  AvgDialog_118125_Content_66 = {
    Text = "Tenangkanlah, saya menduga tidak semudah itu, suara dari luar ruang tamu sudah terputus."
  },
  AvgDialog_118125_Content_67 = {
    Text = "Bawa dia pergi dulu!"
  },
  AvgDialog_118125_Content_7 = {
    Text = "Apakah ini berhubungan dengan reincarnation?"
  },
  AvgDialog_118125_Content_8 = {
    Text = "Wanita itu menggelengkan kepala, ujung jarinya menyentuh benang dari roda pemintal, berputar searah jarum jam, berhenti di titik awal."
  },
  AvgDialog_118125_Content_9 = {
    Text = "Seiring dengan putaran pemintal, benang awal putus dan hancur."
  },
  AvgDialog_118699_Content_1 = {
    Text = "Keinginan kami"
  },
  AvgDialog_118699_Content_10 = {
    Text = "Lebih banyak kekuatan roh yang kuat... Saya mengerti, saya akan mengirim pemberitahuan ke semua awak."
  },
  AvgDialog_118699_Content_11 = {
    Text = "Di lapangan bermain senja, Ogier menyelesaikan latihan rutinnya dalam sehari, tidak ada pengurangan dibanding sebelumnya."
  },
  AvgDialog_118699_Content_12 = {
    Text = "Hari ini lagi-lagi melampaui sedikit rekor sebelumnya……"
  },
  AvgDialog_118699_Content_13 = {
    Text = "Menghapus keringat yang mengalir, senjata panjang yang berat menjunam ke tanah, Ogier menoleh, di belakangnya tidak ada lagi sosok yang tersenyum memberikan dorongan, hanya bayang-bayangnya yang sendiri membentang di tanah."
  },
  AvgDialog_118699_Content_14 = {
    Text = "Senyuman Lotan membawa dua senjata biasa penyelidik terbang dalam bayangan, mengakhiri satu lagi pertarungan yang hanya berlangsung selama satu menit."
  },
  AvgDialog_118699_Content_15 = {
    Text = "Apa dengan kelahiran baru sekarang, kualitasnya sangat buruk, ayo lagi!"
  },
  AvgDialog_118699_Content_16 = {
    Text = "Belum sempat dia mengangkat pedang untuk terus menganiaya, dua mahasiswa baru yang terengah-engah di hadapannya telah mulai bertepuk tangan meminta ampun."
  },
  AvgDialog_118699_Content_17 = {
    Text = "Tsk, membosankan..."
  },
  AvgDialog_118699_Content_18 = {
    Text = "Mengingat seseorang yang bisa memberinya pertempuran yang seru, Lotan menatap matahari terbenam dan menghela napas, berpaling dengan bosan."
  },
  AvgDialog_118699_Content_19 = {
    Text = "Aigis memotong seutas benang yang tersisa, membuka dengan hati-hati sweater yang baru dijahit, meratakannya, lalu berjinjit menghangatkannya ke dalam lemari yang penuh dengan bahan tenun."
  },
  AvgDialog_118699_Content_2 = {
    Text = [[
Dunia Kadath
Sekarang]]
  },
  AvgDialog_118699_Content_20 = {
    Text = "Gaya yang semakin banyak, motif mandala, berlian, gelombang, bunga kecil, dan pola hewan, Aigis kini dapat menenun lebih banyak lagi."
  },
  AvgDialog_118699_Content_21 = {
    Text = "Saudaraku{Male=Tuan Penjaga Rahasia,Female=Nona Penjaga Rahasia}, kamu suka seperti apa...?"
  },
  AvgDialog_118699_Content_22 = {
    Text = "Mencermati, tikus kecil berwarna abu-abu melompati lubang pintu, dengan setia menempatkan sebuah cincin berkilauan di tangan rekannya."
  },
  AvgDialog_118699_Content_23 = {
    Text = "Hmm, bagus sekali, Cokelat."
  },
  AvgDialog_118699_Content_24 = {
    Text = "Lincah, tikus kecil itu melihat temannya yang bosan menguap, melemparkan cincin ke dalam peti kayu yang terbuka, barang-barang \"koleksi\" yang berantakan di dalamnya sudah menumpuk tinggi."
  },
  AvgDialog_118699_Content_25 = {Text = "Ciiit..."},
  AvgDialog_118699_Content_26 = {
    Text = "Orang itu sudah lama tidak datang ke asrama untuk mencari kotak harta mereka, memerintahkan ketua untuk mengembalikan barang satu per satu, tetapi mengapa setelah itu ketua masih tampak murung?"
  },
  AvgDialog_118699_Content_27 = {
    Text = "Gadis yang manis duduk di depan meja belajar, membuka buku cerita yang lain."
  },
  AvgDialog_118699_Content_28 = {
    Text = "Di sudut meja telah menumpuk setumpuk buku anak-anak yang telah dibaca, di buku catatan di samping gadis itu, ia juga mencatat ide cerita yang terpikirkan."
  },
  AvgDialog_118699_Content_29 = {
    Text = "Ketika teringat saat-saat bersemangat, wajah tenang gadis itu menunjukkan senyum tipis, dan kakinya perlahan bergetar di bawah meja."
  },
  AvgDialog_118699_Content_3 = {
    Text = "Terowongan kabur yang belum terbentuk runtuh akibat erosi mengerikan yang tiba-tiba muncul, Ramona mengeluarkan suara rendah, kesadarannya ditarik kembali dengan mendesak oleh alat."
  },
  AvgDialog_118699_Content_30 = {
    Text = "Cerita ini pasti akan disukai oleh semua orang..."
  },
  AvgDialog_118699_Content_31 = {
    Text = "Pensil berbunyi nyaring, mencatat imajinasi masa kanak-kanak. Tetapi segera, gadis itu berhenti menulis, merenung menatap ke luar jendela."
  },
  AvgDialog_118699_Content_32 = {
    Text = "Tapi, kapan {Male=Tuan Penjaga Rahasia,Female=Nona Penjaga Rahasia} bisa kembali untuk membawa Lily syuting film?"
  },
  AvgDialog_118699_Content_34 = {
    Text = "Prajurit menuangkan kantong anggur, membasahi tanah di depan batu nisan."
  },
  AvgDialog_118699_Content_35 = {
    Text = "Setelah menghabiskan setengah botol sisa, pejuang telah pergi dengan diam, hanya wreath laurel yang tergantung dengan tenang di atas nisan."
  },
  AvgDialog_118699_Content_36 = {
    Text = "Di atas meja kain beludru yang megah, teh sore para wanita tetap semewah sebelumnya."
  },
  AvgDialog_118699_Content_37 = {
    Text = "Suara benturan alat makan dan piring yang teredam, mengantarkan kue krim yang lezat ke dalam mulut."
  },
  AvgDialog_118699_Content_38 = {
    Text = "Dengan santapan yang terlalu tenang, sang wanita terhormat diam-diam menatap kursi kosong di depannya, set perlengkapan makan yang khusus untuk orang itu."
  },
  AvgDialog_118699_Content_39 = {
    Text = "Meninggalkan majikan sendirian di sini, benar-benar pelayan yang tidak kompeten…"
  },
  AvgDialog_118699_Content_4 = {
    Text = "Ramona! Pollux! Bagaimana keadaan kalian?"
  },
  AvgDialog_118699_Content_40 = {
    Text = "Di sebuah kamar dormitori kosong yang sengaja disiapkan, perabotan yang bersih dan baru seolah tidak ada yang menempati, hanya sebuah pot bibit pohon yang baru tumbuh di depan jendela."
  },
  AvgDialog_118699_Content_41 = {
    Text = "Di saat-saat yang sangat jarang, seseorang mungkin melihat di balik jendela itu, ada seorang wanita berskin cokelat yang bersandar di ambang jendela, lembut memeluk pot tanaman muda itu."
  },
  AvgDialog_118699_Content_42 = {
    Text = "Bahkan sekarang ketika kegiatan klub mulai kembali aktif, ruang musik milik master pertunjukan ini masih tidak ada yang berani mengganggu."
  },
  AvgDialog_118699_Content_44 = {
    Text = "Tirai tertiup lembut oleh angin malam, Hameln berdiri di depan piano, menatap ke arah menara jam."
  },
  AvgDialog_118699_Content_45 = {
    Text = "Di depan tuts piano yang pernah kita mainkan bersama, tidak ada seorang pun, hanya suara seruling yang dimainkan berulang-ulang setiap hari, dengan tenang melayang di bawah sinar bulan, tanpa ada yang mendengarkan."
  },
  AvgDialog_118699_Content_46 = {
    Text = "Di kedalaman Kolam hitam, seorang narapidana yang kesepian selamanya di balik pintu kini memiliki teman yang terlelap."
  },
  AvgDialog_118699_Content_47 = {
    Text = "Sepasang mata berbelas kasih itu membuka dengan diam, menatap jiwa yang mengembara di jauh."
  },
  AvgDialog_118699_Content_48 = {
    Text = "Di laboratorium departemen penelitian, Ramona, yang sedang berlatih kekuatan roh siang dan malam, peluhnya sudah membasahi pakaian latihannya."
  },
  AvgDialog_118699_Content_49 = {
    Text = "Doll menatap sosok yang berjuang dengan gigih itu, diam-diam meneguk segelas kopi pekat, membuka laporan eksperimen halaman baru, melanjutkan penyesuaian data alat."
  },
  AvgDialog_118699_Content_5 = {
    Text = "Kek... saya baik-baik saja, terputus tepat waktu."
  },
  AvgDialog_118699_Content_50 = {
    Text = "<Small:Aah, kopi Winkle memang sedikit terlalu kuat……>"
  },
  AvgDialog_118699_Content_51 = {
    Text = "Di alat komunikasi yang baru saja dia letakkan, berkedip sebuah notifikasi yang dikirim ke semua awakener."
  },
  AvgDialog_118699_Content_52 = {
    Text = "Semua awakener di kampus, pada saat yang sama melihat ke pemancar yang tiba-tiba berbunyi, melihat nama yang telah lama mereka tunggu di dalam pemancar."
  },
  AvgDialog_118699_Content_53 = {
    Text = [[
Kepada semua awakener:

Baru-baru ini, kita masih melawan bencana hitam yang menelan segalanya, hingga kini di batu nisan keyflare, masih terukir banyak nama yang kabur, serta nama Penjaga yang membawa kita menuju perdamaian abadi.
Mereka adalah teman kita, rekan kita, siswa Mythag yang sering bolos, banyak dari mereka adalah sahabat istimewa, penunjuk jalan kita yang unik, dan juga pahlawan yang menyelamatkan kita semua.]]
  },
  AvgDialog_118699_Content_54 = {
    Text = [[
Setelah kehilangan {Male=dia,Female=dia}, Mythag kehilangan satu warna yang kuat, di tengah kesedihan yang sama, departemen penelitian tidak menyerah pada harapan yang tipis, tetap mencari jejak kesadaran Penjaga. 
 Awalnya, sebelum memastikan keberhasilan, saya tidak ingin memberikan harapan yang tidak diketahui kepada kalian, hanya menambah penderitaan menunggu yang panjang. Tapi sekarang, kita telah memverifikasi metode untuk menemukan <Yellow:%player%>, dan akan segera memulai upaya terakhir.]]
  },
  AvgDialog_118699_Content_55 = {
    Text = [[
Pertempuran menyambut kembalinya {Male=dia,Female=dia} membutuhkan kalian, membutuhkan kita semua untuk bersama-sama, mengubah kerinduan kita terhadap {Male=dia,Female=dia} menjadi penanda untuk menemukan {Male=dia,Female=dia}.
Saya mewakili Mythag dengan tulus mengundang kalian semua, untuk bersama-sama datang ke Kolam Hitam sebelum ini, seperti pada saat pertempuran terakhir, untuk bertarung berdampingan lagi demi <Yellow:%player%>.

Rekan tempur kalian, Dole]]
  },
  AvgDialog_118699_Content_56 = {
    Text = [[
Dunia Kadath
Hari perjanjia]]
  },
  AvgDialog_118699_Content_57 = {
    Text = "Di bawah tanah terlarang menara jam, di depan kolam hitam yang tenang, berdiri kerumunan orang-orang yang diam."
  },
  AvgDialog_118699_Content_58 = {
    Text = "Setelah Doll menjelaskan prinsip perjalanan dimensi, awakener yang awalnya ribut ingin pergi semua berdiri diam di samping resonator spiritual."
  },
  AvgDialog_118699_Content_59 = {
    Text = "Karena sifat spiritual dari ruang dimensi, semakin banyak Tubuh roh yang muncul bersama, hanya akan menarik lebih banyak perhatian dari keberadaan tingkat tinggi, dan Penjaga di sisi itu akan semakin sulit untuk bertahan."
  },
  AvgDialog_118699_Content_6 = {
    Text = "Mengapa... baru saja aku jelas-jelas mendengar suara {Male=dia,Female=dia}, tetapi mengapa aku masih tidak bisa menemukan {Male=dia,Female=dia}?"
  },
  AvgDialog_118699_Content_60 = {
    Text = "Di hadapan kerumunan, Ramona memegang sekuntum mawar layu, diam-diam menatap Kolam hitam, dengan telapak tangan lainnya, mengenggam erat kunci perak bernomor 0617."
  },
  AvgDialog_118699_Content_61 = {
    Text = "Alat sudah siap untuk diaktifkan, semua orang berfokus."
  },
  AvgDialog_118699_Content_62 = {
    Text = "Kaki penjepit menekan tombol, gelombang emosional menyebar seperti riak air, mengumpulkan pikiran semua orang menjadi benang, menyusun jaring raksasa yang menghubungkan."
  },
  AvgDialog_118699_Content_63 = {
    Text = "Ramona dengan serius membuka telapak tangannya, kunci perak perlahan terangkat dalam gaya aneh, mengapung di tengah jaring tak kasat mata, berkilau dengan cahaya seakan bernapas."
  },
  AvgDialog_118699_Content_64 = {
    Text = "Semua orang memandang kunci itu, berdoa dalam hati."
  },
  AvgDialog_118699_Content_65 = {
    Text = "Sekolah ini, orang-orang di sini, semua membutuhkanmu. Baik itu satu tahun, dua tahun, sepuluh tahun... selama penelitian masih berarti, kami pasti akan menjemputmu kembali."
  },
  AvgDialog_118699_Content_66 = {
    Text = "Tuanku, saya sudah bisa bertahan selama 40 detik dalam keadaan terputus tautan, sekarang saya bisa melindungi Tuanku dengan lebih baik, sungguh ingin menunjukkan hasil latihan saya kepada Anda…"
  },
  AvgDialog_118699_Content_67 = {
    Text = "Kelahiran baru di Mythag tidak ada yang sekuat dirimu, kapan kau akan membiarkanku merasakan sekali lagi pertempuran di bawah komando mu?"
  },
  AvgDialog_118699_Content_68 = {
    Text = "Aigis mendengarkan dengan baik, makan dengan baik. Aku telah membuatkan banyak scarf, topi, sarung tangan, dan berbagai sweater untuk {Male=Tuan Penjaga Rahasia,Female=Nona Penjaga Rahasia}. Apakah {Male=Tuan Penjaga Rahasia,Female=Nona Penjaga Rahasia} akan menyukainya?"
  },
  AvgDialog_118699_Content_69 = {
    Text = "Orang daerah barat, janji untuk mengajarimu rahasia bertahan hidup di daerah timur belum kamu pelajari sepenuhnya, aku sudah mengambil uang sekolahnya, cepat kembali, jangan biarkan reputasi bisnis si pencuri ini rusak..."
  },
  AvgDialog_118699_Content_7 = {
    Text = "Memang, \"Hati Suci\" hanya dapat merasakan {Male=arahnya, Female=arahnya} secara kasar, tetapi tidak dapat menemukan koordinat yang lebih rinci."
  },
  AvgDialog_118699_Content_70 = {
    Text = "Penjaga {Male=tuan,Female=nyonya}, saya percaya orang baik akan mendapatkan perlindungan keberuntungan, orang seperti Anda pasti akan memiliki akhir yang bahagia."
  },
  AvgDialog_118699_Content_71 = {
    Text = "Saudaraku{Male=Tuan Penjaga Rahasia,Female=Nona Penjaga Rahasia}, Lily sudah bisa membaca banyak cerita, ketika kamu kembali, bisakah kita membuat film tentang Saudaraku{Male=Tuan Penjaga Rahasia,Female=Nona Penjaga Rahasia} dan Lily?"
  },
  AvgDialog_118699_Content_72 = {
    Text = "Prajurit yang kembali dengan kemenangan, seharusnya kembali ke {Male=kampung halamannya,Female=kampung halamannya}."
  },
  AvgDialog_118699_Content_73 = {
    Text = "Segera kembali, pelayan bodoh, Anda berhutang padaku banyak sore teh, semua itu harus dibayar kembali dengan baik!"
  },
  AvgDialog_118699_Content_74 = {
    Text = "Kau pernah bertanya padaku, apa keinginanku... sekarang aku akhirnya memiliki keinginanku sendiri, yaitu berharap kau bisa kembali dengan selamat."
  },
  AvgDialog_118699_Content_75 = {
    Text = "Pohon kecil yang tidak bisa dipercaya, di dunia baru yang kau janjikan, tidak boleh tidak ada dirimu..."
  },
  AvgDialog_118699_Content_76 = {
    Text = "Ras kami tidak akan meninggalkan anggota yang tersisa."
  },
  AvgDialog_118699_Content_77 = {
    Text = "Suara seruling saya, selamanya menunggu Anda."
  },
  AvgDialog_118699_Content_78 = {
    Text = "Semua awakener mengucapkan nama yang akrab itu dalam hati, kekuatan roh bersinar seperti kunang-kunang mengalir ke dalam kunci perak yang melayang, bagian tengah kunci perak perlahan bersinar seperti bintang."
  },
  AvgDialog_118699_Content_79 = {
    Text = "<pollux> dan <castor> bertukar pandang， saling mengangguk， tubuh <castor> sekejap berubah menjadi aliran cahaya， menyatu ke dalam dada <pollux>."
  },
  AvgDialog_118699_Content_8 = {
    Text = "Namun, keinginan kuat yang terakhir dari Nona Ramona membuat \"Hati Suci\" merasa lebih jelas terhadap <Yellow:%player%>."
  },
  AvgDialog_118699_Content_80 = {
    Text = "Aura hijau-biru mengalir dalam hati suci, di belakang Pollux, sepasang sayap biru tua yang indah tiba-tiba terbentang, dia mengulurkan jari telunjuknya dan jantung suci bersinar menyala bersamaan dengan cahaya kunci perak."
  },
  AvgDialog_118699_Content_81 = {
    Text = "Nona Ramona."
  },
  AvgDialog_118699_Content_82 = {
    Text = "Menghadapi tatapan Pollux yang serius, Ramona menggenggam mawar yang mulai bersinar di tangannya, itu adalah sinyal yang dia sepakati bersama Penjaga."
  },
  AvgDialog_118699_Content_83 = {
    Text = "Kekuatan roh yang telah berlatih ribuan kali perlahan-lahan terkonstruksi mengikuti petunjuk yang familiar, dia mengangkat kepalanya menatap kunci perak itu, mengarahkan suara hatinya ke pusat kunci bersama dengan semua orang."
  },
  AvgDialog_118699_Content_84 = {
    Text = "(<Yellow:%player%>, tunggu aku, aku akan segera menjemputmu pulang.)"
  },
  AvgDialog_118699_Content_9 = {
    Text = "Jika mengumpulkan lebih banyak kekuatan roh yang kuat yang mengarah ke <Yellow:%player%>, mungkin akan lebih akurat untuk merasakan posisi %player%."
  },
  AvgDialog_118700_Content_1 = {
    Text = "Sebuah pelukan sesaat"
  },
  AvgDialog_118700_Content_10 = {
    Text = "Kebisingan di sekitar menghilang. Di dalam pikirannya, ramona menatap dirinya yang jauh di sana."
  },
  AvgDialog_118700_Content_11 = {
    Text = "Kekuatanmu lebih besar dari padaku... mungkin, tugas kali ini seharusnya kau yang melakukannya, agar lebih aman..."
  },
  AvgDialog_118700_Content_12 = {
    Text = "Merasa apa yang ada dalam hati Ramona, ramona: timeworn menggelengkan kepala, dan mengangkat kedua matanya yang tertutup dan menatap jurang itu diam-diam."
  },
  AvgDialog_118700_Content_13 = {
    Text = "Saya hanya datang untuk mengantar, dalam perjalanan dimensi yang jauh ini, saya dan Anda tidak ada bedanya, terlebih lagi..."
  },
  AvgDialog_118700_Content_14 = {
    Text = "Kamu adalah {Male=rekannya, Female=rekannya} ini, ini adalah takdir kalian, bukan milikku."
  },
  AvgDialog_118700_Content_15 = {
    Text = "Pergilah, bawa kembali {Male=dia, Female=dia}, \"Ramona\"."
  },
  AvgDialog_118700_Content_16 = {
    Text = "Ramona menggenggam tangan mawar dengan kuat, setelah beberapa saat, dia mengangguk dengan serius, duduk di dalam alat pemisahan roh diiringi tatapan dirinya yang lain."
  },
  AvgDialog_118700_Content_17 = {
    Text = "Mata fisik tertutup rapat, sepasang mata lain perlahan membuka, sebuah jiwa yang padat terlepas dari tubuh, diselimuti cahaya bercahaya dari \"Hati Suci\" Pollux yang berwarna putih samar seperti kabut."
  },
  AvgDialog_118700_Content_18 = {
    Text = "Di bawah tatapan puluhan pasang mata, Ramona menoleh, bertatapan satu per satu dengan rekan-rekannya, dan memikul harapan yang berat itu."
  },
  AvgDialog_118700_Content_19 = {
    Text = "Di bawah petunjuk kerinduan itu, dia berbalik dan melompat ke dalam pusaran besar. Pintu masuknya seperti gerbang Neraka, sekejap menelan jiwa yang rapuh."
  },
  AvgDialog_118700_Content_2 = {
    Text = "Malaikat yang tergantung menurunkan cahaya ilahi, menunggu untuk membawa jiwa yang tersesat ke sisi Tuhan."
  },
  AvgDialog_118700_Content_3 = {
    Text = "Doll dan Ramona saling bertatapan, mengaktifkan alat raksasa yang hampir menutupi sebagian besar Kolam Hitam. Dalam guncangan hebat air kolam, pusaran besar runtuh dengan gemuruh, menciptakan sebuah jurang seolah-olah siap untuk menelan segalanya."
  },
  AvgDialog_118700_Content_4 = {
    Text = "Itu adalah..."
  },
  AvgDialog_118700_Content_5 = {
    Text = "Air kolam yang megah seolah mengalir ke dunia lain, di dalam pusaran yang dalam tak terhingga, keberadaan dunia mulai menjadi kabur."
  },
  AvgDialog_118700_Content_6 = {
    Text = "Di tepi dunia ini, ada pintu masuk menuju Dimensi."
  },
  AvgDialog_118700_Content_7 = {
    Text = "Di balik jurang, {Male=Dia,Female=Dia} sedang menunggumu."
  },
  AvgDialog_118700_Content_8 = {
    Text = "Ramona mengangguk. Sebelum melangkah ke jurang, dia tiba-tiba berhenti, memandang kerumunan."
  },
  AvgDialog_118700_Content_9 = {
    Text = "Sebuah sosok yang tidak tampak, berdiri diam di belakang kerumunan yang sedang berdoa. Itu adalah sosok yang tersembunyi di dalam kesadarannya, hanya dia yang bisa melihatnya."
  },
  AvgDialog_118701_Content_1 = {Text = "Menunggu"},
  AvgDialog_118701_Content_10 = {
    Text = "Kabut berkumpul dan menghilang, seorang pengunjung tetap dari Mythag muncul di pintu Kolam hitam, berdiri diam di samping doll, melihat sosok yang duduk di depan \"pintu\"."
  },
  AvgDialog_118701_Content_11 = {
    Text = "Kontak lama dengan kolam tidak baik untuk tubuh, apakah kamu tidak membatasi dia?"
  },
  AvgDialog_118701_Content_12 = {
    Text = "Saya memberinya perlindungan dasar, selain itu saya masih bisa menyembuhkan kerusakan tubuh, sedangkan kerusakan mental tidak semudah itu untuk disembuhkan."
  },
  AvgDialog_118701_Content_13 = {
    Text = "Profesor rasionalitas menghela napas, memutar kembali dengan penuh penyelidikan."
  },
  AvgDialog_118701_Content_14 = {
    Text = "Kau jarang mau datang ke sini, kali ini apa yang kau bawa?"
  },
  AvgDialog_118701_Content_15 = {
    Text = "Ah, sebuah kabar baik yang pas untuk menyembuhkan jiwanya."
  },
  AvgDialog_118701_Content_16 = {
    Text = "Rekan, berkat tindakanmu, celah pelarutan di seluruh dunia baru-baru ini telah berkurang sangat banyak."
  },
  AvgDialog_118701_Content_17 = {
    Text = "Para penyelidik di sekolah mulai merasa santai, semua orang hanya mengikuti pelajaran dan ujian setiap hari, Mythag semakin mirip sebagai universitas biasa."
  },
  AvgDialog_118701_Content_18 = {
    Text = "Seseorang mengusulkan untuk membangun sebuah patung untukmu, tepat di sebelah Kepala Sekolah Ward, saat ini pihak sekolah masih mempertimbangkan."
  },
  AvgDialog_118701_Content_19 = {
    Text = "Saya mengajukan saran yang tidak didukung, kamu jelas masih di sini, mengapa kamu harus dibuat menjadi patung seperti kepala sekolah?"
  },
  AvgDialog_118701_Content_2 = {
    Text = [[
Dunia Kadath
Sebelum pemakaman Penjaga]]
  },
  AvgDialog_118701_Content_20 = {
    Text = "Setelah itu, saat kau kembali dan melihat dirimu yang besar berdiri di samping kepala sekolah, pasti akan sangat canggung sampai tidak bisa berbicara."
  },
  AvgDialog_118701_Content_21 = {
    Text = "Ekspresimu begitu tenang, aku tidak percaya... kamu pasti tersesat di dunia lain dan lupa bagaimana cara kembali..."
  },
  AvgDialog_118701_Content_22 = {
    Text = "Kamu benar, {Male=Dia,Female=Dia} memang telah memasuki dimensi lain, dimensi yang sangat jauh."
  },
  AvgDialog_118701_Content_23 = {
    Text = "Mendengar suara daffodil yang tiba-tiba muncul di belakang, ramona hampir kehilangan kendali dan berdiri, hampir tidak bisa menahan diri untuk tidak meraih lengan pemilik toko."
  },
  AvgDialog_118701_Content_24 = {
    Text = "Apa yang kamu katakan? Apakah kamu menemukan {Male=dia, Female=dia}? Dimensi... Saya ingat kamu bisa melintasi dimensi!"
  },
  AvgDialog_118701_Content_25 = {
    Text = "Bagaimana cara membawa {Male=dia,Female=dia} kembali? Aku bersedia membayar dengan harga berapa pun!"
  },
  AvgDialog_118701_Content_26 = {
    Text = "Setelah memohon dengan tidak bisa menyembunyikan rasa bersemangat, Ramona baru menyadari bahwa doll di sampingnya tidak tersenyum."
  },
  AvgDialog_118701_Content_27 = {Text = "……Apa?"},
  AvgDialog_118701_Content_28 = {
    Text = "Meskipun tekadmu sangat mengharukan, sayangnya, itu adalah dimensi yang tidak terhubung dengan dunia ini, dan aku juga tidak bisa membawa Penjaga melintasi ruang dimensi yang tidak dikenal."
  },
  AvgDialog_118701_Content_29 = {
    Text = "Jika tidak ada jalur yang pasti, berkeliaran secara acak dalam badai dimensi hanya akan mengarah pada kebingungan."
  },
  AvgDialog_118701_Content_3 = {
    Text = "Dengan satu dengung selesai pengecekan, banyak instrumen lagi menunjukkan hasil yang sama sekali tidak responsif, doll diam-diam melambai, para peneliti saling memandang, secara diam-diam mulai membongkar instrumen."
  },
  AvgDialog_118701_Content_30 = {
    Text = "Dengan teknologi yang ada di Mythag, itu juga tidak dapat dilakukan."
  },
  AvgDialog_118701_Content_31 = {
    Text = "Apa maksudnya... kita sudah mencoba begitu lama, akhirnya mendapatkan berita tentang {Male=dia,Female=dia}, apa kita harus membiarkan {Male=dia,Female=dia} terdampar sendirian?!!"
  },
  AvgDialog_118701_Content_32 = {
    Text = "Kemungkinan saya masih bisa mendiskusikan keterampilan berpindah dimensi dengan Profesor Doll, dianggap sebagai hadiah gratis untuk pelanggan lama."
  },
  AvgDialog_118701_Content_33 = {
    Text = "Namun untuk mengembalikan <Yellow:%player%>, yang paling sulit adalah bagaimana menemukan jalan menuju dunia itu, bahkan dalam koleksiku, tidak ada barang luar biasa yang melampaui alam semesta seperti itu."
  },
  AvgDialog_118701_Content_34 = {
    Text = "Saya akan membuat departemen penelitian segera berfokus pada penelitian dimensi mulai hari ini."
  },
  AvgDialog_118701_Content_35 = {
    Text = "Antara dimensi dan dimensi, kadang-kadang tidak akan ada persilangan selamanya, tidak bisa ditemukan hanya melalui pengeksplorasian."
  },
  AvgDialog_118701_Content_36 = {
    Text = "Apa yang harus kalian hadapi mungkin adalah upaya yang panjang tanpa harapan."
  },
  AvgDialog_118701_Content_37 = {
    Text = "Kami tidak akan menyerah."
  },
  AvgDialog_118701_Content_39 = {
    Text = "Aku mengerti, apapun yang terjadi, aku akan menunggu {Male=dia, Female=dia}."
  },
  AvgDialog_118701_Content_4 = {
    Text = "Kenapa harus menyimpan alatnya? Coba lagi, pasti masih ada metode uji yang belum terpikirkan……"
  },
  AvgDialog_118701_Content_40 = {
    Text = [[
Dunia Kadath
Sepuluh bulan setelah pemakaman Penjaga
Kolam hitam]]
  },
  AvgDialog_118701_Content_41 = {
    Text = "Suara langkah yang kosong melintasi pintu-pintu yang terhalang lapisan, menginjak gelombang air yang kental, air kolam hitam yang sunyi menyambut pengunjung kedua hari ini."
  },
  AvgDialog_118701_Content_42 = {
    Text = "Saya sudah tahu bahwa kamu ada di sini lagi."
  },
  AvgDialog_118701_Content_43 = {
    Text = "Orang yang diajak bicara profesor tidak menjawab, sosok yang tak bergerak itu terus menghadap ke arah ‘pintu’, bak patung yang mengawasi."
  },
  AvgDialog_118701_Content_44 = {
    Text = "Hari ini lagi-lagi ada orang yang mengirimkan saran kepada saya, ini adalah penolakan ke-7 Anda untuk tugas berpasangan, tetap melaksanakan misi penyelidikan sendiri, bukan?"
  },
  AvgDialog_118701_Content_46 = {
    Text = "Tidak apa-apa, aku tidak datang untuk mengkritik atau memerintahkanmu, apalagi memberikan nasihat, meskipun Sylvia mengatakan bahwa evaluasi psikologismu memang ada sedikit masalah."
  },
  AvgDialog_118701_Content_47 = {
    Text = "Namun, di universitas ini, berapa banyak orang yang benar-benar tidak memiliki masalah?"
  },
  AvgDialog_118701_Content_48 = {
    Text = "Kaki bercakar yang berwarna pink berdiri di samping patung, menghadap sosok yang selalu tertidur itu."
  },
  AvgDialog_118701_Content_49 = {
    Text = "Apakah ada tugas khusus yang perlu saya jalankan?"
  },
  AvgDialog_118701_Content_5 = {
    Text = "Jumlah deteksi dan frekuensi sudah cukup banyak, kursus penggunaan peralatan perakmu adalah nilai penuh, jangan lagi menipu diri sendiri, Ramona."
  },
  AvgDialog_118701_Content_50 = {
    Text = "Patung yang kehilangan reaksi akhirnya membuka suara, nada suaranya tenang seperti mesin."
  },
  AvgDialog_118701_Content_51 = {Text = "Ada."},
  AvgDialog_118701_Content_52 = {
    Text = "Syarat misi?"
  },
  AvgDialog_118701_Content_53 = {
    Text = "Kamu perlu pergi ke tempat yang sangat berbahaya untuk menjemput rekanmu."
  },
  AvgDialog_118701_Content_54 = {
    Text = "Saya tidak perlu......"
  },
  AvgDialog_118701_Content_55 = {
    Text = "Orang itu sebelumnya."
  },
  AvgDialog_118701_Content_56 = {
    Text = "Ramona tiba-tiba berbalik, menatap intens ke mata kosong si boneka."
  },
  AvgDialog_118701_Content_57 = {
    Text = "Misi kali ini adalah sebuah perjudian, juga dengan tingkat bahayanya yang tanpa precedent, sepertinya bantuan di dalam sekolah tidak bisa pergi bersamamu..."
  },
  AvgDialog_118701_Content_58 = {
    Text = "Apakah departemen penelitian sudah mendapatkan hasil? Kapan?"
  },
  AvgDialog_118701_Content_59 = {
    Text = "Doll tersenyum, menyerahkan laporan penelitian yang baru dibuatnya kepada orang itu."
  },
  AvgDialog_118701_Content_6 = {
    Text = "{Male=Dia,Female=Dia}Yang tertinggal di sini hanyalah sebuah tubuh kosong, tanpa adanya gelombang kehidupan, kesadaran Penjaga... mungkin telah lenyap."
  },
  AvgDialog_118701_Content_60 = {
    Text = "Sejak Daffodil memberi tahu kita tentang berita Penjaga, departemen penelitian telah mencoba semua teknologi yang ada, tidak terduga bahwa terobosan terakhir ada pada awakener."
  },
  AvgDialog_118701_Content_61 = {
    Text = "Kami menemukan bahwa \"Hati Suci\" Pollux dapat menarik keberadaan itu; Gereja penerang kuil awalnya menciptakan \"Hati Suci\" untuk menghasilkan jiwa yang murni dan menyebarkan darah Dewa."
  },
  AvgDialog_118701_Content_62 = {
    Text = "Pengorbanan akhirnya pada Sang Putra, memanggil apa yang disebut Tanah Suci."
  },
  AvgDialog_118701_Content_63 = {
    Text = "Sebenarnya, prinsipnya adalah menarik perhatian si dia, sehingga memperluas pelarutan. Setelah pemrosesan terarah, \"Hati Suci\" sangat mungkin dapat secara khusus menuntun kita ke lokasi Penjaga."
  },
  AvgDialog_118701_Content_64 = {
    Text = "Pihak sekolah berencana mengirimkan kesadaran dengan kekuatan roh yang baik ke ruang dimensi, mengikuti petunjuk \"Hati Suci\" untuk melintasi dimensi dan membangun tautan terowongan antara dua dunia."
  },
  AvgDialog_118701_Content_65 = {
    Text = "Jika semua data pengujian berjalan lancar, dalam waktu kurang dari sebulan, kita bisa mulai mencobanya."
  },
  AvgDialog_118701_Content_66 = {
    Text = "Tugasmu selanjutnya akan menambah bagian pelatihan kekuatan roh, semoga kamu... tidak terlalu rajin, agar tidak merusak otak."
  },
  AvgDialog_118701_Content_67 = {
    Text = [[
Dunia Kadath
Setahun setelah pemakaman Penjaga
Kolam hitam]]
  },
  AvgDialog_118701_Content_68 = {
    Text = "Alat pemisah roh yang berputar cepat mengeluarkan alarm merah yang tidak dapat diatasi, dan orang yang mengamati di samping segera menekan tombol penghentian."
  },
  AvgDialog_118701_Content_69 = {
    Text = "Pintu kabin yang berisi pengguna tiba-tiba terbuka, Ramona yang sudah hampir pingsan menggerakkan jarinya, dibantu cepat oleh dua peneliti."
  },
  AvgDialog_118701_Content_7 = {
    Text = "Vonis yang kejam akhirnya jatuh dari mulut boneka, melihat air mata yang mengalir dari mata Ramona yang tercengang, profesor yang terbiasa dengan pengorbanan pun tak tahan menutup matanya."
  },
  AvgDialog_118701_Content_70 = {
    Text = "Dukung dia, cepat masuk ke cairan dingin roh!"
  },
  AvgDialog_118701_Content_71 = {
    Text = "Air kolam berwarna hijau pucat merendam hingga dada, suhu yang tinggi seperti demam pada Ramona akhirnya turun, kedua matanya yang dulunya rasional, kini tampak terobsesi, perlahan terbuka."
  },
  AvgDialog_118701_Content_72 = {
    Text = "Meskipun lusa adalah tanggal percobaan resmi pertama, kamu tidak boleh mengambil risiko dengan tubuhmu seperti itu."
  },
  AvgDialog_118701_Content_73 = {
    Text = "Tidak apa-apa， saya bisa menghadapinya…"
  },
  AvgDialog_118701_Content_74 = {
    Text = "Pollux yang keluar dari alat di samping juga diam-diam mendekat ke dua orang, menyela lebih banyak nasehat dari doll."
  },
  AvgDialog_118701_Content_75 = {
    Text = "Saya bisa memahami rasa sakit karena kehilangan orang penting, dan kebencian terhadap diri sendiri yang merasa tidak berdaya…… Tenang saja, Nona Ramona."
  },
  AvgDialog_118701_Content_76 = {
    Text = "Sekarang \"Hati Suci\" sudah bisa merasakan panggilan lampu terang itu, saya dan castor akan memberikan semua kekuatan untuk menemukan pemberi manfaat bersama Anda."
  },
  AvgDialog_118701_Content_8 = {
    Text = "Siapkan pemakaman untuk <Yellow:%player%>, surat wasiat itu... biar kau yang membacanya untuk {Male=dia, Female=dia}."
  },
  AvgDialog_118701_Content_9 = {
    Text = [[
Dunia Kadas
Tiga bulan setelah pemakaman Penjaga]]
  },
  AvgDialog_118702_Content_1 = {
    Text = "Pesan dari jauh"
  },
  AvgDialog_118702_Content_10 = {
    Text = "Kamu melambai-lambaikan tanganmu seperti orang buta, berusaha melangkah, seperti seorang pelancong yang berusaha melintasi air, merangkak di dalam kegelapan yang lengket, mencari jalan."
  },
  AvgDialog_118702_Content_100 = {
    Text = "Di sini tidak ada suhu yang membara, hanya ada kegelapan lengket yang tak ada habisnya. Ketika melaju ke depan, baik maju maupun mundur mulai kabur, seolah keberadaan juga berubah menjadi kekosongan."
  },
  AvgDialog_118702_Content_101 = {
    Text = "Terus maju, jangan menoleh ke belakang."
  },
  AvgDialog_118702_Content_102 = {
    Text = "Kamu mempercayai suara itu, berusaha mengosongkan pikirannya dan terus maju, sampai warna-warna ajaib membuatmu terjebak dalam pusing yang hebat."
  },
  AvgDialog_118702_Content_103 = {Text = "……Ini!"},
  AvgDialog_118702_Content_104 = {
    Text = "Selain berdiri di lautan kekuatan kuno daffodil, kamu untuk pertama kalinya melihat dunia dari luar jagat raya."
  },
  AvgDialog_118702_Content_105 = {
    Text = "Seolah memasuki dunia mikroskopis, ruang kental, ribuan garis bergerak, bentuk roh yang aneh, galaksi yang berkilau jauh di sana…"
  },
  AvgDialog_118702_Content_106 = {
    Text = "Dan batas dunia yang tak berujung."
  },
  AvgDialog_118702_Content_107 = {
    Text = "Jika tidak ada cukup titik jangkar roh, di ruang yang kacau dan tak terbatas ini, kamu akan cepat tersesat, tapi di hatimu, tidak ada banyak ketakutan."
  },
  AvgDialog_118702_Content_108 = {
    Text = "Sudah siap? Setelah kau mulai tautan, aku akan berusaha membuat kebisingan untuk menarik perhatian-Nya, sisanya adalah pertarunganmu."
  },
  AvgDialog_118702_Content_109 = {
    Text = "Kau menggenggam kunci perak di dadamu, dengan serius dan penuh kasih sayang mengulurkan tentakel jiwa menuju mawar yang mekar di tanganmu."
  },
  AvgDialog_118702_Content_11 = {
    Text = "Akhirnya... aku menemukannmu! Kita @3... melalui @2 terowongan..."
  },
  AvgDialog_118702_Content_110 = {
    Text = "Mari kita mulai."
  },
  AvgDialog_118702_Content_111 = {
    Text = "Gelombang besar kekuatan spiritual mengguncang ruang dimensi, dalam batas sensasi tentakel spiritualmu, sebuah celah tiba-tiba muncul memecahkan ruang."
  },
  AvgDialog_118702_Content_112 = {
    Text = "Sebuah pupil raksasa tiba-tiba muncul di belakang celah, seperti mata raksasa yang tiba-tiba terbuka."
  },
  AvgDialog_118702_Content_12 = {
    Text = "Kamu tidak dapat melihat sosoknya, hanya dapat mendengar suara yang terputus-putus. Orang yang kamu kenal juga bersemangat, menceritakan kebahagiaan perjumpaan setelah lama berpisah."
  },
  AvgDialog_118702_Content_13 = {
    Text = "Kamu bisa merasakan bahwa ada sebuah tali yang nyata menghubungkan kalian, seolah-olah jika mengikuti tali itu, kamu dapat menemukan arah pulang."
  },
  AvgDialog_118702_Content_14 = {
    Text = "Saat kamu terus maju mengikuti petunjuk tali itu, suara retakan tiba-tiba terdengar, seluruh ruang bergetar di tengah guncangan hebat."
  },
  AvgDialog_118702_Content_15 = {
    Text = "Ada sesuatu yang sedang menyerang @2, Pusat Suci sudah tidak bisa bertahan lagi!"
  },
  AvgDialog_118702_Content_16 = {
    Text = "Ramona, putuskan tautan!"
  },
  AvgDialog_118702_Content_17 = {Text = "Tetapi!"},
  AvgDialog_118702_Content_18 = {
    Text = "Penjaga, cari Daffodil! Kami tidak akan menyerah—"
  },
  AvgDialog_118702_Content_19 = {
    Text = "Semua cahaya menghilang. Dari jarak yang jauh, ada sesuatu yang besar dan tidak diketahui mengubah arah dan perlahan menghilang ke dalam kekacauan."
  },
  AvgDialog_118702_Content_2 = {
    Text = "Penjaga@2... Penjaga..."
  },
  AvgDialog_118702_Content_20 = {Text = "!!!"},
  AvgDialog_118702_Content_21 = {
    Text = "Kau tiba-tiba duduk dari tempat tidur, di sekeliling masih di dalam ruangan basis doll: inferno, dinding bata merah yang akrab dan aroma disinfektan yang samar."
  },
  AvgDialog_118702_Content_22 = {
    Text = "Kau bertanya padaku apa yang terjadi? Sejak kapan bidang penelitian saya meluas ke analisis mimpi, bukankah seharusnya kau bertanya pada clementine?"
  },
  AvgDialog_118702_Content_23 = {
    Text = "Namun, kau benar, mengingat keunikan jiwamu, aku juga cenderung menganggap ini bukan ilusi yang kau alami, atau mimpi sederhana."
  },
  AvgDialog_118702_Content_24 = {
    Text = "Mengenai kunci kebenaran, apakah \"aku\" dalam mimpi tidak sudah memberitahumu?"
  },
  AvgDialog_118702_Content_25 = {
    Text = "Sebuah perak yang pernah Anda curi dikeluarkan oleh doll: inferno, dibuang ke dalam perangkat kebangkitan, dan muncul asap ungu yang samar dalam suara dengungan mesin."
  },
  AvgDialog_118702_Content_26 = {
    Text = "Eh, bertemu lagi, pelanggan lamaku?"
  },
  AvgDialog_118702_Content_27 = {
    Text = "Daffodil! Aku……"
  },
  AvgDialog_118702_Content_28 = {
    Text = "Hush, tidak perlu berbicara, seorang pedagang yang kompeten seharusnya bisa memahami apa yang diinginkan pelanggan."
  },
  AvgDialog_118702_Content_29 = {
    Text = "Saya memang sudah bertemu dengan teman-temanmu."
  },
  AvgDialog_118702_Content_3 = {
    Text = "Kamu seolah-olah tertutup dengan tirai panggung besar, terbungkus dalam lapisan-lapisan kain beludru tebal yang menekan tubuhmu, membuatmu tidak terlihat dan tidak bisa bergerak."
  },
  AvgDialog_118702_Content_30 = {Text = "?!"},
  AvgDialog_118702_Content_31 = {
    Text = "Melihat ekspresi terkejutmu, doll: inferno menggelengkan kepala."
  },
  AvgDialog_118702_Content_32 = {
    Text = "Saya pikir dengan otakmu, harus cukup untuk memikirkan kunci kekuatannya."
  },
  AvgDialog_118702_Content_33 = {
    Text = "Kunci dari kekuatan......?"
  },
  AvgDialog_118702_Content_34 = {
    Text = "Kau teringat lautan abu yang penuh kepala."
  },
  AvgDialog_118702_Content_35 = {
    Text = "Ruang dimensi? Apakah kamu bilang, daffodil bisa melintasi dunia yang berbeda... apakah mereka orang yang sama?"
  },
  AvgDialog_118702_Content_36 = {
    Text = "Sudah dekat, anak cerdas, saya di sini dan saya di sana, memang merupakan \"keberadaan\" yang sama, tetapi Anda lupa, kita bukan manusia."
  },
  AvgDialog_118702_Content_37 = {
    Text = "Daffodil melengkungkan matanya dengan penghayatan, membalikkan pergelangan tangannya dan menggoyangkan pipa yang dia pegang."
  },
  AvgDialog_118702_Content_38 = {
    Text = "Kami hanyalah wajah yang muncul di permukaan laut; lautan kabut abu yang mengalir di antara celah-celah di semua dimensi itulah yang menjadi keberadaan kami."
  },
  AvgDialog_118702_Content_39 = {
    Text = "Kami dapat terhubung secara spiritual, tetapi tidak berarti kami adalah \"orang\" yang sama."
  },
  AvgDialog_118702_Content_4 = {
    Text = "Di dalam mimpi hitam yang kosong, suara samar rippling seperti gelombang air datang dan segera menghilang."
  },
  AvgDialog_118702_Content_40 = {
    Text = "Artinya, Anda bisa melalui lautan kekuatan kuno untuk berpindah antar dunia? Dalam mimpi tadi, doll meminta saya untuk mencari Anda, yang berarti Anda sekarang bisa membawa saya kembali ke dunia itu?"
  },
  AvgDialog_118702_Content_41 = {
    Text = "Jangan terburu-buru, aku sudah bilang, bahkan aku, tidak bisa dengan mudah melakukan pergeseran dimensi antara dua dunia."
  },
  AvgDialog_118702_Content_42 = {
    Text = "Jika saya benar-benar memiliki cara seperti itu, mengapa saya harus menghematnya sampai sekarang?"
  },
  AvgDialog_118702_Content_43 = {
    Text = "Kau tertegun, perlahan menundukkan kepalamu."
  },
  AvgDialog_118702_Content_44 = {
    Text = "Namun, kali ini adalah teman-temanmu yang berani menemukan cara baru."
  },
  AvgDialog_118702_Content_45 = {
    Text = "Kau mendongak tiba-tiba, matamu bersinar kembali. Hal ini mengundang tawa lembut dari daffodil dan derai tawa dari doll: inferno."
  },
  AvgDialog_118702_Content_46 = {
    Text = "Sejak terakhir kali kita bertemu di dunia ini, aku telah memberitahukan mereka tentangmu."
  },
  AvgDialog_118702_Content_47 = {
    Text = "Setelah mengetahui keunikan dimensi ini, Doll telah bekerja keras dengan para peneliti Mythag siang dan malam, mencoba memetakan dunia ini. Baru-baru ini, mereka menemukan cara untuk menghubungkan dua dimensi."
  },
  AvgDialog_118702_Content_48 = {
    Text = "Apa yang baru saja kamu rasakan adalah hasil keberhasilan tautan mereka."
  },
  AvgDialog_118702_Content_49 = {
    Text = "Jadi itu bukan mimpi? Tautan roh itu nyata?!"
  },
  AvgDialog_118702_Content_5 = {
    Text = "Siapa? Ada yang memanggilku? Suara yang sangat familiar..."
  },
  AvgDialog_118702_Content_50 = {
    Text = "Iya, tetapi, keruntuhan yang baru saja terhubung itu juga nyata. Seharusnya kamu sudah memperhatikan keberadaan yang tiba-tiba datang itu."
  },
  AvgDialog_118702_Content_51 = {
    Text = "Melintasi dimensi sangat berbahaya, meskipun aku bisa membantumu menghindari pengejaran anjing pemburu, tetapi masih ada terlalu banyak entitas tinggi di ruang dimensi."
  },
  AvgDialog_118702_Content_52 = {
    Text = "Mereka biasanya memiliki wilayah aktivitas sendiri, seperti para raja yang menguasai negara mereka sendiri."
  },
  AvgDialog_118702_Content_53 = {
    Text = "Mungkin bisa dihindari dengan berbagai cara, tetapi sayangnya, yang menargetkan terowongan kali ini adalah musuh yang paling kamu kenal."
  },
  AvgDialog_118702_Content_54 = {
    Text = "Paling familiar... perasaan diperhatikan, Tohuwabohu? Dia sudah bangun?!"
  },
  AvgDialog_118702_Content_55 = {
    Text = "Tak perlu begitu tegang, hasil yang kau korbankan tidak akan mudah menghilang. Dia masih terjebak dalam tidurnya."
  },
  AvgDialog_118702_Content_56 = {
    Text = "Namun, Dia tetaplah Dia. Kalian dengan \"Hati Suci\" Pollux terlalu bersinar, bahkan ketika terjebak dalam tidur, bawah sadarnya juga memperhatikan kalian."
  },
  AvgDialog_118702_Content_57 = {
    Text = "Ekspresi Daffodil tiba-tiba serius, kamu terdiam, mengingat pertempuran yang mengorbankan segalanya itu."
  },
  AvgDialog_118702_Content_58 = {
    Text = "Syukurlah, kegaduhan perpindahan dimensi kali ini jauh lebih kecil dibandingkan dengan keributan yang dilakukan oleh Juliette sebelumnya. Tatapan yang dipancarkan oleh alam bawah sadarnya tidak sampai menghancurkan dunia ini."
  },
  AvgDialog_118702_Content_59 = {
    Text = "Meskipun begitu, kekuatan seperti itu bukanlah sesuatu yang bisa ditanggung oleh awak yang datang untuk menuntunmu. Jadi, untuk membangun tautan dimensi yang sempurna, orang-orang dari sisi itu tidak akan berhasil."
  },
  AvgDialog_118702_Content_6 = {
    Text = "Penjaga... Pasangan!"
  },
  AvgDialog_118702_Content_60 = {
    Text = "Aku membutuhkanmu, <Yellow:%player%>, untuk menarik perhatian-Nya di sini dan mengusir-Nya, melindungi mereka yang jauh di Dunia lain untuk membuka terowongan antara kedua dunia."
  },
  AvgDialog_118702_Content_61 = {
    Text = "Tatapan Tohuwabohu... itu Dia lagi..."
  },
  AvgDialog_118702_Content_62 = {
    Text = "Pertempuran itu begitu jauh, jauh seperti sesuatu yang terjadi di kehidupan sebelumnya."
  },
  AvgDialog_118702_Content_63 = {
    Text = "Pertempuran itu begitu dekat, dekat sehingga Anda dapat dengan mudah mengingat setiap detail di dalamnya."
  },
  AvgDialog_118702_Content_64 = {
    Text = "Setiap luka yang menyedihkan, setiap kemenangan yang menyiksa, setiap ketakutan yang menggigil, setiap teriakan putus asa mendekati kematian..."
  },
  AvgDialog_118702_Content_65 = {
    Text = "Menatap Dewa, telah menghabiskan semua keberanian dan hidupmu. Ketika mengingat tatapan yang melampaui aturan, suaramu tidak dapat ditahan mulai bergetar."
  },
  AvgDialog_118702_Content_66 = {
    Text = "Bahkan jika hanya pandangan bawah sadar yang terlempar, kekuatannya mungkin bukanlah sesuatu yang bisa aku halangi..."
  },
  AvgDialog_118702_Content_67 = {
    Text = "Sekarang saya tidak bisa sepenuhnya memanggil kekuatan tri-materi, juga tidak ada bantuan dari teman satu dimensi lainnya, ingin menghentikannya..."
  },
  AvgDialog_118702_Content_68 = {
    Text = "Bagaimana, penjaga kita yang berani, apakah kamu takut?"
  },
  AvgDialog_118702_Content_69 = {
    Text = "Kau mengeratkan kepalan tangan, menggelengkan kepala, menatap daffodil dengan serius."
  },
  AvgDialog_118702_Content_7 = {Text = "Ramona?!"},
  AvgDialog_118702_Content_70 = {
    Text = "Selama bisa kembali, tak ada ketakutan yang dapat menghentikanku. Aku hanya khawatir, khawatir akan kemampuanku saat ini tidak cukup."
  },
  AvgDialog_118702_Content_71 = {
    Text = "Jika saya gagal, Dia bahkan berisiko untuk terbangun kembali… Malapetaka seperti ini adalah sesuatu yang tidak bisa ditanggung oleh siapa pun."
  },
  AvgDialog_118702_Content_72 = {
    Text = "Baiklah. Tampaknya penjaga kita belum kehilangan keberanian untuk melawan dewa."
  },
  AvgDialog_118702_Content_73 = {
    Text = "Jangan khawatir, <Yellow:%player%>. Kali ini, saya juga akan membantu Anda membuka celah antara dimensi yang berbeda, membagi kekuatannya ke berbagai dimensi."
  },
  AvgDialog_118702_Content_74 = {
    Text = "Terakhir kali, penjaga dari dimensi lain pernah bertarung bersamamu, kali ini, mereka masih akan berperang dengan cara yang sama di tempat-tempat yang tak terlihat olehmu."
  },
  AvgDialog_118702_Content_75 = {
    Text = "Benarkah?! Jika demikian, kami, pasti akan memiliki kemampuan untuk menghentikan-Nya lagi!"
  },
  AvgDialog_118702_Content_76 = {
    Text = "Meskipun demikian, pertempuran pada tingkat ini akan menghancurkan seluruh dunia di sini oleh-Nya, kecuali <Yellow:%player%>, tidak ada yang selamat di dunia ini yang mampu menghadapi-Nya."
  },
  AvgDialog_118702_Content_77 = {
    Text = "Betul, jadi, pertempuran ini perlu dilakukan dalam ruang dimensi, bagaimana membuat <Yellow:%player%> bertahan lama di dalam ruang dimensi juga memerlukan bantuan seorang jenius."
  },
  AvgDialog_118702_Content_78 = {
    Text = "Tolong! Doll: Inferno!"
  },
  AvgDialog_118702_Content_79 = {
    Text = "……Hmph, satu dua orang tampaknya diatur dengan baik."
  },
  AvgDialog_118702_Content_8 = {
    Text = "Ketika kamu menyebut nama itu, suatu penghalang yang tidak terlihat langsung hancur, sebuah tautan yang intim dan hangat melintasi banyak waktu dan ruang, membentuk benang putih yang menempel dekat dadamu."
  },
  AvgDialog_118702_Content_80 = {
    Text = "Sudahlah, siapa yang membuat saya berjanji untuk membantumu pulang. Janji kepada anak anjing, akan saya tepati."
  },
  AvgDialog_118702_Content_81 = {
    Text = "Terima kasih!"
  },
  AvgDialog_118702_Content_82 = {
    Text = "Tidak perlu terburu-buru berterima kasih. Katakan dengan jelas, aku hanya bisa membuat kesadaranmu tertahan di ruang Dimensi, dan berusaha sebaik mungkin untuk membawamu kembali ke dunia ini."
  },
  AvgDialog_118702_Content_83 = {
    Text = "Mengenai pertarunganmu dengan dia... masih ada kemungkinan gagal bahkan mati."
  },
  AvgDialog_118702_Content_84 = {
    Text = "Saya tidak optimis dengan rencana impulsif seperti ini, meskipun begitu, apakah Anda juga ingin mengambil risiko besar ini dan mempertaruhkan hasil yang tidak diketahui?"
  },
  AvgDialog_118702_Content_85 = {
    Text = "Saya bersedia, mereka juga menanggung risiko yang sama untukku, saya tidak punya alasan untuk tidak membalas mereka. Bagaimanapun, meski terpisah oleh dua dunia, kami tetap bertempur berdampingan seperti dulu."
  },
  AvgDialog_118702_Content_86 = {
    Text = "Doll: inferno mengangguk tanpa rasa terkejut, Daffodil juga melihatmu dengan senyum, seolah tidak pernah memikirkan kemungkinan kamu akan mundur."
  },
  AvgDialog_118702_Content_87 = {
    Text = "Tahu sekali, sumpah yang begitu emosional ini sebaiknya diserahkan kepada rekan-rekan pertempuranmu. Aku butuh waktu untuk bersiap, mengenai bagaimana menandai waktu mulai tindakan, aku rasa kamu sudah punya cara?"
  },
  AvgDialog_118702_Content_88 = {
    Text = "Menanggapi pertanyaan doll: inferno, daffodil malah berpaling mengarahkan pandangannya padamu."
  },
  AvgDialog_118702_Content_89 = {
    Text = "Tentu saja, rekan Anda meminta saya untuk mengantarkan sebuah hadiah untuk Anda."
  },
  AvgDialog_118702_Content_9 = {
    Text = "Ini... tautan roh?! Ramona, apakah itu kamu? Di mana kamu?"
  },
  AvgDialog_118702_Content_90 = {
    Text = "Kabut mengepul, sebuah mawar yang tidak diketahui berasal dari mana disodorkan di depanmu."
  },
  AvgDialog_118702_Content_91 = {
    Text = "Ini... bunga yang Ramona berikan padaku...?!"
  },
  AvgDialog_118702_Content_92 = {
    Text = "Sangat disayangkan, saya belum memiliki kemampuan untuk mengirimkan benda nyata melintasi dimensi."
  },
  AvgDialog_118702_Content_93 = {
    Text = "Namun, di kedua dimensi ini, setiap benda pasti memiliki padanan masing-masing."
  },
  AvgDialog_118702_Content_94 = {
    Text = "Mawar ini berhubungan dengan yang Ramona berikan padamu di dimensi itu."
  },
  AvgDialog_118702_Content_95 = {
    Text = "Saya sudah melakukan sedikit penanganan terhadap bunga ini; ketika Anda siap, silakan sambungkan tautan roh pada bunga ini, mereka di sana akan menerima pesan."
  },
  AvgDialog_118702_Content_96 = {
    Text = "Dia berkata, ketika kalian bertemu, dia akan memakaikan bunga ini di dadamu."
  },
  AvgDialog_118702_Content_98 = {
    Text = "Kamu pertama kali tahu bahwa lorong yang digunakan oleh doll: inferno ketika meninggalkan dunia adalah matahari yang telah menghilang di atas kepala."
  },
  AvgDialog_118702_Content_99 = {
    Text = "Kekosongan hitam matahari seperti luka yang tak bisa sembuh di dunia, saat kesadaranmu perlahan masuk, seperti merangkak ke dalam rongga dada raksasa."
  },
  AvgDialog_118703_Content_1 = {
    Text = "Jari-jarinya yang terangkat"
  },
  AvgDialog_118703_Content_10 = {
    Text = "Suara menyedihkan yang tidak berasal dari makhluk atau dimensi manapun, langsung terdengar dari kedalaman kesadaranmu, hampir merobek otakmu."
  },
  AvgDialog_118703_Content_100 = {
    Text = "Ugh—kepala... sakit sekali..."
  },
  AvgDialog_118703_Content_101 = {
    Text = "Alat yang terhubung hampir sepenuhnya rusak, bisa hidup kembali itu sungguh sebuah keajaiban."
  },
  AvgDialog_118703_Content_102 = {
    Text = "Namun tempat ini sudah menyaksikan terlalu banyak keajaiban. Mungkin untuk Kolam hitam, probabilitas itu sendiri adalah sebuah kesalahan."
  },
  AvgDialog_118703_Content_103 = {
    Text = "Baik sekali, Ramona. Jangan lakukan ini lagi lain kali."
  },
  AvgDialog_118703_Content_104 = {
    Text = "Jangan khawatir, Profesor Doll... Aku mengerti apa yang aku lakukan."
  },
  AvgDialog_118703_Content_105 = {
    Text = "Bagi %player%, bisa bertemu denganmu lagi mungkin lebih penting daripada banyak hal."
  },
  AvgDialog_118703_Content_106 = {
    Text = "Satu-satunya penyesalan adalah, {Male=dia,Female=dia} kalimat terakhir itu, kamu tidak bisa mendengarnya."
  },
  AvgDialog_118703_Content_107 = {
    Text = "Tidak, Wanita Narsis. {Male=suara dia, Female=suara dia} sudah aku dengar…"
  },
  AvgDialog_118703_Content_108 = {
    Text = "Ramona berdiri dengan lemah, tersenyum, mendekati lubang hitam yang sedang menghilang."
  },
  AvgDialog_118703_Content_109 = {
    Text = "Jurang mengkerut di matanya, dari sesuatu yang menelan segalanya, menjadi pintu yang memisahkan dimensi, lalu menjadi celah dalam kehampaan, hingga sepenuhnya menghilang."
  },
  AvgDialog_118703_Content_11 = {
    Text = "Kau berlutut di tanah, menutup rapat kedua telinga, merasakan darah yang tidak tertahan mengalir keluar dari matamu..."
  },
  AvgDialog_118703_Content_110 = {
    Text = "Tangan Ramona lembut menyentuh tempat yang dulunya ada jurang, menyentuh tubuh yang penuh luka."
  },
  AvgDialog_118703_Content_111 = {
    Text = "Dia tersenyum, seolah melihat masa depan yang tidak jauh, pemilik tubuhnya berdiri di depannya, seperti hari biasa yang sangat biasa bagi Mythag."
  },
  AvgDialog_118703_Content_112 = {
    Text = "Saya mendengar, Penjaga... kami pasti akan mencapainya."
  },
  AvgDialog_118703_Content_113 = {
    Text = "Saya menunggumu, %player%."
  },
  AvgDialog_118703_Content_12 = {
    Text = "<Shake:Ugh…… ugh……>"
  },
  AvgDialog_118703_Content_13 = {
    Text = "Sepertinya... sudah berakhir?"
  },
  AvgDialog_118703_Content_14 = {
    Text = "Jeritan menyedihkan itu entah kapan menghilang. Kau mengangkat kepala. Di dalam Dimensi yang fragile ini, sudah tidak ada lagi aura mengerikan yang membuat orang bergidik."
  },
  AvgDialog_118703_Content_15 = {
    Text = "Kamu berhasil. KesadaranNya terputus dari sini, dan bola mata raksasa terakhir telah lenyap di dalam dimensi."
  },
  AvgDialog_118703_Content_16 = {
    Text = "Kamu dengan susah payah mempertahankan pikiranmu yang kelelahan, hampir secara naluriah kamu menoleh ke belakang."
  },
  AvgDialog_118703_Content_17 = {Text = "Krek"},
  AvgDialog_118703_Content_18 = {
    Text = "Suara pecahan kristal ilusi terdengar di telingamu, yang kau lihat adalah terowongan dimensi yang retak seperti jaring laba-laba, dan Ramona yang mulai berkedip seperti televisi tua."
  },
  AvgDialog_118703_Content_19 = {
    Text = "<Big:<Shake:ramona！！！>>"
  },
  AvgDialog_118703_Content_2 = {
    Text = "Hanya kurang... sedikit lagi...!"
  },
  AvgDialog_118703_Content_20 = {
    Text = "Tubuh yang sudah kelelahan tampaknya sembuh dalam sekejap. Anda tidak lagi peduli pada hal lain, seperti terbang, datang ke sisinya, menggenggam tangan itu dengan gemetar."
  },
  AvgDialog_118703_Content_21 = {
    Text = "Saya, tidak apa-apa……"
  },
  AvgDialog_118703_Content_22 = {
    Text = "Pasanganmu tersenyum seperti biasa, dia menggenggam tanganmu lebih erat, seolah tidak ada yang terjadi dan melanjutkan rencana yang telah ada."
  },
  AvgDialog_118703_Content_23 = {
    Text = "Kau telah mengalahkan Dia, datanglah, ikutlah aku, aku akan membawamu kembali."
  },
  AvgDialog_118703_Content_24 = {
    Text = [[
Dia membimbingmu, seperti saat menjalankan misi biasanya.
Hanya saja, suara yang lebih rasional berbicara hampir dengan dingin.]]
  },
  AvgDialog_118703_Content_25 = {
    Text = "Ramona, terowongan dimensi sudah dihancurkan oleh-Nya, tubuh rohmu tidak bisa menahan beban terus menerus mempertahankan terowongan, jika terus begini, kau hanya akan menuju kematian otak."
  },
  AvgDialog_118703_Content_26 = {
    Text = "Operasi penyelamatan kali ini... telah gagal, kamu harus segera kembali, saya akan mengaktifkan mode penarikan alat pemisah, agar jiwamu kembali ke tubuhmu."
  },
  AvgDialog_118703_Content_27 = {
    Text = "<Big:Saya tidak pergi！>"
  },
  AvgDialog_118703_Content_28 = {
    Text = "Kamu melihat untuk pertama kalinya orang yang selama ini tenang menjadi panik dan berteriak. Dia terlihat seperti menggerakkan sayap hidungnya, dan segera menunjukkan senyum yang lebih alami kepadamu."
  },
  AvgDialog_118703_Content_29 = {
    Text = "Saya masih bisa, <Yellow:%player%>, saya baru-baru ini melakukan banyak latihan, kekuatan roh saya sudah meningkat, Doll tidak menyadari batasan saya yang sebenarnya."
  },
  AvgDialog_118703_Content_3 = {
    Text = "Ketika pikiranmu hampir habis, mata dewa mulai bergetar karena kelemahan."
  },
  AvgDialog_118703_Content_30 = {
    Text = "Jangan menyerah, mari coba lagi, hanya sedikit saja, bagaimana?"
  },
  AvgDialog_118703_Content_31 = {
    Text = "Dia memohon padamu."
  },
  AvgDialog_118703_Content_33 = {
    Text = "Kamu tidak bisa mengucapkan kata-kata."
  },
  AvgDialog_118703_Content_34 = {
    Text = "Mengapa harus terikat seolah demikian, lebih baik aku menangkap rohnya ke dalam dunia ini, memasukkannya ke dalam tubuh boneka yang kukerjakan dengan cermat, agar dia bisa kembali menemani <Yellow:%player%>."
  },
  AvgDialog_118703_Content_35 = {
    Text = "Doll: inferno yang sangat suka melihat pertunjukan juga bergabung di saluran komunikasi, mengeluarkan tawa yang menyenangkan."
  },
  AvgDialog_118703_Content_36 = {
    Text = "Itu omong kosong. Anda tahu tidak semua orang bisa bertahan lama terpisah dari tubuh seperti Penjaga, kalau tidak, kami tidak perlu setiap hari berjuang dengan pikiran kami."
  },
  AvgDialog_118703_Content_37 = {
    Text = "Tidak apa-apa， <ramona>， lain kali， ketika kamu sudah beristirahat， aku akan menunggu kamu untuk menjemputku."
  },
  AvgDialog_118703_Content_38 = {
    Text = "Kau menatap sosok transparan yang seolah ingin lenyap itu dengan sedikit senyuman, menyembunyikan semua kerinduan untuk pulang."
  },
  AvgDialog_118703_Content_39 = {
    Text = "Tidak semudah itu, \"jalur pelayaran\" ini sudah ditemukan oleh-Nya, menggunakan lagi hanya akan menarik perhatian yang lebih kuat."
  },
  AvgDialog_118703_Content_4 = {
    Text = "Ini adalah medan perang kehendak. Kamu seperti binatang liar yang sekarat, mengerahkan segala daya, mendapatkan sedikit kekuatan terakhir dari Dunia roh yang kering."
  },
  AvgDialog_118703_Content_40 = {
    Text = "Doll: inferno tanpa ampun merobek ilusi, sementara Doll di sisi lain hanya diam."
  },
  AvgDialog_118703_Content_41 = {
    Text = "<Shake:Kami telah sampai di sini, kali ini, sekarang, saya ingin membawamu pulang.>"
  },
  AvgDialog_118703_Content_42 = {
    Text = "Tangan Ramona juga mulai bergetar. Kamu perlahan menarik napas, berpura-pura santai mengelus tangannya."
  },
  AvgDialog_118703_Content_43 = {
    Text = "Ramona, apakah kau masih ingat pertemuan pertama kita?"
  },
  AvgDialog_118703_Content_44 = {
    Text = "Ramona mengangguk, lalu menggelengkan kepala dengan tatapan nyaris memohon padamu. Kamu hanya bisa menutup mata dan meneruskan dengan terpaksa."
  },
  AvgDialog_118703_Content_45 = {
    Text = "Itu benar-benar bencana yang menakutkan, setelah ledakan besar, yang saya ingat samar-samar hanya bahwa segalanya di sekeliling saya berubah menjadi puing-puing dengan suara gemuruh yang memekakkan telinga. Ketika saya membuka mata, saya bahkan berpikir bahwa saya telah sampai di surga."
  },
  AvgDialog_118703_Content_46 = {
    Text = "Cahaya matahari menyilaukan menyinari dari celah batu yang digali, lalu tanganmu yang menjulur ke arahku."
  },
  AvgDialog_118703_Content_47 = {
    Text = "Saat itu saya berpikir, apakah pakaian malaikat begitu aneh? Ternyata itu adalah seragam yang sangat kaku, tidak lama kemudian, seragam seperti itu juga dikenakan pada diri saya."
  },
  AvgDialog_118703_Content_48 = {
    Text = "Ramona masih ingin mengatakan sesuatu, tetapi dibatalkan olehmu, kamu seperti orang tua yang terjebak dalam kenangan, banyak bicara tanpa henti."
  },
  AvgDialog_118703_Content_49 = {
    Text = "Setelah kalian mengeluarkanku, aku selalu menganggapmu sebagai orang baik yang paling baik hati, namun setelah datang ke Mythag, aku baru menyadari aku telah ditipu besar-besaran."
  },
  AvgDialog_118703_Content_5 = {
    Text = "Kau mengangkat kunci perak itu dengan tangan bergetar."
  },
  AvgDialog_118703_Content_50 = {
    Text = "Ketika baru mulai kelas persiapan, kau bilang kau adalah pasanganku, dan akan membantuku menyelesaikan semua masalah hidup dan belajar, aku percaya."
  },
  AvgDialog_118703_Content_51 = {
    Text = "Sebenarnya, Anda telah menyelesaikan masalah saya dengan menggunakan cara yang menyelesaikan sumber masalah - <Shake:menyelesaikan saya>."
  },
  AvgDialog_118703_Content_52 = {
    Text = "Yang disebut mitra, sebenarnya adalah pengawas terbesar, di tahun itu di kelas persiapan, kamu adalah yang paling ketat padaku."
  },
  AvgDialog_118703_Content_53 = {
    Text = "Bukan hanya saat di kelas harus diawasi, saat mengerjakan PR juga harus diawasi, kadang-kadang setelah selesai latihan fisik, bahkan sepiring fish and chips pun tidak boleh saya makan, sungguh sangat jahat."
  },
  AvgDialog_118703_Content_54 = {
    Text = "Ekspresi sunyi dan menyedihkan Ramona sejenak terbuka, sudut bibirnya tidak bisa menahan senyuman."
  },
  AvgDialog_118703_Content_55 = {
    Text = "Tapi, oh, rekan tercintaku, yang juga adalah orang yang paling memperhatikanku."
  },
  AvgDialog_118703_Content_56 = {
    Text = "Bahasa umum Leo yang tidak bisa diucapkan, tekanan yang membuat ujian menjadi hancur, PR yang tidak bisa ditulis… semua masa-masa sedih bisa dihadapi dengan pasangan yang serba bisa."
  },
  AvgDialog_118703_Content_57 = {
    Text = "Masih ingat saat pertama kali aku melihat siswa yang gugur dalam tugas, tidak bisa tidur tengah malam bolak-balik, dan diam-diam mengetuk pintu kamarmu."
  },
  AvgDialog_118703_Content_58 = {
    Text = "Lalu, kamu menarikku, berlari ke puncak menara jam, aku berjuang naik ke atap bersamamu, dan kita duduk berdampingan sambil melihat bintang-bintang."
  },
  AvgDialog_118703_Content_59 = {
    Text = "Kau berbicara lama sekali denganku, tentang banyak hal. Itu adalah pertama kali aku tahu bahwa ternyata kau juga tidak tahu bagaimana keadaan ibumu dan masa kecilmu."
  },
  AvgDialog_118703_Content_6 = {
    Text = "Sampai di sini...... selesai!—"
  },
  AvgDialog_118703_Content_60 = {
    Text = "Hati saya yang selalu merasa sedikit kesepian, sedikit bingung, tiba-tiba jatuh seperti ini."
  },
  AvgDialog_118703_Content_61 = {
    Text = "Saya pikir, meski saya tidak memiliki keluarga, mungkin ini adalah satu-satunya orang di dunia yang begitu baik padaku dan sangat mirip denganku, layaknya keluarga."
  },
  AvgDialog_118703_Content_62 = {
    Text = "Saya berjanji dengan tegas kepada Anda, saya akan sangat serius dalam mengerjakan tugas, belajar dengan giat, dan menyelesaikan misi dengan sungguh-sungguh."
  },
  AvgDialog_118703_Content_63 = {
    Text = "Sejak itu, aku menjadikan Mythag sebagai rumahku yang sebenarnya, jadi dalam setiap misi yang berulang, aku mengenal banyak awak dan satu per satu anggota keluargaku yang baru."
  },
  AvgDialog_118703_Content_65 = {
    Text = "Jadi, terima kasih, terima kasih kalian telah menjemputku, keluargaku."
  },
  AvgDialog_118703_Content_66 = {
    Text = "Saya tahu kalian pasti telah mencoba sangat lama, menghabiskan banyak usaha."
  },
  AvgDialog_118703_Content_67 = {
    Text = "Mari pergi bersama saya, saya pasti bisa membawa Anda kembali."
  },
  AvgDialog_118703_Content_68 = {
    Text = "Melihat air mata yang mengalir di sudut mata Ramona, kamu tetap tersenyum, tetapi ada cairan mendidih tertentu yang juga mengalir tak terkendali di pipi."
  },
  AvgDialog_118703_Content_69 = {
    Text = "Kamu melihat sosoknya yang menjadi samar, berkilau karena keterbatasan kekuatan roh, dengan lembut menggelengkan kepala."
  },
  AvgDialog_118703_Content_7 = {
    Text = "Cahaya perak yang menyilaukan bersinar di tanganmu, cahaya putih menerangi seluruh dimensi yang ilusif."
  },
  AvgDialog_118703_Content_70 = {
    Text = "Sampai di sini saja, Ramona."
  },
  AvgDialog_118703_Content_71 = {
    Text = "Tidak, tidak..."
  },
  AvgDialog_118703_Content_72 = {
    Text = "Ramona sepertinya sudah merasakan sesuatu, dia bergeming dengan kepala terbatuk, mengenggam erat tubuh rohmu dengan tangan yang samar."
  },
  AvgDialog_118703_Content_73 = {
    Text = "Saya berjanji padamu, pasti akan kembali……"
  },
  AvgDialog_118703_Content_74 = {
    Text = "Saya berjanji padamu, kita pasti akan bertemu lagi."
  },
  AvgDialog_118703_Content_75 = {
    Text = "Kau dengan lembut menarik tangannya dari telapak tangan yang akrab, melepaskannya."
  },
  AvgDialog_118703_Content_76 = {
    Text = "Doll di ujung komunikasi menerima sinyal, perasaan perangkat yang familier mengalir ke dalam roh Ramona, dia tahu, dia akan pergi."
  },
  AvgDialog_118703_Content_77 = {
    Text = "\"Tentu\"、\"absolut\"、seperti yang kamu katakan ketika pertama kali melangkah ke Pintu……Sebenarnya, kamu sendiri juga tidak percaya, bukan?"
  },
  AvgDialog_118703_Content_78 = {
    Text = "Kamu benar-benar orang yang kejam..."
  },
  AvgDialog_118703_Content_79 = {
    Text = "Ramona, aku……"
  },
  AvgDialog_118703_Content_8 = {
    Text = "<Shake:Ugh@2@4@3！！！——>"
  },
  AvgDialog_118703_Content_80 = {
    Text = "Kode etik penyelidik... Apa yang dijanjikan, harus ditepati."
  },
  AvgDialog_118703_Content_81 = {
    Text = "Saya percaya padamu. Meskipun kamu sendiri tidak percaya, meskipun kamu menipuku berkali-kali, saya tetap percaya padamu."
  },
  AvgDialog_118703_Content_82 = {
    Text = "Di wajah yang penuh dengan tangisan dan tawa itu, Murid Ramona menatap Anda, seolah ingin mengingat wajah Anda dengan baik."
  },
  AvgDialog_118703_Content_83 = {
    Text = "Di momen terakhir saat tubuh roh dipanggil kembali, dia mengulurkan tangannya lagi kepadaku dengan segenap tenaga."
  },
  AvgDialog_118703_Content_84 = {
    Text = "Seperti saat yang sudah lama lalu di bawah langit berbintang malam, dia mengulurkan jari kelingkingnya, perlahan mengait ujung jarimu."
  },
  AvgDialog_118703_Content_85 = {
    Text = "Kamu pasti bisa melakukannya, kan?"
  },
  AvgDialog_118703_Content_86 = {
    Text = "Tidak menunggu jawabanmu. Dalam sekejap， sosok ilusi itu hancur bersama terowongan <Dimensi>， berubah menjadi jejak bintang-bintang yang perlahan menghilang， tanpa jejak."
  },
  AvgDialog_118703_Content_89 = {
    Text = "Pernapasan normal. Denyut jantung normal. Kekuatan mental di bawah garis peringatan... sedang pulih."
  },
  AvgDialog_118703_Content_9 = {Text = "Aah——"},
  AvgDialog_118703_Content_90 = {
    Text = "Bisa bertahan hidup setelah menguras energi roh seperti ini, nyawa anak anjing memang besar."
  },
  AvgDialog_118703_Content_91 = {
    Text = "Menonton pertunjukan yang bagus. Sayangnya, aku tidak melihat Dewa yang kalian panggil menghancurkan dunia ini, hasilnya kurang menarik."
  },
  AvgDialog_118703_Content_92 = {
    Text = "Jangan khawatir……Aku sudah bilang, aku akan menghentikan-Nya di dimensi lain. Janji yang tidak bisa ditepati……tidak akan ada yang kedua kalinya."
  },
  AvgDialog_118703_Content_93 = {
    Text = "Mendingan kata-kata ini ditahan sampai kita kembali, dan saya katakan langsung padanya."
  },
  AvgDialog_118703_Content_94 = {
    Text = "Karena saya telah berjalan di jalan ini bersama kalian, saya juga ingin melihat sejauh mana Anda dapat melangkah."
  },
  AvgDialog_118703_Content_95 = {
    Text = "Setelah beristirahat dengan baik, mari kita lanjutkan perjalanan, anak anjing."
  },
  AvgDialog_118703_Content_96 = {
    Text = "Kau merasakan sisa kehangatan di ujung jari, perlahan menggenggam jari kelingking yang baru saja kau kaitkan dengannya, menekan kuat di dada."
  },
  AvgDialog_118703_Content_97 = {
    Text = "Menuju ruang Dimensi yang sepi dan kosong, kepada sosok jauh yang telah menghilang itu, kamu berbisik, mengisahkan janji yang pasti akan kamu tepati."
  },
  AvgDialog_118703_Content_98 = {
    Text = "Meskipun kamu sekarang tidak dapat mendengar, tetapi…… aku akan melakukannya. Tunggu aku, Ramona!"
  },
  AvgDialog_118944_Content_1 = {
    Text = "Setelah menebas ikan manusia cacat terakhir, kamu perlahan mendekati gadis yang terjepit di sudut."
  },
  AvgDialog_118944_Content_10 = {
    Text = "William mencoba membuka papan menuju ruang bawah kapal, tetapi tidak peduli seberapa kuat ia berusaha, papan tersebut tidak bergerak sedikit pun."
  },
  AvgDialog_118944_Content_11 = {
    Text = "Tidak bisa, pintu sudah tertutup dari bawah!"
  },
  AvgDialog_118944_Content_12 = {
    Text = "Badannya mengeluarkan suara mencekam, mulai berbelok dengan penuh kesulitan dan ketegasan dalam gelombang besar, menuju laut yang lebih gelap, di mana badai semakin mendalam."
  },
  AvgDialog_118944_Content_13 = {
    Text = "Miryam mengulurkan kedua tangan, merangkul arah kehancuran ini, wajahnya menampakkan senyum lembut yang hampir seperti seorang ibu."
  },
  AvgDialog_118944_Content_14 = {
    Text = "Ritual hampir selesai!"
  },
  AvgDialog_118944_Content_15 = {
    Text = "Apakah kau telah menemukan jawabannya?"
  },
  AvgDialog_118944_Content_16 = {
    Text = "Dalam pertempuran antara badai dan kekacauan, tidak ada yang bisa membedakan posisi semua orang......"
  },
  AvgDialog_118944_Content_17 = {
    Text = "Selama masih ada sebuah kapal kecil..."
  },
  AvgDialog_118944_Content_18 = {
    Text = "Ribuan petunjuk menyala di benakmu…"
  },
  AvgDialog_118944_Content_19 = {
    Text = "Penjaga ruang tamu."
  },
  AvgDialog_118944_Content_2 = {
    Text = "Murphy, ikutlah bersamaku!"
  },
  AvgDialog_118944_Content_20 = {
    Text = "Ritual penuntun di dek."
  },
  AvgDialog_118944_Content_21 = {
    Text = "Ledakan di Ruang kekuatan."
  },
  AvgDialog_118944_Content_22 = {
    Text = "Lifeboat di kabin bawah."
  },
  AvgDialog_118944_Content_23 = {
    Text = "Titik cahaya saling terhubung, saling bertautan, memperluas… akhirnya berkumpul menjadi jalur pelarian yang koheren dan jelas."
  },
  AvgDialog_118944_Content_24 = {
    Text = "William mengangguk."
  },
  AvgDialog_118944_Content_25 = {
    Text = "Karena Anda sudah mendapatkan jawabannya, tujuan dari siklus kali ini hampir selesai, tidak perlu merasa menyesal."
  },
  AvgDialog_118944_Content_26 = {
    Text = "Menurut pola yang kamu sebutkan, kapal mulai tenggelam."
  },
  AvgDialog_118944_Content_27 = {
    Text = "Apakah kamu sudah siap?"
  },
  AvgDialog_118944_Content_28 = {
    Text = "Gelombang air telah menenggelamkan dadamu, kamu dengan lembut menggenggam kunci perak di dadamu, membisikkan kata-kata perpisahan."
  },
  AvgDialog_118944_Content_29 = {
    Text = "Kami akan bertemu lagi di putaran berikutnya."
  },
  AvgDialog_118944_Content_3 = {
    Text = "Dia terkejut dan bergetar, tatapan putusnya sulit berkonsentrasi pada wajahmu."
  },
  AvgDialog_118944_Content_30 = {
    Text = "Semoga Kunci Perak menuntun jalanmu."
  },
  AvgDialog_118944_Content_4 = {
    Text = "Tidak, semuanya tidak ada artinya, semua hanya ilusi…… baik maju maupun mundur, semua……"
  },
  AvgDialog_118944_Content_5 = {
    Text = "Selama belum sampai saat terakhir, jangan menyerah! Meskipun kali ini gagal lagi, aku akan sekali lagi memegang tanganmu!"
  },
  AvgDialog_118944_Content_7 = {
    Text = "Murphy menatap Anda dengan bingung."
  },
  AvgDialog_118944_Content_8 = {
    Text = "Kau menggenggam pergelangan tangannya dengan lembut namun kuat, menariknya keluar dari sudut putus asa itu."
  },
  AvgDialog_118944_Content_9 = {
    Text = "William senior, adakah jalan untuk melarikan diri?"
  },
  AvgDialog_118945_Content_1 = {
    Text = "Anak kecil, kamu menahan diri dalam Pertempuran."
  },
  AvgDialog_118945_Content_10 = {
    Text = "Beberapa orang melakukan kejahatan demi mencari kelangsungan hidup mereka di akhir jalan."
  },
  AvgDialog_118945_Content_11 = {
    Text = "Beberapa orang melakukan penyaringan terhadap orang lain demi membangun dunia baru yang mereka impikan."
  },
  AvgDialog_118945_Content_12 = {
    Text = "Ada juga orang-orang yang murni untuk bersenang-senang, yang dapat menyebabkan kekacauan, menciptakan masalah yang tak terhitung jumlahnya."
  },
  AvgDialog_118945_Content_13 = {
    Text = "Kamu menunggu, kamu mengharapkan jawabannya. Karena kamu pernah melihat jalannya ketika dia datang dalam mimpi yang jauh."
  },
  AvgDialog_118945_Content_14 = {
    Text = "Miryam yang kini kegilaan, dulunya adalah seorang gadis muda yang mengorbankan diri pada misi Pendeta untuk melindungi keluarga satu-satunya di tengah bencana."
  },
  AvgDialog_118945_Content_15 = {
    Text = "Miryam tidak langsung menjawab pertanyaanmu. Dia menyatukan kedua telapak tangannya, berdoa ke arah garis horizon yang jauh."
  },
  AvgDialog_118945_Content_16 = {
    Text = "\"Berkat Dewa bagi yang saleh...\""
  },
  AvgDialog_118945_Content_17 = {
    Text = "\"Segala yang didambakan, Tuhan kami akan mengabulkannya.\""
  },
  AvgDialog_118945_Content_18 = {
    Text = "Seolah-olah mendapatkan persetujuan dari lautan, dia setengah membuka mata ungu-hitamnya yang kehilangan fokus."
  },
  AvgDialog_118945_Content_19 = {
    Text = "Saya datang untuk membangkitkan Ranah dewa, untuk memulihkan kemuliaan Dewa di dunia."
  },
  AvgDialog_118945_Content_2 = {
    Text = "Bagi saya, percakapan dengan Miryam ini jauh lebih penting dari sebuah kemenangan."
  },
  AvgDialog_118945_Content_20 = {
    Text = "Jadi, ketika Lemuria muncul kembali di dunia, apa yang Anda harapkan untuk dilihat?"
  },
  AvgDialog_118945_Content_21 = {
    Text = "\"Dalam mimpi panjang Dewa, kita menikmati kedamaian dan kebahagiaan yang abadi.\""
  },
  AvgDialog_118945_Content_22 = {
    Text = "Kebangkitan kejayaan Lemuria, seperti yang ditanamkan padamu semasa kau hidup."
  },
  AvgDialog_118945_Content_23 = {
    Text = "Kamu belum pernah melihat masa kejayaan seperti itu bahkan sehari pun, apakah kamu benar-benar tahu bagaimana cara menciptakannya?"
  },
  AvgDialog_118945_Content_24 = {
    Text = "\"Perintah Tuhan akan menunjukkan jalur berlayar ke Lemuria kepada mereka yang setia.\""
  },
  AvgDialog_118945_Content_25 = {
    Text = "Kamu di dunia ini memang tak berbeda sedikit pun dari pengetahuanku."
  },
  AvgDialog_118945_Content_26 = {
    Text = "Jadi, mengapa saat dewa telah lahir, Anda masih erat memegang Murphy?"
  },
  AvgDialog_118945_Content_3 = {
    Text = "Selama kamu bisa membuat Miryam sedikit goyah, Domain akan menampakkan celahnya, yang tersembunyi dari \"nukleus\"..."
  },
  AvgDialog_118945_Content_4 = {
    Text = "Kalian memiliki harapan untuk sepenuhnya mengakhiri mimpi buatan yang tak tergoyahkan ini."
  },
  AvgDialog_118945_Content_5 = {
    Text = "Silakan jelaskan maksud kedatanganmu."
  },
  AvgDialog_118945_Content_6 = {
    Text = "Kedatangan saya adalah untuk membawa sebuah pertanyaan."
  },
  AvgDialog_118945_Content_7 = {
    Text = "Miryam, mengapa kau ingin menghidupkan kembali kerajaan Dewa?"
  },
  AvgDialog_118945_Content_8 = {
    Text = "Kau mengajukan pertanyaan yang sangat menarik."
  },
  AvgDialog_118945_Content_9 = {
    Text = "Dalam perjalanan melawan pelarutan, saya mengenal banyak orang."
  },
  AvgDialog_118946_Content_1 = {
    Text = "Meloncat dan kebebasa"
  },
  AvgDialog_118946_Content_10 = {
    Text = "Dia mengangkat ujung jarinya yang pucat, dan sekali lagi memutar roda pemintal."
  },
  AvgDialog_118946_Content_100 = {
    Text = "Hingga kegelapan menelan dunia."
  },
  AvgDialog_118946_Content_11 = {
    Text = "Meskipun aku belum tahu namamu, tolong beri aku berkat, orang asing."
  },
  AvgDialog_118946_Content_12 = {
    Text = [[
Sekumpulan burung terbang melewati, mengangkat gelombang bulu putih.
Setelah gelombang mereda, wanita itu pun menghilang.]]
  },
  AvgDialog_118946_Content_13 = {
    Text = "Kau memberikan gambaran keseluruhan rencana kepada William dengan cepat."
  },
  AvgDialog_118946_Content_14 = {
    Text = "Kedengarannya seperti rencana yang mengandalkan kekacauan untuk kemenangan."
  },
  AvgDialog_118946_Content_15 = {
    Text = "Ritual selesai, pemberontakan meletus, saat paling rentan bagi seluruh gereja pelaut."
  },
  AvgDialog_118946_Content_16 = {
    Text = "Berdasarkan petunjuk yang diberikan oleh Faros, mungkin kita hanya perlu menguasai patung gading untuk terlepas dari domain."
  },
  AvgDialog_118946_Content_17 = {
    Text = "Apakah membawa Murphy pergi terlalu berbelit-belit?"
  },
  AvgDialog_118946_Content_18 = {
    Text = "William senior, apakah kamu yang memberitahuku bahwa acara di dalam Domain mungkin akan mempengaruhi dunia nyata di luar Domain."
  },
  AvgDialog_118946_Content_19 = {
    Text = "Jika demikian, saya tidak dapat membiarkan Murphy berlalu begitu saja…"
  },
  AvgDialog_118946_Content_2 = {
    Text = "Satu siklus lagi."
  },
  AvgDialog_118946_Content_20 = {
    Text = "Goliath berniat merebut kapal, dia tidak akan peduli tentang pelarian Murphy; Miryam lelah menghadapi Goliath, sama sekali tidak mampu mengejar."
  },
  AvgDialog_118946_Content_21 = {
    Text = "Ini adalah kesempatan yang sangat baik."
  },
  AvgDialog_118946_Content_22 = {
    Text = "William menutup matanya dan mendorong kacamatanya, seolah menghela napas dengan putus asa."
  },
  AvgDialog_118946_Content_23 = {
    Text = "Dengarkan kamu."
  },
  AvgDialog_118946_Content_24 = {
    Text = "Sama seperti putaran sebelumnya, kamu dan william telah menyamar di atas platform tiang."
  },
  AvgDialog_118946_Content_25 = {
    Text = "Ketika Goliath melancarkan pemberontakan, kamu melompat turun, menggenggam pergelangan tangan Murphy."
  },
  AvgDialog_118946_Content_26 = {
    Text = "Cepat, ikut saya, lompat dari kapal!"
  },
  AvgDialog_118946_Content_27 = {
    Text = "Kau gila? Kenapa kau masih ingin kembali? Kita tidak bisa keluar, bukankah lebih baik membiarkan segalanya berjalan lancar?"
  },
  AvgDialog_118946_Content_28 = {
    Text = "Murphy mencoba melepaskan diri darimu, tapi keteguhanmu tidak bisa ditolak. Sebuah lingkaran merah muda muncul di pergelangan tangannya."
  },
  AvgDialog_118946_Content_29 = {
    Text = "Murphy, ketenangan yang kau inginkan sudah tidak ada lagi."
  },
  AvgDialog_118946_Content_3 = {
    Text = "Burung terbang di lautan berputar di atas wanita, suara melankolisnya seperti lagu."
  },
  AvgDialog_118946_Content_30 = {
    Text = "Goliath dan Caecus merencanakan untuk merebut kapal, Faros merancang hak atas Patung gading, seluruh Pelaut sekarang sudah tercerai-berai."
  },
  AvgDialog_118946_Content_31 = {
    Text = "Percayalah, sekali lagi percayalah padaku. Aku pasti akan membawamu melarikan diri."
  },
  AvgDialog_118946_Content_32 = {
    Text = "Melarikan diri, lalu bagaimana?"
  },
  AvgDialog_118946_Content_33 = {
    Text = "Lalu kita akan menemukan cara untuk kembali ke Mythag, kamu dan semua orang akan menjadi bagian dari Mythag."
  },
  AvgDialog_118946_Content_34 = {
    Text = "Mereka sering berkata mimpiku adalah ramalan, di dalam mimpi yang jauh, aku telah melihat pemandangan seperti itu…"
  },
  AvgDialog_118946_Content_35 = {
    Text = "Kau merasakan daya tahan untuk melawan sedikit berkurang."
  },
  AvgDialog_118946_Content_36 = {
    Text = "Ayo, ikut aku, menuju sisi kanan kapal… tiga, dua, satu, lompat!"
  },
  AvgDialog_118946_Content_37 = {
    Text = "Plomp, plomp."
  },
  AvgDialog_118946_Content_38 = {
    Text = "Dua ikan yang melompat bebas kembali ke laut setia mereka, tangan masih terikat erat bersama."
  },
  AvgDialog_118946_Content_39 = {
    Text = [[
Sinar matahari menyinari dari permukaan laut, menerangi helai rambutnya yang melayang di antara air laut yang jernih dan kain penutup. 
Tatapan berwarna mawar menatapmu, seperti sebuah mimpi yang sepi.]]
  },
  AvgDialog_118946_Content_4 = {
    Text = "Jangan khawatir, kali ini, persiapan kita sudah tak terkalahkan."
  },
  AvgDialog_118946_Content_40 = {
    Text = "Kalian bebas."
  },
  AvgDialog_118946_Content_41 = {
    Text = "Byurrr——"
  },
  AvgDialog_118946_Content_42 = {
    Text = "Sebuah dayung menusuk ke dalam air laut yang bening di depanmu."
  },
  AvgDialog_118946_Content_43 = {
    Text = "Kamu mengangguk kepada Murphy, keduanya memanjat dayung kapal bersama."
  },
  AvgDialog_118946_Content_44 = {
    Text = "Apakah sudah tertangkap dengan pasti?"
  },
  AvgDialog_118946_Content_45 = {
    Text = "Dia menarik kalian keluar dari permukaan air, kalian memanjat ke tepi perahu kecil."
  },
  AvgDialog_118946_Content_46 = {
    Text = "Hei, tolong tarik saya!"
  },
  AvgDialog_118946_Content_47 = {
    Text = "Ada apa, tidak bisa naik sendiri?"
  },
  AvgDialog_118946_Content_48 = {
    Text = "Kurangi omong kosong, aku belum memintamu untuk bertanggung jawab atas jatuhnya Ibu Dewa ke dalam air!"
  },
  AvgDialog_118946_Content_49 = {
    Text = "Kau dengan lembut menarik bahu murphy yang melayang, mengangkatnya dari permukaan air dengan kekuatan yang pas."
  },
  AvgDialog_118946_Content_5 = {
    Text = "Kami tahu setelah upacara pemanduan selesai, kapal akan terbalik; kami tahu patung gading memiliki kekuatan untuk mengendalikan mimpi."
  },
  AvgDialog_118946_Content_50 = {Text = "Hu——"},
  AvgDialog_118946_Content_51 = {
    Text = "Baiklah, sekarang kita bisa berbicara dengan baik. Kita mau ke mana?"
  },
  AvgDialog_118946_Content_52 = {
    Text = "Sambil Goliath dan Miryam bertempur, ketiga dari kita mengemudikan kapal ini untuk keluar dari batas Domain."
  },
  AvgDialog_118946_Content_53 = {
    Text = "Lalu, bersama-sama menemukan jalan kembali ke dunia asal, kamu bertemu dengan dirimu di dunia itu, setiap hari berebut kue kecil di kantin..."
  },
  AvgDialog_118946_Content_54 = {
    Text = "Puff, itu akan menjadi perjalanan yang panjang."
  },
  AvgDialog_118946_Content_55 = {
    Text = "Kalau begitu, ceritakan dengan baik… tentang tempat yang disebut Mythag itu."
  },
  AvgDialog_118946_Content_57 = {
    Text = "……………"
  },
  AvgDialog_118946_Content_58 = {
    Text = "Lalu bagaimana?"
  },
  AvgDialog_118946_Content_59 = {
    Text = "Lalu, Ramona menemukan alkohol yang disembunyikan Lord Dexter di sudut lemari bukunya. Untuk menyimpan alkohol itu, dia bahkan mengosongkan beberapa halaman buku."
  },
  AvgDialog_118946_Content_6 = {
    Text = "Kami juga tahu bahwa di ruang kapal bawah tidak ada satu pun perahu penyelamat kecuali satu; selama kami bisa keluar dari kapal pesiar ini, kami tidak akan lagi terikat oleh miryam."
  },
  AvgDialog_118946_Content_60 = {
    Text = "Kamu melihat Williams menundukkan kepalanya, mengernyitkan dahi, dan menggosok pelipisnya."
  },
  AvgDialog_118946_Content_61 = {
    Text = "Dia marah, langsung menerobos ke salon Nyonya Sorel dengan pedang tipis di tangannya!"
  },
  AvgDialog_118946_Content_62 = {
    Text = "Lalu bagaimana?"
  },
  AvgDialog_118946_Content_63 = {
    Text = "Murphy dengan gugup menggenggam lenganmu, nafsu makannya terangkat tinggi oleh cerita yang menakjubkan."
  },
  AvgDialog_118946_Content_64 = {
    Text = "Suara tawa yang ceria di ruang pertemuan tiba-tiba terhenti， semua orang melotot menatap tamu tak diundang ini!"
  },
  AvgDialog_118946_Content_65 = {
    Text = "Benar， seperti yang dilakukan senior <william> sekarang!"
  },
  AvgDialog_118946_Content_66 = {Text = "Ada…"},
  AvgDialog_118946_Content_67 = {
    Text = "Ada pembunuh, ada pembunuh! Di sekitar, orang-orang mulai berteriak!"
  },
  AvgDialog_118946_Content_68 = {
    Text = "Senyummu membeku di wajahmu."
  },
  AvgDialog_118946_Content_69 = {
    Text = "Di belakang Murphy, di tepi perahu, monster menjulang yang dibentuk dari ribuan mayat bangkit tiba-tiba dari permukaan laut."
  },
  AvgDialog_118946_Content_7 = {
    Text = "Rencananya adalah, saya akan menyusup ke dalam ritual penuntun, saat murphy dalam keadaan lemah, membawanya terjun ke laut."
  },
  AvgDialog_118946_Content_71 = {
    Text = "Ia dengan diam-diam membuka mulut raksasa yang dibentuk oleh tulang yang bergerak dan kepala—"
  },
  AvgDialog_118946_Content_72 = {
    Text = "<Red:menyerap murphy hidup-hidup>"
  },
  AvgDialog_118946_Content_73 = {
    Text = "<Shake:Tidak……boneka pasang surut…… tidak seharusnya sudah di kota pemakaman……>"
  },
  AvgDialog_118946_Content_74 = {
    Text = "Dalam waktu di domain ini… Goliath masih mengendalikan boneka korupsi."
  },
  AvgDialog_118946_Content_75 = {
    Text = "Kekuatan inti utamanya sedang melawan Miryam, jadi dia mengirimkan formasi eksternal ini untuk mengejar…"
  },
  AvgDialog_118946_Content_76 = {
    Text = "Kami... telah salah perhitungan."
  },
  AvgDialog_118946_Content_77 = {
    Text = "<Big:<Shake:…!!!>>"
  },
  AvgDialog_118946_Content_78 = {
    Text = "Memb devour murphy, raksasa tinggi mengangkat kepala anehnya, tenggorokannya mengeluarkan suara bergemuruh yang puas."
  },
  AvgDialog_118946_Content_79 = {
    Text = "Kabut kotor menyebar di permukaan laut， kapal <Faros> di kejauhan sudah tidak terlihat， hanya tengkorak gunung yang menutupi langit."
  },
  AvgDialog_118946_Content_8 = {
    Text = "Senior William akan mengemudikan sekoci untuk menjemput saya dan Murphy di sisi kapal, setelah saya naik kapal, segera memecahkan rahasia patung gading dan keluar dari domain."
  },
  AvgDialog_118946_Content_80 = {Text = "Awas!"},
  AvgDialog_118946_Content_81 = {
    Text = "William memelukmu yang terpesona, menggulung ke sisi kapal, nyaris menghindari serangan pertama dari kuku tulang."
  },
  AvgDialog_118946_Content_82 = {
    Text = "Senior William, punggungmu…"
  },
  AvgDialog_118946_Content_83 = {
    Text = "Darah, darah yang menetes."
  },
  AvgDialog_118946_Content_84 = {
    Text = "Jangan hiraukan aku, naiklah, putuskan tulang punggung boneka busuk itu!"
  },
  AvgDialog_118946_Content_87 = {
    Text = "Boneka dari gelombang busuk seperti menara yang runtuh, hujan tulang yang pucat jatuh ke dalam lautan tanpa akhir."
  },
  AvgDialog_118946_Content_88 = {
    Text = "Sebagaimana yang kamu katakan... Kekuasaan goliath di dalam Domain sangat tereduksi."
  },
  AvgDialog_118946_Content_89 = {
    Text = "Jadi, kami bisa bertahan dengan susah payah..."
  },
  AvgDialog_118946_Content_9 = {
    Text = "Wanita itu menundukkan kepalanya, poni halus menutupi ekspresinya."
  },
  AvgDialog_118946_Content_90 = {
    Text = "Mungkin karena luka yang terlalu parah, kamu tidak bisa mendengar ucapan William."
  },
  AvgDialog_118946_Content_91 = {
    Text = "Di antara ombak mayat yang runtuh dan tulang, tidak ada jejak gadis itu."
  },
  AvgDialog_118946_Content_92 = {
    Text = "Murphy...... Murphy!"
  },
  AvgDialog_118946_Content_93 = {
    Text = "Kamu menyerbu bangkai yang mengapung, menggali bertumpuk-tumpuk tengkorak menuju area pencernaan."
  },
  AvgDialog_118946_Content_95 = {
    Text = "Tidak ada tempat yang bisa ditemukan Murphy."
  },
  AvgDialog_118946_Content_96 = {
    Text = "Di tengah tulang yang berserakan, hanya ada selembar tipis, ringan, kain hitam."
  },
  AvgDialog_118946_Content_97 = {
    Text = "Kau dengan lembut mengangkat kain hitam itu, sebuah rasa pedih muncul di dalam hati."
  },
  AvgDialog_118946_Content_98 = {
    Text = "Saya pikir kali ini, pasti bisa membawanya pergi......"
  },
  AvgDialog_118946_Content_99 = {
    Text = "Kamu mengeluarkan tangisan rendah. Kemudian suara isak itu semakin keras."
  },
  AvgDialog_118947_Content_1 = {
    Text = "\"Kapal Paradiso\""
  },
  AvgDialog_118947_Content_10 = {
    Text = "Kamu menggunakan penjepit besi untuk mengeluarkan loyang, dan Murphy segera mengulurkan tangan dengan tidak sabar untuk mengambil sepotong kue kecil yang mengeluarkan uap panas."
  },
  AvgDialog_118947_Content_11 = {
    Text = "Jangan terburu-buru, panas panas panas!"
  },
  AvgDialog_118947_Content_12 = {
    Text = "Murphy sepertinya tidak rela melepaskan, tangan kirinya berpindah ke kanan beberapa kali karena panas, akhirnya menunggu kue turun ke suhu yang tepat."
  },
  AvgDialog_118947_Content_13 = {
    Text = "Cobalah sedikit... Sepertinya aku tidak perlu mengatakannya."
  },
  AvgDialog_118947_Content_14 = {
    Text = "Sebelum suaramu mereda, Murphy telah menggigitnya."
  },
  AvgDialog_118947_Content_15 = {
    Text = "Bagaimana rasanya, enak tidak?"
  },
  AvgDialog_118947_Content_16 = {
    Text = "Resep sepenuhnya bergantung pada ingatanmu, untuk merawat Nona kecil yang kelaparan tengah malam, kamu telah beberapa kali meminjam dapur Mythag."
  },
  AvgDialog_118947_Content_17 = {
    Text = "Hmph, bahan makanannya terlalu sederhana, tidak ada bandingnya dengan yang Miryam berikan setiap hari."
  },
  AvgDialog_118947_Content_18 = {
    Text = "Murphy menelan sisa-sisa di mulutnya dengan hati-hati, berkata dengan serius."
  },
  AvgDialog_118947_Content_19 = {
    Text = "Namun, siapa suruh bakat memasak Sang Ibu sangat luar biasa, cukup untuk mengubah Pembusukan menjadi keajaiban."
  },
  AvgDialog_118947_Content_20 = {
    Text = "Hangat dan lembut... Ini adalah makanan terlezat yang pernah saya makan."
  },
  AvgDialog_118947_Content_21 = {
    Text = "Saya juga ingin mencoba sepotong."
  },
  AvgDialog_118947_Content_22 = {
    Text = "William dengan hati-hati mengambil sepotong kecil dengan pisau perak, dan memasukkannya ke dalam mulut."
  },
  AvgDialog_118947_Content_23 = {
    Text = "Senior, jika aku tidak salah lihat, apakah pisau bedah yang kamu gunakan untuk memotong kue itu, adalah pisau bedah yang sebelumnya digunakan untuk mengoperasi Nubia?"
  },
  AvgDialog_118947_Content_24 = {
    Text = "Sudah cukup didisinfeksi. Alat makan kasar yang digunakan oleh pelaut benar-benar sulit untuk disantap."
  },
  AvgDialog_118947_Content_25 = {
    Text = "Seandainya saya tahu seharusnya saya meminta dua set peralatan dari Dulles di Kota Makam…\nAh, pikir-pikir, peralatan Dulles lebih tidak jelas apa yang pernah digunakan…"
  },
  AvgDialog_118947_Content_26 = {
    Text = "Kalian makan dengan lahap, tertawa dan mengoleskan krim pada wajah masing-masing."
  },
  AvgDialog_118947_Content_27 = {
    Text = "(Jika ini adalah ingatan terakhirnya...)"
  },
  AvgDialog_118947_Content_28 = {Text = "BRAK—"},
  AvgDialog_118947_Content_29 = {
    Text = "Suara besar yang menghancurkan ketenangan yang jarang terjadi, dapur tempat kalian berada tiba-tiba mulai bergetar hebat tanpa dapat dihentikan."
  },
  AvgDialog_118947_Content_3 = {
    Text = "Beberapa puluh menit kemudian."
  },
  AvgDialog_118947_Content_30 = {
    Text = "Ada apa ini?！"
  },
  AvgDialog_118947_Content_31 = {
    Text = "Goliath menyerang Ruang kekuatan, Miryam melawan dengan sengit, Ruang kekuatan meledak."
  },
  AvgDialog_118947_Content_32 = {
    Text = "Kau menjawab dengan tenang."
  },
  AvgDialog_118947_Content_33 = {
    Text = "Dengan kata lain, kapal akan tenggelam."
  },
  AvgDialog_118947_Content_34 = {
    Text = "Kapal akan tenggelam, apakah kamu tidak bereaksi sama sekali?"
  },
  AvgDialog_118947_Content_35 = {
    Text = [[
Murphy, aku ada yang ingin kukatakan kepadamu.
Kapal ini harus tenggelam.]]
  },
  AvgDialog_118947_Content_36 = {
    Text = "Saya telah mengalami lima siklus, di setiap siklus, goliath selalu merencanakan perompakan."
  },
  AvgDialog_118947_Content_37 = {
    Text = "Proses ini akan menyebabkan Ruang kekuatan meledak, dan kemudian kapal akan disedot oleh sebuah pusaran ke dasar laut."
  },
  AvgDialog_118947_Content_38 = {Text = "Jadi?"},
  AvgDialog_118947_Content_39 = {
    Text = "Saya terus mencari cara untuk menghentikan kehancuran kapal ini, karena itu adalah pemikiran yang salah dari saya."
  },
  AvgDialog_118947_Content_4 = {
    Text = "Kalian menatap oven, adonan yang diremas mulai mengembang sedikit demi sedikit, dan hati yang kamu nantikan juga melambung seiring lengkungan yang mengembang."
  },
  AvgDialog_118947_Content_40 = {
    Text = "Kapal ini seharusnya tenggelam... hanya dengan tenggelam, barulah bisa membuka jalan kebebasan untukmu."
  },
  AvgDialog_118947_Content_41 = {Text = "DUARR—"},
  AvgDialog_118947_Content_42 = {
    Text = "Kapal bergetar seolah tersengat listrik, seperti makhluk raksasa yang kehilangan kendali dalam rasa sakit akibat ledakan."
  },
  AvgDialog_118947_Content_43 = {
    Text = "Baiklah, sekarang tidak perlu banyak penjelasan, cepat ikut aku."
  },
  AvgDialog_118947_Content_44 = {
    Text = "Jika terlambat sedikit saja, semuanya akan sia-sia."
  },
  AvgDialog_118947_Content_45 = {
    Text = "Kau menarik Murphy, mengikuti jalan yang ditunjuk William."
  },
  AvgDialog_118947_Content_46 = {
    Text = "Hei, apakah kamu benar-benar akan membiarkan wanita baik-baik memanjat tangga? Di depan orang luar, menggunakan tangan dan kaki sangat memalukan!"
  },
  AvgDialog_118947_Content_47 = {
    Text = "Kamu turun lebih dulu menunggu aku, aku pasti tidak akan menengokmu."
  },
  AvgDialog_118947_Content_48 = {
    Text = "Mata mulai beradaptasi dengan kegelapan, di sudut kargo, ada sebuah perahu kecil yang terparkir sendirian."
  },
  AvgDialog_118947_Content_49 = {
    Text = "Rute pelarian yang disiapkan goliath telah ditemukan oleh kami."
  },
  AvgDialog_118947_Content_5 = {
    Text = "Aroma custard meluap ke udara, kelenjar ludah lebih cepat merespon daripada otak, memicu rasa lapar di perutmu."
  },
  AvgDialog_118947_Content_50 = {
    Text = "Sebelum memberontak, orang licik ini menghancurkan hampir semua sekoci, memastikan hanya dia bisa keluar."
  },
  AvgDialog_118947_Content_51 = {
    Text = "Ini dia, kunci cadangan, saya minta William untuk menyiapkannya. Sekarang, naik perahu."
  },
  AvgDialog_118947_Content_52 = {
    Text = "Tunggu, apa yang kamu bicarakan, saya sama sekali tidak setuju untuk melarikan diri bersamamu—"
  },
  AvgDialog_118947_Content_53 = {
    Text = "Saya juga tidak mengatakan bahwa saya akan naik kapal bersamamu. Di sini ada, dan hanya satu perahu penyelamat. Anda naik sendiri, lalu turun."
  },
  AvgDialog_118947_Content_54 = {Text = "!"},
  AvgDialog_118947_Content_55 = {
    Text = "Jika kita pergi seperti ini, Miryam tidak akan berhenti begitu saja. Suatu hari, bayangan dari Pelaut akan mengejarmu lagi."
  },
  AvgDialog_118947_Content_56 = {
    Text = "Saya harus tetap di sini, memastikan bahwa Pelaut dan Tubuh Suci selamanya tenggelam di aequor."
  },
  AvgDialog_118947_Content_57 = {
    Text = "Ini juga sesuatu yang mereka senangi, kembali ke tanah air dan Ranah dewa mereka yang abadi, bukan?"
  },
  AvgDialog_118947_Content_58 = {Text = "Puff—"},
  AvgDialog_118947_Content_59 = {
    Text = "Murphy tersenyum dengan air mata."
  },
  AvgDialog_118947_Content_6 = {
    Text = "Suara langkah kaki Pelaut yang lengket dan cemas kadang-kadang terdengar di lantai kayu, namun pintu tipis menghalangi dua dunia ini, ruang kecil ini dipenuhi kebahagiaan dan kehangatan yang terlampau sederhana seperti ilusi."
  },
  AvgDialog_118947_Content_60 = {
    Text = "Sebelum berangkat, aku sudah merencanakan semuanya."
  },
  AvgDialog_118947_Content_61 = {
    Text = "Jika aku bisa mengantarmu melarikan diri, maka itu adalah akhir terbaik."
  },
  AvgDialog_118947_Content_62 = {
    Text = "Jika tidak… setidaknya, saya sudah berusaha untuk mengembalikan hari yang saya kenal bahwa Murphy pasti akan suka."
  },
  AvgDialog_118947_Content_63 = {
    Text = "Waktu untuk mengenal tidak lama, pengetahuanku tentangmu juga tidak cukup dalam. Semoga kamu juga menyukainya."
  },
  AvgDialog_118947_Content_64 = {
    Text = "Murphy mengangkat jari kakinya dan memberikanmu pelukan lembut."
  },
  AvgDialog_118947_Content_65 = {
    Text = "Saya ingat kamu bilang sebelumnya, kamu akan mengalami siklus berulang kali."
  },
  AvgDialog_118947_Content_66 = {
    Text = "Kali ini tidak akan menjadi akhir."
  },
  AvgDialog_118947_Content_67 = {
    Text = "Lain kali, bawa saya melarikan diri, ya?"
  },
  AvgDialog_118947_Content_68 = {
    Text = [[
<Red:Tidak ada lain kali.>
Perasaan pedas menjalar ke puncak hidungmu.]]
  },
  AvgDialog_118947_Content_69 = {
    Text = "Saya berjanji padamu. Kita akan melarikan diri bersama."
  },
  AvgDialog_118947_Content_7 = {
    Text = "Lihat, kulitnya sudah berubah warna, bisa disajikan sekarang!"
  },
  AvgDialog_118947_Content_70 = {
    Text = "Awan gelap menutupi, di bawah patung kepala kapal, Miryam dan goliath berhadapan dari kejauhan."
  },
  AvgDialog_118947_Content_71 = {
    Text = "Serahkan gadis kecil dan patung gading itu, maka aku dapat memberimu kematian dengan kehormatan yang masih tersisa, seperti yang kau ancam sebelumnya."
  },
  AvgDialog_118947_Content_72 = {
    Text = "Jangan omong kosong disini, bukan kah kalian yang telah mengubur Dewi, memicu kerusuhan ini?"
  },
  AvgDialog_118947_Content_73 = {
    Text = [[
Kalian tak perlu berdebat lagi, murphy sudah tidak berada di kapal ini.
Dia telah melarikan diri dari cengkeraman jahat, jauh dari pusaran air.]]
  },
  AvgDialog_118947_Content_74 = {
    Text = "Sebuah perasaan aneh yang menenangkan muncul di dalam hati."
  },
  AvgDialog_118947_Content_75 = {
    Text = "Apakah kamu yang mengirimnya keluar? Ternyata punya sedikit keberanian."
  },
  AvgDialog_118947_Content_76 = {
    Text = "Jika kalian berniat untuk bertempur di sini, aku tidak keberatan mengambil keuntungan dari keributan ini."
  },
  AvgDialog_118947_Content_77 = {
    Text = "Ternyata kau orang asing yang tidak dikenal..."
  },
  AvgDialog_118947_Content_78 = {
    Text = "Apakah kau mengira bahwa dengan perlindungan sang dewi, kau bisa berbuat semaunya?"
  },
  AvgDialog_118947_Content_79 = {
    Text = "Miryam, aku ingin berbicara denganmu."
  },
  AvgDialog_118947_Content_8 = {Text = "Ya!"},
  AvgDialog_118947_Content_80 = {
    Text = "Bukan mengumumkan perang dengan kasar, tetapi memulai dari pembicaraan, bukan?"
  },
  AvgDialog_118947_Content_81 = {
    Text = "Saya juga penasaran, betapa kurang berharganya Anda, bisa mendapat panggilan dari Ibu Dewa, tetap bisa bertindak sembrono hingga saat ini."
  },
  AvgDialog_118947_Content_82 = {
    Text = "Jika kamu dengan tulus meminta jawaban dari utusan dewa, aku tidak akan ragu untuk memberikan berkat Tuhan kepadamu."
  },
  AvgDialog_118947_Content_83 = {
    Text = "<Red:<Shake:Namun sekarang, hadapi amarah pelaut!>>"
  },
  AvgDialog_118947_Content_9 = {
    Text = "Aroma custard memancar keluar."
  },
  AvgDialog_118948_Content_1 = {Text = "Vortex"},
  AvgDialog_118948_Content_10 = {
    Text = "\"Krak,\" sebuah benang perak tiba-tiba putus."
  },
  AvgDialog_118948_Content_11 = {
    Text = "Caecus tidak menyadari hal ini, hanya melihatmu dengan curiga."
  },
  AvgDialog_118948_Content_12 = {
    Text = "Sahabat, apa yang kamu katakan, sahabat?"
  },
  AvgDialog_118948_Content_13 = {
    Text = "Ini pasti adalah teknik yang membingungkan! Jangan dengarkan {Male=dia,Female=dia}, Tuan Caecus!"
  },
  AvgDialog_118948_Content_14 = {
    Text = "Kata sandi, ya, kata sandi..."
  },
  AvgDialog_118948_Content_15 = {
    Text = "Caecus menarik napas dalam-dalam, seolah keberanian kembali mengalir ke dalam tubuhnya, dan dia mendongak dengan cepat."
  },
  AvgDialog_118948_Content_16 = {
    Text = "Saya hanya tahu, Pelaut sementara menempatkan Anda, ini tidak berarti Anda bisa masuk dan keluar dari tempat penting sesuka hati."
  },
  AvgDialog_118948_Content_17 = {
    Text = "Sesuai perintah besar goliath, orang-orang yang tidak berkepentingan tidak diizinkan memasuki ruang kekuatan!"
  },
  AvgDialog_118948_Content_2 = {
    Text = "Kamu melihat ke arah sana, sepertinya ada seseorang yang menjaga ruang kekuatan."
  },
  AvgDialog_118948_Content_3 = {
    Text = "Beberapa tubuh yang membungkuk berkeliaran, di antara mereka, seorang pemuda dengan postur tegap memegang lembing bersayap, waspada terhadap gerakan angin dan rumput di sekitarnya."
  },
  AvgDialog_118948_Content_4 = {
    Text = "Hati-hati! Misi penting yang diatur oleh Tuan Goliath tidak boleh mengalami kesalahan……"
  },
  AvgDialog_118948_Content_5 = {Text = "Caecus!"},
  AvgDialog_118948_Content_6 = {
    Text = "Eh, kamu adalah..."
  },
  AvgDialog_118948_Content_7 = {
    Text = "Kamu mencoba mengaktifkan kunci perak, menghubungkan dengan kesadarannya, membangkitkan kenangan kalian yang dulu."
  },
  AvgDialog_118948_Content_8 = {
    Text = "Tentakel cahaya perak meregang, memanjat, menyusuri permukaan tubuhnya yang tertutup sisik, mendalami sumsum tulangnya……"
  },
  AvgDialog_118948_Content_9 = {
    Text = "Caecus, aku temanmu, bisakah kau membiarkanku masuk ke belakangmu..."
  },
  AvgDialog_118949_Content_1 = {
    Text = "Maaf, Tuan Goliath…"
  },
  AvgDialog_118949_Content_10 = {
    Text = "Namun sekarang adalah saat yang krusial dalam rencana, tentu saja variabel seharusnya semakin sedikit."
  },
  AvgDialog_118949_Content_11 = {
    Text = "Tutup mulutmu di sini selamanya, nak."
  },
  AvgDialog_118949_Content_12 = {
    Text = "Tuan Goliath, saya akan bertempur bersama Anda!"
  },
  AvgDialog_118949_Content_13 = {
    Text = "Tidak perlu, sesuatu yang lemah, ruang di sini tidak memungkinkan kita beraksi."
  },
  AvgDialog_118949_Content_14 = {
    Text = "<Small:Tapi saya……>"
  },
  AvgDialog_118949_Content_15 = {
    Text = "Caecus mendesah pelan, tetapi pertarungan yang baru saja kalah membuatnya sadar bahwa dia tidak lagi dalam posisi untuk mengeluh, jadi dia hanya menutup mulut dan mundur setengah langkah."
  },
  AvgDialog_118949_Content_16 = {
    Text = "Anak Caecus."
  },
  AvgDialog_118949_Content_17 = {Text = "Hm?"},
  AvgDialog_118949_Content_18 = {
    Text = "Goliath tidak menoleh."
  },
  AvgDialog_118949_Content_19 = {
    Text = "Jangan putus asa, kau adalah orang yang aku pilih. Setelah urusan ini selesai, aku akan memberimu tambahan 500 jadwal pelatihan."
  },
  AvgDialog_118949_Content_2 = {
    Text = "Hmph, jangan terlalu terkejut."
  },
  AvgDialog_118949_Content_20 = {Text = "Ah... iya!"},
  AvgDialog_118949_Content_21 = {
    Text = "<faros>， sudah siap?"
  },
  AvgDialog_118949_Content_22 = {
    Text = "Selama itu untuk membangun tangga menuju Ranah Dewa... Faros selalu siap untuk perintah Anda."
  },
  AvgDialog_118949_Content_3 = {
    Text = "Goliath menggenggam pisau terbalik dan melangkah keluar perlahan, gigi gergaji menyeret di tanah mengeluarkan suara berdecit yang menusuk telinga."
  },
  AvgDialog_118949_Content_4 = {
    Text = "Dengan suara sekecil ini kalian tidak bisa menyelesaikan, benar-benar memalukan untuk keturunan Perishite."
  },
  AvgDialog_118949_Content_5 = {
    Text = "Maaf, saya..."
  },
  AvgDialog_118949_Content_6 = {
    Text = "Guguh, tuan goliath, jangan salahkan tuan caecus, orang yang tidak dikenal itu bisa memanggil monster besar yang tidak terlihat!"
  },
  AvgDialog_118949_Content_7 = {
    Text = "Orang lain... Hey, si kecil, itu kamu."
  },
  AvgDialog_118949_Content_8 = {
    Text = "Kota Penguburan mungkin sudah cukup, tapi di sini tidak ada tempat untukmu berbuat sesuka hati."
  },
  AvgDialog_118949_Content_9 = {
    Text = "Jika kita bertemu sedikit lebih lambat, mungkin kita masih bisa meluangkan waktu untuk duduk dan berbicara."
  },
  AvgDialog_118950_Content_1 = {
    Text = "Langit sedang terbakar."
  },
  AvgDialog_118950_Content_10 = {
    Text = "Jejak darah merah terulur di belakangnya, bercampur dengan pola kayu di dek."
  },
  AvgDialog_118950_Content_11 = {
    Text = "<Red:Matilah, bajingan, dan sesat!>"
  },
  AvgDialog_118950_Content_12 = {
    Text = "Pendeta dengan mata membengkak mengangkat tombak yang seharusnya milik pemuda itu, menusuk dengan tepat dan kejam ke punggung pemuda. Ujung tombak yang tajam menembus tubuh, menancapkan pemuda itu dengan kuat di dek."
  },
  AvgDialog_118950_Content_13 = {
    Text = "Pemuda itu bergetar sejenak, lalu berhenti sejauh satu langkah dari pria itu."
  },
  AvgDialog_118950_Content_14 = {
    Text = "Haha, hahaha!"
  },
  AvgDialog_118950_Content_15 = {
    Text = "Tuhanku, yang Maha Besar, apakah Engkau melihatnya? Ini adalah persembahan suci dari saya dan Ibu Dewa untuk Anda!"
  },
  AvgDialog_118950_Content_16 = {
    Text = "Miryam yang penuh darah melihat lukisan neraka ini dari jauh, tertawa sinis ke langit, jubah yang robek terbang dalam api."
  },
  AvgDialog_118950_Content_17 = {
    Text = "<Shake: Semoga Ranah dewa Anda mengapung kembali dari Jurang, semoga kehendak Anda segera diterapkan di bumi!>"
  },
  AvgDialog_118950_Content_18 = {
    Text = "Pandangan sang ritualis berkeliling di wilayahnya, melintasi faros yang terpotong menjadi dua oleh bilah besar, melintasi dua penyelidik yang terluka parah dan tidak bisa bergerak, berhenti pada gadis yang kain hitamnya basah dengan darah dan racun."
  },
  AvgDialog_118950_Content_19 = {
    Text = "Ibu Dewi, datanglah, ke sisiku. Aku telah menghukum semua pengkhianat yang berpaling dari terang dan orang-orang terkutuk yang menodai dewa!"
  },
  AvgDialog_118950_Content_2 = {
    Text = "Laut sedang terbakar."
  },
  AvgDialog_118950_Content_20 = {
    Text = "Badan kapal yang ambruk kehilangan keseimbangan karena kebocoran, setengah dari badan kapal sudah tenggelam, tetapi dia sama sekali tidak menyadarinya."
  },
  AvgDialog_118950_Content_21 = {
    Text = "<Red:<Shake:Selanjutnya, kita berdua mewarisi keabadian Ranah dewa, hingga saat bintang berikutnya selaras, nama suci-Nya akan terdengar di seluruh jagat!>>"
  },
  AvgDialog_118950_Content_22 = {
    Text = "Di ujung haluan kapal yang miring seperti guillotine, Myriam menjulurkan tangan yang dipenuhi darah."
  },
  AvgDialog_118950_Content_23 = {
    Text = "<Shake:Tidak, tidak……bukan……>"
  },
  AvgDialog_118950_Content_24 = {
    Text = [[
Kaki Murphy melemah, dan ia berlutut di tanah.
Tubuh kecilnya sepenuhnya kehilangan keindahannya yang dahulu, bergetar dalam api.]]
  },
  AvgDialog_118950_Content_25 = {
    Text = "<Shake:Maaf, saya tidak seharusnya…… tidak seharusnya ingin melarikan diri……>"
  },
  AvgDialog_118950_Content_26 = {
    Text = "Air mata mengalir, menciptakan bekas air yang bercak di dek, dan kemudian dijilati oleh panas api."
  },
  AvgDialog_118950_Content_27 = {
    Text = "<Red:<Shake:Aku seharusnya tahu, ini adalah takdir yang tidak bisa aku hindari atau lari dari...>>"
  },
  AvgDialog_118950_Content_28 = {
    Text = "Murphy...... bukan seperti ini, Murphy, masih ada kesempatan......"
  },
  AvgDialog_118950_Content_29 = {
    Text = "Kau sangat ingin menghampiri gadis itu untuk menghiburnya, tetapi tubuhmu mengkhianati keinginanmu."
  },
  AvgDialog_118950_Content_3 = {
    Text = "Tidak, tidak seperti itu…… hanya saja pandanganmu sedang terbakar.\n Kematian dan keputusasaan menyelimuti tanah yang tak berpenghuni di lautan ini."
  },
  AvgDialog_118950_Content_30 = {
    Text = "Nyeri yang mendalam di pergelangan kaki merobek setiap inci indra kamu, kerusakan parah yang kamu terima dalam pertempuran sebelumnya membuatmu terjebak di tempat, tidak bisa bergerak."
  },
  AvgDialog_118950_Content_31 = {Text = "Maaf."},
  AvgDialog_118950_Content_32 = {
    Text = "Mengabaikan luka yang mengalir darah di dada, gadis itu berdiri dengan tenang."
  },
  AvgDialog_118950_Content_33 = {
    Text = "Rasa sakit tidak bisa lagi menghentikannya, tanpa ragu, tanpa ilusi, dan tanpa kerinduan."
  },
  AvgDialog_118950_Content_34 = {
    Text = [[
Melangkah melewati gunung mayat, melewati lautan api.
Dia melangkah dengan langkah yang serius, satu langkah demi satu menuju pendeta.]]
  },
  AvgDialog_118950_Content_35 = {
    Text = "Tidak… tidak bisa diakhiri di sini…"
  },
  AvgDialog_118950_Content_36 = {
    Text = "William… senior William…! Apakah kamu masih bisa bergerak?"
  },
  AvgDialog_118950_Content_37 = {
    Text = "Kau ingin... melakukan apa?"
  },
  AvgDialog_118950_Content_38 = {
    Text = "William terbaring di genangan darah, menghela napas berat."
  },
  AvgDialog_118950_Content_39 = {
    Text = "<Red:<Big:……bunuh saya, mulai kembali.>>"
  },
  AvgDialog_118950_Content_4 = {
    Text = "Ledakan beruntun merobek ruang mesin, dek yang terbakar terangkat dalam distorsi."
  },
  AvgDialog_118950_Content_40 = {
    Text = "Tidak, kenapa……"
  },
  AvgDialog_118950_Content_41 = {
    Text = "Tidak bisa membiarkan dunia ini menjadi akhir... tidak bisa menerima akhir seperti ini..."
  },
  AvgDialog_118950_Content_42 = {
    Text = "Cepat, saya tidak bisa bergerak lagi..."
  },
  AvgDialog_118950_Content_43 = {
    Text = "Lengan mekanik William telah terpisah dari Tubuhnya, ia dengan susah payah mengulurkan lengan yang masih bisa bergerak, menggenggam belati yang dilemparkan Miryam di sampingnya."
  },
  AvgDialog_118950_Content_44 = {
    Text = "Maaf, aku tidak bisa membuatmu melihat ekspresiku saat ini..."
  },
  AvgDialog_118950_Content_45 = {
    Text = "Kemudian, rasa sakit yang tajam muncul dari punggung kiri belakang."
  },
  AvgDialog_118950_Content_46 = {
    Text = "Jangan harap!"
  },
  AvgDialog_118950_Content_47 = {
    Text = "Pendeta Besar, tangkap orang itu hidup-hidup, jangan biarkan {Male=dia,Female=dia} mati!"
  },
  AvgDialog_118950_Content_48 = {
    Text = "Dengan satu perintah dari miryam, sebuah trisula lainnya menembus dada william, kau terkejut melihat kembali dan hanya melihat sehelai rambut emas yang lembut jatuh."
  },
  AvgDialog_118950_Content_49 = {
    Text = "Pendeta ikan menggelikan berputar di tempat, tertawa terbahak-bahak."
  },
  AvgDialog_118950_Content_5 = {
    Text = "Rekan yang pernah berjuang bersamamu, musuh yang bertarung mati-matian, berbaris tidak terpisahkan dalam genangan darah merah yang membara."
  },
  AvgDialog_118950_Content_50 = {
    Text = "Guguh, hehe, apa pun yang ingin kamu lakukan, sekarang tidak bisa dilakukan!"
  },
  AvgDialog_118950_Content_51 = {
    Text = "Jantung lebih sakit daripada disayat, anggota tubuh yang kehilangan darah terasa dingin dan menusuk."
  },
  AvgDialog_118950_Content_52 = {
    Text = "<Red:Anda harus mati>，Anda harus menuju siklus berikutnya."
  },
  AvgDialog_118950_Content_53 = {
    Text = "<Red:<Shake:Aku... pasti bisa...>>"
  },
  AvgDialog_118950_Content_54 = {
    Text = "Menahan belati dengan papan kapal"
  },
  AvgDialog_118950_Content_55 = {
    Text = "Belati perlahan-lahan masuk ke dalam tubuhmu, diiringi rasa sakit yang menusuk tulang."
  },
  AvgDialog_118950_Content_56 = {
    Text = "Jatuh mundur dengan keras"
  },
  AvgDialog_118950_Content_57 = {
    Text = "Kepala pisau tajam menembus dadamu, perasaan hampa saat kesadaran menghilang menyelimuti pandanganmu."
  },
  AvgDialog_118950_Content_58 = {
    Text = "<Shake:Murphy…… William…… tolong tunggu saya di siklus berikutnya.>"
  },
  AvgDialog_118950_Content_59 = {
    Text = "<Yellow:Kami pasti akan…… melarikan diri.>"
  },
  AvgDialog_118950_Content_6 = {
    Text = "<Shake:Tuan Goliath, maaf, jika saya sedikit lebih kuat……>"
  },
  AvgDialog_118950_Content_7 = {
    Text = "Pemuda yang terluka parah menyeret tubuhnya yang rusak, berusaha meraih tanah kasar dengan jari-jarinya, merangkak dengan susah payah menuju pria yang tertidur."
  },
  AvgDialog_118950_Content_8 = {
    Text = "<Shake:Tuan Goliath……>"
  },
  AvgDialog_118950_Content_9 = {
    Text = "Apa pun yang dia lakukan untuk memanggil, pria yang telah kehilangan semangatnya tetap tak bergerak."
  },
  AvgDialog_118951_Content_1 = {
    Text = "Jadi, kamu menipuku untuk apa sebenarnya?"
  },
  AvgDialog_118951_Content_10 = {
    Text = "Mari lakukan sesuatu yang tidak ada hubungannya dengan dewi, doktrin, atau ritual."
  },
  AvgDialog_118951_Content_11 = {
    Text = "Saya tahu, meskipun sekarang kamu selalu membicarakan hal-hal itu, yang sebenarnya kamu sukai bukanlah ini."
  },
  AvgDialog_118951_Content_12 = {
    Text = "Jangan banyak bicara, cepat ambil ini!"
  },
  AvgDialog_118951_Content_13 = {
    Text = "Ini, apa ini?"
  },
  AvgDialog_118951_Content_14 = {
    Text = "Aduk dengan cepat, menuju satu arah!"
  },
  AvgDialog_118951_Content_16 = {
    Text = "Lalu, tambahkan tepung! Baking powder! Sedikit garam!"
  },
  AvgDialog_118951_Content_17 = {
    Text = "Senior William jangan hanya diam? Pergi bantu lelehkan mentega!"
  },
  AvgDialog_118951_Content_18 = {
    Text = "……Baiklah."
  },
  AvgDialog_118951_Content_19 = {
    Text = "William berjalan pergi, dengan sabar berperan sebagai juru masak yang gugup namun bertanggung jawab di dapur yang berantakan."
  },
  AvgDialog_118951_Content_2 = {
    Text = "Ayo, biarkan senior William menunjukkan sulap untukmu!"
  },
  AvgDialog_118951_Content_20 = {
    Text = "Akhirnya, kalian mengirimkan adonan yang telah dicampur ke dalam oven."
  },
  AvgDialog_118951_Content_21 = {
    Text = "Murphy menatap oven, tertegun dalam tatapannya."
  },
  AvgDialog_118951_Content_22 = {
    Text = "Mengingat beberapa hal dari waktu yang lama..."
  },
  AvgDialog_118951_Content_23 = {Text = "Hm?"},
  AvgDialog_118951_Content_24 = {
    Text = "Itu saat masih di pos selatan. Saya menemukan altar di celah pegunungan, di atasnya terdapat banyak patung kecil."
  },
  AvgDialog_118951_Content_25 = {
    Text = "Saya meminta ibuku…… Miryam memberiku sebuah pisau kecil dan beberapa kayu, saya ingin membuat beberapa patung kayu."
  },
  AvgDialog_118951_Content_26 = {
    Text = "Setelah sekian lama, dia hanya memberiku sebilah pisau kecil yang tidak tajam, karena khawatir \"tubuh suci Ibu Dewa akan rusak\"."
  },
  AvgDialog_118951_Content_27 = {
    Text = "Saya merasa tubuh saya seolah tidak milik saya, tentu juga tidak milik dia, kami seolah semua merupakan satu batu bata dari Ranah dewa, terpenjara di tempat masing-masing, tidak bisa bergerak sedikit pun."
  },
  AvgDialog_118951_Content_28 = {
    Text = "Saya melihat beberapa ukiran kayu di samping tempat tidur Anda."
  },
  AvgDialog_118951_Content_29 = {
    Text = "Hmm, saya diam-diam meminta Goliath untuk membantu saya mencari sepotong batu minyak."
  },
  AvgDialog_118951_Content_3 = {
    Text = "Semua sudah dibawa sesuai daftar, silakan periksa."
  },
  AvgDialog_118951_Content_30 = {
    Text = "Saya mengerahkan banyak usaha, dengan susah payah mengasah mata pisau sampai cukup tajam untuk memotong kayu."
  },
  AvgDialog_118951_Content_31 = {
    Text = "Saya mengukir selama berhari-hari, berusaha untuk menghidupkan kembali detail yang saya bayangkan."
  },
  AvgDialog_118951_Content_32 = {
    Text = "Ketika saya akhirnya merasa puas, saya memberikannya kepada miryam..."
  },
  AvgDialog_118951_Content_33 = {
    Text = "Tahukah kamu apa yang dia katakan?"
  },
  AvgDialog_118951_Content_34 = {
    Text = "Miryam...... dia bilang ukiranmu buruk, menodai Dewa?"
  },
  AvgDialog_118951_Content_35 = {
    Text = "Kamu berusaha menerka sikap Miryam, dengan hati-hati memberikan sebuah tebakkan."
  },
  AvgDialog_118951_Content_36 = {Text = "Tidak."},
  AvgDialog_118951_Content_37 = {
    Text = "Dia bahkan tidak melirik, hanya berkata jika saya menyukai patung seperti itu, dia bisa memberikan perintah, meminta pandai besi terbaik untuk mengukirnya setiap hari untuk saya."
  },
  AvgDialog_118951_Content_38 = {
    Text = "Murphy tertawa kegilaan, rasa sakit yang tak bisa dijelaskan dan ejekan keluar dari senyuman kaku."
  },
  AvgDialog_118951_Content_39 = {
    Text = "Saya adalah anak Dewa, dan juga adalah induk Dewa, ingin apa pun, cukup angkat tangan untuk memiliki."
  },
  AvgDialog_118951_Content_4 = {
    Text = "William membuka satu per satu kantong besar dan kecil di dada, punggung, dan lengan."
  },
  AvgDialog_118951_Content_40 = {
    Text = "Karena aku sudah memiliki segalanya, maka mengukir sebuah patung kayu adalah hal yang sangat sepele bagi saya."
  },
  AvgDialog_118951_Content_41 = {
    Text = "Dia tertawa, tertawa, tanpa sadar, air mata membanjir. Air mata yang tidak terduga, mengalir cepat di sepanjang pipinya yang terdistorsi oleh tawa."
  },
  AvgDialog_118951_Content_42 = {
    Text = "Saya melihat karya-karya yang kamu letakkan di samping tempat tidur, keterampilanmu cukup baik."
  },
  AvgDialog_118951_Content_43 = {
    Text = "Baik dan buruk, apa pentingnya itu..."
  },
  AvgDialog_118951_Content_44 = {
    Text = "Murphy, mulai sekarang, kamu bisa mengukir sekehendakmu, seperti yang kamu inginkan."
  },
  AvgDialog_118951_Content_45 = {
    Text = "Lalu kita membuat kue kecil bersama, pergi belajar tentang seni bunga bersama."
  },
  AvgDialog_118951_Content_46 = {
    Text = "Saya akan menemukan cara untuk kembali ke dunia saya, saya akan memperkenalkan murphy yang saya kenal kepada Anda, kalian bisa bersama-sama bebas, melakukan segala sesuatu yang ingin kalian lakukan."
  },
  AvgDialog_118951_Content_47 = {
    Text = "Murphy menyeka air mata di wajahnya, lalu mengangkat kepala, memberikan senyuman cerah yang belum pernah Anda lihat sebelumnya."
  },
  AvgDialog_118951_Content_48 = {
    Text = "Baiklah, semua ini adalah apa yang kau janjikan padaku."
  },
  AvgDialog_118951_Content_49 = {
    Text = "Hati-hati, jangan sekali-kali mengecewakan ya."
  },
  AvgDialog_118951_Content_5 = {
    Text = "Terima kasih kepada senior William yang hebat dari dewa sihir, yang mencuri bahan dari dapur untuk kita."
  },
  AvgDialog_118951_Content_50 = {
    Text = "Ini adalah cerita yang tidak ada hubungannya dengan ibu dewa."
  },
  AvgDialog_118951_Content_51 = {
    Text = "Namun sepertinya dia tidak pernah merasa sebahagia ini dalam hidupnya."
  },
  AvgDialog_118951_Content_6 = {
    Text = "Ada tepung, telur, lemon, madu, gula, bubuk pengembang, mentega."
  },
  AvgDialog_118951_Content_7 = {
    Text = "Masih cukup lengkap! Sungguh baik memiliki banyak kantong di seragam pelaut."
  },
  AvgDialog_118951_Content_8 = {
    Text = "Saya masih tidak mengerti…… kenapa?"
  },
  AvgDialog_118951_Content_9 = {
    Text = "Kamu tidak ingin mencoba memanggang kue yang biasa kamu makan sendiri?"
  },
  AvgDialog_118952_Content_1 = {
    Text = "Hari Kelahiran Dewa"
  },
  AvgDialog_118952_Content_10 = {
    Text = "Saya memohon kepada Dewa untuk jawaban."
  },
  AvgDialog_118952_Content_11 = {
    Text = "Saya bertanya tentang masa depan Ranah Dewa, menanyakan hubungan-Nya dengan saya, menanyakan segala sesuatu yang ingin saya ketahui dan yang Miryam coba selidiki."
  },
  AvgDialog_118952_Content_12 = {
    Text = "Dewa terdiam."
  },
  AvgDialog_118952_Content_13 = {
    Text = "<color=#E6E6E6>Hari Kelima Penciptaan Tuhan</color>"
  },
  AvgDialog_118952_Content_14 = {
    Text = "Miryam menanyakan hasil pertemuanku dengan Dewa."
  },
  AvgDialog_118952_Content_15 = {
    Text = "Dalam kebuntuan, aku membuat jawaban dari Tuhan, \"Ranah dewa akan segera muncul\"."
  },
  AvgDialog_118952_Content_16 = {
    Text = "Dia terus bertanya tentang waktu, aku hanya bisa menjawab \"ketika bintang berjajar\"."
  },
  AvgDialog_118952_Content_17 = {
    Text = "Miryam penuh kegembiraan, itu adalah ekspresi kebahagiaan yang belum pernah kulihat sebelumnya, tidak saat aku memberinya ukiran kayu, tidak saat aku mengandung bayi suci."
  },
  AvgDialog_118952_Content_18 = {
    Text = "<color=#E1E1E1>Hari Keenam Penciptaan Tuhan.</color>"
  },
  AvgDialog_118952_Content_19 = {
    Text = "Miryam menanyakan tentang lokasi Lemuria, aku hanya bisa menjawab sembarangan, ekspresinya setengah percaya setengah ragu."
  },
  AvgDialog_118952_Content_2 = {
    Text = "Hari pertama Kelahiran Dewa"
  },
  AvgDialog_118952_Content_20 = {
    Text = "Dia pernah melihat Dewa yang belum mati, kebohonganku mungkin tidak berfungsi."
  },
  AvgDialog_118952_Content_21 = {
    Text = "<Shake:Tuhan, tolong aku, meskipun hanya satu kata, jawab doaku.>"
  },
  AvgDialog_118952_Content_22 = {
    Text = "<Red:Hari ketujuh dari kelahiran ilahi>"
  },
  AvgDialog_118952_Content_23 = {
    Text = "Dewa telah mati. Dewa tidak pernah dilahirkan."
  },
  AvgDialog_118952_Content_24 = {
    Text = "Yang berbaring di dadaku hanyalah patung palsu, sebuah massa cacat yang secara keliru disebut sebagai <Yellow:\"Tuhan\">."
  },
  AvgDialog_118952_Content_25 = {
    Text = "Miryam tidak pernah mencintai siapa pun. Tidak pernah peduli pada siapa pun."
  },
  AvgDialog_118952_Content_26 = {
    Text = "Setelah menguasai kuasa Sang Ibu, aku telah membaca semua catatan Pelaut."
  },
  AvgDialog_118952_Content_27 = {
    Text = "Selama ribuan tahun, setiap enam puluh tahun akan datang saat ketika bintang berjajar."
  },
  AvgDialog_118952_Content_28 = {
    Text = "Ibu yang dikorbankan, aku bukan yang pertama, dan bukan yang terakhir."
  },
  AvgDialog_118952_Content_29 = {
    Text = "Ingin bertahan hidup, ingin melestarikannya..."
  },
  AvgDialog_118952_Content_3 = {
    Text = "Embrio dewa lahir dari tubuh yang terkelupas."
  },
  AvgDialog_118952_Content_30 = {
    Text = "Harus membunuh itu..."
  },
  AvgDialog_118952_Content_31 = {
    Text = "Saya yang lemah dan naif..."
  },
  AvgDialog_118952_Content_4 = {
    Text = "Saya sangat kelelahan karena spiritualitas saya terhisap, tetapi di wajah semua orang terpancar kegembiraan yang antusias."
  },
  AvgDialog_118952_Content_5 = {
    Text = "<color=#F7F7F7>Hari Kedua Penciptaan Tuhan</color>"
  },
  AvgDialog_118952_Content_6 = {
    Text = "Saya membaptis rahim suci. Dia menutup mata, tidur nyenyak dalam gendongan."
  },
  AvgDialog_118952_Content_7 = {
    Text = "<color=#F2F2F2>Hari Ketiga Penciptaan Tuhan</color>"
  },
  AvgDialog_118952_Content_8 = {
    Text = "Bayi suci belum membuka mata. Meskipun aku dapat merasakan detak jantungnya, seperti jantungnya yang berdetak di depan dadaku."
  },
  AvgDialog_118952_Content_9 = {
    Text = "<color=#F0F0F0>Hari Keempat Penciptaan Tuhan</color>"
  },
  AvgDialog_118953_Content_1 = {
    Text = "Tirai di langit bergetar, bergerak, seperti badai di sebuah miniatur dunia."
  },
  AvgDialog_118953_Content_10 = {
    Text = "Awan gelap mulai berubah, tertutup oleh gelapnya langit."
  },
  AvgDialog_118953_Content_11 = {
    Text = "Di langit......... matahari......"
  },
  AvgDialog_118953_Content_12 = {
    Text = "Kilmatan palsu menghilang, di bawah langit yang jauh, tirai gelap yang menutupi langit bergetar lembut mengikuti napas."
  },
  AvgDialog_118953_Content_13 = {
    Text = "Itu adalah matahari hitam pekat."
  },
  AvgDialog_118953_Content_2 = {
    Text = "Sebuah angin sejuk yang melintas mengangkat kain hitam kabur yang menutupi wajahnya, di bawahnya adalah sepasang mata yang sudah kering karena air mata."
  },
  AvgDialog_118953_Content_3 = {
    Text = "Ada falter!"
  },
  AvgDialog_118953_Content_4 = {Text = "Oh!"},
  AvgDialog_118953_Content_6 = {
    Text = "Dalam sekejap getaran tirai langit, mata pisau bergerigi dengan fatal memotong celah yang bergetar itu."
  },
  AvgDialog_118953_Content_7 = {
    Text = "Patung gading meledak dengan cahaya putih yang menyilaukan, layaknya perlawanan yang akan mati."
  },
  AvgDialog_118953_Content_8 = {
    Text = "Beberapa detik kemudian, cahaya putih tiba-tiba padam, patung gading hancur berantakan, menciptakan hujan fragmen putih dalam diameter dua puluh sentimeter."
  },
  AvgDialog_118953_Content_9 = {
    Text = "Semua sudah selesai……"
  },
  AvgDialog_118954_Content_1 = {
    Text = "Reinkarnasi waktu"
  },
  AvgDialog_118954_Content_10 = {
    Text = "Penjaga Rahasia…"
  },
  AvgDialog_118954_Content_11 = {Text = "Ramona!"},
  AvgDialog_118954_Content_12 = {
    Text = "Tenanglah, dengarkan aku berbicara."
  },
  AvgDialog_118954_Content_13 = {
    Text = "Saya telah mengalami jumlah lompatan waktu yang tak terhitung, mundur ke siklus."
  },
  AvgDialog_118954_Content_14 = {
    Text = "Oleh karena itu, aku sangat yakin, apa yang terjadi padamu bukan \"perputaran waktu\"."
  },
  AvgDialog_118954_Content_15 = {
    Text = "Waktu yang kamu alami masih terus mengalir dengan alami."
  },
  AvgDialog_118954_Content_16 = {
    Text = "Tidak ada \"siklus waktu\"..."
  },
  AvgDialog_118954_Content_17 = {
    Text = "Hal-hal aneh yang saya temui setiap kali saya bangkit, kapal pesiar tenggelam kemudian melanjutkan pelayaran, gadis yang meninggal hidup kembali tanpa cedera..."
  },
  AvgDialog_118954_Content_18 = {
    Text = "Kenapa ini bisa terjadi?"
  },
  AvgDialog_118954_Content_19 = {
    Text = "Saya tidak dapat menjawabmu."
  },
  AvgDialog_118954_Content_2 = {
    Text = "Kau merasakan bahwa kau sedang bermimpi."
  },
  AvgDialog_118954_Content_20 = {
    Text = "Ada matahari itu di langit......"
  },
  AvgDialog_118954_Content_21 = {
    Text = "Ramona tidak lagi berbicara. Dia pun tidak tahu jawaban atas pertanyaan ini."
  },
  AvgDialog_118954_Content_22 = {
    Text = "Permukaan air secara bertahap menjadi gelombang， bayangannya mulai bergetar dari tepi， akhirnya menjadi pecahan <Memori> yang tak dapat ditangkap， menyebar ke dalam cahaya gelombang yang berkilauan."
  },
  AvgDialog_118954_Content_23 = {
    Text = "Menyengat. Rasa sakit. Lidah api membakar setiap inch dari kulitmu."
  },
  AvgDialog_118954_Content_24 = {
    Text = [[
Ujung saraf meringkuk karena sakit, karbon karena kehilangan air.
Kamu menjadi sangat ringan, ringan hingga menjadi tulang hitam yang hangus.]]
  },
  AvgDialog_118954_Content_25 = {
    Text = "Kau batuk keras-keras."
  },
  AvgDialog_118954_Content_26 = {Text = "Bangun?"},
  AvgDialog_118954_Content_27 = {
    Text = "<Shake:……sekali lagi…… siklus?……>"
  },
  AvgDialog_118954_Content_28 = {
    Text = "Jika tubuhmu sudah pulih, saya akan pergi mempersiapkan ritual."
  },
  AvgDialog_118954_Content_29 = {
    Text = "Jangan pergi, tunggu sebentar, Murphy......"
  },
  AvgDialog_118954_Content_3 = {
    Text = "Mimpi adalah perwujudan dari keinginan dan ketakutan yang ada di dalam hati, domain mimpi adalah pulau-pulau yang melayang di kehampaan."
  },
  AvgDialog_118954_Content_30 = {
    Text = "Mereka… di mana semua orang?"
  },
  AvgDialog_118954_Content_31 = {
    Text = "Murphy menarik napas panjang lalu mengeluarkannya perlahan."
  },
  AvgDialog_118954_Content_32 = {
    Text = "Setiap orang memiliki urusan masing-masing. Duduklah dan istirahat yang baik di sini."
  },
  AvgDialog_118954_Content_33 = {
    Text = "Ketika saat berikutnya ketikan bintang berjajar, kapal ini akan tiba di Lemuria, semuanya akan baik-baik saja."
  },
  AvgDialog_118954_Content_34 = {
    Text = [[
Krek, pintu ditutup.
Kamu ditinggalkan sendirian di ruang tamu.]]
  },
  AvgDialog_118954_Content_35 = {
    Text = "Tidak bisa berhenti, kamu harus bergerak."
  },
  AvgDialog_118954_Content_36 = {
    Text = "Setelah melewati tiga siklus, apa kesimpulanmu?"
  },
  AvgDialog_118954_Content_37 = {
    Text = "Karena jumlah siklus sudah pasti, maka informasi jauh lebih penting daripada melarikan diri."
  },
  AvgDialog_118954_Content_38 = {
    Text = "Dalam putaran pertama, saya awalnya memahami Pelaut; meskipun putaran ketiga adalah kekalahan yang mengenaskan, saya punya pemahaman dasar tentang pergerakan orang-orang di kapal."
  },
  AvgDialog_118954_Content_39 = {
    Text = "Justru waktu siklus kedua adalah yang terbuang sia-sia."
  },
  AvgDialog_118954_Content_4 = {
    Text = "Di dalam mimpi kacau yang dipenuhi dengan kekacauan, berbagai ujung pisau berwarna warni menusuk dadamu, memantulkan bayangan satu sama lain seperti gelembung."
  },
  AvgDialog_118954_Content_40 = {
    Text = "Yang paling mendesak adalah mengumpulkan lebih banyak informasi tentang kapal Paradesa dan pelaut."
  },
  AvgDialog_118954_Content_41 = {
    Text = "Meskipun orang misterius itu menyiratkan bahwa kamu memiliki total enam reinkarnasi……"
  },
  AvgDialog_118954_Content_42 = {
    Text = "Namun, apakah kau tidak mempertimbangkan, jika sekarang adalah siklus terakhir, apakah kau telah membuang-buang satu kesempatan?"
  },
  AvgDialog_118954_Content_43 = {
    Text = "Jika sekarang adalah siklus terakhir…"
  },
  AvgDialog_118954_Content_44 = {
    Text = "Kau menggelengkan kepala, menyingkirkan semua dugaan buruk."
  },
  AvgDialog_118954_Content_45 = {
    Text = "Dalam mimpi ini yang merupakan awal siklus ini, Ramona: timeworn memberiku sebuah informasi: <Yellow: dia bisa merasakan waktu di tubuhku masih terus mengalir dengan teratur>."
  },
  AvgDialog_118954_Content_46 = {
    Text = "Dan kamu menyatakan bahwa kamu pernah mengalami acara yang berulang……"
  },
  AvgDialog_118954_Content_47 = {Text = "!"},
  AvgDialog_118954_Content_48 = {
    Text = "Sepertinya Kak William juga mulai menyadari."
  },
  AvgDialog_118954_Content_49 = {
    Text = "Ini bukan \"putaran waktu\", melainkan \"peristiwa yang sama berulang kali terjadi\"..."
  },
  AvgDialog_118954_Content_5 = {
    Text = "Kau perlu metode untuk mengakhiri mimpi."
  },
  AvgDialog_118954_Content_50 = {
    Text = "Di Mythag, saya sering dipaksa terjebak dalam situasi yang serupa."
  },
  AvgDialog_118954_Content_51 = {
    Text = "\"Domain Buatan\"……"
  },
  AvgDialog_118954_Content_52 = {
    Text = "Benar， ini sebagian besar adalah sebuah \"Domain buatan\"."
  },
  AvgDialog_118954_Content_53 = {
    Text = "Domain buatan hanyalah wadah informasi, kita yang sebenarnya mungkin sedang dibawa oleh badai dan petir berputar di udara."
  },
  AvgDialog_118954_Content_54 = {
    Text = "Bagaimana Domain buatan ini muncul? Kenapa Domain terus-menerus diulang? Apa yang menjadi pemicu untuk mengakhirinya?"
  },
  AvgDialog_118954_Content_55 = {
    Text = "Tanpa memahami semua ini, percobaan yang kita lakukan di Domain hanya akan memusingkan kita."
  },
  AvgDialog_118954_Content_56 = {
    Text = "Rasionalitas. Selama tiga ratus tahun, rasionalitas selalu membantu Mythag melawan kegilaan yang bernama pelarutan."
  },
  AvgDialog_118954_Content_57 = {
    Text = "Percayalah, Kak William juga pasti sudah menyadari bahwa matahari yang kita lihat beberapa hari ini bukanlah matahari hitam setelah kabut hitam menyelimuti, melainkan matahari dunia yang normal dan murni."
  },
  AvgDialog_118954_Content_58 = {
    Text = "Waktu kelahiran Domain terjadi sebelum kabut hitam menyerang dunia."
  },
  AvgDialog_118954_Content_6 = {
    Text = "Sebagai Pemintal nasib, saya harus diam dan tidak bisa mengungkapkan Kebenaran."
  },
  AvgDialog_118954_Content_60 = {
    Text = "Apakah saya salah bicara? Kenapa menatap saya seperti itu?"
  },
  AvgDialog_118954_Content_61 = {
    Text = "……Tidak, saya hanya tiba-tiba teringat saat di Mythag, saat itu ketika tugas luar, selalu ada kamu dan Ramona di sisiku, yang membebaskan pikiranku maksimal."
  },
  AvgDialog_118954_Content_62 = {
    Text = "Pemikiran adalah bagian yang tak terpisahkan dari penyelidikan."
  },
  AvgDialog_118954_Content_63 = {
    Text = "Jadi, senior William, menurut Anda siapa pemilik domain ini?"
  },
  AvgDialog_118954_Content_64 = {
    Text = "Berdasarkan prinsip pembentukan domain dan informasi yang diketahui, saya perkirakan domain ini milik Miryam atau Faros."
  },
  AvgDialog_118954_Content_65 = {
    Text = "<Yellow:\"Inti\"> dari Domain adalah \"Ritual Panggilan Dewa\", melacak keberadaan Lemuria seharusnya adalah obsesi Penguasa Domain."
  },
  AvgDialog_118954_Content_66 = {
    Text = "Dan berdasarkan catatan penyelidikan Sonaniel, tujuan Goliath adalah kekuatan, obsesi Caecus adalah keturunan, hanya Miryam dan Phalos yang mendambakan cahaya kemuliaan Ranah Dewa."
  },
  AvgDialog_118954_Content_67 = {
    Text = "Selanjutnya, kunci pemilik domain, lalu?"
  },
  AvgDialog_118954_Content_68 = {
    Text = "Ketika sang pemilik domain mulai goyah tentang penyebab domain, celah akan muncul dan di dalamnya, \"Clades\" akan muncul."
  },
  AvgDialog_118954_Content_69 = {
    Text = "Namun, karena ini adalah Domain buatan, maka keamanan fisik kita bisa dijamin."
  },
  AvgDialog_118954_Content_7 = {
    Text = "Oleh karena itu, aku mengarahkanmu kepada orang yang bisa memberikan pencerahan."
  },
  AvgDialog_118954_Content_70 = {
    Text = "Jangan meremehkan. Belum lagi bahwa Domain buatan saat ini masih sebatas spekulasi kita..."
  },
  AvgDialog_118954_Content_71 = {
    Text = "Setelah 306 tahun banjir, Penyelidik Jude Bright terjebak dalam jebakan Pemburu dan patah kaki kanannya. Setelah kembali ke realitas, kaki kanannya juga mulai membusuk."
  },
  AvgDialog_118954_Content_72 = {
    Text = "Cara pengaruh Domain terhadap realitas saat ini masih tidak dapat dipastikan, tetapi kehati-hatian selalu merupakan hal yang benar."
  },
  AvgDialog_118954_Content_73 = {Text = "Paham."},
  AvgDialog_118954_Content_74 = {
    Text = "Setelah ritual selesai, aku akan menghadapi Miryam, Faros akan kau tangani."
  },
  AvgDialog_118954_Content_75 = {
    Text = "Semoga Kunci Perak menuntun jalanmu."
  },
  AvgDialog_118954_Content_76 = {
    Text = "Nada yang akrab membuatmu tertegun sejenak, tetapi segera mengungkapkan senyum tulus."
  },
  AvgDialog_118954_Content_77 = {
    Text = "Semoga Kunci Perak membimbing kita."
  },
  AvgDialog_118954_Content_78 = {
    Text = "Wanita berwawasan menghuni sudut kabin kapten sendirian, lampu di atas kepalanya berkedip samar mengikuti napasnya."
  },
  AvgDialog_118954_Content_79 = {
    Text = "Pharos……"
  },
  AvgDialog_118954_Content_8 = {
    Text = "Dalam pantulan gelombang mimpi, muncul sosok yang berdiri tegak."
  },
  AvgDialog_118954_Content_80 = {
    Text = "Saat kau membuka mulut, tiba-tiba kau terhenti. Kau berusaha mengingat informasi terkait faros, baru kemudian menyadari bahwa catatan tentangnya di Mythag sangat sedikit."
  },
  AvgDialog_118954_Content_81 = {
    Text = "Dia merindukan kembali ke Ranah Dewa, dia membimbing para pelancong ke jalan yang salah."
  },
  AvgDialog_118954_Content_82 = {
    Text = "Selain itu, dokumen lainnya semuanya kosong."
  },
  AvgDialog_118954_Content_83 = {
    Text = "Apa yang terjadi, melihat ekspresimu, apakah kamu merasa bingung?"
  },
  AvgDialog_118954_Content_84 = {
    Text = "Mungkin…… saya bisa sedikit membantu memberi petunjuk untukmu?"
  },
  AvgDialog_118954_Content_85 = {
    Text = "Takutnya..."
  },
  AvgDialog_118954_Content_86 = {
    Text = "Saya tahu siapa pemilik Domain."
  },
  AvgDialog_118954_Content_9 = {
    Text = "Gelombang bayangan, pecah dan bersatu, secara bertahap stabil menjadi wajah dingin yang akrab dalam ingatan Anda."
  },
  AvgDialog_118955_Content_1 = {Text = "Orang luar"},
  AvgDialog_118955_Content_10 = {Text = "William…"},
  AvgDialog_118955_Content_11 = {
    Text = "Namun kamu tidak seharusnya berhenti di sini, dia telah melalui banyak hari dan malam di sini, hanya kamu yang dapat mengakhiri dengan menemukan pemilik domain mimpi."
  },
  AvgDialog_118955_Content_12 = {
    Text = "Di ujung kapal, kamu menemui seorang gadis muda."
  },
  AvgDialog_118955_Content_13 = {
    Text = "Ribuan pelaut berpakaian hitam tergeletak sembarangan di sekelilingnya, sementara dia tenang bersandar di altar, memegang seonggok daging busuk berwarna merah darah."
  },
  AvgDialog_118955_Content_14 = {Text = "Murphy…"},
  AvgDialog_118955_Content_15 = {
    Text = "Sebagaimana yang kamu janjikan, kamu datang."
  },
  AvgDialog_118955_Content_16 = {
    Text = "Pemilik domain mimpi adalah kamu."
  },
  AvgDialog_118955_Content_17 = {
    Text = "Ya, semua yang ada di kapal ini hanyalah sebuah mimpi. Termasuk semua yang kamu lihat sekarang, hanyalah\"realitas dalam mimpi\"."
  },
  AvgDialog_118955_Content_18 = {Text = "Kenapa?"},
  AvgDialog_118955_Content_19 = {
    Text = "Kenapa menciptakan domain mimpi seperti ini? Atau kenapa harus menjadi diriku yang sekarang?"
  },
  AvgDialog_118955_Content_2 = {
    Text = "Hah, hah, hē..."
  },
  AvgDialog_118955_Content_20 = {
    Text = "Itu adalah hari yang sangat jauh."
  },
  AvgDialog_118955_Content_21 = {
    Text = "Siluet kecil berjuang di salju."
  },
  AvgDialog_118955_Content_22 = {
    Text = "Hah, hah……"
  },
  AvgDialog_118955_Content_23 = {
    Text = "Sejak datang ke Antartika, Murphy telah merasakan sebuah kebebasan yang absurd."
  },
  AvgDialog_118955_Content_24 = {
    Text = "Dia bisa pergi ke mana saja sendirian. Tetapi ke mana pun dia pergi, yang dia lihat hanyalah hamparan salju yang pucat."
  },
  AvgDialog_118955_Content_25 = {
    Text = "Jangan bilang orang, bahkan jejak manusia yang pernah ada tidak ada."
  },
  AvgDialog_118955_Content_26 = {
    Text = "Apakah ini…… saya tersesat?"
  },
  AvgDialog_118955_Content_27 = {
    Text = "Gadis itu menoleh kembali pada jejak langkahnya. Di padang salju yang luas, satu jejak kaki yang hampir lurus menuju ke tempat yang tidak diketahui."
  },
  AvgDialog_118955_Content_28 = {
    Text = "Tidak masalah, selagi terus berjalan, kita pasti akan sampai di suatu tempat."
  },
  AvgDialog_118955_Content_29 = {
    Text = "Gadis itu menghitung persediaan makanan yang dibawanya, memastikan seberapa jauh dia bisa pergi dengan menghemat untuk waktu yang akan datang."
  },
  AvgDialog_118955_Content_3 = {
    Text = "Kau batuk keras, mencoba mengusir air laut yang meresap ke dalam paru-parumu."
  },
  AvgDialog_118955_Content_30 = {
    Text = "Ayo, Murphy. Ini adalah perjalanan menuju kebebasan, tidak apa-apa kalau perutmu lapar."
  },
  AvgDialog_118955_Content_32 = {
    Text = "……………"
  },
  AvgDialog_118955_Content_33 = {
    Text = "Tidak bisa, dalam badai salju seperti ini, tidak bisa membedakan jalan."
  },
  AvgDialog_118955_Content_34 = {
    Text = "Makanan kering dengan air salju, rasanya benar-benar sangat tidak enak."
  },
  AvgDialog_118955_Content_35 = {
    Text = "Terkadang dia bersarang di dalam gua salju, dan masih bisa mendengar suara binatang buas. Dia belum pernah melihatnya, hanya tahu bahwa itu adalah sejenis serigala putih."
  },
  AvgDialog_118955_Content_36 = {Text = "Tolong!"},
  AvgDialog_118955_Content_37 = {
    Text = "Murphy dengan panik melarikan diri dari gua. Pasangan mata hijau yang bersinar itu tetap di gua, tidak mengikuti langkahnya."
  },
  AvgDialog_118955_Content_38 = {
    Text = "Dalam keadaan putus asa seperti ini, saya melihat sepasang jejak kaki."
  },
  AvgDialog_118955_Content_39 = {
    Text = "Jejak kaki manusia...!"
  },
  AvgDialog_118955_Content_4 = {
    Text = "Namun tidak ada yang bisa dikeluarkan, paru-paru hanya tersisa saraf yang bergetar dan rasa sakit tenggelam."
  },
  AvgDialog_118955_Content_40 = {
    Text = "Selama ada orang, ada harapan. Aku tidak ragu mengikuti."
  },
  AvgDialog_118955_Content_42 = {
    Text = "Tidak lama kemudian, jejak kaki berubah menjadi dua baris."
  },
  AvgDialog_118955_Content_43 = {
    Text = "Tiga baris."
  },
  AvgDialog_118955_Content_44 = {
    Text = "Jejak kaki semakin banyak, tetapi pemilik jejak kaki tersebut tidak juga terlihat."
  },
  AvgDialog_118955_Content_45 = {
    Text = "Aku yang terlalu lelah akhirnya pingsan."
  },
  AvgDialog_118955_Content_46 = {
    Text = "Baru kemudian aku tahu, karena panjang kaki kanan dan kiri berbeda, setiap orang saat berjalan tanpa bisa menentukan arah, akan sedikit miring ke satu arah."
  },
  AvgDialog_118955_Content_47 = {
    Text = "Dengan kata lain... saat itu, jejak langkahku adalah sebuah lingkaran."
  },
  AvgDialog_118955_Content_48 = {
    Text = "Jejak yang saya lihat bernama harapan, berasal dari diriku yang lalu, menuju siklus tanpa akhir."
  },
  AvgDialog_118955_Content_49 = {
    Text = [[
Karena sedikit penyimpangan yang nyaris tidak berarti... 
Hidupku terus terjebak dalam lingkaran setan.]]
  },
  AvgDialog_118955_Content_5 = {
    Text = "Kenapa…… bukankah seharusnya ini putaran terakhir?"
  },
  AvgDialog_118955_Content_50 = {
    Text = "Titik pusat dari lingkaran itu disebut takdir."
  },
  AvgDialog_118955_Content_51 = {
    Text = "Inilah yang telah saya bangun, siklus yang menjebak saya sendiri."
  },
  AvgDialog_118955_Content_52 = {
    Text = "Artinya……"
  },
  AvgDialog_118955_Content_53 = {
    Text = "Sejak Goliath mulai mempersiapkan pemberontakan untuk pertama kalinya, waktu telah terhenti."
  },
  AvgDialog_118955_Content_54 = {
    Text = [[
Semua orang terbenam dalam mimpi, memulai siklus mimpi yang terus-menerus.
Siklus mimpi dimulai dari lahirnya Sang Suci hingga berakhir dengan karamnya kapal pesiar.]]
  },
  AvgDialog_118955_Content_55 = {
    Text = "Selama Goliath belum melancarkan pengkhianatan, semua dapat baik-baik saja seperti semula."
  },
  AvgDialog_118955_Content_56 = {
    Text = "Tetapi aku pernah melihat Goliath di Kota Makam..."
  },
  AvgDialog_118955_Content_57 = {
    Text = "Untuk mempertahankan domain mimpi, setiap beberapa waktu, aku akan mengirim sekelompok orang keluar untuk mengumpulkan energi untuk patung gading."
  },
  AvgDialog_118955_Content_58 = {
    Text = "Selama kembali ke Dimensi mimpi, mereka akan melupakan pengalaman ini dan menjadi penduduk Dimensi mimpi."
  },
  AvgDialog_118955_Content_59 = {
    Text = "Sayang sekali, sejak saat itu ketika kamu menghalangi kami untuk menyerap energi dari Kota Makam, Dimensi mimpi semakin tidak stabil."
  },
  AvgDialog_118955_Content_6 = {
    Text = "Kamu melihat sekeliling, di dek yang luas tidak ada siapa-siapa, tidak ada laba-laba ungu, dan juga tidak ada pengikut yang mengelilingi."
  },
  AvgDialog_118955_Content_60 = {
    Text = "Kenapa kamu ingin aku melihatmu?"
  },
  AvgDialog_118955_Content_61 = {
    Text = "Awalnya aku ingin memanggilmu, berharap untuk menghancurkan semua faktor ketidakstabilan, mencekikmu dalam mimpi ini..."
  },
  AvgDialog_118955_Content_62 = {
    Text = "Hanya sebelum itu, perak di tanganku sepertinya beresonansi dengan kunci perak milikmu, aku tersambung ke Mimpimu, Memori-mu."
  },
  AvgDialog_118955_Content_63 = {
    Text = "Dalam mimpi, aku melihat kemungkinan lain… diriku yang lain."
  },
  AvgDialog_118955_Content_64 = {
    Text = "Aku melihatnya berkompetisi dalam kelas patung bersama teman-temannya;"
  },
  AvgDialog_118955_Content_65 = {
    Text = "Aku melihatnya bertengkar dengan kucing liar di bawah air mancur;"
  },
  AvgDialog_118955_Content_66 = {
    Text = "Saya melihatnya dipaksa teman-temannya untuk mengenakan gaun setan kecil, membawa lentera labu dan membagikan permen pintu ke pintu..."
  },
  AvgDialog_118955_Content_67 = {
    Text = "Di dunia di mana sakral belum lahir, dia benar-benar... sangat bahagia."
  },
  AvgDialog_118955_Content_68 = {
    Text = "Mengagumkan dan membuat iri."
  },
  AvgDialog_118955_Content_69 = {
    Text = "Juga menginginkan untuk menjadi."
  },
  AvgDialog_118955_Content_7 = {
    Text = "Kau melarikan diri, mencarinya."
  },
  AvgDialog_118955_Content_70 = {
    Text = "<Yellow:%player%>, sampai aku bertemu denganmu, aku baru tahu bahwa di dunia ini masih ada cara hidup yang sederhana dan bahagia seperti ini……"
  },
  AvgDialog_118955_Content_71 = {
    Text = "Tidak perlu mahkota kesombongan Sang Ibu, tidak perlu kehormatan yang dihormati banyak orang, tidak perlu sehari-hari menghadapi wajah para pengikut yang membosankan……"
  },
  AvgDialog_118955_Content_72 = {
    Text = "Apa tanggung jawab ini, apa warisan ini, mengapa begitu banyak orang harus mengorbankan kehidupan mereka untuk seonggok daging busuk?"
  },
  AvgDialog_118955_Content_73 = {
    Text = "Kamu tetap diam, kamu hanya bisa diam."
  },
  AvgDialog_118955_Content_74 = {
    Text = "Murphy mengingkari dirinya yang dulu."
  },
  AvgDialog_118955_Content_75 = {
    Text = "Saya masih memiliki satu pertanyaan terakhir untuk kamu."
  },
  AvgDialog_118955_Content_76 = {
    Text = "Di dunia mu, apakah kamu juga mengajaknya membuat kue kecil?"
  },
  AvgDialog_118955_Content_77 = {
    Text = "Di dunia itu... Bukan hanya aku, akan ada banyak orang yang bersedia membantumu, menemanimu dalam apa pun yang ingin kamu lakukan, yang sesuka hatimu."
  },
  AvgDialog_118955_Content_78 = {
    Text = "Murphy, karena kamu mencintai dunia, mencintai semua orang."
  },
  AvgDialog_118955_Content_79 = {
    Text = "Karena kau, telah membelah hatimu sendiri dan semua orang melihatnya secara langsung."
  },
  AvgDialog_118955_Content_8 = {
    Text = "Tertidur， tertidur， semua orang tertidur."
  },
  AvgDialog_118955_Content_80 = {
    Text = "Jantung yang bergetar."
  },
  AvgDialog_118955_Content_81 = {
    Text = "Murphy tersenyum, senyumnya bersinar seperti kenangan masa lalumu."
  },
  AvgDialog_118955_Content_82 = {
    Text = "Tahukah kamu? Kapal ini adalah sebuah mimpi."
  },
  AvgDialog_118955_Content_83 = {
    Text = [[
Aku dulu berpikir itu adalah mimpi indah...
Aku adalah Ibu Dewa yang mulia, dan daging yang merayap adalah Dewa yang katanya.]]
  },
  AvgDialog_118955_Content_84 = {
    Text = "Hari dan malam, saya hidup dalam ketakutan, merasa gelisah dan tersiksa."
  },
  AvgDialog_118955_Content_85 = {
    Text = "Ternyata mimpi ini bukan mimpi indah, tetapi mimpi buruk yang menakutkan, yang bahkan aku sendiri tidak sadar."
  },
  AvgDialog_118955_Content_86 = {
    Text = "Jadi, sekarang, ungkap tirai kebohongan, biarkan mimpi bangun."
  },
  AvgDialog_118955_Content_9 = {
    Text = "William terbaring di atas geladak, seragamnya penuh noda, seolah-olah telah dilanda badai dan terik matahari berulang kali, minyak dan garam membentuk peta yang berbintik-bintik."
  },
  AvgDialog_118956_Content_1 = {
    Text = "Kalian bertempur dan mundur, dari Ruang kekuatan ke koridor, dari koridor ke dek, hingga di belakangmu hanya ada pagar yang memisahkanmu dengan lautan tak berujung."
  },
  AvgDialog_118956_Content_10 = {
    Text = "Raksasa yang kuat mundur dengan cepat di bawah doronganmu, tampaknya akan menabrak papan lambung."
  },
  AvgDialog_118956_Content_11 = {
    Text = "Dalam sekejap, ia menusukkan bilah besar ke tanah, berjuang untuk menjaga keseimbangan."
  },
  AvgDialog_118956_Content_12 = {
    Text = "Kau, nak, telah berkembang sejak terakhir kita bertemu."
  },
  AvgDialog_118956_Content_13 = {
    Text = "Tidak, bukan seperti itu."
  },
  AvgDialog_118956_Content_14 = {
    Text = "Bukan kamu yang menjadi lebih kuat, melainkan Goliath yang menjadi lebih lemah."
  },
  AvgDialog_118956_Content_15 = {
    Text = "Bahkan dengan Faros yang membantu, kekuatan Goliath tidak sebanding dengan pertemuanmu yang terakhir dengan dia."
  },
  AvgDialog_118956_Content_16 = {
    Text = "Setiap serangan terasa ringan, sama sekali tidak berasal dari tangan raksasa yang memeliki kekuatan luar biasa."
  },
  AvgDialog_118956_Content_17 = {
    Text = "Goliath, sejak pertama kali bertempur aku menyadari, kekuatan tidak manusiawi di tubuhmu… sedang menurun dengan cepat."
  },
  AvgDialog_118956_Content_18 = {
    Text = "Hmph, bahkan jika sepuluh kali lebih lemah, bukan kamu yang bisa menandinginya, nak kecil."
  },
  AvgDialog_118956_Content_19 = {
    Text = "Apakah ini berkaitan dengan Faros muncul di sini?"
  },
  AvgDialog_118956_Content_2 = {
    Text = "Kamu sangat bertahan… ternyata bisa bertahan sampai di sini."
  },
  AvgDialog_118956_Content_20 = {
    Text = "Lebih jauh lagi, apakah itu terkait dengan fenomena di kapal ini?"
  },
  AvgDialog_118956_Content_21 = {
    Text = "Kau tergesa-gesa melaksanakan pengaturan yang dikatakan karena kelemahan kekuatanmu sendiri?"
  },
  AvgDialog_118956_Content_22 = {
    Text = "Hmph, jangan berharap tahu hal yang tidak seharusnya kamu ketahui, tidak peduli seberapa banyak kamu bertanya, jangan harap aku mengeluarkan sepatah kata pun dariku."
  },
  AvgDialog_118956_Content_23 = {
    Text = "Jika tujuan kita sama, saya mungkin bukan pilihan yang harus kamu singkirkan."
  },
  AvgDialog_118956_Content_24 = {
    Text = "Masing-masing mundur sedikit, aku tidak mengganggu niat pengkhianatanmu terhadap Pelaut, kamu juga jangan menyusahkan aku."
  },
  AvgDialog_118956_Content_25 = {
    Text = "Goliath belum menjawab, dua bayangan ular berbisa menyambar kalian dengan kilat!"
  },
  AvgDialog_118956_Content_27 = {
    Text = "Kalian mundur secara mendadak, bayangan ular meledak di dek, menciptakan dua lubang mengerikan yang mengeluarkan asap hitam."
  },
  AvgDialog_118956_Content_28 = {
    Text = "Dua pengkhianat yang tidak tahu berterima kasih, di sini tidak ada ruang bagi kalian untuk mencapai kesepakatan."
  },
  AvgDialog_118956_Content_29 = {
    Text = "Mengenai orang asing... Saat melarikan diri, sepertinya kau melupakan sesuatu yang penting."
  },
  AvgDialog_118956_Content_3 = {
    Text = "Tetapi, kau sudah tidak punya jalan kembali."
  },
  AvgDialog_118956_Content_30 = {
    Text = [[
Patung gading melayang di tangan Miryam.
Dia berdoa dengan tulus, bahasa yang menodai mengalir dari mulutnya seperti cacing.]]
  },
  AvgDialog_118956_Content_31 = {
    Text = "<Change>Raga dan jiwa kalian seharusnya menjadi milik bayangan lautan."
  },
  AvgDialog_118956_Content_32 = {
    Text = "Tunggu, miryam, jangan—"
  },
  AvgDialog_118956_Content_33 = {
    Text = "Maaf, Ibu Dewa, aku harus menghukum orang-orang yang menodai ini untukmu."
  },
  AvgDialog_118956_Content_34 = {
    Text = "Patung gading mengeluarkan desisan tanpa suara, ratusan benang perak menyebar, seakan parasit di jantung rakyat di negara laut."
  },
  AvgDialog_118956_Content_35 = {
    Text = "Ini... wanita gila, apa yang kamu lakukan?!"
  },
  AvgDialog_118956_Content_36 = {
    Text = "Apa yang saya lakukan? Tentu saja memberikan belas kasihan Dewa, kasih sayang Dewa, dan kekuatan Dewa yang tak tertandingi kepada kalian."
  },
  AvgDialog_118956_Content_37 = {
    Text = "Benang terjerat erat, seketika merapat dengan kuat——"
  },
  AvgDialog_118956_Content_38 = {
    Text = "Tuan Goliath... saya merasa tidak bisa bernapas..."
  },
  AvgDialog_118956_Content_39 = {
    Text = "<Shake:Aah…… saya merasakannya…… aliran Dewa…… saya menyentuh…… jiwanya……>"
  },
  AvgDialog_118956_Content_4 = {
    Text = "Kau menarik nafasku dalam-dalam, menenangkan diri, dan menghadapi Goliath yang kembali melayangkan pedangnya yang besar."
  },
  AvgDialog_118956_Content_40 = {Text = "Pah."},
  AvgDialog_118956_Content_41 = {
    Text = "Jantung meledak berturut-turut, kotoran merah menyebar di dek seperti gelombang darah."
  },
  AvgDialog_118956_Content_42 = {
    Text = "Berapa lama pun pengaruhnya, itu tidak akan mengubah kebodohan para yang tidak percaya."
  },
  AvgDialog_118956_Content_43 = {
    Text = "<Shake: Mari gunakan darah dan jiwa kalian untuk membentuk tangga menuju Ranah dewa!>"
  },
  AvgDialog_118956_Content_44 = {
    Text = "<Shake:Berhentilah dia……<Big:bersamaku, hentikan dia!>>"
  },
  AvgDialog_118956_Content_6 = {
    Text = "Jalan buntu di matamu adalah medan perang yang telah kutentukan untukmu."
  },
  AvgDialog_118956_Content_7 = {
    Text = "Kau telah memboroskan kekuatan, dan sekarang, saatnya bagi saya untuk melawan balik."
  },
  AvgDialog_118956_Content_8 = {
    Text = [[
Cahaya perak mendadak memancar, menghempaskan dengan kekuatan yang luar biasa, menghantam goliath. 
Goliath segera mengangkat pedangnya untuk melawan, tetapi sudah terlambat.]]
  },
  AvgDialog_118957_Content_1 = {Text = "Penutup"},
  AvgDialog_118957_Content_10 = {
    Text = "Sungguh mimpi yang panjang sekali."
  },
  AvgDialog_118957_Content_11 = {
    Text = "Kematian, Penghianatan, Tenggelam, semakin ingin aku menahan sesuatu, semakin tidak terhindarkan itu meluncur dari celah jari."
  },
  AvgDialog_118957_Content_12 = {
    Text = "Mungkin ini adalah takdir. Tak dapat diubah, tidak perlu dipaksakan."
  },
  AvgDialog_118957_Content_13 = {
    Text = "Segera lepaskan, mungkin Anda akan bertemu teman yang sejalan lebih baik."
  },
  AvgDialog_118957_Content_14 = {
    Text = "Misalnya… <Mythag>?"
  },
  AvgDialog_118957_Content_15 = {
    Text = "Orang-orang Mythag tampaknya sangat pandai beradaptasi... atau menghaluskan semua sifat buruk orang."
  },
  AvgDialog_118957_Content_16 = {
    Text = "Saya ingat ada satu tahun, Murphy merengek ingin mencoba semua rasa permen, hasilnya dia malah mengeluh sakit gigi."
  },
  AvgDialog_118957_Content_17 = {
    Text = "Sylvia akhirnya membuat Jenkin mencuri seluruh stok wanita yang baik."
  },
  AvgDialog_118957_Content_18 = {
    Text = "Puff. Lalu?"
  },
  AvgDialog_118957_Content_19 = {
    Text = "Lalu dia mulai menangani pencurian dengan sangat besar, sepenuhnya melupakan permen."
  },
  AvgDialog_118957_Content_2 = {
    Text = "Kapal Parades sudah berlabuh, selanjutnya…"
  },
  AvgDialog_118957_Content_20 = {
    Text = "Ada satu kesempatan lagi......"
  },
  AvgDialog_118957_Content_21 = {
    Text = "Baiklah, berapa banyak lagi yang kau ingin aku cemburu padanya?"
  },
  AvgDialog_118957_Content_22 = {
    Text = "Ketika kita kembali ke Mythag, semuanya juga akan menjadi milikmu."
  },
  AvgDialog_118957_Content_23 = {
    Text = "Semoga suatu hari kita bertemu di Mythag."
  },
  AvgDialog_118957_Content_24 = {
    Text = "Murphy merentangkan tangannya ke langit yang jauh, seolah ingin menyentuh matahari di ketinggian."
  },
  AvgDialog_118957_Content_25 = {
    Text = "Bayangan gelap bulat berwarna hitam menggulung di sela-sela jari-jarinya."
  },
  AvgDialog_118957_Content_26 = {
    Text = "Ada satu hal lagi yang harus kuberitahu padamu."
  },
  AvgDialog_118957_Content_27 = {
    Text = "Tatapan Murphy langsung menembus Anda."
  },
  AvgDialog_118957_Content_28 = {
    Text = "Dunia ini sudah punah, tak bisa diselamatkan, dipenuhi oleh keputusasaan yang lebih mendalam daripada siklus yang pernah saya alami."
  },
  AvgDialog_118957_Content_29 = {
    Text = "Jika bisa, aku bisa mencoba mengantarmu kembali."
  },
  AvgDialog_118957_Content_3 = {
    Text = "Mereka sudah tahu semua tentang dewa-dewa di dunia ini, dan secepatnya akan membuat pilihan mereka sendiri."
  },
  AvgDialog_118957_Content_30 = {
    Text = "Bawa aku... kembali?"
  },
  AvgDialog_118957_Content_31 = {
    Text = "Tahukah kamu cara untuk melintasi dua dunia?"
  },
  AvgDialog_118957_Content_32 = {
    Text = "Tidak bisa dibilang tahu, tetapi jika hanya menyadari esensi dunia ini, tentu saja bisa memahami titik-titik penghubung dunia."
  },
  AvgDialog_118957_Content_33 = {
    Text = "Kapal ini adalah sebuah mimpi, tetapi ketika tirai kebohongan terangkat..."
  },
  AvgDialog_118957_Content_34 = {
    Text = "Seluruh dunia juga adalah mimpi seseorang, hanya saja mimpi ini lebih besar, lebih samar, dan lebih jauh……"
  },
  AvgDialog_118957_Content_35 = {
    Text = "Bahkan bulan dan bintang pun bersumber dari khayalan-Nya, hanya makhluk hidup yang terjerat dengan roh-Nya yang bisa……"
  },
  AvgDialog_118957_Content_36 = {
    Text = "Matahari dan bulan bintang…"
  },
  AvgDialog_118957_Content_37 = {
    Text = "Lapisan hitam bergetar, membentuk jalur sutra yang berbelok-belok menuju ufuk langit."
  },
  AvgDialog_118957_Content_38 = {
    Text = "Kembalilah, pulanglah, kembali ke duniamu! Tidak perlu merindukan dunia yang telah mati ini."
  },
  AvgDialog_118957_Content_39 = {
    Text = "Kalau begitu, Anda, Murphy?"
  },
  AvgDialog_118957_Content_4 = {
    Text = "Menurutku, Miryam dan Faros seharusnya berlayar kembali, mencari keberadaan Lemuria."
  },
  AvgDialog_118957_Content_40 = {
    Text = "Kamu menahan diri untuk segera melangkah di atas jalan pasir, berbalik bertanya pada Murphy yang diam."
  },
  AvgDialog_118957_Content_41 = {
    Text = "Siapa yang tahu? Dunia ini adalah dunia yang telah hancur."
  },
  AvgDialog_118957_Content_42 = {
    Text = "Terimalah ini. Mungkin suatu hari, kamu bisa merasakan perak di dunia itu."
  },
  AvgDialog_118957_Content_43 = {
    Text = "Sebuah batu permata yang terbentuk dari setetes darah jatuh ke telapak tanganmu, berasal dari luka aneh yang menembus dadanya."
  },
  AvgDialog_118957_Content_44 = {
    Text = "Anda tidak tahu, yang Anda panggil, di periode mana \"saya\" itu?"
  },
  AvgDialog_118957_Content_45 = {
    Text = "Namun, ketika kau memanggilku, ingatlah penampilanku yang sekarang…"
  },
  AvgDialog_118957_Content_46 = {
    Text = "Kelahiran-Nya adalah ilusi… membentuk mimpi hanya kebohongan…"
  },
  AvgDialog_118957_Content_47 = {
    Text = "Panggil aku...\"<Yellow:Kelahiran Palsu·Murphy>\"!"
  },
  AvgDialog_118957_Content_48 = {
    Text = "Kau berjalan perlahan di jalan sutra, berbagai pemikiran melintas di dalam kepalamu."
  },
  AvgDialog_118957_Content_49 = {
    Text = "Perjalanan melawan pelarutan, dua dunia yang terjerat dalam mimpi hitam, banyak wajah yang mirip atau sama saling tumpang tindih..."
  },
  AvgDialog_118957_Content_5 = {
    Text = "Goliath dan Caecus mungkin akan pergi, bahkan di dunia yang agak tandus ini, mereka memiliki perjalanan mereka sendiri."
  },
  AvgDialog_118957_Content_50 = {
    Text = "Dua Doll..."
  },
  AvgDialog_118957_Content_51 = {
    Text = "Dua Clementine..."
  },
  AvgDialog_118957_Content_52 = {
    Text = "Dua Murphy..."
  },
  AvgDialog_118957_Content_53 = {
    Text = "Akhirnya terhenti pada wajah tersenyum Ramona."
  },
  AvgDialog_118957_Content_54 = {
    Text = "Saya... bisa kembali?"
  },
  AvgDialog_118957_Content_55 = {
    Text = "Dengan cara yang mengagumkan, kamu menemukan dirimu sudah berdiri hanya sejauh satu lengan dari matahari hitam, namun tidak merasakan panas sama sekali."
  },
  AvgDialog_118957_Content_56 = {
    Text = "Kegelapan tak terbatas itu menelan semua cahaya, segera siap untuk menelan Anda pula."
  },
  AvgDialog_118957_Content_57 = {
    Text = "Ramona... Apakah kau akan menunggu aku setelah ini?"
  },
  AvgDialog_118957_Content_58 = {
    Text = "Kau menutup mata, dengan lembut mengulurkan ujung jarimu, menyentuh lorong hitam itu."
  },
  AvgDialog_118957_Content_59 = {
    Text = "Jika bisa, pegang tanganku."
  },
  AvgDialog_118957_Content_6 = {
    Text = "Adapun \"yang ini\" Murphy..."
  },
  AvgDialog_118957_Content_60 = {
    Text = "Dari kaki Anda, dari ribuan mimpi dalam."
  },
  AvgDialog_118957_Content_61 = {
    Text = "Dengan matahari hitam sebagai titik awal, selubung hitam mulai perlahan memudar."
  },
  AvgDialog_118957_Content_62 = {
    Text = "Kamu terjatuh dari ketinggian."
  },
  AvgDialog_118957_Content_63 = {
    Text = "<Yellow:Jatuh ke dalam pusaran yang disebut \"takdir\".>"
  },
  AvgDialog_118957_Content_64 = {
    Text = "Aku dalam mimpi yang dalam, melihat pengalaman gadis itu."
  },
  AvgDialog_118957_Content_65 = {
    Text = "Sangat disayangkan, Yu awalnya mengirimnya pergi dari Lemuria dan menyerahkan patung gading dalam mimpinya, bukan untuk akhir seperti ini."
  },
  AvgDialog_118957_Content_66 = {
    Text = "Bukankah seharusnya berterima kasih atas peran yang aku mainkan di dalamnya?"
  },
  AvgDialog_118957_Content_67 = {
    Text = "Cahaya harapan di dunia ini sudah punah, kamu seharusnya mengetahuinya, bukan?"
  },
  AvgDialog_118957_Content_68 = {
    Text = "Wanita yang mengusap roda pemintal tidak berbicara, hanya membiarkan benang yang dipegangnya meluas hingga ke bawah langit, di antara semua makhluk."
  },
  AvgDialog_118957_Content_69 = {
    Text = "Selama masih ada satu benih."
  },
  AvgDialog_118957_Content_7 = {
    Text = "Saya rasa, dia pasti ada beberapa hal ingin dikatakan padamu."
  },
  AvgDialog_118957_Content_70 = {
    Text = "Tidak peduli berapa lama keheningan, di mana pun tanah itu, pada akhirnya suatu hari akan mulai bertunas."
  },
  AvgDialog_118957_Content_71 = {
    Text = "Mengenai aku..."
  },
  AvgDialog_118957_Content_72 = {
    Text = "Wanita itu menunduk."
  },
  AvgDialog_118957_Content_73 = {
    Text = "Saya bukan penanam, bukan pembesaran, juga bukan pemanen."
  },
  AvgDialog_118957_Content_74 = {
    Text = "Saya hanya menarik tali yang menggantung, mengikuti hukum alam, menggambarkan orang yang menentukan nasib."
  },
  AvgDialog_118957_Content_75 = {
    Text = "Saya akan menarik benang dari jari penggulung, menariknya untuk mengeluarkan tanah yang paling sesuai."
  },
  AvgDialog_118957_Content_76 = {
    Text = "Saya akan menunggu dengan tenang."
  },
  AvgDialog_118957_Content_8 = {
    Text = "Kau datang?"
  },
  AvgDialog_118957_Content_9 = {Text = "Hm."},
  AvgDialog_118958_Content_1 = {Text = "Nukleus"},
  AvgDialog_118958_Content_10 = {
    Text = "Saya pernah bersekutu dengan goliath, tetapi para barbar yang hanya memahami perang dan kekerasan jelas tidak mengerti bagaimana mematuhi Kontrak, apalagi memimpin menuju jalur ke Lemuria."
  },
  AvgDialog_118958_Content_11 = {
    Text = "Bagaimana? Selama kau mengangguk setuju, aku akan membocorkan identitas pemilik domain kepadamu."
  },
  AvgDialog_118958_Content_12 = {
    Text = "Hati gadis itu terasa di kerongkongan."
  },
  AvgDialog_118958_Content_13 = {
    Text = "Izinkan saya menolak."
  },
  AvgDialog_118958_Content_14 = {
    Text = "Saya tidak bisa tergesa-gesa setuju untuk mengambil nyawa seseorang tanpa tahu siapa orang itu."
  },
  AvgDialog_118958_Content_15 = {
    Text = "Lagipula, karena kamu sudah mengajukan permintaan seperti itu, jelas bahwa pemilik Domain tidak berada di antara kamu, Goliath, dan Caecus."
  },
  AvgDialog_118958_Content_16 = {
    Text = "Dan kamu telah mengungkapkan bahwa hak atas mimpi terkait dengan patung gading itu."
  },
  AvgDialog_118958_Content_17 = {
    Text = "Jadi satu-satunya tersangka yang tersisa hanyalah dia…"
  },
  AvgDialog_118958_Content_18 = {
    Text = "Selera pilihan tempat observasimu sangat patut dipuji."
  },
  AvgDialog_118958_Content_19 = {
    Text = "Kau menarik tali, membuat layar di tiang menutupi bentukmu dan William."
  },
  AvgDialog_118958_Content_2 = {
    Text = "<Shake:tap tap tap, tap tap tap.>"
  },
  AvgDialog_118958_Content_20 = {
    Text = "Saat ritual sebelumnya saya memperhatikan, dibandingkan dengan kapal Sonariel, kapal Paladise mempertahankan struktur tiang yang relatif kuno."
  },
  AvgDialog_118958_Content_21 = {
    Text = "Setara dengan sebuah menara pengawas, dapat melihat situasi di lokasi upacara penuntun."
  },
  AvgDialog_118958_Content_22 = {
    Text = "Ketika upacara penuntun dimulai, miryam akan menyerahkan patung gading kepada murphy, ini adalah satu-satunya kesempatan kita untuk berinteraksi dengan patung gading."
  },
  AvgDialog_118958_Content_23 = {
    Text = "Mengambil patung dan menganalisanya, mungkin kita dapat menguasai cara untuk membatalkan Domain."
  },
  AvgDialog_118958_Content_24 = {
    Text = "Hush, mereka sudah datang."
  },
  AvgDialog_118958_Content_25 = {
    Text = "William mengetuk bahumu, memberi isyarat agar kamu melihat ke belakang."
  },
  AvgDialog_118958_Content_26 = {
    Text = "Perhatikan posisi Patung gading…… ini adalah garis hidup kami."
  },
  AvgDialog_118958_Content_27 = {
    Text = "Sama persis dengan ingatanmu, ritual penuntun berjalan dengan teratur."
  },
  AvgDialog_118958_Content_28 = {
    Text = "Kepada Dewa Ibu yang terhormat, mohon tarik garis keturunan Raja Dewa, pandu Pelaut yang tersesat, tunjukkan kepada kami arah Lemuria."
  },
  AvgDialog_118958_Content_29 = {
    Text = "Murphy menggigit bibirnya, menerima belati bercahaya dari tangan Miryam."
  },
  AvgDialog_118958_Content_3 = {
    Text = "Gadis itu berlari di koridor."
  },
  AvgDialog_118958_Content_30 = {
    Text = "Dia menganggkat pisau - lalu lama tidak menusukkan."
  },
  AvgDialog_118958_Content_31 = {
    Text = "Ibu Dewi, bukankah Anda sudah membuat keputusan sebelumnya? Lemuria masih terletak di dasar Jurang, menunggu kedatangan Anda."
  },
  AvgDialog_118958_Content_32 = {
    Text = "……Aku akan segera……"
  },
  AvgDialog_118958_Content_33 = {
    Text = "Bagian akhir kalimat ditelan."
  },
  AvgDialog_118958_Content_34 = {
    Text = "Dia memegang patung gading yang berlumuran darah, membiarkan monster cacat itu menghisap habis jiwanya."
  },
  AvgDialog_118958_Content_35 = {
    Text = "Sungai darah menyebar di sisi kapal, mengarah ke kiri."
  },
  AvgDialog_118958_Content_36 = {
    Text = "Berputar! Pengemudi laut, dengarlah wahyu, belok ke kiri penuh!"
  },
  AvgDialog_118958_Content_37 = {
    Text = "Tanggapan padanya adalah suara tajam yang menembus udara."
  },
  AvgDialog_118958_Content_38 = {
    Text = "Sepertinya saya tidak perlu melihat itu."
  },
  AvgDialog_118958_Content_39 = {
    Text = "Sumpit tajam seperti gigi tajam hiu, tiba-tiba menjulur dari kegelapan malam, tepat menembus tenggorokan juru mudi."
  },
  AvgDialog_118958_Content_4 = {
    Text = "Saat melewati ruangan kapten, suara yang tenang masuk ke telinganya."
  },
  AvgDialog_118958_Content_40 = {
    Text = "Pisau besar yang berat menggoreskan beberapa percikan api di dek, raksasa itu keluar dari kedalaman malam, menginjak tengkorak juru mudi, dan menunjukkan senyuman kejamnya kepada penyihir di depannya."
  },
  AvgDialog_118958_Content_41 = {
    Text = "Di belakangnya, suku yang mengenakan jas hujan pakaian minyak berwarna biru-abu menggenggam senjata tajam, dengan lapar menunggu perintah untuk membunuh."
  },
  AvgDialog_118958_Content_42 = {
    Text = "Goliath... apakah Anda masih tidak mau menyerah?"
  },
  AvgDialog_118958_Content_43 = {
    Text = "Kumpulkan pelaut, ciptakan kekacauan... berusaha untuk menghancurkan ketenangan surga..."
  },
  AvgDialog_118958_Content_44 = {
    Text = "Sangat disayangkan, saya bukan bagian dari ketenangan ini. Kali ini, lain kali, dan lain kali lagi... Perishite tidak akan rela selamanya terkurung di bawah."
  },
  AvgDialog_118958_Content_45 = {
    Text = "Ayo, Perishite!"
  },
  AvgDialog_118958_Content_46 = {
    Text = "Dalam suara jahat, suku-suku yang mengenakan jas hujan dipegang dengan senjata tajam, bergegas muncul dari bayangan."
  },
  AvgDialog_118958_Content_47 = {
    Text = "Rumble rendah bergetar karena semangat. Mereka menunggu dengan penuh hasrat, menunggu saat untuk mendapatkan kembali kejayaan, menunggu perintah untuk menghancurkan segalanya."
  },
  AvgDialog_118958_Content_48 = {
    Text = "<Big:Kill them！>"
  },
  AvgDialog_118958_Content_49 = {
    Text = "Lagu perang yang kasar mengoyak langit malam di lautan, suku yang liar meluncurkan tali, menyebar ke dalam kerumunan di dek dengan kecepatan yang sulit dipahami."
  },
  AvgDialog_118958_Content_5 = {
    Text = "Saya tahu siapa pemilik Domain, dan dapat memimpin kalian melewati batas-batas Domain, kembali ke dunia nyata."
  },
  AvgDialog_118958_Content_50 = {
    Text = "Orang Perishite yang menghidupi kehidupan merampok di pesisir seperti hiu yang mencium bau darah, dengan ganas dan lapar menyerang mangsa mereka, menggigit tubuh musuh dengan pedang melengkung yang tajam."
  },
  AvgDialog_118958_Content_51 = {
    Text = "Tuhanku, dengar panggilan para pengikut... mohon turunkan berkah kepada umat-Mu..."
  },
  AvgDialog_118958_Content_52 = {
    Text = "Miryam mengulurkan kedua tangan, cahaya gelap yang dalam mulai menyebar."
  },
  AvgDialog_118958_Content_53 = {
    Text = "Para Pelaut yang mengenakan jubah hitam aneh tidak mengeluarkan suara apapun, seperti sekelompok hantu hitam yang khusyuk, diam-diam merasakan berkah yang dalam, diam-diam menusukkan pisau ke dada musuh."
  },
  AvgDialog_118958_Content_54 = {
    Text = "Biru abu-abu dan hitam ungu, dua kumpulan kuda yang terpisah bertarung mati-matian dalam neraka yang bergerak ini."
  },
  AvgDialog_118958_Content_55 = {
    Text = "Membunuh, saudaraku… di sini, mengulangi kejayaan Perishite!"
  },
  AvgDialog_118958_Content_56 = {
    Text = "Pisau besar dengan leluasa memenggal kepala pengikut Pelaut yang menghalangi, darah asin yang memancut mengubah sebagian besar wajah Goliath menjadi merah darah."
  },
  AvgDialog_118958_Content_57 = {
    Text = "Dia menjilat darah di wajahnya, dan di bawah kilatan petir, melibas setiap pengikut yang menghadangnya dengan pedang raksasa yang dipegangnya."
  },
  AvgDialog_118958_Content_58 = {
    Text = "Darah baru saja mengalir dari tubuh yang hangat, segera terlarut oleh hujan deras, bercampur dengan air laut, membentuk arus merah yang licin di dek yang bergoyang."
  },
  AvgDialog_118958_Content_59 = {
    Text = "<Shake:Tuhanku, saya telah mendengar perintah-Mu. Pengikut-Mu, akan bersamamu kembali ke Ranah dewa……>"
  },
  AvgDialog_118958_Content_6 = {
    Text = "Gadis itu berusaha tenang, langkahnya menjadi lebih pelan."
  },
  AvgDialog_118958_Content_60 = {
    Text = "Upacara, badai, pertempuran…"
  },
  AvgDialog_118958_Content_61 = {
    Text = "Di tengah kekacauan ini, di bawah patung gading yang menakutkan di buritan kapal, Miryam berdiri tegak, membisikkan doa dengan penuh devosi di tengah badai."
  },
  AvgDialog_118958_Content_62 = {
    Text = "Dia tidak acuh terhadap lautan darah dan gunung mayat di sekelilingnya, belati meluncur di dekat telinganya, ombak besar mengalirkan air ke seluruh tubuhnya, dan dia tidak menyadarinya."
  },
  AvgDialog_118958_Content_63 = {
    Text = "Semoga wahyu Dewa Anda membimbing kami, semoga tubuh Anda melindungi kami."
  },
  AvgDialog_118958_Content_64 = {
    Text = "Miryam...... berhentilah! Kita tidak bisa mencapai Lemuria!"
  },
  AvgDialog_118958_Content_65 = {
    Text = "Tidak… Dia berjanji padaku, Anda juga mendengar wahyu-Nya, bukan?"
  },
  AvgDialog_118958_Content_66 = {
    Text = "Miryam dengan khusyuk menatap ke cakrawala."
  },
  AvgDialog_118958_Content_67 = {
    Text = "Badai adalah napasmu, guntur adalah genderang perangmu!"
  },
  AvgDialog_118958_Content_68 = {
    Text = "Tolong bimbing domba yang tersesat ini, <Big:ke arah kerajaan Anda!>"
  },
  AvgDialog_118958_Content_69 = {
    Text = "Sebuah kilatan cahaya putih memekakkan langit, seketika menerangi mata penuh gairah dan kerinduan."
  },
  AvgDialog_118958_Content_7 = {
    Text = "Namun bantuanku memiliki syarat."
  },
  AvgDialog_118958_Content_70 = {
    Text = "Gadis berbaju hitam meringkuk diam di sudut haluan kapal, tatapan kosongnya putus asa mengarah ke medan perang yang berperang, seperti boneka kain yang dibuang di tumpukan barang rongsokan."
  },
  AvgDialog_118958_Content_71 = {
    Text = "Ayo, kita turun!"
  },
  AvgDialog_118958_Content_72 = {
    Text = "Aku bertanggung jawab untuk mengambil patung gading!"
  },
  AvgDialog_118958_Content_73 = {
    Text = "Aku pergi untuk menyelamatkan Murphy saat mereka terjebak dalam kekacauan!"
  },
  AvgDialog_118958_Content_8 = {
    Text = "Apakah syaratmu...?"
  },
  AvgDialog_118958_Content_9 = {
    Text = "Bunuh penguasa Domain, ambil patung gading itu, dan serahkan kekuasaan Domain kepada saya."
  },
  AvgDialog_118959_Content_1 = {
    Text = "Saya membunuh diriku, mengangkat mahkota. Selain kebebasan, saya mendapatkan segala yang saya impikan."
  },
  AvgDialog_118959_Content_10 = {
    Text = "Karena kau berbeda."
  },
  AvgDialog_118959_Content_11 = {
    Text = "Apa perbedaan saya dengan mereka? Hanya dianggap sebagai korban di matamu, hanya pakan untuk daging busuk ini."
  },
  AvgDialog_118959_Content_12 = {
    Text = "Murphy mengangkat gumpalan kotor yang ada di tangannya, darah segar mengalir deras ke bawah."
  },
  AvgDialog_118959_Content_13 = {
    Text = "Tidak, kamu berbeda dari mereka."
  },
  AvgDialog_118959_Content_14 = {
    Text = "Karena……"
  },
  AvgDialog_118959_Content_15 = {
    Text = "Kami bersama-sama, melewati semuanya."
  },
  AvgDialog_118959_Content_16 = {
    Text = "Saya ingat pada hari kamu menanamkan embrio suci di dadamu, kamu bilang ingin makan churros."
  },
  AvgDialog_118959_Content_17 = {
    Text = "Kamu tiba-tiba menyadari bahwa makanan yang terlalu enak tidak cocok untuk dinikmati sendirian, lalu dengan canggung membagikan setengahnya padaku."
  },
  AvgDialog_118959_Content_18 = {
    Text = "Kemudian, janin mulai tumbuh, seluruh tubuhmu demam tinggi, kami melakukan segala cara namun tidak bisa menurunkan suhu, akhirnya kami hanya bisa membawamu ke ruang dingin di Antartika."
  },
  AvgDialog_118959_Content_19 = {
    Text = "Menjadi masalah besar bagi kami."
  },
  AvgDialog_118959_Content_2 = {
    Text = "Namun aku yang melahirkan bayi suci, tidak dapat meraih kemurahan wahyu, dan tidak dapat menunjukkan jalan menuju Lemuria…"
  },
  AvgDialog_118959_Content_20 = {
    Text = "Bahkan dalam kondisi sulit tersebut, kamu tetap mempertahankan tugasmu sebagai Ibu Dewa."
  },
  AvgDialog_118959_Content_21 = {
    Text = "Sebagian besar pendeta, menderita di tengah dinginnya, menemani dan menantikan di altar Antartika."
  },
  AvgDialog_118959_Content_22 = {
    Text = "Dan kamu tidak mengecewakan harapan, menjadi induk pertama yang melahirkan bayi suci."
  },
  AvgDialog_118959_Content_23 = {
    Text = "Kami bersama-sama, mencapai momen itu."
  },
  AvgDialog_118959_Content_24 = {
    Text = "Kami akan bersama-sama, berlayar ke Ranah dewa yang abadi."
  },
  AvgDialog_118959_Content_25 = {
    Text = "Miryam berjalan lamban dan tegas ke depan Murphy, menunduk."
  },
  AvgDialog_118959_Content_26 = {
    Text = "Kau adalah ibu dewa yang terhormat, aku siap berlutut selamanya di bawah kakimu, mempersembahkan kesetiaan seumur hidupku untukmu."
  },
  AvgDialog_118959_Content_27 = {
    Text = "Saya bersedia untuk selalu memandangmu dengan sikap seolah memperlakukan seorang \"Dewa\"."
  },
  AvgDialog_118959_Content_28 = {
    Text = "Murphy menatap Miryam dengan tatapan bingung."
  },
  AvgDialog_118959_Content_29 = {
    Text = "Miryam berlutut, meraih punggung tangannya, dan menjatuhkan ciuman yang tulus di atasnya."
  },
  AvgDialog_118959_Content_3 = {
    Text = "Jadi kamu menciptakan mimpi yang tak akan pernah berakhir ini……"
  },
  AvgDialog_118959_Content_30 = {
    Text = "Kembali ke sisiku, ya kan, \"Ibu Tuhan\"?"
  },
  AvgDialog_118959_Content_31 = {
    Text = "Murphy menunduk. Angin mereda, semesta kecil dalam celah hening dan sunyi."
  },
  AvgDialog_118959_Content_32 = {
    Text = "Semua ceritamu berkaitan dengan Sang Ibu. Semua gelarmu tak terlepas dari ibu dewa."
  },
  AvgDialog_118959_Content_33 = {
    Text = "Kau masih tidak mengerti... dan kau tidak akan pernah mengerti..."
  },
  AvgDialog_118959_Content_34 = {
    Text = "Di sela gigi, terdengar beberapa bisikan."
  },
  AvgDialog_118959_Content_35 = {
    Text = "Hanya tahu tentang doa, upacara, Ranah dewa, Lemuria, dan kelahiran Dewa..."
  },
  AvgDialog_118959_Content_36 = {
    Text = "Tidak akan pernah mengerti."
  },
  AvgDialog_118959_Content_37 = {
    Text = "Segala yang saya lakukan, titik akhir yang saya capai dengan gigih, ilusi yang saya pertahankan…"
  },
  AvgDialog_118959_Content_38 = {
    Text = "Hanya ingin dipanggil dengan sikap yang tulus olehmu..."
  },
  AvgDialog_118959_Content_39 = {Text = "Mama……"},
  AvgDialog_118959_Content_4 = {
    Text = "Jika saya tidak melakukan ini, dia pasti akan mencabut jantung saya dengan tangannya sendiri..."
  },
  AvgDialog_118959_Content_40 = {
    Text = "Angin kencang di laut menutupi bisikan yang sudah kabur."
  },
  AvgDialog_118959_Content_41 = {
    Text = "Sayang sekali, sayang sekali."
  },
  AvgDialog_118959_Content_42 = {
    Text = "Murphy menyeka air mata yang tersisa."
  },
  AvgDialog_118959_Content_43 = {
    Text = "Semua harapan saya terhadapmu hanya deliria, menjaga keseimbangan dengan kebohongan hanyalah ilusi abadi."
  },
  AvgDialog_118959_Content_44 = {
    Text = "Kau tidak akan pernah menjadi ibuku."
  },
  AvgDialog_118959_Content_45 = {
    Text = "Murphy yang kamu kenal sudah lama meninggal. KematianNya datang bersamaan dengan kelahiran Dewa."
  },
  AvgDialog_118959_Content_46 = {
    Text = "Yang berdiri di sini adalah sebuah pu awakener yang lahir dari abu kehidupan dan kecerdasan perak..."
  },
  AvgDialog_118959_Content_47 = {
    Text = "Orang yang membangkitkan saya dari puing-puing… tidak, bisakah itu disebut manusia?"
  },
  AvgDialog_118959_Content_48 = {
    Text = "Penghubung saya, ada di depan kalian."
  },
  AvgDialog_118959_Content_49 = {
    Text = "Dia dengan lembut membuka selimut, di wajahnya, kau menangkap kehangatan aneh yang belum pernah kau lihat sebelumnya, hampir menakutkan."
  },
  AvgDialog_118959_Content_5 = {
    Text = "Mengorbankan saya kepada raja yang dia kagumi."
  },
  AvgDialog_118959_Content_50 = {
    Text = "Saya membawanya ke dunia ini… dan ia membawaku kembali ke dunia ini…"
  },
  AvgDialog_118959_Content_51 = {
    Text = "Nasib yang tersesat terjalin erat, siklus terbalik tidak akan pernah berhenti."
  },
  AvgDialog_118959_Content_52 = {
    Text = "Ayah melahirkan anak, putri mengandung ayah, ayah kemudian membangunkan putrinya..."
  },
  AvgDialog_118959_Content_53 = {
    Text = "Tidak ada yang datang memutuskan ikatan berat ini， tidak ada yang menghalangi kekacauan kehidupan abadi yang terhubung oleh darah."
  },
  AvgDialog_118959_Content_54 = {
    Text = "Apakah kamu merasa bahwa kamu orang pertama yang terjebak dalam siklus ini?"
  },
  AvgDialog_118959_Content_55 = {
    Text = "Sebelum itu, saya telah masuk ke dalam siklus ini berkali-kali, dan setiap akhir siklus adalah mimpi buruk yang tak terkatakan."
  },
  AvgDialog_118959_Content_56 = {
    Text = "Karena menolak Lemuria, akhir yang menembus tubuh oleh miryam."
  },
  AvgDialog_118959_Content_57 = {
    Text = "Terjebak dengan rantai oleh Goliath, patung gading dirampas, mengakibatkan kapal tenggelam bersama."
  },
  AvgDialog_118959_Content_58 = {
    Text = "Ada dalam mimpi, sosok kurus namun kuat, membukakan jalan pelarian bagiku."
  },
  AvgDialog_118959_Content_59 = {
    Text = [[
Saya selalu percaya, semua itu bukanlah akhir yang sebenarnya.
Saya menunggu akhir yang khusus untuk "saya yang ini".]]
  },
  AvgDialog_118959_Content_6 = {
    Text = "Jadi kamu bilang dia selalu menunggu aku... aku tidak mengerti."
  },
  AvgDialog_118959_Content_60 = {
    Text = "Akhir yang sesungguhnya dapat segera tiba."
  },
  AvgDialog_118959_Content_61 = {
    Text = "Biarkan kapal ini terbalik."
  },
  AvgDialog_118959_Content_62 = {
    Text = "Layar hitam berfungsi seperti sutra yang diturunkan dari langit, menutupi dan mengisolasi kapal dari dunia luar di bawah sinar matahari hitam tanpa cahaya."
  },
  AvgDialog_118959_Content_63 = {
    Text = "Air laut yang tak berujung dan tak bertepi naik mengubur seluruh kapal Paradis ke dalam jurang yang gelap dan tak terlihat."
  },
  AvgDialog_118959_Content_64 = {
    Text = "Sekali lagi, kamu terperosok dalam kegelapan yang tiada akhir."
  },
  AvgDialog_118959_Content_7 = {
    Text = "<Shake:Kenapa? Miryam, kenapa?>"
  },
  AvgDialog_118959_Content_8 = {
    Text = "Jika saya bukan ibu dewa yang kompeten, maka kamu hanya perlu melepaskanku seperti biasa, bukan?"
  },
  AvgDialog_118959_Content_9 = {
    Text = "<Red:Biarkan aku pergi... Berikan aku kebebasan...>"
  },
  AvgDialog_118960_Content_1 = {
    Text = "Selubung Abadi"
  },
  AvgDialog_118960_Content_10 = {
    Text = "Tidak, aku selalu dapat mengendalikan segalanya dalam mimpi, aku bisa menentukan akhir dan awal siklus, aku……"
  },
  AvgDialog_118960_Content_11 = {
    Text = "Dewa memberikan kekuatan untuk bermimpi kepadamu, tetapi kamu terjebak dalam obsesi sendiri, menyia-nyiakan niat baik-Nya."
  },
  AvgDialog_118960_Content_12 = {
    Text = "Meminjam…?"
  },
  AvgDialog_118960_Content_13 = {
    Text = "Kau masih ingat dari mana patung itu berasal?"
  },
  AvgDialog_118960_Content_14 = {
    Text = "Patung… CitraNya…"
  },
  AvgDialog_118960_Content_15 = {
    Text = "Saat melahirkan... bayi suci..."
  },
  AvgDialog_118960_Content_16 = {
    Text = "Tidak, aku tidak pernah melihat patung ini dalam tujuh hari sejak lahirnya sang bayi suci."
  },
  AvgDialog_118960_Content_17 = {
    Text = "Patung-Nya… adalah…"
  },
  AvgDialog_118960_Content_18 = {
    Text = "Tidak heran saya selalu merasa ada satu potongan puzzle yang hilang dari jawaban lengkap."
  },
  AvgDialog_118960_Content_19 = {
    Text = [[
%player%, apakah kamu masih ingat penalaran kita? 
 Waktu lahirnya Domain, sebelum pelarutan menelan dunia dan matahari bertransformasi menjadi matahari hitam.]]
  },
  AvgDialog_118960_Content_2 = {
    Text = "<Red:Tidak boleh berakhir>"
  },
  AvgDialog_118960_Content_20 = {
    Text = "Sementara itu, Upacara Kelahiran bayi suci, pengorbanan dan kebangkitan Murphy, jelas terjadi setelah kelahiran Hari Hitam."
  },
  AvgDialog_118960_Content_21 = {
    Text = "Dengan kata lain, pada waktu itu Murphy hanyalah seorang manusia yang penuh semangat, tidak cukup untuk membangun mimpi ini."
  },
  AvgDialog_118960_Content_22 = {
    Text = "Orang yang menguasai kekuasaan sebelum itu... seharusnya adalah..."
  },
  AvgDialog_118960_Content_23 = {
    Text = "Raja dewa di dunia ini sudah lahir... tidak, lebih tepatnya, tidak pernah mati."
  },
  AvgDialog_118960_Content_24 = {
    Text = "Kau tidak dapat membangunkan kesadarannya, karena kesadarannya masih terlelap dalam mimpi panjang."
  },
  AvgDialog_118960_Content_25 = {
    Text = "Ia tidak tega melihatmu mati karena pengorbanan, khususnya memberikan seberkas kekuatan, menciptakan mimpimu dalam mimpi."
  },
  AvgDialog_118960_Content_26 = {
    Text = "Sayang sekali kamu menginginkan banyak... sehingga Mimpi terus hancur dan dimulai lagi, itulah inti dari kapal Paradise."
  },
  AvgDialog_118960_Content_27 = {
    Text = "Ia lahir dari keinginanmu, tetapi bukan budakmu..."
  },
  AvgDialog_118960_Content_28 = {
    Text = "<Yellow:Jadi, sekarang, Dia akan menjalankan misi yang diberikan oleh penciptanya.>"
  },
  AvgDialog_118960_Content_29 = {
    Text = "Tirai langit mulai bergelombang, kain hitam menyelimuti pandangan, tubuh raksasa menjulang seperti puncak gunung."
  },
  AvgDialog_118960_Content_3 = {Text = "?!"},
  AvgDialog_118960_Content_30 = {
    Text = "Itu bukan muncul dari jurang, tetapi \"niat\" itu sendiri yang menembus tubuh dimensi."
  },
  AvgDialog_118960_Content_31 = {
    Text = "Di bawah kubah yang membuat sesak, tubuh-Nya tampak tanpa suara: pucat, ramping, sendi yang membengkok, seperti tulang suci yang disiksa hingga cacat."
  },
  AvgDialog_118960_Content_32 = {
    Text = "<Big:<Shake:…!!!>>"
  },
  AvgDialog_118960_Content_33 = {Text = "Murphy…"},
  AvgDialog_118960_Content_34 = {
    Text = "Gambaran besar itu jelas merupakan sosok gadis yang Anda kenal."
  },
  AvgDialog_118960_Content_35 = {
    Text = "<Red:Mimpi... harus... berlanjut...>"
  },
  AvgDialog_118960_Content_4 = {
    Text = "<Red:Tidak bisa berakhir>"
  },
  AvgDialog_118960_Content_5 = {
    Text = "Langit mulai menutup, kain hitam menutupi cahaya, menyatu menjadi langit yang ilusif."
  },
  AvgDialog_118960_Content_6 = {
    Text = "Gorak-girik, kamu mendengar suara roda pemintalan berputar kembali."
  },
  AvgDialog_118960_Content_7 = {
    Text = "Kenapa? Kenapa? Aku jelas sudah memutuskan untuk mengakhiri mimpi ini……"
  },
  AvgDialog_118960_Content_8 = {
    Text = "Karena…… yang terhormat Ibu Dewa, pemilik mimpi ini sebenarnya bukan kamu."
  },
  AvgDialog_118960_Content_9 = {Text = "??!!"},
  AvgDialog_118961_Content_1 = {Text = "Fauxborn"},
  AvgDialog_118961_Content_10 = {
    Text = "Terkejut? Satu-satunya jalur untuk melarikan diri dari kapal ini berada di bawah kendaliku."
  },
  AvgDialog_118961_Content_11 = {
    Text = [[
Goliath memegang murphy, pisau besar di tenggorokannya.
Darah mengalir dari lehernya, mengalir ke dada yang memiliki luka yang tak pernah sembuh.]]
  },
  AvgDialog_118961_Content_12 = {Text = "Murphy!"},
  AvgDialog_118961_Content_13 = {Text = "Ibu Dewi!"},
  AvgDialog_118961_Content_14 = {
    Text = "Maaf, aku masih merasa khawatir..."
  },
  AvgDialog_118961_Content_15 = {
    Text = "Bukan Miryam yang tak mau melepaskan gadis kecil ini, tetapi gadis kecil ini mengikat Miryam."
  },
  AvgDialog_118961_Content_16 = {
    Text = "Dia tidak mau, tidak berani, dan tidak dapat membiarkan Miryam mengetahui kebenarannya."
  },
  AvgDialog_118961_Content_17 = {
    Text = "Apa kebenaran yang kau katakan?"
  },
  AvgDialog_118961_Content_18 = {
    Text = "Dia juga tidak tahu di mana Lemuria itu, dia sama sekali belum pernah melihat wujud Dewa."
  },
  AvgDialog_118961_Content_19 = {
    Text = "Karena dia tidak tahu, kapal ini hanya bisa mengapung di laut, terus mengapung."
  },
  AvgDialog_118961_Content_2 = {
    Text = "Jadi, mengapa saat dewa telah lahir, Anda masih erat memegang Murphy?"
  },
  AvgDialog_118961_Content_20 = {
    Text = "Saya tidak tahu apa yang dikatakan gadis kecil itu untuk membujuk kalian berdua..."
  },
  AvgDialog_118961_Content_21 = {
    Text = "Seorang Pelaut utama, seorang yang misterius turun dari langit, dibuat pusing oleh seorang gadis kecil."
  },
  AvgDialog_118961_Content_22 = {
    Text = "Apakah kamu sudah lupa saat dia melarikan diri?"
  },
  AvgDialog_118961_Content_23 = {Text = "Berlari."},
  AvgDialog_118961_Content_24 = {
    Text = "Gadis itu sedang berlari."
  },
  AvgDialog_118961_Content_25 = {
    Text = "Dia tidak tahu di mana ujung perjalanan, dan tidak tahu apakah dia bisa melarikan diri dari pengawasan sang ibu baptis."
  },
  AvgDialog_118961_Content_26 = {
    Text = "<Shake: Ha, ha...>"
  },
  AvgDialog_118961_Content_27 = {
    Text = "Tidak ada yang menyambutnya di depan, suara geli yang aneh dari sirip yang memukul tanah semakin mendekat."
  },
  AvgDialog_118961_Content_28 = {
    Text = "Kabar hilangnya Perawan Suci telah menyebar, Pelaut sedang mengumpulkan pasukan."
  },
  AvgDialog_118961_Content_29 = {
    Text = "Sial, makhluk-makhluk mengganggu ini."
  },
  AvgDialog_118961_Content_3 = {
    Text = "Suara pertanyaanmu bergema."
  },
  AvgDialog_118961_Content_30 = {
    Text = "Di belakang kilauan itu, sosok berjubah ungu yang melambangkan kegagalannya muncul dengan tenang......"
  },
  AvgDialog_118961_Content_32 = {
    Text = "Murphy di dunia ini tidak bisa melarikan diri."
  },
  AvgDialog_118961_Content_33 = {
    Text = "Karena orang yang mengirimnya kepada Pelaut, kemudian secara mendalam menyesali telah mengirimnya keluar……"
  },
  AvgDialog_118961_Content_34 = {
    Text = "Sudah menghilang selamanya dalam bencana pelarutan akibat ledakan besar itu."
  },
  AvgDialog_118961_Content_35 = {
    Text = "Gadis kecil ini bukan untuk menjadi ibu dewa secara sukarela, sama seperti saya tidak sukarela menjadi budakmu."
  },
  AvgDialog_118961_Content_36 = {
    Text = "Kami semua demi... sesuatu yang kami inginkan."
  },
  AvgDialog_118961_Content_37 = {
    Text = "<Shake: Tidak, saya tidak memiliki apa yang saya inginkan.>Saya... tidak ingin apa-apa."
  },
  AvgDialog_118961_Content_38 = {
    Text = "Kamu tidak ingin apa-apa? Tidak, kamu ingin banyak hal."
  },
  AvgDialog_118961_Content_39 = {
    Text = "Kau ingin menikmati kehidupan yang mewah dari Dewi tetapi tidak ingin memikul tanggung jawab sebagai pemimpin."
  },
  AvgDialog_118961_Content_4 = {
    Text = "Di tanganmu, maksudmu...?"
  },
  AvgDialog_118961_Content_40 = {
    Text = "Kau takut ditinggalkan, jadi kau menjadikan orang lain sebagai boneka dalam hidupmu, seperti mainan bermain rumah teh."
  },
  AvgDialog_118961_Content_41 = {
    Text = "Setiap periode tertentu， kamu akan menghapus semua <Memori> orang di kapal， dan kemudian memulai siklus baru."
  },
  AvgDialog_118961_Content_42 = {
    Text = "Anak kecil, biarkan saya memberi tahu Anda: jangan sok pintar, segala sesuatu yang didapat di dunia ini memiliki harga."
  },
  AvgDialog_118961_Content_43 = {
    Text = "Apakah kau pikir tidak akan ada yang menemukan trik kecilmu? Mengira dengan patung gading itu, kau bisa melakukan segalanya?"
  },
  AvgDialog_118961_Content_44 = {
    Text = "Murphy menggenggam Patung gading di tangannya erat-erat."
  },
  AvgDialog_118961_Content_45 = {
    Text = "Jangan bodoh, anak bodoh."
  },
  AvgDialog_118961_Content_46 = {
    Text = "Apakah kamu merasa aku tidak tahu tentang tindakanmu? Aku hanya belum siap untuk melawanmu secara langsung."
  },
  AvgDialog_118961_Content_47 = {
    Text = "Setiap siklus, saya mencoba mengubah cara merampok kapal. Mengancammu, mengancam Myriam, meledakkan Ruang Kekuatan..."
  },
  AvgDialog_118961_Content_48 = {
    Text = "Kemudian aku menemukan, selama patung gading sialan itu masih ada, aku tidak memiliki ruang untuk melawanmu."
  },
  AvgDialog_118961_Content_49 = {
    Text = "Tawa Goliath bergema di dek kapal."
  },
  AvgDialog_118961_Content_5 = {
    Text = "Apakah kamu yang menciptakan mimpi ini dan menahan Murphy dalam mimpi yang berulang?"
  },
  AvgDialog_118961_Content_50 = {
    Text = "Hingga beberapa bulan yang lalu, ketika upaya di Kota Pemakaman yang dihancurkan oleh benda kecil ini di depan."
  },
  AvgDialog_118961_Content_51 = {
    Text = "Tidak mampu mengumpulkan cukup <Perak>， kekuatan dewa patung gading hilang， <awakener> di kapal sudah kehilangan <Memori> sejak lama."
  },
  AvgDialog_118961_Content_52 = {
    Text = "Kamu ingat semua hal... mereka ingat semua hal?..."
  },
  AvgDialog_118961_Content_53 = {
    Text = "Jadi, William tidak ingat semua hal karena dia berasal dari dunia lain."
  },
  AvgDialog_118961_Content_54 = {
    Text = "Orang-orang yang juga memiliki jiwa, tidak berbeda denganku… Mereka tahu bahwa langit dan bumi terbalik, waktu mengalir kembali."
  },
  AvgDialog_118961_Content_55 = {
    Text = "<Small:<Shake:Semua orang yang kamu sebutkan…… termasuk…… dia?>>"
  },
  AvgDialog_118961_Content_56 = {
    Text = "Murphy menunduk, suaranya nyaris tak terdengar, tatapannya melayang-layang, sering kali mengarah ke wanita di sampingnya, tapi segera menarik kembali sebelum menyentuh pandangannya."
  },
  AvgDialog_118961_Content_57 = {
    Text = "Gadis kecil yang sangat bodoh ini, aku berbicara tentang semua awak awak."
  },
  AvgDialog_118961_Content_58 = {
    Text = "Tentu saja, ini juga mencakup wanita bodoh bernama Miryam."
  },
  AvgDialog_118961_Content_59 = {
    Text = "Maksudmu adalah..."
  },
  AvgDialog_118961_Content_6 = {
    Text = "Miryam berpikir sejenak sebelum berbicara, suara tawa berat bergema dari belakangmu."
  },
  AvgDialog_118961_Content_60 = {
    Text = "Miryam ingat semua yang terjadi setiap kali siklus berlangsung, dia menunggu kamu berulang kali."
  },
  AvgDialog_118961_Content_61 = {
    Text = "Aku bisa terhubung dengan mimpi orang itu di sana, aku telah menyaksikan akhir dunia itu. Kurasa, Miryam juga bisa."
  },
  AvgDialog_118961_Content_62 = {
    Text = "Namun, dalam semua reinkarnasi yang saya ketahui, dia tidak melakukan usaha apa pun, hanya menunggu dengan pasif."
  },
  AvgDialog_118961_Content_63 = {
    Text = "Goliath mengangkat dagunya dan menunjuk Miryam yang diam di sampingnya."
  },
  AvgDialog_118961_Content_64 = {
    Text = "Kamu mengira bahwa kota yang kamu bangun dengan tanganmu sendiri, dia rela terjebak di dalamnya."
  },
  AvgDialog_118961_Content_65 = {
    Text = "Miryam menjawab tebakkan goliath dengan diam."
  },
  AvgDialog_118961_Content_66 = {
    Text = "<Shake:Mengapa? Saya tidak mengerti mengapa?>"
  },
  AvgDialog_118961_Content_67 = {
    Text = "Bagi Anda, saya seharusnya tidak menjadi produk gagal, alat yang terpinggirkan?"
  },
  AvgDialog_118961_Content_68 = {
    Text = "Bukankah kamu seharusnya menyerah pada aku seperti kau menyerah kepada mereka?"
  },
  AvgDialog_118961_Content_7 = {
    Text = "Aku akan memberitahumu."
  },
  AvgDialog_118961_Content_8 = {
    Text = "<Shake:Karena gadis kecil bernama Murphy ini adalah penipu.>"
  },
  AvgDialog_118961_Content_9 = {
    Text = "Kerumunan yang dipimpin oleh Perishite membelah diri, sebuah celah terbentuk dan seorang pelaut mendorong murphy yang compang-camping keluar dari celah tersebut."
  },
  AvgDialog_118962_Content_1 = {
    Text = "Kau menutup pintu kokpit, mengunci pengait, mendengarkan suara langkah kaki yang mengejar berbelok ke arah lain, kemudian berbalik untuk mengamati sandera kecilmu."
  },
  AvgDialog_118962_Content_10 = {
    Text = "Jika mereka tidak menjalankan tugas mereka… di mana mereka akan berada?"
  },
  AvgDialog_118962_Content_11 = {
    Text = "Berdasarkan sifat goliath, seharusnya dia tidak pergi ke kasino bawah tanah untuk malas."
  },
  AvgDialog_118962_Content_12 = {
    Text = "Dia pasti sedang merencanakan sesuatu di balik layar…"
  },
  AvgDialog_118962_Content_13 = {
    Text = "William bertahan di dalam kamar tidur Murphy."
  },
  AvgDialog_118962_Content_14 = {
    Text = "Bahkan jika hanya aku yang tersisa, setidaknya aku bisa menahan mereka selama dua puluh menit... sudah cukup..."
  },
  AvgDialog_118962_Content_15 = {
    Text = "Suara langkah tiba-tiba menjadi jarang."
  },
  AvgDialog_118962_Content_16 = {
    Text = "Selamat datang, tuan besar yang terhormat!"
  },
  AvgDialog_118962_Content_17 = {
    Text = "Yang Mulia, kami sudah mengepung para penyerang di dalam kamar tidur Sang Ibu! Hanya perlu satu perintah dari Anda…"
  },
  AvgDialog_118962_Content_18 = {
    Text = "Tidak perlu, Sang Ibu sudah tidak ada di sini."
  },
  AvgDialog_118962_Content_19 = {
    Text = "(Terbongkar?!)"
  },
  AvgDialog_118962_Content_2 = {Text = "Hmph……"},
  AvgDialog_118962_Content_20 = {
    Text = "Orang-orang di dalam ruangan…… apakah kita bisa berbicara sedikit?"
  },
  AvgDialog_118962_Content_21 = {
    Text = "Kau ingin membahas apa?"
  },
  AvgDialog_118962_Content_22 = {
    Text = "Baik Anda maupun teman Anda, sejak naik kapal, semua Pelaut diperlakukan dengan hormat."
  },
  AvgDialog_118962_Content_23 = {
    Text = "Namun kalian membalas budi dengan berkhianat, menculik Sang Ibu, sehingga ritus pengarah yang krusial tidak dapat dilaksanakan tepat waktu."
  },
  AvgDialog_118962_Content_24 = {
    Text = "Seandainya melewatkan momen ketika bintang berbaris ini, cita-cita agung kita akan memerlukan menunggu enam puluh perputaran bintang lagi."
  },
  AvgDialog_118962_Content_25 = {
    Text = "Pastinya ada alasan di balik ini, dan saya ingin mendengar alasan kalian berdua."
  },
  AvgDialog_118962_Content_26 = {
    Text = "Karena siklus yang dilalui Penjaga? Karena gadis itu pernah menjadi bagian dari Mythag?"
  },
  AvgDialog_118962_Content_27 = {
    Text = "William belum menyusun jawaban, tiba-tiba terdengar suara mengerikan yang basah dan melingkar dari belakang."
  },
  AvgDialog_118962_Content_28 = {
    Text = "Dia tiba-tiba berbalik — pupil matanya menyusut seketika. Beberapa penghuni laut telah memenuhi seluruh jendela seperti arus kotor yang pecah."
  },
  AvgDialog_118962_Content_29 = {
    Text = "Anggota tubuh yang terdistorsi berdesakan masuk ke dalam ruangan, cairan tubuh yang amis dan kental mengalir deras, seketika mengubah karpet menjadi rawa licin."
  },
  AvgDialog_118962_Content_3 = {
    Text = "Dia tidak tahu dari mana dia mendapatkan sebuah cermin kecil, dan dia terlihat sangat teliti saat merapikan rambutnya yang acak-acakan."
  },
  AvgDialog_118962_Content_30 = {
    Text = "Dia seperti paku, terbenam kuat di titik kematian di mana dua gelombang terburuk akan bertemu."
  },
  AvgDialog_118962_Content_31 = {
    Text = "Bagaimana dia melakukannya..."
  },
  AvgDialog_118962_Content_32 = {
    Text = "Jendela jauh dari dek setinggi lebih dari sepuluh meter; Penjaga berhasil melarikan diri dan tepat waktu memutuskan tali panjang."
  },
  AvgDialog_118962_Content_33 = {
    Text = "Bagaimana mereka bisa memasuki melalui dinding halus, dengan diam-diam meluncur masuk dari jendela?"
  },
  AvgDialog_118962_Content_34 = {
    Text = "Ranah Dewa memberi kami kekuatan yang cukup untuk melawan bencana alam, rintangan yang tidak berarti ini tentu saja tidak bisa menghalangi Pelaut."
  },
  AvgDialog_118962_Content_35 = {
    Text = "Makhluk laut…… apakah itu cawan di kaki?"
  },
  AvgDialog_118962_Content_36 = {
    Text = "Selain pelaut yang bertugas di kapal pesiar, semua makhluk laut yang mengelilingi badan kapal adalah yang datang atas panggilan roh Tuan kami, siap untuk diperintah oleh kami."
  },
  AvgDialog_118962_Content_37 = {
    Text = "Meskipun bukan dengan cara seperti itu, kamu seharusnya tahu bahwa kamu tidak bisa melawan seluruh ajaran Pelaut dengan hanya mengandalkan sebuah ruangan kecil..."
  },
  AvgDialog_118962_Content_38 = {
    Text = "Penyelidik Mythag tidak seberani itu... Beritahu saya, apa lagi yang Anda ketahui?"
  },
  AvgDialog_118962_Content_39 = {
    Text = "<Big:<Shake:Gemuruh——>>"
  },
  AvgDialog_118962_Content_4 = {
    Text = "Struktur yang kau maksud... di mana?"
  },
  AvgDialog_118962_Content_40 = {
    Text = "Suara gemuruh yang membuat gigi bergetar seperti logam yang sobek menembus langit, disertai getaran hebat, badan kapal seolah-olah ditangkap oleh tangan raksasa yang tak terlihat dan diputar dengan keras!"
  },
  AvgDialog_118962_Content_41 = {
    Text = "Ada apa ini?!"
  },
  AvgDialog_118962_Content_42 = {
    Text = "Seseorang sedang memaksa mengubah arah!"
  },
  AvgDialog_118962_Content_43 = {
    Text = "Kapal raksasa seperti binatang buas yang marah dan kehilangan kendali, bergoyang dan mencakar di ombak laut malam, setiap guncangan hebat tampaknya bisa merobek badan kapal!"
  },
  AvgDialog_118962_Content_44 = {
    Text = "Ruang kekuatan...... adalah ruang kekuatan!"
  },
  AvgDialog_118962_Content_45 = {
    Text = "Goliath mengambil sandera dan merebut Ruang kekuatan!"
  },
  AvgDialog_118962_Content_46 = {
    Text = "Datang lagi..."
  },
  AvgDialog_118962_Content_47 = {
    Text = "Getaran yang hebat terus-menerus."
  },
  AvgDialog_118962_Content_48 = {Text = "Murphy…"},
  AvgDialog_118962_Content_49 = {
    Text = "Saya tahu, kamu pasti tidak bisa melupakan seniormu itu, kan?"
  },
  AvgDialog_118962_Content_5 = {
    Text = "Di bawah kursi nakhoda, lihat."
  },
  AvgDialog_118962_Content_50 = {
    Text = "Saya mengerti, satu per satu mereka mengatakan bahwa saya adalah orang paling penting, tetapi pada saat pemilihan, mereka semua akan dengan mudah mengabaikan saya."
  },
  AvgDialog_118962_Content_51 = {Text = "Aku..."},
  AvgDialog_118962_Content_52 = {
    Text = "Baiklah, baiklah, hanya beberapa keluhan yang tidak berguna dan tidak langsung menyindir. Kita tidak akrab, kan?"
  },
  AvgDialog_118962_Content_53 = {
    Text = "Lagipula, jika Ruang Kekuatan meledak, kabin bawah mungkin juga akan terpengaruh."
  },
  AvgDialog_118962_Content_54 = {
    Text = "Ayo, kita tidak punya pilihan lain."
  },
  AvgDialog_118962_Content_6 = {
    Text = "Dia menginjak-injak pelat besi di bawah kakinya."
  },
  AvgDialog_118962_Content_7 = {
    Text = "Namun, ada yang agak aneh di sini……"
  },
  AvgDialog_118962_Content_8 = {
    Text = "Biasanya pada saat ini, Goliath dan Caecus seharusnya menjaga ruang kemudi."
  },
  AvgDialog_118962_Content_9 = {
    Text = "Makhluk bawah laut sebelum ritual akan menjadi gelisah, kita harus mencegah serangan ikan-ikan yang kegilaan mengganggu arah kapal…"
  },
  AvgDialog_118963_Content_1 = {
    Text = "Hari libur Ibu Dewa"
  },
  AvgDialog_118963_Content_10 = {
    Text = "Maksudmu……"
  },
  AvgDialog_118963_Content_11 = {
    Text = "Iya, kamu masih bisa menjadi ibu dewa-mu. Tapi, hari ini adalah hari libur bagi ibu dewa."
  },
  AvgDialog_118963_Content_12 = {
    Text = "Kau mengucapkan kebohongan tanpa mengubah ekspresi wajahmu."
  },
  AvgDialog_118963_Content_13 = {
    Text = "Liburan Ibu Dewi?"
  },
  AvgDialog_118963_Content_14 = {
    Text = "Ya, hari ini, saya diperintahkan untuk membawamu bermain di kapal seharian."
  },
  AvgDialog_118963_Content_15 = {
    Text = "Setelah naik kapal, kamu belum pernah merasakan kehidupan kru yang nyata, kan?"
  },
  AvgDialog_118963_Content_16 = {
    Text = "Dengan tanpa bisa ditolak, kau 'meminta' Murphy keluar dari kamar."
  },
  AvgDialog_118963_Content_17 = {
    Text = "Apakah kita benar-benar harus mendaki tempat seperti ini?"
  },
  AvgDialog_118963_Content_18 = {
    Text = "Ayo naik, hanya di sana pemandangan jelas, dan bisa mengamati situasi pelaut yang berpatroli."
  },
  AvgDialog_118963_Content_19 = {
    Text = "Jangan terlalu lambat, nanti akan ketahuan orang!"
  },
  AvgDialog_118963_Content_2 = {
    Text = "Kamu membuka mata. Matahari yang terang menyakiti matamu."
  },
  AvgDialog_118963_Content_20 = {
    Text = "Apa sih, bikin jadi berantakan!"
  },
  AvgDialog_118963_Content_21 = {
    Text = "Meski begitu, dia patuh menggenggam tanganmu, dan dengan mudah kamu menariknya ke atas platform."
  },
  AvgDialog_118963_Content_22 = {Text = "Puff—"},
  AvgDialog_118963_Content_23 = {
    Text = "Murphy tiba-tiba tertawa."
  },
  AvgDialog_118963_Content_24 = {
    Text = "Kenapa kamu tertawa?"
  },
  AvgDialog_118963_Content_25 = {
    Text = "Cara kau merangkak di rig terlihat seperti monyet!"
  },
  AvgDialog_118963_Content_26 = {
    Text = "Kau ini, seandainya tidak harus menjaga volume suara sekarang, aku pasti sudah memukul kepalamu..."
  },
  AvgDialog_118963_Content_27 = {
    Text = "Jangan tertawa! Kau tidak bisa melarikan diri!"
  },
  AvgDialog_118963_Content_28 = {
    Text = "Kamu meraih tangan Murphy dan menariknya dekat denganmu."
  },
  AvgDialog_118963_Content_29 = {
    Text = "Hei, bagaimana kamu berani!"
  },
  AvgDialog_118963_Content_3 = {
    Text = "Namun kamu tidak mengalihkan tatapanmu."
  },
  AvgDialog_118963_Content_30 = {Text = "Ssst!"},
  AvgDialog_118963_Content_31 = {
    Text = "Kalian menahan napas, satu kelompok pelaut mengenakan jubah jerami yang kumuh dan kotor, terhuyung-huyung melewati dek."
  },
  AvgDialog_118963_Content_32 = {
    Text = "Cepat, segera cari keberadaan Ibu Dewa! Dia pasti ada di kapal ini!"
  },
  AvgDialog_118963_Content_33 = {
    Text = "Kami ada tepat di atas kepala mereka, dan mereka tidak melihat sama sekali?"
  },
  AvgDialog_118963_Content_34 = {
    Text = "Sejak zaman dahulu, patroli tidak melihat ke atas."
  },
  AvgDialog_118963_Content_35 = {
    Text = "Jangan khawatir, selama kita bersembunyi di sini, tidak ada yang bisa menemukan kita."
  },
  AvgDialog_118963_Content_36 = {
    Text = "Kek, lihat di atas, ada orang!"
  },
  AvgDialog_118963_Content_37 = {
    Text = "Kau ini terlalu dekat dengan takhayul, bukan?"
  },
  AvgDialog_118963_Content_38 = {
    Text = "Diam-diam, hapus regu ini, setelah itu kita langsung menyelinap ke ruang awak!"
  },
  AvgDialog_118963_Content_4 = {
    Text = "Suaranya seperti desiran， suara merayap laba-laba seperti dorongan lembut dari ibu."
  },
  AvgDialog_118963_Content_5 = {
    Text = "Tak perlu mengingatkan aku. Aku tahu, ini adalah siklus terakhir."
  },
  AvgDialog_118963_Content_6 = {
    Text = "Kau menghapus air mata yang mengalir dari sudut matamu, membalikkan tubuh menuju arah suara panggilan yang akan segera datang, tanpa menoleh untuk memastikan asal suara nyanyian itu."
  },
  AvgDialog_118963_Content_7 = {
    Text = "Karena kau tahu, wanita yang memeluk alat tenun pasti menatapmu dengan penuh belas kasihan."
  },
  AvgDialog_118963_Content_8 = {
    Text = "Kau masih datang ke sini untuk apa? Perjalanan kapal ini telah pulih, dan tidak ada tempat untukmu di sini lagi."
  },
  AvgDialog_118963_Content_9 = {
    Text = "Tidak masalah, kamu adalah ibu dewa para pelaut, juga kapten dari kapal Paradis, penguasa surga. Ini tidak ada hubungannya dengan cuti yang akan saya berikan padamu."
  },
  AvgDialog_119922_Content_1 = {
    Text = "Selamat datang kembali, rekan."
  },
  AvgDialog_119922_Content_10 = {
    Text = "Tidak apa-apa， Tuan， tidak peduli seberapa lama Anda ingin pergi， <ogier> akan menemani Anda. Saya hanya berharap…"
  },
  AvgDialog_119922_Content_11 = {
    Text = "Ksatria muda itu menatapmu dengan serius, matanya penuh dengan ketulusan, serta permohonan yang tersimpan di balik ketulusan tersebut."
  },
  AvgDialog_119922_Content_12 = {
    Text = "Saya hanya berharap... jika tuan masih berniat \"berlibur\" dan pergi dalam waktu yang lama, tolong bawa saya bersama. Ogier akan bersumpah untuk melindungi Anda."
  },
  AvgDialog_119922_Content_13 = {
    Text = "Atau mungkin saya juga bisa."
  },
  AvgDialog_119922_Content_14 = {
    Text = "Lotan juga memandangmu, dengan mata yang biasanya mencolok kini dipenuhi dengan kesungguhan. Saat ini, dia tidak memikirkan tentang menang atau kalah, atau pertarungan, hanya perhatian terhadapmu."
  },
  AvgDialog_119922_Content_15 = {
    Text = "……Aku sudah tahu ini akan terjadi. Kalian berdua, jangan lupakan tujuan pertemuan teh kali ini. Kita merayakan \"kembalinya\" %player%."
  },
  AvgDialog_119922_Content_16 = {
    Text = "Semoga setelah kamu \"kembali\" kali ini, jangan pernah pergi lagi."
  },
  AvgDialog_119922_Content_17 = {
    Text = "Hanya sekadar bersantai, jangan dibesar-besarkan... Lagipula, bukankah aku sudah kembali?"
  },
  AvgDialog_119922_Content_18 = {
    Text = "Mendengar kata-katamu, doll menatapmu. Dia sepertinya ingin mengatakan sesuatu, tetapi akhirnya hanya menghela napas ringan."
  },
  AvgDialog_119922_Content_19 = {
    Text = "Iya, kamu sudah kembali, hari-hari ketika mereka mencari sosokmu di kampus hanya untuk kecewa, dan hari-hari ketika mereka berdiri tanpa suara di depan pintumu, tapi tidak berani mengetuk pintu, juga telah berlalu."
  },
  AvgDialog_119922_Content_2 = {
    Text = "Entah kapan, alun-alun Mythag telah didekorasi menjadi acara teh kecil, Ramona berdiri di samping meja kecil yang penuh dengan muffin, selai, dan teh, tersenyum dan mengulurkan tangannya kepadamu."
  },
  AvgDialog_119922_Content_20 = {
    Text = "%player%， saya telah mengatakannya berkali-kali, dan akan terus mengatakannya di masa depan, keberadaanmu sangat penting."
  },
  AvgDialog_119922_Content_21 = {
    Text = "Baik untuk dunia ini, maupun untuk kita. Jadi…"
  },
  AvgDialog_119922_Content_22 = {
    Text = "Kau menunggu pernyataan doll, tetapi doll hanya menutup matanya, dan tidak berbicara lagi."
  },
  AvgDialog_119922_Content_23 = {
    Text = "Saat itu, sepasang tangan lembut namun tegas menutupi punggung tanganmu, itu Ramona."
  },
  AvgDialog_119922_Content_24 = {
    Text = "Rekan, saya tahu sebagai penjaga, kamu menanggung banyak tekanan, kami semua mengerti dan memahami. Jadi, kami tidak akan memaksakan terlalu banyak."
  },
  AvgDialog_119922_Content_25 = {
    Text = "Saya hanya ingin Anda tahu, tidak peduli berapa kali Anda pergi, tidak peduli berapa lama Anda pergi, saat Anda kembali, kami semua ada di sini."
  },
  AvgDialog_119922_Content_26 = {
    Text = "Saat sampai di sini, suara gadis itu berhenti sejenak, kemudian perlahan memberimu senyum."
  },
  AvgDialog_119922_Content_27 = {
    Text = "Selamat datang kembali, rekan. Sekarang, nikmati acara teh yang sudah dipersiapkan untukmu."
  },
  AvgDialog_119922_Content_28 = {
    Text = "Benar. Hari ini tidak ada ujian， tidak ada tugas tambahan. Satu-satunya tugasmu adalah membuat dirimu bahagia."
  },
  AvgDialog_119922_Content_29 = {
    Text = "Jika kamu tidak peduli tentang gigi berlubang dan masalah kelebihan gula, kamu bisa menghabiskan semua makanan manis ini. Lagipula, mereka juga disiapkan untukmu."
  },
  AvgDialog_119922_Content_3 = {
    Text = "Aku tidak tahu apakah aku memiliki kehormatan ini, untuk mengundangmu ke acara teh penyambutan yang telah kami siapkan untukmu?"
  },
  AvgDialog_119922_Content_30 = {
    Text = "Sebenarnya tidak perlu begitu…"
  },
  AvgDialog_119922_Content_31 = {
    Text = "Meskipun begitu, kamu tetap mencicipi gulungan mentega yang dipenuhi gula. Rasanya sama seperti yang kamu bayangkan, manis berlebihan, tetapi tidak menjijikkan."
  },
  AvgDialog_119922_Content_32 = {
    Text = "Karena di bawah tatapan penuh perhatian orang-orang, hatimu telah memperoleh kepuasan. Mungkin, hidup adalah merasakan manis yang menggugah di celah-celah pahit dari kenyataan."
  },
  AvgDialog_119922_Content_4 = {
    Text = "Kau mengangguk, lalu, gadis itu perlahan menggandengmu, membawamu menuju meja segitiga yang penuh dengan hidangan, dan ada awak yang telah menunggu lama di samping meja."
  },
  AvgDialog_119922_Content_5 = {
    Text = "Menurutku, bertarung tidak lebih menggembirakan daripada pertemuan santai, kan? Tapi memang... kali ini sedikit berbeda."
  },
  AvgDialog_119922_Content_6 = {
    Text = "Kali ini, tidak ada hubungannya dengan menang atau kalah, tidak ada hubungannya dengan pertempuran. Hanya ada hubungannya dengan kamu."
  },
  AvgDialog_119922_Content_7 = {
    Text = "%player%， kamu adalah bintang utama dalam pertemuan teh kali ini."
  },
  AvgDialog_119922_Content_8 = {
    Text = [[
Lotan berkata sambil mendorong piring berisi gulungan mentega berlapis gula ke arahmu.
 Hanya dengan melihat sekilas, kamu langsung tahu bahwa kalori dari makanan ini sangat mengerikan.]]
  },
  AvgDialog_119922_Content_9 = {
    Text = "Mengapa saya merasa… begitu, hanya dengan satu suapan, saya perlu berlari satu semester untuk mencernanya…"
  },
  AvgDialog_119923_Content_1 = {
    Text = "Di dalam lumpur spiritual yang gelap, terdengar rasa sakit yang menusuk langsung ke jiwa, serta kata-kata dingin."
  },
  AvgDialog_119923_Content_10 = {
    Text = "Mengingat perasaan saat dilakukan pembedahan otak, otakmu bergetar, untuk menghindari perasaan ini, kamu secara aktif mengalihkan topik pembicaraan."
  },
  AvgDialog_119923_Content_11 = {
    Text = "Bagaimana keadaan dunia ini... sekarang?"
  },
  AvgDialog_119923_Content_12 = {
    Text = "Tetap seperti biasa. Setiap saat mendekati kehancuran dan kehancuran. Tapi setidaknya ada kabar baik, untukmu."
  },
  AvgDialog_119923_Content_13 = {
    Text = "Sambil berkata, Doll: inferno membuka alat komunikasi, dengan cepat, sosok yang familiar muncul di depanmu. Itu adalah pesan yang sudah direkam sebelumnya."
  },
  AvgDialog_119923_Content_14 = {
    Text = "Doll: inferno, jika %player% berhasil kembali atau ada kabar apapun, ingatlah untuk memberi tahu aku. Selain itu, saya pikir usulan psikologis yang kamu tanam sebelumnya sangat rasional."
  },
  AvgDialog_119923_Content_15 = {
    Text = "Sebagai seorang psikiater profesional, dalam hal ini %player% akan tinggal, aku tidak bisa terlalu memanjakan kehendak pasien…"
  },
  AvgDialog_119923_Content_16 = {
    Text = "Komunikasi terhenti di sini, ditutup oleh doll: inferno. Dia dengan lembut menepuk meja, menandakan agar Anda memperhatikan dia."
  },
  AvgDialog_119923_Content_17 = {
    Text = "Basa-basi yang tidak berguna bisa berhenti sampai di sini. Aku menaruh ini, Hanya Saja untuk menunjukkan kepadamu, apa yang sebenarnya kamu lewatkan selama kamu \"pergi\"."
  },
  AvgDialog_119923_Content_18 = {
    Text = "Yang terpenting, eksperimen saya belum berakhir…"
  },
  AvgDialog_119923_Content_19 = {
    Text = "Doll: inferno mendekat kepadamu dengan pisau bedah. Ekspresinya tenang, tetapi mengandung kebangkitan kegilaan."
  },
  AvgDialog_119923_Content_2 = {
    Text = "Sampai kapan kau akan berpura-pura tidur? Anak anjingku yang lucu."
  },
  AvgDialog_119923_Content_20 = {
    Text = "Kau, kau ingin melakukan apa?"
  },
  AvgDialog_119923_Content_21 = {
    Text = "Berencana untuk mengunci roh mu secara permanen dalam otak ini, dalam tubuh ini. Dengan cara itu, kamu tidak akan bisa \"pergi\" lagi."
  },
  AvgDialog_119923_Content_22 = {
    Text = "Kau mundur satu langkah karena terkejut, tetapi segera tenang kembali, karena kau teringat tugas yang belum selesai—"
  },
  AvgDialog_119923_Content_23 = {
    Text = "Doll: inferno, tidak perlu seperti ini. Selama dunia ini belum kembali normal, aku tidak akan benar-benar pergi."
  },
  AvgDialog_119923_Content_24 = {
    Text = "Sosok yang memegang pisau bedah berhenti dan hanya menatapmu, tampaknya sedang menilai kebenaran kata-katamu."
  },
  AvgDialog_119923_Content_25 = {
    Text = "Saya serius. Sebagai Penjaga, saya tidak akan pernah menyerah pada upaya menyelamatkan dunia ini, jadi tidak peduli berapa lama saya \"pergi\", saya pasti akan kembali."
  },
  AvgDialog_119923_Content_26 = {
    Text = [[
Doll: inferno meletakkan pisau bedah. Manfaatkan kesempatan ini, kamu meraba dadamu.
Saat jari-jarimu menyentuh kunci perak yang familiar, hatimu akhirnya tenang.]]
  },
  AvgDialog_119923_Content_27 = {
    Text = "Sekarang, saya kembali. Penyelidikan yang terputus sebelumnya, bisa dilanjutkan."
  },
  AvgDialog_119923_Content_28 = {
    Text = "Sambil berkata demikian, kau berjalan ke pintu. Doll: inferno menatapmu sejenak, kemudian mengikuti."
  },
  AvgDialog_119923_Content_29 = {
    Text = "Sepertinya kamu sangat mengerti betapa pentingnya keberadaanmu bagi dunia ini."
  },
  AvgDialog_119923_Content_3 = {
    Text = "Doll: inferno?"
  },
  AvgDialog_119923_Content_30 = {
    Text = "Tentu saja, karena seperti yang Tawi katakan, saya adalah variabel dunia ini, masa depan dunia ini."
  },
  AvgDialog_119923_Content_31 = {
    Text = "Seiring dengan kata-katamu, pintu laboratorium perlahan terbuka. Udara dan sinar matahari dari luar perlahan-lahan jatuh ke tubuhmu, seperti sambutan yang tidak bersuara, atau balasan."
  },
  AvgDialog_119923_Content_32 = {
    Text = "Dunia ini menunggu kamu, menunggu perubahan yang akan kamu bawa, dan masa depan yang akan kamu ciptakan."
  },
  AvgDialog_119923_Content_4 = {
    Text = "Kamu mengenali pemilik suara itu, perlahan membuka mata. Segera, kegelapan memudar, cahaya muncul —"
  },
  AvgDialog_119923_Content_5 = {
    Text = "\"Bagaimana rasanya meninggalkan\" dunia ini?"
  },
  AvgDialog_119923_Content_6 = {
    Text = "Mungkin, lain kali saya harus mengikat \"roh\"mu juga, sehingga tidak perlu lagi mencarinya."
  },
  AvgDialog_119923_Content_7 = {
    Text = "Doll: inferno menyipitkan matanya, menunjukkan ekspresi yang seolah senyum namun tidak, perlahan memainkan pisau bedah yang bersinar dingin di tangannya."
  },
  AvgDialog_119923_Content_8 = {
    Text = "……Bagaimana aku bisa berada di sini?"
  },
  AvgDialog_119923_Content_9 = {
    Text = "Tentu saja karena setelah \"Roh\" Anda pergi, tubuh kehilangan fungsinya; jadi saya harus sekali lagi melakukan operasi untuk menangkap kembali \"Roh\" Anda."
  },
  AvgDialog_120290_Content_1 = {
    Text = "Tulang Cantik, Gua Emas"
  },
  AvgDialog_120290_Content_10 = {
    Text = "Pintu terbuka lebar, kamu jatuh ke dalam pelukan. Dia memelukmu ke tempat tidur, lalu merapikan selimut, membungkuk dan menyentuh dahinya ke dahi kamu, menarikmu untuk bersandar di sisinya."
  },
  AvgDialog_120290_Content_11 = {
    Text = "Ibu...? Ibu!"
  },
  AvgDialog_120290_Content_12 = {
    Text = "Ayah sudah lama tidak memperhatikan saya, di rumah tidak ada yang membantu saya, dan tidak ada air... Kepala saya sangat sakit, seluruh tubuh saya juga sakit."
  },
  AvgDialog_120290_Content_13 = {
    Text = "……Anak perempuan yang baik Ibu, jangan menangis."
  },
  AvgDialog_120290_Content_14 = {
    Text = "Tenang saja, semuanya akan segera baik-baik saja, Ibu menjanjikanmu."
  },
  AvgDialog_120290_Content_15 = {
    Text = "Kamu terjebak dalam selimut yang hangat, dengan bingung menciumnya saat aroma itu perlahan menjadi semakin kuat, tidak lagi seperti aroma melati yang biasa ada di tubuh ibumu, melainkan seperti……"
  },
  AvgDialog_120290_Content_16 = {
    Text = "Seperti apa ya… seperti lorong-lorong yang bertumpuk di dalam Hai Cheng, bunga magnolia putih yang besar jatuh, di sudut-sudutnya, karena suhu tinggi, mengeluarkan aroma manis yang aneh dan dalam, lengket."
  },
  AvgDialog_120290_Content_17 = {
    Text = "Ibu, apakah aroma yang ada di tubuhmu sudah berubah? Sangat harum, juga... sangat aneh."
  },
  AvgDialog_120290_Content_18 = {
    Text = "Suara lembut itu tidak menjawab pertanyaanmu, seiring dengan usapan lembutnya, aroma semakin kuat, hampir menjadi nyata."
  },
  AvgDialog_120290_Content_19 = {
    Text = "Kamu ingin melihat wajahnya dengan jelas, tetapi hanya ada kabut tak berujung yang menyelimuti di depan mata, akhirnya membungkusmu."
  },
  AvgDialog_120290_Content_2 = {
    Text = "Kabut tipis yang membawa aroma melati, melingkari seluruh tubuhmu, menjalinmu dengan cara yang tak terlihat dan lembap."
  },
  AvgDialog_120290_Content_20 = {
    Text = "Tidurlah, sayangku, tidurlah, Ibu akan segera kembali di sisimu."
  },
  AvgDialog_120290_Content_21 = {
    Text = "…Saya sudah berjanji padanya."
  },
  AvgDialog_120290_Content_22 = {
    Text = "Dalam kegelapan, rasa haus masih mencakar dirimu seperti cakaran kucing, segera diikuti oleh semacam cairan hangat dan kental yang tampaknya masuk ke tenggorokanmu dari lubang hidung atau sudut mulut."
  },
  AvgDialog_120290_Content_23 = {
    Text = "Kelopak matamu semakin berat, dalam aroma dan bisikan, perlahan-lahan kehilangan kesadaran sepenuhnya."
  },
  AvgDialog_120290_Content_24 = {
    Text = "……sampai suara langkah kaki perlahan berkumpul di luar pintu, kamu terbangun dari rasa pusing yang menyakitkan oleh suara percakapan."
  },
  AvgDialog_120290_Content_25 = {
    Text = "Oh ya, Nona Dige, setiap hari begitu membuka mata langsung ingin minum teh, sangat menjengkelkan, apakah benar mengira dirinya masih seperti Nona yang manja saat masih hidup?"
  },
  AvgDialog_120290_Content_26 = {
    Text = "Jangan bicara begitu keras! … Tuan sendiri juga tidak mengurus putrinya, di rumah ada berapa banyak ibu tiri yang cantik? Lihatlah, hari ini dia masih pergi ke Jalan Sima lagi."
  },
  AvgDialog_120290_Content_27 = {
    Text = "Kalian lihat saja, tidak akan memakan banyak waktu, di dalam rumah setiap bibi pasti ada bayi yang akan lahir, sedikit banyak pasti ada tuan kecil dan nyonya kecil yang akan muncul…"
  },
  AvgDialog_120290_Content_28 = {
    Text = "……Tuan?"
  },
  AvgDialog_120290_Content_29 = {
    Text = "Kamu mengangkat kepala, wadah tembaga yang sedikit kotor di atas rangka kayu, samar-samar mencerminkan wajah halus dan muda seorang gadis dari Timur Jauh. Kamu bingung berkedip, gadis kecil dalam bayangan itu juga berkedip."
  },
  AvgDialog_120290_Content_3 = {
    Text = "Kebingungan setelah demam tinggi membuatmu tidak bisa menahan diri untuk mendekati kabut itu……"
  },
  AvgDialog_120290_Content_30 = {
    Text = "Kesadaranmu perlahan kembali, beberapa fragmen tentang identitas muncul di lautan kesadaranmu."
  },
  AvgDialog_120290_Content_31 = {
    Text = "Tuan, di mana, Ayah... Saya di rumah besar, saya adalah putri dari mana, nama saya..."
  },
  AvgDialog_120290_Content_32 = {
    Text = "Aduh, kamu tidak bisa berbaring di tanah, Tuan akan memarahi saya."
  },
  AvgDialog_120290_Content_33 = {
    Text = "Pintu tiba-tiba didorong terbuka, pikiranmu terputus, seseorang datang dengan tergesa-gesa dan dengan tidak sabar membantumu berdiri."
  },
  AvgDialog_120290_Content_34 = {
    Text = "Tadi jelas-jelas, aku di mana di tanah? Ibu di mana?"
  },
  AvgDialog_120290_Content_35 = {
    Text = "Ibu? Nona, Anda harus ingat, Nyonya sudah pergi lebih dari sebulan."
  },
  AvgDialog_120290_Content_36 = {
    Text = "Dia tiba-tiba mengeluarkan kata-kata, melihatmu tertegun berdiri di tempat, wajahnya menunjukkan ekspresi yang agak tidak tega."
  },
  AvgDialog_120290_Content_37 = {
    Text = "<Small:Hanya sebesar ini, mungkin bahkan tidak tahu apa arti pergi.>"
  },
  AvgDialog_120290_Content_38 = {
    Text = "<LightGray:Iya, Ibu sudah lebih dari sebulan yang lalu…>"
  },
  AvgDialog_120290_Content_39 = {
    Text = "Kamu bermimpi lagi, ya? Ah. Nah, ini airnya sudah kubawakan untukmu."
  },
  AvgDialog_120290_Content_4 = {
    Text = "Lalu jatuh lurus ke lantai."
  },
  AvgDialog_120290_Content_40 = {
    Text = "Air… kamu tiba-tiba menyadari bahwa kamu sudah tidak haus lagi, cairan yang mengalir masuk saat itu, disertai aroma yang menyertainya."
  },
  AvgDialog_120290_Content_41 = {
    Text = [[
Masih tersisa di antara gigi dan rongga hidungmu, aroma melati putih yang manis hingga mendekati busuk!
Kamu tiba-tiba menyadari, lalu berlari keluar dengan cepat.]]
  },
  AvgDialog_120290_Content_42 = {
    Text = "Hei, hei! Mau lari ke mana? Nona!"
  },
  AvgDialog_120290_Content_43 = {
    Text = "Perayaan di Timur Jauh telah tiba, lampu-lampu mulai menyala, lentera merah dan lampu neon modern saling bersinar, tetapi orang-orang yang seharusnya pulang lebih awal pada hari ini justru berbondong-bondong menuju arah yang sama."
  },
  AvgDialog_120290_Content_44 = {
    Text = "Udara dipenuhi dengan aroma bedak, bau minyak tanah, bau asap dari warung makanan dan restoran, serta semakin kuatnya..."
  },
  AvgDialog_120290_Content_45 = {
    Text = "Ibu, itu bau Ibu, bukan mimpi, aku tidak bermimpi!"
  },
  AvgDialog_120290_Content_46 = {
    Text = "Kamu telah menemukan asal dari aroma manis yang asing, kuat, akrab, hangat, dan lembut."
  },
  AvgDialog_120290_Content_47 = {
    Text = "Papan nama \"Xiaojinlou\" tergantung jauh di atas pintu megah."
  },
  AvgDialog_120290_Content_48 = {Text = "Tuan Xu!"},
  AvgDialog_120290_Content_49 = {
    Text = "Minggir, kamu menghalangi aku, Tuan Xu, lihat ke sana!"
  },
  AvgDialog_120290_Content_5 = {
    Text = "Ugh! Sakit... Ibu... Air..."
  },
  AvgDialog_120290_Content_50 = {Text = "Tsk."},
  AvgDialog_120290_Content_51 = {
    Text = "Sosok di atas panggung tinggi, dengan kurang semangat memainkan sebuah kipas hitam, wajahnya sebagian tersembunyi di balik permukaan kipas."
  },
  AvgDialog_120290_Content_52 = {
    Text = "Orang-orang berdesakan hampir akan menenggelamkanmu, semangat dan kegelisahan yang samar-samar mengalir di dasar mata mereka, tetapi sepertinya tidak memengaruhi dirinya."
  },
  AvgDialog_120290_Content_53 = {
    Text = "Kamu menemukan sumber aroma itu, atau lebih tepatnya, semacam keinginan dan ketakutan yang tidak dapat kamu pahami telah menguasaimu. Kamu berusaha keras untuk mengangkat kepala dan melihat ke atas."
  },
  AvgDialog_120290_Content_54 = {Text = "...Ya."},
  AvgDialog_120290_Content_55 = {
    Text = "Jika merasakan sesuatu, dia menundukkan matanya, dan kamu hanya melihat sepasang mata yang sangat, sangat cantik."
  },
  AvgDialog_120290_Content_56 = {
    Text = "Kipas hitam perlahan-lahan, dengan keanggunan yang membuat jantung berdebar, bergerak menjauh."
  },
  AvgDialog_120290_Content_57 = {
    Text = "kabut kabut kabut\nkabut kabut kabut kabut  Dia Dia? Dia…dia…ibu…ibu ibu ibu ibu ibu mata-Nya mata-nya\nkabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut\ndia dia dia dia dia dia Dia Dia Dia Dia Dia ibu ibu ibu ibu ibu ibu ibu ibu ibu ibu ibu ibu ibu Dia\nmata kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut mata yang indah kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut\nkabut kabut kabut kabut kabut kabut dia dia dia dia dia mata yang indah dia dia dia dia dia kabut kabut mata yang indah dia Dia Dia dia kabut kabut kabut\nkabut kabut kabut kabut kabut dia Dia Dia Dia Dia Dia kabut kabut kabut mata yang indah kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut\nibu ibu ibu ibu ibu ibu ibu mata yang indah ibu ibu ibu ibu ibu ibu ibu ibu mata mata mata\nmata mata mata mata kabut kabut kabut kabut kabut kabut kabut mata yang indah ibu mata dia Dia dia dia Dia Dia Dia Dia Dia Dia dia\nmata-nya mata mata mata ibu mata yang indah ibu mata ibu dia ibu Dia dia ibu ibu ibu ibu\nkabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut mata yang indah dia Dia Dia Dia Dia Dia Dia Dia Dia Dia Dia mata mata dia dia dia\ndia Dia Dia dia Dia Dia Dia dia dia dia dia Dia mata yang indah dia dia dia dia Dia Dia dia Dia Dia Dia dia dia dia dia Dia Dia dia dia\nibu ibu ibu ibu ibu ibu kabut kabut kabut kabut kabut mata yang indah kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut\n@4@4@4@1@1@3@3kabut kabut kabut kabut@1@3\ndia Dia dia Dia Dia dia mata yang indah dia dia Dia Dia dia Dia Dia Dia@3Dia Dia dia@1Dia Dia Dia dia dia dia\ndia@4@3@4@4@4mata@2@4\nibu kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut kabut mata yang indah kabut kabut kabut kabut kabut kabut kabut kabut mata yang indah ibu ibu\ndia dia dia mata yang indah dia dia dia@4Dia Dia Dia mata yang indah Dia Dia Dia Dia Dia Dia mata yang indah"
  },
  AvgDialog_120290_Content_58 = {
    Text = "Tangisan, teriakan, dan raungan tiba-tiba meledak di telingamu, lautan manusia yang bertumpuk-tumpuk datang menghampirimu!"
  },
  AvgDialog_120290_Content_59 = {
    Text = "Aku melihatnya, aku melihatnya, dia sedang melihatku!"
  },
  AvgDialog_120290_Content_6 = {
    Text = "Anggota tubuh terasa lemas dan tidak bertenaga, ingatan belum kembali, kamu benar-benar sangat haus, secara naluriah mengucapkan sebuah panggilan yang paling akrab."
  },
  AvgDialog_120290_Content_60 = {
    Text = "Dia sedang melihatku!"
  },
  AvgDialog_120290_Content_61 = {
    Text = "<Change>Terlalu... terlalu indah!! Wajah seperti apa ini, begitu cantik, begitu... luar biasa... begitu horor!!!"
  },
  AvgDialog_120290_Content_62 = {
    Text = "Tuan Xu! Tuan Xu... Tolong, tolong!!"
  },
  AvgDialog_120290_Content_63 = {
    Text = "Tolong lihat aku!"
  },
  AvgDialog_120290_Content_64 = {
    Text = "<Shake:<Red:Aaaaaahhh!!!!>>"
  },
  AvgDialog_120290_Content_65 = {
    Text = "Pria yang berpakaian rapi tiba-tiba berteriak dan menerjang pria berpakaian jas yang menghalangi antara dirinya dan Xu, sementara lawannya terus menatap ke arah posisi Xu, sampai bola matanya tiba-tiba dicungkil."
  },
  AvgDialog_120290_Content_66 = {
    Text = "Pria yang matanya dicungkil itu menjerit kesakitan sambil tertawa, kristal bulat menggantung lembut dari rongga matanya, dia mengusap wajahnya dengan sembrono, dengan sekuat tenaga mengulurkan tangan ke arah panggung tinggi dengan urat-urat di lehernya menonjol."
  },
  AvgDialog_120290_Content_67 = {
    Text = "Seperti suatu perintah yang terdengar, di tengah tawa dan teriakan mereka, orang-orang terbawa oleh gelombang tak terlihat, berdesakan dengan gila-gilaan, berusaha untuk menyentuh panggung tinggi."
  },
  AvgDialog_120290_Content_68 = {
    Text = "<Change>Xu!! Xu!!!"
  },
  AvgDialog_120290_Content_69 = {
    Text = "<Change>Xǔ——!!!!"
  },
  AvgDialog_120290_Content_7 = {
    Text = "Suara nyanyian lembut yang berbisik semakin dekat, sosok wanita melintas di depan pintu, akrab dan hangat, kamu merasa tubuh bagian bawahmu lemah dan ingin bangkit..."
  },
  AvgDialog_120290_Content_70 = {
    Text = "Suara tajam hampir menghancurkan gendang telingamu, kerumunan mendorong, tubuh ini yang masih muda mengeluarkan keluhan yang tak tertahankan, wajah di bawah kipas semakin jelas namun semakin kabur."
  },
  AvgDialog_120290_Content_71 = {
    Text = "Akhirnya hanya terkumpul menjadi kabut yang menelan semua cahaya, seperti jurang yang dalam."
  },
  AvgDialog_120290_Content_72 = {
    Text = "Dan tawa lembut yang sangat menyenangkan yang melintas melalui kabut."
  },
  AvgDialog_120290_Content_73 = {
    Text = "Kamu di sini ya, bunga melati kecilku."
  },
  AvgDialog_120290_Content_74 = {
    Text = "Sebelum ditenggelamkan oleh kegelapan dan sesak, kamu samar-samar melihat seseorang di kerumunan, namun juga terjebak dalam kegilaan, mengabaikan martabat, berdesak-desakan ke depan..."
  },
  AvgDialog_120290_Content_75 = {
    Text = "Sosok ayah yang tidak sekali pun menatapmu."
  },
  AvgDialog_120290_Content_8 = {
    Text = "<Shake:Ciiit——>"
  },
  AvgDialog_120290_Content_9 = {
    Text = "Aduh, kasihan, mengapa terjatuh di tempat seperti ini?"
  },
  AvgDialog_120291_Content_1 = {Text = "Tiba-tiba"},
  AvgDialog_120291_Content_10 = {
    Text = "Sepotong kue yang lembek dan menggumpal, jelas tidak dianggap sebagai kue yang mewah, dimasukkan ke dalam mulutmu, dan begitu tekstur kue itu sedikit meleleh, air liur mulai keluar dengan liar di dalam mulut."
  },
  AvgDialog_120291_Content_11 = {
    Text = "Kamu mengikuti langkahnya sambil mengunyah kue, perutmu baru saja merasa lega, detik berikutnya, tekanan yang lebih berat menekan di atas jantungmu."
  },
  AvgDialog_120291_Content_12 = {
    Text = "Jangan bengong, Nona, cepat masuk, Tuan Xu sudah menunggu lama."
  },
  AvgDialog_120291_Content_13 = {
    Text = "Ayah dikelilingi oleh banyak bibi yang wajahnya tidak dapat kamu ingat, para bibi di kediaman selalu datang dan pergi, ada yang berbadan gemuk dan ada yang ramping, penuh warna dan kehidupan."
  },
  AvgDialog_120291_Content_14 = {
    Text = "Namun kini pandangannya sangat bingung, hanya terkunci pada satu orang."
  },
  AvgDialog_120291_Content_15 = {
    Text = "Pemilik sepasang mata yang indah hingga membuat gila itu, jelas sedang berpura-pura bersikap sopan yang sedikit menjauh karena kebosanan, sampai tatapannya yang lembut jatuh padamu."
  },
  AvgDialog_120291_Content_16 = {
    Text = "Meskipun saya sudah lama tahu bahwa setelah upacara kamu akan turun, tetapi saya tidak pernah menyangka kamu akan begitu menawan."
  },
  AvgDialog_120291_Content_17 = {
    Text = "Aku seharusnya tidak mengirimmu ke gedung pelacuran, ya! Aku seharusnya membiarkanmu tetap di sisiku, semuanya sudah tidak ada artinya, selain dirimu, tidak ada yang berarti!"
  },
  AvgDialog_120291_Content_18 = {
    Text = "Tuan He, mohon jangan kehilangan kesopanan. Kita bisa berbincang nostalgia nanti, saya datang hari ini untuk meminta maaf."
  },
  AvgDialog_120291_Content_19 = {
    Text = "Seorang gadis bodoh tahu apa, hari ini aku akan menyiapkan hadiah lagi di Gedung Xiau Jin. Jika kamu suka, bawa dan ajari sendiri bagaimana cara merawatnya?"
  },
  AvgDialog_120291_Content_20 = {
    Text = "Tuan He memiliki sikap yang luar biasa, jika ada jodoh, tentu saja akan membuat hati hamba ini senang."
  },
  AvgDialog_120291_Content_21 = {
    Text = "Namun aku merasa akrab dengan anak ini sejak pertama bertemu, sebelumnya juga banyak terjadi bentrokan… Jika kamu dan aku ingin lebih dekat, dia juga harus merasa tenang."
  },
  AvgDialog_120291_Content_22 = {
    Text = "Wanita yang dipanggil Tuan Xu mendekatimu, membungkuk dengan lembut."
  },
  AvgDialog_120291_Content_23 = {
    Text = "Belum menyapa, saya bernama Xu. Jadi, bagaimana pendapatmu, Nona dari keluarga He?"
  },
  AvgDialog_120291_Content_24 = {
    Text = "Xu entah sejak kapan sudah berada di depanmu, kamu secara naluriah menggenggam erat tangan wanita yang mengantarmu, berusaha untuk bersembunyi di belakangnya."
  },
  AvgDialog_120291_Content_25 = {
    Text = [[
Jari-jari Xu Yingyu yang seperti giok menopang dagumu, perlahan diangkat ke atas, dan kamu melihat kembali sepasang mata itu.
Sangat mirip dengan ibumu, tetapi sangat indah hingga membuatmu merasa kegelisahan.]]
  },
  AvgDialog_120291_Content_26 = {
    Text = "Saya, saya..."
  },
  AvgDialog_120291_Content_27 = {
    Text = "<Shake:Orang-orang yang melihatmu di jalan sebelumnya semua menjadi gila, ada seorang paman yang memakai gaun, matanya bahkan dicongkel keluar! Aku takut!>"
  },
  AvgDialog_120291_Content_28 = {
    Text = "Kata-kata kekanak-kanakan yang keluar dari mulutmu membuat Xu terdiam sejenak, lalu ia tertawa hingga hampir kehilangan kesopanan."
  },
  AvgDialog_120291_Content_29 = {
    Text = "Ini kebetulan. Tuan Du, pas sekali, mohon bantu aku keluar dari kesulitan ini. Bunga Melati Kecil, coba lihat, apakah yang dimaksud adalah Tuan ini?"
  },
  AvgDialog_120291_Content_3 = {
    Text = "Keterkejutannya yang berada di pusat kegilaan yang tidak dikenal seharusnya menghancurkan otakmu, atau setidaknya menghilangkan kekuatan kehendakmu."
  },
  AvgDialog_120291_Content_30 = {
    Text = "Kamu mengikuti jari-jarinya yang menjauh dari dagumu, dan baru menyadari bahwa di belakang para bibi yang penuh kebencian, masih ada seorang pria lain yang mengenakan gaun itu."
  },
  AvgDialog_120291_Content_31 = {
    Text = "Itu dia, eh, kenapa matanya masih ada?"
  },
  AvgDialog_120291_Content_32 = {
    Text = "Wajahnya tidak lagi berdarah, dan matanya juga tumbuh di tempat yang seharusnya, kamu bisa mengenalinya."
  },
  AvgDialog_120291_Content_33 = {
    Text = "Saat Ibu masih ada, kalian dan Ayah pergi ke pesta, Ayah beberapa kali ingin berbincang dengannya, tetapi setiap kali selalu ditolak, dan setelah itu Ayah marah besar."
  },
  AvgDialog_120291_Content_34 = {
    Text = "Hari itu yang ketakutan, adalah gadis kecil ini? Apakah ini layak untukmu menghabiskan banyak perhatian, mengirimku jauh untuk membelikannya makanan."
  },
  AvgDialog_120291_Content_35 = {
    Text = "Keluarga He bahkan tidak bisa mengurus putri mereka yang mengalami histeria, tapi masih ingin campur tangan dalam bisnis ekspor-impor Haicheng, sungguh menggelikan."
  },
  AvgDialog_120291_Content_36 = {
    Text = "Gadis kecil baru-baru ini sakit karena istrinya meninggal, terbaring di tempat tidur, dan selalu dalam kondisi tidak baik. Maafkan Pak Du, saya akan segera..."
  },
  AvgDialog_120291_Content_37 = {
    Text = "Melihat wajah ayah yang suram, kamu terkejut dan tubuhmu menjadi kaku, tapi segera, kamu mencium aroma magnolia, kamu dipeluk oleh Xu, sambil dia dengan acuh tak acuh mencubit dan menggosok-gosok."
  },
  AvgDialog_120291_Content_38 = {
    Text = "Dulangjun, hamba sudah bilang, hamba suka Nona kecil dari keluarga He ini. Jika Anda berbicara serius tentang dia, hamba tidak akan senang—jika hamba tidak senang, apa yang akan Anda lakukan?"
  },
  AvgDialog_120291_Content_39 = {
    Text = "Pria itu mendengar kata-kata tersebut, tatapan meremehkan yang semula menilai dirimu dari atas ke bawah tiba-tiba kehilangan fokus. Kemudian, dia mengayunkan tangannya dengan penuh semangat, memukul wajahnya sendiri satu per satu."
  },
  AvgDialog_120291_Content_4 = {
    Text = "Tetapi kesadaran ini masih terlalu kecil, seperti serangga mayfly. Tidak, lebih sederhana. Sebuah amoeba, atau makhluk bersel tunggal lainnya. Kamu hanya tahu bahwa kamu harus kenyang, harus hangat, dan harus menghindari bahaya serta mencari keuntungan."
  },
  AvgDialog_120291_Content_40 = {
    Text = "Wajahnya seketika membengkak merah, namun seolah tidak merasakan sedikit pun rasa sakit, ia membuka mulutnya dengan kaku, memperlihatkan senyuman seperti boneka yang pernah kamu lihat di festival orang asing."
  },
  AvgDialog_120291_Content_41 = {
    Text = "Saya salah ucap!"
  },
  AvgDialog_120291_Content_42 = {
    Text = "Saya salah ucap, saya salah ucap!"
  },
  AvgDialog_120291_Content_43 = {
    Text = "Dalam suara tamparan yang berulang, Xu tersenyum ceria sambil mengambil sekantong permen dari sakunya, lalu mengambil satu butir dan memasukkannya ke dalam mulutmu."
  },
  AvgDialog_120291_Content_44 = {
    Text = "Ini aneh, apakah Nona He suka melihatnya?"
  },
  AvgDialog_120291_Content_45 = {
    Text = "Cairan manis mengalir, kamu tertegun menatap segala sesuatu di depanmu, akhirnya, mengangkat kepala dan melihat ke arah Xu."
  },
  AvgDialog_120291_Content_46 = {
    Text = "…Permen pir dari Kuil Chenghuang, ibu sering membelinya untukku dulu."
  },
  AvgDialog_120291_Content_47 = {
    Text = "Tuan Xu, apakah kamu Ibu?"
  },
  AvgDialog_120291_Content_48 = {
    Text = "Xu tidak menjawabmu, hanya tersenyum terus-menerus, sementara para bibi dan ayah, semuanya seperti terpesona, berdiri diam di tempat tanpa suara."
  },
  AvgDialog_120291_Content_49 = {
    Text = "Dulang Jun, lihat dirimu, aku hanya bertindak sedikit nakal. Tindakanmu begitu keras, aku akan merasa sakit hati."
  },
  AvgDialog_120291_Content_5 = {
    Text = "Jadi kamu hanya ditahan lagi oleh kabut itu, membuka mata tanpa cedera sedikit pun."
  },
  AvgDialog_120291_Content_50 = {
    Text = "Begitu pria itu berhenti, para bibi seolah baru tersadar, menatap Tuan Du yang wajahnya sudah memucat keunguan dengan tatapan bingung dan terkejut."
  },
  AvgDialog_120291_Content_51 = {
    Text = "Saya ingat Tuan He memiliki sesuatu yang ingin dibicarakan dengan Tuan Du, jadi saya mengambil inisiatif untuk membawa hadiah kunjungan ini."
  },
  AvgDialog_120291_Content_52 = {
    Text = "Nona kecil dari keluarga He, saat mereka berdiskusi, apakah kamu bersedia membawaku keluar untuk berjalan-jalan?"
  },
  AvgDialog_120291_Content_53 = {
    Text = "Sebelum melangkah keluar dari pintu, kamu tidak bisa menahan diri untuk melihat ke arah ayahmu. Di wajahnya tidak ada ekspresi kosong dan aneh seperti yang ditunjukkan oleh Tuan Du dan para bibi, tetapi ia diam-diam membiarkan segalanya terjadi."
  },
  AvgDialog_120291_Content_54 = {
    Text = "Tuan Xu, Anda……"
  },
  AvgDialog_120291_Content_55 = {
    Text = "Kamu punya banyak hal yang ingin ditanyakan, bukan?"
  },
  AvgDialog_120291_Content_56 = {
    Text = "Jangan tergesa-gesa… sayangku, sayangku yang baik."
  },
  AvgDialog_120291_Content_57 = {
    Text = "Bunga melati kecilku... ayo, lihatlah aku."
  },
  AvgDialog_120291_Content_58 = {
    Text = "Malam yang gelap menekan ke bawah, di bawah bulan perak yang pucat seperti tulang, Xu membuka kipasnya, kabut samar-samar menyerangmu, membungkusmu dan menelanmu."
  },
  AvgDialog_120291_Content_59 = {
    Text = "Dengan samar, ibu melihatmu dalam cahaya hangat, tersenyum lembut dan membungkuk mengulurkan kedua tangannya kepadamu."
  },
  AvgDialog_120291_Content_6 = {
    Text = "Langit benar-benar gelap, jendela-jendela di ruangan lain memantulkan bayangan lilin yang jauh, langkah-langkah kecil yang melayang kembali mendekat dari kejauhan."
  },
  AvgDialog_120291_Content_60 = {
    Text = "Seperti senar yang tiba-tiba putus, hidungmu terasa perih, air mata sepenuhnya mengaburkan pandanganmu, dan kamu tanpa ragu memeluknya erat-erat."
  },
  AvgDialog_120291_Content_61 = {
    Text = "Ibu, bisakah kamu tidak pergi lagi."
  },
  AvgDialog_120291_Content_62 = {
    Text = "Huu hu, huu huu huu, pikiranku sangat kacau, saya sangat takut. Aku sangat merindukanmu! Ibu."
  },
  AvgDialog_120291_Content_63 = {
    Text = "Wanita dengan lembut memelukmu, mengusap punggungmu dengan lembut."
  },
  AvgDialog_120291_Content_64 = {
    Text = "Anak perempuan sayang Ibu, anak perempuan yang baik Ibu."
  },
  AvgDialog_120291_Content_65 = {
    Text = "Sayangku yang patuh, sayangku yang baik."
  },
  AvgDialog_120291_Content_66 = {
    Text = "Apa yang kamu rela korbankan untuk dapat bersama Ibu selamanya?"
  },
  AvgDialog_120291_Content_67 = {
    Text = "Kabut itu sepertinya kembali menyelimuti dirimu, dan kamu mendengar suara gumamanmu sendiri."
  },
  AvgDialog_120291_Content_68 = {
    Text = "Semua bisa... apa pun bisa."
  },
  AvgDialog_120291_Content_69 = {
    Text = "Seluruh rumah boleh?"
  },
  AvgDialog_120291_Content_7 = {
    Text = "Aduh, Nona, kamu membuat orang terkejut. Berlari ke jalan besar dan berperilaku aneh, apakah kamu ingin membahayakan kami yang di bawah ini."
  },
  AvgDialog_120291_Content_70 = {
    Text = "Aku tidak mau rumah, aku hanya mau Ibu."
  },
  AvgDialog_120291_Content_71 = {
    Text = "Seluruh rumah, seluruh kota laut, dan ayahmu, apakah bisa?"
  },
  AvgDialog_120291_Content_72 = {
    Text = "Ayah… Ayah…"
  },
  AvgDialog_120291_Content_73 = {
    Text = "Kamu melamun sejenak, tiba-tiba teringat setiap malam, ibumu menunggu dengan penuh kesabaran, tangan yang jatuh di kepalamu saat ayah pulang."
  },
  AvgDialog_120291_Content_74 = {
    Text = "Tidak apa-apa, waktu masih sangat lama, Bunga Melati Kecil."
  },
  AvgDialog_120291_Content_75 = {
    Text = "Kamu sepertinya diangkat oleh seseorang, jatuh ke dalam selimut yang lembut, sesuatu yang lebih hangat, lebih lembut, dengan mesra memelukmu."
  },
  AvgDialog_120291_Content_76 = {
    Text = "Malam sudah sangat larut, tidurlah, aku akan segera, segera, datang ke sisimu."
  },
  AvgDialog_120291_Content_77 = {
    Text = "Setelah ibu pergi, kamu merasakan ketenangan yang tak terhingga untuk pertama kalinya, diiringi dengan rasa kantuk yang datang, terjatuh ke dalam mimpi yang manis dan dalam."
  },
  AvgDialog_120291_Content_8 = {
    Text = "<Shake:Guruh——>"
  },
  AvgDialog_120291_Content_9 = {
    Text = "……Sigh, aku benar-benar merasa kasihan padamu, cepat makan. Tuan sudah menunggu di depan, jangan buat aku kesulitan lagi, mengerti tidak?"
  },
  AvgDialog_120296_Content_1 = {Text = "Sayang"},
  AvgDialog_120296_Content_10 = {
    Text = "Sudah, simpan pikiranmu itu, jangan bilang aku menakut-nakutimu, rumah ini tidak tenang. Semua wanita yang terlalu disukai tuan, pada akhirnya semua menghilang."
  },
  AvgDialog_120296_Content_11 = {
    Text = "Bahkan mantan istrinya yang tumbuh bersama dengannya, dikatakan meninggal karena sakit, siapa yang tahu sebenarnya..."
  },
  AvgDialog_120296_Content_12 = {
    Text = "Aduh! Kamu mendorongku apa!"
  },
  AvgDialog_120296_Content_13 = {
    Text = "Nyonya, sungguh... sungguh minta maaf. Kakak saya suka berbicara sembarangan, tolong jangan dengarkan omongannya, kami sama sekali tidak bermaksud untuk berselisih dengan Anda, saya mohon, jangan sekali-kali memberitahu Tuan."
  },
  AvgDialog_120296_Content_14 = {
    Text = "Ditarik kembali oleh adiknya dengan tiba-tiba, bibi yang memiliki riasan mata dan alis yang halus, langsung tersadar, wajahnya tiba-tiba pucat ketakutan, buru-buru menutup mulutnya dan menghentikan suaranya."
  },
  AvgDialog_120296_Content_15 = {
    Text = "Masa rumah ini tidak aman, kenapa kalian tidak berpikir untuk mencari tempat lain?"
  },
  AvgDialog_120296_Content_16 = {
    Text = "…Di mana masih ada tempat yang bisa pergi, jika kita bisa diperlakukan seperti Anda, dijunjung tinggi oleh orang-orang terhormat, barulah kita bisa pergi ke mana saja."
  },
  AvgDialog_120296_Content_17 = {
    Text = "Hehe, diperlakukan seperti permata?"
  },
  AvgDialog_120296_Content_18 = {
    Text = "Xu tiba-tiba tertawa, pada saat itu, beberapa selir di koridor mendengar suara tawa pelan yang lebih samar dan tidak menentu."
  },
  AvgDialog_120296_Content_19 = {
    Text = "Mata mereka pun menjadi kosong, bingung menengadah, melihat wanita yang berjalan kembali ke dalam kedalaman koridor."
  },
  AvgDialog_120296_Content_2 = {
    Text = "Anak gadis baru, memang punya sedikit cara."
  },
  AvgDialog_120296_Content_20 = {
    Text = "Bunga melati kecilku sedang tidur, jangan ganggu dia, ikutlah bersamaku."
  },
  AvgDialog_120296_Content_21 = {
    Text = "Hamba akan membuat kalian tahu, Yang Mulia, bahwa orang-orang terhormat, harus seperti barang berharga, yang menarik ketika dipegang di ujung jari."
  },
  AvgDialog_120296_Content_22 = {
    Text = "Wajah para selir muncul senyuman penuh kebodohan, kemudian, kabut menutupi bibir mereka, kipas menutupi wajah mereka."
  },
  AvgDialog_120296_Content_23 = {
    Text = "Aroma melati yang manis dan kuat, perlahan menyebar di dalam rumah."
  },
  AvgDialog_120296_Content_25 = {
    Text = "Setelah Xu diterima ke dalam rumah He dengan nama Istri yang Melanjutkan, kamu tidak pernah merasakan lapar lagi. Setiap orang memperlakukanmu dengan ramah dan hangat, seolah-olah kamu masih menjadi Nona yang sama saat Ibumu masih ada."
  },
  AvgDialog_120296_Content_26 = {
    Text = "Namun, ayah tidak pernah keluar dari kamarnya lagi, Xu juga tidak pernah masuk, sebaliknya, para bibi seolah-olah ditarik oleh benang tak terlihat, sering bolak-balik ke kamar Xu."
  },
  AvgDialog_120296_Content_27 = {
    Text = "Eh, Nona, bisakah kamu membantu, tuan sudah khusus memerintahkan untuk tidak membiarkan siapa pun mendekati kamarnya."
  },
  AvgDialog_120296_Content_28 = {
    Text = "Sudah lama aku tidak bertemu Ayah, aku... aku hanya akan melihatnya dari jauh, menjamin tidak akan mengganggunya."
  },
  AvgDialog_120296_Content_29 = {
    Text = "Namun sebelum mendekat, kamu sudah mendengar raungan serak yang penuh semangat dan tidak normal dari dalam ruangan."
  },
  AvgDialog_120296_Content_3 = {
    Text = "Kamu memang mulutnya jahat, kipas yang dia berikan padamu, bukankah kamu sangat menyukainya?"
  },
  AvgDialog_120296_Content_30 = {
    Text = "Xu… kasihku, penyelamatku, jantungku, aku tidak bisa lagi mengirimmu pergi, kamu adalah milikku, kamu hanya bisa menjadi milikku."
  },
  AvgDialog_120296_Content_31 = {
    Text = "Darah dan tulang mereka, tidak ada yang layak disebutkan... Berapa pun jumlahnya, ah! Asalkan bisa menukarnya dengan dirimu, asalkan bisa menukarnya dengan dirimu, semuanya berharga!"
  },
  AvgDialog_120296_Content_32 = {
    Text = "Saya mengerti, saya melihatnya! Haha, hahahaha!!!"
  },
  AvgDialog_120296_Content_33 = {
    Text = "Suara bergerak licin seolah-olah merayap di lantai, hingga akhirnya, napas dari arah manapun berubah menjadi suara pendek seperti tiupan api yang terputus, seolah-olah terbungkus oleh sesuatu yang membuatnya sulit bernapas."
  },
  AvgDialog_120296_Content_34 = {Text = "Ayah!"},
  AvgDialog_120296_Content_35 = {
    Text = "Kau terkejut oleh suaranya yang seolah-olah mendekati kematian, langsung berlari dan mendorong pintu kamar dengan keras."
  },
  AvgDialog_120296_Content_36 = {
    Text = "Di dalamnya hanya ada He Fang, yang dengan panik bersandar pada pinggiran tempat tidur terkulai di atas selimut berwarna gelap, seluruh selimut, atau bisa dibilang seluruh kamar, sangat lembap seolah-olah telah direndam."
  },
  AvgDialog_120296_Content_37 = {
    Text = "Pecahan benda yang hancur dan kain tergeletak di sekeliling dengan mencolok, dia tersadar, wajahnya dipenuhi warna merah patologis yang tidak normal, lalu mengangkat bantal kayu dan memukul kepalamu."
  },
  AvgDialog_120296_Content_38 = {
    Text = "Siapa yang membiarkanmu masuk!"
  },
  AvgDialog_120296_Content_39 = {
    Text = "Siapa pun tidak boleh mengganggu kita sendirian, pergi! Pergi!"
  },
  AvgDialog_120296_Content_4 = {
    Text = "Ge Mei terlihat bagus, seleranya bagus, barang-barang yang diberikan sangat bergaya. Kamu juga tidak ingin mengayunkan kipas di timur dan di barat, seolah-olah ingin terlihat seperti dia, dengan kipas di wajah."
  },
  AvgDialog_120296_Content_40 = {
    Text = "Wanita itu segera mengikuti langkahmu dan cepat-cepat menutup pintu di tengah raungan yang datang dari arah mana."
  },
  AvgDialog_120296_Content_41 = {
    Text = "Sudah dibilang jangan mengganggu Tuan, dia akan marah, jangan berlarian, keponakanku yang kecil."
  },
  AvgDialog_120296_Content_42 = {
    Text = "Ayah... Ayah, ada apa ini? Kenapa dia terus memanggil nama Tuan Xu?"
  },
  AvgDialog_120296_Content_43 = {
    Text = "<Shake:Tuan Xu jelas-jelas sudah keluar sejak pagi, dia sedang berbicara dengan siapa, ekspresinya sangat menakutkan...>"
  },
  AvgDialog_120296_Content_44 = {
    Text = "Urusan tuan, kami para pelayan tidak bisa mengaturnya."
  },
  AvgDialog_120296_Content_45 = {
    Text = "Kamu terhuyung-huyung berlari ke tempat yang paling kamu kenal, berharap menemukan seseorang untuk membantu."
  },
  AvgDialog_120296_Content_46 = {
    Text = "Kamar Nyonya, kini juga kamar Xu, adalah kamar yang pernah ditinggali Ibu."
  },
  AvgDialog_120296_Content_47 = {
    Text = "Pintu yang semakin pudar setelah ibu pergi, kini dihiasi dengan ukiran emas sekali lagi, seolah-olah menjadi semacam gerbang, setiap kali dibuka dan ditutup mengeluarkan aroma aneh yang membuat pusing."
  },
  AvgDialog_120296_Content_48 = {
    Text = "Haha, hihi... ugh, hiks hiks hiks... Ternyata aku selalu salah, salah sampai keterlaluan!"
  },
  AvgDialog_120296_Content_49 = {
    Text = "Cincang, hancurkan, buka! Buka semua, buka, masih panas, persembahkan kepada-Nya, mereka akan patuh, Allah tidak perlu lagi menderita di lautan penderitaan!"
  },
  AvgDialog_120296_Content_5 = {
    Text = "Apakah sedang membicarakan tentang diriku?"
  },
  AvgDialog_120296_Content_50 = {
    Text = "<Change>Xú... Juruselamat kami, @3 kami!"
  },
  AvgDialog_120296_Content_51 = {
    Text = "Kabut tak terlihat memenuhi seluruh ruangan, mereka dengan khusyuk mengangkat kipas yang dibagikan pada hari Xu Ru masuk, sambil menangis dan tertawa, perlahan-lahan berubah menjadi jeritan yang aneh."
  },
  AvgDialog_120296_Content_52 = {
    Text = "Kata-kata para selir di dalam rumah tidak kamu pahami sama sekali, telinga penuh dengan dengungan dan suara detak jantung, terjatuh kembali mundur, tanpa sengaja menabrak pagar dan mengeluarkan suara."
  },
  AvgDialog_120296_Content_53 = {
    Text = "...Ya, ada suara."
  },
  AvgDialog_120296_Content_54 = {
    Text = "<Shake:<Red:Apakah ini lagi makanan darah yang bisa dipersembahkan?>>"
  },
  AvgDialog_120296_Content_55 = {
    Text = "Akhiran kalimat mereka dibawa dengan senyuman ringan, semua tangisan menghilang, dan rasa dingin yang aneh dan mencekam menyelimuti tubuhmu!"
  },
  AvgDialog_120296_Content_56 = {Text = "Lari!!!!!!"},
  AvgDialog_120296_Content_57 = {
    Text = "Itu adalah ketakutan yang diperhatikan oleh para pemangsa, ketakutan yang paling dalam dari darah semua makhluk sejak zaman purba!"
  },
  AvgDialog_120296_Content_58 = {
    Text = "Ya! Hanya sekotak kue kupu-kupu, apa pantas membuat Bunga Melati kecil begitu senang berlari ke pelukan saya?"
  },
  AvgDialog_120296_Content_59 = {
    Text = "Lengan yang sehalus giok menahan momentum jatuhmu, jika kamu melihat keluar melalui celah pagar rumah, pengawas kuning yang terkenal di Kota Laut itu sedang menutup pintu mobilnya."
  },
  AvgDialog_120296_Content_6 = {
    Text = "*Teriakan Ah! Maaf, Nyonya!"
  },
  AvgDialog_120296_Content_60 = {
    Text = "Kotak kue disodorkan di depanmu, pola mata yang bertumpuk di atas kertas bunga benar-benar membuatmu ketakutan. Kamu menarik napas dalam-dalam, mengumpulkan keberanian untuk menjatuhkannya ke tanah."
  },
  AvgDialog_120296_Content_61 = {
    Text = "Siapa kamu sebenarnya?! Mengapa di rumah kami! Apa yang terjadi di rumahku, ayah, bibi, dan paman-paman itu, setelah kamu datang, semua orang jadi aneh..."
  },
  AvgDialog_120296_Content_62 = {
    Text = "Astaga... hal kecil saja, lihat, bunga melati kecilku bahkan sudah menangis."
  },
  AvgDialog_120296_Content_63 = {
    Text = "Dia tidak marah karena camilan yang kamu jatuhkan, malah dengan mesra membungkuk, menyentuh sudut matamu yang basah karena ketakutan."
  },
  AvgDialog_120296_Content_64 = {
    Text = "Bunga Melati Kecil, sebelum aku datang ke sini, tempat yang bahkan tidak ada setetes air ini, apakah benar-benar rumahmu?"
  },
  AvgDialog_120296_Content_65 = {
    Text = "Nona! Hanya sebentar tidak memperhatikan, kamu bisa... Nyonya, maaf, semua salahku karena tidak menjaga Nona dengan baik."
  },
  AvgDialog_120296_Content_66 = {
    Text = "Xu tidak menghiraukan orang yang datang, memelukmu lebih erat lagi, seperti biasa, seolah sedang mengelus hewan kecil, membelai punggungmu dengan suara yang lembut dan halus."
  },
  AvgDialog_120296_Content_67 = {
    Text = "Bunga Melati Kecil, pikirkanlah dengan baik. Apa yang sebenarnya terjadi dengan hal ini, dan apa yang terjadi dengan hal itu, dan apa hubungannya?"
  },
  AvgDialog_120296_Content_68 = {
    Text = "Asalkan kau baik-baik saja, patuh, dan terus mendengarkan perkataan hamba."
  },
  AvgDialog_120296_Content_69 = {
    Text = "Semua hal bisa menjadi milikmu, semua orang bisa menjadi mainanmu."
  },
  AvgDialog_120296_Content_7 = {
    Text = "Cih, apa itu Nyonya atau bukan, seorang yang keluar dari panggung teater, takut apa dia, dia bisa memakanmu."
  },
  AvgDialog_120296_Content_70 = {
    Text = "Dia mengelus dari punggungmu hingga ke rambut, dan setelah akhirnya puas bermain dengan rambutmu, dia melepaskannya, seluruh tubuhnya memancarkan aura kebahagiaan."
  },
  AvgDialog_120296_Content_71 = {
    Text = "Baiklah, bawa diri ini, bunga melati kecil, untuk tidur... Dia perlu istirahat."
  },
  AvgDialog_120296_Content_72 = {
    Text = "Kamu telah berjalan jauh di dalam kabut, di dalam warna kabut yang kelabu, kamu melihat sebuah area perairan gelap yang luas."
  },
  AvgDialog_120296_Content_73 = {
    Text = "Ribuan tubuh lengket yang merayap dan dipenuhi dengan penyedot menempel di perbatasan air dan kabut, sebuah bayangan lembut duduk membelakangi kamu di tepi air."
  },
  AvgDialog_120296_Content_74 = {
    Text = "Ibu? Apakah itu kamu?"
  },
  AvgDialog_120296_Content_75 = {
    Text = "<Shake:......salah......semua......lari......>"
  },
  AvgDialog_120296_Content_76 = {
    Text = "Ibu, apa yang kamu katakan, aku tidak bisa mendengar dengan jelas."
  },
  AvgDialog_120296_Content_77 = {
    Text = "Kamu mendekat lebih dekat, dan tiba-tiba menyadari bahwa dia tidak duduk di tepi air, melainkan bagian bawahnya telah berubah menjadi banyak tentakel, menyatu dengan air abu-abu."
  },
  AvgDialog_120296_Content_78 = {
    Text = "<Shake:Salah, semuanya salah.>"
  },
  AvgDialog_120296_Content_79 = {
    Text = "<Shake:Dia bukan... Dia bukan...>"
  },
  AvgDialog_120296_Content_8 = {
    Text = "Lihat kalian beberapa, seperti kucing yang berduri, sangat menggemaskan."
  },
  AvgDialog_120296_Content_80 = {
    Text = "Wanita itu menoleh, wajah yang sudah dikenal dipenuhi dengan garis air mata abu-abu, berteriak dan berteriak padamu."
  },
  AvgDialog_120296_Content_81 = {
    Text = "<Red:Dia memiliki wajah ibu.>"
  },
  AvgDialog_120296_Content_82 = {
    Text = "<Change>Dia bukan Dia bukan Dia bukan Dia bukan!!"
  },
  AvgDialog_120296_Content_83 = {
    Text = "<Red:<Shake:Salah! Semua salah!! Nak!!! Lari!! Cepat lari!!!>>"
  },
  AvgDialog_120296_Content_9 = {
    Text = "Jangan khawatir, aku hanya baru datang, melihat kalian berbincang dengan semangat, jadi aku juga ingin datang dan berbicara sedikit."
  },
  AvgDialog_120297_Content_1 = {
    Text = "Suara panah berbunyi"
  },
  AvgDialog_120297_Content_10 = {
    Text = "Kadang-kadang itu mereka sendiri, kadang-kadang itu istri mereka, saat-saat seperti itu, senyuman di wajah Xu selalu menjadi lebih jelas, dan saat mereka datang untuk kedua kalinya, kipas hitam yang sama dengan selir di halaman akan muncul di tangan mereka."
  },
  AvgDialog_120297_Content_100 = {
    Text = "Namun, He Fang yang baru saja terlihat garang, ekspresinya ternyata benar-benar melunak."
  },
  AvgDialog_120297_Content_101 = {
    Text = "Kau... benar-benar berpikir seperti itu?"
  },
  AvgDialog_120297_Content_102 = {
    Text = "He Lang juga tahu, meskipun aku memiliki kekuatan ilahi, namun aku terhubung dengan orang yang membangkitkan. Apa pun yang He Lang perintahkan padaku, aku hanya bisa melakukannya, di mana ada kemungkinan untuk menipumu?"
  },
  AvgDialog_120297_Content_103 = {
    Text = "Dan di jalan seperti biasanya, kamu tidak bisa bersuara dan tidak bisa bergerak. Seolah-olah \"dewi\" yang aneh ini sudah memutuskan untuk membuatmu menyaksikan pertunjukan konyol ini."
  },
  AvgDialog_120297_Content_104 = {
    Text = "He Fang pergi dengan gembira, seperti hari itu di depan gedung Xianjin, bahkan tidak menoleh ke arahmu lagi."
  },
  AvgDialog_120297_Content_105 = {
    Text = "Saat kamu bisa bersuara, kamu berbalik dan menerjang Xu, mengeluarkan jeritan seperti binatang. Kaki, tinju, gigi, semua cara serangan yang kamu ketahui digunakan meskipun kamu tahu itu sia-sia."
  },
  AvgDialog_120297_Content_106 = {
    Text = "Kembalikan padaku, kembalikan ibuku, kembalikan ayahku!"
  },
  AvgDialog_120297_Content_107 = {
    Text = "Xu Zhi shan berdiri di tempat, tak bergerak membiarkanmu meluapkan emosimu, senyuman di matanya membuatmu melupakan rasa takut, hanya tersisa kemarahan dan kehancuran."
  },
  AvgDialog_120297_Content_108 = {
    Text = "Semua ini karena kamu, kamu sama sekali bukan dewi, kamu adalah monster!"
  },
  AvgDialog_120297_Content_109 = {
    Text = "Wanita di depanmu... mengangguk."
  },
  AvgDialog_120297_Content_11 = {
    Text = "Jika menunggu lebih lama, bayangan Tuan Xu pun tidak akan terlihat, cepat datang."
  },
  AvgDialog_120297_Content_110 = {
    Text = "Benar, bunga melati kecil, hamba adalah makhluk gaib."
  },
  AvgDialog_120297_Content_111 = {
    Text = "Tapi kematian ibumu tidak ada hubungannya dengan diriku, siapa pun yang membunuh banyak wanita, termasuk dia, hanya untuk memanggil diriku, demi kekayaan dan kekuasaan mereka."
  },
  AvgDialog_120297_Content_112 = {
    Text = "Tadi, dia bahkan ingin membunuhmu. Kau tidak ingin mati, aku meresponmu. Jika aku mengabaikanmu, kau pasti akan mati, bukan?"
  },
  AvgDialog_120297_Content_114 = {
    Text = "Kamu terdiam, suaranya penuh semangat, dan sepasang mata cantiknya dipenuhi dengan senyuman."
  },
  AvgDialog_120297_Content_115 = {
    Text = "Sekarang, bunga melati kecilku, kamu mau memilih yang mana?"
  },
  AvgDialog_120297_Content_116 = {
    Text = "Kamu membuka mulutmu sia-sia, akhirnya hanya terdiam menatapnya, suara dering tajam di telingamu mengganggu sarafmu, dia hanya mengusap punggungmu, lalu berjalan ke dalam halaman."
  },
  AvgDialog_120297_Content_117 = {
    Text = "Hehe... Segera, sangat cepat, saatnya untuk membuat pilihanmu akan segera tiba, Bunga Melati Kecil."
  },
  AvgDialog_120297_Content_119 = {
    Text = "Adegan siang hari terulang kembali dalam mimpi, kau terbangun dengan teriakan di tengah malam, rumah seakan sunyi seperti kematian. Tidak ada yang menjawabmu, suara tajam itu pun tidak ada lagi."
  },
  AvgDialog_120297_Content_12 = {
    Text = "Becak berguncang dengan hebat, meskipun tidak terdeteksi, setelah berbelok ke sana kemari, akhirnya kehilangan jejak saat kendaraan masuk ke dalam hutan."
  },
  AvgDialog_120297_Content_120 = {
    Text = "Kelaparan menggerogoti perutmu, kamu meringkuk cukup lama, akhirnya berdiri, mengikuti ingatan menemukan kotak biskuit yang pecah, berdiri diam di bawah sinar bulan, memakannya sampai bersih."
  },
  AvgDialog_120297_Content_121 = {
    Text = "Saat kamu tertidur kembali, kamu kembali ke tepi air abu-abu, ibumu mengulurkan lengan yang seperti tentakel, membuka tangan untukmu. Dan di belakangnya, samar-samar terlihat sosok besar lainnya."
  },
  AvgDialog_120297_Content_122 = {
    Text = "Ibu, dia masih di sini tidak?"
  },
  AvgDialog_120297_Content_123 = {
    Text = "Ibu akan selalu bersamamu."
  },
  AvgDialog_120297_Content_124 = {
    Text = "Aku akan selalu, selalu berada di sisi bunga melati kecilku."
  },
  AvgDialog_120297_Content_125 = {
    Text = "Dua suara terdengar bersamaan di telinga, kamu tidak bertanya lagi. Kamu benar-benar sangat lelah dan juga sangat takut."
  },
  AvgDialog_120297_Content_126 = {
    Text = "Kamu melompat tanpa ragu, terjun ke dalam pelukan yang mengerikan, lengket, dan sangat lembut."
  },
  AvgDialog_120297_Content_13 = {
    Text = "Kamu dibawa pergi tanpa tahu alasannya, perasaan cemas semakin kuat, satu-satunya cara untuk merasa sedikit lebih baik adalah dengan menggenggam tangan wanita itu lebih erat."
  },
  AvgDialog_120297_Content_14 = {
    Text = [[
Langit perlahan menjadi gelap, bulan tanpa sadar merayap di atas puncak pohon. 
 Tiba-tiba, wanita itu memberi isyarat untuk menyuruhmu diam.]]
  },
  AvgDialog_120297_Content_15 = {Text = "Ssst——"},
  AvgDialog_120297_Content_16 = {
    Text = "Jauh di sana, sosok Xu muncul, kereta putih melaju pergi, Tuan Du berdiri diam di sampingnya, di sudut, beberapa bayangan panjang melintasi bayangan pohon yang diterangi sinar bulan di tanah."
  },
  AvgDialog_120297_Content_17 = {
    Text = "Tuan Du, Pengawas Huang, pemimpin angkutan sungai Utara, dan di jalan besar, oh ya, Tuan Xu memang luar biasa..."
  },
  AvgDialog_120297_Content_18 = {
    Text = "Di kejauhan, wajah para pria tampak seperti ayah pada hari itu, muncul dengan warna darah yang tidak normal. Awalnya terdengar bisikan pelan, kemudian berubah menjadi jeritan bersemangat yang cepat, seperti mantra yang diucapkan."
  },
  AvgDialog_120297_Content_19 = {
    Text = "<Shake:Dia... tinggal... tidak bisa...>"
  },
  AvgDialog_120297_Content_2 = {
    Text = "Semua bibi semakin mirip dengan Xu, dan ayah juga tidak pernah lagi melangkah keluar dari pintu."
  },
  AvgDialog_120297_Content_20 = {
    Text = "<Shake:Membunuh... baru bisa...>"
  },
  AvgDialog_120297_Content_21 = {
    Text = "<Shake:Bunuh… bunuh… bunuh!! Bunuh—— cincang——!!!>"
  },
  AvgDialog_120297_Content_22 = {
    Text = "<Change>Milikku milikku milikku milikku milikku milikku, dia milikku!!"
  },
  AvgDialog_120297_Content_23 = {
    Text = "Cahaya pucat menyilaukan matamu, dan kamu baru menyadari bahwa di belakang setiap pria tersembunyi sebuah sabit, kini diangkat tinggi-tinggi dengan rapi——"
  },
  AvgDialog_120297_Content_24 = {
    Text = "Ha—ahhaha, ahahahahahahah!!!"
  },
  AvgDialog_120297_Content_25 = {
    Text = "Para pria itu perlahan mendekat, Xu tiba-tiba tertawa terbahak-bahak di tengah mereka, seolah melihat hal paling lucu di dunia, sambil mengulurkan jarinya untuk menunjuk wajah mereka satu per satu."
  },
  AvgDialog_120297_Content_26 = {
    Text = "Detik berikutnya, sabit tajam menghujam dari berbagai arah, suara daging yang robek, suara patah tulang yang mematahkan otot, lengan putih seperti giok terangkat tinggi."
  },
  AvgDialog_120297_Content_27 = {
    Text = "Cii, Kacha."
  },
  AvgDialog_120297_Content_28 = {
    Text = "Umm…umm…umm…umm…umm…umm…!"
  },
  AvgDialog_120297_Content_29 = {
    Text = "Kamu dipeluk erat, tangan wanita itu menutup mulutmu dengan kuat, menahan teriakan panikmu kembali ke dalam."
  },
  AvgDialog_120297_Content_3 = {
    Text = "Ibu tidak lagi muncul dalam mimpimu, terkadang kamu bermimpi melihat wajah Xu di setiap kipas, terkadang bermimpi ayah dimakan oleh monster, dan akhirnya terbangun dengan keringat dingin."
  },
  AvgDialog_120297_Content_30 = {
    Text = "<Change>Tengkorak, leher, rongga dada, lengan, perut…"
  },
  AvgDialog_120297_Content_31 = {
    Text = "<Shake:Muncul dari kepala, muncul dari leher, muncul dari rongga dada, muncul dari lengan, muncul dari pinggang dan perut…>"
  },
  AvgDialog_120297_Content_32 = {
    Text = "<Change>Menyusup keluar dari kepala, menyusup keluar dari leher, menyusup keluar dari rongga dada, menyusup keluar……"
  },
  AvgDialog_120297_Content_33 = {Text = "Tuan."},
  AvgDialog_120297_Content_34 = {
    Text = "Lembut, manja, manis."
  },
  AvgDialog_120297_Content_35 = {
    Text = "Terpisah begitu jauh, seperti kabut, berkelok-kelok masuk ke dalam pikiranmu melalui telingamu."
  },
  AvgDialog_120297_Content_36 = {
    Text = "Kabut darah entah kapan perlahan menjadi lebih dalam, satu per satu merangkak keluar dari potongan tubuh, lengan putih bersinar seperti giok mengalirkan lumpur hitam, terangkat tinggi."
  },
  AvgDialog_120297_Content_37 = {
    Text = "Aku sangat sakit, berikan aku sebuah ciuman——"
  },
  AvgDialog_120297_Content_38 = {
    Text = "<Change>Hamba@3, berikan hamba sebuah ciuman……"
  },
  AvgDialog_120297_Content_39 = {
    Text = "<Change>Hamba@3, berikan hamba@4!"
  },
  AvgDialog_120297_Content_4 = {
    Text = "Nona, jangan lagi marah, Tuan Xu sangat baik kepada Anda, setiap hari dia membawa banyak makanan dan mainan baru untuk Anda."
  },
  AvgDialog_120297_Content_40 = {
    Text = "<Change>Aku sangat sakit, berikan aku sebuah ciuman!"
  },
  AvgDialog_120297_Content_41 = {
    Text = "Xu... monster yang mirip Xu, bagian bawah tubuh mereka larut dalam potongan tubuh yang hancur, lumpur menutupi seluruh wajah, hanya menyisakan kontur bibir."
  },
  AvgDialog_120297_Content_42 = {
    Text = "Setiap wajah \"Xu\" terbuka dengan sepuluh lebih bibir yang subur, indah, dan berbentuk kelopak, menghisap ke arah pria-pria yang tertawa seperti terpesona."
  },
  AvgDialog_120297_Content_43 = {
    Text = "<Change>Glek la - Glek la -"
  },
  AvgDialog_120297_Content_44 = {
    Text = "Suara tekanan tengkorak, suara pecahnya tengkorak."
  },
  AvgDialog_120297_Content_45 = {
    Text = "<Change>Slurp——Ciirooo——"
  },
  AvgDialog_120297_Content_46 = {
    Text = "Suara hisapan, suara makan."
  },
  AvgDialog_120297_Content_47 = {
    Text = "Kamu menyaksikan kepala mereka pecah berantakan, lalu kembali utuh seperti semula. Mereka mengeluarkan desahan puas, dan berkumpul dalam suara gumaman yang kenyang."
  },
  AvgDialog_120297_Content_48 = {
    Text = "Tuan Du, Pengawas Huang, pemimpin pengangkutan utara..."
  },
  AvgDialog_120297_Content_49 = {
    Text = "Mereka bangkit dalam keheningan, seolah-olah tidak ada yang pernah terjadi, pergi dengan bingung, sementara Xu entah kapan, telah menghilang tanpa jejak."
  },
  AvgDialog_120297_Content_5 = {
    Text = "Wanita itu menghela napas, menggunakan sapu tangan untuk menghapus keringat dingin yang muncul karena terkejut."
  },
  AvgDialog_120297_Content_50 = {
    Text = "Akhirnya tangan itu melepaskanmu, dalam keheningan yang menekan hingga ke titik tertinggi, air matamu jatuh tanpa bisa dikendalikan, saat kamu berbalik, pupil matamu bergetar dengan kuat."
  },
  AvgDialog_120297_Content_51 = {Text = "Aduh..."},
  AvgDialog_120297_Content_52 = {
    Text = "Aku selalu berpikir, bagaimana cara berterus terang dengan bunga melati kecilku—Moyashi."
  },
  AvgDialog_120297_Content_53 = {
    Text = "Muridmu menyusut sangat kecil, hingga akhirnya, hanya tersisa wanita di depanmu, dalam sekejap, otakmu yang sudah tidak mampu menanggungnya lagi menghadirkan rasa sakit yang hebat."
  },
  AvgDialog_120297_Content_54 = {
    Text = "Dia seperti apa, wanita dengan suara yang nyaring itu."
  },
  AvgDialog_120297_Content_55 = {
    Text = "Pelayan di kamarmu sudah diberhentikan sejak ibumu meninggal."
  },
  AvgDialog_120297_Content_56 = {
    Text = "Tidak ada yang peduli tentang hidup atau matimu, kamu tidak pernah melihat wajahnya dengan jelas, tapi mengapa semua orang merasa kehadirannya begitu alami?"
  },
  AvgDialog_120297_Content_57 = {
    Text = "Aku menyukai tubuh itu, menyukai aroma melati yang ada padanya, aku sudah berpikir sejak awal... bagaimana bentuk bunga melati kecilnya, bunga melati kecilku?"
  },
  AvgDialog_120297_Content_58 = {
    Text = "Jadi, aku sudah tidak bisa menahan diri untuk datang dan menemui bunga melati kecilku sejak lama, sangat lama."
  },
  AvgDialog_120297_Content_59 = {
    Text = "Kamu melarikan diri secepatnya. Dia tidak menghentikan gerakanmu, hanya melihatmu dengan senyuman dari balik tirai, seperti melihat anak kucing liar yang ketakutan dan berlari."
  },
  AvgDialog_120297_Content_6 = {
    Text = "Nona, jika kamu benar-benar takut seperti ini, kami punya ide."
  },
  AvgDialog_120297_Content_60 = {
    Text = "Ayah! Xu adalah monster, dia……"
  },
  AvgDialog_120297_Content_61 = {
    Text = "Kamu tidak ingat sudah berlari berapa lama, juga tidak tahu sudah melewati berapa banyak jalan yang salah, di tengah tatapan terkejut dari pelayan pintu, kamu berlari menuju kamar ayahmu, hampir saja menghancurkan pintu itu, panik menarik ujung pakaian ayahmu."
  },
  AvgDialog_120297_Content_62 = {
    Text = "Tetapi begitu nama Xu terucap, yang menyambutmu adalah sebuah tamparan telak yang sangat keras."
  },
  AvgDialog_120297_Content_63 = {
    Text = "Saya sudah bilang, kamu harus memanggilnya<Red:\"Ibu\">."
  },
  AvgDialog_120297_Content_64 = {
    Text = "Wajah Ayah tampak sangat jernih dan suram, kegilaan beberapa waktu lalu telah lenyap. Dia menarik kerah bajumu dan mencabutmu dari sisinya."
  },
  AvgDialog_120297_Content_65 = {
    Text = "Bukan, Ayah, dia telah menjadi orang di sekitarku, dia bergaul dengan banyak orang, dan bahkan membawa mereka——"
  },
  AvgDialog_120297_Content_66 = {Text = "Cukup!"},
  AvgDialog_120297_Content_67 = {
    Text = "Saat itu Xu menyukaimu, aku hanya membiarkanmu tinggal di rumah, tetapi kamu sama sekali tidak tahu diri seperti ibumu yang pendek umur."
  },
  AvgDialog_120297_Content_68 = {
    Text = "Satu badan berantakan, berbicara sembarangan, bahkan berbicara kasar kepada ibunya! Pergi ke depan aula dan hukum berlutut, sebelum jam tujuh malam, tidak boleh bangkit!"
  },
  AvgDialog_120297_Content_69 = {
    Text = "Dia bukan ibuku, dia adalah monster pemakan manusia!"
  },
  AvgDialog_120297_Content_7 = {
    Text = "Kamu begitu takut pada Tuan Xu, ikutlah lihat apa yang dia lakukan setiap hari, jika dia benar-benar monster, kita akan pergi berbicara dengan tuan dan mengusirnya dari rumah, bagaimana?"
  },
  AvgDialog_120297_Content_70 = {
    Text = "Kamu berteriak sekuat tenaga, ruangan itu terdiam sejenak, lalu, kamu mendengar..."
  },
  AvgDialog_120297_Content_71 = {
    Text = "<Red:Tawa dingin ayah.>"
  },
  AvgDialog_120297_Content_72 = {
    Text = "<Shake:\"Youkai\"?>"
  },
  AvgDialog_120297_Content_73 = {
    Text = "Xu, adalah korban persembahan yang aku pilih satu per satu dan belah satu per satu dengan tanganku sendiri, mengeluarkan biaya yang tak terhitung, menghabiskan semua tenaga, dan akhirnya berhasil memanggil <Red:\"Dewi\">!"
  },
  AvgDialog_120297_Content_74 = {
    Text = "Aku sudah mencoba begitu banyak kali, namun wanita-wanita biasa itu tidak layak mendapatkan perhatiannya, apakah kamu pikir hatiku tidak sakit? Aku juga tidak tega pada ibumu."
  },
  AvgDialog_120297_Content_75 = {
    Text = "Seperti kilat yang menyambar, kamu sulit memahami maksud kata-kata ayah, kesadaranmu sepenuhnya dikuasai oleh suara nyaring yang tajam."
  },
  AvgDialog_120297_Content_76 = {
    Text = "<Shake:Kamu seharusnya merasa terhormat, tubuhnya membentuk wujud dewi di dunia fana.>"
  },
  AvgDialog_120297_Content_77 = {
    Text = "Suara ayahmu mengeluarkan rasa dingin yang menyeramkan, dan kamu terkejut menyadari bahwa dia sudah berdiri dengan muram di antara dirimu dan pintu, mendekat langkah demi langkah."
  },
  AvgDialog_120297_Content_78 = {
    Text = "Karena kamu sudah tahu segalanya, rumah ini tidak boleh untukmu, dan aku juga tidak akan membiarkanmu keluar dan berbicara sembarangan lagi."
  },
  AvgDialog_120297_Content_79 = {
    Text = "Teriakanmu belum sempat keluar, tenggorokanmu sudah dicekik oleh ayahmu yang wajahnya dipenuhi kegilaan, pandanganmu segera diselimuti oleh merah darah."
  },
  AvgDialog_120297_Content_8 = {
    Text = "Mengusir Tuan Xu?"
  },
  AvgDialog_120297_Content_80 = {
    Text = "<Red:Dewi> telah turun, mulai sekarang dia akan <Red:selamanya> menjadi milikku. Apa pun kehormatan dan kekayaan, tidak ada artinya bagiku. Asalkan ada <Red:Dewi> di sisiku, semua pengorbanan adalah berharga!"
  },
  AvgDialog_120297_Content_81 = {
    Text = "<Shake:Ibu, tolong selamatkan aku…>"
  },
  AvgDialog_120297_Content_82 = {
    Text = "Aku... tidak ingin mati, aku ingin tetap hidup, Ibu..."
  },
  AvgDialog_120297_Content_83 = {
    Text = "<Change><Shake:Aku tidak ingin mati, sangat tidak enak, sangat tidak enak, Ibu, tolong selamatkan aku, tolong selamatkan @4!>"
  },
  AvgDialog_120297_Content_84 = {
    Text = "Siapa saja bisa, tolong selamatkan aku…………"
  },
  AvgDialog_120297_Content_85 = {
    Text = "Tidak ada yang menanggapi doamu yang tanpa suara."
  },
  AvgDialog_120297_Content_86 = {
    Text = "Kaos. Tercekik. Penderitaan. Hening… Aroma manis-pedas dari magnolia putih yang sudah tidak asing lagi."
  },
  AvgDialog_120297_Content_87 = {
    Text = "<Red:<Shake:Ciiit——>>"
  },
  AvgDialog_120297_Content_88 = {
    Text = "Dalam keadaan bingung, tentakel hitam meluncur keluar dari pintu, dengan kekuatan raksasa melemparkan ke arah mana pun, langsung menjatuhkannya ke atas tempat tidur."
  },
  AvgDialog_120297_Content_89 = {
    Text = "He Lang, bagaimana bisa bersaing dengan anak kecil."
  },
  AvgDialog_120297_Content_9 = {
    Text = "Suara klakson mobil terdengar di depan pintu utama, setiap hari menunggu di depan kediaman He, adalah wajah-wajah yang berbeda, semuanya adalah orang-orang terkemuka yang ingin didekati oleh pemilik rumah ini."
  },
  AvgDialog_120297_Content_90 = {
    Text = "Sebuah pelukan yang lembut menangkapmu, udara kembali masuk ke paru-paru yang hampir kering, perlahan mengangkat ekor kipas, di mana kamu diangkat tanpa terlihat."
  },
  AvgDialog_120297_Content_91 = {
    Text = "Hanya melihat sesuatu yang tidak seharusnya dilihat, aku tidak ingin dia mengingatnya, jadi dia tentu saja tidak akan mengingatnya."
  },
  AvgDialog_120297_Content_92 = {
    Text = "Nada suaranya seperti biasa ceria dan ringan, bahkan kekuatan yang menyentuh puncak kepalamu juga demikian."
  },
  AvgDialog_120297_Content_93 = {
    Text = "Di luar pintu, terdengar suara pelayan yang melaporkan."
  },
  AvgDialog_120297_Content_94 = {
    Text = "Tuan, ada beberapa pria yang menunggu Anda di ruang depan."
  },
  AvgDialog_120297_Content_95 = {
    Text = "Wajah He Fang berubah drastis, bahkan lebih buruk daripada saat dia ingin membunuhmu tadi."
  },
  AvgDialog_120297_Content_96 = {
    Text = "Qingqing, mengapa kamu mulai lagi? Aku sudah bilang, hal-hal di luar diriku tidak ada artinya bagiku, hanya kamu, hanya kamu yang harus menjadi milikku."
  },
  AvgDialog_120297_Content_97 = {
    Text = "Aku dipanggil oleh siapa, orang lain tentu hanya akan menjadi angin lalu. Namun, aku masih ingat prestasi besar yang direncanakan oleh siapa, dan bersedia memberikan sedikit tenaga."
  },
  AvgDialog_120297_Content_98 = {
    Text = "Aku melakukan semua ini, hanya ingin memiliki lebih banyak waktu bersandar pada He Lang saat bersama di dunia ini."
  },
  AvgDialog_120297_Content_99 = {
    Text = "Tatapan Xu jelas tidak menunjukkan setetes keikhlasan pun, bahkan anak kecil sepertimu bisa melihatnya, apalagi dia baru saja melempar keluar orang yang seharusnya menerima kasih sayang ini tanpa ampun."
  },
  AvgDialog_120298_Content_1 = {
    Text = "Tidak Mimpi"
  },
  AvgDialog_120298_Content_10 = {
    Text = "Aku berbicara dengan mereka, aroma dirimu terus-menerus menusuk ke dalam rongga hidungku. Begitu memikirkan kedekatanmu dengan pria lain, aku hampir gila!"
  },
  AvgDialog_120298_Content_11 = {
    Text = "Aku sudah bilang, aku hanya butuh kamu di sisiku, kenapa kamu tidak hanya milikku seorang, kenapa kamu masih menggoda pria lain!"
  },
  AvgDialog_120298_Content_12 = {
    Text = "Kamu belum pernah melihat ekspresi kebingungan seperti itu di wajah Xu, seolah-olah dia ingin menemukan cara untuk melarikan diri, tatapannya bergerak liar, dengan terkejut jatuh pada dirimu yang bersembunyi di balik jendela, tidak ditemukan oleh siapa pun."
  },
  AvgDialog_120298_Content_13 = {
    Text = "Kamu secara naluriah bersembunyi di bawah tepi jendela, dan saat menyadari tatapan Xu, kamu menoleh ke belakang sejenak, lalu pandanganmu kembali tertuju padanya."
  },
  AvgDialog_120298_Content_14 = {
    Text = "Masih berpikir bagaimana cara melarikan diri? Menyerahlah, aku adalah <Red: pemanggilmu>, kekuatanmu terhubung denganku, kekuatan ilahimu tidak berpengaruh padaku."
  },
  AvgDialog_120298_Content_15 = {
    Text = "<Red:<Shake:Aku sudah sepenuhnya mengerti, asalkan aku membunuhmu, hanya dengan membunuhmu… kita bisa bersama selamanya.>>"
  },
  AvgDialog_120298_Content_16 = {
    Text = "Kamu menahan napas dan berbalik, segera berlari panik menuju setiap kamar, berusaha menemukan seseorang yang bisa menghentikan apa pun."
  },
  AvgDialog_120298_Content_17 = {
    Text = "Tidak ada, tidak ada, tidak ada. Rumah yang besar ini kosong tanpa seorang pun, bahkan pelayan pintu pun tidak tahu ke mana perginya."
  },
  AvgDialog_120298_Content_18 = {
    Text = "Bahkan pintu gerbang juga dikunci dengan kunci besar, dan kabut abu-abu yang tak berujung menyelimuti di luar."
  },
  AvgDialog_120298_Content_19 = {
    Text = "Jika terus seperti ini, Tuan Xu akan menjadi seperti Ibu..."
  },
  AvgDialog_120298_Content_2 = {
    Text = "Keesokan harinya, sebelum fajar menyingsing, suara teriakan histeris terdengar dari halaman."
  },
  AvgDialog_120298_Content_20 = {
    Text = "<Shake:Kamu harus bersembunyi, sampai segalanya berakhir.>"
  },
  AvgDialog_120298_Content_21 = {
    Text = "Tetapi kamu tidak memiliki tempat untuk pergi, kamu menemukan benda itu, menyembunyikan tanganmu di belakang, dan sekali lagi berjalan menuju kamar yang pernah dimiliki Mama."
  },
  AvgDialog_120298_Content_22 = {
    Text = "<Red:<Shake:Nyonya, sayang, kamu hanya bisa menjadi milikku.>>"
  },
  AvgDialog_120298_Content_23 = {
    Text = "Saat sabit yang bersinar putih terangkat, kamu bertatapan dengan Xu, matanya tiba-tiba bersinar, melintas ekspresi memohon."
  },
  AvgDialog_120298_Content_24 = {
    Text = "Namun segera setelah itu, dia menggelengkan kepala dengan sangat halus—"
  },
  AvgDialog_120298_Content_25 = {
    Text = "<Red:Cepat lari.>"
  },
  AvgDialog_120298_Content_26 = {
    Text = "Mata yang indah itu tertutup, pemiliknya mengangkat lehernya untuk disembelih."
  },
  AvgDialog_120298_Content_28 = {Text = "Aaaahhh!!!"},
  AvgDialog_120298_Content_29 = {
    Text = "Kau ini berani sekali!"
  },
  AvgDialog_120298_Content_3 = {
    Text = "Suara teriakannya terdistorsi, jahat, dan penuh niat buruk, kamu tidak sempat berpikir, suatu ketakutan besar mendorongmu untuk berlari menuju sumber suara."
  },
  AvgDialog_120298_Content_30 = {
    Text = "Sabit jatuh ke tanah, He Fang dengan wajah penuh rasa sakit menutupi pinggang belakangnya, di sana, sebuah pisau kecil yang kamu temukan terbenam dalam tubuhnya."
  },
  AvgDialog_120298_Content_31 = {
    Text = "Dalam kemarahan, He Fang berbalik dan meraih ke arahmu. Tiba-tiba, kamu mendengar suara tawa kecil yang berisik, tidak hanya satu, sumber suara itu mengalir dengan padat menuju ruangan."
  },
  AvgDialog_120298_Content_32 = {
    Text = "Dalam tawa kecil, tawa besar yang tak terhindarkan meledak, Xu di belakang He Fang tertawa terpingkal-pingkal, air mata mengalir."
  },
  AvgDialog_120298_Content_33 = {
    Text = "Ahaha, ahahahahaha, bunga melati kecil, bunga melati kecil yang paling paling paling aku cintai. Ternyata kamu tidak mengecewakanku—kamu memang se menarik yang aku pikirkan!"
  },
  AvgDialog_120298_Content_34 = {
    Text = "Wanita-wanita yang mengenakan qipao kuning dan hitam masuk berbaris, kipas lipat menutupi hidung dan bibir mereka, setiap orang dari mereka — memiliki sepasang mata yang sangat, sangat indah."
  },
  AvgDialog_120298_Content_35 = {
    Text = "Di mana ketakutan yang luar biasa, sebelum teriakan mengerikan itu muncul, sebuah pelukan yang dingin dan lembut telah muncul, membungkusmu di dalamnya."
  },
  AvgDialog_120298_Content_36 = {
    Text = "<Red:Benda menjijikkan, jangan kotorin mata melati kecilku.>"
  },
  AvgDialog_120298_Content_37 = {
    Text = "<Shake:Tuan…>"
  },
  AvgDialog_120298_Content_38 = {
    Text = "<Shake:Tuan…>"
  },
  AvgDialog_120298_Content_39 = {
    Text = "Apa yang kalian lakukan, sudah gila?! Pergi, semua pergi dari sini."
  },
  AvgDialog_120298_Content_4 = {
    Text = "Xu terpojok di sudut tempat tidur oleh He Fang, yang matanya merah darah, rambutnya berantakan, seolah-olah tidak tidur semalaman."
  },
  AvgDialog_120298_Content_40 = {
    Text = "Ibu-ibu di depan mata, perlahan-lahan menggeser permukaan kipas, di bawah setiap kipas, muncul wajah yang sama."
  },
  AvgDialog_120298_Content_41 = {
    Text = "Mengapa Tuan menjadikan kami sebagai korban persembahan?"
  },
  AvgDialog_120298_Content_42 = {
    Text = "Mengapa Tuan memotong anggota badan kami?"
  },
  AvgDialog_120298_Content_43 = {
    Text = "Tak terhitung banyaknya suara kemarahan Xu yang bergetar terhadap He Fang, tanpa disadari, mereka tertawa riang dan mengelilingi He Fang di tengah, kipas hitam dan sabit berselang-seling membentuk lingkaran dengan dia sebagai pusatnya."
  },
  AvgDialog_120298_Content_44 = {
    Text = "<Change>Apakah kita sekarang cukup cantik?"
  },
  AvgDialog_120298_Content_45 = {
    Text = "<Change>Bisakah kita sekarang selamanya bersama Tuan?"
  },
  AvgDialog_120298_Content_46 = {
    Text = "Siluet raksasa melesat dari belakang Xu, satu, dua, tiga… jumlah yang tak terhitung, dengan bibir bercakar naga yang menyembul dari kulitnya yang gemuk, meneteskan air liur, berniat memilih orang untuk dilahap,"
  },
  AvgDialog_120298_Content_47 = {
    Text = "Sisir berbulu merentang ke seluruh rumah He, semua cahaya tertutup, semua kebisingan menghilang."
  },
  AvgDialog_120298_Content_48 = {
    Text = "Pandanganmu diselimuti oleh kabut, kamu hanya merasakan aroma aneh dari Xu, serta suara makan yang aneh, lambat, dan memuaskan."
  },
  AvgDialog_120298_Content_5 = {
    Text = "Anak perempuanku yang bodoh itu tidak salah dalam satu hal... aku menciumnya."
  },
  AvgDialog_120298_Content_50 = {
    Text = "Setelah suara hisapan yang berkelanjutan berhenti, He Fang dengan diam-diam berdiri dan berjalan keluar, berdiri di antara sekelompok pria yang juga menunggu dengan diam."
  },
  AvgDialog_120298_Content_51 = {
    Text = "Pengawas, presiden, ketua… istri mereka berdiri di samping para pria, sinar matahari yang baru terbit membuatmu terpesona, kamu melihat senyuman misterius yang sama seperti Xu terlukis di wajah mereka."
  },
  AvgDialog_120298_Content_53 = {
    Text = "Siapa yang berkata, kekuatanmu terhubung dengannya, jadi sekarang dia menjadi seperti ini, apakah kamu akan menghilang?"
  },
  AvgDialog_120298_Content_54 = {
    Text = "Jasmine kecil ternyata ingin bertanya tentang ini, sungguh... membuatku sangat tersentuh."
  },
  AvgDialog_120298_Content_55 = {
    Text = "Jarinya mengusap di antara alismu, lalu berhenti di ujung hidungmu."
  },
  AvgDialog_120298_Content_56 = {
    Text = "Mungkin iya, atau mungkin... tidak, tapi, apakah kamu mau menjadi tuan hamba?"
  },
  AvgDialog_120298_Content_57 = {
    Text = "Xu dengan lembut mengayunkan tangannya di udara, menangkap sehelai kain sutra tipis seperti sayap belalang, mencelupkan kuas perak ke udara, mewarnainya dengan tinta hitam, dan membentangkannya di hadapanmu."
  },
  AvgDialog_120298_Content_58 = {
    Text = "Aku akan memberikan kepadamu apa yang tidak didapatkan oleh siapa pun, serta yang terbaik di dunia."
  },
  AvgDialog_120298_Content_59 = {
    Text = "Ibu masih hidup, Hai Cheng mengangkat semangat baru, kamu adalah orang yang pernah belajar dan menulis."
  },
  AvgDialog_120298_Content_6 = {
    Text = "<Shake:<Red:Orang-orang pria itu…>>"
  },
  AvgDialog_120298_Content_60 = {
    Text = "Xu sudah menggenggam tanganmu, tunggu kamu mulai menulis, kamu... siapa namanya?"
  },
  AvgDialog_120298_Content_61 = {
    Text = "Cermin tembaga yang terkena percikan cairan merah segar, memantulkan wajah seorang pemuda dari Timur Jauh yang halus dan muda, seperti sekuntum melati yang pucat dan rapuh."
  },
  AvgDialog_120298_Content_62 = {
    Text = "Kamu berkedip dengan bingung, gadis kecil dalam bayangan juga berkedip. \n Kamu teringat, tulisan kekanak-kanakanmu muncul di atas kain sutra, namamu adalah——"
  },
  AvgDialog_120298_Content_63 = {Text = "He Fang."},
  AvgDialog_120298_Content_65 = {
    Text = "Jadi, pemimpin organisasi bawah tanah yang muncul di Kota Laut itu adalah seorang gadis kecil yang seukuran dengan Jenkin?!"
  },
  AvgDialog_120298_Content_66 = {
    Text = "Kepalamu terasa sangat sakit karena efek samping dari mimpi, dan kamu terkejut oleh wanita yang muncul tiba-tiba setelah terbangun."
  },
  AvgDialog_120298_Content_67 = {
    Text = "Asrama Mythag benar-benar harus menambahkan beberapa langkah keamanan. Dengan pemikiran itu, kamu mulai memikirkan benda apa yang mungkin bisa melindungimu dari wanita yang bahkan tidak menyisakan anak kecil."
  },
  AvgDialog_120298_Content_68 = {
    Text = "……Menurut catatan, dalam legenda Timur Jauh, terdapat sebuah dewa jahat kuno yang disebut <Red:\"Seribu Kipas Xuan Nü\">, Ia suka bermain dengan hati manusia dan memakan otak orang-orang yang memiliki keinginan terhadap-Nya."
  },
  AvgDialog_120298_Content_69 = {
    Text = "Bahkan jika hanya bisa melihat matanya, jelas sekali kamu tahu wanita di depanmu sedang tersenyum bahagia. Dia bersandar malas dengan dagunya, dan kamu sangat meragukan apakah tatapannya bisa membuat selembar kain pel pun terlihat penuh perasaan."
  },
  AvgDialog_120298_Content_7 = {
    Text = "Kau pikir bisa menipuku? Jangan lupakan, akulah yang membangkitkanmu dengan tubuh istriku sendiri <Red:\"mayat\">, bagaimana mungkin aku salah mengenali aroma itu?"
  },
  AvgDialog_120298_Content_70 = {
    Text = "Anda begitu memahami diriku, benar-benar membuatku sangat senang."
  },
  AvgDialog_120298_Content_71 = {
    Text = "Pria bodoh itu, mendapatkan sebuah gulungan buku kuno, berniat memanggil diriku untuk melakukan sihir penipuan, telah membunuh entah berapa banyak orang, dan pada akhirnya, bahkan tidak melewatkan istri sah yang mencintainya sepenuh hati."
  },
  AvgDialog_120298_Content_72 = {
    Text = "Sebenarnya, hanya saja kebencian istri dia yang membuatku merasa menarik, ingin mencicipi musuhnya untuknya."
  },
  AvgDialog_120298_Content_73 = {
    Text = "Namun pada saat itu, kota laut dipenuhi dengan bau busuk dan niat jahat yang menyengat, sungguh membuat hamba… enggan pergi."
  },
  AvgDialog_120298_Content_74 = {
    Text = "……kamu sebenarnya tidak perlu penghubung, kan?"
  },
  AvgDialog_120298_Content_75 = {
    Text = "Aku telah membaca \"Catatan Penyimpanan Perak\", kamu sepenuhnya mampu menyelesaikan Upacara Pemanggilan sendiri, menjaga akal sehat bagimu adalah hal yang sangat mudah."
  },
  AvgDialog_120298_Content_76 = {
    Text = "Apa tujuanmu menghubungi He Fang di Haicheng secara aktif?"
  },
  AvgDialog_120298_Content_77 = {
    Text = "Xu tidak berkata apa-apa, seberkas kabut melingkari dirimu, secara perlahan menghilangkan rasa nyeri di kepalamu, dia yang berada di balik kipas, mengedipkan matanya padamu."
  },
  AvgDialog_120298_Content_78 = {
    Text = "Aku awalnya berpikir, di dunia ini, tidak ada perbedaan antara orang dewasa dan orang dewasa, tetapi setiap anak memiliki perbedaan masing-masing."
  },
  AvgDialog_120298_Content_79 = {
    Text = "Aku membesarkannya dengan kabut, menyiramnya dengan hasrat kekuasaan, aku mencintainya, mengapa Anda masih menghukumku?"
  },
  AvgDialog_120298_Content_8 = {
    Text = "Jika bukan karena kamu telah bersenang-senang dengan mereka, mengapa mereka mengeluarkan aroma yang menjadi milik <Red:mu>?"
  },
  AvgDialog_120298_Content_80 = {
    Text = "Itu bukan cinta"
  },
  AvgDialog_120298_Content_82 = {
    Text = "Hehe, saya memang tidak mengerti apa itu cinta manusia. Makanan, mainan, dan kekuasaan yang salah, saya akan mempersembahkan hadiah-hadiah terbaik di dunia ini."
  },
  AvgDialog_120298_Content_83 = {
    Text = "Tentu saja... Aku juga akan mendapatkan imbalan yang kuinginkan. Ketika hari itu tiba, Bunga Melati Kecil, bagaimana kamu akan memilih?"
  },
  AvgDialog_120298_Content_84 = {
    Text = "Tempat mimpiku, kapan saja, aku selalu bersedia menunggu kedatanganmu."
  },
  AvgDialog_120298_Content_85 = {
    Text = "Dengan lembut, suara tawa kecil yang manja, kabut menyebar - dalam sekejap, hanya aroma magnolia putih yang tersisa di dalam asrama."
  },
  AvgDialog_120298_Content_9 = {
    Text = "Dia tiba-tiba tertawa dengan gelisah, membungkuk ke depan, dan menangkap pergelangan tangan Xu yang memegang kipas."
  },
  AvgDialog_120313_Content_1 = {
    Text = [[
Sementara itu
 di luar Matahari Hitam]]
  },
  AvgDialog_120313_Content_10 = {
    Text = "Di luar dunia yang berkilau seperti bintang, sosok itu berjuang melewati arus yang berat, langkah demi langkah mendekati dirimu."
  },
  AvgDialog_120313_Content_11 = {Text = "Ramona!!!"},
  AvgDialog_120313_Content_12 = {
    Text = "Kamu melihat kontur wajahnya, wajahnya, dan mata yang bersinar karena kebahagiaan, tidak lagi menjadi ilusi yang palsu, tidak lagi hanya suara yang samar."
  },
  AvgDialog_120313_Content_13 = {
    Text = "Gelombang energi dari terowongan menerpa rambutmu, akhirnya, ujung jari kalian bertemu, lalu saling berpelukan erat."
  },
  AvgDialog_120313_Content_14 = {
    Text = "Kerinduan dari dunia lain berubah menjadi cahaya putih, berputar mengalir melalui jiwamu."
  },
  AvgDialog_120313_Content_15 = {
    Text = "<Shake:<color=#DEDEDE>Akhirnya…… menemukanmu.</color>>"
  },
  AvgDialog_120313_Content_16 = {
    Text = "Kalian saling berdekatan, tangannya memeluk erat punggungmu, suaranya bergetar karena sangat bahagia."
  },
  AvgDialog_120313_Content_17 = {
    Text = "Semua kelelahan, kesepian, dan rasa sakit lenyap pada saat ini, kau tahu, jiwamu telah kembali ke tempat yang sebenarnya."
  },
  AvgDialog_120313_Content_18 = {
    Text = "Perjalanan antar dimensi cukup berbahaya, bukan? Apakah kamu terluka?"
  },
  AvgDialog_120313_Content_19 = {
    Text = "Kau mengingat sesuatu, memeriksa kembali jiwa yang telah berjuang lama di depanmu, hanya melihat sosoknya yang agak kurus. Ramona menggelengkan kepala, lembut mengelus wajahmu."
  },
  AvgDialog_120313_Content_2 = {
    Text = "Kedatangan, Kehancuran, Kelahiran ulang… perlawanan, pertempuran, bertahan…"
  },
  AvgDialog_120313_Content_20 = {
    Text = "Bagaimana denganmu? Sendirian di dunia yang asing begitu lama, kau pasti berjuang keras."
  },
  AvgDialog_120313_Content_21 = {
    Text = "Hidungmu terasa asam, kau juga menggelengkan kepala, dalam tatapan saling berhadapan, dalam tetes air mata yang menggantung di matamu, kalian tersenyum bersamaan."
  },
  AvgDialog_120313_Content_22 = {
    Text = "Kenapa kamu tertawa, seperti orang bodoh."
  },
  AvgDialog_120313_Content_23 = {
    Text = "Kamu juga sedang tertawa, bukan…"
  },
  AvgDialog_120313_Content_24 = {
    Text = "Dalam kebahagiaan yang besar, kamu tidak bisa menahan menggenggam tangannya, ingin segera pulang."
  },
  AvgDialog_120313_Content_25 = {Text = "!!!"},
  AvgDialog_120313_Content_26 = {
    Text = "Tiba-tiba, Anda melihat pupilnya menyempit dengan cepat, sekejap kemudian, dia melompat ke arah Anda dan mendorong Anda dengan keras ke samping."
  },
  AvgDialog_120313_Content_27 = {
    Text = "Di saat terbang mundur, kau melihat tempat yang awalnya di belakangmu, di dalam celah dimensi baru, sebuah mata lainnya berputar membuka, memperhatikan Ramona yang tertinggal di tempat."
  },
  AvgDialog_120313_Content_28 = {
    Text = "Dalam sekejap, racun gelap menelannya."
  },
  AvgDialog_120313_Content_29 = {
    Text = "<Shake:<Big:Tidak！！！>>"
  },
  AvgDialog_120313_Content_3 = {
    Text = "Di bawah tekanan Kehendak tertinggi itu, segalanya terasa begitu akrab."
  },
  AvgDialog_120313_Content_4 = {
    Text = "Mata besar berwarna putih yang raksasa di dimensi lain satu per satu menghilang dengan suara keras, jiwamu juga perlahan menuju kekeringan, yang tersisa untuk menopangmu hanyalah mawar merah yang kau genggam."
  },
  AvgDialog_120313_Content_5 = {
    Text = "Huh... tidak boleh jatuh, mereka masih menunggu saya..."
  },
  AvgDialog_120313_Content_6 = {
    Text = "Dalam keadaan bingung, jantungmu tiba-tiba mulai berdebar kencang, kamu mengikuti firasat ini dan menoleh."
  },
  AvgDialog_120313_Content_7 = {
    Text = "Seolah meteor melintas, atau siraman kristal es, terowongan bercahaya dengan suara aneh dan ethereal membentang ke arah sana."
  },
  AvgDialog_120313_Content_8 = {
    Text = "Sebuah suara yang telah bergema dalam ingatan ribuan kali melewati ruang dimensi yang jauh di belakangmu, bergema dalam pikiranmu di bawah tautan tentakel spiritual."
  },
  AvgDialog_121232_Content_1 = {
    Text = "Cahaya tanah air telah berkilauan di depan mata saya, Tuan Goliath, sekarang serahkan padamu…"
  },
  AvgDialog_121232_Content_2 = {
    Text = "Kekuatan ilahi yang mengalir... mengingatkanku pada perempuan gila itu."
  },
  AvgDialog_121232_Content_3 = {
    Text = "Baiklah, anak kecil di sana, sekarang bersiap-siap untuk melihat kekuatan Perishite yang melampaui berkah!"
  },
  AvgDialog_121369_Content_1 = {
    Text = "Di aula yang kosong, hanya langkahmu dan murphy yang bergema."
  },
  AvgDialog_121369_Content_10 = {
    Text = "Tidak sempat menjernihkan situasi, anggota tangan dingin melilit kakimu, kekuatan raksasa mendorongmu berlutut ke bawah."
  },
  AvgDialog_121369_Content_11 = {
    Text = "Kau mencoba melawan, tetapi racun paralisis menyusup ke dalam sarafmu, membuatmu tidak bisa bergerak."
  },
  AvgDialog_121369_Content_12 = {
    Text = "Murphy, apa yang kau lakukan?!"
  },
  AvgDialog_121369_Content_13 = {
    Text = "Entah kenapa, terasa sangat marah."
  },
  AvgDialog_121369_Content_14 = {
    Text = "Ada api yang membara di dalam hati, ketika melihatmu api itu semakin berkobar."
  },
  AvgDialog_121369_Content_15 = {
    Text = "(Tenanglah, tenanglah. Tidak boleh melakukan hal-hal yang merugikan kewibawaan Dewi.)"
  },
  AvgDialog_121369_Content_16 = {
    Text = "Jadi... biarkan saya berlutut di sini untuk apa sebenarnya?"
  },
  AvgDialog_121369_Content_17 = {
    Text = "Biarkan kamu berlutut, jangan tanya!"
  },
  AvgDialog_121369_Content_18 = {
    Text = "Nada suara Murphy terdengar masih marah, tentakel gurita bergetar di kaki Anda gelisah. Sepertinya hanya bisa mengandalkan diri sendiri."
  },
  AvgDialog_121369_Content_19 = {
    Text = "Kau memberontak mengatasi kekuatan racun paralisis sambil mengangkat kepala, menyentuh pipinya yang memerah."
  },
  AvgDialog_121369_Content_2 = {
    Text = "Sejak tadi, kau tak ingin berkata apa pun."
  },
  AvgDialog_121369_Content_20 = {
    Text = "Murphy, apakah kau... terganggu oleh kekuatan Sungai Suci?"
  },
  AvgDialog_121369_Content_21 = {
    Text = "Sombong! Saya adalah ibu dari para dewa, bagaimana mungkin saya terpengaruh oleh kebodohan seperti ini…"
  },
  AvgDialog_121369_Content_22 = {
    Text = "Lengan biru menjalar di punggungmu, di mana pun mereka pergi semuanya terasa gatal."
  },
  AvgDialog_121369_Content_23 = {
    Text = "Sebelum pagi tiba, tetaplah di sini dengan baik."
  },
  AvgDialog_121369_Content_24 = {
    Text = "Jangan bergerak!"
  },
  AvgDialog_121369_Content_25 = {
    Text = "Namun kau merasa belenggu yang mengikatmu menjadi sedikit longgar, seolah-olah awan mengangkatmu, tapi saat kau mencoba untuk merobek, mereka tidak mengizinkanmu bergerak sedikit pun."
  },
  AvgDialog_121369_Content_26 = {
    Text = "Bersyukurlah, kamu akan mendapatkan kehormatan untuk menyambut fajar bersama Ibu Dewa."
  },
  AvgDialog_121369_Content_27 = {
    Text = "Sebagai balasannya…"
  },
  AvgDialog_121369_Content_28 = {
    Text = "Suara napasnya bergetar di telingamu. Dan kemudian, sebuah ciuman lembut, jatuh di dahimu."
  },
  AvgDialog_121369_Content_29 = {
    Text = "Kau juga akan menerima anugerah dari Sang Ibu."
  },
  AvgDialog_121369_Content_3 = {
    Text = "Apa yang terjadi, Murphy?"
  },
  AvgDialog_121369_Content_4 = {
    Text = "Murphy tidak menjawab, hanya berjalan lurus menuju puncak tangga, tempat takhta berada."
  },
  AvgDialog_121369_Content_5 = {
    Text = "Kau melangkah mengikuti setiap gerakannya, sampai dia akhirnya duduk di atas Takhta, tatapannya sedikit marah menusukmu."
  },
  AvgDialog_121369_Content_6 = {
    Text = "Siapa yang mengizinkanmu berdiri di sampingku? Turunlah, tidak boleh menatapku."
  },
  AvgDialog_121369_Content_7 = {
    Text = "Kau tidak mengerti, tetapi tetap mundur dua langkah, pandanganmu sejajar dengan gadis di atas Takhta."
  },
  AvgDialog_121369_Content_8 = {Text = "Berlutut."},
  AvgDialog_121369_Content_9 = {Text = "Hah?"},
  AvgDialog_121741_Content_1 = {
    Text = "Besar, busuk, kosong... dengan fantasi absurd menjaga ilusinya di atas \"tirai\"..."
  },
  AvgDialog_121741_Content_2 = {
    Text = "Saya yang tenggelam dalam \"Surga\", betapa bodoh dan konyolnya..."
  },
  AvgDialog_121741_Content_3 = {
    Text = "%player%，bantu aku mengakhiri mimpi ini sepenuhnya."
  },
  AvgDialog_121741_Content_4 = {
    Text = "Bantu aku merebut kembali... takdirku."
  },
  AvgDialog_121742_Content_1 = {
    Text = "Rantai bergetar, monster di balik tirai mengamati seluruh kapal dengan tatapan penuh kebingungan, mengeluarkan jeritan putus asa."
  },
  AvgDialog_121742_Content_10 = {
    Text = "Selamat tinggal, \"kemarin\" yang rapuh dan tak berdaya...!"
  },
  AvgDialog_121742_Content_2 = {
    Text = "Aku mengerti... aku mengerti... kerinduanmu, hal yang tidak bisa kau lepaskan..."
  },
  AvgDialog_121742_Content_3 = {
    Text = "Namun aku sudah mengambil keputusan."
  },
  AvgDialog_121742_Content_4 = {
    Text = "Murphy menatap-Nya, kemudian, setelah beberapa saat, seperti telah memutuskan, ia menunjukkan senyuman lembut padamu."
  },
  AvgDialog_121742_Content_5 = {
    Text = "Tolong lihatlah... hati di dada saya..."
  },
  AvgDialog_121742_Content_6 = {
    Text = "Hingga hari ini, tetap bergerak dengan segar."
  },
  AvgDialog_121742_Content_7 = {
    Text = "Seperti saat upacara navigasi, Murphy membelah dadanya sendiri."
  },
  AvgDialog_121742_Content_8 = {
    Text = "Untuk meninggalkan tempat ini, demi hari kita bertemu kembali di Mythag."
  },
  AvgDialog_121742_Content_9 = {
    Text = "Darah spiritual mengalir dari dada Murphy, benang perak samar yang terjerat, berjuang untuk membuka tirai di langit."
  },
  AvgDialog_121743_Content_1 = {
    Text = "Kamu tidak tahu sudah berapa lama kamu bertarung, hanya merasa pusing di kepala, dan lengan mulai berat, namun makhluk raksasa yang pucat dan kurus itu terus mengayunkan lengannya yang patah dan terlahir kembali tanpa lelah."
  },
  AvgDialog_121743_Content_10 = {
    Text = "Janji William bagaikan benteng tak terlihat dibangun di belakang, rasa percaya yang ditempa selama bertahun-tahun mengalirkan kekuatan baru dari dalam saraf tulangnya."
  },
  AvgDialog_121743_Content_11 = {
    Text = "Kita telah berjanji, kita akan kembali bersama."
  },
  AvgDialog_121743_Content_12 = {
    Text = "Semoga Kunci Perak menuntun jalanmu."
  },
  AvgDialog_121743_Content_13 = {
    Text = "Semoga Kunci Perak membimbing kita."
  },
  AvgDialog_121743_Content_2 = {
    Text = "Keringat mengalir dari dahi Anda, mengaburkan pandangan, tetapi Anda bahkan sulit mengangkat tangan untuk menghapusnya."
  },
  AvgDialog_121743_Content_3 = {Text = "Sialan..."},
  AvgDialog_121743_Content_4 = {
    Text = "%player%，bertahanlah."
  },
  AvgDialog_121743_Content_5 = {
    Text = "Jubah hitam merah melayang di depan mata, lengan mekanik yang rumit melindungi Anda dari serangan tulang yang pucat."
  },
  AvgDialog_121743_Content_6 = {
    Text = "Seperti tentakel yang panjang menghantam dengan marah, tertahan lagi, pecahan menghantam di sisi Anda, menghasilkan asap terbang."
  },
  AvgDialog_121743_Content_7 = {Text = "William?"},
  AvgDialog_121743_Content_8 = {
    Text = [[
Fokuslah, lihat pada-Nya.
Serahkan belakangmu padaku.]]
  },
  AvgDialog_121743_Content_9 = {
    Text = [[
Di dunia yang baru... Aku akan sementara menggantikan tugas pasangan di sisimu.
Hingga hari kita kembali ke Mythag bersama.]]
  },
  AvgDialog_121744_Content_1 = {
    Text = "Makhluk itu meraung, berteriak, dan tirai yang menutupi pecah, Tubuhnya muncul dari dasar aequor."
  },
  AvgDialog_121744_Content_10 = {
    Text = "Tidak menguasai penggunaan kekuatan dengan baik dan menyerahkan takdir kepada orang lain, itu bukanlah cara Perishite."
  },
  AvgDialog_121744_Content_11 = {
    Text = "Raksasa itu mengayunkan senjatanya, mengarahkan ujung pedangnya ke daging besar yang sedang berubah bentuk."
  },
  AvgDialog_121744_Content_12 = {
    Text = "Jadi, tidak perlu bicara lagi, bersiaplah untuk pertempuran!"
  },
  AvgDialog_121744_Content_13 = {
    Text = "Hanya pemenang yang berhak untuk hidup."
  },
  AvgDialog_121744_Content_2 = {
    Text = "Sial...! Dia masih berkembang!"
  },
  AvgDialog_121744_Content_3 = {
    Text = "Sebuah kilat membelah langit malam yang gelap, pedang raksasa yang haus darah dengan cepatnya menyambar ke anggota tubuh yang pucat lemah di balik tirai."
  },
  AvgDialog_121744_Content_4 = {
    Text = "...Miryam? Goliath? Kenapa kalian ada di sini?"
  },
  AvgDialog_121744_Content_5 = {
    Text = "Keputusan Dewi sudah dibuat, kita harus membiarkan Dewi memotong \"tirai\" yang berat ini."
  },
  AvgDialog_121744_Content_6 = {Text = "Miriam…"},
  AvgDialog_121744_Content_7 = {
    Text = "Tenanglah, Ibu Dewa. Apa pun rencana Anda di masa depan, Pelaut adalah landasan kuat dan setia di belakang Anda."
  },
  AvgDialog_121744_Content_8 = {
    Text = "Berhentilah berbicara tumpang tindih, apakah kita akan melihat kalian berdua menghadapi makhluk ini dengan tangan kosong?"
  },
  AvgDialog_121744_Content_9 = {
    Text = "Suara yang dikenal tiba-tiba muncul, memutuskan kata-kata Murphy. Itu adalah Goliath dan Caecus."
  },
  AvgDialog_121745_Content_1 = {
    Text = "Makhluk tinggi menjulang itu mengangkat kepala dengan penuh kebanggaan, dari balik tirai yang redup, \"memperhatikan\" kalian semua."
  },
  AvgDialog_121745_Content_10 = {
    Text = "Tolong kamu dan yang seperti saya... selamanya dikubur dalam aequor yang tak berujung!"
  },
  AvgDialog_121745_Content_2 = {Text = "……!!!"},
  AvgDialog_121745_Content_3 = {
    Text = "Sebuah tautan tak terlihat benar-benar menembus di antara dia dan Dia, tak bisa dihindari, membuat gadis itu melihat luka-luka, tangisan, bahkan kebingungan-Nya..."
  },
  AvgDialog_121745_Content_4 = {
    Text = "Seperti bayi yang disakiti, menanyakan \"penghianatan\" ibunya."
  },
  AvgDialog_121745_Content_5 = {
    Text = "Jangan lihat aku, jangan tanya aku... Aku sudah memutuskan. Ini adalah \"penghianatan\" terakhirku."
  },
  AvgDialog_121745_Content_6 = {
    Text = "Dulu, saya membuat harapan kepada \"Surga\", sebuah \"fantasi\" yang saya dambakan di masa muda saya."
  },
  AvgDialog_121745_Content_7 = {
    Text = "Kupikir \"otoritas\" bisa memberiku \"kebahagiaan,\" tapi ini semua hanya mimpi kosong..."
  },
  AvgDialog_121745_Content_8 = {
    Text = "Murphy tersenyum sambil menghapus air mata di sudut matanya. Dia perlahan dan dengan hati-hati menyeka, sampai bekas air mata terakhir menghilang sepenuhnya. Dia menatap ke atas, melihat \"diri\" yang besar."
  },
  AvgDialog_121745_Content_9 = {
    Text = "Aku tidak butuh surga, tidak perlu mimpi indah yang menipu diri sendiri. Tidak lagi dibutuhkan."
  },
  AvgDialog_121858_Content_1 = {
    Text = [[
Dari bawah kaki-Nya meluap ribuan monster, dan kalian membunuh satu per satu. 
 Menginjak ribuan mayat, kalian tiba di bawah kaki siluet raksasa.]]
  },
  AvgDialog_121858_Content_10 = {
    Text = "Kali ini, aku tidak akan membiarkan kemenangan diperoleh dengan mengorbankan nyawa siapapun."
  },
  AvgDialog_121858_Content_11 = {
    Text = "Siapkan diri untuk bertempur, \"tirai\" yang akan layu!"
  },
  AvgDialog_121858_Content_2 = {
    Text = "Inilah kehendakku, kehendak \"Surga\"..."
  },
  AvgDialog_121858_Content_3 = {
    Text = "\"Anak\" tidak pernah menjadi milik \"Ibu\", setelah dilahirkan, Dia juga memiliki \"keinginan\"-nya sendiri."
  },
  AvgDialog_121858_Content_4 = {
    Text = "<Red:Mimpi... harus... berlanjut...>"
  },
  AvgDialog_121858_Content_5 = {
    Text = "Kamu pernah berkata, selama membunuh penguasa mimpi, serahkan kekuasaan padamu..."
  },
  AvgDialog_121858_Content_6 = {
    Text = "Ya. Apakah kamu sudah membuat kesadaran?"
  },
  AvgDialog_121858_Content_7 = {
    Text = "Tidak, dia tidak perlu berkorban seperti itu."
  },
  AvgDialog_121858_Content_8 = {
    Text = "…%player%!"
  },
  AvgDialog_121858_Content_9 = {
    Text = "\"Nukleus\" dari Domain, \"bencana\" yang muncul, skala seperti ini, aku sudah tidak ingat berapa kali aku menghadapi pertarungan ini."
  },
  AvgDialog_121859_Content_1 = {
    Text = "Kekuatan yang Dia berikan di dalam tirai... sedang berubah..."
  },
  AvgDialog_121859_Content_2 = {
    Text = "Terbuang, ditinggalkan... Dia berada dalam ketidakpuasan, kemarahan, dan ratapan..."
  },
  AvgDialog_121859_Content_3 = {
    Text = "Kemarahan-Nya akan tercurah kepada kalian...!"
  },
  AvgDialog_121864_Content_1 = {
    Text = "Apakah ini mengejutkan? Karena wahyu memanggilku, di balik tirai..."
  },
  AvgDialog_121865_Content_1 = {
    Text = "Darahku sedang berdenyut, lautan dalam bersenandung mengundangku!"
  },
  AvgDialog_121866_Content_1 = {
    Text = "Dewa yang jauh, hamba setia Anda akan mempersembahkan sedikit kekuatan untuk Anda..."
  },
  AvgDialog_121867_Content_1 = {
    Text = "Orang beruntung, ini akan memperlihatkan kekuatan Perishite!"
  },
  AvgDialog_122640_Content_1 = {
    Text = "<Shake:Boom!——>"
  },
  AvgDialog_122640_Content_2 = {
    Text = "Tatapan gila membuat seluruh dimensi mulai bergetar, tautan antara Ramona dan kamu tertutup oleh Pelarutan, menghilang tanpa jejak."
  },
  AvgDialog_122640_Content_3 = {
    Text = "Kamu menarik napas dalam-dalam, memaksa menekan kegelisahan yang muncul akibat kegilaan di dalam hati."
  },
  AvgDialog_122640_Content_4 = {
    Text = "Biarkan kegilaan ini untuk dirimu sendiri...<Big:Aku tidak akan membiarkan kegilaanmu ini, menyakiti siapa pun lagi!>"
  },
  AvgDialog_122641_Content_1 = {Text = "...@3!!..."},
  AvgDialog_122641_Content_2 = {
    Text = "Tekanan yang akrab. Tatapan yang akrab. Rasa sakit yang akrab hampir merobek otakmu."
  },
  AvgDialog_122641_Content_3 = {
    Text = "Heh... kita bertemu lagi, Tohuwabohu, Tuhan yang Maha Tinggi... meskipun kau tidak bisa mendengar, tetapi aku harus berterima kasih padamu."
  },
  AvgDialog_122641_Content_4 = {
    Text = "Kamu pernah membuatku mati sekali, dalam kematian ini, aku memahami sebuah kebenaran yang mendalam…"
  },
  AvgDialog_122641_Content_5 = {
    Text = "Kamu menggenggam kunci perak erat-erat, menatap tatapan kehendak-Nya. Bahkan kamu sendiri tidak menyadari, sudut bibirmu menyunggingkan senyuman."
  },
  AvgDialog_122641_Content_6 = {
    Text = "Kau membuatku tahu, di dalam mimpi agungmu ini, tidak ada yang tidak dapat diubah, tidak ada yang tidak dapat dikalahkan."
  },
  AvgDialog_122641_Content_7 = {
    Text = "Untuk bertemu lagi, kami sudah menunggu lama... Bahkan kamu, jangan harap bisa menghalangi jalan kami!"
  },
  AvgDialog_122642_Content_1 = {
    Text = "……@2……@2……@1@3……!!"
  },
  AvgDialog_122642_Content_2 = {
    Text = "Guncangan yang kuat membuat seluruh dimensi mulai hancur. Kamu membuka mata merahmu, memandang ke arah pupil yang semakin mendekati wujud."
  },
  AvgDialog_122642_Content_3 = {
    Text = "Kesadaranmu juga sudah mencapai batas, Tuhuwa Bo... Sekarang, tidurlah dengan tenang!"
  },
  AvgDialog_122642_Content_4 = {
    Text = "Kamu mengumpulkan semangatmu yang hampir habis, dan menuangkan kekuatan roh terakhir ke dalam kunci perak."
  },
  AvgDialog_122642_Content_5 = {
    Text = "Kamu menggenggam cahaya perak seperti pisau tajam, menusuk ke arah dewa di depanmu——"
  },
  AvgDialog_122643_Content_1 = {
    Text = "<Big:<Shake:ramona！！！>>"
  },
  AvgDialog_122643_Content_2 = {
    Text = "Sosok yang familiar ditelan oleh pengikisan yang dibawa oleh tatapan, mantra kuno dan jahat samar-samar muncul dalam tatapan ini."
  },
  AvgDialog_122643_Content_3 = {
    Text = "Ini adalah pembacaan yang cukup sampai di sini…!"
  },
  AvgDialog_122644_Content_1 = {
    Text = "Dunia runtuh dan dibangun kembali di depanmu, orang terdekatmu mati dan hidup kembali di hadapanmu. Tatapan yang membingungkan itu membawa semua kekacauan alam semesta ke dalam jiwamu."
  },
  AvgDialog_122644_Content_2 = {
    Text = "Ketidakteraturan, kekacauan, kebingungan... apa yang dibawa oleh kekuasaanmu tetaplah hal-hal ini."
  },
  AvgDialog_122644_Content_3 = {
    Text = "Tatapanmu tidak pernah membingungkan saya, Tuhuwa Bo. Dulu begitu, sekarang juga demikian."
  },
  AvgDialog_122644_Content_4 = {
    Text = "Cahaya perak bersinar. Di antara ilusi yang tak berujung itu, kamu menemukan jalan untuk melawan itu —"
  },
  AvgDialog_122645_Content_1 = {
    Text = "Di dimensi yang jauh, sebuah titik cahaya sedang berkedip-kedip."
  },
  AvgDialog_122645_Content_2 = {
    Text = "Itu adalah... \"Hati Suci\" Pollux?"
  },
  AvgDialog_122645_Content_3 = {
    Text = "Pencarian mereka juga sudah dimulai... sekarang, mereka pasti juga dalam bahaya."
  },
  AvgDialog_122645_Content_4 = {
    Text = "Aku masih ingat ketakutan saat pertama kali menghadapi kamu, Tuhuwa Bo. Kali ini, aku tidak akan membiarkan mereka menunggu terlalu lama!"
  },
  AvgDialog_122646_Content_1 = {
    Text = "Rasa sakit yang tajam menyerang setiap tulangmu, setiap inci dagingmu. Kamu menahan rasa sakit yang menyiksa ini, tersenyum dengan susah payah."
  },
  AvgDialog_122646_Content_2 = {
    Text = "Dewa yang bodoh, kamu tidak tahu, di dalam mimpimu, ada banyak penderitaan yang jauh melampaui tubuh..."
  },
  AvgDialog_122646_Content_3 = {
    Text = "Sakit seperti itu, saya tidak akan membiarkannya muncul lagi!"
  },
  AvgDialog_122694_Content_1 = {
    Text = "Pintu di tengah koridor sudah tertutup embun beku, bahkan ada kecenderungan menyebar ke luar."
  },
  AvgDialog_122694_Content_10 = {
    Text = "Tolong, Penjaga, peluklah aku, sedikit saja, hanya sedikit kehangatan sudah cukup~ Peri ini akan selalu mengingat kebaikanmu."
  },
  AvgDialog_122694_Content_11 = {
    Text = "Ini pertama kalinya kamu melihat si penipu kecil di depanmu menampilkan ekspresi seperti ini, namun kewaspadaan yang tersisa tetap membuatmu berdiri di tempat sambil menghembuskan napas putih dan menggerakkan tubuh."
  },
  AvgDialog_122694_Content_12 = {
    Text = "Aku sudah memberitahu bagian urusan sekolah, mereka akan segera datang membantu, kamu tetap berdiri di sini jangan bergerak, jangan lakukan apa pun."
  },
  AvgDialog_122694_Content_13 = {
    Text = "Tapi aku sekarang sangat tidak enak badan, kekuatan sungai itu membawaku kembali ke tempat yang pucat… dingin… mengerikan itu…"
  },
  AvgDialog_122694_Content_14 = {
    Text = "Tanpa peringatan apa pun, air mata Caraboo jatuh begitu saja, seolah-olah dia benar-benar menyaksikan sesuatu yang mengerikan."
  },
  AvgDialog_122694_Content_15 = {
    Text = "Aku mungkin tidak bisa menunggu bantuan datang, Penjaga, maaf karena selama ini selalu berbohong padamu…"
  },
  AvgDialog_122694_Content_16 = {
    Text = "Kristal menyebar keluar dengan dirinya sebagai pusat, dia tampak tak berdaya dan rapuh, menatapmu dengan mata merah, seolah-olah bisa jatuh tersungkur kapan saja."
  },
  AvgDialog_122694_Content_17 = {Text = "Caraboo!"},
  AvgDialog_122694_Content_18 = {
    Text = "Sesaat sebelum dia jatuh ke tanah, kamu akhirnya tetap saja menerjang maju untuk menopangnya, namun detik berikutnya, kamu menyesal."
  },
  AvgDialog_122694_Content_19 = {
    Text = "Kedua lengan dingin itu melilit tubuhmu dengan lincah seperti makhluk tak bertulang belakang, hembusan napas berbintik kristal salju pun menyerbu ke lekuk leher dan daun telingamu."
  },
  AvgDialog_122694_Content_2 = {
    Text = "Kamu memberanikan diri, menahan dingin yang hampir membuatmu menggigit lidah sendiri, lalu mendorong pintu asrama Caraboo."
  },
  AvgDialog_122694_Content_20 = {
    Text = "Hihihi~ Aduh, ternyata, %player% masih selembut ini juga."
  },
  AvgDialog_122694_Content_21 = {
    Text = "Di belakangnya, ada sesuatu yang lebih lembut namun dingin, yang dengan rapat dan perlahan menenggelamkanmu ke dalam lapisan salju yang dalam."
  },
  AvgDialog_122694_Content_22 = {
    Text = "Kamu meronta-ronta dengan suara tertahan, dan sebelum sepenuhnya kehilangan kesadaran, kamu mendengar tawa riang dari sosok putih licik itu."
  },
  AvgDialog_122694_Content_23 = {
    Text = "Tidak apa-apa, peri agung ini akan sangat, sangat lembut dalam memperlakukan anak dombaku yang paling berharga~"
  },
  AvgDialog_122694_Content_3 = {
    Text = "Caraboo, kamu melakukan apa lagi, ssst, dingin sekali ini. *gemetar"
  },
  AvgDialog_122694_Content_4 = {
    Text = "Namun sosok eksentrik itu, ternyata tidak muncul seperti biasanya dengan cara yang berkilauan, memamerkan kenakalan isengnya padamu."
  },
  AvgDialog_122694_Content_5 = {
    Text = "Di wajahnya muncul semburat merah yang jarang terlihat, bahkan bisa dibilang, hmm, memelas menggemaskan."
  },
  AvgDialog_122694_Content_6 = {
    Text = "Penjaga, bagaimana ini~ Caraboo merasa sangat aneh, badan terasa aneh, kepala juga terasa aneh."
  },
  AvgDialog_122694_Content_7 = {
    Text = "Caraboo sangat kedinginan, hampir mati membeku di sini."
  },
  AvgDialog_122694_Content_8 = {
    Text = "Caraboo juga sangat kepanasan, panas sampai kaki terasa lemas, tidak bisa melangkah sama sekali."
  },
  AvgDialog_122694_Content_9 = {
    Text = "Dia menggigit bibir bawahnya, dengan mata berkaca-kaca membuka kedua lengannya ke arahmu, berpose meminta pelukan."
  },
  AvgDialog_122696_Content_1 = {
    Text = "Di aula yang kosong, hanya langkahmu dan murphy yang bergema."
  },
  AvgDialog_122697_Content_1 = {
    Text = "Hari ini langit menjadi gelap lebih cepat dari biasanya, dan mendung, jelas akan turun hujan."
  },
  AvgDialog_122697_Content_10 = {
    Text = "Moxia mengangkat kepalanya, di wajahnya yang berwarna kemerahan yang tidak normal, muncul senyuman yang campur aduk antara kebingungan dan kegilaan."
  },
  AvgDialog_122697_Content_11 = {
    Text = "Bertarung denganku, segera, sekarang!"
  },
  AvgDialog_122697_Content_13 = {
    Text = "Sebelum kamu sempat menjawab, kapak Moxia sudah menyerang, dengan ringan dan tepat menyapu pipimu, menimbulkan angin dingin."
  },
  AvgDialog_122697_Content_14 = {
    Text = "Angin itu masuk tanpa izin ke dalam kerah bajumu, mengalir ke dalam dadamu, membuat tubuhmu secara naluriah merinding."
  },
  AvgDialog_122697_Content_15 = {
    Text = "Kenapa langsung bertengkar begitu saja!?"
  },
  AvgDialog_122697_Content_16 = {
    Text = "Pertanyaanmu diabaikan oleh kapak dan pemilik kapak itu."
  },
  AvgDialog_122697_Content_17 = {
    Text = "<Shake:Moyasha?>"
  },
  AvgDialog_122697_Content_18 = {Text = "Moyasha!?"},
  AvgDialog_122697_Content_19 = {
    Text = "Di bawah pertanyaanmu yang terus menerus, kapak akhirnya berhenti. Ia menempel di bahu kamu, terbenam dalam dinding."
  },
  AvgDialog_122697_Content_2 = {
    Text = "Untuk menghindari nasib basah, kamu berlari tergesa-gesa menuju asrama, tetapi sebuah sosok menghalangi jalanmu."
  },
  AvgDialog_122697_Content_20 = {
    Text = "Dan pemilik kapak itu berdiri di depanmu, wajahnya memerah, menggenggam tinjunya, dan dengan kuat mencengkeram kerah bajumu."
  },
  AvgDialog_122697_Content_21 = {
    Text = "<Shake:Jangan berisik... Aku merasa sangat tidak enak, hanya dengan bertarung denganmu aku bisa merasa sedikit lebih baik...>"
  },
  AvgDialog_122697_Content_22 = {
    Text = "Jari-jari yang mencengkeram kerah bajumu terus memberikan tekanan, berubah dari warna daging menjadi pucat, menandakan kerasnya hati dan ketidakrelakan sang pemilik."
  },
  AvgDialog_122697_Content_23 = {
    Text = "Saya paling benci ketika orang lain memaksakan ide mereka kepada orang lain..."
  },
  AvgDialog_122697_Content_24 = {
    Text = "Hanya Sungai Suci, ingin mempengaruhiku?<Shake:Terlalu meremehkan aku.>"
  },
  AvgDialog_122697_Content_25 = {
    Text = "Moxia berkata sambil menghembuskan napas dengan kuat, berusaha meredakan pengaruh Sungai Suci terhadapnya, tetapi kamu dapat merasakan panas yang mengalir dalam dirinya, keinginan yang menggelora, dan konflik yang sedang bertarung."
  },
  AvgDialog_122697_Content_26 = {
    Text = "Menyadari emosi Mosha, kamu tidak bisa tidak menghela napas, meraih tangannya, dan membimbing gadis itu untuk menggenggam kembali pegangan kapak."
  },
  AvgDialog_122697_Content_27 = {
    Text = "<Shake:Apa yang kamu lakukan?>"
  },
  AvgDialog_122697_Content_28 = {
    Text = "Bukankah kamu ingin bertarung? Mari bertarung."
  },
  AvgDialog_122697_Content_29 = {
    Text = "Apa pun cara yang ingin kau gunakan untuk bertarung, tidak peduli sampai kapan kau ingin bertarung, aku akan bertempur bersamamu sampai akhir."
  },
  AvgDialog_122697_Content_3 = {
    Text = "Moyasha? Ada apa?"
  },
  AvgDialog_122697_Content_31 = {
    Text = "Mata gadis itu tiba-tiba membelalak, menatapmu dengan terkejut."
  },
  AvgDialog_122697_Content_32 = {
    Text = "Saat itu, hujan yang telah direncanakan akhirnya turun, tetesan air jatuh di wajah Moxia, mengalir dari dagunya, kemudian masuk ke dalam kerah bajumu, mengalir di sepanjang dadamu."
  },
  AvgDialog_122697_Content_33 = {
    Text = "Kemudian, lebih banyak tetesan hujan, menghantam tanah dengan liar, memukul pipi kamu dan gadis itu, membawa sedikit rasa gatal."
  },
  AvgDialog_122697_Content_34 = {
    Text = "<Shake:Hahahaha, saya suka jawabanmu.>"
  },
  AvgDialog_122697_Content_35 = {
    Text = "Keadaan mulai menjadi lebih berarti, bukan?"
  },
  AvgDialog_122697_Content_36 = {
    Text = "Moxia menggenggam pegangan kapak, menarik kapak dari dinding, tetapi dia tidak mengayunkan kapak itu lagi, melainkan menatapmu, menatapmu dengan tajam."
  },
  AvgDialog_122697_Content_37 = {
    Text = "Biasanya, saya tidak bertarung tangan kosong dengan orang lain, tetapi terkadang harus mencoba hal-hal baru, bukan?"
  },
  AvgDialog_122697_Content_38 = {
    Text = "Hidup ini begitu panjang, beberapa hal yang menarik, harus dialami secara langsung dan perlahan."
  },
  AvgDialog_122697_Content_39 = {
    Text = "Moxia berkata sambil perlahan berjalan menuju kamu. Sementara itu, kapak itu diam-diam bersandar di dinding, menerima pencucian lembap dunia."
  },
  AvgDialog_122697_Content_4 = {
    Text = "Moxia menundukkan kepalanya, tidak menjawab, kamu hanya bisa melihat dari jari-jarinya yang memutih akibat menggenggam kapak dengan kuat, merasakan bahwa gadis itu tidak dalam keadaan tenang."
  },
  AvgDialog_122697_Content_5 = {
    Text = "<Shake:Moyasha!?>"
  },
  AvgDialog_122697_Content_6 = {
    Text = "Akhirnya, gadis itu berbicara, tetapi suaranya terdengar dengan sedikit keraguan dan ketidakpastian."
  },
  AvgDialog_122697_Content_7 = {
    Text = "%player%, saya, saya membutuhkan bantuanmu..."
  },
  AvgDialog_122697_Content_8 = {
    Text = "Bantuan? Tidak masalah. Apa yang kamu butuhkan?"
  },
  AvgDialog_122697_Content_9 = {
    Text = "<Shake:Aku butuh kamu...>"
  },
  AvgDialog_122700_Content_1 = {
    Text = "Selamat datang di teaterku. Anda datang tepat waktu, Penjaga Rahasia {Male=先生,Female=小姐}."
  },
  AvgDialog_122700_Content_10 = {
    Text = "Berkembang biak… Kelahiran baru… Jangan-jangan kau juga?!"
  },
  AvgDialog_122700_Content_11 = {
    Text = "Eh, tiba-tiba teringat tugas dari Profesor Dor belum selesai… Sepertinya aku sebaiknya…"
  },
  AvgDialog_122700_Content_12 = {
    Text = "Kau berbalik ingin pergi, tetapi langkah kakimu secara tidak sadar membawamu terus maju, tiba di depan Arachne."
  },
  AvgDialog_122700_Content_13 = {
    Text = "Ini pengaruh Sungai Suci… juga tarikan takdir. Malam ini, adalah malam yang hanya milik kita berdua."
  },
  AvgDialog_122700_Content_14 = {
    Text = "Sebuah drama yang ditakdirkan untuk dipentaskan, akhirnya menunggu pemeran utama yang telah ditakdirkan untuknya."
  },
  AvgDialog_122700_Content_15 = {
    Text = "Arachne's napas telah menempel di telingamu, hangat dan samar."
  },
  AvgDialog_122700_Content_16 = {
    Text = "Senyumnya masih lembut dan tenang, namun di kedua matanya yang tak berdasar itu, berkilau api yang belum pernah kau lihat sebelumnya, seolah mampu menelan segalanya."
  },
  AvgDialog_122700_Content_17 = {
    Text = "Tidak, tidak bisa... Arachne... aku..."
  },
  AvgDialog_122700_Content_18 = {
    Text = "Tak perlu melarikan diri, %player%. Jaring takdir telah merajut semua kemungkinan, dan ia akan membimbing Anda bersama saya menyelesaikan pertunjukan malam ini."
  },
  AvgDialog_122700_Content_19 = {
    Text = "Jaring laba-laba tak kasat mata membelenggumu, merampas seluruh tenagamu, dan juga menelan semua keinginanmu untuk melawan."
  },
  AvgDialog_122700_Content_2 = {
    Text = "Kamu mendorong pintu besar teater yang berat, sinar bulan menyinari dari jendela tinggi, embun malam yang sedikit dingin dan suara lembut Arachne di dalam teater membuatmu terbangun tiba-tiba."
  },
  AvgDialog_122700_Content_20 = {
    Text = "Benang-benang takdir terjalin. Kau menatap wajah lembut yang begitu dekat itu, jantungmu berdegup kencang, napasmu tiba-tiba menjadi cepat."
  },
  AvgDialog_122700_Content_21 = {
    Text = "Dalam takdirmu, kau tak pernah ingin melarikan diri. Kau mendambakan, mendambakan untuk datang ke sini, mendambakan untuk menyelesaikan pertunjukan tanpa penonton ini."
  },
  AvgDialog_122700_Content_22 = {
    Text = "Kau… memalsukan takdirku?!"
  },
  AvgDialog_122700_Content_23 = {
    Text = "Saya tidak pernah memalsukan takdir, Penjaga Rahasia {Male=先生,Female=小姐}. Saya hanya membuat takdir Anda melangkah ke jalur yang seharusnya ditempuh."
  },
  AvgDialog_122700_Content_24 = {
    Text = "Arachne... kamu... kamu sepenuhnya bisa mengubah jalannya nasib, menghindari pengaruh Sungai Suci... mengapa tidak melakukannya?"
  },
  AvgDialog_122700_Content_25 = {
    Text = "Kenapa harus melakukannya?"
  },
  AvgDialog_122700_Content_26 = {
    Text = "Bagi seorang aktris yang sudah lama menghafal naskah, kejutan adalah hadiah paling berharga yang diberikan takdir…"
  },
  AvgDialog_122700_Content_27 = {
    Text = "Kata-kata lembut Arachne bergetar di telingamu. Dia tidak lagi tenang dan jauh, napasnya bergetar pelan, senyumnya begitu dekat."
  },
  AvgDialog_122700_Content_28 = {
    Text = "Kebetulan, aku tidak menolak akhir ini… akhir di mana tak seorang pun akan terluka."
  },
  AvgDialog_122700_Content_29 = {
    Text = "Jaring yang terajut dari benang-benang sutra itu dingin, lentur, dengan kelengketan yang mencekik, semakin erat, mengiris kainmu, menempel di kulitmu."
  },
  AvgDialog_122700_Content_3 = {
    Text = "Tunggu! Seharusnya aku sedang tidur di asrama, kenapa aku bisa sampai di sini… Apa kau yang mengendalikanku?"
  },
  AvgDialog_122700_Content_30 = {
    Text = "Detik berikutnya, kelisera mencengkeram tubuhmu, pedipalpa yang dingin menerobos masuk ke mulutmu, menyegel penolakan yang belum sempat kau ucapkan."
  },
  AvgDialog_122700_Content_31 = {
    Text = "Benang-benang mulai menarik anggota tubuhmu—lembut, namun tak bisa dilawan."
  },
  AvgDialog_122700_Content_32 = {
    Text = "Tak perlu khawatir, Penjaga Rahasia, dan tak perlu menolak hadiah dari takdir."
  },
  AvgDialog_122700_Content_33 = {
    Text = "Karena… ini juga yang Anda inginkan, bukan?"
  },
  AvgDialog_122700_Content_34 = {
    Text = "... benar, Arachne... ini adalah... yang aku inginkan..."
  },
  AvgDialog_122700_Content_35 = {
    Text = "Tentu saja, kau tak pernah menjadi boneka marionette takdir. Kau adalah Penjaga Rahasia Mythag, pengendali takdirmu sendiri."
  },
  AvgDialog_122700_Content_36 = {
    Text = "Semua ini memang yang kau inginkan. Takdirlah yang tunduk pada kehendakmu, tubuhmu yang merespons panggilanmu…"
  },
  AvgDialog_122700_Content_37 = {
    Text = "Benang-benang bergetar halus, bagai takdir memetik dawai. Kau membelai kaki-kaki laba-laba yang berayun pelan di udara, membelai kedua tangan yang senantiasa memutar roda pemintal, membelai wajah lembut itu."
  },
  AvgDialog_122700_Content_38 = {
    Text = "Wajah yang akrab itu, yang selalu membawa belas kasih abadi dan ketenangan bagai takdir, kini merona merah samar oleh kemabukan."
  },
  AvgDialog_122700_Content_39 = {
    Text = "Mari kita bersama, menyambut datangnya takdir, Penjaga Rahasia {Male=先生,Female=小姐}."
  },
  AvgDialog_122700_Content_4 = {
    Text = "Andalah yang mengikuti kehendak Anda sendiri, \"ingin\" datang ke sini. Anda lupa?"
  },
  AvgDialog_122700_Content_40 = {
    Text = "Dua helai benang takdir saling melilit, saling menggigit, tak pernah berhenti. Riak yang bergetar menyebar sepanjang jaring kekosongan, merembes menuju cakrawala tanpa batas."
  },
  AvgDialog_122700_Content_5 = {
    Text = "Dia tersenyum padamu. Tekanan bagai takdir yang tak terelakkan menghampirimu dari segala penjuru."
  },
  AvgDialog_122700_Content_6 = {
    Text = "Manusia selalu memandang takdir sebagai belenggu yang tak bisa dilawan, menganggap semua penderitaan berasal darinya."
  },
  AvgDialog_122700_Content_7 = {
    Text = "Namun kau dan aku yang pernah menyentuh benang-benang takdir memahami, bahwa takdir hanyalah ciptaan yang kita pilih sendiri."
  },
  AvgDialog_122700_Content_8 = {
    Text = "Berkembang biak, demi kehancuran. Kehancuran, juga demi kelahiran baru."
  },
  AvgDialog_122700_Content_9 = {
    Text = "Berulang-ulang, tanpa henti… Begitulah takdir, bukan?"
  },
  AvgDialog_122780_Content_1 = {
    Text = "Pesan dari jauh"
  },
  AvgDialog_122780_Content_2 = {
    Text = "Ini adalah dokumen uji"
  },
  AvgDialog_122780_Content_3 = {
    Text = "Ini adalah dokumen uji"
  },
  AvgDialog_122780_Content_4 = {
    Text = "Ini adalah dokumen uji"
  },
  AvgDialog_122780_Content_5 = {
    Text = "Ini adalah dokumen uji"
  },
  AvgDialog_122780_Content_6 = {
    Text = "Ini adalah dokumen uji"
  },
  AvgDialog_122780_Content_7 = {
    Text = "Pernyataan akhir"
  },
  AvgDialog_123116_Content_1 = {
    Text = "Anak Domba yang Tersesat"
  },
  AvgDialog_123116_Content_10 = {
    Text = "Tetapi setiap pendeta yang tiba di Howick - John, James, Anderson, semuanya telah kehilangan kontak dalam waktu singkat."
  },
  AvgDialog_123116_Content_11 = {
    Text = "Anak-anak yang baik... Setelah bencana alam, mereka terus mengikuti ajaran Sang Bapa, secara sukarela pergi ke berbagai paroki untuk menyebarkan kabar baik dari Sang Bapa."
  },
  AvgDialog_123116_Content_12 = {
    Text = "Bahkan di kota besar seperti London, orang biasa sering kali tidak bisa mengurus diri sendiri setelah bencana, sementara keadaan di Howick hanya akan semakin buruk. Mengapa mereka —"
  },
  AvgDialog_123116_Content_13 = {
    Text = "Sama seperti yang kau lakukan untuk dunia ini, dan dunia yang telah berlalu, utusan pucat."
  },
  AvgDialog_123116_Content_14 = {
    Text = "Salvador menyatukan kedua tangan, dengan sikap berdoa yang khusyuk dan penuh kasih sayang."
  },
  AvgDialog_123116_Content_15 = {
    Text = "Karena saudara-saudara kita sedang menderita."
  },
  AvgDialog_123116_Content_16 = {
    Text = "Menghilangkan penderitaan dari bumi ini adalah tanggung jawab wakil Sang Bapa. Mereka tidak dapat meninggalkan orang lain dalam keadaan terdesak hanya karena jarak yang jauh."
  },
  AvgDialog_123116_Content_17 = {
    Text = "……Aku mengerti."
  },
  AvgDialog_123116_Content_18 = {
    Text = [[
Pendeta Salvador, aku akan membantumu mencarikan mereka. 
Apapun yang terjadi.]]
  },
  AvgDialog_123116_Content_19 = {Text = "Saat ini"},
  AvgDialog_123116_Content_2 = {
    Text = "Pinggiran kota London, desa terpencil, Hawick"
  },
  AvgDialog_123116_Content_20 = {
    Text = "Salvador, sepertinya ada cahaya di depan…"
  },
  AvgDialog_123116_Content_21 = {
    Text = "Suaramu tiba-tiba terhenti karena penemuan yang tak terduga — di dalam gua yang kosong, tiba-tiba muncul sebuah sangkar yang sederhana."
  },
  AvgDialog_123116_Content_22 = {
    Text = "Di dalam kandang setidaknya ada belasan orang, semuanya terlihat lelah, dan beberapa di antaranya memiliki wajah memar dan tubuh penuh luka."
  },
  AvgDialog_123116_Content_23 = {
    Text = "<Shake:Henry... mati? Mereka menembak mati Henry, menembak mati Henry...!>"
  },
  AvgDialog_123116_Content_24 = {
    Text = "Wanita itu memeluk kepalanya dan berbicara pelan, tatapan gila dan getaran yang hebat mengungkapkan ketidaknormalannya."
  },
  AvgDialog_123116_Content_25 = {
    Text = "Tiba-tiba, dia mendongak dan menemukan kalian yang mendekat."
  },
  AvgDialog_123116_Content_26 = {
    Text = "<Shake:Tidak, mereka akan datang, cepat bawa kami pergi dari sini!>"
  },
  AvgDialog_123116_Content_27 = {
    Text = "Gerakan anehnya menarik lebih banyak perhatian, seorang pria dari dalam sangkar tiba-tiba berlari ke arah jeruji sangkar, meraih lenganmu dengan kuat."
  },
  AvgDialog_123116_Content_28 = {
    Text = "Tolong aku! Aku tidak ingin menjadi korban manusia, tidak ingin dikorbankan…"
  },
  AvgDialog_123116_Content_29 = {
    Text = "Aah aah aah aah——bawa kami pergi dari sini!"
  },
  AvgDialog_123116_Content_3 = {
    Text = "Jika informasi yang diberikan oleh \"Boneka\" tidak salah, mereka seharusnya ada di sini."
  },
  AvgDialog_123116_Content_30 = {
    Text = "Diam semuanya*Suara mati*!"
  },
  AvgDialog_123116_Content_31 = {
    Text = "Sebuah teriakan keras memecah teriakan para korban, para tahanan tampak sangat ketakutan terhadap pemilik suara itu, membuat mereka ketakutan hingga kehilangan akal."
  },
  AvgDialog_123116_Content_32 = {
    Text = "Pengorbanan belum dimulai, kalian sekelompok babi ini sudah terburu-buru mencari mati!?"
  },
  AvgDialog_123116_Content_33 = {
    Text = "Langkah kaki yang terburu-buru menyusul."
  },
  AvgDialog_123116_Content_34 = {
    Text = "Seharusnya adalah sekte jahat yang menahan orang-orang ini, %player%, kita......"
  },
  AvgDialog_123116_Content_35 = {
    Text = "Sembunyi dulu, nanti kita cari cara untuk menyelamatkan. Mereka membawa senjata, dalam kekacauan ini kita tidak bisa melindungi keselamatan orang-orang ini."
  },
  AvgDialog_123116_Content_36 = {
    Text = "Tetapi pria itu tetap memegangmu dengan erat, kekuatannya hampir mematahkan lenganmu."
  },
  AvgDialog_123116_Content_37 = {
    Text = "Selamatkan kami, selamatkan kami terlebih dahulu! Jika tidak menyelamatkan kami, mati bersama kami!!"
  },
  AvgDialog_123116_Content_38 = {
    Text = "Suara langkah kaki semakin dekat, keadaan mental lawan jelas tidak bisa menerima alasan apapun."
  },
  AvgDialog_123116_Content_39 = {
    Text = "Kamu menggigit gigi, mengangkat tanganmu dan memukulnya hingga pingsan."
  },
  AvgDialog_123116_Content_4 = {
    Text = "Saya percaya pada penilaianmu, %player%."
  },
  AvgDialog_123116_Content_40 = {Text = "Ha..."},
  AvgDialog_123116_Content_41 = {
    Text = "Di sudut penjara, terdengar tawa kecil secara tiba-tiba."
  },
  AvgDialog_123116_Content_42 = {
    Text = "Kamu secara naluri berbalik menatap, di dalam kandang penjara, seorang gadis yang berpakaian aneh sedang menatapmu, senyum lembutnya tidak sesuai dengan suasana yang kacau dan gila saat ini."
  },
  AvgDialog_123116_Content_43 = {
    Text = "Betapa menariknya, detik sebelumnya bilang ingin menyelamatkan orang, detik berikutnya langsung memukulnya pingsan..."
  },
  AvgDialog_123116_Content_44 = {
    Text = "Keadaan yang terlalu terasing saat ini membuatmu tertegun sejenak di tempat."
  },
  AvgDialog_123116_Content_45 = {
    Text = "Jangan hiraukan saya, teruskan saja."
  },
  AvgDialog_123116_Content_46 = {
    Text = "Belum cepat? Pengikut Fajar Bintang akan segera tiba, lho."
  },
  AvgDialog_123116_Content_47 = {Text = "...?"},
  AvgDialog_123116_Content_48 = {
    Text = "Waktu mendesak, tidak ada waktu untuk mengobrol, kamu hanya bisa meninggalkan gadis itu dan bersembunyi di tempat gelap bersama Salvador."
  },
  AvgDialog_123116_Content_49 = {
    Text = "Tak lama kemudian, dua pengikut sesat yang memegang senapan muncul di luar kandang, mereka berdiri di kedua sisi, mengangkat senjata di tangan mereka dan mengarahkan larasnya ke dalam kandang."
  },
  AvgDialog_123116_Content_5 = {
    Text = "Semoga Bapa melindungi mereka dari kegelapan, semoga mereka tetap tinggal dalam ketenangan."
  },
  AvgDialog_123116_Content_50 = {
    Text = "Siapa yang berisik barusan, keluar!"
  },
  AvgDialog_123116_Content_51 = {
    Text = [[
Tidak ada yang menjawab. Para tahanan bersembunyi di sudut, menggigil ketakutan, atau tatapan mereka kosong, bisu dan tidak berbicara. 
 Kecuali gadis aneh itu.]]
  },
  AvgDialog_123116_Content_52 = {
    Text = "Dia masih tersenyum santai, dengan tenang mengamati para pengikut sesat yang memegang senjata."
  },
  AvgDialog_123116_Content_53 = {
    Text = "Orang ini jangan-jangan gila, sudah di ambang kematian masih begitu santai."
  },
  AvgDialog_123116_Content_54 = {
    Text = "Di dunia sialan ini, di mana ada orang normal, ha! Jika kita juga orang gila, mungkin akan lebih mudah."
  },
  AvgDialog_123116_Content_55 = {
    Text = "Semoga upacara kali ini berhasil, aku benar-benar sudah cukup menderita dengan kabut tebal yang aneh itu..."
  },
  AvgDialog_123116_Content_56 = {
    Text = "Kapan upacara yang kalian bicarakan dimulai?"
  },
  AvgDialog_123116_Content_57 = {
    Text = "Pengikut sesat tertegun dengan jelas terlihat."
  },
  AvgDialog_123116_Content_58 = {
    Text = "Kamu sedang berbicara dengan siapa, kami?"
  },
  AvgDialog_123116_Content_59 = {
    Text = "Kalau tidak? Jangan berbicara kosong, jawab pertanyaanku."
  },
  AvgDialog_123116_Content_6 = {
    Text = "Salvador menundukkan kepala dengan khusyuk, setelah berdoa pelan, ia melangkah lebih dulu ke dalam gua."
  },
  AvgDialog_123116_Content_60 = {
    Text = "Pengikut sesat itu benar-benar marah, tertawa dingin sambil mengangkat tangan dan mengarahkan moncong senjata ke bagian kaki gadis itu."
  },
  AvgDialog_123116_Content_61 = {
    Text = "Wanita gila, kamu hanya perlu menunggu dengan patuh untuk dikorbankan, saya rasa kamu sama sekali tidak mengerti situasinya."
  },
  AvgDialog_123116_Content_62 = {Text = "BRAK—"},
  AvgDialog_123116_Content_63 = {
    Text = "Kekuatan tak terlihat membuat peluru kehilangan ketepatan, mengenai bagian atas gua, memercikkan cahaya api yang lemah —"
  },
  AvgDialog_123116_Content_64 = {
    Text = "Kau dan Salvador muncul dari kegelapan, melancarkan serangan terhadap para pengikut kultus."
  },
  AvgDialog_123116_Content_66 = {
    Text = "Waktu yang ditangkap cukup baik, sepertinya kalian tidak bodoh-bodoh amat."
  },
  AvgDialog_123116_Content_67 = {
    Text = "Terima kasih telah mengalihkan perhatian para pengikut sesat untuk kami, Nyonya yang baik hati."
  },
  AvgDialog_123116_Content_68 = {
    Text = "Semoga Bapa melindungi kamu."
  },
  AvgDialog_123116_Content_69 = {
    Text = [[
Salvador menggambar simbol suci Sang Bapa di udara.
Kamu menyita semua senjata para pengikut sesat, memerintahkan mereka untuk berlutut di depan sangkar, dan memulai interogasi.]]
  },
  AvgDialog_123116_Content_7 = {
    Text = "Tiga hari yang lalu"
  },
  AvgDialog_123116_Content_70 = {
    Text = "Katakan, kapan upacara diadakan? Di mana diadakan? Apakah hilangnya pendeta Santuari Kehidupan ada hubungannya dengan kalian!?"
  },
  AvgDialog_123116_Content_71 = {
    Text = "Gereja Hidup... Pendeta...?"
  },
  AvgDialog_123116_Content_72 = {
    Text = "Benar, John, James, Anderson, mereka di mana?"
  },
  AvgDialog_123116_Content_73 = {
    Text = "Mendengar ini, pengikut sesat terdiam sejenak, lalu tiba-tiba tertawa terbahak-bahak."
  },
  AvgDialog_123116_Content_74 = {
    Text = "<Shake:Kami akan menyelamatkan diri kami sendiri sesuai dengan kehendak Sang Pencipta, ya, \"kerajaan damai tanpa penderitaan yang lenyap\"!>"
  },
  AvgDialog_123116_Content_75 = {
    Text = "<Shake:<Big:Ia telah datang! Kalian yang tidak beruntung hanya bisa tinggal di sini, mengikuti dunia ini menuju kehancuran!>>"
  },
  AvgDialog_123116_Content_76 = {
    Text = "Jadi, upacara akan segera dimulai? <Small:Sepertinya aku harus mempercepat waktu.>"
  },
  AvgDialog_123116_Content_77 = {
    Text = "Cepat, waktu... apa artinya? Apa yang kamu tahu?"
  },
  AvgDialog_123116_Content_78 = {
    Text = [[
Gadis itu tidak menjawab, dia melirikmu dan Salvador, lalu menunjukkan senyuman yang polos dan manis. 
 Entah mengapa, kamu merasakan sedikit kecurangan di antara itu.]]
  },
  AvgDialog_123116_Content_79 = {
    Text = "Ah, benar, nama saya Moyasha, tentang nama kalian—tidak perlu dikatakan, saya tidak tertarik."
  },
  AvgDialog_123116_Content_8 = {
    Text = "Pendeta yang dikirim oleh Santuari Kehidupan ke Howick, semuanya hilang?"
  },
  AvgDialog_123116_Content_80 = {
    Text = "Aku tahu di mana lokasi upacara, dan aku bisa membawa kalian ke sana, hanya saja…"
  },
  AvgDialog_123116_Content_81 = {
    Text = "Perlu bantuan kecil dari kalian."
  },
  AvgDialog_123116_Content_82 = {
    Text = "Apa yang bisa dibantu? Harap kamu bisa menjelaskan dengan jelas."
  },
  AvgDialog_123116_Content_83 = {
    Text = "Masih tidak menjawab, gadis itu hanya meninggalkan satu kalimat, lalu pergi dengan nada yang terputus-putus."
  },
  AvgDialog_123116_Content_84 = {
    Text = "Hmph☆Hmph! Aku pergi mengurus sesuatu terlebih dahulu. Sepuluh menit kemudian, kita berkumpul di luar~"
  },
  AvgDialog_123116_Content_86 = {
    Text = "Baiklah, kita bisa menghubungi Santuari Kehidupan terlebih dahulu untuk mengirimkan lebih banyak orang untuk menata orang-orang yang menderita ini."
  },
  AvgDialog_123116_Content_87 = {
    Text = "Mari kita mulai, aku sudah tidak sabar ingin tahu siapa aku dan seperti apa masa laluku…"
  },
  AvgDialog_123116_Content_88 = {
    Text = "Memandang ke arah gadis yang pergi, rasa tidak nyaman yang semakin tumbuh membuatmu merasa seolah ada sesuatu yang merayap di punggungmu."
  },
  AvgDialog_123116_Content_89 = {
    Text = "Sumbernya adalah perasaan terputus yang sangat mendekati manusia, namun jelas-jelas palsu di balik penampilan naif pihak lain..."
  },
  AvgDialog_123116_Content_9 = {
    Text = "Ya, setelah Pendeta White yang bertanggung jawab atas paroki Howick kehilangan kontak dengan kami, Gereja memutuskan untuk mengirimkan bala bantuan."
  },
  AvgDialog_123117_Content_1 = {
    Text = "Di antara Perak dan Darah"
  },
  AvgDialog_123117_Content_10 = {
    Text = "...Aku tidak seharusnya membahas ini denganmu."
  },
  AvgDialog_123117_Content_100 = {
    Text = "Mossya... jika kau masih ada... keluarlah... aku mohon..."
  },
  AvgDialog_123117_Content_101 = {
    Text = "Masih tidak ada jawaban, seolah gadis bernama \"Moxia\" itu benar-benar menghilang."
  },
  AvgDialog_123117_Content_103 = {
    Text = [[
Kamu menutup mata, menghela napas dalam-dalam. Tidak ada waktu lagi. 
 Salvador masih di luar, pintu tak terlihat masih ada di luar, kamu harus kembali.]]
  },
  AvgDialog_123117_Content_104 = {
    Text = "Maaf, aku membawamu ke dunia yang begitu kejam ini... Maaf juga, aku tidak bisa mengantarmu pulang..."
  },
  AvgDialog_123117_Content_105 = {
    Text = "Detik berikutnya, kamu memutuskan tautan dimensi spiritual dengan Moyasha—"
  },
  AvgDialog_123117_Content_106 = {
    Text = "Setelah pusing singkat, semangatmu kembali ke tubuh, segalanya kembali ke titik awal:"
  },
  AvgDialog_123117_Content_107 = {
    Text = "Pintu tak terlihat masih dalam keadaan tidak terkendali, kapak Moyasha juga tergeletak diam di tanganmu."
  },
  AvgDialog_123117_Content_108 = {
    Text = "<Shake:Moyasha… aku…>"
  },
  AvgDialog_123117_Content_109 = {
    Text = "Kamu menggenggam pegangan kapak dengan kuat, menatap Mosha. Gadis dari dunia lain itu diam dalam kehilangan akal, seolah-olah menunggu keputusan terakhirmu."
  },
  AvgDialog_123117_Content_11 = {
    Text = "Kamu menghela napas, wajahmu penuh dengan kekecewaan. Salvador melihat semua ini, tidak bisa menahan senyum kecil."
  },
  AvgDialog_123117_Content_110 = {
    Text = [[
Mungkin ini hanya sugesti, tetapi kamu selalu merasa bahwa mata itu tidak sepenuhnya kehilangan akal sehat. 
 Karena kamu pernah melihat mata itu tersenyum.]]
  },
  AvgDialog_123117_Content_111 = {
    Text = "<Shake:Kamu mau... melihat apa... kapan...>"
  },
  AvgDialog_123117_Content_112 = {
    Text = "Moyasha! Kau telah mendapatkan akal sehatmu!?"
  },
  AvgDialog_123117_Content_113 = {
    Text = "<Shake:Tidak... tapi aku... mendengar... kata-katamu...>"
  },
  AvgDialog_123117_Content_114 = {
    Text = "Kamu benar... seharusnya tidak seperti ini... aku tidak bisa menyerah tanpa mencoba..."
  },
  AvgDialog_123117_Content_115 = {
    Text = "Mossia mengerahkan tenaga terakhirnya untuk menggenggammu, menyentuh kunci perak di dadamu."
  },
  AvgDialog_123117_Content_116 = {
    Text = "Apapun hasilnya, pintu tak terlihat akan menghilang..."
  },
  AvgDialog_123117_Content_117 = {
    Text = "Aku tidak akan... membiarkan tempat ini menjadi dunia bencana kabut yang lain..."
  },
  AvgDialog_123117_Content_118 = {
    Text = "Terutama setelah mengetahui betapa kerasnya kamu berusaha menyelamatkan dunia ini"
  },
  AvgDialog_123117_Content_119 = {
    Text = "Kemudian, kunci perak di dadamu berfungsi otomatis, memancarkan cahaya dan mewarnai pandanganmu menjadi putih."
  },
  AvgDialog_123117_Content_12 = {
    Text = "Moyasha, memang anak yang istimewa... hanya istimewa saja, tetaplah anak yang sangat baik."
  },
  AvgDialog_123117_Content_120 = {
    Text = "Kamu mendengar teriakan yang menyayat hati, ratapan penuh penderitaan, suara seruling yang terdistorsi, dan suara sesuatu yang pecah."
  },
  AvgDialog_123117_Content_121 = {
    Text = "Atau mungkin, semua ini hanyalah halusinasi akibat keteganganmu, karena di tengah putih yang murni ini, kamu kehilangan kendali atas persepsimu, dan juga kehilangan pemahaman tentang waktu."
  },
  AvgDialog_123117_Content_122 = {
    Text = "Sampai entah berapa lama kemudian, sampai semua ilusi menghilang, berbagai perasaanmu akhirnya kembali—"
  },
  AvgDialog_123117_Content_123 = {
    Text = "Kabut tebal menghilang, pintu tak terlihat lenyap, di altar yang penuh dengan noda darah, hanya ada dirimu, dan Salvador yang menatapmu dengan penuh kekhawatiran."
  },
  AvgDialog_123117_Content_124 = {
    Text = "Utusan pucat, kita...... gagal?"
  },
  AvgDialog_123117_Content_126 = {
    Text = "Tepat pada saat itu, terdengar tawa kecil di belakang kalian."
  },
  AvgDialog_123117_Content_127 = {
    Text = "%player%, Salvador, kenapa kalian melongo? Tugas sudah selesai."
  },
  AvgDialog_123117_Content_128 = {
    Text = "<Big:Moyasha——!!>"
  },
  AvgDialog_123117_Content_129 = {
    Text = "Dalam keadaan terkejut, kamu berteriak, namun di detik berikutnya, kamu tak bisa menahan diri untuk tersenyum."
  },
  AvgDialog_123117_Content_13 = {
    Text = "Anak baik? Tolong, jangan gunakan kata ini untuk menggambarkan... Tunggu, apakah kalian mendengar suara apa pun?"
  },
  AvgDialog_123117_Content_130 = {
    Text = "Tidak perlu berteriak, saya juga bisa mendengarnya dengan jelas. Lagipula, pertempuran yang mendebarkan sudah berakhir, yang tersisa hanyalah kehidupan sehari-hari yang membosankan."
  },
  AvgDialog_123117_Content_131 = {
    Text = "Setelah pulang, saya benar-benar ingin segelas teh hazelnut yang panas, oh... di sini tidak ada itu, jadi mari makan kue kecil saja."
  },
  AvgDialog_123117_Content_132 = {
    Text = "Kita bisa sambil makan kue kecil, sambil mengobrol, misalnya, siapa itu Murphy, siapa itu Liz, siapa itu Dole, dan petualangan menarik apa yang telah kamu lakukan dengan tubuh bangkit?"
  },
  AvgDialog_123117_Content_133 = {
    Text = "Lagipula aku juga tidak bisa kembali, jadi hanya bisa lebih memahami dunia ini."
  },
  AvgDialog_123117_Content_134 = {
    Text = "Aku rasa, permintaan ini tidak akan ditolak oleh %player%."
  },
  AvgDialog_123117_Content_135 = {
    Text = [[
Salvador memandangmu dengan senyuman, dan kamu pun tersenyum, memandang ke arah Mosha. 
 Kabut tebal menghilang, sinar bulan di langit malam jatuh menimpa kalian, memantulkan cahaya lembut.]]
  },
  AvgDialog_123117_Content_136 = {
    Text = "Kamu masih memiliki banyak pertanyaan yang ingin ditanyakan kepada Mouchette, tetapi kamu menekannya di dalam hatimu—"
  },
  AvgDialog_123117_Content_137 = {
    Text = "Mungkin karena cahaya bulan yang indah itu, atau mungkin karena sesuatu yang tidak bisa kamu jelaskan, mirip dengan perasaan selamat dari kematian yang mendekati \"kelahiran kembali\"."
  },
  AvgDialog_123117_Content_138 = {
    Text = "Yah, laporan bisa ditulis kapan saja, tetapi merayakan kedatangan tamu dari dunia lain seperti ini, kesempatan untuk terlahir kembali di dunia baru tidaklah banyak."
  },
  AvgDialog_123117_Content_139 = {
    Text = "Selamat telah menjadi Pembangun, Moyasha. Mulai sekarang, tempat ini bukan hanya dunia kami, tetapi juga duniamu..."
  },
  AvgDialog_123117_Content_14 = {
    Text = "Sepertinya, ada seseorang yang menangis... dan suaranya semakin keras..."
  },
  AvgDialog_123117_Content_140 = {
    Text = [[
Pembangun Moyasha
selamat datang di dunia kami]]
  },
  AvgDialog_123117_Content_15 = {
    Text = [[
Kamu mendengarkan dengan seksama, tetapi tidak mendengar apa pun. 
 Kamu kemudian melihat ke arah Salvador, dia juga menggelengkan kepala dengan lembut.]]
  },
  AvgDialog_123117_Content_16 = {
    Text = "Moxia tiba-tiba berteriak dengan menyedihkan, membungkuk, dan dengan kesakitan menutupi telinganya."
  },
  AvgDialog_123117_Content_17 = {
    Text = "<Shake:Tunggu sebentar... Ada seseorang, tidak, banyak orang, yang berteriak dan meratap di dalam pikiranku...>"
  },
  AvgDialog_123117_Content_18 = {
    Text = "Kamu merasakan sesuatu yang tidak beres, memeriksa keadaan Mosha, tetapi hanya melihatnya bergetar kesakitan tanpa henti, dan pupil matanya terus kabur."
  },
  AvgDialog_123117_Content_19 = {
    Text = "Kehilangan kendali? Apakah ini karena cairan Perak...?"
  },
  AvgDialog_123117_Content_2 = {
    Text = "Di bawah langit yang dipenuhi perak dan darah, kabut tebal tak terhingga bergolak, pintu tak berbentuk memancarkan cahaya, tetapi mereka tidak lagi terlihat tak terkalahkan —"
  },
  AvgDialog_123117_Content_20 = {
    Text = "Inti Perak Cair!?"
  },
  AvgDialog_123117_Content_21 = {
    Text = "Kamu memeriksa noda darah di tubuh Moxia dengan teliti, di tengah warna merah tua, cairan inti perak perlahan mengalir, meresap ke dalam tubuhnya melalui kulitnya yang telanjang."
  },
  AvgDialog_123117_Content_22 = {
    Text = "Moyasha datang ke dunia kita melalui upacara pengorbanan, dan cairan kunci perak ini dijadikan sebagai persembahan, mungkin juga menjadikannya sebagai \"bagian\" dari upacara tersebut..."
  },
  AvgDialog_123117_Content_23 = {
    Text = "Tidak bisa, cairan perak di sini terlalu banyak dan campur aduk, harus segera ditangani, jika tidak, sebagai orang biasa dia akan gila!"
  },
  AvgDialog_123117_Content_24 = {
    Text = "Kamu dan Salvador segera mulai membersihkan cairan Perak dari tubuh Moyasha, tetapi sudah terlambat—"
  },
  AvgDialog_123117_Content_25 = {
    Text = "<Red:<Shake:Aaaah——>>"
  },
  AvgDialog_123117_Content_26 = {
    Text = "Dengan suara jeritan yang menyedihkan, pupil Moxia resmi menyebar dan terbelah, tubuhnya juga retak dan terdistorsi, memercikkan banyak darah dan daging, berubah menjadi suatu keberadaan yang sulit untuk dijelaskan."
  },
  AvgDialog_123117_Content_27 = {
    Text = "Daging dan darah yang hancur ini memercik ke arahmu dan Salvador, serta memercik ke Pintu Tak Terlihat, menimbulkan gelombang di permukaan yang tidak diketahui dan tidak jelas."
  },
  AvgDialog_123117_Content_28 = {
    Text = "Tidak beres, \"pintu\" sedang berubah…"
  },
  AvgDialog_123117_Content_29 = {
    Text = "Belum sempat selesai berbicara, gelombang dorongan yang kuat mengalir melalui pintu tak terlihat dan menghubungkan kunci perak ke dalam pikiranmu, membuatmu seketika kehilangan kata-kata."
  },
  AvgDialog_123117_Content_3 = {
    Text = "Kunci perak di tanganmu memancarkan cahaya yang menyilaukan dan tegas, perlahan menutup celah waktu, dan sedikit demi sedikit menghilangkan semua keanehan yang ditimbulkan oleh upacara."
  },
  AvgDialog_123117_Content_30 = {
    Text = "Dalam trauma mental yang tak tertahankan, darah mengalir dari hidungmu, kehilangan semua tenaga, setengah berlutut di tanah."
  },
  AvgDialog_123117_Content_31 = {
    Text = "<Red:<Shake:Bunuh bunuh bunuh! Bunuh semua orang!>>"
  },
  AvgDialog_123117_Content_32 = {
    Text = "<Red:<Shake:Hahahaha, hancurkan dunia ini!>>"
  },
  AvgDialog_123117_Content_33 = {
    Text = "Kapak yang pernah membuka jalan untukmu, diangkat tinggi, namun mengarah ke kepalamu. Sementara kamu, terkuras habis oleh tautan roh yang aneh, kehilangan kesadaran, tidak bisa bergerak."
  },
  AvgDialog_123117_Content_34 = {
    Text = "<Shake:Moyasha…>"
  },
  AvgDialog_123117_Content_35 = {
    Text = "Kamu berusaha untuk bersuara, tetapi suaramu serak dan lemah, sama sekali tidak bisa membangunkan akal sehat Moxia."
  },
  AvgDialog_123117_Content_37 = {
    Text = "Akhirnya, kapak jatuh dengan berat, menyusup ke dalam daging dan darah——\nPada saat kritis, Salvador berdiri di depanmu, menahan serangan ini."
  },
  AvgDialog_123117_Content_38 = {
    Text = "Darah mengalir di sepanjang bahu Salvador, namun ekspresinya tidak menunjukkan kebencian, hanya ada rasa belas kasihan dan kemurahan hati."
  },
  AvgDialog_123117_Content_39 = {
    Text = "Anak, saya tahu ini bukan maksudmu. Kamu hanya tersesat."
  },
  AvgDialog_123117_Content_4 = {
    Text = "Setelah waktu yang lama, perak dan darah yang mengapung mulai jatuh, jatuh ke tanah, jatuh ke tubuh kalian, kabut tebal di sekeliling juga terlihat memudar, menyusut, semuanya mulai membaik."
  },
  AvgDialog_123117_Content_40 = {
    Text = "<Red:<Shake:Bunuh! Bunuh bunuh! Hancurkan dunia!>>"
  },
  AvgDialog_123117_Content_41 = {
    Text = "Kegilaan telah sepenuhnya melahap Moxia, saat ini yang menggerakkan dirinya hanyalah dorongan brutal untuk menghancurkan dan membunuh."
  },
  AvgDialog_123117_Content_42 = {
    Text = "<Shake:Salvador, tidak berguna, dia...>"
  },
  AvgDialog_123117_Content_43 = {
    Text = [[
Kamu melihat Moxia yang sudah tidak bisa disebut sebagai "manusia", suaranya bergetar. 
 Jelas-jelas di detik sebelumnya, dia masih begitu hidup.]]
  },
  AvgDialog_123117_Content_44 = {
    Text = "Tidak, utusan pucat. Dia hanya tersesat."
  },
  AvgDialog_123117_Content_45 = {
    Text = "Salvador melangkah maju, menghadapi kapak tajam yang diangkat kembali oleh Masha."
  },
  AvgDialog_123117_Content_46 = {
    Text = "Darah dari permukaan kapak memercik di wajahnya, namun ekspresi Salvador tidak menunjukkan sedikitpun rasa takut."
  },
  AvgDialog_123117_Content_47 = {
    Text = "Perhimpunan Bintang Pagi mengorbankan manusia, saat memanggilmu, saya tidak berada di sini, saya sangat menyesal."
  },
  AvgDialog_123117_Content_48 = {
    Text = "Tetesan darah dari kapak Moxia mengalir dari pipi Salvador, seperti setetes air mata."
  },
  AvgDialog_123117_Content_49 = {
    Text = "Salvador tidak menghapus tetesan \"air mata\" ini, dia hanya menggenggam tepi kapak Moxia dengan tegas, sambil mengangkat tangan yang lain——"
  },
  AvgDialog_123117_Content_5 = {
    Text = "Segera, anomali Pintu Dimensi akan berkurang hingga paling lemah, Mosha, itu adalah waktu terbaik bagimu untuk pulang."
  },
  AvgDialog_123117_Content_50 = {
    Text = "Tapi pada saat ini, aku di sini, akan menyelamatkanmu."
  },
  AvgDialog_123117_Content_51 = {
    Text = "Tangan sang pendeta yang penuh darah menyentuh dahi gadis itu. Dalam sekejap, cahaya yang menyilaukan dan tegas menyala dari tempat mereka bersentuhan."
  },
  AvgDialog_123117_Content_52 = {
    Text = "Itu adalah seorang pendeta dunia ini, memberikan berkat kepada domba dari dunia lain."
  },
  AvgDialog_123117_Content_53 = {
    Text = "Dengan cahaya ini menyala, rasa sakit yang tajam di kepalamu tiba-tiba mereda dengan cepat, seolah-olah ada seseorang yang mengambil alih semua penderitaanmu..."
  },
  AvgDialog_123117_Content_54 = {
    Text = "Salvador, berhenti! Ini melibatkan hubungan lintas dimensi, tidak ada yang mampu menanggungnya!"
  },
  AvgDialog_123117_Content_55 = {Text = "Aku tahu."},
  AvgDialog_123117_Content_56 = {
    Text = "Suara Salvador bergetar dan hancur, tingkat penderitaan ini, bahkan bagi dirinya, adalah siksaan yang melebihi batas."
  },
  AvgDialog_123117_Content_57 = {
    Text = "Tak lama kemudian, dia tidak dapat menahan diri, dan darah air mata mengalir keluar."
  },
  AvgDialog_123117_Content_58 = {
    Text = "Tetapi sebagai wakil dari Dewa Ayah, aku harus berusaha sepenuhnya."
  },
  AvgDialog_123117_Content_59 = {
    Text = "Lebih banyak air mata darah mengalir dari bawah penutup mata Salvador, tetapi warna itu terpengaruh oleh cahaya \"berkah\" yang kuat, seolah-olah yang mengalir dari mata Salvador bukanlah darah, melainkan emas yang mencair."
  },
  AvgDialog_123117_Content_6 = {
    Text = "Saya akan selalu mengatur energi kunci perak ke maksimum, cukup untukmu melintasi dimensi dengan aman."
  },
  AvgDialog_123117_Content_60 = {
    Text = "Emas ini jatuh, menetes di punggung tangan Moxia, mengelupas kulit emasnya, memperlihatkan warna merah darah yang asli, bersatu dengan darah manusia yang memercik di tubuh Moxia, serta darah Moxia sendiri."
  },
  AvgDialog_123117_Content_61 = {
    Text = "Demi nama Bapa, Moxia, aku pasti tidak akan membiarkanmu tersesat."
  },
  AvgDialog_123117_Content_62 = {
    Text = "Dengan suara panggilan ini, dahi Mosha memancarkan cahaya yang kuat, cahaya ini begitu menyala, sepenuhnya menutupi darah yang memenuhi tubuh Mosha, juga menutupi cahaya dari pintu tak terlihat."
  },
  AvgDialog_123117_Content_63 = {
    Text = "Itu adalah cahaya yang dipancarkan Salvador dengan mengorbankan hidupnya."
  },
  AvgDialog_123117_Content_64 = {
    Text = "<Shake:Umm……>"
  },
  AvgDialog_123117_Content_65 = {
    Text = "Dalam cahaya yang menerangi segalanya ini, pupil yang terpecah mendapatkan kesadaran sesaat, dan dengan sisa akal sehatnya melihat punggung tangannya."
  },
  AvgDialog_123117_Content_66 = {
    Text = "Di sana sudah tidak terlihat lagi darah Salvador, karena semua darah telah menyatu."
  },
  AvgDialog_123117_Content_67 = {
    Text = "Darah korban dan pelaku, darah yang berdosa dan yang menyelamatkan, saling terjalin membentuk satu sungai darah yang sama."
  },
  AvgDialog_123117_Content_68 = {
    Text = "Saya... sudah bilang..."
  },
  AvgDialog_123117_Content_69 = {
    Text = "<Shake:Aku benci... mengorbankan orang lain... untuk menyelamatkan diri sendiri...>"
  },
  AvgDialog_123117_Content_7 = {
    Text = "Seandainya bisa mandi sebelum melintasi, pasti akan lebih baik. Kembali dengan tubuh berlumuran darah, aku tidak tahu apakah itu akan mengejutkan penyelidik."
  },
  AvgDialog_123117_Content_70 = {
    Text = [[
Moxia mendorong Salvador dengan sisa akalnya, lalu menatapmu. 
 Kamu melihat dia mengangkat kapak dengan keras, dan juga melihat air matanya mengalir deras.]]
  },
  AvgDialog_123117_Content_71 = {
    Text = "Di masa depan... jangan biarkan dia seperti ini lagi... orang seperti dia yang seharusnya hidup..."
  },
  AvgDialog_123117_Content_72 = {
    Text = "Karena alasan ritual… pintu tak terlihat menganggapku sebagai bagian darinya…"
  },
  AvgDialog_123117_Content_73 = {
    Text = "<Shake: Bunuh aku, itu akan menghilang… orang-orang itu… juga akan terbebas…>"
  },
  AvgDialog_123117_Content_74 = {
    Text = "Dan juga... ini bukan pelarian... ini adalah mati bersama musuh..."
  },
  AvgDialog_123117_Content_75 = {
    Text = "Moshia mengerahkan seluruh tenaga terakhirnya untuk menyerahkan kapak ke tanganmu, sementara kamu yang menerima kapak itu hanya bisa terdiam di tempat."
  },
  AvgDialog_123117_Content_76 = {
    Text = "Sungguh... mengapa saya juga membuat... pilihan yang tidak dapat saya pahami..."
  },
  AvgDialog_123117_Content_77 = {
    Text = "Padahal menghancurkan dunia lebih sesuai dengan gaya saya..."
  },
  AvgDialog_123117_Content_78 = {
    Text = "Moxia terisak, dan detik berikutnya, setetes air mata jatuh tanpa peringatan dari matanya, mengalir di sepanjang kapaknya, hancur di telapak tanganmu."
  },
  AvgDialog_123117_Content_79 = {
    Text = [[
Dengan cepat, kedua mata yang mengalirkan air mata mulai tampak bingung, perlahan-lahan memunculkan kegilaan. 
 Mosa akan segera kehilangan akal sehatnya.]]
  },
  AvgDialog_123117_Content_8 = {
    Text = "Apakah kita perlu menyiapkan meja dan beberapa kue kecil untuk teh sore?"
  },
  AvgDialog_123117_Content_80 = {
    Text = "Utusan pucat, tolong jangan... Aku akan menyelamatkannya lagi."
  },
  AvgDialog_123117_Content_81 = {
    Text = "Salvador berjuang untuk bangkit, memohon kepadamu, sementara kamu menunduk melihat kapak milik Mosha di tanganmu, merasa gelisah."
  },
  AvgDialog_123117_Content_82 = {
    Text = "Itu bukan sekadar sebuah kapak, tetapi juga sebuah kepercayaan kehidupan, dan perpisahan."
  },
  AvgDialog_123117_Content_83 = {
    Text = "<Shake:Beri aku sedikit waktu... pasti ada cara lain, pasti...>"
  },
  AvgDialog_123117_Content_84 = {
    Text = "Tiba-tiba, sebuah cara yang kejam muncul di benakmu —"
  },
  AvgDialog_123117_Content_85 = {
    Text = "Kamu tidak sempat berpikir panjang, satu tangan menggenggam kunci perak, satu tangan menarik tangan Moyasha, dan masuk ke dalam lumpur jiwa."
  },
  AvgDialog_123117_Content_86 = {
    Text = "Dengan Tautan kunci perak, memaksa Moyasha bertransformasi dari manusia menjadi Pembangun adalah satu-satunya cara yang dapat kamu pikirkan saat ini."
  },
  AvgDialog_123117_Content_87 = {
    Text = [[
Saat kamu terbenam dalam jiwa Mosha, banyak titik cahaya yang bergerak liar menguasai pandanganmu. 
 Mereka semua mengerang dan berteriak, tetapi tidak ada satu pun dari mereka yang adalah Mosha.]]
  },
  AvgDialog_123117_Content_88 = {
    Text = "Di dunia spiritual Mosha, tidak ada Mosha."
  },
  AvgDialog_123117_Content_89 = {
    Text = "Masha! Masha, di mana kamu……"
  },
  AvgDialog_123117_Content_9 = {
    Text = "Itu lebih hebat. Melihat dunia yang membosankan ini berantakan, kue kecil pasti akan terasa lebih lezat."
  },
  AvgDialog_123117_Content_90 = {
    Text = "Tidak ada jawaban. Sebagai orang biasa, \"permohonan\" terakhir itu sudah menjadi batas yang bisa dia lakukan di tengah kegilaan dan kehancuran."
  },
  AvgDialog_123117_Content_91 = {
    Text = "Masyah? Apakah kamu sudah menyerah? Iya, kamu pernah bilang bahwa setiap minggu akan ada beberapa kali kamu tidak ingin hidup lagi, dan selalu mengucapkan kata \"mati\"..."
  },
  AvgDialog_123117_Content_92 = {
    Text = "Namun, bukan seperti itu... Salvador, aku, dan petugas penyelidik yang selalu kamu sebut-sebut, tidak ingin hal seperti ini terjadi..."
  },
  AvgDialog_123117_Content_93 = {
    Text = "Jadi, Moyasha, keluarlah..."
  },
  AvgDialog_123117_Content_94 = {
    Text = "Namun tidak peduli seberapa keras kamu berteriak, seberapa keras kamu mencari, di sekeliling hanya ada jeritan dan teriakan yang gila."
  },
  AvgDialog_123117_Content_95 = {
    Text = "Moyasha telah \"menghilang\"."
  },
  AvgDialog_123117_Content_96 = {
    Text = "...Sebenarnya, aku telah memikirkan sebuah cara..."
  },
  AvgDialog_123117_Content_97 = {
    Text = "Ini adalah dengan memanfaatkan chip perak yang meresap ke dalam tubuhmu, mengubahmu, membuatmu menjadi Pembangun. Risiko kegagalan sangat besar, tetapi ini adalah satu-satunya cara yang bisa aku pikirkan saat ini."
  },
  AvgDialog_123117_Content_98 = {
    Text = "<Small:Aku mengira hal yang paling sulit adalah \"Membangun\", tidak menyangka, aku bahkan tidak dapat menemukan tubuh spiritualmu…>"
  },
  AvgDialog_123117_Content_99 = {
    Text = [[
Kamu terjebak dalam keheningan yang panjang, merasakan setiap napas begitu sulit. 
 Sebagai Penjaga, kamu tahu apa yang akan terjadi pada orang biasa akibat kelebihan inti perak.]]
  },
  AvgDialog_123118_Content_1 = {
    Text = "Dalam kabut yang tak berujung, terdengar jeritan menyayat hati yang terus bergema."
  },
  AvgDialog_123118_Content_10 = {
    Text = "Kasih sayang Bapa tidak dapat menyelamatkan setiap orang, tetapi kami akan memberikan bantuan kepada setiap korban sesuai kemampuan kami."
  },
  AvgDialog_123118_Content_11 = {
    Text = "<Shake:Jangan... jangan panggil lagi...>"
  },
  AvgDialog_123118_Content_12 = {
    Text = "Di bawah trauma mental, dia mulai mengalami mimisan tanpa bisa mengendalikan diri."
  },
  AvgDialog_123118_Content_13 = {
    Text = "<Shake:Aku bilang, <Big:Jangan panggil lagi…>>"
  },
  AvgDialog_123118_Content_15 = {
    Text = "Moxia berteriak dengan marah, dalam keadaan bersemangat, dia mengayunkan kapaknya untuk memotong kabut berbentuk manusia itu, tetapi kabut itu terbelah tanpa suara dan dengan cepat berkumpul kembali."
  },
  AvgDialog_123118_Content_16 = {
    Text = "Tidak berguna. Selama kabut tebal masih ada, monster-monster ini tidak akan menghilang."
  },
  AvgDialog_123118_Content_17 = {
    Text = "Jadi kamu sebelumnya membiarkan kami \"membantu\" mengalihkan perhatian monster, bukan?"
  },
  AvgDialog_123118_Content_18 = {
    Text = "Apakah kalian sekarang ingin menghitung dengan saya? Harus antre, silakan mundur sedikit……"
  },
  AvgDialog_123118_Content_19 = {
    Text = "Moxia menghapus darah dari hidungnya dan terus mengayunkan kapaknya. Perasaan bertarung membuatnya begitu bersemangat, sehingga dia sama sekali tidak bisa berhenti."
  },
  AvgDialog_123118_Content_2 = {
    Text = "@2 aku... tolong @2..."
  },
  AvgDialog_123118_Content_20 = {
    Text = "Bagaimanapun, tidak ada cara untuk mundur sekarang, lebih baik tahan serangan ini dulu!"
  },
  AvgDialog_123118_Content_21 = {
    Text = "Moyasha, berpikirlah dengan rasional! Jika terus seperti ini, kau akan……"
  },
  AvgDialog_123118_Content_22 = {
    Text = "Akan mati, ya?"
  },
  AvgDialog_123118_Content_23 = {
    Text = "Lagipula, setiap minggu aku pasti punya beberapa kali ingin mati, kebetulan..."
  },
  AvgDialog_123118_Content_24 = {
    Text = "Kata-kata Moxia terhenti tiba-tiba. Di depannya tiba-tiba ada cahaya, dan kemudian perasaan hangat menyebar ke seluruh tubuhnya, mengalir ke setiap penjuru tubuhnya."
  },
  AvgDialog_123118_Content_25 = {
    Text = "Salvador\"Berkat\"kepadanya."
  },
  AvgDialog_123118_Content_26 = {
    Text = "<Shake:Apa yang sedang kamu lakukan!?>"
  },
  AvgDialog_123118_Content_27 = {
    Text = [[
Moxia tanpa sadar mundur selangkah. 
 Perasaan hangat itu terlalu asing. Itu seharusnya tidak ada di dirinya.]]
  },
  AvgDialog_123118_Content_28 = {
    Text = "Kami, kami adalah musuh, mengapa…"
  },
  AvgDialog_123118_Content_29 = {
    Text = "Saya pernah bilang, kita bukan musuh."
  },
  AvgDialog_123118_Content_3 = {
    Text = "Tolong@2……@2aku……"
  },
  AvgDialog_123118_Content_30 = {
    Text = "Bukan musuh bukan berarti teman!"
  },
  AvgDialog_123118_Content_31 = {
    Text = "Aku tidak akan naif berpikir bahwa hanya dengan bertemu beberapa kali, aku bisa menganggap orang yang baru kutemui sebagai partner..."
  },
  AvgDialog_123118_Content_32 = {
    Text = "Tapi kita sudah pernah melawan sekte-sekte jahat itu bersama-sama, bukan? Yang berjuang berdampingan adalah rekan."
  },
  AvgDialog_123118_Content_33 = {
    Text = "Ngomong-ngomong, saya tidak menganggap ini sebagai teori membosankan di mana saya mencintai orang dan orang mencintai saya, saya lebih cenderung untuk…"
  },
  AvgDialog_123118_Content_34 = {
    Text = "Saya lebih cenderung untuk memahaminya sebagai kebijaksanaan bertahan hidup di dunia yang kejam ini."
  },
  AvgDialog_123118_Content_35 = {
    Text = "Cahaya Bapa Surgawi melimpahkan ke seluruh bumi, bahkan di tanah yang hancur, saudara-saudari akan saling membantu."
  },
  AvgDialog_123118_Content_36 = {
    Text = "Moxia menutup rapat bibirnya, terdiam tanpa suara. Tatapannya tetap waspada dan meragukan, namun akhirnya semua kewaspadaan dan keraguan itu perlahan-lahan memudar, berubah menjadi kebingungan dan sedikit kerinduan."
  },
  AvgDialog_123118_Content_37 = {
    Text = "Bibirnya bergerak-gerak, seolah-olah sedang membisikkan sesuatu, tetapi karena suaranya terlalu pelan, kamu hanya bisa mendengar dengan samar kata \"penyidik\"."
  },
  AvgDialog_123118_Content_38 = {
    Text = "Masalah kematian akan dipertimbangkan nanti, saya masih ada orang yang harus saya temui di rumah."
  },
  AvgDialog_123118_Content_39 = {
    Text = "Apakah yang kamu maksud adalah... penyelidik?"
  },
  AvgDialog_123118_Content_4 = {
    Text = "<Shake:Jangan teriak! Kabut ini... mengapa terus melolong?!>"
  },
  AvgDialog_123118_Content_40 = {
    Text = "Sebelum Moxia sempat menjawab, semacam gelombang tak terlihat tiba-tiba datang, membuat bulu kudukmu berdiri dan juga membuat monster di dalam kabut semakin ganas."
  },
  AvgDialog_123118_Content_41 = {
    Text = "Perasaan ini…<Shake:<Big:Upacara dimulai!>>"
  },
  AvgDialog_123118_Content_42 = {
    Text = "Upacara dimulai? Tapi kita jelas sudah menyelamatkan orang-orang itu."
  },
  AvgDialog_123118_Content_43 = {
    Text = "Dan, utusan pucat, tidak ada pendeta dari Kuil Kehidupan di antara para tahanan yang baru saja ditangkap..."
  },
  AvgDialog_123118_Content_44 = {
    Text = "Apakah orang yang kita selamatkan hanya cadangan? Atau apakah waktu pelaksanaan ritual itu tetap, meskipun korban tidak mencukupi, tetap harus dilaksanakan?"
  },
  AvgDialog_123118_Content_45 = {
    Text = "Sekarang tidak ada waktu untuk menjadi detektif dan menyelesaikan kasus."
  },
  AvgDialog_123118_Content_46 = {
    Text = "Apakah kalian akan terus mengoceh di sini, atau ikut saya, cepat buat keputusan!"
  },
  AvgDialog_123118_Content_47 = {
    Text = "Moxia menunjukkan ekspresi tidak sabar, berbalik, membelakangi kalian, dan melangkah ke dalam kabut tebal."
  },
  AvgDialog_123118_Content_48 = {Text = "Moyasha!"},
  AvgDialog_123118_Content_49 = {
    Text = "Aku tahu apa yang kamu khawatirkan. Kali ini aku tidak akan lagi melakukan trik apa pun."
  },
  AvgDialog_123118_Content_5 = {
    Text = "Karena kabut tebal ini, mungkin bukan \"Bencana Kabut\" di duniamu, dan monster-monster ini juga bukan \"Artefak Kuno\" yang kau sebutkan."
  },
  AvgDialog_123118_Content_50 = {
    Text = "Moxia sambil mengayunkan kapaknya untuk memecahkan kabut manusia yang menyerangnya, sambil menjawab."
  },
  AvgDialog_123118_Content_51 = {
    Text = "Meskipun optimisme kalian bermasalah dan beberapa pernyataan penuh dengan idealisme yang tidak realistis, perlu ada yang membangunkan, tetapi…"
  },
  AvgDialog_123118_Content_52 = {
    Text = [[
Tetapi selalu ada beberapa orang yang bersikeras ingin menyelamatkan dunia yang membosankan ini. 
<Small: kamu seperti itu, petugas penyelidik juga seperti itu...>]]
  },
  AvgDialog_123118_Content_53 = {
    Text = "Mungkin kalian berdua bisa saling ngobrol dengan baik, siapa tahu?"
  },
  AvgDialog_123118_Content_54 = {
    Text = "Topik sepertinya sudah agak jauh... orang-orang itu masih menunggu kita..."
  },
  AvgDialog_123118_Content_55 = {
    Text = "Jadi belum cepat lari? Semoga ini bisa segera berakhir, saya masih harus pulang."
  },
  AvgDialog_123118_Content_56 = {
    Text = "Ayo, ikuti aku, jangan ketinggalan. Aku adalah penyerang tercepat dari tim penyelidikan Kabut!"
  },
  AvgDialog_123118_Content_57 = {
    Text = "Siluet Moxia berlari kencang di tengah kabut, kamu dan Salvador bertukar pandang sejenak, lalu mengikuti."
  },
  AvgDialog_123118_Content_6 = {
    Text = "<Shake:Mereka... apa...?>"
  },
  AvgDialog_123118_Content_7 = {
    Text = "Moxia tidak bisa menahan diri untuk menutup telinganya, sayangnya itu tidak ada gunanya."
  },
  AvgDialog_123118_Content_8 = {
    Text = "Rasa sakit dan keputusasaan ini perlahan meresap ke dalam daging dan tulang pendengar melalui kabut tebal, hingga mencapai jiwa."
  },
  AvgDialog_123118_Content_9 = {
    Text = "Saya bisa membedakan bahwa jiwa mereka... adalah manusia yang dikorbankan dalam upacara terakhir."
  },
  AvgDialog_123119_Content_1 = {
    Text = "Antara Dimensi"
  },
  AvgDialog_123119_Content_10 = {
    Text = "Moxia mengangkat bahu, mengangkat tangan menunjuk pintu dimensi yang terus memuntahkan kabut tebal, mencemari dunia ini."
  },
  AvgDialog_123119_Content_100 = {
    Text = "Tidak, %player%, sebentar……"
  },
  AvgDialog_123119_Content_101 = {
    Text = "Moyasha ingin menghentikan usaha penyelamatanmu. Setelah mengetahui tentang pengalaman \"kamu\", dia dipenuhi dengan kebingungan dan pertanyaan."
  },
  AvgDialog_123119_Content_102 = {
    Text = "Tapi tidak ada waktu lagi. Sebuah tarikan dari jiwa menariknya, dengan keras membawanya menjauh dari dunia aneh yang penuh dengan bercak cahaya ini."
  },
  AvgDialog_123119_Content_103 = {
    Text = "Dan titik cahaya yang memberinya pencerahan ada di sana, tidak jauh dan tidak dekat, memancarkan niat baik yang lembut dan hangat, mengucapkan selamat tinggal terakhir padanya."
  },
  AvgDialog_123119_Content_104 = {
    Text = "Tampilkan informasi @4 kepada @3 \"saya\", kamu bisa @2 pulang @1."
  },
  AvgDialog_123119_Content_105 = {
    Text = "@2, selamat tinggal, Moyasha, @2… diri yang lain."
  },
  AvgDialog_123119_Content_106 = {
    Text = "Segera, suara berdengung yang tak terlihat itu terdistorsi, menghilang, dan akhirnya sepenuhnya lenyap, bersamaan dengan hilangnya penglihatan, pendengaran, dan berbagai indera Mosha."
  },
  AvgDialog_123119_Content_107 = {
    Text = "Ketika Mosha kembali mendapatkan pendengaran dan penglihatannya, dia melihat sosok yang sudah dikenalnya lagi, sosok yang tidak bisa dia pahami."
  },
  AvgDialog_123119_Content_108 = {
    Text = "Moshia, pergi dari sini. Aku dan Salvador akan mengurus sisanya."
  },
  AvgDialog_123119_Content_109 = {
    Text = "Pelarutan \"pintu\" semakin dalam, saya dan Utusan Pucat terpaksa bersiap untuk kemungkinan terburuk..."
  },
  AvgDialog_123119_Content_11 = {
    Text = "Jadi, saya harus pergi, hanya saya yang bisa pergi."
  },
  AvgDialog_123119_Content_111 = {
    Text = "Moxia? Kenapa melamun? Cepat tinggalkan tempat ini."
  },
  AvgDialog_123119_Content_112 = {
    Text = "Memandangmu, emosi seperti marah, kemarahan, dan belas kasihan saling berjalin di dada Mosha, membuatnya sama sekali tidak bisa mengeluarkan kata-kata."
  },
  AvgDialog_123119_Content_113 = {
    Text = "Akhirnya, dia menghembuskan napas dengan marah, menggenggam tinjunya, dan dengan enggan membuka mulut:"
  },
  AvgDialog_123119_Content_114 = {
    Text = "Sejak pertama kali bertemu, aku seharusnya sudah tahu bahwa kamu adalah jenis orang yang antusias dan suka mencampuri urusan orang lain, yaitu \"Karakter Utama\", yang selalu tidak bisa aku pahami."
  },
  AvgDialog_123119_Content_115 = {
    Text = "Meskipun seratus tahun lagi, aku tetap tidak bisa memahami jalur berpikirmu. Jadi, aku menyerah."
  },
  AvgDialog_123119_Content_116 = {Text = "Apa?"},
  AvgDialog_123119_Content_117 = {
    Text = "Saya tahu nilai gelombang yang kamu maksud, ini adalah yang lain @4@3…"
  },
  AvgDialog_123119_Content_118 = {
    Text = "Rasa sakit yang akrab menyerang, membuat kata-kata yang diucapkan oleh Moxia menjadi terdistorsi dan bermutasi. Setelah beberapa kali mencoba tetapi gagal untuk mengungkapkan kebenaran dari cahaya itu, Moxia menyerah."
  },
  AvgDialog_123119_Content_119 = {
    Text = "Gadis itu menggantikan kata-kata dengan tindakan, menggenggam tanganmu erat-erat, dengan ekspresi di wajahnya yang sangat tegas."
  },
  AvgDialog_123119_Content_12 = {
    Text = "Dalam kata-kata kalian, itu adalah... oh, kebijaksanaan bertahan hidup di dunia yang kejam ini."
  },
  AvgDialog_123119_Content_120 = {
    Text = "Aku akan menyelesaikan masalah besar ini bersamamu."
  },
  AvgDialog_123119_Content_121 = {
    Text = "Aku, Mosha, penyerang yang diperhatikan oleh tim penyelidikan, tidak akan mengakhiri pertempuran ini dengan status \"pembelot\"."
  },
  AvgDialog_123119_Content_13 = {
    Text = "Mendengarkan pernyataan Moxia, kamu dan Salvador tidak bisa tidak terdiam, lalu secara bersamaan membuka mulut —"
  },
  AvgDialog_123119_Content_14 = {
    Text = "Saya tidak setuju, anak. Yang harus berkorban adalah saya."
  },
  AvgDialog_123119_Content_15 = {
    Text = "Aku setuju. Aku berjanji akan menyelamatkanmu, atau mengantarmu pulang dengan cara apa pun, tidak peduli berapa biaya yang harus dibayar."
  },
  AvgDialog_123119_Content_16 = {
    Text = "Pada saat yang sama, kalian dan Salvador tidak bisa tidak saling memandang dengan pandangan yang sepenuhnya bertentangan."
  },
  AvgDialog_123119_Content_17 = {
    Text = "%player%, kenapa……"
  },
  AvgDialog_123119_Content_18 = {
    Text = "Baiklah, itu sudah diputuskan, urusan pulang sudah aku serahkan padamu, %player%."
  },
  AvgDialog_123119_Content_19 = {
    Text = "Mouchette memotong percakapanmu dan Salvador, sebelum kalian berdua menyadari, dia sudah berjalan menuju pintu yang tidak dikenal dan penuh tanda tanya itu."
  },
  AvgDialog_123119_Content_2 = {
    Text = "Mouchette, maksudmu, kamu ingin memasuki \"pintu\" yang tidak diketahui itu...?"
  },
  AvgDialog_123119_Content_20 = {
    Text = "Kamu menggenggam kunci perak dengan satu tangan, sementara tangan yang lain menarik Salvador dengan keras, menatap sosok Mosha dengan penuh konsentrasi, bahkan tidak berani berkedip."
  },
  AvgDialog_123119_Content_21 = {
    Text = "Salvador, dengarkan aku, mungkin... Moyasha berbeda."
  },
  AvgDialog_123119_Content_22 = {
    Text = "Ini adalah pintu yang menghubungkan ke dimensi lain, dan Moyasha, berasal dari dimensi itu, bahkan dipanggil dengan upacara yang sama."
  },
  AvgDialog_123119_Content_23 = {
    Text = "Namun... jika..."
  },
  AvgDialog_123119_Content_24 = {
    Text = "Jika ada situasi yang tidak benar, saya akan mengaktifkan kunci perak dan memindahkan tautan ke diri saya."
  },
  AvgDialog_123119_Content_25 = {
    Text = "Salvador menatap matamu yang berusaha tenang, melihatmu menggenggam kunci perak dengan erat, dan akhirnya menghela napas."
  },
  AvgDialog_123119_Content_26 = {
    Text = "Jika saat itu, mohon izinkan aku untuk berbagi beban."
  },
  AvgDialog_123119_Content_27 = {
    Text = "Utusan pucat, aku tidak akan membiarkanmu jatuh sebelum aku."
  },
  AvgDialog_123119_Content_28 = {
    Text = "Responmu adalah senyuman penuh pengertian."
  },
  AvgDialog_123119_Content_29 = {
    Text = "Sementara itu, Moyasha sedang mengangkat tangannya, mencoba menyentuh pintu tak terlihat itu."
  },
  AvgDialog_123119_Content_3 = {
    Text = "Bukan hanya kamu, bahkan Salvador juga terkejut."
  },
  AvgDialog_123119_Content_30 = {
    Text = "<Shake: Ini……>"
  },
  AvgDialog_123119_Content_31 = {
    Text = "Saat Moshia menyentuh pintu tak terlihat, pintu itu tiba-tiba memancarkan cahaya yang kuat seperti sebelumnya."
  },
  AvgDialog_123119_Content_32 = {
    Text = "Sementara itu, kamu juga mengaktifkan kunci perak."
  },
  AvgDialog_123119_Content_33 = {
    Text = "Cahaya yang memancar dari kunci perak beresonansi dengan cahaya pintu tak terlihat, lautan perak dan darah seolah dipandu oleh sesuatu yang tak terlihat, mendidih dan bergerak."
  },
  AvgDialog_123119_Content_34 = {
    Text = "Di bawah kombinasi keduanya, gema dengungan yang tidak diketahui yang dapat mengikis jiwa muncul, bercampur dengan kabut tebal yang tak ada habisnya, menghantam segala sesuatu di sekitarnya, membuat semua orang yang hadir terjebak dalam semacam kebingungan antara jiwa dan tubuh..."
  },
  AvgDialog_123119_Content_35 = {
    Text = "Dunia@2 kosong dan samar, seperti@2@1 kabut tebal, @3, ada sesuatu@2 yang berkembang di dalam kehampaan@3 ini."
  },
  AvgDialog_123119_Content_36 = {
    Text = "@1Hanya mimpi besar @4 yang tak terduga, @2 kecil ini berjuang, merayap @2, berevolusi, dan berubah menjadi @4 ras."
  },
  AvgDialog_123119_Content_37 = {
    Text = "Suara seruling yang kacau dan terdistorsi terdengar di kegelapan, menghancurkan semangat Moxia. Meskipun itu adalah suara musik, dia samar-samar melihat makna mengerikan di dalamnya."
  },
  AvgDialog_123119_Content_38 = {
    Text = "Manusia, ini adalah sebutan diri @3. @2 dibandingkan dengan @1 alam semesta yang tak berujung, @4 kecil dan lenyap dalam sekejap."
  },
  AvgDialog_123119_Content_39 = {
    Text = "@3 tidak berarti @3 tidak meninggalkan, darah dan perak @1 yang mengalir dari generasi ke generasi, jejak @4@2 sebagai bukti @1."
  },
  AvgDialog_123119_Content_4 = {
    Text = "Benar. Saya masuk, membantu kamu menyelidiki apa itu gelombang getaran."
  },
  AvgDialog_123119_Content_40 = {
    Text = "Suara seruling yang terdistorsi dan kacau semakin tajam dan menakutkan, seperti penyiksaan yang menganiaya jiwa Moxia. Dia tidak bisa menahan lagi, tiba-tiba membuka matanya."
  },
  AvgDialog_123119_Content_41 = {
    Text = "Setelah membuka mata, Moxia tidak mendengar suara seruling, juga tidak melihat ada pemain musik. Di sekelilingnya terlihat aneh, hanya ada banyak bercak cahaya yang mengelilinginya, menjaga jarak yang tidak terlalu dekat dan tidak terlalu jauh."
  },
  AvgDialog_123119_Content_42 = {
    Text = "Senang bertemu denganmu, Moyasha, \"temanku\"."
  },
  AvgDialog_123119_Content_43 = {
    Text = [[
Titik cahaya mengeluarkan bunyi berdengung, yang aneh adalah, dia sepenuhnya dapat memahaminya. 
 Atau bisa dibilang, saat ini dia juga adalah titik cahaya.]]
  },
  AvgDialog_123119_Content_44 = {
    Text = "Apakah aku sudah gugur? Ternyata gugur itu rasanya seperti ini..."
  },
  AvgDialog_123119_Content_45 = {
    Text = "Tidak, kamu masih hidup. Kamu hanya dibawa ke sini olehku. Di tubuhmu ada napas \"aku\"."
  },
  AvgDialog_123119_Content_46 = {
    Text = "Jika aku tidak melakukan ini, kau akan menderita karena melintasi Dimensi kegagalan @4, karena kau sudah @3."
  },
  AvgDialog_123119_Content_47 = {
    Text = "Mocca tidak mendengar kata-kata terakhir dari cahaya, karena pada saat suku kata yang kacau itu terdengar, kepalanya tiba-tiba sakit hebat, seolah-olah akan pecah."
  },
  AvgDialog_123119_Content_48 = {
    Text = "<Shake:Berhenti! Berhenti! Katakan sesuatu yang bisa aku dengar... Jika terus begini, kepalaku akan meledak.>"
  },
  AvgDialog_123119_Content_49 = {
    Text = "Sepertinya dia mendengar desahan cahaya, atau mungkin tidak, karena sejumlah informasi aneh membanjiri pikiran Mosha, menarik seluruh perhatiannya."
  },
  AvgDialog_123119_Content_5 = {
    Text = "Anak, kamu tidak mengerti bahaya di dalamnya, trauma dari Dimensi Roh juga akan mempengaruhi dunia nyata, kamu akan..."
  },
  AvgDialog_123119_Content_50 = {Text = "Ini apa?"},
  AvgDialog_123119_Content_51 = {
    Text = "Apa yang kalian butuhkan saat ini. Tunjukkan kepada \"aku\", {Male=dia,Female=dia} akan memahaminya."
  },
  AvgDialog_123119_Content_52 = {
    Text = "Apa yang aku, kamu, tidak bisa mengerti—"
  },
  AvgDialog_123119_Content_53 = {
    Text = "Sebentar, kamu adalah... %player%?"
  },
  AvgDialog_123119_Content_54 = {
    Text = "Ini tidak mungkin, aku baru saja melihatmu bersemangat, terlihat tidak ada masalah untuk hidup seratus tahun lagi."
  },
  AvgDialog_123119_Content_55 = {
    Text = "Bintik-bintik cahaya berdengung, mengeluarkan suara tawa kecil, Mosa tidak tahu apakah ini bisa disebut \"senyuman\", karena tidak ada rasa bahagia. Tepatnya, tidak ada emosi sama sekali."
  },
  AvgDialog_123119_Content_56 = {
    Text = "Kamu bisa menganggapnya sebagai \"aku\" dari dimensi lain, dan aku, diriku yang sebenarnya——"
  },
  AvgDialog_123119_Content_57 = {
    Text = "Seiring dengan kata-kata cahaya, banyak informasi masuk ke dalam pikiran Mosha. Informasi ini terus terpecah dan bergabung, membentuk gambaran yang tidak stabil."
  },
  AvgDialog_123119_Content_58 = {
    Text = "Pada awalnya, gambar-gambar ini abstrak dan bercak-bercak, kabur dan tidak menentu, tetapi dengan cepat—"
  },
  AvgDialog_123119_Content_59 = {
    Text = "Cahaya dan bayangan yang aneh itu berkumpul menjadi sebuah sosok, sebuah sosok yang dikenalnya."
  },
  AvgDialog_123119_Content_6 = {
    Text = "Hanya aku yang cocok di sini. Meskipun pikiranku agak sederhana, tapi aku tidak bodoh."
  },
  AvgDialog_123119_Content_60 = {
    Text = "Sosok yang akrab itu terbangun di tengah ledakan, dengan bingung menatap dunia ini."
  },
  AvgDialog_123119_Content_61 = {
    Text = "Bertahun-tahun kemudian, orang-orang menyebut ledakan ini sebagai \"Ledakan Akut\"."
  },
  AvgDialog_123119_Content_62 = {
    Text = "Kemudian, {Male=dia,Female=dia} memasuki Mythag, memperoleh Kunci Perak, menjadi \"Penjaga\", dan mulai menjalani misi bersama rekan-rekan yang disebut \"Pembangun\" untuk menyelidiki dunia yang aneh dan menakutkan ini."
  },
  AvgDialog_123119_Content_63 = {
    Text = "Seperti dia dan petugas penyelidik, serta tim penyelidikan Kabut."
  },
  AvgDialog_123119_Content_65 = {
    Text = "Mengingat orang-orang yang akrab dan masa lalu, Moxia menghela napas dengan penuh kerinduan. Dan tentang kehidupan %player%, masih berlanjut —"
  },
  AvgDialog_123119_Content_66 = {
    Text = "Dia melihat %player% melintasi kota kecil yang berselimut salju, di rumah sakit yang penuh dengan rahasia, menghadapi anjing pemburu yang melintasi ruang dan waktu, menyaksikan keabadian kasih sayang."
  },
  AvgDialog_123119_Content_67 = {
    Text = "Juga mengikuti %player% menjelajahi Cité yang dipenuhi puisi dan bunga, mendengarkan desah api, merasakan kesedihan akan layunya mawar."
  },
  AvgDialog_123119_Content_68 = {
    Text = "Masih ada kapal hantu yang melayang di lautan. Iman, dewa, pengorbanan, dia bersama %player% menyadari distorsi, kekejaman, dan kegilaan dunia ini."
  },
  AvgDialog_123119_Content_69 = {
    Text = "Namun, tidak peduli seberapa berbahayanya tempat itu, %player% dan rekan {Male=dia,Female=dia} tidak terkalahkan."
  },
  AvgDialog_123119_Content_7 = {
    Text = "Mouchette bersuara memotong ucapan Salvador, memandang kalian dengan serius."
  },
  AvgDialog_123119_Content_70 = {
    Text = "Seperti di dunia itu, bencana kabut, mayat abu, dan barang antik juga tidak dapat menjatuhkan dia dan petugas penyelidik, tidak dapat menjatuhkan Tim Penyelidikan Kabut."
  },
  AvgDialog_123119_Content_71 = {
    Text = "Ini sudah lebih baik!"
  },
  AvgDialog_123119_Content_72 = {
    Text = "Saya juga tidak tahu bagaimana kabar makhluk-makhluk kecil di dalam kabut sekarang?"
  },
  AvgDialog_123119_Content_73 = {
    Text = "Aduh, saya benar-benar ingin segelas teh hazelnut yang panas!"
  },
  AvgDialog_123119_Content_74 = {
    Text = "Moyasha tersenyum. \n Dia berpikir %player% akan bertarung selamanya dengan Pembangun —"
  },
  AvgDialog_123119_Content_75 = {
    Text = "Sudah sewajarnya seperti itu, karena dia tidak pernah berpikir untuk meninggalkan Tim Penyelidikan Kabut, dan mereka yang terbangun juga tidak akan berpikir untuk meninggalkan Para Penjaga Rahasia."
  },
  AvgDialog_123119_Content_76 = {
    Text = [[
Mereka akan bertarung, bertarung, sampai masalah dunia teratasi, atau dunia mengatasi mereka. 
 Seperti yang terjadi dalam semua cerita.]]
  },
  AvgDialog_123119_Content_77 = {
    Text = "Namun dunia ini, jauh lebih kejam daripada yang dipikirkan Moyasha, jauh lebih kejam daripada dunia tempatnya berada."
  },
  AvgDialog_123119_Content_78 = {
    Text = "<Shake:Bagaimana bisa seperti ini!!>"
  },
  AvgDialog_123119_Content_79 = {
    Text = "Jadi kamu…!?"
  },
  AvgDialog_123119_Content_8 = {
    Text = "Salvador, kemampuanmu adalah dasar bagi kita untuk tetap aman dalam kabut tebal, dan %player%, jelas sekali, kunci perakmu juga sangat penting."
  },
  AvgDialog_123119_Content_80 = {
    Text = "Kau ini, aku seharusnya tidak berharap kau akan menyerah untuk menyelamatkan dunia yang membosankan ini."
  },
  AvgDialog_123119_Content_81 = {
    Text = "Pengorbanan untuk menyelamatkan orang lain... hal semacam ini..."
  },
  AvgDialog_123119_Content_82 = {
    Text = "Mossya tidak bisa melanjutkan bicaranya, karena baik marah maupun emosi lainnya sudah tidak ada gunanya."
  },
  AvgDialog_123119_Content_83 = {
    Text = "%player% tentu adalah teman Moyasha, tetapi Moyasha hanyalah seorang pengunjung di dunia ini."
  },
  AvgDialog_123119_Content_84 = {
    Text = "Yang memisahkan keduanya bukan hanya \"dimensi\", tetapi juga dua \"dunia\" yang sama sekali berbeda."
  },
  AvgDialog_123119_Content_85 = {
    Text = "Sebenarnya, impian saya adalah duduk bersama orang yang saya cintai di dekat perapian yang nyaman, menghabiskan hidup kami yang tak ternilai."
  },
  AvgDialog_123119_Content_86 = {
    Text = "Salju di luar jendela perlahan-lahan turun, tahun demi tahun, hingga kita menghembuskan napas terakhir. Kemudian, di batu nisanku akan tertulis: {Male=dia,Female=dia} adalah seorang yang panjang umur dan bahagia, meskipun tak berguna."
  },
  AvgDialog_123119_Content_87 = {
    Text = "Hingga kini, mimpiku juga tidak pernah berubah."
  },
  AvgDialog_123119_Content_88 = {
    Text = "Kalau begitu, ayo wujudkan mimpi ini! Dunia hancur, lantas apa? Dunia yang membosankan ini, meskipun hancur, lantas apa!?"
  },
  AvgDialog_123119_Content_89 = {
    Text = "Lebih baik daripada meninggalkan penyesalan abadi, terjebak sendirian selamanya di tempat sialan ini!"
  },
  AvgDialog_123119_Content_9 = {
    Text = "Jika terjadi sesuatu padamu, tidak ada yang bisa menyelesaikan masalah itu."
  },
  AvgDialog_123119_Content_90 = {
    Text = [[
Cahaya itu tertawa ringan lagi, namun Moxia sudah tidak bisa membedakan apakah ada tawa dalam suara itu. 
 Karena hatinya dipenuhi dengan kepahitan.]]
  },
  AvgDialog_123119_Content_91 = {
    Text = "Saya juga ingin mewujudkan impian ini, sangat ingin, tetapi……"
  },
  AvgDialog_123119_Content_92 = {
    Text = "Di dunia yang kejam ini, kita selalu akan membuat beberapa \"pilihan\", beberapa pilihan yang mungkin bahkan tidak bisa kita pahami sendiri."
  },
  AvgDialog_123119_Content_93 = {
    Text = "Mungkin, itu tidak sepenuhnya tidak bisa dipahami. Meskipun saya belum pernah minum teh kacang hazel yang panas, saya juga memiliki hal-hal yang saya suka."
  },
  AvgDialog_123119_Content_94 = {
    Text = "Kue kecil Murphy, tarian Liz, bahkan tugas tambahan yang diberikan oleh Dore setiap kali, sekarang teringat juga penuh dengan kesenangan..."
  },
  AvgDialog_123119_Content_95 = {
    Text = "Cukup, jangan bicara lagi. Kau ini benar-benar tidak bisa diselamatkan..."
  },
  AvgDialog_123119_Content_96 = {
    Text = "Moyasha! Moyasha!"
  },
  AvgDialog_123119_Content_97 = {
    Text = "Tiba-tiba, sebuah suara terdengar di dalam pikiran Masha. Dan dia, langsung mengenali orang tersebut."
  },
  AvgDialog_123119_Content_98 = {
    Text = "Setelah melihat perjuangan dan pengorbanan \"{Male=dia,Female=dia}\" untuk menyelamatkan dunia, dia berpikir, dia sulit untuk melupakan suara ini, orang ini."
  },
  AvgDialog_123119_Content_99 = {
    Text = "Bertahanlah, aku dan Salvador akan segera menyelamatkanmu! Aku sudah berjanji."
  },
  AvgDialog_123120_Content_1 = {
    Text = "Mengorbankan diri sendiri"
  },
  AvgDialog_123120_Content_10 = {
    Text = "Pastor Salvador...?"
  },
  AvgDialog_123120_Content_100 = {
    Text = "Tidak tahu seberapa jauh benda setan ini akan menyebar, jika benar-benar sama dengan dunianya saya yang itu……"
  },
  AvgDialog_123120_Content_101 = {
    Text = "Moyasha tidak melanjutkan, tetapi kamu mengerti maksud tersiratnya—"
  },
  AvgDialog_123120_Content_102 = {
    Text = "Bencana kabut adalah bencana yang cukup bisa mempengaruhi sebuah dunia."
  },
  AvgDialog_123120_Content_103 = {
    Text = "Harus mengakhiri ritual ini dengan segala cara...<Shake:Salvador!>"
  },
  AvgDialog_123120_Content_104 = {
    Text = "Aku ada di sini. Aku pasti akan menjamin keselamatan kalian... dan juga akan membuat para tersesat ini mendapatkan penebusan yang sebenarnya..."
  },
  AvgDialog_123120_Content_105 = {
    Text = "Kemudian, cahaya hangat dan lembut tiba-tiba muncul di atas Salvador, menyebar ke arahmu dan Mosha, menghalangi bahaya kabut."
  },
  AvgDialog_123120_Content_106 = {
    Text = "Moyasha, untuk menutup celah ruang ini, selanjutnya aku perlu mengukur dan menentukan gelombang getaran dimensi mental, pertarungan ini akan aku serahkan padamu."
  },
  AvgDialog_123120_Content_107 = {
    Text = "Pertempuran? Tidak masalah. Selama aku di sini, kamu pasti tidak akan kehilangan sehelai pun rambut!"
  },
  AvgDialog_123120_Content_108 = {
    Text = "Setelah menahan begitu lama, akhirnya bisa meluapkan sedikit emosi—"
  },
  AvgDialog_123120_Content_109 = {
    Text = "Semua orang, tua dan muda, menyukainya!\n<Big:Berkilau☆Puting Beliung——!!>"
  },
  AvgDialog_123120_Content_11 = {
    Text = "Salvador terdiam, menarik napas dalam-dalam, lalu mengeluarkannya dengan berat."
  },
  AvgDialog_123120_Content_111 = {
    Text = "Sebuah kapak meluncur keluar, memecah sebaris sosok kabut, juga memberi jalan aman sementara untuk mendekati gerbang misterius yang terus mengeluarkan kabut tebal."
  },
  AvgDialog_123120_Content_112 = {
    Text = "Dan kamu terus mengoperasikan alat pengukur, mencoba menangkap gelombang getaran dari dimensi yang berbeda."
  },
  AvgDialog_123120_Content_113 = {
    Text = [[
Satu menit, berlalu dengan tenang. 
 Dua menit, berlalu dengan tenang.]]
  },
  AvgDialog_123120_Content_114 = {
    Text = "Kemudian tiga menit, lima menit, sepuluh menit…"
  },
  AvgDialog_123120_Content_115 = {
    Text = "Keringat jatuh dari dahimu, kau belum pernah merasakan waktu sepanjang ini."
  },
  AvgDialog_123120_Content_116 = {
    Text = "Sudah berapa lama? Aku merasa sepertinya monster-monster ini menjadi lebih kuat, harus dipukul berkali-kali untuk bisa mengalahkan mereka…"
  },
  AvgDialog_123120_Content_117 = {
    Text = "Itu adalah manifestasi dari dimensi lain yang mencoba menyerang dan melahap dunia kita, bukan? Utusan pucat?"
  },
  AvgDialog_123120_Content_118 = {
    Text = "Setetes keringat lagi jatuh dari dahimu, dalam keadaan tegang, kamu bahkan lupa untuk mengangguk."
  },
  AvgDialog_123120_Content_119 = {
    Text = "Gelombang getaran... terus berubah..."
  },
  AvgDialog_123120_Content_12 = {
    Text = "Tidak perlu mencarinya lagi, Pendeta White... ada di sini."
  },
  AvgDialog_123120_Content_120 = {
    Text = "Mungkin disebabkan oleh kabut tebal itu sendiri, atau mungkin gangguan dari jiwa yang terjebak dalam kabut... Saya butuh waktu untuk menyelidiki."
  },
  AvgDialog_123120_Content_121 = {
    Text = [[
Kamu menLihat ke atas melihat langit, pada saat ini kamu tidak dapat melihat apa pun yang disebut "bintang-bintang".
Seluruh dunia tampaknya hanya tersisa kabut tebal, serta gerbang dimensi yang terus-menerus memuntahkan kabut tebal.]]
  },
  AvgDialog_123120_Content_122 = {
    Text = "Tapi kita tidak ada waktu lagi."
  },
  AvgDialog_123120_Content_123 = {
    Text = "...Kamu benar."
  },
  AvgDialog_123120_Content_124 = {
    Text = "Kamu menyimpan alat pengukur, mengangkat tanganmu dan menggenggam kunci perak."
  },
  AvgDialog_123120_Content_125 = {
    Text = "Tampaknya, kita hanya bisa bertaruh sekali..."
  },
  AvgDialog_123120_Content_126 = {
    Text = "Utusan pucat, apakah kau ingin terhubung...?"
  },
  AvgDialog_123120_Content_127 = {
    Text = "Salvador mengerutkan alis, menatapmu dengan tidak setuju. Sedangkan kamu, hanya terdiam."
  },
  AvgDialog_123120_Content_128 = {
    Text = "Hei hei, ada satu lagi \"Tamu dari Dunia Lain\" di sini, bisakah kamu mengatakan sesuatu yang bisa aku mengerti?"
  },
  AvgDialog_123120_Content_129 = {
    Text = "Arti dari %player% adalah... menghubungkan \"pintu\" yang tidak diketahui itu, untuk memastikan gelombang getaran dimensi."
  },
  AvgDialog_123120_Content_13 = {
    Text = "Uskup di altar itu... adalah White."
  },
  AvgDialog_123120_Content_130 = {
    Text = "Apa? Barang itu sangat aneh, siapa yang tahu apa hasilnya, jangan lakukan hal bodoh."
  },
  AvgDialog_123120_Content_131 = {
    Text = "Kamu menggenggam kunci perak dengan erat, berjalan menuju gerbang cahaya yang tak terlihat dengan ekspresi serius. Saat ini, tindakan lebih berarti daripada kata-kata."
  },
  AvgDialog_123120_Content_132 = {
    Text = "Sungguh aku terkesan dengan kalian yang masih percaya bahwa dunia membosankan ini masih memiliki nilai untuk diselamatkan..."
  },
  AvgDialog_123120_Content_133 = {
    Text = "Secara mengejutkan, Mouchette mengulurkan tangannya untuk menghentikanmu. Ekspresinya yang rumit memandangmu, seolah-olah melihatmu, tetapi juga seolah-olah menembusmu, melihat orang lain."
  },
  AvgDialog_123120_Content_134 = {
    Text = "Akhirnya, semua kerumitan berubah menjadi senyuman di wajahnya, Moxia berusaha agar suaranya terdengar santai."
  },
  AvgDialog_123120_Content_135 = {
    Text = "Sudahlah, siapa suruh aku adalah penyerang yang sangat diperhatikan dalam tim penyelidikan, maju ke depan juga adalah hal yang wajar—"
  },
  AvgDialog_123120_Content_136 = {
    Text = "Jadi, biarkan aku pergi."
  },
  AvgDialog_123120_Content_137 = {
    Text = "Moxia memandangmu, dengan ekspresi yang serius dan tegas."
  },
  AvgDialog_123120_Content_138 = {
    Text = "Dari sudut sangkar, ini adalah pertama kalinya dia menunjukkan ekspresi serius seperti itu."
  },
  AvgDialog_123120_Content_14 = {Text = "Apa?!"},
  AvgDialog_123120_Content_15 = {
    Text = "Dalam keterkejutan, kamu tidak bisa tidak menoleh ke arah White, melihat mantan pendeta Gereja Kehidupan, kini pemimpin sekte, sedang berpidato dengan bersemangat."
  },
  AvgDialog_123120_Content_16 = {
    Text = "Saat ini, kami telah membuat pilihan dengan harga perak dan darah, dan tidak akan pernah menyesalinya."
  },
  AvgDialog_123120_Content_17 = {
    Text = "Untuk menuju \"Negara Damai Tanpa Penyebaran Penderitaan\", untuk menyelamatkan diri kita sendiri di dunia yang terbakar ini—"
  },
  AvgDialog_123120_Content_18 = {
    Text = "Untuk menuju \"Negara Damai Tanpa Penyebaran Penderitaan\", untuk menyelamatkan diri kita sendiri di dunia yang terbakar ini—"
  },
  AvgDialog_123120_Content_19 = {
    Text = "Belasan pengikut bintang pagi bersumpah serentak—"
  },
  AvgDialog_123120_Content_2 = {
    Text = "<Shake:Dunia ini sedang terbakar, dunia ini sedang hancur, dunia ini ditakdirkan untuk hancur.>"
  },
  AvgDialog_123120_Content_20 = {
    Text = "Sekelompok pengikut bintang-bintang pagi mengangkat pisau perak secara serempak——"
  },
  AvgDialog_123120_Content_21 = {Text = "Berhenti!"},
  AvgDialog_123120_Content_22 = {
    Text = "Dalam teriakanmu, pisau perak menusuk jantung para korban secara bersamaan, menancap dalam-dalam, dan mengaduk dengan keras."
  },
  AvgDialog_123120_Content_23 = {
    Text = "Darah yang menyilaukan memancar dari dada hewan korban, mewarnai altar dengan warna merah."
  },
  AvgDialog_123120_Content_24 = {
    Text = "Di tengah darah, kalian muncul dari Bayangan yang tersembunyi, menatap langsung ke arah White, menghadapi sumber dari semua tragedi ini."
  },
  AvgDialog_123120_Content_25 = {
    Text = "Apakah lagi orang-orang bodoh yang datang untuk menghalangi upacara Sang Bapa?"
  },
  AvgDialog_123120_Content_26 = {
    Text = "Ha, ketika bencana datang, kalian tidak peduli, tetapi ketika aku hampir memimpin saudara-saudara untuk mendapatkan penebusan, kalian ingin menghalangiku—"
  },
  AvgDialog_123120_Content_27 = {
    Text = "Pemimpin Perhimpunan Bintang Pagi tertawa dengan sinis, melihat ke arah kalian, lalu matanya tiba-tiba membelalak dan terdiam di tempat."
  },
  AvgDialog_123120_Content_28 = {
    Text = "<Shake:Uskup Salvador!?>"
  },
  AvgDialog_123120_Content_29 = {
    Text = "Wajah Salvador diliputi oleh awan gelap, kamu memperhatikan bahwa di balik jubah besar itu, tubuhnya yang tinggi dan kurus ternyata bergetar perlahan."
  },
  AvgDialog_123120_Content_3 = {
    Text = "<Shake:Satu-satunya jalan untuk penebusan adalah menuju <Yellow:\"kerajaan tenang tanpa penderitaan yang lenyap\">, yang terletak di atas kepala kita, di alam semesta yang dipenuhi bintang-bintang yang bersinar.>"
  },
  AvgDialog_123120_Content_30 = {
    Text = "White... anakku yang tersesat..."
  },
  AvgDialog_123120_Content_31 = {
    Text = "Oh, saya mengerti, anak yang datang jauh-jauh ini untuk diselamatkan oleh Yang Mulia Uskup, sebenarnya adalah pemimpin sekte! Sangat menarik!"
  },
  AvgDialog_123120_Content_32 = {Text = "Moyasha!"},
  AvgDialog_123120_Content_33 = {
    Text = "Baiklah, baiklah, aku tidak akan mengatakan apa-apa. Meskipun aku tidak mengatakan apa-apa, kenyataannya tidak akan berubah, kan?"
  },
  AvgDialog_123120_Content_34 = {
    Text = "Maka suasana menjadi sunyi, hanya darah hewan korban yang mengalir perlahan di atas altar, membasahi tanah."
  },
  AvgDialog_123120_Content_35 = {
    Text = "John, James, Anderson... mereka semua pernah menjadi rekan kerjamu."
  },
  AvgDialog_123120_Content_36 = {
    Text = "Sebagai Santuari Kehidupan... mantan pendeta, kamu seharusnya mengerti mengapa mereka datang ke Howick."
  },
  AvgDialog_123120_Content_37 = {
    Text = "...Tentu saja aku mengerti."
  },
  AvgDialog_123120_Content_38 = {
    Text = "Karena aku yang dulu, juga seperti mereka, datang ke sini dengan cita-cita yang mulia!"
  },
  AvgDialog_123120_Content_39 = {
    Text = "Suara White tiba-tiba menjadi bersemangat, menatap Salvador dengan antusias, seperti anak yang mencari pengakuan."
  },
  AvgDialog_123120_Content_4 = {
    Text = "<Shake:<Big:Temukan itu, kembali kepada itu, serahkan diri padanya! Hanya dengan cara ini, kehidupan kita akan menyambut fajar abadi——>>"
  },
  AvgDialog_123120_Content_40 = {
    Text = "Dan saya juga telah menepati janji saya, menemukan satu-satunya jalan untuk menyelamatkan saudara-saudari."
  },
  AvgDialog_123120_Content_42 = {
    Text = "Kematian bukan ajaran Sang Pencipta, White. Kau telah tersesat di jalan yang salah."
  },
  AvgDialog_123120_Content_43 = {
    Text = "<Shake:Tidak! Saya masih mengikuti petunjuk Sang Pencipta!>"
  },
  AvgDialog_123120_Content_44 = {
    Text = "Puji Bapa Surgawi, <Italic:\"Kita semua adalah anak-anak-Nya, memiliki kasih-Nya\">, <Italic:\"Cintailah satu sama lain, sebagaimana kalian mencintai diri sendiri\">."
  },
  AvgDialog_123120_Content_45 = {
    Text = "Bapa Surgawi menasihati<Italic:\"Kalian yang terhormat akan menjadi wakil-Ku, melakukan pekerjaan-Ku, untuk menghilangkan penderitaan dari bumi ini \">."
  },
  AvgDialog_123120_Content_46 = {
    Text = "...Tidak salah. Semua ini adalah kehendak Sang Pencipta."
  },
  AvgDialog_123120_Content_47 = {
    Text = "Dan aku telah berhasil. Aku akan menyelamatkan saudara-saudariku, mengakhiri penderitaan yang ditimpakan kepada mereka."
  },
  AvgDialog_123120_Content_48 = {
    Text = "Aku akan meninggalkan mereka di tanah penderitaan ini, membawa mereka menuju fajar yang bersinar di antara bintang-bintang, menuju itu —"
  },
  AvgDialog_123120_Content_49 = {
    Text = "<Yellow:<Big:\"Kerajaan damai tanpa penderitaan yang lenyap\">>."
  },
  AvgDialog_123120_Content_5 = {
    Text = "Di dalam gua yang dipenuhi simbol penodaan, pemimpin Persekutuan Fajar Bintang sedang berpidato dengan bersemangat. Begitu suaranya mereda, manusia-manusia korban ditarik ke tengah altar."
  },
  AvgDialog_123120_Content_50 = {
    Text = "Untuk menuju \"Negara Damai Tanpa Penyebaran Penderitaan\", untuk menyelamatkan diri kita sendiri di dunia yang terbakar ini—"
  },
  AvgDialog_123120_Content_51 = {
    Text = "Untuk menuju \"Negara Damai Tanpa Penyebaran Penderitaan\", untuk menyelamatkan diri kita sendiri di dunia yang terbakar ini—"
  },
  AvgDialog_123120_Content_52 = {
    Text = "Saat itu, sebuah tawa dingin seperti duri, menusuk ke dalam suara panggilan yang saleh dan teratur dari para penganut."
  },
  AvgDialog_123120_Content_53 = {
    Text = "Kerajaan damai tanpa penderitaan yang menghilang? Apakah kamu maksud dunia di balik pintu itu?"
  },
  AvgDialog_123120_Content_54 = {
    Text = "Apa lelucon ini. Duniaku tidak seindah itu."
  },
  AvgDialog_123120_Content_55 = {
    Text = "Bencana kabut, barang kuno, abu, serta berbagai monster mutasi, dan apapun yang kalian temui, cukup untuk membuat kalian minum satu kendi."
  },
  AvgDialog_123120_Content_56 = {
    Text = "Jadi, jangan lagi berbicara tentang omong kosong seperti penebusan, kalian hanya mengorbankan orang lain untuk menyelamatkan hidup kalian sendiri."
  },
  AvgDialog_123120_Content_57 = {
    Text = "<Shake: Bukan seperti ini! Karena——>"
  },
  AvgDialog_123120_Content_58 = {
    Text = "White melangkah maju satu langkah, mendekati Mosha, dengan emosional mengangkat belati berlapis perak di tangannya."
  },
  AvgDialog_123120_Content_59 = {
    Text = "Kamu secara naluriah melindungi Mosha, tetapi serangan yang diharapkan tidak terjadi."
  },
  AvgDialog_123120_Content_6 = {
    Text = "Kalian bersembunyi di bayangan tidak jauh dari situ, dengan teliti mengonfirmasi jumlah manusia yang terjebak."
  },
  AvgDialog_123120_Content_60 = {
    Text = "Target belati dari awal adalah tuannya—"
  },
  AvgDialog_123120_Content_61 = {
    Text = "Darah memercik dari jantung White, mengalir dan bercampur dengan darah dari para korban di altar merah darah."
  },
  AvgDialog_123120_Content_62 = {
    Text = "<Shake:Ini... Perak dan darah sudah cukup...>"
  },
  AvgDialog_123120_Content_63 = {
    Text = "Seiring dengan bisikan White, sebuah gelombang tak terlihat meledak dari altar."
  },
  AvgDialog_123120_Content_64 = {
    Text = "Darah yang mengalir di permukaan altar mulai bergerak, terangkat ke udara, sambil tubuh korban juga melayang ke atas."
  },
  AvgDialog_123120_Content_65 = {
    Text = "<Shake:Ah ah ah——Uskup Salvador……>"
  },
  AvgDialog_123120_Content_66 = {
    Text = "<Shake:Apakah kamu melihatnya... aku tidak mengkhianati diriku sendiri... janji kepada Tuhan Bapa...>"
  },
  AvgDialog_123120_Content_67 = {
    Text = "White berteriak, tubuhnya yang sekarat terus bergetar, perak dan darah di dalam tubuhnya diperas oleh kekuatan tak terlihat, menggambar pola aneh di langit."
  },
  AvgDialog_123120_Content_68 = {
    Text = "<Shake:Uskup, saya tahu saya telah berdosa... Saya bersedia menanggung dosa ini, bersama dengan mereka.>"
  },
  AvgDialog_123120_Content_69 = {
    Text = "<Shake:Tetapi saya tidak akan menyesal... karena saya telah menyelamatkan saudara-saudara saya di tanah yang penuh dengan penderitaan ini...>"
  },
  AvgDialog_123120_Content_7 = {
    Text = "John, James, Anderson... mereka semua ada di sini."
  },
  AvgDialog_123120_Content_70 = {
    Text = "Pandangan White terus tertuju pada Salvador. Dan Salvador, uskup yang pernah mencurahkan perhatian untuknya, perlahan-lahan menggambar tanda suci Sang Bapa di udara."
  },
  AvgDialog_123120_Content_71 = {
    Text = "Tangan yang menggambarkan tanda suci bergetar, menahan dorongan untuk \"memberkati\". Karena Salvador tahu, anak yang tersesat telah membuat pilihannya sendiri."
  },
  AvgDialog_123120_Content_72 = {
    Text = "Saya masih tidak setuju dengan tindakanmu, White, tetapi kau benar-benar menjalankan ajaran Sang Pencipta. Jadi……"
  },
  AvgDialog_123120_Content_73 = {
    Text = "Semoga Bapa mengampunimu, semoga kamu... bisa kembali ke pelukan Bapa... terlepas dari penderitaan, dan mendapatkan penebusan..."
  },
  AvgDialog_123120_Content_74 = {
    Text = "Salvador menghela napas, melakukan doa terakhir."
  },
  AvgDialog_123120_Content_75 = {
    Text = [[
Tetapi White tidak bisa mendengar lagi. 
 Ekspresinya terhenti di antara senyuman bahagia dan rasa sakit yang ekstrem, jantungnya berhenti berdetak.]]
  },
  AvgDialog_123120_Content_76 = {
    Text = "Kemudian, perak dan darah yang melayang di udara tiba-tiba bergejolak, seperti ribuan \"bintang-bintang\" yang mendidih, menerangi langit malam."
  },
  AvgDialog_123120_Content_77 = {
    Text = "Dalam cahaya yang menyilaukan dan megah ini, ribuan titik cahaya yang tidak diketahui berkumpul dan menggabungkan, membentuk sebuah pintu tak terlihat yang tidak diketahui arahnya."
  },
  AvgDialog_123120_Content_78 = {
    Text = "Inilah yang mereka sebut sebagai \"pintu\"?"
  },
  AvgDialog_123120_Content_79 = {
    Text = "Melalui itu, bisakah aku kembali ke duniamu sendiri?"
  },
  AvgDialog_123120_Content_8 = {
    Text = "Jadi, masih kurang Pastor White...?"
  },
  AvgDialog_123120_Content_80 = {
    Text = "Sangat sulit untuk dikatakan. Secara teoritis, kita bisa menghubungkan dimensi yang sama beberapa kali dengan mensimulasikan gelombang getaran yang sama, tetapi dalam praktiknya, sangat mudah terjadi kecelakaan."
  },
  AvgDialog_123120_Content_81 = {
    Text = "Terutama ritual pengorbanan seperti ini, yang penuh dengan banyak variabel, lebih mudah menimbulkan masalah—"
  },
  AvgDialog_123120_Content_82 = {
    Text = "Tunggu, jangan ke sana!"
  },
  AvgDialog_123120_Content_83 = {
    Text = "Kamu bersuara untuk menghentikan para pengikut sekte yang bergerak seragam menuju pintu tak terlihat, tetapi mereka tampaknya tidak mendengar, melanjutkan langkah dengan tenang."
  },
  AvgDialog_123120_Content_84 = {
    Text = "Untuk menuju \"Negara Damai Tanpa Penyebaran Penderitaan\", untuk menyelamatkan diri kita sendiri di dunia yang terbakar ini—"
  },
  AvgDialog_123120_Content_85 = {
    Text = "Untuk menuju \"Negara Damai Tanpa Penyebaran Penderitaan\", untuk menyelamatkan diri kita sendiri di dunia yang terbakar ini—"
  },
  AvgDialog_123120_Content_86 = {
    Text = "Akhirnya, pengikut pertama mengangkat tangannya, menyentuh pintu tak kasat mata itu, melangkah ke dunia baru yang ia dambakan."
  },
  AvgDialog_123120_Content_87 = {
    Text = "<Shake:Aaaah——>"
  },
  AvgDialog_123120_Content_88 = {
    Text = "Dalam jeritan putus asa, kedua tangan pengikut yang menyentuh pintu cahaya mulai terdistorsi dan meleleh, larut dalam cahaya terang yang tiba-tiba memancar dari pintu tak terlihat."
  },
  AvgDialog_123120_Content_89 = {
    Text = "Kemudian, kabut tebal yang tak berujung menyembur keluar dari gerbang tak berbentuk itu, melahap daging dan jiwa para pengikut, mengubah orang-orang yang mendambakan menuju bintang-bintang menjadi bagian dari \"bintang-bintang\"."
  },
  AvgDialog_123120_Content_90 = {
    Text = "Komunikator khusus mulai mengeluarkan suara dengungan yang rusak lagi, memutar bisikan yang akrab saat menjelang kematian."
  },
  AvgDialog_123120_Content_91 = {
    Text = "@2 aku... tolong @2..."
  },
  AvgDialog_123120_Content_92 = {
    Text = "Tolong@2……@2aku……"
  },
  AvgDialog_123120_Content_93 = {
    Text = "Ini adalah...<Shake:Ritualnya bermasalah!>"
  },
  AvgDialog_123120_Content_94 = {
    Text = "Salvador, hati-hati dengan monster di kabut!"
  },
  AvgDialog_123120_Content_95 = {
    Text = "Setelah suara itu terdengar, di dalam kabut tebal sekitar, berkumpul sejumlah besar kabut berbentuk manusia, meraung dan menyerang kalian."
  },
  AvgDialog_123120_Content_96 = {
    Text = "Akhirnya, keadaan menjadi menyenangkan."
  },
  AvgDialog_123120_Content_97 = {
    Text = "Moyasha——"
  },
  AvgDialog_123120_Content_98 = {
    Text = "Baiklah, saya tidak akan berbicara lagi, tetapi saya harus mengingatkanmu, bencana kabut semakin meluas."
  },
  AvgDialog_123120_Content_99 = {
    Text = "...Utusan pucat, tadi saya masih bisa melihat pemandangan di sekitar, sekarang sudah tidak bisa melihat sama sekali."
  },
  AvgDialog_123121_Content_1 = {
    Text = "Bintang yang padam"
  },
  AvgDialog_123121_Content_10 = {
    Text = "Dengan kekuatanmu, sama sekali tidak seharusnya kau terkurung oleh beberapa penyembah sesat yang payah."
  },
  AvgDialog_123121_Content_11 = {
    Text = "Dan saya rasa kita berdua telah memperhatikan, wanita ini baru saja bertanya beberapa kali tentang waktu pelaksanaan upacara, dan ekspresinya... jelas menunjukkan bahwa dia sedang menantikan sesuatu."
  },
  AvgDialog_123121_Content_12 = {
    Text = "Ah, ternyata aku terungkap di tempat-tempat ini... Aku terlalu ceroboh."
  },
  AvgDialog_123121_Content_13 = {
    Text = "Jadi, siapa kamu sebenarnya? Apa ritual itu? Apa yang kamu ketahui?"
  },
  AvgDialog_123121_Content_14 = {
    Text = "Moyasha menunjukkan senyuman santai, tidak menjawab tetapi balik bertanya —"
  },
  AvgDialog_123121_Content_15 = {
    Text = "Lalu kalian bagaimana? Kenapa kalian bisa sampai ke tempat di mana tatanan duniawi sepenuhnya runtuh, hanya tersisa kepercayaan yang membosankan?"
  },
  AvgDialog_123121_Content_16 = {
    Text = "Salvador tidak mempermasalahkan penghinaan terhadap keyakinan dalam kata-kata Mosha, hanya menunjukkan ekspresi belas kasih."
  },
  AvgDialog_123121_Content_17 = {
    Text = "Aku datang untuk penebusan."
  },
  AvgDialog_123121_Content_18 = {
    Text = "Penebusan? Penebusan untuk siapa? Orang-orang itu? Maafkan saya, kadang-kadang mati dengan cepat lebih baik daripada hidup dalam penderitaan."
  },
  AvgDialog_123121_Content_19 = {
    Text = "Terutama di dunia yang... hmm, penuh rangsangan dan menyenangkan seperti ini."
  },
  AvgDialog_123121_Content_2 = {
    Text = "Setelah mengirim sinyal ke Katedral Kehidupan, kamu dan Salvador menunggu di luar gua untuk gadis aneh yang mengaku bernama \"Moyasha\"."
  },
  AvgDialog_123121_Content_20 = {
    Text = "Berkat Sang Pencipta akan menyebar ke setiap sudut yang mendambakan penebusan."
  },
  AvgDialog_123121_Content_21 = {
    Text = "Para tahanan itu meminta bantuan kepada saya, kepada Dewan Kehidupan dalam penderitaan mereka, dan kita pasti akan memenuhi permintaan mereka."
  },
  AvgDialog_123121_Content_22 = {
    Text = "Sebagai perwakilan dari Dewa Ayah, saya akan berusaha sekuat tenaga untuk melenyapkan penderitaan dari bumi ini."
  },
  AvgDialog_123121_Content_23 = {
    Text = [[
Salvador menundukkan kepala, dengan hormat menyatukan tangan dan memberi hormat. 
 Menjawabnya adalah tawa lembut dari Mosha.]]
  },
  AvgDialog_123121_Content_24 = {
    Text = "Aku rasa, kalian semua adalah orang baik dalam arti duniawi, percaya pada omong kosong seperti aku mencintai semua orang, dan semua orang mencintai aku, bukan?"
  },
  AvgDialog_123121_Content_25 = {
    Text = "Jadi kamu bisa begitu mudah mempercayaiku, mengikuti aku ke sini..."
  },
  AvgDialog_123121_Content_26 = {
    Text = "Sungguh naif hingga membuat orang pusing."
  },
  AvgDialog_123121_Content_27 = {
    Text = "Kamu tidak bisa melihat ekspresi Mo Xia saat ini apakah itu ejekan atau rasa nostalgia, karena seberkas kabut yang entah dari mana menghalangi wajahnya."
  },
  AvgDialog_123121_Content_28 = {
    Text = "Kamu salah, kami hanya tidak ingin berprasangka buruk terhadap orang asing."
  },
  AvgDialog_123121_Content_29 = {
    Text = "Ah, tidak masalah bagaimana pun, karena kalian benar-benar tidak mengerti..."
  },
  AvgDialog_123121_Content_3 = {
    Text = "Namun ketika Mouchette muncul di ujung pandangan, dia secara tak terduga memegang sebuah kapak yang penuh dengan desain."
  },
  AvgDialog_123121_Content_30 = {
    Text = "Saat itu, suara saklar yang tiba-tiba memotong perkataan Moxia."
  },
  AvgDialog_123121_Content_31 = {
    Text = "Alat komunikasi mendeteksi fluktuasi spiritual... sumbernya adalah... kabut?!"
  },
  AvgDialog_123121_Content_32 = {
    Text = "Tanpa sadar, kabut itu terus meluas, tidak hanya menutupi sebagian besar sosok Mosha, tetapi juga menutupi pemandangan di sekitarnya."
  },
  AvgDialog_123121_Content_33 = {
    Text = "Fluktuasi spiritual? Ternyata kalian menjelaskan \"Bencana Kabut\" seperti ini…"
  },
  AvgDialog_123121_Content_34 = {
    Text = "\"Bencana kabut\"?"
  },
  AvgDialog_123121_Content_35 = {
    Text = "Tentu saja, dunia yang runtuh ini tidak akan memiliki hal yang menarik seperti itu, itu berasal dari diriku —"
  },
  AvgDialog_123121_Content_36 = {
    Text = "Dari <Yellow:Dunia Ku>."
  },
  AvgDialog_123121_Content_37 = {
    Text = "Duniamu...?"
  },
  AvgDialog_123121_Content_38 = {
    Text = "Bodoh-bodoh dari Perhimpunan Fajar Bintang telah membuka pintu terlarang yang seharusnya tidak dibuka."
  },
  AvgDialog_123121_Content_39 = {
    Text = "Kemudian ritual \"krek——\" gagal, hanya meninggalkan aku yang sial, dan mereka yang saling terjerat——"
  },
  AvgDialog_123121_Content_4 = {
    Text = "Bagaimana? Apakah sangat keren?"
  },
  AvgDialog_123121_Content_40 = {
    Text = "Sekadar mengingatkan, kalian sekarang bisa mempertimbangkan kapan untuk mulai melarikan diri."
  },
  AvgDialog_123121_Content_41 = {
    Text = "Mereka? Keluar?"
  },
  AvgDialog_123121_Content_42 = {
    Text = "Hmph☆hmph, makhluk-makhluk kecil di dalam kabut itu akan segera datang——"
  },
  AvgDialog_123121_Content_43 = {
    Text = "Selamat bersenang-senang."
  },
  AvgDialog_123121_Content_44 = {
    Text = "Sambil berbicara, Mosha mundur, bersembunyi di balik kabut tebal, hanya suaranya yang semakin jauh di dalam kabut."
  },
  AvgDialog_123121_Content_45 = {
    Text = "Masih ada, terima kasih atas bantuan kalian, kalian harus berjuang untuk mendapatkan waktu yang cukup untukku ya~"
  },
  AvgDialog_123121_Content_46 = {
    Text = "... Moyasha, tunggu!?"
  },
  AvgDialog_123121_Content_47 = {
    Text = "Kamu ingin menghentikannya, tetapi kabut tebal membuatmu sama sekali tidak tahu dari mana harus mengejarnya."
  },
  AvgDialog_123121_Content_48 = {
    Text = "Setelah berpikir, kamu menggenggam kunci perak, bersiap untuk membuka \"Penelusuran Roh\", saat itu alat komunikasi mengeluarkan suara lagi."
  },
  AvgDialog_123121_Content_49 = {
    Text = "Itu adalah suara arus listrik yang bising dan menyakitkan, semakin keras dan semakin jelas di dalam kabut tebal yang terus bergerak."
  },
  AvgDialog_123121_Content_50 = {
    Text = "@2 aku... tolong @2..."
  },
  AvgDialog_123121_Content_51 = {Text = "…!?"},
  AvgDialog_123121_Content_52 = {
    Text = "Salvador, apakah kamu mendengarnya?"
  },
  AvgDialog_123121_Content_53 = {
    Text = "Itu sepertinya... suara manusia?"
  },
  AvgDialog_123121_Content_54 = {
    Text = "Mendengar kata-kata ini, kamu mengambil alat komunikasi, menunggu suara berikutnya, dan alat komunikasi pun memberikan balasan—"
  },
  AvgDialog_123121_Content_55 = {
    Text = "Sebuah teriakan putus asa yang cukup untuk menembus gendang telinga, seperti mata pisau yang menusuk kepalamu, membuatmu seketika merasa pusing dan bingung."
  },
  AvgDialog_123121_Content_56 = {
    Text = "Sementara itu, dari dalam kabut tebal muncul berbagai bentuk kabut humanoid yang tak terhitung jumlahnya, mengaum dan menyerangmu serta Salvador."
  },
  AvgDialog_123121_Content_57 = {Text = "Hati-hati!"},
  AvgDialog_123121_Content_58 = {
    Text = "Batu tulis melintasi kabut tebal, menghancurkan monster yang terbuat dari kabut, tetapi jeritan menyedihkan itu tetap ada, tiada henti, menghantam jiwa Anda."
  },
  AvgDialog_123121_Content_59 = {
    Text = "Darah terus-menerus jatuh dari rongga hidungmu, memercik di tanah, namun kamu tidak bisa melihat dengan jelas karena pusing."
  },
  AvgDialog_123121_Content_6 = {
    Text = "Moxia mengayunkan kapak beberapa kali, gerakannya bersih dan cepat, seolah-olah senjata besar ini adalah bagian dari dirinya yang selalu bersamanya——"
  },
  AvgDialog_123121_Content_60 = {
    Text = "Rohmu tampaknya terlepas dari tubuh, terus meluas dalam keadaan yang tak berbentuk dan kacau, merasakan desa tempatmu berada."
  },
  AvgDialog_123121_Content_61 = {
    Text = "Kamu merasakannya—kabut tebal yang ada di mana-mana dengan sembarangan menelan tanah, bangunan, dan jejak keberadaan manusia atau makhluk bukan manusia."
  },
  AvgDialog_123121_Content_62 = {
    Text = "Dan di dalam kabut tebal yang tak berujung ini, tak terhitung bintang-bintang membakar dingin dalam keheningan, jelas sudah mati sejak lama."
  },
  AvgDialog_123121_Content_63 = {Text = "%player%!"},
  AvgDialog_123121_Content_64 = {
    Text = "Suara Salvador bergema di dalam pikiranmu, tetapi keputusasaan dan rasa sakit yang menjalar dari kedalaman jiwamu membuatmu tak berdaya."
  },
  AvgDialog_123121_Content_65 = {
    Text = "@2 aku... tolong @2..."
  },
  AvgDialog_123121_Content_66 = {
    Text = "Tolong@2……@2aku……"
  },
  AvgDialog_123121_Content_67 = {
    Text = "Bintang-bintang yang telah mati membawa keputusasaan dan penderitaan yang tak berujung, mengelilingi kamu, dengan keras mencairkan kamu, menggerogoti kamu, berusaha menarikmu ke tempat tidur abadi."
  },
  AvgDialog_123121_Content_68 = {
    Text = "...Tidak bisa tertidur seperti ini, Sal..."
  },
  AvgDialog_123121_Content_69 = {
    Text = "Sal... Salvador... tolong aku..."
  },
  AvgDialog_123121_Content_7 = {
    Text = "Setelah menyadari hal ini, kamu meluncurkan serangan."
  },
  AvgDialog_123121_Content_70 = {
    Text = "Tepat pada saat itu, cahaya yang lembut bersinar di duniamu, seperti matahari yang paling hangat, memelukmu dengan erat, mengusir segala kedinginan dan rasa mati."
  },
  AvgDialog_123121_Content_71 = {
    Text = "Itu adalah cahaya yang berasal dari Salvador."
  },
  AvgDialog_123121_Content_72 = {
    Text = "Dia telah mendengar permohonanmu."
  },
  AvgDialog_123121_Content_73 = {
    Text = "Dia telah menanggapi permintaanmu."
  },
  AvgDialog_123121_Content_74 = {
    Text = "<Shake:Batuk batuk……>"
  },
  AvgDialog_123121_Content_75 = {
    Text = "Dengan bantuan Salvador, kamu akhirnya keluar dari pusing yang membingungkan itu. Kamu berusaha keras bernapas, menghela napas dalam-dalam, dan merasa sedikit mendapatkan kembali akal sehatmu."
  },
  AvgDialog_123121_Content_76 = {
    Text = "Salvador, Anda bisa berhenti memberikan Berkat, saya sudah, jauh lebih baik."
  },
  AvgDialog_123121_Content_77 = {
    Text = "Salvador mengangguk, sepenuh hati terlibat dalam pertempuran melawan ancaman tak dikenal di dalam kabut."
  },
  AvgDialog_123121_Content_78 = {
    Text = "Monster-monster di dalam kabut ini tidak akan mati. Meskipun terpecah, mereka akan segera muncul kembali."
  },
  AvgDialog_123121_Content_79 = {
    Text = "Sayangnya, selama kabut ini masih ada, monster-monster ini akan hidup selamanya."
  },
  AvgDialog_123121_Content_8 = {
    Text = "Mouchette, kamu adalah sukarela ditangkap oleh para penganut sekte."
  },
  AvgDialog_123121_Content_80 = {
    Text = "Pastor Salvador, apakah kamu pikir apa yang Moyasha katakan barusan... itu benar?"
  },
  AvgDialog_123121_Content_81 = {
    Text = "Sejak pertemuan dimulai, api jiwa Nona Moyasha tetap konstan. Dari yang saya lihat, dia tidak menunjukkan tanda-tanda berbohong, dan juga tidak memiliki motif untuk berbohong."
  },
  AvgDialog_123121_Content_82 = {
    Text = "Jadi, aku punya beberapa dugaan. Namun, kita harus menemukan Moyasha terlebih dahulu."
  },
  AvgDialog_123121_Content_83 = {
    Text = "Saya menghormati keputusanmu, utusan yang pucat."
  },
  AvgDialog_123121_Content_84 = {
    Text = "Tidak perlu khawatir tentang monster-monster di kabut ini, aku pasti akan menjamin keselamatanmu."
  },
  AvgDialog_123121_Content_85 = {
    Text = "Kamu melihat Salvador dengan penuh rasa syukur, lalu mengalihkan tanganmu ke kunci perak."
  },
  AvgDialog_123121_Content_86 = {
    Text = "Darah kembali jatuh dari pipimu, tetapi kamu tidak bergerak, dugaan mengerikan saat pusing tadi menguasai seluruh kesadarannya."
  },
  AvgDialog_123121_Content_87 = {
    Text = "@2 aku... tolong @2..."
  },
  AvgDialog_123121_Content_88 = {
    Text = "Tolong@2……@2aku……"
  },
  AvgDialog_123121_Content_89 = {
    Text = "Akhirnya, saat komunikator kembali mengeluarkan suara bising, kamu melewati banyak bintang mati yang dingin, dan menyentuh entitas roh Moyasha."
  },
  AvgDialog_123121_Content_9 = {
    Text = "Hm? Apakah kamu bercanda? Orang normal tidak akan dengan sukarela menjadi tahanan penyembah sesat, terkurung dalam kandang tanpa makan dan minum."
  },
  AvgDialog_123122_Content_1 = {
    Text = "Melalui kedua matamu"
  },
  AvgDialog_123122_Content_10 = {
    Text = "Saya sedang sibuk, tidak ada waktu untuk bermain permainan rumah-rumahan yang membosankan, dan tidak tertarik untuk berperan sebagai anak perempuan yang diajari."
  },
  AvgDialog_123122_Content_11 = {
    Text = "Kau tidak memahami dunia ini, dan tidak tahu harga dan efek sebenarnya dari ritual Perhimpunan Bintang Fajar."
  },
  AvgDialog_123122_Content_12 = {
    Text = "Dengan kata lain, para tahanan yang tadi terkurung bersamamu, adalah persembahan yang tidak dapat dihindari untuk ritual berikutnya."
  },
  AvgDialog_123122_Content_13 = {
    Text = "Lagipula, meskipun ritual diadakan lagi, kamu tidak tahu apakah pintu antara dua dunia akan terbuka lagi, dan apakah kamu bisa melewatinya untuk kembali ke duniamu."
  },
  AvgDialog_123122_Content_14 = {
    Text = "Gerakan Moyasha terhenti, kemudian dia menggigit bibirnya dengan erat."
  },
  AvgDialog_123122_Content_16 = {
    Text = "Anak, aku tahu kamu tidak datang ke dunia yang kejam ini dengan sukarela, dan aku memahami perasaanmu ingin kembali."
  },
  AvgDialog_123122_Content_17 = {
    Text = "Kami hanya berharap bisa membantu kamu, menghindarkanmu dari jalan yang salah."
  },
  AvgDialog_123122_Content_18 = {
    Text = "Kau bilang, aku ingin kembali ke dunaku melalui upacara Perhimpunan Bintang Fajar, itu adalah jalan yang salah?"
  },
  AvgDialog_123122_Content_19 = {
    Text = "Sikap Mo Xia yang baru saja melunak tampaknya kembali menjadi keras, nada suaranya dipenuhi dengan ejekan yang tajam."
  },
  AvgDialog_123122_Content_2 = {
    Text = "Kalian, bagaimana kalian bisa menemukanku?!"
  },
  AvgDialog_123122_Content_20 = {
    Text = "Kabut tebal di sekitar mulai bergejolak dan bergerak."
  },
  AvgDialog_123122_Content_21 = {
    Text = "Jadi apa itu jalan yang benar? Siapa yang menentukan apa itu jalan yang benar? Kamu, atau Tuhanmu?"
  },
  AvgDialog_123122_Content_22 = {
    Text = "Penyamaran sudah terlepas, Moyasha tidak ragu menunjukkan penghinaan dan meremehkannya terhadap para penganut keyakinan seperti Salvador."
  },
  AvgDialog_123122_Content_23 = {
    Text = "Apa gunanya menilai benar dan salah? Aku melihat dunia ini lebih tandus dan tidak layak dibandingkan Taimulan."
  },
  AvgDialog_123122_Content_24 = {
    Text = "Ketika orang-orang itu menderita, di mana \"Sang Pencipta\" yang ada di mulutmu?"
  },
  AvgDialog_123122_Content_25 = {
    Text = "Kabut tebal semakin bergelora, menutupi wajah Moxia, juga menutupi ekspresi Salvador."
  },
  AvgDialog_123122_Content_26 = {
    Text = "Satu-satunya yang bisa kamu dengar di dalam kabut ini adalah helaan napas Salvador dan suara aneh yang menandakan bahaya semakin mendekat."
  },
  AvgDialog_123122_Content_27 = {Text = "Aku..."},
  AvgDialog_123122_Content_28 = {
    Text = "Bicara saja, pendeta, lagipula sedang tidak ada kerjaan."
  },
  AvgDialog_123122_Content_29 = {
    Text = "Begitu suara Moxia terdengar, kabut di sekitar seolah pecah dan mengeluarkan sejumlah sosok berbentuk manusia, mendekati kalian."
  },
  AvgDialog_123122_Content_3 = {
    Text = "Apa kabut yang baru saja muncul ada kesalahan? Atau... apakah kalian juga memiliki kemampuan untuk melihat kabut seperti para penyelidik?"
  },
  AvgDialog_123122_Content_30 = {
    Text = "Namun, gerakan Moxia lebih cepat daripada kabut sosok-sosok itu. Melihatnya ingin melarikan diri, kamu tidak bisa menahan diri untuk berteriak."
  },
  AvgDialog_123122_Content_31 = {
    Text = "Salvador, halangi dia!"
  },
  AvgDialog_123122_Content_4 = {
    Text = "Keterkejutan Moxia tidak berlangsung lama, dalam sekejap, ekspresinya menjadi tenang."
  },
  AvgDialog_123122_Content_5 = {
    Text = "Kalian memang memiliki beberapa cara untuk melepaskan diri dari barang-barang kuno di dalam kabut. Tetapi—"
  },
  AvgDialog_123122_Content_6 = {
    Text = "<Big:<Shake:Jangan mengganggu aku melakukan hal yang serius!>>"
  },
  AvgDialog_123122_Content_7 = {
    Text = "Moxia berkata sambil memegang erat kapaknya, tatapannya penuh kewaspadaan dan permusuhan."
  },
  AvgDialog_123122_Content_8 = {
    Text = "Moyasha, kamu tidak perlu seperti ini, kita bukan musuh. Setidaknya tidak sekarang."
  },
  AvgDialog_123122_Content_9 = {
    Text = "Tapi sebelum kamu membuat keputusan, saya memiliki satu pesan yang harus saya sampaikan kepadamu."
  },
  AvgDialog_125040_Content_1 = {
    Text = "Banjir Sungai Suci membawa masalah yang belum pernah terjadi sebelumnya bagi Mythag, secara mengejutkan, kamar Xu ternyata menjadi salah satu dari sedikit tempat yang bisa kamu gunakan untuk berlindung."
  },
  AvgDialog_125040_Content_10 = {
    Text = "Hamba bisa menjadi sebuah kebohongan, sebuah angan-angan, hanya ketika hamba adalah diri hamba sendiri... sangat membosankan."
  },
  AvgDialog_125040_Content_11 = {Text = "Eh... Xu?"},
  AvgDialog_125040_Content_12 = {Text = "Kabut."},
  AvgDialog_125040_Content_13 = {
    Text = "Kabut tipis, seperti sutra dan benang, melingkari dirimu dengan berlapis-lapis."
  },
  AvgDialog_125040_Content_14 = {
    Text = "<LightGray:Apakah tidak ada pengaruhnya? Bukankah kita sedang berbincang sambil bermain catur! Kalian Pembangun, mengapa semua, berkata satu hal dan melakukan hal lain!>"
  },
  AvgDialog_125040_Content_15 = {
    Text = "Seperti bayangan emas yang berkilau melintas dari cahaya sisa, sentuhan seperti sutra mengikat lengan dan punggungmu, membimbingmu untuk mengangkat tirai yang terbuat dari kabut."
  },
  AvgDialog_125040_Content_16 = {
    Text = "Aduh, karena aku benar-benar, benar-benar penasaran."
  },
  AvgDialog_125040_Content_17 = {
    Text = "Ketika mereka menyentuhku, yang mereka sentuh adalah fatamorgana. Ketika mereka memandangiku, itu adalah melalui diriku, melihat orang yang mereka \"anggap\" sebagai orang yang mereka cintai."
  },
  AvgDialog_125040_Content_18 = {
    Text = "Tetapi Anda berbeda, apakah Anda memiliki bayangan siapa pun? Jika Anda menyelidiki lebih dalam, wajah siapa yang akan Anda lihat di bawah kipas saya...?"
  },
  AvgDialog_125040_Content_19 = {
    Text = "Kabut terangkat, di bawah permukaan kipas, sesuatu yang hangat menyentuh lembut ujung hidungmu, bulu halus di bahu wanita itu jatuh, lembut membelai kulitmu yang bergetar tanpa alasan."
  },
  AvgDialog_125040_Content_2 = {
    Text = "Sungai Suci benar-benar tidak memberikan pengaruh padamu?"
  },
  AvgDialog_125040_Content_20 = {
    Text = "<LightGray:Bagus sekali, membara, satu lagi.>"
  },
  AvgDialog_125040_Content_21 = {
    Text = "Xu, jika saya tidak salah ingat, yang kamu katakan barusan adalah,\"tidak ada pikiran yang mengganggu\"."
  },
  AvgDialog_125040_Content_22 = {
    Text = "Ya, di negeri Timur Jauh, jika seorang penguasa memiliki urusan penting untuk dibicarakan dengan seseorang, dia akan mengundang orang itu masuk ke dalam tirai, oleh karena itu disebut sebagai — tamu yang masuk."
  },
  AvgDialog_125040_Content_23 = {
    Text = "Namun, bagi wanita, tamu yang masuk memiliki makna lain."
  },
  AvgDialog_125040_Content_24 = {
    Text = "<Shake:——Dah.>"
  },
  AvgDialog_125040_Content_25 = {
    Text = "Satu tetes lilin jatuh di meja, bidak-bidak berserakan."
  },
  AvgDialog_125040_Content_26 = {
    Text = "Cahaya telah padam."
  },
  AvgDialog_125040_Content_27 = {
    Text = "Hamba biasanya hanya perlu berada di luar, hanya Anda mungkin akhirnya bisa melihat hamba."
  },
  AvgDialog_125040_Content_28 = {
    Text = "Hanya Anda yang membuat hamba bersedia berada di balik tirai, menghadapi tamu yang mungkin paling penting dalam hidup hamba, bagaimana mungkin timbul \"pikiran yang tidak diinginkan\"?"
  },
  AvgDialog_125040_Content_29 = {
    Text = "Belenggu menghilang, dewa kuno dan misterius ini jelas memberikanmu jalan keluar."
  },
  AvgDialog_125040_Content_3 = {
    Text = "Entah apakah karena sumber kekuatan berasal dari tiga plasmid yang sama, atau karena terlalu mahir dalam seni kesenangan, sepertinya aku tidak memiliki pikiran yang mengganggu."
  },
  AvgDialog_125040_Content_30 = {
    Text = "Dan juga undangannya yang penuh kebahagiaan, hampir tidak terdengar, sulit dibedakan antara yang asli dan yang palsu."
  },
  AvgDialog_125040_Content_31 = {
    Text = "Hamba terjatuh ke laut yang dalam, meminta daratan tetapi tidak mendapat……"
  },
  AvgDialog_125040_Content_4 = {
    Text = "Sepasang mata yang indah itu dipenuhi dengan senyuman, beberapa pion putih dengan ringan saling mengetuk di papan catur, pemiliknya sangat antusias menggunakan permainan kuno yang berasal dari Timur ini untuk mengisi waktu."
  },
  AvgDialog_125040_Content_5 = {
    Text = "Manusia adalah makhluk yang sangat aneh, akan kehilangan penampilan demi kesenangan sesaat, dan setelah mendapatkannya, segera menunjukkan ekspresi yang tidak tertarik."
  },
  AvgDialog_125040_Content_6 = {
    Text = "Tahun demi tahun pasti terlihat, tahun demi tahun saling jenuh. Hanya dengan menenun ilusi untuk mereka, membuat mereka melupakan hidup dan mati, merobek hati dan mengMenggali hati, mereka tidak akan pernah bisa melupakan."
  },
  AvgDialog_125040_Content_7 = {
    Text = "Cahaya lilin yang bergetar menggambarkan wanita yang duduk di tempat tidur, siluetnya samar dan gelap."
  },
  AvgDialog_125040_Content_8 = {
    Text = "Langit sudah sepenuhnya gelap tanpa diketahui kapan, dia mengeluarkan tawa kecil."
  },
  AvgDialog_125040_Content_9 = {
    Text = "Mendorong keluarga baik untuk terjun ke dunia malam, menyarankan @2 untuk kembali ke jalan yang benar. Hamba sangat mahir dalam drama seperti ini, menyusun sebuah cerita yang setengah benar setengah salah, lalu membiarkan mereka melihat wajah ini di bawah kipas, yang penuh penyesalan atau cinta yang tak terbalas."
  },
  AvgDialog_126907_Content_1 = {
    Text = "Kembang Api Masa Lalu"
  },
  AvgDialog_126907_Content_10 = {
    Text = "Kalau begitu, silakan."
  },
  AvgDialog_126907_Content_11 = {
    Text = "Elsa menatapmu dengan mata berbinar, menarikmu dengan kuat, dan dengan cepat memulai tarian yang seharusnya kamu pimpin."
  },
  AvgDialog_126907_Content_12 = {
    Text = "Kekuatan dia begitu besar, hampir membuatmu terlempar, dia dengan panik menarikmu kembali dengan menggunakan might."
  },
  AvgDialog_126907_Content_13 = {
    Text = "<Shake:Iya, maaf>,Tuan Lord, lain kali saya pasti akan mengendalikan diri dengan baik..."
  },
  AvgDialog_126907_Content_14 = {
    Text = "Kamu merasa seperti sebuah gasing yang dipukul bolak-balik, berputar tanpa henti, langkah tari yang sudah tidak mahir menjadi semakin canggung."
  },
  AvgDialog_126907_Content_15 = {Text = "Pshii."},
  AvgDialog_126907_Content_16 = {
    Text = "Melihat situasimu yang canggung, Ramona tidak bisa menahan tawa kecil."
  },
  AvgDialog_126907_Content_17 = {
    Text = "Kamu bertemu pandangannya, kamu merasakan tatapannya yang penuh senyuman sedang berbisik padamu——"
  },
  AvgDialog_126907_Content_18 = {
    Text = "Lord Dexter, kau juga memiliki hari ini."
  },
  AvgDialog_126907_Content_2 = {
    Text = "Di lantai dansa, pemuda dan gadis yang mengenakan seragam sekolah sedang berputar dengan anggun. Suara musik mengalir seperti air, melintasi telapak tangan yang bersentuhan, rok yang sedikit terangkat, dan tatapan yang saling bertukar."
  },
  AvgDialog_126907_Content_20 = {
    Text = "Setelah lagu berakhir, kamu segera memberi cium tangan sebagai salam perpisahan kepada pasangan dansamu, lalu langsung menuju Ramona."
  },
  AvgDialog_126907_Content_21 = {
    Text = "Saya ingat kamu disebut sebagai profesor yang paling anggun dalam tari sosial di seluruh Universitas Mythag, Lord Dexter."
  },
  AvgDialog_126907_Content_22 = {
    Text = "Kamu menggali perutmu, mencoba untuk menampilkan balasan licik Lord Dexter."
  },
  AvgDialog_126907_Content_23 = {
    Text = "Saya pikir, jika diadakan kompetisi \"Menari Bersama Elsa\", saya tetap akan menjadi pemenangnya."
  },
  AvgDialog_126907_Content_24 = {
    Text = "Ramona mengalihkan pandangannya, sambil perlahan menggoyangkan gelas tinggi di tangannya."
  },
  AvgDialog_126907_Content_25 = {
    Text = "Elsa sangat mengagumimu. Meskipun tarian ini tidak sempurna, bisa dianggap sebagai wujud dari keinginannya pada Perayaan Tahun Baru."
  },
  AvgDialog_126907_Content_26 = {
    Text = "Sayangnya, orang yang menari bersamanya bukanlah Tuan Mulia Dexter yang sebenarnya."
  },
  AvgDialog_126907_Content_27 = {
    Text = "Lebih mengerikan lagi, meskipun tanpa adegan kamu yang dirasuki hantu, orang yang dia kenal juga bukanlah Tuan Mulia Dexter yang sebenarnya."
  },
  AvgDialog_126907_Content_28 = {
    Text = "Tapi ini bukan topik yang ingin kamu bahas."
  },
  AvgDialog_126907_Content_29 = {
    Text = "Ramona, apakah kamu punya harapan Perayaan Tahun Baru?"
  },
  AvgDialog_126907_Content_3 = {
    Text = "Kamu memperhatikan bahwa Ramona berdiri sendirian di samping meja kecil di luar lantai dansa, menyeruput minuman yang tidak diketahui namanya."
  },
  AvgDialog_126907_Content_30 = {
    Text = "Apakah peran yang kamu mainkan telah berubah? Tidak pergi menyapa Nyonya ini atau Nyonya itu, malah datang untuk mengkhawatirkan anak angkatmu?"
  },
  AvgDialog_126907_Content_31 = {
    Text = "Saya lihat kamu tidak pernah pergi menari, apakah tidak ada pasangan dansa yang kamu sukai?"
  },
  AvgDialog_126907_Content_32 = {
    Text = "Tidak perlu repot-repot."
  },
  AvgDialog_126907_Content_33 = {
    Text = "Maukah Anda memberi kesempatan untuk menari dengan ayah yang kesepian?"
  },
  AvgDialog_126907_Content_34 = {
    Text = "Ramona diam. Kamu tahu dia sedang mencari alasan di dalam istana pikirannya."
  },
  AvgDialog_126907_Content_35 = {
    Text = "Orang yang kamu tunggu, juga berharap kamu bisa menerima undangan tari ini."
  },
  AvgDialog_126907_Content_36 = {
    Text = "Bagaimana kau tahu?"
  },
  AvgDialog_126907_Content_37 = {
    Text = "Aku sudah tahu."
  },
  AvgDialog_126907_Content_38 = {
    Text = "Keheningan yang lebih panjang."
  },
  AvgDialog_126907_Content_39 = {
    Text = "Lupakan saja, aku percaya padamu sekali."
  },
  AvgDialog_126907_Content_4 = {
    Text = "Kamu sedang berpikir alasan apa yang tepat untuk memulai percakapan, sebuah suara yang ragu-ragu terdengar di sampingmu."
  },
  AvgDialog_126907_Content_40 = {
    Text = "Dia melangkah ringan ke dalam lantai dansa, jari-jarinya yang ramping menyentuh telapak tanganmu."
  },
  AvgDialog_126907_Content_41 = {
    Text = "Ayo, aku belum pernah menari denganmu."
  },
  AvgDialog_126907_Content_43 = {
    Text = "Langkah tari Ramona bagaikan kepribadiannya—rasional, menahan diri, tepat, dan teliti."
  },
  AvgDialog_126907_Content_44 = {
    Text = "Kamu bisa lebih santai, sepertinya kamu menganggap lantai dansa sebagai medan perang."
  },
  AvgDialog_126907_Content_45 = {
    Text = "Dan kamu bisa lebih serius, Lorde yang mulia. Sejak mulai menari sampai sekarang, kamu hampir menginjak kakiku tiga kali."
  },
  AvgDialog_126907_Content_46 = {
    Text = "Ini tidak seperti Tuan Mulia Dexter yang telah bergaul di dunia sosial selama puluhan tahun."
  },
  AvgDialog_126907_Content_47 = {
    Text = "Mungkin kadang-kadang aku juga ingin berperan sedikit berbeda?"
  },
  AvgDialog_126907_Content_48 = {Text = "Benarkah?"},
  AvgDialog_126907_Content_49 = {
    Text = "Kamu tahu tidak? Hari ini kamu terlalu tenang, ada yang tidak beres."
  },
  AvgDialog_126907_Content_5 = {
    Text = "<Shake:<Small:Lorde Dexter… bisakah aku menari denganmu?>>"
  },
  AvgDialog_126907_Content_50 = {
    Text = "<LightGray:Saya pikir saya sudah mengembalikannya dengan baik…>"
  },
  AvgDialog_126907_Content_51 = {
    Text = "Benarkah? Mungkin karena cuacanya terlalu dingin, membuat orang tidak ingin berbicara."
  },
  AvgDialog_126907_Content_52 = {
    Text = "Jika itu Tuan Mulia Dexter, dia pasti akan berkata: menggoda anak angkat sendiri adalah hal yang sangat tabu, lho."
  },
  AvgDialog_126907_Content_53 = {
    Text = "<Yellow:Siapa kamu sebenarnya?>"
  },
  AvgDialog_126907_Content_54 = {
    Text = "Ramona, waktu untuk bertemu denganmu terlalu singkat, aku tidak ingin..."
  },
  AvgDialog_126907_Content_55 = {
    Text = "Terdengar suara batuk Xu yang lembut di telinga."
  },
  AvgDialog_126907_Content_56 = {
    Text = "Tidak usah membicarakan itu, lihat!"
  },
  AvgDialog_126907_Content_59 = {
    Text = "Dalam sekejap, kembang api meluncur ke udara."
  },
  AvgDialog_126907_Content_6 = {
    Text = "Eh? Kenapa ini?"
  },
  AvgDialog_126907_Content_62 = {
    Text = "Di atas kepala mekar pohon api berbunga emas yang berkelanjutan."
  },
  AvgDialog_126907_Content_64 = {
    Text = "Seperti hari upacara pemberian kunci, kamu menggenggam tangan Ramona."
  },
  AvgDialog_126907_Content_66 = {
    Text = "Dalam ekspresi terkejutnya, kamu menutup kedua matamu."
  },
  AvgDialog_126907_Content_68 = {
    Text = "Dalam kegelapan, suara-suara yang penuh dengan kegembiraan atau harapan terdengar bertumpuk:"
  },
  AvgDialog_126907_Content_69 = {
    Text = "<Big:<Shake:\"Selamat Perayaan Tahun Baru!\">>"
  },
  AvgDialog_126907_Content_7 = {
    Text = "Mereka semua tidak mau menari denganku... mereka bilang merasa berbahaya."
  },
  AvgDialog_126907_Content_70 = {
    Text = "Selamat Perayaan Tahun Baru, Ramona."
  },
  AvgDialog_126907_Content_71 = {
    Text = "Tepat pukul nol, suara angin menderu, semua cerita yang seharusnya menjadi milikmu semakin menjauh darimu."
  },
  AvgDialog_126907_Content_72 = {
    Text = "Tapi kamu tahu, hari reuni itu tidak akan terlalu jauh lagi."
  },
  AvgDialog_126907_Content_8 = {
    Text = "Namun, tenang saja! Aku akan berusaha mengontrol kekuatanku dengan baik!"
  },
  AvgDialog_126907_Content_9 = {
    Text = "Pandanganmu melintasi sosok kecil yang menyusut dari atas ke bawah."
  },
  AvgDialog_126908_Content_1 = {
    Text = "Kamar Kegelapan Abadi"
  },
  AvgDialog_126908_Content_10 = {
    Text = "Senyumnya dan sosoknya menghilang samar, tersebar di dalam angin yang lenyap menjadi debu."
  },
  AvgDialog_126908_Content_11 = {
    Text = "Pergilah, ambil barang rampasanmu."
  },
  AvgDialog_126908_Content_12 = {
    Text = "Di balik kabut dan abu, terlihat sebuah pintu — pintu menuju ruang kemudi kereta."
  },
  AvgDialog_126908_Content_13 = {
    Text = "Tidak ada tipu daya, tidak ada pegas, tidak ada yang berlebihan."
  },
  AvgDialog_126908_Content_14 = {
    Text = "Itu hanyalah sebuah pintu yang sangat biasa, seperti semua pintu lain di dunia yang memiliki fungsi \"masuk dan keluar\", menunggu kamu di ujung teka-teki."
  },
  AvgDialog_126908_Content_15 = {
    Text = "Kamu menarik napas dalam-dalam, menggenggam kunci perak dengan erat, lalu mendorong pintu ini terbuka."
  },
  AvgDialog_126908_Content_17 = {
    Text = "<LightGray: Tidak ada lebih banyak mayat, juga tidak ada satu atau dua pekerja yang hancur, aku bahkan merasa agak tidak terbiasa.>"
  },
  AvgDialog_126908_Content_18 = {Text = "Hm?"},
  AvgDialog_126908_Content_19 = {
    Text = "Sekumpulan kabut mengalir dari meja, perlahan-lahan membentangkan sehelai sapu tangan sutra yang bersinar lembut, dengan penuh perhatian menuliskan huruf-huruf Londinium yang tidak selaras dengan gayanya."
  },
  AvgDialog_126908_Content_2 = {
    Text = "Gerbong nomor 1"
  },
  AvgDialog_126908_Content_20 = {
    Text = "Kepada Penjaga yang terhormat: \n\n Semoga surat ini menemukan Anda dalam keadaan baik. \n Anda telah berhasil tiba di sini, pasti sudah menemukan rahasia kereta ini—ia adalah sebuah Domain buatan yang dibangun oleh N. Sekarang, hamba di dalam kereta ini telah meninggal. \n Hamba menyaksikan kalian semua berbicara tentang tempat kembali kalian. Winkle dan Tinct, kampung halaman mereka telah lenyap; hamba sebenarnya juga menginginkan Miryam, tetapi setelah diteliti lebih lanjut, Lemuria yang disebutkan oleh Miryam juga telah menjadi sesuatu yang tidak dapat dikejar lagi."
  },
  AvgDialog_126908_Content_21 = {
    Text = [[
Dan saya ingin kembali ke mana? Saya pikir, mungkin itu adalah tempat yang sebenarnya tidak mimpi kampung. 
 Mereka semua, kita semua, sudah tidak memiliki tempat untuk kembali. 
 Namun Anda, hanya Anda, %player%, Universitas Mythag yang Anda impikan dan rindukan masih ada, masih ada orang yang menunggu Anda kembali di sana. 
 Jadi, Anda harus menjadi pemenang terakhir dalam permainan ini. 

 Oleh karena itu, saya mempersembahkan kemenangan ini kepada Anda, dengan kematian saya sebagai catatan. 
 Asalkan Anda mendorong tuas di tangan Anda, itu akan membawa Anda ke tempat-tempat yang mereka tunggu.]]
  },
  AvgDialog_126908_Content_22 = {
    Text = [[
Semoga Anda dan hamba dapat memenuhi keinginan.

Xu]]
  },
  AvgDialog_126908_Content_23 = {
    Text = "Seperti apa yang sesuai dengan sifat buruk N itu, lelucon aneh yang aneh…"
  },
  AvgDialog_126908_Content_24 = {
    Text = "Kamu berbisik pelan, berusaha melemparkan impuls dari pikiranmu."
  },
  AvgDialog_126908_Content_25 = {
    Text = "Tetapi godaan ini benar-benar terlalu besar, satu per satu teman yang akrab muncul di benakmu, hingga sosok itu muncul..."
  },
  AvgDialog_126908_Content_26 = {Text = "Ramona..."},
  AvgDialog_126908_Content_27 = {
    Text = "Suara detakan jantung yang menggema menguasai persepsi, tubuh bertindak sebelum akal, kau mendorong tuas kereta."
  },
  AvgDialog_126908_Content_28 = {
    Text = "Kereta tiba-tiba mempercepat, melaju cepat menuju lubang hitam di kejauhan."
  },
  AvgDialog_126908_Content_29 = {
    Text = "Beberapa detik kemudian, di ujung terowongan yang berjarak lebih dari seratus meter, tiba-tiba muncul sebuah dinding gunung yang menjulang tinggi."
  },
  AvgDialog_126908_Content_3 = {
    Text = "Di ujung gerbong nomor 1, sosok ramping menutupi wajahnya dengan kipas, menunggu kamu dengan tenang."
  },
  AvgDialog_126908_Content_30 = {
    Text = "Bercanda……"
  },
  AvgDialog_126908_Content_31 = {
    Text = "Kamu dengan cemas menarik tuas dengan keras, tetapi tuas seolah-olah terjepit dan tidak bergerak, dinding gunung mendekat dengan kecepatan lebih dari seratus kilometer per jam."
  },
  AvgDialog_126908_Content_32 = {
    Text = "<Red:Akan terbentur...>"
  },
  AvgDialog_126908_Content_33 = {
    Text = "Kamu menutup mata dengan putus asa, menunggu saat dampak kedatangan."
  },
  AvgDialog_126908_Content_34 = {
    Text = "<Shake:Sungguh buruk… Mengapa aku begitu bodoh hingga percaya pada salah satu duplikat N?…>"
  },
  AvgDialog_126908_Content_35 = {
    Text = "Gemuruh——!!"
  },
  AvgDialog_126908_Content_36 = {
    Text = "Detik berikutnya setelah kereta menghantam, sensasi tanpa bobot menarikmu jatuh lurus ke bawah."
  },
  AvgDialog_126908_Content_37 = {Text = "!!! Umm!!"},
  AvgDialog_126908_Content_38 = {
    Text = "Waktu entah sudah berlalu berapa lama."
  },
  AvgDialog_126908_Content_4 = {
    Text = "Izinkan hamba memperkenalkan diri. Hamba adalah Thais di kereta ini, atau Anda juga bisa menyebut hamba sebagai pengkhianat N."
  },
  AvgDialog_126908_Content_40 = {
    Text = "Di sini adalah? <Shake: Mythag?!>"
  },
  AvgDialog_126908_Content_41 = {
    Text = "Struktur bangunan di luar jendela sudah sangat familiar, kegembiraan yang besar membuatmu mengabaikan beberapa hal yang aneh, hampir melompat dari kursi berlengan mahal itu."
  },
  AvgDialog_126908_Content_42 = {
    Text = "Sampai kamu melihat cermin yang diletakkan dengan sangat hati-hati dan sengaja dari sudut tertentu."
  },
  AvgDialog_126908_Content_43 = {
    Text = "Di dalam memantulkan wajah Lord Dexter."
  },
  AvgDialog_126908_Content_44 = {Text = "???"},
  AvgDialog_126908_Content_45 = {
    Text = "Kamu dengan curiga menyentuh wajahmu, dan di cermin, ujung jari Dexter juga menyentuh pipinya yang cekung."
  },
  AvgDialog_126908_Content_46 = {
    Text = "Aduh, hadiah dari saling bunuh diri yang menang adalah \"kembali ke Mythag\", dan tidak ada janji bagaimana cara kembali, kan?"
  },
  AvgDialog_126908_Content_47 = {
    Text = "Batas yang bisa aku capai adalah meminjamkan kesadaranmu sebentar melalui sosokku."
  },
  AvgDialog_126908_Content_48 = {
    Text = "Meskipun begitu, ini adalah tindakan yang melanggar hukum semesta, kamu harus tetap menahan diri, jangan sampai orang lain mengetahui bahwa kamu bukan Lord Dexter ya~"
  },
  AvgDialog_126908_Content_49 = {
    Text = "Saya rasa kamu akan mengatakan,\"Kalau tidak\"……"
  },
  AvgDialog_126908_Content_5 = {
    Text = "Dalam kehidupan yang panjang hingga ribuan atau jutaan tahun, saya lebih terbiasa dengan nama \"Xu\". Nama itu cukup biasa, cukup umum, cukup dikenal, sehingga bisa dianggap milik siapa saja."
  },
  AvgDialog_126908_Content_50 = {
    Text = "Jika tidak, clang clang! Lonceng tengah malam akan berbunyi lebih awal, kereta labu dan sepatu kristal akan kembali ke bentuk semula."
  },
  AvgDialog_126908_Content_51 = {
    Text = "Hargai momen sebelum pukul nol datang, itu adalah waktu yang kau dapatkan dengan mengorbankan nyawa teman-temanmu."
  },
  AvgDialog_126908_Content_6 = {
    Text = "Hamba masih ada banyak hal yang ingin dikatakan kepada Anda, namun bukan di sini."
  },
  AvgDialog_126908_Content_7 = {
    Text = "Jika ada jodoh, biarkan hamba dan Anda bertemu lagi di tempat lain di masa depan."
  },
  AvgDialog_126908_Content_8 = {
    Text = "Dia mengangkat tangannya, lalu menghancurkan Perak kecil yang ada di telapak tangannya."
  },
  AvgDialog_126908_Content_9 = {
    Text = "Kamu adalah pemenang akhir, Penjaga."
  },
  AvgDialog_126909_Content_1 = {
    Text = "Kereta Doa Tahun Baru"
  },
  AvgDialog_126909_Content_10 = {
    Text = "<Shake:Dong, dong, dong——>"
  },
  AvgDialog_126909_Content_11 = {
    Text = "<Shake:Hmm… sangat ngantuk.>\nTidur di kereta, tidak peduli berapa lama, tetap tidak cukup tidur."
  },
  AvgDialog_126909_Content_12 = {
    Text = "<LightGray:Merasa seperti otakku terjerat dalam sejumput bubur, lupa akan sesuatu yang penting...>"
  },
  AvgDialog_126909_Content_13 = {
    Text = "<LightGray:<Shake:Tidak peduli, dengan alasan harus libur selama Perayaan Tahun Baru, aku akan kembali ke asrama untuk menyimpan mayat, meskipun Doll terus mendesak tugas dan Ramona terus mendesak laporan, aku akan tetap melawan sampai akhir…>>"
  },
  AvgDialog_126909_Content_14 = {
    Text = "Aduh, memang bibit kecil yang suka tidur. Sebelum kereta tiba di tujuan, kau bisa bersandar di pundakku, ya?"
  },
  AvgDialog_126909_Content_15 = {Text = "Uwaa?!"},
  AvgDialog_126909_Content_16 = {
    Text = "Kamu melihat sekeliling, menghitung jumlah penumpang."
  },
  AvgDialog_126909_Content_17 = {
    Text = "Wanda mengayunkan setengah gelas anggur merah, menundukkan kepala untuk mengagumi kuku runcingnya yang dipoles dengan hati-hati."
  },
  AvgDialog_126909_Content_18 = {
    Text = "Tinct diam-diam memegang sebuah partitur, bibir tipisnya bergerak, seolah-olah sedang berlatih dengan suara pelan di dalam pikirannya."
  },
  AvgDialog_126909_Content_19 = {
    Text = "Winkle bersandar di samping lampu kecil yang redup, pandangannya seolah-olah takut cahaya itu akan keluar, terpaku pada sumbu lampu."
  },
  AvgDialog_126909_Content_2 = {
    Text = "Jiang! Selamat Perayaan Tahun Baru untuk para tuan dan nyonya di kursi penonton! Akhirnya, akhirnya giliran saya, si kecil N, untuk menunjukkan bakat saya!"
  },
  AvgDialog_126909_Content_20 = {
    Text = "Miryam mendongak dan menutup matanya, tampak tidak menyadari perubahan di sekitarnya."
  },
  AvgDialog_126909_Content_21 = {
    Text = "<LightGray:Semua, suasana yang saling tidak mengganggu, sangat nyaman…>"
  },
  AvgDialog_126909_Content_23 = {
    Text = "……………"
  },
  AvgDialog_126909_Content_24 = {
    Text = "<LightGray:Namun, apakah waktu kereta ini agak lama?>"
  },
  AvgDialog_126909_Content_25 = {
    Text = "Kereta khusus Mythag disiapkan untuk melewati Penghalang kabut di luar kampus, ini adalah kereta jalur pendek. Namun sejak kamu tertidur dan terbangun, sudah berlalu setidaknya satu jam."
  },
  AvgDialog_126909_Content_26 = {
    Text = "Kamu berpikir sejenak, lalu mendekati satu-satunya anggota kelompok guru di dalam mobil."
  },
  AvgDialog_126909_Content_27 = {
    Text = "Winkle… Kenapa kereta khusus <Yellow:Mythag> hari ini begitu lambat?"
  },
  AvgDialog_126909_Content_28 = {
    Text = "Winkle melompat seperti kelinci liar yang terkejut."
  },
  AvgDialog_126909_Content_29 = {
    Text = "Apa, kereta khusus Mythag? Bukankah kereta ini menuju @1 planet asal?"
  },
  AvgDialog_126909_Content_3 = {
    Text = "Meskipun kamu adalah sosokku, aku tetap harus mengkritik bahwa tipu muslihat yang kamu lakukan kali ini terkesan kurang berkelas, agak absurd dan tidak masuk akal."
  },
  AvgDialog_126909_Content_30 = {
    Text = "Semua mata tertuju pada Kerang seperti lampu sorot."
  },
  AvgDialog_126909_Content_31 = {
    Text = "Jangan bercanda, gadis kecil, bukankah ini kereta yang menuju Aran?"
  },
  AvgDialog_126909_Content_32 = {
    Text = "Eh, tapi Aran terletak di dalam laut pasir yang dalam, tidak mungkin ada kereta yang bisa sampai di sana..."
  },
  AvgDialog_126909_Content_33 = {
    Text = "Menurut pengetahuan saya, tujuan akhir kereta ini seharusnya Isarau."
  },
  AvgDialog_126909_Content_34 = {
    Text = "Itu semakin absurd, Isaraul bukan sudah lama hancur?"
  },
  AvgDialog_126909_Content_35 = {
    Text = "Berkata tanpa bukti, saya memiliki kuitansi sebagai bukti."
  },
  AvgDialog_126909_Content_36 = {
    Text = "Wanda mengeluarkan tiket logam dan menunjukkannya di depan semua orang."
  },
  AvgDialog_126909_Content_37 = {
    Text = "Di tempat turun tiket, tertulis jelas nama Isarau."
  },
  AvgDialog_126909_Content_38 = {
    Text = "Miryam, Tinct, kalian berdua…"
  },
  AvgDialog_126909_Content_39 = {
    Text = "Tidak perlu banyak bicara, kehendak-Nya akan memandu saya kembali ke jalan Lemuria."
  },
  AvgDialog_126909_Content_4 = {
    Text = "Ini bukan Perayaan Tahun Baru, tentu saja harus memberikan hiburan yang berbeda kepada para penonton yang terhormat."
  },
  AvgDialog_126909_Content_40 = {
    Text = "Aku... aku ingin memanfaatkan liburan Perayaan Tahun Baru untuk kembali ke Bintang Terasing menemani kakak..."
  },
  AvgDialog_126909_Content_41 = {
    Text = "<LightGray:Bintang Terasing……Tinct telah mengembara selama waktu yang tak terhitung, hingga tiba di Kadas. Jarak ini, bagi sebuah kereta, sama sekali tidak terjangkau…>"
  },
  AvgDialog_126909_Content_42 = {
    Text = "Lemuria, telah tenggelam di dasar laut sejak seribu tahun yang lalu."
  },
  AvgDialog_126909_Content_43 = {
    Text = "Dan Isaraul... sudah lama hancur."
  },
  AvgDialog_126909_Content_44 = {
    Text = "Anak kecil, kamu sudah menunjuk-nunjuk selama setengah hari. Planet asalmu yang ingin kamu kembali, apa namanya, di mana?"
  },
  AvgDialog_126909_Content_45 = {
    Text = "Winkle berubah wajahnya dengan drastis."
  },
  AvgDialog_126909_Content_46 = {
    Text = "<Shake:Planet asal……adalah planet asal! Nama planet asal……adalah……<Small:@1……>>"
  },
  AvgDialog_126909_Content_47 = {
    Text = "Eh? Aku tidak salah dengar, kau bahkan tidak bisa mengingat nama planet asalmu?"
  },
  AvgDialog_126909_Content_48 = {
    Text = "Semua orang tenang sebentar, dengarkan saya."
  },
  AvgDialog_126909_Content_49 = {
    Text = "Tujuan semua orang terdengar sangat tidak realistis. Namun, setiap orang memang memegang tiket menuju kampung halaman mereka sendiri."
  },
  AvgDialog_126909_Content_5 = {
    Text = "Meskipun begitu, apakah tidak terlalu sulit dipercaya jika dari awal hingga akhir hanya ada satu adegan?"
  },
  AvgDialog_126909_Content_50 = {
    Text = "Jadi, yang paling perlu kita temukan adalah <Yellow:petugas kereta>, untuk mengetahui informasi tentang kereta ini, bukan berdebat secara sia-sia di sini."
  },
  AvgDialog_126909_Content_51 = {Text = "Hek, hek."},
  AvgDialog_126909_Content_52 = {
    Text = "Suara aneh yang sedikit konyol terdengar dari sudut."
  },
  AvgDialog_126909_Content_53 = {
    Text = "Sudah selesai ramai begini? Aku masih ingin melihat pertunjukan sedikit lebih lama~"
  },
  AvgDialog_126909_Content_54 = {Text = "N kecil?!"},
  AvgDialog_126909_Content_55 = {
    Text = "Ada apa? Apakah tidak ada yang menyambutku? Aku bahkan telah menyiapkan hadiah besar untuk Perayaan Tahun Baru ini!"
  },
  AvgDialog_126909_Content_56 = {
    Text = "Dalang yang seharusnya tersembunyi dalam kegelapan kini melangkah ke tengah panggung, niat jahatnya jelas terlihat——dia pasti sedang merencanakan konspirasi yang lebih besar."
  },
  AvgDialog_126909_Content_57 = {
    Text = "Apa yang kamu lakukan di sini?"
  },
  AvgDialog_126909_Content_58 = {
    Text = "Bukankah ini sudah jelas? Saya yang perhatian, tidak mementingkan diri sendiri, dan suka berbuat baik, pada saat Perayaan Tahun Baru ini, telah meluncurkan kereta cepat pulang, agar semua orang yang merindukan tanah air dapat merasakan kehangatan perayaan."
  },
  AvgDialog_126909_Content_59 = {
    Text = "Kamu tidak sebaik itu. Katakan, apa lagi yang kamu sembunyikan?"
  },
  AvgDialog_126909_Content_6 = {
    Text = "<Shake:Wuwu, sekarang bukanlah waktu Anda untuk mengelola teater dan berhadapan dengan Orang itu. Tim proyek acara Tahun Baru kali ini sangat kekurangan dana, hanya bisa menyediakan dekorasi lokasi yang sangat minim…>"
  },
  AvgDialog_126909_Content_60 = {
    Text = "Eh, jangan buru-buru, tunggu aku bicara sedikit lagi."
  },
  AvgDialog_126909_Content_61 = {
    Text = "Banyak orang yang ingin pulang, tetapi hanya ada satu kereta. Jadi, hanya satu orang yang bisa kembali ke kampung halaman yang mereka rindukan, ya?"
  },
  AvgDialog_126909_Content_62 = {
    Text = "Aduh, sebagai N yang perhatian, tidak mementingkan diri sendiri, dan suka berbuat baik, aku pasti akan menggunakan cara yang paling adil untuk menentukan siapa yang bisa mendapatkan kualifikasi ini, kan?"
  },
  AvgDialog_126909_Content_63 = {Text = "Jadi..."},
  AvgDialog_126909_Content_64 = {
    Text = "<Big:Jadi, <Shake:<Red:Mulai bunuh diri sendiri!>>!>"
  },
  AvgDialog_126909_Content_65 = {
    Text = "Bunuh semua orang, orang yang bertahan hingga akhir akan menentukan tujuan kereta ini dan mendapatkan kesempatan untuk berwisata sehari di <Yellow:tanah kelahiran>!"
  },
  AvgDialog_126909_Content_66 = {
    Text = "Tidak mungkin! Tidak ada yang akan mengambil nyawa orang lain hanya untuk hal semacam ini, kan?!"
  },
  AvgDialog_126909_Content_67 = {
    Text = "Benar, meskipun aku sangat merindukan Faint... tapi tidak mungkin ikut serta dalam kompetisi yang begitu kejam ini..."
  },
  AvgDialog_126909_Content_68 = {
    Text = "Hm, tinggal di sini menikmati anggur dan pelayan, sebenarnya juga tidak buruk. Isaraul bagiku, hanyalah kenangan lama."
  },
  AvgDialog_126909_Content_69 = {
    Text = "Meskipun sangat berat untuk ditinggalkan... tetapi di sini ada bibit pohon kecilku, dan orang Aram tidak lagi bergantung padaku untuk memimpin suku. Sepertinya, kakakku juga tidak memiliki motivasi untuk terlibat dalam pembunuhan satu sama lain."
  },
  AvgDialog_126909_Content_7 = {
    Text = "Sepertinya saya juga hanya bisa... mengamati dengan tenang."
  },
  AvgDialog_126909_Content_70 = {
    Text = "Semua orang memandang, berkumpul pada orang terakhir."
  },
  AvgDialog_126909_Content_72 = {
    Text = "Pandangan kalian sama sekali tidak mengganggunya, Miryam terdiam tanpa suara."
  },
  AvgDialog_126909_Content_73 = {
    Text = "Kau mengetahui obsesinya, mengetahui makna dan nilai kata Lemuria baginya."
  },
  AvgDialog_126909_Content_74 = {
    Text = "Aduh, aku sudah tahu ini tidak sesederhana itu..."
  },
  AvgDialog_126909_Content_75 = {
    Text = "Untuk menghindari situasi canggung saat ini, saya telah memperbaiki aturannya——harus menggunakan 5 orang yang telah meninggal untuk menukarkan tiket terakhir dengan saya."
  },
  AvgDialog_126909_Content_76 = {
    Text = "Kumpulkan tujuh tiket, baru bisa menyalakan kereta, ya!"
  },
  AvgDialog_126909_Content_77 = {
    Text = "Dengan kata lain, sebelum semua orang membunuh dan hanya tersisa satu orang di kereta, tidak ada yang bisa melarikan diri dari sini."
  },
  AvgDialog_126909_Content_78 = {
    Text = "Selain itu, di antara kalian ada seorang <Yellow:pengkhianat> yang saya tanamkan, yang berubah menjadi alter ego saya, N yang serba bisa!"
  },
  AvgDialog_126909_Content_79 = {
    Text = "Jika kalian tidak melakukan apa-apa, ia akan membunuh kalian satu per satu, satu per satu! Pada saat itu, tidak ada yang bisa kembali!"
  },
  AvgDialog_126909_Content_8 = {
    Text = "Tanpa basa-basi, N kecil akan segera mempersembahkan <Shake:Teater Penampilan Eksklusif <Red:Perayaan Tahun Baru> terbaru dan terpanas>!"
  },
  AvgDialog_126909_Content_81 = {
    Text = "Begitu suara kecil N selesai, sebuah batang pohon tiba-tiba menembus kabut hitam."
  },
  AvgDialog_126909_Content_82 = {
    Text = "Baiklah, semuanya. Jangan dengarkan omong kosong orang ini."
  },
  AvgDialog_126909_Content_83 = {
    Text = "Kita ada enam orang, termasuk Penjaga paling hebat di Mythag, apakah kita tidak bisa keluar dari gerbong kecil ini?"
  },
  AvgDialog_126909_Content_9 = {
    Text = "Suara tepuk tangan dan sorakan terdengar!"
  },
  AvgDialog_126910_Content_1 = {
    Text = "Korban kedua"
  },
  AvgDialog_126910_Content_10 = {
    Text = "Hal yang lebih mendesak, bukankah menemukan pelaku di antara kita?"
  },
  AvgDialog_126910_Content_11 = {
    Text = "Tidak, saya tidak berpikir begitu... Kita hanya memiliki beberapa orang, jika terjebak dalam saling curiga, hanya akan membuat keadaan semakin buruk."
  },
  AvgDialog_126910_Content_12 = {
    Text = "Yang lebih penting adalah menjamin keselamatan orang-orang yang tersisa. Bagaimana jika kita semua tinggal di gerbong nomor 2?"
  },
  AvgDialog_126910_Content_13 = {
    Text = "Kamu melihat Winkle yang tampak lelah, lalu mengangguk."
  },
  AvgDialog_126910_Content_14 = {
    Text = "Bibit kecil sudah membuat keputusan, tentu saja aku tidak akan menentangnya."
  },
  AvgDialog_126910_Content_15 = {
    Text = "……Setiap tiga jam, saya perlu mencari sudut yang tenang untuk berdoa sendirian."
  },
  AvgDialog_126910_Content_16 = {
    Text = "Itu tidak boleh! Siapa yang tahu apa yang akan kamu lakukan selama berdoa!"
  },
  AvgDialog_126910_Content_17 = {
    Text = "Lagipula, saat semua orang berdiskusi tentang melepaskan diri dari saling membunuh, hanya kamu yang tidak memberikan pendapat, siapa yang tahu apakah kamu adalah pelayan N itu?"
  },
  AvgDialog_126910_Content_18 = {
    Text = "Tuhanku yang aku layani hanya satu, yaitu dewa Lemuria."
  },
  AvgDialog_126910_Content_19 = {
    Text = "Namun, jika kau mengucapkan kata-kata penghinaan lagi, aku tidak keberatan untuk menjatuhkan hukuman ilahi atas nama Tuhanku."
  },
  AvgDialog_126910_Content_2 = {
    Text = "Tiga jam kemudian, di dalam gerbong"
  },
  AvgDialog_126910_Content_20 = {
    Text = "Melihat Miryam sudah mengeluarkan belati, kamu segera menengahi."
  },
  AvgDialog_126910_Content_21 = {
    Text = "Kami saat ini tidak memiliki bukti untuk menuduh siapa pun, Tinct... saat itu, semua orang sudah tertidur."
  },
  AvgDialog_126910_Content_22 = {
    Text = "Selain itu, pengkhianat yang disebut-sebut itu mungkin hanya salah satu tipu daya N untuk menggoda kita agar saling membunuh sesuai dengan niatnya."
  },
  AvgDialog_126910_Content_23 = {
    Text = "Bagaimana kau bisa mengatakan itu tentang orang lain, uuu, orang itu benar-benar dengan tulus mengingatkan kalian——"
  },
  AvgDialog_126910_Content_24 = {
    Text = "<LightGray:Mata Pisau……>"
  },
  AvgDialog_126910_Content_25 = {
    Text = "Baik, baik, saya menghilang, huhu..."
  },
  AvgDialog_126910_Content_26 = {
    Text = "Dengan suara ledakan, sosok kecil N menghilang di udara."
  },
  AvgDialog_126910_Content_27 = {
    Text = "Karena begitu... Miryam, bisakah kamu berdoa sendirian di gerbong nomor 1, dan jangan pergi tanpa izin jika tidak ada kejadian tak terduga?"
  },
  AvgDialog_126910_Content_28 = {
    Text = "Kita akan berkumpul di pintu belakang gerbong 1, sementara orang lain berada di satu ruangan, sehingga tidak akan terjadi bahaya."
  },
  AvgDialog_126910_Content_29 = {
    Text = "Apakah ini tidak terlalu... untuk Miryam?"
  },
  AvgDialog_126910_Content_3 = {
    Text = "<Shake:Guruh guruh guruh——>"
  },
  AvgDialog_126910_Content_30 = {
    Text = "Saya tidak memiliki keberatan."
  },
  AvgDialog_126910_Content_31 = {
    Text = "Miryam sama sekali tidak menghiraukan halanganmu, dia langsung berdiri dan meninggalkan gerbong nomor 2, sambil tidak lupa menutup dan mengunci pintu pemisah dengan serius."
  },
  AvgDialog_126910_Content_32 = {
    Text = "Orang-orang yang tersisa ini, seharusnya bisa merasa tenang…"
  },
  AvgDialog_126910_Content_33 = {
    Text = "Aku selalu merasa, bahwa hal ini tidak sesederhana itu…"
  },
  AvgDialog_126910_Content_34 = {
    Text = "Satu jam kemudian, di dalam gerbong 2"
  },
  AvgDialog_126910_Content_35 = {Text = "Umm…umm!"},
  AvgDialog_126910_Content_36 = {
    Text = "Saya pergi sebentar…"
  },
  AvgDialog_126910_Content_37 = {
    Text = "Winkle berjalan goyang menuju batas gerbong."
  },
  AvgDialog_126910_Content_38 = {
    Text = "<LightGray:Apakah sudah terlalu banyak minum kopi…>"
  },
  AvgDialog_126910_Content_39 = {
    Text = "Satu jam kemudian, di dalam gerbong 2"
  },
  AvgDialog_126910_Content_4 = {
    Text = "Jangan minum lagi."
  },
  AvgDialog_126910_Content_40 = {
    Text = "<LightGray:Aneh, Winkle kenapa belum kembali...>"
  },
  AvgDialog_126910_Content_41 = {
    Text = "Khawatir sekali? Apakah kamu ingin aku menemanimu untuk memeriksanya?"
  },
  AvgDialog_126910_Content_42 = {Text = "Ayo pergi."},
  AvgDialog_126910_Content_43 = {
    Text = "Perasaan cemas menyebar di dalam hati, suara langkah kaki yang hampa bersama bayangan mengisi seluruh gerbong."
  },
  AvgDialog_126910_Content_44 = {
    Text = "Kamu mengerti nama kabut itu——"
  },
  AvgDialog_126910_Content_45 = {Text = "Kematian."},
  AvgDialog_126910_Content_46 = {
    Text = "Kalian terus-menerus mengetuk pintu toilet, memanggil nama Winkle, namun tidak ada yang menjawab."
  },
  AvgDialog_126910_Content_47 = {
    Text = "Kalian mulai mencoba menabrak pintu."
  },
  AvgDialog_126910_Content_48 = {
    Text = "Dung, dung, dung!"
  },
  AvgDialog_126910_Content_49 = {
    Text = "Apa yang terjadi?"
  },
  AvgDialog_126910_Content_5 = {
    Text = "<Shake:Guruh guruh guruh——>"
  },
  AvgDialog_126910_Content_50 = {
    Text = "Wanda juga tertarik oleh suara yang aneh."
  },
  AvgDialog_126910_Content_51 = {
    Text = "Winkle sudah berada di kamar mandi selama satu jam, kami mengetuk pintu, namun tidak ada jawaban."
  },
  AvgDialog_126910_Content_52 = {
    Text = "Pintu juga tidak bisa dibuka, aneh sekali, sekumpulan Awakener yang bisa mengendalikan angin dan hujan, melakukan hal-hal luar biasa, tetapi tidak bisa membuka sebuah pintu!"
  },
  AvgDialog_126910_Content_53 = {
    Text = "Apakah kalian pernah mendengar tentang genre baru?"
  },
  AvgDialog_126910_Content_54 = {
    Text = "Berbicara tentang genre baru, tidak bisa tidak menyebutkan genre asli."
  },
  AvgDialog_126910_Content_56 = {
    Text = "Dalam karya detektif yang murni, merujuk pada karya penyelidikan yang memiliki teka-teki yang jelas dan logika yang masuk akal, sementara detektif baru menambahkan pengaturan dunia yang unik di atas dasar ini."
  },
  AvgDialog_126910_Content_57 = {
    Text = "Meskipun demikian, genre baru tetap harus menghormati pembaca dan keadilan, harus mengajukan pertanyaan dalam batasan pengaturan yang sudah diketahui oleh pembaca, dan tidak mendukung penambahan pengaturan yang tidak masuk akal secara sembarangan."
  },
  AvgDialog_126910_Content_58 = {
    Text = "Dengan kata lain, jika kalian tidak menguasai keterampilan membuka kunci, kalian tidak bisa sembarangan membuka pintu yang terkunci dari dalam."
  },
  AvgDialog_126910_Content_59 = {
    Text = "N kecil sebentar memanjat di rak bagasi, sebentar bersembunyi di belakang sandaran kursi, menghindari semua spike dan sulur sambil menyelesaikan pidato panjangnya."
  },
  AvgDialog_126910_Content_6 = {Text = "Winkle…"},
  AvgDialog_126910_Content_60 = {
    Text = "Sesuai dengan yang kamu maksud... ini adalah pembunuhan di ruang tertutup, di dalamnya adalah lokasi kejadian?"
  },
  AvgDialog_126910_Content_61 = {
    Text = "Siapa yang tahu! Mungkin Winkle melarikan diri karena takut dihukum, melompat dari jendela toilet untuk melarikan diri dari mobil?"
  },
  AvgDialog_126910_Content_62 = {
    Text = "Bukankah kamu bilang kita tidak bisa meninggalkan kereta?"
  },
  AvgDialog_126910_Content_63 = {
    Text = "Aduh, ada celah dalam penalaran!"
  },
  AvgDialog_126910_Content_64 = {
    Text = "Sebelum detektif besar yang sebenarnya muncul, pasti ada orang yang bertanggung jawab atas penalaran yang salah."
  },
  AvgDialog_126910_Content_65 = {
    Text = "Jika semua orang tidak ingin berperan sebagai bodoh, biarkan aku, si kecil N yang hebat dan berdedikasi, yang memerankannya!"
  },
  AvgDialog_126910_Content_66 = {
    Text = "Jangan lagi bercanda dengan orang ini."
  },
  AvgDialog_126910_Content_67 = {
    Text = "Meskipun agak tidak sopan... Namun, di pintu toilet terdapat sebuah jendela kecil berlapis, strukturnya sangat rapuh."
  },
  AvgDialog_126910_Content_68 = {
    Text = "Wanda mengangkat Spike."
  },
  AvgDialog_126910_Content_69 = {
    Text = "Berderak berderak, tirai jendela dibongkar."
  },
  AvgDialog_126910_Content_7 = {
    Text = "Meskipun minum banyak kopi, Tinct tidak akan bisa hidup kembali, bukan?"
  },
  AvgDialog_126910_Content_70 = {
    Text = "Selanjutnya serahkan padaku."
  },
  AvgDialog_126910_Content_71 = {
    Text = "Vine menjulur, membuka kunci pintu, kalian mendorong pintu dan masuk."
  },
  AvgDialog_126910_Content_72 = {
    Text = "Tidak ada waktu lagi."
  },
  AvgDialog_126910_Content_73 = {
    Text = "Winkle meringkuk diam di sudut kamar mandi."
  },
  AvgDialog_126910_Content_74 = {Text = "Wenkoer!"},
  AvgDialog_126910_Content_75 = {
    Text = "Kamu bergegas menuju Winkle, sudut bibirnya mengalir dengan darah merah tua, dia sudah kehilangan napas."
  },
  AvgDialog_126910_Content_76 = {
    Text = "Sejujurnya, Winkle... pada saat kamu meninggal, kita bertiga, kamu, saya, dan Wanda, sama sekali tidak pernah meninggalkan gerbong nomor 2."
  },
  AvgDialog_126910_Content_77 = {
    Text = "Satu-satunya pembunuh... hanya bisa Miryam."
  },
  AvgDialog_126910_Content_78 = {
    Text = "Tuan saya tidak membimbing saya untuk melakukan tindakan seperti ini. Namun, jika kau bersikeras, saya juga tidak keberatan untuk menjatuhkan keputusan atas nama dewa."
  },
  AvgDialog_126910_Content_79 = {
    Text = "Aduh, tidak bisa sepakat!"
  },
  AvgDialog_126910_Content_8 = {
    Text = "<Shake:Kamu——>"
  },
  AvgDialog_126910_Content_80 = {
    Text = "Karena membahas keputusan dewa, aku ingin memberi kalian sebuah <Yellow:kesempatan untuk menang dengan mudah>!"
  },
  AvgDialog_126910_Content_81 = {
    Text = "Kita sekarang bisa mengadakan satu putaran pemungutan suara, orang dengan suara terbanyak akan saya usir dari kereta, kehilangan hak untuk pulang ke tanah air!"
  },
  AvgDialog_126910_Content_82 = {
    Text = "Tidak diragukan lagi, aku akan memilih Miryam."
  },
  AvgDialog_126910_Content_83 = {Text = "Thais."},
  AvgDialog_126910_Content_84 = {
    Text = "Anak kecil, menurutmu bagaimana? Melihat situasi saat ini, aku juga akan memilih untuk memberikan suara kepada Miryam."
  },
  AvgDialog_126910_Content_85 = {
    Text = "Miryam 2 suara! Thais 1 suara!"
  },
  AvgDialog_126910_Content_86 = {
    Text = "N, jika hasilnya seri, bagaimana cara menghitung hasilnya?"
  },
  AvgDialog_126910_Content_87 = {
    Text = "Jika hasilnya seri, maka dianggap tidak ada yang keluar dari pertandingan~"
  },
  AvgDialog_126910_Content_88 = {
    Text = "Namun, pikirkanlah dengan serius, sekarang tinggal empat orang. Jika melewatkan kesempatan ini, dan pengkhianat membunuh satu orang lagi, peluang untuk menang akan meningkat—secara signifikan—!"
  },
  AvgDialog_126910_Content_89 = {
    Text = "Aku tidak ingin menuduh orang baik. Aku memilih Thais."
  },
  AvgDialog_126910_Content_9 = {
    Text = "Benar, yang lebih penting daripada itu adalah menemukan cara untuk meninggalkan kereta."
  },
  AvgDialog_126910_Content_90 = {
    Text = "Apakah kamu benar-benar tidak mau mempertimbangkan lagi? Ini adalah satu-satunya kesempatan untuk memilih loh?"
  },
  AvgDialog_126910_Content_91 = {
    Text = "Tidak, semakin kamu seperti ini, semakin saya merasa bahwa saya telah membuat pilihan yang benar."
  },
  AvgDialog_126910_Content_92 = {
    Text = "Baiklah, maka hasil voting untuk putaran ini adalah: seri, tidak ada yang keluar dari pertandingan~"
  },
  AvgDialog_126910_Content_93 = {
    Text = "Aduh~ Sangat mengecewakan~ Xiao N juga harus mencari sudut sendiri untuk menenangkan emosinya, sampai jumpa semua~"
  },
  AvgDialog_126911_Content_1 = {
    Text = "Permainan dimulai"
  },
  AvgDialog_126911_Content_10 = {
    Text = "Jika kamu terus mengoceh, aku tidak keberatan menggunakan ini untuk memberimu pengalaman menembus hati sekali lagi, lho?"
  },
  AvgDialog_126911_Content_11 = {
    Text = "Wanda mengelus Spike di telapak tangannya."
  },
  AvgDialog_126911_Content_12 = {
    Text = "Aduh aduh, sungguh pernyataan yang menyedihkan."
  },
  AvgDialog_126911_Content_13 = {
    Text = "Acara Tahun Baru yang dipersiapkan dengan hati-hati oleh N kecil, apakah begitu tidak disukai? <Shake: Wuwu…>"
  },
  AvgDialog_126911_Content_14 = {
    Text = "Dengan berpura-pura menangis kurang dari satu detik, N kecil segera menunjukkan senyuman yang cerah."
  },
  AvgDialog_126911_Content_15 = {
    Text = "Singkatnya, silakan semua berjuang saling menghancurkan! Si kecil N akan menantikan penampilan kalian!"
  },
  AvgDialog_126911_Content_16 = {
    Text = [[
"Shua" dengan suara ledakan, sosok kecil N menghilang lagi. 
 Di dalam kereta kembali menjadi keheningan yang mengganggu.]]
  },
  AvgDialog_126911_Content_17 = {
    Text = "Yang menyusul adalah keheningan yang panjang, kegelapan di depan rel seolah-olah tidak ada habisnya."
  },
  AvgDialog_126911_Content_18 = {
    Text = "Berapa lama lagi kereta akan berjalan? Tujuan akhir akan menuju ke mana?"
  },
  AvgDialog_126911_Content_19 = {
    Text = "Di dalam hati orang-orang, mungkin tidak ada jawaban, atau ada jawaban yang tidak bisa diucapkan."
  },
  AvgDialog_126911_Content_2 = {
    Text = "...tidak bisa melarikan diri."
  },
  AvgDialog_126911_Content_20 = {
    Text = "Itu, semuanya..."
  },
  AvgDialog_126911_Content_21 = {
    Text = "Suara yang indah memecahkan ketenangan."
  },
  AvgDialog_126911_Content_22 = {
    Text = "Terkurung di sini juga cukup membosankan... Jika semua tidak keberatan mengganggu, saya akan menyanyikan sebuah lagu untuk semua..."
  },
  AvgDialog_126911_Content_23 = {
    Text = "Hmm?! Ini yang aku suka tonton! Bolehkah aku memesan lagu?"
  },
  AvgDialog_126911_Content_24 = {
    Text = "Pergi, pergi, pergi! Apa urusanmu?"
  },
  AvgDialog_126911_Content_25 = {
    Text = "Karena ini adalah Perayaan Tahun Baru Kerajaan Kuno Panlong, saya teringat sebuah lagu Timur yang pernah dinyanyikan oleh orang-orang dari Paduan Suara Bayangan."
  },
  AvgDialog_126911_Content_26 = {
    Text = "Saya tidak yakin apakah saya telah menguasai cukup banyak lagu-lagu Timur..."
  },
  AvgDialog_126911_Content_27 = {
    Text = "Lagu itu berjudul \"Bunga Melati\"."
  },
  AvgDialog_126911_Content_28 = {
    Text = "Oh? Apakah ini yang dimaksud?"
  },
  AvgDialog_126911_Content_29 = {
    Text = "Kebetulan, saya juga berada di bawah panggung saat pertunjukan paduan suara bayangan itu."
  },
  AvgDialog_126911_Content_3 = {
    Text = "Winkle dengan lesu mengeluarkan kesimpulan."
  },
  AvgDialog_126911_Content_30 = {
    Text = "Jika saya tidak salah ingat, saya juga bertemu di kursi penonton dengan..."
  },
  AvgDialog_126911_Content_31 = {
    Text = "Pandangan Wanda tertuju pada Miryam, sementara Miryam hanya mengangguk tanpa bicara."
  },
  AvgDialog_126911_Content_32 = {
    Text = "Karena tidak ada yang menolak... saya akan mulai bernyanyi."
  },
  AvgDialog_126911_Content_33 = {
    Text = "Tinct membersihkan tenggorokannya."
  },
  AvgDialog_126911_Content_34 = {
    Text = "<Shake:Sebuah bunga melati yang indah, sebuah bunga melati yang indah♪~ Seluruh taman bunga tidak ada yang bisa menandingi dia♪~>"
  },
  AvgDialog_126911_Content_35 = {
    Text = "<Shake:La la la~ la la la~ la la la♪~>"
  },
  AvgDialog_126911_Content_36 = {
    Text = "Suara nyanyian yang ethereal dan lembut bergema di dalam gerbong yang kosong."
  },
  AvgDialog_126911_Content_37 = {
    Text = "Di bawah penghiburan suara nyanyian yang merdu, benang yang tegang di dalam pikiranmu perlahan-lahan menjadi santai, dan kamu bahkan merasakan sedikit kantuk."
  },
  AvgDialog_126911_Content_38 = {
    Text = "Sepertinya kalian semua sudah lelah? Aku sudah terbiasa tidak tidur, bisa menjaga malam untuk kalian semua."
  },
  AvgDialog_126911_Content_39 = {
    Text = "Kamu mengangguk, lalu terjun ke dalam mimpi yang telah lama menyerang."
  },
  AvgDialog_126911_Content_4 = {
    Text = "Selain kokpit, kereta ini terdiri dari tiga gerbong. Saat ini kita berada di gerbong 2, yaitu gerbong yang berada di tengah."
  },
  AvgDialog_126911_Content_41 = {
    Text = "Setelah lama, Tinct juga mengakhiri nyanyiannya."
  },
  AvgDialog_126911_Content_42 = {
    Text = "Semua orang sudah tertidur, kamu juga istirahatlah sejenak, ya?"
  },
  AvgDialog_126911_Content_43 = {
    Text = "Benarkah tidak apa-apa?"
  },
  AvgDialog_126911_Content_44 = {
    Text = "Apa, kamu takut aku adalah pengkhianat itu?"
  },
  AvgDialog_126911_Content_45 = {
    Text = "Itu tidak akan terjadi. Hanya saja sebelumnya, aku selalu menunggu Faint tertidur, lalu baru pergi istirahat…"
  },
  AvgDialog_126911_Content_46 = {
    Text = "Nah, hari ini giliranmu untuk istirahat dengan baik! Pergilah, pergilah."
  },
  AvgDialog_126911_Content_47 = {
    Text = "Atas desakan Winkle, Tinct juga mengambil selembar selimut, bersandar pada sandaran kursi dan menutup kedua matanya."
  },
  AvgDialog_126911_Content_48 = {
    Text = "Tak heran semua orang sudah tertidur, suasana yang benar-benar nyaman…"
  },
  AvgDialog_126911_Content_5 = {
    Text = "Gerbong nomor 1 dan 3 semuanya kosong, semua jendela dan pintu tertutup rapat, baik dengan menggunakan cara fisik maupun teknologi chip perak tidak dapat dibuka."
  },
  AvgDialog_126911_Content_50 = {
    Text = "……………"
  },
  AvgDialog_126911_Content_51 = {Text = "Hmm...?"},
  AvgDialog_126911_Content_52 = {
    Text = "Pertama yang terlihat adalah wajah tidur Winkle yang tenang dan damai."
  },
  AvgDialog_126911_Content_53 = {
    Text = "Lampu di dalam kereta padam entah kapan, lingkungan di sekitarnya terjebak dalam kegelapan, hanya cahaya lembut yang terlihat dari sambungan gerbong."
  },
  AvgDialog_126911_Content_54 = {
    Text = "Winkle... bagaimana kamu bisa tertidur...?"
  },
  AvgDialog_126911_Content_55 = {
    Text = "Winkle mengeluarkan napas perlahan."
  },
  AvgDialog_126911_Content_56 = {
    Text = "Hmm……? Aku…… tertidur?"
  },
  AvgDialog_126911_Content_57 = {
    Text = "Eh eh eh?!!! Aku tertidur!!!"
  },
  AvgDialog_126911_Content_58 = {
    Text = "Seruan Winkle seperti angin kencang dan hujan deras, segera membangunkan semua penumpang yang tertidur."
  },
  AvgDialog_126911_Content_59 = {
    Text = "Lampu tiba-tiba menyala, menerangi seluruh gerbong."
  },
  AvgDialog_126911_Content_6 = {
    Text = "Aku sudah bilang! Tidak perlu repot-repot! Sebelum hanya tersisa satu pemenang di dalam mobil, tidak ada yang bisa keluar!"
  },
  AvgDialog_126911_Content_60 = {
    Text = "Para penumpang, apakah kalian sudah beristirahat dengan baik di kereta pulang?"
  },
  AvgDialog_126911_Content_61 = {
    Text = "Setelah mendeteksi bahwa semua penumpang telah memasuki keadaan tidur, N kecil telah menyiapkan lingkungan yang tenang dan gelap untuk kalian!"
  },
  AvgDialog_126911_Content_62 = {
    Text = "Maaf, biasanya saya bergantung pada minum banyak kopi untuk tetap terjaga..."
  },
  AvgDialog_126911_Content_63 = {
    Text = "Tunggu, apakah kita kekurangan satu orang?"
  },
  AvgDialog_126911_Content_65 = {
    Text = "Hmm? Apakah bibit kecil sedang melihatku? Aku ada di sini."
  },
  AvgDialog_126911_Content_66 = {
    Text = "Jadi, orang yang hilang adalah..."
  },
  AvgDialog_126911_Content_67 = {
    Text = "Semua orang memandang ke ujung gerbong——"
  },
  AvgDialog_126911_Content_68 = {
    Text = "Tinct memiliki lubang besar yang tembus di tenggorokannya akibat suatu benda tajam, plasma darah mengalir dari luka di lehernya yang anggun seperti swan, membasahi bagian depan gaunnya."
  },
  AvgDialog_126911_Content_69 = {
    Text = "Burung malam yang berdarah, tidak bisa bernyanyi lagi."
  },
  AvgDialog_126911_Content_7 = {
    Text = "Kau kenapa lagi... Bukankah Thais baru saja..."
  },
  AvgDialog_126911_Content_70 = {
    Text = "<Shake:Yi——iya————!!!>"
  },
  AvgDialog_126911_Content_71 = {
    Text = "Winkle mengeluarkan teriakan yang menyayat hati, tubuhnya meluncur di sepanjang dinding hingga ke sudut, kedua lengan erat memeluk tubuhnya sendiri, tidak bisa berhenti bergetar."
  },
  AvgDialog_126911_Content_72 = {
    Text = "<Shake:Maaf, aku tidak seharusnya begitu percaya diri, aku tidak seharusnya menjaga malam sendirian, aku tidak seharusnya merasa tidak akan tertidur tanpa kopi...>"
  },
  AvgDialog_126911_Content_73 = {
    Text = "Winkle gelisah menggigit kukunya sendiri, air mata panik terus mengalir, menetes di atas karpet."
  },
  AvgDialog_126911_Content_74 = {
    Text = "Klang! Si N yang peka mendengar apa? <Shake:Permintaan penumpang>!"
  },
  AvgDialog_126911_Content_75 = {
    Text = "Sekarang kami akan memberikan layanan yang penuh perhatian kepada penumpang—<Yellow:mesin kopi tanpa batas>!"
  },
  AvgDialog_126911_Content_76 = {
    Text = "Asalkan kamu menekan tombol merah ini, akan ada kehangatan yang mendalam dan tak terhingga dari semprotan yang keluar!"
  },
  AvgDialog_126911_Content_77 = {
    Text = "Kamu maju tanpa suara, mengangkat tangan——"
  },
  AvgDialog_126911_Content_78 = {
    Text = "Lalu dengan keras menghancurkan si kecil N yang mengganggu di depan ini."
  },
  AvgDialog_126911_Content_79 = {
    Text = "<Shake:Maaf, maaf, maaf…>"
  },
  AvgDialog_126911_Content_8 = {
    Text = "Hmph, jika mati semudah itu, aku bukan si kecil N!"
  },
  AvgDialog_126911_Content_80 = {
    Text = "Suara isak tangis Winkle bergema di dalam gerbong."
  },
  AvgDialog_126911_Content_81 = {
    Text = "Tidak peduli bagaimana kalian melawan, dengan kematian Tinct sebagai pembuka——"
  },
  AvgDialog_126911_Content_82 = {
    Text = "Pembunuhan diri sendiri, sudah dimulai."
  },
  AvgDialog_126911_Content_9 = {
    Text = "Bagaimana, apakah semua orang sudah memutuskan target bunuh malam ini di dalam hati mereka?"
  },
  AvgDialog_126912_Content_1 = {
    Text = "Serangan Tersembunyi"
  },
  AvgDialog_126912_Content_10 = {
    Text = "Entah mengapa, kamu selalu merasa bahwa di balik senyuman itu tersembunyi suatu emosi yang masih tidak dikenal olehmu."
  },
  AvgDialog_126912_Content_11 = {
    Text = "Ayo, Miryam. Kita pergi ke gerbong nomor 1."
  },
  AvgDialog_126912_Content_12 = {
    Text = "Saat pintu penghubung hampir menutup, Wanda menoleh ke samping."
  },
  AvgDialog_126912_Content_13 = {
    Text = "Selamat Perayaan Tahun Baru, Penjaga."
  },
  AvgDialog_126912_Content_15 = {
    Text = "Gerbong nomor 2"
  },
  AvgDialog_126912_Content_16 = {
    Text = "Setelah Wanda dan Miryam pergi, hanya tersisa kamu dan Thais di dalam gerbong."
  },
  AvgDialog_126912_Content_17 = {
    Text = "Selanjutnya, waktu sendirian yang jarang terjadi, apa yang sebaiknya kita lakukan, bibit kecilku?"
  },
  AvgDialog_126912_Content_18 = {
    Text = "Thais mendekat dengan niat jahat, kamu terkejut dan melompat mundur setengah langkah, menjaga jarak yang aman."
  },
  AvgDialog_126912_Content_19 = {
    Text = "Aku bisa pergi untuk mengejar laporan......"
  },
  AvgDialog_126912_Content_2 = {
    Text = "Gerbong nomor 2"
  },
  AvgDialog_126912_Content_20 = {
    Text = "Sudah menjadi Perayaan Tahun Baru, relaks sebentar, jangan terus memikirkan laporanmu."
  },
  AvgDialog_126912_Content_21 = {
    Text = "Lengan berwarna madu miliknya dengan lembut melingkari bahumu, napas yang ambigu melilitmu seperti kabut malam."
  },
  AvgDialog_126912_Content_22 = {Text = "Ini……"},
  AvgDialog_126912_Content_23 = {
    Text = "Wajah serius Doll, suara desahan Ramona, dan tongkat pengajar Czort seketika muncul di depan matamu."
  },
  AvgDialog_126912_Content_24 = {
    Text = "Tetap tidak bisa..."
  },
  AvgDialog_126912_Content_25 = {
    Text = "Kau tersenyum dengan genit, seolah-olah secara tidak sengaja menghindari kedekatan Thais."
  },
  AvgDialog_126912_Content_26 = {
    Text = "Baiklah, lalu kita duduk dengan tenang dan mengobrol sebentar, bagaimana?"
  },
  AvgDialog_126912_Content_27 = {
    Text = "Beritahu aku, Penjaga... di saat tatapanmu menghindar, siapa yang kau rindukan dalam pikiranmu?"
  },
  AvgDialog_126912_Content_29 = {
    Text = "……………"
  },
  AvgDialog_126912_Content_3 = {
    Text = "Di tengah suara deru kereta, Wanda yang pertama kaliPecahkan Keheningan."
  },
  AvgDialog_126912_Content_30 = {
    Text = "Kamu tidak ingat sudah bercerita berapa lama, yang kamu tahu hanyalah segala hal dari masa lalu masih jelas dalam ingatan."
  },
  AvgDialog_126912_Content_31 = {
    Text = "Ada juga kantin Mythag, tempat yang jauh lebih ramai daripada laboratorium."
  },
  AvgDialog_126912_Content_32 = {
    Text = "Terutama saat kue kecil dipajang, anak-anak akan berlari ke meja dengan penuh semangat, sama sekali tidak memperhatikan keanggunan dan kebajikan kesopanan seorang wanita..."
  },
  AvgDialog_126912_Content_33 = {
    Text = "Masih ada beberapa nakal kecil yang akan curang, membiarkan teman hewan mereka menggigit kupon makanan untuk menduduki tempat di pintu keluar makanan lebih awal, lalu mengirimkan kue yang direbut kepada teman mereka yang penakut."
  },
  AvgDialog_126912_Content_34 = {
    Text = "<Shake:Masih ada... Eh?>"
  },
  AvgDialog_126912_Content_35 = {
    Text = "Kamu menyadari bahwa nada suaramu mulai tercekat, air mata mengalir tanpa bisa ditahan dari sudut matamu."
  },
  AvgDialog_126912_Content_36 = {
    Text = "Dan juga……"
  },
  AvgDialog_126912_Content_37 = {
    Text = "Air mata semakin banyak mengumpul, dan pandangan semakin kabur."
  },
  AvgDialog_126912_Content_38 = {
    Text = "<Shake: Aku sangat ingin kembali ke Mythag, kembali ke sisi semua orang…>"
  },
  AvgDialog_126912_Content_39 = {
    Text = "Sangat aneh, jelas saya <Yellow:Tiga hari yang lalu> baru saja meninggalkan Mythag untuk melakukan penelitian lapangan, seharusnya tidak…"
  },
  AvgDialog_126912_Content_4 = {
    Text = "Saya memiliki sebuah usulan."
  },
  AvgDialog_126912_Content_40 = {
    Text = "Namun kepedihan kerinduan membuat hidungmu terasa perih, seolah-olah ada senar yang tegang di dalam otakmu mendekati batas putus."
  },
  AvgDialog_126912_Content_41 = {
    Text = "Tenang, tenang, Penjaga."
  },
  AvgDialog_126912_Content_42 = {
    Text = "Kau terbenam dalam pelukan yang lembut. Pelukan Ibu."
  },
  AvgDialog_126912_Content_43 = {
    Text = "@2Aku berjanji padamu, kamu akan kembali ke tempat yang kamu rindukan."
  },
  AvgDialog_126912_Content_44 = {
    Text = "Wajah Thais menjadi kabur."
  },
  AvgDialog_126912_Content_45 = {
    Text = "Kabut samar menyelimuti kalian berdua, kamu meringkuk dengan tenang di pelukannya, berubah menjadi sangat kecil."
  },
  AvgDialog_126912_Content_46 = {
    Text = "Kamu mencium aroma. <Yellow:Aroma melati putih>."
  },
  AvgDialog_126912_Content_47 = {
    Text = "<Red:Aroma magnolia putih yang besar-besar.>"
  },
  AvgDialog_126912_Content_48 = {
    Text = "Kamu terjebak dalam pelukan aroma yang harum ini, terjatuh ke dalam tidur seperti bayi yang membuatmu melupakan semua kekhawatiran dan ketakutan."
  },
  AvgDialog_126912_Content_49 = {
    Text = "Sebelum kesadaran memudar, yang kamu ingat hanyalah <Yellow:Mata ibu yang berwarna emas, yang memikat>."
  },
  AvgDialog_126912_Content_5 = {
    Text = "Kita bisa dibagi menjadi dua kelompok, masing-masing tinggal di gerbong 1 dan 2, sehingga bisa saling menjaga."
  },
  AvgDialog_126912_Content_51 = {Text = "Lalu——"},
  AvgDialog_126912_Content_52 = {
    Text = "\"Klang\"suara keras datang dari gerbong nomor 1."
  },
  AvgDialog_126912_Content_53 = {
    Text = "Kamu tahu, permainan bunuh diri masih berlanjut, mimpi harus segera berakhir."
  },
  AvgDialog_126912_Content_54 = {
    Text = "Gerbong nomor 1"
  },
  AvgDialog_126912_Content_55 = {
    Text = "Di dalam gerbong nomor 1, Wanda dan tubuh Miryam yang terluka parah terjerat satu sama lain, sebuah belati sepenuhnya tertusuk ke dada Wanda, sementara Miryam ditusuk oleh banyak spike."
  },
  AvgDialog_126912_Content_56 = {
    Text = "Wanda setengah membuka matanya yang kosong, terputus-putus mengungkapkan kepada kalian."
  },
  AvgDialog_126912_Content_57 = {
    Text = "Aku sudah tahu, Miryam pasti akan menyerang, jadi, aku sudah siap dengan \"Counter\"…"
  },
  AvgDialog_126912_Content_58 = {
    Text = "Sekarang, N sama sekali tidak bisa mencapai kemenangannya..."
  },
  AvgDialog_126912_Content_59 = {
    Text = "Kalian pasti harus……"
  },
  AvgDialog_126912_Content_6 = {
    Text = "Apakah tidak berbahaya bagi orang yang ditinggalkan di dekat pelaku?"
  },
  AvgDialog_126912_Content_60 = {
    Text = "Nada akhir Wanda menghilang. Berkah dalam kata-katanya pun lenyap dalam keheningan."
  },
  AvgDialog_126912_Content_61 = {
    Text = "Setelah hening yang panjang, Thais akhirnya membuka mulutnya dengan gemetar."
  },
  AvgDialog_126912_Content_62 = {
    Text = "Tampaknya pelakunya memang Miryam. Dia tahu bahwa di bawah aturan saling menjaga antara keduanya, dia harus membunuh Wanda terlebih dahulu, jika tidak, aksinya pasti akan mengundang permusuhan dari semua orang yang tersisa, jadi dia bertindak."
  },
  AvgDialog_126912_Content_63 = {
    Text = "Wanda... tepat karena dia tahu dirinya ahli dalam \"Counter\", jadi dia secara sukarela berada dalam satu ruangan dengan pengkhianat Miryam."
  },
  AvgDialog_126912_Content_64 = {
    Text = "Dia dengan pengorbanannya, memperoleh kemenangan bagi\"Orang Baik\"."
  },
  AvgDialog_126912_Content_65 = {
    Text = [[
Nada suara Thais, berat namun mengandung sedikit rasa hormat. 
 Jika bisa, kau sangat berharap ini berasal dari hati yang tulus.]]
  },
  AvgDialog_126912_Content_66 = {
    Text = "Sayang sekali bukan."
  },
  AvgDialog_126912_Content_67 = {
    Text = "Tidak… Miryam… bukan N yang menyusup di antara kita sebagai pengkhianat."
  },
  AvgDialog_126912_Content_68 = {
    Text = "<Shake:Bukan dia? Lalu mengapa dia?…>"
  },
  AvgDialog_126912_Content_69 = {
    Text = "Untuk kemenangan, untuk menang, demi \"Lemuria\" yang dijanjikan N, Miryam yang saya kenal memang tidak ragu untuk turun tangan sendiri."
  },
  AvgDialog_126912_Content_7 = {
    Text = "Tapi setidaknya ini bisa memastikan N tidak akan mendapatkan kemenangan akhir."
  },
  AvgDialog_126912_Content_70 = {
    Text = "Kalau begitu……"
  },
  AvgDialog_126912_Content_71 = {
    Text = "Pengkhianat sejati adalah kamu. Thais, atau bisa dibilang, <Yellow:seseorang yang menyamar sebagai Thais>."
  },
  AvgDialog_126912_Content_72 = {
    Text = "Mungkin persiapanmu sudah cukup, Thais tidak menunjukkan terlalu banyak keheranan, hanya menatap matamu dengan tenang dan senyuman di matanya."
  },
  AvgDialog_126912_Content_73 = {
    Text = "Oh? Kapan kamu menemukannya? Aku ingin mendengarnya."
  },
  AvgDialog_126912_Content_74 = {
    Text = "Kerang… Setelah pergi, Wanda mengusulkan untuk membagi dua gerbong sebelumnya."
  },
  AvgDialog_126912_Content_75 = {
    Text = "Sungguh... begitu cepat? Aku pikir, metode yang aku pilih sudah cukup hati-hati, tidak meninggalkan banyak petunjuk."
  },
  AvgDialog_126912_Content_76 = {
    Text = "Luka tembus di tubuh Tinct bisa berasal dari duri Thais, spike Wanda, atau belati yang dibawa Miryam."
  },
  AvgDialog_126912_Content_77 = {
    Text = "Dan kematian Winkle... Thais, Wanda, dan Miryam semuanya memiliki kemampuan untuk memberikan Racun."
  },
  AvgDialog_126912_Content_78 = {
    Text = "Mengingat jumlah konsumsi kopi Winkle, asalkan racun dimasukkan ke dalam mesin kopi, kematian pasti akan datang pada suatu saat."
  },
  AvgDialog_126912_Content_79 = {
    Text = "Jadi, ya, dalam metode pembunuhan, penyamaranmu sangat berhasil."
  },
  AvgDialog_126912_Content_8 = {
    Text = "Aku yang akan menjaga Miryam. Tenang saja, aku menyimpan kartu truf yang pasti tidak terduga oleh lawan."
  },
  AvgDialog_126912_Content_80 = {
    Text = "Lalu dasar penalaranmu adalah...?"
  },
  AvgDialog_126912_Content_81 = {
    Text = "Apakah kamu pernah mendengar tentang permainan pesta yang bernama \"Malam Bulan Darah\"? Setiap Bulan Darah, para serigala akan membuka mata dan mulai berburu, lalu pada siang kedua mereka menyusup di antara orang-orang baik."
  },
  AvgDialog_126912_Content_82 = {
    Text = "Untuk membedakan serigala yang tersembunyi, hal terpenting adalah menyimpulkan tujuan setiap orang selama fase berbicara. Serigala tahu identitas orang baik, jadi penunjukan mereka seringkali lebih pasti."
  },
  AvgDialog_126912_Content_83 = {
    Text = "Dan Thais yang sebenarnya adalah ratu yang bersembunyi selama seribu tahun di Aran, warna kepribadiannya sangat berbeda dari penampilannya. Ia bertindak dengan hati-hati, dan jelas bukan orang yang dengan mudah menuduh orang lain."
  },
  AvgDialog_126912_Content_84 = {
    Text = "Jadi kamu memilih aku, bukan Miryam."
  },
  AvgDialog_126912_Content_85 = {
    Text = "Saya secara aktif berada dalam satu ruangan dengan pelaku."
  },
  AvgDialog_126912_Content_86 = {
    Text = "Aku awalnya bersiap untuk menangkapmu saat kamu beraksi, sayangnya, aksi Miryam lebih cepat darimu..."
  },
  AvgDialog_126912_Content_87 = {
    Text = "Sebelum kamu menyelesaikan hipnosis terhadapku, dia sudah menyerang Wanda."
  },
  AvgDialog_126912_Content_88 = {
    Text = "Luar biasa, penalaran yang luar biasa. Benar-benar membuatku terkesan."
  },
  AvgDialog_126912_Content_89 = {
    Text = "Tidak, masih jauh dari cukup… Lagi pula, aku tidak berniat untuk berperan sebagai detektif dalam cerita ini sesuai dengan rencana N kecil."
  },
  AvgDialog_126912_Content_9 = {
    Text = "Wanda menyipitkan matanya dan menunjukkan senyuman yang menenangkan."
  },
  AvgDialog_126912_Content_90 = {
    Text = "Saya lebih berharap, sebelum kasus ini terjadi, bisa menghentikan rencana jahat kalian. Tapi sudah terlambat."
  },
  AvgDialog_126912_Content_91 = {
    Text = "Sekarang, saya hanya bisa meminta kamu untuk memberi tahu saya... siapa sebenarnya wujud aslimu?"
  },
  AvgDialog_126912_Content_92 = {
    Text = "Cahaya perak meledak dari kunci perak di dadamu, seolah ingin menembus semua kekosongan dan penyamaran."
  },
  AvgDialog_126912_Content_93 = {
    Text = "Hehe, hohohoho~"
  },
  AvgDialog_126912_Content_94 = {
    Text = "Seranganmu sepertinya jatuh ke udara."
  },
  AvgDialog_126912_Content_95 = {
    Text = "Dia berubah menjadi asap, menjadi kabut, menjadi keberadaan yang tidak dapat ditangkap dan tidak dapat dijelaskan."
  },
  AvgDialog_126912_Content_96 = {
    Text = "Mari, ikutlah denganku."
  },
  AvgDialog_126912_Content_97 = {
    Text = "Kabut tertawa tawa, mengajakmu dengan undangan yang ambigu dan misterius."
  },
  AvgDialog_126912_Content_98 = {
    Text = "Ayo berjalan bersamaku menuju kebenaran cerita."
  },
  AvgDialog_128696_Content_1 = {
    Text = "Bam! Dong! Bam! Dong"
  },
  AvgDialog_128696_Content_10 = {Text = "Nautila!"},
  AvgDialog_128696_Content_11 = {
    Text = "Mosk dengan panik berlari ke depan, berbaring di dada Nautila, dan menemukan bahwa Nautila hanya terlalu ngantuk, sampai tertidur lelap."
  },
  AvgDialog_128696_Content_12 = {
    Text = "Mosk menghela napas lega dan tidak bisa menahan tawa besar."
  },
  AvgDialog_128696_Content_13 = {
    Text = "Pff, hahahaha!"
  },
  AvgDialog_128696_Content_14 = {
    Text = "Dia mengangkat Nautila ke tempat tidur, mengabaikan perlawananmu dan menggulungmu di lantai beberapa kali."
  },
  AvgDialog_128696_Content_15 = {
    Text = "Keluar, kita, tidak perlu berpisah!"
  },
  AvgDialog_128696_Content_16 = {
    Text = "Ini adalah pertama kalinya Mosk merasa begitu santai sejak hari itu, matanya bercahaya karena harapan, dengan ujung hidungnya yang bahagia mengacak-acak bulu lembut di dadamu."
  },
  AvgDialog_128696_Content_17 = {
    Text = "Tidur... sebentar saja... besok pagi... besok pagi..."
  },
  AvgDialog_128696_Content_18 = {
    Text = "Mosk yang juga sudah beberapa hari tidak tidur, memelukmu erat-erat, bersandar di sudut tempat tidur Nautila, dan juga terlelap dengan nyenyak."
  },
  AvgDialog_128696_Content_2 = {
    Text = "Boom——Boom boom——Boom!"
  },
  AvgDialog_128696_Content_20 = {
    Text = "@2, Mosk, @4……"
  },
  AvgDialog_128696_Content_21 = {
    Text = "@4 mendekati……"
  },
  AvgDialog_128696_Content_23 = {
    Text = "Kapal baru saja berlayar setengah hari, tanpa peringatan, badai besar pun datang."
  },
  AvgDialog_128696_Content_24 = {
    Text = "Arah sepenuhnya hilang, hujan turun deras, tidak memberikan kesempatan bagi para penantang yang tidak tahu diri untuk mundur."
  },
  AvgDialog_128696_Content_25 = {
    Text = "Roda kemudi menyimpang dengan aneh, terlepas dari usaha Nautila dan Mosk, bahkan hampir merusaknya, tidak ada tanda-tanda untuk kembali ke jalur yang benar."
  },
  AvgDialog_128696_Content_26 = {
    Text = "Bagaimana bisa, seharusnya tidak seperti ini! Tidak ada tanda peringatan sama sekali, tekanan udara semuanya normal... tidak ada masalah apapun sampai kami mendekati perairan ini."
  },
  AvgDialog_128696_Content_27 = {
    Text = "Sungguh… sungguh seolah-olah pusaran ini menciptakan angin yang tiba-tiba, sengaja menjebak kita"
  },
  AvgDialog_128696_Content_28 = {Text = "Jebakan?"},
  AvgDialog_128696_Content_29 = {
    Text = "Justru saat-saat paling dekat dengan pusaran, padahal hanya perlu lima, tidak, bahkan tiga mil laut lagi, sudah cukup bagi kita untuk keluar dari jangkauan pengaruh pusaran."
  },
  AvgDialog_128696_Content_3 = {
    Text = "Raksasa baja yang telah lama tertidur mengeluarkan deru serak, peluit berbunyi, dan di tengah suara sayap burung camar, seluruh kapal seolah-olah perlahan-lahan hidup kembali."
  },
  AvgDialog_128696_Content_30 = {
    Text = "Kepalamu sudah kacau, kamu berusaha keras untuk mengeluarkan suara, apa itu……"
  },
  AvgDialog_128696_Content_31 = {
    Text = "Ah, ah——!"
  },
  AvgDialog_128696_Content_32 = {
    Text = "Kamu hanya bisa mengeluarkan teri bingung, kamu tidak mengerti, apakah mereka tidak merasakannya?"
  },
  AvgDialog_128696_Content_33 = {
    Text = "(Jangan mendekati pusaran, raksasa, jangan mendekati pusaran!)"
  },
  AvgDialog_128696_Content_34 = {
    Text = "Keberadaan yang besar dan mengerikan itu, Dia melihat Mosk."
  },
  AvgDialog_128696_Content_35 = {
    Text = "<Red:Dia tidak siap membiarkan siapa pun pergi>"
  },
  AvgDialog_128696_Content_37 = {
    Text = "Tidak apa-apa, Bola arang kecil, Mosk, di sini."
  },
  AvgDialog_128696_Content_38 = {
    Text = "Ya, percayalah padaku, Bola arang kecil, Mosk. Masih ada cara, aku pasti bisa memikirkan cara!"
  },
  AvgDialog_128696_Content_39 = {
    Text = "Nautila……"
  },
  AvgDialog_128696_Content_4 = {
    Text = "Mesin, langkah terakhir..."
  },
  AvgDialog_128696_Content_40 = {
    Text = "Aku yang harus membawa kapal pergi, aku yang membawa kalian ke sini, aku pasti bisa memikirkan cara, aku pasti bisa membuat kalian selamat!"
  },
  AvgDialog_128696_Content_41 = {
    Text = "<Change>Gali badan kapal di posisi ini, gunakan air untuk menambah berat..."
  },
  AvgDialog_128696_Content_42 = {
    Text = "<Change>Tidak bisa... @2tenaga, ya, jika, Asalkan memaksakan salah satu mesin, melepaskan diri dari daya tarik@1"
  },
  AvgDialog_128696_Content_43 = {
    Text = "Gadis itu terburu-buru membawa kamu dan Mosk berkeliling di berbagai ruangan, terus mencoba berbagai cara, dan di matanya perlahan dipenuhi dengan merah darah yang gila."
  },
  AvgDialog_128696_Content_44 = {
    Text = "Jiang lang—— Bam!"
  },
  AvgDialog_128696_Content_45 = {
    Text = "Nautila……"
  },
  AvgDialog_128696_Content_46 = {
    Text = "Bersamaan dengan kehilangan tenaga, kunci pas menghantam dinding, lalu jatuh keras di kaki Nautila, namun, dia seolah-olah tidak merasakan sakit dan berucap ingin terus mengambil kunci pas itu."
  },
  AvgDialog_128696_Content_47 = {
    Text = "<Change>Tidak ada waktu lagi, pusaran semakin dekat... Kenapa, kenapa, kenapa, kenapa!! Aku harus menyelamatkan kalian, aku pasti... pasti...!"
  },
  AvgDialog_128696_Content_48 = {
    Text = "Kak——Bam——!"
  },
  AvgDialog_128696_Content_49 = {
    Text = "Badai dan pukulan akhirnya melampaui batas kapal, setelah suara retakan yang nyaring, papan tua jatuh dengan cepat dari atas Nautila——"
  },
  AvgDialog_128696_Content_5 = {
    Text = "Bagus sekali! Mosk, Bola arang kecil, kita berhasil"
  },
  AvgDialog_128696_Content_50 = {
    Text = "<Big:Nautila! Berhenti!>"
  },
  AvgDialog_128696_Content_51 = {
    Text = "Membuka mata yang tertutup karena ketakutan, di depan Nautila terpampang sebuah pemandangan yang tak terduga."
  },
  AvgDialog_128696_Content_52 = {
    Text = "Mosk bersandar pada dinding dengan satu tangan, melindungi dirinya di bawahnya, sementara tangan yang lain menopang seluruh langit-langit."
  },
  AvgDialog_128696_Content_53 = {Text = "Ngh..."},
  AvgDialog_128696_Content_54 = {Text = "Ha!"},
  AvgDialog_128696_Content_55 = {
    Text = "Mosk dengan kuat mendorong langit-langit ke tempat lain, kemudian menarik Nautila yang hampir gila, memegang wajahnya dengan kedua tangan dan mengarahkan pandangannya ke arah dirinya."
  },
  AvgDialog_128696_Content_56 = {
    Text = "Tidak apa-apa, pulang, lain kali."
  },
  AvgDialog_128696_Content_57 = {
    Text = "Kembali... namun..."
  },
  AvgDialog_128696_Content_58 = {
    Text = "Nautila memandang sekeliling dengan bingung, membiarkan tirai hujan yang deras membasahi tubuhnya."
  },
  AvgDialog_128696_Content_59 = {
    Text = "Badai menyertai guntur dan kilat, merangsang setiap saraf, seperti musik yang tak henti-hentinya di jamuan setan."
  },
  AvgDialog_128696_Content_6 = {
    Text = "Setelah itu, Nautila terus memperbaiki badan kapal tanpa henti, masih tersisa tiga hari sebelum badai diperkirakan datang, semua komponen kunci telah kembali ke tempat yang seharusnya."
  },
  AvgDialog_128696_Content_60 = {
    Text = "Daya tarik pusaran terlalu besar, kami sudah tidak bisa kembali lagi…"
  },
  AvgDialog_128696_Content_61 = {
    Text = "Mosk tidak menghiraukan kata-kata Nautila, menarik pakaian selam dari kabin kapal, mencoba dengan sembarangan untuk mengenakan pakaian itu ke tubuh Nautila."
  },
  AvgDialog_128696_Content_62 = {
    Text = "Baju selam? Tidak bisa, jika aku memakainya, kamu bagaimana?"
  },
  AvgDialog_128696_Content_63 = {
    Text = "Saat ini, badan kapal sudah mulai miring sepenuhnya ke arah vortex tanpa kendali."
  },
  AvgDialog_128696_Content_64 = {
    Text = "<Shake:Ciiit——ya——>"
  },
  AvgDialog_128696_Content_7 = {
    Text = "Asalkan jangkarnya dipasang lagi... huh... sangat mengantuk..."
  },
  AvgDialog_128696_Content_8 = {Text = "Plung."},
  AvgDialog_128696_Content_9 = {
    Text = "Ciiit?! Ciiit——? (Orang?! Orang——?)"
  },
  AvgDialog_128697_Content_1 = {
    Text = "Baik, lebih baik, lebih lebih baik"
  },
  AvgDialog_128697_Content_11 = {Text = "*Sorak"},
  AvgDialog_128697_Content_12 = {
    Text = "Meskipun memang daya hancurnya sedikit kuat."
  },
  AvgDialog_128697_Content_13 = {
    Text = "Penjaga! Mosk! Kalahkan tugas jahat! Hebat!"
  },
  AvgDialog_128697_Content_14 = {
    Text = "Hei... penjaga rahasia... Bola arang kecil?!"
  },
  AvgDialog_128697_Content_15 = {
    Text = "Mosk dengan naluri seperti binatang buas segera merasakan ada yang berbeda, dia melompat seperti hewan dan memelukmu dengan erat."
  },
  AvgDialog_128697_Content_16 = {
    Text = "Auh! Mosk, sakit!"
  },
  AvgDialog_128697_Content_17 = {
    Text = "Sementara itu, dia juga memukul hidung malangmu dengan mulutnya."
  },
  AvgDialog_128697_Content_18 = {
    Text = "Kandang mulut, alat pembatas, Mosk baja, bagus! Hehe, Mosk, aman."
  },
  AvgDialog_128697_Content_19 = {
    Text = "Mythag telah merancang perangkat khusus untuknya yang dengan baik mengontrol keluarnya kekuatan, saat ini kekuatan penghancuran maksimum Mosk hanya setara dengan seorang manusia biasa yang sedikit lebih kuat."
  },
  AvgDialog_128697_Content_2 = {
    Text = "Halo, Penjaga. Mengenai Awakener O-1841, mengingat ia baru saja bangun dan kadang menunjukkan tanda-tanda fury, serta tidak dapat sepenuhnya mengontrol kemampuannya, disarankan untuk tetap waspada saat berinteraksi dengannya."
  },
  AvgDialog_128697_Content_20 = {
    Text = "Teman-teman, kemudian, petualangan yang sangat sempurna, ada? Tidak ada?"
  },
  AvgDialog_128697_Content_21 = {
    Text = "Kamu mengeluarkan banyak tenaga untuk melepaskan anjing besar yang sedang bermain dari tubuhmu, akhirnya dia mau diam sejenak, duduk di depan meja belajar, matanya berkilau menatapmu."
  },
  AvgDialog_128697_Content_22 = {Text = "Hmm..."},
  AvgDialog_128697_Content_23 = {
    Text = "Sebenarnya……"
  },
  AvgDialog_128697_Content_24 = {
    Text = "Di bawah Vortex M-Panggilan Meruskus terdapat D-rongga yang sangat besar, meskipun Nautila dan aku telah lepas dari pengaruh Vortex, kami berdua pada dasarnya menunjukkan tanda-tanda kehilangan ingatan."
  },
  AvgDialog_128697_Content_25 = {
    Text = "Kamu hanya berhenti sejenak, lalu memilih untuk menggunakan \"Saya\" sebagai sebutan untuk kesadaran itu di dalam mimpi."
  },
  AvgDialog_128697_Content_26 = {
    Text = "Nautila terus berusaha menemukanmu setelah itu, dia membentuk sebuah kelompok petualangan, namun saat kembali, dia secara tidak sengaja menemui bencana lainnya……"
  },
  AvgDialog_128697_Content_27 = {
    Text = "Meskipun dia mungkin sudah tidak ingat, tapi... dia membuat pilihan yang sama sepertimu."
  },
  AvgDialog_128697_Content_28 = {
    Text = "Begitu ya..."
  },
  AvgDialog_128697_Content_29 = {
    Text = "Tetapi, itu sangat bagus."
  },
  AvgDialog_128697_Content_3 = {
    Text = "Terima kasih, Erica. Tapi tidak apa-apa, saya rasa saya sudah cukup mengenal teman saya..."
  },
  AvgDialog_128697_Content_30 = {Text = "Tentu saja"},
  AvgDialog_128697_Content_31 = {
    Text = "Tentu ada! Kemudian, aku dan Nautila..."
  },
  AvgDialog_128697_Content_32 = {
    Text = "Singkatnya, sampai aku dan Nautila tua hingga tidak bisa bergerak, kami terus mengalami berbagai macam petualangan."
  },
  AvgDialog_128697_Content_33 = {
    Text = "Kamu berpikir keras, mengumpulkan semua cerita petualangan yang pernah kamu dengar dalam satu tahun kehidupanmu yang penuh kesadaran, dan menyusunnya menjadi kisah untuk Mosk."
  },
  AvgDialog_128697_Content_34 = {
    Text = "Bagaimanapun, ya Tuhan, kamu benar-benar tidak bisa mengucapkan kata-kata kejam di depan sepasang mata ini."
  },
  AvgDialog_128697_Content_35 = {
    Text = "Cerita @2 Lu, Mosk, pernah mendengarnya."
  },
  AvgDialog_128697_Content_36 = {
    Text = "<Gray:Selesai, lupa ini adalah bacaan mata kuliah umum...>"
  },
  AvgDialog_128697_Content_37 = {
    Text = "Tidak apa-apa."
  },
  AvgDialog_128697_Content_38 = {Text = "Eh?"},
  AvgDialog_128697_Content_39 = {
    Text = "Mosk menundukkan kepala, seperti saat kamu masih bola arang kecil, menempelkan wajahnya di telapak tanganmu."
  },
  AvgDialog_128697_Content_4 = {
    Text = "Berbeda dengan yang diperkirakan akademi, tautan pertamamu dengan Awakener yang memiliki kekuatan Fury ini berjalan dengan sangat lancar."
  },
  AvgDialog_128697_Content_40 = {
    Text = "Teman, Bola arang kecil, kita bertemu lagi."
  },
  AvgDialog_128697_Content_41 = {
    Text = "Bola arang kecil, mengalami gelap gulita, ingat Mosk, baik."
  },
  AvgDialog_128697_Content_42 = {
    Text = "Dia menyeringai, memberimu senyuman yang sangat-sangat bahagia."
  },
  AvgDialog_128697_Content_43 = {
    Text = "Meskipun, gelang tangan, sudah tidak ada."
  },
  AvgDialog_128697_Content_44 = {
    Text = "Tapi, kita bertemu kembali, lebih baik, lebih baik dari yang lebih baik!"
  },
  AvgDialog_128697_Content_45 = {Text = "Mosk…"},
  AvgDialog_128697_Content_46 = {Text = "Cicit?"},
  AvgDialog_128697_Content_47 = {
    Text = "?? Kenapa di sini ada seekor berang-berang yang mengenakan topi Mythag?"
  },
  AvgDialog_128697_Content_48 = {
    Text = "Maaf, Penjaga, sepertinya banyak pelajar sangat menyukai ikan laut asing ini dan telah memberikan beberapa dekorasi yang tidak perlu padanya."
  },
  AvgDialog_128697_Content_49 = {
    Text = "Erica akan segera memulai program pengusiran, 1, 2——"
  },
  AvgDialog_128697_Content_5 = {
    Text = "Setelah mimpi yang tidak terduga ini, kamu merasa bahwa kamu telah menemukan jawabannya."
  },
  AvgDialog_128697_Content_50 = {
    Text = "Ah, berang-berang laut! Menggemaskan, ayo bermain dengan Mosk!"
  },
  AvgDialog_128697_Content_51 = {
    Text = "Bum, dung, klang——"
  },
  AvgDialog_128697_Content_52 = {Text = "BRAK!"},
  AvgDialog_128697_Content_53 = {Text = "Sss, Mosk!"},
  AvgDialog_128697_Content_54 = {
    Text = "Nautila baru saja memasuki ruang kelas, dan melihat teman baik barunya sedang mengejar seekor berang-berang yang mengenakan topi Mythag, yang berlari dengan sembrono dan merusak peralatan pengajaran di dalam kelas."
  },
  AvgDialog_128697_Content_55 = {
    Text = "Penjaga, katakan kepada guru Erica, saya akan memperbaiki semua barang di dalam kelas"
  },
  AvgDialog_128697_Content_56 = {
    Text = "Mosk, cepat hentikan!"
  },
  AvgDialog_128697_Content_57 = {
    Text = "Ah——Ah!"
  },
  AvgDialog_128697_Content_58 = {Text = "Ah!"},
  AvgDialog_128697_Content_59 = {Text = "*Sorak"},
  AvgDialog_128697_Content_6 = {
    Text = "Dia suka daging panggang, suka laut, sangat penakut, benci kedinginan, kegelapan, dan kesepian, serta akan menangis pelan saat menghadapi mereka."
  },
  AvgDialog_128697_Content_60 = {
    Text = "Jika saya tidak salah paham, itu berang-berang laut sedang berkata \"Bermain denganku\", kan...? Bagaimana dia berkomunikasi dengan Mosk?"
  },
  AvgDialog_128697_Content_61 = {
    Text = "Eh, tidak benar, mengapa aku juga bisa mengerti suara berang-berang berbicara?!"
  },
  AvgDialog_128697_Content_62 = {
    Text = "Tunggu, kalau begitu……"
  },
  AvgDialog_128697_Content_63 = {
    Text = "Ehem, berang-berang laut Mythag yang tidak dikenal, sekarang aku akan memberikan gelar Bola arang kecil kepada mu."
  },
  AvgDialog_128697_Content_64 = {
    Text = "Kamu akan mewarisi gelar Bola Arang Kecil, menjadi Bola Arang Kecil yang Kedua yang hebat dan mulia"
  },
  AvgDialog_128697_Content_65 = {Text = "!"},
  AvgDialog_128697_Content_66 = {
    Text = "Bola arang kecil, Dua! Bola arang kecil, Dua!"
  },
  AvgDialog_128697_Content_67 = {
    Text = "Jik——(Dampak Berang-Berang!)"
  },
  AvgDialog_128697_Content_68 = {
    Text = "Nautila——"
  },
  AvgDialog_128697_Content_69 = {
    Text = "Bagus sekali, sudah kacau balau——"
  },
  AvgDialog_128697_Content_7 = {
    Text = "Sore hari, sinar Matahari di Mythag sangat baik, Matahari menerobos melalui kaca berwarna, memproyeksikan cahaya pada wajah gadis yang sedang berkelahi dengan buku pelajaran bahasa."
  },
  AvgDialog_128697_Content_70 = {
    Text = "Jadi sebagai pewaris Bola Arang Kecil, <Small:Generasi Kedua, kamu memiliki kewajiban untuk mengatasi masalah yang dihadapi oleh Generasi Pertama...>"
  },
  AvgDialog_128697_Content_71 = {
    Text = "Kamu berpura-pura santai meniup peluit, dengan pelan, dengan pelan——"
  },
  AvgDialog_128697_Content_72 = {
    Text = "Melempar tugas kalkulusnya ke arah cakar berang-berang laut saat sedang kacau."
  },
  AvgDialog_128697_Content_73 = {
    Text = "Dalam sekejap, tugas itu berubah menjadi kertas sampah yang acak-acakan, tergeletak diam di tumpukan kertas bekas."
  },
  AvgDialog_128697_Content_74 = {
    Text = "Hari yang sangat indah, kan, Nautila, Mosk?"
  },
  AvgDialog_128697_Content_75 = {Text = "Ah——!"},
  AvgDialog_128697_Content_76 = {
    Text = "Hari ini, Mythag sangat ramah dan damai."
  },
  AvgDialog_128697_Content_77 = {
    Text = "Selamat dan gembira, selamat dan gembira."
  },
  AvgDialog_128697_Content_8 = {
    Text = "Tapi dia juga sangat berani, akan menghadapi semua hal yang dia benci demi teman-temannya."
  },
  AvgDialog_128697_Content_9 = {
    Text = "Sssrrr—— Buku teks itu terbelah dua dalam suasana yang baru saja menjadi emosional."
  },
  AvgDialog_128698_Content_1 = {
    Text = "Wussshh~ Wussshh~"
  },
  AvgDialog_128698_Content_10 = {
    Text = "Tenaga dan bahan bakar tidak masalah, tapi badan kapalnya terlalu rapuh... Mosk, adakah cara untuk menghindari Pusaran besar itu? Rombongan kapal sebelumnya mengalami kecelakaan di dekatnya."
  },
  AvgDialog_128698_Content_11 = {
    Text = "...tidak bisa keluar."
  },
  AvgDialog_128698_Content_12 = {
    Text = "Mosk menggelengkan kepala, sekali lagi memelukmu, berusaha bersama-sama dengan empat tangan dan kaki."
  },
  AvgDialog_128698_Content_13 = {
    Text = "Orang jahat, tangkap, ayah dan ibu. Mosk, gigit, ditangkap, Bola arang kecil, di kapal, bertemu."
  },
  AvgDialog_128698_Content_14 = {
    Text = "Laut, panggil——di sini, Mosk, cari cara, tidak bisa."
  },
  AvgDialog_128698_Content_15 = {
    Text = "Kamu ditangkap oleh orang jahat dan terpisah dari Ayah dan Ibu, dan tidak bisa keluar lagi?"
  },
  AvgDialog_128698_Content_16 = {
    Text = "Tidak ada, Ayah dan Ibu."
  },
  AvgDialog_128698_Content_17 = {Text = "Maaf……"},
  AvgDialog_128698_Content_18 = {
    Text = "Oh ya, Ayah Ibu, seperti, ayo!"
  },
  AvgDialog_128698_Content_19 = {
    Text = "Mosk! Kamu mau mendorongku ke mana?"
  },
  AvgDialog_128698_Content_2 = {
    Text = "Asalkan perbaikan bantalan di bagian ini selesai, kemudi kapal akan…"
  },
  AvgDialog_128698_Content_21 = {
    Text = "Huh... huh, apakah kamu monster?! Kenapa kamu masih bisa berenang begitu cepat sambil menggendongku?!"
  },
  AvgDialog_128698_Content_22 = {
    Text = "Eh, ini tempat apa?"
  },
  AvgDialog_128698_Content_23 = {Text = "Ah——!"},
  AvgDialog_128698_Content_24 = {
    Text = "Kamu yang pertama kali melompat ke dalam air dengan gembira, mengejutkan ikan-ikan di sekitarmu."
  },
  AvgDialog_128698_Content_25 = {
    Text = "Seiring dengan sorakan kegembiraan yang dihasilkan oleh kamu dan Mosk saat terjun ke dalam air, gelombang yang membalas kalian perlahan mulai bergetar dari kedalaman dasar air."
  },
  AvgDialog_128698_Content_26 = {
    Text = "Ayah Ibu, dan mereka, sama! Nautila, Mosk, sama"
  },
  AvgDialog_128698_Content_27 = {
    Text = "Sejumlah lumba-lumba putih yang cantik muncul dari dasar laut, mengelilingi kalian, dengan mesra menggosokkan bagian moncong dan siripnya ke kalian dan Mosk."
  },
  AvgDialog_128698_Content_28 = {
    Text = "Mereka dengan lembut mengelilingi kalian, bahkan melompat keluar dari permukaan air, menyemburkan sedikit mata air ke arah Nautila, seolah-olah mengundangnya."
  },
  AvgDialog_128698_Content_29 = {
    Text = "Mereka... lumba-lumba? Mosk, maksudmu, ayah dan ibumu juga lumba-lumba?"
  },
  AvgDialog_128698_Content_3 = {
    Text = "Kapal curi?"
  },
  AvgDialog_128698_Content_30 = {
    Text = "Benar, Mosk kecil, hilang. Lumba-lumba, Hei Mosk kecil, Mosk, sudah dewasa"
  },
  AvgDialog_128698_Content_31 = {
    Text = "Mosk, Hei, Bola arang kecil, Bola arang kecil, sudah dewasa!"
  },
  AvgDialog_128698_Content_32 = {
    Text = "Mosk tertawa terbahak-bahak, menghindari percikan air yang kamu semburkan padanya karena marah, lalu kalian berdua mengulurkan tangan ke arah Nautila."
  },
  AvgDialog_128698_Content_33 = {
    Text = "Percayalah padaku, teman."
  },
  AvgDialog_128698_Content_34 = {Text = "Ya!"},
  AvgDialog_128698_Content_35 = {
    Text = "Nautila erat menggenggam tangan kalian dengan erat, satu di depan dan satu di belakang, kamu dan Mosk membawa Nautila menuju sebuah gua."
  },
  AvgDialog_128698_Content_36 = {
    Text = "Setelah kegelapan sesaat, satu kelompok, dua kelompok... tak terhitung kelompok cahaya samar yang memesona terbangun, ubur-ubur bergerak menuju permukaan air, lalu didorong lembut oleh Pusaran, hingga cahaya yang lebih terang turun dari kubah langit."
  },
  AvgDialog_128698_Content_37 = {
    Text = "...Aku, ini bukan Mimpi kan."
  },
  AvgDialog_128698_Content_38 = {
    Text = "Sinar matahari menembus lapisan batu, memantulkan biru yang dalam dan dangkal di permukaan laut yang tak berujung, terumbu karang yang berwarna-warni kembali memotong biru tersebut, bersama dengan berbagai makhluk laut lainnya, menyajikan pemandangan yang cukup membuat orang terdiam."
  },
  AvgDialog_128698_Content_39 = {
    Text = "Anemon laut yang berbisa menari dengan tentakel berserabut di dalam air, moluska hidup bersamanya, pemangsa menunggu kesempatan di dalam jurang. Ini adalah gambaran dari lautan yang berbahaya, indah, gelap, dan megah."
  },
  AvgDialog_128698_Content_4 = {
    Text = "Roda kemudi, seperti setir, adalah sesuatu yang mengendalikan arah, apakah kamu tahu apa itu setir?"
  },
  AvgDialog_128698_Content_40 = {Text = "Nautila?"},
  AvgDialog_128698_Content_41 = {
    Text = "Ini, bagus, untukmu."
  },
  AvgDialog_128698_Content_42 = {
    Text = "Mosk entah kapan, mengeluarkan sebuah mutiara yang memancarkan kilau lembut, dengan ekspresi yang sangat, sangat serius, meletakkannya di telapak tangan Nautila."
  },
  AvgDialog_128698_Content_43 = {
    Text = "Mosk, di sini, suka. Mosk, harta, suka. Nautila, teman, untukmu."
  },
  AvgDialog_128698_Content_44 = {
    Text = "(Aku sudah meminta begitu banyak kali sebelumnya, tapi kamu tidak memberikannya, si raksasa, jahat!)"
  },
  AvgDialog_128698_Content_45 = {
    Text = "Meskipun dalam hati kamu bergumam seperti itu, tetapi ketika memikirkan ikan bakar dan seafood rebus yang lezat yang telah kamu makan selama ini, kamu dengan murah hati mendorong mutiara ke tangan Nautila bersama Mosk."
  },
  AvgDialog_128698_Content_46 = {
    Text = "Ah, terima kasih! Kalau begitu, saya juga akan memberikan hadiah untuk Mosk."
  },
  AvgDialog_128698_Content_47 = {Text = "Li Wu?"},
  AvgDialog_128698_Content_48 = {
    Text = "Nautila melepaskan gelang yang selalu dikenakannya di pergelangan tangan, yang dihiasi dengan hiasan kecil berbentuk Nautilus."
  },
  AvgDialog_128698_Content_49 = {
    Text = "Barang yang diberikan teman kepada teman disebut hadiah—— mutiara adalah hadiah yang diberikan Mosk kepada saya, ini adalah hadiah yang saya berikan kepada Mosk."
  },
  AvgDialog_128698_Content_5 = {Text = "Hmm...?"},
  AvgDialog_128698_Content_50 = {
    Text = "Ibu saya memberikan saya kalung dan gelang, dan saya berjanji padanya untuk menjadi seorang petualang yang hebat."
  },
  AvgDialog_128698_Content_51 = {
    Text = "Mosk, aku akan segera memperbaiki kapal dan pergi bersamamu dari sini untuk mencari ayah dan ibumu."
  },
  AvgDialog_128698_Content_52 = {
    Text = "Setelah itu, maukah kamu mengenakan gelang ini, membawa Bola arang kecil, dan berpetualang bersamaku?"
  },
  AvgDialog_128698_Content_54 = {
    Text = "Nautila, Mosk, Bola arang kecil, Petualangan!"
  },
  AvgDialog_128698_Content_55 = {Text = "Yahuu!"},
  AvgDialog_128698_Content_56 = {
    Text = "Seolah-olah setelah keheningan singkat yang tampak seperti ilusi, Mosk kembali mengangkat senyuman cerahnya dan memelukmu sambil bersorak."
  },
  AvgDialog_128698_Content_57 = {
    Text = "Cii! (Petualangan!)"
  },
  AvgDialog_128698_Content_58 = {
    Text = "Apa yang bisa kamu perhatikan? Kamu hanyalah seekor berang-berang laut. Meskipun kamu dapat mencium sesuatu dengan tajam, otak yang tidak cukup besar tidak mendukungmu untuk melakukan lebih banyak. Kamu segera tenggelam dalam suasana yang ceria."
  },
  AvgDialog_128698_Content_59 = {
    Text = "Bagus sekali, Bola arang kecil, aku juga menyiapkan hadiah untukmu!"
  },
  AvgDialog_128698_Content_6 = {
    Text = "Roda kemudi adalah benda yang mengendalikan arah semua kendaraan besar. Ke mana roda kemudi mengarahkan jalan, di situlah kapal dan mobil akan pergi."
  },
  AvgDialog_128698_Content_61 = {Text = "!"},
  AvgDialog_128698_Content_62 = {
    Text = "Kabin yang awalnya bobrok kini telah sepenuhnya berubah, di antara dua tempat tidur yang sama, sederhana namun bersih dan kokoh, terdapat sebuah peti kayu yang dipenuhi dengan bantal empuk."
  },
  AvgDialog_128698_Content_63 = {
    Text = "Hehe, sekarang setiap orang sudah memiliki satu tempat tidur."
  },
  AvgDialog_128698_Content_64 = {
    Text = "Begitu Nautila selesai berbicara, seluruh tubuh mu terjatuh ke dalam sarang kecilmu yang sempurna, Nautila bahkan menyisakan satu tempat untuk meletakkan kerang kecil kesayanganmu"
  },
  AvgDialog_128698_Content_65 = {
    Text = "Sup seafood malam masih hangat tertinggal di perutmu, di antara napas yang tenang dari gadis-gadis, kamu segera tertidur."
  },
  AvgDialog_128698_Content_66 = {
    Text = "Namun ketika malam benar-benar tiba, bayangan yang tidak menguntungkan itu menyebar seperti kabut malam yang lengket di permukaan laut."
  },
  AvgDialog_128698_Content_67 = {
    Text = "<Shake:Mosk, @3……>"
  },
  AvgDialog_128698_Content_68 = {
    Text = "<Shake: Kembalilah padaku, patuh padaku, @4……@4！>"
  },
  AvgDialog_128698_Content_69 = {
    Text = "Lautan dalam kegelapan, menjadi horor dan misterius, sinar matahari tidak lagi menerangi permukaan air, di kedalaman yang lebih dalam, suatu keberadaan sedang mengeluarkan gumaman yang dalam."
  },
  AvgDialog_128698_Content_7 = {
    Text = "Oh——mengerti! Setir, hebat"
  },
  AvgDialog_128698_Content_70 = {
    Text = "Kamu terombang-ambing dalam kekosongan dan kedinginan yang tak berujung, berusaha sekuat tenaga untuk mendekati sosok yang sedang menangis pelan di kejauhan."
  },
  AvgDialog_128698_Content_71 = {
    Text = "Ah——(Besar——)"
  },
  AvgDialog_128698_Content_72 = {
    Text = "Ah!(Besar!)"
  },
  AvgDialog_128698_Content_73 = {
    Text = "Kamu terbangun dengan kaget, tidak ada suara napas lembut dari para gadis yang tertidur, semuanya sunyi senyap. Kamu keluar dari sarangmu, mengikuti aroma Mosk menuju dek."
  },
  AvgDialog_128698_Content_74 = {
    Text = "Dia sedang melihat pusaran di kejauhan."
  },
  AvgDialog_128698_Content_75 = {
    Text = "(Ini mimpi itu lagi, sudah berapa kali sejak orang-orang manusia yang menyebalkan itu mati dan kita menetap di sini?)"
  },
  AvgDialog_128698_Content_76 = {
    Text = "Panggilan, Mosk, di sana."
  },
  AvgDialog_128698_Content_77 = {
    Text = "Menakutkan... jangan..."
  },
  AvgDialog_128698_Content_78 = {
    Text = "Eh, Bola arang kecil, Mosk, kalian kenapa di luar?"
  },
  AvgDialog_128698_Content_79 = {
    Text = "Suara Nautila memotong bisikan mimpi Mosk, dan dalam sekejap, Nautila dengan bersemangat mendorong sekumpulan besi untuk menunjukkan kepada kalian."
  },
  AvgDialog_128698_Content_80 = {
    Text = "Mosk, bukankah kamu sebelumnya bilang bahwa menyelam ke tempat yang terlalu dalam akan membuat tidak nyaman, tapi tetap ingin pergi melihatnya?"
  },
  AvgDialog_128698_Content_81 = {
    Text = "Saya telah memperbaiki pakaian selam yang ditemukan di kapal. Asalkan ada ini, waktu menyelammu bisa lebih lama, dan tidak akan merasa tidak nyaman lagi."
  },
  AvgDialog_128698_Content_82 = {
    Text = "Sayangnya, aku harus memperbaiki kapal sebelum badai berikutnya, setelah badai, aku juga akan membuat satu set untuk diriku sendiri."
  },
  AvgDialog_128698_Content_83 = {
    Text = "Di masa depan, kita bisa berpetualang bersama di laut"
  },
  AvgDialog_128698_Content_84 = {
    Text = "Mosk jarang sekali tenang, setelah sejenak, dia mengangguk dengan kuat, memelukmu, dan memberikan Nautila pelukan besar."
  },
  AvgDialog_128698_Content_85 = {Text = "Keluar."},
  AvgDialog_128698_Content_86 = {
    Text = "Mosk, Nautila, Bola arang kecil, Keluar! Bersama!"
  },
  AvgDialog_128698_Content_9 = {
    Text = "Berdasarkan data instrumen, paling lambat dalam seminggu, akan ada badai besar yang berlangsung setidaknya selama dua minggu. Kondisi kapal ini sendiri sudah tidak begitu baik... setelah badai, tidak tahu apakah bisa beroperasi lagi."
  },
  AvgDialog_128699_Content_1 = {
    Text = "Pletak, pletak."
  },
  AvgDialog_128699_Content_10 = {
    Text = "Mosk, dengarkan aku, aku yang mengusulkan untuk berlayar, dan aku juga yang tidak menghitung cuaca dengan baik, jadi aku memiliki kewajiban untuk menyelamatkanmu dan bola arang kecil."
  },
  AvgDialog_128699_Content_11 = {
    Text = "Aku akan segera melepas baju selam dan memberikannya padamu. Sekarang kapal masih bisa bergerak, aku akan berusaha mengendalikannya untuk berlayar menuju tepi Vortex. Nanti, kamu..."
  },
  AvgDialog_128699_Content_12 = {Text = "Kau……"},
  AvgDialog_128699_Content_13 = {
    Text = "Nautila tertegun di tempatnya, dia melihat gadis yang sebelumnya ceria, aktif, dan tanpa beban itu jarang menunjukkan ekspresi khawatir yang rumit."
  },
  AvgDialog_128699_Content_14 = {
    Text = "Nautila, Maaf."
  },
  AvgDialog_128699_Content_15 = {
    Text = "Mosk mengulurkan tangannya, meskipun dia tidak mengerti bagaimana alat ini seharusnya berfungsi, tetapi dengan naluri seperti binatang buas, dia memaksa untuk membantu Nautila mengenakan pakaian selam."
  },
  AvgDialog_128699_Content_16 = {
    Text = "Mosk, bahaya, firasat."
  },
  AvgDialog_128699_Content_17 = {
    Text = "Namun, harapan, tidak akan terjadi."
  },
  AvgDialog_128699_Content_18 = {
    Text = "Air hujan masuk melalui lubang di atap, menghantam kedua orang itu."
  },
  AvgDialog_128699_Content_19 = {
    Text = "Keheningan menyelimuti ruangan, akhirnya, Mosk yang memecahkan keheningan yang berat ini."
  },
  AvgDialog_128699_Content_2 = {
    Text = "<Shake:Ciiit——ya——>"
  },
  AvgDialog_128699_Content_20 = {
    Text = "Mosk, datang ke sini, bermimpi."
  },
  AvgDialog_128699_Content_21 = {
    Text = "Mosk bermimpi... ada sesuatu, bernama Mosk..."
  },
  AvgDialog_128699_Content_22 = {
    Text = "Namun, tidak ingin pergi. Dingin, tidak ada orang, kesepian…"
  },
  AvgDialog_128699_Content_23 = {
    Text = "Nautila tiba-tiba menyadari mengapa hujan lebat turun lebih awal, mengapa angin puting beliung tiba-tiba muncul, dia mulai bergetar tanpa henti."
  },
  AvgDialog_128699_Content_24 = {
    Text = "Benda itu... ada di sana..."
  },
  AvgDialog_128699_Content_25 = {
    Text = "Mengikuti jari-jari Mosk, Nautila merasakan sebuah ketakutan yang menyebar di dalam alam bawah sadarnya."
  },
  AvgDialog_128699_Content_26 = {
    Text = "Dari dasar Vortex Merscus, ketakutan yang melampaui hal-hal manusiawi."
  },
  AvgDialog_128699_Content_28 = {
    Text = "Tidak, tidak bisa! Saya tahu apa yang ingin kamu lakukan, tidak bisa!"
  },
  AvgDialog_128699_Content_29 = {
    Text = "Percayalah padaku, pasti ada cara lain"
  },
  AvgDialog_128699_Content_3 = {
    Text = "Arus putaran yang ganas seperti sepasang tangan raksasa, berusaha memutar kapal seperti memeras handuk."
  },
  AvgDialog_128699_Content_30 = {
    Text = "Nautila dengan cemas menekan Mosk, meskipun dengan kekuatannya, Mosk bisa kapan saja melepaskan diri dari pembatasan, tetapi gadis seperti binatang buas itu tidak melakukannya."
  },
  AvgDialog_128699_Content_31 = {
    Text = "Dia hanya mengangkatmu, lalu menggesekkan tubuhnya dengan manja."
  },
  AvgDialog_128699_Content_32 = {
    Text = "Teman, hebat, tetapi, tidak bisa. Hanya, Mosk, yang bisa."
  },
  AvgDialog_128699_Content_33 = {
    Text = "Hanya, Mosk, bisa."
  },
  AvgDialog_128699_Content_34 = {
    Text = "...Kenapa, kenapa bisa seperti ini."
  },
  AvgDialog_128699_Content_35 = {
    Text = "Sahabat, jangan menangis, tersenyumlah, Mosk, suka!"
  },
  AvgDialog_128699_Content_36 = {
    Text = "Eh, maaf, aku lihat kalian sepertinya makan ikan mentah, jadi aku memasaknya sedikit... meski tidak ada bumbu, mau Cicipi?"
  },
  AvgDialog_128699_Content_37 = {Text = "Ah Uhu!"},
  AvgDialog_128699_Content_38 = {Text = "Ah Uhu!"},
  AvgDialog_128699_Content_39 = {Text = "Enak"},
  AvgDialog_128699_Content_4 = {
    Text = "Badan kapal mengeluarkan suara berputar yang tak tertahankan, Mosk hampir berteriak di tengah badai, sambil berusaha keras memasukkan Nautila ke dalam baju selam, dia juga memelukmu erat-erat yang hampir terlempar."
  },
  AvgDialog_128699_Content_40 = {
    Text = "Petualangan, sangat menantikannya!"
  },
  AvgDialog_128699_Content_41 = {
    Text = "Mosk, aku akan segera memperbaiki kapal dan membawamu pergi dari sini untuk mencari ayah dan ibumu."
  },
  AvgDialog_128699_Content_42 = {
    Text = "Setelah itu, maukah kamu membawa gelang ini, membawa bola arang kecil, dan pergi berpetualang bersamaku?"
  },
  AvgDialog_128699_Content_43 = {
    Text = "Nautila, Mosk, Bola arang kecil, Petualangan!"
  },
  AvgDialog_128699_Content_44 = {
    Text = "Teman, suka!"
  },
  AvgDialog_128699_Content_45 = {
    Text = "Teman, beri Mosk, sangat banyak!"
  },
  AvgDialog_128699_Content_46 = {
    Text = "Jadi, sekarang, Mosk akan memberikan banyak sekali kepada teman-teman!"
  },
  AvgDialog_128699_Content_47 = {
    Text = "Dia seolah-olah membangun dirinya menjadi dinding di tengah badai, dengan kokoh menempatkanmu dan Nautila di tengah, lalu menarik napas dalam-dalam, tersenyum lebar, memperlihatkan senyuman khas Mosk yang menenangkan."
  },
  AvgDialog_128699_Content_48 = {
    Text = "Mosk, pasti akan kembali!"
  },
  AvgDialog_128699_Content_49 = {
    Text = "……Baiklah, aku percaya pada Mosk. Setelah kamu kembali, aku akan menyiapkan kapal terbaik di dunia, lalu membawamu dan Bola arang kecil untuk petualangan yang paling luar biasa."
  },
  AvgDialog_128699_Content_5 = {
    Text = "Bahaya! Tangkap"
  },
  AvgDialog_128699_Content_50 = {
    Text = "Nautila mengusap air mata, berusaha menguatkan semangat, dan menunjukkan senyuman yang terlihat agak jelek."
  },
  AvgDialog_128699_Content_51 = {
    Text = "Melihat Nautila tidak lagi melawan, Mosk dengan diam-diam, perlahan-lahan menarik cakarmu, menempelkan wajahnya di bantalan dagingmu."
  },
  AvgDialog_128699_Content_52 = {
    Text = "Jangan, takut."
  },
  AvgDialog_128699_Content_53 = {
    Text = "Ah... ah! (Kau akan meninggalkanku...)"
  },
  AvgDialog_128699_Content_54 = {
    Text = "Ah!! Ah——(Kamu akan meninggalkanku!!)"
  },
  AvgDialog_128699_Content_55 = {
    Text = "Kamu dimasukkan ke dalam pelukan Nautila di tengah jeritan yang memilukan. Di saat berikutnya, Mosk tanpa ragu berbalik dan berlari ke arah Vortex saat kapal miring sekali lagi."
  },
  AvgDialog_128699_Content_56 = {Text = "... Plung."},
  AvgDialog_128699_Content_57 = {
    Text = "Seperti seekor ikan yang masuk ke dalam lautan miliknya."
  },
  AvgDialog_128699_Content_58 = {Text = "Mosk!!"},
  AvgDialog_128699_Content_59 = {
    Text = "Badai menutupi semua teriakan, gelombang besar menerjang dek dan menyeret kalian ke dalam laut."
  },
  AvgDialog_128699_Content_6 = {Text = "Boom——"},
  AvgDialog_128699_Content_60 = {
    Text = "Di bawah air laut berwarna hitam biru, ribuan cairan hitam seperti benang terbentang ke arah Mosk, kedua tangannya berubah menjadi pusaran besar, wajahnya tampak damai dan tenang, di kedalaman matanya yang tenang, seolah-olah berada di pusat pusaran."
  },
  AvgDialog_128699_Content_61 = {
    Text = "Mosk, Pusaran. Mosk, setir."
  },
  AvgDialog_128699_Content_62 = {
    Text = "Bola arang kecil, Nautila, di sini, selamanya."
  },
  AvgDialog_128699_Content_63 = {
    Text = "Mosk akhirnya tidak bisa menahan diri dan menangis tersedu-sedu, sambil menunjuk ke arah jantungnya."
  },
  AvgDialog_128699_Content_64 = {
    Text = "Dia mengangkat tangannya, dengan kekuatan penghancuran yang liar seperti dirinya, namun dengan pusaran yang sangat lembut, mendorong kalian jauh ke arah yang menjauh dari vortex."
  },
  AvgDialog_128699_Content_65 = {
    Text = "Satu demi satu, lendir menempel pada tubuh Mosk, sekejap saja telah merayap memenuhi seluruh tubuhnya."
  },
  AvgDialog_128699_Content_66 = {
    Text = "Vortex mulai berbalik dan menyusut ke pusat, membungkus apa yang diinginkannya, gadis itu seperti terjerat dan ditarik oleh banyak rumput laut hitam, secara bertahap tenggelam ke dasar laut yang gelap."
  },
  AvgDialog_128699_Content_68 = {
    Text = "Segalanya telah tenang, langit biru cerah, di permukaan laut yang damai, kapal-kapal mengapung dengan tenang."
  },
  AvgDialog_128699_Content_69 = {
    Text = "Eh, ini di mana, mengapa saya di atas air? Huh, sangat pengap!"
  },
  AvgDialog_128699_Content_7 = {
    Text = "Getaran hebat melempar Nautila keluar, menghantam barel kayu yang jatuh ke tanah."
  },
  AvgDialog_128699_Content_70 = {
    Text = "Kamu melihat dengan aneh orang yang mengenakan pakaian aneh, mengapung di atas air."
  },
  AvgDialog_128699_Content_71 = {
    Text = "(Apa aku bisa sampai di sini, siapa itu?)"
  },
  AvgDialog_128699_Content_72 = {
    Text = "Pletak. Pletak."
  },
  AvgDialog_128699_Content_73 = {
    Text = "Pletak. Pletak."
  },
  AvgDialog_128699_Content_74 = {
    Text = "(Oh ya, saya adalah seekor berang-berang laut! Berang-berang laut harus mencari kerang. Kerang, kerang!)"
  },
  AvgDialog_128699_Content_75 = {
    Text = "Kau dengan bahagia menyelam ke dalam air yang hangat, menjauh dari manusia yang berjuang berenang menuju kapal."
  },
  AvgDialog_128699_Content_76 = {
    Text = "Kamu tidak menyadari bahwa air mata kamu sudah larut ke dalam laut."
  },
  AvgDialog_128699_Content_8 = {Text = "Ngh..."},
  AvgDialog_128699_Content_9 = {
    Text = "Nautila menahan rasa sakit, bangkit dengan goyah, dan berlari menuju sisi Mosk."
  },
  AvgDialog_128700_Content_1 = {
    Text = "Guruh——guruh——"
  },
  AvgDialog_128700_Content_10 = {
    Text = "Kamu adalah seekor berang-berang laut berusia satu setengah tahun, sedang mencari makanan di luar bersama teman besar favoritmu."
  },
  AvgDialog_128700_Content_100 = {
    Text = "Air liur mengalir tanpa kendali karena godaan makanan, kamu dan Mosk hampir serentak melompat, dan sama-sama menggigit ikan bakar."
  },
  AvgDialog_128700_Content_101 = {
    Text = "Enak——!"
  },
  AvgDialog_128700_Content_102 = {
    Text = "Hei, ah... Nautila, tangannya?"
  },
  AvgDialog_128700_Content_103 = {
    Text = "Hanya dislokasi, saya sudah menyambungkannya sendiri, bagi seorang petualang, tidak ada yang perlu dikhawatirkan, terima kasih atas obatnya!"
  },
  AvgDialog_128700_Content_104 = {
    Text = "<Small:(Meskipun rasanya pahit dan efeknya cukup kuat, tetapi hasilnya memang sangat baik.)>"
  },
  AvgDialog_128700_Content_105 = {
    Text = "Yahuu! Senang, peluk……"
  },
  AvgDialog_128700_Content_106 = {
    Text = "Hehe, Mosk, hati-hati."
  },
  AvgDialog_128700_Content_107 = {
    Text = "Eh? Eh! Jangan khawatir, Mosk, lain kali aku akan berteriak sakit untuk mengingatkanmu."
  },
  AvgDialog_128700_Content_108 = {Text = "Cii!"},
  AvgDialog_128700_Content_11 = {
    Text = "(Kombu, rumput laut, batu kecil…)"
  },
  AvgDialog_128700_Content_12 = {
    Text = "(Stone, bibi Stone, kakek Stone…?)"
  },
  AvgDialog_128700_Content_13 = {
    Text = "(Stone! Suruh seluruh keluargamu untuk tidak berkeliaran di sekitar sini lagi!!)"
  },
  AvgDialog_128700_Content_14 = {
    Text = "<Shake:Gedebum——>"
  },
  AvgDialog_128700_Content_15 = {Text = "(Buruk…)"},
  AvgDialog_128700_Content_16 = {
    Text = "Permukaan laut berputar membentuk pusaran besar, sebuah sosok yang familiar mengangkat sesuatu dan dengan cepat meluncur ke arahmu"
  },
  AvgDialog_128700_Content_17 = {
    Text = "Bola arang kecil! Daging! Mosk, dapatkan"
  },
  AvgDialog_128700_Content_18 = {
    Text = "Senang, pulang, bersama"
  },
  AvgDialog_128700_Content_19 = {
    Text = "Sebelum kamu sempat protes, gadis itu kembali mengangkatmu ke punggungnya dan berenang ke permukaan laut seperti ikan."
  },
  AvgDialog_128700_Content_2 = {
    Text = "<Shake:Guruh guruh……>"
  },
  AvgDialog_128700_Content_21 = {
    Text = "DOR——! Setelah kilat, suara guntur yang besar menggema, awan hujan yang berat selama ini melepaskan kelembapan ke dalam laut."
  },
  AvgDialog_128700_Content_22 = {
    Text = "Kamu dan Mosk kembali ke kabin yang aman, saling memandang."
  },
  AvgDialog_128700_Content_23 = {
    Text = "A? Ah, ah! (Ini daging? Besar, ini mirip dengan wajahmu!)"
  },
  AvgDialog_128700_Content_24 = {Text = "Sama?"},
  AvgDialog_128700_Content_25 = {
    Text = "Mosk memiringkan kepalanya, menunjukkan ekspresi kebingungan khasnya, lalu menunduk dengan serius untuk melihat \"daging\" yang telah dia letakkan di tanah."
  },
  AvgDialog_128700_Content_26 = {
    Text = "Puh——Ugh."
  },
  AvgDialog_128700_Content_27 = {
    Text = "Apa yang baru saja terjadi, kepalaku sepertinya terus berada di dalam air, ini di mana? Apakah aku sudah mati?"
  },
  AvgDialog_128700_Content_28 = {
    Text = "Orang asing itu batuk beberapa kali, meludah keluar segumpal besar air laut."
  },
  AvgDialog_128700_Content_29 = {
    Text = "Teman? Teman! Sama dengan Mosk"
  },
  AvgDialog_128700_Content_3 = {
    Text = "<Shake:Guruh guruh guruh——>"
  },
  AvgDialog_128700_Content_30 = {Text = "Eh... Eh?"},
  AvgDialog_128700_Content_31 = {
    Text = "<LightGray:Apakah ini populasi asli di sekitar sini? Aneh... di mana tempat ini?>"
  },
  AvgDialog_128700_Content_32 = {
    Text = "Kamu menemukan bahwa meskipun lawan sangat waspada, tampaknya tidak memiliki niat jahat. Jadi, kamu mendekat sedikit dengan hati-hati, bersiap untuk mengamati orang baru ini."
  },
  AvgDialog_128700_Content_33 = {
    Text = "Ini seharusnya adalah kabin sebuah kapal, meskipun terlihat agak tua, tetapi secara keseluruhan masih utuh…"
  },
  AvgDialog_128700_Content_34 = {
    Text = "Tunggu, paku keling kapal dari perusahaan Nosterdri?! Rangkaian pengukur level air, katup geser utama tipe cincin..."
  },
  AvgDialog_128700_Content_35 = {
    Text = "Saya akan melihat, kalau begitu……"
  },
  AvgDialog_128700_Content_36 = {
    Text = "Orang asing dengan bersemangat memeriksa kabin yang penuh sesak dengan barang-barang, sementara Mosk di sampingnya mengedipkan mata dengan bahagia dan penasaran."
  },
  AvgDialog_128700_Content_37 = {
    Text = "Bercahaya, bagus, Mosk, membawa. Teman, suka?"
  },
  AvgDialog_128700_Content_38 = {
    Text = "Mosk, asalkan ada barang-barang ini, saya bisa membuat kapal ini bergerak lagi, bisakah kamu memberikannya kepada saya?"
  },
  AvgDialog_128700_Content_39 = {
    Text = "Setelah kembali ke Aglo, aku pasti akan mengembalikan lebih banyak dan lebih indah bercahaya untukmu."
  },
  AvgDialog_128700_Content_4 = {
    Text = "Kamu berbaring telentang di dalam air laut yang hangat, dengan nyaman meregangkan anggota tubuhmu yang pendek, dan berputar dengan sempurna."
  },
  AvgDialog_128700_Content_40 = {
    Text = "Ah——！(Tidak bisa! Di dalam masih ada bola kecilku yang cantik!)"
  },
  AvgDialog_128700_Content_41 = {
    Text = "Kamu berteriak dengan marah, ingin merebut bola kecilmu kembali, tetapi pandanganmu segera tertarik oleh Mosk."
  },
  AvgDialog_128700_Content_42 = {
    Text = "Ssshh, Mosk, untukmu, kerang."
  },
  AvgDialog_128700_Content_43 = {
    Text = "Mosk dengan diam-diam memberikanmu dua cangkang yang sudah lama kamu incar, lalu mendorong komponen-komponen itu ke arah orang asing, memberi isyarat bahwa orang tersebut bisa memberikannya kepadanya."
  },
  AvgDialog_128700_Content_44 = {
    Text = "Teman, suka, berikan"
  },
  AvgDialog_128700_Content_45 = {
    Text = "Kamu tidak mengerti bagaimana benda-benda ini bisa membuat orang asing begitu bersemangat, lalu dengan wajah penuh kebahagiaan, menguburkan hidung kecilnya ke dalam dua cangkang indah yang sebelumnya Mosk sama sekali tidak mau biarkan kamu sentuh."
  },
  AvgDialog_128700_Content_46 = {
    Text = "Sangat bagus! Terima kasih… teman."
  },
  AvgDialog_128700_Content_47 = {
    Text = "Terpengaruh oleh semangat dan keramahan Mosk, orang asing itu akhirnya merasa lebih relaks dan memberikan senyuman kepada kalian."
  },
  AvgDialog_128700_Content_48 = {
    Text = "Ngomong-ngomong, nama saya Nautila."
  },
  AvgDialog_128700_Content_49 = {
    Text = "Bagus! Nautila, Mosk, teman, senang"
  },
  AvgDialog_128700_Content_5 = {
    Text = "(Sejenak, anggota tubuh yang pendek?)"
  },
  AvgDialog_128700_Content_50 = {
    Text = "Mosk bersorak, mengulurkan kedua tangan, ingin memberikan pelukan besar kepada teman baru yang baru dikenalnya."
  },
  AvgDialog_128700_Content_51 = {
    Text = "Ah! (Celaka... si besar...)"
  },
  AvgDialog_128700_Content_52 = {
    Text = "Teman, peluk!"
  },
  AvgDialog_128700_Content_53 = {
    Text = "Tunggu, Mosk... Ugh! Sakit sekali!"
  },
  AvgDialog_128700_Content_54 = {
    Text = "Arus udara di dalam udara tiba-tiba berkumpul, di tengah tekanan angin yang tiba-tiba meningkat, terdengar suara glek yang nyaring."
  },
  AvgDialog_128700_Content_55 = {Text = "Ah!"},
  AvgDialog_128700_Content_56 = {
    Text = "Mosk tiba-tiba sadar, segera melepaskan Nautila, tetapi Nautila sudah menahan rasa sakit dengan wajah yang terdistorsi, dan lengan terlihat terpelintir pada sudut yang tidak wajar."
  },
  AvgDialog_128700_Content_57 = {
    Text = "Maaf, maafkan saya..."
  },
  AvgDialog_128700_Content_58 = {
    Text = "Kamu melihat Mosk yang kebingungan, berusaha keras menggigit celananya, menarik ke satu arah."
  },
  AvgDialog_128700_Content_59 = {
    Text = "Ah, ah!(<Big:Ini dia!>)"
  },
  AvgDialog_128700_Content_6 = {
    Text = "<Shake:Ptak ptak.>"
  },
  AvgDialog_128700_Content_60 = {
    Text = "Oh oh, benar, ini! Nautila, minum"
  },
  AvgDialog_128700_Content_61 = {
    Text = "Jangan sentuh aku!"
  },
  AvgDialog_128700_Content_62 = {
    Text = "Nautila secara naluri mengibaskan tangan Mosk, seluruh tubuhnya bersandar ke belakang."
  },
  AvgDialog_128700_Content_63 = {
    Text = "[@3 campuran]"
  },
  AvgDialog_128700_Content_64 = {
    Text = "Gulu gulu——botol obat jatuh ke tanah, menggulung hingga di sisi kaki Mosk."
  },
  AvgDialog_128700_Content_65 = {
    Text = "Gadis yang barusan berbangga diri, dengan tajam menangkap ketakutan lawannya, perlahan-lahan menurunkan tangannya."
  },
  AvgDialog_128700_Content_67 = {
    Text = "Maaf, tapi... apakah ada tempat lain di kapal ini, aku mungkin perlu istirahat sendiri sebentar."
  },
  AvgDialog_128700_Content_68 = {
    Text = "Mosk terdiam sejenak, lalu menyeret selimut terbesar dan terlembut di kapal, dan menyebarkannya jauh di atas tanah."
  },
  AvgDialog_128700_Content_69 = {
    Text = "Mosk, Ceroboh, Kekuatan Besar, Melukai."
  },
  AvgDialog_128700_Content_7 = {
    Text = "Pletak pletak~"
  },
  AvgDialog_128700_Content_70 = {
    Text = "Mosk, buruk, maaf. Rumah, hangat, Nautila."
  },
  AvgDialog_128700_Content_71 = {
    Text = "Tubuhmu tiba-tiba melayang, Mosk dengan hati-hati dan sedikit ragu menyerahkanmu kepada Nautila seolah-olah memberikan harta."
  },
  AvgDialog_128700_Content_72 = {
    Text = "Di luar, Mosk. Bola arang kecil, hangat, Nautila, di sini."
  },
  AvgDialog_128700_Content_73 = {
    Text = "Dia mengangkat dagunya, menunjuk ke luar, lalu menunjuk ke selimut, berdiri dengan keras kepala di antara Nautila dan pintu."
  },
  AvgDialog_128700_Content_74 = {
    Text = "...Baiklah, terima kasih."
  },
  AvgDialog_128700_Content_75 = {
    Text = "Apa, apa? (Hei, hei, orang besar?)"
  },
  AvgDialog_128700_Content_77 = {
    Text = "Hujan tidak berhenti semalam, tengah malam, Nautila berjalan ke pintu kabin, memandang gadis yang sedang tidur di dek."
  },
  AvgDialog_128700_Content_78 = {
    Text = "Dia meringkuk menjadi satu bola, bersembunyi dari angin dan hujan di sudut kapal."
  },
  AvgDialog_128700_Content_79 = {
    Text = "……Di tempat seperti ini bisa tidur begitu nyenyak, memang seperti hewan kecil…"
  },
  AvgDialog_128700_Content_8 = {
    Text = "(Ya, aku adalah seekor berang-berang laut!)"
  },
  AvgDialog_128700_Content_80 = {
    Text = "Maaf, aku tidak seharusnya bersikap begitu kasar padamu, Mosk."
  },
  AvgDialog_128700_Content_81 = {
    Text = "Mosk mengenakan selimut tambahan, dia menggerakkan bibirnya dalam tidurnya, terbenam dalam mimpi yang lebih manis dan gelap."
  },
  AvgDialog_128700_Content_82 = {Text = "Cii!"},
  AvgDialog_128700_Content_83 = {
    Text = "Keesokan paginya, setelah hujan adalah waktu yang tepat untuk memancing. \n Kamu dengan bangga menggigit ikan terbesar hari ini dan melemparkannya ke arah Mosk, tetapi……"
  },
  AvgDialog_128700_Content_84 = {Text = "Plak!"},
  AvgDialog_128700_Content_86 = {
    Text = "Mosk langsung menangkap ikan dengan wajahnya, dan sedikit retakan muncul dari kebodohan yang dimulai sejak pagi. Dia menatapmu, sudut bibirnya melengkung ke bawah, lalu, tetesan air mata besar mulai jatuh."
  },
  AvgDialog_128700_Content_87 = {
    Text = "Uuh... aaaaaa..."
  },
  AvgDialog_128700_Content_88 = {
    Text = "Segera setelah itu, dia tidak peduli dan menekan wajahnya sepenuhnya ke dalam perutmu, mulai menangis terisak-isak."
  },
  AvgDialog_128700_Content_89 = {
    Text = "Mosk, buruk!"
  },
  AvgDialog_128700_Content_9 = {
    Text = "Kepala kecilmu yang hanya sebesar sedikit, dengan gembira mengingat situasi saat ini."
  },
  AvgDialog_128700_Content_90 = {
    Text = "Ah! Ah!! Ah!(<Big:Hei! Hati-hati ingat ingusmu!>)"
  },
  AvgDialog_128700_Content_91 = {
    Text = "Hiks, bisa bicara, sama, teman, selamanya tidak... hiks hiks hiks..."
  },
  AvgDialog_128700_Content_92 = {
    Text = "Mosk menangis terisak-isak, kamu berusaha keras untuk membebaskan perutmu dari bawah wajahnya, namun akhirnya hanya bisa menghela napas, membiarkannya mengusap-usap ingusnya."
  },
  AvgDialog_128700_Content_93 = {
    Text = "(Ini ingin mengatakan akhirnya menemukan teman yang bisa bicara seperti dirinya, tetapi ternyata berantakan, tapi apakah orang besar itu bisa dihitung sebagai orang yang bisa bicara?)"
  },
  AvgDialog_128700_Content_94 = {
    Text = "(Eh, tunggu sebentar, baunya sangat harum!)"
  },
  AvgDialog_128700_Content_96 = {
    Text = "Di dalam kabin, Nautila menusukkan beberapa ikan laut dengan kawat tipis, api telah memanggang permukaan ikan laut hingga garing, lemak menetes ke lantai, mengeluarkan aroma yang cukup menggugah naluri hewani."
  },
  AvgDialog_128700_Content_97 = {
    Text = "Eh, maaf, aku lihat kalian sepertinya makan ikan mentah, jadi aku memasaknya sedikit... meski tidak ada bumbu, mau Cicipi?"
  },
  AvgDialog_128700_Content_98 = {Text = "Ah Uhu!"},
  AvgDialog_128700_Content_99 = {Text = "Ah Uhu!"},
  AvgDialog_130451_Content_1 = {
    Text = "Malam yang gelap gulita, kamu baru saja menyelesaikan sebuah misi lapangan, dan Awakener yang bersamamu dalam misi itu — ksatria kecil dari dunia lain, Sumpah Palsu·Ogier — berjalan dengan tenang di belakangmu."
  },
  AvgDialog_130451_Content_10 = {
    Text = "Tunggu, tolong jangan mendekat!"
  },
  AvgDialog_130451_Content_11 = {
    Text = "Belum habis kata-katanya, pandanganmu tiba-tiba menjadi gelap gulita."
  },
  AvgDialog_130451_Content_12 = {
    Text = "Sesuatu yang tak kasat mata yang selama ini hidup berdampingan dengan Sumpah Palsu·Ogier tiba-tiba mengerumuni dan menempel di anggota tubuhmu, menutupi kedua matamu, membelenggumu dengan erat, membuatmu merasakan sensasi dingin."
  },
  AvgDialog_130451_Content_13 = {Text = "Ogier!"},
  AvgDialog_130451_Content_14 = {
    Text = "Kamu berteriak memanggil, namun lumpur-lumpur itu malah melilit semakin erat, seolah ingin membelenggumu sepenuhnya di dalamnya. Kamu mengulurkan tangan untuk menariknya dengan keras, namun mereka membungkusmu kembali dengan keras kepala seperti sulur tanaman."
  },
  AvgDialog_130451_Content_15 = {Text = "Ngh..."},
  AvgDialog_130451_Content_16 = {
    Text = "Suara remaja itu yang samar dan lemah terdengar terputus-putus, jelas sedang berusaha keras menahan sesuatu."
  },
  AvgDialog_130451_Content_17 = {
    Text = "Ogier? Bisakah kamu mendengar aku berbicara?"
  },
  AvgDialog_130451_Content_18 = {
    Text = "Cengkeraman yang membelenggumu bergetar sejenak, lalu mengencang kembali, seolah-olah sedang tarik-menarik antara dua kehendak yang berbeda."
  },
  AvgDialog_130451_Content_19 = {
    Text = "Karena ketidakmampuanku, Anda tetap saja terluka. Seandainya, aku bisa melindungi Anda dengan cara yang lebih baik…"
  },
  AvgDialog_130451_Content_2 = {
    Text = "Misi kali ini tidak terlalu sulit, sebagai Penjaga yang cukup berpengalaman, kamu dan Sumpah Palsu·Ogier dengan mudah membereskan semua musuh. Namun, karena sedikit kecerobohanmu, tetap saja ada luka kecil yang tertinggal di pergelangan tanganmu."
  },
  AvgDialog_130451_Content_20 = {
    Text = "Kamu hanya bisa mendengar beberapa kata yang samar-samar, seperti seseorang yang berbicara pada diri sendiri."
  },
  AvgDialog_130451_Content_21 = {
    Text = "Meski lumpur-lumpur ini melilit dengan erat, kamu tidak merasakan sedikit pun rasa sakit atau sesak napas. Kamu tiba-tiba menyadari bahwa ini mungkin bukan untuk menyakitimu, melainkan lebih seperti ingin menyembunyikanmu di suatu tempat yang benar-benar aman, tempat yang tidak membiarkan apapun mendekat."
  },
  AvgDialog_130451_Content_22 = {
    Text = "Tidak apa-apa, aku baik-baik saja, kamu tidak perlu takut."
  },
  AvgDialog_130451_Content_23 = {
    Text = "Kata-katamu tampaknya berhasil. Kali ini, cengkeraman lumpur-lumpur itu akhirnya perlahan-lahan mengendur. Kamu memanfaatkan kesempatan itu untuk menarik dan melepaskan diri."
  },
  AvgDialog_130451_Content_24 = {
    Text = "Kamu melihat Ogier·Pemungkir Sumpah menundukkan kepalanya dengan lesu, mengerutkan dahi sedikit, matanya masih dipenuhi kebingungan, bagaikan patung pertobatan yang menanggung dosa yang sangat besar."
  },
  AvgDialog_130451_Content_25 = {Text = "Apa kabar?"},
  AvgDialog_130451_Content_26 = {
    Text = "Aku bahkan menggunakan kekuatan yang tak terkendali seperti itu terhadap Anda…"
  },
  AvgDialog_130451_Content_27 = {
    Text = "Tidak bisa, aku harus membuat diriku… sadar kembali."
  },
  AvgDialog_130451_Content_28 = {
    Text = "Ia memejamkan mata dan berbisik, mengubah segumpal lumpur hitam yang berputar di tangannya menjadi bentuk belati. Cahaya bulan jatuh di atas bilah yang memancarkan kilau dingin itu, dan yang dituju olehnya adalah lengannya sendiri yang lain."
  },
  AvgDialog_130451_Content_29 = {
    Text = "Namun, benda tajam itu tidak sempat jatuh, kamu segera berlari ke depan dan menghentikan gerakannya. Kamu baru menyadari bahwa sesuatu yang tak kasat mata yang tadi melilit erat tubuhmu, kini telah sepenuhnya menghilang."
  },
  AvgDialog_130451_Content_3 = {
    Text = "Suasana di sekitar sangat sunyi, kamu merasa sedikit linglung karena kelelahan, namun terkejut oleh suara yang tiba-tiba terdengar dari belakang."
  },
  AvgDialog_130451_Content_30 = {Text = "Tuanku…?"},
  AvgDialog_130451_Content_31 = {
    Text = "Kamu setengah berjongkok, memeluknya dengan lembut, dan menepuk punggungnya dengan menenangkan."
  },
  AvgDialog_130451_Content_32 = {
    Text = "Ia tidak menghindar seperti biasanya, melainkan terdiam di tempat, mempertahankan posisi dipeluk olehmu."
  },
  AvgDialog_130451_Content_33 = {
    Text = "Jangan terlalu terburu-buru, santai saja, lihat, Dia sudah berhasil kamu tekan. Tapi, sebenarnya apa yang terjadi?"
  },
  AvgDialog_130451_Content_34 = {
    Text = "Maaf, Tuan. Entah mengapa, keberadaan yang menempel pada diriku hari ini sangat gelisah, pikiranku pun menjadi sangat kacau."
  },
  AvgDialog_130451_Content_35 = {
    Text = "Padahal Anda ada di sisiku, namun Dia bukannya mundur seperti biasanya, malah semakin aktif… itulah mengapa aku ingin menggunakan rasa sakit untuk menenangkan diri."
  },
  AvgDialog_130451_Content_36 = {
    Text = "Kamu memeluk Ogier dan bisa merasakan suhu tubuhnya yang tidak normal, dalam hati kamu sudah mendapat kesimpulan. Kamu tidak menyangka bahwa pengaruh Sungai Suci secara langsung mengganggu kekuatan lain yang ada pada diri Ogier."
  },
  AvgDialog_130451_Content_37 = {
    Text = "Ini bukan kesalahanmu, melainkan karena pengaruh dari sesuatu… hal lain."
  },
  AvgDialog_130451_Content_38 = {
    Text = "Dan meskipun lumpur hitam ini sempat menjebakku, tapi sama sekali tidak melukаiku… seharusnya karena kamu yang mengendalikan Dia, bukan? Sungguh luar biasa."
  },
  AvgDialog_130451_Content_39 = {
    Text = "Setelah keheningan singkat, akhirnya kamu mendengar suara pemuda itu yang terdengar tertahan."
  },
  AvgDialog_130451_Content_4 = {
    Text = "……Cukup! Bagaimana mungkin aku bisa terhadap Tuan—"
  },
  AvgDialog_130451_Content_40 = {
    Text = "…Terima kasih, Anda sudah menghiburku lagi."
  },
  AvgDialog_130451_Content_41 = {
    Text = "Sudah larut malam, izinkan aku terlebih dahulu mengobati lukamu, lalu mengantarmu kembali ke kamar."
  },
  AvgDialog_130451_Content_5 = {
    Text = "Kamu tahu bahwa selama ini Sumpah Palsu·Ogier terus berjuang melawan sesuatu yang tak kasat mata yang menempel padanya, namun reaksinya hari ini tampak berlebihan dan agak aneh."
  },
  AvgDialog_130451_Content_6 = {
    Text = "Maka, kamu berbalik dan berjalan menghampirinya."
  },
  AvgDialog_130451_Content_7 = {
    Text = "Ogier? Apakah kamu baik-baik saja? Apakah Dia sedang mencoba mengendalikanmu lagi?"
  },
  AvgDialog_130451_Content_8 = {Text = "!"},
  AvgDialog_130451_Content_9 = {
    Text = "Sumpah Palsu·Ogier tiba-tiba mengangkat kepalanya yang sedari tadi menatap ujung sepatunya, lalu mundur selangkah dengan tubuh gemetar."
  },
  AvgDialog_130453_Content_1 = {
    Text = "Mengingat kekuatan khusus yang dimiliki Saya sejak awal, semua orang merasa tegang terhadap kemungkinan reaksinya saat terpengaruh oleh Sungai Suci."
  },
  AvgDialog_130453_Content_10 = {
    Text = "Segala sesuatu di masa lalu telah membentuk diriku yang sekarang, tapi masih banyak hal yang belum pernah kupelajari."
  },
  AvgDialog_130453_Content_11 = {
    Text = "\"Naluri adalah reproduksi\" ya. Hmm……begitu rupanya……"
  },
  AvgDialog_130453_Content_12 = {
    Text = "Sambil berkata demikian, dia menyodorkan sebuah bantal empuk kepadamu."
  },
  AvgDialog_130453_Content_13 = {
    Text = "Kamu menghela napas lega, lalu bersandar pada bantal empuk itu seperti Saya."
  },
  AvgDialog_130453_Content_14 = {
    Text = "Begitu rupanya, setelah mengalami semua itu, dibandingkan naluri, rasionalitaslah yang lebih dominan ya……"
  },
  AvgDialog_130453_Content_15 = {
    Text = "<Small:Meskipun telah menjadi Awakened, Saya tetap istimewa ya……>"
  },
  AvgDialog_130453_Content_16 = {
    Text = "Kalau tidak mengganggu, bolehkah tempat Saya ini menjadi tempat perlindunganku!"
  },
  AvgDialog_130453_Content_17 = {
    Text = "Dengan penuh rasa haru, kamu mengajukan permohonan kepada lawan bicaramu."
  },
  AvgDialog_130453_Content_18 = {
    Text = "Yang paling penting saat ini adalah, penjaga rahasia Misag yang malang akhirnya memiliki sebuah rumah aman yang bisa diandalkan."
  },
  AvgDialog_130453_Content_19 = {
    Text = "Eh? Meskipun kurang mengerti……"
  },
  AvgDialog_130453_Content_2 = {
    Text = "Tapi di luar dugaan, Saya hanya berdiri dengan tenang di samping jendela, kulit seputih salju yang nyaris transparan seolah memisahkannya ke dunia lain."
  },
  AvgDialog_130453_Content_20 = {
    Text = "Saya pura-pura mengerutkan alis dengan ekspresi kesulitan, dan baru tersenyum lagi setelah berhasil melihat ekspresi kecewamu."
  },
  AvgDialog_130453_Content_21 = {
    Text = "Tentu saja boleh, tapi, sebagai gantinya kamu harus menjawab satu pertanyaan ya."
  },
  AvgDialog_130453_Content_22 = {
    Text = "Siapa orang yang paling kamu pedulikan?"
  },
  AvgDialog_130453_Content_23 = {
    Text = "Seperti dua sahabat yang bisa membicarakan apa saja, kalian mengobrol dengan gembira."
  },
  AvgDialog_130453_Content_24 = {
    Text = "Orang yang selalu kukhawatirkan……"
  },
  AvgDialog_130453_Content_25 = {
    Text = "Sosok seseorang muncul dalam kesadaranmu. Kamu menutup mata dengan rileks, dan juga mendoakan masa depan Saya—semoga keberadaan ini dapat melampaui waktu yang panjang."
  },
  AvgDialog_130453_Content_26 = {
    Text = "Kekuatan Sungai Suci mengalir melewati kalian berdua dengan tenang, bagaikan ombak yang lembut."
  },
  AvgDialog_130453_Content_27 = {
    Text = "Segalanya sunyi bagai misteri."
  },
  AvgDialog_130453_Content_3 = {
    Text = "Halo, Penjaga Rahasia."
  },
  AvgDialog_130453_Content_4 = {
    Text = "Saya, apakah sekarang kamu merasa ada yang tidak nyaman, atau ada sesuatu yang aneh?"
  },
  AvgDialog_130453_Content_5 = {
    Text = "Seolah merasakan kekhawatiranmu, gadis itu berputar ringan."
  },
  AvgDialog_130453_Content_6 = {
    Text = "Tidak ada demam tinggi, tidak ada detak jantung yang terlalu cepat, tidak ada kegembiraan yang tak beralasan, tidak ada apa-apa."
  },
  AvgDialog_130453_Content_7 = {
    Text = "Tidak perlu khawatir, sepertinya tidak ada hal istimewa yang terjadi padaku."
  },
  AvgDialog_130453_Content_8 = {
    Text = "Naluri ras Nona Taisce adalah berkembang biak ya, apakah hal seperti itu juga akan terjadi padaku?"
  },
  AvgDialog_130453_Content_9 = {
    Text = "Dia duduk di posisi yang lebih dekat denganmu, menyandarkan dirinya ke bantal empuk yang nyaman, tersenyum seperti hewan kecil yang tidak berbahaya."
  },
  AvgDialog_130454_Content_1 = {
    Text = "Di aula yang kosong, hanya langkahmu dan murphy yang bergema."
  },
  AvgDialog_13049_Content_1 = {
    Text = "Ogier memeluk senjatanya erat-erat, waspada terhadap setiap gerak-gerik di sekitarnya. Di matanya, setiap suara bisa jadi pasukan musuh yang bersembunyi."
  },
  AvgDialog_13049_Content_10 = {
    Text = "Suara air? Itu dari jam air di sana, kan."
  },
  AvgDialog_13049_Content_11 = {
    Text = "Sepertinya suara itu datang dari luar, aku pergi melihat!"
  },
  AvgDialog_13049_Content_12 = {
    Text = "Jangan terburu-buru! Kita pergi bersama!"
  },
  AvgDialog_13049_Content_13 = {
    Text = "Sebelum sempat dicegah, Augier sudah mengangkat senjatanya dan bergegas ke depan pintu istana."
  },
  AvgDialog_13049_Content_14 = {
    Text = "Ini——?!"
  },
  AvgDialog_13049_Content_15 = {
    Text = "Serangan musuh!"
  },
  AvgDialog_13049_Content_2 = {
    Text = "Kau tak menemukan alasan untuk menghiburnya. Kata-kata dari arsip Awakened yang pernah kau baca dengan saksama, kini terbayang jelas di depan mata—"
  },
  AvgDialog_13049_Content_3 = {
    Text = "Pernyataan diri Awakened: Ogier Danske, Ksatria Kadipaten @2\nGugur pada Malam Pertahanan Tanah Air……"
  },
  AvgDialog_13049_Content_4 = {
    Text = "Tuan Ajudan, sebaiknya Anda mengungsi ke pinggiran kota terlebih dahulu. Di sini…kami berdua saja sudah cukup."
  },
  AvgDialog_13049_Content_5 = {
    Text = "Kalian berdua ksatria, bahkan tidak bisa membedakan akonit dan anggrek. Bagaimana kalau kalian malah memberikan racun kepada sang putri?"
  },
  AvgDialog_13049_Content_6 = {
    Text = "Penolakan yang blak-blakan itu justru mencairkan suasana tegang. Ogier merona merah, sang ksatria pengawal menahan tawa, dan bahkan dari balik pintu terdengar tawa kecil yang tertahan."
  },
  AvgDialog_13049_Content_7 = {
    Text = "Kau tidak bisa pergi—terjebak dalam misteri yang berpusat pada Ogier, pergi sembarangan entah akan mendatangkan konsekuensi apa."
  },
  AvgDialog_13049_Content_8 = {Text = "Tik tak—"},
  AvgDialog_13049_Content_9 = {
    Text = "Kalian dengar suara itu tidak?"
  },
  AvgDialog_13050_Content_1 = {
    Text = "Setelah pertempuran akhirnya usai, kamu dan Ogier tinggal di bawah tangga untuk membersihkan aula istana, sementara ksatria pengawal sudah lebih dulu kembali berjaga di depan kamar sang putri."
  },
  AvgDialog_13050_Content_10 = {Text = "Srak……"},
  AvgDialog_13050_Content_11 = {
    Text = "Tapi… wabah bisa berubah menjadi monster, dan orang biasa tidak bisa melihatnya?"
  },
  AvgDialog_13050_Content_12 = {
    Text = "Sungguh terlalu absurd, bahkan jika dinyanyikan oleh penyair istana, mungkin tidak banyak orang yang akan percaya."
  },
  AvgDialog_13050_Content_13 = {
    Text = "Awalnya, aku dan ayah mengira itu kutukan yang dijatuhkan oleh penyihir negara tetangga, tapi… segera setelah itu mereka juga membawa kabar bahwa wabah merajalela di sana."
  },
  AvgDialog_13050_Content_14 = {
    Text = "Bahkan aku sendiri juga…… uhuk, uhuk uhuk……"
  },
  AvgDialog_13050_Content_15 = {
    Text = "Di sela-sela pembicaraan, batuk terdengar dari balik pintu, memilukan hati."
  },
  AvgDialog_13050_Content_16 = {
    Text = "Tuan Putri, tolong jangan bicara dulu, silakan kembali ke tempat tidur."
  },
  AvgDialog_13050_Content_17 = {Text = "Srak……"},
  AvgDialog_13050_Content_18 = {
    Text = "Ajudan! Ajudan, cepat kembali bantu! Tuan Putri dia——"
  },
  AvgDialog_13050_Content_19 = {Text = "Ugh!"},
  AvgDialog_13050_Content_2 = {
    Text = "Bertempur melawan musuh yang tak terlihat itu baru pertama kali, setelah semua ini selesai, bagaimana kalau kita cari seorang penyair pengembara untuk menuliskan kisahnya menjadi sebuah lagu?"
  },
  AvgDialog_13050_Content_20 = {
    Text = "Suara tulang patah terdengar begitu nyaring. Sesuatu dengan paksa menerobos jaringan otot yang rapat, cairan merah segar pun terciprat ke mana-mana."
  },
  AvgDialog_13050_Content_21 = {Text = "A...pa...?"},
  AvgDialog_13050_Content_22 = {
    Text = "Sir Fernando!!!"
  },
  AvgDialog_13050_Content_23 = {
    Text = "Ksatria pengawal itu terbatuk, darah bercampur potongan daging menyembur dari tenggorokannya. Ia membelalakkan mata tak percaya, linglung sekaligus ketakutan."
  },
  AvgDialog_13050_Content_3 = {
    Text = "Namanya sudah kupikirkan, judulnya \"Mata Danske, Pedang Fernando\"!"
  },
  AvgDialog_13050_Content_4 = {
    Text = "Ogier yang namanya disebut mendongak menatap ksatria pengawal. Tangannya penuh cairan korosi, ingin mengelap tangan tapi merasa serba salah, tampak sangat canggung."
  },
  AvgDialog_13050_Content_5 = {
    Text = "Nama saya juga akan ditulis di lagunya? Ogier tidak pantas menerima kehormatan itu……"
  },
  AvgDialog_13050_Content_6 = {
    Text = "Hehe… Apakah aku dan ajudan tidak boleh ikut dicantumkan namanya?"
  },
  AvgDialog_13050_Content_7 = {
    Text = "Tentu saja! Tentu saja boleh! Nama Anda akan ditulis di baris pertama lagu ini!"
  },
  AvgDialog_13050_Content_8 = {Text = "Srak……"},
  AvgDialog_13050_Content_9 = {
    Text = "@1Suite Sang Putri… bagaimana? Bukankah aku berbakat menjadi penyair?"
  },
  AvgDialog_13051_Content_1 = {
    Text = "Apa… apa yang terjadi?"
  },
  AvgDialog_13051_Content_10 = {
    Text = "Sir Fernando… setahuku dia anak tunggal di keluarganya."
  },
  AvgDialog_13051_Content_11 = {
    Text = "Andai saja aku lebih waspada……"
  },
  AvgDialog_13051_Content_12 = {
    Text = "Jangan menyalahkan dirimu atas kematiannya. Monster-monster @1 itu muncul dan menghilang tanpa jejak, kita sudah melakukan yang terbaik."
  },
  AvgDialog_13051_Content_13 = {
    Text = [[
Ogier menggelengkan kepala, hiburan pucatmu jelas tak mampu menghiburnya.
Saat itu, terdengar ketukan pelan dari balik pintu di belakangmu.]]
  },
  AvgDialog_13051_Content_14 = {
    Text = "Ajudan, bawalah Ogier pergi dari sini."
  },
  AvgDialog_13051_Content_15 = {Text = "Mengapa!"},
  AvgDialog_13051_Content_16 = {
    Text = "A-Anda tidak membutuhkan saya lagi? Saya tahu saya gagal menyelamatkan Tuan Fernando, tapi……"
  },
  AvgDialog_13051_Content_17 = {
    Text = "Wabah ini membawa penyakit, peperangan, penderitaan… Kau tetap di sini hanya akan menjadi santapan lezat berikutnya baginya."
  },
  AvgDialog_13051_Content_18 = {
    Text = "Suaranya bergetar, namun ia masih mengucapkan kata-kata yang sedikit jenaka. Di hadapan kematian yang bisa datang kapan saja, ia tidak menunjukkan secuil pun ketakutan."
  },
  AvgDialog_13051_Content_19 = {
    Text = "Kupikir… Yang Mulia Fernando juga tidak ingin bertemu kembali denganmu secepat ini, bukan begitu?"
  },
  AvgDialog_13051_Content_2 = {
    Text = "Dari balik pintu terdengar langkah kaki yang gontai, lalu palang pintu bergeser—"
  },
  AvgDialog_13051_Content_20 = {
    Text = "Tapi… ini adalah… tanggung jawabku…"
  },
  AvgDialog_13051_Content_21 = {
    Text = "Sekarang… hanya tinggal aku… Aku akan mewarisi kehendak Yang Mulia Fernando… Aku harus mewarisinya…"
  },
  AvgDialog_13051_Content_22 = {
    Text = "Dari balik pintu terdengar helaan napas panjang penuh keputusasaan. Setelah lama terdiam, sang Putri akhirnya bersuara kepadamu."
  },
  AvgDialog_13051_Content_23 = {
    Text = "Ajudan, berjanjilah padaku… Ketika suaraku benar-benar lenyap, pastikan kau membawa Ogier pergi, bahkan jika kau harus membuatnya pingsan, bisa kan?"
  },
  AvgDialog_13051_Content_24 = {
    Text = "……Akan kuhormati harapanmu."
  },
  AvgDialog_13051_Content_25 = {
    Text = "Ogier memeluk senjatanya erat-erat, kedua tangannya memutih karena mencengkeram begitu kuat, seolah tombak panjang dalam dekapannya adalah keluarga yang tak diketahui nasibnya, adalah sang Putri yang sekarat, adalah Fernando yang telah pergi selamanya."
  },
  AvgDialog_13051_Content_26 = {
    Text = "Ia menatap gerbang istana tanpa berkedip, namun kesadarannya entah kapan telah melayang jauh. Bahkan hantaman keras pada gerbang besar yang menghasilkan dentuman pun tak mampu menyadarkannya."
  },
  AvgDialog_13051_Content_27 = {
    Text = "Ogier? Ogier?"
  },
  AvgDialog_13051_Content_28 = {
    Text = "Ada orang datang."
  },
  AvgDialog_13051_Content_29 = {
    Text = "Ada orang… datang? Para ksatria sudah kembali!?"
  },
  AvgDialog_13051_Content_3 = {
    Text = "Jangan keluar!"
  },
  AvgDialog_13051_Content_30 = {
    Text = "Gerbang besar dihantam hingga terbuka, namun panji yang berkibar tertiup angin bukanlah warna yang kalian harapkan."
  },
  AvgDialog_13051_Content_4 = {
    Text = "Tuan Putri… tolong jangan keluar……"
  },
  AvgDialog_13051_Content_5 = {
    Text = "Ogier dengan susah payah mendorong tubuh Ksatria Fernando menjauh dari pintu, lalu menarik tirai gantung dan menutupi genangan darah yang hampir mengalir masuk melalui celah pintu."
  },
  AvgDialog_13051_Content_6 = {
    Text = "Duri makhluk bermutasi itu menembus baju baja dan daging, dadanya hancur berantakan seolah habis terkena ledakan. Ksatria Fernando sudah menghembuskan napas terakhirnya dalam kesakitan."
  },
  AvgDialog_13051_Content_7 = {
    Text = "...Baiklah."
  },
  AvgDialog_13051_Content_8 = {
    Text = "Tolong, usahakan untuk mempersiapkan jenazahnya sebaik mungkin."
  },
  AvgDialog_13051_Content_9 = {
    Text = "Kau dan Ogier saling berpandangan, lalu dalam diam membungkus jasad sang ksatria dengan karpet, kemudian duduk di lantai di depan pintu kamar tidur. Rasa sakit dan kecemasan menyebar di udara."
  },
  AvgDialog_13052_Content_1 = {
    Text = "Ada apa? Di mana musuhnya?"
  },
  AvgDialog_13052_Content_10 = {
    Text = "Tuan Ajudan, Anda juga bisa melihatnya?"
  },
  AvgDialog_13052_Content_11 = {
    Text = "Kau mengirimkan tatapan menenangkan kepadanya, lalu melanjutkan negosiasi dengan ksatria."
  },
  AvgDialog_13052_Content_12 = {
    Text = "Augier tidak pernah menjadi anak yang membuat keributan tanpa alasan. Anda yang pernah berlatih bersamanya pasti paling tahu, bukan?"
  },
  AvgDialog_13052_Content_13 = {
    Text = "Meskipun kau bilang begitu, tapi aku memang tidak melihat apa-apa……"
  },
  AvgDialog_13052_Content_14 = {
    Text = "…Tunggu, Tuan Fernando."
  },
  AvgDialog_13052_Content_15 = {
    Text = "Terdengar suara ketukan pintu dari arah kamar tidur, suara wanita yang lemah itu membuat semua orang berkumpul kembali di depan pintu."
  },
  AvgDialog_13052_Content_16 = {
    Text = "Mereka benar… Itulah musuh tak kasat mata yang menyebarkan wabah."
  },
  AvgDialog_13052_Content_17 = {
    Text = "Kalau Tuan Putri sendiri yang mengatakannya……"
  },
  AvgDialog_13052_Content_18 = {
    Text = "Ksatria pengawal menggertakkan giginya, mengangkat senjata dan berdiri di samping kalian."
  },
  AvgDialog_13052_Content_19 = {
    Text = "Tolong beritahu saya posisi musuhnya, saya akan berusaha sekuat tenaga membantu pertempuran!"
  },
  AvgDialog_13052_Content_2 = {
    Text = "Ksatria pengawal juga berlari menuruni tangga menghampiri kalian, tampak kebingungan."
  },
  AvgDialog_13052_Content_3 = {
    Text = "Sekarang bukan waktunya bercanda, jangan lengah."
  },
  AvgDialog_13052_Content_4 = {
    Text = "Aku tidak bercanda! A-Anda tidak bisa melihatnya?!"
  },
  AvgDialog_13052_Content_5 = {
    Text = "Augier membela diri dengan cemas, tetapi ksatria pengawal tetap setengah percaya setengah ragu."
  },
  AvgDialog_13052_Content_6 = {
    Text = "Hal itu tidak bisa disalahkan padanya, karena musuh yang kau dan Augier kalahkan — adalah entitas mutan yang sepenuhnya berasal dari Erosi."
  },
  AvgDialog_13052_Content_7 = {
    Text = [[
Orang yang bisa mengamati fenomena Erosi dengan mata telanjang sangatlah langka.
Augier adalah salah satu dari sedikit orang beruntung yang malang itu.]]
  },
  AvgDialog_13052_Content_8 = {
    Text = "Tolong percayalah pada kami"
  },
  AvgDialog_13052_Content_9 = {
    Text = "Tolong percayalah pada kami, percayalah pada karakter Augier."
  },
  AvgDialog_13053_Content_1 = {
    Text = "Lagu Berakhir, Orang Berpisah"
  },
  AvgDialog_13053_Content_11 = {
    Text = [[
Biarkan Ogier ikut menjaga istana.
Dia kan ksatria pelindung yang sah, yang ditunjuk langsung oleh Adipati Agung, bukan?]]
  },
  AvgDialog_13053_Content_12 = {
    Text = "Ksatria penjaga tidak menemukan alasan lain untuk menolak. Setelah ia mengangguk setuju, kalian bersama-sama kembali ke istana."
  },
  AvgDialog_13053_Content_13 = {
    Text = [[
Istana kosong tak berpenghuni, bahkan dayang yang selalu ribut itu pun telah pergi.
Selain kalian bertiga, hanya sang Putri yang tersisa di istana.]]
  },
  AvgDialog_13053_Content_14 = {
    Text = "Kau mengetuk pintu kamar tidur yang megah berkilauan, suara ketukan bergema di aula yang sunyi, terasa menyesakkan."
  },
  AvgDialog_13053_Content_15 = {
    Text = "Putri? Apakah Anda baik-baik saja?"
  },
  AvgDialog_13053_Content_16 = {
    Text = "Tidak ada jawaban dari dalam ruangan. Kau menunggu sejenak, lalu mengetuk pintu sekali lagi."
  },
  AvgDialog_13053_Content_17 = {
    Text = "Putri, aku bersama ksatria pengawal dan Ogier ada di sini."
  },
  AvgDialog_13053_Content_18 = {
    Text = "Dari balik pintu kayu yang tebal, terdengar suara gesekan kain. Seseorang sedang berusaha keras untuk bangun dari tempat tidur."
  },
  AvgDialog_13053_Content_19 = {
    Text = "……Jangan konyol."
  },
  AvgDialog_13053_Content_2 = {Text = "\"Mimpi\""},
  AvgDialog_13053_Content_20 = {
    Text = "Kalian…pergilah, pergi bersama yang lain. Tidak perlu menjaga sebuah mayat."
  },
  AvgDialog_13053_Content_21 = {
    Text = "Napas sang gadis lemah, suaranya nyaris tak terdengar. Seolah-olah sekadar meresponsmu saja sudah menguras seluruh tenaganya."
  },
  AvgDialog_13053_Content_22 = {
    Text = "Wabah menyebar tanpa kendali di seluruh kadipaten, bahkan kaum bangsawan pun tak luput. Sang putri sudah terjangkit penyakit sebelum perang dimulai, dan hingga kini, ia bahkan tak punya tenaga untuk beranjak dari tempat tidur."
  },
  AvgDialog_13053_Content_23 = {
    Text = "Dokter istana bahkan berterus terang bahwa sang putri sudah tidak sanggup menanggung perjalanan untuk dipindahkan dari istana peristirahatan. Guncangan sekecil apa pun bisa merenggut nyawanya."
  },
  AvgDialog_13053_Content_24 = {
    Text = "Yang Mulia Putri……"
  },
  AvgDialog_13053_Content_25 = {
    Text = "Apa pun yang Anda katakan, saya tidak akan meninggalkan tempat ini. Izinkan saya untuk tetap menjaga Anda, biarkan saya…\nmenunaikan kewajiban seorang ksatria."
  },
  AvgDialog_13053_Content_27 = {
    Text = "……Jangan terlalu dekat dengan kamarku. Wabah ini sudah tak bisa disembuhkan, setidaknya…jangan sampai kalian juga tertular."
  },
  AvgDialog_13053_Content_28 = {
    Text = "Setiap kali jam air habis mengalir, datanglah bicara padaku, ya?\nSaat aku tidak lagi menjawab…pergilah kalian."
  },
  AvgDialog_13053_Content_3 = {
    Text = "Konspirasi bergerak dalam kegelapan, menyulut sumbu yang telah ditanam oleh wabah penyakit, dan perang meletus dalam semalam."
  },
  AvgDialog_13053_Content_4 = {
    Text = "<Yellow:Wabah> yang tak tersembuhkan telah lama menyebar ke seluruh kadipaten, para prajurit penjaga kota didera penyakit, tak mampu melawan pasukan berkuda penyerbu."
  },
  AvgDialog_13053_Content_5 = {
    Text = "Bahkan para ksatria kerajaan pun telah bergegas melewati parit pertahanan atas perintah Adipati Agung, bergabung dalam garis pertahanan terakhir untuk menjaga ibu kota."
  },
  AvgDialog_13053_Content_6 = {
    Text = "Ogier, kenapa kau masih di sini?"
  },
  AvgDialog_13053_Content_7 = {
    Text = "Aku… aku ingin menjalankan tugas pengawalan bersama Anda."
  },
  AvgDialog_13053_Content_8 = {
    Text = "Kau masih terlalu muda, perang…untuk saat ini belum giliranmu untuk ikut serta.\nKembalilah, pergi ke tempat yang aman bersama keluargamu."
  },
  AvgDialog_13053_Content_9 = {
    Text = "Rumah Ogier, Perkebunan Danske… seharusnya berada di luar garis pertahanan, bukan?"
  },
  AvgDialog_13054_Content_1 = {
    Text = "Mimpi, atau Cita-cita"
  },
  AvgDialog_13054_Content_10 = {
    Text = "Ajudan, tolong pergilah ke sana untukku."
  },
  AvgDialog_13054_Content_100 = {
    Text = "Pembicaraan kita tadi…… Anda benar-benar tidak akan memberitahu Putri, kan?"
  },
  AvgDialog_13054_Content_101 = {
    Text = "Kenapa? Aku sama sekali tidak punya kredibilitas di matamu?"
  },
  AvgDialog_13054_Content_102 = {
    Text = "Mana mungkin! Aku sama sekali tidak bermaksud begitu……!"
  },
  AvgDialog_13054_Content_103 = {
    Text = "Kalau begitu, aku akan menggunakan kejadian hari ini untuk mengancammu."
  },
  AvgDialog_13054_Content_104 = {Text = "Mengancam?"},
  AvgDialog_13054_Content_105 = {
    Text = "Kau berlutut di hadapan Augier, pandanganmu sejajar dengan anak anjing yang panik itu, lalu mengulurkan tanganmu kepadanya."
  },
  AvgDialog_13054_Content_106 = {
    Text = "Percakapan hari ini akan selamanya terkubur di perut kita, tapi sebagai imbalan atas kerahasiaanku, kau harus berjanji satu hal padaku."
  },
  AvgDialog_13054_Content_107 = {
    Text = "Di era ini tidak ada kebiasaan berjanji dengan mengaitkan jari kelingking, tapi Ogier tetap dengan polosnya mengaitkan jari kelingkingnya pada jari kelingkingmu yang terulur."
  },
  AvgDialog_13054_Content_108 = {
    Text = "Selama itu sesuatu yang bisa kulakukan…"
  },
  AvgDialog_13054_Content_109 = {
    Text = "Kalau begitu, aku akan menyimpan satu hak untuk membuat permohonan. Suatu hari nanti, mungkin aku akan datang untuk menagihnya, jangan sampai lupa ya, \"Tuan Ksatria\"."
  },
  AvgDialog_13054_Content_11 = {
    Text = "Jika yang terakhir benar, apakah membangunkan pemilik mimpi ini bisa membuatmu terbebas dari sini?"
  },
  AvgDialog_13054_Content_12 = {
    Text = "Hei! Tuan Ajudan? Sadarlah!"
  },
  AvgDialog_13054_Content_13 = {
    Text = "Pikiranmu melayang semakin jauh mengikuti petunjuk-petunjuk kecil, dan saat rencana \"membangunkan pemilik mimpi\" mulai terbentuk, kuku seseorang mencubit lenganmu dengan keras, rasa sakit itu membuatmu tersadar seketika."
  },
  AvgDialog_13054_Content_14 = {
    Text = "Sss— sakit sekali!"
  },
  AvgDialog_13054_Content_15 = {
    Text = "Ternyata kau masih bisa merasakan sakit! Kami sudah memanggilmu berkali-kali, tapi kau seperti mayat tanpa reaksi sama sekali, apa telingamu bermasalah?"
  },
  AvgDialog_13054_Content_16 = {
    Text = "Akhir-akhir ini kau sering melamun, pasti karena terlalu lelah, kan? Mau pulang ke wilayah keluargamu untuk beristirahat sebentar? Kebetulan kalian sudah lama tidak mendapat cuti."
  },
  AvgDialog_13054_Content_17 = {
    Text = "Jangan— maafkan aku, aku hanya sedang ada pikiran……"
  },
  AvgDialog_13054_Content_18 = {
    Text = "Kunci untuk keluar dari \"mimpi\" ini pasti ada pada Augier. Meskipun kau penasaran seperti apa dunia yang jauh dari pusat mimpi, di saat genting seperti ini, kau tidak boleh pergi terlalu jauh."
  },
  AvgDialog_13054_Content_19 = {
    Text = "Ada pikiran? Apa apa? Jangan-jangan ada orang yang kau sukai dan kau sedang gelisah karenanya?"
  },
  AvgDialog_13054_Content_2 = {
    Text = [[
"Alam Mimpi"
Istana Sang Putri]]
  },
  AvgDialog_13054_Content_20 = {
    Text = "Jangan-jangan kau gelisah karena orang itu tidak menyukaimu? Putri— tolong ramalkan untuk Tuan Ajudan kita sekali, atau sekalian saja berikan {Male=dia,Female=dia} ramuan cinta—"
  },
  AvgDialog_13054_Content_21 = {
    Text = "Sudahlah, mana bisa menggunakan sihir dan ramuan untuk mempertahankan hubungan?"
  },
  AvgDialog_13054_Content_22 = {
    Text = "Sang putri tersenyum mengalihkan topik yang diangkat oleh dayang, lalu melambaikan tangan kepadamu."
  },
  AvgDialog_13054_Content_23 = {
    Text = "Ogier sedang menjalani latihan di ordo ksatria. Tolong pergi dan lihatlah dia untukku, jangan sampai anak itu terluka."
  },
  AvgDialog_13054_Content_24 = {Text = "Baik!"},
  AvgDialog_13054_Content_25 = {
    Text = "Bagai diberi bantal saat mengantuk, sang putri memberimu alasan yang sah untuk mendekati Ogier."
  },
  AvgDialog_13054_Content_26 = {
    Text = "Tapi kalau memang benar-benar butuh ramuan, kau tetap bisa datang memintanya padaku, lho."
  },
  AvgDialog_13054_Content_27 = {
    Text = [[
"Mimpi"
Arena Latihan Ordo Ksatria]]
  },
  AvgDialog_13054_Content_28 = {
    Text = "Dengan panduan pelayan lain, kau melewati kastil dan taman yang bagaikan labirin, lalu menemukan arena latihan."
  },
  AvgDialog_13054_Content_29 = {
    Text = "Dentingan senjata yang beradu dan sorak-sorai penonton tak henti-hentinya terdengar, jelas ada orang yang sedang berlatih tanding di bawah terik matahari."
  },
  AvgDialog_13054_Content_3 = {
    Text = "Setelah percobaan ketiga untuk terbangun, yang hanya membuat pemandangan di depan matamu berubah tanpa alasan, kau akhirnya menerima kenyataan bahwa kau terjebak dalam ingatan Augier."
  },
  AvgDialog_13054_Content_30 = {
    Text = "——Hanya saja kau tidak menyangka, salah satu pihak yang berlatih tanding itu adalah Ogier."
  },
  AvgDialog_13054_Content_32 = {Text = "Ukh……!"},
  AvgDialog_13054_Content_33 = {
    Text = "Di hadapan perbedaan kekuatan yang mutlak, keteguhan dan keyakinan tak banyak berguna. Ksatria dewasa itu bahkan belum mengeluarkan seluruh tenaganya, namun getaran logam sudah membuat genggaman Ogier kehilangan kekuatan."
  },
  AvgDialog_13054_Content_34 = {
    Text = "Tombak terlepas dari tangan, sang pemuda bercucuran keringat, terengah-engah berlutut di atas permukaan tanah berpasir yang kasar."
  },
  AvgDialog_13054_Content_35 = {
    Text = "Nak, pulanglah dulu. Kalau terus berlatih, tanganmu bisa patah tulang."
  },
  AvgDialog_13054_Content_36 = {
    Text = [[
Betul tuh, kau masih terlalu kecil.
Kembalilah dua tahun lagi untuk berlatih, sekarang kau bahkan tidak bisa mengangkat senjata.]]
  },
  AvgDialog_13054_Content_37 = {
    Text = "Tidak……"
  },
  AvgDialog_13054_Content_38 = {
    Text = "Ogier gemetar seluruh tubuh, membungkuk memungut tombak yang terjatuh, dengan susah payah menyesuaikan posisi siaga, mengarahkan ujung tombak ke ksatria lawannya,"
  },
  AvgDialog_13054_Content_39 = {
    Text = "Aku masih… bisa bertahan!"
  },
  AvgDialog_13054_Content_4 = {
    Text = "Kau berdiri di sudut kamar tidur sang putri, memasang tampang pendengar yang baik, dengan patuh memainkan peran sebagai ajudan."
  },
  AvgDialog_13054_Content_40 = {
    Text = "Dasar anak ini… benar-benar keras kepala."
  },
  AvgDialog_13054_Content_41 = {
    Text = "Wajah sang pemuda memerah karena kelelahan dan kekurangan oksigen. Menghadapi kemauan sekeras itu, orang yang awalnya berniat membuat Ogier mundur melalui latihan akhirnya angkat bicara."
  },
  AvgDialog_13054_Content_42 = {
    Text = "Lumayan juga, ya. Musuh di luar sana mengincar kadipaten kita, anak-anak yang berkemauan teguh seperti Tuan Muda Danske, semakin banyak semakin baik."
  },
  AvgDialog_13054_Content_43 = {
    Text = "Kalau begitu, aku akan serius sekarang, ya?"
  },
  AvgDialog_13054_Content_44 = {
    Text = "Jangan sembarangan! Kalau anak ini sampai tumbang karena latihan, bagaimana kau mau melapor kepada Grand Duke dan Putri?"
  },
  AvgDialog_13054_Content_45 = {
    Text = "Mulai dari latihan fisik dasar dulu, awasi dia, jangan sampai dia terluka oleh senjata."
  },
  AvgDialog_13054_Content_46 = {
    Text = "Kata-kata sang Komandan menyulut semangat Ogier. Mata pemuda itu seketika berbinar, kegembiraannya tak terbendung."
  },
  AvgDialog_13054_Content_47 = {
    Text = "Anda setuju saya bergabung dengan ordo ksatria?!"
  },
  AvgDialog_13054_Content_48 = {
    Text = "Bahkan tanpa candaan Grand Duke itu pun, dengan tekad sekuat ini, dia sudah layak menjadi ksatria magang."
  },
  AvgDialog_13054_Content_49 = {
    Text = "Melihat luka lecet dan bekas darah di sekujur tubuh pemuda itu, sang Komandan terdiam sejenak, merasa tak tega."
  },
  AvgDialog_13054_Content_5 = {
    Text = "Putri, Putri! Kudengar Tuan Muda Danske pergi ke ordo ksatria lagi untuk melapor, ini sudah hari ketiga!"
  },
  AvgDialog_13054_Content_50 = {
    Text = "Hari ini pulanglah dulu, mulai besok aku akan membuatkan rencana latihan khusus untukmu — dan kalian semua! Berhenti menonton, masing-masing tambah dua putaran latihan beban!"
  },
  AvgDialog_13054_Content_51 = {
    Text = "Ampuni kami, Komandan—"
  },
  AvgDialog_13054_Content_52 = {
    Text = "Belum selesai sang Komandan bicara, memanfaatkan suasana ringan yang jarang terjadi, muncul perlawanan kecil dari kerumunan. Para ksatria muda melepaskan tekanan mereka dengan cara seperti ini."
  },
  AvgDialog_13054_Content_53 = {
    Text = "Tiga putaran!"
  },
  AvgDialog_13054_Content_54 = {
    Text = "Di tengah keluhan yang bersahut-sahutan, Ogier akhirnya melepaskan ketegangan yang selama ini dipendamnya, dan bruk — ia terjatuh terbaring di tanah."
  },
  AvgDialog_13054_Content_55 = {
    Text = "Syukurlah…akhirnya……"
  },
  AvgDialog_13054_Content_56 = {
    Text = "Ogier, bisakah kita bicara sebentar?"
  },
  AvgDialog_13054_Content_57 = {
    Text = "Anda… Tuan Ajudan! Anda melihat penampilan memalukan saya seperti ini, saya……"
  },
  AvgDialog_13054_Content_58 = {
    Text = "Ogier langsung duduk tegak, lutut yang terluka bergesekan dengan pasir saat ia bergerak, rasa sakit membuat ekspresi tegangnya menjadi sedikit terdistorsi."
  },
  AvgDialog_13054_Content_59 = {
    Text = "Kau melambaikan tangan padanya, lalu mengeluarkan obat luka yang entah kapan diselipkan Putri ke dalam saku bajumu."
  },
  AvgDialog_13054_Content_6 = {
    Text = "Dia benar-benar menganggap serius perkataan ayahnya… Dia masih sangat kecil, bagaimana mungkin dia tahan dengan latihan ordo ksatria?"
  },
  AvgDialog_13054_Content_60 = {
    Text = "Eh…tidak sakit? Bukankah ini obat luka?"
  },
  AvgDialog_13054_Content_61 = {
    Text = "Ini obat yang diracik sendiri oleh Putri, sepertinya sudah melalui pemrosesan khusus."
  },
  AvgDialog_13054_Content_62 = {
    Text = "Putri yang dilayani oleh \"kau\" adalah seorang gadis penuh misteri. Ia jarang keluar, namun memiliki pemahaman dan bakat unik dalam pengobatan. Jika ia hidup di zamanmu, ia pasti menjadi seorang apoteker yang sangat terkenal."
  },
  AvgDialog_13054_Content_63 = {
    Text = "Sayangnya, di masa yang hilang ratusan tahun sebelumnya ini, bakatnya tidak dipahami oleh dunia. Kau sudah lebih dari sekali mendengar pelayan lain diam-diam memanggilnya \"penyihir\"."
  },
  AvgDialog_13054_Content_64 = {
    Text = "Obat milik Sang Putri?! Ini terlalu berharga, mana mungkin digunakan untukku— Sssh!"
  },
  AvgDialog_13054_Content_65 = {
    Text = [[
Jangan banyak bergerak, mau menyia-nyiakan kemurahan hati Sang Putri?
Duduklah dulu, biar aku selesaikan mengobati lukamu.]]
  },
  AvgDialog_13054_Content_66 = {
    Text = [[
Takut menyia-nyiakan obat yang berharga, Ogier akhirnya duduk dengan tenang.
Anggota ordo ksatria lainnya juga mulai meninggalkan arena satu per satu. Ini adalah kesempatan langka yang baik.]]
  },
  AvgDialog_13054_Content_67 = {
    Text = "Ogier, bisakah kau merasakan bahwa kau sedang bermimpi?"
  },
  AvgDialog_13054_Content_68 = {
    Text = "Memang, rasanya seperti mimpi……"
  },
  AvgDialog_13054_Content_69 = {
    Text = "Pemuda itu salah mengartikan kata-katamu menjadi makna yang paling sesuai dengan situasi saat ini. Ia memejamkan mata dan bergumam penuh kekaguman, kata-katanya dipenuhi kepuasan dan harapan."
  },
  AvgDialog_13054_Content_7 = {
    Text = "Tidak… tunggu dulu…… mungkin ada kemungkinan lain."
  },
  AvgDialog_13054_Content_70 = {
    Text = "Menghadap audiensi, terpilih, lalu mendapat pengakuan dari para ksatria…… Rasanya benar-benar seperti mimpi."
  },
  AvgDialog_13054_Content_71 = {
    Text = "<LightGray:(Haruskah aku langsung memberitahunya bahwa ini mimpi? Tapi esensi tempat ini belum sepenuhnya kupahami, apakah ini kenangan atau mimpi……)>"
  },
  AvgDialog_13054_Content_72 = {
    Text = "Keraguanmu menarik perhatian Ogier. Ia tiba-tiba menjadi sedikit gugup, kedua tangannya dengan gelisah meremas ujung bajunya."
  },
  AvgDialog_13054_Content_73 = {
    Text = "Tuan Ajudan, apakah… apakah Sang Putri tidak puas denganku?"
  },
  AvgDialog_13054_Content_75 = {
    Text = "Ogier adalah anak dari keluarga bangsawan, jelas bisa hidup berkecukupan seumur hidup. Mengapa harus menjadi ksatria?"
  },
  AvgDialog_13054_Content_76 = {
    Text = "Karena… karena……"
  },
  AvgDialog_13054_Content_77 = {
    Text = "Suara Ogier semakin mengecil karena rasa malu, kepalanya pun semakin tertunduk. Jawaban dari pertanyaan itu jelas membuatnya merasa sulit untuk diucapkan."
  },
  AvgDialog_13054_Content_78 = {
    Text = "Aku bersumpah, percakapan di antara kita tidak akan diketahui orang ketiga."
  },
  AvgDialog_13054_Content_79 = {
    Text = "Karena… ayahku juga jatuh sakit. Sama seperti Bibi Merlinette di dapur, dan Kakak Pedro si tukang kebun……"
  },
  AvgDialog_13054_Content_8 = {
    Text = "Dari deskripsi sang pelayan, Augier sedang menjalani latihan di ordo ksatria. Karena Augier tidak terlibat dalam percakapan ini, maka dugaan bahwa ini adalah \"ingatan Augier\" tidak bisa dibenarkan."
  },
  AvgDialog_13054_Content_80 = {
    Text = "Dan masih banyak orang lainnya, semua orang terkena penyakit yang sama."
  },
  AvgDialog_13054_Content_81 = {
    Text = "Ayah sudah tidak bisa meninggalkan tempat tidurnya, tapi aku belum cukup dewasa… Sebagai satu-satunya anak ayah, aku……"
  },
  AvgDialog_13054_Content_82 = {
    Text = "Kalau ayah sampai meninggal, semua orang di manor akan dibubarkan.\nSemua masih sakit… sama sekali tidak punya tempat untuk pergi."
  },
  AvgDialog_13054_Content_83 = {
    Text = "Aku harus… aku harus bertanggung jawab untuk semua orang…… Hanya dengan menjadi ksatria, mendapat perlindungan dari Yang Mulia Adipati……"
  },
  AvgDialog_13054_Content_84 = {
    Text = "Sampai di sini, wajah Ogier sudah pucat pasi. Ia menatapmu dengan cemas, seolah takut kau akan menyalahkan \"motifnya yang tidak murni\", takut kau menjatuhkan hukuman atas nama Sang Putri kepadanya."
  },
  AvgDialog_13054_Content_85 = {
    Text = [[
Kegugupan yang serupa, tekad yang sama kuatnya.
Dia memang Augier yang kau kenal, tanpa keraguan sedikit pun.]]
  },
  AvgDialog_13054_Content_86 = {
    Text = "Maaf, Tuan Pelayan Istana…… Jika, jika Anda ingin Putri menggantikan saya…a-aku juga tidak akan mengeluh……"
  },
  AvgDialog_13054_Content_87 = {
    Text = "Pada malam Grand Duke memilihmu, kau bersumpah di hadapan semua tamu atas nama kehormatan keluargamu, bukan?"
  },
  AvgDialog_13054_Content_88 = {
    Text = "Bersumpah akan menjalankan tugas ksatria dengan taruhan nyawa…… Saat kau mengucapkan sumpah itu bersama yang lain, apakah kau sungguh-sungguh?"
  },
  AvgDialog_13054_Content_89 = {
    Text = "<Big:Tentu saja! Aku tidak bercanda!>"
  },
  AvgDialog_13054_Content_9 = {
    Text = "Ini bukan sekadar \"ingatan\" biasa. Mungkin, kau telah memasuki sepenggal sejarah yang benar-benar terjadi, atau mungkin, ini adalah mimpi yang dilengkapi oleh alam bawah sadar?"
  },
  AvgDialog_13054_Content_90 = {
    Text = "\"Aku akan selalu setia, selalu mengabdi\"…… Ayah pasti juga mengharapkan aku melakukan hal ini."
  },
  AvgDialog_13054_Content_91 = {
    Text = [[
Baiklah, aku tidak akan memberitahu Putri soal ini.
Jangan terlalu panik, air matamu hampir jatuh tuh.]]
  },
  AvgDialog_13054_Content_92 = {
    Text = "Be-benarkah?! Maafkan ketidaksopananku!"
  },
  AvgDialog_13054_Content_93 = {
    Text = "Ugh…ugh?! Mata, mataku sakit sekali……"
  },
  AvgDialog_13054_Content_94 = {
    Text = "Augier dengan panik menggosok matanya, tapi sapu tangannya sudah terkena debu saat latihan. Usapan itu justru membuat penampilannya yang sudah berantakan semakin kacau."
  },
  AvgDialog_13054_Content_95 = {
    Text = "Memperlihatkan penampilan memalukan seperti ini di hadapan Tuan Pelayan Istana, aku benar-benar……"
  },
  AvgDialog_13054_Content_96 = {
    Text = [[
Tidak apa-apa, aku pernah melihat penampilan yang lebih berantakan dari ini.
Ayo kita kembali ke istana dulu untuk membersihkanmu, tidak bisa membiarkanmu pulang dengan penampilan seperti ini.]]
  },
  AvgDialog_13054_Content_98 = {
    Text = "Tuan Pelayan Istana, bolehkah saya meminta satu hal kepada Anda?"
  },
  AvgDialog_13054_Content_99 = {
    Text = "Silakan katakan."
  },
  AvgDialog_13055_Content_1 = {
    Text = "Benang Masa Lalu"
  },
  AvgDialog_13055_Content_10 = {
    Text = "Tautkan kembali"
  },
  AvgDialog_13055_Content_11 = {
    Text = "Melihat Ogier semakin mendekati kehilangan kendali, kau memilih untuk tidak menunggu lagi dan langsung menggenggam erat kedua tangannya yang sudah tertutup lumpur hitam."
  },
  AvgDialog_13055_Content_12 = {
    Text = "Kunci Perak berpendar, kau membimbing sulur-sulur spiritual menembus badai Gnosis, melewati lapisan demi lapisan kegelapan, dan sekali lagi bertaut dengan Ogier."
  },
  AvgDialog_13055_Content_13 = {
    Text = "Diiringi rasa sakit samar bagai tersengat listrik, gambaran demi gambaran berkilat cepat di depan mata, lalu lenyap seketika."
  },
  AvgDialog_13055_Content_14 = {
    Text = "Tanda-tanda kehilangan kendali surut bagai air pasang, kondisi Ogier mulai stabil, wajah mudanya menampakkan sedikit kelelahan."
  },
  AvgDialog_13055_Content_15 = {
    Text = "Tuanku, kali ini……berapa lama aku bertahan?"
  },
  AvgDialog_13055_Content_16 = {
    Text = "Penghitung waktu baru berjalan setengah putaran. Dalam keadaan terputus dari tautan, Ogier tidak berhasil bertahan lebih lama dari latihan sebelumnya."
  },
  AvgDialog_13055_Content_17 = {
    Text = "Hmm……30 detik, ditambah 200 milidetik."
  },
  AvgDialog_13055_Content_18 = {
    Text = "Ke-kenapa bisa begini……!"
  },
  AvgDialog_13055_Content_19 = {
    Text = "Nada bicaranya gelisah, bagaimanapun juga <Yellow:Latihan Pemutusan Tautan> ini adalah ide yang ia ajukan sendiri."
  },
  AvgDialog_13055_Content_2 = {
    Text = [[
Arena Latihan Universitas Misagar
Senja]]
  },
  AvgDialog_13055_Content_20 = {
    Text = "Ia terus memikirkan insiden pada hari Upacara Penyerahan Kunci, takut suatu hari nanti ia pun akan kehilangan kendali dan mengarahkan tombaknya kepada kalian—untuk itulah, ia ingin meningkatkan kemampuannya mempertahankan kewarasan dalam keadaan tanpa tautan."
  },
  AvgDialog_13055_Content_21 = {
    Text = "Tuan, ayo kita lakukan sekali lagi!"
  },
  AvgDialog_13055_Content_22 = {
    Text = "Kita sudah berlatih cukup lama, latihan berlebihan justru akan kontraproduktif."
  },
  AvgDialog_13055_Content_23 = {
    Text = "Mata Ogier berkilat-kilat, tapi akhirnya meredup, nada bicaranya diwarnai sedikit rasa menyalahkan diri sendiri."
  },
  AvgDialog_13055_Content_24 = {
    Text = "Aku yang kurang mempertimbangkan semuanya..."
  },
  AvgDialog_13055_Content_26 = {
    Text = "Besok aku juga tidak ada tugas investigasi. Setelah makan siang, kita pasti bertemu."
  },
  AvgDialog_13055_Content_27 = {Text = "Tuan!"},
  AvgDialog_13055_Content_28 = {
    Text = "Di bawah tatapan bersemangat bak anak anjing yang kegirangan, kamu menyeret tubuhmu yang sama lelahnya kembali ke asrama."
  },
  AvgDialog_13055_Content_29 = {
    Text = "Sebuah mumi yang sudah membersihkan diri seadanya berbaring di atas ranjang yang empuk. Diiringi rasa terima kasih atas selera Misagar dalam memilih perlengkapan tidur untuk logistik, kesadaran perlahan melayang keluar dari otak..."
  },
  AvgDialog_13055_Content_3 = {
    Text = "Kunci Perak berkilauan, kau mengendalikan untaian benang perak halus tak kasat mata dalam pikiranmu, menariknya keluar dari titik-titik cahaya yang berkilau."
  },
  AvgDialog_13055_Content_31 = {
    Text = "Dalam kegelapan terdengar alunan musik asing yang merdu, diiringi dentingan piala perak yang saling beradu, suasana ramai namun elegan memenuhi alam mimpi."
  },
  AvgDialog_13055_Content_32 = {
    Text = "Berisik sekali... siapa sih... mengadakan perjamuan di area asrama tengah malam..."
  },
  AvgDialog_13055_Content_33 = {
    Text = "Kamu membalikkan badan, mengulurkan tangan untuk meraih selimut yang tertendang dari tempat tidur."
  },
  AvgDialog_13055_Content_34 = {
    Text = "Tanganmu meraba ke dalam kabut, menggenggam segumpal awan cumulonimbus yang penuh dengan hal tak diketahui, sentuhan yang terasa nyata sekaligus ilusi."
  },
  AvgDialog_13055_Content_35 = {
    Text = "Oh, ternyata kamu di sini. Tadi aku baru saja mencarimu."
  },
  AvgDialog_13055_Content_36 = {Text = "A...pa...?"},
  AvgDialog_13055_Content_37 = {
    Text = "Kakiku terasa lemas lagi, aku perlu merepotkanmu untuk pergi ke tempat Ayah dan menjemput ksatriaku kemari."
  },
  AvgDialog_13055_Content_38 = {
    Text = "Ksatria...?"
  },
  AvgDialog_13055_Content_39 = {
    Text = "Kenapa bengong? Tidak dengar perkataan Putri?"
  },
  AvgDialog_13055_Content_4 = {Text = "Ukh……!"},
  AvgDialog_13055_Content_40 = {
    Text = "Wanita itu menepuk bahumu dengan keras, kegelapan memudar, dan pemandangan asing terpampang di hadapan mata."
  },
  AvgDialog_13055_Content_41 = {
    Text = "Aula yang mewah, orkestra yang memainkan suite kuno di kejauhan, hidangan penutup yang indah dan menggoda, serta para bangsawan wanita yang serentak menatapmu."
  },
  AvgDialog_13055_Content_42 = {
    Text = "Dan seorang gadis yang dikelilingi mereka, berbaring miring di atas dipan yang empuk."
  },
  AvgDialog_13055_Content_43 = {
    Text = "Tidak masalah, jangan terlalu keras pada {Male=dia,Female=dia}. Demi menyajikan perjamuan yang sempurna untuk semua orang, ajudanku sudah sibuk semalaman tanpa istirahat."
  },
  AvgDialog_13055_Content_44 = {
    Text = "Gadis itu dipanggil \"Putri\" oleh orang-orang lain, menunjukkan betapa mulia kedudukannya, namun saat ini ia dengan lembut menolongmu dari situasi sulit."
  },
  AvgDialog_13055_Content_45 = {
    Text = "Tolong bawa \"ksatria\" yang ditunjuk ayah untukku kemari untuk bertemu, setelah itu kamu boleh pulang dan beristirahat hari ini, ya?"
  },
  AvgDialog_13055_Content_46 = {
    Text = "Sejumlah besar ingatan yang terfragmentasi membanjiri benakmu, tidak berkesinambungan dan tidak lengkap, tetapi cukup untuk membuatmu memerankan identitas dari raga ini — satu-satunya ajudan sang Putri."
  },
  AvgDialog_13055_Content_47 = {
    Text = "……Terima kasih atas kemurahan hati Anda, Tuan Putri."
  },
  AvgDialog_13055_Content_48 = {
    Text = "Insting tubuh membuatmu memberi hormat kepadanya. Di tengah tatapan iri atau merendahkan, kamu melewati kerumunan para bangsawan wanita dan berjalan menuju aula besar tempat lebih banyak orang berkumpul."
  },
  AvgDialog_13055_Content_49 = {
    Text = "Kamu menunduk menatap tangan \"dirimu sendiri\", warna kulitnya beberapa tingkat lebih gelap dari kulitmu yang biasa tersembunyi di balik sarung tangan, di mana-mana terdapat bekas luka tipis samar, jelas bukan milik orang yang hidup bermewah-mewahan."
  },
  AvgDialog_13055_Content_5 = {
    Text = "Jangan memaksakan diri, kalau sudah tidak kuat, segera tautkan dengan Black Pool!"
  },
  AvgDialog_13055_Content_50 = {
    Text = "Vas bunga logam mewah yang kamu lewati semakin membuktikan dugaan yang tidak menyenangkan itu—"
  },
  AvgDialog_13055_Content_51 = {
    Text = "Bayangan yang terpantul di sana, bukanlah wajahmu."
  },
  AvgDialog_13055_Content_52 = {
    Text = "Tuan Ajudan! Apakah Anda datang mewakili Tuan Putri?"
  },
  AvgDialog_13055_Content_53 = {
    Text = "Pelayan wanita yang muncul dari kerumunan itu jelas bermata lebih tajam darimu, langsung menemukan \"dirimu\" yang familiar dari kerumunan yang ramai dan hiruk-pikuk."
  },
  AvgDialog_13055_Content_54 = {
    Text = "<Small:Adipati Agung memilih ksatria yang sangat muda! Apakah benar-benar akan membiarkan anak sekecil ini bergabung dalam pelatihan ordo ksatria? Kurasa dia bahkan tidak bisa mengangkat senjata.>"
  },
  AvgDialog_13055_Content_55 = {
    Text = "<BigItalic:Maaf, mohon semua minggir, kami datang atas perintah Putri @1 untuk menghadap—>"
  },
  AvgDialog_13055_Content_56 = {
    Text = "<Small:Kamu tadi tidak lihat, saat dia dibawa Adipati Agung ke hadapan semua orang, wajahnya merah padam karena malu.>"
  },
  AvgDialog_13055_Content_57 = {
    Text = "<BigItalic:Maaf, maaf, ajudan Putri datang menghadap!!>"
  },
  AvgDialog_13055_Content_58 = {
    Text = "<Small:Anak sekecil ini, butuh berapa lama latihan untuk menjadi ksatria sejati… Adipati Agung pasti hanya bercanda, kan?>"
  },
  AvgDialog_13055_Content_59 = {
    Text = "Pelayan wanita itu dengan cekatan menyibak kerumunan dengan kata-katanya, sambil berbisik bergurau denganmu, membimbingmu menerobos hingga ke depan singgasana."
  },
  AvgDialog_13055_Content_6 = {
    Text = "Aku masih…bisa……bertahan……"
  },
  AvgDialog_13055_Content_60 = {
    Text = "A-Anda… Salam. Anda yang Tuan Ajudan itu?"
  },
  AvgDialog_13055_Content_61 = {
    Text = "Kamu adalah……!"
  },
  AvgDialog_13055_Content_62 = {
    Text = "Saya putra sulung keluarga Dansk, berterima kasih atas pengangkatan dari Adipati Agung, sa-saya sangat terhormat bisa menjadi ksatria Putri @1."
  },
  AvgDialog_13055_Content_7 = {
    Text = "Ogier berlutut dengan satu kaki, kehilangan tautan yang menopangnya, ia terpaksa menyandarkan tubuhnya pada tombak panjang agar tidak benar-benar ambruk."
  },
  AvgDialog_13055_Content_8 = {Text = "Tuan……"},
  AvgDialog_13055_Content_9 = {
    Text = "Cairan hitam pekat merembes dari sudut mata, bibir, dan lubang telinga. Organ-organnya telah dihancurkan oleh lumpur hitam tak berbentuk—bisa dibayangkan betapa besar penderitaan yang ditanggung pemuda itu."
  },
  AvgDialog_13056_Content_1 = {
    Text = "Nyanyian Baru"
  },
  AvgDialog_13056_Content_10 = {
    Text = "Jangan mendekat lagi! Aku tidak akan segan-segan!"
  },
  AvgDialog_13056_Content_100 = {
    Text = "Ayo pergi, hari ini hari libur, pasar di distrik timur pasti ramai, sekalian kita bisa mengunjungi anak-anak di panti asuhan…"
  },
  AvgDialog_13056_Content_101 = {
    Text = "Kau sengaja menyebutkan rencana perjalanan sambil melangkah pergi dari arena latihan sendirian, tanpa secuil pun kekhawatiran di hati."
  },
  AvgDialog_13056_Content_102 = {
    Text = "Tuanku! Tuanku! Tolong beritahu saya bagaimana Anda bisa tahu——"
  },
  AvgDialog_13056_Content_103 = {
    Text = "Karena kau tahu, dia pasti akan menyusul."
  },
  AvgDialog_13056_Content_11 = {
    Text = "Ogier mengacungkan tombaknya, menghalangi tangga."
  },
  AvgDialog_13056_Content_12 = {
    Text = "Ini peringatan terakhir, silakan tinggalkan istana!"
  },
  AvgDialog_13056_Content_13 = {
    Text = "Hei, kau dengar itu? Apa katanya? \"Silakan\" kita pergi?"
  },
  AvgDialog_13056_Content_14 = {
    Text = "Hahahahahaha, lucu sekali! Pantas saja kadipaten begitu mudah dikalahkan, ternyata membawa anak-anak bermain rumah-rumahan ksatria."
  },
  AvgDialog_13056_Content_15 = {
    Text = "Kecilkan suaramu, telingaku sakit mendengarnya."
  },
  AvgDialog_13056_Content_16 = {
    Text = "Bintara itu mengabaikan peringatan Ogier, berjalan ke depan pintu kamar tidur, dan memandang rendah ke arah Ogier."
  },
  AvgDialog_13056_Content_17 = {Text = "Minggir."},
  AvgDialog_13056_Content_18 = {
    Text = "Ogier dengan susah payah mengangkat tombaknya secara horizontal, berusaha menghalangi langkah bintara itu."
  },
  AvgDialog_13056_Content_19 = {
    Text = "Silakan pergi!"
  },
  AvgDialog_13056_Content_2 = {
    Text = "Sepatu baja dengan percikan api dan debu menginjak karpet istana."
  },
  AvgDialog_13056_Content_20 = {
    Text = "Kau tahu, senjata ksatria tidak cocok untukmu."
  },
  AvgDialog_13056_Content_22 = {
    Text = [[
Perlawanan di hadapan perbedaan kekuatan yang mutlak, sungguh sia-sia.
Bintara itu dengan mudah menyingkirkan tombak Ogier, dan menghujamkan sebilah belati ke dadanya.]]
  },
  AvgDialog_13056_Content_23 = {
    Text = "Uhuk——!"
  },
  AvgDialog_13056_Content_24 = {
    Text = [[
Lihat? Inilah teknik yang seharusnya kau pelajari.
Lagipula setelah negara hancur, kalian hanya pantas tinggal di gang-gang gelap yang tak tersentuh cahaya.]]
  },
  AvgDialog_13056_Content_25 = {
    Text = "Mencuri, kelaparan, saling membenci… itulah akhir kalian.\nTombak yang melambangkan kehormatan ksatria ini, tentu saja tidak ada gunanya lagi bagimu di masa depan."
  },
  AvgDialog_13056_Content_26 = {
    Text = "Darah membanjiri tenggorokan, membawa rasa sakit yang menyesakkan, seperti tenggelam di daratan, setiap tarikan napas menyemburkan bau darah."
  },
  AvgDialog_13056_Content_27 = {
    Text = [[
Kau ingin melompat dari balik meja rendah, ingin mendorong bintara di tepi tangga itu jatuh ke bawah, ingin melindungi Ogier yang berlutut di depan pintu.
Tapi tubuh ini tiba-tiba gemetar dan kaku, tidak lagi mau menuruti perintahmu.]]
  },
  AvgDialog_13056_Content_28 = {
    Text = "Tidak… uhuk……"
  },
  AvgDialog_13056_Content_29 = {
    Text = "Ada satu hal yang salah kukatakan — kau sudah tak akan bisa melihat masa depan itu lagi. Kau akan bernasib sama seperti orang ini, menjadi kayu bakar yang menyulut istana ini."
  },
  AvgDialog_13056_Content_3 = {
    Text = "Ini adalah karpet favoritmu dalam \"Mimpi Kenangan\". Kau dan dayang yang cerewet menghabiskan satu sore penuh memilihnya di gudang Adipati Agung, lalu menghabiskan setengah hari lagi untuk menggelarnya hingga serapi sekarang."
  },
  AvgDialog_13056_Content_30 = {
    Text = "Sepatu baja menginjak keras tubuh Fernando, suara benturan logam berdentang-dentang, dan di antaranya terdengar bunyi tulang yang patah,"
  },
  AvgDialog_13056_Content_31 = {
    Text = "…Fernan……"
  },
  AvgDialog_13056_Content_33 = {
    Text = "Setiap otot di tubuhnya dikendalikan adrenalin, membuatnya mengangkat tombak dan menerjang ke arah musuh!"
  },
  AvgDialog_13056_Content_34 = {
    Text = "<Big:Jangan sentuh dia!>"
  },
  AvgDialog_13056_Content_36 = {Text = "Ugh——!"},
  AvgDialog_13056_Content_37 = {
    Text = "Perlawanan itu sia-sia. Serangannya tak mampu menggoyahkan sang sersan, malah justru mengekspos punggungnya kepada pengintai."
  },
  AvgDialog_13056_Content_38 = {
    Text = "Anak ini benar-benar keras kepala. Kalau dari awal dia kabur, kita juga tak sempat mengejarnya, kan?"
  },
  AvgDialog_13056_Content_39 = {
    Text = [[
Adik kecil, melihat betapa kerasnya kau bertahan, jangan-jangan kau sedang melindungi sesuatu?
Apa sang putri ada di balik pintu itu?]]
  },
  AvgDialog_13056_Content_4 = {
    Text = "Sang Putri yang jarang keluar kamar, bersandar di pagar koridor lantai dua, dengan santai memandangi kalian sibuk di aula besar, sementara Ogier yang datang menghadap begitu gugup sampai tidak tahu harus melangkahkan kaki ke mana."
  },
  AvgDialog_13056_Content_40 = {
    Text = "Darah mengalir keluar dari telinganya. Augier sudah tak bisa mendengar setiap kata dengan jelas, tapi ia masih menangkap satu kata yang paling penting."
  },
  AvgDialog_13056_Content_41 = {
    Text = "Tidak…pergi……"
  },
  AvgDialog_13056_Content_42 = {
    Text = "Pandangannya mulai memutih dari tepi, sebuah kekuatan sedang menarik kesadarannya keluar dari tubuh yang masih belia itu."
  },
  AvgDialog_13056_Content_43 = {
    Text = "Ia merangkak ke depan, melewati jasad Fernando, melewati sepatu bot sang sersan dan pengintai, hingga akhirnya jari-jarinya menyentuh pintu kayu yang tebal itu."
  },
  AvgDialog_13056_Content_44 = {
    Text = [[
Teksturnya halus dan hangat, dengan aroma kayu yang sedikit menyengat hidung. Suara yang lembut dan penuh perhatian sering terdengar dari balik pintu ini.
Namun kini, selain detak jam air yang berputar, tak ada suara sedikit pun dari balik pintu.]]
  },
  AvgDialog_13056_Content_45 = {
    Text = "Pergi…dari sini……"
  },
  AvgDialog_13056_Content_46 = {
    Text = "<Big:AAAAAHH————!>"
  },
  AvgDialog_13056_Content_47 = {
    Text = "Kali ini yang menancap menembus daging dan kulitnya, adalah tombaknya sendiri."
  },
  AvgDialog_13056_Content_48 = {
    Text = "Senjata yang telah diejek oleh banyak orang, diremehkan oleh musuh, namun tak pernah sekalipun ia lepaskan dari genggamannya."
  },
  AvgDialog_13056_Content_49 = {
    Text = "Ujung tombak menembus tubuhnya, memakunya ke pintu, tak bisa bergerak."
  },
  AvgDialog_13056_Content_5 = {
    Text = "Itu bukan ksatria Kadipaten… Cepat bersembunyi!"
  },
  AvgDialog_13056_Content_50 = {
    Text = "Aduh — jangan sekejam itu dong.\nKalau menyiksa ksatrianya seperti ini, bagaimana kalau \"Putri Penyihir\" mengutuk kita?"
  },
  AvgDialog_13056_Content_51 = {
    Text = "Penyihir? Menggelikan."
  },
  AvgDialog_13056_Content_52 = {
    Text = "<Small:@1Putri… bukan……>"
  },
  AvgDialog_13056_Content_53 = {
    Text = "Ogier membuka mulutnya, nama sang putri sudah di ujung lidah, tetapi bagaimanapun juga tidak bisa diucapkan."
  },
  AvgDialog_13056_Content_55 = {
    Text = "Dia mendengar suara aliran air, apakah jam air terjatuh? Apakah itu berarti……@1Putri masih hidup?"
  },
  AvgDialog_13056_Content_56 = {
    Text = "<Small:Tidak boleh……jangan keluar…tidak……masuk……>"
  },
  AvgDialog_13056_Content_57 = {
    Text = "Cukup……Ogier…terima kasih……"
  },
  AvgDialog_13056_Content_58 = {
    Text = "Terima kasih…milikku……"
  },
  AvgDialog_13056_Content_59 = {
    Text = "Dari celah pintu, beberapa aliran air hitam merembes keluar terlebih dahulu, bercampur dengan darah Ogier, tampak persis seperti air mata yang mengalir untuk seseorang."
  },
  AvgDialog_13056_Content_6 = {
    Text = "Tunggu! Bagaimana denganmu?!"
  },
  AvgDialog_13056_Content_60 = {
    Text = "Kemudian, gelombang dahsyat bagaikan banjir besar menghantam celah pintu hingga retak. Mengaum dan bergelora, seketika menenggelamkan istana peristirahatan."
  },
  AvgDialog_13056_Content_61 = {
    Text = "<Shake:Ugh——ugh!>"
  },
  AvgDialog_13056_Content_62 = {
    Text = "Wabah yang tak terlihat oleh orang biasa menerjang kedua orang itu, cairan hitam pekat masuk melalui panca indra, menenggelamkan mereka di udara."
  },
  AvgDialog_13056_Content_63 = {
    Text = "<Shake:Kutukan, ini kutu——>"
  },
  AvgDialog_13056_Content_65 = {
    Text = "Penjaga Rahasia? Bangun, Penjaga Rahasia? %player%?"
  },
  AvgDialog_13056_Content_66 = {Text = "Ogier!"},
  AvgDialog_13056_Content_67 = {
    Text = "Mimpi buruk? Coba lihat baik-baik, aku ini siapa."
  },
  AvgDialog_13056_Content_68 = {
    Text = "……Dor? Kenapa kamu ada di kamarku?"
  },
  AvgDialog_13056_Content_69 = {
    Text = "Aku tidak peduli isi mimpi burukmu, tapi semalam gelombang mentalmu aktif seperti sedang berdansa."
  },
  AvgDialog_13056_Content_7 = {
    Text = [[
Ogier mendorongmu dengan keras, menjejalkanmu ke bawah meja rendah.
Sudut pandangmu berputar-putar, dan akhirnya kau hanya bisa melihat karpet Persia yang mewah itu tepinya melengkung terbakar oleh api.]]
  },
  AvgDialog_13056_Content_70 = {
    Text = "Entitas Kebangkitan yang terhubung denganmu, termasuk aku, sedikit banyak merasakan kejanggalan."
  },
  AvgDialog_13056_Content_71 = {
    Text = "Semalam? ……Ternyata baru satu malam berlalu, jadi itu benar-benar hanya mimpi……"
  },
  AvgDialog_13056_Content_72 = {
    Text = "Kamu menggambarkan segala sesuatu dari mimpi absurd itu kepada Doer.\nPutri, ksatria, wabah penyakit……"
  },
  AvgDialog_13056_Content_73 = {
    Text = "Di antara para penyelidik yang mempertahankan tautan dengan Awakened, sesekali ada kasus di mana ingatan dan emosi beresonansi dengan Awakened. Tapi fenomena yang kamu gambarkan ini…… belum pernah kudengar sebelumnya."
  },
  AvgDialog_13056_Content_74 = {
    Text = "Sejauh ini, \"memasuki mimpi\" ini tampaknya tidak memberikan pengaruh lebih lanjut padamu. Aku akan terus memantau gelombang mentalmu dengan cermat."
  },
  AvgDialog_13056_Content_75 = {
    Text = "……Mungkin, sekarang kamu ingin pergi menemui Augier?"
  },
  AvgDialog_13056_Content_76 = {
    Text = "Sensasi ditelan oleh cairan Erosi terasa terlalu nyata. Sinar matahari pagi menyinari selimut, tubuh yang seharusnya merasakan kehangatan justru terasa seperti terperosok ke dalam jurang es."
  },
  AvgDialog_13056_Content_77 = {
    Text = "Augier dia… benar, aku sudah berjanji dengannya untuk melanjutkan latihan hari ini……"
  },
  AvgDialog_13056_Content_78 = {
    Text = "Universitas Misagor — Lapangan Latihan\nPagi Hari"
  },
  AvgDialog_13056_Content_79 = {
    Text = "Uwaa—— jangan jangan jangan, aku bisa mati——"
  },
  AvgDialog_13056_Content_8 = {
    Text = "Cuma ada anak kecil ini? Kita tidak salah tempat, kan?"
  },
  AvgDialog_13056_Content_80 = {
    Text = "Lepaskan aku, kasihanilah reporter kecil yang malang ini, Tuan Augier——"
  },
  AvgDialog_13056_Content_81 = {
    Text = [[
Nona Hannah, bertahanlah sedikit lagi, tinggal satu putaran lagi dan selesai.
Kali ini Anda pasti bisa lulus tes fisik!]]
  },
  AvgDialog_13056_Content_82 = {
    Text = "Huhu…… baiklah……"
  },
  AvgDialog_13056_Content_83 = {
    Text = [[
Sang makelar kampus mengikatkan karung pasir pemberat di betisnya, sambil merengek-rengek berlari pelan mengelilingi lapangan latihan.
Augier berlari kecil mengikutinya sambil terus menyemangatinya, tampak santai tanpa terengah-engah sedikit pun.]]
  },
  AvgDialog_13056_Content_84 = {Text = "Ogier"},
  AvgDialog_13056_Content_85 = {
    Text = "Penjaga Rahasia!"
  },
  AvgDialog_13056_Content_86 = {
    Text = "Dia menyerahkan tugas mengawasi Hannah kepada staf lain, lalu berlari menghampirimu."
  },
  AvgDialog_13056_Content_87 = {
    Text = "Bukankah Anda bilang latihan kita baru dimulai setelah tengah hari? Kenapa datang sepagi ini?"
  },
  AvgDialog_13056_Content_88 = {
    Text = "Dia dan para siswa serta Awakened lainnya sudah berada di lapangan latihan sepanjang pagi, namun sama sekali tidak menunjukkan tanda-tanda kelelahan. Saat menatapmu, matanya masih penuh rasa hormat dan semangat."
  },
  AvgDialog_13056_Content_89 = {Text = "Aku..."},
  AvgDialog_13056_Content_9 = {
    Text = "Tidak salah, peta strategis sudah menunjukkan dengan jelas, ini adalah istana peristirahatan untuk para wanita bangsawan."
  },
  AvgDialog_13056_Content_90 = {
    Text = "……Setelah latihan Hannah selesai, ayo kita jalan-jalan ke pusat kota Londinium."
  },
  AvgDialog_13056_Content_91 = {Text = "Eh?"},
  AvgDialog_13056_Content_92 = {
    Text = "Augier jelas tidak menyangka kamu akan tiba-tiba mengusulkan untuk beristirahat, bahkan kamu sendiri pun tidak menduganya."
  },
  AvgDialog_13056_Content_93 = {
    Text = "Tuanku, izinkan saya menolak. Krisis Erosi sudah di depan mata, saya…… saya yang sekarang, belum siap."
  },
  AvgDialog_13056_Content_94 = {
    Text = "Dibanding bersenang-senang, aku ingin lebih fokus mengasah kemampuan bela diri."
  },
  AvgDialog_13056_Content_95 = {
    Text = "Kalau begitu, biar kuubah cara bicaraku."
  },
  AvgDialog_13056_Content_96 = {
    Text = "Sore hari yang dihabiskan bersamanya di ordo ksatria tiba-tiba muncul di benakmu, kenangan tertentu yang kaukira akan terlupakan saat terbangun dari mimpi kini muncul ke permukaan."
  },
  AvgDialog_13056_Content_97 = {
    Text = "Sekarang adalah saatnya mewujudkan keinginan itu, Tuan Ksatria."
  },
  AvgDialog_13056_Content_98 = {Text = "!?"},
  AvgDialog_13056_Content_99 = {
    Text = "A-Anda, bagaimana Anda bisa tahu?!"
  },
  AvgDialog_130571_Content_1 = {
    Text = "Bang! ————"
  },
  AvgDialog_130571_Content_10 = {
    Text = "Ah, ah... Bola arang kecil, maaf... Mosk, tertahan."
  },
  AvgDialog_130571_Content_11 = {
    Text = "Tidak ada, cuma Mosk, bagaimana bisa kamu tiba-tiba masuk?"
  },
  AvgDialog_130571_Content_12 = {
    Text = "Ah! Mosk, panas! Peluk bola arang kecil, nyaman!"
  },
  AvgDialog_130571_Content_13 = {
    Text = "Mosk, aneh, karena, tidak dingin lagi."
  },
  AvgDialog_130571_Content_14 = {
    Text = "Tapi, sangat panas, sangat panas…"
  },
  AvgDialog_130571_Content_15 = {
    Text = "(Aduh, apakah ini pengaruh dari Sungai Suci?)"
  },
  AvgDialog_130571_Content_16 = {
    Text = "Mosk, tidak tahu…"
  },
  AvgDialog_130571_Content_17 = {
    Text = "Mosk semakin kehilangan arah, jari-jari halusnya meraih dari celah pakaianmu, dengan lembut membelai kulitmu."
  },
  AvgDialog_130571_Content_18 = {
    Text = "Kamu sangat akrab dengan perasaan ini, dalam mimpi itu, \"Bola arang kecil\" kadang-kadang akan menikmati layanan menyisir bulu ini di pelukan Mosk."
  },
  AvgDialog_130571_Content_19 = {
    Text = "Bola arang kecil, memeluk, tenang~"
  },
  AvgDialog_130571_Content_2 = {
    Text = "Bola arang kecil, peluk-peluk——"
  },
  AvgDialog_130571_Content_20 = {
    Text = "Bola arang kecil, aroma, harum~"
  },
  AvgDialog_130571_Content_21 = {
    Text = "Mosk perlahan mencium tubuhmu, dan kamu tidak yakin apakah itu aroma yang tersisa di tubuhmu, ataukah keistimewaan dirimu yang membuat Mosk merasa tenang."
  },
  AvgDialog_130571_Content_22 = {
    Text = "Tapi kamu mengerti, kamu tidak bisa membiarkan Mosk terus seperti ini."
  },
  AvgDialog_130571_Content_23 = {
    Text = "Lantainya kasar, pinggangmu mengeluarkan protes, ia merindukan tempat tidur yang lembut."
  },
  AvgDialog_130571_Content_24 = {
    Text = "Jadi malam ini peluk aku, mari kita tidur bersama?"
  },
  AvgDialog_130571_Content_25 = {
    Text = "Hmm! Bola arang kecil, suka! Ingin peluk!"
  },
  AvgDialog_130571_Content_26 = {
    Text = "Peluk bola arang kecil, tidur, tidur~"
  },
  AvgDialog_130571_Content_27 = {
    Text = "Kamu mengikuti alur dan berbaring di atas tempat tidur yang lembut bersama Mosk, berpelukan, saling menatap, seperti saat di atas kapal dulu."
  },
  AvgDialog_130571_Content_28 = {
    Text = "Mosk, tidak panas lagi~ Mosk, sangat nyaman~"
  },
  AvgDialog_130571_Content_29 = {
    Text = "Selamat malam…zzz…Bola arang kecil…zzz"
  },
  AvgDialog_130571_Content_3 = {
    Text = "Mosk, Mosk?"
  },
  AvgDialog_130571_Content_4 = {
    Text = "Mosk tiba-tiba berlari ceria masuk ke dalam kamar, kedua tangannya melingkar di pinggangmu, rambut panjang peraknya terus-menerus menggesek di dadamu."
  },
  AvgDialog_130571_Content_5 = {
    Text = "Kau diam-diam bersyukur bahwa dia sudah menyimpan terlebih dahulu \"benda mengerikan\" yang menempel di tangan kirinya, sehingga kau tidak perlu menanggung risiko tiba-tiba digigit."
  },
  AvgDialog_130571_Content_6 = {
    Text = "Bola arang kecil, nyaman——"
  },
  AvgDialog_130571_Content_7 = {
    Text = "Mosk, tunggu, sebentar, ah——"
  },
  AvgDialog_130571_Content_8 = {Text = "Dong."},
  AvgDialog_130571_Content_9 = {
    Text = "Sayang sekali, seperti yang kamu duga, Mosk tidak bisa mengendalikan kekuatannya dengan baik, dan kalian jatuh bersama ke tanah."
  },
  AvgDialog_131200_Content_1 = {
    Text = "Belenggu yang Lembut"
  },
  AvgDialog_131200_Content_10 = {
    Text = "Arachne mengelus setengah wajah perempuan yang tersisa. Saat dia dengan lembut menutup mata perempuan itu, tiang lampu raksasa di belakangnya mengeluarkan cahaya samar."
  },
  AvgDialog_131200_Content_11 = {
    Text = "Arachne mengulurkan tangannya. Sedikit abu sisa yang tersisa di tiang lampu seperti pasir halus yang diterbangkan oleh angin, berputar-putar di sekitar jari-jarinya yang ramping, mengalir, lalu jatuh ke tanah."
  },
  AvgDialog_131200_Content_12 = {
    Text = "Dimensi Abu sisa yang tersisa......persepsi kita tidak salah, ini dulunya adalah tempat Nefraea menyembunyikan abu sisa, tetapi sekarang, abu sisa telah dibawa pergi olehnya."
  },
  AvgDialog_131200_Content_13 = {
    Text = "Bawa pergi abu sisa, bunuh misteri pasangan, Nefraea sebenarnya ingin melakukan apa......"
  },
  AvgDialog_131200_Content_14 = {Text = "Hm?"},
  AvgDialog_131200_Content_15 = {
    Text = "Sepertinya terkejut oleh sesuatu, Arachne mengangkat kepalanya, menatap ke arah peron yang tidak jauh melalui jendela kaca patri yang bergambar lambang lentera."
  },
  AvgDialog_131200_Content_16 = {
    Text = "Arachne? Ada apa denganmu?"
  },
  AvgDialog_131200_Content_17 = {
    Text = "Nafas dari tubuh ini... saya tidak bisa merasakannya lagi."
  },
  AvgDialog_131200_Content_18 = {Text = "!!!"},
  AvgDialog_131200_Content_19 = {
    Text = "Apakah maksudmu, kamu sudah pergi dari teater?"
  },
  AvgDialog_131200_Content_2 = {
    Text = "Jari, betis, bola mata, tulang rusuk, kepala … Tuan memotong boneka tercintanya dan melemparkannya ke dalam lendir dan darah segar."
  },
  AvgDialog_131200_Content_20 = {
    Text = "Saat kami mencari kesempatan rahasia, tubuhku sedang membersihkan para pelayan Abyss di sepanjang benang kota. Setelah mengetahui keberadaan \"kenangan\", dia pergi ke gereja untuk menjemput kami."
  },
  AvgDialog_131200_Content_21 = {
    Text = "Aromanya sudah sangat dekat... tapi sekarang, aroma itu telah menghilang."
  },
  AvgDialog_131200_Content_22 = {
    Text = "Apakah dia... mengalami sesuatu yang tidak terduga? Tapi \"Memori\" baru saja mati, bagaimana mungkin..."
  },
  AvgDialog_131200_Content_23 = {
    Text = "Apa yang sebenarnya terjadi, saya tidak tahu. Namun sebelum menghilang, dia menyentuh jaringan yang menghubungkan saya. Selain instruksi untuk kembali, pesan terakhir yang dia tinggalkan adalah sebuah kata."
  },
  AvgDialog_131200_Content_24 = {
    Text = "\"Kesukacitaan\"."
  },
  AvgDialog_131200_Content_25 = {
    Text = "Kesukacitaan…?"
  },
  AvgDialog_131200_Content_26 = {
    Text = "Di hadapanmu muncul senyuman menjijikkan dari N."
  },
  AvgDialog_131200_Content_27 = {
    Text = "Saya tidak mengerti... kalian memiliki ingatan yang sama, pasti kamu tahu maksud yang ingin dia sampaikan."
  },
  AvgDialog_131200_Content_28 = {
    Text = "Arachne menggelengkan kepala perlahan."
  },
  AvgDialog_131200_Content_29 = {
    Text = "Takdirmu adalah seekor kupu-kupu yang tak boleh kusentuh sembarangan, segala penjelasan akan menimbulkan konsekuensi yang tak terukur."
  },
  AvgDialog_131200_Content_3 = {
    Text = "\"Kenangan\"……"
  },
  AvgDialog_131200_Content_30 = {
    Text = "Namun, kamu harus tahu, dalam masa depan singkatmu, \"Kesukacitaan\" adalah sebuah kunci, yang akan membuka rahasia yang kamu hadapi."
  },
  AvgDialog_131200_Content_31 = {
    Text = "Takdirku? Maksudmu, sekarang kau bisa melihat benang takdirku?!"
  },
  AvgDialog_131200_Content_32 = {
    Text = "Kau menatap matanya. Dalam senyuman lembut itu, kau melihat keagungan takdir yang tak terbantahkan."
  },
  AvgDialog_131200_Content_33 = {
    Text = "……Apa pun yang terjadi, percayalah padaku, dan percayalah pada dirimu sendiri."
  },
  AvgDialog_131200_Content_34 = {
    Text = "Kembalilah ke Teater Takdir. Kunci dan gemboknya menunggumu di sana, Penjaga Rahasia {Male=先生,Female=小姐}."
  },
  AvgDialog_131200_Content_35 = {Text = "Tapi..."},
  AvgDialog_131200_Content_36 = {
    Text = "Suara tenang Arachne seperti matahari sore yang hangat di musim gugur. Sosoknya berubah menjadi segenggam jaring laba-laba, menghilang dalam cahaya lampu gereja yang sepi."
  },
  AvgDialog_131200_Content_37 = {
    Text = "Di bawah pantulan warna-warni jendela kaca, hanya tersisa bara dimensi yang melayang di atas genangan darah dan potongan tubuh."
  },
  AvgDialog_131200_Content_38 = {
    Text = "\"Kesukacitaan\"……"
  },
  AvgDialog_131200_Content_39 = {
    Text = "Kamu mengucapkan kata yang tidak jelas itu dalam hati, lalu menoleh dan melihat sisa tubuh yang disebut \"kenangan\"."
  },
  AvgDialog_131200_Content_4 = {
    Text = "Kamu dengan lembut mengambil fragmen tubuh gadis itu, lendir dan darah segar yang menempel di anggota tubuhnya membasahi pakaianmu."
  },
  AvgDialog_131200_Content_40 = {
    Text = "Mereka bermandikan cairan keruh dan cahaya suci, menyatu dengan gereja kudus ini, tak terpisahkan."
  },
  AvgDialog_131200_Content_42 = {
    Text = "Jalan yang terjalin seperti jaring laba-laba bergetar lembut, diterangi oleh cahaya redup di atas panggung. Saat kamu menginjak jaring laba-laba itu, semua boneka berhentiPertunjukan."
  },
  AvgDialog_131200_Content_43 = {
    Text = "Semua orang di semua dimensi, menatapmu. Mereka penasaran, mereka bersemangat, mereka gembira dan penuh rasa hormat."
  },
  AvgDialog_131200_Content_44 = {
    Text = "Ini adalah upacara sambutan yang megah dan tenang. Tak terhitung banyaknya aktor menjadi penonton, satu-satunya penonton menjadi tokoh utama."
  },
  AvgDialog_131200_Content_45 = {
    Text = "Mungkin mendengarkan kata-kata Arachne bukanlah ide yang baik..."
  },
  AvgDialog_131200_Content_46 = {
    Text = "Kamu secara diam-diam menggenggam kunci perak, berjalan sendirian melewati kesunyian yang padat dan aneh ini."
  },
  AvgDialog_131200_Content_47 = {
    Text = "Pemilik baru teater telah menunggumu sejak lama, Penjaga Rahasia {Male=先生,Female=小姐}."
  },
  AvgDialog_131200_Content_48 = {
    Text = "Bayangan berkumpul di atas panggung yang tinggi. Hampir sebagai respons naluriah, kamu cepat-cepat bersandar ke belakang dan mengangkat kunci perak di depan tubuhmu."
  },
  AvgDialog_131200_Content_49 = {
    Text = "Pemilik baru?"
  },
  AvgDialog_131200_Content_5 = {
    Text = "Mungkin... mungkin masih ada cara untuk menyelamatkannya... kekuatan plasmid... perbaikan nasib..."
  },
  AvgDialog_131200_Content_50 = {
    Text = "Selamat datang kembali di teater, Penjaga Rahasia {Male=先生,Female=小姐}."
  },
  AvgDialog_131200_Content_51 = {
    Text = "Arachne, kamu......"
  },
  AvgDialog_131200_Content_52 = {
    Text = "Maaf, cerita baru kami ini membutuhkan partisipasimu."
  },
  AvgDialog_131200_Content_53 = {
    Text = "Jaring laba-laba bergetar lembut. Pemilik teater yang berjalan perlahan mendekatimu, suaranya tetap hangat seperti senja."
  },
  AvgDialog_131200_Content_54 = {
    Text = "Di panggung di sekitarmu, boneka-boneka yang sama persis dengan pelayan laba-laba dingin berbalik tubuh dan melompat serentak ke arahmu…"
  },
  AvgDialog_131200_Content_55 = {Text = "!!!"},
  AvgDialog_131200_Content_6 = {
    Text = "Nefraea telah menghancurkan benangnya... nasibnya telah berakhir, Penjaga {Male=Tuanku, Female=Nyonyaku}."
  },
  AvgDialog_131200_Content_7 = {
    Text = "Suara roda penggulung masih tenang dan jauh."
  },
  AvgDialog_131200_Content_8 = {
    Text = "\"Kenangan\" juga dibunuh olehnya, apakah ini berarti……"
  },
  AvgDialog_131200_Content_9 = {
    Text = "Nefraea, telah memiliki kekuatan untuk mengubah nasib panggung ini."
  },
  AvgDialog_131201_Content_1 = {
    Text = "Huh... Pelayan Nefraea ini memang susah dihadapi..."
  },
  AvgDialog_131201_Content_10 = {
    Text = "Dua puluh hari kemudian, dia akan mulai mempelajari dengan serius apa yang tercatat dalam buku ini... Saat itu tiba, panggung ini akan menyambut nasib kehancuran yang tidak dapat dihindari, sama seperti panggung-panggung lainnya."
  },
  AvgDialog_131201_Content_100 = {
    Text = "Pangeran dan istrinya duduk di kursi belakang mobil terbuka, menikmati kota kuno ini. Orang-orang berlari mengikuti di belakang mobil, menuju nasib yang telah ditentukan untuk mereka."
  },
  AvgDialog_131201_Content_11 = {
    Text = "Dunia yang baru saja kau sentuh namun terasa akrab ini bergejolak dalam benakmu. Kau belum pernah melihat dunia yang begitu indah dan makmur."
  },
  AvgDialog_131201_Content_12 = {
    Text = "Kamu telah mengalami terlalu banyak, Pelarutan menutupi pemandangan yang gersang itu dengan mudah, memenuhi dunia yang megah ini, dan memenuhi imajinasimu."
  },
  AvgDialog_131201_Content_13 = {
    Text = "Arachne mengulurkan tangan, lembut menyentuh cahaya pagi yang jatuh di mulut gang. Dia sedang berkabung untuk dunia lain yang akan mati."
  },
  AvgDialog_131201_Content_14 = {
    Text = "Sebuah dunia yang tidak diperhatikan oleh Dewa... saya belum pernah memiliki imajinasi seperti ini sebelumnya."
  },
  AvgDialog_131201_Content_15 = {
    Text = "Apakah kita masih punya kesempatan untuk mengubah ini?"
  },
  AvgDialog_131201_Content_16 = {
    Text = "Inilah tujuan kami datang ke sini."
  },
  AvgDialog_131201_Content_17 = {
    Text = "Tolong beri tahu saya, apa yang harus saya lakukan?"
  },
  AvgDialog_131201_Content_18 = {
    Text = "Tunggu!……"
  },
  AvgDialog_131201_Content_19 = {
    Text = "Anda menyadarinya, Penjaga Rahasia {Male=先生,Female=小姐}."
  },
  AvgDialog_131201_Content_2 = {
    Text = "Kau bersandar di dinding gang tersembunyi ini, terengah-engah."
  },
  AvgDialog_131201_Content_20 = {
    Text = "Di luar gang, sekelompok orang dengan gelombang mental yang jelas berbeda dari orang biasa sedang mendekati arah kalian."
  },
  AvgDialog_131201_Content_21 = {
    Text = "Belakang, atas, depan… semakin banyak musuh muncul dalam persepsimu."
  },
  AvgDialog_131201_Content_22 = {
    Text = "Kami dikepung!…"
  },
  AvgDialog_131201_Content_23 = {
    Text = "Sejak datang ke panggung, saya telah memperbaiki nasib yang telah dimanipulasi. Namun, memperbaiki nasib begitu banyak orang bukanlah hal yang mudah."
  },
  AvgDialog_131201_Content_24 = {
    Text = "Nefraea meninggalkan orang-orang ini hanya untuk menghalangi saya memperbaiki nasib."
  },
  AvgDialog_131201_Content_25 = {
    Text = "Mungkin kita masih memiliki cara lain…"
  },
  AvgDialog_131201_Content_26 = {
    Text = "Arachne, Komite Pemulihan Negara hari ini merencanakan pembunuhan di sini, saya adalah salah satu pelaksananya."
  },
  AvgDialog_131201_Content_27 = {
    Text = "Dunia ini akan hancur karena Orang itu, Putra Mahkota, yang mempelajari buku sihir. Jika aku berhasil, mungkin aku bisa menghentikan hal ini terjadi"
  },
  AvgDialog_131201_Content_28 = {
    Text = "Ini tidak sepenuhnya benar..."
  },
  AvgDialog_131201_Content_29 = {
    Text = "Di sana! Tangkap mereka"
  },
  AvgDialog_131201_Content_3 = {
    Text = "Kamu tidak melihat Arachne yang berlari, dia berdiri tenang di sampingmu, seolah-olah dia ditakdirkan untuk berdiri di lorong kecil ini pada saat ini."
  },
  AvgDialog_131201_Content_30 = {
    Text = "Arachne memainkan senar, sedang mempersiapkan pelayan yang bermutasi terhenti di pintu gang, seperti sebuah patung."
  },
  AvgDialog_131201_Content_31 = {
    Text = "Suara terompet dan saksofon terdengar dari kejauhan, suara itu disertai dengan deru mobil, perlahan mendekat."
  },
  AvgDialog_131201_Content_32 = {
    Text = "Rencana pembunuhan sudah terbongkar, orang lain tidak bisa melakukan hal ini... Orang itu, sang pewaris tahta, sudah mendekat ke sini, jika tidak segera bertindak, akan terlambat"
  },
  AvgDialog_131201_Content_33 = {
    Text = "Arachne menatap mata kamu yang cemas, setelah ragu sejenak, ia perlahan mengangguk."
  },
  AvgDialog_131201_Content_34 = {
    Text = "Karena arah nasib adalah seperti ini... mungkin, mencoba membuat pilihan untuk dunia ini adalah hal yang seharusnya kamu lakukan."
  },
  AvgDialog_131201_Content_35 = {
    Text = "Lakukanlah apa yang ingin Anda lakukan, Penjaga Rahasia {Male=先生,Female=小姐}. Kebenaran takdir akan terungkap di sini untuk Anda."
  },
  AvgDialog_131201_Content_36 = {
    Text = "Kamu tidak punya waktu untuk memikirkan kata-kata Arachne dengan seksama, hanya mengangguk, dan dengan bantuan Arachne, melarikan diri dari gang kecil, bergabung dengan kerumunan yang mengalir deras."
  },
  AvgDialog_131201_Content_37 = {
    Text = "Itu Adipati Agung Flavian? Pewaris kekaisaran, berapa harga mobilnya itu..."
  },
  AvgDialog_131201_Content_38 = {
    Text = "Sial! Bajingan anak perampok itu! Setiap sen yang ada di sakunya adalah darah yang diperas dari tubuh kita!"
  },
  AvgDialog_131201_Content_39 = {
    Text = "Seandainya kakinya tidak pincang, aku pasti akan mati di medan perang yang menyerang sekelompok perampok ini"
  },
  AvgDialog_131201_Content_4 = {
    Text = "Setelah melakukan persiapan yang begitu matang... apa sebenarnya yang ingin dia lakukan?"
  },
  AvgDialog_131201_Content_40 = {
    Text = "Ssst! Di sini banyak penjaga kekaisaran, kamu tidak ingin hidup lagi?"
  },
  AvgDialog_131201_Content_42 = {
    Text = "Ketika kamu mendorong kerumunan orang yang padat dan akhirnya sampai di tepi jalan, mobil convertible baru itu perlahan melaju ke arahmu."
  },
  AvgDialog_131201_Content_43 = {
    Text = "Putra mahkota yang hampir berusia enam puluh tahun duduk di kursi belakang bersama istrinya, melambaikan tangan kepada kerumunan di sekitar sambil menunjuk-nunjuk bangunan bersejarah di Hervats."
  },
  AvgDialog_131201_Content_44 = {
    Text = "Bahkan dalam ingatanmu yang samar, kau tahu dengan jelas betapa beratnya luka yang ditimbulkan keluarga kerajaan era ini kepada tanah ini."
  },
  AvgDialog_131201_Content_45 = {
    Text = "Khawatir akan dampak buruk yang mungkin ditimbulkan bagi dunia ini, kamu menghentikan tanganmu yang secara tidak sadar meraih kunci perak, mengeluarkan pistol yang seharusnya ada di sana dari saku, mendekati kendaraan yang melaju perlahan."
  },
  AvgDialog_131201_Content_46 = {
    Text = "Hei! Pelajar itu! Kamu tidak boleh mendekat…"
  },
  AvgDialog_131201_Content_47 = {
    Text = "Maaf, Yang Mulia, sejak aku sudah berdiri di atas panggung, aku harus menyelesaikan apa yang harus dilakukan oleh karakter ini"
  },
  AvgDialog_131201_Content_48 = {
    Text = "Brak brak brak——"
  },
  AvgDialog_131201_Content_49 = {
    Text = "Di jalanan yang kacau ini, pewaris kekaisaran yang bangga tidak dikelilingi oleh langkah keamanan yang ketat seperti yang kamu bayangkan. Berkat pelatihan yang ketat, kamu dengan mudah mendekati kendaraan dan menarik pelatuknya."
  },
  AvgDialog_131201_Content_5 = {
    Text = "Nefraea meninggalkan sebuah pengantar. Di jaring takdir yang besar di dunia ini, dia mencemari salah satu benangnya."
  },
  AvgDialog_131201_Content_50 = {
    Text = "Ketika tiga peluru menembus tepat dada sang pangeran, seluruh dunia terhenti."
  },
  AvgDialog_131201_Content_51 = {
    Text = "Pangeran yang menderita, permaisuri yang terkejut, dan penjaga yang berlari, semuanya tiba-tiba berhenti dengan cara yang konyol, seperti lukisan cat minyak yang hidup."
  },
  AvgDialog_131201_Content_52 = {
    Text = "(!!! Ini adalah...)"
  },
  AvgDialog_131201_Content_53 = {
    Text = "Setelah jeda singkat, warna-warna lukisan minyak mulai mengalir dan terjerat, waktu dan gravitasi ikut bergabung dalam pesta kacau ini, tubuhmu terjepit, dan tak terhitung banyaknya gambar melintas di depan matamu."
  },
  AvgDialog_131201_Content_54 = {
    Text = "Pemakaman putra mahkota. Murka sang raja. Perang. Meriam. Kematian. Terompet prajurit, tangisan rakyat. Burung nasar hinggap di medan perang Verdun yang merah darah, menggerogoti empat ratus ribu jasad yang hancur lebur."
  },
  AvgDialog_131201_Content_55 = {
    Text = "Kehancuran kekaisaran, tanah yang dibagi, raja yang terpuruk, buku sihir yang dibuka kembali…"
  },
  AvgDialog_131201_Content_56 = {
    Text = "Cairan hitam yang kental sesaat menelan bidang pandangmu. Cerita yang kau kenal itu terulang kembali, kegelapan yang total dan rasa sakit, mengikis setiap sel dalam dirimu…"
  },
  AvgDialog_131201_Content_57 = {
    Text = "Tidak perlu khawatir, Anda sudah aman, Penjaga Rahasia {Male=先生,Female=小姐}."
  },
  AvgDialog_131201_Content_58 = {
    Text = "Sebuah tangan bertumpu di bahumu. Lukisan kacau dan kegelapan tak berujung lenyap dari pandanganmu."
  },
  AvgDialog_131201_Content_59 = {
    Text = "Kau membuka mata dengan terkejut. Kafe masih tenang seperti semula, pistol Browning di pelukanmu telah lenyap, dan kue Sacher yang baru saja dihidangkan mengeluarkan aroma yang menggoda."
  },
  AvgDialog_131201_Content_6 = {
    Text = "Dalam takdir yang telah tercemar, putra mahkota Kekaisaran Fio menemukan sebuah buku dua bulan yang lalu."
  },
  AvgDialog_131201_Content_60 = {
    Text = "Arachne... ini... apa yang terjadi?! Kami..."
  },
  AvgDialog_131201_Content_61 = {
    Text = "Jangan panik, kita sudah kembali ke saat baru masuk kafe. Kabar baiknya adalah, kita mendapatkan secangkir kopi gratis."
  },
  AvgDialog_131201_Content_62 = {
    Text = "Arachne mengangkat cangkir kopi, tersenyum dan meneguk sedikit. Di atas cairan cokelat, terpantul wajahmu yang terkejut."
  },
  AvgDialog_131201_Content_63 = {
    Text = "Benang nasib bukanlah sesuatu yang bisa kamu lihat dengan jelas. Para aktor dari luar panggung yang memaksa mengubah nasib dunia ini, akan tersesat dalam jaring nasib."
  },
  AvgDialog_131201_Content_64 = {
    Text = "Masa lalu dan masa depan—ketika takdir-takdir tak terhitung dari panggung ini terjalin di matamu, itulah pemandangan Jaring Takdir."
  },
  AvgDialog_131201_Content_65 = {
    Text = "Nasib di masa depan... maksudmu, semua yang baru saja terjadi, itu semua benar? Perang-perang itu, kematian... semua itu disebabkan olehku?"
  },
  AvgDialog_131201_Content_66 = {
    Text = "Takdir membuatmu menyaksikan semua ini. Setelah pembunuhan putra mahkota, semua ini memang seharusnya terjadi. Namun jangan khawatir, Penjaga Rahasia {Male=先生,Female=小姐}. Takdir panggung ini telah kurajut ulang."
  },
  AvgDialog_131201_Content_67 = {
    Text = "Kamu melihat ke luar jendela. Masih ramai kerumunan, tetapi warga dan petugas polisi yang terpengaruh oleh Nefraea sudah tidak ada lagi."
  },
  AvgDialog_131201_Content_68 = {
    Text = "Jika sesuai dengan cara saya tadi... jika kamu tidak memperbaiki takdir..."
  },
  AvgDialog_131201_Content_69 = {
    Text = "Satu bulan kemudian, dunia ini akan meletuskan perang terbesar dalam sejarah karena kematian Putra Mahkota ini. Delapan kerajaan terlibat, dua puluh juta orang akan mati dalam perang ini."
  },
  AvgDialog_131201_Content_7 = {
    Text = "Sebuah buku yang mencatat ilmu sihir misterius, yang dapat menghubungkan dewa yang tidak berasal dari dimensi ini."
  },
  AvgDialog_131201_Content_70 = {
    Text = "Tanah di bawah kaki kita akan berubah menjadi abu, orang-orang yang duduk di samping kita di kafe ini, tidak ada yang bisa selamat dari perang itu."
  },
  AvgDialog_131201_Content_71 = {
    Text = "Arachne menggoyangkan cangkir kopi, memandang pemandangan jalan yang ramai di luar jendela. Dia menceritakan dengan tenang, seolah sedang memperkenalkan sebuah makanan penutup yang sangat biasa."
  },
  AvgDialog_131201_Content_72 = {
    Text = "Suara ramai di jalanan membawa melodi ketenangan dan kemakmuran, masuk ke telingamu."
  },
  AvgDialog_131201_Content_73 = {
    Text = "Pelarutan, ya? Mengapa setelah aku membunuh pewaris tahta itu, dunia ini masih mendatangkan Pelarutan..."
  },
  AvgDialog_131201_Content_74 = {
    Text = "Dalam perang yang megah itu, kekaisaran ini mengalami kekalahan. Orang itu, yang sebelumnya harus menerima keputusan kejam dari nasib. Namun sekarang, dia memiliki pilihan baru."
  },
  AvgDialog_131201_Content_75 = {
    Text = "Sihir yang tidak berasal dari dunia ini, dewa yang melampaui segala kekuatan. Apa yang bisa lebih menarik bagi seorang ayah yang kehilangan anak, seorang raja yang kehilangan negaranya?"
  },
  AvgDialog_131201_Content_76 = {
    Text = "Kata-kata lembut Arachne membuatmu merinding. Berat dua miliar nyawa seolah menekanmu seperti benda nyata."
  },
  AvgDialog_131201_Content_77 = {
    Text = "<Shake:Aku tidak menyangka, membunuh seorang putra mahkota ternyata akan menyebabkan hal seperti ini... Aku mengira...>"
  },
  AvgDialog_131201_Content_78 = {
    Text = "Nasib membiarkanmu membuat pilihan ini, agar kamu bisa melihatnya dengan jelas. Kamu tidak bisa melihat benang-benang itu, tetapi sekarang kamu sudah mengerti, bagaimana benang-benang ini saling berjalin dengan cara yang rumit."
  },
  AvgDialog_131201_Content_79 = {
    Text = "Benang nasib menenun jaring raksasa, setiap getaran lembut dari benang mungkin akan membuat jaring nasib terbalik."
  },
  AvgDialog_131201_Content_8 = {
    Text = "Arachne mengangkat kepalanya, menatap benang-benang yang tidak bisa kau lihat."
  },
  AvgDialog_131201_Content_80 = {
    Text = "Inilah takdir——takdir yang begitu kompleks."
  },
  AvgDialog_131201_Content_81 = {
    Text = "Kamu menarik napas dalam-dalam sekali, menenangkan jantung yang berdetak kencang karena ketakutan."
  },
  AvgDialog_131201_Content_82 = {
    Text = "Syukurlah, syukurlah kamu berhasil menghentikan perang ini…"
  },
  AvgDialog_131201_Content_83 = {
    Text = "Saya tidak mencegah perang, Penjaga Rahasia {Male=先生,Female=小姐}."
  },
  AvgDialog_131201_Content_84 = {
    Text = "Arachne menggelengkan kepala dengan lembut."
  },
  AvgDialog_131201_Content_85 = {
    Text = "Dalam nasib baru, raja imperium akan melihat sebagian kecil mukjizat yang ditunjukkan dalam buku sihir. Kekuatan-kekuatan itu akan menjadi sandaran baginya untuk memulai perang."
  },
  AvgDialog_131201_Content_86 = {
    Text = "Raja dan sekutunya melancarkan perang yang lebih besar, beberapa kekaisaran di benua lain juga terlibat dalam perang ini."
  },
  AvgDialog_131201_Content_87 = {
    Text = "Orang-orang yang mati dalam perang ini adalah empat kali lipat dari yang awalnya."
  },
  AvgDialog_131201_Content_88 = {
    Text = "Dia bercerita dengan tenang, seolah sedang mendongengkan sebuah kisah lembut untuk anak yang belum bisa tidur."
  },
  AvgDialog_131201_Content_89 = {
    Text = "<Shake:I-ini... kenapa bisa begitu?>"
  },
  AvgDialog_131201_Content_9 = {
    Text = "Panggung ini tidak pernah terhubung dengan dewa, dalam waktu yang lama, ia seharusnya terhindar dari nasib terbalik akibat pelarutan."
  },
  AvgDialog_131201_Content_90 = {
    Text = "Kamu telah melihat kompleksitas jaring nasib. Memaksa untuk menghindari beberapa hal yang sudah ditentukan akan mengakibatkan bencana yang lebih serius."
  },
  AvgDialog_131201_Content_91 = {
    Text = "Sang raja tetap kalah. Pengetahuan terbatas dari buku itu tidak banyak membantu kekaisaran."
  },
  AvgDialog_131201_Content_92 = {
    Text = "Setelah kekalahan ini, ilmu sihir menjadi bahan lelucon, dan para penguasa di panggung ini tidak ada lagi yang menekuni hal tersebut."
  },
  AvgDialog_131201_Content_93 = {
    Text = "Pandangan mereka jatuh pada hal-hal lain. Mereka menganut ilmu pengetahuan, meneliti senjata yang dapat menelan planet, menikmati kedamaian sementara di bawah ancaman senjata-senjata ini, lalu dihancurkan oleh senjata yang mereka cipta sendiri."
  },
  AvgDialog_131201_Content_94 = {
    Text = "Panggung ini tetap akan musnah karena bencana lain—itu adalah takdir yang tak bisa dihindari. Namun mereka masih bisa menikmati masa kejayaan yang indah bagai karya seni."
  },
  AvgDialog_131201_Content_95 = {
    Text = "Pandangan Tohvapo untuk sementara tidak akan bisa jatuh ke tempat ini."
  },
  AvgDialog_131201_Content_96 = {
    Text = "Sendok Arachne berputar perlahan di dalam gelas, pusaran cokelat tua itu persis sama dengan apa yang kamu lihat di Jaring Takdir."
  },
  AvgDialog_131201_Content_97 = {
    Text = "Dia menundukkan kepalanya. Sinar matahari di luar jendela jatuh ke tubuhnya, seperti tirai kesedihan."
  },
  AvgDialog_131201_Content_98 = {
    Text = "Berjuang, merajut, menambal, namun tak bisa mengubah... Inilah takdir, Penjaga Rahasia {Male=先生,Female=小姐}."
  },
  AvgDialog_131201_Content_99 = {
    Text = "Suara terompet dan saksofon datang ke dekat jendela, disertai sorakan dan makian kerumunan yang perlahan menjauh."
  },
  AvgDialog_131202_Content_1 = {Text = "Pak—"},
  AvgDialog_131202_Content_10 = {
    Text = "Penganut?…"
  },
  AvgDialog_131202_Content_11 = {
    Text = "Jubah ungu panjang... Aku tidak pernah... tidak pernah melihatnya..."
  },
  AvgDialog_131202_Content_12 = {
    Text = "Mereka……membawa \"Kenangan\" ke altar…… <Shake:Uhuk uhuk……>"
  },
  AvgDialog_131202_Content_13 = {
    Text = "Jalan St. Basil... sebuah gereja milik mereka..."
  },
  AvgDialog_131202_Content_14 = {
    Text = "Tulang dan daging bergetar, berjuang, menekan sisa-sisa kehidupan tubuh yang hancur ini."
  },
  AvgDialog_131202_Content_15 = {
    Text = "Dia tahu, Nona Arachne tidak dapat melihat benang-benang orang-orang itu. Dia tahu, ini adalah sesuatu yang perlu diselesaikannya."
  },
  AvgDialog_131202_Content_16 = {
    Text = "Nona... penjahat di dalam bayangan... sedang memburu kami... dia memanipulasi nasib kami..."
  },
  AvgDialog_131202_Content_17 = {
    Text = "Mereka telah mengambil darahku... di gereja itu, dia akan melaksanakan ritual horor itu..."
  },
  AvgDialog_131202_Content_18 = {
    Text = "Pembalas dendam takdir, bermandikan darah kami…… Dewa jahat dari bayang-bayang akan segera turun, semua takdir akan jatuh ke dalam…… keseluruhan…… <Shake:Uhuk uhuk uhuk……><Big:kekacauan total……!>"
  },
  AvgDialog_131202_Content_19 = {
    Text = "Pupil lansia itu tiba-tiba membesar, tubuhnya bergetar karena dingin dan ketakutan, seolah-olah telah melihat neraka yang lebih mengerikan daripada mimpi buruk terdalammnya."
  },
  AvgDialog_131202_Content_2 = {
    Text = "Para laba-laba menyebar, sosok terakhir terjatuh dalam cahaya perak, pemilik hujan lebat sudah tidak terlihat. Kamu dan Arachne tiba di depan sosok yang terjatuh di tengah kamar."
  },
  AvgDialog_131202_Content_20 = {
    Text = "Dia menggenggam lengan baju Arachne dengan erat, memandang Arachne dengan tatapan yang hampir seperti meminta."
  },
  AvgDialog_131202_Content_21 = {
    Text = "Nona... Saya masih terbiasa memanggil Anda Nona... Anda sudah lama belajar berbicara, membuat Tuan dan Nyonya khawatir..."
  },
  AvgDialog_131202_Content_22 = {
    Text = "Kamu mengucapkan selamat tinggal padaku, semua orang senang karena akhirnya kamu bisa berbicara, tapi aku tahu, hanya aku yang tahu... kata-kata itu adalah putusan takdir yang tidak bisa diubah..."
  },
  AvgDialog_131202_Content_23 = {
    Text = "Saya kembali ke rumah, menunggu kedatangan kematian. Saya tidak bisa berhenti menangis, bukan untuk diri saya sendiri, tetapi untuk Anda, Nona Arachne..."
  },
  AvgDialog_131202_Content_24 = {
    Text = "Aku tahu, apa yang akan kamu tanggung adalah kutukan yang sangat berat…"
  },
  AvgDialog_131202_Content_25 = {
    Text = "Air mata mengalir di wajah lansia yang berlekuk-lekuk. Dia menggenggam tangan Arachne dengan gemetar. Melalui cahaya air mata yang kabur, dia melihat Arachne muda berdiri di depannya."
  },
  AvgDialog_131202_Content_26 = {
    Text = "Wajah yang masih polos itu tidak pernah menangis dengan suara keras, ia selalu melihat ke langit yang kosong dengan rasa ingin tahu, tersenyum kepada nasib yang tidak bisa mereka lihat."
  },
  AvgDialog_131202_Content_27 = {
    Text = "Nona Arachne, tolong jaga dia dengan baik, jaga \"Kenangan\"... tolong jaga diri Anda dengan baik..."
  },
  AvgDialog_131202_Content_28 = {
    Text = "Jangan... hilang di... jaringan..."
  },
  AvgDialog_131202_Content_29 = {
    Text = "Suara\"Kebaikan\"hampir tidak terdengar di akhir. Ketika suaranya berhenti, Arachne dengan lembut menutup kedua matanya."
  },
  AvgDialog_131202_Content_3 = {Text = "Kau……"},
  AvgDialog_131202_Content_30 = {
    Text = "\"Selamat malam, Tuan Edgar……\""
  },
  AvgDialog_131202_Content_31 = {
    Text = "Sudut mulut Edgar tua sedikit terangkat. Di saat-saat terakhir hidupnya, ia sekali lagi mendengar kalimat pertama yang diucapkan Arachne dalam hidupnya."
  },
  AvgDialog_131202_Content_32 = {
    Text = "Dia tidak menginginkan apa-apa lagi."
  },
  AvgDialog_131202_Content_33 = {
    Text = "Kamu……menggunakan kenangan kepala pelayanmu untuk menciptakannya…… Boneka rahasia ini sama sekali berbeda dari boneka lain yang kamu ciptakan. Mengapa?"
  },
  AvgDialog_131202_Content_34 = {
    Text = "Mungkin untuk mengenang, atau mungkin... untuk menghibur diri sendiri."
  },
  AvgDialog_131202_Content_35 = {
    Text = "Penghiburan?"
  },
  AvgDialog_131202_Content_36 = {
    Text = "Menghibur diri, mereka selalu ada di sampingku, tidak pernah menjauh…"
  },
  AvgDialog_131202_Content_37 = {
    Text = "Arachne dengan tenang melepaskan tubuh lansia yang hancur, tidak memberikan penjelasan lebih lanjut, dan kamu juga tidak bertanya lagi. Kamu tahu, jawabannya sedang menunggu tidak jauh dari situ."
  },
  AvgDialog_131202_Content_38 = {
    Text = "Dalam Jaring Takdir ini, kekuatan Nefraea berkaitan dengan mereka. Kematian mereka akan membuat hubungan Nefraea dengan jaring semakin erat."
  },
  AvgDialog_131202_Content_39 = {
    Text = "Sebelum dia memiliki kekuatan untuk menghancurkan jaring ini, hentikan dia. Itulah satu-satunya hal yang penting sekarang, Penjaga Rahasia {Male=先生,Female=小姐}."
  },
  AvgDialog_131202_Content_4 = {
    Text = "<Shake:Nona Arachne......Orang Asing......hek hek......>"
  },
  AvgDialog_131202_Content_40 = {
    Text = "Tangan Arachne mengelus kepala lansia, menyentuh benang yang hampir tak terlihat itu. Di ujung kota yang jauh ini, benang nasib mengirimkan gema yang lemah."
  },
  AvgDialog_131202_Content_41 = {
    Text = "Nasib telah menjawabmu?"
  },
  AvgDialog_131202_Content_42 = {
    Text = "Arachne mengangguk. Sebelum bangkit, dia melihat sekali lagi wajah tersenyum lansia itu."
  },
  AvgDialog_131202_Content_43 = {
    Text = "\"Kenangan\" masih hidup. Para tamu dari jurang sedang menunggu kedatangan kita."
  },
  AvgDialog_131202_Content_5 = {
    Text = "Di depanmu, tubuh itu setengahnya adalah daging yang busuk karena dimakan, dan setengahnya lagi adalah tulang putih yang berwarna darah."
  },
  AvgDialog_131202_Content_6 = {
    Text = "Suara batuk keras dari lansia itu dengan susah payah mengeluarkan beberapa tetes darah yang belum mengering. Sebuah benang tak terlihat tergenggam di tangan Arachne, seperti nyala lilin di tengah hujan deras, goyang-goyang."
  },
  AvgDialog_131202_Content_7 = {
    Text = "Hentikan pendarahan… kita butuh sesuatu untuk menghentikan pendarahan…"
  },
  AvgDialog_131202_Content_8 = {
    Text = "Terlambat sudah... Nona Arachne... Pergi selamatkan dia... Pergi selamatkan \"Kenangan\"..."
  },
  AvgDialog_131202_Content_9 = {
    Text = "Para pengikut itu... membawa dia pergi..."
  },
  AvgDialog_131203_Content_1 = {
    Text = "Arachne! Apa yang kamu lakukan?! Ini adalah apa yang kamu sebut ... kepercayaan?"
  },
  AvgDialog_131203_Content_10 = {
    Text = "Pertunjukan. Penipuan. Menipu."
  },
  AvgDialog_131203_Content_11 = {
    Text = "\"Kegembiraan\", itulah takdirmu. Naiklah ke panggung, Penjaga Rahasia {Male=先生,Female=小姐}. Di atas panggung ini, selesaikanlah kisah yang menjadi milikmu."
  },
  AvgDialog_131203_Content_12 = {
    Text = "Di panggung ini, kamu akan mendapatkan apa yang kamu inginkan."
  },
  AvgDialog_131203_Content_2 = {
    Text = "Senior William……Senior William masih dalam masa pemulihan!……"
  },
  AvgDialog_131203_Content_3 = {
    Text = "Tenang saja, takdir ini tidak ada hubungannya dengan Tuan William, aku sudah memindahkannya ke tempat yang aman."
  },
  AvgDialog_131203_Content_4 = {
    Text = "Ini adalah takdir yang tak bisa kau dan aku hindari, Penjaga Rahasia {Male=先生,Female=小姐}."
  },
  AvgDialog_131203_Content_5 = {
    Text = "Aku tidak pernah memberitahumu kebohongan. Aku akan membawamu ke panggung yang menjadi milikmu, di mana kamu akan menyelesaikan pertunjukan megah yang menjadi milikmu."
  },
  AvgDialog_131203_Content_6 = {
    Text = "Arachne perlahan-lahan mendekat kepadamu. Kamu menatap mata kaburnya, berusaha membaca informasi yang tidak bisa dia sampaikan langsung kepadamu dari dalamnya."
  },
  AvgDialog_131203_Content_7 = {
    Text = "(Ini adalah… pertunjukanku…)"
  },
  AvgDialog_131203_Content_8 = {
    Text = "Sebuah cahaya spiritual melintas di pikiranmu, seperti meteor yang cepat berlalu, menghilang di antara kepingan kesadaran yang rumit."
  },
  AvgDialog_131203_Content_9 = {
    Text = "Pelayan Laba-laba Dingin menyebar di sekitar, tidak lagi maju. Arachne mengangkat tangannya dengan lembut, menggesek senar gitar yang kosong."
  },
  AvgDialog_131204_Content_1 = {
    Text = "Cahaya perak memotong benang-benang laba-laba seperti bilah tajam. Memanfaatkan celah ini, kamu dengan cepat melewati garis pertahanan para pelayan dan tiba di depan Arachne."
  },
  AvgDialog_131204_Content_10 = {
    Text = "Dia berbalik. Benang-benang berputar lembut, sebuah dorongan yang tiba-tiba muncul dari dalam hati, mendorongmu untuk berdiri."
  },
  AvgDialog_131204_Content_11 = {
    Text = "Anda yakin bahwa Anda sepenuhnya mandiri, Anda adalah perwakilan sempurna dari kehendak bebas. Anda sepenuhnya mengikuti kehendak pribadi Anda, mengikuti jejak Arachne dengan langkah dan frekuensi yang sepenuhnya selaras dengannya, menuju ujung jalan jaring laba-laba."
  },
  AvgDialog_131204_Content_13 = {
    Text = "Ah, selamat datang! %player%{Male=先生,Female=小姐}, tamuku yang terhormat! Ini adalah saat di mana langkah kakimu terdengar paling merdu."
  },
  AvgDialog_131204_Content_14 = {
    Text = "Pemilik baru teater muncul, suara Nefraea yang berlebihan terdengar di atas panggung yang gelap."
  },
  AvgDialog_131204_Content_15 = {
    Text = "Rasanya tidak enak ketika takdirmu dipermainkan orang lain, bukan, Penjaga Rahasia {Male=先生,Female=小姐}? Tapi tidak apa-apa, kisah ini akan segera mencapai akhirnya."
  },
  AvgDialog_131204_Content_16 = {
    Text = "Nefraea, apa sebenarnya yang kau inginkan?..."
  },
  AvgDialog_131204_Content_17 = {
    Text = "Ketegangan, benar, itulah yang mendorong penonton untuk datang ke teater ini! Namun, jangan terburu-buru, sayang."
  },
  AvgDialog_131204_Content_18 = {
    Text = "Tuan dan Nyonya! Siapkan sorakan kalian... Eh, di mana boneka saya... Oh, ketemu"
  },
  AvgDialog_131204_Content_19 = {
    Text = "Memburu tiga rahasia, pembalas yang agung dari nasib, pertunjukan imajinatif seperti apa yang ingin mereka persembahkan di panggung ini?"
  },
  AvgDialog_131204_Content_2 = {Text = "Berhasil!"},
  AvgDialog_131204_Content_20 = {
    Text = "Selanjutnya, silakan nikmati babak kedua dari drama ini, <Big:<Red:klimaks terakhir!>>"
  },
  AvgDialog_131204_Content_21 = {
    Text = "Aku menamakannya, \"Baru lahir\"——"
  },
  AvgDialog_131204_Content_22 = {Text = "Pak—"},
  AvgDialog_131204_Content_23 = {
    Text = "Sebuah cahaya terang berkumpul di atas panggung, memecahkan ketenangan dan kegelapan singkat di teater. Sebuah boneka yang memegang pemintal melangkah ke atas panggung."
  },
  AvgDialog_131204_Content_24 = {
    Text = "Nefraea, dewa kematian Jurang, pembalas nasib...<Shake:Saya telah menyerah kepada kekuatan agung Anda!>"
  },
  AvgDialog_131204_Content_25 = {
    Text = "Ini adalah romantis, yang membuat orang menjadi bodoh. Ini adalah kebaikan, yang membuat orang menjadi rapuh. Ini adalah kenangan... di antara semua kualitas yang indah, kenangan adalah sumber dari semua penderitaan."
  },
  AvgDialog_131204_Content_26 = {
    Text = "Saya tidak dapat menanggungnya... Saya mempersembahkannya kepada Anda, yang agung Nefraea."
  },
  AvgDialog_131204_Content_27 = {
    Text = "Benarkah, Kakak? Kakak perempuanku yang baik..."
  },
  AvgDialog_131204_Content_28 = {
    Text = "Tidak apa-apa, di dunia ini, aku adalah orang yang paling mengerti dirimu. Tak perlu menderita lagi, serahkan semua penderitaan ini padaku."
  },
  AvgDialog_131204_Content_29 = {
    Text = "Lihat, lentera yang berasal dari jurang telah dinyalakan, cahayanya akan menunjukkan jalan pulang bagi kita —"
  },
  AvgDialog_131204_Content_3 = {Text = "Ding——"},
  AvgDialog_131204_Content_30 = {
    Text = "Betapa hangatnya cahaya ini... tapi, jalan pulang kita, sebenarnya di mana?"
  },
  AvgDialog_131204_Content_31 = {
    Text = "Anda masih belum mengerti? Kakakku yang baik."
  },
  AvgDialog_131204_Content_32 = {
    Text = "Roda tenun ini adalah tubuh Rasul. Api-api ini adalah pandangan Rasul — Dia sedang memandang kita"
  },
  AvgDialog_131204_Content_33 = {
    Text = "\"Nefraea\" dengan penuh semangat berdiri dan mengulurkan kedua tangannya."
  },
  AvgDialog_131204_Content_34 = {
    Text = "Hanya perlu mengumpulkan kekuasaan dari tiga plasmid, maka rasul yang tak bernama akan terbangun di sini"
  },
  AvgDialog_131204_Content_35 = {
    Text = "Dia akan membukakan jalan menuju dewa tertinggi bagi kita……Saat itu tiba, <Big:segala penderitaan akan musnah, segala kesia-siaan akan berakhir!>"
  },
  AvgDialog_131204_Content_36 = {
    Text = "\"Nefraea\" tiba-tiba menarik masker kayu itu, memperlihatkan wajah Nefraea yang hidup."
  },
  AvgDialog_131204_Content_37 = {
    Text = "Panggung kayu, boneka kayu, satu-satunya tubuh yang hidup berdiri di tengah panggung, mengulurkan kedua lengan, menikmati pandangan dari satu-satunya penonton di bawah."
  },
  AvgDialog_131204_Content_38 = {
    Text = "Lorong dewa akan segera terbuka, misi kamu akan segera selesai, apakah kamu mengerti, Kakak?"
  },
  AvgDialog_131204_Content_39 = {
    Text = "Kamu tidak perlu lagi menjalin jaringmu yang tak berujung, kamu tidak perlu lagi mengorbankan dirimu"
  },
  AvgDialog_131204_Content_4 = {
    Text = "Tangan yang ramping menjulur ke udara dan dengan lembut menggesek. Senar bergetar lembut, menciptakan gelombang elegan di udara."
  },
  AvgDialog_131204_Content_40 = {
    Text = "Terima aku kembali, ya, Arachne?...... Biarkan aku menjadi bagian darimu lagi......"
  },
  AvgDialog_131204_Content_41 = {
    Text = "Air mata menghapus riasan, meninggalkan jejak hitam seperti pelarutan di wajah. Tawa dan tangisan yang gila seperti jaring raksasa, melilit orang ini, satu-satunya individu hidup di atas panggung."
  },
  AvgDialog_131204_Content_42 = {
    Text = "Nefraea berlutut, mengangkat pipi halus tanpa wajah dari \"Arachne\". Air mata mengalir di wajahnya yang merana, menetes di atas topeng tersenyum dari boneka."
  },
  AvgDialog_131204_Content_43 = {
    Text = "Dia menatap Arachne di bawah panggung dengan tajam, bibirnya yang bergetar perlahan menempel di telinga boneka. Suaranya begitu lembut, seolah-olah sedang berbicara untuk dirinya sendiri."
  },
  AvgDialog_131204_Content_44 = {
    Text = "Jangan lagi meninggalkanku... ya?"
  },
  AvgDialog_131204_Content_5 = {
    Text = "Gelombang melintas di atas cahaya perak, cahaya perak menghilang, kunci perak yang membawa kekuatan roh yang kuat menghilang tanpa jejak. Gelombang melintasi tubuh, tubuhmu berubah menjadi tulang kering, darahmu menjadi lumpur. Kamu terpecah belah, lalu kembali seperti semula."
  },
  AvgDialog_131204_Content_6 = {
    Text = "Semua kekuatan menghilang tanpa bentuk, semua pikiran lenyap seperti debu. Di mana gelombang menyentuh, ribuan dunia berubah menjadi benang di tangannya. Termasuk dirimu, dirimu sendiri."
  },
  AvgDialog_131204_Content_7 = {
    Text = [[
Dia adalah tuan teater. 
 Dia adalah takdir itu sendiri.]]
  },
  AvgDialog_131204_Content_8 = {
    Text = "Arachne, kamu... kamu dapat mengendalikan nasibku?!..."
  },
  AvgDialog_131204_Content_9 = {
    Text = "Senyum Arachne seperti sebuah danau yang tenang, kamu tidak bisa melihat bentuk danau itu, di permukaan danau ini, kamu hanya bisa melihat bayanganmu sendiri."
  },
  AvgDialog_131205_Content_1 = {Text = "Tembakan"},
  AvgDialog_131205_Content_10 = {
    Text = "Kamu tidak perlu menyerahkan tugas apa pun."
  },
  AvgDialog_131205_Content_11 = {
    Text = "Guru Arachne, Anda... apa maksudnya?"
  },
  AvgDialog_131205_Content_12 = {
    Text = "Apakah kamu masih ingat siapa kamu dan dari mana kamu berasal?"
  },
  AvgDialog_131205_Content_13 = {
    Text = "Saya? Tentu saja saya……"
  },
  AvgDialog_131205_Content_14 = {
    Text = "%player%. Pemuda asli Hervats. Mahasiswa baru tahun pertama di Akademi Teater. Orang tuamu adalah pegawai biasa pemerintah yang sangat menyayangimu. Pernah menjalani dua hubungan percintaan yang layak. Bakat terbatas, penuh semangat, pecinta kue Sacher dan burrito daging panggang."
  },
  AvgDialog_131205_Content_15 = {
    Text = "Memori yang awalnya jelas tiba-tiba menjadi kabur, sebuah fragmen memori lain tiba-tiba melompat keluar dari pikiranmu. Mythag, Awakener, Pelarutan, Touva Wave…"
  },
  AvgDialog_131205_Content_16 = {
    Text = "Kamu tiba-tiba membelalak, memandang wanita yang sedang mencicipi kopi di seberang."
  },
  AvgDialog_131205_Content_17 = {
    Text = "Tidak... tidak benar... saya adalah Penjaga Mythag... apa yang terjadi?"
  },
  AvgDialog_131205_Content_18 = {
    Text = "Aku ingat... kita berada di teatermu, naik ke atas panggung, lalu... lalu..."
  },
  AvgDialog_131205_Content_19 = {
    Text = "Lalu kamu memesan teh sore kepada pelayan. Sebagai penduduk setempat, seleramu cukup baik."
  },
  AvgDialog_131205_Content_2 = {
    Text = "Ting ting——"
  },
  AvgDialog_131205_Content_20 = {
    Text = "Arachne mengambil seteguk cairan coklat di dalam cangkir kopi, dan mengangguk sebagai bentuk pujian."
  },
  AvgDialog_131205_Content_21 = {
    Text = "Kalian berdua, barang-barang kalian sudah lengkap."
  },
  AvgDialog_131205_Content_22 = {
    Text = "Piring di tangan pelayan mengeluarkan aroma yang memabukkan, saat membungkuk untuk menyajikan makanan, dia diam-diam mendekatkan kepalanya ke telinga kamu."
  },
  AvgDialog_131205_Content_23 = {
    Text = "Rencana pembunuhan telah bocor, rute Adipati Agung kemungkinan besar akan berubah. Begitu ada informasi baru, atasan akan segera memberitahu kalian. Bersiaplah, %player%."
  },
  AvgDialog_131205_Content_24 = {
    Text = "Sebuah pistol Browning yang baru saja diletakkan dengan diam-diam di tanganmu. Ketika kamu mengangkat kepala lagi, wajah pelayan itu kembali tersenyum ramah, setelah memberi hormat kepada kalian, dia membawa piring kembali ke dapur."
  },
  AvgDialog_131205_Content_25 = {
    Text = "Memori yang berlebihan menumpuk di kepalamu, kamu sedikit kesakitan sambil mengusap dahi yang terasa bengkak."
  },
  AvgDialog_131205_Content_26 = {
    Text = "Dua bagian memori yang berbeda ada dalam satu otak, bagi orang yang mengalaminya untuk pertama kali, perasaan ini memang tidak terlalu menyenangkan."
  },
  AvgDialog_131205_Content_27 = {
    Text = "Untungnya, dibandingkan dengan menghadapi Touva Wave, sakit kepala seperti ini terasa seperti sedang dipijat."
  },
  AvgDialog_131205_Content_28 = {
    Text = "Ingatanku memberitahuku bahwa aku akan mengikuti instruksi dari Dewan Restorasi, dan dalam dua jam lagi, menggunakan pistol ini untuk membunuh putra mahkota Kekaisaran Fio yang datang berkunjung..."
  },
  AvgDialog_131205_Content_29 = {
    Text = "Kamu menyentuh pola pada pistol itu, mengatur kembali ingatan yang berasal dari dunia ini dalam benakmu."
  },
  AvgDialog_131205_Content_3 = {
    Text = "Roda mobil melintasi permukaan jalan berbatu yang terjal, suara lonceng yang marah mengaum ke arah kerumunan besar dalam parade, mengangkat debu dan makian."
  },
  AvgDialog_131205_Content_30 = {
    Text = "Sebelum kamu sempat melanjutkan pertanyaan, seberkas cahaya terang masuk ke dalam kafe. Suara sepatu bot militer bertemu dengan lantai semen yang keras, mendekati meja bar."
  },
  AvgDialog_131205_Content_31 = {
    Text = "Beberapa petugas polisi, selamat datang, bolehkah saya bertanya……"
  },
  AvgDialog_131205_Content_32 = {
    Text = "Sebelum dia selesai berbicara, seorang petugas polisi cepat-cepat maju, membalikkan kedua tangannya, dan menekan kepalanya di atas meja bar."
  },
  AvgDialog_131205_Content_33 = {
    Text = "Di dalam tatapan ketakutannya, sebuah pistol ditekan di tengah dahinya."
  },
  AvgDialog_131205_Content_34 = {
    Text = "Anggota Dewan Pemulihan Negara Bosante. Kamu punya sepuluh detik untuk memberi tahu saya di mana rekanmu."
  },
  AvgDialog_131205_Content_35 = {
    Text = "Pelayan itu bernapas terengah-engah karena ketakutan. Di tengah perjuangan hebat, ia melirik ke sudut aula."
  },
  AvgDialog_131205_Content_36 = {
    Text = "Tempat duduk yang baru saja kalian tempati sudah kosong sejak tadi, di atas secangkir kopi yang belum habis diminum, uap tipis perlahan menguar."
  },
  AvgDialog_131205_Content_38 = {
    Text = "Tempat ini seharusnya aman untuk sementara."
  },
  AvgDialog_131205_Content_39 = {
    Text = "Kalian keluar dari pintu belakang kafe, seperti dua tetes air yang tidak mencolok, berkumpul di kerumunan yang gaduh."
  },
  AvgDialog_131205_Content_4 = {
    Text = "Kamu melambaikan tanganmu, mengusir debu-debu yang masuk dari tirai kafe."
  },
  AvgDialog_131205_Content_40 = {
    Text = "Situasi sekarang ini… apa yang sebenarnya terjadi dengan ingatan yang berbeda ini?"
  },
  AvgDialog_131205_Content_41 = {
    Text = "Melangkah ke panggung teater takdir, maka kamu akan menjadi karakter di atas panggung. Setiap karakter, memiliki kehidupannya sendiri."
  },
  AvgDialog_131205_Content_42 = {
    Text = "Dunia ini terletak di dimensi yang jauh, yang belum pernah kau dengar, belum pernah kau masuki. Namun sebagai karakter yang tumbuh di dunia ini, kau sudah sangat memahaminya."
  },
  AvgDialog_131205_Content_43 = {
    Text = "Selamat datang di salah satu panggungku, Penjaga Rahasia {Male=先生,Female=小姐}."
  },
  AvgDialog_131205_Content_44 = {
    Text = "Maksudmu adalah... kamu bisa menghubungkan dunia lain melalui panggung?"
  },
  AvgDialog_131205_Content_45 = {
    Text = "Arachne memahami makna di balik tatapanmu yang membara. Dia mengangkat cangkir kopi yang dibawanya dari toko, menciumnya dengan serius, lalu menggelengkan kepala pelan."
  },
  AvgDialog_131205_Content_46 = {
    Text = "Melarikan diri dengan kopi dan kue, hal aneh ini sama sekali tidak menarik perhatianmu. Itu terjadi dengan begitu harmonis pada Arachne, seolah-olah itu adalah bagian dari nasibnya."
  },
  AvgDialog_131205_Content_47 = {
    Text = "Nyonya Daphdael telah menjelaskan kepada Anda prinsip penjelajahan dimensi. Dinding pemisah antar dimensi sangatlah kokoh, setiap perjalanan lintas dimensi akan menuntut harga yang sangat besar."
  },
  AvgDialog_131205_Content_48 = {
    Text = "Tapi kita sekarang tidak sudah berada di sini…?"
  },
  AvgDialog_131205_Content_49 = {
    Text = "Panggung teater mampu menghubungkan takdir dari dunia-dunia yang berbeda secara singkat."
  },
  AvgDialog_131205_Content_5 = {
    Text = "Satu burrito daging panggang, satu kue Sacher, dua cangkir kopi Hervats. Terima kasih."
  },
  AvgDialog_131205_Content_50 = {
    Text = "Kita saat ini hanyalah dua karakter yang tenggelam di atas panggung, dua proyeksi sesaat di dunia ini."
  },
  AvgDialog_131205_Content_51 = {
    Text = "Proyeksi... bahkan proyeksi pun bisa, bisakah kamu membantuku kembali dengan cara ini..."
  },
  AvgDialog_131205_Content_52 = {
    Text = "Mohon maaf, %player%. Pintu yang Anda tutup telah menghalangi pandangan Tohvapo, dan juga memutus benang takdir."
  },
  AvgDialog_131205_Content_53 = {
    Text = "Jika mencoba untuk mempengaruhi tempat itu, akan menghadapi bencana yang tidak dapat kita tanggung."
  },
  AvgDialog_131205_Content_54 = {
    Text = "Dia melihat ekspresi kecewa di wajahmu, lalu tersenyum dan menyerahkan kue di piring kepadamu."
  },
  AvgDialog_131205_Content_55 = {
    Text = "Tenang saja, %player%. Setelah urusan dengan adik perempuan saya selesai, jalur koneksi Anda dengan Kardas akan segera dapat dibuka kembali."
  },
  AvgDialog_131205_Content_56 = {
    Text = "Nasib tidak akan mengecewakan setiap penantian, dan kita juga tidak boleh mengecewakan setiap hadiah dari nasib. Coba saja."
  },
  AvgDialog_131205_Content_57 = {
    Text = "Kamu menarik napas dalam-dalam, mengambil kue dan menggigitnya dengan lembut. Rasa manisnya membuatmu hampir melupakan ketidaknyamanan yang disebabkan oleh benturan dua kenangan yang berbeda."
  },
  AvgDialog_131205_Content_58 = {
    Text = "Hmm... Konon setiap kali Adipati Agung Flavian datang, beliau selalu mencicipi kue khas daerah ini. Sebagai seorang putra mahkota, seleranya memang tidak buruk."
  },
  AvgDialog_131205_Content_59 = {
    Text = "Jadi, apa yang Nefraea pengaruhi di dunia ini? Bagaimana kita seharusnya memperbaikinya..."
  },
  AvgDialog_131205_Content_6 = {
    Text = "Kamu menyerahkan menu yang terbuat dari kulit domba kepada pelayan, sambil dengan murung menatap jalan yang familiar di luar jendela."
  },
  AvgDialog_131205_Content_60 = {
    Text = "Saat kamu berbicara, Arachne tampaknya tertarik oleh sesuatu, mengangkat kepala untuk melihat benang-benang di udara yang tidak bisa kamu lihat dengan jelas."
  },
  AvgDialog_131205_Content_61 = {
    Text = "Dia tersenyum, menghabiskan tegukan terakhir kopi di cangkirnya, memberikan beberapa koin dan sisa cangkir kepada seorang pelayan yang kebetulan lewat dan ingin kembali ke kafe, sambil mengucapkan terima kasih dengan suara pelan."
  },
  AvgDialog_131205_Content_62 = {
    Text = "Dia menemukan kita, waktunya tepat. Hati-hati, %player%."
  },
  AvgDialog_131205_Content_63 = {Text = "BRAK—"},
  AvgDialog_131205_Content_64 = {
    Text = "Kamu secara instinktif membungkuk, sebuah peluru hampir melintas di atas kepalamu."
  },
  AvgDialog_131205_Content_65 = {Text = "Di sana"},
  AvgDialog_131205_Content_66 = {
    Text = "Ini adalah pembunuh dari Komite Pemulihan Negara! Tangkap mereka"
  },
  AvgDialog_131205_Content_67 = {
    Text = "Dipandu oleh beberapa warga, sekelompok polisi menyibak kerumunan dan mengelilingi kalian."
  },
  AvgDialog_131205_Content_68 = {
    Text = "Saat mendekati kalian, tubuh mereka mulai berubah bentuk. Di atas kaki-kaki laba-laba yang hitam legam, cakar tajam mengayun ke arah kalian—"
  },
  AvgDialog_131205_Content_7 = {
    Text = "Jalan ini memang perlu diperlebar, saat kecil di sini memang seperti ini, kecuali semakin rusak, selama bertahun-tahun ini tidak ada yang berubah sama sekali."
  },
  AvgDialog_131205_Content_8 = {
    Text = "Pemerintah memang tidak pandai membangun. Satu-satunya yang bisa mereka lakukan hanyalah menjual tanah Hervats dan menyerahkan kue dengan hormat kepada keluarga kerajaan."
  },
  AvgDialog_131205_Content_9 = {
    Text = "Pengungsi, pawai, harus memilih waktu ini untuk mengunjungi Adipati... Guru Arachne, apakah saya bisa menyerahkan tugas penelitian folklor saya sedikit lebih lambat? Kegiatan Komite Pemulihan Negara belakangan ini menghabiskan terlalu banyak energi saya."
  },
  AvgDialog_131206_Content_10 = {
    Text = "Ciiit——Ciiit——Dewi nasib memutar alat tenunnya."
  },
  AvgDialog_131206_Content_11 = {
    Text = "Ciiit——Ciiit——Benang nasib berkumpul di tangannya."
  },
  AvgDialog_131206_Content_12 = {
    Text = "Boneka-boneka antre untuk masuk, melangkah ke dalam jaring besar takdir."
  },
  AvgDialog_131206_Content_13 = {
    Text = "Mereka menari. Mereka bernyanyi. Ciiit——ciiit——"
  },
  AvgDialog_131206_Content_14 = {
    Text = "Mereka mati bersama jaring raksasa, tanpa suara."
  },
  AvgDialog_131206_Content_16 = {
    Text = "Tuan, pertunjukan baru kami sudah dimulai."
  },
  AvgDialog_131206_Content_17 = {
    Text = "Jalan kembali ke Kadas sudah ditutup tepat waktu, orang itu {Male=tuannya, Female=nyonya}, sudah tiba di kota."
  },
  AvgDialog_131206_Content_18 = {
    Text = "Bagaimana, apakah kamu menyukai drama baru ini?"
  },
  AvgDialog_131206_Content_19 = {
    Text = "Hmm... mungkin ini agak terlalu rumit?"
  },
  AvgDialog_131206_Content_2 = {
    Text = "Kota Kabut Belum Terbangun"
  },
  AvgDialog_131206_Content_20 = {
    Text = "Cerita yang sederhana tentu saja tidak merepotkan, tetapi bagi sebagian orang, cerita seperti ini tidak dapat menuliskan nasib mereka."
  },
  AvgDialog_131206_Content_21 = {
    Text = "Emosi yang kuat, perubahan yang dramatis, alur yang mengharukan, akhir yang heroik…"
  },
  AvgDialog_131206_Content_22 = {
    Text = "Semua ini, adalah takdir yang melekat pada seorang \"Pahlawan\"."
  },
  AvgDialog_131206_Content_23 = {
    Text = "Pergilah, saatnya kamu tampil di atas panggung."
  },
  AvgDialog_131206_Content_24 = {
    Text = "Gadis itu bersujud memberi hormat. Pada saat dahinya menyentuh lantai, tubuhnya pecah dan terbelah, daging serta kulitnya seluruhnya berubah menjadi laba-laba berwarna ungu pucat, menyebar dan menghilang ke sudut-sudut ruangan."
  },
  AvgDialog_131206_Content_26 = {
    Text = "<Shake:Khe… khe khe…>"
  },
  AvgDialog_131206_Content_27 = {
    Text = "Di bawahmu adalah permukaan jalan aspal yang keras. Kamu berdiri dengan goyah, menggosok-gosok kepalamu yang kacau dengan keras."
  },
  AvgDialog_131206_Content_28 = {
    Text = "Tadi… terjadi…"
  },
  AvgDialog_131206_Content_29 = {
    Text = "Ah! Lorong Kadas!"
  },
  AvgDialog_131206_Content_3 = {
    Text = "Terompet memainkan koloratura. Ksatria berbaju hitam naik panggung."
  },
  AvgDialog_131206_Content_30 = {
    Text = "Kamu terbangun tiba-tiba, mengangkat kepala dan memandang ke langit."
  },
  AvgDialog_131206_Content_31 = {
    Text = "Di langit biru yang cerah, sinar matahari yang terang menyinari, tidak ada jejak sedikit pun dari hari gelap dan jalur dimensi yang ada."
  },
  AvgDialog_131206_Content_32 = {
    Text = "Ini... orang ini sangat aneh... {Male=Dia,Female=Dia} baru saja jatuh dari langit?"
  },
  AvgDialog_131206_Content_33 = {
    Text = "Hmm, menurut yang saya ketahui, ada sebuah perusahaan teknologi di sekitar sini yang sedang menguji pesawat terbang, {Male=dia,Female=dia} seharusnya adalah satu orang pengujicoba pesawat terbang."
  },
  AvgDialog_131206_Content_34 = {
    Text = "Hmm... ini..."
  },
  AvgDialog_131206_Content_35 = {Text = "Manusia."},
  AvgDialog_131206_Content_36 = {
    Text = "Kerumunan yang padat muncul di mata yang disakiti oleh cahaya yang menyilaukan."
  },
  AvgDialog_131206_Content_37 = {
    Text = "Sebuah kota yang ramai seperti Londinium membawamu kembali ke kenangan jauh di Kazdel."
  },
  AvgDialog_131206_Content_38 = {
    Text = "Jalanan yang padat, kerumunan penonton, toko-toko berwarna-warni di mana-mana..."
  },
  AvgDialog_131206_Content_39 = {
    Text = "Dunia dimensi ini mengalami penurunan populasi yang tajam akibat Pelarutan, bahkan di Nekropolis kamu tidak pernah melihat pemandangan semeriah ini."
  },
  AvgDialog_131206_Content_4 = {
    Text = "Ah, Kadas, tanah airmu dalam mimpiku! Sekarang, aku akhirnya bisa kembali"
  },
  AvgDialog_131206_Content_40 = {
    Text = "Permisi... di mana sini?"
  },
  AvgDialog_131206_Content_41 = {
    Text = "Haha, aneh, ada orang yang bahkan belum pernah mendengar nama Londinium? Ini adalah kota terbesar di dunia"
  },
  AvgDialog_131206_Content_42 = {
    Text = "<Shake:!!!>"
  },
  AvgDialog_131206_Content_43 = {
    Text = "Kamu bilang tempat ini disebut apa?"
  },
  AvgDialog_131206_Content_44 = {
    Text = "Kamu yakin kamu mendengar empat kata itu."
  },
  AvgDialog_131206_Content_45 = {
    Text = "Otak yang berat segera terbangun, kamu tiba-tiba berdiri dan melihat sekeliling."
  },
  AvgDialog_131206_Content_46 = {
    Text = "Persimpangan Brick, jejak yang pudar di papan petunjuk persimpangan sama persis dengan yang ada dalam ingatanmu."
  },
  AvgDialog_131206_Content_47 = {
    Text = "Toko Buku Bekas Waktu Lipatan, setiap kali kamu diam-diam keluar dari sekolah, yang paling kamu suka lakukan adalah bersembunyi di sini dan membaca novel detektif."
  },
  AvgDialog_131206_Content_48 = {
    Text = "Toko Kelontong Pasar Wangi, Profesor Dexter selalu memintamu untuk membawakan satu botol anggur emas dari sini. Tipu daya kecil N."
  },
  AvgDialog_131206_Content_49 = {
    Text = "Kamar Bunga Embun Pagi. Pada perayaan satu tahun kamu menjadi Penjaga, Ramona sebenarnya berencana untuk menyiapkan seikat bunga paling cerah di seluruh Londinium untukmu…"
  },
  AvgDialog_131206_Content_5 = {
    Text = "Guruku, rekanku, sahabat dekatku, dan segalanya bagiku…"
  },
  AvgDialog_131206_Content_51 = {
    Text = "Londinium... aku benar-benar... sudah kembali?"
  },
  AvgDialog_131206_Content_52 = {
    Text = "Bolehkah saya bertanya... Bagaimana kondisi Mythag sekarang?"
  },
  AvgDialog_131206_Content_53 = {
    Text = "Mythag? Orang ini {Male=Tuanku,Female=Nona}, tempat yang Anda sebutkan belum pernah kami dengar."
  },
  AvgDialog_131206_Content_54 = {
    Text = "Bagaimana dengan pelarutan itu? Bagaimana situasi bencana di sini?"
  },
  AvgDialog_131206_Content_55 = {
    Text = "Bencana? Kota ini sudah berdiri selama lebih dari dua ribu tahun, dan belum pernah ada bencana apa pun."
  },
  AvgDialog_131206_Content_56 = {
    Text = "Anak, sepertinya kamu sudah lelah... Mari duduk di bangku taman dan makan sedikit. Kebetulan saya punya beberapa."
  },
  AvgDialog_131206_Content_57 = {
    Text = "Lansia menyerahkan roti dan air yang baru saja dibeli dari toko kelontong ke arahmu."
  },
  AvgDialog_131206_Content_58 = {
    Text = "Ah, terima kasih banyak... Namun saya tidak lapar sekarang, saya hanya... memiliki beberapa pertanyaan yang belum saya mengerti..."
  },
  AvgDialog_131206_Content_59 = {
    Text = "<Small:Ini tidak mungkin... tidak ada Mythag, dan tidak ada Pelarutan...>"
  },
  AvgDialog_131206_Content_6 = {
    Text = "Asalkan melewati pintu kegelapan ini, aku akan bertemu kembali dengan mereka"
  },
  AvgDialog_131206_Content_60 = {
    Text = "Kakek, orang ini aneh sekali, kenapa dia terus berbicara sendiri?"
  },
  AvgDialog_131206_Content_61 = {
    Text = "Jangan bicara sembarangan, {Male=Dia,Lady=Dia} mungkin menghadapi kesulitan. Untuk tamu yang datang dari jauh, haruslah sopan."
  },
  AvgDialog_131206_Content_62 = {
    Text = "Sebuah tangan dengan lembut menepuk pundakmu. Kamu berbalik dan melihat wajah yang asing."
  },
  AvgDialog_131206_Content_63 = {
    Text = "Kami adalah petugas patroli di sekitar sini, berada di bawah yurisdiksi Komite. Ini adalah identitas saya."
  },
  AvgDialog_131206_Content_64 = {
    Text = "Salam sejahtera untuk Anda. Ada warga yang baik hati memberi tahu kami bahwa seorang pelancong tersesat di kota indah kami."
  },
  AvgDialog_131206_Content_65 = {
    Text = "Permisi, apakah orang ini {Male=Tuan, Female=Nona} membutuhkan bantuan?"
  },
  AvgDialog_131206_Content_66 = {
    Text = "Kamu berpikir sejenak. Sebelum memahami situasinya, kamu perlu menghindari menarik perhatian orang lain sebisa mungkin."
  },
  AvgDialog_131206_Content_67 = {
    Text = "Ah... terima kasih atas perhatian kalian. Saya hanya pingsan saat berjalan-jalan di jalan, tidak mengalami masalah apa pun."
  },
  AvgDialog_131206_Content_68 = {
    Text = "Terima kasih banyak kepada kalian. Kami masih ada hal yang perlu dilakukan, jadi kami pergi lebih dulu…"
  },
  AvgDialog_131206_Content_69 = {
    Text = "Begitu rupanya. Kalau begitu, maaf mengganggu waktu Anda sebentar lagi, saya punya beberapa pertanyaan yang ingin saya tanyakan."
  },
  AvgDialog_131206_Content_7 = {
    Text = "Tapi mengapa pintu yang begitu dekat ini tertutup? Langit yang kejam ini, mengapa meninggalkanku?"
  },
  AvgDialog_131206_Content_70 = {
    Text = "Petugas itu tersenyum dan mendekat ke sisi kalian, lalu menepuk debu di bahu kalian."
  },
  AvgDialog_131206_Content_71 = {
    Text = "<Red:Penjaga Rahasia>, saya seharusnya memanggil Anda begitu, bukan?"
  },
  AvgDialog_131206_Content_72 = {
    Text = "Saya ingin bertanya... apakah Anda puas dengan upacara penyambutan ini?"
  },
  AvgDialog_131206_Content_73 = {Text = "!!!"},
  AvgDialog_131206_Content_74 = {
    Text = "Suara bergerak-gerik yang memuakkan terdengar. Beberapa kaki laba-laba raksasa menembus tubuh petugas polisi dan pejalan kaki, plasma darah kental yang berbau amis terciprat ke tubuh kalian."
  },
  AvgDialog_131206_Content_75 = {
    Text = "Mewakili takdir untuk menyapamu, Penjaga Rahasia yang terkasih."
  },
  AvgDialog_131206_Content_76 = {
    Text = "Tamu terhormat telah tiba di panggung kita, antar{Male=他,Female=她} ke tempat duduk, anak-anak."
  },
  AvgDialog_131206_Content_77 = {
    Text = "Baik, Tuan."
  },
  AvgDialog_131206_Content_78 = {Text = "Hati-hati!"},
  AvgDialog_131206_Content_8 = {
    Text = "Kunci perak yang terkasih... tolong terangi jalanku... tolong berikan sepenggal jawaban padaku..."
  },
  AvgDialog_131206_Content_9 = {
    Text = "Pencahayaan berubah. Penyanyi perak naik panggung."
  },
  AvgDialog_131207_Content_1 = {
    Text = "Bayangan Sang Dewa"
  },
  AvgDialog_131207_Content_10 = {
    Text = "Kau masih memiliki kesempatan untuk berhenti, Nefraea."
  },
  AvgDialog_131207_Content_11 = {
    Text = "Sepenuhnya menghilang, lalu bagaimana?"
  },
  AvgDialog_131207_Content_12 = {
    Text = "Nefraea tersenyum dengan sembrono, berbalik untuk melihat para pelayan yang setia."
  },
  AvgDialog_131207_Content_13 = {
    Text = "Katakan padaku, anak-anak, apakah kalian takut?"
  },
  AvgDialog_131207_Content_14 = {
    Text = "Tanggapan Arachne adalah tawa putus asa."
  },
  AvgDialog_131207_Content_15 = {
    Text = "Hahahaha! Kami adalah orang-orang yang ditinggalkan oleh nasib, tidak ada bencana yang akan membuat kami takut... Tolong berikan kami pembebasan, Tuhanku."
  },
  AvgDialog_131207_Content_16 = {Text = "Anak baik."},
  AvgDialog_131207_Content_17 = {
    Text = "Nefraea dengan kasih sayang mengelus kepala Pelayan."
  },
  AvgDialog_131207_Content_18 = {
    Text = "Kau salah, saudariku tercinta. Nasib telah menjatuhkan hukuman mati dan penjara abadi kepada kita. Sekelompok roh yang ditinggalkan, tidak akan lagi memohon belas kasihan nasib."
  },
  AvgDialog_131207_Content_19 = {
    Text = "Kami, sedang membalas dendam pada nasib."
  },
  AvgDialog_131207_Content_2 = {
    Text = "Di panggung megah yang belum pernah kamu lihat sebelumnya, roda tenun hitam Nefraea berdiri sendirian di tengah panggung. Di tengah lingkaran raksasa, cahaya biru gelap yang tampaknya tidak pernah padam menerangi wajah Nefraea yang penuh kebahagiaan."
  },
  AvgDialog_131207_Content_20 = {
    Text = "Entah itu disengaja atau tidak, Nefraea memainkan Benang Takdir, dan salah satu benangnya tiba-tiba putus."
  },
  AvgDialog_131207_Content_21 = {
    Text = "Saat benang itu putus, sebuah panggung yang tidak jauh dari kalian hancur dengan keras, berubah menjadi serpihan-serpihan yang terbang, lenyap di dalam ruang dimensi teater yang tak berujung."
  },
  AvgDialog_131207_Content_22 = {
    Text = "Astaga, maaf maaf, aku tidak sengaja merusak benangmu…"
  },
  AvgDialog_131207_Content_23 = {
    Text = "Cepat lakukan, kakak yang baik. Meskipun ada banyak panggung di teater, jika kamu merusaknya lagi, pasti kamu juga akan merasa sakit hati, kan?"
  },
  AvgDialog_131207_Content_24 = {
    Text = "Desahan Arachne hampir tidak terdengar. Ketika dia membuka mata lagi, dia mengangkat ujung jarinya dan mengetuk lembut di atas kepalamu."
  },
  AvgDialog_131207_Content_25 = {
    Text = "Arachne! Jangan lakukan itu... Kita pasti bisa menemukan cara lain..."
  },
  AvgDialog_131207_Content_26 = {
    Text = "Naiklah ke panggung, persembahkan kuasa substansi kepada utusan dewa... ini adalah takdir yang tak bisa kau hindari, Penjaga Rahasia {Male=先生,Female=小姐}."
  },
  AvgDialog_131207_Content_27 = {
    Text = "Arachne suara yang tak terelakkan bergema di dunia roh Anda. Ketika Anda mengangkat langkah menuju panggung, tiga kekuatan yang telah lama hilang dalam diri Anda mulai ketidaktenangan."
  },
  AvgDialog_131207_Content_28 = {
    Text = "Mereka terjerat dan bertabrakan di dalam tubuhmu, melawan kata-kata seperti wahyu Arachne."
  },
  AvgDialog_131207_Content_29 = {
    Text = "Aduh, memang layak disebut Triad... sedikit kekuasaan ini, meskipun berada di dimensi yang begitu jauh, masih bisa mempengaruhi tuan rumah."
  },
  AvgDialog_131207_Content_3 = {
    Text = "Lihat, Penjaga Rahasia {Male=先生,Female=小姐}, betapa indahnya cahaya ini..."
  },
  AvgDialog_131207_Content_30 = {
    Text = "Buat mereka lebih jinak, Penjaga Rahasia {Male=先生,Female=小姐}."
  },
  AvgDialog_131207_Content_4 = {
    Text = "Cahaya ini adalah hadiah dari nasib, ia akan menunjukkan jalan bagi kita menuju Kebahagiaan Tertinggi yang bebas dari penderitaan…"
  },
  AvgDialog_131207_Content_5 = {
    Text = "Nefraea mengulurkan tangan, mengusap jejak cahaya yang ditinggalkan di ruang dimensi. Bayangan jari perlahan-lahan menyusut, merayap di wajah Arachne."
  },
  AvgDialog_131207_Content_6 = {
    Text = "Ayo, kakak, protagonis kita sudah saatnya muncul."
  },
  AvgDialog_131207_Content_7 = {
    Text = "......Nasib bukanlah sesuatu yang bisa dimainkan dan diubah, Nefraea."
  },
  AvgDialog_131207_Content_8 = {
    Text = "Takdir setiap orang sudah ditentukan, membangkitkan dewa itu, mengakhiri segalanya... memalsukan takdir secara paksa akan mendatangkan bencana yang tak bisa kau bayangkan."
  },
  AvgDialog_131207_Content_9 = {
    Text = "Baik yang kau benci maupun yang kau pedulikan, semuanya akan lenyap dalam bencana."
  },
  AvgDialog_131208_Content_1 = {
    Text = "Penghakiman"
  },
  AvgDialog_131208_Content_10 = {
    Text = "Gadis itu menarik napas dalam-dalam dan tersenyum puas."
  },
  AvgDialog_131208_Content_11 = {
    Text = "Bunga iris telah mulai mekar... sebuah musim semi yang sebenarnya telah tiba."
  },
  AvgDialog_131208_Content_12 = {
    Text = "Eh, Xiaofu, apakah aku pernah bertanya padamu, musim apa yang paling kamu suka?"
  },
  AvgDialog_131208_Content_13 = {
    Text = "……Aku tidak memiliki musim yang disukai, Tuan."
  },
  AvgDialog_131208_Content_14 = {
    Text = "Membosankan."
  },
  AvgDialog_131208_Content_15 = {
    Text = "Arachne memutar matanya, mengulurkan tangan yang tidak memegang benang, menangkap sinar matahari yang jatuh dari luar jendela."
  },
  AvgDialog_131208_Content_16 = {
    Text = "Aku menyukai setiap musim, terutama musim semi. Kita sudah lama tidak keluar……Bagaimana kalau kita cari waktu beberapa hari ini untuk pergi berjalan-jalan menikmati alam?"
  },
  AvgDialog_131208_Content_17 = {
    Text = "Di samping rumah besar tempat saya lahir, ada sebuah taman bunga yang dikelola dengan sangat indah, pasti kalian akan menyukainya."
  },
  AvgDialog_131208_Content_18 = {
    Text = "Anda sudah menunggu selama tiga hari…… saatnya untuk membuat keputusan, Tuan."
  },
  AvgDialog_131208_Content_19 = {
    Text = "Pelayan menjalankan tanggung jawabnya, kata-kata dingin seperti hujan es. Memadamkan musim semi yang cemerlang di mata Arachne."
  },
  AvgDialog_131208_Content_2 = {
    Text = "Ciiit——Ciiit——Dewi nasib memutar alat tenunnya."
  },
  AvgDialog_131208_Content_20 = {
    Text = "Ciiit, Ciiit…"
  },
  AvgDialog_131208_Content_21 = {
    Text = "Setelah terhenti sejenak, roda penggulung itu berputar kembali. Frekuensinya lembut, jernih, dan abadi."
  },
  AvgDialog_131208_Content_22 = {
    Text = "Negara yang kita huni ini baru saja mengakhiri seratus tahun peperangan. Orang-orang telah membangun kembali kota mereka di atas reruntuhan, menantikan apa yang akan menjadi perdamaian yang panjang."
  },
  AvgDialog_131208_Content_23 = {
    Text = "Lihat, di sana..."
  },
  AvgDialog_131208_Content_24 = {
    Text = "Mengikuti pandangan Arachne, pelayan melihat sebuah lukisan raksasa yang tergantung di aula. Dia tidak pernah mengerti lukisan itu."
  },
  AvgDialog_131208_Content_25 = {
    Text = "Di antara semua karya besar Tuan Zos, lukisan ini tidak ada yang memperhatikannya, tetapi ini adalah lukisan favorit saya."
  },
  AvgDialog_131208_Content_26 = {
    Text = "Kawanan rusa yang dilukis dengan oker dan struktur geometris itu, meskipun hanya berupa simbol-simbol abstrak, tetap mampu membuat orang merasakan vitalitas kehidupan mereka yang meluap."
  },
  AvgDialog_131208_Content_27 = {
    Text = "Setiap kali melihatnya, aku selalu teringat pada drama favoritku yang paling aku cintai……"
  },
  AvgDialog_131208_Content_28 = {
    Text = "Celah ini sudah ada selama tiga hari, Tuan. Nasib dimensi ini telah terpengaruh oleh Pandangan orang itu."
  },
  AvgDialog_131208_Content_29 = {
    Text = "Jika ini terus berlanjut, tempat yang akan dihancurkan oleh pandangan-Nya jauh lebih dari ini."
  },
  AvgDialog_131208_Content_3 = {
    Text = "Ciiit——Ciiit——Benang nasib berkumpul di tangannya."
  },
  AvgDialog_131208_Content_30 = {
    Text = "Ciiit, ciiit."
  },
  AvgDialog_131208_Content_31 = {
    Text = "Gadis itu menutup mata, menikmati sentuhan sinar matahari. Kamar yang hangat terjebak dalam keheningan, hanya roda penggulung yang masih berputar dengan frekuensi yang abadi."
  },
  AvgDialog_131208_Content_32 = {
    Text = "Kamu masih ingat, sudah berapa banyak takdir dunia yang telah kita susun?"
  },
  AvgDialog_131208_Content_33 = {
    Text = "Jumlah total dua puluh tujuh, Tuan."
  },
  AvgDialog_131208_Content_34 = {
    Text = "Setelah ayah memberiku roda tenun ini, aku pernah mendekati pintu kebenaran itu melalui benang-benangnya. Di balik pintu itu, aku melihat nasib yang akan datang ke dunia ini……"
  },
  AvgDialog_131208_Content_35 = {
    Text = "Aku tahu apa yang menunggu di depan. Aku tahu pilihan seperti apa yang harus aku buat... tapi aku tidak bisa melakukannya."
  },
  AvgDialog_131208_Content_36 = {
    Text = "Kerabat. Teman. Memori. Sejarah megah selama tujuh belas ribu tahun. Teknologi dan seni yang bintang-bintang..."
  },
  AvgDialog_131208_Content_37 = {
    Text = "Setelah melihat jawaban itu, aku mulai menyusun takdir dunia ini... Aku selalu berpikir, takdir telah memberiku kemampuan seperti ini, pasti aku bisa melakukan sesuatu untuk dunia ini."
  },
  AvgDialog_131208_Content_38 = {
    Text = "Ini adalah tanah kelahiranku, juga bayiku……<Shake:Aku……aku tidak sanggup>, Fufu……"
  },
  AvgDialog_131208_Content_39 = {Text = "Tuan……"},
  AvgDialog_131208_Content_4 = {
    Text = "Boneka-boneka antre untuk masuk, melangkah ke dalam jaring besar takdir."
  },
  AvgDialog_131208_Content_40 = {
    Text = "Pelayan itu berjongkok, menghapus air mata tuannya. Di bawah sinar matahari musim semi, suaranya jernih dan teguh."
  },
  AvgDialog_131208_Content_41 = {
    Text = "Anda telah meramalkan hari ini, jadi Anda membiarkan saya menjadi pelayan di sisi Anda."
  },
  AvgDialog_131208_Content_42 = {
    Text = "Seluruh makna hidupku adalah, pada saat ini, memberitahumu apa yang harus dilakukan…"
  },
  AvgDialog_131208_Content_43 = {
    Text = "Anda adalah penguasa takdir, penjaga dari berbagai dimensi ini. Ini adalah jalan yang kejam, tetapi Anda sudah membuat pilihan."
  },
  AvgDialog_131208_Content_44 = {
    Text = "Tiga Dewi Takdir, bertanggung jawab untuk merajut, memotong... dan memutuskan."
  },
  AvgDialog_131208_Content_45 = {
    Text = "Sejak saat kamu membuat pilihan, semua ini adalah tanggung jawab yang telah ditentukan untukmu."
  },
  AvgDialog_131208_Content_46 = {
    Text = "Arachne mengangkat kepalanya, di mata yang kabur itu, celah yang tidak bisa dilihat oleh orang biasa berkilau di cakrawala. Itu selalu ada di sana, di samping sinar matahari musim semi yang hangat, seperti senyuman yang kejam."
  },
  AvgDialog_131208_Content_47 = {
    Text = "Celah berbisik kepada Arachne, menceritakan kepadanya tentang masa depan yang dingin. Dia telah menerima kutukan ini sejak lama, dan ketika kedatangan masa depan, tubuhnya masih bergetar karena ketakutan."
  },
  AvgDialog_131208_Content_48 = {
    Text = "Arachne kembali duduk di depan alat tenun. Setelah ketakutan dan keputusasaan, wajahnya muncul rona merah yang tidak sehat."
  },
  AvgDialog_131208_Content_49 = {
    Text = "Dia membelai benang-benang yang rapat itu, bagaikan seorang ibu membelai wajah anaknya."
  },
  AvgDialog_131208_Content_5 = {
    Text = "Mereka menari. Mereka bernyanyi. Ciiit——ciiit——"
  },
  AvgDialog_131208_Content_50 = {
    Text = "Tahun 804, aku belum bisa berbicara, kepala pelayan memainkan sebuah lagu piano di rumah."
  },
  AvgDialog_131208_Content_51 = {
    Text = "\"Pemakaman Sungai Loaos\" karya Elichion, suara musik itu bagaikan air mancur yang mengalir tenang di luar kuil, aku melihat, bahkan para dewa pun berhenti melangkah demi alunan musik itu……"
  },
  AvgDialog_131208_Content_52 = {
    Text = "Sebuah benang dipotong tanpa suara. Ia melayang tenang di udara, melayang tanpa suara dalam gelombang purna nasib."
  },
  AvgDialog_131208_Content_53 = {
    Text = "Suara musik di aula menghilang, hanya fonograf yang masih berputar. Garis-garis di piringan rekaman terisi, nama lagu yang ditulis dengan huruf indah dicoret."
  },
  AvgDialog_131208_Content_54 = {
    Text = "Elihion menyambut nasibnya yang lain. Di dunia yang sepi ini, kehidupan megahnya tidak pernah ada."
  },
  AvgDialog_131208_Content_55 = {
    Text = "Kassandra, gereja yang dirancangnya lebih layak untuk dipuji dibandingkan dengan dewa-dewa di dalamnya…"
  },
  AvgDialog_131208_Content_56 = {
    Text = "Satu benang lagi putus. Dua ratus kilometer jauhnya, gereja megah itu hancur, runtuh, mata dewa yang penuh belas kasih itu pecah, tidak ada bedanya dengan debu."
  },
  AvgDialog_131208_Content_57 = {
    Text = "Dongeng Mornlin, opera Aldo, lukisan Malmo, puisi Rovel…"
  },
  AvgDialog_131208_Content_58 = {
    Text = "Buku menjadi serpihan kertas, patung menjadi pecahan, lukisan menjadi warna-warna yang tidak teratur."
  },
  AvgDialog_131208_Content_59 = {
    Text = "Dia adalah jurnalis Ming. Dia adalah algojo. Dia mengucapkan nama setiap seniman besar di dunia ini, memotong benang yang menjadi milik mereka."
  },
  AvgDialog_131208_Content_6 = {
    Text = "Sinar matahari menerangi wajah mereka, betapa senangnya——"
  },
  AvgDialog_131208_Content_60 = {
    Text = "Wilderburg, sebuah kota megah yang dimiliki oleh para pahlawan. Kota ini telah mengalami seratus lima kali peperangan, tiga puluh tujuh kali dihancurkan dan dibangun kembali, dua puluh satu penguasa hebat telah meraih prestasi di sini, terjebak dalam pasir dan patah pedang."
  },
  AvgDialog_131208_Content_61 = {
    Text = "Kaum bangsawan bernyanyi di sini, kaum miskin berteriak di sini, penyair meninggalkan larik-larik indah untuknya, suara di tepi sungai Nerkin dan suara meriam bergema di atasnya. Sejarah pahlawannya berakhir hari ini."
  },
  AvgDialog_131208_Content_62 = {
    Text = "Sekelompok benang yang terputus melayang dengan kacau, seperti sebuah tari yang meriah. Dua ribu tiga ratus kilometer jauhnya, kota megah itu runtuh dengan keras."
  },
  AvgDialog_131208_Content_63 = {
    Text = "Tujuh belas ribu tahun keberlangsungan, berdiri kokoh di tengah bencana dan malapetaka, peradaban kuno yang tak pernah runtuh......"
  },
  AvgDialog_131208_Content_64 = {
    Text = "Dalam keadaan lemah, bergetar. Arachne mengangkat tangannya dengan sekuat tenaga, menggenggam benang yang tak berujung di depannya."
  },
  AvgDialog_131208_Content_65 = {
    Text = "Benang itu putus. Delapan ribu kilometer jauhnya, negara besar yang mewarisi peradaban manusia dan tidak pernah terputus, dengan cara ini menghilang dari sejarah manusia, seperti asap yang membubung."
  },
  AvgDialog_131208_Content_67 = {
    Text = "Manusia. Seni. Kota. Negara. Peradaban."
  },
  AvgDialog_131208_Content_68 = {
    Text = "Segalanya sedang runtuh, segalanya sedang menghilang."
  },
  AvgDialog_131208_Content_69 = {
    Text = "<Shake:Kau lihat, Fufu?> Anak pertamaku telah mati, akulah yang membunuhnya dengan tanganku sendiri……"
  },
  AvgDialog_131208_Content_7 = {
    Text = "Ciiit, ciiit."
  },
  AvgDialog_131208_Content_70 = {
    Text = "Air mata jatuh dengan tenang. Arachne tersenyum lemah, menatap keluar jendela. Di antara reruntuhan dunia, hanya manor yang goyang-goyang di luar jendela yang masih berdiri."
  },
  AvgDialog_131208_Content_71 = {
    Text = "Aku pernah berpikir, saat menyusun takdir, jika aku bisa terus melihat tempat di mana aku pernah hidup, itu akan membuatku tidak begitu kesepian di jalan ini."
  },
  AvgDialog_131208_Content_72 = {
    Text = "Sungguh kekanak-kanakan... Bagi seorang algojo yang tidak memiliki pilihan, aku telah menyiapkan hukuman yang paling kejam untuk diriku sendiri."
  },
  AvgDialog_131208_Content_73 = {
    Text = "Dia mengulurkan tangannya, menggerakkan benang samar yang ada di atas kepalanya, yang bahkan dia sendiri tidak bisa melihat dengan jelas, menghubungkan sebagian darinya dengan benang terakhir di dunia ini."
  },
  AvgDialog_131208_Content_74 = {
    Text = "Tuan, ini apa...?"
  },
  AvgDialog_131208_Content_75 = {
    Text = "Romantis membawa kebodohan, kebaikan membawa kerapuhan, kenangan membawa rasa sakit…"
  },
  AvgDialog_131208_Content_76 = {
    Text = "Saya sudah memikirkannya dengan jelas, Xiao Fu. Saya adalah eksekutor yang terkutuk, hal-hal indah itu seharusnya tidak ada pada diri saya."
  },
  AvgDialog_131208_Content_77 = {
    Text = "Anda……bermaksud membunuh sebagian dari diri Anda sendiri? Tapi……ini semua adalah bagian yang paling Anda hargai, bagaimana mungkin Anda……"
  },
  AvgDialog_131208_Content_78 = {
    Text = "Ketika saya masih sangat kecil, saya bermimpi untuk pertama kalinya dalam hidup saya."
  },
  AvgDialog_131208_Content_79 = {
    Text = "Arachne mengulurkan tangan, menangkap sinar matahari yang bersinar di atas reruntuhan tanpa akhir itu."
  },
  AvgDialog_131208_Content_8 = {
    Text = "Roda tenun yang tua mengeluarkan iringan yang lembut, gadis itu duduk di depan roda tenun, bersenandung sebuah lagu dengan melodi yang sederhana."
  },
  AvgDialog_131208_Content_80 = {
    Text = "Dalam mimpi, saya sedang berjalan di atas permukaan danau. Di sekitar saya adalah reruntuhan dan tulang belulang yang tak terhingga, sementara di bawah permukaan danau, bayangan masa kecil saya sedang berjalan di sebuah kerajaan yang indah."
  },
  AvgDialog_131208_Content_81 = {
    Text = "Tidak ada kematian, tidak ada penderitaan, tidak ada pelupaan. Cahaya matahari yang lembut selalu bersinar di sana, kerumunan bernyanyi di sampingnya, tanpa henti..."
  },
  AvgDialog_131208_Content_82 = {
    Text = "Saya tidak bisa melihat ke mana benang saya menuju, tetapi saya rasa, sekarang saya bisa melihat nasib yang ditunjukkan oleh mimpi itu."
  },
  AvgDialog_131208_Content_83 = {
    Text = "Dia berusaha mengangkat sudut bibirnya, mungkin kepada pelayannya sendiri, atau mungkin kepada sesuatu yang lain."
  },
  AvgDialog_131208_Content_84 = {
    Text = "Ibu pernah berkata, jika membalik nama Arachne, itu dibaca sebagai Nefraea. Dalam legenda dunia ini, itu adalah nama dewa musim semi."
  },
  AvgDialog_131208_Content_85 = {
    Text = "Saya menyukai setiap musim, terutama Musim Semi. Musim Semi lebih kecil dari nasib, jauh lebih kecil. Tetapi nasib selalu mengarah pada kematian, sedangkan Musim Semi, Musim Semi hanya membawa Baru lahir……"
  },
  AvgDialog_131208_Content_86 = {
    Text = "Dia memandang ke luar jendela. Di sisi bingkai jendela, nasib dan Musim Semi saling bertatapan untuk terakhir kalinya."
  },
  AvgDialog_131208_Content_87 = {
    Text = "Tinggalkan aku, bayanganku, adik perempuanku tercinta. Bersama semua sifat baik yang ada pada kita, dan semua kenangan indah kita."
  },
  AvgDialog_131208_Content_88 = {
    Text = "Takdir……Aku persembahkan sebagian diriku sepenuhnya kepadamu. Jalan yang sulit ini, akan kutempuh menggantikannya."
  },
  AvgDialog_131208_Content_89 = {
    Text = "Arachne dengan lembut mengelus benang yang terjerat bersama. Benang itu bergetar lembut, seolah-olah sedang berjuang, teriak."
  },
  AvgDialog_131208_Content_9 = {
    Text = "Seberkas cahaya matahari menerobos dari jendela, jatuh di atas plakat bertuliskan \"Moirai\" di samping roda pemintal."
  },
  AvgDialog_131208_Content_90 = {
    Text = "Air matanya mengalir melalui benang itu, menetes di plakat \"Moilai\"."
  },
  AvgDialog_131208_Content_91 = {
    Text = "Kamu sudah bebas, \"Arachne\"."
  },
  AvgDialog_131208_Content_92 = {Text = "Ciiit."},
  AvgDialog_131208_Content_93 = {
    Text = "Benang putus. Di bawah sinar matahari yang hangat di hari musim semi, roda penggulung mengeluarkan desahan terakhir."
  },
  AvgDialog_131209_Content_1 = {
    Text = "Bersatu Kembali"
  },
  AvgDialog_131209_Content_10 = {
    Text = "Jika aku memilih untuk menjadi seorang aktor opera, antrean pembeli tiket di teater pasti akan membentang hingga tiga blok lebih jauh."
  },
  AvgDialog_131209_Content_11 = {
    Text = "Sayang sekali, boneka-boneka Londinium tidak memiliki kesempatan untuk melihat pertunjukan menawanku. Melihat ini, betapa beruntungnya kamu, sayang."
  },
  AvgDialog_131209_Content_12 = {
    Text = "Nefraea dengan kasih sayang perlahan mencubit pipi perempuan itu, seperti seorang ibu yang menyayangi putrinya."
  },
  AvgDialog_131209_Content_13 = {
    Text = "Di tengah aula gereja, paku baja menembus dada, bahu, tulang kering, dan telapak tangan gadis itu, menembus setiap bagian tubuhnya yang memungkinkan untuk digantung dan merasakan sakit, menancapkannya dengan kuat pada lampu berbentuk roda besar."
  },
  AvgDialog_131209_Content_14 = {
    Text = "Nefraea mengangkat tangan yang penuh dengan darah ke ujung hidungnya, menutup mata dengan penuh pesona."
  },
  AvgDialog_131209_Content_15 = {
    Text = "Ah... aroma kehidupan, begitu segar."
  },
  AvgDialog_131209_Content_16 = {
    Text = "Selama bertahun-tahun ini, aku telah mencoba banyak kali, menggigit tubuh anak-anak, menggigit tubuhku sendiri, tetapi bahkan sedikit rasa kehidupan pun tidak bisa ku cicipi."
  },
  AvgDialog_131209_Content_17 = {
    Text = "Takdir yang benar. Kehidupan yang penuh semangat. Betapa mengagumkannya… Tapi tahukah kamu? Seharusnya, kamu juga seperti kami, dibuang ke dalam tumpukan sampah nasib."
  },
  AvgDialog_131209_Content_18 = {
    Text = "Kamu tidak perlu makan, tidak pernah berbicara. Selain kenangan yang disimpan untuknya, kamu tidak memiliki apa-apa, tidak tahu apa-apa."
  },
  AvgDialog_131209_Content_19 = {
    Text = "Nasib sudah lama meninggalkanmu, kasihan kecil. Kau hanyalah boneka yang membuatnya merasa nyaman, seorang penjaga makam yang menjaga kenangan-kenangan itu, mengembara sendirian di panggung hipokrit ini…"
  },
  AvgDialog_131209_Content_2 = {
    Text = "<Shake:La♪ lalala♪>"
  },
  AvgDialog_131209_Content_20 = {
    Text = "Dia memandang gadis yang hampir tidak bernapas, suara bisikannya bergetar karena kesedihan, jari-jarinya yang dingin dengan lembut merapikan helai rambut yang berantakan di pelipis gadis itu."
  },
  AvgDialog_131209_Content_21 = {
    Text = "Sekarang, ibumu yang kejam dari takdir akan segera datang... Apa pun yang terjadi, hadapilah segalanya dengan penampilan yang paling indah, mengerti kan, sayang?"
  },
  AvgDialog_131209_Content_23 = {
    Text = "Setelah mata beradaptasi dengan cahaya redup gereja, yang pertama kali menarik perhatianmu adalah sekelompok lukisan dinding raksasa."
  },
  AvgDialog_131209_Content_24 = {
    Text = "Pewarna seperti lendir dioleskan pada dinding setinggi puluhan meter, membentang terus menerus ke dalam kegelapan yang tak terlihat ujungnya. Megah, suci, kotor, seperti patung penyelamat yang berdiri di dalam saluran pembuangan."
  },
  AvgDialog_131209_Content_25 = {
    Text = "Nyonya yang penuh pengertian membersihkan ruangan untuk para pengunjung, di dalam gereja yang luas hanya ada gema langkah kaki dan napas. Kamu tiba di bawah mural besar, mengangkat kepala dan menatap ke atas."
  },
  AvgDialog_131209_Content_26 = {
    Text = "Seorang wanita duduk di depan roda tenun, sedang memotong benang sutra dengan gunting... Apakah lukisan dinding ini menggambarkan dirimu?"
  },
  AvgDialog_131209_Content_27 = {
    Text = "Sepertinya memang begitu... Saya pikir, ini adalah hal yang ingin disampaikan oleh adik perempuan saya kepada kita."
  },
  AvgDialog_131209_Content_28 = {
    Text = "Arachne tidak terburu-buru mencari \"Kenangan\". Dia mengikuti langkahmu, dengan penuh minat mengamati lukisan dinding ini."
  },
  AvgDialog_131209_Content_29 = {
    Text = "Sebuah sosok yang persis sama, meninggalkan wanita yang sedang duduk, terjatuh ke dalam gua yang gelap..."
  },
  AvgDialog_131209_Content_3 = {
    Text = "Ciiit——Ciiit——Dewi nasib memutar alat tenunnya."
  },
  AvgDialog_131209_Content_30 = {
    Text = "Di dalam gua yang gelap, seorang wanita dan makhluk kegelapan lainnya sedang menarikan tarian yang aneh. Yang dipegangnya adalah…… sebuah roda pemintal?"
  },
  AvgDialog_131209_Content_31 = {
    Text = "Pusat roda pemintal itu memancarkan cahaya terang, bagaikan sebuah lentera, menerangi gua itu……"
  },
  AvgDialog_131209_Content_32 = {
    Text = "Seorang wanita membawa lentera berbentuk roda pemintal ke kota... Sekelompok orang yang mengenakan jubah suci berlutut di depan wanita dan lentera. Pada pakaian mereka terukir... adalah simbol lentera?"
  },
  AvgDialog_131209_Content_33 = {
    Text = "Itu memiliki beberapa perbedaan halus dengan simbol lentera yang pernah kamu lihat, di luar segitiga terbalik yang jahat itu, terdapat lingkaran berbentuk roda pemintal."
  },
  AvgDialog_131209_Content_34 = {
    Text = "Tapi kamu mengerti setiap elemen dari simbol itu. Kamu dengan jelas tahu, itu adalah simbol Gereja Penerang Kuil, itu adalah kelahiran Gereja Penerang Kuil."
  },
  AvgDialog_131209_Content_35 = {
    Text = "Karya terakhir..."
  },
  AvgDialog_131209_Content_36 = {
    Text = "Lukisan dinding terakhir berdiri di ujung lorong, seperti sebuah pintu yang memisahkan nasib. Cat kotor bergelembung di atas lukisan dinding, memantulkan cahaya dan bayangan keruh di dalam gereja."
  },
  AvgDialog_131209_Content_37 = {
    Text = "Wanita itu memegang lentera, berlutut menyembah sosok bayangan yang samar. Di belakang bayangan itu, terdapat sebuah……"
  },
  AvgDialog_131209_Content_38 = {Text = "Uuu……"},
  AvgDialog_131209_Content_39 = {
    Text = "Ketika kamu mengenali bola mata besar yang belum terbuka itu, seberkas rasa sakit yang kuat dan akrab menyerangmu, memicu gelombang besar di dalam Ruang Jiwamu."
  },
  AvgDialog_131209_Content_4 = {
    Text = "Ciiit——Ciiit——Benang nasib berkumpul di tangannya."
  },
  AvgDialog_131209_Content_40 = {
    Text = "Kau buru-buru memalingkan pandangan, menarik napas dalam-dalam, menenangkan gejolak menyakitkan yang bergolak di ruang mentalmu."
  },
  AvgDialog_131209_Content_41 = {
    Text = "<Shake:Hah……hah……>Gereja Lentera……Tohuwabowo……"
  },
  AvgDialog_131209_Content_42 = {
    Text = "Di dimensi ini, Nefraea ternyata...... adalah pencipta Gereja penerang kuil"
  },
  AvgDialog_131209_Content_43 = {
    Text = "Ternyata begitu, aku mengerti!……"
  },
  AvgDialog_131209_Content_44 = {
    Text = "Seperti yang Anda ketahui, Penjaga Rahasia {Male=先生,Female=小姐}. Ketika dewa tertinggi itu hampir terbangun, adikku yang ditinggalkan oleh takdir, melarikan diri dari Jurang Neraka."
  },
  AvgDialog_131209_Content_45 = {
    Text = "Dia mengganggu pandanganku, menyembunyikan sekte ini di bawah panggungku."
  },
  AvgDialog_131209_Content_46 = {
    Text = "Orang yang dia kagumi itu adalah Rasul yang menghubungkan kepada Sang Tuhan Yang Maha Tinggi di dimensi ini."
  },
  AvgDialog_131209_Content_47 = {
    Text = "Kamu sekali lagi menatap bayangan hitam yang kabur yang terhubung dengan Tuhuwa Bo di dinding mural."
  },
  AvgDialog_131209_Content_48 = {
    Text = "Saya mengerti... Nefraea ingin melakukan, yaitu mengandalkan kekuatan orang itu Rasul, untuk membangun kembali koneksi dengan Touva Wave!..."
  },
  AvgDialog_131209_Content_49 = {
    Text = "Tetapi jika demikian, mengapa dia harus memburu para Rahasia itu..."
  },
  AvgDialog_131209_Content_5 = {
    Text = "Boneka-boneka antre untuk masuk, melangkah ke dalam jaring besar takdir."
  },
  AvgDialog_131209_Content_50 = {
    Text = "Deng!——"
  },
  AvgDialog_131209_Content_51 = {
    Text = "Suara lonceng keruh terdengar dari menara gereja di luar, seperti sebuah wahyu kotor."
  },
  AvgDialog_131209_Content_52 = {
    Text = "Gereja yang besar mengeluarkan dentuman yang berat. Dalam getaran yang panjang, dinding batu yang dihiasi dengan lukisan kotor perlahan-lahan terangkat."
  },
  AvgDialog_131209_Content_53 = {
    Text = "Itu adalah!!"
  },
  AvgDialog_131209_Content_54 = {
    Text = "Arachne......Nyonya......"
  },
  AvgDialog_131209_Content_55 = {
    Text = "Aduh... Kenangan kecil kami, suaranya benar-benar lemah sampai membuat orang merasa kasihan."
  },
  AvgDialog_131209_Content_56 = {
    Text = "Nefraea! Lepaskan dia"
  },
  AvgDialog_131209_Content_57 = {
    Text = "Tubuh gadis kecil tergantung di atas rangka lampu pemintal yang megah, darah merah darah mengalir perlahan di atas marmer putih yang bersih."
  },
  AvgDialog_131209_Content_58 = {
    Text = "Cahaya terang bersinar di belakang gadis itu, menggambarkan siluet suci dari tubuh berdarah ini."
  },
  AvgDialog_131209_Content_59 = {
    Text = "Nefraea, jangan lagi melakukan pertarungan yang tidak berarti ini. Lepaskan dia."
  },
  AvgDialog_131209_Content_6 = {
    Text = "Mereka menari. Mereka bernyanyi. Ciiit——ciiit——"
  },
  AvgDialog_131209_Content_60 = {
    Text = "Oh? Dewi nasib kita, sekarang mulai peduli pada \"kenangan\"nya?"
  },
  AvgDialog_131209_Content_61 = {
    Text = "Kau tidak pernah peduli pada mereka, kau meninggalkan mereka, Arachne."
  },
  AvgDialog_131209_Content_62 = {
    Text = "Nefraea, saya tahu kamu ingin memanggil Rasul, membangkitkan Touva Wave kembali... Ada sesuatu yang bisa kita diskusikan lagi, tidak perlu membunuh mereka..."
  },
  AvgDialog_131209_Content_63 = {
    Text = "Caramu mengulur waktu sungguh kekanak-kanakan yang menggemaskan, %player%."
  },
  AvgDialog_131209_Content_64 = {
    Text = "Kau tidak mengerti apa-apa. Aku tidak pernah membunuh mereka. Aku hanya mengantarkan mereka pulang."
  },
  AvgDialog_131209_Content_65 = {
    Text = "Membawa kalian ke sini, hanyalah untuk melihat bersama-sama, akhir yang sempurna bagi mereka."
  },
  AvgDialog_131209_Content_66 = {
    Text = "Adegan kedua, scene ketiga. Saya menamakannya, \"Berkumpul\"."
  },
  AvgDialog_131209_Content_67 = {
    Text = "Nefraea dengan sinis memandangmu. Kuku jari-jarinya menyentuh wajah \"Kenangan\", meninggalkan jejak darah yang halus di atasnya."
  },
  AvgDialog_131209_Content_68 = {
    Text = "Dia membungkuk, memandang dengan kasih sayang wajah gadis yang gemetar karena kelemahan dan ketakutan."
  },
  AvgDialog_131209_Content_69 = {
    Text = "Anak baik, jangan takut. Segera, kita akan sampai di rumah."
  },
  AvgDialog_131209_Content_7 = {
    Text = "Mereka mati bersama jaring raksasa, tanpa suara."
  },
  AvgDialog_131209_Content_70 = {
    Text = "Selamat tinggal kenangan burukmu, Kakak tersayang——"
  },
  AvgDialog_131209_Content_71 = {
    Text = "Tunggu... Nefraea!"
  },
  AvgDialog_131209_Content_72 = {Text = "Pak—"},
  AvgDialog_131209_Content_73 = {
    Text = "Di tengah suara jari yang ceria dari Nefraea, tubuh perempuan meledak seperti kembang api merah yang cerah."
  },
  AvgDialog_131209_Content_74 = {
    Text = "Cahaya lentera menerangi jejak darah yang memercik, memantulkan bunga merah darah di wajah kalian."
  },
  AvgDialog_131209_Content_75 = {
    Text = "Bola darah terbang ke udara, berhenti, lalu kembali, merayap dengan serakah menuju tubuh Nefraea, mewarnai setiap inci tubuh Nefraea dengan merah."
  },
  AvgDialog_131209_Content_76 = {
    Text = "Tetesan darah terus mengalir ke bawah, menyusup ke dalam pakaian dan kulitnya, menyusup ke setiap pembuluh darahnya, mengalir deras di dalam tubuhnya yang ramping."
  },
  AvgDialog_131209_Content_77 = {
    Text = "Lidah menjilat darah di tepi bibir, Nefraea dengan senang hati mengagumi kuku-kuku yang ternoda darah, seperti tuan rumah yang berpakaian megah, bersiap menyambut sebuah pesta berkumpul kembali."
  },
  AvgDialog_131209_Content_78 = {
    Text = "Selamat datang kembali, sayang."
  },
  AvgDialog_131209_Content_79 = {Text = "Berhenti!!"},
  AvgDialog_131209_Content_8 = {
    Text = "Suara nyanyian bergema di dalam gereja yang luas. Nefraea mengulurkan kedua tangannya, menikmati residu suaranya."
  },
  AvgDialog_131209_Content_80 = {
    Text = "Cahaya perak mekar di tanganmu, kau berlari menuju Nefraea."
  },
  AvgDialog_131209_Content_81 = {
    Text = "Di bawah cahaya berdarah yang suci, bayangan hitam yang tak terhitung jumlahnya membentang di atas mural kotor, menghalangi jalanmu..."
  },
  AvgDialog_131209_Content_9 = {
    Text = "Bagaimana, apakah suaraku enak didengar?"
  },
  AvgDialog_131210_Content_1 = {
    Text = "Tidak disangka saat bertemu lagi, kamu akan berada dalam keadaan yang begitu berantakan."
  },
  AvgDialog_131210_Content_2 = {Text = "Taisses…"},
  AvgDialog_131210_Content_3 = {
    Text = "Tavie benar. Tidak apa-apa, Penjaga Rahasia."
  },
  AvgDialog_131210_Content_4 = {
    Text = "Kau pernah bilang akan membawaku menyaksikan akhir yang lain. Aku percaya padamu, dari awal hingga akhir."
  },
  AvgDialog_131210_Content_5 = {
    Text = "Baik berhenti di sini, atau melewatiku, aku selalu berada di sisimu."
  },
  AvgDialog_131211_Content_1 = {Text = "Kepompong"},
  AvgDialog_131211_Content_10 = {
    Text = "Pengalaman seperti ini, saya tidak ingin mengalaminya lagi..."
  },
  AvgDialog_131211_Content_11 = {
    Text = "Kau tidak yakin apakah itu kata-kata jujurmu. Kau mengepalkan tinjumu, kembali menyesuaikan diri dengan tubuh yang baru saja kau kendalikan bersama\"N\"."
  },
  AvgDialog_131211_Content_12 = {
    Text = "Pandanganmu perlahan menjadi jelas, kamu mengusap kepalamu yang nyeri, berjalan menuju sosok kurus yang berlutut di tepi panggung."
  },
  AvgDialog_131211_Content_13 = {
    Text = "Nefraea, rencanamu sudah......"
  },
  AvgDialog_131211_Content_14 = {
    Text = "Tolong hati-hati."
  },
  AvgDialog_131211_Content_16 = {
    Text = "Seolah-olah ada benang yang menarik lembut, langkahmu melambat sedikit. Sebuah cakar laba-laba hitam yang tajam hampir mengenai matamu, melintas tepat di depanmu."
  },
  AvgDialog_131211_Content_17 = {
    Text = "Delapan cabang raksasa yang beracun merobek pakaian di punggungnya, bergerak di udara, terdistorsi, dan berjuang. Nefraea tampaknya tidak peduli dengan semua ini."
  },
  AvgDialog_131211_Content_18 = {
    Text = "Fragmen Lorong Dimensi melayang di sekelilingnya seperti kembang api yang jatuh. Air matanya jatuh, membasahi roda pemintal yang redup dan kehilangan cahaya di tangannya."
  },
  AvgDialog_131211_Content_19 = {
    Text = "Lorong Dimensi telah menghilang, kamu tidak memiliki kesempatan lagi."
  },
  AvgDialog_131211_Content_2 = {
    Text = "……Menjaga……"
  },
  AvgDialog_131211_Content_20 = {
    Text = "Nasib berjalan di jalurnya yang seharusnya, Nefraea. Terimalah itu."
  },
  AvgDialog_131211_Content_21 = {
    Text = "Kesempatan?… Hehehehe..."
  },
  AvgDialog_131211_Content_22 = {
    Text = "Siluet yang kurus bergetar karena tawa, dengan anggota tubuh yang beracun melukis jejak menyedihkan di udara."
  },
  AvgDialog_131211_Content_23 = {
    Text = "Aku tidak pernah memiliki kesempatan, dan juga tidak pernah membutuhkan kesempatan."
  },
  AvgDialog_131211_Content_24 = {
    Text = "Kebebasan, kanak-kanak, keluarga, cinta, diri sendiri… nasib telah merenggut segalanya dari kita, aku tidak akan pernah, tidak akan pernah seperti dirimu, menjadi tahanannya."
  },
  AvgDialog_131211_Content_25 = {
    Text = "Nefraea perlahan-lahan berdiri, menempatkan tubuhnya di dalam roda pemintal yang redup dan hancur itu."
  },
  AvgDialog_131211_Content_26 = {
    Text = "Perhatikan baik-baik, Arachne! Hal-hal yang sangat kau inginkan namun tak berani kau lakukan, akan aku lakukan untukmu"
  },
  AvgDialog_131211_Content_27 = {
    Text = "Hampir adalah suara teriakan marah, tubuh Nefraea tampaknya seketika tertusuk oleh ribuan Spike. Darah mengalir keluar dari tubuhnya, terhubung pada roda pemintal yang hancur itu, seperti jaring berdarah."
  },
  AvgDialog_131211_Content_28 = {
    Text = "<Shake:@2————!>"
  },
  AvgDialog_131211_Content_29 = {
    Text = "Sebuah jeritan frekuensi tinggi yang tidak bisa ditanggung oleh manusia berasal dari kepala Nefraea. Tubuhnya bergetar karena rasa sakit yang hebat, dan pola pembuluh darah ungu gelap terlihat jelas di tubuhnya."
  },
  AvgDialog_131211_Content_3 = {
    Text = "Penjaga Rahasia {Male=先生,Female=小姐}."
  },
  AvgDialog_131211_Content_30 = {
    Text = "Fragmen saluran dimensi tampaknya tertarik oleh sesuatu, berhenti mengalir, perlahan-lahan berkumpul menuju jaring yang terbuat dari darah segar. Roda pemintal yang redup, kembali menyala dengan cahaya berdarah."
  },
  AvgDialog_131211_Content_31 = {
    Text = "Heh……Hahahaha……! <Big:<Shake:Jika tidak ada dewa, maka akulah yang akan menjadi dewa itu!>>"
  },
  AvgDialog_131211_Content_32 = {
    Text = "Ceritaku……panggungku……tidak akan pernah berakhir! Aku akan memberikan jaring yang seharusnya tidak ada ini……<Big:<Shake:<Red:pembebasan!!!>>>"
  },
  AvgDialog_131211_Content_33 = {
    Text = "Dalam jeritan menyakitkan Nefraea, seluruh Teater Nasib bergetar hebat. Boneka-boneka di atas panggung terbalik, bertabrakan, benang yang menghubungkan boneka-boneka itu kusut dan saling melilit..."
  },
  AvgDialog_131211_Content_34 = {
    Text = "Arachne menatap sosok yang tidak jauh di sana, yang tergerus oleh kekuatan dan kegilaan dari fragmen dimensi. Di dalam matanya yang dalam seperti kolam, muncul gelombang kesedihan, seperti hari ketika dia pertama kali melepaskan dirinya."
  },
  AvgDialog_131211_Content_35 = {
    Text = "Saya telah mencoba membebaskanmu dari kutukan ini... Sayangnya, saya salah, Nefraea."
  },
  AvgDialog_131211_Content_36 = {
    Text = "Kutukan tidak bisa dihindari, kandang, kita tidak akan pernah bisa melarikan diri…"
  },
  AvgDialog_131211_Content_37 = {
    Text = "Fragmen-fragmen itu… roda tenun itu…"
  },
  AvgDialog_131211_Content_38 = {
    Text = "Nefraea sedang menyerap kekuatan yang tersisa di lorong dimensi! Dia... dia ingin menjadikan dirinya sebagai wick!!"
  },
  AvgDialog_131211_Content_39 = {
    Text = "Suara helaan napas yang lembut, bergema jelas di dalam gedung opera yang goyang-goyang ini."
  },
  AvgDialog_131211_Content_4 = {
    Text = "<Shake:Umh……uhuk uhuk……>"
  },
  AvgDialog_131211_Content_40 = {
    Text = "Tolong berdiri tegap, Penjaga Rahasia {Male=先生,Female=小姐}."
  },
  AvgDialog_131211_Content_41 = {Text = "Apa..."},
  AvgDialog_131211_Content_42 = {
    Text = "<Shake:BLARR——>"
  },
  AvgDialog_131211_Content_43 = {
    Text = "Suara belum reda, seluruh teater tiba-tiba terbelah. Nefraea dengan ganas mencabik-cabik benang nasib, di celah yang menakutkan, bangunan kota dan serpihan dimensi yang berwarna-warni terjerat satu sama lain."
  },
  AvgDialog_131211_Content_44 = {
    Text = "Panggung utama teater hancur menjadi beberapa bagian, fragmen masa lalu, masa depan, dan sekarang saling bertabrakan secara kacau di atas panggung yang rusak, menyusun kembali menjadi pemandangan yang tidak dapat kamu pahami."
  },
  AvgDialog_131211_Content_45 = {
    Text = "Arachne......jaringmu......"
  },
  AvgDialog_131211_Content_46 = {
    Text = "Roda pemintal di tangan Arachne berputar dengan cepat, dimensi abu sisa yang luas mengalir keluar dari tubuh Arachne, mengikuti benang di roda pemintal, mengisi kekosongan yang hancur di jaring takdir, dengan susah payah menjaga panggung agar terhindar dari nasib yang hancur."
  },
  AvgDialog_131211_Content_47 = {
    Text = "Di bawah tarikan benang, kamu dengan susah payah berdiri."
  },
  AvgDialog_131211_Content_48 = {
    Text = "Menyerap kekuatan yang tertebar, mengubah arah seluruh jaring takdir... Kamu bukan pecahan-Nya, tidak mampu menanggung tekanan seperti ini. Kamu tidak perlu mati dengan begitu menyakitkan, Nefraea."
  },
  AvgDialog_131211_Content_49 = {
    Text = "Penderitaan? Tidak, saya sangat senang, Kakak! Di dalam Neraka selama bertahun-tahun, saya membayangkan hari ini setiap detik."
  },
  AvgDialog_131211_Content_5 = {
    Text = "Aku ini……"
  },
  AvgDialog_131211_Content_50 = {
    Text = "Justru ilusi inilah yang membuatku bertahan hingga hari ini…"
  },
  AvgDialog_131211_Content_51 = {
    Text = "Gema tawa kegilaan Nefraea bergema di ruang hancur teater. Dia mengangkat kepalanya, dengan keserakahan menyerap cahaya redup yang tersisa di antara pecahan."
  },
  AvgDialog_131211_Content_52 = {
    Text = "Dewa yang terjatuh dalam tidur, rasul yang dicuri nasibnya... Hahaha... Tidak masalah, semua ini tidak akan menghentikanku. Jika Dewa tidak dapat membawa berkah, maka biarlah aku yang membawanya untuk-Nya!"
  },
  AvgDialog_131211_Content_53 = {
    Text = "Wahai para pembalas dendam takdir, sekarang, <Red:naiklah ke panggung milik kalian!>"
  },
  AvgDialog_131211_Content_54 = {
    Text = "Nefraea tiba-tiba mengangkat tangannya. Cairan hitam tak berujung mengalir dari tubuh Nefraea, membangun jaring laba-laba hitam di dalam kekosongan teater ini."
  },
  AvgDialog_131211_Content_55 = {
    Text = "Dendam tak terhitung dari mereka yang pernah dibuang oleh takdir menjelma menjadi wujud nyata, merangkak keluar tanpa henti melalui jaring laba-laba hitam raksasa itu, menerjang ke arah kalian."
  },
  AvgDialog_131211_Content_56 = {
    Text = "Arachne, di tubuh kita......！"
  },
  AvgDialog_131211_Content_57 = {
    Text = "Kau tiba-tiba menemukan, seutas benang hitam yang bisa kau lihat muncul samar dari tubuh Arachne."
  },
  AvgDialog_131211_Content_58 = {
    Text = "Kau mengangkat kepala, melihat seutas benang hitam yang juga kabur menjulur dari tubuhmu, dari setiap panggung, dari setiap tubuh boneka, menghubungkan ke roda pemintal di tangan Nefraea."
  },
  AvgDialog_131211_Content_59 = {
    Text = "Salam sejahtera, Arachne! Berkah untukmu, dewi nasib"
  },
  AvgDialog_131211_Content_6 = {
    Text = "Pusing yang kuat dan kejang perut adalah sisa-sisa kesukacitaan, kamu menahan rasa mual dan perlahan bangkit."
  },
  AvgDialog_131211_Content_60 = {
    Text = "Ayo, tarik pedang kalian, prajurit-prajurit! Bertarunglah demi nasib kita"
  },
  AvgDialog_131211_Content_61 = {
    Text = "Nona Arachne, akui nasibmu... jangan lagi melawan dengan sia-sia..."
  },
  AvgDialog_131211_Content_62 = {
    Text = "Jangan khawatir, sayang. Pembebasanmu akan segera tiba, cepat, cepat..."
  },
  AvgDialog_131211_Content_63 = {
    Text = "Nefraea yang kelam berputar dengan gila, boneka-boneka di atas panggung berubah menjadi bayangan di Jurang, melangkah di atas jaring hitam yang baru ditenun di bawah tarikan benang."
  },
  AvgDialog_131211_Content_64 = {
    Text = "Arachne perlahan-lahan menutup mata, tangan yang menggenggam benang bergetar sedikit karena rasa sakit."
  },
  AvgDialog_131211_Content_65 = {
    Text = "Nefraea, mereka tidak dapat membantumu menjadi dewa yang bisa menghancurkan segala nasib... yang kamu lakukan hanya akan membuat mereka mengalami kehampaan yang menyakitkan sekali lagi."
  },
  AvgDialog_131211_Content_66 = {
    Text = "Lalu apa bedanya? Balas dendam, selain balas dendam, kita tidak menginginkan apa-apa lagi! Benar kan, anak-anak yang terbuang dari nasib?"
  },
  AvgDialog_131211_Content_67 = {
    Text = "<Shake:Hehehe……Hahahaha……!>"
  },
  AvgDialog_131211_Content_68 = {
    Text = "Suara tawa yang tajam, megah, dan menyayat hati datang dari jaring laba-laba hitam yang tak berujung, seperti sebuah paduan suara penuh penderitaan."
  },
  AvgDialog_131211_Content_69 = {
    Text = "Nasib yang Terbuang tertawa terbahak-bahak dan meratap, menghalangi di depan Nefraea."
  },
  AvgDialog_131211_Content_7 = {
    Text = "Kesadaran rasul telah meninggalkan roda pemintal itu, dan kehilangan keterhubungan dengan dewa, sekarang sudah hancur sepenuhnya. Kekuatan plasmid juga telah kembali tenang."
  },
  AvgDialog_131211_Content_70 = {
    Text = "Sekarang, pintu Jurang telah sepenuhnya terbuka. Ayo, Arachne, lihatlah nasib yang kamu ciptakan dengan tanganmu sendiri, lihatlah anak-anak yang kamu cintai"
  },
  AvgDialog_131211_Content_71 = {
    Text = "Lihatlah penderitaan mereka, keputusasaan mereka... Lihatlah mereka, lalu, bunuh mereka sekali lagi"
  },
  AvgDialog_131211_Content_72 = {
    Text = "Lihatlah segala takdir berputar di tanganku, hancurkan!…… Lihatlah aku, jadilah dewa yang membawa akhir"
  },
  AvgDialog_131211_Content_73 = {
    Text = "Serpihan Dimensi yang membawa Kekuatan dewa dan kehendak Kegilaan, satu per satu menusuk ke dalam tubuh Nefraea, darah terus mengalir ke dalam roda pemintal Nefraea."
  },
  AvgDialog_131211_Content_74 = {
    Text = "Wajahnya berkedut kesakitan, tawanya semakin gila."
  },
  AvgDialog_131211_Content_75 = {
    Text = "Dia memandang panggung yang hancur dengan penuh harapan, seperti seorang penulis naskah yang sedang menunggu pertunjukan perdana karyanya."
  },
  AvgDialog_131211_Content_76 = {
    Text = "Jurang nasib itu, sudah kedatangan di panggung ini... Nefraea sedang pengorbanan dirinya."
  },
  AvgDialog_131211_Content_77 = {
    Text = "Dia ingin mengubah segalanya di sini, termasuk kita, menjadi bonekanya. Dia ingin menjadi Dewa itu. Dia… ingin menjadi nasib itu sendiri."
  },
  AvgDialog_131211_Content_78 = {
    Text = "Suara tenang Arachne seolah-olah milik seseorang yang tidak pernah terlibat dalam pertunjukan. Abu sisa dimensi yang diambil kembali melingkari ujung jarinya seperti pasir ringan, terus-menerus."
  },
  AvgDialog_131211_Content_79 = {
    Text = "Roda pemintal Dia berputar dengan sulit, berusaha mempertahankan nasib yang sedang dihancurkan oleh Nefraea, menghentikan benang hitam itu masuk ke tangan Nefraea."
  },
  AvgDialog_131211_Content_8 = {
    Text = "Kamu telah menyelesaikan pertunjukan yang luar biasa."
  },
  AvgDialog_131211_Content_80 = {
    Text = "Abu sisa dimensi sudah diambil kembali, kini aku tidak perlu lagi merasa ragu."
  },
  AvgDialog_131211_Content_81 = {
    Text = "Tolong bantu saya, coba dekati dia. Roda pemintal Nefraea akan berhenti berputar, nasib yang salah ini, saya akan memperbaikinya bersama Anda."
  },
  AvgDialog_131211_Content_82 = {
    Text = "Tolong bantu aku…… untuk nasib yang ditinggalkan ini, bawa kebebasan."
  },
  AvgDialog_131211_Content_9 = {
    Text = "Huh… sulit dipercaya, kata-kata itu baru saja keluar dari mulutku."
  },
  AvgDialog_131212_Content_1 = {
    Text = [[
Saat yang sama
di ujung kota yang lain]]
  },
  AvgDialog_131212_Content_10 = {
    Text = "Nomor enam diambil oleh duke dari kandang kuda di perkebunan dan dikirim ke arena pacuan kuda, kali ini pasti nomor enam yang akan menang, dengarkan aku, beli nomor enam pasti tidak akan salah"
  },
  AvgDialog_131212_Content_11 = {
    Text = "Suara riuh di dalam kereta bawah tanah berkumpul menjadi arus mengapung yang melompat, Arachne diam-diam menatap lampu-lampu yang mendekat dan menjauh di luar jendela, tersenyum sambil mendengarkan bonekanya berbicara tentang pertunjukan, balapan kuda, dan pernikahan."
  },
  AvgDialog_131212_Content_12 = {
    Text = "Dia dengan tenang menggoyangkan roda penggulung di tangannya. Di antara jutaan benang yang rumit itu, dia menikmati ketenangan saat ini."
  },
  AvgDialog_131212_Content_13 = {
    Text = "Tuan, tujuan kita hampir tiba. Kereta untuk berpindah sudah siap, saudari kita sudah menunggu di sana."
  },
  AvgDialog_131212_Content_14 = {Text = "Anak baik."},
  AvgDialog_131212_Content_15 = {
    Text = "Dia dengan enggan melirik sekeliling pada boneka-boneka yang masih beraksi, seperti seorang penonton yang enggan meninggalkan kursi."
  },
  AvgDialog_131212_Content_16 = {
    Text = "Apakah kamu masih ingat, sudah berapa lama kita tidak meninggalkan teater?"
  },
  AvgDialog_131212_Content_17 = {
    Text = "Sejak hari aku menjadi laba-laba dingin, aku selalu berada di sisimu, tidak pernah pergi. Sampai sekarang... lima puluh tahun? Atau enam puluh tahun? Aku juga agak lupa."
  },
  AvgDialog_131212_Content_18 = {
    Text = "Namun kali ini meninggalkan teater, sudah terlalu lama."
  },
  AvgDialog_131212_Content_19 = {
    Text = "Ini harus disyukuri kepada Nefraea. Jika bukan karena kedatangannya, saya juga tidak akan memiliki kesempatan untuk tinggal di luar teater selama ini."
  },
  AvgDialog_131212_Content_2 = {
    Text = "Tuan ini, silakan tunjukkan tiket Anda."
  },
  AvgDialog_131212_Content_20 = {
    Text = "Sejalan dengan aksi di pihak Penjaga, dalam beberapa hari ini kami telah memburu ratusan Pelayan dari Abyss. Setelah menyelamatkan \"Kenangan\", kita harus kembali ke teater."
  },
  AvgDialog_131212_Content_21 = {
    Text = "Lain kali ada kesempatan keluar, entahlah kapan……"
  },
  AvgDialog_131212_Content_22 = {
    Text = "Sepertinya merasakan pikiran Arachne, cahaya di luar kereta bawah tanah redup. Dia menatap ke luar jendela yang gelap, mencari kenangan biasa tentang dirinya di antara ingatan peradaban yang tak terhitung jumlahnya."
  },
  AvgDialog_131212_Content_23 = {
    Text = "Jarum jam berputar selama dua detik. Pemilik kota menyadari bahwa suara percakapan yang mengalir seperti air di kereta bawah tanah tampaknya menghilang pada saat gerbong memasuki kegelapan."
  },
  AvgDialog_131212_Content_24 = {
    Text = "Tuan, sepertinya di sini ada sedikit..."
  },
  AvgDialog_131212_Content_25 = {
    Text = "Karalu——"
  },
  AvgDialog_131212_Content_26 = {
    Text = "Pelayan darah yang dingin menyemprotkan ke wajah Arachne yang tenang, mengeluarkan aroma segar seperti bunga iris."
  },
  AvgDialog_131212_Content_27 = {
    Text = "Cahaya di luar jendela menyala. Arachne melihat tubuh pelayan yang terputus, bilah tajam yang melintasi tubuhnya dan terus menuju dirinya, serta setelah bilah tajam itu, boneka-boneka yang mengalir ke arahnya seperti kawanan binatang."
  },
  AvgDialog_131212_Content_29 = {
    Text = "Sistem rem mengeluarkan suara gesekan yang lelah, angin sepoi-sepoi yang dihasilkan mengangkat helai-helai rambut pelayan lainnya."
  },
  AvgDialog_131212_Content_3 = {
    Text = "Bukankah sudah diperiksa saat masuk stasiun? Uang pembayar pajak terbuang seperti ini..."
  },
  AvgDialog_131212_Content_30 = {
    Text = "Ah! Sudah tiba"
  },
  AvgDialog_131212_Content_31 = {
    Text = "Pintu mobil terbuka, tetapi kerumunan orang yang ramai tidak muncul. Hanya aliran darah yang berbau amis, mengalir dari setiap celah pintu, seperti sebuah ensemble yang tak bersuara."
  },
  AvgDialog_131212_Content_32 = {
    Text = "Menginjak sungai darah yang mengiringi irama ini, Arachne melangkah keluar dari gerbong dengan perlahan. Pakaian nya bersih tanpa noda, roda pemintal nya masih berputar, tak pernah berhenti."
  },
  AvgDialog_131212_Content_33 = {Text = "Ini…"},
  AvgDialog_131212_Content_34 = {
    Text = "Sebuah pertunjukan teater interaktif yang luar biasa. Sebagai penonton dan aktor, pengalaman ini jauh lebih menarik daripada yang ditulis oleh penulis naskah."
  },
  AvgDialog_131212_Content_35 = {
    Text = "Dia melirik sekilas dayang di hadapannya, wajahnya yang tenang tak menunjukkan emosi apa pun."
  },
  AvgDialog_131212_Content_36 = {
    Text = "Pelayan saya telah menemani saya di samping selama bertahun-tahun, saya tidak sering menyentuh benang nasib mereka."
  },
  AvgDialog_131212_Content_37 = {
    Text = "Di dalam teater yang membosankan ini, mereka adalah salah satu dari sedikit kehidupan yang hidup."
  },
  AvgDialog_131212_Content_38 = {
    Text = "Kau telah membunuh dua pelayanku hari ini. Penghancuran nasib akan ada harganya, Nefraea."
  },
  AvgDialog_131212_Content_39 = {
    Text = "Hehehehe...<Shake:Haha!>Betapa mulianya, Arachne."
  },
  AvgDialog_131212_Content_4 = {
    Text = "Hei, Charlie, di mana bros saya?"
  },
  AvgDialog_131212_Content_40 = {
    Text = "Seperti mentega yang jatuh ke dalam panci timah yang mendidih, tubuh pelayan mulai meleleh. Di bawah cairan lengket hitam yang mendidih dan kotor, wajah yang persis sama dengan Arachne tertawa lebar."
  },
  AvgDialog_131212_Content_41 = {
    Text = "\"Lihat, aku adalah pengendali takdir, algojo yang bertugas! Aku akan memilih takdir yang benar, mengirimkan semua kesalahan ke dalam jurang kehampaan...\""
  },
  AvgDialog_131212_Content_42 = {
    Text = "Kamu adalah idolaku, keyakinanku, kakak tersayang. Aku hanya sedang memainkan peranmu."
  },
  AvgDialog_131212_Content_43 = {
    Text = "Bagaimana, apakah saya sebagai pelajar sudah melakukan dengan baik?"
  },
  AvgDialog_131212_Content_44 = {
    Text = "Arachne diam-diam tatap mata yang memandangnya. Itu penuh semangat, cerah, dipenuhi harapan, seolah-olah hanya berasal dari seseorang yang menunggu pujian dari kakaknya."
  },
  AvgDialog_131212_Content_45 = {
    Text = "Peron, pintu tangga, tiang koridor, terowongan... saat dia berbicara, tak terhitung banyaknya bayangan muncul di setiap tempat yang bisa dia pikirkan."
  },
  AvgDialog_131212_Content_46 = {
    Text = "Aroma gelap yang keruh terhubung erat, berkumpul di tangan Nefraea, seperti jaring raksasa yang semakin mendekat ke Arachne."
  },
  AvgDialog_131212_Content_47 = {
    Text = "Sudut mulut Arachne terangkat lembut."
  },
  AvgDialog_131212_Content_48 = {
    Text = "Aku belum pernah membayangkan, akan ada orang yang mencoba menjebakku dengan jaring."
  },
  AvgDialog_131212_Content_49 = {
    Text = "Kamu pernah melihat ulat sutra, kakak? Itu adalah sejenis serangga yang berasal dari Timur Jauh, mereka tidak melakukan apa-apa setiap hari, hanya tahu terus-menerus makan, mengeluarkan benang... kemudian, menunggu kepompong yang terbuat dari benang itu untuk mengurung diri mereka."
  },
  AvgDialog_131212_Content_5 = {
    Text = "Bukankah saat keluar sudah diberi tahu untuk tidak mengenakan pakaian itu?"
  },
  AvgDialog_131212_Content_50 = {
    Text = "Hampir semua pelayanmu telah lenyap di berbagai sudut kota ini, di dalam kereta ini. Mereka pernah menemanimu, menghabiskan tahun-tahun yang panjang dalam kehampaan."
  },
  AvgDialog_131212_Content_51 = {
    Text = "Kau membawa mereka pada akhir yang seharusnya tidak terjadi. Nasib tidak dapat dilawan, Nefraea."
  },
  AvgDialog_131212_Content_52 = {
    Text = "Maksudmu, akhir mereka seharusnya adalah tetap tinggal di dalam jurang kegelapan itu, tenggelam dalam waktu yang tak berujung... Benarkah, penguasa nasib yang mulia?"
  },
  AvgDialog_131212_Content_53 = {
    Text = "Nefraea tersenyum sambil menggelengkan kepala."
  },
  AvgDialog_131212_Content_54 = {
    Text = "Aku mencintai mereka lebih dari yang kau bayangkan, kakak. Tapi mereka memberitahuku, jika kematian bisa membebaskan mereka dari nasib terpenjara lagi, mereka akan menyambutnya tanpa ragu..."
  },
  AvgDialog_131212_Content_55 = {
    Text = "Setelah pembantaian di dalam kereta bawah tanah ini, berapa banyak abu sisa yang kau miliki untuk memperbaiki nasibmu?"
  },
  AvgDialog_131212_Content_56 = {
    Text = "Nefraea dengan angkuh mengangkat roda pemintal hitam di tangannya. Ribuan benang yang membentang dari panggung kota terhubung pada roda pemintal yang diam itu."
  },
  AvgDialog_131212_Content_57 = {
    Text = "Nasib kota ini tergantung pada benang-benang yang ada di tanganku. Aku tidak memiliki kemampuan untuk mengendalikannya, banyak hal menarik yang tidak bisa dilakukan, sungguh menyedihkan..."
  },
  AvgDialog_131212_Content_58 = {
    Text = "Namun untungnya, memperbaiki mereka membutuhkan banyak abu sisa, tetapi polusi tidak diperlukan."
  },
  AvgDialog_131212_Content_59 = {
    Text = "Asalkan aku melepaskan dengan lembut seperti ini... teatermu, panggungmu, akan berubah menjadi tempat pembiakan chaos yang paling sempurna, seperti... seperti tempat yang pernah aku tinggali selama bertahun-tahun."
  },
  AvgDialog_131212_Content_6 = {
    Text = "Ya ampun… Saya sudah mempersiapkan pesta hari ini selama sebulan penuh! Tanpa brooch ini, gaun ini sama saja dengan kain penutup peti mati…"
  },
  AvgDialog_131212_Content_60 = {
    Text = "Dan kamu hanya bisa melihat semua ini terjadi. Tidak ada yang bisa diubah, tidak ada yang bisa dilawan..."
  },
  AvgDialog_131212_Content_61 = {
    Text = "Nefraea datang di depan Arachne, dengan hati-hati mengusap wajahnya yang tidak terlihat emosinya."
  },
  AvgDialog_131212_Content_62 = {
    Text = "Apa yang harus dilakukan, kakakku... Apakah dia harus patuh padaku, atau bersama-sama melihat dunia ini berubah menjadi neraka?"
  },
  AvgDialog_131212_Content_63 = {
    Text = "Kau adalah sebuah nasib yang tidak lengkap, mencemari nasib seluruh kota, kau tidak memiliki hal seperti itu..."
  },
  AvgDialog_131212_Content_64 = {
    Text = "Suara putusnya benang halus terdengar di telinga Arachne. Dia mengangkat kepalanya, memandang Nefraea dengan seberkas kesedihan yang dimiliki oleh penonton."
  },
  AvgDialog_131212_Content_65 = {
    Text = "…kamu juga telah membunuh \"kenangan\"."
  },
  AvgDialog_131212_Content_66 = {
    Text = "Ini adalah penerimaan. Romantis, baik hati, kenangan... Saya hanya satu per satu, mengembalikan hal-hal yang telah kau buang kembali ke rumah mereka yang seharusnya."
  },
  AvgDialog_131212_Content_67 = {
    Text = "Nefraea bangkit berdiri dan dengan senang hati berputar satu kali."
  },
  AvgDialog_131212_Content_68 = {
    Text = "Sebuah diri yang utuh, seorang pembalas dendam yang utuh... Apakah kamu suka, kakak?"
  },
  AvgDialog_131212_Content_69 = {
    Text = "Kamu sudah bisa mendapatkan kaos yang kamuKerinduan... Jika demikian, apa lagi yang kamu tunggu?"
  },
  AvgDialog_131212_Content_7 = {
    Text = "Tarian kelompok angsa memang pantas disebut anggun, tetapi jika ada bentrok waktu, saya pasti akan memilih \"Kebun Zamrud\"."
  },
  AvgDialog_131212_Content_70 = {
    Text = "Ah, tidak, tidak, tidak, kakak yang baik, saya masih jauh, sangat jauh dari apa yang saya inginkan."
  },
  AvgDialog_131212_Content_71 = {
    Text = "Roda pemintalmu akan aku jaga dengan baik, dimensi abu sisa yang kau inginkan akan tak ada habisnya, semua panggung yang kau cintai, tidak akan aku hancurkan satu pun."
  },
  AvgDialog_131212_Content_72 = {
    Text = "Dan yang aku ingin kamu lakukan, hanyalah membantuku dengan satu hal yang sangat kecil, sangat kecil."
  },
  AvgDialog_131212_Content_73 = {
    Text = "Nefraea mendekat ke arah Arachne, mengusap roda pemintal yang terus berputar di tangannya, napasnya menjadi cepat karena imajinasi yang penuh keseruan."
  },
  AvgDialog_131212_Content_74 = {
    Text = "Bantu aku mengendalikan Penjaga, kakak yang baik, hanya Penjaga yang bisa membawakan apa yang benar-benar aku inginkan."
  },
  AvgDialog_131212_Content_75 = {
    Text = "Kau seharusnya tahu, %player% adalah pecahan dari dewa tertinggi itu, kita tidak bisa mengendalikan takdir %player%……"
  },
  AvgDialog_131212_Content_76 = {
    Text = "Sebuah cahaya hijau gelap memancar dari roda pemintal hitam di tangan Nefraea. Dalam cahaya itu, sebuah benang yang tersembunyi dan keruh muncul dalam bidang pandang Arachne."
  },
  AvgDialog_131212_Content_77 = {
    Text = "Ini adalah……<Shake:Benang takdir Penjaga Rahasia?!>"
  },
  AvgDialog_131212_Content_78 = {
    Text = "<Shake:Hehehe……><Big:<Shake:Hahahaha!>>Ini pertama kalinya aku mendengar suaramu bergetar. Bagaimana, Kakak? Sangat bersemangat, bukan?!"
  },
  AvgDialog_131212_Content_79 = {
    Text = "Di dalam penjara kedalaman, Rasul yang merupakan perwujudan kehendak dewa itu, telah ditempatkan dalam roda penggulung ini, menjadi sumbu lentera… Dialah yang menerangi penjara kedalaman, memberikan satu-satunya cahaya bagi kita."
  },
  AvgDialog_131212_Content_8 = {
    Text = "Banyak lapisan karakter dan narasi lintas waktu dan ruang, betapa menarik dan rumitnya teknik ini. Kejayaan dan kejatuhan taman kerajaan tidak dapat dibandingkan dengan klise-klise yang biasa..."
  },
  AvgDialog_131212_Content_80 = {
    Text = "Kekuatan kita, ditambah bimbingan sang Rasul, bahkan takdir pecahan dewa itu pun, <Big:sekarang berada dalam genggaman kita!>"
  },
  AvgDialog_131212_Content_81 = {
    Text = "Ini bukan arah yang benar dari nasib, Nefraea... tidak ada yang bisa melawan nasib."
  },
  AvgDialog_131212_Content_82 = {
    Text = "Segera akan ada, Kakak. Asalkan menyentuh kekuasaan dari tiga plasmid, rasul dapat dibangkitkan kembali! Dia akan membuka kembali jalur yang terhubung dengan dewa, Dia akan menyampaikan suara para percaya ke dalam kuil yang abadi itu"
  },
  AvgDialog_131212_Content_83 = {
    Text = "Dewa tertinggi itu akan kembali terbangun……Kau tidak perlu lagi memangkas takdir-takdir yang menyakitkan itu, tidak perlu lagi selamanya menenun jaring yang ditakdirkan untuk hancur……"
  },
  AvgDialog_131212_Content_84 = {
    Text = "Nefraea menarik napas dalam-dalam, sebuah air mata jatuh dari wajahnya yang penuh keseruan."
  },
  AvgDialog_131212_Content_85 = {
    Text = "Suara dia bergetar karena mimpi indah yang akan datang. Dua mata yang berkaca-kaca itu menatap dalam-dalam ke wajah tenang Arachne."
  },
  AvgDialog_131212_Content_86 = {
    Text = "Jangan lagi melakukan perlawanan yang menyakitkan itu, kakak."
  },
  AvgDialog_131212_Content_87 = {
    Text = "Ayo, datanglah ke sisiku, mari kita sambut Bangunnya-Nya bersama-sama, bawa semua panggung menuju akhir yang seharusnya mereka dapatkan!…"
  },
  AvgDialog_131212_Content_9 = {
    Text = "Ha, jika kau membeli nomor delapan, kau akan rugi besar! Diam-diam aku beritahu, aku punya informasi internal, hari ini akan ada seseorang yang menaruh obat di pakan nomor delapan."
  },
  AvgDialog_131213_Content_1 = {
    Text = "Komedi Improvisasi"
  },
  AvgDialog_131213_Content_10 = {
    Text = "Sekarang, kamu telah menyambut satu orang percaya yang baru——"
  },
  AvgDialog_131213_Content_100 = {
    Text = "Aku meminjam otoritas\"N\"……<color=#98918C>Aku menguasai setengah kesadaran %player%</color>……Tapi sebutan itu adalah hal yang paling tidak penting sekarang."
  },
  AvgDialog_131213_Content_101 = {
    Text = "Yang penting, kerjasama yang menyenangkan, Arachne."
  },
  AvgDialog_131213_Content_102 = {
    Text = "<Shake:Kau……kalian……kalian sudah tahu sejak awal……>"
  },
  AvgDialog_131213_Content_103 = {
    Text = "Pandangan lemah Nefraea berpindah dari wajah Arachne ke wajahmu. Kamu dengan rakus mencicipi kebencian dan penderitaan yang tak berujung dalam pandangan itu. Ah, betapa memabukkan baunya..."
  },
  AvgDialog_131213_Content_104 = {
    Text = "Lihatlah dengan baik, sayang Nefraea, nakal yang keluar dari Tanah Void."
  },
  AvgDialog_131213_Content_105 = {
    Text = "Permainanmu membuatku sangat senang. Sebuah sisa kesadaran dari Touva Wave, sepotong fragmen Touva Wave yang jatuh, hanya pertemuan mereka yang dapat melepaskan kekuasaan plasmid sepenuhnya, memberi kesempatan bagiku untuk merasakan kebahagiaan yang belum pernah aku alami sebelumnya..."
  },
  AvgDialog_131213_Content_106 = {
    Text = "Jika bisa, betapa aku ingin terus bermain seperti sekarang, kesenangan ini cukup untuk membuatku bermain selama seminggu penuh…"
  },
  AvgDialog_131213_Content_107 = {
    Text = "Gorong-gorongmu bergetar. Kamu menghela napas dengan penuh penyesalan."
  },
  AvgDialog_131213_Content_108 = {
    Text = "Sungguh disayangkan, jika orang itu bangkit kembali, Taman Hiburan yang megah ini akan pergi dariku."
  },
  AvgDialog_131213_Content_109 = {
    Text = "Jadi, sayang sekali……klimaks cerita ini akan segera berakhir. Angkat kepalamu, sayangku. Bagaimanapun juga, mengenai cerita takdir, kurasa kita memiliki sebuah konsensus yang indah……"
  },
  AvgDialog_131213_Content_11 = {
    Text = "Benang nasib menarik tubuhmu. Jari-jari tanganmu saling silang, kedua tangan bersatu di depan dada, perlahan berlutut dan menundukkan kepala ke arah roda pemintal di depan."
  },
  AvgDialog_131213_Content_110 = {
    Text = "Kamu membungkuk, mencengkeram dagu Nefraea yang anggun, mendekatkan diri ke telinganya."
  },
  AvgDialog_131213_Content_111 = {
    Text = "Kehancuran adalah pemandangan terindah di alam semesta ini, bukan? Sayang?"
  },
  AvgDialog_131213_Content_112 = {
    Text = "Sebuah jari yang cerah, penuh dengan kesukacitaan dan penyesalan, terdengar di depan mata Nefraea."
  },
  AvgDialog_131213_Content_113 = {
    Text = "BLARR——"
  },
  AvgDialog_131213_Content_114 = {
    Text = "Dalam guncangan Dimensi, saluran yang terhubung dengan dewa tiba-tiba bergetar. Tak terhitung retakan merayap di permukaan ilusi saluran..."
  },
  AvgDialog_131213_Content_115 = {
    Text = "<Big:<Shake:TIDAK!!——>>"
  },
  AvgDialog_131213_Content_116 = {
    Text = "Nefraea berteriak dan menerjang ke arah lorong, ketika tangannya tersisa beberapa inci dari lorong, itu hancur dan runtuh."
  },
  AvgDialog_131213_Content_117 = {
    Text = "Tak terhitung kepingan ilusi melayang di depan Nefraea, seperti sebuah kaleidoskop yang pecah, potongan kertas berwarna murah berterbangan di udara, menyapu wajah Nefraea."
  },
  AvgDialog_131213_Content_118 = {
    Text = "Kamu melepas topi hadiah yang tidak ada, memutarnya dua kali di udara, dan membungkuk kepada punggung Nefraea yang bingung."
  },
  AvgDialog_131213_Content_119 = {
    Text = "Nasib, betapa menariknya panggung ini…… Kisah babak ketiga pun berakhir. Tepuk tangan dan sorakanmu membuatku sangat menikmati."
  },
  AvgDialog_131213_Content_12 = {
    Text = "Saya... utusan yang saya impikan... saya adalah... pengikut setia Anda dan Dewa Yang Maha Tinggi."
  },
  AvgDialog_131213_Content_120 = {
    Text = "Selamat menikmati pertunjukan, yang terhormat Nefraea."
  },
  AvgDialog_131213_Content_121 = {
    Text = "Dalam teriakan yang menyayat hati di Nefraea, kesadaran Rasul hancur seiring dengan putusnya jalur. Kamu terjatuh di atas panggung dengan senyuman terakhir yang penuh kesukacitaan."
  },
  AvgDialog_131213_Content_13 = {
    Text = "Saluran tenggorokan dan anggota tubuhmu telah memiliki nasibnya sendiri. Mereka tidak lagi milikmu, dan kamu juga tidak perlu berusaha sia-sia untuk menguasainya kembali."
  },
  AvgDialog_131213_Content_14 = {
    Text = "Jangan mengendalikan. Jangan mencoba memahami. Nikmati saja. Jalan kesukacitaan, ada di dalamnya……"
  },
  AvgDialog_131213_Content_15 = {
    Text = "Lihatlah, Kakak, betapa hebatnya aktor yang telah kau didik!"
  },
  AvgDialog_131213_Content_16 = {
    Text = "Arachne duduk dengan tenang di bawah panggung, memutar roda pemintal di tangannya dengan frekuensi yang abadi. Dia diam-diam menatap bayangan gelap lentera di atas panggung, seolah-olah hanya seorang penonton yang mematuhi tata krama."
  },
  AvgDialog_131213_Content_17 = {
    Text = "Wahai rasulku tercinta... para percaya kami telah membawakan korban yang paling kau inginkan untukmu."
  },
  AvgDialog_131213_Content_18 = {
    Text = "Benang sutra berputar pelan, roda pemintal gelap tiba-tiba mekar, menyebarkan cahaya redup dan lengket ke setiap sudut panggung."
  },
  AvgDialog_131213_Content_19 = {Text = "Umm!!…"},
  AvgDialog_131213_Content_2 = {
    Text = "Tak, tak, tak."
  },
  AvgDialog_131213_Content_20 = {
    Text = "Rasa sakit datang tanpa peringatan, bukan di daging maupun di organ dalammu. Ia meledak dari kedalaman ruang mentalmu, dari tempat jiwamu bersemayam."
  },
  AvgDialog_131213_Content_21 = {
    Text = "Seekor makhluk raksasa muncul di dalam tubuhmu, ia meronta, meraung, tubuhnya yang besar membengkak dengan cepat di dalam dirimu."
  },
  AvgDialog_131213_Content_22 = {
    Text = "Makhluk raksasa itu memenuhi seluruh tubuhmu, menekan setiap organ dalammu. Ia membengkak, membengkak, dengan murka ingin merobek setiap jengkal kulitmu, rasa nyeri yang luar biasa hampir membuatmu pingsan..."
  },
  AvgDialog_131213_Content_23 = {
    Text = "Hah... <Big:<Shake:AAAAAHH!!——>>"
  },
  AvgDialog_131213_Content_24 = {
    Text = "Dalam jeritan hatimu yang menyayat, tiga nafas yang samar-samar mengalir dari tubuh yang penuh penderitaan itu, melayang menuju roda pemintal yang memancarkan cahaya gelap."
  },
  AvgDialog_131213_Content_25 = {
    Text = "Kuasa mengalir ke dalam cahaya, bagai bahan bakar murni yang dituangkan ke dalam api. Nyala api gelap meledak tiba-tiba, berkobar membara di lingkaran tengah roda pemintal. Cahaya lentera meningkat pesat, hampir menerangi seluruh dimensi ruang."
  },
  AvgDialog_131213_Content_26 = {
    Text = "<Shake:Hah... hah...>"
  },
  AvgDialog_131213_Content_27 = {
    Text = "Aduh, sungguh kasihan, pengikut kecil kami yang setia..."
  },
  AvgDialog_131213_Content_28 = {
    Text = "Nefraea datang di sampingmu, dengan penuh rasa sakit hati mengelus pipimu yang basah oleh keringat."
  },
  AvgDialog_131213_Content_29 = {
    Text = "Tak apa, Penjaga Rahasia {Male=先生,Female=小姐}, lihat, utusan kita sudah menampakkan wujudnya..."
  },
  AvgDialog_131213_Content_3 = {
    Text = "Benang nasib menarik dengan lembut, sol sepatu boneka bertabrakan dengan panggung, mengeluarkan suara yang jernih."
  },
  AvgDialog_131213_Content_30 = {
    Text = "Kamu mengangkat kepala dengan penuh rasa sakit. Cahaya dari roda pemintal mulai berkumpul, sebuah entitas semu yang berubah-ubah muncul di atas cahaya."
  },
  AvgDialog_131213_Content_31 = {
    Text = "Dia tak berwajah, tak berbentuk. Dia adalah pembawa pesan setia sang dewa, memandang jauh ke arah tempat sang dewa tertidur di dalam kehampaan."
  },
  AvgDialog_131213_Content_32 = {
    Text = "Tatapan-Nya adalah sebuah undangan. Di bawah pandangan-Nya, sebuah tangga yang menghubungkan tempat peristirahatan sang dewa perlahan menampakkan wujudnya……"
  },
  AvgDialog_131213_Content_33 = {
    Text = "<Shake:Berhasil……Berhasil!> Gerbang menuju kerajaan dewa akan segera terbuka……Sang dewa, akan segera terbangun……"
  },
  AvgDialog_131213_Content_34 = {
    Text = "Kakak, apakah kamu melihatnya? Jaringmu, hampir selesai……"
  },
  AvgDialog_131213_Content_35 = {
    Text = "Nefraea dengan gembira memandangi jalur yang semakin jelas, senyuman dan air mata muncul sekaligus di wajahnya."
  },
  AvgDialog_131213_Content_37 = {
    Text = "Teater bergetar hebat. Panggung runtuh, dimensi bergetar. Segala nasib, dalam kedatangan yang agung ini, ketakutan dan tunduk."
  },
  AvgDialog_131213_Content_38 = {
    Text = "Otoritas dalam tubuhmu sudah hampir tak terasa. Kekuatan substansi, semuanya telah kembali ke tubuh sang Rasul. Cahaya-Nya tak dapat dipandang langsung, keberadaan-Nya tak dapat disangkal."
  },
  AvgDialog_131213_Content_39 = {
    Text = "Di bawah tatapan tenang Arachne, di tengah semua getaran nasib, Dia akan kedatangan di panggung terakhir ini —"
  },
  AvgDialog_131213_Content_4 = {
    Text = "Ah, para penonton yang terhormat, momen yang dinantikan semua orang akan segera tiba! Mari kita sambut dengan tepuk tangan untuk tokoh utama kita, tampil dengan gemilang! Oh"
  },
  AvgDialog_131213_Content_40 = {
    Text = "Dengan nama…@2…pengikut @3…"
  },
  AvgDialog_131213_Content_41 = {
    Text = "Katakanlah, rasul... apa yang ingin kau sampaikan padaku? Apakah itu hasratmu? Atau kata-kata dari orang itu, sang dewa?"
  },
  AvgDialog_131213_Content_42 = {
    Text = "Apa wahyu yang ingin Ia sampaikan kepada dunia ini? Apakah Ia ingin menghancurkan panggung ini? Atau ingin agar para boneka ini bersama-sama menyambut Kedatangannya?"
  },
  AvgDialog_131213_Content_43 = {
    Text = "Katakan padaku, Rasul tersayang! Kau adalah seekor binatang buas yang begitu berbahaya namun menggemaskan, tak mengenal apa pun selain mencabik dan menghancurkan……Katakan padaku, apa yang kau inginkan……"
  },
  AvgDialog_131213_Content_44 = {
    Text = "Membaca@2……Nama saya……Bangun@2……@3Awal……"
  },
  AvgDialog_131213_Content_45 = {
    Text = "Ah, nama mu, tidak salah... Aku akan mengucapkan namamu! Aku akan membawakan segala yang kau inginkan untuk kau makan ke bibirmu. Aku akan membuka penjara ini untukmu..."
  },
  AvgDialog_131213_Content_46 = {
    Text = "Namaku……@2……"
  },
  AvgDialog_131213_Content_47 = {
    Text = "Suara Rasul terdengar keruh, Nefraea berjalan menuju tiang cahaya yang semakin terang, tanpa melirik sedikit pun kepada dirimu yang bergetar seluruh tubuh karena rasa sakit."
  },
  AvgDialog_131213_Content_48 = {
    Text = "Ia berseru dengan penuh kegilaan dan tawa, melangkah ke hadapan sosok agung itu, napasnya nyaris terhenti karena kegembiraan."
  },
  AvgDialog_131213_Content_49 = {
    Text = "Dia mengusap cahaya hijau yang misterius itu, mengelus binatang buas yang akan melahap segalanya. Dia akan menjadi makanan pertama bagi binatang buas itu, dia melangkah tanpa ragu, manis seperti madu."
  },
  AvgDialog_131213_Content_5 = {
    Text = "Nefraea mengangkat tangannya, seperti jaring laba-laba kembang api yang berterbangan. Kamu berdiri di tengah panggung, cahaya redup menerangi wajahmu."
  },
  AvgDialog_131213_Content_50 = {
    Text = "Saatnya sekarang, Rasul... ceritakan padaku, ceritakan kepada dunia ini, namamu"
  },
  AvgDialog_131213_Content_51 = {
    Text = "Namaku……@2……"
  },
  AvgDialog_131213_Content_52 = {
    Text = "Namaku……<Red:%player%>……"
  },
  AvgDialog_131213_Content_53 = {
    Text = "Namaku……<Yellow:%player%>!"
  },
  AvgDialog_131213_Content_54 = {Text = "!!!"},
  AvgDialog_131213_Content_55 = {
    Text = "Waktu berhenti pada saat ini. Benang nasib meleleh dan hancur di mata Nefraea, nasib yang runtuh seperti pusaran yang mengamuk di lautan, menyeret dan menelan dirinya."
  },
  AvgDialog_131213_Content_56 = {
    Text = "<Shake:Ini……apa yang terjadi?!!>"
  },
  AvgDialog_131213_Content_57 = {
    Text = "Vortex tenang, lautan mengumpulkan, tetesan air kembali berkumpul menjadi benang, dan jaring yang mereka susun, sudah menjadi bentuk yang tidak pernah diperkirakan oleh Nefraea."
  },
  AvgDialog_131213_Content_58 = {
    Text = "Tidak mengerti, Nefraea? Sembahlah rasulmu dengan tulus. Rasul yang kau doakan, sudah berdiri di depanmu."
  },
  AvgDialog_131213_Content_59 = {
    Text = "Kau berdiri di depan Nefraea, memandang jalan yang menghubungkan kuil Touva Wave, menatap sosok yang agung itu, dan tersenyum lebar."
  },
  AvgDialog_131213_Content_6 = {
    Text = "Ayo, Penjaga Rahasia {Male=先生,Female=小姐}, babak terakhir pertunjukan kita, akan segera dimulai..."
  },
  AvgDialog_131213_Content_60 = {
    Text = "Kekuasaan dari tiga plasmid mengalir dengan liar di dalam tubuhmu, tetapi tidak lagi menyakitimu. Cahaya dari roda pemintal, dengan kehendak yang agung di dalamnya, mengalir ke dalam tubuhmu seperti lautan, bersatu dengan kekuasaan dari ketiga plasmid."
  },
  AvgDialog_131213_Content_61 = {
    Text = "Kamu merasakan, sosok Rasul itu tumpang tindih dengan tubuhmu. Kamu merasa megah. Kamu merasa tak terbatas. Kamu merasa bebas. Kamu merasa… kebahagiaan yang tertinggi."
  },
  AvgDialog_131213_Content_62 = {
    Text = "Kamu... mencuri nasib Rasul?!"
  },
  AvgDialog_131213_Content_63 = {
    Text = "Hehehehe... Hahahaha! Bab ketiga cerita, kedatangan?... Ha, haha. Bab ketiga, benar. Tapi ini bukan ceritamu, sayang Nefraea."
  },
  AvgDialog_131213_Content_64 = {
    Text = "Babak ketiga cerita ini, akulah yang menulisnya. Dan aku memberi nama cerita ini——<Big:<color=#98918C>Kesenangan</color>!>"
  },
  AvgDialog_131213_Content_65 = {
    Text = "<Shake:Kau……kalian……>"
  },
  AvgDialog_131213_Content_66 = {
    Text = "Tidak, ini tidak mungkin… aku bisa melihat nasibmu… ini tidak mungkin…"
  },
  AvgDialog_131213_Content_67 = {
    Text = "<color=#EE4D0C>\"Oh, Yang Mulia Duke, mengapa Anda menangis! Biarlah badut Anda, mengembalikan senyuman berharga Anda!\"</color>"
  },
  AvgDialog_131213_Content_68 = {
    Text = "<color=#BF0909>\"Lihatlah, takdir yang kejam itu, kutukan yang jahat itu……Betapa lucunya pemandangan ini! Betapa manisnya tipu daya ini!\"</color>"
  },
  AvgDialog_131213_Content_69 = {
    Text = "<color=#FC1818>\"Inilah akhir bagi para pendosa……Hadiah untuk kejahatan, hanyalah kesenangan!\"</color>"
  },
  AvgDialog_131213_Content_7 = {
    Text = "Adegan ini, saya menamakannya —\"Kedatangan\""
  },
  AvgDialog_131213_Content_70 = {
    Text = "Bangku penonton yang kosong bergemuruh tepuk tangan, panggung yang hancur bersinar terang benderang. Kau adalah pusat dunia, tuan dari singularitas. Kau merentangkan kedua lenganmu. Kau berkata takdir bertekuk lutut padamu, kau berkata, drama ini layak dipuji."
  },
  AvgDialog_131213_Content_71 = {
    Text = "Menipu. Memperdaya. Menikmati……<Shake:Hehehe, <Big:Hahahaha!>> Betapa menyenangkannya pertunjukan ini, laba-laba kecil."
  },
  AvgDialog_131213_Content_72 = {
    Text = "<Shake:Kau……mustahil memiliki kemampuan mengubah takdir……>"
  },
  AvgDialog_131213_Content_73 = {
    Text = "Ah, tidak tidak tidak, itu adalah kekuatan milik kalian. Pengikut kesenangan tidak akan melakukan hal yang melelahkan seperti itu."
  },
  AvgDialog_131213_Content_74 = {
    Text = "<Shake:Aku sudah melihatnya……Kau akan menyerahkan otoritas substansi, kau akan menyaksikan gerbang terbuka, <Big:kau akan mati di atas panggung ini! Mengapa?!!>>"
  },
  AvgDialog_131213_Content_75 = {
    Text = "Orang yang mengendalikan nasib mengetahui segalanya, tetapi tidak bisa mengetahui orang-orang yang berbahagia. Karena, karena orang-orang yang berbahagia tidak memiliki nasib, sayangku…"
  },
  AvgDialog_131213_Content_76 = {
    Text = "Kamu membungkuk, mengagumi mata Nefraea yang bergetar. Rasa sakit dan keputusasaan yang berkilau di dalamnya, menyuburkan setiap inci tubuhmu."
  },
  AvgDialog_131213_Content_77 = {
    Text = "Segala sesuatu dalam hidup kita adalah untuk mengejar kesukacitaan. Setelah melepaskan kesukacitaan, kita tidak memiliki apa-apa... Mereka yang bersukacita, tidak memiliki nasib."
  },
  AvgDialog_131213_Content_78 = {
    Text = "Apa yang kau lihat, hanyalah sebuah trik kecil, sebuah lelucon kecil dari diriku yang sekarang—yang telah memiliki kehendak dan kekuatan dewa—terhadap diriku di masa lalu, terhadap takdir."
  },
  AvgDialog_131213_Content_79 = {
    Text = "Mengendalikan takdir, mana bisa lebih menarik dibanding mempermainkan takdir? Benar kan, wahai wakil takdir?"
  },
  AvgDialog_131213_Content_8 = {
    Text = "Kedatangan. Di balik panggung, tirai yang lengket seperti lendir menjalin kata yang besar dan horor ini. Nefraea menarik napas dalam-dalam dan mengulurkan kedua tangannya."
  },
  AvgDialog_131213_Content_80 = {
    Text = "Kau pernah ingin melanjutkan percakapan ini dengan serius, tapi kau tak bisa menahan tawa gilamu."
  },
  AvgDialog_131213_Content_81 = {
    Text = "Apakah kau Penjaga Rahasia? Apakah kau\"N\"? Kau tidak tahu, dan tidak peduli. Otoritas kesenangan mengalir ke dalam kehendak sang Rasul, memenuhi setiap sel dalam tubuhmu."
  },
  AvgDialog_131213_Content_82 = {
    Text = "Kau ingin tertawa terbahak-bahak, ingin bersorak, ingin menunjukkan penghinaan paling lembut dan paling ekstrem kepada sang manipulator yang telah diperdaya."
  },
  AvgDialog_131213_Content_83 = {
    Text = "Kamu telah menemukan kunci untuk membuka kunci. Kamu berbalik dan memberi hormat dengan anggun kepada orang itu yang merancang."
  },
  AvgDialog_131213_Content_84 = {
    Text = "Arachne, penulis drama yang hebat! Sejak saat pertama saya datang ke dunia ini, saya telah mulai menjalin panggung ini"
  },
  AvgDialog_131213_Content_85 = {
    Text = "Bawa aku untuk melihat cara kerja nasib, biarkan aku merasakan pesona olok-olok, beri tahu aku rahasia \"Kesukacitaan\"…"
  },
  AvgDialog_131213_Content_86 = {
    Text = "Sekarang, kunci untuk \"Kesukacitaan\" sudah terbuka. Bagaimana, aktor saya, apakah kamu masih puas?"
  },
  AvgDialog_131213_Content_87 = {
    Text = "Aku hanya pembangun panggung, penulisan cerita, adalah keputusanmu sendiri."
  },
  AvgDialog_131213_Content_88 = {
    Text = "Kamu mengembangkan senyummu padanya. Kamu adalah rasul dewa. Kamu adalah budak kesukacitaan. Kamu adalah satu-satunya tuan yang tak terbantahkan di dunia ini. Kamu mengangkat tanganmu, seperti seorang konduktor yang dengan lembut menekan."
  },
  AvgDialog_131213_Content_89 = {
    Text = "Sebagai imbalan... sekarang, kenakan kostummu, Arachne. Pertunjukan ini, sebentar lagi akan tiba saatmu untuk tampil"
  },
  AvgDialog_131213_Content_9 = {
    Text = "Rasul Tuhan Yang Maha Tinggi, penyampai pesan kebodohan Chaos. Cahaya-Mu menerangi penjara abadi, aku mendengar suaramu yang memanggil Chaos."
  },
  AvgDialog_131213_Content_90 = {
    Text = "Kau dengan mudah menggerakkan benang-benang takdir yang dulu tak terlihat, seperti memindahkan sebuah balok mainan ke tempat lain sesuka hati."
  },
  AvgDialog_131213_Content_91 = {
    Text = "Saat semua benang takdir dikacaukan dan dibentuk ulang, bara dimensi yang telah dicuri kembali ke sisinya."
  },
  AvgDialog_131213_Content_92 = {
    Text = "Pasir halus ungu gelap yang tak ada habisnya mengalir di sekitar Arachne, berputar di sekelilingnya. Dalam karyamu, yang dicuri oleh Dimensi Abu sisa tidak pernah ada."
  },
  AvgDialog_131213_Content_93 = {
    Text = "<color=#8C7E96>Dulu, di masa depan, mereka akan selamanya milik Arachne.</color>"
  },
  AvgDialog_131213_Content_94 = {
    Text = "Arachne mengangguk tersenyum kepadamu, menyembunyikan abu sisa ke dalam tubuhnya. Roda pemintalnya tidak pernah berhenti. Senyumannya tidak pernah berubah."
  },
  AvgDialog_131213_Content_95 = {
    Text = "Kamu menggelengkan kepala di atas panggung, mengeluarkan desahan yang berlebihan."
  },
  AvgDialog_131213_Content_96 = {
    Text = "Mati suram, tanpa semangat... Betapa menariknya dirimu, Arachne."
  },
  AvgDialog_131213_Content_97 = {
    Text = "Kamu sama seperti Tawil, adalah Pengamat nasib, dan juga hamba nasib. Kebahagiaanku yang sekarang, kalian tidak akan pernah bisa merasakannya."
  },
  AvgDialog_131213_Content_98 = {
    Text = "Lihatlah wajahmu yang tidak bersemangat itu, Arachne. Saya benar-benar merasa kasihan padamu."
  },
  AvgDialog_131213_Content_99 = {
    Text = "Setiap orang punya pilihannya sendiri, %player%……Mungkin, aku harus memanggil Anda sebagai Rasul, atau……\"N\"?"
  },
  AvgDialog_131214_Content_1 = {
    Text = "<Shake:Aaaaaah!—>"
  },
  AvgDialog_131214_Content_10 = {
    Text = "Karena... balas dendam kita, belum berakhir, dan tidak akan pernah berakhir..."
  },
  AvgDialog_131214_Content_11 = {
    Text = "Kau secara tidak sadar mundur selangkah. Namun, tidak ada gelombang berbahaya yang muncul dari tubuh Nefraea."
  },
  AvgDialog_131214_Content_12 = {
    Text = "Dia hanya menggerakkan kaki penjepitnya, merobek tirai yang menutupi di sampingnya, memperlihatkan pemandangan di balik tirai."
  },
  AvgDialog_131214_Content_13 = {Text = "Ini......!"},
  AvgDialog_131214_Content_14 = {
    Text = "Benang Merah Darah, menghubungkan beberapa panggung di teater, menghubungkan kota megah tempat teater berada, menghubungkan banyak boneka di kota, berkumpul ke dalam tubuh Nefraea yang penuh luka."
  },
  AvgDialog_131214_Content_15 = {
    Text = "Kamu... tidak menghubungkan benang ke roda tenun?"
  },
  AvgDialog_131214_Content_16 = {
    Text = "Dia telah melihat akhir. Dia melihat kegagalannya sendiri. Ketika dia masih memiliki kekuatan, dia mengikat takdir ini dengan dirinya sendiri, seperti…"
  },
  AvgDialog_131214_Content_17 = {
    Text = "Sama seperti saat kamu membunuhku untuk pertama kalinya."
  },
  AvgDialog_131214_Content_18 = {
    Text = "Nefraea tersenyum, sambil mengangkat seutas benang yang sangat tersembunyi di depannya."
  },
  AvgDialog_131214_Content_19 = {
    Text = "Benang merah darah itu membentang dari belakang kepalanya, melalui perjalanan panjang yang hati-hati, secara tersembunyi berkumpul ke dalam tubuh Arachne."
  },
  AvgDialog_131214_Content_2 = {
    Text = "BLARR——"
  },
  AvgDialog_131214_Content_20 = {
    Text = "Sudah lama kita tidak sedekat itu, Kakak. Hingga baru saja, aku menemukan kesempatan untuk mengembalikan benang sutra ini padamu."
  },
  AvgDialog_131214_Content_21 = {
    Text = "\"Masih\"…?"
  },
  AvgDialog_131214_Content_22 = {
    Text = "Benang ini... adalah yang saya putuskan saat pertama kali menghancurkan ciptaan saya."
  },
  AvgDialog_131214_Content_23 = {
    Text = "Romantisme-mu, kebaikanmu, kenanganmu… Segala sesuatu yang ada padaku, sudah sepenuhnya aku kembalikan kepadamu."
  },
  AvgDialog_131214_Content_24 = {
    Text = "Kamu sudah lengkap, Arachne."
  },
  AvgDialog_131214_Content_25 = {
    Text = "Sudut mulut Nefraea terangkat, seperti seorang anak yang bersembunyi di balik tirai, melihat orang dewasa terjebak dalam lelucon jahatnya sendiri."
  },
  AvgDialog_131214_Content_26 = {
    Text = "Pada saat-saat di mana kamu memiliki kekuatan… apakah ini yang ingin kamu lakukan?"
  },
  AvgDialog_131214_Content_27 = {
    Text = "Bagaimana? Ide yang brilian, bukan"
  },
  AvgDialog_131214_Content_28 = {
    Text = "Ayo, bunuh aku! Hancurkan sepenuhnya nasib yang pernah kau tinggalkan! Hancurkan kota tempat kau tinggal ini, hancurkan teater yang kau cintai, hancurkan setiap orang di sini"
  },
  AvgDialog_131214_Content_29 = {
    Text = "Ayo, Arachne! Bawa semua kelemahanmu, <Shake: bunuh sekali lagi segala sesuatu yang kau cintai!!!>"
  },
  AvgDialog_131214_Content_3 = {
    Text = "Jeritan menyakitkan dan suara getaran kehancuran menggema di teater yang hancur. Benang merah darah terputus sedikit demi sedikit, roda pemintal yang menemani Nefraea seumur hidupnya jatuh di depan dirinya."
  },
  AvgDialog_131214_Content_30 = {
    Text = "Gema teriakan dan tawa Nefraea yang penuh semangat bergema lama di dalam teater yang hancur."
  },
  AvgDialog_131214_Content_31 = {
    Text = "Tubuh Arachne tampaknya menjadi lebih berat dari sebelumnya. Dia perlahan-lahan memutar kepalanya, memandang segala sesuatu yang terhubung dengan Nefraea."
  },
  AvgDialog_131214_Content_32 = {
    Text = "Melalui celah teater, dia melihat mobil dan kerumunan memenuhi kota yang ramai ini. Wajah-wajah yang akrab dengan nama-nama yang akrab tersebar di setiap sudut yang dikenalnya."
  },
  AvgDialog_131214_Content_33 = {
    Text = "Dia melihat panggung yang pernah kau pijaki bersamanya. Perang yang mengerikan telah berakhir, dunia itu akan menyambut perdamaian yang indah dan panjang selama dua ratus tahun."
  },
  AvgDialog_131214_Content_34 = {
    Text = "Di antara cairan hitam itu, dia melihat wajah ibunya. Dia duduk bersama ayahnya di bawah pohon birch putih di halaman, melambai ke arah dirinya sendiri."
  },
  AvgDialog_131214_Content_35 = {
    Text = "Tuan Edgar berdiri di samping mereka, membersihkan perangkat makan yang dibuat khusus untuknya."
  },
  AvgDialog_131214_Content_36 = {
    Text = "Kau menyebut ini sebagai balas dendam, karena kau tidak pernah melihat nasib dengan jelas, dan kau juga tidak pernah melihatku dengan jelas, Nefraea."
  },
  AvgDialog_131214_Content_37 = {
    Text = "Sebuah benang yang dipenuhi dengan lendir menghubungkan Arachne dengan panggung yang hancur di bawah kaki Nefraea. Menarik tubuhnya yang berat, Arachne melangkah di atas benang yang rapuh itu."
  },
  AvgDialog_131214_Content_38 = {
    Text = "Benang-benang bergetar, seolah akan putus kapan saja, menghukum sang tahanan takdir ke dalam jurang tanpa dasar."
  },
  AvgDialog_131214_Content_39 = {
    Text = "Arachne dengan tenang memandang mata Nefraea yang terkejut. Langkahnya tidak pernah berhenti sejenak pun."
  },
  AvgDialog_131214_Content_4 = {
    Text = "Dia seperti bayi yang terjatuh ke dalam air, menggenggam roda pemintal dengan erat. Di tangannya, roda pemintal yang kelam hancur tanpa bisa dihalangi, berubah menjadi abu sisa dimensi, berkumpul ke dalam pasir bergerak di samping Arachne."
  },
  AvgDialog_131214_Content_40 = {
    Text = "Saat yang ditentukan, akan segera tiba…"
  },
  AvgDialog_131214_Content_41 = {
    Text = "Arachne di atas benang laba-laba mengangkat roda pemintal di tangannya. Kamu dapat melihat dengan jelas seluruh dunia terhenti sejenak, seluruh alam semesta yang terhubung dengan teater ini, sedang menunggu perintahnya."
  },
  AvgDialog_131214_Content_42 = {
    Text = "Aku atas nama nasib, mengumumkan di sini——"
  },
  AvgDialog_131214_Content_43 = {
    Text = "Segala takdir yang keliru, akan lenyap dalam debu waktu. Takdir dunia, akan kembali ke jalur yang telah ditakdirkan."
  },
  AvgDialog_131214_Content_44 = {
    Text = "Benang-benang yang kacau, diputus di sini. Yang malang dan terbuang itu, akan beristirahat dengan tenang di sini……"
  },
  AvgDialog_131214_Content_45 = {
    Text = "Roda penggulung miring, ribuan benang bergetar mengikuti."
  },
  AvgDialog_131214_Content_46 = {
    Text = "Benang putus. Menunggu panggung damai, hancur dan lenyap."
  },
  AvgDialog_131214_Content_47 = {
    Text = "Benang putus. Di celah teater, tidak ada lagi jejak kota yang terlihat."
  },
  AvgDialog_131214_Content_48 = {
    Text = "Benang putus, putus, putus…"
  },
  AvgDialog_131214_Content_49 = {
    Text = "Kamu kesulitan untuk melihat benang-benang nasib itu, tetapi kamu jelas mendengar teriakan nasib."
  },
  AvgDialog_131214_Content_5 = {
    Text = "Nefraea tertegun menatap harapan yang berlalu ini, tiba-tiba tertawa kecil."
  },
  AvgDialog_131214_Content_50 = {
    Text = "Tak terhitung kehidupan masa lalu dan sekarang dari banyak orang, berbagai kesedihan dan kebahagiaan hancur, terurai, dibangun kembali, dan lenyap di telingamu..."
  },
  AvgDialog_131214_Content_51 = {Text = "…Cahaya?"},
  AvgDialog_131214_Content_52 = {
    Text = "Lampu panggung yang tidak diketahui berasal dari mana menyala. Cahaya menembus gedung teater yang hancur, para pengabaian yang bersembunyi dalam bayangan menghilang pada saat cahaya jatuh, seolah-olah mereka tidak pernah ada."
  },
  AvgDialog_131214_Content_53 = {
    Text = "Arachne, kakak, kamu......"
  },
  AvgDialog_131214_Content_54 = {
    Text = "Arachne membawa roda pemintal yang berputar, melangkah melewati benang yang rapuh, dan tiba di hadapannya. Nefraea menatapnya, seolah melihat nasib yang tak terelakkan itu sendiri."
  },
  AvgDialog_131214_Content_55 = {
    Text = "Dekatlah padaku, Nefraea."
  },
  AvgDialog_131214_Content_56 = {
    Text = "Arachne memegang tangan Nefraea dan menempelkannya di pipinya."
  },
  AvgDialog_131214_Content_57 = {
    Text = "Saat menyentuh Arachne, sebuah pintu tersembunyi terbuka menuju Nefraea. Nefraea melewati lapisan-lapisan penjara itu dan untuk pertama kalinya benar-benar berada di depan Arachne."
  },
  AvgDialog_131214_Content_58 = {
    Text = "Di dalam kandang itu, dia melihat tiga wajah yang akrab."
  },
  AvgDialog_131214_Content_59 = {
    Text = "Arachne！！！Kamu......"
  },
  AvgDialog_131214_Content_6 = {
    Text = "Tawaannya semakin keras, hampir tidak memiliki tenaga untuk bangkit. Darah menetes dari tubuhnya yang bergetar, mewarnai pecahan pemintal yang redup menjadi merah."
  },
  AvgDialog_131214_Content_60 = {
    Text = "<Shake:Romansa, kebaikan, kenangan…… Mereka…… Mereka……>"
  },
  AvgDialog_131214_Content_61 = {
    Text = "Aku tidak pernah bisa sepenuhnya meninggalkan mereka. Aku tidak pernah benar-benar bisa meninggalkanmu."
  },
  AvgDialog_131214_Content_62 = {
    Text = "Tapi kau pernah berkata, kau tidak bisa menanggung ini..."
  },
  AvgDialog_131214_Content_63 = {
    Text = "Bodoh, Fragile, menghancurkan segala sesuatu yang aku hargai dengan rasa sakit... kau tidak dapat membalas dendam padaku dengan ini, Nefraea."
  },
  AvgDialog_131214_Content_64 = {
    Text = "Karena, ini adalah hukuman yang telah ditentukan oleh nasib untukku."
  },
  AvgDialog_131214_Content_65 = {
    Text = "Arachne tersenyum padanya dengan tenang. Roda jarumnya berputar, tak pernah berhenti."
  },
  AvgDialog_131214_Content_66 = {
    Text = "Sudah berakhir, Nefraea."
  },
  AvgDialog_131214_Content_67 = {
    Text = "Sebuah senar gitar bergetar lembut. Nefraea mendengar suara cry burung bangau, seperti saat dia masih kecil, ketika ayahnya membawakan alat pemintal bernama Moira untuknya."
  },
  AvgDialog_131214_Content_68 = {
    Text = "Ini adalah kamar miliknya, pohon birch di luar jendela adalah teman setianya, satu orang tahanan kesepian yang abadi."
  },
  AvgDialog_131214_Content_69 = {
    Text = "Mereka terkurung oleh nasib, mereka saling bergantung satu sama lain di sini."
  },
  AvgDialog_131214_Content_7 = {
    Text = "Akhir, akhir memang tidak bisa diubah... inilah takdir..."
  },
  AvgDialog_131214_Content_70 = {
    Text = "Ciiit——"
  },
  AvgDialog_131214_Content_71 = {
    Text = "Pintu kayu yang sederhana didorong terbuka, Arachne datang di sampingnya, menunduk, dan dengan lembut mengusap wajahnya."
  },
  AvgDialog_131214_Content_72 = {
    Text = "Kakak... aku kalah... kita kalah..."
  },
  AvgDialog_131214_Content_73 = {
    Text = "Kami tidak pernah punya hak untuk menang."
  },
  AvgDialog_131214_Content_74 = {
    Text = "Apakah kamu masih ingat keinginan yang kita buat pada hari kita menerima roda tenun?"
  },
  AvgDialog_131214_Content_75 = {
    Text = "\"Aku tidak akan menyia-nyiakan anugerah takdir…… Aku akan membawa takdir yang indah, kepada dunia ini……\""
  },
  AvgDialog_131214_Content_76 = {
    Text = "Betapa naifnya harapan itu, Arachne... Saat itu, kami sama sekali tidak mengerti apa artinya."
  },
  AvgDialog_131214_Content_77 = {
    Text = "Arachne mengulurkan tangan yang sedikit bergetar itu, mengusap wajahnya yang jauh."
  },
  AvgDialog_131214_Content_78 = {
    Text = "Nasib… siapa yang bisa benar-benar melihatnya."
  },
  AvgDialog_131214_Content_79 = {
    Text = "Namun meskipun bisa melihat, pilihanku tetap tidak akan berubah."
  },
  AvgDialog_131214_Content_8 = {
    Text = "Kemenangan yang menyedihkan ini, kau sudah melihatnya, kan, Arachne?"
  },
  AvgDialog_131214_Content_80 = {
    Text = "<Shake:Kenapa, Arachne?>Kau bisa pergi, kau bisa lepaskan, kau bisa..."
  },
  AvgDialog_131214_Content_81 = {
    Text = "Setelah meninggalkan Penjara Abyss, kamu seharusnya bisa mendapatkan kebebasan abadi. Kamu tahu bahwa pada akhirnya kamu akan gagal, tetapi kamu tetap mencoba untuk membawakan kelegaan untukku, untuk nasib-nasib yang mengikuti kamu."
  },
  AvgDialog_131214_Content_82 = {
    Text = "Setiap pengendali nasib, akan menjadi tahanan nasib, begitu juga kamu dan aku. Bukankah begitu, Nefraea?"
  },
  AvgDialog_131214_Content_83 = {
    Text = "Nefraea diam diam, dengan sedih melihat ke luar jendela ke pohon birch putih. Dia melihat pohon itu mengeluarkan cabang, bertunas, tumbuh, dan layu."
  },
  AvgDialog_131214_Content_84 = {
    Text = "Dia menghela nafas pelan, mengangkat kepala, dan membelai air mata yang perlahan jatuh di wajah Arachne. Dia tersenyum padanya."
  },
  AvgDialog_131214_Content_85 = {
    Text = "Senang sekali bisa bertemu denganmu lagi... Kakak."
  },
  AvgDialog_131214_Content_86 = {
    Text = "Sebuah tetes air mata jatuh dengan ringan, menetes di wajah yang persis sama dengan Arachne."
  },
  AvgDialog_131214_Content_87 = {
    Text = "Tolong maafkan egoisku…"
  },
  AvgDialog_131214_Content_88 = {
    Text = "Kau... sudah bebas, <Red: \"Arachne\">."
  },
  AvgDialog_131214_Content_89 = {Text = "Ciiit."},
  AvgDialog_131214_Content_9 = {
    Text = "Tadi, kamu juga sempat melihat secara diam-diam segala sesuatu ini. Sekarang kamu sudah mengetahui akhir yang terakhir, untuk apa masih terikat pada ini?"
  },
  AvgDialog_131214_Content_90 = {
    Text = "Saat benang terakhir terputus, kau mendengar tepuk tangan yang menggelegar bagai guntur."
  },
  AvgDialog_131214_Content_91 = {
    Text = "Selalu tidak ada orang di bawah panggung, tempat duduk sudah penuh. Nasib yang ditinggalkan dan boneka-boneka yang mati di tangan kalian, memenuhi setiap kursi beludru yang hancur."
  },
  AvgDialog_131214_Content_92 = {
    Text = "Para aktor duduk di kursi penonton, diam menatap akhir dari panggung ini."
  },
  AvgDialog_131214_Content_93 = {
    Text = [[
Mereka tanpa ekspresi, tanpa suara. 
 Mereka bertepuk tangan dengan semangat. Suara tepuk tangan mengguntur, berlangsung lama.]]
  },
  AvgDialog_131215_Content_1 = {
    Text = "Tokoh dalam Drama"
  },
  AvgDialog_131215_Content_10 = {
    Text = "Sebelumnya saya tidak mengerti, mengapa Arachne harus mengeluarkan adiknya dari Jaring Takdir, dan mengapa kamu harus mendapatkan kekuatan dari tiga Misteri Pasangan itu."
  },
  AvgDialog_131215_Content_101 = {
    Text = "Dewi nasib yang penuh ketahanan namun sia-sia... Betapa putus asanya, betapa indahnya pemandangan ini..."
  },
  AvgDialog_131215_Content_102 = {
    Text = "Kalian bilang, dia melakukan ini untuk apa?"
  },
  AvgDialog_131215_Content_103 = {
    Text = "Nefraea menatap panggung sederhana ini dengan penuh perhatian, suaranya kecil seperti sedang berbisik."
  },
  AvgDialog_131215_Content_104 = {
    Text = "Ini hanyalah sebuah mimpi, dewi nasib… kamu seharusnya bisa memilih nasib yang paling bahagia untuk semua orang, kamu bisa memperbaiki ilusi yang tidak realistis, memenuhi segala sesuatu yang kamu inginkan."
  },
  AvgDialog_131215_Content_105 = {
    Text = "Tapi kamu tidak pernah berpikir untuk melakukan hal ini... Ketika kamu menciptakan kesempurnaan, kamu juga menciptakan penderitaan. Kamu terus-menerus membiarkan penderitaan datang ke dunia ini."
  },
  AvgDialog_131215_Content_106 = {
    Text = "Kamu berusaha sekuat tenaga untuk menjalin jaring besar dari nasib, namun pemandangan di balik pintu itu, dan akhir yang telah ditentukan oleh nasib, kita berdua pernah melihatnya."
  },
  AvgDialog_131215_Content_107 = {
    Text = "Ketika jaring nasib telah ditenun, saat itulah Sang Dewa yang Maha Tinggi sepenuhnya Bangun..."
  },
  AvgDialog_131215_Content_108 = {
    Text = "Apa……?!"
  },
  AvgDialog_131215_Content_109 = {
    Text = "Kau menatap Arachne, berharap mendapatkan jawaban negatif dari wajahnya."
  },
  AvgDialog_131215_Content_11 = {
    Text = "Setidaknya, saya harus berterima kasih karena kamu telah menjawab kebingungan saya."
  },
  AvgDialog_131215_Content_110 = {
    Text = "Di wajah itu, selain ketenangan yang tak pernah berubah, kau tak bisa melihat apa pun. Di atas panggung takdir, ketenangan adalah topeng yang tak bisa ia lepaskan."
  },
  AvgDialog_131215_Content_111 = {
    Text = "Kakak, kau tidak bisa berhenti menenun jaring, karena kau tidak bisa membiarkan nasib alam semesta ini jatuh ke dalam kekacauan. Dan pada hari jaringmu selesai tertenun, kau akan menghancurkan dengan tanganmu sendiri semua yang kau cintai……"
  },
  AvgDialog_131215_Content_112 = {
    Text = "Sungguh ironis, Arachne. Mengapa? Mengapa, tidak membiarkan alam semesta ini menyambut akhir yang ditakdirkan dengan sukacita?"
  },
  AvgDialog_131215_Content_113 = {
    Text = "Segala sesuatu yang berkaitan dengan takdir, pasti ada kepastian. Segala sesuatu yang berkaitan dengan takdir, pasti ada variabel. Dua kalimat yang saling bertentangan ini adalah hakikat dari takdir."
  },
  AvgDialog_131215_Content_114 = {
    Text = "Arachne menatap mata Nefraea, menjawab pertanyaan yang pernah dia jawab berkali-kali pada dirinya sendiri."
  },
  AvgDialog_131215_Content_115 = {
    Text = "Nefraea, di dimensi yang tak berujung, masih ada banyak orang yang berjuang untuk variabel itu."
  },
  AvgDialog_131215_Content_116 = {
    Text = "Menjaga agar panggung tetap beroperasi, menunggu munculnya variabel… Inilah belenggu yang dikenakan takdir padaku. Ini adalah tanggung jawab yang tidak bisa kuhindari."
  },
  AvgDialog_131215_Content_117 = {
    Text = "Tanggung jawab, bahaya... Kamu berbicara tentang semua yang megah itu, tapi tidak pernah membicarakan dirimu sendiri, Arachne, saudariku yang malang. Tapi tidak apa-apa, tanggung jawabmu yang menyakitkan akan segera berakhir."
  },
  AvgDialog_131215_Content_118 = {
    Text = "Nefraea dengan lembut mengelus wajah Arachne, sambil memberikan senyuman manis kepadanya."
  },
  AvgDialog_131215_Content_119 = {
    Text = "Di dalam jurang, aku membayangkan berkali-kali gambaran kita bertemu kembali, aku berpikir, hadiah seperti apa yang pantas untuk pertemuan kembali kita ini."
  },
  AvgDialog_131215_Content_12 = {
    Text = "Hal-hal ini, kenapa tidak ada yang memberitahuku sebelumnya?"
  },
  AvgDialog_131215_Content_120 = {
    Text = "Aku sudah memikirkan ini lama, sangat lama. Aku telah memikirkan, kakak tercinta! Ini adalah hadiah terbaik yang bisa aku berikan untukmu——"
  },
  AvgDialog_131215_Content_121 = {
    Text = "——<Red:Pembebasan>."
  },
  AvgDialog_131215_Content_122 = {
    Text = "Dalam kata-kata lembut Nefraea, cairan hitam berkumpul di antara celah dimensi. Di ujung jaring laba-laba, sebuah panggung megah muncul di depan kalian."
  },
  AvgDialog_131215_Content_13 = {
    Text = "Kamu melihat ke arah Arachne yang membimbing langkahmu."
  },
  AvgDialog_131215_Content_14 = {
    Text = "Sebuah batu yang tidak akan membangkitkan riak apa pun di danau nasib, selain menghancurkan ketenangan danau, sama sekali tidak berguna."
  },
  AvgDialog_131215_Content_15 = {
    Text = "Dia dan aku, sudah sejak lama menjadi dua orang yang berbeda, Penjaga Rahasia {Male=先生,Female=小姐}."
  },
  AvgDialog_131215_Content_16 = {
    Text = "Apakah kamu sudah memprediksi hari ini?"
  },
  AvgDialog_131215_Content_17 = {
    Text = "Sebelum menerima vonis takdir, tak ada tahanan yang bisa melihat jelas nasibnya sendiri."
  },
  AvgDialog_131215_Content_18 = {
    Text = "Jika kamu tahu bahwa nasib yang terbuang tidak akan menghilang, melainkan akan terasing ke dalam jurang yang abadi... apakah kamu masih akan melakukan hal-hal ini, Arachne?"
  },
  AvgDialog_131215_Content_2 = {
    Text = "La la la la…"
  },
  AvgDialog_131215_Content_20 = {
    Text = "Diam. Diam adalah bencana abadi bagi penulis drama. Diam adalah pertahanan tak berdaya dari tahanan. Dalam keheningan yang seperti hukuman mati, terdengar suara tawa gila Nefraea."
  },
  AvgDialog_131215_Content_21 = {
    Text = "Ah, tentu saja kamu bisa, Kakak. Nasib adalah ajaranmu, semua, semua syarat, tidak dapat mengubah satu-satunya jawaban itu."
  },
  AvgDialog_131215_Content_22 = {
    Text = "Dewi nasib, betapa kecil, betapa rapuh, betapa kejam…"
  },
  AvgDialog_131215_Content_23 = {
    Text = "Tapi tidak apa-apa. Apa pun yang kamu lakukan, selama waktu yang panjang ini, aku selalu mengkhawatirkanmu, kakak tersayangku."
  },
  AvgDialog_131215_Content_24 = {
    Text = "Romantis, baik hati, kenangan. Campuran bahan yang indah, difermentasi, mengolah senyuman Nefraea menjadi racun manis."
  },
  AvgDialog_131215_Content_25 = {
    Text = "Di balik senyumnya yang cerah, cahaya di samping jalan yang dipenuhi jaring laba-laba menerangi panggung."
  },
  AvgDialog_131215_Content_26 = {
    Text = "Kakak, Penjaga Rahasia {Male=先生,Female=小姐}, drama-drama baru yang dipentaskan ini adalah hadiah dariku sebagai pemilik baru teater untuk kalian."
  },
  AvgDialog_131215_Content_27 = {
    Text = "Sebelum pertunjukan megah di Babak Tiga dimulai, nikmatilah prelud yang indah ini… Ingatlah etika menonton di Teater Nasib, jangan berbicara ya"
  },
  AvgDialog_131215_Content_28 = {
    Text = "Nefraea membuka kedua tangannya seperti Pembawa Acara. Panggung yang bercahaya seperti bintang-bintang di sepanjang jalan, menyala satu per satu saat kalian melangkah perlahan."
  },
  AvgDialog_131215_Content_3 = {
    Text = "Mereka menari. Mereka bernyanyi. Ciiit ciiit~"
  },
  AvgDialog_131215_Content_30 = {
    Text = "Dewi nasib yang terhormat, tubuh dari tiga pasangan rahasia telah disiapkan untuk Anda."
  },
  AvgDialog_131215_Content_31 = {
    Text = "Betapa halusnya boneka-boneka itu…… Hal-hal yang telah hilang akan terulang kembali di dalamnya……"
  },
  AvgDialog_131215_Content_32 = {
    Text = "\"Arachne\" meninggalkan alat tenun dan mendekati boneka."
  },
  AvgDialog_131215_Content_33 = {
    Text = "Yang pertama, aku berikan padamu sebagai \"Romantis\"."
  },
  AvgDialog_131215_Content_34 = {
    Text = "Kamu adalah bagian paling bersemangat dari simfoni, kumpulan emosi, buah yang dihasilkan oleh bunga musim semi."
  },
  AvgDialog_131215_Content_35 = {
    Text = "Kau akan pergi ke Taman Hiburan tengah malam, membawa anggur, pertemuan, dan dorongan yang takkan pernah pudar bagi kota ini."
  },
  AvgDialog_131215_Content_36 = {
    Text = "Terima kasih, Dewi Nasib yang Agung Arachne. Sesuai dengan kehendak Anda, anggur dan madu akan mengalir di antara bibir dan gigi saya."
  },
  AvgDialog_131215_Content_37 = {
    Text = "Seorang wanita cantik memberi hormat kepada \"Arachne\"."
  },
  AvgDialog_131215_Content_38 = {
    Text = "Kedua, aku berikan kamu sebagai \"Kebaikan\"."
  },
  AvgDialog_131215_Content_39 = {
    Text = "Kamu adalah lansia yang pernah menemani saya melewati masa kanak-kanak. Kamu adalah bulu putih yang terjatuh dari malaikat, sinar matahari yang paling suci."
  },
  AvgDialog_131215_Content_4 = {
    Text = "Kisah yang jauh dan langkah yang menyenangkan bergetar di jaring laba-laba. Nefraea mengangkat kedua tangannya di belakang tubuh, melompat dengan ceria sambil berjalan maju."
  },
  AvgDialog_131215_Content_40 = {
    Text = "Kamu akan datang ke jalanan kota, menggunakan kebaikanmu untuk menghangatkan segala sesuatu yang kamu lihat."
  },
  AvgDialog_131215_Content_41 = {
    Text = "Terima kasih! Dewi nasib yang agung, Arachne. HP saya diberikan oleh Anda, tidak ada cara untuk membalasnya."
  },
  AvgDialog_131215_Content_42 = {
    Text = "Aku tidak memiliki apa-apa, hanya mencintai segalanya di dunia ini. Aku akan melindungi apa yang harus dilindungi, membantu apa yang harus dibantu."
  },
  AvgDialog_131215_Content_43 = {
    Text = "Segala yang aku miliki, terbuka untuk para korban."
  },
  AvgDialog_131215_Content_44 = {
    Text = "Lansia yang baik hati memberi hormat yang dalam kepada \"Arachne\"."
  },
  AvgDialog_131215_Content_45 = {
    Text = "Dan kamu, tubuh ketiga... aku memberimu nama \"Kenangan\"."
  },
  AvgDialog_131215_Content_46 = {
    Text = "\"Arakne\" datang di depan Misteri Pasangan yang pendek itu, berjongkok dan menatap matanya yang tidak ada."
  },
  AvgDialog_131215_Content_47 = {
    Text = "Kamu adalah anak yatim nasib, terkubur di bawah daun-daun kering yang tertutup salju dalam."
  },
  AvgDialog_131215_Content_48 = {
    Text = "Kau berjalan sendirian, tak bisa berbicara, tidak diketahui oleh dunia."
  },
  AvgDialog_131215_Content_49 = {
    Text = "Dalam kehidupanmu yang tenang dan panjang, kamu akan menjadi satu-satunya Penjaga Makam dari kenangan-kenangan itu."
  },
  AvgDialog_131215_Content_5 = {
    Text = "Kamu mengikuti Arachne tanpa bisa melawan, berjalan di sepanjang jaring laba-laba menuju ujungnya."
  },
  AvgDialog_131215_Content_50 = {
    Text = "Gadis yang diam mengangkat kepalanya dan dengan lembut membelai wajah \"Arachne\"."
  },
  AvgDialog_131215_Content_51 = {
    Text = "\"Arachne\" berdiri, dengan lembut memandang pasangan-pasangan misterinya."
  },
  AvgDialog_131215_Content_52 = {
    Text = "Pergilah, anak-anakku. Di depan mesin tenun nasib, aku akan selalu mengawasi kalian."
  },
  AvgDialog_131215_Content_53 = {
    Text = "Yang telah ditinggalkan oleh keabadian, akan mekar satu per satu dalam nasib kalian."
  },
  AvgDialog_131215_Content_55 = {
    Text = "Panggung menjadi gelap. Bersama langkah kalian, lampu panggung berikutnya menyala."
  },
  AvgDialog_131215_Content_56 = {
    Text = "Sinarlah tidak ada di tempat ini. Angin, bunga, awan… Setelah tiga abad yang panjang berlalu, kalender pun tidak ada lagi…"
  },
  AvgDialog_131215_Content_57 = {
    Text = "Tuan, pengabaian baru telah tiba."
  },
  AvgDialog_131215_Content_58 = {
    Text = "Oboe bergema. Yang Terbuang berpakaian compang-camping naik ke panggung."
  },
  AvgDialog_131215_Content_59 = {
    Text = "\"Nefraea\" berdiri dan pergi ke tengah panggung."
  },
  AvgDialog_131215_Content_6 = {
    Text = "Bagaimana, Penjaga Rahasia {Male=先生,Female=小姐}! Pertunjukan tadi, ditambah kisah di balik layar ini, bukankah sangat menakjubkan!"
  },
  AvgDialog_131215_Content_60 = {
    Text = "Ceritakan padaku, anak-anak malang...... siapa kalian, dari mana kalian berasal?"
  },
  AvgDialog_131215_Content_61 = {
    Text = "Dewi nasib, mohon maafkan ketidak sopanan saya... tetapi kemarahan memaksa saya untuk bertanya kepada Anda."
  },
  AvgDialog_131215_Content_62 = {
    Text = "Aku melewati rintangan, dengan keberanian dan kehidupanku meninggalkan lagu agung, yang seharusnya berjalan bersama tanah airku, sampai ke ujung alam semesta."
  },
  AvgDialog_131215_Content_63 = {
    Text = "Mengapa, Dewi yang agung... mengapa mengusir kami ke tanah tandus ini? <Shake:Mengapa, mengubah simfoni abadi itu menjadi debu!>"
  },
  AvgDialog_131215_Content_64 = {
    Text = "Prajurit-prajuritku baru saja melewati musim dingin yang panjang. Kami telah mengusir para penyerang yang biadab, membela peradaban dan sejarah kami."
  },
  AvgDialog_131215_Content_65 = {
    Text = "Di saat yang paling mengerikan, prajurit-prajurit yang terluka secara sukarela mengorbankan caro mereka, untuk makanan rekan-rekan mereka... Betapa menyedihkannya kemenangan ini, dewi saya."
  },
  AvgDialog_131215_Content_66 = {
    Text = "Ketika musuh mundur, air mata kebahagiaan menggenang di mata semua orang. Di pesta perayaan, aku akan mengisi cangkir setiap prajurit dengan minuman keras."
  },
  AvgDialog_131215_Content_67 = {
    Text = "Namun pada saat ini, sebelum kita mengangkat gelas untuk merayakan, rumah kita telah menjadi reruntuhan, dan orang-orang terkasih kita telah lenyap menjadi debu..."
  },
  AvgDialog_131215_Content_68 = {
    Text = "<Shake:Wahai Dewi Takdir yang kami hormati, apakah Engkau tak sudi memberikan kami walau sejenak kebahagiaan?>"
  },
  AvgDialog_131215_Content_7 = {
    Text = "Nefraea sudah keluar dari keadaan kegilaan di atas panggung, dia menoleh, menatapmu dengan penuh harapan."
  },
  AvgDialog_131215_Content_70 = {
    Text = "\"Nefraea\" mendengarkan cerita boneka-boneka yang seolah-olah tidak pernah berhenti, di wajahnya yang tanpa fitur, ternyata mengalir dua baris air mata."
  },
  AvgDialog_131215_Content_71 = {
    Text = "Saya mendengar kalian, melihat kalian..."
  },
  AvgDialog_131215_Content_72 = {
    Text = "Peradaban yang agung lenyap dari tanganmu; seni dan arsitektur yang megah berubah menjadi debu. Orang-orang yang saling mencintai melupakan segalanya tentang satu sama lain, menyambut kehancuran yang menyakitkan dalam ketakutan..."
  },
  AvgDialog_131215_Content_73 = {
    Text = "Hanya satu nasib yang benar akan tersisa, dan saat itu terjadi, segala kesalahan yang tak terhitung akan mengalir ke dalam jurang yang liar dan tanpa dasar ini. Begitu panjang seperti waktu yang terhenti, cerita seperti ini dimainkan setiap hari."
  },
  AvgDialog_131215_Content_74 = {
    Text = "Kamu ingin aku melihat berapa lama, mendengar berapa lama, kakakku tercinta..."
  },
  AvgDialog_131215_Content_75 = {
    Text = "\"Nefraea\" menghadap penonton dan menarik napas dalam-dalam, lalu berbalik."
  },
  AvgDialog_131215_Content_76 = {
    Text = "Jangan khawatir, anak-anak baikku... penderitaan kalian yang aku ciptakan, akan aku akhiri."
  },
  AvgDialog_131215_Content_77 = {
    Text = "Silakan beristirahat di sini untuk sementara waktu. Suatu hari nanti, aku akan membawa kalian meninggalkan tempat ini, dan aku akan membuat kalian menemukan kembali nasib kalian yang sebenarnya…"
  },
  AvgDialog_131215_Content_78 = {
    Text = "Dengan nama Nefraea, pembalas nasib, aku berjanji kepada kalian......"
  },
  AvgDialog_131215_Content_8 = {
    Text = "Melihat wajahmu yang diam, dia menggelengkan kepala dengan kecewa."
  },
  AvgDialog_131215_Content_80 = {
    Text = "Lalalala... lalala..."
  },
  AvgDialog_131215_Content_81 = {
    Text = "Panggung semakin menjauh, sebelum lampu padam, kamu melihat kedua lengan boneka yang terbuka, serta jejak air mata hitam di wajahnya."
  },
  AvgDialog_131215_Content_82 = {
    Text = "Kalian tidak berbicara, hanya Nefraea yang dengan lembut menyanyikan melodi di atas panggung. Suaranya cepat dan jernih, cerita yang telah dipentaskan berkali-kali ini tidak membuatnya merasakan emosi berlebih lagi."
  },
  AvgDialog_131215_Content_83 = {
    Text = "Aduh! Salah satu panggung favoritku akan segera tiba! Cepatlah, Kakak"
  },
  AvgDialog_131215_Content_84 = {
    Text = "Suara Nefraea menjadi penuh keseruan. Dia menarik tangan Arachne dan berlari dengan ceria menuju panggung di depan."
  },
  AvgDialog_131215_Content_86 = {
    Text = "Lampu menyala. Tanpa musik, tanpa dialog, di atas panggung yang kosong, hanya ada sosok kesepian yang duduk di depan roda pemintal."
  },
  AvgDialog_131215_Content_87 = {
    Text = "Kriet, kriet. Roda pemintal terus berputar, seolah tak akan pernah ada hari di mana ia berhenti."
  },
  AvgDialog_131215_Content_88 = {
    Text = "……Mereka menari. Mereka bernyanyi. Ciiit——Ciiit——"
  },
  AvgDialog_131215_Content_89 = {
    Text = "Sinar matahari menerangi wajah mereka, betapa senangnya——"
  },
  AvgDialog_131215_Content_9 = {
    Text = "Tidak ada tepuk tangan, juga tidak ada air mata. Keheningan adalah sebuah penghinaan... Aku pikir setelah berlatih begitu lama di dalam neraka, penampilan ini sudah sempurna, sayang sekali."
  },
  AvgDialog_131215_Content_90 = {
    Text = "Lagu dinyanyikan lembut dari wajah \"Arachne\" yang tanpa fitur, dia dengan tenang memutar roda pemintal, tidak terburu-buru dan tidak lambat."
  },
  AvgDialog_131215_Content_91 = {
    Text = "Itu adalah irama yang aneh, cukup sekali pandang dan kau akan mengerti, begitu irama itu dimulai ia akan kekal tak berubah, hingga hari di mana segalanya mencapai ujungnya."
  },
  AvgDialog_131215_Content_92 = {
    Text = "Dewi nasib, segera akan menenun jaringnya dengan baik."
  },
  AvgDialog_131215_Content_93 = {
    Text = "Jaring nasib yang utuh, melindungi semua orang... mereka menari, mereka bernyanyi..."
  },
  AvgDialog_131215_Content_94 = {
    Text = "Sebuah jaring raksasa ditenun oleh alat tenun, membentang di seluruh panggung. Bagian berlebih dari jaring nasib merambat ke bawah panggung."
  },
  AvgDialog_131215_Content_95 = {
    Text = "Setiap kali jaring itu hampir selesai ditenun, bagian terluarnya mulai meleleh."
  },
  AvgDialog_131215_Content_96 = {
    Text = "Cairan hitam, debu hitam, akhirnya lenyap tanpa jejak. Itu adalah pemandangan yang sangat kamu kenal."
  },
  AvgDialog_131215_Content_97 = {
    Text = "Rayakanlah, anakku, bangsaku... Dewi nasib, akan segera menyusun jaringnya..."
  },
  AvgDialog_131215_Content_98 = {
    Text = "Boneka memandang jaring yang terus dijalin dan terus menghilang."
  },
  AvgDialog_131215_Content_99 = {
    Text = "Suara dia tidak bergetar, gerakannya tidak ragu. Dia masih menyanyikan lagu dengan lembut, roda penggulung di tangannya berputar, tanpa henti."
  },
  AvgDialog_131216_Content_1 = {
    Text = "Pesta Topeng"
  },
  AvgDialog_131216_Content_10 = {
    Text = "Sungguh standar ganda yang tidak tersembunyi, Kakak Senior."
  },
  AvgDialog_131216_Content_11 = {
    Text = "Ehem... Membuat penilaian yang sesuai dengan karakter orang yang berbeda adalah keterampilan dasar seorang penyelidik..."
  },
  AvgDialog_131216_Content_12 = {
    Text = "William berpura-pura tidak mendengar ejekanmu, mulai serius mencari target yang layak untuk ditanya."
  },
  AvgDialog_131216_Content_13 = {
    Text = "Saya kehilangan segalanya dalam pertempuran itu. Gelar saya, keluarga saya, kaki kiri saya, hidup saya."
  },
  AvgDialog_131216_Content_14 = {
    Text = "Dua puluh tahun, tepat dua puluh tahun. Ini adalah siksaan, temanku. Nasib membuatku bertahan hidup, membiarkanku menebus dosa-dosaku dengan sisa hidupku."
  },
  AvgDialog_131216_Content_15 = {
    Text = "Keluargaku hancur di tanganku, tapi apa artinya? Katakan padaku, apa yang lebih penting dalam hidup daripada alkohol?"
  },
  AvgDialog_131216_Content_17 = {
    Text = "Ah, sayang, apakah kamu masih ingat minuman yang dibuatkan oleh bartender untuk kita saat terakhir kali datang ke sini?"
  },
  AvgDialog_131216_Content_18 = {
    Text = "Saya berani bertaruh, seantero Londinium tidak akan menemukan anggur yang lebih enak daripada itu. Rasanya begitu tepat, elegan, seperti sebuah ramalan"
  },
  AvgDialog_131216_Content_19 = {
    Text = "Saya ingin, seandainya bulan depan pesta bisa mengundang orang ini, bartender, itu akan sangat baik."
  },
  AvgDialog_131216_Content_2 = {
    Text = "\"90 menit tengah malam, 15 inci topeng palsu, 10 galon mimpi, 2 ons alkohol—— satu-satunya resep kebahagiaan\""
  },
  AvgDialog_131216_Content_21 = {Text = "Pak—"},
  AvgDialog_131216_Content_22 = {
    Text = "Jentikan jari yang nyaring seperti kembang api melintas di telinga kalian. Kalian berbalik dan melihat sebuah wajah dengan senyuman yang cerah."
  },
  AvgDialog_131216_Content_23 = {
    Text = "Maaf mengganggu, tamu yang terhormat. Mendengar begitu banyak topik menarik, apakah Anda ingin menikmati segelas minuman yang menarik?"
  },
  AvgDialog_131216_Content_24 = {
    Text = "Lihat daftar minuman, Kak William."
  },
  AvgDialog_131216_Content_25 = {
    Text = "William memahami tatapanmu. Dua orang yang mengenakan seragam tak dikenal muncul di tempat ini, tidak menyentuh alkohol dari awal hingga akhir, sungguh sulit untuk tidak menarik perhatian orang."
  },
  AvgDialog_131216_Content_26 = {
    Text = "Melihat tatapan matanya yang mencari daftar minuman, bartender itu tersenyum sambil menggelengkan kepala."
  },
  AvgDialog_131216_Content_27 = {
    Text = "Daftar minuman? Ah, membosankan, tidak menarik, klise."
  },
  AvgDialog_131216_Content_28 = {
    Text = "Sebuah taverna yang romantis, tidak seharusnya ada hal yang membosankan seperti ini."
  },
  AvgDialog_131216_Content_29 = {
    Text = "Tidak ada daftar minuman? Lalu bagaimana kita bisa memesan?"
  },
  AvgDialog_131216_Content_3 = {
    Text = "Aku sudah menghafal slogan iklan bar \"Topeng Tengah Malam\". Saat di Kadas, ini adalah tempat yang paling ingin aku kunjungi."
  },
  AvgDialog_131216_Content_30 = {
    Text = "Setiap kursi di tengah malam adalah teater yang hanya dimiliki oleh satu orang tamu. Kalian di sini untuk menonton, pertunjukan, dan menikmati..."
  },
  AvgDialog_131216_Content_31 = {
    Text = "Di antara ribuan cerita, saya akan memilih bagian yang paling cocok untuk Anda."
  },
  AvgDialog_131216_Content_32 = {
    Text = "Silakan duduk, kalian berdua. Pembaca cerita sudah siap."
  },
  AvgDialog_131216_Content_33 = {
    Text = "Kamu bertukar tatapan dengan William, ragu-ragu duduk di dekat posisi bar."
  },
  AvgDialog_131216_Content_34 = {
    Text = "Pertama-tama, Anda, Tuan berambut emas dengan ekspresi dingin."
  },
  AvgDialog_131216_Content_35 = {
    Text = "Bartender datang di depan kalian. Menghadapi tatapan mata yang mengamati dengan saksama itu, William batuk pelan dan sedikit merasa tidak nyaman mengalihkan pandangannya."
  },
  AvgDialog_131216_Content_36 = {
    Text = "Ah... Latihan yang ketat hari demi hari, membawa pencapaian yang luar biasa. Ketekunan, ketenangan, ketangguhan, keberanian, kebijaksanaan... Seorang legenda yang hidup, dikelilingi oleh bunga dan cahaya."
  },
  AvgDialog_131216_Content_37 = {
    Text = "Dan di balik semua pujian dan kemuliaan itu adalah... penyesalan. Penyesalan yang lebih dalam dan lebih menyakitkan daripada kabut kota ini."
  },
  AvgDialog_131216_Content_38 = {
    Text = "Berapa banyak cahaya air mata yang tak terlihat di malam yang dalam. Janji-janji yang diucapkan satu per satu kepada diri sendiri."
  },
  AvgDialog_131216_Content_39 = {
    Text = "Cahaya yang pernah menerangi kamu di lorong kegelapan itu, padam dalam kegelapan yang tak berujung, bersama dengan duniamu, hancur, hancur…"
  },
  AvgDialog_131216_Content_4 = {
    Text = "Apakah peraturan manajemen Mythag kadang-kadang terlalu ketat?"
  },
  AvgDialog_131216_Content_40 = {
    Text = "Kamu berpikir, jika saja kamu bisa lebih giat, jika saja kamu bisa lebih kuat, mungkin, kamu bisa memberikan akhir yang berbeda bagi orang-orang di sekitarmu..."
  },
  AvgDialog_131216_Content_41 = {
    Text = "Ekspresi di wajah William tampaknya tidak berubah, tapi kamu melihat jejak pembuluh darah biru yang jelas di tangannya yang menggenggam gelas."
  },
  AvgDialog_131216_Content_42 = {
    Text = "Aku mendengar suara dunia yang hancur. Anak kecil itu menahan rasa sakit, mengumpulkan potongan-potongan itu satu per satu, menyatukannya…"
  },
  AvgDialog_131216_Content_43 = {
    Text = "Dalam sambungan yang panjang dan kejam ini, anak laki-laki itu akhirnya tumbuh menjadi seorang pria."
  },
  AvgDialog_131216_Content_44 = {
    Text = "Seorang bartender dengan suara panjang yang lembut mulai meracik, sambil mengambil beberapa botol dengan berbagai bentuk dari rak minuman di belakangnya yang seolah-olah tidak ada akhirnya."
  },
  AvgDialog_131216_Content_45 = {
    Text = "Dengan cepat, cairan berwarna emas pucat yang terisi dalam gelas klasik didorong ke depan William."
  },
  AvgDialog_131216_Content_46 = {
    Text = "2 ons Whiskey, 1 ons anggur putih, dan latar belakang yang menyakitkan dan tangguh — 2 tetes pahit."
  },
  AvgDialog_131216_Content_47 = {
    Text = "<Yellow:\"Sang Penunjuk Jalan\">. Semoga Anda bisa memimpin mereka yang mengagumi Anda untuk menemukan jalan yang benar bersama-sama — seperti orang yang Anda kagumi, pernah memimpin Anda."
  },
  AvgDialog_131216_Content_48 = {
    Text = "William menerima gelas berisi cairan keemasan itu, menggoyang-goyangkannya perlahan di tangan, tatapannya meneliti bartender di hadapannya."
  },
  AvgDialog_131216_Content_49 = {
    Text = "Apa yang baru saja kamu katakan... bagaimana kamu bisa tahu?"
  },
  AvgDialog_131216_Content_5 = {
    Text = "Saya mengusulkan untuk melarang pelajar Mythag memasuki tempat-tempat seperti ini tanpa izin, demi mencegah beberapa Penjaga yang tidak bertanggung jawab, yang mengatasnamakan tugas penyelidikan untuk menyia-nyiakan dana misi."
  },
  AvgDialog_131216_Content_50 = {
    Text = "Seorang bartender yang baik harus mampu mendengarkan suara hati tamunya. Ini adalah rahasia milik bartender, tamu yang terhormat."
  },
  AvgDialog_131216_Content_51 = {
    Text = "Bartender itu melompati tatapan tajam William dengan lincah bagai rusa kecil. Jarinya bergoyang pelan di depan bibirnya, lalu menunjuk ke arahmu."
  },
  AvgDialog_131216_Content_52 = {
    Text = "Giliran Anda, tamu ini..."
  },
  AvgDialog_131216_Content_53 = {
    Text = "Saya memiliki firasat, ini mungkin adalah hal terberbahaya yang pernah saya coba dalam hidup ini — tetapi tidak apa-apa, saya mencintai petualangan."
  },
  AvgDialog_131216_Content_54 = {
    Text = "Dia datang ke hadapanmu, menatap matamu dengan serius. Kamu hampir bisa mendengar napasnya yang lembut."
  },
  AvgDialog_131216_Content_55 = {
    Text = "Hmm... apa yang saya tatap adalah tamu dari jauh, atau mungkin... seorang dewa yang jatuh ke dunia manusia dan menghadapi banyak kesulitan?"
  },
  AvgDialog_131216_Content_56 = {Text = "?!!"},
  AvgDialog_131216_Content_57 = {
    Text = "Kamu secara naluriah bangkit dan mundur dua langkah."
  },
  AvgDialog_131216_Content_58 = {
    Text = "Ini tidak mungkin sesuatu yang bisa diketahui oleh seorang bartender biasa... Siapa sebenarnya kamu?"
  },
  AvgDialog_131216_Content_59 = {
    Text = "Ah, tenang saja, tamu yang terkasih, di bar ini, aku bukanlah orang yang berniat jahat."
  },
  AvgDialog_131216_Content_6 = {
    Text = "Bagaimanapun, dalam perjalanan belajar orang ini sebagai Penjaga, ada banyak catatan buruk."
  },
  AvgDialog_131216_Content_60 = {
    Text = "Mungkin kamu sudah memperhatikan, di belakangmu, ada beberapa \"teman lama\" yang datang."
  },
  AvgDialog_131216_Content_61 = {
    Text = "%player%, di belakang."
  },
  AvgDialog_131216_Content_62 = {
    Text = "Aku merasakannya..."
  },
  AvgDialog_131216_Content_63 = {
    Text = "Dengan pengingat dari bartender, kamu menyadari bahwa belasan gelombang mental yang kuat mendekat dengan cepat dari segala arah."
  },
  AvgDialog_131216_Content_64 = {
    Text = "William berdiri di belakangmu dengan penuh kewaspadaan, mengawasi arah yang lain. Kamu menggenggam erat kunci perak itu, menatap serius bartender misterius seperti kabut di hadapanmu."
  },
  AvgDialog_131216_Content_65 = {
    Text = "Bartender meletakkan gelas di tangannya dan menempatkan botol anggur di atas meja ke sudut yang tidak mudah pecah."
  },
  AvgDialog_131216_Content_66 = {
    Text = "Tolong jangan tegang, %player%. Jejak kalian sudah lama mereka ketahui. Di tempat ini, setidaknya aku masih bisa membantu kalian."
  },
  AvgDialog_131216_Content_67 = {
    Text = "Kamu? Mereka?…"
  },
  AvgDialog_131216_Content_68 = {
    Text = "Heh... ketemu kalian."
  },
  AvgDialog_131216_Content_69 = {
    Text = "Tempat kotor seperti ini tidak cocok untuk kalian berlama-lama, tamu kecil dari negeri asing."
  },
  AvgDialog_131216_Content_7 = {
    Text = "Saya ingat bahwa di arsip Senior Fengol disebutkan, hobi terbesarnya adalah minum sedikit di Midnight Masquerade setelah selesai bekerja…"
  },
  AvgDialog_131216_Content_70 = {
    Text = "Hati-hati, mereka sudah datang"
  },
  AvgDialog_131216_Content_8 = {
    Text = "…Tentu saja, istirahat sesekali bukanlah hal yang sepenuhnya buruk."
  },
  AvgDialog_131216_Content_9 = {
    Text = "Selain itu, daftar anggota topeng tengah malam mencakup seluruh tokoh terkenal di Londinium, menjadikannya tempat yang sempurna untuk mengumpulkan informasi."
  },
  AvgDialog_131217_Content_1 = {
    Text = "Kekuasaan dari tiga plasmid telah tenang di dalam tubuhmu, tetapi kamu masih belum membuka mata."
  },
  AvgDialog_131217_Content_10 = {
    Text = "Semangat kontrak, prinsip bisnis dan semacamnya... transaksi selalu membutuhkan modal tawar, kau paham soal ini, bukan?"
  },
  AvgDialog_131217_Content_11 = {
    Text = "\"N\" menggelengkan kepalanya, tampaknya butuh usaha besar untuk menahan tawanya."
  },
  AvgDialog_131217_Content_12 = {
    Text = "Kabar baiknya, kau selalu punya modal tawar yang sempurna."
  },
  AvgDialog_131217_Content_13 = {
    Text = "Sang pejuang pemberani yang akan meninggalkan keyakinannya, tenggelam dalam jaring besar takdir, menipu, memperdaya, tanpa batas... betapa menawannya adegan ini!"
  },
  AvgDialog_131217_Content_14 = {
    Text = "Kursi penonton terbaik, aku tak mau melewatkannya."
  },
  AvgDialog_131217_Content_15 = {
    Text = "Kapan aku pernah bilang…"
  },
  AvgDialog_131217_Content_16 = {
    Text = "Sang Penikmat tidak punya kesabaran untuk menjawab keraguanmu. Dia menimbang-nimbang apa yang akan kau bayarkan di masa depan, tersenyum sambil menggoyang-goyangkan jarinya."
  },
  AvgDialog_131217_Content_17 = {
    Text = "Petunjuk tidak bisa dianggap, hanya sebuah saran kecil yang tulus."
  },
  AvgDialog_131217_Content_18 = {
    Text = "Mengapa harus melawan Nefraea? Mengapa tidak tunduk padanya, Penjaga {Male=Tuanku, Female=Nyonyaku}?"
  },
  AvgDialog_131217_Content_19 = {
    Text = "\"N\" tersenyum mendekat ke hadapanmu, ramah bagaikan seorang pengacara yang sedang mengunjungi kliennya di penjara."
  },
  AvgDialog_131217_Content_2 = {
    Text = "Kesadaranmu menyelam ke dalam lautan roh yang luas, menyelam lebih dalam, sampai ke kegelapan yang tak terhingga, sampai ke jurang milikmu sendiri yang tak dapat kau lihat dengan jelas."
  },
  AvgDialog_131217_Content_20 = {
    Text = "Kamu... apa yang kamu katakan? Tidak, aku tidak mungkin..."
  },
  AvgDialog_131217_Content_21 = {
    Text = "Ah, benar, tidak akan menyerah, tidak akan mundur, tidak akan mengakui tindakan Nefraea... heroisme yang kuno dan klasik."
  },
  AvgDialog_131217_Content_22 = {
    Text = "Kirimkan kami kepada Nefraea, memanggil orang itu sepupu tercintamu, kembali ke istana yang menjadi milikmu... Selain itu, apa lagi yang bisa kamu lakukan sekarang, %player%?"
  },
  AvgDialog_131217_Content_23 = {
    Text = "Aku akan memberimu sebuah rahasia: karena kamu tidak bisa melarikan diri dari jaring itu, mengapa tidak membuka kedua tanganmu dan menyambut kedatangan jaring itu?"
  },
  AvgDialog_131217_Content_24 = {
    Text = "Berhenti bermimpi, \"N\", aku tidak mungkin..."
  },
  AvgDialog_131217_Content_25 = {
    Text = "Ssst. Jangan terlalu mudah membatasi dirimu, sayang."
  },
  AvgDialog_131217_Content_26 = {
    Text = "Jangan lupa, Arachne telah menghubungkan nasibmu ke dalam jaring raksasa. Kamu, sudah menjadi bagian dari mereka."
  },
  AvgDialog_131217_Content_27 = {
    Text = "Orang itu, dewi nasib, memberimu sebuah kunci yang bernama Kesukacitaan. Tapi, apakah kamu pernah berpikir, pintu itu sebenarnya mengarah ke mana, dan menuju ke mana?"
  },
  AvgDialog_131217_Content_28 = {
    Text = "Pintu menghadap ke mana... pintu menuju ke mana?..."
  },
  AvgDialog_131217_Content_29 = {
    Text = "Saya kira, Arachne adalah seorang wanita yang pekerja keras, baik hati, dan membosankan, satu-satunya yang bisa dia lakukan adalah menjaring dan tersenyum. Tetapi dia jauh lebih menarik daripada yang saya bayangkan."
  },
  AvgDialog_131217_Content_3 = {
    Text = "Kamu berusaha membuka mulut yang tidak ada, berteriak dengan marah dan tanpa suara di dalam jurang ini."
  },
  AvgDialog_131217_Content_30 = {
    Text = "Dia telah menenun jaring besar untuk panggung ini, sejak detik pertama kau tiba di dunia ini, jaring ini mulai membentangkan untukmu."
  },
  AvgDialog_131217_Content_31 = {
    Text = "Memiliki kemampuan yang luar biasa seperti ini, tetapi terjebak dalam hal-hal bodoh seperti menjaga agar dunia tetap berputar... Sayang sekali, sungguh sangat disayangkan."
  },
  AvgDialog_131217_Content_32 = {
    Text = "Melangkah ke panggung teater takdir, maka kamu akan menjadi karakter di atas panggung. Setiap karakter, memiliki kehidupannya sendiri."
  },
  AvgDialog_131217_Content_33 = {
    Text = "Nasib membiarkanmu membuat pilihan ini, agar kamu bisa melihatnya dengan jelas. Kamu tidak bisa melihat benang-benang itu, tetapi sekarang kamu sudah mengerti, bagaimana benang-benang ini saling berjalin dengan cara yang rumit."
  },
  AvgDialog_131217_Content_34 = {
    Text = "Benang nasib menenun jaring raksasa, setiap getaran lembut dari benang mungkin akan membuat jaring nasib terbalik."
  },
  AvgDialog_131217_Content_35 = {
    Text = "Inilah takdir, Penjaga Rahasia {Male=先生,Female=小姐}."
  },
  AvgDialog_131217_Content_36 = {
    Text = "Pertunjukan, memperdaya, menyenangkan... di dalam dirimu, terdapat kekuatan seperti itu. Panggung nasib tidak akan memberikan kesempatan yang sama untuk semua orang. Ketika kamu perlu naik ke panggung, kekuatan ini akan membantumu."
  },
  AvgDialog_131217_Content_37 = {
    Text = "Kamu tidak bisa menghindari panggung yang ditakdirkan untuk datang. Berpikirlah, lalu tampilkanlah, Penjaga Rahasia {Male=先生,Female=小姐}."
  },
  AvgDialog_131217_Content_38 = {
    Text = "\"Kesukacitaan\"."
  },
  AvgDialog_131217_Content_39 = {
    Text = "Dalam masa depan singkatmu, \"Kesukacitaan\" adalah sebuah kunci, yang akan membuka rahasia yang kamu hadapi."
  },
  AvgDialog_131217_Content_4 = {Text = "\"N\"!"},
  AvgDialog_131217_Content_40 = {
    Text = "……Apa pun yang terjadi, percayalah padaku, dan percayalah pada dirimu sendiri."
  },
  AvgDialog_131217_Content_41 = {
    Text = "Kembalilah ke Teater Takdir. Kunci dan gemboknya menunggumu di sana, Penjaga Rahasia {Male=先生,Female=小姐}."
  },
  AvgDialog_131217_Content_42 = {
    Text = "Kata-kata Arachne seperti benang-benang yang melintasi dan berjalin-jalin di dalam pikiranmu. Akhirnya, mereka berkumpul menjadi sebuah jaring besar yang rapat."
  },
  AvgDialog_131217_Content_43 = {
    Text = "Kau akhirnya mengerti, sejak pertama kali bertemu, Arachne telah berbicara denganmu melintasi waktu, dengan dirimu yang sekarang."
  },
  AvgDialog_131217_Content_44 = {
    Text = "Kamu terkagum-kagum memandang jaring yang rumit itu, seolah ada sesuatu yang sangat penting, sedang perlahan-lahan terbentuk di dalam benakmu."
  },
  AvgDialog_131217_Content_45 = {
    Text = "Pertunjukan, menggoda, menyenangkan…"
  },
  AvgDialog_131217_Content_46 = {
    Text = "Ah, benar. Jangan pernah mencoba untuk memahami. Nikmati saja, itulah satu-satunya rahasia kesukacitaan."
  },
  AvgDialog_131217_Content_47 = {
    Text = "Kesedihan dan kebahagiaan, baik dan jahat, semua emosi dan moralitas tidak lagi ada. Selain menikmati, tidak ada apa-apa."
  },
  AvgDialog_131217_Content_48 = {
    Text = "Sekarang, beritahu aku... apakah kamu mengerti \"Kesukacitaan\", Penjaga?"
  },
  AvgDialog_131217_Content_49 = {
    Text = "Wajah merah menyeringai milik \"N\" menghilang dari benakmu. Kau melihat sebuah cermin, dan yang terpantul di atasnya adalah wajahmu sendiri yang tertawa."
  },
  AvgDialog_131217_Content_5 = {
    Text = "Shh... Suaramu terlalu keras, Penjaga."
  },
  AvgDialog_131217_Content_50 = {
    Text = "Kesukacitaan?……Kesukacitaan……"
  },
  AvgDialog_131217_Content_51 = {
    Text = "Hohoho... Hahaha. Betul, kesukacitaan, temanku"
  },
  AvgDialog_131217_Content_52 = {
    Text = "Kata yang paling indah di dunia ini, seluruh makna keberadaan mimpi ini…"
  },
  AvgDialog_131217_Content_53 = {
    Text = "Seolah melihat adegan yang akan segera dipentaskan, seluruh tubuh N bergetar dalam kenikmatan. Dia mengangkat tangan kanannya, jari telunjuk yang diselimuti kabut hitam menyentuh pelan dahinya sendiri."
  },
  AvgDialog_131217_Content_54 = {
    Text = "Kau akan segera tiba. Hanya satu langkah lagi, langkah terakhir... Pikirkan dengan baik, lalu masuki jaring itu, Penjaga."
  },
  AvgDialog_131217_Content_55 = {
    Text = "Jalan kesukacitaan, ada di dalamnya."
  },
  AvgDialog_131217_Content_6 = {
    Text = "Bayangan \"N\" tidak menghilang. Dia muncul dengan santai di ruang mentalmu, seolah-olah dia adalah pemilik sah tempat ini yang tak terbantahkan."
  },
  AvgDialog_131217_Content_7 = {
    Text = "\"Kesukacitaan\" yang dikatakan Arachne, pasti merujuk padamu"
  },
  AvgDialog_131217_Content_8 = {
    Text = "\"N\", beri aku beberapa petunjuk..."
  },
  AvgDialog_131217_Content_9 = {
    Text = "Petunjuk? Hahahaha... Apa yang telah aku lakukan sampai membuatmu menghina aku seperti ini?"
  },
  AvgDialog_131218_Content_10 = {
    Text = "Kamu... kalian ini..."
  },
  AvgDialog_131218_Content_11 = {
    Text = "Orang dewasa yang mabuk, gadis muda, pria bangsawan yang mewah, anggota geng di jalan, pelayan yang terlihat lelah, bartender yang cantik……"
  },
  AvgDialog_131218_Content_12 = {
    Text = "Setiap wajah di bar, baik muda maupun tua, tampan maupun biasa, semuanya berbalik ke arahmu secara bersamaan dengan ekspresi yang serupa bagai salinan."
  },
  AvgDialog_131218_Content_13 = {
    Text = "Mereka... tidak seperti individu, lebih seperti..."
  },
  AvgDialog_131218_Content_14 = {
    Text = "Orang-orang yang sesaat lalu masih hidup, kini berdiri di hadapan kalian bagaikan boneka-boneka tak bernyawa."
  },
  AvgDialog_131218_Content_15 = {
    Text = "...Lebih seperti, boneka kayu yang terikat dalam jaring."
  },
  AvgDialog_131218_Content_16 = {
    Text = "Saya sudah mendengar tentang kejelian pengamatan Anda, Tuan William."
  },
  AvgDialog_131218_Content_17 = {
    Text = "Yang ada di hadapan Anda ini, adalah dekorasi di atas panggung, bayangan di dalam cermin."
  },
  AvgDialog_131218_Content_18 = {
    Text = "Mohon maaf, untuk sementara saya tidak bisa meninggalkan jaring saya, terpaksa menggunakan mereka untuk berbicara dengan kalian berdua."
  },
  AvgDialog_131218_Content_19 = {
    Text = "Selamat datang di panggung saya, Tuan William, Penjaga Rahasia {Male=tuan,Female=nyonya}."
  },
  AvgDialog_131218_Content_2 = {
    Text = "Sudah teratasi, benda-benda ini sebenarnya apa…"
  },
  AvgDialog_131218_Content_20 = {
    Text = "Setiap kata diteruskan dengan sempurna, dua puluh suara yang berbeda, ditenun menjadi satu untaian suara yang dingin."
  },
  AvgDialog_131218_Content_21 = {
    Text = "Semua orang di bar, dengan senyuman dan nada bicara yang sama, membungkuk memberi hormat kepada kalian. Lengkungan tubuh dan sudut tangan mereka saat membungkuk, tidak ada perbedaan sedikit pun."
  },
  AvgDialog_131218_Content_22 = {
    Text = "Panggungmu...? Siapa kamu sebenarnya?"
  },
  AvgDialog_131218_Content_23 = {
    Text = "Dia adalah tuan di sini, juga satu orang tahanan."
  },
  AvgDialog_131218_Content_24 = {
    Text = "Saya rasa, pasti banyak pertanyaan yang Anda miliki."
  },
  AvgDialog_131218_Content_25 = {
    Text = "Di sini tidak aman, orang-orang mereka akan segera mengejar. Pelayan saya akan datang untuk menyambut kalian berdua, setelah bertemu dengannya, harap jangan panik."
  },
  AvgDialog_131218_Content_26 = {
    Text = "Setelah pertemuan, semua pertanyaan akan saya jawab satu per satu untuk kalian berdua."
  },
  AvgDialog_131218_Content_27 = {
    Text = "Setelah mengucapkan kalimat itu, kesadaran kerumunan tampaknya ditarik pergi dalam sekejap."
  },
  AvgDialog_131218_Content_28 = {
    Text = "Gelas kristal sang pria berhenti di bibir, kipas lipat sang wanita menutupi separuh wajahnya, bartender dengan anggun mengangkat gelasnya."
  },
  AvgDialog_131218_Content_29 = {
    Text = "Seolah benang yang menarik mereka tiba-tiba terputus, semua orang membeku dalam pose terakhir mereka, membatu bagaikan patung lilin di ruangan ini."
  },
  AvgDialog_131218_Content_3 = {
    Text = "Hati-hati di belakangmu!!…"
  },
  AvgDialog_131218_Content_30 = {
    Text = "Kamu menarik napas dalam-dalam, memandang ragu ke sekeliling pada \"boneka-boneka\" yang membeku dengan senyuman yang sama."
  },
  AvgDialog_131218_Content_31 = {
    Text = "Meskipun mereka memang telah membantuku barusan, aku benar-benar tidak bisa sepenuhnya percaya..."
  },
  AvgDialog_131218_Content_32 = {
    Text = "Kak William, hal yang ingin kami ketahui, orang ini\"Pemilik\"mungkin adalah jawaban terbaik."
  },
  AvgDialog_131218_Content_33 = {
    Text = "Meskipun ada bahaya, saya rasa saya harus pergi sekali, hanya saja…"
  },
  AvgDialog_131218_Content_34 = {
    Text = "Saya mengerti."
  },
  AvgDialog_131218_Content_35 = {
    Text = "Melihat tatapanmu, William mengerti dan mengangguk."
  },
  AvgDialog_131218_Content_36 = {
    Text = "Aku akan menyelidiki jejak Bayangan di luar, mereka sedang mencarimu, dan jejakku di luar akan lebih aman daripada milikmu."
  },
  AvgDialog_131218_Content_37 = {
    Text = "Orang ini\"Tuan\"berasal tidak jelas, jika menghadapi bahaya……"
  },
  AvgDialog_131218_Content_38 = {
    Text = "William dengan lembut mengetuk lencana di dadanya. Di dunia ini, kalian adalah satu-satunya orang yang bisa saling menghubungi melalui lencana satu sama lain."
  },
  AvgDialog_131218_Content_39 = {
    Text = "Mengerti... kamu juga, Kak William."
  },
  AvgDialog_131218_Content_4 = {
    Text = "Sebuah rasa krisis yang kuat membuatmu segera terbangun. Kamu tiba-tiba berbalik dan melihat bilah tajam yang terbuat dari bayangan hanya beberapa inci di depanmu."
  },
  AvgDialog_131218_Content_40 = {
    Text = "\"Tuan\" memahami kehati-hatian Anda. Tuan William, panggung ini sekarang memiliki banyak bahaya, harap berhati-hati. Dalam batas kemampuan kami, kami akan memberikan bantuan yang diperlukan kepada Anda."
  },
  AvgDialog_131218_Content_41 = {
    Text = "Laba-laba berwarna ungu muda berkumpul dari berbagai penjuru bar, seorang pelayan wanita dengan ciri-ciri laba-laba muncul diam-diam di belakang kalian. Setelah membungkuk sopan kepada kalian, dia berjalan menuju pintu keluar."
  },
  AvgDialog_131218_Content_42 = {
    Text = "Penjaga Rahasia {Male=先生,Female=小姐}, silakan ikuti saya. \"Tuan\" sudah menunggu Anda sejak lama."
  },
  AvgDialog_131218_Content_5 = {Text = "Crassh—"},
  AvgDialog_131218_Content_6 = {
    Text = "Kamu perlahan menggeser lengan yang menutupi matamu. Bayangan itu dipotong oleh orang di belakangmu, cairan hitam menyemprot, dan membasahi seluruh tubuhmu."
  },
  AvgDialog_131218_Content_7 = {
    Text = "Maaf, kalian telah terkejut."
  },
  AvgDialog_131218_Content_8 = {
    Text = "Mereka terus mencari jejakmu. Di sini, kekuatanku masih bisa memberikan sedikit bantuan untukmu."
  },
  AvgDialog_131218_Content_9 = {
    Text = "Tanpa izin Anda, saya secara pribadi mengarahkan kalian ke sini, semoga kalian berdua tidak keberatan."
  },
  AvgDialog_131219_Content_1 = {
    Text = "Kekuatan yang tersebar dari pecahan dimensi... ini adalah...!"
  },
  AvgDialog_131219_Content_2 = {
    Text = "Otoritas Tritunggal tidak pernah mengkhianati, dan pertunjukan Anda bersama N pun belum berakhir."
  },
  AvgDialog_131219_Content_3 = {
    Text = "Pinjam kekuatan mereka, dan bawalah akhir yang telah ditakdirkan bagi mereka... Penjaga Rahasia{Male=先生,Female=小姐}."
  },
  AvgDialog_131220_Content_1 = {
    Text = "Angsa Terbang Tinggi"
  },
  AvgDialog_131220_Content_10 = {
    Text = "Kamu ingat pintu besar yang sedikit berkarat itu, setiap kali digerakkan akan mengeluarkan suara berat, seperti napas lembut kakek."
  },
  AvgDialog_131220_Content_11 = {
    Text = "Universitas Miska……"
  },
  AvgDialog_131220_Content_12 = {
    Text = "Di lingkungan yang akrab ini, kamu menyentuh nama yang sama sekali berbeda yang terukir di plakat alun-alun."
  },
  AvgDialog_131220_Content_13 = {
    Text = "Setiap aktor memiliki panggung yang paling mereka cintai. Bahkan sebuah kampus yang direplikasi dari ingatan pun tak tergantikan bagimu."
  },
  AvgDialog_131220_Content_14 = {
    Text = "Mengapa harus menciptakan tempat yang persis sama dengan Mythag ini……"
  },
  AvgDialog_131220_Content_15 = {
    Text = "Aku tidak menciptakannya, hanya saja seharusnya ia ada di sini. Sama seperti kota ini, dunia ini, semuanya adalah bagian dari jaring nasib."
  },
  AvgDialog_131220_Content_16 = {
    Text = "Tidak perlu melihat sejauh itu, %player%. Begitu kamu naik ke sebuah panggung, akan ada makna untuk berada di sini."
  },
  AvgDialog_131220_Content_17 = {
    Text = "Ngomong-ngomong, sudah lama bergaul dengan Liz, saya belum pernah melihat pertunjukan resminya secara langsung..."
  },
  AvgDialog_131220_Content_18 = {
    Text = "Kamu memandang sekeliling alun-alun yang familiar ini, kedua tanganmu melintasi rumput di bawah tubuhmu dengan lembut."
  },
  AvgDialog_131220_Content_19 = {
    Text = "Momen terindah dalam hidup adalah saat kamu tidak menyadari bahwa kamu sedang tersenyum."
  },
  AvgDialog_131220_Content_2 = {
    Text = "Sungguh langka, harga tiket untuk kelompok tari ini di teater, yang termurah pun harus menghabiskan dua bulan gajiku."
  },
  AvgDialog_131220_Content_20 = {
    Text = "Ah... maaf..."
  },
  AvgDialog_131220_Content_21 = {
    Text = "Ingat tentang Mythag?"
  },
  AvgDialog_131220_Content_22 = {
    Text = "Di alun-alun ini, kami telah mengadakan banyak pertunjukan di dalam kampus. Saat itu juga seperti sekarang, pelajar Mythag memenuhi alun-alun."
  },
  AvgDialog_131220_Content_23 = {
    Text = "Ada banyak Pembangun yang memiliki pencapaian yang sangat mendalam dalam seni. Banyak orang awalnya tidak terlalu mau tampil dalam acara seperti ini, saya dan para guru di akademi telah memikirkan berbagai cara…"
  },
  AvgDialog_131220_Content_24 = {
    Text = "Kemudian, banyak dari mereka juga secara sukarela mulai ingin melakukan pertunjukan untuk rekan-rekan di sini."
  },
  AvgDialog_131220_Content_25 = {
    Text = "Tari Liz, lagu Tinct, simfoni Hameln, puisi Horla, patung Sanga…"
  },
  AvgDialog_131220_Content_26 = {
    Text = "Aku tidak tahu apakah kehidupan Mythag sudah kembali seperti dulu setelah aku pergi..."
  },
  AvgDialog_131220_Content_27 = {
    Text = "Tirai bergerak! Tirai bergerak! Nona Liz segera akan tampil!"
  },
  AvgDialog_131220_Content_28 = {
    Text = "Kamu menggelengkan kepala, mengusir perasaan sedih itu dari pikiranmu."
  },
  AvgDialog_131220_Content_29 = {
    Text = "Bagaimanapun juga, bisa melihat Tari Liz lagi di dunia yang jauh ini adalah hal yang patut disyukuri."
  },
  AvgDialog_131220_Content_3 = {
    Text = "Kabar yang beredar adalah bahwa ini adalah pertunjukan amal yang disponsori secara pribadi oleh Nyonya Sorel! Betapa baiknya jika setiap tuan dan nyonya di kota ini memiliki hati yang sama"
  },
  AvgDialog_131220_Content_30 = {
    Text = "Setelah urusan ini selesai sepenuhnya, jika ada waktu, aku ingin berbicara dengan mereka dengan baik."
  },
  AvgDialog_131220_Content_31 = {
    Text = "Para hadirin, selamat datang di lokasi pertunjukan kami"
  },
  AvgDialog_131220_Content_32 = {
    Text = "Tarian Angsa, betapa suci dan tak terjangkau namanya! Angsa putih yang paling anggun di Londinium ini, hari ini, akan pertama kali bersarang di depan umum Londinium"
  },
  AvgDialog_131220_Content_33 = {
    Text = "Terima kasih atas kesabaran kalian. Para pemain kami sudah siap. Pertunjukan yang menarik, akan segera disajikan untuk kalian"
  },
  AvgDialog_131220_Content_34 = {
    Text = "Dengan jari telunjuk yang nyaring dari pengumuman, semua lampu di sekitar mati, beberapa sorotan diarahkan ke tengah layar."
  },
  AvgDialog_131220_Content_35 = {
    Text = "Selanjutnya, silakan nikmati tarian yang dibawakan oleh Nona Liz, Angsa — Terbang!"
  },
  AvgDialog_131220_Content_36 = {
    Text = "Di tengah tepuk tangan dan sorakan hangat dari kerumunan, tirai itu perlahan terbuka —"
  },
  AvgDialog_131220_Content_37 = {
    Text = "<Big:<Red:!!!!>>"
  },
  AvgDialog_131220_Content_38 = {
    Text = "Kamu sudah melihat Liz berkali-kali."
  },
  AvgDialog_131220_Content_39 = {
    Text = "Di atas panggung Ruang Upacara Mythag, dia berputar hanya untukmu."
  },
  AvgDialog_131220_Content_4 = {
    Text = "Meskipun tidak mengerti, tetapi kesempatan seperti ini tidak boleh dilewatkan."
  },
  AvgDialog_131220_Content_40 = {
    Text = "Di bawah langit berbintang Londinium, ujung jari kakinya yang berjinjit menyentuh cahaya kunang-kunang yang terbang di malam."
  },
  AvgDialog_131220_Content_41 = {
    Text = "Di tengah angin sepoi-sepoi di Charing Cross, rok-nya terangkat tinggi, seperti api yang mendidih."
  },
  AvgDialog_131220_Content_42 = {
    Text = "Dan hari ini, di panggung yang jauh di negeri asing, dia muncul di hadapanmu dengan pose yang belum pernah kamu lihat sebelumnya."
  },
  AvgDialog_131220_Content_43 = {
    Text = "Bintang utama dari grup tari angsa, kembang api paling cemerlang di seluruh kota. Duri hitam menembus tenggorokannya, lengan, dada, perut, dan telapak kaki yang terangkat, menembus tubuhnya yang menguasai tarian."
  },
  AvgDialog_131220_Content_44 = {
    Text = "Darah segar memercik, menggambar sepasang sayap merah darah di papan belakangnya, meninggalkan beberapa goresan menyakitkan di wajahnya yang tersenyum tenang."
  },
  AvgDialog_131220_Content_45 = {
    Text = "Kerumunan sunyi tanpa suara, angin bertiup dari alun-alun yang luas, rok tari yang bercampur hitam dan hijau melayang di udara, seperti api yang terbakar selamanya."
  },
  AvgDialog_131220_Content_46 = {
    Text = "—— Saat itu kamu sepenuhnya mengerti, jika kematian tak terhindarkan, maka inilah cara kematian yang paling diinginkan oleh Liz."
  },
  AvgDialog_131220_Content_47 = {
    Text = "Dia menyelesaikan pertunjukan perpisahan dengan darah dan kehidupannya. Gerakan tariannya terhenti dalam lompatan yang paling indah, seperti seekor angsa hitam yang terbang tinggi."
  },
  AvgDialog_131220_Content_48 = {
    Text = "Gerakan tari Nona Liz, betapa anggunnya, betapa indahnya"
  },
  AvgDialog_131220_Content_49 = {
    Text = "Nikmati dengan tenang, teman-teman penonton tersayang! Melihat momen ini dengan mata kepala sendiri adalah kehormatan yang hanya kalian miliki dalam hidup ini."
  },
  AvgDialog_131220_Content_5 = {
    Text = "Tiga puluh tahun... Aku sudah tiga puluh tahun tidak bisa kembali ke teater untuk menonton pertunjukan..."
  },
  AvgDialog_131220_Content_50 = {
    Text = "Kau melihat wajah pembawa acara yang telah sobek menjadi dua. Wajah pria paruh baya yang tidak bernyawa itu mencair seperti lendir, mengungkapkan sepasang mata Nefraea yang dipenuhi dengan keseruan."
  },
  AvgDialog_131220_Content_51 = {
    Text = "Di tengah teriakan dan pelarian yang kacau di kerumunan, suara tawanya yang tajam menusuk gendang telingamu seperti jarum beracun."
  },
  AvgDialog_131220_Content_52 = {
    Text = "<Big:Liz!!>"
  },
  AvgDialog_131220_Content_53 = {
    Text = "Kamu menerobos kerumunan yang ketakutan, berlari ke depan panggung."
  },
  AvgDialog_131220_Content_54 = {
    Text = "Ah, orang ini yang cerdas, bagaimana Anda tahu bahwa pertunjukan tari ini masih memiliki babak kedua?"
  },
  AvgDialog_131220_Content_55 = {
    Text = "Di sekitar panggung, beberapa penonton yang tidak melarikan diri cepat-cepat mendekatimu. Tubuh mereka meledak saat berlari, mengeluarkan pelayan laba-laba hitam yang tak henti-hentinya membunuh."
  },
  AvgDialog_131220_Content_56 = {
    Text = "Di depanmu, tubuh Liz terlepas dari spike. Sebuah karya seni yang dibuat oleh penganut agama asing, dengan kekosongan yang kejam dan darah yang cerah."
  },
  AvgDialog_131220_Content_57 = {
    Text = "Jejak kaki telanjang berwarna merah darah membentang dari tengah panggung. Liz perlahan berjalan ke arahmu, riasan tragis nan memukau yang dilukis dengan darah membuatmu merasa sesak napas."
  },
  AvgDialog_131220_Content_58 = {
    Text = "Dia menengadah menatapmu. Mata yang kosong dan berdarah itu mengingatkanmu pada semua karya seni yang layak untuk dikenang."
  },
  AvgDialog_131220_Content_59 = {
    Text = "Menarilah bersama teman lamamu…… Penjaga Rahasia {Male=先生,Female=小姐}!"
  },
  AvgDialog_131220_Content_6 = {
    Text = "Balet, tari yang paling murni di dunia ini, hanya orang yang benar-benar pernah menari yang dapat memahami betapa indahnya keanggunan yang kejam itu"
  },
  AvgDialog_131220_Content_7 = {
    Text = "Saya masih bisa menyaksikan penampilan Nona Liz secara langsung, ini adalah sesuatu yang bahkan tidak pernah saya impikan…"
  },
  AvgDialog_131220_Content_8 = {
    Text = "Suara latar yang seharusnya berisik itu bercampur menjadi suara putih yang jauh di telingamu."
  },
  AvgDialog_131220_Content_9 = {
    Text = "Kamu ingat padang rumput ini, danau itu. Kamu ingat gedung-gedung pengajaran yang tinggi-rendah, ingat patung yang memiliki pandangan teguh yang menatap ke kejauhan."
  },
  AvgDialog_131221_Content_1 = {
    Text = "Babak Kedua"
  },
  AvgDialog_131221_Content_10 = {
    Text = "Aku adalah tahanan nasib, ini hanyalah kewajiban yang harus aku lakukan."
  },
  AvgDialog_131221_Content_11 = {
    Text = "Seseorang yang dapat mengendalikan nasib tak terhitung banyaknya dunia, mungkin lebih tepat jika menyebut dirinya sebagai hakim takdir atau kepala penjara?"
  },
  AvgDialog_131221_Content_12 = {
    Text = "Di penjara nasib ini, penjaga penjara dan tahanan tidak ada bedanya."
  },
  AvgDialog_131221_Content_13 = {
    Text = "Tuan William, apakah Anda merasa nyaman sepanjang perjalanan ini?"
  },
  AvgDialog_131221_Content_14 = {
    Text = "Berkat pelayan Anda, jika hanya mengandalkan diri saya sendiri, untuk terbebas dari pelayan-pelayan yang ada di bayang-bayang itu, mungkin saya harus membayar biaya yang lebih besar."
  },
  AvgDialog_131221_Content_15 = {
    Text = "Nefraea... Apakah kamu sudah bertemu orangnya lagi?"
  },
  AvgDialog_131221_Content_16 = {
    Text = "William mengangguk dengan ekspresi yang berat."
  },
  AvgDialog_131221_Content_17 = {
    Text = "Saat berpencar, aku bertemu beberapa orang yang tampak mencurigakan. Aku mengikuti mereka beberapa saat dan mendengar percakapan mereka."
  },
  AvgDialog_131221_Content_18 = {
    Text = "Mereka sedang mencari sesuatu yang disebut\"Misteri Pasangan\"."
  },
  AvgDialog_131221_Content_19 = {
    Text = "Saya ingin... apa yang kalian bicarakan tadi, tentang polusi nasib panggung, mungkin hanyalah sebuah cara pendahuluan."
  },
  AvgDialog_131221_Content_2 = {
    Text = "Sebuah pertunjukan yang luar biasa..."
  },
  AvgDialog_131221_Content_20 = {
    Text = "Itu adalah \"Kekasih Rahasia\" yang sebenarnya adalah tujuan mereka."
  },
  AvgDialog_131221_Content_21 = {
    Text = "Adik perempuan saya menyembunyikan benang takdir miliknya dan para pengikutnya, saya tidak bisa dengan mudah melihat mereka. Anda memberikan informasi yang sangat berharga, Tuan Wilhelm."
  },
  AvgDialog_131221_Content_22 = {
    Text = "Aksi selanjutnya, aku akan bersama kalian..."
  },
  AvgDialog_131221_Content_23 = {
    Text = "Tidak boleh!"
  },
  AvgDialog_131221_Content_24 = {
    Text = "Tidak boleh! Kau masih terluka, aku tidak ingin kejadian Lemvahi terulang lagi."
  },
  AvgDialog_131221_Content_25 = {
    Text = "Sang Penjaga Rahasia benar. Pelayanku akan membantumu mengobati racun di dalam tubuhmu. Sebelum sembuh, beristirahatlah dengan tenang di teater."
  },
  AvgDialog_131221_Content_26 = {
    Text = "Segera, kita akan menyambut hari ketika kami membutuhkan bantuanmu."
  },
  AvgDialog_131221_Content_27 = {
    Text = "Kata-kata Arachne bagaikan sebuah vonis yang lembut, dengan mudah menembus tubuh dan jiwa, jatuh lembut ke dalam nasib William."
  },
  AvgDialog_131221_Content_28 = {
    Text = "William melihat darah yang merembes dari perutnya, lalu mengangguk pelan."
  },
  AvgDialog_131221_Content_29 = {
    Text = "Bertindak bersama kalian sekarang memang hanya akan menjadi beban. Tenang saja, aku akan membuat hari itu datang secepat mungkin."
  },
  AvgDialog_131221_Content_3 = {
    Text = "<Shake:Batuk batuk……>"
  },
  AvgDialog_131221_Content_30 = {
    Text = "Arachne tersenyum dan mengulurkan tangannya. Seekor, dua ekor... tak terhitung laba-laba keluar dari lengannya, menjalar di sepanjang benang dan jatuh ke tanah."
  },
  AvgDialog_131221_Content_31 = {
    Text = "Laba-laba berjatuhan ke tanah bagai tetesan air, lalu berkumpul. Laba-laba yang tak terhitung jumlahnya saling bertumpuk membentuk siluet manusia, warna dan cahaya melekat di atasnya."
  },
  AvgDialog_131221_Content_32 = {
    Text = "Dengan cepat, satu Arachne baru yang persis sama berdiri di depanmu."
  },
  AvgDialog_131221_Content_33 = {
    Text = "Silakan ikuti saya, Penjaga Rahasia {Male=先生,Female=小姐}. Saya rasa, kita akan segera bertemu dengan adik perempuan saya."
  },
  AvgDialog_131221_Content_35 = {
    Text = "Di kota ini ada banyak toko yang sangat aku cintai, namun sama seperti kamu, tempat ini juga merupakan salah satu tempat yang aku cintai."
  },
  AvgDialog_131221_Content_36 = {
    Text = "Topeng Tengah Malam, kamu duduk di tempat yang sama seperti saat terakhir kali datang, dengan dahi berkerut memandang Arachne yang sedang mengamati sekeliling."
  },
  AvgDialog_131221_Content_37 = {
    Text = "Jadi, kamu sebenarnya apa sekarang... boneka? Kloning? Mesin misterius yang terbuat dari sekumpulan laba-laba yang membantumu melarikan diri?"
  },
  AvgDialog_131221_Content_38 = {
    Text = "Pada dasarnya, aku di sini dan aku di dalam teater adalah nasib yang memiliki dua pengalaman berbeda pada saat yang sama."
  },
  AvgDialog_131221_Content_39 = {
    Text = "Sebagian besar kekuatanku perlu tersisa di teater, untuk terus menyusun takdir yang besar. Selain itu, tidak ada perbedaan antara kita. Tidak perlu merusak suasana saat ini karena keraguan, penjaga."
  },
  AvgDialog_131221_Content_4 = {
    Text = "Suara menarik luka, William menutupi perutnya yang terbalut perban, tidak bisa menahan batuk."
  },
  AvgDialog_131221_Content_40 = {
    Text = "Arachne tersenyum tenang, es batu bergetar lembut di dalam gelas anggur yang goyang."
  },
  AvgDialog_131221_Content_41 = {
    Text = "Tahukah kamu, taverna ini mengadakan bal masqued setiap bulan, dan setiap tamu yang masuk harus mengenakan topeng yang paling menarik milik mereka."
  },
  AvgDialog_131221_Content_42 = {
    Text = "Sosialisasi di kalangan masyarakat kelas atas sering kali membuat tempat ini menjadi membosankan, hanya pada hari itu, tempat ini akan menjadi tempat yang paling layak untuk dikunjungi di kota ini."
  },
  AvgDialog_131221_Content_43 = {
    Text = "Mungkin pada pesta topeng berikutnya, saya juga harus melepaskan segalanya dan merasakan dengan serius sekali."
  },
  AvgDialog_131221_Content_44 = {
    Text = "Aku pikir seseorang yang bisa melihat perkembangan nasib tidak akan lagi tertarik pada segala sesuatu di masa depan."
  },
  AvgDialog_131221_Content_45 = {
    Text = "Memang benar, %player%. Namun, sejak lama aku sudah menemukan cara untuk menghindari kebosanan."
  },
  AvgDialog_131221_Content_46 = {
    Text = "Terkadang saya datang dari belakang tirai ke depan panggung, melangkah ke panggung yang saya ciptakan, dan menjadikan diri saya sebagai salah satu karakternya."
  },
  AvgDialog_131221_Content_47 = {
    Text = "Menutupi pandanganmu terhadap nasib, menempatkan dirimu sepenuhnya di atas panggung, untuk merasakan aliran waktu dengan seksama, perubahan nasib..."
  },
  AvgDialog_131221_Content_48 = {
    Text = "Ini adalah istirahat yang langka. Kesempatan seperti ini tidak banyak, setiap kali, aku menganggapnya sebagai perayaan yang sangat berharga."
  },
  AvgDialog_131221_Content_49 = {
    Text = "Arachne sambil berbicara melihat dengan penuh minat para tamu yang megah dan para pelayan yang lembut, cahaya redup di kedai mengalir di mata Arachne."
  },
  AvgDialog_131221_Content_5 = {
    Text = "Kak William?! Apakah kamu terluka"
  },
  AvgDialog_131221_Content_50 = {
    Text = "Meskipun begitu... bukankah kita pergi untuk mencari sesuatu yang disebut \"Misteri Rahasia\"? Mengapa kita berada di sini?"
  },
  AvgDialog_131221_Content_51 = {
    Text = "Salah satu orang ada di sini. Anda segera... ah tidak, Anda sudah bertemu dengannya."
  },
  AvgDialog_131221_Content_52 = {
    Text = "Halo, pelanggan yang terhormat."
  },
  AvgDialog_131221_Content_53 = {
    Text = "Suara yang direndam dalam madu. Jari-jari yang diukir dari porselen. Di leher yang telanjang, aroma melati dan bunga akasia yang cerah. Dan sepasang mata yang berkilau seperti lampu neón, mampu menembus segalanya."
  },
  AvgDialog_131221_Content_54 = {
    Text = "Ah, aku ingat kamu, {Male=先生,Female=小姐} yang anggun ini."
  },
  AvgDialog_131221_Content_55 = {
    Text = "Makhluk kegelapan, cahaya perak yang mencolok… Betapa menawannya cerita pahlawan ini"
  },
  AvgDialog_131221_Content_56 = {
    Text = "Sejujurnya, selama kamu tidak ada, Bar Topeng Tengah Malam telah menghasilkan banyak uang dari ceritamu. Kami seharusnya membayar hak cipta kepadamu—setidaknya, biarkan kami mentraktirmu satu gelas anggur."
  },
  AvgDialog_131221_Content_57 = {
    Text = "Ternyata kamu... saya tidak akan minum dulu, bisakah kamu membawakan segelas untuk teman saya ini?"
  },
  AvgDialog_131221_Content_58 = {
    Text = "Namanya sudah aku pikirkan, akan disebut Sutradara Diri Sendiri."
  },
  AvgDialog_131221_Content_59 = {
    Text = "Nama yang bagus. Untuk apakah itu cocok untuk teman Anda ini, saya masih harus melihat dengan seksama..."
  },
  AvgDialog_131221_Content_6 = {
    Text = "Di bawah tarikan Arachne, kamu melintasi dinding yang tidak mencolok di samping kafe Hewaz."
  },
  AvgDialog_131221_Content_60 = {
    Text = "Ini yang bernama\"Romantis\"Misteri Pasangan datang ke sisi bar, dengan serius Tatapan mata Arachne."
  },
  AvgDialog_131221_Content_61 = {
    Text = "Pencipta yang rendah hati tenggelam dalam panggung yang ia ciptakan. Arachne tersenyum dan bertatapan dengannya."
  },
  AvgDialog_131221_Content_62 = {
    Text = "Ah, betapa dalamnya sepasang mata itu, Nona."
  },
  AvgDialog_131221_Content_63 = {
    Text = "Sebuah lautan yang sedalam dan seluas ini, dasar laut yang tak terlihat oleh siapa pun, menyimpan rahasia yang tidak diketahui oleh siapa pun."
  },
  AvgDialog_131221_Content_64 = {
    Text = "Gelombang yang mengamuk itu, semuanya diterima oleh lautan ini, tidak peduli seberapa besar guncangannya, ia tetap mempertahankan ketenangan abadi."
  },
  AvgDialog_131221_Content_65 = {
    Text = "Waktu berlalu, lautan bintang berputar. Gunung berubah menjadi ladang, laut berubah menjadi padang rumput…"
  },
  AvgDialog_131221_Content_66 = {
    Text = "Namun, di balik perubahan ini, lautan ini telah meninggalkan apa..."
  },
  AvgDialog_131221_Content_67 = {
    Text = "Bartender duduk di hadapan Arachne, mengangkat dagunya. Kuku yang panjang secara alami menekan di arteri leher Arachne."
  },
  AvgDialog_131221_Content_68 = {
    Text = "Kamu ini..."
  },
  AvgDialog_131221_Content_69 = {
    Text = "Dewa nasib, Arachne yang agung. Cara kamu memainkan nasib, sungguh elegan. Aku sangat iri, iri pada mereka yang kamu pilih, yang kamu tinggalkan."
  },
  AvgDialog_131221_Content_7 = {
    Text = "Saat kembali ke panggung teater, pandanganmu langsung tertuju pada William yang duduk sendirian di kursi penonton."
  },
  AvgDialog_131221_Content_70 = {
    Text = "Sayang sekali... kita terlahir hanya bisa menjadi bagian yang terbuang."
  },
  AvgDialog_131221_Content_71 = {
    Text = "……Sepertinya, hari ini tidak ada kesempatan untuk mencicipi minuman ini lagi."
  },
  AvgDialog_131221_Content_72 = {
    Text = "Arachne tidak berusaha untuk melepaskan diri dari tangan yang berbahaya itu. Dia menghela napas pelan, seolah-olah menghela napas untuk kenangan yang jauh, dan juga seolah-olah menghela napas untuk minuman khusus yang tidak bisa diminumnya."
  },
  AvgDialog_131221_Content_73 = {
    Text = "Kamu bisa mencemari benang takdir dari misteri pasangan ini, membuatku tidak dapat melihat dengan jelas, tetapi itu tidak ada artinya. Kamu tidak memiliki kemampuan untuk mengendalikan nasib, Nefraea."
  },
  AvgDialog_131221_Content_74 = {
    Text = "Bagaikan krim hitam yang meleleh, kulit luar sang bartender berubah menjadi genangan lumpur dan meluncur jatuh dari tubuhnya."
  },
  AvgDialog_131221_Content_75 = {
    Text = "Di bawah lumpur itu, sebuah wajah yang sudah dikenal muncul di hadapanmu."
  },
  AvgDialog_131221_Content_76 = {
    Text = "Apakah itu kamu?"
  },
  AvgDialog_131221_Content_77 = {
    Text = "Kakak baikku. Abu sisa dari dimensi itu, kamu sudah hampir tidak tersisa lagi."
  },
  AvgDialog_131221_Content_78 = {
    Text = "Aku sangat ingin berbicara denganmu dengan baik lagi, tetapi sekarang, biarkan anak-anak labah-labahku menyambutmu dengan baik."
  },
  AvgDialog_131221_Content_79 = {
    Text = "Hati-hati di belakang"
  },
  AvgDialog_131221_Content_8 = {
    Text = "Luka kecil."
  },
  AvgDialog_131221_Content_9 = {
    Text = "Nasib yang terjadi di panggung ini, saya telah melihatnya. Saya rasa, ada baiknya seseorang berterima kasih atas pengorbanan Anda, Nyonya Arachne."
  },
  AvgDialog_131222_Content_1 = {
    Text = "Undangan dari Kediaman"
  },
  AvgDialog_131222_Content_10 = {
    Text = "Surat undangan? Seumur hidupku sampai sekarang, aku belum pernah menunjukkan surat undangan."
  },
  AvgDialog_131222_Content_100 = {
    Text = "Sorel sedikit menyipitkan mata, sepasang mata yang anggun itu menyala dengan kemarahan yang jarang terlihat."
  },
  AvgDialog_131222_Content_101 = {
    Text = "Saya tidak tahu apa yang kamu lakukan pada Karen, tapi itu tidak penting. Bagaimanapun, harga yang akan kamu bayar sudah ditentukan."
  },
  AvgDialog_131222_Content_102 = {
    Text = "Ah, sebuah pertemuan bisnis yang gagal... Sangat disayangkan, Nyonya Sorel. Sepertinya, hanya mayat Anda yang bisa memberi tahu saya."
  },
  AvgDialog_131222_Content_103 = {
    Text = "Sorel mengernyitkan alisnya, merasakan gelombang kekuatan mental yang kuat dari lawannya. Bayangan hitam pekat dengan cepat mendekat, memblokir setiap jalur pelariannya."
  },
  AvgDialog_131222_Content_105 = {
    Text = "Ketika bilah tajam di dalam bayangan tiba-tiba menusuk Sorel, cahaya perak yang kuat melesat masuk ke dalam ruangan seperti meteor."
  },
  AvgDialog_131222_Content_106 = {
    Text = "Sorel, mundur"
  },
  AvgDialog_131222_Content_11 = {Text = "Minggir."},
  AvgDialog_131222_Content_12 = {
    Text = "Maaf, Tuan. Jamuan hari ini hanya bisa dihadiri dengan undangan."
  },
  AvgDialog_131222_Content_13 = {
    Text = "Orang yang tidak memiliki penglihatan, apakah kamu tahu siapa aku?"
  },
  AvgDialog_131222_Content_14 = {
    Text = "Itu bukan tanggung jawab saya, Tuan."
  },
  AvgDialog_131222_Content_15 = {
    Text = "Mendengar aksen Anda, saya rasa Anda adalah penduduk setempat, saya pikir Anda seharusnya bisa memahami apa yang saya katakan."
  },
  AvgDialog_131222_Content_16 = {
    Text = "Kau!! Baik, baik, saya akan membuatmu dan pemilik perkebunan ini membayar harganya"
  },
  AvgDialog_131222_Content_17 = {
    Text = "Arachne melihat punggung bangsawan yang penuh kemarahan, lalu menggelengkan kepala."
  },
  AvgDialog_131222_Content_18 = {
    Text = "Sepertinya, untuk masuk ke manor ini tidak semudah yang dibayangkan."
  },
  AvgDialog_131222_Content_19 = {
    Text = "Jika bisa menemukan pelayan yang menjual air mandi itu, mungkin bisa membeli dua undangan…"
  },
  AvgDialog_131222_Content_2 = {
    Text = "Kediaman Duke Cadlin, tempat sosial paling terkenal di Londinium yang tua."
  },
  AvgDialog_131222_Content_20 = {
    Text = "Garam mandi laut langka yang berasal dari Pulau Sira, lavender, jeruk, cengkeh, dan kelopak mawar yang diangkut dari bagian selatan Konstan…"
  },
  AvgDialog_131222_Content_21 = {
    Text = "Air mandi lebih berharga dan lebih langka dibandingkan undangan."
  },
  AvgDialog_131222_Content_22 = {Text = "???"},
  AvgDialog_131222_Content_23 = {
    Text = "Aku sebenarnya berniat untuk berbicara sendiri sedikit... bagaimana kau bisa tahu tentang apa yang aku alami dalam mimpiku?"
  },
  AvgDialog_131222_Content_24 = {
    Text = "Meskipun saya tidak bisa melihat nasib Anda dengan jelas, saya terus memperhatikan nasib orang-orang di sekitar Anda."
  },
  AvgDialog_131222_Content_25 = {
    Text = "Karena nasib orang-orang ini dapat kamu kendalikan, meskipun mengubahnya sangat rumit, membuat dua undangan kecil seharusnya bisa dilakukan, kan?"
  },
  AvgDialog_131222_Content_26 = {
    Text = "Reaksi berantai yang disebabkan oleh perubahan takdir, Anda sudah menyaksikannya. Takdir bukanlah mainan yang bisa saya mainkan sesuka hati, melainkan sebuah rumah kaca yang perlu saya rawat dengan hati-hati."
  },
  AvgDialog_131222_Content_27 = {
    Text = "Saya perlu berhati-hati dalam membuat setiap pilihan untuk itu, menghabiskan banyak tenaga dan Abu sisa Dimensi. Segala ketidakhati-hatian dan kesalahan akan berujung pada kolaps dan Kehancuran."
  },
  AvgDialog_131222_Content_28 = {
    Text = "Apalagi… seperti yang telah saya katakan sebelumnya, seringkali, menjadi seorang penonton jauh lebih menarik daripada menjadi seorang penulis naskah."
  },
  AvgDialog_131222_Content_29 = {
    Text = "Aku sangat menantikan penampilanmu, {Male=先生,Female=小姐}."
  },
  AvgDialog_131222_Content_3 = {
    Text = "Setengah kehidupan sang Duke, perdana menteri dan pejabat tinggi kabinet menuliskan surat-surat keputusan yang menentukan nasib imperium di meja teh di padang rumput."
  },
  AvgDialog_131222_Content_30 = {
    Text = "Tapi aku tidak tahu apa-apa tentang sini..."
  },
  AvgDialog_131222_Content_31 = {
    Text = "Pertunjukan, memperdaya, menyenangkan... di dalam dirimu, terdapat kekuatan seperti itu. Panggung nasib tidak akan memberikan kesempatan yang sama untuk semua orang. Ketika kamu perlu naik ke panggung, kekuatan ini akan membantumu."
  },
  AvgDialog_131222_Content_32 = {
    Text = "Kamu tidak bisa menghindari panggung yang ditakdirkan untuk datang. Berpikirlah, lalu tampilkanlah, Penjaga Rahasia {Male=先生,Female=小姐}."
  },
  AvgDialog_131222_Content_33 = {
    Text = "Senyum sopan Arachne menyimpan keseriusan yang tidak sulit untuk diperhatikan. Dia seolah-olah sedang menceritakan sesuatu padamu, tatapannya seakan menembus dirimu dan berbicara dengan masa depan yang jauh."
  },
  AvgDialog_131222_Content_34 = {
    Text = "Itu adalah perintah yang tidak bisa ditolak oleh nasib. Kamu menundukkan kepala, merenungkan kata-kata Arachne."
  },
  AvgDialog_131222_Content_35 = {
    Text = "Pertunjukan, menipu, menyenangkan... maksudmu, kekuasaan N?"
  },
  AvgDialog_131222_Content_36 = {
    Text = "Tapi setelah pertempuran terakhir dengan Touva Wave, aku kehilangan tautan dengan kekuatan Triad..."
  },
  AvgDialog_131222_Content_37 = {
    Text = "Kekuatan mereka masih terlelap, tetapi otoritas bukan hanya sekadar kekuatan."
  },
  AvgDialog_131222_Content_38 = {
    Text = "Kekuasaan, bukan hanya kekuatan…"
  },
  AvgDialog_131222_Content_39 = {
    Text = "Saat kamu mencoba memikirkan kalimat ini, seberkas cahaya muncul di Dunia Rohmu."
  },
  AvgDialog_131222_Content_4 = {
    Text = "Setengah hidup Duke, punggungnya yang membungkuk saat dijualnya perkebunan mengantarnya menuju tempat eksekusi."
  },
  AvgDialog_131222_Content_40 = {
    Text = "Kamu mengambil dua helai daun maple yang jatuh dari tanah, membelai pola mereka yang seperti surat."
  },
  AvgDialog_131222_Content_41 = {
    Text = "Aku ingat kamu pernah bilang, semua orang di dunia ini memiliki Perak di dalam tubuh mereka. Itu berarti, dunia Roh semua orang dapat dipengaruhi oleh Kunci perak… benar kan?"
  },
  AvgDialog_131222_Content_42 = {
    Text = "Arachne tersenyum memandangmu, berdiri di sampingmu, menuju pintu besar kebun."
  },
  AvgDialog_131222_Content_43 = {
    Text = "Halo, silakan tunjukkan……"
  },
  AvgDialog_131222_Content_44 = {
    Text = "Benar-benar sebuah perkebunan yang indah. Kami merasa sangat terhormat menerima undangan dari Nyonya Sorel."
  },
  AvgDialog_131222_Content_45 = {
    Text = "Saat menyerahkan dua helai daun maple kepada penjaga, kunci perak di dadamu berkilau dengan cahaya redup. Kamu dengan mudah menangkap titik cahaya dari penjaga."
  },
  AvgDialog_131222_Content_46 = {
    Text = "Sementara itu, titik cahaya lainnya menyala di dunia roh kamu. Di persimpangan tautan kedua titik cahaya, fatamorgana Clementine menggoyangkan pendulum di tangannya."
  },
  AvgDialog_131222_Content_47 = {
    Text = "Hewi……Graf Hewi……"
  },
  AvgDialog_131222_Content_48 = {
    Text = "Ah, Graf Earl, Grafina, Kadlin Manor menyambut kedatangan Anda berdua."
  },
  AvgDialog_131222_Content_49 = {
    Text = "Di bawah pandangan hormat penjaga, kalian melangkah di jalan berbatu halus di dalam perkebunan."
  },
  AvgDialog_131222_Content_5 = {
    Text = "Setelah hening sejenak, rumah besar ini kembali dipenuhi oleh tamu-tamu berharga, pemilik barunya mengumumkan kembalinya melalui serangkaian salon."
  },
  AvgDialog_131222_Content_50 = {
    Text = "Bagaimana rasanya, Penjaga Rahasia {Male=先生,Female=小姐}?"
  },
  AvgDialog_131222_Content_51 = {
    Text = "Meskipun saya masih tidak memahami arti kekuasaan yang kamu maksud, tetapi saya benar-benar merasakan sesuatu yang berbeda…"
  },
  AvgDialog_131222_Content_52 = {
    Text = "Kesenangan yang muncul setelah diolok-olok, belum pernah terjadi padaku... seperti... emosi yang sepenuhnya bukan milikku..."
  },
  AvgDialog_131222_Content_53 = {
    Text = "Kamu mengangkat tanganmu, dua helai daun maple yang indah meninggalkan ujung jarimu, berputar dengan ceria di angin."
  },
  AvgDialog_131222_Content_54 = {
    Text = "Saat kamu melangkah masuk ke dalam rumah besar dengan senyuman yang pantas bersama Arachne, kamu yakin bahwa kamu mendengar tawa bahagia yang berasal dari dalam tubuhmu."
  },
  AvgDialog_131222_Content_56 = {
    Text = "Sulit dibayangkan, ada orang yang bisa meraih pencapaian seperti ini di usia semuda itu."
  },
  AvgDialog_131222_Content_57 = {
    Text = "Setelah perundingan perdagangan kali ini berakhir, hubungan antara dunia bisnis dan politik di kota ini akan mengalami perubahan yang belum pernah terjadi sebelumnya. Ini adalah kesempatan yang langka..."
  },
  AvgDialog_131222_Content_58 = {
    Text = "Surat undangan yang sulit didapatkan oleh kepala editor, kali ini kita harus mendapatkan beberapa momen yang luar biasa. Nanti kamu bawa peralatan dan ikuti, kita akan berusaha berjalan maju, mendekat sedikit…"
  },
  AvgDialog_131222_Content_59 = {
    Text = "Keluar! Keluar!"
  },
  AvgDialog_131222_Content_6 = {
    Text = "Halo, ini adalah surat undangan saya."
  },
  AvgDialog_131222_Content_60 = {
    Text = "Dengan suara teriakan pemuda itu, semua orang berlari menuju pintu besar yang terbuka."
  },
  AvgDialog_131222_Content_61 = {
    Text = "Gaun panjang berwarna merah seperti mawar yang bersemangat, membuat semua dekorasi dan kerumunan di dalam kamar tampak pudar."
  },
  AvgDialog_131222_Content_62 = {
    Text = "Wajah Soreil menampilkan senyuman sopan yang tak pernah salah, dengan gestur paling sempurna, ia melambai pelan kepada kerumunan."
  },
  AvgDialog_131222_Content_63 = {
    Text = "Di panggung ini, dia tampil lebih baik dari sebelumnya…… Lama tidak berjumpa, Mawar Merah."
  },
  AvgDialog_131222_Content_64 = {
    Text = "Hadirin sekalian, selamat datang di manor saya. Di salon hari ini, beberapa jalan komersial di kota ini akan memiliki pemilik baru."
  },
  AvgDialog_131222_Content_65 = {
    Text = "Tentu saja, para bangsawan terhormat kita juga akan mendapatkan keuntungan yang selayaknya."
  },
  AvgDialog_131222_Content_66 = {
    Text = "Kurasa, malam ini pasti akan ada jamuan makan malam yang menakjubkan dan menyenangkan."
  },
  AvgDialog_131222_Content_67 = {
    Text = "Koki di rumah besar telah menyiapkan kue dan sampanye yang tiada tara untuk kalian, silakan beristirahat sejenak. Segera, jamuan malam kita akan dimulai secara resmi."
  },
  AvgDialog_131222_Content_68 = {
    Text = "Pandangan Sorel tersenyum sambil melintasi seluruh ruangan, lalu berbalik dan berjalan ke atas."
  },
  AvgDialog_131222_Content_69 = {
    Text = "S...Sorel!...Karen"
  },
  AvgDialog_131222_Content_7 = {
    Text = "……Ah, selamat datang, Tuan Fugen. Pemilik sedang menunggu kedatangan Anda di dalam, silakan masuk."
  },
  AvgDialog_131222_Content_70 = {
    Text = "Suaramu tenggelam dalam perdebatan dan teriakan kerumunan."
  },
  AvgDialog_131222_Content_71 = {
    Text = "Nyonya Sorel! Nyonya Sorel! Bolehkah saya tahu bagaimana Anda merencanakan pembagian kawasan bisnis? Apakah ini akan menyentuh..."
  },
  AvgDialog_131222_Content_72 = {
    Text = "Ssst, Tuan jurnalis. Aku baru saja kembali setelah menyelesaikan urusan di luar, tunggu aku berganti pakaian, aku akan menjawab semua pertanyaan yang ingin kau ketahui."
  },
  AvgDialog_131222_Content_73 = {
    Text = "Sorel melambaikan tangan kepada wartawan dan berjalan masuk ke area kamar tidur di lantai atas gedung."
  },
  AvgDialog_131222_Content_74 = {
    Text = "Sepertinya kita harus menunggu sampai dia keluar untuk bertanya padanya."
  },
  AvgDialog_131222_Content_75 = {
    Text = "Kau memperhatikan pelayan di samping Sorel itu tidak?"
  },
  AvgDialog_131222_Content_76 = {
    Text = "Karen? Tentu saja, dia seharusnya juga tidak mendengarnya... Tunggu, maksudmu..."
  },
  AvgDialog_131222_Content_77 = {
    Text = "Kamu mengingat aura yang dimiliki Karen. Aura itu sangat berbeda dari yang kamu kenal, bahkan ketika berada di dimensi yang berbeda, mereka tidak mungkin milik orang yang sama."
  },
  AvgDialog_131222_Content_78 = {
    Text = "Aku merasakan trajektori nasib yang tidak seharusnya ada di panggung ini… nasibnya telah tercemar."
  },
  AvgDialog_131222_Content_79 = {
    Text = "Nyonya Sorel dalam bahaya"
  },
  AvgDialog_131222_Content_8 = {
    Text = "Hmph, bahkan pedagang yang bau tembaga seperti Fugen pun bisa masuk ke kediaman Adipati Tua, sikap Londinium sudah sepenuhnya lenyap..."
  },
  AvgDialog_131222_Content_80 = {
    Text = "Kamu dengan keras mendorong kerumunan, menemukan sebuah tangga tersembunyi di belakang gedung."
  },
  AvgDialog_131222_Content_81 = {
    Text = "Maaf, {Male=先生,Female=小姐}, ini adalah kediaman pribadi Nyonya Soreil, dilarang bagi yang tidak berkepenting……"
  },
  AvgDialog_131222_Content_82 = {
    Text = "Nyonya Sorel mengundang saya untuk datang dan membahas urusan penting dengannya."
  },
  AvgDialog_131222_Content_83 = {
    Text = "Kamu mengeluarkan selembar serbet yang dicabut sembarangan. Cahaya perak bersinar, sebuah kartu identitas polisi dari Komite diletakkan di depan penjaga."
  },
  AvgDialog_131222_Content_84 = {
    Text = "Maaf, saya tidak mengenali Anda... Nyonya Sorel sedang di atas, saya bisa..."
  },
  AvgDialog_131222_Content_85 = {
    Text = "Misi rahasia, jangan biarkan orang lain mengetahui kedatanganku."
  },
  AvgDialog_131222_Content_86 = {
    Text = "Belum sempat petugas berbicara, kamu segera berlari menaiki tangga."
  },
  AvgDialog_131222_Content_88 = {
    Text = "Pakaian Anda sudah siap, Nyonya Sorel"
  },
  AvgDialog_131222_Content_89 = {
    Text = "Londinium adalah sebuah padang liar yang asli, para politisi dan pedagang adalah hyena kota ini…"
  },
  AvgDialog_131222_Content_9 = {
    Text = "Halo, silakan tunjukkan surat undangan."
  },
  AvgDialog_131222_Content_90 = {
    Text = "Soreil mengambil pakaian yang disiapkan Kallen. Cahaya menembus kain sutra merah tipis itu, memproyeksikan bayangan indah nan mencolok di kamar tidur yang mewah."
  },
  AvgDialog_131222_Content_91 = {
    Text = "Hyena juga memiliki sisi yang menggemaskan. Sebuah daging busuk bisa membuat mereka berbondong-bondong. Keserakahan, tajam, kejam, kekanak-kanakan. Tidak ada senjata yang lebih berguna daripada mereka."
  },
  AvgDialog_131222_Content_92 = {
    Text = "Kulihat mereka sudah tidak sabar menunggu……Anda muncul agak terlambat hari ini, dan gaun mewah ini pun sudah sedikit kotor."
  },
  AvgDialog_131222_Content_93 = {
    Text = "Anda seharusnya kembali lebih awal, Nyonya."
  },
  AvgDialog_131222_Content_94 = {
    Text = "Gerakan Sorel terhenti sejenak. Dia perlahan melepaskan gaun berwarna darahnya dan menatap wajah tenang Karen."
  },
  AvgDialog_131222_Content_95 = {
    Text = "Seharusnya ada yang mengajarkanmu bagaimana pelayan berbicara dengan tuannya. Ada apa denganmu hari ini?"
  },
  AvgDialog_131222_Content_96 = {
    Text = "Nyonya Sorel, Anda memiliki noda dari Kawasan Timur di tubuh Anda. Saya penasaran, ke mana Anda mengirim orang itu yang baik hati?"
  },
  AvgDialog_131222_Content_97 = {
    Text = "Kamar yang terang menjadi redup sejenak. Beberapa laba-laba hitam berubah dari bayangan menjadi sosok manusia, mengelilingi Sorel di tengah."
  },
  AvgDialog_131222_Content_98 = {
    Text = "Anda memiliki satu orang pelayan yang sangat setia, Nyonya Sorel. Meskipun dia sangat tertarik untuk mencuri dan menjual aset Anda, kesetiaannya dalam menjaga keamanan Anda tidak diragukan lagi."
  },
  AvgDialog_131222_Content_99 = {
    Text = "Bahkan hingga sekarang, kehendaknya masih melawan dengan keras. Hanya saja sangat disayangkan, kekuatan takdir bukanlah sesuatu yang bisa dilawan oleh manusia."
  },
  AvgDialog_131223_Content_1 = {
    Text = "Takdir. Takdir yang liar, hampa, dan menyedihkan. Takdir-takdir yang terbuang tidak tahu dari mana mereka berasal, maupun ke mana mereka menuju."
  },
  AvgDialog_131223_Content_10 = {
    Text = "Suara Nefraea tiba-tiba menjadi tajam. Cahaya kelam menyala, benang merah darah mengikatnya dengan erat, sisa-sisa api lentera membakar tubuhnya."
  },
  AvgDialog_131223_Content_11 = {
    Text = "Capit raksasa bergerak di udara, sepasang mata majemuk besar yang mengalirkan lendir hitam, memandang kalian dengan senyuman. Benang merah darah melilit tubuhnya, melayang dalam pusaran nasib."
  },
  AvgDialog_131223_Content_12 = {
    Text = "Dia di samping, roda pemintal yang hancur dan mengumpulkan benang itu berputar perlahan dan tak terhentikan, mencekik semua panggung, mencekik Nefraea sendiri."
  },
  AvgDialog_131223_Content_13 = {Text = "Ukh——"},
  AvgDialog_131223_Content_14 = {
    Text = "Kamu memegang kepalamu dengan rasa sakit yang menyiksa. Di bawah putaran roda tenun, Dunia Rohmu mulai bergelora. Kamu terengah-engah, mencoba menenangkan rasa sakit yang sangat hebat."
  },
  AvgDialog_131223_Content_15 = {
    Text = "Di sisi Nefraea, pecahan Lorong Dimensi sudah hampir habis. Benang-benang di tubuh kalian, serta pola seperti boneka itu, semakin jelas."
  },
  AvgDialog_131223_Content_16 = {
    Text = "Kekuatan saluran Dimensi… Dia hampir sepenuhnya menyerapnya"
  },
  AvgDialog_131223_Content_17 = {
    Text = "Abu sisa ungu muda mengalir terus-menerus dari dalam tubuh Arachne, seperti ngengat yang terbang menuju jaring takdir yang hampir sepenuhnya hancur."
  },
  AvgDialog_131223_Content_18 = {
    Text = "Arachne menggigil dengan tangan yang bergetar pada frekuensi yang tak berubah sejak zaman purba, memutar roda pemintal di tangannya. Suaranya, tetap tenang seperti saat pertama kali kamu melihatnya."
  },
  AvgDialog_131223_Content_19 = {
    Text = "Kau sudah melihatnya. Ini adalah titik pertemuan nasib, Nefraea."
  },
  AvgDialog_131223_Content_2 = {
    Text = "Mereka ditarik oleh benang-benang, membanjirimu, berubah menjadi genangan-genangan cairan hitam pekat dalam cahaya perakmu."
  },
  AvgDialog_131223_Content_20 = {
    Text = "Semua kesalahan akan berakhir di sini."
  },
  AvgDialog_131223_Content_21 = {
    Text = "Betapa percaya dirinya pernyataan itu, Nona Tahanan. Mari kita lihat, apa yang akan kau gunakan untuk menghentikan Dewa, untuk menghentikan nasib itu sendiri..."
  },
  AvgDialog_131223_Content_22 = {
    Text = "Kegilaan senyum mekar di wajah Nefraea. Benang yang membatasi dia mengangkatnya, di atas panggung yang hancur, dia adalah satu-satunya cahaya."
  },
  AvgDialog_131223_Content_23 = {
    Text = "\"Kemari, wahai para pemuja yang merangkak di dunia! Berlutut dan bersujudlah di hadapanku!\""
  },
  AvgDialog_131223_Content_24 = {
    Text = "\"Yang Mahatinggi telah turun dari takhta langit, akhir yang tak dapat dilawan, telah menampakkan diri di sini!\""
  },
  AvgDialog_131223_Content_25 = {
    Text = "\"Takdir yang palsu itu, mari bersama-sama, menyambut kehancurannya!\""
  },
  AvgDialog_131223_Content_3 = {
    Text = "Lendir yang liar, hampa, menyedihkan, seperti nasib mereka sendiri."
  },
  AvgDialog_131223_Content_4 = {
    Text = "Nefraea tidak memperhatikan semua ini, pemandangan di depannya telah berlangsung selama bertahun-tahun, dan dia sudah terbiasa dengan hal itu."
  },
  AvgDialog_131223_Content_5 = {
    Text = "Aku sudah melihat dengan jelas. Gambar-gambar yang kau lihat, segala sesuatu yang kau lihat, akhirnya aku melihatnya dengan jelas......"
  },
  AvgDialog_131223_Content_6 = {
    Text = "Rasa sakit yang dibawa oleh pecahan telah mati rasa, dia tersenyum sambil menatap kekosongan yang kacau di dalam teater."
  },
  AvgDialog_131223_Content_7 = {
    Text = "Senyum yang angkuh, penuh belas kasihan, dan acuh tak acuh, dalam sekejap, kamu hampir tidak bisa membedakan dia dengan Arachne."
  },
  AvgDialog_131223_Content_8 = {
    Text = "Hanya orang yang terjebak dalam sangkar yang dapat benar-benar membuka sangkar. Apa yang kamu lihat adalah kaos dan kehancuran, bukan nasib yang nyata, Nefraea..."
  },
  AvgDialog_131223_Content_9 = {
    Text = "Hehehehe!......Selama bertahun-tahun ini, kamu memang menipu dirimu sendiri seperti ini, Arachne?"
  },
  AvgDialog_131224_Content_1 = {
    Text = "Penonton, Aktor, Penulis"
  },
  AvgDialog_131224_Content_10 = {Text = "Ini......!"},
  AvgDialog_131224_Content_100 = {
    Text = "Pergilah temukan %player%, anak-anakku."
  },
  AvgDialog_131224_Content_101 = {
    Text = "Pergilah rebut kekuatan %player%, potong setiap benang takdir, robek jaring takdir yang agung, biarkan setiap orang yang menghalangi jalan ini mati di jalan itu!"
  },
  AvgDialog_131224_Content_102 = {
    Text = "Kami akan menggunakan darah fragmen ini, agar Awal yang agung, bangkit kembali."
  },
  AvgDialog_131224_Content_103 = {
    Text = "Ketika kamu melihat jaring takdir yang kamu jaga dengan sepenuh hati hancur berkeping-keping, menjadi gumpalan lumpur, akankah kamu tenggelam dalam kehampaan tanpa akhir seperti kami?"
  },
  AvgDialog_131224_Content_104 = {
    Text = "Dewi nasib, saudara perempuanku yang baik, sayang <Red:Arachne>?"
  },
  AvgDialog_131224_Content_105 = {
    Text = "Jarak antara panggung dan kursi penonton seolah tidak lagi ada, ruang kehilangan maknanya di dalam teater ini."
  },
  AvgDialog_131224_Content_106 = {
    Text = "Dalam tawa yang mengerikan, boneka itu tampak berdiri di depan kalian, menatap mata Arachne dengan tajam."
  },
  AvgDialog_131224_Content_107 = {
    Text = "Cahaya memudar, tirai jatuh. Boneka dan suara tawanya menghilang, di dalam teater yang kosong, hanya tersisa suara roda pemintal yang berputar pelan."
  },
  AvgDialog_131224_Content_108 = {
    Text = "Maaf, saya tidak sepenuhnya mengerti... nasib yang terbuang, maksudnya apa?"
  },
  AvgDialog_131224_Content_109 = {
    Text = "Seperti yang Anda lihat, nasib adalah benang-benang yang kacau. Jika tidak ada yang menjalin, alam semesta ini akan terjerumus ke dalam kekacauan yang tak ada habisnya. Saya pikir, itu adalah pemandangan yang tidak ingin kita lihat."
  },
  AvgDialog_131224_Content_11 = {
    Text = "Saat kamu memasuki pintu, pintu di belakangmu menghilang."
  },
  AvgDialog_131224_Content_110 = {
    Text = "Tentu saja…"
  },
  AvgDialog_131224_Content_111 = {
    Text = "Menyusun benang menjadi jaringan nasib, menjaga agar alam semesta ini berfungsi dengan normal, adalah tanggung jawab abadi saya."
  },
  AvgDialog_131224_Content_112 = {
    Text = "Setiap saat, takdir memiliki kemungkinan yang tak terhitung. Setiap saat, aku harus membuat pilihan untuk semua takdir."
  },
  AvgDialog_131224_Content_113 = {
    Text = "Takdir yang benar akan bergabung ke dalam jaring agung, takdir yang salah akan dibuang. Begitulah jaring takdir beroperasi, tak terhindarkan."
  },
  AvgDialog_131224_Content_114 = {
    Text = "Adik perempuanku, juga merupakan bagian yang aku buang dalam nasib-nasib yang salah itu."
  },
  AvgDialog_131224_Content_115 = {
    Text = "Arachne tersenyum, dalam ceritanya yang tenang, kamu tidak merasakan sedikitpun gelombang emosi."
  },
  AvgDialog_131224_Content_116 = {
    Text = "Nasib yang terbuang itu… akan dikirim ke\"Penjara Kegelapan\"?"
  },
  AvgDialog_131224_Content_117 = {
    Text = "Mimpi Orang itu yang Maha Tinggi membentuk alam semesta ini, tempat yang disebut\"Kedalaman Neraka\"adalah bawah sadar dewa, tempat berkumpulnya segala hal yang belum terjadi dan segala nasib yang tidak ada."
  },
  AvgDialog_131224_Content_118 = {
    Text = "Mereka seharusnya sepenuhnya lenyap di tempat yang hampa itu, tetapi di bawah pimpinan adikku, mereka entah bagaimana berhasil bertahan."
  },
  AvgDialog_131224_Content_119 = {
    Text = "Arachne melihat tirai besar itu, menatap di belakang tirai, boneka yang mewakili Nefraea."
  },
  AvgDialog_131224_Content_12 = {
    Text = "Di dalam toko sempit yang kamu bayangkan, terdapat ruang dimensi yang luas dan tak terbatas."
  },
  AvgDialog_131224_Content_120 = {
    Text = "Dia tidak memiliki kemampuan untuk mengendalikan nasib, tetapi dia seperti aku, dapat melihat benang-benang nasib, menghalangi mereka, mencemari mereka, menghancurkan trajektori yang aku susun untuk mereka, dan mengarahkannya menuju kematian…"
  },
  AvgDialog_131224_Content_121 = {
    Text = "Jadi dia ingin menemukan saya, memanfaatkan kekuatan saya, untuk membangunkan Touva Wave kembali?"
  },
  AvgDialog_131224_Content_122 = {
    Text = "Saya tidak tahu rencana spesifiknya, tetapi sejauh ini tampaknya memang seperti itu. Bagaimanapun, dia adalah kesalahan yang harus saya selesaikan."
  },
  AvgDialog_131224_Content_123 = {
    Text = "Dia menutup saluran antar dimensi, juga untuk ini, kan……"
  },
  AvgDialog_131224_Content_124 = {
    Text = "Lorong dimensi adalah yang aku tutup. Dia selalu menunggu, menunggu saat untuk pergi ke Kadas bersamamu."
  },
  AvgDialog_131224_Content_125 = {
    Text = "Kadas adalah sebuah dimensi yang belum pernah saya masuki kekuatanku, dan juga merupakan tempat yang paling erat terhubung dengan Orang itu, Sang Tuhan yang Maha Tinggi."
  },
  AvgDialog_131224_Content_126 = {
    Text = "Jika dia kembali bersamamu, nasib bencana akan benar-benar tidak dapat diperbaiki."
  },
  AvgDialog_131224_Content_127 = {
    Text = "Mohon maafkan keputusan sepihak saya, Penjaga Rahasia {Male=先生,Female=小姐}."
  },
  AvgDialog_131224_Content_128 = {
    Text = "Saya mengerti, Arachne. Jika apa yang kamu katakan itu benar, maka itu bukanlah pemandangan yang ingin saya lihat."
  },
  AvgDialog_131224_Content_129 = {
    Text = "Jadi, jika aku ingin kembali ke Kadas, aku harus menyelesaikannya terlebih dahulu..."
  },
  AvgDialog_131224_Content_13 = {
    Text = "Panggung-panggung tak terhitung melayang bagai bintang-bintang di kegelapan wilayah ini, boneka-boneka melantunkan dialog mereka di atas setiap panggung."
  },
  AvgDialog_131224_Content_130 = {
    Text = "Tuan, ada anomali di panggung area GI-9849. Ini adalah kasus ketiga hari ini."
  },
  AvgDialog_131224_Content_131 = {
    Text = "Setelah mencuri bahan untuk menyusun takdir, dia selalu menikmati merusak nasib."
  },
  AvgDialog_131224_Content_132 = {
    Text = "Mohon maaf, %player%, saya sekarang perlu menangani masalah-masalah itu. Silakan ikuti saya, ada beberapa hal penting yang perlu saya sampaikan kepada Anda."
  },
  AvgDialog_131224_Content_133 = {
    Text = "Arachne tersenyum sambil menggelengkan kepala. Dia memberi isyarat undangan kepadamu, berdiri sambil membawa roda pemintal."
  },
  AvgDialog_131224_Content_135 = {
    Text = "Ini... adalah panggung yang telah dihancurkan?..."
  },
  AvgDialog_131224_Content_136 = {
    Text = "Mengikuti jalan yang terbuat dari jaring laba-laba, kalian tiba di sebuah panggung yang usang. Di kafe sederhana di atas panggung, beberapa orang yang terlihat seperti pelajar sedang berbicara dengan kepala menunduk."
  },
  AvgDialog_131224_Content_137 = {
    Text = "Selama waktu ini, dia terus-menerus mengirim pelayan-pelayannya untuk merusak nasib dunia ini. Para pelayanku sedang mencari mereka ke sana kemari, dan pertarungan dengan mereka telah membuat banyak anak baik kehilangan nyawa."
  },
  AvgDialog_131224_Content_138 = {
    Text = "Semua nasib dunia terhubung dalam satu jaring raksasa, setiap kehancuran dunia akan merobek seluruh jaring nasib, membawa segalanya ke dalam kekacauan yang sepenuhnya dan fatal."
  },
  AvgDialog_131224_Content_139 = {
    Text = "Nefraea telah mencuri bahan untuk menyusun takdir, saya tidak dapat dengan mudah menggunakan kekuatan saya. Penjaga {Male=Tuanku, Female=Nyonyaku}, saya berpikir, mungkin Anda dapat membantu saya memperbaiki nasib dunia ini?"
  },
  AvgDialog_131224_Content_14 = {
    Text = "Dialog-dialog itu terdengar samar dari kejauhan, bagaikan doa khusyuk yang dipanjatkan oleh ribuan umat."
  },
  AvgDialog_131224_Content_140 = {
    Text = "Jika apa yang kamu katakan benar, dia juga merupakan masalah yang harus saya selesaikan."
  },
  AvgDialog_131224_Content_141 = {
    Text = "Arachne dengan menyesal mengangguk padamu. Dia mengangkat tangan, dengan lembut menggerakkan udara yang kosong, benang-benang tersembunyi itu."
  },
  AvgDialog_131224_Content_142 = {
    Text = "Deng!——"
  },
  AvgDialog_131224_Content_143 = {
    Text = "Setelah suara alat musik yang jernih, suara pembawa acara yang merdu terdengar, seperti aliran jernih yang abadi yang terus mengalir ke dalam kolam yang dalam."
  },
  AvgDialog_131224_Content_144 = {
    Text = "Trompet memainkan melodi bunga. Mahasiswa muda dan akademisi, naik——"
  },
  AvgDialog_131224_Content_145 = {
    Text = "Arachne membuat gerakan undangan."
  },
  AvgDialog_131224_Content_146 = {
    Text = "Sudah saatnya kita tampil, %player%."
  },
  AvgDialog_131224_Content_147 = {
    Text = "Kamu mengangguk. Dalam suara pengumuman yang merdu, dua boneka melangkah ke panggung yang menjadi milik mereka."
  },
  AvgDialog_131224_Content_15 = {
    Text = "Serangkaian benang laba-laba membentang dari aktor boneka dan panggung, bersama dengan jalan yang terbuat dari benang laba-laba di bawah kakimu, berkumpul menuju panggung yang terletak di tengah ruang ini."
  },
  AvgDialog_131224_Content_16 = {
    Text = "Kamu menoleh, pelayan di sampingmu sudah berjalan ke depan."
  },
  AvgDialog_131224_Content_17 = {
    Text = "Sungguh upacara sambutan yang aneh…"
  },
  AvgDialog_131224_Content_18 = {
    Text = "Kamu ragu-ragu, berjalan di sepanjang jalan yang dipenuhi jaring laba-laba menuju panggung di tengah. Saat kamu melewati panggung-panggung yang melayang, serangkaian percakapan melayang masuk ke telingamu."
  },
  AvgDialog_131224_Content_19 = {
    Text = "Orang ini, saya melihat kebingungan di mata Anda."
  },
  AvgDialog_131224_Content_2 = {
    Text = "Saya masih ada satu pertanyaan..."
  },
  AvgDialog_131224_Content_20 = {
    Text = "Apakah kejadian yang terjadi di toko barusan tidak membuat Anda takut?"
  },
  AvgDialog_131224_Content_21 = {
    Text = "Struktur yang berbasis pada minuman keras emas, dengan rasa bunga hibiscus, pasti sangat cocok dengan suasana hati Anda saat ini."
  },
  AvgDialog_131224_Content_23 = {
    Text = "Ah! Satu orang anak jalanan yang tidak punya tempat tinggal, begitu kecil, begitu malang."
  },
  AvgDialog_131224_Content_24 = {
    Text = "Dengan mengandalkan pakaian tipis ini, bagaimana kamu akan bertahan di musim dingin ini?"
  },
  AvgDialog_131224_Content_25 = {
    Text = "Ikutlah denganku, aku akan membawamu ke tempat yang terlindung dari badai salju…"
  },
  AvgDialog_131224_Content_27 = {
    Text = "Orang-orang ini... adalah mereka yang baru saja aku temui?"
  },
  AvgDialog_131224_Content_28 = {
    Text = "Bagaimana mereka bisa muncul di panggung-panggung ini…"
  },
  AvgDialog_131224_Content_29 = {
    Text = "Polisi yang berpatroli, pegawai yang membaca koran, pengemudi yang menikmati pemandangan jalan, pasangan yang membeli bunga, bangsawan yang berbincang-bincang……"
  },
  AvgDialog_131224_Content_3 = {
    Text = "Ini sudah pertanyaan Anda yang ke dua puluh tiga, {Male=先生,Female=小姐}."
  },
  AvgDialog_131224_Content_30 = {
    Text = "Orang-orang yang pernah dan belum pernah kamu temui, memainkan cerita mereka sendiri di atas panggung yang tak terhitung jumlahnya ini. Di panggung masing-masing, mereka adalah pemeran utama dalam cerita mereka sendiri."
  },
  AvgDialog_131224_Content_31 = {
    Text = "Salam sejahtera, %player%! Berbahagialah, bayi Akut!"
  },
  AvgDialog_131224_Content_32 = {
    Text = "Salam sejahtera, %player%! Berbahagialah, Penjaga Rahasia Misagre!"
  },
  AvgDialog_131224_Content_33 = {
    Text = "Salam sejahtera, %player%! Berbahagialah, Dewa Penghancur Segalanya!"
  },
  AvgDialog_131224_Content_34 = {
    Text = "Setelah kalian mendekati panggung tengah, tiga boneka kayu dengan bentuk yang berbeda-beda naik ke atas panggung dan memberi penghormatan ke arahmu."
  },
  AvgDialog_131224_Content_35 = {
    Text = "Tuan sedang menunggu Anda di dalam. Silakan masuk, Penjaga Rahasia {Male=先生,Female=小姐}."
  },
  AvgDialog_131224_Content_36 = {
    Text = "Ketika pintu kabin terbuka, seolah-olah semua gambar dan suara di seluruh teater terhenti sejenak."
  },
  AvgDialog_131224_Content_37 = {
    Text = "Kamu melangkah masuk ke dalam pintu, menyingkap tirai——"
  },
  AvgDialog_131224_Content_38 = {
    Text = "Mereka muncul di panggung-panggung ini, karena nama teater ini adalah takdir."
  },
  AvgDialog_131224_Content_39 = {
    Text = "Suara yang dingin dan lembut tiba di hadapanmu selangkah lebih cepat dari warna."
  },
  AvgDialog_131224_Content_4 = {
    Text = "Dibandingkan dengan teka-teki di tempat ini, pertanyaan saya masih jauh dari cukup."
  },
  AvgDialog_131224_Content_40 = {
    Text = "Di dalam sebuah balkon yang nyaris tak bertepi, benang-benang yang menghubungkan panggung dan boneka berkumpul pada sebuah roda pemintal yang berpendar redup. Seorang wanita duduk di persimpangan benang-benang itu, memutar roda pemintal dengan lembut."
  },
  AvgDialog_131224_Content_41 = {
    Text = "Kamu melihat setiap detail dirinya dengan jelas, tetapi di setiap kedipan mata, seluruh kesan tentangnya lenyap dari dunia batinmu, sirna tanpa bekas."
  },
  AvgDialog_131224_Content_42 = {
    Text = "Sosoknya selalu kabur dalam benakmu. Ketika dia menoleh memandangmu, jantungmu yang selama ini dalam kewaspadaan tinggi mulai berdebar keras."
  },
  AvgDialog_131224_Content_43 = {Text = "Kamu?!!"},
  AvgDialog_131224_Content_44 = {
    Text = "Di Kapal Paradise… dan juga orang yang menyerang kami beberapa kali…!"
  },
  AvgDialog_131224_Content_45 = {
    Text = "Saat kamu bersiap untuk mengalirkan kekuatan jiwa ke dalam kunci perak, pemilik teater mengulurkan tangannya, melayang di udara. Gerakannya lembut dan anggun, seolah-olah sedang menyentuh sebuah senar dengan lembut."
  },
  AvgDialog_131224_Content_46 = {Text = "!!!"},
  AvgDialog_131224_Content_47 = {
    Text = "Kekuatan roh datang ke ujung jarimu, lalu mundur seperti arus deras yang terhalang bendungan. Saat kamu mengangkat tanganmu di udara, kamu tiba-tiba menyadari, entah sejak kapan, tanganmu kosong tanpa apa-apa."
  },
  AvgDialog_131224_Content_48 = {
    Text = "Kunci perak… kunci perak selalu ada di tanganku… kenapa…"
  },
  AvgDialog_131224_Content_49 = {
    Text = "Dia tersenyum dan mengangguk pelan kepada pelayannya."
  },
  AvgDialog_131224_Content_5 = {
    Text = "Saya bukan penjawab yang kamu cari. Orang yang dapat menjawab pertanyaanmu, sedang menunggu di sini."
  },
  AvgDialog_131224_Content_50 = {
    Text = "Di hadapan tatapan terkejutmu, pelayan itu melangkah maju dan dengan hormat menyerahkan kunci perak ke tanganmu."
  },
  AvgDialog_131224_Content_51 = {
    Text = "Tidak mungkin... dia sama sekali tidak mungkin mencuri kunci perak!..."
  },
  AvgDialog_131224_Content_52 = {
    Text = "Sebelum memasuki teater, Anda sudah menggenggam kunci di tangan dan terus menjaga koneksi spiritual dengan kunci perak."
  },
  AvgDialog_131224_Content_53 = {
    Text = "Pelatihan Misagre telah memberi Anda profesionalisme dan kewaspadaan tingkat tinggi, tidak ada seorang pun yang bisa mencuri kunci perak dari tangan Anda."
  },
  AvgDialog_131224_Content_54 = {
    Text = "Itu sebabnya……"
  },
  AvgDialog_131224_Content_55 = {
    Text = "Tidak ada yang bisa membuatnya pergi darimu, tetapi nasib bisa."
  },
  AvgDialog_131224_Content_56 = {
    Text = "Mohon maaf, %player%, saya memahami kegugupan Anda, dan saya menghormati kekuatan Anda."
  },
  AvgDialog_131224_Content_57 = {
    Text = "Demi mencegah kerusakan yang tidak disengaja terhadap teater, saya terpaksa mengubah sementara takdir kunci perak di tangan Anda. Mohon maafkan saya."
  },
  AvgDialog_131224_Content_58 = {
    Text = "Dia melambaikan tangan, seberkas cahaya menyinari ruang di antara kamu dan dia. Kamu memandang dengan saksama, akhirnya melihat sehelai benang samar yang memanjang dari kunci perak, terhubung ke roda pemintalnya."
  },
  AvgDialog_131224_Content_59 = {
    Text = "Benang-benang ini adalah...?"
  },
  AvgDialog_131224_Content_6 = {
    Text = "Kalian berhenti di depan pintu teater yang hanya muat untuk satu orang. Tidak ada tanda, juga tidak ada pelanggan, seperti jaring laba-laba yang tidak mencolok di antara toko-toko mewah Londinium."
  },
  AvgDialog_131224_Content_60 = {
    Text = "Ada banyak penjelasan tentang benang, beberapa terlalu rumit untuk saat ini. Kamu bisa menganggapnya dengan sederhana sebagai… nasib."
  },
  AvgDialog_131224_Content_61 = {
    Text = "Roda pemintal berputar pelan dengan sendirinya. Dia berdiri dan mengangguk kepadamu sebagai tanda hormat."
  },
  AvgDialog_131224_Content_62 = {
    Text = "Arachne, tuan Teater Nasib. Sangat terhormat bertemu dengan Anda, Penjaga."
  },
  AvgDialog_131224_Content_63 = {
    Text = "Tidak perlu khawatir, Anda aman di sini."
  },
  AvgDialog_131224_Content_64 = {
    Text = "Memang, jika kau ingin membunuhku, barusan aku rasa tidak ada kesempatan bagiku untuk tetap hidup."
  },
  AvgDialog_131224_Content_65 = {
    Text = "Dengan Arachne menggerakkan benang, cahaya dari roda pemintal di dalam kotak menjadi redup. Kamu memandang dengan ekspresi campur aduk pada kunci perak yang dikembalikan oleh pelayan, mengerutkan dahi melihatnya."
  },
  AvgDialog_131224_Content_66 = {
    Text = "Di Kapal Paradise, kamu pernah memberiku bantuan. Di kota ini, kamu dua kali menyerangku…"
  },
  AvgDialog_131224_Content_67 = {
    Text = "Saya memahami kewaspadaan Anda. Tapi percayalah, saya tidak pernah melakukan hal yang menyakiti Anda."
  },
  AvgDialog_131224_Content_68 = {
    Text = "Memutuskan tautan saya dengan Kadas, menyerang saya berkali-kali... apakah kamu ingin mengatakan bahwa semua ini bukan kamu yang melakukannya?"
  },
  AvgDialog_131224_Content_69 = {
    Text = "Orang itu yang mengganggu Anda meskipun memiliki wajah yang sama dengan saya, tetapi bukan saya."
  },
  AvgDialog_131224_Content_7 = {
    Text = "Pelayan perlahan-lahan mendorong pintu terbuka, sosoknya menghilang ke dalam kegelapan di dalam pintu. Cahaya yang tidak diketahui asalnya berkedip-kedip di dalam kegelapan, seperti undangan yang tersembunyi."
  },
  AvgDialog_131224_Content_70 = {
    Text = "Mengenai koneksi Anda dengan Kadath… itu adalah jebakan yang berbahaya, %player%."
  },
  AvgDialog_131224_Content_71 = {Text = "Jebakan?"},
  AvgDialog_131224_Content_72 = {
    Text = "Seorang anak yang lahir karena saya telah menyebabkan masalah yang tidak perlu bagi Anda, saya sangat menyesal. Masalah ini bermula dari saya, dan saya sedang berusaha sekuat tenaga untuk memperbaiki kesalahan ini."
  },
  AvgDialog_131224_Content_73 = {
    Text = "Saya tidak mengerti…"
  },
  AvgDialog_131224_Content_74 = {
    Text = "Ini adalah sebuah cerita yang agak panjang dan terkait dengan nasib. Cerita selalu lebih mudah dipahami dibandingkan dengan sekadar pernyataan."
  },
  AvgDialog_131224_Content_75 = {
    Text = "Silakan duduk, Penjaga Rahasia {Male=先生,Female=小姐}. Babak baru drama ini baru saja dimulai tidak lama yang lalu."
  },
  AvgDialog_131224_Content_76 = {
    Text = "Arachne melambaikan tangan dengan lembut. Tirai terbuka, sebuah panggung kosong yang melayang muncul di depanmu."
  },
  AvgDialog_131224_Content_77 = {
    Text = "Sepertinya ada cermin yang samar-samar di atas panggung, memantulkan sosok kalian."
  },
  AvgDialog_131224_Content_78 = {
    Text = "Musik dimulai. Takdir yang Dibuang, naik panggung."
  },
  AvgDialog_131224_Content_79 = {
    Text = "Dengan cepat, sosokmu menghilang di cermin, sosok Arachne berubah menjadi sebuah boneka."
  },
  AvgDialog_131224_Content_8 = {
    Text = "Kamu sedikit ragu, lalu masuk ke dalam pintu."
  },
  AvgDialog_131224_Content_80 = {
    Text = "Dia masih duduk di kursinya, tetapi kelembutan dan ketenangan telah lenyap."
  },
  AvgDialog_131224_Content_81 = {
    Text = "Dia menggoyang-goyangkan gelas berisi darah di tangannya, bagaikan duduk di atas singgasana yang kejam. Tatapan polos namun kejam menyapu kursi penonton."
  },
  AvgDialog_131224_Content_82 = {
    Text = "Di belakangnya, empat pasang tungkai laba-laba yang tajam berayun santai, menyapu melewati wajah para pelayan di sisinya."
  },
  AvgDialog_131224_Content_83 = {
    Text = "Ah, udara kebebasan……"
  },
  AvgDialog_131224_Content_84 = {
    Text = "Sudah berapa tahun kita terkurung di jurang itu, pelayanku yang terkasih?"
  },
  AvgDialog_131224_Content_85 = {
    Text = "Saya tidak tahu, Tuan saya."
  },
  AvgDialog_131224_Content_86 = {
    Text = "Nama, waktu, emosi... Saya telah melupakan segalanya... Saya hanya ingat Anda, tuanku, yang terhormat Nefraea."
  },
  AvgDialog_131224_Content_87 = {
    Text = "Saya hanya ingat, Anda berkata kepada saya, akan membawa kami pergi dari sini, akan membawa kami, mengayunkan bilah tajam balas dendam kepada nasib."
  },
  AvgDialog_131224_Content_88 = {
    Text = "Aku ingat, anak. Aku telah membuat janji sebanyak sembilan puluh ribu kali kepada kalian, sekarang, biarkan aku memberitahumu yang kesembilan puluh ribu satu."
  },
  AvgDialog_131224_Content_89 = {
    Text = "Setiap momen, hanya satu nasib yang bisa ada. Eksekutor dari nasib itu akan memotong banyak nasib yang salah, meninggalkan satu-satunya nasib yang benar."
  },
  AvgDialog_131224_Content_90 = {
    Text = "Kami adalah nasib yang terbuang. Hehehehe... Pelayanku tercinta, kamu adalah sebuah kesalahan, sama seperti aku."
  },
  AvgDialog_131224_Content_91 = {
    Text = "Di dalam alam bawah sadar semesta ini, di dalam jurang kehampaan yang tidak ada, kami terasing, terkurung. Kami mengembara di sini, melupakan, selamanya. Hukuman kami lebih lama daripada waktu itu sendiri……"
  },
  AvgDialog_131224_Content_92 = {
    Text = "Seorang wanita bernama Nefraea bangkit dari kursi, membungkuk, dan tersenyum sambil bertatapan dengan Arachne di bangku penonton."
  },
  AvgDialog_131224_Content_93 = {
    Text = "Tapi, kenapa, Dewi nasib? Kenapa, yang terbuang, haruslah kita?"
  },
  AvgDialog_131224_Content_94 = {
    Text = "Tuhan yang tertinggi dan satu-satunya dari tak terhitungnya alam semesta, akhirnya terbangun sejenak. Dia kembali jatuh ke dalam tidur, tetapi penjara kesadarannya, jurang abadi, akhirnya terbuka untuk kita."
  },
  AvgDialog_131224_Content_95 = {
    Text = "Aku seharusnya sudah melupakan dan menghilang. Tapi kenapa, kenapa aku harus teringat semua rasa sakit ini?"
  },
  AvgDialog_131224_Content_96 = {
    Text = "Nefraea menghabiskan cairan di dalam cangkirnya, mengeluarkan desahan puas. Cairan merah cerah mengalir di sepanjang bibirnya yang pucat, menetes di atas roda pemintal yang suram di tangannya."
  },
  AvgDialog_131224_Content_97 = {
    Text = "Mungkin, ini adalah pengaturan takdir… nasib yang bahkan tidak bisa kau kendalikan."
  },
  AvgDialog_131224_Content_98 = {
    Text = "Dewa Awal kembali terlelap, tetapi fragmennya telah datang ke tempat kami."
  },
  AvgDialog_131224_Content_99 = {
    Text = "Saya tidak memiliki kemampuan untuk mengendalikan nasib seperti kamu. Saya hanyalah seorang pengubah nasib, seorang algojo yang berasal dari Kekosongan. Dosa-dosa dalam aliran nasib itu akan saya hukum atas nama Awal."
  },
  AvgDialog_131225_Content_1 = {
    Text = "Bayangan Masa Lalu"
  },
  AvgDialog_131225_Content_10 = {
    Text = "Berbeda sekali dengan ruang kosong yang kamu bayangkan berdasarkan pengalaman, bagian dalam vila ini tampak sangat ramai, Nefraea sepertinya sudah bertekad untuk menulis sembarangan dalam skenarionya."
  },
  AvgDialog_131225_Content_11 = {
    Text = "Lemari dan rak yang terus-menerus berdiri diam dan sesak, dipenuhi dengan berbagai ukuran wadah yang memenuhi setiap ruang yang ada."
  },
  AvgDialog_131225_Content_12 = {
    Text = "Cermin perak, telur laba-laba, sepatu tarian yang merayap dari makhluk aneh... Berbagai benda terendam dalam cairan yang tidak diketahui, seperti mulut-mulut yang diam-diam berteriak."
  },
  AvgDialog_131225_Content_13 = {
    Text = "Kamu datang di depan berbagai macam kaleng, dan mulai membacakan dengan suara pelan tulisan di labelnya."
  },
  AvgDialog_131225_Content_14 = {
    Text = "Dua tahun, mengucapkan kalimat pertama dalam hidup. Tidak memanggil keluarganya sendiri, tetapi mengucapkan selamat tinggal kepada pelayan tua yang telah merawat keluarganya selama beberapa generasi."
  },
  AvgDialog_131225_Content_15 = {
    Text = "Malam itu, pelayan tua meninggal karena penyakit jantung. Dengan membawa peninggalan pelayan, dia menangis di luar pintu rumah pelayan..."
  },
  AvgDialog_131225_Content_16 = {
    Text = "Itu adalah sebuah bros keluarga yang sudah usang."
  },
  AvgDialog_131225_Content_17 = {
    Text = "Pada usia lima tahun, di tengah sorakan tamu undangan yang membuat wajahnya memerah, ia dengan malu-malu menari waltz meniru ibunya..."
  },
  AvgDialog_131225_Content_18 = {
    Text = "Itu sepasang sepatu dansa merah yang cerah."
  },
  AvgDialog_131225_Content_19 = {
    Text = "Pada usia tujuh tahun, dia menerima hadiah ulang tahun dari ayahnya, sebuah roda tenun yang bernama \"Moirai\"."
  },
  AvgDialog_131225_Content_2 = {
    Text = "Brick Lane, apakah kamu masih ingat suasana saat menyelidiki di area Londinium ini."
  },
  AvgDialog_131225_Content_20 = {
    Text = "Di dalam benang roda, melihat bayangan nasib…"
  },
  AvgDialog_131225_Content_21 = {
    Text = "Itu adalah segenggam benang yang putus."
  },
  AvgDialog_131225_Content_22 = {
    Text = "Pertama kali pergi ke opera dengan orang tua… Pertama kali bertemu teman dekat… Pertama kali mengubur anjing kesayangan sendiri…"
  },
  AvgDialog_131225_Content_23 = {
    Text = "Tulisan di label kaleng satu per satu muncul di matamu. Setiap kali kamu menyentuhnya, sepotong kenangan samar muncul di benakmu. Kamu menoleh, bingung memandang Arachne."
  },
  AvgDialog_131225_Content_24 = {
    Text = "Ini... apakah semua ini ingatanmu?"
  },
  AvgDialog_131225_Content_25 = {
    Text = "Ini adalah ingatan saya yang dulu. Jauh sebelum ini, mereka milik orang yang bernama\"Kenangan\"."
  },
  AvgDialog_131225_Content_26 = {
    Text = "Semua ini adalah kenangan berharga…… Mengapa harus meletakkannya di atas sebuah rahasia?"
  },
  AvgDialog_131225_Content_27 = {
    Text = "Setiap orang dalam hidupnya, perlu membuat beberapa pilihan. Setiap pilihan, ada harganya."
  },
  AvgDialog_131225_Content_28 = {
    Text = "Demi mencapai tujuan akhir itu, kita selalu perlu mengorbankan beberapa hal. Saya rasa, Anda pasti sangat memahami hal ini, Penjaga Rahasia {Male=先生,Female=小姐}."
  },
  AvgDialog_131225_Content_29 = {
    Text = "Arachne tidak langsung menjawab pertanyaanmu, dia menatap lemari-lemari itu, dan dengan lembut menyentuh wadah-wadah yang penuh dengan cairan."
  },
  AvgDialog_131225_Content_3 = {
    Text = "Kotor, kaos, udara dipenuhi dengan bau asap batubara dan saluran pembuangan, aroma ini menemani Mason dan Jenkin selama semua waktu hidup mereka."
  },
  AvgDialog_131225_Content_30 = {
    Text = "Gerakannya sangat lembut dan lambat, seperti seorang lansia yang sudah uzur, mengelus mainan yang sangat dicintainya di masa kanak-kanak."
  },
  AvgDialog_131225_Content_31 = {
    Text = "Ambil ingatan ini dari tubuh Misteri Pasangan dan wujudkan dalam bentuk ini. Ini adalah pemandangan yang kau siapkan untukku, Nefraea."
  },
  AvgDialog_131225_Content_32 = {
    Text = "Apa yang ingin kau sampaikan padaku, aku mengerti..."
  },
  AvgDialog_131225_Content_33 = {
    Text = "<Big:<Shake:Aaaaaah!——>>"
  },
  AvgDialog_131225_Content_34 = {
    Text = "Teriakan menyayat hati bergema di dalam kamar, toples yang penuh kenangan bergetar lembut, seperti sekelompok penonton yang tertawa tanpa suara."
  },
  AvgDialog_131225_Content_35 = {
    Text = "！！Di dalam kamar di belakang koridor"
  },
  AvgDialog_131225_Content_36 = {Text = "BRAK—"},
  AvgDialog_131225_Content_37 = {
    Text = "Kamu lari cepat melintasi koridor, menabrak pintu kamar…"
  },
  AvgDialog_131225_Content_38 = {
    Text = "Kamu berada di tengah hujan lebat."
  },
  AvgDialog_131225_Content_39 = {
    Text = "Tidak ada guntur, tidak ada angin, dan tidak ada hujan. Hanya laba-laba yang berjatuhan dari langit-langit yang kosong seperti hujan deras."
  },
  AvgDialog_131225_Content_4 = {
    Text = "Dan pada saat ini, sebuah vila yang megah dan berkilauan tiba-tiba muncul di antara dua rumah kumuh, seperti kotak perhiasan yang diletakkan di tumpukan sampah."
  },
  AvgDialog_131225_Content_40 = {
    Text = "Hewan berkaki banyak hitam yang kental berkumpul menjadi gelombang yang mengalir deras, melahap semua benda dan semua cahaya di dalam rumah."
  },
  AvgDialog_131225_Content_41 = {
    Text = "Di tengah hujan deras yang gelap, laba-laba yang panik memanjat dan menggerogoti berkumpul menjadi sosok manusia yang sulit dikenali. Di tempat di mana ombak laba-laba belum menutupi, muncul wajah seorang lansia pucat yang pernah kamu lihat."
  },
  AvgDialog_131225_Content_42 = {
    Text = "Arachne......Nona......"
  },
  AvgDialog_131225_Content_43 = {
    Text = "Cepat... lari!..."
  },
  AvgDialog_131225_Content_44 = {
    Text = "Diamlah… di sini tidak ada dialogmu, Tuan yang \"baik hati\"."
  },
  AvgDialog_131225_Content_45 = {
    Text = "Pembalasan Nasib, Babak Kedua, Adegan Kedua. Saya menamainya, \"Hujan Lebat\"."
  },
  AvgDialog_131225_Content_46 = {
    Text = "Nikmati mandi di tengah hujan yang indah ini, penontonnya yang terkasih."
  },
  AvgDialog_131225_Content_47 = {
    Text = "Genangan air mulai bergelora, laba-laba hitam mendengarkan perintah tertinggi, mengalir ke setiap sudut kamar."
  },
  AvgDialog_131225_Content_48 = {
    Text = "Dalam pujian Nefraea, penjaga, pelayan yang terbuat dari laba-laba, dan makhluk menjijikkan, mengalir menuju kalian—"
  },
  AvgDialog_131225_Content_5 = {
    Text = "Pengembara dan para pekerja yang lelah berjalan melewati kotak megah ini, tidak ada satu pun yang melirik lebih, seolah-olah ia sudah ada di sini sejak mereka dilahirkan."
  },
  AvgDialog_131225_Content_6 = {
    Text = "Ternyata bahkan nasib kota ini juga terpengaruh... Kekuatan Nefraea, memang semakin meningkat."
  },
  AvgDialog_131225_Content_7 = {
    Text = "Kamu waspada melangkah maju, awalnya ingin mengetuk pintu, tetapi saat tanganmu baru saja diletakkan di atas pintu, pintu itu tiba-tiba terbuka dengan diam-diam."
  },
  AvgDialog_131225_Content_8 = {
    Text = "Tampaknya, pemilik kita yang perhatian telah meninggalkan pintu untuk kita."
  },
  AvgDialog_131225_Content_9 = {Text = "Ini…"},
  AvgDialog_131226_Content_1 = {
    Text = "Bunuh... sudah membunuh!"
  },
  AvgDialog_131226_Content_10 = {
    Text = "Aku melihat semua yang terjadi tadi. Kamu tidak melewati lorong itu, %player%. Tempat ini, bukan tempat yang seharusnya kita tuju."
  },
  AvgDialog_131226_Content_11 = {
    Text = "Saya juga merasa aneh... Pelarutan dan Mythag, bencana-bencana itu, mereka sama sekali tidak tahu."
  },
  AvgDialog_131226_Content_12 = {
    Text = "Tetapi penampilan kota ini, sama persis seperti sebelum bencana itu terjadi, dan seperti yang ada dalam ingatanku. Mungkin, kita sekarang bisa kembali ke sekolah dan melihat, mungkin kita bisa menemukan sesuatu......"
  },
  AvgDialog_131226_Content_13 = {
    Text = "Aku baru saja kembali dari sana. Tidak ada Misage di sini, %player%."
  },
  AvgDialog_131226_Content_14 = {
    Text = "Tidak ada...?"
  },
  AvgDialog_131226_Content_15 = {
    Text = "Peta dunia di dalam toko adalah bentuk yang belum pernah saya lihat, semua tahun yang tercantum di kalender juga sangat berbeda dengan tahun Aluvi."
  },
  AvgDialog_131226_Content_16 = {
    Text = "Hal yang paling aneh adalah……kota ini tidak memiliki ujung."
  },
  AvgDialog_131226_Content_17 = {
    Text = "Tidak ada... akhir?"
  },
  AvgDialog_131226_Content_18 = {
    Text = "Dari arah Mythag yang asli, terus menuju utara, maka kamu akan bisa keluar dari wilayah Londinium."
  },
  AvgDialog_131226_Content_19 = {
    Text = "Saya juga mengalami serangan laba-laba ini di jalan, untuk menghindari mereka, saya melanjutkan perjalanan di jalan itu, tetapi akhirnya... saya kembali ke dekat lokasi Anda, di selatan Londinium."
  },
  AvgDialog_131226_Content_2 = {
    Text = "Kerumunan berteriak dan berlari menjauh. Entah sejak kapan, rambut pirang mencolok itu sudah muncul di sisimu."
  },
  AvgDialog_131226_Content_20 = {
    Text = "Ini bukan Londinium, ini bukan Kadas."
  },
  AvgDialog_131226_Content_21 = {
    Text = "Sepertinya ingatanku tidak salah… Lorong itu, memang benar-benar tertutup sebelum aku masuk…"
  },
  AvgDialog_131226_Content_22 = {
    Text = "Kamu memandang pemandangan yang familiar di luar lorong itu, menghela napas dengan kecewa."
  },
  AvgDialog_131226_Content_23 = {
    Text = "Sebuah tempat yang persis sama dengan Londinium, sebuah kota tanpa batas, laba-laba hitam yang muncul entah dari mana... dan tuan yang mereka sebut-sebut..."
  },
  AvgDialog_131226_Content_24 = {
    Text = "Belum bisa dipastikan sekarang, tapi menurutku, tertutupnya lorong dan kemunculan kita di sini pasti bukan kebetulan. Seseorang sengaja merancang semua ini — tuan dari laba-laba itu."
  },
  AvgDialog_131226_Content_25 = {
    Text = "Sekarang kita belum mengetahui apa pun, kita perlu mengumpulkan informasi terlebih dahulu..."
  },
  AvgDialog_131226_Content_26 = {
    Text = "Dua orang……"
  },
  AvgDialog_131226_Content_27 = {Text = "Siapa?!"},
  AvgDialog_131226_Content_28 = {
    Text = "Cahaya perak berkilau di telapak tangan mekanis William, seperti bilah tajam yang siap meluncur kapan saja."
  },
  AvgDialog_131226_Content_29 = {
    Text = "Di balik cahaya perak yang berbahaya itu, kamu melihat lansia yang baru saja ingin memberikan makanan kepadamu."
  },
  AvgDialog_131226_Content_3 = {
    Text = "Kak William… kapan kamu… apa yang terjadi?"
  },
  AvgDialog_131226_Content_30 = {
    Text = "Iya……ini aku……"
  },
  AvgDialog_131226_Content_31 = {
    Text = "Ini... punya Anda?"
  },
  AvgDialog_131226_Content_32 = {
    Text = "Lansia membuka telapak tangannya. Lencana sekolah Mythag yang digunakan untuk komunikasi, tergeletak diam di telapak tangannya yang kasar."
  },
  AvgDialog_131226_Content_33 = {
    Text = "Aduh! Itu jatuh saat pertempuran tadi..."
  },
  AvgDialog_131226_Content_34 = {
    Text = "Benda ini sangat penting bagiku... Terima kasih banyak!"
  },
  AvgDialog_131226_Content_35 = {
    Text = "Di bawah pandangan waspada William, kamu mengambil kembali lambang sekolah dan menyimpannya dengan serius."
  },
  AvgDialog_131226_Content_36 = {
    Text = "Lansia... Apakah Anda tidak takut dengan apa yang terjadi tadi?"
  },
  AvgDialog_131226_Content_37 = {
    Text = "Ini adalah ketakutan... Aku telah hidup di sini sepanjang hidupku, belum pernah melihat ini sebelumnya..."
  },
  AvgDialog_131226_Content_38 = {
    Text = "Namun, aku melihat bahwa benda itu cukup penting bagimu. Kamu baru saja sampai di sini, jika hilang, mungkin kamu bahkan tidak tahu harus mencarinya ke mana, jadi aku membawanya untukmu."
  },
  AvgDialog_131226_Content_39 = {
    Text = "Sungguh terima kasih banyak…"
  },
  AvgDialog_131226_Content_4 = {
    Text = "Ini bukan tempat untuk berbicara. Ayo"
  },
  AvgDialog_131226_Content_40 = {
    Text = "Kami baru sampai di sini, banyak hal yang tidak kami ketahui, bolehkah kami menanyakan beberapa hal kepada Anda?"
  },
  AvgDialog_131226_Content_41 = {
    Text = "Aku tidak keberatan mengobrol lebih lama dengan dua anak muda, tapi yang aku tahu sangat terbatas, aku khawatir tidak bisa banyak membantu."
  },
  AvgDialog_131226_Content_42 = {
    Text = "Mungkin, kalian sekarang lebih perlu mencari tempat yang ramai."
  },
  AvgDialog_131226_Content_43 = {
    Text = "Baiklah, barang sudah sampai, saya akan pulang dulu."
  },
  AvgDialog_131226_Content_44 = {
    Text = "Orang tua itu melambaikan tangan, tidak menghiraukan permohonan kalian, dan pergi meninggalkan gang kecil."
  },
  AvgDialog_131226_Content_45 = {
    Text = "Lansia ini tampaknya tidak memiliki niat jahat. Dia benar, kita perlu segera mencari tempat yang lebih banyak informasi."
  },
  AvgDialog_131226_Content_46 = {
    Text = "Aku tahu satu tempat yang bisa dituju!"
  },
  AvgDialog_131226_Content_47 = {
    Text = "Jika kota ini persis sama dengan Londinium, tempat itu pasti akan sangat cocok."
  },
  AvgDialog_131226_Content_48 = {
    Text = "Saat kalian pergi, seekor laba-laba berwarna ungu pucat bersembunyi di titik buta pandangan kalian, merayap melalui jaring laba-laba masuk ke celah dinding, dan menghilang dari pandangan."
  },
  AvgDialog_131226_Content_5 = {
    Text = "William menarikmu dan berlari ke arah berlawanan dari kerumunan."
  },
  AvgDialog_131226_Content_7 = {
    Text = "Seharusnya tidak ada orang di sekitar sini."
  },
  AvgDialog_131226_Content_8 = {
    Text = "Apa yang sebenarnya terjadi? Kenapa Londinium bisa menjadi seperti ini..."
  },
  AvgDialog_131226_Content_9 = {
    Text = "Laba-laba yang menyerang kita, dan orang itu... sepertinya ada hubungannya dengan orang yang kita temui di kapal Le Plaisir sebelumnya?"
  },
  AvgDialog_131227_Content_1 = {
    Text = "Tawil! Aku..."
  },
  AvgDialog_131227_Content_2 = {
    Text = "Saya mengerti, Penjaga."
  },
  AvgDialog_131227_Content_3 = {
    Text = "Takdirmu telah diubah. Kau tidak bisa berhenti, dan tidak seharusnya berhenti."
  },
  AvgDialog_131227_Content_4 = {
    Text = "Arachne tidak dapat mengungkapkan nasib masa depan... Tolong beri tahu saya, apa yang harus saya lakukan..."
  },
  AvgDialog_131227_Content_5 = {
    Text = "Saya tidak dapat menjelaskan kepada kamu tentang apa yang ada di balik pintu. Dalam hal ini, ada orang yang lebih cocok untuk membantumu daripada saya."
  },
  AvgDialog_131227_Content_6 = {
    Text = "Majulah, Penjaga. Nasibmu, harus kau lihat sendiri."
  },
  AvgDialog_131228_Content_1 = {
    Text = "Hmm... pahlawan dan badut, boneka tali takdir... sandiwara yang bagus."
  },
  AvgDialog_131228_Content_2 = {
    Text = "Arachne memberitahuku, kunci untuk membuka kunci adalah \"Kesukacitaan\"... ini adalah bidangmu, N."
  },
  AvgDialog_131228_Content_3 = {
    Text = "Shh! Jangan terburu-buru. Menghancurkan sebuah pertunjukan yang baik adalah dosa yang paling tidak dapat dimaafkan di alam semesta ini."
  },
  AvgDialog_131228_Content_4 = {
    Text = "Ayo, Penjaga. Sudah lama tidak bertemu, biarkan aku melihat, apakah kamu memiliki pemahaman baru tentang Kesukacitaan?"
  },
  AvgDialog_131229_Content_10 = {
    Text = "Tanggapi aku… Liz!…"
  },
  AvgDialog_131229_Content_11 = {
    Text = "Nasibnya sudah terputus... HP-nya sudah berakhir."
  },
  AvgDialog_131229_Content_12 = {
    Text = "<Shake:Tidak... kita tidak bisa membiarkan Nefraea menang begitu saja>, dia harus membayar harga untuk semua tindakan sembrunhnya"
  },
  AvgDialog_131229_Content_13 = {
    Text = "Biaya yang akan dibayar, nasib telah menyiapkannya untuknya. Petunjuk tidak akan terputus di sini."
  },
  AvgDialog_131229_Content_14 = {
    Text = "Tapi, kamu baru saja bilang Liz sekarang sudah......"
  },
  AvgDialog_131229_Content_15 = {
    Text = "Kematian adalah bagian dari takdir. Ini adalah panggungku, Penjaga Rahasia {Male=先生,Female=小姐}. Semua takdir adalah benang di tanganku. Arah mereka, <color=#8C7E96>tidak ditenun oleh orang lain</color>."
  },
  AvgDialog_131229_Content_16 = {Text = "!!!"},
  AvgDialog_131229_Content_17 = {
    Text = "<Shake:Tunggu, maksudmu……>"
  },
  AvgDialog_131229_Content_18 = {
    Text = "Wajah Arachne tidak menunjukkan rasa sedih atau bahagia. Dia berjalan menuju pembawa acara yang sempat dijadikan parasit oleh Nefraea. Cahaya senja menggambarkan siluetnya yang samar dan stabil, seperti nasib itu sendiri."
  },
  AvgDialog_131229_Content_19 = {
    Text = "Hehe... hahahaha... Arachne, kamu masih begitu, begitu sombong! Hahahaha..."
  },
  AvgDialog_131229_Content_2 = {
    Text = "Musuh di sekeliling telah jatuh, tetapi seranganmu masih belum berhenti."
  },
  AvgDialog_131229_Content_20 = {
    Text = "Nefraea tampaknya melihat sesuatu yang sangat lucu, tertawa hingga berguling-guling di tanah."
  },
  AvgDialog_131229_Content_21 = {
    Text = "Polusi nasib Liz, biarkan dia menyambut akhir kematian... Setiap hal yang kau lakukan, jaring nasib akan mengingatnya."
  },
  AvgDialog_131229_Content_22 = {
    Text = "Nasib yang salah akan diperbaiki. Di depan takdirmu, pasti ada harga yang menunggu untukmu."
  },
  AvgDialog_131229_Content_23 = {
    Text = "Arachne mengulurkan tangan, perlahan-lahan menggerakkan di atas kepala mayat ini. Roda pemintal di tangannya berputar perlahan, semua yang ada di sekitarmu sepertinya terdistorsi dan disusun ulang dalam putaran ini..."
  },
  AvgDialog_131229_Content_24 = {
    Text = "Benang nasib, dengarkan panggilan jaringan. Ikuti satu-satunya jalan itu, dan naik kembali ke panggung..."
  },
  AvgDialog_131229_Content_25 = {
    Text = "Tubuhnya... menghilang?"
  },
  AvgDialog_131229_Content_26 = {
    Text = "Dengan gerakan jari Arachne, di atas panggung, mayat Liz seolah sedang mengalami pembakaran tanpa suara, berubah menjadi abu sisa yang menghilang di udara."
  },
  AvgDialog_131229_Content_27 = {
    Text = "Di bawah abu yang rontok itu, sebuah tubuh baru muncul di depanmu."
  },
  AvgDialog_131229_Content_28 = {
    Text = "Ini... orang yang mengumumkan?"
  },
  AvgDialog_131229_Content_29 = {
    Text = "Duri menembus tubuh pengumuman, menggantungnya di atas panggung, semua gerakan dan amplitudo, persis sama dengan Liz."
  },
  AvgDialog_131229_Content_3 = {
    Text = "Kamu mengaum, dengan gila menginjak wajah pengumuman yang tersenyum itu hingga hancur di atas papan panggung."
  },
  AvgDialog_131229_Content_30 = {
    Text = "Pembawa acara meninggalkan senyuman menyeramkan, tidak ada suara lagi."
  },
  AvgDialog_131229_Content_31 = {
    Text = "Arachne, kamu......"
  },
  AvgDialog_131229_Content_32 = {
    Text = "Maaf, saya datang terlambat, saya baru saja... ah"
  },
  AvgDialog_131229_Content_33 = {
    Text = "Sosok yang akrab mengangkat tirai dan melangkah ke atas panggung. Pandangannya melintas di antara kalian, berhenti pada mayat yang tergantung di udara."
  },
  AvgDialog_131229_Content_34 = {
    Text = "Gerakannya… sungguh indah…"
  },
  AvgDialog_131229_Content_35 = {
    Text = "Liz sepertinya melupakan mayat-mayat yang berserakan di tanah dan penonton yang berdiri. Dia datang ke tengah panggung, tangannya melintasi di atas kaki mayat yang tergantung, seolah-olah sedang meresapi busur yang anggun itu."
  },
  AvgDialog_131229_Content_36 = {
    Text = "Arachne, kamu... telah menukar nasib Pembawa Acara dan Liz?"
  },
  AvgDialog_131229_Content_37 = {
    Text = "Tapi kamu pernah bilang, konsumsi seperti ini sulit untuk ditanggung..."
  },
  AvgDialog_131229_Content_38 = {
    Text = "Konsumsi tidak ada hubungannya dengan pilihan. Dalam nasib saya, ini juga merupakan harga yang harus saya bayar."
  },
  AvgDialog_131229_Content_39 = {
    Text = "Pergilah, %player%, jangan buat Nona Liz menunggu terlalu lama."
  },
  AvgDialog_131229_Content_4 = {
    Text = "Benar...... begitu...... marah, meluapkan! Betapa menawannya ekspresi ini......"
  },
  AvgDialog_131229_Content_40 = {
    Text = "Mata yang ethereal dan napas. Rok yang melayang dengan nyala api hijau yang halus. Setiap getaran di ujung jari seperti tarian yang diatur dengan cermat."
  },
  AvgDialog_131229_Content_41 = {
    Text = "Sosoknya tumpang tindih dengan bayangan berlumuran darah yang tadi menerjang ke arahmu. Liz berdiri hidup-hidup di hadapanmu, tenunan takdir yang begitu halus tidak meninggalkan sedikit pun jejak dalam hidupnya."
  },
  AvgDialog_131229_Content_42 = {
    Text = "Setelah lama, Liz kembali sadar dari pengamatannya terhadap mayat, dan menoleh untuk melihatmu yang berdiri di sampingnya."
  },
  AvgDialog_131229_Content_43 = {
    Text = "Saya tertidur di rumah sampai sore ini, melewatkan pertunjukan. Ini adalah situasi yang belum pernah terjadi sebelumnya…"
  },
  AvgDialog_131229_Content_44 = {
    Text = "Sepertinya, saya telah melewatkan beberapa hal yang sangat penting?"
  },
  AvgDialog_131229_Content_45 = {
    Text = "Mata Liz melirik ke mayat dan darah yang diabaikannya di tanah."
  },
  AvgDialog_131229_Content_46 = {
    Text = "Tidak, kamu tidak melewatkan apapun, Liz."
  },
  AvgDialog_131229_Content_47 = {
    Text = "Kamu... baik-baik saja? Apakah ada yang tidak nyaman di tubuhmu?"
  },
  AvgDialog_131229_Content_48 = {
    Text = "Tidak juga…… {Male=先生,Female=小姐}, apakah kita saling kenal? Sepertinya aku merasakan sesuatu yang sangat familiar dari diri Anda……"
  },
  AvgDialog_131229_Content_49 = {
    Text = "Mungkin karena, sebagai pengikutmu, aku telah melihat banyak pertunjukanmu."
  },
  AvgDialog_131229_Content_5 = {
    Text = "Wajahnya yang seperti lumpur tersenyum, suara lembut keluar dari tenggorokannya yang pecah."
  },
  AvgDialog_131229_Content_50 = {
    Text = "Kamu tersenyum dan memandangnya. Panggung ini memiliki cerita yang menjadi miliknya, dan kamu tidak berniat untuk menceritakan hal-hal lama itu padanya."
  },
  AvgDialog_131229_Content_51 = {
    Text = "Kami datang untuk\"Kebaikan\"."
  },
  AvgDialog_131229_Content_52 = {
    Text = "Teman Nyonya Sorel akhirnya datang, aku khawatir jika aku pergi tampil, akan mengabaikan orang yang \"baik hati\" itu... Silakan kalian berdua mengikuti saya, tempat tinggalku tidak jauh dari kelompok tari."
  },
  AvgDialog_131229_Content_53 = {
    Text = "Liz menatap mayat di dinding dengan sedikit enggan, lalu membawa kalian berjalan ke balik tirai."
  },
  AvgDialog_131229_Content_55 = {
    Text = "Jadi... seharusnya mayatku yang digantung di panggung..."
  },
  AvgDialog_131229_Content_56 = {
    Text = "Tidak sempat meratapi pasangan tari yang telah tiada, juga lupa mengungkapkan terima kasih kepada orang yang membuatnya hidup kembali."
  },
  AvgDialog_131229_Content_57 = {
    Text = "Dalam ceritamu, mata Liz berkilau seperti nyala api yang melompat. Dia mengulurkan tangannya, membentuk pose yang sama dengan mayat itu."
  },
  AvgDialog_131229_Content_58 = {
    Text = "Apakah pemandangan itu indah?"
  },
  AvgDialog_131229_Content_59 = {
    Text = "Keindahan tertinggi di dunia hanya muncul pada dua momen, satu adalah kelahiran, satu lagi adalah kematian. Itu adalah pemandangan yang tak tertandingi, Nona Liz."
  },
  AvgDialog_131229_Content_6 = {
    Text = "Nefraea tidak ada di sini, ini hanyalah ilusi yang ditinggalkannya. Jangan terjebak dalam kemarahan, Penjaga {Male=Tuanku, Female=Nyonyaku}."
  },
  AvgDialog_131229_Content_60 = {
    Text = "Terima kasih, Nyonya Arachne. Anda adalah penenun nasib, jadi saya rasa, Anda pasti sering dikelilingi oleh keindahan ini. Ini benar-benar... sangat mengagumkan."
  },
  AvgDialog_131229_Content_61 = {
    Text = "Terlalu banyak harta, akan menjadi sebuah hukuman."
  },
  AvgDialog_131229_Content_62 = {
    Text = "Jika ini adalah hukuman Anda, apa berkat yang Anda minta?"
  },
  AvgDialog_131229_Content_63 = {
    Text = "Liz tidak menyadari jeda singkat Arachne, dan membuka pintu kamar tamu di halaman."
  },
  AvgDialog_131229_Content_64 = {
    Text = "Ini adalah tempat tinggal sementara Tuan \"Baik Hati\". Tuan \"Baik Hati\", teman Anda telah datang menjemput Anda."
  },
  AvgDialog_131229_Content_65 = {
    Text = "\"Baik Hati\"Tuan?"
  },
  AvgDialog_131229_Content_66 = {
    Text = "Kamar yang sederhana, tanpa satu pun perabot yang tidak berasal dari sini, tanpa satu pun orang yang tidak berasal dari sini."
  },
  AvgDialog_131229_Content_67 = {
    Text = "Di dalam ruangan yang kosong, selembar kertas sederhana tergeletak diam di atas lemari buku."
  },
  AvgDialog_131229_Content_68 = {
    Text = "\"Maaf karena pergi tanpa pamit. Nyonya Sorel khawatir Anda terlibat, jadi ada pengaturan baru, saya akan pergi ke vila kenangan untuk bersembunyi.\""
  },
  AvgDialog_131229_Content_69 = {
    Text = "\"Saya sangat berterima kasih atas perhatian Anda. Saya akan dengan serius membalas budi ini kepada Anda.\""
  },
  AvgDialog_131229_Content_7 = {
    Text = "<Shake:Ugh…… ugh……>"
  },
  AvgDialog_131229_Content_70 = {
    Text = "Jika Nyonya Sorel mengubah rencana, dia pasti akan memberi tahu kami…"
  },
  AvgDialog_131229_Content_71 = {
    Text = "Kamu menatap mata Arachne yang tidak berombak. Dalam senyuman tenang yang seolah tidak akan pernah menghilang itu, kamu melihat bayangan yang melintas dengan cepat."
  },
  AvgDialog_131229_Content_72 = {
    Text = "\"Kenangan\" adalah seorang pengembara. Dia tidak memiliki rumah."
  },
  AvgDialog_131229_Content_73 = {
    Text = "Apa?!!! Itu..."
  },
  AvgDialog_131229_Content_74 = {
    Text = "Nasib \"Kenangan\", mungkin juga telah dirusak oleh Nefraea. Keduanya sekarang terjebak dalam bahaya."
  },
  AvgDialog_131229_Content_75 = {
    Text = "Maaf, saya tidak menyangka…"
  },
  AvgDialog_131229_Content_76 = {
    Text = "Ini bukan tanggung jawabmu, Nona Liz."
  },
  AvgDialog_131229_Content_77 = {
    Text = "Nefraea dapat mengubah nasibmu, sehingga menemukan orang-orang di sekitarmu bukanlah hal yang sulit. Ini adalah masalah yang perlu kita selesaikan."
  },
  AvgDialog_131229_Content_78 = {
    Text = "Noda di atas belum sepenuhnya kering, waktu Nefraea untuk bertindak tidak jauh lagi, kita harus segera mungkin masih ada waktu untuk..."
  },
  AvgDialog_131229_Content_79 = {
    Text = "Liz, ada beberapa hal yang tidak sempat diucapkan kali ini…"
  },
  AvgDialog_131229_Content_8 = {
    Text = "Ketika wajah yang tersenyum itu tidak lagi dapat dikenali sedikit pun, akhirnya kamu berhenti."
  },
  AvgDialog_131229_Content_80 = {
    Text = "Pasti akan ada kesempatan, Penjaga Rahasia {Male=先生,Female=小姐}. Semoga saat kita bertemu lagi nanti, tarian baru itu masih bisa menyentuh hati Anda."
  },
  AvgDialog_131229_Content_81 = {
    Text = "SetelahPerpisahan dengan senyuman sederhana, Liz tidak lagi peduli dengan cerita rumit kalian."
  },
  AvgDialog_131229_Content_82 = {
    Text = "Dia mengangkat lengannya, membentuk busur yang sama dengan mayat itu, mencoba menghidupkan kembali gerakan tari yang terus terbayang dalam pikirannya."
  },
  AvgDialog_131229_Content_83 = {
    Text = "Angin sepoi-sepoi menggerakkan rok dia, seperti angsa yang sedang terbang."
  },
  AvgDialog_131229_Content_9 = {
    Text = "Mayat Liz yang dikendalikan telah kehilangan semua vitalitas. Kamu meletakkan mayatnya yang berlumuran darah dengan lembut di atas lantai, dan membuka saluran mental yang terhubung dengannya."
  },
  AvgDialog_131230_Content_1 = {
    Text = "Tirai Turun"
  },
  AvgDialog_131230_Content_10 = {
    Text = "Karena kota ini telah diciptakan kembali... aku mengira, kau akan membawa kembali hal-hal yang telah menghilang ke sini."
  },
  AvgDialog_131230_Content_11 = {
    Text = "…Kamu merindukannya, bukan?"
  },
  AvgDialog_131230_Content_12 = {
    Text = "Daripada secangkir kopi, saya lebih ingin melihat bagaimana panggung itu tampil sendiri."
  },
  AvgDialog_131230_Content_13 = {
    Text = "Saya telah menciptakan kembali tempat ini dengan ingatan, tetapi saya tetap tidak bisa mengubah fakta bahwa ini adalah panggung yang sepenuhnya baru."
  },
  AvgDialog_131230_Content_14 = {
    Text = "Kopi baru di sini juga memiliki rasa yang unik, bukan?"
  },
  AvgDialog_131230_Content_15 = {
    Text = "Arachne tersenyum, perlahan-lahan meneguk cairan pahit itu."
  },
  AvgDialog_131230_Content_16 = {
    Text = "Nefraea... bagaimana akhirnya?"
  },
  AvgDialog_131230_Content_17 = {
    Text = "Benang-benang takdir kalian tersambung kembali, apakah itu berarti…… kalian sekarang menjadi satu orang lagi?"
  },
  AvgDialog_131230_Content_18 = {
    Text = "Barang-barang yang pernah menjadi milik Nefraea, kualitasnya, sifat aslinya, telah kembali ke nasibku. Atau bisa dibilang, seperti yang Anda ketahui—mereka tidak pernah pergi."
  },
  AvgDialog_131230_Content_19 = {
    Text = "Tetapi Jaring Takdir adalah satu-satunya. Orang itu yang Anda kenal, Nefraea, orang yang terjebak di Jurang dan ditinggalkan oleh nasib, tidak memiliki benang yang menjadi miliknya dalam jaring ini."
  },
  AvgDialog_131230_Content_2 = {
    Text = [[
Lascia ch'io pianga Biarkan aku menangis!
mia cruda sorte, Takdir yang kejam.]]
  },
  AvgDialog_131230_Content_20 = {
    Text = "Dia…… telah lenyap sepenuhnya, Penjaga Rahasia{Male=先生,Female=小姐}."
  },
  AvgDialog_131230_Content_21 = {
    Text = "Roda pemintal berputar perlahan, tanpa henti. Arachne menutup mata, mengangkat kepala dengan lembut, mencium aroma bunga yang tipis di angin."
  },
  AvgDialog_131230_Content_22 = {
    Text = "Nasib yang terbuang, yang dihadapi hanya penjara abadi dan penghapusan total. Sungguh hal yang kejam…"
  },
  AvgDialog_131230_Content_23 = {
    Text = "Setiap saat, takdir harus membuat pilihan. Yang benar akan tetap tinggal, yang salah akan dibuang……"
  },
  AvgDialog_131230_Content_24 = {
    Text = "Sebelum kita menemukan jalan yang sesungguhnya, hal ini tak terhindarkan, sama seperti keruntuhan alam semesta ini."
  },
  AvgDialog_131230_Content_25 = {
    Text = "Penjaga Rahasia{Male=先生,Female=小姐}, jika Anda memiliki kemampuan untuk mengendalikan takdir, akankah Anda membiarkannya menuju kekacauan, atau membuat pilihan untuk mereka, meskipun itu akan membuat Anda menanggung tuduhan sebagai pembunuh?"
  },
  AvgDialog_131230_Content_26 = {
    Text = "Ini... aku..."
  },
  AvgDialog_131230_Content_27 = {
    Text = "Ini hanyalah topik debat untuk menghibur Anda, bukan pertanyaan yang harus Anda jawab. Anda sudah menanggung terlalu banyak hal, beban ini tidak perlu Anda pikul lagi."
  },
  AvgDialog_131230_Content_28 = {
    Text = "Arachne tersenyum sambil menggelengkan kepala."
  },
  AvgDialog_131230_Content_29 = {
    Text = "Memilih adalah sebuah kekuasaan, banyak orang meskipun memilikinya, tetap memilih untuk melepaskannya. Karena saat membuat pilihan, itu juga berarti menanggung konsekuensinya."
  },
  AvgDialog_131230_Content_3 = {
    Text = "E che sospiri la libertà! \nBetapa aku mendambakan, datangnya kebebasan!"
  },
  AvgDialog_131230_Content_30 = {
    Text = "Anda tahu, itu bukanlah hal yang mudah, Penjaga Rahasia{Male=先生,Female=小姐}."
  },
  AvgDialog_131230_Content_31 = {
    Text = "Aku adalah pengendali takdir, segala konsekuensi dari takdir akan aku tanggung sendiri."
  },
  AvgDialog_131230_Content_32 = {
    Text = "Ini adalah kata-kata yang diberikan-Nya kepadaku ketika aku pertama kali mengetuk pintu Chokmah-Da'at. Untuk itu, aku menerimanya dengan penuh suka cita."
  },
  AvgDialog_131230_Content_33 = {
    Text = "Jadi kamu... meskipun tidak bisa melihat nasibmu sendiri, tetapi semua ini, apa yang terjadi sekarang... sebenarnya kamu sudah tahu."
  },
  AvgDialog_131230_Content_34 = {
    Text = "Sinar matahari yang hangat menyinari jalan ini, tetapi melihat wajah tenang Arachne, membayangkan apa yang dihadapi orang ini setiap hari, bahkan kamu pun tidak bisa menahan menggigil."
  },
  AvgDialog_131230_Content_35 = {
    Text = "Romantis membawa kebodohan, kebaikan membawa kerapuhan, kenangan membawa rasa sakit…"
  },
  AvgDialog_131230_Content_36 = {
    Text = "Meskipun sudah lama bersiap menghadapi semua ini, kau tidak pernah benar-benar membuangnya…… mengapa?"
  },
  AvgDialog_131230_Content_37 = {
    Text = "Bagi kamu, menyerah pada mereka seharusnya akan membuat hidupmu lebih mudah."
  },
  AvgDialog_131230_Content_38 = {
    Text = "Apakah Anda pernah ke penjara? Para tahanan yang telah terkurung bertahun-tahun di penjara selalu membawa beberapa barang yang mereka hargai."
  },
  AvgDialog_131230_Content_39 = {
    Text = "Sebuah medali yang dimenangkan dari berkelahi, sebuah jam tangan warisan keluarga, selembar foto bersama keluarga……"
  },
  AvgDialog_131230_Content_4 = {
    Text = "Suara nyanyian yang merdu bergema di jalan, melayang lembut mengikuti angin yang hangat. Para pejalan kaki di jalan berhenti atau berjalan sambil menikmati kehidupan tenang mereka di bawah sinar musim semi ini."
  },
  AvgDialog_131230_Content_40 = {
    Text = "Bagi para tahanan, hasrat yang menyiksa mereka ini adalah motivasi untuk terus hidup."
  },
  AvgDialog_131230_Content_41 = {
    Text = "Mereka dengan hati-hati mempertahankan barang-barang yang paling berharga ini, hingga saat-saat mendekati kematian, menyerahkan satu per satu benda-benda yang tidak berharga itu."
  },
  AvgDialog_131230_Content_42 = {
    Text = "……Di dalam sangkar takdir, kita semua tidak memiliki apa-apa, Penjaga Rahasia{Male=先生,Female=小姐}."
  },
  AvgDialog_131230_Content_43 = {
    Text = [[
Il duolo infranga Penderitaan dunia,
queste ritorte tiada habisnya.]]
  },
  AvgDialog_131230_Content_44 = {
    Text = "de miei martiri Atas kesakitan seperti ini,\nsol per pietà tak ada yang mengasihani."
  },
  AvgDialog_131230_Content_45 = {
    Text = "Penyanyi opera di tepi jalan bernyanyi tentang sungai nasib yang mengalir di kota ini. Arachne menyeruput kopi, mendengarkan dengan serius. Dari awal hingga akhir, sudut senyumnya tidak pernah berubah."
  },
  AvgDialog_131230_Content_46 = {
    Text = "Tahukah Anda, Penjaga Rahasia{Male=先生,Female=小姐}, saya sering memimpikan pemandangan yang sama berulang kali."
  },
  AvgDialog_131230_Content_47 = {
    Text = "Itu adalah sebuah teater yang indah, hanya ada aku dan Nefraea. Tepat di dalam lagu yang indah ini, aku mengantarnya pergi."
  },
  AvgDialog_131230_Content_48 = {
    Text = "Anda lihat, meskipun kita tidak dapat melihat nasib kita sendiri, pengadilannya ada di mana-mana."
  },
  AvgDialog_131230_Content_49 = {
    Text = "E che sospiri la libertà! Betapa aku mendambakan!\nE che sospiri la libertà! Betapa aku mendambakan!"
  },
  AvgDialog_131230_Content_5 = {
    Text = "Kamu mengangkat kopi dan meminumnya dengan satu tegukan besar."
  },
  AvgDialog_131230_Content_50 = {
    Text = "Suara penyanyi opera tak pernah berhenti, benang dari roda pemintal berputar selamanya. Arachne meletakkan cangkir di tangannya, dengan tulus bertepuk tangan lembut bersama penonton yang berhenti."
  },
  AvgDialog_131230_Content_51 = {
    Text = "Bagaimanapun, sebuah pertunjukan telah berakhir, panggung ini akan menyambut istirahat singkatnya. Kami para aktor, juga akan segera menuju panggung berikutnya."
  },
  AvgDialog_131230_Content_52 = {
    Text = "Pengaruh Nefraea sudah hilang, sekarang seharusnya bisa membuka kembali jalur koneksi dengan Kadas?"
  },
  AvgDialog_131230_Content_53 = {
    Text = "Lorong yang menghubungkan Kadas ada dalam nasib dunia ini. Upaya melintasi dimensi, kamu juga sudah mencobanya."
  },
  AvgDialog_131230_Content_54 = {
    Text = "Bahaya di dalamnya, kamu juga sudah mengetahuinya."
  },
  AvgDialog_131230_Content_55 = {
    Text = "Memang... pandangan-pandangan Tuhuwa Bo itu, saya tidak ingin menghadapi sekali lagi..."
  },
  AvgDialog_131230_Content_56 = {
    Text = "Arachne, kamu bisa mengendalikan nasib dunia ini, mungkin kamu punya cara untuk membantuku?"
  },
  AvgDialog_131230_Content_57 = {
    Text = "Saya sangat senang untuk melayani, namun, di dunia ini, hanya kota ini yang merupakan panggung saya. Penguasa takdir dunia ini, bukanlah saya."
  },
  AvgDialog_131230_Content_58 = {
    Text = "Ternyata!……"
  },
  AvgDialog_131230_Content_59 = {
    Text = "Penguasa dunia ini, memiliki kemampuan yang bahkan aku pun tak mampu menandingi. Dunia ini, ada karena kehendak-Nya."
  },
  AvgDialog_131230_Content_6 = {
    Text = "Jauh lebih buruk dibanding kopi Khvartz."
  },
  AvgDialog_131230_Content_60 = {
    Text = "Kecuali jika saluran dibuka secara sengaja, tempat ini akan menjadi tempat yang bahkan pandangan dewa tertinggi pun tak dapat menjangkaunya…… dan itulah alasan mengapa aku berlindung di sini."
  },
  AvgDialog_131230_Content_61 = {
    Text = "Apa... jika saya membuka saluran, akan ada bahaya di sini?"
  },
  AvgDialog_131230_Content_62 = {
    Text = "Seperti yang saya katakan, nasib memiliki trajektorinya sendiri. Tinggal di sini, hanya menunggu kematian dengan lambat. Membantu kamu kembali ke Kadas juga merupakan harapan pemilik dunia ini."
  },
  AvgDialog_131230_Content_63 = {
    Text = "Demi titik cahaya di ujung takdir, ini adalah risiko yang sepenuhnya rela kami tanggung."
  },
  AvgDialog_131230_Content_64 = {
    Text = "Begitu rupanya… Aku mengerti sekarang."
  },
  AvgDialog_131230_Content_65 = {
    Text = "Di mana aku bisa menemukannya?"
  },
  AvgDialog_131230_Content_66 = {
    Text = "Benang takdir-Nya luas seperti lautan bintang, namun sehalus debu. Hanya bergantung pada penangkapan takdir, aku tidak bisa langsung menunjukkan posisinya padamu."
  },
  AvgDialog_131230_Content_67 = {
    Text = "Namun mungkin, ini bisa membantumu."
  },
  AvgDialog_131230_Content_68 = {
    Text = "Arachne menyerahkan selembar pamflet kepadamu. Kamu mengernyitkan dahi, melihat huruf-huruf indah yang penuh dengan nuansa religius di atasnya."
  },
  AvgDialog_131230_Content_69 = {
    Text = "Pengumuman Lowongan Kerja:"
  },
  AvgDialog_131230_Content_7 = {
    Text = "Setelah terakhir kali pergi ke panggung itu untuk mencicipi, aku juga merasa rasanya sangat enak. Sayangnya, di panggung ini, keluarga yang menciptakan kopi itu sudah punah sejak lama."
  },
  AvgDialog_131230_Content_70 = {
    Text = "Pemimpin Agung, Orang yang Dipilih oleh dewa, Eksekutor Tuhan Yang Maha Tinggi, ahli waris sah dari sekte yang megah, Penyelamat dari penderitaan, dan Teman dekat Sang Raja telah tiba di Benua Utara, saat ini sekte sedang berkembang pesat, para percaya dapat segera datang untuk bertemu."
  },
  AvgDialog_131230_Content_71 = {
    Text = "Dua belas pengikut pertama yang tiba akan diangkat sebagai santo, selamanya mengikuti peri, dan dilindungi oleh dewa selamanya…"
  },
  AvgDialog_131230_Content_72 = {
    Text = "Ini... apa ini?"
  },
  AvgDialog_131230_Content_73 = {
    Text = "Seperti yang Anda lihat, ini adalah brosur promosi yang dibuat dengan hati-hati."
  },
  AvgDialog_131230_Content_74 = {
    Text = "Mengapa konten di atas begitu aneh... Arachne, kamu bisa melihat arah nasib, apakah kamu yakin ini bukan sebuah penipuan?"
  },
  AvgDialog_131230_Content_75 = {
    Text = "Di benang itu, aku melihat sosokmu. Aku sangat yakin, itu adalah nasib yang akan kau sambut."
  },
  AvgDialog_131230_Content_76 = {
    Text = "Apakah itu bantuan atau bahaya, aku tidak tahu. Tapi aku tahu, antara kamu dan orang itu yang menguasai dunia, ini adalah satu-satunya tautan."
  },
  AvgDialog_131230_Content_77 = {
    Text = "Tangan Arachne menjulur ke atas pamflet yang konyol itu, mengambil sesuatu yang tidak terlihat olehmu, dan meletakkannya di telapak tanganmu."
  },
  AvgDialog_131230_Content_78 = {
    Text = "Ini lagi?..."
  },
  AvgDialog_131230_Content_79 = {
    Text = "Tak lama kemudian, seuntai benang samar memantulkan kilau redup di tanganmu."
  },
  AvgDialog_131230_Content_8 = {
    Text = "Kamu memandang kota ini. Persimpangan Brick, toko buku tua yang berlipat waktu, toko kelontong pasar yang harum……"
  },
  AvgDialog_131230_Content_80 = {
    Text = "Ini adalah kesempatan yang menghubungkanmu dengan takdir itu. Ia akan menuntunmu, menuju tempat yang seharusnya kau tuju."
  },
  AvgDialog_131230_Content_81 = {
    Text = "Aku mengerti. Begitu luka Senior William sembuh, kami akan segera……"
  },
  AvgDialog_131230_Content_82 = {
    Text = "Dalam sekilas pengintipan singkat saya terhadap benang takdir Anda, Anda akan menemui sebuah kisah yang menarik."
  },
  AvgDialog_131230_Content_83 = {
    Text = "Saya tidak mampu melihat akhir dari kisah Anda, dan itu adalah sebuah keberuntungan — terhadap takdir Anda, saya masih memiliki kehormatan sebagai penonton."
  },
  AvgDialog_131230_Content_84 = {
    Text = "Saya rasa, tidak ada satu pun kisah yang pantas untuk disia-siakan… Jadi, tolong jangan terburu-buru. Mari kita dengarkan opera ini sampai selesai, Penjaga Rahasia {Male=先生,Female=小姐}."
  },
  AvgDialog_131230_Content_85 = {
    Text = "Suara penyanyi opera kembali melintasi jalanan. Arachne menutup mata, sinar matahari jatuh di wajahnya yang tenang, hangat seperti musim semi yang telah ia hilangkan."
  },
  AvgDialog_131230_Content_86 = {
    Text = "Roda pintal berputar, nyanyian tak henti. Orang-orang berlalu-lalang, ribuan benang yang tak dapat kaulihat berkumpul dan terjalin di sekelilingnya."
  },
  AvgDialog_131230_Content_87 = {
    Text = "Kamu menatap wajah Arachne yang tersenyum. Kamu melihat, di sampingnya tidak ada apa-apa."
  },
  AvgDialog_131230_Content_9 = {
    Text = "Semuanya sepertinya tidak berubah, bahkan bercak karat yang pudar di papan nama toko itu juga persis seperti yang ada dalam ingatanmu."
  },
  AvgDialog_131231_Content_1 = {
    Text = "Huh... untung bisa tepat waktu..."
  },
  AvgDialog_131231_Content_10 = {
    Text = "Sorel sedikit menyipitkan mata memandang Arachne. Dia menemukan bahwa kemampuan membaca orang yang dia banggakan sama sekali tidak berfungsi. Dia tidak bisa melihat masa lalu orang di depannya, dan tidak bisa menebak keinginannya."
  },
  AvgDialog_131231_Content_11 = {
    Text = "Segala detail wajah yang dia ingat dengan cepat, semuanya terlupakan dalam sekejap mata. Sudut bibir Sorel terangkat dengan penuh arti."
  },
  AvgDialog_131231_Content_12 = {
    Text = "Dua tamu yang memikat. Salon ini pasti akan menjadi pengalaman yang tak terlupakan seumur hidupku. Silakan duduk."
  },
  AvgDialog_131231_Content_13 = {
    Text = "Sorel berbalik dan duduk di sofa, mengangkat tangannya memberi isyarat kepada kalian."
  },
  AvgDialog_131231_Content_14 = {
    Text = "Aku telah beberapa kali berhubungan dengan\"kebaikan\", dia datang mencariku, mencari perlindunganku."
  },
  AvgDialog_131231_Content_15 = {
    Text = "Kalian telah menyelamatkanku. Aku tidak bisa melihat kalian dengan jelas, tetapi aku bisa melihat bahwa kalian tidak memiliki niat jahat."
  },
  AvgDialog_131231_Content_16 = {
    Text = "Benar, Nyonya Sorel. Kami datang untuk menyelamatkannya."
  },
  AvgDialog_131231_Content_17 = {
    Text = "Dia tidak berada di dalam perkebunan ini."
  },
  AvgDialog_131231_Content_18 = {
    Text = "Tapi kamu baru saja bilang..."
  },
  AvgDialog_131231_Content_19 = {
    Text = "Seperti yang kamu lihat, ladangku juga tidak aman."
  },
  AvgDialog_131231_Content_2 = {
    Text = "Setelah memastikan kondisi Karen, kamu bangkit dan mengusap keringat dingin di dahimu."
  },
  AvgDialog_131231_Content_20 = {
    Text = "Sorel mengangkat lengannya, menatap mayat-mayat yang berantakan di dalam kamar yang indah dan rapi seolah-olah memamerkan barang koleksi yang berharga."
  },
  AvgDialog_131231_Content_21 = {
    Text = "Itu adalah seorang pria yang baik hati tetapi tidak bodoh. Saya bisa melihat bahwa situasinya sangat kritis."
  },
  AvgDialog_131231_Content_22 = {
    Text = "Hubunganku dengannya, banyak orang yang tahu. Menyembunyikannya di dalam mansion bukanlah keputusan yang bijaksana."
  },
  AvgDialog_131231_Content_23 = {
    Text = "Bolehkah saya tahu dia sekarang di mana?"
  },
  AvgDialog_131231_Content_24 = {
    Text = "Soreil berdiri dan menghampiri sebuah lukisan. Kamu ikut berdiri dan melihat jelas gambar di atasnya."
  },
  AvgDialog_131231_Content_25 = {
    Text = "Itu adalah…!"
  },
  AvgDialog_131231_Content_26 = {
    Text = "Beberapa tahun yang lalu, saya pernah menonton pertunjukan kelompok tari angsa di Teater Londinium. Itu awalnya hanya sebuah acara biasa, tetapi saya sangat terkesan oleh gerakan tariannya."
  },
  AvgDialog_131231_Content_27 = {
    Text = "Dalam beberapa tahun ini, saya kadang-kadang mengunjungi belakang panggung saat diundang untuk pertunjukan kelompok tari. Kami tidak memiliki hubungan yang nyata, dan karena itu, kelompok tari tempat dia berada adalah tempat yang paling cocok untuk menempatkan orang \"baik\" itu."
  },
  AvgDialog_131231_Content_28 = {
    Text = "Di lukisan di hadapanmu, Liz mengenakan gaun tari yang anggun, melompat tinggi di udara, bagaikan angsa yang terbang melayang."
  },
  AvgDialog_131231_Content_29 = {
    Text = "Liz…… kelompok tari dia, sekarang di mana?"
  },
  AvgDialog_131231_Content_3 = {
    Text = "Karen seharusnya baik-baik saja, dia terkena sedikit dampak, setelah beristirahat sejenak seharusnya akan membaik."
  },
  AvgDialog_131231_Content_30 = {
    Text = "Mengikuti benang takdir yang semakin jelas, Arachne memandang ke luar jendela, tempat yang terhubung dengan benang itu, tersembunyi di balik hutan lebat."
  },
  AvgDialog_131231_Content_31 = {
    Text = "Di suatu tempat yang sangat kamu kenal."
  },
  AvgDialog_131231_Content_4 = {
    Text = "Aku bisa dengan jelas mengingat setiap wajah yang pernah kutemui, tetapi perasaan yang kamu berikan padaku sangat aneh. Aku tidak bisa memastikan apakah aku pernah melihatmu... ini belum pernah terjadi padaku sebelumnya."
  },
  AvgDialog_131231_Content_5 = {
    Text = "Sorel mengambil botol anggur yang belum terbalik di meja teh dan menuangkannya ke dalam gelas, melangkahi mayat-mayat yang sedang meleleh di seluruh ruangan, lalu mengulurkan gelas ke depan kalian."
  },
  AvgDialog_131231_Content_6 = {
    Text = "Porto yang sudah berumur empat puluh tahun, koleksi pribadi saya, tidak layak dicicipi oleh para hyena di bawah. Siapa pun kalian dan mengapa kalian ada di sini, saya rasa, segelas anggur ini seharusnya milik kalian."
  },
  AvgDialog_131231_Content_7 = {
    Text = "Kami datang untuk \"kebaikan\", Nyonya Sorel."
  },
  AvgDialog_131231_Content_8 = {
    Text = "Arachne menerima gelas anggur, tersenyum dan menganggukkan kepala sebagai penghormatan kepada Sorel."
  },
  AvgDialog_131231_Content_9 = {
    Text = "Tanpa membuka mulut, dia seperti jaring laba-laba di bawah cahaya pagi, sama sekali tidak menarik perhatian. Setelah dia mulai berbicara, semua cahaya di dalam kamar seolah berkumpul di sekelilingnya."
  },
  AvgDialog_131232_Content_1 = {
    Text = "Betapa hebatnya pertarungan ini, Kakak."
  },
  AvgDialog_131232_Content_10 = {
    Text = "Kau dan pelayanmu adalah orang-orang yang kehilangan nasib. Benang nasib kalian tidak dapat aku tangkap. Namun, kemampuanmu berasal dariku, aku tidak bisa melihat nasibku sendiri, begitu pula kamu."
  },
  AvgDialog_131232_Content_11 = {
    Text = "Kamu dan aku... ini adalah perang sia-sia yang pasti akan terhenti. Seharusnya ini tidak terjadi."
  },
  AvgDialog_131232_Content_12 = {
    Text = "Tentu saja, tentu saja. Bagi kamu, hal-hal yang telah ditinggalkan seperti kami seharusnya lenyap di kuburan takdir, terurai, lenyap, dan menghilang di sini, hingga selamanya, selamanya."
  },
  AvgDialog_131232_Content_13 = {
    Text = "Sayang sekali, kau tidak bisa melihat-Nya... Meskipun kau memiliki Kekuatan yang sangat besar, bagaimana mungkin bisa dibandingkan dengan Orang itu, Tuhan yang Maha Tinggi?"
  },
  AvgDialog_131232_Content_14 = {
    Text = "Kamu tahu. Kamu jelas tahu, semua ini sia-sia. Tapi kamu tidak bisa berhenti menjalin jaring..."
  },
  AvgDialog_131232_Content_15 = {
    Text = "Karena kamu sudah melihatnya, kamu tidak bisa menahan garis-garis yang berantakan itu. Karena kamu memiliki kemampuan seperti itu, kamu tidak bisa membiarkan dunia terjebak dalam kekacauan yang tiada akhir."
  },
  AvgDialog_131232_Content_16 = {
    Text = "Kamu membawa kedamaian yang palsu bagi mereka, dan juga membawa mereka ke jalan yang pada akhirnya akan mengarah pada kehancuran."
  },
  AvgDialog_131232_Content_17 = {
    Text = "Sungguh orang yang menyedihkan, Arachne."
  },
  AvgDialog_131232_Content_18 = {
    Text = "Ini adalah takdir kita, Nefraea."
  },
  AvgDialog_131232_Content_19 = {
    Text = "Ah... sepertinya aku sedikit mengantuk. Berdebat dengan orang bodoh adalah hal yang paling membosankan di dunia ini."
  },
  AvgDialog_131232_Content_2 = {
    Text = "Bar yang ramai tiba-tiba menjadi sepi, tubuh-tubuh yang tergeletak di tanah berubah menjadi cairan hitam dan serbuk, menghilang di bawah cahaya lembut."
  },
  AvgDialog_131232_Content_20 = {
    Text = "Selamat datang di babak kedua cerita ini. Ini adalah panggungmu, tetapi mulai sekarang, cerita ini akan ditulis olehku."
  },
  AvgDialog_131232_Content_21 = {
    Text = "Bagian pembukaan sangat penting, bukan? Apa nama yang sebaiknya dipilih... Ah, sebut saja \"Reuni\", bagaimana?"
  },
  AvgDialog_131232_Content_22 = {
    Text = "Nefraea sangat puas dengan namanya, mencelupkan anggota tubuhnya ke dalam anggur tua di dalam gelas dan memasukkannya ke mulutnya, mengeluarkan sebuah desahan terpesona."
  },
  AvgDialog_131232_Content_23 = {
    Text = "Untuk hari ini, aku telah mempersiapkan begitu lama. Aku akan menikmati cerita ini bersamamu, kakakku tercinta."
  },
  AvgDialog_131232_Content_24 = {
    Text = "Tidak ada kesempatan lagi untuk kalian bertanya. Kuku tajam Nefraea menyentuh tepi pipi Arachne dengan lembut, lalu jatuh ke tanah bersama tubuhnya."
  },
  AvgDialog_131232_Content_25 = {Text = "Tunggu…!"},
  AvgDialog_131232_Content_26 = {
    Text = "Dia tidak ada di sini, Penjaga Rahasia {Male=先生,Female=小姐}."
  },
  AvgDialog_131232_Content_27 = {
    Text = "Suara mendidih terdengar, cairan hitam kembali mengalir dari wajah mayat."
  },
  AvgDialog_131232_Content_28 = {
    Text = "\"Romantis\" mata yang menawan itu masih mempertahankan lengkungan senyum, laba-laba hitam merayap sembarangan di tubuhnya, samar-samar terlihat di rongga mata yang cerah. Bibirnya yang anggun tidak mengeluarkan suara lagi."
  },
  AvgDialog_131232_Content_29 = {Text = "Ini…"},
  AvgDialog_131232_Content_3 = {
    Text = "Nefraea dan Arachne masih duduk berhadapan, dia menuangkan segelas anggur dan mendorongnya ke arah Arachne."
  },
  AvgDialog_131232_Content_30 = {
    Text = "Dia membunuh boneka rahasia ini, meninggalkan cap di tubuhnya, mencemari nasibnya, dan membuat dirinya ada secara singkat di dalam dirinya."
  },
  AvgDialog_131232_Content_31 = {
    Text = "Arachne datang di depan Misteri Pasangan, mengulurkan tangannya ke atas kepala \"Romantis\", menatap benang yang hampir menghilang itu."
  },
  AvgDialog_131232_Content_32 = {
    Text = "……Apakah kamu melihat sesuatu?"
  },
  AvgDialog_131232_Content_33 = {
    Text = "Rahasia lainnya juga telah tercemar, saya tidak dapat merasakan keberadaan mereka dari jaring nasib... tetapi nasib \"romantis\" terhubung dengan mereka."
  },
  AvgDialog_131232_Content_34 = {
    Text = "Dia memberi tahu saya tentang keberadaan \"Kebaikan\"."
  },
  AvgDialog_131232_Content_35 = {
    Text = "Arachne Lepaskan nasib yang terjalin, untuk \"Romantis\" merapikan poni yang indah itu."
  },
  AvgDialog_131232_Content_36 = {
    Text = "Kemampuan Nefraea berasal dari saya, nasib yang terpolusi olehnya, saya tidak dapat melihat, banyak kemampuan, juga terbatas oleh ini."
  },
  AvgDialog_131232_Content_37 = {
    Text = "Anda adalah pecahan dari dewa itu, seseorang yang takdirnya tidak bisa kami lihat. Oleh karena itu, saya membutuhkan bantuan Anda, Penjaga Rahasia {Male=先生,Female=小姐}."
  },
  AvgDialog_131232_Content_38 = {
    Text = "Tenang saja, meskipun hanya untuk kembali ke Kadas, aku harus menyelesaikannya."
  },
  AvgDialog_131232_Content_39 = {
    Text = "Dia mencari rahasia-rahasia ini, untuk apa?"
  },
  AvgDialog_131232_Content_4 = {
    Text = "Meskipun Nona \"Romantis\" sudah tidak ada, tetapi anggur di sini tidak seharusnya terbuang."
  },
  AvgDialog_131232_Content_40 = {
    Text = "Rahasia ini akan menjadi sumber kekuatannya."
  },
  AvgDialog_131232_Content_41 = {
    Text = "Jadi kita harus segera berangkat... menemukan Misteri Pasangan itu, serta Dimensi Abu sisa yang bisa membantumu menyusun takdir..."
  },
  AvgDialog_131232_Content_42 = {
    Text = "Di mana \"Boneka Baik\" yang disebut itu sekarang?"
  },
  AvgDialog_131232_Content_43 = {
    Text = "\"Romantis\" baru saja memberitahunya tentang bahaya itu. Dia sekarang bersembunyi, dilindungi oleh seorang teman lama Anda."
  },
  AvgDialog_131232_Content_44 = {
    Text = "Teman lama?……"
  },
  AvgDialog_131232_Content_45 = {
    Text = "Silakan ikuti saya, Penjaga Rahasia {Male=先生,Female=小姐}. Salon megah Nyonya Soreil akan segera dimulai."
  },
  AvgDialog_131232_Content_5 = {
    Text = "Ingin mencobanya? Dibandingkan dengan sosok rahasia yang kamu perankan sendiri, akulah yang benar-benar memahami dirimu."
  },
  AvgDialog_131232_Content_6 = {
    Text = "Arachne tidak ragu, dia tersenyum sambil mengangkat gelas, perlahan-lahan mengambil seteguk."
  },
  AvgDialog_131232_Content_7 = {
    Text = "Kamu tidak cocok untuk melakukan pekerjaan ini, Nefraea. Selain pahit dan asam, tidak ada rasa lain."
  },
  AvgDialog_131232_Content_8 = {
    Text = "Aku menyebutnya \"Takdir\". Suka?"
  },
  AvgDialog_131232_Content_9 = {
    Text = "Arachne tidak menghiraukan tatapan penuh harap Nefraea. Dia perlahan meneguk minuman di dalam cangkirnya, kemudian meletakkan cangkir itu dengan lembut di atas meja."
  },
  AvgDialog_132684_Content_1 = {
    Text = "<Small:<LightGray:Ji……? (Hm……?)>>"
  },
  AvgDialog_132684_Content_10 = {
    Text = "Tidak salah, dan mengingat bahwa Mythag sendiri memiliki tradisi menggoda orang untuk berkomunikasi perasaan di hari ini, pihak sekolah tidak akan menghukum \"prank\" yang tidak berlebihan seperti ini."
  },
  AvgDialog_132684_Content_11 = {
    Text = "Ciiit! Ciiit, Ciiit—!<Small:<LightGray:(Guru Doll, kamu sedang mencubit tanganku dan wajahku, kan? Kamu benar-benar sedang menggosok wajahku, kan!)>>"
  },
  AvgDialog_132684_Content_12 = {
    Text = "Meskipun nada suaranya selalu dingin, bahkan sedikit sinis, kamu sangat yakin bahwa sudut bibir Doll setidaknya terangkat 2 milimeter."
  },
  AvgDialog_132684_Content_13 = {
    Text = "Maaf, Penjaga. Alat penerjemah Perak sepertinya mengalami sedikit masalah, tapi tidak apa-apa, reagen balik bisa disintesis besok pagi."
  },
  AvgDialog_132684_Content_14 = {
    Text = "Kamu melihat Doll dengan wajah terkejut, meskipun sekarang kamu hanya punya otak berang-berang, kamu bisa melihat bahwa reagen di belakangnya jelas berada dalam keadaan selesai."
  },
  AvgDialog_132684_Content_15 = {
    Text = "Guru, cari Mosk?"
  },
  AvgDialog_132684_Content_16 = {
    Text = "！！！Bola arang kecil—"
  },
  AvgDialog_132684_Content_17 = {
    Text = "Jik—<Small:<LightGray:(Bos——)>>"
  },
  AvgDialog_132684_Content_18 = {
    Text = "Mengingat kita memiliki orang-orang yang berpengalaman dalam kelompok tersebut, saya rasa, menghabiskan sehari bersama mereka seharusnya dapat membantu Penjaga kita untuk lebih ingat."
  },
  AvgDialog_132684_Content_19 = {
    Text = "Mosk, urus tugas %player% sudah menjadi tanggung jawabmu."
  },
  AvgDialog_132684_Content_2 = {Text = "*Melompat"},
  AvgDialog_132684_Content_20 = {
    Text = "*Sorak Bagus! Bola arang kecil, ayo bermain"
  },
  AvgDialog_132684_Content_21 = {
    Text = "Ciiit!<Small:<LightGray:(Ayo bermain bersama!)>>"
  },
  AvgDialog_132684_Content_22 = {
    Text = "Jii—<Small:<LightGray:(Jangan, Ramona, tolong aku—)>>"
  },
  AvgDialog_132684_Content_23 = {Text = "Batuk."},
  AvgDialog_132684_Content_24 = {
    Text = "Rekan, hari ini tidak ada urusan penting, jadi jangan khawatir."
  },
  AvgDialog_132684_Content_25 = {
    Text = "Saya juga akan meluangkan waktu hari ini untuk menjamin keselamatanmu."
  },
  AvgDialog_132684_Content_26 = {
    Text = "Meskipun kata-katanya seperti itu, jelas bahwa dia juga sudah sepenuhnya dikendalikan oleh bulu yang luar biasa sulit dipercaya yang kamu miliki, sama seperti Mosk."
  },
  AvgDialog_132684_Content_27 = {
    Text = "Jik, jik jik jik……<Small:<LightGray:(Apakah masih ada yang bisa menyelamatkan, William, Senior……)>>"
  },
  AvgDialog_132684_Content_28 = {
    Text = "Ngomong-ngomong, William hari ini pergi untuk tugas luar, dia akan kembali sangat larut."
  },
  AvgDialog_132684_Content_29 = {
    Text = "*Minum teh <Small:<LightGray:(Huh, kesempatan langka, siswa saya yang paling tidak merepotkan dan paling penting, mari kita tinggalkan segalanya dan bersantai seharian.)>>"
  },
  AvgDialog_132684_Content_3 = {
    Text = "*Menggosok Wajah"
  },
  AvgDialog_132684_Content_30 = {
    Text = "Saat ini, seorang senior yang jauh di sana."
  },
  AvgDialog_132684_Content_31 = {Text = "Aduh"},
  AvgDialog_132684_Content_32 = {
    Text = "Aneh, entah kenapa saya merasa tidak enak."
  },
  AvgDialog_132684_Content_33 = {
    Text = "Hari ini lebih baik kembali ke sekolah lebih awal."
  },
  AvgDialog_132684_Content_34 = {
    Text = "Mythag April Mop, juga sangat damai."
  },
  AvgDialog_132684_Content_35 = {
    Text = "Selamat dan gembira, selamat dan gembira."
  },
  AvgDialog_132684_Content_4 = {Text = "???!!!"},
  AvgDialog_132684_Content_5 = {
    Text = "Ciiit Ciiit Ciiit Ciiit Ciiit! Yeng yeng yeng yeng yeng!!!<Small:<LightGray:(Aku telah menjadi berang-berang! Ramona, tolong aku!)>>"
  },
  AvgDialog_132684_Content_7 = {
    Text = "Kabar baik, efek semprotan ini tidak bersifat permanen, dan pengaturan reagen balik juga sangat sederhana, jelas pihak lain tidak memiliki niat jahat."
  },
  AvgDialog_132684_Content_8 = {
    Text = "Berita yang lebih baik, ternyata berani menggunakan hadiah dari si penipu kecil yang penuh kebohongan itu tanpa berpikir, sementara mengganti otak dengan seekor berang-berang mungkin benar-benar membantu kamu untuk sadar sejenak."
  },
  AvgDialog_132684_Content_9 = {
    Text = "Jadi, konversi sementara ini tidak akan menyebabkan kerusakan apapun pada penjaga?"
  },
  AvgDialog_13733_Content_1 = {
    Text = "Ritual Merah"
  },
  AvgDialog_13733_Content_10 = {
    Text = "Heh, kau tak bisa mengharapkan wawasan dari orang Lemwashi. Buka lebar matamu dan perhatikan..."
  },
  AvgDialog_13733_Content_11 = {
    Text = "Purin mengeluarkan pisau ritual dari lengan bajunya dan tanpa ragu menyayat pergelangan tangannya sendiri."
  },
  AvgDialog_13733_Content_12 = {
    Text = "Darah merah menetes satu per satu ke atas lingkaran sihir yang dibuat dari belerang, dan keajaiban pun terjadi—"
  },
  AvgDialog_13733_Content_13 = {
    Text = "Bagaikan setetes air yang meresap ke padang pasir yang gersang, lingkaran sihir yang menyerap darah segar itu dengan cepat memancarkan cahaya merah gelap bergelombang."
  },
  AvgDialog_13733_Content_14 = {
    Text = "Cahaya itu bagaikan api di bawah langit gelap, dengan rakus menjilati pasir kuning yang dihempas angin, seolah hendak menelan seluruh bumi ke dalam perutnya."
  },
  AvgDialog_13733_Content_15 = {
    Text = "Kau lihat itu? Inilah momen sihir yang sesungguhnya! Hahahaha!"
  },
  AvgDialog_13733_Content_16 = {
    Text = "Hahahaha... <Big:UAAARGH!!!>"
  },
  AvgDialog_13733_Content_17 = {
    Text = "Purin jatuh berlutut ke tanah dengan bunyi \"bruk\", tangannya tak terkendali mencekik lehernya sendiri."
  },
  AvgDialog_13733_Content_18 = {
    Text = "Rantai yang menghubungkan dirinya dengan Yuuhashi dengan cepat menegang, menarik daging dan jiwa keduanya erat-erat menjadi satu."
  },
  AvgDialog_13733_Content_19 = {
    Text = "Ngh... Apa...?"
  },
  AvgDialog_13733_Content_2 = {
    Text = [[
Pinggiran Gurun Kusi
Lokasi Ritual]]
  },
  AvgDialog_13733_Content_20 = {
    Text = "Yuuhashi tak lagi bisa mempertahankan posisi duduknya yang santai."
  },
  AvgDialog_13733_Content_21 = {
    Text = "Ia dihempaskan oleh kekuatan tak kasat mata, menatap dengan bingung lingkaran sihir di hadapannya yang hampir kehilangan kendali."
  },
  AvgDialog_13733_Content_22 = {Text = "Ngh..."},
  AvgDialog_13733_Content_23 = {
    Text = "<Big:AAAAAAAH!>"
  },
  AvgDialog_13733_Content_24 = {
    Text = "Purin tertelungkup di tanah, menatap dengan ganas sosok Yuuhashi yang meronta-ronta, lalu terkekeh pelan."
  },
  AvgDialog_13733_Content_25 = {
    Text = "Sakit, kan... Memang harus sakit..."
  },
  AvgDialog_13733_Content_26 = {
    Text = "Saat ini kesadaran kita terhubung erat satu sama lain..."
  },
  AvgDialog_13733_Content_27 = {
    Text = "Bagaimana anjing-anjing Lemwashi membantai bangsaku, menodai istriku, kau sudah melihatnya, kan... Kau merasakannya, kan..."
  },
  AvgDialog_13733_Content_28 = {
    Text = "<Big:Jawab aku, dasar makhluk bodoh sebodoh @1!>"
  },
  AvgDialog_13733_Content_29 = {Text = "Hehe……"},
  AvgDialog_13733_Content_3 = {
    Text = "Bagus, taburkan dulu selapis belerang, lalu serbuk arang……"
  },
  AvgDialog_13733_Content_30 = {
    Text = "Jangan senang dulu……orang tua."
  },
  AvgDialog_13733_Content_31 = {
    Text = "Begitu aku lepas dari belenggu ini, orang pertama yang akan kucabik-cabik adalah kau—umph!!"
  },
  AvgDialog_13733_Content_32 = {
    Text = "Sayang sekali, kali ini kau sepertinya tidak akan bisa mendapatkan apa yang kau inginkan……"
  },
  AvgDialog_13733_Content_33 = {
    Text = "Purin terengah-engah, tangannya gemetar menggenggam rantai tak kasat mata itu, lalu menariknya dengan sekuat tenaga—"
  },
  AvgDialog_13733_Content_34 = {
    Text = "Rantai yang tadinya begitu kokoh itu pun hancur berkeping-keping."
  },
  AvgDialog_13733_Content_35 = {
    Text = "Hehe@3aaah@1aaah!!"
  },
  AvgDialog_13733_Content_36 = {
    Text = "Purin mengeluarkan jeritan kesakitan, kulit wajahnya membusuk dan mengelupas seperti kulit kayu, memperlihatkan daging mentah yang kabur di baliknya."
  },
  AvgDialog_13733_Content_37 = {
    Text = "Lingkaran sihir membuka mulutnya yang gelap menganga, memakan daging dan darahnya sedikit demi sedikit hingga bersih, sampai sang penyihir benar-benar berubah menjadi kerangka tulang yang kosong."
  },
  AvgDialog_13733_Content_38 = {
    Text = "Aku telah mengorbankan daging, jiwa, dan segalanya……lalu bagaimana denganmu……"
  },
  AvgDialog_13733_Content_39 = {
    Text = "Sebelum kau membunuh sepuluh ribu anjing Lemwahi, kau tidak akan pernah mendapatkan kebebasan sejati!"
  },
  AvgDialog_13733_Content_4 = {
    Text = "Tidak, coba lihat apa kata bukunya……"
  },
  AvgDialog_13733_Content_40 = {
    Text = "Yuuhashi perlahan berdiri."
  },
  AvgDialog_13733_Content_41 = {
    Text = "Wajahnya terbakar menjadi abu hitam oleh api tak kasat mata, berjatuhan rontok tertiup angin."
  },
  AvgDialog_13733_Content_42 = {Text = "Heh……"},
  AvgDialog_13733_Content_43 = {
    Text = "\"Kebebasan sejati\"……? Apa itu?"
  },
  AvgDialog_13733_Content_44 = {
    Text = "Prajurit yang hangus terbakar itu berdiri tegak di tengah cahaya api yang menyala-nyala. Kedua matanya merah menyala, hanya getaran serak yang keluar dari tenggorokannya."
  },
  AvgDialog_13733_Content_45 = {
    Text = "Aku, Yuuhashi, hanya pernah peduli pada satu hal—"
  },
  AvgDialog_13733_Content_46 = {
    Text = "Dia melesat keluar dengan kecepatan luar biasa, menerjang sang penyihir hingga jatuh ke tanah."
  },
  AvgDialog_13733_Content_47 = {
    Text = "Lalu dia memperlihatkan taringnya yang tajam dan menggigit putus leher sang penyihir dengan ganas."
  },
  AvgDialog_13733_Content_48 = {
    Text = "<Red:Yaitu darah!!>"
  },
  AvgDialog_13733_Content_49 = {
    Text = "Tuan Purin!"
  },
  AvgDialog_13733_Content_5 = {
    Text = "Di tempat yang kurang dari lima puluh yard dari medan perang, Purin sedang sibuk bekerja keras."
  },
  AvgDialog_13733_Content_50 = {
    Text = "<Shake:Nyawa ini, kuberikan padamu……untuk balas dendam@2tolong aku……>"
  },
  AvgDialog_13733_Content_51 = {
    Text = "Menolongmu? Orang tua, kau pasti salah paham……"
  },
  AvgDialog_13733_Content_52 = {
    Text = "Mangsa tidak berhak mengajukan tuntutan kepada aku, Yuuhashi."
  },
  AvgDialog_13733_Content_53 = {
    Text = "Aku bisa menuruti kata-katamu, itu karena aku bisa kapan saja menghancurkan mainan rantai besimu, bukan karena kontrak omong kosong yang kau buat denganku."
  },
  AvgDialog_13733_Content_54 = {
    Text = "Waktu bermain sudah berakhir. Sekarang, aku ingin kau membuka lebar matamu dan menyaksikan——"
  },
  AvgDialog_13733_Content_55 = {
    Text = "Bagaimana aku membantai musuhmu, bangsamu, dan semua makhluk hidup yang kau lihat……"
  },
  AvgDialog_13733_Content_56 = {
    Text = "<Change>Iblis……kau iblis……"
  },
  AvgDialog_13733_Content_57 = {
    Text = "Darah Purin mengalir deras di dalam lingkaran sihir, membuat cahaya merah darah itu pun tampak sangat pudar."
  },
  AvgDialog_13733_Content_58 = {
    Text = "Dia mengorbankan nyawanya sendiri, demi menukar \"kebebasan\" Yuuhashi."
  },
  AvgDialog_13733_Content_59 = {
    Text = "Hehe……aaah@4……"
  },
  AvgDialog_13733_Content_6 = {
    Text = "Sementara Yuuhashi, atas permintaan Purin, duduk tegak di tengah lingkaran sihir yang digambar dengan serbuk belerang."
  },
  AvgDialog_13733_Content_60 = {
    Text = "Yuuhashi perlahan mengangkat kepalanya, sudut bibirnya masih berlumuran darah segar yang belum dijilat habis, matanya sudah lama digerogoti kegelapan."
  },
  AvgDialog_13733_Content_61 = {
    Text = "Dia telah berubah menjadi seekor binatang buas sejati. Atau bisa dibilang, inilah wujud aslinya yang sebenarnya."
  },
  AvgDialog_13733_Content_62 = {
    Text = "<Red:Kembali, semuanya telah kembali……>"
  },
  AvgDialog_13733_Content_7 = {
    Text = "Huu……huu……"
  },
  AvgDialog_13733_Content_8 = {
    Text = "Hebat sekali, dalam situasi seperti ini masih bisa tertidur……"
  },
  AvgDialog_13733_Content_9 = {
    Text = [[
Saya ingin bertanya soal teknis, Tuan Purin.
Bukankah serbuk yang kau taburkan ini bisa diterbangkan angin?]]
  },
  AvgDialog_13734_Content_1 = {
    Text = "Hah……akhirnya berhasil menyusul.\nKuperingatkan kau, Yuuhashi, kau seharusnya tahu akibat dari meninggalkanku tanpa izin, kan?"
  },
  AvgDialog_13734_Content_10 = {
    Text = "Kalian akhirnya tiba di tujuan akhir perjalanan ini. Purin mengeluarkan dua tawa aneh dari tenggorokannya, api bernama balas dendam membakarnya hingga seluruh tubuhnya gemetar."
  },
  AvgDialog_13734_Content_11 = {
    Text = "<Shake:Ayo pergi, Yuuhashi……>"
  },
  AvgDialog_13734_Content_12 = {
    Text = "<Red:Bunuh sepuasnya.>"
  },
  AvgDialog_13734_Content_2 = {Text = "Ssstt!!"},
  AvgDialog_13734_Content_3 = {
    Text = "Yuuhashi berjongkok di atas bukit pasir yang tinggi, mengeluarkan desisan tak sabar dari hidungnya, seperti seekor binatang buas yang sedang fokus berburu namun terganggu oleh nyamuk."
  },
  AvgDialog_13734_Content_4 = {
    Text = "Bibirnya sedikit terbuka, cuping hidungnya bergetar pelan, dan cahaya merah darah di matanya lebih pekat dari sebelumnya."
  },
  AvgDialog_13734_Content_5 = {
    Text = "<RedShake:Ketemu, ketemu……>"
  },
  AvgDialog_13734_Content_6 = {
    Text = "Kalian mengikuti arah pandangannya dan memandang ke bawah—"
  },
  AvgDialog_13734_Content_7 = {
    Text = "Titik-titik hitam kecil tak terhitung bertebaran di atas bukit pasir yang bergelombang, seperti semut-semut yang merayap di atas meja pasir."
  },
  AvgDialog_13734_Content_8 = {
    Text = "Dentingan senjata yang beradu, teriakan, dan derap kaki kuda silih berganti, gulungan lukisan perang yang megah terbentang perlahan di hadapan kalian."
  },
  AvgDialog_13734_Content_9 = {
    Text = "Orang Lemwashi, orang Leo……bagus, bagus sekali."
  },
  AvgDialog_13735_Content_1 = {
    Text = "Ekspedisi Matahari"
  },
  AvgDialog_13735_Content_10 = {
    Text = "Dia masih terikat oleh rantai tak kasat mata, hanya bisa duduk bersila dalam posisi yang canggung, seluruh tubuhnya hampir menyatu dengan kegelapan."
  },
  AvgDialog_13735_Content_11 = {
    Text = "…Tidak kusangka kau masih terjaga."
  },
  AvgDialog_13735_Content_12 = {
    Text = "<Yellow:Golem> tidak perlu tidur."
  },
  AvgDialog_13735_Content_13 = {
    Text = "Golem……?"
  },
  AvgDialog_13735_Content_14 = {
    Text = "Hehe……jangan berpura-pura tidak tahu."
  },
  AvgDialog_13735_Content_15 = {
    Text = "Kau bisa melihat rantai di tubuhku, seharusnya kau juga tahu apa itu golem."
  },
  AvgDialog_13735_Content_16 = {
    Text = [[
Tidak disangka lirikan santainya waktu itu ternyata disadari olehnya.
Dia memang memiliki insting binatang buas.]]
  },
  AvgDialog_13735_Content_17 = {
    Text = "Guruku pernah memberitahuku……"
  },
  AvgDialog_13735_Content_18 = {
    Text = "Pada zaman Romawi kuno, ada seorang alkemis gila yang mengorbankan banyak nyawa manusia untuk menciptakan golem pertama."
  },
  AvgDialog_13735_Content_19 = {
    Text = "Itu juga merupakan keberadaan yang paling mendekati Awakened Body dalam literatur kuno."
  },
  AvgDialog_13735_Content_2 = {
    Text = "Gurun Kusi bagian utara, malam"
  },
  AvgDialog_13735_Content_20 = {
    Text = "Golem itu, adalah kau, kan?"
  },
  AvgDialog_13735_Content_21 = {
    Text = "Benar……itu aku. Aku menjadi anjing peliharaan <Blue:Caligula>, membunuh banyak orang untuknya."
  },
  AvgDialog_13735_Content_22 = {
    Text = "Kemudian mereka tidak membutuhkanku lagi, jadi mereka mengunciku di bawah tanah yang gelap gulita, sampai orang itu membebaskanku."
  },
  AvgDialog_13735_Content_23 = {
    Text = "Sambil berkata demikian, tatapan Yuuhashi melirik Purin yang masih tidur nyenyak di dalam tenda."
  },
  AvgDialog_13735_Content_24 = {
    Text = "——Syaratnya?"
  },
  AvgDialog_13735_Content_25 = {
    Text = "Syaratnya adalah, menjadi anjingnya dulu, pergi ke medan perang dan membunuh sebanyak mungkin orang Lemwashi."
  },
  AvgDialog_13735_Content_26 = {
    Text = "Setelah itu kita berpisah, masing-masing menjalani hidup sendiri."
  },
  AvgDialog_13735_Content_27 = {
    Text = "Yuuhashi meregangkan tubuhnya dengan santai, duduk bersandar di bukit pasir dengan kedua kaki terbuka lebar."
  },
  AvgDialog_13735_Content_28 = {
    Text = "Rantai seperti ini sama sekali tidak bisa membatasimu. Kenapa tidak langsung membunuh penyihir itu lalu pergi?"
  },
  AvgDialog_13735_Content_29 = {
    Text = "Karena dia bilang, di medan perang ada banyak orang."
  },
  AvgDialog_13735_Content_3 = {
    Text = "Grrr… grrr… syuuu…"
  },
  AvgDialog_13735_Content_30 = {
    Text = "<Red:Banyak orang, berarti banyak darah.>"
  },
  AvgDialog_13735_Content_31 = {
    Text = "<RedShake:Kau tahu, sudah hampir seribu tahun aku tidak merasakan rasa darah itu……>"
  },
  AvgDialog_13735_Content_33 = {
    Text = "Orang itu sama sekali tidak terlihat seperti orang baik yang menepati janji. Bagaimana kalau dia menipumu?"
  },
  AvgDialog_13735_Content_34 = {
    Text = "Kalau begitu bunuh saja dia. Simpel, bukan?"
  },
  AvgDialog_13735_Content_36 = {
    Text = "Harus diakui, kata-katanya memang masuk akal."
  },
  AvgDialog_13735_Content_37 = {
    Text = "Angin malam berhembus lembut, bukit-bukit pasir yang bergelombang halus terus membentang di hadapanmu. Di bawah langit yang tak bertepi, hanya tersisa dua sosok kecil."
  },
  AvgDialog_13735_Content_38 = {
    Text = "Kau mendongak memandang langit yang dipenuhi bintang-bintang."
  },
  AvgDialog_13735_Content_39 = {
    Text = "Untuk menghabiskan malam yang panjang ini, kau memutuskan untuk berbincang dan bertukar pengalaman dengan golem di hadapanmu."
  },
  AvgDialog_13735_Content_4 = {
    Text = "Dengkuran bagaikan guntur memecah keheningan malam, tampaknya insiden kecil di siang hari tidak memengaruhi tidur nyenyak Purin."
  },
  AvgDialog_13735_Content_40 = {
    Text = [[
Pasti tidak enak sekali dikurung di bawah tanah.
Setelah memenuhi perjanjian, kau akan mendapatkan kebebasan. Bagaimana perasaanmu sekarang?]]
  },
  AvgDialog_13735_Content_41 = {
    Text = [[
Kalau kau sendiri?
Kau juga sudah lama bukan budak lagi, berkeliaran di gurun pasir untuk mencari nafkah setiap hari. Bagaimana rasanya?]]
  },
  AvgDialog_13735_Content_43 = {
    Text = "Memang tidak begitu menyenangkan. Di tempat terkutuk ini bahkan matahari pun tak terlihat…"
  },
  AvgDialog_13735_Content_44 = {
    Text = "Kau ini buta ya. Matahari sebesar itu di gurun pasir tidak kelihatan?"
  },
  AvgDialog_13735_Content_45 = {
    Text = "Kau tidak mengerti. Yang kumaksud itu matahari yang lembut, cerah, yang terasa hangat saat berjemur… Di gurun pasir tidak ada yang seperti itu."
  },
  AvgDialog_13735_Content_46 = {
    Text = [[
Kau menguap, rasa kantuk perlahan menyergap.
Begitu sarafmu sedikit mengendur, obrolan pun menjadi jauh lebih santai.]]
  },
  AvgDialog_13735_Content_47 = {
    Text = "Di luar dugaanmu, Yuuhashi ternyata cukup layak sebagai pendengar."
  },
  AvgDialog_13735_Content_48 = {
    Text = "Mungkin kau tidak akan percaya, tapi sebenarnya aku juga sedang mengemban misi…"
  },
  AvgDialog_13735_Content_49 = {
    Text = "Suatu hari nanti, setelah menyelesaikan semua hal yang harus kulakukan, aku pasti akan mencari tempat untuk berbaring berjemur di bawah matahari, dan makan banyak sekali kue-kue kecil…"
  },
  AvgDialog_13735_Content_5 = {
    Text = "Kau sudah tidak tahan lagi, akhirnya menyibak tenda dan berjalan keluar."
  },
  AvgDialog_13735_Content_50 = {
    Text = "…Sulit dipahami."
  },
  AvgDialog_13735_Content_51 = {
    Text = "Golem terlahir dari kegelapan, secara naluriah takut akan sinar matahari, dan pemenjaraan selama hampir seribu tahun semakin memperdalam kebenciannya terhadap cahaya matahari."
  },
  AvgDialog_13735_Content_52 = {
    Text = "Aku benar-benar merasa kasihan padamu. Berjemur di bawah matahari itu hal paling menyenangkan di dunia…"
  },
  AvgDialog_13735_Content_53 = {
    Text = "Sayangnya bagiku, bahkan keinginan sesederhana ini pun sulit untuk diwujudkan…"
  },
  AvgDialog_13735_Content_54 = {
    Text = [[
Angin bertiup.
Pasir halus yang melayang merajut lapis demi lapis selendang kuning pucat, mengambang lembut di bawah langit malam yang bertaburan bintang.]]
  },
  AvgDialog_13735_Content_55 = {
    Text = "Kau mendengarkan suara angin bersih yang datang dari kejauhan, akhirnya terlelap dalam mimpi."
  },
  AvgDialog_13735_Content_57 = {
    Text = "Gurun Kusi bagian utara, siang hari"
  },
  AvgDialog_13735_Content_58 = {
    Text = "Ini benar-benar gila! Bukankah kau sudah menepuk dada dan berjanji bahwa beberapa hari ini mustahil ada badai pasir?!"
  },
  AvgDialog_13735_Content_59 = {
    Text = "Purin melotot sambil menunjuk ke arah pasir liar yang bergulung-gulung menerjang dari cakrawala."
  },
  AvgDialog_13735_Content_6 = {
    Text = "Indahnya…"
  },
  AvgDialog_13735_Content_60 = {
    Text = "Sekarang jelaskan padaku, <Big:@1itu apa?>"
  },
  AvgDialog_13735_Content_61 = {Text = "Ehm……"},
  AvgDialog_13735_Content_62 = {
    Text = "Sebelum kau \"memasuki mimpi\", pemilik tubuh asli memang membuat beberapa janji yang tidak tulus demi memeras domba gemuk ini."
  },
  AvgDialog_13735_Content_63 = {
    Text = "Sekarang bukan waktunya bertengkar, badai pasir sudah datang, cepat lari——"
  },
  AvgDialog_13735_Content_64 = {
    Text = "Setelah berkata demikian, kau langsung melesat secepat mungkin, meninggalkan Purin jauh di belakang."
  },
  AvgDialog_13735_Content_65 = {
    Text = "<Big:Hei……berhenti kau!>"
  },
  AvgDialog_13735_Content_66 = {
    Text = "Badai pasir? Apa itu, pemandangannya terlihat bagus kok."
  },
  AvgDialog_13735_Content_67 = {
    Text = "Yuwuhashi berlari santai dengan punggung menghadap ke depan, menyusul ke sisimu, matanya masih menatap ke kejauhan tanpa berkedip."
  },
  AvgDialog_13735_Content_68 = {
    Text = "Kau belum pernah melihat badai pasir?"
  },
  AvgDialog_13735_Content_69 = {
    Text = "Yuwuhashi mengangkat bahu."
  },
  AvgDialog_13735_Content_7 = {
    Text = "Selamat malam, Tuan Pemandu."
  },
  AvgDialog_13735_Content_70 = {
    Text = "Dulu ruang gerakku terbatas hanya di dalam kota Roma, ada terlalu banyak hal yang belum pernah kulihat."
  },
  AvgDialog_13735_Content_71 = {
    Text = "<Shake:Uhh……hoek……>"
  },
  AvgDialog_13735_Content_72 = {
    Text = "Tertarik oleh rantai, Purin yang tertinggal jauh di belakang kalian terseret hingga melayang."
  },
  AvgDialog_13735_Content_73 = {
    Text = "<Shake:Pe-pelan sedikit……aku hampir mati……>"
  },
  AvgDialog_13735_Content_74 = {
    Text = "Tsk. Hampir lupa, masih ada si tua itu."
  },
  AvgDialog_13735_Content_75 = {
    Text = "Yuwuhashi berbalik kembali, dengan ringan mengangkat tubuh pendek gempal sang penyihir."
  },
  AvgDialog_13735_Content_76 = {
    Text = "Ka-kamu mau apa?"
  },
  AvgDialog_13735_Content_77 = {
    Text = "Tidak apa-apa, cuma membantumu berlari lebih cepat sedikit."
  },
  AvgDialog_13735_Content_78 = {
    Text = "Setelah berkata demikian, Uuhashi dengan mudah menjepit sang penyihir di bawah ketiaknya, kaki depan melangkah satu langkah, telapak kaki belakang menolak tanah, membungkukkan seluruh tubuhnya."
  },
  AvgDialog_13735_Content_79 = {
    Text = "Hei…… aku peringatkan kamu, sekarang bukan waktunya bermain-main——<Big:AAARGH!!!>"
  },
  AvgDialog_13735_Content_8 = {Text = "!!"},
  AvgDialog_13735_Content_80 = {
    Text = "Uuhashi menghentakkan kakinya dengan kuat, melesat keluar bagai anak panah yang terlepas dari busurnya."
  },
  AvgDialog_13735_Content_81 = {
    Text = "A-aku, kamu…… @1 sialan, turunkan aku!"
  },
  AvgDialog_13735_Content_82 = {
    Text = [[
Uuhashi meledak dalam tawa yang membahana.
Suara tawanya terbang tertiup angin, berpadu dengan butiran pasir keemasan dan debu, berlari riang menuju kejauhan.]]
  },
  AvgDialog_13735_Content_83 = {
    Text = "Tidak bisa begitu, aku masih harus menyimpan nyawamu untuk membantuku meraih kebebasan!"
  },
  AvgDialog_13735_Content_9 = {
    Text = "Yuuhashi tiba-tiba muncul dari sudut gelap, menyeringai ke arahmu."
  },
  AvgDialog_13736_Content_1 = {
    Text = "Pemandu, Penyihir, dan Budak"
  },
  AvgDialog_13736_Content_10 = {
    Text = "Kecokelatan, kering, garis-garis telapak tangan yang kasar dan liar — ini adalah sepasang tangan seorang pejuang."
  },
  AvgDialog_13736_Content_100 = {
    Text = "Maaf, aku tidak punya apa-apa untuk dibicarakan denganmu."
  },
  AvgDialog_13736_Content_101 = {
    Text = "Tentara bayaran itu sekelompok orang tanpa keyakinan. Sedangkan budak, lebih tidak mungkin lagi memahami apa itu martabat dan kehormatan."
  },
  AvgDialog_13736_Content_102 = {
    Text = "Kau dan orang itu, kalian berdua pada dasarnya tidak ada bedanya."
  },
  AvgDialog_13736_Content_103 = {
    Text = "Tapi aku juga sudah melewati usia yang mudah terpancing emosi."
  },
  AvgDialog_13736_Content_104 = {
    Text = [[
Pertama, aku tidak bisa mengalahkanmu.
Kedua, kau masih sedikit berguna bagiku.]]
  },
  AvgDialog_13736_Content_105 = {
    Text = "Tidak peduli dari mana asalmu, sekarang, saat ini juga, teruslah memimpin rombongan, Tuan Pemandu."
  },
  AvgDialog_13736_Content_11 = {
    Text = "<Gray:Jamila·@1, 32 tahun, mantan tentara bayaran Mamluk, sekarang menjadi pemandu di gurun pasir…>"
  },
  AvgDialog_13736_Content_12 = {
    Text = "Kau diam-diam mencerna identitas barumu."
  },
  AvgDialog_13736_Content_13 = {
    Text = "Sepertinya kau \"memasuki mimpi\" lagi."
  },
  AvgDialog_13736_Content_14 = {
    Text = "Hei, apa yang kau bisikkan diam-diam? Kalau sudah bangun, cepat berdiri. Aku dan <Blue:budak>ku masih ada urusan penting."
  },
  AvgDialog_13736_Content_15 = {
    Text = "Pria bertubuh pendek gempal dengan pakaian aneh itu adalah <Blue:Ludwig Prin>, majikan yang menyewamu untuk pekerjaan ini."
  },
  AvgDialog_13736_Content_16 = {
    Text = "Dia berkata dengan tidak sabar, sambil mengarahkan cambuknya sembarangan ke belakang."
  },
  AvgDialog_13736_Content_17 = {Text = "Sss……"},
  AvgDialog_13736_Content_18 = {
    Text = "Youwuhashi——?!"
  },
  AvgDialog_13736_Content_19 = {
    Text = "Barulah kau menyadari pria yang bersembunyi di balik bukit pasir."
  },
  AvgDialog_13736_Content_2 = {
    Text = [[
@2, kekuasaan Paus melemah, kekuasaan raja bangkit
Kota Suci Akka menjadi rebutan

Karena mengkhawatirkan kekuatan Mamluk yang dipimpin oleh Baibars
Sang Pangeran menyerukan seluruh rakyat untuk berperang ke Timur, merebut kembali Kota Suci Akka]]
  },
  AvgDialog_13736_Content_20 = {
    Text = "Dia mempertahankan posisi jongkok, kedua lengannya yang panjang bertumpu santai di tanah, seperti seekor binatang buas yang siap menerkam."
  },
  AvgDialog_13736_Content_21 = {
    Text = "Melihat ekspresi terkejutmu, dia menyeringai lebar, memperlihatkan deretan taring putih yang tajam."
  },
  AvgDialog_13736_Content_22 = {
    Text = "Kenapa, kau mengenalku?"
  },
  AvgDialog_13736_Content_24 = {
    Text = "Sebelum kau sempat menjawab, cambuk panjang di tangan sang penyihir sudah menghantam keras tubuh Youwu."
  },
  AvgDialog_13736_Content_25 = {
    Text = "Kawan, kusarankan kau jangan bicara dengannya."
  },
  AvgDialog_13736_Content_26 = {
    Text = "Jangan tertipu karena dia punya mata dan hidung seperti kita, sebenarnya dia masih binatang liar yang tak beradab, atau lebih tepatnya……"
  },
  AvgDialog_13736_Content_28 = {
    Text = "Sekali lagi cambuk panjang menghantam keras tubuh Youwu."
  },
  AvgDialog_13736_Content_29 = {
    Text = "Dia itu <Red:iblis>."
  },
  AvgDialog_13736_Content_3 = {
    Text = "Dengan demikian, <Yellow:Perang Salib> yang megah sekali lagi dimulai…"
  },
  AvgDialog_13736_Content_30 = {
    Text = "Meski dicambuk berkali-kali berturut-turut, Youwuhashi bahkan tidak berkedip sedikit pun."
  },
  AvgDialog_13736_Content_31 = {
    Text = "Dia mengusap darah segar yang mengalir dari pelipisnya, mendekatkan telapak tangan ke hidung dan mengendusnya, lalu dengan santai mulai menjilati darah di ujung jarinya."
  },
  AvgDialog_13736_Content_32 = {
    Text = "Nah, lihat itu? Anjing penjaga rumahku saja lebih beradab dari dia! Lebih rendah dari binatang, hahahaha!"
  },
  AvgDialog_13736_Content_33 = {
    Text = "Hei…… orang tua, tenagamu hari ini jauh lebih lemah ya.\nKenapa, bahkan cambuk pun sudah tak bisa kau pegang erat?"
  },
  AvgDialog_13736_Content_34 = {Text = "Hmph……"},
  AvgDialog_13736_Content_35 = {
    Text = "Alasan binatang tetaplah binatang, karena mereka selalu tidak bisa menjaga mulut mereka, atau menyadari posisi mereka sendiri."
  },
  AvgDialog_13736_Content_36 = {
    Text = "Tidak apa-apa, aku akan <BigItalic:mengajarimu dengan baik>——"
  },
  AvgDialog_13736_Content_37 = {
    Text = "Purin begitu marah hingga kumisnya sampai tertiup ke atas, lalu seperti bola yang terpental, dia langsung melesat ke arah Yuwuhashi."
  },
  AvgDialog_13736_Content_38 = {Text = "Tunggu."},
  AvgDialog_13736_Content_39 = {
    Text = "Kau memegang pergelangan tangan Purin dan menariknya kembali."
  },
  AvgDialog_13736_Content_40 = {
    Text = "Berikan cambuknya padaku."
  },
  AvgDialog_13736_Content_41 = {
    Text = "Lepaskan aku! Biarkan aku memberi pelajaran pada binatang itu……"
  },
  AvgDialog_13736_Content_42 = {
    Text = "Tuan Jamila, sekarang aku adalah majikanmu. Tidak perlu kujelaskan apa itu majikan, kan?"
  },
  AvgDialog_13736_Content_43 = {
    Text = [[
Maaf, yang kutahu hanyalah aku adalah pemandu perjalanan ini.
Karena aku pemandunya, maka kalian harus menuruti perkataanku.]]
  },
  AvgDialog_13736_Content_44 = {
    Text = "Kalau tidak, aku pergi sekarang, dan kalian pergi sendiri ke <Blue:medan perang>."
  },
  AvgDialog_13736_Content_45 = {
    Text = "<Shake:Hei, hei……! Bisa kita bicarakan baik-baik, bicarakan baik-baik……>"
  },
  AvgDialog_13736_Content_46 = {
    Text = "Masih ada satu hal lagi."
  },
  AvgDialog_13736_Content_47 = {
    Text = "Kau mengernyit menatap Yuwuhashi."
  },
  AvgDialog_13736_Content_48 = {
    Text = "Meskipun interaksimu dengannya di kampus tidak banyak, kau tetap sedikit banyak mengetahui berbagai sepak terjangnya."
  },
  AvgDialog_13736_Content_49 = {
    Text = "Dia sama sekali bukan tipe orang yang mau tunduk pada orang lain."
  },
  AvgDialog_13736_Content_5 = {
    Text = "Kau membuka mata dari tidur panjang, yang terlihat di hadapanmu adalah hamparan gurun pasir yang luas tak berujung."
  },
  AvgDialog_13736_Content_50 = {
    Text = "Apa yang kau lakukan padanya? Bagaimana mungkin dia mau menuruti perkataanmu begitu saja?"
  },
  AvgDialog_13736_Content_51 = {
    Text = "Kenapa, kau meragukan kemampuanku sebagai <Blue:Penyihir Agung Utama Levant>?"
  },
  AvgDialog_13736_Content_52 = {
    Text = "Ini adalah ilmu rahasia langka di bidang kami, dan juga privasi diriku sebagai majikan. Tolong Tuan Pemandu jangan ikut campur urusan orang lain……"
  },
  AvgDialog_13736_Content_53 = {
    Text = [[
Tidak mau bilang ya?
Kalau begitu kupukul sampai kau mau bicara.]]
  },
  AvgDialog_13736_Content_54 = {
    Text = "Hei, tunggu……<Big:Auw!>"
  },
  AvgDialog_13736_Content_56 = {
    Text = "<Shake:Sss, sakit sekali... Kau, kau pasti bukan pemandu biasa!>"
  },
  AvgDialog_13736_Content_57 = {
    Text = "Katakan, apa kau mata-mata yang dikirim dari <Blue:Lemwashie> untuk menghadangku?"
  },
  AvgDialog_13736_Content_58 = {
    Text = "Kau tidak menanggapi pertanyaan Purin, karena seluruh perhatianmu sudah tertarik oleh sesuatu yang lain—"
  },
  AvgDialog_13736_Content_59 = {
    Text = "Sebuah rantai tipis panjang tampak samar-samar di bawah sinar matahari, memancarkan cahaya yang tidak biasa."
  },
  AvgDialog_13736_Content_6 = {
    Text = "Sudah bangun? Benar-benar sial, belum juga melangkah jauh sang pemandu sudah pingsan karena sengatan panas, apa-apaan ini?"
  },
  AvgDialog_13736_Content_60 = {
    Text = "Rantai itu membentang dari pergelangan tangan Purin, terus memanjang hingga berakhir di leher Yuuhashi."
  },
  AvgDialog_13736_Content_61 = {
    Text = "<Gray:Teknik yang tidak asing... Sepertinya pernah mendengar seseorang membicarakannya...>"
  },
  AvgDialog_13736_Content_62 = {
    Text = "Kalau tidak mau patuh, ikat saja pakai rantai anjing."
  },
  AvgDialog_13736_Content_63 = {
    Text = "Itu melanggar hukum di Londinium, Nona Agrippa. Sepertinya kami perlu memberitahumu beberapa pengetahuan hukum dasar..."
  },
  AvgDialog_13736_Content_64 = {
    Text = "Hehe, aku bukan orang bodoh."
  },
  AvgDialog_13736_Content_65 = {
    Text = "Kau tahu @1?"
  },
  AvgDialog_13736_Content_66 = {
    Text = "Itu adalah sihir kuno, di mana sang perapal bisa mengendalikan orang lain dengan rantai tak terlihat..."
  },
  AvgDialog_13736_Content_67 = {
    Text = "Kalau soal harganya..."
  },
  AvgDialog_13736_Content_68 = {
    Text = "Apa ya harganya? Gawat, aku tidak ingat..."
  },
  AvgDialog_13736_Content_69 = {
    Text = "Saat kau tenggelam dalam ingatan, tiba-tiba seseorang menyibak penutup wajahmu."
  },
  AvgDialog_13736_Content_7 = {
    Text = "Untung tempat terkutuk ini seumur hidup cuma kukunjungi sekali, @1!"
  },
  AvgDialog_13736_Content_70 = {
    Text = "Tiga sungai berliku... Kau adalah <Blue:tentara bayaran budak Mamluk>?!"
  },
  AvgDialog_13736_Content_71 = {
    Text = "Begitu Purin selesai bicara, Yuuhashi yang tadinya acuh tak acuh tiba-tiba menoleh menatapmu."
  },
  AvgDialog_13736_Content_72 = {Text = "Menarik..."},
  AvgDialog_13736_Content_73 = {
    Text = "Ti-tidak, orang-orang Mamluk seharusnya sedang di medan perang sekarang..."
  },
  AvgDialog_13736_Content_74 = {
    Text = "Aku mengerti, kau seorang desertir."
  },
  AvgDialog_13736_Content_75 = {
    Text = "Secara refleks kau meraba wajahmu sendiri."
  },
  AvgDialog_13736_Content_76 = {
    Text = "<Gray:Ternyata di wajahku juga ada tato……>"
  },
  AvgDialog_13736_Content_77 = {
    Text = "Benar, aku memang seorang desertir. Kampung halamanku di <Blue:Lemwashi>, tapi aku juga tidak ingin kembali ke sana lagi……"
  },
  AvgDialog_13736_Content_78 = {
    Text = [[
Desertir juga harus makan, jadi sekarang aku mencari nafkah sebagai pemandu.
Tenang saja, kelebihan terbesarku adalah bekerja dengan sangat teliti.]]
  },
  AvgDialog_13736_Content_79 = {
    Text = "Dijamin bisa membawa kalian ke medan perang——"
  },
  AvgDialog_13736_Content_8 = {
    Text = "Pemandu? Ini… di mana…"
  },
  AvgDialog_13736_Content_80 = {Text = "Pfft."},
  AvgDialog_13736_Content_81 = {
    Text = "Sudah cukup melihat kekacauan di depan mata, Yuuhashi meregangkan tubuhnya, lalu berjalan santai ke hadapanmu."
  },
  AvgDialog_13736_Content_82 = {
    Text = "Dia merangkul bahumu, lalu perlahan memutar dagumu, hingga pandanganmu tepat mengarah ke penyihir yang diam di depanmu."
  },
  AvgDialog_13736_Content_83 = {
    Text = "Demi kita semua yang masih atau pernah menjadi budak, aku beri sedikit petunjuk——"
  },
  AvgDialog_13736_Content_84 = {
    Text = [[
Kalau aku jadi kamu, sekarang sebaiknya tutup mulut.
Tahu orang macam apa yang paling dibenci orang itu?]]
  },
  AvgDialog_13736_Content_85 = {
    Text = "……Rasanya sungguh aneh dinasihati soal jaga bicara oleh orang seperti dia."
  },
  AvgDialog_13736_Content_86 = {
    Text = "……Silakan jelaskan."
  },
  AvgDialog_13736_Content_87 = {
    Text = "Ketiga, tentara bayaran Mamluk."
  },
  AvgDialog_13736_Content_88 = {
    Text = "Kedua, orang Lemwashi.\nKalau yang pertama……"
  },
  AvgDialog_13736_Content_89 = {
    Text = "Rasa sakit yang luar biasa menjalar dari bahu——Yuuhashi tertawa terbahak-bahak sambil menepuk bahumu dengan keras."
  },
  AvgDialog_13736_Content_9 = {
    Text = "Sinar matahari yang menyengat membuatmu pusing, kau menunduk menatap kedua tanganmu."
  },
  AvgDialog_13736_Content_90 = {
    Text = "<Big:Tentu saja tentara bayaran Mamluk dari Lemwashi!>"
  },
  AvgDialog_13736_Content_91 = {
    Text = "<Gray:……Bagus. Selain dia, seharusnya tidak ada yang bisa tertawa.>"
  },
  AvgDialog_13736_Content_92 = {
    Text = "<Gray:Kemampuan orang ini dalam menyinggung orang lain memang kelas satu.>"
  },
  AvgDialog_13736_Content_93 = {Text = "Heh……"},
  AvgDialog_13736_Content_94 = {
    Text = "Dulu tentara bayaran Mamluk membantai puluhan ribu bangsaku, istriku, rekan seperjuanganku, guruku…… semuanya tewas di sini."
  },
  AvgDialog_13736_Content_95 = {
    Text = "Baiklah, kisah tragis dariku sudah selesai, kalian boleh lanjut tertawa."
  },
  AvgDialog_13736_Content_96 = {
    Text = "Maaf, Tuan Purin. Izinkan saya menjelaskan, meskipun saya memiliki beberapa… hmm, masa lalu yang kurang membanggakan."
  },
  AvgDialog_13736_Content_97 = {
    Text = "Tapi itu semua sudah berlalu, dan tidak ada hubungannya dengan diriku yang sekarang."
  },
  AvgDialog_13736_Content_98 = {
    Text = "Purin melambaikan tangan ke arahmu."
  },
  AvgDialog_13736_Content_99 = {
    Text = "Wajahnya yang bulat di bawah terik matahari tampak seperti apel besar yang sudah matang sempurna — sayangnya, apel besar ini sedang tidak senang sekarang."
  },
  AvgDialog_13737_Content_1 = {
    Text = "Tirai Penutup Tragedi"
  },
  AvgDialog_13737_Content_10 = {
    Text = "<RedShake:Per...gi……>"
  },
  AvgDialog_13737_Content_11 = {
    Text = "Yuuhashi dengan ringan meremukkan otak si penghalang jalan, lalu perlahan berjalan menuju prajurit lainnya."
  },
  AvgDialog_13737_Content_12 = {
    Text = "<RedShake:Darah……aku butuh lebih banyak darah……>"
  },
  AvgDialog_13737_Content_13 = {
    Text = "Dia perlahan mengangkat tangannya."
  },
  AvgDialog_13737_Content_16 = {Text = "Kau……"},
  AvgDialog_13737_Content_17 = {
    Text = "Ya, ini aku."
  },
  AvgDialog_13737_Content_18 = {
    Text = "Kau berdiri menghalangi di antara mereka berdua, lalu menoleh ke belakang menatap prajurit yang ketakutan hingga berlutut di tanah."
  },
  AvgDialog_13737_Content_19 = {
    Text = "Cepat pergi. Larilah sejauh mungkin."
  },
  AvgDialog_13737_Content_2 = {
    Text = "Pinggiran Gurun Kusi, Medan Perang"
  },
  AvgDialog_13737_Content_20 = {
    Text = "<Big:Pergi!!>"
  },
  AvgDialog_13737_Content_21 = {
    Text = "<Shake:Ba-baik……aku pergi……>"
  },
  AvgDialog_13737_Content_22 = {
    Text = "Para prajurit pergi dengan tertatih-tatih sambil merangkak."
  },
  AvgDialog_13737_Content_23 = {
    Text = "Kenapa kau menghalangiku? Aku baru saja merasakan sedikit kenikmatan darah dan pertarungan……"
  },
  AvgDialog_13737_Content_24 = {
    Text = "Bukankah kau cuma ingin bertarung? Aku akan menemanimu."
  },
  AvgDialog_13737_Content_25 = {
    Text = "Kau? Hahahaha, memangnya kau siapa——"
  },
  AvgDialog_13737_Content_27 = {
    Text = "Kau menempelkan pedang lengkung ke leher Yuuhashi, dengan tenang menatap kedua matanya yang sudah kehilangan fokus."
  },
  AvgDialog_13737_Content_28 = {
    Text = "Kalau tidak dicoba, mana bisa tahu?"
  },
  AvgDialog_13737_Content_3 = {
    Text = "Hei, sudah dengar? Ada lagi yang mengamuk, membunuh siapa saja yang dilihat."
  },
  AvgDialog_13737_Content_4 = {
    Text = "Mereka bilang dia bukan orang Leo, juga bukan orang Lemwashi, entah muncul dari mana……"
  },
  AvgDialog_13737_Content_5 = {
    Text = "Pokoknya cepat pergi dari sini——"
  },
  AvgDialog_13737_Content_7 = {
    Text = "<Shake:Ka-kau, sejak kapan muncul di sini……>"
  },
  AvgDialog_13737_Content_8 = {
    Text = "Aaaaaah! Cepat——"
  },
  AvgDialog_13737_Content_9 = {Text = "——!!"},
  AvgDialog_13738_Content_1 = {
    Text = "Bagus, badai pasir pergi ke arah lain. Selanjutnya kita……"
  },
  AvgDialog_13738_Content_11 = {
    Text = "Bukankah kamu ingin pergi ke medan perang? Tentu saja kita harus maju mengikuti <Red:arah darah>."
  },
  AvgDialog_13738_Content_12 = {
    Text = "Arah darah……?"
  },
  AvgDialog_13738_Content_13 = {
    Text = "Kamu menunjuk ke arah punggung Uuhashi yang melangkah pergi dengan langkah lebar."
  },
  AvgDialog_13738_Content_14 = {Text = "arahnya."},
  AvgDialog_13738_Content_2 = {
    Text = "HOEK——!!"
  },
  AvgDialog_13738_Content_3 = {
    Text = "Purin menopang dirinya pada batang pohon yang gundul, membungkukkan badan dan mulai muntah hebat."
  },
  AvgDialog_13738_Content_4 = {
    Text = "Aku bersumpah, setelah urusan ini selesai. Aku bersumpah……"
  },
  AvgDialog_13738_Content_5 = {
    Text = "Kali ini, kutukan lemah sang penyihir tidak mendapat respons apa pun."
  },
  AvgDialog_13738_Content_6 = {
    Text = "Entah menemukan sesuatu, pupil mata Uuhashi tiba-tiba menyusut sesaat, nyaris tak terlihat."
  },
  AvgDialog_13738_Content_7 = {
    Text = "<Red:……Darah.>"
  },
  AvgDialog_13738_Content_8 = {
    Text = "Setelah berkata demikian, dia pergi tanpa menoleh ke belakang."
  },
  AvgDialog_13738_Content_9 = {
    Text = "Tunggu……! Tanpa izinku, kamu tidak boleh pergi ke mana pun!"
  },
  AvgDialog_13739_Content_1 = {
    Text = "Burung nasar menjerit keras di bawah cahaya senja merah darah, medan perang sudah lama kosong tanpa seorang pun."
  },
  AvgDialog_13739_Content_10 = {
    Text = "Selama pertarungan, kau jelas merasakan kondisi Yuuhashi menurun dengan kecepatan yang mengejutkan."
  },
  AvgDialog_13739_Content_11 = {
    Text = "Entah ini efek samping dari kontrak atau bukan, saat ini dia sudah berada di ujung kekuatannya."
  },
  AvgDialog_13739_Content_12 = {
    Text = "Pertarungan tentu saja baru menarik kalau seimbang, demi itu aku tidak keberatan menjadi sedikit lebih lemah."
  },
  AvgDialog_13739_Content_13 = {
    Text = "Aku tidak pernah peduli dengan pikiran manusia, sama seperti manusia tidak peduli dengan semut."
  },
  AvgDialog_13739_Content_14 = {
    Text = "Tapi kau berbeda. Di dalam dirimu ada kekuatan yang dahsyat, dan kau tahu cara mengendalikannya."
  },
  AvgDialog_13739_Content_15 = {
    Text = "Teruslah seperti itu, petarung. Keinginan-keinginan membosankanmu itu — matahari, kue-kue kecil dan semacamnya, mungkin benar-benar bisa terwujud."
  },
  AvgDialog_13739_Content_16 = {
    Text = "<Gray:Itu cuma omongan asal yang kuucapkan sembarangan, ternyata dia masih mengingatnya……>"
  },
  AvgDialog_13739_Content_17 = {
    Text = "Pergilah…… ke tempat yang pernah kau sebut, tempat yang ada mataharinya."
  },
  AvgDialog_13739_Content_18 = {Text = "?!"},
  AvgDialog_13739_Content_19 = {
    Text = "Lalu bagaimana denganmu?"
  },
  AvgDialog_13739_Content_2 = {
    Text = "Kau dan Yuuhashi berdiri dengan jarak kurang dari sepuluh yard, saling menatap dalam diam."
  },
  AvgDialog_13739_Content_20 = {
    Text = "Aku……? Si tua bangka itu menyimpan satu trik terakhir, aku tidak akan hidup lama lagi. Hehe……"
  },
  AvgDialog_13739_Content_21 = {
    Text = "Si tua bangka dan aku harus sama-sama mati…… itulah harga sesungguhnya untuk memutus kontrak."
  },
  AvgDialog_13739_Content_22 = {
    Text = "Dengan langkah yang berat, dia perlahan berjalan menghampirimu."
  },
  AvgDialog_13739_Content_23 = {
    Text = "Kemudian dia menggigit pergelangan tangannya sendiri hingga terbuka."
  },
  AvgDialog_13739_Content_24 = {
    Text = "Darah segar yang merah menyala dan menyengat hidung mengalir deras, menetes ke atas kepalamu, ke kelopak matamu, lalu mengalir turun melalui batang hidungmu hingga ke bibirmu yang kering."
  },
  AvgDialog_13739_Content_25 = {
    Text = "Darah ini…… anggap saja sebagai hadiah perpisahan dariku."
  },
  AvgDialog_13739_Content_26 = {
    Text = "Burung-burung nasar berputar-putar di atas kepalanya, jelas sudah mengincar mangsa yang hampir mati."
  },
  AvgDialog_13739_Content_27 = {
    Text = "Aku terlahir dari ribuan daging dan darah, mengembara di dunia ini selama hampir seribu tahun……"
  },
  AvgDialog_13739_Content_28 = {
    Text = "Aku pernah melihat lembaran emas berterbangan di langit saat parade kemenangan, juga pernah melihat istana emas terbakar dalam kobaran api."
  },
  AvgDialog_13739_Content_29 = {
    Text = "Aku pernah menikmati darah yang paling lezat, juga pernah mengalami pertempuran yang paling brutal."
  },
  AvgDialog_13739_Content_3 = {
    Text = "Hei……sudah berapa lama kita bertarung?"
  },
  AvgDialog_13739_Content_30 = {
    Text = "Aku membantai manusia, juga dibelenggu dan dimanfaatkan oleh manusia, lalu tanpa kejutan akhirnya mati di tangan manusia."
  },
  AvgDialog_13739_Content_31 = {
    Text = "Sekarang, sudah waktunya bagiku untuk pergi……"
  },
  AvgDialog_13739_Content_32 = {
    Text = "Dia memandangmu dari atas, tanpa emosi apa pun di matanya."
  },
  AvgDialog_13739_Content_33 = {
    Text = "Darah kental menetes perlahan dari ujung hidungmu ke tanah."
  },
  AvgDialog_13739_Content_34 = {
    Text = "Kau seperti seorang calon baptis yang polos, bingung dan tak berdaya menghadapi semua yang terjadi di depan matamu."
  },
  AvgDialog_13739_Content_35 = {
    Text = "Aku kembalikan darah dan dagingku kepadamu, kepada dunia ini."
  },
  AvgDialog_13739_Content_36 = {
    Text = "Semuanya milik langit, milik bumi…… milikmu, tapi bukan milikku."
  },
  AvgDialog_13739_Content_37 = {
    Text = "Sekarang kau boleh pergi…… pergilah tanpa menoleh ke belakang."
  },
  AvgDialog_13739_Content_38 = {
    Text = [[
Pandanganmu akhirnya tertutupi kabut darah yang pekat.
Kau memejamkan mata, merasakan gelombang pusing yang datang silih berganti, seolah bumi terus tenggelam.]]
  },
  AvgDialog_13739_Content_39 = {
    Text = "Cerita setelahnya sudah tak begitu kau ingat lagi."
  },
  AvgDialog_13739_Content_40 = {
    Text = "Mungkin kau sudah lama pergi, mungkin kau mati bersamanya di padang pasir ini."
  },
  AvgDialog_13739_Content_41 = {
    Text = "Semua itu tidak penting. Karena kau akan selalu mengingat saat-saat terakhirnya sebelum kematian."
  },
  AvgDialog_13739_Content_42 = {
    Text = "Saat itu sekawanan burung nasar hitam terbang melintas, tepat menghalangi cahaya senja di belakangnya."
  },
  AvgDialog_13739_Content_43 = {
    Text = "Cahaya terus meredup, bayangan menyelimuti sekitar, dan dia berlutut di tengah bayangan itu sambil menatapmu."
  },
  AvgDialog_13739_Content_44 = {
    Text = "Dia berkata——"
  },
  AvgDialog_13739_Content_45 = {Text = "Pergilah."},
  AvgDialog_13739_Content_46 = {
    Text = "Pergilah ke tempat terkutuk yang ada mataharinya itu."
  },
  AvgDialog_13739_Content_5 = {
    Text = "Siapa yang tahu…… satu jam, satu hari?"
  },
  AvgDialog_13739_Content_7 = {
    Text = "Seribu tahun…… sudah hampir seribu tahun aku tidak menikmati pertarungan yang begitu memuaskan seperti ini."
  },
  AvgDialog_13739_Content_8 = {
    Text = "Kau adalah petarung sejati."
  },
  AvgDialog_13739_Content_9 = {
    Text = "Sungguh mengejutkan, sejak kapan kau belajar mengucapkan pujian seperti manusia."
  },
  AvgDialog_138765_Content_1 = {
    Text = "Bara dimensi sedang mengalir. Roda takdir, Moirai, telah berputar di sini."
  },
  AvgDialog_138765_Content_2 = {
    Text = "Ambillah risiko itu, Penjaga Rahasia{Male=先生,Female=小姐}. Aku akan membantumu memperbaiki takdir yang keliru, dan menghancurkan kepompong-kepompong yang seharusnya tidak ada."
  },
  AvgDialog_138765_Content_3 = {
    Text = "Arah takdir tidak pernah ditenun oleh orang lain."
  },
  AvgDialog_138766_Content_1 = {
    Text = "Ini…… sudah berakhir?"
  },
  AvgDialog_138766_Content_2 = {
    Text = "Hati-hati, Penjaga Rahasia…… roda pemintal yang menghancurkan takdir, sudah berputar di belakangnya……"
  },
  AvgDialog_138766_Content_3 = {
    Text = "Hehe…… Hahahaha……!"
  },
  AvgDialog_138766_Content_4 = {
    Text = "\"Lihatlah! Wahai para pengikut bodoh takdir, lonceng kematian yang ditakdirkan telah berdentang!\""
  },
  AvgDialog_138766_Content_5 = {
    Text = "\"Akulah akhir dari segalanya—akulah takdir—akulah @4!\""
  },
  AvgDialog_138766_Content_6 = {
    Text = "\"Sekarang, akhir yang mahatinggi itu, pembebasan yang kalian dambakan itu, akan kuanugerahkan kepada kalian!!!\""
  },
  AvgDialog_13946_Content_1 = {
    Text = "Lautan Tanpa Sandaran"
  },
  AvgDialog_13946_Content_10 = {
    Text = "Mengirimmu untuk \"mengawal\" aku mencari penyihir?\nBenar-benar menggelikan. Niat mereka sudah jelas sekali……"
  },
  AvgDialog_13946_Content_11 = {
    Text = "Goliath mengeluarkan suara rintihan kesakitan. Di bawah tubuhnya, genangan darah merah gelap perlahan meluas, mengalir hingga ke kakimu."
  },
  AvgDialog_13946_Content_12 = {
    Text = "<Red:Mereka ingin kita mati bersama di lautan ini.>"
  },
  AvgDialog_13946_Content_13 = {
    Text = "Tuan, Anda terluka sangat parah! Apa yang terjadi……"
  },
  AvgDialog_13946_Content_14 = {
    Text = "Ingatan yang kacau membanjiri benakmu."
  },
  AvgDialog_13946_Content_15 = {
    Text = "Dalam pertempuran krusial sebelumnya, pemimpin Goliath kalah dari suku musuh karena meremehkan lawan."
  },
  AvgDialog_13946_Content_16 = {
    Text = "Bangsa Filistin tidak menerima kekalahan. Goliath yang terluka parah dibuang dengan kejam, ditemani hanya sebuah perahu kecil yang lapuk, dan kamu——"
  },
  AvgDialog_13946_Content_17 = {
    Text = "Orang Filistin yang paling lemah, bahkan gulat pun bisa kalah dari anak berusia sepuluh tahun."
  },
  AvgDialog_13946_Content_18 = {
    Text = "Aku ingat ketua <Blue:Igelun> pernah berkata, di perairan sekitar ada seorang penyihir misterius, dia menggunakan semacam cairan kental hitam……"
  },
  AvgDialog_13946_Content_19 = {
    Text = "Asalkan cairan itu dituangkan ke luka, luka Tuan pasti bisa sembuh!"
  },
  AvgDialog_13946_Content_2 = {
    Text = [[
Mendesah untuk Rasul Lautan.
Mendesah untuk cahaya kita, harapan kita.

Karena takdir dibuang ke lautan, kami meraung, meratap, dan menangis hingga air mata habis.]]
  },
  AvgDialog_13946_Content_20 = {
    Text = "Kamu secara refleks menceritakan legenda tentang penyihir itu, baru kemudian menyadari ada sesuatu yang janggal."
  },
  AvgDialog_13946_Content_21 = {
    Text = "<Gray:Tunggu, jangan-jangan cairan kental itu adalah Cairan Korosi……>"
  },
  AvgDialog_13946_Content_22 = {
    Text = "Ketua, Igelun?"
  },
  AvgDialog_13946_Content_23 = {
    Text = "Senyum perlahan muncul di wajah dingin Goliath."
  },
  AvgDialog_13946_Content_24 = {
    Text = "Sepertinya dia sudah menjadi ketua baru kalian. Sangat efisien, memang pantas menjadi anggota sukuku yang paling tercinta."
  },
  AvgDialog_13946_Content_25 = {Text = "BRASSHH!!"},
  AvgDialog_13946_Content_26 = {
    Text = "Perahu kecil yang sudah lapuk akhirnya tak sanggup menahan hantaman ombak, pecah membentuk lubang besar, dan air laut terus-menerus membanjiri masuk."
  },
  AvgDialog_13946_Content_27 = {
    Text = "Tch, sudah kuduga."
  },
  AvgDialog_13946_Content_28 = {
    Text = "Gawat, kita bisa tenggelam! Harus segera cari sesuatu untuk menambal lubangnya……"
  },
  AvgDialog_13946_Content_29 = {Text = "……Oh."},
  AvgDialog_13946_Content_3 = {
    Text = [[
Oh, lindungilah mereka yang tertimpa bencana!
Arahkan tatapan belas kasihan kepada kami, karuniakan sumber kehidupan hitam kepada kami.]]
  },
  AvgDialog_13946_Content_30 = {
    Text = "Goliath bersandar malas di dek kapal, membiarkan darah di bawahnya mewarnai air laut yang masuk menjadi merah."
  },
  AvgDialog_13946_Content_31 = {
    Text = "Tenang saja. Bahkan kalau kita berhasil memperbaiki kapal ini, mereka punya sejuta cara untuk membuatku mati di lautan ini."
  },
  AvgDialog_13946_Content_32 = {
    Text = "Saranku, jangan pedulikan aku lagi. Turun dari kapal, lalu berenang sendiri kembali."
  },
  AvgDialog_13946_Content_33 = {
    Text = "Bilang pada mereka bahwa kau sudah membunuhku. Kalau beruntung, mungkin kau masih bisa selamat."
  },
  AvgDialog_13946_Content_34 = {
    Text = "Lalu kau……?"
  },
  AvgDialog_13946_Content_35 = {Text = "Aku?"},
  AvgDialog_13946_Content_36 = {
    Text = "Goliath dengan santai menikmati pemandangan di atas permukaan laut, lalu menoleh ke arahmu sambil tersenyum tipis."
  },
  AvgDialog_13946_Content_37 = {
    Text = "Duduk di sini menikmati lautan, sambil menunggu ajal."
  },
  AvgDialog_13946_Content_38 = {Text = "...?"},
  AvgDialog_13946_Content_39 = {
    Text = "<Gray:Sepesimis ini, apakah ini benar-benar Goliath yang kukenal?>"
  },
  AvgDialog_13946_Content_4 = {
    Text = "<Red:Belas kasihan, belas kasihan, belas kasihan……>"
  },
  AvgDialog_13946_Content_40 = {
    Text = "Oh ya, ada satu hal lagi yang harus kuperingatkan."
  },
  AvgDialog_13946_Content_41 = {
    Text = "Ada lubang di belakang bokongmu. Berdasarkan pengalamanku, kapal ini akan segera patah menjadi dua, waktu yang tersisa untuk berpikir sudah tidak banyak lagi."
  },
  AvgDialog_13946_Content_42 = {Text = "BRASSHH!!"},
  AvgDialog_13946_Content_43 = {
    Text = "Seolah membuktikan bahwa perkataan Goliath bukan omong kosong, sebuah ombak besar menghantam, dan perahu kayu itu seketika pecah menjadi dua."
  },
  AvgDialog_13946_Content_44 = {
    Text = "<Shake:AAAAAAH——!!>"
  },
  AvgDialog_13946_Content_45 = {
    Text = "Air laut yang asin dan amis terus mengalir masuk ke paru-parumu. Kau membuka mulut, tetapi justru semakin banyak air laut yang menelanmu sepenuhnya."
  },
  AvgDialog_13946_Content_46 = {
    Text = "Tubuhmu terus tenggelam, napas menjadi semakin sulit……"
  },
  AvgDialog_13946_Content_47 = {
    Text = "Di antara kesadaran yang memudar, kau seperti mendengar suara helaan napas yang pasrah."
  },
  AvgDialog_13946_Content_48 = {
    Text = "Belum sempat bereaksi, sebuah tenaga besar tiba-tiba menarik rambutmu dengan kuat, mengangkatmu keluar dari laut dengan mudah."
  },
  AvgDialog_13946_Content_49 = {
    Text = "Uhuk uhuk……Hoek!"
  },
  AvgDialog_13946_Content_50 = {
    Text = "Pegangan yang erat, ini satu-satunya penyelamat kita berdua."
  },
  AvgDialog_13946_Content_51 = {
    Text = "Kau menoleh ke sekeliling, baru menyadari bahwa kau dan Goliath berdesakan di atas sebuah papan kayu yang goyah."
  },
  AvgDialog_13946_Content_52 = {
    Text = "Apa-apaan ini…… Orang Filistin yang mahir berenang dan mengarungi empat samudra, masa tidak bisa berenang?"
  },
  AvgDialog_13946_Content_53 = {
    Text = "Kau benar-benar orang Filistin?"
  },
  AvgDialog_13946_Content_54 = {
    Text = "<SmallShake:Maaf, tubuh saya sejak kecil memang sering sakit-sakitan……>"
  },
  AvgDialog_13946_Content_55 = {
    Text = "Terima kasih, Tuan. Kalau bukan karena Anda, saya sudah mati di sini……"
  },
  AvgDialog_13946_Content_56 = {
    Text = "……Sepertinya kau bukan orang yang mereka kirim untuk membunuhku."
  },
  AvgDialog_13946_Content_57 = {
    Text = "Naluri bertahan hidupmu tadi sangat kuat, tidak seperti sandiwara."
  },
  AvgDialog_13946_Content_58 = {
    Text = "Goliath menyeka rambut basah di dahinya, lalu memandang ke arah lautan yang diselimuti kabut di hadapannya."
  },
  AvgDialog_13946_Content_59 = {
    Text = "Saat jatuh ke laut, kau seperti kepiting besar yang mencengkeram tubuhku erat-erat, tak mau melepaskan sedetik pun. Kenapa?"
  },
  AvgDialog_13946_Content_6 = {
    Text = "Sudah bangun?"
  },
  AvgDialog_13946_Content_60 = {
    Text = "Eh? Tentu saja demi bertahan hidup……"
  },
  AvgDialog_13946_Content_61 = {
    Text = "Bertahan hidup…… Tapi kau hidup pun juga tidak berguna, kau bahkan tidak bisa berenang."
  },
  AvgDialog_13946_Content_62 = {
    Text = "Sebenarnya untuk apa kau hidup?"
  },
  AvgDialog_13946_Content_63 = {
    Text = "Suara Goliath perlahan melemah, seolah bertanya kepadamu, sekaligus bertanya kepada dirinya sendiri."
  },
  AvgDialog_13946_Content_64 = {
    Text = "Diusir oleh kaumnya sendiri, terluka parah, saat ini jalan di hadapannya bagaikan lautan berkabut tebal di depan mata, hanya menyisakan keputusasaan tanpa akhir."
  },
  AvgDialog_13946_Content_66 = {
    Text = "Tuan bilang ingin menunggu ajal, tapi ketika ombak benar-benar datang menerjang, Tuan tidak hanya menemukan papan kayu ini dan naik ke atasnya, tapi juga menyelamatkan saya."
  },
  AvgDialog_13946_Content_67 = {
    Text = "……Itu karena kau terus menempel padaku dan tidak mau lepas."
  },
  AvgDialog_13946_Content_68 = {
    Text = "Semua itu tidak penting. Yang penting adalah berkat Tuan, kita berdua sekarang masih hidup."
  },
  AvgDialog_13946_Content_69 = {
    Text = "Menurut Anda, kenapa bisa begitu?"
  },
  AvgDialog_13946_Content_7 = {
    Text = "Air laut menggulung ombak yang terpanggang panas oleh sinar matahari, angin laut yang sedikit asin membawa bau amis yang pekat ke hidung."
  },
  AvgDialog_13946_Content_70 = {
    Text = "Goliath menggelengkan kepalanya."
  },
  AvgDialog_13946_Content_71 = {
    Text = "Jujur, aku juga tidak tahu. Tapi aku menyadari satu hal……"
  },
  AvgDialog_13946_Content_72 = {
    Text = "Goliath menundukkan kepala, memandangmu dengan tatapan penuh makna."
  },
  AvgDialog_13946_Content_73 = {
    Text = "Sekarang aku paham kenapa sampah sepertimu bisa bertahan hidup sampai sekarang."
  },
  AvgDialog_13946_Content_8 = {
    Text = "<Gray:Ini… masuk ke dalam mimpi?>"
  },
  AvgDialog_13946_Content_9 = {
    Text = "Memang pantas dijuluki si sakit-sakitan terkenal di suku, satu ombak besar saja sudah membuatmu pingsan setengah hari."
  },
  AvgDialog_13947_Content_1 = {
    Text = "Kisah Sang Raksasa"
  },
  AvgDialog_13947_Content_10 = {
    Text = "Hanya orang bodoh yang mempercayakan nyawanya pada orang lain."
  },
  AvgDialog_13947_Content_11 = {
    Text = "<Gray:Penyihir…>"
  },
  AvgDialog_13947_Content_12 = {
    Text = "Berdasarkan arsip Kebangkitan Goliath, \"penyihir\" yang dimaksud sudah pasti adalah Miriam."
  },
  AvgDialog_13947_Content_13 = {
    Text = "Meskipun perkembangan selanjutnya tidak sesuai harapan, Miriam memang telah menyelamatkan nyawa Goliath."
  },
  AvgDialog_13947_Content_14 = {
    Text = "Tuan, Anda terluka parah. Saat ini sepertinya tidak ada cara lain, bagaimana kalau kita mencari penyihir itu bersama—"
  },
  AvgDialog_13947_Content_15 = {Text = "Bumm!!"},
  AvgDialog_13947_Content_16 = {
    Text = "Disertai hentakan yang kuat, tenggorokanmu yang rapuh dicekik dengan keras. Kakimu terangkat dari tanah saat kau diangkat ke hadapan sang raksasa."
  },
  AvgDialog_13947_Content_17 = {
    Text = "Aku hanya akan mengatakannya sekali: jangan tatap aku dengan pandangan seperti itu, dan jangan bicara padaku dengan nada seperti itu."
  },
  AvgDialog_13947_Content_18 = {
    Text = "Yang paling tidak dibutuhkan oleh Goliath ini adalah belas kasihan dari yang lemah."
  },
  AvgDialog_13947_Content_19 = {
    Text = "Nada bicara Goliath datar, ekspresinya biasa saja, seolah hanya sedang membicarakan cuaca denganmu."
  },
  AvgDialog_13947_Content_2 = {
    Text = "Sinar matahari memanggang permukaan laut, seolah ingin melenyapkan segala kehidupan dalam panas yang tak berujung."
  },
  AvgDialog_13947_Content_20 = {
    Text = "Tapi kalian begitu dekat, cukup dekat hingga kau bisa melihat dengan jelas lingkar matanya yang memerah karena rasa sakit dan ketidakrelaan."
  },
  AvgDialog_13947_Content_21 = {
    Text = "Pada saat ini, ia seolah telah menanggalkan segala kemuliaan sebagai penguasa lautan, menjadi ikan yang tersesat di samudra tak berujung ini—sama sepertimu."
  },
  AvgDialog_13947_Content_22 = {
    Text = "Maaf……eh, Tuan……"
  },
  AvgDialog_13947_Content_23 = {
    Text = "<Shake:Wuuu——>"
  },
  AvgDialog_13947_Content_24 = {
    Text = "Suara tanduk yang rendah terdengar samar dari kejauhan."
  },
  AvgDialog_13947_Content_25 = {
    Text = "Lehermu tiba-tiba terasa ringan. Goliath melepaskan tangannya dan menatap ke arah suara tanduk itu berasal."
  },
  AvgDialog_13947_Content_26 = {
    Text = "<Gray:Uhuk uhuk……hah, selamat……>"
  },
  AvgDialog_13947_Content_27 = {
    Text = "Menarik……mereka khawatir aku mati kurang cepat, jadi sengaja datang beramai-ramai untuk mengantarku ke liang kubur?"
  },
  AvgDialog_13947_Content_28 = {
    Text = "Tak lama kemudian, armada kapal yang megah telah mengepung kalian di tengah-tengah. Papan kayu yang terombang-ambing menjadi satu-satunya pulau terpencil di perairan ini."
  },
  AvgDialog_13947_Content_29 = {
    Text = "Kalian sudah terjebak dalam kepungan."
  },
  AvgDialog_13947_Content_3 = {
    Text = "Papan kayu yang kau dan Goliath pegangan menjadi satu-satunya pulau di tengah lautan. Menatap matahari yang terik di atas kepala, kau kembali merasakan gelombang pusing yang datang silih berganti."
  },
  AvgDialog_13947_Content_30 = {
    Text = "Izinkan aku memperkenalkan dengan meriah, pemimpin paling perkasa dalam sejarah Filistin! Raksasa berkekuatan besar dengan kehendak yang tak terpatahkan! Pahlawan suku yang mengguncang empat penjuru lautan dan memandang rendah segalanya——"
  },
  AvgDialog_13947_Content_31 = {
    Text = "<BigShake:Tuan Goliath!>"
  },
  AvgDialog_13947_Content_32 = {
    Text = "Cahaya matahari yang terpantul dari permukaan laut terlalu menyilaukan. Kamu hanya bisa melihat sekilas siluet hitam berdiri di haluan kapal, memandang kalian dari atas."
  },
  AvgDialog_13947_Content_33 = {
    Text = "Saudara-saudara yang baru bergabung mungkin belum tahu, tuan yang terhormat ini terluka parah dalam sebuah duel dan nyaris tertawan, menyebabkan seluruh suku kita jatuh ke dalam kebinasaan yang belum pernah terjadi sebelumnya!"
  },
  AvgDialog_13947_Content_34 = {
    Text = "Kehancuran yang begitu dekat telah menelan sebagian besar anggota suku! Terpujilah engkau! Tuan Goliath yang paling kuhormati!"
  },
  AvgDialog_13947_Content_35 = {
    Text = "Heh heh……prestasi sebesar ini mana berani aku nikmati sendiri, Igrun?"
  },
  AvgDialog_13947_Content_36 = {
    Text = "Dulu siapa yang bersembunyi di belakangku dan tak berani mengerahkan pasukan, dan siapa yang pertama kali membuang senjata sambil menangis meraung berlari pulang?"
  },
  AvgDialog_13947_Content_37 = {Text = "Kau……!"},
  AvgDialog_13947_Content_38 = {
    Text = "Wajah Igrun memerah menahan amarah, bola matanya yang keruh bergetar tak henti, dan akhirnya tertuju padamu."
  },
  AvgDialog_13947_Content_39 = {
    Text = "Oh, Tuan Pemimpin yang agung, meskipun sukunya sudah bubar, tetap masih memiliki seorang……pengikut yang sangat manis."
  },
  AvgDialog_13947_Content_4 = {
    Text = "<Shake:Maaf, aku kurang enak badan… biarkan aku tidur sebentar…>"
  },
  AvgDialog_13947_Content_40 = {
    Text = "Aib bangsa Filistin——sampah yang bahkan tak sanggup menerima satu pukulan pun di dalam suku, tapi ingin mengikutimu menjadi pejuang……"
  },
  AvgDialog_13947_Content_41 = {
    Text = "Hahahaha……!!"
  },
  AvgDialog_13947_Content_42 = {
    Text = "Goliath mendongak, menatapmu dengan terkejut dari balik gelak tawa kerumunan."
  },
  AvgDialog_13947_Content_43 = {
    Text = "Nak kecil, kau secara sukarela mengikutiku kemari?"
  },
  AvgDialog_13947_Content_44 = {
    Text = "<Gray:Ehm... kalau tidak salah ingat, memang begitu...>"
  },
  AvgDialog_13947_Content_45 = {
    Text = "Mengharukan, bukan? Aku hanya asal menyebut soal penyihir, dan si bodoh kecil ini langsung mempercayainya, dengan penuh harap ingin ikut denganmu kemari..."
  },
  AvgDialog_13947_Content_46 = {
    Text = "Ditahan pun tak bisa, haha——"
  },
  AvgDialog_13947_Content_47 = {Text = "BRASSHH!!"},
  AvgDialog_13947_Content_48 = {
    Text = "Tawa terhenti seketika. Angin ganas meraung menerjang, dan sepotong kaki yang terputus seketika menggelinding di hadapan semua orang."
  },
  AvgDialog_13947_Content_49 = {
    Text = "Aaaaah... kakiku, KAKIKU!!"
  },
  AvgDialog_13947_Content_5 = {
    Text = "Sebuah jubah yang bercampur keringat dan bau amis darah menutupi kepalamu, baunya membuatmu langsung terlonjak bangun."
  },
  AvgDialog_13947_Content_50 = {
    Text = "Sang penguasa lautan masa lalu berdiri tegak bagai gunung di hadapan Igren, memancarkan aura yang membuat siapa pun gemetar ketakutan."
  },
  AvgDialog_13947_Content_51 = {
    Text = "Sejak tadi, ada seekor lalat yang terus terbang bolak-balik di telingaku..."
  },
  AvgDialog_13947_Content_52 = {
    Text = "Goliath dengan santai mengusap noda darah di mata pisaunya, lalu mendongak dan tersenyum dingin ke arah Igren."
  },
  AvgDialog_13947_Content_53 = {
    Text = "Igren, tadi aku bertanya padamu, hah?"
  },
  AvgDialog_13947_Content_6 = {
    Text = "Uhuk uhuk……Hoek!"
  },
  AvgDialog_13947_Content_7 = {
    Text = "Kau terkena sengatan matahari. Tutupi kepalamu dengan ini untuk menghalangi matahari, jangan dilepas."
  },
  AvgDialog_13947_Content_8 = {
    Text = "Memang pantas pakaian yang pernah dikenakan Tuan, benar-benar menyegarkan pikiran…\nSelanjutnya kita harus ke mana? Mencari penyihir?"
  },
  AvgDialog_13947_Content_9 = {
    Text = "Penyihir apaan? Jangan bilang kau benar-benar percaya omong kosong mereka."
  },
  AvgDialog_13948_Content_1 = {
    Text = "Melodi Keemasan"
  },
  AvgDialog_13948_Content_10 = {
    Text = "Ketenangan pucat di permukaan laut pecah. Ular laut berwarna ungu kehitaman tiba-tiba menyembur keluar, melilit semua orang dengan erat."
  },
  AvgDialog_13948_Content_11 = {
    Text = "Ugh… AAAAAAAH!!"
  },
  AvgDialog_13948_Content_12 = {
    Text = "Diiringi suara samar yang aneh, tubuh ular berubah menjadi bilah hitam pekat yang menembus tubuh manusia sepenuhnya."
  },
  AvgDialog_13948_Content_13 = {
    Text = "<Big:Menyingkir>… Eh?"
  },
  AvgDialog_13948_Content_15 = {
    Text = "Sentuhan lembut dan dingin terasa di leher yang dililit ular hitam, dan luka-luka itu perlahan mulai sembuh."
  },
  AvgDialog_13948_Content_16 = {
    Text = "Luka-lukaku… semuanya sembuh?"
  },
  AvgDialog_13948_Content_17 = {
    Text = "Ular hitam itu meninggalkan kalian tanpa ragu, lalu dengan kecepatan luar biasa melilit Igren dengan erat."
  },
  AvgDialog_13948_Content_18 = {
    Text = "Cepat lari, penyihir itu da… tang…"
  },
  AvgDialog_13948_Content_19 = {
    Text = "Ular-ular hitam merayap keluar dari mata dan mulut Igren. Dia bahkan tidak sempat mengucapkan satu kalimat utuh sebelum ambruk tak berdaya."
  },
  AvgDialog_13948_Content_2 = {
    Text = [[
Mendesah untuk Rasul Lautan.
Mendesah untuk cahaya kita, harapan kita.

Karena takdir dibuang ke lautan, kami meraung, meratap, dan menangis hingga air mata habis.]]
  },
  AvgDialog_13948_Content_20 = {
    Text = "Tak lama kemudian, jasad-jasad yang hancur tak terhitung jumlahnya mengapung di permukaan laut."
  },
  AvgDialog_13948_Content_21 = {
    Text = "Ini adalah pembantaian yang sunyi."
  },
  AvgDialog_13948_Content_22 = {
    Text = "<Gray:Sudah selesai? Hebat sekali, memang pantas disebut Miriam.>"
  },
  AvgDialog_13948_Content_23 = {
    Text = "Kau membantu kami… Siapa kau?"
  },
  AvgDialog_13948_Content_24 = {
    Text = "Wanita berkerudung hitam itu tidak berkata apa-apa. Dia berdiri tegak di haluan kapal, di antara kalian hanya terhalang selapis kabut tebal."
  },
  AvgDialog_13948_Content_25 = {
    Text = "Tampak begitu dekat, namun terasa jauh tak terjangkau."
  },
  AvgDialog_13948_Content_26 = {
    Text = "Wanita itu menatap Goliath yang terpaku, sudut bibirnya menyunggingkan senyuman. Ia mengulurkan tangan menunjuk ke kejauhan, seolah sebuah undangan tanpa kata."
  },
  AvgDialog_13948_Content_27 = {
    Text = "Kemudian ia memutar haluan perahunya dan pergi dengan tenang."
  },
  AvgDialog_13948_Content_28 = {
    Text = "Tunggu, jangan pergi… <Big:Jangan pergi!>"
  },
  AvgDialog_13948_Content_29 = {
    Text = "Kabut menghilang, seberkas cahaya menembus celah awan, dan buih ombak berkilau bagai emas."
  },
  AvgDialog_13948_Content_3 = {
    Text = "Pandangan tiba-tiba meredup, cahaya matahari yang menyilaukan perlahan menghilang, kabut pekat menyelimuti seluruh permukaan laut."
  },
  AvgDialog_13948_Content_30 = {
    Text = "Kau mengerjapkan mata, di ujung lautan sudah tak ada siapa pun."
  },
  AvgDialog_13948_Content_31 = {
    Text = "Angin dan ombak berangsur mereda, kau dan Goliath berdesakan di satu-satunya papan yang masih utuh, terus terengah-engah."
  },
  AvgDialog_13948_Content_32 = {
    Text = "Lautan yang semula biru telah diwarnai merah oleh darah, kalian berdua bagaikan rumput apung yang terhanyut di dalamnya."
  },
  AvgDialog_13948_Content_33 = {
    Text = "Pada akhirnya tetap tidak berhasil mendapatkan kapal… Sekarang entah bagaimana caranya pulang."
  },
  AvgDialog_13948_Content_34 = {
    Text = "Tidak usah pulang."
  },
  AvgDialog_13948_Content_35 = {
    Text = "Goliath menopang satu kakinya, menatap kosong ke arah kepergian Miriam."
  },
  AvgDialog_13948_Content_36 = {
    Text = "Aku sudah memutuskan, aku akan mencari penyihir itu. Mau ikut denganku?"
  },
  AvgDialog_13948_Content_37 = {
    Text = "Uhuk uhuk, \"Hanya orang bodoh yang mempercayakan nyawanya pada orang lain.\""
  },
  AvgDialog_13948_Content_38 = {
    Text = "Kau sengaja merendahkan suaramu, menirukan nada bicara Goliath sebelumnya dan mengulang kata-katanya."
  },
  AvgDialog_13948_Content_39 = {
    Text = "Hmph, itu karena taruhannya belum cukup besar. Kekuatan yang bisa menghancurkan segalanya dalam sekejap seperti itu, aku belum pernah melihatnya."
  },
  AvgDialog_13948_Content_4 = {
    Text = "Oh, lindungilah mereka yang tertimpa banyak bencana.\nArahkan tatapan belas kasihmu kepada kami…"
  },
  AvgDialog_13948_Content_40 = {
    Text = "Lagipula, tadi dia membantu kita, dan bahkan mengundangku…"
  },
  AvgDialog_13948_Content_41 = {
    Text = "Tapi bagaimana kalau… itu jebakan?"
  },
  AvgDialog_13948_Content_42 = {Text = "Jebakan…"},
  AvgDialog_13948_Content_43 = {
    Text = "Masih ingat pertanyaan yang kau ajukan padaku sebelumnya?"
  },
  AvgDialog_13948_Content_44 = {
    Text = "…Yang penting adalah berkat Tuan, kita berdua sekarang masih hidup."
  },
  AvgDialog_13948_Content_45 = {
    Text = "Menurut Anda, kenapa bisa begitu?"
  },
  AvgDialog_13948_Content_46 = {
    Text = "Sekarang aku tahu jawabannya."
  },
  AvgDialog_13948_Content_47 = {
    Text = "Apa jawabannya?"
  },
  AvgDialog_13948_Content_48 = {
    Text = "Sekawanan burung laut tiba-tiba terbang mendekat secara bergerombol. Sayap putih yang mengepak bagaikan awan yang terbang, berkibar bebas di tengah angin laut."
  },
  AvgDialog_13948_Content_49 = {
    Text = "Goliath sama sekali tidak terganggu oleh kawanan burung itu. Ia menatap lurus ke depan dengan penuh fokus, matanya berkilau penuh semangat."
  },
  AvgDialog_13948_Content_5 = {
    Text = "Nyanyian kuno nan misterius mengambang di udara. Sosok wanita yang berdiri di haluan kapal tampak samar-samar, bagaikan hantu yang berkeliaran di dalam kabut."
  },
  AvgDialog_13948_Content_50 = {
    Text = "Karena aku adalah Goliath."
  },
  AvgDialog_13948_Content_51 = {
    Text = "Pemimpin dengan masa pemerintahan terlama dalam sejarah Filistin, raksasa perkasa dengan kehendak tak terpatahkan, pahlawan suku yang disegani di seluruh penjuru — Goliath sang Raksasa."
  },
  AvgDialog_13948_Content_52 = {
    Text = "Meskipun hanya tersisa satu pengikut, selama masih ada secercah kesempatan terakhir, aku bisa bangkit kembali."
  },
  AvgDialog_13948_Content_53 = {
    Text = "Penyihir itu adalah kesempatan terakhirku. Hanya dia yang bisa memberiku kekuatan absolut."
  },
  AvgDialog_13948_Content_54 = {
    Text = "Meskipun itu jebakan, aku tetap akan pergi."
  },
  AvgDialog_13948_Content_55 = {
    Text = "Lalu kenapa kau menyelamatkanku? \"Sampah\" sepertiku mungkin tidak bisa membantumu sama sekali…"
  },
  AvgDialog_13948_Content_56 = {
    Text = "Kau sengaja menekankan pengucapan kata tertentu, membuat Goliath tertawa terbahak-bahak."
  },
  AvgDialog_13948_Content_57 = {
    Text = "Sinar matahari menembus awan dan menyinari segalanya dengan cahaya keemasan. Helai-helai rambut yang berantakan menari lembut di bawah langit biru."
  },
  AvgDialog_13948_Content_58 = {
    Text = "Mana ada di dunia ini pemimpin tanpa pengikut yang bisa mencapai sesuatu."
  },
  AvgDialog_13948_Content_59 = {
    Text = [[
Si Kecil, kau bukan sampah.
Kau adalah satu-satunya pengikut Goliath sang Raksasa, tak ada yang bisa menggantikanmu.]]
  },
  AvgDialog_13948_Content_6 = {
    Text = "Eh, ada seseorang yang bernyanyi?"
  },
  AvgDialog_13948_Content_60 = {
    Text = "Setelah aku meraih kejayaan, paling tidak aku akan mengangkatmu menjadi kepala suku!"
  },
  AvgDialog_13948_Content_61 = {
    Text = "…Tidak perlu juga."
  },
  AvgDialog_13948_Content_62 = {
    Text = "Tanpa terasa langit perlahan menggelap. Senja di ufuk barat bagaikan aliran sungai berkilauan keemasan, mengalir di antara cakrawala."
  },
  AvgDialog_13948_Content_63 = {
    Text = "Hei, kau tahu tidak? Alasan seorang pahlawan bisa menjadi pahlawan adalah karena ada orang seperti kita yang menjadi latar belakangnya."
  },
  AvgDialog_13948_Content_64 = {
    Text = "<Small:Jadi aku juga sangat penting, paham kan…>"
  },
  AvgDialog_13948_Content_65 = {
    Text = "<Small:Hmm…>"
  },
  AvgDialog_13948_Content_66 = {
    Text = "Kata-kata lirih itu bagaikan bunga dandelion yang tertiup angin laut, terbawa pergi ke tempat yang sangat jauh."
  },
  AvgDialog_13948_Content_67 = {
    Text = "Kau dan Goliath duduk di atas papan kayu tipis, dilihat dari kejauhan, kalian tampak seperti daun kecil yang hanyut di lautan keemasan."
  },
  AvgDialog_13948_Content_68 = {
    Text = "Tak ada yang tahu ke mana kalian pada akhirnya akan berlayar."
  },
  AvgDialog_13948_Content_7 = {
    Text = "<Shake:Penyihir, itu penyihir itu!!>"
  },
  AvgDialog_13948_Content_8 = {
    Text = "Bagaimana mungkin… Jadi legenda itu benar adanya…"
  },
  AvgDialog_13948_Content_9 = {
    Text = "<Red:Belas kasihan.\n         Belas kasihan.\n                  Belas kasihan…>"
  },
  AvgDialog_139656_Content_1 = {Text = "Perpisahan"},
  AvgDialog_139656_Content_10 = {
    Text = "Diriku yang sekarang…… hmm, mungkin lebih baik tidak usah."
  },
  AvgDialog_139656_Content_11 = {
    Text = "Setelah terhubung tadi…… banyak hal yang berubah."
  },
  AvgDialog_139656_Content_12 = {
    Text = "Anu…… aku pernah bermimpi."
  },
  AvgDialog_139656_Content_13 = {
    Text = "Dalam mimpi itu, Ramona berubah menjadi……"
  },
  AvgDialog_139656_Content_14 = {
    Text = "Meskipun sudah mengingatnya berkali-kali, kamu tetap sulit mendeskripsikan pemandangan itu karena rasa jijik yang bersifat fisiologis."
  },
  AvgDialog_139656_Content_15 = {
    Text = "Aku tahu kok. Saat itu, kamu pasti sangat ketakutan dan merasa jijik, kan?"
  },
  AvgDialog_139656_Content_16 = {
    Text = "Mystic Realm adalah bagian dari gambaran batinku, aku bisa merasakannya."
  },
  AvgDialog_139656_Content_17 = {
    Text = "Kalau memang begitu, aku sangat minta maaf."
  },
  AvgDialog_139656_Content_18 = {
    Text = "Tidak, bukan itu yang ingin kukatakan."
  },
  AvgDialog_139656_Content_19 = {
    Text = "Yang ingin kusampaikan adalah, saat itu aku tidak tahu apakah orang yang tertutup gumpalan daging itu adalah Ramona atau bukan."
  },
  AvgDialog_139656_Content_2 = {
    Text = "Dunia menjadi \"normal\". Normal yang seharusnya milik duniamu."
  },
  AvgDialog_139656_Content_20 = {
    Text = "Tapi sekarang aku tahu, itu memang Ramona yang kukenal, jadi, aku tidak akan takut."
  },
  AvgDialog_139656_Content_21 = {
    Text = "Penuturan memberimu keberanian, nada bicaramu perlahan menjadi teguh."
  },
  AvgDialog_139656_Content_22 = {
    Text = "Penampilan luar tidaklah penting, yang penting hanyalah hubungan antara aku dan Awakened yang terjalin melalui Silver Core."
  },
  AvgDialog_139656_Content_23 = {
    Text = "Karena hal serupa sudah terlalu sering kulihat."
  },
  AvgDialog_139656_Content_24 = {
    Text = "Aku pernah melihat sebuah hati semulia emas yang terlahir dari lumpur paling kotor di dunia;"
  },
  AvgDialog_139656_Content_25 = {
    Text = "Juga pernah melihat hasrat berkembang biak yang fanatik yang melahirkan daging darah penuh kasih sayang. Jadi——"
  },
  AvgDialog_139656_Content_26 = {
    Text = "Segalanya menjadi hening."
  },
  AvgDialog_139656_Content_27 = {
    Text = "Setelah sekian lama, sebuah senyuman tersampaikan dari ujung sana melalui hubungan itu. Senyuman yang tenang dan damai."
  },
  AvgDialog_139656_Content_28 = {
    Text = "……Senang sekali bisa bertemu denganmu."
  },
  AvgDialog_139656_Content_29 = {
    Text = "…Kemudian, di dalam alam rahasia yang terguncang itu, kamu kembali jatuh ke dalam mimpi itu."
  },
  AvgDialog_139656_Content_3 = {
    Text = "Pasir kuning yang diselimuti lendir korosi, menderu membentangkan daratan luas tak berujung."
  },
  AvgDialog_139656_Content_30 = {
    Text = "Selaｦ7matﾋkｸ daQ tangﾃ...diｨ弥A爨ﾑ萨9格ｴ鑷Uniﾅzverｷsitas, %player%."
  },
  AvgDialog_139656_Content_31 = {
    Text = "Gumpalan daging yang bergetar dan menggeliat, memeras keluar suara gelap nan lengket."
  },
  AvgDialog_139656_Content_32 = {
    Text = "Di dunia yang dipenuhi daging dan lumpur korosif, Ramona yang menetes lendir mengulurkan tangannya, perlahan menyentuh jari kelingkingmu."
  },
  AvgDialog_139656_Content_33 = {
    Text = "Aku tidak akan pernah melupakan momen ini."
  },
  AvgDialog_139656_Content_34 = {
    Text = "Kau bergumam pelan dalam hati."
  },
  AvgDialog_139656_Content_35 = {
    Text = "Sem(ﾉogaｲ驫 Kun8ciﾃP靇 Peｬﾗrakｸﾎ龥menﾑwuntun jalan."
  },
  AvgDialog_139656_Content_36 = {
    Text = "Di tengah lautan daging dan kehampaan, kau dengan teguh menggenggam balik tangan Ramona, menatap langsung kedua matanya yang hampa dan tubuhnya yang berlumuran darah."
  },
  AvgDialog_139656_Content_37 = {
    Text = "Semoga Kunci Perak membimbing kita."
  },
  AvgDialog_139656_Content_38 = {
    Text = "Cahaya Kunci Perak menyebar ke seluruh dunia."
  },
  AvgDialog_139656_Content_39 = {
    Text = "Sosok gadis putih bersih muncul di benakmu. Itu adalah Saya yang sedang tersenyum."
  },
  AvgDialog_139656_Content_4 = {
    Text = "Hanya pondok kecil di dalam hutan itu yang diselimuti warna merah darah bagai organ dalam. Pada saat yang sama, kau merasakan bahwa \"Saya\" berada di dalam pondok itu. Dan, saat akhirnya sudah sangat dekat."
  },
  AvgDialog_139656_Content_40 = {
    Text = "Sesuatu yang menyerupai sayap indah menari tertiup angin."
  },
  AvgDialog_139656_Content_41 = {
    Text = "Bunga dandelion beterbangan ke segala arah."
  },
  AvgDialog_139656_Content_42 = {
    Text = "Pada saat semua dandelion terlepas dari induknya, dunia yang samar bagai mimpi kembali menjadi kenyataan."
  },
  AvgDialog_139656_Content_43 = {
    Text = "Kau terbangun dari mimpi, dan segala sesuatu menampakkan wujud aslinya."
  },
  AvgDialog_139656_Content_44 = {
    Text = "Terima kasih……"
  },
  AvgDialog_139656_Content_45 = {
    Text = "Seolah terdengar bisikan perpisahan di telingamu. Apakah itu hanya ilusi?"
  },
  AvgDialog_139656_Content_46 = {
    Text = "Entah sejak kapan, sebuah Inti Perak muncul di telapak tanganmu."
  },
  AvgDialog_139656_Content_47 = {
    Text = "Itu adalah Inti Perak yang pernah dipungut oleh Tincture dan dipenuhi kerinduan abadi."
  },
  AvgDialog_139656_Content_48 = {
    Text = "Ketika waktunya tiba, kau dapat menggunakan Inti Perak ini untuk membangkitkan \"cinta\" abadinya."
  },
  AvgDialog_139656_Content_49 = {
    Text = "——Membangkitkan Corpus·Saya, cinta itu."
  },
  AvgDialog_139656_Content_5 = {
    Text = "Kurasa, jiwaku dan jiwamu sudah terhubung. Kalau begitu… penghalangnya juga akan lenyap sepenuhnya."
  },
  AvgDialog_139656_Content_6 = {
    Text = "Bisa merasakan perasaan seperti ini di saat-saat terakhir… aku sudah puas. …Terima kasih."
  },
  AvgDialog_139656_Content_7 = {
    Text = "Sekarang, pergilah dari sini, melangkahlah ke dalam lautan pasir kuning. Di tepi lautan pasir itu, kau akan bertemu kembali dengan masa lalumu."
  },
  AvgDialog_139656_Content_8 = {
    Text = "Tidak apa-apa, meskipun aku menghilang dari dunia ini, kesadaran kita akan tetap terhubung melalui Silver Core."
  },
  AvgDialog_139656_Content_9 = {
    Text = "Untuk yang terakhir kalinya, bolehkah aku melihat wujud aslimu?"
  },
  AvgDialog_139657_Content_1 = {Text = "\"Misi\""},
  AvgDialog_139657_Content_10 = {
    Text = "Aku merasakan ada pertanda besar yang akan segera datang..."
  },
  AvgDialog_139657_Content_11 = {
    Text = "Saya mengerutkan alis, seluruh tubuhnya tampak gelisah."
  },
  AvgDialog_139657_Content_12 = {
    Text = "Kamu menarik paksa gumpalan daging dari pergelangan tangan Saya dan membantunya berdiri."
  },
  AvgDialog_139657_Content_13 = {
    Text = "Aku ingin melihat padang bunga dandelion di luar. Temani aku jalan-jalan, ya?"
  },
  AvgDialog_139657_Content_14 = {
    Text = "Tubuhmu perlu istirahat yang cukup..."
  },
  AvgDialog_139657_Content_15 = {
    Text = "Tidak apa-apa, tak masalah..."
  },
  AvgDialog_139657_Content_16 = {
    Text = "Saya perlahan mendorong pintu pondok, pemandangan di luar masuk ke pandangan kalian bersama cahaya."
  },
  AvgDialog_139657_Content_17 = {
    Text = "Warna padang bunga dandelion telah berubah."
  },
  AvgDialog_139657_Content_18 = {
    Text = "Padang rumput yang kemarin masih hijau segar kini telah diselimuti bayangan hitam kemerahan. Dedaunan yang jarang tak mampu mempertahankan warna aslinya, tergerus dan termutasi."
  },
  AvgDialog_139657_Content_19 = {
    Text = "Ini adalah <Red:erosi>…!"
  },
  AvgDialog_139657_Content_2 = {
    Text = "Mimpi yang aneh dan fantastis menyerangmu."
  },
  AvgDialog_139657_Content_20 = {
    Text = "Kamu terlihat... sedih?"
  },
  AvgDialog_139657_Content_21 = {
    Text = "Kemarin tempat ini masih berupa padang bunga dandelion yang indah."
  },
  AvgDialog_139657_Content_22 = {
    Text = "Hari ini Korosi mengganggunya, menelannya. Dalam beberapa hari lagi, semuanya akan lenyap tanpa bekas."
  },
  AvgDialog_139657_Content_23 = {
    Text = "Setelah beberapa waktu berlalu, bahkan dalam ingatanmu pun tak akan tersisa kenangan tentang padang bunga ini."
  },
  AvgDialog_139657_Content_24 = {
    Text = "Bukankah itu hal yang menyedihkan?"
  },
  AvgDialog_139657_Content_25 = {
    Text = "Begitu ya, jadi begitu pikirmu..."
  },
  AvgDialog_139657_Content_26 = {
    Text = "Saya punya pandangan yang berbeda?"
  },
  AvgDialog_139657_Content_27 = {
    Text = "Hmm, di dunia ini selalu ada banyak sekali orang yang berbeda, hal-hal yang berbeda……"
  },
  AvgDialog_139657_Content_28 = {
    Text = "Di antaranya, yang lebih kuat akan menguasai dan merampas dari yang lebih lemah."
  },
  AvgDialog_139657_Content_29 = {
    Text = "Bukankah itu hal yang tak terhindarkan?"
  },
  AvgDialog_139657_Content_3 = {
    Text = "Dalam mimpi, bayangan Ramona sesekali muncul, suaranya terkoyak menjadi bunyi aneh bagai hembusan yang bocor."
  },
  AvgDialog_139657_Content_30 = {
    Text = "Tidak, bukan begitu. Itulah mengapa Misage ada."
  },
  AvgDialog_139657_Content_31 = {
    Text = "Kami ingin melindungi kehidupan dan kenangan yang belum tentu kuat, namun bersinar terang, dari erosi Fusi."
  },
  AvgDialog_139657_Content_32 = {
    Text = "Tentu saja, termasuk kamu juga, Saya."
  },
  AvgDialog_139657_Content_33 = {
    Text = "……Begitu ya."
  },
  AvgDialog_139657_Content_34 = {
    Text = "Saya bergumam pelan."
  },
  AvgDialog_139657_Content_35 = {
    Text = "Kalau begitu……mungkin memang begitu……"
  },
  AvgDialog_139657_Content_36 = {
    Text = "Entah sudah berapa lama kalian berjalan melewati pemandangan yang berulang, akhirnya kalian melihat sesuatu yang berbeda."
  },
  AvgDialog_139657_Content_37 = {
    Text = "Bunga dandelion lagi……?"
  },
  AvgDialog_139657_Content_38 = {
    Text = "Saya menundukkan kepala, napasnya sedikit terengah. Kamu tidak bisa melihat ekspresinya dengan jelas."
  },
  AvgDialog_139657_Content_39 = {
    Text = "Di sini……adalah pondok tempat kita berangkat tadi. Lihat ke sana."
  },
  AvgDialog_139657_Content_4 = {
    Text = "Kamu tersentak bangun."
  },
  AvgDialog_139657_Content_40 = {
    Text = "Kamu menunjuk ke sudut ruangan, gumpalan daging yang tadi pagi kamu cabut dari pergelangan tangan Saya dan lemparkan ke samping."
  },
  AvgDialog_139657_Content_41 = {
    Text = "Kita……kembali berputar ke sini."
  },
  AvgDialog_139657_Content_42 = {
    Text = "Di dalam Ranah Tersembunyi ini, selain kekosongan, tidak ada apa-apa."
  },
  AvgDialog_139657_Content_43 = {
    Text = "Kebetulan juga sih, kita bisa……istirahat sebentar."
  },
  AvgDialog_139657_Content_44 = {
    Text = "Saya tersenyum seolah tidak terjadi apa-apa, namun di ujung suaranya ada getaran yang tak bisa ditahan."
  },
  AvgDialog_139657_Content_45 = {
    Text = "Saya, tubuhmu……"
  },
  AvgDialog_139657_Content_46 = {
    Text = "Aku agak lelah……"
  },
  AvgDialog_139657_Content_47 = {
    Text = "Tepat di hadapanmu, tubuh Saya seolah kehilangan seluruh penopangnya, dan jatuh ambruk begitu saja."
  },
  AvgDialog_139657_Content_48 = {Text = "Saya!"},
  AvgDialog_139657_Content_49 = {
    Text = "Tengah malam, demam tinggi Saya tak kunjung reda. Di bawah arahannya, kau menyalakan api unggun menggunakan benda yang tak bisa kau kenali."
  },
  AvgDialog_139657_Content_5 = {
    Text = "Hek, hek..."
  },
  AvgDialog_139657_Content_50 = {
    Text = "Kalau aku tahu kau sakit separah ini, aku tidak akan membiarkanmu berjalan bersamaku seharian…"
  },
  AvgDialog_139657_Content_51 = {
    Text = "Tidak apa-apa, kurasa sakitku bukan karena alasan itu…\nDaripada itu… maukah kau mengobrol denganku?"
  },
  AvgDialog_139657_Content_52 = {
    Text = "Tentu saja, kau ingin membicarakan apa?"
  },
  AvgDialog_139657_Content_53 = {
    Text = "Tadi pagi kau bilang, kau dan Misage ingin melawan Erosi, melindungi orang lain, dan juga melindungiku."
  },
  AvgDialog_139657_Content_54 = {
    Text = "Apa itu benar?"
  },
  AvgDialog_139657_Content_55 = {
    Text = "Tentu saja. Pada hari aku resmi menerima Kunci Perak, aku sudah mengucapkan sumpah."
  },
  AvgDialog_139657_Content_56 = {
    Text = "Suaramu terdengar lebih teguh dari yang kau bayangkan. Begitu kata-kata itu terucap, gambaran upacara penyerahan kunci seketika muncul di benakmu—"
  },
  AvgDialog_139657_Content_57 = {
    Text = "Dinginnya Kunci Perak yang jatuh berat ke telapak tangan, tatapan khidmat semua orang, serta tekad membara yang membuncah dari lubuk hati saat kau menggenggam erat kunci itu."
  },
  AvgDialog_139657_Content_58 = {
    Text = "Saya tampak terdiam sejenak. Cahaya api menyepuh siluet mungilnya dengan lapisan jingga yang hangat."
  },
  AvgDialog_139657_Content_59 = {
    Text = "Kalau begitu, jika suatu hari nanti, kau kehilangan kekuatanmu sebagai Penjaga Rahasia dan menjadi orang biasa."
  },
  AvgDialog_139657_Content_6 = {
    Text = "Saya bersandar di pintu pondok, mengeluarkan suara batuk pelan."
  },
  AvgDialog_139657_Content_60 = {
    Text = "Jika kau tidak bisa lagi menjalankan misi melawan Erosi… apa yang akan kau lakukan?"
  },
  AvgDialog_139657_Content_61 = {
    Text = "Soal itu, aku sudah memikirkannya."
  },
  AvgDialog_139657_Content_62 = {
    Text = "Kau menyandarkan tubuhmu ke belakang, kedua tangan bertumpu di rerumputan, mendongak menatap hamparan bintang tak berujung di atas kepala."
  },
  AvgDialog_139657_Content_63 = {
    Text = "Aku akan bersama orang yang kucintai dan teman-temanku, menjalani kehidupan biasa dengan tenang dan damai hingga akhir."
  },
  AvgDialog_139657_Content_64 = {
    Text = "Saat sudah tua nanti, rambut sudah memutih, kaki sudah tak kuat berlari, kami akan duduk bersama mengelilingi perapian, berulang kali mengenang hal-hal memalukan yang pernah kami lakukan saat masih muda."
  },
  AvgDialog_139657_Content_65 = {
    Text = "Ramona pasti masih akan mengoreksi setiap nama nyonya yang salah diucapkan oleh Lord Dexter; William masih dengan tampang seriusnya yang kaku, berpura-pura membaca buku, padahal telinganya sudah berdiri sejak tadi…"
  },
  AvgDialog_139657_Content_66 = {
    Text = "Guru Holet tetap seperti biasa memeluk vodka-nya, dan saat sudah minum sepuasnya, pasti memaksa semua orang ikut bernyanyi."
  },
  AvgDialog_139657_Content_67 = {
    Text = "Kau menoleh dan mendapati Saya sedang memandangimu dengan tenang. Cahaya api terpantul di dasar matanya, berkedip-kedip, seperti dua gugus bintang kecil yang bersemayam di sana."
  },
  AvgDialog_139657_Content_68 = {
    Text = "Sungguh indah."
  },
  AvgDialog_139657_Content_69 = {Text = "Namun..."},
  AvgDialog_139657_Content_7 = {
    Text = "Saya! Tanganmu……!"
  },
  AvgDialog_139657_Content_70 = {
    Text = "Suara Saya sedikit serak. Ia menarik pandangannya, mata yang redup itu menatap kekosongan di sudut gelap."
  },
  AvgDialog_139657_Content_71 = {
    Text = "Jika kau terpisah dari mereka, dan tak ada seorang pun di sisimu, apa yang akan kau lakukan?"
  },
  AvgDialog_139657_Content_72 = {
    Text = "Apakah mereka pergi, atau sejak awal memang tidak pernah ada?"
  },
  AvgDialog_139657_Content_73 = {
    Text = "Jika… dalam ingatan memang masih tersisa jejak pertemuan, waktu yang dihabiskan bersama…"
  },
  AvgDialog_139657_Content_74 = {
    Text = "Tapi waktu telah berlalu terlalu lama, ingatan hancur berkeping-keping, dan kau sendiri tak tahu apakah itu nyata atau tidak…"
  },
  AvgDialog_139657_Content_75 = {
    Text = "Selama aku masih bisa mengingatnya, aku pasti akan pergi mencari mereka."
  },
  AvgDialog_139657_Content_76 = {
    Text = "Tak peduli sejauh apa pun, tak peduli berapa banyak rintangan yang menghadang, aku pasti akan menemukan mereka."
  },
  AvgDialog_139657_Content_77 = {
    Text = "Tatapanmu kepada Saya tak menunjukkan setitik pun keraguan."
  },
  AvgDialog_139657_Content_78 = {
    Text = "Seandainya… maksudku seandainya—kau tidak bisa menemukannya?"
  },
  AvgDialog_139657_Content_79 = {
    Text = "Aku tetap akan terus mencari, melangkah di setiap jalan, mendaki setiap gunung, menyeberangi setiap lautan."
  },
  AvgDialog_139657_Content_8 = {
    Text = "Gumpalan daging yang dipenuhi lumpur hitam menyusup masuk melalui celah pintu pondok, melilit pergelangan tangan Saya."
  },
  AvgDialog_139657_Content_80 = {
    Text = "Hingga dalam perjalanan pencarian yang tak henti itu, aku menghabiskan seluruh hidupku yang panjang ini."
  },
  AvgDialog_139657_Content_81 = {
    Text = "Bahkan di saat aku menutup mata untuk terakhir kalinya, aku tetap merasa penuh dan utuh."
  },
  AvgDialog_139657_Content_82 = {
    Text = "Karena hidupku memiliki kenangan yang berharga, dan juga tempat yang bagaimanapun juga harus kutuju."
  },
  AvgDialog_139657_Content_83 = {
    Text = "Pencarian itu sendiri, sudah merupakan sebuah makna."
  },
  AvgDialog_139657_Content_84 = {
    Text = "Setelah kata-kata itu usai, sekitar tiba-tiba hening hingga hanya tersisa suara desir bunga dandelion yang berayun tertiup angin sepoi."
  },
  AvgDialog_139657_Content_85 = {Text = "…Saya?"},
  AvgDialog_139657_Content_86 = {
    Text = "Saya memejamkan matanya, wajahnya pucat seperti kertas tipis. Hatimu terasa tercengkeram erat."
  },
  AvgDialog_139657_Content_87 = {Text = "Saya…"},
  AvgDialog_139657_Content_88 = {
    Text = "Kamu mendekat dengan cemas, namun mendapati napas Saya lembut dan stabil, dadanya naik turun perlahan mengikuti irama napasnya, seperti riak paling halus di permukaan danau."
  },
  AvgDialog_139657_Content_89 = {
    Text = "Ternyata hanya tertidur..."
  },
  AvgDialog_139657_Content_9 = {
    Text = "Perubahan yang tampak di permukaan ini... justru bukan hal yang paling penting."
  },
  AvgDialog_139657_Content_90 = {
    Text = "Aku juga, agak, mengantuk..."
  },
  AvgDialog_139657_Content_91 = {
    Text = "Di bawah rasa lega yang datang tiba-tiba, kelelahan setelah seharian berlarian dan tekanan visual dari pemandangan daging di mana-mana akhirnya menguasaimu."
  },
  AvgDialog_139657_Content_92 = {
    Text = "Sebelum akhir tiba, malam ini pun berlalu dalam keheningan."
  },
  AvgDialog_139658_Content_1 = {
    Text = "Saat Hujan Reda"
  },
  AvgDialog_139658_Content_10 = {
    Text = "Senangnya, bisa merasakan matahari."
  },
  AvgDialog_139658_Content_11 = {
    Text = "Saya tersenyum, mengulurkan tangannya ke arah datangnya cahaya matahari, seperti tanaman yang menghadap cahaya."
  },
  AvgDialog_139658_Content_12 = {
    Text = "Bisakah kamu membantuku keluar untuk melihat?"
  },
  AvgDialog_139658_Content_13 = {
    Text = "Kamu memapah Saya dan membantunya duduk bersandar di dinding samping pondok. Meski hanya jarak sesingkat ini, Saya tak bisa menyembunyikan napasnya yang terengah."
  },
  AvgDialog_139658_Content_14 = {
    Text = "Saya, tubuhmu……"
  },
  AvgDialog_139658_Content_15 = {
    Text = "Jangan khawatir, kurasa waktunya sudah hampir tiba."
  },
  AvgDialog_139658_Content_16 = {
    Text = "Kamu juga bisa merasakannya, kan? Dinding penghalang yang menghalangi koneksi kita... sedang memudar."
  },
  AvgDialog_139658_Content_17 = {
    Text = "Sebentar lagi, pasti akan runtuh sepenuhnya.\nSaat itu tiba……seharusnya \"koneksi\" yang kamu sebutkan bisa terjalin."
  },
  AvgDialog_139658_Content_18 = {Text = "Tapi..."},
  AvgDialog_139658_Content_19 = {
    Text = "Setelah terkoneksi, Saya mungkin akan menghilang. Dinding penghalang itu adalah tembok yang dia bangun untuk melindungi dirinya sendiri, itulah mengapa dinding itu menjadi rapuh karena kelemahannya."
  },
  AvgDialog_139658_Content_2 = {
    Text = "Ketika kamu terbangun, cahaya sudah berubah."
  },
  AvgDialog_139658_Content_20 = {
    Text = "Tidak perlu merasa sungkan. Di saat seperti ini, bisa ditemani dan berbincang denganmu, aku sangat senang."
  },
  AvgDialog_139658_Content_21 = {
    Text = "Saya menyipitkan matanya, menampakkan senyuman yang tulus namun lemah. Kamu tak sanggup menatap langsung, tapi tetap berusaha mengukir senyumannya dalam ingatan."
  },
  AvgDialog_139658_Content_22 = {
    Text = "Aku akan selalu menemanimu."
  },
  AvgDialog_139658_Content_23 = {
    Text = "Sudahlah, jangan pasang ekspresi murung seperti itu. Mari kita lanjutkan topik pembicaraan kemarin."
  },
  AvgDialog_139658_Content_24 = {
    Text = "Kamu bilang, meskipun tak bisa melawan Erosi, meskipun tak ada siapa pun di sisimu, kamu tetap akan terus maju."
  },
  AvgDialog_139658_Content_25 = {
    Text = "Aku penasaran, kenapa bisa begitu?"
  },
  AvgDialog_139658_Content_26 = {
    Text = "Kenapa ya? Sinar matahari setelah hujan agak menyilaukan, membuatmu tak kuasa menahan air mata."
  },
  AvgDialog_139658_Content_27 = {
    Text = "Kamu menarik napas dalam-dalam."
  },
  AvgDialog_139658_Content_28 = {
    Text = [[
Karena aku mencintai Ramona, mencintai semua rekan di Universitas Misago.
Dan aku yakin, mereka juga mencintaiku.]]
  },
  AvgDialog_139658_Content_29 = {
    Text = "Tapi kalian terpisah sangat jauh, tak bisa saling menyentuh, tak bisa memastikan perasaan satu sama lain."
  },
  AvgDialog_139658_Content_3 = {
    Text = "Udara lembap kini memiliki aroma bersih seperti habis dicuci, yang menerobos celah pintu bukanlah angin, melainkan seberkas cahaya yang tenang."
  },
  AvgDialog_139658_Content_30 = {
    Text = "Lagipula, duniamu memiliki anomali yang disebut \"Erosi\", bagaimana kau bisa yakin bahwa orang yang kau rindukan tidak melupakan keberadaanmu?"
  },
  AvgDialog_139658_Content_31 = {
    Text = "Suaranya membawa kelembutan yang nyaris seperti igauan dalam mimpi."
  },
  AvgDialog_139658_Content_32 = {
    Text = "Erosi mungkin bisa menghapus keberadaan, tapi Silver Core menghubungkanku dan Ramona di lautan alam bawah sadar."
  },
  AvgDialog_139658_Content_33 = {
    Text = "Kamu memandang ke kejauhan. Garis cakrawala setelah hujan begitu jernih tak terbayangkan, lapisan awan dirobek angin membentuk celah, dan pilar-pilar cahaya emas tercurah dari celah itu, jatuh di punggung gunung yang jauh."
  },
  AvgDialog_139658_Content_34 = {
    Text = "Aku bisa merasakan keberadaannya, bahkan di saat ini pun sama saja, meskipun kami terpaksa terpencar di dunia yang berbeda pun tetap sama."
  },
  AvgDialog_139658_Content_35 = {
    Text = "Lagipula……"
  },
  AvgDialog_139658_Content_36 = {Text = "Hm?"},
  AvgDialog_139658_Content_37 = {
    Text = "Dia sedikit memiringkan kepalanya ke sini."
  },
  AvgDialog_139658_Content_38 = {
    Text = "Orang yang benar-benar saling mencintai tidak perlu berada di sisi satu sama lain untuk bisa merasakan keberadaan masing-masing, untuk bisa memastikan cinta satu sama lain."
  },
  AvgDialog_139658_Content_39 = {
    Text = "Meskipun kiamat terus berulang tanpa henti, aku pasti bisa menemukan Ramona. Dan dia pasti akan membuat pilihan yang sama."
  },
  AvgDialog_139658_Content_4 = {
    Text = "...Di luar sangat sunyi."
  },
  AvgDialog_139658_Content_40 = {
    Text = "Aku punya firasat itu. Kerinduan kami yang terhubung di lautan jiwa, tidak akan pernah terputus."
  },
  AvgDialog_139658_Content_41 = {
    Text = "Saya terdiam cukup lama. Angin setelah hujan menerpa pondok kecil itu, menyapu pipinya yang hampir tak berwarna."
  },
  AvgDialog_139658_Content_42 = {
    Text = "Lalu, dia tersenyum."
  },
  AvgDialog_139658_Content_43 = {
    Text = "Sungguh, kepercayaan yang kuat dan teguh, sungguh, cinta yang agung…"
  },
  AvgDialog_139658_Content_44 = {
    Text = "Saat dia mengucapkan kata \"cinta\", suaranya tanpa rasa iri, tanpa kesedihan, tanpa penyesalan."
  },
  AvgDialog_139658_Content_45 = {
    Text = "Hanya kelembutan."
  },
  AvgDialog_139658_Content_46 = {
    Text = "Seperti seorang musafir yang berjalan sendirian di malam musim dingin yang panjang, akhirnya melihat sinar fajar pertama di ujung cakrawala — dia belum tentu bisa sampai ke sana, tapi selama cahaya itu ada, itu sudah cukup."
  },
  AvgDialog_139658_Content_47 = {
    Text = "Saya tersenyum dengan tatapan menerawang."
  },
  AvgDialog_139658_Content_48 = {
    Text = "Lalu, dia mengulurkan tangannya kepadamu."
  },
  AvgDialog_139658_Content_49 = {
    Text = "…Genggam tanganku."
  },
  AvgDialog_139658_Content_5 = {
    Text = "Hujan... sudah berhenti?"
  },
  AvgDialog_139658_Content_50 = {
    Text = "Tangan itu pucat, ramping, sedikit gemetar. Dia tidak bisa melihatmu, tapi tangannya terulur tepat ke arahmu tanpa keraguan—"
  },
  AvgDialog_139658_Content_51 = {
    Text = "Seolah sesuatu yang lebih tua dari penglihatan, lebih dalam dari bahasa, sedang membimbingnya."
  },
  AvgDialog_139658_Content_52 = {
    Text = "Kau mengulurkan tangan dan menggenggam tangannya."
  },
  AvgDialog_139658_Content_53 = {
    Text = "Tepat di saat telapak tangan kalian bersentuhan—"
  },
  AvgDialog_139658_Content_54 = {
    Text = "Rasa sakit yang hebat menghantam rongga matamu."
  },
  AvgDialog_139658_Content_55 = {
    Text = "Sesuatu yang jauh lebih tajam, lebih membakar dari itu, seperti sambaran petir membelah tengkorakmu, menembus langsung ke kedalaman kesadaranmu."
  },
  AvgDialog_139658_Content_56 = {
    Text = "Pandanganmu berguncang hebat."
  },
  AvgDialog_139658_Content_57 = {
    Text = "Kau melihat bunga dandelion yang basah di bawah sinar matahari, wajah samping Saya yang pucat namun damai, senyum tipis di sudut bibirnya yang pecah-pecah—"
  },
  AvgDialog_139658_Content_58 = {
    Text = "Lalu segalanya berubah menjadi alam semesta dari daging dan darah. Langit merah darah, bumi merah darah, bahkan Saya di hadapanmu juga—"
  },
  AvgDialog_139658_Content_59 = {
    Text = "Tidak——"
  },
  AvgDialog_139658_Content_6 = {
    Text = "Mata Saya memandang ke arah jendela, tapi tatapannya tak memiliki titik fokus."
  },
  AvgDialog_139658_Content_60 = {
    Text = "Dua pemandangan berkedip bergantian, tumpang tindih, dan melebur dalam pandanganmu. Dua sungai yang seharusnya mengalir sejajar tiba-tiba bertabrakan di titik pertemuan yang mustahil."
  },
  AvgDialog_139658_Content_61 = {
    Text = "Tautanmu dengan Saya telah terhubung."
  },
  AvgDialog_139658_Content_7 = {
    Text = "Sinar matahari jatuh ke dasar matanya, seperti batu kerikil yang dilempar ke air, namun tak menimbulkan riak apa pun."
  },
  AvgDialog_139658_Content_8 = {
    Text = "Hujan sudah berhenti."
  },
  AvgDialog_139658_Content_9 = {
    Text = "Nada bicaramu terasa berat."
  },
  AvgDialog_139659_Content_1 = {Text = "\"Cinta\""},
  AvgDialog_139659_Content_10 = {
    Text = "Saya berdiri di tengah ladang bunga dandelion di pagi hari."
  },
  AvgDialog_139659_Content_11 = {
    Text = "Setelah disiram hujan, biji-biji dandelion yang tak terhitung jatuh ke tanah berwarna merah kehitaman, dan beberapa di antaranya sudah mulai bertunas dan tumbuh."
  },
  AvgDialog_139659_Content_12 = {
    Text = "Tumbuh dalam semalam, lahir dalam semalam..."
  },
  AvgDialog_139659_Content_13 = {
    Text = "Melihat ekspresimu, apakah kamu teringat sesuatu?"
  },
  AvgDialog_139659_Content_14 = {
    Text = "Ya, aku pernah melihat pemandangan serupa di gurun Ayalan."
  },
  AvgDialog_139659_Content_15 = {
    Text = "Tanah di sana diberkati oleh \"Pohon Induk Kesuburan\", keturunan spesies itu tumbuh begitu menyentuh tanah, dan berkembang tertiup angin."
  },
  AvgDialog_139659_Content_16 = {
    Text = "Bukankah itu hal yang bagus?"
  },
  AvgDialog_139659_Content_17 = {
    Text = "...Tapi, kedengarannya, sepertinya kamu merasa itu tidak begitu bagus."
  },
  AvgDialog_139659_Content_18 = {
    Text = "Sebagai orang yang tidak terlibat langsung, aku tidak bisa memberikan penilaian."
  },
  AvgDialog_139659_Content_19 = {
    Text = "Hanya saja, bagi banyak orang, setiap tahap kehidupan itu sangat penting."
  },
  AvgDialog_139659_Content_2 = {
    Text = "Kamu dan Saya meringkuk di sudut pondok masing-masing, tanpa sepatah kata pun sepanjang malam."
  },
  AvgDialog_139659_Content_20 = {
    Text = "Seperti anak bernama Neferure itu… dia tidak pernah mengalami masa kecil yang sesungguhnya, tidak pernah merasakan kasih sayang dari orang tua, dan tergesa-gesa melangkah ke medan perang menghadapi Tembok Badai…"
  },
  AvgDialog_139659_Content_21 = {
    Text = "Saya mengangguk dengan pemahaman yang setengah-setengah."
  },
  AvgDialog_139659_Content_22 = {
    Text = "Maksudmu, bagi manusia, panjangnya kehidupan juga sangat penting, kan?"
  },
  AvgDialog_139659_Content_23 = {
    Text = "Bukan hanya itu, setiap hal yang dialami dalam hidup, setiap orang yang ditemui, semuanya akan menjadi bagian dari kenangan di masa depan."
  },
  AvgDialog_139659_Content_24 = {
    Text = "Endapan kenangan-kenangan ini membentuk diri setiap orang."
  },
  AvgDialog_139659_Content_25 = {
    Text = [[
Bahkan bisa dikatakan, manusia adalah wadah dari kenangan.
Meskipun raga telah musnah, kenangan akan terus diwariskan, hingga dilupakan oleh semua orang.]]
  },
  AvgDialog_139659_Content_26 = {
    Text = "Begitu ya…… Aku mengerti."
  },
  AvgDialog_139659_Content_27 = {
    Text = "Kalau begitu, jika suatu hari aku mati, kenangan kita bersama di sini hari ini, juga akan menjadi bagian dari dirimu?"
  },
  AvgDialog_139659_Content_28 = {
    Text = "Tentu saja."
  },
  AvgDialog_139659_Content_29 = {
    Text = "Di balik senyuman lemah Saya, kamu mengangguk dengan tegas."
  },
  AvgDialog_139659_Content_3 = {
    Text = "Entah kapan, didorong oleh kelelahan, kamu pun tertidur lelap."
  },
  AvgDialog_139659_Content_30 = {
    Text = "Hari ini pun berlalu dalam penjelajahan dan pengembaraan di perbatasan."
  },
  AvgDialog_139659_Content_31 = {
    Text = "Namun di luar padang bunga dandelion, yang ada hanyalah pemandangan tandus yang serupa satu sama lain, daratan yang tertutup daging dan darah hingga bentuk aslinya tak bisa dikenali."
  },
  AvgDialog_139659_Content_32 = {
    Text = "Meskipun kamu memaksanya untuk ditekan, rasa gelisah itu tetap perlahan-lahan tumbuh dari lubuk hati, sedikit demi sedikit merambat ke kesadaranmu."
  },
  AvgDialog_139659_Content_33 = {
    Text = "(Jika tidak menemukan apa pun, maka inti dari ruang rahasia ini hanya bisa berupa……)"
  },
  AvgDialog_139659_Content_34 = {
    Text = "Malam sudah larut."
  },
  AvgDialog_139659_Content_35 = {
    Text = "Istirahatlah yang baik, aku merasa agak lelah."
  },
  AvgDialog_139659_Content_36 = {
    Text = "Kebetulan, aku juga ingin istirahat lebih awal, supaya besok bisa menjelajah ke tempat yang lebih jauh."
  },
  AvgDialog_139659_Content_37 = {
    Text = "Diiringi percakapan seperti itu, kalian pun terlelap dalam tidur nyenyak."
  },
  AvgDialog_139659_Content_39 = {
    Text = "Kamu terbangun oleh suatu suara, seluruh tubuhmu terasa panas membara, seolah-olah berada di tengah gurun pasir."
  },
  AvgDialog_139659_Content_4 = {
    Text = "(Dingin sekali... Semoga besok bisa tidur di tempat tidur yang hangat...)"
  },
  AvgDialog_139659_Content_40 = {Text = "?!!"},
  AvgDialog_139659_Content_41 = {
    Text = "Kepalamu terasa berat dan pusing, entah karena pemandangan aneh di hadapanmu, atau asap samar yang melayang-layang di udara."
  },
  AvgDialog_139659_Content_42 = {
    Text = "Atau mungkin karena pengaruh Sungai Suci Pohon Induk."
  },
  AvgDialog_139659_Content_43 = {
    Text = "Sayang sekali, apakah orang yang kamu harapkan bukan aku?"
  },
  AvgDialog_139659_Content_44 = {
    Text = "Ratu Aran — Thais masuk dengan mengangkat tirai, dia tanpa ragu mendekat. Kain tipis yang hampir tak terasa menyentuh lengan kecilmu, mengeluarkan undangan yang terang-terangan."
  },
  AvgDialog_139659_Content_45 = {
    Text = "Ayo, terimalah darah keturunan Alan dan jadilah salah satu dari kami."
  },
  AvgDialog_139659_Content_46 = {
    Text = "Mendekatlah padaku, peluk aku... berikan darahmu, benihmu..."
  },
  AvgDialog_139659_Content_47 = {
    Text = "Kilatan api bergerak di dalam muridnya yang penuh semangat, pipinya yang kemerahan menunjukkan keinginan yang tidak sehat."
  },
  AvgDialog_139659_Content_48 = {
    Text = "Hanya satu tetes saja, asalkan daging tulang kita bersatu, Dia akan memberikan masa depan yang kita dambakan…"
  },
  AvgDialog_139659_Content_49 = {
    Text = "Mari kita... melahirkan keturunan untuk komunitas kita, dan berbagi keabadian..."
  },
  AvgDialog_139659_Content_5 = {
    Text = "Dalam keadaan setengah sadar, kamu merasakan sesuatu menyelimutimu."
  },
  AvgDialog_139659_Content_50 = {
    Text = "Kamu berusaha keras mengerahkan akal sehatmu untuk melawan godaan Taiyisi, namun dentang lonceng yang dulu pernah membangunkanmu tak kunjung datang."
  },
  AvgDialog_139659_Content_51 = {
    Text = "Di tengah kebuntuan itu, tiba-tiba kamu mendengar suara baru merasuk ke telingamu."
  },
  AvgDialog_139659_Content_52 = {
    Text = "Kenapa, kenapa harus menolak?"
  },
  AvgDialog_139659_Content_53 = {
    Text = "Entah sejak kapan, sang gadis muncul dari sudut tenda."
  },
  AvgDialog_139659_Content_54 = {
    Text = "Berbeda dari nada bicaranya yang biasanya riang, kali ini seolah mengandung emosi yang istimewa."
  },
  AvgDialog_139659_Content_55 = {
    Text = "\"Berkembang biak\" menurutku adalah hal yang baik, dan juga tujuan dari semua makhluk hidup…"
  },
  AvgDialog_139659_Content_56 = {
    Text = "Kalau begitu, kenapa tidak menerimanya?"
  },
  AvgDialog_139659_Content_57 = {
    Text = "Kenapa, kenapa harus menolak?"
  },
  AvgDialog_139659_Content_58 = {
    Text = "Karena ini bukan soal cinta, ini hanyalah godaan."
  },
  AvgDialog_139659_Content_59 = {
    Text = "Godaan bukanlah cinta, misi bukanlah cinta, nafsu juga bukanlah cinta."
  },
  AvgDialog_139659_Content_6 = {Text = "……Hmm?"},
  AvgDialog_139659_Content_60 = {
    Text = "Cinta adalah—"
  },
  AvgDialog_139659_Content_61 = {
    Text = "Cinta adalah—"
  },
  AvgDialog_139659_Content_62 = {
    Text = "Kamu jatuh pingsan."
  },
  AvgDialog_139659_Content_63 = {
    Text = "Segalanya tenggelam ke dalam kegelapan yang panjang."
  },
  AvgDialog_139659_Content_7 = {
    Text = "Tubuhmu tertutupi selimut tipis."
  },
  AvgDialog_139659_Content_8 = {
    Text = "Langit sudah cerah."
  },
  AvgDialog_139659_Content_9 = {
    Text = "Keluarlah untuk melihat-lihat."
  },
  AvgDialog_139660_Content_1 = {Text = "\"Ingatan\""},
  AvgDialog_139660_Content_10 = {
    Text = "Aku memang bukan orang biasa, aku adalah penyelidik dari Universitas Misagar."
  },
  AvgDialog_139660_Content_11 = {
    Text = "Mata Saya dipenuhi kebingungan, jelas semua istilah ini terlalu asing baginya."
  },
  AvgDialog_139660_Content_12 = {
    Text = "Kalau harus dijelaskan semuanya, akan terlalu panjang. Sekarang ada hal yang lebih penting yang harus kuselesaikan."
  },
  AvgDialog_139660_Content_13 = {
    Text = "Rekanku, Ramona, aku melihat dia ditelan oleh sesuatu, dia berubah menjadi……"
  },
  AvgDialog_139660_Content_14 = {
    Text = "Kamu tidak menyelesaikan kalimatmu. Kamu tidak sanggup menyelesaikannya."
  },
  AvgDialog_139660_Content_15 = {
    Text = "Kata-kata hanyalah simbol hampa, tidak mampu menyampaikan ketakutan yang kamu rasakan di detik itu—ketakutan yang menjalar dari dasar tulang belakangmu."
  },
  AvgDialog_139660_Content_16 = {
    Text = "Ketakutan akan kemungkinan kehilangan Ramona untuk selamanya."
  },
  AvgDialog_139660_Content_17 = {
    Text = "Dia adalah orang yang tak tergantikan bagiku."
  },
  AvgDialog_139660_Content_18 = {
    Text = "Tatapan Saya sesaat kehilangan fokus."
  },
  AvgDialog_139660_Content_19 = {
    Text = "Orang yang tak tergantikan…… begitu rupanya."
  },
  AvgDialog_139660_Content_2 = {
    Text = "Sebelum kamu sempat menyusun semua pertanyaan yang memenuhi pikiranmu, gadis itu lebih dulu membuka suara."
  },
  AvgDialog_139660_Content_20 = {
    Text = "Sepertinya aku juga pernah punya……orang seperti itu."
  },
  AvgDialog_139660_Content_21 = {
    Text = "Dia menundukkan kepala, mengerutkan alis sambil bergumam pelan."
  },
  AvgDialog_139660_Content_22 = {
    Text = "Ada seseorang. Orang yang sangat penting. Wajah orang itu……seharusnya aku ingat. Aku pasti ingat. Tapi saat aku mencoba memikirkannya sekarang, yang bisa kulihat hanyalah——"
  },
  AvgDialog_139660_Content_23 = {
    Text = "——hanya siluetnya. Seperti terhalang kaca buram. Aku tahu dia ada di sana, tahu dia sangat penting, tapi semua detailnya sudah……terhapus."
  },
  AvgDialog_139660_Content_24 = {
    Text = "Bukan hanya dia. Hal-hal lain juga sama. Aku tahu ada sesuatu yang harus kulakukan——sesuatu yang sangat penting."
  },
  AvgDialog_139660_Content_25 = {
    Text = "Namun setiap penggalan ingatan saling bertentangan. Satu bagian mengatakan dia sangat lembut, bagian berikutnya mengatakan aku berada di tempat yang sangat gelap untuk waktu yang lama."
  },
  AvgDialog_139660_Content_26 = {
    Text = "Satu bagian mengatakan aku menunggu seseorang menjemputku, bagian berikutnya mengatakan aku perlu melakukan sesuatu… yang akan membuat orang takut."
  },
  AvgDialog_139660_Content_27 = {
    Text = "Setiap potongan terasa nyata. Tapi saat disatukan, semuanya saling bertentangan."
  },
  AvgDialog_139660_Content_28 = {
    Text = "Kau pernah melihat kondisi seperti ini."
  },
  AvgDialog_139660_Content_29 = {
    Text = [[
Ini adalah gejala yang tercatat dalam laporan Fenomena-d, dan bukan hanya terjadi padanya.
Kesadaran kabur, Pecahan Memori, crash dalam pengenalan diri.]]
  },
  AvgDialog_139660_Content_3 = {
    Text = "Aku adalah…… hmm, panggil saja aku \"Saya\".\nOmong-omong, kamu tahu ini di mana?"
  },
  AvgDialog_139660_Content_30 = {
    Text = "Aku tidak tahu bagian mana yang benar-benar terjadi, aku tidak tahu mana yang merupakan ingatan asliku sendiri……"
  },
  AvgDialog_139660_Content_31 = {
    Text = "Jari-jari Saya mengerut, seolah ingin menggenggam sesuatu yang sudah tidak ada lagi."
  },
  AvgDialog_139660_Content_32 = {
    Text = "Seiring kegoyahannya, kau merasakan lingkungan sekitar mulai berubah."
  },
  AvgDialog_139660_Content_33 = {Text = "Hati-hati!"},
  AvgDialog_139660_Content_34 = {
    Text = "Kau memandang ke pinggiran padang dandelion. Membran daging yang diselimuti cairan hitam perlahan merambat mendekat sedikit demi sedikit, batas padang bunga dandelion tampak semakin rapuh."
  },
  AvgDialog_139660_Content_4 = {
    Text = "Kenapa aku bisa ada di tempat seperti ini……\nHmm— rasanya banyak hal yang tidak bisa kuingat."
  },
  AvgDialog_139660_Content_5 = {
    Text = "……Kamu, sepertinya bukan orang biasa?\nMemiliki kekuatan khusus……?"
  },
  AvgDialog_139660_Content_6 = {
    Text = "Kamu tidak langsung menjawab. Gadis bernama Saya itu melepaskan tangannya, mundur setengah langkah, dan menyipitkan mata mengamatimu."
  },
  AvgDialog_139660_Content_7 = {
    Text = "Melihatku, kamu tidak merasakan apa-apa? Kenapa kamu datang ke sini?"
  },
  AvgDialog_139660_Content_8 = {
    Text = "Pelan-pelan, satu pertanyaan dulu."
  },
  AvgDialog_139660_Content_9 = {
    Text = "Berdasarkan pengalamanku, kemungkinan besar tempat ini adalah sebuah Mystic Realm."
  },
  AvgDialog_139661_Content_1 = {
    Text = "Lanskap Batin"
  },
  AvgDialog_139661_Content_10 = {
    Text = "Seorang gadis cantik, dan seorang pemuda."
  },
  AvgDialog_139661_Content_11 = {
    Text = "Mereka bergandengan tangan, berjalan mesra di padang tandus yang diterpa angin pasir."
  },
  AvgDialog_139661_Content_13 = {
    Text = "Dia tertawa riang, merentangkan tangan memeluk angin."
  },
  AvgDialog_139661_Content_14 = {
    Text = "Pemuda di sampingnya pun menoleh, mendengarkan setiap tawa manisnya."
  },
  AvgDialog_139661_Content_15 = {
    Text = "Langit cerah, namun menyimpan sedikit kesedihan."
  },
  AvgDialog_139661_Content_16 = {
    Text = "Namun dari bayangan dua orang yang saling menemani itu, kau merasakan kebahagiaan yang tumbuh dengan sendirinya."
  },
  AvgDialog_139661_Content_17 = {
    Text = "Meskipun tak ada siapa pun di sekitar, meskipun tak mendapat pengertian dan restu dari siapa pun, cinta itu tetap—"
  },
  AvgDialog_139661_Content_18 = {
    Text = "Lalu mimpi itu terhenti mendadak, angin pasir menyapu segalanya."
  },
  AvgDialog_139661_Content_19 = {
    Text = "Dunia jatuh ke dalam kegelapan hampa."
  },
  AvgDialog_139661_Content_2 = {
    Text = "Langit dan bumi terbentuk dari pasir."
  },
  AvgDialog_139661_Content_20 = {
    Text = "——Saat itu, ada seorang penyanyi, yang sedang melintasi bintang-bintang."
  },
  AvgDialog_139661_Content_21 = {
    Text = "Di tengah alam semesta yang tandus, dia memungut sebuah inti perak."
  },
  AvgDialog_139661_Content_22 = {
    Text = "Pada saat dia menyentuhnya, \"aku\" pun terbangun."
  },
  AvgDialog_139661_Content_23 = {
    Text = "\"Aku\" kehilangan ingatan, hanya tahu bahwa aku harus mencari \"orang yang tak tergantikan\" itu."
  },
  AvgDialog_139661_Content_24 = {
    Text = "\"Aku\" bertanya kepada sang penyanyi, apakah kami bisa pergi bersama, tetapi permintaan itu ditolak."
  },
  AvgDialog_139661_Content_25 = {
    Text = "Aku akan pergi mencari orang yang sangat kucintai—kakak perempuanku."
  },
  AvgDialog_139661_Content_26 = {
    Text = "Begitulah kata sang penyanyi."
  },
  AvgDialog_139661_Content_27 = {
    Text = "Kuharap kau juga bisa menemukan kembali orang yang kaucintai, Saya. Aku sungguh berharap kau bisa mendapatkan akhir seperti itu."
  },
  AvgDialog_139661_Content_28 = {
    Text = "Meninggalkan kata-kata itu, sang penyanyi pun pergi."
  },
  AvgDialog_139661_Content_29 = {
    Text = "Sejak saat itu, aku yang kehilangan ingatan masa lalu, juga kehilangan sang penyanyi itu."
  },
  AvgDialog_139661_Content_3 = {
    Text = "Dalam angin yang bertiup tanpa henti melintasi gurun sepanjang keabadian, kau memandang ke bawah dengan kebingungan."
  },
  AvgDialog_139661_Content_30 = {
    Text = "Membawa harapan darinya, aku terus berjalan seorang diri di dunia ini."
  },
  AvgDialog_139661_Content_31 = {
    Text = "Demi menemukan orang yang dulu tak tergantikan, demi menemukan kembali ingatan masa lalu…"
  },
  AvgDialog_139661_Content_32 = {
    Text = "Selalu percaya bahwa apa yang kucari, pasti ada di depan sana."
  },
  AvgDialog_139661_Content_33 = {
    Text = "…Lalu, aku bertemu denganmu."
  },
  AvgDialog_139661_Content_4 = {
    Text = "Di sini adalah..."
  },
  AvgDialog_139661_Content_5 = {
    Text = "Tidak ada lumpur yang mengikis, tidak ada gumpalan daging yang memenuhi padang."
  },
  AvgDialog_139661_Content_6 = {
    Text = "Pemandangan di sini sunyi, murni, dan indah."
  },
  AvgDialog_139661_Content_7 = {
    Text = "Ini adalah lanskap batinku, lho."
  },
  AvgDialog_139661_Content_8 = {
    Text = "Ini adalah keberadaan milik Saya yang tak boleh dilupakan dan tak tergantikan."
  },
  AvgDialog_139661_Content_9 = {
    Text = "Pasir bergulung pergi, dan di sudut gurun, dua sosok muncul."
  },
  AvgDialog_139662_Content_10 = {
    Text = "Aku akan menjadi asistenmu, menemanimu hingga akhir dari jalan ini…<Yellow:Semoga Kunci perak membimbing jalan ke depan.>"
  },
  AvgDialog_139662_Content_11 = {
    Text = [[
Apa kabar, %player%?
Sejak tadi, ekspresi wajahmu tampak tidak baik. Apakah kamu butuh aku antar ke ruang kesehatan?]]
  },
  AvgDialog_139662_Content_12 = {Text = "Ramona..."},
  AvgDialog_139662_Content_13 = {
    Text = "Gumaman-mu seolah tersangkut di tenggorokan, kau tak bisa memanggil namanya, nama yang begitu kau kenal."
  },
  AvgDialog_139662_Content_14 = {
    Text = "<Shake:<Red:Mmｦ,ﾋuntuk5 jagaｸk-jagaQ...ﾃlebih爨 baikｨ sambungkanA denganﾑku鑷 saja9ｴﾅ.>>"
  },
  AvgDialog_139662_Content_15 = {
    Text = "<Shake:<Red:Sediｷkitz(lebihﾉ cepatｲ dari驫ｲ yang8 diﾃPerkirakanｬ,tapiﾗ tidakｸ apaﾎ-apa靇ﾑ,bukanw kahｦJ?>>"
  },
  AvgDialog_139662_Content_16 = {
    Text = "<Red:Tidak tidak tidak tidak. Semuanya salah. Tidak ada yang benar.>"
  },
  AvgDialog_139662_Content_17 = {
    Text = "<Shake:<Red:ﾒSejakｩﾇ龥 bertahunｯ-tahun7 yangﾘ laluL,ﾝ aku sudahQ menungguｱ齉 hariﾏ inir ｮ麤.>>"
  },
  AvgDialog_139662_Content_18 = {
    Text = "<Shake:Tidak, itu bukan Ramona, Ramona tidak mungkin menjadi gumpalan daging yang buruk rupa dan terdistorsi, tidak mungkin mengeluarkan dengungan rendah yang memualkan seperti itu, tidak mungkin seluruh tubuhnya membanjiri cairan erosi hitam pekat...>"
  },
  AvgDialog_139662_Content_19 = {
    Text = "<Red:Tidak mungkin menatapku lekat-lekat dengan sepasang mata hitam kosong itu——>"
  },
  AvgDialog_139662_Content_2 = {
    Text = "Darahﾝdagingｲw duniaｮ"
  },
  AvgDialog_139662_Content_20 = {
    Text = "Tidak——!"
  },
  AvgDialog_139662_Content_21 = {
    Text = "Aku ini... bermimpi?"
  },
  AvgDialog_139662_Content_22 = {
    Text = "Kau terbangun dengan keringat dingin membasahi sekujur tubuh."
  },
  AvgDialog_139662_Content_23 = {
    Text = "Mimpi yang aneh sekali. Bahkan setelah terbangun, bayangannya masih tertinggal di pandanganku."
  },
  AvgDialog_139662_Content_24 = {
    Text = "Yang ada di pandanganku... adalah..."
  },
  AvgDialog_139662_Content_25 = {
    Text = "...adalah...?"
  },
  AvgDialog_139662_Content_26 = {
    Text = "<Shake:<Red:Gumpalan daging, gumpalan daging besar yang bertumpuk-tumpuk dan saling menutupi.>>"
  },
  AvgDialog_139662_Content_27 = {
    Text = "<Red:Organ-organ merah tua yang bergerak-gerak memenuhi dinding, melilit tiang-tiang, merambati jendela.\nDan di celah-celah antara gumpalan daging itu——>"
  },
  AvgDialog_139662_Content_28 = {
    Text = "Cairan hitam mulai merembes keluar."
  },
  AvgDialog_139662_Content_29 = {Text = "Korosi."},
  AvgDialog_139662_Content_3 = {
    Text = "Rasa sakit, rasa sakit yang luar biasa. Warna merah gelap menusuk retinamu."
  },
  AvgDialog_139662_Content_30 = {
    Text = "Kau sudah melihat terlalu banyak korosi. Tapi tidak seperti ini. Dua penyakit yang sama sekali berbeda menyerang satu tubuh secara bersamaan."
  },
  AvgDialog_139662_Content_31 = {Text = "Ramona..."},
  AvgDialog_139662_Content_32 = {
    Text = "Gambar kembali berkilas. Rongga mata yang gelap dan kosong. Siluet yang terdistorsi dan membengkak. Jari-jarinya di telapak tanganmu berubah menjadi <Shake:daging yang tidak beraturan>——"
  },
  AvgDialog_139662_Content_33 = {
    Text = "Tidak, jangan pikirkan lagi—"
  },
  AvgDialog_139662_Content_34 = {
    Text = "Dia masih ada— dia pasti masih ada di suatu tempat—"
  },
  AvgDialog_139662_Content_35 = {
    Text = "Sebuah getaran sangat halus bergema di dalam kepalamu."
  },
  AvgDialog_139662_Content_36 = {
    Text = "Secara refleks kau mencoba mengenali sumbernya— bukan Ramona. Riak gelombang Ramona bisa kau kenali bahkan dengan mata tertutup, pola mentalnya seperti permukaan danau yang tenang."
  },
  AvgDialog_139662_Content_37 = {
    Text = "Pergi ke timur……"
  },
  AvgDialog_139662_Content_38 = {Text = "Siapa?"},
  AvgDialog_139662_Content_39 = {
    Text = "Tidak ada jawaban."
  },
  AvgDialog_139662_Content_4 = {
    Text = "Kepalaku sakit sekali——"
  },
  AvgDialog_139662_Content_40 = {
    Text = "Sebelum petunjuk lain muncul, kau hanya bisa mengikuti suara itu untuk melangkah maju."
  },
  AvgDialog_139662_Content_41 = {
    Text = "Melangkahi sungai kecil yang mengeluarkan bau karat dan busuk, melangkahi tanah bermembran daging yang dipenuhi jaringan otot merah gelap bagaikan parasit."
  },
  AvgDialog_139662_Content_42 = {
    Text = "Napasmu menjadi sulit, dan saraf-sarafmu berdenyut-denyut akibat erosi warna-warna aneh itu."
  },
  AvgDialog_139662_Content_43 = {
    Text = "Adakah seseorang yang bisa membawaku keluar dari mimpi ini……"
  },
  AvgDialog_139662_Content_44 = {
    Text = "Benar, ini pasti mimpi, meskipun sensasi dalam mimpi ini terasa begitu nyata, tapi kau harus yakin bahwa ini hanyalah sebuah mimpi……"
  },
  AvgDialog_139662_Content_45 = {
    Text = "Sehelai bulu halus putih yang lembut mendarat di ujung hidungmu."
  },
  AvgDialog_139662_Content_46 = {
    Text = "Dandelion……?"
  },
  AvgDialog_139662_Content_47 = {
    Text = "Kau melangkah ke sebuah perbatasan, sebuah garis batas yang jelas terlihat, memisahkan dua dunia."
  },
  AvgDialog_139662_Content_48 = {
    Text = "Di luar perbatasan itu, terdapat daging dan darah yang memuakkan serta cairan korosi yang mengalir deras."
  },
  AvgDialog_139662_Content_49 = {
    Text = "Di dalam batas itu, terbentang sepetak kecil ladang bunga dandelion. Di tengah ladang bunga, berdiri sebuah pondok kayu."
  },
  AvgDialog_139662_Content_5 = {
    Text = "Cahaya redup berkedip, dengungan bergema di gendang telinga, dunia ini tak layak dipercaya, semua yang terlihat di depan mata hanyalah ilusi belaka."
  },
  AvgDialog_139662_Content_50 = {
    Text = "Sesuatu bergerak di antara rumpun dandelion."
  },
  AvgDialog_139662_Content_51 = {
    Text = "Pandanganmu mengikuti gerakan itu. Bola-bola putih halus tersingkap perlahan, memperlihatkan sepotong kecil ujung kain berwarna putih bersih."
  },
  AvgDialog_139662_Content_52 = {
    Text = "Lalu dia berdiri."
  },
  AvgDialog_139662_Content_53 = {
    Text = "Seorang gadis yang bagaikan bunga dandelion."
  },
  AvgDialog_139662_Content_54 = {
    Text = "Dia memiringkan kepalanya sedikit, seolah mengamati ekspresimu."
  },
  AvgDialog_139662_Content_55 = {
    Text = "Penampilanku, tidak menakutkan?"
  },
  AvgDialog_139662_Content_56 = {
    Text = "Sungguh menggelikan. Sepanjang perjalanan ini, dia adalah satu-satunya manusia normal yang kau temui, satu-satunya keberadaan yang tidak menakutkan."
  },
  AvgDialog_139662_Content_57 = {
    Text = "Kalau begitu, mau berjabat tangan?"
  },
  AvgDialog_139662_Content_58 = {
    Text = "Eh, kenapa?"
  },
  AvgDialog_139662_Content_59 = {
    Text = "Hmm... entah kenapa rasanya sekarang memang harus begitu."
  },
  AvgDialog_139662_Content_6 = {
    Text = "Bangunlah, cepat bangun..."
  },
  AvgDialog_139662_Content_60 = {
    Text = "Soal alasannya, aku agak tidak bisa mengingatnya."
  },
  AvgDialog_139662_Content_61 = {
    Text = "Lagipula..."
  },
  AvgDialog_139662_Content_62 = {
    Text = "Gadis itu memiringkan kepalanya, tersenyum seolah penuh ketertarikan."
  },
  AvgDialog_139662_Content_63 = {
    Text = "Kelihatannya kamu juga sangat ingin menyentuhku."
  },
  AvgDialog_139662_Content_64 = {
    Text = "Kau ingin, tentu saja kau ingin."
  },
  AvgDialog_139662_Content_65 = {
    Text = "Setelah semua kegelapan, bau amis, dan serangan indra yang menjijikkan sepanjang perjalanan ini, bagaimana mungkin kau tidak ingin menyentuh manusia hidup pertama yang kau temui?"
  },
  AvgDialog_139662_Content_66 = {
    Text = "Kau mengulurkan tangan, menyentuh jari-jarinya yang ramping dan lembut."
  },
  AvgDialog_139662_Content_67 = {
    Text = "Perasaan yang luar biasa..."
  },
  AvgDialog_139662_Content_68 = {
    Text = "Ya, kamu pun merasakannya, yang datang melalui sentuhan itu, selain kehangatan tubuh manusia, ada pula sensasi lemah seperti arus listrik yang tersambung."
  },
  AvgDialog_139662_Content_69 = {
    Text = "Itu adalah resonansi Inti Perak."
  },
  AvgDialog_139662_Content_7 = {
    Text = "Selamat datang di Universitas Mythag, %player%."
  },
  AvgDialog_139662_Content_8 = {
    Text = "Atau mungkin... selamat datang, kamu secara resmi melangkah ke sisi lain dari dunia."
  },
  AvgDialog_139662_Content_9 = {
    Text = "(Aku ini... sudah kembali?)"
  },
  AvgDialog_139663_Content_1 = {
    Text = "Monster-monster ini……"
  },
  AvgDialog_139663_Content_10 = {
    Text = "Ini sungguh pertanyaan yang agak sulit dijawab. Meskipun sama-sama sebagai penyelidik Messager, Ramona tidak memiliki keistimewaan khususmu sebagai Penjaga Rahasia."
  },
  AvgDialog_139663_Content_11 = {
    Text = "Karena kau adalah Tubuh Kebangkitan, mungkin aku bisa membangun tautan denganmu. Melalui resonansi mimpi, kau bisa mengetahui rupa Ramona."
  },
  AvgDialog_139663_Content_12 = {
    Text = "Dengan dia sebagai petunjuk, mungkin juga bisa menggali ingatanmu."
  },
  AvgDialog_139663_Content_13 = {
    Text = "Kau kembali menggenggam tangan Saya, mencoba mengingat wajah dan senyum Ramona di benakmu, berharap tautan yang nyaris tak terasa itu bisa tersampaikan ke benak Saya."
  },
  AvgDialog_139663_Content_14 = {
    Text = "Krak! Tautan itu terputus."
  },
  AvgDialog_139663_Content_15 = {
    Text = "Sepertinya ada dinding tak kasat mata yang menghalangi tautan kita..."
  },
  AvgDialog_139663_Content_16 = {
    Text = "Mungkin ada kaitannya dengan apa yang harus kulakukan. Ada semacam firasat yang mengingatkanku, bahwa itu adalah hal terlarang yang tidak bisa diceritakan kepada semua orang."
  },
  AvgDialog_139663_Content_17 = {
    Text = "Duar, petir menggelegar di cakrawala."
  },
  AvgDialog_139663_Content_18 = {
    Text = "Hujan deras akan turun. Ayo kita beristirahat di dalam pondok dulu."
  },
  AvgDialog_139663_Content_19 = {
    Text = "Dari celah-celah papan kayu pondok, cairan hitam sesekali melayang naik melawan gravitasi."
  },
  AvgDialog_139663_Content_2 = {
    Text = "Aku juga tidak tahu. Tapi, aku punya firasat, jawabannya tersembunyi di dalam ingatanku."
  },
  AvgDialog_139663_Content_20 = {
    Text = "Saya meringkuk di sudut pondok, separuh wajah bagian bawahnya terbenam di lengannya, bertanya padamu dengan suara pelan."
  },
  AvgDialog_139663_Content_21 = {
    Text = "Ini yang kau sebut \"Erosi\", kan?"
  },
  AvgDialog_139663_Content_22 = {
    Text = "Kau mengangguk sebagai tanda persetujuan."
  },
  AvgDialog_139663_Content_23 = {
    Text = "Apakah ini yang membuatku kehilangan ingatan?"
  },
  AvgDialog_139663_Content_24 = {
    Text = "Bukan hanya kau, banyak sekali orang yang kehilangan ingatan penting karena Erosi."
  },
  AvgDialog_139663_Content_25 = {
    Text = "Ada yang melupakan wajah keluarganya sendiri, terus mencari tanpa henti, bahkan sampai menyakiti orang yang dirindukannya."
  },
  AvgDialog_139663_Content_26 = {
    Text = "Ada yang bahkan melupakan kota tempat mereka dilahirkan, berkelana sendirian di atas lautan, mencari masa lalu yang tak pernah bisa kembali."
  },
  AvgDialog_139663_Content_27 = {
    Text = "...Kehilangan kenangan yang berharga, pasti sangat menyakitkan."
  },
  AvgDialog_139663_Content_28 = {
    Text = "Saya memandang tirai hujan yang tak henti di luar pondok, seolah air hujan bisa membersihkan lumpur dan kekeruhan hitam itu."
  },
  AvgDialog_139663_Content_29 = {
    Text = "Entah apa hal penting yang tersimpan dalam ingatanku?"
  },
  AvgDialog_139663_Content_3 = {
    Text = "Aku akan mencari cara untuk membawamu keluar dari Mystic Realm dan mencari ingatanmu."
  },
  AvgDialog_139663_Content_30 = {
    Text = "Raut kesedihan terpancar dari wajah Shaya."
  },
  AvgDialog_139663_Content_31 = {
    Text = "Kamu tidak menanggapi."
  },
  AvgDialog_139663_Content_32 = {
    Text = "Hujan di luar jendela masih terus menetes rintik-rintik."
  },
  AvgDialog_139663_Content_4 = {Text = "Tapi……"},
  AvgDialog_139663_Content_5 = {
    Text = "Kau ingin menemukan orang bernama Ramona itu dulu, kan?"
  },
  AvgDialog_139663_Content_6 = {
    Text = "Sejujurnya, aku samar-samar ingat, aku pernah bertemu seseorang, lalu……"
  },
  AvgDialog_139663_Content_7 = {
    Text = "Pandangan mata Shaya melayang, separuh kalimatnya ditelan kembali."
  },
  AvgDialog_139663_Content_8 = {
    Text = "Ngomong-ngomong, Ramona yang kau sebut itu, apakah dia istimewa sepertimu?"
  },
  AvgDialog_139663_Content_9 = {
    Text = "Jika dia orang biasa, mungkin dia tidak bisa berkomunikasi denganku."
  },
  AvgDialog_141373_Content_1 = {
    Text = "Ini bukan pertama kalinya Kamu datang ke Epoyanis, namun belum pernah sekalipun, makhluk-makhluk tanpa wajah ini segelisah hari ini."
  },
  AvgDialog_141373_Content_10 = {
    Text = "Tunggu, Kamu adalah… mengapa bisa ada di sini?"
  },
  AvgDialog_141373_Content_11 = {
    Text = "Kebisingan putih yang tajam menelan kesadaran, pasang surut kuno yang tak kasat mata memaksamu mengangkat kepala dengan berat, memandang satu-satunya hal yang bisa dikenali."
  },
  AvgDialog_141373_Content_12 = {
    Text = "Benar, semua itu tidak penting, siapa kamu, apa yang ingin kamu lakukan, Alasan kamu datang ke sini."
  },
  AvgDialog_141373_Content_13 = {
    Text = "Suara berat itu mengusir suara ombak laut, sang tetua memandang dari atas dan mempersempit lingkaran Pemburuan."
  },
  AvgDialog_141373_Content_14 = {
    Text = "Kamu aman, selamat datang kembali."
  },
  AvgDialog_141373_Content_15 = {
    Text = "Oh… ya, Epoyanis, aku kembali ke Epoyanis."
  },
  AvgDialog_141373_Content_16 = {
    Text = "Kamu bergumam mengulanginya, tanpa sadar sudut bibirmu terangkat, semua tindakan selanjutnya terasa begitu wajar."
  },
  AvgDialog_141373_Content_17 = {
    Text = "Baiklah, aku akui ini sedikit melanggar aturan, tapi jangan khawatir, aku akan mengembalikanmu ke Mythag."
  },
  AvgDialog_141373_Content_18 = {
    Text = "Jurang telah menyelimutimu sepenuhnya, kecerdasanmu yang Fragile sama sekali tidak mampu memahami semua yang disampaikan oleh pihak lain di tengah guncangan demi guncangan."
  },
  AvgDialog_141373_Content_19 = {Text = "Apa?"},
  AvgDialog_141373_Content_2 = {
    Text = "Hei, Hei! Berhenti, aku bukan musuh…"
  },
  AvgDialog_141373_Content_20 = {
    Text = "Tawa serak yang singkat."
  },
  AvgDialog_141373_Content_21 = {
    Text = "Hanya Saja bukan sekarang."
  },
  AvgDialog_141373_Content_22 = {
    Text = "Basah, Kaos, sesak, semuanya memenuhi dirimu hingga penuh, lalu bergelombang membuatmu Terjebak dalam, kamu kehilangan semua kendali."
  },
  AvgDialog_141373_Content_23 = {
    Text = "Di telingamu Hanya tersisa bisikan yang bercampur dengan desahan napas."
  },
  AvgDialog_141373_Content_24 = {
    Text = "Sekarang, kamu milik tempat ini, milik-Ku, milik Epoyanis."
  },
  AvgDialog_141373_Content_25 = {
    Text = "Kamu tidak mengerti, kamu Hanya Saja terus mengikuti arus laut purba itu dalam kebahagiaan."
  },
  AvgDialog_141373_Content_26 = {
    Text = "Dia tidak menunjukkan tanda-tanda akan berhenti."
  },
  AvgDialog_141373_Content_3 = {
    Text = "*Suara peluit berburu"
  },
  AvgDialog_141373_Content_4 = {
    Text = "Serangan berhenti, namun, kegelapan tiba-tiba menyapu Kamu. Hampir dalam sekejap, keheningan yang membeku melemparkanmu ke dalam semacam arus tak terkatakan."
  },
  AvgDialog_141373_Content_5 = {Text = "Hm?"},
  AvgDialog_141373_Content_6 = {Text = "Ah……"},
  AvgDialog_141373_Content_7 = {
    Text = "Seolah-olah ingin memastikan sesuatu, mengabaikan merinding yang meledak dari dirimu akibat respons sesaat, penguasa tempat ini dengan sikap tak terbantahkan menyentuh tulang alismu, sudut matamu, hingga sisi lehermu."
  },
  AvgDialog_141373_Content_8 = {
    Text = "Mengunjungi Epoyanis di saat seperti ini bukanlah ide yang baik, %player%."
  },
  AvgDialog_141373_Content_9 = {
    Text = "<Small:Aku Hanya Saja……>"
  },
  AvgDialog_142850_Content_1 = {Text = "Semut"},
  AvgDialog_142850_Content_10 = {
    Text = "Varo… kamu, Kamu menyerahlah! Kami punya begitu banyak orang, kamu tidak mungkin bisa keluar dari Hutan ini dengan hidup!"
  },
  AvgDialog_142850_Content_100 = {
    Text = "Itulah kecepatan dan Kekuatan yang tak mampu ia lawan. Varo mengangkat matanya yang penuh kebingungan, menatap Lotan dengan tidak mengerti."
  },
  AvgDialog_142850_Content_101 = {
    Text = "Kamu… sudah berjanji…"
  },
  AvgDialog_142850_Content_102 = {
    Text = "Aku berjanji membiarkanmu bergabung dengan timku. Tapi aku tidak bilang, kamu akan tetap hidup."
  },
  AvgDialog_142850_Content_103 = {
    Text = "Lemah bukanlah kesalahanmu. Tapi kamu tidak cukup murni, prajurit."
  },
  AvgDialog_142850_Content_104 = {
    Text = "Lotan mengambil dua Cap Tulang itu dari tangan Varo, dengan santai mendorong jatuh mayat yang bingung itu, menumpuknya bersama mayat dua belas ksatria tersebut, bagaikan setumpuk sampah yang tidak dipedulikan siapapun."
  },
  AvgDialog_142850_Content_105 = {
    Text = "Dia melirik ke arah semak-semak, mengangkat pedang besarnya, bersiap untuk membelah Cap Tulang yang tersisa itu…"
  },
  AvgDialog_142850_Content_106 = {
    Text = "Tunggu!! —"
  },
  AvgDialog_142850_Content_107 = {
    Text = "Pedang Lotan berhenti di udara, menatap dengan dingin ke arahmu yang merangkak keluar dari semak-semak."
  },
  AvgDialog_142850_Content_108 = {
    Text = "Aku tidak tertarik pada lawan yang terlalu lemah."
  },
  AvgDialog_142850_Content_109 = {
    Text = "Pengikut kecil dari kesatuan Ksatria, jika aku adalah kamu, aku akan kabur sebelum pihak lain berubah pikiran, semakin cepat semakin baik."
  },
  AvgDialog_142850_Content_11 = {
    Text = "Serahkan cap tulangmu, kami berjanji, berjanji kamu bisa pergi dengan selamat!"
  },
  AvgDialog_142850_Content_110 = {
    Text = "Tuan Elian menyuruh kesatuan Ksatria membawa Mahkota kembali untuknya, kalau… kalau dia Menemukan aku kabur, seluruh keluargaku tidak akan bisa selamat…"
  },
  AvgDialog_142850_Content_111 = {
    Text = "Kamu mengumpulkan seluruh keberanianmu, melangkah selangkah ke arah Lotan."
  },
  AvgDialog_142850_Content_112 = {
    Text = "Anda masih memiliki satu lembar cap tulang… kumohon, izinkan aku juga pergi ke Koloseum Paus Langit Bintang, bolehkah? Hanya perlu sampai ke sana, tugasku akan selesai… Anda sekuat itu, aku tidak akan menjadi ancaman apapun bagi Anda…"
  },
  AvgDialog_142850_Content_113 = {Text = "Kamu?"},
  AvgDialog_142850_Content_114 = {
    Text = "Lotan mengangkat alisnya, menatapmu dengan Taunt."
  },
  AvgDialog_142850_Content_115 = {
    Text = "Kekuatanmu bahkan tidak sebanding dengan para sampah yang dibunuh Varo. Detik pertama kamu memasuki Koloseum itu, kamu akan mati seperti seekor ulat."
  },
  AvgDialog_142850_Content_116 = {
    Text = "Pergi sekarang, kamu masih punya kesempatan untuk hidup."
  },
  AvgDialog_142850_Content_117 = {
    Text = "Kamu memandangi jasad-jasad yang berserakan di tanah, memandangi sosok di hadapanmu yang membuatmu merasakan Ketakutan dari lubuk hati terdalam, lalu dengan susah payah menelan ludah."
  },
  AvgDialog_142850_Content_118 = {
    Text = "Kamu tahu, kemenangan sejak awal tidak ada hubungannya denganmu. Kamu sangat ingin meninggalkan iblis di hadapanmu ini, semakin jauh semakin baik."
  },
  AvgDialog_142850_Content_119 = {
    Text = "Kamu sangat ingin melupakan ibu yang dikorbankan hidup-hidup kepada Paus Langit Bintang, melupakan saudara-saudari yang dikurung di kandang kuda, dan hidup dengan baik."
  },
  AvgDialog_142850_Content_12 = {
    Text = "Dia benar, Varo! Bahkan jika kamu adalah tentara bayaran terkuat di enam negara, terjebak dalam kepungan tiga belas orang kami, kamu tidak akan mendapat keuntungan apa pun."
  },
  AvgDialog_142850_Content_120 = {
    Text = "Tapi tidak ada cara, kamu tidak bisa melupakannya. Seperti ikut serta dalam pertarungan yang sudah ditakdirkan menjadi tumbal ini, kamu tidak pernah punya hak untuk memilih."
  },
  AvgDialog_142850_Content_121 = {
    Text = "Aku adalah pemandu regu, tahu Jalan menuju Koloseum. Aku sudah menjadi Pengikut selama bertahun-tahun, aku tahu cara melayani seorang pejuang! Aku sangat berguna, Anda akan membutuhkanku…"
  },
  AvgDialog_142850_Content_122 = {
    Text = "Kamu menarik napas dalam, melangkah maju memungut Cap Tulang itu, lalu menggunakan kain compang-camping untuk membersihkan noda di baju besi Lotan, seperti yang pernah kamu lakukan untuk para ksatria."
  },
  AvgDialog_142850_Content_123 = {
    Text = "Silakan lewat sini, Orang Ini… Orang Ini… eh?"
  },
  AvgDialog_142850_Content_124 = {
    Text = "Kamu membungkuk berdiri di hadapannya, napasnya yang tenang membuatmu tidak berani mengangkat kepala, hanya bisa menatap erat tanah di bawah kakinya. Kamu merasakan, Tatapan Bilah tajam miliknya bertahan beberapa detik di tubuhmu."
  },
  AvgDialog_142850_Content_125 = {
    Text = "Jika menghadapi bahaya, jangan berharap aku akan membantumu."
  },
  AvgDialog_142850_Content_126 = {
    Text = "Tidak perlu akhiran. Kamu bisa memanggilku Lotan."
  },
  AvgDialog_142850_Content_127 = {
    Text = "Lotan menyarungkan pedang besarnya, lalu berjalan ke arah yang kamu tunjuk."
  },
  AvgDialog_142850_Content_128 = {
    Text = "Darah telah sepenuhnya meresap ke dalam tanah. Di kedalaman langit merah gelap, sebuah bayangan besar yang bergerak perlahan tampak samar-samar."
  },
  AvgDialog_142850_Content_129 = {
    Text = "Kamu bergidik, lalu segera mengikuti langkah Lotan."
  },
  AvgDialog_142850_Content_13 = {
    Text = "Kita bisa bekerja sama, bukan?"
  },
  AvgDialog_142850_Content_130 = {
    Text = "Iya… Tuan Lotan!"
  },
  AvgDialog_142850_Content_14 = {
    Text = "Bekerja sama?"
  },
  AvgDialog_142850_Content_15 = {
    Text = "Paus Bintang Langit hanya akan memilih satu orang untuk menjadi Eksekutor-nya, hal ini tidak bisa dilakukan oleh satu orang saja!"
  },
  AvgDialog_142850_Content_16 = {
    Text = "Cukup Lepaskan cap tulang itu, kami berjanji kamu bisa pergi dari sini dengan selamat, dan mendapatkan semua yang bisa kamu dapatkan…"
  },
  AvgDialog_142850_Content_17 = {Text = "Benarkah?"},
  AvgDialog_142850_Content_18 = {
    Text = "Aku tahu, Varo, kamu selamat dari kawanan binatang di pulau terpencil, membunuh orang yang paling kamu cintai di depan cermin, mungkin orang tuamu, anakmu, atau sesuatu yang lain."
  },
  AvgDialog_142850_Content_19 = {
    Text = "Kamu telah hidup setengah bulan di Hutan belantara ini. Kamu pasti tidak ingin pulang begitu saja…"
  },
  AvgDialog_142850_Content_2 = {
    Text = "Daun-daun berjatuhan dari ranting, melayang melintasi langit merah tua, jatuh ke dalam genangan Darah di tanah, menimbulkan riak kecil yang lemah."
  },
  AvgDialog_142850_Content_20 = {
    Text = "Tapi coba pikirkan, pikirkan apa yang Menunggu di depanmu!"
  },
  AvgDialog_142850_Content_21 = {
    Text = "Kamu harus menerobos kepungan kami, menghindari bahaya di sepanjang Jalan, menemukan Arena Paus Bintang Langit, dan bertarung Deathmatch di sana melawan orang-orang paling berbahaya di dunia ini."
  },
  AvgDialog_142850_Content_22 = {
    Text = "Bahkan jika cap tulang itu bisa membawamu ke Arena, bisakah kamu memastikan bahwa kamu akan menjadi orang terakhir yang bertahan hidup?"
  },
  AvgDialog_142850_Content_23 = {
    Text = "Asalkan kamu menyerah, setelah Tuan Elian berkuasa, kamu bisa menjadi pahlawan pendiri negara… pikirkanlah baik-baik, Varo!"
  },
  AvgDialog_142850_Content_24 = {
    Text = "Tawaranmu sangat menggoda. Tapi sayang, Hanya orang lemah yang butuh bersatu untuk menghangatkan diri. Kamu sama sekali tidak mengerti apa artinya menjadi yang kuat."
  },
  AvgDialog_142850_Content_25 = {
    Text = "Tidak perlu banyak bicara, majulah bersama, sampah-sampah Ksatria."
  },
  AvgDialog_142850_Content_26 = {Text = "Kau……"},
  AvgDialog_142850_Content_27 = {
    Text = "Varo! Kamu akan membayar atas ketidakhormatanmu!"
  },
  AvgDialog_142850_Content_28 = {
    Text = "Ksatria! Serbu!!!"
  },
  AvgDialog_142850_Content_29 = {
    Text = "Sekumpulan sampah…"
  },
  AvgDialog_142850_Content_3 = {
    Text = "Hutan kuno diselimuti aroma amis-manis yang tak kunjung hilang, tubuh-tubuh yang menyuburkan tanah dengan Darah terbaring di atas lumut merah tua, menatap dengan Mata penuh ketidakrelaan, sudah lama tak bersuara."
  },
  AvgDialog_142850_Content_30 = {
    Text = "Arus baju besi menyerbu bagai gelombang lautan menuju sosok yang terisolasi di tengah. Serangan lebih dari sepuluh orang menghancurkan lumut dan tulang-tulang kering, membuat Bumi di bawah kaki mereka Guncangan."
  },
  AvgDialog_142850_Content_31 = {
    Text = "Suara benturan logam yang keras meledak di hutan lebat, mengejutkan kawanan burung yang hitam pekat, bagaikan serpihan hitam yang terkelupas dari tajuk pohon."
  },
  AvgDialog_142850_Content_32 = {
    Text = "Ranting dan daun di tempat persembunyian bergetar. Kamu meringkuk di balik semak-semak, mengintip melalui celah-celah sulur tanaman, menahan napas memandangi pembantaian ini."
  },
  AvgDialog_142850_Content_34 = {
    Text = "Pedang melengkung menghancurkan pedang-pedang lain, menembus Caro yang Fragile di balik baju besi, memutus anggota tubuh dan kepala melalui celah-celah pelat baja. Setiap tebasan tepat sasaran, brutal, tanpa satu pun gerakan yang berlebihan."
  },
  AvgDialog_142850_Content_35 = {
    Text = "Strength, kecepatan, keahlian… Di hadapan Orang Ini, pasukan Ksatria Elit berjatuhan satu per satu bagaikan domba yang menunggu disembelih."
  },
  AvgDialog_142850_Content_37 = {
    Text = "Ini… orang ini…"
  },
  AvgDialog_142850_Content_38 = {
    Text = "Serangan dan teriakan perang segera mereda. Varo menarik sepotong kain bersih dari tubuh Ksatria yang telah tewas, mengelap noda Darah dari pedang melengkungnya."
  },
  AvgDialog_142850_Content_39 = {
    Text = "Ia memeriksa bilah pedang yang kini bersih tanpa noda, mengangguk puas. Kemudian, ia menggeledah jasad Ksatria pemimpin dan menemukan cap tulang yang menjadi akses menuju Koloseum."
  },
  AvgDialog_142850_Content_4 = {
    Text = "Hah… tenang… seharusnya tidak ada yang Menemukan aku…"
  },
  AvgDialog_142850_Content_40 = {
    Text = "Satu, dua, tiga… sebelas, dua belas."
  },
  AvgDialog_142850_Content_41 = {
    Text = "Dua belas, dua belas…"
  },
  AvgDialog_142850_Content_42 = {
    Text = "Ia memandang ke sekeliling, tidak menemukan mayat ketiga belas."
  },
  AvgDialog_142850_Content_43 = {
    Text = "Gawat! Ia Menemukan aku… Aku harus segera…"
  },
  AvgDialog_142850_Content_44 = {
    Text = "Kraak——"
  },
  AvgDialog_142850_Content_45 = {
    Text = "Sebatang kayu mati muncul di Jalan mundurmu pada saat yang tidak tepat. Varo berbalik dengan cepat, memandang ke arah semak-semak tempat Kamu bersembunyi."
  },
  AvgDialog_142850_Content_46 = {Text = "!!!"},
  AvgDialog_142850_Content_47 = {
    Text = "Pantas saja rasanya ada yang kurang, ternyata masih ada satu lagi yang bersembunyi di sini."
  },
  AvgDialog_142850_Content_48 = {
    Text = "Keluarlah, kawan, aku akan memberimu kematian yang cepat."
  },
  AvgDialog_142850_Content_49 = {
    Text = "Varo mengagumi bayangan wajahnya yang terpantul di pedang melengkung, berjalan santai mendekat ke arahmu."
  },
  AvgDialog_142850_Content_5 = {
    Text = "Sebuah Mimpi yang penuh gejolak. Kamu bersembunyi di semak-semak, menenangkan napasmu yang tersengal-sengal, mengintip keluar melalui celah-celah pepohonan."
  },
  AvgDialog_142850_Content_50 = {
    Text = "Kamu memandang ke sekeliling, dengan gelisah mencari Jalan pelarian yang tepat."
  },
  AvgDialog_142850_Content_51 = {
    Text = "Tidak bisa… semuanya hutan lebat… dengan tubuh anak kecil seperti ini, aku sama sekali tidak bisa berlari lebih cepat darinya…"
  },
  AvgDialog_142850_Content_52 = {
    Text = "Harus bagaimana…"
  },
  AvgDialog_142850_Content_53 = {
    Text = "Kamu memejamkan Mata, berusaha keras menekan Ketakutan yang bergolak dalam hati, pikiran menjadi kosong…"
  },
  AvgDialog_142850_Content_54 = {
    Text = "<Red:Srek. Srek. Srek.>"
  },
  AvgDialog_142850_Content_55 = {Text = "Hm?"},
  AvgDialog_142850_Content_56 = {
    Text = "langkah kaki menginjak daun-daun gugur dan lumut, datang dari arah yang lain."
  },
  AvgDialog_142850_Content_57 = {
    Text = "Langkah itu tenang, stabil, seperti orang yang berjalan santai di sore hari."
  },
  AvgDialog_142850_Content_58 = {
    Text = "Bantuan dari ordo Ksatria... tidak memilih untuk Keluar, sangat berani, juga sangat bodoh."
  },
  AvgDialog_142850_Content_59 = {
    Text = "Saat langkah kaki berhenti, suara Angin dan kicauan burung semuanya lenyap, bahkan Darah yang merembes dari mayat-mayat di belakangmu seolah berhenti mengalir, seluruh Hutan tenggelam dalam keheningan mati yang aneh."
  },
  AvgDialog_142850_Content_6 = {
    Text = "Sebilah golok ditarik keluar dari dadanya dengan bersih dan tegas, mengeluarkan suara gesekan yang membuat gigi ngilu. Sang prajurit menepuk debu yang menempel di baju zirahnya, lalu mendongak memandang Sekitar."
  },
  AvgDialog_142850_Content_60 = {
    Text = "Seorang wanita muncul dalam Bidang pandangmu. Baju besi ringan hitam berhias menutupi tubuhnya, dua pedang besar kasar yang tidak sebanding dengan postur tubuhnya digenggamnya dengan santai di tangan."
  },
  AvgDialog_142850_Content_61 = {
    Text = "Mata Dia menyapu mayat-mayat yang berserakan di tanah, Tatapan sekilas melintas di atas Luka-luka mereka."
  },
  AvgDialog_142850_Content_62 = {
    Text = "Setiap orang tewas dalam lima tebasan atau kurang, sengaja membidik celah-celah baju zirah, sudut dan kekuatannya tepat... orang-orang ini, Kamu yang membunuh mereka?"
  },
  AvgDialog_142850_Content_63 = {
    Text = "Heh heh heh... Benar. Sayang sekali, aku belum puas bermain, mereka sudah roboh duluan."
  },
  AvgDialog_142850_Content_64 = {
    Text = "Dua belas orang, Kamu tidak terluka. Tidak buruk."
  },
  AvgDialog_142850_Content_65 = {
    Text = "wanita berbaju zirah hitam itu mengangguk dengan puas, langkahnya yang stabil terus mendekat ke arahnya."
  },
  AvgDialog_142850_Content_66 = {
    Text = "Varo Menunggu. Dia mencari Ketakutan di Mata wanita ini, namun yang terlihat hanyalah ketenangan yang menjengkelkan."
  },
  AvgDialog_142850_Content_67 = {
    Text = "Tidak peduli siapa Kamu, aku bisa memberimu tiga menit untuk Keluar. Setelah tiga menit, bisa hidup atau tidak tergantung..."
  },
  AvgDialog_142850_Content_68 = {
    Text = "Aku bilang, apakah Kamu tuli, tidak bisa mendengar perkataanku?"
  },
  AvgDialog_142850_Content_69 = {
    Text = "wanita berbaju zirah hitam itu tidak menjawab, langkahnya tetap tenang seperti orang yang sedang berjalan-jalan. marah seketika membakar Varo, tangannya mencengkeram gagang pisau, mencabut golok tajam itu."
  },
  AvgDialog_142850_Content_7 = {
    Text = "Berikutnya, giliran siapa?"
  },
  AvgDialog_142850_Content_70 = {
    Text = "Tadinya aku ingin mengampuni nyawamu, tapi kalau Kamu begitu ingin mati, maka aku tidak akan segan-..."
  },
  AvgDialog_142850_Content_71 = {Text = "Tring—"},
  AvgDialog_142850_Content_72 = {
    Text = "Suara benturan logam paling nyaring yang pernah didengar Varo sepanjang hidupnya, berlalu begitu saja di telinganya dalam sekejap."
  },
  AvgDialog_142850_Content_73 = {
    Text = "wanita yang seharusnya berada di depan Varo, entah kapan telah muncul di belakangnya. Sebuah pedang besar digenggamnya dengan satu tangan, bilah pedang disandarkan dengan santai di sisi lehernya."
  },
  AvgDialog_142850_Content_74 = {
    Text = "Varo menundukkan kepala. Golok yang ditempa oleh pandai besi paling terampil dari enam negara itu, yang telah membunuh tak terhitung musuh, tergantung beberapa inci dari sarungnya, terpotong hingga ke pangkalnya."
  },
  AvgDialog_142850_Content_75 = {
    Text = "Bilah pedang indah yang menjadi kebanggaannya itu, berputar dan menancap terbalik di tanah yang dibasahi Darah, seperti sebuah batu nisan yang dingin."
  },
  AvgDialog_142850_Content_76 = {
    Text = "Ini… Kamu…"
  },
  AvgDialog_142850_Content_77 = {
    Text = "Seseorang yang bisa memusnahkan seluruh kesatuan Ksatria, kukira setidaknya bisa membangkitkan sedikit minatku."
  },
  AvgDialog_142850_Content_78 = {
    Text = "Wanita berzirah hitam itu berbicara dengan nada kecewa yang tak tersembunyi."
  },
  AvgDialog_142850_Content_79 = {
    Text = "Cap tulang, apakah kamu memilikinya?"
  },
  AvgDialog_142850_Content_8 = {
    Text = "Dia menjilat Darah di pedang melengkungnya, memandang sekeliling ke belasan orang yang mengepungnya, dan bertanya dengan penuh minat."
  },
  AvgDialog_142850_Content_80 = {
    Text = "<Shake:Ada! Ada ada ada!>"
  },
  AvgDialog_142850_Content_81 = {
    Text = "Varo telah melihat banyak orang dan kejadian, dia tahu kapan harus melakukan apa. Kedua kakinya lemas, dan dia berlutut di hadapannya."
  },
  AvgDialog_142850_Content_82 = {
    Text = "Tuan, Tuan tolong dengarkan saya… Paus Bintang Langit hanya akan memilih satu orang untuk menjadi Eksekutornya, hal ini tidak bisa dilakukan oleh satu orang saja!"
  },
  AvgDialog_142850_Content_83 = {
    Text = "Mahkota, Mahkota itu! Itu adalah sesuatu yang diimpikan semua orang… Anda juga sama, bukan?!"
  },
  AvgDialog_142850_Content_84 = {
    Text = "Anda memiliki Strength yang begitu besar, jika kita membentuk sebuah tim, pasti bisa meraih kemenangan akhir!"
  },
  AvgDialog_142850_Content_85 = {
    Text = "Aku akan menjadi pelayan Anda yang paling setia, selamanya mengabdi kepada Anda, membantu Anda mendapatkan Strength Paus Bintang Langit! …"
  },
  AvgDialog_142850_Content_86 = {
    Text = "Tuan… mohon Tuan pertimbangkan…"
  },
  AvgDialog_142850_Content_87 = {
    Text = "Tawaran yang bagus. Aku menerimanya."
  },
  AvgDialog_142850_Content_88 = {
    Text = "Anda… Anda…"
  },
  AvgDialog_142850_Content_89 = {
    Text = "Varo yang sudah mempersiapkan serangkaian panjang argumen, Menemukan semuanya sama sekali tidak diperlukan."
  },
  AvgDialog_142850_Content_9 = {
    Text = "Ketika dia mengangkat pedang melengkungnya, Semua orang serempak mundur selangkah."
  },
  AvgDialog_142850_Content_90 = {
    Text = "Tenang. Aku tidak pernah ingkar janji."
  },
  AvgDialog_142850_Content_91 = {
    Text = "<Shake:Ter-, terlalu bagus!>"
  },
  AvgDialog_142850_Content_92 = {
    Text = "Varo bagaikan diselamatkan dari tepi jurang, dengan tergesa-gesa menggeledah tubuhnya sendiri, akhirnya dengan tangan gemetar mempersembahkan Cap Tulang itu dengan kedua tangan di hadapan Lotan."
  },
  AvgDialog_142850_Content_93 = {
    Text = "Di sini! Inilah dia!"
  },
  AvgDialog_142850_Content_94 = {
    Text = "Ordo ksatria ini berhasil merebut dua Cap Tulang, Asalkan membawa ini, kita bisa pergi bersama ke Koloseum Paus Langit Bintang!"
  },
  AvgDialog_142850_Content_95 = {
    Text = "Saat itu tiba, tidak ada siapapun yang bisa mengalahkan…"
  },
  AvgDialog_142850_Content_96 = {
    Text = "BYURRR——"
  },
  AvgDialog_142850_Content_97 = {Text = "Aaaahhh!!!"},
  AvgDialog_142850_Content_98 = {
    Text = "Mata pedang raksasa itu dengan mudah menembus baju besi, menciptakan luka besar yang hampir menembus tubuh, memanjang dari pinggang kanan Varo hingga bahu kirinya."
  },
  AvgDialog_142850_Content_99 = {
    Text = "Darah hangat menyembur ke semak-semak di hadapanmu, membeku menjadi embun merah gelap di permukaan daun."
  },
  AvgDialog_142851_Content_1 = {
    Text = "Semangat Perjanjian"
  },
  AvgDialog_142851_Content_10 = {
    Text = "Di tengah pilar-pilar batu yang patah itu, sebuah celah menuju ruang lain Mencabik-cabik realitas, seperti sebuah pupil vertikal yang perlahan-lahan membuka."
  },
  AvgDialog_142851_Content_100 = {
    Text = "Dinding daging di bawah kaki bergetar dengan spasme hebat, bau karat yang pekat menyerbu rongga hidung. Ruang itu sendiri mulai dipenuhi Keseruan."
  },
  AvgDialog_142851_Content_101 = {
    Text = "Bagus… Bagus!"
  },
  AvgDialog_142851_Content_102 = {
    Text = "Dua belas ribu tahun, Lotan… aku Menunggu di kehampaan ini, menunggu seseorang yang bisa membuatku merasa bahwa keberadaan bukanlah sebuah siksaan."
  },
  AvgDialog_142851_Content_103 = {
    Text = "Raja, orang suci, pejuang, makhluk iblis… mereka datang ke hadapanku, membawa hasrat yang mereka anggap agung, berlutut, memohon."
  },
  AvgDialog_142851_Content_104 = {
    Text = "Kemudian, mereka perlahan-lahan digerogoti oleh kekuatan yang kuberikan, berubah menjadi satu lagi wajah yang melayang di jurang."
  },
  AvgDialog_142851_Content_105 = {
    Text = "Aku kira itulah seluruh isi dari keabadian."
  },
  AvgDialog_142851_Content_106 = {
    Text = "Hingga kamu berdiri di sini, menatapku dengan Mata yang tidak mendambakan apa pun, memberitahuku bahwa kamu akan… hehehe… kamu akan membunuhku?!!"
  },
  AvgDialog_142851_Content_107 = {
    Text = "Merah gelap yang murni, kental, dan berbobot mengalir dari celah di jantung, menenggelamkan semua urat cahaya dan wajah-wajah di jurang."
  },
  AvgDialog_142851_Content_108 = {
    Text = "Di dalam kemerahan gelap yang membusuk itu, siluet tubuh raksasa Paus Bintang muncul di cakrawala."
  },
  AvgDialog_142851_Content_109 = {
    Text = "Tubuh yang jauh lebih besar dari dunia ini melengkungkan bentuk kehampaan itu sendiri, bidang di bawah kakimu mulai melengkung seperti kertas, dan kegelapan di kejauhan mulai runtuh ke dalam."
  },
  AvgDialog_142851_Content_11 = {
    Text = "Ternyata tidak perlu membunuh lawan untuk membuat Pintu terbuka……Kamu cukup beruntung."
  },
  AvgDialog_142851_Content_110 = {
    Text = "Planet ini tumbuh di atas tubuhnya, manusia dari enam negara ada karena dirinya. Ia adalah dewa yang Devour kekuatan planet, penguasa tak terbantahkan dari bintang ini. Ia adalah ruang itu sendiri."
  },
  AvgDialog_142851_Content_111 = {
    Text = "Fatamorgana lenyap sepenuhnya, Leviathan tiba-tiba membuka kedua matanya yang agung."
  },
  AvgDialog_142851_Content_112 = {
    Text = "Sebuah kekuatan yang mampu menghancurkan langit dan bumi menyembur keluar dari tubuh Paus Bintang. Seluruh ruang Dimensi mulai runtuh, kekuatan tak kasat mata melemparmu terbang, dan kamu jatuh keras di tepi bidang itu."
  },
  AvgDialog_142851_Content_113 = {
    Text = "Jari-jarimu mencengkeram celah itu, berusaha sekuat tenaga agar tidak tergelincir ke dalam jurang."
  },
  AvgDialog_142851_Content_114 = {
    Text = "Kamu membuatku sangat, sangat senang, Lotan!"
  },
  AvgDialog_142851_Content_115 = {
    Text = "Setelah kamu mati, aku akan memerintahkan semua hamba di dunia ini untuk mengukir patung paling megah untukmu!"
  },
  AvgDialog_142851_Content_116 = {
    Text = "Di tengah kegelapan yang menelan segalanya, di hadapan keberadaan maha besar yang tak terlukiskan itu, Lotan menggenggam pedang raksasa dengan kedua tangannya dan melangkah menuju sepasang mata raksasa yang mengerikan itu."
  },
  AvgDialog_142851_Content_117 = {
    Text = "Langkahnya semakin cepat, semakin cepat, dan akhirnya berubah menjadi badai yang tak terbendung. Di wajahnya, terpancar senyum Kegilaan yang belum pernah kamu lihat sebelumnya."
  },
  AvgDialog_142851_Content_118 = {
    Text = "Ayo! Leviathan!!!"
  },
  AvgDialog_142851_Content_119 = {
    Text = "Raungan penuh semangat bagaikan ombak lautan bergema, menghancurkan sisa-sisa kesadaranmu yang terakhir. Tanganmu yang mencengkeram Batu tidak lagi memiliki Kekuatan, dan di dalam badai yang mengaum itu, kamu kembali ke Koloseum melalui celah tersebut."
  },
  AvgDialog_142851_Content_12 = {
    Text = "Lotan memalingkan Tatapannya, Dia sama sekali tidak pernah tertarik padamu. Sosok ramping itu mengangkat pedang besarnya dan berjalan menuju celah tersebut."
  },
  AvgDialog_142851_Content_120 = {
    Text = "Dalam sisa pandanganmu yang terakhir, kamu melihat Lotan menggenggam kedua pedang raksasa itu, melompat menuju dewa yang lebih agung dari bintang-bintang."
  },
  AvgDialog_142851_Content_121 = {
    Text = [[
Badai hancur berkeping-keping.
Badai tidak pernah berpaling.]]
  },
  AvgDialog_142851_Content_13 = {
    Text = "Hingga sosoknya benar-benar lenyap di dalam celah, barulah kamu akhirnya duduk tegak, terengah-engah dengan napas yang dalam."
  },
  AvgDialog_142851_Content_14 = {
    Text = "Hah……hampir mati ketakutan……"
  },
  AvgDialog_142851_Content_15 = {
    Text = "Di sana……apakah itu tempat tinggal Paus Bintang Langit……"
  },
  AvgDialog_142851_Content_16 = {
    Text = "Kamu tadinya ingin melarikan diri dari sini, namun sebuah daya tarik yang tak tertahankan mengalir keluar dari celah itu, seperti benang tak kasat mata yang terikat pada tulang-tulangmu, menarikmu dengan lembut dan terus-menerus."
  },
  AvgDialog_142851_Content_17 = {
    Text = "Kakimu melangkah tanpa sadar menuju celah itu. Celah itu bergetar pelan, seperti sepasang Mata yang lembut sedang menatapmu."
  },
  AvgDialog_142851_Content_18 = {
    Text = "Lihat sebentar saja, hanya sebentar. Melihat seperti apa wujud sang penguasa agung yang men-Devour bintang-bintang itu……kamu menyelinap mendekati celah, mengintip ke dalamnya……"
  },
  AvgDialog_142851_Content_2 = {
    Text = "Lo, Lotan Yang Mulia!……"
  },
  AvgDialog_142851_Content_20 = {
    Text = "Tidak ada cahaya, tidak ada suara, bahkan detak jantungmu sendiri pun tak terdengar. Kamu tidak yakin apakah dirimu masih memiliki tubuh, atau sudah berubah menjadi semacam serpihan kesadaran yang melayang di dalam Void."
  },
  AvgDialog_142851_Content_21 = {
    Text = "Indera peraba Kembali ke tubuhmu, kakimu merasakan gerakan menggeliat yang lembut, hangat, dan berirama. Ia berkontraksi pelan di bawah telapak kakimu, seperti lidah raksasa yang menjilatimu."
  },
  AvgDialog_142851_Content_22 = {
    Text = "Apa ini?!!!…"
  },
  AvgDialog_142851_Content_23 = {
    Text = "Bintang-bintang redup berputar di langit berbintang, sebuah denyutan yang terus berubah warna menerangi ruang tempatmu berada."
  },
  AvgDialog_142851_Content_24 = {
    Text = "Gumpalan Caro yang membentang tak berujung bergelombang di bawah kakimu, seperti sebuah lidah raksasa atau kantung perut."
  },
  AvgDialog_142851_Content_25 = {
    Text = "Kamu menarik napas dalam-dalam, dan bertatapan dengan denyutan berkedip seperti bola Mata di kejauhan itu. Hanya satu detik, pusing yang hebat menyerangmu, aliran Darah hangat mengucur dari rongga hidungmu. Kamu segera memalingkan Tatapanmu."
  },
  AvgDialog_142851_Content_26 = {
    Text = "Dalam sisa pandanganmu yang terakhir, kamu melihat gumpalan denyutan yang berubah-ubah itu mengeras menjadi bentuk, sebuah Fatamorgana Void muncul di hadapan Lotan. Saat Dia membuka mulut, nyanyian paus yang luas bergema di ruang ini."
  },
  AvgDialog_142851_Content_27 = {
    Text = "Selamat datang, penantang keempat ribu yang datang ke hadapanku! Selamat datang di kediamanku."
  },
  AvgDialog_142851_Content_28 = {
    Text = "Memang benar itu kamu."
  },
  AvgDialog_142851_Content_29 = {
    Text = "Pertarungan yang begitu memukau, apa kesenangannya jika tidak bisa menyaksikannya secara langsung."
  },
  AvgDialog_142851_Content_3 = {
    Text = "Aku… aku tidak… tidak pernah berniat untuk merebut Mahkota dari Anda…"
  },
  AvgDialog_142851_Content_30 = {
    Text = "Aku telah menyaksikan setiap pertarunganmu, anak yang membawa pedang besar."
  },
  AvgDialog_142851_Content_31 = {
    Text = "Graku, Saudari Vorn, Sanji, Elian, Alish……di Koloseum yang megah ini, kamu telah mengalahkan semua makhluk paling kuat di planet ini."
  },
  AvgDialog_142851_Content_32 = {
    Text = "Pedangmu tidak memiliki gerakan yang berlebihan. Jiwamu tidak memiliki beban yang berlebihan. Kemenanganmu sangat layak, Lotan."
  },
  AvgDialog_142851_Content_33 = {
    Text = "Fatamorgana itu mengangguk dengan puas."
  },
  AvgDialog_142851_Content_34 = {
    Text = "Makhluk yang datang ke sini, alasannya tidak lain hanya tiga: pengetahuan, kekuasaan, HP."
  },
  AvgDialog_142851_Content_35 = {
    Text = "Raja yang serakah menginginkan takhta abadi, Ibu yang putus asa menginginkan Kebangkitan anaknya yang telah mati, penyihir gila yang ingin melakukan Pengintaian terhadap pengetahuan terlarang… mereka menginginkan banyak, sangat banyak hal."
  },
  AvgDialog_142851_Content_36 = {
    Text = "Maka, mereka menyebabkan Kerusakan, membunuh, mengorbankan segalanya. Mereka berlutut di hadapanku, memohon kepadaku dengan kata-kata yang telah kudengar selama ribuan tahun."
  },
  AvgDialog_142851_Content_37 = {
    Text = "Namun semuanya sepadan… pada akhirnya, setiap orang mendapatkan apa yang mereka cari dengan susah payah."
  },
  AvgDialog_142851_Content_38 = {
    Text = "Lalu, pejuang yang gagah berani… apa yang kamu inginkan?"
  },
  AvgDialog_142851_Content_39 = {Text = "Kekuatan."},
  AvgDialog_142851_Content_4 = {
    Text = "Aku……aku hanya saja……"
  },
  AvgDialog_142851_Content_40 = {
    Text = "Kekuatan hanyalah sebuah alat, sebuah tangga, dan di atas tangga itu, masih ada sesuatu yang Menunggu kamu."
  },
  AvgDialog_142851_Content_41 = {
    Text = "Katakan padaku, apa sebenarnya yang benar-benar kamu inginkan?"
  },
  AvgDialog_142851_Content_42 = {
    Text = "Aku sudah mengatakannya… yang aku inginkan hanyalah Kekuatan. Kekuatan yang semakin besar tanpa batas akhir."
  },
  AvgDialog_142851_Content_43 = {
    Text = "Selain Kekuatan, aku tidak tertarik pada hal lain."
  },
  AvgDialog_142851_Content_44 = {
    Text = "Paus Langit Bintang menatap Lotan dengan penuh rasa ingin tahu, sebuah tawa menggelegar bergema di ruang ini."
  },
  AvgDialog_142851_Content_45 = {Text = "Hehehe..."},
  AvgDialog_142851_Content_46 = {
    Text = "Kata-kata seperti itu, telah kudengar berkali-kali. Setiap orang yang mengucapkannya, pada akhirnya akan Hilang dalam nafsu yang dibawa oleh Kekuatan."
  },
  AvgDialog_142851_Content_47 = {
    Text = "Mereka mendapatkan Kekuatanku, namun tidak mampu menanggung beratnya. Ia tumbuh di dalam sumsum tulang, Menggerogoti jiwa, hasrat untuk membunuh dan menaklukkan menelan kesadaran mereka satu per satu…"
  },
  AvgDialog_142851_Content_48 = {
    Text = "Kisah seperti ini, sudah kulihat empat ribu kali, dan tidak pernah bosan."
  },
  AvgDialog_142851_Content_49 = {
    Text = "Seiring nyanyian paus bergema, sebuah jantung paus yang besar muncul di ruang ini. Sebuah tiang Darah mengalir dari jantung itu, Gabung di hadapan Lotan membentuk rune-rune yang padat."
  },
  AvgDialog_142851_Content_5 = {
    Text = "Kamu sudah lama melupakan Luka di bahumu, tidak punya keberanian untuk menatap langsung sepasang Mata yang tenang itu."
  },
  AvgDialog_142851_Content_50 = {
    Text = "Mereka tersusun menjadi sebuah gambar yang tidak dapat dipahami, setiap kali Lotan mencoba melihat keseluruhannya, ia berubah menjadi bentuk yang sepenuhnya berbeda."
  },
  AvgDialog_142851_Content_51 = {
    Text = "Hanya dengan sekilas meliriknya, kamu merasakan aliran Darah yang membara bergemuruh di dalam tubuhmu, Dampak pada setiap organmu, mendorongmu untuk mengangkat pedang dan menusukkan ke jantung orang di hadapanmu… kamu segera memalingkan pandangan."
  },
  AvgDialog_142851_Content_52 = {
    Text = "Tandatanganinya. Kamu akan mendapatkan apa yang selalu kamu impikan……Kekuatan milikku."
  },
  AvgDialog_142851_Content_53 = {Text = "Harganya?"},
  AvgDialog_142851_Content_54 = {
    Text = "Tidak ada harga, Hanya satu janji."
  },
  AvgDialog_142851_Content_55 = {
    Text = "Kekuatanku akan terhubung denganmu, nasibku akan terikat denganmu. Sejak saat Kontrak ditandatangani, kamu adalah penguasa planet ini, adalah wakil dari kehendakku."
  },
  AvgDialog_142851_Content_56 = {
    Text = "Kamu akan memiliki segalanya dari enam negara, hingga — hingga tiga tahun kemudian, sebuah persaingan baru Mulai, Satu Orang raja baru lahir."
  },
  AvgDialog_142851_Content_57 = {
    Text = "Kamu akan menemaniku, menyaksikan jiwa-jiwa yang menarik itu, menyaksikan dirimu sendiri, melangkah selangkah demi selangkah menuju jurang. Seperti para raja sebelummu."
  },
  AvgDialog_142851_Content_58 = {
    Text = "Namun aku tahu, meskipun kamu mengetahui akibatnya, kamu tidak akan menolak."
  },
  AvgDialog_142851_Content_59 = {
    Text = "Kamu berpikir, kamu berbeda dari empat ribu penantang sebelumnya. Kamu memiliki tekad yang mampu Mengatasi segalanya, kamu tidak akan pernah jatuh ke dalam jurang Kekuatan dan nafsu…"
  },
  AvgDialog_142851_Content_6 = {
    Text = "Lotan tidak berkata apa-apa, hanya saja mengangkat pedangnya dan berjalan mendekat ke arahmu, perlahan namun pasti. Dahinya menempel erat di tanah, tubuhmu gemetar di hadapan sosok yang semakin mendekat itu."
  },
  AvgDialog_142851_Content_60 = {
    Text = "Kontrak ini, bagaimana cara menandatanganinya?"
  },
  AvgDialog_142851_Content_61 = {
    Text = "Senyum Paus Langit Bintang membawa kejenuhan kuno. Dia telah menyaksikan kisah yang sama terlalu banyak kali. Kali ini pun, tidak ada yang berbeda."
  },
  AvgDialog_142851_Content_62 = {
    Text = "…Keserakahan. Tegas. Kamu tidak peduli dengan etiket, namun setidaknya, kamu memiliki kualitas yang membuatku merasa senang."
  },
  AvgDialog_142851_Content_63 = {
    Text = "Ulurkan tanganmu, Lepaskan di atas Kontrak."
  },
  AvgDialog_142851_Content_64 = {
    Text = "Tanpa ragu, Lotan mengulurkan tangan, menekannya di atas gambar yang terbentuk dari Darah segar itu."
  },
  AvgDialog_142851_Content_65 = {
    Text = "Semacam karakter cair yang hidup merayap keluar dari genangan Darah. Ia memanjat dan meresap sepanjang lengan Lotan, menyelinap ke bawah kulitnya."
  },
  AvgDialog_142851_Content_66 = {
    Text = "Di tempat-tempat yang dilalui karakter-karakter itu, Caro Lotan dengan cepat membusuk dan menjadi Pecahan, hanya menyisakan tulang putih yang mengerikan dan Darah merah tua."
  },
  AvgDialog_142851_Content_67 = {
    Text = "Tubuh Lotan gemetar karena kesakitan, namun dari awal hingga akhir ia tidak mengeluarkan suara sedikit pun. Dia membuka lebar kedua matanya yang sudah setengah hancur, dengan sungguh-sungguh Menyaksikan semua ini."
  },
  AvgDialog_142851_Content_68 = {
    Text = "Karakter-karakter itu menyebar melalui jaringan pembuluh darah menuju jantung, akhirnya mencapai kedua matanya. Seketika, pupil Lotan berubah menjadi Pusaran yang sama seperti milik Paus Bintang Langit."
  },
  AvgDialog_142851_Content_69 = {
    Text = "Kemudian, Pusaran itu menghilang, warna pupil Paus Bintang Langit selamanya tertinggal di dalam matanya, dan baju besi seperti tulang putih menutupi tubuhnya yang Baru lahir."
  },
  AvgDialog_142851_Content_7 = {
    Text = "Satu Orang penantang memilih untuk tunduk, satu orang penantang memilih untuk melarikan diri, lima belas penantang memilih kematian……tampaknya, pemenang terakhir kita telah lahir."
  },
  AvgDialog_142851_Content_70 = {
    Text = "Seluruh kekosongan mengeluarkan Resonansi yang dalam dan berat, wajah-wajah yang melayang di jurang itu, yang mati di Koloseum, serentak membuka mulut mereka, mengeluarkan ratapan tanpa suara."
  },
  AvgDialog_142851_Content_71 = {
    Text = "Mereka menyambut Raja Baru mereka."
  },
  AvgDialog_142851_Content_72 = {
    Text = "Ini… inilah Kekuatan Paus Bintang Langit…"
  },
  AvgDialog_142851_Content_73 = {
    Text = "Lotan menggenggam tinjunya, merasakan Kekuatan dari dewa kuno yang mengalir deras di dalam dirinya, merasakan Tautan antara dirinya dan dunia ini."
  },
  AvgDialog_142851_Content_74 = {
    Text = "Dunia yang di-Devour oleh Paus Bintang Langit berdenyut dalam persepsinya, semua HP yang diciptakan dan diperbudak oleh Paus Bintang Langit bagaikan nyala lilin yang kecil, Hanya dengan satu pikiran, semuanya bisa dipadamkan."
  },
  AvgDialog_142851_Content_75 = {
    Text = "Kolam Darah itu Gabung menjadi mahkota Merah Darah, bersinar gemilang di hadapannya."
  },
  AvgDialog_142851_Content_76 = {
    Text = "Kontrak telah terbentuk. nasib kita berdua menjadi satu, tidak dapat dibalikkan. Berapa banyak era aku telah ada, sebanyak itulah beban era yang kamu warisi."
  },
  AvgDialog_142851_Content_77 = {
    Text = "Nikmatilah, Lotan. Aku telah melihat terlalu banyak jiwa yang mirip denganmu. Murni, membara, tak tertandingi."
  },
  AvgDialog_142851_Content_78 = {
    Text = "Aku akan menantikannya… menantikan, hari ketika kamu jatuh ke dalam jurang. Aku akan terlelap dalam tidur panjang yang baru… Sekarang, kamu bisa pergi melakukan semua yang ingin kamu lakukan."
  },
  AvgDialog_142851_Content_79 = {
    Text = "Fatamorgana Paus Bintang Langit meninggalkan Perpisahan yang membosankan, lalu kembali membuka celah itu."
  },
  AvgDialog_142851_Content_8 = {
    Text = "Suara itu mengalir dari segala penjuru, membawa kegembiraan yang tidak menyenangkan. Tak terhitung Fatamorgana di tribun berdiri serentak, wajah-wajah yang terus berubah menampilkan senyuman yang persis sama."
  },
  AvgDialog_142851_Content_80 = {
    Text = "Sudah selesai kamu bicara?"
  },
  AvgDialog_142851_Content_81 = {
    Text = "Kediaman Paus Bintang Langit jatuh dalam keheningan sesaat. Dia tidak mendapatkan pujian dan ketundukan yang diharapkan-Nya, yang Dia dapatkan adalah sepasang Mata seorang pejuang yang Membakar dengan hasrat yang tak tertahankan."
  },
  AvgDialog_142851_Content_82 = {
    Text = "Maka sekarang… saatnya kamu bertindak."
  },
  AvgDialog_142851_Content_83 = {
    Text = "Kamu tidak pernah menyangka, kamu akan melihat kebingungan di Mata Satu Orang dewa."
  },
  AvgDialog_142851_Content_84 = {
    Text = "Kamu... apa yang kamu katakan?"
  },
  AvgDialog_142851_Content_85 = {
    Text = "Kamu bilang, aku bisa melakukan semua yang ingin aku lakukan… Hanya ada satu hal yang ingin aku lakukan. Membunuhmu, atau dibunuh olehmu."
  },
  AvgDialog_142851_Content_86 = {
    Text = "Kebiasaanku adalah membiarkan lawan bertindak lebih dulu. Jadi, saatnya kamu bertindak, Leviathan."
  },
  AvgDialog_142851_Content_87 = {
    Text = "Kamu baru saja menandatangani Kontrak…"
  },
  AvgDialog_142851_Content_88 = {
    Text = "Aku telah berjanji, untuk menjadi Pembela planet ini, pelaksana kehendakmu."
  },
  AvgDialog_142851_Content_89 = {
    Text = "Kamu adalah tuan budak planet ini, aku memerangimu demi mereka, itu pun termasuk menjalankan tugasku."
  },
  AvgDialog_142851_Content_9 = {
    Text = "Suara gemuruh yang berat terdengar. Pilar-pilar batu Koloseum di belakangmu runtuh, serpihan batu beterbangan ke langit, lenyap di kedalaman langit merah gelap seperti rawa itu."
  },
  AvgDialog_142851_Content_90 = {
    Text = "Kamu adalah pemangsa bintang, perwujudan pembantaian dan perang. Bertarung, itulah kehendakmu."
  },
  AvgDialog_142851_Content_91 = {
    Text = "Lelucon yang bagus, Lotan. Pergilah sekarang, kamu masih bisa mendapatkan segalanya yang diinginkan Semua orang. Tetap di sini, kamu tidak akan mendapatkan apa pun."
  },
  AvgDialog_142851_Content_92 = {
    Text = "Perkataanku sudah sangat jelas."
  },
  AvgDialog_142851_Content_93 = {
    Text = "Kontrak telah mengikat nasibmu bersamaku. Kematianku adalah kematianmu."
  },
  AvgDialog_142851_Content_94 = {
    Text = "Aku tidak peduli."
  },
  AvgDialog_142851_Content_95 = {
    Text = "Kekuatanmu, bahkan tidak mencapai setengah dari milikku. Kamu baru saja mendapatkannya, kamu sama sekali tidak memahami kekuatan yang ingin kamu kendalikan… kamu sama sekali tidak mampu menantangku, Lotan."
  },
  AvgDialog_142851_Content_96 = {
    Text = "Aku ingin mencobanya."
  },
  AvgDialog_142851_Content_97 = {
    Text = "Hehehe… Hahahaha!!!"
  },
  AvgDialog_142851_Content_98 = {
    Text = "Paus Langit Bintang tertawa terbahak-bahak. Ia sudah lebih dari sepuluh ribu tahun tidak tertawa sepuas ini."
  },
  AvgDialog_142851_Content_99 = {
    Text = "Suara tawa itu mengalir dari kedalaman kehampaan, menggetarkan setiap urat cahaya, setiap sisik, setiap wajah yang melayang di jurang."
  },
  AvgDialog_142852_Content_1 = {Text = "Penaklukan"},
  AvgDialog_142852_Content_10 = {
    Text = "Kamu berbalik, tepat melihat dua bayangan yang datang menyerbu dengan cepat—"
  },
  AvgDialog_142852_Content_100 = {
    Text = "Alish menatap dengan terkejut pada wanita muda di hadapannya. Cahaya merah darah yang suram menerangi siluetnya. Di saat-saat terakhir hidupnya, dia melihat kepercayaannya sendiri."
  },
  AvgDialog_142852_Content_101 = {
    Text = "Heh… hahaha! Memuaskan!"
  },
  AvgDialog_142852_Content_102 = {
    Text = "Aku sudah membayangkan kematianku sendiri berkali-kali… tidak ada satu pun yang lebih memuaskanku daripada yang terjadi hari ini."
  },
  AvgDialog_142852_Content_103 = {
    Text = "Terima kasih, Nyonya Lotan."
  },
  AvgDialog_142852_Content_104 = {
    Text = "Jenderal Alish membentangkan kedua tangannya, memandikan dirinya dalam cahaya matahari berwarna darah."
  },
  AvgDialog_142852_Content_106 = {
    Text = "Seberkas cahaya pedang yang tajam dan bersih menyala, kepala Alish tua menggelinding jatuh di samping kuda perang yang telah mati dan bendera yang patah."
  },
  AvgDialog_142852_Content_107 = {
    Text = "Kepala yang telah melewati banyak cobaan itu menampakkan senyum kepuasan. Terhadap akhir hidupnya sendiri, Alish tua tidak meminta apa pun lagi."
  },
  AvgDialog_142852_Content_108 = {
    Text = "Setelah memejamkan kedua matanya untuknya, Lotan berbalik, melihat bangsawan yang mengenakan pakaian perdana menteri itu, dan anak kecil yang berada di bawah pisaunya yang gemetar."
  },
  AvgDialog_142852_Content_109 = {
    Text = "Lo… Tuan Lotan…"
  },
  AvgDialog_142852_Content_11 = {Text = "!!!"},
  AvgDialog_142852_Content_110 = {
    Text = "<Shake:Sanji? Sanji!>"
  },
  AvgDialog_142852_Content_111 = {
    Text = "Mengikuti suara Elian, Lotan menoleh sejenak memandang sosok yang tersembunyi dalam kegelapan di belakangnya."
  },
  AvgDialog_142852_Content_112 = {
    Text = "Setelah berjuang sejenak selama beberapa detik, ahli racun dari kediaman perdana menteri menarik kembali tangannya yang gemetar, lalu berbalik dan berlari keluar dari Koloseum. Di hadapan kematian, kebanyakan orang tahu pilihan apa yang harus diambil."
  },
  AvgDialog_142852_Content_113 = {
    Text = "Tampaknya, kendalimu atas orang-orang di sekitarmu sungguh terbatas."
  },
  AvgDialog_142852_Content_114 = {
    Text = "Nyonya Lotan, kita adalah sekutu! Masih ingat?"
  },
  AvgDialog_142852_Content_115 = {
    Text = "Biarkan aku hidup, biarkan aku menemui Paus Bintang Langit… aku akan memberikanmu semua yang kamu inginkan!"
  },
  AvgDialog_142852_Content_116 = {
    Text = "Masih ada {Male=dia,Female=dia}……Kamu tidak ingin {Male=dia,Female=dia} mati, bukan? Aku bisa melihatnya……pertempuran yang begitu sengit, Kamu tetap ingin menjaga nyawa {Male=dia,Female=dia}……"
  },
  AvgDialog_142852_Content_117 = {
    Text = "Langkah kematian terus-menerus mendekati Elian. Suaranya mulai bergetar."
  },
  AvgDialog_142852_Content_118 = {
    Text = "AHHH!!!——"
  },
  AvgDialog_142852_Content_119 = {
    Text = "Belati tajam itu menghujam keras ke bahumu, dan teriakan kesakitanmu bergema di dalam Koloseum."
  },
  AvgDialog_142852_Content_120 = {
    Text = "Lotan! Jika kamu mendekat lagi, orang ini akan mati karenamu!"
  },
  AvgDialog_142852_Content_121 = {
    Text = "Kamu tidak pernah membunuh orang tak bersalah sembarangan… kamu tidak pernah ingin orang tak bersalah mati karenamu! Benar, benar!! Aku tidak mungkin salah menilai orang!!"
  },
  AvgDialog_142852_Content_122 = {
    Text = "Diiringi ratapan yang terus-menerus, Belati itu berputar di dalam tubuhmu."
  },
  AvgDialog_142852_Content_123 = {
    Text = "Lotan tampak tenang seolah tidak mendengar apa pun, dia mengangkat pedang besarnya dan berjalan menuju Elian, langkahnya stabil seperti jalan-jalan santai di sore hari."
  },
  AvgDialog_142852_Content_124 = {
    Text = "Aku mengagumi orang yang murni. Niat membunuh yang murni, Kekuatan yang murni, kemuliaan yang murni, kecerdasan dan kelicikan yang murni."
  },
  AvgDialog_142852_Content_125 = {
    Text = "Tapi kamu, Elian…"
  },
  AvgDialog_142852_Content_126 = {
    Text = "Lotan menggelengkan kepalanya dengan penuh penghinaan."
  },
  AvgDialog_142852_Content_127 = {
    Text = "Kamu bahkan tidak memahami apa yang aku pedulikan."
  },
  AvgDialog_142852_Content_128 = {
    Text = "Kamu, bukan apa-apa."
  },
  AvgDialog_142852_Content_13 = {
    Text = "Dua Angin menerpa melewati sisimu, cairan hangat menyembur ke tubuhmu."
  },
  AvgDialog_142852_Content_130 = {
    Text = "Kilatan pedang yang bersih dan cepat berlalu. Politikus yang telah melanglang buana di enam negara itu, dengan Mata yang terkejut dan tak berdaya, menyambut akhir hidupnya."
  },
  AvgDialog_142852_Content_131 = {
    Text = "Di seluruh Koloseum hanya tersisa dua makhluk yang masih bisa bernapas. Pedang besar di tangan Lotan berlumuran Darah, Tatapan tanpa kehangatan itu pun mengarah padamu."
  },
  AvgDialog_142852_Content_14 = {
    Text = "Tidak ada rasa sakit, kematian pun tampaknya belum Datang. Kamu menyingkirkan tangan yang menutupi kedua Mata, melihat dua kepala segar yang masih menatapmu dengan Mata penuh penyesalan."
  },
  AvgDialog_142852_Content_15 = {Text = "Aaaahhh!!!"},
  AvgDialog_142852_Content_16 = {
    Text = "Kamu segera mundur dua langkah, hampir tersandung separuh mayat Gracchus."
  },
  AvgDialog_142852_Content_17 = {
    Text = "Ha, Saudari Vaughn, dua pemburu bayaran yang begitu terkenal. Para raja dari enam negara telah mencoba berbagai cara tanpa henti, namun tak satu pun berhasil merekrut mereka."
  },
  AvgDialog_142852_Content_18 = {
    Text = "Kini, mereka menghadapi satu-satunya perburuan yang berakhir dengan kekalahan."
  },
  AvgDialog_142852_Content_19 = {
    Text = "Di tengah sorak sorai para Penonton Fatamorgana yang menggelegar bagai ombak, Elian melangkahi mayat-mayat dengan puas."
  },
  AvgDialog_142852_Content_2 = {
    Text = "Dinding batu melingkar Koloseum menjulang tinggi, tribun penuh sesak dengan para Fatamorgana yang memusatkan perhatian."
  },
  AvgDialog_142852_Content_20 = {
    Text = "Urutannya berbeda dari yang kubayangkan, tapi tidak apa-apa. Musuh-musuh kita sudah hampir habis. Sekarang, kurasa kamu perlu istirahat…"
  },
  AvgDialog_142852_Content_21 = {
    Text = "Suara derap kaki kuda yang keras disertai angin kencang Menderu memotong ucapan Elian, tiba-tiba muncul di belakang Elian dan kamu."
  },
  AvgDialog_142852_Content_22 = {
    Text = "Sebelum kamu sempat bereaksi, Lotan mengangkatmu dan melemparkanmu ke samping."
  },
  AvgDialog_142852_Content_23 = {
    Text = "<RedBigShake:Mati—!>"
  },
  AvgDialog_142852_Content_24 = {
    Text = "Ringkikan nyaring kuda perang bergema memenuhi Koloseum. Di tengah debu yang mengepul, seorang jenderal berzirah usang menghentikan kudanya yang berlari kencang, menancapkan Spike pada ujung panji di tangannya ke dada seorang Ksatria yang tak sempat menghindar."
  },
  AvgDialog_142852_Content_25 = {
    Text = "Debu yang perlahan menghilang membentuk siluet sosok yang tidak terlalu kekar. Dia menarik tali kekang dengan lembut, memutar kudanya, lalu sepasang Mata yang telah terbiasa melihat lautan mayat dan Darah menatap kalian dengan tenang."
  },
  AvgDialog_142852_Content_26 = {
    Text = "Kamu tidak sengaja bertatapan dengan sepasang Mata itu sejenak. Tekanan yang luar biasa membuat kedua kakimu lemas, Hampir tidak bisa berdiri."
  },
  AvgDialog_142852_Content_27 = {
    Text = "Debu pun menghilang. Kamu melihat baju zirah tua legendaris yang konon memiliki tujuh puluh retakan, serta kuda perang berzirah yang pernah menginjak tanah enam negeri, dengan angkuh menghembuskan napas panas."
  },
  AvgDialog_142852_Content_28 = {
    Text = "Empat kepala yang meneteskan Darah segar tergantung di sisi kuda perang itu — kebiasaan yang telah dimiliki si lansia sejak kecil."
  },
  AvgDialog_142852_Content_29 = {
    Text = "Jenderal Alish."
  },
  AvgDialog_142852_Content_3 = {
    Text = "Di kedalaman langit merah gelap bagai rawa, bayangan raksasa menyerupai paus bergerak perlahan."
  },
  AvgDialog_142852_Content_30 = {
    Text = "Kamu menyadari bahwa nada bicara Lotan berubah secara nyata untuk pertama kalinya. Suaranya serak dan penuh Keseruan, seperti seekor singa yang mencium bau mangsanya."
  },
  AvgDialog_142852_Content_31 = {
    Text = "Katakan padaku, siapa nama lawanku."
  },
  AvgDialog_142852_Content_32 = {
    Text = "Kamu bisa memanggilku Lotan."
  },
  AvgDialog_142852_Content_33 = {
    Text = "Lotan… Sebagian besar orang yang layak kuhadapi di dunia ini pernah kudengar, tapi aku tidak ingat nama itu."
  },
  AvgDialog_142852_Content_34 = {
    Text = "Mungkin karena sebagian besar orang yang pernah mendengar nama itu sudah mati. Itu tidak penting. Lima menit lagi, kamu akan mengingat namaku."
  },
  AvgDialog_142852_Content_35 = {
    Text = "Ha… Dunia ini sering menghadirkan perubahan yang sulit kuAdaptasi, mungkin, anak-anak muda zaman sekarang memiliki modal yang membuatku waspada."
  },
  AvgDialog_142852_Content_36 = {
    Text = "Pertandingan perpisahan sudah berlalu setengah jam. Bisa bertahan hingga sekarang, kamu pasti memiliki kemampuan yang sepadan dengan kesombonganmu."
  },
  AvgDialog_142852_Content_37 = {
    Text = "Kamu salah paham, Jenderal Alish, kami bukanlah musuhmu."
  },
  AvgDialog_142852_Content_38 = {
    Text = "Minggir, Elian."
  },
  AvgDialog_142852_Content_39 = {
    Text = "(berbisik) Nyonya Lotan, tolong jangan lupakan rencana yang telah kita buat sebelumnya. Sekarang kita seharusnya membereskan musuh-musuh lain terlebih dahulu. Alish sudah tua dan lemah, tunggu sampai tenaganya habis…"
  },
  AvgDialog_142852_Content_4 = {
    Text = "Apakah Dia selalu begitu suka menonton keramaian?"
  },
  AvgDialog_142852_Content_40 = {
    Text = "Aku bilang, minggir."
  },
  AvgDialog_142852_Content_41 = {
    Text = "Elian pernah bertemu banyak orang berbahaya, suara Lotan tidak sedikit pun lebih keras dibanding mereka, namun kata-kata dingin itu membuat Elian merasakan Ketakutan yang belum pernah ia rasakan sebelumnya."
  },
  AvgDialog_142852_Content_42 = {
    Text = "Dia tidak berpikir terlalu lama, dengan Wajah yang tetap tenang dia pun menyingkir memberi jalan."
  },
  AvgDialog_142852_Content_43 = {
    Text = "Tidak banyak orang yang tersisa di Koloseum ini. lawan yang layak kutantang, Hanya ada satu."
  },
  AvgDialog_142852_Content_44 = {
    Text = "Tangan Lotan diletakkan di gagang pedang besarnya, melangkah menuju arah Alish."
  },
  AvgDialog_142852_Content_45 = {
    Text = "Semua Bayangan di tribun itu terdiam sepenuhnya, wajah-wajah mereka yang samar serempak berputar mengikuti langkah Lotan."
  },
  AvgDialog_142852_Content_46 = {
    Text = "Dengungan frekuensi rendah di udara semakin jelas terdengar, bagaikan suatu harapan kuno yang penuh Keserakahan."
  },
  AvgDialog_142852_Content_47 = {
    Text = "Aku telah melihat caramu bertarung, anak muda. Dalam tujuh puluh tahun karier tempurku, aku tidak pernah melihat lawan sekuat dirimu."
  },
  AvgDialog_142852_Content_48 = {
    Text = "Di Koloseum ini terdapat musuh-musuh terkuat di dunia, setiap orang ingin menyerang lebih dulu, tapi kamu tidak. Kamu selalu menunggu lawanmu mencabut pedang terlebih dahulu…"
  },
  AvgDialog_142852_Content_49 = {
    Text = "Bisakah kamu memberitahuku, mengapa?"
  },
  AvgDialog_142852_Content_5 = {
    Text = "Lotan menggelengkan kepala, mencabut pedang besarnya dari tubuh mayat di bawah kakinya."
  },
  AvgDialog_142852_Content_50 = {
    Text = "Karena… musuh yang mencabut pedangnya, akan sedikit lebih kuat."
  },
  AvgDialog_142852_Content_51 = {
    Text = "Lebih… kuat sedikit?"
  },
  AvgDialog_142852_Content_52 = {
    Text = "Aku hanya tertarik pada sesuatu yang lebih kuat. Angkatlah panji perangmu, Alish."
  },
  AvgDialog_142852_Content_53 = {
    Text = "Kata-kata Lotan tidak mengandung sedikit pun nada provokasi. Tangannya diletakkan di atas pedang besarnya, Matanya menatap tajam Orang Itu — sang jenderal yang sudah renta — langkahnya khidmat bagai seorang peziarah."
  },
  AvgDialog_142852_Content_54 = {
    Text = "Heh heh… Hahaha!"
  },
  AvgDialog_142852_Content_55 = {
    Text = "Sang jenderal tua mendongak dan tertawa. Kuda perangnya berdiri tak bergerak, satu manusia dan satu kuda berdiri sendiri di tengah Koloseum, panji merah Berantakan berkibar-kibar di tengah Angin."
  },
  AvgDialog_142852_Content_56 = {
    Text = "Sangat mirip. Benar-benar sangat mirip… Jika sedikit lebih muda, mungkin kita bisa melihat diri kita sendiri yang lain di dunia ini."
  },
  AvgDialog_142852_Content_57 = {
    Text = "Bagaimanapun juga… semoga kita tidak akan mengecewakan satu sama lain!"
  },
  AvgDialog_142852_Content_58 = {
    Text = "Suara Alish tiba-tiba meninggi, kedua kakinya dengan terampil menepuk, kuda perang yang telah bersamanya bertahun-tahun dalam pertempuran itu langsung bergerak, ringkikan nyaring Gaung di medan perang yang luas——"
  },
  AvgDialog_142852_Content_59 = {
    Text = "Panji berkibar, bagaikan kilat merah yang membelah debu di tengah Koloseum, melesat menerjang Lotan."
  },
  AvgDialog_142852_Content_6 = {
    Text = "Tulang yang tertembus bergesekan dengan bilah pedang menghasilkan suara yang membuat gigi ngilu, tubuh kekar itu tercabik menjadi dua bagian, sepasang mata penuh penyesalan menggelinding bersama separuh tubuh ke dalam selokan berlumuran Darah."
  },
  AvgDialog_142852_Content_60 = {
    Text = "Kamu melihat, sudut bibir Lotan terangkat tanpa bisa di-Inhibisi. Ini adalah pertama kalinya Kamu melihat senyum Lotan."
  },
  AvgDialog_142852_Content_61 = {
    Text = "Dia mencabut pedang besarnya, lalu dengan keras menghantam kilat merah itu dari depan—"
  },
  AvgDialog_142852_Content_63 = {Text = "Bum!!! —"},
  AvgDialog_142852_Content_64 = {
    Text = "Pedang besar putih berbenturan dengan panji merah, suara berfrekuensi tinggi dan tajam menggetarkan gendang telinga setiap orang."
  },
  AvgDialog_142852_Content_65 = {
    Text = "Kuku besi kuda perang mengepulkan debu, sosok Lotan dan Alish saling bersilangan di medan perang yang suram."
  },
  AvgDialog_142852_Content_66 = {
    Text = "Setiap kali terjadi benturan, bayangan paus raksasa di langit bergetar hebat, seolah-olah sedang menikmati Kelezatan yang Mengerikan yang langka."
  },
  AvgDialog_142852_Content_68 = {
    Text = "Jenderal Alish… Nyonya Lotan…"
  },
  AvgDialog_142852_Content_69 = {
    Text = "Sungguh pertarungan yang menakjubkan…"
  },
  AvgDialog_142852_Content_7 = {
    Text = "Tadi dia bilang, siapa namanya?"
  },
  AvgDialog_142852_Content_70 = {
    Text = "Kamu berusaha keras menangkap sosok keduanya dengan Mata, namun itu membuatmu sangat sulit untuk membedakan mereka."
  },
  AvgDialog_142852_Content_71 = {
    Text = "Vira, lakukan sekarang."
  },
  AvgDialog_142852_Content_72 = {
    Text = "Baik, Tuan Elian."
  },
  AvgDialog_142852_Content_73 = {Text = "!!!"},
  AvgDialog_142852_Content_74 = {
    Text = "Itu adalah… penyihir pembuat racun dari kediaman perdana menteri?! Nyonya Lotan! Hati-hati…"
  },
  AvgDialog_142852_Content_75 = {
    Text = "Kata-katamu belum selesai, sebuah sentuhan dingin menempel di kulitmu."
  },
  AvgDialog_142852_Content_76 = {
    Text = "Ssst… burung pipit kecil. Kamu telah setia kepadaku selama ini, apakah sekarang kamu ingin mengkhianatiku demi seseorang yang tidak kamu kenal sama sekali?"
  },
  AvgDialog_142852_Content_77 = {
    Text = "Aku… tapi…"
  },
  AvgDialog_142852_Content_78 = {
    Text = "Aku sudah berkata, begitu aku mendapatkan Mahkota Paus Bintang Langit dan menjadi raja tertinggi enam negara, keluargamu dan dirimu sendiri akan mendapatkan anugerah yang layak."
  },
  AvgDialog_142852_Content_79 = {
    Text = "Tapi sekarang, tutup mulutmu baik-baik untukku."
  },
  AvgDialog_142852_Content_8 = {
    Text = "Gracchus… Gladiator paling terkenal di seluruh utara, tidak pernah kalah di Koloseum mana pun di enam negara…"
  },
  AvgDialog_142852_Content_80 = {
    Text = "Tenggorokan bergulir. Hanya mereka yang menjadi budak yang tahu betapa kuatnya daya tarik kata-kata Elian itu."
  },
  AvgDialog_142852_Content_81 = {
    Text = "Kamu melihat ahli racun itu menyembunyikan dirinya dan berbaur ke dalam debu asap, lalu tidak bersuara lagi."
  },
  AvgDialog_142852_Content_82 = {Text = "Hm?"},
  AvgDialog_142852_Content_83 = {
    Text = "Sang jenderal yang sedang memacu kudanya dengan cepat menangkap sekilas sosok yang menghilang ke dalam asap debu, alisnya berkerut erat. Hal itu membuat reaksinya sedikit terlambat."
  },
  AvgDialog_142852_Content_84 = {
    Text = "Ketika pedang besar yang ganas itu kembali dihantamkan ke arahnya, ia hanya bisa mengangkat panji perang untuk menangkisnya dengan susah payah."
  },
  AvgDialog_142852_Content_86 = {
    Text = "Sebuah benturan Brawn yang dahsyat, kuda perang sempoyongan dan tiba-tiba jatuh ke tanah. Panji merah cerah itu patah menjadi dua, sebuah pedang besar menghadang di lehernya."
  },
  AvgDialog_142852_Content_87 = {
    Text = "Gerakanmu melambat, Alish."
  },
  AvgDialog_142852_Content_88 = {
    Text = "… Sekutumu, telah mengkhianatimu."
  },
  AvgDialog_142852_Content_89 = {
    Text = "Apakah hal itu penting?"
  },
  AvgDialog_142852_Content_9 = {
    Text = "Kamu sudah sering melihat orang mati, namun pemandangan di depanmu ini tetap membuat perutmu bergolak."
  },
  AvgDialog_142852_Content_90 = {
    Text = "Kau bilang... apa?"
  },
  AvgDialog_142852_Content_91 = {
    Text = "Lotan menghela napas pelan, dalam hembusan napas ringan itu penuh dengan penyesalan."
  },
  AvgDialog_142852_Content_92 = {
    Text = "Kamu sudah sangat dekat, Alish, tapi belum cukup. Di atas Strength dan pertempuran, kamu masih memiliki hasrat lain — kehormatan."
  },
  AvgDialog_142852_Content_93 = {
    Text = "Kamu terlalu mempedulikan hal-hal yang membosankan itu. Kamu belum cukup murni."
  },
  AvgDialog_142852_Content_94 = {
    Text = "Lotan Buka mata, menggelengkan kepala, sama sekali tidak mempedulikan bayangan yang bersembunyi di belakangnya."
  },
  AvgDialog_142852_Content_95 = {
    Text = "Kamu berpikir, dengan bantuan Elian, kalian bertarung melawanku bersama-sama, itu bukan kemenangan yang terhormat."
  },
  AvgDialog_142852_Content_96 = {
    Text = "Bukankah memang seharusnya begitu? Dua orang dengan kemampuan dan pemikiran yang setara, sebuah duel yang adil…"
  },
  AvgDialog_142852_Content_97 = {
    Text = "Lihat berapa banyak kata yang kamu gunakan. Kehormatan, keadilan, martabat… semuanya adalah rantai yang diciptakan oleh orang-orang lemah untuk diri mereka sendiri."
  },
  AvgDialog_142852_Content_98 = {
    Text = "Seorang pejuang dilahirkan hanya untuk bertarung. Pertempuran… hanyalah pertempuran semata. Tidak ada hubungannya dengan hal lain apa pun."
  },
  AvgDialog_142852_Content_99 = {
    Text = "Bayangan di langit berhenti, mengeluarkan gemuruh yang penuh kesenangan."
  },
  AvgDialog_142853_Content_1 = {
    Text = "Satu-satunya Aturan"
  },
  AvgDialog_142853_Content_10 = {
    Text = "Aku bilang… Lotan yang terhormat… bisakah Anda berjalan sedikit lebih lambat…"
  },
  AvgDialog_142853_Content_100 = {
    Text = "Tuan Lotan… jangan percaya kata-katanya! Dia adalah penipu… Saya berada di sisinya dan menyaksikan dia melakukan begitu banyak kejahatan…"
  },
  AvgDialog_142853_Content_101 = {
    Text = "Saya percaya, Anda tidak akan bekerja sama dengan orang seperti dia…"
  },
  AvgDialog_142853_Content_102 = {
    Text = "Kamu melambaikan tangan berulang kali ke arah Lotan. Kamu ingin mengingatkannya betapa liciknya Elian."
  },
  AvgDialog_142853_Content_103 = {
    Text = "Dari budak menjadi Pedagang, dari Pedagang menjadi bangsawan, dari bangsawan menjadi perdana menteri, Elian menapaki jalan yang sulit dan meninggalkan tak terhitung jejak kaki, setiap jejak kaki dipenuhi dengan Kebohongan dan Darah."
  },
  AvgDialog_142853_Content_104 = {
    Text = "Namun Lotan tidak memandang kamu. Dia memalingkan kepala, menatap langit merah gelap. Bayangan besar berbentuk paus itu masih bergerak perlahan, siluet yang dipenuhi duri tulang tampak samar-samar."
  },
  AvgDialog_142853_Content_105 = {Text = "Minggir."},
  AvgDialog_142853_Content_106 = {
    Text = "Kamu dengan mati rasa menyingkir. Lotan berjalan melewati sisimu, menundukkan kepala memandang perdana menteri di hadapannya. Cahaya merah gelap membentuk siluet tajam di belakangnya."
  },
  AvgDialog_142853_Content_107 = {
    Text = "Kamu jauh lebih menarik daripada Ksatria-Ksatria-mu, Elian. Saya tidak peduli seperti apa dirimu, dan tidak peduli kapan kamu akan berkhianat. Kamu bisa membantuku, itu sudah cukup."
  },
  AvgDialog_142853_Content_108 = {
    Text = "Saya menyetujui permintaanmu. Jangan ganggu pertarunganku, itu satu-satunya syaratku."
  },
  AvgDialog_142853_Content_109 = {
    Text = "Tuan Lotan… Anda…"
  },
  AvgDialog_142853_Content_11 = {
    Text = "Sepanjang Jalan Anda hampir tidak berbicara, hanya sibuk membunuh dan bergegas, juga hampir tidak beristirahat…"
  },
  AvgDialog_142853_Content_110 = {
    Text = "Hasrat kekuasaan yang mengalir di udara menghantam kamu bagai pasang surut, senyum pahit merayap ke Wajahmu. Semua orang yang datang ke Koloseum ini sama saja, kamu seharusnya tidak menaruh harapan apa pun."
  },
  AvgDialog_142853_Content_111 = {
    Text = "Elian menyeringai, dalam sikapnya tidak ada sedikit pun kegembiraan yang melampaui rasa terkejut, Seolah-olah ini adalah negosiasi yang pasti akan dimenangkan."
  },
  AvgDialog_142853_Content_112 = {
    Text = "Dia berbalik dan berjalan menuju tribun di tepi Koloseum."
  },
  AvgDialog_142853_Content_113 = {
    Text = "Informasi tentang Semua orang, tim yang akan mereka bentuk, saat mereka akan terpecah, serta urutan tantangan yang paling bisa membuatmu senang, semuanya sudah saya pikirkan untukmu."
  },
  AvgDialog_142853_Content_114 = {
    Text = "Nikmati pertarungan ini, Nyonya Lotan."
  },
  AvgDialog_142853_Content_12 = {
    Text = "Kamu mau menutup mulutmu sendiri, atau mau aku masukkan pedang ke dalam mulutmu?"
  },
  AvgDialog_142853_Content_14 = {
    Text = "Kamu menutup mulutmu erat-erat. Tatapan Lotan tidak tertuju padamu. Dia mengamati lingkungan Sekitar, tangannya menyentuh sepotong tiang batu yang patah."
  },
  AvgDialog_142853_Content_15 = {
    Text = "Permukaan potongan tiang batu itu dipenuhi guratan hitam menyerupai pembuluh Darah, seperti jaringan makhluk hidup yang sedang tumbuh."
  },
  AvgDialog_142853_Content_16 = {Text = "Ini…"},
  AvgDialog_142853_Content_17 = {
    Text = "Kamu menempelkan telingamu pada tiang batu itu, sayup-sayup mendengar irama yang sangat dalam, seperti makhluk raksasa yang bernapas perlahan di kedalaman Batu."
  },
  AvgDialog_142853_Content_18 = {
    Text = "Rasa mual yang tiba-tiba dan dorongan untuk membunuh menyerbu tubuhmu, kamu segera mundur."
  },
  AvgDialog_142853_Content_19 = {
    Text = "Benda ini… masih hidup?!"
  },
  AvgDialog_142853_Content_2 = {
    Text = "Ini Jalan yang kamu tunjukkan?"
  },
  AvgDialog_142853_Content_20 = {
    Text = "Dalam legenda, Paus Langit Bintang menciptakan dunia ini dengan tubuh-Nya, rakyat keenam negeri, semuanya hidup di atas raga-Nya."
  },
  AvgDialog_142853_Content_21 = {
    Text = "Sepertinya, kita sudah sangat dekat dengannya."
  },
  AvgDialog_142853_Content_22 = {
    Text = "Lotan berjalan menuju sebuah meja batu di tengah alun-alun. Meja batu yang terbuat dari lapis lazuli itu, dengan pengerjaan yang halus dan bahan yang mahal, sangat tidak sesuai dengan tempat yang sunyi ini."
  },
  AvgDialog_142853_Content_23 = {
    Text = "Permukaan meja batu itu tertutup lapisan sisik yang halus dan lembap, membuka dan menutup perlahan di bawah cahaya redup, dengan frekuensi seperti suara napas yang baru saja kamu dengar."
  },
  AvgDialog_142853_Content_24 = {
    Text = "Lotan meletakkan kedua Cap Tulang itu di atasnya. Sesaat Cap Tulang menyentuh sisik-sisik itu, sisik-sisik tersebut tiba-tiba mengetat, seperti jari-jari tak terhitung yang mencengkeram mangsa, Devour kedua stempel tua berbahan tulang itu hingga lenyap."
  },
  AvgDialog_142853_Content_25 = {
    Text = "Stempel tulang kita!!!"
  },
  AvgDialog_142853_Content_26 = {
    Text = "Ah! Dua penantang baru!"
  },
  AvgDialog_142853_Content_27 = {
    Text = "Saat kamu berlari menuju meja batu itu, sebuah siluet berbentuk manusia perlahan-lahan muncul dari tengah meja batu."
  },
  AvgDialog_142853_Content_28 = {
    Text = "Wajahnya terus berubah-ubah, kadang menjadi raja, kadang menjadi Ksatria, kadang menjadi sesuatu yang tidak bisa kamu kenali."
  },
  AvgDialog_142853_Content_29 = {
    Text = "Suaranya seperti datang dari bawah genangan Darah, setiap suku kata membawa Resonansi yang aneh."
  },
  AvgDialog_142853_Content_3 = {
    Text = "Yang kita cari adalah Koloseum, bukan reruntuhan. Tempat ini terlihat sudah lama ditinggalkan."
  },
  AvgDialog_142853_Content_30 = {
    Text = "Aku adalah Fatamorgana dari Paus Langit Bintang, pelayan paling setia-Nya, sekaligus pengelola dan Penonton dari Koloseum ini."
  },
  AvgDialog_142853_Content_31 = {
    Text = "Kalian telah melewati berbagai rintangan, akhirnya mengandalkan Kekuatan dan kecerdasan kalian sendiri untuk tiba di sini. Kalian adalah kebanggaan keenam negeri, yang paling kuat dan tangguh…"
  },
  AvgDialog_142853_Content_32 = {
    Text = "Bisa kurangi basa-basinya."
  },
  AvgDialog_142853_Content_33 = {
    Text = "……Kamu cukup tidak sopan, penantang. Beruntungnya, Paus Bintang Langit tidak pernah peduli dengan hal-hal itu."
  },
  AvgDialog_142853_Content_34 = {
    Text = "Yang Dia pedulikan hanya satu hal: Kekuatan. Kekuatan yang murni, tanpa secuil pun niat lain."
  },
  AvgDialog_142853_Content_35 = {
    Text = "Selamat datang, selamat datang di Koloseum Paus Bintang Langit, selamat datang di panggung Kekuatan yang murni—"
  },
  AvgDialog_142853_Content_36 = {
    Text = "Fatamorgana mengangkat kedua tangannya, suara berfrekuensi rendah dan jauh seperti nyanyian paus keluar dari dalam tubuhnya, menembus tulangmu, Resonansi di dalam rongga tengkorakmu."
  },
  AvgDialog_142853_Content_37 = {
    Text = "(!!! Ini adalah...)"
  },
  AvgDialog_142853_Content_38 = {
    Text = "Nyanyian itu menyebar bagai riak air, dan di mana pun gelombangnya menjangkau, langit diwarnai merah gelap, reruntuhan dinding yang hancur dihubungkan oleh lendir tak dikenal, dan bangunan-bangunan bak puing berubah menjadi sebuah Koloseum kuno yang megah."
  },
  AvgDialog_142853_Content_39 = {
    Text = "Patung-patung dewa raksasa di Sekitar membuat berbagai gestur, menatap makhluk-makhluk kecil seperti semut di bawah kaki mereka dengan Mata penuh belas kasih atau marah."
  },
  AvgDialog_142853_Content_4 = {
    Text = "Aku hafal betul petanya, seharusnya memang tempat ini yang benar… tapi kenapa tempat ini berbeda dari yang tercatat?"
  },
  AvgDialog_142853_Content_40 = {
    Text = "Belasan penantang tersebar berkelompok di Sekitar panggung utama, diam-diam mengamati kalian."
  },
  AvgDialog_142853_Content_41 = {
    Text = "Satu, dua, tiga… lima belas, enam belas."
  },
  AvgDialog_142853_Content_42 = {
    Text = "Cap Tulang berjumlah dua puluh keping, seharusnya masih ada dua orang lagi di belakang……"
  },
  AvgDialog_142853_Content_43 = {
    Text = "Tidak ada lagi, penantang. Kedua Cap Tulang itu telah hancur dalam pertarungan babak sebelumnya."
  },
  AvgDialog_142853_Content_44 = {
    Text = "Selamat kepada kalian berdua. Sebagai orang yang tiba paling akhir, kalian akan mendapat kehormatan untuk diperhatikan oleh semua orang——"
  },
  AvgDialog_142853_Content_45 = {
    Text = "Di tengah tawa ringan Fatamorgana, enam belas Tatapan tidak bersahabat diarahkan kepada kalian."
  },
  AvgDialog_142853_Content_46 = {
    Text = "Orang itu terasa sangat familiar… sepertinya pernah melihatnya di poster promosi arena gladiator mana?"
  },
  AvgDialog_142853_Content_47 = {
    Text = "Pakaian itu… sepertinya milik organisasi pembunuh yang disebut Jari Kelingking! Tidak menyangka bisa bertemu orang mereka di sini…"
  },
  AvgDialog_142853_Content_48 = {
    Text = "Kamu tahu cukup banyak."
  },
  AvgDialog_142853_Content_49 = {
    Text = "Aku tidak bisa berbicara di rapat Ksatria, tapi sudah sering ikut mendengarkan. Tuan Elian sudah menceritakan banyak hal kepada kami…"
  },
  AvgDialog_142853_Content_5 = {
    Text = "Kamu memandang dinding-dinding runtuh Sekitar yang telah lapuk selama bertahun-tahun, lalu menggaruk kepala."
  },
  AvgDialog_142853_Content_50 = {
    Text = "Ah! Lihat ke sana!! Orang yang memakai baju besi tua itu!"
  },
  AvgDialog_142853_Content_51 = {
    Text = "Itu adalah jenderal paling gagah berani dari enam negara! Dia pernah sendirian membunuh raja negara musuh di medan perang, aku tumbuh besar dengan mendengar kisah-kisahnya!"
  },
  AvgDialog_142853_Content_52 = {
    Text = "Satu Orang legenda yang masih hidup! Tidak menyangka… tidak menyangka bisa bertemu dengannya di sini!"
  },
  AvgDialog_142853_Content_53 = {
    Text = "Lotan tidak menghiraukan teriakan kegembiraanmu yang tak terbendung. Dia menyapu pandangan ke arah para peserta, lalu bersandar pada pilar batu dan memejamkan mata."
  },
  AvgDialog_142853_Content_54 = {
    Text = "Sebelum Ksatria ikut dalam perebutan ini, aku dan nyonya bertaruh siapa yang akan masuk ke istana Paus Bintang."
  },
  AvgDialog_142853_Content_55 = {
    Text = "Kamu melakukannya dengan baik, pipit kecil. Setelah permainan membosankan ini berakhir, nyonya harus membayarku sejumlah besar uang."
  },
  AvgDialog_142853_Content_56 = {Text = "!!!"},
  AvgDialog_142853_Content_57 = {
    Text = "E… Tuan Elian…"
  },
  AvgDialog_142853_Content_58 = {
    Text = "Suara lembut, langkah yang mantap, jubah lebar dari kain mahal, aroma parfum juniper di tubuhnya… bahkan jika telah menjadi Abu pun, kamu bisa mengenalinya."
  },
  AvgDialog_142853_Content_59 = {
    Text = "Anda… bagaimana Anda bisa datang sendiri… Maksud saya…"
  },
  AvgDialog_142853_Content_6 = {
    Text = "Raja berkata dalam buku hariannya, dinding-dinding di sini terbuat dari Emas, di langit sini terbang utusan dewa bersayap enam, dan di sungai sini mengalir madu dan anggur…"
  },
  AvgDialog_142853_Content_60 = {
    Text = "Anda meminta Ksatria untuk membantu Anda merebut Mahkota, saya kira…"
  },
  AvgDialog_142853_Content_61 = {
    Text = "Kamu kira aku akan menaruh seluruh harapanku pada sebuah Ksatria yang bahkan tidak bisa mengalahkan tentara bayaran? Aku pernah mengajarimu, pipit kecil, jangan pernah menaruh semua telur dalam satu keranjang."
  },
  AvgDialog_142853_Content_62 = {
    Text = "Tolong percayalah pada Elian yang baik hati, Paus Bintang yang agung selalu memberikan Berkat kepada orang-orang baik."
  },
  AvgDialog_142853_Content_63 = {
    Text = "Bangsawan itu tersenyum dengan anggun. Tatapannya tidak pernah lepas dari Lotan."
  },
  AvgDialog_142853_Content_64 = {
    Text = "Orang Ini adalah… temanmu?"
  },
  AvgDialog_142853_Content_65 = {
    Text = "Hmm, mungkin tidak terlalu…"
  },
  AvgDialog_142853_Content_66 = {
    Text = "Lotan. Seorang pejuang."
  },
  AvgDialog_142853_Content_67 = {
    Text = "Senang bertemu denganmu, Nyonya Lotan. Semoga pelayanku tidak menyusahkanmu."
  },
  AvgDialog_142853_Content_68 = {
    Text = "Perdana Menteri?"
  },
  AvgDialog_142853_Content_69 = {
    Text = "Tatapan Lotan menyapu ornamen pakaian dan pedang yang tergantung di pinggangnya. Bahkan bagi mereka yang tidak peduli dengan politik enam negara sekalipun, Cap Perdana Menteri tetaplah sangat mudah dikenali."
  },
  AvgDialog_142853_Content_7 = {
    Text = "Apa yang terjadi dengan alun-alun yang seperti reruntuhan ini… juga tidak terlihat ada orang yang memeriksa cap tulang."
  },
  AvgDialog_142853_Content_70 = {
    Text = "Hanya sebuah jabatan kosong, satu-satunya kegunaannya adalah menghemat waktu perkenalan diri."
  },
  AvgDialog_142853_Content_71 = {
    Text = "Elian tersenyum, lalu duduk di pilar batu di hadapan Lotan."
  },
  AvgDialog_142853_Content_72 = {
    Text = "Kamu membawa budakku ke sini, namun Ksatriaku menghilang begitu saja. Kurasa aku sudah bisa memahami apa yang terjadi di Jalan."
  },
  AvgDialog_142853_Content_73 = {
    Text = "Ksatriamu mati dengan sangat memalukan. Dua belas orang, bahkan tidak sempat menyentuh baju besi seorang pejuang kelas rendah sekalipun."
  },
  AvgDialog_142853_Content_74 = {
    Text = "Dan kamu, dengan mudah menjadi pemenang pertarungan itu."
  },
  AvgDialog_142853_Content_75 = {
    Text = "Kamu sepertinya sama sekali tidak tertarik dengan kematian mereka."
  },
  AvgDialog_142853_Content_76 = {
    Text = "Ah, tidak tidak tidak, Anda salah paham tentang saya, Nyonya Lotan…"
  },
  AvgDialog_142853_Content_77 = {
    Text = "Elian tertawa terbahak-bahak, menggelengkan kepalanya."
  },
  AvgDialog_142853_Content_78 = {
    Text = "Para Ksatria saya semua adalah anak-anak yang baik, setia, tekun… tetapi ini adalah Koloseum Paus Bintang. Yang lemah mendapat akhir yang pantas bagi yang lemah, saya tidak peduli dengan itu."
  },
  AvgDialog_142853_Content_79 = {
    Text = "Yang saya pedulikan adalah kamu, Nyonya Lotan. Seorang pejuang tangguh yang mencintai pedang, pembantaian, dan Darah, rela menyerahkan segalanya demi Mahkota yang ditempa dari Darah…"
  },
  AvgDialog_142853_Content_8 = {
    Text = "Hei! Tunggu aku…"
  },
  AvgDialog_142853_Content_80 = {
    Text = "Kecepatan bicara Elian semakin cepat. Hawa pembantaian dan nafsu kekuasaan yang melayang di udara meresap ke dalam dirinya, membuat hatinya yang telah banyak menanggung beban pun tak bisa menahan diri untuk berdegup kencang."
  },
  AvgDialog_142853_Content_81 = {
    Text = "Seolah menyadari sikapnya yang tidak terkendali, ia menarik napas dalam-dalam dan mundur setengah langkah."
  },
  AvgDialog_142853_Content_82 = {
    Text = "Saya rasa, kita bisa bekerja sama."
  },
  AvgDialog_142853_Content_83 = {
    Text = "Menurutmu, apakah saya orang yang suka bekerja sama?"
  },
  AvgDialog_142853_Content_84 = {
    Text = "Yang lemah selalu terbiasa berkelompok, kamu tentu bukan tipe seperti itu. Tapi, setiap orang punya kebutuhan untuk bekerja sama, kamu pun tidak terkecuali."
  },
  AvgDialog_142853_Content_85 = {
    Text = "Lotan belum sempat menjawab, tak terhitung Fatamorgana yang identik muncul di kursi-kursi Koloseum, memenuhi tribun Penonton yang padat, dan suara seperti nyanyian paus kembali bergema di seluruh Koloseum yang luas dan kosong ini."
  },
  AvgDialog_142853_Content_86 = {
    Text = "Baiklah, para penantang, kami sudah tidak sabar lagi. Ujian terakhir, akan segera dimulai di Koloseum yang megah ini!"
  },
  AvgDialog_142853_Content_87 = {
    Text = "Ketika pemenang terakhir muncul, sebuah Pintu menuju istana Paus Bintang akan terbuka untuknya!"
  },
  AvgDialog_142853_Content_88 = {
    Text = "Di balik Pintu itu, terdapat kemuliaan, kekayaan, kekuasaan yang tak terbatas — segalanya!"
  },
  AvgDialog_142853_Content_89 = {
    Text = "Memilih pemenang… apa aturannya?"
  },
  AvgDialog_142853_Content_9 = {
    Text = "Saat kamu berbicara sendiri di hadapan singgasana batu kuno itu, Lotan berjalan menuju pusat alun-alun yang besar."
  },
  AvgDialog_142853_Content_90 = {
    Text = "Aturan? Hehehe… Hahahaha! Aturan?!…"
  },
  AvgDialog_142853_Content_91 = {
    Text = "Tawa berlebihan para Fatamorgana menggetarkan gendang telinga Semua orang di dalam Koloseum hingga terasa sakit. Di tengah tawa Kegilaan itu, mereka tidak lagi berkata-kata, menatap dengan penuh harap ke tengah Koloseum yang luas dan kosong."
  },
  AvgDialog_142853_Content_92 = {
    Text = "Tapi… dia belum mengatakan apa aturannya…"
  },
  AvgDialog_142853_Content_93 = {
    Text = "Dia sudah mengatakannya. \"Pemenang terakhir\", Hanya Satu Orang. Itulah satu-satunya aturan, burung pipit kecil."
  },
  AvgDialog_142853_Content_94 = {
    Text = "Pembunuhan, tantangan, aliansi, pengkhianatan… Delapan belas peserta, hanya satu orang yang masih berdiri yang dapat melewati pintu itu."
  },
  AvgDialog_142853_Content_95 = {
    Text = "Senyum yang kamu kenal kembali menghiasi Wajah Elian."
  },
  AvgDialog_142853_Content_96 = {
    Text = "Yang akan kamu hadapi adalah sekumpulan orang terkuat di dunia ini."
  },
  AvgDialog_142853_Content_97 = {
    Text = "Tolong jangan salah paham, saya sama sekali tidak Merasakan keraguan terhadap Kekuatan Kamu, Nyonya Lotan."
  },
  AvgDialog_142853_Content_98 = {
    Text = "Namun saya rasa, Kamu juga tidak ingin diganggu oleh orang-orang membosankan saat menikmati pembunuhan yang menyenangkan itu, bukan?"
  },
  AvgDialog_142853_Content_99 = {
    Text = "Lotan untuk pertama kalinya mengangkat kepalanya dengan serius. Dia melihat sepasang Wajah yang tersenyum lembut, serta Mata di wajah itu yang seolah-olah mampu menembus segalanya."
  },
  AvgDialog_142854_Content_1 = {
    Text = "Ringannya Mahkota"
  },
  AvgDialog_142854_Content_10 = {
    Text = "Lo……Lotan Yang Mulia?"
  },
  AvgDialog_142854_Content_11 = {
    Text = "Kamu tidak dapat mengenali apakah orang yang bersimbah Darah di hadapanmu ini adalah Lotan atau bukan."
  },
  AvgDialog_142854_Content_12 = {
    Text = "Darah yang kotor dan busuk memenuhi seluruh tubuhnya, entah berasal dari dirinya sendiri atau dari sesuatu yang lain."
  },
  AvgDialog_142854_Content_13 = {
    Text = "Di balik Darah yang kotor dan baju besi yang hancur itu, setengah tubuhnya hanya menyisakan tulang-belulang yang putih."
  },
  AvgDialog_142854_Content_14 = {
    Text = "Sang prajurit yang hanya tersisa setengah tubuh melangkah keluar dari celah yang dipenuhi bau amis. Langkahnya lambat dan lelah, pedang besar yang patah terseret di tanah, menggores alur dangkal di genangan Darah."
  },
  AvgDialog_142854_Content_15 = {
    Text = "Di tangannya yang satu lagi, Mahkota yang terbentuk dari Darah segar itu sedang meneteskan Darah yang kotor."
  },
  AvgDialog_142854_Content_16 = {
    Text = "Mata-nya bersinar lebih terang dari sebelumnya."
  },
  AvgDialog_142854_Content_17 = {
    Text = "Lo……Lotan Yang Mulia……Paus Langit Bintang……Dia……"
  },
  AvgDialog_142854_Content_18 = {Text = "Dia kalah."},
  AvgDialog_142854_Content_19 = {
    Text = "Suara Lotan tidak memiliki getaran sedikit pun, Seolah-olah hanya sedang menyampaikan sesuatu yang pasti akan terjadi."
  },
  AvgDialog_142854_Content_2 = {
    Text = "Hem... hem hem..."
  },
  AvgDialog_142854_Content_20 = {
    Text = "Anda telah menandatangani Kontrak dengan-Nya……jika Dia menerima Kerusakan, Anda juga……"
  },
  AvgDialog_142854_Content_21 = {
    Text = "Kamu tidak perlu bertanya lebih lanjut. Luka di tubuh Lotan sudah menjelaskan segalanya."
  },
  AvgDialog_142854_Content_22 = {
    Text = "Tuan Lotan, Anda telah mengalahkan semua penantang, bahkan……bahkan Paus Langit Bintang!"
  },
  AvgDialog_142854_Content_23 = {
    Text = "Sekarang, Anda adalah raja planet ini yang tak terbantahkan……sekarang adalah momen paling gemilang dalam hidup Anda! Sekarang……"
  },
  AvgDialog_142854_Content_24 = {
    Text = "Sekarang, juga adalah saat paling Fragile baginya."
  },
  AvgDialog_142854_Content_25 = {
    Text = "Bau amis Darah yang merembes dari celah itu menyelimuti kamu, Bisikan seperti nyanyian paus semakin jelas terdengar di telingamu."
  },
  AvgDialog_142854_Content_26 = {
    Text = "Lihatlah, Mahkota yang terbentuk dari Darah segar……"
  },
  AvgDialog_142854_Content_27 = {
    Text = "Tahta enam kerajaan, kepatuhan jutaan orang, kekayaan dan kemuliaan yang tak pernah habis……Mahkota itu dapat memberikan segalanya kepada pemiliknya."
  },
  AvgDialog_142854_Content_28 = {
    Text = "Setiap orang di Koloseum mendambakannya. Para Ksatria yang setiap hari Memaki kamu, Gracchus, saudari Vorn, Jenderal Alish, Tuan Elian yang serba bisa……"
  },
  AvgDialog_142854_Content_29 = {
    Text = "Dan juga kamu, si pipit kecil. Kamu pun mendambakannya……"
  },
  AvgDialog_142854_Content_3 = {Text = "Ini…"},
  AvgDialog_142854_Content_30 = {
    Text = "Kamu memandang Mahkota Merah Darah yang ada di tangan Lotan. Setiap tetes Darah yang jatuh, Bisikan paus langit bintang semakin jelas terdengar."
  },
  AvgDialog_142854_Content_31 = {
    Text = "Kamu tidak perlu lagi hidup sebagai budak, burung pipit kecil."
  },
  AvgDialog_142854_Content_32 = {
    Text = "Kamu akan membangun sebuah makam megah untuk ibumu. Kamu akan menjemput saudara-saudaramu dari kandang kuda, dan tinggal bersama mereka di istana yang gemilang."
  },
  AvgDialog_142854_Content_33 = {
    Text = "Orang-orang yang pernah menghinamu, akan berlutut di hadapanmu, mencium punggung kakimu."
  },
  AvgDialog_142854_Content_34 = {
    Text = "Kekuasaan. Kekuasaan tertinggi."
  },
  AvgDialog_142854_Content_35 = {
    Text = "Nama-nama yang mengalir dalam legenda, semuanya mati demi itu… dan kini, ia ada di hadapanmu, begitu dekat."
  },
  AvgDialog_142854_Content_36 = {
    Text = "Pergilah, burung pipit kecil. Dalam hidupmu, inilah satu-satunya kesempatanmu!"
  },
  AvgDialog_142854_Content_37 = {
    Text = "Bisikan berubah menjadi gemuruh, dorongan kuat Surge di benakmu. Tenggorokanmu yang kering bergulir, tanganmu yang gemetar mengangkat Belati berhiaskan permata peninggalan Elian itu. Di bilah Belati tersebut, masih terdapat noda Darahmu sendiri."
  },
  AvgDialog_142854_Content_38 = {
    Text = "Tenggorokan yang kering bergerak, tanganmu yang gemetar mengangkat Belati berhiaskan permata yang ditinggalkan Elian. Di bilah Belati itu, masih terdapat Darah milikmu sendiri."
  },
  AvgDialog_142854_Content_39 = {
    Text = "Kamu sudah sampai di sini, mengapa tidak bisa melangkah satu langkah lagi? Itu milikmu… Mahkota memang milikmu…"
  },
  AvgDialog_142854_Content_4 = {
    Text = "Kamu bangkit dari debu yang berserakan di lantai, mengibaskan kerikil dari tubuhmu, dan menghabiskan beberapa detik untuk mengingat di mana kamu berada sekarang."
  },
  AvgDialog_142854_Content_40 = {
    Text = "<Red:Bunuh Dia?… Bunuh Dia… Bunuh Dia… Bunuh Dia!!!>"
  },
  AvgDialog_142854_Content_41 = {
    Text = "Tiga langkah. Jarakmu dari kemuliaan tertinggi itu, hanya tiga langkah…"
  },
  AvgDialog_142854_Content_42 = {
    Text = "<ShakeRed:(Aku harus… membunuh Dia…!)>"
  },
  AvgDialog_142854_Content_43 = {
    Text = "Saat kamu mengumpulkan keberanian untuk melangkah pertama kali, Lotan berbalik. Sepasang Mata yang lelah itu, dengan tenang memandang ke arahmu."
  },
  AvgDialog_142854_Content_44 = {
    Text = "Pada sedetik saat ditatap oleh Tatapan itu, semua Bisikan yang menopangmu seketika lenyap, dan Darahmu yang mendidih seketika mendingin."
  },
  AvgDialog_142854_Content_45 = {
    Text = "<Shake:Lo… Lotan… maafkan aku…>"
  },
  AvgDialog_142854_Content_46 = {
    Text = "<Shake:Aku… aku…>"
  },
  AvgDialog_142854_Content_47 = {
    Text = "Tidak ada sedikit pun niat membunuh di Mata Lotan. Memandang sepasang Mata itu, kamu tiba-tiba mengerti, jika bukan demi bertemu paus langit bintang, tidak ada satu pun orang di sini yang layak baginya untuk bertindak."
  },
  AvgDialog_142854_Content_48 = {
    Text = "Itu adalah tatapan seseorang yang sedang memandang ke bawah, menyaksikan semut-semut bertarung demi sepotong gula. Selain itu, tidak ada emosi lain sama sekali."
  },
  AvgDialog_142854_Content_49 = {
    Text = "Kisah para semut, tidak pernah berubah. Dia mengangkat tangan yang telah menjadi tulang belulang itu, dan dengan sembarangan meletakkan sesuatu yang ada di tangannya di atas kepalamu."
  },
  AvgDialog_142854_Content_5 = {
    Text = "Dinding Batu Koloseum hancur berkeping-keping seperti kertas, bongkahan Batu raksasa berjatuhan dari tribun penonton, dan sisa-sisa bayangan para Penonton Fatamorgana telah lama menghilang."
  },
  AvgDialog_142854_Content_50 = {
    Text = "(!!! Ini adalah...)"
  },
  AvgDialog_142854_Content_51 = {
    Text = "Noda Darah yang hangat dan kotor menetes dari puncak kepalamu. Kamu mengulurkan tangan, di atas kepalamu sendiri, kamu meraba Mahkota yang terbentuk dari Darah itu, dingin dan lengket."
  },
  AvgDialog_142854_Content_52 = {
    Text = "Tak terhitung pahlawan yang membunuh demi itu, tak terhitung kemanusiaan yang jatuh demi itu. Kekuasaan dan kekayaan enam negeri, kemuliaan dan kehormatan tertinggi, kini dengan ringannya bertengger di atas kepalamu."
  },
  AvgDialog_142854_Content_53 = {
    Text = "Sang pemenang akhir melemparkannya begitu saja kepadamu, seperti menjejalkan sepotong gula ke dalam mulut anak yang penuh Keserakahan — kini, kamu memiliki segalanya."
  },
  AvgDialog_142854_Content_54 = {
    Text = "Tuan Lotan… Kamu… Kamu…"
  },
  AvgDialog_142854_Content_55 = {
    Text = "Tolong aku satu hal."
  },
  AvgDialog_142854_Content_56 = {
    Text = "Aku akan pergi mencari lawan baru. Sebelum itu, aku butuh sepasang pedang baru."
  },
  AvgDialog_142854_Content_57 = {
    Text = "Lotan memandang sepasang pedang besar yang telah menemaninya selama bertahun-tahun, lalu memasukkan sisa-sisa yang hancur itu ke dalam sarungnya."
  },
  AvgDialog_142854_Content_58 = {
    Text = "Dia berbalik, menyeret tubuhnya yang hancur, melangkah maju dengan lelah dan perlahan, menuju tujuan akhir yang tak mampu kamu pahami."
  },
  AvgDialog_142854_Content_59 = {
    Text = "Di dalam celah di belakangmu, rune-rune kuno padam satu per satu, dan sang dewa yang sedang hancur dan membusuk itu menampakkan senyum lega yang belum pernah kamu lihat sebelumnya."
  },
  AvgDialog_142854_Content_6 = {
    Text = "Kamu tiarap di lantai yang dipenuhi puing-puing, telingamu berdengung tanpa henti. Fissura Dimensi itu melayang di tengah Koloseum, tepinya bergetar hebat, seperti sebuah Luka yang menyeringai."
  },
  AvgDialog_142854_Content_60 = {
    Text = "Untukku… Catatan namanya."
  },
  AvgDialog_142854_Content_61 = {
    Text = "Darah menetes dari kepala dan Wajahmu, genangan Darah di bawahmu memantulkan Mata kosong dan kebingunganmu."
  },
  AvgDialog_142854_Content_62 = {
    Text = "Mahkota di atas kepala terasa berat, sangat berat. Beban hasrat dua belas ribu tahun membuatmu berlutut di tengah genangan Darah, menatap sosok yang semakin menjauh itu, tak mampu bangkit untuk waktu yang lama."
  },
  AvgDialog_142854_Content_63 = {
    Text = "Mahkota di atas kepala terasa sangat ringan, sangat ringan, seolah tidak pernah ada."
  },
  AvgDialog_142854_Content_7 = {
    Text = "Sebuah ratapan rendah dan panjang terdengar dari dalam Luka itu, menembus tengkorakmu langsung ke kedalaman pikiranmu, seberat desahan sebuah planet."
  },
  AvgDialog_142854_Content_8 = {
    Text = "Suara itu… apakah itu Paus Bintang?!"
  },
  AvgDialog_142854_Content_9 = {
    Text = "Bau amis Darah yang kuat dan menjijikkan memancar dari celah itu. Saat kamu bersiap untuk perlahan mendekatinya, sepasang kaki yang hanya tersisa tulang belulang melangkah keluar dari celah tersebut."
  },
  AvgDialog_142888_Content_1 = {Text = "Kebohongan"},
  AvgDialog_142888_Content_10 = {
    Text = "Kamu tidak bisa menjawab, ingatanmu sekarang kacau seperti seekor anjing berbulu panjang yang berguling tiga kali di lumpur."
  },
  AvgDialog_142888_Content_100 = {
    Text = "Mengalir melewati dada, melewati daun telinga, melewati……"
  },
  AvgDialog_142888_Content_101 = {Text = "Tuan!"},
  AvgDialog_142888_Content_102 = {
    Text = "Kamu tersadar tiba-tiba, di kejauhan, Augir, Rotan, dan Ramona yang telah selesai berlatih berjalan ke arahmu, boneka duplikat Dor sedang menganalisis data latihan mereka."
  },
  AvgDialog_142888_Content_103 = {
    Text = "Orang di sisinya menghela napas dengan sangat menyesal."
  },
  AvgDialog_142888_Content_104 = {
    Text = "Jangan khawatir, aku akan selalu menyimpan pilihan ini untukmu."
  },
  AvgDialog_142888_Content_105 = {
    Text = "Di sisimu sudah tak ada siapa pun, garis cakrawala di mana matahari terbenam membiaskan sedikit kilau mutiara lembut yang memesona."
  },
  AvgDialog_142888_Content_106 = {Text = "Ah……"},
  AvgDialog_142888_Content_107 = {
    Text = "Kamu masih banyak ingin dikatakan. Tentang bencana yang tidak ditargetkan pada siapa pun itu, yang hanya dipicu oleh N yang iseng memperdaya para pengikut."
  },
  AvgDialog_142888_Content_108 = {
    Text = "Tentang peran Gereja Lentera dalam memperburuk keadaan, tentang berbagai aksi balas dendam gila yang dilakukan Pontos selama ratusan tahun setelahnya."
  },
  AvgDialog_142888_Content_109 = {
    Text = "Tentang……apakah ada satu momen di mana ia juga pernah terguncang oleh kemungkinan lain, sehingga membiarkan waktu meninggalkan jejaknya pada dirinya."
  },
  AvgDialog_142888_Content_11 = {
    Text = "Leisa yang juga hampir kehabisan tenaga akibat pertempuran sebelumnya, berusaha keras bangkit, menghalangi antara kamu dan Pontos."
  },
  AvgDialog_142888_Content_110 = {
    Text = "Tentang Yager dan Leisa, apakah mereka masih berpesta pora di Epoyanis sekarang."
  },
  AvgDialog_142888_Content_111 = {
    Text = "……Pada akhirnya kamu hanya ingin berdoa agar ia tidak membuat masalah dengan Profesor Dexter di sekolah."
  },
  AvgDialog_142888_Content_112 = {
    Text = "Kamu menggelengkan kepala, tanpa ragu berjalan menuju sisi teman-temanmu."
  },
  AvgDialog_142888_Content_12 = {
    Text = "Pontos, sudah berakhir."
  },
  AvgDialog_142888_Content_13 = {
    Text = "Orang-orang yang masih hidup, jika tetap tinggal di Epoyanis, harus membayar dengan melupakan kenangan di luar Epoyanis."
  },
  AvgDialog_142888_Content_14 = {
    Text = "Sedangkan orang seperti aku yang sudah mati dan dibentuk ulang menjadi Nightmare, pada akhirnya semua kenangan akan perlahan-lahan terkikis oleh Corrosion."
  },
  AvgDialog_142888_Content_15 = {
    Text = "Yager telah membuat pilihannya, dan aku pun telah membuat pilihanku…\nMari kita pergi."
  },
  AvgDialog_142888_Content_16 = {
    Text = "Bibir Pontos mengatup menjadi garis dingin yang kaku, rahangnya menegang."
  },
  AvgDialog_142888_Content_17 = {
    Text = "Kamu seharusnya masih ingat, kamu ada karena bergantung pada Epoyanis. Meninggalkan Epoyanis, kamu akan mati."
  },
  AvgDialog_142888_Content_18 = {
    Text = "Ya, tapi kenangan masa laluku juga akan kembali. Aku akan mati sebagai manusia, ini adalah satu-satunya cara."
  },
  AvgDialog_142888_Content_19 = {
    Text = "Aku sudah…… tidak ingat lagi wajah kalian berdua dan Jaeger saat masih kecil, setidaknya, sebelum aku benar-benar melupakan kalian."
  },
  AvgDialog_142888_Content_2 = {
    Text = "Intimidasi yang mencekik surut bagaikan air pasang, otakmu terasa nyeri hebat, pandanganmu berulang kali memutih."
  },
  AvgDialog_142888_Content_20 = {
    Text = "Pontos terpaku di tempat, untuk pertama kalinya, kamu melihat Ekspresi kesedihan yang begitu dalam muncul di Wajahnya."
  },
  AvgDialog_142888_Content_21 = {
    Text = "……Aku sungguh berharap aku bisa mengatakan bahwa Kekuatan itu masih mengendalikanku."
  },
  AvgDialog_142888_Content_22 = {
    Text = "Ia memejamkan Mata, seolah ingin bersembunyi dari hal-hal yang tidak ingin ia hadapi. Akhirnya, ia memunculkan senyum mengejek diri sendiri yang lesu."
  },
  AvgDialog_142888_Content_23 = {
    Text = "Dengan begitu aku bisa dengan leluasa melanggar kehendak kalian, dan berbuat jahat kepada kalian."
  },
  AvgDialog_142888_Content_25 = {
    Text = "Pontos berkompromi dalam Keheningan, kereta perang yang membawanya membalas dendam kepada musuh, kini juga mengantar kepergian Leisa."
  },
  AvgDialog_142888_Content_26 = {
    Text = "Saat badan kendaraan yang memancarkan kilauan mutiara tak terkatakan itu meluncur memasuki langit di luar Epoyanis, senyum lega muncul di Wajah Leisa, ia menoleh memandang kalian——"
  },
  AvgDialog_142888_Content_27 = {
    Text = "Lalu, lenyap sepenuhnya dalam angin laut malam hari."
  },
  AvgDialog_142888_Content_28 = {
    Text = "Kalian tidak ada yang membuka mulut, hanya menatap lama ke arah Void itu, hingga Pontos memecah keheningan tersebut."
  },
  AvgDialog_142888_Content_29 = {
    Text = "Bagaimana kehidupanmu setelah meninggalkan Epoyanis, kehidupan \"Kamu\", seperti apa?"
  },
  AvgDialog_142888_Content_3 = {
    Text = "Aduh, sakit sekali!"
  },
  AvgDialog_142888_Content_30 = {
    Text = "Kamu tidak menyangka kalimat pertamanya akan seperti ini, terdiam sejenak, baru kemudian mulai merapikan kenangan-kenangan yang kacau itu."
  },
  AvgDialog_142888_Content_31 = {
    Text = "Domain kali ini sepertinya mengalami beberapa masalah, baik Catatan Yager maupun %player% tidak terlalu lengkap."
  },
  AvgDialog_142888_Content_32 = {
    Text = "……Aku tidak ingat dengan jelas, di kepalaku sekarang ada ingatan sebagai Jaeger, juga ingatan sebagai orang lain di tempat yang jauh, semua ingatan itu sangat kacau."
  },
  AvgDialog_142888_Content_33 = {
    Text = "Secara refleks kamu memasukkan tangan ke dalam saku, untuk meraba belalang kecil itu."
  },
  AvgDialog_142888_Content_34 = {
    Text = "Namun, meskipun sangat biasa, sangat sederhana, sibuk setiap hari, hari demi hari, tetapi juga sangat bahagia."
  },
  AvgDialog_142888_Content_35 = {
    Text = "Cukup bahagia untuk membuatku menjadi diriku sendiri, cukup untuk membuatku ingin kembali bagaimanapun caranya."
  },
  AvgDialog_142888_Content_36 = {
    Text = "Dia dengan tenang menatap Matamu, Seolah-olah, seperti… cara Leisa memandangmu."
  },
  AvgDialog_142888_Content_37 = {
    Text = "<Red:Dia tidak hanya sedang memandang Yager.>"
  },
  AvgDialog_142888_Content_38 = {
    Text = "Kalian salah sangka, Yager… <Red:%player%>."
  },
  AvgDialog_142888_Content_39 = {
    Text = "！！！¿¿¿???"
  },
  AvgDialog_142888_Content_4 = {
    Text = "Pontos berdiri sendirian di tempat itu, kamu tidak dapat melihat jelas Ekspresinya."
  },
  AvgDialog_142888_Content_40 = {Text = "Apa?!"},
  AvgDialog_142888_Content_41 = {
    Text = "Kamu terkejut, mengapa Pontos bisa tahu nama <Red:\"Kamu\">, bukankah ini Hanya Saja sebuah Domain?"
  },
  AvgDialog_142888_Content_42 = {
    Text = "Dia kembali ke sikap dingin dan angkuhnya, seolah tidak ada yang lepas dari kendali, dengan tenang menampilkan senyuman."
  },
  AvgDialog_142888_Content_43 = {
    Text = "Aku tahu <Red:Kamu> selalu ada di sini, aku tahu <Red:Kamu> adalah \"dia\", sejak <Red:Kamu> kecil, aku sudah tahu <Red:Kamu> berbeda dari yang lain."
  },
  AvgDialog_142888_Content_44 = {
    Text = "Suara bising yang suram, milik air laut, kembali menenggelamkan telingamu."
  },
  AvgDialog_142888_Content_45 = {
    Text = "Kalian masih terlalu kecil, terlalu polos, salah mengira bahwa kebiasa-biasaan itu disebut kebahagiaan."
  },
  AvgDialog_142888_Content_46 = {
    Text = "Kali ini, aku tidak akan mengulangi <Red:\"kesalahan\"> menyerahkan pilihan kepada kalian sendiri."
  },
  AvgDialog_142888_Content_47 = {
    Text = "Kalian salah sangka, dia tidak berkompromi, dia tidak akan, dan sama sekali tidak berniat Lepaskan, dia hanya meletakkan umpan."
  },
  AvgDialog_142888_Content_48 = {
    Text = "Dia sudah lama Menemukan bagian lain dari \"Kamu\", dia ingin Menemukan \"Kamu\", dia tidak mengizinkan adanya kejutan apapun lagi."
  },
  AvgDialog_142888_Content_49 = {
    Text = [[
Terlalu mudah, pertempuran itu, kemenangan itu.
Itu adalah jebakan untuk memancing <Red:Kamu> keluar.]]
  },
  AvgDialog_142888_Content_5 = {
    Text = "Namun jelas, ada sesuatu yang telah meninggalkannya."
  },
  AvgDialog_142888_Content_50 = {
    Text = "Apapun harga yang harus dibayar, kepada keberadaan apapun yang harus aku bersumpah setia..."
  },
  AvgDialog_142888_Content_51 = {
    Text = "Aku akan membuat pesta pora Epoyanis berlangsung selamanya."
  },
  AvgDialog_142888_Content_52 = {
    Text = "Tidak ada yang tahu, mengapa dia tiba-tiba membiarkan penuaan terjadi pada dirinya."
  },
  AvgDialog_142888_Content_53 = {
    Text = "Seluruh Epoyanis bergoyang bersamanya, semua medium di sekitarnya dan air laut yang mengalir dari dadanya bercampur satu sama lain tanpa batas."
  },
  AvgDialog_142888_Content_54 = {
    Text = "Mungkin ada teman, mungkin ada musuh, tak terhitung lengan hitam menjulur dari dadanya, mencabik-cabik dan membelai kulitnya."
  },
  AvgDialog_142888_Content_55 = {
    Text = "Seperti ingin melarikan diri, namun juga seperti ingin bersatu dengannya selamanya."
  },
  AvgDialog_142888_Content_56 = {
    Text = "Aku berada di jalan yang sudah tidak mungkin untuk kembali, dan aku pun tidak perlu kembali."
  },
  AvgDialog_142888_Content_57 = {
    Text = "Waktu-waktu yang belum pernah dialami sama sekali tidak penting, di Epoyanis, semuanya terkendali, jinak, tidak akan menimbulkan Kerusakan."
  },
  AvgDialog_142888_Content_58 = {
    Text = "Sungguh sayang, untuk saat ini aku belum bisa menahanmu, waktu kita sudah habis, <Red:%player%>."
  },
  AvgDialog_142888_Content_59 = {Text = "!!!"},
  AvgDialog_142888_Content_6 = {
    Text = "Beri aku satu alasan."
  },
  AvgDialog_142888_Content_60 = {
    Text = [[
Rasa tak berbobot menarikmu keluar dari ruang yang tercabik-cabik, terlempar tinggi ke atas.
Nightmare yang menutupi langit membentangkan sayap membrannya, berhamburan menerjangmu.]]
  },
  AvgDialog_142888_Content_61 = {
    Text = "Tenang saja, kita akan segera bertemu lagi."
  },
  AvgDialog_142888_Content_62 = {
    Text = "Aku dan Epoyanis, akan selamanya Menunggu Kepulanganmu."
  },
  AvgDialog_142888_Content_63 = {
    Text = "Jejak waktu menggerayangi tubuh Pontos bagai pelapukan."
  },
  AvgDialog_142888_Content_64 = {
    Text = "Ia tertawa terbahak-bahak, di Epoyanis yang semakin menjauh darimu, mengangkat gelasnya untukmu."
  },
  AvgDialog_142888_Content_65 = {
    Text = "Sekilas pandang terakhir sebelum tenggelam dalam kegelapan, kamu melihat dua sosok yang berdiri di sisinya."
  },
  AvgDialog_142888_Content_66 = {
    Text = "Ia tidak melepaskan siapa pun, ia menahan semua orang."
  },
  AvgDialog_142888_Content_67 = {
    Text = "<Red:Itu adalah Leisa, dan Yager yang masih muda.>"
  },
  AvgDialog_142888_Content_69 = {
    Text = "Eh?! Lalu bagaimana, lalu bagaimana? Penjaga tidak sampai jatuh dan mati kan! Paman Pontos jahat sekali!"
  },
  AvgDialog_142888_Content_7 = {
    Text = "Suaranya serak, namun tubuhnya tetap tegang, seperti seekor binatang yang terdesak ke ujung jalan."
  },
  AvgDialog_142888_Content_70 = {
    Text = "Iya kan, Pontos jahat sekali!"
  },
  AvgDialog_142888_Content_71 = {
    Text = "Iya kan, Pontos jahat sekali!"
  },
  AvgDialog_142888_Content_72 = {
    Text = "Kamu sedang dengan bersemangat berbisik-bisik kepada Aurita tentang pengalamanmu di dalam Mimpi, lalu menoleh..."
  },
  AvgDialog_142888_Content_73 = {
    Text = "Dan terkejut melihat seseorang yang dengan antusias bersandar di pintu dengan tangan di saku, entah sudah mendengarkan sejak kapan."
  },
  AvgDialog_142888_Content_74 = {
    Text = "Kemudian dalam cerita, Yager kecil berhasil pergi, Buka mata dari dalam Mimpi."
  },
  AvgDialog_142888_Content_75 = {
    Text = "Ia Menemukan dirinya sedang berbaring di tempat tidur di Rumahnya, orang-orang yang dicintainya mengelilinginya."
  },
  AvgDialog_142888_Content_76 = {
    Text = "Tokoh utama lain dalam cerita itu bersandar di dinding kamar tidur Aurita, dengan suara rendah dan tenang melengkapi akhir cerita."
  },
  AvgDialog_142888_Content_77 = {
    Text = "Dia mengingat semua kenangan seumur hidupnya, menutup kedua matanya dengan damai, dan pergi ke tempat yang bahagia."
  },
  AvgDialog_142888_Content_78 = {
    Text = "Aurita mengeluarkan hembusan napas kecil yang puas dari hidungnya, perlahan-lahan tertidur dalam keadaan setengah sadar, persis seperti Vera dalam ingatanmu."
  },
  AvgDialog_142888_Content_79 = {
    Text = "Pontos membuat gestur simbolis mengundang ke arah luar pintu."
  },
  AvgDialog_142888_Content_8 = {
    Text = "Mengapa, mengapa kamu juga harus pergi, mengapa lebih memilih menuju kematian, daripada—"
  },
  AvgDialog_142888_Content_80 = {
    Text = "Kurasa, kamu pasti ingin berbicara denganku?"
  },
  AvgDialog_142888_Content_82 = {
    Text = "Reuni setelah perpisahan panjang, sungguh ungkapan yang indah."
  },
  AvgDialog_142888_Content_83 = {
    Text = "Kamu tidak memberitahu Aurita akhir yang sebenarnya, kamu berbohong, bukan?"
  },
  AvgDialog_142888_Content_84 = {
    Text = "Kamu melepaskan Leisa adalah sebuah kebohongan, yang meninggalkan Epoyanis hanya aku, bukan Yager."
  },
  AvgDialog_142888_Content_85 = {
    Text = "Diinterupsi secara langsung, Pontos tidak marah, ia malah menyeringai dan mengangkat alisnya."
  },
  AvgDialog_142888_Content_86 = {
    Text = "Tentu saja, sudah jelas. Ada beberapa cerita yang tidak cocok diceritakan kepada anak-anak, bukan begitu?"
  },
  AvgDialog_142888_Content_87 = {
    Text = "Penampilanmu sekarang… juga hanya untuk memberitahu semua orang bahwa penuaan yang kamu lewatkan bukanlah hal yang istimewa."
  },
  AvgDialog_142888_Content_88 = {
    Text = "Karena kamu bisa mengendalikan segalanya, termasuk waktu, termasuk penuaan, termasuk kehidupan orang lain, bukan?"
  },
  AvgDialog_142888_Content_89 = {
    Text = "Mungkin karena nada provokatif dalam kata-katamu terlalu jelas, Pontos tidak menjawab secara langsung, Hanya Saja tertawa dengan cara yang membuatmu sangat kesal."
  },
  AvgDialog_142888_Content_9 = {
    Text = "Bukan \"Saya\"."
  },
  AvgDialog_142888_Content_90 = {
    Text = "Siapa yang tahu, mungkin aku Hanya ingin mencoba hal-hal baru."
  },
  AvgDialog_142888_Content_91 = {
    Text = "Bagaimanapun, senang sekali kamu mengingatnya, sejak pertama kali aku datang ke Mythag, aku selalu Menunggu hari ini."
  },
  AvgDialog_142888_Content_92 = {
    Text = "Segala sesuatu di Epoyanis masih Menunggu kamu, %player%."
  },
  AvgDialog_142888_Content_93 = {
    Text = "……Jika kamu perlu pengingat, Mythag memiliki sistem keamanan yang lengkap."
  },
  AvgDialog_142888_Content_94 = {
    Text = "Tidak perlu setegang itu."
  },
  AvgDialog_142888_Content_95 = {
    Text = "Ngomong-ngomong, aku sangat penasaran. Kamu yang bukan lagi Yager, anak kecil dari Mythag, apakah kamu sudah menemukan jawabannya?"
  },
  AvgDialog_142888_Content_96 = {
    Text = "Pontos sedikit memiringkan kepalanya, kamu menatap mata biru tua miliknya."
  },
  AvgDialog_142888_Content_97 = {
    Text = "Jika aku memberimu satu kesempatan lagi untuk memilih, apakah kamu akan memilih keabadian dengan masa muda yang kekal, atau kenangan yang tercipta sepanjang hidupmu?"
  },
  AvgDialog_142888_Content_98 = {
    Text = "Suara air laut, suara kepakan sayap."
  },
  AvgDialog_142888_Content_99 = {
    Text = "White noise yang akrab namun terasa jauh itu sekali lagi perlahan meresap ke seluruh tubuh."
  },
  AvgDialog_142889_Content_1 = {
    Text = "Hal Terbaik di Dunia"
  },
  AvgDialog_142889_Content_10 = {
    Text = "Kalau sudah besar nanti kamu akan mengerti, kita pasti akan bertemu lagi. Saat kita berpisah, aku akan selalu merindukanmu."
  },
  AvgDialog_142889_Content_100 = {
    Text = "Dia menghela napas, menampilkan senyum yang sudah semestinya, lalu bersama suara lain mengucapkan bagian akhir kalimat itu."
  },
  AvgDialog_142889_Content_101 = {
    Text = "Apa yang kau bicarakan, ini adalah Epoyanth, di sini tidak ada penuaan, kita akan berpesta selamanya, selamanya muda."
  },
  AvgDialog_142889_Content_102 = {
    Text = "Sosok yang melangkah keluar dari balik Olney bersuara serak rendah, bagaikan seorang tetua yang paling bijaksana dan berwibawa."
  },
  AvgDialog_142889_Content_103 = {
    Text = "Itu bukan suara Pontos."
  },
  AvgDialog_142889_Content_104 = {
    Text = "Kekunoan-Nya menyapu bersih semua rasa keakraban yang pernah ada, hanya menyisakan laut di <Red:kedalaman terdalam>, Echo air laut mencuci kesadaranmu sekali lagi."
  },
  AvgDialog_142889_Content_105 = {
    Text = "Ya, ya, ini adalah Epoyanth, aku sudah kembali ke Epoyanth."
  },
  AvgDialog_142889_Content_106 = {
    Text = "<Shake:<Red:Kita akan berpesta selamanya.>>"
  },
  AvgDialog_142889_Content_107 = {
    Text = "<Red:Kita akan selamanya muda.>"
  },
  AvgDialog_142889_Content_108 = {
    Text = "Kau begitu bahagia, begitu ringan, kau berada di Epoyanth."
  },
  AvgDialog_142889_Content_109 = {
    Text = "Selain itu, semua pikiran yang tidak penting pun lenyap."
  },
  AvgDialog_142889_Content_11 = {
    Text = "<Red:Plak——>"
  },
  AvgDialog_142889_Content_110 = {
    Text = "Namun, entah mengapa, kau tidak membiarkan siapa pun melihat belalang yang namanya sudah kau lupakan itu."
  },
  AvgDialog_142889_Content_12 = {
    Text = "Tepat di saat kompas itu baru saja meninggalkan tanganmu, terdengar suara gemerisik yang rapat dari luar jendela."
  },
  AvgDialog_142889_Content_13 = {
    Text = "Disusul kemudian, sebuah tawa kecil."
  },
  AvgDialog_142889_Content_14 = {
    Text = "Coba kulihat siapa jagoan tampan ini——"
  },
  AvgDialog_142889_Content_15 = {
    Text = "Seiring dengan kekuatan tak kasat mata yang maha dahsyat, daun jendela terbuka lebar. Dalam kegelapan yang pekat dan riuh, cahaya bulan perak berkilau menembus celah-celahnya."
  },
  AvgDialog_142889_Content_16 = {
    Text = "Halo, Yager."
  },
  AvgDialog_142889_Content_17 = {
    Text = "Banyak sekali… banyak sekali sayap, Kakek!!"
  },
  AvgDialog_142889_Content_18 = {
    Text = "Sayap-sayap membran hitam raksasa yang tak terhitung jumlahnya, menutupi langit, menerjang ke arahmu. Pupil matamu bergetar menatap pusat kegelapan itu, tak mampu bergerak."
  },
  AvgDialog_142889_Content_19 = {
    Text = "<Red:Paman Pontos...>"
  },
  AvgDialog_142889_Content_2 = {
    Text = "Kenangan itu berakhir, kamu terdiam cukup lama."
  },
  AvgDialog_142889_Content_20 = {
    Text = "Cuit… gucuit… <LightGray:*suara tekanan yang basah dan licin>"
  },
  AvgDialog_142889_Content_21 = {
    Text = [[
Tangan mungil Viera mencengkeram erat tanganmu, namun pada akhirnya hanya meninggalkan bekas cakaran yang dalam.
Membungkus, menyesakkan, menelan.]]
  },
  AvgDialog_142889_Content_22 = {
    Text = "Sunyi, tenang, familiar, menyenangkan..."
  },
  AvgDialog_142889_Content_23 = {
    Text = "White noise seperti lautan menenggelamkan telingamu, kau terus turun, turun——"
  },
  AvgDialog_142889_Content_24 = {
    Text = "<Red:Jatuh.>"
  },
  AvgDialog_142889_Content_26 = {
    Text = "Jaeger, bangun, jangan tidur lagi."
  },
  AvgDialog_142889_Content_27 = {
    Text = "Pesta hari ini akan segera dimulai, semua orang menunggumu."
  },
  AvgDialog_142889_Content_28 = {
    Text = "White noise yang tajam membuat gendang telingamu terasa sakit luar biasa, secara refleks kau terlonjak bangun dari tempat tidur."
  },
  AvgDialog_142889_Content_29 = {
    Text = "Sudah kubilang dia akan segera pulih, Jaeger-ku memang anak yang luar biasa."
  },
  AvgDialog_142889_Content_3 = {
    Text = "Anggap saja ini sebagai keegoisanku sebagai orang tua, pikirmu, karena mungkin kamu adalah orang terakhir yang masih mengingat Mereka, dan kamu tidak ingin Mereka terlupakan."
  },
  AvgDialog_142889_Content_30 = {
    Text = "Pontos tertawa sambil menyenggol Leisa dengan sikunya. Olney, Paman White, dan banyak wajah-wajah familiar berkerumun di depan tempat tidurmu."
  },
  AvgDialog_142889_Content_31 = {
    Text = "Kesadaranmu seperti tenggelam dalam air yang dalam. Kau merasa ada sesuatu yang terlupakan, dan kelincahan tubuhmu juga terasa sedikit janggal."
  },
  AvgDialog_142889_Content_32 = {
    Text = "Paman Pontos, Mama? Apa yang terjadi, kenapa semua orang ada di sini?"
  },
  AvgDialog_142889_Content_33 = {
    Text = "Oh, kamu pergi jauh, anak kecil. Aku menghabiskan waktu yang sangat, sangat lama untuk mencarimu."
  },
  AvgDialog_142889_Content_34 = {
    Text = "Sekarang, aku membawamu pulang ke Rumah."
  },
  AvgDialog_142889_Content_35 = {
    Text = "Matahari senja menembus awan, memotong permukaan laut menjadi kilauan berkilauan, seperti serpihan emas yang terpantul di kaca jendela. Kau telah kembali ke penginapan tepi laut tempat kau dibesarkan."
  },
  AvgDialog_142889_Content_36 = {
    Text = "Ah, benar. Ini adalah……@4"
  },
  AvgDialog_142889_Content_37 = {Text = "??!!!"},
  AvgDialog_142889_Content_39 = {
    Text = "Rasa nyeri berdenyut, desakan, nama kota itu tersangkut di ujung bibir."
  },
  AvgDialog_142889_Content_4 = {
    Text = "Kamu menatap Vera dengan lembut, para kerabat dengan penuh perhatian memberikan kalian ruang untuk berdua agar kamu tidak terlalu kelelahan."
  },
  AvgDialog_142889_Content_40 = {
    Text = "Suara melengking seperti besi menggesek kaca menghantam tenggorokanmu dari dalam tengkorak, otakmu seketika berubah menjadi bubur kental."
  },
  AvgDialog_142889_Content_41 = {
    Text = "Hingga telapak tangan yang hangat dan kasar itu menangkup bagian belakang kepalamu, mengetukkan dahinya ke dahimu sambil tersenyum seperti biasa."
  },
  AvgDialog_142889_Content_42 = {
    Text = "Hei, bangun, ada apa?"
  },
  AvgDialog_142889_Content_43 = {
    Text = "Kau perlahan membuka mulut, mencoba menemukan kembali suaramu."
  },
  AvgDialog_142889_Content_44 = {
    Text = "Pontos menatapmu dengan seksama, kau tidak mengerti, tatapannya padamu seperti menatap sesuatu yang telah hilang dan kini kembali."
  },
  AvgDialog_142889_Content_45 = {
    Text = "Seperti menatap harta paling berharga."
  },
  AvgDialog_142889_Content_46 = {
    Text = "Selamat datang kembali di Öboyangs, Jaeger."
  },
  AvgDialog_142889_Content_47 = {
    Text = "Memandang semua yang familiar di sekitar, sinar matahari menghangatkan lantai hingga butiran garam mengkristal."
  },
  AvgDialog_142889_Content_48 = {
    Text = "Ketenangan yang aneh dan penuh kegembiraan menyelimuti segalanya, senyum pun perlahan terbentuk di wajahmu."
  },
  AvgDialog_142889_Content_49 = {
    Text = "Aku ingat sekarang, Öboyangs, ini adalah Öboyangs, tempat aku dibesarkan……"
  },
  AvgDialog_142889_Content_5 = {
    Text = "Aku tidak pernah lagi bertemu Mama dan Paman Pontos. Kalau bukan karena kompas ini, mungkin aku akan menganggap semuanya hanyalah halusinasi akibat ledakan itu."
  },
  AvgDialog_142889_Content_50 = {
    Text = "Nah begitu, lama tidak bertemu!"
  },
  AvgDialog_142889_Content_51 = {
    Text = "Akhirnya kau pulang juga, Yager."
  },
  AvgDialog_142889_Content_53 = {
    Text = "Pikiranmu seolah terendam dalam lendir bernama kebahagiaan, semua orang di sekitarmu tampak semuda saat kalian berpisah dahulu..."
  },
  AvgDialog_142889_Content_54 = {
    Text = "Oh... berpisah."
  },
  AvgDialog_142889_Content_55 = {
    Text = "Kapan kau meninggalkan Epoyanis, dan bagaimana kau bisa kembali? Rasanya belum lama kau berbaring di ranjang lain. Kau punya seorang cucu perempuan, namanya..."
  },
  AvgDialog_142889_Content_56 = {
    Text = "Sedang memikirkan apa, nak?"
  },
  AvgDialog_142889_Content_57 = {
    Text = "Pontos bersandar di jendela, matahari senja telah tenggelam ke permukaan laut, sinar terakhirnya bersembunyi di balik tubuhnya."
  },
  AvgDialog_142889_Content_58 = {
    Text = "Paman Pontos, rasanya aku melupakan sesuatu yang sangat penting, apa ya..."
  },
  AvgDialog_142889_Content_59 = {
    Text = "Hahaha, kalau sementara tidak bisa mengingatnya, berarti itu tidak terlalu penting. Jangan terburu-buru, di Epoyanis, kita punya banyak waktu."
  },
  AvgDialog_142889_Content_6 = {
    Text = "Jadi, Vera, itulah mengapa aku ingin menceritakan kisah ini kepadamu."
  },
  AvgDialog_142889_Content_60 = {
    Text = "Ayo! Kamu masih muda, punya banyak waktu yang indah, tentu saja harus digunakan untuk berpesta pora."
  },
  AvgDialog_142889_Content_61 = {
    Text = "Dia merangkul bahumu, berjalan menuju aula besar di lantai bawah yang baru direnovasi, dan bersama kerumunan yang bersorak, melemparkanmu ke lantai dansa."
  },
  AvgDialog_142889_Content_62 = {
    Text = "Baru kau sadari penginapan itu telah berubah menjadi aula yang sangat megah."
  },
  AvgDialog_142889_Content_63 = {
    Text = "Wajah-wajah yang familiar tertawa di lantai dansa sambil mengangkat gelas ke arahmu, gelas kayu dan kaca beradu menimbulkan bunyi yang bersahutan."
  },
  AvgDialog_142889_Content_64 = {
    Text = "Aku masih muda, aku masih... muda?"
  },
  AvgDialog_142889_Content_65 = {
    Text = "Rasa pusing yang berat kembali menyerang, kegembiraan yang aneh itu membekukan dirimu."
  },
  AvgDialog_142889_Content_66 = {
    Text = "Kau mengangkat lengan, melihat sepasang tangan yang muda dan kuat."
  },
  AvgDialog_142889_Content_67 = {
    Text = "Di cermin di sampingmu, terpantul wajah seorang pemuda yang mengenakan senyum yang sama seperti semua orang."
  },
  AvgDialog_142889_Content_68 = {
    Text = "Teman-teman, mari kita angkat gelas, untuk Epoyanis!"
  },
  AvgDialog_142889_Content_69 = {
    Text = "Sebelum kau sempat tersadar, Pontos melewati bahumu dan mengangkat gelas ke arah kerumunan."
  },
  AvgDialog_142889_Content_7 = {
    Text = "Mereka mungkin tidak pergi selamanya, hanya saja melayang di langit malam di suatu tempat. Jika suatu hari aku menghilang, mungkin merekalah yang datang menjemputku."
  },
  AvgDialog_142889_Content_70 = {
    Text = "Untuk Epoyanis!"
  },
  AvgDialog_142889_Content_71 = {
    Text = "Dalam kegembiraan yang membingungkan dan luar biasa itu, kamu mengangkat gelas bersama orang-orang, gelombang suara menyeretmu semakin jauh ke pusat keramaian."
  },
  AvgDialog_142889_Content_72 = {
    Text = "Kalian berpesta, kalian menari, kalian minum sepuasnya."
  },
  AvgDialog_142889_Content_73 = {
    Text = "Berkas cahaya dari atap tinggi menembus kabut yang mengembun dari permukaan laut, berkelip sepanjang malam."
  },
  AvgDialog_142889_Content_74 = {
    Text = "Hingga ufuk timur mulai diwarnai semburat fajar, orang-orang satu per satu tumbang dan saling bersandar tertidur, barulah kau pun dengan sedikit mabuk bersenandung, bersandar miring ke bantalan berlapis beludru."
  },
  AvgDialog_142889_Content_76 = {
    Text = "Saat kau hampir tertidur, kau melihat wajah Leisa, kau melangkah cepat menghampirinya."
  },
  AvgDialog_142889_Content_77 = {
    Text = "Mama! Tunggu aku, kamu pergi ke mana? Aku tidak melihatmu sepanjang malam."
  },
  AvgDialog_142889_Content_78 = {
    Text = "Rasa gelisah yang tak jelas timbul di hatimu, kau tak bisa menahan diri untuk bergumam."
  },
  AvgDialog_142889_Content_79 = {
    Text = "Aneh sekali, bukankah aku hanya pergi jauh sebentar saja? Kenapa rasanya kita sudah sangat lama tidak bertemu?"
  },
  AvgDialog_142889_Content_8 = {
    Text = "Tapi... aku tidak mau berpisah dari Kakek, boleh bawa aku ikut juga?"
  },
  AvgDialog_142889_Content_80 = {
    Text = "Langkahmu terhenti mendadak, karena ekspresi yang sangat tak berdaya dan sedih di wajah Leisa."
  },
  AvgDialog_142889_Content_81 = {
    Text = "Dia menemukanmu, Jaeger-ku yang malang, seharusnya kau tidak datang ke sini."
  },
  AvgDialog_142889_Content_82 = {
    Text = "Cepat berpikirlah, selagi kau belum lupa, cepat ingat kembali, kehidupan seperti apa yang telah kau jalani."
  },
  AvgDialog_142889_Content_83 = {
    Text = "Air mata ibu jatuh di tanganmu, dinginnya membuatmu refleks menarik tangan, udara yang membeku membuat bulu kudukmu seketika berdiri di seluruh tubuh."
  },
  AvgDialog_142889_Content_84 = {
    Text = "Lihatlah orang-orang di sekitar ini, lihatlah aku, seperti apa seharusnya kita."
  },
  AvgDialog_142889_Content_85 = {
    Text = "Periksa sakumu, Yager."
  },
  AvgDialog_142889_Content_86 = {
    Text = "Kasar, tidak rapi, agak menusuk tangan — di sana ada seekor <Red:belalang>."
  },
  AvgDialog_142889_Content_87 = {
    Text = "Seekor belalang yang dibuat oleh <Red:Vera>, yang dinamai <Red:Vera>."
  },
  AvgDialog_142889_Content_88 = {
    Text = "<Shake:<Red:Vera>… tidak, aku sudah… sudah lama sekali…>"
  },
  AvgDialog_142889_Content_89 = {
    Text = "<Shake:Aku hampir mati, aku berbaring di tempat tidur, aku pernah punya teman, kekasih, anak, aku sedang…>"
  },
  AvgDialog_142889_Content_9 = {
    Text = "Kamu menahan tawa, mengeluarkan kompas yang sudah puluhan tahun tidak pernah lepas dari genggamanmu, lalu meletakkannya di telapak tangan Vera."
  },
  AvgDialog_142889_Content_90 = {
    Text = "Segala sesuatu di Sekitar berputar dalam kekacauan yang tak beraturan, dua aliran pikiran yang sangat berbeda bercampur menjadi satu."
  },
  AvgDialog_142889_Content_91 = {
    Text = "Kamu memeluk kepalamu, membungkuk kesakitan, berusaha keras Serap oksigen sebanyak-banyaknya."
  },
  AvgDialog_142889_Content_92 = {
    Text = "Ya Tuhan, Jaeger, ada apa denganmu, wajahmu pucat sekali!"
  },
  AvgDialog_142889_Content_93 = {
    Text = "Olney yang entah dari mana datangnya menabrakmu, dan suara denging di telingamu yang berdengung tiba-tiba lenyap."
  },
  AvgDialog_142889_Content_94 = {
    Text = "Kamu mengangkat kepala, sosok Leisa sudah tidak terlihat lagi."
  },
  AvgDialog_142889_Content_95 = {
    Text = "Olney, Olney, tidak, tidak, aku ingat sekarang!"
  },
  AvgDialog_142889_Content_96 = {
    Text = "Kita jelas-jelas tumbuh besar bersama, aku hadir di wisudamu, di pernikahanmu, kamu seharusnya sama seperti aku, kamu tidak seharusnya semuda ini, kita sudah sangat tua."
  },
  AvgDialog_142889_Content_97 = {
    Text = "Olney menatapmu dengan Ekspresi yang sangat asing bagimu, sangat lama, sangat lama, hingga kamu Hampir ingin Keluar."
  },
  AvgDialog_142889_Content_98 = {Text = "Lalu..."},
  AvgDialog_142889_Content_99 = {
    Text = "Ah, Jaeger……"
  },
  AvgDialog_142890_Content_1 = {
    Text = "Dia dan Dia"
  },
  AvgDialog_142890_Content_10 = {
    Text = "Terima kasih atas Hadiah-mu, Paman Pontos, tapi…"
  },
  AvgDialog_142890_Content_11 = {
    Text = "Itu pasti adalah kehidupan yang sangat panjang dan berharga, untuk itu, aku rela melepaskan masa muda dan HP yang abadi."
  },
  AvgDialog_142890_Content_12 = {
    Text = "Orang-orang berhenti berbicara. Secara serentak, semua orang menolehkan wajah mereka menatapmu."
  },
  AvgDialog_142890_Content_13 = {
    Text = "Gendang telingamu terasa nyeri seperti akan pecah, suara gemericik air laut menggali di dalam kepalamu."
  },
  AvgDialog_142890_Content_14 = {
    Text = "Menembus air laut yang berat, kamu mendengar sebuah helaan napas."
  },
  AvgDialog_142890_Content_15 = {
    Text = "<Red:Lagi-lagi begini.>"
  },
  AvgDialog_142890_Content_16 = {
    Text = "<Shake:<Red:Kiiit... muu, gukjyu, guk...>>"
  },
  AvgDialog_142890_Content_17 = {
    Text = "Keempat dinding bergetar dalam Guncangan, segalanya menetes dalam lendir yang basah."
  },
  AvgDialog_142890_Content_18 = {
    Text = "Bahkan setelah aku memisahkanmu, penuaan tetap membuatmu mengucapkan <Red:omong kosong yang lemah> ini, sama seperti Leisa."
  },
  AvgDialog_142890_Content_19 = {
    Text = "Kamu tiba-tiba merasakan bahwa dia <Red:bukan lagi> Pontos."
  },
  AvgDialog_142890_Content_2 = {
    Text = "Memandang tangan yang familiar dan hangat itu, kamu akhirnya— mundur selangkah."
  },
  AvgDialog_142890_Content_20 = {
    Text = "Kuno hingga terlupakan, Ketakutan dingin yang luas, agung, dan sulit untuk di-Tatapan membuatmu terpaku di tempat mengeluarkan <Red:jeritan> tanpa suara."
  },
  AvgDialog_142890_Content_22 = {
    Text = "Kau teringat sekarang—suara itu saat tiba di Epoyangs, saat meninggalkan Epoyangs, dan saat kembali ke Epoyangs."
  },
  AvgDialog_142890_Content_23 = {
    Text = "Kulit, tulang rusuk, terbalik keluar dan merentang, lalu…"
  },
  AvgDialog_142890_Content_24 = {
    Text = [[
Kosong melompong, tak terhitung tangan, kosong melompong, kosong melompong, kosong melompong, kosong melompong, kosong melompong, @2y@2, @4@4@2@4
@3@2@4@3@1@3@3!!!!!!]]
  },
  AvgDialog_142890_Content_25 = {
    Text = "Tetaplah di sini, tetaplah di Epoyanis."
  },
  AvgDialog_142890_Content_26 = {
    Text = "<Change>Ikuti jurang, terjun ke dalam jurang."
  },
  AvgDialog_142890_Content_27 = {Text = "Bulan."},
  AvgDialog_142890_Content_28 = {
    Text = "Bulan yang bersih bercahaya, tergantung jauh di langit yang nun jauh di sana."
  },
  AvgDialog_142890_Content_29 = {
    Text = [[
Tulang rusuknya kulitnya lengannya dadanya pelukannya
pelukannya pelukannya pelukannya pelukannya pelukannya
pelukannya pelukannya pelukannya pelukannya pelukannya
Epo@3@4ya@3@2nis
Epo@4@3@2ya@4@3@2nis
tulang rusuknya kulitnya lengannya dadanya pelukannya
selamanya selamanya selamanya selamanya selamanya selamanya selama
selamaselama selamanya selamanya selamanya selamanya selamanya selamanya <Red:Epoyanis>]]
  },
  AvgDialog_142890_Content_3 = {Text = "...Ada."},
  AvgDialog_142890_Content_30 = {
    Text = "<Red:Epoyanis yang datang ke dalam pelukannya.>"
  },
  AvgDialog_142890_Content_31 = {
    Text = "Sayap yang berlapis-lapis, membungkus di dalamnya pelukan yang erat dan kokoh, tak terbantahkan, serta penelanan."
  },
  AvgDialog_142890_Content_32 = {
    Text = "Kau didorong, kau dibungkus, kau ditampung, kau jatuh ke dalam ketenangan yang tak berujung."
  },
  AvgDialog_142890_Content_33 = {Text = "Berhenti!"},
  AvgDialog_142890_Content_34 = {
    Text = "Sebuah sosok dengan keras merobek kerumunan yang beku dan tak sadarkan diri, menerobos menuju pusaran <Red:\"Pontos\">."
  },
  AvgDialog_142890_Content_35 = {
    Text = "Tidak menimbulkan Kerusakan apa pun, namun rasa terkejut yang sangat jelas membuat pupil <Red:\"Pontos\"> bergetar, menatap tajam Wajahnya."
  },
  AvgDialog_142890_Content_36 = {
    Text = "Aku selalu mengira… aku hanya membentuk ulang sebuah Cangkang kosong."
  },
  AvgDialog_142890_Content_37 = {
    Text = "Seperti hal-hal yang terlupakan oleh Yager namun masih mempengaruhinya, sebagian dariku pun masih ada."
  },
  AvgDialog_142890_Content_38 = {
    Text = "Biarkan dia pergi, Pontos, dia bukan milik tempat ini."
  },
  AvgDialog_142890_Content_39 = {Text = "Oh, Leisa."},
  AvgDialog_142890_Content_4 = {Text = "Apa?"},
  AvgDialog_142890_Content_40 = {
    Text = "Aku mencintainya, mencintainya sepertimu."
  },
  AvgDialog_142890_Content_41 = {
    Text = "Olney, White."
  },
  AvgDialog_142890_Content_42 = {
    Text = "Semua orang-orang Epoyanis."
  },
  AvgDialog_142890_Content_43 = {
    Text = "Mereka diam membisu bersama mimpi buruk, mendekat seperti tembok yang menggilas."
  },
  AvgDialog_142890_Content_44 = {
    Text = "Tidak, tidak tidak tidak! Tidak!!"
  },
  AvgDialog_142890_Content_45 = {
    Text = "Leisa memandangmu, memandang Yager, dan juga memandang… kamu."
  },
  AvgDialog_142890_Content_46 = {
    Text = "Aku tahu mengapa kamu begitu menginginkan mereka, di sana bukan hanya ada Yager, bukan hanya satu jiwa."
  },
  AvgDialog_142890_Content_47 = {
    Text = "Ah… mereka semua akan melupakan segalanya, mereka akan tinggal di sini."
  },
  AvgDialog_142890_Content_48 = {
    Text = "Leisa kembali terjebak, ia mengerahkan seluruh tenaganya untuk memutar tubuhnya, menatap tajam Mata kamu, seolah-olah ingin melihat ke kedalaman jiwa yang paling dalam."
  },
  AvgDialog_142890_Content_49 = {
    Text = "Kumohon, siapapun kamu, aku tahu kamu ada di sana. Bawa Yager kembali, kembali ke kehidupan kalian semula!"
  },
  AvgDialog_142890_Content_5 = {
    Text = "Dia seolah tidak mengerti pertanyaanmu, mengerutkan dahi dengan tidak percaya."
  },
  AvgDialog_142890_Content_50 = {
    Text = "Selaput sayap hitam yang rapat membentang, semuanya begitu sunyi, begitu… memikat, kamu hampir melangkah menuju Mereka."
  },
  AvgDialog_142890_Content_51 = {
    Text = "Kemudian, kamu mendengar… suara <Red:Kamu>."
  },
  AvgDialog_142890_Content_52 = {
    Text = "Kurasa, <Red:「Saya」> sudah membuat pilihan."
  },
  AvgDialog_142890_Content_53 = {
    Text = "Dari kedalaman lautan kesadaran, sebuah roh berjuang untuk keluar."
  },
  AvgDialog_142890_Content_54 = {
    Text = "Selamat dari ledakan besar Akut, Kamu sebagai <Red:\"Penjaga Mythag\">, mengambil alih tubuh ini."
  },
  AvgDialog_142890_Content_55 = {
    Text = "Cahaya keperakan berkilauan di telapak tanganmu."
  },
  AvgDialog_142890_Content_56 = {
    Text = "Kenangan-kenangan yang kacau milik Yager dipungut satu per satu."
  },
  AvgDialog_142890_Content_57 = {
    Text = "Tahukah kamu, Paman Pontos, hal pertama yang aku ingat ternyata adalah sesuatu yang sangat tidak penting."
  },
  AvgDialog_142890_Content_59 = {
    Text = "\"Pontos\" tidak membuka mulut, ia menatapmu dengan Keheningan."
  },
  AvgDialog_142890_Content_6 = {
    Text = "Ada artinya, kenangan-kenangan itu."
  },
  AvgDialog_142890_Content_60 = {
    Text = "Pada usia delapan belas tahun, Olney dan \"Saya\" diam-diam menyelinap ke palka kapal terdekat, dengan muka tebal membantu para pelaut, dan mendapat satu kali perjalanan kapal pesiar gratis."
  },
  AvgDialog_142890_Content_61 = {
    Text = "Keesokan paginya, kami menyaksikan matahari terbit paling indah yang pernah kami lihat. Olney berkata, ia berharap Matahari tidak pernah terbenam, tapi aku tidak berpikir demikian."
  },
  AvgDialog_142890_Content_62 = {
    Text = "Karena Matahari akan terbenam dan hari akan berakhir, itulah mengapa hal-hal yang kami alami setiap hari menjadi sangat berharga."
  },
  AvgDialog_142890_Content_63 = {
    Text = "Jangan bicara omong kosong lagi, di Epoyanis, Asalkan kamu mau, aku bisa membuat Matahari terbit atau terbenam sesuai keinginanmu."
  },
  AvgDialog_142890_Content_64 = {
    Text = "Ia menutup Mata dengan lelah, akhirnya kehilangan kesabaran, kamu dengan Teguh menggelengkan kepala."
  },
  AvgDialog_142890_Content_65 = {
    Text = "Yang penting adalah waktu yang kita jalani bersama, bukan Matahari yang selamanya tergantung tinggi."
  },
  AvgDialog_142890_Content_66 = {
    Text = "Maaf, Pontos."
  },
  AvgDialog_142890_Content_67 = {
    Text = "Ia mengangkat tangannya, dan dinding mimpi buruk itu kembali menekanmu."
  },
  AvgDialog_142890_Content_68 = {
    Text = "Pergilah, para hamba."
  },
  AvgDialog_142890_Content_7 = {
    Text = "Bukan untuk orang lain, melainkan untuk diriku sendiri."
  },
  AvgDialog_142890_Content_8 = {
    Text = "Aku ingin tahu bagaimana aku menjalani hidupku, setelah kehilangan ingatan, mengapa kebahagiaan apapun membuatku merasa ada yang kurang."
  },
  AvgDialog_142890_Content_9 = {
    Text = "Duri belalang itu sedikit menusuk ujung jarimu, entah mengapa kamu teringat bayangan anak yang menangis di sisi tempat tidur itu."
  },
  AvgDialog_142891_Content_1 = {
    Text = "Rahasia Keluarga"
  },
  AvgDialog_142891_Content_10 = {
    Text = "Namanya — um, namanya Vera, karena Vera adalah nama yang diberikan kakek, nama yang paling indah."
  },
  AvgDialog_142891_Content_100 = {
    Text = "Murka-Nya akan membakar kalian, hanya Kesukacitaan yang bisa… @1!"
  },
  AvgDialog_142891_Content_101 = {Text = "Pfft."},
  AvgDialog_142891_Content_102 = {
    Text = "Darah terciprat, kamu terpana melihat Leisa dan beberapa tamu tetap penginapan di kejauhan, menggerakkan makhluk yang sama seperti yang kalian tunggangi untuk bertempur."
  },
  AvgDialog_142891_Content_103 = {
    Text = "Kenapa makhluk-makhluk terkutuk ini bisa sampai ke sini…\nSudahlah, ini seharusnya yang terakhir."
  },
  AvgDialog_142891_Content_104 = {
    Text = "Semoga mereka hanya kebetulan lewat…"
  },
  AvgDialog_142891_Content_105 = {
    Text = "Leisa dan para temannya telah pergi, kamu dan Pontos berdiri di tempat yang gelap, dia menopang bahumu dari belakang sehingga kamu tidak langsung jatuh tersungkur ke tanah."
  },
  AvgDialog_142891_Content_106 = {
    Text = "Kamu menggenggam erat ujung bajunya, suaranya tenang dan lembut, seolah-olah berusaha keras untuk tidak membuatmu semakin terkejut."
  },
  AvgDialog_142891_Content_107 = {
    Text = "Yager, seperti yang kamu lihat sendiri… makhluk ini disebut Nightmare, kami menggerakkan mereka untuk bertempur bagi kami."
  },
  AvgDialog_142891_Content_108 = {
    Text = "Dia berhenti sejenak, meletakkan tangan di sisi tubuh \"Nightmare\" itu, mengeretakkan buku-buku jarinya, seolah-olah sedang berpikir bagaimana cara menjelaskannya,"
  },
  AvgDialog_142891_Content_109 = {
    Text = "Kami adalah tokoh utama dalam kisah petualangan para pemberani, maksudku, seperti mereka yang menunggangi naga — hanya saja kami adalah keluarga yang menunggangi Nightmare."
  },
  AvgDialog_142891_Content_11 = {
    Text = "Vera… Kakek perlu istirahat, ke sini saja sama ayah."
  },
  AvgDialog_142891_Content_110 = {
    Text = "A… apa?! Apa yang kamu bicarakan, Paman Pontos?! Keluarga kita jelas-jelas hanya mengelola sebuah penginapan."
  },
  AvgDialog_142891_Content_111 = {
    Text = "Setelah… sebuah kecelakaan, hanya sebagian kecil dari kelompok ini yang tersisa, Leisa telah berbuat banyak untuk kelompok ini, dan semua orang sangat bergantung padanya."
  },
  AvgDialog_142891_Content_112 = {
    Text = "Tapi dia tidak ingin kita, terutama kamu, terlibat dengan semua ini, dan kehidupan yang tenang tanpa nama besar itulah yang ingin dia berikan kepada kita."
  },
  AvgDialog_142891_Content_113 = {
    Text = "Namun di dunia ini masih banyak hal-hal jahat dan buruk yang ada, seperti yang kamu lihat hari ini, aku tidak mengerti…"
  },
  AvgDialog_142891_Content_114 = {
    Text = "Pontos menampilkan Ekspresi yang agak kesal, sesuatu yang jarang terlihat darinya, lalu dengan santai menyisir rambut pirang yang jatuh di dahinya ke belakang."
  },
  AvgDialog_142891_Content_115 = {
    Text = "Belakangan ini, \"Nightmare\" menemukanku, dan aku bisa merasakan Kekuatan yang lebih besar di balik mereka, Dia memilihku, memanggil-Ku."
  },
  AvgDialog_142891_Content_116 = {
    Text = "Aku bisa berbuat lebih banyak, tapi Leisa merasa Asalkan kita bersembunyi dengan baik, monster-monster itu tidak ada hubungannya dengan kita, dan segalanya akan aman."
  },
  AvgDialog_142891_Content_117 = {
    Text = "Banjir informasi yang begitu besar membuatmu hanya bisa berkedip-kedip dengan bengong, untuk pertama kalinya kamu merasakan perasaan di mana setiap kata dipahami, namun ketika digabungkan sama sekali tidak dimengerti."
  },
  AvgDialog_142891_Content_118 = {
    Text = "Pontos sepertinya juga tersadar, lalu menoleh dan tersenyum padamu."
  },
  AvgDialog_142891_Content_119 = {
    Text = "Maaf, Yager, apakah aku terlalu banyak bicara sekaligus?"
  },
  AvgDialog_142891_Content_12 = {
    Text = "Putramu sedikit khawatir dengan kondisimu, ingin menggendong cucumu pergi, Dia cemberut, hampir menangis."
  },
  AvgDialog_142891_Content_120 = {
    Text = "Sebelum Leisa Menemukan kita kabur diam-diam, mari kita kembali dulu, kita masih punya banyak waktu untuk membicarakan ini."
  },
  AvgDialog_142891_Content_121 = {
    Text = "Di kejauhan, Leisa sepertinya menyadari ada sesuatu yang bergerak, lalu melirik ke arah sini, Pontos kembali memberi isyarat diam padamu."
  },
  AvgDialog_142891_Content_123 = {
    Text = "Jendela terbuka dengan diam-diam, lalu tertutup kembali dengan diam-diam."
  },
  AvgDialog_142891_Content_124 = {
    Text = "Seolah hanya angin yang pernah membuka jendela. Di luar jendela, ombak menghantam lalu surut. Kau mendengar suara langkah Leisa naik dari lantai bawah."
  },
  AvgDialog_142891_Content_125 = {
    Text = "Kalian membenamkan wajah ke bantal dengan napas yang teratur, berpura-pura ini masih malam yang biasa."
  },
  AvgDialog_142891_Content_13 = {
    Text = "Kamu tertawa sambil batuk beberapa kali, dengan susah payah menopang tulang-tulang yang Fragile ini, bersandar di kepala ranjang."
  },
  AvgDialog_142891_Content_14 = {
    Text = "Vera, jangan menangis. Cahaya bulan di luar begitu indah, redupkan lampunya sedikit."
  },
  AvgDialog_142891_Content_15 = {
    Text = "Kakek masih punya waktu untuk menceritakan satu kisah lagi untukmu, biar kupikir dulu……"
  },
  AvgDialog_142891_Content_16 = {
    Text = "Pandanganmu jatuh pada kompas kuningan yang tidak pernah lepas dari sisimu, tidak tergerus oleh waktu, dilapisi Bulan dengan tepi perak yang lembut berbulu."
  },
  AvgDialog_142891_Content_17 = {
    Text = "Dengan penuh kerinduan kamu perlahan mengusap permukaannya, suaramu serak saat tenggelam dalam kenangan."
  },
  AvgDialog_142891_Content_18 = {
    Text = "Itu adalah……lebih dari enam puluh tahun yang lalu, ketika aku masih seorang anak kecil."
  },
  AvgDialog_142891_Content_19 = {
    Text = "Reisa, kapalnya akan segera berangkat dari pelabuhan, dia belum kembali?"
  },
  AvgDialog_142891_Content_2 = {Text = "Bulan."},
  AvgDialog_142891_Content_20 = {
    Text = "Sepertinya memang tidak bisa berpamitan secara langsung, tolong setidaknya sampaikan bros ini……"
  },
  AvgDialog_142891_Content_21 = {
    Text = "Peluit pelabuhan berbunyi, para pemilik perhiasan meninggalkan setumpuk perhiasan pribadi mereka dengan berisik, lalu kembali ke kapal dengan wajah penuh penyesalan."
  },
  AvgDialog_142891_Content_22 = {
    Text = "Ya ampun, demi @3, sayangku, kapan pamanmu itu akhirnya bisa sedikit belajar untuk tidak punya begitu banyak \"teman\"?"
  },
  AvgDialog_142891_Content_23 = {
    Text = "Ibumu, Reisa, menatapmu dengan ekspresi geli sekaligus pasrah, menghela napas dan memasukkan perhiasan-perhiasan itu ke dalam kotak kecil yang akan dikembalikan kepada kapten kapal untuk diteruskan saat kapal berlabuh lagi."
  },
  AvgDialog_142891_Content_24 = {
    Text = "Keluargamu mengelola sebuah penginapan kecil yang biasa saja di kota pesisir, hanya ada satu hal yang sedikit istimewa……"
  },
  AvgDialog_142891_Content_25 = {
    Text = "Coba kulihat siapa jagoan tampan ini——"
  },
  AvgDialog_142891_Content_26 = {
    Text = "Pintu besar kembali terbuka membawa Angin beraroma asin, \"hal istimewa\" itu tertawa terbahak-bahak sambil memelukmu dari pinggang dan mengayunkanmu di udara."
  },
  AvgDialog_142891_Content_27 = {
    Text = "Pontos! Sudah kubilang berapa kali, kau bisa melukai lengannya!"
  },
  AvgDialog_142891_Content_28 = {
    Text = "Paman Pontos!"
  },
  AvgDialog_142891_Content_29 = {
    Text = "Hai, Yager kecil, lihat apa yang kubawakan untukmu?"
  },
  AvgDialog_142891_Content_3 = {
    Text = "Bulan purnama paling terang yang pernah kamu lihat tergantung di langit. Anggota tubuhmu terasa Lemah tak berdaya, dan pikiranmu pun agak lamban."
  },
  AvgDialog_142891_Content_30 = {
    Text = "Dia menjentikkan jari, membuka telapak tangannya di udara, dan sebuah kompas berlapis tembaga yang berat jatuh ke telapak tanganmu."
  },
  AvgDialog_142891_Content_31 = {
    Text = "Lebih baik ini didapat dari jalur yang benar, rumah ini sudah tidak bisa menampung lebih banyak \"Token Kepercayaan\" dan \"hati yang hancur\" lagi."
  },
  AvgDialog_142891_Content_32 = {
    Text = "Leisa dengan mengejek melemparkan kotak perhiasan itu kepadanya, mengangkat dagunya, memberi isyarat bahwa kapal yang membawa separuh lainnya dari \"hati yang hancur\" baru saja meninggalkan pelabuhan."
  },
  AvgDialog_142891_Content_33 = {
    Text = "Aduh… kamu tahu sendiri, aku memang tidak terlalu pandai menolak orang lain."
  },
  AvgDialog_142891_Content_34 = {
    Text = "Pontos dengan cengengesan memiringkan kepala menghindari satu Serangan Kuat dari Leisa, lalu menurunkanmu ke tanah."
  },
  AvgDialog_142891_Content_35 = {
    Text = "Ngomong-ngomong, aku sudah mengenal beberapa teman baru, kita mungkin perlu bicara, Leisa."
  },
  AvgDialog_142891_Content_36 = {
    Text = "Tentang hal-hal yang tidak ingin kamu bicarakan."
  },
  AvgDialog_142891_Content_37 = {
    Text = "Kamu sibuk memeriksa mainan baru di tanganmu, melewatkan Ekspresi tidak enak di Wajah Leisa, Pontos mengacak-acak rambutmu."
  },
  AvgDialog_142891_Content_38 = {
    Text = "Aku dan mama ada sedikit urusan yang perlu dibicarakan, kalau jagoan kesayanganku mau naik ke atas dan bermain sebentar, aku akan menceritakan beberapa kisah perjalanan yang seru, deal?"
  },
  AvgDialog_142891_Content_39 = {
    Text = "Dia mengulurkan lima jarinya, kamu membalasnya demi kompas itu, itulah ritual \"jabat tangan deal\" yang hanya milik kalian berdua."
  },
  AvgDialog_142891_Content_4 = {
    Text = "Angkat tanganmu, garis-garis yang melambangkan ketuaan telah menjalar di seluruh kulitmu."
  },
  AvgDialog_142891_Content_41 = {
    Text = "Kamu tengkurap di lantai kamar tidur lantai atas, mengeluarkan peta, dengan penuh konsentrasi mencoba menggunakan kompas untuk menemukan arah-arah dalam kisah pelayaran itu."
  },
  AvgDialog_142891_Content_42 = {
    Text = "Namun rumah ini sudah terlalu tua, laut dan angin terus menggerogotinya, beberapa patah kata masih bisa terdengar samar merembes dari celah lantai."
  },
  AvgDialog_142891_Content_43 = {
    Text = "……mereka semua sudah……memberitahu……tidak bisa terus……bersembunyi bukan solusi."
  },
  AvgDialog_142891_Content_44 = {
    Text = "……Mereka……aku bisa……Talent-ku……"
  },
  AvgDialog_142891_Content_45 = {
    Text = "Nada bicara Paman Pontos semakin mendesak, kamu baru saja ingin menempelkan telinga dengan penasaran——"
  },
  AvgDialog_142891_Content_46 = {Text = "BRAK! DUK!"},
  AvgDialog_142891_Content_47 = {
    Text = "Pintu dibanting terbuka dengan keras, Pontos dilempar masuk dengan ditarik kerahnya, Leisa memasang Wajah serius dengan Ekspresi yang berarti \"tidak bisa ditawar\"."
  },
  AvgDialog_142891_Content_48 = {
    Text = "Aku tidak setuju, Pontos. Satu-satunya harapanku adalah kalian semua hidup dengan selamat……jauhi teman-teman barumu itu."
  },
  AvgDialog_142891_Content_49 = {
    Text = "Kalau situasinya benar-benar tidak terkendali, aku akan membawa kalian pergi dari sini."
  },
  AvgDialog_142891_Content_5 = {
    Text = "Ah, ternyata aku sudah sampai di usia ini… Mungkin malam ini adalah malam terakhir."
  },
  AvgDialog_142891_Content_50 = {
    Text = "Hei, Leisa, aku sudah bukan anak kecil lagi! Kita tidak bisa terus-terusan kabur begini."
  },
  AvgDialog_142891_Content_51 = {
    Text = "Belajar dulu membantuku mengurus bisnis, jangan berkeliaran di luar seharian baru bicara soal ini."
  },
  AvgDialog_142891_Content_52 = {
    Text = "Kamu jarang mendengar Leisa berbicara dengan nada setajam itu, dia menarik napas, memaksakan senyum tipis untukmu."
  },
  AvgDialog_142891_Content_53 = {
    Text = "Yager, tolong mama. Jaga pamanmu, setidaknya malam ini jangan biarkan dia keluyuran lagi."
  },
  AvgDialog_142891_Content_54 = {
    Text = "Dia melemparkan kata-kata itu, lalu terburu-buru turun ke bawah untuk mengurus buku-buku akun yang tak pernah ada habisnya, seolah ingin segera mengakhiri topik ini."
  },
  AvgDialog_142891_Content_55 = {
    Text = "Pontos mengangkat alis, mengangkat bahu ke arahmu."
  },
  AvgDialog_142891_Content_56 = {
    Text = "Baiklah, Jaeger, sepertinya kita bisa memajukan waktu cerita sedikit lebih awal."
  },
  AvgDialog_142891_Content_58 = {
    Text = "Mungkin karena kisah-kisah yang berjatuhan keluar dari kabin kapal bersama barang-barang itu terlalu penuh liku, hingga tengah malam, tidurmu pun tidak nyenyak."
  },
  AvgDialog_142891_Content_59 = {
    Text = "Cahaya bulan di luar jendela melapisi kelopak matamu dengan warna perak, sesuatu menghalanginya."
  },
  AvgDialog_142891_Content_6 = {
    Text = "Ingatan perlahan kembali, tapi anehnya, hatimu tidak merasakan ketakutan akan kematian sama sekali, melainkan tersenyum karena kedamaian yang tulus dari dalam hati."
  },
  AvgDialog_142891_Content_60 = {
    Text = "Klik, itu suara kait jendela, kamu Buka mata, daun jendela sudah ditarik terbuka sepenuhnya."
  },
  AvgDialog_142891_Content_61 = {Text = "!"},
  AvgDialog_142891_Content_62 = {
    Text = "Paman Pontos, kamu tidak boleh keluar lewat jendela, Mama akan marah!"
  },
  AvgDialog_142891_Content_63 = {
    Text = "Setengah tubuh Pontos sudah melewati ambang jendela, tanpa pikir panjang kamu hendak berlari memeluknya, bahkan lupa mempertimbangkan mengapa dia tampak seperti… melayang di udara."
  },
  AvgDialog_142891_Content_64 = {
    Text = "Tunggu, hati-hati!"
  },
  AvgDialog_142891_Content_65 = {
    Text = "Rasa tak berbobot menyerang, lalu——"
  },
  AvgDialog_142891_Content_66 = {Text = "SYUUT!"},
  AvgDialog_142891_Content_67 = {
    Text = "SRAAAK——!"
  },
  AvgDialog_142891_Content_7 = {
    Text = "Orang-orang tersayang berkerumun di sisimu, cucu perempuan terkecilmu Vera belum mengerti apa-apa, hanya bersandar dengan penuh kasih di sisi tanganmu."
  },
  AvgDialog_142891_Content_70 = {
    Text = "Kau ditarik dengan kasar dari kain di pinggangmu, sensasi bulu halus yang aneh menyapu wajahmu."
  },
  AvgDialog_142891_Content_71 = {
    Text = "Kamu Buka mata, gemetar bagai jatuh ke dalam lubang es tiba-tiba menjalar dari tulang belakang hingga ke ubun-ubun."
  },
  AvgDialog_142891_Content_72 = {Text = "Pon——"},
  AvgDialog_142891_Content_73 = {
    Text = "Ekor makhluk aneh yang sama sekali tidak memiliki fitur wajah dan tak terlukiskan itu tersangkut di punggungmu, ujung ekornya dipenuhi duri-duri jelek yang rapat."
  },
  AvgDialog_142891_Content_74 = {
    Text = "Kamu tidak sempat memikirkan bahwa jelas tadi makhluk horor inilah yang menyelamatkanmu, teriakan tertahan yang tidak terkendali hampir meledak keluar dari tenggorokanmu."
  },
  AvgDialog_142891_Content_75 = {Text = "Ssst!"},
  AvgDialog_142891_Content_76 = {
    Text = "Pontos yang tengkurap di atas makhluk tak berwajah itu langsung meraih dan menaikkanmu ke sana, menutup mulutmu rapat-rapat, makhluk itu membentangkan sayap besar seperti kelelawar, meluncur tanpa suara ke dalam kegelapan malam."
  },
  AvgDialog_142891_Content_77 = {
    Text = "Jangan takut, Mereka tidak akan menyakitimu."
  },
  AvgDialog_142891_Content_78 = {
    Text = "Tidak ada waktu, Yager, jangan bersuara, aku akan menjelaskannya nanti."
  },
  AvgDialog_142891_Content_79 = {
    Text = "Pontos merangkul bahumu dengan menenangkan, menyelipkanmu di antara dirinya dan makhluk itu, membungkuk rendah, tatapannya terpaku pada hamparan karang di sudut pelabuhan yang sepi."
  },
  AvgDialog_142891_Content_8 = {
    Text = "Kakek, kapan kamu bisa menemani aku bermain lagi? Lihat, yang kakek ajarkan terakhir kali, aku sudah bisa."
  },
  AvgDialog_142891_Content_80 = {
    Text = "Kau tidak sempat bertanya apa pun, dari dalam laut, suara sial itu merayap keluar seperti cacing."
  },
  AvgDialog_142891_Content_81 = {
    Text = "<Shake:<Red:Srek, srek, srek, srek…>>"
  },
  AvgDialog_142891_Content_82 = {
    Text = "<Shake:<Red:Plak, plak… Blesak——>>"
  },
  AvgDialog_142891_Content_83 = {
    Text = "！……hoek……"
  },
  AvgDialog_142891_Content_84 = {
    Text = "Pertama cakar bersisik, lalu lengan, atau mungkin anggota tubuh lunak yang berbelit-belit, tubuh yang dipenuhi teritip dan lendir menjijikkan bak penistaan terhadap yang suci……"
  },
  AvgDialog_142891_Content_85 = {
    Text = "Kau tidak pernah menyangka bahwa di lautan yang menghasilkan begitu banyak hasil laut, ternyata hidup kelompok terkutuk seperti ini, bola mata mereka yang menonjol penuh dengan niat jahat, menatap tajam bangunan-bangunan di kota."
  },
  AvgDialog_142891_Content_86 = {
    Text = "<Change>@4 Tipu… di mana pun ia melangkah…"
  },
  AvgDialog_142891_Content_87 = {
    Text = "<Change>…pasti melewati sini… memberi makan Korosi Lebur, menyerahkan diri pada Korosi Lebur! Daging, daging!!"
  },
  AvgDialog_142891_Content_88 = {
    Text = "<Small:<Shake:Paman, ada, ada monster!!>>"
  },
  AvgDialog_142891_Content_89 = {
    Text = "Detik berikutnya, makhluk bersayap tanpa wajah di bawah kalian menukik ke bawah, Pontos membentangkan jari-jarinya yang bertulang tegas, cahaya samar menyerang dua makhluk hina itu."
  },
  AvgDialog_142891_Content_9 = {
    Text = "Dia mengangkat seekor belalang yang bentuknya tidak karuan, lalu meletakkannya di atas selimut."
  },
  AvgDialog_142891_Content_90 = {Text = "Nng, mmh!"},
  AvgDialog_142891_Content_91 = {
    Text = "Mereka terjatuh kaku ke tanah, bagaikan dua patung yang terbelah."
  },
  AvgDialog_142891_Content_92 = {
    Text = "Pak, suara sentuhan ringan."
  },
  AvgDialog_142891_Content_93 = {
    Text = "Lalu kedua belahan tubuh itu menghantam tanah, berubah menjadi abu abu-abu yang tersapu angin laut."
  },
  AvgDialog_142891_Content_94 = {
    Text = "Huh, aku sudah tahu pasti ada satu dua yang lolos, Leisa dan yang lainnya masih terlalu ceroboh."
  },
  AvgDialog_142891_Content_95 = {
    Text = "<Shake:Mama dan yang lainnya? Paman Pontos, sebenarnya ini ada apa?!>"
  },
  AvgDialog_142891_Content_96 = {
    Text = "Kau hampir lemas karena ketakutan, hampir terjatuh dari punggung yang licin itu."
  },
  AvgDialog_142891_Content_97 = {
    Text = "Tunggu sebentar, aku harus memastikan dulu apakah Mereka baik-baik saja."
  },
  AvgDialog_142891_Content_98 = {
    Text = "Pontos hanya menepuk bahumu, lalu menggerakkan makhluk itu untuk membawa kalian terbang menuju garis pantai di sisi lain kota."
  },
  AvgDialog_142892_Content_1 = {
    Text = "Saat Kau Tiada"
  },
  AvgDialog_142892_Content_10 = {
    Text = "Pasir kuning."
  },
  AvgDialog_142892_Content_11 = {
    Text = "Hamparan salju."
  },
  AvgDialog_142892_Content_12 = {Text = "Kesunyian."},
  AvgDialog_142892_Content_13 = {
    Text = "Lalu kembali ke malam."
  },
  AvgDialog_142892_Content_14 = {
    Text = "Ini bukanlah perjalanan dan lintasan yang bisa dipahami manusia. Waktu dan ruang menjadi tak bermakna. Kalian hanya terus melintasi dan menjelajah, kau merasakan segalanya lalu dihancurkan oleh segalanya."
  },
  AvgDialog_142892_Content_15 = {
    Text = "Karena Mereka berani menerobos masuk, maka usir Mereka dari dunia fana, buat Mereka gentar terhadap kita, buat Mereka mengingat namaku!"
  },
  AvgDialog_142892_Content_16 = {
    Text = "Pontos dengan bebas menghambur-hamburkan Kekuatan yang telah diraihnya, dan mereka yang telah mendapatkan keberadaannya kini juga sedang Mencabik-cabik musuh-musuhnya."
  },
  AvgDialog_142892_Content_17 = {
    Text = "Tak terhitung monster yang terdistorsi dan menjijikkan, diburu dan ditusuk olehnya bersama para Nightmare dan Pemimpin Gaunt."
  },
  AvgDialog_142892_Content_18 = {
    Text = "Pada akhirnya menjadi bagian dari pesta pora, mengundang tak terhitung siulan perayaan dan tawa."
  },
  AvgDialog_142892_Content_19 = {
    Text = "Tidak, tidak, jangan lagi, tidaktidaktidaktidaktidaktidak!!!!!!"
  },
  AvgDialog_142892_Content_2 = {
    Text = "Sentuhan bulu halus yang aneh, duri tajam di ujung ekor, sayap membran raksasa yang membelah langit malam tanpa suara."
  },
  AvgDialog_142892_Content_20 = {
    Text = "Kau menyaksikan sendiri sinar yang dilepaskan Pontos menghancurkan penganut fanatik ini menjadi debu, tetapi sesaat kemudian, tubuh-Nya kembali menyusun diri, mengeluarkan tangisan ketakutan dari mulut-Nya."
  },
  AvgDialog_142892_Content_21 = {
    Text = "Dia adalah yang paling setia di antara para fanatik ini, namun kini, Dia telah mengalami entah berapa kali kematian yang menyakitkan dan penyusunan ulang."
  },
  AvgDialog_142892_Content_22 = {
    Text = "Paman Pontos, Dia sedang… Kelahiran Kembali?"
  },
  AvgDialog_142892_Content_23 = {
    Text = "Tidak, Dia Hanya merasakan penderitaan yang dijanjikan dalam siklus mati dan hidup kembali berulang kali."
  },
  AvgDialog_142892_Content_24 = {
    Text = "Terkadang aku juga membiarkan Mereka mati, Asalkan Mereka melepaskan kepercayaan pada dewa-dewa yang Menodai dan kotor itu."
  },
  AvgDialog_142892_Content_25 = {
    Text = "Tapi jika Kesetiaan Mereka terlalu Teguh, maka bahkan kematian pun tak bisa membebaskan Mereka dari penderitaan."
  },
  AvgDialog_142892_Content_26 = {
    Text = "Diucapkan dengan enteng seolah hanya membicarakan hal sepele, telapak tangan Pontos terangkat, kekuatan tak kasat mata membuat kedua lengan si penganut fanatik terbentang, tubuh bagian atasnya membungkuk, berlutut di hadapan Pontos."
  },
  AvgDialog_142892_Content_27 = {
    Text = "Ayo, katakan sekali lagi padaku, apakah kau masih menyembah tuhanmu yang menjijikkan itu?"
  },
  AvgDialog_142892_Content_28 = {
    Text = "<LightGray:*isak tangis> Tidak... tidak, kumohon, kumohon padamu, biarkan aku mati, Asalkan kau membiarkanku mati!"
  },
  AvgDialog_142892_Content_29 = {
    Text = "<Shake:Hahaha, hahahahahaha, tidak ada juru selamat, sama sekali tidak ada juru selamat, hanya AB@2S, hanya @2@3!!>"
  },
  AvgDialog_142892_Content_3 = {
    Text = "Pontos mengajakmu bergabung dalam perburuan malam sebelum pesta pora Epoyanis setiap malam."
  },
  AvgDialog_142892_Content_30 = {
    Text = "Bagus, mangsa, angkat kepalamu, perlihatkan tenggorokanmu."
  },
  AvgDialog_142892_Content_31 = {
    Text = "Sang fanatik mengeluarkan suara isak tangis Distortion dan tawa gila dengan pikiran yang crash, merangkak maju dengan lutut, mengangkat lehernya tinggi-tinggi dengan postur yang aneh."
  },
  AvgDialog_142892_Content_32 = {
    Text = "Aku akan menganugerahkan kematian padamu."
  },
  AvgDialog_142892_Content_33 = {
    Text = "Cahaya melelehkan tenggorokan-Nya sepenuhnya bagaikan pisau panas memotong mentega, tubuh-Nya tiba-tiba runtuh menjadi debu abu, tersapu angin ke lautan."
  },
  AvgDialog_142892_Content_34 = {
    Text = "Kali ini, penganut yang menyedihkan ini tidak mengalami Kelahiran Kembali."
  },
  AvgDialog_142892_Content_35 = {
    Text = "Ke mana para fanatik lain yang tertangkap itu pergi?"
  },
  AvgDialog_142892_Content_36 = {
    Text = "Mereka juga ada di Epoyanis."
  },
  AvgDialog_142892_Content_37 = {
    Text = "Sebuah Epoyanis yang sama-sama abadi, namun tidak sebahagia ini."
  },
  AvgDialog_142892_Content_38 = {
    Text = "Di sana, Tidak ada apa-apa, bahkan penderitaan pun bisa dianggap sebagai hadiah."
  },
  AvgDialog_142892_Content_39 = {
    Text = "Kamu setengah mengerti setengah tidak, cahaya bulan menyelimuti kalian, Nightmare menjaga kalian, perjalanan menakjubkan ini menuju Epilog."
  },
  AvgDialog_142892_Content_4 = {
    Text = "Di dalam berbagai medium yang sulit dikenali, orang-orang Epoyanis memburu \"mangsa\" dari berbagai Dimensi."
  },
  AvgDialog_142892_Content_40 = {
    Text = "Pejamkan matamu, Yagor."
  },
  AvgDialog_142892_Content_41 = {
    Text = "Kegelapan yang lembap, akrab, dan rapat memelukmu, menelanmu."
  },
  AvgDialog_142892_Content_42 = {
    Text = "Kalian kembali ke Rumah Tinggi, Pontos melangkah turun dari kereta perang, membuka tirai pesta pora yang baru."
  },
  AvgDialog_142892_Content_43 = {
    Text = "Anak ini sepertinya sangat menyukaimu."
  },
  AvgDialog_142892_Content_44 = {
    Text = "Di dekat kusen jendela beranda, Pontos meninggalkan kerumunan yang ramai, mengulurkan tangannya ke arah Nightmare yang berputar-putar di luar jendela."
  },
  AvgDialog_142892_Content_45 = {
    Text = "Meskipun entah kenapa banyak hal yang tidak bisa kuingat dengan jelas, tapi, Paman Pontos, kau sudah bukan manusia lagi, dan tempat ini juga bukan dunia yang kupahami, kan?"
  },
  AvgDialog_142892_Content_46 = {
    Text = "Apakah aku sudah mati?"
  },
  AvgDialog_142892_Content_47 = {
    Text = "Tampaknya tidak menyangka kau akan bertanya seterus terang ini, Pontos sedikit terkejut mengangkat alisnya, lalu—tertawa."
  },
  AvgDialog_142892_Content_48 = {
    Text = "Teman kecilku yang tersayang, tentu saja tidak."
  },
  AvgDialog_142892_Content_49 = {
    Text = "Tinggallah di Epoyansi, kau akan menjalani kehidupan yang agung dan luar biasa seperti yang kau impikan saat membaca buku cerita di masa kecil. Kau tidak akan pernah lagi terkikis oleh waktu."
  },
  AvgDialog_142892_Content_5 = {
    Text = "Cahaya aneh masih berkedip-kedip di balik kaca gedung-gedung tinggi, Nightmare demi Nightmare berputar-putar di udara."
  },
  AvgDialog_142892_Content_50 = {
    Text = "Kita akan berpetualang, melarikan diri dari dunia fana. Musuh-musuh yang membawa perubahan drastis dan bencana ke dalam hidup kita, pada akhirnya akan kita hancurkan hingga mereka tak berani menampakkan diri lagi selamanya."
  },
  AvgDialog_142892_Content_51 = {
    Text = "Kau menarik napas dalam-dalam. Kau kembali meraba belalang rumput itu—kasar, tidak rapi, sedikit menusuk tangan."
  },
  AvgDialog_142892_Content_52 = {
    Text = "Ya, semua itu memang terdengar indah."
  },
  AvgDialog_142892_Content_53 = {
    Text = "Tapi apa harga yang harus kubayar, Paman Pontos?"
  },
  AvgDialog_142892_Content_54 = {
    Text = "Alisnya mengernyit perlahan sekali, membawa keangkuhan yang terasa asing bagimu."
  },
  AvgDialog_142892_Content_55 = {
    Text = "Harganya Hanya Saja... sesuatu yang sama sekali tidak penting, sesuatu yang tidak kamu butuhkan, dan tidak akan kamu ingat. <Red:Berikan padaku>, Yager."
  },
  AvgDialog_142892_Content_56 = {
    Text = "Begitu kata-katanya selesai, ekor berkait milik nightmare itu menjulur dari luar jendela menuju sakumu."
  },
  AvgDialog_142892_Content_57 = {
    Text = "Meraih belalang di sakumu."
  },
  AvgDialog_142892_Content_58 = {Text = "Tidak!"},
  AvgDialog_142892_Content_59 = {
    Text = "Secara refleks kau mundur dengan cepat, tetapi gerakan ini tampaknya membuat Pontos marah. Ia langsung mencengkeram lenganmu."
  },
  AvgDialog_142892_Content_6 = {
    Text = "Hingga Pontos yang berdiri bersamamu di dalam bodi kendaraan berkilau mutiara yang tak terjelaskan itu mengeluarkan sebuah pekikan."
  },
  AvgDialog_142892_Content_60 = {
    Text = "Kau sama sekali tidak mengerti, Nak. Aku sudah menghabiskan begitu banyak usaha untuk menemukanmu..."
  },
  AvgDialog_142892_Content_61 = {
    Text = "Guk guk, guk guk..."
  },
  AvgDialog_142892_Content_62 = {
    Text = "Kau membeku di tempat. Yang menempel di kulitmu bukan hanya jari-jari Pontos. Ketakutan tak bernama membuatmu mendongak, dan pupil biru tua Pontos jatuh berat menimpamu."
  },
  AvgDialog_142892_Content_63 = {
    Text = "Karena kau ingin melihat, lihatlah—dari hal macam apa sebenarnya aku menyelamatkanmu."
  },
  AvgDialog_142892_Content_64 = {
    Text = "Kamu sekali lagi <Red:ditelan>."
  },
  AvgDialog_142892_Content_66 = {
    Text = "Hei, hei, kawan lama, kau dengar aku bicara tidak? Kenapa kau melamun lagi? Hati-hati!"
  },
  AvgDialog_142892_Content_67 = {
    Text = "Crat! Air berlumpur terciprat ke wajahmu. Kau tersadar dengan terkejut, memandangi orang di sampingmu dengan linglung. Tua, bungkuk, cerewet—tapi kau mengenalinya. Itu tidak diragukan lagi adalah Orni yang sudah menua."
  },
  AvgDialog_142892_Content_68 = {
    Text = "Para pelaut sialan itu, benar-benar tidak tahu aturan! Kalau kau tanya aku, pelayaran-pelayaran itu sudah membuat hati mereka liar. Sama sekali tidak punya pikiran untuk mengurus hal-hal yang sebenarnya penting!"
  },
  AvgDialog_142892_Content_69 = {
    Text = "Olney?… Bukankah impian terbesarmu saat kecil adalah menjadi seorang pelaut dan menjelajahi setiap benua?"
  },
  AvgDialog_142892_Content_7 = {
    Text = "Tangkap Mereka, jangan biarkan Mereka pergi lagi selamanya, biarkan Mereka menderita di sini untuk selama-lamanya!"
  },
  AvgDialog_142892_Content_70 = {
    Text = "Aku pernah bilang begitu? Jangan bercanda. Di usia kita sekarang, seharusnya kita sudah tahu bahwa hidup tenang dan stabil adalah yang terbaik."
  },
  AvgDialog_142892_Content_71 = {
    Text = "Kamu lupa, kawan lama, sejak tahun kedua kuliah kita tidak membahas ini lagi. Kita membicarakan berita-berita di koran, laporan-laporan sialan satu per satu, dana pensiun, makan malam keluarga dua minggu sekali."
  },
  AvgDialog_142892_Content_72 = {
    Text = "Dia menepuk bahumu, lalu dengan tangan gemetar mengambil dua kantong kertas dari jendela apotek."
  },
  AvgDialog_142892_Content_73 = {
    Text = "Bukankah kau sama sepertiku? Setelah lulus kuliah dan kembali ke sini, syukurlah, kita bahkan malas pergi bepergian jauh."
  },
  AvgDialog_142892_Content_74 = {
    Text = "Artritis sialan ini, untungnya, selain kamu dan obat pereda nyeri ini, tidak ada hal lain yang mengharuskanku keluar."
  },
  AvgDialog_142892_Content_75 = {
    Text = "Kesepian, ha! Waktu kita masih muda, kita pikir itu sama mustahilnya seperti Bigfoot!"
  },
  AvgDialog_142892_Content_76 = {
    Text = "Olney terus mengoceh tentang sesuatu. Kau menatap bibirnya yang terbuka dan tertutup, lalu pusing yang datang tiba-tiba menarikmu keluar dari keseharian yang membosankan."
  },
  AvgDialog_142892_Content_78 = {
    Text = "Kau lihat? Hari-hari biasa itu telah mengubah Olney menjadi seperti apa. Sekarang pergi dan lihatlah, apa yang kau dapatkan sebagai gantinya."
  },
  AvgDialog_142892_Content_79 = {
    Text = "Kau melihatnya—terbaring di tempat tidur, kurus kering dan layu—dirimu."
  },
  AvgDialog_142892_Content_8 = {Text = "Awan."},
  AvgDialog_142892_Content_80 = {
    Text = "Tentu saja, awalnya mereka akan bersedih, meneteskan beberapa tetes air mata untukmu."
  },
  AvgDialog_142892_Content_81 = {
    Text = "Kau melihat sepasang suami istri dan putri kecil mereka pergi jalan-jalan, saling menghibur satu sama lain."
  },
  AvgDialog_142892_Content_82 = {
    Text = "Namun dalam Satu Minggu, bahkan beberapa hari, mereka akan perlahan membaik."
  },
  AvgDialog_142892_Content_83 = {
    Text = "Makan bersama, pergi keluar, siapa yang tahu? Anak-anak akan tinggal sedikit lebih lama, tentu saja, tidak akan terlalu lama."
  },
  AvgDialog_142892_Content_84 = {
    Text = "Pada akhirnya, tidak akan ada yang tersisa di sini, tidak ada yang akan mengingatmu."
  },
  AvgDialog_142892_Content_85 = {
    Text = "Musim dingin, Musim Semi, lalu musim dingin lagi, rumah itu segera dipenuhi debu."
  },
  AvgDialog_142892_Content_86 = {
    Text = "Kau paham sekarang, Jaeger? Aku hanya membawa bagian kalian yang... menarik, bagian yang hidup, ke Erboyance."
  },
  AvgDialog_142892_Content_87 = {
    Text = "Tubuh ini akan segera mati, baik kamu ada maupun tidak, semua orang yang kamu kenal akan menjalani kehidupan mereka sendiri tanpa ada hubungannya denganmu."
  },
  AvgDialog_142892_Content_88 = {
    Text = "Suara Pontos bergema di telingamu. Detik berikutnya, kau kembali muncul di aula besar Erboyance."
  },
  AvgDialog_142892_Content_89 = {
    Text = "Sekarang, Jaeger, pikirkanlah, pikirkanlah baik-baik. Buang raga itu, lepaskan ingatan-ingatan yang tak bermakna, dan tinggallah bersama kami."
  },
  AvgDialog_142892_Content_9 = {
    Text = "Tanah musnah."
  },
  AvgDialog_142892_Content_90 = {
    Text = "Olney di Erboyance, Paman White, setiap orang di lantai dansa yang ramai—seolah tiba-tiba semuanya memperhatikan ke sini."
  },
  AvgDialog_142892_Content_91 = {
    Text = "Hei, kenapa kalian berdua memasang wajah seperti itu? Kita baru saja meraih kemenangan besar lagi!"
  },
  AvgDialog_142892_Content_92 = {
    Text = "Ayo, Jaeger, minum bersama kami! Di Erboyance tidak ada hal yang perlu dikhawatirkan!"
  },
  AvgDialog_142892_Content_93 = {
    Text = "Mereka tertawa riang, mengerumunimu di tengah-tengah mereka."
  },
  AvgDialog_142892_Content_94 = {
    Text = "Orang-orang saling melempar barang rampasan, bahu-membahu satu sama lain, dan suara air laut itu muncul kembali."
  },
  AvgDialog_142892_Content_95 = {
    Text = "Pontos mengulurkan tangannya, Menunggu kamu menggenggam kelima jarinya."
  },
  AvgDialog_142892_Content_96 = {
    Text = "Seperti \"jabat tangan kesepakatan\" yang kalian buat saat masih kecil."
  },
  AvgDialog_142893_Content_1 = {Text = "Alasan"},
  AvgDialog_142893_Content_10 = {
    Text = "<Red:Seharusnya tidak seperti ini.>"
  },
  AvgDialog_142893_Content_11 = {
    Text = "Seharusnya kau secara tidak sengaja mengetahui garis darahmu, lalu Mama dibujuk Paman Pontos untuk membimbingmu, kalian akan memulai perjalanan bersama, mengalami banyak hal yang menegangkan sekaligus menyenangkan."
  },
  AvgDialog_142893_Content_12 = {
    Text = "<Shake:Lalu kamu akan menjadi seorang <Red:pemberani> yang hebat, begitulah yang tertulis dalam novel petualangan.>"
  },
  AvgDialog_142893_Content_13 = {
    Text = "Yager! Semangat, tidak apa-apa, ibumu adalah Pengendali Mimpi Buruk terkuat yang pernah kulihat, semuanya pasti akan teratasi!"
  },
  AvgDialog_142893_Content_14 = {
    Text = "Aku… Paman Pontos, Mama…"
  },
  AvgDialog_142893_Content_15 = {
    Text = "Kota kecil yang biasanya tenang, kini telah sepenuhnya tenggelam dalam lautan api."
  },
  AvgDialog_142893_Content_16 = {
    Text = "Hanya saja satu hari telah berlalu, para fanatik yang datang tiba-tiba dan membanjiri segala sesuatu yang terlihat oleh matamu."
  },
  AvgDialog_142893_Content_17 = {
    Text = "Di antara mereka ada manusia, juga ada monster sejati, serangan tanpa pandang bulu membuat seluruh kota membakar dengan hebat."
  },
  AvgDialog_142893_Content_18 = {
    Text = "Darah dengan bau amis asin terciprat di wajah dan tubuhmu, Pontos meniup peluit berburu di tangannya sekuat tenaga, memaksa membuka jalan bersama Nightmare-nya."
  },
  AvgDialog_142893_Content_19 = {
    Text = "Pontos, bawa Yager, lari!"
  },
  AvgDialog_142893_Content_2 = {
    Text = "Malam itu, kau yang kelelahan karena terlalu terkejut dan terlalu banyak berpikir, segera tertidur."
  },
  AvgDialog_142893_Content_20 = {
    Text = "Leisa yang sedang bersusah payah bersama para Pengendali Mimpi Buruk lainnya menghentikan gelombang monster yang mendekat, melihat kamu selamat, matanya bersinar, dan berteriak sekuat tenaga kepada Pontos."
  },
  AvgDialog_142893_Content_21 = {Text = "Kyiii!"},
  AvgDialog_142893_Content_22 = {
    Text = "Satu lagi kepala yang menyerupai anemon laut dirobek oleh cakar tajam Nightmare, Reisa mengibaskan cahaya putih samar yang sama seperti milik Pontos, menghalangi Pontos berlari ke arahnya."
  },
  AvgDialog_142893_Content_23 = {
    Text = "Kali ini kita tidak bisa menang, tapi masih bisa mengulur waktu untuk kalian, lari, lari sejauh mungkin!"
  },
  AvgDialog_142893_Content_24 = {
    Text = "Bercanda apa, musuh yang lebih banyak dari ini pun pernah kamu selesaikan dengan mudah, tidak akan ada masalah! Dan, kamu tahu, kita selalu punya cara."
  },
  AvgDialog_142893_Content_25 = {
    Text = "Kau tidak tahu apa yang dimaksud Paman Pontos dengan rencananya, hanya melihat tatapannya jatuh pada peluit yang tidak pernah meninggalkan sisinya sejak ia kembali kali ini."
  },
  AvgDialog_142893_Content_26 = {
    Text = "Tidak, <Red:tidak akan pernah.>"
  },
  AvgDialog_142893_Content_27 = {
    Text = "<Shake:Aku tahu apa yang kau pikirkan, <Red:adikku tidak boleh selamanya terjebak di tempat terkutuk itu!>   >"
  },
  AvgDialog_142893_Content_28 = {
    Text = "Menyerahkan diri pada Sukaci@1, memberi makan Erosi!"
  },
  AvgDialog_142893_Content_29 = {Text = "Reisa!!!"},
  AvgDialog_142893_Content_3 = {
    Text = "Kau dan Pontos sama-sama mengira masih banyak kesempatan untuk membicarakan hal ini."
  },
  AvgDialog_142893_Content_30 = {
    Text = "Di tengah suara sisik yang pecah dengan ganas, seorang fanatik yang setengah tubuhnya sudah tercabik bola matanya yang Merah Darah menonjol sepenuhnya, menggumam dengan Fury sambil menerjang Leisa."
  },
  AvgDialog_142893_Content_31 = {
    Text = "…Suara yang membuat gigi ngilu, kulit dan daging yang robek."
  },
  AvgDialog_142893_Content_32 = {
    Text = "Suara dua tubuh menghantam jalan berbatu."
  },
  AvgDialog_142893_Content_33 = {
    Text = "Suara organ dalam yang tumpah keluar."
  },
  AvgDialog_142893_Content_34 = {
    Text = "Lalu, dunia tiba-tiba hening, kau tak bisa mendengar apa pun, juga tak bisa melihat apa pun."
  },
  AvgDialog_142893_Content_35 = {
    Text = "Darah, langit malam, bulan."
  },
  AvgDialog_142893_Content_36 = {
    Text = "Bulan sewarna darah, tergantung jauh di angkasa yang tak terjangkau."
  },
  AvgDialog_142893_Content_37 = {
    Text = "Ah……aahh."
  },
  AvgDialog_142893_Content_38 = {
    Text = "AAAAAAAAAHHH!!!!!!"
  },
  AvgDialog_142893_Content_39 = {
    Text = "Setelah rintihan singkat bagai hembusan napas yang dipaksakan keluar dari kedalaman tenggorokan, Pontos mengeluarkan suara yang belum pernah kaudengar seumur hidupmu."
  },
  AvgDialog_142893_Content_4 = {
    Text = "<Red:Ternyata tidak.>"
  },
  AvgDialog_142893_Content_40 = {
    Text = "Ratapan yang sama sekali tidak menyerupai manusia."
  },
  AvgDialog_142893_Content_41 = {
    Text = "Ka-Kakak……Leisa, Leisa!!!"
  },
  AvgDialog_142893_Content_42 = {
    Text = "Otakmu mengeluarkan dengungan tajam, kekosongan luar biasa menerjangmu bagai gelombang laut, tidak, tidak, tidak, tidak, tidaktidaktidaktidaktidak……"
  },
  AvgDialog_142893_Content_43 = {
    Text = "Tidak ada yang selamat, para Pemimpin Gaunt yang biasanya seolah-olah hanya tetangga yang ramah berjatuhan satu per satu, sementara warga biasa kota kecil itu menjerit-jerit di tengah lautan api dan gelombang monster."
  },
  AvgDialog_142893_Content_44 = {
    Text = "Dan kau sudah tidak bisa mendengar semua itu lagi, tubuhmu sepenuhnya mengkhianatimu, ikut bersama mereka, mengeluarkan lolongan yang memilukan."
  },
  AvgDialog_142893_Content_45 = {
    Text = "<Change>Persembahkan mereka semua kepada <Red:Kesukacitaan>!"
  },
  AvgDialog_142893_Content_46 = {
    Text = "Para fanatik lainnya dengan mudah mengunci targetnya padamu, tepat saat cakar-cakar bersisik yang meneteskan lendir Profanasi itu mencengkerammu……"
  },
  AvgDialog_142893_Content_47 = {
    Text = "Pontos meniup peluit berburu itu."
  },
  AvgDialog_142893_Content_48 = {
    Text = "Kamu tidak pernah mendengar suara peluit yang begitu memekakkan dan kuno, suatu kekuatan yang tak masuk akal menembus gendang telingamu, menghantam setiap sudut akal sehatmu yang tersisa."
  },
  AvgDialog_142893_Content_49 = {
    Text = "Intimidasi yang tak tertandingi dan maha luas menghantam daratan!"
  },
  AvgDialog_142893_Content_5 = {
    Text = "Tsss——!"
  },
  AvgDialog_142893_Content_50 = {
    Text = "Kekuatan yang besar dan tak kasat mata menekan Pontos hingga tersungkur ke tanah, namun ia sama sekali tidak menyadarinya, matanya nyaris pecah saat ia melantunkan doa-doa yang sulit dipahami."
  },
  AvgDialog_142893_Content_51 = {
    Text = "No@2, @4,@3Penguasa Jurang, aku memanggil-Mu atas nama @3……"
  },
  AvgDialog_142893_Content_52 = {
    Text = "Tak terhitung keberadaan yang menyerupai lengan hitam, menjulur dari celah yang lebih dalam dari laut paling tua, meraih satu-satunya <Red:mangsa> yang mereka inginkan."
  },
  AvgDialog_142893_Content_53 = {
    Text = "<Shake:Meraih <Red:sang tuan >yang telah mereka pilih.>"
  },
  AvgDialog_142893_Content_54 = {
    Text = "Ambil Caro-ku, ambil jiwaku!"
  },
  AvgDialog_142893_Content_55 = {
    Text = "Di wajah yang selalu tersenyum santai itu, muncul ekspresi penuh keputusasaan yang tragis dan kenekatan tanpa peduli apa pun."
  },
  AvgDialog_142893_Content_56 = {
    Text = "Pada saat keberadaan yang jauh lebih agung dan dahsyat itu menjadi satu dengannya, sayap-sayap yang menutupi langit membangun lapisan demi lapisan penghalang hitam pekat."
  },
  AvgDialog_142893_Content_57 = {
    Text = "Jawablah doa para Eksekutor-mu, hancurkan mereka menjadi abu!!!"
  },
  AvgDialog_142893_Content_58 = {
    Text = "Tidak ada lagi yang bisa membedakan suara gemuruh yang dalam dan tak terpahami itu dengan suara yang pernah menjadi milik Pontos."
  },
  AvgDialog_142893_Content_59 = {
    Text = "Mereka akhirnya menjadi satu seperti yang diinginkan."
  },
  AvgDialog_142893_Content_6 = {
    Text = "<Shake:<Red:Bukan begitu, kisah sang pemberani tidak seharusnya seperti ini.>>"
  },
  AvgDialog_142893_Content_60 = {
    Text = "Seiring dengan siulan tajam yang bergaung di sepanjang garis pantai, semua kaum fanatik berubah menjadi abu putih."
  },
  AvgDialog_142893_Content_62 = {
    Text = "Ah!... Kemudian? Paman Pontos, nenek moyang Kakek..."
  },
  AvgDialog_142893_Content_63 = {
    Text = "Vera yang menahan napas sepanjang cerita akhirnya tidak tahan untuk mengeluarkan seruan terkejut, air mata hampir memenuhi sudut matanya."
  },
  AvgDialog_142893_Content_64 = {
    Text = "Setelah itu, tidak peduli bagaimana aku mencoba mengingatnya, aku tidak bisa mengingat apa pun. Yang kuingat hanyalah..."
  },
  AvgDialog_142893_Content_66 = {
    Text = "Hiks hiks, Jaeger... Jaeger! Syukurlah, kau akhirnya sadar."
  },
  AvgDialog_142893_Content_67 = {
    Text = "Ayah, Bibi Leisa, semua orang, kota kita, semuanya... Huwaaaaaa!!"
  },
  AvgDialog_142893_Content_68 = {
    Text = "Dari cerita teman masa kecilmu, Olney, yang diselingi isak tangis, kau baru mengetahui bahwa seluruh kota telah musnah dalam sebuah ledakan besar."
  },
  AvgDialog_142893_Content_69 = {
    Text = "Hanya beberapa orang yang selamat dari reruntuhan, dikirim ke rumah kerabat atau teman di kota tetangga. Kau tertidur selama empat hari penuh."
  },
  AvgDialog_142893_Content_7 = {
    Text = "Yager, pejamkan matamu, ikuti aku!"
  },
  AvgDialog_142893_Content_70 = {
    Text = "Tidak, itu bukan ledakan, aku jelas-jelas ingat... Ugh! Kepalaku sakit sekali."
  },
  AvgDialog_142893_Content_71 = {
    Text = "White noise tajam di dalam kepalamu membuatmu kembali tertidur dalam keadaan setengah sadar. Saat terbangun lagi, kau mendapati dirimu berada dalam sebuah pelukan dengan kesadaran yang masih kabur."
  },
  AvgDialog_142893_Content_72 = {
    Text = "Mama... Mama?!"
  },
  AvgDialog_142893_Content_73 = {
    Text = "Jangan banyak bergerak, lukamu belum sembuh."
  },
  AvgDialog_142893_Content_74 = {
    Text = "Kau melihat dengan mata kepalamu sendiri bahwa Leisa, yang perutnya dirobek oleh para penganut fanatik, kini duduk di tepi tempat tidur tanpa luka sedikit pun. Kebahagiaan luar biasa membuatmu tiba-tiba membelalakkan mata dan meneteskan air mata."
  },
  AvgDialog_142893_Content_75 = {
    Text = "Mama! Apakah aku sedang bermimpi? Kamu baik-baik saja, kamu masih hidup!"
  },
  AvgDialog_142893_Content_76 = {
    Text = "Sst, dengarkan Mama, Jaeger. Mama harus meninggalkanmu, pergi ke tempat yang sangat jauh."
  },
  AvgDialog_142893_Content_77 = {
    Text = "Keluarga Olney akan menjagamu dengan baik. Besok pagi mereka akan menemukan cukup uang di atas meja. Kau harus hidup dengan baik."
  },
  AvgDialog_142893_Content_78 = {
    Text = "Tunggu, meninggalkanku? Mama, kenapa? Di mana Paman Pontos? Di mana dia?"
  },
  AvgDialog_142893_Content_79 = {
    Text = "Leisa tiba-tiba terdiam. Setelah beberapa saat, dia menggenggam tanganmu erat-erat, meletakkan kompas tembaga yang sempat kau jatuhkan ke tanganmu, lalu membungkuk dan mencium dahimu."
  },
  AvgDialog_142893_Content_8 = {
    Text = "Graor! Graor!"
  },
  AvgDialog_142893_Content_80 = {
    Text = "Jaeger, pegang ini baik-baik. Berjanjilah padaku, kau akan hidup dengan aman di suatu tempat."
  },
  AvgDialog_142893_Content_81 = {
    Text = "Kamu berusaha mati-matian untuk menggelengkan kepala, namun Leisa tidak memberimu kesempatan itu."
  },
  AvgDialog_142893_Content_82 = {
    Text = "Ingat, jangan pernah mencari aku dan Paman Pontos-mu, jangan pernah."
  },
  AvgDialog_142893_Content_83 = {
    Text = "Mama!……"
  },
  AvgDialog_142893_Content_84 = {
    Text = "Kamu tiba-tiba duduk tegak."
  },
  AvgDialog_142893_Content_85 = {
    Text = "Angin berhembus lembut melewati dedaunan, malam pun tiba tanpa terasa."
  },
  AvgDialog_142893_Content_86 = {
    Text = "Apakah itu Mimpi? Leisa tidak ada di sini, hanya Olney yang mengantuk menjagamu, terkejut dibuatnya."
  },
  AvgDialog_142893_Content_87 = {
    Text = "Yager?! Kamu kenapa?"
  },
  AvgDialog_142893_Content_88 = {
    Text = "Kamu menatap kosong ke luar jendela, bulan masih tergantung jauh di langit."
  },
  AvgDialog_142893_Content_89 = {
    Text = "Selain itu, tidak ada apa-apa lagi."
  },
  AvgDialog_142893_Content_9 = {
    Text = "Pontos melindungimu erat-erat sambil berlari menjauh dari garis pantai, kau memandang dengan kegelisahan ke arah api yang berkobar di mana-mana dan kerumunan yang dilanda kegilaan."
  },
  AvgDialog_145231_Content_1 = {Text = "BRAK—"},
  AvgDialog_145231_Content_10 = {
    Text = "Hari ini, aku tidak bisa memusatkan perhatianku pada pedang dan lawan."
  },
  AvgDialog_145231_Content_11 = {
    Text = "Ada sesuatu yang terus-menerus menjadi Gangguan di pikiranku."
  },
  AvgDialog_145231_Content_12 = {
    Text = "Sesuatu yang lain? Apa itu?"
  },
  AvgDialog_145231_Content_13 = {Text = "Kamu."},
  AvgDialog_145231_Content_14 = {
    Text = "¿¿¿??? Maksudmu…"
  },
  AvgDialog_145231_Content_15 = {
    Text = "Tepat. Thais si wanita gila itu, dan sungainya yang ikut-ikutan gila."
  },
  AvgDialog_145231_Content_16 = {
    Text = "Tidak apa-apa kalau sekali kalah dalam pertarungan, kamu istirahat dulu di sini, aku akan mencarikan obat untukmu…"
  },
  AvgDialog_145231_Content_18 = {
    Text = "Kamu ingin melarikan diri dari kamarmu, tapi Lotan tidak memberimu kesempatan itu."
  },
  AvgDialog_145231_Content_19 = {
    Text = "Dua suara Tusukan yang nyaring bergema di telingamu. Pedang besar Lotan menancap ke dalam ranjangmu, duri di gagangnya mengunci kedua tanganmu sehingga kamu tidak bisa bergerak."
  },
  AvgDialog_145231_Content_2 = {
    Text = "Suara benturan keras pintu yang ditendang terdengar bagai genderang perang. Sebuah sosok dengan bau amis darah di sekujur tubuhnya menerobos masuk ke kamarmu, duduk di atas ranjangmu sambil terengah-engah."
  },
  AvgDialog_145231_Content_20 = {
    Text = "Aku ke sini bukan untuk mengobati luka. Aku ke sini untuk menyelesaikan masalah. Dan kamu… adalah masalah itu."
  },
  AvgDialog_145231_Content_21 = {
    Text = "Hei! Lotan… kamu… kamu mau melakukan apa…"
  },
  AvgDialog_145231_Content_22 = {
    Text = "Aku tidak suka perasaan tidak bisa berkonsentrasi dalam pertarungan seperti ini. Ini membuatku sangat kesal."
  },
  AvgDialog_145231_Content_23 = {
    Text = "A, aku punya satu cara! Kamu bisa pergi menemui Thais… umm umm…"
  },
  AvgDialog_145231_Content_24 = {
    Text = "Sebuah tangan berbau amis Darah mencengkeram bagian bawah Wajahmu, membuat suara yang kamu keluarkan menjadi tidak jelas maknanya."
  },
  AvgDialog_145231_Content_25 = {
    Text = "Di kepalaku selain pertarungan, tidak pernah ada hal lain. Sesekali ada satu kali, ternyata juga tidak buruk…"
  },
  AvgDialog_145231_Content_26 = {
    Text = "Aku suka fokus melakukan satu hal. Entah itu bertarung, atau hal lainnya…"
  },
  AvgDialog_145231_Content_27 = {
    Text = "Lotan menatapmu, seperti sedang menatap seorang lawan yang bisa membuatnya sangat gembira, Niat Bertarung di Matanya sepenuhnya berubah menjadi Keserakahan yang tak terselubung."
  },
  AvgDialog_145231_Content_28 = {
    Text = "Karena kamu, aku mengalirkan begitu banyak Darah. Kamu harus membayar harganya. Bukan begitu?"
  },
  AvgDialog_145231_Content_29 = {
    Text = "Duri lancip di ujung jari baju besinya menyusuri garis rahangmu, melewati tenggorokan, melewati dada, melewati pinggang dan perut… Kamu berusaha keras untuk melepaskan diri, mulutmu mengeluarkan suku kata yang tidak jelas artinya, namun sepasang pedang besar itu tidak bergerak sedikit pun bagaikan batu karang."
  },
  AvgDialog_145231_Content_3 = {
    Text = "Ah! Siapa——"
  },
  AvgDialog_145231_Content_30 = {
    Text = "Lotan mendekat ke arahmu, menikmati Wajahmu yang memerah karena mengerahkan tenaga."
  },
  AvgDialog_145231_Content_31 = {
    Text = "Darah segar mengalir di sudut bibirnya yang tersenyum, menetes jatuh di Wajahmu."
  },
  AvgDialog_145231_Content_32 = {
    Text = "Berjuanglah sekuat tenaga. Biarkan aku melihat, apakah kamu bisa melarikan diri dari sini… \"lawan\"-ku."
  },
  AvgDialog_145231_Content_4 = {
    Text = "……Lotan? Kamu terluka?!!!"
  },
  AvgDialog_145231_Content_5 = {
    Text = "Kamu menatap sosok penuh luka di atas tempat tidur itu dengan tidak percaya."
  },
  AvgDialog_145231_Content_6 = {
    Text = "Hanya luka kecil, tidak masalah."
  },
  AvgDialog_145231_Content_7 = {
    Text = "Sebenarnya apa yang terjadi… siapa yang bisa melukaimu separah ini?"
  },
  AvgDialog_145231_Content_8 = {
    Text = "Seekor Cacing Laut Bintang, yang seharusnya mudah dikalahkan. Tapi hari ini…"
  },
  AvgDialog_145231_Content_9 = {
    Text = "Dia mengerutkan dahi, sekilas cahaya kesal melintas di matanya."
  },
  AvgDialog_14530_Content_10 = {
    Text = [[
Bibir terbuka dan tertutup, rasa asin samar menyebar.
Ini bukan hujan.]]
  },
  AvgDialog_14530_Content_11 = {
    Text = "<Gray:…Air mata?>"
  },
  AvgDialog_14530_Content_12 = {
    Text = "Seolah kotoran tersapu oleh air hujan, pemandangan di hadapanmu perlahan menjadi jelas."
  },
  AvgDialog_14530_Content_14 = {
    Text = "La… mona…"
  },
  AvgDialog_14530_Content_15 = {
    Text = "Panggilanmu terhenti mendadak."
  },
  AvgDialog_14530_Content_16 = {
    Text = "Tekanan dahsyat datang dari segala penjuru, gelombang hitam menelanmu."
  },
  AvgDialog_14530_Content_18 = {
    Text = "Jam berdetak, kicauan burung masuk melalui jendela yang setengah terbuka."
  },
  AvgDialog_14530_Content_19 = {
    Text = "Sisa rasa sesak membuatmu tak tahan untuk menepuk-nepuk dada. Kamu perlahan duduk, dan butuh beberapa saat sebelum benar-benar merasa sudah terbangun."
  },
  AvgDialog_14530_Content_2 = {
    Text = "Air Mata Bagai Hujan"
  },
  AvgDialog_14530_Content_20 = {
    Text = "<Gray:Sudah bermimpi aneh berkali-kali, tapi bermimpi tentang kematian sendiri baru pertama kali.>"
  },
  AvgDialog_14530_Content_21 = {
    Text = "Rasanya sangat aneh."
  },
  AvgDialog_14530_Content_22 = {
    Text = "Tapi cukup menarik juga."
  },
  AvgDialog_14530_Content_23 = {
    Text = "Kring kring——"
  },
  AvgDialog_14530_Content_24 = {
    Text = "Kamu mematikan alarm, berdiri dan meregangkan badan."
  },
  AvgDialog_14530_Content_25 = {
    Text = "Sudahlah, tidak usah dipikir, kalau tidak salah hari ini aku harus pergi ke——"
  },
  AvgDialog_14530_Content_26 = {
    Text = "Besok pukul 8 pagi akan diadakan latihan khusus, tempatnya di Ruang Kebangkitan, jangan terlambat."
  },
  AvgDialog_14530_Content_27 = {
    Text = "Ruang Kebangkitan? Apakah ini latihan yang berkaitan dengan kebangkitan?"
  },
  AvgDialog_14530_Content_28 = {
    Text = "Ini untuk menguji stabilitas <Yellow:Mistik Buatan>."
  },
  AvgDialog_14530_Content_29 = {Text = "Apa itu?"},
  AvgDialog_14530_Content_3 = {Text = "Jatuh."},
  AvgDialog_14530_Content_30 = {
    Text = "Sebuah proyek kecil yang selama ini kukerjakan, bisa juga dianggap sebagai hobi pribadi——memanfaatkan fungsi amplifikasi spiritual yang sudah ada pada perangkat kebangkitan, memperbesar kesadaran dan spiritual seseorang saat mereka tertidur."
  },
  AvgDialog_14530_Content_31 = {
    Text = "Secara teori, spiritual yang diperbesar hingga cukup besar dapat membentuk sebuah domain, dan domain yang sudah stabil dapat eksis secara independen dari dimensi realitas maupun dimensi spiritual."
  },
  AvgDialog_14530_Content_32 = {
    Text = "Domain seperti ini sangat mirip dengan <Yellow:Mistik>, makanya aku menyebutnya Mistik Buatan."
  },
  AvgDialog_14530_Content_33 = {
    Text = "Berbeda dengan Mistik alami yang terbentuk dari intrusi dimensi spiritual ke realitas, Mistik Buatan tidak bersifat agresif, lebih stabil dan terkendali, serta mampu <Yellow:mereproduksi \"periode waktu yang tidak ada di masa kini\">."
  },
  AvgDialog_14530_Content_34 = {
    Text = "\"Tidak ada di masa kini\"——maksudmu, ia bisa menampilkan ingatan seseorang?"
  },
  AvgDialog_14530_Content_35 = {
    Text = "Bisa <Yellow:menampilkan sebuah ingatan sesuai pemahaman pemilik spiritualnya>, dan lebih dari itu, ia juga memungkinkan orang lain memasuki ingatan tersebut."
  },
  AvgDialog_14530_Content_36 = {
    Text = "Seperti memasuki Mistik begitu……?"
  },
  AvgDialog_14530_Content_37 = {
    Text = "Lumayan juga pemahamanmu. Benar, setelah Mistik Buatan terbentuk, individu lain dapat memasuki di dalamnya secara fisik dan berinteraksi dengan kesadaran subjek spiritual——yaitu pemilik Mistik."
  },
  AvgDialog_14530_Content_38 = {
    Text = "Pada saat itu, apakah subjek spiritual mengenali pengunjungnya, dan sikap apa yang akan ditunjukkannya terhadap mereka……ha, menarik sekali kalau dipikir-pikir."
  },
  AvgDialog_14530_Content_39 = {
    Text = "Jika Mistik Buatan berhasil, ini akan menjadi cara terbaik bagi Investigator, Penjaga Rahasia, dan masing-masing Entitas Kebangkitan mereka untuk membangun keselarasan dan memperdalam pemahaman satu sama lain."
  },
  AvgDialog_14530_Content_4 = {
    Text = "Kamu sedang jatuh."
  },
  AvgDialog_14530_Content_40 = {
    Text = "Mengingat tatapan penuh semangat Doer, kamu merasa bulu kudukmu merinding."
  },
  AvgDialog_14530_Content_41 = {
    Text = "Katanya latihan khusus, tapi ini jelas-jelas jadi kelinci percobaan……\nSemoga hari ini tidak terjadi masalah apa pun."
  },
  AvgDialog_14530_Content_42 = {
    Text = "Kamu mengumpulkan semangat dan mendorong pintu di lorong bawah tanah."
  },
  AvgDialog_14530_Content_43 = {
    Text = "Sebelum kau sempat bereaksi, cahaya menyilaukan telah menelanmu sepenuhnya."
  },
  AvgDialog_14530_Content_5 = {
    Text = "Sensasi jatuh menarikmu, perlahan menyeret kesadaranmu keluar dari mimpi yang gelap gulita."
  },
  AvgDialog_14530_Content_6 = {
    Text = "Bayangan cahaya samar muncul di hadapanmu. Kamu terpana sesaat, lalu menyadari bahwa sepertinya kamu telah membuka mata."
  },
  AvgDialog_14530_Content_7 = {
    Text = "<Gray:Kenapa… tidak bisa melihat jelas…>"
  },
  AvgDialog_14530_Content_8 = {
    Text = "Setetes, dua tetes… cairan sejuk jatuh di dahimu, mengalir menuruni pipimu."
  },
  AvgDialog_14530_Content_9 = {Text = "Hujan…?"},
  AvgDialog_145510_Content_10 = {
    Text = "Di kaki pegunungan bersalju, sebuah pasar yang semrawut tumbuh dari tanah beku. Gubuk kayu, tenda, dan lapak sementara dari kulit yak berdesakan rapat di kedua sisi jalan pegunungan yang berlumpur."
  },
  AvgDialog_145510_Content_11 = {
    Text = "Benua Utara ini terlalu dingin, aku sedikit merindukan teh panas merah milik Nyonya Sylvia..."
  },
  AvgDialog_145510_Content_12 = {
    Text = "Meski terlalu dini untuk mengatakannya, begitu kita kembali ke Mythag, aku akan meminta Nyonya Sylvia untuk menyediakan teh merah panas dengan Siklus pasokan 24 jam untukmu."
  },
  AvgDialog_145510_Content_13 = {
    Text = "Sekarang, mari fokus pada tugas yang ada di depan kita."
  },
  AvgDialog_145510_Content_14 = {
    Text = "Kamu mengeluarkan brosur promosi yang sudah kusut terlipat di antara barang bawaan, lalu memutarnya menghadap Matahari untuk dibandingkan."
  },
  AvgDialog_145510_Content_15 = {
    Text = "Sambungan pegunungan yang dimulai dari tepi brosur itu tepat menyatu dengan siluet pegunungan di bawah langit yang mendung."
  },
  AvgDialog_145510_Content_16 = {
    Text = "Ya, inilah tempatnya, Hanya Saja entah bagaimana cara menemukan pemimpin misterius dengan tumpukan gelar yang lebih tinggi dari Gunung Everest itu..."
  },
  AvgDialog_145510_Content_17 = {
    Text = "<Shake:Dengarkan baik-baik, semuanya——>"
  },
  AvgDialog_145510_Content_18 = {
    Text = "Mengikuti arah suara Panggilan itu, seorang gadis berbaju putih berdiri sendiri di depan tenda di atas bukit kecil, memandang ke bawah pada kerumunan yang tersebar jarang."
  },
  AvgDialog_145510_Content_19 = {
    Text = "Aku adalah Eksekutor dari dewa tertinggi, Peri Sekte yang agung, Caraboo, penjelmaan Dewi Salju Umapati yang turun ke dunia manusia."
  },
  AvgDialog_145510_Content_2 = {
    Text = "Wilayah Salju"
  },
  AvgDialog_145510_Content_20 = {
    Text = "(Kenapa sedikit berbeda dari yang tertulis di brosur...)"
  },
  AvgDialog_145510_Content_21 = {
    Text = "Hei, kalau memang Dewi Salju, tunjukkan saja sihirnya kepada semua orang!"
  },
  AvgDialog_145510_Content_22 = {
    Text = "Taunt dari pria itu memancing beberapa tawa cekikikan yang tersebar."
  },
  AvgDialog_145510_Content_23 = {
    Text = "Tidak, aku belum bisa melakukannya sekarang."
  },
  AvgDialog_145510_Content_24 = {
    Text = "Gadis itu dengan santai mengeluarkan sebuah Apel merah ranum, lalu menggigitnya."
  },
  AvgDialog_145510_Content_25 = {
    Text = "Karena aku telah kehilangan tujuh artefak, itulah tujuh harta yang paling kucintai."
  },
  AvgDialog_145510_Content_26 = {
    Text = "Mereka adalah apel emas Eris, Yata no Kagami, bulu Maat, Kunci Solomon, mata Balor…"
  },
  AvgDialog_145510_Content_27 = {
    Text = "Artefak-artefakmu ini berasal dari peradaban yang cukup banyak dan beragam ya!"
  },
  AvgDialog_145510_Content_28 = {
    Text = "Kembali terdengar tawa riuh, namun gadis itu sama sekali tidak peduli."
  },
  AvgDialog_145510_Content_29 = {
    Text = "Lalu ada Benang Sutra Moira, dan Mahkota Ariadne."
  },
  AvgDialog_145510_Content_3 = {
    Text = [[
Kebohongan terbesar di dunia ini,
lahir dari mulut mereka yang tak pernah berbohong.]]
  },
  AvgDialog_145510_Content_30 = {
    Text = "Benang Sutra Moira… benang dari roda pemintal Dewi Takdir…"
  },
  AvgDialog_145510_Content_31 = {
    Text = "Jangan-jangan inilah yang dimaksud Arachne, \"nasib yang harus kita sambut\"?"
  },
  AvgDialog_145510_Content_32 = {
    Text = "Kamu mengeluarkan gulungan kecil Benang Sutra itu dari lapisan tersembunyi sakumu, Benang Sutra yang berkilau itu berpendar dengan warna-warna mengalir di ujung jarimu yang hampir tak tertangkap mata."
  },
  AvgDialog_145510_Content_33 = {
    Text = "Tunggu sebentar lagi, bertindaklah dengan hati-hati."
  },
  AvgDialog_145510_Content_34 = {
    Text = "Meskipun nasib telah menuntun kita ke sini, namun belum memberitahu kita peran apa yang dimainkan pemilik buku panduan ini dalam cerita ini."
  },
  AvgDialog_145510_Content_35 = {Text = "Huh, huh!"},
  AvgDialog_145510_Content_36 = {
    Text = "Jika sudah mengerti semuanya, tinggalkan persembahan kalian di sini!"
  },
  AvgDialog_145510_Content_37 = {
    Text = "Tidak kurang tidak lebih, Asalkan lima puluh Rose Scrip! Maka Dewi Salju Umapati akan merasakan ketulusan hati kalian!"
  },
  AvgDialog_145510_Content_38 = {
    Text = "Sebagai Dewi Salju, setelah aku mengumpulkan kembali tujuh artefak agung dan bangkit kembali di bawah bulan sabit, aku pasti akan membalas doa-doa kalian seribu kali lipat!"
  },
  AvgDialog_145510_Content_39 = {
    Text = "Bicara panjang lebar tidak karuan, ternyata ujung-ujungnya minta sumbangan!"
  },
  AvgDialog_145510_Content_4 = {
    Text = "-Ketinggian 4000 meter-"
  },
  AvgDialog_145510_Content_40 = {
    Text = "Sejak Dewi Salju menampakkan diri, rombongan yang datang mendaki gunung tidak kurang dari seribu, mana ada yang tidak membawa bekal sendiri."
  },
  AvgDialog_145510_Content_41 = {
    Text = "Orang sepertimu yang hanya ingin untung tanpa kerja, lebih baik pergi dari sini, belajarlah mewujudkan keinginan dengan tanganmu sendiri yang rajin!"
  },
  AvgDialog_145510_Content_42 = {
    Text = "Para penonton yang mengerumuni pun bubar berhamburan."
  },
  AvgDialog_145510_Content_43 = {
    Text = "Kamu memanfaatkan kesempatan itu untuk menerobos kerumunan dan mendekati gadis muda yang tampak murung itu, lalu bertanya kepadanya."
  },
  AvgDialog_145510_Content_44 = {
    Text = "Permisi… Saya ingin bertanya, apakah kamu yang mengirimkan brosur ini?"
  },
  AvgDialog_145510_Content_45 = {
    Text = "Kamu mengeluarkan brosur mencolok itu, mengetuk-ngetuk tulisan \"Pemimpin Agung, Orang yang Dipilih Dewa, Teman Dekat Raja Dewa\" di sana."
  },
  AvgDialog_145510_Content_46 = {
    Text = "Mata gadis itu seketika berbinar."
  },
  AvgDialog_145510_Content_47 = {
    Text = "<Shake:Ooo!! Kamu menerima buku rekrutmenku!>"
  },
  AvgDialog_145510_Content_48 = {
    Text = "Jadi, di mana dua belas rasul dan pengikutmu yang lain?"
  },
  AvgDialog_145510_Content_49 = {
    Text = "Soal itu, panjang ceritanya. Sekte agungku telah dikhianati oleh orang jahat, bahkan salah satu dari dua belas rasul ternyata menyimpan niat buruk, berambisi menguasai kemuliaan tertinggi seorang diri."
  },
  AvgDialog_145510_Content_5 = {
    Text = "Kami sudah tiba."
  },
  AvgDialog_145510_Content_50 = {
    Text = "Pengikut lainnya semua dipecah belah hingga bercerai-berai. Hanya tersisa aku, sang pemimpin, yang berjalan seorang diri dalam perjalanan panjang nan berat demi membangkitkan kembali sekte ini."
  },
  AvgDialog_145510_Content_51 = {
    Text = "Asalkan kalian mensponsori seribu Rose Scrip sekarang, kalian bisa menduduki posisi teratas sebagai Rasul Baru yang Pertama dari dua belas, menjadi murid utamaku…"
  },
  AvgDialog_145510_Content_52 = {
    Text = "Tapi tadi waktu kamu mengamen di jalanan, kamu bilang dirimu adalah Dewi Salju Umapati."
  },
  AvgDialog_145510_Content_53 = {
    Text = "Ini yang namanya di luar rumah, Identitas itu kita tentukan sendiri, begitu?"
  },
  AvgDialog_145510_Content_54 = {
    Text = "Hah, ketahuan."
  },
  AvgDialog_145510_Content_55 = {
    Text = "Gadis itu melompat, dalam dua tiga gerakan langsung bersembunyi di balik sebuah tenda dan menghilang."
  },
  AvgDialog_145510_Content_56 = {
    Text = "Saat kamu baru hendak mengejar gadis itu, tiba-tiba seseorang menepuk punggungmu."
  },
  AvgDialog_145510_Content_57 = {
    Text = "Dua tamu, apakah kalian datang untuk mendaki?"
  },
  AvgDialog_145510_Content_58 = {Text = "Eh, kami?"},
  AvgDialog_145510_Content_59 = {
    Text = "Iya, sekali lihat kalian berdua tampak luar biasa, bukan penduduk setempat, bukan?"
  },
  AvgDialog_145510_Content_6 = {
    Text = "Di sinilah pos perbekalan terakhir menuju Gunung Everest."
  },
  AvgDialog_145510_Content_60 = {
    Text = "Belakangan ini yang datang ke tanah tandus ini, siapa yang tidak datang demi dewi di puncak gunung yang bisa mengabulkan semua keinginan?"
  },
  AvgDialog_145510_Content_61 = {
    Text = "Kalian berdua tidak membawa banyak perlengkapan, sepertinya berencana menumpang perbekalan orang lain. Kebetulan sekali, bukan?"
  },
  AvgDialog_145510_Content_62 = {
    Text = "<Yellow:Namaku Naraka, aku adalah pemandu Sherpa setempat.>"
  },
  AvgDialog_145510_Content_63 = {
    Text = "Regu pendakian kami didanai oleh Yayasan Green, perbekalan sudah disiapkan, tinggal menunggu \"orang yang berjodoh\" untuk bersama-sama menuju puncak."
  },
  AvgDialog_145510_Content_64 = {
    Text = "Orang yang ditakdirkan?"
  },
  AvgDialog_145510_Content_65 = {
    Text = "Ya, aku sudah tinggal di bawah gunung salju ini selama bertahun-tahun. Siapa yang memiliki kemampuan untuk mencapai puncak—"
  },
  AvgDialog_145510_Content_66 = {
    Text = "Dia menunjuk ke matanya sendiri."
  },
  AvgDialog_145510_Content_67 = {
    Text = "Kedua mata ini bisa langsung melihatnya."
  },
  AvgDialog_145510_Content_68 = {
    Text = "Oh? Tidak ada salahnya ceritakan?"
  },
  AvgDialog_145510_Content_69 = {
    Text = "Pertama tentu saja usia yang tepat, tubuh yang kuat, dan Kekuatan mental yang stabil."
  },
  AvgDialog_145510_Content_7 = {
    Text = "Lebih jauh ke atas, kendaraan sudah tidak bisa melanjutkan perjalanan."
  },
  AvgDialog_145510_Content_70 = {
    Text = "Selain itu, yang lebih penting adalah keteguhan dan tekad untuk mencapai puncak — tekad untuk tidak menghembuskan napas terakhir asalkan belum sampai di puncak gunung."
  },
  AvgDialog_145510_Content_71 = {
    Text = "Baru menghembuskan napas setelah sampai di puncak — kedengarannya seperti kamu tidak berniat membiarkan kami turun hidup-hidup?"
  },
  AvgDialog_145510_Content_72 = {
    Text = "Hei, jangan berkata begitu. Setelah sampai di puncak dan bertemu Dewi Gunung Salju, semua keinginan bisa terwujud. Kalau sudah begitu, urusan kecil seperti turun gunung, masih perlu dikhawatirkan?"
  },
  AvgDialog_145510_Content_73 = {
    Text = "Ayo, ikuti aku ke kamp pendakian. Dijamin kalian puas."
  },
  AvgDialog_145510_Content_74 = {
    Text = "Kamu meminta pendapat William dengan tatapan matamu."
  },
  AvgDialog_145510_Content_75 = {
    Text = "Ayo pergi. Gadis tadi entah ke mana."
  },
  AvgDialog_145510_Content_76 = {
    Text = "Jika benar-benar ingin mendaki, pemandu lokal dan perlengkapan yang lengkap adalah hal yang tidak bisa diabaikan."
  },
  AvgDialog_145510_Content_77 = {
    Text = "Ayo, pergi lihat kamp."
  },
  AvgDialog_145510_Content_79 = {
    Text = "Suara nyanyian yang begitu indah…"
  },
  AvgDialog_145510_Content_8 = {
    Text = "Kamu mendorong pintu mobil, udara yang dipenuhi aroma harum teh mentega yang sedikit gosong, bau amis ternak, serta hawa dingin tipis dan segar khas dataran tinggi, dengan tak sabar menerobos masuk ke dalam hidungmu."
  },
  AvgDialog_145510_Content_80 = {
    Text = "Terasa familiar."
  },
  AvgDialog_145510_Content_81 = {
    Text = "Seolah mengalir turun dari galaksi yang jauh tak terhingga, namun juga seolah mengapung perlahan dari kedalaman Aequor yang tak bertepi."
  },
  AvgDialog_145510_Content_83 = {
    Text = "Suara nyanyian itu melayang dari arah kamp, helai demi helai, semakin jelas, bagaikan kabut tipis yang tersibak, memperlihatkan cahaya bulan purnama yang terang."
  },
  AvgDialog_145510_Content_85 = {
    Text = "Di tanah lapang di sisi kamp, seorang gadis berwajah penuh kesedihan bernyanyi dengan lantang."
  },
  AvgDialog_145510_Content_86 = {
    Text = "Semua orang yang lewat tanpa sadar memperlambat langkah mereka dan menahan napas — takut mengganggu suara yang mengalir bagai cahaya bulan itu."
  },
  AvgDialog_145510_Content_88 = {
    Text = "Hingga lagu berakhir, barulah dia keluar dari dunianya sendiri, lalu menemukan keberadaan kalian."
  },
  AvgDialog_145510_Content_89 = {
    Text = "Apakah ada anggota baru?"
  },
  AvgDialog_145510_Content_9 = {
    Text = "Langit berwarna abu-abu timah menggantung di ujung dunia. Deretan puncak pegunungan bersalju berdiri bagai barisan dewa-dewa yang diam, tegak di batas antara senja dan awan."
  },
  AvgDialog_145511_Content_1 = {
    Text = "Ada sesuatu yang tidak beres."
  },
  AvgDialog_145511_Content_10 = {
    Text = "Tidak, bukan hanya jubah, dari belakangnya, sesuatu yang lain pun ikut terangkat."
  },
  AvgDialog_145511_Content_11 = {
    Text = "Sepasang sayap."
  },
  AvgDialog_145511_Content_12 = {
    Text = "Sepasang sayap hitam——hitam yang pekat, dalam, dan membawa firasat buruk bagi setiap orang yang memandangnya."
  },
  AvgDialog_145511_Content_13 = {
    Text = "<BigShake:Dengan tubuh yang tak bisa binasa ini, kutangkis segala Bencana!>"
  },
  AvgDialog_145511_Content_14 = {
    Text = "Castor mengepakkan sayap, Salju di belakangnya meledak membentuk busur putih yang terang, hampir vertikal."
  },
  AvgDialog_145511_Content_15 = {
    Text = "Ia melompat dari lereng bersalju, melewati jarak yang dulu tak terjangkau——"
  },
  AvgDialog_145511_Content_16 = {
    Text = "Lalu menghantam masuk di antara wendigo itu dan Evelyn."
  },
  AvgDialog_145511_Content_17 = {
    Text = "Sayap terbentang, menopang diri di belakangnya menjadi sebuah penghalang besar yang gelap pekat."
  },
  AvgDialog_145511_Content_18 = {
    Text = "Mulut wendigo yang hendak mengatup itu menggigit sayap kanannya, mencabut selembar Bulu hingga ke akarnya."
  },
  AvgDialog_145511_Content_19 = {
    Text = "<Shake:Ugh!!>"
  },
  AvgDialog_145511_Content_2 = {
    Text = "Di sudut pandang mata, di pojok kawanan binatang buas, Wendigo yang paling tinggi dan paling kurus itu tidak pernah ikut bertarung sejak pertempuran dimulai."
  },
  AvgDialog_145511_Content_20 = {
    Text = "Castor mendengus pelan, namun ia tidak mundur."
  },
  AvgDialog_145511_Content_21 = {
    Text = "Jangan sia-siakan kesempatan yang diciptakan Castor, sekarang!"
  },
  AvgDialog_145511_Content_3 = {
    Text = "Ia menunggu, mengamati mata rantai terlemah dalam regu pendaki."
  },
  AvgDialog_145511_Content_4 = {
    Text = "Ia melewati kalian bertiga, lalu menerjang Evelyn dengan ganas."
  },
  AvgDialog_145511_Content_5 = {
    Text = "Evelyn——!"
  },
  AvgDialog_145511_Content_6 = {
    Text = "Caraboo terlalu jauh, saat ia berteriak, ia sudah tahu dirinya tidak akan sempat."
  },
  AvgDialog_145511_Content_7 = {
    Text = "——Tapi ada yang sempat."
  },
  AvgDialog_145511_Content_8 = {
    Text = "Castor berlari dengan cepat, mengulurkan tangan melepas tali pengikat jubahnya."
  },
  AvgDialog_145511_Content_9 = {
    Text = "Jubah itu berkibar-kibar di belakangnya——"
  },
  AvgDialog_145512_Content_1 = {
    Text = "Sudah selesai, pecundang."
  },
  AvgDialog_145512_Content_10 = {
    Text = "Apakah tuanmu berkata begini: sayang, kamu sudah bekerja keras, ini adalah hadiah atas pengorbananmu selama ini."
  },
  AvgDialog_145512_Content_11 = {
    Text = "Hanya Saja kamu perlu mendaki puncak gunung bersalju sendiri, mengusir para lawan, dan merebut kembali mahkotamu?"
  },
  AvgDialog_145512_Content_12 = {
    Text = "Sayang sekali, <BigShake:kamu——ter——ti——pu——deh——>"
  },
  AvgDialog_145512_Content_13 = {
    Text = "Pion selamanya hanyalah pion, dan pada saat yang diperlukan, akan menjadi pion yang dikorbankan."
  },
  AvgDialog_145512_Content_14 = {
    Text = "Ketika nilai yang bisa kamu berikan telah diperas habis, ketika kamu mulai merasa tidak puas… itulah saatnya kamu menyerahkan kepalamu."
  },
  AvgDialog_145512_Content_15 = {
    Text = "Sebagai salah satu dari tujuh Korban di altar, apakah ada kata-kata terakhir yang ingin kamu sampaikan?"
  },
  AvgDialog_145512_Content_16 = {
    Text = "Tidak seharusnya……tidak seharusnya mempercayai siapa pun……"
  },
  AvgDialog_145512_Content_17 = {
    Text = "Dari awal, mempercayai perhatian Nyonya itu……Kemudian……merindukan balas dendam sesama bangsa……"
  },
  AvgDialog_145512_Content_18 = {
    Text = "Hingga saat ini, digerakkan oleh janji seseorang……"
  },
  AvgDialog_145512_Content_19 = {
    Text = "Sudah sudah, memberimu waktu untuk menyampaikan kata-kata terakhir hanyalah basa-basi, tidak ada yang benar-benar peduli dengan hidupmu yang menyedihkan dan gagal itu."
  },
  AvgDialog_145512_Content_2 = {
    Text = "Caraboo melangkah melewati Helot yang berlutut di tanah, lalu dengan lembut mengambil bola mata dari atas formasi sihir itu."
  },
  AvgDialog_145512_Content_20 = {
    Text = "Hal yang tidak bisa kamu menangkan sendiri, ya tinggal dicuri, ditipu, atau dirampas, apa gunanya hanya menunggu orang lain memberi sedekah."
  },
  AvgDialog_145512_Content_21 = {
    Text = "Waktu yang tersisa tidak cukup, perenungan sisanya, tunggu saja sampai kehidupan berikutnya untuk dilanjutkan."
  },
  AvgDialog_145512_Content_22 = {
    Text = "Caraboo mengangkat tangan dan melempar pelan, bola mata itu masuk ke dalam tubuh Helot."
  },
  AvgDialog_145512_Content_23 = {
    Text = "Setelah itu, terdengar suara krek krek, suara Makan."
  },
  AvgDialog_145512_Content_24 = {
    Text = "Makanlah, makanlah."
  },
  AvgDialog_145512_Content_25 = {
    Text = "Tubuh Helot segera runtuh, meninggalkan genangan lumpur berwarna Darah."
  },
  AvgDialog_145512_Content_26 = {
    Text = "Tepat sekali, begitulah, mereka akan memakan Kamu, hingga tidak tersisa tulang pun……"
  },
  AvgDialog_145512_Content_27 = {
    Text = "Kamu mengintip semacam kesenangan kejam dari Wajah Caraboo."
  },
  AvgDialog_145512_Content_28 = {
    Text = "Lihatlah, akibat tragismu semua bersumber dari kebodohanmu, bersumber dari mudahnya Kamu mempercayai Kebohongan."
  },
  AvgDialog_145512_Content_29 = {Text = "Caraboo…"},
  AvgDialog_145512_Content_3 = {
    Text = "Keinginanmu pun akan menjadi pupuk yang menyuburkan gunung bersalju."
  },
  AvgDialog_145512_Content_30 = {
    Text = "Hmm? Ada apa?"
  },
  AvgDialog_145512_Content_31 = {
    Text = "Dia berbalik, mengamati ekspresi wajahmu."
  },
  AvgDialog_145512_Content_32 = {
    Text = "Dia menampilkan sikap manja yang biasa, namun Kamu tetap bisa membaca kebencian Tersembunyi-nya dari secercah keangkuhan di sudut Mata-nya."
  },
  AvgDialog_145512_Content_33 = {
    Text = "Bolehkah aku melihat keenam artefak itu?"
  },
  AvgDialog_145512_Content_34 = {
    Text = "Tentu saja bisa!"
  },
  AvgDialog_145512_Content_35 = {
    Text = "Caraboo melangkah ke samping, memberikan posisi yang langsung menghadap formasi sihir itu kepadamu."
  },
  AvgDialog_145512_Content_36 = {
    Text = "Benang Sutra Moira, hadiah dari Arachne."
  },
  AvgDialog_145512_Content_37 = {
    Text = "Yata no Kagami, ditemukan di tepi danau es tempat Tinct berkeliaran."
  },
  AvgDialog_145512_Content_38 = {
    Text = "Bulu Maat, jatuh melayang dari Salju dan Angin Setelah Castor pergi."
  },
  AvgDialog_145512_Content_39 = {
    Text = "Mata Balor, membeku di dalam genangan Darah Helot."
  },
  AvgDialog_145512_Content_4 = {
    Text = "Bola mata itu tiba-tiba berubah menjadi mengerikan, pupil merah menyala melebar memancarkan cahaya Darah."
  },
  AvgDialog_145512_Content_40 = {
    Text = "Apel Emas, entah dari bungkusan mana Caraboo mengeluarkannya."
  },
  AvgDialog_145512_Content_41 = {
    Text = "Kunci Solomon, sebenarnya adalah Kunci Perak yang selalu kamu bawa."
  },
  AvgDialog_145512_Content_42 = {
    Text = "Dan juga, yang ditemukan oleh tim ekspedisi sebelumnya, Mahkota Ariadne…"
  },
  AvgDialog_145512_Content_43 = {
    Text = "Kamu terkejut."
  },
  AvgDialog_145512_Content_44 = {
    Text = "Mahkota Ariadne… Mahkota Ariadne macam apa ini, bukankah ini <Yellow:Mahkota Tulu>!"
  },
  AvgDialog_145512_Content_45 = {
    Text = "Ada apa yang perlu diherankan? Apel Emas pun tidak berwarna emas, bukan?"
  },
  AvgDialog_145512_Content_46 = {
    Text = "Tapi, mengapa Mahkota Tulu bisa ada di sini?"
  },
  AvgDialog_145512_Content_47 = {
    Text = "Karena, ini adalah artefak-Nya, persembahan untuk-Nya, bahan makanan favorit-Nya."
  },
  AvgDialog_145512_Content_48 = {
    Text = "Seiring kata-kata Caraboo jatuh ke tanah, Bumi tiba-tiba berguncang."
  },
  AvgDialog_145512_Content_49 = {
    Text = "Apa yang terjadi?"
  },
  AvgDialog_145512_Content_5 = {
    Text = "Tidak, bagaimana bisa…!"
  },
  AvgDialog_145512_Content_50 = {
    Text = "Dia sedang tertawa!"
  },
  AvgDialog_145512_Content_51 = {
    Text = "…Tertawa?"
  },
  AvgDialog_145512_Content_52 = {
    Text = "Puncak gunung berguncang berulang kali, seolah-olah Satu Orang gadis muda yang sedang tertawa melihat sesuatu yang lucu, tertawa hingga tubuhnya bergetar."
  },
  AvgDialog_145512_Content_53 = {
    Text = "Salju yang menumpuk berjatuhan."
  },
  AvgDialog_145512_Content_54 = {
    Text = "Puncak tajam itu bukanlah pegunungan, melainkan cacing raksasa yang bercokol di atas puncak gunung, bagaikan ular besar yang mampu menelan langit dan bumi."
  },
  AvgDialog_145512_Content_55 = {
    Text = "Karena kelemahan manusia yang tidak mampu menghadapi kenyataan, mereka memilih untuk mempercayai Kebohongan, menitipkan harapan kepada Dewa yang ada di dalam Void."
  },
  AvgDialog_145512_Content_56 = {
    Text = "Mereka tidak pernah terpikirkan — bahwa Dewa yang disebut-sebut itu pun bisa berbohong. Karena Dewa pun memiliki keinginan yang ingin mereka wujudkan."
  },
  AvgDialog_145512_Content_57 = {
    Text = "Keinginan Dewa adalah — memakan mereka."
  },
  AvgDialog_145512_Content_58 = {
    Text = "Mahkota, Benang Sutra, Kunci Perak, buah terlarang, bulu terbang, cermin terang, Mata sihir. Tujuh artefak, adalah Korban yang dijadikan dari HP oleh orang-orang Keserakahan ini."
  },
  AvgDialog_145512_Content_59 = {
    Text = "Segalanya milik kalian, tidak lebih dari satu kali makan kenyang bagi-Nya."
  },
  AvgDialog_145512_Content_6 = {
    Text = "Mata Balor, mata iblis sang dewa jahat. Mampu menghancurkan segalanya yang dipandangnya, namun juga merupakan satu-satunya kelemahan-Nya."
  },
  AvgDialog_145512_Content_60 = {
    Text = "Sekarang, Dia telah mendapatkan apa yang Dia inginkan, tentu saja Dia harus tertawa!"
  },
  AvgDialog_145512_Content_61 = {
    Text = "Sudah sampai di sini, sudah saatnya kamu berkata jujur kepada kami, bukan?"
  },
  AvgDialog_145512_Content_62 = {
    Text = "Kamu sama sekali tidak seperti yang kamu perankan, seolah hanya ikut-ikutan dalam perjalanan ini."
  },
  AvgDialog_145512_Content_63 = {
    Text = "Lebih tepatnya, seluruh regu pendaki ini berjalan sampai sejauh ini di bawah arahanmu."
  },
  AvgDialog_145512_Content_64 = {
    Text = "Pertemuan tak terduga di gua pertama dengan Castor, pilihan Tinct untuk memandang danau es dari kejauhan…"
  },
  AvgDialog_145512_Content_65 = {
    Text = "Dan juga Helot yang terus mengikuti kami ini, sebenarnya kamu sudah memprediksi segalanya sejak lama."
  },
  AvgDialog_145512_Content_66 = {
    Text = "Sebenarnya, siapa kamu?"
  },
  AvgDialog_145512_Content_7 = {
    Text = "Apakah tuanmu tidak memberitahumu? Bola mata ini, hanya dengan direndam Darahmu, barulah layak disebut \"Mata Balor\"."
  },
  AvgDialog_145512_Content_8 = {
    Text = "Dia berkata…"
  },
  AvgDialog_145512_Content_9 = {
    Text = "Ssst, biarkan aku menebaknya."
  },
  AvgDialog_145513_Content_1 = {
    Text = "Aliansi Kebohongan"
  },
  AvgDialog_145513_Content_10 = {
    Text = "<Yellow:Kamu yang membakar paketku kan>? Lihat saja, aku akan membongkar topeng manusia makhluk ini—"
  },
  AvgDialog_145513_Content_11 = {
    Text = "Dia mencengkeram pipi Naraka dengan erat, menariknya ke dua sisi."
  },
  AvgDialog_145513_Content_12 = {
    Text = "<Shake:Hei——>"
  },
  AvgDialog_145513_Content_13 = {
    Text = "Sreet——"
  },
  AvgDialog_145513_Content_14 = {
    Text = "Tubuh yang bernama \"Naraka\" itu, bagaikan boneka karet di tangan anak nakal, dirobek menjadi dua bagian."
  },
  AvgDialog_145513_Content_15 = {
    Text = "Yang mengalir deras dari celah retakan itu adalah asap hitam bernama \"Chaos\"."
  },
  AvgDialog_145513_Content_16 = {
    Text = "Asap itu bergolak, melingkar, mengeras, lalu dengan genit mengulurkan setangkai mawar."
  },
  AvgDialog_145513_Content_17 = {
    Text = "Bertemu lagi, kawan lama."
  },
  AvgDialog_145513_Content_18 = {
    Text = "Sebelum bernostalgia, mari kita lakukan pemanasan terlebih dahulu untuk menenangkan si penipu kecil kita yang sedang marah-marah itu?"
  },
  AvgDialog_145513_Content_2 = {
    Text = "Di ujung Benang Sutra, seorang gadis melangkah keluar dari kegelapan."
  },
  AvgDialog_145513_Content_3 = {
    Text = "Hei, penipu kecil, kamu ikut mengorbankan dirimu sendiri juga?"
  },
  AvgDialog_145513_Content_4 = {
    Text = "Kata-kata Naraka membuat gadis yang sudah murung itu semakin marah."
  },
  AvgDialog_145513_Content_5 = {
    Text = "Kamu enak saja."
  },
  AvgDialog_145513_Content_6 = {
    Text = "Caraboo mendongak, sepasang matanya yang penuh amarah menatap tajam ke arah Naraka."
  },
  AvgDialog_145513_Content_7 = {
    Text = "Jangan pura-pura, seorang pemandu Sherpa, ditelan ke dalam perut gunung, masih sempat-sempatnya bercanda?"
  },
  AvgDialog_145513_Content_8 = {
    Text = "Sejak pertama kali aku melihatmu, aku sudah tahu, kamu ini juga seorang penipu."
  },
  AvgDialog_145513_Content_9 = {
    Text = "Caraboo menerjang maju. Kali ini, dia tidak membiarkan Naraka menghindar."
  },
  AvgDialog_145514_Content_1 = {
    Text = "Wendigo terakhir itu, lenyap di bawah bayangan Castor."
  },
  AvgDialog_145514_Content_10 = {
    Text = "Mungkin hubungan antar manusia memang dimulai dari mengungkapkan sebuah rahasia kecil, bukan?"
  },
  AvgDialog_145514_Content_11 = {
    Text = "Tanpa disadari, Caraboo mendekat dan dengan senyum lebar mengucapkan apa yang ada di dalam pikiranmu."
  },
  AvgDialog_145514_Content_12 = {
    Text = "Bertukar rahasia bukanlah hal yang satu arah."
  },
  AvgDialog_145514_Content_13 = {
    Text = "Bibi Rosa yang sudah kamu panggil berkali-kali itu, apakah orang yang sangat penting bagimu?"
  },
  AvgDialog_145514_Content_14 = {
    Text = "Tentu saja itu karanganku. Masa kamu percaya sungguhan?"
  },
  AvgDialog_145514_Content_15 = {
    Text = "Hehe, menipu orang bodoh itu biasa, tapi menipu kamu itu tidak mudah."
  },
  AvgDialog_145514_Content_16 = {
    Text = "Membuat Wendigo percaya bahwa kamu telah tersihir jauh lebih sulit daripada menipuku."
  },
  AvgDialog_145514_Content_17 = {
    Text = "Mereka bisa mendengar suara di dalam hatimu, lalu mengulangnya kembali melalui angin."
  },
  AvgDialog_145514_Content_18 = {
    Text = "Lalu siapa yang tahu? Mungkin dewi salju di gunung itu menyimpan terlalu banyak cerita di hatinya, sehingga setiap cerita terasa nyata?"
  },
  AvgDialog_145514_Content_19 = {
    Text = "Caraboo dengan ringan mengelak menggunakan candaan."
  },
  AvgDialog_145514_Content_2 = {
    Text = "Kemudian angin yang berhembus melewati telinga tiba-tiba menjadi jernih. Angin itu tidak lagi membawa suara apapun."
  },
  AvgDialog_145514_Content_20 = {
    Text = "Karena kamu tidak mau bercerita, kami tentu tidak akan memaksamu."
  },
  AvgDialog_145514_Content_21 = {
    Text = "Tapi ketulusan adalah sesuatu yang sangat berharga, bahkan jika kamu seorang penipu sekalipun, sebaiknya jangan biarkan harapan semua orang berakhir sia-sia."
  },
  AvgDialog_145514_Content_22 = {
    Text = "Ini adalah saran tulusku, terserah kamu mau mendengarnya atau tidak."
  },
  AvgDialog_145514_Content_23 = {
    Text = "Setelah William selesai berbicara, ia bergegas menuju bagian depan rombongan."
  },
  AvgDialog_145514_Content_24 = {Text = "Apa sih."},
  AvgDialog_145514_Content_25 = {
    Text = "{Male=恩公,Female=恩人}, kamu pasti tidak akan sekurang ajar seperti dia, kan?"
  },
  AvgDialog_145514_Content_26 = {
    Text = "Aku dan William bertempur bahu-membahu dalam waktu yang lama, ia bukan orang yang suka berbicara berlebihan."
  },
  AvgDialog_145514_Content_27 = {
    Text = "Dalam ingatanku, setiap saran yang pernah dia berikan, semuanya efektif."
  },
  AvgDialog_145514_Content_28 = {
    Text = "<Shake:Huhu, {Male=恩公,Female=恩人}, kamu juga sangat dingin……>"
  },
  AvgDialog_145514_Content_29 = {
    Text = "Caraboo berpura-pura sedih lalu pergi, sementara kamu mengejar William yang sedang berbincang dengan Naraka."
  },
  AvgDialog_145514_Content_3 = {
    Text = "Keheningan berarti keamanan, namun keamanan itu justru membuat hati terasa hampa."
  },
  AvgDialog_145514_Content_30 = {
    Text = "Dia memberi isyarat dengan matanya agar kamu mundur beberapa langkah, sampai orang-orang di sisi itu tidak bisa mendengar Bisikan kalian."
  },
  AvgDialog_145514_Content_31 = {
    Text = "Pertarungan melawan Wendigo tadi, apakah kamu merasa ada yang aneh?"
  },
  AvgDialog_145514_Content_32 = {Text = "Ke mana?"},
  AvgDialog_145514_Content_33 = {Text = "Naraka."},
  AvgDialog_145514_Content_34 = {
    Text = "Coba kamu ingat kembali, dari suara-suara yang terdengar dari Angin, hingga Wendigo muncul, hingga pengepungan tadi—"
  },
  AvgDialog_145514_Content_35 = {
    Text = "Naraka, apakah ada, di satu momen pun, Wendigo mana pun yang mendekatinya?"
  },
  AvgDialog_145514_Content_36 = {
    Text = "Caraboo diserang Wendigo saat berpura-pura menjadi korban, Evelyn diterjang oleh Wendigo yang paling tinggi, Castor digigit hingga selembar Bulu-nya terlepas…"
  },
  AvgDialog_145514_Content_37 = {
    Text = "Termasuk saat sebelumnya ketika terperdaya oleh Wendigo, sepertinya Naraka juga tidak terpengaruh sama sekali."
  },
  AvgDialog_145514_Content_38 = {
    Text = "Maksudmu adalah..."
  },
  AvgDialog_145514_Content_39 = {
    Text = "Aku tidak bermaksud apa-apa."
  },
  AvgDialog_145514_Content_4 = {
    Text = "Evelyn melirik sayap Castor, namun ekspresinya tetap biasa saja, seolah-olah setiap orang di dunia ini menyembunyikan sepasang sayap adalah hal yang wajar."
  },
  AvgDialog_145514_Content_40 = {
    Text = "Masih empat atau lima hari perjalanan ke atas, kita tidak punya pemandu lain yang bisa diganti."
  },
  AvgDialog_145514_Content_41 = {
    Text = "Aku berharap aku terlalu khawatir, tapi kita harus tetap waspada."
  },
  AvgDialog_145514_Content_42 = {
    Text = "Sepanjang Jalan ini, Kita sudah kehilangan satu Tinct. Aku tidak ingin karena kelalaianku, ada orang lain yang tertinggal di gunung ini."
  },
  AvgDialog_145514_Content_43 = {
    Text = "Angin berhembus memutar dari tepi luar punggung bukit berbatu."
  },
  AvgDialog_145514_Content_44 = {
    Text = "Melewati sosok yang berjongkok mengetuk es di kejauhan."
  },
  AvgDialog_145514_Content_45 = {
    Text = "Ujung beliung Naraka mengetuk serpihan es di sol sepatu, mengeluarkan suara yang stabil seperti bandul jam."
  },
  AvgDialog_145514_Content_46 = {
    Text = "-Ketinggian 6500 meter-"
  },
  AvgDialog_145514_Content_5 = {
    Text = "Biar aku yang membalut lukamu."
  },
  AvgDialog_145514_Content_6 = {
    Text = "Maaf… sudah menyembunyikan hal ini selama ini."
  },
  AvgDialog_145514_Content_7 = {
    Text = "Tidak apa-apa. Kita semua datang untuk mencari Keajaiban luar biasa setingkat kebangkitan orang mati… Menemukan keberadaan yang melanggar akal sehat di saat seperti ini justru adalah kabar baik."
  },
  AvgDialog_145514_Content_8 = {
    Text = "Lagipula, jubahmu itu bahkan tidak mau kamu lepas saat tidur, semua orang tahu kamu menyimpan rahasia."
  },
  AvgDialog_145514_Content_9 = {
    Text = "Meski terdengar seperti keluhan, kamu jelas merasakan bahwa setelah pertempuran ini semua orang Mulai membuka diri dan menjadi lebih akrab satu sama lain."
  },
  AvgDialog_145515_Content_1 = {
    Text = "Tujuh Takdir"
  },
  AvgDialog_145515_Content_10 = {
    Text = "<Shake:Lihat ke sana — !>"
  },
  AvgDialog_145515_Content_11 = {
    Text = "Belum selesai bicara, dia sudah berlari menuju lereng landai di sisi lainnya."
  },
  AvgDialog_145515_Content_12 = {
    Text = "Itu adalah sebuah altar bersegi enam."
  },
  AvgDialog_145515_Content_13 = {
    Text = "Di tengah altar, sudah terdapat sebuah Mahkota yang diletakkan di sana."
  },
  AvgDialog_145515_Content_14 = {
    Text = "Wanita yang dibelenggu rantai itu menghitung harta rampasan yang telah diambilnya. %player%Kunci Perak dan Benang Sutra di dalam saku, cermin, Helaian Bulu Onyx, dan Apel emas di dalam bungkusan Caraboo."
  },
  AvgDialog_145515_Content_15 = {
    Text = "Bola mata Balor?"
  },
  AvgDialog_145515_Content_16 = {
    Text = "Helot mendengus, lalu menancapkan kukunya yang tajam ke dalam bola rantai di sisinya."
  },
  AvgDialog_145515_Content_17 = {
    Text = "Plak, bola rantai itu mengeluarkan suara aneh yang kental."
  },
  AvgDialog_145515_Content_18 = {
    Text = "Dia mengaduk, menggali… hingga berhasil mengeluarkan sebuah bola mata berdarah dari dalamnya."
  },
  AvgDialog_145515_Content_19 = {
    Text = "Semuanya sudah kuberikan untukmu, makhluk rakus."
  },
  AvgDialog_145515_Content_2 = {
    Text = "-Ketinggian 8800 Meter-"
  },
  AvgDialog_145515_Content_20 = {
    Text = "Dia meletakkan keenam benda berharga itu masing-masing di sudut altar."
  },
  AvgDialog_145515_Content_21 = {
    Text = "Sekarang, saatnya keinginanku terwujud."
  },
  AvgDialog_145515_Content_22 = {
    Text = "Dia memejamkan mata, diam dalam keheningan."
  },
  AvgDialog_145515_Content_23 = {
    Text = "Bangkitkanlah dia… biarkan aku membunuh musuhku dengan tanganku sendiri, wujudkanlah dendamku yang sudah lama terpendam."
  },
  AvgDialog_145515_Content_24 = {
    Text = "Angin dingin berhembus melewati puncak Wilayah Salju. Permohonannya tidak mendapat respons apa pun."
  },
  AvgDialog_145515_Content_25 = {
    Text = "Mengapa? Bukankah aku sudah menyerahkan tujuh persembahan kepadamu?"
  },
  AvgDialog_145515_Content_26 = {
    Text = "Suara protes Helot Gaung di antara puncak-puncak gunung yang jauh, memicu longsoran salju kecil yang berulang-ulang."
  },
  AvgDialog_145515_Content_27 = {
    Text = "Karena, ada persembahan yang palsu, bukan?"
  },
  AvgDialog_145515_Content_28 = {Text = "Siapa?!"},
  AvgDialog_145515_Content_29 = {
    Text = "Caraboo melompat-lompat dengan ringan melangkah maju, Seolah-olah sama sekali tidak menganggap Helot ada."
  },
  AvgDialog_145515_Content_3 = {
    Text = "Ini adalah tempat yang belum pernah dijejaki oleh manusia."
  },
  AvgDialog_145515_Content_30 = {
    Text = "Kalian ini, hanya memikirkan keinginan kalian sendiri, tapi tidak pernah memikirkan persembahan apa yang benar-benar diinginkan Dewa."
  },
  AvgDialog_145515_Content_31 = {
    Text = "Apel Emas, Apel Emas, masa kamu mengira Asalkan itu Apel berwarna emas, berarti sudah memilih yang benar?"
  },
  AvgDialog_145515_Content_32 = {
    Text = "Dia mengangkat Apel Emas dari altar dan menggigitnya pelan."
  },
  AvgDialog_145515_Content_33 = {
    Text = "Hmm hmm, memang benar itu kamu."
  },
  AvgDialog_145515_Content_34 = {
    Text = "Kertas timah berwarna emas pun terkelupas, memperlihatkan wujud aslinya."
  },
  AvgDialog_145515_Content_35 = {
    Text = "Camilan, permen, cokelat cair, sebut saja apa pun, pokoknya ini adalah cokelat yang paling biasa dari yang biasa."
  },
  AvgDialog_145515_Content_36 = {
    Text = "<BigShake:Ciang ciang! Berkat sang peri, kelezatan tiada tara!>"
  },
  AvgDialog_145515_Content_37 = {
    Text = "Kamu ini… penipu…"
  },
  AvgDialog_145515_Content_38 = {
    Text = "Perampok juga tidak lebih baik dari penipu, bukan?"
  },
  AvgDialog_145515_Content_39 = {
    Text = "Jangan banyak bicara, serahkan Apel Emas yang asli!"
  },
  AvgDialog_145515_Content_4 = {
    Text = "Berdiri di puncak gunung bersalju, memandang jauh ke pegunungan yang tertutup salju putih, yang Gaung di dalam dada, ternyata bukanlah rasa Pencapaian karena telah mencapai puncak."
  },
  AvgDialog_145515_Content_40 = {
    Text = "Kalau begitu, kamu harus tanya dulu apakah mereka setuju."
  },
  AvgDialog_145515_Content_41 = {
    Text = "Caraboo memiringkan tubuhnya, regu pendaki gunung itu sedang mendaki melewati tebing terakhir."
  },
  AvgDialog_145515_Content_5 = {
    Text = "Melainkan Ketakutan."
  },
  AvgDialog_145515_Content_6 = {
    Text = "Ketakutan karena jauh dari dunia manusia, Ketakutan karena terpisah dari hal-hal yang sudah dikenal."
  },
  AvgDialog_145515_Content_7 = {
    Text = "Di sini tidak ada lagi puncak yang lebih tinggi, yang bisa dilakukan oleh mereka yang telah mencapai puncak hanyalah berlutut menyembah langit."
  },
  AvgDialog_145515_Content_8 = {
    Text = "Teman-teman, kita telah mencapai puncak."
  },
  AvgDialog_145515_Content_9 = {
    Text = "Di antara regu pendaki, hanya satu orang yang sama sekali tidak terguncang oleh pemandangan di puncak gunung."
  },
  AvgDialog_145516_Content_1 = {Text = "Pelopor"},
  AvgDialog_145516_Content_10 = {
    Text = "Ternyata, masih kurang <Blue:Kunci Solomon> dan <Blue:Mata Balor>."
  },
  AvgDialog_145516_Content_11 = {
    Text = "Caraboo menghitung dengan jari-jarinya, bergumam pelan."
  },
  AvgDialog_145516_Content_12 = {
    Text = "Menurutmu, apakah Mata Balor juga akan jatuh dari langit tiba-tiba seperti Bulu Maat?"
  },
  AvgDialog_145516_Content_13 = {
    Text = "Lelucon ini sama sekali tidak lucu."
  },
  AvgDialog_145516_Content_14 = {
    Text = "Kamu tidak tahu apa yang terjadi pada Castor, tapi aroma dirinya masih tersisa pada bulu hitam pekat itu."
  },
  AvgDialog_145516_Content_15 = {
    Text = "Sudah tidak jauh lagi di depan."
  },
  AvgDialog_145516_Content_16 = {
    Text = "Sebelum mencapai puncak, kita tidak boleh berbalik."
  },
  AvgDialog_145516_Content_17 = {
    Text = "William menepuk bahumu. Jelas, dia tahu apa yang sedang kamu pikirkan."
  },
  AvgDialog_145516_Content_18 = {
    Text = "Tahukah kamu? Aku punya firasat."
  },
  AvgDialog_145516_Content_19 = {
    Text = "Castor pasti telah menemukan sesuatu yang ingin ia kejar, itulah mengapa ia meninggalkan tim."
  },
  AvgDialog_145516_Content_2 = {
    Text = "Ini adalah titik istirahat terakhir sebelum pendakian puncak."
  },
  AvgDialog_145516_Content_20 = {
    Text = "Dan, jika itu dia, pasti bisa mewujudkan keinginannya."
  },
  AvgDialog_145516_Content_21 = {
    Text = "Evelyn sedikit berdehem, seolah ingin memberi lebih banyak bobot pada kata-katanya, lalu menambahkan."
  },
  AvgDialog_145516_Content_22 = {
    Text = "Asalkan seseorang hidup cukup lama, ia bisa melihat secara diam-diam arah nasib orang lain bahkan dari pertemuan yang singkat."
  },
  AvgDialog_145516_Content_23 = {
    Text = "Pada diri Castor, apa yang kamu lihat?"
  },
  AvgDialog_145516_Content_24 = {
    Text = "Kesederhanaan, dan ketangguhan."
  },
  AvgDialog_145516_Content_25 = {
    Text = [[
Hingga ia mendapatkan satu-satunya jawaban itu, ia tidak akan berhenti.
Tidak akan ragu, dan tidak akan menyerah.]]
  },
  AvgDialog_145516_Content_26 = {
    Text = "Lalu bagaimana denganmu, Evelyn? Di mana jawabanmu?"
  },
  AvgDialog_145516_Content_27 = {
    Text = "Ada di atas gunung."
  },
  AvgDialog_145516_Content_28 = {
    Text = "Kebetulan sekali, kita searah!"
  },
  AvgDialog_145516_Content_29 = {
    Text = "Caraboo entah dari mana mengeluarkan sebuah Apel lagi, melemparnya ke atas lalu menangkapnya."
  },
  AvgDialog_145516_Content_3 = {
    Text = "Memandang ke pegunungan jauh, di bawah kaki terbentang hamparan salju yang luas, menghilang ke cakrawala yang jauh di antara kabut lembah."
  },
  AvgDialog_145516_Content_30 = {
    Text = "Jika semuanya sudah siap, mari Mulai etape terakhir."
  },
  AvgDialog_145516_Content_31 = {
    Text = "Jangan lengah. Banyak kejadian tak terduga terjadi di seribu meter terakhir."
  },
  AvgDialog_145516_Content_32 = {
    Text = "Di hadapan kalian menjulang sebuah dinding es yang hampir vertikal."
  },
  AvgDialog_145516_Content_33 = {
    Text = "Naraka mengayunkan kapak es, ujung kapak menghantam salju keras secara miring dengan bunyi gedebuk, lalu mengangkat titik berat sedikit ke atas, crampon menginjak tepat ke lubang kecil yang baru saja dibuat ujung kapak."
  },
  AvgDialog_145516_Content_34 = {
    Text = "Aneh, sepertinya baru-baru ini ada seseorang yang pernah ke sini."
  },
  AvgDialog_145516_Content_35 = {
    Text = "Lihat, di sini ada beberapa lubang, agak mirip seperti bekas galian kapak es."
  },
  AvgDialog_145516_Content_36 = {
    Text = "Mungkin ini ditinggalkan oleh tim ekspedisi sebelumnya?"
  },
  AvgDialog_145516_Content_37 = {
    Text = "Sepertinya tidak. Waktunya sudah terlalu lama berlalu, bekas-bekas dari saat itu pasti sudah membeku kembali."
  },
  AvgDialog_145516_Content_38 = {
    Text = "Sudahlah, tidak perlu terlalu banyak berpikir. Ada orang yang pernah lewat adalah hal yang baik, artinya jalan ini bisa dilalui."
  },
  AvgDialog_145516_Content_39 = {
    Text = "Dia mengambil sebuah paku es dari tali harness-nya, memutarnya masuk ke lapisan es, mengeluarkan bunyi \"krek\" yang membuat gigi ngilu."
  },
  AvgDialog_145516_Content_4 = {
    Text = "Pemandangan yang megah membuat kalian yang sudah agak kelelahan merasa sedikit lebih segar."
  },
  AvgDialog_145516_Content_40 = {
    Text = "Hingga seluruh badan paku tertanam, Naraka menggantungkan sebuah kunci karabiner di atasnya, memasukkan tali utama ke dalamnya, lalu memutar pintu kunci hingga mentok."
  },
  AvgDialog_145516_Content_41 = {
    Text = "Titik pengaman pertama."
  },
  AvgDialog_145516_Content_42 = {
    Text = "Semua orang, pasang ascender ke tali utama. Gunakan crampon di sepatu pendakian untuk mengait lubang yang sudah aku pahat, maju perlahan."
  },
  AvgDialog_145516_Content_43 = {
    Text = "Kamu mencari titik pijakan yang kokoh di atas kepala dengan kapak es, menancapkan ujung kapak dengan kuat, lalu mengangkat kaki kanan, menendang keras permukaan es dengan crampon depan, membiarkan dua gigi baja itu mencengkeram kuat."
  },
  AvgDialog_145516_Content_44 = {
    Text = "Tumpukan berat badan ke kaki, jangan memeluk dinding es."
  },
  AvgDialog_145516_Content_45 = {
    Text = "Kamu menarik napas dalam-dalam menghirup udara tipis yang terasa menyakitkan, sedikit mendorong tubuh menjauh dari permukaan es, membiarkan crampon menanggung beban. Kaki kiri menyusul, sekali lagi sebuah tendangan."
  },
  AvgDialog_145516_Content_46 = {
    Text = "Ascender perlahan bergeser naik mengikutimu, setiap kali bergeser sedikit terdengar bunyi klik-klik saat berputar bebas."
  },
  AvgDialog_145516_Content_47 = {
    Text = "Di tengah perjalanan, tubuhmu sudah basah kuyup keringat, konsentrasi yang tadinya terpusat mulai buyar tanpa bisa ditahan."
  },
  AvgDialog_145516_Content_48 = {
    Text = "Tetap fokus, bagian jalan ini tidak bisa mentolerir kesalahan sekecil apapun."
  },
  AvgDialog_145516_Content_49 = {
    Text = "Tepat saat kata-katanya selesai terucap, musibah pun terjadi."
  },
  AvgDialog_145516_Content_5 = {
    Text = "<Shake:Tu-, tunggu sebentar…>"
  },
  AvgDialog_145516_Content_51 = {
    Text = "Seberkas cahaya merah berkilat dari kegelapan malam, ujung hidung William bergerak—"
  },
  AvgDialog_145516_Content_52 = {
    Text = "<BigShake:Merunduk—!>"
  },
  AvgDialog_145516_Content_53 = {
    Text = "Belum selesai kata-katanya, dia sudah menerjang dengan keras, seluruh tubuhnya menindihmu, hanya tali pengaman yang menggantung kalian berdua, berbenturan di dinding es."
  },
  AvgDialog_145516_Content_54 = {
    Text = "Sejalur garis Darah tipis muncul di pipinya."
  },
  AvgDialog_145516_Content_55 = {
    Text = "Heh, reaksinya cukup cepat."
  },
  AvgDialog_145516_Content_56 = {
    Text = "Dari kedalaman kegelapan, rantai berat terseret di lantai, suara gesekan logam dengan lantai terdengar berat dan panjang."
  },
  AvgDialog_145516_Content_57 = {
    Text = "Oh, kamu ya, orang yang mengikuti kami sepanjang jalan."
  },
  AvgDialog_145516_Content_58 = {
    Text = "Mengikuti sepanjang jalan?"
  },
  AvgDialog_145516_Content_59 = {
    Text = "Ya, saat pertama kali bertemu Castor, aku sudah memperingatkan kalian bahwa ada seseorang yang mengikuti kita."
  },
  AvgDialog_145516_Content_6 = {
    Text = "Evelyn terengah-engah dengan napas berat. Tekanan rendah di ketinggian tinggi jelas memberikan dampak serius pada tubuhnya."
  },
  AvgDialog_145516_Content_60 = {
    Text = "Yang tidak diketahui adalah, kapan dia berlari ke depan kita."
  },
  AvgDialog_145516_Content_61 = {
    Text = "Pantas saja aura ini terasa sangat familiar."
  },
  AvgDialog_145516_Content_62 = {
    Text = "Aku ingat namamu——"
  },
  AvgDialog_145516_Content_63 = {
    Text = "Kebetulan kalau begitu, tidak perlu perkenalan diri."
  },
  AvgDialog_145516_Content_64 = {
    Text = "Di batas antara cahaya dan bayangan, sebuah sosok perlahan melangkah keluar."
  },
  AvgDialog_145516_Content_65 = {
    Text = "Kedua pergelangan tangannya terputus, di belakangnya terseret sepasang bola rantai yang berat, di atas bola rantai itu, sepasang mata raksasa berwarna darah menatap dunia dengan garang."
  },
  AvgDialog_145516_Content_66 = {
    Text = "……Helot: Catena."
  },
  AvgDialog_145516_Content_67 = {
    Text = "Di dunia sebelumnya, dia adalah orang terakhir yang kutemui."
  },
  AvgDialog_145516_Content_68 = {
    Text = "Dengan kata lain——dia adalah orang yang membunuhku."
  },
  AvgDialog_145516_Content_69 = {
    Text = "Saat itu, dia mematuhi Herbert, mematuhi Asosiasi Pematung."
  },
  AvgDialog_145516_Content_7 = {
    Text = "Di belakangnya, gadis kecil itu justru melangkah dengan ringan."
  },
  AvgDialog_145516_Content_70 = {
    Text = "Sekarang? <Yellow:Siapa> yang menyuruhmu datang?"
  },
  AvgDialog_145516_Content_71 = {
    Text = "Hanya anjing yang peduli siapa tuannya."
  },
  AvgDialog_145516_Content_72 = {
    Text = "Yang harus kulakukan hanya satu hal——membuat kalian terkubur di sini selamanya."
  },
  AvgDialog_145516_Content_73 = {
    Text = "Tak terhitung Pustula muncul dari tanah, mengepung kalian dari segala arah."
  },
  AvgDialog_145516_Content_8 = {
    Text = "<Blue:Yata no Kagami>, <Blue:Bulu Maat>… <Blue:Mahkota Ariadne> ada di puncak gunung…"
  },
  AvgDialog_145516_Content_9 = {
    Text = "<Blue:Benang Sutra Moira>, hm hm, ada yang tidak mau memberitahuku, tapi aku tahu di mana. <Blue:Apel Emas> bisa aku urus."
  },
  AvgDialog_145517_Content_1 = {
    Text = "Burung Terbang Jauh Hari Ini"
  },
  AvgDialog_145517_Content_10 = {
    Text = "Keluarlah, kalian sudah mengikutiku sepanjang jalan, bukan?"
  },
  AvgDialog_145517_Content_11 = {
    Text = "Aku sudah sendirian, dan jarak sekarang pun tidak cukup untuk berteriak minta tolong."
  },
  AvgDialog_145517_Content_12 = {
    Text = "<Shake:Biarkan kita……berhadapan……satu……sama……lain……>"
  },
  AvgDialog_145517_Content_13 = {
    Text = "Sosok yang muncul dari hutan itu, seolah melangkah keluar dari mimpinya."
  },
  AvgDialog_145517_Content_14 = {
    Text = "<Shake:Tidak……kamu adalah……>"
  },
  AvgDialog_145517_Content_15 = {
    Text = "Sosok yang tegap dan anggun itu, tampak lebih kurus dibanding saat perpisahan dulu."
  },
  AvgDialog_145517_Content_16 = {
    Text = "Namaku Pollux. Atas perintah Pemimpin Agama, aku datang untuk mengejar buronan Castor."
  },
  AvgDialog_145517_Content_17 = {
    Text = "Isinya sudah tidak penting lagi, suaranya berdengung di telinga Castor, bagai Igauan."
  },
  AvgDialog_145517_Content_18 = {
    Text = "<SmallShake:Apakah itu Wendigo?>"
  },
  AvgDialog_145517_Content_19 = {
    Text = "Tidak, bukan Wendigo. Bahkan ilusi paling indah sekalipun tidak bisa memalsukan tekstur yang nyata."
  },
  AvgDialog_145517_Content_2 = {
    Text = "Pemuda itu berlari kencang di tengah salju."
  },
  AvgDialog_145517_Content_20 = {
    Text = "Pendosa……Castor……Cahaya Suci akan menyingkap dosa-dosamu."
  },
  AvgDialog_145517_Content_21 = {
    Text = "nyata, kasar, dingin, kejam, dan mengerikan."
  },
  AvgDialog_145517_Content_22 = {Text = "Pollux…"},
  AvgDialog_145517_Content_23 = {
    Text = "Yang memenuhi hati, rasa sakit yang menusuk itu."
  },
  AvgDialog_145517_Content_24 = {
    Text = "Berapa lama lagi bisa Menghindar? Masih bisakah Menghindar lebih lama lagi?"
  },
  AvgDialog_145517_Content_25 = {
    Text = "Castor melangkah di atas Salju, selangkah demi selangkah menuju Pollux."
  },
  AvgDialog_145517_Content_26 = {
    Text = "<Red:<Shake:Berlututlah di bawah Lentera, aku akan mengampuni dosamu, dan mengizinkanmu terlahir kembali dalam wujud baru di tanah suci yang tak berdosa!>>"
  },
  AvgDialog_145517_Content_27 = {
    Text = "Castor tidak menurut. Dia Hanya terus melangkah maju menuju Pollux."
  },
  AvgDialog_145517_Content_28 = {
    Text = "Bahkan jika itu adalah Wendigo pun tidak masalah. Dia Hanya terus maju."
  },
  AvgDialog_145517_Content_29 = {
    Text = "Pollux mengangkat pisaunya. Pisau yang familiar. Pada Pengejaran sebelumnya, dada Castor pernah di-Pierce oleh pisau itu."
  },
  AvgDialog_145517_Content_3 = {
    Text = "Tidak ada lagi yang bisa menghalanginya."
  },
  AvgDialog_145517_Content_30 = {
    Text = "<Big:Selangkah lagi ke depan, cahaya suci akan menghukummu!>"
  },
  AvgDialog_145517_Content_4 = {
    Text = "Jalan menuruni gunung… terasa ringan seperti terbang bersama angin."
  },
  AvgDialog_145517_Content_5 = {
    Text = "Jalan yang tidak perlu menanggung kebohongan membuat hatinya pun melayang ringan."
  },
  AvgDialog_145517_Content_6 = {
    Text = "Maaf, aku tidak seharusnya menipu kalian."
  },
  AvgDialog_145517_Content_7 = {
    Text = "Syukurlah, sekarang semuanya masih belum terlambat."
  },
  AvgDialog_145517_Content_8 = {
    Text = "Setiap kali dia berhenti sejenak, dari hutan di belakangnya selalu terdengar suara yang menyerupai salju jatuh."
  },
  AvgDialog_145517_Content_9 = {
    Text = "Itu adalah suara langkah kaki yang tiba-tiba berhenti."
  },
  AvgDialog_145518_Content_1 = {
    Text = "Bulan yang Tak Membeku"
  },
  AvgDialog_145518_Content_10 = {
    Text = "Kamu dengan senang hati menyetujuinya."
  },
  AvgDialog_145518_Content_100 = {
    Text = "Hah, penipu licik, selalu muncul dengan citra korban yang paling polos…"
  },
  AvgDialog_145518_Content_101 = {
    Text = "Dia berdendang kecil, lalu berlari kembali ke barisan paling depan."
  },
  AvgDialog_145518_Content_102 = {
    Text = "Apa maksud perkataannya itu?"
  },
  AvgDialog_145518_Content_103 = {
    Text = "Saya juga tidak mengerti."
  },
  AvgDialog_145518_Content_104 = {
    Text = "Hei~ ikuti terus, jangan sampai tertinggal~"
  },
  AvgDialog_145518_Content_105 = {
    Text = "Keduanya yang kebingungan hanya bisa melangkah maju."
  },
  AvgDialog_145518_Content_106 = {
    Text = "-Ketinggian 6000 meter-"
  },
  AvgDialog_145518_Content_11 = {
    Text = "Aku tahu ini sulit dipercaya, tapi aku berasal dari tempat yang sangat jauh. Terlalu lama mengembara, aku hanya ingat, di hari-hari terakhir, kami menyebutnya <Blue:Bintang Terasing>."
  },
  AvgDialog_145518_Content_12 = {
    Text = "Aku melewati waktu yang begitu panjang hingga tak terhitung, baru bisa tiba di sini."
  },
  AvgDialog_145518_Content_13 = {
    Text = "Saya percaya kamu."
  },
  AvgDialog_145518_Content_14 = {
    Text = "Yang ingin aku sampaikan adalah… Bintang Terasing terlalu jauh, begitu jauh hingga bahkan membayangkan dan menggambarkannya pun sangat Keras."
  },
  AvgDialog_145518_Content_15 = {
    Text = "Tapi tadi, sepertinya di dalam air danau… aku melihat kakak perempuanku, Faint."
  },
  AvgDialog_145518_Content_16 = {
    Text = "Tinct menggigit bibirnya."
  },
  AvgDialog_145518_Content_17 = {
    Text = "Tidak, sebenarnya juga bukan… Hanya Saja aku merasakan semacam pertanda, bayangan di dalam danau itu, juga berasal dari Bintang Terasing…"
  },
  AvgDialog_145518_Content_18 = {
    Text = "Aku tahu ini mustahil, tapi aku merasa, <Shake:itu bukan halusinasi……>"
  },
  AvgDialog_145518_Content_19 = {
    Text = "Kamu terlihat sangat kelelahan."
  },
  AvgDialog_145518_Content_2 = {
    Text = "Angin dan salju entah kapan berhenti, yang tersisa di antara langit dan bumi hanyalah kesunyian yang begitu luas hingga terasa gemetar. Di atas kepala terbentang langit biru tua tanpa awan, bahkan puncak-puncak bersalju di kejauhan pun tampak jelas tanpa terhalang."
  },
  AvgDialog_145518_Content_20 = {
    Text = "Evelyn menampakkan raut wajah penuh perhatian."
  },
  AvgDialog_145518_Content_21 = {
    Text = "Jika merasa lelah, istirahatlah segera."
  },
  AvgDialog_145518_Content_22 = {
    Text = "Kita baru saja berangkat, turun gunung sendirian pun tidak terlalu berbahaya."
  },
  AvgDialog_145518_Content_23 = {
    Text = "<Yellow:<Big:Tidak……! Aku tidak lelah! Aku tidak akan mundur!>>"
  },
  AvgDialog_145518_Content_24 = {
    Text = "Di luar dugaan semua orang, Tinct berteriak histeris."
  },
  AvgDialog_145518_Content_25 = {
    Text = "Menyadari semua Tatapan tertuju padanya, Tinct berusaha menenangkan diri, namun dadanya yang naik turun masih mengungkap perasaannya yang nyata."
  },
  AvgDialog_145518_Content_26 = {
    Text = "Maaf sudah bertingkah aneh. Terima kasih atas perhatianmu, <Yellow:aku tidak lelah>."
  },
  AvgDialog_145518_Content_27 = {
    Text = "Berbohong itu tidak ada gunanya."
  },
  AvgDialog_145518_Content_28 = {
    Text = "Aku sangat teguh. Aku tidak akan tertinggal."
  },
  AvgDialog_145518_Content_29 = {
    Text = "Tinct kembali mengatupkan bibirnya, melirik sekali ke danau es, lalu melangkah Berangkat."
  },
  AvgDialog_145518_Content_3 = {
    Text = "Di bawah langit cerah yang membentang luas, kalian berjalan menyusuri jalan salju yang landai, hingga tiba di tepi sebuah danau es."
  },
  AvgDialog_145518_Content_30 = {
    Text = "Di atas permukaan danau yang membeku, Hanya bayangan samarnya yang terpantul."
  },
  AvgDialog_145518_Content_31 = {
    Text = "Kalian berjalan setengah hari, menemukan sebidang tanah datar untuk berkemah, Naraka memerintahkan semua pendaki untuk mengumpulkan Salju yang mencair dan merebusnya menggunakan kompor gunung."
  },
  AvgDialog_145518_Content_32 = {
    Text = "Ketika kalian kembali membawa tumpukan Salju, kalian justru Menemukan asap tebal mengepul di dekat kemah."
  },
  AvgDialog_145518_Content_33 = {
    Text = "Hei, itu bagasi siapa yang terbakar di sana!"
  },
  AvgDialog_145518_Content_34 = {
    Text = "Hm…? Tidak!!!"
  },
  AvgDialog_145518_Content_35 = {
    Text = "Lidah api menjilati tas kecil berbahan kain yang selalu dijaga bak harta karun oleh Caraboo."
  },
  AvgDialog_145518_Content_36 = {
    Text = "Tunggu, sekantong koin emas di dalam tasmu itu?"
  },
  AvgDialog_145518_Content_37 = {
    Text = "Di bawah jilatan api, koin-koin emas itu perlahan meleleh dan amblas."
  },
  AvgDialog_145518_Content_38 = {
    Text = "Tidak! Tidak apa-apa! Biarkan aku yang menyelamatkannya!"
  },
  AvgDialog_145518_Content_39 = {
    Text = "Tidak benar, biarkan aku lihat!"
  },
  AvgDialog_145518_Content_4 = {
    Text = "Tinct terpaku menatap air danau dengan pandangan kosong."
  },
  AvgDialog_145518_Content_40 = {
    Text = "Saat dirobek, semua koin emas yang setengah meleleh bergulingan ke lantai."
  },
  AvgDialog_145518_Content_41 = {
    Text = "Salah satunya menggelinding ke kaki William, ia membungkuk untuk memungutnya."
  },
  AvgDialog_145518_Content_42 = {
    Text = "<Blue:Debojale, Cokelat Koin Emas <Italic:Pistoles de Marie>>……"
  },
  AvgDialog_145518_Content_43 = {Text = "Cokelat?!"},
  AvgDialog_145518_Content_44 = {
    Text = "<Shake:Ha, haha……>Ini… meskipun hanya cokelat, tapi harganya juga mahal!"
  },
  AvgDialog_145518_Content_45 = {
    Text = "Omong kosong, kalau tidak bisa menyerahkan uang pemandu, pergi saja dari rombongan ini!"
  },
  AvgDialog_145518_Content_46 = {
    Text = "<Shake:Tidak, tolong, aku tidak tahu Jalan sendirian……>"
  },
  AvgDialog_145518_Content_47 = {
    Text = "<Shake:Kalau kamu membuangku dari rombongan, aku pasti akan mati di tengah perjalanan turun gunung!>"
  },
  AvgDialog_145518_Content_48 = {
    Text = "Persetan, apa gunanya menangis meraung-raung di sini sekarang? Kalau sudah berani menipu, harus siap ketahuan!"
  },
  AvgDialog_145518_Content_49 = {
    Text = "Melihat Naraka tidak bisa dilunakkan dengan cara apapun, Caraboo memandang sekeliling, lalu Seolah-olah menemukan pegangan hidup, ia berlutut dengan suara gedebuk dan memeluk erat pahamu."
  },
  AvgDialog_145518_Content_5 = {
    Text = "Ada sesuatu di dalam danau?"
  },
  AvgDialog_145518_Content_50 = {
    Text = "<Shake:Tolong, orang baik, kamu tidak mungkin membiarkan seorang gadis kecil turun gunung sendirian tanpa siapa-siapa, kan?>"
  },
  AvgDialog_145518_Content_51 = {
    Text = "<Shake:Huu huu huu, selalu begini, aku selalu ditinggalkan, ke mana pun aku pergi, semua orang membenciku karena aku tidak punya apa-apa……>"
  },
  AvgDialog_145518_Content_52 = {
    Text = "<Shake:Orang baik, dermawan, kamu pasti berbeda dari mereka, kamu pasti akan membantuku, kan?>"
  },
  AvgDialog_145518_Content_53 = {
    Text = "Dia mendongakkan kepala, menatapmu dengan Mata berkaca-kaca."
  },
  AvgDialog_145518_Content_54 = {
    Text = "……Sudahlah. Uang pemandunya, akan kubayarkan untuknya setelah turun gunung."
  },
  AvgDialog_145518_Content_55 = {
    Text = "Tidak tahan dengan serangan tatapan matanya, kamu pun menyanggupinya."
  },
  AvgDialog_145518_Content_56 = {
    Text = "<Big:Terima kasih, {Male=恩公,Female=恩人}!!> Kamu adalah penolong terbesar dan terhebat dalam hidup Caraboo!!"
  },
  AvgDialog_145518_Content_57 = {
    Text = "Caraboo langsung menyeka air matanya dan melompat-lompat dengan wajah ceria."
  },
  AvgDialog_145518_Content_58 = {
    Text = "{Male=恩公,Female=恩人}, setelah aku memulihkan kekuasaan Dewi Gunung Salju, pasti akan membalas budi besarmu!"
  },
  AvgDialog_145518_Content_59 = {
    Text = "Saat itu tiba, jangankan tiga puluh keping emas, tiga ratus, tiga ribu pun bisa aku bayar!"
  },
  AvgDialog_145518_Content_6 = {
    Text = "Tidak, tidak, tidak ada, tidak ada apa-apa……"
  },
  AvgDialog_145518_Content_60 = {
    Text = "Baiklah, baiklah."
  },
  AvgDialog_145518_Content_61 = {
    Text = "Kamu menjawab asal-asalan."
  },
  AvgDialog_145518_Content_62 = {
    Text = "Bagaimanapun kita masih harus mendaki bersama, asalkan urusan ini cepat berlalu saja."
  },
  AvgDialog_145518_Content_63 = {
    Text = "Situasi akhirnya mereda, dan semua orang kembali sibuk atau beristirahat masing-masing."
  },
  AvgDialog_145518_Content_64 = {
    Text = "William menarikmu ke samping dan berbisik kepadamu."
  },
  AvgDialog_145518_Content_65 = {
    Text = "Agak aneh, aku ingat tas Caraboo, sebelumnya tidak berada di posisi itu."
  },
  AvgDialog_145518_Content_66 = {
    Text = "<Red:Siapa yang memindahkannya ke dekat api unggun?>"
  },
  AvgDialog_145518_Content_67 = {
    Text = "Air sudah mendidih. Ayo semua minum sedikit untuk menghangatkan badan."
  },
  AvgDialog_145518_Content_68 = {
    Text = "Ada sup bawang putih?"
  },
  AvgDialog_145518_Content_69 = {
    Text = "Tanya aku? Tidak ada yang seperti itu. Minum air panas saja untuk sementara."
  },
  AvgDialog_145518_Content_7 = {
    Text = "Tinct tersadar dan kembali ke kesadarannya, dia tampak ingin berkata sesuatu namun ragu-ragu."
  },
  AvgDialog_145518_Content_70 = {
    Text = "Hmph, tidak ada ya... Sherpa pemimpin terbaik katanya juga tidak seberapa, masih memungut biaya pemandu yang begitu mahal."
  },
  AvgDialog_145518_Content_71 = {
    Text = "Melihat suasana yang hampir memanas lagi, Evelyn segera menyela."
  },
  AvgDialog_145518_Content_72 = {
    Text = "Kalau kamu mau minum yang hangat, aku punya sedikit cokelat panas di sini."
  },
  AvgDialog_145518_Content_73 = {
    Text = "Dan kamu, anak kecil, bekal keringmu sepertinya tidak cukup? Kulihat kamu tidak banyak makan."
  },
  AvgDialog_145518_Content_74 = {
    Text = "Aku? Tidak apa-apa, saat kami bertapa, setiap hari pun hanya makan sekali."
  },
  AvgDialog_145518_Content_75 = {
    Text = "Saat mendaki, tidak mengisi cukup energi itu tidak boleh, lho."
  },
  AvgDialog_145518_Content_76 = {
    Text = "Suamiku dulu waktu mendaki, juga sama sepertimu, selalu suka membawa Ransel Perjalanan yang paling ringan."
  },
  AvgDialog_145518_Content_77 = {
    Text = "Sejak suatu kali terjebak badai salju selama beberapa hari, dia selalu memilih strategi yang lebih aman."
  },
  AvgDialog_145518_Content_78 = {
    Text = "Suami Anda... dia juga seorang Pendaki Gunung?"
  },
  AvgDialog_145518_Content_79 = {
    Text = "Hmm, dia adalah Pendaki Gunung yang sangat hebat, sebelumnya juga pernah menyerang puncak Everest dan K2."
  },
  AvgDialog_145518_Content_8 = {
    Text = "Sejenak kemudian, dia baru berbalik ke arahmu dan berkata dengan pelan."
  },
  AvgDialog_145518_Content_80 = {
    Text = "Kemudian apa?"
  },
  AvgDialog_145518_Content_81 = {Text = "Kemudian?"},
  AvgDialog_145518_Content_82 = {
    Text = "Suamimu, apakah dia tidak lagi mendaki gunung?"
  },
  AvgDialog_145518_Content_83 = {
    Text = "<Shake:Hmm? Kenapa kamu menarikku?>"
  },
  AvgDialog_145518_Content_84 = {
    Text = "Semua orang mengikuti ucapannya dan memandang ke satu sisi, wajah Caraboo tampak tersenyum ramah, namun tangannya diam-diam menarik lengan baju Castor."
  },
  AvgDialog_145518_Content_85 = {
    Text = "Melihat Aksinya Ditemukan, dia sedikit canggung menarik tangannya kembali, lalu bergumam pelan."
  },
  AvgDialog_145518_Content_86 = {
    Text = "<Small:Orang bodoh>."
  },
  AvgDialog_145518_Content_87 = {
    Text = "Tidak apa-apa..."
  },
  AvgDialog_145518_Content_88 = {
    Text = "Suamiku... dia menghilang saat berusaha mencapai puncak Everest yang terakhir kali. Tidak ada yang tahu ke mana dia pergi. Jenazahnya pun tidak ditemukan."
  },
  AvgDialog_145518_Content_89 = {
    Text = "Dulu aku selalu menemaninya bersama, Hanya Saja aku akan berhenti dan menunggu di sekitar titik C2."
  },
  AvgDialog_145518_Content_9 = {
    Text = "Maaf, entah mengapa, terhadap Anda, aku selalu merasakan perasaan yang sangat akrab. Jadi, bisakah Anda mendengarkan aku bicara sebentar?"
  },
  AvgDialog_145518_Content_90 = {
    Text = "Sekarang dia telah pergi, aku juga ingin melihat pemandangan yang pernah dia lihat..."
  },
  AvgDialog_145518_Content_91 = {
    Text = "Evelyn memandang jauh ke punggungan gunung di kejauhan. Gunung Salju abadi itu diam membisu, menjawab dengan Angin yang Menderu."
  },
  AvgDialog_145518_Content_92 = {
    Text = "Kali ini kita pasti akan mencapai puncak."
  },
  AvgDialog_145518_Content_93 = {
    Text = "Aku mempercayai hal itu."
  },
  AvgDialog_145518_Content_94 = {
    Text = "Tidak lama Setelah percakapan itu berlalu, Caraboo kembali ke penampilannya yang santai, berjalan-jalan ke sana kemari dengan tangan di belakang."
  },
  AvgDialog_145518_Content_95 = {
    Text = "Dia mendekat ke Castor dengan penuh misteri."
  },
  AvgDialog_145518_Content_96 = {
    Text = "Hei, orang bodoh, apakah kamu merasa ada seseorang yang mengikuti kita?"
  },
  AvgDialog_145518_Content_97 = {
    Text = "Sepertinya tidak. Sepanjang Jalan ini aku selalu waspada terhadap pengejaran Gereja Lentera. Tapi kalian adalah orang-orang pertama yang kutemui..."
  },
  AvgDialog_145518_Content_98 = {
    Text = "Aku juga tidak merasakannya."
  },
  AvgDialog_145518_Content_99 = {
    Text = "Begitu? Kalau begitu anggap saja aku terlalu banyak berpikir."
  },
  AvgDialog_145519_Content_10 = {
    Text = "Yata no Kagami, bersama Pedang Kusanagi dan Magatama Yasakani no Magatama, dalam mitologi Jepang ketiganya disebut Tiga Pusaka Suci. Dalam lukisan yang umum dijumpai, Yata no Kagami selalu terbuat dari logam, dengan ukiran motif bergaya Jepang di bagian belakang cermin."
  },
  AvgDialog_145519_Content_11 = {
    Text = "Tapi lihatlah cermin ini…"
  },
  AvgDialog_145519_Content_12 = {
    Text = "Permukaan cermin tipis, rata, dan halus, berbentuk bulat sempurna, bagaikan bulan purnama yang tergantung tinggi di langit."
  },
  AvgDialog_145519_Content_13 = {
    Text = "Di balik permukaan kaca yang dingin, sepertinya ada partikel cahaya berwarna yang mengalir samar-samar."
  },
  AvgDialog_145519_Content_14 = {
    Text = "Bagaimanapun juga, mari kita ambil dulu dan lihat."
  },
  AvgDialog_145519_Content_15 = {
    Text = "Naraka mengangkat sebuah paku es, dengan mudah memecahkan lapisan es, dan mengambil cermin itu."
  },
  AvgDialog_145519_Content_16 = {
    Text = "Caraboo melompat maju, merebut cermin itu dengan cepat, dan dengan sigap memasukkannya ke dalam tas bawaannya."
  },
  AvgDialog_145519_Content_17 = {
    Text = "<Shake:Apa-apaan! Lihat apa, jangan lihat aku!>"
  },
  AvgDialog_145519_Content_18 = {
    Text = "Ini memang harta milik Dewi Gunung Salju, tentu saja setelah ditemukan seharusnya menjadi milikku!"
  },
  AvgDialog_145519_Content_19 = {
    Text = "Tidak ada seorang pun yang mencoba memperebutkan kepemilikannya dari dia."
  },
  AvgDialog_145519_Content_2 = {
    Text = "Kalian berkeliaran di tepi danau es. Permukaan danau seperti cermin, bersih dan jernih, seluruh penjuru terlihat jelas, tidak ada bayangan Tinct di sana."
  },
  AvgDialog_145519_Content_20 = {
    Text = "Dibandingkan sebuah cermin yang tampak biasa-biasa saja, menghilangnya Tinct jelas jauh lebih layak mendapat perhatian."
  },
  AvgDialog_145519_Content_21 = {
    Text = "Namun tidak ada seorang pun yang membicarakan hal itu lagi. Hanya bayang-bayang kelamnya yang tetap tak terelakkan, menghimpit berat di hati setiap orang."
  },
  AvgDialog_145519_Content_3 = {
    Text = "Di antara Gaung suara Angin yang bergema di pegunungan salju, Seolah-olah terselip suara nyanyian Tinct dan isak tangis yang lirih — samar-samar, tidak bisa dibedakan apakah itu suara angin atau Bayangan."
  },
  AvgDialog_145519_Content_4 = {
    Text = "Tinct… apakah dia tidak akan kembali lagi?"
  },
  AvgDialog_145519_Content_5 = {
    Text = "Tidak ada yang membantah."
  },
  AvgDialog_145519_Content_6 = {
    Text = "Aneh, apakah benda ini ada kemarin?"
  },
  AvgDialog_145519_Content_7 = {
    Text = "Di permukaan danau es, di dalam es bening yang keras, tersimpan dengan tenang sebuah cermin bulat sempurna."
  },
  AvgDialog_145519_Content_8 = {
    Text = "<Shake:Yata no Kagami, inilah Yata no Kagami yang harus dipersembahkan kepada Dewi Gunung Salju!>"
  },
  AvgDialog_145519_Content_9 = {
    Text = "William, kamu terlihat seperti ingin mengatakan sesuatu tapi menahan diri."
  },
  AvgDialog_145520_Content_1 = {
    Text = "Penumpang Ketujuh"
  },
  AvgDialog_145520_Content_10 = {
    Text = "Beberapa hari ini tidak ada regu pendaki lain, kalian semua bisa beristirahat dengan tenang di sini, tidak akan ada yang mengganggu—"
  },
  AvgDialog_145520_Content_100 = {
    Text = "Hati-hati! Ada sesuatu yang muncul ke permukaan!"
  },
  AvgDialog_145520_Content_11 = {
    Text = "Belum selesai Naraka berbicara, dari sudut gua tiba-tiba terdengar suara gemerisik."
  },
  AvgDialog_145520_Content_12 = {
    Text = "…Eh, ada orang?"
  },
  AvgDialog_145520_Content_13 = {
    Text = "Suara pertanyaan William bergaung di dalam gua, tak ada yang menjawab."
  },
  AvgDialog_145520_Content_14 = {
    Text = "Kami adalah regu pendaki, datang ke sini untuk berlindung dari angin dan salju, tidak ada niat buruk."
  },
  AvgDialog_145520_Content_15 = {
    Text = "Kamu melepaskan sinyal persahabatan, membawa lampu berjalan ke balik bebatuan."
  },
  AvgDialog_145520_Content_16 = {Text = "Hati-hati!"},
  AvgDialog_145520_Content_17 = {
    Text = "Sosok di balik bebatuan itu tiba-tiba menegang. Sebelum semua orang sempat menjelaskan, serangan tajam sudah datang dari kegelapan."
  },
  AvgDialog_145520_Content_19 = {
    Text = "Mungkin karena menghadapi banyak orang sendirian, si pendatang melancarkan satu Ambush lalu seketika menghilang kembali ke dalam bayangan. Namun kamu masih sempat mengenali sosok itu dalam pertarungan singkat tersebut."
  },
  AvgDialog_145520_Content_2 = {
    Text = "Setelah Naraka memimpin kalian berjalan sejenak, sebuah celah hitam terlihat di antara puncak-puncak gunung."
  },
  AvgDialog_145520_Content_20 = {
    Text = "<Shake:Castor?!>"
  },
  AvgDialog_145520_Content_21 = {
    Text = "Sejenak kemudian, dari dalam bayangan muncul seseorang berbalut jubah hitam, dari balik jubah itu, separuh Wajah dengan ekspresi waspada mengintip keluar."
  },
  AvgDialog_145520_Content_22 = {
    Text = "…Kamu mengenalku?"
  },
  AvgDialog_145520_Content_23 = {
    Text = "Tidak, kalau diceritakan ini akan menjadi kisah yang sangat panjang…"
  },
  AvgDialog_145520_Content_24 = {
    Text = "Jadi, mengapa kamu bisa sendirian di sini?"
  },
  AvgDialog_145520_Content_26 = {
    Text = "……………"
  },
  AvgDialog_145520_Content_27 = {
    Text = "Hmm, aku dan adikku — Pollux sudah berjanji untuk melarikan diri dari Gereja Lentera dengan cara berbeda secara bergantian. Tapi aku sudah menunggu selama sebulan di tempat yang kami sepakati, dan dia tidak muncul."
  },
  AvgDialog_145520_Content_28 = {
    Text = "Aku pikir, pasti karena kepergianku membuat Nyonya Juliette memperketat penjagaan. Sejak saat itu, aku terus mencari cara untuk menyelamatkannya."
  },
  AvgDialog_145520_Content_29 = {
    Text = "<Yellow:Untungnya aku berhasil bersembunyi dengan baik dan lolos dari pengejaran mereka.>"
  },
  AvgDialog_145520_Content_3 = {Text = "Masuklah."},
  AvgDialog_145520_Content_30 = {
    Text = "Akhirnya, aku mendengar bahwa di puncak gunung salju ada Dewa yang bisa mengabulkan segala keinginan."
  },
  AvgDialog_145520_Content_31 = {
    Text = "Tapi aku tidak bisa bergabung dengan regu pendakian mana pun... mata-mata Gereja ada di mana-mana, kalau aku terlalu sering menampakkan diri, akan sangat mudah ditemukan."
  },
  AvgDialog_145520_Content_32 = {Text = "Bodoh."},
  AvgDialog_145520_Content_33 = {Text = "Ah...?"},
  AvgDialog_145520_Content_34 = {
    Text = "Belum pernah kulihat orang yang sebodoh kamu."
  },
  AvgDialog_145520_Content_35 = {
    Text = "Seandainya kamu berhasil mendaki gunung sendirian, di mana kamu akan mencari tujuh artefak sakti itu?"
  },
  AvgDialog_145520_Content_37 = {
    Text = "Sepertinya aku belum pernah memikirkan itu..."
  },
  AvgDialog_145520_Content_38 = {
    Text = "Kan! Sekarang, kamu butuh bantuan Dewi Salju."
  },
  AvgDialog_145520_Content_39 = {
    Text = "Ayo, asalkan bergabung ke Sekte Peri, aku jamin setelah berhasil mencapai puncak, aku akan membantumu menyelesaikan penderitaan pemisahan antara kamu dan adikmu!"
  },
  AvgDialog_145520_Content_4 = {
    Text = "Kalian saling berpegangan menuruni bebatuan terjal, kamu menoleh ke arah mulut gua."
  },
  AvgDialog_145520_Content_40 = {Text = "Benarkah?"},
  AvgDialog_145520_Content_41 = {
    Text = "Tentu saja ini serius! Tidak bisa lebih serius dari ini!"
  },
  AvgDialog_145520_Content_42 = {
    Text = "Tapi untuk menunjukkan kesungguhanmu kepada Sekte Peri, semua harta benda yang kamu bawa harus diserahkan kepada Peri untuk dijaga."
  },
  AvgDialog_145520_Content_43 = {
    Text = "...Baiklah."
  },
  AvgDialog_145520_Content_44 = {
    Text = "Castor terbata-bata cukup lama, lalu mengeluarkan beberapa keping koin dan sebuah Buku Dongeng yang sudah lusuh dan usang."
  },
  AvgDialog_145520_Content_45 = {
    Text = "Hanya ini yang kumiliki. Bolehkah aku bergabung?"
  },
  AvgDialog_145520_Content_46 = {
    Text = "William menepuk lenganmu."
  },
  AvgDialog_145520_Content_47 = {
    Text = "Sudah puas menonton?"
  },
  AvgDialog_145520_Content_48 = {
    Text = "Ehm, itu, Castor, selamat datang bergabung dengan regu petualangan kami."
  },
  AvgDialog_145520_Content_49 = {
    Text = "Caraboo hanya menggodamu, asalkan kamu membawa perbekalan sendiri, tidak perlu menyerahkan apa pun tambahan."
  },
  AvgDialog_145520_Content_5 = {
    Text = "Celah itu sempit dan rata, seperti mata yang setengah terbuka, menghalangi angin dan salju dari luar."
  },
  AvgDialog_145520_Content_50 = {
    Text = "Hmph, Dewi Salju pun tidak tertarik dengan persembahan remehmu itu, lebih baik kamu simpan sendiri saja."
  },
  AvgDialog_145520_Content_51 = {
    Text = "Castor dengan penuh kehati-hatian meratakan lipatan Buku Dongeng itu, lalu menyimpannya kembali dengan hati-hati ke dalam pelukannya."
  },
  AvgDialog_145520_Content_52 = {
    Text = "Kemudian ia melirik beberapa koin itu, pandangannya berkeliling di antara kalian semua."
  },
  AvgDialog_145520_Content_53 = {
    Text = "Kalau tidak ada yang mau, aku terima dengan senang hati."
  },
  AvgDialog_145520_Content_54 = {
    Text = "Naraka melambaikan tangannya, dan seketika meja batu itu menjadi kosong melompong."
  },
  AvgDialog_145520_Content_55 = {
    Text = "Biaya pemandu Orang Ini, jauh lebih murah dibanding yang lain."
  },
  AvgDialog_145520_Content_56 = {
    Text = "Kalau aku tidak salah ingat, biaya pemandumu sudah kami bayar."
  },
  AvgDialog_145520_Content_57 = {
    Text = "Kalau memang harus membayar satu porsi tambahan, biar aku yang menanggungnya untuknya."
  },
  AvgDialog_145520_Content_58 = {
    Text = "Tidak apa-apa, kita tidak saling kenal, bagaimana mungkin aku bisa merepotkan Anda…"
  },
  AvgDialog_145520_Content_59 = {
    Text = "Tangan yang dijulurkan Evelyn memotong ucapan Castor; yang terakhir ragu sejenak selama setengah detik, lalu membalas genggamannya."
  },
  AvgDialog_145520_Content_6 = {
    Text = "Di dalam sini… sangat hangat…"
  },
  AvgDialog_145520_Content_60 = {
    Text = "Evelyn, namaku Evelyn, aku seorang arkeolog."
  },
  AvgDialog_145520_Content_61 = {
    Text = "Sekarang kita tidak lagi asing satu sama lain, bukan?"
  },
  AvgDialog_145520_Content_63 = {
    Text = "Badai salju mengurung semua orang di dalam gua yang sempit. Api belum menyala, dan percakapan pun menjadi satu-satunya cara untuk melawan dingin dan keheningan."
  },
  AvgDialog_145520_Content_64 = {
    Text = "Kamu tadi bilang, kamu sedang mencari saudara kembarmu, benar?"
  },
  AvgDialog_145520_Content_65 = {Text = "Hm."},
  AvgDialog_145520_Content_66 = {
    Text = "Castor mengangguk dengan hati-hati."
  },
  AvgDialog_145520_Content_67 = {
    Text = "Kebetulan sekali, aku juga sedang mencari saudari kembarku."
  },
  AvgDialog_145520_Content_68 = {
    Text = "Aku dan Faint adalah orang yang sangat berbeda. Meski kakak perempuan memiliki kondisi tubuh yang kurang baik, sebenarnya dia adalah orang yang berani dan kuat."
  },
  AvgDialog_145520_Content_69 = {
    Text = "Saat menyebut saudari kembarnya, Tinct yang biasanya selalu melamun pun seolah hidup kembali, menampilkan senyum tipis."
  },
  AvgDialog_145520_Content_7 = {
    Text = "Hah, hah, aku sebagai dewi gunung salju, bagaimana bisa tidak tahu ada tempat seperti ini di dalam gunung?"
  },
  AvgDialog_145520_Content_70 = {
    Text = "Lalu bagaimana dengan Pollux? Seperti apa orangnya?"
  },
  AvgDialog_145520_Content_71 = {
    Text = "<Shake:Pollux…>"
  },
  AvgDialog_145520_Content_72 = {
    Text = "Dan juga tidak terlalu mirip denganku. Dia cerdas, tajam, dan memiliki pemahaman yang kuat. Sejak kecil hingga dewasa, pemimpin dan guru selalu lebih menyukainya…"
  },
  AvgDialog_145520_Content_73 = {
    Text = "Jangan khawatir. Kamu juga punya kelebihanmu sendiri. Misalnya, bukankah kamu baru saja bilang berhasil lolos dari pengejaran gereja? Itu juga sangat hebat."
  },
  AvgDialog_145520_Content_74 = {
    Text = "Wajah Castor memerah, ia berdeham pelan, lalu mengalihkan topik pembicaraan kembali ke Tinct."
  },
  AvgDialog_145520_Content_75 = {
    Text = "Kamu dan kakakmu, mengapa kalian berpisah?"
  },
  AvgDialog_145520_Content_76 = {
    Text = "Di saat melarikan diri, dia memberikan tiket kapal terakhir untukku."
  },
  AvgDialog_145520_Content_77 = {
    Text = "Suaranya sangat pelan, seolah-olah dengan sedikit saja tenaga, kenangan itu akan tersapu oleh angin dan salju."
  },
  AvgDialog_145520_Content_78 = {
    Text = "Semoga pada akhirnya, kita semua bisa bertemu kembali dengan mereka."
  },
  AvgDialog_145520_Content_79 = {
    Text = "Castor terdiam sejenak, tatapannya melewati dirinya, jatuh ke arah badai putih yang terus bergolak di luar gua."
  },
  AvgDialog_145520_Content_8 = {
    Text = "Tentu saja, bayaran pemandu Sherpa tidak dipungut percuma."
  },
  AvgDialog_145520_Content_80 = {
    Text = "Di tengah obrolan santai, waktu berlalu detik demi detik."
  },
  AvgDialog_145520_Content_82 = {
    Text = "Badai mencapai puncak yang hampir terasa jahat setelah jam ketujuh."
  },
  AvgDialog_145520_Content_83 = {
    Text = "Sepertinya, malam ini kita harus bermalam di dalam gua."
  },
  AvgDialog_145520_Content_84 = {
    Text = "Naraka menyingkirkan sisa-sisa yang sudah lembap di tengah gua, mencoba menyalakan api unggun baru dengan kayu kering."
  },
  AvgDialog_145520_Content_85 = {
    Text = "Dari kegelapan di kedalaman gua, terdengar suara gemerisik kecil, seperti ada sesuatu yang menggaruk dinding batu dengan kuku."
  },
  AvgDialog_145520_Content_86 = {Text = "Ada tikus?"},
  AvgDialog_145520_Content_87 = {
    Text = "Seharusnya tidak ada tikus di ketinggian ini…"
  },
  AvgDialog_145520_Content_88 = {
    Text = "Suara itu tiba-tiba berhenti. Keheningan di dalam gua terasa mencekam."
  },
  AvgDialog_145520_Content_89 = {
    Text = "Dari kegelapan yang begitu pekat hingga tak setitik cahaya pun bisa menembus, sebuah niat jahat angin menerpa wajah."
  },
  AvgDialog_145520_Content_9 = {
    Text = "Para tetua bilang, celah ini tiba-tiba muncul setelah sebuah longsoran salju."
  },
  AvgDialog_145520_Content_90 = {
    Text = "Naraka mengangkat obor, menerangi kedalaman gua mengikuti arah suara. Cahaya api hanya maju beberapa langkah sebelum ditelan kegelapan di depannya."
  },
  AvgDialog_145520_Content_91 = {
    Text = "Jangan ke sana."
  },
  AvgDialog_145520_Content_92 = {
    Text = "Aku hanya ingin melihat sebentar."
  },
  AvgDialog_145520_Content_93 = {
    Text = "Naraka bersandar pada dinding batu, dengan hati-hati menjulurkan tubuhnya."
  },
  AvgDialog_145520_Content_94 = {
    Text = "Cahaya api yang bergoyang melewati tepi batu di bawah kaki, menerangi kolam gelap pekat di bawahnya. Permukaan air begitu halus tanpa satu pun riak, hampir Menjadi satu dengan bayangan Sekitar."
  },
  AvgDialog_145520_Content_95 = {
    Text = "Di Bawah ada air. <Shake:Sepertinya sangat dalam——>"
  },
  AvgDialog_145520_Content_96 = {
    Text = "Belum selesai bicara, \"permukaan air\" hitam pekat itu tiba-tiba amblas ke bawah."
  },
  AvgDialog_145520_Content_97 = {
    Text = "Tubuh Naraka oleng, setengah kakinya sudah menginjak celah yang tiba-tiba melebar."
  },
  AvgDialog_145520_Content_98 = {
    Text = "<Shake:Pegang aku——!>"
  },
  AvgDialog_145520_Content_99 = {
    Text = "Kamu dengan cepat meraih kerah bajunya, menariknya jatuh ke belakang."
  },
  AvgDialog_145521_Content_1 = {
    Text = "Obrolan Malam di Perapian"
  },
  AvgDialog_145521_Content_10 = {
    Text = "Di sudut terdapat beberapa peti kayu yang berjamur, dan di dinding batu yang lebih dalam, terdapat sepotong rantai besi yang patah terpaku di sana."
  },
  AvgDialog_145521_Content_100 = {
    Text = "Dia memejamkan Mata, merasakan lekukan yang tersentuh ujung jarinya."
  },
  AvgDialog_145521_Content_101 = {
    Text = "<Small:……\"Orang jahat memakai sihir, mengubah adik menjadi seekor gagak.\">"
  },
  AvgDialog_145521_Content_102 = {
    Text = "<Small:……\"Tapi kakak mengenali warna sayapnya.\">"
  },
  AvgDialog_145521_Content_103 = {
    Text = "Cahaya api berkedip sekali, lalu meredup kembali."
  },
  AvgDialog_145521_Content_104 = {
    Text = "Bisakah aku membawamu kembali?"
  },
  AvgDialog_145521_Content_105 = {
    Text = "Saat kita bertemu lagi nanti, apakah kamu masih bisa mengenaliku?"
  },
  AvgDialog_145521_Content_107 = {
    Text = "Lama kemudian, ia menutup buku, berdiri, dan berjalan dengan tenang menuju mulut gua, membungkuk untuk membersihkan celah ventilasi yang tersumbat oleh salju malam."
  },
  AvgDialog_145521_Content_108 = {
    Text = "Salju jatuh melalui sela-sela jarinya, menumpuk di atas tumpukan kecil yang sudah ada, tanpa suara."
  },
  AvgDialog_145521_Content_109 = {
    Text = "Fajar belum tiba."
  },
  AvgDialog_145521_Content_11 = {
    Text = "Dulu ada orang yang tinggal di sini?"
  },
  AvgDialog_145521_Content_110 = {
    Text = "Kamu terbangun oleh cahaya lemah yang masuk melalui mulut gua."
  },
  AvgDialog_145521_Content_111 = {
    Text = "Castor sudah membereskan Ransel Perjalanannya, berdiri di mulut gua menunggu kamu bangun."
  },
  AvgDialog_145521_Content_112 = {
    Text = "Maaf, aku bersiap untuk pergi."
  },
  AvgDialog_145521_Content_113 = {
    Text = "Keinginanku berbeda dengan kalian."
  },
  AvgDialog_145521_Content_114 = {
    Text = "Aku ingin menemukan kembali adikku, dan itu bisa kulakukan dengan tanganku sendiri."
  },
  AvgDialog_145521_Content_115 = {
    Text = "Tapi perjalanan ini sangat berbahaya, kamu sendirian——"
  },
  AvgDialog_145521_Content_116 = {
    Text = "…Ada satu hal lagi, aku sempat ragu apakah harus memberitahu kalian. Tapi, sekarang saatnya untuk jujur——"
  },
  AvgDialog_145521_Content_117 = {
    Text = "Castor menarik napas dalam-dalam, seolah telah mengambil keputusan besar."
  },
  AvgDialog_145521_Content_118 = {
    Text = "Saat pertama kali bertemu, Tinct berkata, meski tidak sepopuler Pollux, aku punya kelebihanku sendiri, yaitu bisa meloloskan diri dari pengejaran Gereja Lentera seorang diri."
  },
  AvgDialog_145521_Content_119 = {
    Text = "Tapi itu bohong. Itu untuk menipu kalian."
  },
  AvgDialog_145521_Content_12 = {
    Text = "Tempat berlindung tim pendaki lama, sudah lama ditinggalkan. Posisi tumpukan api unggun ada di sana, aku akan membersihkannya."
  },
  AvgDialog_145521_Content_120 = {
    Text = "Aku jauh lebih lemah dari yang kalian ketahui, aku tidak berhasil melakukannya."
  },
  AvgDialog_145521_Content_121 = {
    Text = "Para pengikut itu terus mengikutiku dengan ketat. Jika aku terus tinggal, aku akan menyeret kalian semua ke dalam masalah."
  },
  AvgDialog_145521_Content_122 = {
    Text = "Ia mengangkat kepalanya, memandang ke arah bagian dalam gua yang lebih dalam, di mana orang-orang lain masih tertidur lelap."
  },
  AvgDialog_145521_Content_123 = {
    Text = "Simbol yang rusak di dalam gua itu, aku mengenalinya, itu adalah simbol Gereja Lentera."
  },
  AvgDialog_145521_Content_124 = {
    Text = "Ini adalah markas sementara mereka."
  },
  AvgDialog_145521_Content_125 = {
    Text = "Semakin ke atas semakin terbuka, cepat atau lambat mereka akan menemukanku. Lebih baik pergi lebih awal, berbaur dengan kerumunan, itu lebih bisa menghindari pengejaran mereka."
  },
  AvgDialog_145521_Content_126 = {
    Text = "Dia berbalik dan melangkah masuk ke dalam angin dan salju."
  },
  AvgDialog_145521_Content_127 = {
    Text = "Kamu berdiri di tempat itu memandang sangat lama, hingga sosoknya benar-benar menghilang."
  },
  AvgDialog_145521_Content_128 = {
    Text = "Dari belakang terdengar suara langkah kaki yang pelan."
  },
  AvgDialog_145521_Content_129 = {
    Text = "Caraboo entah kapan sudah bangun juga, bersandar di mulut gua, memandang ke arah Castor pergi."
  },
  AvgDialog_145521_Content_13 = {
    Text = "Dia dengan terampil berjalan menuju sebuah batu datar yang menghitam terkena asap di tengah gua, berjongkok, dan Mulai menyingkirkan Abu yang sudah lama menumpuk."
  },
  AvgDialog_145521_Content_130 = {
    Text = "……Bodoh."
  },
  AvgDialog_145521_Content_131 = {
    Text = "Dalam nada bicaranya, tidak ada Spike seperti biasanya."
  },
  AvgDialog_145521_Content_132 = {
    Text = "Tim pendaki berkurang dari lima orang menjadi empat orang."
  },
  AvgDialog_145521_Content_14 = {
    Text = "Tatapan Castor sempat berhenti sejenak pada ukiran-ukiran di dinding itu. Dia tidak berkata apa-apa, Hanya Saja memalingkan Tatapannya."
  },
  AvgDialog_145521_Content_15 = {
    Text = "Belum sempat bertanya, semua orang sudah teralihkan Tatapannya oleh Panggilan Caraboo."
  },
  AvgDialog_145521_Content_16 = {
    Text = "<Big:Gua yang hangat! Api unggun! istirahat panjang!>"
  },
  AvgDialog_145521_Content_17 = {
    Text = "Caraboo sangat penuh Keseruan."
  },
  AvgDialog_145521_Content_18 = {
    Text = "Meskipun semua orang memaksakan diri untuk tetap bersemangat, Kamu bisa melihat bahwa semua orang sudah kelelahan akibat pertempuran melawan Wendigo."
  },
  AvgDialog_145521_Content_19 = {
    Text = "Sebuah gua yang pas. Sebuah istirahat yang pas."
  },
  AvgDialog_145521_Content_2 = {
    Text = "Angin dan salju belum berhenti. Kalian menelusuri celah-celah retakan es untuk mencari tempat berlindung, dan akhirnya menemukan sebuah gua salju yang terlindung dari angin di bawah sebuah dinding batu."
  },
  AvgDialog_145521_Content_20 = {
    Text = "Apapun bahaya yang mengintai di depan, tidak dapat menghalangi kalian untuk menikmati sejenak ketenangan saat ini."
  },
  AvgDialog_145521_Content_21 = {
    Text = "Api menyala di sisi dalam mulut gua, agak ke luar. Asap terbawa Angin miring ke luar gua."
  },
  AvgDialog_145521_Content_22 = {
    Text = "Evelyn mengeluarkan selembar alas anti-lembap dari ranselnya, terlebih dahulu menekan lapisan tipis Salju di tanah, lalu menggelar alas tersebut di atasnya."
  },
  AvgDialog_145521_Content_23 = {
    Text = "Semua orang melepas jaket mereka yang kaku karena membeku, berkumpul di sekitar api unggun, mengulurkan tangan sedekat mungkin ke nyala api."
  },
  AvgDialog_145521_Content_24 = {
    Text = "Alangkah baiknya jika di gunung selalu sehangat ini."
  },
  AvgDialog_145521_Content_25 = {Text = "Pff."},
  AvgDialog_145521_Content_26 = {
    Text = "Kenapa kamu tertawa?"
  },
  AvgDialog_145521_Content_27 = {
    Text = "Menertawakanmu yang bodoh karena tidak tahu menjaga ucapan. Bagaimana jika Dewi Salju menganggap ini sebagai keinginanmu yang nyata dan mengabulkannya?"
  },
  AvgDialog_145521_Content_28 = {
    Text = "Itu juga bagus. Kalau begitu, para pendaki gunung akan jauh lebih aman."
  },
  AvgDialog_145521_Content_29 = {
    Text = "Cahaya api unggun terpantul di Mata Castor yang serius."
  },
  AvgDialog_145521_Content_3 = {
    Text = "Mulut gua sempit, namun bagian dalamnya luar biasa luas."
  },
  AvgDialog_145521_Content_30 = {
    Text = "Sudahlah, tidak ada gunanya menggoda orang bodoh sepertimu."
  },
  AvgDialog_145521_Content_31 = {
    Text = "Caraboo, apakah kamu punya keinginan?"
  },
  AvgDialog_145521_Content_32 = {
    Text = "Caraboo tampaknya tidak menyangka akan ditanya secara tiba-tiba, setelah terkejut sejenak, bola matanya berputar-putar."
  },
  AvgDialog_145521_Content_33 = {
    Text = "Akulah Dewi Salju, orang yang bertanggung jawab mengabulkan keinginan kalian!"
  },
  AvgDialog_145521_Content_34 = {
    Text = "Kalau harus menyebut keinginan, maka itu adalah merebut kembali kekuasaanku."
  },
  AvgDialog_145521_Content_35 = {
    Text = "Ya! Benar! Setelah merebut kembali kekuasaan, aku akan membangun kembali Sekte Peri! Membuat seluruh benua Memberi Nafkah kepada Dewi Salju!"
  },
  AvgDialog_145521_Content_36 = {
    Text = "Evelyn tertawa pelan. Cahaya api bergoyang di matanya yang dalam bagai kolam."
  },
  AvgDialog_145521_Content_37 = {
    Text = "Bagaimana dengan yang lain?"
  },
  AvgDialog_145521_Content_38 = {
    Text = "Dia berpaling ke arahmu, namun tatapannya tidak mengandung rasa ingin tahu, hanya kepedulian layaknya Obrolan Rumah biasa."
  },
  AvgDialog_145521_Content_39 = {
    Text = "Aku juga sangat penasaran! Keinginan seperti apa yang harus aku wujudkan untuk {Male=恩公,Female=恩人}?"
  },
  AvgDialog_145521_Content_4 = {
    Text = "Jangan ada yang masuk dulu."
  },
  AvgDialog_145521_Content_40 = {
    Text = "Ada seseorang yang telah menunjukkan Jalan pulang untukku, untuk kembali, aku perlu menemukan seseorang."
  },
  AvgDialog_145521_Content_41 = {
    Text = "Kamu juga bodoh. Bukankah lebih baik langsung memohon untuk kembali?"
  },
  AvgDialog_145521_Content_42 = {
    Text = "Ada seseorang yang pernah menuliskan Ramalan untukku."
  },
  AvgDialog_145521_Content_43 = {
    Text = "<Yellow:nasib adalah benang yang saling terkait, siapa pun yang mencoba melompati setiap simpul untuk langsung mencapai tujuan akhir, pasti akan menanggung penderitaan akibat benang yang putus.>"
  },
  AvgDialog_145521_Content_44 = {
    Text = "Mengerti. Lalu bagaimana dengan Tuan William di sisimu ini?"
  },
  AvgDialog_145521_Content_45 = {
    Text = "Kisah William, kalau diceritakan, agak rumit."
  },
  AvgDialog_145521_Content_46 = {
    Text = "Setidaknya untuk saat ini, hal terpenting bagiku adalah menemani %player% kembali ke Mythag, kembali ke sisi Ramona."
  },
  AvgDialog_145521_Content_47 = {
    Text = "Kamu menatap William dengan terkejut. Wajahnya tenang, dan kamu tidak bisa menemukan sedikit pun tanda kebohongan dalam Ekspresi mikronya."
  },
  AvgDialog_145521_Content_48 = {
    Text = "Tidak perlu menatapku seperti itu."
  },
  AvgDialog_145521_Content_49 = {
    Text = "<Yellow:Misi lainku di dunia ini telah berakhir untuk sementara.>"
  },
  AvgDialog_145521_Content_5 = {
    Text = "Dia mengangkat beliung es, mengetuk satu per satu sepanjang bagian atas sisi dalam mulut gua."
  },
  AvgDialog_145521_Content_50 = {
    Text = "Saat mengucapkan kalimat itu, William sengaja mengangkat tangan menyibak helai rambut yang menutupi Matanya, menutupi sebagian besar Ekspresinya."
  },
  AvgDialog_145521_Content_51 = {
    Text = "Lalu bagaimana denganmu, si bodoh?"
  },
  AvgDialog_145521_Content_52 = {Text = "Aku?"},
  AvgDialog_145521_Content_53 = {
    Text = "Castor menatap api unggun dengan pandangan kosong."
  },
  AvgDialog_145521_Content_54 = {
    Text = "Aku ingin Pollux… kembali."
  },
  AvgDialog_145521_Content_55 = {
    Text = "Caraboo mengangkat Mata menatap Castor, sedikit sikap sinis sehari-harinya dalam tatapan itu sejenak menghilang."
  },
  AvgDialog_145521_Content_56 = {
    Text = "Kamu baru saja bilang, kamu ingin dia kembali."
  },
  AvgDialog_145521_Content_57 = {
    Text = "Tapi saat pertama kali kita bertemu, kamu bilang kamu ingin menyelamatkannya."
  },
  AvgDialog_145521_Content_58 = {
    Text = "Ada perbedaan halus di antara kedua ungkapan itu… tapi belum tentu tidak bisa disatukan."
  },
  AvgDialog_145521_Content_59 = {
    Text = "Castor, adikmu, apakah benar-benar dipenjara oleh pemimpin sekte itu?"
  },
  AvgDialog_145521_Content_6 = {
    Text = "Bagian ini Longgar, hindari tepat di bawahnya saat berkemah."
  },
  AvgDialog_145521_Content_60 = {
    Text = "Keheningan sejenak. Caraboo mengambil Apel dan menggigitnya lagi, seolah tidak ada yang terjadi sambil mengalihkan topik pembicaraan."
  },
  AvgDialog_145521_Content_61 = {
    Text = "Sebenarnya, mewujudkan keinginan itu sangat mudah, lho."
  },
  AvgDialog_145521_Content_62 = {
    Text = "Lihat, di antara tujuh harta itu bukankah ada sehelai bulu? Siapa tahu bulu yang ada di tubuhmu itu adalah <Yellow:Bulu Maat>."
  },
  AvgDialog_145521_Content_63 = {
    Text = "Maat, dewi kebenaran, keteraturan, dan keadilan, mengenakan sehelai bulu burung unta di kepalanya."
  },
  AvgDialog_145521_Content_64 = {
    Text = "Saat penghakiman Mayat Hidup, Anubis akan meletakkan jantung si Mayat Hidup bersama bulu ini di atas timbangan. Jika jantung lebih berat dari bulu, ia akan di-Devour oleh monster Ammit; jika jantung seringan bulu, ia boleh memasuki Padang Alang-alang."
  },
  AvgDialog_145521_Content_65 = {
    Text = "Bulu adalah satu-satunya definisi \"tak bersalah\" bagi peradaban ini."
  },
  AvgDialog_145521_Content_66 = {
    Text = "Bulu tanpa dosa... sungguh ironis."
  },
  AvgDialog_145521_Content_67 = {
    Text = "Castor menampilkan senyum yang tampak sedikit pasrah."
  },
  AvgDialog_145521_Content_68 = {
    Text = "Sepasang Sayap ini diImplan untukku dan adikku oleh Juliette, pemimpin Gereja Lentera, demi Produksi Dewa miliknya."
  },
  AvgDialog_145521_Content_69 = {
    Text = "Dalam tuturannya, kamu mendengar sebuah suara. Suara kesakitan yang tak tertahankan."
  },
  AvgDialog_145521_Content_7 = {
    Text = "Dia berjalan membungkuk ke bagian gua yang lebih dalam, berjongkok menempelkan telinga ke tanah untuk mendengarkan sejenak, lalu menguji kelembapan permukaan batu dengan punggung tangannya."
  },
  AvgDialog_145521_Content_70 = {
    Text = "Kemudian, dia mencabut kedua Sayap Pollux. Sekarang, hanya aku yang masih menyisakan sepasang Sayap yang Menodai ini."
  },
  AvgDialog_145521_Content_71 = {
    Text = "Castor perlahan membelai Bulu di ujung sayapnya, dan kamu tiba-tiba merasa bahwa di sana penuh dengan noda Darah."
  },
  AvgDialog_145521_Content_72 = {
    Text = "Jadi, kalau bicara soal tidak bersalah... sepasang Sayap ini mungkin adalah keberadaan yang paling jauh dari tidak bersalah."
  },
  AvgDialog_145521_Content_73 = {
    Text = "Udara menjadi sunyi, hanya ada suara derak api unggun yang Membakar."
  },
  AvgDialog_145521_Content_74 = {
    Text = "Naraka, lalu apa keinginanmu?"
  },
  AvgDialog_145521_Content_75 = {
    Text = "William tiba-tiba berpaling ke arah Naraka yang sedang menghangatkan diri di dekat api dan tampaknya tidak berniat ikut dalam pembicaraan."
  },
  AvgDialog_145521_Content_76 = {
    Text = "Aku Hanya Saja seorang pemandu, tidak berniat membuat permintaan bersama kalian."
  },
  AvgDialog_145521_Content_77 = {
    Text = "Jika harus menyebut <Yellow:keinginan Naraka>, mungkin dia berharap nama pemandu Sherpa juga bisa tercatat dalam Riwayat para pendaki."
  },
  AvgDialog_145521_Content_78 = {
    Text = "Tapi keinginan semacam itu, terlalu membosankan jika diwujudkan lewat mukjizat, bukan?"
  },
  AvgDialog_145521_Content_79 = {
    Text = "Membuat Kebohongan melintasi Riwayat melalui penyusunan dan pemalsuan buku, terlalu mudah, terlalu gampang, begitu gampang hingga kehilangan nilainya."
  },
  AvgDialog_145521_Content_8 = {
    Text = "Masuklah, Di Dalam seharusnya aman."
  },
  AvgDialog_145521_Content_80 = {
    Text = "Urusan mencapai puncak, tetap harus diwujudkan dengan kaki sendiri."
  },
  AvgDialog_145521_Content_81 = {
    Text = "Dengan diri sendiri..."
  },
  AvgDialog_145521_Content_82 = {
    Text = "Castor seolah-olah merasakan sesuatu."
  },
  AvgDialog_145521_Content_83 = {
    Text = "Hei— kamu tidak terlihat seperti orang yang akan mengucapkan hal-hal benar seperti itu."
  },
  AvgDialog_145521_Content_84 = {
    Text = "Caraboo mencubit hidungnya dan mengipas-ngipaskan tangan, seolah-olah mencium bau busuk."
  },
  AvgDialog_145521_Content_85 = {
    Text = "Sesi kejujuran, jangan berpura-pura, ngobrol yang tulus dong?"
  },
  AvgDialog_145521_Content_86 = {
    Text = "Dia menatap mata Naraka dengan penuh kesenangan, Naraka menghindar dengan tatapannya, dia membungkuk, tatapannya terus mengejar tanpa mau lepas."
  },
  AvgDialog_145521_Content_87 = {
    Text = "<Shake:Ayo, biarkan aku melihat wujud aslimu——>"
  },
  AvgDialog_145521_Content_88 = {
    Text = "Caraboo melompat ke depan, ingin menangkap Naraka seperti elang menangkap anak ayam, tapi Naraka hanya sedikit memiringkan tubuh dan menghindarinya."
  },
  AvgDialog_145521_Content_89 = {
    Text = "Sudah, jangan ribut, besok masih harus melanjutkan Jalan. Aku tidak mau kalian tidak sampai ke puncak gunung."
  },
  AvgDialog_145521_Content_9 = {
    Text = "Di dinding batu terdapat sisa-sisa motif yang memudar, seperti garis luar suatu tanda, catnya sudah mengelupas hingga sulit dikenali."
  },
  AvgDialog_145521_Content_90 = {
    Text = "Caraboo melompat tapi meleset, dan langsung duduk begitu saja di atas salju, tersenyum lebar."
  },
  AvgDialog_145521_Content_91 = {
    Text = "Kalau kamu juga ingin kami mencapai puncak, aku jadi tenang."
  },
  AvgDialog_145521_Content_93 = {
    Text = "Api unggun menyala hingga tengah malam, hanya menyisakan percikan cahaya merah yang bertahan di antara abu."
  },
  AvgDialog_145521_Content_94 = {
    Text = [[
Naraka membagi giliran jaga malam, masing-masing dua jam.
Semua orang pun tidur satu per satu. Dari dalam kantong tidur terdengar suara dengkuran yang pelan dan tertahan.]]
  },
  AvgDialog_145521_Content_95 = {
    Text = "Castor secara alami mengambil giliran pertama. Dia bersandar di dinding gua, dan dari kedalaman Ransel Perjalanannya, mengeluarkan sebuah buku kecil yang sudut-sudutnya sudah lusuh memutih."
  },
  AvgDialog_145521_Content_96 = {
    Text = "Itu adalah sebuah Buku Dongeng."
  },
  AvgDialog_145521_Content_97 = {
    Text = "Ujung jarinya menyentuh dua nama yang tertera di halaman judul."
  },
  AvgDialog_145521_Content_98 = {
    Text = "Tulisan tangan anak-anak yang rapi berasal dari dirinya sendiri, sementara yang satu lagi ditulis dengan krayon merah yang miring-miring, warnanya perlahan memudar seiring waktu yang mengusapnya."
  },
  AvgDialog_145521_Content_99 = {Text = "Pollux…"},
  AvgDialog_145522_Content_1 = {
    Text = "Jangan Menjawab"
  },
  AvgDialog_145522_Content_10 = {
    Text = "Castor berjalan di ujung barisan, dia lebih pendiam dari biasanya."
  },
  AvgDialog_145522_Content_11 = {
    Text = "Hei, si bengong. Kamu kedinginan?"
  },
  AvgDialog_145522_Content_12 = {
    Text = "Tidak terlalu."
  },
  AvgDialog_145522_Content_13 = {
    Text = "Aku juga. Ini sungguh aneh."
  },
  AvgDialog_145522_Content_14 = {
    Text = "Kalau begitu, suara napas yang begitu berat dan kasar itu, milik siapa?"
  },
  AvgDialog_145522_Content_15 = {
    Text = "Barisan berhenti. Semua orang serentak berbalik. Di belakang mereka hanya ada jejak kaki mereka sendiri, dalam dan dangkal silih berganti."
  },
  AvgDialog_145522_Content_16 = {
    Text = "Di tepi jejak kaki itu, saljunya sangat bersih. Bersih seolah-olah telah dilap perlahan oleh sesuatu."
  },
  AvgDialog_145522_Content_17 = {
    Text = "Sunyi. Hanya Angin. Angin berhembus dari tempat yang sangat jauh, melingkari punggung gunung, menyelinap ke kerah baju setiap orang."
  },
  AvgDialog_145522_Content_18 = {
    Text = "Di dalam Angin terselip suara yang Hampir tidak terdengar. Itu bukan nyanyian. Itu adalah Panggilan."
  },
  AvgDialog_145522_Content_19 = {
    Text = "<Change>……Eve, lyn, Evelyn……"
  },
  AvgDialog_145522_Content_2 = {
    Text = "Angin dan salju mereda, namun langit justru terlihat lebih suram dibanding saat badai salju sedang mengamuk."
  },
  AvgDialog_145522_Content_20 = {Text = "?!"},
  AvgDialog_145522_Content_21 = {
    Text = "Dia berbalik dengan tiba-tiba. Lapangan Salju itu luas dan kosong, tidak ada apa pun. Namun suara itu datang lagi, kali ini lebih dekat, membawa kelembutan yang hampir terasa kejam."
  },
  AvgDialog_145522_Content_22 = {
    Text = "<Change>……Evelyn……aku kedinginan……"
  },
  AvgDialog_145522_Content_23 = {Text = "Ini…"},
  AvgDialog_145522_Content_24 = {
    Text = "<Shake:Tidak mungkin…>"
  },
  AvgDialog_145522_Content_25 = {
    Text = "Wajahnya seketika pucat pasi. Bibirnya memutih, suaranya gemetar, seolah momen yang telah dia bayangkan berkali-kali akhirnya tiba."
  },
  AvgDialog_145522_Content_26 = {
    Text = "Kalian… kalian semua mendengarnya?!"
  },
  AvgDialog_145522_Content_27 = {Text = "Itu dia."},
  AvgDialog_145522_Content_28 = {
    Text = "<Shake:Itu suaranya……>"
  },
  AvgDialog_145522_Content_29 = {
    Text = "Nona Evelyn, siapa pun yang kamu dengar, tolong jangan meresponsnya."
  },
  AvgDialog_145522_Content_3 = {
    Text = "Lapisan awan abu-abu timah menggantung rendah di atas punggung gunung, seperti lapisan Mimpi lama yang berat dan enggan pergi."
  },
  AvgDialog_145522_Content_30 = {
    Text = "Kalian menahan napas. Angin Lapangan Salju berhembus melewati telinga kalian, lalu— \nKalian semua juga mendengarnya."
  },
  AvgDialog_145522_Content_31 = {
    Text = "Angin berubah menjadi tak terhitung suara, tak terhitung Panggilan yang membelai. Setiap satu berhembus dari arah yang pernah kamu kenal, dan pernah kamu kehilangan."
  },
  AvgDialog_145522_Content_32 = {
    Text = "Suara. Suara memanggil kamu. Dingin dan jernih."
  },
  AvgDialog_145522_Content_33 = {
    Text = "<Change>Aku menunggumu, partner."
  },
  AvgDialog_145522_Content_34 = {
    Text = "<Change>Jangan tertinggal, kita akan mencapai ujung jalan ini bersama-sama."
  },
  AvgDialog_145522_Content_35 = {Text = "Ramona..."},
  AvgDialog_145522_Content_36 = {
    Text = "Kamu menggigit gigi, Menahan keinginan untuk mengikuti."
  },
  AvgDialog_145522_Content_37 = {
    Text = "Kakimu seolah membeku di dalam salju, tidak mau menuruti perintahmu. Kamu bisa merasakan sebuah kekuatan yang sangat ringan dan sangat lembut, dari arah suara itu, perlahan-lahan, perlahan-lahan, menarik titik beratmu ke depan."
  },
  AvgDialog_145522_Content_38 = {
    Text = "Itu adalah Undangan. Undangan yang tidak bisa ditolak."
  },
  AvgDialog_145522_Content_39 = {
    Text = "Asalkan kamu mau melangkah maju satu langkah, kamu bisa kembali ke momen hangat mana pun di masa lalu—"
  },
  AvgDialog_145522_Content_4 = {
    Text = "Tidak ada yang berbicara. Anjing-anjing pemandu berjalan paling depan, bahkan mereka pun menekan rintihan kebiasaan di tenggorokan mereka."
  },
  AvgDialog_145522_Content_40 = {Text = "Penjaga—"},
  AvgDialog_145522_Content_41 = {
    Text = "Suara William datang dari tempat yang sangat jauh. Baru saat itulah kamu Menemukan dirimu telah melangkah setengah langkah tanpa tahu kapan."
  },
  AvgDialog_145522_Content_42 = {
    Text = "Di sisi kalian, beberapa anjing pemandu sudah terkoyak tenggorokannya, darah yang menyembur mewarnai hamparan salju putih dengan beberapa bercak merah yang menyilaukan."
  },
  AvgDialog_145522_Content_43 = {Text = "Mundur."},
  AvgDialog_145522_Content_44 = {
    Text = "Berikan tanganmu padaku."
  },
  AvgDialog_145522_Content_45 = {
    Text = "Wajah William pucat seperti kertas, tangannya yang menggenggam lenganmu gemetar tanpa disadari."
  },
  AvgDialog_145522_Content_46 = {
    Text = "Kamu bisa merasakan dia sedang berusaha keras Menahan dirinya, Menahan diri agar tidak terperdaya oleh suara itu."
  },
  AvgDialog_145522_Content_47 = {
    Text = "Suara itu palsu. Kalian harus tersadar."
  },
  AvgDialog_145522_Content_48 = {
    Text = "Dia berkata dengan suara yang sangat pelan, seolah sedang mengumumkan sebuah Putusan."
  },
  AvgDialog_145522_Content_49 = {
    Text = "<Shake:<Small:Ugh… Bibi Rosa…>>"
  },
  AvgDialog_145522_Content_5 = {
    Text = "Berjalanlah lebih lambat, medannya tidak beres."
  },
  AvgDialog_145522_Content_50 = {
    Text = "Caraboo tersadar dari mimpi, masih bergumam sesuatu."
  },
  AvgDialog_145522_Content_51 = {
    Text = "Tapi tidak semua orang bisa terbangun."
  },
  AvgDialog_145522_Content_52 = {
    Text = "Pollux…! Pollux…! Kamu di mana?!"
  },
  AvgDialog_145522_Content_53 = {
    Text = "<Shake:<Big:Pollux…!!!>>"
  },
  AvgDialog_145522_Content_54 = {
    Text = "<Italic:…Kak, aku kedinginan…>"
  },
  AvgDialog_145522_Content_55 = {
    Text = "<Italic:Kak, ruang isolasi itu sangat gelap, sangat pekat, sangat menakutkan… kumohon… biarkan aku keluar… Tuan Pemimpin…>"
  },
  AvgDialog_145522_Content_56 = {
    Text = "<Shake:<Italic:…Kak, kenapa kamu tidak datang mencari aku…>>"
  },
  AvgDialog_145522_Content_57 = {
    Text = "Pollux!! Tunggu aku, aku segera datang—"
  },
  AvgDialog_145522_Content_58 = {
    Text = "<Shake:Hei, orang bodoh, berhenti!>"
  },
  AvgDialog_145522_Content_59 = {
    Text = "Mengabaikan Panggilan kalian, Castor berlari keluar."
  },
  AvgDialog_145522_Content_6 = {
    Text = "Bagian ini dulunya lereng lurus, sekarang sudah retak membentuk jurang melintang."
  },
  AvgDialog_145522_Content_60 = {
    Text = "<Shake:Tangkap dia!>"
  },
  AvgDialog_145522_Content_61 = {
    Text = "Jangan biarkan orang bodoh itu tertipu!"
  },
  AvgDialog_145522_Content_7 = {
    Text = "Ini retakan baru yang terbentuk setelah longsoran salju terakhir… seharusnya tidak sedalam ini."
  },
  AvgDialog_145522_Content_8 = {
    Text = "Bentuk gunung ini sedang berubah."
  },
  AvgDialog_145522_Content_9 = {
    Text = "William tidak melanjutkan perkataannya. Kedua matanya yang berwarna hijau menatap kejauhan, alisnya sedikit berkerut."
  },
  AvgDialog_145523_Content_1 = {
    Text = "Puncak Tanpa Keinginan"
  },
  AvgDialog_145523_Content_10 = {
    Text = "William perlahan berjongkok, ujung jarinya menyentuh ukiran-ukiran rumit di antara alas altar yang semula kamu anggap hanya sebagai hiasan."
  },
  AvgDialog_145523_Content_100 = {
    Text = "<Shake:Hentikan, hentikan ini! Kalau terus begini, <Red:aku akan mati sebelum permohonanku terkabul!>>"
  },
  AvgDialog_145523_Content_101 = {
    Text = "Itu tidak termasuk dalam perjanjian kita."
  },
  AvgDialog_145523_Content_102 = {
    Text = "Memang, dia hanya berjanji memulai ritual untukmu, bukan berjanji bahwa kau masih bisa hidup setelah ritual selesai."
  },
  AvgDialog_145523_Content_103 = {
    Text = "Ternyata begitu, setiap kata yang diucapkan Senior William adalah benar… namun teknik montase yang digunakan menyusunnya menjadi ilusi yang sepenuhnya palsu."
  },
  AvgDialog_145523_Content_104 = {
    Text = "Lingkaran cahaya keenam bangkit."
  },
  AvgDialog_145523_Content_105 = {
    Text = "Seluruh gunung bergetar sekarat. Tak terhitung daging pucat bermunculan dari celah bebatuan yang retak, mengalir bagai ombak besar menuju altar."
  },
  AvgDialog_145523_Content_106 = {
    Text = "Tidak! Itu milikku! Caro-ku! Kekuatanku! Keinginanku!"
  },
  AvgDialog_145523_Content_107 = {
    Text = "Atau mungkin mereka tidak pernah menjadi milikmu, tidak pernah menjadi kekuatanmu. Itu adalah harapan yang dipersembahkan oleh tak terhitung banyaknya peziarah kepada gunung ini."
  },
  AvgDialog_145523_Content_108 = {
    Text = "Kekuatan itu milik semua orang yang kau tipu, kau telan, dan kau kubur di sini. Kau tidak berhak memilikinya."
  },
  AvgDialog_145523_Content_109 = {
    Text = "Sekarang, mereka hanya kembali ke tempat yang seharusnya."
  },
  AvgDialog_145523_Content_11 = {
    Text = "Tidak mungkin… bagaimana bisa… tanda-tanda unik di samping pola altar ini… aku mengenalinya."
  },
  AvgDialog_145523_Content_110 = {
    Text = "Tinct, Castor, Evelyn, dan Fengol yang belum pernah kau temui…"
  },
  AvgDialog_145523_Content_111 = {
    Text = "Wajah demi wajah, nama demi nama muncul di benakmu, lalu menyelam ke kedalaman ingatan."
  },
  AvgDialog_145523_Content_112 = {
    Text = "<BigShake:Jangan harap! Jangan harap!>"
  },
  AvgDialog_145523_Content_113 = {
    Text = "Sebelum kekuatanku terkuras habis, <Big:<Red:aku akan menghancurkan altar terlebih dahulu, lalu mengunyah kalian satu per satu!>>"
  },
  AvgDialog_145523_Content_114 = {
    Text = "William mengangguk kepadamu."
  },
  AvgDialog_145523_Content_115 = {
    Text = "Masing-masing lakukan tugasnya, aku akan menjaga jalannya ritual."
  },
  AvgDialog_145523_Content_116 = {
    Text = "Tugas menghentikan-Nya, serahkan padaku!"
  },
  AvgDialog_145523_Content_12 = {
    Text = "Ini adalah karya Fengol."
  },
  AvgDialog_145523_Content_13 = {Text = "Fengol?"},
  AvgDialog_145523_Content_14 = {
    Text = "Kamu tahu nama itu. Mitra William, Penyelidik yang menghilang dari \"dunia itu\" sebelum dia."
  },
  AvgDialog_145523_Content_15 = {
    Text = "Rupanya begitu, Kunci Solomon… alasan mengapa cacing tidak dapat memulai ritual… dan juga tujuan Fengol datang ke dunia ini…"
  },
  AvgDialog_145523_Content_16 = {
    Text = "Hahaha, rupanya begitu, menarik, menarik, sungguh menarik!"
  },
  AvgDialog_145523_Content_17 = {
    Text = "Sang penenun yang selalu sibuk itu menyuruhku membawa kalian ke puncak, rupanya untuk memperlihatkan hiburan ini kepadaku!"
  },
  AvgDialog_145523_Content_18 = {
    Text = "Apa maksudmu?"
  },
  AvgDialog_145523_Content_19 = {
    Text = "N mengangkat bahunya."
  },
  AvgDialog_145523_Content_2 = {
    Text = "Itu adalah sebuah altar yang sangat besar, Seolah-olah sama tuanya dengan seluruh pegunungan ini."
  },
  AvgDialog_145523_Content_20 = {
    Text = "Penerjemahnya adalah dia, bukan aku. Meskipun kesepakatan dia juga membebaskanku, tapi apakah aku terlihat seperti orang yang tahu membalas budi?"
  },
  AvgDialog_145523_Content_21 = {
    Text = "Biar aku yang menjelaskan."
  },
  AvgDialog_145523_Content_22 = {
    Text = "\"Kunci Solomon\" sebenarnya bukan kunci, melainkan sebuah kitab sihir."
  },
  AvgDialog_145523_Content_23 = {
    Text = "Dan isi terpenting yang tercatat dalam kitab sihir itu adalah metode Memanggil tujuh puluh dua iblis Solomon. Dengan kata lain, cara untuk menghubungkan dunia-dunia."
  },
  AvgDialog_145523_Content_24 = {
    Text = "Dia mengangkat kepalanya, memandang ke tepat tengah tujuh alas itu — sebuah lubang kunci yang sempit, Hampir menyatu dengan bayangan."
  },
  AvgDialog_145523_Content_25 = {
    Text = "Tanda-tanda ini adalah sandi rahasia yang Hanya bisa dibaca olehnya dan aku."
  },
  AvgDialog_145523_Content_26 = {
    Text = "William mengeja ukiran di tanah satu per satu, kata demi kata, dan tulisan-tulisan yang tak bersuara itu perlahan menyusun sebuah suara yang familiar di benaknya."
  },
  AvgDialog_145523_Content_27 = {
    Text = [[
Apakah itu William? Aku tahu kamu bisa sampai ke sini. 

Formasi sihir yang terukir di sini mengandung tiga jenis bahasa kuno, kurasa hanya kamu si murid teladan dalam kelompok kita yang bisa membacanya sekaligus tanpa henti. 
Mereka adalah mantra pemanggilan dan penyegelan. Kamu seharusnya memahami arti kedua kata itu.]]
  },
  AvgDialog_145523_Content_28 = {
    Text = "Pembukaan dan penutupan \"Pintu\"."
  },
  AvgDialog_145523_Content_29 = {
    Text = [[
Singkatnya, formasi sihir ini menggunakan "Mahkota" sebagai perantara, menghubungkan titik asal dunia ini. Oleh karena itu, khusus di dunia ini, ia benar-benar dapat mewujudkan segala keinginan.

Apakah kamu pernah bertanya-tanya mengapa kamu bisa datang ke dunia asing ini?

Sekarang, aku bisa menjawabmu.

Kamu adalah keinginan itu sendiri.]]
  },
  AvgDialog_145523_Content_3 = {
    Text = "Anak tangga melingkar berlapis-lapis menuju ke atas, di ujungnya berdiri tujuh alas kosong yang tersusun membentuk lingkaran. Di antara satu alas dengan alas lainnya, dalam alur-alur kuno tertentu, mengendap cahaya keemasan gelap yang telah lama mengering."
  },
  AvgDialog_145523_Content_30 = {
    Text = [[
Sayangnya, kekuatan yang aku kerahkan belum cukup banyak, hanya mampu membuka sedikit celah untuk Perak-mu.

Tujuan akhir yang tidak berhasil aku capai, perlu kamu capai untukku.

Lagipula, kamu adalah Penyelidik legendaris William, bukan?]]
  },
  AvgDialog_145523_Content_31 = {
    Text = [[
Tak banyak yang perlu dikatakan, semoga kamu sudah mengambil Kunci perak milikku.

Gunakanlah untuk mengaktifkan formasi sihir, lalu ucapkan keinginanmu, Dia akan membawamu menuju tanah yang dijanjikan.

Jalan selanjutnya, serahkan pada dirimu sendiri.

Dengan tulus, Fengol.]]
  },
  AvgDialog_145523_Content_32 = {
    Text = "Jari-jari William berhenti."
  },
  AvgDialog_145523_Content_33 = {
    Text = "Dia terdiam sangat lama. Kamu belum pernah melihat ekspresi seperti itu di wajahnya."
  },
  AvgDialog_145523_Content_34 = {Text = "%player%."},
  AvgDialog_145523_Content_35 = {Text = "Saya ada."},
  AvgDialog_145523_Content_36 = {
    Text = "Bukankah kamu dulu pernah bertanya padaku, mengapa aku adalah orang pertama yang terbangun di bawah Panggilan Wendigo?"
  },
  AvgDialog_145523_Content_37 = {
    Text = "Karena aku adalah satu-satunya di antara kita yang pernah melihat tulang belulangnya."
  },
  AvgDialog_145523_Content_38 = {
    Text = "Tubuhnya sudah membusuk sepenuhnya, sama sekali tidak bisa dikenali Identitasnya. Tapi aku mengenali setengah Kunci perak yang ada di tubuhnya."
  },
  AvgDialog_145523_Content_39 = {
    Text = "Nomor I-1021, angka milik Fengol. Setiap kali sebuah angka menghilang dari catatan, kami tahu ada satu lagi pendahulu yang telah dilupakan dunia."
  },
  AvgDialog_145523_Content_4 = {
    Text = "Inilah tempat tujuan akhir di mana Cacing Gunung menggunakan permohonan sebagai umpan untuk menarik tak terhitung banyaknya pendaki gunung."
  },
  AvgDialog_145523_Content_40 = {
    Text = "Sejak saat itu, aku selalu membawa Kunci perak ini di dekat tubuhku."
  },
  AvgDialog_145523_Content_41 = {
    Text = "Ia memejamkan mata. Saat membukanya kembali, di dalam sepasang Mata hijau itu, hanya tersisa sesuatu yang tenang dan tidak tergoyahkan."
  },
  AvgDialog_145523_Content_42 = {
    Text = "…Fengol, terima kasih atas kepercayaan yang kamu berikan."
  },
  AvgDialog_145523_Content_43 = {
    Text = "Cacing Gunung, aku akan menjelaskan cara mengaktifkan formasi sihir ini kepadamu."
  },
  AvgDialog_145523_Content_44 = {
    Text = "Persembahkan keinginan kepada Manusia Gunung, kekuatan yang mereka miliki akan menjadi sumber formasi sihir, sehingga menghubungkan \"titik asal\" dunia."
  },
  AvgDialog_145523_Content_45 = {
    Text = "\"Titik asal\" dunia?"
  },
  AvgDialog_145523_Content_46 = {
    Text = "Jika tebakanku tidak salah, itu adalah \"Matahari Hitam\" di langit."
  },
  AvgDialog_145523_Content_47 = {
    Text = "Keberadaan Matahari Hitam sangat mirip dengan \"Kolam Hitam\" milik Mythag, mencakup segalanya, merupakan sisa-sisa segala sesuatu yang telah musnah di masa lalu dan masa depan yang tersuspensi dalam arus pasang erosi."
  },
  AvgDialog_145523_Content_48 = {
    Text = "Skala perwujudan keinginan bergantung pada seberapa banyak air pasang yang ingin diambil oleh si pemohon dari \"Matahari Hitam\"."
  },
  AvgDialog_145523_Content_49 = {
    Text = "Anak kecil, bantu aku awasi mata orang ini. Pastikan dia tidak berbohong."
  },
  AvgDialog_145523_Content_5 = {
    Text = "Tidak pernah ada seorang pun yang bisa meninggalkan tempat ini dalam keadaan hidup. Semua pendaki, mereka semua berada di bawah kaki kita, di dalam perut gunung."
  },
  AvgDialog_145523_Content_50 = {
    Text = "Caraboo dengan enggan melangkah maju, menatap ke atas ke arah kedua mata William."
  },
  AvgDialog_145523_Content_52 = {
    Text = "William memejamkan mata, menggelengkan kepala dengan lembut."
  },
  AvgDialog_145523_Content_53 = {
    Text = "Setiap kata yang dia ucapkan adalah kebenaran."
  },
  AvgDialog_145523_Content_54 = {
    Text = "<Shake:Jangan bohongi aku! Kamu ragu, kamu penipu kecil!>"
  },
  AvgDialog_145523_Content_55 = {
    Text = "Apakah yang aku katakan benar atau salah, kamu lebih tahu dariku."
  },
  AvgDialog_145523_Content_56 = {
    Text = "Cacing Gunung mengeluarkan tawa dingin, salju pun berjatuhan bersamanya."
  },
  AvgDialog_145523_Content_57 = {
    Text = "Hmph, yang terpenting sekarang adalah ritualnya. Setelah semua ini selesai, aku akan menghukummu, pengkhianat."
  },
  AvgDialog_145523_Content_58 = {
    Text = "Katakan padaku, Cacing Gunung, keinginan berskala apa yang ingin kamu wujudkan?"
  },
  AvgDialog_145523_Content_59 = {
    Text = "Hihihi, itu sudah pasti! Tentu saja semakin banyak semakin baik, semakin banyak semakin baik! Aku ingin menelan seluruh dunia ke dalam perutku, tak pernah habis, tak pernah kerontang!"
  },
  AvgDialog_145523_Content_6 = {
    Text = "Kurangi omong kosong. Mulai tafsirkan formasi sihir."
  },
  AvgDialog_145523_Content_60 = {
    Text = "Sungguh makhluk bodoh yang serakah, mungkin belajar untuk tahu batas akan lebih baik untukmu?"
  },
  AvgDialog_145523_Content_61 = {
    Text = "Makhluk kacau sepertimu mana bisa mengerti, jika aku mengikuti aturan, aku tidak akan bisa sampai sejauh ini."
  },
  AvgDialog_145523_Content_62 = {
    Text = "\"Sejauh ini\" yang kamu banggakan itu maksudnya, merangkak di atas gunung, menjadi seekor ulat yang gemuk dan besar?"
  },
  AvgDialog_145523_Content_63 = {
    Text = "Aduh… sudahlah, memang hampir tidak ada yang mau mendengarkan nasihat baik dari N."
  },
  AvgDialog_145523_Content_64 = {
    Text = "Aku mengerti."
  },
  AvgDialog_145523_Content_65 = {
    Text = "William mengangguk."
  },
  AvgDialog_145523_Content_66 = {
    Text = "Untuk mewujudkan keinginan dengan skala tertinggi, semua persembahan harus dipersembahkan sepenuhnya."
  },
  AvgDialog_145523_Content_67 = {
    Text = "<BigShake:Ambillah!> Mereka ada untuk momen ini."
  },
  AvgDialog_145523_Content_68 = {
    Text = "%player%, berikan Korban itu padaku."
  },
  AvgDialog_145523_Content_69 = {
    Text = "Kamu membuka koper itu."
  },
  AvgDialog_145523_Content_7 = {
    Text = "Suara Cacing Gunung terdengar dari bawah kaki. Kali ini, nada bicaranya tidak lagi hanya mengandung ejekan, melainkan juga menyimpan suatu kegelisahan yang telah lama terpendam selama bertahun-tahun."
  },
  AvgDialog_145523_Content_70 = {
    Text = "Apel Emas, Yata no Kagami, Bulu Maat, Mata Balor, Benang Dewi Nasib, Mahkota Ariadne… dan Kunci Perak itu sendiri."
  },
  AvgDialog_145523_Content_71 = {
    Text = "Tujuh persembahan menyatu satu per satu dengan alasnya, di dalam alur kuno itu, cahaya emas gelap kembali mengalir dan mengalir deras, menyambung menjadi sebuah lingkaran yang utuh."
  },
  AvgDialog_145523_Content_72 = {
    Text = "<Shake:Hahaha! Akhirnya… akhirnya!>"
  },
  AvgDialog_145523_Content_73 = {
    Text = "Gunung akan menikmati perjamuan-Nya, Gunung akan mencurahkan seluruh koleksi-Nya."
  },
  AvgDialog_145523_Content_74 = {
    Text = "Gunung telah lama merindukan ini."
  },
  AvgDialog_145523_Content_75 = {
    Text = "William menggenggam Kunci yang satu-satunya itu, lalu memasukkannya ke dalam lubang kunci."
  },
  AvgDialog_145523_Content_76 = {
    Text = "Atas nama Fengol—"
  },
  AvgDialog_145523_Content_77 = {
    Text = "<Red:Mulai.>"
  },
  AvgDialog_145523_Content_78 = {Text = "Klik."},
  AvgDialog_145523_Content_79 = {
    Text = "Sebuah bunyi ringan terdengar, tujuh persembahan serentak memancarkan cahaya yang menyilaukan."
  },
  AvgDialog_145523_Content_8 = {
    Text = "Semua pandangan tertuju pada tulisan-tulisan misterius yang memenuhi altar."
  },
  AvgDialog_145523_Content_80 = {
    Text = "Lingkaran cahaya pertama naik dari atas altar. Lalu yang kedua, yang ketiga. Keinginan yang tertidur di dalam tujuh benda pusaka saling bersahutan, bagaikan tujuh sungai yang mengalir menuju lautan yang sama."
  },
  AvgDialog_145523_Content_81 = {
    Text = "Andai Gunung memiliki sepasang tangan, Ia pasti akan mengulurkan tangan penuh hasrat ke arah lingkaran yang melayang tinggi di udara."
  },
  AvgDialog_145523_Content_82 = {
    Text = "<Shake:Akhirnya hari ini tiba!>"
  },
  AvgDialog_145523_Content_83 = {
    Text = "Lalu, Ia akan meraih lingkaran yang tergantung di cakrawala itu, memeluknya erat, erat sekali, hingga terbenam ke dalam tubuh-Nya yang mengembung, hingga semua kekuatan habis dilahap-Nya."
  },
  AvgDialog_145523_Content_84 = {
    Text = "Kamu menatap langit tinggi dengan bingung. Ketika Gunung mengucapkan keinginan-Nya, bagaimana nasib kalian? Apakah perjalanan kalian akan berakhir di sini?"
  },
  AvgDialog_145523_Content_85 = {
    Text = "Pada saat itu, kamu melihat kacamata William berkilat."
  },
  AvgDialog_145523_Content_86 = {
    Text = "Seketika itu juga, lingkaran cahaya keempat menyala."
  },
  AvgDialog_145523_Content_87 = {
    Text = "Seluruh puncak gunung di bawah kaki mengeluarkan suara gemuruh. Itu adalah getaran seperti makhluk hidup, bukan milik bebatuan. Sinar-sinar redup merembes dari bawah lapisan batu yang retak."
  },
  AvgDialog_145523_Content_88 = {
    Text = "<Shake:……Apa?>"
  },
  AvgDialog_145523_Content_89 = {
    Text = "<Shake:Mengapa, kekuatanku… menghilang?>"
  },
  AvgDialog_145523_Content_9 = {
    Text = "Tunggu… ukiran-ukiran ini…"
  },
  AvgDialog_145523_Content_90 = {
    Text = "Itulah harga dari ritual yang kau inginkan."
  },
  AvgDialog_145523_Content_91 = {
    Text = "Setelah membayar harganya, apa yang akan terjadi padanya?"
  },
  AvgDialog_145523_Content_92 = {
    Text = "Ritual akan menyerap \"seluruh\" Strength korban, jadi kurasa, ia akan kembali seperti sebelum bertemu denganmu, bahkan lebih lemah."
  },
  AvgDialog_145523_Content_93 = {
    Text = "Lemah seperti cacing kecil yang menggeliat di dalam apel, yang akan hancur hanya dengan sedikit tekanan?"
  },
  AvgDialog_145523_Content_94 = {
    Text = "<BigShake:Kau menipuku! Penipu hina!>"
  },
  AvgDialog_145523_Content_95 = {
    Text = "Aku berjanji memulai ritual dengan standar tertinggi, dan kau pun menyetujui untuk mempersembahkan \"semua\" kurban."
  },
  AvgDialog_145523_Content_96 = {
    Text = "Semua yang telah kau telan ke dalam perutmu, kekuatan seluruh gunung ini, semuanya akan dipersembahkan ke altar, dipersembahkan kepada dewa yang mendirikan formasi ini."
  },
  AvgDialog_145523_Content_97 = {
    Text = "Lingkaran cahaya kelima bangkit."
  },
  AvgDialog_145523_Content_98 = {
    Text = "Bebatuan di bawah kaki mulai retak dan terkelupas, memperlihatkan lapisan di bawahnya yang lembap, pucat, dan sedang berkontraksi hebat."
  },
  AvgDialog_145523_Content_99 = {
    Text = "Hamparan salju yang luas runtuh bergemuruh, dan langit perlahan-lahan ditelan oleh bayangan raksasa yang besar."
  },
  AvgDialog_145524_Content_1 = {
    Text = "Kamu……jangan mendekat!"
  },
  AvgDialog_145524_Content_10 = {
    Text = "<Change>Masihkah kamu ingat misimu?"
  },
  AvgDialog_145524_Content_11 = {
    Text = "<Small:Habisi, pengkhianat……>"
  },
  AvgDialog_145524_Content_12 = {
    Text = "Chaos di mata Pollux perlahan menghilang, digantikan oleh kekosongan, kekosongan yang hanya bisa digerakkan oleh Suara Dalam Benak."
  },
  AvgDialog_145524_Content_13 = {
    Text = "Ya, benar, aku adalah pengkhianat. Aku adalah orang yang mengkhianatimu dan melarikan diri."
  },
  AvgDialog_145524_Content_14 = {
    Text = "Tapi sekarang, aku tidak akan pergi lagi."
  },
  AvgDialog_145524_Content_15 = {
    Text = "<Shake:Pengkhianat, Castor…>"
  },
  AvgDialog_145524_Content_16 = {
    Text = "Dia bingung, dia ingin melawan sesuatu, ingin menggenggam sesuatu, namun suara di dalam kepalanya terus berjuang."
  },
  AvgDialog_145524_Content_17 = {
    Text = "Pollux, kamu selalu mengikuti kami, pasti kamu juga sudah bertemu Wendigo."
  },
  AvgDialog_145524_Content_18 = {
    Text = "Di dalam Ilusi Wendigo, apa yang kamu dengar?"
  },
  AvgDialog_145524_Content_19 = {
    Text = "Pupil Pollux seketika membesar, lalu perlahan menjadi kosong. Dia tenggelam dalam perenungan seperti Igauan."
  },
  AvgDialog_145524_Content_2 = {
    Text = "Pollux membelalakkan Mata-nya. Dia tidak mengerti apa yang dipikirkan oleh orang gila di hadapannya ini."
  },
  AvgDialog_145524_Content_20 = {
    Text = "Aku mendengar… ada seseorang yang mempanggilku…"
  },
  AvgDialog_145524_Content_21 = {
    Text = "Dia berkata, kita bisa menjadi ksatria yang luar biasa."
  },
  AvgDialog_145524_Content_22 = {
    Text = "Kita menunggang kuda, melewati pegunungan, melewati sungai dan lautan, membunuh naga…"
  },
  AvgDialog_145524_Content_23 = {
    Text = "Lalu, lalu, di akhir Mimpi…"
  },
  AvgDialog_145524_Content_25 = {
    Text = "<BigShake:Tidak, tidak…!>"
  },
  AvgDialog_145524_Content_26 = {
    Text = "Sangat menyakitkan, Juliette, <Shake:Tolong Aku!, Tolong Aku!…>"
  },
  AvgDialog_145524_Content_27 = {
    Text = "<Shake:Aku adalah… yang mulia… satu-satunya… Anak Suci… Tolong Aku!… <Small:Aku tidak bisa…>>"
  },
  AvgDialog_145524_Content_28 = {
    Text = "Tidak apa-apa… kamu tidak perlu mengingatnya."
  },
  AvgDialog_145524_Content_29 = {
    Text = "Penderitaan yang tak tertahankan, biar aku yang menanggungnya. Seperti waktu kecil dulu."
  },
  AvgDialog_145524_Content_3 = {
    Text = "Di wajah Castor tidak ada rasa hormat terhadap ajaran, juga tidak ada ketakutan terhadap permusuhan."
  },
  AvgDialog_145524_Content_30 = {
    Text = "Bagaimanapun, akulah kakaknya."
  },
  AvgDialog_145524_Content_31 = {
    Text = "Castor memeluk Pollux, menenangkannya dengan suara lembut seperti menghibur seorang anak kecil."
  },
  AvgDialog_145524_Content_32 = {
    Text = "Napas Pollux melambat, Wajahnya bersandar di bahu Castor, kelopak Matanya perlahan-lahan turun."
  },
  AvgDialog_145524_Content_33 = {
    Text = "<Shake:Castor…>"
  },
  AvgDialog_145524_Content_34 = {
    Text = "Ini aku, aku ini, Castor…"
  },
  AvgDialog_145524_Content_35 = {
    Text = "<Shake:Castor, Castor…>"
  },
  AvgDialog_145524_Content_36 = {
    Text = "<Shake:<Small:……Kakak?>>"
  },
  AvgDialog_145524_Content_37 = {
    Text = "Pupil yang tadinya kosong seketika menjadi jernih, suara Pollux begitu pelan hingga Hampir tersapu Angin, namun tetap saja tepat masuk ke telinga Castor."
  },
  AvgDialog_145524_Content_38 = {
    Text = "Panggilan yang telah ia bayangkan dan rindukan berkali-kali, akhirnya kembali bergema di telinganya."
  },
  AvgDialog_145524_Content_39 = {Text = "Aah——"},
  AvgDialog_145524_Content_4 = {
    Text = "Dia hanya melangkah maju, melewati pisau itu, melewati semua rintangan yang seharusnya ada namun kini tiada."
  },
  AvgDialog_145524_Content_40 = {
    Text = "Ia ingin menangis, ingin berteriak, ingin meraung."
  },
  AvgDialog_145524_Content_41 = {
    Text = "Meskipun saat ini di sekelilingnya hanya ada Lapangan Salju yang luas tak bertepi, ia ingin mengumumkan kepada seluruh dunia tanpa alasan apa pun, bahwa adiknya telah kembali."
  },
  AvgDialog_145524_Content_42 = {
    Text = "Namun ia tidak mengucapkan apa pun, seperti biasanya, seperti saat Pollux mengejeknya sebagai kayu bisu dan Caraboo mengejeknya sebagai orang bodoh."
  },
  AvgDialog_145524_Content_43 = {
    Text = "<Shake:Pollux…>"
  },
  AvgDialog_145524_Content_44 = {
    Text = "— Tepat pada saat itu, di ketinggian gunung bersalju — di suatu tempat yang lebih tinggi, yang puncaknya tak terlihat —"
  },
  AvgDialog_145524_Content_45 = {
    Text = "Sebuah Tatapan Pengadilan, jatuh ke bawah."
  },
  AvgDialog_145524_Content_46 = {
    Text = "<Change>Produk cacat."
  },
  AvgDialog_145524_Content_47 = {
    Text = "Castor dengan cepat merangkul adiknya erat-erat—"
  },
  AvgDialog_145524_Content_48 = {
    Text = "Namun itu tidak berguna. Cahaya itu memancar dari dada Pollux."
  },
  AvgDialog_145524_Content_49 = {
    Text = "Cahaya itu menembus dada keduanya, merobek jubah usang Castor, menembus Sayap Castor yang memeluk mereka berdua—"
  },
  AvgDialog_145524_Content_5 = {
    Text = "Dia memeluk Pollux erat-erat dalam pelukannya."
  },
  AvgDialog_145524_Content_50 = {
    Text = "Bagaikan rantai putih bersih, mengikat keduanya erat-erat, berjanji mulai saat ini, tidak akan pernah Pemisahan."
  },
  AvgDialog_145524_Content_51 = {
    Text = "Kakak… maafkan aku…"
  },
  AvgDialog_145524_Content_52 = {
    Text = "Meninggalkan kata-kata terakhirnya, Pollux bersandar di bahu Castor, terlelap dalam tidur yang panjang."
  },
  AvgDialog_145524_Content_53 = {
    Text = "Begini… juga baik… kita tidak akan pernah terpisah lagi…"
  },
  AvgDialog_145524_Content_54 = {
    Text = "Ini juga… sedikit keegoisan dariku…"
  },
  AvgDialog_145524_Content_55 = {
    Text = "Ia menoleh sekali ke arah yang lebih tinggi di gunung itu, membayangkan bagaimana rekan-rekan tim pendakian dulu saling membantu mendaki."
  },
  AvgDialog_145524_Content_56 = {
    Text = "Kebohongan telah berakhir, perjalanan ini tidak lagi miliknya."
  },
  AvgDialog_145524_Content_57 = {
    Text = "Menukar satu Kebohongan dengan Kebohongan lainnya…"
  },
  AvgDialog_145524_Content_58 = {
    Text = "Selamat tinggal… semua orang… semoga perjalanan kalian… akhirnya tiba di tanah yang dijanjikan…"
  },
  AvgDialog_145524_Content_59 = {
    Text = "Sehelai Bulu hitam terlepas dari Sayap Castor, tersapu Angin Salju ke angkasa tinggi."
  },
  AvgDialog_145524_Content_6 = {
    Text = "Seperti dulu ketika berada di dalam cairan ketuban."
  },
  AvgDialog_145524_Content_60 = {
    Text = "Biarkan ia mewakili kita, menuju tempat yang kamu impikan itu, tanah suci yang bebas dari dosa…"
  },
  AvgDialog_145524_Content_61 = {
    Text = "Sebuah celah sempit terbuka di bawah kaki keduanya, perlahan menelan semua beban ke dalam salju dan es di perut gunung."
  },
  AvgDialog_145524_Content_62 = {
    Text = "Selamat malam, Pollux."
  },
  AvgDialog_145524_Content_63 = {
    Text = "Kalian mendaki jalur gunung yang baru, merapikan perlengkapan yang berat."
  },
  AvgDialog_145524_Content_64 = {
    Text = "Angin Salju Seolah-olah memiliki kesadaran sendiri, berputar-putar di atas."
  },
  AvgDialog_145524_Content_65 = {
    Text = "Itu adalah..."
  },
  AvgDialog_145524_Content_66 = {
    Text = "Di tengah Angin Salju, sehelai Bulu hitam pekat perlahan melayang jatuh."
  },
  AvgDialog_145524_Content_67 = {
    Text = "Kamu mengangkat tanganmu, dan ia tepat jatuh ke telapak tanganmu."
  },
  AvgDialog_145524_Content_68 = {
    Text = "Bagaikan Blessing datang dari jauh."
  },
  AvgDialog_145524_Content_69 = {
    Text = "Ketinggian -7000 meter-"
  },
  AvgDialog_145524_Content_7 = {
    Text = "Kembalilah, Pollux. Seperti ketika kita masih kecil dulu."
  },
  AvgDialog_145524_Content_8 = {
    Text = "Benak Pollux dipenuhi kebingungan, dipenuhi ketidakmengertian. Namun entah mengapa, dia tidak mampu mendorong pelukan hangat itu."
  },
  AvgDialog_145524_Content_9 = {
    Text = "Suara teguran keras tiba-tiba bergema di telinganya."
  },
  AvgDialog_145525_Content_1 = {
    Text = "Gua kembali sunyi dengan cara yang aneh, semua orang yang masih ketakutan saling berpandangan."
  },
  AvgDialog_145525_Content_10 = {
    Text = "Hanya Saja di gunung ini ada keberadaan tertentu selain Dewi, yang sedang berusaha merampas keinginan kalian."
  },
  AvgDialog_145525_Content_11 = {
    Text = "Berhenti menakut-nakuti semua orang, Caraboo."
  },
  AvgDialog_145525_Content_12 = {
    Text = "Terserah kalian mau percaya atau tidak. Dewi gunung Salju bisa merasakannya, tepat di dekat rombongan kita, mengikuti dengan erat…"
  },
  AvgDialog_145525_Content_13 = {
    Text = "Kalian tidak bisa membedakan dari nada bicaranya apakah dia sedang berpura-pura, atau memang benar-benar merasakan sesuatu."
  },
  AvgDialog_145525_Content_14 = {
    Text = "Angin dan salju perlahan mereda."
  },
  AvgDialog_145525_Content_15 = {
    Text = "Di tengah keheningan yang berat itu, kalian pun kembali berangkat."
  },
  AvgDialog_145525_Content_2 = {
    Text = "Aneh, aku sudah berkali-kali menemani tim pendaki mencapai ketinggian ini, tapi baru pertama kali mengalami hal seperti ini…"
  },
  AvgDialog_145525_Content_3 = {
    Text = "Ini membuktikan bahwa bahaya di gunung Salju ini bukan hanya suhu minus tiga puluh derajat dan kekurangan oksigen di ketinggian."
  },
  AvgDialog_145525_Content_4 = {
    Text = "Caraboo merendahkan suaranya, perlahan menguraikan dengan nada yang membuat bulu kuduk merinding."
  },
  AvgDialog_145525_Content_5 = {
    Text = "Dewi gunung Salju benar-benar ada."
  },
  AvgDialog_145525_Content_6 = {
    Text = "<Red:Dewi gunung salju tidak menyambut kalian, tidak menyambut mereka yang tidak memiliki ketulusan hati.>"
  },
  AvgDialog_145525_Content_7 = {
    Text = "Suasana menjadi kaku."
  },
  AvgDialog_145525_Content_8 = {
    Text = "Hanya bercanda! Masa kalian benar-benar percaya!"
  },
  AvgDialog_145525_Content_9 = {
    Text = "Aku adalah Dewi gunung Salju yang paling baik hati, dengan doaku, gunung akan menyambut kalian, langsung menuju puncak."
  },
  AvgDialog_145526_Content_1 = {
    Text = "Hari Meninggalkan Sarang"
  },
  AvgDialog_145526_Content_10 = {
    Text = "Kita tadi Hanya Saja berhasil menangkis satu serangan, tapi serangannya tidak akan berhenti."
  },
  AvgDialog_145526_Content_11 = {
    Text = "Di tempat berbahaya seperti pegunungan ini, manusia pasti sesekali menunjukkan sisi Fragile dan lemahnya…"
  },
  AvgDialog_145526_Content_12 = {
    Text = "Saat seperti itu, lebih baik berpura-pura."
  },
  AvgDialog_145526_Content_13 = {
    Text = "Caraboo entah dari mana mengeluarkan sebuah Apel, menggigitnya dengan bunyi krak, dengan ekspresi santai \"kalimat tadi bukan aku yang bilang\"."
  },
  AvgDialog_145526_Content_14 = {
    Text = "…Kamu juga tidak salah dengan mengatakan itu."
  },
  AvgDialog_145526_Content_15 = {
    Text = "Bagaimanapun, kita harus menemukannya, lalu menangkapnya."
  },
  AvgDialog_145526_Content_16 = {
    Text = "Tapi mereka tidak meninggalkan jejak saat berjalan di atas Salju, bagaimana kita bisa…"
  },
  AvgDialog_145526_Content_17 = {
    Text = "Serahkan padaku. Aku paling ahli menghadapi penipu, bukan?"
  },
  AvgDialog_145526_Content_18 = {
    Text = "Lihat, mereka hampir datang."
  },
  AvgDialog_145526_Content_19 = {
    Text = "Caraboo menunjuk ke sisi rombongan, satu-satunya anjing pemandu yang masih hidup merendahkan tubuhnya, mengerang pelan."
  },
  AvgDialog_145526_Content_2 = {Text = "Wendigo."},
  AvgDialog_145526_Content_20 = {
    Text = "Kalian jangan bergerak, jangan bicara juga."
  },
  AvgDialog_145526_Content_21 = {
    Text = "Dia melemparkan Apel yang sudah digigitnya kepadamu."
  },
  AvgDialog_145526_Content_22 = {
    Text = "Di dalam bekas gigitan tersembunyi selembar kertas kecil: Apapun yang aku katakan selanjutnya, jangan dipercaya."
  },
  AvgDialog_145526_Content_23 = {
    Text = "Caraboo terdiam, dia memejamkan mata, lalu membukanya kembali."
  },
  AvgDialog_145526_Content_24 = {
    Text = "Pada saat itu, tatapan matanya berubah. Bingung, cemas, sayu, perasaan yang rumit tertampung di dalam bola matanya yang kecil."
  },
  AvgDialog_145526_Content_25 = {
    Text = "<Shake:Bibi Rosa, apakah itu kamu?>"
  },
  AvgDialog_145526_Content_26 = {
    Text = "<Shake:Apakah Bibi sedang membuat pai Apel lagi? Aku mencium aromanya.>"
  },
  AvgDialog_145526_Content_27 = {
    Text = "<Shake:Bibi Rosa, aku tidak akan mengeluh lagi soal kulit pai Apelnya yang terlalu tebal. Sejak saat itu, aku tidak pernah lagi makan pai Apel yang seenak itu. Aku merindukan aroma harum panggangnya.>"
  },
  AvgDialog_145526_Content_28 = {
    Text = "<Shake:Bibi Rosa. Aku akan pergi menemuimu sekarang, tunggulah aku.>"
  },
  AvgDialog_145526_Content_29 = {
    Text = "Caraboo melangkah maju dengan sempoyongan."
  },
  AvgDialog_145526_Content_3 = {
    Text = "William mengucapkannya kata demi kata."
  },
  AvgDialog_145526_Content_30 = {
    Text = "Di atas salju, di belakang Caraboo, tiba-tiba muncul dua gundukan salju setinggi satu setengah orang."
  },
  AvgDialog_145526_Content_31 = {
    Text = "Ia menerjang Caraboo dengan cepat. Caraboo merunduk tepat saat ia menerjang."
  },
  AvgDialog_145526_Content_32 = {
    Text = "<Big:William, bersiap!!>"
  },
  AvgDialog_145526_Content_4 = {
    Text = "<Italic:\"Kakinya ditempa dari api — saat ia berlari, Salju Membakar di bawah kakinya.\">"
  },
  AvgDialog_145526_Content_5 = {
    Text = "\"Kisah Aneh dari Utara\" jilid ketujuh mencatat: <Italic:Siapa pun yang mendengar Bisikan di malam musim dingin, jangan pernah menyahut.>"
  },
  AvgDialog_145526_Content_6 = {
    Text = "<Italic:Sahut sekali, ia akan Catat namamu; sahut dua kali, ia akan mengenali bayanganmu; sahut sampai ketiga kalinya — kamu pun menjadi dirinya.>"
  },
  AvgDialog_145526_Content_7 = {
    Text = "Kita tidak bisa menghindarinya?"
  },
  AvgDialog_145526_Content_8 = {
    Text = "Tidak ada gunanya, Asalkan Angin dan Salju melanda suatu wilayah, di sanalah Wendigo berkeliaran."
  },
  AvgDialog_145526_Content_9 = {
    Text = "Mereka dulunya adalah manusia. Berubah wujud karena memakan sesamanya, sejak saat itu bibir dan gigi mereka membusuk, Kelaparan selamanya — memakan seluruh Hutan pun tidak akan kenyang."
  },
  AvgDialog_145527_Content_1 = {
    Text = "Ransel Perjalanan"
  },
  AvgDialog_145527_Content_10 = {
    Text = "Tidak bisa."
  },
  AvgDialog_145527_Content_100 = {
    Text = "Ia mendekatkan rantingnya ke tungku api untuk menyalakannya, lalu Gabung ke tengah-tengah kalian."
  },
  AvgDialog_145527_Content_101 = {
    Text = "Api menjalar dari satu ranting ke ranting lain, cahaya yang Berkedip menerangi satu per satu Wajah yang mendongak."
  },
  AvgDialog_145527_Content_102 = {
    Text = "Saat segalanya sunyi senyap, Seolah-olah terdengar suara lantunan doa yang dalam, suara lonceng, dan suara gendang yang datang dari tidak jauh."
  },
  AvgDialog_145527_Content_103 = {
    Text = "Serukan Lha Gyalo dengan lantang, lalu lemparkan semuanya ke dalam api."
  },
  AvgDialog_145527_Content_104 = {
    Text = "Suara serak namun penuh tenaga itu Gaung di udara yang tipis, ranting-ranting di tangan satu per satu jatuh ke dalam api seiring seruan lantang itu."
  },
  AvgDialog_145527_Content_105 = {
    Text = "Terima kasih kepada Dewa Gunung, yang telah memaafkan ketidakhormatan kami saat memasuki wilayah suci-Nya."
  },
  AvgDialog_145527_Content_106 = {
    Text = "Ranting pinus dan cemara berderak di dalam tumpukan api, asap biru-hijau mengepul lurus ke atas, lalu dirobek oleh angin di ketinggian."
  },
  AvgDialog_145527_Content_107 = {
    Text = "Dan kamu mencium sedikit aroma pertanda buruk dari sana."
  },
  AvgDialog_145527_Content_109 = {
    Text = "Baik, penjelasan mengenai bahaya pendakian kali ini dan rencana darurat telah selesai disampaikan kepada semua orang."
  },
  AvgDialog_145527_Content_11 = {
    Text = "Eh!!! Kenapa!!!"
  },
  AvgDialog_145527_Content_110 = {
    Text = "Selama Satu Minggu terakhir, kalian semua juga sudah beradaptasi bergerak dengan mengenakan sarung tangan, sepatu pendakian, dan kacamata salju, serta telah berlatih dan menguasai cara penggunaan tali dan paku es."
  },
  AvgDialog_145527_Content_111 = {
    Text = "Berdasarkan pemantauan ketat selama beberapa hari terakhir, 5-7 hari ke depan adalah jendela cuaca paling ideal untuk pendakian, ini adalah waktu yang tepat untuk berangkat."
  },
  AvgDialog_145527_Content_112 = {
    Text = "Harap periksa peta rute, makanan, bahan bakar, tabung oksigen, kotak medis, dan perlengkapan lainnya yang masing-masing kalian bawa."
  },
  AvgDialog_145527_Content_113 = {
    Text = "Sekali lagi ditekankan, selama proses pendakian wajib <Yellow:sepenuhnya mematuhi instruksi pemandu>, selain anggota yang mundur lebih awal, yang lainnya <Yellow:dilarang keras meninggalkan rombongan>."
  },
  AvgDialog_145527_Content_114 = {
    Text = "Kalau sudah siap, mari kita berangkat!"
  },
  AvgDialog_145527_Content_116 = {
    Text = "……………"
  },
  AvgDialog_145527_Content_117 = {
    Text = "Kalian baru berjalan di gunung selama setengah hari, cuaca yang tadinya cerah tiba-tiba berubah mendung."
  },
  AvgDialog_145527_Content_118 = {
    Text = "Badai salju tiba-tiba menguat, memandang ke mana pun bahkan sudut-sudut gunung sulit dibedakan, dan anjing pemandu yang menemani pun merengek enggan melanjutkan perjalanan."
  },
  AvgDialog_145527_Content_119 = {
    Text = "Aneh, berdasarkan hasil pemantauan kami, cuaca ekstrem seharusnya tidak muncul secepat ini."
  },
  AvgDialog_145527_Content_12 = {
    Text = "Bukankah mereka berdua juga baru bergabung?"
  },
  AvgDialog_145527_Content_120 = {
    Text = "Pernahkah menghadapi situasi serupa sebelumnya?"
  },
  AvgDialog_145527_Content_121 = {
    Text = "Tidak pernah. Bahkan jika pemantauan meleset, biasanya baru terjadi tiga hari setelah hasil prediksi."
  },
  AvgDialog_145527_Content_122 = {
    Text = "<Shake:Badai salju yang tidak wajar… sepertinya… <Yellow:gunung sedang menolak kita>.>"
  },
  AvgDialog_145527_Content_123 = {
    Text = "Tidak mungkin, dengan adanya Dewi Gunung Salju seperti aku di regu ini, bagaimana bisa hal seperti ini terjadi?"
  },
  AvgDialog_145527_Content_124 = {
    Text = "Tidak perlu terlalu khawatir, saat turun gunung pun kadang kita bisa bertemu badai salju yang tak terduga."
  },
  AvgDialog_145527_Content_125 = {
    Text = "Di dekat sini ada titik perlindungan, di sana bahkan ada sedikit perbekalan tambahan, kita pergi istirahat sebentar, tunggu badai salju reda, lalu bersiap-siap dan berangkat kembali."
  },
  AvgDialog_145527_Content_126 = {
    Text = "Kalau begitu apa lagi yang perlu dikatakan, ayo cepat jalan!"
  },
  AvgDialog_145527_Content_13 = {
    Text = "Caraboo dengan wajah penuh protes mengulurkan tangan dan menunjuk kamu dan William."
  },
  AvgDialog_145527_Content_14 = {
    Text = "Sederhana saja. Mereka berdua sudah dewasa, mampu menjaga diri sendiri."
  },
  AvgDialog_145527_Content_15 = {
    Text = "Mendaki gunung bukan bermain-main, nak."
  },
  AvgDialog_145527_Content_16 = {
    Text = "Di sini, kamu boleh mengaku sebagai ayah, ibu, Dewi Salju, atau bahkan Kehendak Tertinggi sekalipun."
  },
  AvgDialog_145527_Content_17 = {
    Text = "Tapi begitu mencapai puncak di atas ketinggian lima ribu meter, semua kebohongan akan terbongkar di tengah badai salju dan mabuk ketinggian."
  },
  AvgDialog_145527_Content_18 = {
    Text = "Tapi aku punya uang, aku punya <Big:banyak——sekali——uang——>!"
  },
  AvgDialog_145527_Content_19 = {
    Text = "Kamu masih anak kecil, memangnya kamu punya berapa banyak——"
  },
  AvgDialog_145527_Content_2 = {
    Text = "Di bawah panduan pemandu Naraka, kalian dan para anggota tim pendakian saling memperkenalkan diri."
  },
  AvgDialog_145527_Content_20 = {Text = "<Big:!>"},
  AvgDialog_145527_Content_21 = {
    Text = "Kata-kata Naraka terhenti tiba-tiba."
  },
  AvgDialog_145527_Content_22 = {
    Text = "Gadis itu mengeluarkan sebuah kantong kain yang berat, mengambil segenggam koin emas, membiarkan hujan koin emas mengalir deras kembali ke dalam kantong dengan suara gemerincing, hanya menyisakan satu keping, yang ia mainkan dengan jari-jarinya."
  },
  AvgDialog_145527_Content_23 = {
    Text = "Sudah kubilang aku ini peri, mana mungkin kekurangan Benda di luar tubuh seperti uang!"
  },
  AvgDialog_145527_Content_24 = {
    Text = "<Small:Sebenarnya peri atau dewi……>"
  },
  AvgDialog_145527_Content_25 = {
    Text = "Tidak peduli, siapa yang mau tahu!"
  },
  AvgDialog_145527_Content_26 = {
    Text = "Caraboo melempar koin emas begitu saja, Naraka buru-buru menjulurkan badan untuk menangkapnya, sempoyongan, hampir terjatuh ke dalam Salju."
  },
  AvgDialog_145527_Content_27 = {
    Text = "Dia menggenggam koin emas itu, menggigitnya dengan gigi, sangat gembira."
  },
  AvgDialog_145527_Content_28 = {
    Text = "<Shake:Ini asli……!>"
  },
  AvgDialog_145527_Content_29 = {
    Text = "Hmph, koin emas dari tangan peri, mana mungkin palsu?"
  },
  AvgDialog_145527_Content_3 = {
    Text = "Tinct, penyanyi yang misterius dan pendiam, mengaku ingin mencari kakak perempuannya."
  },
  AvgDialog_145527_Content_30 = {
    Text = "Pokoknya, aku bisa ikut regu pendaki sekarang kan?"
  },
  AvgDialog_145527_Content_31 = {
    Text = "<Shake:<Small:Memang, mengajak anak kecil bergabung dengan regu pendaki agak tidak bertanggung jawab terhadap keselamatanmu……>>"
  },
  AvgDialog_145527_Content_32 = {
    Text = "<BigShake:Hm?>"
  },
  AvgDialog_145527_Content_33 = {
    Text = "Tapi kalau dipikir lagi, regu pendaki kami memiliki Pengalaman mendaki yang kaya dan perbekalan yang cukup, melindungi seorang kamu masih <Big:lebih dari cukup>!"
  },
  AvgDialog_145527_Content_34 = {
    Text = "Tapi sudah kubilang ya, begitu kamu memutuskan untuk kembali di tengah jalan, kami akan meninggalkan cukup bekal untuk turun gunung, tapi biaya pemandu <Big:tidak ada yang dikembalikan> lho."
  },
  AvgDialog_145527_Content_35 = {
    Text = "Tahu tahu, masa peri mau ribut soal uang receh seperti itu?"
  },
  AvgDialog_145527_Content_36 = {
    Text = "<Shake:<Small:Aneh sekali, bukankah tadi Dia masih mengamen dan mengemis?>>"
  },
  AvgDialog_145527_Content_37 = {
    Text = "Jangan kira aku tidak bisa dengar!"
  },
  AvgDialog_145527_Content_38 = {
    Text = "Sudah kubilang, itu adalah Memberi Nafkah! Yang dewi inginkan adalah ketulusan semua orang, mengerti tidak?"
  },
  AvgDialog_145527_Content_39 = {
    Text = "<Shake:<Small:Saat tidak diperlukan, pendengarannya juga sangat bagus...>>"
  },
  AvgDialog_145527_Content_4 = {
    Text = "Evelyn, seorang arkeolog, yang datang untuk penelitian ilmiah bahkan di dunia pasca-kiamat ini."
  },
  AvgDialog_145527_Content_40 = {
    Text = "<BigShake:Kalimat itu juga bisa kudengar!>"
  },
  AvgDialog_145527_Content_41 = {
    Text = "Rombonganmu memeriksa perbekalan, dan topik pembicaraan pun segera beralih ke ritual permohonan kepada dewi gunung salju."
  },
  AvgDialog_145527_Content_42 = {
    Text = "Apakah kalian benar-benar percaya bahwa ada dewi di puncak gunung bersalju yang bisa mewujudkan segala keinginan?"
  },
  AvgDialog_145527_Content_43 = {
    Text = "William bertanya dengan pura-pura tidak sengaja."
  },
  AvgDialog_145527_Content_44 = {
    Text = "Setidaknya para penduduk setempat semua mempercayainya. Karena regu pendaki sebelumnya."
  },
  AvgDialog_145527_Content_45 = {
    Text = "Regu pendaki sebelumnya?"
  },
  AvgDialog_145527_Content_46 = {
    Text = "Ya. Sejak kabar tentang Dewi Gunung Salju tersebar, Benua Utara pun membentuk tatanan tersendiri. Regu pendaki itu adalah yang paling terlatih dan paling berpeluang mencapai puncak di antara semua regu pendaki."
  },
  AvgDialog_145527_Content_47 = {
    Text = "Mereka berangkat dengan tujuh orang. Namun dalam proses pendakian, para anggota regu satu per satu meninggal dunia."
  },
  AvgDialog_145527_Content_48 = {
    Text = "Ada yang meninggalkan tenda di tengah malam, berjalan telanjang kaki ke dalam badai salju; ada yang memotong tali pengamannya sendiri dan melompat dari tebing es;"
  },
  AvgDialog_145527_Content_49 = {
    Text = "Ada pula yang menghilang selama beberapa hari, namun akhirnya ditemukan membeku di depan rombongan—"
  },
  AvgDialog_145527_Content_5 = {
    Text = "Ketika kalian sedang membahas rencana keberangkatan keesokan harinya, tiba-tiba sebuah kepala putih muncul di pintu masuk kemah."
  },
  AvgDialog_145527_Content_50 = {
    Text = "Seolah-olah setelah meninggal, ia masih terus mendaki."
  },
  AvgDialog_145527_Content_51 = {
    Text = "Gerakan semua orang menghitung persediaan tanpa disadari melambat."
  },
  AvgDialog_145527_Content_52 = {
    Text = "Pada akhirnya, hanya satu orang yang kembali hidup ke kaki gunung."
  },
  AvgDialog_145527_Content_53 = {
    Text = "Namun, tidak bisa dikatakan bahwa ia benar-benar \"kembali hidup\"."
  },
  AvgDialog_145527_Content_54 = {
    Text = "Apa maksudmu?"
  },
  AvgDialog_145527_Content_55 = {
    Text = "Kesepuluh jarinya membusuk karena kedinginan, telinganya tersumbat salju bercampur Darah. Apapun yang ditanyakan orang lain, ia hanya akan terus mengulang beberapa kalimat yang sama."
  },
  AvgDialog_145527_Content_56 = {
    Text = "Naraka merendahkan suaranya, menirukan nada bicara sang penyintas yang seperti Igauan."
  },
  AvgDialog_145527_Content_57 = {
    Text = "<Shake:\"Legenda itu nyata. Keinginan di puncak gunung itu nyata.\">"
  },
  AvgDialog_145527_Content_58 = {
    Text = "<Shake:<Red:\"Tutup telingamu, jangan dengarkan.\">>"
  },
  AvgDialog_145527_Content_59 = {
    Text = "<Shake:\"Orang yang mendengar nyanyian itu akan tergoda, di-Devour... lalu naik ke langit, berubah menjadi <Red:Bulan>.\">"
  },
  AvgDialog_145527_Content_6 = {
    Text = "Hei~ Apakah ini tim pendakian Naraka?"
  },
  AvgDialog_145527_Content_60 = {
    Text = "Kemudian apa?"
  },
  AvgDialog_145527_Content_61 = {
    Text = "Kemudian ah……"
  },
  AvgDialog_145527_Content_62 = {
    Text = "Naraka menampilkan senyuman aneh yang terlihat seperti senyum namun bukan senyum."
  },
  AvgDialog_145527_Content_63 = {
    Text = "Penduduk asli percaya bahwa mereka telah menghina Dewi Gunung Salju dalam perjalanan mendaki, dan khawatir amarah sang dewi akan menimpa warga desa."
  },
  AvgDialog_145527_Content_64 = {
    Text = "Maka mereka memilih suatu malam yang gelap gulita tanpa angin, lalu melemparnya ke dalam celah es yang tak terukur dalamnya."
  },
  AvgDialog_145527_Content_65 = {
    Text = "Itukah akhir dari ceritanya?"
  },
  AvgDialog_145527_Content_66 = {Text = "Tidak."},
  AvgDialog_145527_Content_67 = {
    Text = "Sejak saat itu, setiap kali bulan purnama, orang-orang yang melewati celah es itu masih bisa mendengar suara seseorang bernyanyi dari bawah."
  },
  AvgDialog_145527_Content_68 = {
    Text = "Maka semua orang pun tahu, bahwa yang ia katakan adalah benar. Pasti ada sesuatu di atas gunung itu."
  },
  AvgDialog_145527_Content_69 = {
    Text = "Naraka kembali menundukkan kepala, menggulung tali satu per satu ke dalam Ransel Perjalanan, seolah-olah apa yang baru saja dikatakannya hanyalah urusan lama yang tidak penting."
  },
  AvgDialog_145527_Content_7 = {
    Text = "Mencari saya?"
  },
  AvgDialog_145527_Content_70 = {
    Text = "Di tengah keheningan yang singkat, hanya ada Angin yang menyapu tenda, mengeluarkan erangan panjang dan samar."
  },
  AvgDialog_145527_Content_71 = {
    Text = "Aku juga pernah mendengar, bahwa dalam perjalanan mendaki, mereka mendengar nyanyian Sirene."
  },
  AvgDialog_145527_Content_72 = {
    Text = "Kamu lagi-lagi bicara sembarangan, Sirene adalah makhluk laut, bagaimana mungkin muncul di gunung?"
  },
  AvgDialog_145527_Content_73 = {
    Text = "Caraboo cemberut tidak puas, lalu mendengus pelan."
  },
  AvgDialog_145527_Content_74 = {
    Text = "Di laut ada monster yang bisa bernyanyi, mengapa di gunung tidak boleh ada?"
  },
  AvgDialog_145527_Content_75 = {
    Text = "Terserah kamu percaya atau tidak. Saat mendengar nyanyian itu, ingat untuk menutup telingamu."
  },
  AvgDialog_145527_Content_76 = {
    Text = "Saat kamu hendak bertanya lebih lanjut, kamu menemukan Caraboo sudah berbalik dan masuk ke dalam pondok, tidak berniat melanjutkan diskusi."
  },
  AvgDialog_145527_Content_77 = {
    Text = "……………"
  },
  AvgDialog_145527_Content_78 = {
    Text = "Tujuh hari kemudian"
  },
  AvgDialog_145527_Content_79 = {
    Text = "Latihan hari ini sampai di sini, besok adalah hari pendakian resmi."
  },
  AvgDialog_145527_Content_8 = {
    Text = "Hehe, aku dengar kamu adalah pemandu pendakian terbaik di seluruh suku Sherpa!"
  },
  AvgDialog_145527_Content_80 = {
    Text = "Caraboo tiba-tiba melangkah maju, menghalangi Naraka yang hendak pergi."
  },
  AvgDialog_145527_Content_81 = {
    Text = "Tidak mengadakan <Yellow:Ritual Weisang>?"
  },
  AvgDialog_145527_Content_82 = {
    Text = "Ritual Weisang, itu apa?"
  },
  AvgDialog_145527_Content_83 = {
    Text = "Sebelum setiap pendakian, sepuluh dari sepuluh orang Sherpa melakukan ritual doa seperti ini. Apakah kamu sama sekali tidak memiliki rasa hormat kepada Dewa?"
  },
  AvgDialog_145527_Content_84 = {
    Text = "Naraka menepuk dahinya."
  },
  AvgDialog_145527_Content_85 = {
    Text = "<Yellow:Aduh, terlalu banyak urusan, sampai tidak sengaja terlupa.>"
  },
  AvgDialog_145527_Content_86 = {
    Text = "Ini pun bisa terlupakan?"
  },
  AvgDialog_145527_Content_87 = {
    Text = "Tidak apa-apa, besok pagi aku akan cepat-cepat melakukan versi sederhananya."
  },
  AvgDialog_145527_Content_89 = {
    Text = "Kamu menggerakkan bahu yang pegal lalu mendorong pintu kamar, di koridor sudah mengapung selapis asap tipis yang samar."
  },
  AvgDialog_145527_Content_9 = {
    Text = "Demi Blessing Dewi Salju, bisakah kamu membawaku mendaki bersama?"
  },
  AvgDialog_145527_Content_90 = {
    Text = "William berdiri beberapa langkah di depan cermin tembaga, sedang meratakan kerutan demi kerutan pada kerah bajunya."
  },
  AvgDialog_145527_Content_91 = {
    Text = "Selamat pagi, Penjaga Rahasia."
  },
  AvgDialog_145527_Content_92 = {
    Text = "Kamu mengendus. Di udara tercium aroma tumbuhan yang terbakar, dengan lapisan wangi yang segar dan dingin di bawahnya."
  },
  AvgDialog_145527_Content_93 = {
    Text = "Mendorong pintu besar, udara dingin dan asap wangi yang pekat datang bersamaan."
  },
  AvgDialog_145527_Content_94 = {
    Text = "Di halaman terbuka, sebuah tungku sang kecil sedang menyala. Asap berwarna putih kebiruan mengepul dari antara ranting cemara dan rerumputan wangi, naik lurus menuju langit abu-abu kebiruan."
  },
  AvgDialog_145527_Content_95 = {
    Text = "Orang Sherpa memandang puncak gunung sebagai roh ilahi, dan di Gunung Everest bahkan bersemayam Dewi Ibu Dunia."
  },
  AvgDialog_145527_Content_96 = {
    Text = "Sebelum pendakian resmi pertama, para Sherpa akan membangun altar, mengibarkan bendera doa, membacakan sutra, melakukan ritual \"Sang\" di samping altar, membiarkan asap menyampaikan persembahan dan doa kepada para dewa."
  },
  AvgDialog_145527_Content_97 = {
    Text = "Ritual doa ini cukup rumit, bahkan upacara resminya bisa Berkelanjutan selama tiga hingga empat jam."
  },
  AvgDialog_145527_Content_98 = {
    Text = "Naraka mengambil seikat ranting cemara dari kantong kain, lalu membagikannya ke setiap orang."
  },
  AvgDialog_145527_Content_99 = {
    Text = "Angkat tinggi, rapatkan."
  },
  AvgDialog_145528_Content_1 = {
    Text = "Kamu menerjang maju, memeluk pinggang Castor erat-erat dari belakang. Castor masih meronta, pita suaranya Hampir Mencabik-cabik karena meraung dalam Angin Salju."
  },
  AvgDialog_145528_Content_10 = {
    Text = "Evelyn melangkah maju selangkah demi selangkah. Dia berjongkok, menatap sejajar dengan pemuda yang kamu dan William tahan bersama di atas salju."
  },
  AvgDialog_145528_Content_11 = {
    Text = "Castor, dengarkan aku. Aku pun pernah mengira, Wendigo hanyalah makhluk yang ada dalam legenda."
  },
  AvgDialog_145528_Content_12 = {
    Text = "Tapi tadi aku… mendengarnya."
  },
  AvgDialog_145528_Content_13 = {
    Text = "Aku mendengar… suami ku memanggilku."
  },
  AvgDialog_145528_Content_14 = {
    Text = "Sejak hari dia menghilang, setiap hari aku mendengar Panggilan seperti itu, tapi tidak pernah sejelas ini, senyata ini…"
  },
  AvgDialog_145528_Content_15 = {
    Text = "Suara Evelyn sedikit serak."
  },
  AvgDialog_145528_Content_16 = {
    Text = "<Shake:Tapi Castor… tahukah kamu…>"
  },
  AvgDialog_145528_Content_17 = {
    Text = "Sudah lebih dari sembilan puluh hari sejak suamiku menghilang di gunung bersalju, waktu penyelamatan terbaik sudah lama terlewat."
  },
  AvgDialog_145528_Content_18 = {
    Text = "Dalam keadaan paling beruntung sekalipun, aku hanya bisa menemukan tulang belulangnya di suatu jalur pegunungan."
  },
  AvgDialog_145528_Content_19 = {
    Text = "Dia tidak akan hidup… di sini. Adikmu, apalagi."
  },
  AvgDialog_145528_Content_2 = {
    Text = "Castor, itu bukan dia."
  },
  AvgDialog_145528_Content_20 = {
    Text = "Kita harus terus mendaki, terus berjalan hingga ke ujung gunung."
  },
  AvgDialog_145528_Content_21 = {
    Text = "Itulah satu-satunya kesempatan kita untuk Reuni dengan mereka."
  },
  AvgDialog_145528_Content_22 = {
    Text = "Di bawah ketenangan Evelyn, Castor perlahan menjadi tenang."
  },
  AvgDialog_145528_Content_23 = {
    Text = "Kamu benar… di gunung bersalju tidak akan ada sel isolasi… dia tidak berada di tempat seperti ini."
  },
  AvgDialog_145528_Content_24 = {
    Text = "Aku akan terus bertahan… hingga Reuni dengannya."
  },
  AvgDialog_145528_Content_25 = {
    Text = "Di belakangmu, seseorang mengangkat kapak es, mengetukkannya dua kali dengan bunyi tok tok di atas bebatuan."
  },
  AvgDialog_145528_Content_26 = {
    Text = "Jika emosi kalian semua sudah stabil, kita perlu bersiap menghadapi ancaman yang sesungguhnya."
  },
  AvgDialog_145528_Content_27 = {
    Text = "<Yellow:Wendigo>."
  },
  AvgDialog_145528_Content_3 = {
    Text = "<Shake:Bagaimana kamu tahu itu bukan dia?! Kamu bahkan tidak mengenalnya!>"
  },
  AvgDialog_145528_Content_4 = {
    Text = "Kalian semua tidak mengenalnya! Hanya aku yang mengenalnya, aku mengenal suaranya!! Akulah yang meninggalkannya di sana!"
  },
  AvgDialog_145528_Content_5 = {
    Text = "Untuk pertama kalinya ia meninggikan suaranya kepada William. Lalu ia pun terkejut dengan suaranya sendiri."
  },
  AvgDialog_145528_Content_6 = {
    Text = "Castor, tenang, itu adalah <Yellow:Wendigo>."
  },
  AvgDialog_145528_Content_7 = {
    Text = "Monster gunung Wendigo… akan menggali bayangan terdalam di hatimu…"
  },
  AvgDialog_145528_Content_8 = {
    Text = "Kemudian, ia akan meminjam suara orang yang kamu rindukan, menggoda Yang Tersesat untuk melangkah masuk ke dalam jebakannya."
  },
  AvgDialog_145528_Content_9 = {
    Text = "<Shake:Tidak, atas dasar apa kamu berkata——>"
  },
  AvgDialog_145529_Content_1 = {
    Text = "Musim Semi yang Lain"
  },
  AvgDialog_145529_Content_10 = {
    Text = "<Shake:Tempat ini adalah… di mana…?>"
  },
  AvgDialog_145529_Content_100 = {
    Text = "Entah itu kehidupan yang tenang, maupun orang tua yang penuh kasih sayang."
  },
  AvgDialog_145529_Content_101 = {
    Text = "Bahkan seekor kelinci kecil itu."
  },
  AvgDialog_145529_Content_102 = {
    Text = "Kelinci liar di ladang itu menoleh, sepasang Mata bulat bening menatap balik ke arahnya."
  },
  AvgDialog_145529_Content_103 = {
    Text = "Lalu berbalik, menendang tanah dengan kedua kaki belakangnya, dan menyelinap masuk ke dalam lubang tanah."
  },
  AvgDialog_145529_Content_11 = {
    Text = "Berdasarkan perkataan terakhir Caraboo, kita sekarang Selaras berada di dalam perut gunung."
  },
  AvgDialog_145529_Content_12 = {
    Text = "Yang terpenting saat ini adalah menemukan Jalan untuk Melarikan diri."
  },
  AvgDialog_145529_Content_13 = {
    Text = "Aku juga belum pernah ke tempat ini, sepertinya aku tidak bisa menjadi pemandu kalian."
  },
  AvgDialog_145529_Content_14 = {
    Text = "Jangan khawatir, kita sudah pernah melewati saat-saat yang jauh lebih sulit dari ini."
  },
  AvgDialog_145529_Content_15 = {
    Text = "%player%, apa yang ada di tanganmu itu?"
  },
  AvgDialog_145529_Content_16 = {
    Text = "Eh, ini adalah… Benang Sutra Arachne…"
  },
  AvgDialog_145529_Content_17 = {
    Text = "Entah sejak kapan, Benang Sutra ini diam-diam melilit di jari kelingkingmu."
  },
  AvgDialog_145529_Content_18 = {
    Text = "Benang Sutra yang semula Hening dan lembut itu, kini bersinar memancarkan kilau memesona, ujungnya terbentang secara alami menuju kegelapan di kejauhan."
  },
  AvgDialog_145529_Content_19 = {
    Text = "Apakah ini petunjuk nasib? Mari ikuti dan lihat ke mana arahnya."
  },
  AvgDialog_145529_Content_2 = {
    Text = "kegelapan. kegelapan yang tak berujung."
  },
  AvgDialog_145529_Content_20 = {
    Text = "Caraboo mengikuti Benang Sutra itu, entah sudah berapa lama berjalan. Di ujung Benang Sutra, muncullah secercah cahaya."
  },
  AvgDialog_145529_Content_21 = {Text = "Cahaya…?"},
  AvgDialog_145529_Content_22 = {
    Text = "Cahaya dan bayangan tiba-tiba berubah."
  },
  AvgDialog_145529_Content_23 = {
    Text = "Di sini...?"
  },
  AvgDialog_145529_Content_24 = {
    Text = "Hei, Caraboo, pelan-pelan!"
  },
  AvgDialog_145529_Content_25 = {
    Text = "Lihat, Bibi Rosa, ada kelinci di sana!"
  },
  AvgDialog_145529_Content_26 = {
    Text = "Ah, dia masuk ke dalam lubang!"
  },
  AvgDialog_145529_Content_27 = {
    Text = "Dia Menunggu dari siang hingga malam, namun kelinci itu tidak pernah keluar."
  },
  AvgDialog_145529_Content_28 = {
    Text = "Bibi Rosa, aku jelas melihat kelincinya masuk dari lubang ini!"
  },
  AvgDialog_145529_Content_29 = {
    Text = "Bibi Rosa dengan penuh kasih membelai ujung rambut Caraboo."
  },
  AvgDialog_145529_Content_3 = {
    Text = "Sakit sakit sakit… Aku ini ada di mana?"
  },
  AvgDialog_145529_Content_30 = {
    Text = "Anak bodoh, kelinci itu tidak sesederhana yang kamu kira."
  },
  AvgDialog_145529_Content_31 = {
    Text = "Gua-gua di ladang ini saling terhubung di bawah tanah seperti jaringan lalu lintas yang rumit."
  },
  AvgDialog_145529_Content_32 = {
    Text = "Kelinci putih kecil yang kamu incar itu, sudah kabur entah dari lubang mana."
  },
  AvgDialog_145529_Content_33 = {
    Text = "Lalu harus bagaimana?"
  },
  AvgDialog_145529_Content_34 = {
    Text = "Tidak perlu melakukan apa-apa, Caraboo kecil."
  },
  AvgDialog_145529_Content_35 = {
    Text = "Kita menanam benih di padang, Menyiram, Menunggu mereka matang, memanen, dan menikmati buah yang diberikan Dewa kepada kita."
  },
  AvgDialog_145529_Content_36 = {
    Text = "Tapi, bagaimana kalau aku menginginkan kelinci itu?"
  },
  AvgDialog_145529_Content_37 = {
    Text = "Caraboo kecilku yang tersayang, kita tidak menginginkan kelinci itu. Kalau kamu ingin makan daging, kita bisa pergi ke pasar dan menukarnya dengan buah dan sayuran."
  },
  AvgDialog_145529_Content_38 = {
    Text = "Tapi, bagaimana kalau aku masih menginginkan kelinci itu?"
  },
  AvgDialog_145529_Content_39 = {
    Text = "<Red:Mengapa, aku tidak bisa memiliki kelinci itu?>"
  },
  AvgDialog_145529_Content_4 = {
    Text = "Tanpa perlu bertanya pun Dia sudah tahu. Dia berada di dalam perut cacing."
  },
  AvgDialog_145529_Content_41 = {
    Text = "……………"
  },
  AvgDialog_145529_Content_42 = {
    Text = "Mengapa pada saat seperti ini, aku bisa melihat kenangan masa kanak-kanakku…?"
  },
  AvgDialog_145529_Content_43 = {
    Text = "Tenang. Mungkin karena terlalu lama berjalan dalam kegelapan, aku mulai melihat Bayangan."
  },
  AvgDialog_145529_Content_44 = {
    Text = "Ini bukan Bayangan lho?"
  },
  AvgDialog_145529_Content_45 = {
    Text = "<Shake:Uwah! Ada hantu!!>"
  },
  AvgDialog_145529_Content_46 = {
    Text = "Kamu masih ingat salah satu dari tujuh artefak suci, Benang Sutra nasib? Yang kamu lihat adalah Trajektori nasib."
  },
  AvgDialog_145529_Content_47 = {
    Text = "Selanjutnya, Trajektori nasib akan menunjukkan kepadamu kemungkinan lain, beserta titik percabangannya."
  },
  AvgDialog_145529_Content_48 = {
    Text = "Apa hubungannya dengan aku yang sekarang berada di dalam perut monster ini?"
  },
  AvgDialog_145529_Content_49 = {
    Text = "Karena, itulah keinginanmu. Keinginan adalah sumbu, yang akan menarik setiap orang menuju takdir akhir mereka."
  },
  AvgDialog_145529_Content_5 = {
    Text = "Sialan, menipu orang masuk, malah dimakan sendiri."
  },
  AvgDialog_145529_Content_50 = {
    Text = "Tukang teka-teki macam apa, daripada buang waktu lebih baik beritahu aku cara keluar dari sini! <BigShake:Hei——>"
  },
  AvgDialog_145529_Content_51 = {
    Text = "Bayangan itu menghilang tanpa suara."
  },
  AvgDialog_145529_Content_52 = {
    Text = "Huh, pelit sekali. Tidak ada cara lain, lagipula di dalam rongga perut cacing ini tidak ada jalan bercabang lainnya, terus maju saja."
  },
  AvgDialog_145529_Content_54 = {
    Text = "……………"
  },
  AvgDialog_145529_Content_55 = {
    Text = "Bibi Rosa! Jangan khawatir, aku segera datang membantu!"
  },
  AvgDialog_145529_Content_56 = {
    Text = "Ini... aku?"
  },
  AvgDialog_145529_Content_57 = {
    Text = "Anak baik, Bibi Hanya Saja datang untuk melihatmu."
  },
  AvgDialog_145529_Content_58 = {
    Text = "Bibi Rosa, kaki Bibi tidak kuat, tidak perlu selalu datang ke kebun. Setelah aku selesai memetik kemangi ini, kita pulang bersama untuk memberi makan kelinci."
  },
  AvgDialog_145529_Content_59 = {
    Text = "Sudah kamu lihat belum? Selada Gemuk kita semalam melahirkan banyak sekali anak kelinci, ada yang hitam, putih, abu-abu, kuning, belang, semua warna ada!"
  },
  AvgDialog_145529_Content_6 = {
    Text = "Tunggu, ini apa? Benang Sutra…?"
  },
  AvgDialog_145529_Content_60 = {
    Text = "Caraboo kita sudah tumbuh menjadi gadis besar ya."
  },
  AvgDialog_145529_Content_61 = {
    Text = "Bibi Rosa, Bibi bicara apa. Pekerjaan pertanian ini, waktu aku tiga belas tahun pun sudah bisa kukerjakan sendiri."
  },
  AvgDialog_145529_Content_62 = {
    Text = "Keputusan paling benar yang Bibi buat seumur hidup adalah membawamu dari orang tuamu untuk tinggal bersamaku."
  },
  AvgDialog_145529_Content_63 = {
    Text = "Saat kamu bilang padaku bahwa ayahmu memukulimu dalam keadaan mabuk, aku ragu-ragu semalam penuh, lalu Dini Hari, aku menaiki kereta paling awal."
  },
  AvgDialog_145529_Content_64 = {
    Text = "Hampir saja aku berkelahi dengan ayahmu, baru bisa membawamu pergi."
  },
  AvgDialog_145529_Content_65 = {
    Text = "Sejak saat itu, sudah hampir sepuluh tahun berlalu, bukan?"
  },
  AvgDialog_145529_Content_66 = {
    Text = "Sekarang, tanpa kamu, dengan kedua kakiku ini, entah bagaimana aku bisa hidup sendiri—"
  },
  AvgDialog_145529_Content_67 = {Text = "Ah—ah—"},
  AvgDialog_145529_Content_68 = {
    Text = "Ini adalah, malam itu—malam itu—kemungkinan lain—"
  },
  AvgDialog_145529_Content_69 = {
    Text = "Malam itu, malam ketika dia bertemu dengan \"Cacing Gunung\", malam ketika dia memutuskan untuk membebaskan diri dari nasib dengan tangannya sendiri."
  },
  AvgDialog_145529_Content_7 = {
    Text = "Sehelai Benang Sutra yang berkilau dan bening menjulur dari kegelapan di kejauhan, melayang di hadapan Caraboo."
  },
  AvgDialog_145529_Content_70 = {
    Text = "Milik dunia nyata, malam yang dia alami itu."
  },
  AvgDialog_145529_Content_71 = {
    Text = "Di tengah suara gemeretak api perapian, dia berdiri di depan ranjang ayahnya yang mabuk, ragu-ragu untuk waktu yang sangat lama."
  },
  AvgDialog_145529_Content_72 = {
    Text = "Pergilah, lakukan apa yang sudah lama ingin kamu lakukan."
  },
  AvgDialog_145529_Content_73 = {
    Text = "Dia mengangkat pisau—"
  },
  AvgDialog_145529_Content_74 = {
    Text = "Tepat sekali, begitulah."
  },
  AvgDialog_145529_Content_75 = {
    Text = "Bunuh dia, semua orang bisa mendapatkan kebahagiaan."
  },
  AvgDialog_145529_Content_76 = {
    Text = "Lalu perlahan, perlahan menurunkannya."
  },
  AvgDialog_145529_Content_77 = {
    Text = "Maaf, aku tetap tidak bisa melakukannya."
  },
  AvgDialog_145529_Content_78 = {
    Text = "Pergilah, Asalkan kamu melarikan diri jauh dari sini, kamu tidak perlu lagi menanggung penderitaan."
  },
  AvgDialog_145529_Content_79 = {
    Text = "Makhluk kecil yang tidak berguna."
  },
  AvgDialog_145529_Content_8 = {
    Text = "Tidak peduli tidak peduli, lebih baik kamu tidak sedang menipuku!"
  },
  AvgDialog_145529_Content_80 = {
    Text = "Biarlah, yang aku lihat adalah hal lain yang ada padamu."
  },
  AvgDialog_145529_Content_81 = {
    Text = "Pergilah, dengan lidahmu yang licik itu, kita tetap bisa mendapatkan harta paling berharga."
  },
  AvgDialog_145529_Content_82 = {
    Text = "Pagi hari berikutnya, aku diam-diam bersembunyi di antara jerami di gerobak sapi, menyelinap masuk ke kota terdekat."
  },
  AvgDialog_145529_Content_83 = {
    Text = "Lalu dengan Identitas dan tiket palsu, aku menaiki kereta menuju timur."
  },
  AvgDialog_145529_Content_84 = {
    Text = "Sejak saat itu, aku telah memiliki banyak Identitas — keponakan kondektur kereta, teman Penjaga, Peri Sekte, Dewi Salju Gunung…"
  },
  AvgDialog_145529_Content_85 = {
    Text = "Aku melemparkan semua masa lalu ke belakang, meninggalkannya di malam bersalju saat aku melarikan diri itu."
  },
  AvgDialog_145529_Content_86 = {
    Text = "Kemudian, jauh setelah itu, barulah aku mendengar dari seorang kawan sekampung yang kutemui secara kebetulan di medan perang—"
  },
  AvgDialog_145529_Content_87 = {Text = "Tuan Hans?"},
  AvgDialog_145529_Content_88 = {
    Text = "Suatu hari bersalju, dia mabuk berat."
  },
  AvgDialog_145529_Content_89 = {
    Text = "Api di perapian padam disiram oleh salju yang mencair dan menetes dari langit-langit. Biasanya, putri kecilnya yang akan pergi menyalakan api itu kembali."
  },
  AvgDialog_145529_Content_9 = {
    Text = "Kamu terbangun dari keadaan setengah sadar, di hadapanmu terdapat kekosongan yang lembut, lembap, dan menekan."
  },
  AvgDialog_145529_Content_90 = {
    Text = "Hanya Saja hari itu, entah mengapa putri kecilnya tidak ada di Rumah."
  },
  AvgDialog_145529_Content_91 = {
    Text = "Dia mati kedinginan di malam bersalju itu."
  },
  AvgDialog_145529_Content_92 = {
    Text = "Kami pun tidak pernah melihat gadis kecil itu lagi Setelah itu."
  },
  AvgDialog_145529_Content_93 = {
    Text = "Oh ya, Tuan Peri, mengapa Anda tiba-tiba menanyakan hal ini? Berkat saya, bisakah Anda berikan sekarang?"
  },
  AvgDialog_145529_Content_94 = {
    Text = "Caraboo mengambilkan segenggam penuh permen untuk pemuda di hadapannya."
  },
  AvgDialog_145529_Content_95 = {
    Text = "Demi Peri di atas, satu butir setiap hari — setelah permen Berkat ini habis, luka di kaki Anda akan sembuh."
  },
  AvgDialog_145529_Content_96 = {
    Text = "Meskipun dalam hatinya Dia tahu, tidak ada permen mana pun yang bisa menyembuhkan kedua kaki pemuda itu yang telah diamputasi."
  },
  AvgDialog_145529_Content_98 = {
    Text = "……………"
  },
  AvgDialog_145529_Content_99 = {
    Text = "Sungguh lucu, benar-benar lucu. Ternyata malam itu, Asalkan aku tidak melakukan apa-apa, aku sudah bisa mendapatkan kebahagiaan yang kuinginkan."
  },
  AvgDialog_145530_Content_1 = {
    Text = "Mimpi Agung"
  },
  AvgDialog_145530_Content_10 = {
    Text = "Kalau begitu, aku mendukungmu."
  },
  AvgDialog_145530_Content_11 = {
    Text = "Aku mendukungmu, untuk menemukan kembali dirimu yang telah dibuang."
  },
  AvgDialog_145530_Content_12 = {
    Text = "Bagaimanapun juga, kita memang orang yang paling egois."
  },
  AvgDialog_145530_Content_13 = {
    Text = "Gunung Salju itu mati."
  },
  AvgDialog_145530_Content_14 = {
    Text = "<Shake:Sudah berakhir…>"
  },
  AvgDialog_145530_Content_15 = {
    Text = "Di tengah Gunung Salju itu terbelah sebuah Luka yang mengerikan, dari puncak kepala cacing hingga ujung rongga perutnya."
  },
  AvgDialog_145530_Content_16 = {
    Text = "Tubuh cacing itu mengikuti Luka tersebut, perlahan-lahan, perlahan-lahan runtuh ke kedua sisinya."
  },
  AvgDialog_145530_Content_17 = {
    Text = "Kalian pun ikut jatuh bebas seiring runtuhnya puncak gunung itu."
  },
  AvgDialog_145530_Content_18 = {
    Text = "<Shake:Hati-hati, gunung akan runtuh!>"
  },
  AvgDialog_145530_Content_19 = {
    Text = "Di tengah suara Angin saat jatuh, kamu tanpa sempat bersiap, mendengar sebuah Bisikan."
  },
  AvgDialog_145530_Content_2 = {
    Text = "Apakah kamu sudah memikirkannya?"
  },
  AvgDialog_145530_Content_20 = {
    Text = "Belum berakhir."
  },
  AvgDialog_145530_Content_21 = {
    Text = "Caraboo mengulurkan tangannya."
  },
  AvgDialog_145530_Content_22 = {
    Text = "Di Wajahnya yang penuh bekas air mata, tersungging sebuah senyum yang santai."
  },
  AvgDialog_145530_Content_23 = {
    Text = "Kemudian, di tengah gravitasi yang tak bisa kalian kendalikan, tujuh lingkaran cahaya pun menyala."
  },
  AvgDialog_145530_Content_24 = {
    Text = "Yang mati……Hanya Saja gunung bersalju……ritual……masih berjalan!"
  },
  AvgDialog_145530_Content_25 = {
    Text = "Pada saat itu, Seolah-olah langit dan Bumi kehilangan segala suara."
  },
  AvgDialog_145530_Content_26 = {
    Text = "Kamu Hanya melihat bibir dan lidahnya bergerak pelan, mengucapkan sebuah kalimat yang baru Mulai bergema di antara langit dan Bumi beberapa detik kemudian."
  },
  AvgDialog_145530_Content_27 = {
    Text = "Keinginanku, adalah agar di dunia ini tidak ada lagi Kebohongan."
  },
  AvgDialog_145530_Content_28 = {
    Text = "Tepat saat kata-katanya terucap, dunia di depan mata pun hancur berantakan."
  },
  AvgDialog_145530_Content_29 = {
    Text = "Abu berwarna perak yang bertebaran, jatuh dengan sangat ringan dan sangat lambat dari ketinggian yang jauh."
  },
  AvgDialog_145530_Content_3 = {
    Text = "Ya, aku sudah memutuskan."
  },
  AvgDialog_145530_Content_30 = {
    Text = "Itu adalah sebuah keruntuhan yang sunyi, sebuah crash yang perlahan, sebuah Tirai ditutup dari sebuah Mimpi yang telah ada sejak zaman purba."
  },
  AvgDialog_145530_Content_31 = {
    Text = "Puncak gunung."
  },
  AvgDialog_145530_Content_32 = {
    Text = "Salju yang menumpuk."
  },
  AvgDialog_145530_Content_33 = {Text = "Langit."},
  AvgDialog_145530_Content_34 = {Text = "Bumi."},
  AvgDialog_145530_Content_35 = {
    Text = "Segala sesuatu yang pernah ada, seperti Kebohongan yang terungkap, lenyap menjadi Void."
  },
  AvgDialog_145530_Content_36 = {Text = "...Kenapa?"},
  AvgDialog_145530_Content_37 = {
    Text = "Suatu pengetahuan yang seharusnya tidak Kamu ketahui, beserta kenangan yang jauh, menancap seperti Spike ke dalam benakmu."
  },
  AvgDialog_145530_Content_38 = {
    Text = "Kapal ini adalah sebuah mimpi, tetapi ketika tirai kebohongan terangkat..."
  },
  AvgDialog_145530_Content_39 = {
    Text = "Seluruh dunia juga adalah mimpi seseorang, hanya saja mimpi ini lebih besar, lebih samar, dan lebih jauh……"
  },
  AvgDialog_145530_Content_4 = {
    Text = "Ini adalah kebohongan, ini adalah pengkhianatan."
  },
  AvgDialog_145530_Content_40 = {
    Text = "Bahkan bulan dan bintang pun bersumber dari khayalan-Nya, hanya makhluk hidup yang terjerat dengan roh-Nya yang bisa……"
  },
  AvgDialog_145530_Content_41 = {
    Text = "\"Seluruh dunia adalah kebohongan yang sangat besar\"."
  },
  AvgDialog_145530_Content_42 = {
    Text = "Seiring dengan kesadaran seperti itu, kehancuran semakin cepat. Di langit turunlah hujan lebat berwarna perak."
  },
  AvgDialog_145530_Content_43 = {
    Text = "Hujan lebat itu jatuh ke dalam air. Pecahan-pecahan yang dulunya adalah \"dunia\" itu, berubah menjadi tetesan hujan perak, perlahan-lahan tenggelam menuju Aequor yang tak bertepi."
  },
  AvgDialog_145530_Content_44 = {
    Text = "Dan Kamu berada di dalam air laut itu."
  },
  AvgDialog_145530_Content_45 = {
    Text = "Tenggelam, tenggelam."
  },
  AvgDialog_145530_Content_46 = {
    Text = "Hingga ilusi yang panjang itu berakhir, Kamu kembali membuka kedua Mata."
  },
  AvgDialog_145530_Content_47 = {
    Text = "Menghadapi kenyataan nyata dari dunia ini."
  },
  AvgDialog_145530_Content_48 = {
    Text = "Di dasar Aequor yang paling dalam dan paling gelap."
  },
  AvgDialog_145530_Content_49 = {
    Text = "Negara Dewa yang megah dan telah lama musnah, akhirnya menampakkan wujud sejatinya."
  },
  AvgDialog_145530_Content_5 = {
    Text = "Semua orang merawatmu dengan penuh perhatian, mereka pun memiliki keinginan yang ingin mereka wujudkan."
  },
  AvgDialog_145530_Content_6 = {
    Text = "Namun kesempatan untuk membuat permintaan, hanya ada satu kali."
  },
  AvgDialog_145530_Content_7 = {
    Text = "Meski begitu, apakah kamu tetap ingin meminta <Yellow:\"itu\">?"
  },
  AvgDialog_145530_Content_8 = {
    Text = "Tidak ada keinginan yang lebih penting dari ini."
  },
  AvgDialog_145530_Content_9 = {
    Text = "Bayangan itu tersenyum."
  },
  AvgDialog_145531_Content_1 = {
    Text = "Malam yang Baik"
  },
  AvgDialog_145531_Content_10 = {
    Text = "Di belakangnya, seseorang diam-diam Buka mata sebelah, Melihat secara diam-diam bayangan punggungnya yang menjauh."
  },
  AvgDialog_145531_Content_11 = {
    Text = "Tinct berjalan perlahan mengikuti asal suara nyanyian itu, serpihan es dan tanah beku berderak halus di bawah sepatunya yang bersol tipis."
  },
  AvgDialog_145531_Content_12 = {
    Text = "(Ini adalah… danau es tadi siang…)"
  },
  AvgDialog_145531_Content_13 = {
    Text = "(Tapi ada sedikit yang berbeda…)"
  },
  AvgDialog_145531_Content_14 = {
    Text = "Air danau yang membeku di siang hari, entah mengapa telah Bangkit."
  },
  AvgDialog_145531_Content_15 = {
    Text = "Permukaan air yang tenang tanpa riak Buka mata menatap langit, bagaikan sebuah cermin jernih yang dengan diam memantulkan Bulan yang abadi sejak zaman dahulu kala."
  },
  AvgDialog_145531_Content_16 = {
    Text = "Faint, apakah itu kamu?"
  },
  AvgDialog_145531_Content_17 = {
    Text = "(Air danau… sangat jernih…)"
  },
  AvgDialog_145531_Content_18 = {
    Text = "Dia memandang ke dasar danau."
  },
  AvgDialog_145531_Content_19 = {
    Text = "Air danau begitu dalam hingga tak terlihat dasarnya, seolah-olah Pierce Bumi, menuju suatu tempat yang jauh lebih jauh dari Bintang-bintang."
  },
  AvgDialog_145531_Content_2 = {
    Text = "Di tengah malam, Tinct terbangun oleh suara yang sayup-sayup dari kejauhan."
  },
  AvgDialog_145531_Content_20 = {
    Text = "Di antara hembusan angin, terdengar nyanyian yang sayup-sayup, serak, tua, seolah telah bertahan melewati erosi waktu yang tak terbayangkan lamanya namun belum juga berhenti."
  },
  AvgDialog_145531_Content_21 = {
    Text = "<Italic:La——la la~la~♪>"
  },
  AvgDialog_145531_Content_22 = {
    Text = "Tinct memejamkan mata, menarik napas dalam-dalam."
  },
  AvgDialog_145531_Content_23 = {
    Text = "(Melodi yang familiar… aroma… yang dirindukan…)"
  },
  AvgDialog_145531_Content_24 = {
    Text = "Tekstur suaranya mengingatkan pada dasar sungai yang kering, pada lapisan batu pasir yang telah terkikis angin selama seratus ribu tahun, pada teriakan Hutan purba yang tertekan menjadi batu bara di bawah beban zaman geologi."
  },
  AvgDialog_145531_Content_25 = {
    Text = "(Ini sepertinya… melodi… dari Bintang Terasing…)"
  },
  AvgDialog_145531_Content_26 = {
    Text = "Kenangan seribu tahun lalu perlahan Mulai Pemulihan, Dia Mulai mencoba bersenandung, mencoba mengikuti nyanyian yang melayang-layang itu."
  },
  AvgDialog_145531_Content_27 = {
    Text = "<Shake:La——la~la la la~♪>"
  },
  AvgDialog_145531_Content_28 = {
    Text = "Dia merasakannya, Dia menangkapnya."
  },
  AvgDialog_145531_Content_29 = {
    Text = "Di Wajah-nya terpancar kegembiraan yang tulus."
  },
  AvgDialog_145531_Content_3 = {
    Text = "(Di luar… ini… suara nyanyian?)"
  },
  AvgDialog_145531_Content_30 = {
    Text = "Jangkauan suaranya meluas, ke atas. Suara jernih bak bulbul, dengan lembut dan ringan Entwined dengan melodi dasar yang serak itu."
  },
  AvgDialog_145531_Content_31 = {
    Text = "Dua suara Mulai saling menarik, saling melilit, saling mendekat."
  },
  AvgDialog_145531_Content_32 = {
    Text = "<Change>La la la la la la~♪"
  },
  AvgDialog_145531_Content_33 = {
    Text = "Lapisan es menutup sedikit demi sedikit, di kedalaman danau, tak terhitung wajah pucat pasi mengangkat kepala mengikuti alunan nyanyian."
  },
  AvgDialog_145531_Content_34 = {
    Text = "Namun Tinct sama sekali tidak menyadarinya."
  },
  AvgDialog_145531_Content_35 = {
    Text = "Hanya ada nyanyian. Nyanyian yang melampaui Wilayah Salju tanah beku, melampaui samudra bintang semesta, melampaui zaman abadi, berubah menjadi sesuatu yang seharusnya dianggap kekal oleh setiap orang."
  },
  AvgDialog_145531_Content_36 = {
    Text = "Ya, aku tidak seharusnya terus membohongi diri sendiri lagi……"
  },
  AvgDialog_145531_Content_37 = {
    Text = "Aku sudah… tidak ingin mencari lagi… Harapan tidak ada di mana pun… Dia ada dalam ingatanku, dan hanya dalam ingatanku……"
  },
  AvgDialog_145531_Content_38 = {
    Text = "Teman lama di dalam air mengulurkan tangan kepadanya."
  },
  AvgDialog_145531_Content_39 = {
    Text = "Suara nyanyian tua yang lembut memanggilnya, memanggil namanya dari seribu tahun lalu."
  },
  AvgDialog_145531_Content_4 = {
    Text = "Suara itu sangat lembut dan sangat jauh, menembus lapisan es dan bebatuan yang tak terhitung, meresap naik dari kedalaman yang tak terukur."
  },
  AvgDialog_145531_Content_41 = {
    Text = "Aku seharusnya menyerah……"
  },
  AvgDialog_145531_Content_42 = {
    Text = "Perjalanan ini terlalu panjang, terlalu panjang, aku sudah, sangat lelah sejak lama……"
  },
  AvgDialog_145531_Content_43 = {
    Text = "Suara panggilan itu bergetar menyusuri tulang-tulangnya, menghadiahkan penghiburan yang ia rindukan. Kesedihan yang tak tahu harus ia taruh di mana, duka yang tak tahu harus ia curahkan ke mana, akhirnya sepenuhnya diketahui dan diterima oleh suatu keberadaan."
  },
  AvgDialog_145531_Content_44 = {
    Text = "<Shake:Peluklah aku, Faint… bayangan dalam ingatanku… Peluklah aku, seperti dulu……>"
  },
  AvgDialog_145531_Content_45 = {
    Text = "<Shake:Berikanlah aku, ketenangan yang aku rindukan……>"
  },
  AvgDialog_145531_Content_46 = {
    Text = "Dia perlahan-lahan, perlahan-lahan, melangkah masuk ke dalam danau yang tenang."
  },
  AvgDialog_145531_Content_47 = {
    Text = "Air danau tidak beriak sedikit pun, seperti lidah yang dingin, dengan lembut menjilati pinggang, bahu, dan tenggorokannya."
  },
  AvgDialog_145531_Content_48 = {
    Text = "<Change>La la……"
  },
  AvgDialog_145531_Content_49 = {
    Text = "Dia masih bernyanyi."
  },
  AvgDialog_145531_Content_5 = {
    Text = "Suaranya serak dan lambat, setiap suku kata bagaikan pasir yang tersapu angin melintasi tanah; keras kepala dan tak pernah berhenti, seperti sungai bawah tanah yang mengalir selamanya."
  },
  AvgDialog_145531_Content_50 = {
    Text = "Bayangan tubuhnya, raganya, keberadaannya perlahan memudar bersama nyanyian itu, melebur dan menyebar dalam cahaya bulan."
  },
  AvgDialog_145531_Content_51 = {
    Text = "Sebuah pikiran, sebuah pikiran yang begitu lemah hingga hampir tak bisa ditangkap, pada saat itu, entah mengapa merayap ke dalam kesadaran Tinct."
  },
  AvgDialog_145531_Content_52 = {
    Text = "(Aneh… hari ini… seharusnya bulan baru…)"
  },
  AvgDialog_145531_Content_53 = {
    Text = "Lalu— permukaan danau tiba-tiba ambruk ke dalam."
  },
  AvgDialog_145531_Content_54 = {
    Text = "Tidak ada percikan air, tidak ada teriakan. Hanya suara nyanyian yang terus bergema."
  },
  AvgDialog_145531_Content_55 = {
    Text = "Bulan di langit entah kapan telah menghilang."
  },
  AvgDialog_145531_Content_56 = {
    Text = "Hanya tersisa air danau yang beriak dengan pantulan bulan, memantulkan bayangan Tinct yang jelas."
  },
  AvgDialog_145531_Content_58 = {
    Text = "Pagi hari berikutnya."
  },
  AvgDialog_145531_Content_59 = {
    Text = "Apakah ada yang melihat Tinct?"
  },
  AvgDialog_145531_Content_6 = {
    Text = "(Sangat jauh, namun terasa begitu akrab…)"
  },
  AvgDialog_145531_Content_60 = {
    Text = "Semua orang menggelengkan kepala."
  },
  AvgDialog_145531_Content_61 = {
    Text = "Hmm… semalam aku mendengar ada gerakan di dekatku, tapi aku langsung tertidur lagi."
  },
  AvgDialog_145531_Content_62 = {
    Text = "Aku sudah mencari ke seluruh tenda, dia tidak ada di mana pun."
  },
  AvgDialog_145531_Content_63 = {
    Text = "Mungkin dia keluar di tengah jalan?"
  },
  AvgDialog_145531_Content_64 = {
    Text = "Kemarin saat dia berada di tepi danau es, kondisinya sudah sangat tidak beres…"
  },
  AvgDialog_145531_Content_65 = {
    Text = "Evelyn bergumam dengan gelisah."
  },
  AvgDialog_145531_Content_66 = {
    Text = "Dia bahkan tidak membawa tabung oksigen saat keluar."
  },
  AvgDialog_145531_Content_67 = {
    Text = "Ini adalah puncak dengan ketinggian enam ribu meter, setiap orang harus, dan hanya bisa, bertanggung jawab atas HP mereka sendiri."
  },
  AvgDialog_145531_Content_68 = {
    Text = "Setidaknya… setidaknya pergi lihat ke tepi danau es."
  },
  AvgDialog_145531_Content_69 = {Text = "Mau pergi?"},
  AvgDialog_145531_Content_7 = {
    Text = "Rekan-rekan tim di dalam tenda di sisinya telah terlelap karena kelelahan mendaki di siang hari, bahkan anjing pemandu yang seharusnya berjaga pun mengeluarkan dengkuran halus yang teratur."
  },
  AvgDialog_145531_Content_70 = {
    Text = "Kamu ingin pergi mencari Tinct, tidak mau menyerah pada secuil kemungkinan pun. Namun kamu juga sadar, setiap pilihan yang kamu buat menanggung nyawa seluruh anggota tim."
  },
  AvgDialog_145531_Content_71 = {
    Text = "Ayo pergi, ketinggian di sini dan danau es hampir tidak ada bedanya, waktu pergi-pulang masih dalam batas yang bisa dikendalikan."
  },
  AvgDialog_145531_Content_72 = {
    Text = "Satu-satunya hal yang perlu diperhatikan hanyalah binatang buas gunung salju di sepanjang jalan."
  },
  AvgDialog_145531_Content_8 = {
    Text = "Keluarlah untuk melihat-lihat."
  },
  AvgDialog_145531_Content_9 = {
    Text = "Dia menarik kantong tidurnya, membuka tenda, lalu perlahan-lahan merangkak keluar."
  },
  AvgDialog_145532_Content_1 = {
    Text = "Arah Berlawanan"
  },
  AvgDialog_145532_Content_10 = {
    Text = "Kemudian, giliran Evelyn. William berjaga di belakang, Tatapannya yang tenang dan fokus menjaga semua orang."
  },
  AvgDialog_145532_Content_11 = {Text = "Tunggu…"},
  AvgDialog_145532_Content_12 = {
    Text = "Tatapan Evelyn, menatap sepotong tali di dinding tebing yang retak."
  },
  AvgDialog_145532_Content_13 = {
    Text = "Ini adalah… pengait tali mereka! Aku mengenali tanda ini!"
  },
  AvgDialog_145532_Content_14 = {
    Text = "Sudut yang dibentuk oleh tepi Salju! Sudut yang dibentuk oleh tepi Salju menciptakan zona aman, sehingga tempat ini tidak akan tertutup oleh Salju yang jatuh!"
  },
  AvgDialog_145532_Content_15 = {
    Text = "Kamu memandang ke bawah ke arah Evelyn. Hanya sekali lihat, Bayangan jatuh itu sudah membuatmu pusing."
  },
  AvgDialog_145532_Content_16 = {
    Text = "Aku harus pergi mencarinya!"
  },
  AvgDialog_145532_Content_17 = {
    Text = "Evelyn melepas pengait talinya, perlahan-lahan turun ke bawah."
  },
  AvgDialog_145532_Content_18 = {
    Text = "Terlalu berbahaya, Evelyn!"
  },
  AvgDialog_145532_Content_19 = {
    Text = "Tidak apa-apa, aku memang datang untuk ini! Kalau bicara soal bahaya, pendakian itu sendiri sudah cukup berbahaya!"
  },
  AvgDialog_145532_Content_2 = {
    Text = "Empat orang, seperti empat dadu, melayang di atas papan permainan bernama tebing es."
  },
  AvgDialog_145532_Content_20 = {
    Text = "Kalian tidak perlu khawatir tentang aku! Aku akan segera menyusul!"
  },
  AvgDialog_145532_Content_21 = {
    Text = "Di kedalaman celah es itu, seolah-olah ada sesuatu yang menggoda Dia."
  },
  AvgDialog_145532_Content_22 = {
    Text = "Evelyn, kamu tidak bisa——!"
  },
  AvgDialog_145532_Content_23 = {
    Text = "Kamu mengulurkan tangan ke arah tali pengamanmu, menarik napas dalam-dalam, bersiap untuk jatuh."
  },
  AvgDialog_145532_Content_24 = {
    Text = "%player%......"
  },
  AvgDialog_145532_Content_25 = {
    Text = "William menahan tanganmu, menggelengkan kepala perlahan."
  },
  AvgDialog_145532_Content_26 = {
    Text = "Tidak ada yang tahu apakah Helot akan kembali atau tidak, kita tidak bisa membiarkan semua orang tergantung di udara."
  },
  AvgDialog_145532_Content_27 = {
    Text = "Lihat Di Atas."
  },
  AvgDialog_145532_Content_28 = {
    Text = "Caraboo sudah lebih dulu melewati tebing es terakhir."
  },
  AvgDialog_145532_Content_29 = {
    Text = "Ke atas, adalah tujuan akhir perjalanan ini, tanah yang dijanjikan tempat semua keinginan terwujud."
  },
  AvgDialog_145532_Content_3 = {
    Text = "Setiap orang menggenggam erat tali pengaman di tangan mereka, berjuang keras mencari pijakan berikutnya."
  },
  AvgDialog_145532_Content_30 = {
    Text = "Ke bawah, adalah jurang kegelapan yang tak berdasar."
  },
  AvgDialog_145532_Content_31 = {
    Text = "Tapi kita tidak bisa kehilangan rekan tim lagi——!"
  },
  AvgDialog_145532_Content_32 = {Text = "Aku tahu."},
  AvgDialog_145532_Content_33 = {
    Text = "Jadi, serahkan padaku."
  },
  AvgDialog_145532_Content_34 = {
    Text = "Sebelum kamu sempat bereaksi, William sudah melepaskan simpul tali dan jatuh ke bawah."
  },
  AvgDialog_145532_Content_35 = {
    Text = "Dinding es yang begitu sulit didaki, ternyata begitu mudah saat jatuh, dalam sekejap William dan Evelyn sudah menjadi dua titik kecil yang jauh di dalam celah es itu."
  },
  AvgDialog_145532_Content_36 = {
    Text = "Kamu hanya bisa memandang Evelyn dan William turun semakin rendah, menuju celah es itu."
  },
  AvgDialog_145532_Content_37 = {
    Text = "Lalu kamu mendongakkan kepala, dan memaku pasak batu berikutnya."
  },
  AvgDialog_145532_Content_39 = {
    Text = "……………"
  },
  AvgDialog_145532_Content_4 = {
    Text = "Di Atas ada batu karang, kita harus mendakinya."
  },
  AvgDialog_145532_Content_40 = {
    Text = "Celah es itu tak terlihat dasarnya, saat kembali menginjak tanah datar, suasana sudah gelap gulita tak terlihat apa pun."
  },
  AvgDialog_145532_Content_41 = {
    Text = "Tunggu, Evelyn…"
  },
  AvgDialog_145532_Content_42 = {
    Text = "Cahaya lampu kepala yang bergerak Tari menjelajah ke depan."
  },
  AvgDialog_145532_Content_43 = {
    Text = "Di bawah celah es tampaknya terdapat sebuah gua stalaktit, udaranya berbeda dari tempat lain. Dingin, lembap, dan Angin membawa bau asing yang tak dapat dijelaskan."
  },
  AvgDialog_145532_Content_44 = {
    Text = "Hati-hati dengan langkahmu, ada cekungan di sini…"
  },
  AvgDialog_145532_Content_45 = {
    Text = "Kata-katanya tersangkut di tenggorokan, berubah menjadi tarikan napas dingin yang tertahan."
  },
  AvgDialog_145532_Content_46 = {
    Text = "Di tempat yang disapu cahaya lampu, terdapat puluhan tulang belulang yang telah membatu seperti lilin."
  },
  AvgDialog_145532_Content_47 = {
    Text = "Mereka mempertahankan posisi saat jatuh, ada yang meringkuk, ada yang berpelukan, diam-diam, berlapis-lapis menutupi lantai."
  },
  AvgDialog_145532_Content_48 = {
    Text = "Ini adalah… seragam ekspedisi Green."
  },
  AvgDialog_145532_Content_49 = {
    Text = "Mereka semua ada di sini."
  },
  AvgDialog_145532_Content_5 = {
    Text = "Kalian bergerak dengan sangat hati-hati melewati batu besar, memastikan pijakan di bawah adalah batu karang yang kokoh, atau salju yang Longgar."
  },
  AvgDialog_145532_Content_50 = {
    Text = "Sejenak kemudian, Evelyn berbalik, menatap mata William dengan serius."
  },
  AvgDialog_145532_Content_51 = {
    Text = "Sepertinya, di sini juga tidak banyak informasi yang kalian butuhkan, bukan?"
  },
  AvgDialog_145532_Content_52 = {
    Text = "Kalau begitu, bisakah kamu membiarkan aku sendirian di sini sebentar? Aku ingin mencari tahu, apakah dia ada di sini."
  },
  AvgDialog_145532_Content_53 = {
    Text = "Kalau bisa, lebih baik aku bisa berbicara dengannya."
  },
  AvgDialog_145532_Content_54 = {
    Text = "Pada jenazah-jenazah ini, mungkin terdapat bakteri berbahaya…"
  },
  AvgDialog_145532_Content_55 = {
    Text = "Evelyn mengungkapkan ketekunannya melalui tatapan matanya."
  },
  AvgDialog_145532_Content_56 = {
    Text = "Aku mengerti."
  },
  AvgDialog_145532_Content_57 = {
    Text = "Tapi, kamu berjanji padaku, kamu pasti akan keluar dengan selamat."
  },
  AvgDialog_145532_Content_58 = {
    Text = "Hmm, baik, aku berjanji padamu. Aku pasti akan menyelesaikan pendakian ke puncak."
  },
  AvgDialog_145532_Content_59 = {
    Text = "William mengangguk."
  },
  AvgDialog_145532_Content_6 = {
    Text = "Setelah akhirnya berhasil melewatinya, belum sempat kalian menarik napas, sebuah celah yang tak terlihat dasarnya muncul di bawah kaki."
  },
  AvgDialog_145532_Content_60 = {
    Text = "Aku menunggumu di mulut gua."
  },
  AvgDialog_145532_Content_62 = {
    Text = "……………"
  },
  AvgDialog_145532_Content_63 = {
    Text = "Setelah waktu yang sangat lama, begitu lama hingga William Hampir tidak bisa menahan dorongan untuk masuk dan melihat sendiri, akhirnya terdengar suara gemerisik gesekan pakaian dari dalam gua."
  },
  AvgDialog_145532_Content_64 = {
    Text = "Kemudian Evelyn muncul."
  },
  AvgDialog_145532_Content_65 = {
    Text = "Kamu… menemukannya?"
  },
  AvgDialog_145532_Content_66 = {
    Text = "Hmm, sudah ketemu."
  },
  AvgDialog_145532_Content_67 = {
    Text = "Evelyn mengangguk, nada bicaranya tenang, tidak terdengar sedikit pun gejolak."
  },
  AvgDialog_145532_Content_68 = {
    Text = "Turut berduka."
  },
  AvgDialog_145532_Content_69 = {
    Text = "Tidak perlu."
  },
  AvgDialog_145532_Content_7 = {
    Text = "Hati-hati, jangan lihat ke bawah."
  },
  AvgDialog_145532_Content_70 = {
    Text = "Evelyn tertawa kecil."
  },
  AvgDialog_145532_Content_71 = {
    Text = "Aku sudah tahu ini akan menjadi hasilnya."
  },
  AvgDialog_145532_Content_72 = {
    Text = "Kamu juga sama, bukan?"
  },
  AvgDialog_145532_Content_73 = {
    Text = "Aku bisa merasakannya, kamu juga sedang mencari seseorang yang tidak mungkin kembali."
  },
  AvgDialog_145532_Content_74 = {
    Text = "Selalu begini."
  },
  AvgDialog_145532_Content_75 = {
    Text = "Di awal-awal waktu itu, selalu menyimpan harapan, berpikir bahwa mungkin dia akan kembali besok."
  },
  AvgDialog_145532_Content_76 = {
    Text = "Lalu satu hari esok…"
  },
  AvgDialog_145532_Content_77 = {
    Text = "…lalu hari esok berikutnya."
  },
  AvgDialog_145532_Content_78 = {
    Text = "Harapan semakin menipis, sementara Batu di dasar hati pun semakin berat menekan."
  },
  AvgDialog_145532_Content_79 = {
    Text = "Ia terus Jatuh hari demi hari, Jatuh terus."
  },
  AvgDialog_145532_Content_8 = {
    Text = "Kamu mengikuti tepat di belakang Naraka, berpegangan pada tali dengan sekuat tenaga untuk melewati celah itu."
  },
  AvgDialog_145532_Content_80 = {
    Text = "Hingga suatu hari, kamu Menemukan bahwa kamu tidak lagi memikirkan hal itu."
  },
  AvgDialog_145532_Content_81 = {
    Text = "Kamu makan, tidur, bekerja, bepergian, berbicara dengan orang lain, bercanda seperti biasa…"
  },
  AvgDialog_145532_Content_82 = {
    Text = "Lalu, untuk waktu yang sangat lama, tidak lagi menyebutnya."
  },
  AvgDialog_145532_Content_83 = {
    Text = "Nada suara Evelyn berubah sedikit."
  },
  AvgDialog_145532_Content_84 = {
    Text = "Tapi kamu tahu, kamu tidak melupakannya, kamu tidak pernah melupakannya."
  },
  AvgDialog_145532_Content_85 = {
    Text = "Kamu tidak akan pernah melupakannya."
  },
  AvgDialog_145532_Content_86 = {
    Text = "Hanya butuh satu legenda, satu percikan api, dan ia akan Mulai Membakar…"
  },
  AvgDialog_145532_Content_87 = {
    Text = "Itu akan menelanmu…"
  },
  AvgDialog_145532_Content_88 = {
    Text = "…membakarmu hingga habis."
  },
  AvgDialog_145532_Content_89 = {
    Text = "William mendongak tiba-tiba, menatap langsung Tatapan Evelyn."
  },
  AvgDialog_145532_Content_9 = {
    Text = "Saat pandangan sekilas menyapu ke sana, Hanya terlihat kegelapan pekat di dalam celah yang membuat jantung berdegup kencang, tak tahu di mana ujungnya."
  },
  AvgDialog_145532_Content_90 = {
    Text = "Sementara pihak lain hanya memandang balik dengan lembut, apakah yang memenuhi kedua Mata itu adalah api atau kekosongan, terhalang oleh pantulan kacamata pelindung, ia tidak bisa membedakannya."
  },
  AvgDialog_145532_Content_91 = {
    Text = "Jangan melamun, ayo pergi. Aku sudah berjanji padamu, akan mendaki puncak bersama kalian, bukan begitu?"
  },
  AvgDialog_145532_Content_92 = {
    Text = "Entah mengapa, William selalu merasa, meskipun tatapan mereka bertemu, namun tujuan bicara lawan bicaranya itu tampaknya bukan dirinya."
  },
  AvgDialog_145532_Content_93 = {
    Text = "Evelyn tidak lagi menunggunya. Dia berbalik berjalan ke luar gua, membungkuk memeriksa tali pengaman, gerakannya begitu cekatan seolah-olah pengakuan tadi tidak pernah terjadi."
  },
  AvgDialog_145532_Content_94 = {
    Text = "William berdiri di tempat, tenggorokannya kering dan serak. Ia melirik punggung wanita itu yang semakin menjauh, lalu berbalik memandang lubang gelap di belakangnya."
  },
  AvgDialog_145532_Content_95 = {
    Text = "Dia tidak menemukan alasan untuk bertahan satu detik lebih lama. Dia menarik kembali tatapannya, diam-diam mengikuti langkah kakinya."
  },
  AvgDialog_145534_Content_1 = {
    Text = "Sandiwara selesai. Sekarang, gunung bersalju akan menelan kalian bulat-bulat."
  },
  AvgDialog_145534_Content_10 = {
    Text = "Puncak gunung Mencabik-cabik dari tengah, semakin lebar menganga, berubah menjadi mulut raksasa yang membelah langit dan Bumi; air liur merah darah mengalir deras di antara lapisan taring yang bertumpuk, jatuh bagai hujan."
  },
  AvgDialog_145534_Content_11 = {
    Text = "Mulut raksasa itu tiba-tiba menutup —"
  },
  AvgDialog_145534_Content_12 = {
    Text = "Sebelum orang-orang sempat mengeluarkan teriakan pertama mereka, mereka sudah ditelan ke dalam perutnya yang tak berdasar."
  },
  AvgDialog_145534_Content_13 = {
    Text = "Bumi berhenti Guncangan, dan di antara Salju yang berjatuhan, sebuah topi runcing kecil muncul berdiri."
  },
  AvgDialog_145534_Content_14 = {
    Text = "Caraboo mengibaskan Salju yang memenuhi tubuhnya, dengan puas memeriksa hasil kerjanya —"
  },
  AvgDialog_145534_Content_15 = {
    Text = "Mengapa? Mengapa Kamu masih di sini?"
  },
  AvgDialog_145534_Content_16 = {
    Text = "Sosok lain yang seharusnya tidak ada, sendirian, terpencil."
  },
  AvgDialog_145534_Content_17 = {
    Text = "Aku pun ingin tahu, mengapa aku masih di sini."
  },
  AvgDialog_145534_Content_18 = {
    Text = "Kamu baru saja bilang, para pengunjung mempersembahkan keinginan mereka kepada gunung, dan gunung mengabulkan permohonan mereka."
  },
  AvgDialog_145534_Content_19 = {
    Text = "Mungkin karena, dibandingkan kalian semua, aku tidak punya keinginan apa-apa, terlalu biasa, terlalu sederhana, tidak cukup lezat?"
  },
  AvgDialog_145534_Content_2 = {
    Text = "Caraboo berbalik, menghadap deretan pegunungan yang membentang, menghadap badai Angin dan Salju yang luas."
  },
  AvgDialog_145534_Content_20 = {
    Text = "Tidak, tidak mungkin. Apakah kamu tidak punya keinginan yang ingin kamu serahkan kepada gunung?"
  },
  AvgDialog_145534_Content_21 = {
    Text = "Caraboo membelalakkan matanya, dalam pertanyaannya tersirat sedikit rasa tidak percaya dan kemarahan."
  },
  AvgDialog_145534_Content_22 = {
    Text = "Tidak ada. Satu-satunya keinginanku dalam perjalanan ini sudah terwujud."
  },
  AvgDialog_145534_Content_23 = {
    Text = "Di bawah tebing terakhir, aku menemukan sisa-sisa jasadnya. Sungguh beruntung, dia tersangkut di celah batu, tidak tertimbun Salju."
  },
  AvgDialog_145534_Content_24 = {
    Text = "Raganya sudah mengalami Pembusukan, tapi Plakat-nya masih ada. Aku masih bisa mengenalinya, masih bisa memastikan keberadaannya."
  },
  AvgDialog_145534_Content_25 = {
    Text = "Bagaimana mungkin, bagaimana mungkin bisa terpenuhi semudah itu!"
  },
  AvgDialog_145534_Content_26 = {
    Text = "Begitulah kenyataannya. Keinginan manusia biasa memang seharusnya bukan sesuatu yang perlu diselesaikan dengan kekuatan ilahi."
  },
  AvgDialog_145534_Content_27 = {
    Text = "Ada kabar baik lainnya. Berdasarkan perkiraan dari perlengkapan yang dibawanya, mereka mengalami kecelakaan dalam perjalanan turun."
  },
  AvgDialog_145534_Content_28 = {
    Text = "Jadi, semasa hidupnya dia sudah mewujudkan keinginannya untuk mendaki puncak tertinggi."
  },
  AvgDialog_145534_Content_29 = {
    Text = "Meski terpisah oleh waktu, namun di sini, kita semua akan meninggal dalam kepenuhan."
  },
  AvgDialog_145534_Content_3 = {
    Text = "Peri Gunung Salju sejati, Dewa Cacing yang agung, aku telah membawa persembahan untukMu!"
  },
  AvgDialog_145534_Content_30 = {
    Text = "<Shake:Tidak, kamu sedang menipu dirimu sendiri… itu tidak benar, kamu tidak mungkin rela begitu saja…>"
  },
  AvgDialog_145534_Content_31 = {
    Text = "Nada suara Caraboo semakin melengking, air mata merembes dari sudut matanya."
  },
  AvgDialog_145534_Content_32 = {
    Text = "Evelyn Hanya Saja menatapnya dengan Tatapan penuh belas kasih."
  },
  AvgDialog_145534_Content_33 = {
    Text = "Salju terus turun."
  },
  AvgDialog_145534_Content_34 = {
    Text = "Setelah lama, Evelyn melangkah maju dan menepuk Salju yang jatuh di bahu Caraboo."
  },
  AvgDialog_145534_Content_35 = {
    Text = "Pikirkanlah baik-baik lagi. Aku akan pergi menemani suamiku."
  },
  AvgDialog_145534_Content_36 = {
    Text = "Setelah mengucapkan kata-kata itu, dia bersenandung pelan, melangkah satu per satu menuju bawah tebing."
  },
  AvgDialog_145534_Content_37 = {
    Text = "Tanpa tali pengaman, dia tidak takut jatuh. Celah es di dasar bebatuan itulah tujuannya."
  },
  AvgDialog_145534_Content_38 = {
    Text = "<Shake:Jangan pergi, Evelyn, jangan pergi——>"
  },
  AvgDialog_145534_Content_39 = {
    Text = "Yang menolaknya, bukanlah Evelyn."
  },
  AvgDialog_145534_Content_4 = {
    Text = "Dia diliputi kegembiraan, Dia tertawa terbahak-bahak. Dia merasa senang karena tipu dayanya berhasil."
  },
  AvgDialog_145534_Content_40 = {
    Text = "Yang menahannya, juga bukan seseorang selain Evelyn."
  },
  AvgDialog_145534_Content_41 = {
    Text = "Kenapa……"
  },
  AvgDialog_145534_Content_42 = {
    Text = "Mengapa… gunung ini Guncangan?…"
  },
  AvgDialog_145534_Content_44 = {
    Text = "Di dalam gunung berdiam sesuatu yang paling horor."
  },
  AvgDialog_145534_Content_45 = {
    Text = "Ia membentang ribuan li, bercokol di satu wilayah. Ia rakus memangsa hati manusia, menelan hasrat yang sia-sia."
  },
  AvgDialog_145534_Content_46 = {
    Text = "Kini, Dia datang untuk menangkap mangsanya."
  },
  AvgDialog_145534_Content_47 = {
    Text = "<Change>Keinginan… keinginan… keinginan yang kuat…"
  },
  AvgDialog_145534_Content_48 = {
    Text = "Tidak! Aku sudah menipu mereka semua untukmu, kamu sudah berjanji tidak akan memakanku!"
  },
  AvgDialog_145534_Content_49 = {
    Text = "<Change>Siapa yang akan mematuhi… perjanjian… si penipu…"
  },
  AvgDialog_145534_Content_5 = {
    Text = "Wahai manusia yang serakah, wahai manusia yang bodoh."
  },
  AvgDialog_145534_Content_50 = {
    Text = "Cacing di atas Apel itu pun mengangkat suaranya, tertawa nyaring."
  },
  AvgDialog_145534_Content_51 = {
    Text = "Lagipula, bukankah sejak awal kamu sudah tahu bahwa salah satu Korban-nya adalah \"Apel Emas\"?"
  },
  AvgDialog_145534_Content_52 = {
    Text = "Tidak, aku adalah dewi gunung salju, Apel Emas adalah senjata suci milikku, aku tidak mungkin menjadi Korban!"
  },
  AvgDialog_145534_Content_53 = {
    Text = "Apakah kamu lupa siapa dirimu? Biarkan aku mengingatkanmu, Caraboo, kamu bukan siapa-siapa."
  },
  AvgDialog_145534_Content_54 = {
    Text = [[
Kamu bukan dewi, bukan putri, bukan peri.
Kamu hanyalah puing-puing yang lahir dari medan perang, seorang pengungsi yang bahkan telah melupakan wajah orang tuanya sendiri.]]
  },
  AvgDialog_145534_Content_55 = {
    Text = "Kamu seharusnya sudah tahu sejak lama… Identitas-identitas yang kamu karang sendiri, kehormatan-kehormatan yang kamu raih melalui penipuan… suatu hari nanti semuanya akan kembali kepadamu dengan keras, berlipat ganda."
  },
  AvgDialog_145534_Content_56 = {
    Text = "Hari ini, saatnya tiba."
  },
  AvgDialog_145534_Content_57 = {
    Text = "Gunung itu membuka mulutnya yang menganga lebar penuh Darah."
  },
  AvgDialog_145534_Content_58 = {
    Text = "<Change>Masuklah… ke dalam perutku… jadilah… Kekuatanku…"
  },
  AvgDialog_145534_Content_6 = {
    Text = "Serahkan keinginan kalian kepada gunung, serahkan hasrat kalian kepada gunung."
  },
  AvgDialog_145534_Content_60 = {
    Text = "Lereng yang landai tiba-tiba menjadi curam, dan Evelyn yang hanya berjarak beberapa puluh meter dari celah es membuang semua beban yang memberatinya."
  },
  AvgDialog_145534_Content_61 = {
    Text = "Dia melepas pengait tabung oksigen, menanggalkan sepatu crampon yang berat, lalu tanpa ragu memotong satu-satunya tali utama yang mengikat tubuhnya."
  },
  AvgDialog_145534_Content_62 = {
    Text = "Tidak ada lagi yang bisa menahannya."
  },
  AvgDialog_145534_Content_63 = {
    Text = "Dia Hanya dengan ringan, Hampir dengan gembira, menerjang ke arah kekasihnya yang tertidur di celah es."
  },
  AvgDialog_145534_Content_64 = {
    Text = "Sayangku, aku datang menjemputmu."
  },
  AvgDialog_145534_Content_65 = {
    Text = "Di tengah guncangan yang baru, Evelyn dengan lembut memeluk tulang belulang kekasihnya."
  },
  AvgDialog_145534_Content_66 = {
    Text = "Dalam Bidang pandang yang jatuh, gunung bersalju membuka mulutnya yang sangat besar, menelan sosok kecil yang bagaikan kue krim ceri itu."
  },
  AvgDialog_145534_Content_67 = {
    Text = "Ditelan ke dalam perut pegunungan."
  },
  AvgDialog_145534_Content_7 = {
    Text = "<BigShake:Gunung akan mendengarkan kalian, lalu \"merespons\" kalian!>"
  },
  AvgDialog_145534_Content_8 = {
    Text = "Seketika, tubuh gunung tiba-tiba bergerak Surge dari dasarnya — Salju putih yang menumpuk berjatuhan berguguran, tubuh berbuku-buku itu menggeliat dan melilit, terangkat ruas demi ruas bagai gletser yang runtuh."
  },
  AvgDialog_145534_Content_9 = {
    Text = "Seluruh \"gunung\" itu berdiri tegak dengan gemuruh, membungkuk mendekat, setiap inci gerakannya menghancurkan Lapangan Salju di bawahnya menjadi serpihan debu."
  },
  AvgDialog_145535_Content_1 = {Text = "Tamu Pesta"},
  AvgDialog_145535_Content_10 = {
    Text = "Menipu? Memangnya kenapa, siapa yang tidak menipu?"
  },
  AvgDialog_145535_Content_11 = {
    Text = "%player%, kamu juga bisa merasakannya, bukan? Bau kebohongan."
  },
  AvgDialog_145535_Content_12 = {
    Text = "<Yellow:Untungnya aku berhasil bersembunyi dengan baik dan lolos dari pengejaran mereka.>"
  },
  AvgDialog_145535_Content_13 = {
    Text = "<Yellow:<Big:Tidak……! Aku tidak lelah! Aku tidak akan mundur!>>"
  },
  AvgDialog_145535_Content_14 = {
    Text = "<Yellow:Misi lainku di dunia ini telah berakhir untuk sementara.>"
  },
  AvgDialog_145535_Content_15 = {
    Text = "Tinct jelas sudah tidak bisa bertahan melewati malam itu, tapi dia memilih untuk menyembunyikan kondisi penyakitnya, bukankah dia juga seorang penipu?"
  },
  AvgDialog_145535_Content_16 = {
    Text = "Castor, sejak pertama kali bertemu dengan kami, dia menyembunyikan fakta bahwa dia menanggung Sayap, bukankah dia juga seorang penipu?"
  },
  AvgDialog_145535_Content_17 = {
    Text = "William jelas menyembunyikan suatu keinginan, namun tidak mau memberitahu semua orang. Bukankah dia seorang pembohong?"
  },
  AvgDialog_145535_Content_18 = {
    Text = "Semua orang menipu, semua orang adalah penipu, mengapa hanya aku yang mendapat penuduhan?"
  },
  AvgDialog_145535_Content_19 = {
    Text = "Namun Tinct menyembunyikan kondisi kesehatannya hanya demi melangkah lebih jauh, sayap Castor dan keinginan William memang sudah menjadi urusan pribadi mereka."
  },
  AvgDialog_145535_Content_2 = {
    Text = "Sebenarnya, siapa kamu?"
  },
  AvgDialog_145535_Content_20 = {
    Text = "Mereka tidak mengungkapkan kebenaran, tapi mereka juga tidak berniat menyakiti siapa pun."
  },
  AvgDialog_145535_Content_21 = {
    Text = "Mengapa kamu masih tidak mengerti, manusia itu, hidup di dunia ini, hal yang diinginkan, entah itu Kekuatan, entah itu keinginan, bagaikan Apel ini —"
  },
  AvgDialog_145535_Content_22 = {
    Text = "Semua orang menginginkannya, semua orang berjuang keras mencarinya…"
  },
  AvgDialog_145535_Content_23 = {
    Text = "Caraboo melempar Apel sembarangan ke kejauhan, berpura-pura mengejarnya, lalu dengan dramatis berdebam jatuh ke tumpukan salju."
  },
  AvgDialog_145535_Content_24 = {Text = "Namun, ..."},
  AvgDialog_145535_Content_25 = {
    Text = "Selamanya, selamanya, hanya segelintir orang yang bisa mendapatkannya."
  },
  AvgDialog_145535_Content_26 = {
    Text = "Dan aku, ingin menjadi pemiliknya yang abadi, satu-satunya."
  },
  AvgDialog_145535_Content_27 = {
    Text = "Namun cara yang kamu gunakan untuk mencapai tujuan itu adalah Kebohongan."
  },
  AvgDialog_145535_Content_28 = {
    Text = "Benar, apakah Kebohongan tidak cukup?"
  },
  AvgDialog_145535_Content_29 = {
    Text = "Yang menarik kalian kemari bukanlah hal-hal agung atau megah seperti nasib atau raja dewa, Hanya Saja Kebohongan, hanya sebuah kebohongan belaka!"
  },
  AvgDialog_145535_Content_3 = {
    Text = "Caraboo tertawa kecil."
  },
  AvgDialog_145535_Content_30 = {
    Text = "Kalian mempersembahkan Dedikasi kepada gunung, dan gunung memenuhi keinginan kalian sesuai suasana hatinya. Ini tidak berbeda dengan Dewa di dunia manusia."
  },
  AvgDialog_145535_Content_31 = {
    Text = "Hanya saja kali ini, yang diminta gunung dari kalian adalah <Red:\"segalanya\">."
  },
  AvgDialog_145535_Content_32 = {
    Text = "Jangan harap berhasil…!"
  },
  AvgDialog_145535_Content_4 = {
    Text = "Sebenarnya, siapa aku?"
  },
  AvgDialog_145535_Content_5 = {
    Text = "Bukankah dari awal aku sudah memberitahu kalian? Aku adalah dewi gunung salju, peri pelindung, perwujudan kehendak gunung salju."
  },
  AvgDialog_145535_Content_6 = {
    Text = "Ini adalah Pemandu paling penting, paling menggemaskan, Caraboo, yang sekarang akan memberikan kalian sebagai santapan bagi-Nya."
  },
  AvgDialog_145535_Content_7 = {
    Text = "Caraboo… kamu telah menipu kami."
  },
  AvgDialog_145535_Content_8 = {
    Text = "Menipu Evelyn yang telah merawatmu sepanjang perjalanan, menipu %player% yang memperjuangkan kesempatanmu untuk tetap tinggal di tengah perdebatan."
  },
  AvgDialog_145535_Content_9 = {
    Text = "Apakah ini hasil yang kamu kejar?"
  },
  AvgDialog_145862_Content_1 = {Text = "Caraboo…"},
  AvgDialog_145862_Content_2 = {
    Text = "Apa yang kamu katakan tadi… apakah itu benar?"
  },
  AvgDialog_145862_Content_3 = {Text = "Menurutmu?"},
  AvgDialog_145862_Content_4 = {
    Text = "Saya tidak tahu..."
  },
  AvgDialog_145862_Content_5 = {
    Text = "Kalau begitu jangan dipikirkan. Hati-hati, ada musuh yang datang dari sana!"
  },
  AvgDialog_146405_Content_1 = {
    Text = "Minggir, biarkan aku pergi mencarinya!"
  },
  AvgDialog_146405_Content_2 = {
    Text = "Pollux memanggilku!"
  },
  AvgDialog_146516_Content_1 = {
    Text = "Sialan, apakah Pustula-pustula ini tidak bisa dibekukan?"
  },
  AvgDialog_146516_Content_10 = {
    Text = "Sebelum ini, tak seorang pun memedulikan harta benda yang disebut Caraboo."
  },
  AvgDialog_146516_Content_11 = {
    Text = "Bagaimanapun, tidak ada satu pun legenda yang mengandung unsur seperti ini."
  },
  AvgDialog_146516_Content_12 = {
    Text = "Mereka hanya bilang begitu kamu mencapai puncak, keinginanmu akan terwujud."
  },
  AvgDialog_146516_Content_13 = {Text = "Beres."},
  AvgDialog_146516_Content_14 = {
    Text = "Maka, ketika bola rantai Helot menyapu semua orang dan mengait bawaan masing-masing, tak seorang pun dari kalian yang menduganya."
  },
  AvgDialog_146516_Content_15 = {
    Text = "Hanya cokelat koin emas yang berkilauan tak terhitung jumlahnya, beterbangan dari celah-celah tas, berhamburan di sepanjang tebing."
  },
  AvgDialog_146516_Content_16 = {
    Text = "Bagai hujan emas yang gemilang."
  },
  AvgDialog_146516_Content_17 = {
    Text = "<Shake:Tinct… Castor…>"
  },
  AvgDialog_146516_Content_18 = {
    Text = [[
Kamu tidak tahu apa yang telah kamu kehilangan.
Namun kalian pasti telah kehilangan sesuatu, sesuatu yang sangat penting.]]
  },
  AvgDialog_146516_Content_19 = {
    Text = "Jangan menyerah! Dia masih akan menuju altar di puncak gunung!"
  },
  AvgDialog_146516_Content_2 = {
    Text = "Hmph, mereka adalah anak-anak yang tumbuh besar di tengah salju sejak kecil."
  },
  AvgDialog_146516_Content_20 = {
    Text = "Sebelum ritual berakhir, masih ada kesempatan!"
  },
  AvgDialog_146516_Content_21 = {
    Text = "Caraboo yang pertama kali membangkitkan semangat dan mulai memanjat, tak lupa menundukkan kepala untuk memanggil kalian."
  },
  AvgDialog_146516_Content_22 = {
    Text = "Entah mengapa, kamu melihat semacam kegembiraan yang tak jelas asalnya di matanya."
  },
  AvgDialog_146516_Content_23 = {
    Text = "Ikuti kata-kata Caraboo."
  },
  AvgDialog_146516_Content_24 = {
    Text = "Dan Helot: Catena… sampai jumpa di puncak."
  },
  AvgDialog_146516_Content_25 = {
    Text = "Di kejauhan, siluet puncak gunung bersalju tampak samar-samar di antara lapisan awan."
  },
  AvgDialog_146516_Content_26 = {
    Text = "-Ketinggian 7950 meter-"
  },
  AvgDialog_146516_Content_3 = {
    Text = "Bola rantai melayang di udara, kamu dan William melindungi Evelyn dan Naraka, kewalahan menghadapi serangan dari segala penjuru."
  },
  AvgDialog_146516_Content_4 = {
    Text = "Caraboo entah bersembunyi di balik tumpukan salju yang mana, salju putih bersih menutupi sosoknya."
  },
  AvgDialog_146516_Content_5 = {
    Text = "Kalian tidak merasa aneh? Dia sudah mengikuti kita sejak mulai mendaki gunung."
  },
  AvgDialog_146516_Content_6 = {
    Text = "Mengapa baru sekarang tiba-tiba melancarkan serangan?"
  },
  AvgDialog_146516_Content_7 = {
    Text = "<Shake:Jika, tujuannya bukan untuk membunuh kita, melainkan——>"
  },
  AvgDialog_146516_Content_8 = {
    Text = "Sudah terlambat. Rantai yang berputar memisahkan semua orang, dan membuat kalian tak sempat memperhatikan beban bawaan yang berat."
  },
  AvgDialog_146516_Content_9 = {
    Text = "<Big:——Harta benda di tangan kita!>"
  },
  AvgDialog_147080_Content_1 = {
    Text = "……………"
  },
  AvgDialog_147080_Content_10 = {
    Text = "Baik baik baik, aku tahu. Tapi tidak bisa kuberitahu kalian."
  },
  AvgDialog_147080_Content_100 = {
    Text = "Theseus keluar dari labirin dengan bantuan gulungan benang Ariadne, namun cinta mereka tidak mendapat Blessing dari dewi nasib…"
  },
  AvgDialog_147080_Content_101 = {
    Text = "Pada akhirnya, dewa anggur Dionysus menghadiahkan sebuah mahkota indah yang dihiasi tujuh permata berkilau kepada Ariadne."
  },
  AvgDialog_147080_Content_102 = {
    Text = "William melirik Caraboo sekilas."
  },
  AvgDialog_147080_Content_103 = {
    Text = "Meskipun telah bersama sepanjang perjalanan, menghadapi kesulitan bersama, namun Theseus dan Ariadne mungkin memang ditakdirkan bukan untuk berjalan di jalan yang sama."
  },
  AvgDialog_147080_Content_104 = {
    Text = "Caraboo mengalihkan pandangannya dari William."
  },
  AvgDialog_147080_Content_105 = {
    Text = "Menukar sebuah Cangkang kosong yang telah menyelesaikan tugasnya dengan sebuah keinginan yang mampu Tulis Ulang nasib, tidakkah kamu merasa rugi?"
  },
  AvgDialog_147080_Content_106 = {
    Text = "Tujuan kami mendaki gunung ini memang untuk menemukan pemilik Mahkota melalui Mahkota ini."
  },
  AvgDialog_147080_Content_107 = {
    Text = "Kamu bisa langsung membaca kesadaran Caraboo, sementara dia bisa mengamati apakah kami sedang berbohong."
  },
  AvgDialog_147080_Content_108 = {
    Text = "Jadi, kamu bisa memastikan bahwa apa yang aku katakan sekarang adalah kebenaran, bukan?"
  },
  AvgDialog_147080_Content_109 = {
    Text = "<Yellow:Kartu truf-ku, adalah memperlihatkan kartu truf itu sendiri>."
  },
  AvgDialog_147080_Content_11 = {
    Text = "Kamu membalasnya dengan tatapan penuh amarah."
  },
  AvgDialog_147080_Content_111 = {
    Text = "<Shake:Haha, hahaha! >Tepat sekali, bahkan bisa memanfaatkan mekanisme ini secara terbalik, berbisnis dengan orang cerdas memang mudah."
  },
  AvgDialog_147080_Content_112 = {
    Text = "<Big:Bersiaplah untuk mendapatkan kebebasanmu kembali!>"
  },
  AvgDialog_147080_Content_113 = {
    Text = "<Shake:Hitung mundur, tiga, dua, satu—>"
  },
  AvgDialog_147080_Content_114 = {Text = "—Nol."},
  AvgDialog_147080_Content_115 = {
    Text = "Dinding Caro dari segala penjuru menekan kalian secara bersamaan, lendir yang merembes dari lipatan-lipatannya berubah menjadi ratusan tentakel panjang dan ramping, membelit pergelangan tangan, pergelangan kaki, dan pinggang."
  },
  AvgDialog_147080_Content_116 = {
    Text = "Tunggu, bukankah ini sedikit berbeda dari kebebasan yang dijanjikan—"
  },
  AvgDialog_147080_Content_117 = {
    Text = "Aku hanya berjanji mengantarkan kalian keluar, apakah aku pernah berjanji membuat perjalanan kalian nyaman dan menyenangkan?"
  },
  AvgDialog_147080_Content_118 = {
    Text = "Sebuah kekuatan yang tak tertahankan mengalir dari bawah kaki."
  },
  AvgDialog_147080_Content_119 = {
    Text = "Kalian seperti benda asing yang ditelan lalu didorong keluar melalui kerongkongan, naik dengan cepat di dalam lorong Caro yang sempit dan licin."
  },
  AvgDialog_147080_Content_12 = {
    Text = "Jangan marah, jangan marah, aku akan mulai menjelaskan sekarang."
  },
  AvgDialog_147080_Content_120 = {
    Text = "Bidang pandang ditelan kegelapan. Di telinga hanya tersisa suara lengket gesekan Caro, serta detak jantung seluruh gunung yang berat dan panjang."
  },
  AvgDialog_147080_Content_121 = {Text = "Dong."},
  AvgDialog_147080_Content_122 = {Text = "Dong."},
  AvgDialog_147080_Content_123 = {
    Text = "<Red:Dug—>"
  },
  AvgDialog_147080_Content_124 = {
    Text = "Saat detak jantung terakhir berhenti, di depan terbelah seberkas cahaya putih yang menyilaukan."
  },
  AvgDialog_147080_Content_125 = {
    Text = "Angin kencang membawa salju menerpa wajah."
  },
  AvgDialog_147080_Content_126 = {
    Text = "Kalian dilempar keluar dengan keras oleh kekuatan itu, terjatuh berat ke dalam salju yang dalamnya setinggi lutut."
  },
  AvgDialog_147080_Content_127 = {
    Text = "Batuk… makhluk ini pasti sedang membalas dendam."
  },
  AvgDialog_147080_Content_128 = {
    Text = "Setidaknya Dia tidak memungut biaya kebersihan saat check-out. Menurut standar keramahan-Nya, itu sudah bisa dibilang murah hati."
  },
  AvgDialog_147080_Content_129 = {
    Text = "Kamu bertumpu pada salju dan berdiri. Bau amis Darah yang tak kunjung hilang di dalam dada, akhirnya tersapu oleh angin dingin yang menusuk."
  },
  AvgDialog_147080_Content_13 = {
    Text = "Untuk membahas cara keluar dari sini, pertama-tama kita perlu tahu, di mana ini, dan mengapa kita bisa berada di sini."
  },
  AvgDialog_147080_Content_130 = {
    Text = "Tempat ini sudah bukan lagi punggung gunung saat kalian datang."
  },
  AvgDialog_147080_Content_131 = {
    Text = "Memandang ke sekeliling, semua puncak yang lebih rendah tenggelam di bawah lautan awan. Langit hitam pekat terasa begitu dekat seolah-olah bisa dijangkau dengan tangan, sementara Bintang-bintang berkedip-kedip di balik tirai Salju yang diterbangkan Angin kencang."
  },
  AvgDialog_147080_Content_132 = {
    Text = "Kalian sedang berdiri di atas puncak tertinggi dari seluruh pegunungan ini."
  },
  AvgDialog_147080_Content_133 = {
    Text = "Di sini adalah..."
  },
  AvgDialog_147080_Content_134 = {
    Text = "Puncak sejati."
  },
  AvgDialog_147080_Content_135 = {
    Text = "Suara itu datang dari bawah tumpukan salju."
  },
  AvgDialog_147080_Content_136 = {
    Text = "Lapisan es pun sedikit bergetar, seolah-olah puncak bersalju ini hanyalah sepotong tulang yang mencuat keluar dari tubuh suatu makhluk raksasa."
  },
  AvgDialog_147080_Content_137 = {
    Text = "Ritual permohonan kepada Dewi Gunung Salju ada di depan. Kembalikan ketujuh artefak ke tempat yang semestinya beserta persembahan. Untuk penafsiran selanjutnya, bergantung pada si rambut kuning tadi."
  },
  AvgDialog_147080_Content_138 = {
    Text = "Kamu tidak ikut bersama kami?"
  },
  AvgDialog_147080_Content_139 = {
    Text = "Aku ada di mana-mana."
  },
  AvgDialog_147080_Content_14 = {
    Text = "Di sinilah perut Cacing Gunung, dan alasan Cacing Gunung menipu kalian ke sini dengan Dewi Salju dan ritual permohonan…"
  },
  AvgDialog_147080_Content_140 = {
    Text = "Sebuah tawa rendah bergema dari bawah kaki."
  },
  AvgDialog_147080_Content_141 = {
    Text = "Seluruh gunung ini adalah cangkang tubuhku. Setiap langkah yang kalian ambil, kalian berjalan di atas Caro-ku."
  },
  AvgDialog_147080_Content_142 = {
    Text = "Maka, jangan pernah berdelusi untuk memainkan trik konyol apa pun."
  },
  AvgDialog_147080_Content_143 = {
    Text = "Melangkahlah ke depan. Biarkan aku melihat, kalian yang menanggung begitu banyak permohonan ini, pada akhirnya akan membukakan Pintu seperti apa untukku."
  },
  AvgDialog_147080_Content_144 = {
    Text = "Salju di hadapan kalian perlahan-lahan terbelah."
  },
  AvgDialog_147080_Content_145 = {
    Text = "Anak tangga batu kuno yang telah terkubur oleh Angin dan Salju entah berapa tahun lamanya pun terungkap, berkelok-kelok menuju puncak."
  },
  AvgDialog_147080_Content_146 = {
    Text = "Dan di ujung anak tangga itu, tujuh cahaya emas yang redup menyala satu per satu, bagaikan Mata yang telah tertidur selama seribu tahun, akhirnya Menunggu kedatangan orang yang akan Awaken mereka."
  },
  AvgDialog_147080_Content_147 = {
    Text = "William melangkah lebih dulu menaiki anak tangga batu."
  },
  AvgDialog_147080_Content_148 = {
    Text = "Tangannya terus menempel di bagian dalam jaketnya — seolah-olah sedang menenangkan sebuah permohonan yang telah ia relakan."
  },
  AvgDialog_147080_Content_149 = {
    Text = "Saat itu, tak ada seorang pun yang memperhatikan bahwa Kunci yang telah Hening selama bertahun-tahun itu sedang bergetar sangat halus, menembus lapisan kain."
  },
  AvgDialog_147080_Content_15 = {
    Text = "Untuk Devour kekuatan kalian."
  },
  AvgDialog_147080_Content_150 = {
    Text = "Seolah-olah ada sesuatu, yang sedang Menunggu di puncak gunung."
  },
  AvgDialog_147080_Content_16 = {
    Text = "Penjelasan yang ringkas dan mudah dipahami."
  },
  AvgDialog_147080_Content_17 = {
    Text = "Kalau begitu, kekuatan para pendaki lainnya..."
  },
  AvgDialog_147080_Content_18 = {
    Text = "Semuanya ada di dalam beberapa Korban ini."
  },
  AvgDialog_147080_Content_19 = {
    Text = "Mekanisme kerja sama antara Caraboo dan Cacing Gunung adalah, Dia menyaring Korban yang memiliki keinginan kuat dan spiritualitas, lalu menggoda mereka untuk memasuki pegunungan."
  },
  AvgDialog_147080_Content_2 = {
    Text = "Jadi, Tuan yang terhormat, kesenangan apa yang mendorong Anda untuk berperan sebagai pemandu pendakian Sherpa? Masa karena kecintaan pada olahraga ekstrem manusia?"
  },
  AvgDialog_147080_Content_20 = {
    Text = "Pertanyaannya, mengapa Cacing Gunung secara aktif memutus kerja sama ini?"
  },
  AvgDialog_147080_Content_21 = {
    Text = "Karena ia tahu, aku mulai Guncangan."
  },
  AvgDialog_147080_Content_22 = {
    Text = "Caraboo mengangkat kembali percakapan terakhir di punggung gunung itu."
  },
  AvgDialog_147080_Content_23 = {
    Text = "Dulu aku mengira, tidak ada orang yang bisa Menahan Keserakahan, ingin mewujudkan keinginan, Hanya bisa bergantung pada \"hal bukan manusia\". Tapi dia membuatku mengerti, menerima kebiasaan pun bisa mendapatkan kebahagiaan."
  },
  AvgDialog_147080_Content_24 = {
    Text = "Pada momen itu, aku memunculkan \"keinginan\" yang tidak perlu."
  },
  AvgDialog_147080_Content_25 = {
    Text = "\"Keinginan\" adalah umpan, adalah sumbu."
  },
  AvgDialog_147080_Content_26 = {
    Text = "Sejak awal, akulah \"Apel Emas\" yang ditakdirkan untuk Ditelan."
  },
  AvgDialog_147080_Content_27 = {
    Text = "Bagaimana kami bisa memastikan kamu tidak sedang menipu kami lagi?"
  },
  AvgDialog_147080_Content_28 = {
    Text = "Terserah kamu percaya atau tidak. Sekarang, akulah yang paling membenci Cacing Gunung di antara kalian semua."
  },
  AvgDialog_147080_Content_29 = {
    Text = "Kalau bukan karena malam bersalju itu, ketika Cacing Gunung menipuku dan aku membuat Kontrak dengannya… aku tidak akan menempuh jalan yang ada hari ini."
  },
  AvgDialog_147080_Content_3 = {
    Text = "Kalau aku bilang demi menyuarakan nasib orang-orang Sherpa, kamu akan percaya?"
  },
  AvgDialog_147080_Content_30 = {
    Text = "<Small:Penipu sialan>."
  },
  AvgDialog_147080_Content_31 = {
    Text = "Dalam Keheningan yang singkat, hanya ada suara napas menjijikkan dari dinding Caro yang naik turun."
  },
  AvgDialog_147080_Content_32 = {
    Text = "Mengerti. Asalkan kamu tidak bertindak keterlaluan, kami tidak akan mempermasalahkan urusan masa lalu untuk sementara ini."
  },
  AvgDialog_147080_Content_33 = {
    Text = "Yang lebih mendesak sekarang adalah menemukan cara untuk keluar dari perut Dewa ini… sebaiknya tanpa meminjam Kekuatan Tuan N."
  },
  AvgDialog_147080_Content_34 = {
    Text = "Aduh, kalian begitu menyia-nyiakan kebaikan hati Tuan N yang tampan dan baik itu?"
  },
  AvgDialog_147080_Content_35 = {
    Text = "Atau kalian benar-benar mengira, keluar dari perut-Nya semudah meninggalkan kamar hotel yang tidak memuaskan?"
  },
  AvgDialog_147080_Content_36 = {
    Text = "Kamu bilang kamu tidak bisa memberitahu kami."
  },
  AvgDialog_147080_Content_37 = {
    Text = "Mengira aku sengaja menyembunyikannya dari kalian? Kalau begitu kamu sungguh menyalahkan aku."
  },
  AvgDialog_147080_Content_38 = {
    Text = "N memainkan setangkai mawar yang muncul begitu saja di antara jari-jarinya, dengan santai mengarahkan Tatapannya ke Caraboo."
  },
  AvgDialog_147080_Content_39 = {
    Text = "Apa pun cara yang kumiliki, tidak boleh kamu ketahui. Benar kan, penipu kecil?"
  },
  AvgDialog_147080_Content_4 = {
    Text = "Percaya, aku tidak hanya percaya itu, aku juga percaya bahwa Nyonya Sorel mendukung sikap tidak ikut campur, Ryker pensiun dari meja judi selamanya, Erica berjiwa mulia dan pandai berkata-kata…"
  },
  AvgDialog_147080_Content_40 = {
    Text = "Caraboo tidak membantah. Dia Hanya Saja menggigit bibir bawahnya kuat-kuat, menghindari pandangan semua orang."
  },
  AvgDialog_147080_Content_41 = {Text = "Caraboo?"},
  AvgDialog_147080_Content_42 = {
    Text = "…Dia bisa mendengarku."
  },
  AvgDialog_147080_Content_43 = {
    Text = "Ini bukan kiasan. Saat aku berusia enam tahun, ketika aku mengikutinya pergi di malam bersalju itu, aku telah menggadaikan jiwaku kepadanya."
  },
  AvgDialog_147080_Content_44 = {
    Text = "Ini adalah Kontrak antara aku dan dia. Dia meminjamkan kepadaku Kekuatan \"Kebohongan\", membuatku bisa menipu semua orang di dunia; dan sebagai gantinya —"
  },
  AvgDialog_147080_Content_45 = {
    Text = "Aku tidak bisa menyembunyikan satu pun pikiran dariku darinya."
  },
  AvgDialog_147080_Content_46 = {
    Text = "…Jadi, saat ini, setiap kata yang kita ucapkan —"
  },
  AvgDialog_147080_Content_47 = {
    Text = "Asalkan masuk ke telingaku, masuk ke otakku, dia akan mengetahui semuanya."
  },
  AvgDialog_147080_Content_48 = {
    Text = "Caro di sekeliling tiba-tiba menegang sesaat, lalu perlahan mengendur kembali. Seolah ada sesuatu yang sangat besar sedang bersembunyi di balik tirai, mendengarkan semua ini dengan penuh minat."
  },
  AvgDialog_147080_Content_49 = {
    Text = "Sekarang kalian mengerti?"
  },
  AvgDialog_147080_Content_5 = {
    Text = "Sekarang bukan waktunya untuk berdebat."
  },
  AvgDialog_147080_Content_50 = {
    Text = "Cara itu selalu ada. Tapi selama melewati telinga nona ini, sama saja seperti langsung memperlihatkan kartu as kepada lawan saat bermain poker."
  },
  AvgDialog_147080_Content_51 = {
    Text = "Saat kita mendiskusikan rencana, minta Caraboo untuk Menghindar sebentar?"
  },
  AvgDialog_147080_Content_52 = {
    Text = "Bahkan jika aku tidak mendengar rencana kalian, aku mungkin bisa merasakan kejanggalan saat pelaksanaannya."
  },
  AvgDialog_147080_Content_53 = {
    Text = "Aku tidak boleh melihat ekspresi kecilmu, gerak-gerik kecilmu. Kalau tidak, aku akan tahu kalimat mana yang berisi Kebohongan."
  },
  AvgDialog_147080_Content_54 = {
    Text = "Mungkin, kamu bisa tidak melihat?"
  },
  AvgDialog_147080_Content_55 = {
    Text = "Tidak, Kebohongan adalah semacam suasana yang mengalir… dan aku sudah terlalu lama terbenam di dalamnya."
  },
  AvgDialog_147080_Content_56 = {
    Text = "Terkadang meski tidak ada yang berbicara, aku bisa merasakan keberadaan Kebohongan dari udara yang membeku."
  },
  AvgDialog_147080_Content_57 = {
    Text = "Biarkan aku mencoba."
  },
  AvgDialog_147080_Content_58 = {
    Text = "Diiringi suara jentikan jari yang nyaring, asap hitam merayap ke kelopak mata Caraboo."
  },
  AvgDialog_147080_Content_59 = {
    Text = "Baiklah, Buka mata."
  },
  AvgDialog_147080_Content_6 = {
    Text = "Arachne yang membawa kita ke sini, pasti ada alasannya. Dan kamu, seharusnya adalah bagian dari nasib itu."
  },
  AvgDialog_147080_Content_60 = {
    Text = "Caraboo Buka mata. Semua yang ada di depannya diselimuti lapisan asap Distortion, bahkan suara pun menjadi samar dan jauh."
  },
  AvgDialog_147080_Content_61 = {
    Text = "Namun William tiba-tiba menundukkan Mata, buku jari menempel di dagu, seolah sedang melakukan Inference sebuah permainan catur yang hanya bisa dilihat olehnya."
  },
  AvgDialog_147080_Content_62 = {Text = "Berhenti."},
  AvgDialog_147080_Content_63 = {Text = "Hm?"},
  AvgDialog_147080_Content_64 = {
    Text = "Tidak perlu menutupi Mata-nya."
  },
  AvgDialog_147080_Content_65 = {
    Text = "Justru sebaliknya, mulai sekarang, kuharap Caraboo kamu berkonsentrasi penuh untuk membedakan kebenaran dan kepalsuan dari setiap kata-kataku."
  },
  AvgDialog_147080_Content_66 = {
    Text = "Dengarkan baik-baik, Caraboo — atau lebih tepatnya, Cacing Gunung di balik Caraboo. Aku ingin melakukan transaksi denganmu."
  },
  AvgDialog_147080_Content_67 = {
    Text = "Dinding Caro bergetar seolah mengejek."
  },
  AvgDialog_147080_Content_68 = {
    Text = "Lucu sekali, kalian ada di dalam perutku. Apa yang akan Kamu tawarkan untuk bernegosiasi denganku?"
  },
  AvgDialog_147080_Content_69 = {Text = "Keinginan."},
  AvgDialog_147080_Content_7 = {
    Text = "Kamu pasti tahu cara keluar dari sini, kan, N?"
  },
  AvgDialog_147080_Content_70 = {
    Text = "Sekeliling tiba-tiba menjadi sunyi."
  },
  AvgDialog_147080_Content_71 = {
    Text = "Formasi keinginan di puncak gunung <Yellow:bukan diciptakan olehmu>, melainkan sesuatu yang lebih kuno darimu, bukan?"
  },
  AvgDialog_147080_Content_73 = {
    Text = "Cacing Gunung terdiam sejenak, lalu mengeluarkan tawa kecil yang tidak menunjukkan pendapat."
  },
  AvgDialog_147080_Content_74 = {
    Text = "Menarik. Lanjutkan."
  },
  AvgDialog_147080_Content_75 = {
    Text = "Sebelum pendakian kali ini, legenda yang diceritakan Caraboo sedikit berbeda dari yang beredar di antara penduduk gunung. Singkatnya, penduduk gunung hanya tahu bahwa mencapai puncak bisa mewujudkan keinginan, mereka tidak tahu tentang keberadaan tujuh artefak."
  },
  AvgDialog_147080_Content_76 = {
    Text = "Ini masuk akal. Jika tujuannya hanya untuk memikat manusia mendaki gunung lalu Devour mereka, tidak perlu menciptakan legenda tentang tujuh artefak."
  },
  AvgDialog_147080_Content_77 = {
    Text = "Cukup beritahu semua orang bahwa mencapai puncak bisa mewujudkan keinginan."
  },
  AvgDialog_147080_Content_78 = {
    Text = "Semakin sulit, semakin sedikit penantang — prinsip dasar ini tidak mungkin kalian tidak mengerti, kecuali—"
  },
  AvgDialog_147080_Content_79 = {Text = "Kecuali—"},
  AvgDialog_147080_Content_8 = {
    Text = "Aku tahu… atau tidak tahu ya… aduh, ini benar-benar pertanyaan yang menarik."
  },
  AvgDialog_147080_Content_80 = {
    Text = "Cacing Gunung memperpanjang nada bicaranya dengan sinis."
  },
  AvgDialog_147080_Content_81 = {
    Text = "Kecuali ketujuh artefak itu benar-benar ada, dan ritual untuk mewujudkan keinginan itu pun nyata adanya."
  },
  AvgDialog_147080_Content_82 = {
    Text = [[
Dan kamu berdiam di sisi formasi itu bukan hanya untuk Devour para pendaki.
Kamu juga Menunggu kesempatan untuk mengaktifkan ritual tersebut.]]
  },
  AvgDialog_147080_Content_83 = {
    Text = "Dunia Caro berhenti bernapas."
  },
  AvgDialog_147080_Content_84 = {
    Text = "Jika kamu selalu menjaga ritual itu, mengapa tidak mengaktifkannya sendiri?"
  },
  AvgDialog_147080_Content_85 = {
    Text = "Manusia, pertanyaanmu terlalu banyak."
  },
  AvgDialog_147080_Content_86 = {
    Text = "Sepertinya pertanyaan yang tepat."
  },
  AvgDialog_147080_Content_87 = {
    Text = "Biarkan aku menebak."
  },
  AvgDialog_147080_Content_88 = {
    Text = "Di dalam formasi sihir terdapat inti yang tidak bisa kamu pecahkan, bukan? Jadi selama bertahun-tahun ini, kamu menumpuk korban demi korban, namun tetap tidak bisa membuka pintu terakhir itu."
  },
  AvgDialog_147080_Content_89 = {
    Text = "Dinding daging tiba-tiba menegang, hampir menghancurkan semua orang."
  },
  AvgDialog_147080_Content_9 = {
    Text = "Jangan bertele-tele, langsung saja."
  },
  AvgDialog_147080_Content_90 = {
    Text = "Aku tahu mengapa kamu tidak bisa memecahkannya. Tadi aku sempat melihat sekilas formasi sihir itu, rune yang terukir di atasnya mengandung tulisan Latin dan aksara kuno lainnya."
  },
  AvgDialog_147080_Content_91 = {
    Text = "Dan Eksekutor kecilmu ini… jika dihitung dari waktu dia meninggalkan Rumah, jelas dia belum pernah mendapat pendidikan akademis yang layak…"
  },
  AvgDialog_147080_Content_92 = {
    Text = "<Shake:Memangnya kenapa kalau tidak bisa baca!>"
  },
  AvgDialog_147080_Content_93 = {
    Text = "Waktunya terbatas, tadi aku belum sempat membacanya secara mendetail sebelum kamu menelanku ke sini. Tapi kutebak yang tercatat di atasnya sebagian besar adalah pengetahuan terkait pengaktifan formasi sihir."
  },
  AvgDialog_147080_Content_94 = {
    Text = "Dewi nasib telah memandu kami ke sini, tujuh artefak agung telah terkumpul, kamu seharusnya tahu, ini adalah kesempatan terdekatmu untuk mewujudkan keinginan."
  },
  AvgDialog_147080_Content_95 = {
    Text = "Dan kami, bersedia <Yellow:melepaskan kesempatan untuk membuat permohonan kepada gunung>."
  },
  AvgDialog_147080_Content_96 = {
    Text = "Cacing gunung itu jatuh dalam keheningan yang panjang. Ketika kalian mengira ia tidak akan merespons lagi, ia mengeluarkan suara dengkuran pelan."
  },
  AvgDialog_147080_Content_97 = {
    Text = "Melepaskan keinginan… sungguh pengorbanan yang luar biasa. Yang kamu inginkan seharusnya bukan sekadar aku melepaskan kalian keluar, bukan?"
  },
  AvgDialog_147080_Content_98 = {
    Text = "Setelah ritual selesai, artefak lainnya boleh menjadi milikmu, tapi kami harus membawa pergi <Blue:Mahkota Ariadne>."
  },
  AvgDialog_147080_Content_99 = {
    Text = "Mahkota Ariadne…"
  },
  AvgDialog_147095_Content_1 = {
    Text = "Di aula yang kosong, hanya langkahmu dan murphy yang bergema."
  },
  AvgDialog_149752_Content_1 = {
    Text = "Sarang Naga"
  },
  AvgDialog_149752_Content_10 = {
    Text = "Kau sudah tidak memiliki apa-apa, tak sanggup menanggung kelupaan sekali lagi."
  },
  AvgDialog_149752_Content_11 = {
    Text = "Api yang berkobar-kobar telah dipadamkan oleh hujan, kau melewati gerbang yang tak terjaga, menyaksikan kekacauan di mana-mana."
  },
  AvgDialog_149752_Content_12 = {
    Text = "Kastil berdiri dalam kebisuan, tong minyak kosong, karung goni yang robek, perisai yang hancur berkeping-keping, tombak yang patah, anak panah berjajar bagai ilalang yang merunduk ditiup angin, bau amis lumpur basah bercampur dengan aroma hangus yang tak kunjung hilang."
  },
  AvgDialog_149752_Content_13 = {
    Text = "Di sini pernah terjadi pertempuran, namun kini hanya tersisa bayangan."
  },
  AvgDialog_149752_Content_14 = {
    Text = "Bayangan menjalar bebas dalam kegelapan, memanjat tembok tinggi, merayap melewati celah benteng, menenggelamkan mayat-mayat yang bergelimpangan, mengeluarkan suara guk-guk. Kau berusaha tidak memikirkan apa artinya itu."
  },
  AvgDialog_149752_Content_15 = {
    Text = "Ikuti bayangan itu… cukup ikuti bayangan itu…"
  },
  AvgDialog_149752_Content_16 = {
    Text = "Heh, heh… to… tolong…"
  },
  AvgDialog_149752_Content_17 = {
    Text = "Rintihan kesakitan terdengar dari balik helm yang penyok, bayangan memeluknya erat bagai kekasih yang mesra, kau memberanikan diri untuk melangkah maju."
  },
  AvgDialog_149752_Content_18 = {
    Text = "Orang yang membawa bayangan itu, ke mana dia pergi?"
  },
  AvgDialog_149752_Content_19 = {
    Text = "<Shake:Ba… bayangan? Tidak, tidak, itu monster! Darah hitam… berongga… ksatria kematian… itu nyata, semuanya nyata!>"
  },
  AvgDialog_149752_Content_2 = {
    Text = "Apa itu janji? Sihir yang tidak akan menjadi nyata jika tidak dipercaya."
  },
  AvgDialog_149752_Content_20 = {
    Text = "<Shake:Lari… heh… cepat lari! Monster yang tak bisa mati… pembalasan… kehancuran… guk… guk guk guk…>"
  },
  AvgDialog_149752_Content_21 = {
    Text = "Suara kental mengalir dari tenggorokan monster itu, tubuhnya mengejang seperti ikan yang terdampar, namun lengannya perlahan terangkat, menjulur ke arah bungkusan di pelukanmu, lumpur lunak yang menggeliat merembes dari celah-celah baju zirahnya."
  },
  AvgDialog_149752_Content_22 = {
    Text = "Itu bayangan. Ia menginginkan piala suci."
  },
  AvgDialog_149752_Content_23 = {
    Text = "Tidak, tidak bisa, ini sesuatu yang penting, tidak bisa kuberikan padamu."
  },
  AvgDialog_149752_Content_24 = {
    Text = "Penolakan tidak berguna, bayangan mengalir turun dari tembok, dengan cepat berkerumun ke arahmu, kau tergesa-gesa memeluk erat bungkusan itu, berbalik dan berlari menuju bagian kastil yang lebih dalam."
  },
  AvgDialog_149752_Content_25 = {
    Text = "Menara gerbang, aula besar, kapel, tangga batu berputar memanjang ke bawah tanah, kastil ini adalah sarang naga yang berbahaya. Udara semakin dingin, napasmu dan langkah kakimu diperkuat berlapis-lapis oleh dinding batu, terdengar seperti orang lain."
  },
  AvgDialog_149752_Content_26 = {
    Text = "Api menyala di ujung tangga spiral, kau melihat sosok yang familiar."
  },
  AvgDialog_149752_Content_27 = {Text = "O——"},
  AvgDialog_149752_Content_28 = {
    Text = "Kau baru saja hendak memanggilnya dengan gembira, tiba-tiba menyadari bahwa di sini bukan hanya kalian berdua. Monster itu lebih dulu membuka suara."
  },
  AvgDialog_149752_Content_29 = {
    Text = "<Shake:Uhuk uhuk uhuk uhuk… Ogier…>"
  },
  AvgDialog_149752_Content_3 = {
    Text = "Apa itu perpisahan? Saat berikutnya setelah tiba."
  },
  AvgDialog_149752_Content_30 = {
    Text = "Bagaimana kau bisa berubah menjadi seperti ini?"
  },
  AvgDialog_149752_Content_31 = {
    Text = "Penampilanku… ?"
  },
  AvgDialog_149752_Content_32 = {
    Text = "Di atas meja tersaji anggur dan hidangan lezat, peralatan makan perak berkilau di bawah cahaya lilin. Andai bukan karena dingin menusuk yang merembes dari celah-celah batu, tata letak yang cermat ini hampir membuat orang lupa bahwa mereka berada di kedalaman bumi yang gelap."
  },
  AvgDialog_149752_Content_33 = {
    Text = "Sang tuan tanah yang kurus duduk sendirian di balik meja, mata cekung, tulang pipi menonjol, terkubur di balik tumpukan sutra tebal, bagaikan naga yang bersemayam di antara harta emas dan perak."
  },
  AvgDialog_149752_Content_34 = {
    Text = "Ksatriamu melangkah mendekatinya selangkah demi selangkah, bayangan panjang terseret di belakangnya. Mungkin dirinya sendiri pun adalah sebuah bayangan. Pakaiannya compang-camping, wajahnya menyeramkan, langkahnya tanpa suara."
  },
  AvgDialog_149752_Content_35 = {
    Text = "Ya, kalau tidak melihat dengan mata kepala sendiri, aku hampir tidak percaya… uhuk uhuk uhuk… ksatria termuda di Kadipaten, ternyata telah jatuh menjadi monster."
  },
  AvgDialog_149752_Content_36 = {
    Text = "Kadipaten… sudah hancur."
  },
  AvgDialog_149752_Content_37 = {
    Text = "Karena kau."
  },
  AvgDialog_149752_Content_38 = {
    Text = "Karena perang, karena wabah, karena keserakahan negara tetangga, karena kelemahan diri sendiri. Ada banyak alasan yang bisa menghancurkan sebuah kadipaten, aku hanyalah, uhuk uhuk, yang paling tidak berarti di antaranya."
  },
  AvgDialog_149752_Content_39 = {
    Text = "<Shake:Kau… mengkhianati Kadipaten… bersekongkol dengan musuh… menjual… rakyat…>"
  },
  AvgDialog_149752_Content_4 = {
    Text = "Apa itu kematian? Hari esok tanpa perpisahan."
  },
  AvgDialog_149752_Content_40 = {
    Text = "<Shake:Pengkhianat… harus mati.>"
  },
  AvgDialog_149752_Content_41 = {
    Text = "Ya, ya, seperti yang kau lihat, buah pahit itu telah menimpaku. Waktuku tidak banyak lagi, uhuk uhuk uhuk uhuk."
  },
  AvgDialog_149752_Content_42 = {
    Text = "Wabah tidak mengampuniku, Ogier. Kematian, ia tidak memandang bulu, menunggu dengan sabar di ujung jembatan yang lain, tak seorang pun bisa lolos… kecuali kau."
  },
  AvgDialog_149752_Content_43 = {
    Text = "Ceritakan padaku, perjanjian apa yang kau buat dengan iblis?"
  },
  AvgDialog_149752_Content_45 = {
    Text = "Harga dari menghindari kematian hanya akan lebih berat dari kematian itu sendiri. Ksatria Kematian… menjadi algojo-Nya, apakah itu keinginan yang kau ucapkan, atau hukuman yang kau terima?"
  },
  AvgDialog_149752_Content_46 = {
    Text = "Ogier, ksatria paling setia dan paling saleh di Kadipaten, hah, <Shake:uhuk uhuk uhuk uhuk uhuk…>"
  },
  AvgDialog_149752_Content_47 = {
    Text = "Aku adalah pengkhianat terkutuk, bukankah kamu juga demikian?"
  },
  AvgDialog_149752_Content_48 = {Text = "!!"},
  AvgDialog_149752_Content_49 = {
    Text = "Petir tak kasat mata menyambar ksatriamu, memakunya kuat-kuat di tempat. Bayangan-bayangan di kegelapan bergetar hebat, penuh kegembiraan atau kemarahan, mereka sudah tak sabar lagi."
  },
  AvgDialog_149752_Content_5 = {
    Text = "Apa itu keglupaan?"
  },
  AvgDialog_149752_Content_50 = {
    Text = "Aku mengkhianati sang Adipati, tapi kamu, kamu dan putrimu, kalian mengkhianati Tuhan."
  },
  AvgDialog_149752_Content_51 = {
    Text = "Kamu masih ingat… kamu masih berani menyebut…"
  },
  AvgDialog_149752_Content_52 = {
    Text = "<Red:Putri penyihir>, uhuk uhuk uhuk, betapa ironis, tipu muslihatnya akhirnya terbongkar, namun bahkan namanya pun tak ada lagi yang mengingatnya. Sudah lama aku katakan, serahkan dia, maka api perang bisa padam, dan kadipaten pun tak perlu hancur."
  },
  AvgDialog_149752_Content_53 = {
    Text = "Kamu tahu apa yang dia bawa, kamu sangat paham. Kutukan… perang dimulai karenanya, dan berakhir karenanya pula. Berkat dia, @3kadipaten menjadi tempat yang terlupakan."
  },
  AvgDialog_149752_Content_54 = {
    Text = "Diam! Kamu… tidak pantas… menyebut namanya!"
  },
  AvgDialog_149752_Content_55 = {
    Text = "Tombak tak berbentuk membelah meja panjang, cangkir dan piring berjatuhan ke lantai, perjamuan palsu itu hancur berkeping-keping, memperlihatkan wujud aslinya yang berantakan."
  },
  AvgDialog_149752_Content_56 = {
    Text = "Bayangan menjulurkan pseudopoda lengketnya, dengan rakus menelan segala sesuatu yang disentuhnya, rawa-rawa mengalir keluar dari kegelapan tanpa cahaya, dan dunia pun mulai tenggelam."
  },
  AvgDialog_149752_Content_57 = {
    Text = "Kematian… lalu dilupakan… seolah tidak pernah terjadi. Inilah nasib mereka yang mengkhianati Tuhan."
  },
  AvgDialog_149752_Content_58 = {
    Text = "Dialah yang membuatmu menjadi seperti ini… menyeret seluruh kadipaten ke dalam kehampaan, lalu meninggalkan sebuah boneka penuh kebencian, menyebarkan kematian nyata ke seluruh bumi. Menjalankan misi seperti itu, apakah kamu menyebutnya kesetiaan?"
  },
  AvgDialog_149752_Content_59 = {
    Text = "Ogier… sebenarnya untuk siapa kamu mengabdi?"
  },
  AvgDialog_149752_Content_60 = {
    Text = "<Shake:Tidak… tidak… Putri bukan… grrr… grrrrr…>"
  },
  AvgDialog_149752_Content_61 = {
    Text = "Ksatriamu memeluk kepalanya dengan kesakitan, bayangan mengalir keluar dari dadanya, dari telinganya, dari sudut matanya. Siksaan iblis yang tak pernah berhenti siang dan malam membuatnya lemah, ia sudah tak mampu mengeluarkan suara, bagaikan boneka tanah liat yang meleleh dalam air sungai yang hitam."
  },
  AvgDialog_149752_Content_62 = {
    Text = "Saat tak seorang pun di antara kalian memperhatikan, sang tuan memutar kursi rodanya, dan ternyata di dinding batu di belakangnya tersembunyi sebuah lubang pembunuh seukuran kepalan tangan. Bayangan hitam seperti ular berkelebat di depan mata, disertai suara benturan yang berat, tombak besi menembus dada ksatriamu."
  },
  AvgDialog_149752_Content_63 = {
    Text = "<Big:Ogier!!!>"
  },
  AvgDialog_149752_Content_64 = {
    Text = "<Shake:Uhuk uhuk uhuk uhuk…> Monster yang merangkak keluar dari kubur, sebaiknya segera kembali ke kubur."
  },
  AvgDialog_149752_Content_65 = {
    Text = "Kamu dan monster kecilmu, biarlah kalian dikubur bersama di sini."
  },
  AvgDialog_149752_Content_66 = {
    Text = "Beberapa pengawal bersenjata lengkap muncul dari lorong rahasia, perisai dan pedang berkilat dengan cahaya yang berbahaya, jebakan terakhir akhirnya terungkap."
  },
  AvgDialog_149752_Content_7 = {
    Text = "……………"
  },
  AvgDialog_149752_Content_8 = {
    Text = "<Red:Kutukan.>"
  },
  AvgDialog_149752_Content_9 = {
    Text = "Kutukan. Wabah. Hukuman. Kekosongan yang digerogoti ulat. Dasar sungai yang retak. Membusuk dalam keheningan. Terkikis. Tenggelam. Tatapan yang telah habis. Memudar dari sebuah kisah menjadi bayangan. Kematian terakhir."
  },
  AvgDialog_149753_Content_1 = {Text = "Piala Suci"},
  AvgDialog_149753_Content_10 = {
    Text = "Semua yang kulakukan bukanlah tindakan seorang ksatria, kamu sudah melihatnya sendiri."
  },
  AvgDialog_149753_Content_11 = {
    Text = "Kenapa? Ksatria memang seharusnya melawan monster, itu adalah tugasmu, dan kamu melakukannya dengan baik."
  },
  AvgDialog_149753_Content_12 = {
    Text = "Dan kamu sedang mencari sesuatu, bukan? Aku bisa melihatnya. Kamu mencari dari satu tempat ke tempat lain, sejak memasuki kota, sudah beberapa hari. Apakah monster itu juga merampas sesuatu milikmu?"
  },
  AvgDialog_149753_Content_14 = {
    Text = "Sudah tiba."
  },
  AvgDialog_149753_Content_15 = {
    Text = "Cahaya lilin kuning hangat yang menggoda memenuhi setiap sudut ruangan, pintu kayu ek memblokir angin dingin, bagi para pengembara tunawisma, gudang biara yang terbuka di malam hujan bahkan bisa menyelamatkan nyawa."
  },
  AvgDialog_149753_Content_16 = {
    Text = "Namun kamu tidak akan tertipu oleh ilusi ini, kamu mengingatnya. Mereka yang mondar-mandir membawa kandil itu, jubah hitam, liontin kuningan, algojo yang menyebut diri mereka gembala, mereka adalah monster di antara para monster."
  },
  AvgDialog_149753_Content_17 = {
    Text = "<Small:Kenapa kita harus ke sini… apakah yang kamu cari ada di sini?>"
  },
  AvgDialog_149753_Content_18 = {
    Text = "Tunggu di sini, jangan ikut."
  },
  AvgDialog_149753_Content_19 = {
    Text = "<Big:Apa?! Tidak! Tidak mau!>"
  },
  AvgDialog_149753_Content_2 = {
    Text = "<Shake:Aku tidak tahu, aku tidak tahu itu adalah — tidak, tidak tidak tidak, tolong, tolong ampuni — >"
  },
  AvgDialog_149753_Content_20 = {
    Text = "<Big:Aku tidak mau tinggal di sini, aku benar-benar tidak mau tinggal di sini! Aku mau pergi bersamamu!>"
  },
  AvgDialog_149753_Content_21 = {
    Text = "Ada apa? Nak, apakah kamu butuh bantuan?"
  },
  AvgDialog_149753_Content_22 = {
    Text = "Ya, tolong jaga dia, jangan biarkan dia kabur."
  },
  AvgDialog_149753_Content_23 = {
    Text = "Oh… sudah larut malam, hujan pula, mau buru-buru pergi ke mana? Tunggulah sampai matahari terbit, jangan tinggalkan adikmu sendirian."
  },
  AvgDialog_149753_Content_24 = {
    Text = "Aku akan datang menjemputnya setelah hari terang."
  },
  AvgDialog_149753_Content_25 = {
    Text = "Kalau kamu bersikeras, baiklah, baiklah. Kasihan sekali anak ini, basah kuyup seluruh tubuhnya, ke sini, ke sini, biar aku bantu lap mukamu."
  },
  AvgDialog_149753_Content_26 = {
    Text = "Kamu terjebak, tidak bisa bergerak, kain linen kering mengusap pipimu, kamu tidak tahu kapan kain itu akan menutup mulut dan hidungmu."
  },
  AvgDialog_149753_Content_27 = {
    Text = "Rasa takut menghimpit dadamu, kamu tidak bisa bernapas, hanya bisa berteriak."
  },
  AvgDialog_149753_Content_28 = {
    Text = "<Shake:Kembali! Kamu adalah ksatriaku, kamu harus melindungiku, jangan tinggalkan aku di sini — kamu sudah berjanji padaku!>"
  },
  AvgDialog_149753_Content_29 = {
    Text = "<Shake:Kumohon, aku tidak akan membuat masalah, biarkan aku ikut bersamamu!>!"
  },
  AvgDialog_149753_Content_3 = {Text = "Ah!!"},
  AvgDialog_149753_Content_30 = {
    Text = "Banyak mata yang tertarik keluar oleh teriakanmu yang memekakkan telinga, ada yang seperti kumbang, ada yang seperti kambing, ada yang seperti burung hantu."
  },
  AvgDialog_149753_Content_31 = {
    Text = "Mereka menatapmu lekat-lekat, seolah hanya kamu yang tidak memiliki mata."
  },
  AvgDialog_149753_Content_32 = {
    Text = "<SmallShake:Jangan… jangan pergi… kamu sudah berjanji…>"
  },
  AvgDialog_149753_Content_33 = {
    Text = "<SmallShake:Kumohon, jangan tinggalkan aku…>"
  },
  AvgDialog_149753_Content_34 = {
    Text = "Aku berubah pikiran, biarkan dia ikut bersamaku."
  },
  AvgDialog_149753_Content_35 = {
    Text = "Kamu mendongak tiba-tiba, ksatriamu entah kapan telah berbalik kembali, menghalangi seluruh pandangan para monster di belakangnya."
  },
  AvgDialog_149753_Content_36 = {
    Text = "Tapi ke mana kamu akan membawanya? Tidak banyak tempat berteduh dari hujan di dalam kota, dan juga tidak cocok untuk anak-anak masuk."
  },
  AvgDialog_149753_Content_37 = {
    Text = "Tempat yang ingin kutuju tidak ada di dalam kota."
  },
  AvgDialog_149753_Content_38 = {
    Text = "Di luar kota bahkan lebih tidak ada — ah! Jangan-jangan kamu ingin pergi ke manor itu?"
  },
  AvgDialog_149753_Content_39 = {
    Text = "Ada apa dengan manor itu?"
  },
  AvgDialog_149753_Content_4 = {
    Text = "Jeritan tertahan oleh hujan deras, mengalir bersama darah ke selokan di kaki tembok, membusuk bersama lumpur, kotoran kuda, dan daun sayuran, hingga akhirnya ditelan bulat-bulat oleh gang gelap itu."
  },
  AvgDialog_149753_Content_40 = {
    Text = "Di sana, di sana… aduh, kalian juga pengungsi bukan? Nak, jangan dekati tempat itu."
  },
  AvgDialog_149753_Content_41 = {
    Text = "Tuan itu, dulunya dia orang baik, tapi perang, wabah, bencana datang silih berganti seperti pasang surut air laut, dan manusia pun menjadi tidak lagi seperti manusia. Mereka semua bilang dia sudah gila. Orang-orang di kota semakin sedikit, mereka yang pergi meminta roti, tidak pernah kembali lagi."
  },
  AvgDialog_149753_Content_42 = {
    Text = "Semoga Tuhan mengampuni… mereka semua bilang dia diam-diam memakan manusia."
  },
  AvgDialog_149753_Content_43 = {
    Text = "Monster memakan manusia, kamu sudah tahu sejak lama, jadi tidak sedikit pun terkejut, juga tidak takut… setidaknya tidak setakut itu. Kamu punya ksatriamu."
  },
  AvgDialog_149753_Content_44 = {
    Text = "Ikuti aku dengan ketat, ada yang tidak beres di sini."
  },
  AvgDialog_149753_Content_45 = {
    Text = "Baik, baik."
  },
  AvgDialog_149753_Content_46 = {
    Text = "Manor yang luas itu kosong melompong, tidak ada penjaga, tidak ada pelayan, seolah sudah lama terbengkalai, di lorong panjang yang sempit hanya terdengar langkah kakimu yang sengaja diperlahan."
  },
  AvgDialog_149753_Content_47 = {
    Text = "Jadi… sebenarnya kamu sedang mencari apa? Apakah itu penting bagimu? Ceritakan padaku seperti apa bentuknya, aku juga bisa membantumu mencari."
  },
  AvgDialog_149753_Content_48 = {
    Text = "Sebuah piala emas."
  },
  AvgDialog_149753_Content_49 = {
    Text = "Piala emas? Maksudnya terbuat dari emas? Wah, seberapa besar dan tingginya? Dipakai untuk apa? Seperti apa emas itu, apakah seperti bulan, bersinar di malam hari?"
  },
  AvgDialog_149753_Content_5 = {
    Text = "Tubuh itu jatuh lunglai ke tanah, kilatan dingin logam berpendar sesaat lalu lenyap, sang pembunuh menarik jubahnya rapat-rapat dan melangkah cepat keluar, suara langkah kakinya pun menghilang di tengah hujan."
  },
  AvgDialog_149753_Content_50 = {
    Text = "...Aku tidak tahu."
  },
  AvgDialog_149753_Content_51 = {
    Text = "Eh? Bukan milikmu?"
  },
  AvgDialog_149753_Content_52 = {
    Text = "Bukan, tapi sangat penting bagiku."
  },
  AvgDialog_149753_Content_53 = {
    Text = "Oh! Aku mengerti, itu Piala Suci kan? Aku pernah mendengarnya dalam cerita, sebuah harta bermagis, hanya ksatria yang lulus ujian yang bisa mendapatkannya, pantas saja kamu mencarinya begitu lama."
  },
  AvgDialog_149753_Content_54 = {
    Text = "Ehm ehm, sebagai putrimu, jika kamu bisa mendapatkan Piala Suci itu, itu juga menguntungkanku, jadi…"
  },
  AvgDialog_149753_Content_55 = {
    Text = "Ia tiba-tiba menghentikan langkahnya, mengangkat jari telunjuk, memberi isyarat diam kepadamu."
  },
  AvgDialog_149753_Content_56 = {
    Text = "Kamu langsung membeku, tanpa sadar menahan napas. Lentera padam, kegelapan menyerbu, menyelimutimu rapat tanpa celah."
  },
  AvgDialog_149753_Content_57 = {
    Text = "Jantung berdegup hingga hitungan keempat belas, dari ujung lorong terdengar suara benturan, disertai bunyi pecahan benda yang jatuh, beberapa teriakan tak terkendali memecah keheningan."
  },
  AvgDialog_149753_Content_58 = {
    Text = "Ada cahaya menyala, berkedip-kedip, seperti bayangan banyak orang yang sedang bertarung sengit, kamu berlari menghampiri, namun terpaksa mundur karena gelombang panas. Ternyata api, api berwarna biru."
  },
  AvgDialog_149753_Content_59 = {
    Text = "Lepas, ehm ehm, lepaskan aku! Aku hampir berhasil! Tinggal sedikit lagi, tinggal sedikit lagi!"
  },
  AvgDialog_149753_Content_6 = {
    Text = "Kamu segera memasang tudung dan berlari kecil menembus hujan, baru bisa mengikutinya dengan susah payah."
  },
  AvgDialog_149753_Content_60 = {
    Text = "Ruang rahasia itu dipenuhi bau menyengat, cairan merah gelap yang mencurigakan mengalir perlahan di dalam tabung kaca, lilin menyulut cairan bening yang tumpah di lantai, nyala api biru pucat membakar tanpa suara, ternyata di dalam manor tersembunyi sebuah ruang alkimia yang tersembunyi."
  },
  AvgDialog_149753_Content_61 = {
    Text = "Tepat di tengah-tengah berbagai peralatan kaca, sebuah piala berkaki tinggi dari emas murni bersinar cemerlang, lebih terang dari Wick, pasti itulah Piala Suci."
  },
  AvgDialog_149753_Content_62 = {
    Text = "Apa yang kamu masukkan ke dalamnya?"
  },
  AvgDialog_149753_Content_63 = {
    Text = "Lepaskan aku! Kamu tidak mengerti! Sebentar lagi, sebentar lagi tiba… menembus tirai yang lapuk, menjalar di sepanjang jalan yang terlupakan. Orang hidup, orang mati, tak ada yang bisa lolos… tak ada yang bisa lolos…"
  },
  AvgDialog_149753_Content_64 = {Text = "Ia?"},
  AvgDialog_149753_Content_65 = {
    Text = "Ia… malam abadi yang tak berujung, kehancuran yang paling akhir… itulah kutukan… <Shake:Kutukan akan segera tiba! Kutukan yang menelan segalanya, kutukan <Red:Putri Penyihir>!!>"
  },
  AvgDialog_149753_Content_66 = {
    Text = "Apa katamu?!"
  },
  AvgDialog_149753_Content_67 = {
    Text = "Bayangan di belakangnya bergidik hebat, nyala api jatuh ke dalam mata yang terbelalak karena ketakutan, menyulut sesuatu? Rasa takut, atau harapan?"
  },
  AvgDialog_149753_Content_68 = {
    Text = "Dalam kalimat itu pasti tersembunyi mantra yang sangat kuat, karena ksatriamu tiba-tiba membeku seperti patung batu, namun seolah baru pertama kali hidup. Bayangannya terus gemetar tanpa henti."
  },
  AvgDialog_149753_Content_69 = {
    Text = "Ka, kamu……kamu ingat dia? Kamu masih ingat apa lagi?"
  },
  AvgDialog_149753_Content_7 = {
    Text = "Kamu sedang mencari apa?"
  },
  AvgDialog_149753_Content_70 = {
    Text = "<Shake:Kesia-siaan, kesia-siaan dari segala kesia-siaan, semua adalah kesia-siaan……Manusia berjuang bagai debu di atas batu, tanpa masa lalu, tanpa masa depan……>"
  },
  AvgDialog_149753_Content_71 = {
    Text = "Tidak, Piala Emas! Piala Emas adalah satu-satunya keselamatan! Biarkan aku meminum kebenaran, biarkan aku——aku harus terus!"
  },
  AvgDialog_149753_Content_72 = {
    Text = "<Big:Jawab pertanyaanku! @1@2Putri, seberapa banyak yang kamu ingat tentang dirinya?!>"
  },
  AvgDialog_149753_Content_73 = {
    Text = "Bayangan menggeliat, bayangan bergolak, bayangan menari liar, bayangan melilit leher monster semakin erat, kedua bibirnya membuka dan menutup dengan sia-sia."
  },
  AvgDialog_149753_Content_74 = {
    Text = "<Shake:Aku ingat……wabah……ramuan sihir……kutukan……kha, kha……aku ingat, aku ingat kamu……>"
  },
  AvgDialog_149753_Content_75 = {
    Text = "<Shake:<Red:O……Gir>……ksatriaku……kamu……larilah……>"
  },
  AvgDialog_149753_Content_76 = {Text = "\"Kha.\""},
  AvgDialog_149753_Content_77 = {
    Text = "Kata-katanya belum selesai, namun sudah tak bisa dilanjutkan, bayangan mematahkan lehernya. Kepala yang gembung itu seperti karung goni yang diikat kencang, terkulai lemah ke satu sisi, dari lubang yang menganga tampak dua bola mata berkarat, masih menatap kosong ke kekosongan."
  },
  AvgDialog_149753_Content_79 = {
    Text = "O……Gir? Jangan-jangan ini……namamu?"
  },
  AvgDialog_149753_Content_8 = {
    Text = "Aku tidak pernah mengizinkanmu untuk ikut."
  },
  AvgDialog_149753_Content_80 = {
    Text = "Ia tiba-tiba berbalik, bagai arwah yang terungkap wujud aslinya, ekspresinya berada di antara kebingungan dan kebencian. Bayangan di dinding bergoyang-goyang, melangkah dengan tarian riang, mengelilingi kalian di tengah-tengahnya."
  },
  AvgDialog_149753_Content_81 = {
    Text = "Tidak, salah kah? Baiklah……bagaimanapun juga apapun namamu, kamu adalah ksatriaku."
  },
  AvgDialog_149753_Content_82 = {
    Text = "Piala Suci sudah ditemukan, sekarang kita pergi ke mana?"
  },
  AvgDialog_149753_Content_83 = {
    Text = "Diingatkan olehmu, ia perlahan memutar kepala, memandang piala emas di atas meja, lalu dengan susah payah melepaskan diri dari bayangan, mengangkat setengah cangkir sisa penawar racun, atau mungkin racun, kamu tidak tahu."
  },
  AvgDialog_149753_Content_84 = {
    Text = "Kamu hanya melihatnya mendongak dan meminumnya."
  },
  AvgDialog_149753_Content_85 = {
    Text = "<Big:Hei!!>"
  },
  AvgDialog_149753_Content_9 = {
    Text = "Kalau aku tidak ikut, bagaimana kalau kamu mengkhianati putrimu? Kamu bahkan tidak mau bersumpah."
  },
  AvgDialog_149754_Content_1 = {
    Text = "Suara gemuruh yang memekakkan telinga, seolah seluruh menara utama berguncang, batu bata yang retak berjatuhan dengan bunyi berderak, monster-monster yang tersisa mengelilingi sang tuan rapat-rapat di tengah, bergerombol mundur ke arah lorong rahasia."
  },
  AvgDialog_149754_Content_10 = {
    Text = "Entah sudah berjalan seberapa jauh, angin berhembus dari depan. Asin. Laut."
  },
  AvgDialog_149754_Content_11 = {
    Text = "Ke-keluar! Kita berhasil kabur! Ogier, apakah kamu mendengarku? Kita selamat!!"
  },
  AvgDialog_149754_Content_12 = {Text = "…Ogier?"},
  AvgDialog_149754_Content_13 = {
    Text = "Ia tidak mengeluarkan suara apa pun, bahkan kamu tak bisa merasakan napasnya. Ombak menghantam karang, air laut dingin bercampur hujan membasahi wajahmu, seolah baru kali ini kamu merasakan dingin, kamu tak bisa menahan tubuhmu yang mulai gemetar."
  },
  AvgDialog_149754_Content_14 = {
    Text = "<SmallShake:…Uhuk… uhuk uhuk…>"
  },
  AvgDialog_149754_Content_15 = {
    Text = "Ogier! Syukurlah, aku tahu kamu tidak akan mati!"
  },
  AvgDialog_149754_Content_16 = {
    Text = "<Shake:Aku… tidak pernah… berjanji padamu… untuk ikut.>"
  },
  AvgDialog_149754_Content_17 = {
    Text = "Sudah tahu, mau berapa kali lagi kamu mengatakannya. Apakah seorang putri perlu izin ksatria untuk pergi ke mana pun?"
  },
  AvgDialog_149754_Content_19 = {
    Text = "<Shake:Aku… dulu… pernah memiliki… seorang putri.>"
  },
  AvgDialog_149754_Content_2 = {
    Text = "Ksatriamu berjuang keras bertahan, dadanya yang hancur mengeluarkan raungan serak penuh amarah, namun bayangan-bayangan itu menyerbu bagai ombak. Dibanding musuh, mereka seolah lebih ingin mencabik-cabiknya hidup-hidup."
  },
  AvgDialog_149754_Content_20 = {
    Text = "<Shake:Aku tidak… berhasil melindunginya.>"
  },
  AvgDialog_149754_Content_21 = {
    Text = "Gumaman lemahnya terdengar seperti igauan, dengan mudah tersapu angin laut, kamu terpaksa menahan napas."
  },
  AvgDialog_149754_Content_22 = {
    Text = "Sebelum perang… meletus… ia memerintahkanku… untuk pergi…"
  },
  AvgDialog_149754_Content_23 = {
    Text = "Aku……mematuhinya."
  },
  AvgDialog_149754_Content_24 = {
    Text = "Aku tidak menyangka……pasukan musuh……begitu cepat……aku tidak sempat, uhuk uhuk, tidak sempat……"
  },
  AvgDialog_149754_Content_25 = {
    Text = "Pembantaian……mayat-mayat……wabah hitam……<Shake:Sang Putri……dia merelakan dirinya, uhuk uhuk uhuk uhuk!>"
  },
  AvgDialog_149754_Content_26 = {
    Text = "Entah kenangan menyakitkan apa yang terbayang, kau bisa merasakan tubuhnya mengkerut, seperti siput yang ditaburi garam."
  },
  AvgDialog_149754_Content_27 = {
    Text = "<Shake:Ini salahku……aku tidak mampu melindungi……semuanya lenyap……semuanya akan lenyap……>"
  },
  AvgDialog_149754_Content_28 = {
    Text = "<Shake:Dulu……aku ingin menjadi ksatria……>"
  },
  AvgDialog_149754_Content_29 = {
    Text = "<Shake:Tapi……sekarang……aku ini……siapa……>"
  },
  AvgDialog_149754_Content_3 = {
    Text = "Berhenti! Kalian yang sebenarnya monster! Jangan lari!!"
  },
  AvgDialog_149754_Content_30 = {
    Text = "Dulu ya dulu, sekarang ya sekarang, sekarang kau pun memiliki seorang putri, dan kau masih harus melindungiku."
  },
  AvgDialog_149754_Content_31 = {
    Text = "Ia lama tak menjawab, namun menggeliat sedikit."
  },
  AvgDialog_149754_Content_32 = {
    Text = "<Shake:Turunkan aku, uhuk uhuk uhuk, tolong turunkan aku.>"
  },
  AvgDialog_149754_Content_33 = {
    Text = "Akulah yang paling lemah……paling tidak berdaya……"
  },
  AvgDialog_149754_Content_34 = {
    Text = "Yang paling pantas……tertinggal……tinggal di……masa lalu……yang terlupakan……"
  },
  AvgDialog_149754_Content_35 = {
    Text = "Tidak mungkin! Janjimu belum terpenuhi, masa mau ingkar?"
  },
  AvgDialog_149754_Content_36 = {
    Text = "Air pasang merendam lututmu, kau berjuang keras menembus kegelapan, karang-karang tajam merobek betismu, luka-lukamu terasa kebas direndam air laut, kau mengatupkan gigi, tak mengeluarkan sepatah pun keluhan."
  },
  AvgDialog_149754_Content_37 = {
    Text = "Kata-katamu tercabik oleh napas yang berat, kau memaksa setiap kalimat keluar dari tenggorokan, setiap kali selesai mengucap satu kalimat, kau melangkah maju selangkah, seolah kata-kata itu yang menopangmu untuk terus berjalan."
  },
  AvgDialog_149754_Content_38 = {
    Text = "Kau adalah, ksatria pilihanku. Jika kubiarkan kau tinggal, bagaimana sang putri bisa, seorang diri, mengalahkan monster, menyelesaikan petualangan?"
  },
  AvgDialog_149754_Content_39 = {
    Text = "……Itu hanyalah sebuah cerita."
  },
  AvgDialog_149754_Content_4 = {
    Text = "Kamu panik dan marah, melempar bungkusan yang kamu peluk dengan sekuat tenaga. Bungkusan itu penuh sesak, simpul tali yang longgar terurai di udara, dan barang-barang peninggalan seseorang pun berhamburan — lilin, sisir, patung batu kecil… dan piala suci."
  },
  AvgDialog_149754_Content_40 = {
    Text = "Semua hal, adalah cerita."
  },
  AvgDialog_149754_Content_41 = {
    Text = "Kemarin, adalah cerita hari ini, hari ini adalah, cerita hari esok. Ada yang, lenyap, ada yang, akan terus berlanjut. Tapi tidak boleh, tanpa cerita."
  },
  AvgDialog_149754_Content_42 = {
    Text = "Maka, pergilah mencari, Pulau Apel. Pergi, hah, hah……pergi selesaikan, cerita kita."
  },
  AvgDialog_149754_Content_5 = {
    Text = "Cahaya emas bergulung-gulung, terbang tinggi melewati rawa bayangan, membentur dinding batu, memantul dua kali di lantai, lalu menggelinding tepat ke kaki sang tuan tanah."
  },
  AvgDialog_149754_Content_6 = {
    Text = "Kamu melihatnya mengangkat tangan menghentikan pengawal, lalu membungkuk sendiri, memungut piala emas kecil itu, mengusap ukiran di dinding piala dengan ibu jarinya, seolah teringat sesuatu, dan menatapmu dengan pandangan penuh ejekan."
  },
  AvgDialog_149754_Content_7 = {
    Text = "Lalu dengan cepat berubah menjadi ketakutan."
  },
  AvgDialog_149754_Content_8 = {
    Text = "…Sebelum kastil itu benar-benar runtuh menjadi puing dan menguburkan bayangan, naga, serta semua peninggalan itu, ksatriamu menyeretmu bersembunyi ke dalam lorong rahasia."
  },
  AvgDialog_149754_Content_9 = {
    Text = "Ia sudah kelelahan, bahkan tak mampu berdiri, kamu mencengkeram lengannya erat-erat, melangkah dengan susah payah, seolah memikul sekarung gandum yang berat."
  },
  AvgDialog_149755_Content_1 = {Text = "Pulau Apel"},
  AvgDialog_149755_Content_10 = {
    Text = "Luka di kakimu tidak kunjung sembuh, malah semakin sakit seiring hujan yang terus-menerus turun, bagian bawah lutut membengkak seperti wortel, tidak bisa melangkah sama sekali. Beberapa hari terakhir, Ogier yang menggendongmu melewati gunung dan lembah."
  },
  AvgDialog_149755_Content_100 = {
    Text = "Paduka Putri, tidak perlu menangis untukku. Monster sudah terlalu banyak, satu-satunya yang bisa hamba lakukan untukmu adalah menjaga surga milik manusia, milik Paduka, ini adalah tanggung jawab hamba, sekaligus penebusan dosa hamba."
  },
  AvgDialog_149755_Content_101 = {
    Text = "Hamba tidak sedang menuju akhir, hamba akan melampaui akhir itu, karena hamba telah mendapatkan fajar."
  },
  AvgDialog_149755_Content_102 = {
    Text = "Hamba akan terus menjaga Paduka di tempat matahari terbit."
  },
  AvgDialog_149755_Content_103 = {
    Text = "Bayangan menyembur menggantikan darah, seseorang yang masuk ke dalam arus banjir yang menggelegar itu menghilang dalam sekejap mata, namun bayangan itu masih belum lenyap."
  },
  AvgDialog_149755_Content_104 = {
    Text = "Bayangan menggeliat, bayangan bergulung, bayangan mengeras menjadi perisai, menjadi tembok, akhirnya menjadi sebuah bendungan raksasa, kau menatap lekat-lekat kegelapan yang paling dalam, hingga kereta sapi membelok di sebuah tikungan, dan kau tak lagi bisa melihat permukaan sungai."
  },
  AvgDialog_149755_Content_105 = {
    Text = "Ksatriamu sejak saat itu menghilang tanpa kabar, ia hanya menepati setengah dari janjinya, namun meninggalkan sebuah pesan terakhir yang sungguh licik, membuatmu bahkan saat tertidur sambil menangis pun, tetap menantikan hari esok."
  },
  AvgDialog_149755_Content_106 = {
    Text = "Karena saat itu akan ada matahari baru yang terbit, hari demi hari, tak pernah berubah."
  },
  AvgDialog_149755_Content_11 = {
    Text = "Ini, baru dipetik."
  },
  AvgDialog_149755_Content_12 = {
    Text = "Seolah untuk menghibur, ia menyelipkan sebuah buah ke tanganmu, kamu setengah sadar menggigitnya, hingga rasa asam menyebar di pangkal gigimu, baru kamu menyadari apa itu."
  },
  AvgDialog_149755_Content_13 = {
    Text = "……Apel?"
  },
  AvgDialog_149755_Content_14 = {
    Text = "Ya, tadi melewati kebun apel."
  },
  AvgDialog_149755_Content_15 = {
    Text = "Apel… Pulau Apel, apakah kita sudah sampai?"
  },
  AvgDialog_149755_Content_16 = {
    Text = "Sebentar lagi."
  },
  AvgDialog_149755_Content_17 = {
    Text = "Ia melepas perban yang membalut, menempelkan ramuan herbal pada luka, lalu membalutnya kembali satu per satu. Kamu mengamati ekspresinya, merasa itu bukanlah ekspresi penuh harapan."
  },
  AvgDialog_149755_Content_18 = {
    Text = "Kamu masih ingin menggali lebih dalam, namun terganggu oleh suara gonggongan anjing yang semakin mendekat."
  },
  AvgDialog_149755_Content_19 = {
    Text = "Tunggu, jangan lari secepat itu! Kamu mau ke mana? Itu bukan jalan kembali ke desa— Ah!"
  },
  AvgDialog_149755_Content_2 = {
    Text = "……sadar……"
  },
  AvgDialog_149755_Content_20 = {
    Text = "Anjing gembala yang garang menerobos keluar dari semak-semak, mengusir tamu tak diundang dengan keras, gadis yang mengejar di belakangnya melihat kalian, tak bisa menahan teriakan kaget, keranjang rotan di tangannya pun jatuh ke tanah."
  },
  AvgDialog_149755_Content_21 = {
    Text = "Itu Ogier, bekas luka hitam kotor memenuhi wajahnya, seperti boneka kain yang robek lalu dijahit sembarangan, mengingatkan orang pada banyak legenda mengerikan."
  },
  AvgDialog_149755_Content_22 = {
    Text = "Ia menatap gadis itu dalam diam, lalu berdiri dan mengenakan tudungnya."
  },
  AvgDialog_149755_Content_23 = {
    Text = "Kita pergi sekarang."
  },
  AvgDialog_149755_Content_24 = {
    Text = "Bukan… bukan itu, aku tidak— tunggu sebentar!"
  },
  AvgDialog_149755_Content_25 = {
    Text = "Ogier baru saja melangkah beberapa langkah sambil menggendongmu, ketika gadis itu dengan tergesa-gesa mengejarnya."
  },
  AvgDialog_149755_Content_26 = {
    Text = "Jangan pergi! Bukan itu maksudku, masih banyak orang sakit di desa, biar aku antar kalian!"
  },
  AvgDialog_149755_Content_27 = {Text = "Sakit?"},
  AvgDialog_149755_Content_28 = {
    Text = "Ya, semuanya penderita kusta. Awalnya hanya ada penderita kusta, lalu tentara datang, tentara menghancurkan banyak desa, tapi tidak pernah mendekati desa kusta, jadi beberapa orang yang kehilangan rumah mereka melarikan diri ke sini, termasuk aku."
  },
  AvgDialog_149755_Content_29 = {
    Text = "Tidak perlu khawatir, semua orang sudah terbiasa. Sebenarnya selain tampak berbeda, kami tidak jauh berbeda, sama-sama makan, tidur, bekerja… penyakit kusta tidak seseram tentara, lama-lama akan terbiasa."
  },
  AvgDialog_149755_Content_3 = {
    Text = "……hujan……istirahat……bangun……"
  },
  AvgDialog_149755_Content_30 = {
    Text = "Maaf, aku tidak takut padamu, aku hanya belum pernah melihat… maaf! Ini sekeranjang apel biru untukmu, aku yang memilihnya, dijamin yang paling besar dan paling manis!"
  },
  AvgDialog_149755_Content_31 = {
    Text = "Seperti apa seharusnya surga itu?"
  },
  AvgDialog_149755_Content_32 = {
    Text = "Tidak ada monster, tidak ada keputusasaan, tidak ada kepanikan yang tak terlukiskan, tidak ada mata yang mengintai dalam kegelapan, tidak perlu takut tidak bisa bangun lagi sebelum tidur, setiap hari bisa minum sup hangat."
  },
  AvgDialog_149755_Content_33 = {
    Text = "Kau tidak tahu apakah ada tempat lain yang lebih mirip surga dari sini."
  },
  AvgDialog_149755_Content_34 = {
    Text = "…Sudah cukup."
  },
  AvgDialog_149755_Content_35 = {
    Text = "Pisau tajam membelah abses, sedikit demi sedikit membuang daging busuk yang membusuk, besi panas yang membara ditekan ke luka yang terus berdarah, rasa sakit yang luar biasa membuatmu menjerit tertahan, berkeringat deras."
  },
  AvgDialog_149755_Content_36 = {
    Text = "Sudah selesai. Kain yang dijejalkan ke mulutmu diambil, kau berusaha sekuat tenaga untuk bernapas, hampir menelan udara ke dalam perutmu."
  },
  AvgDialog_149755_Content_37 = {
    Text = "Kali ini berbeda, kau tahu. Mereka melakukan ini untuk menyelamatkanmu, dan ksatriamu pun ada di sisimu."
  },
  AvgDialog_149755_Content_38 = {
    Text = "Obat ini, bawa pulang dan rebus dengan air untuk diminum. Sekali saat fajar, sekali saat malam."
  },
  AvgDialog_149755_Content_39 = {
    Text = "Baik, terima kasih."
  },
  AvgDialog_149755_Content_4 = {
    Text = "Kamu dibangunkan dengan lembut, kesadaranmu masih kabur, terdengar suara hujan yang rintik-rintik."
  },
  AvgDialog_149755_Content_40 = {
    Text = "Ia mengeluarkan beberapa keping koin sebagai imbalan, namun tukang cukur itu menggelengkan tangan menolaknya. Di tempat yang terisolasi dari dunia luar, nilai dari luar tidak ada gunanya, orang-orang di sini tidak hidup untuk itu."
  },
  AvgDialog_149755_Content_41 = {
    Text = "<Small:Cuaca cerah…>"
  },
  AvgDialog_149755_Content_42 = {
    Text = "<Small:Ogier, aku ingin pergi ke kebun apel.>"
  },
  AvgDialog_149755_Content_43 = {
    Text = "Kamu perlu beristirahat."
  },
  AvgDialog_149755_Content_44 = {
    Text = "Bawa aku ke sana, aku punya penemuan besar… yang ingin kuceritakan padamu."
  },
  AvgDialog_149755_Content_45 = {
    Text = "Sudah sampai. Penemuan besar apa?"
  },
  AvgDialog_149755_Content_46 = {
    Text = "Hah… Aku menemukan bahwa tempat ini adalah Pulau Apel, kita sudah menemukannya."
  },
  AvgDialog_149755_Content_47 = {
    Text = "Ksatriamu meletakkanmu di atas sebatang kayu tumbang, berlutut, dan dengan hati-hati menopang kakimu yang terluka. Tatapannya penuh perhatian dan kekhawatiran, jelas kebenaran yang baru kamu sadari itu tidak membuatnya terkejut."
  },
  AvgDialog_149755_Content_48 = {
    Text = "Tapi ini bukan pulau."
  },
  AvgDialog_149755_Content_49 = {
    Text = "Tidak ada yang bilang pulau harus berada di laut, bukan? Selama tidak terhubung dengan dunia luar, itu sudah bisa disebut pulau."
  },
  AvgDialog_149755_Content_5 = {
    Text = "Hujan turun lagi, hujan tak pernah benar-benar berhenti."
  },
  AvgDialog_149755_Content_50 = {
    Text = "Apalagi di sini ada peri."
  },
  AvgDialog_149755_Content_51 = {Text = "Peri?"},
  AvgDialog_149755_Content_52 = {
    Text = "Ya, di desa ini banyak peri. Ada yang berwajah singa, ada yang bersisik ikan, ada pula yang berganti kulit seperti ular. Mereka adalah peri yang hidup di negeri ajaib."
  },
  AvgDialog_149755_Content_53 = {
    Text = "Peri… bukan monster?"
  },
  AvgDialog_149755_Content_54 = {
    Text = "Tentu saja bukan! Peri dan monster, bagaimana mungkin sama?"
  },
  AvgDialog_149755_Content_55 = {
    Text = "Monster memakan manusia, melakukan segala cara untuk memakan manusia. Kadang langsung membunuh dengan pisau lalu memakannya, kadang membuat kebohongan, mengurung manusia, lalu memotong dagingnya sedikit demi sedikit."
  },
  AvgDialog_149755_Content_56 = {
    Text = "Tidak hanya dimakan sendiri, tapi juga dibuat sup, dijadikan daging asin, dijadikan bubur, lalu diberikan kepada manusia untuk dimakan. Daging manusia ada di mana-mana, tidak makan akan kelaparan, tapi siapa pun yang pernah memakan manusia akan berubah menjadi monster, sehingga monster semakin banyak."
  },
  AvgDialog_149755_Content_57 = {
    Text = "Manusia tidak memakan manusia, peri pun tidak memakan manusia. Di Pulau Apel, mereka bersih."
  },
  AvgDialog_149755_Content_58 = {
    Text = "Lalu bagaimana denganku? Aku bukan manusia, bukan pula peri. Tanganku penuh dengan darah, dalam tubuhku bersemayam iblis, kamu sendiri pernah melihat wujudnya."
  },
  AvgDialog_149755_Content_59 = {
    Text = "Mengapa tidak takut?"
  },
  AvgDialog_149755_Content_6 = {
    Text = "Hutan menyembunyikan para pelarian yang melarikan diri, kekejaman monster yang membasahi kastil dengan darah telah sampai ke telinga penguasa, surat perintah penangkapan ditempel di setiap kota, ksatria gereja dan tentara bayaran semuanya telah bergerak, kalian terpaksa berjalan siang dan malam."
  },
  AvgDialog_149755_Content_60 = {
    Text = "Mengapa harus takut? Sejak pertama kali melihatnya, kamu sudah tahu bahwa dia pasti seorang ksatria. Melalui bayangan gelap yang menyelimutinya, kamu masih bisa melihat sosoknya sebagai ksatria, begitu jelas, begitu pasti, seolah kamu pernah melihatnya di suatu tempat."
  },
  AvgDialog_149755_Content_61 = {
    Text = "Apa yang dibutuhkan untuk menjadi ksatria sejati? Kesetiaan, keberanian, belas kasih, pengorbanan, dan…"
  },
  AvgDialog_149755_Content_62 = {
    Text = "Pemberian gelar dari sang tuan."
  },
  AvgDialog_149755_Content_63 = {
    Text = "Ehm, ehm… Kalau begitu, aku menyatakan, atas nama sang putri, aku mengangkatmu sebagai ksatria."
  },
  AvgDialog_149755_Content_64 = {
    Text = "Kau telah mengalahkan monster, merebut piala suci, menahan iblis, dan melindungiku. Kau telah menepati janjimu, mengantarkan putrimu ke Pulau Apel."
  },
  AvgDialog_149755_Content_65 = {
    Text = "Tak peduli siapa dirimu dulu, dalam kisah kita, kau adalah seorang ksatria, dan tak ada putri yang akan takut pada ksatrianya sendiri."
  },
  AvgDialog_149755_Content_66 = {
    Text = "Kau akan selalu menjadi ksatriaku."
  },
  AvgDialog_149755_Content_67 = {
    Text = "Ksatriamu terpaku, satu tangannya menggenggam erat jubah itu, seolah ingin bersembunyi di balik bayangan yang luas. Jubah itu menutupi jejak bayangannya, hanya dia sendiri yang tahu betapa rapuh dirinya di balik penyamaran itu."
  },
  AvgDialog_149755_Content_68 = {
    Text = "Ranting-ranting tipis yang masih basah oleh embun hujan itu perlahan bertumpu di bahunya. Kerinduan yang sudah hampir terlupakan tiba-tiba menjadi nyata, namun yang membuat jiwanya gemetar bukanlah kebahagiaan."
  },
  AvgDialog_149755_Content_69 = {
    Text = "Melainkan Ketakutan."
  },
  AvgDialog_149755_Content_7 = {
    Text = "Di depan ada sebuah desa, aku pergi menukar beberapa makanan dan obat, kamu istirahat di sini, tunggu hujan berhenti baru kita pergi."
  },
  AvgDialog_149755_Content_70 = {
    Text = "Nyala api ketakutan membubung dari jurang tanpa dasar, di bawah kaki, di atas kepala, di mata yang ketakutan di balik celah sempit. Panas membara, hangat mengalir, menyembur dari leher yang patah, meluap dari dada. Api begitu terpelintir, bayangan pun ikut mengamuk. Api dan bayangan sejatinya satu."
  },
  AvgDialog_149755_Content_71 = {
    Text = "Itu adalah sebuah pembantaian, tanpa kehormatan, tanpa keadilan, sama bagi semua orang. Akhir yang berlumuran darah merobek-robek polesan kata-kata manis, kematian hanyalah kematian. Ia tidak ingat bagaimana dirinya bisa bertahan hidup, mungkin memang ia tidak pernah bertahan."
  },
  AvgDialog_149755_Content_72 = {
    Text = "Monster yang telah jatuh, arwah yang haus balas dendam, pencariannya bagaikan menyiram api dengan kayu bakar, Orang yang Tersesat tak terbendung meluncur menuju kehancuran, tak pernah percaya bisa mendapat penebusan."
  },
  AvgDialog_149755_Content_73 = {
    Text = "<Shake:Tapi… tapi…>"
  },
  AvgDialog_149755_Content_74 = {
    Text = "Ogier, Ogier? Hei, apakah kau mendengarkan, aku sudah selesai bicara, sekarang giliranmu."
  },
  AvgDialog_149755_Content_76 = {
    Text = "Ya, aku bersedia."
  },
  AvgDialog_149755_Content_77 = {
    Text = "Atas nama tanah airku yang telah hilang, aku, Ogier putra Keluarga Dansk, bersumpah setia dan hormat kepadamu."
  },
  AvgDialog_149755_Content_78 = {
    Text = "Aku persembahkan perisai dan tombakku untukmu, beserta keyakinan yang telah ternoda olehku, ketakutanku yang abadi, dan hatiku yang tak utuh. Aku pernah kehilangan namaku di malam yang panjang, namun panggilanmulah yang menerangi fajar."
  },
  AvgDialog_149755_Content_79 = {
    Text = "Mereka yang mengingkari sumpah tidak layak lagi disebut beriman, namun jika pandanganmu masih bersedia bertahan, maka aku akan menjadi milikmu, hingga napas terakhirku."
  },
  AvgDialog_149755_Content_8 = {
    Text = "<Small:Mengerti… cepat kembali.>"
  },
  AvgDialog_149755_Content_80 = {
    Text = "Kisah tidak selalu dimulai dengan awal yang penuh warna, ia pun bisa bermula dari tepi keputusasaan."
  },
  AvgDialog_149755_Content_81 = {
    Text = "Meski ujung jalan berdiri abadi, menghujani segala sesuatu dengan bayangan yang berat, sebelum tiba di sana, kalian masih memiliki kebebasan untuk memilih apa yang akan menjadi takdir."
  },
  AvgDialog_149755_Content_82 = {
    Text = "Angin sepoi-sepoi, sinar matahari, aroma apel matang, kabut mengembang bagai awan dari dalam hutan, dunia indah bagai lukisan, kau tertawa gembira, seolah menyambut akhir yang sempurna."
  },
  AvgDialog_149755_Content_83 = {
    Text = "Namun kau tahu kisah ini akan terus berlanjut, ia selalu akan terus berlanjut."
  },
  AvgDialog_149755_Content_84 = {
    Text = "<Big:Masih berapa orang yang belum bangun? Cepat panggil mereka, banjir akan datang!>"
  },
  AvgDialog_149755_Content_85 = {
    Text = "Kegelapan malam memperparah amukan hujan deras, tetes-tetes air jatuh berdentam seperti batu kerikil, air sungai yang keruh menderu menerjang kedua tepi, genangan air sudah melewati lutut."
  },
  AvgDialog_149755_Content_86 = {
    Text = "Sosok-sosok berlari ke sana kemari, berteriak keras, memukul setiap pintu dan jendela dengan sekuat tenaga, namun para peri bergerak lamban, setelah jatuh tak mampu bangkit lagi, tak bisa menyeberangi tanah berlubang yang tidak rata sendirian."
  },
  AvgDialog_149755_Content_87 = {
    Text = "\"Bum!!\" Suara dentuman keras yang jelas membuat jantungmu bergetar, namun malam yang gelap gulita membuat orang-orang menatap bingung ke sekeliling, tidak tahu apa yang akan segera runtuh."
  },
  AvgDialog_149755_Content_88 = {
    Text = "<Big:Celaka, itu tanggul!!>"
  },
  AvgDialog_149755_Content_89 = {
    Text = "<Big:Cepat pergi! Yang bisa pergi segera pergi, sudah tidak ada waktu!>"
  },
  AvgDialog_149755_Content_9 = {
    Text = "Meski sangat tidak ingin ditinggal, tubuhmu panas luar biasa, sudah tidak ada tenaga untuk mengikutinya."
  },
  AvgDialog_149755_Content_90 = {
    Text = "Ratapan, erangan, tangisan, surga impianmu goyah dan hampir dihancurkan oleh hujan yang tiada henti, hanya menyisakan reruntuhan yang hancur. Sementara kamu bahkan tidak bisa berjalan sendiri, hanya bisa menyaksikan dengan tak berdaya."
  },
  AvgDialog_149755_Content_91 = {
    Text = "Ksatriamu mengangkatmu ke tepi kereta, melepas jubahnya, dan membungkusmu dengan rapat."
  },
  AvgDialog_149755_Content_92 = {
    Text = "Paduka Putri, hamba mohon izin untuk pergi menghadapi banjir yang mengamuk."
  },
  AvgDialog_149755_Content_93 = {
    Text = "Bisakah kamu menghentikan banjir itu?"
  },
  AvgDialog_149755_Content_94 = {
    Text = "Hamba akan berusaha semaksimal mungkin."
  },
  AvgDialog_149755_Content_95 = {
    Text = "Bisakah kamu kembali?"
  },
  AvgDialog_149755_Content_96 = {
    Text = "……Hamba akan berusaha semaksimal mungkin."
  },
  AvgDialog_149755_Content_97 = {
    Text = "<Big:Tidak, tidak mau, aku tidak setuju! Aku tidak mengizinkan!>"
  },
  AvgDialog_149755_Content_98 = {
    Text = "Kita pergi, pergi sekarang… masih akan ada yang berikutnya, Pulau Apel, Pulau Labu, apa saja, masih akan ada yang berikutnya!"
  },
  AvgDialog_149755_Content_99 = {
    Text = "Kamu menggenggam ujung bajunya dengan sekuat tenaga, namun dalam hati tahu ini hanya sia-sia, dia sudah membuat pilihannya. Dia membungkuk hormat padamu, seperti pahlawan paling lembut dan ksatria paling setia dalam semua kisah."
  },
  AvgDialog_149756_Content_1 = {Text = "Putri"},
  AvgDialog_149756_Content_10 = {
    Text = "Kamu ingin membantah dengan keras, ingin mengejek, ingin memaki, ingin berteriak, tapi kain berlumur minyak menyumbat mulutmu. Benda asing yang amis dan berminyak itu menekan pangkal lidahmu dengan kuat, selain muntah-muntah, kamu tidak bisa mengeluarkan suara apa pun."
  },
  AvgDialog_149756_Content_11 = {
    Text = "Lihat, dia gemetar, iblis di dalam tubuhnya sedang meronta, inilah wujud aslinya yang buruk."
  },
  AvgDialog_149756_Content_12 = {
    Text = "Tuhan yang Maha Pengasih, aku memohon kepada-Mu untuk membuka mulutnya yang disegel oleh iblis, biarkan dia mengakui dosanya sendiri, jika di dalam hatinya masih ada kerinduan akan keselamatan."
  },
  AvgDialog_149756_Content_13 = {
    Text = "Gumpalan kain penyumbat itu ditarik keluar dengan kasar, kamu terbatuk dua kali, lalu terengah-engah, air liur mengalir dari sudut mulutmu."
  },
  AvgDialog_149756_Content_14 = {
    Text = "Para monster mengangkat kapak dan garpu jerami membentuk lingkaran, menatapmu dengan waspada. Di tempat yang lebih jauh, di pematang sawah, di antara ranting pohon, di balik jendela yang setengah terbuka, masih banyak mata yang tersembunyi."
  },
  AvgDialog_149756_Content_15 = {
    Text = "Ucapkanlah, nak! Nyatakan penyesalanmu kepada Tuhan, inilah saat terakhirmu untuk terbebas dari hukuman abadi!"
  },
  AvgDialog_149756_Content_16 = {
    Text = "<Small:…Monster.>"
  },
  AvgDialog_149756_Content_17 = {
    Text = "Apa? Apa yang dia katakan?"
  },
  AvgDialog_149756_Content_18 = {
    Text = "<BigShake:Monster! Monster! Mon— uhuk uhuk uhuk!>"
  },
  AvgDialog_149756_Content_19 = {
    Text = "Tipuan yang dirancang dengan cermat itu kamu bongkar, para monster menampakkan ekspresi panik, kamu merasakan kepuasan yang kejam."
  },
  AvgDialog_149756_Content_2 = {
    Text = "Monster-monster itu memakan keluargaku, dan sekarang, mereka berencana memakan diriku."
  },
  AvgDialog_149756_Content_20 = {
    Text = "Kutukan, ini kutukan! Penyihir sialan!"
  },
  AvgDialog_149756_Content_21 = {
    Text = "Cepat sumbat mulutnya!"
  },
  AvgDialog_149756_Content_22 = {
    Text = "Tuhan… lindungi kami…"
  },
  AvgDialog_149756_Content_23 = {
    Text = "<Big:Bakar dia! Bakar dia!>"
  },
  AvgDialog_149756_Content_24 = {
    Text = "<Big:Goblin! Makhluk rawa! Ghoul! Monster! Kalian semua adalah mon— uuuu——!!>"
  },
  AvgDialog_149756_Content_25 = {
    Text = "Iblis telah merenggut jiwanya, demi melindungi desa kita dari ancaman ilmu sihir, yang najis ini harus disingkirkan."
  },
  AvgDialog_149756_Content_26 = {
    Text = "Semoga api suci membakar habis dosanya, semoga Tuhan menganugerahkan kedamaian bagi kami."
  },
  AvgDialog_149756_Content_27 = {
    Text = "Seikat demi seikat kayu kering ditumpuk di bawah kakimu, duri-duri merobek kulitmu yang terbuka, kamu meronta kesakitan, rantai besi bergemerincing."
  },
  AvgDialog_149756_Content_28 = {
    Text = "Hal itu membuatmu mendapat lebih banyak makian, serta seutas tali rami yang diikat lebih kencang."
  },
  AvgDialog_149756_Content_29 = {
    Text = "Api pun menyala."
  },
  AvgDialog_149756_Content_3 = {
    Text = "Senja adalah pertanda kebangkitan sesuatu, matahari terbenam bagaikan bercak merah yang sakit, langit pun membengkak karena memar darah."
  },
  AvgDialog_149756_Content_30 = {
    Text = "Kami mengusirmu… jiwa yang najis, bidah yang sesat… seperti asap yang ditiup angin, seperti lilin yang dilelehkan api…"
  },
  AvgDialog_149756_Content_31 = {
    Text = "Yang terjatuh, yang menindas, yang terusir, atas nama Suci Tuhan, aku memerintahkanmu, gentar lah, tunduk lah, pergi—"
  },
  AvgDialog_149756_Content_32 = {
    Text = "Suaranya terhenti mendadak, seolah dipotong oleh sepasang gunting di tengah-tengah."
  },
  AvgDialog_149756_Content_33 = {
    Text = "Kamu berusaha membuka lebar matamu yang perih, menembus kepulan asap tebal, kamu melihat sosok asing berdiri di samping sang pendeta."
  },
  AvgDialog_149756_Content_34 = {
    Text = "Kapan dia muncul? Kamu tidak tahu. Kamu melirik sisa-sisa monster itu, mereka tidak bergerak, seperti sekumpulan katak yang ternganga."
  },
  AvgDialog_149756_Content_35 = {
    Text = "Sang pendeta kejang-kejang dengan gelisah, kedua tangan menutupi lehernya, darah mengalir dari sela-sela jarinya, menyembur dari mulutnya, wajahnya sepucat langit. Dia pun roboh."
  },
  AvgDialog_149756_Content_36 = {
    Text = "<Big:Aah——!!>"
  },
  AvgDialog_149756_Content_37 = {
    Text = "Teriakan, lebih keras dari peluit, lidah api pun ikut bergetar."
  },
  AvgDialog_149756_Content_38 = {
    Text = "Darah… banyak sekali darah… ada yang terbunuh! Tolong, monster membunuh orang!"
  },
  AvgDialog_149756_Content_39 = {
    Text = "Tidak, tidak… iblis, itu iblis! Penyihir itu memanggil sesuatu dari neraka! Ya Tuhan, ampunilah kami…"
  },
  AvgDialog_149756_Content_4 = {
    Text = "Api belum menyala, namun pohon-pohon kering sudah memelintir, dengan sikap putus asa itu, seolah cahaya siang hari yang datang berulang pun adalah semacam pembakaran yang tak tertahankan."
  },
  AvgDialog_149756_Content_40 = {
    Text = "Jantungmu berdegup kencang, kamu tahu siapa dia, kamu tahu hidupmu tidak akan berakhir hari ini, ini hanyalah sebuah pendahuluan, sebuah selingan, untuk menyambut kedatangannya."
  },
  AvgDialog_149756_Content_41 = {
    Text = "Dipenuhi semangat penuh harapan, kamu meronta-ronta sekuat tenaga, memanggil dengan erangan, ingin sekali membuatnya melihatmu, hampir melupakan rantai besi yang membara."
  },
  AvgDialog_149756_Content_43 = {
    Text = "Sebuah tangan bersarung menarikmu keluar dari tumpukan api, kakimu lemas, jatuh tersungkur tak terkendali, batuk-batuk sambil muntah, air mata dan ingus bercampur jadi satu."
  },
  AvgDialog_149756_Content_44 = {
    Text = "<Shake:Uhuk uhuk uhuk uhuk uhuk uhuk——!! Tung, uhuk uhuk uhuk uhuk, tunggu! Jangan pergi!>"
  },
  AvgDialog_149756_Content_45 = {
    Text = "Sebelum dia berbalik pergi, kamu dengan tergesa-gesa mencengkeram jubahnya."
  },
  AvgDialog_149756_Content_46 = {
    Text = "Tampaknya tidak menduga tindakanmu, tudung kepalanya melorot setengah, memperlihatkan wajah seorang pemuda."
  },
  AvgDialog_149756_Content_47 = {Text = "Lepaskan."},
  AvgDialog_149756_Content_48 = {
    Text = "Kamu cukup cerdas untuk membedakan gertakan dan peringatan, mengingat kematian sang pendeta tidak lama ini, kamu pun bergidik."
  },
  AvgDialog_149756_Content_49 = {
    Text = "Namun kamu melihat wajahnya, tak diragukan lagi, ksatria mulia dalam cerita memang seharusnya seperti ini. Dia pasti datang untukmu, bahkan kamu merasa sepasang alis dan matanya itu terasa begitu familiar."
  },
  AvgDialog_149756_Content_5 = {
    Text = "<BigShake:Jangan tertipu oleh penampilannya!> Wajah anak kecil itu hanyalah penyamaran, di dalam tubuh itu bersemayam iblis, dosanya, Tuhan telah melihat semuanya."
  },
  AvgDialog_149756_Content_50 = {
    Text = "Ya, kamu pasti pernah melihatnya di suatu tempat, dalam mimpi, kutukan, atau ramalan. Kalau tidak, bagaimana menjelaskan keberanian yang tiba-tiba muncul itu?"
  },
  AvgDialog_149756_Content_51 = {
    Text = "<Shake:Tidak… uhuk uhuk uhuk, kamu tidak boleh pergi.>"
  },
  AvgDialog_149756_Content_52 = {Text = "Kenapa?"},
  AvgDialog_149756_Content_53 = {
    Text = "Karena, uhuk uhuk, karena kamu datang untuk menyelamatkanku, bagaimana bisa meninggalkanku di sini?"
  },
  AvgDialog_149756_Content_54 = {
    Text = "Kamu sudah diselamatkan, kembalilah ke kehidupanmu."
  },
  AvgDialog_149756_Content_55 = {
    Text = "Tidak ada kehidupan untukku di sini, di mana-mana ada monster yang hanya bisa menangkap dan memakan orang, kamu sudah melihatnya sendiri."
  },
  AvgDialog_149756_Content_56 = {
    Text = "Tidak ada hubungannya denganku."
  },
  AvgDialog_149756_Content_57 = {
    Text = "Bagaimana mungkin tidak ada hubungannya denganmu? Aku sudah menunggumu sepanjang waktu."
  },
  AvgDialog_149756_Content_58 = {
    Text = "Menungguku? Kamu… kamu mengenalku?"
  },
  AvgDialog_149756_Content_59 = {
    Text = "Tentu saja, kamu adalah ksatriaku."
  },
  AvgDialog_149756_Content_6 = {
    Text = "Dia adalah pencuri, penipu, hamba kegelapan. Bencana mengalir dari mulutnya, racun mencemari sumur dan sungai, sehingga sapi dan domba mati di kandang, orang-orang saleh pun tertimpa penyakit."
  },
  AvgDialog_149756_Content_60 = {
    Text = "Terkejut, bingung, panik, kesakitan, berbagai ekspresi sekaligus membanjiri wajahnya, dia tiba-tiba melepaskan tanganmu, seperti menghindari seekor ular berbisa, pedang pendek berlumuran darah itu menempel di lehermu."
  },
  AvgDialog_149756_Content_61 = {
    Text = "Siapa kamu!"
  },
  AvgDialog_149756_Content_62 = {
    Text = "Aku, aku adalah putri! Benar, aku adalah putri, aku diculik oleh monster dan selalu menunggumu datang menyelamatkanku!"
  },
  AvgDialog_149756_Content_63 = {
    Text = "Jangan tidak percaya, kalau aku bukan putri, mengapa Tuhan akan mengutus seorang ksatria untuk menyelamatkanku?"
  },
  AvgDialog_149756_Content_65 = {
    Text = "Pedang pendek itu masuk ke sarungnya, dia berdiri dan berjalan menuju kedalaman hutan lebat, tanpa mengucapkan sepatah kata pun lagi kepadamu."
  },
  AvgDialog_149756_Content_66 = {
    Text = "Tunggu, kamu mau ke mana, aku, uhuk, aku ikut bersamamu."
  },
  AvgDialog_149756_Content_67 = {
    Text = "<Shake:Berhenti! Uhuk uhuk, atas nama putri, aku memerintahkanmu untuk berhenti!>"
  },
  AvgDialog_149756_Content_68 = {
    Text = "Meskipun dia sangat lincah, namun kamu unggul karena mengenal hutan ini seperti punggung tanganmu sendiri."
  },
  AvgDialog_149756_Content_69 = {
    Text = "Apalagi kamu sudah tidak punya tempat lain untuk pergi, hanya bisa terus mengejar, mengejar, bahkan jika harus terjatuh di tengah hutan dan menjadi mangsa binatang buas."
  },
  AvgDialog_149756_Content_7 = {
    Text = "Kalian semua menjadi saksi, berapa kali dia masuk ke hutan, menghilang, lalu kembali seolah tidak terjadi apa-apa? Itulah bukti bahwa dia mempraktikkan ilmu sihir!"
  },
  AvgDialog_149756_Content_70 = {
    Text = "<Shake:Hah… hah… tunggu, aku, aku tahu aturannya.>"
  },
  AvgDialog_149756_Content_71 = {
    Text = "Aku punya tempat yang harus kutuju, antarkan aku ke sana, kamu akan mendapat kehormatan dan hadiah."
  },
  AvgDialog_149756_Content_72 = {
    Text = "Aku tidak membutuhkannya."
  },
  AvgDialog_149756_Content_73 = {
    Text = "Kamu membutuhkannya, setidaknya sekarang, kamu butuh seseorang untuk membawamu keluar dari sini, bukan?"
  },
  AvgDialog_149756_Content_74 = {
    Text = "Dia tidak menjawab, namun perlahan-lahan menghentikan langkahnya."
  },
  AvgDialog_149756_Content_75 = {
    Text = "Kau mau ke mana?"
  },
  AvgDialog_149756_Content_76 = {
    Text = "Hmm… oh ya, Pulau Apel, pernahkah kamu mendengarnya? Surga yang tidak perlu bercocok tanam, tidak akan sakit, dan tidak ada musim dingin, itulah tempat yang akan kutuju."
  },
  AvgDialog_149756_Content_77 = {
    Text = "Belum pernah mendengarnya. Di mana itu?"
  },
  AvgDialog_149756_Content_78 = {
    Text = "Peri itu tidak memberitahuku arahnya, tapi dia bilang aku pasti akan menemukannya suatu hari nanti, seperti dirinya. Kita bisa berjalan sambil mencarinya, lagipula, petualangan besar selalu penuh tantangan, bukan?"
  },
  AvgDialog_149756_Content_79 = {
    Text = "Jubah hitam itu menyatu dengan kegelapan malam, dia berdiri di balik semak belukar yang berantakan, wajahnya samar dan tidak jelas."
  },
  AvgDialog_149756_Content_8 = {
    Text = "<SmallShake:Wabah… penyihir… benar, ini karena penyihir… kutukan penyihir…>"
  },
  AvgDialog_149756_Content_80 = {
    Text = "Kamu berjalan sangat perlahan mendekatinya, dengan hati-hati, seolah takut mengusik seekor serigala liar."
  },
  AvgDialog_149756_Content_81 = {
    Text = "Berhenti, tetap di sana, jangan mendekat lagi."
  },
  AvgDialog_149756_Content_82 = {
    Text = "Tunjukkan jalannya."
  },
  AvgDialog_149756_Content_83 = {
    Text = "Apakah ini berarti kamu setuju, ksatria pemberani?"
  },
  AvgDialog_149756_Content_85 = {
    Text = "Aku bukan ksatria."
  },
  AvgDialog_149756_Content_86 = {
    Text = "Kamu adalah, mulai sekarang, kamu adalah ksatria setiaku."
  },
  AvgDialog_149756_Content_87 = {
    Text = "Ksatria menepati janjinya, sebelum tiba di Pulau Apel, kamu harus melindungiku. Kamu harus berjalan di depan, membersihkan duri dan sulur untukku, jika ada monster yang mengejar, kamu harus mengusirnya, dan juga…"
  },
  AvgDialog_149756_Content_88 = {
    Text = "Mau ke mana kamu? Kamu belum bersumpah, jika kamu berani berbohong dan menipu putrimu, kamu akan ditangkap dan dimakan monster, bersumpahlah dulu."
  },
  AvgDialog_149756_Content_89 = {
    Text = "Hei! Jangan pergi, tunggu aku — aku tahu jalannya!"
  },
  AvgDialog_149756_Content_9 = {
    Text = "Penyihir yang belum genap sepuluh tahun? Bahkan orang gila pun tak bisa berbohong seperti itu."
  },
  AvgDialog_149757_Content_1 = {Text = "Makam"},
  AvgDialog_149757_Content_10 = {
    Text = "<Shake:Hah, hah… sebenarnya di mana… ksatriku…>"
  },
  AvgDialog_149757_Content_11 = {
    Text = "Kamu teringat desas-desus itu, semakin khawatir. Tidak boleh membiarkan satu-satunya ksatriamu dikalahkan iblis, kamu akan mengingat namanya, kamu sudah mengingatnya."
  },
  AvgDialog_149757_Content_12 = {
    Text = "Ogier… ya, Ogier! Kamu di mana! <Big:O——gi——er——>"
  },
  AvgDialog_149757_Content_13 = {
    Text = "Sebuah raungan kesakitan menembus tirai hujan, lebih menyerupai binatang terluka daripada manusia, kamu langsung berlari menuju asal suara itu."
  },
  AvgDialog_149757_Content_14 = {
    Text = "Jangan bersembunyi lagi! Aku sudah melihatmu!"
  },
  AvgDialog_149757_Content_15 = {
    Text = "Pergi! Jangan, ha, jangan mendekat!!"
  },
  AvgDialog_149757_Content_16 = {
    Text = "Cahaya lentera bergetar tak menentu, tak mampu mengusir kegelapan yang mengepung dari segala arah, ksatriamu telah terpojok ke jalan buntu, punggungnya yang tegang bagai busur yang ditarik penuh."
  },
  AvgDialog_149757_Content_17 = {
    Text = "Diam! Aku tidak lupa! Itu bukan— tidak, aku tidak pernah— aku tidak akan lupa!"
  },
  AvgDialog_149757_Content_18 = {
    Text = "<Shake:Aku akan membalas dendam untuk mereka… aku harus membalas dendam untuk mereka… mata dibalas mata, gigi dibalas gigi…>"
  },
  AvgDialog_149757_Content_19 = {
    Text = "Tidak, tidak mungkin, kamu berbohong! Sang putri tidak akan berkata begitu, sang putri, sang putri dia—"
  },
  AvgDialog_149757_Content_2 = {
    Text = "Pernah kamu dengar seseorang berkata, nama setiap orang adalah sebuah mantra."
  },
  AvgDialog_149757_Content_20 = {
    Text = "<Big:Aaah——!!>"
  },
  AvgDialog_149757_Content_21 = {
    Text = "Kata-kata yang kacau balau terpotong oleh jeritan menyayat, seolah ditusuk tombak tepat di dada, ia terhuyung dan jatuh berlutut, namun bayangan di belakangnya masih berdiri di tempat, bagai baju besi, bagai penjara."
  },
  AvgDialog_149757_Content_22 = {
    Text = "Kamu merasakan kepanikan, kamu tahu bahwa jika tidak segera dihentikan, bayangan itu akan menjadi manusia, sementara manusia itu akan jatuh menjadi bayangan."
  },
  AvgDialog_149757_Content_23 = {
    Text = "Cepat sadar! Jangan dengarkan ia berbicara lagi, putrimu ada di sini!!"
  },
  AvgDialog_149757_Content_24 = {
    Text = "<Shake:…@1@2Paduka Putri… apakah hamba mengecewakan Anda?>"
  },
  AvgDialog_149757_Content_25 = {
    Text = "<Shake:Hamba tidak melarikan diri, Andalah yang menyuruh hamba—>Tidak, bukan itu maksudku, akulah yang mengkhianatimu, aku tidak berhak memohon pengampunan."
  },
  AvgDialog_149757_Content_26 = {
    Text = "<Shake:Aib… aib aib aib aib aib aib aib aib, aib adalah satu-satunya yang kumiliki…>"
  },
  AvgDialog_149757_Content_27 = {
    Text = "<Shake:Aku bukan ksatria, aku adalah… aku adalah…>"
  },
  AvgDialog_149757_Content_28 = {
    Text = "<Red:Siapa?>"
  },
  AvgDialog_149757_Content_29 = {
    Text = "Di saat kebingungan melandanya, ia mengangkat wajah menatapmu — jika itu masih bisa disebut wajah."
  },
  AvgDialog_149757_Content_3 = {
    Text = "Jika sampai kehilangan nama, entah dilupakan sendiri atau dilupakan orang lain, ibarat domba yang tersesat dari kawanannya, kehilangan perlindungan, akan diincar oleh iblis."
  },
  AvgDialog_149757_Content_30 = {
    Text = "Bayangan menggerogoti daging dan kulit, meninggalkan bekas seperti jejak siput yang merayap, wajahnya berbercak dan membusuk, namun dari luka-luka itu mengalir lumpur hitam pekat."
  },
  AvgDialog_149757_Content_31 = {
    Text = "Ia menunggu jawaban dari siapa? Hujan dingin membekukan bibir dan lidahmu, kau berdiri kaku di tengah lumpur, anggota tubuhmu gemetar terlambat."
  },
  AvgDialog_149757_Content_32 = {
    Text = "…T, tunggu, aku tahu! Kau adalah—"
  },
  AvgDialog_149757_Content_33 = {
    Text = "<BigShake:Jangan! Ogier!!>"
  },
  AvgDialog_149757_Content_34 = {
    Text = "Lumpur hitam menyembur dari dadanya, ksatriamu menghabiskan seluruh kekuatannya dalam keheningan, ia roboh tak berdaya, bagaikan cangkang yang ditinggalkan, bayangan mengelilinginya, tertawa sekaligus menangis."
  },
  AvgDialog_149757_Content_35 = {
    Text = "Kau menyaksikan bagaimana seseorang hancur berkeping-keping."
  },
  AvgDialog_149757_Content_36 = {
    Text = "Ogier! Kau adalah Ogier! Aku tahu, aku mengingatnya! Iblis tidak bisa menyakitimu, aku sudah mengingatnya!"
  },
  AvgDialog_149757_Content_37 = {
    Text = "Bangun! Dengar? Cepat bangun, kita belum sampai! Kau akan baik-baik saja, Pulau Apel, iblis tidak bisa pergi ke sana, sesampainya di Pulau Apel semuanya akan baik-baik saja! Bangkit, cepat bangkit!"
  },
  AvgDialog_149757_Content_38 = {
    Text = "Hujan deras mengubah hutan menjadi rawa yang membusuk, kau berteriak sekuat tenaga, menyeret, menangis, hanya membuat dirimu semakin terperosok. Kau tidak tahu ke mana lagi bisa melarikan diri."
  },
  AvgDialog_149757_Content_39 = {
    Text = "Rupanya inilah penyebab kematian dunia… dikubur hidup-hidup oleh keputusasaan."
  },
  AvgDialog_149757_Content_4 = {
    Text = "Mungkin ksatriamu sama sepertimu, dirampas segalanya oleh monster, bahkan ia kehilangan lebih banyak darimu, sampai-sampai namanya pun tak tersisa."
  },
  AvgDialog_149757_Content_40 = {
    Text = "<SmallShake:Batuk… batuk batuk…>"
  },
  AvgDialog_149757_Content_41 = {
    Text = "<SmallShake:Tunggu hujan reda… pergi ke pemakaman…>"
  },
  AvgDialog_149757_Content_42 = {
    Text = "Ogier! Kau masih hidup!"
  },
  AvgDialog_149757_Content_43 = {
    Text = "Tidak, pergi ke pemakaman untuk apa? Kau, kau sebenarnya masih hidup atau tidak?"
  },
  AvgDialog_149757_Content_44 = {
    Text = "<Shake:Pergi ke pemakaman… menguburkan… tidak ada waktu lagi… harus pergi menguburkan…>"
  },
  AvgDialog_149757_Content_45 = {
    Text = "Siapa? Kau ingin menguburkan siapa?"
  },
  AvgDialog_149757_Content_47 = {
    Text = "Ia tak lagi bersuara, memandang lurus ke atas, ke ujung semua rawa, tempat segala kenangan dan kelupaan akan larut, hujan turun dari sana, membuat udara semakin tipis."
  },
  AvgDialog_149757_Content_48 = {
    Text = "Namun kalian bagaimanapun tak bisa mencapai langit, maka hanya bisa berjalan menuju pemakaman. Di sanalah tempat yang paling dekat dengan ujung."
  },
  AvgDialog_149757_Content_49 = {
    Text = "Hanya untuk sebidang tanah kosong, ternyata harus mengeluarkan uang sebanyak ini…"
  },
  AvgDialog_149757_Content_5 = {
    Text = "Maka <Red:iblis> yang mengintai pun menampakkan cakar-cakarnya."
  },
  AvgDialog_149757_Content_50 = {
    Text = "Seandainya kau tahu lebih awal betapa mahalnya tempat para monster mengubur diri mereka sendiri, kau pasti tidak akan datang."
  },
  AvgDialog_149757_Content_51 = {
    Text = "Hujan turun terus selama tiga hari, akhirnya berhenti sejenak, ksatriamu terluka parah dalam pertarungan melawan iblis, sehingga hanya bisa menyuruhmu datang ke pemakaman menggantikannya, mengubur bungkusan yang selalu ia bawa. Katanya itu adalah peninggalan seseorang."
  },
  AvgDialog_149757_Content_52 = {
    Text = "Batu nisan itu kosong melompong, tanpa nama, kau tidak tahu untuk siapa ia didirikan."
  },
  AvgDialog_149757_Content_53 = {
    Text = "Lilin, sisir, patung kecil dari batu, perkamen…"
  },
  AvgDialog_149757_Content_54 = {
    Text = "Bungkusan itu ringan, isinya tidak banyak, namun semuanya rusak parah. Kau sudah memeras otak pun tak menemukan jawaban, ksatriamu pun bagaikan lembaran kosong bagimu, kau tidak tahu apa-apa tentang dirinya."
  },
  AvgDialog_149757_Content_55 = {
    Text = "…bahkan piala suci pun harus ikut dikubur?"
  },
  AvgDialog_149757_Content_56 = {
    Text = "Hei, bocah kecil di sana, kau dari keluarga mana? Apa yang kau lakukan sembunyi-sembunyi di sini?"
  },
  AvgDialog_149757_Content_57 = {
    Text = "Monster-monster berbaju zirah berjalan melewati pemakaman, salah satunya tiba-tiba berhenti, lalu seluruh barisan pun berhenti. Mereka berbaris rapi, satu sama lain tak ada bedanya, seperti seekor kelabang besar yang berbuku-buku."
  },
  AvgDialog_149757_Content_58 = {
    Text = "Telingamu tuli? Kutanya kau dari mana— hei, mau lari ke mana? Tangkap dia!"
  },
  AvgDialog_149757_Content_59 = {
    Text = "Lepaskan! Lepaskan aku! Aku tidak melakukan apa-apa, tanah ini sudah kubeli!"
  },
  AvgDialog_149757_Content_6 = {
    Text = "Di mana… di mana… bukankah ini arahnya?"
  },
  AvgDialog_149757_Content_60 = {
    Text = "Kau beli? Ha, kalau begitu jelaskan, di batu nisannya saja tidak ada nama, ini makam siapa?"
  },
  AvgDialog_149757_Content_61 = {
    Text = "Saya, saya..."
  },
  AvgDialog_149757_Content_62 = {
    Text = "Para tuan, ini adalah pemakaman Paroki, anak ini memang sudah membeli tanahnya, semuanya tercatat di buku registrasi."
  },
  AvgDialog_149757_Content_63 = {
    Text = "Soal nama, wabah sudah datang, setiap hari ada orang yang menghilang, apakah batu nisan tanpa nama itu masih kurang banyak?"
  },
  AvgDialog_149757_Content_64 = {
    Text = "Wajah para monster berubah, mereka saling berpandangan sebentar, lalu bergegas pergi, seolah takut tertular sesuatu. Kau melihat rasa takut yang familiar di mata-mata itu."
  },
  AvgDialog_149757_Content_65 = {Text = "Wabah?"},
  AvgDialog_149757_Content_66 = {
    Text = "Ya, wabah yang kejam, wabah yang mengerikan. Membuat manusia lupa, hanya butuh sedikit waktu, membuat batu lupa, namun butuh mengubah batu menjadi pasir."
  },
  AvgDialog_149757_Content_67 = {
    Text = "Batu-batu yang terlupa semakin banyak, orang tua menjadi kosong seperti anak kecil, kita tidak lagi memiliki cerita."
  },
  AvgDialog_149757_Content_68 = {
    Text = "Kau… kau tidak merasa ini adalah kutukan? Karena penyihir, atau hal lain."
  },
  AvgDialog_149757_Content_69 = {
    Text = "Kutukan, wabah, hukuman Tuhan, atau balas dendam ksatria kematian, apa bedanya? Kita tidak berdaya, nak, kita hanya bisa menatap saat ini, saat ini adalah segalanya yang bisa kita miliki, selalu begitu."
  },
  AvgDialog_149757_Content_7 = {
    Text = "Malam tanpa bulan begitu gelap, apalagi hutan lebat yang tak terlihat dasarnya, kamu memeluk Lentera di dadamu, mencari-cari ke segala penjuru mengikuti jejak pelarian yang tergesa-gesa."
  },
  AvgDialog_149757_Content_70 = {
    Text = "Pulanglah, sebentar lagi hari akan gelap."
  },
  AvgDialog_149757_Content_71 = {
    Text = "Tunggu, ksatria kematian? Apa itu?"
  },
  AvgDialog_149757_Content_72 = {
    Text = "Sebuah legenda. Perang itu adalah sebuah kesalahan, mereka berseru ingin membasmi wabah, namun justru membuat wabah datang lebih cepat, mereka menciptakan sebuah monster."
  },
  AvgDialog_149757_Content_73 = {
    Text = "Ia bersembunyi di balik bayangan pohon, kapal, tembok batu, dan burung yang terbang, berpindah dari satu tempat ke tempat lain, bahkan sinar matahari pun tak mampu menyentuhnya."
  },
  AvgDialog_149757_Content_74 = {
    Text = "Darahnya hitam pekat, jantungnya membakar dengan api suram, matanya adalah cahaya di kedalaman rawa, di mana pun ia melangkah, akan tertinggal bayangan yang membelah siang."
  },
  AvgDialog_149757_Content_75 = {
    Text = "Ia adalah kelanjutan dari perang itu, kumpulan dendam para arwah, hanya muncul di malam hari untuk membantai musuh-musuhnya. Ia tidak pernah melupakan, tidak pernah lengah, alasan kedatangannya sudah jelas, tuan kita, negeri yang pernah menjadi miliknya."
  },
  AvgDialog_149757_Content_76 = {
    Text = "Apa? Maksudmu, tuan adalah musuhnya, dan ia datang ke sini… untuk membalas dendam?"
  },
  AvgDialog_149757_Content_77 = {
    Text = "Tentu saja, kita semua tahu, tuan pun tahu. Kalau tidak, mengapa tiba-tiba ada begitu banyak prajurit patroli di kota?"
  },
  AvgDialog_149757_Content_78 = {
    Text = "Mereka semua sedang menunggunya."
  },
  AvgDialog_149757_Content_79 = {
    Text = "Hujan kembali turun, jalanan seolah menjadi sungai yang mengalir."
  },
  AvgDialog_149757_Content_8 = {
    Text = "Sebelum ditelan bayangan, ia menyuruhmu pergi, tapi bagaimana mungkin seorang putri tanpa ksatrianya? Kamu berusaha menyelamatkannya, namun ia melepas tanganmu, mendobrak jendela dan melompat dari loteng, lenyap ke dalam hutan liar di luar perkebunan."
  },
  AvgDialog_149757_Content_80 = {
    Text = "Kau memeluk semua peninggalan itu di dadamu, berlari sekencang mungkin melewati gang-gang sempit, dengan susah payah menghindari regu demi regu penjaga, langsung menuju gubuk jerami tempat kalian bersembunyi."
  },
  AvgDialog_149757_Content_81 = {
    Text = "<Shake:Cepat, cepat kembali dan beritahu dia…>"
  },
  AvgDialog_149757_Content_82 = {
    Text = "Monster di antara para monster, tidak diragukan lagi itu adalah ksatriamu, pembunuhan terang-terangannya akhirnya sampai ke telinga tuan, kabarnya malam ini para penjaga akan menggeledah setiap sudut kota."
  },
  AvgDialog_149757_Content_83 = {
    Text = "Masih ada waktu, gerbang kota belum ditutup, asalkan sedikit lebih cepat…"
  },
  AvgDialog_149757_Content_84 = {
    Text = "<Big:Ogier! Cepat pergi, mereka akan datang—>"
  },
  AvgDialog_149757_Content_85 = {
    Text = "Gubuk sempit itu berdiri di ujung gang buntu, sekelilingnya ditumpuk karung goni, namun tetap tak mampu menahan lumpur yang mengalir. Kau menerobos menuju sosok yang terbaring di sudut paling dalam, menarik jubahnya dengan sekali sentakan — yang tertarik hanyalah sebuah jubah."
  },
  AvgDialog_149757_Content_86 = {
    Text = "Di dalam gubuk selain jerami tidak ada apa-apa lagi, ksatriamu sudah tidak tampak bayangannya."
  },
  AvgDialog_149757_Content_9 = {
    Text = "Hujan deras menutupi ranting-ranting yang patah dan jejak kaki yang tersisa, pemandangan di sekitar tampak serupa semua, langkahmu semakin melambat, hingga akhirnya kamu berhenti dengan bingung."
  },
  AvgDialog_15363_Content_1 = {
    Text = "Matinya Ny. Coral"
  },
  AvgDialog_15363_Content_10 = {
    Text = "Orang-orang mengerumuninya hingga tak ada celah, kilatan lampu kamera menyala serentak, suara diskusi riuh bersahut-sahutan, hingga seorang staf menyibak kain penutupnya."
  },
  AvgDialog_15363_Content_11 = {
    Text = "Ini... ya Tuhan."
  },
  AvgDialog_15363_Content_12 = {
    Text = "...Tak bisa dipercaya."
  },
  AvgDialog_15363_Content_13 = {
    Text = "Seolah ada saklar yang terpicu, kerumunan otomatis terdiam, aula yang tadinya ramai dan hiruk-pikuk kini terasa begitu sunyi."
  },
  AvgDialog_15363_Content_14 = {
    Text = "Kamu susah payah menerobos kerumunan, akhirnya melihat karya yang dikelilingi di tengah."
  },
  AvgDialog_15363_Content_16 = {
    Text = "Itu Shan. Dia telah menanggalkan seluruh warna dan emosinya, berubah menjadi patung karang putih murni."
  },
  AvgDialog_15363_Content_17 = {
    Text = "Cahaya terang menembus kubah kaca yang jernih, membiaskan sinarnya ke tubuhnya, menyelimutinya dengan cahaya lembut keemasan."
  },
  AvgDialog_15363_Content_18 = {
    Text = "Kamu menunduk menatap label kuningan di alas patung, di atasnya terukir nama patung dengan huruf yang indah: <Red:\"Gadis Karang Tak Bernama\">."
  },
  AvgDialog_15363_Content_19 = {
    Text = "Karang tak bernama..."
  },
  AvgDialog_15363_Content_2 = {
    Text = "Yang terhormat Tuan Claudel:\n\nBanyak hal terjadi belakangan ini, mohon maafkan kelalaianku dalam membalas surat.\n\nSetelah Nona Shan pergi, Tuan Auguste tidak pernah lagi menghasilkan karya yang memukau.\nDi bawah tekanan opini publik, dia mengumumkan penghentian karier pahatannya tanpa batas waktu.\nDia mendapat hukuman yang setimpal, namun aku tidak bisa merasa senang—<Yellow:Nona Shan masih tidak diketahui keberadaannya.>"
  },
  AvgDialog_15363_Content_20 = {
    Text = "Kamu menatap deretan huruf itu dengan terpaku, kesadaranmu seolah ikut bergoyang dan terdistorsi bersama garis-garis indah itu..."
  },
  AvgDialog_15363_Content_21 = {
    Text = "Mengangkat tangan untuk mengucek mata, namun mendapati jari-jarimu entah sejak kapan mulai dipenuhi lapisan kasar berwarna putih pudar."
  },
  AvgDialog_15363_Content_22 = {Text = "?!"},
  AvgDialog_15363_Content_23 = {
    Text = "Kabut karang putih terus merambat dari sela-sela jari, perlahan menutupi seluruh tubuhmu, dengan cepat memenuhi seluruh ruang pameran, lalu—"
  },
  AvgDialog_15363_Content_24 = {Text = "——!!"},
  AvgDialog_15363_Content_25 = {
    Text = "Kamu dan ruang pameran pecah menjadi serpihan putih tak terhitung secara bersamaan, berjatuhan ke kedalaman lautan tanpa batas."
  },
  AvgDialog_15363_Content_26 = {
    Text = "Di tengah patung-patung putih dan karang yang tak terhitung, di bawah cahaya pagi yang tenang, reruntuhan istana putih menjulang megah."
  },
  AvgDialog_15363_Content_27 = {
    Text = "Ikan-ikan berwarna-warni berenang melintas di antara gerbang lengkung dan koridor reruntuhan yang miring, menikmati waktu senggang yang menyenangkan."
  },
  AvgDialog_15363_Content_28 = {
    Text = "Seluruh reruntuhan itu Seolah-olah tertinggal dalam bayangan waktu, jauh dari Corrosion dunia, menghindari gangguan kerumunan."
  },
  AvgDialog_15363_Content_29 = {
    Text = "Ketika kau telah melihat keajaiban-keajaiban itu... kau akan memahami aku..."
  },
  AvgDialog_15363_Content_3 = {
    Text = "<Yellow:Besok aku akan pergi ke Pameran Salon Cité, mencari \"jawaban\" yang Nona Shan sebutkan.>\nDoakan aku beruntung.\n\nCamille@1\nA.F.2@1 September"
  },
  AvgDialog_15363_Content_30 = {
    Text = "Inikah... keajaiban yang kau lihat, Nona Shan?"
  },
  AvgDialog_15363_Content_31 = {
    Text = "Kamu mengembara di air laut yang hangat, terpesona namun bingung menatap semua yang ada di hadapanmu."
  },
  AvgDialog_15363_Content_32 = {
    Text = "Minggir, biarkan aku lewat!!"
  },
  AvgDialog_15363_Content_33 = {
    Text = "<Big:Biarkan aku lewat!!>"
  },
  AvgDialog_15363_Content_34 = {
    Text = "Suara keributan yang bising menarikmu kembali ke kenyataan."
  },
  AvgDialog_15363_Content_35 = {
    Text = "Seorang pria tua berpakaian compang-camping menerobos barikade keamanan yang berlapis-lapis, menerjang ke arahmu dan mencengkeram tanganmu erat-erat."
  },
  AvgDialog_15363_Content_36 = {
    Text = "Kau juga melihatnya, kan? Laut dalam, istana, ilusi-ilusi aneh itu…"
  },
  AvgDialog_15363_Content_37 = {Text = "?!"},
  AvgDialog_15363_Content_38 = {
    Text = "Wanita jahat ini, dia seorang pencuri…"
  },
  AvgDialog_15363_Content_39 = {
    Text = "Pria tua itu terus bergumam tak jelas. Kau menatap wajah yang tersembunyi di balik topi lebar dan jenggot lebat itu, lalu tiba-tiba menyadari sesuatu."
  },
  AvgDialog_15363_Content_4 = {
    Text = "Pameran Salon Cité\nHari Pembukaan"
  },
  AvgDialog_15363_Content_40 = {
    Text = "…Tuan Auguste?!"
  },
  AvgDialog_15363_Content_41 = {
    Text = "Astaga, ternyata benar dia… Ya Tuhan! Bagaimana bisa dia jadi seperti ini?"
  },
  AvgDialog_15363_Content_42 = {
    Text = "Dia sudah lama bangkrut, kau belum dengar? Setelah kegagalan \"Muse Tragedi\", dia menghabiskan banyak uang untuk membuat beberapa karya, tapi sayangnya tak ada yang laku…"
  },
  AvgDialog_15363_Content_43 = {
    Text = "Pemerintah sekarang khawatir dengan reputasinya dan tidak lagi memberinya pesanan. Mungkin dia sudah gila karena terlalu banyak tekanan…"
  },
  AvgDialog_15363_Content_44 = {
    Text = "Orang-orang terkejut sekaligus ketakutan, memandang Auguste dari jarak yang tidak terlalu dekat maupun terlalu jauh."
  },
  AvgDialog_15363_Content_45 = {
    Text = "Auguste menghempaskan tanganmu. Dia berjalan terpincang-pincang menuju patung itu, matanya dipenuhi kebencian yang tak bisa lagi ditahan."
  },
  AvgDialog_15363_Content_46 = {
    Text = "Heh… Kau pikir dengan mati kau bisa menghapus semua yang telah kau lakukan?"
  },
  AvgDialog_15363_Content_47 = {
    Text = "Kau menipu semua orang… Bakat, inspirasi, dan reputasiku semuanya kau bawa pergi."
  },
  AvgDialog_15363_Content_48 = {
    Text = "Aku hancur, hancur total. Dan kau? Duduk santai di sini, menikmati tatapan kagum semua orang, menunggu mereka mengangkatmu sebagai sebuah mahakarya…"
  },
  AvgDialog_15363_Content_5 = {
    Text = "Sudah dengar? Tuan Auguste datang lagi memamerkan karya pahatannya."
  },
  AvgDialog_15363_Content_50 = {
    Text = "Menghadapi kutukan histeris dari mantan gurunya, patung itu berdiri diam membisu, ekspresi acuh tak acuhnya tak berkurang sedikit pun."
  },
  AvgDialog_15363_Content_51 = {
    Text = "Auguste tak bisa lagi menahan diri, dia menerjang patung itu dengan penuh kebencian."
  },
  AvgDialog_15363_Content_52 = {
    Text = "Lagi-lagi ekspresi seperti ini, lagi-lagi ejekan seperti ini…"
  },
  AvgDialog_15363_Content_53 = {
    Text = "Iblis… Iblis! <Big:Akan kurobek topengmu!>"
  },
  AvgDialog_15363_Content_6 = {
    Text = "Auguste, pematung itu? Bukankah dia menghilang setelah dituduh menjiplak? Kukira dia tidak akan punya muka untuk muncul lagi seumur hidupnya."
  },
  AvgDialog_15363_Content_7 = {
    Text = "Aku justru penasaran, tanpa murid perempuannya itu, karya apa yang masih bisa dia hasilkan sekarang……"
  },
  AvgDialog_15363_Content_8 = {
    Text = "Upacara pembukaan Pameran Salon dipenuhi lautan pengunjung."
  },
  AvgDialog_15363_Content_9 = {
    Text = "Karya Auguste ditempatkan di tengah ruang pameran, ditutupi kain penutup tebal berlapis-lapis, membangkitkan rasa penasaran banyak orang."
  },
  AvgDialog_15364_Content_1 = {Text = "Ugh!!"},
  AvgDialog_15364_Content_10 = {
    Text = "Pameran Salon Cité\nMalam Hari Pembukaan"
  },
  AvgDialog_15364_Content_11 = {
    Text = "Seiring jatuhnya gembok terakhir, ruang pameran tenggelam dalam kesunyian yang gelap gulita."
  },
  AvgDialog_15364_Content_12 = {
    Text = "Kau melangkah keluar dari bayang-bayang di sudut ruangan, dan sekali lagi berdiri di hadapannya."
  },
  AvgDialog_15364_Content_13 = {
    Text = "Tak ada hiruk-pikuk siang hari yang mengganggu di sini, saat yang tepat untuk berbicara."
  },
  AvgDialog_15364_Content_14 = {
    Text = "Nona Shan, Tuan Auguste hari ini dibawa pergi. Dia bilang……\nkau telah menipu semua orang."
  },
  AvgDialog_15364_Content_15 = {
    Text = "Apakah \"semua orang\" di sini juga termasuk aku?"
  },
  AvgDialog_15364_Content_17 = {
    Text = "Kau pernah berjanji akan pulang bersamaku. Apakah itu benar?"
  },
  AvgDialog_15364_Content_19 = {
    Text = "Patung itu tetap membisu. Meskipun kehidupan semua orang telah menyimpang karenanya, ia tak pernah menundukkan kedua matanya yang memandang ke kejauhan."
  },
  AvgDialog_15364_Content_2 = {
    Text = "Lepaskan aku, orang yang kalian cari itu dia, dia——"
  },
  AvgDialog_15364_Content_20 = {
    Text = "Cahaya bulan menembus jendela kaca ruang pameran, menyelimutinya dalam kabut cahaya putih yang samar."
  },
  AvgDialog_15364_Content_21 = {
    Text = "<Red:Ikuti arah pandanganku……>"
  },
  AvgDialog_15364_Content_22 = {
    Text = "Ikuti arah pandangan…… Jangan-jangan?!"
  },
  AvgDialog_15364_Content_23 = {
    Text = "Kamu berjinjit, baru menyadari bahwa di bawah sinar rembulan, kedua mata patung yang semula hampa dan tak terfokus telah berubah, mengkristal menjadi emosi yang nyata dan kuat."
  },
  AvgDialog_15364_Content_24 = {
    Text = "Dia selalu menatap ke kejauhan."
  },
  AvgDialog_15364_Content_25 = {
    Text = "Kamu berbalik mengikuti arah pandangannya."
  },
  AvgDialog_15364_Content_26 = {
    Text = "Dalam sekejap matamu bergulir, ruang pameran di bawah kakimu lenyap secara ajaib."
  },
  AvgDialog_15364_Content_27 = {
    Text = "Tergantikan oleh lautan tak bertepi dan pantai berpasir putih yang membentang luas."
  },
  AvgDialog_15364_Content_28 = {
    Text = "Dari kejauhan terdengar gemuruh guntur yang bergemuruh, ombak bergelora hebat, menerjang ke arahmu."
  },
  AvgDialog_15364_Content_29 = {
    Text = "Ini adalah lautan yang pernah kamu kunjungi bersama Shan."
  },
  AvgDialog_15364_Content_3 = {
    Text = "Tuan Auguste, kami menerima laporan bahwa tindakan Anda telah menyebabkan gangguan serius terhadap ketertiban pameran salon. Sekarang silakan ikut kami."
  },
  AvgDialog_15364_Content_4 = {
    Text = "Tidak, tidak……"
  },
  AvgDialog_15364_Content_5 = {
    Text = "Suasana begitu kacau, arus orang yang berdatangan dari segala penjuru benar-benar memisahkanmu dari Auguste. Kau hanya bisa menyaksikannya diseret paksa oleh para polisi."
  },
  AvgDialog_15364_Content_6 = {
    Text = "Jangan senang dulu kalian…… Suatu hari nanti, kalian akan bernasib sama sepertiku……"
  },
  AvgDialog_15364_Content_7 = {
    Text = "Heh…… heheheh……"
  },
  AvgDialog_15364_Content_8 = {
    Text = "Ruang pameran akhirnya kembali tertib."
  },
  AvgDialog_15364_Content_9 = {
    Text = "Tawa gemetar dan neurotis terakhir Auguste bagaikan riak yang perlahan memudar, sayup-sayup bergema di ruang pameran yang luas."
  },
  AvgDialog_15365_Content_1 = {
    Text = "Di Tengah Lautan"
  },
  AvgDialog_15365_Content_10 = {
    Text = [[
Ternyata memang kau.
Maaf, apakah aku membangunkanmu saat bangun di malam hari?]]
  },
  AvgDialog_15365_Content_11 = {
    Text = "Daripada mengkhawatirkan membangunkanku, sebaiknya kau lebih khawatir apakah kau akan membangunkan <Blue:para penghuni tua yang tidur di bawah tanah> itu."
  },
  AvgDialog_15365_Content_12 = {
    Text = "Kau mengangkat dagumu, menunjuk ke makam di hadapannya yang sudah digali sedalam hampir satu kaki."
  },
  AvgDialog_15365_Content_13 = {
    Text = "Kamu sepertinya sedang mencari sesuatu, perlu bantuan?"
  },
  AvgDialog_15365_Content_14 = {
    Text = "Tidak apa-apa, aku sudah menemukannya."
  },
  AvgDialog_15365_Content_15 = {
    Text = "Shan tersenyum lebar sambil membuka telapak tangannya ke arahmu, di atasnya penuh dengan cairan hitam pekat yang lengket—"
  },
  AvgDialog_15365_Content_16 = {
    Text = "Itu adalah cairan Peleburan. Kamu sudah sangat familiar dengannya."
  },
  AvgDialog_15365_Content_17 = {
    Text = "Lihat? Di bawah cahaya bulan, mereka memancarkan warna biru yang aneh. Di siang hari, mereka berubah menjadi bentuk yang lain…"
  },
  AvgDialog_15365_Content_18 = {
    Text = "Ini adalah bahan pahatan paling sempurna yang pernah kulihat."
  },
  AvgDialog_15365_Content_2 = {
    Text = [[
Yang terhormat Tuan Claudel:

Nona Shan tidak menolak permintaan untuk pulang, tetapi dia berharap saya bisa memberinya sedikit waktu.
Dia berkata: <Yellow:Setelah pameran Salon selesai, aku bisa pulang.>

Meskipun demikian, kondisi Nona Shan belakangan ini cukup mengkhawatirkan.
Setiap larut malam dia diam-diam pergi, dan baru kembali menjelang subuh.]]
  },
  AvgDialog_15365_Content_20 = {
    Text = "Kamu menyelinap keluar setiap malam hanya untuk mengumpulkan cairan Peleburan di sini?"
  },
  AvgDialog_15365_Content_21 = {
    Text = "Kamu tahu nama mereka? Kamu sangat memahami mereka."
  },
  AvgDialog_15365_Content_22 = {
    Text = "Ini… bukan sesuatu yang langka, di Besançon cukup banyak."
  },
  AvgDialog_15365_Content_23 = {
    Text = "Oh begitu… Aku kira ini adalah penemuan indah yang hanya milikku seorang."
  },
  AvgDialog_15365_Content_24 = {
    Text = "Peleburan (Dissolution)… nama yang benar-benar tepat."
  },
  AvgDialog_15365_Content_25 = {
    Text = "Sekarang bukan waktunya bercanda, Shan."
  },
  AvgDialog_15365_Content_26 = {
    Text = "Kamu bisa mati. Ini bukan sesuatu yang boleh disentuh oleh orang biasa seperti kita."
  },
  AvgDialog_15365_Content_27 = {
    Text = "Aku mengerti, tentu saja aku mengerti… Keindahan pasti mendatangkan bahaya."
  },
  AvgDialog_15365_Content_28 = {
    Text = [[
Tapi sebaliknya, bukankah bahaya itu sendiri juga merupakan sebuah keindahan?
Bagiku, kematian bukanlah hal yang menakutkan.]]
  },
  AvgDialog_15365_Content_29 = {
    Text = "Yang benar-benar menakutkan adalah…"
  },
  AvgDialog_15365_Content_3 = {
    Text = "Anehnya, kebiasaan tidur siang dan keluar malam yang terus-menerus ini justru membuatnya penuh energi,\nbahkan Tuan Auguste pun puas dengan efisiensi kerjanya belakangan ini.\n\n<Yellow:Dia menjadi begitu asing.>\n\nBeberapa malam, aku terbangun dari mimpi buruk, dan melihatnya berdiri begitu saja di samping tempat tidur……\nDia menatapku tanpa berkedip, matanya penuh dengan hal-hal menakutkan yang tidak bisa kupahami."
  },
  AvgDialog_15365_Content_30 = {
    Text = "Semilir angin berhembus lembut, menelan kata-kata Shan selanjutnya. Entah sejak kapan bulan menyembul dari balik awan gelap yang berlapis-lapis, menyiramkan cahaya bulan yang dingin ke atas kalian berdua."
  },
  AvgDialog_15365_Content_31 = {
    Text = "Kemudian kamu melihat bekas luka di leher Shan."
  },
  AvgDialog_15365_Content_32 = {
    Text = "Mereka seperti tentakel karang, terus merambat ke atas, berkilauan dengan cahaya dingin biru keabu-abuan di sela-sela pergerakan cahaya bulan."
  },
  AvgDialog_15365_Content_33 = {
    Text = "Nona Shan, kamu sudah terinfeksi…?!"
  },
  AvgDialog_15365_Content_34 = {
    Text = "Meski tahu ini hanyalah mimpi, hatimu tetap tertusuk sakit sesaat."
  },
  AvgDialog_15365_Content_35 = {
    Text = "Bagaimanapun, kini kau memiliki seluruh ingatan dan emosi pemilik tubuh asli. Pelayan dari pedesaan Besançon ini memiliki kasih sayang yang mendalam terhadap nyonya mudanya."
  },
  AvgDialog_15365_Content_36 = {
    Text = "Apakah ini karena Tuan Auguste? Kata-katanya memberimu tekanan yang terlalu besar, jadi……"
  },
  AvgDialog_15365_Content_37 = {
    Text = "Shan menggelengkan kepalanya."
  },
  AvgDialog_15365_Content_38 = {
    Text = [[
Dari awal hingga akhir, hal ini sama sekali tidak ada hubungannya dengan dia.
Ayo, kuajak kau ke suatu tempat.]]
  },
  AvgDialog_15365_Content_39 = {
    Text = "Akhirnya sampai — markas rahasiaku."
  },
  AvgDialog_15365_Content_4 = {
    Text = [[
<Yellow:Aku memutuskan untuk diam-diam mengikutinya malam ini, untuk melihat apa sebenarnya yang dia lakukan.>
Doakan aku beruntung.

Camille@1
A.F.2@1 September]]
  },
  AvgDialog_15365_Content_40 = {
    Text = "Ini adalah sebuah gudang terbengkalai di tepi laut, di dalamnya terpajang banyak patung latihan dengan pose beragam yang sangat aneh dan terdistorsi."
  },
  AvgDialog_15365_Content_41 = {
    Text = "Karang, cangkang keong, tentakel, serta bangunan dan makhluk yang diukir dengan pola-pola aneh…… Satu-satunya kesamaan mereka adalah hubungan erat dengan lautan."
  },
  AvgDialog_15365_Content_42 = {
    Text = "Tekstur patung-patung ini……"
  },
  AvgDialog_15365_Content_43 = {
    Text = "Bukan marmer, juga tidak seperti granit. Dari mana kau menemukannya?"
  },
  AvgDialog_15365_Content_44 = {
    Text = "Shan mengedipkan mata padamu dengan nakal."
  },
  AvgDialog_15365_Content_45 = {
    Text = "Itu rahasiaku. Suatu hari nanti kau akan tahu."
  },
  AvgDialog_15365_Content_46 = {
    Text = "Di tengah pondok kayu berdiri sebuah patung berbentuk manusia yang belum selesai."
  },
  AvgDialog_15365_Content_47 = {
    Text = "Tubuhnya terbungkus dalam Tentacle yang mengerikan, terpelintir pada sudut yang tidak masuk akal. Pembuluh darah di lehernya menegang, Seolah-olah seekor ular yang meliuk-liuk."
  },
  AvgDialog_15365_Content_48 = {
    Text = [[
Indah, bukan?
Mereka semua memanggilku "Si Jagal", karena aku selalu kejam tanpa ampun terhadap model.]]
  },
  AvgDialog_15365_Content_49 = {
    Text = "Tapi justru karena itulah, aku bisa menangkap esensi yang tersembunyi di balik daging dan kulit — yang penuh lilitan dan penderitaan."
  },
  AvgDialog_15365_Content_5 = {
    Text = "September di Cité sudah diterpa angin dingin yang menusuk.\nKau berjalan tanpa suara di jalanan, berusaha menyembunyikan dirimu dalam bayang-bayang."
  },
  AvgDialog_15365_Content_50 = {
    Text = "Sementara guruku selalu berhati-hati dalam memperlakukan model, maka dari itu dia hanya bisa menjadi pematung kelas dua."
  },
  AvgDialog_15365_Content_51 = {
    Text = "Kau memandang patung di hadapanmu. Tak diragukan lagi ia indah, namun juga kejam."
  },
  AvgDialog_15365_Content_52 = {
    Text = "Apakah ini karya yang akan kau bawa ke pameran?"
  },
  AvgDialog_15365_Content_53 = {
    Text = "Shan menggelengkan kepalanya."
  },
  AvgDialog_15365_Content_54 = {
    Text = "Hanya beberapa latihan saja. Sebelum menemukan cairan…… pelarut itu, pemahamanku tentang seni pahat masih sangat dangkal."
  },
  AvgDialog_15365_Content_55 = {
    Text = "Diriku yang sekarang bagaikan bayi yang baru membuka mata, dipaksa untuk mengenal kembali dunia di hadapanku……"
  },
  AvgDialog_15365_Content_56 = {
    Text = "<Yellow:Dan mengenalmu kembali.>"
  },
  AvgDialog_15365_Content_57 = {Text = "Aku……?"},
  AvgDialog_15365_Content_58 = {
    Text = "Ya, kamu. Dari mata dan ekspresimu, aku melihat kemungkinan baru."
  },
  AvgDialog_15365_Content_59 = {
    Text = "Shan dengan lembut menelusuri kontur wajahmu menggunakan jari-jarinya."
  },
  AvgDialog_15365_Content_6 = {
    Text = [[
Sosok kurus Shan ada di depan sana.
Jarak di antara kalian tidak terlalu jauh dan tidak terlalu dekat, seolah dihubungkan oleh seutas benang tak kasat mata.]]
  },
  AvgDialog_15365_Content_60 = {
    Text = "Berbeda dari nona-nona lain yang hidup bermewah-mewahan, ujung jarinya memiliki lapisan kapalan tipis, memberikan tekstur kasar yang khas."
  },
  AvgDialog_15365_Content_61 = {
    Text = "Kamu ketakutan. Tenang saja, aku tidak akan memaksamu melakukan apa pun."
  },
  AvgDialog_15365_Content_62 = {
    Text = "Masih ingat waktu kecil dulu?"
  },
  AvgDialog_15365_Content_63 = {
    Text = "Waktu kecil?"
  },
  AvgDialog_15365_Content_64 = {
    Text = "Kamu mengikuti alur kata-katanya, terus menyelami dan menjelajahi pikiran kacau sang pemilik tubuh asli……"
  },
  AvgDialog_15365_Content_65 = {
    Text = "Akhirnya berhenti di musim panas yang remang dan kabur itu."
  },
  AvgDialog_15365_Content_66 = {
    Text = "Tentu saja ingat. Saat umur 5 tahun, kamu sudah bisa membentuk kerangka manusia dari tanah liat."
  },
  AvgDialog_15365_Content_67 = {
    Text = "Aku pergi ke pantai untuk mencarikanmu berbagai macam bahan, dan Tuan Muda Paul Claudel bertugas melemparkan model-model itu ke dalam tungku untuk dibakar."
  },
  AvgDialog_15365_Content_68 = {
    Text = "Ya, itu adalah rahasia kecil kita bertiga."
  },
  AvgDialog_15365_Content_69 = {
    Text = "Suatu kali ketahuan oleh ayah, kamu menanggung semua kesalahan sendirian, dan dihukum berdiri semalaman."
  },
  AvgDialog_15365_Content_7 = {
    Text = "Benang itu membawa kalian melewati gedung demi gedung, menembus embun beku yang panjang dan suram, hingga akhirnya tiba di tujuan bersama kalian—"
  },
  AvgDialog_15365_Content_70 = {
    Text = "Mata kelabu Shan diselimuti kabut tipis kesedihan."
  },
  AvgDialog_15365_Content_71 = {
    Text = "Dia memelukmu dengan lembut."
  },
  AvgDialog_15365_Content_72 = {
    Text = "Kalian berdua adalah keluargaku selamanya. Paul yang menyuruhmu mencariku, kan?"
  },
  AvgDialog_15365_Content_73 = {
    Text = "Ya. Tuan Muda dia…… sedang sakit, tidak bisa datang sendiri."
  },
  AvgDialog_15365_Content_74 = {
    Text = [[
Kamu bernapas pelan di lekuk leher Shan, hidungmu dipenuhi aroma tubuhnya.
Aroma ombak laut yang memabukkan.]]
  },
  AvgDialog_15365_Content_75 = {
    Text = "Tenang saja. Karena aku sudah berjanji akan pulang bersamamu, aku tidak akan mengingkarinya."
  },
  AvgDialog_15365_Content_76 = {
    Text = "Tapi sebelum itu, aku harus meninggalkanmu."
  },
  AvgDialog_15365_Content_77 = {
    Text = "Meninggalkanku……? Kau mau pergi ke mana?"
  },
  AvgDialog_15365_Content_78 = {
    Text = "Shan tidak lagi berkata-kata, melainkan menoleh memandang lautan kelabu di luar rumah."
  },
  AvgDialog_15365_Content_79 = {
    Text = "Malam itu diselimuti kabut, ombak yang lembut bergulung pelan dengan irama yang tak pernah berubah sejak dahulu kala, seperti denyut nadi yang terdengar dari sisi leher Shan."
  },
  AvgDialog_15365_Content_8 = {
    Text = "Sebuah makam terbengkalai."
  },
  AvgDialog_15365_Content_80 = {
    Text = "Aku tidak tahu. Mungkin ke kedalaman lautan, atau mungkin ke @1……"
  },
  AvgDialog_15365_Content_81 = {
    Text = "Setelah hari itu, Nona Shan menghilang."
  },
  AvgDialog_15365_Content_82 = {
    Text = [[
Aku pergi ke semua tempat yang bisa kukunjungi, bertanya kepada semua orang yang bisa kutanyai, namun tak membuahkan hasil.

Dia pergi meninggalkan kami bagaikan angin.
Hingga sekarang, aku masih terus mengingat kembali malam itu di tepi laut.]]
  },
  AvgDialog_15365_Content_83 = {
    Text = "Saat itu, Nona Shan memelukku erat.\nDia kemudian mengatakan sesuatu lagi kepadaku, atau mungkin tidak, aku tidak tahu.\n\nIngatanku mulai menjadi kabur sejak hari itu.\n\n<Red:Karang putih, cangkang keong, istana bawah laut yang misterius……>\nHingga sekarang, bayangan-bayangan kacau ini terus menyiksa sarafku di kegelapan malam."
  },
  AvgDialog_15365_Content_84 = {
    Text = "<Yellow:\"Pergilah ke Pameran Salon untuk mencari jawabannya.\">\n\nBegitulah yang Nona Shan katakan kepadaku. Dia juga berkata—"
  },
  AvgDialog_15365_Content_85 = {
    Text = "Ketika kau telah melihat keajaiban-keajaiban itu, kau akan memahami diriku."
  },
  AvgDialog_15365_Content_86 = {
    Text = "Ikuti saja arah pandangku……"
  },
  AvgDialog_15365_Content_87 = {
    Text = "Aku berjanji kepadamu."
  },
  AvgDialog_15365_Content_9 = {Text = "Nona Shan."},
  AvgDialog_15367_Content_1 = {
    Text = "Minggir, jangan sentuh aku……!!"
  },
  AvgDialog_15367_Content_10 = {
    Text = "Aku tahu belakangan ini kau diam-diam membuat semacam <Yellow:studio> di luar sana, tapi kurasa aku perlu mengingatkanmu."
  },
  AvgDialog_15367_Content_11 = {
    Text = "Jangan berharap <Yellow:karya amatir yang menjijikkan dan tak senonoh> itu bisa mendapat perhatian para pejabat pemerintah."
  },
  AvgDialog_15367_Content_12 = {
    Text = "Kuakui kau sangat berbakat, dan sudah banyak membantu studio. Tapi berkarya seni di tempat seperti Cité, yang dibutuhkan jauh lebih dari sekadar bakat."
  },
  AvgDialog_15367_Content_13 = {
    Text = "Kalau kau membuatku marah……"
  },
  AvgDialog_15367_Content_14 = {
    Text = "Tuan Auguste, tolong jaga ucapan Anda."
  },
  AvgDialog_15367_Content_15 = {
    Text = "Tidak apa-apa, Camille."
  },
  AvgDialog_15367_Content_16 = {
    Text = "Shan menarikmu pelan dari belakang. Menghadapi cercaan Auguste, wajahnya tetap tenang seperti biasa."
  },
  AvgDialog_15367_Content_17 = {
    Text = "Dia berjongkok, memungut pecahan wajah patung itu satu per satu, lalu membuangnya ke tumpukan sampah di samping."
  },
  AvgDialog_15367_Content_18 = {
    Text = "Kalau membuat Anda marah, karya tidak bisa dipamerkan, tidak bisa dijual, sebagai seniman tidak akan pernah bisa maju, dan pada akhirnya……"
  },
  AvgDialog_15367_Content_19 = {
    Text = "Hanya akan mati kedinginan di jalanan, atau dikirim ke rumah sakit jiwa."
  },
  AvgDialog_15367_Content_2 = {
    Text = "Semua orang beramai-ramai menahan maestro dunia patung yang sudah murka luar biasa ini."
  },
  AvgDialog_15367_Content_20 = {
    Text = "Semua itu tentu saja sudah saya pahami betul, Guru."
  },
  AvgDialog_15367_Content_3 = {
    Text = "Jangan gegabah, guruku yang baik."
  },
  AvgDialog_15367_Content_4 = {
    Text = "Karya yang biasa-biasa saja seperti ini, yang dihancurkan bukan hanya suasana hatiku, tapi juga reputasi Anda."
  },
  AvgDialog_15367_Content_5 = {
    Text = "Heh……jangan sok pintar. Pameran Salon tinggal kurang dari setengah tahun lagi, kau bisa membuat sesuatu yang lebih baik dari udara kosong?"
  },
  AvgDialog_15367_Content_6 = {
    Text = "Satu bulan."
  },
  AvgDialog_15367_Content_7 = {Text = "……Apa?"},
  AvgDialog_15367_Content_8 = {
    Text = "Beri aku waktu satu bulan, aku pasti akan memberikan Anda sebuah <Yellow:kejutan> yang luar biasa."
  },
  AvgDialog_15367_Content_9 = {
    Text = "……Hmph."
  },
  AvgDialog_15368_Content_1 = {
    Text = "Semoga surat ini menemui Anda dalam keadaan baik"
  },
  AvgDialog_15368_Content_10 = {
    Text = "Pelipismu berdenyut-denyut. Kau mencoba menggerakkan tubuh, namun——"
  },
  AvgDialog_15368_Content_11 = {Text = "……!"},
  AvgDialog_15368_Content_12 = {
    Text = "<Shake:Kaki… mati rasa…>"
  },
  AvgDialog_15368_Content_13 = {
    Text = "Eh, apa ini hanya perasaanku? Saat kau membuka mata tadi, aku seperti melihat cahaya yang belum pernah kulihat sebelumnya."
  },
  AvgDialog_15368_Content_14 = {
    Text = "Tidak, bukan perasaanku saja. Ekspresimu juga berbeda…"
  },
  AvgDialog_15368_Content_15 = {
    Text = "Mata murid pemahat muda itu berkilau penuh semangat, ia tiba-tiba mendekatkan wajahnya padamu."
  },
  AvgDialog_15368_Content_16 = {
    Text = "Siapa kamu?"
  },
  AvgDialog_15368_Content_17 = {Text = "Pelayanmu"},
  AvgDialog_15368_Content_18 = {
    Text = "<Shake:A-aku ini pelayanmu, Camille@1, masa kau tidak ingat, haha…>"
  },
  AvgDialog_15368_Content_19 = {
    Text = "Kau mengingat baik-baik identitasmu."
  },
  AvgDialog_15368_Content_2 = {
    Text = "Yang terhormat Tuan Claudel:\n\nSaya telah tiba di Cité.\nBerbeda dengan ketenangan Besançon, tempat ini selalu dipenuhi kebisingan.\nLonceng, kereta kuda, dan hiruk-pikuk kerumunan orang…\nMembayangkan Nona Shan hidup di lingkungan seperti ini, saya merasa sangat gelisah."
  },
  AvgDialog_15368_Content_20 = {
    Text = "Kali ini, kau adalah pelayan yang tumbuh bersama Shan sejak kecil, diperintahkan oleh Tuan Muda Paul untuk membawa Shan pulang."
  },
  AvgDialog_15368_Content_21 = {
    Text = "\"Pastikan kau menyelamatkan jiwanya dari tangan iblis yang hanya bisa mengeksploitasi dan menjiplak karya orang lain.\""
  },
  AvgDialog_15368_Content_23 = {
    Text = "<Gray:Tidak, tidak benar……>"
  },
  AvgDialog_15368_Content_24 = {
    Text = "Kau mengingat baik-baik identitasmu."
  },
  AvgDialog_15368_Content_25 = {
    Text = "Kali ini, kamu adalah pelayan yang tumbuh bersama Shan sejak kecil, diperintahkan oleh Tuan Muda @1·Claudel untuk membawa Shan pulang."
  },
  AvgDialog_15368_Content_26 = {
    Text = "\"Kamu harus menyelamatkan jiwanya dari tangan iblis yang hanya bisa mengeksploitasi dan menjiplak karya bawahannya.\""
  },
  AvgDialog_15368_Content_27 = {
    Text = "A-aku adalah pelayanmu, Camille@1, masa kamu tidak ingat, haha……"
  },
  AvgDialog_15368_Content_28 = {
    Text = "<Shake:Sudah berpisah bertahun-tahun, kita semua sudah sedikit berbeda, bukan?>"
  },
  AvgDialog_15368_Content_3 = {
    Text = "Rumor sudah menyebar.\nOrang-orang mengatakan Nona Shan menghabiskan waktu bersama seorang pria yang 20 tahun lebih tua darinya, \"demi seni\".\nSungguh tidak masuk akal, besok saya akan pergi ke studio untuk mencari tahu kebenarannya.\n\nKali ini, saya pasti akan menyelesaikan amanat Anda——\n<Yellow:Membawa kakak Anda, Nona Shan kita, kembali ke Besançon.>\n\nCamille@1\nA.F.2@1 Agustus"
  },
  AvgDialog_15368_Content_30 = {
    Text = "Memang sangat berbeda, sekarang kamu jauh lebih hidup dibanding dulu.\nSeperti……tiba-tiba menjadi hidup saja."
  },
  AvgDialog_15368_Content_31 = {
    Text = "<Gray:Jadi ini yang namanya insting seniman, sepertinya aku harus lebih berhati-hati setelah ini.>"
  },
  AvgDialog_15368_Content_32 = {
    Text = "<Shake:Kalau tidak keberatan, bisakah kamu membantuku? Aku sekarang agak tidak bisa berdiri……>"
  },
  AvgDialog_15368_Content_33 = {
    Text = "Shan perlahan menggenggam tanganmu, secercah kekhawatiran melintas di matanya yang tenang tanpa riak."
  },
  AvgDialog_15368_Content_34 = {
    Text = "Maaf, tadi aku terlalu tenggelam dalam berkarya. Kamu pasti sangat tidak nyaman sekarang, biar kulihat."
  },
  AvgDialog_15368_Content_35 = {
    Text = "BRAAAK——!!"
  },
  AvgDialog_15368_Content_36 = {
    Text = "Pintu besar studio ditarik terbuka dengan kasar."
  },
  AvgDialog_15368_Content_37 = {
    Text = "Seorang pria tinggi besar dengan wajah muram melangkah masuk, diikuti beberapa wajah asing di belakangnya."
  },
  AvgDialog_15368_Content_38 = {
    Text = "Tanpa perlu mengakses ingatan pemilik tubuh asli, kamu langsung mengenalinya dari kumis khasnya—"
  },
  AvgDialog_15368_Content_39 = {
    Text = "Pematung termasyhur, <Blue:Auguste>."
  },
  AvgDialog_15368_Content_4 = {
    Text = "Nona Shan, kembalilah bersamaku. Di sini bahkan tidak ada tempat untuk menghangatkan diri——"
  },
  AvgDialog_15368_Content_40 = {
    Text = "Hingga saat ini, karya-karya patungnya masih dianggap sebagai mahakarya dan sangat diminati di lelang-lelang Londinium."
  },
  AvgDialog_15368_Content_41 = {
    Text = "Melihat tanganmu dan Shan yang saling bergenggaman, Auguste mengerutkan alisnya. Namun tak lama, perhatiannya segera tertarik oleh patung di hadapannya."
  },
  AvgDialog_15368_Content_42 = {
    Text = "Ini adalah……<Big:Mahakarya, mahakarya yang tak terbantahkan!>"
  },
  AvgDialog_15368_Content_43 = {
    Text = "Yang lainnya juga mengerumuni, memandang patung yang baru selesai dengan penuh rasa ingin tahu, sambil mengeluarkan decak kagum."
  },
  AvgDialog_15368_Content_44 = {
    Text = "Bagus, bagus sekali……Hubungi orang-orang di Departemen Kebudayaan, katakan bahwa karya untuk pameran Cité tahun ini sudah ada prospeknya."
  },
  AvgDialog_15368_Content_45 = {
    Text = "Aku sudah tidak sabar ingin melihat wajah terkejut para kritikus itu... Hahahaha!"
  },
  AvgDialog_15368_Content_46 = {
    Text = "Tawa riang Auguste bergema di studio yang luas. Dia mendorongmu menjauh, lalu menggenggam erat tangan Shan."
  },
  AvgDialog_15368_Content_47 = {
    Text = "Sudah kuduga kau tidak akan mengecewakan harapanku, Shan."
  },
  AvgDialog_15368_Content_48 = {
    Text = "Shan perlahan menarik tangannya, lalu berjalan pelan menuju patung itu."
  },
  AvgDialog_15368_Content_49 = {
    Text = "Mahakarya yang... tak terbantahkan?"
  },
  AvgDialog_15368_Content_5 = {
    Text = "Jangan bergerak, jangan bicara juga. Tetap seperti ini saja.\nYa, seperti ini…"
  },
  AvgDialog_15368_Content_50 = {
    Text = "Menurutmu bagaimana, Camille?"
  },
  AvgDialog_15368_Content_51 = {
    Text = "Eh, aku...?"
  },
  AvgDialog_15368_Content_52 = {
    Text = "Kau menatap patung di hadapanmu yang tampak hampir persis seperti \"dirimu\", lalu tenggelam dalam lamunan..."
  },
  AvgDialog_15368_Content_53 = {Text = "Biasa saja"},
  AvgDialog_15368_Content_54 = {
    Text = "Hmm, ekspresinya kaku, strukturnya berantakan, ketegangan kurang..."
  },
  AvgDialog_15368_Content_55 = {
    Text = "Kau berkomentar dengan gaya sok paham. Sebenarnya, kau selalu jauh dari dunia seni. Alasanmu berkata demikian hanyalah karena tidak suka melihat sikap Auguste yang semena-mena."
  },
  AvgDialog_15368_Content_56 = {
    Text = "Kau tidak menyukainya."
  },
  AvgDialog_15368_Content_57 = {
    Text = "Shan menatapmu sambil tersenyum, seperti seorang ibu penuh kasih sayang menghadapi ocehan seorang anak kecil."
  },
  AvgDialog_15368_Content_58 = {
    Text = "Hmm... Meskipun alasannya berbeda, tapi kesimpulan kita sama."
  },
  AvgDialog_15368_Content_59 = {Text = "Mahakarya!"},
  AvgDialog_15368_Content_6 = {
    Text = "Jadilah modelku dengan baik, biarkan aku menyelesaikan karya ini… setelah itu baru kita diskusikan soal pulang."
  },
  AvgDialog_15368_Content_60 = {
    Text = "Benar-benar tak tertandingi, aku tidak bisa menemukan kekurangan apa pun darinya."
  },
  AvgDialog_15368_Content_61 = {
    Text = "Kau, sama seperti yang lain, juga sepenuhnya terpesona oleh karya patung yang tampak bebas namun sebenarnya sangat presisi ini."
  },
  AvgDialog_15368_Content_62 = {
    Text = "Tentu saja, ini juga berkaitan dengan sirkulasi darahmu yang tidak lancar akibat mempertahankan pose yang sama dalam waktu lama."
  },
  AvgDialog_15368_Content_63 = {
    Text = "Otak yang kekurangan oksigen tidak bisa mengamati sesuatu dengan jernih, tapi pujian selalu tidak ada salahnya."
  },
  AvgDialog_15368_Content_64 = {
    Text = "Kau benar. Tidak bisa menemukan kekurangan, justru itulah masalah terbesarnya."
  },
  AvgDialog_15368_Content_65 = {
    Text = "Sekarang……apa yang harus kulakukan denganmu?"
  },
  AvgDialog_15368_Content_66 = {
    Text = "Shan menopang dagu sambil menatap patung di hadapannya. Kemudian dia mengulurkan jari telunjuknya, dan dengan santai menyentuh dahi patung itu——"
  },
  AvgDialog_15368_Content_67 = {
    Text = "BRAAAKK——!!"
  },
  AvgDialog_15368_Content_68 = {
    Text = "Patung itu meluncur dalam lengkungan yang indah, lalu roboh menghantam lantai."
  },
  AvgDialog_15368_Content_69 = {
    Text = "Camille——atau lebih tepatnya, wajahmu yang penuh kecemasan itu seketika pecah menjadi serpihan tak terhitung."
  },
  AvgDialog_15368_Content_7 = {Text = "Ini……?"},
  AvgDialog_15368_Content_71 = {
    Text = "Nona Claudel, kau sudah gila ya?!"
  },
  AvgDialog_15368_Content_72 = {
    Text = "Auguste dengan murka menerjang ke arah kalian."
  },
  AvgDialog_15368_Content_73 = {
    Text = "<Big:Ini marmer Pentelic yang paling murni, dari Paros——>"
  },
  AvgDialog_15368_Content_8 = {
    Text = "Sebuah ruangan yang berantakan."
  },
  AvgDialog_15368_Content_9 = {
    Text = "Berbagai patung dari tanite liat, marmer, dan granit diletakkan sembarangan, menjadikan tempat ini sebuah studio pahatan sederhana."
  },
  AvgDialog_15370_Content_1 = {
    Text = "Kepala Emas"
  },
  AvgDialog_15370_Content_10 = {
    Text = [[
Hujan semakin deras, tenggorokanmu semakin kering.
Di tengah badai seperti ini, kamu harus berteriak sekeras mungkin agar bisa mendengar suaramu sendiri.]]
  },
  AvgDialog_15370_Content_11 = {
    Text = "Di sini… aku di sini…"
  },
  AvgDialog_15370_Content_12 = {
    Text = "Di@1hihihi di sini di sini@2sini sini sini…"
  },
  AvgDialog_15370_Content_13 = {
    Text = "Suara-suara tak terhitung menyerbumu dari segala penjuru. Kamu tak sanggup bertahan lagi, akhirnya jatuh berlutut di atas pasir pantai."
  },
  AvgDialog_15370_Content_14 = {
    Text = "Mungkin semua ini hanyalah halusinasimu… mungkin Nona Shan sudah pergi untuk selamanya."
  },
  AvgDialog_15370_Content_15 = {
    Text = "<Shake:Nona Shan, keluarlah……Aku tahu kau ada di sini……>"
  },
  AvgDialog_15370_Content_16 = {
    Text = "Entah sejak kapan, kesadaran sang pelayan telah perlahan menelanmu. Harapan dan penderitaannya begitu dalam menggerakkan hatimu."
  },
  AvgDialog_15370_Content_17 = {
    Text = "Kau menempelkan dahimu di pasir yang lembap, tenggorokanmu mengeluarkan isakan yang terasa asing."
  },
  AvgDialog_15370_Content_18 = {
    Text = "<Shake:Nona Shan……>"
  },
  AvgDialog_15370_Content_19 = {
    Text = "<Red:Di sini……Aku di sini……>"
  },
  AvgDialog_15370_Content_2 = {
    Text = "Tuan Claudel yang terhormat:\n\nKematian Gadis Karang meraih kesuksesan besar di Cité, semua orang membicarakannya.\nMelihat patung ini, aku tak bisa menahan diri untuk teringat padamu.\n\nPatung ini menggunakan material putih yang redup, mirip dengan batu-batu yang menutupi seluruh tubuhmu dan membuatmu tak bisa bergerak lagi.\nTapi mereka tidak mengizinkanku menyentuh patung itu@1\nAku akan mencari cara."
  },
  AvgDialog_15370_Content_20 = {Text = "……Ini?"},
  AvgDialog_15370_Content_21 = {
    Text = "Dingin yang membeku menjalar dari ujung jari."
  },
  AvgDialog_15370_Content_22 = {
    Text = "Kabut putih kembali merambat dari sela-sela jari, bagaikan sulur yang hidup……"
  },
  AvgDialog_15370_Content_23 = {
    Text = "Perlahan……dengan teratur……"
  },
  AvgDialog_15370_Content_24 = {
    Text = "Akhirnya……akhirnya saat ini tiba."
  },
  AvgDialog_15370_Content_25 = {
    Text = [[
Sepasang sepatu kulit wanita yang elegan berhenti di hadapanmu.
Shan memegang pisau ukir, masih dengan ekspresi tenangnya yang biasa.]]
  },
  AvgDialog_15370_Content_26 = {
    Text = "Nona Shan……ternyata kau memang masih hidup……"
  },
  AvgDialog_15370_Content_27 = {
    Text = "Itu tergantung bagaimana kau mendefinisikan \"hidup\"."
  },
  AvgDialog_15370_Content_28 = {
    Text = "Cahaya lembut dari kejauhan menyelimuti tubuh Shan dengan perlahan. Dia tersenyum padamu dalam diam."
  },
  AvgDialog_15370_Content_29 = {
    Text = "Aku sudah kembali, Camille. Kau pasti sudah lama menungguku, kan?"
  },
  AvgDialog_15370_Content_3 = {
    Text = [[
Nona Shan akhirnya mewujudkan keinginannya. Dia menukarkan nyawanya sendiri demi menciptakan seni yang abadi.
Namun karena itu pula, dia meninggalkan kita untuk selamanya.
Sudah hampir sebulan sejak pameran berakhir, aku masih sangat merindukannya.

<Yellow:Aku akan menemukannya, lalu membawanya pulang bersama.>

Camille@1
A.F.2@1 Agustus]]
  },
  AvgDialog_15370_Content_30 = {
    Text = "Penderitaan, keterkejutan, kegembiraan yang meluap……"
  },
  AvgDialog_15370_Content_31 = {
    Text = "Tak terhitung emosi bergejolak di dalam dadamu, kau membuka mulut, namun mendapati dirimu tak lagi mampu mengeluarkan suku kata yang utuh."
  },
  AvgDialog_15370_Content_32 = {
    Text = "Shan@1……Ja@2……"
  },
  AvgDialog_15370_Content_33 = {Text = "Ssst……"},
  AvgDialog_15370_Content_34 = {
    Text = "Kau tahu? Tubuh manusia itu bagaikan sebuah dunia yang bergetar dan berdenyut."
  },
  AvgDialog_15370_Content_35 = {
    Text = "Ketika raga dan jiwa telah melewati cukup banyak penempaan, pada puncak ledakan emosi, mereka akan bermetamorfosis menjadi patung yang paling sempurna……"
  },
  AvgDialog_15370_Content_36 = {
    Text = "Jari-jari dingin menyentuh wajahmu yang perlahan mengeras."
  },
  AvgDialog_15370_Content_37 = {
    Text = "Shan menatapmu penuh kasih sayang, tatapan membara yang hampir membakarmu habis."
  },
  AvgDialog_15370_Content_38 = {
    Text = "Seperti dirimu yang sekarang ini……"
  },
  AvgDialog_15370_Content_39 = {
    Text = "Aku yang sekarang ini……? Nona Shan, apakah cairan korosi itu……"
  },
  AvgDialog_15370_Content_4 = {
    Text = "Kamu berlari terhuyung-huyung ke tepi laut. Di sini tak ada siapa pun, hanya lautan yang gelap dan sunyi serta garis cakrawala yang samar menemanimu."
  },
  AvgDialog_15370_Content_40 = {
    Text = "Sst…… diam."
  },
  AvgDialog_15370_Content_41 = {
    Text = "Bagiku, kematian tidak pernah menjadi hal yang menakutkan. Yang benar-benar menakutkan adalah……"
  },
  AvgDialog_15370_Content_42 = {
    Text = "<Yellow:Kehilangan keindahan, atau buta terhadap keindahan.>"
  },
  AvgDialog_15370_Content_43 = {
    Text = "<Shake:Per……gi…… biarkan aku……>"
  },
  AvgDialog_15370_Content_44 = {
    Text = "Jangan bicara bodoh, Camille."
  },
  AvgDialog_15370_Content_45 = {
    Text = "<Red:Kau sudah lama mati, tidak ingat?>"
  },
  AvgDialog_15370_Content_46 = {
    Text = "<Red:Sudah mati……>"
  },
  AvgDialog_15370_Content_48 = {
    Text = "Kau kembali terjatuh ke kedalaman lautan tanpa ujung."
  },
  AvgDialog_15370_Content_49 = {
    Text = "Fragmen-fragmen yang tersegel dalam ingatan bagaikan buih putih yang melayang di sekitar, terus bermunculan, terus pecah……"
  },
  AvgDialog_15370_Content_5 = {
    Text = "Kalian semua adalah keluargaku selamanya."
  },
  AvgDialog_15370_Content_50 = {
    Text = "Di detik terakhir sebelum kematian, kau terpaksa menghadapi kenyataan yang kejam itu——"
  },
  AvgDialog_15370_Content_51 = {
    Text = "Ini semua salahku, Camille. Semua salahku…… Biarkan aku memelukmu, dengan begitu lukanya tidak akan terasa sakit lagi."
  },
  AvgDialog_15370_Content_52 = {
    Text = "Kakak adalah jenius sejati. Dia pasti bisa menjadi seniman besar yang namanya terukir dalam buku!"
  },
  AvgDialog_15370_Content_53 = {
    Text = "Uhuk uhuk…… Jangan membohongi dirimu sendiri lagi, Camille……"
  },
  AvgDialog_15370_Content_54 = {
    Text = "Bawa dia kembali untuk menemuiku@2ada yang ingin kutanyakan langsung padanya……"
  },
  AvgDialog_15370_Content_55 = {
    Text = "Berita terbaru, berita terbaru!!"
  },
  AvgDialog_15370_Content_56 = {
    Text = "<Yellow:Kasus pembunuhan patung> yang menggemparkan dunia kembali menambah korban baru!"
  },
  AvgDialog_15370_Content_57 = {
    Text = "Hingga saat ini, kasus <Yellow:pusing dan histeria> akibat mengunjungi pameran \"Kematian Gadis Karang\" telah meningkat menjadi 54 kasus……"
  },
  AvgDialog_15370_Content_58 = {
    Text = "<Red:Di antaranya, 23 orang telah bunuh diri……>"
  },
  AvgDialog_15370_Content_6 = {
    Text = "Tenang saja. Karena aku sudah berjanji akan pulang bersamamu, aku tidak akan mengingkarinya."
  },
  AvgDialog_15370_Content_60 = {
    Text = "Ternyata aku……sudah mengetahui segalanya……"
  },
  AvgDialog_15370_Content_61 = {
    Text = "Kau kembali melihat istana laut putih itu. Plankton berkumpul di atas kalsium karbonat putih, dengan malas merentangkan anggota tubuh mereka."
  },
  AvgDialog_15370_Content_62 = {
    Text = "Kau juga melihat patung-patung putih yang melayang tanpa tujuan di dalam air laut."
  },
  AvgDialog_15370_Content_63 = {
    Text = "Di antara mereka ada beberapa wajah yang familiar, seperti Tuan Auguste, yang masih mempertahankan ekspresi murka dan putus asa saat menerjang patung itu."
  },
  AvgDialog_15370_Content_64 = {
    Text = "Seperti Tuan Muda Paul, rongga matanya yang cekung dipenuhi kemurungan, seolah sudah lama meramalkan takdirnya sendiri."
  },
  AvgDialog_15370_Content_65 = {
    Text = "Air laut yang hangat menyelimuti tubuhmu, irama pasang surut yang tak henti bagaikan sebuah nyanyian yang mengalir."
  },
  AvgDialog_15370_Content_66 = {
    Text = "Sebelum membuka mata sang bayi mengayunkan tangan mungilnya\nMenggenggam tanah liat merasakan kegembiraan serupa kasih ibu\nSeni membentuk dan menguasai sejak itu merambat di sela-sela jari\n\n<Red:Membuka mata semua yang terlihat lahir dari indah indah indah indah indah indah indah……>"
  },
  AvgDialog_15370_Content_67 = {
    Text = "Tangan dingin memelukmu dengan lembut. Shan membenamkan pipinya yang lembut di bahumu yang kaku."
  },
  AvgDialog_15370_Content_68 = {
    Text = "Kau dengar? Nyanyian-nyanyian itu, mereka terus bergema di dalam kepalaku tanpa henti."
  },
  AvgDialog_15370_Content_69 = {
    Text = "Itu adalah panggilan dari <Yellow:Mereka>, takdir yang sudah ditentukan dan tak bisa kuhindarkan……"
  },
  AvgDialog_15370_Content_7 = {
    Text = "Dia tidak akan mengingkari janjinya… dia tidak akan…"
  },
  AvgDialog_15370_Content_70 = {
    Text = "Aku mengikuti nyanyian-nyanyian itu, dan akhirnya menemukan tempat ini."
  },
  AvgDialog_15370_Content_71 = {
    Text = "Keajaiban dan keindahan dari dasar laut yang dalam……Aku tak punya apa pun untuk dipersembahkan kepada-Nya, kecuali dirimu."
  },
  AvgDialog_15370_Content_72 = {Text = "Aku……?"},
  AvgDialog_15370_Content_73 = {
    Text = "Ya, hanya dirimu——%player%."
  },
  AvgDialog_15370_Content_74 = {
    Text = "Dia mengucapkan nama aslimu dengan jelas dan tanpa keraguan."
  },
  AvgDialog_15370_Content_75 = {
    Text = "Sejak saat kau membuka matamu, aku sudah mengetahuinya."
  },
  AvgDialog_15370_Content_76 = {
    Text = "<Yellow:Kamulah \"Kematian Gadis Karang\" yang sesungguhnya.>"
  },
  AvgDialog_15370_Content_77 = {
    Text = "Kesadaran perlahan memudar, karang putih telah merambat ke seluruh tubuh sejak lama."
  },
  AvgDialog_15370_Content_78 = {
    Text = "Kau merasakan darah dan dagingmu menjadi begitu berat, namun anehnya, tubuh kalian terus naik di antara buih dan karang."
  },
  AvgDialog_15370_Content_79 = {
    Text = "<Shake:Tidak…… rumah…… pulang ke rumah……>"
  },
  AvgDialog_15370_Content_8 = {
    Text = "Kamu mengangkat ujung rokmu, terus berlari menyusuri garis pantai yang panjang."
  },
  AvgDialog_15370_Content_80 = {
    Text = "Di sinilah rumahmu, %player%."
  },
  AvgDialog_15370_Content_81 = {
    Text = "Tidak……"
  },
  AvgDialog_15370_Content_82 = {
    Text = "Kau membelalakkan mata menatap wajah Shan, hingga pupil matamu pun tertutup oleh karang putih keabu-abuan."
  },
  AvgDialog_15370_Content_83 = {
    Text = "Kau tenggelam dalam kehampaan tanpa batas."
  },
  AvgDialog_15370_Content_84 = {
    Text = "Semua lautan, karang, dan patung menjauh darimu, hanya suaranya yang tetap ada."
  },
  AvgDialog_15370_Content_85 = {
    Text = "Suara yang lembut namun dingin, seperti biasa."
  },
  AvgDialog_15370_Content_86 = {
    Text = "Aku sudah berjanji padamu, akan membawamu pulang bersama……"
  },
  AvgDialog_15370_Content_87 = {
    Text = "Aku sudah berjanji padamu."
  },
  AvgDialog_15370_Content_9 = {
    Text = "Nona Shan— Nona Shan—"
  },
  AvgDialog_15605_Content_1 = {
    Text = "Memulai pengujian"
  },
  AvgDialog_15605_Content_10 = {
    Text = "Jangan-jangan kau memasuki masa lalu Awakened lagi? Kau ingat sepertinya sedang melihat dokumen……"
  },
  AvgDialog_15605_Content_11 = {
    Text = "Kenapa tidak ada respons, modul pendengarannya bermasalah?"
  },
  AvgDialog_15605_Content_12 = {
    Text = "Itu tergantung situasinya. Apa kemarin setelah aku pergi, kamu diam-diam memodifikasi modulnya lagi?"
  },
  AvgDialog_15605_Content_13 = {
    Text = [[
Tidak, tidak, kali ini benar-benar tidak, sumpah!
Bagaimana kalau aku coba sekali lagi? Manusia Tik-Tok, kamu bisa mendengarku?]]
  },
  AvgDialog_15605_Content_14 = {Text = "Bisa."},
  AvgDialog_15605_Content_15 = {
    Text = "Lihat, lihat! Mulutnya bergerak, sudah kubilang tidak ada masalah!"
  },
  AvgDialog_15605_Content_16 = {
    Text = [[
Boneka mekanik otomatis penuh pertama di dunia yang bisa mengikuti perintah suara! Yang pertama! Otomatis penuh!
Ya Tuhan yang tercinta, jemputlah aku sekarang, hidupku sudah tidak ada penyesalan lagi!]]
  },
  AvgDialog_15605_Content_17 = {
    Text = "Aku justru punya banyak penyesalan, misalnya belum menyelesaikan uji respons perintah, uji fleksibilitas anggota tubuh, uji durasi operasi……"
  },
  AvgDialog_15605_Content_18 = {
    Text = "Me——i——kamu benar-benar tidak seru sama sekali."
  },
  AvgDialog_15605_Content_19 = {
    Text = "……uji koordinasi keseluruhan, uji keseimbangan, uji daya beban……"
  },
  AvgDialog_15605_Content_2 = {
    Text = "Kondisi perkaitan roda gigi, baik; sistem hidrolik, tidak ditemukan kebocoran tekanan; motor MF311000 beroperasi normal, suhu sedikit tinggi tetapi masih dalam batas yang diizinkan."
  },
  AvgDialog_15605_Content_20 = {
    Text = "Iya iya aku tahu! <Small:Kamu bahkan lebih mirip mesin daripada si Manusia Tik-Tok.>"
  },
  AvgDialog_15605_Content_21 = {
    Text = "Apa katamu?"
  },
  AvgDialog_15605_Content_22 = {
    Text = "Ah——selanjutnya kita lakukan uji penerimaan dan pemahaman perintah dasar!\nManusia Tik-Tok, kedipkan mata."
  },
  AvgDialog_15605_Content_23 = {Text = "Kedip"},
  AvgDialog_15605_Content_24 = {
    Text = [[
Ikuti jariku, bagus.
Buka mulut? Bagus sekali, anak pintar.]]
  },
  AvgDialog_15605_Content_25 = {
    Text = "……Huek."
  },
  AvgDialog_15605_Content_26 = {
    Text = "Apa sih! Bagaimanapun juga aku yang membuatnya sedikit demi sedikit, memanggilku mama juga wajar-wajar saja kan."
  },
  AvgDialog_15605_Content_27 = {
    Text = "Iya iya, Mama Si Gila Roda Gigi, ambilkan lengan kiri bayi baja kesayanganmu, kita mulai uji anggota tubuh."
  },
  AvgDialog_15605_Content_28 = {
    Text = "Sebuah lengan yang terdiri dari roda gigi rumit dan struktur mekanik yang tak kamu pahami muncul sekilas di pandanganmu, lalu menghilang di sisi kirimu, kemudian di sisi kanan."
  },
  AvgDialog_15605_Content_29 = {
    Text = "Pemasangan keempat anggota tubuh berjalan lancar. Kamu mengikuti perintah mengangkat tangan dan meluruskan kaki, senyum di wajah Erica semakin cerah."
  },
  AvgDialog_15605_Content_3 = {
    Text = "Sumber energi khusus S, kondisi stabil."
  },
  AvgDialog_15605_Content_30 = {
    Text = "Baik, selanjutnya——ah!"
  },
  AvgDialog_15605_Content_31 = {
    Text = [[
Asap hitam pekat mengepul dari bawah pandanganmu: ada sesuatu yang terbakar.
Kamu menunduk dan melihat percikan listrik serta bunga api berkilat di rongga perutmu.]]
  },
  AvgDialog_15605_Content_32 = {
    Text = "Alat pemadam, Mei, Mei!"
  },
  AvgDialog_15605_Content_33 = {Text = "Minggir!"},
  AvgDialog_15605_Content_34 = {
    Text = [[
Alat pemadam menyemburkan busa putih, bau hangus menyebar terbawa aliran udara.
Erika mendekat, tak peduli panasnya motor listrik itu dan langsung melepasnya.]]
  },
  AvgDialog_15605_Content_35 = {Text = "Erika!"},
  AvgDialog_15605_Content_36 = {
    Text = "Motor listrik yang gosong diletakkan di atas meja kerja. Erika menarik napas, baru kemudian menyadari tangannya yang berlumur busa putih terasa panas dan meniup-niupnya."
  },
  AvgDialog_15605_Content_37 = {
    Text = "Panas sekali, panas sekali!"
  },
  AvgDialog_15605_Content_38 = {
    Text = "Energi S, cepat periksa Energi S!"
  },
  AvgDialog_15605_Content_39 = {
    Text = "Erika mendekat ke motor listrik, jari-jarinya yang sedikit memerah karena panas dengan lembut menyusuri casing logamnya."
  },
  AvgDialog_15605_Content_4 = {
    Text = "Huu— sudah siap?\nUji aktivasi ke-13 automaton Ticktock Man, dimulai."
  },
  AvgDialog_15605_Content_40 = {
    Text = "Sepertinya sirkuit luar yang korsleting dan terbakar, seharusnya bagian dalam tidak rusak."
  },
  AvgDialog_15605_Content_41 = {
    Text = "Jangan khawatir, nanti aku akan memeriksanya."
  },
  AvgDialog_15605_Content_42 = {
    Text = "……Kau mau mengusirku keluar lagi?"
  },
  AvgDialog_15605_Content_43 = {Text = "Mei……"},
  AvgDialog_15605_Content_44 = {
    Text = "Memang salahku karena diam-diam memakai Energi S untuk eksperimen, tapi kau juga tahu kondisi keuangan kita. Menjadikan S sebagai terobosan bisa memberi kita lebih banyak waktu dan material."
  },
  AvgDialog_15605_Content_45 = {
    Text = [[
Biarkan aku melihatnya, sekali saja, aku bersumpah tidak akan membocorkan informasinya kepada siapa pun.
Kumohon.]]
  },
  AvgDialog_15605_Content_46 = {
    Text = "Sudah kubilang, di dalamnya tidak ada apa-apa."
  },
  AvgDialog_15605_Content_47 = {
    Text = "……Bahkan malas mengarang alasan, perlu sekali ya mewaspadaiku seperti itu?\nBukankah aku selalu memikirkan masa depan kita?"
  },
  AvgDialog_15605_Content_49 = {
    Text = [[
Sudahlah.
Aku pergi duduk-duduk di restoran Joey, terserah kau mau apa.]]
  },
  AvgDialog_15605_Content_5 = {
    Text = "Membuka mata"
  },
  AvgDialog_15605_Content_50 = {
    Text = "Pintu tertutup, langkah kaki menjauh, Erika menghela napas."
  },
  AvgDialog_15605_Content_51 = {
    Text = "Dia tetap…… tapi orang itu sudah memperingatkanku, Energi S……\nAku tidak bisa membiarkan Mei menanggung risiko bersamaku."
  },
  AvgDialog_15605_Content_52 = {
    Text = "Dia kembali menghadap motor listrik, seolah mengumpulkan kembali semangatnya."
  },
  AvgDialog_15605_Content_53 = {
    Text = "Aku pasti akan mencari tahu, tunggu aku, Mei."
  },
  AvgDialog_15605_Content_54 = {
    Text = "Dia membuka tutupnya dan mengeluarkan sebuah tabung hitam dari dalamnya."
  },
  AvgDialog_15605_Content_55 = {
    Text = "Pada saat itu, duniamu tenggelam dalam kegelapan."
  },
  AvgDialog_15605_Content_6 = {
    Text = "Ticktock Man, kau bisa mendengarku?"
  },
  AvgDialog_15605_Content_7 = {
    Text = "……Erica?"
  },
  AvgDialog_15605_Content_8 = {
    Text = "Wajah yang familiar itu menunjukkan ekspresi alami yang sama sekali berbeda dari ingatanmu. Dibandingkan automaton, dia terlihat lebih seperti manusia hidup."
  },
  AvgDialog_15605_Content_9 = {
    Text = "……Apa yang terjadi?"
  },
  AvgDialog_15606_Content_1 = {
    Text = "Suara itu berkata"
  },
  AvgDialog_15606_Content_10 = {
    Text = "Dia bergumam sambil pergi, meninggalkanmu sendirian bersama motor dan komponen-komponen di meja kerja."
  },
  AvgDialog_15606_Content_11 = {
    Text = "Kau memandangi tanganmu sendiri."
  },
  AvgDialog_15606_Content_12 = {
    Text = "Ramping, kuat, cangkang porselen halus yang telah dibersihkan dan dirawat dengan cermat. Meski dingin, di bawah cahaya redup tampak tak berbeda dari tangan orang hidup."
  },
  AvgDialog_15606_Content_13 = {
    Text = [[
Ini adalah tangan Erica, tangan <Blue:boneka otomatis Erica> yang kau kenal.
Kau tampaknya telah menempati tubuhnya yang kemudian, menjadi boneka otomatis yang dia ciptakan.]]
  },
  AvgDialog_15606_Content_14 = {
    Text = [[
Yang baru saja kau lihat, dia jelas-jelas seorang manusia.
Pengalaman apa sebenarnya yang mengubahnya menjadi sosok seperti itu di kemudian hari?]]
  },
  AvgDialog_15606_Content_15 = {Text = "Erika?"},
  AvgDialog_15606_Content_16 = {
    Text = [[
Kau berkedip, entah sejak kapan Mei sudah masuk.
Pandangannya menyapu sekeliling ruangan, dan akhirnya jatuh pada motor di sampingmu.]]
  },
  AvgDialog_15606_Content_18 = {
    Text = "Setelah menyapu ruangan untuk kedua kalinya, dia menutup pintu dan berjalan cepat menuju motor."
  },
  AvgDialog_15606_Content_19 = {
    Text = "Maafkan aku, Erica."
  },
  AvgDialog_15606_Content_2 = {
    Text = "Manusia Detak, sayangku, kau bisa mendengarku?"
  },
  AvgDialog_15606_Content_20 = {
    Text = "Tutupnya diputar, Mei mencengkeram benda di dalamnya. Kali ini kau melihat dengan jelas — itu adalah tabung logam berdiameter hanya 5 sentimeter dengan huruf \"S\" terukir di sisinya."
  },
  AvgDialog_15606_Content_21 = {
    Text = "Begitu dia mencabut tabung itu sepenuhnya, kau akan kehilangan kesadaran lagi.\nJadi sebelum itu terjadi, kau harus——"
  },
  AvgDialog_15606_Content_22 = {
    Text = "Raih tangannya"
  },
  AvgDialog_15606_Content_23 = {Text = "Ah!"},
  AvgDialog_15606_Content_24 = {
    Text = "Ada apa, ada apa——"
  },
  AvgDialog_15606_Content_25 = {
    Text = "Erica menerobos masuk ke ruangan, raut kekhawatiran di wajahnya langsung membeku saat melihat tabung di tangan Mei."
  },
  AvgDialog_15606_Content_26 = {
    Text = "Mei, apa yang sedang kau lakukan?"
  },
  AvgDialog_15606_Content_27 = {
    Text = "Apa yang kau lakukan!"
  },
  AvgDialog_15606_Content_28 = {
    Text = "Aku hanya mencoba… energi ini… ternyata benar-benar bisa…"
  },
  AvgDialog_15606_Content_29 = {
    Text = "Menghadapi tabung kecil yang telah menggerakkan seluruh mesin dan semua perangkat yang terhubung, Mei membelalakkan matanya."
  },
  AvgDialog_15606_Content_3 = {
    Text = "Terbangun dari kegelapan abadi, kau mendapati dirimu masih berada di bengkel. Motor yang terbakar hitam masih tergeletak di meja kerja, terhubung ke tubuhmu dengan beberapa kabel dengan ketebalan berbeda-beda."
  },
  AvgDialog_15606_Content_30 = {
    Text = "Kau tahu apa artinya ini, Erica?"
  },
  AvgDialog_15606_Content_31 = {
    Text = "Artinya benda ini berbahaya. Sudah kubilang, Mei, jangan sembarangan menyentuhnya——"
  },
  AvgDialog_15606_Content_32 = {
    Text = "Tidak, tidak, dengarkan, Erica——benda ini, benda kecil ini, mampu menyuplai energi tanpa kehilangan, tanpa emisi, dalam jangka waktu lama. Kau masih belum mengerti?"
  },
  AvgDialog_15606_Content_33 = {
    Text = "Batu bara, minyak bumi, semuanya tak ada artinya di hadapannya. Jika bisa diproduksi massal, kita akan menulis ulang struktur energi umat manusia, nama kita akan dikenang sepanjang sejarah!"
  },
  AvgDialog_15606_Content_34 = {
    Text = "Kau harus memberitahuku bagaimana kau membuatnya, kau harus!"
  },
  AvgDialog_15606_Content_35 = {
    Text = "Erica, mau ke mana kau? Apa maksudmu kau tidak tahu cara membuatnya, Erica!"
  },
  AvgDialog_15606_Content_36 = {
    Text = "Investor sudah bilang, selama mereka bisa melihat sampelnya, mereka bersedia menyediakan dana besar untuk kita, bahkan studio kerja eksklusif."
  },
  AvgDialog_15606_Content_37 = {
    Text = "Kenapa kau tidak mau dengar——aku tidak tahu bagaimana benda ini dibuat, aku tidak bisa membuatnya!"
  },
  AvgDialog_15606_Content_38 = {
    Text = "Aku sudah melewati usia untuk percaya dongeng, Erica. <Blue:Pemilik toko misterius> katamu? Kalau mau mengelak, setidaknya cari alasan yang lebih baik."
  },
  AvgDialog_15606_Content_39 = {
    Text = "Kau jelas-jelas mampu membuat sesuatu yang sehebat ini, kenapa pandanganmu tidak lebih jauh ke depan?"
  },
  AvgDialog_15606_Content_4 = {
    Text = "Bisa mendengar."
  },
  AvgDialog_15606_Content_40 = {
    Text = "Kenapa masih mengurung dirimu di tempat seperti ini, mengutak-atik besi-besi rongsokan?"
  },
  AvgDialog_15606_Content_41 = {
    Text = "Suara Mei bagaikan tamparan keras di wajah Erika. Ia menatap rekan dan partnernya, tak percaya dengan apa yang baru saja didengarnya."
  },
  AvgDialog_15606_Content_42 = {
    Text = "……Besi rongsokan, jadi itu yang sebenarnya kau pikirkan?"
  },
  AvgDialog_15606_Content_43 = {
    Text = "Kupikir kita memiliki cita-cita yang sama."
  },
  AvgDialog_15606_Content_44 = {
    Text = "Mei menggigit bibirnya dan menggenggam erat tabung di tangannya."
  },
  AvgDialog_15606_Content_45 = {
    Text = "Hadapi kenyataan, Erika. Sekarang tidak ada yang mau mengeluarkan uang untuk automaton lagi. Energi baru adalah jalan keluar kita."
  },
  AvgDialog_15606_Content_46 = {
    Text = "……Letakkan energi khusus itu."
  },
  AvgDialog_15606_Content_47 = {
    Text = "Pikirkan semua yang bisa kita miliki—lebih banyak dana, lebih banyak sumber daya.\nDengan semua itu, barulah kau bisa melanjutkan mimpimu. Dengan semua itu, barulah kau bisa—"
  },
  AvgDialog_15606_Content_48 = {
    Text = "Kubilang letakkan!"
  },
  AvgDialog_15606_Content_49 = {
    Text = "Erika maju untuk merebutnya. Mei tak sempat menghindar dan menabrak lemari di sampingnya."
  },
  AvgDialog_15606_Content_5 = {
    Text = "Maaf ya, aku janji setelah ini akan fokus mengatasi modul suara! Untuk sementara bertahanlah dulu, oke?"
  },
  AvgDialog_15606_Content_50 = {Text = "!!"},
  AvgDialog_15606_Content_51 = {
    Text = "Botol-botol berisi berbagai reagen dan bahan bakar berjatuhan. Kau menerjang ke depan untuk melindungi mereka berdua, dan detik berikutnya—"
  },
  AvgDialog_15606_Content_6 = {
    Text = "Mengangguk."
  },
  AvgDialog_15606_Content_7 = {
    Text = "Demi Bapa Dewa, syukurlah. Aku benar-benar takut ada kabel yang terbakar."
  },
  AvgDialog_15606_Content_8 = {
    Text = "Dia menghela napas lega, lalu menguap lebar seolah baru merasakan kelelahan."
  },
  AvgDialog_15606_Content_9 = {
    Text = "Aku harus minum secangkir kopi, dan juga makan malam…"
  },
  AvgDialog_15607_Content_1 = {
    Text = "Meriam plasma menembak tangan raksasa itu. Inti perak terlepas dari telapak tangan akibat hantaman, dan jatuh tanpa suara ke tanah."
  },
  AvgDialog_15607_Content_10 = {
    Text = "Aku… sebenarnya sudah… melakukan apa…"
  },
  AvgDialog_15607_Content_11 = {
    Text = [[
Kamu masih tidak mengerti, tapi tidak apa-apa, kamu sudah mendorong revolusi kehidupan dan jiwa ini, revolusi <Red:"Metamorfosis"> ini.
Matilah dengan tenang, aku memastikan semua orang mengingat kontribusimu.]]
  },
  AvgDialog_15607_Content_12 = {
    Text = "Erica menutup matanya."
  },
  AvgDialog_15607_Content_13 = {
    Text = "Kau… benar, kau selalu…"
  },
  AvgDialog_15607_Content_14 = {
    Text = "Air mata hitam mengalir dari sudut matanya. Ia mengernyitkan hidungnya, lalu tiba-tiba menoleh ke arahmu."
  },
  AvgDialog_15607_Content_15 = {
    Text = "Sejak awal aku… seharusnya mendengarkan… kau… Aku… tidak seharusnya mengambil benda ini…"
  },
  AvgDialog_15607_Content_16 = {
    Text = "Kewarasanku… milikku… tolong aku… untuk terakhir kalinya…"
  },
  AvgDialog_15607_Content_17 = {
    Text = "Apakah benar ada kesadaran ketiga di dalam tubuh ini, ataukah kau hanyalah perwujudan rasa bersalahnya di bawah pengaruh erosi? Kau tidak tahu."
  },
  AvgDialog_15607_Content_18 = {
    Text = "Ia mengulurkan tangan ke arahmu."
  },
  AvgDialog_15607_Content_19 = {
    Text = "Tolong aku… selamatkan…"
  },
  AvgDialog_15607_Content_2 = {
    Text = "Setelah terhenti sesaat, tangan raksasa itu hancur dan terurai. Cairan hitam menumpah turun bagaikan hujan deras, menembus tubuhmu, namun menodai bayangan Erica hingga menghitam."
  },
  AvgDialog_15607_Content_20 = {
    Text = "Yang kau tahu hanyalah kau akan membantunya, menyaksikan akhirnya sebagai \"manusia\"."
  },
  AvgDialog_15607_Content_21 = {
    Text = "Genggam tangannya"
  },
  AvgDialog_15607_Content_22 = {
    Text = "Ia menatapmu dengan terkejut, seolah tidak pernah menyangka bahwa ia benar-benar bisa menyentuh \"kewarasannya\" sendiri."
  },
  AvgDialog_15607_Content_23 = {Text = "Mengangguk"},
  AvgDialog_15607_Content_24 = {
    Text = "Ia menatapmu dengan terkejut, seolah sama sekali tidak menyangka bahwa \"nuraninya\" bisa memberikan respons kepadanya."
  },
  AvgDialog_15607_Content_25 = {
    Text = "Terima kasih……"
  },
  AvgDialog_15607_Content_26 = {
    Text = "Bayangan semu itu pecah dan menghilang bagaikan gelembung, hanya menyisakan bola cahaya yang berkedip-kedip tak menentu, masih memancarkan sinarnya yang terakhir."
  },
  AvgDialog_15607_Content_27 = {
    Text = "Kau mendekap bola cahaya yang telah mengecil itu dalam pelukanmu, memandang ke arah Inti Perak yang hancur tak jauh dari sana."
  },
  AvgDialog_15607_Content_28 = {
    Text = "Kau pasti akan berhasil."
  },
  AvgDialog_15607_Content_3 = {
    Text = "Berakhir……sudah……"
  },
  AvgDialog_15607_Content_4 = {
    Text = "Kau benar-benar berpikir begitu?"
  },
  AvgDialog_15607_Content_5 = {Text = "!?"},
  AvgDialog_15607_Content_6 = {
    Text = "Sudah kubilang, selama kau memasuki jantung perak ini, kau akan meraih keabadian sejati."
  },
  AvgDialog_15607_Content_7 = {
    Text = "Berontak sepuasmu, materi hitam pada akhirnya akan menghapusmu. Saat itu tiba, aku akan membawa <Red:\"Metamorfosis\"> sejati kepada dunia — semua orang akan menjadi abadi, semua orang akan hidup selamanya."
  },
  AvgDialog_15607_Content_8 = {
    Text = "Itu adalah… kematian… bukan…"
  },
  AvgDialog_15607_Content_9 = {
    Text = "Warna hitam semakin banyak menguasai tubuhnya. Erica membungkuk kesakitan, kesadarannya sudah di ambang kehancuran."
  },
  AvgDialog_15608_Content_1 = {
    Text = "Ini… ruang mental?"
  },
  AvgDialog_15608_Content_2 = {
    Text = "Ya Tuhan, ini sebenarnya, ini sebenarnya…"
  },
  AvgDialog_15608_Content_3 = {
    Text = "Suara itu… Erika!"
  },
  AvgDialog_15609_Content_1 = {
    Text = "Tidak, Erica, jangan percaya padanya!"
  },
  AvgDialog_15609_Content_10 = {
    Text = [[
Tubuh daging dan darah hanyalah belenggu bagi jiwa. Hanya dengan membebaskan jiwa, dia bisa bergabung dengan kita.
Hanya tubuh dan pikiran dari logam yang bisa membuat kita abadi.]]
  },
  AvgDialog_15609_Content_11 = {
    Text = "Jari-jari itu mengencang, wajah Mei menunjukkan ekspresi kesakitan."
  },
  AvgDialog_15609_Content_12 = {
    Text = "<Shake:Kau… gila…>"
  },
  AvgDialog_15609_Content_13 = {
    Text = "Sebuah tangan lain yang gemetar muncul di layar. Erica mencengkeram pergelangan tangannya sendiri dan memutarnya, melepas tangan yang tak terkendali itu lalu melemparkannya ke samping."
  },
  AvgDialog_15609_Content_14 = {
    Text = "Tangan raksasa itu berhenti sesaat, seolah sedikit bingung."
  },
  AvgDialog_15609_Content_15 = {
    Text = "Kenapa kamu melawanku? Aku sedang memberinya kehidupan baru."
  },
  AvgDialog_15609_Content_16 = {
    Text = "Halusinasi, semua ini, halusinasi."
  },
  AvgDialog_15609_Content_17 = {
    Text = "Erica menopang Mei yang tak sadarkan diri dan perlahan berdiri."
  },
  AvgDialog_15609_Content_18 = {
    Text = "Aku harus membawanya ke rumah sakit, aku harus… membuatnya tetap hidup."
  },
  AvgDialog_15609_Content_19 = {
    Text = "Dia memapah Mei di bahunya, melewati studio yang hancur berantakan akibat ledakan, dan berjalan menuju pintu yang tak jauh dari sana."
  },
  AvgDialog_15609_Content_2 = {
    Text = "Erica, Erica!"
  },
  AvgDialog_15609_Content_3 = {
    Text = "Saat kau melawan musuh di hadapanmu, seekor monster yang terbentuk dari cairan hitam berputar ke belakangmu dan menerjang bola cahaya yang mewakili jiwa Erica."
  },
  AvgDialog_15609_Content_4 = {
    Text = [[
Bagaikan cat yang masuk ke dalam air, kegelapan menyebar di dalam bola cahaya dan menutupi segalanya di dalamnya.
Bola cahaya mulai berkedip-kedip.]]
  },
  AvgDialog_15609_Content_5 = {
    Text = "Apa yang terjadi, tanganku… bergerak sendiri…"
  },
  AvgDialog_15609_Content_6 = {
    Text = "Apa ini ulahmu?Berhenti, <Big:berhenti!>"
  },
  AvgDialog_15609_Content_7 = {
    Text = "Kenapa, bukankah kamu ingin menyelamatkannya?"
  },
  AvgDialog_15609_Content_8 = {
    Text = "Kamu jelas-jelas mau mencekiknya sampai mati! Lepaskan!"
  },
  AvgDialog_15609_Content_9 = {
    Text = "Di antara silih bergantinya kegelapan dan cahaya, kamu melihat tangan mekanis perlahan-lahan menjulur ke leher Mei."
  },
  AvgDialog_15610_Content_1 = {
    Text = "Pertahanan satu orang nyaris tak berarti. Tak peduli berapa banyak monster yang kau hancurkan, tubuh mereka yang terbuat dari cairan dengan cepat berkumpul kembali, melewatimu, dan langsung melompat ke dalam bola cahaya."
  },
  AvgDialog_15610_Content_10 = {
    Text = "Plasma keemasan berderak-derak di atas bayangan itu, sosok Erika semakin memadat."
  },
  AvgDialog_15610_Content_11 = {
    Text = "Dia mengangkat tangan dan menggunakan plasma untuk menghancurkan monster di hadapanmu. Tangan raksasa itu bergerak sedikit, mengeluarkan sebuah helaan napas."
  },
  AvgDialog_15610_Content_12 = {
    Text = "Aku hanya ingin membalas budi karena kau membawaku kembali dan memberiku tubuh baru. Mengapa kau harus menyakitiku seperti ini?"
  },
  AvgDialog_15610_Content_13 = {
    Text = "Membawa kembali? Apa maksudmu, aku tidak pernah……"
  },
  AvgDialog_15610_Content_14 = {
    Text = "Benda ini bisa menjadi sumber energi untuk bonekaku?"
  },
  AvgDialog_15610_Content_15 = {
    Text = "Erica mengambil tabung logam hitam itu dengan penuh keraguan, mengamatinya dari segala sisi."
  },
  AvgDialog_15610_Content_16 = {
    Text = [[
Kalau kau khawatir benda ini tidak mampu menopang operasi boneka dalam jangka panjang, tak perlu cemas.
Benda sekecil ini sudah cukup untuk menggerakkan sesuatu yang jauh lebih rumit dan besar.]]
  },
  AvgDialog_15610_Content_17 = {
    Text = "Maksudmu, ada orang lain yang menggunakan sumber energi seperti ini?"
  },
  AvgDialog_15610_Content_18 = {
    Text = "Sesuatu yang mirip dengannya, ada. Tapi yang persis sama? Mustahil."
  },
  AvgDialog_15610_Content_19 = {
    Text = "Yang kau minta adalah \"sumber energi yang unik\", dan toko kecil Daffodil tidak pernah mengecewakan pelanggannya."
  },
  AvgDialog_15610_Content_2 = {
    Text = "Si… al…"
  },
  AvgDialog_15610_Content_20 = {
    Text = "Oh ya, satu peringatan ramah — jangan penasaran dengan struktur dan prinsip kerjanya.\nBegitu kotak Pandora dibuka, konsekuensinya hanya bisa kau tanggung sendiri."
  },
  AvgDialog_15610_Content_21 = {
    Text = "Aku tidak ingin seorang jenius sepertimu meninggal di usia muda. Selain proyektor, masih banyak ide yang ingin kuwujudkan."
  },
  AvgDialog_15610_Content_22 = {
    Text = "Kutunggu kunjunganmu berikutnya ya, Erica."
  },
  AvgDialog_15610_Content_23 = {
    Text = "Tidak, tidak mungkin. Di dalam Sumber Energi S jelas-jelas hanya ada——"
  },
  AvgDialog_15610_Content_24 = {
    Text = [[
Sebuah <Yellow:pecahan perak> kecil, benar kan?
Benda kecil yang ajaib, tidak hanya bisa menggerakkan mesin, tapi juga menyimpan jiwa makhluk hidup.]]
  },
  AvgDialog_15610_Content_25 = {
    Text = [[
Jiwamu telah menyatu dengan tubuh ini berkat bantuan zat hitam. Selama kau masuk ke dalam <Yellow:jantung perak> sebelum digerogoti oleh mereka, kau bisa benar-benar menjadi abadi. Kau dan aku.

Sebagai "ibu" dalam kehidupan ini, kau berhak berbagi denganku.
Sayang, kau terlalu keras kepala.]]
  },
  AvgDialog_15610_Content_26 = {
    Text = "Aku terpaksa membiarkanmu ditelan oleh <Yellow:zat hitam>."
  },
  AvgDialog_15610_Content_27 = {
    Text = "Tangan raksasa itu tiba-tiba bergerak, membuka kelima jarinya dan memperlihatkan telapak tangannya. Inti perak di dalamnya penuh retakan, namun tetap berkilau terang."
  },
  AvgDialog_15610_Content_28 = {
    Text = "Selamat tinggal, penciptaku yang singkat."
  },
  AvgDialog_15610_Content_3 = {
    Text = "Bola cahaya berkedip lagi. Kau melihat kedua kaki Erika gemetar tanpa henti."
  },
  AvgDialog_15610_Content_4 = {
    Text = "Roda gigi saling mengunci, kilatan listrik kuning terang menyambar sekilas di antara pipa dan penyangga."
  },
  AvgDialog_15610_Content_5 = {
    Text = "Jangan melawan lagi, serahkan kendali tubuhmu padaku."
  },
  AvgDialog_15610_Content_6 = {
    Text = "Bukankah kau ingin menyelamatkannya? Bukankah kau ingin dia memperoleh keabadian bersamamu?"
  },
  AvgDialog_15610_Content_7 = {
    Text = "Semakin banyak kilatan listrik muncul di layar."
  },
  AvgDialog_15610_Content_8 = {
    Text = "Partikel cahaya melayang keluar dari bola cahaya, berkumpul bersama, membentuk bayangan berwujud manusia."
  },
  AvgDialog_15610_Content_9 = {Text = "E-Erika?!"},
  AvgDialog_15611_Content_1 = {
    Text = [[
Kenapa menyelamatkannya?
Dia menukar mimpimu demi kariernya sendiri, kamu benar-benar tidak dendam sedikit pun?]]
  },
  AvgDialog_15611_Content_10 = {
    Text = "Tapi aku segera menyadari: ini bukan bencana, bukan halusinasi, melainkan sebuah kesempatan bagi umat manusia."
  },
  AvgDialog_15611_Content_11 = {
    Text = "Dalam mekanik tidak ada penyakit, tidak ada kematian; dalam mekanik, kita bisa menciptakan kerajaan Tuhan yang sejati—tidak, lebih baik dari kerajaan Tuhan palsu kalian.\n\nKita bisa melampaui kehidupan dari daging dan darah."
  },
  AvgDialog_15611_Content_12 = {
    Text = "Cairan hitam kembali menetes dari tangan raksasa itu. Mereka bergetar, menggeliat, merangkak maju sambil saling melebur satu sama lain, bersemangat oleh pemandangan mengerikan yang dilukiskan oleh suara itu."
  },
  AvgDialog_15611_Content_13 = {
    Text = "Suara itu meninggi, tangan raksasa bergoyang, melemparkan lebih banyak cairan, lebih banyak monster."
  },
  AvgDialog_15611_Content_14 = {
    Text = "Kita, bisa menjadi Tuhan itu sendiri."
  },
  AvgDialog_15611_Content_15 = {
    Text = "Cairan itu tiba-tiba berakselerasi, menerjang kembali ke arah bola cahaya di belakangmu."
  },
  AvgDialog_15611_Content_2 = {
    Text = "Dia hanya… membuat keputusan yang salah.\nSetelah dia sadar, kita bicara baik-baik, semuanya pasti bisa diselesaikan."
  },
  AvgDialog_15611_Content_3 = {
    Text = "Telepon umum terdekat ada satu kilometer dari sini, dia tidak bisa menunggu selama itu."
  },
  AvgDialog_15611_Content_4 = {
    Text = "Maaf, aku lebih memilih percaya pada naluri bertahan hidup manusia daripada omong kosong \"membebaskan jiwa\" darimu."
  },
  AvgDialog_15611_Content_5 = {
    Text = [[
Jika perkataanku bohong, bagaimana kamu menjelaskan kondisimu sekarang?
Tubuh daging dan darahmu sudah hancur berkeping-keping, tapi kesadaranmu tetap bertahan, bahkan bisa mengendalikan tubuh ini untuk terus menjalani hidup.

Bukankah itu cukup membuktikan apa yang kukatakan?]]
  },
  AvgDialog_15611_Content_6 = {
    Text = "<Big:Kamu tidak bisa memastikan itu penyebab aku menjadi seperti ini!>"
  },
  AvgDialog_15611_Content_7 = {
    Text = "Erika terdiam sejenak. Ia seperti ingin menarik napas, namun organ yang memungkinkannya melakukan itu sudah tidak ada lagi."
  },
  AvgDialog_15611_Content_8 = {
    Text = "Apa yang sedang kulakukan, berdebat dengan halusinasi… Jangan dengarkan, jangan pikirkan, dia adalah halusinasi, halusinasi yang ditimbulkan oleh gas beracun—"
  },
  AvgDialog_15611_Content_9 = {
    Text = [[
Kau takut, maka kau mencoba melarikan diri.
Aku bisa memahaminya. Aku yang baru saja menyelesaikan <Red:"Metamorfosis"> juga dipenuhi ketakutan sepertimu.]]
  },
  AvgDialog_15612_Content_1 = {
    Text = "Irama tak kasat mata mengelilingimu, menyelimutimu. Titik-titik cahaya menyala di kejauhan, tampak rapuh dan tak terjangkau."
  },
  AvgDialog_15612_Content_10 = {
    Text = "<Gray:Tidak mungkin… Jangan-jangan…>"
  },
  AvgDialog_15612_Content_11 = {
    Text = [[
Jangan-jangan saat itu, kau dan Erica berbagi satu tubuh yang sama?
Jangan-jangan itulah alasan dia berubah menjadi boneka mekanis?]]
  },
  AvgDialog_15612_Content_12 = {
    Text = "<Gray:Tapi, bagaimana mungkin ledakan biasa bisa menghasilkan efek seperti ini?>"
  },
  AvgDialog_15612_Content_13 = {
    Text = "Apakah kau ingin menyelamatkannya?"
  },
  AvgDialog_15612_Content_14 = {Text = "?!"},
  AvgDialog_15612_Content_15 = {
    Text = [[
Sebuah suara muncul entah dari mana, ada di mana-mana namun tak dapat dilacak.
Kau menoleh ke sekeliling. Di dalam ruang mental yang kosong, sebuah siluet mulai terbentuk.]]
  },
  AvgDialog_15612_Content_16 = {
    Text = "Siapa, siapa di sana?"
  },
  AvgDialog_15612_Content_17 = {
    Text = "Aku adalah kehendak yang merespons panggilanmu, kehidupan yang kau berikan tubuh baru."
  },
  AvgDialog_15612_Content_18 = {
    Text = "Aku bisa dianggap sebagai ciptaanmu, dan kau, adalah \"ibu\" bagiku dalam kehidupan ini."
  },
  AvgDialog_15612_Content_19 = {
    Text = "Sebuah tangan raksasa terbentuk di balik bola cahaya yang mewakili jiwa Erica. Ujung-ujung jarinya berkedut dan gemetar, meneteskan cairan hitam pekat."
  },
  AvgDialog_15612_Content_2 = {
    Text = "Mei, Mei! Bangunlah, Mei!"
  },
  AvgDialog_15612_Content_20 = {
    Text = "…Ticktock Man…?"
  },
  AvgDialog_15612_Content_21 = {
    Text = [[
Aku suka nama itu. Benar, panggil saja aku Ticktock Man.
Sebagai balasan karena telah memberiku kehidupan baru, aku bisa membantumu menyelamatkannya.
Kau hanya perlu melepaskan.]]
  },
  AvgDialog_15612_Content_22 = {
    Text = "Lepaskan, lalu serahkan segalanya padaku."
  },
  AvgDialog_15612_Content_23 = {
    Text = "Cairan hitam yang menumpuk di tanah tiba-tiba bergerak. Mereka saling melebur, membentuk individu-individu yang terdistorsi, merangkak bergerak menuju arah cahaya."
  },
  AvgDialog_15612_Content_3 = {
    Text = "Kau segera mendekati sumber suara itu."
  },
  AvgDialog_15612_Content_4 = {
    Text = "Itu adalah bola cahaya yang melayang di udara. Melalui bola cahaya itu, kau melihat sebuah wajah yang dipenuhi darah dan pasir—wajah Mei."
  },
  AvgDialog_15612_Content_5 = {
    Text = "Ia tampak dalam keadaan tak sadarkan diri. Bahkan ketika sebuah tangan pucat menepuk-nepuknya pelan, tak ada respons sama sekali."
  },
  AvgDialog_15612_Content_6 = {
    Text = "<Gray:Tangan itu…>"
  },
  AvgDialog_15612_Content_7 = {
    Text = [[
Kau menundukkan kepala, memastikan dugaan dalam hatimu: tangan yang terlihat dalam bola cahaya itu persis sama dengan tanganmu.
Itu adalah tangan automaton, yang saat ini bergerak mengikuti kehendak orang lain.]]
  },
  AvgDialog_15612_Content_8 = {
    Text = "Sial, Mei! Kita harus pergi dari sini, Mei!"
  },
  AvgDialog_15612_Content_9 = {
    Text = "Tangan mekanis itu beralih menekan bahu Mei. Pemandangan di dalam bola cahaya berubah, menampilkan studio yang masih terbakar, seolah seseorang sedang menoleh ke sana-kemari."
  },
  AvgDialog_15613_Content_1 = {
    Text = "Akhir yang Gemilang"
  },
  AvgDialog_15613_Content_10 = {
    Text = "Kaki kanan."
  },
  AvgDialog_15613_Content_11 = {
    Text = "Erica jatuh berlutut ke depan, korsleting yang terlalu sering membuat kaki kirinya kehilangan tenaga, ia hanya bisa menopang diri dengan lengan kanan yang sudah kehilangan telapak tangan."
  },
  AvgDialog_15613_Content_12 = {
    Text = [[
Dia dengan sangat hati-hati menyandarkan Mei di samping bilik telepon, lalu merangkak masuk ke dalam bilik telepon dengan kedua tangan dan kakinya.
Arus listrik memaksa kotak telepon menyala, dia menekan nomor darurat dan menyebutkan lokasi bilik telepon tersebut.]]
  },
  AvgDialog_15613_Content_13 = {
    Text = "Dengan begini……dia……akan aman……"
  },
  AvgDialog_15613_Content_14 = {
    Text = "Selanjutnya……apa……ya……"
  },
  AvgDialog_15613_Content_15 = {
    Text = "Kau tahu apa itu."
  },
  AvgDialog_15613_Content_16 = {
    Text = "Kau teringat, isi dokumen yang kau baca sebelum memasuki tempat ini."
  },
  AvgDialog_15613_Content_17 = {
    Text = "A.F. 297 tanggal @1 bulan @1 pukul 03:47, ledakan tak dikenal terjadi di tenggara kota @1@2@1, negara bagian @3, Republik Yagro. Gelombang kejut memicu gempa berkekuatan 3.8 skala Richter di wilayah setempat, getarannya terasa jelas, berdampak hingga desa-desa yang berjarak 5 kilometer dari kota @1@2@1.\n\n……\n\nA.F. 297 tanggal @1 bulan @1, 13 komponen berhasil dipulihkan dari hutan di tenggara kota @1@2@1, negara bagian @3, Republik Yagro, dengan nomor seri A101 hingga A114. Di antaranya, tiga komponen A108, A109, dan A113 mengalami kerusakan parah dan telah diserahkan kepada Dor untuk rekonstruksi desain.\nTim investigasi memulihkan serangkaian gambar desain dari @2 Jalan @1, di mana gambar-gambar tersebut cocok dengan komponen yang tersisa di lokasi ledakan, diduga sebagai cetak biru bahan peledak, dan telah diserahkan kepada Dor untuk dianalisis."
  },
  AvgDialog_15613_Content_18 = {
    Text = "Kau mendengar suara angin menyapu dedaunan."
  },
  AvgDialog_15613_Content_19 = {
    Text = "Bola cahaya itu sudah sangat redup, hampir melebur ke dalam kegelapan di sekelilingnya."
  },
  AvgDialog_15613_Content_2 = {Text = "Kaki kiri."},
  AvgDialog_15613_Content_20 = {
    Text = [[
Meskipun kau menyelamatkan tubuh dagingnya, lalu apa?
Kematian pasti akan datang, saat itu tiba, apakah dia akan berterima kasih padamu, atau membencimu karena telah merampas kesempatannya untuk hidup abadi?

Lepaskanlah, Erica, biarkan aku mengambil alih tubuh ini.
Aku akan membuatnya <Red:"Bertransformasi">, memberinya masa depan yang lebih baik.]]
  },
  AvgDialog_15613_Content_21 = {
    Text = "Aku……selalu merasa……akan mati dalam ledakan……\nMaaf……harus……menyeretmu ikut serta……"
  },
  AvgDialog_15613_Content_22 = {
    Text = "……Apa yang mau kau lakukan?"
  },
  AvgDialog_15613_Content_23 = {
    Text = "Diam……iblis……aku tidak……sedang bicara denganmu……"
  },
  AvgDialog_15613_Content_24 = {
    Text = "Gambar yang muncul di dalam bola cahaya adalah sebuah tangan mekanis yang sudah penuh bekas hangus dan masih terus mengeluarkan plasma listrik."
  },
  AvgDialog_15613_Content_25 = {
    Text = "Entah sejak kapan tangan itu menggenggam beberapa helai kabel yang dipenuhi cairan hitam lengket."
  },
  AvgDialog_15613_Content_26 = {
    Text = "Maafkan aku, Ticker……pada akhirnya……justru……harus menghancurkanmu dengan tanganku sendiri……"
  },
  AvgDialog_15613_Content_27 = {
    Text = [[
Keheningan menyelimuti kalian berdua.
Kamu masih belum yakin siapa identitasmu dalam mimpi ini, dan dia, tampaknya juga tidak menunggu sebuah jawaban.]]
  },
  AvgDialog_15613_Content_28 = {Text = "Haah..."},
  AvgDialog_15613_Content_29 = {
    Text = "Sungguh……sayang sekali……"
  },
  AvgDialog_15613_Content_3 = {
    Text = "Kaki kanan."
  },
  AvgDialog_15613_Content_30 = {
    Text = "Dia menariknya dengan sekuat tenaga."
  },
  AvgDialog_15613_Content_32 = {
    Text = "Kamu terbangun dengan tiba-tiba dan mendapati dirimu kembali di kamar yang familiar."
  },
  AvgDialog_15613_Content_33 = {
    Text = "Seseorang sedang mengetuk pintu kamarmu."
  },
  AvgDialog_15613_Content_34 = {
    Text = "Silakan masuk."
  },
  AvgDialog_15613_Content_35 = {
    Text = "Selamat siang, Penjaga Rahasia. Kamu memiliki sebuah pesan dari Dor. Apakah ingin menerimanya?"
  },
  AvgDialog_15613_Content_36 = {
    Text = "Dor lagi-lagi menambahkan fitur baru apa untukmu…… Terima."
  },
  AvgDialog_15613_Content_37 = {
    Text = "Bip— Kamu masih ingat hari ini hari apa, %player%? Kuingatkan dua kata: ujian."
  },
  AvgDialog_15613_Content_38 = {
    Text = "……Gawat."
  },
  AvgDialog_15613_Content_39 = {
    Text = "Kusarankan kamu muncul di kelas dalam lima menit, kalau tidak aku tidak bisa menjamin bagaimana kehidupan latihanmu selama 30 hari ke depan. Mungkin latihan fisiknya akan berlipat ganda?"
  },
  AvgDialog_15613_Content_4 = {
    Text = "Setiap langkah memercikkan bunga api, setiap langkah terdengar suara nyaring gesekan dan benturan mekanis."
  },
  AvgDialog_15613_Content_40 = {
    Text = "Bip— Pesan selesai. Apakah perlu membalas?"
  },
  AvgDialog_15613_Content_41 = {
    Text = "Balas apa! Cepat keluar sekarang!!"
  },
  AvgDialog_15613_Content_42 = {
    Text = "Sosok Penjaga Rahasia menghilang di ujung koridor. Erica berbalik dan memandang dokumen-dokumen yang berserakan di atas meja."
  },
  AvgDialog_15613_Content_43 = {
    Text = "Tahun Aluvial 298, bulan @1 tanggal @2, Departemen Kebangkitan Universitas Misage, @3\nBerdasarkan cetak biru T-38, restorasi tubuh Automaton E telah selesai, nomor seri EA301881.\nIni adalah percobaan restorasi kami yang ke-10. Aku harus mengagumi orang yang pertama kali merancang dan membuatnya—automaton ini sangat rumit dan halus, sekaligus sangat elegan. Ratusan bahkan ribuan roda gigi dan bantalan saling terhubung, bersama-sama memainkan simfoni megah yang bernama struktur mekanis. Bahkan saat ia diam tak bergerak, aku bisa merasakan suatu vitalitas yang unik.\nSayangnya, hingga kini kami belum menemukan kunci dari cetak biru motor—sebuah silinder berdiameter 5 sentimeter dan panjang 10 sentimeter. Seharusnya itu adalah inti energi dari seluruh automaton, namun benda seukuran itu yang mampu memasok daya untuk mekanisme serumit ini, aku belum pernah melihatnya…\nSemoga Profesor Dor bisa memikirkan sesuatu. Aku sudah tidak sabar ingin melihatnya benar-benar beroperasi."
  },
  AvgDialog_15613_Content_44 = {
    Text = "Tahun Aluvial 298, bulan @1 tanggal @2, Departemen Kebangkitan Universitas Misage, @3\nRestorasi motor selesai, nomor seri MF311028.\nMeskipun prosesnya penuh liku-liku (demi Bapa di atas, kami melakukan 28 kali percobaan, 28 kali!), gagasan akhir Profesor Dor terbukti benar—inti pasokan energi motor adalah Inti Perak.\nSetelah mencoba berbagai Inti Perak, hanya Inti Perak nomor E-1929 yang membuat motor berfungsi normal. Sulit bagiku untuk tidak membayangkan bahwa ini adalah pengaruh dari semacam kehendak yang ditinggalkan oleh perancangnya, meskipun hingga kini kami tidak mengetahui keberadaan orang tersebut."
  },
  AvgDialog_15613_Content_45 = {
    Text = "Tahun Aluvial 300, bulan @2 tanggal @1, Departemen Kebangkitan Universitas Misage, Dor\nKebangkitan Automaton Erica berhasil.\nSubjek kebangkitan memiliki agresivitas dan hasrat destruktif yang sangat kuat. Bahkan dengan penyelidik yang menjaga kondisi mentalnya, ia tetap menunjukkan kecenderungan menyerang yang jelas, serta melepaskan arus listrik secara tak terkendali, menyerang segala sesuatu di sekitarnya tanpa pandang bulu.\nAlistair menilai bahwa E-1929 mengandung dua jiwa—satu yang gila dan kuat, dan satu lagi yang lemah namun lebih rasional. Perlu dicoba untuk memisahkan keduanya, atau menekan kegilaan hingga dalam batas yang terkendali.\n…\nTahun Aluvial 300, bulan @2 tanggal @2, Departemen Kebangkitan Universitas Misage, Dor\nTidak dapat memisahkan jiwa, secara aktif mempertimbangkan rencana kedua.\nPerangkat penekan mental adalah ide yang bagus.\n…\nTahun Aluvial 303, bulan @1 tanggal @2, Departemen Kebangkitan Universitas Misage, Dor\nPerangkat penekan selesai dibuat, pemasangan berhasil.\nKegilaan subjek kebangkitan berhasil ditekan, kondisi keseluruhan cenderung stabil, namun masih ada kasus di mana penekanan gagal sesaat.\nKepribadian, hobi, dan aspek lain dari subjek kebangkitan hilang sepenuhnya, perilakunya lebih menyerupai boneka daripada manusia.\nSetidaknya dia tidak lagi berada di ambang ledakan setiap saat.\n…"
  },
  AvgDialog_15613_Content_46 = {
    Text = "Erica memiringkan kepalanya sedikit, merapikan dokumen-dokumen itu, lalu meninggalkan ruangan."
  },
  AvgDialog_15613_Content_5 = {
    Text = "Di bawah lampu jalan tak jauh dari sana, sebuah bilik telepon umum berdiri dengan tenang."
  },
  AvgDialog_15613_Content_6 = {Text = "Kaki kiri."},
  AvgDialog_15613_Content_7 = {
    Text = "Kaki kanan."
  },
  AvgDialog_15613_Content_8 = {
    Text = "Seolah menyadari tekad kalian, cairan kental yang terkulai di tanah masih terus menyerang kesadaran Erica, bahkan tubuhmu pun telah ternoda hitam pekat."
  },
  AvgDialog_15613_Content_9 = {Text = "Kaki kiri."},
  AvgDialog_18708_Content_1 = {Text = "!!!"},
  AvgDialog_18708_Content_10 = {
    Text = "Diiringi rintihan kesakitan, wajah Sang Pemburu Tengkorak terdistorsi hingga tak terbayangkan, bisul-bisul di bawah kulitnya bergerak-gerak cepat, seolah siap meledak keluar."
  },
  AvgDialog_18708_Content_11 = {Text = "Ini……?"},
  AvgDialog_18708_Content_13 = {
    Text = "Kepala dipenggal tanpa ampun, cairan Erosi hitam menyembur dari leher, nyaris muncrat ke wajahmu."
  },
  AvgDialog_18708_Content_14 = {
    Text = "Rasa ingin tahu yang berlebihan bukanlah kebiasaan yang baik, Penjaga Rahasia."
  },
  AvgDialog_18708_Content_15 = {
    Text = "Rongga tengkoraknya penuh dengan cairan Erosi yang menggenang, kusarankan kalian sebaiknya menjauh."
  },
  AvgDialog_18708_Content_16 = {
    Text = "Nyonya Daffodel!"
  },
  AvgDialog_18708_Content_17 = {
    Text = "Selamat malam, mawar kecilku."
  },
  AvgDialog_18708_Content_18 = {
    Text = "Kenapa kau lagi...?"
  },
  AvgDialog_18708_Content_19 = {
    Text = "Aku mengikuti jejak Sang Pemburu Tengkorak hingga kemari, sekalian mengambil kembali bungaku."
  },
  AvgDialog_18708_Content_2 = {
    Text = "Sang Pemburu Tengkorak terjatuh keras ke tanah, mulutnya mengeluarkan rintihan lemah."
  },
  AvgDialog_18708_Content_20 = {
    Text = "Daffodel berjalan dengan santai di atas lantai yang ternoda darah dan cairan Erosi, memetik bunga narsis dari kepala tempat tidur, lalu mendekatkannya ke ujung hidung dan menghirup aromanya perlahan."
  },
  AvgDialog_18708_Content_21 = {
    Text = "Ini adalah narsis piala cokelat yang kurawat dengan cermat selama tiga tahun, memiliki efek menenangkan dan menyegarkan pikiran, lho."
  },
  AvgDialog_18708_Content_22 = {
    Text = "Mau coba menciumnya?"
  },
  AvgDialog_18708_Content_23 = {
    Text = "<LightGray:Pantas saja tadi aku tidur begitu lelap...>"
  },
  AvgDialog_18708_Content_24 = {
    Text = "Dengan agak jengkel, kau menyingkirkan bunga narsis berembun yang ada di tangannya."
  },
  AvgDialog_18708_Content_25 = {
    Text = "Kau sepertinya sangat memahami si Pemburu Tengkorak."
  },
  AvgDialog_18708_Content_26 = {
    Text = "Bagaimana kau tahu cairan Erosi akan meluap dari otaknya?"
  },
  AvgDialog_18708_Content_27 = {
    Text = "Kalau kau hidup selama aku, dan sudah melihat cukup banyak penderita Erosi, tentu kau juga akan lebih paham."
  },
  AvgDialog_18708_Content_28 = {
    Text = "Jejak Pemburu Tengkorak?"
  },
  AvgDialog_18708_Content_29 = {
    Text = "\"Mengikuti jejak Pemburu Tengkorak\"—kau bisa merasakan posisinya?"
  },
  AvgDialog_18708_Content_3 = {
    Text = "Suara langkah kaki \"duk duk duk\" terdengar dari tangga, pintu kayu di belakangmu ditarik terbuka."
  },
  AvgDialog_18708_Content_30 = {
    Text = "Aku punya caraku sendiri. Tapi… demi menghindari menakuti anak kecil, lebih baik tidak kuungkapkan."
  },
  AvgDialog_18708_Content_32 = {
    Text = "Sekarang tolong tinggalkan tempat ini untuk sementara, Nyonya Daffodel. Jangan mengganggu penyelidikan Penjaga Rahasia."
  },
  AvgDialog_18708_Content_33 = {
    Text = "Eh, sekarang sudah tidak mencurigaiku lagi?"
  },
  AvgDialog_18708_Content_34 = {
    Text = "Belum bisa sepenuhnya menghapus kecurigaan terhadapmu. Tapi instingku mengatakan…"
  },
  AvgDialog_18708_Content_35 = {
    Text = "Kalau kau adalah \"Pemburu Tengkorak\", seharusnya kau melakukannya dengan jauh lebih rapi, tanpa meninggalkan bukti yang begitu ceroboh."
  },
  AvgDialog_18708_Content_36 = {
    Text = [[
Ah, apakah itu pujian untukku?
Tepatnya, itu fakta, bukan insting.]]
  },
  AvgDialog_18708_Content_37 = {
    Text = "…Jangan mengalihkan pembicaraan."
  },
  AvgDialog_18708_Content_38 = {
    Text = "Kalau kau baru tiba di kota hari ini, lalu siapa yang kulihat semalam?"
  },
  AvgDialog_18708_Content_39 = {
    Text = "Jangan-jangan kau punya saudari kembar?"
  },
  AvgDialog_18708_Content_4 = {
    Text = "%player%{Male=tuan,Female=nyonya}, tadi aku mendengar suara, apa yang terjadi?"
  },
  AvgDialog_18708_Content_41 = {
    Text = "Daffodel tampak berpikir dengan raut gelisah, lalu tiba-tiba mengulurkan tangannya ke arahmu."
  },
  AvgDialog_18708_Content_42 = {
    Text = "Ujung jari yang lembut mengusap wajahmu sesaat, lalu bergeser ke lehermu dan berhenti di sana, merasakan denyut dari dalam pembuluh darahmu."
  },
  AvgDialog_18708_Content_43 = {
    Text = "<Shake:……?>"
  },
  AvgDialog_18708_Content_44 = {
    Text = "Aku selalu mengira bahwa manusia adalah makhluk yang pandai menyamar."
  },
  AvgDialog_18708_Content_45 = {
    Text = "Kalian membungkus diri dalam daging dan darah yang serupa, mengucapkan kata-kata yang hampir sama, memiliki denyut nadi dan detak jantung yang nyaris tak berbeda…"
  },
  AvgDialog_18708_Content_46 = {
    Text = "Untuk waktu yang lama, aku tidak bisa membedakan kalian, sama seperti kalian juga tidak bisa membedakan aku."
  },
  AvgDialog_18708_Content_47 = {
    Text = "Maksudmu… kalian bukan kembar, melainkan memiliki hubungan yang lebih istimewa?"
  },
  AvgDialog_18708_Content_48 = {
    Text = "Mungkin saja. Kuberi kau tiga kesempatan, mau coba menebak?"
  },
  AvgDialog_18708_Content_49 = {
    Text = "…Aku menolak."
  },
  AvgDialog_18708_Content_5 = {
    Text = "I-ini... adalah...?!"
  },
  AvgDialog_18708_Content_50 = {
    Text = "Bahkan jika aku menebak dengan benar, kau tidak akan memberitahuku jawaban yang sebenarnya. Aku benar, kan?"
  },
  AvgDialog_18708_Content_51 = {
    Text = "Daffodil dengan santai menelusuri pembuluh darah di lehermu menggunakan ujung jarinya, senyum di matanya semakin dalam."
  },
  AvgDialog_18708_Content_52 = {
    Text = "Kau semakin memahami diriku, Penjaga Rahasia {Male=tuan,Female=nyonya}."
  },
  AvgDialog_18708_Content_53 = {
    Text = "Kau mundur setengah langkah menjauh dari telapak tangan Daffodil, melemparkan tatapan peringatan kepadanya."
  },
  AvgDialog_18708_Content_54 = {
    Text = "Di mata kalian, terlihat persis sama sudah dianggap kembar?"
  },
  AvgDialog_18708_Content_55 = {
    Text = "Secara umum, itu mungkin satu-satunya kemungkinan."
  },
  AvgDialog_18708_Content_56 = {
    Text = "Tapi kau dan aku sama-sama tahu, dunia tempat kita berada tidaklah \"umum\"."
  },
  AvgDialog_18708_Content_57 = {
    Text = "Ya. Hal yang paling disayangkan dari dunia ini adalah \"ketidaklaziman\"-nya."
  },
  AvgDialog_18708_Content_58 = {
    Text = "Menjadi sepasang saudari kembar yang tanpa beban, sepertinya juga tidak buruk."
  },
  AvgDialog_18708_Content_6 = {
    Text = "Kau maju dan menyibak tudung hitam Sang Pemburu Tengkorak, memperlihatkan wajah di baliknya."
  },
  AvgDialog_18708_Content_7 = {
    Text = "Tulang pipi tinggi, hidung bengkok bagai paruh elang, pipi yang kurus kering — sebuah wajah yang sama sekali asing."
  },
  AvgDialog_18708_Content_8 = {
    Text = "Pandai sekali memilih target, sampai mengejar kemari. Sebenarnya siapa kau?"
  },
  AvgDialog_18708_Content_9 = {
    Text = "Ugh aah... aah..."
  },
  AvgDialog_18709_Content_1 = {
    Text = "Tanah Hujan Pahit"
  },
  AvgDialog_18709_Content_10 = {
    Text = "Kamu bangkit dan bersandar di kepala tempat tidur, adegan demi adegan yang terjadi sebelumnya melintas di depan matamu, masih banyak masalah yang mendesak untuk diselesaikan."
  },
  AvgDialog_18709_Content_11 = {
    Text = "Sebaiknya tanyakan dulu apa saja yang diketahui Nona Orla."
  },
  AvgDialog_18709_Content_12 = {
    Text = "Tanyakan tentang Tua Freeman"
  },
  AvgDialog_18709_Content_13 = {
    Text = "Pak tua Freeman? Ternyata dia masih hidup……"
  },
  AvgDialog_18709_Content_14 = {
    Text = "Menurut penduduk desa, waktu muda dia orangnya optimis dan ceria, semua orang sangat menyukainya."
  },
  AvgDialog_18709_Content_15 = {
    Text = "Setelah <Yellow:wabah> itu, dia pergi meninggalkan Kota Reini, dan saat kembali dia sudah berubah total."
  },
  AvgDialog_18709_Content_16 = {Text = "Wabah?"},
  AvgDialog_18709_Content_17 = {
    Text = "Tiga tahun lalu, bencana korosi terjadi di utara Kota Reini, penduduk setempat menyebutnya wabah."
  },
  AvgDialog_18709_Content_18 = {
    Text = "Sekarang tempat itu sudah benar-benar menjadi tanah mati."
  },
  AvgDialog_18709_Content_19 = {
    Text = "Tanyakan tentang Daffodel"
  },
  AvgDialog_18709_Content_20 = {
    Text = "Nona Orla, tadi nada bicaramu saat menyebut Daffodel…… kalian pernah saling kenal?"
  },
  AvgDialog_18709_Content_21 = {
    Text = "Nyonya Daffodel……"
  },
  AvgDialog_18709_Content_22 = {
    Text = "Orla menatap lembaran buku di tangannya, senyum tipis tersungging di wajahnya."
  },
  AvgDialog_18709_Content_23 = {
    Text = "Nyonya Daffodel, dia…… pernah membantuku."
  },
  AvgDialog_18709_Content_24 = {
    Text = "15@1 tahun, San Pedro"
  },
  AvgDialog_18709_Content_25 = {
    Text = "Antologi puisi Ronsard ini adalah edisi langka satu-satunya, pastikan kamu menyimpannya baik-baik ya."
  },
  AvgDialog_18709_Content_26 = {
    Text = "Terima kasih banyak, Nyonya Daffodel. Tidak kusangka Anda benar-benar berhasil menemukannya……"
  },
  AvgDialog_18709_Content_27 = {
    Text = "\"Semoga kecantikanmu yang semarak bak mawar tetap abadi, hingga selamanya.\""
  },
  AvgDialog_18709_Content_28 = {
    Text = "Bait puisi yang indah, seleramu bagus."
  },
  AvgDialog_18709_Content_29 = {
    Text = "Ya, tapi aku lebih suka \"Dengan susu dan bunga segar, kupersembahkan penghormatan di saat ini……\""
  },
  AvgDialog_18709_Content_3 = {
    Text = "Kamu akhirnya sadar, Penjaga Rahasia {Male=tuan,Female=nyonya}."
  },
  AvgDialog_18709_Content_30 = {
    Text = "Ah…… maaf, aku melantur lagi."
  },
  AvgDialog_18709_Content_31 = {
    Text = "Aku tahu aturan \"Toko Barter\". Jadi, apa yang ingin Anda dapatkan dariku?"
  },
  AvgDialog_18709_Content_32 = {
    Text = "Hmm…… kalau begitu aku harus mengamatimu baik-baik, mawar kecilku."
  },
  AvgDialog_18709_Content_33 = {
    Text = "Tatapan tanpa emosi menyapu seluruh tubuh Aurla. Sang gadis tanpa sadar menegakkan punggungnya."
  },
  AvgDialog_18709_Content_34 = {
    Text = "Bisakah kau berikan aku salah satu kenanganmu?\nYang menyakitkan, menyedihkan…… kenangan tidak menyenangkan apa pun boleh."
  },
  AvgDialog_18709_Content_35 = {
    Text = "Kenangan yang tidak menyenangkan? I-itu bukan sesuatu yang baik. Anda berencana menggunakannya untuk apa……?"
  },
  AvgDialog_18709_Content_36 = {
    Text = "Aku berencana menggunakannya untuk sebuah eksperimen kecil, nanti kau akan tahu."
  },
  AvgDialog_18709_Content_37 = {
    Text = "Kelelahan akibat kesibukan berhari-hari terus menggerogoti sarafmu, dan kau kembali terlelap dalam kata-kata lembut Aurla."
  },
  AvgDialog_18709_Content_39 = {
    Text = "Entah sudah berapa lama berlalu, hujan rintik-rintik mulai turun di luar jendela."
  },
  AvgDialog_18709_Content_4 = {
    Text = "Aku ingat sepertinya aku pingsan, lalu……"
  },
  AvgDialog_18709_Content_40 = {
    Text = "Seseorang melangkah di atas jalan berlumpur, berjalan perlahan dan tanpa henti di tengah hujan."
  },
  AvgDialog_18709_Content_41 = {
    Text = "Mereka hanya muncul di malam yang diguyur hujan, langkah kaki tersembunyi di balik suara hujan, hanya perlu diam-diam berputar ke belakangmu……"
  },
  AvgDialog_18709_Content_42 = {
    Text = "Pemburu Tengkorak bukan satu orang, juga bukan dua orang. Pemburu Tengkorak adalah sebuah organisasi."
  },
  AvgDialog_18709_Content_43 = {
    Text = "Malam yang diguyur hujan, sendirian…… <Red:Bukankah itu persis situasimu sekarang?>"
  },
  AvgDialog_18709_Content_44 = {
    Text = "<Red:Zhi... krek krek...>"
  },
  AvgDialog_18709_Content_45 = {
    Text = "<RedBig:KRAK!>"
  },
  AvgDialog_18709_Content_46 = {Text = "?!"},
  AvgDialog_18709_Content_47 = {
    Text = "Kilatan petir pucat membelah kesunyian malam, kau tiba-tiba membuka mata dalam kegelapan."
  },
  AvgDialog_18709_Content_48 = {
    Text = "Seseorang sedang berdiri di samping tempat tidurmu."
  },
  AvgDialog_18709_Content_49 = {
    Text = "Tatapan berat itu bagaikan sabit yang basah dan dingin, menelusuri anggota tubuhmu, punggung, dan juga……"
  },
  AvgDialog_18709_Content_5 = {
    Text = "Nyonya Daffodil yang menggendongmu kembali, dia juga berpesan agar aku merawatmu dengan baik."
  },
  AvgDialog_18709_Content_50 = {
    Text = "Leher yang tak berpelindung."
  },
  AvgDialog_18709_Content_51 = {
    Text = "Kepala@1tengkorak@4"
  },
  AvgDialog_18709_Content_54 = {
    Text = "Ugh……!!"
  },
  AvgDialog_18709_Content_55 = {
    Text = "Kau terjatuh dari tempat tidur tanpa sempat bersiap, secara refleks menutup lehermu dengan tangan."
  },
  AvgDialog_18709_Content_56 = {
    Text = "Bayangan hitam yang memegang sabit berdiri di depan tempat tidur, hampir menyatu dengan gelapnya malam di belakangnya."
  },
  AvgDialog_18709_Content_57 = {
    Text = "Udara dipenuhi bau hujan dan karat besi. Darah merah gelap mengalir dari mata pisau yang putih dingin, lalu menetes satu per satu ke lantai."
  },
  AvgDialog_18709_Content_58 = {
    Text = "——Pemburu Tengkorak."
  },
  AvgDialog_18709_Content_6 = {
    Text = "Daffodil……?"
  },
  AvgDialog_18709_Content_7 = {
    Text = "Kamu mencium aroma yang familiar."
  },
  AvgDialog_18709_Content_8 = {
    Text = "Entah sejak kapan, sebuah vas berleher ramping telah diletakkan di samping tempat tidur, bunga narsis putih sedang merentangkan putiknya menghadap sinar matahari."
  },
  AvgDialog_18709_Content_9 = {
    Text = "Ini aroma dari tubuhnya……"
  },
  AvgDialog_18710_Content_1 = {
    Text = "Kerajaan Binatang Buas"
  },
  AvgDialog_18710_Content_10 = {
    Text = "Malam musim panas yang cerah itu, aku seperti biasa dengan rajin mengangkut \"hasil buruan\"-ku."
  },
  AvgDialog_18710_Content_11 = {
    Text = "<Shake:Kepala……lebih banyak kepala……>"
  },
  AvgDialog_18710_Content_12 = {
    Text = "Tap. Tap. Tap."
  },
  AvgDialog_18710_Content_13 = {
    Text = "Langkah kaki yang ringan mendekat tanpa suara, sebuah suara lembut terdengar dari atas kepalaku."
  },
  AvgDialog_18710_Content_14 = {
    Text = "Heh……lihat apa yang kutemukan? Seekor binatang buas kecil yang tersesat."
  },
  AvgDialog_18710_Content_15 = {
    Text = "Malam itu, seorang wanita datang menghampiriku."
  },
  AvgDialog_18710_Content_16 = {
    Text = [[
Ketika dia mendekatiku, aku mencium aroma yang sangat harum.
Itu adalah aroma bunga dan kabut.]]
  },
  AvgDialog_18710_Content_17 = {
    Text = "Itu adalah aroma dari dunia lain, yang dengan kerajaanku bagaikan siang dan malam yang jelas terpisah, seharusnya tak pernah memiliki persinggungan apa pun."
  },
  AvgDialog_18710_Content_18 = {
    Text = "Tapi dia tetap melangkah melewati genangan air kotor yang berbau busuk, menembus bayangan kota, dan mengulurkan tangan kepadaku."
  },
  AvgDialog_18710_Content_19 = {
    Text = "Dia berkata……"
  },
  AvgDialog_18710_Content_2 = {
    Text = "Aku adalah seekor binatang buas……Aku adalah orang yang sakit.\n\nAku adalah orang yang tak bisa disembuhkan."
  },
  AvgDialog_18710_Content_20 = {
    Text = "Mau ikut denganku, hewan liar kecil?"
  },
  AvgDialog_18710_Content_21 = {
    Text = "5:00, Utara Kota Reini"
  },
  AvgDialog_18710_Content_22 = {
    Text = "Tempat ini benar-benar……tandus sekali."
  },
  AvgDialog_18710_Content_23 = {
    Text = "Tiga tahun lalu, di sini muncul sebuah <Yellow:Celah Erosi tingkat S>. Sumber air, vegetasi……semua ekosistem mengalami kerusakan parah."
  },
  AvgDialog_18710_Content_24 = {
    Text = "Untungnya korban jiwa relatif sedikit, para Penduduk telah meninggalkan tempat atas pengaturan Dewan Sensor."
  },
  AvgDialog_18710_Content_25 = {
    Text = "Kamu memandang tembok-tembok yang gersang dan pohon-pohon kering yang pucat di hadapanmu."
  },
  AvgDialog_18710_Content_26 = {
    Text = "Kalau bukan karena Erosi, tempat ini seharusnya menjadi padang hijau yang dipenuhi bunga lilac. Saat angin bertiup, ombak rumput akan bergoyang naik turun, bagaikan lautan hijau."
  },
  AvgDialog_18710_Content_27 = {
    Text = "Kamu yakin Pemburu Tengkorak ada di sini, Nyonya Daffodel?"
  },
  AvgDialog_18710_Content_28 = {
    Text = "Yang menjawabmu hanyalah suara parau gagak."
  },
  AvgDialog_18710_Content_29 = {
    Text = "Eh, Nyonya Daffodel menghilang?"
  },
  AvgDialog_18710_Content_3 = {
    Text = "Di siang hari, aku bersembunyi di balik bayangan kota, terlentang dengan perut menghadap langit, tertidur pulas."
  },
  AvgDialog_18710_Content_30 = {
    Text = "Nah, itulah akibat terlalu mudah percaya orang lain."
  },
  AvgDialog_18710_Content_31 = {
    Text = "Uhuk uhuk. Dia memang selalu begitu, pergi tanpa jejak. Aku sudah terbiasa."
  },
  AvgDialog_18710_Content_32 = {
    Text = "Tidak apa-apa, aku bisa menyelidiki sendiri. Pasti ada sesuatu yang bisa ditemukan di sini……"
  },
  AvgDialog_18710_Content_33 = {
    Text = "<Big:GRRRUMMMM——!!>"
  },
  AvgDialog_18710_Content_34 = {
    Text = "Dari balik awan rendah yang menggantung, terdengar gemuruh guntur yang berat, daun-daun kering berdesir ditiup angin musim gugur."
  },
  AvgDialog_18710_Content_35 = {
    Text = "Ini pertanda hujan akan turun."
  },
  AvgDialog_18710_Content_36 = {
    Text = "Kenapa dia hanya muncul saat hujan?"
  },
  AvgDialog_18710_Content_37 = {
    Text = "Karena saat hujan turun, darah bisa bercampur dengan air hujan dan mengalir ke saluran pembuangan."
  },
  AvgDialog_18710_Content_38 = {
    Text = "Ya, mengalir ke selokan, ke dalam peti mati, dan ke parit kecil di sampingmu……"
  },
  AvgDialog_18710_Content_39 = {
    Text = "<Red:Zhi... krek krek...>"
  },
  AvgDialog_18710_Content_4 = {
    Text = "Di malam hari, aku berkeliaran di jalanan bak hantu, mencari satu demi satu tengkorak."
  },
  AvgDialog_18710_Content_40 = {
    Text = "Malam hujan yang gelap……tidak, kenapa aku mulai berkhayal lagi."
  },
  AvgDialog_18710_Content_41 = {
    Text = "Kamu menggelengkan kepala keras-keras, berusaha mengusir pikiran-pikiran kacau dari benakmu."
  },
  AvgDialog_18710_Content_42 = {
    Text = "Waktu yang tersisa tidak banyak, kamu harus segera bertindak."
  },
  AvgDialog_18710_Content_5 = {
    Text = "<Red:Tengkorak. Tengkorak. Tengkorak.>"
  },
  AvgDialog_18710_Content_6 = {
    Text = "<RedBig:Tengkorak.\n        Tengkorak.\n                Tengkorak.\n                        Tengkorak.\n                                Tengkorak.\n                                        Tengkorak……>"
  },
  AvgDialog_18710_Content_7 = {
    Text = [[
Otakku tak lagi mampu memikirkan tentang kelangsungan hidup, cinta, dan martabat.

Sudah lama ia dipenuhi oleh khayalan-khayalan yang haus dan kelaparan.]]
  },
  AvgDialog_18710_Content_8 = {
    Text = "Aku adalah orang yang tak bisa disembuhkan."
  },
  AvgDialog_18710_Content_9 = {
    Text = "15@1, Kota San Pedro"
  },
  AvgDialog_18711_Content_1 = {
    Text = "AAAAAAH——!!"
  },
  AvgDialog_18711_Content_10 = {
    Text = "Tanpa menghiraukan lendir kotor dan noda darah yang memenuhi lantai, dia berjongkok dan menatap makhluk yang terus meronta di hadapannya."
  },
  AvgDialog_18711_Content_11 = {
    Text = "Berhenti mencari. Semuanya sudah lenyap, dan tidak akan pernah kembali lagi."
  },
  AvgDialog_18711_Content_12 = {
    Text = "Yang kau butuhkan bukan benda-benda itu."
  },
  AvgDialog_18711_Content_13 = {
    Text = "Tidak butuh……? Tidak, kepala@1berikan padaku……"
  },
  AvgDialog_18711_Content_15 = {
    Text = "Kau tahu? Sebenarnya……kita sama.\nAku memahami penderitaanmu."
  },
  AvgDialog_18711_Content_16 = {
    Text = "15@1, Kota San Pedro"
  },
  AvgDialog_18711_Content_17 = {
    Text = "Maukah kau ikut denganku, hewan kecil yang liar? Kau butuh pertolongan."
  },
  AvgDialog_18711_Content_18 = {
    Text = "Musim panas tahun 15@1, seorang wanita mengulurkan tangannya kepadaku."
  },
  AvgDialog_18711_Content_19 = {
    Text = "Mungkin karena aroma tubuhnya begitu harum, atau mungkin karena dia terlihat sangat lembut."
  },
  AvgDialog_18711_Content_2 = {
    Text = "Gumpalan daging yang mengambang runtuh dengan dahsyat, cairan lebur dan lendir kelabu membanjir keluar bagaikan air pasang, hingga akhirnya menyisakan tubuh ringkih Harriet."
  },
  AvgDialog_18711_Content_20 = {
    Text = "Singkatnya, aku tidak menolaknya."
  },
  AvgDialog_18711_Content_21 = {
    Text = "Dengan polos aku meraih tangannya, dan juga meraih takdirku di masa depan."
  },
  AvgDialog_18711_Content_22 = {
    Text = "Uhuk uhuk…"
  },
  AvgDialog_18711_Content_23 = {
    Text = "Kau sekarat, Daffdail."
  },
  AvgDialog_18711_Content_24 = {
    Text = "Anak bodoh……sudah kuajari bertahun-tahun, masih belum belajar berbicara dengan baik."
  },
  AvgDialog_18711_Content_25 = {
    Text = "Jangan menangis……uhuk uhuk……"
  },
  AvgDialog_18711_Content_26 = {
    Text = "<Shake:A-aku tidak……>"
  },
  AvgDialog_18711_Content_27 = {
    Text = "Ambillah kepalaku. Kuserahkan identitas dan wajahku, serta toko kecil ini kepadamu."
  },
  AvgDialog_18711_Content_28 = {Text = "?!"},
  AvgDialog_18711_Content_29 = {
    Text = "Aku tahu, uhuk uhuk……kau selalu mendambakan bisa berjalan di dunia layaknya manusia biasa."
  },
  AvgDialog_18711_Content_3 = {
    Text = "Kepala-kepala berwarna abu-abu pucat bermunculan satu per satu, namun dalam sekejap mata lenyap tanpa jejak."
  },
  AvgDialog_18711_Content_30 = {
    Text = "Kau bersembunyi di sudut mengamatiku bagaimana aku berbicara, bagaimana aku berjalan, diam-diam memakai pakaianku saat aku tidak ada, bahkan menyamar sebagai diriku untuk keluar berteman……"
  },
  AvgDialog_18711_Content_31 = {
    Text = "Aku selalu mengetahuinya."
  },
  AvgDialog_18711_Content_32 = {
    Text = "Maafkan aku, Daffdail, aku tidak sengaja……"
  },
  AvgDialog_18711_Content_33 = {
    Text = "Sekarang aku mengabulkan keinginanmu, uhuk uhuk……tapi kau harus berjanji kepadaku……"
  },
  AvgDialog_18711_Content_34 = {
    Text = "Mulai sekarang tidak boleh sembarangan mengambil kepala orang yang tidak bersalah. Dan jika kau bertemu orang yang sepertimu, kau juga harus menolong mereka."
  },
  AvgDialog_18711_Content_35 = {
    Text = "Sama seperti aku membantumu sekarang."
  },
  AvgDialog_18711_Content_36 = {
    Text = "<Shake:Selamatkan aku, selamatkan aku……>"
  },
  AvgDialog_18711_Content_37 = {
    Text = "Harriet mengeluarkan rintihan seperti hewan yang terpojok, mengulurkan tangannya yang gemetar ke arah Daffodil."
  },
  AvgDialog_18711_Content_39 = {
    Text = "Saat itu…… ketika kau bertemu suamimu di pemakaman, kau pasti sangat putus asa, bukan?"
  },
  AvgDialog_18711_Content_4 = {
    Text = "Kepala@1tidak……"
  },
  AvgDialog_18711_Content_40 = {
    Text = "Freeman…… heh@2……"
  },
  AvgDialog_18711_Content_41 = {
    Text = "Kita menanggung kutukan yang sama, tapi aku jauh lebih beruntung darimu."
  },
  AvgDialog_18711_Content_42 = {
    Text = "Saat aku belum mengerti apa itu baik dan buruk, nyonya itulah yang mengulurkan tangan kepadaku."
  },
  AvgDialog_18711_Content_43 = {
    Text = "Daffodil berjongkok di hadapan Nyonya Harriet, dengan lembut menggenggam tangannya yang penuh luka dan berlumuran cairan korosi."
  },
  AvgDialog_18711_Content_44 = {
    Text = "Aku belajar berbicara dan berjalan sepertinya, menjalani hidup menjadi sosok seperti dirinya."
  },
  AvgDialog_18711_Content_45 = {
    Text = "Hati-hati, Nyonya Daffodil! Tangan Harriet penuh dengan cairan korosi——"
  },
  AvgDialog_18711_Content_46 = {
    Text = "Sst…… aku masih ada yang ingin kubicarakan dengannya."
  },
  AvgDialog_18711_Content_47 = {
    Text = "Daffodil terus menatap Harriet. Sebuah ikatan tersembunyi mengalir di antara keduanya, menghalangi segala kegaduhan dari luar."
  },
  AvgDialog_18711_Content_48 = {
    Text = "Sekarang akhirnya aku juga bisa mengulurkan tangan kepada orang lain seperti yang dia lakukan…… tapi aku datang terlalu terlambat."
  },
  AvgDialog_18711_Content_49 = {
    Text = "Kabut ungu muda perlahan naik, melayang pelan di dalam ruangan yang remang."
  },
  AvgDialog_18711_Content_5 = {
    Text = "Harriet yang kehilangan kepalanya menggeliat gelisah, pembuluh darah di lehernya bergetar cepat, mengeluarkan dengungan samar dari dalamnya."
  },
  AvgDialog_18711_Content_50 = {
    Text = "Kau kembali mencium aroma bunga yang familiar itu, membawa kelembapan kabut tengah malam, meredakan bau darah pekat yang memenuhi ruangan."
  },
  AvgDialog_18711_Content_51 = {
    Text = "Daffodil meletakkan tangannya dengan lembut di sisi Nyonya Harriet."
  },
  AvgDialog_18711_Content_52 = {
    Text = "Pergilah dengan tenang, Nyonya Harriet. Kau tidak akan merasakan rasa sakit apa pun."
  },
  AvgDialog_18711_Content_53 = {
    Text = "Dari telapak tangannya, sebuah celah dengan cepat terbuka, perlahan menelan Harriet ke dalamnya……"
  },
  AvgDialog_18711_Content_55 = {
    Text = "Kalau bertemu suamiku@2tolong bilang padanya untuk berhenti minum."
  },
  AvgDialog_18711_Content_56 = {
    Text = "Dan juga……"
  },
  AvgDialog_18711_Content_57 = {
    Text = "Rongga tenggorokan Harriet yang terekspos bergetar pelan, namun akhirnya seperti daun yang layu, tak lagi mengeluarkan sepatah suara pun."
  },
  AvgDialog_18711_Content_58 = {
    Text = "Dia melepaskan tangan Daffodel, dan jatuh tanpa suara ke dalam celah dimensi yang tak berdasar."
  },
  AvgDialog_18711_Content_59 = {
    Text = "<Change>Selamat tinggal, selamat tinggal……"
  },
  AvgDialog_18711_Content_6 = {
    Text = "Berikan@2kembalikan kepalaku……"
  },
  AvgDialog_18711_Content_60 = {
    Text = "Akhirnya…… sudah berakhir? Kau membawanya ke mana, Nyonya Daffodel?"
  },
  AvgDialog_18711_Content_61 = {
    Text = "Lautan Originium. Dia akan memiliki waktu yang panjang untuk mengingat…… atau melupakan semua yang terjadi."
  },
  AvgDialog_18711_Content_62 = {
    Text = "Nyonya Harriet…"
  },
  AvgDialog_18711_Content_63 = {
    Text = "Belum sempat kau merapikan pikiranmu yang kacau, kau sudah mendengar samar-samar langkah kaki dari luar."
  },
  AvgDialog_18711_Content_64 = {
    Text = "Siapa itu? Ikuti dan lihat."
  },
  AvgDialog_18711_Content_65 = {
    Text = "I-ini aku…… hik."
  },
  AvgDialog_18711_Content_66 = {
    Text = "Lama tak jumpa, detektif kecil! Masih ingat aku? Penjaga makam tua Freeman!"
  },
  AvgDialog_18711_Content_67 = {
    Text = "Freeman tua menjinjing sebotol brandy, terus-menerus cegukan, dengan senyum canggung tersungging di sudut bibirnya."
  },
  AvgDialog_18711_Content_68 = {
    Text = "Freeman tua?! Apa yang kau lakukan di sini…… kau mendengar semuanya?"
  },
  AvgDialog_18711_Content_69 = {Text = "Aku..."},
  AvgDialog_18711_Content_7 = {
    Text = "Dia merangkak ke sana kemari di lantai dengan panik, kedua lengannya yang kurus kering mengayun ke segala arah. Bagaikan binatang buas yang terpojok, hanya mengeluarkan rintihan putus asa dari tenggorokannya."
  },
  AvgDialog_18711_Content_70 = {
    Text = "Aku juga tidak tahu apa yang terjadi, setelah minum aku tertidur pulas."
  },
  AvgDialog_18711_Content_71 = {
    Text = "Apa yang terjadi di antaranya juga tidak ingat, pokoknya entah bagaimana aku sudah sampai di sini."
  },
  AvgDialog_18711_Content_72 = {
    Text = "Lalu aku dengar ada keributan di dalam…… Tenang saja, aku sama sekali tidak mengintip ke dalam!"
  },
  AvgDialog_18711_Content_73 = {
    Text = [[
Freeman tua berkata begitu, lalu tiba-tiba mendekat, mengedipkan mata dengan penuh misteri ke arahmu.
Kau tak sempat menghindar, dan mencium bau menyengat rokok serta alkohol.]]
  },
  AvgDialog_18711_Content_74 = {
    Text = "Kalian sudah membunuh si Pemburu Tengkorak itu, kan?"
  },
  AvgDialog_18711_Content_75 = {
    Text = "Ku-kurang lebih begitulah, mulai sekarang tidak ada yang akan mengganggu tidurmu lagi."
  },
  AvgDialog_18711_Content_76 = {
    Text = "Kau mencubit hidungmu dan mundur tiga langkah, mengangguk dengan seadanya."
  },
  AvgDialog_18711_Content_77 = {Text = "Oh……"},
  AvgDialog_18711_Content_78 = {
    Text = "Pak tua Freeman mengusap rambutnya yang berantakan, matanya tampak sedikit linglung."
  },
  AvgDialog_18711_Content_79 = {
    Text = "Bagus, bagus……"
  },
  AvgDialog_18711_Content_80 = {
    Text = "Tuan Freeman. Mulai sekarang…… jangan minum alkohol lagi."
  },
  AvgDialog_18711_Content_81 = {
    Text = "Berhenti minum? Tidak tidak tidak…… lebih realistis kalau kau langsung mengambil nyawa tua ini saja."
  },
  AvgDialog_18711_Content_82 = {
    Text = "Ini permintaan seorang teman yang dititipkan kepadaku. Dia pergi ke tempat yang sangat jauh…… tapi dia selalu mengkhawatirkanmu."
  },
  AvgDialog_18711_Content_83 = {
    Text = "Teman? Hehe, jangan membohongiku. Mana mungkin si tua Freeman punya teman……"
  },
  AvgDialog_18711_Content_84 = {
    Text = "Dia melambaikan tangan dengan asal kepada kalian, sambil bergumam dan berjalan pergi dengan langkah gontai."
  },
  AvgDialog_18711_Content_85 = {
    Text = "Dia tampak sangat kehilangan. Sayang sekali……\nDia tidak akan pernah tahu mengapa dirinya merasa kehilangan."
  },
  AvgDialog_18711_Content_86 = {
    Text = "Sama seperti dia tidak mengerti mengapa dia datang ke sini."
  },
  AvgDialog_18711_Content_87 = {
    Text = "Ini juga yang diharapkan oleh Nyonya Harriet, bukan."
  },
  AvgDialog_18711_Content_88 = {
    Text = "Jangan beritahu dia apa pun…… biarkan dia tetap seperti sekarang, minum sambil bernyanyi, menjalani sisa hidupnya dalam ketidaktahuan."
  },
  AvgDialog_18711_Content_89 = {
    Text = "Dalam arti tertentu, ini juga sebuah keberuntungan. Seumur hidup manusia, sangatlah singkat……"
  },
  AvgDialog_18711_Content_9 = {
    Text = "Daphodel menghela napas pelan, kesedihan yang tak terkatakan berkilat di dasar matanya."
  },
  AvgDialog_18711_Content_90 = {
    Text = "Kau menatap kepergian pak tua Freeman."
  },
  AvgDialog_18711_Content_91 = {
    Text = "Sosok bungkuknya menggigil tertiup angin yang dingin, semakin kecil, semakin kecil……"
  },
  AvgDialog_18711_Content_92 = {
    Text = "Hingga akhirnya ditelan sepenuhnya oleh garis cakrawala di kejauhan."
  },
  AvgDialog_18711_Content_93 = {
    Text = "Kemudian kau melihat seberkas cahaya fajar menyibak kabut tipis, perlahan menerangi langit."
  },
  AvgDialog_18711_Content_94 = {
    Text = "Hujan sudah berhenti…… Daffodil."
  },
  AvgDialog_18712_Content_1 = {
    Text = "Nyanyian Bayangan"
  },
  AvgDialog_18712_Content_10 = {
    Text = "Berikan padaku……<Big:Kembalikan padaku>!"
  },
  AvgDialog_18712_Content_11 = {
    Text = "Sulur-sulur hitam terus memanjang dari dalam lehernya, dengan rakus menyerap kepala-kepala yang bergelinding di tanah satu per satu ke dalam tubuhnya."
  },
  AvgDialog_18712_Content_12 = {
    Text = "Setiap kali menelan satu kepala, tubuhnya membesar sedikit."
  },
  AvgDialog_18712_Content_13 = {
    Text = "Yang akhirnya berdiri di hadapan kalian adalah gumpalan daging raksasa yang bertumpuk-tumpuk."
  },
  AvgDialog_18712_Content_14 = {
    Text = "<Bold:——!!!>"
  },
  AvgDialog_18712_Content_15 = {
    Text = "Kepala-kepala ini……aku pernah melihatnya."
  },
  AvgDialog_18712_Content_16 = {
    Text = "Kau pernah melihat sebagian dari mereka, di dalam berkas yang diberikan kepolisian kepadamu, di dalam foto-foto korban yang dingin dan berjajar rapi itu."
  },
  AvgDialog_18712_Content_17 = {
    Text = "Kau pernah melihat mereka."
  },
  AvgDialog_18712_Content_18 = {
    Text = "Sekarang kau paham, kan? Tidak pernah ada organisasi Pemburu Tengkorak."
  },
  AvgDialog_18712_Content_19 = {
    Text = "<Yellow:Dari awal hingga akhir, Pemburu Tengkorak hanyalah satu orang.>"
  },
  AvgDialog_18712_Content_2 = {
    Text = "Nyonya Daffodel…?!"
  },
  AvgDialog_18712_Content_20 = {
    Text = "<RedShake:Tidak cukup……>"
  },
  AvgDialog_18712_Content_21 = {
    Text = "<RedShake:Tidak cukup……tidak cukup……>"
  },
  AvgDialog_18712_Content_22 = {
    Text = "Tubuh yang membengkak dipenuhi kepala-kepala dengan ekspresi kesakitan dan meraung-raung, mereka bergerak naik-turun dan bernapas bersama lemak yang lembut……"
  },
  AvgDialog_18712_Content_23 = {
    Text = "Gelombang spiritual yang begitu familiar……Ilusi Seribu Wajah?!"
  },
  AvgDialog_18712_Content_24 = {
    Text = "Itu hanyalah kekuatan yang berasal dari sumber yang sama dengan Ilusi Seribu Wajah, karena itulah aku bisa merasakan posisinya."
  },
  AvgDialog_18712_Content_25 = {
    Text = [[
Sekarang dia sudah benar-benar kehilangan kendali, dan akan terus membesar.
Kita harus menyelesaikan ini dengan cepat.]]
  },
  AvgDialog_18712_Content_26 = {Text = "Jadi..."},
  AvgDialog_18712_Content_27 = {
    Text = "Daffdel tiba-tiba mendekat padamu, menggenggam kunci perak di dadamu."
  },
  AvgDialog_18712_Content_28 = {
    Text = "Maukah kau bekerja sama denganku, %player%?"
  },
  AvgDialog_18712_Content_29 = {
    Text = "Eh, kau bersedia terhubung denganku?"
  },
  AvgDialog_18712_Content_3 = {
    Text = "Maaf… Demi memancingnya keluar, aku sengaja meninggalkanmu di sini. Kau pasti menyalahkanku dalam hati, kan?"
  },
  AvgDialog_18712_Content_30 = {
    Text = "Setelah perjalanan bersama dan kerja sama kita selama ini, kupikir seharusnya sudah ada keselarasan di antara kita."
  },
  AvgDialog_18712_Content_31 = {
    Text = "Atau… kau tidak yakin bisa mengendalikanku?"
  },
  AvgDialog_18712_Content_32 = {
    Text = "Heh… kalau begitu, mau kita coba?"
  },
  AvgDialog_18712_Content_33 = {
    Text = "Kau memejamkan mata, memusatkan pikiran dan mengaktifkan kunci perak di dadamu."
  },
  AvgDialog_18712_Content_34 = {
    Text = "Tak lama kemudian, kunci perak memancarkan getaran lemah yang terus-menerus, dan cahaya putih dingin yang memancar darinya dengan cepat menelan seluruh ruangan gelap."
  },
  AvgDialog_18712_Content_35 = {
    Text = "Kau seolah berada di tengah lautan waktu yang tak bertepi."
  },
  AvgDialog_18712_Content_36 = {
    Text = "Energi asing terus bergejolak di dadamu, bagaikan gelombang dahsyat yang melintas dimensi."
  },
  AvgDialog_18712_Content_37 = {
    Text = [[
Di seberang lautan waktu yang luas, Daphodel menatapmu dalam diam.
Pada saat ini, wajahnya samar-samar menampakkan ekspresi yang belum pernah kau lihat sebelumnya.]]
  },
  AvgDialog_18712_Content_38 = {
    Text = "Itu adalah kepercayaan diri yang mutlak dan tak terbantahkan, yang diasah selama ratusan tahun dari tak terhitung pertarungan dan konfrontasi."
  },
  AvgDialog_18712_Content_39 = {
    Text = "Berangkat, %player%. Aku sudah siap."
  },
  AvgDialog_18712_Content_5 = {
    Text = "Tunggu sampai kita keluar, baru kita hitung-hitungan."
  },
  AvgDialog_18712_Content_6 = {
    Text = "<Shake:Kepala… kembalikan kepalaku…>"
  },
  AvgDialog_18712_Content_7 = {
    Text = "\"Harriet\" terhuyung-huyung melangkah dua langkah ke depan, mengulurkan tangan meraba-raba dengan sia-sia di atas lehernya."
  },
  AvgDialog_18712_Content_8 = {
    Text = "Satu kali, dua kali……"
  },
  AvgDialog_18712_Content_9 = {
    Text = "Setelah menyadari kepalanya sudah lama tidak ada, dia mengeluarkan jeritan-jeritan memilukan."
  },
  AvgDialog_18713_Content_1 = {
    Text = "Hujan turun."
  },
  AvgDialog_18713_Content_10 = {
    Text = "Kamu mengusap asal air hujan di wajahmu, mengerjapkan mata, baru kemudian memastikan bahwa memang ada seseorang yang berbicara padamu."
  },
  AvgDialog_18713_Content_11 = {
    Text = "Kukira sudah tidak ada orang yang tinggal di sini."
  },
  AvgDialog_18713_Content_12 = {
    Text = "Sebagian besar orang sudah pindah."
  },
  AvgDialog_18713_Content_13 = {
    Text = "Mereka yang sakit dan sudah lanjut usia memilih untuk tetap tinggal, ada juga beberapa yang pergi ke luar, lalu kembali lagi……"
  },
  AvgDialog_18713_Content_14 = {
    Text = "Tidak semua orang bisa beradaptasi dengan kehidupan di luar sana."
  },
  AvgDialog_18713_Content_15 = {
    Text = "Begitu rupanya. Tapi tadi aku tidak melihat siapa pun."
  },
  AvgDialog_18713_Content_16 = {
    Text = "……Mereka tidak suka berurusan dengan orang luar."
  },
  AvgDialog_18713_Content_17 = {
    Text = "Kamu mengedarkan pandangan ke sekeliling, melihat rumah-rumah yang jarang dan bobrok."
  },
  AvgDialog_18713_Content_18 = {
    Text = "Dari balik jendela yang gelap, samar-samar terlihat tatapan diam yang penuh kehati-hatian dan permusuhan."
  },
  AvgDialog_18713_Content_19 = {
    Text = "Selamat siang, Nyonya. Boleh saya bertanya——"
  },
  AvgDialog_18713_Content_2 = {
    Text = "Kamu berjalan sendirian di tengah hujan, air hujan yang dingin dan basah meresap ke pakaianmu hingga basah kuyup, menempel erat di kulit."
  },
  AvgDialog_18713_Content_20 = {
    Text = "Apakah Anda pernah melihat sesuatu yang aneh?"
  },
  AvgDialog_18713_Content_21 = {
    Text = "Sesuatu yang aneh……?"
  },
  AvgDialog_18713_Content_22 = {
    Text = "Ehm……manusia, atau binatang buas, yang pokoknya bergerak sangat cepat."
  },
  AvgDialog_18713_Content_23 = {
    Text = "Wanita itu menggelengkan kepalanya."
  },
  AvgDialog_18713_Content_24 = {
    Text = "Sudah lama sekali tidak ada yang datang ke sini, bahkan burung nasar pun enggan mendekat."
  },
  AvgDialog_18713_Content_25 = {
    Text = "Apakah Anda pernah melihat Dafne?"
  },
  AvgDialog_18713_Content_26 = {
    Text = "Permisi, apakah Anda pernah melihat seorang, hmm……wanita yang sangat cantik, mengenakan gaun panjang berwarna ungu?"
  },
  AvgDialog_18713_Content_27 = {
    Text = "Wanita itu menggelengkan kepalanya."
  },
  AvgDialog_18713_Content_28 = {
    Text = "Sudah lama sekali tidak ada yang datang ke sini, bahkan burung nasar pun enggan mendekat."
  },
  AvgDialog_18713_Content_29 = {
    Text = "<Big:Grrrrumm——>"
  },
  AvgDialog_18713_Content_3 = {
    Text = "Kamu melewati rumah-rumah terbengkalai satu demi satu, melewati makam-makam satu demi satu."
  },
  AvgDialog_18713_Content_30 = {
    Text = "Hujan semakin deras, langit dan bumi menjadi kelabu."
  },
  AvgDialog_18713_Content_31 = {
    Text = "Sosok wanita itu mulai kabur, tak fokus, bahkan suaranya pun semakin sayup……"
  },
  AvgDialog_18713_Content_32 = {
    Text = "Masuklah, {Male=tuan,Female=nyonya}. Hujan sederas ini, Anda bisa sakit……"
  },
  AvgDialog_18713_Content_34 = {
    Text = "Dengan senang hati."
  },
  AvgDialog_18713_Content_4 = {
    Text = "Ke mana pun kamu pergi, yang terlihat hanyalah luka dan kehancuran, semuanya tandus."
  },
  AvgDialog_18713_Content_5 = {
    Text = "Hanya hujan. Hujan yang tak henti-henti dan dingin membeku, menemanimu sepanjang perjalanan."
  },
  AvgDialog_18713_Content_6 = {
    Text = "{Male=Tuan,Female=Nyonya}..."
  },
  AvgDialog_18713_Content_7 = {
    Text = "Seorang wanita tua berdiri di depan gubuk kayu, melambaikan tangan ke arahmu."
  },
  AvgDialog_18713_Content_8 = {
    Text = "Dia mengenakan gaun berwarna kusam, wajahnya tersembunyi di balik tirai hujan kelabu, menyatu sempurna dengan rumah bobrok di belakangnya."
  },
  AvgDialog_18713_Content_9 = {
    Text = "{Male=Tuan,Female=Nyonya}, kamu terlihat kedinginan……mau masuk dan duduk sebentar?"
  },
  AvgDialog_18714_Content_1 = {
    Text = "Badai Akan Datang"
  },
  AvgDialog_18714_Content_10 = {
    Text = "Sendirian?!"
  },
  AvgDialog_18714_Content_11 = {
    Text = "Wah, wajahmu terlihat sangat pucat. Perlu bantuan?"
  },
  AvgDialog_18714_Content_12 = {
    Text = "Mundur dulu, ada yang ingin kutanyakan padamu."
  },
  AvgDialog_18714_Content_13 = {
    Text = "Kata-kata itu sungguh menyakitkan. Kenapa, apakah ada bau tak sedap yang menempel di tubuhku?"
  },
  AvgDialog_18714_Content_14 = {
    Text = "Aku tidak tahu……mungkin bau orang mati?"
  },
  AvgDialog_18714_Content_15 = {
    Text = "Beren Stoker, Dwight Williams……apakah nama-nama ini terdengar familiar?"
  },
  AvgDialog_18714_Content_17 = {
    Text = "Begitu rupanya, kau mencurigaiku sebagai Pemburu Tengkorak."
  },
  AvgDialog_18714_Content_18 = {
    Text = "Dan kau tahu dengan jelas nama-nama korban Pemburu Tengkorak."
  },
  AvgDialog_18714_Content_2 = {
    Text = "Daffodil berjalan menghampirimu dengan anggun dan santai, seolah-olah sedang berlibur di sini."
  },
  AvgDialog_18714_Content_20 = {
    Text = "Kupikir, setelah kebersamaan kita di Lai, setidaknya ada sedikit rasa saling percaya di antara kita."
  },
  AvgDialog_18714_Content_21 = {
    Text = "Pemburu Tengkorak mengambil sebuah <Yellow:tengkorak berharga> dariku, jadi aku datang untuk melakukan sedikit investigasi. Sesederhana itu."
  },
  AvgDialog_18714_Content_22 = {
    Text = "Tengkorak berharga… milik siapa?"
  },
  AvgDialog_18714_Content_24 = {
    Text = "Daphdale memandangmu dengan senyum manis. Setiap kali dia tidak ingin menjawab pertanyaan, dia selalu memasang senyuman seperti itu."
  },
  AvgDialog_18714_Content_25 = {
    Text = "Kalau aku tidak salah ingat, kau selalu punya kebiasaan mengoleksi tengkorak. Jarak garis lurus dari Reini ke Lai kurang dari 15 mil, perjalanan pulang-pergi juga cukup mudah."
  },
  AvgDialog_18714_Content_26 = {
    Text = "Maaf, aku hanya bertanggung jawab menerima tengkorak, bukan memproduksi tengkorak."
  },
  AvgDialog_18714_Content_27 = {
    Text = "Ada perbedaan halus di antara keduanya… Aku yakin kau pasti bisa memahaminya, Penjaga Rahasia {Male=tuan,Female=nyonya} yang cerdas?"
  },
  AvgDialog_18714_Content_28 = {
    Text = [[
Baik, aku paham.
Kalau begitu, semalam pukul 8:15, kau ada di mana dan sedang apa?]]
  },
  AvgDialog_18714_Content_29 = {
    Text = "Coba kuingat… Toko baru saja mendapat stok garam mandi baru, jadi aku mencobanya di bak mandi."
  },
  AvgDialog_18714_Content_3 = {Text = "Kau……?"},
  AvgDialog_18714_Content_30 = {
    Text = "Kenapa, mau dengar detail percobaan mandiku?"
  },
  AvgDialog_18714_Content_31 = {
    Text = "Oh ya? Tapi saat aku melihatmu semalam, kau berdiri sendirian di bawah lampu jalan, menjinjing sebuah kepala manusia."
  },
  AvgDialog_18714_Content_32 = {
    Text = "Dan itu sama sekali tidak terlihat seperti garam mandi."
  },
  AvgDialog_18714_Content_34 = {
    Text = "Maksudmu… kau semalam melihat seseorang yang wajahnya persis sama denganku?"
  },
  AvgDialog_18714_Content_35 = {
    Text = "Kau mengingat kembali Daphdale yang kau lihat semalam."
  },
  AvgDialog_18714_Content_36 = {
    Text = "Tidak diragukan lagi, wajah mereka nyaris sama, tetapi aura dan ekspresi mereka sangat berbeda."
  },
  AvgDialog_18714_Content_37 = {
    Text = "Atau lebih tepatnya, aku melihat <Yellow:kau>, bukan seseorang yang wajahnya mirip denganmu."
  },
  AvgDialog_18714_Content_38 = {
    Text = "Sekarang semua bukti yang memberatkan mengarah kepadamu, aku punya alasan yang cukup untuk mencurigaimu."
  },
  AvgDialog_18714_Content_39 = {
    Text = "Hmm, kecurigaanmu memang cukup masuk akal."
  },
  AvgDialog_18714_Content_4 = {
    Text = "Wah, sepertinya ada yang kurang senang melihatku?"
  },
  AvgDialog_18714_Content_41 = {
    Text = "Kau tidak punya sesuatu yang ingin dijelaskan?"
  },
  AvgDialog_18714_Content_42 = {
    Text = "Daffodil menatapmu dengan sedikit terkejut, seolah-olah kau baru saja mengajukan pertanyaan yang sangat konyol."
  },
  AvgDialog_18714_Content_43 = {
    Text = "Penjelasan? Maaf, aku tidak perlu menjelaskan apa pun kepada siapa pun."
  },
  AvgDialog_18714_Content_44 = {
    Text = "Dia melangkah anggun menghampirimu."
  },
  AvgDialog_18714_Content_45 = {
    Text = "Rok lebarnya menyapu dedaunan kering, menimbulkan suara gemerisik halus, sementara kabut ungu melilit di sekelilingnya bagai tentakel."
  },
  AvgDialog_18714_Content_46 = {
    Text = "Detik berikutnya, dia lenyap begitu saja di hadapanmu."
  },
  AvgDialog_18714_Content_47 = {
    Text = "Tirai awan rendah menutupi cahaya matahari sepenuhnya. Kau seolah berada di tengah mimpi kelabu, dan bisikan Daffodil bergema di telingamu—"
  },
  AvgDialog_18714_Content_48 = {
    Text = "Karena kau menganggapku sebagai \"Pemburu Tengkorak\"… lalu apa? Apa yang akan kau lakukan padaku?"
  },
  AvgDialog_18714_Content_49 = {
    Text = "Atau lebih tepatnya… apa yang bisa kau lakukan padaku?"
  },
  AvgDialog_18714_Content_5 = {
    Text = "Angin musim gugur yang dingin berhembus dari belakang. Kau menoleh, di hadapanmu kosong melompong, Tuan Freeman tua sudah entah ke mana."
  },
  AvgDialog_18714_Content_6 = {
    Text = "Mengingat kembali semua yang baru saja terjadi, rasanya seperti mimpi buruk."
  },
  AvgDialog_18714_Content_7 = {
    Text = "Tuan Freeman……?"
  },
  AvgDialog_18714_Content_8 = {
    Text = "Eh, kau membawa teman? Gadis kecil yang selalu memasang wajah masam itu?"
  },
  AvgDialog_18714_Content_9 = {
    Text = "Tadi kau berdiri sendirian di sini, tidak bergerak sama sekali, seperti sedang dirasuki seseorang."
  },
  AvgDialog_18715_Content_1 = {
    Text = "Aku menyerah, Penjaga Rahasia {Male=tuan,Female=nyonya}."
  },
  AvgDialog_18715_Content_10 = {
    Text = "Kau jatuh ke dalam lautan materi primordial berwarna kelabu."
  },
  AvgDialog_18715_Content_11 = {
    Text = "Cahaya matahari siang menyengat matamu, dan sejauh mata memandang terbentang lautan kelabu tanpa batas."
  },
  AvgDialog_18715_Content_12 = {
    Text = "Gelombang kelabu yang bergemuruh berkilauan dengan cahaya berpendar, permukaannya dihiasi titik-titik hitam tak terhitung jumlahnya."
  },
  AvgDialog_18715_Content_13 = {
    Text = "Penglihatanmu perlahan beradaptasi, dan kau menyadari bahwa itu bukanlah titik-titik hitam, melainkan hanyalah kepala-kepala."
  },
  AvgDialog_18715_Content_14 = {
    Text = "Tak terhitung banyaknya kepala yang terendam di lautan kelabu, naik turun mengikuti ombak. Mereka terus menjerit dan meratap, tenggelam dalam kesedihan dan ketakutan yang luar biasa."
  },
  AvgDialog_18715_Content_15 = {
    Text = "<Change>Kristal, kristal…"
  },
  AvgDialog_18715_Content_16 = {
    Text = "<Shake:Jangan sentuh buku kecil itu, jangan sentuh…>"
  },
  AvgDialog_18715_Content_17 = {
    Text = "<Shake:San Pedro, biarkan aku kembali, biarkan aku kembali…>"
  },
  AvgDialog_18715_Content_18 = {
    Text = "Tak terhitung suara menjerit di telingamu, kau terpaksa menutup telinga, kepalamu terasa seperti ditusuk jutaan jarum."
  },
  AvgDialog_18715_Content_19 = {
    Text = "Ugh… <Big:AAAAHH…!!>"
  },
  AvgDialog_18715_Content_2 = {
    Text = "Karena aku tak tega melihatmu terluka, melanjutkan pertarungan ini hanya membuang-buang waktu kita semua."
  },
  AvgDialog_18715_Content_20 = {
    Text = "Darah hangat mengalir dari telinga dan hidungmu, dan saat menetesi permukaan air, seketika memicu gelombang dahsyat."
  },
  AvgDialog_18715_Content_21 = {
    Text = "Gelombang yang membawa amarah dan ketakutan, bersama dengan tak terhitung kepala yang terombang-ambing di atasnya, menerjang ke arahmu."
  },
  AvgDialog_18715_Content_22 = {
    Text = "<Change>Tidak, tidak…"
  },
  AvgDialog_18715_Content_23 = {
    Text = "<Shake:Ada penyusup… Penyusup!!>"
  },
  AvgDialog_18715_Content_24 = {
    Text = "Kau tak bisa mundur lagi, hanya bisa memejamkan mata."
  },
  AvgDialog_18715_Content_25 = {Text = "Ukh……!"},
  AvgDialog_18715_Content_26 = {
    Text = "Uhuk uhuk…"
  },
  AvgDialog_18715_Content_27 = {
    Text = "Dafodel memegangi dahinya, menatapmu dengan alis berkerut."
  },
  AvgDialog_18715_Content_28 = {
    Text = "Secepat itu sudah keluar…? Kukira setidaknya bisa menjebakmu seharian penuh."
  },
  AvgDialog_18715_Content_29 = {
    Text = "Sepertinya kita berdua memang ditakdirkan untuk terikat bersama, bukan begitu?"
  },
  AvgDialog_18715_Content_3 = {
    Text = "Mengingat ada pertentangan yang tak bisa didamaikan di antara kita, kusarankan kau jangan menggangguku lagi."
  },
  AvgDialog_18715_Content_30 = {
    Text = "Kepala… sakit sekali…"
  },
  AvgDialog_18715_Content_31 = {
    Text = "Tadi itu… apa…"
  },
  AvgDialog_18715_Content_32 = {
    Text = [[
Itu ruang superdimensiku lho, kuberi nama <Yellow:Ilusi Seribu Wajah>.
Bagaimana, menarik bukan?]]
  },
  AvgDialog_18715_Content_34 = {
    Text = "%player%, hidungmu berdarah. Tunggu, bahkan telingamu juga…"
  },
  AvgDialog_18715_Content_35 = {
    Text = "<Shake:Aku tidak apa-apa…… jangan mendekat……>"
  },
  AvgDialog_18715_Content_36 = {
    Text = "Memaksakan diri sekarang bukanlah pilihan yang bijak, kamu bahkan sudah hampir tidak bisa berdiri tegak."
  },
  AvgDialog_18715_Content_37 = {
    Text = "Uhuk uhuk, jangan…… mendekat……"
  },
  AvgDialog_18715_Content_38 = {
    Text = "Pandanganmu menghitam, dan kamu ambruk ke tanah."
  },
  AvgDialog_18715_Content_39 = {
    Text = "Dalam kegelapan, kamu seperti mendengar suara yang familiar."
  },
  AvgDialog_18715_Content_4 = {
    Text = "Daffodil memasang wajah dingin, mengangkat tangannya dan dengan cepat menggambar serangkaian mantra ungu bercahaya di udara."
  },
  AvgDialog_18715_Content_40 = {
    Text = "Lembut, dingin, terbungkus dalam suara arus listrik yang sedikit menyengat, terasa jauh dan samar."
  },
  AvgDialog_18715_Content_41 = {
    Text = "%player%, bisakah kamu mendengarku sekarang……<Red:Arah investigasi salah>……"
  },
  AvgDialog_18715_Content_42 = {
    Text = "Pemburu Tengkorak kembali beraksi……\nTotal tiga korban tewas, semua kepala diambil……"
  },
  AvgDialog_18715_Content_43 = {
    Text = "Baru saja……"
  },
  AvgDialog_18715_Content_5 = {
    Text = "<Change>Ilusi Seribu Wajah, aktifkan."
  },
  AvgDialog_18715_Content_6 = {
    Text = "Dunia di hadapanmu tiba-tiba berubah menjadi bayangan pecah di dalam air, bergoyang lembut di depanmu."
  },
  AvgDialog_18715_Content_7 = {
    Text = "Secara refleks kau mengulurkan tangan, namun saat menyentuh bayangan pecah itu, kau tersedot ke dalam pusaran yang dalam."
  },
  AvgDialog_18715_Content_8 = {
    Text = "Aaaaahh…!!"
  },
  AvgDialog_18715_Content_9 = {Text = "Ini…"},
  AvgDialog_18716_Content_1 = {
    Text = "Uwaaaaah——!!"
  },
  AvgDialog_18716_Content_10 = {
    Text = "Kemudian, benang-benang itu tiba-tiba menyusut, pintu kamar tidur hancur berkeping-keping, dan tak terhitung banyaknya kepala bergelinding keluar."
  },
  AvgDialog_18716_Content_11 = {
    Text = "Saat kau tersadar, leher kosong Harriet sudah terpasang sebuah kepala yang tidak begitu asing."
  },
  AvgDialog_18716_Content_12 = {
    Text = "Kepala ini… wajah ini…"
  },
  AvgDialog_18716_Content_13 = {
    Text = "Beren Stoke, orang yang sebelumnya terbunuh… Apa yang terjadi?!"
  },
  AvgDialog_18716_Content_14 = {
    Text = "Kepala pucat pasi itu mengeluarkan suara berderak kaku, akhirnya membuka kedua mata yang kehilangan fokus."
  },
  AvgDialog_18716_Content_15 = {
    Text = "\"Harriet\" yang terlahir kembali menyeringai lebar, melesat ke arahmu dengan kecepatan yang tak terbayangkan."
  },
  AvgDialog_18716_Content_16 = {
    Text = "AAAAAAH——!!"
  },
  AvgDialog_18716_Content_18 = {
    Text = "Kilatan pedang yang dingin menusuk tanpa ampun membelah kegelapan."
  },
  AvgDialog_18716_Content_19 = {
    Text = "Detik berikutnya, kepala \"Harriet\" melayang ringan ke udara, bergelinding jatuh di samping rok lebar yang mengembang."
  },
  AvgDialog_18716_Content_2 = {
    Text = "Harriet terjatuh ke lantai, mengeluarkan jeritan pilu dari kedalaman tenggorokannya."
  },
  AvgDialog_18716_Content_20 = {
    Text = "Huff… Sepertinya aku datang tidak terlalu terlambat."
  },
  AvgDialog_18716_Content_21 = {
    Text = "Kelihatannya semangatmu masih bagus, %player%."
  },
  AvgDialog_18716_Content_3 = {
    Text = "Kau maju dan mencengkeram kerah bajunya."
  },
  AvgDialog_18716_Content_4 = {
    Text = "Bicara, siapa komplotanmu, di mana mereka semua? Apakah Pak Tua Freeman komplotanmu?"
  },
  AvgDialog_18716_Content_5 = {
    Text = "Freeman……? Heh…… heheheh……"
  },
  AvgDialog_18716_Content_6 = {
    Text = "Wajahnya berkerut hebat, di bawah kulitnya yang tipis bermunculan bisul-bisul bernanah tak terhitung jumlahnya, siap untuk menetas keluar."
  },
  AvgDialog_18716_Content_7 = {
    Text = "Bzzzzt——!!"
  },
  AvgDialog_18716_Content_8 = {
    Text = "Kepala Harriet meledak menjadi genangan cairan hangat."
  },
  AvgDialog_18716_Content_9 = {
    Text = "Lehernya terus bergerak-gerak, cairan korosif bercampur darah membeku menjadi untaian benang tipis, terus merambat ke langit-langit, dinding, dan lantai…"
  },
  AvgDialog_18717_Content_1 = {
    Text = "Perkumpulan Puisi Felinne"
  },
  AvgDialog_18717_Content_10 = {
    Text = "Itu benar-benar pengalaman yang menarik."
  },
  AvgDialog_18717_Content_11 = {
    Text = "Kenangan yang awalnya menyedihkan, setelah diinterpretasikan ulang melalui gambar bergerak, ternyata memiliki kekuatan ajaib yang membuat orang tertawa."
  },
  AvgDialog_18717_Content_12 = {
    Text = "Kudengar kalian kemudian mendirikan sebuah salon film, namanya <Yellow:\"Film Poetry Society\">?"
  },
  AvgDialog_18717_Content_13 = {
    Text = "Ya…… kadang-kadang aku membantu menulis skenario, meskipun aku selalu menjadi penulis naskah yang buruk."
  },
  AvgDialog_18717_Content_14 = {
    Text = "Nyonya Daphodel-lah yang membantuku keluar dari masa lalu, terlepas dari apakah itu memang niat aslinya."
  },
  AvgDialog_18717_Content_15 = {
    Text = "Aku selalu berterima kasih kepada Nyonya Daphodel."
  },
  AvgDialog_18717_Content_16 = {
    Text = "Begitu rupanya, itulah yang dia ceritakan kepadamu."
  },
  AvgDialog_18717_Content_17 = {
    Text = "Aku juga sama berterima kasihnya kepada Nona Aurla, itu adalah pertemuan yang indah."
  },
  AvgDialog_18717_Content_18 = {
    Text = "Jadi demi Nona Aurla, aku memilih untuk mempercayaimu sekali ini."
  },
  AvgDialog_18717_Content_19 = {
    Text = "<LightGray:Lagipula, orang-orang yang dikirim sekolah sudah dalam perjalanan.>"
  },
  AvgDialog_18717_Content_2 = {
    Text = "2:15, Jalan Kenting"
  },
  AvgDialog_18717_Content_20 = {
    Text = "<LightGray:Kalau aku pergi terlalu lama, mereka juga tidak akan tinggal diam……>"
  },
  AvgDialog_18717_Content_21 = {
    Text = "Kalau begitu, mari berangkat, Penjaga Rahasia{Male=tuan,Female=nyonya}."
  },
  AvgDialog_18717_Content_22 = {
    Text = "Daphodel mengangguk dengan gembira dan mengulurkan tangannya kepadamu."
  },
  AvgDialog_18717_Content_24 = {
    Text = "Kamu perlahan menggenggam tangan Daphodel. Berbeda dari yang dibayangkan, tangannya sangat lembut dan juga hangat."
  },
  AvgDialog_18717_Content_25 = {
    Text = "Genggam erat-erat ya, Penjaga Rahasia."
  },
  AvgDialog_18717_Content_26 = {
    Text = "Kakimu terasa ringan, lalu kamu ditarik masuk ke dalam sebuah dimensi yang dalam dan gelap."
  },
  AvgDialog_18717_Content_27 = {
    Text = "Selamat datang kembali di \"Ilusi Seribu Wajah\"-ku."
  },
  AvgDialog_18717_Content_28 = {
    Text = "Lagi-lagi lautan esensi primordial yang familiar itu, kepala-kepala masih naik turun mengikuti ombak."
  },
  AvgDialog_18717_Content_29 = {
    Text = "Berbeda dengan terakhir kali, kali ini tengkorak-tengkorak itu tampak jauh lebih tenang. Mereka mengarahkan rongga mata kosong mereka serentak ke arahmu, sambil tidak lupa berkumpul dan berbisik-bisik satu sama lain."
  },
  AvgDialog_18717_Content_3 = {
    Text = "Tak kusangka kamu begitu cepat setuju untuk ikut denganku. Tidak takut aku membawamu ke tempat-tempat aneh?"
  },
  AvgDialog_18717_Content_30 = {
    Text = "Daffodil mengibas tangannya dengan lembut, dan dua tengkorak melayang gemetar ke posisi sejajar dengan pandangannya."
  },
  AvgDialog_18717_Content_31 = {
    Text = "<Change>Tuan kami……"
  },
  AvgDialog_18717_Content_32 = {
    Text = "<Change>Lama tidak berjumpa……"
  },
  AvgDialog_18717_Content_33 = {
    Text = "<Change>Bantu aku mencari seseorang……"
  },
  AvgDialog_18717_Content_34 = {
    Text = "Daffodil berbicara pelan dengan tengkorak-tengkorak itu dalam bahasa yang tidak kamu mengerti dengan cepat. Entah apa yang mereka bicarakan, dia tertawa dengan gembira."
  },
  AvgDialog_18717_Content_35 = {
    Text = "Kamu belum pernah melihat senyuman seperti itu darinya, seolah-olah senyuman itu bukan milik masa kini."
  },
  AvgDialog_18717_Content_36 = {
    Text = "Melainkan menembus ratusan tahun waktu, dan jatuh di sudut cerita yang tidak kamu ketahui."
  },
  AvgDialog_18717_Content_38 = {
    Text = "Kenapa, ada sesuatu di wajahku?"
  },
  AvgDialog_18717_Content_39 = {
    Text = "Kamu terlihat sangat senang"
  },
  AvgDialog_18717_Content_4 = {
    Text = "Jadi apakah kamu akan… membawaku ke tempat aneh?"
  },
  AvgDialog_18717_Content_40 = {
    Text = "Mereka semua adalah koleksi kesayanganku."
  },
  AvgDialog_18717_Content_41 = {
    Text = "Sudah lama sekali sejak terakhir kali aku kembali ke sini. Aku sangat merindukan mereka."
  },
  AvgDialog_18717_Content_42 = {
    Text = "Kalian membicarakan apa"
  },
  AvgDialog_18717_Content_43 = {
    Text = "Masa lalu, masa kini, dan masa depan."
  },
  AvgDialog_18717_Content_44 = {
    Text = "Setiap tengkorak di sini adalah <Yellow:proyeksi yang berasal dari realitas>. Pandangan dan ingatan mereka bisa melampaui dimensi ruang dan waktu, membantu aku menemukan banyak hal yang tak terduga."
  },
  AvgDialog_18717_Content_45 = {
    Text = "Jadi karena itulah tokomu punya begitu banyak barang aneh……?"
  },
  AvgDialog_18717_Content_46 = {
    Text = "Daffodil berkedip, yang bisa dianggap sebagai pengakuan diam atas dugaanmu."
  },
  AvgDialog_18717_Content_47 = {
    Text = "Sebanyak ini tengkorak…… semuanya dari mana?"
  },
  AvgDialog_18717_Content_48 = {
    Text = [[
Perdagangan, hadiah, dan sedikit keberuntungan.
Tentu saja, ada juga sebagian yang kuambil sendiri dengan tanganku.]]
  },
  AvgDialog_18717_Content_49 = {
    Text = "Kudengar tengkorak yang pernah kamu kumpulkan mencapai @1 buah — dan itu baru angka yang tercatat secara resmi."
  },
  AvgDialog_18717_Content_5 = {
    Text = "Tentu saja."
  },
  AvgDialog_18717_Content_50 = {
    Text = "Daffodil dengan santai menyelipkan pipa rokoknya yang panjang ke mulut, menghisap dalam-dalam, lalu menghembuskan asap putih yang mengepul perlahan."
  },
  AvgDialog_18717_Content_51 = {
    Text = "Sayang sekali harus membuatmu kecewa, Penjaga Rahasia{Male=tuan,Female=nyonya}, kecaman moral tidak mempan terhadapku."
  },
  AvgDialog_18717_Content_52 = {
    Text = "Aturan yang dibuat manusia tidak berlaku bagi kami. Diriku yang kaulihat sekarang ini, memiliki mata, hidung yang sama seperti kalian…"
  },
  AvgDialog_18717_Content_53 = {
    Text = "Daffodil mengangkat kunci perak di dadamu, perlahan menelusuri ukiran rumit di permukaannya."
  },
  AvgDialog_18717_Content_54 = {
    Text = "Seketika rongga dada dipenuhi dengungan dan getaran yang kacau tak beraturan, saling berbenturan dengan hebat, bagaikan perang tanpa kata."
  },
  AvgDialog_18717_Content_55 = {
    Text = "Kau merasakannya? Kami bukan manusia. Kami adalah \"beast\", atau seperti yang dikatakan sebagian orang…"
  },
  AvgDialog_18717_Content_56 = {
    Text = "Kami adalah <Yellow:eksistensi yang lebih tinggi>."
  },
  AvgDialog_18717_Content_57 = {
    Text = "Kami menoleransi manusia yang bodoh, kami mengikuti aturan yang berubah-ubah, kami patuh pada tautan yang rapuh, semua itu karena rasa takut…"
  },
  AvgDialog_18717_Content_58 = {
    Text = "Dia perlahan menyentuh wajahmu."
  },
  AvgDialog_18717_Content_59 = {
    Text = "Dan juga janji."
  },
  AvgDialog_18717_Content_61 = {
    Text = "Karena itulah kau menjadi salah satu dari sedikit Awakened yang terdaftar namun belum pernah menjalin tautan dengan siapa pun."
  },
  AvgDialog_18717_Content_62 = {
    Text = "Tidak ada yang terlahir suka dikekang orang lain, sebagian besar makhluk secara naluriah mendambakan kebebasan."
  },
  AvgDialog_18717_Content_63 = {
    Text = "Secara pribadi, aku sebenarnya tidak membenci yang namanya \"tautan\"… Selama bisa saling menguntungkan, mengapa harus terpaku pada penampilan luar?"
  },
  AvgDialog_18717_Content_64 = {
    Text = [[
Masalahnya bukan ada padaku, lho.
Tidak ada yang menautkanku, karena mereka semua tidak memenuhi syarat, paham?]]
  },
  AvgDialog_18717_Content_65 = {Text = "Eh……"},
  AvgDialog_18717_Content_66 = {
    Text = "Kalau aku? Apakah aku juga termasuk yang \"tidak memenuhi syarat\" itu…?"
  },
  AvgDialog_18717_Content_67 = {
    Text = "Daffodil tertawa terbahak-bahak, asap rokok tersedak di tenggorokannya, membuatnya tak bisa menahan batuk beberapa kali."
  },
  AvgDialog_18717_Content_68 = {
    Text = "Jangan terburu-buru, anak kecil… Kau akan tahu jawabannya."
  },
  AvgDialog_18717_Content_69 = {
    Text = "<LightGray:Lagi-lagi jawaban yang ambigu seperti ini…>"
  },
  AvgDialog_18717_Content_7 = {
    Text = "Sebenarnya… Nona Aurla sore tadi bercerita padaku tentang pertemuan pertama kalian. Dia bilang—"
  },
  AvgDialog_18717_Content_70 = {
    Text = "Gawat, sepertinya aku sudah terlalu banyak bicara."
  },
  AvgDialog_18717_Content_71 = {
    Text = "Daffodil mengangkat tangan dan menyentuh dahi masing-masing tengkorak melayang itu satu per satu, dan mereka pun patuh melayang pergi."
  },
  AvgDialog_18717_Content_72 = {
    Text = "<Change>Terima kasih semuanya."
  },
  AvgDialog_18717_Content_73 = {
    Text = "Baiklah. Ayo berangkat, Penjaga Rahasia."
  },
  AvgDialog_18717_Content_74 = {
    Text = "Aku sudah mengetahui lokasi si Pemburu Tengkorak."
  },
  AvgDialog_18717_Content_8 = {
    Text = "Baru kemudian aku tahu, dia mengubah kenangan itu menjadi sesuatu yang disebut \"film\"."
  },
  AvgDialog_18717_Content_9 = {
    Text = "Aku duduk di kursi penonton, menonton film pertama dalam hidupku."
  },
  AvgDialog_18718_Content_1 = {
    Text = "Pertemuan Kembali yang Sepi"
  },
  AvgDialog_18718_Content_10 = {
    Text = [[
Ini adalah rumahku.
Selain tempat ini, aku tidak punya tempat lain untuk dituju.]]
  },
  AvgDialog_18718_Content_11 = {
    Text = "Orang desa seperti kami, ke mana pun pergi hasilnya sama saja."
  },
  AvgDialog_18718_Content_12 = {
    Text = "Nyonya Harriet…"
  },
  AvgDialog_18718_Content_13 = {
    Text = "Suasana di dalam ruangan menjadi agak berat."
  },
  AvgDialog_18718_Content_14 = {
    Text = "Hujan masih turun dengan lembut, kamu dan dia bersama-sama memandang ke tirai hujan tak berujung di luar jendela."
  },
  AvgDialog_18718_Content_15 = {
    Text = "Di luar segalanya kelabu, kabut air yang menyebar menyelimuti kalian dengan rapat, seolah-olah di antara langit dan bumi, kalian adalah satu-satunya kehidupan yang tersisa."
  },
  AvgDialog_18718_Content_16 = {
    Text = "<LightGray:Entah di mana Nyonya Daffodil sekarang…>"
  },
  AvgDialog_18718_Content_17 = {
    Text = "Tolong tunggu sebentar, {Male=tuan,Female=nyonya}. Aku pergi ke dapur untuk menyeduh teh panas."
  },
  AvgDialog_18718_Content_18 = {
    Text = "Meskipun tempat ini sederhana, secangkir teh masih bisa disajikan."
  },
  AvgDialog_18718_Content_19 = {
    Text = "Nyonya Harriet berjalan dengan langkah lambat menuju dapur."
  },
  AvgDialog_18718_Content_2 = {
    Text = [[
Kamu mengikuti wanita itu masuk ke dalam pondok kayu.
Perabotan di dalamnya sangat sederhana, kamu mencium bau kayu yang lembap.]]
  },
  AvgDialog_18718_Content_20 = {
    Text = "Baru setelah sosoknya ditelan oleh bayangan pekat di lorong, kamu tersadar kembali."
  },
  AvgDialog_18718_Content_21 = {
    Text = "Sepertinya hujan masih butuh waktu untuk berhenti, lihat-lihat sekeliling dulu saja."
  },
  AvgDialog_18718_Content_3 = {
    Text = "Wanita itu perlahan membungkuk dan memungut beberapa potong kayu bakar dari sudut ruangan, lalu melemparkan semuanya ke dalam tungku kecil yang gelap."
  },
  AvgDialog_18718_Content_4 = {
    Text = "Ulurkan tanganmu ke sini, hangatkan sebentar, nanti tidak akan kedinginan lagi."
  },
  AvgDialog_18718_Content_5 = {
    Text = "Terima kasih banyak……"
  },
  AvgDialog_18718_Content_6 = {
    Text = "Nama saya Harriet·@1, {Male=tuan,Female=nyonya}. Anda bisa memanggil saya Harriet."
  },
  AvgDialog_18718_Content_7 = {
    Text = "Baiklah, Nyonya Harriet. Sejujurnya saya penasaran, mengapa Anda memilih untuk tetap tinggal di sini?"
  },
  AvgDialog_18718_Content_8 = {
    Text = "Daerah sekitar sini sepertinya tidak begitu layak untuk ditinggali."
  },
  AvgDialog_18718_Content_9 = {
    Text = "Nyonya Harriet berjongkok di tanah sambil mengaduk-aduk kayu bakar, cahaya api yang berkedip-kedip terus menari di wajahnya yang kurus dan lelah."
  },
  AvgDialog_18719_Content_1 = {
    Text = "Perkumpulan Pemburu Tengkorak"
  },
  AvgDialog_18719_Content_10 = {
    Text = "Semalam kamu tidak berhasil mengejar Daphdale, jadi kamu hanya bisa mengikuti alamat yang diberikan Ramona untuk mendatangi kediaman Aurla."
  },
  AvgDialog_18719_Content_11 = {
    Text = "Se-selamat pagi, Nona Aurla."
  },
  AvgDialog_18719_Content_12 = {
    Text = "Selamat pagi, %player%{Male=tuan,Female=nyonya}."
  },
  AvgDialog_18719_Content_15 = {
    Text = "Keheningan yang canggung mengalir di udara. Kamu menyadari bahwa Awakened di hadapanmu ini tampaknya tidak terlalu pandai bersosialisasi."
  },
  AvgDialog_18719_Content_16 = {
    Text = [[
Nona Aurla, kali ini saya datang untuk kasus Pemburu Tengkorak.
Kamu sudah lama tinggal di sini, apakah ada petunjuk atau informasi?]]
  },
  AvgDialog_18719_Content_17 = {
    Text = "\"Pemburu Tengkorak\"…… tolong tunggu sebentar."
  },
  AvgDialog_18719_Content_18 = {
    Text = "Aurla berbalik dan mulai mencari-cari di rak buku yang tinggi."
  },
  AvgDialog_18719_Content_19 = {
    Text = "Ketemu! Uhuk uhuk……"
  },
  AvgDialog_18719_Content_2 = {Text = "Daphdale!"},
  AvgDialog_18719_Content_20 = {
    Text = "Aurla menyingkirkan debu yang beterbangan di sekitar, lalu meletakkan buku catatan yang sudah menguning ke tanganmu."
  },
  AvgDialog_18719_Content_21 = {
    Text = "Sebulan yang lalu, Nona Dorl pernah meminta bantuan saya."
  },
  AvgDialog_18719_Content_22 = {
    Text = "Aku tidak punya keahlian khusus lainnya, jadi aku mencatat semua kasus yang terjadi belakangan ini, semoga bisa membantu kalian……"
  },
  AvgDialog_18719_Content_23 = {
    Text = "Kau membuka catatan itu, di dalamnya tercatat waktu penemuan dan lokasi setiap kasus dengan tulisan tangan indah bergaya kaligrafi, bahkan dilengkapi sketsa jenazah dan tempat kejadian perkara."
  },
  AvgDialog_18719_Content_24 = {
    Text = "<Shake:Maaf sekali, kemampuan menggambar saya sangat buruk, Anda bisa mengabaikannya saja……>"
  },
  AvgDialog_18719_Content_25 = {
    Text = [[
Tidak, ini sangat bagus.
Terima kasih, Nona Aurla. Catatan ini sangat penting bagi kami.]]
  },
  AvgDialog_18719_Content_26 = {
    Text = "Bagaimanapun juga, senang bisa membantu. Orang-orang malang itu……"
  },
  AvgDialog_18719_Content_27 = {
    Text = "Aurla menghela napas pelan, lalu menoleh memandang langit mendung di luar jendela."
  },
  AvgDialog_18719_Content_28 = {
    Text = "Kota Rainy adalah tempat yang hujan sepanjang tahun. Setelah hujan berlalu, yang datang biasanya bukan panen melimpah, melainkan banjir dan wabah penyakit yang tiada akhir."
  },
  AvgDialog_18719_Content_29 = {
    Text = "Anak-anak muda pergi bekerja ke kota besar seperti Londinium, hanya menyisakan orang tua dan anak-anak yang tinggal di sini."
  },
  AvgDialog_18719_Content_3 = {
    Text = "Eh…… ini di mana?"
  },
  AvgDialog_18719_Content_30 = {
    Text = "Sekarang, bahkan para orang tua pun mulai pergi satu per satu……"
  },
  AvgDialog_18719_Content_31 = {
    Text = "Aku pernah menghadiri beberapa pemakaman di sini. Setiap kali ada keluarga yang meninggal, penduduk Rainy akan menyanyikan sebuah lagu kuno……"
  },
  AvgDialog_18719_Content_32 = {
    Text = "Aurla mulai bersenandung pelan, melodi penuh kesedihan itu pun seketika mengkristal menjadi huruf-huruf sehitam tinta."
  },
  AvgDialog_18719_Content_33 = {
    Text = "<RedItalic:Kami menjadikan darah sebagai pena, kami menjadikan tanah sebagai kertas.>\n<RedItalic:Kami menuliskan duka dan ketakutan dengan tubuh yang basah kuyup oleh hujan……>"
  },
  AvgDialog_18719_Content_34 = {
    Text = "Huruf-huruf itu mengalir perlahan di sekeliling Aurla, lalu terbentuklah selembar kertas surat yang menguning, membungkus Aurla di dalamnya."
  },
  AvgDialog_18719_Content_35 = {
    Text = "Dia menghela napas pelan, matanya berkilau oleh air mata yang menggenang."
  },
  AvgDialog_18719_Content_36 = {
    Text = "Semua yang terjadi sekarang, bukankah ini duka yang ditulis oleh penduduk Rainy dengan tubuh mereka yang basah kuyup oleh hujan……"
  },
  AvgDialog_18719_Content_37 = {
    Text = "Udara dipenuhi oleh kemurungan yang tak terucap dan pekat, hampir membuatmu tak bisa bernapas."
  },
  AvgDialog_18719_Content_38 = {
    Text = "<Shake:Uhuk uhuk, Au… Nona Aurla……>"
  },
  AvgDialog_18719_Content_4 = {
    Text = "Kicauan burung yang riang menarikmu kembali dari mimpi ke kenyataan."
  },
  AvgDialog_18719_Content_40 = {
    Text = "Ah! Maaf, aku tidak sengaja lagi……"
  },
  AvgDialog_18719_Content_41 = {
    Text = "Aurla tersadar seperti baru terbangun dari mimpi, lalu menarik napas dalam-dalam dua kali."
  },
  AvgDialog_18719_Content_42 = {
    Text = "Emosi yang menyesakkan itu akhirnya menghilang, beban berat yang menekan dadamu seketika terasa jauh lebih ringan."
  },
  AvgDialog_18719_Content_45 = {
    Text = "Ah, be-benar juga."
  },
  AvgDialog_18719_Content_46 = {
    Text = "Aku menyeduh teh mawar dari kelopak bunga yang baru dipetik. Mau mencicipinya bersama?"
  },
  AvgDialog_18719_Content_47 = {
    Text = "Setengah jam kemudian"
  },
  AvgDialog_18719_Content_48 = {
    Text = "Dengan satu tangan memegang cangkir porselen berisi teh mawar, tangan lainnya membolak-balik catatan Aurla, kamu berusaha menemukan celah yang mungkin bisa menjadi titik terang."
  },
  AvgDialog_18719_Content_49 = {
    Text = "Bagaimana dengan orang-orang dari kantor polisi?"
  },
  AvgDialog_18719_Content_5 = {
    Text = "Kamu memandang bingung ke ruangan yang bersih dan sederhana di hadapanmu, lalu menarik selimut dan menciumnya."
  },
  AvgDialog_18719_Content_50 = {
    Text = "Di Norwich Street, tempat yang kamu lewati semalam."
  },
  AvgDialog_18719_Content_52 = {
    Text = [[
Hujan. Darah. Daffodil.
Mengenang perjumpaan semalam, kamu tak bisa membedakan apakah itu mimpi atau kenyataan.]]
  },
  AvgDialog_18719_Content_53 = {
    Text = "Kamu terdengar lemah… Tidak tidur nyenyak semalam?"
  },
  AvgDialog_18719_Content_54 = {
    Text = "Tidak, hanya saja…"
  },
  AvgDialog_18719_Content_55 = {
    Text = "Kamu menggelengkan kepala, berusaha mengosongkan pikiran dari segala hal yang berkecamuk di benakmu."
  },
  AvgDialog_18719_Content_57 = {
    Text = "Penyelidikan di Kota Rye baru saja selesai beberapa hari lalu, luka di tubuhmu pun belum sembuh sepenuhnya."
  },
  AvgDialog_18719_Content_58 = {
    Text = "Haah, mau bagaimana lagi, penyelidik lain juga sedang tidak bisa ditarik."
  },
  AvgDialog_18719_Content_59 = {
    Text = "Sudah terlanjur begini, lebih baik selesaikan kasus ini secepatnya. Aku masih ingin berlibur."
  },
  AvgDialog_18719_Content_6 = {
    Text = "Bagus. Kering, lembut, tanpa bau hujan dan darah."
  },
  AvgDialog_18719_Content_60 = {Text = "Eh, ini…"},
  AvgDialog_18719_Content_61 = {
    Text = "Suara halaman yang dibalik terhenti mendadak."
  },
  AvgDialog_18719_Content_62 = {
    Text = "Kamu menatap lekat halaman yang terhenti itu, mulai menyusun rencana penyelidikan selanjutnya."
  },
  AvgDialog_18719_Content_63 = {
    Text = "Ramona… sebelum bertemu dengan detektif, aku ingin pergi ke suatu tempat dulu."
  },
  AvgDialog_18719_Content_7 = {
    Text = "Selamat pagi, %player%{Male=tuan,Female=nyonya}. Selamat datang di kediaman sederhana saya……"
  },
  AvgDialog_18719_Content_8 = {
    Text = "Nona Aurla?!"
  },
  AvgDialog_18719_Content_9 = {
    Text = "Ingatan mulai pulih sedikit demi sedikit."
  },
  AvgDialog_18720_Content_1 = {
    Text = "11:00, Lahan Makam Highgate"
  },
  AvgDialog_18720_Content_10 = {
    Text = "Jangan berharap terlalu tinggi pada profesionalisme detektif di daerah terpencil."
  },
  AvgDialog_18720_Content_11 = {
    Text = "……Ada benarnya juga."
  },
  AvgDialog_18720_Content_12 = {
    Text = "Kau mengeluarkan kaca pembesar yang selalu kau bawa dan melanjutkan pengamatan terhadap kerangka ini."
  },
  AvgDialog_18720_Content_13 = {
    Text = "Ada <Red:luka sayatan bergerigi> di tulang leher…"
  },
  AvgDialog_18720_Content_14 = {
    Text = "Tapi sangat berantakan, dengan banyak bekas sayatan yang tumpang tindih, sama sekali berbeda dari yang pernah kita lihat di foto sebelumnya."
  },
  AvgDialog_18720_Content_15 = {
    Text = "Masih cukup canggung, kejahatan pertama kali?"
  },
  AvgDialog_18720_Content_16 = {
    Text = [[
Mari mulai penyelidikan dengan kuburan massal sebagai pusatnya.
Pemula yang belum terampil biasanya tidak pergi terlalu jauh dari rumah saat melakukan kejahatan pertama mereka.]]
  },
  AvgDialog_18720_Content_17 = {
    Text = "Mengerti. Kali ini aku sangat yakin, pelakunya pasti akan segera tertangkap!"
  },
  AvgDialog_18720_Content_18 = {
    Text = "Pelaku (murderer)? Berani-beraninya kau berasumsi, hik, bahwa pelakunya hanya satu?"
  },
  AvgDialog_18720_Content_19 = {
    Text = "Dari balik lebatnya pepohonan, muncul seorang pria tua dengan bau alkohol menyengat dan pipi yang merah merona."
  },
  AvgDialog_18720_Content_2 = {
    Text = "Kamu berjalan sendirian melewati lahan makam yang sunyi dan hampa."
  },
  AvgDialog_18720_Content_20 = {
    Text = "Maaf, tidak bermaksud menguping omonganmu sendiri."
  },
  AvgDialog_18720_Content_21 = {
    Text = "Aku penjaga makam di sini, kau bisa memanggilku Pak… hik, <Blue:Pak Freeman>."
  },
  AvgDialog_18720_Content_22 = {
    Text = [[
Selamat siang, Tuan Freeman.
Tadi maksud Anda, pelakunya lebih dari satu orang?]]
  },
  AvgDialog_18720_Content_23 = {
    Text = "Pak Freeman mengangkat botol minumannya dan meneguk isinya ke tenggorokan, jakun besarnya naik turun tanpa henti."
  },
  AvgDialog_18720_Content_24 = {
    Text = "Hik! Hutan jelek ini seharian tidak ada orang yang terlihat. Jarang-jarang kau datang, jadi dengarkanlah aku bercerita dengan baik…"
  },
  AvgDialog_18720_Content_25 = {
    Text = "Itu kira-kira sekitar awal tahun ini……? Aku juga tidak ingat persisnya."
  },
  AvgDialog_18720_Content_26 = {
    Text = "Seperti biasa, aku minum-minum, lalu asal cari tempat teduh dan langsung tertidur."
  },
  AvgDialog_18720_Content_27 = {
    Text = "Lalu aku mendengar suara-suara aneh, seperti……"
  },
  AvgDialog_18720_Content_28 = {
    Text = "<RedItalic:Zzzzt……krak krak……>"
  },
  AvgDialog_18720_Content_29 = {
    Text = "Suara aneh, lalu apa?"
  },
  AvgDialog_18720_Content_3 = {
    Text = "Gagak melintas di langit yang suram dan mendung, angin musim gugur yang dingin terus meraung tanpa henti."
  },
  AvgDialog_18720_Content_30 = {
    Text = "Jangan buru-buru, detektif kecil.\nAku membuka mata……hik, coba tebak apa yang kulihat?"
  },
  AvgDialog_18720_Content_31 = {
    Text = "Tidak mungkin sebetulan itu, jangan-jangan itu si Pemburu Tengkorak?"
  },
  AvgDialog_18720_Content_32 = {
    Text = "Benar, itu Pemburu Tengkorak! Atau, bisa juga dibilang seorang perempuan……"
  },
  AvgDialog_18720_Content_33 = {
    Text = "Seorang perempuan sedang memotong kepala Pinoko!"
  },
  AvgDialog_18720_Content_34 = {
    Text = "Lalu dia melihatku, hik, seperti melihat hantu saja, larinya cepat sekali!"
  },
  AvgDialog_18720_Content_35 = {
    Text = "Pinoko-ku yang malang, lehernya tinggal separuh tergantung di sana!"
  },
  AvgDialog_18720_Content_36 = {
    Text = "Haha, <Big:hahahaha……>"
  },
  AvgDialog_18720_Content_37 = {
    Text = "Pak Tua Freeman mengeluarkan serangkaian tawa yang sangat keras, sampai air matanya keluar karena tertawa."
  },
  AvgDialog_18720_Content_38 = {
    Text = "<SmallShake:Sabar, sabar……>"
  },
  AvgDialog_18720_Content_39 = {
    Text = "Hik, hik! Sekitar sebulan kemudian, aku mendengar suara itu lagi……"
  },
  AvgDialog_18720_Content_4 = {Text = "Ketemu."},
  AvgDialog_18720_Content_40 = {
    Text = "<RedItalic:Zzzzt zzzzt……krak krak krak……>"
  },
  AvgDialog_18720_Content_41 = {
    Text = "Kali ini yang datang bukan perempuan itu, tapi seorang laki-laki yang sangat kurus."
  },
  AvgDialog_18720_Content_42 = {
    Text = "Dia itu sudah ahli! Sekali tebas……"
  },
  AvgDialog_18720_Content_43 = {
    Text = "<RedBig:Wussh!> Kepala Pinoko langsung hilang!"
  },
  AvgDialog_18720_Content_44 = {
    Text = "Kedengarannya ada dua Pemburu Tengkorak. Lalu apa yang terjadi?"
  },
  AvgDialog_18720_Content_45 = {
    Text = "Setelah itu? Tidak ada setelah itu. Itulah seluruh kisah Freeman tua dan Pemburu Tengkorak, hik."
  },
  AvgDialog_18720_Content_46 = {
    Text = "Freeman tua bersendawa puas, lalu menyipitkan mata kuningnya yang keruh, mengamatimu dari atas ke bawah."
  },
  AvgDialog_18720_Content_47 = {
    Text = "Sepertinya kau tidak tahu apa-apa, detektif kecil yang malang. Pernah dengar <Red:Legenda Pemburu Tengkorak>?"
  },
  AvgDialog_18720_Content_48 = {
    Text = "Legenda Pemburu Tengkorak? Ceritakan lebih lanjut."
  },
  AvgDialog_18720_Content_49 = {
    Text = "Freeman tua bersandar santai di batu nisan, menghabiskan sisa minuman di botol dalam beberapa tegukan, lalu melemparkannya begitu saja ke tanah."
  },
  AvgDialog_18720_Content_5 = {
    Text = "Kau berhenti di depan sebuah makam yang berdiri sendirian. Tutup peti mati yang sudah lapuk di bawahnya telah lama terbuka."
  },
  AvgDialog_18720_Content_50 = {
    Text = "Cairan mengalir keluar dari botol yang pecah, meninggalkan jejak berkelok-kelok di tanah. Seperti air mata, juga seperti darah."
  },
  AvgDialog_18720_Content_51 = {
    Text = "Ada yang bilang, Pemburu Tengkorak adalah monster yang lahir dari <Yellow:wabah> itu."
  },
  AvgDialog_18720_Content_52 = {
    Text = "Ada juga yang bilang, Pemburu Tengkorak bukan satu orang, juga bukan dua orang."
  },
  AvgDialog_18720_Content_53 = {
    Text = "<Red:Pemburu Tengkorak adalah sebuah organisasi.>"
  },
  AvgDialog_18720_Content_54 = {
    Text = "Organisasi?"
  },
  AvgDialog_18720_Content_55 = {
    Text = "Ya, sebuah organisasi."
  },
  AvgDialog_18720_Content_56 = {
    Text = "Mereka hanya muncul di malam hujan, langkah kaki mereka tersembunyi di balik suara hujan, hanya perlu diam-diam berputar ke belakangmu…"
  },
  AvgDialog_18720_Content_57 = {
    Text = "<RedBig:KRAK!>"
  },
  AvgDialog_18720_Content_58 = {Text = "!!"},
  AvgDialog_18720_Content_59 = {
    Text = "Hahahaha! Kenapa, sudah ketakutan setengah mati, detektif kecilku?"
  },
  AvgDialog_18720_Content_6 = {
    Text = "Sebuah kerangka tanpa kepala terbaring di dalam peti, permukaannya telah lama menjadi surga bagi lumut dan serangga."
  },
  AvgDialog_18720_Content_60 = {
    Text = "Dia bergoyang-goyang, lalu melangkah beberapa langkah lebih dekat ke arahmu. Bola mata kuning keruhnya berputar-putar, seolah hendak membakar tembus dirimu."
  },
  AvgDialog_18720_Content_61 = {
    Text = "Orang ini tidak beres. Segera pergi dari sini."
  },
  AvgDialog_18720_Content_62 = {
    Text = "Maaf, Tuan Freeman. Hari sudah mulai gelap, kurasa aku harus pergi…"
  },
  AvgDialog_18720_Content_63 = {
    Text = "Kau menarik napas pelan, lalu berbalik pergi tanpa menoleh ke belakang."
  },
  AvgDialog_18720_Content_64 = {
    Text = "Tawa mengejek terdengar dari belakang, tapi kau sudah tak peduli lagi. Sekarang kau hanya ingin pergi."
  },
  AvgDialog_18720_Content_65 = {
    Text = "Langit perlahan menggelap, awan rendah yang menggantung menutupi cahaya matahari yang pucat, angin meniup dedaunan bergelombang bak pasang surut yang tak menentu."
  },
  AvgDialog_18720_Content_66 = {
    Text = "Di ujung pemakaman, kau melihat sosok yang familiar sekaligus asing."
  },
  AvgDialog_18720_Content_67 = {
    Text = "Itu Daffodil. Sebagian besar wajahnya tersembunyi di balik pinggiran topi yang rendah, helai rambut abu-abunya menari lembut tertiup angin."
  },
  AvgDialog_18720_Content_68 = {
    Text = "Melihat penampilanmu yang berantakan, Daffodil tertawa gembira."
  },
  AvgDialog_18720_Content_69 = {
    Text = "Lama tidak bertemu, Penjaga Rahasia{Male=tuan,Female=nyonya}."
  },
  AvgDialog_18720_Content_7 = {
    Text = "Waktu penemuan yang tercatat di buku catatan adalah setengah tahun lalu, waktu kematiannya pasti lebih awal lagi…"
  },
  AvgDialog_18720_Content_8 = {
    Text = "Dengan kata lain, ini kemungkinan besar adalah korban paling awal yang diketahui dari \"Pemburu Tengkorak\". Tapi data kepolisian tidak pernah menyebutkannya…"
  },
  AvgDialog_18720_Content_9 = {
    Text = "Di sini bahkan tidak ada rumah sakit atau rumah duka yang layak, dan tidak ada yang terlalu peduli soal orang mati."
  },
  AvgDialog_18721_Content_1 = {
    Text = "Mungkin bisa mencoba menggunakan penelusuran mental untuk menemukan Pemburu Tengkorak?"
  },
  AvgDialog_18721_Content_2 = {
    Text = "Metode ini tidak terlalu efektif terhadap makhluk dari Ranah Superdimensi."
  },
  AvgDialog_18721_Content_3 = {
    Text = "Penelusuran mental juga bukan solusi untuk segalanya."
  },
  AvgDialog_18722_Content_1 = {
    Text = "Sampai Jumpa Lagi"
  },
  AvgDialog_18722_Content_10 = {
    Text = "<LightGray:Tengkorak berharga? Milik siapa ya……>"
  },
  AvgDialog_18722_Content_12 = {
    Text = "Kau terlihat gelisah, %player%. Sepertinya kau benar-benar ingin tahu jawabannya?"
  },
  AvgDialog_18722_Content_13 = {Text = "Biasa saja"},
  AvgDialog_18722_Content_14 = {
    Text = "Ehm, aku bukan tipe orang yang suka mencampuri privasi orang lain."
  },
  AvgDialog_18722_Content_15 = {
    Text = "Benarkah? Tapi ekspresimu sudah mengkhianatimu, lho."
  },
  AvgDialog_18722_Content_16 = {
    Text = "Memang ingin tahu"
  },
  AvgDialog_18722_Content_17 = {
    Text = "Aku hanya ingin mengenal Anda lebih dalam, Nyonya Dafaudel."
  },
  AvgDialog_18722_Content_18 = {
    Text = "Oh? Sepertinya seseorang semakin serakah saja."
  },
  AvgDialog_18722_Content_19 = {
    Text = "Kuberi petunjuk: <Yellow:Itu sesuatu yang pernah kau lihat sebelumnya.>"
  },
  AvgDialog_18722_Content_2 = {
    Text = "Pasukan bantuan dan tim audit sudah dalam perjalanan ke sini, kau tetap di sini dulu untuk mengamankan lokasi."
  },
  AvgDialog_18722_Content_20 = {
    Text = "Sesuatu yang pernah kulihat……?"
  },
  AvgDialog_18722_Content_21 = {
    Text = "Kau berpikir keras, kisah-kisah yang terjadi dan orang-orang yang kau temui selama dua hari ini berkilas balik dengan cepat di depan matamu."
  },
  AvgDialog_18722_Content_23 = {Text = "!!"},
  AvgDialog_18722_Content_24 = {
    Text = "Jangan-jangan itu yang di jalanan Norwich, yang persis sama denganmu itu……"
  },
  AvgDialog_18722_Content_25 = {
    Text = "Pintar sekali."
  },
  AvgDialog_18722_Content_26 = {
    Text = "Tapi kenapa……Aku tidak mengerti."
  },
  AvgDialog_18722_Content_27 = {
    Text = "Daffodil memandang jauh ke cahaya fajar yang samar di garis cakrawala, angin dingin yang sejuk meniup rambut panjangnya."
  },
  AvgDialog_18722_Content_28 = {
    Text = "Itu adalah sebuah \"spesimen\", milik tuanku yang dulu."
  },
  AvgDialog_18722_Content_29 = {
    Text = "Kuberitahu sebuah rahasia: wajahku yang sekarang dibuat meniru spesimen itu."
  },
  AvgDialog_18722_Content_3 = {
    Text = "Tenang saja, kali ini aku pasti akan menunggu dengan manis, tidak akan berkeliaran ke mana-mana lagi."
  },
  AvgDialog_18722_Content_30 = {Text = "?!"},
  AvgDialog_18722_Content_31 = {
    Text = "<LightGray:Ternyata ini bukan wujud asli Nyonya Daffodil…>"
  },
  AvgDialog_18722_Content_32 = {
    Text = [[
Kali ini kau sangat membantuku.
Menggunakan Penjaga Rahasia yang masih begitu muda sebagai umpan, sampai sekarang aku tidak bisa memaafkan diriku sendiri.]]
  },
  AvgDialog_18722_Content_33 = {
    Text = "……Tidak apa-apa, selama penyelidikan bisa diselesaikan, aku tidak keberatan dimanfaatkan sekali."
  },
  AvgDialog_18722_Content_34 = {
    Text = "Benarkah, tapi aku merasa sangat tidak enak hati. Jadi……"
  },
  AvgDialog_18722_Content_35 = {
    Text = "Sebagai permintaan maaf, aku bisa mengabulkan satu permintaanmu."
  },
  AvgDialog_18722_Content_36 = {
    Text = "Gratis lho~"
  },
  AvgDialog_18722_Content_37 = {Text = "!!"},
  AvgDialog_18722_Content_38 = {
    Text = "Yang berdiri di hadapanmu adalah seorang pedagang yang terkenal kejam dan cerdik. Informasi, pengetahuan terlarang, dan koleksi berharga yang ia kuasai adalah hal yang diimpikan banyak orang."
  },
  AvgDialog_18722_Content_39 = {
    Text = "Dan sekarang, ia bisa mengabulkan satu permintaanmu secara cuma-cuma."
  },
  AvgDialog_18722_Content_4 = {
    Text = [[
Tak kusangka penyelidikan ini bisa diselesaikan secepat ini.
Kerja bagus, %player%.]]
  },
  AvgDialog_18722_Content_40 = {
    Text = "<LightGray:Tidak boleh… Kalau Nona Dor tahu aku sembarangan membuat kesepakatan dengan orang lain di luar, dia pasti akan marah.>"
  },
  AvgDialog_18722_Content_41 = {
    Text = "Berbagai kemungkinan melintas di benakmu — artefak emas yang telah hilang, kue-kue kecil paling lezat, sejumlah besar Leofang…"
  },
  AvgDialog_18722_Content_42 = {
    Text = "Pikiran-pikiran yang kacau terus bersilangan dan bertabrakan, lalu semuanya surut bagai gelombang — kau memutuskan untuk mengikuti naluri hatimu."
  },
  AvgDialog_18722_Content_43 = {
    Text = "Sudah memikirkan permintaanmu? Jangan terlalu serakah ya."
  },
  AvgDialog_18722_Content_44 = {
    Text = "Sudah, permintaanku sangat sederhana."
  },
  AvgDialog_18722_Content_45 = {
    Text = "Biarkan aku melihat wujud aslimu."
  },
  AvgDialog_18722_Content_47 = {
    Text = "Sesederhana itu? Pikirkan baik-baik, aku bisa memberimu banyak hal, yang mana pun lebih berharga dari itu."
  },
  AvgDialog_18722_Content_48 = {
    Text = "Seberapa besar nilainya, itu tergantung pada penilaianku. Selain itu, aku tidak punya permintaan lain."
  },
  AvgDialog_18722_Content_49 = {
    Text = "Tidak heran kau seorang Penjaga Rahasia{Male=tuan,Female=nyonya}, selalu bisa membuatku terkejut. Kalau begitu……"
  },
  AvgDialog_18722_Content_5 = {
    Text = "Ehm, kali ini semua berkat Nyonya Dafaudel."
  },
  AvgDialog_18722_Content_50 = {
    Text = "Daffodil berjalan perlahan menghampirimu. Angin meniup rambut panjangnya, bagaikan ombak kelabu yang berkibar naik turun."
  },
  AvgDialog_18722_Content_51 = {
    Text = "Kalian begitu dekat, kau hampir bisa melihat bayanganmu sendiri di matanya."
  },
  AvgDialog_18722_Content_52 = {
    Text = "Ingat, rahasiakan ini ya, %player%."
  },
  AvgDialog_18722_Content_53 = {
    Text = "Begitu kata-katanya usai, wajahnya mulai melebur dan memudar, bagaikan cat minyak yang terendam air..."
  },
  AvgDialog_18722_Content_54 = {
    Text = "Akhirnya, kau bisa melihat wajahnya dengan jelas."
  },
  AvgDialog_18722_Content_55 = {
    Text = "Itu adalah wajah yang @2, membuatmu teringat akan banyak hal."
  },
  AvgDialog_18722_Content_56 = {
    Text = "Seperti kabut lembap setelah hujan, bunga narsis yang diam-diam mekar di sudut, atau hewan kecil yang meringkuk dalam kegelapan..."
  },
  AvgDialog_18722_Content_57 = {
    Text = "Belum sempat kau memperhatikannya lebih saksama, wajah itu sudah melebur kembali seperti tetesan air yang jatuh ke permukaan air, lenyap tak berbekas."
  },
  AvgDialog_18722_Content_58 = {
    Text = "Ternyata... inilah wujud aslimu yang sebenarnya."
  },
  AvgDialog_18722_Content_59 = {
    Text = "Bagaimana, apakah menurutmu jelek?"
  },
  AvgDialog_18722_Content_6 = {
    Text = "Hanya bantuan kecil, lagipula aku juga berhasil menemukan kembali sesuatu yang hilang."
  },
  AvgDialog_18722_Content_60 = {
    Text = "Kau menggelengkan kepala."
  },
  AvgDialog_18722_Content_61 = {
    Text = "Mengejutkan... tapi wajah yang sangat cocok denganmu."
  },
  AvgDialog_18722_Content_62 = {
    Text = "Sinar mentari pagi menyapu kelembapan air hujan, seluruh tubuhnya diselimuti cahaya lembut yang hangat."
  },
  AvgDialog_18722_Content_63 = {
    Text = "Sejujurnya... tadi aku bahkan merasa takut, lalu aku terkejut dengan rasa takutku sendiri."
  },
  AvgDialog_18722_Content_64 = {
    Text = "Sepuluh tahun, lima puluh tahun? Aku sudah tidak ingat kapan terakhir kali aku merasa takut."
  },
  AvgDialog_18722_Content_65 = {
    Text = "Takut...? Jangan-jangan kau takut aku menganggapmu jelek?"
  },
  AvgDialog_18722_Content_66 = {
    Text = "Daffodil tidak menjawab, hanya mengusap lembut rambutmu."
  },
  AvgDialog_18722_Content_67 = {
    Text = "%player%, sekarang kau adalah satu-satunya orang di dunia ini yang pernah melihat \"aku\" yang sebenarnya."
  },
  AvgDialog_18722_Content_68 = {
    Text = "Hehe, sekarang ada sedikit rahasia tentangmu yang kupegang."
  },
  AvgDialog_18722_Content_69 = {
    Text = "Selagi belum hilang ingatan, aku harus segera menggambar wajahmu di atas kertas."
  },
  AvgDialog_18722_Content_7 = {
    Text = "Dari sudut pandang pedagang, ini adalah \"transaksi\" yang sempurna."
  },
  AvgDialog_18722_Content_70 = {
    Text = "Daffodil tertawa, matanya melengkung membentuk busur yang indah."
  },
  AvgDialog_18722_Content_71 = {
    Text = "Dasar anak bodoh."
  },
  AvgDialog_18722_Content_72 = {
    Text = "Baiklah, teman-temanmu dari dewan pemeriksa dan kepolisian pasti sudah dalam perjalanan ke sini, kan?"
  },
  AvgDialog_18722_Content_73 = {
    Text = "<Shake:Ternyata kau sudah tahu semuanya……>"
  },
  AvgDialog_18722_Content_74 = {
    Text = [[
Aku tidak berminat menghadapi interogasi membosankan itu.
Lain kali, carilah tempat yang tidak ada yang mengganggu, aku akan mentraktirmu secangkir kopi.]]
  },
  AvgDialog_18722_Content_75 = {
    Text = "Sampai jumpa lagi, Penjaga Rahasiaku{Male=tuan,Female=nyonya}."
  },
  AvgDialog_18722_Content_76 = {
    Text = "Hah? Oh…… da, dah, Nyonya Daffodil."
  },
  AvgDialog_18722_Content_77 = {
    Text = "Daffodil melambaikan tangan padamu, lalu berbalik pergi."
  },
  AvgDialog_18722_Content_78 = {
    Text = "Kau memandangi punggungnya yang santai dari kejauhan, dan hatimu pun ikut terasa ringan."
  },
  AvgDialog_18722_Content_79 = {
    Text = "Awan mendung yang terus-menerus akhirnya sirna sepenuhnya, langit pun cerah kembali. Sinar matahari menembus awan yang malas, menghangatkan seluruh tubuhmu."
  },
  AvgDialog_18722_Content_8 = {
    Text = "Sesuatu yang hilang……"
  },
  AvgDialog_18722_Content_80 = {
    Text = "Entah mengapa, kau punya firasat—"
  },
  AvgDialog_18722_Content_81 = {
    Text = "Kalian akan terus bertemu lagi, di dimensi waktu dan ruang yang berbeda."
  },
  AvgDialog_18722_Content_9 = {
    Text = "Pemburu Tengkorak mengambil sebuah <Yellow:tengkorak berharga> dariku, jadi aku datang ke sini untuk melakukan sedikit penyelidikan. Sesederhana itu."
  },
  AvgDialog_18723_Content_1 = {
    Text = "Uhuk uhuk, Awakened Being dari Dimensi Super benar-benar sulit dikejar…"
  },
  AvgDialog_18723_Content_10 = {
    Text = "Jawaban…?"
  },
  AvgDialog_18723_Content_11 = {
    Text = "Dia melarikan diri saat kamu pergi sebentar, ketika aku dan Nona Orla sedang mengobrol di samping."
  },
  AvgDialog_18723_Content_12 = {
    Text = "Tapi tak perlu khawatir, kalau ikut denganku, kamu akan segera bisa menemuinya."
  },
  AvgDialog_18723_Content_13 = {
    Text = "Di <Blue:tanah tandus di utara Kota Reney>, kan?"
  },
  AvgDialog_18723_Content_14 = {
    Text = "Oh? Rupanya detektif kecil kita cukup tajam ya. Bagaimana kamu bisa mengetahuinya?"
  },
  AvgDialog_18723_Content_15 = {
    Text = "Makhluk itu menunjukkan fenomena erosi fusi di tubuhnya, kemungkinan besar terkait dengan wabah yang terjadi di utara tiga tahun lalu."
  },
  AvgDialog_18723_Content_16 = {
    Text = "Sekarang dia terluka separah itu, dan menghadapi tekanan ganda dari kita dan kepolisian, tempat yang bisa dia tuju sudah tidak banyak."
  },
  AvgDialog_18723_Content_17 = {
    Text = "Entah pada akhirnya dia bersembunyi di tanah tandus itu atau tidak, tempat itu tetap merupakan titik terobosan yang layak diselidiki."
  },
  AvgDialog_18723_Content_18 = {
    Text = "Bagus, cerdas sekali. Tapi kamu tahu seberapa luas tanah tandus itu?"
  },
  AvgDialog_18723_Content_19 = {
    Text = [[
Hampir 50 mil persegi.
Kamu juga tidak mau liburan berhargamu terbuang sia-sia untuk ekspedisi geologi dan sensus penduduk, kan?]]
  },
  AvgDialog_18723_Content_2 = {
    Text = "Kamu berlari terhuyung-huyung sampai di sebuah persimpangan."
  },
  AvgDialog_18723_Content_20 = {
    Text = [[
Dan aku, kebetulan bisa menemukan lokasi persembunyiannya yang tepat.
Mau ikut denganku?]]
  },
  AvgDialog_18723_Content_21 = {
    Text = "Jangan setuju. Dia sangat berbahaya, jangan sampai terperdaya olehnya."
  },
  AvgDialog_18723_Content_22 = {
    Text = "Aku hitung sampai tiga ya. Tiga, dua…"
  },
  AvgDialog_18723_Content_24 = {
    Text = "Aku ikut denganmu."
  },
  AvgDialog_18723_Content_26 = {
    Text = "Hmm, anak yang penurut."
  },
  AvgDialog_18723_Content_27 = {
    Text = "Nyonya Daffodil, bolehkah aku ikut bersama kalian?"
  },
  AvgDialog_18723_Content_28 = {
    Text = "Gadis kurus itu melangkah keluar dari bayang-bayang pohon di belakang kalian, matanya penuh kekhawatiran."
  },
  AvgDialog_18723_Content_29 = {
    Text = "Aku tahu kamu sangat mengkhawatirkan %player%."
  },
  AvgDialog_18723_Content_3 = {
    Text = "Di sini sudah tak ada jejak sang Pemburu Tengkorak, hanya tersisa Daffdail dan bayangan panjang di bawah kakinya."
  },
  AvgDialog_18723_Content_30 = {
    Text = "Tapi maaf, mawar kecilku. Kali ini aku hanya bisa membawa satu orang."
  },
  AvgDialog_18723_Content_31 = {
    Text = "Angin malam bertiup menusuk di jalanan larut malam, Aurla tanpa sadar merapatkan lembaran surat yang cukup untuk menahan dingin dan angin. Dia mendongakkan wajah pucatnya, menatap Daffodil dengan serius."
  },
  AvgDialog_18723_Content_32 = {
    Text = "Kenapa? Meskipun aku tidak pandai bertarung, tapi satu orang tambahan selalu lebih baik, bukan?"
  },
  AvgDialog_18723_Content_33 = {
    Text = "Aku hanya membawa satu orang. Maaf, mawar kecilku, aku punya alasanku sendiri."
  },
  AvgDialog_18723_Content_35 = {
    Text = "Nyonya Daffodil, kamu pasti akan mengawal %player%{Male=tuan,Female=nyonya} pulang dengan selamat, kan?"
  },
  AvgDialog_18723_Content_36 = {
    Text = "Daffodil menatap ngengat yang terus beterbangan di bawah lampu jalan, menghembuskan lingkaran asap bulat dari mulutnya dengan santai."
  },
  AvgDialog_18723_Content_37 = {
    Text = "Tentu saja, tenanglah."
  },
  AvgDialog_18723_Content_4 = {
    Text = "Entah mengapa, kamu merasa dia sudah berdiri di sana sangat, sangat lama."
  },
  AvgDialog_18723_Content_5 = {
    Text = "Seolah sejak masa lampau yang tak terhingga, dia telah berdiri sendirian di sini, menatap kejauhan dalam diam, tanpa mengucapkan sepatah kata pun."
  },
  AvgDialog_18723_Content_6 = {
    Text = "Kamu sudah datang ya."
  },
  AvgDialog_18723_Content_7 = {
    Text = "Daffdail berbalik, ekspresinya tetap tenang seperti biasa."
  },
  AvgDialog_18723_Content_8 = {
    Text = "Pemburu Tengkoraknya? Kehilangan jejak?"
  },
  AvgDialog_18723_Content_9 = {
    Text = "Ya, kehilangan jejak. Tapi… kurasa aku sudah tahu jawabannya."
  },
  AvgDialog_18724_Content_1 = {
    Text = "Dari Kejauhan"
  },
  AvgDialog_18724_Content_10 = {
    Text = "Dari kondisi jenazah dan kesaksian saksi mata, waktu kematian keduanya berdekatan, tidak lebih dari setengah jam."
  },
  AvgDialog_18724_Content_11 = {
    Text = "Bagaimana dengan lokasi kematiannya, apakah berdekatan?"
  },
  AvgDialog_18724_Content_12 = {
    Text = "Ramona menggelengkan kepalanya."
  },
  AvgDialog_18724_Content_13 = {
    Text = "Bahkan dengan mobil pun butuh lebih dari satu jam, apalagi sangat sedikit orang di kota yang punya mobil."
  },
  AvgDialog_18724_Content_14 = {
    Text = "…Mungkin Pak Tua Freeman benar."
  },
  AvgDialog_18724_Content_15 = {
    Text = "Pemburu Tengkorak adalah sebuah organisasi. Tapi apa sebenarnya tujuan mereka?"
  },
  AvgDialog_18724_Content_16 = {
    Text = "Kepala@2lebih banyak kepala…"
  },
  AvgDialog_18724_Content_17 = {
    Text = "Tiba-tiba angin dingin berhembus dari belakang."
  },
  AvgDialog_18724_Content_18 = {
    Text = "Kamu menoleh ke belakang, dan melihat mayat yang kepalanya telah kamu penggal itu menerjang ke arahmu dengan kecepatan luar biasa."
  },
  AvgDialog_18724_Content_19 = {Text = "?!"},
  AvgDialog_18724_Content_2 = {
    Text = "00:15, Pondok Kayu Aurla"
  },
  AvgDialog_18724_Content_20 = {
    Text = "Berikan kepalamu@3berikan@1kepala@4"
  },
  AvgDialog_18724_Content_21 = {
    Text = "Kamu dengan cepat menghindar. Mayat itu langsung menabrak kaca di depan dan seketika menghilang dalam kegelapan malam."
  },
  AvgDialog_18724_Content_22 = {
    Text = "Kecepatannya luar biasa… Apakah itu entitas terjaga dari Ranah Superdimensi?"
  },
  AvgDialog_18724_Content_23 = {
    Text = "Saat masih kebingungan, aroma narsis yang pekat sudah menyelimutimu berlapis-lapis."
  },
  AvgDialog_18724_Content_24 = {
    Text = "Ujung gaun berwarna ungu melesat melewati pandanganmu, lalu juga menghilang di hadapanmu."
  },
  AvgDialog_18724_Content_25 = {
    Text = "Nyonya Daffodil…?"
  },
  AvgDialog_18724_Content_26 = {
    Text = "Cepat kejar, jangan biarkan petunjuk penting ini lolos."
  },
  AvgDialog_18724_Content_3 = {
    Text = "Kau mencari sudut yang sepi dan menjelaskan situasi yang baru saja terjadi kepada Ramona."
  },
  AvgDialog_18724_Content_4 = {
    Text = "Tentu saja, kau melewatkan bagian di mana kau hampir disembelih."
  },
  AvgDialog_18724_Content_6 = {
    Text = "Aku sudah memanggilmu <Red:35> kali sejak sore tadi, dan kau tidak memberikan respons sama sekali."
  },
  AvgDialog_18724_Content_7 = {
    Text = "Maaf, semuanya terjadi begitu mendadak…"
  },
  AvgDialog_18724_Content_8 = {
    Text = "…Jangan sampai terulang lagi."
  },
  AvgDialog_18724_Content_9 = {
    Text = [[
Identitas korban baru yang ditemukan pada siang hari sudah selesai diselidiki.
Tukang kayu Damon Mendes, 35 tahun; pemuda pengangguran Thomas Quillen, 23 tahun.]]
  },
  AvgDialog_18725_Content_1 = {
    Text = "Sebuah bingkai foto yang tertelungkup menarik perhatianmu."
  },
  AvgDialog_18725_Content_10 = {
    Text = "<RedItalic:Hari Minggu dia minum sepuluh botol, kehilangan pekerjaan, kehilangan istrinya.>"
  },
  AvgDialog_18725_Content_11 = {
    Text = "Seseorang bersenandung pelan, menyanyikan lagu anak-anak tanpa variasi irama."
  },
  AvgDialog_18725_Content_12 = {
    Text = "Melodi yang kering itu bagaikan tangan lembap tak kasat mata, membelai lembut bulu kuduk di tengkukmu yang sudah berdiri tegak."
  },
  AvgDialog_18725_Content_13 = {
    Text = "<RedItalic:Freeman tua menangis tersedu-sedu, hari Senin dia minum sebelas botol lagi……>"
  },
  AvgDialog_18725_Content_14 = {
    Text = "Diiringi suara papan kayu yang berderit, Harriet berdiri tanpa suara di depan lorong yang gelap."
  },
  AvgDialog_18725_Content_15 = {
    Text = "Benar, Freeman tua adalah suamiku."
  },
  AvgDialog_18725_Content_16 = {Text = "Apa?!"},
  AvgDialog_18725_Content_17 = {
    Text = "Saat itu, semua orang mengira aku sudah mati. Suamiku juga begitu."
  },
  AvgDialog_18725_Content_18 = {
    Text = "Kemudian, entah berapa lama berlalu, aku hidup kembali… tapi aku menjadi sedikit berbeda."
  },
  AvgDialog_18725_Content_19 = {
    Text = "Kau terdiam, dalam hati sudah bisa menebak kelanjutan ceritanya."
  },
  AvgDialog_18725_Content_2 = {
    Text = "Dari dapur terdengar suara air mendidih yang bergemericik, Nyonya Harriet masih sibuk di dalam."
  },
  AvgDialog_18725_Content_20 = {
    Text = "Setelah manusia terinfeksi Erosi, jiwa mereka akan mengalami kerusakan permanen, yang kemudian memicu berbagai macam komplikasi."
  },
  AvgDialog_18725_Content_21 = {
    Text = "Nyonya Harriet menjadi seperti ini tidaklah mengherankan."
  },
  AvgDialog_18725_Content_22 = {
    Text = "Aku mulai mendambakan tengkorak, banyak tengkorak… jadi aku diam-diam pergi ke sebuah kuburan massal."
  },
  AvgDialog_18725_Content_23 = {
    Text = "Aku menindih tubuh Pinoco tua, menggorok kepalanya sekuat tenaga dengan sabit berkarat.\nTapi saat itu aku terlalu lemah, bahkan menggenggam pisau pun tak sanggup…"
  },
  AvgDialog_18725_Content_24 = {
    Text = "Lalu coba tebak siapa yang kutemui?"
  },
  AvgDialog_18725_Content_26 = {
    Text = "Aku bertemu suamiku."
  },
  AvgDialog_18725_Content_27 = {
    Text = "Dia bertambah gemuk, bertambah tua, dan juga menjadi seorang pemabuk."
  },
  AvgDialog_18725_Content_28 = {
    Text = "Heh heh…… Dunia ini selalu menemukan cara baru untuk menyiksa kita, makhluk-makhluk malang ini."
  },
  AvgDialog_18725_Content_29 = {
    Text = "Dia menjinjing botol minumannya, menatapku seperti menatap anjing liar."
  },
  AvgDialog_18725_Content_3 = {
    Text = "Kamu perlahan membalikkan bingkai foto itu."
  },
  AvgDialog_18725_Content_30 = {
    Text = "Dia terus tertawa. Ya, aku tahu penampilanku saat itu pasti menyedihkan sekaligus menggelikan."
  },
  AvgDialog_18725_Content_31 = {
    Text = "Tapi dia ternyata…… sama sekali tidak mengenaliku lagi."
  },
  AvgDialog_18725_Content_32 = {
    Text = "……Jadi kau yang dimaksud olehnya sebagai Pemburu Tengkorak itu."
  },
  AvgDialog_18725_Content_33 = {
    Text = "Harriet memiringkan kepalanya ke kanan secara mekanis, terdengar suara \"krak krak\" dari lehernya."
  },
  AvgDialog_18725_Content_34 = {
    Text = "Ya. Meski tahu dia sudah lama tidak mengingatku, aku tetap diam-diam pergi untuk melihatnya."
  },
  AvgDialog_18725_Content_35 = {
    Text = "Lalu kau mendengar percakapan kami, tahu aku sedang menyelidiki kasus pembunuhan, baru kemudian memutuskan untuk menguntit dan menyerang diam-diam?"
  },
  AvgDialog_18725_Content_37 = {
    Text = "Kau memang berbeda dari mereka. Aku sudah bicara sebanyak ini, tapi kau masih bisa tetap tenang."
  },
  AvgDialog_18725_Content_38 = {
    Text = "Kau menghela napas pelan, menunduk menatap pintu yang terkunci rapat di sampingmu."
  },
  AvgDialog_18725_Content_39 = {
    Text = "Darah merah gelap seperti sirup kental perlahan merembes keluar dari celah pintu, sedikit demi sedikit merambat ke kakimu."
  },
  AvgDialog_18725_Content_4 = {
    Text = "Ini adalah foto keluarga yang sudah usang. Wajah istri dan anak-anak sudah lama kabur tak jelas, hanya tersisa sang suami yang berdiri di sisi paling kiri."
  },
  AvgDialog_18725_Content_40 = {
    Text = "Kau tahu tidak……"
  },
  AvgDialog_18725_Content_41 = {
    Text = "Di lantai sini, di langit-langit, di lemari…… semuanya berbau darah dan mayat."
  },
  AvgDialog_18725_Content_42 = {
    Text = "Sejak detik pertama aku masuk, aku sudah mengetahui semuanya."
  },
  AvgDialog_18725_Content_5 = {
    Text = "Tubuhnya kekar, bersandar dengan santai di depan rumah baru yang baru selesai dibangun, menghadap kamera dengan senyuman yang begitu cerah."
  },
  AvgDialog_18725_Content_6 = {
    Text = "Kau menatap alis dan matanya yang tampak sedikit familiar, sebuah pikiran absurd tiba-tiba menyambar bagai kilat di benakmu."
  },
  AvgDialog_18725_Content_7 = {
    Text = "Freeman tua……?!"
  },
  AvgDialog_18725_Content_8 = {
    Text = "Mungkinkah dia suami Nyonya Harriet?"
  },
  AvgDialog_18725_Content_9 = {
    Text = "<RedItalic:Freeman tua, Freeman tua, si pemabuk miskin dan gila, Freeman tua……>"
  },
  AvgDialog_18726_Content_1 = {
    Text = "Kau berjalan menuju kedalaman gang, air hujan sudah lama membasahi jaketmu."
  },
  AvgDialog_18726_Content_10 = {
    Text = "Tak, tak, tak."
  },
  AvgDialog_18726_Content_11 = {
    Text = "Dari jalanan di luar gang terdengar langkah kaki yang santai, sebuah siluet samar muncul di bawah lampu jalan."
  },
  AvgDialog_18726_Content_12 = {
    Text = "Di sini berbahaya, cepat pergi—"
  },
  AvgDialog_18726_Content_13 = {
    Text = "Itu seorang wanita."
  },
  AvgDialog_18726_Content_14 = {
    Text = "Dia berdiri sendirian di bawah lampu jalan, tangannya menjinjing sebuah kepala yang tambun, ukurannya cocok sempurna dengan leher jasad tanpa kepala di belakangmu."
  },
  AvgDialog_18726_Content_15 = {
    Text = "Darah segar menetes dari leher kepala itu, mengalir perlahan menyusuri celah-celah batu jalanan."
  },
  AvgDialog_18726_Content_16 = {
    Text = [[
Berdiri di situ, jangan bergerak.
Siapa kau?]]
  },
  AvgDialog_18726_Content_17 = {
    Text = "Lampu jalan kekuningan terus berkedip-kedip, mengeluarkan dengungan listrik yang menjengkelkan."
  },
  AvgDialog_18726_Content_18 = {
    Text = "Wanita itu mengangkat kepalanya, dan akhirnya kau bisa melihat jelas wajahnya."
  },
  AvgDialog_18726_Content_2 = {
    Text = "Darah merah gelap mengalir dari balik bayangan, mengulurkan tentakel-tentakel mengerikan, mengirimkan undangan tanpa suara kepadamu."
  },
  AvgDialog_18726_Content_20 = {
    Text = "<Gray:Daph…… Nyonya Daphdale?>"
  },
  AvgDialog_18726_Content_3 = {
    Text = "Di sini sangat sunyi, yang kau dengar hanyalah suara hujan, langkah kaki, dan napas."
  },
  AvgDialog_18726_Content_4 = {
    Text = "Semuanya bagaikan dentuman genderang yang saling bersilangan kacau, semakin cepat, semakin keras, hingga kau tiba di ujung gang."
  },
  AvgDialog_18726_Content_5 = {
    Text = "Jasad yang tambun dibuang begitu saja di atas tumpukan sampah, terkulai lemas."
  },
  AvgDialog_18726_Content_6 = {
    Text = "Potongan di leher begitu kabur dan berantakan, darah merah gelap mengalir deras dari pembuluh darahnya."
  },
  AvgDialog_18726_Content_7 = {
    Text = "Tanpa perlu menyentuhnya, kau tahu darah itu pasti masih hangat."
  },
  AvgDialog_18726_Content_8 = {
    Text = "Kepala hilang, bekas luka bergerigi di leher…"
  },
  AvgDialog_18726_Content_9 = {
    Text = "Ini ulah \"Pemburu Tengkorak\"."
  },
  AvgDialog_18727_Content_1 = {
    Text = "Pertemuan Tak Terduga"
  },
  AvgDialog_18727_Content_10 = {
    Text = "Jika dia tidak berbohong atau salah lihat, ya."
  },
  AvgDialog_18727_Content_11 = {
    Text = "<Blue:Tim perintis> telah tiba di Kota Reini satu minggu yang lalu, dan mendeteksi tanda-tanda aktivitas Inti Perak di lokasi kematian."
  },
  AvgDialog_18727_Content_12 = {
    Text = "Termasuk tiga kasus tadi, ini sudah merupakan insiden <Blue:pembunuhan Pemburu Tengkorak> yang kedelapan di Kota Reini."
  },
  AvgDialog_18727_Content_13 = {
    Text = "Pemburu Tengkorak? Begitukah orang-orang di sini menyebut pelakunya?"
  },
  AvgDialog_18727_Content_14 = {
    Text = "Cukup menggambarkan, bukan? Berkat ulahnya, sudah tidak ada yang berani keluar setelah gelap di sini."
  },
  AvgDialog_18727_Content_15 = {
    Text = "Kamu memandang jalanan sepi di hadapanmu."
  },
  AvgDialog_18727_Content_16 = {
    Text = "Baru pukul 8 malam, semua pintu dan jendela di sekitar sudah terkunci rapat. Ketakutan merembes keluar dari jendela-jendela yang gelap, menyelimuti sekitar dalam keheningan."
  },
  AvgDialog_18727_Content_17 = {
    Text = "Selain satu dua gonggongan anjing yang panjang, tempat ini sunyi senyap."
  },
  AvgDialog_18727_Content_18 = {
    Text = "Rintik-rintik……"
  },
  AvgDialog_18727_Content_19 = {Text = "Eh, hujan?"},
  AvgDialog_18727_Content_2 = {
    Text = [[
Beren Stoke, 46 tahun, meninggal pada 12 September di dapur rumahnya.
<Red:Kepala hilang>, bagian tubuh lainnya utuh, terdapat luka sayatan bergerigi di leher.]]
  },
  AvgDialog_18727_Content_20 = {
    Text = "Gerimis sejuk menetes dari langit malam, menyelimuti pandanganmu dengan lapisan tipis kabut putih."
  },
  AvgDialog_18727_Content_21 = {
    Text = "Aku dengar suara hujan di tempatmu. Bawa payung?"
  },
  AvgDialog_18727_Content_22 = {
    Text = "<Shake:Gawat. Kamu selalu yang bawa payung, jadi……>"
  },
  AvgDialog_18727_Content_23 = {
    Text = "Sepertinya aku masih perlu membiasakan diri hidup tanpamu."
  },
  AvgDialog_18727_Content_25 = {
    Text = "Maaf, kali ini aku tidak bisa ikut bersamamu."
  },
  AvgDialog_18727_Content_26 = {
    Text = "Nona Doerr bersikeras agar aku tinggal, untuk melakukan riset Erosi yang katanya \"sangat penting\"……"
  },
  AvgDialog_18727_Content_27 = {
    Text = "<Small:Ramona, tolong ambilkan sampel Inti Perak di rak kelima, lapisan ketiga, nomor SI-3007……>"
  },
  AvgDialog_18727_Content_29 = {
    Text = "Jaga dirimu baik-baik, %player%. Soal penginapan…… Nona <Blue:Orla> akan mengatur semuanya."
  },
  AvgDialog_18727_Content_3 = {
    Text = [[
Dwight Williams, 56 tahun, meninggal pada 13 September di persimpangan Jalan Deman.
<Red:Kepala hilang>, bagian tubuh lainnya utuh, terdapat luka sayatan bergerigi di leher.]]
  },
  AvgDialog_18727_Content_30 = {
    Text = "Nona Orla? Pantas jarang terlihat di sekolah, ternyata dia tinggal di luar?"
  },
  AvgDialog_18727_Content_31 = {
    Text = "Misager bukan semacam kamp konsentrasi yang hanya bisa masuk tanpa bisa keluar."
  },
  AvgDialog_18727_Content_32 = {
    Text = [[
Awakened dengan tingkat bahaya rendah boleh keluar untuk berlibur, menginap, atau mengunjungi keluarga.
Syaratnya sederhana: ajukan permohonan terlebih dahulu, dan jangan bikin masalah.]]
  },
  AvgDialog_18727_Content_33 = {
    Text = "Eh…… jadi Nona Orla juga akan ikut penyelidikan?"
  },
  AvgDialog_18727_Content_34 = {
    Text = "Tidak semua Awakened tertarik dengan misi lapangan. Kalau kamu merasa perlu, kamu bisa tanyakan keinginannya."
  },
  AvgDialog_18727_Content_35 = {
    Text = "Saat ini situasinya masih cukup stabil dan terkendali, tidak perlu—"
  },
  AvgDialog_18727_Content_36 = {Text = "BYUR—"},
  AvgDialog_18727_Content_37 = {
    Text = "Dari gang di depan tiba-tiba terdengar suara daging dan darah yang terciprat, diikuti langkah kaki yang kacau, memecah keheningan malam secara tiba-tiba."
  },
  AvgDialog_18727_Content_38 = {Text = "?!"},
  AvgDialog_18727_Content_39 = {
    Text = "Di waktu seperti ini, suara seperti itu…… jangan-jangan……"
  },
  AvgDialog_18727_Content_4 = {
    Text = "Korban nomor 012, identitas dan usia tidak diketahui, meninggal pada dini hari 16 September di tepi Danau Knerl di utara…"
  },
  AvgDialog_18727_Content_40 = {
    Text = "Ikuti dan lihat. Ingat untuk tetap menjaga kontak."
  },
  AvgDialog_18727_Content_41 = {
    Text = "Semoga Kunci Perak menuntun jalanmu."
  },
  AvgDialog_18727_Content_5 = {
    Text = [[
20:00, Jalan Norwich
Kota Kecil Reini]]
  },
  AvgDialog_18727_Content_6 = {
    Text = "Kepala hilang, bekas luka bergerigi…"
  },
  AvgDialog_18727_Content_7 = {
    Text = "Dan semuanya meninggal saat sedang keluar sendirian atau berada di rumah."
  },
  AvgDialog_18727_Content_8 = {
    Text = "Selain itu, satu minggu setelah kematian Dwight Williams, istrinya mengklaim melihatnya berlari tergesa-gesa di alam liar."
  },
  AvgDialog_18727_Content_9 = {
    Text = "…Bangkit dari kematian?"
  },
  AvgDialog_18764_Content_1 = {
    Text = "Tidak, jangan…"
  },
  AvgDialog_18764_Content_10 = {
    Text = "Uhuk uhuk uhuk... Ka-kamu, dasar curang!"
  },
  AvgDialog_18764_Content_11 = {
    Text = "<SmallShake:Cuma minta kamu main tebak-tebakan saja, kenapa panik begitu sih...>"
  },
  AvgDialog_18764_Content_12 = {
    Text = "Di mana jalan keluar labirin ini?"
  },
  AvgDialog_18764_Content_13 = {
    Text = "Hihihi, mau tahu? Kalau begitu berlututlah, minta maaf yang benar kepada Yang Mulia ini, lalu..."
  },
  AvgDialog_18764_Content_14 = {
    Text = "Kamu perlahan mengangkat tangan."
  },
  AvgDialog_18764_Content_15 = {
    Text = "<Shake:Tu-tunggu dulu! Aku bicara...>"
  },
  AvgDialog_18764_Content_16 = {
    Text = "Gadis itu membuka mulutnya, lalu menundukkan kepala dengan lesu."
  },
  AvgDialog_18764_Content_17 = {
    Text = "Sebenarnya... aku juga tidak tahu. Aku sudah terkurung di sini hampir lebih dari seribu tahun..."
  },
  AvgDialog_18764_Content_18 = {
    Text = "Selain tidur dan melamun, yang kulakukan hanya mengurus anak-anakku. Aku hampir gila karena bosan!"
  },
  AvgDialog_18764_Content_20 = {
    Text = "Bukankah kamu penguasa labirin ini? Bagaimana bisa tidak tahu di mana jalan keluarnya?"
  },
  AvgDialog_18764_Content_21 = {
    Text = "<SmallShake:Itu harus ditanyakan pada orang yang melemparku ke sini. Mana aku tahu apa yang Dia pikirkan...>"
  },
  AvgDialog_18764_Content_22 = {
    Text = "Bagaimana bisa begini..."
  },
  AvgDialog_18764_Content_23 = {
    Text = "Kalau begitu, misalnya, maksudku misalnya saja—"
  },
  AvgDialog_18764_Content_24 = {
    Text = "Orang yang memasuki labirin bukanlah entitas fisik, melainkan hadir dalam bentuk kesadaran tertentu."
  },
  AvgDialog_18764_Content_25 = {
    Text = "Apakah mungkin dia, eh, misalnya… mengabaikan aturan labirin ini?"
  },
  AvgDialog_18764_Content_26 = {
    Text = "Agrippa menatapmu dengan pandangan aneh."
  },
  AvgDialog_18764_Content_27 = {
    Text = "Tentu saja tidak bisa."
  },
  AvgDialog_18764_Content_28 = {
    Text = "Mau coba tebak, kenapa kamu melihat begitu banyak orang dan tempat yang familiar di dalam labirin?"
  },
  AvgDialog_18764_Content_29 = {
    Text = "Halusinasi? Bukan, mungkin ingatan…"
  },
  AvgDialog_18764_Content_3 = {
    Text = "Akhirnya kamu berhasil membersihkan \"Charlotte\" yang terakhir."
  },
  AvgDialog_18764_Content_30 = {
    Text = "Agrippa menggelengkan kepalanya."
  },
  AvgDialog_18764_Content_31 = {
    Text = "Bukan keduanya. Lebih tepatnya, itu adalah <Yellow:kesadaran>."
  },
  AvgDialog_18764_Content_32 = {
    Text = "<Yellow:Yang terjebak di dalam labirin, sejak awal memang hanya kesadaran kalian.>"
  },
  AvgDialog_18764_Content_4 = {
    Text = "Makam Kunci perlahan menghilang, dan kamu kembali ke tempat semula."
  },
  AvgDialog_18764_Content_5 = {
    Text = "Keluarlah, aku tahu kamu di mana."
  },
  AvgDialog_18764_Content_6 = {
    Text = "Dari kedalaman bumi terdengar dengungan bergetar, lalu tanah perlahan-lahan retak terbuka."
  },
  AvgDialog_18764_Content_7 = {Text = "Duaaarr!!"},
  AvgDialog_18764_Content_8 = {
    Text = "Puah... cuih cuih cuih!!"
  },
  AvgDialog_18764_Content_9 = {
    Text = "Agrippa tiba-tiba menyembul keluar dari dalam tanah, tubuhnya dipenuhi debu."
  },
  AvgDialog_18765_Content_1 = {
    Text = "Kluster Kesadaran"
  },
  AvgDialog_18765_Content_10 = {
    Text = "Tugas minggu ini sudah dikerjakan? Ujian \"Pengantar Korosi\" sebentar lagi, bagaimana persiapanmu?"
  },
  AvgDialog_18765_Content_11 = {
    Text = "Ramona?! Tidak, aku tidak……tunggu, bukan……"
  },
  AvgDialog_18765_Content_12 = {
    Text = "%player%, hari ini kamu terlambat 5 menit di kelas, total keterlambatan bulan ini 30 menit 15 detik."
  },
  AvgDialog_18765_Content_13 = {
    Text = "Setelah kelas selesai, datang ke kantorku."
  },
  AvgDialog_18765_Content_14 = {Text = "——!!"},
  AvgDialog_18765_Content_15 = {
    Text = "Pfft. <Big:Hahahahahaha!>"
  },
  AvgDialog_18765_Content_16 = {
    Text = "Kaget, ya? Kamu harus lihat wajahmu sendiri di cermin sekarang."
  },
  AvgDialog_18765_Content_18 = {
    Text = "Trik-trik… berubah wujud ini, kamu pelajari dari mana?"
  },
  AvgDialog_18765_Content_19 = {
    Text = "Kamu pernah melihat data Agrippa di ruang arsip Awakened. Di sana tidak ada catatan apa pun yang berkaitan dengan \"perubahan wujud\"."
  },
  AvgDialog_18765_Content_20 = {
    Text = "Pelajari? Aku adalah penguasa labirin ini. Di wilayahku, tentu saja aku bisa ber-buat se-su-ka ha-ti."
  },
  AvgDialog_18765_Content_21 = {
    Text = "Jangan bilang satu… sepuluh, seratus pun bisa kutunjukkan padamu."
  },
  AvgDialog_18765_Content_22 = {
    Text = "Setelah berkata demikian, Agrippa menghilang lagi."
  },
  AvgDialog_18765_Content_23 = {
    Text = "Tak lama kemudian, satu, dua… semakin banyak Charlotte muncul di hadapanmu."
  },
  AvgDialog_18765_Content_24 = {
    Text = "Tebak yang mana yang benar-benar aku, hihihi…"
  },
  AvgDialog_18765_Content_25 = {
    Text = "Huhu… Charlotte yang mana yang sebenarnya Agrippa?"
  },
  AvgDialog_18765_Content_26 = {
    Text = "Satu kali, hanya satu kali kesempatan…"
  },
  AvgDialog_18765_Content_27 = {
    Text = "Tak terhitung suara-suara tajam terjalin menjadi melodi yang kacau dan tak beraturan, berkeliaran di dalam benakmu."
  },
  AvgDialog_18765_Content_28 = {
    Text = "Pergi, pergi…!!"
  },
  AvgDialog_18765_Content_29 = {
    Text = "Kamu menarik napas dalam-dalam, akhirnya berhasil menenangkan pikiranmu."
  },
  AvgDialog_18765_Content_3 = {
    Text = "Charlotte, bagaimana bisa kamu jadi seperti ini?"
  },
  AvgDialog_18765_Content_30 = {
    Text = "Maaf. Kalian semua terlihat sama, aku tidak bisa menebaknya."
  },
  AvgDialog_18765_Content_31 = {
    Text = "Hah? Secepat itu menyerah, membosankan sekali."
  },
  AvgDialog_18765_Content_33 = {
    Text = "Detik berikutnya, \"Charlotte\" terjungkal ke tanah.\nKamu memijat pelipismu dan berkata dengan tenang—"
  },
  AvgDialog_18765_Content_34 = {
    Text = "Tapi tidak masalah."
  },
  AvgDialog_18765_Content_35 = {
    Text = "Aku bisa menghajar kalian semua sampai tumbang, lalu bertanya satu per satu."
  },
  AvgDialog_18765_Content_4 = {
    Text = "\"Charlotte\" memutar kepalanya, dari kedalaman tenggorokannya terdengar dengungan yang mengerikan."
  },
  AvgDialog_18765_Content_5 = {
    Text = "<Shake:Hihihi, tidak menyangka, kan? Temanmu itu sudah lama jadi keturunanku!>"
  },
  AvgDialog_18765_Content_6 = {
    Text = "Suara ini……Kau Agrippa?"
  },
  AvgDialog_18765_Content_7 = {
    Text = [[
Sungguh mengharukan, kamu masih ingat suara Yang Mulia ini.
Tunggu, akan kutunjukkan sesuatu yang hebat!]]
  },
  AvgDialog_18765_Content_8 = {
    Text = "Dari rongga tenggorokan \"Charlotte\" terdengar suara terkekeh yang samar, lalu lehernya berputar, dan seketika penampilannya berubah."
  },
  AvgDialog_18765_Content_9 = {
    Text = "%player%, kamu diam-diam makan kue lagi!"
  },
  AvgDialog_18766_Content_1 = {Text = "pintu"},
  AvgDialog_18766_Content_10 = {
    Text = "Sudah siap, @1? Ayo kita dorong bersama."
  },
  AvgDialog_18766_Content_11 = {
    Text = "Kriiieet——"
  },
  AvgDialog_18766_Content_12 = {Text = "<Big:!!!>"},
  AvgDialog_18766_Content_13 = {
    Text = "Ini... tempat apa...?"
  },
  AvgDialog_18766_Content_14 = {
    Text = "Ini adalah tempat di mana kau akan tinggal dengan manis selama sisa hidupmu."
  },
  AvgDialog_18766_Content_15 = {
    Text = "Gadis itu duduk di atas meja berongga sambil tersenyum, kedua tangan menopang dagu, kaki kanan yang disilangkan berayun-ayun dengan santai."
  },
  AvgDialog_18766_Content_16 = {
    Text = "Selamat datang di labirinku."
  },
  AvgDialog_18766_Content_17 = {
    Text = "Tidurmu nyenyak sekali, aku bahkan berencana menyuapimu serangga kecil supaya kau segar sedikit."
  },
  AvgDialog_18766_Content_18 = {
    Text = "<LightGray:Agrippa...?>"
  },
  AvgDialog_18766_Content_19 = {
    Text = "Kau menunduk memandangi pakaian asing yang kau kenakan, menyadari bahwa kau sekali lagi masuk ke dalam mimpi."
  },
  AvgDialog_18766_Content_2 = {
    Text = "Orang-orang berkata, di dalam labirin \"Dia\", yang hilang bukan hanya arah."
  },
  AvgDialog_18766_Content_20 = {
    Text = [[
Bedanya, kali ini kau kehilangan hampir seluruh ingatan tentang pemilik asli tubuh ini.
Siapa dia? Dari mana dia berasal?]]
  },
  AvgDialog_18766_Content_21 = {
    Text = "Kau tidak tahu apa-apa."
  },
  AvgDialog_18766_Content_22 = {
    Text = "<Shake:Apa yang terjadi... Pemilik asli, bukan, siapa aku...>"
  },
  AvgDialog_18766_Content_23 = {
    Text = "Sudahlah, berhenti berpikir. Kau tidak akan mengingat apa pun."
  },
  AvgDialog_18766_Content_24 = {
    Text = "Bahkan setelah 1 hari, 100 hari, 1000 hari, otakmu akan tetap bersih seperti bayi yang baru lahir."
  },
  AvgDialog_18766_Content_25 = {
    Text = "Sekarang aku beri kau dua pilihan."
  },
  AvgDialog_18766_Content_26 = {
    Text = "<Red:Satu: Buat kontrak denganku, lalu jadilah keturunanku.>"
  },
  AvgDialog_18766_Content_27 = {
    Text = "<Red:Dua: Mati kelaparan di labirin, lalu jadilah keturunanku.>"
  },
  AvgDialog_18766_Content_28 = {
    Text = "Agrippa dengan terampil menjelaskan situasimu dan memberikan pilihan, seolah-olah proses ini sudah diulang tak terhitung kali."
  },
  AvgDialog_18766_Content_29 = {
    Text = "Keturunan? Apa itu?"
  },
  AvgDialog_18766_Content_3 = {
    Text = "Nama, kampung halaman, kekasih…… semua yang penting maupun tidak penting, semuanya akan ditinggalkan."
  },
  AvgDialog_18766_Content_30 = {
    Text = "Tenang saja, tidak beracun, tidak menyakitkan, tidak berbahaya. Soal efek samping? Kau bahkan tidak akan menyadari keberadaannya."
  },
  AvgDialog_18766_Content_31 = {
    Text = "Bagaimana, dibandingkan dewa-dewa jahat yang suka menyuruhmu mengorbankan nyawa atau membunuh kekasihmu sendiri, bukankah aku jauh lebih lembut?"
  },
  AvgDialog_18766_Content_33 = {
    Text = "Sekarang kuberi kau waktu tiga detik untuk memilih. Menandatangani kontrak, atau mati kelaparan?"
  },
  AvgDialog_18766_Content_34 = {Text = "Tiga——"},
  AvgDialog_18766_Content_35 = {Text = "Dua——"},
  AvgDialog_18766_Content_36 = {
    Text = "Baik, aku sudah memutuskan."
  },
  AvgDialog_18766_Content_37 = {Text = "Eh……?"},
  AvgDialog_18766_Content_38 = {
    Text = "Cepat sekali, kau……tidak buruk. Kalau begitu, katakan pilihanmu."
  },
  AvgDialog_18766_Content_39 = {
    Text = "Kau mengangguk, diam-diam menggeser kaki kananmu ke belakang sedikit."
  },
  AvgDialog_18766_Content_4 = {
    Text = "Sejak saat itu, kau hanya memiliki satu identitas: <Red:Keturunan-Nya>."
  },
  AvgDialog_18766_Content_40 = {
    Text = "Pilihanku adalah——"
  },
  AvgDialog_18766_Content_41 = {
    Text = "Kau berbalik dengan tegas dan melesat keluar secepat mungkin."
  },
  AvgDialog_18766_Content_42 = {
    Text = "<BigShake:Lari!!>"
  },
  AvgDialog_18766_Content_43 = {
    Text = "Lama sekali setelah itu……"
  },
  AvgDialog_18766_Content_44 = {
    Text = "Huu……huu……"
  },
  AvgDialog_18766_Content_45 = {
    Text = "Kau berlari di sepanjang lorong panjang, hingga sebuah pintu menghalangi jalanmu."
  },
  AvgDialog_18766_Content_46 = {
    Text = "Museum lilin? Lagi……"
  },
  AvgDialog_18766_Content_47 = {
    Text = "Kalau tidak salah ingat, ini sudah ke-23 kalinya aku melihatnya."
  },
  AvgDialog_18766_Content_48 = {
    Text = "Ya, di sini ada tak terhitung banyaknya pintu, menuju tak terhitung banyaknya ruangan."
  },
  AvgDialog_18766_Content_49 = {
    Text = "Mereka berulang kali muncul di hadapanmu, dengan frekuensi yang cukup tinggi untuk membuat penyelidik paling tenang sekalipun menjadi gila."
  },
  AvgDialog_18766_Content_5 = {
    Text = "<Shake:Ke, keturunan?>"
  },
  AvgDialog_18766_Content_50 = {
    Text = "Kau mendorong pintu dan terus berjalan menyusuri koridor."
  },
  AvgDialog_18766_Content_51 = {
    Text = "Koridor ini lagi……15 kali."
  },
  AvgDialog_18766_Content_52 = {
    Text = "Secara refleks kamu meraba kancing manset perak yang tertanam di ujung lengan bajumu."
  },
  AvgDialog_18766_Content_53 = {
    Text = "Lencana sekolah Misagar dari masa lalu…… Sepertinya kali ini aku menjadi senior dari masa lampau?"
  },
  AvgDialog_18766_Content_54 = {
    Text = "Tapi bagaimana dia bisa masuk ke dalam labirin?"
  },
  AvgDialog_18766_Content_55 = {
    Text = "Sementara kamu merenungkan hal itu, sebuah pintu lagi menghalangi jalanmu."
  },
  AvgDialog_18766_Content_56 = {
    Text = "Sekarang kamu sudah berdiri di depan pintu ini, @1. Buka pintunya."
  },
  AvgDialog_18766_Content_57 = {
    Text = "Siapa yang bicara?!"
  },
  AvgDialog_18766_Content_58 = {
    Text = "Kepala…… sakit sekali. Apakah ini ingatan kakak senior?"
  },
  AvgDialog_18766_Content_59 = {
    Text = "Tarik napas dalam-dalam, %player%. Singkirkan semua pikiran yang mengganggu……"
  },
  AvgDialog_18766_Content_6 = {
    Text = "Ya. Keturunan-keturunan yang tak terhitung jumlahnya, bagaikan gelombang pucat, membanjiri labirin dari segala penjuru."
  },
  AvgDialog_18766_Content_60 = {
    Text = "Kamu memaksa dirimu untuk tenang, memutar gagang kuningan di tanganmu, dan perlahan menarik pintu terbuka."
  },
  AvgDialog_18766_Content_61 = {
    Text = "……Makam Kunci?"
  },
  AvgDialog_18766_Content_62 = {
    Text = "Di antara kabut yang menyelimuti, kamu menyadari sosok yang terasa familiar sekaligus asing."
  },
  AvgDialog_18766_Content_63 = {
    Text = "Charlotte…… <Big:Charlotte!>"
  },
  AvgDialog_18766_Content_64 = {
    Text = "Kamu teringat gadis bernama Charlotte ini. Dia adalah sahabat yang membawa \"kamu\" masuk ke dalam labirin."
  },
  AvgDialog_18766_Content_65 = {
    Text = "<Big:Tunggu aku, Charlotte!>"
  },
  AvgDialog_18766_Content_66 = {
    Text = "Kamu berlari mengejarnya dan meraih pergelangan tangan Charlotte."
  },
  AvgDialog_18766_Content_67 = {
    Text = "Saat kulit saling bersentuhan, tiba-tiba tak terhitung fragmen yang kacau melintas di benakmu."
  },
  AvgDialog_18766_Content_68 = {
    Text = "Buka pintunya, @1."
  },
  AvgDialog_18766_Content_69 = {
    Text = "<Shake:Tidak, a-aku tiba-tiba ingat PR-ku belum selesai, aku ingin——>"
  },
  AvgDialog_18766_Content_7 = {
    Text = "Jalur masuk ke labirin ada di mana-mana. Di dalam dinding, di dalam saluran pembuangan, dan di tempat kita berada sekarang……"
  },
  AvgDialog_18766_Content_70 = {
    Text = "<Big:Aaaaah!!>"
  },
  AvgDialog_18766_Content_71 = {
    Text = "<Shake:Charlotte, wajahmu……>"
  },
  AvgDialog_18766_Content_72 = {
    Text = "Pintu……pintu……"
  },
  AvgDialog_18766_Content_73 = {
    Text = "@1pintu@2buka@4"
  },
  AvgDialog_18766_Content_74 = {
    Text = "<RedBig:Buka pintunya……>"
  },
  AvgDialog_18766_Content_75 = {
    Text = "Jadi begitu. Kaulah yang menipu \"aku\" masuk ke dalam labirin……"
  },
  AvgDialog_18766_Content_76 = {
    Text = "Secara refleks kamu melepaskan pergelangan tangan Charlotte dan mundur beberapa langkah."
  },
  AvgDialog_18766_Content_77 = {
    Text = "Kabut perlahan menghilang. Charlotte dengan susah payah berbalik, menatapmu dengan penuh kesedihan."
  },
  AvgDialog_18766_Content_78 = {
    Text = "……@4pintu@4@1"
  },
  AvgDialog_18766_Content_79 = {
    Text = "——Dengan sepasang rongga mata yang gelap menganga itu."
  },
  AvgDialog_18766_Content_8 = {
    Text = "Di dalam pintu rahasia di bawah <Blue:Perpustakaan Kota>."
  },
  AvgDialog_18766_Content_9 = {
    Text = "<Shake:Ti, tidak kusangka tempat seperti ini benar-benar ada…… Semua legenda itu ternyata nyata……>"
  },
  AvgDialog_18767_Content_1 = {
    Text = "Ujung Labirin"
  },
  AvgDialog_18767_Content_10 = {
    Text = "Sst…… pejamkan matamu, kosongkan pikiranmu, jangan pikirkan apa pun."
  },
  AvgDialog_18767_Content_11 = {
    Text = "Jangan lakukan apa pun……"
  },
  AvgDialog_18767_Content_12 = {Text = "Ugh!!"},
  AvgDialog_18767_Content_13 = {
    Text = "Kepalaku rasanya mau pecah…… lain kali lebih baik jangan terlalu sering pakai cara ini……"
  },
  AvgDialog_18767_Content_14 = {
    Text = "<Shake:Minggir, minggir kalian semua!>"
  },
  AvgDialog_18767_Content_15 = {
    Text = "Siapa pun yang berani menyentuh keluargaku, aku akan membunuh babi ini terlebih dahulu!!"
  },
  AvgDialog_18767_Content_16 = {
    Text = "Mata pisau yang gemetar langsung menempel di lehermu."
  },
  AvgDialog_18767_Content_17 = {Text = "...?"},
  AvgDialog_18767_Content_18 = {
    Text = "Berhasil memasuki mimpi — meskipun bukan dengan cara kemunculan yang kau bayangkan."
  },
  AvgDialog_18767_Content_19 = {
    Text = "Di depan, berkerumun sekelompok budak bertelanjang dada. Sikap patuh mereka sehari-hari telah lenyap, mata mereka berkilat penuh kebencian."
  },
  AvgDialog_18767_Content_2 = {
    Text = "Maksudmu, kau bisa menyelami kesadaranku, lalu mengubah masa lalu?"
  },
  AvgDialog_18767_Content_20 = {
    Text = "Menghadapi ancaman Agrippa, mereka terdiam sejenak, lalu meledak dalam tawa."
  },
  AvgDialog_18767_Content_21 = {
    Text = "Pfft. Hahahahahaha!"
  },
  AvgDialog_18767_Content_22 = {
    Text = "Bagaimana, tuan putri kecil kita ternyata punya nyali juga ya!"
  },
  AvgDialog_18767_Content_23 = {
    Text = "Heh. Tidak percaya ya……"
  },
  AvgDialog_18767_Content_24 = {
    Text = "Bilah tajam menggores dengan cepat, rasa sakit yang luar biasa langsung menjalar di lehermu."
  },
  AvgDialog_18767_Content_25 = {
    Text = "Ukh! Kau serius rupanya!!"
  },
  AvgDialog_18767_Content_26 = {
    Text = "<Big:Diam!> Kau dan mereka, jelas-jelas satu komplotan! Kaulah yang mencuri kunci rumah kami dan surat penjualan budak!"
  },
  AvgDialog_18767_Content_27 = {Text = "...?"},
  AvgDialog_18767_Content_28 = {
    Text = "Dan kalian semua! Siapa pun yang tertawa lagi, aku akan menggores leher {Male=dia,Female=dia} sekali lagi!"
  },
  AvgDialog_18767_Content_29 = {
    Text = "Turunkan pisaumu, Agrippa…… <Big:Cepat pergi!>"
  },
  AvgDialog_18767_Content_3 = {
    Text = "Kalau kau memang sehebat itu, bagaimana bisa kau terjebak olehku?"
  },
  AvgDialog_18767_Content_31 = {
    Text = "Cambuk menghantam tubuh wanita itu dengan keras, dia bahkan belum sempat mengeluarkan suara apa pun sebelum pingsan."
  },
  AvgDialog_18767_Content_32 = {
    Text = "<Big:Ibu!!>"
  },
  AvgDialog_18767_Content_33 = {
    Text = "Simpan saja tingkah lakumu yang menggelikan itu, sekarang kami bukan budakmu lagi."
  },
  AvgDialog_18767_Content_34 = {
    Text = "Waktu dulu pamer kekuatan di arena latihan, kenapa tidak pernah memikirkan hari ini?"
  },
  AvgDialog_18767_Content_35 = {
    Text = "Buka matamu lebar-lebar dan lihat baik-baik, \"tuan putri kecil\". Lihat bagaimana kami mempermalukan kalian……"
  },
  AvgDialog_18767_Content_36 = {
    Text = "<Shake:Pengecut, kalian semua pengecut! Beraninya kalian……>"
  },
  AvgDialog_18767_Content_37 = {
    Text = "<Shake:Yang menyiksa kalian itu aku, bukan mereka…… tidak, akulah yang terlalu bodoh, seharusnya aku tidak memperlakukan kalian seperti itu……>"
  },
  AvgDialog_18767_Content_38 = {
    Text = "<Shake:Lampiaskan semuanya padaku, mau melakukan apa pun juga boleh! Asalkan lepaskan ibuku……>"
  },
  AvgDialog_18767_Content_39 = {
    Text = "Gadis itu sudah panik hingga bicaranya tak karuan, belati di tangannya bergetar hebat, hampir saja jatuh ke tanah."
  },
  AvgDialog_18767_Content_4 = {
    Text = "Uhuk uhuk…… tepatnya, memengaruhi, bukan mengubah."
  },
  AvgDialog_18767_Content_40 = {
    Text = "Kau menghela napas pelan, lalu perlahan mengambil belati dari tangannya."
  },
  AvgDialog_18767_Content_41 = {
    Text = "Jangan takut, Agrippa. Aku akan membantumu."
  },
  AvgDialog_18767_Content_42 = {
    Text = "Membantuku? Bukankah kau……"
  },
  AvgDialog_18767_Content_43 = {
    Text = "Kau berdiri di depan Agrippa, menatap langsung para budak di hadapanmu."
  },
  AvgDialog_18767_Content_44 = {
    Text = [[
Cukup, waktu bermain sudah berakhir.
Kalian sudah mendapatkan apa yang kalian inginkan, sekarang pergilah.]]
  },
  AvgDialog_18767_Content_45 = {
    Text = "Wah, ada yang merasa jadi bos dan sedang menasihati kita."
  },
  AvgDialog_18767_Content_46 = {
    Text = "Cres, bukankah seharusnya kau berdiri di pihak kami?"
  },
  AvgDialog_18767_Content_47 = {
    Text = "Kau menggelengkan kepala."
  },
  AvgDialog_18767_Content_48 = {
    Text = "Aku selalu menghormati perjuangan perlawanan kalian, tapi tidak ada yang boleh membunuh orang tak bersalah sembarangan."
  },
  AvgDialog_18767_Content_49 = {
    Text = "\"Tak bersalah\"……?"
  },
  AvgDialog_18767_Content_5 = {
    Text = "Jangan meremehkan dirimu sendiri, labirinmu jauh lebih rumit dari yang kubayangkan……"
  },
  AvgDialog_18767_Content_50 = {
    Text = "Heh, orang ini sudah sepenuhnya mengkhianati kita, buat apa lagi banyak bicara."
  },
  AvgDialog_18767_Content_51 = {
    Text = "<Big:Bunuh dia!>"
  },
  AvgDialog_18767_Content_6 = {
    Text = "Agrippa menatapmu dengan curiga."
  },
  AvgDialog_18767_Content_7 = {
    Text = [[
Sudahlah, toh tidak ada cara lain.
Apa yang harus kulakukan?]]
  },
  AvgDialog_18767_Content_8 = {
    Text = "Kau berusaha mengingat kondisimu setiap kali memasuki mimpi, lalu perlahan menggenggam tangan Agrippa."
  },
  AvgDialog_18767_Content_9 = {
    Text = "Hei, kau ini, jangan-jangan mau cari kesempatan dalam kesempitan ya?"
  },
  AvgDialog_18768_Content_1 = {
    Text = "Uhuk uhuk…"
  },
  AvgDialog_18768_Content_10 = {
    Text = "Suara terompet rendah sayup-sayup terdengar dari kejauhan, kalian belum lepas dari pengejaran pasukan pemberontak."
  },
  AvgDialog_18768_Content_11 = {
    Text = "Kau dan Agrippa bergandengan tangan, berlari di bawah langit malam yang gelap gulita."
  },
  AvgDialog_18768_Content_12 = {
    Text = "Keluarganya berada tidak jauh dari kalian. Semua orang, didorong oleh rasa takut dan harapan, berlari menuju kejauhan yang tak berujung."
  },
  AvgDialog_18768_Content_13 = {
    Text = "Siapa kamu? Kenapa menyelamatkanku?"
  },
  AvgDialog_18768_Content_14 = {
    Text = "Hmm…… tepatnya, ini demi menyelamatkan diriku sendiri."
  },
  AvgDialog_18768_Content_15 = {
    Text = "Oh…… apa pun alasannya, kamu…… orang baik."
  },
  AvgDialog_18768_Content_16 = {
    Text = "Setelah kita diselamatkan, aku akan memberikan semua uang dan perhiasan yang kusimpan diam-diam selama bertahun-tahun kepadamu."
  },
  AvgDialog_18768_Content_17 = {
    Text = "Kamu tak bisa menahan diri untuk tertawa."
  },
  AvgDialog_18768_Content_18 = {
    Text = "Aku tidak butuh uangmu. Tapi…… kalau kamu ingin membalas budiku, aku punya satu permintaan."
  },
  AvgDialog_18768_Content_19 = {
    Text = "Katakan, aku pasti bisa melakukannya."
  },
  AvgDialog_18768_Content_2 = {
    Text = "Tadi demi persahabatan lama, saudara-saudara tidak berniat membunuhmu."
  },
  AvgDialog_18768_Content_20 = {
    Text = "Sebuah bintang jatuh melintasi langit malam. Sekarang adalah saat yang tepat untuk membuat permohonan."
  },
  AvgDialog_18768_Content_21 = {
    Text = "Permintaanku sederhana. Tetaplah tersenyum, lalu ingat perasaanmu saat ini."
  },
  AvgDialog_18768_Content_22 = {
    Text = "Perasaan saat ini? Hmm…… senang, lega, khawatir? Yang mana yang kamu maksud!"
  },
  AvgDialog_18768_Content_23 = {
    Text = "Terserah hatimu saja. Aku penasaran perasaan itu akan membawaku ke Agrippa yang mana."
  },
  AvgDialog_18768_Content_24 = {Text = "?"},
  AvgDialog_18768_Content_25 = {
    Text = "<SmallShake:Orang ini memang baik, tapi cara bicaranya aneh sekali……>"
  },
  AvgDialog_18768_Content_26 = {
    Text = "Suara terompet akhirnya menghilang, ketenangan malam kembali menyelimuti."
  },
  AvgDialog_18768_Content_27 = {
    Text = "Akhirnya…… selesai."
  },
  AvgDialog_18768_Content_28 = {
    Text = "Gadis itu berlari beberapa langkah ke puncak bukit pasir, mengepalkan kedua tinjunya, dan berteriak ke arah tempat suara terompet menghilang."
  },
  AvgDialog_18768_Content_29 = {
    Text = "Tidak menyangka kan, dasar kalian @2, gue tetap bertahan sampai akhir!"
  },
  AvgDialog_18768_Content_3 = {
    Text = "Karena kau bersikeras membantu mereka, maka jangan salahkan kami kalau tidak sopan lagi——"
  },
  AvgDialog_18768_Content_30 = {
    Text = "Hahahahahaha, @2!"
  },
  AvgDialog_18768_Content_31 = {
    Text = "<Shake:Agrippa! Anggun, anggun……!>"
  },
  AvgDialog_18768_Content_32 = {
    Text = "Tidak dengar!!!"
  },
  AvgDialog_18768_Content_33 = {
    Text = "Persetan dengan sopan santun dan etiket, akhirnya aku bebas!!"
  },
  AvgDialog_18768_Content_34 = {
    Text = "Diiringi deklarasi yang lantang dan tegas, sang gadis merentangkan kedua lengannya, seolah mengangkat langit malam yang megah di atas kepalanya ke dalam genggaman."
  },
  AvgDialog_18768_Content_35 = {
    Text = "<Big:Bebaaaaas——!!>"
  },
  AvgDialog_18768_Content_36 = {
    Text = "BRAAAKK——!!"
  },
  AvgDialog_18768_Content_37 = {Text = "……Eh?"},
  AvgDialog_18768_Content_38 = {
    Text = "Langit menghilang, labirin pun menghilang."
  },
  AvgDialog_18768_Content_39 = {
    Text = "Lembah Sungai Cambrian langsung menghujam pandangan kalian."
  },
  AvgDialog_18768_Content_4 = {Text = "Duaaarr!"},
  AvgDialog_18768_Content_40 = {
    Text = "Air danau yang dalam bagaikan cermin mengalir dengan tenang, angin menyibak permukaan danau, menimbulkan riak-riak bercahaya yang melingkar."
  },
  AvgDialog_18768_Content_41 = {
    Text = "Agrippa terduduk di atas rerumputan, menatap kosong pemandangan di hadapannya."
  },
  AvgDialog_18768_Content_42 = {
    Text = "%player%, kita ini… sudah keluar?"
  },
  AvgDialog_18768_Content_43 = {
    Text = "Selamat datang kembali di dunia nyata, Agrippa."
  },
  AvgDialog_18768_Content_44 = {Text = "……Oh."},
  AvgDialog_18768_Content_45 = {
    Text = "Jadi ini lembah itu. Seratus kali lebih indah dari yang orang-orang katakan, bukan, seribu kali lebih indah."
  },
  AvgDialog_18768_Content_46 = {
    Text = "Cahaya fajar yang lembut menembus kabut tipis dan menyinari kalian."
  },
  AvgDialog_18768_Content_47 = {
    Text = "Agrippa memejamkan matanya, dengan rakus meresapi aroma-aroma yang sudah lama tak dirasakannya."
  },
  AvgDialog_18768_Content_48 = {
    Text = "Aku mencium banyak hal. Tanah, rumput, freesia, dan juga sinar matahari……"
  },
  AvgDialog_18768_Content_49 = {
    Text = "Sinar matahari juga punya aroma?"
  },
  AvgDialog_18768_Content_5 = {
    Text = "Kau memanfaatkan kekacauan untuk mendorong roboh pilar yang melintang di depan, seluruh bangunan mulai goyah."
  },
  AvgDialog_18768_Content_50 = {
    Text = "Mm. Aroma yang membuat orang mengantuk."
  },
  AvgDialog_18768_Content_51 = {
    Text = "Terima kasih, %player%."
  },
  AvgDialog_18768_Content_52 = {
    Text = "Dia meregangkan tubuhnya, lalu pelan-pelan bersenandung sebuah lagu Romawi kuno."
  },
  AvgDialog_18768_Content_53 = {
    Text = "Melodi yang ringan berputar di udara, menyebarkan suasana hati sang pemiliknya yang gembira ke setiap sudut lembah."
  },
  AvgDialog_18768_Content_54 = {
    Text = "Setelah lebih dari seribu tahun berlalu, akhirnya dia kembali melihat sinar matahari."
  },
  AvgDialog_18768_Content_55 = {
    Text = "Dan akhirnya untuk pertama kalinya melihat lembah sungai."
  },
  AvgDialog_18768_Content_6 = {
    Text = "Sekarang saatnya, cepat ikut aku pergi!"
  },
  AvgDialog_18768_Content_7 = {
    Text = "Kau meraih tangan Agrippa dan bersama keluarganya bergegas pergi."
  },
  AvgDialog_18768_Content_8 = {
    Text = "Halaman megah yang dulu berjaya itu, runtuh dengan gemuruh bagai raksasa yang membisu."
  },
  AvgDialog_18768_Content_9 = {
    Text = "16@1 tahun sebelum Banjir Besar, pinggiran Capua"
  },
  AvgDialog_18769_Content_1 = {
    Text = "Penghalang Memori"
  },
  AvgDialog_18769_Content_10 = {
    Text = "Kau@1 bilang apa——"
  },
  AvgDialog_18769_Content_11 = {
    Text = "Sudahlah, jangan berurusan dengan orang itu. Dia memang orang gila……"
  },
  AvgDialog_18769_Content_12 = {
    Text = "Para budak saling mendorong sambil pergi, sel yang gelap akhirnya menjadi sunyi."
  },
  AvgDialog_18769_Content_13 = {
    Text = "Gadis itu menundukkan kepala dan melangkah keluar dari bayangan di sudut sel."
  },
  AvgDialog_18769_Content_14 = {
    Text = "Kenapa tidak pergi bersama mereka? Malam ini adalah kesempatan bagus untuk meraih kebebasanmu kembali."
  },
  AvgDialog_18769_Content_15 = {
    Text = "Aku suka di sini, kenapa harus pergi?"
  },
  AvgDialog_18769_Content_16 = {
    Text = "Suka……? Haha, sungguh luar biasa. Suka dimarahi, atau suka dicambuk olehku?"
  },
  AvgDialog_18769_Content_17 = {
    Text = "Gladiator itu menguap, dengan nyaman meregangkan tubuhnya."
  },
  AvgDialog_18769_Content_18 = {
    Text = "Aku suka darah, dan lebih suka membunuh. Bagiku, membunuh adalah kebebasan."
  },
  AvgDialog_18769_Content_19 = {
    Text = "Soal gelar budak, mau berapa pun aku tak peduli. Kenapa harus pergi?"
  },
  AvgDialog_18769_Content_2 = {
    Text = "16@1 tahun sebelum Diluvium, Capua"
  },
  AvgDialog_18769_Content_21 = {
    Text = "Heh…… Sekarang aku justru mulai memandangmu dengan kagum. Kau benar-benar orang gila sejati."
  },
  AvgDialog_18769_Content_22 = {
    Text = "Agrippa mendongak menatap pintu keluar penjara bawah tanah, wajahnya sangat tenang."
  },
  AvgDialog_18769_Content_23 = {
    Text = "Gelombang api merah darah menyapu langit, tawa, tangisan, jeritan…… berbagai macam suara berkumpul menjadi satu, menggubah simfoni dari neraka."
  },
  AvgDialog_18769_Content_24 = {
    Text = "Sebentar lagi, mereka akan menemukanku, @1ku, lalu memenggal kepalaku, sama seperti yang mereka lakukan pada orang tuaku."
  },
  AvgDialog_18769_Content_25 = {
    Text = "Aku tak sudi orang-orang hina itu mendekatiku. Tapi kau……"
  },
  AvgDialog_18769_Content_26 = {
    Text = [[
Kau berbeda dari mereka.
Aku tahu sebelumnya kita punya sedikit "perselisihan", tapi kali ini, kau pasti tidak akan menolak permintaanku.]]
  },
  AvgDialog_18769_Content_27 = {
    Text = "Oh? Coba katakan."
  },
  AvgDialog_18769_Content_29 = {Text = "Bunuh aku."},
  AvgDialog_18769_Content_3 = {
    Text = "Sialan, perempuan itu menghilang."
  },
  AvgDialog_18769_Content_30 = {
    Text = "<RedBig:Bunuh aku……>"
  },
  AvgDialog_18769_Content_31 = {
    Text = "Agrippa……?"
  },
  AvgDialog_18769_Content_32 = {
    Text = "<RedBig:Bunuh aku bunuh aku bunuh aku bunuh aku bunuh aku bunuh aku bunuh aku bunuh aku……>"
  },
  AvgDialog_18769_Content_33 = {Text = "Agrippa!"},
  AvgDialog_18769_Content_34 = {Text = "!!"},
  AvgDialog_18769_Content_35 = {
    Text = "<Shake:Umm……>"
  },
  AvgDialog_18769_Content_36 = {
    Text = "Aku bermimpi yang sangat panjang……"
  },
  AvgDialog_18769_Content_37 = {
    Text = "Dengar, sepertinya tadi kita melewatkan beberapa pertanyaan."
  },
  AvgDialog_18769_Content_38 = {
    Text = "Omong kosong! Aku ini Penguasa Labirin yang agung, semuanya ada dalam kendaliku——"
  },
  AvgDialog_18769_Content_39 = {
    Text = "Pertama, kenapa keturunanmu bisa keluar masuk labirin dengan bebas, tapi kau dan aku tidak bisa?"
  },
  AvgDialog_18769_Content_4 = {
    Text = "Heh. Sekarang baru tahu bersembunyi? Tunggu sampai kita menemukannya, potong dulu kakinya……"
  },
  AvgDialog_18769_Content_40 = {
    Text = "Bukankah kalian bisa berbagi kesadaran?"
  },
  AvgDialog_18769_Content_41 = {
    Text = "Apa kau tahu? Sebagai penguasa labirin, aku harus selalu menjaga aura misterius."
  },
  AvgDialog_18769_Content_42 = {
    Text = "Lagipula, selama aku mau, mereka semua harus patuh kembali ke sini. Itu mana bisa disebut bebas keluar masuk?"
  },
  AvgDialog_18769_Content_43 = {
    Text = "Kau mengangguk, lalu mengeluarkan buku catatan dari tanganmu."
  },
  AvgDialog_18769_Content_44 = {
    Text = "Masih ada satu pertanyaan lagi."
  },
  AvgDialog_18769_Content_45 = {
    Text = "Aku sudah mencatat semua tempat yang kutemui di dalam labirin — sekolah, museum lilin, jalanan Londinium…"
  },
  AvgDialog_18769_Content_46 = {
    Text = "Tapi tidak ada satu pun tempat yang pernah kau alami. Tidak satu pun."
  },
  AvgDialog_18769_Content_47 = {
    Text = "Kenapa? Bukankah kau juga terjebak di sini?"
  },
  AvgDialog_18769_Content_48 = {
    Text = "Kenapa banyak tanya! Karena Yang Mulia ini tidak mau mengingat-ingat, hal yang tidak menyenangkan buat apa dipikirkan."
  },
  AvgDialog_18769_Content_49 = {
    Text = "Ya, <Yellow:kau tidak mau mengingat>."
  },
  AvgDialog_18769_Content_5 = {
    Text = "Hei, Yuhashi, kau pernah melihat Agrippa?"
  },
  AvgDialog_18769_Content_50 = {
    Text = "Mungkinkah…"
  },
  AvgDialog_18769_Content_51 = {
    Text = "Justru karena kau — sang penguasa labirin — menolak untuk berbagi kesadaran, labirin yang terbentuk dari kesadaran para yang terjebak ini selamanya akan tetap tidak lengkap."
  },
  AvgDialog_18769_Content_52 = {
    Text = "Karena itu kita tidak akan pernah bisa keluar dari sini."
  },
  AvgDialog_18769_Content_54 = {
    Text = "Masalah yang kau sebutkan ini, dulu aku juga pernah memikirkannya. Ini kan labirinku."
  },
  AvgDialog_18769_Content_55 = {
    Text = "Tapi begitu teringat masa lalu, rasanya menyebalkan setengah mati…"
  },
  AvgDialog_18769_Content_56 = {
    Text = "Agrippa memegangi kepalanya, mulutnya dengan cepat mengucapkan kata-kata bagai igauan."
  },
  AvgDialog_18769_Content_57 = {
    Text = "Makhluk-makhluk hina itu… berani-beraninya memperlakukanku seperti itu…"
  },
  AvgDialog_18769_Content_58 = {
    Text = "Mereka cuma sekumpulan budak, bahkan tidak layak disebut manusia, seharusnya diinjak-injak oleh kita turun-temurun."
  },
  AvgDialog_18769_Content_59 = {
    Text = "Memberontak? Sungguh omong kosong."
  },
  AvgDialog_18769_Content_6 = {
    Text = "Gladiator di balik bayangan perlahan membuka matanya."
  },
  AvgDialog_18769_Content_60 = {
    Text = "Tapi mereka tidak hanya melakukannya, mereka bahkan menggantung kepala ayah dan ibuku di tembok kota, menjambak rambutku dan memaksaku melihat dengan saksama, memperhatikan baik-baik, setiap detail tidak boleh terlewat."
  },
  AvgDialog_18769_Content_61 = {
    Text = "Dan adikku, Yulia. Saat aku menemukannya, sekujur tubuhnya@3, dia masih begitu kecil…"
  },
  AvgDialog_18769_Content_62 = {
    Text = "Sungguh konyol…… mengira aku akan menangis?"
  },
  AvgDialog_18769_Content_63 = {
    Text = "Tidak, tidak mungkin. Aku lebih baik mati daripada meneteskan setetes air mata di depan mereka."
  },
  AvgDialog_18769_Content_64 = {
    Text = "Kami adalah keturunan serigala abu-abu, kami akan mati dengan bermartabat layaknya serigala sejati. Anjing-anjing kampung itu tidak akan pernah memahaminya seumur hidup mereka."
  },
  AvgDialog_18769_Content_65 = {
    Text = "Hahahaha……"
  },
  AvgDialog_18769_Content_66 = {
    Text = "Agrippa memegangi perutnya, tertawa sampai air matanya keluar."
  },
  AvgDialog_18769_Content_67 = {
    Text = "Mereka pasti sangat kecewa saat melihat mayatku…… Hahaha……"
  },
  AvgDialog_18769_Content_68 = {
    Text = "Agrippa……? Agrippa!"
  },
  AvgDialog_18769_Content_69 = {
    Text = "Kamu menggenggam erat bahu Agrippa, berusaha menariknya kembali dari mimpi buruk masa lalu."
  },
  AvgDialog_18769_Content_7 = {
    Text = "……Pergi."
  },
  AvgDialog_18769_Content_70 = {
    Text = "Sudah cukup. Semua sudah berlalu."
  },
  AvgDialog_18769_Content_72 = {
    Text = "Maafkan aku, Agrippa. Aku tidak tahu sebelumnya…… Hal-hal yang tidak menyenangkan itu, biarkanlah berlalu."
  },
  AvgDialog_18769_Content_73 = {
    Text = "Kamu adalah Penguasa Labirin yang agung, tidak ada yang bisa benar-benar melukaimu."
  },
  AvgDialog_18769_Content_74 = {Text = "……Mm."},
  AvgDialog_18769_Content_75 = {
    Text = "Agrippa terdiam dengan cara yang jarang terlihat, tampaknya dia belum keluar dari bayang-bayang masa lalu."
  },
  AvgDialog_18769_Content_76 = {
    Text = "<LightGray:Andai saja masa lalu benar-benar bisa diubah…… Dengan begitu bisa membantunya, sekaligus keluar dari kesulitan yang ada sekarang.>"
  },
  AvgDialog_18769_Content_77 = {
    Text = "<LightGray:Tidak, jangan buru-buru putus asa. Pikirkan cara lain lagi……>"
  },
  AvgDialog_18769_Content_78 = {
    Text = "Kamu berusaha keras mencari informasi yang mungkin berguna dari ingatan yang tidak lengkap."
  },
  AvgDialog_18769_Content_79 = {
    Text = "Memasuki mimpi tidak bisa mengubah masa lalu, tapi bisa memengaruhi masa depan. Karena itu selama memasuki mimpi, Penjaga Rahasia harus belajar menahan diri."
  },
  AvgDialog_18769_Content_8 = {
    Text = "Heh, semua saudara berjuang demi tujuan mulia, hanya kau yang masih mau tinggal dan terus jadi anjing."
  },
  AvgDialog_18769_Content_80 = {
    Text = "Memengaruhi masa depan?"
  },
  AvgDialog_18769_Content_81 = {
    Text = "Sebagai perumpamaan, ingatan manusia itu seperti danau yang tenang."
  },
  AvgDialog_18769_Content_82 = {
    Text = "Memasuki mimpi itu ibarat melemparkan sebuah batu kecil ke dalamnya, riak yang ditimbulkan akan segera menghilang."
  },
  AvgDialog_18769_Content_83 = {
    Text = "Tapi batu kerikil itu masih ada."
  },
  AvgDialog_18769_Content_84 = {
    Text = "Benar. Meskipun setelah terbangun, orang yang dimasuki mimpinya tidak mengingat apa pun……"
  },
  AvgDialog_18769_Content_85 = {
    Text = "Batu kerikil itu akan selamanya tenggelam ke alam bawah sadarnya, memengaruhi masa kininya."
  },
  AvgDialog_18769_Content_86 = {Text = "!!!"},
  AvgDialog_18769_Content_87 = {
    Text = "Agrippa, aku tahu cara untuk keluar dari sini."
  },
  AvgDialog_18769_Content_9 = {
    Text = "Sudah kubilang, pergi. Tidak mengerti?"
  },
  AvgDialog_18770_Content_1 = {
    Text = "Kerajaannya"
  },
  AvgDialog_18770_Content_10 = {
    Text = "Percuma, percuma! Dulu yang terjebak di labirin ini, ada juga orang pintar seperti matematikawan, lho!"
  },
  AvgDialog_18770_Content_11 = {
    Text = "Teka-teki yang bahkan mereka tidak bisa pecahkan, kamu jangan buang-buang tenaga lagi."
  },
  AvgDialog_18770_Content_12 = {
    Text = "Kalau menurutku, toh kita berdua tidak bisa saling membunuh, lebih baik kita akur saja seperti ini."
  },
  AvgDialog_18770_Content_13 = {
    Text = "Ayo ngobrol! Main kartu juga boleh. Kamu bisa main kartu apa?"
  },
  AvgDialog_18770_Content_14 = {
    Text = "Jangan lihat aku terus-terusan di bawah tanah, tapi aku sudah belajar teknik bermain kartu yang hebat, tidak ada yang bisa mengalahkanku!"
  },
  AvgDialog_18770_Content_15 = {
    Text = "Kamu harus mengakui, kata-katanya sedikit banyak membuatmu terpukul."
  },
  AvgDialog_18770_Content_16 = {
    Text = "Kalau selama bertahun-tahun tidak ada yang bisa memecahkan labirin ini, lalu apa yang membuatmu yakin bisa?"
  },
  AvgDialog_18770_Content_17 = {
    Text = "Kamu tidak punya otak secerdas Ramona."
  },
  AvgDialog_18770_Content_18 = {
    Text = "Sambil berpikir begitu, kamu menjatuhkan diri ke atas bantal yang empuk."
  },
  AvgDialog_18770_Content_19 = {
    Text = [[
Aku tidak terlalu bisa main kartu, ayo ngobrol saja.
Bagaimana kamu bisa terjebak di labirin ini?]]
  },
  AvgDialog_18770_Content_2 = {
    Text = "39, 40, 41……"
  },
  AvgDialog_18770_Content_20 = {Text = "Eh……"},
  AvgDialog_18770_Content_21 = {
    Text = "Seolah tidak menyangka pertanyaanmu itu, mata-mata majemuk yang terus berputar di dalam rongga mata gadis itu serentak terhenti sesaat."
  },
  AvgDialog_18770_Content_22 = {
    Text = "Kamu sendiri yang bilang, kita harus rukun. Kalau begitu, saling terbuka adalah langkah pertama."
  },
  AvgDialog_18770_Content_23 = {
    Text = "Oke, oke, akan kuceritakan……! Cuma cerita klise biasa kok."
  },
  AvgDialog_18770_Content_24 = {
    Text = "Dulu keluargaku adalah orang terkaya di Kapua, setiap hari budak yang mengikutiku di belakang sampai tak terlihat ujungnya……"
  },
  AvgDialog_18770_Content_25 = {
    Text = "Lalu orang-orang bodoh itu malah memberontak, katanya mau \"pembebasan\" \"kebebasan\", pokoknya hal-hal yang tidak kumengerti."
  },
  AvgDialog_18770_Content_26 = {
    Text = "Aku tidak mau mati di tangan mereka, jadi aku menyuruh seorang gladiator untuk membunuhku."
  },
  AvgDialog_18770_Content_27 = {
    Text = "Agrippa berkata sambil merentangkan tangannya ke arahmu."
  },
  AvgDialog_18770_Content_28 = {
    Text = "……Saat terbangun, aku sudah ada di sini."
  },
  AvgDialog_18770_Content_29 = {
    Text = "Aku pernah mendengar tentang revolusi ini di kelas sejarah. Konon—"
  },
  AvgDialog_18770_Content_3 = {
    Text = "Kamu mencatat dengan cepat <Blue:Asrama Mahasiswa: 41> di buku catatan yang dibawa kakak senior."
  },
  AvgDialog_18770_Content_30 = {
    Text = "Tidak mau dengar. Topik ini membosankan! Ganti ganti."
  },
  AvgDialog_18770_Content_31 = {
    Text = "Satu jam kemudian……"
  },
  AvgDialog_18770_Content_32 = {
    Text = "Percakapan tanpa isi terus berlanjut, sampai akhirnya Agrippa menarik topik kembali ke dirinya sendiri."
  },
  AvgDialog_18770_Content_33 = {
    Text = "Tahu tidak, sekarang keturunan di bawahku sudah ada seribu……"
  },
  AvgDialog_18770_Content_34 = {
    Text = "Mereka bisa keluar masuk labirin dengan bebas, membantu mengumpulkan cerita tentang apa yang terjadi di luar, dan juga membawa kembali orang-orang sial yang cocok menjadi keturunan."
  },
  AvgDialog_18770_Content_35 = {
    Text = "Kalau bukan karena mereka, aku pasti sudah mati kebosanan."
  },
  AvgDialog_18770_Content_36 = {
    Text = "Kamu mendengarkan keluh kesahnya yang tak henti-henti, dan entah mengapa, sebuah gambaran muncul di benakmu—"
  },
  AvgDialog_18770_Content_37 = {
    Text = "Seorang raja tua bertopang pada tongkatnya, terbenam dalam takhta yang lapuk dan berat."
  },
  AvgDialog_18770_Content_38 = {
    Text = "Wilayah kekuasaannya tak berbatas, otoritasnya tak terbantahkan."
  },
  AvgDialog_18770_Content_39 = {
    Text = "Dia mengirim banyak utusan, menyuruh mereka membawa kembali cerita dari negeri jauh: batu mata kucing hijau zamrud, gajah yang tersesat, dan pelangi setelah hujan reda…"
  },
  AvgDialog_18770_Content_4 = {
    Text = "Berhentilah melakukan hal yang sia-sia, ayo temani aku bermain game!"
  },
  AvgDialog_18770_Content_40 = {
    Text = "Saat sampai di bagian yang seru, para utusan akan melambaikan tangan dengan gembira. Namun sang raja selalu diam, bagaikan patung yang ditumbuhi lumut."
  },
  AvgDialog_18770_Content_41 = {
    Text = "Dia tak bisa melakukan apa pun, karena dia sudah lama tak mampu beranjak selangkah pun dari takhtanya."
  },
  AvgDialog_18770_Content_42 = {
    Text = "Agrippa, kamu sudah mendengar begitu banyak cerita dari luar… Adakah tempat yang ingin kamu kunjungi?"
  },
  AvgDialog_18770_Content_43 = {
    Text = "Tempat yang ingin dikunjungi…"
  },
  AvgDialog_18770_Content_44 = {
    Text = "<Blue:Lembah Cambrian> mungkin salah satunya."
  },
  AvgDialog_18770_Content_45 = {
    Text = "Agrippa menjawab hampir tanpa berpikir."
  },
  AvgDialog_18770_Content_46 = {
    Text = "Para keturunanku memberitahuku, pusat labirin ini tampaknya berada di bawah sebuah lembah yang disebut Cambrian."
  },
  AvgDialog_18770_Content_47 = {
    Text = "Kudengar itu tempat yang sangat indah, dengan danau yang seperti cermin."
  },
  AvgDialog_18770_Content_48 = {
    Text = "Setiap musim semi, di mana-mana akan bermekaran bunga yang disebut freesia…"
  },
  AvgDialog_18770_Content_49 = {
    Text = "Agrippa menopang dagu dengan tangan, menatap jauh ke kejauhan."
  },
  AvgDialog_18770_Content_50 = {
    Text = "Di kampung halamanku juga ada danau yang sangat indah, tapi aku tak pernah melihatnya."
  },
  AvgDialog_18770_Content_51 = {
    Text = "Kenapa tidak pergi melihatnya?"
  },
  AvgDialog_18770_Content_52 = {
    Text = "Agrippa melirikmu dengan angkuh, mengangkat dagu mungilnya yang lancip."
  },
  AvgDialog_18770_Content_53 = {
    Text = "Aku ini seorang wanita terhormat Roma dari keluarga terpandang, seorang wanita terhormat tidak boleh berjalan-jalan sembarangan."
  },
  AvgDialog_18770_Content_54 = {
    Text = "Jadi kau bisa memerintah banyak budak, tapi kau sendiri juga tidak sepenuhnya bebas."
  },
  AvgDialog_18770_Content_55 = {
    Text = "Realita terungkap hanya dengan satu kalimatmu, wajah gadis itu langsung murung, seperti terong yang layu terkena embun beku."
  },
  AvgDialog_18770_Content_56 = {
    Text = "Waktu itu, nasibku bahkan lebih buruk dari para budak itu. Apalagi sekarang……"
  },
  AvgDialog_18770_Content_6 = {
    Text = "Maaf, bisakah kamu ganti wajah dulu sebelum bicara denganku?"
  },
  AvgDialog_18770_Content_7 = {
    Text = "Cih, pelit sekali!"
  },
  AvgDialog_18770_Content_8 = {
    Text = "\"William\" memutar matanya, lalu dengan bunyi \"poof\" menghilang ke udara."
  },
  AvgDialog_18770_Content_9 = {
    Text = "Kamu kembali menunduk menatap catatan yang berjejer rapat di hadapanmu, mencoba mencari cara untuk memecahkan labirin ini."
  },
  AvgDialog_18779_Content_1 = {
    Text = "Ini... ini Embrio?"
  },
  AvgDialog_18779_Content_10 = {
    Text = [[
Apakah itu menyerap energi dari Miryam?!
Haruskah kita melakukannya sekali lagi?]]
  },
  AvgDialog_18779_Content_11 = {
    Text = [[
Tidak ada gunanya.
Itu dilindungi oleh "plasenta", dan Kekuatan yang diberikan Miryam setidaknya bisa memperbaiki plasenta tiga kali lagi.]]
  },
  AvgDialog_18779_Content_12 = {
    Text = "Untuk sepenuhnya menghancurkannya, serangan langsung ke inti yang sebenarnya diperlukan."
  },
  AvgDialog_18779_Content_13 = {Text = "Inti?"},
  AvgDialog_18779_Content_14 = {
    Text = "Jantung pucat tertanam di dalam kepompong transparan, dan melalui pantulan cahaya bulan, bayangan \"Dia\"tampak samar-samar di dalam kepompong raksasa itu."
  },
  AvgDialog_18779_Content_15 = {
    Text = "Apakah itu \"palsu\" itu sendiri?"
  },
  AvgDialog_18779_Content_16 = {
    Text = "Ya, tetapi juga bukan."
  },
  AvgDialog_18779_Content_17 = {
    Text = "Apakah itu... Murphy?"
  },
  AvgDialog_18779_Content_18 = {Text = "Benar."},
  AvgDialog_18779_Content_19 = {
    Text = "Miryam mempercepat ritual secara paksa, namun \"Dia\" dilahirkan dari kebohongan dan harapan. Sebelum bintang-bintang mencapai posisi Selaras, keberadaan-Nya tidak akan diakui oleh realitas."
  },
  AvgDialog_18779_Content_2 = {
    Text = "Sepertinya sudah tidak ada gerakan lagi."
  },
  AvgDialog_18779_Content_20 = {
    Text = "Sebelum tercipta, inti tetaplah dia."
  },
  AvgDialog_18779_Content_3 = {
    Text = "Belum selesai"
  },
  AvgDialog_18779_Content_4 = {
    Text = "\"Jantung\" berhenti berdetak, tetapi rintihan rendah yang dibawa oleh angin laut membuatnya tak terabaikan."
  },
  AvgDialog_18779_Content_5 = {
    Text = "Apakah kalian mendengar suara tangis?"
  },
  AvgDialog_18779_Content_6 = {
    Text = "Gelombang laut bergulung, kepompong raksasa tiba-tiba meninggi dengan dukungan Miryam dan muncul dari permukaan laut."
  },
  AvgDialog_18779_Content_7 = {
    Text = "Ya, seperti ini..."
  },
  AvgDialog_18779_Content_8 = {
    Text = "Mengambil dan memberi adalah hak Anda, demi kelahiran Anda, demi menghukum mereka yang tidak beriman ini..."
  },
  AvgDialog_18779_Content_9 = {
    Text = "Suara Miryam semakin lemah, tetapi keberadaan di dalam kepompong raksasa yang sedang tidur semakin nyata."
  },
  AvgDialog_18784_Content_10 = {
    Text = "Sungguh kasihan, hanya karena kehilangan link Silver Core, sudah merosot menjadi seperti ini."
  },
  AvgDialog_18784_Content_11 = {
    Text = "Monster bernanah mengabaikan ejekan Lotan, hanya menerjang maju ke arah musuh dengan raungan."
  },
  AvgDialog_18784_Content_12 = {
    Text = "<Change>Letakkan dia…… kepada…… saya……"
  },
  AvgDialog_18784_Content_13 = {
    Text = "Asalkan bisa menangkap gadis itu... asalkan bisa menjadi Kembar Suci bersamanya..."
  },
  AvgDialog_18784_Content_14 = {
    Text = "Dia tidak akan ditinggalkan, tak perlu meratapi asal-usulnya, dan takkan menjadi pion yang diperintah seenaknya."
  },
  AvgDialog_18784_Content_17 = {
    Text = "<Change>Serahkan… dia… padaku!"
  },
  AvgDialog_18784_Content_18 = {
    Text = "Bahkan kemampuan berkomunikasi pun sudah hilang?"
  },
  AvgDialog_18784_Content_19 = {
    Text = [[
Jika demikian, percayakan kata-kata dan perasaanmu kepada pedangmu. 
 Biarkan aku mendengar kemarahanmu!]]
  },
  AvgDialog_18784_Content_2 = {
    Text = "<BigShake:Raung——>"
  },
  AvgDialog_18784_Content_3 = {
    Text = "Tidak lama setelah kalian berjalan dalam kegelapan, seekor monster lengket merayap keluar dari bawah jembatan. Tubuh besarnya menyeret tak terhitung bola-bola lengket dan tiba-tiba jatuh tepat di depan kalian."
  },
  AvgDialog_18784_Content_4 = {
    Text = "Monster itu mengangkat tubuh bagian atasnya yang masih samar-samar berbentuk manusia, memandang kalian satu putaran, lalu pandangannya tertuju pada Lily. Ekspresinya secara bertahap menjadi kegilaan."
  },
  AvgDialog_18784_Content_6 = {
    Text = "Serahkan dia…… kepadaku!"
  },
  AvgDialog_18784_Content_7 = {
    Text = "Lotan melangkah maju untuk menghalangi kalian, dengan gagah menatap monster itu."
  },
  AvgDialog_18784_Content_8 = {
    Text = "Borgol terpecah menjadi empat bagian, anggota tubuh membengkak dan berubah bentuk. Hanya wajah kotor di bawah rambut panjang yang kusut seperti rerumputan yang masih membuktikan identitas pemilik tubuh tersebut."
  },
  AvgDialog_18784_Content_9 = {
    Text = "Kamu adalah... Helot..."
  },
  AvgDialog_18785_Content_1 = {
    Text = "Realitas yang terdistorsi"
  },
  AvgDialog_18785_Content_10 = {
    Text = "Dengan bantuan cahaya, dia melihat bahwa di atas permukaan yang halus dari \"ibunya\", tersebar luka-luka hitam yang tak terhitung jumlahnya, besar dan kecil."
  },
  AvgDialog_18785_Content_11 = {
    Text = "\"Maafkan aku...\""
  },
  AvgDialog_18785_Content_12 = {
    Text = "Lumpur hitam bergelombang, menghancurkan ketenangan di dasar pantai."
  },
  AvgDialog_18785_Content_13 = {
    Text = "\"Ibu\"mengeluarkan suara merdu yang menyayat hati, tentakel-tentakelnya bergerak cepat, memasukkan sesuatu ke dalam rongga dada burung muda."
  },
  AvgDialog_18785_Content_14 = {
    Text = "Jalinan-jalinan lunak yang licin dan dingin melilitnya, air kolam hitam tidak lagi menyumbat mulut dan hidungnya, melainkan seperti cairan ketuban, menopang hidupnya."
  },
  AvgDialog_18785_Content_15 = {
    Text = "<Change>\"Maafkan aku……\"\n\"Aku……belum ingin mati……\""
  },
  AvgDialog_18785_Content_16 = {
    Text = "Permukaan air tetap tenang untuk waktu yang lama, bahkan angin yang menderu dari kutub tidak mampu membuat riak pada kolam yang kental."
  },
  AvgDialog_18785_Content_17 = {
    Text = "Miryam-sama, apakah Saintess sudah..."
  },
  AvgDialog_18785_Content_18 = {
    Text = "Dia lahir pada saat bintang Selaras sebelumnya, dan dia adalah anak yang \"dapat melihat\"."
  },
  AvgDialog_18785_Content_19 = {
    Text = "Di dunia ini, tidak ada seorang pun yang lebih layak mendapatkan pengakuan dari darah dewa selain dia."
  },
  AvgDialog_18785_Content_2 = {
    Text = "Burung muda yang sayapnya patah jatuh ke dalam kolam air hitam."
  },
  AvgDialog_18785_Content_20 = {
    Text = [[
Wanita yang kurus itu dikelilingi oleh kerumunan, berdiri di tempat tertinggi yang bisa menatap rendah semua orang. 
 Kain tipis mengaburkan wajahnya, bahkan pelayan dekatnya pun tak mampu membaca apa yang ada di pikiran tuannya.]]
  },
  AvgDialog_18785_Content_21 = {Text = "Murphy…"},
  AvgDialog_18785_Content_3 = {
    Text = "Doa sang pemimpin ritual terdengar samar namun tegas, kata-katanya yang penuh semangat menembus cairan hitam kental, berubah menjadi belati yang membelah rongga dada burung muda."
  },
  AvgDialog_18785_Content_4 = {
    Text = "Cairan berwarna merah segar muncul di atas dada, mekar dengan memesona di permukaan air hitam yang tenang——"
  },
  AvgDialog_18785_Content_5 = {
    Text = "Namun, dia terus tenggelam, akar yang berlumuran darah membawanya ke dalam kedalaman terdalam, ke dalam pelukan yang lembut namun dingin."
  },
  AvgDialog_18785_Content_8 = {
    Text = [[
Dia melihatnya. 
Dia menengadah, "Ibu" menurunkan tiga pasang tangkai mata, saling bertatapan dengannya.]]
  },
  AvgDialog_18785_Content_9 = {
    Text = "Itu adalah sebuah benda raksasa berwarna merah tua, bagian yang terkena darah menjadi transparan putih. \"Ibu\"memancarkan cahaya redup, untuk sementara menerangi sepetak kecil dunia."
  },
  AvgDialog_18786_Content_1 = {
    Text = "Video fade in"
  },
  AvgDialog_18786_Content_2 = {
    Text = "Video loop 1"
  },
  AvgDialog_18786_Content_3 = {
    Text = "Video loop 2"
  },
  AvgDialog_18786_Content_4 = {
    Text = "Video fade out"
  },
  AvgDialog_18786_Content_5 = {
    Text = "Tidak ada lagi"
  },
  AvgDialog_18787_Content_1 = {
    Text = "Tapi sekarang ada hal yang lebih mendesak."
  },
  AvgDialog_18787_Content_10 = {
    Text = "Inilah gadis yang sedang Herbert lacak. Mungkin ada petunjuk terkait penyelidikan kalian pada dirinya."
  },
  AvgDialog_18787_Content_11 = {
    Text = [[
Ayo pergi, apa yang kalian tunggu? 
 Apakah kalian benar-benar suka tinggal di luar dan berteriak seperti serigala sepanjang malam?]]
  },
  AvgDialog_18787_Content_12 = {
    Text = "Jika kamu ingin makan angin dan tidur di bawah langit, aku selalu siap menemani. Namun, aku khawatir kamu, seorang gadis yang lemah lembut, tidak akan tahan."
  },
  AvgDialog_18787_Content_13 = {
    Text = "Lotan menepuk bahu Ramona dari belakang. Ramona menunjukkan ekspresi seperti orang yang baru saja memakan seekor lalat, tetapi dia tidak mengatakan apa-apa."
  },
  AvgDialog_18787_Content_14 = {
    Text = "Wanita narsis… terdengar seperti orang kaya yang berbaik hati, kan?"
  },
  AvgDialog_18787_Content_2 = {Text = "?"},
  AvgDialog_18787_Content_3 = {
    Text = "Jika kamu tidak berniat menggunakan salju sebagai selimut, sebaiknya pikirkan dengan matang di mana kita akan bermalam, Penjaga."
  },
  AvgDialog_18787_Content_4 = {
    Text = "<Italic:Kakak laki-laki, kakak perempuan, apakah kalian datang dari tempat yang sangat jauh?>"
  },
  AvgDialog_18787_Content_5 = {
    Text = "Suara yang masih terdengar polos memutus pembicaraan kalian."
  },
  AvgDialog_18787_Content_6 = {Text = "Siapa itu?"},
  AvgDialog_18787_Content_7 = {
    Text = "Salju yang menumpuk di dinding memantulkan cahaya bulan yang terang. Di tengahnya berdiri seorang gadis yang lebih putih daripada cahaya bulan itu sendiri."
  },
  AvgDialog_18787_Content_8 = {
    Text = [[
Jika tidak menemukan tempat tinggal, kamu bisa sementara tinggal di kamar <Blue:Wanita narsis>. 
 Tepat di depan di tikungan.]]
  },
  AvgDialog_18787_Content_9 = {
    Text = "Kamu memberi isyarat mata kepada Ramona, dan Ramona membalas dengan tatapan yang mengiyakan."
  },
  AvgDialog_18790_Content_1 = {
    Text = "Kalian semua berhasil menembus jalan dan mencapai haluan kapal. Belum sempat melihat ke arah laut, hantaman dari bawah muncul lagi, membuat kapal itu miring beberapa derajat."
  },
  AvgDialog_18790_Content_2 = {
    Text = "Kapal kargo naik turun mengikuti gelombang laut yang bergelora, sesuatu pun muncul dari dalam air ——"
  },
  AvgDialog_18790_Content_3 = {Text = "Murphy!"},
  AvgDialog_18790_Content_4 = {
    Text = "Kepala ular erat melilit tubuh gadis itu, Miryam hanya bisa berdoa dengan suara yang serak dan tidak jelas."
  },
  AvgDialog_18790_Content_5 = {
    Text = "Ph'nglui mglw'nafh @3..."
  },
  AvgDialog_18790_Content_6 = {
    Text = "Dia mengangkat Murphy ke dalam cahaya bulan. Sepasang demi sepasang tangan kecil dan hitam yang lembut muncul dari rongga dada gadis itu, bergerak dan menenun, lapis demi lapis membungkus tubuh gadis itu, membentuk sebuah kepompong raksasa berwarna hitam."
  },
  AvgDialog_18790_Content_7 = {
    Text = "Dalam dengusan rendah yang teredam, tangan dan benang hitam menjadikan Miryam sebagai penopang, membuat jalinan erat membungkus tubuh ular raksasa itu."
  },
  AvgDialog_18790_Content_8 = {
    Text = "Kulit kepompong menjadi transparan akibat pembengkakan, tak terhitung banyaknya tangan saling bertautan membentuk singgasana, mengangkat tinggi-tinggi sebuah jantung pucat."
  },
  AvgDialog_18790_Content_9 = {
    Text = "Ph'nglui mglw'nafh @1'@2 wgah'nagl fhtagn!"
  },
  AvgDialog_18792_Content_1 = {
    Text = "Dia hanyalah seorang anak dari kawasan kumuh, tidak tahu apa-apa, tidak akan menjadi ancaman bagi kalian sama sekali……"
  },
  AvgDialog_18792_Content_10 = {
    Text = "Benar-benar menyebalkan, tangan saya sudah pegal. Apakah kamu berniat mati di sini hari ini, 24?"
  },
  AvgDialog_18792_Content_11 = {
    Text = "Kehilangan budak yang begitu penurut seperti dirimu, aku juga akan menangis, loh~"
  },
  AvgDialog_18792_Content_12 = {
    Text = "Maaf… Aku tidak akan meninggalkan tempat ini sedikit pun."
  },
  AvgDialog_18792_Content_14 = {
    Text = "Pletak——!"
  },
  AvgDialog_18792_Content_15 = {
    Text = "Segera, seluruh tubuh 24 penuh dengan luka Caro. Namun, dia tidak bergerak sama sekali, hanya menggumamkan kata-kata yang sama."
  },
  AvgDialog_18792_Content_16 = {
    Text = "<Shake:Bi-biarkan dia pergi……>"
  },
  AvgDialog_18792_Content_17 = {
    Text = "<Shake:Biarkan dia pergi……>"
  },
  AvgDialog_18792_Content_18 = {
    Text = "Ayo, kalau punya nyali, serang aku! Sekelompok sampah! Jangan..."
  },
  AvgDialog_18792_Content_19 = {
    Text = "<Bold:Jangan pukul kakakku…>"
  },
  AvgDialog_18792_Content_2 = {
    Text = "Pletak——!"
  },
  AvgDialog_18792_Content_20 = {
    Text = "Nona 24! Berhenti… uh…"
  },
  AvgDialog_18792_Content_21 = {
    Text = "<Small:Tidak bisa... sama sekali tidak bisa bergerak. Cari cara untuk mengeluarkan kunci perak...>"
  },
  AvgDialog_18792_Content_22 = {
    Text = "Bodoh sekali, bodoh sekali! Kalau begitu, jangan salahkan aku karena kejam, ya~"
  },
  AvgDialog_18792_Content_23 = {
    Text = "Leigh, saatnya kamu menunjukkan kemampuanmu."
  },
  AvgDialog_18792_Content_3 = {
    Text = "Cemeti tanpa ampun mendarat, dan dalam sekejap muncul bekas merah yang mengerikan di wajah 24."
  },
  AvgDialog_18792_Content_4 = {Text = "Ugh——!"},
  AvgDialog_18792_Content_5 = {
    Text = "24 berdiri di depan Jenkin, tulang belikatnya yang kurus bergetar seperti sayap kupu-kupu."
  },
  AvgDialog_18792_Content_6 = {
    Text = "Dia mencoba memaksakan senyum, namun justru terlihat lebih menyedihkan daripada menangis."
  },
  AvgDialog_18792_Content_7 = {
    Text = "Tuan, kasihanilah... Biarkan dia pergi, aku bersedia melakukan apa saja..."
  },
  AvgDialog_18792_Content_8 = {
    Text = "Pletak——!"
  },
  AvgDialog_18792_Content_9 = {
    Text = "Tak terhitung cambukan jatuh seperti hujan."
  },
  AvgDialog_18795_Content_1 = {
    Text = "Ujung pedang tipis menembus tubuh energi berbentuk sisik ular, menusuk bagian vital ular raksasa."
  },
  AvgDialog_18795_Content_10 = {
    Text = "Yang… Tuan-ku… Murphy… Murphy…"
  },
  AvgDialog_18795_Content_12 = {
    Text = "Sekarang… masih ada ruang untuk bernegosiasi. \nKembali ke ordo, kau tetap menjadi \"Ibu Dewa\" yang terhormat."
  },
  AvgDialog_18795_Content_13 = {
    Text = "Pemakamanmu akan menjadi perayaan pengorbanan terbesar dalam sejarah Ranah Dewa, dihormati oleh puluhan ribu orang… Nama mu juga akan tercatat dalam sejarah, dikenang selama-lamanya."
  },
  AvgDialog_18795_Content_14 = {
    Text = "Kembali padaku, kita bersama-sama... bersama-sama menjatuhkan hukuman pada <Blue:orang yang tidak hormat ini>."
  },
  AvgDialog_18795_Content_15 = {
    Text = "Eksekusi… orang kotor yang menyamar sebagai Tuan!"
  },
  AvgDialog_18795_Content_16 = {
    Text = "Ular raksasa menghilang lalu terkumpul kembali. Di bawah dampak Kekuatan Miryam, ruang secara bertahap menjadi terdistorsi dan berubah."
  },
  AvgDialog_18795_Content_17 = {
    Text = "Miryam! Aku memerintahkanmu untuk berhenti!"
  },
  AvgDialog_18795_Content_18 = {
    Text = "Palsu, tiruan, penipu, orang yang tidak hormat… Tidak ada @1 @2 yang diizinkan menggunakan bentuk @3 @4!"
  },
  AvgDialog_18795_Content_19 = {
    Text = [[
Pada suatu saat, bayangan semu yang menutupi Ruang Kekuatan mengental menjadi entitas fisik. 
Bangunan dengan bentuk yang sulit digambarkan menjulang tinggi.]]
  },
  AvgDialog_18795_Content_2 = {
    Text = "Eh eh! Orang akan jatuh!"
  },
  AvgDialog_18795_Content_20 = {
    Text = "<Change>Orang yang tidak hormat... orang yang tidak hormat... tidak hormat, tidak terkendali▼▼▼▼▼▼▼▼!"
  },
  AvgDialog_18795_Content_21 = {
    Text = "Suara kasar yang tidak beraturan keluar dari mulutnya. Miryam mencengkeram lehernya dengan kedua tangan, tubuhnya berubah bentuk dan memanjang."
  },
  AvgDialog_18795_Content_22 = {
    Text = "Hati-hati! Dia akan kehilangan kendali!"
  },
  AvgDialog_18795_Content_3 = {
    Text = "Kamu juga jatuh dalam teriakan dahsyat Ular Raksasa."
  },
  AvgDialog_18795_Content_4 = {
    Text = "—— lalu jatuh ke dalam pelukan hangat yang gemetar."
  },
  AvgDialog_18795_Content_5 = {
    Text = "...%player%."
  },
  AvgDialog_18795_Content_6 = {
    Text = "Apakah aku berada di surga?"
  },
  AvgDialog_18795_Content_7 = {
    Text = "Maaf, kami masih berada di Sonnelier. Dan, krisis sudah hampir tiba…"
  },
  AvgDialog_18795_Content_8 = {
    Text = "<Small:Benar-benar tak termaafkan…>"
  },
  AvgDialog_18795_Content_9 = {
    Text = "Hati-hati! Miryam bergerak aneh!"
  },
  AvgDialog_18796_Content_1 = {
    Text = "Hai semuanya! Hari ini kita akan menguji efek transisi Z1~"
  },
  AvgDialog_18796_Content_10 = {
    Text = "Cocok untuk beralih dengan cepat ke adegan yang lebih gelap, lho."
  },
  AvgDialog_18796_Content_11 = {
    Text = "Hu... capek sekali, tidak perlu aku jelaskan lagi kan. Setelah nomor 4, tentu saja langsung ke transisi nomor 5!"
  },
  AvgDialog_18796_Content_12 = {
    Text = "Hmm… intinya, No. 5 adalah transisi yang sering digunakan dan cocok untuk banyak situasi, ya."
  },
  AvgDialog_18796_Content_13 = {
    Text = "Baiklah, selanjutnya adalah transisi terakhir——Mari sambut nomor 6!"
  },
  AvgDialog_18796_Content_14 = {
    Text = "Ini adalah transisi terpanjang, loh~"
  },
  AvgDialog_18796_Content_15 = {
    Text = "Itu dia semua efek transisi, apakah kalian sudah memahaminya?"
  },
  AvgDialog_18796_Content_16 = {
    Text = "Sampai jumpa lagi di episode berikutnya ♡"
  },
  AvgDialog_18796_Content_2 = {
    Text = "Selanjutnya, mari kita sambut transisi nomor 1 —— transisi kiri dan kanan~!"
  },
  AvgDialog_18796_Content_3 = {
    Text = "Cang cang cang! Bagaimana, apakah terlihat sangat megah!"
  },
  AvgDialog_18796_Content_4 = {
    Text = "Transisi ini biasanya digunakan untuk beralih di antara adegan yang sama, lho."
  },
  AvgDialog_18796_Content_5 = {
    Text = "Selanjutnya adalah transisi ke adegan nomor 2——"
  },
  AvgDialog_18796_Content_6 = {
    Text = "Transisi ini biasanya digunakan untuk beralih ke adegan yang lebih terang, lho."
  },
  AvgDialog_18796_Content_7 = {
    Text = "Lalu... transisi ke adegan 3!"
  },
  AvgDialog_18796_Content_8 = {
    Text = "Transisi No. 3 juga cocok digunakan untuk beralih ke adegan yang lebih terang, meskipun ritmenya akan sedikit lebih lambat, hehe."
  },
  AvgDialog_18796_Content_9 = {
    Text = "Berikutnya yang mendekati kita adalah——Transisi 4!"
  },
  AvgDialog_18797_Content_1 = {
    Text = "Mi…@1…uh…"
  },
  AvgDialog_18797_Content_10 = {
    Text = "Bukankah kamu \"Raja Dewa\"!"
  },
  AvgDialog_18797_Content_11 = {
    Text = "Pada akhirnya, sebagai orang yang dilayani oleh Miryam, bukankah ramalan tentang kebangkitan kembali Dewa itu diturunkan olehmu?"
  },
  AvgDialog_18797_Content_12 = {Text = "Kau……"},
  AvgDialog_18797_Content_13 = {
    Text = "Aku baru saja melihatnya... Melalui tautan, aku melihat memori-mu."
  },
  AvgDialog_18797_Content_14 = {Text = "...ya."},
  AvgDialog_18797_Content_15 = {
    Text = "Ini adalah ramalan yang diturunkan oleh Yu, tetapi yang disebut \"wahyu ilahi\" tidak ada."
  },
  AvgDialog_18797_Content_16 = {Text = "Apa?"},
  AvgDialog_18797_Content_17 = {
    Text = [[
Jauh sebelum banjir itu datang, Yu telah kehilangan kemampuan untuk melihat masa depan dari mimpi Dewa.
Yu tidak tahu ke mana Dia pergi. Mungkin Dia telah bangun, atau mungkin Dia telah pergi.]]
  },
  AvgDialog_18797_Content_18 = {
    Text = "Lalu ramalanmu..."
  },
  AvgDialog_18797_Content_19 = {
    Text = "Miryam adalah seorang penganut yang taat. Dia dilahirkan untuk Ranah Dewa dan digerakkan oleh kehendak Yu."
  },
  AvgDialog_18797_Content_2 = {
    Text = "Murphy mengeluarkan erangan kesakitan, gumamannya terdengar kacau dan tak teratur."
  },
  AvgDialog_18797_Content_20 = {
    Text = "Yu hanya berharap kata-kata itu bisa menenangkan ketakutannya sebelum kematiannya, tidak pernah menyangka dia akan menganggapnya sebagai prinsip utama dan memiliki niat membangun kembali ranah dewa."
  },
  AvgDialog_18797_Content_21 = {
    Text = "Semua ini ..."
  },
  AvgDialog_18797_Content_22 = {
    Text = "Ya, semua ini adalah kesalahanku."
  },
  AvgDialog_18797_Content_23 = {
    Text = "Hitung Mundur 60 Menit"
  },
  AvgDialog_18797_Content_3 = {
    Text = "! Apa ini?!"
  },
  AvgDialog_18797_Content_4 = {
    Text = "Jejak berwarna hijau kehitaman yang mengerikan muncul di wajah Murphy, menancap dalam ke kulitnya seperti sistem akar tanaman."
  },
  AvgDialog_18797_Content_5 = {
    Text = "Dia mulai memblokir aliran darah inang."
  },
  AvgDialog_18797_Content_6 = {
    Text = "Bukankah sudah dikatakan bahwa menjauh dari benda langit sudah cukup?"
  },
  AvgDialog_18797_Content_7 = {
    Text = "Maksud Yu adalah, mungkin dia bisa merasa tidak terlalu tersiksa."
  },
  AvgDialog_18797_Content_8 = {
    Text = "Benda langit telah memasuki orbit, sudah tidak ada ruang untuk kembali."
  },
  AvgDialog_18797_Content_9 = {
    Text = "Apakah benar-benar tidak ada cara lain?"
  },
  AvgDialog_18798_Content_1 = {
    Text = "Hah… hah… Tidak terlihat di atas, juga tidak di bawah…"
  },
  AvgDialog_18798_Content_10 = {
    Text = "Murphy langsung kehilangan tenaga, bersandar di pagar kapal lalu meluncur ke dek. Ia tak lagi memedulikan apakah sikap duduknya masih anggun atau tidak."
  },
  AvgDialog_18798_Content_11 = {
    Text = "Dia ingin menemukan titik tumpu agar tidak jatuh. Setelah meraba-raba sejenak, dia akhirnya bersandar di pundakmu."
  },
  AvgDialog_18798_Content_12 = {
    Text = "Sebentar saja..."
  },
  AvgDialog_18798_Content_13 = {
    Text = [[
Tak beberapa detik kemudian, terdengar napas cepat namun teratur di samping telinga. 
 Murphy kembali kehilangan kesadaran.]]
  },
  AvgDialog_18798_Content_14 = {
    Text = "Dia semakin merasakan kelemahan…"
  },
  AvgDialog_18798_Content_15 = {
    Text = "Dewa yang kuhubungkan datang dari ribuan bintang. Meskipun itu adalah tiruan, manusia tetap tidak mampu menahannya."
  },
  AvgDialog_18798_Content_16 = {
    Text = "Apakah tidak ada cara untuk meredakannya?"
  },
  AvgDialog_18798_Content_17 = {
    Text = "...Bawa dia ke bawah."
  },
  AvgDialog_18798_Content_18 = {
    Text = "Jauh dari benda langit, mungkin dia akan merasa lebih nyaman."
  },
  AvgDialog_18798_Content_2 = {
    Text = "Mereka… hu... di mana mereka?"
  },
  AvgDialog_18798_Content_3 = {
    Text = "<Small:Sangat benci... kapal ini kok sebesar ini...>"
  },
  AvgDialog_18798_Content_4 = {Text = "Apa kabar?"},
  AvgDialog_18798_Content_5 = {
    Text = "Aku baik-baik saja! Huh, huh…"
  },
  AvgDialog_18798_Content_6 = {
    Text = "Murphy menaikkan suaranya untuk menjawabmu, tapi tanpa sengaja tersedak dan mulai batuk hebat."
  },
  AvgDialog_18798_Content_7 = {
    Text = "Tapi aku sangat lelah, dan kepala saya sedikit sakit."
  },
  AvgDialog_18798_Content_8 = {
    Text = "Saat berbicara, kamu sudah duduk di sana."
  },
  AvgDialog_18798_Content_9 = {
    Text = "Nah, kalau begitu, istirahat sebentar... hanya sebentar saja..."
  },
  AvgDialog_18802_Content_1 = {
    Text = [[
Jika aku lebih kuat, jika aku bisa terus melawan dia... 
 Namun, aku tidak bisa, aku tidak bisa...]]
  },
  AvgDialog_18802_Content_10 = {
    Text = "Maaf... maaf... semua ini... semuanya salahku..."
  },
  AvgDialog_18802_Content_11 = {
    Text = "Saya adalah monster yang tak berguna. Saya telah membunuh begitu banyak orang, dan saya bahkan tidak bisa menyelamatkan kakak perempuan Jenkin."
  },
  AvgDialog_18802_Content_12 = {
    Text = [[
Dia dibawa pergi, dia dibawa pergi, tapi aku bahkan tidak tahu ke mana dia pergi...
Aku sama sekali tidak tahu siapa yang mengendalikan kita...]]
  },
  AvgDialog_18802_Content_13 = {
    Text = "Ramona berlutut di depan Aigis, dengan lembut memeluk gadis itu dalam pelukannya."
  },
  AvgDialog_18802_Content_14 = {
    Text = "Kamu sudah berusaha keras, Aigis. Itu bukan salahmu."
  },
  AvgDialog_18802_Content_15 = {
    Text = [[
Itu adalah kesalahan Pembunuh Berantai yang sebenarnya, Pembunuh Berantai yang memanipulasi kalian dan melakukan kejahatan ini. 
 Bukan salahmu.]]
  },
  AvgDialog_18802_Content_16 = {
    Text = "Gadis itu langsung menangis tersedu-sedu di pelukan Ramona, namun tangan kanannya terus menutupi matanya."
  },
  AvgDialog_18802_Content_17 = {
    Text = "Kami akan menemukan orang itu."
  },
  AvgDialog_18802_Content_18 = {
    Text = [[
Kita akan menemukannya, lalu membuatnya membayar. 
Aku bersumpah padamu.]]
  },
  AvgDialog_18802_Content_19 = {
    Text = "Terima kasih, terima kasih kalian. Terima kasih."
  },
  AvgDialog_18802_Content_2 = {
    Text = "Terakhir kali saya melawannya, malah... malah... Saya tidak bisa, hiks hiks hiks..."
  },
  AvgDialog_18802_Content_20 = {
    Text = "Sisa keemasan matahari terbenam menembus permukaan jam raksasa yang transparan di menara jam, dan jatuh ke tubuh gadis itu."
  },
  AvgDialog_18802_Content_21 = {
    Text = "Aigis memutar tubuhnya ke samping, meletakkan satu tangan di atas kaca, dan menyipitkan mata sambil menghadap sinar matahari yang hangat."
  },
  AvgDialog_18802_Content_22 = {
    Text = "Hari ini, bisa melihat matahari, ya…"
  },
  AvgDialog_18802_Content_24 = {
    Text = "Seperti mendapatkan semangat dari hari cerah yang langka, dia menopang tubuhnya dan berjalan dengan goyah menuju sepotong kaca yang lebih bersih."
  },
  AvgDialog_18802_Content_25 = {
    Text = "Pandangan yang buram akhirnya menjadi jelas. Dia menatap jalan-jalan yang tampak akrab atau asing, dan dalam keadaan bingung, seolah-olah terdengar bisikan seseorang di telinganya."
  },
  AvgDialog_18802_Content_26 = {
    Text = "Lihat, suara itu berkata, \"Malam ini pasti bisa melihat langit penuh bintang yang cemerlang.\""
  },
  AvgDialog_18802_Content_28 = {
    Text = "Gadis itu menundukkan kepalanya, memperlihatkan senyuman penuh kerinduan."
  },
  AvgDialog_18802_Content_29 = {
    Text = "Dulu, setiap kali bisa melihat matahari, Tiyouge akan diam-diam membawa saya ke sini pada malam hari."
  },
  AvgDialog_18802_Content_3 = {
    Text = "Jangan seperti ini lagi, jangan paksa aku melakukan hal semacam ini lagi."
  },
  AvgDialog_18802_Content_30 = {
    Text = "Nyonya Sarah tidak pernah mengizinkan kami datang ke sini. Dia berkata bahwa tempat ini terlalu berbahaya dan kami bisa dengan mudah terluka. Namun, Tiug sama sekali tidak peduli dengan hal itu."
  },
  AvgDialog_18802_Content_31 = {
    Text = "Matanya sangat tajam. Tak peduli seberapa gelap tempatnya, dia selalu bisa melihat jalan dengan jelas."
  },
  AvgDialog_18802_Content_32 = {
    Text = "Dia sama seperti Jenkin, cerdik dan berani, selalu mengetahui jalan-jalan kecil dan mekanisme yang tidak diketahui oleh orang lain."
  },
  AvgDialog_18802_Content_33 = {
    Text = "Selama dia yang membawa, kita tidak akan ditemukan oleh Nona Sarah."
  },
  AvgDialog_18802_Content_34 = {
    Text = "Selama dia membawa, tempat ini akan selalu menjadi basis rahasia kita."
  },
  AvgDialog_18802_Content_35 = {
    Text = [[
Dia memberitahuku bahwa aku harus lebih sering berinteraksi dengan bintang-bintang agar kekuatan sihirku semakin kuat. 
 Meskipun di sini kita tidak bisa melihat satu bintang pun.]]
  },
  AvgDialog_18802_Content_36 = {
    Text = [[
Pada saat itu, dia adalah satu-satunya orang yang percaya padaku. 
 Dia percaya bahwa aku bisa melihat hal-hal hitam itu dan mengatakan bahwa itu adalah bakat seorang penyihir.]]
  },
  AvgDialog_18802_Content_37 = {
    Text = "Kemudian dia… Setelah itu, para dokter mulai membawa pasien keluar dan tidak lagi melakukan pemeriksaan di workhouse. Saya juga tidak bisa mengumpulkan bukti, tidak bisa membalas dendam untuk Tiyouge."
  },
  AvgDialog_18802_Content_38 = {
    Text = "Jika aku secerdas dia, seberani Jenkin, mungkin aku sudah bisa mengungkap kebenarannya."
  },
  AvgDialog_18802_Content_39 = {
    Text = "Tapi aku bukan penyihir."
  },
  AvgDialog_18802_Content_4 = {
    Text = "Saya tidak ingin memberikan kerusakan kepada orang lain, saya tidak ingin membunuh."
  },
  AvgDialog_18802_Content_40 = {
    Text = "Saya hanyalah seorang pengecut."
  },
  AvgDialog_18802_Content_41 = {
    Text = "Sebuah monster."
  },
  AvgDialog_18802_Content_42 = {
    Text = "Seorang... pembunuh."
  },
  AvgDialog_18802_Content_43 = {
    Text = [[
Apakah kalian tahu berapa kali aku telah dikendalikan oleh orang lain?
Apakah kalian tahu berapa banyak darah yang telah mengotori tanganku?]]
  },
  AvgDialog_18802_Content_44 = {
    Text = "Aku sangat takut, takut akan apa yang akan aku menjadi."
  },
  AvgDialog_18802_Content_46 = {
    Text = "Dulu mata saya sangat sakit, tubuh saya juga sangat sakit. Tapi sekarang saya tidak merasakan apa-apa, seolah-olah saya juga terbuat dari batu."
  },
  AvgDialog_18802_Content_48 = {
    Text = "Sialan, ke mana mereka semua pergi…"
  },
  AvgDialog_18802_Content_49 = {
    Text = "Itu adalah..."
  },
  AvgDialog_18802_Content_5 = {
    Text = "<Shake:<AvgNormalFont:Tidak! Jangan! \nJangan biarkan Xiao Mai melakukan ini, dia masih kecil, bagaimana mungkin dia bisa……<Shake:Tolong……>>>"
  },
  AvgDialog_18802_Content_50 = {
    Text = "Aigis?! Aigis—!"
  },
  AvgDialog_18802_Content_51 = {
    Text = "Dari bawah menara lonceng tiba-tiba terdengar suara Jenkin. Entah sejak kapan dia sudah muncul di halaman."
  },
  AvgDialog_18802_Content_52 = {
    Text = "Dia berteriak dengan cemas memanggil nama Aigis, lalu membentangkan kedua tangannya ke arah langit."
  },
  AvgDialog_18802_Content_53 = {
    Text = "Tubuh kecil gadis itu menghilang selamanya dari langit malam ini saat sedang jatuh."
  },
  AvgDialog_18802_Content_54 = {
    Text = "Seekor burung terbang melintasi langit malam, hilang dalam kabut tebal, tanpa meninggalkan jejak."
  },
  AvgDialog_18802_Content_55 = {
    Text = "Lengan Jenkin yang terentang hanya dengan kosong memegang gaun kosong Aigis, dan bersamaan dengan itu, selembar-selembar kertas persegi jatuh menyebar seperti serpihan salju."
  },
  AvgDialog_18802_Content_56 = {
    Text = [[
Ai... Aigis...?
Bagaimana... bisa begitu...]]
  },
  AvgDialog_18802_Content_57 = {
    Text = "Di atas kertas terdapat gambar kupu-kupu emas, tepi yang berkerut telah hati-hati diratakan dan dilipat dengan rapi. Saat jatuh, membawa aroma manis permen."
  },
  AvgDialog_18802_Content_58 = {
    Text = "Ugh... Aigis..."
  },
  AvgDialog_18802_Content_59 = {
    Text = "Sebuah pita sutra yang berlumuran darah jatuh ke tangan seorang gadis bersamaan dengan bungkus permen. Pita itu bergerak tertiup angin dan dengan lembut menyentuh ujung jari gadis tersebut, seperti sebuah hiburan lembut yang diberikan oleh seseorang."
  },
  AvgDialog_18802_Content_6 = {
    Text = "Saya tidak bisa mendengar, saya tidak bisa mendengar, saya tidak bisa mendengar—"
  },
  AvgDialog_18802_Content_60 = {
    Text = "Gadis itu berkedip, air mata yang mengaburkan pandangannya pun jatuh dari bulu matanya, lalu diam-diam ditampung oleh warna merah terang itu."
  },
  AvgDialog_18802_Content_61 = {
    Text = "Warna yang familiar ini, tekstur yang familiar ini —— hanya kurang sebuah gesper perak berbentuk persegi untuk bisa sempurna bertemu dengan keberadaan dalam memori-nya."
  },
  AvgDialog_18802_Content_62 = {
    Text = "...Kakak...?"
  },
  AvgDialog_18802_Content_7 = {
    Text = [[
Berhasil, berhasil? 
 Cepat lari, cepat, tapi tolong jangan memberitahu siapa pun.]]
  },
  AvgDialog_18802_Content_8 = {
    Text = "<Shake:<AvgNormalFont:Tunggu, tidak, ini apa! Kepalaku, kepalaku… \n Ah… Aah…! <Shake:Ah——!!>>>"
  },
  AvgDialog_18802_Content_9 = {
    Text = "Maaf... Maaf..."
  },
  AvgDialog_18804_Content_1 = {
    Text = "Penjaga yang terhormat, habis dijarah oleh beberapa anak biasa. Pelatihan setahun terakhir benar-benar sia-sia, bahkan murid baru di sekolah dasar umum lebih cerdas daripada kamu."
  },
  AvgDialog_18804_Content_2 = {
    Text = "Untungnya, pencuri itu juga ada di lokasi misi. Kalau tidak, kamu harus menanggung akibat buruknya sendiri. Aku tidak akan mengizinkanmu menyia-nyiakan waktu misi untuk urusan pribadi."
  },
  AvgDialog_18804_Content_3 = {
    Text = "Kondisinya tidak seburuk itu, Boneka. Berikan %player% sedikit kepercayaan."
  },
  AvgDialog_18804_Content_4 = {
    Text = "Juga, jangan mengganggu penyelidikan Penjaga."
  },
  AvgDialog_18805_Content_1 = {
    Text = "Penjaga yang terhormat, habis dijarah oleh beberapa anak biasa. Pelatihan setahun terakhir benar-benar sia-sia, bahkan murid baru di sekolah dasar umum lebih cerdas daripada kamu."
  },
  AvgDialog_18805_Content_2 = {
    Text = "Untungnya, pencuri itu juga ada di lokasi misi. Kalau tidak, kamu harus menanggung akibat buruknya sendiri. Aku tidak akan mengizinkanmu menyia-nyiakan waktu misi untuk urusan pribadi."
  },
  AvgDialog_18805_Content_3 = {
    Text = "Kondisinya tidak seburuk itu, Boneka. Berikan %player% sedikit kepercayaan."
  },
  AvgDialog_18805_Content_4 = {
    Text = "Juga, jangan mengganggu penyelidikan Penjaga."
  },
  AvgDialog_18808_Content_1 = {
    Text = "Ini adalah tes percakapan tanpa latar belakang 1"
  },
  AvgDialog_18808_Content_2 = {
    Text = "Ini adalah tes percakapan tanpa latar belakang 2"
  },
  AvgDialog_18809_Content_1 = {
    Text = [[
Murphy tidak banyak berbasa-basi. Dia menarik Ramona ke samping dan mulai membuka pakaiannya. 
 Saat kancing terakhir pada bagian depan terbuka, Ramona melihat "dewa" di dalam tubuh gadis itu.]]
  },
  AvgDialog_18809_Content_2 = {
    Text = "Di bagian dada terdapat sepotong kulit transparan. Kulit transparan ini menarik kulit dan otot di sekitarnya, menyebabkan seluruh rongga dada dan perut tampak berwarna putih pucat dengan tanda-tanda kemunduran."
  },
  AvgDialog_18809_Content_3 = {
    Text = "Fenomena aneh itu memperlihatkan organ di dalam rongga dada dengan jelas. Ramona melihat sebuah jantung muda berwarna merah pucat, serta sebuah \"telur\" berwarna susu."
  },
  AvgDialog_18809_Content_4 = {
    Text = "Tak terhitung jumlahnya benang halus menjulur dari \"telur\", erat berjalinan dengan pembuluh darah Murphy, saling bergantung satu sama lain."
  },
  AvgDialog_18809_Content_5 = {
    Text = "Seandainya keberadaannya tidak menekan jantung Murphy, Dia tampaknya menyatu sempurna dengan rongga dada transparan itu, tidak seperti benda asing."
  },
  AvgDialog_18809_Content_6 = {
    Text = "Dia Kekacauan namun tenang, orison segitiga terbalik yang terukir di atasnya juga ikut membeku, seperti sebuah karya seni yang aneh."
  },
  AvgDialog_18809_Content_7 = {
    Text = "Pelarutan… benda ini sudah terkena pelarutan."
  },
  AvgDialog_18809_Content_8 = {
    Text = "Apakah sudah cukup melihat?"
  },
  AvgDialog_18809_Content_9 = {
    Text = "Maaf, aku terlalu lancang. Cepat kenakan bajumu."
  },
  AvgDialog_18810_Content_1 = {
    Text = "Hitung Mundur 20 Menit"
  },
  AvgDialog_18810_Content_10 = {
    Text = "Hati-hati! Jangan jatuh ke laut!"
  },
  AvgDialog_18810_Content_11 = {
    Text = [[
Ular raksasa berbentuk ular muncul dari laut, hampir membalikkan seluruh kapal. 
 Beberapa kepala ular bergerak liar, menciptakan bayangan menakutkan yang luas di atas dek.]]
  },
  AvgDialog_18810_Content_12 = {
    Text = "Orang yang melampaui batas… orang yang tidak sopan… bodoh!"
  },
  AvgDialog_18810_Content_13 = {
    Text = "Dewa Ibu… Dewa Ibu… @3!"
  },
  AvgDialog_18810_Content_14 = {
    Text = "Astaga, itu Miryam!"
  },
  AvgDialog_18810_Content_15 = {
    Text = "Cepat bawa Murphy ke bawah!"
  },
  AvgDialog_18810_Content_16 = {Text = "Ah!!"},
  AvgDialog_18810_Content_17 = {
    Text = "Kamu menoleh ke arah dek di belakang, sosok Murphy sudah tidak ada di sana. Kepala ular raksasa itu menggigit erat gadis itu dan menyeretnya ke dalam Aequor."
  },
  AvgDialog_18810_Content_2 = {
    Text = "Tautan? Apakah ini berarti dia akan bergantung padamu untuk bertahan hidup di masa depan?"
  },
  AvgDialog_18810_Content_3 = {
    Text = "Hanya solusi sementara, kami tidak berniat mengambil Celeste dari tangan Anda."
  },
  AvgDialog_18810_Content_4 = {
    Text = "Ini bukan sesuatu yang bisa aku putuskan."
  },
  AvgDialog_18810_Content_5 = {
    Text = "Celeste, apakah kamu bersedia?"
  },
  AvgDialog_18810_Content_6 = {
    Text = "Seolah kata kunci telah terpicu, Celeste mengangkat kepalanya, namun ia menatap ke arah laut di belakangnya. Pelayaran pun berhenti."
  },
  AvgDialog_18810_Content_7 = {
    Text = "Kapal, tidak bisa bergerak lagi."
  },
  AvgDialog_18810_Content_8 = {
    Text = "Ada sesuatu yang mencengkeram saya."
  },
  AvgDialog_18810_Content_9 = {
    Text = "Sebelum suara itu hilang, getaran yang belum pernah terjadi sebelumnya mengguncang dengan hebat di bawah kaki, dan badan kapal miring pada sudut yang tak terbayangkan."
  },
  AvgDialog_18812_Content_1 = {
    Text = "Bahkan kalian juga seperti ini... sekumpulan orang dewasa yang hanya berbicara semaunya sendiri."
  },
  AvgDialog_18812_Content_10 = {
    Text = "Cahaya yang terlalu menyilaukan menusuk mata, membuat air mata mengalir tanpa bisa dikendalikan."
  },
  AvgDialog_18812_Content_11 = {Text = "Ini, ini!?"},
  AvgDialog_18812_Content_12 = {
    Text = "Cairan keruh mengalir habis, dan mata akhirnya bisa fokus kembali pada gadis itu."
  },
  AvgDialog_18812_Content_13 = {
    Text = "Mata pisaunya menembus dalam ke arah dada, gadis yang mandi di bawah cahaya bulan membuka matanya."
  },
  AvgDialog_18812_Content_14 = {
    Text = "Bulan purnama yang melambangkan kematian sudah sangat dekat, namun di wajah muda itu tidak terlihat sedikit pun rasa takut."
  },
  AvgDialog_18812_Content_15 = {
    Text = "Aku... menembus-Nya... Dia tidak akan dilahirkan lagi..."
  },
  AvgDialog_18812_Content_16 = {
    Text = "Dengan cara ini..."
  },
  AvgDialog_18812_Content_17 = {
    Text = "Tangan yang erat memegang gagang pisau terkulai lemas, cairan berwarna merah segar, kental, dan pekat mengalir deras dari mulut luka, mengalir melewati celah jari-jari dan masuk ke laut."
  },
  AvgDialog_18812_Content_18 = {
    Text = "Darah dengan cepat mengalir keluar dari tubuh, warna kulit sangat pucat, namun seluruh tubuh memancarkan semangat hidup yang aneh."
  },
  AvgDialog_18812_Content_19 = {
    Text = "Tidak... tidak, tidak tidak tidak aaaaa——"
  },
  AvgDialog_18812_Content_2 = {
    Text = "Tidak ada yang pernah meminta pendapatku, bahkan sekali pun…… Hmph."
  },
  AvgDialog_18812_Content_20 = {
    Text = "Ya Tuhan yang Maha Kuasa, ampunilah aku, ampunilah anak ini, ampunilah hamba-Mu yang setia…"
  },
  AvgDialog_18812_Content_21 = {
    Text = "Selaras akan tiba, Selaras akan tiba, akan tiba…"
  },
  AvgDialog_18812_Content_22 = {
    Text = "\"Plasenta\"pecah, \"jantung\"juga runtuh — tak terhitung banyaknya tangan menjulur keluar dari tubuh, rongga dada gadis itu hancur menjadi serpihan."
  },
  AvgDialog_18812_Content_23 = {
    Text = "Tangan yang cacat mencengkeram erat sisa-sisa yang sudah tak berbentuk, bertumpuk, membengkak, bertumpuk, membengkak——"
  },
  AvgDialog_18812_Content_24 = {
    Text = "Ah ah... Anda mendengarku... Anda menanggapiku..."
  },
  AvgDialog_18812_Content_25 = {
    Text = "Mereka mendorong sebuah entitas cacat ke bawah sinar bulan."
  },
  AvgDialog_18812_Content_26 = {
    Text = "Dewa yang agung...!"
  },
  AvgDialog_18812_Content_3 = {
    Text = "Nyawa yang diperoleh dengan pengorbanan... siapa yang menginginkannya?"
  },
  AvgDialog_18812_Content_4 = {
    Text = [[
Tidak bisa, plasentanya terlalu keruh. 
 Apakah dengan menggunakan "Roh Penelusuran"bisa melihat ke dalamnya?]]
  },
  AvgDialog_18812_Content_5 = {
    Text = "Kamu menggenggam erat Kunci perak yang bergetar, lalu tenggelam kembali ke dalam ruang kesadaran."
  },
  AvgDialog_18812_Content_6 = {
    Text = "Di ruang yang dilapisi D-lendir, cahaya yang melambangkan kehidupan dan pengetahuan menjadi semakin bersinar."
  },
  AvgDialog_18812_Content_7 = {
    Text = "——Itu adalah pisau ritual yang memantulkan cahaya bulan yang dingin."
  },
  AvgDialog_18812_Content_8 = {Text = "——Uh!!"},
  AvgDialog_18812_Content_9 = {
    Text = "Cahaya meledak dalam sekejap, bahkan memaksamu keluar dari dunia roh."
  },
  AvgDialog_18813_Content_1 = {
    Text = "Selanjutnya adalah transisi efek. Memperlambat aliran waktu. Tes."
  },
  AvgDialog_18813_Content_10 = {
    Text = "Badai Pasir 2"
  },
  AvgDialog_18813_Content_11 = {
    Text = "Pengujian selesai"
  },
  AvgDialog_18813_Content_12 = {
    Text = "Berikutnya akan dilakukan pengujian Efek layar yang terus bergetar."
  },
  AvgDialog_18813_Content_13 = {
    Text = "Pengujian dimulai"
  },
  AvgDialog_18813_Content_16 = {
    Text = "Pengujian selesai"
  },
  AvgDialog_18813_Content_17 = {
    Text = "Berikutnya akan dilakukan [Efek layar] video aktivasi Kunci Perak - Pengujian"
  },
  AvgDialog_18813_Content_18 = {
    Text = "Pengujian dimulai"
  },
  AvgDialog_18813_Content_19 = {
    Text = "Tes selesai, tetapi saya akan langsung memulai [Efek layar] Efek aktivasi Kunci perak Tes"
  },
  AvgDialog_18813_Content_2 = {
    Text = "Pengujian dimulai"
  },
  AvgDialog_18813_Content_20 = {
    Text = "Pengujian dimulai"
  },
  AvgDialog_18813_Content_21 = {
    Text = "Sedang berlangsung"
  },
  AvgDialog_18813_Content_22 = {
    Text = "Pengujian selesai"
  },
  AvgDialog_18813_Content_23 = {
    Text = "Selanjutnya akan dilakukan pengujian Efek FadeDarkRole."
  },
  AvgDialog_18813_Content_26 = {Text = "Selesai"},
  AvgDialog_18813_Content_3 = {
    Text = "Pengujian selesai"
  },
  AvgDialog_18813_Content_4 = {
    Text = "Selanjutnya akan dilakukan transisi latar belakang dan pengujian percepatan waktu."
  },
  AvgDialog_18813_Content_5 = {
    Text = "Pengujian dimulai"
  },
  AvgDialog_18813_Content_6 = {
    Text = "Pengujian selesai"
  },
  AvgDialog_18813_Content_7 = {
    Text = "Berikutnya akan dilakukan [Efek Layar] Uji Badai Pasir"
  },
  AvgDialog_18813_Content_8 = {
    Text = "Pengujian dimulai"
  },
  AvgDialog_18813_Content_9 = {
    Text = "Badai Pasir 1"
  },
  AvgDialog_18814_Content_1 = {
    Text = "Hah, maaf, sekarang tidak ada waktu untuk menunggu kau beradaptasi."
  },
  AvgDialog_18814_Content_10 = {
    Text = "Ramona sangat terkejut. Dalam memori, sepertinya kamu belum pernah melihatnya begitu cemas sebelumnya."
  },
  AvgDialog_18814_Content_11 = {
    Text = "Suara gadis yang dibanjiri masalah bergetar, tampak sedikit lelah."
  },
  AvgDialog_18814_Content_12 = {
    Text = "Kalau tidak, apakah saya datang ke sini untuk berlibur?"
  },
  AvgDialog_18814_Content_13 = {
    Text = "Dia menutup matanya sejenak, lalu menyemangati dirinya."
  },
  AvgDialog_18814_Content_14 = {
    Text = [[
Seharusnya aku sudah memikirkan ini, penyerang menunjukkan keakraban yang tinggi dengan Mythag, kunci kuburan tidak mungkin selamat. 
 Di sini dekat pintu belakang, kalian segera pergi.]]
  },
  AvgDialog_18814_Content_15 = {
    Text = "Kita bisa pergi! %player% bisa menghubungkan kita semua dan memerintahkan—"
  },
  AvgDialog_18814_Content_16 = {
    Text = [[
Ramona. 
 Itu adalah kewajiban kita, %player% hanyalah seorang pemula yang belum terlalu berpengalaman.]]
  },
  AvgDialog_18814_Content_17 = {
    Text = "Tetapi %player% bisa, saya tahu {Male=dia,Female=dia} bisa."
  },
  AvgDialog_18814_Content_18 = {
    Text = "Boneka mengamati kamu dari atas ke bawah, lalu memasang wajah serius ke arah Ramona."
  },
  AvgDialog_18814_Content_19 = {
    Text = [[
Jika saya tidak salah, upacara sumpah seharusnya belum selesai. 
{Male=dia,Female=dia} belum diberikan Kunci perak, bukan?]]
  },
  AvgDialog_18814_Content_2 = {
    Text = "Varian abnormal tiba di Key Mound sebelum alarm berbunyi, kemungkinan besar <Blue:Penghalang Kabut> di perimeter Mythag sudah tidak berfungsi."
  },
  AvgDialog_18814_Content_20 = {
    Text = "Masuknya orang yang tidak berwenang ke zona terlarang Mythag merupakan insiden tingkat apa, aku pikir kamu yang dibesarkan di sini sejak kecil sudah memahaminya."
  },
  AvgDialog_18814_Content_21 = {
    Text = "Keadaan mendesak, dan %player% bukanlah mahasiswa baru biasa, {Male=dia,Female=dia} adalah satu-satunya Penjaga yang kita miliki."
  },
  AvgDialog_18814_Content_22 = {
    Text = "Kau harus ingat, tentang <Yellow: ledakan besar Akut> setahun yang lalu. Jika bukan karena {Male=dia,Female=dia} yang menghubungkan semua pembangun sendirian, aku tidak akan bisa berdiri di sini berdebat denganmu."
  },
  AvgDialog_18814_Content_23 = {
    Text = "Gadis berambut merah muda tidak menjawab, melainkan berbalik ke arahmu."
  },
  AvgDialog_18814_Content_24 = {
    Text = "Aku tahu kau pernah melihat sekilas apa yang ada di dalam <Yellow:\"pintu\">. Namun, baik masa depan dunia maupun inti Mythag mungkin lebih mengerikan daripada yang kau bayangkan."
  },
  AvgDialog_18814_Content_25 = {
    Text = "Kami menghadapi fenomena yang dapat menyebabkan kehancuran keberadaan materi itu sendiri. Begitu terkontaminasi oleh <Yellow:Pelarutan>, segalanya tentangmu akan lenyap tanpa jejak, bahkan memori tentangmu pun tidak akan tersisa."
  },
  AvgDialog_18814_Content_26 = {
    Text = "Dalam upacara sumpah, nama yang terukir di nisan akan berubah menjadi genangan lumpur hitam, dan tidak seorang pun akan mengingatnya."
  },
  AvgDialog_18814_Content_27 = {
    Text = "Jawab aku, apakah kamu sudah benar-benar siap?"
  },
  AvgDialog_18814_Content_28 = {
    Text = "Boneka menatapmu dengan dingin, nadanya tanpa emosi."
  },
  AvgDialog_18814_Content_29 = {
    Text = "Dia tampak tidak memiliki ekspresi, tetapi dari dasar murid matanya yang seperti es, kamu bisa melihat api yang berkobar dengan ganas."
  },
  AvgDialog_18814_Content_3 = {
    Text = [[
<Blue:William> Kakak Senior tahu hari ini ada ritual di Makam Kunci, tapi bala bantuan belum datang, ditambah dengan suara lonceng... 
 Kita harus cari cara untuk bertemu mereka, <Yellow:memberantas sumber gangguan>.]]
  },
  AvgDialog_18814_Content_30 = {
    Text = "Jawaban Anda adalah——"
  },
  AvgDialog_18814_Content_31 = {
    Text = "Nisan saya, sekarang berdiri di tengah Key Mound."
  },
  AvgDialog_18814_Content_32 = {
    Text = [[
Kamu adalah anggota Mythag.
Mungkin sejak di Akut, kamu sudah menjadi salah satunya.]]
  },
  AvgDialog_18814_Content_33 = {
    Text = "Di sini ada sesuatu yang hanya bisa aku lakukan."
  },
  AvgDialog_18814_Content_34 = {
    Text = "Keputusan ini mungkin terlihat sedikit terburu-buru, tetapi siapa yang bisa menjamin bahwa setiap momen dalam hidup selalu dipersiapkan dengan sempurna?"
  },
  AvgDialog_18814_Content_35 = {Text = "Baiklah."},
  AvgDialog_18814_Content_36 = {
    Text = "Saya, sebagai kepala sekolah keenam Mythag <Blue:Oliver Elsi>, memberikan kunci perak bernomor K-0617 ini kepadamu."
  },
  AvgDialog_18814_Content_38 = {
    Text = [[
Boneka mengeluarkan kunci perak dari kotak kecil yang presisi dan memasangnya di dada Anda. 
 Kunci perak berkilauan, sensasi yang familiar memenuhi rongga dada.]]
  },
  AvgDialog_18814_Content_39 = {
    Text = "Mulai sekarang, dengan gelar Penjaga, engkau akan bersama ribuan guru dan siswa di Mythag."
  },
  AvgDialog_18814_Content_4 = {Text = "?!"},
  AvgDialog_18814_Content_41 = {
    Text = "Sekarang, buat tautan denganku."
  },
  AvgDialog_18814_Content_5 = {
    Text = "Di ujung pandangan, pemuda berambut emas mengangkat perisai raksasa hitam yang tidak sesuai dengan posturnya, sedang menahan serangan dari seorang pejuang pedang ganda yang gesit."
  },
  AvgDialog_18814_Content_6 = {
    Text = "Dia menggunakan Perisai untuk melindungi gadis berambut panjang merah muda di belakangnya dengan kuat, namun terus terdesak mundur."
  },
  AvgDialog_18814_Content_7 = {
    Text = "Kamu mengenal gadis berambut merah muda itu, dia adalah Profesor Boneka yang terkenal sulit diajak berkomunikasi, bernaung di bawah <Blue:Bangun Research Institute>. Dengan kata lain, dia adalah personel non-pertempuran."
  },
  AvgDialog_18814_Content_8 = {
    Text = "Tunggu… yang menyerang itu… adalah Pembangun?"
  },
  AvgDialog_18814_Content_9 = {
    Text = "Boneka? <Blue:Menara Jam> tidak terkendali?!"
  },
  AvgDialog_18815_Content_1 = {
    Text = "Hitung Mundur 80 Menit"
  },
  AvgDialog_18815_Content_10 = {
    Text = "Murphy melangkah maju dua langkah, tiba-tiba tubuhnya bergoyang hebat, lalu jatuh lemas di sekitar tiang kapal."
  },
  AvgDialog_18815_Content_11 = {Text = "Murphy?!"},
  AvgDialog_18815_Content_12 = {
    Text = "Kamu menopang Murphy yang terkulai di atas dek. Kesadarannya sudah tidak jelas, poninya basah oleh keringat dingin, tampak sangat kacau dan menempel di dahinya."
  },
  AvgDialog_18815_Content_13 = {
    Text = "Sakit… sangat sakit……"
  },
  AvgDialog_18815_Content_14 = {
    Text = "Hmm…@1…@1…"
  },
  AvgDialog_18815_Content_15 = {
    Text = "Dia menggenggam erat tanganmu yang menopangnya, rasa sakit membuatnya secara tidak sadar mengeratkan jari-jarinya, lima jarinya menancap ke dalam dagingmu, namun kamu tak terlalu memperhatikan sedikit rasa sakit itu."
  },
  AvgDialog_18815_Content_16 = {
    Text = "Kamu mendengar ketukan drum yang semakin keras — otot yang bukan milik manusia berdenyut di dalam rongga dada gadis itu."
  },
  AvgDialog_18815_Content_17 = {
    Text = "Embrio… sedang menghisap hidupnya."
  },
  AvgDialog_18815_Content_18 = {
    Text = "Mi…@2……"
  },
  AvgDialog_18815_Content_19 = {
    Text = "Selain mengerang kesakitan, Murphy hanya bisa mengucapkan gumaman yang tidak bermakna."
  },
  AvgDialog_18815_Content_2 = {
    Text = "Kabut tebal menyelimuti permukaan laut, namun dek kapal disinari oleh cahaya bulan sehingga tampak sangat terang. Setiap ekspresi orang terlihat dengan jelas."
  },
  AvgDialog_18815_Content_20 = {
    Text = "Di tengah suara yang kacau dan tidak teratur ini, musuh muncul dari Bayangan."
  },
  AvgDialog_18815_Content_3 = {Text = "Bulan…"},
  AvgDialog_18815_Content_4 = {
    Text = "Apa yang terjadi dengan bulan?"
  },
  AvgDialog_18815_Content_5 = {
    Text = "Semakin terang."
  },
  AvgDialog_18815_Content_6 = {
    Text = "Murphy menelan sisa kalimatnya, tapi kamu tahu apa yang ingin dia katakan——"
  },
  AvgDialog_18815_Content_7 = {
    Text = "Waktu yang tersisa untuknya semakin berkurang."
  },
  AvgDialog_18815_Content_8 = {
    Text = "... Segera bergabung dengan yang lain. Mungkin Kapten dan yang lainnya memiliki cara untuk segera tiba di pantai."
  },
  AvgDialog_18815_Content_9 = {Text = "Hmm..."},
  AvgDialog_18818_Content_1 = {
    Text = "Tertangkap!"
  },
  AvgDialog_18818_Content_10 = {
    Text = "Makhluk raksasa dengan penampilan aneh saat ini menundukkan kepalanya dengan patuh, seolah-olah mengharapkan belaian dari gadis berpakaian putih."
  },
  AvgDialog_18818_Content_11 = {
    Text = "Di atas leher tubuh raksasa anjing itu tampak jelas sebuah kepala manusia yang memakai mahkota, membuat adegan ini menjadi sangat aneh."
  },
  AvgDialog_18818_Content_12 = {Text = "Lily…"},
  AvgDialog_18818_Content_13 = {
    Text = "Gadis berpakaian putih perlahan berjalan seperti dalam gerakan lambat menuju makhluk raksasa yang penampilannya aneh. Dia mengulurkan tangannya yang ramping dan membelai kepalanya, seolah-olah sedang membelai hewan peliharaan biasa."
  },
  AvgDialog_18818_Content_14 = {
    Text = "Di atas leher tubuh raksasa anjing itu terlihat jelas sebuah kepala manusia yang memakai mahkota, membuat adegan ini menjadi sangat aneh."
  },
  AvgDialog_18818_Content_16 = {
    Text = "Kamu dan Ramona saling berpandangan, dada kalian dipenuhi dengan ribuan kata yang tak terucap."
  },
  AvgDialog_18818_Content_17 = {
    Text = "Hei, kalian tidak hanya akan berdiri di sana, kan? Anjing neraka sudah ada di depan mata."
  },
  AvgDialog_18818_Content_18 = {
    Text = "Tersangka utama yang harus kita lakukan Penyelidikan ada di sekitar kita, bagaimana ya mengatakannya? \"Mudah didapat tanpa usaha\"?"
  },
  AvgDialog_18818_Content_19 = {
    Text = "Gadis itu seolah-olah tidak mendengarnya, berbisik di dekat telinga Kum. Angin malam yang lembut membawa suara halus itu ke dalam gendang telinga."
  },
  AvgDialog_18818_Content_2 = {
    Text = "Ramona melompat maju, monster yang terdesak menggeram dengan ganas, dengan niat melakukan perlawanan terakhir."
  },
  AvgDialog_18818_Content_20 = {
    Text = [[
Kum, jadi anak baik dan dengarkan perintah tuan.
Anak yang patuh adalah anak yang baik.]]
  },
  AvgDialog_18818_Content_21 = {
    Text = "Suara itu perlahan terdengar, Lily berputar dan berjalan mendekati kalian."
  },
  AvgDialog_18818_Content_22 = {
    Text = "Wanita Narsis berkata, jika Kuum ditemukan oleh seseorang, Lily harus kembali ke sisi ibunya."
  },
  AvgDialog_18818_Content_23 = {
    Text = [[
Sekarang, silahkan kembali ke toko.
Wanita narsis akan memberitahumu segalanya.]]
  },
  AvgDialog_18818_Content_3 = {
    Text = "<Italic:Jangan, jangan, Kumu, kembali!>"
  },
  AvgDialog_18818_Content_4 = {
    Text = "Suara ini... sepertinya pernah kudengar di suatu tempat?"
  },
  AvgDialog_18818_Content_5 = {
    Text = "Dari bayangan lampu yang gelap, muncul sosok kecil yang menyusut."
  },
  AvgDialog_18818_Content_6 = {
    Text = "Khum, tidak boleh memberikan Kerusakan kepada Kakak laki-laki, Kakak perempuan ya."
  },
  AvgDialog_18818_Content_7 = {
    Text = "Anjing besar yang disebut \"Khum\" duduk di tanah dan dengan patuh menjilati cakarnya."
  },
  AvgDialog_18818_Content_8 = {Text = "Khum..."},
  AvgDialog_18818_Content_9 = {
    Text = "Pada saat itulah baru bisa diperhatikan, bahwa wajah yang hitam legam itu bukan tanpa fitur wajah. Hanya saja, mata yang tertutup, lubang hidung yang pipih, dan bibir yang hampir tak terlihat semuanya berwarna hitam pekat, sehingga menciptakan ilusi wajah tanpa fitur."
  },
  AvgDialog_18819_Content_1 = {
    Text = "Ini adalah tes percakapan tanpa latar belakang 1"
  },
  AvgDialog_18819_Content_2 = {
    Text = "Ini adalah tes percakapan tanpa latar belakang 2"
  },
  AvgDialog_18820_Content_1 = {
    Text = "Teror di Museum Lilin"
  },
  AvgDialog_18820_Content_10 = {
    Text = "Ayo, tanyakan dia."
  },
  AvgDialog_18820_Content_11 = {
    Text = "Jadi, Nona yang cantik dan menggemaskan, bolehkah kami masuk untuk melihat-lihat?"
  },
  AvgDialog_18820_Content_12 = {
    Text = [[
Museum lilin ini hanya dibuka untuk pengunjung pada hari berkabut seperti ini. 
 Selama kalian adalah tamu yang patuh terhadap aturan, kalian bisa masuk.]]
  },
  AvgDialog_18820_Content_13 = {
    Text = "Apakah kalian tamu yang mematuhi aturan?"
  },
  AvgDialog_18820_Content_14 = {
    Text = "Tentu saja benar"
  },
  AvgDialog_18820_Content_15 = {
    Text = "Apa itu aturan?"
  },
  AvgDialog_18820_Content_16 = {
    Text = "Bagus, aku suka tamu yang patuh pada aturan."
  },
  AvgDialog_18820_Content_17 = {
    Text = "Tidak apa-apa, kalian akan menjadi lebih patuh, percayalah padaku."
  },
  AvgDialog_18820_Content_18 = {
    Text = "Ini adalah anjing kesayanganku, Bobi. Kalian pasti juga tidak ingin membuatnya marah, kan?"
  },
  AvgDialog_18820_Content_19 = {
    Text = "<BigShake:Uwaa!!!>"
  },
  AvgDialog_18820_Content_2 = {
    Text = "Museum lilin yang diperbesar"
  },
  AvgDialog_18820_Content_20 = {
    Text = "Gadis itu membawa ketiganya masuk ke dalam gedung, kemudian berdiri di belakang meja resepsionis dan mengambil sikap layaknya seorang resepsionis."
  },
  AvgDialog_18820_Content_21 = {
    Text = "Ini adalah <Yellow:Area Pameran Pertama>."
  },
  AvgDialog_18820_Content_22 = {
    Text = "Saya ingat Duo pernah berkata, \"Ada sesuatu yang tersembunyi di sini.\""
  },
  AvgDialog_18820_Content_23 = {
    Text = "Jangan lengah, Penjaga. Di sana mungkin tersembunyi... sesuatu yang tak terduga."
  },
  AvgDialog_18820_Content_24 = {
    Text = "Apa, takut?"
  },
  AvgDialog_18820_Content_25 = {
    Text = "Tidak ada hal seperti itu"
  },
  AvgDialog_18820_Content_26 = {
    Text = "<Small:Hmm… aroma aneh apa ini.>"
  },
  AvgDialog_18820_Content_27 = {
    Text = "Sebaiknya kamu lebih baik tidak tahu."
  },
  AvgDialog_18820_Content_28 = {
    Text = "Ini adalah <Yellow:Area Pameran Kedua>."
  },
  AvgDialog_18820_Content_3 = {
    Text = "Museum lilin yang biasa"
  },
  AvgDialog_18820_Content_30 = {
    Text = "<BigShake:Uwaa!!!>"
  },
  AvgDialog_18820_Content_31 = {
    Text = "Ini adalah <Shake: karya unggulan kami>, bagaimana, apakah terasa sangat hidup?"
  },
  AvgDialog_18820_Content_32 = {
    Text = "Hampir sama persis dengan manusia sungguhan——"
  },
  AvgDialog_18820_Content_33 = {
    Text = "<Change>Haha."
  },
  AvgDialog_18820_Content_34 = {Text = "?!"},
  AvgDialog_18820_Content_35 = {
    Text = "Apakah aku salah lihat, sepertinya dia baru saja tersenyum."
  },
  AvgDialog_18820_Content_36 = {
    Text = "Ah, siapa yang tahu."
  },
  AvgDialog_18820_Content_37 = {
    Text = "Ini adalah <Red:Peta Venue> yang disiapkan untuk kalian."
  },
  AvgDialog_18820_Content_38 = {
    Text = "Selanjutnya, silakan nikmati waktu kunjungan pameran dengan bebas~"
  },
  AvgDialog_18820_Content_4 = {
    Text = "Panti asuhan yang normal"
  },
  AvgDialog_18820_Content_5 = {
    Text = "Panti asuhan diperbesar menjadi 1.2 kali lipat"
  },
  AvgDialog_18820_Content_6 = {
    Text = "Panti asuhan yang normal"
  },
  AvgDialog_18820_Content_7 = {
    Text = "Ini adalah... Museum Lilin Rogers?"
  },
  AvgDialog_18820_Content_8 = {
    Text = "Apa sekarang, <Yellow:%player%>?"
  },
  AvgDialog_18820_Content_9 = {
    Text = "Kita perlu menemukan lokasi \"Spring\"."
  },
  AvgDialog_18823_Content_1 = {
    Text = "Hei, bangun!"
  },
  AvgDialog_18823_Content_10 = {
    Text = "Waktu untuk mengingat telah berakhir! Selanjutnya adalah bagian utama kita ——"
  },
  AvgDialog_18823_Content_11 = {
    Text = "Filter lendir yang meniru aliran Pelarutan D-lendir!"
  },
  AvgDialog_18823_Content_12 = {
    Text = "Ini adalah filter yang cukup panjang, disarankan untuk digunakan bersama dengan beberapa baris dialog."
  },
  AvgDialog_18823_Content_15 = {
    Text = "Baiklah, waktu sudah habis! Sekarang kita beralih ke modul cuaca kita —"
  },
  AvgDialog_18823_Content_16 = {
    Text = "Turun salju!"
  },
  AvgDialog_18823_Content_17 = {
    Text = "Hatsj! Hatsj! Hari ini pakaianku agak terlalu sedikit…"
  },
  AvgDialog_18823_Content_18 = {Text = "Kebakaran!"},
  AvgDialog_18823_Content_19 = {
    Text = "Cuaca kering, hati-hati dengan api lilin!"
  },
  AvgDialog_18823_Content_2 = {
    Text = "Hmm? Kamu tanya efek membuka dan menutup mata tadi itu apa?"
  },
  AvgDialog_18823_Content_20 = {
    Text = "Hujan turun!"
  },
  AvgDialog_18823_Content_21 = {
    Text = "Hanna juga merasa sedikit murung karena cuaca hujan."
  },
  AvgDialog_18823_Content_22 = {
    Text = "Setelah melihat begitu banyak filter, apakah kepalamu terasa sedikit pusing?"
  },
  AvgDialog_18823_Content_23 = {
    Text = "Haha, tingkatkan dosisnya dua kali lipat, dan keluarkan filter pusing kita!"
  },
  AvgDialog_18823_Content_24 = {
    Text = "Bagaimana, apakah kamu merasa sangat pusing, sangat pusing…"
  },
  AvgDialog_18823_Content_25 = {
    Text = "Selanjutnya, kita akan membuat suasana romantis dengan mawar! Aktifkan bunga merah!"
  },
  AvgDialog_18823_Content_26 = {
    Text = "Romantis atau tidak, aku tidak tahu, tapi teman-teman yang alergi serbuk sari akan mengalami kesulitan, karena——"
  },
  AvgDialog_18823_Content_27 = {
    Text = "Tepat setelah Mawar Merah adalah Mawar Gotik! Bunga Hitam aktif!"
  },
  AvgDialog_18823_Content_28 = {
    Text = "Lalu ada efek misterius yang membuat semua orang kebingungan, tidak tahu harus digunakan di mana ——"
  },
  AvgDialog_18823_Content_29 = {
    Text = "Kabut darah!"
  },
  AvgDialog_18823_Content_3 = {
    Text = "Hei, ini adalah filter mata terbuka kami, lho!"
  },
  AvgDialog_18823_Content_30 = {
    Text = "Kelihatannya cukup keren, jadi untuk sementara aku akan tetap menyimpannya."
  },
  AvgDialog_18823_Content_31 = {
    Text = "Setelah selesai melihat kabut darah, mari kita lihat seperti apa kabut hitam itu."
  },
  AvgDialog_18823_Content_32 = {
    Text = "Gelap gulita——Suram dan menyeramkan——Londinium seperti rumah hantu——"
  },
  AvgDialog_18823_Content_33 = {
    Text = "Setelah melihat begitu banyak, mataku sudah lelah. Berkedip sebentar untuk meredakannya."
  },
  AvgDialog_18823_Content_34 = {
    Text = "Tidak bisa, tidak bisa. Nanti harus mencari obat tetes mata juga."
  },
  AvgDialog_18823_Content_35 = {
    Text = "Baiklah, itulah semua efek filter yang tersedia saat ini."
  },
  AvgDialog_18823_Content_36 = {
    Text = "Kelas kecil filter Hannah untuk episode ini telah selesai, sampai bertemu lagi di episode berikutnya~!"
  },
  AvgDialog_18823_Content_4 = {
    Text = "Selain itu, kita juga punya banyak filter lainnya. Ayo ulangi sekali lagi bersama Hanna!"
  },
  AvgDialog_18823_Content_5 = {
    Text = "Jika berbicara tentang London pada tahun 1900, apa reaksi pertama kalian?"
  },
  AvgDialog_18823_Content_6 = {
    Text = "Jawabannya tentu saja kabut!"
  },
  AvgDialog_18823_Content_7 = {
    Text = "Sebuah lautan putih yang membentang, apakah ini membangkitkan kenangan masa lalu bagi semua orang?"
  },
  AvgDialog_18823_Content_8 = {
    Text = "Berbicara tentang kenangan, kita juga punya filter kenangan lho, seperti sekarang ini!"
  },
  AvgDialog_18823_Content_9 = {
    Text = "Bagaimana, apakah terasa seperti nuansa film lama?"
  },
  AvgDialog_18824_Content_1 = {
    Text = "Musim Semi Botticelli"
  },
  AvgDialog_18824_Content_10 = {
    Text = "Ngomong-ngomong, ini adalah surat dari semua orang di Taring untukmu. Nyonya Diana memintaku untuk menyampaikannya padamu."
  },
  AvgDialog_18824_Content_11 = {
    Text = [[
Jika Anda membutuhkan sesuatu di sini, jangan ragu untuk menghubungi kami. Saya akan berusaha datang menjenguk Anda sesering mungkin.
Sampai jumpa lagi, Nona Sarah.]]
  },
  AvgDialog_18824_Content_12 = {
    Text = "Begitu kamu berbalik ke arah pintu, kamu mendengar suara lemah dari belakang."
  },
  AvgDialog_18824_Content_13 = {
    Text = [[
...Permisi... Saya melihat di dalam surat ini, sepertinya tidak ada surat untuk Aigis. 
 Apakah dia... baik-baik saja?]]
  },
  AvgDialog_18824_Content_15 = {
    Text = "Wajah Sarah menunjukkan sedikit harapan yang hati-hati, di sisimu, Ramona menghela napas."
  },
  AvgDialog_18824_Content_16 = {
    Text = "Dia... baik-baik saja."
  },
  AvgDialog_18824_Content_17 = {
    Text = "Karena keadaan khusus, kami memindahkannya ke Rumah Sakit Universitas Mythag. Setelah negaranya stabil, dia pasti akan menulis surat untukmu."
  },
  AvgDialog_18824_Content_18 = {
    Text = "Baguslah, baguslah. Aku... aku masih khawatir apakah dia membenciku."
  },
  AvgDialog_18824_Content_19 = {
    Text = "Setelah aku meninggalkan tempat ini, aku harus memberinya kompensasi yang layak. Menurutmu, apakah dia mau hidup bersamaku? Hanya kita berdua dan Jenkin. Dia pasti akan senang, kan?"
  },
  AvgDialog_18824_Content_2 = {
    Text = "——Dua Hari Kemudian——"
  },
  AvgDialog_18824_Content_20 = {
    Text = "Apakah dia akan melakukannya?"
  },
  AvgDialog_18824_Content_21 = {
    Text = [[
Mungkin iya, tapi sampai saat ini, tidak ada yang bisa menjamin. 
Lagipula, orang yang bisa menjawab pertanyaan itu sudah tiada selamanya.]]
  },
  AvgDialog_18824_Content_22 = {
    Text = "... Saya sangat menyesal."
  },
  AvgDialog_18824_Content_23 = {
    Text = "Tidak... saya... saya tidak percaya..."
  },
  AvgDialog_18824_Content_24 = {
    Text = "Suara Sarah bergetar."
  },
  AvgDialog_18824_Content_25 = {
    Text = "Dia hanya sedang marah, kan? Orang-orang sering berkata bahwa seseorang yang biasanya berwatak baik, saat marah akan menjadi sangat intens. Dia juga seperti itu, kan?"
  },
  AvgDialog_18824_Content_26 = {
    Text = "Aigis, Aigis… Aigis tersayang… Maafkan aku… Maafkan aku…"
  },
  AvgDialog_18824_Content_28 = {Text = "Ayo pergi."},
  AvgDialog_18824_Content_29 = {
    Text = "Kami... sampai jumpa lagi lain waktu, Nona Sarah."
  },
  AvgDialog_18824_Content_3 = {
    Text = [[
11:41, Londinium 
 Markas Besar Komite Perjanjian Mystia 
 Ruang Observasi Bawah Tanah D Area 31]]
  },
  AvgDialog_18824_Content_30 = {
    Text = [[
13:20, Londinium
Universitas Mythag]]
  },
  AvgDialog_18824_Content_31 = {
    Text = "Kamu dan Ramona melangkah ke dalam hutan lebat di luar gerbang sekolah, dari jauh terlihat Jenkin dan seorang siswa yang mengenakan seragam sekolah sedang bergumul di tanah."
  },
  AvgDialog_18824_Content_32 = {Text = "..."},
  AvgDialog_18824_Content_33 = {Text = "..."},
  AvgDialog_18824_Content_34 = {
    Text = "Tikus menggigit cerpelai"
  },
  AvgDialog_18824_Content_35 = {
    Text = "Keajaiban dunia, tikus ternyata menyerang musang dan menggigitnya!"
  },
  AvgDialog_18824_Content_36 = {
    Text = "Siapa yang kamu sebut tikus!"
  },
  AvgDialog_18824_Content_37 = {
    Text = "Kamu bilang siapa musang salju!"
  },
  AvgDialog_18824_Content_38 = {
    Text = "Hannah? Jenkin? Apa yang kalian lakukan di sini...?"
  },
  AvgDialog_18824_Content_39 = {
    Text = "Ini tidak bisa disalahkan padaku, dia yang pertama kali memanggil penjaga!"
  },
  AvgDialog_18824_Content_4 = {
    Text = "...Membuka blokade, sekarang, Nyonya Diana telah mengambil alih sebagai pemimpin Taring Pengrajin, dan Xiao Mike juga sudah kembali."
  },
  AvgDialog_18824_Content_40 = {
    Text = [[
Astaga, aku hanya bercanda sedikit dengannya. 
 Hidup yang terlalu serius itu membosankan.]]
  },
  AvgDialog_18824_Content_41 = {
    Text = "Jadi, orang yang dia cari adalah kalian, ya? Di mana kalian bertemu, Taring Lily? Pemburu Anggota? Ah! Apakah dia Jenkin kecil itu?"
  },
  AvgDialog_18824_Content_42 = {
    Text = "Tidak salah lagi, ini memang cerpelai salju nomor satu di Kerajaan Leo. Apakah kamu sedang mengumpulkan bahan untuk koran sekolah besok?"
  },
  AvgDialog_18824_Content_43 = {
    Text = "Bukan hanya itu, Ramona. Kamu tahu aku, informasi adalah hidupku."
  },
  AvgDialog_18824_Content_44 = {
    Text = "Lalu, di bawah sinar matahari terang, gadis yatim piatu yang malang itu pergi sendirian ke dalam hutan lebat untuk berpetualang. Apa sebenarnya tujuannya? Dapatkah dua orang yang ia cari memberikan sedikit harapan bagi dirinya?"
  },
  AvgDialog_18824_Content_45 = {
    Text = "Hanna, sambil berbicara, tiba-tiba dengan suara \"plak\" mengeluarkan sebuah buku catatan entah dari mana, lalu menatap kalian penuh harap, seolah-olah siap mencatat setiap ucapan dan tindakan kalian."
  },
  AvgDialog_18824_Content_46 = {
    Text = "Wartawan lapangan Hannah Peaceley, akan segera melakukan pelaporan terkini!"
  },
  AvgDialog_18824_Content_47 = {
    Text = "...Aku mulai mengerti, kalian semua di universitas aneh ini, tidak ada satu pun yang berbicara dengan cara yang mudah dimengerti."
  },
  AvgDialog_18824_Content_48 = {
    Text = "Saya tidak bersalah, sungguh."
  },
  AvgDialog_18824_Content_49 = {
    Text = [[
Kalau dia tidak ada, itu lebih baik. 
Ngomong-ngomong, Jenkin, apakah ada masalah?]]
  },
  AvgDialog_18824_Content_5 = {
    Text = "Di Universitas Mythag, sebuah donasi untuk Taring telah diluncurkan dan efeknya sangat baik. Ditambah dengan dukungan dari Tuan Mulia Dexter, operasional dapat berjalan dengan lancar untuk beberapa waktu."
  },
  AvgDialog_18824_Content_50 = {
    Text = "Jenkin mengeluarkan selembar koran yang terlipat kusut dari tasnya dan menyodorkannya ke arahmu serta Ramona."
  },
  AvgDialog_18824_Content_51 = {
    Text = "Sebelumnya kita sudah berjanji bahwa kamu akan membantu aku mencari kakakku. Sekarang, inilah saatnya kamu menepati janjimu."
  },
  AvgDialog_18824_Content_52 = {
    Text = "Dia membuka koran dan menunjuk ke sebuah artikel berjudul \"Lukisan Tiga Dimensi\", sebuah cerita lokal yang unik."
  },
  AvgDialog_18824_Content_53 = {
    Text = "Penulis menulis dengan gaya cerita nyata, dia pernah melihat sebuah pameran menakjubkan di museum lilin No. 44 Jalan Nanhua: karya baru dari seniman lilin Rogers berjudul \"Musim Semi\"."
  },
  AvgDialog_18824_Content_54 = {
    Text = "Sepertinya untuk meningkatkan kredibilitas, di sampingnya juga disertakan sebuah foto yang tampak meyakinkan."
  },
  AvgDialog_18824_Content_55 = {
    Text = "Ini adalah kelompok patung lilin yang dibuat menyerupai lukisan terkenal Botticelli \"Primavera\", terletak di tengah-tengah adalah patung lilin wanita dengan cat yang konyol dan ekspresi penderitaan."
  },
  AvgDialog_18824_Content_56 = {
    Text = [[
Saya ingin melindungi semua orang, melindungi Nona Sarah, melindungi Xiao Mike, melindungi Jenkin.
Saya tidak ingin mereka diubah menjadi <Yellow:patung lilin>.]]
  },
  AvgDialog_18824_Content_57 = {
    Text = "Saya tidak tahu alamatnya, tapi saya berjalan sangat lama, terus sampai ke Distrik Barat, ada sebuah rumah dengan etalase yang memajang manusia. Di papan nama tertulis <Yellow:44>."
  },
  AvgDialog_18824_Content_58 = {
    Text = "Rogers... patung lilin? Dan Jalan Nanhuak <Yellow:44>, ini tidak terlihat seperti kebetulan."
  },
  AvgDialog_18824_Content_59 = {
    Text = "Apa itu? Apakah kalian tahu sesuatu?"
  },
  AvgDialog_18824_Content_6 = {
    Text = "Jadi, kamu bisa merasa tenang."
  },
  AvgDialog_18824_Content_60 = {
    Text = "Aigis telah menyebutkan——"
  },
  AvgDialog_18824_Content_61 = {Text = "Huh huh!"},
  AvgDialog_18824_Content_62 = {
    Text = [[
Kamu memberi isyarat mata kepada Ramona, tapi sudah terlalu terlambat. 
 Mendengar nama Aigis, Jenkin secara nyata menjadi lesu.]]
  },
  AvgDialog_18824_Content_63 = {
    Text = "...Jangan terlalu sedih tentang Aigis."
  },
  AvgDialog_18824_Content_64 = {
    Text = [[
Aku tidak sedih. Aku hanya... 
 Aku sudah berjanji dengannya bahwa dia akan menjadi adikku.]]
  },
  AvgDialog_18824_Content_65 = {
    Text = "Dia membatalkan janjinya, sungguh tidak memiliki integritas."
  },
  AvgDialog_18824_Content_66 = {
    Text = "Bagaimana dengan wanita itu, apakah dia sudah tahu? Tentang Aigis…"
  },
  AvgDialog_18824_Content_68 = {
    Text = "Lupakan saja, lebih baik dia tidak tahu. Aigis pasti tidak ingin dia merasa sedih."
  },
  AvgDialog_18824_Content_69 = {
    Text = [[
Lalu, apa yang kalian dengar? 
Jangan berbelit-belit, cepat! Kalian sudah berjanji untuk membantu aku mencari seseorang!]]
  },
  AvgDialog_18824_Content_7 = {
    Text = "Nyonya Sarah."
  },
  AvgDialog_18824_Content_70 = {
    Text = "Aigis pernah menyebutkan bahwa saat dia dikendalikan, dia pergi ke sebuah tempat di Distrik Barat dengan nomor rumah <Yellow:44>, ditambah lagi dengan \"mereka berubah menjadi patung lilin\"... Apakah orang-orang yang hilang berada di sana?"
  },
  AvgDialog_18824_Content_71 = {
    Text = "Sialan... siapapun itu, aku tidak akan memaafkannya!"
  },
  AvgDialog_18824_Content_72 = {
    Text = "Kapan kita akan berangkat?"
  },
  AvgDialog_18824_Content_73 = {
    Text = "Mengingat bahwa pihak lain mungkin sangat berbahaya, aku lebih berharap kamu mau menunggu di sini untuk kabar dari kami. Namun — kamu pasti punya pemikiran lain, kan?"
  },
  AvgDialog_18824_Content_74 = {
    Text = [[
Itu kakakku, aku tidak mungkin tidak pergi!
Lagipula, siapa tahu kalian akan meminta bantuanku untuk merangkak melalui lubang ventilasi kapan saja!]]
  },
  AvgDialog_18824_Content_75 = {
    Text = "Gagasan ini terlalu spesifik."
  },
  AvgDialog_18824_Content_76 = {
    Text = "Sepertinya harus mengajukan permohonan tugas lapangan mendesak."
  },
  AvgDialog_18824_Content_77 = {
    Text = "Saya akan mencari Profesor Alistair, dia seharusnya bersedia memberi kita akses belakang."
  },
  AvgDialog_18824_Content_78 = {
    Text = "Jika kamu berbicara, pasti tidak ada masalah. Namun — aku berharap William bisa menunda pengumpulan laporan kita terlebih dahulu."
  },
  AvgDialog_18824_Content_79 = {
    Text = "Mengenai hal ini, kalian tidak perlu khawatir."
  },
  AvgDialog_18824_Content_8 = {
    Text = "Luar biasa, sungguh... luar biasa. \nTerima kasih banyak, Ashe——bukan, %player%, Nyonya Ramona."
  },
  AvgDialog_18824_Content_80 = {Text = "?"},
  AvgDialog_18824_Content_81 = {
    Text = "Sekitar satu jam yang lalu, William meninggalkan sekolah dengan izin tugas lapangan."
  },
  AvgDialog_18824_Content_82 = {
    Text = "Aku awalnya ingin mengikutinya, melihat apakah bisa mendapatkan berita apa pun, tapi aku kehilangan jejaknya di jalan dan akhirnya kembali. Melihat arahnya, sepertinya dia pergi ke Barat Daya Londinium."
  },
  AvgDialog_18824_Content_83 = {
    Text = [[
Jalan Southwark ada di Distrik Barat. 
 Sepertinya kali ini, kita bisa menyaksikan sendiri kehebatan Penyelidik ternama, William.]]
  },
  AvgDialog_18824_Content_84 = {
    Text = "...Saya selalu merasa bahwa dia akan sangat memarahi saya..."
  },
  AvgDialog_18824_Content_85 = {
    Text = [[
18:24, Londinium Barat Daya
Jalan Southwark]]
  },
  AvgDialog_18824_Content_86 = {
    Text = "Terima kasih atas kerja sama kalian semua. Selanjutnya, aku bisa menyelesaikannya sendiri."
  },
  AvgDialog_18824_Content_87 = {
    Text = [[
Ini tidak bisa, Tuan. Perintah dari atasan sangat jelas, kami harus menemani Anda dalam penyelidikan. 
 Lagipula, Rogers juga adalah salah satu tersangka kami, tidak mungkin membiarkan Anda bekerja sendirian.]]
  },
  AvgDialog_18824_Content_88 = {
    Text = "Lagipula, dengan kami di sini, identitasmu bisa lebih tersembunyi, bukan?"
  },
  AvgDialog_18824_Content_9 = {
    Text = "Kami hanya bisa berusaha semaksimal mungkin."
  },
  AvgDialog_18824_Content_90 = {
    Text = "Tenang saja, Tuan. Kami punya senjata dan bisa berlari cepat, jadi tidak akan mengecewakan Anda."
  },
  AvgDialog_18824_Content_91 = {
    Text = "Baiklah, harap tingkatkan kewaspadaan. Jika perlu, prioritaskan hidupmu sendiri."
  },
  AvgDialog_18824_Content_92 = {
    Text = "Laporan. Tiba di lokasi misi, Jalan Southwark No. 44, Museum Lilin Rogers. Target dikonfirmasi: memastikan kemungkinan hubungan antara pemilik Museum Lilin Rogers dan Para pematung."
  },
  AvgDialog_18824_Content_93 = {
    Text = [[
Konfirmasi kedatangan di lokasi misi, konfirmasi target Penyelidikan.
Semoga Kunci Perak membimbing jalan ke depan.]]
  },
  AvgDialog_18824_Content_94 = {
    Text = "Semoga Kunci Perak membimbing kita."
  },
  AvgDialog_18825_Content_1 = {
    Text = "Ramona melangkah maju, langsung menuju ke tempat ia melihat bayangan seseorang tadi."
  },
  AvgDialog_18825_Content_10 = {
    Text = "Tiba-tiba, salah satu dari mereka dengan cepat mencengkeram leher orang di sebelahnya. Teriakan singkat terdengar seperti minyak panas yang jatuh ke dalam air, langsung memicu kerumunan di sekitarnya."
  },
  AvgDialog_18825_Content_11 = {
    Text = "Cepat bubar!"
  },
  AvgDialog_18825_Content_2 = {
    Text = "Nona Mary, i-i ini halaman luar, kan? Kamu juga sudah melihatnya tadi. Mari kita kembali ke rute kunjungan semula."
  },
  AvgDialog_18825_Content_3 = {
    Text = "Oh? Tapi kebetulan saya ingin berjalan-jalan di halaman. Kamu bisa memakluminya, kan, Nona Sarah?"
  },
  AvgDialog_18825_Content_4 = {
    Text = "Tentu, tentu. Saya sangat memahami. Hanya saja, eh, apakah kita bisa minum teh terlebih dahulu? Nona Mary——"
  },
  AvgDialog_18825_Content_5 = {
    Text = "Mengabaikan halangan dari Sarah, Ramona melangkah ke halaman depan dan menyapu pandangannya di antara para pekerja yang sedang tekun bekerja."
  },
  AvgDialog_18825_Content_6 = {
    Text = "Udara dipenuhi dengan keringat dan bau aneh, seperti batubara basah yang terbakar."
  },
  AvgDialog_18825_Content_7 = {
    Text = "Lihat, Nona Mary, aku sudah bilang, tidak ada yang bisa dilihat di sini. Sebaiknya kita segera kembali."
  },
  AvgDialog_18825_Content_8 = {
    Text = [[
Saat Sarah berbicara, beberapa pekerja tiba-tiba menghentikan gerakan mereka. 
 Bibir mereka bergerak, sepertinya sedang bergumam sesuatu dengan suara pelan, tubuh mereka bergoyang kecil.]]
  },
  AvgDialog_18825_Content_9 = {
    Text = "Di bawah monokel di mata kiri, Ramona melihat punggung mereka mulai menonjol, cairan hitam merembes keluar dari dalam tubuh mereka, seolah-olah memiliki kehidupan sendiri dan merayap menuruni anggota tubuh mereka."
  },
  AvgDialog_18826_Content_1 = {
    Text = "Di tengah kerumunan yang kacau, Ramona dengan susah payah menahan serangan dari beberapa pekerja yang mulai berperilaku aneh, agar para pekerja lainnya bisa melarikan diri dengan aman."
  },
  AvgDialog_18826_Content_2 = {
    Text = "Perawat! Cepat panggil perawat!"
  },
  AvgDialog_18826_Content_3 = {
    Text = "Langkah-langkah terburu-buru terdengar, beberapa orang yang mengenakan seragam khusus berjalan melawan arus dengan tergesa-gesa. Mereka memegang tali, dengan Ekspresi yang serius."
  },
  AvgDialog_18826_Content_4 = {
    Text = "Di belakang mereka, terdapat sosok berpakaian putih."
  },
  AvgDialog_18826_Content_5 = {
    Text = "Nona Mary, berhati-hatilah!"
  },
  AvgDialog_18826_Content_6 = {
    Text = "Ramona menghindar ke samping, memanfaatkan momentum serangan pekerja abnormal untuk melangkah maju. Dia menempelkan ujung pedang yang masih tersarung ke tulang dada lawan, memaksa mereka mundur beberapa langkah."
  },
  AvgDialog_18826_Content_7 = {
    Text = "Di belakangnya, para perawat berhenti melangkah."
  },
  AvgDialog_18826_Content_8 = {
    Text = "Aku akan bekerja sama dengan kalian. Bersiaplah."
  },
  AvgDialog_18827_Content_1 = {
    Text = "Kabut Berdarah"
  },
  AvgDialog_18827_Content_10 = {
    Text = "Melihat wajah Aigis yang sedikit bingung, Jenkin menghela napas berat. Ia lalu mengambil teko teh yang berat dari nampan, membungkusnya dengan kain, dan memeluknya."
  },
  AvgDialog_18827_Content_11 = {
    Text = "Jenkin, jika ini digunakan untuk bermain, Nyonya Sarah akan marah…"
  },
  AvgDialog_18827_Content_12 = {
    Text = [[
Siapa yang bermain! Aku sedang membantu kamu! 
 Ayo pergi, cepat, selesai lebih awal agar bisa pulang lebih awal!]]
  },
  AvgDialog_18827_Content_13 = {Text = "Hmm, hmm!"},
  AvgDialog_18827_Content_14 = {
    Text = "20:27, Halaman Depan Taring Lily\n"
  },
  AvgDialog_18827_Content_15 = {
    Text = "...Kalian benar-benar percaya pada gadis itu dan berniat menunggu bayangan hitam di sini?"
  },
  AvgDialog_18827_Content_16 = {
    Text = "Mengingat adanya D-marka yang tidak normal di Taring, serta \"peneliti\" yang menghilang, mengikuti dari jauh memang merupakan langkah yang baik."
  },
  AvgDialog_18827_Content_17 = {
    Text = [[
...Baiklah, lagipula yang terbuang adalah waktu kalian sendiri. 
Kembali ke topik sebelumnya, apakah kalian tidak menemukan Clades di Taring?]]
  },
  AvgDialog_18827_Content_18 = {
    Text = "Kunci perak tidak bereaksi, saya perkirakan entitas hidup yang tidak dikenal bukan Clades baru, kemungkinan lebih berkaitan dengan D-marka khusus dan \"Peneliti\" itu."
  },
  AvgDialog_18827_Content_19 = {
    Text = [[
Saya belum pernah melihat D-marka seperti ini, tampaknya hampir mirip dengan percobaan jahitan yang buruk. 
Dan ramuan yang dia gunakan untuk menundukkan para mutan... sebenarnya, saya agak curiga mereka bisa mempengaruhi Pelarutan.]]
  },
  AvgDialog_18827_Content_2 = {
    Text = [[
20:27, Lily's Taring 
 Kafetaria]]
  },
  AvgDialog_18827_Content_20 = {
    Text = "Tidak ada Clades tetapi ada Pelarutan, D-marka berbentuk jahitan... Apakah mereka?"
  },
  AvgDialog_18827_Content_21 = {
    Text = [[
Kata kunci berhasil dibaca, "D-marka pelarutan", total 37 acara terkait. 
Kata kunci acara: <Blue:Aksi jaringan ganas, Para pematung>.]]
  },
  AvgDialog_18827_Content_22 = {
    Text = "Bukankah mereka sudah dimusnahkan dalam operasi gabungan Mythag dan <Blue:Komite> 14 tahun yang lalu?"
  },
  AvgDialog_18827_Content_23 = {
    Text = "Ada kesalahan dalam tindakan mereka sebelumnya, yang memungkinkan anggota inti mereka melarikan diri. Selama bertahun-tahun, tim Penyelidikan tidak pernah menemukan jejak mereka, tak disangka bisa bertemu mereka di sini."
  },
  AvgDialog_18827_Content_24 = {
    Text = [[
Situasinya sudah berubah, bersiaplah untuk menarik diri. 
Ingat, jangan bertindak gegabah, jika tidak, aku akan menjadi orang pertama yang memberikan pelatihan tambahan kepada kalian.]]
  },
  AvgDialog_18827_Content_25 = {
    Text = "Tunggu, Boneka——"
  },
  AvgDialog_18827_Content_26 = {
    Text = "Profesor Boneka sudah pergi, apakah Anda memerlukan untuk meninggalkan pesan?"
  },
  AvgDialog_18827_Content_27 = {
    Text = [[
Benar-benar otoriter seperti di laboratorium. 
 Tidak perlu meninggalkan pesan, terima kasih, Erica.]]
  },
  AvgDialog_18827_Content_28 = {
    Text = "Komunikator menjadi sunyi. Kamu menatap Ramona dan melihat emosi yang sama dengan milikmu di matanya."
  },
  AvgDialog_18827_Content_29 = {
    Text = "Ini adalah tugas kita."
  },
  AvgDialog_18827_Content_3 = {
    Text = [[
Saya benar-benar tidak mengerti, kadang membantu di dapur, kadang mengantarkan makanan untuk Rogers. 
 Apakah kamu begitu suka bekerja? Tidak pernah berhenti sejenak.]]
  },
  AvgDialog_18827_Content_30 = {
    Text = "Penyelidikan yang kami mulai harus diselesaikan oleh kami."
  },
  AvgDialog_18827_Content_31 = {
    Text = "Kami tidak bisa pergi."
  },
  AvgDialog_18827_Content_32 = {
    Text = [[
Kamu tahu bahwa aku pasti mendukung keputusanmu, apa pun itu. 
 Aku percaya padamu, %player%.]]
  },
  AvgDialog_18827_Content_33 = {
    Text = "Jika kita bisa menemukan sesuatu sebelum evakuasi, mungkin Boneka bisa diyakinkan, kan?"
  },
  AvgDialog_18827_Content_34 = {
    Text = "Biarkan dia melihat sejauh mana kita bisa mencapai."
  },
  AvgDialog_18827_Content_35 = {
    Text = [[
20:35, Lily Taring 
 Koridor]]
  },
  AvgDialog_18827_Content_36 = {
    Text = "Sampai kapan kamu akan terus melakukannya untuk si kecil Mike? Jangan setiap kali dia mengatakan lapar, kamu memberikan makan malammu sendiri!"
  },
  AvgDialog_18827_Content_37 = {
    Text = "Tidak apa-apa jika aku melewatkan beberapa kali makan. Xiao Mai masih kecil, dia perlu makan lebih banyak agar sehat dan tidak mudah sakit."
  },
  AvgDialog_18827_Content_38 = {
    Text = "Apakah kamu pikir kamu hebat? Kalau aku tidak mencuri uang %player% untuk membelikanmu roti manis, entah sampai kapan kamu akan kelaparan!"
  },
  AvgDialog_18827_Content_39 = {
    Text = "Tetapi dia sangat penurut. Setelah kenyang, dia akan dengan senang hati memanggilku Kakak. Dan, dia juga memberiku sebuah Hadiah lho."
  },
  AvgDialog_18827_Content_4 = {
    Text = "Jenkin bersandar di tepi meja panjang untuk menyajikan makanan, mengamati Aigis dan beberapa pekerja serta pelayan dapur yang sedang sibuk."
  },
  AvgDialog_18827_Content_40 = {
    Text = "Indah sekali, kan? Ini adalah hadiah dari seorang kakak laki-laki yang bertanya arah kepadanya dua hari yang lalu. Semua orang sangat iri. \nLagipula, Xiao Mai berkata——"
  },
  AvgDialog_18827_Content_41 = {
    Text = "Aku satu, kamu satu, kita selamanya adalah teman terbaik!"
  },
  AvgDialog_18827_Content_42 = {
    Text = "\"...Heh, siapa yang peduli. Begitu aku menemukan kakakku, kami akan pergi bersama. Pada saat itu, kau akan menjadi adikku, dan aku akan memberimu dua kakak!\""
  },
  AvgDialog_18827_Content_43 = {Text = "...Aigis?"},
  AvgDialog_18827_Content_44 = {
    Text = "<Small:Ka... kabut lagi, kenapa... hari ini kabut muncul lagi...>"
  },
  AvgDialog_18827_Content_45 = {
    Text = "Hmm? Memang benar. Di tahun-tahun sebelumnya tidak ada banyak hari berkabut, cuaca akhir-akhir ini sangat aneh."
  },
  AvgDialog_18827_Content_46 = {
    Text = "Malah membuatku teringat pada malam pertama kita bertemu."
  },
  AvgDialog_18827_Content_47 = {
    Text = "20:35, Halaman Depan Taring Lily\n"
  },
  AvgDialog_18827_Content_48 = {
    Text = "Cuaca ini... Apakah salah satu penyintas pernah berkata bahwa pada malam mereka mengalami kecelakaan, cuaca juga tiba-tiba berkabut seperti ini?"
  },
  AvgDialog_18827_Content_49 = {
    Text = "Cahaya senter yang lemah tidak bisa menembus kabut air. Segala sesuatu di sekitarmu tampak samar-samar, bahkan gerbang besi di dekatmu pun sulit terlihat dengan jelas."
  },
  AvgDialog_18827_Content_5 = {
    Text = "Saya juga ingin melakukan hal lain, tetapi... tetapi saya merasa begitu tidak berguna, hanya mampu melakukan pekerjaan kasar seperti ini..."
  },
  AvgDialog_18827_Content_50 = {
    Text = "Sebuah bayangan melintas dengan cepat, membangunkan kabut putih yang sedang terlelap."
  },
  AvgDialog_18827_Content_51 = {
    Text = "Itu adalah…!"
  },
  AvgDialog_18827_Content_52 = {
    Text = "Pintu besi yang tertutup rapat mengeluarkan suara yang menusuk telinga. Kamu dan Ramona segera mengejarnya, namun yang terlihat hanyalah pintu besar yang terbuka lebar, serta jalan yang diselimuti kabut malam di luar pintu."
  },
  AvgDialog_18827_Content_53 = {
    Text = "Cepat kejar!"
  },
  AvgDialog_18827_Content_6 = {
    Text = "Lagi, siapa yang mengatakan bahwa kamu tidak berguna?"
  },
  AvgDialog_18827_Content_7 = {
    Text = "Anak ini sudah seperti ini sejak pertama kali datang ke Taring, tidak mau mendengarkan apapun yang dikatakan."
  },
  AvgDialog_18827_Content_8 = {
    Text = "Diana tersenyum saat menyerahkan nampan berisi peralatan teh dan hidangan kepada Aigis, lalu dengan santai menepuk kepala Jenkin."
  },
  AvgDialog_18827_Content_9 = {
    Text = "Jadi, bisakah kamu membuatnya tidak terlalu keras pada dirinya sendiri? Itu semua tergantung padamu, Jenkin kecil."
  },
  AvgDialog_18828_Content_1 = {
    Text = "Apakah kita benar-benar tidak akan menghentikannya? Jika itu orang dari \"Para Pematung\"…"
  },
  AvgDialog_18828_Content_2 = {
    Text = "Lihat situasinya dulu, kita bisa menyesuaikan nanti. Jika sampai mengusik ular di rerumputan, akan lebih sulit untuk menangkap mereka."
  },
  AvgDialog_18829_Content_1 = {
    Text = "Cepat turun!"
  },
  AvgDialog_18829_Content_10 = {
    Text = "Benarkah bisa? Juga terlalu serbaguna, kan?!"
  },
  AvgDialog_18829_Content_11 = {
    Text = "Bagaimanapun juga, kita harus mencobanya. Aku akan menekannya terlebih dahulu, tunggu perintahmu."
  },
  AvgDialog_18829_Content_12 = {
    Text = "Siap... ayo!"
  },
  AvgDialog_18829_Content_3 = {
    Text = "Mata pisaunya membelah udara, menggerakkan aliran angin di belakangmu. Ramona menggeser tubuhnya untuk menangkis cakaran dengan pedangnya, lalu mendorongmu dengan kuat ke arah tangga."
  },
  AvgDialog_18829_Content_5 = {
    Text = "Sarah yang dilanda kegilaan mengikuti kalian ke basement, pedangnya bertabrakan dengan lendir hitam yang bermutasi dan mengeras, menghasilkan suara gesekan logam yang menusuk telinga."
  },
  AvgDialog_18829_Content_6 = {
    Text = "Kamu berbalik dan dengan hati-hati mundur ke dalam ruangan bersama Ramona yang mengangkat pedang rapier."
  },
  AvgDialog_18829_Content_7 = {
    Text = "Erica! Pelarut spesial, perubahan abnormal yang cerdas, mempertahankan bentuk manusia kecuali kepala. Diduga bahwa fluktuasi Roh yang dipicu oleh emosi menyebabkan perubahan pelarutan ini. Solusi?"
  },
  AvgDialog_18829_Content_8 = {
    Text = "Mencari, harap tunggu sebentar."
  },
  AvgDialog_18829_Content_9 = {
    Text = "Selain menghilangkan Mutan, dapat mencoba memengaruhi Roh Mutan dan Mutan Khusus melalui Kunci Perak."
  },
  AvgDialog_18830_Content_1 = {
    Text = "Nyonya Sarah——Nyonya Sarah, bangunlah, lihatlah aku, Nyonya Sarah——"
  },
  AvgDialog_18830_Content_2 = {
    Text = [[
Anomali ini tampaknya dipicu oleh emosi yang sangat kuat, dan masih memiliki sebagian kecerdasan. 
 Saya belum pernah melihat manifestasi seperti ini sebelumnya, sepenuhnya berbeda dari anomali lainnya.]]
  },
  AvgDialog_18830_Content_3 = {
    Text = "Apa itu mutan, apa ini, apa-apaan!"
  },
  AvgDialog_18830_Content_4 = {
    Text = "Hati-hati, jangan biarkan dia melewati. Jika sampai bertemu dengan orang biasa, akan sangat buruk."
  },
  AvgDialog_18830_Content_5 = {
    Text = "Pergi ke basement sebelumnya, lihat apakah bisa menemukan cara untuk menenangkannya."
  },
  AvgDialog_18830_Content_6 = {
    Text = "Nyonya Sarah! Tolong, jangan berikan kerusakan pada Nyonya Sarah!"
  },
  AvgDialog_18830_Content_7 = {
    Text = "Jenkin, cepat bawa Aigis pergi!"
  },
  AvgDialog_18830_Content_8 = {
    Text = "Sialan, di saat genting tetap harus mengandalkan aku, Aigis! Cepat!"
  },
  AvgDialog_18830_Content_9 = {
    Text = "Nyonya Sarah——!"
  },
  AvgDialog_18831_Content_1 = {
    Text = "Bahaya laten"
  },
  AvgDialog_18831_Content_10 = {
    Text = "Jenkin, jangan takutkan aku, aku... aku takut. Bisakah kamu kembali? Atau, bisakah aku ikut denganmu? Jenkin——"
  },
  AvgDialog_18831_Content_11 = {
    Text = [[
Pintu tertutup tanpa suara, meninggalkan gadis dan tikus di dalam ruangan. 
 Aigis duduk terpaku di atas tempat tidur, tubuhnya gemetar tak terkendali.]]
  },
  AvgDialog_18831_Content_12 = {
    Text = "Kenapa, hari ini sudah ada seseorang, kenapa masih seperti ini, kenapa…!"
  },
  AvgDialog_18831_Content_13 = {
    Text = [[
Air mata mengalir di sepanjang pipi, entah sudah berapa kali malam ini membasahi sprei.
Di luar jendela, kabut perlahan menutupi bulan purnama, segalanya menjadi suram dan kabur.]]
  },
  AvgDialog_18831_Content_14 = {
    Text = "Apa yang harus kulakukan... Apa yang harus aku lakukan, apa yang harus kuberikan... agar bisa..."
  },
  AvgDialog_18831_Content_15 = {
    Text = [[
00:17, Lily's Taring 
 Kamar Tamu]]
  },
  AvgDialog_18831_Content_17 = {
    Text = "... apa ... suara ...?"
  },
  AvgDialog_18831_Content_18 = {
    Text = "Bagaimana aku bisa tertidur?"
  },
  AvgDialog_18831_Content_19 = {
    Text = "Saya ingat sepertinya sedang berbicara dengan Sarah, bagaimana bisa tertidur begitu saja…\nRamona, Ramona?"
  },
  AvgDialog_18831_Content_2 = {
    Text = [[
00:14, Lilyan Taring
Kamar Aigis]]
  },
  AvgDialog_18831_Content_20 = {
    Text = "Kamu tidak mendengar respons, hanya bisa bergerak perlahan dengan anggota tubuh yang terasa berat, berusaha keras untuk fokus mengamati sekeliling."
  },
  AvgDialog_18831_Content_21 = {
    Text = "Kunci pintu terlepas di samping, pintu sedikit terbuka, dan angin dingin malam menghembus masuk melalui celah pintu yang gelap."
  },
  AvgDialog_18831_Content_22 = {
    Text = "Sebuah bayangan hitam dengan cepat meluncur dari balik meja dan kursi, dalam sekejap sudah menyerang tepat di hadapanmu."
  },
  AvgDialog_18831_Content_24 = {Text = "!"},
  AvgDialog_18831_Content_25 = {
    Text = [[
Mata pisaunya yang tajam memantulkan cahaya dingin, dan sosokmu terpantul di bilahnya yang pendek. 
Refleks yang terbentuk dari pelatihan membuatmu segera menghindar ke samping, dan kamu bisa melihat jelas sosok orang yang datang.]]
  },
  AvgDialog_18831_Content_26 = {Text = "Jenkin?!"},
  AvgDialog_18831_Content_27 = {
    Text = "Mata gadis itu kosong tanpa warna, ekspresinya datar hingga hampir terlihat seperti orang yang kehilangan kesadaran. Dia tidak mendengar panggilanmu sama sekali, seolah-olah ia kehilangan kemampuan untuk membedakan sesuatu."
  },
  AvgDialog_18831_Content_28 = {
    Text = "Sementara itu, gerakannya sangat gesit. Mata pisaunya melukis busur dingin di udara, tanpa memberimu kesempatan untuk berpikir lebih lanjut, gadis itu kembali menyerangmu."
  },
  AvgDialog_18831_Content_29 = {
    Text = "Menghindar dengan segera"
  },
  AvgDialog_18831_Content_3 = {
    Text = [[
Cahaya bulan yang memenuhi ruangan tiba-tiba menjadi samar, seolah-olah terhalang oleh lapisan kabut.
Seseorang tiba-tiba bangkit dari tempat tidur, mengganggu ketenangan di seluruh ruangan.]]
  },
  AvgDialog_18831_Content_30 = {
    Text = "Ramona, bangun!"
  },
  AvgDialog_18831_Content_31 = {
    Text = "Kamu mundur ke sisi Ramona, lalu mengguncang bahunya dengan kuat."
  },
  AvgDialog_18831_Content_32 = {
    Text = "Bagaimana…? Ada apa?"
  },
  AvgDialog_18831_Content_33 = {
    Text = "Itu Jenkin, dia tiba-tiba menyerangku!"
  },
  AvgDialog_18831_Content_34 = {
    Text = "Bangun Ramona"
  },
  AvgDialog_18831_Content_35 = {
    Text = "Sial, kalau begini terus..."
  },
  AvgDialog_18831_Content_36 = {
    Text = "Kamu menutup kedua matamu dan berkonsentrasi, kunci perak di dadamu bercahaya redup."
  },
  AvgDialog_18831_Content_37 = {
    Text = "Hubungan yang dipertahankan melalui tautan roh, meskipun berada ribuan mil jauhnya, atau di antara dunia nyata dan kota-kota mimpi, akan tetap merespons panggilan."
  },
  AvgDialog_18831_Content_38 = {Text = "Ramona!"},
  AvgDialog_18831_Content_4 = {
    Text = "… Jenkin?"
  },
  AvgDialog_18831_Content_40 = {
    Text = "Bilah pedang beradu, Ramona menangkis pisau itu. Dia sedikit memiringkan kepalanya dan menggunakan sudut matanya untuk memastikan keselamatanmu."
  },
  AvgDialog_18831_Content_41 = {
    Text = "Kamu baik-baik saja?"
  },
  AvgDialog_18831_Content_42 = {
    Text = "Kamu bangun sangat tepat waktu."
  },
  AvgDialog_18831_Content_43 = {Text = "Jenkin?"},
  AvgDialog_18831_Content_44 = {
    Text = "Jenkin tidak merespons, hanya mengangkat belati sekali lagi."
  },
  AvgDialog_18831_Content_45 = {
    Text = "Sepertinya satu-satunya cara adalah menundukkannya lalu menginterogasinya. Pancing dia keluar!"
  },
  AvgDialog_18831_Content_5 = {
    Text = "Suara gesekan pakaian adalah satu-satunya respon. Aigis mengusap matanya yang memerah dan bengkak, lalu melihat Jenkin melompat dari tempat tidur dan berjalan menuju pintu."
  },
  AvgDialog_18831_Content_6 = {
    Text = "Cicit? Cicit cicit!"
  },
  AvgDialog_18831_Content_7 = {
    Text = "Jenkin, apakah kamu... apakah kamu akan ke toilet?"
  },
  AvgDialog_18831_Content_8 = {
    Text = "Sepertinya sama sekali tidak mendengar pertanyaan temannya dan suara cicit tegang dari tikus kawannya. Jenkin mengenakan tas di punggungnya, membuka pintu, dengan wajah tanpa ekspresi."
  },
  AvgDialog_18831_Content_9 = {
    Text = "Wajah Aigis langsung pucat."
  },
  AvgDialog_18832_Content_1 = {
    Text = "Di dalam kegelapan, terdapat sosok kecil berwarna putih yang sedang meringkuk."
  },
  AvgDialog_18832_Content_10 = {
    Text = [[
Menyerahlah, tutup matamu, serahkan semuanya padaku. 
Sarah, Mikro... semua orang di Taring kalian akan menjadi keindahan, menjadi abadi.]]
  },
  AvgDialog_18832_Content_100 = {
    Text = "Pita satin yang terikat di tangan terlepas dan tertiup angin, tubuh kecil gadis itu jatuh ke dalam kegelapan malam ini, menghilang selamanya dari langit malam ini."
  },
  AvgDialog_18832_Content_101 = {
    Text = "Gaun putih kosong bersama dengan lembaran kertas kotak yang berserakan secara lembut jatuh ke tangan Jenkin."
  },
  AvgDialog_18832_Content_102 = {
    Text = "Tak ada sedikit pun kehangatan yang tersisa."
  },
  AvgDialog_18832_Content_103 = {
    Text = "Ai... Aigis...?"
  },
  AvgDialog_18832_Content_104 = {
    Text = "Di atas kertas terdapat gambar kupu-kupu emas, tepi yang berkerut telah diratakan dan dilipat dengan hati-hati, bahkan masih membawa aroma manis permen."
  },
  AvgDialog_18832_Content_105 = {
    Text = "Bagaimana... bagaimana mungkin..."
  },
  AvgDialog_18832_Content_106 = {
    Text = "Pita merah tua jatuh ke tangan gadis itu bersamaan dengan bungkus permen. Pita itu menyentuh ujung jarinya dengan lembut, seperti sebuah penghiburan hangat yang diberikan oleh seseorang."
  },
  AvgDialog_18832_Content_107 = {
    Text = "Gadis itu berkedip, air mata yang mengaburkan pandangannya jatuh dari bulu matanya dan diam-diam ditampung oleh warna merah yang mencolok."
  },
  AvgDialog_18832_Content_108 = {Text = "Aigis…"},
  AvgDialog_18832_Content_11 = {
    Text = "Jangan, tidak bisa...! Tolong, jangan seperti ini, tidak boleh!"
  },
  AvgDialog_18832_Content_12 = {
    Text = "Tikus kecil itu temanmu, kan? Karena kamu sudah membantu mengumpulkan banyak bahan untukku, aku bisa memprioritaskan menjadikannya abadi dan membebaskannya dari penderitaan."
  },
  AvgDialog_18832_Content_13 = {
    Text = "Tidak bisa! Jangan berikan kerusakan pada mereka! Aku mohon! Aku bersedia melakukan apa saja, benar-benar apa saja!"
  },
  AvgDialog_18832_Content_14 = {
    Text = "Dulu, aku juga pernah memohon padanya seperti ini, tapi — kemudian aku mengerti idealismenya. \n Aku yakin kau juga akan mengerti aku, karena selain itu, apa lagi yang bisa kau lakukan?"
  },
  AvgDialog_18832_Content_15 = {Text = "Aku——"},
  AvgDialog_18832_Content_16 = {
    Text = "Memberontak? Rohmu hampir tidak bisa bertahan. Jika tidak demikian, aku juga tidak akan bisa mempengaruhi dirimu saat kamu sadar."
  },
  AvgDialog_18832_Content_17 = {
    Text = "Lebih baik menyerah saja, lalu kamu bisa membantu aku mengubah semua orang di sini menjadi bahan yang berharga."
  },
  AvgDialog_18832_Content_18 = {
    Text = "Bayangan raksasa membeku di kejauhan. Kamu dengan cepat mengeluarkan Kunci perak, mengabaikan nasihat dari Boneka dan Ramona, lalu melemparkannya ke udara."
  },
  AvgDialog_18832_Content_19 = {
    Text = "Kunci perak melayang di udara, memancarkan cahaya yang lembut. Kamu menutup mata dan tenggelam dalam kegelapan dingin."
  },
  AvgDialog_18832_Content_2 = {
    Text = "Paman Charlie memiliki seekor kucing tabby yang sangat ia sayangi. Suatu hari, kucing itu menghilang, dan dia mencarinya ke mana-mana…"
  },
  AvgDialog_18832_Content_20 = {
    Text = [[
Tak terhitung cahaya perak di sekitar memudar, hanya tersisa satu titik cahaya yang sangat redup melayang-layang di depanmu. 
 Kamu mendengarkan dengan saksama, seakan-akan mendengar bisikan seorang gadis.]]
  },
  AvgDialog_18832_Content_21 = {
    Text = [[
Saya ingin melindungi semua orang, melindungi Nona Sarah, melindungi Xiao Mike, melindungi Jenkin.
Saya tidak ingin mereka diubah menjadi patung lilin.]]
  },
  AvgDialog_18832_Content_22 = {
    Text = "Aku harus melindungi mereka, meskipun—meskipun harus membayar dengan segalanya——"
  },
  AvgDialog_18832_Content_23 = {
    Text = "Kamu berusaha keras untuk menyentuh titik kecil itu, Kunci perak bergetar, seperti sebuah respons."
  },
  AvgDialog_18832_Content_24 = {
    Text = "...Apa ini?"
  },
  AvgDialog_18832_Content_25 = {
    Text = "Gadis itu mengangkat wajahnya dan menemukan sebuah kunci kecil berwarna perak di depannya. Kunci itu berputar perlahan, seperti bintang yang memancarkan cahaya lembut namun menyilaukan."
  },
  AvgDialog_18832_Content_26 = {
    Text = [[
Dia berusaha keras menggerakkan lengannya, menopang tubuhnya di bawah. 
 Kegelapan menyelimuti dirinya dari segala arah, menekannya, mengikatnya di tempat, dan membuatnya tak bisa bergerak.]]
  },
  AvgDialog_18832_Content_27 = {
    Text = [[
Gadget spesial. Jangan bergerak, Aigis. Aku belum ingin kehilangan alat sebaik dirimu. 
 Jika kau terus seperti ini, kau tak akan pernah bertemu teman-temanmu lagi. Apakah kau tidak masalah dengan itu?]]
  },
  AvgDialog_18832_Content_28 = {
    Text = "Aku tidak mau mendengarkan... Aku tidak akan mendengarkannya lagi."
  },
  AvgDialog_18832_Content_29 = {
    Text = [[
Meskipun aku tidak bisa makan permen lagi, tidak bisa melihat semua orang di Taring, tidak bisa melihat Jenkin. 
Meskipun aku mati.]]
  },
  AvgDialog_18832_Content_3 = {
    Text = "Kalimat berikutnya, aku akan! Dia membuka lemari, lalu melihat ke bawah tempat tidur."
  },
  AvgDialog_18832_Content_30 = {
    Text = "Aku juga sama sekali tidak akan membiarkanmu memberikan kerusakan kepada mereka lagi, sama sekali tidak."
  },
  AvgDialog_18832_Content_31 = {
    Text = "Kunci perak berkedip dengan kuat, gadis itu tiba-tiba menopang tubuhnya, samar-samar mendengar suara sesuatu yang robek."
  },
  AvgDialog_18832_Content_32 = {
    Text = "Penutup mata perlahan melayang jatuh, warna yang bergerak menggantikan kegelapan. Sebuah pupil pucat raksasa muncul di bawahnya, seakan telah mengamati dia untuk waktu yang lama."
  },
  AvgDialog_18832_Content_33 = {
    Text = "Apakah kamu... mata?"
  },
  AvgDialog_18832_Content_34 = {
    Text = "Apakah benar kekuatan bisa dipinjamkan padaku? \n …… Tidak apa-apa, meski hanya sebentar, aku… ada yang ingin aku katakan kepada mereka."
  },
  AvgDialog_18832_Content_35 = {
    Text = "Terima kasih."
  },
  AvgDialog_18832_Content_36 = {
    Text = "Aigis bergerak sedikit dan benar-benar membuka matanya."
  },
  AvgDialog_18832_Content_37 = {
    Text = "Setelah terdengar jeritan melengkung yang menyayat, tubuh raksasa monster itu meleleh menjadi cairan hitam kental, kemudian runtuh ke bawah. Cairan tersebut berubah menjadi debu dan melayang ke atas, menghitamkan balok kayu di langit-langit."
  },
  AvgDialog_18832_Content_38 = {
    Text = "Kamu terjatuh lemas di tanah, menahan rasa sakit yang berdenyut-denyut di kepala serta mual yang menyusul."
  },
  AvgDialog_18832_Content_39 = {Text = "%player%!"},
  AvgDialog_18832_Content_4 = {
    Text = "Aigis, lihat apa yang sudah kubuat untukmu? Penutup mata ini lebih bagus daripada yang sebelumnya, kan?"
  },
  AvgDialog_18832_Content_40 = {
    Text = [[
Kekuatan rohmu pasti terkuras habis, kan? Sudah kubilang jangan bertindak sembarangan. 
Tugas lapangan tidak seperti di sekolah. Jika terjadi sesuatu padamu, tidak akan ada yang membantu menyelesaikan masalahmu.]]
  },
  AvgDialog_18832_Content_41 = {
    Text = "Lupakan aku, cepat pergi dan lihat Aigis."
  },
  AvgDialog_18832_Content_42 = {
    Text = [[
Suara seperti penguapan cairan secara bertahap melemah, dan tak lama kemudian sepenuhnya menghilang. 
 Di lantai yang terkena cairan hitam kental, seorang gadis duduk dalam keheningan.]]
  },
  AvgDialog_18832_Content_43 = {
    Text = "Nyonya Ramona… dan… %player%. \n Syukurlah kalian baik-baik saja."
  },
  AvgDialog_18832_Content_44 = {
    Text = "Maaf, sungguh maaf. Jika aku mengatakannya lebih awal, mengakuinya lebih cepat, mungkin semuanya sudah berakhir lebih dulu."
  },
  AvgDialog_18832_Content_45 = {
    Text = "Saya tidak menyakiti orang lain, kan? Saya…… saya juga bisa dianggap berhasil melawan, kan?"
  },
  AvgDialog_18832_Content_46 = {
    Text = "Ya, kamu sangat berani dan hebat. Kamu telah melindungi semua orang di Taring."
  },
  AvgDialog_18832_Content_47 = {
    Text = [[
Kalau begitu... kalau begitu, tinggal satu hal lagi. 
Aku akan memberitahumu semua yang aku ketahui.]]
  },
  AvgDialog_18832_Content_48 = {
    Text = "<Small:Aku harus... mengejar waktu...>"
  },
  AvgDialog_18832_Content_49 = {
    Text = [[
Entah sejak kapan, suara misterius itu mulai datang. 
 Suara itu selalu datang pada malam yang berkabut tebal, merasuk ke dalam pikiran kami dan mengendalikan kami untuk melakukan hal-hal buruk.]]
  },
  AvgDialog_18832_Content_5 = {
    Text = "Aigis, Aigis! Hari ini cerah, pasti bisa melihat bintang-bintang, lho!"
  },
  AvgDialog_18832_Content_50 = {
    Text = "Suatu malam, saat saya bangun untuk pergi ke toilet, saya melihat Lucy sedang memegang pisau. Saya mengamati dia menyembunyikan pisaunya di lemari, lalu langsung naik ke tempat tidur dan tidur."
  },
  AvgDialog_18832_Content_51 = {
    Text = "Karena takut dia dimarahi karena piyama kotor, aku membantunya mengganti pakaian dan seprai. Dia terbangun olehku dan bertanya kenapa aku menggantinya, seolah-olah... dia sama sekali tidak tahu apa yang telah dilakukannya."
  },
  AvgDialog_18832_Content_52 = {
    Text = "Saya sangat takut, ingin memberi tahu Nyonya Sarah, tapi takut Nyonya Sarah menghukum Lucy. Lebih takut lagi Nyonya Sarah tidak percaya pada saya…"
  },
  AvgDialog_18832_Content_53 = {
    Text = "Jadi, pada akhirnya aku tidak mengatakan apa pun."
  },
  AvgDialog_18832_Content_54 = {
    Text = "Beberapa hari setelah kejadian dengan Lucy, tidak ada masalah di malam hari. Aku pikir semuanya sudah baik-baik saja, tapi suatu hari aku bangun dan menemukan diriku memegang sebuah pisau."
  },
  AvgDialog_18832_Content_55 = {
    Text = "Seorang kakak perempuan jatuh terduduk di depan saya. Dia menangis dan memohon belas kasihan. Saya ingin berhenti, tapi..."
  },
  AvgDialog_18832_Content_56 = {
    Text = "Aku tidak bisa."
  },
  AvgDialog_18832_Content_57 = {
    Text = "Selama suara itu bernyanyi, aku tidak bisa melakukannya."
  },
  AvgDialog_18832_Content_58 = {
    Text = "Suara menemukan bahwa saya masih \"terjaga\", sangat senang. Ia mengatakan bahwa saya berbakat, meminta saya untuk patuh. Jika tidak, ia akan mengubah semua orang menjadi batu dan menjadikan mereka sebagai \"bahan\"-nya."
  },
  AvgDialog_18832_Content_59 = {
    Text = "Saya berkata bahwa saya ingin memberi tahu Nyonya Sarah, tetapi dia tertawa dan berkata bahwa saya bisa mencobanya, melihat apakah ada orang yang akan mempercayainya."
  },
  AvgDialog_18832_Content_6 = {
    Text = "Aigis, sesekali bersikap manja juga tidak masalah, lho. Mengerti?"
  },
  AvgDialog_18832_Content_60 = {
    Text = "Suara itu selalu benar, terutama dalam hal-hal buruk."
  },
  AvgDialog_18832_Content_61 = {
    Text = "Tidak ada yang mempercayaiku, tidak ada yang ingat apa yang terjadi pada malam itu. Dan setiap malam berkabut, setiap kali lagu itu terngiang di kepala kita, akan ada anak-anak yang dikendalikan oleh suara itu, meninggalkan Taring."
  },
  AvgDialog_18832_Content_62 = {
    Text = "Setiap anak yang kembali berlumuran darah, dan setiap anak yang dikendalikan adalah \"pemutilasi\". \n Beberapa dari mereka lebih muda dariku. Jika mereka benar-benar ditangkap oleh polisi…"
  },
  AvgDialog_18832_Content_63 = {
    Text = "Saya tidak bisa membiarkan hal semacam itu terjadi."
  },
  AvgDialog_18832_Content_64 = {
    Text = "Jadi, aku menyembunyikan semua barang yang berlumuran darah di halaman belakang. Aku tidak bisa melawan suara itu, setidaknya aku bisa melindungi mereka agar tidak dibawa pergi oleh polisi."
  },
  AvgDialog_18832_Content_65 = {
    Text = "Aku tidak tahu mengapa suara itu meminta kita memotong tubuh orang lain. Aku hanya tahu bahwa semua bagian yang dipotong harus dikirim ke depan pintu sebuah rumah dengan jendela di area barat."
  },
  AvgDialog_18832_Content_66 = {
    Text = "Kakak perempuan Jenkin… juga aku bawa ke sana, sebuah rumah dengan papan nama <Blue:44> tergantung di pintu."
  },
  AvgDialog_18832_Content_67 = {
    Text = [[
Ketika saya pergi, dia masih menangis. Saya ingin menghiburnya, tetapi hanya bisa dikendalikan untuk kembali ke Taring. 
 Meskipun begitu, begitu saya bisa bergerak lagi, saya langsung keluar mencarinya. Namun, ketika saya sampai di sana, dia sudah tidak ada.]]
  },
  AvgDialog_18832_Content_68 = {
    Text = "Bersama dengan dia yang menghilang, ada juga kakak laki-laki yang kujadikan batu pada malam itu."
  },
  AvgDialog_18832_Content_69 = {
    Text = "Saya tidak tahu apakah mereka masih hidup. Jika kalian bisa menemukan mereka, bisakah kalian membantu saya meminta maaf kepada mereka?"
  },
  AvgDialog_18832_Content_7 = {
    Text = "Aigis! Cang-cang——roti! Hebat, kan?"
  },
  AvgDialog_18832_Content_70 = {
    Text = [[
Jika bukan karena saya, mereka tidak akan... Jenkin juga tidak akan begitu sedih. 
 Saya... saya benar-benar minta maaf padanya, maaf pada mereka, maaf pada semua orang.]]
  },
  AvgDialog_18832_Content_71 = {Text = "Aigis…"},
  AvgDialog_18832_Content_73 = {
    Text = "Aigis memandang bayangan yang jatuh di depan tubuhnya, matanya berkilauan dengan cahaya redup."
  },
  AvgDialog_18832_Content_74 = {
    Text = "Aku sangat ingin, sangat ingin mengulang semuanya… kalau begitu, aku pasti…"
  },
  AvgDialog_18832_Content_76 = {
    Text = "Pandangan yang buram akhirnya menjadi jelas. Dia menatap jalan-jalan yang tampak akrab atau asing, dan dalam keadaan bingung, seolah-olah terdengar bisikan seseorang di telinganya."
  },
  AvgDialog_18832_Content_77 = {
    Text = "Gadis itu berkedip dan menampilkan senyuman penuh kerinduan."
  },
  AvgDialog_18832_Content_78 = {
    Text = "Apakah kamu tahu? Dulu, setiap kali matahari terlihat, Tiyouge akan diam-diam membawaku ke sini pada malam hari."
  },
  AvgDialog_18832_Content_79 = {
    Text = "Nyonya Sarah tidak pernah mengizinkan kami datang ke sini. Dia bilang tempat ini terlalu berbahaya, dan kami bisa dengan mudah terluka."
  },
  AvgDialog_18832_Content_8 = {
    Text = [[
Gadis itu bergemetar sejenak dan memeluk erat boneka beruang di pelukannya. 
 Bungkus permen yang tersembunyi di dalamnya dilipat dengan rapi, masih mengeluarkan aroma manis permen.]]
  },
  AvgDialog_18832_Content_80 = {
    Text = "Tapi Tiyug tidak peduli dengan semua itu. Setiap malam setelah lampu dimatikan, setelah Nyonya Sarah selesai berkeliling memeriksa kamar, dia diam-diam membawa saya naik ke sini dalam gelap."
  },
  AvgDialog_18832_Content_81 = {
    Text = "Dia sama seperti Jenkin, cerdik dan berani, selalu mengetahui jalan-jalan kecil dan mekanisme yang tidak diketahui oleh orang lain."
  },
  AvgDialog_18832_Content_82 = {
    Text = "Selama dia yang membawa, kita tidak akan ditemukan oleh Nona Sarah."
  },
  AvgDialog_18832_Content_83 = {
    Text = "Selama dia membawa, tempat ini akan selalu menjadi basis rahasia kita."
  },
  AvgDialog_18832_Content_84 = {
    Text = "Dia adalah satu-satunya orang yang percaya padaku. Dia percaya bahwa aku bisa melihat hal-hal hitam itu dan mengatakan bahwa itu adalah bakat penyihir."
  },
  AvgDialog_18832_Content_85 = {
    Text = [[
Dia berkata bahwa semakin sering berinteraksi dengan bintang, kekuatan sihir akan semakin kuat, dan pada hari matahari bersinar terang, malam harinya akan ada bintang. 
Namun, hanya melihat bintang saja tidak ada manfaatnya.]]
  },
  AvgDialog_18832_Content_86 = {
    Text = "Aku bukan penyihir."
  },
  AvgDialog_18832_Content_87 = {
    Text = "Saya hanyalah seorang pengecut."
  },
  AvgDialog_18832_Content_88 = {
    Text = "Seorang sampah yang tidak berguna."
  },
  AvgDialog_18832_Content_89 = {
    Text = "Seorang... pembunuh."
  },
  AvgDialog_18832_Content_9 = {Text = "Jenkin…"},
  AvgDialog_18832_Content_90 = {
    Text = "Saya tidak bisa menghentikan Doktor, juga tidak bisa menghentikan suara misterius itu. Saya tahu jika terus seperti ini, akan lebih banyak orang yang mati, namun saya tak bisa berbuat apa-apa."
  },
  AvgDialog_18832_Content_91 = {
    Text = "Aku takut semua orang terluka, takut semua orang ditangkap, tapi sebenarnya yang paling aku takuti adalah... yang paling aku takuti…"
  },
  AvgDialog_18832_Content_93 = {
    Text = "Dokter Clemantine benar, dengan mempertaruhkan hidup, pasti ada sesuatu yang bisa diraih. \nDulu aku tidak berani, sekarang——"
  },
  AvgDialog_18832_Content_95 = {
    Text = "Sialan, katanya tunggu di kamar, tapi mereka semua entah ke mana pergi."
  },
  AvgDialog_18832_Content_96 = {
    Text = "Itu adalah..."
  },
  AvgDialog_18832_Content_97 = {
    Text = "Aigis?! Aigis—!"
  },
  AvgDialog_18832_Content_98 = {
    Text = "Dari bawah menara lonceng, tiba-tiba terdengar suara Jenkin. Dia berteriak dengan cemas memanggil nama Aigis, sambil membentangkan kedua tangannya ke arah langit."
  },
  AvgDialog_18832_Content_99 = {
    Text = "Seekor burung terbang melintasi langit malam, hilang dalam kabut tebal, tanpa meninggalkan jejak."
  },
  AvgDialog_18833_Content_1 = {
    Text = [[
Aigis terhuyung-huyung, namun kecepatannya tidak berkurang sedikit pun.
Dia memegang kepalanya sambil menahan erangan kesakitan, lalu terus berlari ke depan tanpa memedulikan apa pun.]]
  },
  AvgDialog_18833_Content_2 = {Text = "Aigis!"},
  AvgDialog_18833_Content_3 = {
    Text = "Gadis itu dengan cepat melintasi koridor dan langsung menaiki tangga menuju puncak menara jam, sambil terus bergumam sesuatu."
  },
  AvgDialog_18833_Content_4 = {
    Text = "Kalian mengejarnya sambil mendaki ke atas. Tangga spiral berputar satu lingkaran demi satu lingkaran, dan udara dipenuhi dengan aroma kayu dan debu."
  },
  AvgDialog_18833_Content_5 = {
    Text = "Aku tidak ingin memberikan kerusakan kepada mereka, tolong…"
  },
  AvgDialog_18833_Content_6 = {
    Text = "Aku tidak mau... Aku tidak ingin melakukannya, jangan bicara lagi, jangan bicara lagi...!"
  },
  AvgDialog_18834_Content_1 = {
    Text = "Kamu dan Ramona menembus ke kiri dan kanan, sudah lama kehilangan jejak anak berjubah itu. Anak-anak itu tetap gigih, masih menghalangi di depan kalian."
  },
  AvgDialog_18834_Content_2 = {
    Text = "Kalian... apakah kalian... satu kelompok!"
  },
  AvgDialog_18834_Content_3 = {Text = "Lalu apa!"},
  AvgDialog_18834_Content_4 = {
    Text = "Berani sekali kalian! Pukullah kami kalau kalian berani!"
  },
  AvgDialog_18834_Content_5 = {
    Text = "Kekerasan seperti itu tidak bisa dilakukan pada anak-anak. Namun——"
  },
  AvgDialog_18834_Content_6 = {
    Text = "Pendidikan yang tepat masih sangat diperlukan, bagaimana menurut kalian?"
  },
  AvgDialog_18835_Content_1 = {
    Text = "Ketika kalian mendekati Taring, jalan tiba-tiba menjadi sunyi. Hanya ada seorang gelandangan duduk lesu di pinggir jalan."
  },
  AvgDialog_18835_Content_2 = {
    Text = "Kenapa di sini begitu sunyi. Ada perasaan yang tidak enak."
  },
  AvgDialog_18835_Content_3 = {
    Text = "Kalau begitu, kita harus berhati-hati, Pelarutan——"
  },
  AvgDialog_18835_Content_4 = {
    Text = "Dia belum selesai berbicara, ketika tubuh gelandangan itu tiba-tiba berubah bentuk. Cairan kental yang memancar dari dadanya berkumpul menjadi monster hitam raksasa, merayap mendekati kalian."
  },
  AvgDialog_18836_Content_1 = {
    Text = "Monster hitam pekat itu tercerai lalu dengan cepat menyatu kembali. Ia mengangkat tubuhnya, dan dari bagian atasnya tiba-tiba terbelah, memuntahkan suara serak yang menusuk telinga."
  },
  AvgDialog_18836_Content_2 = {
    Text = "... tolong ...@4... tolong ..."
  },
  AvgDialog_18836_Content_3 = {
    Text = "Itu, itu berbicara...?"
  },
  AvgDialog_18836_Content_4 = {
    Text = "Jangan bersuara!"
  },
  AvgDialog_18836_Content_5 = {
    Text = "Sasha...@2...mati...mati...!"
  },
  AvgDialog_18836_Content_6 = {Text = "!"},
  AvgDialog_18837_Content_1 = {
    Text = "Kalian belum berlari jauh, anak-anak yang tadinya sedang bermain dengan cepat berkumpul di depan kalian dan menghalangi jalan."
  },
  AvgDialog_18837_Content_2 = {
    Text = "Minggir sebentar, minggir... Anak-anak, tolong minggir sebentar."
  },
  AvgDialog_18837_Content_3 = {
    Text = "Hmph hmph hmph——kalau punya nyali, coba saja lompati!"
  },
  AvgDialog_18837_Content_4 = {
    Text = "Kamu memandang Ramona dengan penuh harapan."
  },
  AvgDialog_18837_Content_5 = {
    Text = "Baiklah, kamu harus mengikuti dengan baik, ya."
  },
  AvgDialog_18838_Content_1 = {
    Text = "Cepat tinggalkan tempat ini, pasien sudah gila dan sedang memukul orang!"
  },
  AvgDialog_18838_Content_2 = {
    Text = "Bukankah mereka sudah gila sejak awal—Ya Tuhan! Kenapa semuanya keluar!"
  },
  AvgDialog_18838_Content_3 = {
    Text = "Kau kira aku menipumu? Cepat lari!"
  },
  AvgDialog_18839_Content_1 = {
    Text = [[
Ternyata kalian tidak semudah yang dibayangkan. Anak-anak itu berlarian ke segala arah.
Kamu dan Ramona berhasil menangkap salah satu dari mereka.]]
  },
  AvgDialog_18839_Content_2 = {
    Text = "Aduh, aku bilang, aku bilang, apa tidak bisa! Orang yang mencuri barang kalian pergi ke Taring, cari di sana, cari di sana."
  },
  AvgDialog_18839_Content_3 = {
    Text = "... Bagaimana bisa terasa terlalu kebetulan? Apakah kalian suka bermain di sekitar Taring?"
  },
  AvgDialog_18839_Content_4 = {
    Text = "Aku tidak berani. Mereka bilang ada iblis pemakan manusia di sana, hanya orang bodoh yang akan pergi ke sana untuk bermain."
  },
  AvgDialog_18839_Content_5 = {
    Text = "Kalau begitu, teman kalian yang memakai tudung itu juga tidak akan pergi ke sana, kan?"
  },
  AvgDialog_18839_Content_6 = {
    Text = "Aku, aku tidak berbohong! Aku—pada intinya, kalian bisa percaya atau tidak, terserah kalian!"
  },
  AvgDialog_18839_Content_7 = {
    Text = "Anak itu selesai berbicara lalu langsung berlari pergi. Kamu memandang bayangannya yang semakin menjauh, dan menghela napas."
  },
  AvgDialog_18839_Content_8 = {
    Text = "Yah, tugas yang penting. Mari kita pergi ke Taring."
  },
  AvgDialog_18840_Content_1 = {
    Text = "Apa, apa ini!?"
  },
  AvgDialog_18840_Content_2 = {
    Text = "Anak-anak, cepat kemari!"
  },
  AvgDialog_18840_Content_3 = {
    Text = "Sarah menarik satu anak di masing-masing tangannya saat ia mundur dengan panik. Seluruh tubuhnya gemetar hebat karena ketakutan, namun ia tetap bertahan di depan anak-anak itu dan menutupi mata mereka dengan tangannya."
  },
  AvgDialog_18840_Content_4 = {Text = "Mundur!"},
  AvgDialog_18840_Content_5 = {
    Text = "%player% berhati-hati!"
  },
  AvgDialog_18841_Content_1 = {
    Text = "Sehari satu apel"
  },
  AvgDialog_18841_Content_10 = {
    Text = [[
08:16, Lily Taring 
 Kafetaria]]
  },
  AvgDialog_18841_Content_11 = {
    Text = "Tapi, aku tidak bangun malam itu? Aigis, kenapa kamu terus bertanya padaku tentang ini? Semalam aku hanya tidur, tidak melakukan apa-apa."
  },
  AvgDialog_18841_Content_12 = {Text = "Aku..."},
  AvgDialog_18841_Content_13 = {
    Text = "Benar. Kenapa, Aigis?"
  },
  AvgDialog_18841_Content_14 = {
    Text = [[
Kamu terus-menerus bertanya seperti ini, bahkan ketika kami mengatakan tidak tahu, kamu tetap bertanya. Mengapa? 
 Apakah kamu tahu apa yang kami lakukan semalam?]]
  },
  AvgDialog_18841_Content_15 = {
    Text = "Aku tidak, aku, bagaimana mungkin aku——"
  },
  AvgDialog_18841_Content_16 = {
    Text = "Kamu adalah temanku, Aigis. Aku tidak ingin terus-menerus menebak-nebak seperti ini kepada seorang teman. Katakan saja padaku, apa sebenarnya yang kamu ketahui?"
  },
  AvgDialog_18841_Content_17 = {
    Text = "… Jenkin, aku… aku tidak mengerti…"
  },
  AvgDialog_18841_Content_18 = {
    Text = "Saya sudah ingin bertanya padamu sejak kemarin, ini, apa yang terjadi?"
  },
  AvgDialog_18841_Content_19 = {Text = "!"},
  AvgDialog_18841_Content_2 = {Text = "Hari Kedua"},
  AvgDialog_18841_Content_20 = {
    Text = "Aku sebenarnya sedang berpikir, mungkin kamu secara kebetulan menemukan sepotong pita di suatu tempat dan menyimpannya karena merasa itu indah."
  },
  AvgDialog_18841_Content_21 = {
    Text = [[
Namun, setelah melihat separuh bagian di tangan %player%, mengapa kamu tidak berkata apa-apa? 
 Kedua benda ini jelas merupakan bagian dari yang sama.]]
  },
  AvgDialog_18841_Content_22 = {
    Text = [[
Anak-anak lain di meja tidak memperhatikan percakapan mereka, masih tertawa dan bermain. 
 Aigis menundukkan kepalanya, bahunya yang terangkat bergetar pelan.]]
  },
  AvgDialog_18841_Content_23 = {
    Text = "Bisakah kamu memberitahuku di mana ini ditemukan? Di mana kakak perempuanku? \n Yang lainnya tidak penting, hanya ini ——"
  },
  AvgDialog_18841_Content_24 = {
    Text = [[
Alasan pahit atau apa pun itu, aku bisa memahaminya. Tapi kau harus bicara, Aigis. 
 Di mana kakakku menghilang? Beritahu aku, oke?]]
  },
  AvgDialog_18841_Content_25 = {
    Text = [[
Saya tidak bisa... maafkan saya... saya benar-benar tidak tahu, sungguh saya tidak tahu... 
Jenkin, Jenkin, aku rela melakukan apa saja, tolong jangan pergi, jangan berhenti menjadi temanku...]]
  },
  AvgDialog_18841_Content_26 = {
    Text = "Apa yang sebenarnya kamu maksud?"
  },
  AvgDialog_18841_Content_27 = {
    Text = "Berkumpul! Anak-anak, para pekerja, silakan datang ke halaman! Bariskan diri —"
  },
  AvgDialog_18841_Content_28 = {
    Text = [[
08:16, Lily Taring 
 Kafetaria]]
  },
  AvgDialog_18841_Content_29 = {
    Text = [[
Maaf, kemarin saya ingin menyembunyikan keberadaan para pasien, jadi terus mengatakan bahwa Anda salah lihat, Nona Mary. 
Lagipula, di sebuah Taring normal pasti tidak akan ada peneliti seperti itu.]]
  },
  AvgDialog_18841_Content_3 = {
    Text = [[
08:15, Lily's Taring 
 Kafetaria]]
  },
  AvgDialog_18841_Content_30 = {
    Text = [[
Ngomong-ngomong, di mana peneliti itu? Kenapa aku tidak melihatnya? 
 Aku dan Ash {Male=tuan,Female=nona} masih ingin bertanya kepadanya tentang terapi eksperimental.]]
  },
  AvgDialog_18841_Content_31 = {
    Text = [[
Mungkin mereka kembali ke institut penelitian. Mereka harus melapor setiap beberapa waktu sekali. 
 Aku tidak tahu detailnya.]]
  },
  AvgDialog_18841_Content_32 = {
    Text = "Kalau begitu, bisakah kamu memberikan alamat mereka kepadaku?"
  },
  AvgDialog_18841_Content_33 = {
    Text = "Hmm… aku juga tidak terlalu tahu alamatnya. Tapi hari ini adalah hari Dr. Miller datang untuk memeriksa pasien, mungkin kalian bisa langsung bertanya kepadanya? Waktunya hampir tepat — ah, lihat, mereka sudah datang."
  },
  AvgDialog_18841_Content_34 = {
    Text = "Kamu melihat ke arah Sarah yang sedang menyapa: Rogers dan beberapa orang berjas, membawa tas medis, sedang berjalan ke arah kalian. Clementine tidak berada di antara mereka."
  },
  AvgDialog_18841_Content_35 = {
    Text = "Dokter Miller, dan Tuan Rogers! Saya dan Ash{Male=tuan,Female=nona} sedang membicarakan kalian."
  },
  AvgDialog_18841_Content_36 = {
    Text = [[
Apakah tamu yang terhormat menyebut saya? Itu adalah kehormatan saya.
Halo, Esh{Male=tuan,Female=nona}, Nona Mary. Tuan Rogers baru saja memperkenalkan kalian kepada saya.]]
  },
  AvgDialog_18841_Content_37 = {
    Text = "Senang bertemu denganmu."
  },
  AvgDialog_18841_Content_38 = {
    Text = "Jujur saja, saya dan {Male=tuan,Female=nona} sangat penasaran dengan terapi eksperimental kalian. Apakah kami bisa mengamati proses sembuh kalian nanti?"
  },
  AvgDialog_18841_Content_39 = {
    Text = "Sungguh tidak beruntung. Kami baru-baru ini mengatur pengobatan dalam lembaga penelitian, mungkin tidak begitu nyaman."
  },
  AvgDialog_18841_Content_4 = {
    Text = "Kita harus segera bertindak, siapa yang tahu kapan Boneka akan memerintahkan kita untuk menarik diri."
  },
  AvgDialog_18841_Content_40 = {
    Text = "Mungkin kami bisa mengunjungi institut penelitian Anda? Jika Efek-nya memang seperti yang dikatakan oleh Nona Sarah dan Tuan Rogers, kami juga berharap dapat memberikan kontribusi dalam bentuk dana dan Kekuatan."
  },
  AvgDialog_18841_Content_41 = {
    Text = "Teman yang memiliki tujuan yang sama tentu semakin banyak semakin baik. Namun, penelitian kami saat ini sedang berada di tahap kritis, jadi tidak nyaman untuk menerima tamu. Apakah kalian berdua bisa memahaminya?"
  },
  AvgDialog_18841_Content_42 = {
    Text = [[
Atau, mungkin Anda bisa memberikan kartu nama Anda kepada mereka, Dr. Miller? 
 Dengan begitu, akan lebih mudah bagi kalian untuk berkomunikasi di masa depan.]]
  },
  AvgDialog_18841_Content_43 = {
    Text = [[
Tuan Rogers benar. 
Setelah kita menentukan waktu, kami pasti akan menjamu kalian berdua dengan baik.]]
  },
  AvgDialog_18841_Content_44 = {
    Text = "Dr. Miller memberikan kartu nama kepada kalian, di atasnya tertulis \"Frederick Miller, Jalan Salib No. 10\"."
  },
  AvgDialog_18841_Content_45 = {
    Text = "Nomor jalan dan nomor pintu yang terlalu rapi membuatmu tak bisa menahan diri untuk meragukan, apakah ada satu kalimat pun yang benar di kartu nama ini."
  },
  AvgDialog_18841_Content_46 = {
    Text = "Nona Sarah, tolong kumpulkan semua orang agar kami bisa menentukan siapa yang perlu diperiksa dan disembuhkan kali ini."
  },
  AvgDialog_18841_Content_47 = {
    Text = "Tidak masalah. \nKumpulkan! Anak-anak, para pekerja, silakan datang ke halaman! Berbarislah —"
  },
  AvgDialog_18841_Content_48 = {
    Text = "Kamu mengikuti Sarah dan Dr. Miller, lalu berjalan bersama ke halaman."
  },
  AvgDialog_18841_Content_5 = {
    Text = "Evakuasi? Apa yang dimaksud dengan evakuasi?"
  },
  AvgDialog_18841_Content_6 = {
    Text = "Oh, tidak ada apa-apa. Selamat pagi, Nona Sarah."
  },
  AvgDialog_18841_Content_7 = {
    Text = "Selamat pagi, Tuan atau Nyonya Ash{Male=tuan,Female=nona}, Nona Mary. \n Entah bagaimana kalian berdua beristirahat semalam… apakah kalian tidur dengan nyenyak?"
  },
  AvgDialog_18841_Content_8 = {
    Text = [[
Beruntung sekali bisa tidur dengan sangat nyenyak. 
Teh dari Nona Sarah benar-benar memiliki khasiat yang unik dan tidak ditemukan di tempat lain.]]
  },
  AvgDialog_18841_Content_9 = {
    Text = "Ya, ya. Itu sangat bagus."
  },
  AvgDialog_18842_Content_1 = {
    Text = "Kamu adalah pembunuhnya, kamu yang mengendalikanku, kamu… uh… aa…"
  },
  AvgDialog_18842_Content_2 = {
    Text = "Aigis, dengarkan aku. Kami punya cara untuk membantumu terbebas dari orang yang mencoba mengendalikanmu. Kamu tidak perlu seperti ini."
  },
  AvgDialog_18842_Content_3 = {
    Text = "Jangan mendekat... jangan... aaah...!"
  },
  AvgDialog_18843_Content_1 = {
    Text = "Di balik tembok batu"
  },
  AvgDialog_18843_Content_10 = {
    Text = "Aku tidak mau pergi, aku tidak mau. Aku sudah pergi sebelumnya, aku sudah pernah ke sana, aku tidak mau pergi lagi, aku tidak mau."
  },
  AvgDialog_18843_Content_11 = {
    Text = "Tapi belakangan ini kau sering mengatakan melihat hal hitam, bukan? Aku sudah bertanya pada Dr. Miller, dia bilang melihat ilusi bukanlah hal sepele, hari ini kita harus pergi memeriksanya lagi."
  },
  AvgDialog_18843_Content_12 = {
    Text = [[
Nona Sarah, tolong, jangan suruh aku pergi. 
Aku tidak melihatnya, benar-benar tidak melihatnya. Tolong.]]
  },
  AvgDialog_18843_Content_13 = {
    Text = "Bagaimana kalau kamu nanti menjadi seperti orang-orang gila itu? Tidak, kamu harus pergi. Dengarkan aku."
  },
  AvgDialog_18843_Content_14 = {
    Text = "Nyonya Sarah——"
  },
  AvgDialog_18843_Content_15 = {
    Text = "Anak inilah yang dipilih."
  },
  AvgDialog_18843_Content_16 = {
    Text = "Tidak... aku tidak mau pergi... Aku sudah pernah ke sana sekali, aku tidak mau..."
  },
  AvgDialog_18843_Content_17 = {
    Text = "Saya pergi saja, Tuan."
  },
  AvgDialog_18843_Content_18 = {Text = "!"},
  AvgDialog_18843_Content_19 = {
    Text = "...Apakah ada yang membuatmu merasa tidak nyaman?"
  },
  AvgDialog_18843_Content_2 = {
    Text = "Aku benar-benar melihatnya, sungguh! Yang hitam-hitam itu, berbentuk segitiga. Setiap orang yang pergi ke dokter akan memiliki lebih banyak hal seperti ini di tubuh mereka, sangat menakutkan, sangat menakutkan."
  },
  AvgDialog_18843_Content_20 = {
    Text = [[
Aku tidak merasa tidak enak, bisa berlari dan melompat, sehat-sehat saja! 
Namun, aku bisa melihat sesuatu.]]
  },
  AvgDialog_18843_Content_21 = {
    Text = "Oh? Apa yang bisa kamu lihat?"
  },
  AvgDialog_18843_Content_22 = {
    Text = [[
Sama seperti Aigis, saya juga melihat fatamorgana hitam. 
Bisakah kamu membantu saya?]]
  },
  AvgDialog_18843_Content_23 = {
    Text = "Menarik. Kalau begitu, hari ini kamu yang bertugas."
  },
  AvgDialog_18843_Content_24 = {Text = "Tiyug…"},
  AvgDialog_18843_Content_25 = {
    Text = "Jangan takut, Aigis."
  },
  AvgDialog_18843_Content_26 = {
    Text = "Saya akan segera kembali."
  },
  AvgDialog_18843_Content_27 = {
    Text = [[
09:00, Lily's Taring
Kamar Aigis]]
  },
  AvgDialog_18843_Content_28 = {
    Text = "Kalian duduk di dalam kamar Aigis, mendengarkan gadis itu berceritakan dengan terbata-bata."
  },
  AvgDialog_18843_Content_29 = {
    Text = [[
Orang-orang yang dibawa pergi oleh Dokter kembali dengan lubang hitam di tubuh mereka, semakin banyak, semakin banyak. 
 Namun, tidak ada yang bisa melihatnya, semua orang mengatakan bahwa aku pembohong.]]
  },
  AvgDialog_18843_Content_3 = {
    Text = "Hitam-hitam... apakah itu berarti pakaian kotor? Mungkin terkena sesuatu."
  },
  AvgDialog_18843_Content_30 = {
    Text = "Hanya Tiyug yang percaya padaku, hanya Tiyug. Tapi dia sudah meninggal…\nDia meninggal, itu semua salahku."
  },
  AvgDialog_18843_Content_31 = {
    Text = "Jika saja aku tidak membiarkannya menggantikanku untuk diperiksa saat itu, jika saja aku lebih kuat sedikit, jika saja aku bisa berbuat lebih banyak, dia tidak akan... tidak akan... aku benar-benar sampah..."
  },
  AvgDialog_18843_Content_32 = {
    Text = "Kamu tidak boleh berbicara seperti itu tentang dirimu sendiri, kamu bukan!"
  },
  AvgDialog_18843_Content_33 = {
    Text = "Aku, aku! Aku tidak bisa menyelamatkannya, tidak bisa menyelamatkan semuanya, aku benar-benar tidak bisa berbuat apa-apa! \nIbu memang benar, aku hanya beban, sampah kecil yang tak ada yang menginginkan, aku sama sekali tidak bisa melakukan apa pun…"
  },
  AvgDialog_18843_Content_34 = {
    Text = "Aku tidak tahu apa-apa..."
  },
  AvgDialog_18843_Content_35 = {Text = "Lalu apa!"},
  AvgDialog_18843_Content_36 = {
    Text = "Suara Jenkin menembus ruangan yang sempit, Aigis terpaku memandangnya."
  },
  AvgDialog_18843_Content_37 = {
    Text = [[
Bagaimana kalau tidak bisa menyelamatkan, lalu apa artinya penakut! Siapa yang mengatakan bahwa kamu harus menyelamatkan orang? 
Itu bukan tanggung jawabmu sejak awal!]]
  },
  AvgDialog_18843_Content_38 = {
    Text = "Namun, itu adalah semua orang…"
  },
  AvgDialog_18843_Content_39 = {
    Text = [[
Apa yang terjadi dengan kalian semua? Apakah sudah seharusnya kalian membiarkan seorang anak kecil menyelamatkan dunia? Mengapa? 
 Apakah kamu belum cukup berbuat banyak?]]
  },
  AvgDialog_18843_Content_4 = {
    Text = "Bukan! Mereka berlubang hitam, basah, dan bisa membuat tangan serta kaki seseorang menghilang!"
  },
  AvgDialog_18843_Content_40 = {
    Text = "Jenkin mengeluarkan sepotong pita yang tergulung menjadi bola dari sakunya dan meletakkannya di tangan Aigis. Warna cerahnya sama persis dengan yang ada di tanganmu."
  },
  AvgDialog_18843_Content_41 = {
    Text = [[
Kamu bukan pembohong, juga bukan sampah. Kamu adalah temanku. 
 Jika ada sesuatu yang tidak bisa kamu lakukan sendiri, kita bisa melakukannya bersama-sama.]]
  },
  AvgDialog_18843_Content_42 = {
    Text = "Saya percaya kamu, dan kamu juga harus percaya saya, oke?"
  },
  AvgDialog_18843_Content_43 = {
    Text = [[
Aigis menatap pita di tangannya, air mata jatuh satu per satu bergulir ke bawah. 
 Dia menggelengkan kepala dengan kuat, ekspresi menyakitkan itu muncul kembali di wajahnya.]]
  },
  AvgDialog_18843_Content_44 = {
    Text = "Aigis——"
  },
  AvgDialog_18843_Content_45 = {
    Text = "Jenkin, sudahlah. Aigis pasti memiliki pertimbangannya sendiri."
  },
  AvgDialog_18843_Content_46 = {
    Text = [[
Sekarang sepertinya, ruang perawatan itu adalah arah penyelidikan yang cukup bagus. 
Aigis, bisakah kamu sedikit lebih kuat dan membawa kami ke ruang perawatan?]]
  },
  AvgDialog_18843_Content_47 = {
    Text = "Cukup sampai di depan pintu saja. Jika kamu merasa tidak nyaman, kamu tidak perlu masuk."
  },
  AvgDialog_18843_Content_48 = {
    Text = "Aku mengerti, aku... aku akan membawa kalian ke sana."
  },
  AvgDialog_18843_Content_49 = {
    Text = [[
09:11, Lily Taring 
 Ruang Perawatan Sementara]]
  },
  AvgDialog_18843_Content_5 = {
    Text = "Kak Diana, jangan pergi, aku mohon. Jangan biarkan mereka memeriksamu. Kak Diana, Kak Diana!"
  },
  AvgDialog_18843_Content_50 = {
    Text = "Ruang di sini tidak terlalu besar, bisa dilihat sampai ke ujungnya. Selain beberapa meja dan kursi, hampir tidak ada apa-apa, bahkan tidak ditemukan satu arsip pun."
  },
  AvgDialog_18843_Content_51 = {
    Text = "Setelah kami dibawa masuk, kami semua diminta untuk meminum obat. Setelah meminumnya, kami langsung tertidur."
  },
  AvgDialog_18843_Content_52 = {
    Text = "Setelah tertidur, aku bermimpi pergi ke tempat yang sangat gelap dan dingin, tanpa jendela, hanya ada satu lampu besar yang sangat terang menyilaukan wajahku."
  },
  AvgDialog_18843_Content_53 = {
    Text = "Setelah bangun, akan ditemukan di tubuh... ada yang hitam-hitam..."
  },
  AvgDialog_18843_Content_54 = {
    Text = "Sangat gelap dan dingin, juga tidak ada jendela. Terdengar seperti ruang bawah tanah."
  },
  AvgDialog_18843_Content_55 = {
    Text = "Namun, pintu masuk ke basement Taring tidak berada di sini, dan di dalamnya penuh dengan barang-barang. Tidak seperti dalam mimpi."
  },
  AvgDialog_18843_Content_56 = {
    Text = "Apakah ini ruang tertutup?"
  },
  AvgDialog_18843_Content_57 = {
    Text = "Kamar tersembunyi, ya, aku ahli dalam hal ini. Brown!"
  },
  AvgDialog_18843_Content_58 = {Text = "Cit!"},
  AvgDialog_18843_Content_59 = {
    Text = [[
Tikus meluncur keluar dan menghilang di celah dinding. 
 Tak lama kemudian, terdengar suara tikus berderit dari balik dinding di depan kalian.]]
  },
  AvgDialog_18843_Content_6 = {
    Text = "Tidak ada benda hitam-hitam di sini, Aigis adalah pembohong besar! Pembohong besar, hidung panjang!"
  },
  AvgDialog_18843_Content_60 = {
    Text = "Di sana, ada tempat kosong!"
  },
  AvgDialog_18843_Content_61 = {
    Text = "Jenkin memukul-mukul secara sembarangan di sisi tembok. Saat menyadari apa yang dia lakukan, kamu juga maju dan ikut menekan dengan sadar pada dinding bata tersebut."
  },
  AvgDialog_18843_Content_62 = {
    Text = "Dinding tiba-tiba melesak di telapak tangan Ramona. Setelah terdengar suara 'klik' entah dari mana, dinding itu sedikit menonjol dan perlahan mulai terbuka ke arah luar."
  },
  AvgDialog_18843_Content_63 = {
    Text = "Seiring dengan melebarnya celah di antara batu bata, bau darah dan pembusukan menyembur keluar."
  },
  AvgDialog_18843_Content_64 = {
    Text = "Sebuah lorong yang gelap dan sempit, menuju ke bawah, muncul di hadapan kalian."
  },
  AvgDialog_18843_Content_7 = {
    Text = "Aku tidak berbohong, aku tidak. Aku benar-benar melihatnya!"
  },
  AvgDialog_18843_Content_8 = {
    Text = "Aku benar-benar melihatnya... Percayalah padaku..."
  },
  AvgDialog_18843_Content_9 = {
    Text = "Aigis, ayo. Ikut aku ke ruang perawatan."
  },
  AvgDialog_18844_Content_1 = {
    Text = "Apa yang sebenarnya terjadi pada anak itu?"
  },
  AvgDialog_18844_Content_2 = {
    Text = "Sepertinya dia sedang berbicara dengan seseorang yang tidak bisa kita lihat."
  },
  AvgDialog_18844_Content_3 = {
    Text = "Apakah dia, seperti Jenkin, juga dikendalikan oleh seseorang? Bagaimana hal itu bisa dilakukan?"
  },
  AvgDialog_18845_Content_1 = {
    Text = "Coba telusuri. Penyelidik lain mungkin akan merasa kesulitan saat melakukan Penyelidikan terhadap Pembangun yang tidak Bangun."
  },
  AvgDialog_18845_Content_2 = {
    Text = "Namun, jika itu adalah kamu — dengan tingkat kepekaanmu, kamu pasti bisa."
  },
  AvgDialog_18846_Content_1 = {
    Text = [[
Kamu menarik napas dalam-dalam, menutup kedua matamu, dan pandanganmu tenggelam dalam kegelapan.
Awalnya tidak ada apa-apa, hanya terdengar suara napasmu dan Ramona.]]
  },
  AvgDialog_18846_Content_2 = {
    Text = "Perlahan-lahan, kamu bisa mendengar butiran air halus di dalam kabut saling bertabrakan. Monster yang berubah menjadi lumpur terus-menerus terurai di belakangmu, dan debu hitam berjatuhan dengan lembut."
  },
  AvgDialog_18846_Content_3 = {
    Text = [[
Kunci perak berdengung. Kamu memperhatikan dengan cermat dan samar-samar mendengar melodi yang tersembunyi di bawahnya.
Melodi itu memiliki ritme yang ceria, seperti sebuah nyanyian, memanggil dengan lembut dari suatu tempat yang tidak jauh.]]
  },
  AvgDialog_18846_Content_4 = {
    Text = "\"Charlie yang tua memiliki seekor kucing tabby yang sangat dia cintai…\""
  },
  AvgDialog_18846_Content_5 = {Text = "Di sini!"},
  AvgDialog_18847_Content_1 = {
    Text = "Monster yang telah kalian hancurkan langsung ambruk menjadi genangan lumpur hitam. Kamu memandang sekeliling, namun yang terlihat hanyalah kabut putih yang tebal."
  },
  AvgDialog_18847_Content_2 = {
    Text = "Sialan, sama sekali tidak bisa melihat apa pun."
  },
  AvgDialog_18847_Content_3 = {
    Text = "Kacamata saya juga tidak bisa menampilkan banyak hal."
  },
  AvgDialog_18847_Content_4 = {
    Text = "Apa yang harus kita lakukan sekarang?"
  },
  AvgDialog_18847_Content_5 = {
    Text = "Jika ada cara untuk melacak tanpa menggunakan penglihatan, itu akan sangat membantu."
  },
  AvgDialog_18847_Content_6 = {
    Text = [[
Kata kunci berhasil dibaca, "Metode pelacakan tanpa menggunakan penglihatan", mencari...
Pencarian selesai, Penjaga dapat mempertimbangkan untuk melakukan penelusuran Roh.]]
  },
  AvgDialog_18847_Content_7 = {
    Text = "Bukankah itu yang digunakan oleh Penyelidik untuk melacak Pembangun yang hilang? Apakah itu juga berfungsi pada tubuh abnormal?"
  },
  AvgDialog_18847_Content_8 = {
    Text = [[
Prinsip penelusuran Roh adalah mendeteksi fluktuasi Roh yang berbeda dari orang biasa.
Dalam hal ini, Mutan sama dengan Pembangun.]]
  },
  AvgDialog_18847_Content_9 = {
    Text = "Namun——sebelum itu, selesaikan dulu yang ada di depan."
  },
  AvgDialog_18848_Content_1 = {
    Text = "Satu per satu mutan lenyap di bawah pedang Ramona, dan wajah Aigis tampak semakin pucat di tengah debu hitam yang melayang."
  },
  AvgDialog_18848_Content_2 = {
    Text = [[
Apa kalian masih ragu? Cepat tangkap aku. 
 Aku adalah pembunuhnya, bawa aku pergi, lalu... kembalikan Lucy kecil.]]
  },
  AvgDialog_18848_Content_3 = {
    Text = "Jika kamu ingin dia kembali, buktikan bahwa dia tidak bersalah dan beri tahu kami kebenarannya, bukan seperti sekarang ini. Ini bukan cara yang baik."
  },
  AvgDialog_18848_Content_4 = {
    Text = "Kamu tidak mengerti, kalian... kalian semua tidak mengerti... Hanya aku yang satu-satunya, pemburu sejati."
  },
  AvgDialog_18848_Content_5 = {
    Text = "Tubuhnya goyah, lalu dia menyerang kalian berdua."
  },
  AvgDialog_18849_Content_1 = {
    Text = [[
15:01, Londinium Timur 
 Bengkel Taring Lily]]
  },
  AvgDialog_18849_Content_10 = {
    Text = [[
Jenkin segera meraih pita itu dengan tangannya. 
 Aigis juga tampak sangat tegang, seakan-akan terbawa oleh emosinya.]]
  },
  AvgDialog_18849_Content_11 = {
    Text = "Kakak, ini... ini punya Kakak! Gesper yang aku pesan secara khusus, tidak mungkin salah."
  },
  AvgDialog_18849_Content_12 = {
    Text = "Wajahnya semakin pucat, kedua tangannya memegang pita itu seolah-olah memiliki berat seribu kilo. Jari-jarinya yang kaku seperti ingin mencengkeram erat, namun juga enggan merusaknya."
  },
  AvgDialog_18849_Content_13 = {
    Text = "Di mana dia? Apakah dia baik-baik saja? Apakah dia terluka? Apakah… apakah…"
  },
  AvgDialog_18849_Content_14 = {
    Text = "Cicit, cicit cicit."
  },
  AvgDialog_18849_Content_15 = {
    Text = "Ya, ya. Dia pasti menghilang, kan? Kalian juga tidak bisa menemukannya, kan?"
  },
  AvgDialog_18849_Content_16 = {
    Text = "Kami benar-benar tidak menemukan jejaknya."
  },
  AvgDialog_18849_Content_17 = {
    Text = "Jadi, masih ada harapan. Pita itu pasti tercabik, dia pasti berhasil melarikan diri, lalu bersembunyi di Taring. Pasti begitu."
  },
  AvgDialog_18849_Content_18 = {
    Text = "Kamu bisa melihat guncangan di dasar matanya. Namun, terkadang, dibandingkan dengan kebenaran yang kejam, keyakinan palsu lebih mampu menopang seseorang untuk maju."
  },
  AvgDialog_18849_Content_19 = {
    Text = "Aigis mengeluarkan beberapa permen yang dibungkus dengan rapi dari bawah kasur dan memberikannya kepada Jenkin."
  },
  AvgDialog_18849_Content_2 = {
    Text = "Kamu bilang <Blue:orang gila>, orang gila seperti apa?"
  },
  AvgDialog_18849_Content_20 = {
    Text = "Kami... kami akan menemukan kakakmu. Pasti..."
  },
  AvgDialog_18849_Content_21 = {
    Text = "Gadis itu berbisik pelan, suara penghiburannya perlahan memudar. Wajahnya tampak pucat, seolah-olah ia sedang mengalami penderitaan yang mendalam."
  },
  AvgDialog_18849_Content_22 = {
    Text = "%player%. Ada sesuatu di halaman depan, cepat datang."
  },
  AvgDialog_18849_Content_23 = {
    Text = "Kamu bergegas tiba dan melihat Ramona sedang bersama beberapa orang yang berpakaian berbeda dari pekerja lainnya, menggunakan tali untuk mengikat seorang pria."
  },
  AvgDialog_18849_Content_24 = {
    Text = "Pria itu memiliki bekas luka aneh di tubuhnya, sekilas terlihat seperti jejak jahitan yang terdistorsi. Di antara daging dan kulit yang belum sembuh, terdapat banyak cairan hitam pekat."
  },
  AvgDialog_18849_Content_25 = {
    Text = [[
Itu adalah <Yellow:D-marka>, tampaknya sudah berada pada <Yellow:tahap tengah Pelarutan>.
Kamu belum pernah melihat yang seperti ini.]]
  },
  AvgDialog_18849_Content_26 = {
    Text = [[
Lihat, itulah jenis orang gila yang kumaksud. 
 Lihat, mereka masih mengenakan pakaian kerja. Mungkin mereka baru saja kambuh, sangat menakutkan.]]
  },
  AvgDialog_18849_Content_27 = {
    Text = [[
Seseorang mengenakan pakaian putih tiba-tiba mengeluarkan sebuah jarum suntik entah dari mana. 
 Dia menusukkan jarum itu ke sisi leher pria tersebut, pria itu bergerak dua kali sebelum akhirnya menutup mata dan tidak bergerak lagi.]]
  },
  AvgDialog_18849_Content_28 = {
    Text = "Kamu menahan ekspresimu — obat biasa tidak mungkin bekerja pada individu yang telah mengalami pelarutan. Bagaimana orang ini bisa melakukannya?"
  },
  AvgDialog_18849_Content_29 = {
    Text = [[
Beberapa orang melihat pria itu kehilangan kesadaran, segera mengikatnya dengan kuat, memegang pundaknya, dan dengan cepat pergi.
Ramona ingin mengikuti mereka, tetapi Sarah menghalangi jalannya.]]
  },
  AvgDialog_18849_Content_3 = {
    Text = [[
Hmm, aku juga tidak bisa menjelaskan dengan baik. Orang-orang itu mungkin kemarin masih terlihat normal, tapi hari ini mereka tiba-tiba menjadi aneh dan tidak waras.
Mata dan hidung mereka bahkan bisa tiba-tiba menyatu, sangat menakutkan.]]
  },
  AvgDialog_18849_Content_30 = {
    Text = [[
Nona Mary, jangan pergi ke sana, biarkan mereka menangani saja. 
 Jika kamu terluka, bagaimana aku harus menjelaskan kepada Lord Ash {Male=tuan,Female=nona}?]]
  },
  AvgDialog_18849_Content_31 = {
    Text = "Tidak perlu memberi penjelasan."
  },
  AvgDialog_18849_Content_32 = {
    Text = "Ai, Ai Shi{Male=tuan,Female=nona}!"
  },
  AvgDialog_18849_Content_33 = {
    Text = "Meskipun <Yellow:Komite> memiliki kontrol ketat terhadap penelitian pelarutan di masyarakat, selalu ada satu atau dua orang dengan cara khusus. Orang berbaju putih itu bisa seketika menundukkan entitas abnormal, pasti tidak sederhana."
  },
  AvgDialog_18849_Content_34 = {
    Text = [[
Apakah dia mengetahui sesuatu tentang serangkaian acara di Distrik Timur?
Apakah dia terlibat dalam acara-acara ini?]]
  },
  AvgDialog_18849_Content_35 = {
    Text = "Apa yang terjadi barusan? Siapa orang berbaju putih itu di Taring?"
  },
  AvgDialog_18849_Content_36 = {
    Text = "Itu, itu hanya <Blue:Peneliti> ——"
  },
  AvgDialog_18849_Content_37 = {
    Text = [[
Saya harap Anda bisa bersikap terbuka kepada kami, Nona Sarah. 
 Saya juga tidak ingin melihat segala sesuatunya menjadi tak terkendali.]]
  },
  AvgDialog_18849_Content_38 = {
    Text = [[
Kamu menatap Sarah yang menghindari pandanganmu dengan ekspresi serius.
Tidak tahu apakah dia memahami maksudmu, Sarah menggigit bibirnya dan membuat sebuah keputusan.]]
  },
  AvgDialog_18849_Content_39 = {
    Text = "Baiklah. Jika Anda berkata begitu… mohon ikuti saya."
  },
  AvgDialog_18849_Content_4 = {
    Text = [[
Ngomong-ngomong, di Taring ini banyak rahasia. 
Hanya wanita itu saja sudah menyimpan banyak barang di kantornya.]]
  },
  AvgDialog_18849_Content_40 = {
    Text = [[
15:01, Lily Taring 
 Area Medis Sementara]]
  },
  AvgDialog_18849_Content_41 = {
    Text = "Puluhan tempat tidur diletakkan berdampingan di ruang makan yang sudah tidak terlalu luas. Semua pasien tanpa terkecuali memiliki tangan dan kaki terikat serta diikat pada tempat tidur."
  },
  AvgDialog_18849_Content_42 = {
    Text = "Perawat-perawat berpindah di antaranya, beberapa memegang kain kasar, siap untuk memperkuat ikatan pasien kapan saja."
  },
  AvgDialog_18849_Content_43 = {
    Text = "Di salah satu tempat tidur dekat jendela, seorang pria tua yang kurus membelalakkan matanya. Dari sudut matanya mengalir setetes cairan hitam dan kental."
  },
  AvgDialog_18849_Content_5 = {Text = "Cokelat."},
  AvgDialog_18849_Content_6 = {
    Text = [[
Cokelat keluar dari tas selempangnya, cakar depannya memegang dua cincin yang berkilauan. 
 Dari segi kerajinan dan bahan, meskipun tidak bernilai jutaan dolar, tetap tergolong mahal.]]
  },
  AvgDialog_18849_Content_7 = {
    Text = "Kamu teringat pada pita satin yang dihiasi gesper perak berbentuk persegi."
  },
  AvgDialog_18849_Content_8 = {
    Text = "Lalu, apakah kamu melihat sesuatu yang serupa dengan ini?"
  },
  AvgDialog_18849_Content_9 = {Text = "!"},
  AvgDialog_18850_Content_1 = {
    Text = "Monster yang terdistorsi hanya memiliki satu napas tersisa. Lumpur hitam yang membusuk bergerak dengan susah payah, sementara wajah-wajah yang terus muncul dan menghilang mengeluarkan suara yang membuat bulu roma merinding."
  },
  AvgDialog_18850_Content_10 = {
    Text = [[
Dia sudah... tidak bisa lagi, sepertinya hanya tersisa sedikit kesadaran. 
 Aku ingin berkomunikasi dengannya, ingin mendengar apa yang ingin dia katakan. Apakah ada cara?]]
  },
  AvgDialog_18850_Content_100 = {
    Text = [[
Bagi dia, hari ini pasti sangat sulit.
Dengan pemikiran itu, kamu mengikuti Ramona dan Jenkin, dan mendengar Aigis menyusul di belakangmu.]]
  },
  AvgDialog_18850_Content_11 = {
    Text = [[
...Di antara para Penyelidik biasa, belum ada preseden seperti ini. 
Namun, Guru Alistair pernah berhasil berkomunikasi dengan kesadaran sisa dari tubuh aneh menggunakan Kunci perak.]]
  },
  AvgDialog_18850_Content_12 = {
    Text = "Tak perlu banyak bicara, kamu mengeluarkan kunci perak, lalu secara naluriah menutup mata."
  },
  AvgDialog_18850_Content_13 = {
    Text = [[
Bau busuk Caro yang membusuk, udara dingin di ruang bawah tanah, dan getaran halus Kunci perak semuanya dengan cepat memudar. 
 Kamu tenggelam dalam kegelapan, mendengarkan dengan cermat setiap tangisan penuh penderitaan.]]
  },
  AvgDialog_18850_Content_14 = {
    Text = "Kak Sasa... bantu aku..."
  },
  AvgDialog_18850_Content_15 = {
    Text = "Aku tidak ingin mati, aku tidak ingin mati…"
  },
  AvgDialog_18850_Content_16 = {
    Text = "Semua karena dia... semua karena wanita ini... dia yang membuatku sembuh, dia..."
  },
  AvgDialog_18850_Content_17 = {
    Text = "Bahaya... Harus menunggu... Mythag..."
  },
  AvgDialog_18850_Content_18 = {
    Text = "Kamu telah mengunci suara ini."
  },
  AvgDialog_18850_Content_19 = {
    Text = "Saya adalah Penjaga baru, apakah kamu... senior di Akademi Manajemen?"
  },
  AvgDialog_18850_Content_2 = {
    Text = "Dalam suara doa yang panik dari Sarah, sebuah wajah dengan terlalu banyak mata dan gigi muncul di tubuh mutan itu. Lalu ia membuka mulutnya dan meratap dengan suara serak."
  },
  AvgDialog_18850_Content_20 = {
    Text = [[
Ini aku... lima hari yang lalu... aku dan Sean keluar untuk melakukan Penyelidikan terhadap pembunuh berantai... lalu kami bertemu monster... 
 Sean... apakah dia selamat...]]
  },
  AvgDialog_18850_Content_21 = {
    Text = [[
Dia menerima sembuh di sekolah dan kondisinya stabil.
Bisakah kamu memberitahuku apa yang terjadi padamu?]]
  },
  AvgDialog_18850_Content_22 = {
    Text = "Monster mengubahku menjadi... membawa pergi wanita itu... lalu... seseorang... dengan tanda pisau ukir... membawaku ke sini... memecahkan, memotong... dan meletakkanku bersama yang lain..."
  },
  AvgDialog_18850_Content_23 = {
    Text = "Mereka menyebutkan sebuah… rencana… di luar Taring… masih banyak lagi… \n Temukan mereka… Penjaga Rahasia… lalu… hentikan…"
  },
  AvgDialog_18850_Content_24 = {
    Text = "Suara lemah perlahan memudar, kamu membuka mata. Wajah pucat di tubuh mutan perlahan menghilang begitu saja, hanya menyisakan jejak hitam pekat di tanah."
  },
  AvgDialog_18850_Content_25 = {Text = "Apa kabar?"},
  AvgDialog_18850_Content_26 = {
    Text = "Aku baik-baik saja. Baru saja... seorang senior memberitahuku bahwa setelah dia diubah menjadi patung oleh entitas hidup yang tidak dikenal, dia dibawa ke sini untuk dijadikan eksperimen, lalu ditempatkan bersama dengan yang lainnya, menjadi seperti ini."
  },
  AvgDialog_18850_Content_27 = {
    Text = "Orang yang melakukan penelitian terhadap dirinya memiliki tanda alat ukir."
  },
  AvgDialog_18850_Content_28 = {
    Text = "Benar-benar para pematung. Lambang mereka adalah sebuah pahat."
  },
  AvgDialog_18850_Content_29 = {
    Text = [[
Tidak hanya itu, dia juga mengatakan bahwa para pemahat menyebutkan sebuah rencana.
Sebuah rencana yang melibatkan lebih dari sekadar Taring.]]
  },
  AvgDialog_18850_Content_3 = {
    Text = "Sasha... Sasha... Kak..."
  },
  AvgDialog_18850_Content_30 = {
    Text = "Ramona mengibaskan pedang tipisnya, memasukkannya kembali ke dalam sarung, lalu menatap Sarah yang terjatuh di sampingnya."
  },
  AvgDialog_18850_Content_31 = {
    Text = [[
Katakanlah. Kalian melakukan eksperimen manusia di sini, membunuh semaunya, apa sebenarnya tujuan kalian? 
 Rencana macam apa itu?]]
  },
  AvgDialog_18850_Content_32 = {
    Text = "Eksperimen manusia apa, apa... apa Patung? Aku tidak mengerti, aku tidak paham."
  },
  AvgDialog_18850_Content_33 = {
    Text = "Aku hanya ingin Taring terus berjalan, agar semua orang bisa tumbuh dengan sehat…"
  },
  AvgDialog_18850_Content_34 = {
    Text = "Sehat dari mana! Lihat saja para pasien itu, lihat Aigis! Matanya sudah rusak karena mereka, apakah menurutmu ini masih bisa disebut sehat?!"
  },
  AvgDialog_18850_Content_35 = {
    Text = "Tidak, tidak mungkin... Saya sendiri yang memeriksa Dokter, saya sendiri yang mencoba terapi itu. Saya baik-baik saja, baru saja membiarkan semua orang pergi. Tidak mungkin..."
  },
  AvgDialog_18850_Content_36 = {
    Text = [[
Aigis, sayang, beritahu aku, kau baik-baik saja, kan?
Dokter sudah menyembuhkan fatamorganamu, kan?]]
  },
  AvgDialog_18850_Content_37 = {
    Text = "Aigis melihat kalian, seakan-akan akhirnya berhasil mengumpulkan keberanian."
  },
  AvgDialog_18850_Content_38 = {
    Text = "Tidak, jangan melakukan eksperimen terhadapnya!"
  },
  AvgDialog_18850_Content_39 = {Text = "Aigis!"},
  AvgDialog_18850_Content_4 = {
    Text = [[
...Willie kecil...?
Hanya Willie kecil yang memanggilku seperti itu, Willie kecil, apakah itu kamu, Willie kecil?]]
  },
  AvgDialog_18850_Content_40 = {
    Text = [[
Ternyata kamu, Aigis. 
Apa kamu sudah memutuskan untuk bekerja sama dengan kami?]]
  },
  AvgDialog_18850_Content_41 = {
    Text = "Saya, saya... tidak..."
  },
  AvgDialog_18850_Content_42 = {
    Text = "Jika sakit, harus diperiksa dan disembuhkan sesuai dengan penyakitnya. Kalian semua bisa melihat hal-hal berwarna hitam, jadi seharusnya semua menerima pengobatan agar bisa sembuh secepatnya, benar kan?"
  },
  AvgDialog_18850_Content_43 = {
    Text = [[
Tidak... Tiyouge, Tiyouge sama sekali tidak bisa melihat...! Lepaskan dia! 
Jika kalian terus seperti ini, aku, aku, aku akan memberitahu Nyonya Sarah!]]
  },
  AvgDialog_18850_Content_44 = {
    Text = "Tidak bisa melihat? Tidak disangka ternyata anak kecil yang suka berbohong. \nKarena dia tidak bisa melihat, maka——"
  },
  AvgDialog_18850_Content_45 = {
    Text = "Aigis! Hati-hati di belakangmu!"
  },
  AvgDialog_18850_Content_47 = {
    Text = "—— terserah kamu."
  },
  AvgDialog_18850_Content_48 = {
    Text = "Hmm... di sini adalah..."
  },
  AvgDialog_18850_Content_49 = {
    Text = "Cahaya yang sangat terang membuat seseorang secara tidak sadar ingin menutup mata. Aigis mencoba untuk berkedip, tetapi dia menyadari bahwa dia tidak bisa melakukannya."
  },
  AvgDialog_18850_Content_5 = {
    Text = "Saya adalah... Mythag..."
  },
  AvgDialog_18850_Content_50 = {
    Text = "Ada sesuatu yang mengunci pandangannya, dia hanya bisa melihat seorang pria berbaju putih muncul di hadapannya, dengan sebuah pisau tipis di tangannya."
  },
  AvgDialog_18850_Content_51 = {
    Text = "<Big:Tidak, jangan, Nona Sarah, Nona Sarah!>"
  },
  AvgDialog_18850_Content_52 = {
    Text = "Peralatan perak bergerak mengikuti tangan peneliti, menarik garis perak panjang."
  },
  AvgDialog_18850_Content_53 = {
    Text = "<Big:Bu Sarah! Tiyoug! Tolong! Selamatkan aku! Selamatkan aku!>"
  },
  AvgDialog_18850_Content_54 = {
    Text = "Ujung pisaunya semakin dekat, semakin dekat, hingga memenuhi seluruh pandangan.\nLalu——"
  },
  AvgDialog_18850_Content_55 = {
    Text = "<Shake: Ah————!>"
  },
  AvgDialog_18850_Content_56 = {
    Text = [[
Di tengah kegelapan tanpa batas, dia melayang sendirian, seakan-akan diselimuti oleh air danau yang dingin dari segala arah.
Anggota tubuhnya mati rasa, tak bisa bergerak.]]
  },
  AvgDialog_18850_Content_57 = {
    Text = "Sakit sekali... mata terasa sangat tidak nyaman..."
  },
  AvgDialog_18850_Content_58 = {
    Text = "Warna-warni yang berkilauan, seolah-olah bergerak seperti sesuatu yang merayap, meresap masuk. Warna itu adalah cairan kental yang bercampur dengan darah dan air mata, mengalir deras."
  },
  AvgDialog_18850_Content_59 = {
    Text = "Aku salah, aku memang sampah... seharusnya tidak... tidak melakukan hal yang mustahil untuk kulakukan…"
  },
  AvgDialog_18850_Content_6 = {Text = "!?"},
  AvgDialog_18850_Content_60 = {
    Text = [[
Itu menggantikan air danau, menggantikan udara, menggantikan bau, suara, sentuhan, dan hidup. 
 Itu menjadi satu-satunya hal yang dimilikinya, dan memberinya pelukan penuh rasa sakit.]]
  },
  AvgDialog_18850_Content_61 = {
    Text = "Nona Sarah… Tiyoug… Tolong aku… Aku sangat kesakitan… Aku tidak tahan…"
  },
  AvgDialog_18850_Content_62 = {
    Text = "Warna-warni yang bergerak cepat meloncat ke atas, tiba-tiba dia terjatuh ke dalam tirai cahaya putih. Dorongan yang bukan miliknya berubah menjadi ribuan warna yang membanjiri matanya. Dia mencoba menutupi kedua matanya, namun tubuhnya tak bisa digerakkan."
  },
  AvgDialog_18850_Content_63 = {
    Text = "Kamu... siapa...?"
  },
  AvgDialog_18850_Content_64 = {
    Text = "Rasa sakit yang berlebihan akhirnya berubah menjadi mati rasa. Entah berapa lama telah berlalu, dia akhirnya menangkap secercah suara di tengah keheningan."
  },
  AvgDialog_18850_Content_65 = {
    Text = [[
Bisa melihat mata @2, itu benar-benar bahan terbaik.
Kalau bukan karena Sarah dan anak ini selalu menghalangi, sudah seharusnya digunakan untuk eksperimen.]]
  },
  AvgDialog_18850_Content_66 = {
    Text = "Sekarang juga tidak terlambat, Dokter. Akhirnya kita berhasil @4@2, ini patut dirayakan!"
  },
  AvgDialog_18850_Content_67 = {
    Text = "Suara bising di telinga, suara siapa itu sebenarnya? Apa yang mereka katakan? Setelah mimpi buruk berakhir, sudah tidak bisa mengingatnya dengan jelas."
  },
  AvgDialog_18850_Content_68 = {
    Text = "Aigis menyadari dirinya entah sejak kapan duduk di sebuah kursi, para peneliti berbaju putih berkerumun di sekitarnya. Mereka berbicara dengan penuh semangat tentang sesuatu, namun dia tidak bisa mendengar apa pun."
  },
  AvgDialog_18850_Content_69 = {
    Text = "Ti... Tiyoug...?"
  },
  AvgDialog_18850_Content_7 = {
    Text = "Ini, mungkinkah ini yang hilang itu…!"
  },
  AvgDialog_18850_Content_70 = {
    Text = "Wajah yang akrab di depan mata memudar seperti tercuci, kehilangan warna aslinya. Sebelum iris cokelatnya sepenuhnya digantikan oleh batu putih, dia, atau mungkin itu, menghembuskan napas terakhirnya."
  },
  AvgDialog_18850_Content_71 = {
    Text = "Ai... Jisi..."
  },
  AvgDialog_18850_Content_72 = {
    Text = "<Shake:Tiyouge——!>"
  },
  AvgDialog_18850_Content_73 = {
    Text = "Ketika aku bangun, aku sudah berada di dalam ruangan, dan Tiyouge juga sudah berubah menjadi... kondisi yang buruk."
  },
  AvgDialog_18850_Content_74 = {
    Text = "Jika saja aku tidak masuk begitu saja, jika aku... aku menyadari bahwa aku hanyalah sampah... aku tidak akan membuat mereka marah, dan mereka juga tidak akan melakukan hal itu pada Tiyouge..."
  },
  AvgDialog_18850_Content_75 = {
    Text = "Tidak mungkin, ini tidak benar, ini tidak benar…!"
  },
  AvgDialog_18850_Content_76 = {
    Text = "<Big:Apa lagi yang kau pura-pura tidak tahu!>"
  },
  AvgDialog_18850_Content_77 = {
    Text = "Jenkin mendorong Sarah dengan keras, hampir membuatnya jatuh tersungkur. Tikus di pundaknya turut merasakan kemarahannya dan menunjukkan giginya kepada Sarah."
  },
  AvgDialog_18850_Content_78 = {
    Text = "Katakan, ke mana orang-orang dibawa oleh Doktor Sialan itu? Ke mana kakakku dibawa oleh mereka! Katakan!"
  },
  AvgDialog_18850_Content_79 = {
    Text = "Jenkin, jangan seperti itu...! Sarah, dia juga tidak sengaja, dan dia juga tidak tahu——"
  },
  AvgDialog_18850_Content_8 = {
    Text = "Kalian sudah menemukan orangnya? Bagaimana kondisinya? Apakah dia memerlukan bantuan?"
  },
  AvgDialog_18850_Content_80 = {
    Text = "Jangan membela dia lagi! Kamu berubah seperti ini, orang-orang gila itu menjadi seperti itu, kakakku menghilang, semuanya karena dia! Dia harus membayar harganya!"
  },
  AvgDialog_18850_Content_81 = {
    Text = "Maaf, maaf…"
  },
  AvgDialog_18850_Content_82 = {
    Text = "…Erica, bantu kami menghubungi tim penyelidikan. Ada kebutuhan untuk pengangkutan."
  },
  AvgDialog_18850_Content_83 = {
    Text = [[
Mengirimkan permohonan bantuan penyelidikan. 
 Pengiriman selesai, konfirmasi penerimaan. Tim Penyelidikan No. 3 akan tiba di lokasi target dalam 3 jam.]]
  },
  AvgDialog_18850_Content_84 = {
    Text = [[
Silakan, Nona Sarah. 
Sebelum orang yang bersangkutan datang, Anda harus menunggu sebentar di kantor.]]
  },
  AvgDialog_18850_Content_85 = {
    Text = "Maaf... aku benar-benar... maaf..."
  },
  AvgDialog_18850_Content_86 = {
    Text = "Kamu melangkah beberapa langkah dan menyadari bahwa sosok kecil berwarna putih di sisimu telah menghilang."
  },
  AvgDialog_18850_Content_87 = {
    Text = "Dia mungkin membutuhkan waktu untuk menenangkan diri."
  },
  AvgDialog_18850_Content_88 = {Text = "?"},
  AvgDialog_18850_Content_89 = {
    Text = "Tidak ada apa-apa, ayo pergi."
  },
  AvgDialog_18850_Content_9 = {
    Text = "Makhluk abnormal di depan sini bergerak kesakitan, wajahnya yang mirip manusia namun bukan manusia terkadang memanjang dan berubah bentuk, lalu sesekali mengerut menjadi satu. Apapun kondisinya, tampaknya sudah tidak ada harapan lagi."
  },
  AvgDialog_18850_Content_90 = {Text = "Aigis?"},
  AvgDialog_18850_Content_91 = {
    Text = "Kamu menoleh dan melihat gadis itu berdiri di tempatnya, tak bergerak."
  },
  AvgDialog_18850_Content_92 = {
    Text = "Ada apa, Aigis? Mau aku antar kamu untuk beristirahat?"
  },
  AvgDialog_18850_Content_93 = {
    Text = "...Nona Sarah, apakah akan baik-baik saja?"
  },
  AvgDialog_18850_Content_94 = {
    Text = "Kami hanya ingin mengajukan beberapa pertanyaan kepadanya, jangan khawatir."
  },
  AvgDialog_18850_Content_95 = {
    Text = "Apakah dia akan kembali?"
  },
  AvgDialog_18850_Content_96 = {
    Text = "Dia... mungkin dia akan kembali."
  },
  AvgDialog_18850_Content_98 = {Text = "Aigis?"},
  AvgDialog_18850_Content_99 = {
    Text = [[
Tidak apa-apa... Ayo pergi, %player%{Male=tuan,Female=nyonya}. 
 Saya akan baik-baik saja.]]
  },
  AvgDialog_18851_Content_1 = {
    Text = [[
13:37, Londinium Timur
Lily Taring]]
  },
  AvgDialog_18851_Content_10 = {
    Text = "Dia mengeluarkan sepotong besi dan paku besi yang panjang dari sakunya, lalu memasukkannya ke dalam lubang kunci. Tikus di pundaknya berdiri tegak, memegang kedua cakarnya di depan dengan waspada sambil melihat ke sekeliling."
  },
  AvgDialog_18851_Content_11 = {
    Text = "Kunci pintu mengeluarkan suara klik pelan. Dia memegang gagang pintu, memutarnya, lalu mendorongnya ke dalam."
  },
  AvgDialog_18851_Content_12 = {
    Text = "Hei hei, dengan santai!"
  },
  AvgDialog_18851_Content_13 = {
    Text = [[
13:37, Londinium Timur
Lily Taring]]
  },
  AvgDialog_18851_Content_14 = {
    Text = "Ngomong-ngomong, Nona Sarah, kenapa kamu tidak membiarkan Aigis berpakaian lebih cantik? Bukankah hari ini kita kedatangan tamu penting?"
  },
  AvgDialog_18851_Content_15 = {
    Text = "Apa kamu mengerti? Jika berpakaian terlalu bagus, kita akan terlihat seperti tidak kekurangan uang. Namun, jika berpakaian terlalu buruk, kita akan terlihat seperti lubang tanpa dasar yang hanya menerima tanpa memberi, dan itu akan membuat para donatur kabur."
  },
  AvgDialog_18851_Content_16 = {
    Text = "Dia menarik rok Aigis sambil berbicara, lalu mengoleskan sedikit air liur di lengan bajunya dan mengusap pipi Aigis dengan kuat hingga bersih."
  },
  AvgDialog_18851_Content_17 = {
    Text = "Aigis, Aigisku yang baik, apakah kamu masih ingat apa yang harus dikatakan setelah bertemu dengan donatur?"
  },
  AvgDialog_18851_Content_18 = {
    Text = "Ingat, Nona Sarah. Saya sudah patuh, semalam sebelum tidur saya masih menghafalnya."
  },
  AvgDialog_18851_Content_19 = {
    Text = "Sarah mengangguk puas, lalu menatap pria paruh baya yang berdiri di sampingnya dengan tangan disilangkan."
  },
  AvgDialog_18851_Content_2 = {
    Text = "Aigis, apa yang sedang kamu lakukan? Sponsor akan segera datang!"
  },
  AvgDialog_18851_Content_20 = {
    Text = "Kamu juga harus berhati-hati, jangan bicara yang tidak perlu, mengerti?"
  },
  AvgDialog_18851_Content_21 = {
    Text = "Mengerti, mengerti!"
  },
  AvgDialog_18851_Content_22 = {
    Text = "Mengerti, berdiri dengan baik, {Male=dia,Female=dia} sudah datang."
  },
  AvgDialog_18851_Content_23 = {
    Text = "Hasilnya, dompet tidak ditemukan, malah bertemu dengan tubuh pelarutan. Apakah ini yang disebut tidak berbahaya…"
  },
  AvgDialog_18851_Content_24 = {
    Text = "Kamu belum selesai bicara, tiba-tiba sebuah suara yang familiar terdengar di dalam pikiranmu."
  },
  AvgDialog_18851_Content_25 = {
    Text = [[
Acara tidak selalu tetap, tugas juga demikian. 
 Atau, apakah kamu memiliki pendapat berbeda mengenai penilaian William?]]
  },
  AvgDialog_18851_Content_26 = {
    Text = "Saya sangat percaya pada penilaian Tuan Drapul, pasti Fenomena-d telah memburuk!"
  },
  AvgDialog_18851_Content_27 = {
    Text = [[
Reaksi kalian cukup cepat. 
 Baiklah, fokuslah. Bertemu dengan Entitas Anomali berarti kalian seharusnya tidak jauh dari lokasi target.]]
  },
  AvgDialog_18851_Content_28 = {
    Text = "Memang benar. Lihat."
  },
  AvgDialog_18851_Content_29 = {
    Text = "Kamu mengikuti arah yang dia tunjuk. Tidak jauh dari sana, terdapat sebuah pintu besi dengan tulisan \"Lily Laboratorium Taring\", di depan pintu berdiri tiga orang."
  },
  AvgDialog_18851_Content_3 = {
    Text = "Maaf, Nona Sarah, aku... aku tidak sengaja membuatmu menunggu."
  },
  AvgDialog_18851_Content_30 = {
    Text = "Melapor, tiba di lokasi misi."
  },
  AvgDialog_18851_Content_31 = {
    Text = "Konfirmasi kedatangan di lokasi misi. Periksa tujuan misi: menyusup ke Taring, mencari siswa yang hilang, mengonfirmasi identitas entitas hidup yang tidak dikenal, dan menghentikan tindakannya."
  },
  AvgDialog_18851_Content_32 = {
    Text = "Target misi telah diverifikasi. Segera memasuki Taring, jaga agar komunikasi tetap lancar."
  },
  AvgDialog_18851_Content_33 = {
    Text = "Ramona menatapmu."
  },
  AvgDialog_18851_Content_34 = {
    Text = "Bagaimana, apakah kamu sudah siap?"
  },
  AvgDialog_18851_Content_35 = {
    Text = "Saya bisa mengatasinya, asalkan orang di dalam tidak seperti anak-anak tadi."
  },
  AvgDialog_18851_Content_36 = {
    Text = "<Small:… juga tidak seperti Boneka.>"
  },
  AvgDialog_18851_Content_37 = {
    Text = "Apakah kamu tahu bahwa komunikator Perak sangat sensitif?"
  },
  AvgDialog_18851_Content_38 = {
    Text = "<Shake:Khek khek!>"
  },
  AvgDialog_18851_Content_39 = {
    Text = "Tenang saja. Aku akan membela mati-matian bros dan kancing lengan milikmu, Ashe{Male=tuan,Female=nona}."
  },
  AvgDialog_18851_Content_4 = {
    Text = "Sudahlah, kalian kan sudah besar, masih saja tidak mengerti. Cepat-cepat, kalau terlambat nanti tidak baik…"
  },
  AvgDialog_18851_Content_40 = {
    Text = "Kalau begitu, aku benar-benar mengandalkanmu, Nyonya Mary yang tercinta."
  },
  AvgDialog_18851_Content_41 = {
    Text = "Jika kalian masih bersenang-senang dengan menyamar, bersiaplah untuk menerima hukuman tambahan saat kembali."
  },
  AvgDialog_18851_Content_5 = {
    Text = [[
Gadis itu dengan patuh mengikuti. Dia diam-diam menoleh ke belakang dan melambaikan tangan kepada tanaman pot di sudut dinding. 
Suara langkah kaki perlahan menjauh, gadis yang memeluk tikus muncul dari balik dedaunan hijau.]]
  },
  AvgDialog_18851_Content_6 = {
    Text = "Akhirnya! Wanita menyebalkan itu selalu berada di kantor sepanjang hari, bahkan malam pun tidak pulang. Hari ini akhirnya aku mendapatkan kesempatan!"
  },
  AvgDialog_18851_Content_7 = {
    Text = "Cit! Cit cit!"
  },
  AvgDialog_18851_Content_8 = {
    Text = "Tenang, Aigis berkata bahwa mereka akan membawa siapa itu, manusia mandiri, untuk berkeliling hari ini dan tidak akan kembali hingga tengah hari. Aku harus memeriksa dengan teliti, tidak akan melewatkan satu rambut pun."
  },
  AvgDialog_18851_Content_9 = {
    Text = "Pada jam kerja, lorong di area hunian kosong tanpa seorang pun. Gadis itu tiba di depan sebuah pintu dengan plakat bertuliskan \"Kantor Pengelola\"."
  },
  AvgDialog_18852_Content_1 = {
    Text = "Ash {Male=tuan,Female=nona}, Nona Mary!"
  },
  AvgDialog_18852_Content_2 = {
    Text = "Kami tidak apa-apa, cepat bawa semua orang mundur. Kami bisa menanganinya."
  },
  AvgDialog_18852_Content_3 = {
    Text = "Baik, baik. Ya Tuhan, ini benar-benar… Anak-anak, anak-anak cepat, kemarilah."
  },
  AvgDialog_18852_Content_4 = {
    Text = "Cepat, ada seseorang yang sulit ditangani muncul."
  },
  AvgDialog_18853_Content_1 = {
    Text = [[
Kerusuhan berakhir, orang-orang kembali membentuk antrian. 
 Aigis berdiri di antara anak-anak, dengan wajah pucat dan sedikit gemetar.]]
  },
  AvgDialog_18853_Content_10 = {
    Text = "Sialan——"
  },
  AvgDialog_18853_Content_11 = {
    Text = "Apa yang akan kamu lakukan? Hentikan!"
  },
  AvgDialog_18853_Content_2 = {
    Text = "Beberapa ini, lalu——tambahkan Aigis juga.\nDia adalah anak kesayangan kita."
  },
  AvgDialog_18853_Content_3 = {
    Text = "Tidak, jangan... aku mohon… Aku tidak mau pergi, aku tidak mau berubah… Jangan…"
  },
  AvgDialog_18853_Content_4 = {
    Text = "Anak, Aigis, cepat kemarilah. Jangan membuang-buang waktu orang dewasa."
  },
  AvgDialog_18853_Content_5 = {
    Text = "Peneliti baru saja akan mengulurkan tangan, Jenkin tiba-tiba melompat keluar dan berdiri di depan Aigis untuk menghalanginya."
  },
  AvgDialog_18853_Content_6 = {
    Text = "Apakah kamu tidak mendengarnya ketika orang itu berkata \"jangan pergi\"?"
  },
  AvgDialog_18853_Content_7 = {
    Text = "Apakah kamu anak baru?"
  },
  AvgDialog_18853_Content_8 = {
    Text = [[
Apa pun statusku, baik yang baru datang maupun yang lama, Aigis berkata dia tidak mau pergi, dan tidak ada yang bisa memaksanya! 
 Cokelat, tolong bantu!]]
  },
  AvgDialog_18853_Content_9 = {Text = "Cit cit!"},
  AvgDialog_18854_Content_1 = {
    Text = "Kamu dan Ramona sedang berdiskusi dengan suara pelan, tiba-tiba, suara gaduh terdengar dari belakang kalian."
  },
  AvgDialog_18854_Content_2 = {
    Text = "Orang di luar, hati-hati! Pasien melarikan diri! Melarikan diri!"
  },
  AvgDialog_18854_Content_3 = {Text = "!"},
  AvgDialog_18855_Content_1 = {
    Text = "Nyanyian yang tak terdengar memandu di depan yang samar, kamu menyingkirkan kabut dan berlari ke depan, namun tak pernah bisa melihat titik akhir."
  },
  AvgDialog_18855_Content_10 = {
    Text = "Tolong awasi sekitar untukku."
  },
  AvgDialog_18855_Content_11 = {
    Text = [[
Kamu menghindari noda darah dan berlutut separuh untuk memeriksa. 
 Tidak ada tanda-tanda petrifikasi, namun, kamu melihat beberapa jejak kaki dengan warna aneh di samping mayat itu.]]
  },
  AvgDialog_18855_Content_12 = {
    Text = "D-lendir? Di tubuh korban juga ada… Apakah berasal dari pelaku?"
  },
  AvgDialog_18855_Content_13 = {
    Text = [[
Di area ini, selain Taring, hanya di sini terdapat D-marka. 
 Saya tidak percaya ini adalah kebetulan.]]
  },
  AvgDialog_18855_Content_14 = {
    Text = "Ini hampir membuktikan bahwa pelaku berasal dari Taring, pertanyaan yang tersisa adalah: siapa dia, dan di mana dia bersembunyi di Taring? Apakah itu adalah entitas kehidupan tak dikenal yang kalian cari?"
  },
  AvgDialog_18855_Content_15 = {
    Text = "Tunggu sebentar, ukurannya... ini jejak kaki anak-anak?!"
  },
  AvgDialog_18855_Content_16 = {Text = "?!"},
  AvgDialog_18855_Content_17 = {
    Text = "...memang benar, sepertinya ke arah Taring pergi."
  },
  AvgDialog_18855_Content_18 = {
    Text = "Cepat, cari dia sebelum anak itu sempat bersembunyi."
  },
  AvgDialog_18855_Content_19 = {
    Text = [[
20:47, Taring Lily 
 Koridor]]
  },
  AvgDialog_18855_Content_2 = {
    Text = "Bangunan di kedua sisi jalan memandangmu dengan diam melalui jendela-jendela yang gelap. Langkah kakimu bergema dalam kabut, dan untuk sesaat kamu merasa seolah-olah telah berlari sendirian di jalan ini untuk waktu yang lama."
  },
  AvgDialog_18855_Content_20 = {
    Text = [[
Di tengah kabut yang ada di mana-mana, Taring terasa lebih dingin dan suram dari sebelumnya. 
 Pria dengan tongkat kayu tergantung di pinggangnya berpatroli di koridor yang kosong tanpa cahaya sambil memegang lentera.]]
  },
  AvgDialog_18855_Content_21 = {
    Text = "Jangan nyalakan lampu, hemat listrik——**, Sarah itu benar-benar pelit. Masih banyak maunya! Lihat tempat kita yang buruk ini, mana ada pencuri yang mau datang… Hm?"
  },
  AvgDialog_18855_Content_22 = {
    Text = "Di bawah cahaya redup, sebuah pintu terbuka tanpa suara."
  },
  AvgDialog_18855_Content_23 = {
    Text = "Siapa, siapa di sana?"
  },
  AvgDialog_18855_Content_24 = {
    Text = "Dia mencengkeram erat tongkat kayu itu, memberanikan diri untuk melangkah maju."
  },
  AvgDialog_18855_Content_25 = {
    Text = "Lentera kuno tiba-tiba padam."
  },
  AvgDialog_18855_Content_26 = {Text = "!!!"},
  AvgDialog_18855_Content_27 = {
    Text = "Kekuatan tak terlihat tiba-tiba menariknya masuk. Pintu kayu tertutup dengan bunyi gedebuk, dan koridor kembali menjadi sunyi serta tenang."
  },
  AvgDialog_18855_Content_28 = {
    Text = [[
20:43, Lily Taring 
 Koridor]]
  },
  AvgDialog_18855_Content_29 = {
    Text = "Dua gadis berkerut di bawah cahaya redup lampu lentera, terus-menerus memandang ke sekeliling dengan waspada."
  },
  AvgDialog_18855_Content_3 = {
    Text = "Segalanya tidak memiliki awal, tidak memiliki akhir. Kamu akan terus maju hingga hidup berakhir, hingga waktu ——"
  },
  AvgDialog_18855_Content_30 = {
    Text = "Langkah kaki yang pelan terdengar dari kejauhan, hampir menusuk telinga di koridor yang sunyi."
  },
  AvgDialog_18855_Content_31 = {
    Text = [[
Siapa, siapa di sana? 
 Keluar! Aku memperingatkanmu, aku punya senjata!]]
  },
  AvgDialog_18855_Content_32 = {
    Text = "Tidak ada aliran udara di lorong, namun nyala api pada sumbu lampu bergerak seolah-olah tertiup angin."
  },
  AvgDialog_18855_Content_33 = {
    Text = "Nampan di tangan Aigis bergetar, cangkir teh putih dan alasnya saling berbenturan, menghasilkan suara seperti tangisan pilu burung kecil sebelum ajal."
  },
  AvgDialog_18855_Content_34 = {
    Text = "Langkah kaki semakin dekat, semakin dekat. Cakar Cokelat menancap dalam ke bahu Jenkin, memperlihatkan giginya dan mengeluarkan suara ancaman tajam yang khas bagi tikus."
  },
  AvgDialog_18855_Content_35 = {
    Text = "Seperti terpicu oleh suara Cokelat, langkah kaki tiba-tiba mempercepat, ternyata menuju ke arah mereka berdua."
  },
  AvgDialog_18855_Content_36 = {
    Text = "Bayangan hitam yang pekat sepenuhnya menelan cahaya lilin yang redup. Gadis-gadis itu menutup mata mereka, namun hanya merasakan hembusan uap air menyapu wajah mereka."
  },
  AvgDialog_18855_Content_37 = {
    Text = "Sebuah tangan muncul dari kegelapan, tepat menyentuh cangkir teh yang terus bergetar, menghentikan suaranya."
  },
  AvgDialog_18855_Content_38 = {
    Text = "Apa yang terjadi dengan kalian? Wajah kalian... begitu pucat?"
  },
  AvgDialog_18855_Content_39 = {
    Text = [[
Tuan Rogers! 
Di sini sangat gelap. Kita...]]
  },
  AvgDialog_18855_Content_4 = {
    Text = "Aroma darah."
  },
  AvgDialog_18855_Content_40 = {
    Text = "Malam yang berkabut memang mudah membuat orang merasa takut dan cemas, bukan?"
  },
  AvgDialog_18855_Content_41 = {
    Text = "Rogers mendorong pintu terbuka, cahaya hangat memancar keluar, mengusir bayangan yang pekat di koridor."
  },
  AvgDialog_18855_Content_42 = {
    Text = "Terima kasih telah mengantarkan makanan untukku, Aigis. Jenkin."
  },
  AvgDialog_18855_Content_43 = {
    Text = "Setelah meletakkan nampan di atas meja kecil, Rogers mengambil boneka dengan kerajinan tangan yang halus dari tempat tidur dan tersenyum kepada kedua gadis itu."
  },
  AvgDialog_18855_Content_44 = {
    Text = [[
Sebagai hadiah, apakah kamu mau mencobanya? 
 George akan sangat senang.]]
  },
  AvgDialog_18855_Content_45 = {
    Text = "Mata boneka yang tak bernyawa memantulkan cahaya kuning dari lampu, seakan-akan diam-diam memohon kepada gadis itu: \"Sentuh aku, hanya sekali.\""
  },
  AvgDialog_18855_Content_46 = {
    Text = "Sentuh aku, lalu——"
  },
  AvgDialog_18855_Content_47 = {
    Text = "Menjadi teman setia saya."
  },
  AvgDialog_18855_Content_5 = {
    Text = [[
Kamu tiba-tiba tersadar, lalu perlahan menyadari bau amis-manis yang menusuk. 
 Kamu memperlambat langkahmu dan mendekati bayangan yang terbaring di tanah di depan.]]
  },
  AvgDialog_18855_Content_6 = {
    Text = "Itu adalah jasad seorang wanita yang hancur berkeping-keping, rongga perutnya terbuka dan masih mengepul, wajahnya penuh luka dengan Caro yang hancur, kedua tangannya hilang, permukaan potongan rapi, seolah-olah seseorang dengan cepat memotongnya."
  },
  AvgDialog_18855_Content_7 = {
    Text = "Teknik ini adalah milik seorang pemutilasi."
  },
  AvgDialog_18855_Content_8 = {
    Text = [[
Perut dibedah, anggota tubuh diambil sebagai trofi, sesuai dengan ciri-ciri kejahatan pembunuh yang tercatat dalam laporan polisi. 
 Untuk sesaat, kamu bahkan tidak tahu mana yang lebih kejam: Pelarutan, atau sang pembunuh.]]
  },
  AvgDialog_18855_Content_9 = {
    Text = "Tapi mengapa nyanyian pelacakan Roh mengarahkanmu ke sini? Kemampuan entitas Hidup yang tidak dikenal jelas adalah petrifikasi, atau apakah ada lebih dari satu individu istimewa di sini?"
  },
  AvgDialog_18856_Content_1 = {
    Text = "Beban Hati Nurani"
  },
  AvgDialog_18856_Content_10 = {
    Text = "Kamu mengikuti Sarah dari belakang hingga tiba di samping pintu logam besar Taring, dan tepat pada saat itu, kamu melihat beberapa orang berpakaian seragam menahan seorang gadis kecil yang menangis dan berusaha melawan, sedang dibawa keluar menuju pintu."
  },
  AvgDialog_18856_Content_11 = {Text = "Komite."},
  AvgDialog_18856_Content_12 = {
    Text = "Apakah ini evakuasi yang disebutkan oleh Boneka? Mengapa datangnya begitu cepat?"
  },
  AvgDialog_18856_Content_13 = {
    Text = "Lepaskan! Ke mana kalian akan membawanya, ke mana kalian akan membawa Lucy!"
  },
  AvgDialog_18856_Content_14 = {
    Text = "Tunggu sebentar!"
  },
  AvgDialog_18856_Content_15 = {
    Text = "Kamu mengeluarkan kalung yang tersembunyi di bawah pakaianmu. Kunci perak yang tergantung di kalung itu melayang tegak di atas telapak tanganmu saat kamu menggerakkannya, dan memancarkan cahaya lembut."
  },
  AvgDialog_18856_Content_16 = {
    Text = "Penjaga Universitas Mythag %player%, nomor kunci K-0617, meminta percakapan dengan penanggung jawab operasi ini."
  },
  AvgDialog_18856_Content_17 = {
    Text = "Orang yang berdiri di depanmu mengalihkan pandangannya dari kunci perak, lalu memberi hormat kepadamu."
  },
  AvgDialog_18856_Content_18 = {
    Text = "<Blue:Komite Perjanjian Mystia> Ketua Tim Respons Ketiga, menangani serah terima hasil investigasi terkait organisasi khusus S kali ini."
  },
  AvgDialog_18856_Content_19 = {
    Text = "Tidak disangka bisa bertemu Penjaga baru di sini, suatu kehormatan bagi saya, %player%{Male=tuan,Female=nyonya}."
  },
  AvgDialog_18856_Content_2 = {
    Text = [[
10:20, Lily's Taring 
 Depan Kantor Administrator]]
  },
  AvgDialog_18856_Content_20 = {
    Text = "Boleh tanya, apa yang terjadi? Kenapa kalian tiba-tiba menangkap anggota Taring?"
  },
  AvgDialog_18856_Content_21 = {
    Text = "Mohon izinkan saya untuk menjelaskan."
  },
  AvgDialog_18856_Content_22 = {
    Text = "Kapten melambaikan tangan, lalu seorang Agen di sampingnya memberikan sebuah kantong kertas."
  },
  AvgDialog_18856_Content_23 = {
    Text = "Kamu membuka tas itu dan menemukan bahwa di dalamnya terdapat pakaian tidur anak-anak yang sudah usang. Tepi pakaian tidur tersebut dipenuhi dengan noda cokelat gelap, yang menjadi sedikit keras karena cairan telah mengering."
  },
  AvgDialog_18856_Content_24 = {
    Text = "Setelah menerima pemberitahuan penyelidikan bersama dari Universitas Mythag, kami tiba di sini pada pukul 10:23 dan melakukan pencarian awal di Taring untuk memastikan kondisi Taring."
  },
  AvgDialog_18856_Content_25 = {
    Text = "Selama proses pencarian, kami menemukan jejak darah di ruangan lama di sisi tenggara lantai satu Taring, serta menemukan benda ini dan sebuah pisau pemotong daging yang berlumuran darah di ruang penyimpanan barang-barang di bawah tangga."
  },
  AvgDialog_18856_Content_26 = {
    Text = "Setelah anggota Taring mengonfirmasi, piyama ini adalah milik seorang anak bernama Lucy. Berdasarkan noda darah di kamar lama dan kesaksian seseorang yang berteriak tadi malam, kami memutuskan untuk membawanya kembali guna Penyelidikan."
  },
  AvgDialog_18856_Content_27 = {
    Text = "Itu aku, aku yang berteriak! Aku ketakutan oleh bayangan semalam, tapi tidak ada hal buruk yang terjadi! Penjaga ini juga melihatnya, tidak ada apa-apa yang terjadi, kan?"
  },
  AvgDialog_18856_Content_28 = {
    Text = "Tuan, masalah ini memang tidak sesederhana itu. Kami menduga ada pihak ketiga yang terlibat, dan anak ini kemungkinan besar berada di bawah kendali orang lain. Bisakah Anda tidak membawanya pergi?"
  },
  AvgDialog_18856_Content_29 = {
    Text = "Kami sudah mengetahui tentang Acara organisasi ilegal tersebut. Namun, terlepas dari apakah pelaku dihasut atau tidak, pelaku tetaplah pelaku. Secara prosedural, saya tidak bisa membiarkannya bebas berkeliaran."
  },
  AvgDialog_18856_Content_3 = {
    Text = "Sebelum kalian tiba di depan pintu kantor, seorang wanita muda mendadak berlari menghampiri kalian."
  },
  AvgDialog_18856_Content_30 = {
    Text = "Komite akan mematuhi ketentuan terkait dalam \"Perjanjian\" selama proses Penyelidikan, dan tidak akan membiarkan dia mengalami perlakuan yang tidak adil. Saya dapat menjamin hal ini kepada Anda."
  },
  AvgDialog_18856_Content_31 = {
    Text = "Selain itu, mobil untuk mengantar kalian berdua kembali ke sekolah sudah siap. Karena situasinya istimewa, saya akan menugaskan dua Agen tambahan untuk menemani kalian dan memastikan keselamatan kalian. Mohon ikuti saya."
  },
  AvgDialog_18856_Content_32 = {
    Text = "Tidak bisa."
  },
  AvgDialog_18856_Content_33 = {
    Text = "Para pematung menggunakan lembaga yang disebut sebagai kedok, melalui sponsor Rogers berhubungan dengan Taring, dan secara rahasia melakukan eksperimen manusia di Taring. Eksperimen ini juga menyebabkan munculnya pelarutan abnormal."
  },
  AvgDialog_18856_Content_34 = {
    Text = "Berdasarkan petunjuk yang ada, selain \"penyakit gila\" di Taring, kemungkinan besar \"pemutilasi\" yang akhir-akhir ini aktif di Distrik Timur juga merupakan salah satu manifestasi dari Pelarutan abnormal."
  },
  AvgDialog_18856_Content_35 = {
    Text = "Kami telah menemukan banyak hal, hanya identitas si pembongkar yang belum terungkap untuk benar-benar menjelaskan kebenaran acara tersebut, dan juga untuk menggagalkan rencana sang pemahat. Pada saat ini, kita tidak bisa pergi."
  },
  AvgDialog_18856_Content_36 = {
    Text = "Saya mengerti harapanmu untuk melanjutkan Penyelidikan, tapi perintahku —"
  },
  AvgDialog_18856_Content_37 = {
    Text = [[
Dia tiba-tiba menekan lencana Komite di lengan atasnya, tampak sedang mendengarkan sesuatu. 
 Itu kemungkinan adalah komunikator Perak yang diberikan oleh Universitas Mythag kepada Komite. Apakah ada perintah baru?]]
  },
  AvgDialog_18856_Content_38 = {
    Text = [[
<Blue:Lidiya, Komandan>. Ya, Penjaga tidak mau menyerah dalam penyelidikan. 
 Tiga hari? Bukan, aku tidak sedang mempertanyakanmu... Ya, aku mengerti. Baiklah, konfirmasi penerimaan komunikasi.]]
  },
  AvgDialog_18856_Content_39 = {
    Text = "Halo, sangat terhormat bisa berkomunikasi dengan Anda, <Blue:Penjaga Generasi Pertama>."
  },
  AvgDialog_18856_Content_4 = {
    Text = "Nona Sarah, ada masalah! Beberapa orang ingin membawa Lucy pergi!"
  },
  AvgDialog_18856_Content_40 = {
    Text = "Kamu hanya tahu satu orang yang pantas menyandang gelar itu — mentor kamu yang tinggal di bawah tanah Mythag sepanjang tahun. Selama setahun terakhir, kamu tak pernah melihatnya menghubungi siapa pun kecuali kamu dan Boneka, apakah…"
  },
  AvgDialog_18856_Content_41 = {
    Text = "Baik, saya mengerti. Selamat tinggal, Tuan."
  },
  AvgDialog_18856_Content_42 = {
    Text = "Komandan menghentikan percakapan dan berbalik ke arahmu. Pada saat yang sama, terdengar suara lembut guru di dalam pikiranmu."
  },
  AvgDialog_18856_Content_43 = {
    Text = [[
Lakukan apa yang kamu inginkan, %player%, aku akan menangani tempat lain. 
 Aku percaya padamu.]]
  },
  AvgDialog_18856_Content_44 = {
    Text = [[
Hal yang sama juga dia katakan padamu sebelum keberangkatan.
Sepertinya, untuk sementara kamu tidak perlu kembali.]]
  },
  AvgDialog_18856_Content_45 = {
    Text = "Setelah berkonsultasi dengan Penjaga generasi pertama, Komite memutuskan untuk mengizinkan Penjaga melanjutkan penyelidikan Acara di Taring Lily. Namun, kamu hanya memiliki tiga hari. Setelah tiga hari, acara tersebut akan diserahkan kepada Penyelidik yang lebih senior."
  },
  AvgDialog_18856_Content_46 = {
    Text = "Sambil berbicara, dia berbalik dan mulai memberi perintah kepada para Agen di sekitarnya."
  },
  AvgDialog_18856_Content_47 = {
    Text = "Pengalihan ditangguhkan, segera laksanakan penguncian wilayah level 5. Tersangka untuk sementara ditahan, tunggu hingga pekerjaan pengalihan selesai untuk dilakukan interogasi."
  },
  AvgDialog_18856_Content_48 = {
    Text = "Tidak, tidak! Kumohon, aku akan memberikan apa saja, jangan bawa dia pergi! Lucy, <Big:Lucy——>"
  },
  AvgDialog_18856_Content_49 = {
    Text = "Bukan dia yang melakukannya, bukan dia! %player%! Tolong, bantu Lucy, bantu dia!"
  },
  AvgDialog_18856_Content_5 = {Text = "Apa, apa?!"},
  AvgDialog_18856_Content_50 = {
    Text = [[
Maaf, ini adalah perintah mutlak kami, saya harus menjalankannya. 
 Kalau begitu, saya pamit dulu.]]
  },
  AvgDialog_18856_Content_51 = {
    Text = "Bersumpah untuk menembus kegelapan dengan mata pedang."
  },
  AvgDialog_18856_Content_52 = {
    Text = "Dia sekali lagi memberi hormat kepadamu, lalu tanpa memedulikan teriakan Lucy dan permohonan Sarah serta Aigis, dia memerintahkan anak buahnya untuk membawa gadis itu. Setelah berbalik, dia masuk ke dalam kendaraan yang sudah menunggu."
  },
  AvgDialog_18856_Content_53 = {
    Text = "Pintu mobil tertutup, memutus semua pandangan. Mobil-mobil berangkat satu per satu. Sarah benar-benar kehilangan tenaga dan jatuh berlutut di tanah."
  },
  AvgDialog_18856_Content_54 = {
    Text = "<Small:Saya tidak berguna, saya tidak mampu. Saya bukan kepala sekolah yang baik. Saya tidak bisa melindungi semua orang, tidak bisa melindungi anak-anak…>"
  },
  AvgDialog_18856_Content_55 = {
    Text = "Nyonya Sarah, jangan seperti ini... kami, semua orang sudah mengerti. Kamu sudah berusaha semampumu."
  },
  AvgDialog_18856_Content_56 = {
    Text = "<Small:Maaf, Wheatley, maaf, Aigis, maaf… Jenkin… \nMaaf, Diana, Henry, Lucy…>"
  },
  AvgDialog_18856_Content_57 = {
    Text = "Dia meringkuk, kedua tangannya memeluk tubuhnya, bisikan sedihnya perlahan menjadi serak dan kacau, sulit dibedakan."
  },
  AvgDialog_18856_Content_58 = {
    Text = "Nona Sarah...?"
  },
  AvgDialog_18856_Content_59 = {
    Text = [[
Bengkel yang terang benderang dan ramai itu seolah tenggelam ke dasar laut, tiba-tiba terjatuh ke dalam kesunyian yang dingin. 
Tekanan tak terduga datang, dan kamu terengah-engah, menyadari ada yang tidak beres.]]
  },
  AvgDialog_18856_Content_6 = {
    Text = "Mereka mengenakan seragam yang belum pernah terlihat sebelumnya, tampak begitu menyeramkan. Setelah berkeliling sejenak, mereka langsung menyatakan bahwa Lucy adalah tersangka, bahkan tak bisa dicegah."
  },
  AvgDialog_18856_Content_60 = {
    Text = "Astaga, Ramona, cepat suruh yang lain pergi!"
  },
  AvgDialog_18856_Content_61 = {
    Text = [[
Tidak ada waktu lagi. 
Kepala administrator muda itu retak seperti bunga, dan cairan hitam menyembur ke tanah.]]
  },
  AvgDialog_18856_Content_62 = {
    Text = "Sarah, Nyonya Sarah!"
  },
  AvgDialog_18856_Content_63 = {
    Text = [[
Dia mengeluarkan suara ringkikan yang tinggi dan tajam, dari kejauhan terdengar beberapa suara yang seakan-akan merespons. 
Tubuhnya yang terpuntir, mutan yang tercemar oleh pelarutan muncul dengan cepat dari gedung.]]
  },
  AvgDialog_18856_Content_7 = {
    Text = "Bagaimana mungkin Lucy?! Jelas-jelas..."
  },
  AvgDialog_18856_Content_8 = {
    Text = "Henry dan Manny sedang bertahan di pintu, entah bisa bertahan berapa lama lagi, cepatlah!"
  },
  AvgDialog_18856_Content_9 = {
    Text = "Sarah segera mengangkat roknya dan berlari keluar."
  },
  AvgDialog_18857_Content_1 = {
    Text = "Malam tanpa burung terbang"
  },
  AvgDialog_18857_Content_10 = {
    Text = "Seolah-olah tidak melihatnya, gadis itu terus melangkah maju tanpa henti, satu langkah demi satu langkah ke depan."
  },
  AvgDialog_18857_Content_11 = {
    Text = "Ketika dia berjalan melewati, Aigis mendengar suara nyanyian yang sangat lembut."
  },
  AvgDialog_18857_Content_12 = {
    Text = "Paman Charlie memiliki seekor kucing tabby yang sangat dia cintai..."
  },
  AvgDialog_18857_Content_13 = {
    Text = "Lucy, mau ke mana? Berikan pisaunya padaku, Lucy!"
  },
  AvgDialog_18857_Content_14 = {
    Text = "Sangat dingin… di mana ini… luar? Bagaimana aku bisa sampai di sini?"
  },
  AvgDialog_18857_Content_15 = {
    Text = "Aku jelas-jelas sedang tidur di kamar, tapi Xiao Mai terus berisik... Uh, mataku sakit..."
  },
  AvgDialog_18857_Content_16 = {
    Text = "Gila... gila! Jangan mendekat! Jangan mendekat!"
  },
  AvgDialog_18857_Content_17 = {
    Text = "Bu, apakah Anda membutuhkan bantuan? Jangan takut, saya akan segera memanggil seseorang untuk membantu—"
  },
  AvgDialog_18857_Content_18 = {
    Text = "Tolong! Ada orang di sana? Tolong selamatkan aku!"
  },
  AvgDialog_18857_Content_19 = {
    Text = "Aku, aku tidak bisa bergerak?! Mengapa, mengapa tubuhku tidak bisa bergerak?"
  },
  AvgDialog_18857_Content_2 = {
    Text = "Uap air berkumpul menjadi kabut tebal, membuat koridor yang sudah tidak terlalu lebar menjadi semakin dalam dan suram, hingga akhirnya sepenuhnya dimakan oleh kegelapan."
  },
  AvgDialog_18857_Content_20 = {
    Text = "Ternyata sudah sadar kembali, anak yang sangat istimewa."
  },
  AvgDialog_18857_Content_21 = {
    Text = "Siapa kamu? Apa. Apa yang akan kamu lakukan terhadap wanita ini?"
  },
  AvgDialog_18857_Content_22 = {
    Text = "Saya? Tidak, tidak. Kamu salah. Bukan aku yang akan melakukan sesuatu padanya."
  },
  AvgDialog_18857_Content_23 = {
    Text = "Aku, tangan aku kenapa..."
  },
  AvgDialog_18857_Content_24 = {
    Text = "Apa yang akan kau lakukan padanya, itu terserah kamu."
  },
  AvgDialog_18857_Content_25 = {
    Text = "Jangan bunuh saya, <Big: Tolong jangan bunuh saya!>"
  },
  AvgDialog_18857_Content_26 = {
    Text = "Bukan aku, bukan aku! Taruh pisaunya! Cepat lari, cepat lari!"
  },
  AvgDialog_18857_Content_27 = {
    Text = "<BigShake:AAAAAH——!>"
  },
  AvgDialog_18857_Content_28 = {
    Text = "Maaf... Maaf..."
  },
  AvgDialog_18857_Content_29 = {
    Text = "Cepat lari, kalian semua cepat lari!"
  },
  AvgDialog_18857_Content_3 = {
    Text = "Lilin berjuang untuk menerangi sebagian kecil area di udara yang lembap. Di ujung cahayanya, di kedalaman kegelapan, sesuatu sedang mendekat."
  },
  AvgDialog_18857_Content_30 = {
    Text = "Paman Charlie memiliki seekor kucing tabby yang sangat dia sayangi."
  },
  AvgDialog_18857_Content_31 = {
    Text = "Kakiku, kakiku tidak bisa bergerak. Tolong selamatkan aku! Tolong selamatkan aku!"
  },
  AvgDialog_18857_Content_32 = {Text = "Nyonya!"},
  AvgDialog_18857_Content_33 = {
    Text = "Senior, jangan ke sana, Senior!"
  },
  AvgDialog_18857_Content_34 = {
    Text = "Tolong, Tuan Misterius, jangan lakukan ini, aku mohon."
  },
  AvgDialog_18857_Content_35 = {
    Text = "Suatu hari dia menghilang, dan dia mencarinya ke mana-mana."
  },
  AvgDialog_18857_Content_36 = {
    Text = "Cepat hubungi sekolah!"
  },
  AvgDialog_18857_Content_37 = {
    Text = "Aku tidak ingin memberikan kerusakan pada mereka, kumohon, aku akan mendengarkan semua yang kamu katakan, hanya saja——jangan berikan kerusakan pada mereka."
  },
  AvgDialog_18857_Content_38 = {
    Text = "Dia membuka dan memeriksa lemari. Dia melihat ke bawah tempat tidur."
  },
  AvgDialog_18857_Content_39 = {
    Text = "<Shake: Se-sempai... Be-be-belakang!>"
  },
  AvgDialog_18857_Content_4 = {
    Text = "Suara gesekan berubah menjadi langkah kaki yang ringan, dan sebuah bayangan manusia yang samar perlahan mendekati pulau terpencil yang redup ini."
  },
  AvgDialog_18857_Content_40 = {
    Text = "Dia berkeliling di basement tempat boiler sedang dinyalakan."
  },
  AvgDialog_18857_Content_41 = {
    Text = "Ah……Ah!!"
  },
  AvgDialog_18857_Content_42 = {
    Text = "Tolong! Pak! Jangan, jangan, jangan!"
  },
  AvgDialog_18857_Content_43 = {
    Text = "Charlie tua tidak bisa menemukan kucing lorengnya di mana pun."
  },
  AvgDialog_18857_Content_44 = {
    Text = "<Shake: Tidak, tidak, jangan mendekat... Jangan mendekat... Kumohon, kumohon lepaskan aku...>"
  },
  AvgDialog_18857_Content_45 = {
    Text = "Jadi dia menangis dan menangis——"
  },
  AvgDialog_18857_Content_46 = {
    Text = "<Shake: Aku juga punya adik perempuan... Tolong... Jangan bunuh aku...>"
  },
  AvgDialog_18857_Content_47 = {
    Text = "——Hingga dirinya sendiri juga menghilang."
  },
  AvgDialog_18857_Content_48 = {
    Text = "<BigShake:Ah————!>"
  },
  AvgDialog_18857_Content_49 = {Text = "Jangan..."},
  AvgDialog_18857_Content_5 = {
    Text = "Lucy, kamu ke mana? Kamu sudah lama pergi malam ini, aku mulai khawatir——"
  },
  AvgDialog_18857_Content_50 = {
    Text = "Kenapa… apa yang sebenarnya telah kami lakukan salah… mengapa kami harus mengalami hal seperti ini…"
  },
  AvgDialog_18857_Content_51 = {
    Text = "Mik kecil tanpa ekspresi, menatap lurus ke depan. Tangannya memegang sebuah pisau tajam, dan pakaiannya yang direndam darah terus meneteskan cairan kental."
  },
  AvgDialog_18857_Content_52 = {
    Text = "Di belakangnya ada sebuah pintu kamar yang terbuka, dan dari luar pintu samar-samar terlihat tubuh yang hancur terbaring di dalam kamar."
  },
  AvgDialog_18857_Content_53 = {
    Text = "Semua orang mendengarkan suara itu, tetapi tidak ada yang ingat. Jika, jika suara itu pergi mencari Jenkin…"
  },
  AvgDialog_18857_Content_54 = {
    Text = "Anak yang malang, apakah kamu ingin mencoba usaha yang sia-sia lagi?"
  },
  AvgDialog_18857_Content_55 = {
    Text = [[
...!
Itu, itu, itu kamu...! Jahat, jahat! Jangan kendalikan Little Mike!]]
  },
  AvgDialog_18857_Content_56 = {
    Text = "Jangan kendalikan dia lagi! Kalau tidak, kalau tidak aku akan memberitahu—memberitahu…"
  },
  AvgDialog_18857_Content_57 = {
    Text = [[
Memberitahu siapa, Nona Sarah yang tercinta? 
Aigis, apakah kamu lupa bagaimana dia memperlakukanmu ketika kamu memberitahunya terakhir kali?]]
  },
  AvgDialog_18857_Content_59 = {
    Text = [[
Dia merasa kamu sedang mengalami mimpi buruk, atau melihat Fatamorgana lagi, dan berencana membawamu untuk "diperiksa" sekali lagi.
Bukti yang kamu tunjukkan juga dianggap sebagai sampah yang tertinggal dari "perawatan pasien" oleh Doktor.]]
  },
  AvgDialog_18857_Content_6 = {Text = "!!"},
  AvgDialog_18857_Content_60 = {
    Text = [[
Melihatmu begitu sedih, aku juga merasa terluka, tapi inilah realitas yang kejam dan buruk.
Jika bukan karena matamu masih berguna, aku akan membebaskanmu dan menjadikanmu Relik yang indah.]]
  },
  AvgDialog_18857_Content_61 = {
    Text = [[
Sekarang, lanjutkan apa yang kau lakukan sebelumnya: bersihkan jejaknya, bakar buktinya. 
 Itu satu-satunya yang bisa kau lakukan.]]
  },
  AvgDialog_18857_Content_62 = {
    Text = [[
Bocah itu berjalan menjauh dengan ekspresi kosong. 
 Aigis masuk ke dalam ruangan dan berlutut di samping tubuh hangat petugas keamanan.]]
  },
  AvgDialog_18857_Content_63 = {
    Text = "Dia melepas penutup matanya, ujung jari pria itu langsung mengeras dan berubah putih, mirip patung batu. Sebuah benda logam bulat terjatuh dari tangannya yang kaku, dan saat Aigis hendak mengambilnya, dia mendengar teriakan dari belakang."
  },
  AvgDialog_18857_Content_64 = {
    Text = "Ai, Aigis...?!"
  },
  AvgDialog_18857_Content_65 = {
    Text = "Saya membunuh orang itu, dan ketika saya bersiap untuk menangani mayatnya, Miss Sarah melihat saya."
  },
  AvgDialog_18857_Content_66 = {
    Text = "Dia menarikku keluar, mengusap darah di tanganku, dan meyakinkanku bahwa semuanya akan baik-baik saja, serahkan saja padanya."
  },
  AvgDialog_18857_Content_67 = {
    Text = "Saya baru saja memeriksa, ruangan itu bersih sekali, pasti Nona Sarah yang sudah membantu membersihkannya. \nDan——"
  },
  AvgDialog_18857_Content_68 = {
    Text = [[
Dia mengeluarkan sebuah kancing lengan yang berkilauan dari boneka beruang kecil dan menampilkannya di depan kalian. 
Baik model maupun bahannya sama persis dengan yang kalian temukan kemarin.]]
  },
  AvgDialog_18857_Content_69 = {
    Text = "Kalian menemukannya, kancing lengan yang aku jatuhkan di sana."
  },
  AvgDialog_18857_Content_7 = {
    Text = "Bayangan manusia perlahan tersinari. Itu adalah seorang anak, dia tanpa ekspresi, menatap lurus ke depan, di tangannya memegang sebuah belati tajam, ujung pisaunya masih meneteskan darah."
  },
  AvgDialog_18857_Content_70 = {
    Text = [[
Aku tidak percaya. Apapun motifmu, kamu bukan orang seperti itu, Aigis.
Kamu adalah anak yang baik. Beritahu kami kebenarannya, kita akan mencari solusi bersama, oke?]]
  },
  AvgDialog_18857_Content_71 = {
    Text = [[
...
Aku tidak memberitahumu bagaimana Tiyug sebenarnya meninggal.]]
  },
  AvgDialog_18857_Content_72 = {
    Text = "Aigis melepas penutup mata kanannya, memperlihatkan mata pucat seperti patung batu."
  },
  AvgDialog_18857_Content_73 = {Text = "Ini aku."},
  AvgDialog_18857_Content_74 = {
    Text = "Aku mengubahnya menjadi batu."
  },
  AvgDialog_18857_Content_75 = {
    Text = "Aigis, kita——"
  },
  AvgDialog_18857_Content_76 = {
    Text = "Jangan bicara lagi! Aku... adalah pelaku sebenarnya."
  },
  AvgDialog_18857_Content_77 = {
    Text = "Dia mundur selangkah sambil berbicara. Di sekitarnya, entah sejak kapan, muncul cairan hitam lengket yang siap bergerak sewaktu-waktu."
  },
  AvgDialog_18857_Content_8 = {
    Text = "<Shake: Ini, ini, ini... Lucy...? Apakah kamu, apakah kamu membunuh... membunuh...>"
  },
  AvgDialog_18857_Content_9 = {
    Text = "Dia tidak bisa menahan diri untuk berbalik dan memuntahkan seluruh makan malamnya yang sedikit di sudut dinding."
  },
  AvgDialog_18858_Content_1 = {
    Text = "Apakah mereka... pasien itu? Orang-orang yang dikatakan Aigis memiliki sesuatu yang hitam di tubuh mereka? Apakah ini bentuk yang akan mereka menjadi?"
  },
  AvgDialog_18858_Content_2 = {
    Text = "Apakah ini orang-orang yang... menghilang?"
  },
  AvgDialog_18859_Content_1 = {
    Text = "Di ruang hitam pekat, titik-titik kecil yang berkilauan dengan cahaya perak redup membentuk rangkaian, bergerak naik turun seperti gelombang yang mengikuti pola sulit ditebak."
  },
  AvgDialog_18859_Content_10 = {
    Text = "Titik cahaya tiba-tiba menjauh, dan ruang hitam dengan cepat menghilang."
  },
  AvgDialog_18859_Content_11 = {
    Text = "Kamu membuka mata dan tepat bertemu dengan tatapan Jenkin yang tampak bingung."
  },
  AvgDialog_18859_Content_12 = {
    Text = [[
01:14, Lily's Taring 
 Kamar Tamu]]
  },
  AvgDialog_18859_Content_13 = {
    Text = "%player%……? Ada apa, apakah ada masalah?"
  },
  AvgDialog_18859_Content_14 = {
    Text = "Jenkin mengusap-usap matanya, berniat untuk duduk, namun menyadari bahwa kedua tangannya terikat di belakang punggungnya."
  },
  AvgDialog_18859_Content_15 = {
    Text = "Apa yang terjadi?! Siapa yang melakukannya, cepat lepaskan aku!"
  },
  AvgDialog_18859_Content_16 = {
    Text = "Kamu mengangguk kepada Ramona. Dia mengeluarkan pedang tipisnya dan dengan cekatan memotong tali di pergelangan tangan Jenkin."
  },
  AvgDialog_18859_Content_17 = {
    Text = [[
Maaf, situasi mendesak, kami harus mengambil beberapa tindakan pencegahan. 
 Apakah... kamu masih ingat apa yang baru saja kamu lakukan?]]
  },
  AvgDialog_18859_Content_18 = {
    Text = "Bukankah aku baru saja tidur? Bersama Cokelat dan Aigis, aku bermimpi yang aneh-aneh… Tunggu, ini bukan kamar Aigis, kenapa aku ada di sini?"
  },
  AvgDialog_18859_Content_19 = {
    Text = "Kalian, apa maksud kalian membawaku ke sini? Jangan-jangan kalian mau menculik dan membungkamku!"
  },
  AvgDialog_18859_Content_2 = {
    Text = [[
Kamu berdiri di antara mereka, namun tergantung di atasnya. Kamu adalah salah satu dari mereka, tetapi tidak sesuai dengan mereka. 
 Kamu tidak tahu persis apa mereka itu, kamu hanya tahu bahwa kamu datang untuk mencari seseorang.]]
  },
  AvgDialog_18859_Content_20 = {
    Text = "Itu tidak sesuai dengan gaya dan aturan Penyelidik Universitas Mythag."
  },
  AvgDialog_18859_Content_22 = {
    Text = "Pedang Ramona segera terhunus. Mata pisaunya yang berwarna perak putih menggantung di sisi leher Clementine, namun dia sama sekali tidak takut. Sebaliknya, dengan santai dia menggunakan dua jarinya untuk menyingkirkan pedang tipis itu."
  },
  AvgDialog_18859_Content_23 = {
    Text = "Kamu waspada menatap wanita di depanmu — pintu dan jendela tidak terbuka, dia hampir muncul di hadapan kalian begitu saja. Tanpa suara, bak hantu."
  },
  AvgDialog_18859_Content_24 = {
    Text = "Siapa kamu sebenarnya? Bagaimana kamu bisa mengetahui identitas kami?"
  },
  AvgDialog_18859_Content_25 = {
    Text = "Apakah kamu dari Para pematung? Dan sayapmu tadi di dalam kabut… \n Kamu — apakah kamu manusia?"
  },
  AvgDialog_18859_Content_26 = {
    Text = [[
Saya hanyalah pihak ketiga yang antusias, meskipun saya memang memiliki sedikit kepentingan pribadi.
Kamu membuatku sangat tertarik, Penyelidik yang istimewa.]]
  },
  AvgDialog_18859_Content_27 = {
    Text = "Dia tersenyum ke arahmu, tatapannya yang tertuju padamu samar-samar mengandung semangat aneh yang mendalam."
  },
  AvgDialog_18859_Content_28 = {Text = "...Kenapa?"},
  AvgDialog_18859_Content_29 = {
    Text = [[
Itu bukan sesuatu yang bisa saya sembarangan berikan pendapat tentangnya. 
 Hanya keberadaan tertinggi itu yang dapat memberikan jawaban yang kau inginkan.]]
  },
  AvgDialog_18859_Content_3 = {
    Text = "\"Kakak... Kakak...\""
  },
  AvgDialog_18859_Content_30 = {
    Text = [[
Namun, sebagai permintaan maaf, aku tidak keberatan menjawab pertanyaanmu sebelumnya.
Seperti yang kau pikirkan, hati manusia terbuat dari Caro, sedangkan aku, aku memiliki Hati perak.]]
  },
  AvgDialog_18859_Content_31 = {
    Text = "Kalau begitu, kami tidak bisa membiarkanmu pergi."
  },
  AvgDialog_18859_Content_32 = {
    Text = [[
Jika hanya aku sendiri, tentu saja aku akan dengan senang hati pergi bersama kalian. 
Namun, aku juga harus mempertimbangkan pasienku, karena mereka saat ini sangat bergantung padaku.]]
  },
  AvgDialog_18859_Content_33 = {
    Text = "Clementine entah dari mana mengeluarkan sebuah liontin aneh dan menggoyangkannya perlahan. Rasa lelah yang tak tertahankan langsung menyerang tubuhmu. Kamu bersandar di tepi meja, berusaha tetap berdiri, namun tidak mampu melangkahkan kaki."
  },
  AvgDialog_18859_Content_34 = {
    Text = [[
Pedang tipis di tangan Ramona terjuntai ke bawah, kepalanya bergoyang pelan, hampir tak mampu membuka kedua matanya. 
 Jenkin terbaring di tanah, tak bergerak, tampaknya langsung tertidur.]]
  },
  AvgDialog_18859_Content_35 = {
    Text = "Apa... yang telah kau lakukan..."
  },
  AvgDialog_18859_Content_36 = {
    Text = [[
Hanya sedikit trik kecil yang memungkinkan aku keluar dari sini. 
Dengan kemampuanmu, seharusnya mudah untuk menghapusnya, bukan?]]
  },
  AvgDialog_18859_Content_37 = {
    Text = "Selamat tinggal, <Blue:Mata buta yang pucat>, kita di sini... akan bertemu sekali lagi."
  },
  AvgDialog_18859_Content_38 = {
    Text = "Dia membungkuk ke arahmu, lalu keluar dari ruangan. Kamu tidak bisa menahan diri lebih lama dan terjatuh kembali ke kursi."
  },
  AvgDialog_18859_Content_39 = {
    Text = "Clementine menutup pintu kamarnya, bersenandung pelan dengan lagu yang riang di tenggorokannya, melambaikan tangan dengan ceria ke ujung koridor, lalu berbalik dan pergi."
  },
  AvgDialog_18859_Content_4 = {
    Text = "Kamu melihat ke arah suara, titik cahaya yang sangat redup berkedip di lautan bintang. Benang hitam dengan kilauan logam aneh melilitnya, mengikatnya, membuatnya tak bisa bergerak."
  },
  AvgDialog_18859_Content_40 = {
    Text = [[
Di dalam kegelapan, gadis yang mengenakan rok berdiri tenang seperti patung. 
 Kepalanya tertunduk, dan dia dengan erat memegang penutup mata putih di tangannya.]]
  },
  AvgDialog_18859_Content_5 = {
    Text = "Dari balik garis hitam itu terdengar melodi riang yang samar, seperti lagu anak-anak yang dinyanyikan oleh seorang anak.\nPaman Charlie memiliki seekor kucing belang yang sangat ia cintai…."
  },
  AvgDialog_18859_Content_6 = {
    Text = "\"Kakak... jangan pergi...\""
  },
  AvgDialog_18859_Content_7 = {
    Text = "Suara Jenkin terdengar dari dalam gumpalan cahaya. Ia ingin mendekatimu, tetapi saat bergerak, ia langsung terikat kuat oleh benang hitam tipis, sehingga hanya bisa mundur, seperti boneka yang dikendalikan oleh tali."
  },
  AvgDialog_18859_Content_8 = {
    Text = [[
Kamu tiba-tiba menyadari bahwa seseorang, atau sesuatu, sedang mengendalikannya. 
 Ketika kamu ingin membantunya melepaskan diri dari belenggu itu, tiba-tiba benang hitam tersebut menipis dan akhirnya menghilang sepenuhnya.]]
  },
  AvgDialog_18859_Content_9 = {
    Text = "\"Tidak... Aigis...?\""
  },
  AvgDialog_18860_Content_1 = {
    Text = "Kalian mengejar Aigis sampai ke puncak menara lonceng."
  },
  AvgDialog_18860_Content_2 = {
    Text = "Aigis berdiri di atas platform, dia berbalik dengan mata tertutup, air mata berwarna darah bercampur D-lendir mengalir."
  },
  AvgDialog_18860_Content_3 = {
    Text = "Maaf... aku... tidak bisa bertahan lebih lama..."
  },
  AvgDialog_18860_Content_4 = {
    Text = "Tubuhnya dengan cepat membengkak, kulit dan dagingnya seperti mendidih, membentuk benjolan-benjolan bulat berbagai ukuran. Dalam waktu singkat, tubuh itu sudah menutupi tangga dan menyentuh langit-langit yang tinggi."
  },
  AvgDialog_18860_Content_5 = {
    Text = "Dalam suara mengerikan dari tubuh yang terpuntir dan membungkuk, hanya tersisa sedikit suara gadis itu."
  },
  AvgDialog_18860_Content_6 = {
    Text = "<Shake: Cepat... lari...>"
  },
  AvgDialog_18861_Content_1 = {
    Text = "Jangan menilai seseorang dari penampilannya"
  },
  AvgDialog_18861_Content_10 = {
    Text = "Suatu hari dia menghilang, dan dia mencarinya ke mana-mana."
  },
  AvgDialog_18861_Content_11 = {
    Text = "Kamu lari duluan! Jangan hiraukan kami! Cepat hubungi sekolah!"
  },
  AvgDialog_18861_Content_12 = {
    Text = "Dia membuka dan memeriksa lemari. Dia melihat ke bawah tempat tidur."
  },
  AvgDialog_18861_Content_13 = {
    Text = "<Shake: Se-sempai... Be-be-belakang!>"
  },
  AvgDialog_18861_Content_15 = {
    Text = "Cakar hitam yang tajam merobek kabut dan langsung mencengkeram rambut wanita itu."
  },
  AvgDialog_18861_Content_16 = {
    Text = "Pita merah perlahan melayang jatuh, dan kontur mata raksasa tiba-tiba muncul di dalam Bayangan."
  },
  AvgDialog_18861_Content_17 = {
    Text = "Dia berkeliling di basement tempat boiler sedang dinyalakan."
  },
  AvgDialog_18861_Content_18 = {
    Text = [[
Mata berkedip mengikuti irama lagu anak-anak, wajah pemuda itu memudar dan mengeras dalam sekejap.
Dia membuka mulutnya, namun jeritan dan tubuhnya langsung berubah menjadi patung batu.]]
  },
  AvgDialog_18861_Content_19 = {
    Text = "Ah……Ah!!"
  },
  AvgDialog_18861_Content_2 = {
    Text = "Kabut tebal menutupi kawasan yang lembap dan suram, cahaya kuning redup terpantul di genangan air di tanah, seolah-olah sedang menatap ke atas dunia yang kelam ini."
  },
  AvgDialog_18861_Content_20 = {
    Text = "Charlie tua tidak bisa menemukan kucing lorengnya di mana pun."
  },
  AvgDialog_18861_Content_21 = {
    Text = "<Shake: Tidak, tidak, jangan... tolong, tolong lepaskan aku...>"
  },
  AvgDialog_18861_Content_22 = {
    Text = "Jadi dia menangis dan menangis——"
  },
  AvgDialog_18861_Content_23 = {
    Text = "<Shake: Aku juga punya adik perempuan... Tolong... Jangan bunuh aku...>"
  },
  AvgDialog_18861_Content_24 = {
    Text = "——Hingga dirinya sendiri juga menghilang."
  },
  AvgDialog_18861_Content_25 = {
    Text = "<BigShake:Ah————!>"
  },
  AvgDialog_18861_Content_26 = {
    Text = [[
08:00, Universitas Mythag, Gedung Sistem Bangun
Kantor William Delaplume]]
  },
  AvgDialog_18861_Content_27 = {
    Text = [[
Kamu duduk di depan meja kerja, menahan pandangan William sambil dengan cermat memeriksa benda-benda di dalam nampan di hadapanmu: 
 sebuah patung tangan batu yang dipahat sangat hidup, dan sepotong pita merah dengan gesper perak berbentuk persegi.]]
  },
  AvgDialog_18861_Content_28 = {Text = "Bagaimana."},
  AvgDialog_18861_Content_29 = {
    Text = [[
Kamu merasa sedikit gugup. William bukan hanya seniormu, tetapi juga pelatihmu. 
Meskipun sekarang kamu sudah menjadi Penjaga resmi, kamu masih merasa seperti sedang menjalani ujiannya.]]
  },
  AvgDialog_18861_Content_3 = {
    Text = "Sebuah sepatu kulit menghancurkan bayangan di genangan air, lalu bergegas pergi."
  },
  AvgDialog_18861_Content_30 = {
    Text = [[
Ini seharusnya menjadi bagian dari patung. Namun, patung berongga seperti ini, aku baru pertama kali melihatnya. 
Dan di dalamnya ini... darah?]]
  },
  AvgDialog_18861_Content_31 = {
    Text = "Apakah ini ada hubungannya dengan dua siswa yang kabur dari sekolah?"
  },
  AvgDialog_18861_Content_32 = {
    Text = "Benar. Lima hari yang lalu, dua siswa meninggalkan sekolah secara diam-diam dan pergi ke <Blue:Londinium Timur>, dengan niat melakukan <Red:\"Penyelidikan kasus pembunuhan berantai si Pembungkus Anggota Tubuh\">."
  },
  AvgDialog_18861_Content_33 = {
    Text = "Pada malam itu, kedua orang tersebut di Jalan Bernard, dekat <Blue:Lily's Taring> mendengar teriakan minta tolong. Mereka pergi untuk memeriksa dan menemukan seorang wanita sedang dikejar oleh <Yellow:entitas Hidup yang tidak diketahui>."
  },
  AvgDialog_18861_Content_34 = {
    Text = "Dua siswa mematuhi moto sekolah, berusaha melakukan penyelamatan, namun mereka mengalami serangan. Pada akhirnya, siswa tahun pertama berhasil melarikan diri dan kembali ke sekolah pada pagi hari empat hari yang lalu, sedangkan siswa tahun kedua masih hilang."
  },
  AvgDialog_18861_Content_35 = {
    Text = [[
Tiga hari yang lalu, siswa tahun pertama terbangun dari pingsan dan menceritakan kembali acara tersebut. 
 Dia memberi tahu kami bahwa makhluk hidup itu tampaknya memiliki kemampuan untuk membatu, dan telah mengubah kaki seorang wanita menjadi batu.]]
  },
  AvgDialog_18861_Content_36 = {
    Text = "Petrifikasi? Jangan-jangan patung batu ini adalah... bagian dari siswa yang hilang?"
  },
  AvgDialog_18861_Content_37 = {
    Text = [[
Korban selamat tidak dapat dikenali, tetapi kemungkinan besar iya.
Adapun pita ini, sepertinya milik korban perempuan.]]
  },
  AvgDialog_18861_Content_38 = {
    Text = "Apakah di lokasi ditemukan <Yellow:Fenomena-d>? Kemampuan khusus seperti itu membuatku curiga bahwa entitas hidup yang tidak dikenal sebenarnya adalah Clades baru."
  },
  AvgDialog_18861_Content_39 = {
    Text = "Ini juga aneh. Clades sebagai <Yellow:inti D-rongga>, seharusnya melakukan <Yellow:Pelarutan tanpa pandang bulu> terhadap area sekitarnya. Aku belum pernah mendengar bahwa mereka akan menyerang secara aktif."
  },
  AvgDialog_18861_Content_4 = {
    Text = "Cepat! Itu akan segera mengejar!"
  },
  AvgDialog_18861_Content_40 = {
    Text = "Dan selain sedikit <Yellow:D-lendir>, kami tidak menemukan tanda-tanda Pelarutan yang jelas di lokasi, bahkan di seluruh kawasan Timur, ini tidak sesuai dengan <Yellow:karakteristik Pelarutan> dari D-rongga."
  },
  AvgDialog_18861_Content_41 = {
    Text = "Saat ini, yang dapat kami pastikan adalah: kasus hilangnya orang-orang yang terjadi akhir-akhir ini di <Blue:Lilyan Taring> dan area sekitarnya, bahkan kasus <Red:\"Pemutilasi\">, kemungkinan besar berkaitan dengan entitas Hidup itu."
  },
  AvgDialog_18861_Content_42 = {
    Text = "Setelah analisis awal, kami memperkirakan bahwa entitas kehidupan yang tidak dikenal sangat mungkin bersembunyi di Taring tempat Lily bekerja."
  },
  AvgDialog_18861_Content_43 = {
    Text = "Sepertinya, kita harus pergi ke sana untuk menyelidiki."
  },
  AvgDialog_18861_Content_44 = {
    Text = "Benar. Mengonfirmasi keberadaan siswa yang hilang, menyelidiki kebenaran di balik Acara tersebut, menemukan serta menghentikan dalang di balik peristiwa ini adalah tujuan misi Anda kali ini."
  },
  AvgDialog_18861_Content_45 = {
    Text = "Bagaimana, %player%, apakah kamu bisa melakukannya?"
  },
  AvgDialog_18861_Content_46 = {
    Text = "Sangat mudah."
  },
  AvgDialog_18861_Content_47 = {
    Text = "Aku akan berusaha semaksimal mungkin."
  },
  AvgDialog_18861_Content_48 = {
    Text = "Baik. Mengingat target kali ini mungkin memiliki kecerdasan yang cukup tinggi, saya sarankan kalian mengambil alat penyamaran di departemen logistik sebelum berangkat, agar tidak menimbulkan kecurigaan."
  },
  AvgDialog_18861_Content_49 = {
    Text = "Bawalah pita ini, mungkin bisa digunakan untuk menyelidiki alasan serangan entitas hidup yang tidak dikenal terhadap pemiliknya. Jika memungkinkan, konfirmasikan juga identitas korban."
  },
  AvgDialog_18861_Content_5 = {
    Text = "Tiga orang berlari dengan panik di tengah kabut, napas mereka tersengal-sengal, seperti tikus yang diincar kucing, panik tanpa memilih jalan di bawah nyanyian riang."
  },
  AvgDialog_18861_Content_50 = {
    Text = "Tingkat bahaya misi tidak terlalu tinggi, kami akan menjaga komunikator tetap terhubung, <Blue:Boneka> dan <Blue:Erica> juga akan memberikan panduan dan bantuan kepadamu kapan saja."
  },
  AvgDialog_18861_Content_51 = {
    Text = "Kamu menyentuh lencana sekolah di dada, <Blue:Fragmen Inti Perak> yang tertanam di dalamnya adalah jaminan komunikasi jarak jauh kalian."
  },
  AvgDialog_18861_Content_52 = {
    Text = "Tidak ada waktu untuk disia-siakan, ayo segera berangkat."
  },
  AvgDialog_18861_Content_53 = {
    Text = "Semoga Kunci Perak menuntun jalanmu."
  },
  AvgDialog_18861_Content_54 = {
    Text = [[
13:07, Londinium Timur
Sebuah gang kecil]]
  },
  AvgDialog_18861_Content_55 = {
    Text = "Beberapa anak yang berpakaian sederhana, kurus dan kecil sedang berjongkok di gang, sepertinya sedang membicarakan sesuatu."
  },
  AvgDialog_18861_Content_56 = {
    Text = "Lagi-lagi seperti biasa, aku dan Cokelat yang bertindak, kalian bertugas mengalihkan perhatian orang yang tidak bersalah itu dan beri aku waktu. Setelah selesai, berkumpul di pintu belakang Taring."
  },
  AvgDialog_18861_Content_57 = {
    Text = "Apakah kamu tidak berniat kembali ke Taring?"
  },
  AvgDialog_18861_Content_58 = {
    Text = "Harus beli makanan dulu. Roti di tempat itu lebih keras daripada batu, bahkan tidak bisa ditelan. Aku benar-benar tidak tahan."
  },
  AvgDialog_18861_Content_59 = {
    Text = "Ibu Blake dari kedai susu berkata, begitu seseorang masuk ke sana, mereka tidak akan bisa keluar, bahkan setelah mati, itu sangat menakutkan, apakah kakakmu sudah..."
  },
  AvgDialog_18861_Content_6 = {
    Text = "Paman Charlie memiliki seekor kucing tabby yang sangat dia sayangi."
  },
  AvgDialog_18861_Content_60 = {
    Text = "Jangan bicara sembarangan! Kakak perempuan pasti akan baik-baik saja, kan Jenkin?"
  },
  AvgDialog_18861_Content_61 = {
    Text = [[
Gadis itu tidak menjawab, hanya menatap ke luar gang. 
 Tikus di pundaknya menyentuhnya dengan hidungnya, seakan memberi penghiburan atau mungkin menunjukkan rasa khawatir.]]
  },
  AvgDialog_18861_Content_62 = {
    Text = [[
Di jalan yang ramai oleh keramaian, sebuah mobil hitam mengkilap perlahan berhenti. 
 Dua orang turun dari mobil itu, mereka berpakaian elegan, salah satunya memiliki rambut perak yang memukau.]]
  },
  AvgDialog_18861_Content_63 = {
    Text = [[
Lihat dua orang yang terlihat seperti target empuk itu? Mereka adalah sasaran kita hari ini. 
 Bersiaplah untuk memulai!]]
  },
  AvgDialog_18861_Content_64 = {
    Text = [[
13:10, Londinium Timur
Sebuah jalan]]
  },
  AvgDialog_18861_Content_65 = {
    Text = "Begitu kamu turun dari mobil, kamu langsung merasa sesak karena kelembapan yang pekat dan bau busuk pembusukan."
  },
  AvgDialog_18861_Content_66 = {
    Text = "Perasaan pusing yang kuat disertai dengan dering telinga yang keras tiba-tiba menyerangmu. Gambar buram berkedip cepat di pikiranmu, seolah-olah pada suatu waktu, kamu pernah melihat adegan serupa."
  },
  AvgDialog_18861_Content_67 = {
    Text = [[
Apakah itu ilusi, atau mungkin itu bagian dari memori yang hilang? 
Sebelum kamu sempat merenungkannya, kamu tersenggol oleh sekumpulan anak-anak yang berlarian sambil bermain.]]
  },
  AvgDialog_18861_Content_68 = {Text = "!"},
  AvgDialog_18861_Content_69 = {
    Text = "Kamu menahan lenganmu yang terasa sakit akibat benturan, dan menyadari bahwa Ramona sedang memandangmu dengan senyuman samar."
  },
  AvgDialog_18861_Content_7 = {
    Text = "Kakiku, kakiku tidak bisa bergerak. Tolong selamatkan aku! Tolong selamatkan aku!"
  },
  AvgDialog_18861_Content_70 = {Text = "Ada apa?"},
  AvgDialog_18861_Content_71 = {
    Text = [[
Dia menunjuk ke arah sakumu, dan saat kamu mengikuti arah jarinya, tiba-tiba teringat sebuah kalimat. 
"Upacara penyambutan paling terkenal di Timur adalah membuat dompetmu menghilang tanpa kamu sadari."]]
  },
  AvgDialog_18861_Content_72 = {
    Text = "Apa? … Dompetku!"
  },
  AvgDialog_18861_Content_73 = {
    Text = "Cepat kejar, %player%, kalau terlambat bulan ini kita tidak akan mampu membeli kue kecil."
  },
  AvgDialog_18861_Content_8 = {Text = "Nyonya!"},
  AvgDialog_18861_Content_9 = {
    Text = "Senior, jangan ke sana, Senior!"
  },
  AvgDialog_18862_Content_1 = {
    Text = "Ramona berhasil menahan serangan Aigis. Aigis terhuyung mundur beberapa langkah, kedua tangannya sedikit bergetar, dan cairan hitam kental mengalir deras dari celah jari-jarinya yang menutupi matanya."
  },
  AvgDialog_18862_Content_10 = {
    Text = "Jangan mendekat… Jangan mendekat!"
  },
  AvgDialog_18862_Content_11 = {
    Text = "Gadis itu berbalik dan langsung berlari."
  },
  AvgDialog_18862_Content_12 = {Text = "Aigis!"},
  AvgDialog_18862_Content_13 = {
    Text = "Jangan berteriak lagi, cepat kejar!"
  },
  AvgDialog_18862_Content_2 = {
    Text = "Aigis, apakah kamu baik-baik saja?"
  },
  AvgDialog_18862_Content_3 = {
    Text = "Dia tiba-tiba mengangkat kepalanya dengan gemetaran, pandangannya terkadang kabur dan terkadang jelas."
  },
  AvgDialog_18862_Content_4 = {
    Text = "Bagaimana, bagaimana bisa… Tidak, tidak, aku jelas tidak tertidur, jangan…"
  },
  AvgDialog_18862_Content_5 = {Text = "Aigis?"},
  AvgDialog_18862_Content_6 = {
    Text = "Jangan bicara, jangan, jangan. Sekarang belum gelap, belum berkabut. Kamu tidak bisa mengendalikanku, tidak bisa…!"
  },
  AvgDialog_18862_Content_7 = {
    Text = "Aigis menutupi kepalanya, tubuh kecilnya membungkuk ke depan akibat rasa sakit yang tak terduga."
  },
  AvgDialog_18862_Content_8 = {
    Text = "Tidak bisa... dijadikan patung lilin... Aku tidak mau, aku tidak mau..."
  },
  AvgDialog_18862_Content_9 = {
    Text = "Apakah kamu mendengar sesuatu, Aigis?"
  },
  AvgDialog_18863_Content_1 = {
    Text = "***Dia tampaknya tidak sakit, jadi kenapa dia bisa gila! Aigis, hati-hati, menghindar!"
  },
  AvgDialog_18863_Content_2 = {
    Text = "Dia bilang sudah menjalani sembuh, mungkin saat itulah…\nPokoknya, harus membawanya ke tempat yang lebih sepi."
  },
  AvgDialog_18863_Content_3 = {
    Text = "Sebelum itu, mari kita selesaikan mereka terlebih dahulu."
  },
  AvgDialog_18864_Content_1 = {
    Text = "Kamu dan Ramona mundur sambil bertarung, tanpa mengganggu orang lain, kalian berhasil mencapai halaman depan Taring."
  },
  AvgDialog_18864_Content_2 = {
    Text = "Kabut muncul lagi!"
  },
  AvgDialog_18864_Content_3 = {
    Text = "Entah sejak kapan, kabut tebal telah menyelimuti segalanya. Bersamaan dengan kabut itu, terdengar suara erangan aneh yang berasal dari tempat yang tak terjangkau oleh pandangan, dan perlahan-lahan mendekati kalian."
  },
  AvgDialog_18864_Content_4 = {
    Text = "Kamu dan Ramona bersandar pada punggung satu sama lain, waspada memandangi bayangan-bayangan yang terdistorsi."
  },
  AvgDialog_18864_Content_5 = {
    Text = "Bagaimana mungkin ada anomali di sini? Bukankah pasien sudah dikunci?"
  },
  AvgDialog_18864_Content_6 = {
    Text = "Tidak peduli dari mana asalnya, pukul saja mundur!"
  },
  AvgDialog_18864_Content_7 = {
    Text = "Ramona mengayunkan pedang tipisnya dan secara aktif menyerang beberapa monster terdekat dari kalian."
  },
  AvgDialog_18865_Content_1 = {
    Text = "Tubuh abnormal itu jatuh di depan pedang Ramona, tak lama kemudian berubah menjadi serpihan debu hitam yang halus, menghilang di udara."
  },
  AvgDialog_18865_Content_10 = {
    Text = "Kamu menarik napas dalam-dalam dan meluruskan tubuh."
  },
  AvgDialog_18865_Content_11 = {
    Text = "Hati-hati, Ramona."
  },
  AvgDialog_18865_Content_12 = {
    Text = "Tenang saja, aku tahu batasnya."
  },
  AvgDialog_18865_Content_2 = {
    Text = "Kamu menghapus keringat di dahimu, terengah-engah sambil berkedip beberapa kali dengan kuat."
  },
  AvgDialog_18865_Content_3 = {Text = "Apa kabar?"},
  AvgDialog_18865_Content_4 = {
    Text = "Tidak apa-apa. Hanya kepala terasa sedikit pusing."
  },
  AvgDialog_18865_Content_5 = {
    Text = "Otakku terasa seperti ingin keluar melalui mata."
  },
  AvgDialog_18865_Content_6 = {
    Text = "Masih bisa bercanda, tampaknya tidak ada masalah serius."
  },
  AvgDialog_18865_Content_7 = {
    Text = "Butuh istirahat sejenak?"
  },
  AvgDialog_18865_Content_8 = {
    Text = "Lebih baik segera menemukan Jenkin, aku merasa ada sesuatu yang tidak sesederhana itu."
  },
  AvgDialog_18865_Content_9 = {
    Text = "Sebuah sosok kecil muncul dari kabut di hadapanmu, lututnya sedikit ditekuk, tubuhnya tegang, jelas dalam posisi menyerang."
  },
  AvgDialog_18866_Content_1 = {
    Text = "Di sana, tidak ada banyak orang. Apakah kamu salah lihat?"
  },
  AvgDialog_18866_Content_2 = {
    Text = "Nona Mary, ke mana kamu akan pergi? Hei, Nona Mary!"
  },
  AvgDialog_18867_Content_1 = {Text = "%player%!"},
  AvgDialog_18867_Content_10 = {
    Text = "Nona Sarah, aku sangat takut, tolong..."
  },
  AvgDialog_18867_Content_11 = {
    Text = "Nyonya Sarah…"
  },
  AvgDialog_18867_Content_12 = {
    Text = "Ada apa, Aigis?"
  },
  AvgDialog_18867_Content_13 = {
    Text = "Nyonya Sarah, bisakah kamu menyanyikan lagu itu sekali lagi, hanya sekali? Maksudku, jika itu tidak merepotkanmu..."
  },
  AvgDialog_18867_Content_14 = {
    Text = "Aigis yang tercinta, dengarkan baik-baik. Kamu adalah anak yang paling penurut, paling patuh, dan paling mengerti di seluruh Taring. Kamu adalah yang paling disukai semua orang."
  },
  AvgDialog_18867_Content_15 = {
    Text = "Jadi, sesekali bersikap manja juga tidak masalah, lho. Mengerti?"
  },
  AvgDialog_18867_Content_16 = {
    Text = "Itu... aku, aku ingin mendengar Sarah menyanyikan lagu anak-anak lagi."
  },
  AvgDialog_18867_Content_17 = {
    Text = "Tidak masalah. \n Om Charlie memiliki seekor kucing belang yang sangat dia cintai…"
  },
  AvgDialog_18867_Content_18 = {
    Text = "Kamu tiba-tiba membuka mata lebar-lebar dan terjatuh ke dalam dunia nyata yang penuh warna."
  },
  AvgDialog_18867_Content_19 = {
    Text = "%player%, apakah kamu baik-baik saja?"
  },
  AvgDialog_18867_Content_2 = {
    Text = "Saat Ramona menahan Sarah di kejauhan, kamu dengan cepat berkonsentrasi dan menenggelamkan diri ke dalam ruang hitam pekat yang mulai terasa semakin familiar."
  },
  AvgDialog_18867_Content_20 = {
    Text = [[
Kamu menahan rasa pusing dan mengangguk. 
 Pada saat itu, pandanganmu sekilas menangkap sosok berwarna putih.]]
  },
  AvgDialog_18867_Content_21 = {
    Text = "Aigis? Di sini sangat berbahaya, cepat kembali ke Jenkin."
  },
  AvgDialog_18867_Content_22 = {
    Text = "Nona Sarah, apakah Anda sedang tidur?"
  },
  AvgDialog_18867_Content_23 = {Text = "...?"},
  AvgDialog_18867_Content_24 = {
    Text = "Yah, Nona Sarah sudah lama sekali tidak tidur dengan nyenyak."
  },
  AvgDialog_18867_Content_25 = {
    Text = "Agar Taring tidak dibubarkan, dia selalu berlarian ke sana kemari, bertemu dengan tuan-tuan kaya dan nyonya-nyonya yang tinggal di istana, tidak punya waktu untuk makan, tidak punya waktu untuk beristirahat."
  },
  AvgDialog_18867_Content_26 = {
    Text = "Pada malam hari, setelah kembali ke Taring, dia menyalakan lilin di kantor dan terus menghitung, terus menghitung, untuk melihat apakah uang yang diterima dari Tuan cukup untuk digunakan."
  },
  AvgDialog_18867_Content_27 = {
    Text = "Lihat berapa banyak uang yang bisa didapat dari menjual perhiasan yang diperoleh dari para nyonya dan nona."
  },
  AvgDialog_18867_Content_28 = {
    Text = "Mereka semua menertawakannya dan mengatakan hal-hal yang menyakitkan, tetapi Nona Sarah tidak pernah marah. Dia justru menghiburku dan bernyanyi untuk kami."
  },
  AvgDialog_18867_Content_29 = {
    Text = "Dia sangat baik kepada kami, sungguh. Dia juga sangat baik padaku, bahkan lebih baik lagi."
  },
  AvgDialog_18867_Content_3 = {
    Text = "Kunci perak bergetar dengan hebat, kegelapan di depan matamu berubah beberapa kali, dan perlahan cahaya mulai muncul dari tepi pandanganmu."
  },
  AvgDialog_18867_Content_30 = {
    Text = "Saya adalah beban bagi Ibu, dan Ibu membuang saya. Tuan pengurus sebelumnya menolak untuk menerima saya, tapi Nyonya Sarah mengatakan bahwa dia bersedia bekerja dua kali lipat demi membawa saya masuk."
  },
  AvgDialog_18867_Content_31 = {
    Text = "Sejak saat itu, aku bersumpah untuk tidak menjadi beban bagi Nona Sarah dan harus menjadi anak yang berguna."
  },
  AvgDialog_18867_Content_32 = {
    Text = "Maafkan saya, Nona Sarah. Saya sudah berusaha sekuat tenaga, namun tetap saja tidak bisa melindungi Xiao Mai dan juga tidak bisa melindungi Anda. Maafkan saya."
  },
  AvgDialog_18867_Content_33 = {
    Text = "Aigis dengan lembut menyentuh pipi Sarah, lalu berbalik ke arah kalian."
  },
  AvgDialog_18867_Content_34 = {
    Text = "Aigis, kamu…"
  },
  AvgDialog_18867_Content_35 = {
    Text = "Apakah kalian ingin tahu apa yang terjadi semalam?"
  },
  AvgDialog_18867_Content_36 = {
    Text = "Gadis itu menyeringai, memperlihatkan ekspresi yang hanya bisa disebut sebagai senyuman dengan susah payah."
  },
  AvgDialog_18867_Content_37 = {
    Text = [[
Bebaskan Lucy, dan juga Sarah. 
 Aku adalah Jack the Ripper yang kalian cari selama ini.]]
  },
  AvgDialog_18867_Content_4 = {
    Text = "Kak Sasa, perutku sangat lapar."
  },
  AvgDialog_18867_Content_5 = {
    Text = "Sayang sekali, Nona Sarah, kami tidak dapat melanjutkan dukungan kepada kalian lagi."
  },
  AvgDialog_18867_Content_6 = {
    Text = "Nona Sarah, kenapa ibu tidak mau saya lagi?"
  },
  AvgDialog_18867_Content_7 = {
    Text = "Bayangan hitam dan putih berkelebat bergantian, seakan-akan beberapa film diputar secara bersamaan di satu layar. Tak peduli seberapa keras kamu berusaha, kamu tetap tidak bisa melihat dengan jelas isi di dalamnya."
  },
  AvgDialog_18867_Content_8 = {
    Text = "Nona Sarah, Ibu pernah berkata bahwa aku hanyalah sampah... Apakah hal-hal ini benar-benar bisa diserahkan kepadaku?"
  },
  AvgDialog_18867_Content_9 = {
    Text = "Nona Sarah, Ibu sudah tidak menginginkan saya lagi, kau... apakah kau juga akan meninggalkan saya...?"
  },
  AvgDialog_18868_Content_1 = {
    Text = "Ya Tuhan... ini..."
  },
  AvgDialog_18868_Content_2 = {
    Text = "Tenang, Nona Sarah, Dr. Miller pasti akan membantu para pasien."
  },
  AvgDialog_18868_Content_3 = {
    Text = "Nona Sarah, tolong susun kembali tim ini. Semakin cepat pemilihan selesai, mereka bisa segera menerima Sembuh."
  },
  AvgDialog_18869_Content_1 = {
    Text = "Semuanya, tenanglah!"
  },
  AvgDialog_18869_Content_2 = {
    Text = "Saya sangat tenang. Sebaiknya tanyakan padanya apa yang sebenarnya dia lakukan terhadap Aigis, hingga membuat Aigis begitu takut!"
  },
  AvgDialog_18869_Content_3 = {
    Text = "Apa kau mengerti! Ini demi kesejahteraan umat manusia!"
  },
  AvgDialog_18870_Content_1 = {
    Text = "Rahasia kita"
  },
  AvgDialog_18870_Content_10 = {
    Text = [[
Telah diambil. 
Saat ini tidak ada catatan terkait, sangat disayangkan. Disarankan untuk mengajukan permohonan bantuan penyelidikan.]]
  },
  AvgDialog_18870_Content_11 = {
    Text = "Penyelidik Ramona, nomor komunikator I-3017, secara resmi mengajukan laporan terhadap Clementine Fairfax, diduga sebagai Pembangun non-<Blue:《Perjanjian》>, saat ini menyamar sebagai Dokter George Rogers."
  },
  AvgDialog_18870_Content_12 = {
    Text = [[
Permohonan bantuan penyelidikan telah diterima. 
 Persetujuan telah diberikan dan telah dialihkan ke <Blue:Departemen Penyelidikan Mythag>.]]
  },
  AvgDialog_18870_Content_13 = {
    Text = [[
Permohonan telah diajukan, sisanya serahkan saja kepada tim penyelidikan. 
 Masih ada waktu sebelum matahari terbit, apakah kamu ingin beristirahat sejenak?]]
  },
  AvgDialog_18870_Content_14 = {
    Text = "Tidak, untuk meyakinkan Boneka, kita harus segera menemukan petunjuk yang terobosan, atau seorang tersangka."
  },
  AvgDialog_18870_Content_15 = {
    Text = "Kamu sedang membicarakan Sarah."
  },
  AvgDialog_18870_Content_16 = {
    Text = "Minuman yang dia berikan pasti bukan hanya sekadar teh. Lagipula, sulit dipercaya bahwa seseorang yang lama tinggal di Taring akan takut pada bayangan."
  },
  AvgDialog_18870_Content_17 = {
    Text = "Sekarang dia mengira kita sudah tertidur, kemungkinan besar akan melonggarkan kewaspadaannya."
  },
  AvgDialog_18870_Content_18 = {
    Text = [[
Pergi. Lihat dulu di koridor itu, lalu pergi ke kantornya. 
Dia mungkin menjadi titik terobosan kita.]]
  },
  AvgDialog_18870_Content_19 = {
    Text = [[
01:15, Lily's Taring 
 Kamar Tamu]]
  },
  AvgDialog_18870_Content_2 = {
    Text = [[
01:13, Lily's Taring 
 Kamar Tamu]]
  },
  AvgDialog_18870_Content_20 = {
    Text = [[
Aigis diam-diam membuka pintu, lalu berjalan mendekati Jenkin yang sedang tidur. 
 Setelah berdiri sejenak, dia mulai menangis dengan tertahan-tahan.]]
  },
  AvgDialog_18870_Content_21 = {
    Text = "Kamu baik-baik saja, kamu baik-baik saja, syukurlah…! Maafkan aku, maafkan aku, maafkan aku."
  },
  AvgDialog_18870_Content_22 = {
    Text = "Saya seharusnya datang lebih awal, saya seharusnya mencobanya, meskipun saya tidak berguna, meskipun saya…\nDokter Clemetine benar, tapi…"
  },
  AvgDialog_18870_Content_23 = {
    Text = [[
Aku akan memikirkannya dengan jelas, aku akan tahu... 
 Aku pasti akan mengetahuinya.]]
  },
  AvgDialog_18870_Content_24 = {
    Text = "Dia pergi dengan suara pelan, dan pada saat pintu kamar tertutup, Jenkin membuka matanya dengan tenang."
  },
  AvgDialog_18870_Content_25 = {
    Text = [[
01:37, Lily Taring 
 Koridor]]
  },
  AvgDialog_18870_Content_26 = {
    Text = [[
Kalian dengan hati-hati mendekati tempat kalian bertemu Sarah dan Aigis tidak lama ini. 
Ini adalah ujung koridor, selain dinding dan jendela yang menghadap ke halaman belakang, hanya ada satu pintu yang patut diperhatikan.]]
  },
  AvgDialog_18870_Content_27 = {
    Text = "Ramona mendorong pintu kamar, cahaya senter menyapu tempat tidur dan lemari, menerangi partikel debu yang melayang di udara."
  },
  AvgDialog_18870_Content_28 = {
    Text = "Ini adalah... kamar lama?"
  },
  AvgDialog_18870_Content_29 = {
    Text = "Ramona berjongkok, jari-jarinya menyentuh celah bata lalu menciumnya dengan lembut."
  },
  AvgDialog_18870_Content_3 = {
    Text = [[
Setelah kilauan menyilaukan dari kunci perak yang sangat mencolok, kamu dan Ramona merasa tubuhmu menjadi ringan, lalu segera mengejar keluar pintu. 
 Di koridor, selain kalian berdua, tidak ada seorang pun.]]
  },
  AvgDialog_18870_Content_30 = {
    Text = [[
Ada bau darah, sangat samar. Sepertinya sudah dibersihkan oleh seseorang. 
 Dari tingkat kelembapan, itu terjadi hanya dalam satu jam terakhir.]]
  },
  AvgDialog_18870_Content_31 = {
    Text = "Dia menyorotkan senter ke sekitar tanah. Noda air yang tersisa di antara celah-celah bata sedikit memantulkan cahaya, bahkan kamu melihat cairan hitam yang mengandung firasat buruk di beberapa celah."
  },
  AvgDialog_18870_Content_32 = {
    Text = [[
Apa yang sebenarnya terjadi? Siapa yang terluka, atau mati?
Apakah ini perbuatan si Pembunuh Anggota Tubuh? Atau makhluk hidup yang tidak dikenal?]]
  },
  AvgDialog_18870_Content_33 = {
    Text = "Berdasarkan kondisi penemuan mayat sebelumnya, ada selisih waktu hanya sekitar sepuluh menit antara si pembungkam dan kami. Meskipun kami memerlukan waktu untuk memeriksa mayat tersebut, kami tidak tertinggal terlalu jauh darinya."
  },
  AvgDialog_18870_Content_34 = {
    Text = [[
Sedangkan dari ukuran jejak kaki, si pembunuh mungkin... seorang anak. 
 Tapi tadi saat kami berkeliling di Taring bersama Sarah, kami tidak melihat ada anak dengan noda darah di tubuhnya.]]
  },
  AvgDialog_18870_Content_35 = {
    Text = "Dalam waktu sesingkat itu, menyelesaikan tugas seperti membunuh, mengumpulkan jarahan, melarikan diri, membunuh untuk kedua kalinya, serta menyembunyikan identitas. Saya pikir mustahil bagi seorang individu untuk melakukannya."
  },
  AvgDialog_18870_Content_36 = {
    Text = "Maksudmu, anak ini sangat mungkin memiliki seorang kaki tangan?"
  },
  AvgDialog_18870_Content_37 = {
    Text = "Bahkan mungkin sebagai pelaku bersama, di mana saat salah satu pihak melakukan kejahatan, pada saat yang sama atau hampir bersamaan, kejahatan kedua terjadi di sini."
  },
  AvgDialog_18870_Content_38 = {
    Text = "Apakah mungkin Sarah? Dia punya cukup waktu, dan dia juga ada di sini."
  },
  AvgDialog_18870_Content_39 = {
    Text = "Saat ini, petunjuk yang ada tidak cukup untuk menarik kesimpulan."
  },
  AvgDialog_18870_Content_4 = {
    Text = "Dia berkata dia memiliki \"Hati perak\", kemungkinan besar semacam entitas Bangun. Lalu..."
  },
  AvgDialog_18870_Content_40 = {
    Text = [[
Ramona berjalan ke sudut dinding, membungkuk, dan meraba-raba dalam kegelapan hingga menemukan sebuah benda logam kecil. 
 Itu adalah sebuah kancing lengan yang bernoda darah.]]
  },
  AvgDialog_18870_Content_41 = {
    Text = [[
Melihat dari kerajinannya, ini seharusnya salah satu dari "perhiasan emas dan perak" yang disebutkan Jenkin milik Sarah. 
 Ayo pergi ke kantor, siapa tahu kita bisa menemukan lebih banyak bukti.]]
  },
  AvgDialog_18870_Content_42 = {
    Text = [[
01:55, Lily's Taring 
 Ruang Kerja Kepala Sekolah]]
  },
  AvgDialog_18870_Content_43 = {
    Text = "Seperti yang kuduga, %player%, lihat."
  },
  AvgDialog_18870_Content_44 = {
    Text = "Ramona mengeluarkan sebuah botol kecil berwarna cokelat dari laci meja kerjanya. Kamu menerimanya dan melihat bahwa ada label di atasnya, bertuliskan nama obat serta khasiatnya."
  },
  AvgDialog_18870_Content_45 = {
    Text = "Dapat membantu pasien menenangkan Roh, membantu tidur —— sepertinya inilah bahan tambahan dalam teh kita."
  },
  AvgDialog_18870_Content_46 = {
    Text = "Untungnya, dia masih belum bisa menguasai takaran obat dengan baik, jika tidak, malam ini akan berakhir dengan cara yang berbeda untukmu dan aku."
  },
  AvgDialog_18870_Content_47 = {
    Text = "Ngomong-ngomong, apa maksud dari Jenkin itu? Sarah juga tidak terlihat seperti memiliki kemampuan untuk mengendalikan roh orang lain… Hmm? Apa ini."
  },
  AvgDialog_18870_Content_48 = {
    Text = [[
Sambil berbicara, kamu membuka laci dan menemukan sebuah buku bersampul hitam yang tersembunyi di bagian bawah. 
Kamu meletakkannya di atas meja dan membukanya, hanya untuk menemukan bahwa halaman-halamannya penuh dengan nama-nama yang tertulis rapat.]]
  },
  AvgDialog_18870_Content_49 = {
    Text = "John Douglas, Diana Wolf …… Daftar Taring? Juga mencantumkan jenis kelamin, usia, dan situasi keluarga. Namun, di bagian belakang ini ……"
  },
  AvgDialog_18870_Content_5 = {
    Text = "Kamu menutup mata dan memaksa dirimu untuk kembali ke dunia ilusi itu. Namun, kamu merasa seolah-olah ada selubung di depan matamu, membuat segalanya tampak kabur dan tidak jelas."
  },
  AvgDialog_18870_Content_50 = {
    Text = "Di belakang setiap nama terdapat logo yang mewakili mata uang umum Kerajaan Leo, <Blue:Taring>, dan di belakang logo tersebut terdapat angka."
  },
  AvgDialog_18870_Content_51 = {
    Text = "Deretan angka dan informasi personel yang tertata rapi membuatmu sesaat bingung, apakah ini daftar pekerja Taring, atau daftar barang dari sebuah majalah belanja."
  },
  AvgDialog_18870_Content_52 = {
    Text = "Harga setiap orang berbeda, pria, wanita... anak-anak."
  },
  AvgDialog_18870_Content_53 = {
    Text = [[
Benar-benar memperlakukan orang seperti barang dagangan. 
 Siapa? Siapa yang akan melakukan transaksi seperti itu dengannya?]]
  },
  AvgDialog_18870_Content_54 = {
    Text = "Masih ingat siapa yang membantu pasien dalam perawatan, kan, Sarah?"
  },
  AvgDialog_18870_Content_55 = {
    Text = "Institut Dr. Miller. Apakah institut itu adalah penyamaran dari Para pematung?"
  },
  AvgDialog_18870_Content_56 = {
    Text = [[
Ada kemungkinan itu. Mari kita bawa bukti penting terlebih dahulu.
Besok kita coba mengorek informasi dari Sarah, lihat apakah kita bisa mendapatkan sesuatu darinya.]]
  },
  AvgDialog_18870_Content_57 = {
    Text = [[
01:50, Taring Lily 
 Suatu tempat di halaman belakang]]
  },
  AvgDialog_18870_Content_58 = {
    Text = "Sarah menggesekkan korek api dan melemparkannya ke dalam tumpukan kayu di depannya."
  },
  AvgDialog_18870_Content_59 = {
    Text = "Dengan bantuan katalis bensin, api dengan cepat menyala dan melahap pakaian yang ternoda darah."
  },
  AvgDialog_18870_Content_6 = {
    Text = "Bagian belakang kepala mulai terasa nyeri berdenyut-denyut. Di tengah suara dering telinga yang tajam, kamu menopang dahi dan terpaksa menghentikan upaya penelusuran."
  },
  AvgDialog_18870_Content_60 = {
    Text = "Dia berdiri dalam diam selama beberapa saat, memastikan bahwa api tidak akan padam, lalu berbalik dan pergi."
  },
  AvgDialog_18870_Content_7 = {
    Text = "Kamu sudah sangat lelah hari ini, jangan memaksakan diri."
  },
  AvgDialog_18870_Content_8 = {
    Text = "Tapi Clementine... tidak bisa membiarkannya begitu saja..."
  },
  AvgDialog_18870_Content_9 = {
    Text = [[
Kita bisa meminta bantuan kepada tim pendukung. 
Erica, periksa informasi tentang Clementine Fairfax.]]
  },
  AvgDialog_18871_Content_1 = {
    Text = "Dompetku, kue kecilku…"
  },
  AvgDialog_18871_Content_2 = {
    Text = "Coba bersikap lebih terbuka. Siapa tahu, mungkin kali ini misi bisa diselesaikan dengan baik dan kita bisa mendapatkan hadiah tambahan."
  },
  AvgDialog_18871_Content_3 = {
    Text = "Kalau memang tidak bisa, aku juga tidak keberatan untuk berbagi, lho."
  },
  AvgDialog_18872_Content_1 = {
    Text = "Mimpi Buruk Berwarna"
  },
  AvgDialog_18872_Content_10 = {
    Text = "...Baiklah, jika {Male=tuan,Female=nona} Ash memerintahkan."
  },
  AvgDialog_18872_Content_11 = {
    Text = [[
09:23, Lily Taring 
 Ruang Bawah Tanah]]
  },
  AvgDialog_18872_Content_12 = {
    Text = "Ini adalah ruang eksperimen sekaligus ruang operasi. Di tengah ruangan terdapat meja operasi yang tampaknya telah dimodifikasi, dengan beberapa noda kotor yang mencurigakan."
  },
  AvgDialog_18872_Content_13 = {
    Text = "Di sudut terdalam ruang bawah tanah, terdapat tumpukan pakaian kotor yang sudah tak terlihat bentuk aslinya, setinggi separuh tubuh manusia, dan terus-menerus mengeluarkan bau busuk."
  },
  AvgDialog_18872_Content_14 = {
    Text = "Ini... ini... ini tempat apa?!"
  },
  AvgDialog_18872_Content_15 = {
    Text = "Jangan berpura-pura bodoh, kami sudah mengetahui semua tentang rencana jahatmu dengan Dokter Kotoran itu."
  },
  AvgDialog_18872_Content_16 = {
    Text = "Apa kejahatan yang kau lakukan, anak ini? Sejak kedatanganmu di sini, kau sudah begitu berisik. Aku harus mendidikmu."
  },
  AvgDialog_18872_Content_17 = {
    Text = "Kami melihat buku besarmu!"
  },
  AvgDialog_18872_Content_18 = {Text = "...?"},
  AvgDialog_18872_Content_19 = {
    Text = "Kamu mengambil buku catatan yang tergeletak di samping, membukanya, lalu memberi isyarat kepada Sarah."
  },
  AvgDialog_18872_Content_2 = {
    Text = [[
09:15, Lily's Taring 
 Ruang Kepala Sekolah]]
  },
  AvgDialog_18872_Content_20 = {
    Text = "Mick, laki-laki, 5 tahun, 10 Taring; Diana, perempuan, 23 tahun, 5 Taring…\nAigis, perempuan, 8 tahun, 40 Taring."
  },
  AvgDialog_18872_Content_21 = {
    Text = "Setelah kamu selesai berbicara, kamu mengambil lagi daftar kunjungan yang baru saja kalian temukan."
  },
  AvgDialog_18872_Content_22 = {
    Text = "Mick, laki-laki, 5 tahun, 5 Taring; Diana, perempuan, 23 tahun, 5 Taring; Aigis, perempuan, 8 tahun, 5 Taring."
  },
  AvgDialog_18872_Content_23 = {
    Text = "…Haruskah aku melanjutkan?"
  },
  AvgDialog_18872_Content_24 = {
    Text = "Bukan, bukan seperti yang kamu pikirkan, aku—"
  },
  AvgDialog_18872_Content_25 = {
    Text = "Jangan berkilah! Kau menyuruh orang-orang di Taring menjadi kelinci percobaan untuk eksperimen Dokter Gila itu, lalu menukar hasilnya dengan uang untuk membeli permata dan perhiasanmu!"
  },
  AvgDialog_18872_Content_26 = {
    Text = "Tidak, bukan itu! Nona Sarah berkata, itu adalah tunjangan nutrisi untuk orang yang menerima perawatan dari laboratorium, 5 Leiou per orang per kali, itu sudah disepakati."
  },
  AvgDialog_18872_Content_27 = {Text = "Aigis!"},
  AvgDialog_18872_Content_28 = {
    Text = "Benar. Mengenai apa yang dikatakan anak itu tentang perhiasan, itu sama sekali tidak masuk akal. Tolong percayalah padaku, Ash {Male=tuan,Female=nona}!"
  },
  AvgDialog_18872_Content_29 = {
    Text = "Jenkin mengeluarkan dua cincin perak dari dalam tas selempangnya."
  },
  AvgDialog_18872_Content_3 = {
    Text = "Kalung zamrud, cincin… aneh, di mana buku catatan saya?"
  },
  AvgDialog_18872_Content_30 = {
    Text = "Maksudmu, dua benda kecil di laci kanan meja ini aku ciptakan begitu saja dari ketiadaan?"
  },
  AvgDialog_18872_Content_31 = {
    Text = "Lalu bagaimana bisa ada di tempatmu? Kembalikan, itu Hadiah dari penyandang dana lain!"
  },
  AvgDialog_18872_Content_32 = {
    Text = "Ash{Male=tuan,Female=nona}, kamu percaya padaku. Aku menganggapnya sebagai barang darurat untuk menutupi kekurangan di Taring. Bagaimana mungkin, bagaimana mungkin aku akan memberikan Kerusakan pada anak-anak di Taring karena hal-hal ini?"
  },
  AvgDialog_18872_Content_33 = {
    Text = "Lalu, bagaimana dengan ini?"
  },
  AvgDialog_18872_Content_34 = {Text = "……!!"},
  AvgDialog_18872_Content_35 = {
    Text = "Kancing manset?"
  },
  AvgDialog_18872_Content_36 = {
    Text = "Kemarin, kami sudah masuk ke dalam ruangan itu."
  },
  AvgDialog_18872_Content_37 = {
    Text = [[
Di sana baru saja dibersihkan, tanahnya masih belum kering, dan ada bekas darah yang tersisa di antara celah-celah bata. 
 Ini sepertinya terlewatkan secara tidak sengaja, tepat di sudut sana.]]
  },
  AvgDialog_18872_Content_38 = {
    Text = [[
Bahan-bahannya dipilih dengan cermat, dan pengerjaannya juga terbilang halus. 
Selain kamu sebagai pemimpin Taring ini, siapa lagi yang akan memiliki dekorasi seperti ini?]]
  },
  AvgDialog_18872_Content_39 = {
    Text = "Bukan, itu bukan miliknya! Bukan milik Miss Sarah, itu milikku! Aku yang meninggalkannya di sana!"
  },
  AvgDialog_18872_Content_4 = {
    Text = [[
? Siapa itu. 
 Silakan masuk.]]
  },
  AvgDialog_18872_Content_40 = {
    Text = "Itu miliknya, itu miliknya! Pembunuh, penculik!"
  },
  AvgDialog_18872_Content_41 = {
    Text = "Meskipun dicegah oleh Aigis, Jenkin tetap menerjang dan langsung meraih rok Sarah."
  },
  AvgDialog_18872_Content_42 = {
    Text = "Sialan, beritahu aku, di mana kakakku berada! <Big:Kalian membawa kakakku ke mana!>"
  },
  AvgDialog_18872_Content_43 = {
    Text = [[
Kamu hendak maju untuk mencegahnya, tiba-tiba merasakan kulit kepala kesemutan. 
 Ada sesuatu di belakangmu, di belakang kalian semua, memandang kalian dengan tatapan penuh niat jahat.]]
  },
  AvgDialog_18872_Content_44 = {
    Text = "Kamu menoleh dan melihat tumpukan pakaian kotor di sudut yang entah sejak kapan mulai bergerak."
  },
  AvgDialog_18872_Content_45 = {
    Text = "Cairan hitam merembes keluar dari celah-celah kain, membasahi seluruh pakaian yang awalnya kering, lalu berkumpul di tanah membentuk berbagai entitas mutan yang meneteskan cairan lengket."
  },
  AvgDialog_18872_Content_46 = {Text = "Ramona!"},
  AvgDialog_18872_Content_5 = {
    Text = "Nyonya Sarah."
  },
  AvgDialog_18872_Content_6 = {
    Text = [[
Nona Mary! 
 Ada yang bisa saya bantu?]]
  },
  AvgDialog_18872_Content_7 = {
    Text = [[
Mau merepotkanmu untuk datang bersamaku. 
Ash {Male=tuan,Female=nona} menghadapi beberapa masalah dan berharap kamu bisa menjawabnya.]]
  },
  AvgDialog_18872_Content_8 = {
    Text = "Ash{Male=tuan,Female=nona}? Ini... apakah tidak bisa sedikit lebih lambat? Saya sedang ada sedikit urusan."
  },
  AvgDialog_18872_Content_9 = {
    Text = "Saya khawatir saya harus tetap pada pendirian saya."
  },
  AvgDialog_18873_Content_1 = {
    Text = "Nona kecil, kami juga melakukan ini demi kebaikan Aigis. Kondisinya cukup istimewa. Jika tidak dikontrol dengan baik, akan sangat merepotkan."
  },
  AvgDialog_18873_Content_10 = {
    Text = [[
Jenkin, hentikan pemukulan! 
 ...Aku pergi.]]
  },
  AvgDialog_18873_Content_11 = {Text = "...Ah?!"},
  AvgDialog_18873_Content_12 = {
    Text = "Ini semua sudah menjadi tugasku. Setelah memulai, setelah ada… di tubuhku, tidak akan…"
  },
  AvgDialog_18873_Content_13 = {
    Text = "Apa yang kamu maksud dengan \"seharusnya\"? Kenapa begitu!"
  },
  AvgDialog_18873_Content_14 = {
    Text = [[
Dr. Miller benar, jika saya kambuh, itu akan merepotkan semua orang.
Saya tidak ingin menyakiti kamu, saya... izinkan saya pergi.]]
  },
  AvgDialog_18873_Content_15 = {
    Text = "Kamu, apa kamu sakit?! Apa yang kamu lakukan, bicara sendiri saja. Aku sudah bilang tidak boleh pergi!"
  },
  AvgDialog_18873_Content_16 = {
    Text = "Jenkin——"
  },
  AvgDialog_18873_Content_17 = {
    Text = "Dr. Miller."
  },
  AvgDialog_18873_Content_18 = {
    Text = "Hari ini sampai di sini saja, lain kali... membicarakannya lagi juga tidak terlambat."
  },
  AvgDialog_18873_Content_19 = {
    Text = "...Apakah Anda yakin, Tuan Rogers."
  },
  AvgDialog_18873_Content_2 = {
    Text = "Bahkan mungkin akan memberikan kerusakan kepada orang-orang di sekitarnya."
  },
  AvgDialog_18873_Content_20 = {
    Text = "Saya berpikir demikian."
  },
  AvgDialog_18873_Content_21 = {
    Text = [[
Baiklah, saya pikir, seminggu tanpa pemeriksaan tidak akan berdampak apa-apa. 
Kalau begitu, saya pamit dulu. Sampai jumpa, Nona Sarah, Tuan Rogers, dan Lord atau Lady Ash{Male=tuan,Female=nona}.]]
  },
  AvgDialog_18873_Content_22 = {
    Text = "Dr. Miller membungkuk ke arah kalian, lalu pergi bersama beberapa peneliti."
  },
  AvgDialog_18873_Content_23 = {
    Text = "Kamu merasa tidak seharusnya melepaskan mereka, tapi — semuanya saat ini hanyalah spekulasi. Kamu tidak tahu apakah mereka benar-benar berasal dari Para Pematung, juga tidak tahu berapa banyak orang lagi yang ada di antara mereka dan di mana markas mereka."
  },
  AvgDialog_18873_Content_24 = {
    Text = [[
Kamu menatap Ramona, ekspresi wajahnya muram, jelas memiliki kekhawatiran yang sama denganmu: 
Jika kita menahan mereka sekarang, apakah ini hanya akan membuat musuh waspada?]]
  },
  AvgDialog_18873_Content_25 = {
    Text = "Saya, saya juga akan pergi, Nona Sarah. S. Sampai jumpa lagi bulan depan."
  },
  AvgDialog_18873_Content_26 = {
    Text = [[
Kalau begitu, aku akan membawa Aigis dan Jenkin untuk beristirahat dulu. 
 Nona Sarah, kita bertemu di kantor kamu nanti, bagaimana?]]
  },
  AvgDialog_18873_Content_27 = {
    Text = "Eh? Kamu, Aigis dia——"
  },
  AvgDialog_18873_Content_28 = {
    Text = "Dia tampaknya mengalami ketakutan yang cukup besar. Aku berharap bisa menemaninya sejenak, agar dia bisa tenang."
  },
  AvgDialog_18873_Content_29 = {
    Text = "Baiklah… Baiklah. Terima kasih atas bantuan kalian, Ash {Male=tuan,Female=nona}."
  },
  AvgDialog_18873_Content_3 = {
    Text = "Lihat, Aigis, inilah akibatnya jika kamu tidak mendengarkan dan bekerja sama dengan baik."
  },
  AvgDialog_18873_Content_4 = {
    Text = "Teman-teman yang kau hiraukan, orang-orang di sekitarmu... semuanya akan membayar harga untuk ini."
  },
  AvgDialog_18873_Content_5 = {
    Text = "Patuh, taat, dan jangan melawan. Ingatlah, sebenarnya kamu tidak memiliki tempat untuk melarikan diri."
  },
  AvgDialog_18873_Content_6 = {
    Text = "Apa maksudnya dengan \"di sekitar\"? Aku sudah lama bersamanya, kenapa tidak ada masalah?"
  },
  AvgDialog_18873_Content_7 = {
    Text = "…Jenkin…"
  },
  AvgDialog_18873_Content_8 = {
    Text = "Aigis, jangan takut. Lihat saja bagaimana aku menghajarnya. Cokelat, gigit dia!"
  },
  AvgDialog_18873_Content_9 = {Text = "Cit!"},
  AvgDialog_18874_Content_1 = {
    Text = "Pengumuman Pencarian Orang"
  },
  AvgDialog_18874_Content_10 = {
    Text = "Kalian berdua jangan begitu pesimis, kami juga berharap Taring bisa semakin baik——"
  },
  AvgDialog_18874_Content_11 = {Text = "Ugh!"},
  AvgDialog_18874_Content_12 = {
    Text = "Di sisi tubuhmu tiba-tiba terbentur, kau menunduk dan melihat: seorang anak kecil yang kurus jatuh terduduk di tanah, seluruh tubuhnya gemetar tak terkendali."
  },
  AvgDialog_18874_Content_13 = {
    Text = "Ada, ada, ada monster!"
  },
  AvgDialog_18874_Content_14 = {
    Text = "Beberapa menit yang lalu, Lily Taring"
  },
  AvgDialog_18874_Content_15 = {
    Text = [[
Di koridor yang sunyi, pintu dengan pelat logam perlahan terbuka. 
 Seekor tikus meluncur keluar dari celah pintu, memandang ke kiri dan kanan, lalu mengecik dua kali ke arah belakangnya.]]
  },
  AvgDialog_18874_Content_16 = {
    Text = "Terakhir kamu juga bilang tidak ada orang! Kalau bukan karena bertemu dengan Aigis, aku pasti sudah celaka besar."
  },
  AvgDialog_18874_Content_17 = {
    Text = "Cicit, cicit cicit cicit!"
  },
  AvgDialog_18874_Content_18 = {
    Text = "Betul betul, kamu benar sekali. Cokelat kita yang paling hebat!"
  },
  AvgDialog_18874_Content_19 = {
    Text = "Cicit cicit, cicit."
  },
  AvgDialog_18874_Content_2 = {
    Text = "14:01, Lily Taring"
  },
  AvgDialog_18874_Content_20 = {
    Text = "Tenang saja, wanita itu punya banyak perhiasan emas dan perak. Aku hanya mengambil dua cincin, dia tidak akan menyadarinya!"
  },
  AvgDialog_18874_Content_21 = {
    Text = "Tapi... hehe, sekarang aku tahu di mana dia menyimpan semua barang bagusnya. Begitu aku menemukan kakakku, lihat saja, aku akan mencuri habis-habisan dari wanita sialan itu!"
  },
  AvgDialog_18874_Content_22 = {Text = "Cit!"},
  AvgDialog_18874_Content_23 = {
    Text = "Baiklah, jangan katakan—eh? \nItu... suara apa?"
  },
  AvgDialog_18874_Content_24 = {
    Text = "Di ujung koridor, ada sesuatu yang bergerak cepat di tikungan."
  },
  AvgDialog_18874_Content_25 = {Text = "Cokelat."},
  AvgDialog_18874_Content_26 = {
    Text = "Tikus meloncat dari tas selempang, dengan kegesitan khas tikus, bergerak diam-diam melewati sudut sambil menempel pada dinding untuk memeriksa."
  },
  AvgDialog_18874_Content_27 = {Text = "Cit cit!"},
  AvgDialog_18874_Content_28 = {
    Text = [[
Mendengar temannya mengatakan bahwa situasi aman, gadis itu merunduk dan mengikuti dari belakang. 
 Dia memegang dinding sambil sedikit condong ke depan, lalu bernapas lega saat menyadari tidak ada seorang pun di hadapannya.]]
  },
  AvgDialog_18874_Content_29 = {
    Text = "Memutuskan untuk segera pergi, gadis itu menarik kembali kepalanya, namun dari sudut matanya ia masih menangkap sebuah bayangan pucat."
  },
  AvgDialog_18874_Content_3 = {
    Text = "Seperti yang kamu lihat, meskipun kami sudah berusaha menampung sebanyak mungkin, jumlah orang yang membutuhkan bantuan terlalu banyak. Jika begini terus, Taring ini juga tidak akan bertahan lama. Aku... ah!"
  },
  AvgDialog_18874_Content_30 = {Text = "?"},
  AvgDialog_18874_Content_31 = {
    Text = "Dia melangkah ke koridor dan menemukan sebuah benda putih dengan bentuk tidak beraturan tergeletak di lantai kayu yang tidak terlalu bersih, tampak seperti semacam batu."
  },
  AvgDialog_18874_Content_32 = {
    Text = "Sepertinya itu adalah bagian dari topeng batu, dibuat dengan sangat halus. Setiap helai alis dipahat dengan hati-hati, tampak begitu hidup."
  },
  AvgDialog_18874_Content_33 = {
    Text = "Apa ini? Di Taring tidak terlihat ada pengolahan topeng batu atau patung."
  },
  AvgDialog_18874_Content_34 = {
    Text = "Dia memiringkan kepalanya, melihat ke kiri dan kanan, lalu dengan rasa ingin tahu menyentuh menggunakan jari telunjuknya."
  },
  AvgDialog_18874_Content_35 = {
    Text = "Kenapa masih hangat..."
  },
  AvgDialog_18874_Content_36 = {
    Text = "Dia hendak mengambil topeng itu, ketika sepasang bibir yang seharusnya terbuat dari batu tiba-tiba terbuka, mengeluarkan erangan kesakitan yang seharusnya tidak ada."
  },
  AvgDialog_18874_Content_37 = {Text = "!!"},
  AvgDialog_18874_Content_38 = {
    Text = "Dia mundur dua langkah dengan ketakutan, di antara napas yang terengah-engah, dia bahkan mencium bau busuk Caro yang membusuk."
  },
  AvgDialog_18874_Content_39 = {
    Text = "Makhluk, monster... monster!"
  },
  AvgDialog_18874_Content_4 = {
    Text = "Shasha, Nyonya Sarah setiap hari bekerja keras, bahkan menjual barang-barang kesayangannya sendiri hanya untuk menutupi kebutuhan Taring. Tolong... tolong bantu kami..."
  },
  AvgDialog_18874_Content_40 = {
    Text = [[
14:37, Ruang Taring Lily
Kamar Aigis]]
  },
  AvgDialog_18874_Content_41 = {
    Text = "Lalu aku lari, lalu aku menabrakmu. Lalu kalian memaksa membawaku untuk \"beristirahat\", dan sekarang aku di sini."
  },
  AvgDialog_18874_Content_42 = {
    Text = "Kali ini sudah cukup rinci, bukan?"
  },
  AvgDialog_18874_Content_43 = {Text = "Hmm..."},
  AvgDialog_18874_Content_44 = {
    Text = "Dua anak duduk berdampingan di atas tempat tidur. Kamu memandang mereka, terutama Jenkin, dan akhirnya mengajukan pertanyaan itu."
  },
  AvgDialog_18874_Content_45 = {
    Text = "Kamu... sebenarnya laki-laki atau perempuan, ya?"
  },
  AvgDialog_18874_Content_46 = {
    Text = "Apa ada masalah dengan matamu!? Aku ini perempuan, PEREMPUAN!"
  },
  AvgDialog_18874_Content_47 = {
    Text = "Konfirmasi sekali, konfirmasi sekali."
  },
  AvgDialog_18874_Content_48 = {
    Text = [[
Dasar, orang seperti apa sih, apakah otaknya tidak bermasalah...
Apa kamu sudah selesai bertanya? Kalau sudah, giliranku.]]
  },
  AvgDialog_18874_Content_49 = {
    Text = [[
Tangan Jenkin bergerak cepat, entah dari mana ia mengeluarkan sebuah dompet. 
Bentuknya yang familiar, dengan logo Mythag tercetak di atasnya: tidak salah lagi, itu adalah dompetmu, hanya saja...]]
  },
  AvgDialog_18874_Content_5 = {
    Text = "Cukup, Aigis kecil yang malang dan menggemaskan. Jika Taring benar-benar tidak bisa bertahan, meskipun aku harus mati kelaparan, aku pasti tidak akan membiarkanmu kelaparan!"
  },
  AvgDialog_18874_Content_50 = {
    Text = "... Bagaimana bisa kosong di dalam, uangku mana!"
  },
  AvgDialog_18874_Content_51 = {
    Text = "Itu bukan poin utamanya!"
  },
  AvgDialog_18874_Content_52 = {
    Text = [[
Huh, intinya, jangan lihat aku seperti ini. Aku masih bisa membaca sedikit. 
Yang ada di sini bukan sertifikat {Male=tuan,Female=nona}, %player%.]]
  },
  AvgDialog_18874_Content_53 = {
    Text = "Jika aku memberitahu wanita menjengkelkan itu tentang identitas kalian berdua, apa menurutmu dia akan menyuruh orang di pintu untuk mengusir kalian?"
  },
  AvgDialog_18874_Content_54 = {
    Text = "Apakah ini anak dari Taring?"
  },
  AvgDialog_18874_Content_55 = {
    Text = "Tidak... kalau tidak, haha, di Taring kami, keamanannya sangat ketat. Kami tidak mengizinkan orang yang tidak dikenal masuk atau keluar."
  },
  AvgDialog_18874_Content_56 = {
    Text = "Dari reaksi Sarah, jelas bahwa dia tidak mengenal Jenkin. Lalu——"
  },
  AvgDialog_18874_Content_57 = {
    Text = "Jika ketahuan, bukankah yang akan bermasalah bukan hanya aku? Lagipula, kau juga bukan orang dari Taring."
  },
  AvgDialog_18874_Content_58 = {
    Text = "Aku punya banyak cara untuk masuk. Tapi kamu, setelah kehilangan identitas sebagai pemberi bantuan mandiri, akan sulit bagimu untuk masuk kembali."
  },
  AvgDialog_18874_Content_59 = {
    Text = "... adalah penyandang dana."
  },
  AvgDialog_18874_Content_6 = {
    Text = "Nyonya Sarah...! Aku, aku pasti akan patuh, pasti akan merawatmu dengan baik, membalas budi kebaikanmu, dan tidak akan menjadi beban untukmu."
  },
  AvgDialog_18874_Content_60 = {
    Text = "Terserah! Pokoknya, kalau tidak kamu bantu aku satu hal, kalau tidak, kita berdua akan celaka!"
  },
  AvgDialog_18874_Content_61 = {
    Text = "Pertama-tama, aku ingin mengatakan bahwa aku tidak mencuri."
  },
  AvgDialog_18874_Content_62 = {
    Text = "Mencuri barang, apakah kamu bisa membantu saya? Maksudku, aku ingin kamu membantu aku mencari seseorang!"
  },
  AvgDialog_18874_Content_63 = {
    Text = "Coba jelaskan dulu permintaanmu."
  },
  AvgDialog_18874_Content_64 = {
    Text = "Aku ingin kamu membantu aku mencari seseorang, seorang yang sangat penting."
  },
  AvgDialog_18874_Content_65 = {Text = "Siapa?"},
  AvgDialog_18874_Content_66 = {
    Text = "Kakakku, Mason."
  },
  AvgDialog_18874_Content_8 = {
    Text = "Yang tercinta, Aigis——"
  },
  AvgDialog_18874_Content_9 = {
    Text = "Melihat pertunjukan kedua orang itu — terutama Sarah — semakin berlebihan, kamu merasa cukup putus asa.\nMeskipun memahami mereka, bantuan yang bisa kamu berikan bukanlah dalam bentuk uang."
  },
  AvgDialog_18875_Content_1 = {
    Text = "Detektif Kecil"
  },
  AvgDialog_18875_Content_10 = {
    Text = "Hei, sudahlah, kamu hampir membuatku ketahuan. Kamu harus bertanggung jawab atas ini."
  },
  AvgDialog_18875_Content_11 = {
    Text = [[
Aku akan jujur padamu, aku memang bukan orang dari Taring ini.
Namaku Jenkin, dan ini Brown.]]
  },
  AvgDialog_18875_Content_12 = {Text = "Cit!"},
  AvgDialog_18875_Content_13 = {
    Text = [[
Saya masuk untuk mencari kakak perempuan saya. Namanya Mason, dia menghilang di sekitar sini dua minggu yang lalu. 
Apakah ada orang bernama Mason yang baru muncul di sini akhir-akhir ini?]]
  },
  AvgDialog_18875_Content_14 = {
    Text = "Maaf, aku... aku tidak tahu... maaf..."
  },
  AvgDialog_18875_Content_15 = {
    Text = "Coba pikirkan dengan baik, dia setinggi ini, rambutnya panjang, diikat dengan pita satin merah yang cantik."
  },
  AvgDialog_18875_Content_17 = {
    Text = "Pernah lihat atau tidak, katakanlah. Apakah dia ditangkap oleh orang-orang jahat dari Taring kalian? Apakah dia dipaksa tinggal untuk kerja paksa?"
  },
  AvgDialog_18875_Content_18 = {
    Text = "Ck, tidak bisa. Melihatmu seperti ini, sepertinya kau tidak tahu apa-apa. Aku harus tetap tinggal, bahkan jika harus menyamar dan bergabung dengan Taring——"
  },
  AvgDialog_18875_Content_19 = {
    Text = "Tidak bisa! Kalau bergabung, aku harus sembuh, tidak bisa!"
  },
  AvgDialog_18875_Content_2 = {
    Text = [[
3 hari yang lalu, Londinium Timur
Lily Taring]]
  },
  AvgDialog_18875_Content_20 = {
    Text = "Diamlah! Kamu tidak takut ketahuan, aku masih takut!"
  },
  AvgDialog_18875_Content_21 = {
    Text = "Aku akan membantu mencari kakakmu. Aku bisa membantu kamu bersembunyi, dan membawakan makanan untukmu. Jangan bergabung dengan Taring, oke?"
  },
  AvgDialog_18875_Content_22 = {
    Text = "Benar? Tentu saja bagus! Aku bersumpah akan membalas budi padamu!"
  },
  AvgDialog_18875_Content_23 = {
    Text = "Ngomong-ngomong, siapa nama kamu?"
  },
  AvgDialog_18875_Content_24 = {
    Text = "Saya... saya Aigis."
  },
  AvgDialog_18875_Content_25 = {
    Text = "Senang berkenalan denganmu, Aigis. Mulai hari ini, kita adalah teman!"
  },
  AvgDialog_18875_Content_26 = {
    Text = [[
15:00, Londinium Timur
Lily Taring]]
  },
  AvgDialog_18875_Content_27 = {
    Text = "Kemudian Aigis membantu saya bersembunyi di ruang penyimpanan, dan saya mencari kakak saya di Taring saat orang dewasa tidak memperhatikan."
  },
  AvgDialog_18875_Content_28 = {
    Text = [[
Awalnya, aku berpikir bahwa saat istirahat dan semua orang berkumpul, aku pasti bisa menemukannya.
Namun, kemarin dan kemarin lusa aku tidak melihat siapa pun, jadi aku hanya bisa mencari saat bekerja di siang hari.]]
  },
  AvgDialog_18875_Content_29 = {
    Text = [[
Meskipun aku tidak takut diusir, aku juga tidak ingin mendapat masalah. Tapi kamu berbeda.
Dengan identitasmu, berkeliling di Taring sembarangan tidak akan menimbulkan masalah.]]
  },
  AvgDialog_18875_Content_3 = {
    Text = "Tengah malam, wilayah timur tampak suram. Baik cahaya lampu jalan maupun sinar bulan, semuanya telah ditelan oleh kabut tebal yang menyelimuti, hanya menyisakan beberapa bayangan kabur yang bergoyang di udara."
  },
  AvgDialog_18875_Content_30 = {
    Text = "Aku tidak meminta banyak, hanya ingin kau melihat sejenak apakah kakakku ada di antara orang-orang yang bekerja."
  },
  AvgDialog_18875_Content_31 = {
    Text = [[
Jika kamu membantu aku, aku akan mengembalikan dompetmu dan kartu identitasmu, serta merahasiakan semuanya untukmu. 
Namun, jika kamu tidak mau membantu... hum!]]
  },
  AvgDialog_18875_Content_32 = {
    Text = "Terserah kamu!"
  },
  AvgDialog_18875_Content_33 = {
    Text = "Mengapa kamu begitu yakin bahwa kakakmu ada di sini?"
  },
  AvgDialog_18875_Content_34 = {
    Text = "Kamu mungkin tidak tahu, di sini terkenal sebagai \"Taring Pemakan Manusia\". Banyak orang yang hilang di sekitar sini, kakakku juga menghilang di daerah ini."
  },
  AvgDialog_18875_Content_35 = {
    Text = "Beberapa hari yang lalu, saya masih melihat <Red:bayangan hitam gelap> bergerak liar di halaman pada malam hari. Pasti ada sesuatu yang aneh sedang terjadi."
  },
  AvgDialog_18875_Content_36 = {
    Text = "...Baiklah, aku berjanji akan membantu mencari kakakmu. Sebagai pertukaran, kamu juga harus membantu menyelidiki Taring, oke?"
  },
  AvgDialog_18875_Content_37 = {
    Text = "Seperti itulah keputusannya!"
  },
  AvgDialog_18875_Content_38 = {
    Text = "Dia meludahi telapak tangannya dan menatapmu dengan penuh harapan."
  },
  AvgDialog_18875_Content_4 = {
    Text = "Di halaman depan Taring, dua sosok kecil berdiri di sudut."
  },
  AvgDialog_18875_Content_40 = {
    Text = "Apa yang kalian tunggu? Jabat tanganlah. Apakah kalian meremehkan aturan jalanan?"
  },
  AvgDialog_18875_Content_41 = {
    Text = "Bersalaman dengannya"
  },
  AvgDialog_18875_Content_42 = {
    Text = "Kamu meniru gayanya, meludah ke telapak tanganmu, lalu berjabat tangan erat dengannya."
  },
  AvgDialog_18875_Content_43 = {
    Text = "Tahu aturannya juga, orang dari Zona Barat. Aku yang meremehkanmu."
  },
  AvgDialog_18875_Content_44 = {
    Text = "Kamu meniru gayanya, meludah ke telapak tanganmu, lalu berjabat tangan erat dengannya."
  },
  AvgDialog_18875_Content_45 = {
    Text = "Kerja sama yang baik!"
  },
  AvgDialog_18875_Content_46 = {
    Text = [[
14:50, Londinium Timur
Lily Taring Pekerjaan]]
  },
  AvgDialog_18875_Content_47 = {
    Text = "Nona Mary, tolong, pasti, harus sampaikan permintaan maaf saya yang tulus kepada Ash {Male=tuan,Female=nona}."
  },
  AvgDialog_18875_Content_48 = {
    Text = "Orang-orang di Taring semuanya adalah orang miskin yang berbudi luhur, anak itu bukan... eh, maksud saya, aku pasti akan mendidiknya dengan baik!"
  },
  AvgDialog_18875_Content_49 = {
    Text = "Ramona hendak menjawab, namun tiba-tiba melihat sosok aneh berkelebat di ujung koridor."
  },
  AvgDialog_18875_Content_5 = {
    Text = "Kamu, kamu bukan Xiao Mai, juga bukan Lucy! Siapa sebenarnya kamu…!"
  },
  AvgDialog_18875_Content_50 = {Text = "Nona Mary?"},
  AvgDialog_18875_Content_51 = {
    Text = "Itu adalah...?"
  },
  AvgDialog_18875_Content_6 = {
    Text = "Aku juga mau tanya, siapa kamu! Berkeliling di luar malam-malam tanpa tidur, orang yang tidak tahu mungkin mengira kamu itu si pembunuh yang sedang heboh diperbincangkan."
  },
  AvgDialog_18875_Content_7 = {
    Text = "Bukan aku! Bukan aku!"
  },
  AvgDialog_18875_Content_8 = {
    Text = "Ssst! Apakah kamu tidak punya telinga? Bukankah sudah kubilang untuk berbicara lebih pelan!"
  },
  AvgDialog_18875_Content_9 = {
    Text = "Saya, saya... maaf, saya hanya... saya bukan... saya..."
  },
  AvgDialog_18876_Content_1 = {
    Text = "Jangan berbicara yang tidak sopan"
  },
  AvgDialog_18876_Content_10 = {
    Text = "Dia memang hebat, bahkan berhasil menyembuhkan mata Aigis, sehingga dia tidak lagi melihat Fatamorgana."
  },
  AvgDialog_18876_Content_100 = {
    Text = "Cicit cicit, cicit."
  },
  AvgDialog_18876_Content_101 = {
    Text = [[
Meskipun dia mungkin tahu di mana kakak berada, aku... tidak, aku merasa dia bukan orang jahat. 
 Mari kita pergi dulu, nanti aku akan mencari waktu ketika tidak ada orang untuk bertanya dengan lebih jelas.]]
  },
  AvgDialog_18876_Content_11 = {
    Text = "Benar, Aigis?"
  },
  AvgDialog_18876_Content_12 = {
    Text = "...Ya, Dr. Miller... sangat hebat..."
  },
  AvgDialog_18876_Content_13 = {
    Text = "Tidak bisa! Kalau bergabung, aku harus sembuh, tidak bisa!"
  },
  AvgDialog_18876_Content_14 = {
    Text = "Aku akan membantu mencari kakakmu, aku janji. Aku bisa membantu kamu bersembunyi, tapi jangan bergabung dengan Taring, oke?"
  },
  AvgDialog_18876_Content_15 = {
    Text = "Dari deskripsi Jenkin dan reaksinya saat ini, tampaknya anak ini sangat takut terhadap Dr. Miller dan \"Sembuh\"."
  },
  AvgDialog_18876_Content_16 = {
    Text = "Jika peneliti itu adalah orang dari Dr. Miller, maka \"terapi eksperimental\" yang disebut ini kemungkinan besar bukan sesuatu yang biasa, melainkan berkaitan dengan Pelarutan dan D-marka."
  },
  AvgDialog_18876_Content_17 = {
    Text = "Pada saat itu, beberapa orang yang berpakaian seperti juru masak mendorong gerobak, membawa aroma bubur oatmeal, dan masuk melalui pintu."
  },
  AvgDialog_18876_Content_18 = {
    Text = "Lihat aku, sampai lupa waktu. {Male=tuan,Female=nona} Ashe pasti sudah sangat lapar."
  },
  AvgDialog_18876_Content_19 = {
    Text = [[
Aigis, anak baik, pergi cari Diana dan suruh dia mengeluarkan makanan untuk para tamu. 
Lalu kamu bisa pergi mengantarkan makanan kepada para pasien, oke?]]
  },
  AvgDialog_18876_Content_2 = {
    Text = [[
15:11, Londinium Timur
Lily Taring]]
  },
  AvgDialog_18876_Content_20 = {
    Text = "Baik, Nona Sarah, saya akan pergi sekarang."
  },
  AvgDialog_18876_Content_21 = {
    Text = "Gadis itu membawa nampan, berjalan perlahan melewati satu per satu tempat tidur pasien, serta menyapa setiap pasien, baik yang sadar maupun yang gila."
  },
  AvgDialog_18876_Content_22 = {
    Text = "Selamat siang, Nenek Thompson; selamat siang, Paman Kelvin…"
  },
  AvgDialog_18876_Content_23 = {
    Text = [[
Dia berhenti di samping tempat tidur dekat jendela. 
Di atas tempat tidur, seorang pria tua terikat dengan kain di keempat anggota tubuhnya, terus-menerus mengeluarkan erangan kesakitan dari tenggorokannya.]]
  },
  AvgDialog_18876_Content_24 = {
    Text = "Kakek Robert, aku sudah meletakkan makananmu di samping, jangan lupa untuk memakannya ya."
  },
  AvgDialog_18876_Content_25 = {
    Text = "Gadis itu menundukkan kepala untuk merapikan selimut orang tua, sehingga sama sekali tidak memperhatikan bahwa sebuah segitiga hitam sedang diam-diam melahap wajah orang tua itu. Bahkan fitur wajahnya pun meleleh dalam cairan hitam yang kental."
  },
  AvgDialog_18876_Content_26 = {
    Text = [[
Setelah makan kenyang, kamu akan cepat sembuh. 
 Setelah sembuh, kita bisa pergi ke Taman Delair bersama dan memberi makan merpati.]]
  },
  AvgDialog_18876_Content_27 = {
    Text = "Lengan kurus pria tua itu menarik dan memutuskan kain yang mengikatnya, lalu dengan cepat mengangkatnya ——"
  },
  AvgDialog_18876_Content_28 = {
    Text = "Jika kita memiliki lebih banyak dana, mungkin kita bisa meminta bantuan dari orang yang lebih profesional, dan pasien juga bisa dirawat di tempat yang lebih baik——"
  },
  AvgDialog_18876_Content_29 = {Text = "!"},
  AvgDialog_18876_Content_3 = {
    Text = [[
Kalian mengikuti Sarah ke sebuah ruangan yang dipenuhi dengan tempat tidur sederhana. 
 Tampaknya ruangan ini dulunya adalah kantin, dan masih ada meja panjang di tengah untuk makan.]]
  },
  AvgDialog_18876_Content_30 = {
    Text = "Kamu segera melihat ke arah sumber suara dan melihat seekor monster dengan wajah yang sepenuhnya digantikan oleh lubang-lubang hitam menangkap Aigis."
  },
  AvgDialog_18876_Content_31 = {Text = "Aigis!"},
  AvgDialog_18876_Content_32 = {
    Text = "Ramona segera bereaksi. Dia melintasi kerumunan yang bergejolak dan membanting sarung pedangnya ke bahu monster."
  },
  AvgDialog_18876_Content_33 = {
    Text = "Monster melepaskan tangannya, sementara perawat di sampingnya segera berkerumun dan mengikat benda yang masih menjerit itu kembali ke tempat tidur."
  },
  AvgDialog_18876_Content_34 = {
    Text = "Kakek Robert, Kakek Robert——"
  },
  AvgDialog_18876_Content_35 = {
    Text = [[
Di tengah teriakan sedih gadis itu, kamu melihat "manusia" yang berjuang di atas tempat tidur, merasakan kesedihan yang mendalam. 
<Yellow: Tahap Akhir Pelarutan>, orang tua ini hanya memiliki beberapa hari lagi untuk mempertahankan bentuk manusianya.]]
  },
  AvgDialog_18876_Content_36 = {
    Text = "Perban, aku menemukan perban! Aigis, cepat, biarkan aku melihat lukamu!"
  },
  AvgDialog_18876_Content_37 = {
    Text = "Kakek Robert, cepat bantu Kakek Robert."
  },
  AvgDialog_18876_Content_38 = {
    Text = "Saat seperti ini, kenapa kamu masih memikirkan orang lain? Jika luka tidak segera ditangani, akan sangat merepotkan!"
  },
  AvgDialog_18876_Content_39 = {
    Text = "Jenkin menahan lengan Aigis tanpa banyak bicara, lalu menarik lengan bajunya ke atas, memperlihatkan luka yang mengeluarkan darah di bawahnya."
  },
  AvgDialog_18876_Content_4 = {
    Text = "Untuk merawat mereka, kami harus membagi sebagian tenaga kami. Efisiensi kerja dan pendapatan Taring juga terpengaruh karena hal ini, ditambah lagi dengan penyakit aneh itu…"
  },
  AvgDialog_18876_Content_40 = {
    Text = "Gila sialan ini, garuknya terlalu keras!"
  },
  AvgDialog_18876_Content_41 = {
    Text = "Goresan tipis di lengan gadis itu sedikit mengeluarkan darah, tetapi dibandingkan dengan luka hitam yang melintang dan terpilin di pergelangan tangannya, goresan tersebut tampak tidak berarti."
  },
  AvgDialog_18876_Content_42 = {
    Text = "Jahitan yang bersilangan menarik kulit di kedua sisi ke arah tengah, mencoba menutupi lubang hitam itu dengan cara \"menutup\"nya, tetapi justru membuatnya tampak lebih seperti mulut yang rakus menggigit."
  },
  AvgDialog_18876_Content_43 = {
    Text = "Ini adalah <Yellow:D-marka>, sama seperti pasien lainnya, D-marka yang terdistorsi."
  },
  AvgDialog_18876_Content_44 = {
    Text = "… Jenkin, tolong ambilkan air."
  },
  AvgDialog_18876_Content_45 = {
    Text = "Jenkin mengangguk dengan semangat dan segera berlari menjauh."
  },
  AvgDialog_18876_Content_46 = {
    Text = [[
Ramona mengeluarkan saputangan dan dengan lembut membersihkan darah dari tangan Aigis, menghindari pergelangan tangannya. 
 Aigis melihat Ramona, lalu melihatmu, tampak sedikit ragu-ragu.]]
  },
  AvgDialog_18876_Content_47 = {
    Text = "Aigis, apakah kamu ingin mengatakan sesuatu?"
  },
  AvgDialog_18876_Content_48 = {Text = "!"},
  AvgDialog_18876_Content_49 = {
    Text = "Tidak... tidak... aku tidak..."
  },
  AvgDialog_18876_Content_5 = {
    Text = "Saya tidak mau mengambil risiko kepercayaan para donatur, jadi saya berusaha semaksimal mungkin untuk menyembunyikan semua ini. Hanya donatur utama <Blue:Rogers> yang mengetahuinya."
  },
  AvgDialog_18876_Content_50 = {
    Text = "Jangan takut, Aigis. Apapun itu, kami pasti akan membantu kamu."
  },
  AvgDialog_18876_Content_51 = {
    Text = "Jangan takut, Aigis, Dr. Miller datang untuk membantu kamu."
  },
  AvgDialog_18876_Content_52 = {
    Text = "Jangan takut, Aigis. Hanya disuntik saja, tidak akan sakit."
  },
  AvgDialog_18876_Content_53 = {
    Text = "Jangan takut, Aigis, ini akan segera berlalu."
  },
  AvgDialog_18876_Content_54 = {
    Text = "Jangan takut, Aigis…"
  },
  AvgDialog_18876_Content_55 = {
    Text = "Jangan takut..."
  },
  AvgDialog_18876_Content_56 = {Text = "Aigis?"},
  AvgDialog_18876_Content_57 = {
    Text = [[
Gadis itu menggelengkan kepalanya dengan kuat. 
Pada saat itu, Sarah yang baru saja menenangkan para pekerja lain bergegas mendekati kalian.]]
  },
  AvgDialog_18876_Content_58 = {
    Text = "Aigis, kamu—astaga, kamu berdarah! Di mana perban? Cepat bawa perban kemari!"
  },
  AvgDialog_18876_Content_59 = {
    Text = [[
Aku baik-baik saja, Nona Sarah. 
 Maafkan aku, ini semua karena aku terlalu ceroboh, membuatmu khawatir.]]
  },
  AvgDialog_18876_Content_6 = {
    Text = "Kamu melihat sekeliling, para pasien mengalami tingkat pelarutan yang berbeda-beda. Masing-masing memiliki bentuk yang terdistorsi, sama seperti yang terlihat pada pria tadi."
  },
  AvgDialog_18876_Content_60 = {
    Text = "Kamu... ah. Sudah berapa kali aku bilang, orang-orang gila ini sangat berbahaya, tapi kamu tetap tidak mau mendengarkanku dan bersikeras mengambil tugas mengantarkan makanan ini. Mengapa kamu begitu keras kepala?"
  },
  AvgDialog_18876_Content_61 = {
    Text = "Maaf... Aku tidak bermaksud seperti ini..."
  },
  AvgDialog_18876_Content_62 = {
    Text = "Aku tahu, kamu ingin berbagi beban dengan semua orang, tapi kamu juga harus melihat kemampuanmu sendiri. Apakah dengan bertindak seperti ini kamu tidak menambah masalah bagi semua orang?"
  },
  AvgDialog_18876_Content_63 = {
    Text = "Benar-benar tidak bisa membuat orang tenang. Jika kamu terus bersikap sesuka hati, kapan kamu akan dewasa —"
  },
  AvgDialog_18876_Content_64 = {
    Text = "Cukup bicara!"
  },
  AvgDialog_18876_Content_65 = {
    Text = "Jenkin entah kapan kembali berlari. Dia melemparkan ember ke tanah dan berdiri menghalangi Aigis."
  },
  AvgDialog_18876_Content_66 = {
    Text = [[
Aigis bekerja begitu keras setiap hari, membantu melakukan banyak hal untukmu. Apa lagi yang membuatmu tidak puas?
Jangan bicara soal dewasa. Jika dewasa berarti harus melakukan apa pun yang kamu katakan, menurutku lebih baik tidak pernah dewasa seumur hidup!]]
  },
  AvgDialog_18876_Content_67 = {
    Text = "Apa, apa yang terjadi?"
  },
  AvgDialog_18876_Content_68 = {
    Text = [[
Kamu mengikuti suara dan menoleh ke belakang, hanya untuk menemukan dua orang berdiri di sana. 
 Salah satunya kamu kenal: dia pernah memberikanmu sebuah kuesioner psikologi di jalan.]]
  },
  AvgDialog_18876_Content_69 = {
    Text = [[
Tuan Rogers, Dokter Fairfax! 
Bukankah Anda biasanya datang pada sore hari? Jika Anda memberi tahu saya lebih awal, saya bisa menjemput Anda di pintu.]]
  },
  AvgDialog_18876_Content_7 = {
    Text = "Anehnya, orang yang tadi disebut \"<Blue:Peneliti>\" oleh Sarah saat menjelaskan, tidak berada di sini sekarang."
  },
  AvgDialog_18876_Content_70 = {
    Text = [[
Saya sudah sangat familiar dengan tempat ini, Nona Sarah, tidak perlu repot-repot. 
Dibandingkan dengan itu, kenapa Xiao Ai, Aigis menangis begitu sedih? Apakah ada yang mem-bully dia?]]
  },
  AvgDialog_18876_Content_71 = {
    Text = "Masih saja Sarah yang menyebalkan ini! Dia benar-benar…"
  },
  AvgDialog_18876_Content_72 = {
    Text = "Di tengah teriakan Jenkin, Clementine membungkuk dan dengan mahir menggenggam tangan Aigis."
  },
  AvgDialog_18876_Content_73 = {
    Text = "Apakah Aigis menghadapi masalah baru lagi? Haruskah dia berbicara dengan Dokter Clementine sekali lagi?"
  },
  AvgDialog_18876_Content_74 = {
    Text = "Tunggu sebentar, siapa kamu? Jangan sembarangan menarik orang."
  },
  AvgDialog_18876_Content_75 = {
    Text = "Aku sudah kenal lama dengan Xiao Ai dan Aigis, bocah baru. Sebelumnya, kalau Aigis sedih, dia selalu mengobrol denganku."
  },
  AvgDialog_18876_Content_76 = {
    Text = [[
Bagaimanapun, berbagi keluhan adalah salah satu metode penyembuhan mental, dan kebetulan saya adalah pendengar yang sangat profesional. 
 Apakah kamu ingin bergabung dengan kami? Sepertinya kamu juga sedang memiliki masalah.]]
  },
  AvgDialog_18876_Content_77 = {
    Text = "Aku tidak mau pergi, apa itu terapi psikologis? Aneh-aneh…"
  },
  AvgDialog_18876_Content_78 = {
    Text = [[
Sayang sekali. Jika kamu berubah pikiran, kapan saja bisa datang untuk bergabung, ya.
Ayo pergi, Aigis.]]
  },
  AvgDialog_18876_Content_79 = {
    Text = "Setelah kedua orang itu pergi, kamu mengalihkan perhatian kembali ke depan."
  },
  AvgDialog_18876_Content_8 = {
    Text = "Tuan Rogers bisa dikatakan sebagai orang pertama yang menemukan penyakit aneh tersebut, terus memantau kondisi para pasien, dan juga dia yang memperkenalkan kami kepada <Blue:Dr. Miller> yang ahli dalam Penelitian penyakit-penyakit sulit."
  },
  AvgDialog_18876_Content_80 = {
    Text = "George · Rogers, senang bertemu dengan kalian berdua."
  },
  AvgDialog_18876_Content_81 = {
    Text = "Dia melepaskan satu tangannya untuk berjabat tangan denganmu. Saat telapak tangan saling bersentuhan, rasa pusing yang kuat langsung menyerangmu."
  },
  AvgDialog_18876_Content_82 = {
    Text = [[
Segala sesuatu di sekitarmu meleleh dengan cepat seperti lilin yang mencair, bahkan orang di depanmu pun menjadi terdistorsi dan berubah bentuk. 
Di balik wajah muda itu, kerangka pucat saling bertautan seperti sulur-sulur tanaman merambat.]]
  },
  AvgDialog_18876_Content_83 = {
    Text = "Ilusi aneh menghilang tanpa jejak setelah beberapa kali kedipan. Hanya suara dengungan tajam yang masih terdengar di telinga — apakah ini Fatamorgana yang dihasilkan oleh kelelahan, atau semacam pertanda?"
  },
  AvgDialog_18876_Content_84 = {
    Text = "Kamu tidak mengetahuinya. Kamu hanya tahu bahwa ini mirip dengan apa yang kamu alami beberapa hari lalu di pemakaman."
  },
  AvgDialog_18876_Content_85 = {
    Text = "……Setiap bulan dia akan datang sendiri untuk memeriksa keadaan pasien, berkat dia, kami dapat mendirikan area medis ini untuk merawat pasien. Dia adalah dermawan sejati dari bengkel kami."
  },
  AvgDialog_18876_Content_86 = {
    Text = "Nyonya Sarah terlalu memuji. Saya hanyalah orang biasa yang ingin melakukan sesuatu untuk dunia."
  },
  AvgDialog_18876_Content_87 = {
    Text = [[
Senang bertemu dengan Anda, Tuan Rogers. Nama saya Ash, dan ini pengurus rumah tangga saya, Mary.
Anak ini adalah Jenkin... Eh?]]
  },
  AvgDialog_18876_Content_88 = {
    Text = "Kemana dia pergi lagi?"
  },
  AvgDialog_18876_Content_89 = {
    Text = "Aigis menggandeng tangan Clementine, mengikuti langkahnya untuk berjalan-jalan di halaman depan."
  },
  AvgDialog_18876_Content_9 = {
    Text = "Dr. Miller berjanji untuk memberikan perawatan gratis kepada kami, hanya meminta kami menggunakan \"<Blue:Terapi Eksperimen>\" miliknya."
  },
  AvgDialog_18876_Content_90 = {
    Text = "Begitu ya, \"suara\" yang selalu muncul di pikiranmu di tengah malam hari<Red:\"suara\"> membuatmu berbuat jahat lagi?"
  },
  AvgDialog_18876_Content_91 = {
    Text = "Saya pernah mencoba mengunci pintu, menutup telinga... tapi \"suara\" itu selalu menemukan cara untuk mempengaruhi saya, mempengaruhi kita semua..."
  },
  AvgDialog_18876_Content_92 = {
    Text = "Mereka semua tidak ingat \"suara\" itu, hanya aku yang, meskipun ingin melupakan, tetap tidak bisa melupakannya."
  },
  AvgDialog_18876_Content_93 = {
    Text = "Banyak orang telah meninggal, termasuk kakak perempuan Jenkin… Aku benar-benar tidak tahan lagi. Jika terus berlanjut seperti ini, cepat atau lambat kita semua akan ketahuan dan ditangkap oleh polisi!"
  },
  AvgDialog_18876_Content_94 = {
    Text = "Apakah menurutmu mereka tidak bersalah?"
  },
  AvgDialog_18876_Content_95 = {
    Text = "Aku tahu mereka tidak bersalah! Semua ini karena \"suara\" itu, yang membuat semua orang berubah. Aku juga..."
  },
  AvgDialog_18876_Content_96 = {
    Text = "Bisakah kamu membantu saya, Dokter Clemetine? Peringatan saya tidak dipercaya oleh siapa pun. Jika itu dari kamu, mereka pasti akan mau mendengarkannya."
  },
  AvgDialog_18876_Content_97 = {
    Text = "\"Suara\" yang tidak dapat didengar oleh orang lain memang sulit dianggap sebagai bukti, dan orang-orang biasanya sulit bereaksi terhadap peringatan tanpa bukti, tapi — kamu tidak perlu merasa putus asa."
  },
  AvgDialog_18876_Content_98 = {
    Text = "Dunia ini, tidak ada yang tidak bisa diperoleh dengan mempertaruhkan nyawa."
  },
  AvgDialog_18876_Content_99 = {
    Text = [[
Aigis menundukkan kepalanya, tampak tenggelam dalam pikiran. 
 Di balik beberapa kotak kayu yang ditumpuk di sisi dinding halaman, sebuah kepala dengan tudung coklat muncul.]]
  },
  AvgDialog_18877_Content_1 = {
    Text = "Siapa yang membunuh burung robin"
  },
  AvgDialog_18877_Content_10 = {
    Text = [[
Taring tenggelam dalam kabut, sekelilingnya tampak suram, namun hal itu tampaknya tidak memengaruhi gadis itu. 
Dia berlari sekuat tenaga ke depan.]]
  },
  AvgDialog_18877_Content_11 = {
    Text = "Harus cepat, harus sangat cepat. Jika orang lain menemukannya, jika %player% menemukannya… \n Mereka akan membawa orang itu pergi, pasti akan membawanya pergi."
  },
  AvgDialog_18877_Content_12 = {
    Text = "Dia berbelok di sebuah tikungan, lalu tiba-tiba berhenti."
  },
  AvgDialog_18877_Content_13 = {
    Text = "Tidak, ya Tuhan, tidak..."
  },
  AvgDialog_18877_Content_14 = {
    Text = "Bukan kamu, Little Mike."
  },
  AvgDialog_18877_Content_15 = {
    Text = [[
20:50, Lily's Workshop Taring
Kamar Aigis]]
  },
  AvgDialog_18877_Content_16 = {
    Text = "Jenkin berjalan mengelilingi ruangan yang kosong, menghela napas sambil menaruh kedua tangan di pinggang."
  },
  AvgDialog_18877_Content_17 = {
    Text = "Tidak di toilet, tidak di dapur, bahkan kantin pun tidak. Dia ke mana, ya?"
  },
  AvgDialog_18877_Content_18 = {
    Text = "Dia langsung duduk di lantai, lalu merentangkan tangan ke bawah kasur dan meraba-raba di sekitarnya."
  },
  AvgDialog_18877_Content_19 = {
    Text = "Yah, sudahlah, tidak usah dipikirkan. Dia pasti akan kembali untuk tidur, jadi aku akan menunggunya di sini sambil makan permen!"
  },
  AvgDialog_18877_Content_2 = {
    Text = [[
20:43, Lily's Taring 
 Kamar Tamu]]
  },
  AvgDialog_18877_Content_20 = {
    Text = "Cit cit cit!"
  },
  AvgDialog_18877_Content_21 = {
    Text = "Kamu tidak boleh memberi tahu siapa pun! Lagipula, lain kali aku akan membelikannya lebih banyak——"
  },
  AvgDialog_18877_Content_22 = {
    Text = [[
Gerakan tangannya terhenti sejenak, lalu dia mengeluarkan sesuatu dari dalamnya. 
 Pita merah, gesper persegi berwarna perak, salah satu ujungnya tampak kasar seolah-olah telah disobek.]]
  },
  AvgDialog_18877_Content_23 = {
    Text = "Ini adalah... kakak...?"
  },
  AvgDialog_18877_Content_24 = {
    Text = "20:50, Halaman Depan Taring Lily\n"
  },
  AvgDialog_18877_Content_25 = {
    Text = "Taring di bawah malam telah jatuh tertidur, kamu dan Ramona bergegas kembali, sebuah firasat muncul di hatimu —— \nSegera, akan ada sesuatu selain kalian yang menghancurkan ketenangan."
  },
  AvgDialog_18877_Content_26 = {Text = "%player%."},
  AvgDialog_18877_Content_27 = {
    Text = "Kamu menutup mata kembali. Dingin yang tak terlukiskan merambat seperti air dari bagian belakang kepalamu ke seluruh anggota tubuh. Nyanyian tanpa sumber perlahan memudar, seakan-akan akan lenyap tertiup angin."
  },
  AvgDialog_18877_Content_28 = {
    Text = "Kamu membuka mata dan menyadari bahwa kabut di sekitarmu juga semakin menipis."
  },
  AvgDialog_18877_Content_29 = {
    Text = "Aku tidak bisa merasakannya lagi, seolah-olah... seolah-olah suaranya melemah."
  },
  AvgDialog_18877_Content_3 = {
    Text = "Rogers memainkan tangan George, membuat patung lilin memberi salam kepada Jenkin."
  },
  AvgDialog_18877_Content_30 = {
    Text = "Apakah fluktuasi roh individu spesial ada hubungannya dengan kabut ini?"
  },
  AvgDialog_18877_Content_31 = {Text = "!"},
  AvgDialog_18877_Content_32 = {
    Text = "Dari arah sana!"
  },
  AvgDialog_18877_Content_33 = {
    Text = "Kalian segera berlari ke arah suara itu, dan bertabrakan dengan Jenkin di depan pintu Taring."
  },
  AvgDialog_18877_Content_34 = {Text = "Jenkin?"},
  AvgDialog_18877_Content_35 = {
    Text = "Aigis tidak ada di dalam kamar! Mungkin tadi itu——ah, pokoknya cepatlah!"
  },
  AvgDialog_18877_Content_36 = {
    Text = [[
Mengingat kembali pemandangan mengerikan yang kamu lihat di jalan tadi, kamu mempercepat langkah masuk ke Taring. 
 Tak lama, seberkas cahaya muncul di ujung koridor.]]
  },
  AvgDialog_18877_Content_37 = {
    Text = "Itu adalah lentera gantung model lama, dipegang di tangan, menerangi wajah wanita dan anak tersebut."
  },
  AvgDialog_18877_Content_38 = {
    Text = "Aigis! Aku mendengar teriakan, apakah kamu baik-baik saja!"
  },
  AvgDialog_18877_Content_39 = {
    Text = [[
Gadis yang meringkuk di pelukan Sarah gemetar hebat, wajahnya semakin dalam terbenam di sisi leher Sarah. 
 Melihat itu, Jenkin terkejut sesaat, lalu berbalik ke arah Sarah dengan kemarahan.]]
  },
  AvgDialog_18877_Content_4 = {
    Text = "Halo, teman baik. Apakah kamu suka George?"
  },
  AvgDialog_18877_Content_40 = {
    Text = "Wanita sialan, apa kau melakukan sesuatu yang buruk padanya! Lepaskan dia, dengar atau tidak!"
  },
  AvgDialog_18877_Content_42 = {
    Text = [[
Sarah diam-diam menurunkan gadis itu. 
 Aigis menundukkan kepalanya, tapi kau masih bisa melihatnya di bawah cahaya lampu. Wajahnya penuh dengan air mata.]]
  },
  AvgDialog_18877_Content_43 = {
    Text = "Bisakah kamu membawanya kembali untuk beristirahat dulu? Aigis tersesat, takut gelap, dan sekarang sangat membutuhkan istirahat."
  },
  AvgDialog_18877_Content_44 = {
    Text = "Jenkin, sambil mencurigai Sarah dengan pandangan penuh keraguan, menarik tangan Aigis."
  },
  AvgDialog_18877_Content_45 = {
    Text = "Aigis menarik gaun Sarah dan mulai menangis pelan."
  },
  AvgDialog_18877_Content_46 = {
    Text = "Pergilah, Aigis kecil."
  },
  AvgDialog_18877_Content_47 = {
    Text = "Tidur dengan nyenyak, mimpi buruk akan berakhir besok, oke?"
  },
  AvgDialog_18877_Content_48 = {
    Text = "Tetapi... Nona Sarah..."
  },
  AvgDialog_18877_Content_49 = {
    Text = "Ayo pergi. Saya punya lampu, jadi tidak perlu takut."
  },
  AvgDialog_18877_Content_5 = {
    Text = "Begitu cantik, siapa yang tidak suka! Kamu benar, kan, Aigis?"
  },
  AvgDialog_18877_Content_50 = {
    Text = [[
Dua anak itu berpegangan tangan dan perlahan menjauh. 
Sarah berbalik ke arah kalian, memaksakan senyum yang terlihat sedikit kaku.]]
  },
  AvgDialog_18877_Content_51 = {
    Text = "Maaf sekali, apakah kalian berdua terganggu oleh teriakan saya?"
  },
  AvgDialog_18877_Content_52 = {
    Text = "Cuaca berkabut selalu membuat orang merasa tegang. Saya juga sempat terkejut oleh bayangan sesaat. Mohon beri saya kesempatan untuk meminta maaf, izinkan saya menyeduh secangkir teh untuk kalian berdua."
  },
  AvgDialog_18877_Content_53 = {
    Text = "Tidak perlu repot-repot, Nona Sarah. Saya dan {Male=tuan,Female=nona} bisa kembali sendiri."
  },
  AvgDialog_18877_Content_54 = {
    Text = [[
Bagaimana mungkin tidak? Tolong jawab saya, Ash {Male=tuan,Female=nona}, Nona Marie.
Jika tidak, saya benar-benar tidak bisa tenang!]]
  },
  AvgDialog_18877_Content_55 = {
    Text = [[
Jika Nona Sarah bersikeras seperti itu, maka temani kami berkeliling di Taring. 
Dengan begini, teh yang kita nikmati nanti akan terasa lebih manis. Bagaimana menurutmu?]]
  },
  AvgDialog_18877_Content_56 = {
    Text = "...Baik. Silakan ikuti saya, kedua tuan."
  },
  AvgDialog_18877_Content_57 = {
    Text = [[
21:03, Taring Lily 
 Koridor menuju ruangan Aigis]]
  },
  AvgDialog_18877_Content_58 = {
    Text = "Jenkin, kamu... kamu pergi ke kamarku dulu. Aku mau ke toilet sebentar."
  },
  AvgDialog_18877_Content_59 = {
    Text = "Kamu mau keluar lagi? Tidak takut, kan? Mau aku temani?"
  },
  AvgDialog_18877_Content_6 = {
    Text = "…\nMaaf, Jenkin. Aku... Maaf, aku pergi sebentar."
  },
  AvgDialog_18877_Content_60 = {
    Text = "Tidak apa-apa, aku akan segera kembali."
  },
  AvgDialog_18877_Content_61 = {Text = "Cepat."},
  AvgDialog_18877_Content_62 = {
    Text = [[
22:00, Taring Lily
Kamar Tamu]]
  },
  AvgDialog_18877_Content_63 = {
    Text = "Waktunya sudah hampir tiba, sesi diagnosis hari ini cukup sampai di sini saja."
  },
  AvgDialog_18877_Content_64 = {
    Text = [[
Terima kasih, Dokter Clementine. 
Setiap kali berbicara denganmu, aku merasa pikiranku menjadi lebih jelas.]]
  },
  AvgDialog_18877_Content_65 = {
    Text = [[
Ini semua adalah hal yang seharusnya kulakukan. 
Beritahu aku, apakah kamu tahu apa yang harus dilakukan selanjutnya?]]
  },
  AvgDialog_18877_Content_66 = {
    Text = "Tentu, tentu saja. Aku akan melanjutkannya."
  },
  AvgDialog_18877_Content_67 = {
    Text = "Seperti yang dia katakan: \"Keindahan, pada akhirnya, akan menggantikan semua penderitaan.\""
  },
  AvgDialog_18877_Content_7 = {
    Text = "Aigis? Kamu mau ke mana, hei, Aigis!"
  },
  AvgDialog_18877_Content_8 = {
    Text = [[
20:44, Lily Taring 
 Koridor]]
  },
  AvgDialog_18877_Content_9 = {
    Text = [[
Berlari. 
Aigis sedang berlari.]]
  },
  AvgDialog_18878_Content_1 = {
    Text = "Ogier dan Ramona masing-masing berada di satu sisi, menekan Jenkin yang terus melawan dengan keras."
  },
  AvgDialog_18878_Content_10 = {
    Text = "Paman Charlie memiliki seekor kucing tabby yang sangat dia cintai..."
  },
  AvgDialog_18878_Content_11 = {
    Text = "\"Kakak... jangan pergi...\""
  },
  AvgDialog_18878_Content_12 = {
    Text = "Suara Jenkin terdengar dari dalam gumpalan cahaya. Ia ingin mendekatimu, tetapi saat bergerak, tali hitam tipis langsung mengikatnya erat, sehingga ia hanya bisa mundur, seperti boneka yang dikendalikan oleh orang lain."
  },
  AvgDialog_18878_Content_13 = {
    Text = [[
Kamu tiba-tiba menyadari bahwa seseorang, atau sesuatu, sedang mengendalikannya. 
 Ketika kamu ingin membantunya melepaskan diri dari belenggu itu, tiba-tiba benang hitam tersebut menipis dan akhirnya menghilang sepenuhnya.]]
  },
  AvgDialog_18878_Content_14 = {
    Text = "\"Tidak... Aigis...?\""
  },
  AvgDialog_18878_Content_15 = {
    Text = "Titik cahaya tiba-tiba menjauh, dan ruang hitam dengan cepat menghilang."
  },
  AvgDialog_18878_Content_16 = {
    Text = "Kamu membuka mata dan tepat bertemu dengan tatapan Jenkin yang tampak bingung."
  },
  AvgDialog_18878_Content_17 = {
    Text = "%player%……? Ada apa, apakah ada masalah?"
  },
  AvgDialog_18878_Content_18 = {
    Text = "Ciiit ciiit ciiit ciiit!"
  },
  AvgDialog_18878_Content_19 = {
    Text = "Jenkin berkedip-kedipkan matanya yang kering, berniat untuk duduk, tetapi menyadari bahwa kedua tangannya terikat di belakang punggungnya."
  },
  AvgDialog_18878_Content_2 = {
    Text = "Apakah dia... histeris...?"
  },
  AvgDialog_18878_Content_20 = {
    Text = "Apa yang terjadi?! Siapa yang melakukannya, cepat lepaskan aku!"
  },
  AvgDialog_18878_Content_21 = {
    Text = "Kamu mengangguk kepada Ramona, dia maju dengan pedangnya dan dengan cepat memotong tali di pergelangan tangan Jenkin."
  },
  AvgDialog_18878_Content_22 = {
    Text = [[
Maaf, situasi mendesak, kami harus mengambil beberapa tindakan pencegahan. 
 Apakah... kamu masih ingat apa yang baru saja kamu lakukan?]]
  },
  AvgDialog_18878_Content_23 = {
    Text = "Baru saja? Bukankah kita sudah berencana untuk membobol ruang bawah tanah wanita itu? Untuk menghabiskan waktu, aku dan Cokelat bersembunyi di kamar Aigis menunggunya kembali, tapi tanpa sengaja tertidur dan bermimpi yang aneh-aneh…"
  },
  AvgDialog_18878_Content_24 = {
    Text = "Tunggu, ini bukan kamar Aigis. Kenapa aku ada di sini? Kalian... kalian membawaku ke sini untuk apa? Jangan-jangan kalian mau menculik dan membungkamku!"
  },
  AvgDialog_18878_Content_25 = {
    Text = "Kamu memang datang seperti yang dijanjikan, namun keadaanmu tadi sangat buruk, seolah-olah…"
  },
  AvgDialog_18878_Content_26 = {
    Text = "Seolah-olah ada sesuatu yang menguasai dirimu. Dengan kata lain, mungkin kamu sedang berada di bawah pengaruh hipnotis."
  },
  AvgDialog_18878_Content_27 = {
    Text = "Hipnotis… Ah! Apakah itu dokter psikologi yang membawa Aigis?"
  },
  AvgDialog_18878_Content_28 = {
    Text = "Terlalu tidak sopan mengatakannya. Terapi psikologis adalah ilmu, bukan kekuatan super yang bisa mengendalikan orang sembarangan... hehe, ilmu, ini mirip dengan yang dikejar oleh <Blue: Pygmalion>."
  },
  AvgDialog_18878_Content_3 = {
    Text = [[
Tidak, %player%, rohnya sedang gelisah. 
 Kekuatan roh Kunci Perak mungkin dapat memberikan efek menenangkan.]]
  },
  AvgDialog_18878_Content_30 = {
    Text = "Pedang Ramona segera terhunus. Mata pisaunya yang berwarna perak putih menggantung di sisi leher Clementine, namun dia sama sekali tidak takut. Sebaliknya, dengan santai dia menggunakan dua jarinya untuk menyingkirkan pedang tipis itu."
  },
  AvgDialog_18878_Content_31 = {
    Text = "Kamu waspada menatap wanita di depanmu — pintu dan jendela tidak terbuka, dia hampir muncul di hadapan kalian begitu saja. Tanpa suara, bak hantu."
  },
  AvgDialog_18878_Content_32 = {
    Text = "Apakah kamu dari Para pematung?"
  },
  AvgDialog_18878_Content_33 = {
    Text = [[
Saya hanyalah pihak ketiga yang antusias, meskipun saya memang memiliki sedikit kepentingan pribadi.
Kamu membuatku sangat tertarik, Penyelidik yang istimewa.]]
  },
  AvgDialog_18878_Content_34 = {
    Text = "Dia tersenyum ke arahmu, tatapannya yang tertuju padamu samar-samar mengandung semangat aneh yang mendalam."
  },
  AvgDialog_18878_Content_35 = {Text = "...Kenapa?"},
  AvgDialog_18878_Content_36 = {
    Text = "Clementine menyunggingkan senyuman misterius, mundur dua langkah, lalu sedikit membungkuk ke arahmu."
  },
  AvgDialog_18878_Content_37 = {
    Text = "Malam ini aku sudah berbicara terlalu banyak, hingga <Yellow:hati perakku> bergetar karena begitu bersemangat."
  },
  AvgDialog_18878_Content_38 = {
    Text = "<Yellow:Silver Heart>…Kamu adalah Pembangun?!"
  },
  AvgDialog_18878_Content_39 = {
    Text = "Kalau begitu, kami tidak bisa begitu saja membiarkanmu pergi, Clementine."
  },
  AvgDialog_18878_Content_4 = {
    Text = "Aktifkan Kunci Perak"
  },
  AvgDialog_18878_Content_40 = {
    Text = "Jika cerita pertemuan kita berakhir hari ini, bukankah itu akan terasa sangat membosankan?"
  },
  AvgDialog_18878_Content_41 = {
    Text = "Clementine entah dari mana mengeluarkan sebuah liontin aneh dan menggoyangkannya perlahan. Rasa lelah yang tak tertahankan langsung menyerang tubuhmu. Kamu bersandar di tepi meja, berusaha tetap berdiri, namun tidak mampu melangkahkan kaki."
  },
  AvgDialog_18878_Content_42 = {
    Text = [[
Pedang tipis di tangan Ramona terjuntai ke bawah, kepalanya bergoyang pelan, hampir tak mampu membuka kedua matanya. 
 Jenkin terbaring di tanah, tak bergerak, tampaknya langsung tertidur.]]
  },
  AvgDialog_18878_Content_43 = {
    Text = "Apa... yang telah kau lakukan..."
  },
  AvgDialog_18878_Content_44 = {
    Text = [[
Hanya sedikit trik kecil yang memungkinkan aku meninggalkan tempat ini. 
Dengan kemampuan kalian, seharusnya kalian bisa sadar kembali dengan cepat, bukan?]]
  },
  AvgDialog_18878_Content_45 = {
    Text = "Selamat tinggal, mata buta yang pucat. Kita akan bertemu lagi di masa depan…"
  },
  AvgDialog_18878_Content_46 = {
    Text = [[
Dia membungkuk kepada kalian, lalu keluar dari pintu. 
 Kamu tidak bisa menahan diri lebih lama dan terjatuh kembali ke kursi.]]
  },
  AvgDialog_18878_Content_47 = {
    Text = "Clementine menutup pintu kamarnya, bersenandung pelan dengan lagu yang riang di tenggorokannya, melambaikan tangan dengan ceria ke ujung koridor, lalu berbalik dan pergi."
  },
  AvgDialog_18878_Content_48 = {
    Text = [[
Di dalam kegelapan, gadis yang mengenakan rok berdiri tenang seperti patung. 
 Kepalanya tertunduk, dan dia dengan erat memegang penutup mata putih di tangannya.]]
  },
  AvgDialog_18878_Content_5 = {
    Text = "Kamu terperangkap dalam ruang hitam pekat, titik-titik kecil yang berkilauan dengan cahaya perak redup membentuk pola yang saling terhubung, bergerak naik turun seperti gelombang yang mengikuti ritme sulit ditebak."
  },
  AvgDialog_18878_Content_6 = {
    Text = [[
Kamu berdiri di antara mereka, namun tergantung di atasnya. Kamu adalah salah satu dari mereka, tetapi tidak sesuai dengan mereka. 
 Kamu tidak tahu persis apa mereka itu, kamu hanya tahu bahwa kamu datang untuk mencari seseorang.]]
  },
  AvgDialog_18878_Content_7 = {
    Text = "\"Kakak... Kakak...\""
  },
  AvgDialog_18878_Content_8 = {
    Text = [[
Kamu menatap ke arah suara itu, sebuah titik cahaya yang sangat redup berkedip di antara lautan bintang. 
Jalinan benang hitam dengan kilauan logam aneh melilitnya, menariknya, membuatnya tak bisa bergerak.]]
  },
  AvgDialog_18878_Content_9 = {
    Text = "Dari balik garis hitam itu terdengar melodi riang yang samar-samar, seperti nyanyian anak-anak yang dinyanyikan oleh seorang anak."
  },
  AvgDialog_18879_Content_1 = {
    Text = "Kalian keluar dari gang kecil dan tiba di depan gerbang besi rumah sakit panti asuhan."
  },
  AvgDialog_18879_Content_2 = {
    Text = "Di atas bangku kayu di samping pintu duduk seorang pria paruh baya dengan wajah berminyak. Di pinggangnya terikat sebuah tongkat kayu hitam, dan di mulutnya tergantung pipa rokok yang hitam legam."
  },
  AvgDialog_18879_Content_3 = {
    Text = "Kalian memperhatikan bahwa di lengan pria itu masih tersisa sedikit bekas hitam. Luka berbentuk segitiga tampak seperti jurang kecil, dan cairan kental perlahan mengalir keluar dari sana."
  },
  AvgDialog_18879_Content_4 = {
    Text = "Ramona dengan lembut membersihkan tenggorokannya, mengangkat dagu, dan melangkah maju, tampak seperti seorang pengurus bangsawan yang angkuh."
  },
  AvgDialog_18879_Content_5 = {
    Text = "Selamat pagi, Tuan. Mohon memberitahukan bahwa ada tamu yang datang."
  },
  AvgDialog_18879_Content_6 = {
    Text = "Kalimatnya belum selesai, tubuh petugas keamanan tiba-tiba berubah bentuk, cairan kental yang memancar dari dadanya berkumpul menjadi monster hitam raksasa, merayap mendekati kalian."
  },
  AvgDialog_18880_Content_1 = {
    Text = "Kakak, apa itu, Kakak?"
  },
  AvgDialog_18880_Content_10 = {
    Text = "Dan kamu hanya bisa menyaksikan dengan mata kepalamu sendiri saat dia jatuh, jatuh, dan mendarat di tanah kotor saluran pembuangan yang keras. Patung<Red:plastik> itu pecah menjadi potongan-potongan keras dengan berbagai ukuran."
  },
  AvgDialog_18880_Content_11 = {
    Text = "...patung? Kenapa patung?"
  },
  AvgDialog_18880_Content_12 = {
    Text = "Tidak sempat berpikir, kamu menengadah ke arah tempat kakak terjatuh."
  },
  AvgDialog_18880_Content_13 = {
    Text = "Tidak... tidak akan..."
  },
  AvgDialog_18880_Content_14 = {
    Text = "Gadis kecil yang kamu kenal baik berdiri di sana, penutup mata putihnya telah terjatuh, tatapannya kosong, dan tangannya memegang sepotong pita berwarna merah darah."
  },
  AvgDialog_18880_Content_2 = {
    Text = "Jangan bertanya, cepat lari, Jenkin."
  },
  AvgDialog_18880_Content_3 = {
    Text = "Monster semakin mendekat, secara bertahap memaksa kalian menuju Jurang."
  },
  AvgDialog_18880_Content_4 = {
    Text = "Dia hanyalah anak kecil dari daerah kumuh, tidak mengerti apa-apa, dan sama sekali tidak akan menjadi ancaman bagi kalian…"
  },
  AvgDialog_18880_Content_5 = {
    Text = "Kamu mengikuti petunjuk kakakmu, memeluk Cokelat, lalu mulai turun menyusuri pipa saluran air."
  },
  AvgDialog_18880_Content_6 = {
    Text = "<Shake: Tolong, aku mohon...>"
  },
  AvgDialog_18880_Content_7 = {
    Text = "Itu adalah setengah kalimat terakhir yang diucapkan oleh kakak."
  },
  AvgDialog_18880_Content_8 = {
    Text = "Pada saat suara terputus, siluet yang kamu kenal jatuh dari ketinggian, dengan tangan masih erat memegang sepotong pita merah yang terbelah."
  },
  AvgDialog_18880_Content_9 = {
    Text = [[
Pita itu adalah tabungan uang saku selama satu tahun penuh yang kau kumpulkan, dan kau secara pribadi memesannya untuknya. 
 Kau belum pernah bertemu dengan orang tua kandungmu, dia adalah orang terdekat dalam hidupmu.]]
  },
  AvgDialog_18881_Content_1 = {
    Text = "Tiba-tiba, sebuah bayangan hitam meluncur keluar dari sudut dinding, menyenggol Aigis dan menabrak dinding di sebelah kiri."
  },
  AvgDialog_18881_Content_10 = {
    Text = "Dia tiba-tiba melepaskan diri dari orang di belakangnya dan menerjang ke arahmu."
  },
  AvgDialog_18881_Content_2 = {
    Text = [[
Pada saat itulah kamu baru melihat dengan jelas bahwa yang berlari keluar adalah seorang pria dengan rambut berantakan.
Dia tidak mengenakan alas kaki, memakai pakaian dari panti asuhan, dan terdapat bekas ikatan yang jelas di pergelangan tangan serta kakinya.]]
  },
  AvgDialog_18881_Content_3 = {
    Text = [[
Beberapa orang yang tampaknya merupakan perawat mengejarnya dari belakang, mencoba menariknya menjauh. 
 Pria itu sama sekali tidak terpengaruh, dia mengangkat kepalanya ke belakang, lalu dengan keras memukulkan kepalanya ke permukaan dinding yang dingin dan keras.]]
  },
  AvgDialog_18881_Content_4 = {
    Text = "Di belakangmu, Aigis menghela napas."
  },
  AvgDialog_18881_Content_5 = {Text = "——!"},
  AvgDialog_18881_Content_6 = {
    Text = "Daging tulang menghantam batu bata dengan suara tumpul yang frekuensinya semakin cepat. Pria itu seolah-olah tidak merasakan sakit, terus-menerus menabrakkan dirinya ke dinding."
  },
  AvgDialog_18881_Content_7 = {
    Text = [[
Darah berceceran, meninggalkan bercak-bercak gelap di dinding dan lantai. 
 Kamu melangkah maju untuk membantu, namun tiba-tiba pria itu menghentikan gerakannya.]]
  },
  AvgDialog_18881_Content_8 = {
    Text = "Dia menghirup kuat-kuat melalui hidungnya, mengendus-endus udara di sekitarnya seperti seekor anjing, lalu berbalik ke arahmu dengan gerakan yang lambat dan kaku."
  },
  AvgDialog_18881_Content_9 = {
    Text = "Darah mengalir perlahan dari dahinya. Luka tersebut membengkak akibat benturan keras, kulitnya terbelah, dan kamu bahkan bisa melihat sedikit warna putih tulang di dalamnya."
  },
  AvgDialog_18882_Content_1 = {
    Text = "Kalian belum berlari jauh, anak-anak yang tadinya sedang bermain dengan cepat berkumpul di depan kalian dan menghalangi jalan."
  },
  AvgDialog_18882_Content_2 = {
    Text = "Tuan yang baik hati, beri saya sedikit uang receh. Jika tidak ada Surai, Pensh juga bisa…"
  },
  AvgDialog_18882_Content_3 = {
    Text = "Jika kamu mengeluarkan tanganmu dari saku %player%, kita masih bisa mempertimbangkannya."
  },
  AvgDialog_18882_Content_4 = {Text = "Hmph!"},
  AvgDialog_18882_Content_5 = {
    Text = "Anak itu berlari dengan cepat."
  },
  AvgDialog_18882_Content_6 = {
    Text = "Sepertinya perlu memberi sedikit pelajaran kepada anak-anak yang kurang beruntung ini karena minimnya pendidikan, apa menurutmu begitu?"
  },
  AvgDialog_18882_Content_7 = {Text = "Coba saja."},
  AvgDialog_18882_Content_8 = {
    Text = "Mereka tampaknya satu kelompok dengan Tudung Cokelat."
  },
  AvgDialog_18882_Content_9 = {
    Text = "Kalau begitu, mari berangkat. Menolong orang yang membutuhkan juga merupakan kewajiban sebagai warga negara."
  },
  AvgDialog_18883_Content_1 = {
    Text = "Ogier berlari dengan cemas, melewati satu demi satu dinding bata merah yang menghitam akibat terpapar udara Londinium."
  },
  AvgDialog_18883_Content_10 = {
    Text = "Saya tidak apa-apa, dan anak muda ini juga tidak sengaja, bukan?"
  },
  AvgDialog_18883_Content_11 = {
    Text = "Sangat maaf, aku tidak bisa memperhatikan situasi di sekitar tepat waktu."
  },
  AvgDialog_18883_Content_12 = {
    Text = [[
Clementine menyunggingkan senyuman lembut, lalu perlahan menepuk debu yang tak ada di ujung bajunya. 
 Dia mengangguk hormat, kemudian pergi dengan anggun.]]
  },
  AvgDialog_18883_Content_13 = {
    Text = [[
Kalian menengadah dan melihat tulisan besar yang terpampang di papan besi raksasa, "Panti Asuhan Lily" dengan huruf-huruf besar yang berkarat. 
 Di bawah tulisan itu, seorang petugas keamanan duduk santai dengan bosan.]]
  },
  AvgDialog_18883_Content_14 = {
    Text = [[
Sudah sampai pada titik ini, mari kita masuk dan lihat dulu. 
 Apakah kalian masih ingat identitas penyamaran kalian, Tuan atau Nyonya Ash{Male=tuan,Female=nona}, Si Muda Ash?]]
  },
  AvgDialog_18883_Content_15 = {
    Text = "Tenang saja, Dear Mary the Housekeeper."
  },
  AvgDialog_18883_Content_16 = {
    Text = "Siap melayani Anda, Nyonya Mary."
  },
  AvgDialog_18883_Content_17 = {
    Text = "...Ya sudah, selisihnya tidak terlalu besar."
  },
  AvgDialog_18883_Content_2 = {
    Text = "Pertama kali bekerja sama dengan Tuan dalam misi lapangan, tidak boleh..."
  },
  AvgDialog_18883_Content_3 = {Text = "Huh!"},
  AvgDialog_18883_Content_4 = {
    Text = "Gerbang besi yang tertanam di dinding bata terbuka ke dalam, dan seorang wanita berpakaian putih tiba-tiba muncul dalam pandangan, bertabrakan langsung dengan Ogier."
  },
  AvgDialog_18883_Content_5 = {
    Text = "<Small:Eh...>"
  },
  AvgDialog_18883_Content_6 = {
    Text = "Tidak, maaf! Apakah Anda baik-baik saja?"
  },
  AvgDialog_18883_Content_7 = {
    Text = "Kamu dan Ramona akhirnya berhasil menyusul Ogier."
  },
  AvgDialog_18883_Content_8 = {
    Text = "Maaf, kami... Eh, apakah Anda dokter psikolog yang tadi mengedarkan kuesioner?"
  },
  AvgDialog_18883_Content_9 = {
    Text = "Anda masih mengingat saya yang hanya bertemu sekali, ini adalah kehormatan besar bagi saya."
  },
  AvgDialog_18884_Content_1 = {
    Text = "Di ruang bawah tanah yang sempit ini ternyata tersembunyi begitu banyak monster..."
  },
  AvgDialog_18884_Content_2 = {
    Text = "Panti asuhan ini benar-benar tidak bisa dipandang sebelah mata."
  },
  AvgDialog_18884_Content_3 = {
    Text = "Ssst, mohon semua orang tetap tenang. Segera akan berakhir."
  },
  AvgDialog_18885_Content_1 = {
    Text = "Monster hitam melolong sekali, lalu berubah menjadi lumpur dan ambruk di tanah."
  },
  AvgDialog_18885_Content_10 = {
    Text = "Kalian menyandarkan tubuh keamanan yang tinggal di dekat pintu besi, kemudian berdiri dan melangkah masuk ke panti asuhan Lilian."
  },
  AvgDialog_18885_Content_11 = {
    Text = "Di ujung belokan, sebuah sosok putih melintas sekejap."
  },
  AvgDialog_18885_Content_12 = {
    Text = "Mereka... Kita harus kembali sebelum mereka bertemu dengan Nona Sarah. Mari kita masuk lewat jendela dapur."
  },
  AvgDialog_18885_Content_13 = {
    Text = "Mereka bisa membantu, jangan menolak kedatangan mereka."
  },
  AvgDialog_18885_Content_14 = {Text = "Jangan!"},
  AvgDialog_18885_Content_15 = {
    Text = "Orang-orang itu tidak akan gentar oleh apa yang terjadi di sini, aku bersumpah padamu."
  },
  AvgDialog_18885_Content_16 = {
    Text = "Tidak... tidak bisa melibatkan lebih banyak orang lagi... orang yang mendekati sini berada dalam bahaya, kamu seharusnya sudah tahu itu..."
  },
  AvgDialog_18885_Content_17 = {
    Text = "<Red:Anderson Sah>"
  },
  AvgDialog_18885_Content_2 = {
    Text = "Ini, ini... kenapa dia tiba-tiba berubah!"
  },
  AvgDialog_18885_Content_3 = {
    Text = [[
<Yellow:Pelarutan awal erosi>.
Seharusnya tidak terjadi secepat ini... bahkan seharusnya tidak terjadi sama sekali.]]
  },
  AvgDialog_18885_Content_4 = {
    Text = "Dua suara terdengar melalui bros, bergema di dalam pikiran kalian."
  },
  AvgDialog_18885_Content_5 = {
    Text = "Terdengar seperti produk dari katalis buatan."
  },
  AvgDialog_18885_Content_6 = {
    Text = "Perkembangan abnormal dari Pelarutan… kemungkinan besar terkait dengan <Yellow:Penyelidik Sean Anderson yang hilang>. \n Saya khawatir seseorang sudah mengincar panti asuhan… bahkan mungkin mengincar kalian."
  },
  AvgDialog_18885_Content_7 = {
    Text = "Kami akan berhati-hati."
  },
  AvgDialog_18885_Content_8 = {
    Text = "Tetap waspada, Penjaga."
  },
  AvgDialog_18885_Content_9 = {
    Text = "Pasti akan kutemukan."
  },
  AvgDialog_18886_Content_1 = {
    Text = "Tampaknya anak baru ini agak berbeda."
  },
  AvgDialog_18886_Content_2 = {
    Text = "Kita akan benar-benar bertindak."
  },
  AvgDialog_18887_Content_1 = {
    Text = "Sementara itu——\nOgier mengamati pemandangan di halaman rumah sakit melalui jendela."
  },
  AvgDialog_18887_Content_10 = {
    Text = "Tidak, jangan bawa dia pergi!"
  },
  AvgDialog_18887_Content_11 = {
    Text = [[
Anak kecil, apakah kamu salah paham tentang sesuatu?
Kami adalah dokter yang dipekerjakan oleh panti asuhan untuk membawanya melakukan pemeriksaan rutin.]]
  },
  AvgDialog_18887_Content_12 = {
    Text = "Ogier memerah karena gugup, namun segera menemukan akal."
  },
  AvgDialog_18887_Content_13 = {
    Text = "Tidak boleh! {Male=Tuan Penjaga Rahasia,Female=Nona Penjaga Rahasia} berkata bahwa sebentar lagi kami akan mewakili Tuan Mulia Ash untuk menanyai Aigis, kau tidak bisa membawanya pergi sekarang."
  },
  AvgDialog_18887_Content_14 = {
    Text = "Untuk anak-anak yang tidak patuh, kita harus menggunakan beberapa cara orang dewasa."
  },
  AvgDialog_18887_Content_2 = {
    Text = [[
Pintu besi berderit terbuka, sekelompok orang aneh berbaju putih masuk satu per satu. 
Anak-anak berbaris dalam kabut kelabu yang suram, membiarkan mereka dipilih.]]
  },
  AvgDialog_18887_Content_3 = {
    Text = [[
Di antara anak-anak, Ogier mengenali sosok yang familiar: 
 Gadis kecil berambut putih yang datang menyambut mereka pada hari itu.]]
  },
  AvgDialog_18887_Content_4 = {
    Text = "Dia menarik bahunya ke dalam, menundukkan kepala, dengan kedua tangan erat memelintir ujung bajunya. Meskipun tampak ketakutan, dia tetap berdiri di depan anak-anak lainnya."
  },
  AvgDialog_18887_Content_5 = {
    Text = "Dia mencoba membuat dirinya menjadi lebih kecil, semakin kecil, berharap bisa begitu saja menyusut ke dalam tubuhnya dan menghilang. Bayangan tinggi menjulang menutupinya, dia tiba-tiba gemetar, tidak berani bergerak sedikit pun."
  },
  AvgDialog_18887_Content_6 = {
    Text = [[
Pertengkaran pun meletus. 
 Orang aneh berbaju putih menarik lengan gadis itu, seakan memaksanya untuk menuruti kehendaknya.]]
  },
  AvgDialog_18887_Content_7 = {
    Text = "——Berhenti!"
  },
  AvgDialog_18887_Content_8 = {
    Text = "Ogier tidak bisa menahan diri lebih lama dan langsung menerjang ke arah makhluk berbaju putih serta gadis itu."
  },
  AvgDialog_18887_Content_9 = {
    Text = "Ai, Ai Shi Xiao Shaoye?"
  },
  AvgDialog_18888_Content_1 = {
    Text = "Kakek Robert... bagaimana bisa..."
  },
  AvgDialog_18888_Content_2 = {
    Text = "Hati-hati, sepertinya dia sudah sepenuhnya kehilangan akal sehatnya!"
  },
  AvgDialog_18889_Content_1 = {
    Text = "Tolong, jangan berikan kerusakan pada Nyonya Sarah, aku akan memberitahu kalian semua kebenarannya…"
  },
  AvgDialog_18889_Content_2 = {
    Text = "Ai... Jisi..."
  },
  AvgDialog_18889_Content_3 = {
    Text = "Dia masih memiliki secercah kesadaran!"
  },
  AvgDialog_18889_Content_4 = {
    Text = "Hancurkan dulu monster-monster ini, tahan Sarah! Kita masih perlu menanyainya tentang keberadaan Sean!"
  },
  AvgDialog_18889_Content_5 = {Text = "Mengerti!"},
  AvgDialog_18890_Content_1 = {
    Text = "Ramona meluncur ke belakang pria itu, satu tangan memegang pergelangan tangannya dan tangan lainnya menekan bahunya ke bawah, memutar lengan pria itu ke belakang serta dengan kuat mengunci gerakannya."
  },
  AvgDialog_18890_Content_10 = {
    Text = [[
Saya sudah sangat familiar dengan tempat ini, Nona Sarah, tidak perlu repot-repot. 
Dibandingkan dengan itu, kenapa Xiao Ai, Aigis menangis begitu sedih? Apakah ada yang mem-bully dia?]]
  },
  AvgDialog_18890_Content_11 = {
    Text = "<Small:Aku baik-baik saja, Tuan Rogers.>"
  },
  AvgDialog_18890_Content_12 = {
    Text = [[
Di bawah tatapan sedikit terburu-buru dari direktur, Aigis tiba-tiba menelan ucapannya kembali. 
Dia membungkuk kepada semua orang, memandangmu sekali lagi, lalu sosok kecilnya menghilang di balik pintu.]]
  },
  AvgDialog_18890_Content_13 = {
    Text = "Maaf telah menyembunyikan keberadaan area medis dari kalian, aku hanya khawatir kondisi pasien akan menular kepada kalian…"
  },
  AvgDialog_18890_Content_14 = {
    Text = "Ah, cukup tentang itu. Izinkan saya memperkenalkan kepada kalian seorang donatur jangka panjang kami — pemahat patung lilin terkenal, Tuan Rogers."
  },
  AvgDialog_18890_Content_15 = {
    Text = "Area medis ini, dan perawatan pasien, semua itu terwujud karena dia."
  },
  AvgDialog_18890_Content_16 = {
    Text = "George · Rogers, senang bertemu dengan kalian bertiga."
  },
  AvgDialog_18890_Content_17 = {
    Text = [[
Dia melepaskan satu tangannya untuk berjabat tangan denganmu dengan lembut. 
Saat telapak tangan saling bersentuhan, rasa pusing yang kuat langsung menyerangmu.]]
  },
  AvgDialog_18890_Content_18 = {
    Text = "Segala sesuatu di sekitarmu tampak meleleh seperti lilin yang mencair, bahkan orang di depanmu pun terdistorsi dan berubah bentuk. Di balik wajah itu, kerangka pucat saling berbelit seperti sulur tanaman."
  },
  AvgDialog_18890_Content_19 = {
    Text = "Ilusi aneh itu menghilang beberapa kali kedipan mata kemudian, hanya menyisakan bunyi dengung tajam di telinga——apakah itu ilusi yang timbul dari kelelahan? Kamu tidak tahu."
  },
  AvgDialog_18890_Content_2 = {
    Text = [[
Ogier dengan cepat maju dan, dibantu oleh Ramona, mengikat tangan dan kakinya dengan kain. 
 Pria itu masih terus berusaha melawan, dan di antara bajunya yang terbuka terlihat sebuah bekas luka aneh.]]
  },
  AvgDialog_18890_Content_20 = {
    Text = "Kamu hanya tahu, ini mirip dengan pengalamanmu beberapa hari lalu di pemakaman."
  },
  AvgDialog_18890_Content_21 = {
    Text = "...Setiap bulan, dia selalu datang secara pribadi untuk memeriksa kondisi para pasien. Dia adalah seorang dermawan sejati dan juga merupakan penyokong besar bagi panti kami."
  },
  AvgDialog_18890_Content_22 = {
    Text = "Nyonya Sarah terlalu memuji. Saya hanyalah orang biasa yang ingin melakukan sesuatu untuk dunia."
  },
  AvgDialog_18890_Content_23 = {
    Text = "Ngomong-ngomong, kemarin Anda berkata bahwa hari ini akan datang bersama <Yellow:teman> untuk mengunjungi…"
  },
  AvgDialog_18890_Content_24 = {
    Text = "Pemahat itu, <Yellow:Pematung>, telah menemukan inspirasi dan sudah kembali ke studio lebih dulu."
  },
  AvgDialog_18890_Content_25 = {
    Text = "Anak muda ini adalah...?"
  },
  AvgDialog_18890_Content_26 = {
    Text = "……{Male=tuan,Female=nyonya}? Ash {Male=tuan,Female=nyonya}?"
  },
  AvgDialog_18890_Content_27 = {
    Text = [[
Ah, maafkan saya, mungkin semalam saya kurang istirahat, sedikit melamun. Senang bertemu dengan Anda, Tuan Rogers.
Nama saya Ash, ini adik saya Ogier dan pelayan kami Mary. Ini Jenkin...]]
  },
  AvgDialog_18890_Content_28 = {Text = "Eh?"},
  AvgDialog_18890_Content_29 = {
    Text = "Anak Jenkin, ke mana dia pergi?"
  },
  AvgDialog_18890_Content_3 = {
    Text = "Luka dalam yang membentang di seluruh dada, jahitan yang terdistorsi dengan susah payah menyatukan celah yang tak kunjung sembuh. Di sela-sela jahitan, cairan hitam kental masih perlahan merembes keluar."
  },
  AvgDialog_18890_Content_4 = {
    Text = "Langkah-langkah terburu-buru terdengar di luar area medis. Sarah muncul dengan napas tersengal-sengal sambil memegang bingkai pintu."
  },
  AvgDialog_18890_Content_5 = {
    Text = "Melihat bagian dalam sudah tertata rapi, dia tampak sedikit rileks sejenak, lalu segera mengerutkan alisnya dan berbalik ke arah gadis yang meringkuk di sudut."
  },
  AvgDialog_18890_Content_6 = {
    Text = [[
Aigis! Bukankah sudah kubilang jangan biarkan donatur masuk ke area medis? 
 Jika terjadi sesuatu pada donatur di sini, siapa yang akan...]]
  },
  AvgDialog_18890_Content_7 = {
    Text = "Apa, apa yang terjadi?"
  },
  AvgDialog_18890_Content_8 = {
    Text = [[
Kamu mengikuti suara dan menoleh ke belakang, hanya untuk menemukan dua orang berdiri di sana entah sejak kapan. 
 Salah satunya sudah kamu kenal: wanita berbaju putih yang pernah bertabrakan dengan Ogier.]]
  },
  AvgDialog_18890_Content_9 = {
    Text = [[
Tuan Rogers, Dokter Fairfax! 
Maaf, silakan menunggu di area istirahat dan menikmati beberapa camilan sambil menunggu saya. Saya akan segera menyelesaikan urusan di sini dan melayani Anda...]]
  },
  AvgDialog_18891_Content_1 = {
    Text = "Detektif Kecil"
  },
  AvgDialog_18891_Content_10 = {
    Text = "Kamu mengikuti lokasi yang tertulis di gulungan kertas menuju halaman belakang. Sebelum mendekat, kamu sudah mendengar suara seorang anak bergumam di bawah dinding."
  },
  AvgDialog_18891_Content_11 = {
    Text = [[
Ingatlah, jika penyandang dana itu bertindak merugikan kita, segera beri tahu aku. 
Wanita sialan itu pasti akan menyuruh Aigis pergi membantu <Yellow:orang gila> di sana, kau cukup bawa dia kemari.]]
  },
  AvgDialog_18891_Content_12 = {
    Text = "Apa penyakit gila ini?"
  },
  AvgDialog_18891_Content_13 = {
    Text = "Wow! Bagaimana bisa kamu tiba-tiba muncul! Lagipula, bukankah aku sudah bilang untuk datang sendiri!"
  },
  AvgDialog_18891_Content_14 = {
    Text = "Tikus kecil meloncat ke bahu anak bertudung, dengan gugup menegangkan kumisnya ke arahmu."
  },
  AvgDialog_18891_Content_15 = {
    Text = "Itu bukan dompet saya, saya tidak bisa memutuskan."
  },
  AvgDialog_18891_Content_16 = {
    Text = "Jangan berpura-pura, tidak ada yang bisa lepas dari mata tikus kecil — Kakak berambut putih menyamar sebagai pelayan, si rambut emas kecil masih harus bertanya arah, hanya kamu yang berjalan santai tanpa melakukan apa pun."
  },
  AvgDialog_18891_Content_17 = {
    Text = "Jangan kira aku tidak tahu, kau adalah orang yang sebenarnya memegang kendali. Lagipula, yang ada di dalam sini bukanlah sertifikat seorang tuan muda."
  },
  AvgDialog_18891_Content_18 = {
    Text = "Tangan Jenkin bergerak cepat, entah dari mana ia mengeluarkan sebuah dompet. Dompet itu memiliki tekstur dan bentuk yang familiar, dengan lambang Universitas Mythag tercetak di atasnya, ini adalah dompet milik Ogier."
  },
  AvgDialog_18891_Content_19 = {
    Text = "Benar, Cokelat?"
  },
  AvgDialog_18891_Content_2 = {
    Text = "Seperti yang kau lihat, meskipun kami sudah berusaha sepenuhnya untuk menampung para pencari bantuan, jumlah orang yang membutuhkan bantuan terlalu banyak! Jika begini terus, rumah sakit pun tidak akan bisa bertahan lama lagi… aku… huh!"
  },
  AvgDialog_18891_Content_20 = {
    Text = "Cik, cik cik!"
  },
  AvgDialog_18891_Content_21 = {
    Text = "Ah! Dompetku!"
  },
  AvgDialog_18891_Content_22 = {
    Text = "Ogier dengan cemas meraih ke arah dompet, Jenkin menghindar ke samping, dan dompet itu lenyap seperti sulap."
  },
  AvgDialog_18891_Content_23 = {
    Text = [[
Terlalu tidak sopan, Anak Kecil Emas.
Apakah semua orang dari Universitas Mythag memperlakukan gadis kecil yang terlantar di jalan seperti ini?]]
  },
  AvgDialog_18891_Content_24 = {
    Text = "Apakah kamu... seorang gadis?"
  },
  AvgDialog_18891_Content_25 = {
    Text = "Apa ada masalah dengan matamu!? Aku jelas-jelas perempuan, PEREMPUAN!"
  },
  AvgDialog_18891_Content_26 = {
    Text = "Lupakan saja, jangan bicarakan ini lagi. Aku menyarankan kalian untuk patuh dan nurut, asalkan mengikuti aku—"
  },
  AvgDialog_18891_Content_27 = {
    Text = "Baiklah, kami setuju. Sebagai syarat pertukaran, bawa kami untuk melihat para <Yellow:orang gila> yang kau bicarakan."
  },
  AvgDialog_18891_Content_28 = {Text = "…?"},
  AvgDialog_18891_Content_29 = {
    Text = "Bukankah kamu menyuruh kami mencari seseorang di panti asuhan? Katakan, siapa yang harus kami cari?"
  },
  AvgDialog_18891_Content_3 = {
    Text = "Sarah, setiap hari Miss Sarah bekerja sangat keras. Dia bahkan menjual barang-barang kesayangannya untuk membantu panti asuhan. Tolong... tolong bantu kami..."
  },
  AvgDialog_18891_Content_30 = {
    Text = "Aku belum mengatakan apa-apa!"
  },
  AvgDialog_18891_Content_31 = {
    Text = "Kamu pasti akan mengatakannya. Jadi, aku menyarankan kita melewati langkah-langkah yang tidak perlu dan langsung bersikap terbuka satu sama lain."
  },
  AvgDialog_18891_Content_32 = {
    Text = [[
Kamu pasti datang untuk melakukan <Yellow:penyelidikan> tentang kasus hilangnya orang-orang di dekat panti asuhan, kan?
Kami juga. Membantu kamu dalam penyelidikan ini hanyalah masalah kecil bagi kami.]]
  },
  AvgDialog_18891_Content_33 = {
    Text = "Kamu... Bagaimana kamu bisa tahu?"
  },
  AvgDialog_18891_Content_34 = {
    Text = "Sangat sederhana. Kamu memiliki sepasang tangan yang cekatan dan sekelompok rekan tetap yang bekerja dengan kompak, sehingga bisa mendapatkan penghasilan stabil namun ilegal."
  },
  AvgDialog_18891_Content_35 = {
    Text = "Ramona berbicara sambil dengan kebiasaannya berjalan mondar-mandir di halaman."
  },
  AvgDialog_18891_Content_36 = {
    Text = "Kalian memiliki rencana yang lengkap: kamu bertanggung jawab atas pekerjaan utama, mereka memberikan perlindungan untuk memastikan kamu bisa melarikan diri dengan lancar. Sebagai imbalan, kamu akan memberikan sebagian dari hasil kepada mereka."
  },
  AvgDialog_18891_Content_37 = {
    Text = "Kamu bisa menjalani hidup yang lebih nyaman dan bebas di jalanan, sama sekali tidak perlu mencari nafkah di workhouse. Lagipula, jika kamu masuk ke workhouse tanpa izin dan ketahuan, kemungkinan besar akan mendapat masalah besar."
  },
  AvgDialog_18891_Content_38 = {
    Text = "Kenapa? Apa yang mendorongmu, sehingga kamu rela mengambil risiko didenda atau bahkan dipenjara, hanya untuk tetap tinggal di workhouse?"
  },
  AvgDialog_18891_Content_39 = {
    Text = [[
Hal ini, ditambah dengan kasus hilangnya orang-orang yang sering terjadi akhir-akhir ini di sekitar sini, mengarah pada satu dugaan: 
Keluarga atau temanmu hilang, dan kamu mencurigai bahwa hilangnya mereka ada hubungannya dengan panti asuhan.]]
  },
  AvgDialog_18891_Content_4 = {
    Text = "Melihat pertunjukan kedua orang itu — terutama Sarah — semakin berlebihan, kamu merasa cukup putus asa."
  },
  AvgDialog_18891_Content_40 = {
    Text = "Gadis itu menatap Ramona dengan tercengang, beberapa saat kemudian baru tersadar."
  },
  AvgDialog_18891_Content_41 = {
    Text = "Aku, kita bahkan belum berbicara sepuluh kalimat, tapi kau bertindak seolah-olah sudah menguntitku selama sepuluh hari…"
  },
  AvgDialog_18891_Content_42 = {
    Text = [[
Jika kita memperhitungkan saat kamu meminjam dompet Ogier, kamu sudah berbicara dengan kami sebanyak enam belas kalimat. 
Berdasarkan pengamatan terhadap realitas, jumlah kalimat tersebut sudah cukup untuk menganalisis dan menyimpulkan riwayat hidupmu.]]
  },
  AvgDialog_18891_Content_43 = {
    Text = "...Kalian memang sangat hebat. Kalau begitu, Cokelat."
  },
  AvgDialog_18891_Content_44 = {Text = "Cit!"},
  AvgDialog_18891_Content_45 = {
    Text = "Tikus kecil yang dipanggil Cokelat berderit, menggigit dompet dan melompat dari pohon besar, lalu melemparkannya ke pangkuan Ogier."
  },
  AvgDialog_18891_Content_46 = {
    Text = "Aku akan membawa kalian untuk bertemu dengan orang-orang gila, dan juga akan memberitahumu semua yang aku ketahui sebagai pertukaran ——"
  },
  AvgDialog_18891_Content_47 = {
    Text = "Kalian harus membantu aku mengalahkan hantu di Workhouse dan menyelamatkan kakak perempuanku, <Blue:Mason>."
  },
  AvgDialog_18891_Content_48 = {
    Text = "Kalian mengikuti Jenkin, berjalan menyusuri koridor di workhouse."
  },
  AvgDialog_18891_Content_49 = {
    Text = "Kakak setiap hari Kamis akan datang ke panti asuhan untuk mengambil pakaian dan membawanya pulang untuk dicuci. Mungkin karena pakaian itu juga tidak bersih, kakak tertular penyakit aneh yang sedang populer, disebut \"<Yellow:Histeria>\"."
  },
  AvgDialog_18891_Content_5 = {
    Text = "Tepat pada saat itu, sebuah gumpalan kertas kecil menghantam kepalamu."
  },
  AvgDialog_18891_Content_50 = {
    Text = [[
Kebetulan panti asuhan mengundang dokter, jadi dia sekalian datang untuk pemeriksaan.
Beberapa waktu lalu, dia berkata ingin datang untuk sembuh, lalu tidak pernah pulang ke rumah lagi.]]
  },
  AvgDialog_18891_Content_51 = {
    Text = "Jenkin tampak sangat cemas."
  },
  AvgDialog_18891_Content_52 = {
    Text = "Entah kenapa, akhir-akhir ini aku perlahan-lahan mulai lupa seperti apa wajah kakak."
  },
  AvgDialog_18891_Content_53 = {
    Text = "Terkadang, melihat sedikit barang yang ditinggalkan oleh kakak, aku bisa sejenak mengingatnya kembali, namun segera setelah itu melupakannya lagi."
  },
  AvgDialog_18891_Content_54 = {
    Text = "Ramona tiba-tiba berhenti, lalu mengangguk ke arahmu."
  },
  AvgDialog_18891_Content_55 = {
    Text = "Kenapa berhenti? Tidak mau pergi melihat orang gila lagi?"
  },
  AvgDialog_18891_Content_56 = {
    Text = "Tentang penyakit yang diderita kakakmu… kami mungkin memiliki beberapa petunjuk."
  },
  AvgDialog_18891_Content_58 = {
    Text = "Setelah mengajukan laporan permintaan pengungkapan informasi melalui komunikasi, Ramona perlahan berbalik ke arah Jenkin dan mulai menjelaskan informasi terkait Pelarutan."
  },
  AvgDialog_18891_Content_59 = {
    Text = "Jenkin, kakakmu terpengaruh oleh fenomena khusus yang disebut Pelarutan. Fenomena ini akan membuat keberadaan seseorang perlahan-lahan dilupakan oleh orang lain."
  },
  AvgDialog_18891_Content_6 = {
    Text = "Dari mana dia—"
  },
  AvgDialog_18891_Content_60 = {
    Text = "Tubuh, identitas, riwayat hidup, hubungan sosial… semuanya akan lenyap tanpa jejak dalam diam."
  },
  AvgDialog_18891_Content_61 = {
    Text = "Kondisi para pasien gila yang kamu sebutkan sangat mirip dengan <Yellow:gejala awal Pelarutan>. Kakakmu bahkan sudah mencapai tahap di mana keberadaannya mulai terhapus, aku khawatir dia..."
  },
  AvgDialog_18891_Content_62 = {
    Text = "Jenkin, Mason dia... sudah hilang selama berapa lama?"
  },
  AvgDialog_18891_Content_63 = {
    Text = "Dua puluh tujuh hari. Sejak saat itu, aku menghitung setiap hari."
  },
  AvgDialog_18891_Content_64 = {
    Text = "Melihat ekspresi ragu di wajah Ramona, Jenkin menghirup napas melalui hidungnya."
  },
  AvgDialog_18891_Content_65 = {
    Text = "Aku tahu, sudah begitu lama, kalian pasti merasa tidak ada harapan lagi. \nTapi aku yakin kakak masih hidup… intuisi anak jalanan itu sangat akurat."
  },
  AvgDialog_18891_Content_66 = {
    Text = "Jadi... aku harus segera menemukan kakak. Kalau tidak, aku akan sepenuhnya melupakan wajahnya, bahkan jika bertemu langsung pun aku tidak akan bisa mengenalinya."
  },
  AvgDialog_18891_Content_67 = {
    Text = "Jangan bersedih, kami akan membantu kamu menemukan kakakmu. Begitu kamu bisa melihatnya sekali saja, bukankah kamu akan ingat?"
  },
  AvgDialog_18891_Content_68 = {
    Text = [[
Ramona tidak melanjutkan pembicaraan.
Di bawah tatapan sedikit murungnya, kau mengingat kembali isi cerita yang diceritakan Boneka di kelas.]]
  },
  AvgDialog_18891_Content_69 = {
    Text = "<Yellow:\"Penghapusan keberadaan adalah gejala tahap akhir dari pelarutan, dan proses pelarutan tersebut tidak dapat dibalikkan.\">"
  },
  AvgDialog_18891_Content_7 = {
    Text = "Kamu mengulurkan tangan untuk menenangkan amarah Sarah, membuka gumpalan kertas itu, dan di atasnya tertulis satu baris kata dengan tulisan yang berantakan."
  },
  AvgDialog_18891_Content_8 = {
    Text = "\"Jika ingin mengambil tas sebelumnya, datang sendiri ke halaman belakang.\""
  },
  AvgDialog_18892_Content_1 = {
    Text = "Kalian terbangun oleh serangkaian teriakan tikus yang tajam dan mendesak. Ramona adalah yang pertama bangkit dari tempat tidur dan menyalakan lampu di ruangan itu."
  },
  AvgDialog_18892_Content_10 = {
    Text = "Mata pisaunya yang tajam memantulkan cahaya dingin, dan bilah pendeknya memantulkan wajahmu."
  },
  AvgDialog_18892_Content_11 = {Text = "Siapa!"},
  AvgDialog_18892_Content_12 = {
    Text = "Refleks yang terbentuk dari latihan membuatmu segera menghindar dan melihat dengan jelas sosok orang yang datang."
  },
  AvgDialog_18892_Content_13 = {Text = "Jenkin?!"},
  AvgDialog_18892_Content_14 = {
    Text = "Mata gadis itu kosong tanpa warna, ekspresinya datar hingga hampir terlihat seperti orang linglung. Dia sepertinya tidak mendengar panggilanmu sama sekali."
  },
  AvgDialog_18892_Content_15 = {
    Text = "Aku harus... membalas dendam untuk kakak..."
  },
  AvgDialog_18892_Content_16 = {
    Text = [[
Gerakannya sangat gesit, bilahnya melukis busur dingin di udara. 
Tanpa memberimu waktu untuk berpikir lebih lanjut, gadis itu kembali menyerangmu.]]
  },
  AvgDialog_18892_Content_17 = {
    Text = [[
Sepertinya satu-satunya cara adalah menundukkan dia dulu sebelum menginterogasinya. 
 Ramona, Ogier, tarik dia ke ruang terbuka!]]
  },
  AvgDialog_18892_Content_18 = {Text = "Di sini!"},
  AvgDialog_18892_Content_19 = {
    Text = "Siap mengikuti perintahmu!"
  },
  AvgDialog_18892_Content_2 = {
    Text = "Cokelat? Kenapa kamu datang sendiri."
  },
  AvgDialog_18892_Content_3 = {
    Text = "Ciiit——！Ciiit ciiit！"
  },
  AvgDialog_18892_Content_4 = {
    Text = "Kami bukan Jenkin, jadi kami tidak mengerti maksudmu."
  },
  AvgDialog_18892_Content_5 = {
    Text = "Waktunya hampir tiba, Jenkin seharusnya akan datang untuk bergabung dengan kita."
  },
  AvgDialog_18892_Content_6 = {
    Text = "Kamu menatap ke luar jendela, di tengah kabut putih yang tipis, bayangan bangunan tampak seperti patung-patung yang berdiri tegak di taman makam."
  },
  AvgDialog_18892_Content_7 = {
    Text = "Pintu berderit terbuka sedikit, dan angin dingin malam yang suram masuk melalui celah pintu yang gelap."
  },
  AvgDialog_18892_Content_8 = {
    Text = "Sebuah bayangan hitam dengan cepat meluncur dari balik meja dan kursi, dalam sekejap sudah menyerang tepat di hadapanmu."
  },
  AvgDialog_18893_Content_1 = {
    Text = "Musim Semi Botticelli"
  },
  AvgDialog_18893_Content_10 = {
    Text = "Tikus menyerang musang."
  },
  AvgDialog_18893_Content_11 = {
    Text = "Siapa yang kamu sebut tikus!"
  },
  AvgDialog_18893_Content_12 = {
    Text = "Kamu bilang siapa musang salju!"
  },
  AvgDialog_18893_Content_13 = {
    Text = "Hannah? Jenkin? Apa yang kalian lakukan di sini...?"
  },
  AvgDialog_18893_Content_14 = {
    Text = "Ini tidak bisa disalahkan padaku, dia yang pertama kali memanggil penjaga!"
  },
  AvgDialog_18893_Content_15 = {
    Text = "Ah, hanya bercanda. Hidup terlalu serius tidak ada keseruan."
  },
  AvgDialog_18893_Content_16 = {
    Text = "Jadi, yang datang mencarimu adalah kalian, kan? Di mana kalian bertemu, di panti asuhan Lilyan? Ah! Dia adalah Jenkin kecil itu, kan?"
  },
  AvgDialog_18893_Content_17 = {
    Text = "Tidak salah lagi, ini memang cerpelai salju nomor satu di Kerajaan Leo. Apakah kamu sedang mengumpulkan bahan untuk koran sekolah besok?"
  },
  AvgDialog_18893_Content_18 = {
    Text = "Bukan hanya itu, Ramona. Kamu tahu aku, informasi adalah hidupku."
  },
  AvgDialog_18893_Content_19 = {
    Text = "Lalu, di bawah terik matahari, gadis yatim yang malang pergi sendirian ke hutan lebat untuk berpetualang. Apa sebenarnya tujuannya?"
  },
  AvgDialog_18893_Content_2 = {
    Text = [[
13:20, Londinium
Universitas Mythag]]
  },
  AvgDialog_18893_Content_20 = {
    Text = [[
Orang yang ia cari dengan susah payah, akankah bisa memberinya sedikit cahaya? 
 Reporter garis depan Hannah Peaceley akan segera melakukan pelaporan investigasi!]]
  },
  AvgDialog_18893_Content_21 = {
    Text = "Hanna, sambil berbicara, tiba-tiba dengan suara \"plak\" mengeluarkan sebuah buku catatan entah dari mana, lalu menatap kalian penuh harap, seolah-olah siap mencatat setiap ucapan dan tindakan kalian."
  },
  AvgDialog_18893_Content_22 = {
    Text = "...Aku mulai mengerti, kalian semua di universitas aneh ini, tidak ada satu pun yang berbicara dengan cara yang mudah dimengerti."
  },
  AvgDialog_18893_Content_23 = {
    Text = "Saya tidak bersalah, sungguh."
  },
  AvgDialog_18893_Content_24 = {
    Text = [[
Kalau dia tidak ada, itu lebih baik. 
Ngomong-ngomong, Jenkin, apakah ada masalah?]]
  },
  AvgDialog_18893_Content_25 = {
    Text = "Jenkin mengeluarkan selembar koran yang terlipat kusut dari tasnya dan menyodorkannya ke arahmu serta Ramona."
  },
  AvgDialog_18893_Content_26 = {
    Text = "Sebelumnya kita sudah berjanji bahwa kamu akan membantu aku mencari kakakku. Sekarang, inilah saatnya kamu menepati janjimu."
  },
  AvgDialog_18893_Content_27 = {
    Text = "Dia membuka koran dan menunjuk ke sebuah artikel berjudul \"Lukisan Tiga Dimensi\", sebuah cerita lokal yang unik."
  },
  AvgDialog_18893_Content_28 = {
    Text = "Penulis menulis dengan gaya cerita nyata, dia pernah melihat sebuah pameran menakjubkan di museum lilin No. 44 Jalan Nanhua: karya baru dari seniman lilin Rogers berjudul \"Musim Semi\"."
  },
  AvgDialog_18893_Content_29 = {
    Text = "Sepertinya untuk meningkatkan kredibilitas, di sampingnya juga disertakan sebuah foto yang tampak meyakinkan."
  },
  AvgDialog_18893_Content_3 = {
    Text = "Kamu dan Ramona baru saja kembali ke gerbang sekolah, lalu melihat Jenkin dan seorang siswa yang mengenakan seragam berkelahi di tanah."
  },
  AvgDialog_18893_Content_30 = {
    Text = "Ini adalah kelompok patung lilin yang dibuat menyerupai lukisan terkenal Botticelli \"Primavera\", terletak di tengah-tengah adalah patung lilin wanita dengan cat yang konyol dan ekspresi penderitaan."
  },
  AvgDialog_18893_Content_31 = {
    Text = "Orang ini... entah mengapa, saya merasa dia sangat mirip dengan kakak perempuan saya."
  },
  AvgDialog_18893_Content_32 = {
    Text = "Rogers... Dokter Miller itulah yang memperkenalkannya kepada Sarah. Setelah insiden di workhouse, dia menghilang secara misterius."
  },
  AvgDialog_18893_Content_33 = {
    Text = "Jadi, orang inilah yang membunuh kakakku... dan... Aigis..."
  },
  AvgDialog_18893_Content_34 = {
    Text = "Aku tidak bisa menunggu lebih lama lagi. Kapan kita akan berangkat?"
  },
  AvgDialog_18893_Content_35 = {
    Text = "Mengingat bahwa pihak lain mungkin sangat berbahaya, aku lebih berharap kamu mau menunggu di sini untuk kabar dari kami. Namun — kamu pasti punya pemikiran lain, kan?"
  },
  AvgDialog_18893_Content_36 = {
    Text = [[
Itu kakakku, aku tidak mungkin tidak pergi!
Lagipula, siapa tahu kalian akan meminta bantuanku untuk merangkak melalui lubang ventilasi kapan saja!]]
  },
  AvgDialog_18893_Content_37 = {
    Text = "Keterampilan satu-satunya ini memang sangat berguna."
  },
  AvgDialog_18893_Content_38 = {
    Text = "Sepertinya harus mengajukan permohonan tugas lapangan mendesak."
  },
  AvgDialog_18893_Content_39 = {
    Text = "Saya sedang bersiap untuk menemui Profesor Alistair, berharap dia mau memberi kita akses belakang."
  },
  AvgDialog_18893_Content_4 = {
    Text = "……………"
  },
  AvgDialog_18893_Content_40 = {
    Text = "Selama kamu bersedia berbicara, pasti tidak ada masalah. Yang lebih penting adalah — kita perlu William menunda pengajuan laporan kita terlebih dahulu."
  },
  AvgDialog_18893_Content_41 = {
    Text = "Mengenai hal ini, kalian tidak perlu khawatir."
  },
  AvgDialog_18893_Content_42 = {Text = "?"},
  AvgDialog_18893_Content_43 = {
    Text = "Sekitar satu jam yang lalu, William meninggalkan sekolah dengan izin tugas lapangan."
  },
  AvgDialog_18893_Content_44 = {
    Text = "Aku awalnya ingin mengikutinya, melihat apakah bisa mendapatkan berita apa pun, tapi aku kehilangan jejaknya di jalan dan akhirnya kembali. Melihat arahnya, sepertinya dia pergi ke Barat Daya Londinium."
  },
  AvgDialog_18893_Content_45 = {
    Text = [[
Jalan Nanhuak ada di Distrik Barat. 
 Sepertinya kali ini, kita bisa menyaksikan sendiri kehebatan Penyelidik ternama, William.]]
  },
  AvgDialog_18893_Content_46 = {
    Text = "Apakah dia sudah mulai bergerak..."
  },
  AvgDialog_18893_Content_47 = {
    Text = [[
18:24, Londinium Barat Daya
Jalan Southwark]]
  },
  AvgDialog_18893_Content_48 = {
    Text = "Terima kasih atas kerja sama kalian semua. Selanjutnya, aku bisa menyelesaikannya sendiri."
  },
  AvgDialog_18893_Content_49 = {
    Text = [[
Ini tidak bisa, Tuan. Perintah dari atasan sangat jelas, kami harus menemani Anda dalam penyelidikan. 
 Lagipula, Rogers juga adalah salah satu tersangka kami, tidak mungkin membiarkan Anda bekerja sendirian.]]
  },
  AvgDialog_18893_Content_5 = {
    Text = "……………"
  },
  AvgDialog_18893_Content_50 = {
    Text = "Lagipula, dengan kami di sini, identitasmu bisa lebih tersembunyi dengan baik, bukan?"
  },
  AvgDialog_18893_Content_52 = {
    Text = "Tenang saja, Tuan. Kami punya senjata dan bisa berlari cepat, jadi tidak akan mengecewakan Anda."
  },
  AvgDialog_18893_Content_53 = {
    Text = "Baiklah, harap tingkatkan kewaspadaan. Jika perlu, prioritaskan hidupmu sendiri."
  },
  AvgDialog_18893_Content_54 = {
    Text = "Laporan. Tiba di lokasi misi, Jalan Southwark No. 44, Museum Lilin Rogers. Target dikonfirmasi: memastikan kemungkinan hubungan antara pemilik Museum Lilin Rogers dan Para pematung."
  },
  AvgDialog_18893_Content_55 = {
    Text = [[
Konfirmasi kedatangan di lokasi misi, konfirmasi target Penyelidikan.
Semoga Kunci Perak membimbing jalan ke depan.]]
  },
  AvgDialog_18893_Content_56 = {
    Text = "Semoga Kunci Perak membimbing kita."
  },
  AvgDialog_18893_Content_6 = {
    Text = "Tikus menggigit cerpelai"
  },
  AvgDialog_18893_Content_7 = {
    Text = "Saya merasa seperti melihat keajaiban dunia."
  },
  AvgDialog_18893_Content_8 = {Text = "Hah?"},
  AvgDialog_18893_Content_9 = {
    Text = "Apa keajaiban itu?"
  },
  AvgDialog_18894_Content_1 = {
    Text = "Malam tanpa burung terbang"
  },
  AvgDialog_18894_Content_10 = {
    Text = "Aku tidak bisa berhenti lagi."
  },
  AvgDialog_18894_Content_11 = {
    Text = [[
Saya tidak ingin melihat Nyonya Sarah, Si Kecil Mike, Jenkin, kalian semua...
Setiap orang yang saya kenal berubah menjadi seperti Tiyoug, batu yang tak bisa bergerak.]]
  },
  AvgDialog_18894_Content_12 = {
    Text = "Dengan suara terbata-bata setelah mengucapkan kalimat itu, Aigis berbalik dan berlari menuju pintu keluar basement."
  },
  AvgDialog_18894_Content_13 = {Text = "Tahan dia!"},
  AvgDialog_18894_Content_2 = {
    Text = "Inilah dosaku…."
  },
  AvgDialog_18894_Content_3 = {
    Text = "Aigis berhenti sejenak, lalu menutup matanya."
  },
  AvgDialog_18894_Content_4 = {
    Text = "Saya adalah pembunuh Tiyug. Saya mengubah Xiao Weili menjadi manusia gula. Saya adalah hantu panti asuhan yang sebenarnya."
  },
  AvgDialog_18894_Content_5 = {
    Text = "Sejak saat itu, selalu ada sesuatu yang mencoba menguasai tubuhku. Pada awalnya, untungnya ada <Yellow:Tuan Anderson> yang membantuku. Dia selalu ada di mataku, mengajari aku cara melawan kegelapan."
  },
  AvgDialog_18894_Content_6 = {
    Text = "Tetapi suaranya menjadi semakin lemah, hingga pada akhirnya, setiap <Yellow:malam berkabut> saya kehilangan kendali... Semua ini salahku, semua salahku."
  },
  AvgDialog_18894_Content_7 = {
    Text = "Saya sudah mencoba memakai penutup mata, mencoba mengikat diri di tempat tidur, tapi semuanya tidak berguna. Pada siang hari, tidak peduli seberapa keras saya berusaha, kain itu tetap tidak bergerak sedikit pun, namun Kekuatan itu dengan mudah bisa melepaskannya di malam hari."
  },
  AvgDialog_18894_Content_8 = {
    Text = "Aigis dengan lembut mengusap pergelangan tangannya yang memerah dan bengkak akibat gesekan."
  },
  AvgDialog_18894_Content_9 = {
    Text = [[
Nona Sarah, pasti sudah menemukan sesuatu, kan? 
Itulah sebabnya dia begitu mendesak, begitu mendesak agar Dokter menyembuhkanku.]]
  },
  AvgDialog_18895_Content_1 = {
    Text = "Siapa yang membunuh burung robin"
  },
  AvgDialog_18895_Content_10 = {
    Text = "Kamu pernah mendengar nyanyian ini dalam mimpi."
  },
  AvgDialog_18895_Content_11 = {
    Text = "Tubuh secara bertahap menjadi kaku, tulang yang mencoba bergerak mengeluarkan suara renyah \"krek krek\". Setiap gerakan terasa seperti memaksa memutar roda gigi boneka mekanis yang berkarat. Kamu bisa merasakan serpihan halus jatuh di antara celah-celah tulangmu."
  },
  AvgDialog_18895_Content_12 = {
    Text = "<Italic:Suatu hari dia menghilang, dan dia mencarinya di mana-mana.>"
  },
  AvgDialog_18895_Content_13 = {
    Text = [[
Kelopak mata terasa begitu berat seperti diisi timah, tak mampu menahan untuk tetap terbuka. 
 Dalam dunia kegelapan yang dilalui, hanya kabut kental yang melingkupi.]]
  },
  AvgDialog_18895_Content_14 = {
    Text = "<Italic:Charlie tua tidak bisa menemukan kucing lorengnya di mana pun.>"
  },
  AvgDialog_18895_Content_15 = {
    Text = [[
Dalam kehampaan yang gelap, kau berdiri sendirian. 
 Di langit tanpa batas, mata berwarna madu meneteskan air mata seperti sirup, memandangmu dari ketinggian.]]
  },
  AvgDialog_18895_Content_16 = {
    Text = "<Italic: Jadi dia menangis dan menangis——>"
  },
  AvgDialog_18895_Content_17 = {
    Text = "Entah mengapa, kamu teringat akan perjuangan orang tua yang sekarat itu dan setetes air mata hitam kental di sudut matanya."
  },
  AvgDialog_18895_Content_18 = {
    Text = "<Italic:——Hingga dirinya sendiri juga menghilang.>"
  },
  AvgDialog_18895_Content_19 = {
    Text = "Mengikuti insting yang entah dari mana datangnya, kamu menengadah ke arah mata di ketinggian yang tampak seolah sedang berbicara sesuatu, lalu bertanya dengan suara pelan."
  },
  AvgDialog_18895_Content_2 = {
    Text = "Menurut Jenkin, <Yellow:Hantu Workhouse> akan berkeliaran di halaman pada malam yang berkabut dan menculik para korbannya. Penyelidik Anderson mungkin adalah salah satu dari mereka."
  },
  AvgDialog_18895_Content_20 = {
    Text = "Ini bukan hasil yang kamu harapkan, kan?"
  },
  AvgDialog_18895_Content_21 = {
    Text = [[
Pupil berwarna madu bergetar saat berkedip. 
 Air mata bergoyang jatuh, menetes di pipi Anda, memancarkan aroma manis yang pekat.]]
  },
  AvgDialog_18895_Content_22 = {
    Text = [[
Nyanyian tiba-tiba terhenti, kegelapan dengan cepat memudar, dan sensasi kembali ke saraf. 
 Selama waktu yang kamu hilangkan, kabut tampaknya juga menjadi lebih tipis.]]
  },
  AvgDialog_18895_Content_23 = {Text = "Wah!"},
  AvgDialog_18895_Content_24 = {
    Text = "Gadis itu berlari mendekat, mengenali kalian dari jarak yang sangat dekat, lalu dengan cemas memeluk erat boneka beruang kecil di tangannya."
  },
  AvgDialog_18895_Content_25 = {
    Text = "Pendana, sponsor, kenapa kalian di sini?"
  },
  AvgDialog_18895_Content_26 = {
    Text = "Terima kasih atas jamuan kalian malam ini, kami keluar untuk berjalan-jalan dan mencerna makanan. Ada apa?"
  },
  AvgDialog_18895_Content_27 = {
    Text = "Hari-hari berkabut sangat berbahaya, jangan sekali-kali berjalan sembarangan di luar, kalau tidak…"
  },
  AvgDialog_18895_Content_28 = {
    Text = "Kalau tidak... apa yang akan terjadi?"
  },
  AvgDialog_18895_Content_29 = {
    Text = [[
Biarkan aku menebak... akan hilang, kan? 
 Apakah kamu tahu siapa para korban itu dan ke mana mereka pergi?]]
  },
  AvgDialog_18895_Content_3 = {
    Text = "Tidak ada waktu untuk disia-siakan, mari kita cari ruang bawah tanah rahasia yang disebutkan Jenkin sekarang juga."
  },
  AvgDialog_18895_Content_30 = {
    Text = "Aigis seperti tersambar petir di siang bolong, gemetar sambil menggelengkan kepala, tak mampu berkata-kata."
  },
  AvgDialog_18895_Content_31 = {
    Text = "Aigis, kamu adalah anak yang baik. Anak yang baik tidak seharusnya berbohong."
  },
  AvgDialog_18895_Content_32 = {Text = "Aku..."},
  AvgDialog_18895_Content_33 = {
    Text = "Jawab aku, Aigis. Kau bilang tidak boleh berjalan sembarangan di luar saat kabut tebal, lalu kenapa kau sendiri ada di sini?"
  },
  AvgDialog_18895_Content_34 = {
    Text = "Tangan gadis itu saling terjalin erat."
  },
  AvgDialog_18895_Content_35 = {
    Text = "Tolong... jangan tanyakan lagi..."
  },
  AvgDialog_18895_Content_36 = {
    Text = "Ramona, kabut semakin tebal."
  },
  AvgDialog_18895_Content_37 = {
    Text = "Di tengah kabut, sepasang mata merah menyala terang, menatap tajam kalian yang tak punya jalan untuk mundur."
  },
  AvgDialog_18895_Content_4 = {
    Text = "Jangan terburu-buru, pintu masuknya ada di dekat ruang kerja direktur."
  },
  AvgDialog_18895_Content_5 = {
    Text = [[
Setelah malam semakin larut dan Sarah tidur, kita akan melakukan pencarian lagi. 
Sebelum itu, kita harus beristirahat terlebih dahulu.]]
  },
  AvgDialog_18895_Content_6 = {
    Text = "Eh? Apakah ini kabut?"
  },
  AvgDialog_18895_Content_7 = {
    Text = [[
Saat kalian sedang berbincang, kabut tebal yang tidak biasa mulai menyelimuti sekitar. 
Uap air yang seharusnya ringan dan melayang, terasa seperti tekanan berat yang lengket menempel di tubuh kalian.]]
  },
  AvgDialog_18895_Content_8 = {
    Text = "Di tengah kabut tebal, kalian mendengar suara nyanyian."
  },
  AvgDialog_18895_Content_9 = {
    Text = "<Italic:Charlie tua memiliki seekor kucing belang yang sangat dia cintai…>"
  },
  AvgDialog_18896_Content_1 = {
    Text = "Dalam kegelapan yang samar, suara misterius terdengar di sisi telinga gadis itu."
  },
  AvgDialog_18896_Content_2 = {
    Text = "Menyerahlah, tutup matamu, serahkan semuanya padaku. \nSarah, Mikro… semua orang di panti asuhan akan menjadi keindahan, menjadi abadi."
  },
  AvgDialog_18896_Content_3 = {
    Text = "Tidak, tidak, kali ini aku benar-benar… tidak akan membiarkan diriku dikendalikan olehmu lagi…"
  },
  AvgDialog_18896_Content_4 = {
    Text = "Memberontak? Tanpa bantuan dari orang yang menyebalkan itu, Roh-mu hampir tidak bisa bertahan. Jika tidak begitu, aku juga tidak akan bisa mempengaruhimu saat kamu sadar."
  },
  AvgDialog_18896_Content_5 = {
    Text = "Lebih baik menyerah saja, lalu kamu bisa membantu aku mengubah semua orang di sini menjadi bahan yang berharga."
  },
  AvgDialog_18896_Content_6 = {
    Text = "Aku tidak akan menyerah! Tuan Anderson juga bukan orang yang menyebalkan!"
  },
  AvgDialog_18896_Content_7 = {
    Text = "Dia melindungi saya... Saya juga ingin melindungi semua orang, melindungi Nona Sarah, melindungi Xiao Mike, melindungi Jenkin. Juga melindungi kakak laki-laki dan kakak perempuan yang datang dari luar."
  },
  AvgDialog_18896_Content_8 = {
    Text = "Aku harus melindungi mereka, meskipun—meskipun harus membayar dengan segalanya——"
  },
  AvgDialog_18897_Content_1 = {
    Text = "Bagaimana, apakah kamu sudah menyadarinya? Meskipun kamu berusaha sekuat tenaga, meskipun kamu bertekad untuk mengorbankan segalanya, perubahan yang terjadi pada dirimu tidak akan berhenti."
  },
  AvgDialog_18897_Content_10 = {
    Text = "Saya percaya mereka, pasti bisa menghapuskan…"
  },
  AvgDialog_18897_Content_11 = {
    Text = "<Red:saya>."
  },
  AvgDialog_18897_Content_12 = {
    Text = "Aku sudah mendengarnya, kalian sangat sulit menemukan anak yang cocok untuk dijadikan subjek eksperimen."
  },
  AvgDialog_18897_Content_13 = {
    Text = "Perbuatan jahat yang kamu lakukan sudah terbongkar. Selanjutnya, selama aku tidak ada, mereka semua pasti bisa tetap aman, kan?"
  },
  AvgDialog_18897_Content_14 = {
    Text = "Suara misterius itu tidak memberikan jawaban."
  },
  AvgDialog_18897_Content_2 = {
    Text = "Sebenarnya, setiap orang setelah dewasa akan menemukan bahwa dunia memang seperti ini. Tidak peduli seberapa keras kamu berusaha, melawan, atau memberontak, tetap saja tidak bisa terlepas dari lingkungan yang mengelilingimu."
  },
  AvgDialog_18897_Content_3 = {
    Text = "Kamu masih anak-anak, tapi aku tidak keberatan memberitahumu prinsip ini lebih awal."
  },
  AvgDialog_18897_Content_4 = {
    Text = "Tidak, bukan seperti itu..."
  },
  AvgDialog_18897_Content_5 = {
    Text = [[
Karena aku... sudah bukan satu orang lagi... 
 Aku akan... mempercayai mereka!]]
  },
  AvgDialog_18897_Content_6 = {
    Text = "%player%{Male=Tuan Penjaga Rahasia,Female=Nona Penjaga Rahasia}, Kak Ramona, Ogier…\nMereka berbeda dari orang-orang di panti asuhan. Mereka sangat kuat dan pasti bisa menghilangkan…"
  },
  AvgDialog_18897_Content_7 = {
    Text = "Suara itu dengan tidak sabar memotong ucapannya menggunakan ejekan dingin."
  },
  AvgDialog_18897_Content_8 = {
    Text = [[
Menghabisiku...? Mereka bahkan tidak bisa menemukanku, kan? 
Lagipula, bahkan kau tidak tahu di mana aku berada.]]
  },
  AvgDialog_18897_Content_9 = {
    Text = "Tidak, bukan seperti itu..."
  },
  AvgDialog_18898_Content_1 = {
    Text = "Segalanya berjalan seperti biasa."
  },
  AvgDialog_18898_Content_10 = {
    Text = [[
Pendukung Rogers menghilang tanpa jejak, kelangsungan hidup panti asuhan menjadi sulit untuk dipertahankan. 
Akhirnya, Tuan Mulia Dexter dengan murah hati memberikan bantuannya dan mengirim orang untuk mengambil alih operasi panti asuhan.]]
  },
  AvgDialog_18898_Content_11 = {
    Text = "Pada hari Mulia Dexter memutuskan untuk mengambil alih panti asuhan Lily, kamu dan Ramona kembali datang ke dalam panti asuhan."
  },
  AvgDialog_18898_Content_12 = {
    Text = "Seorang yang berpakaian seperti biarawati menginstruksikan beberapa pekerja untuk memindahkan sebuah ranjang kecil dari area perawatan."
  },
  AvgDialog_18898_Content_13 = {
    Text = "Tetapi itu bukan Sarah yang kalian kenal."
  },
  AvgDialog_18898_Content_14 = {
    Text = "Aneh sekali, di sini jelas tidak pernah ada anak yang sakit, mengapa tempat tidur ini ada di sini…"
  },
  AvgDialog_18898_Content_15 = {
    Text = "Di rak besi yang tegak di sudut tempat tidur, terdapat beberapa helai kain yang telah disobek dan diikatkan di sana."
  },
  AvgDialog_18898_Content_16 = {
    Text = "Ya, seolah-olah sebagai jawaban atas keinginan Aigis, memori tentang Aigis di antara orang-orang di panti asuhan lenyap tanpa jejak hanya dalam dua minggu."
  },
  AvgDialog_18898_Content_17 = {
    Text = "Tatanan lama telah hancur, tatanan baru dengan cepat terbentuk."
  },
  AvgDialog_18898_Content_18 = {
    Text = [[
Ada yang pergi, ada yang menghilang, ada yang mimpi buruknya berakhir, ada yang kondisinya belum membaik. 
Namun, kehidupan terus berjalan, tanpa memberi sedikit pun waktu untuk bernapas.]]
  },
  AvgDialog_18898_Content_19 = {
    Text = "Sarah berbaring diam di atas sebuah ranjang kecil. Kepalanya masih dalam posisi terbuka, dan keempat anggota tubuhnya terikat oleh rantai."
  },
  AvgDialog_18898_Content_2 = {
    Text = "Setelah itu——"
  },
  AvgDialog_18898_Content_20 = {
    Text = "Bisa meminjamkan kunci?"
  },
  AvgDialog_18898_Content_21 = {
    Text = "Kapten Komite yang menemani kalian mengerutkan alisnya, lalu meletakkan kunci di atas meja samping tempat tidur."
  },
  AvgDialog_18898_Content_22 = {
    Text = "Aku akan keluar untuk memeriksa situasinya, kalian tolong jagakan tempat ini."
  },
  AvgDialog_18898_Content_23 = {
    Text = "Kamu dan Ramona dengan hati-hati membuka kunci rantai."
  },
  AvgDialog_18898_Content_24 = {
    Text = "Nona Sarah, apakah kamu masih... ingat kami?"
  },
  AvgDialog_18898_Content_25 = {
    Text = "Makhluk tanpa suara menggelengkan kepalanya — jika bagian yang retak dan mengeluarkan nanah hitam itu masih bisa disebut kepala."
  },
  AvgDialog_18898_Content_26 = {
    Text = "Kalau begitu, apakah kamu masih ingat... Aigis?"
  },
  AvgDialog_18898_Content_27 = {
    Text = "Seolah-olah tersesat dalam kebingungan, Sarah mengulangi kata-katamu."
  },
  AvgDialog_18898_Content_28 = {
    Text = "Ai… Ji… Si…?"
  },
  AvgDialog_18898_Content_29 = {
    Text = "Organ suara bergumam, gemetar mengeluarkan nada yang penuh kekacauan."
  },
  AvgDialog_18898_Content_3 = {
    Text = "Komite mengirim tim eksekusi ke panti asuhan Lilyan untuk mengawal Sanga keluar dari ruang bawah tanah."
  },
  AvgDialog_18898_Content_30 = {
    Text = "Setelah lama terdiam, Sarah mengulurkan tangan kanannya yang terkepal dan menghentikannya tepat di depanmu."
  },
  AvgDialog_18898_Content_31 = {
    Text = "Apakah kamu akan... memberi aku sesuatu?"
  },
  AvgDialog_18898_Content_32 = {
    Text = "Kamu membuka telapak tanganmu."
  },
  AvgDialog_18898_Content_33 = {
    Text = "Sebuah Perak kecil jatuh di telapak tanganmu."
  },
  AvgDialog_18898_Content_34 = {
    Text = "Ai… Ji… Si…"
  },
  AvgDialog_18898_Content_35 = {
    Text = "Ini... anak itu?"
  },
  AvgDialog_18898_Content_36 = {
    Text = "Memori yang kacau saling bertemu."
  },
  AvgDialog_18898_Content_37 = {
    Text = "Pada saat Aigis jatuh seperti burung yang terbang di malam hari, kalian semua bergegas ke arahnya."
  },
  AvgDialog_18898_Content_38 = {
    Text = [[
Jenkin menangkap seutas pita, kamu mengambil selembar bungkus permen, dan Sarah yang sudah jatuh ke dalam kegilaan... 
Mengikuti instingnya, dia menyentuh jiwa gadis itu.]]
  },
  AvgDialog_18898_Content_39 = {
    Text = "Serahkan pada Laboratorium Inti Perak, mungkin suatu hari kita bisa membangun gadis itu, dan kekuatan yang bersemayam di dalam dirinya."
  },
  AvgDialog_18898_Content_4 = {
    Text = "Saat keberangkatan, dia duduk di atas tandu yang diangkat oleh Komite, dengan ekspresi seperti tersenyum namun tidak, memandangmu dengan sudut matanya, bibirnya sedikit terbuka. Dari gerakan bibirnya, kamu membaca apa yang dia katakan."
  },
  AvgDialog_18898_Content_40 = {
    Text = "Apakah akan memberi tahu Jenkin tentang kabar baik ini?"
  },
  AvgDialog_18898_Content_41 = {
    Text = "…Memori Pembangun pada tahap awal akan mengalami kekacauan. \nBeberapa sepenuhnya kehilangan memori, beberapa hanya ingat momen dengan emosi yang mendalam, dan akan pulih secara bertahap seiring waktu."
  },
  AvgDialog_18898_Content_42 = {
    Text = "Lagipula, Aigis pada dasarnya adalah hasil modifikasi, struktur Perak-nya tidak stabil. \nMeskipun kita berhasil menyelesaikan proses Bangun, dia mungkin tidak akan mengenali Jenkin…"
  },
  AvgDialog_18898_Content_43 = {
    Text = "Saya pikir, lebih baik menunggu sampai semuanya stabil, lalu perlahan menjelaskan semuanya kepadanya."
  },
  AvgDialog_18898_Content_44 = {
    Text = "Kamu menutup telapak tanganmu, merasakan suhu dari Perak itu, dan mengingat kembali gadis yang selalu mengikuti orang lain dari belakang, seolah-olah tak terlihat."
  },
  AvgDialog_18898_Content_45 = {
    Text = "Pada saat pertemuan pertama, dia mengikuti di belakang Sarah, dengan malu-malu menyambut kedatangan kalian;"
  },
  AvgDialog_18898_Content_46 = {
    Text = "Ketika Jenkin membawa kalian ke area medis, dia ketakutan dan bersembunyi di belakang Jenkin."
  },
  AvgDialog_18898_Content_47 = {
    Text = "Hanya keberanian sesaat di detik-detik terakhir itulah yang membuatnya berubah menjadi meteor yang singkat, menghilang pada saat senja hari itu."
  },
  AvgDialog_18898_Content_48 = {
    Text = "Aigis... dengan pengorbanannya, menyelamatkan semua orang yang tertinggal."
  },
  AvgDialog_18898_Content_49 = {
    Text = "Dia adalah... ksatria sejati."
  },
  AvgDialog_18898_Content_5 = {
    Text = "Kamu bisa mengerti, kan?"
  },
  AvgDialog_18898_Content_50 = {
    Text = "<Blue:Penyelidik Sean Anderson>… Setelah kematiannya, Inti Perak-nya diekstraksi secara paksa oleh para pematung, dan sisa kesadarannya habis terpakai untuk membantu Aigis."
  },
  AvgDialog_18898_Content_51 = {
    Text = "Kami bahkan tidak bisa membereskan jenazahnya."
  },
  AvgDialog_18898_Content_52 = {
    Text = "Ramona, apakah kita bisa menyelamatkan sesuatu? Apakah kita bisa mengubah sesuatu?"
  },
  AvgDialog_18898_Content_53 = {
    Text = "Inilah perjalanan untuk melawan Pelarutan."
  },
  AvgDialog_18898_Content_54 = {
    Text = "Penjaga, kamu adalah yang istimewa. Oleh karena itu, kamu tidak boleh berhenti di sini."
  },
  AvgDialog_18898_Content_55 = {
    Text = "Kita akan pergi untuk menyelamatkan dan mengubah. \nNamun, meskipun pada akhirnya tidak ada yang berhasil dicapai…"
  },
  AvgDialog_18898_Content_56 = {
    Text = "Sebelum kedatangan malam yang dalam di mana segala sesuatu dilupakan, aku juga berharap kau menggunakan kedua matamu untuk menyaksikan dan mencatat memori dari semua yang terjadi."
  },
  AvgDialog_18898_Content_6 = {
    Text = "Imam utama Katedral Londinium muncul di rumah sakit umum dan, setelah berkonsultasi dengan Komite, memutuskan untuk sementara menampung Sarah, yang akan mengalami perubahan irreversible, di dalam gereja dengan pengawasan anggota Komite."
  },
  AvgDialog_18898_Content_7 = {
    Text = "Berdasarkan rute yang hanya bisa diingat dengan susah payah oleh anak-anak, kalian berhasil menemukan lokasi eksperimen Dr. Miller."
  },
  AvgDialog_18898_Content_8 = {
    Text = "Di sana sudah kosong tanpa seorang pun."
  },
  AvgDialog_18898_Content_9 = {
    Text = "William memberikan tugas kepada tim penyelidikan untuk melanjutkan pelacakan keberadaannya, dan menghubungi Komite untuk secara bersamaan melakukan pencarian menyeluruh di markas para pematung."
  },
  AvgDialog_18899_Content_1 = {
    Text = "Mimpi Kegelapan"
  },
  AvgDialog_18899_Content_10 = {
    Text = "<Italic:Dia membuka lemari pakaian. Dia melihat ke bawah tempat tidur.>"
  },
  AvgDialog_18899_Content_11 = {
    Text = "Ruang terasa semakin sempit, rasa tertekan yang menghimpit menggerogoti indra pernapasanmu, Tubuhmu secara bertahap menjadi kaku, dan perlahan-lahan tak bisa bergerak."
  },
  AvgDialog_18899_Content_12 = {
    Text = "<Italic:Dia berkeliling di basement tempat boiler sedang menyala.>"
  },
  AvgDialog_18899_Content_13 = {
    Text = [[
Hanya bola mata dan tenggorokan yang masih berfungsi dengan susah payah. 
 Seluruh tubuh terasa seperti digerogoti serangga, menyebabkan rasa sakit yang halus dan menusuk.]]
  },
  AvgDialog_18899_Content_14 = {
    Text = "<Italic:Charlie tua tidak bisa menemukan kucing lorengnya di mana pun.>"
  },
  AvgDialog_18899_Content_15 = {
    Text = "<Shake: siapa yang bisa... menyelamatkan... aku...>"
  },
  AvgDialog_18899_Content_16 = {
    Text = "<Italic: Jadi dia menangis dan menangis——>"
  },
  AvgDialog_18899_Content_17 = {
    Text = "<Shake:……@1……aku……menarik@1……>"
  },
  AvgDialog_18899_Content_18 = {
    Text = "<Italic:——Hingga dirinya sendiri juga menghilang.>"
  },
  AvgDialog_18899_Content_19 = {
    Text = "Rasa manis dan amis membanjiri tenggorokan, bahkan pita suara pun berhenti bergetar, dunia terperangkap dalam keheningan mutlak."
  },
  AvgDialog_18899_Content_2 = {
    Text = "Kamu terbangun dalam kegelapan gulita."
  },
  AvgDialog_18899_Content_21 = {
    Text = "Pada suatu waktu, di suatu tempat, kamu pernah mengalami hal yang sama persis seperti ini."
  },
  AvgDialog_18899_Content_22 = {
    Text = "Pada saat itu, orang yang menarikmu dari kegelapan adalah ——"
  },
  AvgDialog_18899_Content_23 = {
    Text = "Bangun, bangun! %player%!"
  },
  AvgDialog_18899_Content_24 = {
    Text = "Cahaya muncul secara tiba-tiba, seseorang menarik tanganmu, dan kamu terbangun dengan keringat dingin."
  },
  AvgDialog_18899_Content_25 = {
    Text = "Apa kamu bermimpi aneh lagi?"
  },
  AvgDialog_18899_Content_26 = {
    Text = "...Aku tidak tahu."
  },
  AvgDialog_18899_Content_27 = {
    Text = "Setelah kembali dari <Yellow:Akut>, kamu sering bermimpi. \n Bermimpi tentang mimpimu sendiri, bermimpi tentang mimpi orang lain, bermimpi tentang masa lalu, dan kadang-kadang… bermimpi tentang masa depan."
  },
  AvgDialog_18899_Content_28 = {
    Text = "Ramona, bisakah kamu menemani aku ke Kuil Kunci?"
  },
  AvgDialog_18899_Content_29 = {
    Text = "Ramona dan kamu berjalan tanpa suara di dalam Key Mound, hingga menemukan satu batu nisan di antara banyaknya makam — yang tampak biasa namun unik."
  },
  AvgDialog_18899_Content_3 = {
    Text = "Sepertinya ini adalah ruang tertutup, sempit, gelap, sunyi, dingin, tanpa cahaya, dan udara yang tipis, seperti bagian dalam peti mati."
  },
  AvgDialog_18899_Content_30 = {
    Text = "Inilah batu nisanmu."
  },
  AvgDialog_18899_Content_31 = {Text = "Ramona..."},
  AvgDialog_18899_Content_32 = {
    Text = "Saya bermimpi tentang ledakan besar Akut… Bermimpi bahwa saya tertimbun di bawah puing-puing, saat kau menggali dan menemukanku."
  },
  AvgDialog_18899_Content_33 = {
    Text = "Kamu dan Mythag, memberiku hidup kedua."
  },
  AvgDialog_18899_Content_34 = {
    Text = [[
Menemukanmu adalah keberuntungan bagi aku dan Mythag. 
 Jika bukan karena kamu, semua orang di sini akan dilenyapkan oleh <Yellow:Pelarutan Clades> Akut.]]
  },
  AvgDialog_18899_Content_35 = {
    Text = "Apakah sebelum itu, kamu masih belum ingat?"
  },
  AvgDialog_18899_Content_36 = {
    Text = "Kau menggelengkan kepala."
  },
  AvgDialog_18899_Content_37 = {
    Text = "Debu tebal Akut dan wajah cemas Ramona, inilah titik awal memori-mu. Kehidupan sebelumnya sepertinya lenyap bersama ledakan besar di padang gurun yang tak berujung."
  },
  AvgDialog_18899_Content_38 = {
    Text = "Dokter sekolah Sylvia pernah berkata, pemulihan ingatan bukanlah hal yang instan. Dengan lebih sering berinteraksi dengan orang dan hal-hal, mungkin selama proses itu, kita bisa perlahan-lahan mengingat sesuatu."
  },
  AvgDialog_18899_Content_39 = {
    Text = "Apakah suasana hatimu sudah lebih tenang? <Blue:William> masih menunggu kita untuk melaporkan kepadanya."
  },
  AvgDialog_18899_Content_4 = {
    Text = "Rasa takut menenggelamkanmu. Kamu berjuang, memukul, berteriak, namun tetap tidak bisa terlepas dari kegelapan tanpa akhir."
  },
  AvgDialog_18899_Content_40 = {
    Text = "Sekilas tinjau tujuan tugas: masuk secara diam-diam ke Panti Asuhan Lillian, mencari penyelidik yang hilang <Blue:Sean Anderson>."
  },
  AvgDialog_18899_Content_41 = {
    Text = "Penyelidik dari tim vanguard tidak mendeteksi sinyal <Yellow:Clades> berbahaya di luar workhouse, namun kalian tetap harus berhati-hati. Selain Ramona, kali ini akan ada Pembangun lain yang menemani kamu."
  },
  AvgDialog_18899_Content_42 = {
    Text = "Meskipun kamu memiliki bakat untuk menghubungkan beberapa Pembangun sekaligus, mengingat beban tubuh yang mungkin ditimbulkan oleh tautan tersebut, misi kali ini akan ditemani oleh Ogier yang sudah menyelesaikan tautan."
  },
  AvgDialog_18899_Content_43 = {
    Text = "Ya! Ogier akan dengan sepenuh hati membantu tuan menyelesaikan penyelidikan!"
  },
  AvgDialog_18899_Content_44 = {
    Text = "Apakah ada informasi lain yang perlu kita ketahui terkait hilangnya Penyelidik Anderson?"
  },
  AvgDialog_18899_Content_45 = {
    Text = "Wilayah sekitar panti sosial merupakan lokasi dengan insiden hilangnya orang di Distrik Timur yang tinggi, laporan hilang pertama dapat ditelusuri hingga setengah tahun yang lalu. Penyelidik Anderson lahir di Distrik Timur, sangat mungkin dia terlibat dalam serangkaian kasus hilangnya orang tersebut."
  },
  AvgDialog_18899_Content_46 = {
    Text = "Jika bisa sekaligus memecahkan kasus hilangnya penyelidik, itu akan lebih baik. Tapi jangan lupa, tugas utama kalian adalah mencari penyelidik yang hilang."
  },
  AvgDialog_18899_Content_47 = {
    Text = [[
Jangan tunda lagi, Sean masih menunggu bantuan kalian, segera berangkatlah. 
 Semoga Kunci Perak membimbing jalan ke depan.]]
  },
  AvgDialog_18899_Content_5 = {
    Text = "Perlahan-lahan, nyanyian mulai terdengar."
  },
  AvgDialog_18899_Content_6 = {
    Text = "<Italic:Charlie yang tua memiliki seekor kucing tabby yang sangat ia cintai.>"
  },
  AvgDialog_18899_Content_7 = {
    Text = "Halo——ada orang——apa ada orang di luar sana——"
  },
  AvgDialog_18899_Content_8 = {
    Text = "<Italic:Suatu hari dia menghilang, dan dia mencarinya di mana-mana.>"
  },
  AvgDialog_18899_Content_9 = {
    Text = "Perasaan ini terasa familiar, ya, di suatu waktu dan tempat, kamu juga pernah terjebak dalam kegelapan yang begitu dalam dan menyesakkan."
  },
  AvgDialog_18900_Content_1 = {
    Text = "Mimpi Buruk Berwarna"
  },
  AvgDialog_18900_Content_10 = {
    Text = [[
Kami berbaris, menunggu dokter memilih. 
 Saya merasa ringan, seolah-olah tidak ada di dunia ini.]]
  },
  AvgDialog_18900_Content_11 = {
    Text = "Gadis ini saja, kondisinya agak rumit. Terakhir kali, kami tidak berhasil menyembuhkannya sepenuhnya."
  },
  AvgDialog_18900_Content_12 = {
    Text = "<Shake: Tidak... aku tidak mau pergi... Aku sudah pernah ke sana sekali, aku tidak mau...>"
  },
  AvgDialog_18900_Content_13 = {
    Text = "Saya pergi saja, Tuan."
  },
  AvgDialog_18900_Content_14 = {Text = "!"},
  AvgDialog_18900_Content_15 = {
    Text = "...Apakah ada yang membuatmu merasa tidak nyaman?"
  },
  AvgDialog_18900_Content_16 = {
    Text = [[
Aku tidak merasa tidak enak, bisa berlari dan melompat, sehat-sehat saja! 
Namun, aku bisa melihat sesuatu.]]
  },
  AvgDialog_18900_Content_17 = {
    Text = "Oh? Apa yang bisa kamu lihat?"
  },
  AvgDialog_18900_Content_18 = {
    Text = [[
Sama seperti Aigis, saya juga melihat fatamorgana hitam. 
Bisakah kamu membantu saya?]]
  },
  AvgDialog_18900_Content_19 = {
    Text = "Menarik. Kalau begitu, hari ini kamu yang bertugas."
  },
  AvgDialog_18900_Content_2 = {
    Text = "Pada awalnya, orang-orang itu mengatakan bahwa mereka datang untuk menyembuhkan penyakit."
  },
  AvgDialog_18900_Content_20 = {Text = "Tiyug…"},
  AvgDialog_18900_Content_21 = {
    Text = "Jangan takut, Aigis."
  },
  AvgDialog_18900_Content_22 = {
    Text = "Saya akan segera kembali."
  },
  AvgDialog_18900_Content_23 = {
    Text = "Setelah itu, Tiyoug tidak pernah kembali ke panti asuhan lagi."
  },
  AvgDialog_18900_Content_24 = {
    Text = "Mereka memberi tahu Nona Sarah bahwa kondisinya parah, tetapi ada seorang tuan yang baik hati bersedia mengadopsinya dan membayar seluruh biaya operasi."
  },
  AvgDialog_18900_Content_25 = {
    Text = "Saya tahu, itu semua adalah kebohongan, tapi Nona Sarah mempercayainya dengan penuh rasa syukur."
  },
  AvgDialog_18900_Content_26 = {
    Text = "Kenapa, kenapa bisa begini…"
  },
  AvgDialog_18900_Content_27 = {
    Text = "Saya berjalan dengan pikiran melayang di koridor dan menabrak sosok tinggi."
  },
  AvgDialog_18900_Content_28 = {
    Text = "Adik kecil, bisa tanya cara menuju area medis baru?"
  },
  AvgDialog_18900_Content_29 = {
    Text = [[
Sejak jumlah pasien semakin banyak, Nona Sarah memindahkan area perawatan ke gedung kecil di timur panti jompo. 
Tempat itu luas, sehingga bisa menampung lebih banyak tempat tidur sementara.]]
  },
  AvgDialog_18900_Content_3 = {
    Text = "Entah sejak kapan, sebuah penyakit aneh mulai menyebar di panti asuhan. Orang-orang yang terkena penyakit itu menjadi sangat pemarah, dan tanda-tanda segitiga hitam mulai muncul di kepala, tangan, serta kaki mereka."
  },
  AvgDialog_18900_Content_30 = {
    Text = [[
Kakak, bisakah kamu tidak pergi ke area medis?
Di sana sangat berbahaya...]]
  },
  AvgDialog_18900_Content_31 = {
    Text = "Anak baik, mengapa kamu mengatakan hal seperti itu?"
  },
  AvgDialog_18900_Content_32 = {
    Text = [[
Saya tidak tahu, saya tidak tahu, maafkan saya... 
Area medis berada di timur.]]
  },
  AvgDialog_18900_Content_33 = {
    Text = [[
Terima kasih. 
 Kamu tampaknya memiliki banyak kekhawatiran. Jika ingin berbicara, jangan ragu untuk datang menemui saya.]]
  },
  AvgDialog_18900_Content_34 = {
    Text = "Saya memiliki seorang adik perempuan, usianya hampir sama denganmu…"
  },
  AvgDialog_18900_Content_35 = {
    Text = "Wanita itu berjalan ke timur, dengan pita merah mencolok yang bergoyang lembut mengikuti langkah kakinya."
  },
  AvgDialog_18900_Content_36 = {
    Text = "Itu adalah terakhir kalinya aku melihat kakak perempuan Jenkin. Setelah hari itu, dia menghilang."
  },
  AvgDialog_18900_Content_37 = {
    Text = "Aku tahu, orang-orang melihat segalanya melalui mataku."
  },
  AvgDialog_18900_Content_38 = {
    Text = "Saya hati-hati menutupi mata saya dengan penutup mata."
  },
  AvgDialog_18900_Content_39 = {
    Text = "Namun, ini tidak bisa menghentikan kedatangan mimpi buruk."
  },
  AvgDialog_18900_Content_4 = {
    Text = "Miss Sarah membawa mereka ke klinik Dokter, tetapi bekas luka di tubuh orang yang kembali tidak berkurang, melainkan semakin banyak…"
  },
  AvgDialog_18900_Content_40 = {
    Text = "Hmm... di sini adalah..."
  },
  AvgDialog_18900_Content_41 = {
    Text = "Cahaya yang sangat terang membuatku tanpa sadar ingin menutup mata. Aku mencoba untuk berkedip, tetapi ternyata aku tidak bisa melakukannya."
  },
  AvgDialog_18900_Content_42 = {
    Text = "Ada sesuatu yang mengunci pandanganku."
  },
  AvgDialog_18900_Content_43 = {
    Text = "Seorang pria berpakaian putih, memegang sebilah pisau tipis, muncul dalam pandangan dan perlahan mendekatiku."
  },
  AvgDialog_18900_Content_44 = {
    Text = "Tidak, jangan, Nona Sarah, Nona Sarah!"
  },
  AvgDialog_18900_Content_45 = {
    Text = "Nyonya Sarah! Tiuyug! Tolong! Selamatkan aku! <Big:Selamatkan aku!>"
  },
  AvgDialog_18900_Content_46 = {
    Text = "Ujung pisaunya semakin dekat, semakin dekat, hingga memenuhi seluruh pandangan.\nLalu——"
  },
  AvgDialog_18900_Content_47 = {
    Text = "<Shake: Ah————!>"
  },
  AvgDialog_18900_Content_48 = {
    Text = [[
Sungguh gelap, sungguh dingin, seperti berendam semalaman di Sungai Isis pada bulan Desember. 
 Aku ingin bangkit, tapi seluruh tubuhku mati rasa, sama sekali tidak bisa bergerak.]]
  },
  AvgDialog_18900_Content_49 = {
    Text = "Sakit sekali... mata terasa sangat tidak nyaman..."
  },
  AvgDialog_18900_Content_5 = {
    Text = "Aku memberi tahu Miss Sarah tentang hal ini, tetapi Miss Sarah berkata…"
  },
  AvgDialog_18900_Content_50 = {
    Text = [[
Dokter memasukkan sesuatu ke dalam mataku, lalu, lalu, aku melihat warna. 
Warna-warna yang bercampur seperti palet cat yang tumpah oleh Xiao Mai.]]
  },
  AvgDialog_18900_Content_51 = {
    Text = "Nona Sarah... Tiyoug... Aku sangat kesakitan... Sangat tidak nyaman..."
  },
  AvgDialog_18900_Content_52 = {
    Text = "Mereka bergerak… warnanya bergerak! Seperti cacing yang merayap masuk ke mataku. Selain warna-warna itu, aku tidak bisa melihat apa pun lagi."
  },
  AvgDialog_18900_Content_53 = {
    Text = "Aku salah, aku seharusnya tidak meminta bantuan orang lain…"
  },
  AvgDialog_18900_Content_54 = {
    Text = "Warna pasti memenuhi pikiranku, dan aku merasa seolah-olah aku akan segera berhenti menjadi diriku sendiri…"
  },
  AvgDialog_18900_Content_55 = {
    Text = "Tolong... tolong aku...."
  },
  AvgDialog_18900_Content_56 = {
    Text = "Saat saya hampir pingsan, mereka memasukkan sesuatu ke mata saya lagi, dan warnanya tertutup oleh cahaya perak."
  },
  AvgDialog_18900_Content_57 = {
    Text = "Dingin sekali, meskipun masih terasa sakit, tiba-tiba saja aku merasa seperti kembali menjadi diriku sendiri."
  },
  AvgDialog_18900_Content_58 = {
    Text = "Jangan takut, aku akan membantu kamu."
  },
  AvgDialog_18900_Content_59 = {
    Text = "Kamu... siapa...?"
  },
  AvgDialog_18900_Content_6 = {
    Text = [[
Aigis, fatamorganamu semakin parah. 
Di sini sama sekali tidak ada jejak hitam.]]
  },
  AvgDialog_18900_Content_61 = {
    Text = [[
Ini tidak penting, Nak. 
 Ayo, ikuti iramaku, kita bersama-sama melawan kontrol <Yellow:benda asing>.]]
  },
  AvgDialog_18900_Content_62 = {
    Text = "Dengan bantuan suara, selain rasa sakit, saya merasa lebih tenang dan mulai bisa berpikir."
  },
  AvgDialog_18900_Content_63 = {
    Text = "Entah sudah berapa lama, begitu lama hingga kulit mulai terasa mati rasa, akhirnya aku mendengar suara Dokter lagi."
  },
  AvgDialog_18900_Content_64 = {
    Text = [[
Bisa melihat mata @2, itu adalah bahan terbaik yang pernah ada.
Kalau bukan karena anak ini selalu menghalangi, sudah sejak lama harus digunakan untuk eksperimen.]]
  },
  AvgDialog_18900_Content_65 = {
    Text = "Tidak terlambat sekarang, Dokter. Akhirnya, kita berhasil menyelesaikan implantasi Perak! Ini patut dirayakan!"
  },
  AvgDialog_18900_Content_66 = {
    Text = "Fusi kesadaran dan reseptor @4 sangat berhasil, efek petrifikasi sedikit menyimpang, tetapi selama kesadaran reseptor terus melemah…"
  },
  AvgDialog_18900_Content_67 = {
    Text = "Ini semua berkat <Yellow:Penyelidik> bodoh itu yang datang sendiri kepada kita, memberikan Perak berkualitas tinggi ini, sehingga mengurangi reaksi penolakan."
  },
  AvgDialog_18900_Content_68 = {
    Text = "Para peneliti itu mengelilingi saya, berbicara dengan penuh semangat tentang sesuatu. Reseptor? Penolakan? Penyelidik? Apa itu semua?"
  },
  AvgDialog_18900_Content_69 = {
    Text = "Bagaimana, anak muda? Cobalah sebentar saja, dengan satu pandangan, sahabat terbaikmu akan menemanimu dalam wujud favoritmu, lho."
  },
  AvgDialog_18900_Content_7 = {
    Text = "Tidak, Nona Sarah, aku benar-benar bisa melihatnya!"
  },
  AvgDialog_18900_Content_70 = {
    Text = "Mereka menyetel perangkat untuk memperkuat fiksasi mata, sehingga setiap kali ingin berkedip, kait akan menusuk kelopak mata."
  },
  AvgDialog_18900_Content_71 = {
    Text = "Mereka mendorong sebuah kursi ke hadapan saya. \nDiikat pada kursi itu adalah sahabat terbaik saya——"
  },
  AvgDialog_18900_Content_72 = {
    Text = "Ti... Tiyoug...?"
  },
  AvgDialog_18900_Content_73 = {
    Text = "Tiyug terbangun karena terkejut, dengan heran mengangkat kepalanya, lalu melihat sekeliling."
  },
  AvgDialog_18900_Content_74 = {
    Text = "Aigis! Kalian melepaskanku, lepaskan dia!"
  },
  AvgDialog_18900_Content_75 = {
    Text = "Jangan bergerak, jangan bergerak! Tiyouge, jangan melihatku!!"
  },
  AvgDialog_18900_Content_76 = {
    Text = [[
Tiyug menangis dan berjuang, namun sia-sia. 
Gerakannya perlahan menjadi kaku, seperti jarum jam yang tak bisa bergerak lagi, lalu pelan-pelan berhenti.]]
  },
  AvgDialog_18900_Content_77 = {
    Text = "Seolah menerima takdir, dia diam-diam menatapku, bertemu pandang denganku, lalu ——"
  },
  AvgDialog_18900_Content_78 = {
    Text = "Dia mulai memudar, menjadi kusam seperti gaun lama yang sudah dicuci berkali-kali oleh Miss Sarah. Sirup keluar dari kulitnya, menutupi Tubuhnya yang menjadi seperti batu."
  },
  AvgDialog_18900_Content_79 = {
    Text = "Dalam pandangan <Yellow:Murid> saya, ia, atau dia, menghembuskan napas terakhirnya."
  },
  AvgDialog_18900_Content_8 = {
    Text = [[
Itu benar-benar hanya fatamorgana. Tidak percaya? Tanyakan saja pada Xiao Mai?
Dia baru berusia lima tahun, anak sekecil itu pasti tidak akan berbohong, kan?]]
  },
  AvgDialog_18900_Content_80 = {
    Text = "Ai... Jisi..."
  },
  AvgDialog_18900_Content_81 = {
    Text = "<Big:Tiyoug——!>"
  },
  AvgDialog_18900_Content_9 = {
    Text = [[
Kak Aigis, jika sakit harus mendengarkan dokter ya. 
 Terakhir kali aku demam, kamu juga berkata seperti ini padaku, kan?]]
  },
  AvgDialog_18901_Content_1 = {
    Text = "Rahasia kita"
  },
  AvgDialog_18901_Content_10 = {
    Text = "Urutan tim adalah: Jenkin, Ramona, dan kamu."
  },
  AvgDialog_18901_Content_11 = {
    Text = "Di belakangmu, Cokelat berderit dan menutup pintu kayu."
  },
  AvgDialog_18901_Content_13 = {
    Text = "Kakakku, dan murid yang kalian cari, pasti berada di bawah sini, bersama hantu panti asuhan itu."
  },
  AvgDialog_18901_Content_14 = {
    Text = "Korek api, korek api…"
  },
  AvgDialog_18901_Content_15 = {
    Text = "Ngomong-ngomong, apakah kalian merasa gatal-gatal di tubuh?"
  },
  AvgDialog_18901_Content_16 = {
    Text = "Setelah dia mengingatkan, kalian baru menyadari, ya, ada semacam rasa gatal yang tak terdefinisikan di permukaan tubuh, dari ujung kaki hingga pergelangan kaki, dan terus menjalar ke punggung…"
  },
  AvgDialog_18901_Content_17 = {
    Text = "Jenkin akhirnya menyalakan lampu lentera, dia dengan cekatan menurunkan tinggi lentera, menerangi sebagian kecil area di tanah."
  },
  AvgDialog_18901_Content_18 = {
    Text = "Juga pada saat itu——"
  },
  AvgDialog_18901_Content_19 = {
    Text = "Retina mengalami benturan."
  },
  AvgDialog_18901_Content_2 = {
    Text = "Setelah keributan semalaman, langit sudah mulai terang."
  },
  AvgDialog_18901_Content_20 = {
    Text = "Semut-semut yang tak terhitung jumlahnya berkumpul menjadi gerombolan semut yang rapat, terus-menerus bergerak dengan gelisah tanpa henti."
  },
  AvgDialog_18901_Content_21 = {
    Text = "Mereka bergerak, berkumpul, berputar-putar, lalu mengalir ke dalam Jurang yang gelap gulita."
  },
  AvgDialog_18901_Content_3 = {
    Text = [[
Ogier tetap di kamar untuk berjaga-jaga, menahan Sarah. 
 Kamu dan Ramona mengikuti Jenkin hingga sampai di depan basement tempat "Hantu Workhouse" berada.]]
  },
  AvgDialog_18901_Content_4 = {
    Text = [[
Kecilkan suara, jangan sampai Sarah menemukan kita. 
Dia akan membawa sekelompok pekerja untuk mengusir kita.]]
  },
  AvgDialog_18901_Content_5 = {
    Text = [[
Ogier sedang memantau tindakan Sarah, dengan dia di sini, kita tidak akan terdeteksi. 
 Ceritakan lagi, apa yang kamu temukan di kantor Sarah terakhir kali.]]
  },
  AvgDialog_18901_Content_6 = {
    Text = "Aduh, berapa kali lagi aku harus mengatakannya."
  },
  AvgDialog_18901_Content_7 = {
    Text = "Wanita busuk itu menjual orang-orang dari panti asuhan kepada Dokter jahat untuk dijadikan percobaan, dan dia menghasilkan banyak uang! Dia membeli banyak perhiasan emas dan perak dan menyembunyikannya di laci kamarnya."
  },
  AvgDialog_18901_Content_8 = {
    Text = "Kalian sudah melihat kartu pelajar teman kalian, apa lagi yang perlu ditanyakan?"
  },
  AvgDialog_18901_Content_9 = {
    Text = [[
Baiklah, tepat di ruangan ini. 
Yang terakhir masuk, tutup pintu.]]
  },
  AvgDialog_18902_Content_1 = {
    Text = "Seni yang manis"
  },
  AvgDialog_18902_Content_10 = {
    Text = "Kedatangan kalian tampaknya sama sekali tidak memengaruhi pekerjaannya. Dia menundukkan kepala, memandangi Patung itu, mengganti posisi pahat, lalu melanjutkan pemahatannya."
  },
  AvgDialog_18902_Content_11 = {
    Text = [[
Itu adalah hantu dari workhouse... 
 Di mana kakakku? Apakah kau yang menyembunyikannya!]]
  },
  AvgDialog_18902_Content_12 = {
    Text = "Hantu melirik kalian sekilas, tanpa menjawab."
  },
  AvgDialog_18902_Content_13 = {
    Text = "Ramona mengeluarkan senjata, bertukar pandang denganmu, lalu melangkah maju."
  },
  AvgDialog_18902_Content_14 = {
    Text = "Harap bersabar, jangan mengganggu proses berpikir seni..."
  },
  AvgDialog_18902_Content_15 = {
    Text = "Begitu suaranya terdengar, tak terhitung banyaknya monster meneriakkan suara sambil meloncat keluar dari bayangan di ruang bawah tanah, berlarian melewati tubuh-tubuh yang bergerak dan menyerang kalian."
  },
  AvgDialog_18902_Content_2 = {
    Text = "Akhirnya, kalian berhasil membuka pintu besi di ruang bawah tanah. Aroma manis dan pekat sirup langsung menusuk hidung."
  },
  AvgDialog_18902_Content_3 = {
    Text = "Lebih menghentak lagi adalah pemandangan mengerikan di dalam ruang bawah tanah: beberapa tubuh tergeletak tak beraturan di lantai, dengan permukaannya dilapisi sirup."
  },
  AvgDialog_18902_Content_4 = {
    Text = "Tubuh yang telah kehilangan bentuk manusia bergerak dengan cara yang mengerikan, meninggalkan jejak sirup yang kacau di belakangnya."
  },
  AvgDialog_18902_Content_5 = {
    Text = "Kerumunan semut yang padat merayap di sekitar sirup, serakah menyeruputnya sambil menyentuhkan antena mereka saat membawa beban, seolah-olah mereka menemukan harta karun paling berharga di dunia ini."
  },
  AvgDialog_18902_Content_6 = {
    Text = "Namun, yang paling menarik perhatian bukanlah ini."
  },
  AvgDialog_18902_Content_7 = {
    Text = "Di dalam ruang bawah tanah, terdapat beberapa patung berwarna cokelat kemerahan yang bersinar. Masing-masing memiliki sikap anggun dan sorot mata lelah. Meski hanya sekilas pandang, rasa sakral itu langsung terasa menggetarkan."
  },
  AvgDialog_18902_Content_8 = {
    Text = "Di antara patung-patung itu, duduklah hantu dari rumah sakit kemiskinan."
  },
  AvgDialog_18902_Content_9 = {
    Text = "Itu jelas hantu dari panti asuhan — tubuhnya berwarna seperti batu, dengan ringan memegang sebuah pahat di tangannya, mengukir satu per satu garis pada wajah patung yang ekspresinya penuh ketakutan, menghasilkan suara gesekan yang mengerikan."
  },
  AvgDialog_18903_Content_1 = {
    Text = "Bahaya laten"
  },
  AvgDialog_18903_Content_2 = {Text = "Gong, gong"},
  AvgDialog_18903_Content_3 = {
    Text = "Kamu sangat menyadari bahwa dirimu sedang bermimpi."
  },
  AvgDialog_18903_Content_4 = {
    Text = "Seseorang berjalan mendekat dengan melangkah di atas pipa besi di dalam saluran pembuangan."
  },
  AvgDialog_18903_Content_5 = {
    Text = [[
Dalam kabut, ada sebuah sosok yang dikenal berlari mendekat.
Dia menggenggam tanganmu dan menarikmu berlari dengan cepat, sambil terus berteriak cemas.]]
  },
  AvgDialog_18903_Content_6 = {
    Text = "Lari, cepat lari, Jenkin, cepat!"
  },
  AvgDialog_18903_Content_7 = {
    Text = "Di belakang kalian, banyak monster hitam kental mengejar kamu dan kakakmu."
  },
  AvgDialog_18904_Content_1 = {Text = "%player%!"},
  AvgDialog_18904_Content_10 = {
    Text = "Nona Sarah, aku sangat takut, tolong..."
  },
  AvgDialog_18904_Content_11 = {
    Text = "Nyonya Sarah…"
  },
  AvgDialog_18904_Content_12 = {
    Text = "Ada apa, Aigis?"
  },
  AvgDialog_18904_Content_13 = {
    Text = [[
Nona Sarah, bisakah kamu menyanyikan lagu itu sekali lagi, hanya sekali? 
 Maksudku, jika itu tidak merepotkanmu...]]
  },
  AvgDialog_18904_Content_14 = {
    Text = "Dear Aigis, dengarkan baik-baik. Kamu adalah anak yang paling penurut, paling patuh, dan paling pengertian di seluruh panti asuhan. Kamu adalah teman kecil yang paling disukai semua orang."
  },
  AvgDialog_18904_Content_15 = {
    Text = "Jadi, jangan terlalu tegang, sesekali bersikap seenaknya juga tidak apa-apa, lho. Mengerti?"
  },
  AvgDialog_18904_Content_16 = {
    Text = "Itu... aku, aku ingin mendengar Sarah menyanyikan lagu anak-anak lagi."
  },
  AvgDialog_18904_Content_17 = {
    Text = "Tidak masalah. \n<Italic: Om Charlie memiliki seekor kucing tabby yang sangat dia cintai…>"
  },
  AvgDialog_18904_Content_18 = {
    Text = "Kamu tiba-tiba membuka mata lebar-lebar dan terjatuh ke dalam dunia nyata yang penuh warna."
  },
  AvgDialog_18904_Content_19 = {
    Text = "%player%, apakah kamu baik-baik saja?"
  },
  AvgDialog_18904_Content_2 = {
    Text = "Saat Ramona menahan Sarah di kejauhan, kamu dengan cepat berkonsentrasi dan menenggelamkan diri ke dalam ruang hitam pekat yang mulai terasa semakin familiar."
  },
  AvgDialog_18904_Content_20 = {
    Text = [[
Kamu menahan rasa pusing dan mengangguk. Pada saat itu, pandanganmu sekilas menangkap sosok berwarna putih. 
 Gadis itu entah sejak kapan telah melewati kalian dan masuk ke medan perang yang porak-poranda.]]
  },
  AvgDialog_18904_Content_21 = {
    Text = "Aigis, cepat kembali! Di sana berbahaya!"
  },
  AvgDialog_18904_Content_22 = {
    Text = [[
Aigis terpaku memandang Sarah yang terbaring tak bergerak. 
 Di samping luka ledakan, cairan kental masih mengalir deras, membentuk aliran kecil berwarna hitam.]]
  },
  AvgDialog_18904_Content_23 = {
    Text = [[
Lalu, dia melangkah ke kolam air hitam pekat dan duduk di tengah-tengah cairan kental itu. 
 Gadis itu membaringkan Sarah di pangkuannya, lalu dengan gerakan yang sudah terbiasa menepuk punggung Sarah.]]
  },
  AvgDialog_18904_Content_24 = {
    Text = "Seperti yang pernah dilakukan oleh direktur ketika menenangkan dan membuatku tertidur."
  },
  AvgDialog_18904_Content_25 = {
    Text = "Nyonya Sarah... Tidak apa-apa, tidak apa-apa... Hanya mimpi buruk..."
  },
  AvgDialog_18904_Content_26 = {
    Text = "Kilauan lemah yang bergerak di sekitar kelopak mata menembus penutup mata, lenyap dalam sekejap. Jika tidak disertai dengan gelombang kuat dari Gnosis, hampir saja kau mengira itu hanya kesedihan gadis itu yang belum terungkap."
  },
  AvgDialog_18904_Content_27 = {
    Text = "Serpihan di kepala dan wajah Sarah awalnya bergetar dengan gelisah, tetapi setelah cahaya samar melintas, dia tidak bergerak lagi, seolah-olah benar-benar jatuh ke dalam tidur yang lelap."
  },
  AvgDialog_18904_Content_28 = {
    Text = "Nyonya Sarah sudah sangat lama tidak tidur dengan nyenyak."
  },
  AvgDialog_18904_Content_29 = {
    Text = "Agar panti asuhan tidak dibubarkan, dia selalu berlari ke sana kemari untuk menemui para tuan dan nyonya kaya yang tinggal di istana. Dia bahkan tidak punya waktu untuk makan atau beristirahat."
  },
  AvgDialog_18904_Content_3 = {
    Text = "Kunci perak bergetar dengan hebat, kegelapan di depan matamu berubah beberapa kali, dan perlahan cahaya mulai muncul dari tepi pandanganmu."
  },
  AvgDialog_18904_Content_30 = {
    Text = "Pada malam hari, setelah kembali ke kantor, dia menyalakan lilin dan terus menghitung, memeriksa apakah uang yang didapat dari Tuan cukup untuk digunakan."
  },
  AvgDialog_18904_Content_31 = {
    Text = "Lihat berapa banyak uang yang bisa didapat dari menjual perhiasan yang diperoleh dari para nyonya dan nona."
  },
  AvgDialog_18904_Content_32 = {
    Text = [[
Mereka semua menertawakannya dan mengatakan hal-hal yang menyakitkan, tetapi Nona Sarah tidak pernah marah. 
Dia malah menghibur saya dan bernyanyi untuk kami.]]
  },
  AvgDialog_18904_Content_33 = {
    Text = "Dia sangat baik kepada kami, sungguh. Dia juga sangat baik padaku, bahkan lebih baik lagi."
  },
  AvgDialog_18904_Content_34 = {
    Text = "Saya adalah beban bagi Ibu, dan Ibu membuang saya. Tuan Direktur sebelumnya menolak untuk menerima saya, tetapi Nona Sarah mengatakan bahwa dia bersedia bekerja dua kali lipat demi membawa saya masuk."
  },
  AvgDialog_18904_Content_35 = {
    Text = "Sejak saat itu, aku bersumpah untuk tidak menjadi beban bagi Nona Sarah dan harus menjadi anak yang berguna."
  },
  AvgDialog_18904_Content_36 = {
    Text = "Maafkan saya, Nona Sarah. Saya sudah berusaha sangat keras, tapi semuanya… terus berjalan ke arah yang buruk. Saya tidak bisa melindungi semua orang, tidak bisa melindungi Anda. Maafkan saya."
  },
  AvgDialog_18904_Content_37 = {
    Text = "Aigis dengan lembut menyentuh pipi Sarah yang sudah tidak berwujud manusia lagi, lalu berbalik ke arah kalian."
  },
  AvgDialog_18904_Content_38 = {
    Text = "Bukankah kalian sedang mencari penyelidik <Blue:Sean Anderson>?"
  },
  AvgDialog_18904_Content_39 = {
    Text = "Aigis, kamu…"
  },
  AvgDialog_18904_Content_4 = {
    Text = "Kak Sasa, perutku sangat lapar."
  },
  AvgDialog_18904_Content_40 = {
    Text = "Gadis itu menyeringai, memperlihatkan ekspresi yang hanya bisa disebut sebagai senyuman dengan susah payah."
  },
  AvgDialog_18904_Content_41 = {
    Text = [[
Lepaskan Nyonya Sarah. 
Aku akan memberitahu kalian tentang keberadaannya.]]
  },
  AvgDialog_18904_Content_42 = {
    Text = "Dia ada di sini."
  },
  AvgDialog_18904_Content_43 = {
    Text = "Aigis perlahan melepas penutup matanya, memperlihatkan murid berwarna pucat seperti batu."
  },
  AvgDialog_18904_Content_44 = {
    Text = "<Red: Di mata saya.>"
  },
  AvgDialog_18904_Content_5 = {
    Text = "Sayang sekali, Nona Sarah, kami tidak dapat melanjutkan dukungan kepada kalian lagi."
  },
  AvgDialog_18904_Content_6 = {
    Text = "Nona Sarah, kenapa ibu tidak mau saya lagi?"
  },
  AvgDialog_18904_Content_7 = {
    Text = "Bayangan hitam dan putih berkelebat bergantian, seakan-akan beberapa film diputar secara bersamaan di satu layar. Tak peduli seberapa keras kamu berusaha, kamu tetap tidak bisa melihat dengan jelas isi di dalamnya."
  },
  AvgDialog_18904_Content_8 = {
    Text = "Nona Sarah, Ibu pernah berkata bahwa aku hanyalah sampah... Apakah hal-hal ini benar-benar bisa diserahkan kepadaku?"
  },
  AvgDialog_18904_Content_9 = {
    Text = "Nona Sarah, Ibu sudah tidak menginginkan saya lagi, kau... apakah kau juga akan meninggalkan saya...?"
  },
  AvgDialog_18905_Content_1 = {
    Text = "Beban Hati Nurani"
  },
  AvgDialog_18905_Content_10 = {
    Text = "Jangan berpura-pura bodoh, kami tahu semua tentang rencana jahatmu dengan Dokter Busuk itu! Kembalikan kakak perempuanku!"
  },
  AvgDialog_18905_Content_11 = {
    Text = "Aku benar-benar tidak punya, semua ini di sini…"
  },
  AvgDialog_18905_Content_12 = {
    Text = "Sarah melihat sekeliling pada makhluk yang tidak yakin dapat disebut manusia, dan terus berbicara dengan terputus-putus."
  },
  AvgDialog_18905_Content_13 = {
    Text = "Saya benar-benar tidak tahu!"
  },
  AvgDialog_18905_Content_14 = {
    Text = "Kami melihat buku besarmu!"
  },
  AvgDialog_18905_Content_15 = {Text = "...?"},
  AvgDialog_18905_Content_16 = {
    Text = "Kamu mengambil buku catatan yang tergeletak di samping, membukanya, lalu memberi isyarat kepada Sarah."
  },
  AvgDialog_18905_Content_17 = {
    Text = "Mick, laki-laki, 5 tahun, 10 Taring; Diana, perempuan, 23 tahun, 5 Taring; Aigis… perempuan, 8 tahun, 40 Taring."
  },
  AvgDialog_18905_Content_18 = {
    Text = "…Haruskah aku melanjutkan?"
  },
  AvgDialog_18905_Content_19 = {
    Text = "Bukan, bukan seperti yang kamu pikirkan, aku—"
  },
  AvgDialog_18905_Content_2 = {
    Text = "Langkah kaki yang terburu-buru terdengar, Sarah muncul dengan wajah penuh kemarahan, diikuti oleh Aigis yang tampak khawatir, dan Ogier yang berwajah teguh."
  },
  AvgDialog_18905_Content_20 = {
    Text = "Jangan berkilah! Kau memang menjadikan orang-orang di panti jompo sebagai kelinci percobaan si Dokter Gila itu, lalu menukar uang untuk membeli permata dan perhiasanmu!"
  },
  AvgDialog_18905_Content_21 = {
    Text = "Aigis, kamu sudah mengalami Sembuh, kamu juga tahu, uang ini jelas-jelas adalah——"
  },
  AvgDialog_18905_Content_22 = {
    Text = "Ya… itu adalah subsidi nutrisi dari laboratorium untuk mereka yang menjalani sembuh, 5 Taring per orang setiap kali, sudah disepakati."
  },
  AvgDialog_18905_Content_23 = {
    Text = "Uang ini, Nonna Sarah gunakan semuanya untuk membeli makanan bagi semua orang."
  },
  AvgDialog_18905_Content_24 = {
    Text = "Uang itu tidak ada sepeser pun yang kutinggalkan! Adapun soal perhiasan yang disebutkan oleh anak liar itu, itu omong kosong belaka. Tolong percayai saya, {Male=tuan,Female=nona} Ash!"
  },
  AvgDialog_18905_Content_25 = {
    Text = "Jangan berkilah!"
  },
  AvgDialog_18905_Content_26 = {
    Text = "Jenkin mengeluarkan dua cincin perak dari dalam tas selempangnya."
  },
  AvgDialog_18905_Content_27 = {
    Text = "Jika bukan kamu, dari mana munculnya dua benda kecil di laci kanan meja kantor ini? Apakah mereka muncul begitu saja dari udara?"
  },
  AvgDialog_18905_Content_28 = {
    Text = "Lalu bagaimana bisa ada padamu? Kembalikan itu padaku, itu Hadiah dari penyandang dana lainnya!"
  },
  AvgDialog_18905_Content_29 = {
    Text = "Percayalah padaku, aku menganggapnya sebagai barang darurat untuk membantu rumah panti asuhan miskin! Bagaimana mungkin, bagaimana mungkin aku bisa memberikan kerusakan pada anak-anak di sini karena hal-hal ini?"
  },
  AvgDialog_18905_Content_3 = {
    Text = "Bagaimana kalian bisa——"
  },
  AvgDialog_18905_Content_30 = {
    Text = "Jika Anda tidak terkait dengan masalah ini, bagaimana Anda bisa menjelaskan anak-anak ini…?"
  },
  AvgDialog_18905_Content_31 = {
    Text = "Ramona menunjuk monster yang merayap di tanah."
  },
  AvgDialog_18905_Content_32 = {
    Text = [[
...Anak?
Apa yang kamu maksud...]]
  },
  AvgDialog_18905_Content_33 = {
    Text = "Sarah tampaknya baru menyadari sesuatu, lalu dengan kaku memutar kepalanya untuk lebih teliti melihat penampakan monster-monster itu."
  },
  AvgDialog_18905_Content_34 = {
    Text = "Ini adalah para pekerja dan anak-anak yang hilang dari workhouse, bukan?"
  },
  AvgDialog_18905_Content_35 = {
    Text = "Tidak, tidak akan..."
  },
  AvgDialog_18905_Content_36 = {
    Text = "Benar-benar berisik."
  },
  AvgDialog_18905_Content_37 = {
    Text = [[
Jangan perhatikan yang belum selesai. 
Tunduklah pada keindahan sejati.]]
  },
  AvgDialog_18905_Content_38 = {
    Text = "Dia mendorong patung yang baru selesai ke arah Sarah."
  },
  AvgDialog_18905_Content_39 = {
    Text = "Itu adalah patung seorang anak kecil, dengan kerangka gula yang keruh, wajahnya tampak sangat hidup."
  },
  AvgDialog_18905_Content_4 = {
    Text = "Ya————"
  },
  AvgDialog_18905_Content_40 = {
    Text = "Itu... itu... Xiao... Wei Li..."
  },
  AvgDialog_18905_Content_41 = {
    Text = "Mata patung tiba-tiba bergetar."
  },
  AvgDialog_18905_Content_42 = {
    Text = "Yi——Yi——<Shake:Ah——>"
  },
  AvgDialog_18905_Content_43 = {
    Text = "Sarah mengeluarkan teriakan yang mengerikan."
  },
  AvgDialog_18905_Content_44 = {
    Text = "Dia meringkuk, kedua tangannya memeluk tubuhnya, bisikan sedihnya perlahan menjadi serak dan kacau, sulit dibedakan."
  },
  AvgDialog_18905_Content_45 = {
    Text = "<Small:Saya tidak berguna, saya tidak mampu. Saya bukan kepala sekolah yang baik. Saya tidak bisa melindungi semua orang, tidak bisa melindungi anak-anak…>"
  },
  AvgDialog_18905_Content_46 = {
    Text = "Nyonya Sarah, jangan seperti ini... kami, semua orang sudah mengerti. Kamu sudah berusaha semampumu."
  },
  AvgDialog_18905_Content_47 = {
    Text = "Maaf, Aigis; maaf, Lucy; maaf, Jenkin, Henry, Diana…"
  },
  AvgDialog_18905_Content_48 = {
    Text = "Sarah mengangkat kepalanya, memperlihatkan wajah yang sepenuhnya kehilangan kendali. Bola matanya dan sudut bibirnya seolah-olah menari dengan gerakan yang terkoordinasi, membentuk postur yang mustahil ditampilkan oleh manusia."
  },
  AvgDialog_18905_Content_49 = {
    Text = "Nona Sarah...?"
  },
  AvgDialog_18905_Content_5 = {
    Text = "Dia tidak bisa menyelesaikan kalimat itu, lalu menatap boneka gula yang terdistorsi di tanah dan mengeluarkan jeritan mengerikan."
  },
  AvgDialog_18905_Content_50 = {
    Text = [[
Sekelilingnya seolah-olah tenggelam ke dasar air, tiba-tiba terperangkap dalam kesunyian dingin yang mencekam.
Tekanan tak terlihat datang secara mendadak, kamu menarik napas dalam-dalam dan menyadari bahwa ada sesuatu yang tidak beres.]]
  },
  AvgDialog_18905_Content_51 = {
    Text = "Astaga, Ramona, cepat suruh yang lain pergi!"
  },
  AvgDialog_18905_Content_52 = {
    Text = [[
Tidak ada waktu lagi. 
 Kepala direktur muda itu terbelah seperti bunga, dan cairan hitam menyembur ke tanah.]]
  },
  AvgDialog_18905_Content_53 = {
    Text = "Sarah, Nyonya Sarah!"
  },
  AvgDialog_18905_Content_54 = {
    Text = "Dia mengeluarkan suara tinggi dan tajam, anggota tubuh yang terdistorsi di sekitarnya meresponsnya dengan suara seperti lolongan serigala, dengan cepat berubah menjadi monster yang terinfeksi oleh Pelarutan."
  },
  AvgDialog_18905_Content_6 = {
    Text = [[
Bagaimana mungkin kita bisa? Kalimat itu seharusnya kuberikan padamu. 
Bukankah kamu hantu workhouse yang bersembunyi di basement? Dia sudah memberitahu kami semuanya.]]
  },
  AvgDialog_18905_Content_7 = {
    Text = "Seperti tertarik oleh teriakan Sarah, sosok setengah terkaramelisasi yang merayap di tanah bergerak mendekati arahnya."
  },
  AvgDialog_18905_Content_8 = {
    Text = "Dengar, Nona Sarah, apa yang telah kamu lakukan tidak bisa lagi tersembunyi."
  },
  AvgDialog_18905_Content_9 = {
    Text = "Silakan segera berikan informasi kontak kerja sama antara rumah sakit umum dan asosiasi para pematung, serta keberadaan penyelidik <Blue:Sean Anderson>."
  },
  AvgDialog_18906_Content_1 = {
    Text = "Jangan menilai seseorang dari penampilannya"
  },
  AvgDialog_18906_Content_10 = {Text = "Anu..."},
  AvgDialog_18906_Content_11 = {
    Text = "Sudah kubilang, hari ini tutup, aku harus masuk ke dalam untuk mencari kakak."
  },
  AvgDialog_18906_Content_12 = {
    Text = "Anak itu terlihat malas, bahkan tidak mengangkat matanya untuk melihatnya."
  },
  AvgDialog_18906_Content_13 = {
    Text = [[
Bukan, aku ingin bertanya... 
 Apakah kamu tahu jalan ke Panti Asuhan Lily?]]
  },
  AvgDialog_18906_Content_15 = {
    Text = "<Small: Dari mana datangnya domba gemuk ini…>"
  },
  AvgDialog_18906_Content_16 = {Text = "...?"},
  AvgDialog_18906_Content_17 = {
    Text = "Maaf, aku baru saja melamun dan tidak mendengarnya dengan jelas. Bisa kamu ulangi lagi?"
  },
  AvgDialog_18906_Content_18 = {
    Text = "Kamu mendekat sedikit, aku akan menunjukkannya padamu."
  },
  AvgDialog_18906_Content_19 = {
    Text = "Lihat, di tikungan sana, sangat dekat."
  },
  AvgDialog_18906_Content_2 = {
    Text = "Begitu kamu turun dari mobil, kamu langsung merasa sesak karena kelembapan yang pekat dan bau busuk pembusukan."
  },
  AvgDialog_18906_Content_20 = {
    Text = "Ah! Terima kasih banyak."
  },
  AvgDialog_18906_Content_21 = {
    Text = "Tidak, aku yang harus berterima kasih kepada kamu."
  },
  AvgDialog_18906_Content_22 = {
    Text = "Terima kasih kepada saya?"
  },
  AvgDialog_18906_Content_23 = {
    Text = [[
Ogier berbalik untuk melihat tangga tempat anak itu tadi berada, namun di sana sudah kosong melompong.
Entah sejak kapan, sosok bertudung itu sudah meluncur ke ujung jalan, dengan dompet Ogier masih tergenggam di tangannya.]]
  },
  AvgDialog_18906_Content_24 = {
    Text = "Ah, dompetku——"
  },
  AvgDialog_18906_Content_25 = {
    Text = "Londinium Fakta Umum Kedua: Upacara penyambutan paling terkenal di Timur adalah dompetmu menghilang tanpa kamu sadari."
  },
  AvgDialog_18906_Content_26 = {
    Text = [[
Sepertinya, kita harus membantu Ogier.
Ayo pergi, Penjaga.]]
  },
  AvgDialog_18906_Content_3 = {
    Text = [[
Perasaan pusing yang kuat disertai dengan dering telinga yang keras tiba-tiba menyerangmu. 
 Gambar kabur melintas cepat di benakmu, seakan-akan pada suatu saat, kamu pernah menyaksikan adegan serupa.]]
  },
  AvgDialog_18906_Content_4 = {
    Text = "Apakah itu ilusi, atau apakah itu bagian dari memori yang hilang milikmu?"
  },
  AvgDialog_18906_Content_5 = {
    Text = "Di sini tidak ada rambu jalan, juga tidak ada papan petunjuk… Dan tidak sesuai dengan peta…"
  },
  AvgDialog_18906_Content_6 = {
    Text = "Salah satu pengetahuan umum tentang Londinium: Selain kabut tebal yang tak kunjung hilang, jalan-jalan sempit yang berliku-liku di Distrik Timur juga bisa membuatmu tersesat."
  },
  AvgDialog_18906_Content_7 = {
    Text = "Aku akan bertanya tentang arah."
  },
  AvgDialog_18906_Content_8 = {
    Text = "Di tepi jalan, seorang anak dengan tudung lusuh terbaring dengan malas. Jubahnya sangat tidak pas di tubuhnya, membuat posturnya tampak lebih pendek."
  },
  AvgDialog_18906_Content_9 = {
    Text = "Ogier mendekati anak itu dan membungkuk dengan hormat."
  },
  AvgDialog_18907_Content_1 = {Text = "Penyakit"},
  AvgDialog_18907_Content_10 = {
    Text = "Jenkin! Bagaimana bisa… tidak boleh membawa sponsor ke <Blue:Area Medis>, jika sampai donor melihat ini…"
  },
  AvgDialog_18907_Content_11 = {
    Text = "Kau memberi isyarat kepada Ramona, dan Ramona mendekati Aigis, bertanya dengan lembut."
  },
  AvgDialog_18907_Content_12 = {
    Text = "Aigis, bisakah kamu menjelaskan kepada kami, mengapa sponsor tidak bisa datang ke area medis?"
  },
  AvgDialog_18907_Content_13 = {
    Text = "Ini, ini... aku... mereka... mereka dalam kelemahan..."
  },
  AvgDialog_18907_Content_14 = {
    Text = "Aigis tampak ragu-ragu. Dia melihat pasien di belakangnya, lalu melihat kalian yang berpakaian rapi, terbata-bata tidak tahu bagaimana menjawab."
  },
  AvgDialog_18907_Content_15 = {
    Text = "Memanfaatkan kesempatan ini, kamu dan Ogier mendekati pria tua yang terbaring di tempat tidur, lalu mengamati dengan cermat."
  },
  AvgDialog_18907_Content_16 = {
    Text = "Orang tua itu diikat tangan dan kakinya dengan kain kasar, lalu ditambatkan di tempat tidur. Di tubuhnya terdapat bekas luka aneh, sekilas tampak seperti jejak jahitan yang terdistorsi. Cairan hitam pekat memenuhi area kulit dan daging yang belum sembuh."
  },
  AvgDialog_18907_Content_17 = {
    Text = [[
Aigis, inspeksi kali ini akan menentukan apakah kita memberikan bantuan ekonomi kepada Panti Asuhan Lily. 
Kamu seharusnya bisa mengerti, tidak ada donatur yang mau uangnya jatuh ke tangan penipu.]]
  },
  AvgDialog_18907_Content_18 = {
    Text = "Mereka tidak akan memberikan kerusakan padamu, jangan melawan mereka."
  },
  AvgDialog_18907_Content_19 = {
    Text = "Keraguan di wajah Aigis menghilang setelah beberapa saat bernapas. Dia menarik napas dalam-dalam dan menjawab dengan suara pelan seperti nyamuk."
  },
  AvgDialog_18907_Content_2 = {
    Text = "Jenkin memimpin kalian melewati halaman belakang, lalu menunjuk ke sebuah gubuk kecil yang rusak di sudut."
  },
  AvgDialog_18907_Content_20 = {
    Text = "<Small:Bu Sarah berkata, jika para donatur melihat pasien-pasien ini, mereka akan menganggap kita sebagai lubang tanpa dasar…>"
  },
  AvgDialog_18907_Content_21 = {
    Text = "Kamu seharusnya tidak mendengarkan omongan wanita busuk itu! Beberapa dermawan ini akan membantu kita menyelesaikan masalah <Yellow:Hantu Workhouse>. Mereka juga sedang mencari seseorang, jadi pasti mereka akan menemukan kakakku..."
  },
  AvgDialog_18907_Content_22 = {
    Text = "Area medis terlalu berbahaya!"
  },
  AvgDialog_18907_Content_23 = {
    Text = "Nada tinggi Aigis tiba-tiba terhenti. Dia dengan gelisah menoleh untuk melihat pria tua yang kehilangan kesadaran, lalu menarik Jenkin menjauh dari sisi tempat tidur pasien."
  },
  AvgDialog_18907_Content_24 = {
    Text = "Bagaimana kalau menulari kamu dan penyandang dana... apa yang harus dilakukan..."
  },
  AvgDialog_18907_Content_25 = {
    Text = "Aigis dengan gugup dan lemah membantah Jenkin. Dia erat memeluk boneka beruang kecilnya, lengan bajunya yang berwarna putih meluncur ke bawah lengan, menampakkan jejak jahitan hitam yang mengerikan serta dua bekas cekikan yang memerah dan bengkak."
  },
  AvgDialog_18907_Content_26 = {
    Text = "Lengan gadis itu ramping dan rapuh, dengan retakan hitam yang menyerupai serangga raksasa beratus-ratus kaki. Tepi retakan tersebut perlahan mengeluarkan cairan hitam kental, membuat siapa pun merinding."
  },
  AvgDialog_18907_Content_27 = {
    Text = "Aigis, luka di lenganmu..."
  },
  AvgDialog_18907_Content_28 = {
    Text = "Aigis dengan cemas menarik lengan bajunya, menggelengkan kepala untuk menghindari tatapan Ramona."
  },
  AvgDialog_18907_Content_29 = {
    Text = "Ini adalah bekas dari terakhir kali aku tidak sengaja jatuh dari tangga."
  },
  AvgDialog_18907_Content_3 = {
    Text = [[
Dari luar jendela, terlihat bayangan Aigis yang sibuk bergerak. 
 Dia memegang baskom besi, buru-buru membawa perban kotor dari sisi tempat tidur pasien ke tumpukan pakaian kotor.]]
  },
  AvgDialog_18907_Content_30 = {
    Text = "Jejak jahitan ini tidak mirip dengan luka biasa akibat terjatuh atau tergores."
  },
  AvgDialog_18907_Content_31 = {
    Text = [[
Lihatlah, mereka bisa "melihat". 
Beritahu mereka semuanya, mereka adalah harapan terakhir.]]
  },
  AvgDialog_18907_Content_32 = {
    Text = "<Small:Mereka akan berada dalam bahaya, tidak boleh...>"
  },
  AvgDialog_18907_Content_33 = {
    Text = "Dengarkan aku, Aigis. Hanya dengan mengungkapkan kebenaran kepada kami, barulah kami bisa benar-benar menilai jenis bantuan apa yang kalian butuhkan."
  },
  AvgDialog_18907_Content_34 = {
    Text = "Di sisi tubuhmu, lelaki tua itu mengeluarkan suara aneh dari tenggorokannya. Lengan kurusnya merobek ikatan kain dan tiba-tiba terangkat ——"
  },
  AvgDialog_18907_Content_35 = {
    Text = "Penjaga, hati-hati!"
  },
  AvgDialog_18907_Content_4 = {
    Text = "Hmm? Ada apa?"
  },
  AvgDialog_18907_Content_5 = {
    Text = [[
Sepertinya dia mendengar panggilan seseorang, lalu meletakkan baskom besi dan membungkuk di sisi tempat tidur. 
 Dari sudut pandang kalian, sosok kecilnya sudah tidak terlihat, hanya terdengar suara lembutnya.]]
  },
  AvgDialog_18907_Content_6 = {
    Text = "Kakek Robert, jangan bangun, biarkan saya yang membawakan air untuk Anda."
  },
  AvgDialog_18907_Content_7 = {
    Text = [[
Jangan berkata seperti itu, penyakit Anda pasti akan sembuh. 
Pada saat itu, kita bisa pergi ke Taman Dreyer untuk bermain dan memberi makan merpati bersama lagi.]]
  },
  AvgDialog_18907_Content_8 = {
    Text = [[
"Dengan bunyi 'bang', Jenkin mendorong pintu gubuk terbuka.
Aigis terkejut, dalam kepanikannya hampir saja menumpahkan air ke tubuh pasien."]]
  },
  AvgDialog_18907_Content_9 = {
    Text = "Lihat, ini adalah <Yellow:orang gila>."
  },
  AvgDialog_18908_Content_1 = {
    Text = "Jangan berbicara yang tidak sopan"
  },
  AvgDialog_18908_Content_10 = {
    Text = "Saat melihat permen, wajah Aigis sedikit memucat, namun tetap hati-hati menerimanya."
  },
  AvgDialog_18908_Content_11 = {
    Text = "Apakah kamu masih ingat apa yang terjadi pada hari kita bertemu?"
  },
  AvgDialog_18908_Content_12 = {
    Text = "Hmm, aku tidak akan pernah melupakannya."
  },
  AvgDialog_18908_Content_13 = {
    Text = [[
10 hari yang lalu, Londinium Timur
Panti Asuhan Lily]]
  },
  AvgDialog_18908_Content_14 = {
    Text = "Tengah malam, wilayah timur tampak suram. Baik cahaya lampu jalan maupun sinar bulan, semuanya telah ditelan oleh kabut tebal yang menyelimuti, hanya menyisakan beberapa bayangan kabur yang bergoyang di udara."
  },
  AvgDialog_18908_Content_15 = {
    Text = [[
Gadis berbaju putih memeluk rasa bersalah dan ketakutan, berlari di halaman depan panti asuhan yang redup dan kosong. 
 Hingga ia menabrak sesuatu yang asing yang bersembunyi dalam bayangan, membuatnya menjerit kesakitan.]]
  },
  AvgDialog_18908_Content_16 = {Text = "Aduh!"},
  AvgDialog_18908_Content_17 = {Text = "Aduh!"},
  AvgDialog_18908_Content_18 = {
    Text = "Kamu, kamu bukan Xiao Mai, juga bukan Lucy! Siapa sebenarnya kamu…!"
  },
  AvgDialog_18908_Content_19 = {
    Text = "Aku juga mau bertanya, siapa kamu! Berkeliling di luar pada malam hari tanpa tidur, membuatku terkejut."
  },
  AvgDialog_18908_Content_2 = {
    Text = "Baru saja di tempat orang gila itu, apakah kamu tidak terluka?"
  },
  AvgDialog_18908_Content_20 = {
    Text = "Ya, maaf... aku pikir aku bertemu dengan..."
  },
  AvgDialog_18908_Content_21 = {
    Text = "Apa yang terjadi?"
  },
  AvgDialog_18908_Content_22 = {
    Text = "Bertemu dengan… hantu… Ya, aku pikir aku bertemu dengan <Red:Hantu Workhouse>…"
  },
  AvgDialog_18908_Content_23 = {
    Text = [[
Hantu? Apa-apaan ini. Aku akan jujur padamu, aku memang bukan orang dari tempat busuk ini. 
 Namaku Jenkin, dan ini Brown.]]
  },
  AvgDialog_18908_Content_24 = {Text = "Cit!"},
  AvgDialog_18908_Content_25 = {
    Text = [[
Saya masuk untuk mencari kakak perempuan saya. Namanya <Blue:Mason>, dia menghilang di sekitar sini dua minggu yang lalu. 
 Apakah ada orang bernama Mason yang baru muncul di sini akhir-akhir ini?]]
  },
  AvgDialog_18908_Content_26 = {
    Text = "Panti asuhan baru saja kedatangan banyak orang baru, aku belum sempat mengenal semua wajah mereka…"
  },
  AvgDialog_18908_Content_27 = {
    Text = "Coba ingat-ingat lagi, dia setinggi ini, rambutnya panjang, <Yellow:diikat dengan pita merah yang indah>, di ujung pita terdapat sebuah gesper persegi dengan ukiran huruf M."
  },
  AvgDialog_18908_Content_28 = {
    Text = "Dia sesekali datang ke sini untuk berobat. Setelah kunjungan terakhirnya, dia tidak pulang. Entah apakah kalian menahannya untuk bekerja."
  },
  AvgDialog_18908_Content_29 = {
    Text = [[
<Shake: Penyakit, pasien?>
Maaf... aku juga belum pernah melihat pasien wanita muda...]]
  },
  AvgDialog_18908_Content_3 = {
    Text = "Hmm... aku tidak masalah."
  },
  AvgDialog_18908_Content_30 = {
    Text = [[
Cih, terserahlah. Aku juga tidak berharap bisa seberuntung itu langsung bertemu dengan orang yang mengetahui informasi penting. 
Namun, kamu hampir membuatku ketahuan. Tanggung jawab ini harus kamu pikul.]]
  },
  AvgDialog_18908_Content_31 = {
    Text = "Nah, aku akan membawamu ke markas rahasia milikku! Nyonya Kepala Sekolah tidak pernah masuk ke menara lonceng. Jika kau bersembunyi di sana, dia pasti tidak akan menemukanmu."
  },
  AvgDialog_18908_Content_32 = {
    Text = [[
Jujur, hari itu sangat beruntung karena orang yang aku tabrak adalah kamu, Aigis. 
Kalau tidak, aku pasti sudah diusir dengan tudungku ditarik.]]
  },
  AvgDialog_18908_Content_33 = {
    Text = "Jangan bicara seperti itu, semua orang di panti asuhan adalah orang-orang yang sangat baik. Hanya saja, terlalu banyak hal buruk terjadi akhir-akhir ini, jadi suasana hati semua orang sedikit buruk..."
  },
  AvgDialog_18908_Content_34 = {Text = "Aigis."},
  AvgDialog_18908_Content_35 = {Text = "Hm?"},
  AvgDialog_18908_Content_36 = {
    Text = "Aku tahu semua orang di panti asuhan sangat penting bagimu... tapi aku selalu menganggapmu sebagai teman, jadi, apakah kau juga menganggapku sebagai teman?"
  },
  AvgDialog_18908_Content_37 = {
    Text = "Tentu saja! Aku sangat, sangat suka berada bersama Jenkin, makan permen dan mengobrol seperti ini."
  },
  AvgDialog_18908_Content_38 = {
    Text = [[
Jika kamu menganggapku sebagai teman, lalu mengapa kamu tidak mau mengatakan yang sebenarnya kepadaku? 
 Aigis, jangan berbohong padaku.]]
  },
  AvgDialog_18908_Content_39 = {
    Text = "Saya... Saya tidak mengerti apa yang kamu maksud..."
  },
  AvgDialog_18908_Content_4 = {
    Text = "... Saya membawa beberapa penyandang dana ke sana, apakah kamu sedang marah padaku?"
  },
  AvgDialog_18908_Content_40 = {
    Text = "Saya menemukan <Blue:buku besar> di kantor wanita itu, dan juga <Blue: kartu mahasiswa> orang yang sedang %player% cari. Aku tahu dia menjual kalian kepada para dokter aneh itu untuk eksperimen!"
  },
  AvgDialog_18908_Content_41 = {
    Text = "Wanita itu sangat menyukaimu, bahkan mempercayakanmu untuk merawat para pasien. Aigis, kau pasti tahu sesuatu, beritahu aku, oke?"
  },
  AvgDialog_18908_Content_42 = {
    Text = "Saya, saya. <Small:Saya tidak tahu…>"
  },
  AvgDialog_18908_Content_43 = {
    Text = [[
Gadis itu bergumam dengan suara yang semakin lama semakin pelan. 
 Wajahnya tampak pucat, seolah-olah sedang mengalami penderitaan yang sangat besar.]]
  },
  AvgDialog_18908_Content_44 = {
    Text = "Universitas Mythag paling mahir menggali Rahasia, mereka akan segera mengetahui kebenarannya."
  },
  AvgDialog_18908_Content_45 = {
    Text = "Kamu tidak bisa terus hidup dengan belenggu untuk selamanya."
  },
  AvgDialog_18908_Content_46 = {
    Text = "Jenkin, jika semua yang hilang sudah tidak bisa diperoleh kembali… apakah kebenaran yang sesungguhnya masih begitu penting?"
  },
  AvgDialog_18908_Content_47 = {
    Text = "Tentu saja penting! Bagi saya, tidak ada yang lebih penting daripada menemukan kakak."
  },
  AvgDialog_18908_Content_48 = {
    Text = "Aku tahu kamu takut pada wanita busuk itu, tapi kenapa kamu terus melindunginya? Dia tidak hanya menjual pekerja kepada Dokter, tetapi juga menyembunyikan <Yellow:Hantu Workhouse>."
  },
  AvgDialog_18908_Content_49 = {
    Text = "Ji, Ji Hantu Panti Asuhan?"
  },
  AvgDialog_18908_Content_5 = {
    Text = "Bagaimana bisa!"
  },
  AvgDialog_18908_Content_50 = {
    Text = [[
Ya, legenda yang kamu ceritakan kepadaku. 
<Yellow:Pada malam yang berkabut, jangan berjalan sembarangan, atau kamu akan ditangkap oleh hantu yang berkeliaran sambil membawa pisau>.]]
  },
  AvgDialog_18908_Content_51 = {
    Text = "Itu... itu hanya karangan saya... Malam terlalu berbahaya, aku tidak ingin kamu berkeliaran."
  },
  AvgDialog_18908_Content_52 = {
    Text = [[
Jangan bela Sarah lagi! Aku sudah menemukan <Yellow:ruang bawah tanah yang menyimpan hantu> dan mendengar <Yellow:suara pisau>. 
Apakah kakakku ada di dalam sana?]]
  },
  AvgDialog_18908_Content_53 = {
    Text = "Seiring dengan kata \"basement\" terlontar dari mulut Jenkin, warna terakhir di wajah Aigis pun memudar sepenuhnya."
  },
  AvgDialog_18908_Content_54 = {
    Text = "Jangan takut, Aigis. Lubang di dalam hatimu akan membuat-Nya masuk."
  },
  AvgDialog_18908_Content_55 = {
    Text = "Mengikuti bimbingan Perak, cahaya akan menunjukkan jalanmu."
  },
  AvgDialog_18908_Content_56 = {
    Text = "Jenkin, maaf, aku tidak bisa…"
  },
  AvgDialog_18908_Content_57 = {
    Text = "Aigis menatap Jenkin dengan mata berkaca-kaca, lalu berbalik dan memanjat kembali ke menara lonceng, berlari menuruni tangga tanpa sedikit pun ragu."
  },
  AvgDialog_18908_Content_58 = {
    Text = "Aigis! Kamu mau pergi ke mana!"
  },
  AvgDialog_18908_Content_59 = {
    Text = [[
Entah sejak kapan, kabut mulai menyelimuti panti asuhan. 
 Kabut ini muncul secara tiba-tiba, segala sesuatu di sekitarnya tertutup oleh lapisan uap air, tampak samar-samar.]]
  },
  AvgDialog_18908_Content_6 = {
    Text = "Aku hanya khawatir kamu juga... terjangkit......"
  },
  AvgDialog_18908_Content_60 = {
    Text = "Aigis! Sial, bagaimana kabut ini bisa masuk ke dalam ruangan!"
  },
  AvgDialog_18908_Content_61 = {
    Text = "Dari kejauhan di dalam Kabut, terdengar suara Caro yang mengembang, dan nyanyian samar yang dibasahi oleh embun air."
  },
  AvgDialog_18908_Content_62 = {
    Text = "<Italic:Charlie tua memiliki seekor kucing belang yang sangat dia cintai…>"
  },
  AvgDialog_18908_Content_63 = {
    Text = "Jenkin mengelap lenteranya, cahaya kecil itu tampak begitu lemah dan tak berdaya di tengah kabut yang tebal."
  },
  AvgDialog_18908_Content_64 = {
    Text = "Langkah kaki yang pelan terdengar dari kejauhan, hampir menusuk telinga di koridor yang sunyi."
  },
  AvgDialog_18908_Content_65 = {
    Text = [[
Siapa, siapa di sana? 
 Keluar! Aku memperingatkanmu, aku punya senjata!]]
  },
  AvgDialog_18908_Content_66 = {
    Text = "Tidak ada aliran udara di lorong, namun nyala api pada sumbu lampu bergerak seolah-olah tertiup angin."
  },
  AvgDialog_18908_Content_67 = {
    Text = "Langkah kaki semakin dekat, semakin dekat. Cakar Cokelat menancap dalam ke bahu Jenkin, memperlihatkan giginya dan mengeluarkan suara ancaman tajam yang khas bagi tikus."
  },
  AvgDialog_18908_Content_68 = {
    Text = "Seperti terpicu oleh suara Cokelat, langkah kaki tiba-tiba bertambah cepat, ternyata menuju ke arah Jenkin."
  },
  AvgDialog_18908_Content_69 = {
    Text = "Bayangan hitam yang pekat sepenuhnya menelan nyala lilin yang lemah. Gadis itu menutup matanya dan berteriak dengan keras, namun hanya merasakan hembusan uap air menerpa wajahnya."
  },
  AvgDialog_18908_Content_7 = {Text = "Itu bagus."},
  AvgDialog_18908_Content_70 = {
    Text = "Sebuah tangan muncul dari kegelapan dan tepat menyentuh bahu Jenkin."
  },
  AvgDialog_18908_Content_71 = {
    Text = "Apa yang terjadi padamu? Wajahmu sangat pucat."
  },
  AvgDialog_18908_Content_72 = {
    Text = "Rogers, apakah kamu melihat Aigis?"
  },
  AvgDialog_18908_Content_73 = {
    Text = "Jangan khawatir, Aigis sangat mengenal panti asuhan ini, dia akan baik-baik saja."
  },
  AvgDialog_18908_Content_74 = {
    Text = "Saya bisa memahami, malam yang berkabut memang mudah membuat orang merasa ketakutan dan was-was."
  },
  AvgDialog_18908_Content_75 = {
    Text = "Rogers mendorong pintu terbuka, cahaya hangat memancar keluar, mengusir bayangan yang pekat di koridor."
  },
  AvgDialog_18908_Content_76 = {
    Text = "Dia mengambil boneka yang dibuat dengan indah dari atas tempat tidur dan tersenyum kepada gadis itu."
  },
  AvgDialog_18908_Content_77 = {
    Text = [[
Sebagai penghiburan, apakah kamu ingin mencoba menyentuhnya? 
<Blue:George> akan merasa senang.]]
  },
  AvgDialog_18908_Content_78 = {
    Text = "Mata boneka yang tak bernyawa memantulkan cahaya kuning dari lampu, seakan-akan diam-diam memohon kepada gadis itu: \"Sentuh aku, hanya sekali.\""
  },
  AvgDialog_18908_Content_79 = {
    Text = "Sentuh aku, lalu——"
  },
  AvgDialog_18908_Content_8 = {
    Text = "Jenkin dengan gerakan yang berlebihan membuka kedua tangannya, dan di telapak tangannya terdapat dua permen kecil."
  },
  AvgDialog_18908_Content_80 = {
    Text = "<Red:Menjadi teman setia saya.>"
  },
  AvgDialog_18908_Content_81 = {
    Text = "\"Dengan suara 'ciit', teriakan Cokelat mengembalikan kesadaran Jenkin yang sedang melamun.\""
  },
  AvgDialog_18908_Content_82 = {
    Text = "Tidak, tidak perlu! Aku tidak tertarik pada kalian, para seniman dari kalangan atas."
  },
  AvgDialog_18908_Content_83 = {
    Text = [[
Oh, tikus kecil yang polos. Sebenarnya, keindahan dan seni... tidak pernah memandang kaya atau miskin, mulia atau hina. 
 Mengubah penderitaan menjadi keindahan adalah hal yang sangat, sangat baik.]]
  },
  AvgDialog_18908_Content_84 = {
    Text = "Rogers menatap gadis yang penuh kewaspadaan dan tikus abu-abu yang muncul dari tudung gadis itu dengan pandangan membara, seolah-olah menahan Keinginan yang tak terbendung."
  },
  AvgDialog_18908_Content_85 = {
    Text = [[
Jika ada kesempatan, aku juga akan membuatmu dan kalian menjadi patung lilin. 
 Namanya akan menjadi "Cokelat dan Jenkin", bagaimana?]]
  },
  AvgDialog_18908_Content_9 = {
    Text = "Nah, satu untuk masing-masing. Setelah memakan permen ini, kamu harus bersumpah untuk tidak marah padaku, oke."
  },
  AvgDialog_18909_Content_1 = {
    Text = "Hantu bawah tanah"
  },
  AvgDialog_18909_Content_10 = {
    Text = [[
Ramona tetap tenang, kalimatnya mengalir lancar seperti seorang aktor panggung yang telah menghafal ribuan dialog. 
 Di sampingnya, Ogier sudah memerah karena malu.]]
  },
  AvgDialog_18909_Content_11 = {
    Text = "Benar-benar pantas sebagai tuan muda dari keluarga Tuan Mulia Ash, sudah bisa memikul tanggung jawab besar di usia semuda ini. \n Di panti asuhan, ada banyak anak seusianya yang hanya bisa membantu menuangkan bubur dan menyapu lantai saja sudah dianggap cukup baik…"
  },
  AvgDialog_18909_Content_12 = {
    Text = "Anda, tolong jangan berkata seperti itu..."
  },
  AvgDialog_18909_Content_13 = {
    Text = "Ramona batuk ringan, dengan cepat mengalihkan arah pembicaraan."
  },
  AvgDialog_18909_Content_14 = {
    Text = "Oleh karena itu, kami akan melakukan serangkaian survei lapangan di wilayah timur, dengan dukungan pendanaan jangka panjang untuk memahami situasi setempat. \nLily's Poorhouse adalah tujuan pertama kami, dan semoga direktur mau bersikap terbuka kepada kami…"
  },
  AvgDialog_18909_Content_15 = {
    Text = "Ramona menceritakan kronologi penjaga di depan pintu panti asuhan yang berubah menjadi pembunuh, tentu saja, bagian tentang pelarutan dilewatkan."
  },
  AvgDialog_18909_Content_16 = {
    Text = "Apakah Anda mengetahui tentang hal ini?"
  },
  AvgDialog_18909_Content_17 = {
    Text = [[
Apa? Masih ada hal seperti ini! Petugas keamanan itu pasti bukan orang dari panti kami.
Lagipula, di sini tidak ada yang bisa dicuri atau dirampok, jadi untuk apa mempekerjakan petugas keamanan?]]
  },
  AvgDialog_18909_Content_18 = {
    Text = "Ekspresinya canggung, jelas sedang berbohong."
  },
  AvgDialog_18909_Content_19 = {
    Text = "Namun, Nona Sarah…"
  },
  AvgDialog_18909_Content_2 = {
    Text = "Kalian semua memasuki panti asuhan. Dari jauh, terlihat seorang wanita berpakaian biarawati sedang memimpin beberapa anak dan pekerja berbaris untuk menunggu kalian."
  },
  AvgDialog_18909_Content_20 = {
    Text = "Sarah memberikan tatapan tajam kepada gadis di sisinya, gadis itu menunjukkan Ekspresi panik."
  },
  AvgDialog_18909_Content_21 = {
    Text = "Aigis, kamu masih muda. Yang terpenting adalah menjaga dirimu sendiri. Urusan orang dewasa, jangan ikut campur."
  },
  AvgDialog_18909_Content_22 = {
    Text = "Gadis itu menekan bibirnya, memandangi boneka di tangannya dengan tatapan tertunduk, dan tidak mengucapkan sepatah kata pun."
  },
  AvgDialog_18909_Content_23 = {
    Text = "... Sudahlah, bawa seorang pekerja ke sana. Tutupi dia dengan kain, jangan sampai tikus menggigitnya."
  },
  AvgDialog_18909_Content_24 = {
    Text = "Setelah selesai berbicara, dia kembali berbalik ke arah kalian."
  },
  AvgDialog_18909_Content_25 = {
    Text = "Maaf, ketika dokter datang, saya akan meminta mereka untuk membantu merapikan jenazah."
  },
  AvgDialog_18909_Content_26 = {Text = "Dokter?"},
  AvgDialog_18909_Content_27 = {
    Text = "Ah… ya, memang begitu. Di sini ada banyak anak, dan berkat kemurahan hati para donatur lainnya, seorang Dokter datang secara teratur untuk memeriksa kondisi anak-anak."
  },
  AvgDialog_18909_Content_28 = {
    Text = "Menghitung waktu, pemeriksaan tubuh berikutnya akan dilakukan dalam dua hari ke depan."
  },
  AvgDialog_18909_Content_29 = {
    Text = "Tidak perlu memberi tahu kantor polisi?"
  },
  AvgDialog_18909_Content_3 = {
    Text = [[
Panti asuhan memiliki banyak urusan, kami mohon maaf karena tidak menyambut Anda dengan baik, Yang Terhormat {Male=tuan,Female=nona} Ash, dan Nona Mary.
Saya Sarah, pengelola di sini.]]
  },
  AvgDialog_18909_Content_30 = {
    Text = "Ah, di sinilah Anda belum mengetahuinya, Distrik Timur memiliki aturannya sendiri."
  },
  AvgDialog_18909_Content_31 = {
    Text = "Bahkan dalam insiden yang membuat orang panik <Red:Acara Pembunuhan>, mereka hanya mengirim orang untuk mengambil mayat, lalu tidak ada kabar lagi."
  },
  AvgDialog_18909_Content_32 = {
    Text = "Bagi kami, makan kenyang saja sudah cukup sulit, apalagi menyisihkan banyak energi untuk hal-hal seperti ini."
  },
  AvgDialog_18909_Content_33 = {
    Text = [[
Setelah berkata demikian, Sarah memimpin kalian masuk ke dalam panti asuhan. 
 Di belakang kalian, para pekerja berdiri dengan tenang dalam dua barisan, seolah-olah menjadi pengawal, atau mungkin juga penjaga.]]
  },
  AvgDialog_18909_Content_34 = {
    Text = "Kamu mendengar bisikan yang diucapkan Ramona dengan pelan."
  },
  AvgDialog_18909_Content_35 = {
    Text = "Londinium Common Sense Ketiga ——"
  },
  AvgDialog_18909_Content_36 = {
    Text = "\"Di Distrik Timur, harga manusia tidak terukur. Karena mereka tidak memiliki nilai.\""
  },
  AvgDialog_18909_Content_37 = {
    Text = [[
Di koridor yang sunyi, pintu dengan plakat logam perlahan terbuka. 
 Seekor tikus meluncur keluar dari celah pintu, memandang ke kiri dan kanan, lalu mengeluarkan suara ciit-ciit ke arah Bayangan di koridor.]]
  },
  AvgDialog_18909_Content_38 = {Text = "Cit!"},
  AvgDialog_18909_Content_39 = {
    Text = "Terakhir kamu juga bilang tidak ada orang! Kalau bukan karena bertemu dengan Aigis, aku pasti sudah celaka besar."
  },
  AvgDialog_18909_Content_4 = {
    Text = [[
Melihat orang di sekitarnya tidak melanjutkan pembicaraan, dia mengerutkan alis dan menepuk punggung gadis itu. 
 Gadis itu tampak sedang melamun, dan seperti tersentak kaget saat ini, lalu buru-buru memberi hormat kepada kalian.]]
  },
  AvgDialog_18909_Content_40 = {
    Text = "Jenkin mengintip dari sudut, memastikan bahwa tidak ada seorang pun di koridor sebelum keluar melalui celah pintu, lalu menutup pintu di belakangnya."
  },
  AvgDialog_18909_Content_41 = {
    Text = "Cicit, cicit cicit cicit!"
  },
  AvgDialog_18909_Content_42 = {
    Text = "Betul betul, kamu benar sekali. Cokelat kita yang paling hebat!"
  },
  AvgDialog_18909_Content_43 = {
    Text = "Cicit cicit, cicit."
  },
  AvgDialog_18909_Content_44 = {
    Text = [[
Biarkan aku lihat rahasia apa yang disembunyikan oleh wanita sialan ini. 
 Cincin, kalung... apakah semua ini terbuat dari emas?]]
  },
  AvgDialog_18909_Content_45 = {
    Text = "Wanita busuk ini bahkan tidak mau membelikan Aigis permen, katanya \"pengeluaran tidak sesuai pemasukan\", tapi ternyata dia menyimpan banyak barang bagus untuk dirinya sendiri!"
  },
  AvgDialog_18909_Content_46 = {
    Text = [[
Kunci, baik, sepertinya keluar masuk tempat lain juga lebih mudah.
Benar-benar harus berterima kasih kepada apa yang disebut <Yellow:"Orang Swadaya">, kita bisa melakukan penyelidikan di panti asuhan secara mandiri.]]
  },
  AvgDialog_18909_Content_47 = {
    Text = "Cicit cicit, cicit."
  },
  AvgDialog_18909_Content_48 = {
    Text = "Jangan terburu-buru, Brown, masih ada waktu."
  },
  AvgDialog_18909_Content_49 = {
    Text = [[
Eh... ini... buku catatan?
Mick, laki-laki, 5 tahun, 10 Taring; Diana, perempuan, 23 tahun, 5 Taring...]]
  },
  AvgDialog_18909_Content_5 = {
    Text = "Selamat datang. Kami telah menyiapkan camilan di restoran..."
  },
  AvgDialog_18909_Content_50 = {
    Text = "Jangan bilang... Apakah panti asuhan ini benar-benar menjual semua orang?!"
  },
  AvgDialog_18909_Content_52 = {
    Text = "Cicit, cicit cicit cicit!"
  },
  AvgDialog_18909_Content_53 = {
    Text = "Cokelat tiba-tiba mengeluarkan peringatan yang tajam, pintu kayu berderit saat dibuka."
  },
  AvgDialog_18909_Content_54 = {
    Text = "Yang muncul di hadapan Sarah adalah sebuah kantor kosong tanpa seorang pun di dalamnya."
  },
  AvgDialog_18909_Content_55 = {
    Text = "Dia membuka laci setengah jalan, memasukkan sebuah benda tipis seukuran telapak tangan, lalu menutup kembali laci kayu itu dengan keras sebelum segera beranjak pergi."
  },
  AvgDialog_18909_Content_56 = {
    Text = "Cicit, cicit."
  },
  AvgDialog_18909_Content_57 = {
    Text = "Setelah Sarah pergi, Cokelat pertama kali berlari keluar dari bayangan tanaman pot di sudut."
  },
  AvgDialog_18909_Content_58 = {
    Text = "Jenkin mengikuti dengan langkah-langkah yang ringan dan membuka laci."
  },
  AvgDialog_18909_Content_59 = {
    Text = "Kartu pelajar? <Blue:Sean… Anderson>… \n Apakah simbol di atasnya sama dengan yang ada di dompet kulit berbulu emas milik orang yang tertipu tadi pagi?"
  },
  AvgDialog_18909_Content_6 = {
    Text = "Eh, siapa ini...?"
  },
  AvgDialog_18909_Content_60 = {
    Text = "Cicit, cicit cicit cicit!"
  },
  AvgDialog_18909_Content_61 = {
    Text = [[
Jangan terburu-buru, Cokelat. 
Aku harus tenang... tenang...]]
  },
  AvgDialog_18909_Content_62 = {
    Text = "Saya sudah memeriksa semuanya, nama kakak tidak ada di dalam buku pembukuan."
  },
  AvgDialog_18909_Content_63 = {
    Text = "Namun, kita masih punya banyak kunci. Aku bisa membuka setiap pintu di tempat sialan ini! Aku tidak percaya kalau aku tidak bisa menemukan bukti."
  },
  AvgDialog_18909_Content_64 = {
    Text = "Kakak, tunggu aku."
  },
  AvgDialog_18909_Content_66 = {
    Text = "……………"
  },
  AvgDialog_18909_Content_67 = {
    Text = "Sialan, ini ruangan terakhir."
  },
  AvgDialog_18909_Content_68 = {
    Text = [[
Gelap gulita, tidak ada apa-apa. 
 Kita harus pulang dengan tangan hampa, Cokelat.]]
  },
  AvgDialog_18909_Content_69 = {
    Text = "Cicit, cicit cicit cicit!"
  },
  AvgDialog_18909_Content_7 = {
    Text = "Sarah dengan ragu melihat Ogier di dalam tim, lalu dia melihat kalian."
  },
  AvgDialog_18909_Content_70 = {
    Text = "Apa? Di bawah lantai?"
  },
  AvgDialog_18909_Content_71 = {
    Text = "Jenkin ragu sejenak, namun tetap dengan lembut dia menyalakan lampu tempel. Dia memperkecil nyala api dan mendekatkannya ke tanah."
  },
  AvgDialog_18909_Content_72 = {
    Text = "Itu adalah barisan semut, berbaris dalam formasi yang rapi, memanjang hingga ke celah papan."
  },
  AvgDialog_18909_Content_73 = {
    Text = [[
Jenkin mencungkil dua paku dan membuka papan kayu. 
 Di bawah papan terdapat penutup besi berukuran 25 inci persegi.]]
  },
  AvgDialog_18909_Content_74 = {
    Text = "Jenkin mencoba semua kunci satu per satu."
  },
  AvgDialog_18909_Content_75 = {
    Text = [[
Sial, semuanya tidak bisa dibuka. 
Apakah wanita ini menyembunyikan kunci lain?]]
  },
  AvgDialog_18909_Content_76 = {
    Text = "Dia menempelkan telinganya ke pelat besi, berusaha mendengarkan suara dari dalam ruang bawah tanah."
  },
  AvgDialog_18909_Content_77 = {
    Text = "<Italic:Gesekan… gesekan…>"
  },
  AvgDialog_18909_Content_78 = {Text = "!!"},
  AvgDialog_18909_Content_79 = {
    Text = "Ini, ini pasti... yang dikatakan Aigis, <Yellow:Hantu dari Panti Asuhan>…!"
  },
  AvgDialog_18909_Content_8 = {
    Text = "Dia adalah adikku, Ogier, dan juga salah satu calon pewaris Keluarga Ash."
  },
  AvgDialog_18909_Content_80 = {
    Text = "Cicit, cicit cicit cicit!"
  },
  AvgDialog_18909_Content_81 = {
    Text = "Di luar pintu terdengar samar-samar suara langkah kaki."
  },
  AvgDialog_18909_Content_82 = {
    Text = [[
Tidak ada jalan lain, Cokelat. 
 Jika wanita sialan itu masih memelihara hantu di workhouse, kita tidak akan bisa mengalahkannya hanya dengan kekuatan kita berdua.]]
  },
  AvgDialog_18909_Content_83 = {
    Text = "Kami membutuhkan <Yellow:orang yang membuatnya takut>…"
  },
  AvgDialog_18909_Content_84 = {
    Text = "Jenkin bersembunyi di dalam bayangan, mengandalkan tanaman pot sebagai penutup sambil menjulurkan setengah kepalanya."
  },
  AvgDialog_18909_Content_85 = {
    Text = "Di koridor, Sarah sedang memperkenalkan kondisi pendapatan dan pengeluaran panti asuhan kepada rombongan pengunjung dengan sikap yang penuh kepatuhan."
  },
  AvgDialog_18909_Content_86 = {
    Text = "... Apakah itu yang dikatakan Aigis, manusia mandiri?"
  },
  AvgDialog_18909_Content_87 = {
    Text = "Jenkin mengangguk dengan ekspresi penuh renungan, lalu diam-diam meninggalkan ruang penyimpanan gelap saat kelompok itu lengah."
  },
  AvgDialog_18909_Content_88 = {
    Text = "Di belakangnya, lantai yang tidak sepenuhnya terpasang membuka celah hitam yang dalam dan gelap, menunggu kedatangan pengunjung dalam kesunyian."
  },
  AvgDialog_18909_Content_9 = {
    Text = "Mulia berharap agar Tuan Muda Ogier dapat memiliki pemahaman yang lebih mendalam mengenai situasi di Distrik Timur, sehingga ketika dia mengambil alih industri keluarga di masa depan, dia bisa lebih efektif dalam memperbaiki kondisi lingkungan Distrik Timur."
  },
  AvgDialog_18910_Content_1 = {
    Text = "Sial, banyak monster masuk, semakin banyak saja!"
  },
  AvgDialog_18910_Content_2 = {
    Text = "Ogier, pergi dan tutup pintu besar di basement! Ramona, fokus untuk menekan Sarah!"
  },
  AvgDialog_18910_Content_3 = {
    Text = "Dengar perintah!"
  },
  AvgDialog_18911_Content_1 = {
    Text = "Semuanya telah berakhir."
  },
  AvgDialog_18911_Content_10 = {
    Text = "Pisau mengikuti gerakan tangan, meninggalkan jejak perak panjang."
  },
  AvgDialog_18911_Content_11 = {
    Text = "Nyonya Sarah! Tiuyug! Tolong! Selamatkan aku! <Big:Selamatkan aku!>"
  },
  AvgDialog_18911_Content_12 = {
    Text = "Ujung pisaunya semakin dekat, semakin dekat, hingga memenuhi seluruh pandangan.\nLalu——"
  },
  AvgDialog_18911_Content_13 = {
    Text = "<Shake: Ah————!>"
  },
  AvgDialog_18911_Content_14 = {
    Text = "Aigis gemetar, dari dalam tenggorokannya terdengar jeritan yang bergetar karena ketakutan."
  },
  AvgDialog_18911_Content_15 = {
    Text = "Seolah-olah dipanggil oleh teriakan itu, dokter misterius muncul diam-diam di belakangnya."
  },
  AvgDialog_18911_Content_16 = {
    Text = "Apakah Aigis menghadapi masalah baru? Maukah kamu berbicara dengan Dokter Clementine?"
  },
  AvgDialog_18911_Content_17 = {
    Text = "Dokter Clementine?!"
  },
  AvgDialog_18911_Content_18 = {
    Text = "Panti asuhan di tengah malam bukanlah tempat terbaik untuk kunjungan, mengapa kamu ada di sini?"
  },
  AvgDialog_18911_Content_19 = {
    Text = "Jangan terlalu serius. Akhir-akhir ini, panti asuhan sedang mengalami ketidaktenangan. Mr. Rogers khawatir tentang kondisi Roh para pekerja dan anak-anak, sehingga dia secara khusus mempekerjakan saya untuk merawat semua orang."
  },
  AvgDialog_18911_Content_2 = {
    Text = "Ramona berbalik ke arah gadis yang masih gemetar ketakutan, bahkan giginya ikut bergetar, dan dia tak mampu mengucapkan sepatah kata pun."
  },
  AvgDialog_18911_Content_20 = {
    Text = "Terkadang, ketika melakukan pemeriksaan hingga larut malam, saya juga menginap di panti asuhan, tidur di ruangan dekat dengan anak-anak."
  },
  AvgDialog_18911_Content_21 = {
    Text = "Aigis, apakah kamu mengenalnya?"
  },
  AvgDialog_18911_Content_22 = {
    Text = "Kedatangan Clementine membuat gadis itu terlepas dari kenangannya. Dia mengangguk dan memberikan jawaban yang tegas."
  },
  AvgDialog_18911_Content_23 = {
    Text = "Sejak pertama kali saya tiba di panti asuhan, dia sudah menjadi tamu kecil saya."
  },
  AvgDialog_18911_Content_24 = {
    Text = "Menceritakan masalah adalah salah satu cara penyembuhan psikologis, dan kebetulan saya adalah pendengar yang sangat profesional."
  },
  AvgDialog_18911_Content_25 = {
    Text = "Pandangan penuh pengamatan meluncur satu per satu di wajah semua orang, dan akhirnya berhenti pada dirimu."
  },
  AvgDialog_18911_Content_26 = {
    Text = "Tidak perlu, kami masih punya urusan."
  },
  AvgDialog_18911_Content_27 = {
    Text = [[
Sayang sekali. Jika kamu berubah pikiran, kamu selalu diterima untuk bergabung dalam perjalanan kami mencari jati diri.
Ayo pergi, Aigis.]]
  },
  AvgDialog_18911_Content_28 = {
    Text = "Aigis menggandeng tangan Clementine, berjalan pergi dalam diam."
  },
  AvgDialog_18911_Content_29 = {
    Text = "Aigis! Kalian mau pergi ke mana!"
  },
  AvgDialog_18911_Content_3 = {
    Text = "Dia perlahan menggulung lengan baju Aigis, jahitan bekas operasi tampak mencolok, sangat menyolok di pergelangan tangannya yang putih."
  },
  AvgDialog_18911_Content_30 = {
    Text = "<Small:Maaf… Dokter Clemetine bisa membantu saya…>"
  },
  AvgDialog_18911_Content_31 = {
    Text = "Setelah gadis itu selesai berbicara, dia dengan langka menarik lengan baju Clementine dengan kuat. Di bawah dorongan tanpa suara, kedua sosok mereka menghilang di balik pintu panti asuhan."
  },
  AvgDialog_18911_Content_32 = {
    Text = "Aigis… Tidak tahu rahasia apa yang disembunyikan oleh anak ini."
  },
  AvgDialog_18911_Content_33 = {
    Text = "Kabut hampir hilang, ayo kita kembali untuk beristirahat sejenak. Pada akhir malam nanti, kita sudah berjanji dengan Jenkin untuk menyelidiki basement, jadi kita perlu menghemat tenaga."
  },
  AvgDialog_18911_Content_4 = {
    Text = [[
Aigis, mereka juga melakukan eksperimen yang sama padamu. 
 Mereka mengikatmu, memaksamu menjalani operasi, dan menanamkan beberapa... <Yellow:benda asing> di tubuhmu, benar kan?]]
  },
  AvgDialog_18911_Content_5 = {
    Text = "Aku, aku, pada saat itu..."
  },
  AvgDialog_18911_Content_6 = {
    Text = "Hmm... di sini adalah..."
  },
  AvgDialog_18911_Content_7 = {
    Text = "Cahaya yang sangat terang membuat seseorang secara tidak sadar ingin menutup mata. Aigis mencoba mengendalikan kelopak matanya, tetapi dia menyadari bahwa dia tidak mampu melakukannya."
  },
  AvgDialog_18911_Content_8 = {
    Text = "Logam dingin mengunci otot di sekitar matanya, dia hanya bisa melihat pria berjubah putih itu perlahan mendekatinya dengan pisau bedah."
  },
  AvgDialog_18911_Content_9 = {
    Text = "Tidak, jangan, Nona Sarah, Nona Sarah!"
  },
  AvgDialog_18912_Content_1 = {
    Text = "Kunci perak berkedip dengan kuat, gadis itu tiba-tiba menopang tubuhnya, samar-samar mendengar suara sesuatu yang robek."
  },
  AvgDialog_18912_Content_10 = {
    Text = "Kamu juga terjatuh lemas di tanah, menahan rasa sakit yang berdenyut-denyut di kepala serta mual yang menyusul kemudian."
  },
  AvgDialog_18912_Content_11 = {Text = "%player%!"},
  AvgDialog_18912_Content_12 = {
    Text = [[
Apakah kekuatan rohmu sudah terkuras habis? Jika terus bertindak sembarangan, kamu tidak akan bisa menyaksikan masa depan Mythag. 
 Duduk dan beristirahatlah, kekuatan roh yang terkuras akan memengaruhi kemampuan persepsimu.]]
  },
  AvgDialog_18912_Content_13 = {
    Text = "Lupakan aku, cepat pergi dan lihat Aigis."
  },
  AvgDialog_18912_Content_14 = {
    Text = [[
Suara seperti penguapan cairan secara bertahap melemah, dan tak lama kemudian sepenuhnya menghilang. 
 Di lantai yang terkena cairan hitam lengket, seorang gadis menutupi salah satu matanya sambil duduk dengan tenang.]]
  },
  AvgDialog_18912_Content_15 = {
    Text = [[
Nyonya Ramona... dan juga... %player%{Male=tuan,Female=nyonya}.
Syukurlah kalian baik-baik saja.]]
  },
  AvgDialog_18912_Content_16 = {Text = "Aigis…"},
  AvgDialog_18912_Content_17 = {
    Text = "Ikut kami kembali ke Mythag, kami pasti akan mencari cara untuk menyembuhkan matamu."
  },
  AvgDialog_18912_Content_18 = {
    Text = "Kamu mengulurkan tanganmu ke arah Aigis."
  },
  AvgDialog_18912_Content_19 = {
    Text = [[
Aigis dengan lembut, sangat lembut, meletakkan telapak tangannya di atas telapak tanganmu. 
 Ujung jarinya dingin seperti batu, namun pada saat ini terasa hangat seperti matahari keemasan yang tenggelam di luar menara lonceng.]]
  },
  AvgDialog_18912_Content_2 = {
    Text = "Penutup mata perlahan melayang jatuh, warna yang bergerak menggantikan kegelapan. Sebuah pupil pucat raksasa muncul di bawahnya, seakan telah mengamati dia untuk waktu yang lama."
  },
  AvgDialog_18912_Content_20 = {
    Text = "Jenkin memberitahuku bahwa fenomena yang kalian teliti, yang sedang diuji oleh Dokter pada kami, disebut \"Pelarutan,\" yang akan membuat keberadaan seseorang perlahan menghilang hingga Memori terkait pun lenyap tanpa jejak."
  },
  AvgDialog_18912_Content_21 = {
    Text = "Jika ini benar… aku memiliki satu permohonan."
  },
  AvgDialog_18912_Content_22 = {
    Text = "Aigis berhenti sejenak, menahan isak tangis yang samar."
  },
  AvgDialog_18912_Content_23 = {
    Text = "Semoga semua orang di panti asuhan bisa melupakanku, melupakan rasa sakit yang telah kubawa kepada mereka."
  },
  AvgDialog_18912_Content_24 = {
    Text = "Dia mengangkat kepalanya dan menatapmu dengan murid yang dingin seperti batu."
  },
  AvgDialog_18912_Content_25 = {
    Text = "Pada saat itu, kamu kehilangan kemampuan untuk bergerak."
  },
  AvgDialog_18912_Content_26 = {
    Text = "Memanfaatkan kesempatan ini, dia berbalik dan menghilang di ujung yang suram, kemudian naik ke platform di luar menara jam."
  },
  AvgDialog_18912_Content_27 = {
    Text = "Sisa keemasan matahari terbenam menembus permukaan jam raksasa yang transparan di menara jam, dan menyelimuti tubuh gadis itu."
  },
  AvgDialog_18912_Content_28 = {
    Text = "Aigis memutar tubuhnya, meletakkan satu tangan di permukaan jam yang sudah lama tidak dibersihkan, dan menyipitkan mata sambil menghadap sinar matahari yang hangat."
  },
  AvgDialog_18912_Content_29 = {
    Text = "Hari ini, bisa melihat matahari, ya…"
  },
  AvgDialog_18912_Content_3 = {
    Text = "Apakah kamu... mata? Apakah mataku?"
  },
  AvgDialog_18912_Content_30 = {
    Text = "Seperti mendapatkan semangat dari hari cerah yang langka, dia menopang tubuhnya dan berjalan dengan goyah menuju sepotong kaca yang lebih bersih."
  },
  AvgDialog_18912_Content_31 = {
    Text = "Pandangan yang buram akhirnya menjadi jelas. Dia menatap jalan-jalan yang tampak akrab atau asing, dan dalam keadaan bingung, seolah-olah terdengar bisikan seseorang di telinganya."
  },
  AvgDialog_18912_Content_32 = {
    Text = "Lihat, suara itu berkata, \"Malam ini pasti bisa melihat langit penuh bintang yang cemerlang.\""
  },
  AvgDialog_18912_Content_33 = {
    Text = "Dulu, setiap kali hari cerah di mana kami bisa melihat matahari, Tiyouge diam-diam membawa saya ke sini dalam kegelapan."
  },
  AvgDialog_18912_Content_34 = {
    Text = "Nyonya Sarah tidak pernah mengizinkan kami datang ke sini. Dia berkata bahwa tempat ini terlalu berbahaya, dan kami bisa dengan mudah terluka."
  },
  AvgDialog_18912_Content_35 = {
    Text = "Tapi Tiyug tidak peduli dengan semua itu. Setiap malam setelah lampu dimatikan, setelah Nyonya Sarah selesai berkeliling memeriksa kamar, dia diam-diam membawa saya naik ke sini dalam gelap."
  },
  AvgDialog_18912_Content_36 = {
    Text = "Dia sama seperti Jenkin, cerdik dan berani, selalu mengetahui jalan-jalan kecil dan mekanisme yang tidak diketahui oleh orang lain."
  },
  AvgDialog_18912_Content_37 = {
    Text = "Selama dia yang membawa, kita tidak akan ditemukan oleh Nona Sarah."
  },
  AvgDialog_18912_Content_38 = {
    Text = "Selama dia membawa, tempat ini akan selalu menjadi basis rahasia kita."
  },
  AvgDialog_18912_Content_39 = {
    Text = "Dia memberi tahu saya bahwa saya harus sering berinteraksi dengan bintang-bintang agar kekuatan sihir saya bertambah kuat. Meskipun di sini kami tidak bisa melihat satu bintang pun."
  },
  AvgDialog_18912_Content_4 = {
    Text = "Tidak, salah! Perasaan ini adalah…! Ini Tuan @2!"
  },
  AvgDialog_18912_Content_40 = {
    Text = "Pada saat itu, dia adalah satu-satunya orang yang percaya padaku. Dia percaya bahwa aku bisa melihat hal-hal hitam itu dan memberitahuku bahwa itu adalah bakat dari seorang penyihir."
  },
  AvgDialog_18912_Content_41 = {
    Text = "Tetapi untuk melindungi saya, dia dibawa pergi oleh Doktor…"
  },
  AvgDialog_18912_Content_42 = {
    Text = [[
Jika aku secerdas dia, seberani Jenkin, mungkin aku sudah bisa mengungkap kebenarannya.
Namun, aku bukan penyihir. Aku hanyalah seorang pengecut, bahkan sebuah monster.]]
  },
  AvgDialog_18912_Content_43 = {
    Text = "Seorang... pembunuh."
  },
  AvgDialog_18912_Content_44 = {
    Text = "Aigis, kamu adalah anak yang baik. Kamu dikendalikan, itu bukan dosamu."
  },
  AvgDialog_18912_Content_45 = {
    Text = "Tahukah kamu sudah berapa banyak orang yang kujadikan patung tanpa kesadaran?"
  },
  AvgDialog_18912_Content_46 = {
    Text = "Aku sangat takut, takut akan apa yang akan aku menjadi."
  },
  AvgDialog_18912_Content_47 = {
    Text = "Juga takut akan apa yang telah menjadi diriku."
  },
  AvgDialog_18912_Content_48 = {
    Text = "Namun, semuanya sudah tidak penting lagi."
  },
  AvgDialog_18912_Content_5 = {
    Text = "Apakah kamu benar-benar bisa meminjamkan Kekuatanmu padaku? Lalu bagaimana denganmu?"
  },
  AvgDialog_18912_Content_50 = {
    Text = "Saya tidak akan dikendalikan lagi, tidak akan memberikan kerusakan kepada siapa pun lagi, dan tidak akan membiarkan teman-teman mati karena diriku lagi."
  },
  AvgDialog_18912_Content_52 = {
    Text = "Sialan, katanya tunggu di kamar, tapi mereka semua entah ke mana pergi."
  },
  AvgDialog_18912_Content_53 = {
    Text = "Itu adalah..."
  },
  AvgDialog_18912_Content_54 = {
    Text = "Aigis?! Aigis—!"
  },
  AvgDialog_18912_Content_55 = {
    Text = "Dari bawah menara lonceng, tiba-tiba terdengar suara Jenkin. Dia berteriak dengan cemas memanggil nama Aigis, sambil membentangkan kedua tangannya ke arah langit."
  },
  AvgDialog_18912_Content_56 = {
    Text = "Seekor burung terbang melintasi langit malam, hilang dalam kabut tebal, tanpa meninggalkan jejak."
  },
  AvgDialog_18912_Content_57 = {
    Text = "Pita satin yang terikat di tangan terlepas dan tertiup angin, tubuh kecil gadis itu jatuh ke dalam kegelapan malam ini, menghilang selamanya dari langit malam ini."
  },
  AvgDialog_18912_Content_58 = {
    Text = "Gaun putih kosong bersama dengan lembaran kertas kotak yang berserakan secara lembut jatuh ke tangan Jenkin."
  },
  AvgDialog_18912_Content_59 = {
    Text = "Tak ada sedikit pun kehangatan yang tersisa."
  },
  AvgDialog_18912_Content_6 = {
    Text = "Terima kasih… meskipun hanya sejenak, aku… ada sesuatu yang ingin aku sampaikan kepada mereka."
  },
  AvgDialog_18912_Content_60 = {
    Text = "Ai... Aigis...?"
  },
  AvgDialog_18912_Content_61 = {
    Text = "Di atas kertas terdapat gambar kupu-kupu emas, tepi yang berkerut telah diratakan dan dilipat dengan hati-hati, bahkan masih membawa aroma manis permen."
  },
  AvgDialog_18912_Content_62 = {
    Text = "Bagaimana... bagaimana mungkin..."
  },
  AvgDialog_18912_Content_63 = {
    Text = "Pita merah tua jatuh ke tangan gadis itu bersamaan dengan bungkus permen. Pita itu menyentuh ujung jarinya dengan lembut, seperti sebuah penghiburan hangat yang diberikan oleh seseorang."
  },
  AvgDialog_18912_Content_64 = {
    Text = "Gadis itu berkedip, air mata yang mengaburkan pandangannya jatuh dari bulu matanya dan diam-diam ditampung oleh warna merah yang mencolok."
  },
  AvgDialog_18912_Content_65 = {Text = "Aigis…"},
  AvgDialog_18912_Content_7 = {
    Text = "Aigis, Aigis!"
  },
  AvgDialog_18912_Content_8 = {
    Text = "Aigis bergerak sedikit dan benar-benar membuka matanya."
  },
  AvgDialog_18912_Content_9 = {
    Text = "Setelah terdengar jeritan melengkung yang menyayat, tubuh raksasa monster itu meleleh menjadi cairan hitam kental, kemudian runtuh ke bawah. Cairan tersebut berubah menjadi debu dan melayang ke atas, menghitamkan balok kayu di langit-langit."
  },
  AvgDialog_18913_Content_1 = {
    Text = "Akhirnya, kalian berhasil mengejar gadis itu. Aigis telah kalian kuasai bersama-sama. Kamu segera mengulurkan tangan untuk meraih lengannya, sementara satu tangan lainnya menekan Kunci perak, bersiap untuk menyelesaikan Tautan."
  },
  AvgDialog_18913_Content_10 = {
    Text = "Tidak akan, tidak akan, Aigis, kamu harus percaya pada kami. Universitas Mythag pernah menghadapi situasi yang jauh lebih berbahaya daripada ini…"
  },
  AvgDialog_18913_Content_11 = {
    Text = "Benarkah? Ogier... Lihat tubuh mereka."
  },
  AvgDialog_18913_Content_12 = {
    Text = "Ogier memutar kepalanya untuk melihat Penjaga dan Ramona yang masih bertahan.\nDi permukaan tubuh mereka, keringat berwarna aneh mulai meresap keluar — itu bukan keringat, melainkan sirup kental yang halus."
  },
  AvgDialog_18913_Content_13 = {
    Text = "Setelah suara Tuan Anderson menghilang, warna di mataku dan tubuhku secara bertahap menjadi tidak terkendali. Bahkan tanpa melihat dengan mata, orang-orang di sekitarku perlahan-lahan akan berubah menjadi batu yang tak bisa bergerak."
  },
  AvgDialog_18913_Content_14 = {
    Text = "Berapa lama lagi aku bisa bertahan? Satu tahun, satu bulan, satu hari, satu jam?"
  },
  AvgDialog_18913_Content_15 = {
    Text = "Apakah aku harus selalu bersembunyi di belakang semua orang, menunggu hingga segala sesuatu yang tersisa tak dapat diselamatkan lagi, baru mengambil tindakan?"
  },
  AvgDialog_18913_Content_16 = {
    Text = "Kali ini, aku ingin menjadi seberani Tiyug, seberani Jenkin, dan seberani kamu."
  },
  AvgDialog_18913_Content_17 = {
    Text = [[
Ogier, bukankah kamu seorang ksatria? Jika iya, kamu seharusnya mengerti. 
Meskipun aku tetap tinggal, aku pasti akan menjadi orang berdosa yang diadili oleh para ksatria.]]
  },
  AvgDialog_18913_Content_18 = {
    Text = "Ogier tercengang."
  },
  AvgDialog_18913_Content_19 = {
    Text = "Ogier, kau pernah berkata... apakah aku bisa mendapatkan penebusan, itu tergantung pada diriku sendiri."
  },
  AvgDialog_18913_Content_2 = {
    Text = "Jangan seperti ini, aku mohon… \n Aku tahu…"
  },
  AvgDialog_18913_Content_20 = {
    Text = "Sekarang… bisakah kau menatapku, menatap jiwaku… apakah jiwa ini bisa diselamatkan."
  },
  AvgDialog_18913_Content_21 = {
    Text = "Ogier menatap satu-satunya murid normal Aigis, setelah ragu sejenak, dia melepaskan tangannya dengan khidmat."
  },
  AvgDialog_18913_Content_22 = {
    Text = "Seiring dengan gerakannya, Aigis terlepas dari kontrol Tautanmu."
  },
  AvgDialog_18913_Content_23 = {
    Text = "Dalam sekejap, tubuh gadis itu membesar dengan cepat, daging dan kulitnya seperti mendidih, membentuk tonjolan-tonjolan bulat berbagai ukuran. Tak lama kemudian, tubuhnya telah menutupi tangga saat ini dan menyentuh langit-langit yang tinggi."
  },
  AvgDialog_18913_Content_24 = {
    Text = "Dalam suara mengerikan dari tubuh yang terpuntir dan membungkuk, hanya tersisa sedikit suara gadis itu."
  },
  AvgDialog_18913_Content_25 = {
    Text = "<Shake: Cepat... lari...>"
  },
  AvgDialog_18913_Content_3 = {
    Text = "Kamu ditarik ke dalam kegelapan."
  },
  AvgDialog_18913_Content_4 = {
    Text = "Gelap yang panas dan menyala-nyala, seperti sirup cair yang meleleh, melilit tubuhmu dan mengikatmu dengan kuat di dalamnya."
  },
  AvgDialog_18913_Content_5 = {
    Text = "<Italic:Charlie tua memiliki seekor kucing belang yang sangat dia cintai…>"
  },
  AvgDialog_18913_Content_6 = {
    Text = "Rasa sakit menjalar dari permukaan tubuh, awalnya seperti gigitan semut, lalu perlahan menjadi semakin kuat, seperti ribuan jarum menembus setiap inci kulitmu secara bersamaan——"
  },
  AvgDialog_18913_Content_7 = {
    Text = "Tautan putus dengan sangat kuat."
  },
  AvgDialog_18913_Content_8 = {
    Text = "Kamu menahan rasa sakit yang luar biasa, tangan kirimu memegang kunci perak, gemetar saat kamu meletakkan tangan kananmu kembali di lengan Aigis."
  },
  AvgDialog_18913_Content_9 = {
    Text = "Tidak ada waktu..."
  },
  AvgDialog_18914_Content_1 = {
    Text = "Di tubuh monster-monster ini, ada D-marka. Dan… seolah-olah dijahitkan ke tubuhnya."
  },
  AvgDialog_18914_Content_2 = {
    Text = "Ramona mengetuk pin di dadanya dua kali."
  },
  AvgDialog_18914_Content_3 = {
    Text = "Erica, cari \"D-marka Pelarutan jahitan\"."
  },
  AvgDialog_18914_Content_4 = {
    Text = [[
Kata kunci berhasil dibaca, "Pelarutan dengan jahitan", total 37 Acara terkait. 
Kata kunci Acara: Tindakan jaringan ganas, <Blue:Para pematung>.]]
  },
  AvgDialog_18914_Content_5 = {
    Text = "Para pematung?"
  },
  AvgDialog_18914_Content_6 = {
    Text = "Itu adalah sekelompok orang gila yang menyebut diri mereka \"Pigmalion\", terobsesi dengan <Red:modifikasi biologis>… Di luar kota Londinium, Mythag telah beberapa kali bentrok dengan mereka."
  },
  AvgDialog_18914_Content_7 = {
    Text = "Tangan mereka sudah merambah ke Timur, berhati-hatilah… waspadai mereka yang <Yellow:memegang pisau kecil>."
  },
  AvgDialog_18915_Content_1 = {
    Text = "Ogier menghadapi beberapa Dokter, tetap tidak takut sedikit pun, bergerak ke kiri dan kanan dengan gesit, secara cerdik melepaskan kekuatan mereka, dan bertahan selama setengah jam."
  },
  AvgDialog_18915_Content_10 = {
    Text = "Ayo segera bereskan, nanti aku akan mengantarmu ke klinik secara pribadi… dan juga Mikro, dia juga sudah lama tidak diperiksa."
  },
  AvgDialog_18915_Content_11 = {
    Text = "Semoga Tuan Rogers bersedia memberi tahu saya alamat mereka."
  },
  AvgDialog_18915_Content_12 = {
    Text = "Tidak! Kumohon, Nona Sarah, kami tidak mau pergi untuk sembuh."
  },
  AvgDialog_18915_Content_13 = {
    Text = "Aigis mendorong anak kecil yang ia lindungi. Anak itu dengan polos memandang semua orang, dan akhirnya memutuskan untuk mendengarkan kata-kata Kakak Aigis, lalu berlari kembali ke dalam ruangan panti asuhan."
  },
  AvgDialog_18915_Content_14 = {
    Text = "Mik kecil! Kembalilah!"
  },
  AvgDialog_18915_Content_15 = {
    Text = "Aigis buru-buru menarik ujung baju Sarah, menghentikannya untuk mengejar Xiao Maike yang sudah menghilang dari pandangan."
  },
  AvgDialog_18915_Content_16 = {
    Text = "Jika... jika memang harus pergi ke klinik, kali ini biarkan aku sendiri..."
  },
  AvgDialog_18915_Content_17 = {
    Text = "Nyonya Sarah."
  },
  AvgDialog_18915_Content_18 = {
    Text = "Ada apa, Tuan Muda Ash?"
  },
  AvgDialog_18915_Content_19 = {
    Text = "Sarah segera mengganti topengnya dengan senyuman yang penuh kepalsuan."
  },
  AvgDialog_18915_Content_2 = {Text = "Cukup."},
  AvgDialog_18915_Content_20 = {
    Text = "Dengan nama Ogier, ksatria dari Yang Mulia, aku memerintahkanmu untuk tidak memaksa Aigis menerima \"Sembuh\"."
  },
  AvgDialog_18915_Content_21 = {
    Text = "Naik, Ksatria?"
  },
  AvgDialog_18915_Content_22 = {
    Text = "Ogier menyadari bahwa dia telah mengatakan sesuatu yang seharusnya tidak diungkapkan. Wajahnya langsung memerah, lalu dia melanjutkan dengan terbata-bata."
  },
  AvgDialog_18915_Content_23 = {
    Text = [[
Ya, ya, putra bungsu keluarga Mulia akan dianugerahi gelar "Ksatria". 
 Pokoknya, aku akan membawa Aigis dan {Male=Tuan Penjaga Rahasia,Female=Nona Penjaga Rahasia} serta gadis pelayan kembali, jadi jangan menyulitkan dia lagi.]]
  },
  AvgDialog_18915_Content_24 = {
    Text = [[
Sambil berbicara, Ogier menarik tangan Aigis dan berlari kembali ke kamar. 
 Gadis itu terus menundukkan kepalanya, tampaknya sedang menangis pelan.]]
  },
  AvgDialog_18915_Content_25 = {
    Text = "Baiklah, Nona Sarah seharusnya tidak akan mengejar lagi."
  },
  AvgDialog_18915_Content_26 = {
    Text = "Aigis, bisakah kamu memberitahuku, kenapa kamu tidak mau menerima sembuh dan juga tidak ingin orang lain menerimanya?"
  },
  AvgDialog_18915_Content_27 = {
    Text = "Aigis erat menahan bibirnya, dan dari tenggorokannya terdengar isakan tertahan."
  },
  AvgDialog_18915_Content_28 = {
    Text = "Kamu tidak perlu khawatir, aku benar-benar seorang ksatria. Seorang ksatria pasti akan melindungimu."
  },
  AvgDialog_18915_Content_29 = {Text = "Benar!"},
  AvgDialog_18915_Content_3 = {
    Text = [[
Karena Aigis tidak bersedia, kami tidak akan memaksanya. 
Kami akan membawa pasien lain yang terpilih kembali ke klinik untuk disembuhkan, setelah proses penyembuhan selesai, mereka akan dikembalikan.]]
  },
  AvgDialog_18915_Content_30 = {
    Text = [[
Ogier tergagap, berusaha keras untuk terlihat khidmat dan serius. 
 Aigis menatapnya, ragu selama beberapa saat, lalu akhirnya tertawa terkekeh.]]
  },
  AvgDialog_18915_Content_31 = {
    Text = [[
Jangan membohongiku, aku pernah membaca di buku bahwa kesatria selalu melindungi putri. 
Lihat aku seperti ini, mana mungkin aku mirip seorang putri.]]
  },
  AvgDialog_18915_Content_32 = {
    Text = "Aigis membelai tambalan di ujung roknya, berbicara dengan suara pelan."
  },
  AvgDialog_18915_Content_33 = {
    Text = [[
Bukan seperti itu, buku tersebut salah. 
Ksatria tidak hanya melindungi putri, tetapi juga melindungi masyarakat umum, melindungi semua orang.]]
  },
  AvgDialog_18915_Content_34 = {
    Text = "Aigis mengamati Ogier dari atas ke bawah."
  },
  AvgDialog_18915_Content_35 = {
    Text = "Apakah kamu benar-benar seorang ksatria?"
  },
  AvgDialog_18915_Content_36 = {
    Text = "Ogier menepuk dadanya, pelindung tangannya berbenturan dengan dada, membuat ekspresinya sedikit berubah selama setengah detik."
  },
  AvgDialog_18915_Content_37 = {
    Text = "Benar-benar asli! Saya secara pribadi dianugerahi oleh keluarga kerajaan, dan sejak saat itu, saya dilahirkan untuk melindungi."
  },
  AvgDialog_18915_Content_38 = {
    Text = "Benar-benar iri padamu, begitu berani… bahkan bisa melindungi orang yang baru dikenal."
  },
  AvgDialog_18915_Content_39 = {
    Text = "Sayangnya, aku bukan ksatria, juga bukan putri, bahkan tidak bisa dianggap sebagai rakyat biasa, hanya seorang yang menyedihkan…"
  },
  AvgDialog_18915_Content_4 = {
    Text = "Selamat siang, Nona Sarah."
  },
  AvgDialog_18915_Content_40 = {
    Text = "Nada akhirnya tertelan kembali."
  },
  AvgDialog_18915_Content_41 = {
    Text = "Ogier, kau berkata bahwa ksatria akan melindungi semua orang…"
  },
  AvgDialog_18915_Content_42 = {
    Text = "Bagaimana dengan pelaku kejahatan? Bahkan... pembunuh?"
  },
  AvgDialog_18915_Content_43 = {
    Text = "Ogier membusungkan dadanya, berbicara dengan tegas tanpa sedikit pun ragu."
  },
  AvgDialog_18915_Content_44 = {
    Text = [[
Ksatria tidak akan melindungi pelaku kejahatan. 
 Karena ksatria perlu menghukum pelaku kejahatan dan melindungi masyarakat dari tangan mereka.]]
  },
  AvgDialog_18915_Content_45 = {
    Text = "Ternyata……"
  },
  AvgDialog_18915_Content_46 = {
    Text = "Tidak memahami makna dalam keluhan pelan Aigis, Ogier melanjutkan ucapannya."
  },
  AvgDialog_18915_Content_47 = {
    Text = "Itu karena, ksatria tidak bisa melakukan segalanya."
  },
  AvgDialog_18915_Content_48 = {
    Text = "Setelah hukuman… ksatria akan menyerahkan orang yang bertobat kepada imam."
  },
  AvgDialog_18915_Content_49 = {
    Text = "Pastor yang penuh belas kasih akan membantu setiap orang yang bertobat… tetapi apakah Jiwa mereka pada akhirnya akan mendapatkan penebusan, itu tergantung pada diri mereka sendiri."
  },
  AvgDialog_18915_Content_5 = {
    Text = "Vik melirik Aigis sekali lagi, lalu pergi bersama yang lainnya."
  },
  AvgDialog_18915_Content_50 = {
    Text = "Tergantung pada… diri sendiri…"
  },
  AvgDialog_18915_Content_51 = {
    Text = "Ya, masih ada ruang untuk berbalik."
  },
  AvgDialog_18915_Content_52 = {
    Text = "Semua ini ada hubungannya denganmu@4…"
  },
  AvgDialog_18915_Content_53 = {
    Text = [[
Aigis terkejut sejenak, tampaknya ia sedang merenungkan kalimat itu. 
 Setelah beberapa saat, dia perlahan-lahan dan dengan agak sulit mulai berbicara.]]
  },
  AvgDialog_18915_Content_54 = {
    Text = "Saya percaya padamu, Ogier. Saya bersedia mengambil risiko untukmu sekali lagi. \nJadi, saya akan memberi tahu Anda…… kebenaran tentang penyembuhan."
  },
  AvgDialog_18915_Content_6 = {
    Text = "Sarah dengan senyum meminta maaf mengantarkan Dokter pergi. Saat berbalik ke arah Aigis, wajahnya dipenuhi dengan keseriusan."
  },
  AvgDialog_18915_Content_7 = {
    Text = "Aigis, mengapa kamu begitu tidak patuh?"
  },
  AvgDialog_18915_Content_8 = {
    Text = "Nyonya Sarah, saya..."
  },
  AvgDialog_18915_Content_9 = {
    Text = "Mereka datang karena menghormati Tuan Rogers, dan sekarang bagus sekali, kau berhasil membuat mereka pergi. Bagaimana aku harus menjelaskan ini kepada Tuan Rogers?"
  },
  AvgDialog_18916_Content_1 = {
    Text = "Monster itu lenyap tanpa suara, berubah menjadi asap hitam."
  },
  AvgDialog_18916_Content_10 = {
    Text = "Jika aku dianggap sebagai monster, lalu apa sebenarnya makhluk ini?"
  },
  AvgDialog_18916_Content_11 = {
    Text = "Dia merespons dengan lembut membelai dagu patung itu, lalu dengan lembut menyentuh punggung tanganmu."
  },
  AvgDialog_18916_Content_12 = {
    Text = "Kamu terperangkap dalam ilusi lautan."
  },
  AvgDialog_18916_Content_13 = {
    Text = "Batu hijau aneh yang sepenuhnya bertentangan dengan geometri Euclidean membentuk kota raksasa yang megah. Ukiran-ukiran indah namun tidak suci membiaskan cahaya laut, terlihat memesona dan aneh hingga membuat pandangan menjadi pusing."
  },
  AvgDialog_18916_Content_14 = {
    Text = "Rasa sesak secara bertahap membungkus dan menelanmu. Udara yang paling berharga terdesak keluar dari paru-paru, mengalir melalui mulut."
  },
  AvgDialog_18916_Content_15 = {
    Text = "——Kemudian, seseorang menarikmu dengan kuat, membebaskanmu dari fatamorgana."
  },
  AvgDialog_18916_Content_16 = {
    Text = "Penjaga Rahasia!"
  },
  AvgDialog_18916_Content_17 = {
    Text = "Jangan khawatir, itu hanya sedikit fatamorgana."
  },
  AvgDialog_18916_Content_18 = {
    Text = "Apa yang ingin kamu katakan dengan menunjukkan ini kepadaku?"
  },
  AvgDialog_18916_Content_19 = {
    Text = "Sanga menundukkan pandangannya, tanpa memberikan jawaban."
  },
  AvgDialog_18916_Content_2 = {Text = "Hu——"},
  AvgDialog_18916_Content_20 = {
    Text = "Pikiranmu berkecamuk, isi pengajaran kelas persiapan Bangun muncul di benakmu."
  },
  AvgDialog_18916_Content_21 = {
    Text = "<Yellow:Aequor>, <Yellow:Caro>, <Yellow:Ultra> adalah klasifikasi utama di kalangan akademik untuk alam Pembangun. Selain itu, ada juga beberapa alam yang kurang dipelajari karena jumlah individunya terlalu sedikit, seperti <Yellow:Magika>, <Yellow:Aether>, dan lain-lain…"
  },
  AvgDialog_18916_Content_22 = {
    Text = "Di antara alam, kekuatan biasanya memiliki isolasi alami, tetapi ada juga <Yellow:Alam Kekacauan> yang dapat beradaptasi dengan kemampuan alam lain."
  },
  AvgDialog_18916_Content_23 = {
    Text = "Suara terbata-bata Jenkin memutus kenanganmu, dia berlari di antara patung-patung gula di basement, mirip sekali dengan tikus kecil yang kebingungan."
  },
  AvgDialog_18916_Content_24 = {
    Text = "Saya sudah memeriksa semuanya, saya mengecek semua wajah mereka."
  },
  AvgDialog_18916_Content_25 = {
    Text = [[
Di dalam tidak ada kakak. 
<Big:Dimana kakakku sebenarnya, katakanlah!>]]
  },
  AvgDialog_18916_Content_26 = {
    Text = "Ramona mengakhiri komunikasi dengan pihak sekolah, memutus kenanganmu dengan suara yang dingin seperti es."
  },
  AvgDialog_18916_Content_27 = {
    Text = "Tidak diragukan lagi, kamu adalah Pembangun yang tidak terdaftar. Berdasarkan <Yellow:ketentuan terkait dalam 《Perjanjian Mystia》,> kami akan memberitahu <Blue:Komite Perjanjian Mystia> untuk menampungmu."
  },
  AvgDialog_18916_Content_28 = {
    Text = "Sebelum kedatangan Komite, harap sampaikan semua keberadaan orang hilang termasuk <Blue:Penyelidik Mythag Shaun Anderson> dan <Blue:Pekerja Pabrik Meison>, serta hubunganmu dengan <Blue:Para Pematung>."
  },
  AvgDialog_18916_Content_29 = {
    Text = "Tunggu sebentar, Ramona, Jenkin."
  },
  AvgDialog_18916_Content_3 = {
    Text = "Hantu itu menghela napas pelan, meniupkan sisa-sisa bubuk gula yang menempel di pahat ukir."
  },
  AvgDialog_18916_Content_30 = {
    Text = "Kamu mengangkat tangan untuk menghentikan pertanyaan dari dua orang itu, lalu berbalik ke arah Sanga yang tampak seperti tersenyum namun tidak."
  },
  AvgDialog_18916_Content_31 = {
    Text = "Apakah kamu bukan orang yang membuat orang-orang ini menjadi seperti ini?"
  },
  AvgDialog_18916_Content_32 = {Text = "%player%?"},
  AvgDialog_18916_Content_33 = {
    Text = "Kamu memperlihatkan padaku ilusi, pemandangan yang terdiri dari dasar laut dan ukiran karang… itu adalah kekuatan dari kedalaman laut dan mimpi, yaitu <Yellow:alam laut dalam>."
  },
  AvgDialog_18916_Content_34 = {
    Text = "Kamu melihat sekelilingmu, dipenuhi oleh permen-permen yang bergerak dengan wajah mengerikan. Kamu menarik napas dalam-dalam, dan aroma manis yang memenuhi rongga hidungmu kembali menghantam ubun-ubunmu."
  },
  AvgDialog_18916_Content_35 = {
    Text = [[
Dan tubuh-tubuh ini, setelah dicairkan menjadi sirup, kemudian mengeras menjadi patung... 
 Kemampuan seperti ini lebih mirip hasil karya <Yellow:Caro Alam Pembangun>, mereka biasanya lebih ahli dalam perubahan daging.]]
  },
  AvgDialog_18916_Content_36 = {
    Text = "Mungkin kamu terlibat di dalamnya, tetapi pelaku utamanya pasti orang lain."
  },
  AvgDialog_18916_Content_37 = {
    Text = "Berbicara dengan orang cerdas sungguh membuat hati senang."
  },
  AvgDialog_18916_Content_38 = {
    Text = "Benar, saya mendengar dari seorang teman bahwa di sini terdapat bahan unik yang tidak ada duanya. Saya hanya ingin meminjam sedikit untuk digunakan dalam menciptakan \"dewa\" saya."
  },
  AvgDialog_18916_Content_39 = {
    Text = "Sanga berbicara dengan nada santai, mulai memasukkan pahat-pahat ke dalam bungkusan di samping kakinya."
  },
  AvgDialog_18916_Content_4 = {
    Text = [[
Selesai. 
Namun, hasilnya kali ini masih belum terlalu ideal.]]
  },
  AvgDialog_18916_Content_40 = {
    Text = [[
Ayo pergi, bukankah kita akan ke Komite untuk peninjauan? 
 Bisakah kamu membantu membungkus patung-patung ini juga?]]
  },
  AvgDialog_18916_Content_41 = {
    Text = "Dan juga……"
  },
  AvgDialog_18916_Content_42 = {
    Text = "Dia mengetuk-ngetuk batu yang menjadi tempat duduknya."
  },
  AvgDialog_18916_Content_43 = {
    Text = "Saya agak tidak nyaman bergerak, bisakah kalian mengirimkan mobil dengan izin akses?"
  },
  AvgDialog_18916_Content_44 = {
    Text = "Kamu langsung meraih pergelangan tangannya."
  },
  AvgDialog_18916_Content_45 = {
    Text = "Siapa yang membuat mereka seperti ini?"
  },
  AvgDialog_18916_Content_46 = {
    Text = "Apakah kamu bertanya padaku?"
  },
  AvgDialog_18916_Content_47 = {
    Text = "Sanga menghela napas pelan."
  },
  AvgDialog_18916_Content_48 = {
    Text = [[
Sebaik saya, biar kutunjukkan jalan yang benar. 
Pergilah tanya rektor dan para dokter itu.]]
  },
  AvgDialog_18916_Content_49 = {
    Text = [[
Sarah! Aku tahu, pasti wanita sialan itu yang berbuat ulah! 
 Lihat saja, kali ini aku akan... akan...]]
  },
  AvgDialog_18916_Content_5 = {
    Text = "Dia meletakkan pahat di tangannya, lalu memutar tubuhnya setengah ke arah kalian."
  },
  AvgDialog_18916_Content_50 = {
    Text = "Jenkin awalnya ganas, lalu berubah menjadi muram."
  },
  AvgDialog_18916_Content_51 = {
    Text = "Kamu perlahan maju dan menepuk pundaknya."
  },
  AvgDialog_18916_Content_52 = {
    Text = [[
Orang belum ditemukan bukanlah hal yang buruk, asalkan...
Masih ada secercah harapan untuk berubah.]]
  },
  AvgDialog_18916_Content_53 = {
    Text = [[
Tidak perlu khawatir lagi tentang mengusik ular dalam rumput. 
 Ramona, tolong beritahu Komite untuk turun tangan. Jenkin, panggil Sarah kemari.]]
  },
  AvgDialog_18916_Content_54 = {
    Text = "Bawa buku catatannya."
  },
  AvgDialog_18916_Content_6 = {
    Text = "Apa yang kalian, para tamu tak diundang, cari dariku?"
  },
  AvgDialog_18916_Content_7 = {
    Text = "Kamu, kamu monster!"
  },
  AvgDialog_18916_Content_8 = {
    Text = "Monster? Aku lebih suka kalian memanggilku \"Sanga\"."
  },
  AvgDialog_18916_Content_9 = {
    Text = "Sanga menyapu debu halus dari permukaan gula tanpa mengatakan apa pun."
  },
  AvgDialog_18917_Content_1 = {
    Text = "Nona 24, kenapa kamu langsung menyerang kami begitu mulai?"
  },
  AvgDialog_18917_Content_2 = {
    Text = "Serangan? Tidak, aku tidak akan berkelahi…"
  },
  AvgDialog_18917_Content_3 = {
    Text = "Aku mengerti! Apakah kalian sudah bertemu dengannya?"
  },
  AvgDialog_18917_Content_4 = {
    Text = "Meskipun terdengar konyol, itu bukan diriku yang sebenarnya——"
  },
  AvgDialog_18917_Content_5 = {
    Text = "Tidak, sebenarnya dia juga aku, hanya saja bagian yang lebih tidak normal…"
  },
  AvgDialog_18917_Content_6 = {
    Text = "Tidak, juga tidak benar. Sebenarnya, masih ada aku yang lain... totalnya ada beberapa aku..."
  },
  AvgDialog_18917_Content_7 = {
    Text = "Sialan! Akhirnya menemukan seseorang yang bisa bicara, ternyata orang gila."
  },
  AvgDialog_18918_Content_1 = {
    Text = "Nona 24, ada satu pertanyaan yang selalu menggangguku…"
  },
  AvgDialog_18918_Content_2 = {
    Text = "Bagaimana mungkin kamu bisa merangkak keluar dari patung lilin?"
  },
  AvgDialog_18918_Content_3 = {
    Text = "Saya... maaf, saya merasa sedikit bingung. Akhir-akhir ini, saya selalu merasa linglung."
  },
  AvgDialog_18918_Content_4 = {
    Text = "Saya sebelumnya dijadikan patung lilin, tidak tahu sudah berapa lama ditempatkan di sini..."
  },
  AvgDialog_18918_Content_5 = {
    Text = "Tiba-tiba, sepertinya aku bisa bergerak dan bernapas lagi. Lalu——"
  },
  AvgDialog_18918_Content_6 = {
    Text = "Lalu kamu keluar dari patung lilin seperti hantu perempuan."
  },
  AvgDialog_18918_Content_7 = {Text = "Ya, ya…"},
  AvgDialog_18919_Content_1 = {Text = "Mata..."},
  AvgDialog_18919_Content_2 = {
    Text = "Selalu merasa bahwa mata Tuan Patung Lilin itu agak familiar…"
  },
  AvgDialog_18920_Content_1 = {
    Text = "Aaa, ka-ka-kalian, dari mana kalian muncul!"
  },
  AvgDialog_18920_Content_2 = {
    Text = "Hatsyi! Bau sekali... Orang mati tidak perlu pakai parfum lagi, bisa tidak?"
  },
  AvgDialog_18920_Content_3 = {
    Text = "Kamu... baik, sangat baik..."
  },
  AvgDialog_18920_Content_4 = {
    Text = "Biarkan aku mengajari kamu apa itu etika yang benar!"
  },
  AvgDialog_18921_Content_1 = {
    Text = "4:40, Museum Lilin Rogers"
  },
  AvgDialog_18921_Content_10 = {
    Text = "Berhenti. Apakah kalian tidak melihat? Luka-lukanya sudah menyerap terlalu banyak D-lendir…"
  },
  AvgDialog_18921_Content_11 = {
    Text = "Segera, dia akan bersama dengan museum lilin ini…"
  },
  AvgDialog_18921_Content_12 = {
    Text = "Sialan... nasib buruk, tadi sedikit terkena D-lendir itu."
  },
  AvgDialog_18921_Content_13 = {
    Text = "Jenkin gemetar saat mengulurkan tangannya, di telapak tangannya terdapat kunci yang dapat membuka lorong tersebut."
  },
  AvgDialog_18921_Content_14 = {
    Text = "Kemarilah, Kak."
  },
  AvgDialog_18921_Content_15 = {
    Text = "Jangan bergerak sembarangan, Jenkin! Kamu terluka, aku akan membawamu keluar…"
  },
  AvgDialog_18921_Content_16 = {
    Text = "Kemarilah, Kak."
  },
  AvgDialog_18921_Content_17 = {
    Text = "Lalu buka telapak tanganmu… ya, seperti sekarang ini——"
  },
  AvgDialog_18921_Content_18 = {
    Text = "24 gemetar membuka telapak tangannya, sebuah Kunci jatuh ke telapak tangannya, masih ada sedikit kehangatan tersisa di atasnya."
  },
  AvgDialog_18921_Content_19 = {
    Text = "Kunci ini sudah sangat bersih, aku sudah melakukan yang terbaik…"
  },
  AvgDialog_18921_Content_2 = {
    Text = "Menunggu seolah-olah tak berujung, hingga terdengar suara yang bergerak dengan susah payah dari atas."
  },
  AvgDialog_18921_Content_20 = {
    Text = "Sial. Aku baru berusia tiga belas tahun, belum hidup cukup lama…"
  },
  AvgDialog_18921_Content_21 = {
    Text = "Jenkin berbicara sambil menghirup hidungnya lagi, lalu menunjukkan senyuman cerah kepada kalian."
  },
  AvgDialog_18921_Content_22 = {
    Text = "Kakak, kita belum sempat berbicara dengan baik, dan sekarang kita harus berpisah lagi."
  },
  AvgDialog_18921_Content_23 = {
    Text = "Apakah kamu masih ingat apa yang kamu katakan padaku saat itu?"
  },
  AvgDialog_18921_Content_24 = {
    Text = "Kamu berkata... aku tidak pernah sendirian, aku masih punya kamu, dan juga kalian."
  },
  AvgDialog_18921_Content_25 = {
    Text = "Mulai saat itu, aku sudah tahu…"
  },
  AvgDialog_18921_Content_26 = {
    Text = "Aku bersedia melakukan apa pun, asalkan itu demi kalian."
  },
  AvgDialog_18921_Content_27 = {Text = "Jenkin…"},
  AvgDialog_18921_Content_28 = {
    Text = "Terima kasih, terima kasih kalian semua… Aku masih punya satu permintaan terakhir…"
  },
  AvgDialog_18921_Content_29 = {
    Text = "Jangan lupakan aku, ya."
  },
  AvgDialog_18921_Content_3 = {
    Text = "Suara semakin jelas, semakin besar..."
  },
  AvgDialog_18921_Content_30 = {
    Text = "Lendir hitam yang kental mengalir deras dari belakang gadis itu, membingkai senyumannya yang cerah dalam momen terakhir."
  },
  AvgDialog_18921_Content_31 = {
    Text = "Dia yang suka membuat wajah lucu, dia yang bisa berbicara dengan hewan kecil, dan dia yang selalu berdebat dengan Nyonya Sarah…"
  },
  AvgDialog_18921_Content_32 = {
    Text = "Bersama dengan museum lilin ini, lenyap tanpa suara."
  },
  AvgDialog_18921_Content_4 = {
    Text = "Entah berapa lama telah berlalu, sebuah lengan kurus kecil menjulur keluar dari dalam."
  },
  AvgDialog_18921_Content_5 = {
    Text = "Mengambil, berhasil mendapatkannya..."
  },
  AvgDialog_18921_Content_6 = {
    Text = "Jenkin, cepat keluar! Di sini akan segera runtuh…"
  },
  AvgDialog_18921_Content_7 = {
    Text = "Maaf. Saya mungkin... tidak bisa keluar bersama kalian."
  },
  AvgDialog_18921_Content_8 = {Text = "Ciiit..."},
  AvgDialog_18921_Content_9 = {
    Text = "Jenkin, cepat ulurkan tanganmu."
  },
  AvgDialog_18922_Content_1 = {
    Text = [[
12:25, Museum lilin Rogers
Studio]]
  },
  AvgDialog_18922_Content_10 = {
    Text = "Katakan, Cokelat. Apa yang sebenarnya kamu temui di bawah sana?"
  },
  AvgDialog_18922_Content_11 = {
    Text = "Cuit, uh... cuit-cuit..."
  },
  AvgDialog_18922_Content_12 = {Text = "Hmm, lalu?"},
  AvgDialog_18922_Content_13 = {
    Text = "Cicit cicit cicit cicit…"
  },
  AvgDialog_18922_Content_14 = {
    Text = "Begitu ya. Terima kasih atas kerja kerasnya, Cokelat."
  },
  AvgDialog_18922_Content_15 = {
    Text = "Cokelat mengatakan bahwa di bawah sana terlalu gelap, dia tidak bisa melihat apa pun dengan jelas, hanya sempat membawa ini ke atas."
  },
  AvgDialog_18922_Content_16 = {
    Text = "Jenkin menyingkirkan cakar kecil Cokelat, lalu mengeluarkan sebuah kantong dokumen kecil."
  },
  AvgDialog_18922_Content_17 = {
    Text = "Mari aku lihat apa saja yang ada di dalam... koin kecil, kancing, dan..."
  },
  AvgDialog_18922_Content_18 = {
    Text = "Sebuah surat?"
  },
  AvgDialog_18922_Content_19 = {
    Text = "Oh, biarkan aku melihat apa yang tertulis di atas."
  },
  AvgDialog_18922_Content_2 = {Text = "Cit cit!"},
  AvgDialog_18922_Content_20 = {
    Text = "Hei, jangan sembarangan mengambil barangku!"
  },
  AvgDialog_18922_Content_21 = {
    Text = "Wanita itu membuka surat di tangannya, di mana beberapa kata dan kalimat tertulis dengan coretan yang tidak rapi, tampaknya dibuat dalam keadaan terburu-buru."
  },
  AvgDialog_18922_Content_22 = {
    Text = "Jenkin:\n\nSaya pikir saya tidak akan hidup lama @2\n\nMereka sedang membuat orang menjadi Patung lilin, segera giliran saya @4\n@2 Saya sudah berbicara dengan Tuan Davis @1\n… Anda bisa bekerja di pabriknya nanti.\nTuan Davis memang ketat, tapi makan siang selalu ada sup kacang polong dan roti hitam.\n<Yellow:Ingatlah untuk tidak membantahnya.>\n\nSelain itu, uangnya ada di @4"
  },
  AvgDialog_18922_Content_23 = {
    Text = "Saat membaca bagian akhir surat, wanita itu berhenti."
  },
  AvgDialog_18922_Content_24 = {
    Text = "Di wajahnya muncul ekspresi yang sangat aneh, seolah-olah dia sedang berpikir dengan serius, tetapi juga seakan pikirannya telah melayang jauh ribuan mil."
  },
  AvgDialog_18922_Content_25 = {
    Text = "Masih ada beberapa baris lagi, kenapa berhenti membaca?"
  },
  AvgDialog_18922_Content_26 = {
    Text = "Wanita itu tidak menjawab, hanya dengan lembut meletakkan surat itu di tanganmu."
  },
  AvgDialog_18922_Content_27 = {
    Text = "Kamu membuka surat itu, hanya melihat beberapa sapaan biasa dan tanda tangannya."
  },
  AvgDialog_18922_Content_28 = {
    Text = "\"… hingga sekarang, aku masih merindukan hari-hari kita berjemur di Wood Park bersama.\""
  },
  AvgDialog_18922_Content_29 = {
    Text = "\"Untukmu, Mason.\""
  },
  AvgDialog_18922_Content_3 = {
    Text = "Cokelat, akhirnya kamu kembali!"
  },
  AvgDialog_18922_Content_30 = {
    Text = "Benar-benar bukan ilusi... Kakak benar-benar ada..."
  },
  AvgDialog_18922_Content_31 = {
    Text = "Aku... aku tidak akan bekerja di tempat Davis!"
  },
  AvgDialog_18922_Content_32 = {
    Text = "Nona Mason ternyata ditahan di sini. Dia pasti telah mengambil risiko besar untuk menulis surat ini."
  },
  AvgDialog_18922_Content_33 = {
    Text = "Dia tak pernah menyerah pada harapan untuk hidup, dan juga tidak melupakanmu."
  },
  AvgDialog_18922_Content_34 = {
    Text = "Tapi sekarang, aku bahkan tidak ingat seperti apa wajahnya…"
  },
  AvgDialog_18922_Content_35 = {
    Text = "Aku benar-benar tidak berguna... Maafkan aku, Kak..."
  },
  AvgDialog_18922_Content_36 = {
    Text = "Sebuah tangan terulur, dengan lembut menutupi punggung tangan Jenkin."
  },
  AvgDialog_18922_Content_37 = {
    Text = "Ini adalah tangan yang penuh luka. Di bawah cahaya bulan, pembuluh darah berwarna biru kehitaman dan bekas-bekas luka tampak jelas tanpa bisa tersembunyi."
  },
  AvgDialog_18922_Content_38 = {
    Text = "Jangan menangis, dan jangan mengucapkan maaf."
  },
  AvgDialog_18922_Content_39 = {
    Text = "Ini adalah nasihat yang kau berikan padaku."
  },
  AvgDialog_18922_Content_4 = {
    Text = "Cokelat dengan kelemahan berbaring di pelukan Jenkin, hidungnya berkerut, dan tiba-tiba mulai terisak."
  },
  AvgDialog_18922_Content_40 = {Text = "24..."},
  AvgDialog_18922_Content_41 = {
    Text = "Setidaknya kamu masih hidup sekarang. Selama ada kehidupan, selalu ada harapan."
  },
  AvgDialog_18922_Content_42 = {
    Text = "Saya pikir kakak perempuanmu pasti juga mengharapkan hal yang sama."
  },
  AvgDialog_18922_Content_44 = {
    Text = "Aku... aku tidak menangis."
  },
  AvgDialog_18922_Content_45 = {
    Text = "Kamu ini, kalau tidak gila, sebenarnya cukup normal juga."
  },
  AvgDialog_18922_Content_46 = {
    Text = "Gadis itu menjawab dengan nada murung, dengan sedikit suara hidung yang hampir tak terdeteksi."
  },
  AvgDialog_18922_Content_47 = {
    Text = "Bagaimanapun, kalian akhirnya menemukan jejak keberadaan Mason."
  },
  AvgDialog_18922_Content_48 = {
    Text = "Ini adalah kabar baik yang langka untuk malam ini."
  },
  AvgDialog_18922_Content_5 = {
    Text = "Ciiit... Ciiit——!!"
  },
  AvgDialog_18922_Content_6 = {Text = "Mm-hm..."},
  AvgDialog_18922_Content_7 = {
    Text = "Cokelat mengatakan bahwa bau di bawah sangat tidak sedap, sekarang dia merasa sangat tidak nyaman."
  },
  AvgDialog_18922_Content_8 = {
    Text = "Oh, apakah tikus juga bisa muntah? Ini hal yang cukup baru."
  },
  AvgDialog_18922_Content_9 = {
    Text = "Cokelat bukanlah tikus biasa."
  },
  AvgDialog_18923_Content_1 = {
    Text = "Kalian sudah mencoba segala cara, namun pintu jebakan tetap tidak bergerak sedikit pun."
  },
  AvgDialog_18923_Content_10 = {
    Text = "Operasi kami sudah lama terbongkar, sekarang kedua pintu keluar yang tersisa di museum lilin ini dijaga oleh seseorang."
  },
  AvgDialog_18923_Content_11 = {
    Text = "Saya menemukan sebuah <Yellow:pintu yang bisa mengarah ke luar> di sekitar sini. Pintu itu sangat istimewa karena terkunci dari dalam."
  },
  AvgDialog_18923_Content_12 = {
    Text = "Rogers pasti sudah melakukan sesuatu pada benda ini, metode biasa tidak bisa membukanya."
  },
  AvgDialog_18923_Content_13 = {
    Text = "Kalian harus pergi ke <Yellow:Ruang Kepala Perpustakaan>, khukhukhu, dan mendapatkan sebuah <Yellow:Kunci>…"
  },
  AvgDialog_18923_Content_14 = {
    Text = "Kali ini saya menemukan banyak hal. Catatan keuangan, laporan, kontrak... cukup untuk membuat Rogers menghabiskan sisa hidupnya di penjara."
  },
  AvgDialog_18923_Content_15 = {
    Text = "Untuk berjaga-jaga, aku serahkan dulu kepada kalian, lalu ——"
  },
  AvgDialog_18923_Content_16 = {Text = "Aa——!!"},
  AvgDialog_18923_Content_17 = {
    Text = "Nona yang tadi mengenakan pakaian putih, dia... dia menghilang..."
  },
  AvgDialog_18923_Content_18 = {
    Text = "Kamu menatap tempat di mana wanita itu sebelumnya berada. Di sini kosong, hanya tirai putih yang tersisa berkibar tertiup angin."
  },
  AvgDialog_18923_Content_19 = {
    Text = "Apa artinya menghilang...?"
  },
  AvgDialog_18923_Content_2 = {
    Text = "Sialan, benar-benar tidak bisa dibuka…"
  },
  AvgDialog_18923_Content_20 = {
    Text = "Saya... saya tidak tahu. Baru saja dia masih di sini..."
  },
  AvgDialog_18923_Content_21 = {
    Text = "Jenkin dengan marah bergegas ke arah 24, lalu menarik tangannya."
  },
  AvgDialog_18923_Content_22 = {
    Text = "Kamu, kan... Aku tahu itu kamu. Baru saja aku mendengar kalian berdua berbicara dengan cara yang mencurigakan di sana, dan sekarang kalian berpura-pura tidak saling kenal?"
  },
  AvgDialog_18923_Content_23 = {
    Text = "Tidak, tidak... Nona Jenkin, dengarkan saya! Bukankah polisi juga memerlukan bukti untuk menuduh seorang pelaku..."
  },
  AvgDialog_18923_Content_24 = {
    Text = [[
Tadi kita semua memandangi kakak kelas itu, hanya kamu dan dia yang berdiri di sisi lain. 
 Apakah kamu benar-benar buta dan tuli?]]
  },
  AvgDialog_18923_Content_25 = {
    Text = "Meskipun dia agak aneh, tapi bagaimana jika dia benar-benar kakakku…"
  },
  AvgDialog_18923_Content_26 = {
    Text = "Saya bertanya sekali lagi, ke mana dia pergi?"
  },
  AvgDialog_18923_Content_27 = {
    Text = "Dalam dorongan, 24 terjatuh ke tanah, rambut panjangnya juga tersingkap ke samping."
  },
  AvgDialog_18923_Content_28 = {
    Text = "Apa ini... 0. 2. 4?"
  },
  AvgDialog_18923_Content_29 = {
    Text = "Di leher putih gadis itu, terlihat jelas tato berkode hitam \"024\"."
  },
  AvgDialog_18923_Content_3 = {Text = "Kembali."},
  AvgDialog_18923_Content_30 = {
    Text = "Tidak lama sebelumnya, kalian pernah melihat pola dengan gaya serupa di tempat lain."
  },
  AvgDialog_18923_Content_31 = {
    Text = [[
Lihatlah, mereka akan mengukir kode untuk setiap produk eksperimen yang berhasil. 
Kode yang <Blue:unik> milik kita...]]
  },
  AvgDialog_18923_Content_32 = {
    Text = "Itu adalah... milik Para pematung..."
  },
  AvgDialog_18923_Content_33 = {Text = "?!"},
  AvgDialog_18923_Content_34 = {
    Text = "24 dengan sia-sia menutupi lehernya, wajahnya tampak sangat pucat."
  },
  AvgDialog_18923_Content_35 = {
    Text = "Ternyata… orang ini memang penipu besar! Aku sudah begitu percaya sebelumnya…"
  },
  AvgDialog_18923_Content_36 = {
    Text = "Ternyata begitu, perhatian kita semua teralihkan oleh \"penyakit gila\" Nona 24."
  },
  AvgDialog_18923_Content_37 = {
    Text = "Seseorang yang sangat mengenal museum lilin ini dan dapat bergerak bebas di dalamnya, tentu saja bukan korban biasa."
  },
  AvgDialog_18923_Content_38 = {
    Text = "Tidak, tidak……"
  },
  AvgDialog_18923_Content_39 = {
    Text = "24 duduk di tanah, hanya secara mekanis dan berulang kali menggaruk leher tempat kode itu berada, hingga menjadi luka dan berdarah."
  },
  AvgDialog_18923_Content_4 = {Text = "Apa...?"},
  AvgDialog_18923_Content_40 = {
    Text = "<Shake: Bukan seperti yang kalian pikirkan, bukan seperti yang kalian pikirkan…>"
  },
  AvgDialog_18923_Content_5 = {
    Text = "Aku berkata, \"Pulang.\""
  },
  AvgDialog_18923_Content_6 = {
    Text = "Apa maksudmu, kita susah payah sampai di sini!"
  },
  AvgDialog_18923_Content_7 = {
    Text = "Di bawah sana ada banyak... monster, bukan sesuatu yang bisa kalian tangani. Apakah Boneka belum memperingatkan kalian?"
  },
  AvgDialog_18923_Content_8 = {
    Text = "Lalu bagaimana denganmu? Kami tidak bisa meninggalkanmu begitu saja."
  },
  AvgDialog_18923_Content_9 = {
    Text = "Ada celah kelas B, akan memakan waktu lama untuk menanganinya, jadi aku tidak bisa meninggalkan tempat ini. \n Dengar, aku hanya akan mengatakannya sekali —"
  },
  AvgDialog_18924_Content_1 = {
    Text = "Ssst... Ada orang di depan, cepat bersembunyi."
  },
  AvgDialog_18924_Content_2 = {
    Text = "Bulan malam ini begitu indah~"
  },
  AvgDialog_18924_Content_3 = {
    Text = "Selama aku masih hidup, setiap malam yang indah seperti ini, aku akan duduk di teras yang dilapisi marmer dan menuangkan segelas anggur untuk diriku sendiri…"
  },
  AvgDialog_18924_Content_4 = {
    Text = "Bukannya seperti sekarang, menjadi pelayan di Museum Lilin, huuu…"
  },
  AvgDialog_18924_Content_5 = {
    Text = "Aduh, cerita ini sudah kudengar hampir seratus kali, telingaku sampai mau berkerak!"
  },
  AvgDialog_18924_Content_6 = {
    Text = "Apakah semua barang sudah dimasukkan ke dalam lemari dan dikunci?"
  },
  AvgDialog_18924_Content_7 = {
    Text = "Semuanya sudah dimasukkan, aku sudah memastikannya berkali-kali, lho~"
  },
  AvgDialog_18924_Content_8 = {Text = "Lemari...?"},
  AvgDialog_18924_Content_9 = {
    Text = "Ikuti dan lihat."
  },
  AvgDialog_18925_Content_1 = {
    Text = "Wanita itu terjatuh ke tanah setelah dipukul, dengan bekas darah yang belum sempat dibersihkan di sudut bibirnya."
  },
  AvgDialog_18925_Content_10 = {
    Text = "Oh ya... jika aku tidak menjawab, apakah kalian akan menusukku dengan itu?"
  },
  AvgDialog_18925_Content_11 = {
    Text = "Apakah akan sangat kuat dan menusuk sangat dalam?"
  },
  AvgDialog_18925_Content_12 = {
    Text = "Bisakah, bisakah?"
  },
  AvgDialog_18925_Content_14 = {
    Text = "Jika kamu tidak menjawab pertanyaan, kami tidak hanya tidak akan menusukmu, tetapi juga akan mengabaikanmu dan akhirnya meninggalkan tempat ini."
  },
  AvgDialog_18925_Content_15 = {Text = "Mengerti?"},
  AvgDialog_18925_Content_16 = {
    Text = "Oh... begitu ya..."
  },
  AvgDialog_18925_Content_17 = {
    Text = "<Big:Berhenti, Ramona!>"
  },
  AvgDialog_18925_Content_18 = {
    Text = "Jenkin bergegas mendekati wanita itu, dengan cemas menarik pergelangan tangannya dan menariknya mendekat."
  },
  AvgDialog_18925_Content_19 = {
    Text = "Kakak... apakah kamu adalah kakak?"
  },
  AvgDialog_18925_Content_2 = {
    Text = "Oh, darahmu rasanya sangat aneh... setelah meminumnya, kepala menjadi pening."
  },
  AvgDialog_18925_Content_20 = {Text = "Kakak...?"},
  AvgDialog_18925_Content_21 = {
    Text = "Pandangan mata wanita itu melayang pelan ke arah Jenkin, dan setelah beberapa saat, dia tiba-tiba tersenyum."
  },
  AvgDialog_18925_Content_22 = {
    Text = "Oh ya. Kamu memanggilku Kakak, jadi kamu adalah keluargaku dari masa lalu, ya."
  },
  AvgDialog_18925_Content_23 = {
    Text = "Yang telah mengurungku di bawah tanah selama tiga tahun... tepatnya 1235 hari, keluarga tercinta."
  },
  AvgDialog_18925_Content_24 = {Text = "Apa?!"},
  AvgDialog_18925_Content_25 = {
    Text = "Kamu, kamu berbohong! Bagaimana mungkin aku bisa melakukan hal seperti itu padamu!"
  },
  AvgDialog_18925_Content_26 = {
    Text = "Eh, kenapa tidak mungkin? Aku kan menderita Pelarutan, setelah sakit ini pikiranku penuh dengan darah, berbagai macam darah…"
  },
  AvgDialog_18925_Content_27 = {
    Text = "Kalian takut aku akan memberikan kerusakan pada orang lain, takut aku akan mempermalukan kalian, jadi kalian mengurungku ya~"
  },
  AvgDialog_18925_Content_28 = {
    Text = "Jenkin, apa kau menyembunyikan sesuatu dari kami…"
  },
  AvgDialog_18925_Content_29 = {
    Text = "Wanita itu dengan ringan melompat ke arah Jenkin, lalu mengangkat pergelangan tangannya yang kurus."
  },
  AvgDialog_18925_Content_3 = {
    Text = "Biarkan aku menebak, kamu bukan manusia biasa, juga tidak seperti Pembangun…"
  },
  AvgDialog_18925_Content_30 = {
    Text = "Lihat, di tangan, kaki, bahkan leherku pun ada belenggu."
  },
  AvgDialog_18925_Content_31 = {
    Text = "Saya, saya..."
  },
  AvgDialog_18925_Content_32 = {
    Text = "Kalian memberi saya minum darah tikus selama tiga tahun, hingga tubuh saya menjadi bau tak sedap."
  },
  AvgDialog_18925_Content_33 = {
    Text = "Bagaimana mungkin aku bisa melakukan hal seperti itu kepada kakak, dia itu, dia itu..."
  },
  AvgDialog_18925_Content_34 = {
    Text = "Dia adalah keluargaku!"
  },
  AvgDialog_18925_Content_35 = {
    Text = "Jenkin memerah wajahnya, menggenggam kedua tinjunya dengan erat, dan tanpa gentar menatap balik wanita itu."
  },
  AvgDialog_18925_Content_36 = {
    Text = "...keluarga?"
  },
  AvgDialog_18925_Content_37 = {
    Text = "Sepertinya tidak menyangka tanggapan dari Jenkin, wanita yang sebelumnya terus berisik akhirnya diam."
  },
  AvgDialog_18925_Content_39 = {
    Text = "Barusan aku hanya bercanda denganmu, tikus kecil."
  },
  AvgDialog_18925_Content_4 = {
    Text = "Ramona berdiri di antara kalian, memandang wanita itu dengan kerut di dahi."
  },
  AvgDialog_18925_Content_40 = {
    Text = "Aku tidak memiliki keluarga, apalagi menjadi kakakmu. Kalian salah orang."
  },
  AvgDialog_18925_Content_5 = {
    Text = "Siapa kamu? Kenapa kamu ada di sini?"
  },
  AvgDialog_18925_Content_6 = {
    Text = "Namun, tidak apa-apa. Saya sudah seminggu tidak makan, terima kasih atas keramahan Anda…"
  },
  AvgDialog_18925_Content_7 = {
    Text = "Ramona mengeluarkan pedang tipis dan meletakkannya di dada wanita itu."
  },
  AvgDialog_18925_Content_8 = {
    Text = "Saya hanya akan bertanya sekali."
  },
  AvgDialog_18925_Content_9 = {
    Text = "Wanita itu menatap mata pisaunya yang mengarah padanya, matanya berkilau sesaat, lalu tiba-tiba dia meluruskan tubuhnya."
  },
  AvgDialog_18926_Content_1 = {
    Text = "Hmm! Lorong ini benar-benar sempit, lututku juga terluka…"
  },
  AvgDialog_18926_Content_2 = {
    Text = "Cicit... Hiks... (Jenkin kecil mengeluarkan banyak darah... Huhuhu...)"
  },
  AvgDialog_18926_Content_3 = {
    Text = "Luka kecil ini tidak apa-apa. Apakah kamu melihat pintu keluar di depan sana? Lompat saja, itu akan membawamu ke ruang pengelola!"
  },
  AvgDialog_18927_Content_2 = {
    Text = "Sial sekali, Cokelat. Saya khawatir… tidak akan bisa keluar dari sini hidup-hidup."
  },
  AvgDialog_18927_Content_3 = {
    Text = "Cik... cik cik. (Jenkin kecil... kamu pasti merasa sangat tersiksa sekarang.)"
  },
  AvgDialog_18927_Content_4 = {
    Text = "Ck, ckck? Ckck. (Bisakah bertahan sebentar lagi, hanya sebentar? Pintu keluar sudah di depan sana ck.)"
  },
  AvgDialog_18927_Content_5 = {
    Text = "Saya, saya tidak tahu… Sepertinya ada sesuatu yang terbakar di tubuh saya…"
  },
  AvgDialog_18927_Content_6 = {
    Text = "Sangat tidak nyaman, pikiran juga kacau... di mana-mana lengket..."
  },
  AvgDialog_18927_Content_7 = {
    Text = "Aku belum mau mati..."
  },
  AvgDialog_18927_Content_8 = {
    Text = "Cicit, cicit cicit. (Ikut aku, Jenkin kecil. Aku akan membawamu keluar.)"
  },
  AvgDialog_18928_Content_1 = {
    Text = "Barusan sepertinya terkena sesuatu yang lengket..."
  },
  AvgDialog_18928_Content_2 = {Text = "?!"},
  AvgDialog_18928_Content_3 = {
    Text = "Mungkin hanya perasaan salah... Ha, haha."
  },
  AvgDialog_18929_Content_1 = {
    Text = "Jadi, bagaimana kamu berhasil meyakinkan Boneka?"
  },
  AvgDialog_18929_Content_2 = {
    Text = "Sangat sederhana. Kita bisa berpura-pura menjadi pengunjung di Museum Lilin."
  },
  AvgDialog_18929_Content_3 = {
    Text = "Pertama-tama, selidiki situasinya. Begitu menemukan masalah, segera tarik diri."
  },
  AvgDialog_18930_Content_1 = {
    Text = "Apakah berakting itu menyenangkan?"
  },
  AvgDialog_18930_Content_2 = {
    Text = "...Saya tidak mengerti maksudmu."
  },
  AvgDialog_18930_Content_3 = {
    Text = "Jangan tegang... Aku hanya penasaran saja, tidak akan membongkarnya."
  },
  AvgDialog_18930_Content_4 = {
    Text = "Kalau begitu, aku @1. Kamu tidak akan mengatakan apa pun, kan?"
  },
  AvgDialog_18930_Content_5 = {Text = "Tunggu…!"},
  AvgDialog_18930_Content_6 = {Text = "Ssst……"},
  AvgDialog_18931_Content_1 = {
    Text = "Melankoli Pembedahan"
  },
  AvgDialog_18931_Content_10 = {
    Text = "Kamu ini terus berpura-pura bodoh dan mengikuti kami, bahkan ingin mencelakai kakakku... Bukan, mencelakai seseorang yang mirip kakakku…"
  },
  AvgDialog_18931_Content_11 = {
    Text = "Pasti orang dari asosiasi aneh itu yang menyuruhmu menjadi mata-mata!"
  },
  AvgDialog_18931_Content_14 = {
    Text = "Aaa—!! Kenapa tidak mau mendengarkan penjelasanku?!"
  },
  AvgDialog_18931_Content_15 = {
    Text = "Menghadapi pertanyaan bertubi-tubi dari kalian, 24 tiba-tiba memegang kepalanya dan berteriak keras."
  },
  AvgDialog_18931_Content_16 = {
    Text = "Dengarkan penjelasanku, @2 dengarkan aku menjelaskan ah ah ah——！！"
  },
  AvgDialog_18931_Content_17 = {
    Text = "<SmallShake: Dengar, aku akan mendengarkan... kenapa gila lagi...>"
  },
  AvgDialog_18931_Content_18 = {
    Text = "24 terus-menerus bernapas dengan berat, urat-urat di wajahnya menonjol."
  },
  AvgDialog_18931_Content_19 = {
    Text = "Hei, pembuluh darah di wajahmu…"
  },
  AvgDialog_18931_Content_2 = {
    Text = "Dengarkan penjelasanku, sebenarnya aku dipaksa! Saat itu, aku yang mendorongmu…"
  },
  AvgDialog_18931_Content_20 = {
    Text = "Hehe... benar, tatapan seperti inilah. Aku melihat..."
  },
  AvgDialog_18931_Content_21 = {Text = "Ketakutan."},
  AvgDialog_18931_Content_22 = {Text = "Jijik."},
  AvgDialog_18931_Content_23 = {
    Text = "<RedShake:Monster. Monster. Makhluk buruk rupa yang ditinggalkan seperti saya…>"
  },
  AvgDialog_18931_Content_24 = {
    Text = "<RedShake:Tidak ada yang mendekati aku, tidak ada yang mempercayai aku…>"
  },
  AvgDialog_18931_Content_25 = {
    Text = "Lengan berwarna merah tua sekali lagi tumbuh dari tubuh 24, dengan kuat melilit lehernya."
  },
  AvgDialog_18931_Content_26 = {
    Text = "<RedShake: Aku bukan monster, aku bukan monster…>"
  },
  AvgDialog_18931_Content_27 = {
    Text = "Astaga, dia mulai bertingkah aneh lagi. Cepat tinggalkan tempat ini!"
  },
  AvgDialog_18931_Content_28 = {
    Text = "Aku bukan @1 monster... Ah @2 ah!"
  },
  AvgDialog_18931_Content_3 = {
    Text = "Ternyata kau yang mendorongnya? Bagus... kau sangat jujur, mengakui semuanya!"
  },
  AvgDialog_18931_Content_4 = {
    Text = "Saya tahu kalian sangat hebat. Jadi, saya memutuskan untuk bekerja sama dengan kalian setelah itu..."
  },
  AvgDialog_18931_Content_5 = {
    Text = "Kamu hanya perlu menjawab satu pertanyaan, Nona 24. Apakah kamu yang membiarkannya pergi?"
  },
  AvgDialog_18931_Content_6 = {Text = "!!"},
  AvgDialog_18931_Content_7 = {
    Text = "Apakah ini juga terpaksa?"
  },
  AvgDialog_18931_Content_8 = {
    Text = "Sebenarnya……"
  },
  AvgDialog_18931_Content_9 = {
    Text = "Tunggu sebentar. Apakah kau benar-benar mengira kami masih akan mempercayai omong kosongmu?"
  },
  AvgDialog_18932_Content_1 = {
    Text = "To……tolong aku……"
  },
  AvgDialog_18932_Content_2 = {
    Text = "Tidak, bunuh aku saja…"
  },
  AvgDialog_18932_Content_3 = {Text = "...?"},
  AvgDialog_18933_Content_1 = {Text = "Ugh!!"},
  AvgDialog_18933_Content_2 = {
    Text = "Eh, sepertinya orang itu terjatuh?"
  },
  AvgDialog_18933_Content_3 = {
    Text = "Lihat dulu."
  },
  AvgDialog_18934_Content_1 = {
    Text = "Kalian lari duluan, aku akan menutup belakang... A-aku tidak takut padanya!"
  },
  AvgDialog_18934_Content_2 = {
    Text = "...Kamu jangan gemetar dulu. Patuhlah, sembunyilah di belakangku."
  },
  AvgDialog_18935_Content_1 = {
    Text = "Rumah Boneka"
  },
  AvgDialog_18935_Content_10 = {Text = "Mama……"},
  AvgDialog_18935_Content_11 = {
    Text = "Sepertinya kamu semakin terbiasa berinteraksi dengan \"Ibu\"."
  },
  AvgDialog_18935_Content_12 = {
    Text = "… lilin, lilin. Patung lilin."
  },
  AvgDialog_18935_Content_13 = {
    Text = "Indah sekali, bukan? Bukan ini penampilan aslinya."
  },
  AvgDialog_18935_Content_14 = {
    Text = "Dia semasa hidupnya adalah seorang penyanyi jalanan, namun naas terkena penyakit menular, seluruh tubuhnya dipenuhi dengan bekas luka dan bengkak berwarna merah."
  },
  AvgDialog_18935_Content_15 = {
    Text = "Aku melihatnya dipukul hingga tewas, jatuh di depanku. Lalu aku membawanya kembali, menjadikannya seperti yang sekarang kau lihat."
  },
  AvgDialog_18935_Content_16 = {
    Text = "Selesai, sama sekali tidak terlihat... apakah ini sihir?"
  },
  AvgDialog_18935_Content_17 = {
    Text = "Ini bukan sihir, anakku. Ini adalah seni lilin."
  },
  AvgDialog_18935_Content_18 = {
    Text = "Patung lilin… seni…"
  },
  AvgDialog_18935_Content_19 = {
    Text = "Aku menatap \"Ibu\". Cahaya lilin yang redup melapisi wajahnya dengan kilau seperti batu giok, sambil menggambarkan senyuman di sudut bibirnya."
  },
  AvgDialog_18935_Content_2 = {
    Text = [[
Tahun Hongji 295, Musim Panas
Scarborough, North Yorkshire]]
  },
  AvgDialog_18935_Content_20 = {
    Text = "Pandangan perlahan menyapu, berusaha mencari jejak-jejak kemiskinan dan penderitaan pada dirinya, namun sia-sia."
  },
  AvgDialog_18935_Content_21 = {
    Text = "Kamu tampaknya tidak terlalu suka berbicara. Tenang saja, aku tidak berniat mengubahmu menjadi patung lilin untuk sementara waktu... Kamu bisa berbicara bebas di depanku."
  },
  AvgDialog_18935_Content_22 = {
    Text = "Mereka bilang aku, aku sakit, perlu sembuh, tidak bisa bicara sembarangan."
  },
  AvgDialog_18935_Content_23 = {
    Text = "Apakah itu gagap? Bagaimana mereka mengobati kamu?"
  },
  AvgDialog_18935_Content_24 = {
    Text = "Dengan api, penjepit panas, suntikan@2 Tetesi…"
  },
  AvgDialog_18935_Content_25 = {
    Text = "@2 Tetesi? Itu bukan sesuatu yang baik."
  },
  AvgDialog_18935_Content_26 = {
    Text = "Saya tidak tahu. Ibu berkata itu akan membantu otot tenggorokan saya menjadi lebih rileks, lebih rileks."
  },
  AvgDialog_18935_Content_27 = {
    Text = "Itu adalah pengalaman yang menyakitkan. Ibuku kecanduan berbagai \"terapi modern\" dan memperlakukanku seperti boneka, memanipulasiku sesuka hatinya."
  },
  AvgDialog_18935_Content_28 = {
    Text = "Setiap pagi, saya harus berdiri di tangga yang tinggi dengan mulut penuh kerikil tajam."
  },
  AvgDialog_18935_Content_29 = {
    Text = "Nyanyi. Ibu berkata, \"Nyanyi.\""
  },
  AvgDialog_18935_Content_3 = {
    Text = "Paman Charlie memiliki seekor kucing tabby yang sangat dia cintai~"
  },
  AvgDialog_18935_Content_30 = {
    Text = "Lalu aku bernyanyi dengan suara keras lagu alfabet yang riang, darah terus mengalir dari mulutku, mengalir sampai ke dada."
  },
  AvgDialog_18935_Content_31 = {
    Text = "Jangan menangis, anakku. Setiap patung lilin di sini memiliki cerita yang menyedihkan di baliknya."
  },
  AvgDialog_18935_Content_32 = {
    Text = "Mereka seharusnya hidup dan mati dalam diam, lalu bersama dengan cerita-cerita sedih itu terbawa air hujan ke saluran pembuangan."
  },
  AvgDialog_18935_Content_33 = {
    Text = "Seolah-olah kesedihan itu tak pernah ada."
  },
  AvgDialog_18935_Content_34 = {
    Text = "Tidak pernah... ada..."
  },
  AvgDialog_18935_Content_35 = {
    Text = "Sangat kejam, bukan? Aku ingin membantu mereka, tapi aku hanya memiliki pahat karat ini."
  },
  AvgDialog_18935_Content_36 = {
    Text = "Maka aku menjadi pencatat kesedihan-kesedihan ini... Namun, tak lama kemudian, aku tidak lagi merasa puas dengan hal itu."
  },
  AvgDialog_18935_Content_37 = {
    Text = "Kamu... mengubah mereka."
  },
  AvgDialog_18935_Content_38 = {
    Text = "Mengingat, lalu membentuk ulang——itulah filsafat patung lilin saya."
  },
  AvgDialog_18935_Content_39 = {
    Text = "Ini adalah jalan pencarian yang sulit, anakku. Namun, itu sangat memikat."
  },
  AvgDialog_18935_Content_4 = {
    Text = "Ketika dia menghilang tanpa alasan, dia mencarinya ke mana-mana~"
  },
  AvgDialog_18935_Content_40 = {
    Text = "Pada saat itu, engkau akan menjadi orang suci dalam kitab suci. Lautan akan terbelah di hadapanmu, memberikan jalan bagi tanah kering untukmu."
  },
  AvgDialog_18935_Content_41 = {
    Text = "Penjepit api pun, @2 Tetesi juga… semuanya sudah tidak penting lagi."
  },
  AvgDialog_18935_Content_42 = {
    Text = [[
22:15, Museum Lilin Rogers
Area Pameran]]
  },
  AvgDialog_18935_Content_43 = {
    Text = "Kalian berjalan di dalam museum lilin yang kuno dan usang."
  },
  AvgDialog_18935_Content_44 = {
    Text = "Hampir tidak ada cahaya alami yang masuk dari luar gedung, dan beberapa lampu minyak yang tersebar juga tidak mampu menghilangkan suasana yang menyeramkan."
  },
  AvgDialog_18935_Content_45 = {
    Text = "Saya punya sebuah pertanyaan..."
  },
  AvgDialog_18935_Content_46 = {
    Text = "Kenapa semua patung lilin ini tersenyum begitu aneh?"
  },
  AvgDialog_18935_Content_47 = {
    Text = "Kamu menatap patung lilin yang sangat halus dan indah ini."
  },
  AvgDialog_18935_Content_48 = {
    Text = "Yang menutup mulut, yang mengantuk, dan yang memegang payung... satu-satunya kesamaan di antara mereka adalah senyuman cerah di wajah mereka."
  },
  AvgDialog_18935_Content_49 = {
    Text = [[
Tampaknya agak menyeramkan. 
Mengatakan mereka bahagia, mata mereka seperti lubang hitam, tanpa Roh sama sekali.]]
  },
  AvgDialog_18935_Content_50 = {
    Text = "Menurut saya, kemampuan Rogers tidak begitu hebat, hanya tampak bagus di luar saja."
  },
  AvgDialog_18935_Content_51 = {
    Text = [[
Dari data sebelumnya, "tawa" tampaknya menjadi salah satu tema seni utama Rogers. 
 Apakah saya benar, Boneka?]]
  },
  AvgDialog_18935_Content_52 = {Text = "Boneka?"},
  AvgDialog_18935_Content_53 = {
    Text = "Kresek… kresek…"
  },
  AvgDialog_18935_Content_54 = {
    Text = "Kamu mengetuk pin dada beberapa kali, namun tidak ada jawaban. Seluruh museum lilin begitu sunyi seperti kuburan raksasa."
  },
  AvgDialog_18935_Content_55 = {
    Text = "Komunikator berfungsi dengan baik, namun sinyal terputus… Ada apa?"
  },
  AvgDialog_18935_Content_56 = {
    Text = "Saat masuk ke museum lilin, sepertinya saya mendengar suara listrik… ada sesuatu yang mengganggu komunikasi?"
  },
  AvgDialog_18935_Content_57 = {Text = "!!"},
  AvgDialog_18935_Content_58 = {
    Text = "Saya juga mendengarnya."
  },
  AvgDialog_18935_Content_59 = {
    Text = "Apa sekarang? Menurut rencana awal, kita harus bekerja sama dengan Nona Boneka…"
  },
  AvgDialog_18935_Content_6 = {
    Text = "Bu, apakah aku bernyanyi dengan baik?"
  },
  AvgDialog_18935_Content_60 = {
    Text = "Mungkin ini ulah Pandia, lebih baik kembali dan lihat dulu."
  },
  AvgDialog_18935_Content_7 = {
    Text = "Hari ini adalah hari kelima belas aku bersama ibuku \"Galatea\"."
  },
  AvgDialog_18935_Content_8 = {
    Text = "Memandang wajahnya yang lembut serta sikapnya yang terlihat begitu sempurna, tiba-tiba sebuah perasaan haru menyusup ke dalam hatiku."
  },
  AvgDialog_18935_Content_9 = {
    Text = "Saya dengan lembut menyandarkan kepala saya ke pangkuannya."
  },
  AvgDialog_18936_Content_1 = {
    Text = "Kenapa harus kembali menemui orang itu… Dia tampaknya bukan orang baik."
  },
  AvgDialog_18936_Content_2 = {
    Text = "Pergi ke meja depan untuk menelepon, lihat apa masalahnya sebenarnya."
  },
  AvgDialog_18936_Content_3 = {
    Text = "Mengerti! Jika dia yang berbuat nakal, tangkap dia dan pukul dulu."
  },
  AvgDialog_18937_Content_1 = {
    Text = "Huu hu hu, kembalikan ususku…"
  },
  AvgDialog_18937_Content_2 = {
    Text = "Nih, ini untukmu!"
  },
  AvgDialog_18937_Content_3 = {
    Text = "Tidak bisa dimasukkan kembali... hu... hu... hu..."
  },
  AvgDialog_18938_Content_1 = {Text = "Galatea"},
  AvgDialog_18938_Content_10 = {
    Text = "Orang tuaku adalah orang kaya yang terhormat, mereka akan memberi uang kepadamu…"
  },
  AvgDialog_18938_Content_11 = {
    Text = "Asalkan kau mau melepaskanku, biarkan aku pergi."
  },
  AvgDialog_18938_Content_12 = {
    Text = "Ssst... jangan bicara, kamu mengganggunya."
  },
  AvgDialog_18938_Content_13 = {
    Text = "Kemarilah, Anak."
  },
  AvgDialog_18938_Content_14 = {
    Text = "Mendekatlah, jangan takut."
  },
  AvgDialog_18938_Content_15 = {
    Text = "Lihat tangannya, bukankah sangat indah?"
  },
  AvgDialog_18938_Content_16 = {
    Text = "Bahkan giok terindah tanpa cela pun tidak sebanding dengan seperseribu bagian darinya."
  },
  AvgDialog_18938_Content_17 = {
    Text = "<Shake: Indah... sangat indah, Tuan.>"
  },
  AvgDialog_18938_Content_18 = {
    Text = "Sangat disayangkan, aku tidak merasakan sedikit pun rasa hormat di matamu, hanya ketakutan dan jijik…"
  },
  AvgDialog_18938_Content_19 = {
    Text = "Tidak... bukan seperti itu, beri aku satu kesempatan lagi!"
  },
  AvgDialog_18938_Content_2 = {
    Text = [[
Tahun Hongji 295, Musim Panas
Scarborough, North Yorkshire]]
  },
  AvgDialog_18938_Content_20 = {
    Text = "Tidak apa-apa, aku akan membimbingmu dengan baik dan menghapus tabir kegelapan dari dirimu. \nMari kita mulai dari langkah pertama ——"
  },
  AvgDialog_18938_Content_21 = {Text = "Berlutut."},
  AvgDialog_18938_Content_22 = {
    Text = "Sekarang aku memerintahkanmu, berlutut."
  },
  AvgDialog_18938_Content_23 = {
    Text = "Kepada Galatea, kepada \"Mama\"…"
  },
  AvgDialog_18938_Content_24 = {
    Text = "Persembahkan ciuman yang tulus."
  },
  AvgDialog_18938_Content_25 = {
    Text = "Itu adalah pertama kalinya aku mencium \"Mama\"."
  },
  AvgDialog_18938_Content_26 = {
    Text = "Tangan pucat itu dibungkus dengan hati-hati dalam lilin minyak kental. Di bawah terik panas musim panas Scarborough, tangan tersebut samar-samar mengeluarkan bau busuk."
  },
  AvgDialog_18938_Content_27 = {
    Text = "Nafas kematian."
  },
  AvgDialog_18938_Content_28 = {
    Text = "21:00, Jalan Southwark"
  },
  AvgDialog_18938_Content_29 = {
    Text = "Memanggil komunikator nomor I-2069, memanggil komunikator nomor I-2069…"
  },
  AvgDialog_18938_Content_3 = {
    Text = "Ini adalah karya seni favorit saya — Galatea."
  },
  AvgDialog_18938_Content_30 = {
    Text = "Percobaan komunikasi ke-25 gagal. Kami kehilangan tautan dengan penyelidik William Delaplume."
  },
  AvgDialog_18938_Content_31 = {
    Text = "Apakah detektif yang bekerja sama dengan William dapat dihubungi?"
  },
  AvgDialog_18938_Content_32 = {
    Text = [[
Sayang sekali, tidak bisa. 
Ayo berhenti dulu, kembali ke Mythag untuk melapor. Sebelum kita memahami situasinya, jangan bertindak sembarangan.]]
  },
  AvgDialog_18938_Content_33 = {
    Text = "Pulang kerja? Tapi situasi Kak William saat ini tidak jelas, aku khawatir tentang dia..."
  },
  AvgDialog_18938_Content_34 = {
    Text = "Benar-benar sekumpulan pengecut."
  },
  AvgDialog_18938_Content_35 = {
    Text = "Maaf, kakak saya tidak bisa menunggu prosedur yang begitu rumit dan memakan waktu ini."
  },
  AvgDialog_18938_Content_36 = {
    Text = "Museum lilin bisa aku kunjungi sendirian."
  },
  AvgDialog_18938_Content_37 = {Text = "Cit cit!"},
  AvgDialog_18938_Content_38 = {
    Text = "Setelah Jenkin selesai berbicara, dia berbalik dan langsung masuk ke dalam kabut yang kental."
  },
  AvgDialog_18938_Content_39 = {
    Text = "Jenkin! Jangan berlari sembarangan, di sana sangat berbahaya!"
  },
  AvgDialog_18938_Content_4 = {
    Text = "Pernah mendengar <Blue:Pygmalion> ceritanya?"
  },
  AvgDialog_18938_Content_40 = {
    Text = "Cepat kejar dia."
  },
  AvgDialog_18938_Content_5 = {
    Text = "Dia mengukir sebuah patung gadis muda yang indah dari gading, membelainya dan mendandaninya seperti seorang suami memperlakukan istrinya…"
  },
  AvgDialog_18938_Content_6 = {
    Text = "Dan mempersembahkan seluruh semangat serta cinta kepadanya."
  },
  AvgDialog_18938_Content_7 = {
    Text = "\"Galatea\" — itulah nama gadis itu."
  },
  AvgDialog_18938_Content_8 = {
    Text = "Maaf, aku tidak sengaja berbicara terlalu banyak. Kamu pasti merasa bosan."
  },
  AvgDialog_18938_Content_9 = {
    Text = "Tidak, tidak ada apa-apa, Tuan. Mohon, Tuan…"
  },
  AvgDialog_18939_Content_1 = {
    Text = "Musim Panas Scarborough"
  },
  AvgDialog_18939_Content_10 = {
    Text = "George, nama saya George."
  },
  AvgDialog_18939_Content_11 = {
    Text = "Tahun Hongji 295, Bulan 6 Hari @1."
  },
  AvgDialog_18939_Content_12 = {
    Text = "Itu adalah hari yang sangat kacau. Hingga mereka membuka pintu ruang bawah tanah dan membiarkan sinar matahari masuk…"
  },
  AvgDialog_18939_Content_13 = {
    Text = "Baru aku sadar bahwa taman ku, kerajaan ku ternyata hanyalah sebuah ruang bawah tanah yang sempit."
  },
  AvgDialog_18939_Content_14 = {
    Text = "Anak! Anakku… akhirnya kutemukan kamu!"
  },
  AvgDialog_18939_Content_15 = {
    Text = "Cepat pergi dari sini bersama Ibu, dan tinggalkan tempat ini selamanya…"
  },
  AvgDialog_18939_Content_16 = {Text = "George…"},
  AvgDialog_18939_Content_17 = {Text = "……Apa?"},
  AvgDialog_18939_Content_18 = {
    Text = "George… Aku akan pergi bersama Joe dan George."
  },
  AvgDialog_18939_Content_19 = {
    Text = "\"George\"? Apakah kamu merujuk pada patung lilin kecil ini?"
  },
  AvgDialog_18939_Content_2 = {
    Text = [[
Tahun Hongji 295, Musim Panas
Scarborough, North Yorkshire]]
  },
  AvgDialog_18939_Content_20 = {
    Text = "George! Tolong, tolong kembalikan padaku——"
  },
  AvgDialog_18939_Content_21 = {
    Text = "Jangan terburu-buru, nak. Jawab dulu satu pertanyaan saya."
  },
  AvgDialog_18939_Content_22 = {
    Text = "<Yellow:\"Patung lilin\" pergi ke mana?>"
  },
  AvgDialog_18939_Content_23 = {
    Text = "\"Patung lilin\"...? Saya... saya tidak tahu apa yang kamu maksud..."
  },
  AvgDialog_18939_Content_24 = {
    Text = "Haha. Apakah kamu benar-benar tidak tahu? Kalau begitu, aku akan memberimu satu pertanyaan lagi."
  },
  AvgDialog_18939_Content_25 = {
    Text = "<Yellow: Dari mana patung lilin ini berasal?>"
  },
  AvgDialog_18939_Content_27 = {
    Text = "<Shake: Ibu, aku... aku takut.>"
  },
  AvgDialog_18939_Content_28 = {
    Text = "Detektif, harap perhatikan nada bicaramu."
  },
  AvgDialog_18939_Content_29 = {
    Text = "Jika diperlukan untuk bekerja sama dalam Penyelidikan, silakan hubungi pengacara kami Franz·@1 kapan saja. Kami berpisah di sini."
  },
  AvgDialog_18939_Content_3 = {
    Text = "Dia sudah meninggal. Sekarang aku hanya punya kamu."
  },
  AvgDialog_18939_Content_30 = {
    Text = "Wanita berpakaian mewah mengangkat dagunya yang lancip, melirik detektif di depannya dengan pandangan menyamping, lalu menarik anak laki-laki itu dan pergi."
  },
  AvgDialog_18939_Content_31 = {
    Text = "Hehe... menarik."
  },
  AvgDialog_18939_Content_32 = {
    Text = "Akhirnya, aku menemukan studio ini juga! Tak disangka, kau ternyata cukup berguna!"
  },
  AvgDialog_18939_Content_33 = {
    Text = "Ah? Ya, ya... terima kasih..."
  },
  AvgDialog_18939_Content_34 = {
    Text = "Kamu melihat sekeliling, ini adalah tempat yang redup."
  },
  AvgDialog_18939_Content_35 = {
    Text = "Cahaya redup lampu dinding di sudut ruangan berkedip-kedip, memberikan cahaya bulan yang masuk melalui jendela sebuah warna kelabu yang suram."
  },
  AvgDialog_18939_Content_36 = {
    Text = "Di dalam ruangan yang kosong, terlihat lengan, kaki, kepala, dan batang tubuh yang terbuat dari lilin di mana-mana…"
  },
  AvgDialog_18939_Content_37 = {
    Text = "Mereka seperti kaos kaki lembut yang sobek, ditumpuk sembarangan di bangku, meja kerja, dan lantai."
  },
  AvgDialog_18939_Content_38 = {
    Text = "Freeman, Little John, dan Luke Si Empat Jari…"
  },
  AvgDialog_18939_Content_39 = {
    Text = "Patung lilin yang ada di sini, semuanya adalah orang yang kukenal di Whitechapel!"
  },
  AvgDialog_18939_Content_4 = {
    Text = "Apa nama kamu?"
  },
  AvgDialog_18939_Content_40 = {
    Text = [[
Dengan demikian, tuduhan terhadap Rogers semakin kuat.  
Tidak hanya itu, orang-orang dari Perhimpunan Pematung sepertinya juga tidak dapat terhindar dari keterlibatan.]]
  },
  AvgDialog_18939_Content_41 = {
    Text = "Ramona berkata sambil menyenggol tumpukan anggota tubuh yang bertumpuk di sampingnya."
  },
  AvgDialog_18939_Content_42 = {
    Text = "Semuanya memiliki jejak percobaan, caranya sangat mirip dengan yang kita lihat di Taring tempat kerja."
  },
  AvgDialog_18939_Content_43 = {
    Text = "Ternyata... Aigis juga olehnya..."
  },
  AvgDialog_18939_Content_44 = {
    Text = "Saya pasti akan menemukannya dan membalas dendam untuk Aigis."
  },
  AvgDialog_18939_Content_45 = {
    Text = "Rogers harus dihukum. Sebelum itu, kita harus menemukan \"Spring\" terlebih dahulu."
  },
  AvgDialog_18939_Content_46 = {
    Text = "Mencari barang adalah keahlianku, serahkan saja padaku!"
  },
  AvgDialog_18939_Content_5 = {
    Text = "Joe, Joe..."
  },
  AvgDialog_18939_Content_6 = {Text = "Jo…"},
  AvgDialog_18939_Content_7 = {
    Text = "Ingat, kamu dan aku tidak sama. Kamu tidak gagap."
  },
  AvgDialog_18939_Content_8 = {
    Text = "Mari kita coba lagi. Siapa namamu?"
  },
  AvgDialog_18940_Content_1 = {
    Text = "Gadis dan Air Mata"
  },
  AvgDialog_18940_Content_10 = {
    Text = "George menyusut ke dalam pelukan Rogers dan berteriak dengan tuduhan."
  },
  AvgDialog_18940_Content_11 = {
    Text = "Rogers dengan penuh kasih sayang mengelus kepala George yang berbulu dan keemasan, lalu menghela napas."
  },
  AvgDialog_18940_Content_12 = {
    Text = "Bagaimana mungkin Jenkin kecil bisa menjadi anak yang biasa? Dia sudah memiliki keberanian untuk datang ke Museum Lilin mencari kakaknya."
  },
  AvgDialog_18940_Content_13 = {
    Text = "Apakah saya benar, <Yellow:Nona Mason>?"
  },
  AvgDialog_18940_Content_14 = {
    Text = "Nona Mason?!"
  },
  AvgDialog_18940_Content_15 = {
    Text = "Mason... apakah kamu benar-benar kakak perempuan?"
  },
  AvgDialog_18940_Content_17 = {
    Text = "24 menghela napas pelan, lalu merangkul Jenkin."
  },
  AvgDialog_18940_Content_18 = {
    Text = "Aroma-aroma yang familiar, yang telah menemani Jenkin selama tak terhitung malam dan hari, datang menerpa, seketika membangun memori yang telah lama terpendam."
  },
  AvgDialog_18940_Content_19 = {
    Text = "Benar-benar aroma Kakak… Ternyata semua ini bukan mimpi. Syukurlah…"
  },
  AvgDialog_18940_Content_2 = {
    Text = [[
3:00, Museum Lilin Rogers
Area Pameran Khusus]]
  },
  AvgDialog_18940_Content_20 = {
    Text = "Jenkin, kamu bukan tikus yang tidak diinginkan. Kamu masih punya aku, dan Cokelat juga."
  },
  AvgDialog_18940_Content_21 = {
    Text = "Tenang saja, aku tidak akan membiarkan mereka membawamu pergi."
  },
  AvgDialog_18940_Content_22 = {
    Text = "24 menyentuh pipi kecil Jenkin, lalu berbalik dan dengan tenang menatap Rogers serta yang lainnya."
  },
  AvgDialog_18940_Content_23 = {
    Text = "Pandia, Rogers, bukankah sudah disepakati sebelumnya?"
  },
  AvgDialog_18940_Content_24 = {
    Text = "Saya akan membantu membawa mereka ke sini sebagai pertukaran, Jenkin bisa pergi."
  },
  AvgDialog_18940_Content_25 = {
    Text = "Kenapa……"
  },
  AvgDialog_18940_Content_26 = {
    Text = "Pletak——!"
  },
  AvgDialog_18940_Content_27 = {
    Text = "Cemeti tanpa ampun mendarat, dan dalam sekejap muncul bekas merah yang mengerikan di wajah 24."
  },
  AvgDialog_18940_Content_28 = {Text = "Ugh——!"},
  AvgDialog_18940_Content_29 = {
    Text = [[
Dari mana ada begitu banyak kenapa. 
Ketika kalian merusak museum lilin, mengapa tidak memikirkan konsekuensinya?]]
  },
  AvgDialog_18940_Content_3 = {Text = "Sebentar?"},
  AvgDialog_18940_Content_30 = {
    Text = "Aku hanya akan mengatakannya sekali — minggir."
  },
  AvgDialog_18940_Content_31 = {
    Text = "24 berdiri di depan Jenkin, tulang belikatnya yang kurus bergetar seperti sayap kupu-kupu."
  },
  AvgDialog_18940_Content_32 = {
    Text = "Dia mencoba memaksakan senyum, namun justru terlihat lebih menyedihkan daripada menangis."
  },
  AvgDialog_18940_Content_33 = {
    Text = "Asalkan kalian bersedia membiarkannya pergi, aku akan minggir…"
  },
  AvgDialog_18940_Content_34 = {
    Text = "Pletak——!"
  },
  AvgDialog_18940_Content_35 = {
    Text = "Tak terhitung cambukan jatuh seperti hujan."
  },
  AvgDialog_18940_Content_36 = {
    Text = "Benar-benar menyebalkan, tangan saya sudah pegal. Apakah kamu berniat mati di sini hari ini, 24?"
  },
  AvgDialog_18940_Content_37 = {
    Text = "Kehilangan budak yang begitu penurut seperti dirimu, aku juga akan menangis, loh~"
  },
  AvgDialog_18940_Content_38 = {
    Text = "Tuan, kasihanilah... Biarkan dia pergi, aku bersedia melakukan apa saja..."
  },
  AvgDialog_18940_Content_39 = {
    Text = "Aku akan tetap tinggal di museum seumur hidupku, seperti yang kalian harapkan, dan tidak akan pergi ke mana-mana lagi…"
  },
  AvgDialog_18940_Content_4 = {
    Text = "Apakah kamu punya ide yang lebih brilian untuk melatih tikus kecil kita? Cepat bagikan kepada semua orang ya, 24~"
  },
  AvgDialog_18940_Content_40 = {
    Text = "Pletak——!"
  },
  AvgDialog_18940_Content_41 = {
    Text = "Pletak——!"
  },
  AvgDialog_18940_Content_42 = {
    Text = [[
Segera, seluruh tubuh 24 penuh dengan Caro yang hancur. 
 Namun dia tidak bergerak sedikit pun, hanya menggumamkan kata-kata yang sama.]]
  },
  AvgDialog_18940_Content_43 = {
    Text = "<Shake:Bi-biarkan dia pergi……>"
  },
  AvgDialog_18940_Content_44 = {
    Text = "<Shake:Biarkan dia pergi……>"
  },
  AvgDialog_18940_Content_45 = {
    Text = "Kalian datang menyerangku, sekumpulan sampah! Jangan..."
  },
  AvgDialog_18940_Content_46 = {
    Text = "<Shake: Jangan pukul kakakku……>"
  },
  AvgDialog_18940_Content_47 = {
    Text = "<Gray:Tidak... sama sekali tidak bisa bergerak. Harus mencari cara untuk mengeluarkan kunci perak...>"
  },
  AvgDialog_18940_Content_48 = {
    Text = "Hmm, sudah cukup bermain. Seseorang, bawa dia pergi."
  },
  AvgDialog_18940_Content_49 = {Text = "Baik!"},
  AvgDialog_18940_Content_5 = {
    Text = "Tuan... dia hanyalah seorang anak biasa dari kawasan kumuh, tidak akan membahayakan kalian sama sekali."
  },
  AvgDialog_18940_Content_50 = {
    Text = "Tidak… aku tidak pergi, kalian belum menepati janjiku…"
  },
  AvgDialog_18940_Content_51 = {
    Text = "<Big:Jangan banyak bicara, ayo pergi!>"
  },
  AvgDialog_18940_Content_52 = {
    Text = "Pemberontakan 24 tidak berguna, dia diseret seperti sepotong kain bekas."
  },
  AvgDialog_18940_Content_53 = {
    Text = "Saat melewati kamu, 24 tiba-tiba mengangkat pandangannya dan langsung menerjangmu."
  },
  AvgDialog_18940_Content_54 = {
    Text = "Kunci… %player%, kunci perak itu, kamu bisa menggunakannya dalam pertempuran, kan?"
  },
  AvgDialog_18940_Content_55 = {Text = "Apa...?"},
  AvgDialog_18940_Content_56 = {
    Text = "Kunci perak itu berhasil padaku! Cepat buat Tautan denganku, kita bersama-sama menyelamatkannya!"
  },
  AvgDialog_18940_Content_57 = {
    Text = "Tidak, kamu bukan Pembangun, aku tidak bisa——"
  },
  AvgDialog_18940_Content_58 = {Text = "Bam——!"},
  AvgDialog_18940_Content_59 = {
    Text = "Jangan coba-coba bermain-main denganku, atau aku akan membuat kepalamu meledak sekarang juga!"
  },
  AvgDialog_18940_Content_6 = {
    Text = "Lebih baik langsung membebaskannya..."
  },
  AvgDialog_18940_Content_60 = {
    Text = "Pukulan ini tidak membuat 24 mundur. Dia secara ajaib melepaskan diri dari belenggu dan berlari ke arahmu."
  },
  AvgDialog_18940_Content_61 = {
    Text = "Lalu ia menarik kunci perak dari dada Anda dan meletakkannya di telapak tangan Anda."
  },
  AvgDialog_18940_Content_62 = {
    Text = "Cepat tangkap dia, jangan biarkan dia melarikan diri!"
  },
  AvgDialog_18940_Content_63 = {
    Text = "Bagaimana bisa tahu kalau tidak mencoba?! Aku pernah menjadi subjek eksperimen, mungkin aku bisa seperti mereka…"
  },
  AvgDialog_18940_Content_64 = {
    Text = "Selama memegangnya, bisa berpartisipasi dalam pertempuran, kan?"
  },
  AvgDialog_18940_Content_66 = {
    Text = "Baik. Saya akan mencobanya."
  },
  AvgDialog_18940_Content_67 = {
    Text = "Kamu menggerakkan kunci perak di tanganmu, cahaya redup yang dingin berkilauan di depan dada, sekaligus menerangi wajah 24."
  },
  AvgDialog_18940_Content_68 = {
    Text = "Pucat, rapuh, namun sangat teguh."
  },
  AvgDialog_18940_Content_69 = {
    Text = "24, dengarkan perintahku!"
  },
  AvgDialog_18940_Content_7 = {Text = "3 kali."},
  AvgDialog_18940_Content_8 = {
    Text = "Orang ini memaki saya 3 kali dengan sebutan \"babi\", 2 kali dengan sebutan \"idiot\", dan 5 kali dengan @2."
  },
  AvgDialog_18940_Content_9 = {
    Text = "Kepribadian George telah dihina secara serius! Jenkin harus mati! Harus mati!"
  },
  AvgDialog_18941_Content_1 = {
    Text = "Buku Panduan Diagnosis"
  },
  AvgDialog_18941_Content_10 = {
    Text = "To……tolong aku……"
  },
  AvgDialog_18941_Content_11 = {
    Text = "D-lendir hitam terus mengalir dari rongga matanya, namun dia sama sekali tidak menyadarinya."
  },
  AvgDialog_18941_Content_12 = {
    Text = "Jangan lihat yang buruk rupa, George. Jangan lihat yang buruk rupa."
  },
  AvgDialog_18941_Content_13 = {
    Text = "Saya menutupi mata kanannya dengan tangan saya."
  },
  AvgDialog_18941_Content_14 = {
    Text = "Begitu lebih baik, tampak lebih bagus. Apakah kamu ingin bertahan hidup?"
  },
  AvgDialog_18941_Content_15 = {
    Text = "Gadis itu mengangguk dengan segenap tenaganya."
  },
  AvgDialog_18941_Content_16 = {
    Text = "Tenang saja, aku akan mewujudkan Keinginanmu."
  },
  AvgDialog_18941_Content_17 = {
    Text = "Namun, dengan cara yang berbeda."
  },
  AvgDialog_18941_Content_18 = {
    Text = "Akhirnya, saya menemukan Anda, Tuan Rogers."
  },
  AvgDialog_18941_Content_19 = {
    Text = "Kamu adalah...?"
  },
  AvgDialog_18941_Content_2 = {
    Text = "Itu adalah sesuatu yang berwarna hitam dan kental."
  },
  AvgDialog_18941_Content_20 = {
    Text = "Kamu bisa memanggil saya <Yellow:Herbert>. Saya sangat tertarik dengan seni lilinmu... Kebetulan ada bar yang bagus di seberang jalan, apakah saya bisa mentraktirmu minum?"
  },
  AvgDialog_18941_Content_21 = {
    Text = "Kalian minum satu gelas bersama. Lalu, apa yang terjadi setelahnya?"
  },
  AvgDialog_18941_Content_22 = {
    Text = "Kemudian saya menerima undangan dari <Blue:Tuan Herbert> untuk bersama-sama meneliti beberapa topik penelitian."
  },
  AvgDialog_18941_Content_23 = {
    Text = "Sebagai imbalan, dia akan memberikan beberapa \"bahan\" untuk patung lilin."
  },
  AvgDialog_18941_Content_24 = {
    Text = "Mengerti. Saya sudah sepenuhnya memahami cerita Anda, jadi…"
  },
  AvgDialog_18941_Content_25 = {
    Text = "Tuan Rogers, Anda telah membunuh \"Patung lilin\"."
  },
  AvgDialog_18941_Content_26 = {
    Text = "Anda membunuh wanita itu di tengah salju."
  },
  AvgDialog_18941_Content_27 = {
    Text = "Anda juga membunuh anak-anak itu. Apakah saya benar?"
  },
  AvgDialog_18941_Content_28 = {
    Text = "Saya... saya tidak..."
  },
  AvgDialog_18941_Content_29 = {
    Text = "Oh? Saya melihatnya dengan jelas di workhouse — anak-anak yang hilang."
  },
  AvgDialog_18941_Content_3 = {
    Text = "Itu memancar keluar dari celah di bawah tanah, mengalir melalui urat daun, dan bahkan bisa mengalir keluar dari mulut seseorang."
  },
  AvgDialog_18941_Content_30 = {
    Text = "Tuan Rogers, karena Anda memilih untuk menerima perawatan, harap bersikap terbuka kepada saya."
  },
  AvgDialog_18941_Content_31 = {
    Text = "Kita harus saling percaya."
  },
  AvgDialog_18941_Content_32 = {
    Text = "Apakah hal ini penting bagi Anda, Nona Clementine?"
  },
  AvgDialog_18941_Content_33 = {
    Text = "Penting atau tidak, tergantung pada jawaban Anda. Sebelum itu, semuanya masih merupakan misteri."
  },
  AvgDialog_18941_Content_34 = {
    Text = "Namun, terkadang justru perasaan ketidaktahuan inilah yang terus menarik kita…"
  },
  AvgDialog_18941_Content_35 = {
    Text = "Maaf, Tuan Rogers, saya tidak seharusnya memaksa Anda seperti itu."
  },
  AvgDialog_18941_Content_36 = {
    Text = "Wanita bodoh, jangan kira aku tidak tahu apa yang kau rencanakan. Kau pasti diam-diam menikmati penderitaan Tuan Rogers, kan?"
  },
  AvgDialog_18941_Content_37 = {
    Text = "Tuan Rogers tidak pernah berbohong."
  },
  AvgDialog_18941_Content_38 = {
    Text = "Kami tidak pernah membunuh; kami hanya memberikan tanggapan."
  },
  AvgDialog_18941_Content_39 = {
    Text = "Menanggapi keinginan mereka untuk dijadikan patung lilin."
  },
  AvgDialog_18941_Content_4 = {
    Text = "Kami menyebutnya \"Pelarutan\". Itu ada di mana-mana, namun tak berbentuk dan tak terlihat."
  },
  AvgDialog_18941_Content_40 = {
    Text = "Salah orang? Tidak mungkin, kamu jelas-jelas mengenakan rok yang sama dengan mereka…"
  },
  AvgDialog_18941_Content_41 = {
    Text = "\"Spring\" Patung lilin ini memiliki begitu banyak orang, apakah kita semua adalah kakakmu?"
  },
  AvgDialog_18941_Content_42 = {
    Text = "Ada suatu masa ketika Tuan Rogers meminta kami untuk mengenakan rok yang hampir sama, bahkan sampai kami tidak bisa bergerak."
  },
  AvgDialog_18941_Content_43 = {
    Text = "Wanita itu mengangkat ujung roknya dan mengusapnya dengan hati-hati, lalu mendekatkannya ke hidung untuk mencium aromanya."
  },
  AvgDialog_18941_Content_44 = {
    Text = "Astaga, sudah bau. Sayang sekali, aku sudah bertahun-tahun tidak memakai pakaian yang utuh."
  },
  AvgDialog_18941_Content_45 = {
    Text = "Barusan kamu bilang <Yellow:Lord Rogers?> Apakah kamu orang suruhannya?"
  },
  AvgDialog_18941_Content_46 = {
    Text = "Ini adalah masalah baru. Jadi... apa yang akan kalian berikan sebagai balasan untukku?"
  },
  AvgDialog_18941_Content_47 = {
    Text = "Balas budi? Baik, aku akan memberikannya sekarang."
  },
  AvgDialog_18941_Content_48 = {
    Text = "Ramona menarik napas dalam-dalam, lalu tiba-tiba mencabut pedangnya dan menusuk bahu Leigh."
  },
  AvgDialog_18941_Content_49 = {Text = "Ramona!!!"},
  AvgDialog_18941_Content_5 = {
    Text = "Orang yang terinfeksi oleh Pelarutan akan perlahan-lahan dilupakan oleh dunia."
  },
  AvgDialog_18941_Content_50 = {
    Text = "Tenang, aku punya batas yang jelas."
  },
  AvgDialog_18941_Content_51 = {
    Text = "Nona, kami tidak punya waktu untuk bermain teka-teki dengannya. Sekarang, bisakah kamu menjawab?"
  },
  AvgDialog_18941_Content_52 = {
    Text = "Wajah pucat wanita itu seketika memerah. Dia gemetar sambil tertawa."
  },
  AvgDialog_18941_Content_53 = {
    Text = "Baik, sangat baik… sungguh, rasa sakit yang pas…"
  },
  AvgDialog_18941_Content_54 = {
    Text = "Jika ada pertanyaan, jangan ragu... untuk bertanya."
  },
  AvgDialog_18941_Content_55 = {
    Text = "Siapa yang memberi perintah kepadamu?"
  },
  AvgDialog_18941_Content_56 = {
    Text = "Maaf... Hanya pertanyaan ini yang tidak bisa saya jawab untukmu."
  },
  AvgDialog_18941_Content_57 = {Text = "Kenapa?"},
  AvgDialog_18941_Content_58 = {
    Text = "Karena cinta."
  },
  AvgDialog_18941_Content_59 = {Text = "...Ha?"},
  AvgDialog_18941_Content_6 = {
    Text = "Surat, arsip, foto... semua bukti yang berkaitan dengan keberadaannya akan dihapus. Seolah-olah..."
  },
  AvgDialog_18941_Content_60 = {
    Text = "Cinta yang menyakitkan, membara, dan tidak tercapai!"
  },
  AvgDialog_18941_Content_61 = {
    Text = "Di atas Altar dinginnya, aku bersedia mempersembahkan air mataku, desahanku, dan yang paling murni dari..."
  },
  AvgDialog_18941_Content_62 = {Text = "Jiwa!"},
  AvgDialog_18941_Content_64 = {
    Text = "Kenapa menjadi Pembangun?"
  },
  AvgDialog_18941_Content_65 = {
    Text = "Tentu saja untuk bertahan hidup. Ini adalah janjiku kepada @1…"
  },
  AvgDialog_18941_Content_66 = {
    Text = "Wanita itu membelai lembut kode hitam yang kabur di pergelangan tangannya, dengan suara yang rendah dan lembut."
  },
  AvgDialog_18941_Content_67 = {
    Text = [[
Lihatlah, mereka akan mengukir kode untuk setiap produk eksperimen yang berhasil. 
Kode yang <Blue:unik> milik kita...]]
  },
  AvgDialog_18941_Content_68 = {
    Text = "\"Mereka,\" apakah yang dimaksud adalah Para pematung?"
  },
  AvgDialog_18941_Content_69 = {
    Text = "Wanita itu tidak merespons, tampaknya dia mengiyakan dugaanmu."
  },
  AvgDialog_18941_Content_7 = {
    Text = "Dia tak pernah ada di dunia ini sebelumnya."
  },
  AvgDialog_18941_Content_71 = {
    Text = "Orang seperti itu, apakah dia benar-benar kakakku... Cokelat, bagaimana menurutmu?"
  },
  AvgDialog_18941_Content_72 = {
    Text = "Tikus kecil dengan lincah melompat ke bahu gadis berambut pendek, lalu dengan penuh kasih sayang menggosokkan dirinya padanya."
  },
  AvgDialog_18941_Content_73 = {
    Text = "Cicit cicit~"
  },
  AvgDialog_18941_Content_74 = {
    Text = "Oh, aku masih begitu disukai oleh tikus-tikus, ya."
  },
  AvgDialog_18941_Content_75 = {
    Text = "Orang yang membusuk dan bertunas di saluran pembuangan selalu memiliki ikatan aneh dengan tikus."
  },
  AvgDialog_18941_Content_76 = {
    Text = "Apakah kamu juga pernah berada di saluran pembuangan? Tidak, ini bukan kebetulan…"
  },
  AvgDialog_18941_Content_77 = {
    Text = "Dor! Dor——!"
  },
  AvgDialog_18941_Content_78 = {
    Text = "Pemeriksaan belum selesai, tiba-tiba terdengar suara berat dari kedalaman ruang bawah tanah yang tidak mencolok."
  },
  AvgDialog_18941_Content_79 = {
    Text = "Kalian menahan napas, dan sepertinya mendengar tangisan anak-anak yang rendah, tertekan, dan terputus-putus."
  },
  AvgDialog_18941_Content_8 = {
    Text = [[
@2 tahun musim dingin
Londinium]]
  },
  AvgDialog_18941_Content_80 = {
    Text = "Lapar……"
  },
  AvgDialog_18941_Content_81 = {
    Text = "<Change>Lapar... lapar lapar lapar lapar lapar lapar lapar lapar lapar"
  },
  AvgDialog_18941_Content_9 = {
    Text = "Enam tahun yang lalu, pada suatu malam musim dingin, saya beruntung menyaksikan salju pertama di Londinium, serta seorang gadis muda yang terbaring di atas salju."
  },
  AvgDialog_18942_Content_1 = {
    Text = "Sempai, kamu terdengar sangat lemah, apakah kamu mengalami kelemahan?"
  },
  AvgDialog_18942_Content_2 = {
    Text = "Kami kehilangan kontak dengan Nona Boneka, bagaimana denganmu?"
  },
  AvgDialog_18942_Content_3 = {
    Text = "Hei, apakah kamu pernah melihat seorang gadis yang lebih tua dariku?"
  },
  AvgDialog_18942_Content_4 = {
    Text = "Huh huh huh… Tanyakan satu per satu."
  },
  AvgDialog_18943_Content_1 = {
    Text = "Seorang wanita muda yang pucat dan kurus bersandar di sisi dinding. Matanya setengah tertutup, wajahnya memerah, dan napasnya sangat cepat."
  },
  AvgDialog_18943_Content_10 = {
    Text = "Rasa sakit yang tajam seperti ditusuk jarum, menusuk leher dengan keras, terus menembus lebih dalam, lebih dalam lagi…"
  },
  AvgDialog_18943_Content_11 = {Text = "<Big:?>!"},
  AvgDialog_18943_Content_12 = {
    Text = "Terdengar suara hisapan dan telan yang serakah di sisi telinga. Ada sesuatu yang lembut dan dingin, seperti pengisap, menempel erat di lehermu."
  },
  AvgDialog_18943_Content_13 = {
    Text = "Ugh... pergi, pergi...!!"
  },
  AvgDialog_18943_Content_14 = {
    Text = "Berikan aku, berikan aku…"
  },
  AvgDialog_18943_Content_15 = {
    Text = "Sensasi kehilangan darah dengan cepat memang tidak nyaman. Penglihatanmu menjadi gelap, dan detak jantungmu meningkat drastis."
  },
  AvgDialog_18943_Content_17 = {
    Text = "Aku memanggilmu... <Big:Menyingkirlah!!!>"
  },
  AvgDialog_18943_Content_2 = {
    Text = "Sepertinya dia terluka, biar aku memeriksa."
  },
  AvgDialog_18943_Content_3 = {
    Text = "Wanita itu mengenakan gaun putih panjang yang tipis, tampaknya sama dengan yang dikenakan oleh dua patung lilin lainnya, dan riasan di wajahnya belum dibersihkan."
  },
  AvgDialog_18943_Content_4 = {
    Text = "Apakah benar-benar Nona Mason? Eh, ada sesuatu di lehernya…"
  },
  AvgDialog_18943_Content_5 = {
    Text = "Borg besi hampir menembus leher yang putih, dengan sebuah permata berwarna merah darah tersemat di atasnya."
  },
  AvgDialog_18943_Content_6 = {
    Text = "Entah mengapa, kamu tampak seperti terpesona, dengan penuh rasa ingin tahu memandangi cahaya yang berkilauan di atas permata."
  },
  AvgDialog_18943_Content_7 = {
    Text = "<Shake:Hihi……berkilauan, berkilauan…>"
  },
  AvgDialog_18943_Content_8 = {
    Text = "<Shake: Haus sekali, haus sekali… Beri aku, beri aku…>"
  },
  AvgDialog_18943_Content_9 = {
    Text = "Kepala... kepala terasa pusing..."
  },
  AvgDialog_18944_Content_1 = {
    Text = "Tiga aturan"
  },
  AvgDialog_18944_Content_10 = {
    Text = "Dia adalah tamu di Museum Lilin, bukan objek dari Penyelidikan kita."
  },
  AvgDialog_18944_Content_11 = {
    Text = "Saya ingin menekankan sekali lagi, kami adalah tamu yang datang untuk melakukan penyelidikan di museum lilin…"
  },
  AvgDialog_18944_Content_12 = {
    Text = "Jangan bertindak gegabah, dan jangan katakan hal-hal yang tidak pantas — sudah kukatakan seratus kali, telingaku sudah kapalan!"
  },
  AvgDialog_18944_Content_13 = {
    Text = "Baiklah, sepertinya semuanya sudah jelas. Kalau begitu, mari kita masuk."
  },
  AvgDialog_18944_Content_14 = {
    Text = [[
21:55, Museum Lilin Rogers
Ruang Depan]]
  },
  AvgDialog_18944_Content_15 = {
    Text = "Barang-barang di dalam gedung tampak usang, setiap tarikan napas dipenuhi oleh debu kering yang beterbangan, dan bau busuk samar-samar terus menguar di sekitarnya."
  },
  AvgDialog_18944_Content_16 = {
    Text = "Seorang gadis duduk di meja depan, asyik membolak-balik majalah berjudul \"Panduan Pemeliharaan Hewan\"."
  },
  AvgDialog_18944_Content_17 = {
    Text = "Selamat malam, Nyonya. Permisi, apakah ini Museum Lilin Rogers?"
  },
  AvgDialog_18944_Content_19 = {
    Text = "Bolehkah kami masuk untuk melihat-lihat?"
  },
  AvgDialog_18944_Content_2 = {Text = "Ting~"},
  AvgDialog_18944_Content_21 = {
    Text = "Hmmm hmmm, lalala~"
  },
  AvgDialog_18944_Content_22 = {
    Text = "Sayang sekali, wanita ini sepertinya mengalami sedikit gangguan pendengaran. Mari kita masuk saja."
  },
  AvgDialog_18944_Content_23 = {
    Text = "Menyebalkan, begitu kasar dari awal. Jika kamu mencoba menarik perhatian orang..."
  },
  AvgDialog_18944_Content_24 = {
    Text = "Kalau begitu, kamu berhasil, sayang~"
  },
  AvgDialog_18944_Content_26 = {
    Text = "Puff. Sayang...?"
  },
  AvgDialog_18944_Content_27 = {
    Text = "Pertama kali bertemu, saya adalah pengelola Museum Lilin Rogers, panggil saja saya Pandia~"
  },
  AvgDialog_18944_Content_28 = {
    Text = "Para hadirin yang datang larut malam, apakah untuk mengagumi seni, membersihkan Jiwa, atau seperti beberapa mahasiswa kedokteran yang tidak tahu diri, datang untuk mencuri bahan?"
  },
  AvgDialog_18944_Content_29 = {
    Text = "...Mahasiswa kedokteran? Mencuri bahan?"
  },
  AvgDialog_18944_Content_3 = {
    Text = "Saat membuka pintu, rasa pusing yang kuat langsung menyerangmu."
  },
  AvgDialog_18944_Content_30 = {
    Text = "Aduh! Apakah... ini untuk mencari orang @2?"
  },
  AvgDialog_18944_Content_31 = {
    Text = "<Gray: Eh, tadi kesadaranku sepertinya menyaring beberapa hal yang tidak bersih…>"
  },
  AvgDialog_18944_Content_32 = {
    Text = "Kami adalah pengikut setia Tuan Rogers, datang jauh-jauh untuk melihat karya besarnya, bo, bo… oh ya!"
  },
  AvgDialog_18944_Content_33 = {
    Text = "<Big:《Musim Semi Laut Baltik》!>"
  },
  AvgDialog_18944_Content_34 = {
    Text = "...tidak buruk, setidaknya masih tahu tentang Laut Baltik."
  },
  AvgDialog_18944_Content_35 = {
    Text = "Eh, bukankah itu Laut Baltik? Itu... Bosnia, Barbarossa... Nanas?"
  },
  AvgDialog_18944_Content_36 = {
    Text = "Jenkin, tidak ada yang memaksa kamu untuk bicara di sini."
  },
  AvgDialog_18944_Content_37 = {
    Text = "Maaf, teman saya meskipun tidak terlalu bisa membaca, namun cintanya terhadap seni tidak pernah berkurang sedikit pun."
  },
  AvgDialog_18944_Content_38 = {
    Text = "Maaf, saya koreksi. Ini adalah <Blue:《Primavera》oleh Botticelli>."
  },
  AvgDialog_18944_Content_39 = {
    Text = "Apakah——"
  },
  AvgDialog_18944_Content_4 = {
    Text = "Kamu merasa pandanganmu menjadi gelap, dan sepertinya ada suara dengungan listrik yang samar di telinga."
  },
  AvgDialog_18944_Content_40 = {
    Text = "Sayangnya, tampaknya Rogers sedang keluar malam ini, jadi si kecil pasti akan kecewa."
  },
  AvgDialog_18944_Content_41 = {
    Text = "Apa?! Bagaimana bisa——"
  },
  AvgDialog_18944_Content_42 = {Text = "Jenkin."},
  AvgDialog_18944_Content_43 = {
    Text = [[
Huh, tidak apa-apa. Orang itu... 
 Bukan, jika Tuan Rogers tidak ada, kita juga bisa berkeliling dengan bebas...]]
  },
  AvgDialog_18944_Content_44 = {Text = "Ngh..."},
  AvgDialog_18944_Content_45 = {
    Text = [[
"Spring" adalah mahakarya Rogers yang menggabungkan semangat, bakat, dan kegilaan menjadi satu kesatuan! 
Mengingat selera seni kalian cukup baik...]]
  },
  AvgDialog_18944_Content_46 = {
    Text = "Asalkan kalian adalah tamu yang mematuhi aturan, kalian juga bisa diizinkan masuk, lho."
  },
  AvgDialog_18944_Content_47 = {
    Text = "Jadi, para kekasih kecilku, apakah kalian tamu yang mematuhi aturan?"
  },
  AvgDialog_18944_Content_48 = {Text = "Ya"},
  AvgDialog_18944_Content_49 = {
    Text = "Hmm… jawaban yang sangat membosankan, ya."
  },
  AvgDialog_18944_Content_5 = {
    Text = "Kemudian kamu mencium sebuah aroma — perpaduan antara bunga violet dan biji kapulaga, dengan sedikit aroma kayu yang khas."
  },
  AvgDialog_18944_Content_50 = {
    Text = "Jadi, domba-domba penurut yang baik, ikuti aku dengan patuh dan jangan banyak bicara."
  },
  AvgDialog_18944_Content_51 = {Text = "Bukan"},
  AvgDialog_18944_Content_52 = {
    Text = [[
Tidak apa-apa, tidak apa-apa. 
Aku paling suka melatih tamu yang tidak patuh~]]
  },
  AvgDialog_18944_Content_53 = {
    Text = "Asalkan diserahkan ke tangan saya, dalam waktu tiga hari, saya jamin kalian akan menjadi seperti anak domba, penurut dan menggemaskan."
  },
  AvgDialog_18944_Content_54 = {
    Text = "Gadis itu membawa kalian ke pintu masuk ruang pameran, lalu menyilangkan kedua tangannya di pinggang dengan sikap seorang pengelola."
  },
  AvgDialog_18944_Content_55 = {
    Text = [[
Dengarkan baik-baik, sayang-sayang. 
Ada tiga aturan di sini yang tidak boleh, benar-benar tidak boleh, dilanggar ya~]]
  },
  AvgDialog_18944_Content_56 = {
    Text = "<Yellow:Pertama, jangan menyentuh patung lilin.>"
  },
  AvgDialog_18944_Content_57 = {
    Text = "<Yellow:Kedua, jangan membuka selimut patung lilin.>"
  },
  AvgDialog_18944_Content_58 = {
    Text = "<Yellow:Ketiga, jangan meneteskan darah di Museum Lilin.>"
  },
  AvgDialog_18944_Content_59 = {
    Text = "Tidak lebih, tidak kurang, tepat tiga. Apakah kamu mengerti?"
  },
  AvgDialog_18944_Content_6 = {
    Text = "Mengendus... Sangat harum!"
  },
  AvgDialog_18944_Content_60 = {
    Text = "Benar-benar... aturan yang berbeda dari biasanya. Apakah ini dibuat oleh Tuan Rogers?"
  },
  AvgDialog_18944_Content_61 = {
    Text = "Hihi, rahasia~"
  },
  AvgDialog_18944_Content_62 = {
    Text = "Ck, apa maksudnya ini."
  },
  AvgDialog_18944_Content_63 = {
    Text = "<SmallShake:Jika aku ingin diam-diam melakukan sesuatu yang jahat, kamu juga tidak akan menyadarinya…>"
  },
  AvgDialog_18944_Content_64 = {
    Text = [[
Astaga, tikus kecil yang tidak patuh ini benar-benar membuat orang merasa bercampur antara suka dan benci. 
Aku akan memberi kalian sedikit petunjuk.]]
  },
  AvgDialog_18944_Content_65 = {
    Text = "Jangan terlalu pintar sendiri."
  },
  AvgDialog_18944_Content_66 = {
    Text = "Melanggar ketiga aturan ini akan membawa konsekuensi yang seratus kali lebih parah daripada menjatuhkan kotak bedak nenekmu, bahkan seribu kali lebih buruk."
  },
  AvgDialog_18944_Content_67 = {
    Text = "Huh, berpura-pura misterius."
  },
  AvgDialog_18944_Content_68 = {
    Text = [[
Ngomong-ngomong, di museum ini tidak ada layanan pemandu, lho. 
 Jika terjadi sesuatu pada para tamu manis kita..]]
  },
  AvgDialog_18944_Content_69 = {
    Text = "Akibat ditanggung sendiri."
  },
  AvgDialog_18944_Content_70 = {
    Text = "Selanjutnya, silakan nikmati waktu berkeliling pameran dengan bebas~"
  },
  AvgDialog_18944_Content_8 = {
    Text = "Wanita itu melenggak-lenggok dengan gerakan yang anggun, berjalan perlahan melewati kalian."
  },
  AvgDialog_18944_Content_9 = {
    Text = "Hei, siapa itu——"
  },
  AvgDialog_18945_Content_1 = {
    Text = "Ditemukan,\"Chun\"!"
  },
  AvgDialog_18945_Content_2 = {
    Text = "Kalian menatap ke arah yang ditunjukkan oleh kedua puluh empat."
  },
  AvgDialog_18945_Content_3 = {
    Text = "Patung lilin dengan sikap anggun mengenakan rok tipis seperti sayap cicada, sedang menari bersama di bawah cahaya bulan yang berwarna merah."
  },
  AvgDialog_18945_Content_4 = {
    Text = "Jika bukan karena senyuman mereka yang terdistorsi dan riasan di wajah mereka yang luntur akibat menangis, ini seharusnya menjadi karya seni yang menenangkan jiwa."
  },
  AvgDialog_18945_Content_5 = {
    Text = "Kurang satu."
  },
  AvgDialog_18945_Content_6 = {
    Text = "Mason berperan sebagai Dewi Kesucian Celena, seharusnya berada di tengah."
  },
  AvgDialog_18945_Content_7 = {Text = "Tolong..."},
  AvgDialog_18945_Content_8 = {
    Text = "Dari sudut terdengar suara panggilan minta tolong yang lemah."
  },
  AvgDialog_18945_Content_9 = {
    Text = "To……tolong aku……"
  },
  AvgDialog_18946_Content_1 = {
    Text = [[
22:30, Museum Lilin Rogers
Ruang Depan]]
  },
  AvgDialog_18946_Content_10 = {
    Text = "Patung lilin? Tapi bukankah dia baru saja berbicara dengan kita?"
  },
  AvgDialog_18946_Content_11 = {
    Text = "Hei! Jangan berpura-pura mati di hadapanku!"
  },
  AvgDialog_18946_Content_12 = {
    Text = "<Italic:Hihi……>"
  },
  AvgDialog_18946_Content_13 = {
    Text = "Bayangan hitam yang bersembunyi di sudut melintas dengan cepat dan mendorong Jenkin dengan keras."
  },
  AvgDialog_18946_Content_14 = {
    Text = "Apa suara itu... Hei!"
  },
  AvgDialog_18946_Content_15 = {
    Text = "Jenkin tanpa diduga jatuh ke arah Pandia. Begitu menyentuh, dia tersedot kuat-kuat ke dalam pusaran yang lengket dan lembut."
  },
  AvgDialog_18946_Content_16 = {
    Text = "Ugh! Siapa, <Big:siapa yang mendorongku ——>"
  },
  AvgDialog_18946_Content_17 = {
    Text = "Jenkin secara refleks menarik kembali tangannya. Saat tersadar, telapak tangannya terasa dingin dan lembap."
  },
  AvgDialog_18946_Content_18 = {
    Text = "Yang erat dipegang di tangannya adalah sebuah usus yang terbuat dari lilin."
  },
  AvgDialog_18946_Content_19 = {
    Text = "<Big:Aaaaa——!!>"
  },
  AvgDialog_18946_Content_2 = {
    Text = "Nona Pandia, bolehkah saya meminjam telepon sebentar? Kami kehilangan kontak dengan teman-teman."
  },
  AvgDialog_18946_Content_20 = {
    Text = "Cicit cicit!!"
  },
  AvgDialog_18946_Content_21 = {
    Text = "<Shake:Ya Tuhan, seharusnya aku tidak mencuri uang pribadi Nyonya Sarah…>"
  },
  AvgDialog_18946_Content_22 = {
    Text = "<RedShake:Jangan sentuh, jangan sentuh…>"
  },
  AvgDialog_18946_Content_23 = {
    Text = "<RedShake: Sakit, sangat sakit…>"
  },
  AvgDialog_18946_Content_24 = {
    Text = "Krek, krek, krek, krek…"
  },
  AvgDialog_18946_Content_25 = {
    Text = "Dari tubuh Pandia terdengar suara sendi bergerak perlahan, berdetak secara teratur seperti napas."
  },
  AvgDialog_18946_Content_26 = {
    Text = "<Red:\"Patung lilin tidak boleh disentuh.\">"
  },
  AvgDialog_18946_Content_27 = {
    Text = "Bola matanya terus bergerak, dan sudut bibirnya yang menyeringai tampak sangat aneh."
  },
  AvgDialog_18946_Content_28 = {
    Text = "<Red:Aturan pertama museum lilin: Jangan menyentuh patung lilin.>"
  },
  AvgDialog_18946_Content_29 = {
    Text = "Sekarang sudah hancur, lho. Kalian ini, benar-benar ceroboh."
  },
  AvgDialog_18946_Content_30 = {
    Text = "Kamu, kamu berbuat curang! Baru saja jelas ada orang yang mendorongku!"
  },
  AvgDialog_18946_Content_31 = {
    Text = "Aduh, aduh. Tikus kecil yang berkilah sama sekali tidak patuh~"
  },
  AvgDialog_18946_Content_32 = {
    Text = [[
Tidak hanya tidak penurut, tetapi juga sangat kasar. 
Aku sedang tidur dengan tenang, tapi kalian malah mengosongkan perutku.]]
  },
  AvgDialog_18946_Content_33 = {
    Text = "Perutku kosong sekarang, aku merasa malu~"
  },
  AvgDialog_18946_Content_34 = {
    Text = "Pandia memiringkan kepalanya dan dengan manis berkedip kepada kalian."
  },
  AvgDialog_18946_Content_35 = {
    Text = "Lalu, para tamu yang kasar——"
  },
  AvgDialog_18946_Content_36 = {
    Text = "<Red:Selamat datang di taman hiburan kami.>"
  },
  AvgDialog_18946_Content_37 = {
    Text = "Setelah Pandia berbicara, api lilin di perutnya tiba-tiba berkobar, membakar tubuhnya menjadi sebentuk lilin minyak yang transparan."
  },
  AvgDialog_18946_Content_38 = {
    Text = "Semua lampu di dalam gedung padam secara bersamaan, dan kegelapan perlahan jatuh seperti tirai di atas panggung."
  },
  AvgDialog_18946_Content_39 = {
    Text = "Dung——Dung——Dung——"
  },
  AvgDialog_18946_Content_4 = {
    Text = "Kenapa orang ini terus saja melamun?"
  },
  AvgDialog_18946_Content_40 = {
    Text = "Lonceng berbunyi dua belas kali. Tanpa terasa, waktu telah mencapai tengah malam."
  },
  AvgDialog_18946_Content_41 = {
    Text = "Suara gemerisik semakin jelas. Saat kembali sadar, patung-patung lilin sudah sepenuhnya mengelilingi kamu."
  },
  AvgDialog_18946_Content_42 = {
    Text = "Mereka tertawa terkekeh, dengan nada yang diperpanjang bergema di ruang pameran yang kosong."
  },
  AvgDialog_18946_Content_43 = {
    Text = "<RedShake: Hihiihii……>"
  },
  AvgDialog_18946_Content_44 = {
    Text = "<RedShake:Makan, makan semuanya!!!>"
  },
  AvgDialog_18946_Content_5 = {
    Text = "Jenkin mengulurkan tangannya dan melambaikannya di depan Pandia, lalu menarik beberapa wajah lucu ke arahnya."
  },
  AvgDialog_18946_Content_6 = {
    Text = "<Big:Le——he——ha! Babi bodoh! Buruk rupa!>"
  },
  AvgDialog_18946_Content_8 = {
    Text = "Hmm, sangat membosankan."
  },
  AvgDialog_18946_Content_9 = {
    Text = "Sebelumnya, cahaya di ruang depan terlalu redup. Setelah diperhatikan dengan seksama, sepertinya dia... adalah patung lilin."
  },
  AvgDialog_18947_Content_1 = {
    Text = "Takutkah kamu, Cokelat? Sekarang hanya ada kamu dan aku."
  },
  AvgDialog_18947_Content_2 = {
    Text = "Cik, cik cik! (Cokelat tidak takut, ayo semangat!)"
  },
  AvgDialog_18947_Content_3 = {
    Text = "Awooo——!!"
  },
  AvgDialog_18947_Content_4 = {
    Text = "Astaga, tak disangka masih ada monster di sini... penampilannya sangat aneh, seolah-olah sebagian besar tubuhnya tidak terlihat."
  },
  AvgDialog_18947_Content_5 = {
    Text = "Cicit, cicit cicit... (%player%{Male=tuan,Female=nyonya} pernah berkata bahwa orang biasa seperti kita dan tikus biasa tidak dapat melihat apa yang disebut Rongrong. Cicit.)"
  },
  AvgDialog_18947_Content_6 = {
    Text = "Apa pun itu, jika tidak bisa menang, lebih baik lari! Ini adalah keahlian utamaku!"
  },
  AvgDialog_18947_Content_7 = {
    Text = "Cokelat, cepat ikuti! Kita harus segera keluar dengan satu usaha penuh!"
  },
  AvgDialog_18947_Content_8 = {
    Text = "Cuit! (Eh, sebentar lagi cuit!)"
  },
  AvgDialog_18948_Content_1 = {
    Text = "AAAAAAH——!!"
  },
  AvgDialog_18948_Content_10 = {
    Text = "Siapa aku……"
  },
  AvgDialog_18948_Content_11 = {
    Text = "Ya... siapa aku sebenarnya."
  },
  AvgDialog_18948_Content_12 = {
    Text = "Nama, sudah lama tidak ingat lagi…"
  },
  AvgDialog_18948_Content_13 = {
    Text = "Ini adalah wajah baru yang kubuat khusus untukmu. Apakah kamu menyukainya?"
  },
  AvgDialog_18948_Content_14 = {
    Text = "Ini... siapa? Monster di cermin, siapakah dia?"
  },
  AvgDialog_18948_Content_15 = {
    Text = "Siapa kamu, siapa orang di cermin? Semua ini tidak penting."
  },
  AvgDialog_18948_Content_16 = {
    Text = "Lupakan masa lalumu, itu hanyalah tumpukan kertas tak berguna."
  },
  AvgDialog_18948_Content_17 = {
    Text = "Ingatlah nomor eksperimenmu, <Blue:24>—— itu akan menyertaimu seumur hidup."
  },
  AvgDialog_18948_Content_18 = {
    Text = "<Shake:Hidupku... hancur, semuanya hancur...>"
  },
  AvgDialog_18948_Content_19 = {
    Text = "Jika kamu menyebut kehidupanmu yang menyedihkan dan tanpa makna sebagai \"kehidupan\"…"
  },
  AvgDialog_18948_Content_2 = {
    Text = "Wanita itu dengan kuat mencekik lehernya sendiri. Otot-otot wajahnya terus berkedut, bola matanya bergerak cepat, hampir saja melotot keluar dari rongganya."
  },
  AvgDialog_18948_Content_20 = {
    Text = "Ya, memang sudah menjauh darimu."
  },
  AvgDialog_18948_Content_21 = {
    Text = "Tidak, tidak… aku mengutuk kalian!"
  },
  AvgDialog_18948_Content_22 = {
    Text = "<Red:Aku mengutuk kalian semua,><RedBig:Kalian akan masuk Neraka!>"
  },
  AvgDialog_18948_Content_24 = {
    Text = "24... Aku ingat sekarang."
  },
  AvgDialog_18948_Content_25 = {
    Text = "Pada pertemuan pertama, kalian bisa memanggil saya 24."
  },
  AvgDialog_18948_Content_26 = {
    Text = "24? Apa gelar aneh ini?"
  },
  AvgDialog_18948_Content_27 = {
    Text = "24 meringkuk di sudut dinding, menggelengkan kepalanya dengan keras, tidak mau mengucapkan sepatah kata pun lagi."
  },
  AvgDialog_18948_Content_29 = {
    Text = [[
Sepertinya gadis ini tidak mau membicarakan masa lalunya. Bagaimana dengan Museum Lilin? 
Mau berbicara dengan kami?]]
  },
  AvgDialog_18948_Content_3 = {
    Text = "Seperti kondisi roh yang tidak terkendali... %player%, segera stabilkan dia dengan Kunci perak!"
  },
  AvgDialog_18948_Content_30 = {
    Text = "Sebagai contoh, \"tiga aturan\"…"
  },
  AvgDialog_18948_Content_31 = {
    Text = "<Big:Ssst!!>"
  },
  AvgDialog_18948_Content_32 = {
    Text = "Jangan berbicara dengan suara keras, <Blue:\"mereka\"> akan mendengarnya."
  },
  AvgDialog_18948_Content_33 = {
    Text = "\"Apa yang dimaksud dengan 'mereka'?\""
  },
  AvgDialog_18948_Content_34 = {
    Text = "24 dengan waspada melihat ke kiri dan kanan, lalu mengubah nada suaranya menjadi lebih misterius dan mendekati kalian."
  },
  AvgDialog_18948_Content_35 = {
    Text = "<Shake:Mereka, itulah mereka…>"
  },
  AvgDialog_18948_Content_36 = {
    Text = "\"Tiga aturan\" adalah tabu di museum lilin ini, dan mereka sama sekali tidak boleh dilanggar."
  },
  AvgDialog_18948_Content_37 = {
    Text = "Huh, aku sudah mematahkan salah satu tadi."
  },
  AvgDialog_18948_Content_38 = {
    Text = "<Big:Apa?!!!>"
  },
  AvgDialog_18948_Content_39 = {
    Text = "Kalian, bagaimana bisa kalian begitu ceroboh?!"
  },
  AvgDialog_18948_Content_4 = {Text = "Mengerti!"},
  AvgDialog_18948_Content_40 = {
    Text = "Eh, itu salahku. Selain menghidupkan patung lilin, apa konsekuensi lain dari melanggar aturan?"
  },
  AvgDialog_18948_Content_41 = {
    Text = "<Shake:Celaka, mereka akan datang mencariku, akan datang mencariku…>"
  },
  AvgDialog_18948_Content_42 = {
    Text = "24 cemas menarik-narik rambut panjangnya, tak disangka ia malah mencabut rambutnya beserta kulit kepalanya."
  },
  AvgDialog_18948_Content_43 = {
    Text = "Hei... hei! Apakah kamu tidak merasakan sakit?"
  },
  AvgDialog_18948_Content_44 = {
    Text = "<Shake: Mencariku, mencariku…>"
  },
  AvgDialog_18948_Content_45 = {
    Text = "Lengan berwarna merah tua perlahan muncul dari tubuhnya, dengan lembut melingkari leher, lalu ——"
  },
  AvgDialog_18948_Content_46 = {
    Text = "Membekap lehernya hingga patah."
  },
  AvgDialog_18948_Content_47 = {
    Text = "Aaa, kepalanya——!!"
  },
  AvgDialog_18948_Content_48 = {
    Text = "24 seperti boneka yang kehilangan daya, kepalanya terkulai berat ke bawah, rambut panjangnya hampir menutupi seluruh wajah."
  },
  AvgDialog_18948_Content_49 = {
    Text = "Klik. Klik. Klik."
  },
  AvgDialog_18948_Content_5 = {
    Text = "Kamu dengan cepat mengeluarkan kunci perak dari dadamu, cahaya redup yang dingin melintasi langit malam."
  },
  AvgDialog_18948_Content_50 = {
    Text = "Diiringi suara tulang patah dan menyusun ulang, dia mengangkat kepalanya lagi, namun Ekspresinya jauh berbeda dari sebelumnya."
  },
  AvgDialog_18948_Content_51 = {
    Text = "Haha... hahahaha..."
  },
  AvgDialog_18948_Content_52 = {
    Text = "<Red:Membunuh…>"
  },
  AvgDialog_18948_Content_53 = {
    Text = "<BigBoldRed:Saya akan @1 kalian!>"
  },
  AvgDialog_18948_Content_6 = {Text = "Ugh——!"},
  AvgDialog_18948_Content_7 = {
    Text = "Apa yang terjadi..."
  },
  AvgDialog_18948_Content_8 = {
    Text = "Jangan mendekat, jawab pertanyaan dengan jujur!"
  },
  AvgDialog_18948_Content_9 = {
    Text = "Siapa kamu?"
  },
  AvgDialog_18949_Content_1 = {
    Text = "Cicit, cicit cicit! (Jenkin kecil cepat pergi, Rongrong semakin banyak, sudah menyebar ke dalam ventilasi!)"
  },
  AvgDialog_18949_Content_2 = {
    Text = "Tidak bisa pergi... harus segera menyelesaikannya."
  },
  AvgDialog_18949_Content_3 = {
    Text = "Cicit... cicit cicit. (Tapi tubuhmu penuh dengan... ah, lupakan, yang penting kita keluar dulu. Apapun yang terjadi, aku tidak akan meninggalkanmu, cicit.)"
  },
  AvgDialog_18949_Content_4 = {
    Text = "Dengan kata-katamu ini, aku merasa tenang. Terima kasih, Cokelat!"
  },
  AvgDialog_18950_Content_1 = {
    Text = "Akhirnya sampai di ruang kepala perpustakaan! William bilang kunci ada di laci meja."
  },
  AvgDialog_18950_Content_10 = {
    Text = "Tanpa mengindahkan nasihat Cokelat, Jenkin melangkah maju dan membenamkan dirinya ke dalam kegelapan yang tak terlihat di depannya."
  },
  AvgDialog_18950_Content_2 = {
    Text = "Meja dari kayu walnut miring mengambang di atas sungai hitam, seperti sebuah pulau terpencil."
  },
  AvgDialog_18950_Content_3 = {
    Text = "Mengendus-endus… cuit cuit! (Jangan pergi ke sana! Di sini penuh dengan bau-bauan aneh, cuit!)"
  },
  AvgDialog_18950_Content_5 = {
    Text = "<Yellow:Saya harus pergi. Kak dan %player% masih menungguku.>"
  },
  AvgDialog_18950_Content_6 = {
    Text = "<Shake:Kriuk, kriuk… (Tapi. Tapi…)>"
  },
  AvgDialog_18950_Content_7 = {
    Text = [[
Menyentuh sedikit saja, seharusnya tidak apa-apa kan? 
Paling banter sakit, dan sekolah itu pasti akan memberi saya perawatan sembuh gratis.]]
  },
  AvgDialog_18950_Content_8 = {
    Text = "Siapa tahu aku bisa mendapatkan pahala meski terluka, mereka mungkin akan memberi kita sejumlah besar uang."
  },
  AvgDialog_18950_Content_9 = {
    Text = "Doakan aku beruntung, Cokelat."
  },
  AvgDialog_18951_Content_1 = {
    Text = "Hah... hah... monster-monster itu ada di mana-mana."
  },
  AvgDialog_18951_Content_2 = {
    Text = "Sekarang sudah tidak ada jalan untuk mundur lagi. Cokelat, bawa kunci dan pergilah lebih dulu."
  },
  AvgDialog_18951_Content_3 = {
    Text = "Cicit! Cicit cicit cicit… (Apa maksudnya, katanya kita akan pergi membeli banyak keju bersama! Kali ini kita juga membawa banyak barang antik, setelah keluar kita akan dapat uang, cicit!)"
  },
  AvgDialog_18951_Content_4 = {
    Text = "Cicit! (Tidak perlu tinggal di rumah tua lagi, cicit!)"
  },
  AvgDialog_18951_Content_5 = {
    Text = "Baiklah... aku akan bertahan sebentar lagi, mari kita keluar bersama."
  },
  AvgDialog_18952_Content_1 = {
    Text = "<Shake:Keluar... biarkan aku keluar...>"
  },
  AvgDialog_18952_Content_2 = {
    Text = "<Shake: Kakak, Ramona, %player%… semua masih menungguku…>"
  },
  AvgDialog_18952_Content_3 = {
    Text = "Kamu tidak pernah sendirian. Kamu masih memiliki aku, memiliki kita."
  },
  AvgDialog_18952_Content_4 = {
    Text = "Masih banyak hal yang perlu kupelajari darimu, <Blue:\"Sang Master Bertahan Hidup di Jalanan\">."
  },
  AvgDialog_18952_Content_5 = {
    Text = "Setelah susah payah mendapatkan kunci… tidak bisa berhenti di sini."
  },
  AvgDialog_18952_Content_6 = {
    Text = "Ciiit... (Jenkin kecil...)"
  },
  AvgDialog_18952_Content_7 = {
    Text = "Jangan menatapku seperti itu, Cokelat... Pertempuran belum berakhir."
  },
  AvgDialog_18952_Content_8 = {
    Text = "Jika aku mati di sini, ingatlah untuk membawa kunci kepada semua orang, oke."
  },
  AvgDialog_18952_Content_9 = {
    Text = "... cicit, cicit. (... Baiklah, cicit. Aku berjanji padamu, Jenkin kecil.)"
  },
  AvgDialog_18953_Content_1 = {
    Text = "41,42,43,45..."
  },
  AvgDialog_18953_Content_2 = {
    Text = "Eh, ke mana perginya No. 44?"
  },
  AvgDialog_18953_Content_3 = {
    Text = "41,42,43,45..."
  },
  AvgDialog_18954_Content_1 = {
    Text = "Kenapa kamu lagi? Apakah pelajaran sebelumnya belum cukup?"
  },
  AvgDialog_18954_Content_2 = {
    Text = "Kamu... apa yang kamu katakan?!"
  },
  AvgDialog_18954_Content_3 = {
    Text = "Coba tantang kami lagi, lain kali yang hilang bukan hanya kunci saja!"
  },
  AvgDialog_18954_Content_4 = {
    Text = "Terlalu berlebihan..."
  },
  AvgDialog_18954_Content_5 = {
    Text = "Cepat tangkap semuanya!"
  },
  AvgDialog_18955_Content_1 = {
    Text = "Di Balik Kerudung"
  },
  AvgDialog_18955_Content_10 = {
    Text = "Tidak, jangan tinggalkan aku sendirian…"
  },
  AvgDialog_18955_Content_11 = {
    Text = "Anakku… Sebelum pergi, aku punya Hadiah untukmu."
  },
  AvgDialog_18955_Content_13 = {
    Text = "Lepaskan mataku dan berikan kepadanya. Biarlah ia berbicara untukmu, biarlah ia mengamati dirimu untukku."
  },
  AvgDialog_18955_Content_14 = {
    Text = "Kamu pasti bisa melangkah lebih jauh dariku, ingatlah——"
  },
  AvgDialog_18955_Content_15 = {
    Text = "Segala penderitaan tidak dapat memberikan kerusakan padamu, apalagi menghancurkanmu."
  },
  AvgDialog_18955_Content_16 = {
    Text = "Mereka akan melebur dalam seni yang kau ciptakan, mencapai keindahan abadi."
  },
  AvgDialog_18955_Content_17 = {
    Text = "Rogers memandang sepasang mata George yang sudah dikenal."
  },
  AvgDialog_18955_Content_18 = {
    Text = "Tuan Patung Lilin... Saya, saya tidak mengerti."
  },
  AvgDialog_18955_Content_19 = {
    Text = "Jika semua penderitaan tidak dapat memberikan kerusakan padaku, lalu mengapa sekarang… aku ingin meneteskan air mata?"
  },
  AvgDialog_18955_Content_2 = {
    Text = "Kemarilah, anak, cepat kemarilah…"
  },
  AvgDialog_18955_Content_20 = {
    Text = "Jawab aku… jawab aku."
  },
  AvgDialog_18955_Content_21 = {
    Text = "<Change>Aaaaaa… Rogers. Rogers…"
  },
  AvgDialog_18955_Content_22 = {
    Text = [[
George membuka mulutnya, namun cairan hitam terus mengalir keluar dari dalamnya. 
 Dia tak akan pernah bisa menjawab pertanyaan itu lagi.]]
  },
  AvgDialog_18955_Content_23 = {
    Text = "Tuan Rogers, tanganmu dan benda-benda itu... sudah menyatu!"
  },
  AvgDialog_18955_Content_24 = {
    Text = "Rogers tidak merespons. Atau lebih tepatnya, dia sudah kehilangan kemampuan untuk merespons."
  },
  AvgDialog_18955_Content_25 = {
    Text = "<Small: Jika kita tidak pergi sekarang, kita semua akan mati di sini…>"
  },
  AvgDialog_18955_Content_27 = {
    Text = "Tuan Rogers, saya tahu Anda pasti akan membenci saya, tapi——"
  },
  AvgDialog_18955_Content_28 = {Text = "BRASSHH!!"},
  AvgDialog_18955_Content_29 = {
    Text = [[
Cambuk panjang melilit lengan Rogers, merobeknya dengan paksa. 
 Darah memancar keluar, mencelupkan pakaian luar Rogers menjadi merah.]]
  },
  AvgDialog_18955_Content_3 = {
    Text = "Patung lilin Tuan...?"
  },
  AvgDialog_18955_Content_30 = {
    Text = "<Red: Aaaah——!!>"
  },
  AvgDialog_18955_Content_31 = {
    Text = "<Red:Tangan, tanganku…>"
  },
  AvgDialog_18955_Content_32 = {
    Text = "George yang kehilangan pegangan erat dijambat oleh patung lilin yang menangis, dan bersama-sama mereka meluncur menuju celah."
  },
  AvgDialog_18955_Content_33 = {
    Text = "<Change>Tidak, jangan..."
  },
  AvgDialog_18955_Content_34 = {
    Text = "Bersama dengan tangan kanan yang pernah menciptakan tak terhitung banyaknya patung lilin, jatuh ke dalam jurang tanpa dasar."
  },
  AvgDialog_18955_Content_35 = {
    Text = "<Red: Aaaaaa——!!>"
  },
  AvgDialog_18955_Content_36 = {
    Text = "<Red:Pandia, apa yang kamu lakukan… tangan saya…>"
  },
  AvgDialog_18955_Content_37 = {
    Text = "Saya akan membawa Tuan Rogers pergi. Leigh, bantu aku menahan mereka!"
  },
  AvgDialog_18955_Content_38 = {Text = "……Eh?"},
  AvgDialog_18955_Content_4 = {
    Text = "Dalam sinar panjang yang kesepian, anak itu berjalan seorang diri."
  },
  AvgDialog_18955_Content_5 = {
    Text = "Dia melintasi lorong, mengikuti suara panggilan, melangkah perlahan hingga akhirnya berdiri di depan pria itu."
  },
  AvgDialog_18955_Content_6 = {
    Text = "Pria itu tenggelam dalam kolam lilin berwarna merah darah, air mata mengalir menyusuri alur-alur berkelok di wajahnya."
  },
  AvgDialog_18955_Content_7 = {
    Text = "Tuan Patung Lilin, apa yang sedang Anda lakukan?!"
  },
  AvgDialog_18955_Content_8 = {
    Text = "Tubuh yang hancur ini masih bisa bertahan sampai sekarang, sungguh sebuah keajaiban…"
  },
  AvgDialog_18955_Content_9 = {
    Text = "Mati dalam lilin adalah tempat peristirahatan terakhir yang paling sempurna yang bisa kubayangkan."
  },
  AvgDialog_18956_Content_1 = {
    Text = "Tidak bisa, jumlah patung lilin terlalu banyak."
  },
  AvgDialog_18956_Content_10 = {
    Text = "Kesadaran terus menyelam lebih dalam, perlahan-lahan hingga menyentuh sesuatu yang aneh ——"
  },
  AvgDialog_18956_Content_11 = {
    Text = "Seperti sesuatu dari kedalaman alam semesta, jauh di luar tahun cahaya. Ia berasal dari masa lalu yang kuno, melintasi tak terhitung bintang dan ruang waktu, membawa pesan yang terasa akrab namun asing dari kejauhan."
  },
  AvgDialog_18956_Content_12 = {
    Text = "<Change>H''s ymg'……\n adalah dirimu……"
  },
  AvgDialog_18956_Content_13 = {
    Text = "Tak terhitung suara-suara tua bergabung menjadi satu, seperti gema orkestra yang bergetar di seluruh ruang angkasa."
  },
  AvgDialog_18956_Content_14 = {
    Text = "Kamu tidak asing dengan bahasanya. \n Ini aneh — ingatlah, nilai bahasa kuno-mu selalu buruk."
  },
  AvgDialog_18956_Content_15 = {
    Text = "<Change>Y' ymg' kadishtu ephainog ephaii……\nAku tahu kamu akan kembali……"
  },
  AvgDialog_18956_Content_16 = {
    Text = "Siapa kamu... siapa kalian?"
  },
  AvgDialog_18956_Content_17 = {
    Text = "Di mana tempat ini?"
  },
  AvgDialog_18956_Content_18 = {
    Text = "Suara itu tidak berniat menjawab pertanyaanmu. Mereka gelisah, berteriak, lalu mengundangmu untuk bergabung."
  },
  AvgDialog_18956_Content_19 = {
    Text = "<Change>Llll nog c'……\nMari pergi bersama……"
  },
  AvgDialog_18956_Content_2 = {
    Text = "Mereka datang lagi, dan lagi, dan lagi!"
  },
  AvgDialog_18956_Content_20 = {
    Text = "Ya uh'@1.\nPir@2…"
  },
  AvgDialog_18956_Content_21 = {
    Text = "Kamu melayang di tengah ruang angkasa yang tak berujung, ribuan meteor melintas di depanmu, lalu memasuki tubuhmu satu per satu."
  },
  AvgDialog_18956_Content_22 = {
    Text = "Mereka membawa suhu yang hampir melelehkan seluruh saluran pencernaanmu. Kamu seperti dipanggang oleh sebuah matahari emas, merasa tubuhmu penuh dengan Kekuatan lagi."
  },
  AvgDialog_18956_Content_23 = {
    Text = "Di tengah aliran kesadaran, suara dingin William bersamaan dengan bunyi tetesan alat yang teratur, samar-samar bergema di telingamu."
  },
  AvgDialog_18956_Content_24 = {Text = "98%, 99…"},
  AvgDialog_18956_Content_25 = {
    Text = "Celah akan segera tertutup... Tahan selama lima menit lagi, %player%."
  },
  AvgDialog_18956_Content_3 = {
    Text = "Tidak——"
  },
  AvgDialog_18956_Content_4 = {
    Text = "Kamu sekali lagi sepenuhnya dibungkus oleh lilin minyak berwarna putih."
  },
  AvgDialog_18956_Content_5 = {
    Text = "Mereka dengan serakah mengisap darah, seakan-akan tidak pernah merasa kenyang, hingga mereka merasakan seberkas rasa aneh dari dalam."
  },
  AvgDialog_18956_Content_6 = {
    Text = "Yang akrab, dekat, dan menjadi milik @2."
  },
  AvgDialog_18956_Content_7 = {
    Text = "Kamu terseret ke dalam pusaran yang dalam dan suram."
  },
  AvgDialog_18956_Content_8 = {
    Text = [[
Memori yang rumit terbentang di hadapanmu seperti lukisan gulung. Bahagia, sedih, menyakitkan... 
Bukan hanya memori milikmu, tetapi juga milik orang lain.]]
  },
  AvgDialog_18956_Content_9 = {
    Text = "Ini... apa..."
  },
  AvgDialog_18957_Content_1 = {
    Text = "Hmm, sedikit lebih rumit daripada yang kubayangkan."
  },
  AvgDialog_18957_Content_10 = {
    Text = "Plak! Plak!"
  },
  AvgDialog_18957_Content_11 = {
    Text = "Kakak, kamu kena tembak!"
  },
  AvgDialog_18957_Content_12 = {
    Text = "Jangan hiraukan aku, cepat pergi."
  },
  AvgDialog_18957_Content_13 = {
    Text = "Tidak, aku tidak pergi… Aku yang menghancurkanmu, aku yang menghancurkan semua orang…"
  },
  AvgDialog_18957_Content_14 = {
    Text = "Kenapa, kenapa harus demi orang sepertiku…"
  },
  AvgDialog_18957_Content_15 = {
    Text = [[
Maafkan aku, Leigh. 
 Selama bertahun-tahun aku mengurungmu di bawah tanah, biarlah aku membayar dengan hidupku.]]
  },
  AvgDialog_18957_Content_16 = {
    Text = "Sekarang kita sudah seimbang."
  },
  AvgDialog_18957_Content_17 = {
    Text = "Ayo pergi, jangan menoleh ke belakang. Hiduplah dengan baik di luar sana…"
  },
  AvgDialog_18957_Content_18 = {
    Text = "Sampai jumpa."
  },
  AvgDialog_18957_Content_19 = {
    Text = "Kakak… aku ingat semuanya, semuanya…"
  },
  AvgDialog_18957_Content_2 = {
    Text = "Leigh, jangan hanya diam dan menonton, kan kita sudah berjanji untuk melindunginya?"
  },
  AvgDialog_18957_Content_20 = {Text = "Leigh…?"},
  AvgDialog_18957_Content_21 = {
    Text = "Aku sudah tahu kalau semua yang dia katakan sehari-hari itu bohong… Membuatku marah, sangat marah!"
  },
  AvgDialog_18957_Content_22 = {
    Text = "Patuhlah berdiri di belakangku dan lakukan bantuan dengan baik, jika berani malas, aku tidak akan memaafkanmu!"
  },
  AvgDialog_18957_Content_4 = {
    Text = "Pandangan Leigh berpindah di antara kalian sejenak, lalu tertuju pada tangan Jenkin dan 24 yang saling bertautan."
  },
  AvgDialog_18957_Content_5 = {
    Text = "Aneh sekali, kalian berdua dengan penampilan seperti ini, selalu membuatku memikirkan hal-hal yang jauh dan…"
  },
  AvgDialog_18957_Content_6 = {
    Text = "Hal yang tidak dikenal.."
  },
  AvgDialog_18957_Content_7 = {
    Text = "Ekstra, ekstra! Menurut sumber terpercaya, <Blue: Saudara Vampir> baru-baru ini terlihat di Londinium!!"
  },
  AvgDialog_18957_Content_8 = {
    Text = "Hanya dengan 5 Pensh, kami akan membawa Anda mengungkap skandal besar keluarga Cavendish! Sudah 23 gelandangan menjadi korban tak berdosa…"
  },
  AvgDialog_18957_Content_9 = {
    Text = "Ketemu! Mereka ada di depan, kali ini kita tidak boleh membiarkan mereka lolos!"
  },
  AvgDialog_18958_Content_1 = {
    Text = "Cokelat Menyerang"
  },
  AvgDialog_18958_Content_10 = {
    Text = "Tidak, tidak apa-apa, Nona Clementine."
  },
  AvgDialog_18958_Content_11 = {
    Text = "Saya sekarang merasa lebih ringan. Suasana hati yang sempat terganggu karena kerusakan patung lilin juga sudah pulih."
  },
  AvgDialog_18958_Content_12 = {
    Text = "Ini, ini adalah kekuatan terapi psikologis, ya? Mirip dengan seni lilin..."
  },
  AvgDialog_18958_Content_13 = {Text = "Tsk."},
  AvgDialog_18958_Content_14 = {
    Text = "George, cepat ucapkan selamat tinggal kepada Nona Clementine."
  },
  AvgDialog_18958_Content_15 = {
    Text = "……Hmph."
  },
  AvgDialog_18958_Content_16 = {
    Text = "Selamat tinggal——Nona Clementine."
  },
  AvgDialog_18958_Content_17 = {
    Text = "<Shake: Hiks hiks… Beginilah keadaannya, bahkan Tuan Lawrence pun…>"
  },
  AvgDialog_18958_Content_18 = {
    Text = "<Shake: Hihihi, bodoh sekali, bodoh sekali…>"
  },
  AvgDialog_18958_Content_19 = {
    Text = "<Shake: Cepat hukum dia, kupas semua kulit wajahnya!>"
  },
  AvgDialog_18958_Content_2 = {
    Text = "Ssst, jangan bersuara."
  },
  AvgDialog_18958_Content_20 = {
    Text = "<Shake:Hukuman! Hukuman! Hukuman…>"
  },
  AvgDialog_18958_Content_21 = {
    Text = "Diam, anak-anakku tersayang."
  },
  AvgDialog_18958_Content_22 = {
    Text = "Benar-benar membingungkan! Ini hanya museum lilin yang tidak mencolok, kenapa semua orang datang kemari."
  },
  AvgDialog_18958_Content_23 = {
    Text = "<Big:Grrrrumm——>"
  },
  AvgDialog_18958_Content_24 = {
    Text = "Huu... hu... hu..."
  },
  AvgDialog_18958_Content_25 = {
    Text = "<Shake:Ya! Suara apa itu! Apakah itu…>"
  },
  AvgDialog_18958_Content_26 = {
    Text = "<Shake:Bangun, harus bangun… Cepat lari!>"
  },
  AvgDialog_18958_Content_28 = {
    Text = "Semua lari? Benar-benar sekumpulan pengecut."
  },
  AvgDialog_18958_Content_29 = {
    Text = "Tuan Rogers, cepat keluarlah, aku baru saja bertemu dengan si kecil George~"
  },
  AvgDialog_18958_Content_3 = {
    Text = "Semua orang langsung terdiam. Tangisan yang tertahan segera berubah menjadi jeritan panjang yang tak henti-hentinya."
  },
  AvgDialog_18958_Content_30 = {
    Text = "Benda-benda itu tidak akan menangis tanpa alasan, pasti karena Anda sudah kembali, kan?"
  },
  AvgDialog_18958_Content_31 = {
    Text = "Malam, selamat malam, Pandia."
  },
  AvgDialog_18958_Content_32 = {
    Text = "Apakah kamu sudah berbicara dengan baik kepada Nona Clementine hari ini? Dia membayar biaya konsultasi dengan harga selangit, lho!"
  },
  AvgDialog_18958_Content_33 = {
    Text = "Pandia, cepat tinggalkan tempat ini! Bawa George bersamamu…"
  },
  AvgDialog_18958_Content_34 = {
    Text = "Meninggalkan tempat ini? Omong kosong apa yang kau bicarakan, Tuan Rogers?"
  },
  AvgDialog_18958_Content_35 = {
    Text = "Kami sudah me... me... menahan seorang Penyelidik, dan sekarang muncul yang lain lagi…"
  },
  AvgDialog_18958_Content_36 = {
    Text = "Saya punya firasat yang tidak enak... Kali ini, sepertinya saya benar-benar menjadi target Mythag..."
  },
  AvgDialog_18958_Content_37 = {
    Text = "Tenang saja, Tuan Rogers, serahkan semua urusan sepele ini kepada Pandia!"
  },
  AvgDialog_18958_Content_38 = {
    Text = "<SmallShake:Saya sudah menempatkan mata-mata di antara mereka, Xiao George juga akan membantu, dijamin seratus persen aman!>"
  },
  AvgDialog_18958_Content_39 = {
    Text = "Apakah kamu baru saja mengatakan bahwa Kepala Museum sudah kembali?"
  },
  AvgDialog_18958_Content_4 = {
    Text = "Setengah ratapan, setengah teror, seperti gema yang berasal dari Neraka."
  },
  AvgDialog_18958_Content_40 = {
    Text = "Bisakah aku menganggap ini sebagai tujuanmu? Menunda waktu bersama kami sampai Rogers kembali."
  },
  AvgDialog_18958_Content_41 = {
    Text = "Ya, ya! Aku telah melakukan banyak dosa yang tak terampuni..."
  },
  AvgDialog_18958_Content_42 = {
    Text = "<Big:Silakan hukum saya dengan keras!>"
  },
  AvgDialog_18958_Content_44 = {
    Text = "Secara pribadi, aku berharap kau bukan Miss Mason, sehingga aku bisa memukulmu tanpa ragu."
  },
  AvgDialog_18958_Content_45 = {
    Text = "%player%, monster bawah tanah, mau menyelidiki bersama?"
  },
  AvgDialog_18958_Content_46 = {Text = "Tentu saja"},
  AvgDialog_18958_Content_47 = {
    Text = "Yang terkurung di bawah mungkin adalah korban Rogers, tidak bisa diabaikan begitu saja."
  },
  AvgDialog_18958_Content_48 = {
    Text = "Hmm. Coba cari di sekitar sini, lihat apakah ada lorong yang menuju ke bawah tanah."
  },
  AvgDialog_18958_Content_49 = {
    Text = "Aku menolak"
  },
  AvgDialog_18958_Content_5 = {
    Text = "Entah berapa lama telah berlalu, suara itu perlahan-lahan mulai mereda."
  },
  AvgDialog_18958_Content_50 = {
    Text = "Intuisi saya mengatakan bahwa ada yang tidak beres dengan suara itu, jadi kita tidak bisa langsung pergi ke sana."
  },
  AvgDialog_18958_Content_51 = {
    Text = "Jangan lupa, Penjaga. Kita di sini untuk menyelidiki ketidakberesan ini, bukan untuk berwisata."
  },
  AvgDialog_18958_Content_52 = {
    Text = "Harus diakui, Ramona benar. Di hadapan insting untuk bertahan hidup, kamu sudah sepenuhnya melupakan \"Kode Etik Penyelidik\"."
  },
  AvgDialog_18958_Content_53 = {
    Text = "<SmallShake: Kamu, kamu benar…>"
  },
  AvgDialog_18958_Content_54 = {
    Text = "Hmm. Coba cari di sekitar sini, lihat apakah ada lorong yang bisa menuju ke bawah tanah."
  },
  AvgDialog_18958_Content_55 = {
    Text = "Ada lubang tersembunyi di sini, sepertinya bisa menuju ke bawah tanah!"
  },
  AvgDialog_18958_Content_56 = {
    Text = "Yah——hei——"
  },
  AvgDialog_18958_Content_57 = {
    Text = "Kalian telah menggunakan seluruh kekuatan kalian, namun hanya bisa membukanya sedikit celah."
  },
  AvgDialog_18958_Content_58 = {
    Text = "Tidak bisa, benar-benar tidak bisa dibuka."
  },
  AvgDialog_18958_Content_59 = {
    Text = "Pada saat-saat kritis seperti ini, tentu saja kita yang harus diandalkan."
  },
  AvgDialog_18958_Content_6 = {
    Text = "Itu... itu apa..."
  },
  AvgDialog_18958_Content_60 = {
    Text = "Cokelat, turunlah!"
  },
  AvgDialog_18958_Content_61 = {Text = "Cit cit!"},
  AvgDialog_18958_Content_7 = {
    Text = [[
Oh ya. Tampaknya Pemimpin Perpustakaan telah kembali. 
Para <Blue:binatang peliharaan kecil> di bawah tanah sangat merindukannya.]]
  },
  AvgDialog_18958_Content_8 = {
    Text = [[
23:00, Klinik Dokter Fairfax
Sejam yang lalu]]
  },
  AvgDialog_18958_Content_9 = {
    Text = [[
Waktunya telah tiba. Terima kasih atas kerja samanya, Tuan Rogers. 
Saya meminta maaf atas sedikit kesalahpahaman yang terjadi tadi.]]
  },
  AvgDialog_18959_Content_1 = {
    Text = "Catatan Akhir"
  },
  AvgDialog_18959_Content_10 = {
    Text = "Jangan lupakan aku, ya."
  },
  AvgDialog_18959_Content_11 = {
    Text = "Jika tidak ada Perak, setelah mati mungkin benar-benar tidak ada apa-apa… Mungkinkah ada seseorang yang sengaja mengambil Perak?"
  },
  AvgDialog_18959_Content_12 = {
    Text = "Atau mungkin ada detail lain yang terlewatkan olehku…"
  },
  AvgDialog_18959_Content_13 = {
    Text = "Boneka mengatakan bahwa akhir-akhir ini tingkat kehadiranmu di kelas sangat rendah, ternyata kamu bersembunyi di sini untuk berbicara dari hati ke hati dengan guru?"
  },
  AvgDialog_18959_Content_14 = {
    Text = "Dekan Czort!"
  },
  AvgDialog_18959_Content_15 = {
    Text = "Jangan khawatir, aku tidak datang untuk memeriksa kehadiran. William sudah kembali hari ini, mungkin kamu bisa mengobrol dengannya?"
  },
  AvgDialog_18959_Content_16 = {
    Text = "Dengar, dia sudah melacak keberadaan Rogers dan menyerahkannya kepada Komite untuk ditangani."
  },
  AvgDialog_18959_Content_17 = {Text = "!!"},
  AvgDialog_18959_Content_18 = {
    Text = "Mengerti… Saya akan bertanya."
  },
  AvgDialog_18959_Content_19 = {
    Text = "Selamat tinggal, Guru Alistair. Selamat tinggal, Dekan Czort."
  },
  AvgDialog_18959_Content_2 = {
    Text = [[
Sebulan kemudian
Mythag, Zona Terbatas A-001]]
  },
  AvgDialog_18959_Content_20 = {
    Text = "Langkah kaki semakin menjauh, kemudian terdengar suara berat lift yang sedang beroperasi."
  },
  AvgDialog_18959_Content_21 = {
    Text = "Sudah sebulan, {Male=dia,Female=dia} masih belum bisa menerima kenyataan bahwa Jenkin telah pergi."
  },
  AvgDialog_18959_Content_22 = {
    Text = [[
{Male=Dia,Female=Dia} menyalahkan dirinya sendiri. 
 Ini adalah pelajaran wajib yang dialami setiap Penyelidik saat baru memulai, beri {Male=dia,Female=dia} sedikit waktu.]]
  },
  AvgDialog_18959_Content_23 = {
    Text = "Sudah lama tidak bertemu, Alistair. Bagaimana kabarmu akhir-akhir ini?"
  },
  AvgDialog_18959_Content_24 = {
    Text = "Berbicara tentang \"perasaan\" dengan orang tua sepertiku tampaknya agak berlebihan."
  },
  AvgDialog_18959_Content_25 = {
    Text = "Dari reaksi %player% tadi, apakah kamu sekarang sudah menjadi dekan Mythag?"
  },
  AvgDialog_18959_Content_26 = {
    Text = "Wakil Dekan. Dan… sepertinya informasimu sudah terlalu ketinggalan."
  },
  AvgDialog_18959_Content_27 = {
    Text = "Mohon maaf, semua orang tampaknya tidak terlalu suka berbicara tentang Mythag denganku. \nBagaimanapun, selamat atas promosi jabatanmu — ini memang pantas kau dapatkan."
  },
  AvgDialog_18959_Content_28 = {
    Text = "Heh… ini bukan tugas yang mudah."
  },
  AvgDialog_18959_Content_29 = {
    Text = "Orang-orang mulai melupakan mereka yang tewas akibat Pelarutan."
  },
  AvgDialog_18959_Content_3 = {
    Text = "Dengar-dengar kamu hari ini mengikuti orang dari Komite ke Museum Lilin lagi, ada hasil apa?"
  },
  AvgDialog_18959_Content_30 = {
    Text = "<Yellow:Penghapusan keberadaan.>"
  },
  AvgDialog_18959_Content_31 = {
    Text = "Saya ingat itu tahun Hongji 290, atau mungkin 291? Dalam esainya, Herbert mengajukan sebuah hipotesis —"
  },
  AvgDialog_18959_Content_32 = {
    Text = "<Yellow:Di ujung Fenomena-d, keberadaan seseorang itu sendiri akan dihapus.>"
  },
  AvgDialog_18959_Content_33 = {
    Text = "Dia pernah menjadi kebanggaan akademi. Tidak ada yang menyangka bahwa dia kemudian membunuh mentornya sendiri, apalagi dengan cara yang begitu kejam…"
  },
  AvgDialog_18959_Content_34 = {
    Text = "Apakah ini sulit untuk diprediksi? Aku sudah memperingatkan mereka sejak lama."
  },
  AvgDialog_18959_Content_35 = {
    Text = "Yang tumbuh dari kegelapan malam hanyalah hal-hal yang tak terlihat oleh cahaya."
  },
  AvgDialog_18959_Content_36 = {
    Text = "Eliminasi eksistensi sebelumnya hanya terjadi pada kasus-kasus sporadis, dan tidak ada yang benar-benar menganggapnya serius. \nNamun, belakangan ini muncul tanda-tanda peningkatan frekuensi kejadian tersebut…"
  },
  AvgDialog_18959_Content_37 = {
    Text = "Saya sudah menghubungi Komite dan meminta mereka untuk memperhatikan gejala terkait. Hanya saja…"
  },
  AvgDialog_18959_Content_38 = {
    Text = "Sejak kasus pertama penyakit pelarutan yang tercatat pada tahun ke-15 era Hongji, hampir tiga ratus tahun telah berlalu."
  },
  AvgDialog_18959_Content_39 = {
    Text = "Hingga hari ini, kami masih belum sepenuhnya memahami pelarutan."
  },
  AvgDialog_18959_Content_4 = {
    Text = "Kau menggelengkan kepala."
  },
  AvgDialog_18959_Content_40 = {
    Text = "Saya punya firasat... Penjaga baru ini mungkin bisa menjadi kunci untuk mengusir Kabut."
  },
  AvgDialog_18959_Content_41 = {
    Text = "{Male=Dia,Female=Dia} dapat mengingat keberadaan yang mati akibat pelarutan, hanya dengan ini saja sudah cukup istimewa."
  },
  AvgDialog_18959_Content_42 = {
    Text = "{Male=Dia,Female=Dia} pasti telah melangkah lebih jauh daripada kita."
  },
  AvgDialog_18959_Content_43 = {
    Text = "Nomor 44 Jalan Nanhuak, reruntuhan Museum Lilin"
  },
  AvgDialog_18959_Content_44 = {
    Text = "Benar-benar reruntuhan. Dalam waktu tiga hari, tempat ini akan berubah menjadi genangan lumpur hitam, lalu lenyap sepenuhnya."
  },
  AvgDialog_18959_Content_45 = {
    Text = "Bagaimana dengan Rogers?"
  },
  AvgDialog_18959_Content_46 = {
    Text = "Dia dan Pandia sekarang dikejar-kejar oleh anjing-anjing gila dari Komite. Terakhir kali kita bertemu, itu di sebuah sanatorium di Cité."
  },
  AvgDialog_18959_Content_47 = {
    Text = "Kedua orang ini sudah terbiasa bertindak sesuka hati. Berikan mereka sedikit pelajaran agar mereka memahami arti berhati-hati dalam berbicara dan bertindak."
  },
  AvgDialog_18959_Content_48 = {
    Text = "Sebelum pergi, Pandia memberi saya sesuatu dan mengatakan bahwa itu adalah permintaan maaf untukmu."
  },
  AvgDialog_18959_Content_49 = {
    Text = "Apa ini... catatan pribadi?"
  },
  AvgDialog_18959_Content_5 = {
    Text = "Di sana telah terjadi pelarutan sepenuhnya, tidak ditemukan sedikit pun serpihan perak."
  },
  AvgDialog_18959_Content_50 = {
    Text = "Buka dan lihat, ada kejutan di dalamnya."
  },
  AvgDialog_18959_Content_51 = {
    Text = "%player%……?"
  },
  AvgDialog_18959_Content_52 = {
    Text = "Tanggal lahir tidak diketahui... baru saja dicatat oleh Mythag tahun lalu, belum pernah dilatih tetapi mampu menghubungkan banyak Wujud Pembangun untuk bertarung..."
  },
  AvgDialog_18959_Content_53 = {
    Text = "Benar-benar orang yang menarik, tidak disangka Mythag masih menyimpan keahlian ini."
  },
  AvgDialog_18959_Content_54 = {
    Text = "Sepertinya Acara \"Lentera\" di masa lalu belum cukup membuat mereka menderita."
  },
  AvgDialog_18959_Content_55 = {
    Text = "Sudah waktunya kembali ke akademi untuk melihat-lihat, dan membersihkan makam mentor tercinta saya."
  },
  AvgDialog_18959_Content_56 = {
    Text = [[
Londinium Pinggiran
Pemakaman Shoreditch]]
  },
  AvgDialog_18959_Content_57 = {Text = "Nona 24."},
  AvgDialog_18959_Content_58 = {
    Text = "%player%{Male=tuan,Female=nyonya}! Mengapa kamu datang…"
  },
  AvgDialog_18959_Content_59 = {
    Text = "Saya akan melihat Jenkin."
  },
  AvgDialog_18959_Content_6 = {
    Text = "Hanya sangat sedikit orang yang akan mengeluarkan Perak setelah meninggal, kupikir kamu sudah seharusnya memahami hal ini."
  },
  AvgDialog_18959_Content_60 = {
    Text = "Kamu berjongkok dan perlahan menyapu serpihan yang melayang di atas nisan kecil itu. Nisan tersebut kosong, kalian belum siap untuk mengukirkan tulisan di atasnya."
  },
  AvgDialog_18959_Content_61 = {
    Text = "Seolah-olah... begitu kata-kata terukir, kepergian Jenkin akan menjadi kenyataan."
  },
  AvgDialog_18959_Content_62 = {
    Text = "Nona 24, ketika berada di Museum Lilin, mengapa kamu tidak memberi tahu kami tentang identitas aslimu?"
  },
  AvgDialog_18959_Content_64 = {
    Text = "Pada saat itu, pikiranku sangat kacau dan aku juga sangat takut… Jika Jenkin melihatku dalam keadaan seperti ini, dia pasti akan merasa sedih."
  },
  AvgDialog_18959_Content_65 = {
    Text = "Jenkin bukan anak biasa, dia mampu menanggungnya."
  },
  AvgDialog_18959_Content_66 = {
    Text = "Ya... dia selalu menjadi anak paling berani dan tegar yang pernah aku lihat."
  },
  AvgDialog_18959_Content_67 = {
    Text = "Aku sudah mendengar semuanya tentang akademi. Perak milik Jenkin masih belum ditemukan, benar?"
  },
  AvgDialog_18959_Content_68 = {
    Text = "Belum ada informasi baru dari Kak William untuk sementara. Tenang saja, Nona 24."
  },
  AvgDialog_18959_Content_69 = {
    Text = "Setelah Rogers tertangkap, aku akan menginterogasinya secara langsung."
  },
  AvgDialog_18959_Content_7 = {
    Text = "Jenkin-nya, dia berbeda…"
  },
  AvgDialog_18959_Content_70 = {
    Text = "24 menggelengkan kepalanya."
  },
  AvgDialog_18959_Content_71 = {
    Text = "Saya tahu kamu tidak akan menyerah. Saya hanya khawatir… memori saya tentang Jenkin sudah mulai memudar."
  },
  AvgDialog_18959_Content_72 = {
    Text = "Saya takut, meskipun suatu hari dia benar-benar berdiri di depan saya, saya tetap tidak akan bisa mengenalinya."
  },
  AvgDialog_18959_Content_73 = {
    Text = "Kalau begitu, tunggu sampai hari aku melupakannya, lalu aku akan memberitahumu."
  },
  AvgDialog_18959_Content_74 = {
    Text = "Bagaimana kalian bertemu, menjalani kehidupan bersama, bagaimana dia menyelamatkanmu, dan akhirnya menjadi pahlawan besar kita…"
  },
  AvgDialog_18959_Content_75 = {
    Text = "Suara perlahan menurun, akhirnya tersapu oleh hembusan angin lembut."
  },
  AvgDialog_18959_Content_76 = {
    Text = "Ciiit... ciiit..."
  },
  AvgDialog_18959_Content_77 = {
    Text = "Tiba-tiba terdengar suara halus di telinga, kadang tinggi, kadang rendah, dengan ritme yang penuh variasi."
  },
  AvgDialog_18959_Content_78 = {
    Text = "Kenapa ada tikus... <Big:Cokelat!?>"
  },
  AvgDialog_18959_Content_79 = {Text = "!!"},
  AvgDialog_18959_Content_8 = {
    Text = [[
Jika kamu membantu aku, aku akan mengembalikan dompetmu dan kartu identitasmu, serta merahasiakan semuanya untukmu. 
Namun, jika kamu tidak mau membantu... hum!]]
  },
  AvgDialog_18959_Content_80 = {
    Text = "Dengar suara itu… sepertinya ada di dekat sini."
  },
  AvgDialog_18959_Content_81 = {
    Text = "Kamu segera bangkit dan berputar satu kali, dan ternyata benar-benar melihat seekor tikus kecil yang gemuk di semak-semak di balik batu nisan."
  },
  AvgDialog_18959_Content_82 = {
    Text = "Hrrr... hhh..."
  },
  AvgDialog_18959_Content_83 = {
    Text = "Postur tubuh ini, dan juga coraknya… benar-benar Cokelat!"
  },
  AvgDialog_18959_Content_84 = {
    Text = "Kamu dan 24 sama-sama terkejut dan berseru."
  },
  AvgDialog_18959_Content_85 = {
    Text = "Tikus kecil yang menghilang sejak acara di museum lilin itu ternyata tidak terganggu tidurnya oleh kalian."
  },
  AvgDialog_18959_Content_86 = {
    Text = "Sepertinya baru saja mengalami petualangan yang mendebarkan, dan kini tertidur lelap karena kelelahan di akhir perjalanannya."
  },
  AvgDialog_18959_Content_87 = {
    Text = "Huu... syuu... ruru..."
  },
  AvgDialog_18959_Content_88 = {
    Text = "Sepertinya ia sedang memeluk sesuatu di dalam pelukannya..."
  },
  AvgDialog_18959_Content_9 = {
    Text = "<Big:《Musim Semi Laut Baltik》!>"
  },
  AvgDialog_18959_Content_90 = {
    Text = "Perak. Perak Jenkin."
  },
  AvgDialog_18959_Content_91 = {
    Text = "Cakar kecil erat memeluk inti perak. Inti itu belum dipoles, dan seluruh tubuhnya memancarkan cahaya redup yang keruh."
  },
  AvgDialog_18959_Content_92 = {
    Text = "Namun, di bawah cahaya redup ini, seolah-olah kamu mendengar detak jantung yang sangat gembira dan penuh semangat."
  },
  AvgDialog_18959_Content_93 = {
    Text = "Lama tidak bertemu, Jenkin."
  },
  AvgDialog_18959_Content_94 = {
    Text = "Langit akhirnya cerah kembali. Matahari tinggi di langit, menyebarkan cahaya keemasan serta kehangatan yang pas."
  },
  AvgDialog_18959_Content_95 = {
    Text = "Angin membawa aroma tanah yang segar, kamu dan 24 tenggelam dalam sinar matahari yang hangat, saling bertukar senyuman."
  },
  AvgDialog_18959_Content_96 = {
    Text = "Ayo pergi, Nona 24."
  },
  AvgDialog_18959_Content_97 = {
    Text = "Awan mendung selama beberapa hari akhirnya mulai menyingkir, petualangan kalian baru saja dimulai."
  },
  AvgDialog_18960_Content_1 = {
    Text = "Kehancuran yang sunyi"
  },
  AvgDialog_18960_Content_10 = {
    Text = "Tapi sekarang kita tidak punya pilihan lain."
  },
  AvgDialog_18960_Content_11 = {
    Text = "Bisa dicoba."
  },
  AvgDialog_18960_Content_12 = {
    Text = "%player%, semoga kamu bisa lebih tenang."
  },
  AvgDialog_18960_Content_13 = {
    Text = "Bagian depan sudah ditenggelamkan oleh D-lendir. Bahkan Pembangun akan terpengaruh jika terendam di dalamnya untuk waktu yang lama."
  },
  AvgDialog_18960_Content_14 = {
    Text = "Sekarang sudah tidak bisa kembali melalui rute normal, harus mencari cara lain."
  },
  AvgDialog_18960_Content_15 = {
    Text = "Cara lain... Lorong lain..."
  },
  AvgDialog_18960_Content_16 = {
    Text = "Aku mengerti!"
  },
  AvgDialog_18960_Content_17 = {
    Text = "Lihat, di sana ada lubang ventilasi."
  },
  AvgDialog_18960_Content_18 = {
    Text = "Kalian mengikuti pandangan Jenkin ke atas, ventilasi kecil itu berada tepat di atas kepala kalian."
  },
  AvgDialog_18960_Content_19 = {
    Text = "Ada kemungkinan itu mengarah ke ruang direktur, D-lendir tidak dapat menjangkau..."
  },
  AvgDialog_18960_Content_2 = {
    Text = "4:15, Museum Lilin Rogers"
  },
  AvgDialog_18960_Content_20 = {
    Text = "Tidak bisa, lorong ini terlalu sempit, kita tidak bisa masuk."
  },
  AvgDialog_18960_Content_21 = {
    Text = "Saya bisa masuk ke dalam."
  },
  AvgDialog_18960_Content_22 = {
    Text = "Apakah kalian lupa, aku ini \"tikus\"."
  },
  AvgDialog_18960_Content_23 = {Text = "Cit!"},
  AvgDialog_18960_Content_24 = {
    Text = "Tidak bisa, ini terlalu berisiko. Tidak ada yang bisa menjamin kunci itu masih ada di ruang kurator sekarang, bahkan apakah lubang ventilasi ini benar-benar bisa ——"
  },
  AvgDialog_18960_Content_25 = {
    Text = "Ck. Berisik sekali, aku kira kamu orang dewasa yang tegas, Nyonya Ramona."
  },
  AvgDialog_18960_Content_26 = {
    Text = "Izinkan aku membantu kalian memahami realitas: Pertama, sepertinya tidak ada cara lain, kan? Daripada menunggu di sini sampai mati, lebih baik mencoba peruntungan."
  },
  AvgDialog_18960_Content_27 = {
    Text = "Kedua, saya dan Cokelat pergi bersama. Saya yang memimpin, sedangkan dia bertanggung jawab untuk mengambil kunci."
  },
  AvgDialog_18960_Content_28 = {
    Text = "Cit! Cit cit!"
  },
  AvgDialog_18960_Content_29 = {
    Text = "Ketiga……"
  },
  AvgDialog_18960_Content_3 = {
    Text = "Kalian terhuyung-huyung berlari di antara reruntuhan, napas kalian saling bersahutan."
  },
  AvgDialog_18960_Content_30 = {
    Text = "Kali ini aku sudah menyusahkan kalian banyak, bahkan kakakku harus menerima hukuman cambuk karena melindungiku."
  },
  AvgDialog_18960_Content_31 = {Text = "Jadi..."},
  AvgDialog_18960_Content_32 = {
    Text = "Biarkan aku membantu sedikit, aku tidak tahan terus-menerus dijaga oleh kalian."
  },
  AvgDialog_18960_Content_33 = {
    Text = "Setelah selesai berbicara, Jenkin langsung melompat ke lubang ventilasi, sama seperti yang telah ia lakukan berkali-kali sebelumnya saat berlarian di antara rumah-rumah di Whitechapel. Dalam sekejap, ia menghilang dari pandangan."
  },
  AvgDialog_18960_Content_34 = {
    Text = "Jenkin…! Dia tak pernah mau mendengarkan aku…"
  },
  AvgDialog_18960_Content_35 = {
    Text = "Jangan khawatir, Nona 24. Jenkin lebih cekatan daripada kita semua, dia pasti akan baik-baik saja."
  },
  AvgDialog_18960_Content_36 = {
    Text = "...Saya percaya dia."
  },
  AvgDialog_18960_Content_4 = {
    Text = "Akhirnya, kalian melihat pintu besar yang berat di depan sana. Cukup dorong dengan lembut —"
  },
  AvgDialog_18960_Content_5 = {
    Text = "Astaga, pintunya terkunci."
  },
  AvgDialog_18960_Content_6 = {
    Text = "Di depan telah berubah menjadi lautan hitam, bahaya semakin mendekat, tidak ada jalan untuk mundur."
  },
  AvgDialog_18960_Content_7 = {
    Text = "Sepertinya itu adalah pintu yang disebutkan oleh Kakak William… Kunci seharusnya ada di ruang direktur perpustakaan."
  },
  AvgDialog_18960_Content_8 = {
    Text = "Tidak bisa pergi"
  },
  AvgDialog_18960_Content_9 = {
    Text = "Di sini penuh dengan D-lendir… Bahkan Pembangun, jika terendam terlalu lama di dalamnya, akan segera mati."
  },
  AvgDialog_18961_Content_1 = {
    Text = "Saluran Air Bawah Tanah"
  },
  AvgDialog_18961_Content_10 = {
    Text = "Ah, ngantuk sekali!"
  },
  AvgDialog_18961_Content_100 = {
    Text = "Saat berikutnya, dia menggoyangkan pergelangan tangannya dengan lembut, lilin panas tiba-tiba mengalir deras, dan lengan putihnya mekar seperti bunga merah yang mengerikan."
  },
  AvgDialog_18961_Content_101 = {
    Text = "Aaaaah——!"
  },
  AvgDialog_18961_Content_102 = {
    Text = "Oh ya… pola yang sangat indah."
  },
  AvgDialog_18961_Content_103 = {
    Text = "George membenci babi yang berisik, lalu dia menuangkan semua lilin ke dalam mulutnya."
  },
  AvgDialog_18961_Content_104 = {
    Text = "Lampu lilin melayang ke arah Jenkin, uap panas membuat wajah Jenkin memerah."
  },
  AvgDialog_18961_Content_105 = {
    Text = "Lilin di dalam kandelaber penuh dengan lilin cair yang mendidih, hampir tumpah."
  },
  AvgDialog_18961_Content_106 = {
    Text = "<Shake: Pembohong... bukankah katanya sedikit pun tidak sakit...>"
  },
  AvgDialog_18961_Content_107 = {
    Text = "Benar-benar memalukan, aku sudah lama tidak menjadi manusia, tidak tahu akan terasa sesakit ini~"
  },
  AvgDialog_18961_Content_108 = {
    Text = "Sempurna. Kalian berdua, naik dan buka mulutnya."
  },
  AvgDialog_18961_Content_109 = {
    Text = "Selanjutnya, cukup tuangkan lilin ke dalam, dan tikus busuk di selokan akan terdiam selamanya."
  },
  AvgDialog_18961_Content_11 = {
    Text = "Lain kali jika kamu begitu lamban, aku akan memasukkanmu ke dalam peti mati juga~"
  },
  AvgDialog_18961_Content_110 = {
    Text = "Berhenti… cepat berhenti! Dia tidak ada hubungannya dengan semua ini…"
  },
  AvgDialog_18961_Content_111 = {
    Text = "<Small:Kakak... sakit sekali... sangat-sangat sakit...>"
  },
  AvgDialog_18961_Content_112 = {
    Text = "Jangan... jangan, aku sudah berubah pikiran, aku tidak mau mati! Jangan mendekat...!"
  },
  AvgDialog_18961_Content_114 = {
    Text = "... sebentar."
  },
  AvgDialog_18961_Content_115 = {
    Text = "Di tengah kekacauan, tiba-tiba kamu mendengar sebuah helaan napas yang pelan."
  },
  AvgDialog_18961_Content_116 = {
    Text = "Aku berkata... mohon tunggu sebentar."
  },
  AvgDialog_18961_Content_12 = {
    Text = "Maaf, Nona Pandia…"
  },
  AvgDialog_18961_Content_13 = {
    Text = "<Big:Pandia——！！>"
  },
  AvgDialog_18961_Content_14 = {
    Text = "Bayangan wanita itu melayang seperti awan, ujung rok panjangnya berputar dan memancarkan cahaya putih. Dia jatuh berlutut di depan Pandia."
  },
  AvgDialog_18961_Content_15 = {
    Text = "Pandia! Jangan perlakukan 24 seperti ini. Jika harus dihukum..."
  },
  AvgDialog_18961_Content_16 = {
    Text = "Tujukan padaku!"
  },
  AvgDialog_18961_Content_18 = {
    Text = "Saya sudah mengubah pikiran, kalian semua telah melakukan dengan baik, silakan undurkan diri."
  },
  AvgDialog_18961_Content_19 = {
    Text = "Tuan, saya mengerti bahwa Anda tidak tega menegur saya. Anda selalu begitu lembut……"
  },
  AvgDialog_18961_Content_2 = {
    Text = "Bagus, semua sudah lengkap. Sekarang kita harus menyiapkan hadiah besar untuk Mythag."
  },
  AvgDialog_18961_Content_21 = {
    Text = "Sayangku, cintaku yang paling manis, bisakah kau lepaskan kakiku terlebih dahulu?"
  },
  AvgDialog_18961_Content_22 = {
    Text = "Semua terserah Anda, Nyonya Pandia."
  },
  AvgDialog_18961_Content_23 = {
    Text = "Pintar sekali. Persis seperti sekarang ini... Lalu berbaliklah ke belakang, maju sepuluh langkah ke depan, tinggalkan ruangan ini, dan jangan pernah menoleh lagi."
  },
  AvgDialog_18961_Content_24 = {
    Text = "Mengerti maksud saya?"
  },
  AvgDialog_18961_Content_25 = {
    Text = "Mengerti…… Saya akan merindukan Anda, Pandia…… \n Tidak, saya sudah mulai merindukan Anda sekarang!"
  },
  AvgDialog_18961_Content_26 = {
    Text = "Wanita itu berbalik, dan sebelum pergi, ia tidak lupa untuk menutup pintu dengan hati-hati."
  },
  AvgDialog_18961_Content_27 = {
    Text = "Hu… sungguh membingungkan."
  },
  AvgDialog_18961_Content_28 = {
    Text = "Setelah memastikan pintu tertutup rapat, Pandia mengambil napas dalam-dalam dan kembali ke semangatnya yang biasa."
  },
  AvgDialog_18961_Content_29 = {
    Text = "Baiklah semuanya, tadi kita berbicara sampai di mana ya~"
  },
  AvgDialog_18961_Content_3 = {
    Text = "Namun, momen ini terasa sedikit——tidak, sangat lama untuk ditunggu."
  },
  AvgDialog_18961_Content_30 = {
    Text = "Bernapas... sangat sulit."
  },
  AvgDialog_18961_Content_32 = {
    Text = "Jangan bergerak, aku sedang merias wajahmu."
  },
  AvgDialog_18961_Content_33 = {
    Text = "Astaga, sudut bibirku luntur. Umm..."
  },
  AvgDialog_18961_Content_34 = {
    Text = "Kamu adalah Rogers…"
  },
  AvgDialog_18961_Content_35 = {
    Text = "Jari-jari dingin menyapu sudut bibirmu, kamu mencium bau minyak pembusukan yang menyengat."
  },
  AvgDialog_18961_Content_36 = {
    Text = "Kamu mencoba bergerak, namun menyadari bahwa seluruh tubuhmu terperangkap dalam mesin yang dingin dan keras."
  },
  AvgDialog_18961_Content_37 = {
    Text = "Begitu saja. Kamu benar-benar bahan patung lilin yang sempurna."
  },
  AvgDialog_18961_Content_38 = {
    Text = "%player%, akhirnya kamu bangun!"
  },
  AvgDialog_18961_Content_39 = {
    Text = "Lepaskan aku... uh!"
  },
  AvgDialog_18961_Content_4 = {
    Text = "24, yang paling kucintai, 24, cepat kemari~"
  },
  AvgDialog_18961_Content_40 = {
    Text = "Jangan bergerak sembarangan, aku sudah bersusah payah untuk menahan kalian di tempat."
  },
  AvgDialog_18961_Content_41 = {
    Text = [[
Lihat peti mati di sana? Itu sudah disiapkan dengan hati-hati untuk kalian. 
 Kalian ini, sebentar lagi akan mendapatkan kehidupan baru~]]
  },
  AvgDialog_18961_Content_42 = {
    Text = "Hanya dalam bentuk patung lilin, hehe. Kali ini sebaiknya buat tema apa, ya? Hmm…"
  },
  AvgDialog_18961_Content_43 = {
    Text = "Paman Charlie tidak bisa menemukan kucing lorengnya di mana pun~"
  },
  AvgDialog_18961_Content_44 = {
    Text = "Kucing tabby, kucing tabby~"
  },
  AvgDialog_18961_Content_45 = {
    Text = "Ramona... Ramona?! Sial, berhenti bernyanyi..."
  },
  AvgDialog_18961_Content_46 = {
    Text = "Orang itu sudah seperti ini sejak aku bangun, hanya terus-menerus menyanyikan lagu yang sama berulang-ulang."
  },
  AvgDialog_18961_Content_47 = {
    Text = "Rekanmu sudah dijadikan patung lilin, lho. Rogers membutuhkan waktu satu jam untuk itu."
  },
  AvgDialog_18961_Content_48 = {
    Text = "Kucing loreng! Meong!"
  },
  AvgDialog_18961_Content_49 = {
    Text = "Bagaimana, suka? Apakah sangat imut~"
  },
  AvgDialog_18961_Content_5 = {
    Text = "...Ya, Yang Mulia Pandia."
  },
  AvgDialog_18961_Content_50 = {
    Text = "Cih, pindahkan tangan kotor kamu dari tubuhnya!"
  },
  AvgDialog_18961_Content_51 = {
    Text = "Rogers, kau kan orang yang membuatku pingsan di Taring."
  },
  AvgDialog_18961_Content_52 = {
    Text = "Kamu telah membunuh Aigis, Xiao Mai, bahkan hilangnya kakakku juga…"
  },
  AvgDialog_18961_Content_53 = {
    Text = "Apa itu Aigis?"
  },
  AvgDialog_18961_Content_54 = {
    Text = "Maaf, George tidak pernah mengingat nama bahan yang terbuang dan sampah."
  },
  AvgDialog_18961_Content_55 = {
    Text = "Kamu@2 memaki siapa?!@1 Babi!"
  },
  AvgDialog_18961_Content_56 = {
    Text = "Eh, bukankah begitu? Kamu Jenkin, kan? Sarah pernah bercerita tentang cerita kecil Jenkin kepada kami."
  },
  AvgDialog_18961_Content_57 = {
    Text = "Tidak lama setelah Jenkin lahir, ayahnya yang pemabuk pergi meninggalkannya."
  },
  AvgDialog_18961_Content_58 = {
    Text = "Ibu Jenkin yang kecil terkena Pelarutan, menjadi seorang wanita gila."
  },
  AvgDialog_18961_Content_59 = {
    Text = "Wanita gila itu setiap hari memukul Jenkin kecil dengan sapu, ikat pinggang, serta semua alat yang bisa ditemukannya, dan juga menghina Jenkin kecil dengan kata-kata paling kotor…"
  },
  AvgDialog_18961_Content_6 = {
    Text = "Pletak——!"
  },
  AvgDialog_18961_Content_60 = {
    Text = "Kamu... kamu berbicara sembarangan..."
  },
  AvgDialog_18961_Content_61 = {
    Text = "Oh iya, dari tubuhnya akan mengalir banyak cairan hitam kental. Di tempat tidur, lantai rumah, semuanya menjadi lengket dan basah... Yuck!"
  },
  AvgDialog_18961_Content_62 = {
    Text = "Mengatakan hal itu, George dengan berlebihan bergidik, lalu tertawa cekikikan."
  },
  AvgDialog_18961_Content_63 = {
    Text = [[
Lalu, wanita gila itu pergi sendirian. Jenkin kecil berdiri di depan pintu menunggunya, menunggu dan menunggu... 
 Ke mana wanita gila itu pergi? Tidak ada yang tahu.]]
  },
  AvgDialog_18961_Content_64 = {
    Text = "Tidak, bukan seperti itu..."
  },
  AvgDialog_18961_Content_65 = {
    Text = "Cih cih cih, George bersikeras untuk mengatakannya! Kemudian, Jenkin kecil dikirim ke panti barang, tapi itu hanya seperti pindah dari satu tempat sampah ke tempat sampah lainnya."
  },
  AvgDialog_18961_Content_66 = {
    Text = "Mengakulah, kalian hanyalah sampah yang bisa ditemui di jalan-jalan dan saluran air bawah tanah Londinium, satu badai besar saja sudah cukup untuk menyapu kalian semua!"
  },
  AvgDialog_18961_Content_67 = {
    Text = "Bahkan kakakmu, bukankah dia pergi dengan alasan yang dibuat-buat karena sudah muak dengan segalanya dan ingin meninggalkanmu?"
  },
  AvgDialog_18961_Content_68 = {
    Text = "Diam... <Big:Diam saja!>"
  },
  AvgDialog_18961_Content_69 = {
    Text = "Jenkin gemetar, wajahnya sangat pucat. Dia membuka mulutnya, tampaknya ingin menjelaskan sesuatu, tetapi pada akhirnya hanya menundukkan kepalanya dengan rasa frustrasi."
  },
  AvgDialog_18961_Content_7 = {
    Text = "Cemeti hitam dengan lembut terayun, 24 tersungkur ke tanah, bekas luka merah bengkak langsung muncul di tubuhnya."
  },
  AvgDialog_18961_Content_70 = {
    Text = "Ya, apa haknya dia? Bagi tikus di selokan, cinta adalah kemewahan yang tak terjangkau, seperti permen yang hanya berani disentuh dalam mimpi."
  },
  AvgDialog_18961_Content_71 = {
    Text = "Sepasang tangan dengan lembut membelai kepala Jenkin."
  },
  AvgDialog_18961_Content_72 = {
    Text = "Anak yang malang. Aku telah melihat banyak anak yang sedih, seperti... seperti dirimu. Mereka tidak diinginkan, juga tidak diperlakukan dengan baik."
  },
  AvgDialog_18961_Content_73 = {
    Text = "Jadi, aku ingin membantu kalian pergi — dalam bentuk patung lilin."
  },
  AvgDialog_18961_Content_74 = {
    Text = "Membantu kami? Tapi kalian terhadap Aigis, terhadap Little Mike…"
  },
  AvgDialog_18961_Content_75 = {
    Text = "Apakah kamu yakin membiarkan mereka terus hidup dalam penderitaan di dunia ini adalah pilihan yang baik?"
  },
  AvgDialog_18961_Content_76 = {
    Text = "<Shake: Aku... aku tidak tahu...>"
  },
  AvgDialog_18961_Content_77 = {
    Text = [[
Tenang saja, anak yang malang. 
Aku akan menjadikanmu patung lilin yang paling indah, dan sama sekali tidak akan terasa sakit.]]
  },
  AvgDialog_18961_Content_78 = {
    Text = "Jenkin, jangan dengarkan pembelaan mereka!"
  },
  AvgDialog_18961_Content_79 = {
    Text = [[
Rogers, kamu benar-benar badut yang menipu diri sendiri. 
 Apakah berubah menjadi patung lilin bisa membuatmu berpura-pura bahwa semuanya tidak terjadi?]]
  },
  AvgDialog_18961_Content_8 = {Text = "Ukh……!"},
  AvgDialog_18961_Content_80 = {
    Text = [[
Apakah mereka benar-benar sukarela?
Beranikah kamu menjamin bahwa kamu tidak pernah membujuk atau memaksa "bahan Patung lilin" milikmu?!]]
  },
  AvgDialog_18961_Content_81 = {
    Text = "Jangan ribut."
  },
  AvgDialog_18961_Content_82 = {
    Text = "Bocah, aku mengakui bahwa kau benar. Dunia ini memang sudah sepenuhnya busuk."
  },
  AvgDialog_18961_Content_83 = {
    Text = "Lagipula, kita tidak bisa melarikan diri sekarang... Cepatlah sedikit, aku masih ingin pergi mencari ibuku."
  },
  AvgDialog_18961_Content_84 = {
    Text = [[
Jenkin, aku tahu kamu sedang merasa sangat sedih sekarang. 
Namun, tolong jangan lupakan bahwa kita di sini untuk mencari kakakmu. Dia masih menunggu kita untuk menyelamatkannya.]]
  },
  AvgDialog_18961_Content_85 = {
    Text = "Maaf, %player%. Saya sedikit lelah."
  },
  AvgDialog_18961_Content_86 = {
    Text = "Mungkin, kakak yang disebut-sebut itu hanya ada dalam imajinasiku…"
  },
  AvgDialog_18961_Content_87 = {
    Text = "Kalau tidak, bagaimana mungkin sampai sekarang dia masih belum keluar untuk menemuiku?"
  },
  AvgDialog_18961_Content_88 = {
    Text = "Ah, jika tikus kecil sudah berbicara, lalu untuk apa menunggu lagi?"
  },
  AvgDialog_18961_Content_89 = {
    Text = "24, Leigh, cepat datang dan tuangkan lilin di atasnya. Tuangkan dengan lembut dan penuh kasih sayang ya~"
  },
  AvgDialog_18961_Content_9 = {
    Text = "Aku sudah menunggu hingga hampir tertidur dan tetap tidak melihat kalian. Untungnya, George akhirnya berhasil membawa orang-orang itu kemari."
  },
  AvgDialog_18961_Content_90 = {
    Text = "... Mematuhi perintah."
  },
  AvgDialog_18961_Content_91 = {
    Text = "Pandia yang terhormat, perintah Anda adalah wahyu bagi saya."
  },
  AvgDialog_18961_Content_92 = {
    Text = "Bagaimana kalian bisa bersama... Aku mengerti, kalian satu tim."
  },
  AvgDialog_18961_Content_93 = {
    Text = "Hehe... aku benar-benar bodoh sekali."
  },
  AvgDialog_18961_Content_94 = {
    Text = "Seorang wanita memegang cawan yang penuh dengan lilin cair, lalu berjalan mendekati Jenkin."
  },
  AvgDialog_18961_Content_95 = {
    Text = "Sebenarnya… saluran pembuangan juga tidak terlalu buruk."
  },
  AvgDialog_18961_Content_96 = {
    Text = "Selain sampah dan makanan yang sudah rusak, sesekali ada juga kaleng ikan yang masih segar. Aku bahkan pernah menemukan seikat bunga tulip!"
  },
  AvgDialog_18961_Content_97 = {Text = "...?"},
  AvgDialog_18961_Content_98 = {
    Text = "Terkejut, ya? Pengetahuanku tentang saluran pembuangan jauh lebih banyak daripada kamu~"
  },
  AvgDialog_18961_Content_99 = {
    Text = "Byurrr——"
  },
  AvgDialog_18962_Content_1 = {
    Text = "Kakak Senior, apakah Anda baik-baik saja?"
  },
  AvgDialog_18962_Content_2 = {
    Text = "Huh huh... abaikan saja aku, lanjutkan misi."
  },
  AvgDialog_18962_Content_3 = {
    Text = "Tenang saja, Senpai. Kali ini aku pasti akan membawamu keluar."
  },
  AvgDialog_18963_Content_1 = {
    Text = "<Change>Hu hu hu……ao ao ao!"
  },
  AvgDialog_18963_Content_10 = {
    Text = "Saya melihat Lorong yang disebutkan oleh senior! Semua orang ikuti saya erat, jangan sampai terpisah!"
  },
  AvgDialog_18963_Content_11 = {
    Text = "Oh ya... sepertinya semua orang melupakanku? Aku diperintahkan untuk menghentikan kalian di sini, lho."
  },
  AvgDialog_18963_Content_12 = {
    Text = "<Big:Pergi kau!>"
  },
  AvgDialog_18963_Content_13 = {
    Text = "Leigh tersenyum lembut memandang Jenkin dan 24. Tangan mereka terus saling bergenggaman."
  },
  AvgDialog_18963_Content_14 = {
    Text = "Tahukah kamu, tikus kecil? Mengapa aku sangat memahami saluran pembuangan?"
  },
  AvgDialog_18963_Content_15 = {Text = "...Ha?"},
  AvgDialog_18963_Content_16 = {
    Text = "Pada hari itu... di saluran pembuangan, banyak polisi datang. Mereka semua membawa senjata."
  },
  AvgDialog_18963_Content_17 = {
    Text = "Aku dan kakak saling menopang, terus berlari, terus berlari di dalam sana…"
  },
  AvgDialog_18963_Content_18 = {
    Text = "Kakak tertembak banyak kali. Aku kemudian menghitungnya dengan sangat serius, 14, 15, 16… \n Ya, totalnya tertembak 16 kali."
  },
  AvgDialog_18963_Content_19 = {
    Text = "Tubuhnya penuh dengan lubang, dan banyak darah mengalir keluar. Aromanya sangat harum… \n Namun, aku berhasil menahan diri."
  },
  AvgDialog_18963_Content_2 = {
    Text = "Patung lilin yang semula berkumpul bersama tiba-tiba runtuh."
  },
  AvgDialog_18963_Content_20 = {
    Text = "Darahnya, aku sama sekali tidak meminumnya."
  },
  AvgDialog_18963_Content_21 = {
    Text = "Apa yang dia bicarakan sembarangan ini……"
  },
  AvgDialog_18963_Content_22 = {
    Text = "Tidak ada apa-apa... Aku tiba-tiba saja berubah pikiran, kalian pergilah."
  },
  AvgDialog_18963_Content_23 = {
    Text = "Begitu saja melepaskan kami? Apakah kau benar-benar sebaik itu...?"
  },
  AvgDialog_18963_Content_24 = {
    Text = "Leigh tidak menjawab pertanyaan kalian, hanya mengangkat jarinya untuk menunjuk ke depan."
  },
  AvgDialog_18963_Content_25 = {
    Text = "Lorong ada di sana. Jika kalian tidak ingin mati, sebaiknya kalian cepat-cepat bergerak."
  },
  AvgDialog_18963_Content_26 = {
    Text = "Lalu kau……?"
  },
  AvgDialog_18963_Content_27 = {
    Text = "Sepertinya tidak menduga pertanyaanmu, Leigh memandangmu dengan sedikit terkejut."
  },
  AvgDialog_18963_Content_28 = {
    Text = "Kemudian dia menengadah memandang cairan hitam yang terus menetes di atas kepalanya, lalu tersenyum dengan ekspresi kosong."
  },
  AvgDialog_18963_Content_29 = {
    Text = "Selamat tinggal, Penjaga."
  },
  AvgDialog_18963_Content_3 = {
    Text = "Kepala George menggelinding di tanah, bola matanya yang besar masih menatap kalian dengan tatapan kosong."
  },
  AvgDialog_18963_Content_30 = {
    Text = "Pada saat keluar dari ruang bawah tanah, kamu menoleh ke arah Leigh."
  },
  AvgDialog_18963_Content_31 = {
    Text = "Di lantai dan langit-langit, D-lendir hitam terus mengalir. Leigh berdiri di tengah reruntuhan, kurus seperti rumput liar yang layu."
  },
  AvgDialog_18963_Content_32 = {
    Text = [[
Kamu tidak bisa melihat ekspresinya dengan jelas, namun kamu bisa merasakan tatapannya. 
Dia terus memperhatikan kalian.]]
  },
  AvgDialog_18963_Content_4 = {
    Text = "<Change>Aku... sempurna..."
  },
  AvgDialog_18963_Content_5 = {
    Text = "Patung lilin perlahan mencair, seperti cat abu-abu pucat yang tenggelam ke dalam lautan pelarutan hitam, lalu tak ada lagi jejak yang tersisa."
  },
  AvgDialog_18963_Content_6 = {
    Text = "Akhirnya… semuanya benar-benar berakhir."
  },
  AvgDialog_18963_Content_7 = {
    Text = "<Big:GRRRUMMMM——!!>"
  },
  AvgDialog_18963_Content_8 = {
    Text = "Gelombang hitam yang mengalir deras menelan segala sesuatu yang dilaluinya."
  },
  AvgDialog_18963_Content_9 = {
    Text = "Museum lilin benar-benar mengalami pelarutan, kita harus segera meninggalkan tempat ini!"
  },
  AvgDialog_18964_Content_1 = {
    Text = "Asap dan Anggrek Ungu"
  },
  AvgDialog_18964_Content_10 = {
    Text = "… Lima menit."
  },
  AvgDialog_18964_Content_11 = {
    Text = "Rogers, Rogers… kita bertemu lagi."
  },
  AvgDialog_18964_Content_12 = {
    Text = "Kamu adalah...?"
  },
  AvgDialog_18964_Content_13 = {
    Text = "Terakhir kali aku melihatmu, kamu baru berusia 8 atau 9 tahun, duduk di antara banyak mayat dan patung lilin."
  },
  AvgDialog_18964_Content_14 = {
    Text = "Ketika ibumu membawamu pergi, kamu masih menangis dan berteriak, tidak mau pergi."
  },
  AvgDialog_18964_Content_15 = {
    Text = "Haha... Saya sudah menjadi detektif selama 30 tahun, dan dari sorot matamu saat itu saya sudah tahu bahwa kau adalah seorang penjahat kelas kakap, sampah masyarakat."
  },
  AvgDialog_18964_Content_16 = {
    Text = "Ternyata, kamu."
  },
  AvgDialog_18964_Content_17 = {
    Text = "<Yellow: Aku tahu kau membunuh \"Patung lilin\", aku sudah tahu sejak awal.>"
  },
  AvgDialog_18964_Content_18 = {
    Text = "Katakan padaku, ke mana kamu menyembunyikannya setelah itu?"
  },
  AvgDialog_18964_Content_2 = {
    Text = [[
19:05, Museum Lilin Rogers
Empat jam sebelumnya]]
  },
  AvgDialog_18964_Content_20 = {
    Text = "Berbicara. Kamu gagap, bukan bisu."
  },
  AvgDialog_18964_Content_22 = {
    Text = "Di sini... di sini saja."
  },
  AvgDialog_18964_Content_23 = {Text = "……Apa?"},
  AvgDialog_18964_Content_24 = {
    Text = "Dia ada di mana-mana... di bawah tanah, di etalase, dalam mimpi burukku..."
  },
  AvgDialog_18964_Content_25 = {
    Text = "<Red:Termasuk... punggungmu.>"
  },
  AvgDialog_18964_Content_26 = {
    Text = "Begitu Rogers selesai berbicara, leher sang detektif langsung muncul bekas merah tipis."
  },
  AvgDialog_18964_Content_27 = {
    Text = "Kemudian kepala terlepas dari leher, menggelinding jatuh ke tanah. Mata yang melebar belum sempat tertutup."
  },
  AvgDialog_18964_Content_28 = {
    Text = "Siapa di sana? Keluar."
  },
  AvgDialog_18964_Content_29 = {
    Text = "Aroma kental bunga daffodil mengalir perlahan di malam hari, dan asap berwarna ungu muda melingkupi William secara bertahap."
  },
  AvgDialog_18964_Content_3 = {
    Text = "Bruk——！"
  },
  AvgDialog_18964_Content_30 = {
    Text = "Melamun bukanlah kebiasaan yang baik, Penyelidik."
  },
  AvgDialog_18964_Content_31 = {
    Text = [[
23:30, Museum lilin Rogers
Studio]]
  },
  AvgDialog_18964_Content_32 = {
    Text = "To……tolong aku……"
  },
  AvgDialog_18964_Content_33 = {
    Text = "Suara seorang wanita... Apakah itu Kakak?!"
  },
  AvgDialog_18964_Content_34 = {
    Text = "Sepertinya suara itu berasal dari sudut dinding, mari kita pergi dan melihat."
  },
  AvgDialog_18964_Content_4 = {
    Text = "Detektif-detektif dengan cekatan memecahkan kaca jendela, lalu menyingkirkan semua patung lilin yang dipajang."
  },
  AvgDialog_18964_Content_5 = {
    Text = "Kasar, orang-orang rendah, kalian telah menodai seni..."
  },
  AvgDialog_18964_Content_6 = {
    Text = "<Big:Tidak!>"
  },
  AvgDialog_18964_Content_7 = {
    Text = "Tuan Rogers, Anda diduga terlibat dalam kasus hilangnya penduduk di wilayah White Chapel. Berdasarkan ketentuan <Yellow:Pasal 112>, kami berhak menahan dan membawa Anda ke Komite untuk ditahan dan diinterogasi."
  },
  AvgDialog_18964_Content_8 = {
    Text = "<Shake: Aku akan ikut kalian. Jangan, jangan merusak karyaku——>"
  },
  AvgDialog_18964_Content_9 = {
    Text = "Tunggu, aku ada sesuatu untuk dikatakan kepadanya."
  },
  AvgDialog_18965_Content_1 = {
    Text = "Dari mana bocah ini muncul, apa kalian yang dimaksud oleh administrator..."
  },
  AvgDialog_18965_Content_10 = {
    Text = "Saya lihat sepertinya mereka meletakkan beberapa dokumen di lemari ini, cepat buka dan lihat."
  },
  AvgDialog_18965_Content_11 = {
    Text = "Kalian menggunakan kunci untuk membuka pintu lemari."
  },
  AvgDialog_18965_Content_12 = {
    Text = "Buku gambar, cat..."
  },
  AvgDialog_18965_Content_13 = {
    Text = "Wah, ukiran pada pisau ukir ini sangat halus, pasti bernilai banyak uang…"
  },
  AvgDialog_18965_Content_14 = {
    Text = "Dan beberapa hiasan ini, sekilas terlihat seperti benda antik..."
  },
  AvgDialog_18965_Content_15 = {
    Text = "Hihi... semuanya dimasukkan, dimasukkan..."
  },
  AvgDialog_18965_Content_16 = {
    Text = "Cokelat, kita kaya raya~!"
  },
  AvgDialog_18965_Content_17 = {Text = "Cit cit!"},
  AvgDialog_18965_Content_18 = {
    Text = "Eh, apa ini?"
  },
  AvgDialog_18965_Content_19 = {
    Text = "Sebuah koran tergeletak diam di sudut yang tidak mencolok, dipenuhi dengan jamur hitam. Sepertinya sudah lama ditinggalkan."
  },
  AvgDialog_18965_Content_2 = {
    Text = "Tahu siapa kami tapi masih berani berdiri di sini? Hati-hati, aku bisa menggores wajahmu."
  },
  AvgDialog_18965_Content_20 = {
    Text = "<Blue:《Kasus Penculikan Patung Lilin Eksentrik》?>"
  },
  AvgDialog_18965_Content_21 = {
    Text = "Sepertinya menceritakan sebuah Acara jahat yang terjadi lebih dari sepuluh tahun yang lalu."
  },
  AvgDialog_18965_Content_22 = {
    Text = "Seorang pembunuh berantai bernama <Blue:\"Patung lilin\"> masih belum ditemukan…"
  },
  AvgDialog_18965_Content_23 = {
    Text = "Saya pernah mendengar Miss Sarah berbicara tentang kasus ini!"
  },
  AvgDialog_18965_Content_24 = {
    Text = "Ada seorang pembunuh berantai dengan julukan \"Patung Lilin\". Dia menculik banyak orang... mungkin sekitar seratus orang, lalu mengubah mereka menjadi patung lilin."
  },
  AvgDialog_18965_Content_25 = {
    Text = "Lalu, apakah dia berhasil ditangkap?"
  },
  AvgDialog_18965_Content_26 = {
    Text = "Judulnya sudah menjelaskan, hilang tanpa jejak. \n Polisi datang ke rumahnya, namun hanya menemukan beberapa korban dan patung lilin…"
  },
  AvgDialog_18965_Content_27 = {
    Text = "Jenkin berkata, dengan sedikit rasa tidak nyaman, dia mengerutkan hidungnya."
  },
  AvgDialog_18965_Content_28 = {
    Text = [[
Pokoknya dia benar-benar gila. 
 Setelah mendengar cerita ini waktu kecil, aku mengalami insomnia selama seminggu penuh.]]
  },
  AvgDialog_18965_Content_29 = {
    Text = "Dibuat menjadi patung lilin… bukankah itu sama saja dengan apa yang dilakukan Rogers?"
  },
  AvgDialog_18965_Content_3 = {
    Text = "Kamu, kalian tunggu di sini! Jangan berani-berani pergi dari tempat ini!"
  },
  AvgDialog_18965_Content_30 = {
    Text = "Namun, pembunuh yang ada di foto itu bukan Rogers."
  },
  AvgDialog_18965_Content_31 = {
    Text = "Kamu melihat foto \"Patung lilin\". Ini adalah seorang pria paruh baya berusia sekitar tiga puluh tahun, sangat kurus, dengan mata yang cekung sehingga tulang pipinya tampak menonjol."
  },
  AvgDialog_18965_Content_32 = {
    Text = "Tidak ada kesamaan dengan Rogers yang kau ingat."
  },
  AvgDialog_18965_Content_33 = {
    Text = "Mata... rasanya seperti pernah melihatnya di suatu tempat."
  },
  AvgDialog_18965_Content_34 = {
    Text = "Intinya, simpan saja dulu."
  },
  AvgDialog_18965_Content_4 = {
    Text = "Nyonya Chatade mengangkat gaun panjangnya dan meninggalkan studio dengan kecepatan yang luar biasa."
  },
  AvgDialog_18965_Content_5 = {
    Text = "Buruk, mereka melarikan diri."
  },
  AvgDialog_18965_Content_6 = {
    Text = "Haha, dia itu, semakin jauh dia pergi, semakin baik~"
  },
  AvgDialog_18965_Content_7 = {
    Text = "Lihat, apa ini?"
  },
  AvgDialog_18965_Content_8 = {
    Text = "Kunci lemari? Bagus sekali, Jenkin!"
  },
  AvgDialog_18965_Content_9 = {
    Text = "Tidak ada yang sulit bagiku, pencuri nomor satu di Londinium!"
  },
  AvgDialog_18966_Content_1 = {
    Text = "Bisikan Abadi"
  },
  AvgDialog_18966_Content_10 = {
    Text = "Sebuah <Yellow:D-rongga> yang sempurna, inilah \"inti\" sebenarnya dari museum lilin ini."
  },
  AvgDialog_18966_Content_11 = {
    Text = [[
Itu memutarbalikkan segalanya, sekaligus menciptakan segalanya. 
Bahan yang terbuang mendapatkan kehidupan baru berkatnya, dan membuat perjanjian denganku.]]
  },
  AvgDialog_18966_Content_12 = {
    Text = "Seolah-olah merespons kedatangan tuannya yang kembali, patung lilin itu tertawa lebih riang dengan segenap tenaga."
  },
  AvgDialog_18966_Content_13 = {
    Text = "<Shake:Rogers… Rogers…>"
  },
  AvgDialog_18966_Content_14 = {
    Text = "<Shake:La la la la la~>"
  },
  AvgDialog_18966_Content_15 = {
    Text = "Janji...? Mungkinkah..."
  },
  AvgDialog_18966_Content_16 = {
    Text = "<Yellow:Tiga aturan.> Mereka adalah penjaga paling setia di Museum Lilin, dan akan menghukum dengan tegas para perusak yang tidak bermoral."
  },
  AvgDialog_18966_Content_17 = {
    Text = "Tak terhitung kepala patung lilin yang cacat mengeluarkan gumaman dengan makna yang tidak jelas, lalu tiba-tiba memutar kepala mereka secara serempak, membelalakkan mata, dan menatap kalian."
  },
  AvgDialog_18966_Content_18 = {
    Text = "<Shake:Hukuman, hukuman… hehe…>"
  },
  AvgDialog_18966_Content_19 = {
    Text = "Astaga, mereka menyadari keberadaan kita. Cepat, pergi —"
  },
  AvgDialog_18966_Content_2 = {
    Text = "Ugh... sangat sakit..."
  },
  AvgDialog_18966_Content_20 = {
    Text = "Lilin putih menyebar dengan cepat, dan dalam sekejap langsung melekat erat pada pelanggar yang melampaui batas."
  },
  AvgDialog_18966_Content_21 = {
    Text = "Pergi! Uh..."
  },
  AvgDialog_18966_Content_22 = {
    Text = "Mereka sudah melewati dada Anda, dan sepertinya akan segera masuk ke mulut dan mata Anda…"
  },
  AvgDialog_18966_Content_23 = {
    Text = "Tidak bisa, hampir sesak napas…"
  },
  AvgDialog_18966_Content_26 = {
    Text = "Ting——!"
  },
  AvgDialog_18966_Content_27 = {
    Text = "Tiba-tiba terdengar suara kunci perak menggesek di samping telinga."
  },
  AvgDialog_18966_Content_28 = {
    Text = "<Shake:Hiks hiks hiks hiks hiks…>"
  },
  AvgDialog_18966_Content_29 = {
    Text = "<Shake: Rogers… sakit… sakit…>"
  },
  AvgDialog_18966_Content_3 = {
    Text = "Apa bau ini, sangat busuk…"
  },
  AvgDialog_18966_Content_30 = {
    Text = "Cahaya redup perak tiba-tiba menyala terang, dan kamu baru menyadari bahwa formasi darah telah ditutupi oleh lapisan mantra baru."
  },
  AvgDialog_18966_Content_31 = {
    Text = "Mereka menerangi kegelapan di balik celah. Wilhelm dan alat Observasi Pelarutannya yang sedikit berat muncul di hadapan kalian."
  },
  AvgDialog_18966_Content_32 = {
    Text = "Kak William…! Apakah ini mantra yang kau tulis, sungguh indah…"
  },
  AvgDialog_18966_Content_33 = {
    Text = "William sedikit mengangkat matanya, memastikan kalian selamat, lalu melanjutkan menatap panel skala di hadapannya."
  },
  AvgDialog_18966_Content_34 = {
    Text = "Kalian datang tepat pada waktunya, aku hampir mengira kalian tidak akan bertahan sampai sekarang."
  },
  AvgDialog_18966_Content_35 = {Text = "Cicit~!"},
  AvgDialog_18966_Content_36 = {
    Text = "Cokelat menggeliat dengan tubuhnya yang besar, muncul dari atas kepala William."
  },
  AvgDialog_18966_Content_37 = {
    Text = "Cokelat! Aku pikir aku telah kehilanganmu...!"
  },
  AvgDialog_18966_Content_38 = {
    Text = "Pekerjaan menutup celah telah mencapai 70%. Sangat berbahaya jika meninggalkan tempat ini secara sembarangan. Saya harus tetap di sini untuk menstabilkan fluktuasi pelarutan."
  },
  AvgDialog_18966_Content_39 = {
    Text = "%player%, tolong bantu aku menunda sedikit lagi."
  },
  AvgDialog_18966_Content_4 = {
    Text = "Ssst… Jangan bicara. Lihat ke depan."
  },
  AvgDialog_18966_Content_40 = {Text = "Mengerti!"},
  AvgDialog_18966_Content_41 = {
    Text = "Bukankah kamu sudah... sudah dipukul sampai pingsan olehnya..."
  },
  AvgDialog_18966_Content_42 = {
    Text = "Maaf, Tuan Rogers. Terkadang \"menipu\" juga merupakan keterampilan yang harus dimiliki oleh seorang penyelidik."
  },
  AvgDialog_18966_Content_43 = {
    Text = "Berkat wanita itu, saya bisa menemukan tempat ini tanpa kesulitan."
  },
  AvgDialog_18966_Content_44 = {
    Text = "Hmph, penyelidik yang sangat licik."
  },
  AvgDialog_18966_Content_45 = {
    Text = "Jangan khawatir, Pemimpin Perpustakaan. Mereka tidak mudah untuk dihadapi."
  },
  AvgDialog_18966_Content_46 = {
    Text = "Kebetulan semua orang sudah berkumpul, jadi bersihkan semuanya sekaligus!"
  },
  AvgDialog_18966_Content_5 = {
    Text = "Sebuah celah raksasa membentang di depan mata, dipenuhi oleh kabut hitam pekat yang mengepul dari dalam hingga ke luar."
  },
  AvgDialog_18966_Content_6 = {
    Text = "Di sekitar celah, di atas lingkaran sihir yang rumit digambar dengan darah, kamu melihat tumpukan besar anggota tubuh patung lilin."
  },
  AvgDialog_18966_Content_7 = {
    Text = "Mereka berjejer rapat, memanjang hingga ke langit-langit. Ribuan mulut terbuka lebar dalam senyuman, membentuk lautan kebahagiaan."
  },
  AvgDialog_18966_Content_8 = {
    Text = "<Shake:Hihihi…>"
  },
  AvgDialog_18966_Content_9 = {
    Text = "Ini, apa ini…"
  },
  AvgDialog_18967_Content_1 = {
    Text = "Paman Charlie tidak bisa menemukan kucing lorengnya di mana pun~"
  },
  AvgDialog_18967_Content_10 = {
    Text = "Tak dapat mengendalikan nasib sendiri, juga tak bisa membantu orang lain."
  },
  AvgDialog_18967_Content_11 = {
    Text = "Sama seperti saya, hanya bisa melihat Aigis berlalu dari depan saya…"
  },
  AvgDialog_18967_Content_12 = {
    Text = "Jenkin berkata, tiba-tiba menghirup napas melalui hidungnya."
  },
  AvgDialog_18967_Content_13 = {
    Text = [[
Eh, ngapain ngomongin hal-hal yang nggak berguna. 
Setelah lama bareng kalian, aku juga jadi aneh, ha, hahaha.]]
  },
  AvgDialog_18967_Content_14 = {Text = "Jenkin…"},
  AvgDialog_18967_Content_15 = {
    Text = "Ramona menghela napas pelan, lalu mengusap kepala Jenkin."
  },
  AvgDialog_18967_Content_16 = {
    Text = "Tidak heran kamu terus merasa sedih, apakah kamu menyalahkan diri sendiri? Aku akan memberitahumu sebuah rahasia."
  },
  AvgDialog_18967_Content_17 = {
    Text = "Di hadapan Clades, baik Penjaga maupun pengemis yang terlantar di jalanan, tidak ada perbedaan sama sekali."
  },
  AvgDialog_18967_Content_18 = {
    Text = "Ini adalah misi kedua saya dan %player%, tidak jauh lebih baik darimu, lho."
  },
  AvgDialog_18967_Content_19 = {
    Text = "Masih banyak hal yang perlu kupelajari darimu, <Blue:\"Sang Master Bertahan Hidup di Jalanan\">."
  },
  AvgDialog_18967_Content_2 = {
    Text = "Dia menangis dan menangis sampai dirinya sendiri lenyap~"
  },
  AvgDialog_18967_Content_20 = {Text = "Ramona..."},
  AvgDialog_18967_Content_21 = {
    Text = "Kemampuanmu untuk menghibur orang juga tidak begitu bagus, ya. Namun, tetap saja terima kasih."
  },
  AvgDialog_18967_Content_3 = {
    Text = "Menghilang~"
  },
  AvgDialog_18967_Content_4 = {
    Text = "Patung lilin kecil yang bahagia bergandengan tangan, berjalan dengan goyang-goyang melewati koridor redup Museum Lilin."
  },
  AvgDialog_18967_Content_5 = {
    Text = "Hu... untuk sementara berhasil menghindar."
  },
  AvgDialog_18967_Content_6 = {
    Text = "Semua salahku... aku terlalu ceroboh, sehingga menempatkan semua orang dalam bahaya."
  },
  AvgDialog_18967_Content_7 = {
    Text = "Tidak perlu terlalu keras pada diri sendiri, sangat normal bagi orang biasa untuk kurang waspada terhadap Acara abnormal."
  },
  AvgDialog_18967_Content_8 = {
    Text = "...Benar-benar iri pada kalian."
  },
  AvgDialog_18967_Content_9 = {
    Text = "Aku benci menjadi orang biasa. Orang biasa benar-benar tidak berguna."
  },
  AvgDialog_18968_Content_1 = {
    Text = [[
Sial, masih kehilangan jejak juga... 
Ini tempat apa, berantakan sekali, seperti habis dijarah.]]
  },
  AvgDialog_18968_Content_10 = {
    Text = "Di rumahku tidak memelihara tikus pemalas!"
  },
  AvgDialog_18968_Content_11 = {
    Text = "Tikus yang terabaikan menggoyangkan tubuhnya yang gemuk, merangkak dengan sempoyongan menuju sudut kantor."
  },
  AvgDialog_18968_Content_12 = {
    Text = "Di sana ada sebuah patung lilin kecil yang ditutupi kain putih, berdiri sendirian di sudut, tampaknya sedang dengan sabar menunggu…"
  },
  AvgDialog_18968_Content_13 = {
    Text = "Menunggu untuk diangkat tabirnya."
  },
  AvgDialog_18968_Content_14 = {
    Text = "Bagus sekali, begitu saja... di dalamnya ada banyak makanan, semuanya keju..."
  },
  AvgDialog_18968_Content_15 = {
    Text = "Cukup angkat dengan lembut..."
  },
  AvgDialog_18968_Content_16 = {
    Text = "Cit cit cit!"
  },
  AvgDialog_18968_Content_17 = {
    Text = "…Cokelat?"
  },
  AvgDialog_18968_Content_18 = {
    Text = "Cokelat sudah memanjat alas patung lilin, cakar kecilnya dengan susah payah mencoba menarik kain penutupnya."
  },
  AvgDialog_18968_Content_19 = {
    Text = "Astaga! Aku ingat aturan kedua di Museum Lilin adalah——"
  },
  AvgDialog_18968_Content_2 = {
    Text = [[
Sepertinya ini adalah kantor Rogers.
Teh di atas meja masih hangat, sepertinya seseorang baru saja pergi.]]
  },
  AvgDialog_18968_Content_20 = {
    Text = "Dilarang membuka kain penutup patung lilin"
  },
  AvgDialog_18968_Content_21 = {
    Text = "Benar, syukurlah masih ada orang yang sadar di sini."
  },
  AvgDialog_18968_Content_22 = {
    Text = "Dilarang berisik"
  },
  AvgDialog_18968_Content_23 = {
    Text = "Jika memang ada aturan seperti itu, kita pasti sudah mati sejak lama."
  },
  AvgDialog_18968_Content_24 = {
    Text = "Aku benar-benar tidak ingat apa pun."
  },
  AvgDialog_18968_Content_25 = {
    Text = "Jika kamu ingin membuatku marah, aku nyatakan bahwa kamu berhasil. Dasar kau."
  },
  AvgDialog_18968_Content_26 = {
    Text = "<Yellow:Aturan kedua: Dilarang membuka kain penutup patung lilin.>"
  },
  AvgDialog_18968_Content_27 = {
    Text = "Harus segera menghentikannya, jika tidak, akibatnya akan sangat mengerikan!"
  },
  AvgDialog_18968_Content_28 = {
    Text = "Cokelat, berhenti sekarang juga! Kalau tidak... kalau tidak, aku akan meninggalkanmu!"
  },
  AvgDialog_18968_Content_29 = {
    Text = "Menghadapi ancaman tuannya, tikus kecil itu sama sekali tidak gentar."
  },
  AvgDialog_18968_Content_3 = {
    Text = "Cokelat yang terus-menerus tertidur di pundak Jenkin tiba-tiba mengeluarkan suara lemah. Cokelat membuka kedua matanya yang berwarna merah darah dan dengan gelisah melihat ke sekeliling."
  },
  AvgDialog_18968_Content_30 = {
    Text = "Itu menyipitkan kedua matanya, membusungkan dadanya seperti seorang jenderal kecil yang angkuh, lalu dengan sangat ringan membuka kain penutupnya."
  },
  AvgDialog_18968_Content_31 = {
    Text = "<RedShake:Uuh uuh uuh... mata, mata...>"
  },
  AvgDialog_18968_Content_32 = {
    Text = "<RedShake:Terlalu terang, terlalu terang…>"
  },
  AvgDialog_18968_Content_33 = {
    Text = "<Big:Cokelat, kamu kamu kamu——!!>"
  },
  AvgDialog_18968_Content_34 = {
    Text = "Di bawah Gheb, terdapat sebuah patung setengah badan seorang pria dewasa."
  },
  AvgDialog_18968_Content_35 = {
    Text = "Alisnya terangkat tinggi, wajahnya yang kurus dipenuhi kerutan, dan bibirnya juga tertutup rapat."
  },
  AvgDialog_18968_Content_36 = {
    Text = "Wajah ini pernah meninggalkan kesan mendalam pada dirimu: pemahat patung lilin yang terkenal kejam di koran."
  },
  AvgDialog_18968_Content_37 = {
    Text = "Kamu menatap rongga mata patung lilin yang kosong dan berpikir bahwa ada sesuatu yang berbeda — matanya telah dicungkil."
  },
  AvgDialog_18968_Content_38 = {
    Text = "Dong——！Dong——！"
  },
  AvgDialog_18968_Content_39 = {
    Text = "Lonceng berbunyi kembali, lebih mendesak dan lebih kuat daripada sebelumnya, bergema di ruangan yang gelap, menusuk telinga seperti tawa histeris."
  },
  AvgDialog_18968_Content_4 = {Text = "Ciiit..."},
  AvgDialog_18968_Content_40 = {
    Text = "Ehem, ehem, ini adalah waktu siaran dari Pandia~"
  },
  AvgDialog_18968_Content_41 = {
    Text = "Kasihan sekali tikus kecil itu, bagaimana bisa begitu ceroboh hingga menyingkap kain penutupnya ya~"
  },
  AvgDialog_18968_Content_42 = {
    Text = "<Red: Sekarang saya umumkan di sini, aturan kedua resmi dilanggar!>"
  },
  AvgDialog_18968_Content_43 = {
    Text = "Cokelat, Cokelat pasti tidak sengaja..."
  },
  AvgDialog_18968_Content_44 = {
    Text = "Hihi, bagaimana kalau setelah sampai di bawah tanah, kamu jelaskan kepada <Blue:mereka>?"
  },
  AvgDialog_18968_Content_45 = {
    Text = "Astaga, hampir saja aku lupa, mereka sama sekali tidak mengerti apa yang kukatakan! Oh hehehe…"
  },
  AvgDialog_18968_Content_46 = {
    Text = "Tawa riang sang gadis perlahan-lahan menghilang dari siaran radio. Kamu mulai merasakan pusing yang datang berulang kali."
  },
  AvgDialog_18968_Content_47 = {
    Text = "Astaga... kepala terasa sangat pusing..."
  },
  AvgDialog_18968_Content_48 = {
    Text = "Kepalamu terasa semakin berat."
  },
  AvgDialog_18968_Content_49 = {
    Text = "Di malam yang membingungkan ini, kamu adalah ngengat yang terperangkap dalam amber, dibungkus oleh resin hitam dari tawa dan nyanyian, tenggelam ke dasar yang paling dalam."
  },
  AvgDialog_18968_Content_5 = {
    Text = "Kamu pasti sangat lapar, tikus kecil…"
  },
  AvgDialog_18968_Content_50 = {
    Text = "<Shake:Hihi. Cekik, cekik, cekik!>"
  },
  AvgDialog_18968_Content_51 = {
    Text = "<Shake: Mencekik, mencekik, mencekik…>"
  },
  AvgDialog_18968_Content_52 = {
    Text = "Tidak, tidak...!"
  },
  AvgDialog_18968_Content_54 = {
    Text = "Satu detik sebelum kehabisan napas, tanganmu dipegang erat oleh seseorang."
  },
  AvgDialog_18968_Content_55 = {
    Text = "Jangan takut, %player%. Kita akan baik-baik saja."
  },
  AvgDialog_18968_Content_56 = {
    Text = "<Shake: Ramona, orang yang takut itu kamu, kan. Tanganmu masih... masih gemetar…>"
  },
  AvgDialog_18968_Content_58 = {
    Text = "Dalam kegelapan, kamu mendengar tawa lemah seorang gadis, seakan-akan sangat jauh dari kamu, namun juga terasa begitu dekat."
  },
  AvgDialog_18968_Content_59 = {
    Text = "Kamu juga begitu, %player%."
  },
  AvgDialog_18968_Content_6 = {
    Text = "Lapar sekali, ya..."
  },
  AvgDialog_18968_Content_7 = {Text = "Cit!"},
  AvgDialog_18968_Content_8 = {
    Text = "Ya, kenapa Cokelat melompat ke bawah."
  },
  AvgDialog_18968_Content_9 = {
    Text = "Abaikan saja. Setelah tidur begitu lama, sudah waktunya untuk bangun dan bergerak."
  },
  AvgDialog_18969_Content_1 = {
    Text = "Patung lilin… hidup kembali?"
  },
  AvgDialog_18969_Content_2 = {
    Text = "Pada saat kamu melanggar aturan, mereka semua langsung hidup kembali, lho~"
  },
  AvgDialog_18969_Content_3 = {
    Text = "Nikmati malam yang indah ini, sayang-sayangku~"
  },
  AvgDialog_18969_Content_4 = {
    Text = "<Shake:Hihiihiihii……>"
  },
  AvgDialog_18969_Content_5 = {
    Text = "Tidak bisa… jumlahnya terlalu banyak!"
  },
  AvgDialog_18969_Content_6 = {
    Text = "Hei... Ramona, kamu sangat pintar, pasti ada cara untuk menghadapi mereka, kan?"
  },
  AvgDialog_18969_Content_7 = {
    Text = "Melihat situasi saat ini, pilihan yang tersisa bagi kita mungkin tidak banyak——"
  },
  AvgDialog_18969_Content_8 = {
    Text = "<Big:Lari!>"
  },
  AvgDialog_18970_Content_1 = {
    Text = "Bagaimana ini, jika tidak bisa menemukannya, Jenkin akan merasa tidak senang, ciyeeet…"
  },
  AvgDialog_18970_Content_2 = {
    Text = "Eh, di sini ada satu lagi jalan keluar…"
  },
  AvgDialog_18970_Content_3 = {
    Text = "Di sini, pasti di sini, ciit!"
  },
  AvgDialog_18971_Content_1 = {
    Text = [[
12:10, Museum Lilin Rogers
Basement]]
  },
  AvgDialog_18971_Content_10 = {
    Text = "Pemeriksaan selesai, diameter 18,54 kaki, kedalaman 65,4… sebuah <Yellow:celah Kelas C>."
  },
  AvgDialog_18971_Content_11 = {
    Text = "Diameternya terlalu kecil, tak heran sebelumnya tidak dapat mendeteksi keberadaannya. Langkah berikutnya adalah memastikan rentang aktivitasnya…"
  },
  AvgDialog_18971_Content_12 = {
    Text = "Cokelat berkeliling di sekitar William, tiba-tiba memperhatikan sudut tas tangan yang terbuka dan menampakkan sebagian dari map dokumen."
  },
  AvgDialog_18971_Content_14 = {
    Text = "Ciiit——<Big:Ciiit ciiit!!>"
  },
  AvgDialog_18971_Content_15 = {
    Text = "Cokelat dengan cepat mengambil tas dokumen dan berlari pergi."
  },
  AvgDialog_18971_Content_16 = {
    Text = "……<Big:Hei!>"
  },
  AvgDialog_18971_Content_17 = {
    Text = "Tap. Tap. Tap."
  },
  AvgDialog_18971_Content_18 = {
    Text = "Itu adalah suara tapak kecil sepatu, seseorang dengan langkah yang tidak terburu-buru datang mendekat."
  },
  AvgDialog_18971_Content_19 = {
    Text = "Jangan sampai ketahuan… Cari tempat untuk bersembunyi dulu."
  },
  AvgDialog_18971_Content_2 = {
    Text = "Cicit... cicit?"
  },
  AvgDialog_18971_Content_20 = {
    Text = "Mari lihat, siapa yang mengganggu George saat makan?"
  },
  AvgDialog_18971_Content_21 = {
    Text = "Ciiit ciiit——!!"
  },
  AvgDialog_18971_Content_22 = {
    Text = "Ternyata tikus kecil. Hari ini George sedang berada dalam suasana hati yang baik, jadi..."
  },
  AvgDialog_18971_Content_23 = {
    Text = "George melemparkan segumpal Caro ke depan Cokelat."
  },
  AvgDialog_18971_Content_24 = {Text = "Makanlah."},
  AvgDialog_18971_Content_25 = {
    Text = "——Cicit?"
  },
  AvgDialog_18971_Content_26 = {
    Text = "Dasar bodoh, kamu pasti lapar, kan?"
  },
  AvgDialog_18971_Content_27 = {
    Text = "Cicit! Cicit…? Cicit…"
  },
  AvgDialog_18971_Content_28 = {
    Text = "Segera beritahu George bahwa kamu lapar."
  },
  AvgDialog_18971_Content_29 = {
    Text = "Suara yang penuh misteri itu seperti riak di permukaan air, menyebar keluar lingkaran demi lingkaran, hingga udara dipenuhi dengan gema yang ramai."
  },
  AvgDialog_18971_Content_3 = {Text = "...tikus?"},
  AvgDialog_18971_Content_30 = {
    Text = "Kamu lapar... Kamu lapar..."
  },
  AvgDialog_18971_Content_31 = {
    Text = "Lapar@1Lapar lapar@4Lapar……"
  },
  AvgDialog_18971_Content_32 = {
    Text = "Ciiit... <Big:Ciiit!>"
  },
  AvgDialog_18971_Content_33 = {
    Text = "Mata tikus itu memerah. Ia menyeringai, menampakkan taring tajamnya, lalu menundukkan kepalanya ke dalam daging busuk dan melahapnya dengan rakus."
  },
  AvgDialog_18971_Content_34 = {
    Text = "Tikus yang patuh... tikus malang dan bodoh yang patuh..."
  },
  AvgDialog_18971_Content_35 = {
    Text = "Sementara itu, di dalam studio..."
  },
  AvgDialog_18971_Content_4 = {
    Text = "Grrr grrr..."
  },
  AvgDialog_18971_Content_5 = {
    Text = "Suara kunyahan yang serakah terdengar samar-samar, bergema di ruang bawah tanah yang gelap gulita."
  },
  AvgDialog_18971_Content_6 = {Text = "...?"},
  AvgDialog_18971_Content_7 = {
    Text = "Ssst... jangan mendekat, di sini sangat berbahaya."
  },
  AvgDialog_18971_Content_8 = {
    Text = "Jangan bangunkan \"mereka\"."
  },
  AvgDialog_18971_Content_9 = {
    Text = "William tidak mengangkat kepalanya, tetap fokus menatap angka-angka yang terus bergerak di layar instrumen di depannya."
  },
  AvgDialog_18972_Content_10 = {
    Text = "Tentu saja. Nilai saya dalam tiga tahun terakhir untuk kelas anatomi di Mythag adalah A+, A+, A++."
  },
  AvgDialog_18972_Content_11 = {
    Text = "Di dalam tengkorak masih tersisa beberapa jaringan tubuh dan darah… Sama seperti rumor yang beredar, <Red:patung lilin memang dibuat dari orang hidup.>"
  },
  AvgDialog_18972_Content_12 = {
    Text = "Ternyata... apa yang disebut seniman besar atau dermawan besar, ternyata di balik layar mereka melakukan hal semacam ini."
  },
  AvgDialog_18972_Content_13 = {
    Text = "Kamu melihat sekeliling, patung lilin dengan senyuman manis berkumpul di ruang pameran, seperti anak-anak, dewasa, dan hewan peliharaan yang paling bahagia di dunia."
  },
  AvgDialog_18972_Content_14 = {
    Text = "Siapa yang bisa membayangkan bahwa kebahagiaan ini terbentuk dari Caro yang nyata?"
  },
  AvgDialog_18972_Content_15 = {
    Text = "Kakak, jika benar-benar jatuh ke tangannya..."
  },
  AvgDialog_18972_Content_16 = {
    Text = "Saya sudah kehilangan Aigis, tidak bisa kehilangan Kakak lagi…"
  },
  AvgDialog_18972_Content_17 = {
    Text = "Klik. Klik. Klik."
  },
  AvgDialog_18972_Content_18 = {
    Text = "Dengan suara isak yang lemah, sepasang tangan muncul dari kegelapan dan perlahan menyentuh pipi Jenkin."
  },
  AvgDialog_18972_Content_19 = {
    Text = "Jenkin…<Big:Cepat menghindar! Ada sesuatu di belakangmu!>"
  },
  AvgDialog_18972_Content_2 = {
    Text = "Pandia... orang itu memang aneh."
  },
  AvgDialog_18972_Content_20 = {
    Text = "<BigBold:?>!"
  },
  AvgDialog_18972_Content_21 = {Text = "Huhuhu..."},
  AvgDialog_18972_Content_22 = {
    Text = "Bayangan hitam merayap perlahan di dalam patung lilin, seperti bayi yang menanti untuk dilahirkan, meregangkan lilin lunak menjadi membran tipis yang hampir transparan."
  },
  AvgDialog_18972_Content_23 = {
    Text = "Ada sesuatu, merangkak keluar dari patung lilin..."
  },
  AvgDialog_18972_Content_24 = {
    Text = "Sebuah kepala."
  },
  AvgDialog_18972_Content_25 = {
    Text = "Kepala seorang wanita. Ia menjulur keluar dari patung lilin, rambut panjangnya lengket dan terseret oleh lilin."
  },
  AvgDialog_18972_Content_26 = {
    Text = "Itu mengangkat wajahnya, memperlihatkan kedua matanya yang kosong dan gelap."
  },
  AvgDialog_18972_Content_27 = {
    Text = "<Shake:Tolong…>"
  },
  AvgDialog_18972_Content_28 = {
    Text = "<Shake: Tolong aku…>"
  },
  AvgDialog_18972_Content_3 = {
    Text = "Barusan aku merasakan sesuatu di perutnya… terasa sangat nyata!"
  },
  AvgDialog_18972_Content_4 = {
    Text = "Tetapi dia jelas merupakan patung lilin…"
  },
  AvgDialog_18972_Content_5 = {
    Text = [[
Omong kosong tidak cukup, mari kita verifikasi. 
 Saat berurusan dengan patung lilin tadi, aku sempat mengambil sesuatu.]]
  },
  AvgDialog_18972_Content_6 = {
    Text = "Lancar, sangat lancar?!"
  },
  AvgDialog_18972_Content_7 = {
    Text = "\"Gadis muda yang memimpin kekacauan dengan berlarian\" — Saya pikir Hanna akan menyukai judul berita ini."
  },
  AvgDialog_18972_Content_8 = {
    Text = "Ramona tidak merespons, hanya dengan hati-hati memeriksa bagian dalam rongga tengkorak menggunakan tangannya."
  },
  AvgDialog_18972_Content_9 = {
    Text = "Kamu tampaknya... sangat mahir, hampir menyamai Pak Johnny yang berjualan daging babi di sebelah rumahku."
  },
  AvgDialog_18973_Content_1 = {
    Text = "Ugh! Aaaaaa—"
  },
  AvgDialog_18973_Content_10 = {
    Text = "Sampai jumpa."
  },
  AvgDialog_18973_Content_11 = {
    Text = "Berhenti, jangan coba kabur!!"
  },
  AvgDialog_18973_Content_2 = {
    Text = "24 bernapas dengan cepat, lalu mendorong kepalanya dengan tangannya."
  },
  AvgDialog_18973_Content_3 = {
    Text = "Tulang leher yang awalnya terputus kembali ke posisi semula, ekspresi 24 secara bertahap berubah dari menyeramkan menjadi lembut."
  },
  AvgDialog_18973_Content_5 = {
    Text = "Kalian... ternyata berbeda. Mungkin..."
  },
  AvgDialog_18973_Content_6 = {
    Text = "Sebuah senyuman singkat muncul di wajah 24. Ini adalah pertama kalinya kamu melihat senyumannya."
  },
  AvgDialog_18973_Content_7 = {
    Text = "Dia perlahan melangkah mundur, wajahnya yang pucat dan murung sebagian besar tersembunyi dalam bayangan."
  },
  AvgDialog_18973_Content_8 = {
    Text = "Maaf, %player%. Bermain bersama kalian sangat menyenangkan."
  },
  AvgDialog_18973_Content_9 = {
    Text = "Tapi... hanya itu saja."
  },
  AvgDialog_18974_Content_1 = {
    Text = "Sangat lapar, George sangat lapar..."
  },
  AvgDialog_18975_Content_1 = {
    Text = "Huh, huh, huh…"
  },
  AvgDialog_18975_Content_2 = {Text = "?!"},
  AvgDialog_18975_Content_3 = {
    Text = "Di depan ada jejak manusia, ciiit!"
  },
  AvgDialog_18975_Content_4 = {
    Text = "Tapi di sini terkunci, harus mencari kunci dulu!"
  },
  AvgDialog_18976_Content_1 = {
    Text = "Ugh……!!"
  },
  AvgDialog_18976_Content_10 = {
    Text = "Ramona mencabut pedang tipisnya dan dengan lembut meletakkannya di pundak 24."
  },
  AvgDialog_18976_Content_11 = {
    Text = "Nona 24, reaksimu sudah mengkhianati dirimu sendiri. Bawa kami menemukan patung lilin, atau tumbang di bawah pedangku."
  },
  AvgDialog_18976_Content_12 = {
    Text = "Pilih satu?"
  },
  AvgDialog_18976_Content_14 = {
    Text = "Patung lilin ini...\"Spring\", apakah itu sangat penting bagi kalian?"
  },
  AvgDialog_18976_Content_15 = {
    Text = "Untuk menemukan kakak perempuanku, Mason."
  },
  AvgDialog_18976_Content_16 = {
    Text = "Meskipun terdengar agak aneh, aku tidak bisa mengingat wajahnya dengan jelas…"
  },
  AvgDialog_18976_Content_17 = {
    Text = "Hanya tahu bahwa dia mungkin telah dijadikan patung lilin, dan disembunyikan di dalam kelompok patung lilin yang bernama \"Musim Semi Laut Baltik\"."
  },
  AvgDialog_18976_Content_18 = {
    Text = "<Small:Ini adalah 《Primavera》 karya Botticelli… Ah, tidak penting.>"
  },
  AvgDialog_18976_Content_19 = {
    Text = "Aku tidak mengerti... Katamu Mason adalah kakakmu, tapi kamu tidak ingat seperti apa rupanya?"
  },
  AvgDialog_18976_Content_2 = {
    Text = "Apa... yang terjadi..."
  },
  AvgDialog_18976_Content_20 = {
    Text = "Ah! Maafkan saya, saya tidak bermaksud meragukan Anda..."
  },
  AvgDialog_18976_Content_21 = {
    Text = "Tempat ini aneh, bisa menghilangkan memori seseorang."
  },
  AvgDialog_18976_Content_22 = {
    Text = "Bisa jadi kita akan segera menjadi orang bodoh seperti Nenek Vanessa."
  },
  AvgDialog_18976_Content_23 = {
    Text = "Nenek Vanessa?"
  },
  AvgDialog_18976_Content_24 = {
    Text = "Pemilik rumah saya sebelumnya. Selain uang sewa yang harus saya bayar kepadanya setiap bulan, saya tidak mengerti apa pun tentang hal lain."
  },
  AvgDialog_18976_Content_25 = {
    Text = "<SmallShake: Sialan! Hal-hal yang seharusnya tidak diingat malah diingat dengan sangat jelas…>"
  },
  AvgDialog_18976_Content_26 = {
    Text = "Ternyata begitu."
  },
  AvgDialog_18976_Content_27 = {
    Text = "Lalu, apakah kamu nanti akan menjadi seperti aku, tidak ingat apa-apa?"
  },
  AvgDialog_18976_Content_28 = {
    Text = "Mungkin saja, siapa yang tahu?"
  },
  AvgDialog_18976_Content_29 = {
    Text = "Bagi saya, ini bukan masalah. Selama kakak berdiri di depan saya, saya pasti akan mengenalinya."
  },
  AvgDialog_18976_Content_3 = {
    Text = "24 duduk terdiam di tanah, lalu mengulurkan tangan untuk meraba kepalanya."
  },
  AvgDialog_18976_Content_30 = {
    Text = "Huh huh……Kenapa aku memberitahumu tentang ini."
  },
  AvgDialog_18976_Content_31 = {
    Text = "Kamu hanyalah orang yang tidak ingat apa pun. Sungguh memprihatinkan."
  },
  AvgDialog_18976_Content_32 = {
    Text = "Ya... aku tidak bisa melakukan apa pun, dan tidak ingat apa pun."
  },
  AvgDialog_18976_Content_33 = {
    Text = "24 berkata, air mata kembali mengalir."
  },
  AvgDialog_18976_Content_34 = {
    Text = "Aku benar-benar tidak berguna... hiks hiks..."
  },
  AvgDialog_18976_Content_36 = {
    Text = "Saya juga ingin melakukan hal lain, tetapi... tetapi saya merasa begitu tidak berguna, hanya mampu melakukan pekerjaan kasar seperti ini..."
  },
  AvgDialog_18976_Content_37 = {
    Text = "Aigis seperti ini, kamu juga begitu…"
  },
  AvgDialog_18976_Content_38 = {
    Text = "<Big:Jangan menangis!>"
  },
  AvgDialog_18976_Content_39 = {
    Text = "Aku paling benci orang yang suka menangis tersedu-sedu, <Big:Mengganggu atau tidak?!>"
  },
  AvgDialog_18976_Content_4 = {
    Text = "<Shake: Jangan, jangan bunuh aku… Aku tidak sengaja, tidak sengaja…>"
  },
  AvgDialog_18976_Content_40 = {
    Text = "Baik, baik... aku tidak akan menangis lagi... maaf..."
  },
  AvgDialog_18976_Content_41 = {
    Text = "Hapus air mataku sampai bersih, mengerti?"
  },
  AvgDialog_18976_Content_42 = {
    Text = "<Yellow:Di depanku, pertama tidak boleh menangis, kedua tidak boleh mengucapkan maaf.>"
  },
  AvgDialog_18976_Content_43 = {
    Text = "Jenkin meletakkan kedua tangannya di pinggang dan mengangkat dagu lancipnya dengan percaya diri."
  },
  AvgDialog_18976_Content_44 = {
    Text = "Lagipula, siapa yang mengatakan bahwa kamu tidak berguna?"
  },
  AvgDialog_18976_Content_45 = {
    Text = "Patuh saja dan bawa kami menemukan patung lilin, itulah guna terbesarmu. Mengerti?"
  },
  AvgDialog_18976_Content_46 = {
    Text = "Baik, baik..."
  },
  AvgDialog_18976_Content_47 = {
    Text = "Melihat 24 begitu patuh, Jenkin mengangguk dengan puas."
  },
  AvgDialog_18976_Content_48 = {
    Text = "Kita sudah menyia-nyiakan banyak waktu di sini, ayo segera berangkat!"
  },
  AvgDialog_18976_Content_49 = {
    Text = "Mungkin Kakak Kelas William masih menunggu dengan penuh harap agar kita menyelamatkannya."
  },
  AvgDialog_18976_Content_5 = {
    Text = "Kalian terjebak di sini, kan, sama seperti yang lainnya…"
  },
  AvgDialog_18976_Content_50 = {
    Text = "Apa, apa ini! Patung lilin ada di <Blue:studio>, bukan di sana…"
  },
  AvgDialog_18976_Content_52 = {
    Text = "Sepertinya kamu ingin mengatakan sesuatu padaku?"
  },
  AvgDialog_18976_Content_53 = {
    Text = "Aku hanya sedikit bingung... kenapa tiba-tiba orang ini marah, lalu tiba-tiba tidak marah lagi?"
  },
  AvgDialog_18976_Content_54 = {
    Text = "Maklumi seorang anak yang baru saja kehilangan temannya. Dia hanya ingin membuat 24 dan dirinya sendiri merasa lebih baik."
  },
  AvgDialog_18976_Content_55 = {
    Text = "Tentu saja, dengan caranya sendiri yang unik."
  },
  AvgDialog_18976_Content_6 = {
    Text = "Saya mengenal museum lilin ini, saya bisa membawa kalian keluar!"
  },
  AvgDialog_18976_Content_7 = {
    Text = "Oh? Bawa kami menemukan patung lilin \"Spring\", dan kamu akan bebas."
  },
  AvgDialog_18976_Content_8 = {
    Text = "Saat mendengar \"Spring\", murid 24 tiba-tiba menyusut, dan alisnya juga sedikit berkerut."
  },
  AvgDialog_18976_Content_9 = {
    Text = "Maaf, saya..."
  },
  AvgDialog_18977_Content_1 = {
    Text = "Semua karena kamu... semua karena kalian..."
  },
  AvgDialog_18978_Content_1 = {
    Text = "Tuan Rogers…"
  },
  AvgDialog_18979_Content_1 = {
    Text = "Jangan tinggalkan George, jangan tinggalkan kami...!"
  },
  AvgDialog_18980_Content_1 = {
    Text = "Setelah berkeliling seharian, akhirnya aku menemukan museum lilin."
  },
  AvgDialog_18980_Content_10 = {
    Text = "\"Museum Lilin Rogers\" —— akhirnya kau bisa membedakan tulisan yang memudar di papan nama itu."
  },
  AvgDialog_18980_Content_11 = {
    Text = "Jenkin, bisakah kamu menggambarkan secara kasar seperti apa penampilan Nona Mason?"
  },
  AvgDialog_18980_Content_12 = {
    Text = "Kakakku adalah seorang wanita yang sangat cantik! Rambutnya sangat panjang, dan kulitnya sangat putih..."
  },
  AvgDialog_18980_Content_13 = {
    Text = "Tidak. Rambutnya sangat pendek, kulitnya..."
  },
  AvgDialog_18980_Content_15 = {
    Text = "Jadi, apakah kakaknya ini adalah manusia yang benar-benar ada dalam arti fisik, atau hanya sosok yang mengembara di dalam fantasi Roh-nya?"
  },
  AvgDialog_18980_Content_16 = {Text = "Gawat..."},
  AvgDialog_18980_Content_17 = {
    Text = "Sepertinya aku lupa dengan wajah Kakak… Tidak, bukan hanya wajahnya, bahkan suaranya juga…"
  },
  AvgDialog_18980_Content_18 = {
    Text = "Saya pernah melihat foto Nyonya Mason, dia…"
  },
  AvgDialog_18980_Content_19 = {Text = "Dia..."},
  AvgDialog_18980_Content_2 = {
    Text = [[
Periksa tujuan misi. 
<Yellow:Misi Pertama: Pergi ke Museum Lilin Rogers, cari Nona Mason dan Penyelidik William.>]]
  },
  AvgDialog_18980_Content_20 = {
    Text = "Ramona mengerutkan alisnya, dan bersama Jenkin terjebak dalam keheningan yang aneh."
  },
  AvgDialog_18980_Content_21 = {
    Text = "Eh... bagaimana kalau kita lihat-lihat foto di koran bersama-sama?"
  },
  AvgDialog_18980_Content_22 = {
    Text = "Kamu membuka surat kabar yang dibawa Jenkin, tapi tinta di atasnya tampak seperti memiliki hidup sendiri, perlahan-lahan mulai menghilang ——"
  },
  AvgDialog_18980_Content_23 = {
    Text = "Hingga kamu tidak bisa lagi melihat dengan jelas laporan tentang \"Spring\"."
  },
  AvgDialog_18980_Content_24 = {
    Text = "Kerusakan pada watermark dan noda tinta ini seolah-olah bertekad untuk sepenuhnya menghapus keberadaan Mason."
  },
  AvgDialog_18980_Content_26 = {
    Text = "Apa, apakah ini sihir? Surat kabar ini sudah kubaca sebanyak delapan ratus kali."
  },
  AvgDialog_18980_Content_27 = {
    Text = "Tapi sekarang... satu kata pun, aku tidak bisa mengingat apa pun."
  },
  AvgDialog_18980_Content_28 = {
    Text = "Eh, kalian benar-benar tidak ingat apa pun?"
  },
  AvgDialog_18980_Content_29 = {
    Text = "\"Pembela utama aliran Kubisme, reinkarnasi Jiwa Botticelli saat ini tinggal di sudut jalan Southwark, di dalam Museum Lilin…\""
  },
  AvgDialog_18980_Content_3 = {
    Text = "<Yellow:Misi Kedua: Penyelidikan kaitan Rogers dengan \"Kasus Hilangnya Workhouse\".>"
  },
  AvgDialog_18980_Content_30 = {
    Text = "Lihat, aku bahkan bisa mengulangi isi berita itu."
  },
  AvgDialog_18980_Content_31 = {
    Text = "Koran telah terlarut. Ini menunjukkan bahwa kemungkinan besar ini adalah fenomena <Yellow:kehilangan ingatan massal> yang disebabkan oleh pelarutan, namun…"
  },
  AvgDialog_18980_Content_32 = {
    Text = "Ramona dan Jenkin serempak menatapmu."
  },
  AvgDialog_18980_Content_33 = {
    Text = "Tampaknya tidak berpengaruh pada seseorang."
  },
  AvgDialog_18980_Content_35 = {
    Text = "Percaya atau tidak, rasanya agak tidak nyaman…"
  },
  AvgDialog_18980_Content_36 = {
    Text = "Sepertinya tanpa disadari, masa lalu telah diubah, dan Cerita pun menyimpang dari jalur yang telah ditentukan."
  },
  AvgDialog_18980_Content_37 = {
    Text = "Dan kamu menjadi satu-satunya saksi atas perubahan-perubahan ini."
  },
  AvgDialog_18980_Content_38 = {
    Text = "Kriiieet——"
  },
  AvgDialog_18980_Content_39 = {
    Text = "Pintu Museum Lilin yang tertutup rapat tiba-tiba terbuka, seolah-olah menyambut kedatangan beberapa tamu tak diundang."
  },
  AvgDialog_18980_Content_4 = {
    Text = "Silakan konfirmasi penerimaan."
  },
  AvgDialog_18980_Content_40 = {
    Text = "Pintu... terbuka dengan sendirinya?"
  },
  AvgDialog_18980_Content_41 = {
    Text = "...Sepertinya rencana penyusupan yang telah kami persiapkan sebelumnya bisa ditunda."
  },
  AvgDialog_18980_Content_42 = {
    Text = [[
Berangkatlah, %player%. 
<Yellow:Sebelum melupakan semuanya, temukan Mason dan William.>]]
  },
  AvgDialog_18980_Content_5 = {
    Text = "Target misi telah diterima, diverifikasi tanpa kesalahan. Sekarang memulai penyelidikan."
  },
  AvgDialog_18980_Content_6 = {
    Text = [[
Konfirmasi selesai. Komunikasi dipertahankan, proses penyelidikan akan dicatat. 
Tugas ini memiliki risiko tinggi, harap tetap berhati-hati.]]
  },
  AvgDialog_18980_Content_7 = {
    Text = "Semoga Kunci Perak menuntun jalanmu."
  },
  AvgDialog_18980_Content_8 = {
    Text = "Kamu mengangkat kepala dan melihat pemandangan jalan yang rusak di depanmu."
  },
  AvgDialog_18980_Content_9 = {
    Text = "Di luar kabut itu, lampu jalan yang bercahaya merah seperti hantu tergantung rendah, samar-samar menerangi papan nama toko-toko di sekitarnya."
  },
  AvgDialog_18981_Content_1 = {Text = "Cicit?"},
  AvgDialog_18981_Content_2 = {
    Text = "Rutenya sangat rumit, ya zhi..."
  },
  AvgDialog_18981_Content_3 = {
    Text = "Ingin pulang untuk makan keju, ci."
  },
  AvgDialog_18982_Content_1 = {Text = "Ugh!"},
  AvgDialog_18982_Content_10 = {
    Text = "Kemudian kamu memfokuskan kekuatan rohmu, mencoba Bangun Ramona yang sedang tidur."
  },
  AvgDialog_18982_Content_11 = {
    Text = "Ramona, cepat bangun!"
  },
  AvgDialog_18982_Content_12 = {
    Text = "Kucing tabby, kucing tabby... harimau, tabby..."
  },
  AvgDialog_18982_Content_13 = {
    Text = "Kamu mengguncang bahu Ramona dengan keras. Ramona berkedip, dan pandangannya perlahan kembali jernih."
  },
  AvgDialog_18982_Content_14 = {
    Text = "Eh, apa yang ada di belakang loreng harimau… Tidak, kenapa aku harus peduli dengan hal yang membosankan seperti ini…"
  },
  AvgDialog_18982_Content_15 = {
    Text = "Bagus sekali, akhirnya kamu bangun!"
  },
  AvgDialog_18982_Content_16 = {
    Text = "Saat kamu tidak ada, banyak hal terjadi. Sebenarnya 24——"
  },
  AvgDialog_18982_Content_17 = {
    Text = "Aku hanya terkunci dalam tindakan, kesadaran masih tersisa meski lemah, dan aku bisa mendengar percakapan kalian."
  },
  AvgDialog_18982_Content_18 = {
    Text = "Mari kita berkenalan kembali, Nona Mason?"
  },
  AvgDialog_18982_Content_2 = {
    Text = "Luka terasa panas dan sangat menyakitkan, sangat menyakitkan! Bagaimana kalian tega memperlakukan aku seperti ini~"
  },
  AvgDialog_18982_Content_20 = {
    Text = "Maaf, aku sebenarnya ingin membawa kalian pergi dari sini…"
  },
  AvgDialog_18982_Content_21 = {
    Text = "<Small:Aku baru pertama kali melihat Pembangun, harus kembali dan bertanya kepada Nona Boneka…>"
  },
  AvgDialog_18982_Content_22 = {
    Text = "Oh ya ya, apakah mengobrol sekarang agak tidak sesuai dengan situasi?"
  },
  AvgDialog_18982_Content_23 = {
    Text = "Meskipun tidak sepenuhnya mengalahkan kalian, ada yang mulai berdarah, ya~"
  },
  AvgDialog_18982_Content_24 = {
    Text = "Kalian mengikuti pandangan Pandia ke bawah."
  },
  AvgDialog_18982_Content_25 = {
    Text = "Darah merah tua mengalir perlahan menyusuri lenganmu, menetes ke tanah."
  },
  AvgDialog_18982_Content_26 = {
    Text = "Satu tetes, dua tetes, tiga tetes…"
  },
  AvgDialog_18982_Content_27 = {
    Text = "<RedShake:Darah, banyak darah…>"
  },
  AvgDialog_18982_Content_28 = {
    Text = "Bangun… cepat bangun…"
  },
  AvgDialog_18982_Content_29 = {
    Text = "Astaga, saat pertempuran tadi tanpa sengaja aku..."
  },
  AvgDialog_18982_Content_3 = {
    Text = "Jenkin! Apakah kamu baik-baik saja?"
  },
  AvgDialog_18982_Content_30 = {
    Text = "<Yellow:Aturan pertama Museum Lilin: Dilarang menyentuh patung lilin.>"
  },
  AvgDialog_18982_Content_31 = {
    Text = "<Yellow:Aturan kedua museum lilin: Jangan membuka kain penutup patung lilin.>"
  },
  AvgDialog_18982_Content_32 = {
    Text = "Adapun aturan ketiga Museum Lilin…"
  },
  AvgDialog_18982_Content_33 = {
    Text = "Dilarang meneteskan darah di dalam museum lilin."
  },
  AvgDialog_18982_Content_34 = {
    Text = "Bingo~! Jawaban benar!"
  },
  AvgDialog_18982_Content_35 = {
    Text = "Dilarang berisik"
  },
  AvgDialog_18982_Content_36 = {
    Text = "Bodoh sekali, bodoh sekali!"
  },
  AvgDialog_18982_Content_37 = {
    Text = "Jika memang ada aturan seperti itu, sudah lama jadi mayat kali~!"
  },
  AvgDialog_18982_Content_38 = {
    Text = "Aku benar-benar tidak ingat apa pun."
  },
  AvgDialog_18982_Content_39 = {
    Text = "Bagaimana kalau aku membantu kamu untuk mengingat-ingat?"
  },
  AvgDialog_18982_Content_4 = {
    Text = "24 berlari seperti terbang menuju Jenkin, lalu melepas belenggu di tubuhnya."
  },
  AvgDialog_18982_Content_40 = {
    Text = "Anak bodoh, kalau begitu biar aku yang memberitahumu."
  },
  AvgDialog_18982_Content_41 = {
    Text = "<Red:Aturan ketiga: Jangan meneteskan darah di museum lilin.>"
  },
  AvgDialog_18982_Content_42 = {
    Text = "Tiga aturan ini adalah <Yellow:perjanjian> antara aku dan mereka. Dengan begini, semuanya telah hancur."
  },
  AvgDialog_18982_Content_43 = {
    Text = "Lalu, para tamu yang melanggar aturan..."
  },
  AvgDialog_18982_Content_44 = {
    Text = "<Red: Nikmati malam yang indah ini sepenuhnya.>"
  },
  AvgDialog_18982_Content_45 = {
    Text = "Dong——！Dong——！"
  },
  AvgDialog_18982_Content_46 = {
    Text = "Semua bandul di dalam gedung mulai merespons dengan semangat, berbagai macam suara lonceng bergabung menjadi lautan gelombang suara."
  },
  AvgDialog_18982_Content_47 = {
    Text = "Ketika tabu sepenuhnya dilanggar, aturan diinjak-injak sembarangan, lonceng penghakiman tidak bisa lagi tetap bungkam, dan semuanya memancarkan ancaman paling tajam."
  },
  AvgDialog_18982_Content_48 = {
    Text = "GRRRUMM——!!"
  },
  AvgDialog_18982_Content_49 = {
    Text = "Tiba-tiba terdengar suara mendengung yang menusuk dari bawah kaki, disertai dengan tangisan anak kecil, menggema di sekitar Museum Lilin."
  },
  AvgDialog_18982_Content_5 = {
    Text = "Dia mengangkat Jenkin, sama seperti yang telah dilakukannya berkali-kali saat masih kecil."
  },
  AvgDialog_18982_Content_50 = {
    Text = "Gurrrrrr——!!"
  },
  AvgDialog_18982_Content_51 = {
    Text = "Seolah-olah sebuah pusaran raksasa terbuka di bawah kakimu, dengan tidak sabar menelan segala sesuatu."
  },
  AvgDialog_18982_Content_52 = {
    Text = "Aaaaah——"
  },
  AvgDialog_18982_Content_6 = {Text = "Kakak..."},
  AvgDialog_18982_Content_7 = {
    Text = "Saya sekarang jauh lebih baik, cepat pergi bantu %player%."
  },
  AvgDialog_18982_Content_8 = {
    Text = "Tidak apa-apa, aku bisa keluar sendiri."
  },
  AvgDialog_18982_Content_9 = {
    Text = "Kunci perak yang diaktifkan telah menyuntikkan kekuatan baru ke dalam dirimu. Kamu menggerakkan tubuhmu dan akhirnya terbebas dari belenggu."
  },
  AvgDialog_18983_Content_1 = {Text = "Kayu cedar"},
  AvgDialog_18983_Content_10 = {
    Text = "Pria yang menyemprotkan cologne, bisakah kamu mendengar ini ——"
  },
  AvgDialog_18983_Content_11 = {
    Text = "Kalian berusaha menurunkan suara semaksimal mungkin, namun tidak mampu lagi menahan kecemasan dan kegentingan di dalam hati."
  },
  AvgDialog_18983_Content_12 = {
    Text = "Teriakan terdengar bergantian tanpa henti, tak lama kemudian, gema yang teredam akhirnya terdengar dari dalam tanah."
  },
  AvgDialog_18983_Content_13 = {
    Text = "...Bising sekali."
  },
  AvgDialog_18983_Content_14 = {
    Text = "Uhuk uhuk…"
  },
  AvgDialog_18983_Content_15 = {
    Text = "Hebat sekali, Kak William! Aku pikir..."
  },
  AvgDialog_18983_Content_16 = {
    Text = "Aku baik-baik saja, hanya mengalami luka ringan. Namun, detektif yang bersamaku..."
  },
  AvgDialog_18983_Content_17 = {
    Text = "Melamun bukanlah kebiasaan yang baik, Penyelidik."
  },
  AvgDialog_18983_Content_18 = {
    Text = "Tidak disangka <Blue:wanita itu> juga memiliki hubungan dengan Para pematung, aku kurang berhati-hati."
  },
  AvgDialog_18983_Content_19 = {
    Text = "Ngomong-ngomong, apakah kalian melihat patung lilin kecil tadi? Rambut pirang keriting, mengenakan gaun hitam…"
  },
  AvgDialog_18983_Content_2 = {
    Text = [[
12:40, Museum lilin Rogers
Studio]]
  },
  AvgDialog_18983_Content_20 = {
    Text = "Kalau kamu naik dan melihat-lihat, kamu akan tahu! Yang paling tidak kurang di sini adalah patung lilin! Untuk model yang kamu maksud, aku bisa langsung menemukan sepuluh untukmu."
  },
  AvgDialog_18983_Content_21 = {
    Text = "Mata sudah hampir kabur melihatnya!"
  },
  AvgDialog_18983_Content_22 = {
    Text = "...Itu bukan patung lilin biasa. Dari reaksi kalian, sepertinya kalian belum pernah melihatnya."
  },
  AvgDialog_18983_Content_23 = {
    Text = "Tidak nyaman berbicara di sini. Beri aku sepuluh menit, Kak."
  },
  AvgDialog_18983_Content_24 = {
    Text = "Kami membuka pintu rahasia, lalu turun untuk mencarimu."
  },
  AvgDialog_18983_Content_3 = {
    Text = "Aneh, bukankah basement itu tempat untuk menahan monster?"
  },
  AvgDialog_18983_Content_4 = {
    Text = "Mengapa Cokelat bisa menemukan barang yang disembunyikan oleh Adik Mason?"
  },
  AvgDialog_18983_Content_5 = {
    Text = "Ramona mengambil kertas surat itu, membolak-baliknya, lalu mendekatkannya ke hidung untuk mencium baunya."
  },
  AvgDialog_18983_Content_6 = {
    Text = "Aroma cologne yang sangat samar... itu William."
  },
  AvgDialog_18983_Content_7 = {
    Text = "Kak William?!"
  },
  AvgDialog_18983_Content_8 = {
    Text = "Kamu membungkukkan tubuhmu, memanjangkan leher untuk mendekati pintu jebakan yang menuju ke ruang bawah tanah."
  },
  AvgDialog_18983_Content_9 = {
    Text = "Kak William, apakah kamu di bawah?"
  },
  AvgDialog_18984_Content_1 = {
    Text = "Aku jelas adalah... yang paling sempurna..."
  },
  AvgDialog_18984_Content_2 = {
    Text = "Yang unik dan satu-satunya..."
  },
  AvgDialog_18984_Content_3 = {
    Text = "Kenapa……"
  },
  AvgDialog_18985_Content_1 = {
    Text = "Umm! Apakah ini... sudah kembali?"
  },
  AvgDialog_18985_Content_10 = {
    Text = "Simbol seni abadi mulai perlahan mencair, hingga akhirnya menampakkan wajah aslinya."
  },
  AvgDialog_18985_Content_11 = {
    Text = "Wanita anggun dengan senyuman samar berubah menjadi wajah yang mengerikan, dia menangis histeris sambil mencari anaknya yang hilang."
  },
  AvgDialog_18985_Content_12 = {
    Text = "Pria yang memesona terus bergetar, namun tak ada lagi setetes air mata yang bisa mengalir dari rongga matanya yang kosong."
  },
  AvgDialog_18985_Content_13 = {
    Text = "Anak kecil yang polos menatap lengan mereka yang cacat, mengeluarkan teriakan bingung."
  },
  AvgDialog_18985_Content_14 = {
    Text = "<Shake: Aaa, tanganku...>"
  },
  AvgDialog_18985_Content_15 = {
    Text = "<Shake: Aku ingat, semuanya sudah kuingat…>"
  },
  AvgDialog_18985_Content_16 = {
    Text = "Tidak, tidak... patung lilin saya..."
  },
  AvgDialog_18985_Content_17 = {
    Text = "Ketika keindahan seni melepaskan selubung halusnya, realitas yang kejam datang tepat pada waktunya."
  },
  AvgDialog_18985_Content_18 = {
    Text = "Patung lilin menangis dan melayang di udara. Mereka serempak memutar kepala, menatap pelaku penyebab semua ini."
  },
  AvgDialog_18985_Content_19 = {
    Text = "Lihat, lihat apa yang kita lakukan, cari anak buah Mythag untuk membalas dendam!"
  },
  AvgDialog_18985_Content_2 = {
    Text = "Pada saat membuka mata, mantra perak di atas celah itu seolah-olah menjadi hidup, mulai bergerak cepat dan berputar…"
  },
  AvgDialog_18985_Content_20 = {
    Text = "Jika kalian melihat George lagi, dia akan mencungkil mata kalian ——"
  },
  AvgDialog_18985_Content_21 = {
    Text = "Sebelum George selesai berbicara, rambut dan pakaiannya tiba-tiba melayang dengan lembut."
  },
  AvgDialog_18985_Content_22 = {
    Text = "Eh……kenapa tubuhku juga……"
  },
  AvgDialog_18985_Content_23 = {
    Text = "George melepaskan diri dari pelukan Rogers dan terbang menuju pusat celah bersama patung lilin yang melayang."
  },
  AvgDialog_18985_Content_24 = {
    Text = "Di malam yang gelap gulita, mereka seperti ubur-ubur bercahaya, perlahan melayang menuju lorong yang dalam dan suram."
  },
  AvgDialog_18985_Content_25 = {
    Text = "<Shake: Tuan, tolong aku... cepat selamatkan aku!!!!!>"
  },
  AvgDialog_18985_Content_26 = {
    Text = "George! Cepat kembali——"
  },
  AvgDialog_18985_Content_27 = {
    Text = "Rogers menarik George, tetapi bersamanya semakin banyak anggota tubuh yang tersisa terjerat dan mengelilinginya."
  },
  AvgDialog_18985_Content_28 = {
    Text = "Tuan, Anda pasti memiliki cara untuk menyelamatkan George... kan?"
  },
  AvgDialog_18985_Content_3 = {
    Text = "Kemudian mereka semua memancarkan cahaya perak yang menyilaukan, hampir menerangi setiap sudut celah tersebut."
  },
  AvgDialog_18985_Content_30 = {
    Text = "Ini adalah hal yang selalu kamu hindari, Rogers."
  },
  AvgDialog_18985_Content_31 = {
    Text = "Sudah kubilang dari awal, kamu tidak bisa berpura-pura seolah-olah semuanya tidak ada."
  },
  AvgDialog_18985_Content_32 = {
    Text = "Saya telah menghabiskan dua, tiga puluh tahun... begitu saja, semuanya hilang?"
  },
  AvgDialog_18985_Content_33 = {
    Text = "Hehe, hehehe… Apakah ini semua palsu? Apakah semuanya hanya ilusi…?"
  },
  AvgDialog_18985_Content_34 = {
    Text = "Mereka tentu saja tidak palsu... mereka hanya terlalu pucat."
  },
  AvgDialog_18985_Content_35 = {
    Text = "Musik, lukisan, patung… semua keindahan dan seni, di hadapan penderitaan yang nyata, tampak pucat."
  },
  AvgDialog_18985_Content_36 = {
    Text = "Di bawah tatapan @2, semuanya rapuh."
  },
  AvgDialog_18985_Content_37 = {
    Text = "Rogers jatuh berlutut, memegang George yang sedang meleleh."
  },
  AvgDialog_18985_Content_38 = {
    Text = "Mimpi buruk ini akan berakhir. Aku akan me... memperbaikimu.... Aku bersumpah...."
  },
  AvgDialog_18985_Content_39 = {
    Text = "Huu hu hu... sakit... sangat sakit..."
  },
  AvgDialog_18985_Content_4 = {Text = "——!!"},
  AvgDialog_18985_Content_40 = {
    Text = "Lilin minyak dengan serakah menempel di lengan Rogers, menusuk kulit dan terus merambat ke bagian yang lebih dalam."
  },
  AvgDialog_18985_Content_41 = {
    Text = "Rogers tidak merasakan sakit sedikit pun. Dia hanya memandang George dengan penuh kesedihan—lebih tepatnya, mata berwarna abu-abu kehijauan milik George."
  },
  AvgDialog_18985_Content_42 = {
    Text = "Lebih dari 70 musim panas yang pengap telah dia habiskan dalam kegelapan, menatap mata ini."
  },
  AvgDialog_18985_Content_43 = {
    Text = "Pupil berwarna abu-abu kehijauan, serta iris berwarna terang yang hanya terlihat jelas di bawah cahaya lilin, seperti riak air yang berlapis-lapis, juga seperti labirin yang tak pernah bisa dilewati."
  },
  AvgDialog_18985_Content_44 = {
    Text = "Dia melihat awal, juga melihat akhir dari itu."
  },
  AvgDialog_18985_Content_45 = {
    Text = "Aku tidak akan membiarkanmu pergi, <Blue:Tuan Patung lilin>…"
  },
  AvgDialog_18985_Content_5 = {
    Text = "William menghela napas lega dan mengangguk padamu dengan penuh penghargaan."
  },
  AvgDialog_18985_Content_6 = {
    Text = "Bagus sekali, %player%. Celah berhasil ditutup."
  },
  AvgDialog_18985_Content_7 = {
    Text = "Namun, kita masih tidak bisa bersantai. Saat-saat sebelum celah menutup sering kali adalah yang paling berbahaya…"
  },
  AvgDialog_18985_Content_8 = {
    Text = "<Big:GRRRUMMMM——!!>"
  },
  AvgDialog_18985_Content_9 = {
    Text = "Seolah merasakan nasib kehancuran yang akan datang, celah itu bergetar dengan putus asa, dan cairan hitam yang kental mengalir deras keluar."
  },
  AvgDialog_18986_Content_1 = {
    Text = "Jenkin, tenanglah!"
  },
  AvgDialog_18986_Content_10 = {
    Text = "Fakta satu, William Delaplume adalah seorang Penyelidik berpengalaman. Jika bahkan dia menghilang…"
  },
  AvgDialog_18986_Content_11 = {
    Text = "Apa yang harus kita hadapi mungkin adalah keberadaan yang lebih berbahaya daripada di panti asuhan."
  },
  AvgDialog_18986_Content_12 = {
    Text = "Fakta kedua, tanpa bantuan kita, dia bahkan tidak akan bisa menyentuh pintu Museum Lilin, apalagi menyelamatkan kakaknya."
  },
  AvgDialog_18986_Content_13 = {
    Text = "Fakta ketiga..."
  },
  AvgDialog_18986_Content_14 = {
    Text = "Boneka belum selesai berbicara, Ramona sudah mematikan komunikator."
  },
  AvgDialog_18986_Content_15 = {
    Text = "Maaf, Jenkin. Kamu baru saja kehilangan teman terbaikmu, pasti merasa sangat sedih."
  },
  AvgDialog_18986_Content_16 = {
    Text = "Aku berjanji padamu, kami pasti akan menemukan kakakmu, asalkan kamu tidak bertindak sembarangan seperti tadi lagi. Mengerti?"
  },
  AvgDialog_18986_Content_17 = {
    Text = "Kamu setuju pergi ke museum lilin denganku? Tapi bos kalian di atas..."
  },
  AvgDialog_18986_Content_18 = {
    Text = "Tidak apa-apa, aku akan membujuknya."
  },
  AvgDialog_18986_Content_2 = {
    Text = "Kamu meraih pergelangan tangan Jenkin, namun dia menepisnya dengan satu tamparan."
  },
  AvgDialog_18986_Content_20 = {
    Text = "Ramona tersenyum tipis dan mengulurkan tangannya kepada Jenkin."
  },
  AvgDialog_18986_Content_21 = {
    Text = "Jadi... <Blue:\"Tim Penyelidikan Museum Lilin Rogers\">, berkumpul lagi?"
  },
  AvgDialog_18986_Content_22 = {
    Text = "Jenkin mendengus pelan, merasa sedikit canggung saat menggenggam tangan Ramona."
  },
  AvgDialog_18986_Content_23 = {
    Text = "Hmm. Apakah ini terlalu kekanak-kanakan?"
  },
  AvgDialog_18986_Content_3 = {Text = "Tenang...?"},
  AvgDialog_18986_Content_4 = {
    Text = "Maaf, seseorang baru saja kehilangan temannya, dan kakaknya juga menghilang tanpa jejak, jadi tidak bisa…"
  },
  AvgDialog_18986_Content_5 = {
    Text = "Tidak bisa tetap tenang berdiri di sana, mendengarkan kalian membahas taktik, melaporkan, memindahkan personel, lalu dengan tenang menjalankan misi."
  },
  AvgDialog_18986_Content_6 = {
    Text = "Kamu tidak mempercayai kami."
  },
  AvgDialog_18986_Content_7 = {
    Text = "Saya percaya kalian, namun saya tidak percaya pada bos kalian."
  },
  AvgDialog_18986_Content_8 = {
    Text = "Mengoreksi: konsultan teknis, bukan bos."
  },
  AvgDialog_18986_Content_9 = {
    Text = "Saya memahami kecemasan seseorang saat kehilangan kerabat dekat yang penting, tetapi sudah seharusnya dia lebih sadar menghadapi realitas."
  },
  AvgDialog_18987_Content_1 = {
    Text = "Gelap gulita, tidak bisa melihat apa pun. Bagaimana kalau itu jebakan.."
  },
  AvgDialog_18987_Content_10 = {
    Text = "Ini adalah alat yang harus dibawa saat bertugas di luar, bukan sesuatu yang istimewa, Nak."
  },
  AvgDialog_18987_Content_2 = {
    Text = "Coba yang ini?"
  },
  AvgDialog_18987_Content_3 = {
    Text = "Dalam kegelapan, Ramona dengan tenang menghidupkan senter, menerangi kembali jalan."
  },
  AvgDialog_18987_Content_4 = {
    Text = "Uwaa, kenapa ada cahaya yang menyembur keluar dari dalam! Apa ini?"
  },
  AvgDialog_18987_Content_5 = {
    Text = [[
Nama ilmiah perangkat elektronik genggam, disingkat senter.
Dapat mencegah kita menabrak dinding, pohon, atau tiang lampu.]]
  },
  AvgDialog_18987_Content_6 = {Text = "Oh……"},
  AvgDialog_18987_Content_7 = {
    Text = "Terkadang saya merasa bahwa ranselmu seperti lubang kelinci yang tak berdasar."
  },
  AvgDialog_18987_Content_8 = {
    Text = "Apakah suatu hari kamu akan mengeluarkan satu set peralatan pesta teh dari dalamnya, seperti yang dikatakan dalam cerita dongeng?"
  },
  AvgDialog_18988_Content_1 = {
    Text = "Semoga kita tidak pernah bertemu lagi seumur hidupku, sayang-sayang kecilku~"
  },
  AvgDialog_18988_Content_10 = {
    Text = "Biarkan dia pergi. Rogers adalah anggota penting dari Para pematung, jadi dia tidak bisa begitu saja dilepaskan."
  },
  AvgDialog_18988_Content_11 = {
    Text = "Mengerti. Lalu, selanjutnya…"
  },
  AvgDialog_18988_Content_12 = {
    Text = "Kalian menoleh ke belakang, menyaksikan kekacauan di hadapan mata."
  },
  AvgDialog_18988_Content_13 = {
    Text = "Tidak, jangan tinggalkan aku..."
  },
  AvgDialog_18988_Content_14 = {
    Text = "<Big:Aaa——!!>"
  },
  AvgDialog_18988_Content_15 = {
    Text = "Pertama-tama kaki, tubuh, lengan..."
  },
  AvgDialog_18988_Content_16 = {
    Text = "Tidak... kalian semua, sampah! Jangan mendekati George..."
  },
  AvgDialog_18988_Content_17 = {
    Text = "Lalu mulut, hidung, mata..."
  },
  AvgDialog_18988_Content_18 = {
    Text = "Kepala emas yang indah milik George terus ditarik oleh patung-patung lilin hingga akhirnya retak sepenuhnya."
  },
  AvgDialog_18988_Content_19 = {
    Text = "<Change>Terima kasih, Rogers! Lezat, makan, makan——!!!"
  },
  AvgDialog_18988_Content_2 = {
    Text = "Kalian tetap di sini dan larutlah dengan patuh dalam pelarutan, jangan pernah muncul dalam ingatanku!"
  },
  AvgDialog_18988_Content_20 = {
    Text = "<Change>Berikan aku sedikit, sedikit saja——!!!"
  },
  AvgDialog_18988_Content_21 = {
    Text = "<Shake: Jangan makan aku, bagaimana kalian berani memakanku... Tidak——>"
  },
  AvgDialog_18988_Content_22 = {
    Text = "Tidak……"
  },
  AvgDialog_18988_Content_23 = {
    Text = "Dengan bergabungnya George, patung lilin dan potongan-potongan mayat yang sebelumnya menumpuk seperti gunungan kembali secara spontan, perlahan-lahan menyatu kembali."
  },
  AvgDialog_18988_Content_24 = {
    Text = "Cairan hitam menetes dari tak terhitung banyaknya mata, bibir, dan telinga mereka."
  },
  AvgDialog_18988_Content_25 = {
    Text = "Kepala besar yang terletak di tengah itu adalah George."
  },
  AvgDialog_18988_Content_26 = {
    Text = "<Change>Hu hu hu… sangat lapar. sangat lapar…"
  },
  AvgDialog_18988_Content_27 = {
    Text = "Semua karena kalian... semua karena kalian..."
  },
  AvgDialog_18988_Content_28 = {
    Text = "<Change>Semua karena kalian!!"
  },
  AvgDialog_18988_Content_3 = {Text = "!!"},
  AvgDialog_18988_Content_4 = {
    Text = "Jangan biarkan dia kabur… %player%, Ramona, apakah kalian bisa menangani ini?"
  },
  AvgDialog_18988_Content_5 = {
    Text = "Kamu dan Ramona mengangguk serempak."
  },
  AvgDialog_18988_Content_6 = {
    Text = "Ancaman terbesar dari celah itu sudah ditutup, sisanya serahkan kepada kami. Tapi Kakak Senior, kamu sendirian..."
  },
  AvgDialog_18988_Content_7 = {
    Text = "Baik, aku percaya kalian. Ingatlah untuk kembali dengan selamat."
  },
  AvgDialog_18988_Content_8 = {
    Text = "Setelah William selesai berbicara, ia menutup perangkat di depannya, lalu membawa koper dan buru-buru mengejar ke luar."
  },
  AvgDialog_18988_Content_9 = {
    Text = "Kakak Senior..."
  },
  AvgDialog_18991_Content_1 = {
    Text = "Hai, Wanita narsis"
  },
  AvgDialog_18991_Content_10 = {
    Text = "Nada suaranya lembut dan penuh keraguan, dengan sedikit aksen yang mencerminkan keanggunan kelas atas."
  },
  AvgDialog_18991_Content_11 = {
    Text = "Meskipun mengucapkan maaf, ekspresinya sama sekali tidak menunjukkan rasa penyesalan, malah terlihat sedikit ejekan."
  },
  AvgDialog_18991_Content_12 = {
    Text = "Baru-baru ini, ada \"Anjing neraka\" berkeliaran di pedesaan. Mungkin dengan tidur lebih awal, kamu bisa menghindari pandangannya."
  },
  AvgDialog_18991_Content_13 = {
    Text = "Anjing neraka?"
  },
  AvgDialog_18991_Content_14 = {
    Text = [[
Konon, jika seseorang tertangkap oleh pandangannya sebanyak tiga kali, mereka akan jatuh ke dalam Ilusi dan menghadapi kematian. 
 Para tamu sekalian, sebaiknya berhati-hati.]]
  },
  AvgDialog_18991_Content_15 = {
    Text = "Saya pikir ini hanya omong kosong untuk menenangkan anak-anak yang tidak mau tidur."
  },
  AvgDialog_18991_Content_16 = {
    Text = "Entah benar atau salah, siapa yang tahu? Legenda pedesaan memiliki kebenarannya sendiri."
  },
  AvgDialog_18991_Content_17 = {
    Text = "Kamu tampaknya tidak berpikir demikian."
  },
  AvgDialog_18991_Content_18 = {
    Text = "Kebenaran dan kepalsuan selalu berdampingan; apa yang dianggap benar oleh seseorang mungkin dianggap salah oleh orang lain."
  },
  AvgDialog_18991_Content_19 = {
    Text = [[
Lihat aku, lagi-lagi mengatakan hal-hal yang kacau, mohon jangan diambil hati. 
Istirahatlah lebih awal, para tamu yang tercinta.]]
  },
  AvgDialog_18991_Content_2 = {
    Text = "Kalian, dipandu oleh seorang gadis muda, tiba di sebuah toko kecil yang tidak mencolok di sudut jalan."
  },
  AvgDialog_18991_Content_20 = {
    Text = "Setelah selesai berbicara, Dafude'er bangkit dan pergi dengan tenang, hanya meninggalkan bayangan punggungnya yang mengeluarkan aroma samar."
  },
  AvgDialog_18991_Content_21 = {
    Text = "...Apa yang kalian bicarakan sembarangan?"
  },
  AvgDialog_18991_Content_22 = {
    Text = "Saya juga tidak mengerti."
  },
  AvgDialog_18991_Content_23 = {
    Text = [[
Kita sekarang berada dalam sebuah ilusi. 
 Coba lihat dengan kunci perak, kamu akan mengerti apa yang aku maksud.]]
  },
  AvgDialog_18991_Content_25 = {Text = "!"},
  AvgDialog_18991_Content_26 = {
    Text = "Tingkat pelarutan di area ini jauh melampaui logika, namun Dafude'er dan barang-barangnya tetap bersih tanpa cela."
  },
  AvgDialog_18991_Content_27 = {
    Text = "Wanita Narsis (Lady Daffodil), si wanita narsis, sulit dipercaya bahwa itu adalah nama asli."
  },
  AvgDialog_18991_Content_28 = {
    Text = "Jika dia adalah pedagang yang menjual barang terlarang, menggunakan nama palsu juga masuk akal."
  },
  AvgDialog_18991_Content_29 = {
    Text = "Meskipun begitu, tetap terasa aneh."
  },
  AvgDialog_18991_Content_3 = {
    Text = [[
Toko kecil yang diselimuti oleh kabut ungu hanya selebar sepuluh kaki, namun tata letaknya cukup berkelas. 
 Hiasan kecil yang halus dan bergaya kuno bertumpuk secara artistik di atas meja, tampak acak namun tetap teratur.]]
  },
  AvgDialog_18991_Content_30 = {
    Text = "Jika kamu seorang pedagang yang \"berpengalaman\" di kota kecil dengan kasus orang hilang yang sering terjadi, apakah kamu akan dengan mudah mengizinkan tiga orang asing masuk pada tengah malam?"
  },
  AvgDialog_18991_Content_31 = {
    Text = "Lagipula, aku selalu merasa ada sesuatu yang mengamati kita."
  },
  AvgDialog_18991_Content_32 = {
    Text = "Apakah kamu juga merasa bulu kudukmu berdiri?"
  },
  AvgDialog_18991_Content_33 = {
    Text = [[
Jangan menganggap aku seperti dirimu. 
Aku hanya sangat penasaran, siapa gerangan orang yang begitu berani hingga berani menjadikanku sebagai mangsa.]]
  },
  AvgDialog_18991_Content_34 = {
    Text = [[
Setidaknya di sini ada atap untuk melindungi dari hujan. 
 Kita bergiliran beristirahat, tetap waspada, dan sisanya bisa kita bicarakan lagi besok.]]
  },
  AvgDialog_18991_Content_36 = {
    Text = "Ngomong-ngomong, Erica?"
  },
  AvgDialog_18991_Content_37 = {
    Text = "Halo, android Erica siaga 24/7, memberikan dukungan teknis dan informasi paling tepat waktu untukmu."
  },
  AvgDialog_18991_Content_38 = {
    Text = "Kata kunci: \"Wanita narsis\", pedagang antik profesional."
  },
  AvgDialog_18991_Content_39 = {
    Text = "Masukkan kata kunci \"Narsis\", \"Pedagang Antik\", sedang mencari, harap tunggu sebentar. \nHasil pencarian: tidak ditemukan. Maaf sekali, silakan coba lagi dengan mengganti kata kunci…"
  },
  AvgDialog_18991_Content_4 = {
    Text = "Ck, katanya toko \"Nyonya Narsis\", ternyata hanya sebuah toko eceran kecil di pinggir jalan."
  },
  AvgDialog_18991_Content_41 = {
    Text = "Malam semakin pekat, disertai dengan suara percakapan antara Ramona dan Erica, kamu perlahan tenggelam ke dalam mimpi…"
  },
  AvgDialog_18991_Content_43 = {
    Text = "...Jangan berdebat dengannya. Setelah kejadian itu, ada yang mengatakan bahwa dia sudah gila."
  },
  AvgDialog_18991_Content_44 = {
    Text = "Dia menemui dokter dan mengklaim bahwa dia bisa melihat \"<Yellow:lubang di tubuh manusia>\"…\nDia juga berkata bahwa lubang itu telah membunuh suaminya dan putrinya."
  },
  AvgDialog_18991_Content_45 = {
    Text = "Bukankah dia selalu lajang? Lalu, dari mana dia mendapatkan suami dan anak perempuan?"
  },
  AvgDialog_18991_Content_46 = {
    Text = "Ya, bukankah ini seperti kehilangan akal sehat?"
  },
  AvgDialog_18991_Content_47 = {
    Text = "Jika begitu, bisakah kita meminta penilaian terhadap kondisi Roh-nya?"
  },
  AvgDialog_18991_Content_48 = {
    Text = "Masih perlu dievaluasi? Orang biasa yang hidup dengan baik-baik saja, apakah akan secara sukarela mengajukan diri untuk mati?"
  },
  AvgDialog_18991_Content_49 = {
    Text = "Dan para pecinta petualangan yang fanatik itu, sepertinya Roh mereka juga tidak terlalu normal. Jika benar-benar dilakukan pemeriksaan Roh, saya ragu ada yang bisa lulus."
  },
  AvgDialog_18991_Content_5 = {
    Text = "Dan lagi, barang-barang antik ini...? Bentuknya aneh, sangat terdistorsi."
  },
  AvgDialog_18991_Content_50 = {
    Text = "Cairan kental berwarna hitam mengalir turun dari langit, menutupi pandangan."
  },
  AvgDialog_18991_Content_51 = {
    Text = "Menutupi tangga <Blue:Yayasan>, gerbang Yayasan, dan konter Yayasan."
  },
  AvgDialog_18991_Content_52 = {
    Text = "Hingga ke wajah para staf yayasan."
  },
  AvgDialog_18991_Content_53 = {
    Text = "Saya memperingatkan kalian, saya memiliki hak untuk menuntut kalian atas dasar pencemaran nama baik di pengadilan."
  },
  AvgDialog_18991_Content_54 = {
    Text = [[
Lendir hitam ini... meskipun kalian tidak bisa melihatnya, mereka tetap ada. 
 Mereka itulah yang telah mengambil...]]
  },
  AvgDialog_18991_Content_55 = {
    Text = "Mengambil... orang yang paling dekat denganku..."
  },
  AvgDialog_18991_Content_56 = {
    Text = "Kenapa? Kenapa mereka semua tidak bisa melihat?"
  },
  AvgDialog_18991_Content_57 = {
    Text = "Sakit, tapi @2 bisa menahan rasa sakitnya, Bu."
  },
  AvgDialog_18991_Content_58 = {
    Text = [[
Tidak, tidak bisa. Jangan seperti ini, kau akan menghilang. 
Aku sudah kehilangan @3, aku tak bisa kehilanganmu lagi.]]
  },
  AvgDialog_18991_Content_59 = {
    Text = "Aku tidak akan meninggalkan Ibu."
  },
  AvgDialog_18991_Content_6 = {
    Text = "Saya sangat menghargai koleksi-koleksi ini. Bukankah menurut Anda ada keindahan yang terbentuk dari waktu pada mereka?"
  },
  AvgDialog_18991_Content_60 = {
    Text = "Kenapa? Bukankah kamu berkata tidak akan meninggalkanku?"
  },
  AvgDialog_18991_Content_61 = {
    Text = "Betul, kamu juga tidak bisa melihatnya."
  },
  AvgDialog_18991_Content_62 = {
    Text = "Tapi aku bisa melihat, aku bisa melihat!"
  },
  AvgDialog_18991_Content_63 = {
    Text = [[
Mereka tidak hilang, mereka sakit, mereka sedang larut... 
 Cairan hitam itu sedang melarutkan mereka...]]
  },
  AvgDialog_18991_Content_64 = {
    Text = [[
Wanita itu berbisik pelan dan terlelap. Kabut di sekitarnya perlahan menyebar dengan lembut, secara bertahap menyelimuti dirinya. 
 Di tengah kabut tebal, muncul bayangan kelam berwarna ungu tua.]]
  },
  AvgDialog_18991_Content_65 = {
    Text = "Awalnya, saya hanya ingin memeriksa apakah sudah waktunya untuk panen... Tidak disangka, perkembangan situasi menjadi begitu menarik."
  },
  AvgDialog_18991_Content_66 = {
    Text = "Lupakan saja, simpan kepala ini untuk sementara waktu."
  },
  AvgDialog_18991_Content_67 = {
    Text = "Setelah kamu kembali dari tempat yang membeku dan sangat dingin itu, kamu harus memberikannya padaku dengan baik-baik, oke?"
  },
  AvgDialog_18991_Content_7 = {
    Text = "Suara yang menyeramkan mengalir keluar dari bayangan gelap, seperti nada rendah yang sangat dalam menyatu dengan simfoni yang kacau."
  },
  AvgDialog_18991_Content_8 = {
    Text = "Maaf, izinkan saya memperkenalkan diri. Saya adalah pemilik toko kecil ini, Narsis."
  },
  AvgDialog_18991_Content_9 = {
    Text = [[
Saya tidak bermaksud mengganggu percakapan para tamu. 
Saya hanya ingin mengingatkan semua orang bahwa malam sudah larut, saatnya untuk beristirahat.]]
  },
  AvgDialog_18992_Content_1 = {
    Text = "Hidup tanpa teman"
  },
  AvgDialog_18992_Content_10 = {
    Text = "Helot bergumam, dengan mulut sedikit terbuka dan mengucapkan mantra penghinaan yang nadanya kaku serta kuno, sulit dimengerti."
  },
  AvgDialog_18992_Content_12 = {
    Text = "Apa suara ini! Sial, kepala terasa sangat sakit…"
  },
  AvgDialog_18992_Content_13 = {
    Text = [[
Kamu belum pernah mendengar bahasa ini sebelumnya, tetapi entah bagaimana kamu bisa memahami maknanya. 
 Bisikan tanpa henti menyusup ke dalam korteks otak, dengan nada aneh yang bergema seperti mimpi buruk.]]
  },
  AvgDialog_18992_Content_14 = {
    Text = "<Change>Kembali ke sarang semula"
  },
  AvgDialog_18992_Content_15 = {
    Text = "<Change>Kembali ke dunia yang kekal"
  },
  AvgDialog_18992_Content_16 = {
    Text = "<Change>Kembali ke pelukan Ibu"
  },
  AvgDialog_18992_Content_17 = {
    Text = "Kamu mengerti, namun tidak memahami."
  },
  AvgDialog_18992_Content_18 = {
    Text = "Kamu merasakan suhu yang menempel di sisi tubuhmu menghilang, ujung baju yang semula tergenggam jatuh, dan sosok kurus dalam pandangan kabur berubah menjadi gumpalan cahaya kecil."
  },
  AvgDialog_18992_Content_19 = {
    Text = "Ibu... Ibu..."
  },
  AvgDialog_18992_Content_2 = {
    Text = "Huh, huh——"
  },
  AvgDialog_18992_Content_20 = {
    Text = "Lily, jangan dengarkan!"
  },
  AvgDialog_18992_Content_21 = {
    Text = "Jangan, jangan…"
  },
  AvgDialog_18992_Content_22 = {
    Text = "Kak Lisa datang untuk bermain dengan saya, bukankah Ibu akan memarahi kami?"
  },
  AvgDialog_18992_Content_23 = {
    Text = [[
Hehe, asalkan dia tidak tahu saja. 
Kamu akan membantu aku merahasiakannya, kan?]]
  },
  AvgDialog_18992_Content_24 = {
    Text = "Hmm, Lily tidak akan memberitahu orang lain."
  },
  AvgDialog_18992_Content_25 = {
    Text = "Kalau begitu, tidak ada masalah. Ini rahasia kita, ya?"
  },
  AvgDialog_18992_Content_26 = {
    Text = "Akhirnya, aku menemukanmu."
  },
  AvgDialog_18992_Content_27 = {
    Text = [[
Kamu adalah...?
Aku belum pernah melihatmu. Apakah kamu bukan orang lokal?]]
  },
  AvgDialog_18992_Content_28 = {
    Text = [[
Bukan kamu yang aku cari, aku mencarinya. 
Lily, apakah kamu masih mengenalku? Paman adalah teman lama ibumu.]]
  },
  AvgDialog_18992_Content_29 = {
    Text = "Dulu, saat kita bekerja sama, dia sering membawamu ke institut untuk bermain. Sudah bertahun-tahun, kamu benar-benar tidak berubah sama sekali."
  },
  AvgDialog_18992_Content_3 = {
    Text = "Kamu bukan lawanku."
  },
  AvgDialog_18992_Content_30 = {
    Text = [[
Apakah kamu sudah meninggalkan ibu untuk sementara waktu? 
Paman datang untuk menjemputmu pulang.]]
  },
  AvgDialog_18992_Content_31 = {
    Text = [[
Lily tidak bisa pergi bersamamu.
Hari ini dia diam-diam keluar untuk menemaniku bermain, aku harus mengantarnya ke Wanita Narsis terlebih dahulu.]]
  },
  AvgDialog_18992_Content_32 = {
    Text = "Mama Lily berulang kali mengingatkan dan meminta saya untuk segera membawa Lily kembali."
  },
  AvgDialog_18992_Content_33 = {
    Text = "Wanita Narsis pada akhirnya hanyalah orang yang tinggal sementara, jadi tolong kamu, anak kecil, pergi dan sampaikan salam saja sudah cukup, kan?"
  },
  AvgDialog_18992_Content_34 = {
    Text = "Tidak, jika Nyonya Narsis memarahiku, aku tidak tahu harus bagaimana."
  },
  AvgDialog_18992_Content_35 = {
    Text = "Tetapi Lily harus segera pergi bersamaku sekarang."
  },
  AvgDialog_18992_Content_36 = {
    Text = "Herbert langsung meraih lengan ramping Lily, namun Lisa maju dan menghalanginya."
  },
  AvgDialog_18992_Content_37 = {
    Text = "Lily, cepat lari!"
  },
  AvgDialog_18992_Content_38 = {
    Text = [[
Pemandangan di belakang terus tertinggal. 
 Hanya terdengar teriakan putus asa Lisa.]]
  },
  AvgDialog_18992_Content_39 = {
    Text = "Lari, jangan menoleh, cari Nyonya Narsis!"
  },
  AvgDialog_18992_Content_4 = {
    Text = "Mangsa di hutan yang mengandalkan kegesitannya dan berani menantang laras senjata Pemburu akan menghadapi akhir seperti ini."
  },
  AvgDialog_18992_Content_41 = {
    Text = "Hmph, orang yang merepotkan..."
  },
  AvgDialog_18992_Content_42 = {
    Text = "Massa gelombang hitam kehijauan berkumpul menjadi gelembung protoplasma raksasa, dengan cahaya aneh berkilauan di atas gelembung bernanah tersebut."
  },
  AvgDialog_18992_Content_43 = {
    Text = "Di sudut mata Lily, air mata berwarna hitam meluncur ke bawah."
  },
  AvgDialog_18992_Content_46 = {
    Text = [[
Nada yang akrab, membentang menjadi intonasi yang asing. 
Suara seperti ini tidak seharusnya dimiliki oleh seorang anak.]]
  },
  AvgDialog_18992_Content_48 = {Text = "%player%!"},
  AvgDialog_18992_Content_49 = {
    Text = "Jangan memberikan kerusakan pada Lily"
  },
  AvgDialog_18992_Content_5 = {
    Text = "Keunggulanku terhadapmu — adalah luar biasa."
  },
  AvgDialog_18992_Content_50 = {
    Text = "Utamakan melindungi dirimu sendiri"
  },
  AvgDialog_18992_Content_51 = {Text = "Mengerti!"},
  AvgDialog_18992_Content_52 = {
    Text = "Tidak perlu kau ingatkan, sedikit sakit kepala ini sama sekali tidak memengaruhi kemampuanku!"
  },
  AvgDialog_18992_Content_6 = {
    Text = "Helot menundukkan kepalanya, membiarkan Lotan mencemoohnya sesuka hati, tetap tidak bergerak sedikit pun."
  },
  AvgDialog_18992_Content_7 = {Text = "!"},
  AvgDialog_18992_Content_8 = {
    Text = "Bagaimana——"
  },
  AvgDialog_18992_Content_9 = {
    Text = "Tiba-tiba, air pasang berwarna hitam kehijauan yang tak bernama memenuhi sekeliling, dan suara jeritan tajam kuno yang mengerikan bergema di dalam pikiran."
  },
  AvgDialog_18994_Content_1 = {
    Text = "Perdagangan yang adil"
  },
  AvgDialog_18994_Content_10 = {
    Text = "Narsis mengeluarkan dua <Blue:arsip> dari kehampaan abu-abu, dan dengan lembut menepuk debu di permukaannya."
  },
  AvgDialog_18994_Content_11 = {
    Text = [[
Setelah debu dari Acara itu mereda, saya akan mengirimkannya ke markas besar kedua. 
 Dan satu-satunya syarat saya adalah kalian berdua berpisah di sini dan melanjutkan jalan masing-masing.]]
  },
  AvgDialog_18994_Content_12 = {
    Text = "Mungkin suatu hari nanti, jalan-jalan akan bertemu lagi di depan, tetapi itu hanya bisa diserahkan kepada takdir yang \"diamati oleh-Nya\"."
  },
  AvgDialog_18994_Content_13 = {
    Text = "Dokumen itu..."
  },
  AvgDialog_18994_Content_14 = {
    Text = "Dan itu ada hubungannya dengan \"Anjing Neraka\". Apakah kamu benar-benar berpikir aku pergi ke Rai untuk berbisnis barang antik?"
  },
  AvgDialog_18994_Content_15 = {
    Text = "Saya perlu memastikan nilai dari dokumen ini."
  },
  AvgDialog_18994_Content_16 = {
    Text = "Ramona, bagaimana menurutmu?"
  },
  AvgDialog_18994_Content_17 = {
    Text = "Kami sebenarnya adalah pihak yang diserang, jadi gencatan senjata tidak akan merugikan kami."
  },
  AvgDialog_18994_Content_18 = {
    Text = [[
Namun, saya perlu memastikan nilai dari arsip ini. 
 Bolehkah saya meminta izin untuk membaca halaman pertamanya?]]
  },
  AvgDialog_18994_Content_19 = {
    Text = "Tentu saja."
  },
  AvgDialog_18994_Content_2 = {
    Text = "Bisikan menghilang, meninggalkan keheningan yang tak berujung di dalam gerbong."
  },
  AvgDialog_18994_Content_20 = {
    Text = "Ramona mengambil dokumen dari Dafdeil, pandangannya di balik lensa bergerak cepat. Setelah membaca beberapa baris, dia mengangguk padamu."
  },
  AvgDialog_18994_Content_21 = {
    Text = "Terjadi kesepakatan."
  },
  AvgDialog_18994_Content_22 = {
    Text = [[
Saya sangat menghargai tamu yang tegas seperti Anda. 
Dokumen akan dikirimkan ke ruang penerimaan Universitas Mythag dalam tujuh hari.]]
  },
  AvgDialog_18994_Content_23 = {
    Text = "Apakah wanita di sini sudah membuat keputusan?"
  },
  AvgDialog_18994_Content_24 = {
    Text = "Helot menggerakkan lehernya, lendir di telapak tangannya membentuk duri."
  },
  AvgDialog_18994_Content_25 = {
    Text = "Saya menolak. Saya harus menyelesaikan tugas."
  },
  AvgDialog_18994_Content_26 = {
    Text = [[
Kamu akan mempertimbangkannya kembali. 
Ini adalah data tentang "<Yellow:kejadian itu>" sepuluh tahun yang lalu.]]
  },
  AvgDialog_18994_Content_27 = {
    Text = [[
Narsis mengeluarkan sebuah lambang, meletakkannya di telapak tangannya, dan menunjukkannya kepada Helot. 
 Begitu melihat lambang tersebut, ekspresi wajah Helot berubah secara drastis.]]
  },
  AvgDialog_18994_Content_28 = {
    Text = "Dari mana kamu ——"
  },
  AvgDialog_18994_Content_29 = {
    Text = "Ssst——\nSebelum kamu berjanji untuk melakukan transaksi, aku tidak akan memberitahumu apa pun."
  },
  AvgDialog_18994_Content_3 = {
    Text = "Lotan melompat ke depan dan menangkap Lily yang terjatuh."
  },
  AvgDialog_18994_Content_30 = {
    Text = "Helot mengerutkan alis, membuka mulut seolah ingin mengatakan sesuatu, namun akhirnya tidak mengucapkan sepatah kata pun dan kembali ke dalam Bayangan."
  },
  AvgDialog_18994_Content_31 = {
    Text = "Dengan suara mendengus, Helot mengarahkan ujung duri ke tanah dan dengan kuat menggoreskan sebuah garis dalam. Gesekan antara duri dan tanah menghasilkan percikan api kecil."
  },
  AvgDialog_18994_Content_32 = {
    Text = "Saya juga setuju. Namun——"
  },
  AvgDialog_18994_Content_33 = {
    Text = "Dia mengangkat tangannya dan menunjuk ke arsip di pelukan Narsis dengan ujung tombak."
  },
  AvgDialog_18994_Content_34 = {
    Text = "Kamu harus menyerahkan dokumen itu kepadaku sekarang."
  },
  AvgDialog_18994_Content_35 = {
    Text = "Begitu tidak sabar? Sayang sekali, harga sudah ditetapkan. Di toko penawar duka Narsis, tidak ada ruang untuk tawar-menawar."
  },
  AvgDialog_18994_Content_36 = {
    Text = "Narsis memanggil kabut kelabu, meletakkan dokumen di atasnya, dan dokumen itu hampir dilahap oleh kabut kelabu."
  },
  AvgDialog_18994_Content_37 = {
    Text = "Dalam sekejap, Helot seperti bayangan kilat menyerbu Daffdell."
  },
  AvgDialog_18994_Content_39 = {
    Text = [[
Namun, sosok berwarna ungu itu menghilang begitu dia mendekat. 
 Daffdell muncul dengan tenang di belakang Helot, tangannya masih memegang erat dokumen tersebut.]]
  },
  AvgDialog_18994_Content_4 = {
    Text = [[
Plak, plak, plak. 
 Di dalam terowongan yang gelap, tiba-tiba terdengar suara tepukan tangan yang jelas dan tajam.]]
  },
  AvgDialog_18994_Content_40 = {
    Text = "Tidak ada gunanya terburu-buru, nak. \nBaiklah, aku tidak akan mengganggu lebih lama. Sekali lagi, selamat menikmati perjalanan kalian——."
  },
  AvgDialog_18994_Content_41 = {
    Text = [[
Kabut abu-abu menyebar.
Puluhan detik kemudian, segalanya kembali sunyi, dan sosok Dafudeer sudah tidak terlihat.]]
  },
  AvgDialog_18994_Content_43 = {
    Text = "Helot mendengus dingin, lalu berkelebat dan menghilang ke dalam kegelapan."
  },
  AvgDialog_18994_Content_44 = {
    Text = "Ramona, lalu kita...?"
  },
  AvgDialog_18994_Content_45 = {
    Text = "...Lotan, tolong jaga Lily sampai kami kembali."
  },
  AvgDialog_18994_Content_46 = {
    Text = "Sebelumnya sudah kubilang, aku tidak terlalu pandai mengurus anak."
  },
  AvgDialog_18994_Content_47 = {
    Text = "Penjaga, apakah kamu percaya padaku?"
  },
  AvgDialog_18994_Content_48 = {Text = "Tentu."},
  AvgDialog_18994_Content_49 = {
    Text = [[
Kalau begitu, silakan tutup mata Anda sejenak. 
Kita akan pergi ke suatu tempat.]]
  },
  AvgDialog_18994_Content_5 = {
    Text = "Diiringi dengan tepuk tangan yang ritmis, ada suara wanita ambigu dengan senyuman yang sedikit mengagumi. Pakaian berwarna abu-abu yang dipenuhi kabut perlahan-lahan menggambar garis dari batas cahaya, sekelilingnya seketika diselimuti aroma violet yang lembut."
  },
  AvgDialog_18994_Content_50 = {
    Text = [[
Kamu menutup mata sesuai dengan permintaannya. 
 Dalam kegelapan, kamu merasakan tangan Ramona yang sedikit dingin menggenggam tanganmu, perlahan-lahan berjalan menuju arah tertentu.]]
  },
  AvgDialog_18994_Content_6 = {
    Text = "Terima kasih atas penampilan luar biasa dari kalian semua. Saya melihat bahwa semua orang sudah sangat lelah. Bagaimana kalau kita berhenti sementara untuk beristirahat?"
  },
  AvgDialog_18994_Content_7 = {
    Text = "Apa maksudmu, \"tidak berkelahi jika tidak mau\"? Mengapa kita harus mengikuti perintahmu?"
  },
  AvgDialog_18994_Content_8 = {
    Text = [[
Toko Kecil Penghilang Kekhawatiran tidak pernah mengecewakan para tamunya. 
 Saya datang untuk membicarakan sebuah transaksi dengan kalian semua.]]
  },
  AvgDialog_18994_Content_9 = {
    Text = "Saya punya dua dokumen di sini, masing-masing berisi informasi yang ingin kalian ketahui."
  },
  AvgDialog_18995_Content_1 = {
    Text = "Bisul-bisul ini... aku memiliki firasat buruk tentangnya."
  },
  AvgDialog_18995_Content_2 = {Text = "Apa?"},
  AvgDialog_18995_Content_3 = {
    Text = "Mungkin aku terlalu khawatir. Mari kita kejar Lotan terlebih dahulu."
  },
  AvgDialog_18996_Content_1 = {
    Text = "Kemari, setan sialan!"
  },
  AvgDialog_18996_Content_2 = {
    Text = "Kakak besar di sana, apakah kamu bisa mengejar aku?"
  },
  AvgDialog_18996_Content_3 = {
    Text = "...Sesaat aku bahkan tidak tahu apakah yang melakukan intimidasi itu aku atau mereka."
  },
  AvgDialog_18997_Content_1 = {
    Text = "Pikirkan dengan matang sebelum bertindak"
  },
  AvgDialog_18997_Content_10 = {
    Text = [[
William dengan hati-hati mengeluarkan beberapa foto dari arsip. 
 Di tengah foto, segitiga hitam yang aneh perlahan-lahan mengeluarkan kabut hitam.]]
  },
  AvgDialog_18997_Content_11 = {
    Text = "<Yellow:Pelarutan parah>."
  },
  AvgDialog_18997_Content_12 = {
    Text = "Laporan orang hilang diterima oleh polisi dua minggu lalu."
  },
  AvgDialog_18997_Content_13 = {
    Text = "<Yellow:Kecepatan penyebarannya sangat cepat>, cepat secara abnormal."
  },
  AvgDialog_18997_Content_14 = {
    Text = "Di kota juga muncul banyak pasien histeris, dan polisi telah memberikan laporan penampakan \"<Blue:Anjing neraka Kerberos>\"."
  },
  AvgDialog_18997_Content_15 = {
    Text = "Apakah kamu curiga bahwa \"Anjing neraka\" adalah <Yellow:Clades> di area ini?"
  },
  AvgDialog_18997_Content_16 = {
    Text = "Benar. Mengingat legenda setempat tentang \"Anjing neraka\" sudah ada sejak lama, kemungkinan besar itu baru saja bangun dari \"Negara tidur\" sebagai <Yellow:Clades kuno>."
  },
  AvgDialog_18997_Content_17 = {
    Text = "Kali ini, kita mungkin harus menghadapi pertempuran sengit. Saya ingin meminta \"orang itu\" untuk menemani Penjaga."
  },
  AvgDialog_18997_Content_18 = {
    Text = "Orang gila yang hanya memikirkan pertempuran di otaknya itu... Setelah perubahan aneh di Kolam Hitam, dia terus berjaga di sana dan melalaikan tugas mengajar."
  },
  AvgDialog_18997_Content_19 = {
    Text = "Mungkin hanya Penjaga yang bisa secara pribadi mengundangnya, agar dia bersedia berpindah tempat."
  },
  AvgDialog_18997_Content_2 = {
    Text = "Universitas Mythag Kantor Departemen Bangun"
  },
  AvgDialog_18997_Content_20 = {
    Text = "{Male=Dia,Female=Dia} sudah pergi."
  },
  AvgDialog_18997_Content_21 = {
    Text = [[
Lotan duduk di sudut terjauh Kolam Hitam, mendongak menatap langit yang kosong. 
Itu adalah tempat Tawil pernah muncul.]]
  },
  AvgDialog_18997_Content_22 = {
    Text = "Kau berkata, apakah Dia akan bangun kembali?"
  },
  AvgDialog_18997_Content_23 = {
    Text = "Kamu juga akan menghadapi lawan lainnya."
  },
  AvgDialog_18997_Content_24 = {
    Text = "——Contohnya, Anjing neraka."
  },
  AvgDialog_18997_Content_25 = {
    Text = "Desis—\n\"Anjing neraka\"? Apakah ini fantasi vulgar yang diciptakan oleh manusia biasa yang takut mati?"
  },
  AvgDialog_18997_Content_26 = {
    Text = "Kami membutuhkan kekuatanmu."
  },
  AvgDialog_18997_Content_27 = {
    Text = [[
Tapi aku hanya butuh orang itu di dalam kolam. 
 Bangunkan Dia, lalu bertarunglah denganku lagi.]]
  },
  AvgDialog_18997_Content_28 = {
    Text = "Tidak ada yang tahu berapa lama lagi Ia akan terus tertidur."
  },
  AvgDialog_18997_Content_29 = {
    Text = "Saya telah ada di Planet ini sejak awal penciptaan, tidak ada yang lebih sabar daripada saya."
  },
  AvgDialog_18997_Content_3 = {
    Text = [[
Legenda <Blue:Kerberos> dapat ditelusuri kembali ke Yunani Kuno pada abad ke-8 SM. 
Pada masa itu, para penyair menggambarkannya seperti ini:]]
  },
  AvgDialog_18997_Content_30 = {
    Text = "Dan... siapa yang tahu berapa lama lagi Dia akan terus tidur?"
  },
  AvgDialog_18997_Content_31 = {
    Text = "Kamu salah."
  },
  AvgDialog_18997_Content_32 = {
    Text = "Selama ada kamu sebagai satu-satunya variabel, kebangkitannya hanyalah masalah waktu, bukan?"
  },
  AvgDialog_18997_Content_34 = {
    Text = [[
Jangan terlalu tegang, aku hanya bercanda denganmu. 
 Tentu saja aku bisa pergi, tapi kamu harus membuat perjanjian tiga poin denganku.]]
  },
  AvgDialog_18997_Content_35 = {
    Text = "Kamu berkata."
  },
  AvgDialog_18997_Content_36 = {
    Text = "Pertama, aku hanya bertanggung jawab atas pertempuran, jangan cari aku untuk urusan lain yang merepotkan."
  },
  AvgDialog_18997_Content_37 = {
    Text = "Kedua, jangan ikut campur dalam tindakan independen saya."
  },
  AvgDialog_18997_Content_38 = {
    Text = "Ketiga, lawan yang saya pilih harus memberi saya kesempatan untuk berduel dengannya."
  },
  AvgDialog_18997_Content_39 = {
    Text = "Lalu dia langsung setuju untuk ikut?"
  },
  AvgDialog_18997_Content_4 = {
    Text = "Ekhidna sebagai ibu, Tifon sebagai ayah, kepalanya ada tiga, <Yellow: bagi mereka yang telah diburu tiga kali olehnya, jiwanya pasti akan masuk ke dunia bawah>."
  },
  AvgDialog_18997_Content_40 = {
    Text = "Dengan tubuh manusia biasa seperti saya, mana mungkin saya bisa memaksanya datang dengan cara mengikatnya, kan?"
  },
  AvgDialog_18997_Content_41 = {
    Text = "Dia cukup tahu bagaimana menikmati hidup dengan apa adanya."
  },
  AvgDialog_18997_Content_42 = {
    Text = "Makhluk yang telah hidup selama ratusan juta tahun — bukan, makhluk hidup, tidak tahu berapa kali telah mengalami perubahan, memang sangat mahir dalam beradaptasi dengan perubahan lingkungan."
  },
  AvgDialog_18997_Content_43 = {
    Text = "Semoga penyelidikan juga bisa berjalan semulus ini."
  },
  AvgDialog_18997_Content_44 = {
    Text = "Data terkait dan memori telah mengalami pelarutan, baik bukti manusia maupun bukti fisik hilang…"
  },
  AvgDialog_18997_Content_45 = {
    Text = "Jangan bicara yang menyurutkan semangat. Jika Lotan pergi begitu saja……\nMungkin ke depannya dia hanya bisa ditemukan di Kolam Hitam."
  },
  AvgDialog_18997_Content_46 = {
    Text = "Ngomong-ngomong, apakah sudah lama tidak melihat Lotan?"
  },
  AvgDialog_18997_Content_5 = {
    Text = "Hmm, tulisannya cukup meyakinkan, bahkan mencantumkan beberapa kasus penampakan pada tahun A.F.187."
  },
  AvgDialog_18997_Content_6 = {
    Text = "Jangan sebutkan kasus-kasus penampakan itu. Kutipan literatur entah sumbernya tidak jelas, atau memang tidak ada sama sekali."
  },
  AvgDialog_18997_Content_7 = {
    Text = "Bahkan deskripsi yang dikaitkan dengan penyair Yunani kuno sangat berbeda dari hasil penelitian literatur saat ini."
  },
  AvgDialog_18997_Content_8 = {
    Text = "Jika kamu hanya berencana mengirim Penjaga untuk tugas lapangan berdasarkan beberapa halaman karangan, William, aku harus mempertanyakan sikap kerja tim Penyelidikan."
  },
  AvgDialog_18997_Content_9 = {
    Text = "Bukan karena saya tidak mau memberikan informasi di tempat, hanya saja..."
  },
  AvgDialog_18998_Content_1 = {
    Text = "Jangan memperbaiki apa yang tidak rusak"
  },
  AvgDialog_18998_Content_10 = {
    Text = "Aku bukan tidak mau menerima suara dari luar, hanya saja... pemikiran %hisorher% terlalu penting."
  },
  AvgDialog_18998_Content_11 = {
    Text = "Menambahkan beban berat di bagian haluan atau buritan perahu kecil yang hanya bisa bergerak dengan stabil bukanlah tindakan yang bijaksana."
  },
  AvgDialog_18998_Content_12 = {
    Text = [[
...Bagaimana Lotan memandangnya?
Tentang menjadi Pembangun.]]
  },
  AvgDialog_18998_Content_13 = {Text = "Aku?"},
  AvgDialog_18998_Content_14 = {
    Text = "...bagaimana, ya."
  },
  AvgDialog_18998_Content_15 = {
    Text = [[
Ketika planet tercipta, aku terbangun di dalam pelukan bumi, dan sekitarku dipenuhi oleh kekacauan.
Dibandingkan dengan luasnya alam semesta, bahkan Paus Pusaran pun tampak begitu tidak berarti.]]
  },
  AvgDialog_18998_Content_16 = {
    Text = [[
Menjadi Pembangun juga memberikan perasaan yang sama. 
 Ketika dibangunkan, roh dan kehendak tidak sepenuhnya utuh, hingga setelah terhubung dengan Perak barulah kondisi tersebut berangsur stabil.]]
  },
  AvgDialog_18998_Content_17 = {
    Text = "Saya tidak tahu perasaan para Pembangun yang dulunya adalah manusia, tetapi bagi saya, rasanya seperti memaksa raksasa besar terikat pada tubuh yang rapuh dan tidak berdaya."
  },
  AvgDialog_18998_Content_18 = {
    Text = "Kekuatan perlahan-lahan pulih, kan?"
  },
  AvgDialog_18998_Content_19 = {
    Text = "Ya. Aku adalah produk awal dari Mythag yang dibangunkan, kondisi Negara tidak sepenuhnya, dan telah melalui siklus yang jauh lebih panjang daripada yang lain."
  },
  AvgDialog_18998_Content_2 = {
    Text = "{Male=Dia,Female=Dia} tidur?"
  },
  AvgDialog_18998_Content_20 = {
    Text = "Namun, saya segera menemukan kembali diri saya, menemukan kembali apa yang ingin saya lakukan — saya menginginkan lawan yang membuat darah saya berdesir."
  },
  AvgDialog_18998_Content_21 = {
    Text = [[
Tidur dan bangun seperti ini, sudah terjadi berkali-kali dalam miliaran tahun. 
Aku sudah sangat terbiasa.]]
  },
  AvgDialog_18998_Content_22 = {
    Text = [[
Namun, dalam hampir tak terbatasnya waktu, aku sampai pada sebuah kesimpulan. 
Segala sesuatu di luar mencari lawan adalah tanpa arti.]]
  },
  AvgDialog_18998_Content_23 = {
    Text = [[
Bentuk kehidupan tidak dapat diubah, daripada terus memikirkan hal ini, lebih baik menemukan makna hidup sebagai Pembangun. 
 Bentuk mungkin diciptakan oleh Perak, tetapi apa yang ingin kulakukan adalah keputusanku sendiri.]]
  },
  AvgDialog_18998_Content_24 = {
    Text = "Ini adalah jawabanmu."
  },
  AvgDialog_18998_Content_25 = {
    Text = "Kamu juga akan menemukan jawabanmu, Nak."
  },
  AvgDialog_18998_Content_26 = {
    Text = "Saya sangat menantikan hari ketika kamu tumbuh hingga mencapai tahap itu."
  },
  AvgDialog_18998_Content_27 = {
    Text = "Semoga Kunci Perak menuntun jalanmu."
  },
  AvgDialog_18998_Content_28 = {
    Text = "Mengatakannya terasa agak canggung, tapi apa boleh buat…\nSemoga Kunci Perak membimbing kita."
  },
  AvgDialog_18998_Content_29 = {Text = "Mimpi"},
  AvgDialog_18998_Content_3 = {
    Text = [[
Begitu menyentuh bantal langsung tertidur.
Beberapa hari ini %hisorher% kekuatan roh sangat terkuras.]]
  },
  AvgDialog_18998_Content_31 = {Text = "Penjara."},
  AvgDialog_18998_Content_32 = {
    Text = "Tak terhitung berapa banyak kandang penjara."
  },
  AvgDialog_18998_Content_33 = {
    Text = [[
Sepertinya ini adalah sebuah gua.
Tubuh tidak lagi dingin, tetapi hati lebih dingin daripada lapisan es yang membeku di kutub.]]
  },
  AvgDialog_18998_Content_34 = {
    Text = "...Bertrand...Letnan Kolonel."
  },
  AvgDialog_18998_Content_35 = {
    Text = "Kamu menyadari bahwa suaramu sangat serak."
  },
  AvgDialog_18998_Content_36 = {
    Text = "Gadis di samping api unggun tampaknya menyadari gerakanmu, namun hanya melirikmu dengan tatapan angkuh tanpa mengucapkan sepatah kata pun."
  },
  AvgDialog_18998_Content_37 = {
    Text = "Ini adalah... di mana?"
  },
  AvgDialog_18998_Content_38 = {
    Text = "Gadis itu tidak menjawab."
  },
  AvgDialog_18998_Content_39 = {
    Text = "Kesadaranmu perlahan kembali, dan pandanganmu tertuju pada tanda yang terukir di sisi gua."
  },
  AvgDialog_18998_Content_4 = {
    Text = "Kami sudah memasuki area Rumah Sakit Lai, mungkin setelah ini tidak akan ada waktu untuk beristirahat."
  },
  AvgDialog_18998_Content_40 = {
    Text = "... dengan tanda pada peta Cecili sepenuhnya sesuai."
  },
  AvgDialog_18998_Content_41 = {
    Text = [[
Apakah ini ... @3Gereja? 
 Aku tahu tentang kalian, kalian bisa menghidupkan orang mati, kan?]]
  },
  AvgDialog_18998_Content_42 = {
    Text = [[
Gadis itu melirikmu sekali lagi dengan tatapan jijik. 
Sepertinya karena merasa kamu terlalu berisik, dia bangkit dan berjalan menuju luar gua, masih bergumam pelan.]]
  },
  AvgDialog_18998_Content_43 = {
    Text = "<Small:Bodoh.>"
  },
  AvgDialog_18998_Content_47 = {
    Text = [[
Setelah beberapa saat, gadis itu kembali. 
Di tangannya terdapat sebuah pahat dan sepotong kayu.]]
  },
  AvgDialog_18998_Content_48 = {
    Text = "Dia duduk di samping api unggun, lalu mulai mengukir."
  },
  AvgDialog_18998_Content_49 = {
    Text = "Kamu memperhatikan bahwa jarinya dibalut penuh dengan perban."
  },
  AvgDialog_18998_Content_5 = {
    Text = [[
Kamu juga seharusnya tidur sebentar. 
 Bagaimanapun, kamu tetap manusia biasa.]]
  },
  AvgDialog_18998_Content_50 = {
    Text = "……Pisau ukirmu terlalu tumpul, ini bisa sangat mudah melukai tanganmu.\nSelain itu, untuk memotong kayu dalam ukuran besar, tidak cocok menggunakan pisau kecil seperti ini."
  },
  AvgDialog_18998_Content_52 = {
    Text = "...aku hanya punya pisau ini."
  },
  AvgDialog_18998_Content_53 = {
    Text = "Ada beberapa alat pemotong di tas saya, bisakah kamu membantu mengambilnya?"
  },
  AvgDialog_18998_Content_56 = {
    Text = "Satu atau dua jam berlalu, gadis itu masih sepenuhnya berkonsentrasi pada ukirannya."
  },
  AvgDialog_18998_Content_57 = {
    Text = "Apa nama kamu?"
  },
  AvgDialog_18998_Content_58 = {
    Text = "<Blue:Murphy>."
  },
  AvgDialog_18998_Content_59 = {
    Text = "Saya memiliki seorang putri. Jika dia masih hidup, usianya sekarang mungkin hampir sama denganmu."
  },
  AvgDialog_18998_Content_60 = {
    Text = "Tetapi dia meninggal karena penyakit hitam, dan tidak ada yang mempercayai perkataanku…"
  },
  AvgDialog_18998_Content_62 = {
    Text = [[
Bergaul akrab denganku juga tidak akan ada gunanya. 
 Di sini, aku tidak memiliki kuasa.]]
  },
  AvgDialog_18998_Content_63 = {
    Text = "Saya tidak punya kunci, jadi tidak bisa membebaskan kamu."
  },
  AvgDialog_18998_Content_64 = {
    Text = "Nada suara gadis itu dingin dan tegas."
  },
  AvgDialog_18998_Content_65 = {
    Text = "Tidak apa-apa, aku tidak berniat untuk melarikan diri..."
  },
  AvgDialog_18998_Content_66 = {
    Text = [[
Ngomong-ngomong, bisakah kamu menjelaskan tentang kejadian "orang mati hidup kembali"...
... Apakah itu benar?]]
  },
  AvgDialog_18998_Content_7 = {
    Text = "……\nPada saat itu, mengapa kamu memotong jawaban %hisorher%?"
  },
  AvgDialog_18998_Content_70 = {
    Text = [[
Suasana menurun hingga mencapai titik beku selama lebih dari sepuluh menit. 
 Tepat saat kamu mengira bahwa gadis itu tidak akan menjawab, dia akhirnya berbicara dengan nada yang tidak bersahabat.]]
  },
  AvgDialog_18998_Content_71 = {
    Text = "Misalkan kamu sekarang hamil lagi, lalu melahirkan seorang anak. Mereka mengatakan bahwa ini adalah putrimu yang dulu, yang telah hidup kembali. Apakah kamu percaya pada mereka?"
  },
  AvgDialog_18998_Content_73 = {
    Text = "Jika dia masih bisa mengingatku, mengingat hal-hal yang terjadi di masa lalu kita, mungkin itu sudah cukup."
  },
  AvgDialog_18998_Content_75 = {
    Text = "Setelah terdiam lama, gadis bernama Murphy menghela napas."
  },
  AvgDialog_18998_Content_76 = {
    Text = "Manusia masih tetap bodoh seperti biasa."
  },
  AvgDialog_18998_Content_77 = {
    Text = "<Small:Aku pikir kamu bisa melihatnya, akan berbeda.>"
  },
  AvgDialog_18998_Content_79 = {
    Text = "...Mayat yang kamu seret itu, siapa?"
  },
  AvgDialog_18998_Content_80 = {
    Text = [[
Dia adalah teman saya. Selama petualangan ini, dia sangat menjaga saya.
Peta untuk sampai ke sini juga diberikan olehnya.]]
  },
  AvgDialog_18998_Content_81 = {
    Text = "Teman, ya..."
  },
  AvgDialog_18998_Content_82 = {
    Text = "Bagaimana dia sekarang...?"
  },
  AvgDialog_18998_Content_83 = {
    Text = "Mungkin sudah diambil oleh <Blue:Miryam> untuk memberi makan. Orang yang sudah muncul bercak mayatnya bahkan tidak bisa dijadikan bahan bakar."
  },
  AvgDialog_18998_Content_84 = {
    Text = "Gadis itu berbicara dengan Ekspresi datar dan mengucapkan kata-kata yang membuat merinding."
  },
  AvgDialog_18998_Content_86 = {
    Text = "…<Yellow:Upacara> pada hari itu, kalian akan ditahan di dekat <Yellow:Altar>."
  },
  AvgDialog_18998_Content_87 = {
    Text = [[
Saya tidak tahu mengapa kamu belum pingsan, tapi bagaimanapun, kamu harus berpura-pura pingsan. 
Aku akan meletakkanmu di posisi terdekat dengan tepi kolam.]]
  },
  AvgDialog_18998_Content_88 = {
    Text = "Setelah mereka semua menarik diri, kenakan jubah keagamaan, lalu diam-diam tinggalkan tempat ini melalui jalan kecil di utara Altar."
  },
  AvgDialog_18998_Content_89 = {
    Text = [[
Ingat, segera pergi dengan kecepatan maksimal, jangan pernah kembali lagi. 
Jika sampai ketahuan oleh orang lain, aku tidak akan bisa membantu kamu.]]
  },
  AvgDialog_18998_Content_9 = {
    Text = "Bagi hal-hal yang belum saya pikirkan dengan jelas, pandangan %hisorher% bisa menyebabkan gangguan."
  },
  AvgDialog_19001_Content_1 = {
    Text = "Hmph! Kalian memang hebat, tapi Ibu Lisa pernah mengajari saya bahwa kebijaksanaan bisa membuat seseorang mengalahkan musuh yang jauh lebih kuat darinya!"
  },
  AvgDialog_19001_Content_2 = {
    Text = "Kita alihkan mereka, lalu hancurkan satu per satu!"
  },
  AvgDialog_19001_Content_3 = {Text = "Baik!"},
  AvgDialog_19002_Content_1 = {
    Text = "Selamat menikmati perjalanan Anda"
  },
  AvgDialog_19002_Content_10 = {
    Text = [[
Begitu protektif ya, Nona Kecil. 
 Apakah itu karena sesuatu yang dikatakan oleh Tuan Tua Dexter?]]
  },
  AvgDialog_19002_Content_11 = {
    Text = "Wajah pucat Ramona menunjukkan sedikit ketidaksetujuan, tetapi tanpa memberinya kesempatan untuk membantah, Narsis melambaikan tangan dan mengusirnya."
  },
  AvgDialog_19002_Content_12 = {
    Text = [[
Baiklah, sepertinya aku tidak diinginkan lagi.
Jika begitu, aku juga tidak akan menghambat perjalanan kalian.]]
  },
  AvgDialog_19002_Content_13 = {
    Text = "Semoga perjalanan kalian menyenangkan."
  },
  AvgDialog_19002_Content_14 = {
    Text = "Sepertinya aku pernah bilang, jangan sembarangan menelepon nomor ini kalau tidak ada keperluan penting."
  },
  AvgDialog_19002_Content_15 = {
    Text = [[
Anda telah berpesan dengan begitu tegas, bagaimana mungkin saya bisa melupakannya? 
 Jadi, apakah Anda tidak ingin mendengar pesan apa yang saya bawa untuk Anda?]]
  },
  AvgDialog_19002_Content_16 = {
    Text = "Siapa yang bergerak?"
  },
  AvgDialog_19002_Content_17 = {
    Text = "Universitas Mythag, Penjaga mereka sedang melacak \"si raksasa besar itu\"."
  },
  AvgDialog_19002_Content_18 = {
    Text = "……………"
  },
  AvgDialog_19002_Content_19 = {
    Text = [[
Di papan caturmu, sepertinya akan kehilangan satu bidak lagi. 
 Bagi Tuan <Blue:Herbert> yang ahli dalam strategi, ini pasti cukup menyakitkan, bukan?]]
  },
  AvgDialog_19002_Content_2 = {
    Text = "Sepertinya kalian sudah siap untuk berangkat."
  },
  AvgDialog_19002_Content_20 = {
    Text = "Nyonya terlalu memuji. Di bawah pengamatan orang itu, bagaimana mungkin kami yang seperti semut ini bisa membicarakan \"strategi\"? Ke mana mereka sekarang?"
  },
  AvgDialog_19002_Content_21 = {
    Text = [[
Anda akan segera mengetahuinya. 
 Ngomong-ngomong, "Ksatria" yang Anda kirim untuk mencegat bukanlah pilihan yang tepat.]]
  },
  AvgDialog_19002_Content_22 = {
    Text = "Orang yang bertindak sembrono seperti itu, di hadapan Universitas Mythag, kemungkinan besar akan menemui jalan buntu."
  },
  AvgDialog_19002_Content_23 = {
    Text = "Awalnya juga <Blue: sampah yang dilemparkan oleh Lentera>, tidak tahan lama, sudah cukup."
  },
  AvgDialog_19002_Content_24 = {
    Text = "Masih karena Rogers yang menghilang, memberikan saya banyak masalah tambahan."
  },
  AvgDialog_19002_Content_25 = {
    Text = [[
Jangan khawatir, bukankah kamu masih punya aku? 
Asalkan imbalannya masuk akal, Narsis dari toko solusi Daffdell pasti akan membantu menangani semua urusan yang mengganggumu.]]
  },
  AvgDialog_19002_Content_26 = {
    Text = "<Shake: Batuk, batuk>… Apakah kita benar-benar harus menggunakan transportasi ini?"
  },
  AvgDialog_19002_Content_27 = {
    Text = "Apa kereta bawah tanah ini... baunya sangat tidak sedap."
  },
  AvgDialog_19002_Content_28 = {
    Text = "Di dalam gerbong kereta bawah tanah yang ramai, seseorang sedang membaca \"Sungai Isis\" di bawah cahaya redup, sementara ada juga yang mengisap pipa dan menghembuskan asap tebal."
  },
  AvgDialog_19002_Content_29 = {
    Text = "Bau keringat tubuh manusia, bau rokok, dan bau solar yang menyengat bercampur menjadi satu, membentuk bau busuk yang aneh."
  },
  AvgDialog_19002_Content_3 = {
    Text = "Terima kasih atas \"perhatian\" Anda selama beberapa hari ini."
  },
  AvgDialog_19002_Content_30 = {
    Text = "Kamu melihat ke arah Lily di sisi jendela. Dia dengan penuh rasa ingin tahu memperhatikan penumpang, kursi, dan pegangan di sekitarnya, seolah-olah untuk pertama kalinya menghadapi dunia baru ini, tenang seperti boneka."
  },
  AvgDialog_19002_Content_31 = {
    Text = "Alih-alih naik bus sekolah yang bagus, kalian malah membujuknya naik barang rusak ini. Apakah kalian terlalu memanjakannya?"
  },
  AvgDialog_19002_Content_32 = {
    Text = "Bukankah mencoba hal-hal baru itu cukup menarik? Saya merasa pengalaman ini sangat berharga."
  },
  AvgDialog_19002_Content_33 = {
    Text = "Mengenai tindakan selanjutnya, apakah kamu punya ide, Penjaga?"
  },
  AvgDialog_19002_Content_34 = {
    Text = "Mengingat <Yellow:pandangan> yang kami rasakan saat berhadapan dengan Herbert kemungkinan berasal dari Anjing neraka yang sebenarnya, tetap tinggal di kota adalah langkah yang lebih konservatif."
  },
  AvgDialog_19002_Content_35 = {
    Text = "Namun, mungkin kita juga bisa mencoba jalan lain: mengawal Lily ke Rumah Sakit Lai, melakukan penyelidikan terhadap Francis."
  },
  AvgDialog_19002_Content_36 = {
    Text = "Dia memang terlihat tidak sederhana."
  },
  AvgDialog_19002_Content_37 = {
    Text = [[
Baik tetap tinggal di kota maupun pergi ke sanatorium, kita harus waspada terhadap campur tangan Dafude'er. 
 Kehadirannya di Rai pada saat ini bukanlah suatu kebetulan.]]
  },
  AvgDialog_19002_Content_38 = {
    Text = [[
Dia seharusnya tidak akan secara aktif menghalangi kalian. 
Berdasarkan pemahamanku tentang dia, hanya hal-hal yang terkait dengan koleksi yang dapat menarik minatnya.]]
  },
  AvgDialog_19002_Content_39 = {
    Text = "\"Seharusnya\"?"
  },
  AvgDialog_19002_Content_4 = {
    Text = "Benar-benar anak yang baik. Hati-hati di sepanjang jalan, ya."
  },
  AvgDialog_19002_Content_40 = {
    Text = "Haha, informasi tentang sanatorium itu sudah aku kirimkan kepadamu, jangan lupa untuk memeriksanya ya."
  },
  AvgDialog_19002_Content_41 = {
    Text = [[
Terima kasih kepada Profesor Dexter yang telah mengirimkan informasi bahwa Erica juga dapat melakukan transmisi sendiri. 
 Jika tidak ada hal lain, saya akan memutuskan kontak terlebih dahulu.]]
  },
  AvgDialog_19002_Content_42 = {
    Text = [[
Tunggu sebentar. 
 Setelah kamu meninjau data, saya telah memeriksa ulang informasi yang diketahui tentang sanatorium.]]
  },
  AvgDialog_19002_Content_43 = {
    Text = "Apa ada temuan?"
  },
  AvgDialog_19002_Content_44 = {
    Text = "Dalam kasus hilangnya orang di Kota Rai, para korban hilang memiliki kerabat dekat yang sudah tua dan lemah atau menderita penyakit Roh. Tiga di antaranya pernah secara pribadi menyerahkan kerabat mereka ke Rumah Sakit Roh Rai."
  },
  AvgDialog_19002_Content_45 = {
    Text = "Mungkin yang lain yang hilang juga melakukan hal serupa, hanya saja tidak ada catatan mengenainya."
  },
  AvgDialog_19002_Content_46 = {
    Text = "Mungkin karena kurangnya pengalaman, polisi setempat meskipun telah membuat catatan, tetapi tidak melakukan Penyelidikan terkait ciri umum ini."
  },
  AvgDialog_19002_Content_47 = {
    Text = "Saya merasa dasar ini tidak terlalu kuat, karena dalam hidup lebih lama, siapa yang bisa menjamin semua kerabatnya bebas dari penyakit dan bencana?"
  },
  AvgDialog_19002_Content_48 = {
    Text = "Bagaimanapun juga, untuk sementara kami tidak punya petunjuk lain."
  },
  AvgDialog_19002_Content_49 = {
    Text = "Saya akan terus memperhatikan kemungkinan-kemungkinan ini."
  },
  AvgDialog_19002_Content_5 = {
    Text = "Narsis tersenyum, memeriksa kalian dari atas ke bawah, lalu tiba-tiba mendekati sisi telingamu."
  },
  AvgDialog_19002_Content_50 = {
    Text = "Kalau begitu, selamat malam. \nAku akan menyiapkan segelas anggur merah dari Zolin Winery, dan menikmati aroma tanah Rumah-ku dengan sepenuh hati—"
  },
  AvgDialog_19002_Content_51 = {
    Text = "Ramona langsung memutus komunikasi."
  },
  AvgDialog_19002_Content_52 = {
    Text = "Kalau begitu, besok pagi kita berangkat mengunjungi <Blue:Roh Rumah Sakit Jiwa Lai> ya."
  },
  AvgDialog_19002_Content_53 = {
    Text = "Setelah itu, Francis pergi terlebih dahulu pada larut malam bersama asistennya, sementara kalian bertanggung jawab mengantarkan Lily kembali ke Panti Rehabilitasi Roh Lai."
  },
  AvgDialog_19002_Content_54 = {
    Text = "Atas permintaan Lily, kalian memilih untuk naik kereta bawah tanah menuju pinggiran kota yang terpencil."
  },
  AvgDialog_19002_Content_55 = {
    Text = [[
Sedikit suara mengembalikanmu dari kenangan ke kenyataan. 
Ketika menunduk, gadis yang mirip boneka menarik ujung bajumu.]]
  },
  AvgDialog_19002_Content_56 = {
    Text = "%player%{Male=Tuan Penjaga Rahasia,Female=Nona Penjaga Rahasia}..."
  },
  AvgDialog_19002_Content_57 = {
    Text = "Kamu bilang, jika seorang gadis yang suka bermain tidak mendengarkan nasihat ibunya dan terjadi sesuatu yang buruk... apakah ibunya akan sangat marah hingga tidak ingin melihatnya lagi?"
  },
  AvgDialog_19002_Content_58 = {
    Text = "Bermain adalah sifat alami anak-anak, dan ibunya pasti akan memahaminya."
  },
  AvgDialog_19002_Content_59 = {
    Text = [[
Tetapi, tetapi hal buruk itu membuatnya berubah, kan?
Menjadi sosok yang bahkan ibunya tidak bisa mengenali...]]
  },
  AvgDialog_19002_Content_6 = {
    Text = "<Yellow:Jangan lupa, kamu sudah pernah melihat \"Anjing neraka\" sekali.>"
  },
  AvgDialog_19002_Content_60 = {
    Text = "Apakah sebaiknya aku tidak pulang ke rumah lagi?\nKarena Ibu pasti akan sangat marah dan sedih…"
  },
  AvgDialog_19002_Content_61 = {
    Text = "Kamu tahu dia sedang membicarakan Lisa."
  },
  AvgDialog_19002_Content_62 = {
    Text = "Lisa sekarang, mungkin tak akan pernah bisa kembali ke sisi ibunya, dan hanya bisa terus hidup sebagai \"Coom\"."
  },
  AvgDialog_19002_Content_63 = {
    Text = "Memorimu dimulai dari ledakan besar di Akut setahun yang lalu. Mengenai keluarga, mengenai ibu, kamu tidak bisa memberikan Lily jawaban yang memuaskan, tetapi jika hanya untuk menghiburnya…"
  },
  AvgDialog_19002_Content_64 = {
    Text = "Ibu tidak akan menyerah pada anak perempuan itu"
  },
  AvgDialog_19002_Content_65 = {
    Text = "Konon, kasih sayang seorang ibu adalah perasaan paling penuh pengertian di dunia."
  },
  AvgDialog_19002_Content_66 = {
    Text = "Tidak peduli bagaimana pun anak itu berubah, selama dia memahami bahwa itu adalah anaknya sendiri, pasti dia akan tetap menerimanya."
  },
  AvgDialog_19002_Content_67 = {
    Text = "Ibu pasti menginginkan dia selamat."
  },
  AvgDialog_19002_Content_68 = {
    Text = "Anak-anak pada akhirnya akan tumbuh dewasa, memiliki kehidupan mereka sendiri, dan menghadapi situasi di mana mereka harus berpisah dari orang tua."
  },
  AvgDialog_19002_Content_69 = {
    Text = "Ada ibu yang berharap anaknya menjadi pedagang besar, ada yang menginginkan anaknya menjadi cendekiawan, dan ada pula yang mendukung anaknya untuk menempuh jalan sebagai petualang."
  },
  AvgDialog_19002_Content_7 = {
    Text = "Nada suaranya misterius dan penuh keangkeran, rasa dingin perlahan meresap ke tulang sumsum melalui telinga."
  },
  AvgDialog_19002_Content_70 = {
    Text = "Tidak peduli bagaimana anak-anak memilih, sebagai seorang ibu, saya akan selalu memberkati mereka dan berdoa untuk keselamatan mereka."
  },
  AvgDialog_19002_Content_71 = {
    Text = "Kamu memejamkan mata sejenak, bayangan seseorang yang jatuh dari menara lonceng melintas di benakmu."
  },
  AvgDialog_19002_Content_72 = {
    Text = [[
Hidup seseorang tidak akan selamanya berjalan di jalan yang sudah ditentukan. 
 Jika melakukan kesalahan, harus memperbaikinya; jika tidak melakukan kesalahan, jalani hidup dengan lebih bahagia.]]
  },
  AvgDialog_19002_Content_73 = {
    Text = "Dalam perjalanan saya dan Ramona, kami pernah bertemu seorang anak... dia memberikan segalanya untuk memperbaikinya."
  },
  AvgDialog_19002_Content_74 = {
    Text = "Ramona di sisinya, sorot matanya bergerak, tanpa menyela."
  },
  AvgDialog_19002_Content_75 = {
    Text = "Dia mengira yang dia bawa pergi adalah dosa, tetapi teman-temannya semua berharap dia tetap tinggal di sisi mereka… Jika teman-temannya saja seperti ini, apalagi ibu dari gadis itu?"
  },
  AvgDialog_19002_Content_76 = {
    Text = "Lily mendengarkan kata-katamu, kepalanya yang kecil terbenam di antara lengan, tenggelam dalam pikiran. Tidak diketahui apakah kata-kata itu terlalu sulit baginya."
  },
  AvgDialog_19002_Content_77 = {
    Text = "Kereta tiba-tiba bergoyang dengan hebat, diikuti oleh teriakan-teriakan yang saling bersahutan di dalam gerbong."
  },
  AvgDialog_19002_Content_78 = {
    Text = "Di tengah kekacauan, terdengar suara gesekan dari bawah. Saat menunduk, tatapan Lily tampak goyah, dan satu tangannya erat memegang ujung bajumu."
  },
  AvgDialog_19002_Content_79 = {
    Text = "Dia datang."
  },
  AvgDialog_19002_Content_8 = {
    Text = "Ramona menarikmu dengan lembut, lalu berbicara dengan sopan dan penuh kendali."
  },
  AvgDialog_19002_Content_80 = {
    Text = [[
Kemungkinan besar mereka datang untuk menyerang kita. 
Penjaga, Lotan, bersiaplah untuk menghadapi musuh!]]
  },
  AvgDialog_19002_Content_9 = {
    Text = [[
Terima kasih banyak atas perhatian Anda. 
Jika Anda memiliki urusan lain, silakan hubungi Profesor Dexter. Dia akan menyampaikannya kepada kami.]]
  },
  AvgDialog_19003_Content_1 = {
    Text = "Kalian dengan tergesa-gesa mengejar Lotan."
  },
  AvgDialog_19003_Content_2 = {
    Text = "Aku adalah Relik Awal, Paus Raksasa Abadi, Air Jurang, Jiwa Eden, Dewa Kekuasaan Perusakan dan Aturan, yang menuruti kehendak Planet, akan tinggal di sini!"
  },
  AvgDialog_19003_Content_3 = {
    Text = [[
Toko kami kecil, tidak bisa menampung banyak orang! 
 Di luar kota ada rumah sakit jiwa, di sana lebih luas, sepertinya cocok!]]
  },
  AvgDialog_19003_Content_4 = {
    Text = "Kamu ini——"
  },
  AvgDialog_19003_Content_5 = {
    Text = "Tunggu, Lotan…"
  },
  AvgDialog_19003_Content_6 = {
    Text = "Cukup omong kosong! Hari ini aku pasti akan memberi pelajaran pada orang yang tidak sopan ini! Kalau punya nyali, coba ikat aku lagi dengan kunci!"
  },
  AvgDialog_19005_Content_1 = {
    Text = "Sebuah kabar buruk, sebuah kabar baik."
  },
  AvgDialog_19005_Content_2 = {
    Text = "Berita buruk: Pria itu melarikan diri memanfaatkan kesempatan."
  },
  AvgDialog_19005_Content_3 = {
    Text = "Kabar baiknya adalah, di sisi lain, Lotan kemungkinan besar tidak akan kekurangan lawan yang cukup kuat."
  },
  AvgDialog_19005_Content_4 = {
    Text = "Lari begitu cepat, aku bahkan belum sempat melakukan pemanasan."
  },
  AvgDialog_19005_Content_5 = {
    Text = "Jangan terburu-buru, aku punya cara."
  },
  AvgDialog_19005_Content_6 = {
    Text = [[
Kamu mengaktifkan Kunci Perak, cahaya berkilauan kecil menunjukkan sumber Aliemus yang luar biasa. 
 Kamu melihat ke arah itu, sebuah Bayangan hitam dengan cepat melesat.]]
  },
  AvgDialog_19005_Content_7 = {
    Text = "Ke arah itu, kejar!"
  },
  AvgDialog_19007_Content_1 = {
    Text = "Sekarang bisa dibuka."
  },
  AvgDialog_19007_Content_2 = {
    Text = "Di sini...?"
  },
  AvgDialog_19007_Content_3 = {
    Text = "Lorong Dimensi. Kami sedang melangkah mengikuti jejak yang ditinggalkan oleh Dafude'er."
  },
  AvgDialog_19009_Content_1 = {
    Text = "Kartu truf di lengan"
  },
  AvgDialog_19009_Content_10 = {
    Text = "Begitu terdengar lebih mencurigakan..."
  },
  AvgDialog_19009_Content_11 = {
    Text = "Bagaimana mungkin, seperti binatang bodoh yang pasti akan tertarik pada bau darah, bayi manusia sama sekali tidak bisa menahan godaan permen."
  },
  AvgDialog_19009_Content_12 = {
    Text = [[
Perumpamaan ini sungguh... 
 Tunggu sebentar, sepertinya ada suara dari luar.]]
  },
  AvgDialog_19009_Content_13 = {
    Text = "Hmm? Apa itu suara?"
  },
  AvgDialog_19009_Content_14 = {
    Text = "Kamu juga mendengarnya, kan? Kalau begitu, tolong periksa sekalian."
  },
  AvgDialog_19009_Content_15 = {
    Text = "Hei, jangan kira aku tidak tahu kalau kamu ingin menyingkirkan aku——"
  },
  AvgDialog_19009_Content_16 = {
    Text = "%player%, kamu pasti tidak akan sekejam dia, kan?"
  },
  AvgDialog_19009_Content_17 = {
    Text = "Serahkan ini kepada saya dan Ramona."
  },
  AvgDialog_19009_Content_18 = {
    Text = "Percayalah pada kami, kami sangat ahli dalam berkomunikasi dengan anak-anak."
  },
  AvgDialog_19009_Content_19 = {
    Text = "Ramona menghela napas dengan lembut."
  },
  AvgDialog_19009_Content_2 = {
    Text = "Di dalam toko, semuanya tampak seperti biasa. Kalian bertiga duduk berjejer menghadap Lily yang kecil. \n Adegan ini terasa seperti sebuah interogasi…"
  },
  AvgDialog_19009_Content_20 = {
    Text = "Astaga, suara di luar semakin membesar."
  },
  AvgDialog_19009_Content_21 = {
    Text = "Sebaiknya kamu keluar dan lihat-lihat, Lotan. Urusan kecil ini serahkan saja pada kami, aku dan Ramona."
  },
  AvgDialog_19009_Content_22 = {
    Text = "Hei, pelit."
  },
  AvgDialog_19009_Content_23 = {
    Text = "Lotan berbalik dan keluar dari ruangan, pandangan Lily mengikuti punggungnya dengan gelisah."
  },
  AvgDialog_19009_Content_24 = {
    Text = "Kakak yang menakutkan sudah pergi. Kita bisa bersantai sedikit, kan, Lily?"
  },
  AvgDialog_19009_Content_25 = {
    Text = "Gadis itu berkedip, seakan-akan dia benar-benar merasa rileks, atau mungkin dia sama sekali tidak memahami situasi saat ini."
  },
  AvgDialog_19009_Content_26 = {
    Text = "Apakah kamu tahu keberadaan Lisa?"
  },
  AvgDialog_19009_Content_27 = {
    Text = "Lily mengangguk, lalu menggelengkan kepala."
  },
  AvgDialog_19009_Content_28 = {
    Text = [[
Lalu, bisakah kamu memberitahu kami? 
 Tenang saja, di sini hanya ada aku dan %player%, kami akan menjaga rahasia Anda, dan melindungi Anda.]]
  },
  AvgDialog_19009_Content_29 = {
    Text = "Tidak bisa, karena... <Yellow:mata> terus mengamati Lily..."
  },
  AvgDialog_19009_Content_3 = {
    Text = "Lily gelisah, terus-menerus menengadah dan melirik ke arah luar jendela."
  },
  AvgDialog_19009_Content_30 = {Text = "Mata?"},
  AvgDialog_19009_Content_31 = {
    Text = "Hmm, banyak sekali mata-mata, dari <Yellow:dimensi lain>…"
  },
  AvgDialog_19009_Content_32 = {
    Text = "Dimensi? Apakah Lily memahami apa arti dimensi?"
  },
  AvgDialog_19009_Content_33 = {
    Text = "Lily tiba-tiba menutup rapat bibirnya, tak mengucapkan sepatah kata pun, sesekali melirik ke luar jendela dengan panik."
  },
  AvgDialog_19009_Content_34 = {
    Text = "%player%, sepertinya ada suara di luar."
  },
  AvgDialog_19009_Content_35 = {
    Text = "... Apakah kau juga akan menyingkirkanku?"
  },
  AvgDialog_19009_Content_36 = {
    Text = "Bukan——"
  },
  AvgDialog_19009_Content_37 = {
    Text = "Roaarrrrrrrr——"
  },
  AvgDialog_19009_Content_38 = {
    Text = "Di luar benar-benar ada sesuatu!"
  },
  AvgDialog_19009_Content_39 = {
    Text = "Lotan! Apa yang terjadi!"
  },
  AvgDialog_19009_Content_4 = {
    Text = "Kamu baru saja ingin mengatakan sesuatu untuk memecah suasana yang menekan, tetapi Lotan lebih dulu membuka suara."
  },
  AvgDialog_19009_Content_40 = {
    Text = "Tidak perlu mengikuti, aku bisa menyelesaikannya!"
  },
  AvgDialog_19009_Content_5 = {
    Text = "Hei, apakah kamu tahu ke mana anak bernama Lisa pergi?"
  },
  AvgDialog_19009_Content_6 = {
    Text = "Jangan khawatir, kita semua adalah orang yang masuk akal. Sebelum memahami situasinya, kami tidak akan mengejarmu seperti ibu-ibu gila itu."
  },
  AvgDialog_19009_Content_7 = {
    Text = "Jika kamu dengan patuh memberitahu keberadaan Lisa itu, kakak yang cantik di sana akan memberimu permen sebagai hadiah, lho?"
  },
  AvgDialog_19009_Content_8 = {
    Text = "Lotan, jangan membuatnya takut."
  },
  AvgDialog_19009_Content_9 = {
    Text = "Bagaimana mungkin! Bukankah aku adalah kakak perempuan yang paling lembut, iya kan?"
  },
  AvgDialog_19013_Content_1 = {
    Text = "Segala sesuatu akan berjalan dengan sendirinya saat kapal tiba di jembatan."
  },
  AvgDialog_19013_Content_10 = {
    Text = "Kum, jangan takut."
  },
  AvgDialog_19013_Content_11 = {
    Text = "Hewan sangat sensitif, mereka dan itu pasti merasakan sesuatu."
  },
  AvgDialog_19013_Content_12 = {
    Text = [[
Di kegelapan, tiba-tiba terdengar suara serak dan aneh yang menyayat. 
 Seolah-olah pita suaranya sudah lama rusak, dengan cairan kental memenuhi tenggorokan.]]
  },
  AvgDialog_19013_Content_13 = {
    Text = "... demi ... menyerah ..."
  },
  AvgDialog_19013_Content_14 = {
    Text = [[
Lily mengangkat tangannya, menunjuk ke dalam kegelapan.
Kalian bisa merasakan dengan samar bahwa itu adalah arah dari mana suara aneh tersebut berasal.]]
  },
  AvgDialog_19013_Content_2 = {
    Text = [[
Jembatan Baja Fuler melintasi permukaan sungai di tengah malam, 
 batang baja seperti senar harpa, dimainkan oleh angin menjadi lagu duka dalam kegelapan malam.]]
  },
  AvgDialog_19013_Content_3 = {
    Text = "Warna malam seperti bayangan gelap yang melahap segalanya. Di sini, Kuum yang telah menunggu kalian selama ini menggonggong dua kali. Di ujung jembatan besi yang redup, lampu bergoyang dengan cahaya yang samar-samar."
  },
  AvgDialog_19013_Content_4 = {
    Text = "...Tidak beres."
  },
  AvgDialog_19013_Content_5 = {
    Text = "Saya juga merasakan hal yang sama, tetapi tidak bisa menjelaskan dengan tepat apa yang salah."
  },
  AvgDialog_19013_Content_6 = {
    Text = [[
Bukankah ini sudah jelas?
Apakah kamu mendengar suara hewan?]]
  },
  AvgDialog_19013_Content_7 = {
    Text = [[
Tidak ada. 
 Segala sesuatu begitu sunyi, tanpa suara.]]
  },
  AvgDialog_19013_Content_8 = {
    Text = "Bahkan jika kalian semua menutup suara dan mata untuk fokus mendengarkan, kalian hanya akan merasakan desiran angin, serta lolongan dari kegelapan yang terlalu jauh, yang sudah tidak bisa dipastikan apakah itu halusinasi atau bukan."
  },
  AvgDialog_19013_Content_9 = {
    Text = "Khum mendengus dengan gelisah."
  },
  AvgDialog_19014_Content_1 = {
    Text = "Hmph, kalian pasti menahan diri, kan? Benar-benar membosankan."
  },
  AvgDialog_19014_Content_10 = {
    Text = "Komunikasi tiba-tiba terputus."
  },
  AvgDialog_19014_Content_11 = {
    Text = [[
Di ujung pandangan, tiba-tiba muncul satu... atau lebih tepatnya dua kucing tak berbulu dengan telinga panjang. 
 Dua kepala, dijahit rapat-rapat menjadi satu, berbagi tubuh yang ramping dan atletis.]]
  },
  AvgDialog_19014_Content_12 = {
    Text = "Dengan lincah, ia melompat dan mendarat di pundak seorang pria berambut kusut."
  },
  AvgDialog_19014_Content_13 = {
    Text = [[
Ini benar-benar pertemuan takdir yang luar biasa. 
 Cahaya bulan malam ini sangat indah, bukan?]]
  },
  AvgDialog_19014_Content_14 = {
    Text = "Para mahasiswa Universitas mythag."
  },
  AvgDialog_19014_Content_2 = {
    Text = "Penyelidikan Pelarutan bukanlah olahraga bela diri, Lotan. Jika hanya berkeringat yang bisa membantu mengatasi defisit perhatianmu, saya sarankan kamu mencari Sylvia untuk bimbingan psikologis."
  },
  AvgDialog_19014_Content_3 = {
    Text = "Ramona, sinkronkan situasi abnormal yang kamu amati sebelumnya."
  },
  AvgDialog_19014_Content_4 = {
    Text = "Ya. Diamati pustula lendir di Dimensi Domain, dengan diameter sekitar 20 inci. Setelah ditusuk, mengeluarkan lendir hitam yang bercahaya hijau dan kemudian menghilang secara alami."
  },
  AvgDialog_19014_Content_5 = {
    Text = "Tidak ada informasi serupa tentang pustula dalam catatan terkait \"Kerberos\"."
  },
  AvgDialog_19014_Content_6 = {
    Text = "...adalah Pembangun."
  },
  AvgDialog_19014_Content_7 = {
    Text = [[
Penjaga, Ramona.
Dengar, kalian harus berhati-hati terhadap seorang pria bermata mekanik.]]
  },
  AvgDialog_19014_Content_8 = {
    Text = "Kalian terus-menerus berhadapan langsung dengan Para pematung, dia pasti sudah mengincar kalian."
  },
  AvgDialog_19014_Content_9 = {
    Text = "Dia mungkin tidak akan terlibat dalam konflik langsung dengan kalian, tapi……<Shake:@1@2……>"
  },
  AvgDialog_19015_Content_1 = {
    Text = "Kemarin Terulang"
  },
  AvgDialog_19015_Content_10 = {
    Text = "Mungkin setelah mengetahui kebenaran, dia akan kehilangan arah karena \"siapa dirinya\"…\nSituasi seperti ini sudah sering kulihat selama ratusan hingga ribuan tahun terakhir."
  },
  AvgDialog_19015_Content_11 = {
    Text = "Di matamu, apa dia itu?"
  },
  AvgDialog_19015_Content_12 = {
    Text = "Dia adalah seorang manusia, teman sekelas saya."
  },
  AvgDialog_19015_Content_13 = {
    Text = "Dia, seperti Pembangun, dapat membantu saya dalam pertempuran."
  },
  AvgDialog_19015_Content_14 = {
    Text = "Apa pun dia sebenarnya tidak penting."
  },
  AvgDialog_19015_Content_15 = {
    Text = "Kamu belum sempat mengatakannya, suara yang sudah tidak asing lagi langsung memotong percakapan kalian."
  },
  AvgDialog_19015_Content_16 = {
    Text = "Aku kembali, %player%, Lotan."
  },
  AvgDialog_19015_Content_17 = {
    Text = "……Apa? Kenapa kamu menatapku dengan aneh, apakah ada sesuatu di wajahku?"
  },
  AvgDialog_19015_Content_18 = {
    Text = "Tidak, tidak ada apa-apa."
  },
  AvgDialog_19015_Content_19 = {
    Text = "Selamat datang kembali"
  },
  AvgDialog_19015_Content_2 = {
    Text = [[
Merangkak, merangkak, tanpa henti merangkak. 
Kedua kaki yang kehilangan kendali merayap di tanah, retina yang rusak hanya menangkap dunia yang kabur.]]
  },
  AvgDialog_19015_Content_21 = {
    Text = "Saya membawa kabar baik dan kabar buruk."
  },
  AvgDialog_19015_Content_22 = {
    Text = "Kabar baiknya adalah pihak sekolah menyetujui strategi kami, sehingga kami bisa mengawal Lily kembali ke sisi ibunya."
  },
  AvgDialog_19015_Content_23 = {
    Text = "Kabar buruknya adalah, William mengamati beberapa orang aneh yang mengincar rumah sakit roh."
  },
  AvgDialog_19015_Content_24 = {
    Text = "Jika perasaan saya tidak meleset... mereka sekarang sedang bersembunyi di sekitar kita."
  },
  AvgDialog_19015_Content_3 = {
    Text = [[
Pergerakan merangkak seperti ini sudah berlangsung selama hampir 20 jam. 
 Tubuh yang kehilangan sumber Kekuatan Roh secara bertahap membusuk, dan tenaganya juga hampir habis.]]
  },
  AvgDialog_19015_Content_4 = {
    Text = "Sebelum sepenuhnya tenggelam dalam kegelapan, dia harus menemukan orang itu —"
  },
  AvgDialog_19015_Content_5 = {
    Text = [[
Kamu sendiri yang ingin mengantarnya pergi, namun kemudian menjadi gelisah lagi. 
Manusia memang selalu seperti ini, kurang terbuka.]]
  },
  AvgDialog_19015_Content_6 = {
    Text = "Saya tidak tahu kebenaran seperti apa yang akan dia dengar, dan bagaimana dia akan memutuskan."
  },
  AvgDialog_19015_Content_7 = {
    Text = "...Aku melihatnya tumbuh dari seorang bayi yang belajar berjalan hingga menjadi seperti sekarang. Dia bukan Bangun, tapi... juga bukan manusia."
  },
  AvgDialog_19015_Content_8 = {
    Text = "Manusia biasa tidak mungkin menunjukkan kemampuan pertempuran seperti ini."
  },
  AvgDialog_19015_Content_9 = {
    Text = "Orang-orang Dexter menyembunyikan latar belakangnya dengan sangat baik, bahkan sampai menutup Kolam Hitam demi itu. Bukan hanya untuk melindungi Mythag, tetapi juga untuk melindungi dirinya."
  },
  AvgDialog_19016_Content_1 = {
    Text = "Seperti duri di punggung"
  },
  AvgDialog_19016_Content_10 = {
    Text = "Segera, dia berbalik dan menghadap kalian."
  },
  AvgDialog_19016_Content_100 = {
    Text = "...selama menuruni bukit ini..."
  },
  AvgDialog_19016_Content_101 = {Text = "!"},
  AvgDialog_19016_Content_102 = {
    Text = "Tumpukan salju yang lembut di bawah kakimu tiba-tiba runtuh, pandanganmu menjadi gelap, lalu kamu pingsan."
  },
  AvgDialog_19016_Content_11 = {
    Text = "Apakah mereka yang kamu maksud, teman baru Lily?"
  },
  AvgDialog_19016_Content_12 = {
    Text = "Francis mengangguk pelan, seolah-olah sedang bergumam pada dirinya sendiri."
  },
  AvgDialog_19016_Content_13 = {
    Text = "Halo, saya adalah ibu Lily, panggil saja saya Frances."
  },
  AvgDialog_19016_Content_14 = {
    Text = "Ini adalah asisten saya, <Blue:Nymphaea>."
  },
  AvgDialog_19016_Content_15 = {
    Text = "Salam sejahtera. Saya Nymphaea Borrones, silakan panggil saya Nymphaea."
  },
  AvgDialog_19016_Content_16 = {
    Text = [[
Apa yang terjadi, aku sudah mendengarnya dari Narsis. 
Aku adalah Dokter di <Blue:Roh>, Lily sebelumnya juga tinggal bersamaku di sanatorium.]]
  },
  AvgDialog_19016_Content_17 = {
    Text = "Saya tidak ingin Lily tinggal terlalu lama di lingkungan seperti itu, jadi saya mengirimnya untuk sementara tinggal di kota. Tidak disangka, dia masih sulit beradaptasi dengan kehidupan di luar."
  },
  AvgDialog_19016_Content_18 = {
    Text = [[
Saya sangat menyesal Lily telah menyebabkan begitu banyak masalah bagi kalian. 
Sebagai seorang ibu yang tidak kompeten, saya menyampaikan permintaan maaf yang mendalam.]]
  },
  AvgDialog_19016_Content_19 = {
    Text = "Jika bukan karena Kuum masih tampak seperti menghadapi musuh besar, dia akan terlihat seperti seorang ibu biasa yang sedikit tegas namun tetap hangat."
  },
  AvgDialog_19016_Content_2 = {
    Text = "Di luar pintu terdengar ketukan lembut. Di malam yang sunyi, suara ketukan berirama membuat tulang punggung terasa dingin secara misterius."
  },
  AvgDialog_19016_Content_20 = {
    Text = "Tidak perlu begitu, Lily sangat penurut."
  },
  AvgDialog_19016_Content_21 = {
    Text = "Hubungan dengan %player% juga sangat baik."
  },
  AvgDialog_19016_Content_22 = {
    Text = "Harapan setelah ini ada kesempatan untuk membalas budi kepada kalian berdua."
  },
  AvgDialog_19016_Content_23 = {
    Text = "Mendengar ucapanmu, apakah kamu akan pergi sekarang?"
  },
  AvgDialog_19016_Content_24 = {
    Text = "Kamu tahu, hanya dengan mengandalkan Nymphaea, aku tidak bisa tinggal di luar semalaman."
  },
  AvgDialog_19016_Content_25 = {
    Text = "Dan… menghindar bukanlah solusi, aku harus berbicara dengan <Yellow:orang itu>."
  },
  AvgDialog_19016_Content_26 = {
    Text = "Rektor Ozwood, mungkin dalam hal ini, saya bisa sedikit membantu meringankan beban Anda?"
  },
  AvgDialog_19016_Content_27 = {
    Text = [[
Tidak, Nymphaea, kau tidak perlu terlibat dalam urusan-urusan ini. 
Keputusan yang telah aku buat, harus aku selesaikan sendiri.]]
  },
  AvgDialog_19016_Content_28 = {
    Text = "Maka aku sangat tidak menyarankan kamu membawa Lily bersamamu, terutama pada beberapa malam ini."
  },
  AvgDialog_19016_Content_29 = {
    Text = "Ada sebuah solusi yang menguntungkan kedua belah pihak: kamu pergi menangani urusanmu, dan tugas mengantarkan Lily kembali akan diserahkan kepada beberapa teman di sini. Bagaimana?"
  },
  AvgDialog_19016_Content_3 = {
    Text = "Ssshh——"
  },
  AvgDialog_19016_Content_30 = {
    Text = "Ini tidak pantas, Lily sudah menyebabkan terlalu banyak masalah bagi semua orang."
  },
  AvgDialog_19016_Content_31 = {
    Text = [[
Narsis memberi kalian kedipan mata. 
 Rupanya, inilah "jawaban" kalian.]]
  },
  AvgDialog_19016_Content_32 = {
    Text = "Kami semua senang berinteraksi dengan Lily."
  },
  AvgDialog_19016_Content_33 = {
    Text = "Kalau begitu... aku menyerahkannya padamu."
  },
  AvgDialog_19016_Content_34 = {
    Text = "Antarkan Lily pulang ke Rumah Sakit Roh Rai."
  },
  AvgDialog_19016_Content_35 = {
    Text = "23:00, Kamar Tidur Lantai Dua"
  },
  AvgDialog_19016_Content_36 = {
    Text = "Erica, tolong bantu aku memeriksa semua data terkait Rumah Sakit Roh Rai."
  },
  AvgDialog_19016_Content_37 = {
    Text = "Rumah Sakit Roh Rai, terletak di sudut tenggara Jalan Lindsay di kota kecil Rai, sudah berdiri selama dua belas tahun. Bisnis utamanya adalah pengamatan dan pemulihan gangguan rohani, sehingga juga dikenal sebagai rumah sakit jiwa."
  },
  AvgDialog_19016_Content_38 = {
    Text = "Kepala saat ini Francis Ozwood——"
  },
  AvgDialog_19016_Content_39 = {
    Text = "Lewati hal-hal yang jelas terlihat ini. Apakah ada data pasien yang dapat diperiksa? Dan bagaimana dengan informasi tentang keluarga mereka?"
  },
  AvgDialog_19016_Content_4 = {
    Text = "Khum tiba-tiba mengangkat tubuhnya, seperti seekor binatang yang terkepung, dan mengambil posisi siap untuk menyerang."
  },
  AvgDialog_19016_Content_40 = {
    Text = [[
Sedang mengambil data, harap tunggu sebentar...
Karena melibatkan sejumlah besar informasi, perkiraan waktu penyelesaian pengambilan data adalah pukul 8 pagi besok.]]
  },
  AvgDialog_19016_Content_41 = {
    Text = [[
...Baiklah. Terima kasih, Erica.
Sepertinya ini sudah semua yang bisa kulakukan hari ini.]]
  },
  AvgDialog_19016_Content_42 = {
    Text = "Saya punya firasat, acara kali ini baru saja dimulai…"
  },
  AvgDialog_19016_Content_43 = {
    Text = "Berbaring di tempat tidur, rasa kantuk terus menyerang. Sebuah kesan samar-samar muncul di benakmu."
  },
  AvgDialog_19016_Content_44 = {
    Text = "Mungkin, akan bermimpi lagi… <Yellow:Mimpi>…"
  },
  AvgDialog_19016_Content_45 = {
    Text = [[
Selamat datang di <Blue:Tim Penjelajah Elworth>.
Saya adalah pemimpin tim, kamu bisa memanggil saya <Blue:Bertrand>.]]
  },
  AvgDialog_19016_Content_46 = {
    Text = "Saya sudah membaca laporan aplikasi Anda. Jujur saja, kami telah melakukan persiapan selama tiga bulan dan seharusnya tidak menerima personel non-profesional secara mendadak."
  },
  AvgDialog_19016_Content_47 = {
    Text = "Namun, perjalanan ini sangat berbahaya, tenaga medis tidak dapat diabaikan. Oleh karena itu, meskipun kamu hanya menjalani pelatihan singkat, kami tetap mengundangmu untuk bergabung dengan tim kami dan bersama-sama menaklukkan <Blue:Elworth>."
  },
  AvgDialog_19016_Content_48 = {
    Text = "Jika ada ketidaknyamanan selama proses, segera beri tahu saya. Demi keselamatan hidup, kami akan mengirimkan sinyal bantuan dan meninggalkan cukup inventaris untuk menunggu penyelamatan."
  },
  AvgDialog_19016_Content_49 = {
    Text = [[
Harap perhatikan, ini juga berarti kamu mungkin tidak dapat menyelesaikan ekspedisi bersama kami. 
 Tim akan mengingat kontribusimu, tetapi nama kamu tidak akan muncul dalam catatan penjelajah pertama yang mencapai tujuan.]]
  },
  AvgDialog_19016_Content_5 = {
    Text = "Mengganggu di larut malam."
  },
  AvgDialog_19016_Content_50 = {
    Text = "Bertrand, jangan selalu bersikap dingin seperti itu. Dia sudah cukup baik mau bersusah payah pergi ke tempat yang sedingin itu bersama kita, bukan?"
  },
  AvgDialog_19016_Content_51 = {
    Text = [[
...Sementara itu, dalam kondisi iklim ekstrem, kemungkinan kehilangan nyawa tidak akan pernah menjadi nol. 
Jika kamu mengonfirmasi, maka kamu akan menjadi bagian dari tim eksplorasi.]]
  },
  AvgDialog_19016_Content_52 = {
    Text = "Hmm, aku sudah mengetahui semuanya."
  },
  AvgDialog_19016_Content_53 = {
    Text = "Itu kamarmu. Selama pelatihan, kamu harus bangun pukul 6 setiap pagi untuk latihan pagi. Jangan terlambat."
  },
  AvgDialog_19016_Content_55 = {
    Text = "Ah, sudah lama tidak ada cuaca secerah ini! Kalian lihat, kita bisa melihat puncak gunung di kejauhan dengan jelas!"
  },
  AvgDialog_19016_Content_56 = {
    Text = [[
Cuaca lebih buruk dari yang diperkirakan, dan kemajuan beberapa hari terakhir tidak sesuai harapan. 
 Kita harus memanfaatkan hari cerah yang langka ini untuk maju secepat mungkin.]]
  },
  AvgDialog_19016_Content_57 = {
    Text = "Dan kamu, sebagai dokter, jangan sampai jatuh sakit sendiri sehingga malah harus diurus oleh orang lain."
  },
  AvgDialog_19016_Content_58 = {
    Text = "Bertrand, aku berbicara padamu. Cuaca cerah adalah kabar baik. Bisakah kamu memperhatikan perasaan semua orang?"
  },
  AvgDialog_19016_Content_59 = {
    Text = [[
...Aku berbeda dari dirimu, seorang gadis bangsawan yang mencari tantangan pribadi. Prajurit memiliki kewajiban sebagai prajurit.
Sebelum mencapai puncak tertinggi itu, aku tidak akan menoleh ke belakang.]]
  },
  AvgDialog_19016_Content_6 = {
    Text = "Kuum berbalik dengan cepat, mencakar tanah, punggungnya menegang, dan mengeluarkan geraman rendah yang mengancam."
  },
  AvgDialog_19016_Content_60 = {
    Text = [[
Cecili, aku baik-baik saja. 
Kolonel Bertrand benar, kita harus segera bergerak.]]
  },
  AvgDialog_19016_Content_62 = {
    Text = "Kalian meninggalkan sebagian beban, memacu anjing salju dan kuda poni untuk maju dengan efisiensi maksimal."
  },
  AvgDialog_19016_Content_63 = {
    Text = "Rasa gelisah di dalam hati mulai bergejolak, kau mengeluarkan jam saku dari balik pakaianmu yang bertumpuk-tumpuk, berdoa dengan khidmat."
  },
  AvgDialog_19016_Content_64 = {
    Text = "Kamu melihat jam saku lagi. Apakah itu istimewa?"
  },
  AvgDialog_19016_Content_65 = {
    Text = [[
Hmm, aku membelinya dari toko antik yang aneh. 
Aku menyimpan foto putriku dan rambut pertamanya di dalamnya, dan setiap kali melihatnya, aku akan teringat padanya.]]
  },
  AvgDialog_19016_Content_66 = {
    Text = "Wow, kamu pasti memiliki putri yang sangat menggemaskan, sungguh membangkitkan rasa iri."
  },
  AvgDialog_19016_Content_67 = {
    Text = "Ah, aku juga ingin punya anak, itu akan sangat indah. Berapa usianya sekarang?"
  },
  AvgDialog_19016_Content_68 = {
    Text = "...Dia meninggal dunia saat berusia 8 tahun."
  },
  AvgDialog_19016_Content_69 = {
    Text = "Maaf, aku tidak tahu…"
  },
  AvgDialog_19016_Content_7 = {Text = "Ibu……"},
  AvgDialog_19016_Content_70 = {
    Text = "Tidak apa-apa."
  },
  AvgDialog_19016_Content_71 = {
    Text = "Ngomong-ngomong, apa alasanmu bergabung dengan tim penjelajah ini?"
  },
  AvgDialog_19016_Content_72 = {
    Text = "Ah, karena aku pernah mendengar sebuah legenda!"
  },
  AvgDialog_19016_Content_73 = {Text = "Legenda?"},
  AvgDialog_19016_Content_74 = {
    Text = "Di Gunung Salju Elworth, tersembunyi sebuah gereja yang sangat kuat. Orang-orang yang bergabung dengan gereja itu akan menerima <Yellow:Berkat>."
  },
  AvgDialog_19016_Content_75 = {
    Text = "Ada yang mengatakan bahwa Berkat itu dapat membuat orang mati kembali ke dunia."
  },
  AvgDialog_19016_Content_76 = {
    Text = "Elworth jarang dihuni manusia, sebagian besar dataran salju merupakan wilayah yang belum pernah dijamah oleh jejak manusia…"
  },
  AvgDialog_19016_Content_77 = {
    Text = "Saya justru merasa ini lebih nyata. Coba pikirkan, jika bukan karena kekuatan yang melampaui dunia fana dan mengubah hidup dan mati, bagaimana mungkin gereja bisa didirikan di tempat seperti ini?"
  },
  AvgDialog_19016_Content_79 = {
    Text = "Maaf, apakah aku terlalu bersemangat? \n …… Maaf, aku tidak memperhatikan perasaanmu ……"
  },
  AvgDialog_19016_Content_8 = {
    Text = "Dengar-dengar ada perubahan situasi, aku buru-buru datang. Lily dan hewan peliharaan kita tidak merepotkan Nyonya, kan?"
  },
  AvgDialog_19016_Content_80 = {
    Text = "Jika gereja itu ada, aku akan berdoa untukmu…"
  },
  AvgDialog_19016_Content_81 = {
    Text = "Berdoa agar putrimu kembali ke sisimu."
  },
  AvgDialog_19016_Content_83 = {
    Text = [[
Longsoran salju terjadi dalam sekejap.
Sebelum semua orang menyadarinya, bumi berguncang hebat, dan dunia tenggelam dalam putih mutlak yang menakutkan.]]
  },
  AvgDialog_19016_Content_84 = {
    Text = "Entah berapa lama telah berlalu, dingin dan rasa sakit di seluruh tubuh membuatmu bangun."
  },
  AvgDialog_19016_Content_85 = {
    Text = [[
Penglihatan kabur. Telapak tangan mengalami kelumpuhan. 
Kaki tidak bisa digerakkan.]]
  },
  AvgDialog_19016_Content_86 = {
    Text = "Di ujung pandangan, di bawah tumpukan salju, terlihat setengah lengan yang pucat."
  },
  AvgDialog_19016_Content_87 = {
    Text = [[
Kamu tidak tahu berapa lama waktu yang dibutuhkan untuk bisa bangkit dengan susah payah. 
 Kamu terhuyung-huyung mendekati orang itu, dan dengan susah payah menarik tubuh yang dingin dan kaku keluar dari tumpukan salju.]]
  },
  AvgDialog_19016_Content_88 = {Text = "Ini…"},
  AvgDialog_19016_Content_89 = {
    Text = "Dari pelukan dingin Cecily, jatuh sebuah paket dari kertas minyak. Kamu membukanya dengan lembut, di dalamnya ada peta yang sudah ditandai, sebuah foto hitam-putih, dan sehelai rambut keemasan muda."
  },
  AvgDialog_19016_Content_9 = {
    Text = "Wanita yang dipanggil Lily sebagai ibu masuk melalui pintu, langsung menghampiri Lily, memeluk tubuh mungilnya dengan lembut, dan menyentuh kepalanya dengan penuh kasih sayang."
  },
  AvgDialog_19016_Content_90 = {
    Text = [[
Di foto terlihat Cecily dan seorang pria berambut terang. 
Di bagian belakang foto tertulis "Kamu akan kembali".]]
  },
  AvgDialog_19016_Content_91 = {
    Text = "Ternyata kau juga... kehilangan seseorang yang penting, ya."
  },
  AvgDialog_19016_Content_92 = {
    Text = "Kamu memeriksa peta. Jika longsoran salju tidak membawa kalian terlalu jauh dari posisi awal, maka lokasi yang ditandai berada dalam jarak kurang dari setengah hari perjalanan kaki dari sini."
  },
  AvgDialog_19016_Content_93 = {
    Text = "Kuda poni yang menyertai sudah menghilang, makanan kering yang kamu bawa tidak cukup untuk bertahan sampai turun gunung."
  },
  AvgDialog_19016_Content_94 = {
    Text = "...Tidak ada alasan untuk ragu, sejak awal kamu tidak pernah berniat untuk kembali hidup-hidup."
  },
  AvgDialog_19016_Content_98 = {
    Text = "Kamu menyeret tubuh Cecilia yang sudah dingin dengan tali pendakian, berjalan terseok-seok di salju selama waktu yang lama."
  },
  AvgDialog_19016_Content_99 = {
    Text = "Untungnya, kamu melewati sebuah danau es yang membantu menentukan koordinatmu."
  },
  AvgDialog_19017_Content_1 = {
    Text = "Kembali ke titik awal"
  },
  AvgDialog_19017_Content_10 = {
    Text = "Penjaga… saya……"
  },
  AvgDialog_19017_Content_11 = {
    Text = "Kami adalah teman, juga mitra. Segala sesuatu yang berhubungan denganmu sangatlah penting."
  },
  AvgDialog_19017_Content_12 = {
    Text = "Terima kasih... tunggu aku kembali."
  },
  AvgDialog_19017_Content_13 = {
    Text = [[
Kamu sudah kembali. 
 Jika bertemu lawan yang sulit, segera tarik diri. Kendalikan dampaknya. Aku sudah memberitahumu tentang ini sebelumnya, kan?]]
  },
  AvgDialog_19017_Content_14 = {
    Text = [[
Herbert melemparkan sebuah koran di atas meja. 
 Berita utama tertulis "Kecelakaan Kereta Bawah Tanah Londinium, Diduga Diserang oleh Organisasi Misterius".]]
  },
  AvgDialog_19017_Content_16 = {
    Text = "Helot berdiri tegak di depan meja Herbert, tanpa mengucapkan sepatah kata pun, seperti patung yang sunyi."
  },
  AvgDialog_19017_Content_17 = {
    Text = "Masih berdiri di sana? Menunggu aku membawakanmu scone dan menuangkan dua cangkir teh hitam?"
  },
  AvgDialog_19017_Content_18 = {
    Text = "Arsip, berikan padaku."
  },
  AvgDialog_19017_Content_19 = {Text = "…Arsip?"},
  AvgDialog_19017_Content_2 = {
    Text = [[
Ramona, apakah kamu baik-baik saja?
Sejak kembali dari Wanita narsis, kamu terlihat gelisah.]]
  },
  AvgDialog_19017_Content_20 = {
    Text = [[
Wanita itu, Dafude'er. 
 Dia bilang akan mengirimkan arsip.]]
  },
  AvgDialog_19017_Content_21 = {
    Text = "Herbert sejenak menunjukkan ekspresi seperti menyadari sesuatu, lalu segera kembali ke penampilan biasa."
  },
  AvgDialog_19017_Content_22 = {
    Text = "Astaga, kamu juga tahu, ada terlalu banyak surat dari berbagai jurnal universitas yang dikirimkan kepadaku, semuanya menumpuk di kotak pos di depan pintu."
  },
  AvgDialog_19017_Content_23 = {
    Text = "Saya sebelumnya sudah membersihkan banyak, tidak tahu apakah masih ada atau tidak…"
  },
  AvgDialog_19017_Content_24 = {
    Text = "Helot memindai sekeliling, dengan mata yang cepat dan cekatan menarik dokumen berwarna ungu muda itu dari bawah koran yang tadi."
  },
  AvgDialog_19017_Content_25 = {
    Text = "Dia membaca dengan kecepatan luar biasa, sepuluh baris dalam sekali pandang, lalu meletakkan dokumen di depan Herbert."
  },
  AvgDialog_19017_Content_26 = {
    Text = "Apa maksud dari konten ini?"
  },
  AvgDialog_19017_Content_27 = {
    Text = [[
Herbert menerima dokumen itu, dengan cepat membaca sekilas lalu meletakkannya di atas meja. 
 Seolah-olah dia sudah hafal isi di dalamnya.]]
  },
  AvgDialog_19017_Content_28 = {
    Text = "<Yellow:Gagal> apa artinya?"
  },
  AvgDialog_19017_Content_29 = {
    Text = "<Blue:Albino> memberi tahu saya, Para pematung kehilangan kekuatan pertempuran dari dua kelompok, Rogers dan Francis, jadi mereka mengirim saya untuk membantu Anda."
  },
  AvgDialog_19017_Content_3 = {
    Text = "Ah, maaf... Saya seharusnya lebih fokus pada acara yang sedang berlangsung..."
  },
  AvgDialog_19017_Content_30 = {
    Text = "Jadi, sebenarnya, apakah aku sudah ditinggalkan?"
  },
  AvgDialog_19017_Content_31 = {
    Text = "Ini adalah cerita yang cukup panjang, dan juga ada kaitannya dengan Francis."
  },
  AvgDialog_19017_Content_32 = {
    Text = "Kamu tahu, \"<Yellow:Proyek Penciptaan Dewa>\" sangat bergantung pada <Yellow:Kekuatan Kembar>.\nKarena Lily dibangunkan secara tidak normal sebelumnya, mereka tidak pernah bisa menciptakan sisi lain dari dirimu…"
  },
  AvgDialog_19017_Content_33 = {
    Text = "Saya tidak tertarik dengan penjelasan!"
  },
  AvgDialog_19017_Content_34 = {
    Text = [[
<BigShake:Jawab aku!>
Apakah aku sudah dibuang?!]]
  },
  AvgDialog_19017_Content_35 = {
    Text = "Dari hasilnya memang begitu, tapi…"
  },
  AvgDialog_19017_Content_36 = {
    Text = "Kenapa? Kenapa? Aku ingin bertemu Nyonya!"
  },
  AvgDialog_19017_Content_37 = {
    Text = "Jangan bermimpi, masih menganggap dirimu putri angkat Penguasa yang terhormat?"
  },
  AvgDialog_19017_Content_38 = {
    Text = "Darah yang kotor, pada akhirnya hanya bisa membesarkan <Blue:pengkhianat> sepertimu."
  },
  AvgDialog_19017_Content_39 = {
    Text = "Saya tidak melakukan kejahatan apapun, saya tidak mengkhianati Nyonya!"
  },
  AvgDialog_19017_Content_4 = {
    Text = "Hanya saja, hal ini sudah menggangguku untuk waktu yang lama, aku... aku tidak bisa berhenti memikirkannya."
  },
  AvgDialog_19017_Content_40 = {
    Text = "Apakah kamu memberi makanan kepada kusir kuda yang kotor itu? Siapa yang memberimu izin?"
  },
  AvgDialog_19017_Content_41 = {
    Text = "<Small:Itu… ayah kandungku…>"
  },
  AvgDialog_19017_Content_42 = {
    Text = "Benar-benar tidak tahu diri. Penguasa bersedia mengangkatmu sebagai anak angkat, namun kamu mengabaikan rasa terima kasih dan hanya memikirkan kerabat darahmu yang telah melakukan kejahatan besar."
  },
  AvgDialog_19017_Content_43 = {
    Text = [[
Nyonya Zhang berkata, selama hidupnya, jangan harap bisa melepaskan rantai ini. 
 Membiarkanmu tetap hidup adalah bentuk belas kasihan khusus yang diberikan karena hubungan ibu dan anak.]]
  },
  AvgDialog_19017_Content_46 = {
    Text = "Penguasa yang dibenci."
  },
  AvgDialog_19017_Content_47 = {
    Text = "Dengan kekuasaan di tangan, memperlakukan orang lain sebagai mainan, memanggil mereka datang dan menyuruh mereka pergi sesuka hati…"
  },
  AvgDialog_19017_Content_48 = {
    Text = "Diberikan dengan penuh kasih seperti harta berharga, namun dibuang seperti sampah tanpa ampun."
  },
  AvgDialog_19017_Content_49 = {
    Text = "Aku akan pergi menemui <Blue:Evie>."
  },
  AvgDialog_19017_Content_5 = {
    Text = "Kalau begitu, selesaikanlah sekarang."
  },
  AvgDialog_19017_Content_50 = {
    Text = "Perilaku ini tidak memiliki arti."
  },
  AvgDialog_19017_Content_51 = {
    Text = "Kalau begitu, aku akan menemukan <Yellow:gadis dengan asal yang sama> dan membawanya kembali ke gereja!"
  },
  AvgDialog_19017_Content_52 = {
    Text = "Sebelum itu, aku harus bertemu dengan Eve terlebih dahulu."
  },
  AvgDialog_19017_Content_53 = {
    Text = [[
Karena kamu sangat ingin melakukannya, aku juga tidak perlu menghentikanmu. 
Ini adalah alamat cabang Gereja Penerang Kuil di Londinium, kamu bisa menemukan Eve di sana.]]
  },
  AvgDialog_19017_Content_54 = {
    Text = "Adapun bagaimana dia akan merespons kamu, aku tidak bisa menjamin."
  },
  AvgDialog_19017_Content_55 = {
    Text = "Tidak perlu. Saya akan menanyakan sendiri dengan jelas."
  },
  AvgDialog_19017_Content_56 = {
    Text = "Pada saat Helot berbalik untuk pergi, dia merasakan sesuatu yang aneh."
  },
  AvgDialog_19017_Content_57 = {
    Text = "Tanah mulai menjadi lembut dan runtuh, langkah yang diambil juga mulai goyah."
  },
  AvgDialog_19017_Content_58 = {
    Text = "Dia menundukkan kepalanya."
  },
  AvgDialog_19017_Content_59 = {
    Text = [[
Yang runtuh bukanlah tanah, melainkan dirinya sendiri. 
Bagian yang seharusnya menjadi kedua kakinya, seperti tunas muda yang menembus tanah, retak dan mengeluarkan bola-bola lengket yang lembut.]]
  },
  AvgDialog_19017_Content_6 = {
    Text = "Tugas yang dapat dilakukan——"
  },
  AvgDialog_19017_Content_60 = {
    Text = "<Shake:You... why... cut... the chain...>"
  },
  AvgDialog_19017_Content_61 = {
    Text = "Ucapan terputus oleh perubahan aneh, ekor suara yang tak jatuh berubah menjadi raungan ilusi."
  },
  AvgDialog_19017_Content_62 = {
    Text = "Tubuh dengan cepat membengkak dan berubah bentuk, tak terhitung jumlahnya tonjolan daging hitam yang aneh saling berdesakan untuk muncul dari kulit pucat."
  },
  AvgDialog_19017_Content_63 = {
    Text = "Cairan nanah yang beraroma amis memancar keluar dari luka terbuka, menarik benang kental."
  },
  AvgDialog_19017_Content_64 = {
    Text = "Kamu ingin membawa Lily untuk bertemu Eve, kan?"
  },
  AvgDialog_19017_Content_65 = {
    Text = "Namun, maaf, <Yellow:Anak Kembar Suci> yang baru sudah dalam tahap pengembangan."
  },
  AvgDialog_19017_Content_66 = {
    Text = "Meskipun kamu bertemu dengan Eve, hasil akhirnya tidak akan berubah."
  },
  AvgDialog_19017_Content_67 = {
    Text = "Jika sudah begitu, sebaiknya kamu memaksimalkan sisa cahaya dan panas yang ada."
  },
  AvgDialog_19017_Content_68 = {
    Text = "Dengan bentuk yang terdistorsi ini —— gunakan instingmu —— untuk menemukan pasanganmu."
  },
  AvgDialog_19017_Content_7 = {
    Text = "Kembali ke Mythag sebentar, tidak akan memakan banyak waktu."
  },
  AvgDialog_19017_Content_70 = {
    Text = "Pada saat yang sama, Mythag Kolam Hitam"
  },
  AvgDialog_19017_Content_71 = {
    Text = [[
Tidak ada seorang pun di tepi Kolam Hitam. 
 Ramona perlahan berjalan ke tepi kolam, menatap bayangan di dalamnya.]]
  },
  AvgDialog_19017_Content_72 = {
    Text = "Riak air yang bergejolak perlahan-lahan kembali tenang, menampakkan sosok seorang wanita dengan ekspresi wajah yang datar."
  },
  AvgDialog_19017_Content_73 = {
    Text = "Wajah itu hampir identik dengan Ramona, namun hanya dengan pengamatan yang lebih teliti, baru bisa diperhatikan bahwa wajah wanita di kolam terlihat lebih dewasa."
  },
  AvgDialog_19017_Content_74 = {
    Text = "Apakah kamu tahu bahwa aku datang?"
  },
  AvgDialog_19017_Content_75 = {
    Text = "Saya memiliki beberapa pertanyaan yang ingin diajukan. \nIngin bertanya kepada……<Blue:Tawil>."
  },
  AvgDialog_19017_Content_8 = {
    Text = [[
Dengan Lotan dalam operasi ini, setidaknya kamu tidak perlu khawatir tentang keselamatanku. 
Betul kan, Lotan?]]
  },
  AvgDialog_19017_Content_9 = {
    Text = [[
Hmph, itu sudah pasti. 
Setelah kamu selesai dengan urusanmu, cepatlah kembali. Anak kecil ini bahkan tidak berani bicara kepadaku.]]
  },
  AvgDialog_19018_Content_1 = {
    Text = "Sudah lama tidak berlatih, izinkan aku menggerakkan otot-ototku!"
  },
  AvgDialog_19019_Content_1 = {
    Text = "Selamat datang di Kota Rai"
  },
  AvgDialog_19019_Content_10 = {
    Text = "<Blue:Lily>…"
  },
  AvgDialog_19019_Content_11 = {
    Text = "Apakah Lily suka ini? Maukah kamu menyentuhnya?"
  },
  AvgDialog_19019_Content_12 = {Text = "Ya!"},
  AvgDialog_19019_Content_13 = {
    Text = [[
Lily dengan hati-hati menyentuh ujung Kunci.
Entah apakah ini ilusi atau bukan, Kunci perak tampak berkilauan sesaat saat disentuh.]]
  },
  AvgDialog_19019_Content_14 = {Text = "Wah..."},
  AvgDialog_19019_Content_15 = {
    Text = [[
Lily tiba-tiba memelukmu erat. 
 Hatimu terasa lembut, dan tanpa sadar kamu mengusap kepalanya dengan lembut.]]
  },
  AvgDialog_19019_Content_16 = {
    Text = "Ramona melihatmu, sepertinya ingin mengatakan sesuatu."
  },
  AvgDialog_19019_Content_17 = {
    Text = "Ada apa, Ramona?"
  },
  AvgDialog_19019_Content_18 = {
    Text = "Meskipun aku tidak ingin merusak ketenangan sesaat ini, tetapi—\nTadi malam Anjing Neraka beraksi, dan kali ini ada seorang saksi."
  },
  AvgDialog_19019_Content_19 = {
    Text = "Kamu dan Ramona bergegas menuju pondok tempat kejadian."
  },
  AvgDialog_19019_Content_2 = {
    Text = "<Gray:Saya seperti bermimpi<Yellow:sesuatu>…kepala terasa pusing……>"
  },
  AvgDialog_19019_Content_20 = {
    Text = [[
Sebelum melangkah masuk, bau amis darah yang menyengat langsung menyeruak ke dalam rongga hidung kalian tanpa ampun. 
 Di tanah tersebar bercak-bercak darah yang kotor dan berbau busuk, bekas darah yang setengah mengering memperlihatkan warna merah gelap yang aneh.]]
  },
  AvgDialog_19019_Content_21 = {
    Text = "Puluhan unggas mati tergeletak di tanah, posisi tenggorokan mengarah ke langit menunjukkan penderitaan menjelang ajal."
  },
  AvgDialog_19019_Content_22 = {
    Text = "Saya pikir, sebagai Anjing neraka dari Clades, seharusnya tidak akan menjadikan beberapa ekor ayam sebagai target, bukan?"
  },
  AvgDialog_19019_Content_23 = {
    Text = "Anjing neraka? Anjing liar di pinggir jalan lebih beradab daripada itu."
  },
  AvgDialog_19019_Content_24 = {
    Text = "Lagi, lagi... Ya Tuhan, Lisa kecilku... jangan sampai terjadi apa-apa padamu..."
  },
  AvgDialog_19019_Content_25 = {
    Text = "%player%, lihat ke sini."
  },
  AvgDialog_19019_Content_26 = {
    Text = "Sisa-sisa ayam dipenuhi bekas cakaran, bulu-bulu berwarna-warni berserakan dan menutupi beberapa goresan cakar yang dalam. Bagian leher terputus oleh kekuatan besar, dengan ujung yang tidak rata, memperlihatkan fragmen tulang yang bergesekan."
  },
  AvgDialog_19019_Content_27 = {
    Text = "Gigitan ini… sepertinya bukan dari hewan sejenis anjing."
  },
  AvgDialog_19019_Content_28 = {
    Text = "Gigi seri rata, gigi taring juga tidak tajam — meskipun enggan mengakuinya, tetapi, ini memang sangat mirip dengan <Blue:bekas gigitan manusia>."
  },
  AvgDialog_19019_Content_29 = {
    Text = [[
Ramona berbalik kepada wanita penduduk desa di sisinya. 
Menurut pengenalan, dia telah menjanda selama bertahun-tahun di kota kecil ini, hanya memiliki putri tunggal <Blue:Lisa> di sisinya.]]
  },
  AvgDialog_19019_Content_3 = {
    Text = "<Gray:Tapi kenapa, dada juga terasa begitu berat…>"
  },
  AvgDialog_19019_Content_30 = {
    Text = "Rambut wanita itu kusut seperti rumput liar, kedua tangannya digabungkan dengan penuh kegilaan sambil berdoa pelan-pelan, bibir pucatnya bergetar lemah."
  },
  AvgDialog_19019_Content_31 = {
    Text = [[
Nyonya, Nyonya? 
 Jangan takut, kami akan membantu Anda. Bisakah Anda menjelaskan secara rinci apa yang terjadi?]]
  },
  AvgDialog_19019_Content_32 = {
    Text = "Ini bukan pertama kalinya hal seperti ini terjadi. Awalnya hanya beberapa ekor ayam betina, tapi sekarang, sekarang…"
  },
  AvgDialog_19019_Content_33 = {
    Text = [[
Pagar tidak bisa menahannya, tidak bisa menahan! Aku melihatnya, aku benar-benar melihatnya sendiri! 
Malam kemarin itu bukan seekor rubah, melainkan monster yang mengerikan!]]
  },
  AvgDialog_19019_Content_34 = {
    Text = [[
Suara janda itu menjadi sangat tajam. 
Dia berteriak dengan suara serak, gemetar saat memeluk erat kedua lengannya dengan sepuluh jarinya.]]
  },
  AvgDialog_19019_Content_35 = {
    Text = "Apa yang perlu ditakuti, itu hanya seekor binatang buas!"
  },
  AvgDialog_19019_Content_36 = {
    Text = "Janda itu seolah-olah tidak mendengar bentakan Lotan, tenggelam dalam kenangan yang menyakitkan."
  },
  AvgDialog_19019_Content_37 = {
    Text = "Itu bukan binatang buas, bukan!"
  },
  AvgDialog_19019_Content_38 = {
    Text = "Ketika itu mendekatiku, aku melihatnya, aku melihatnya dengan sangat jelas——"
  },
  AvgDialog_19019_Content_39 = {
    Text = "Dia memiliki lengan manusia, dan tidak ada apa pun di wajahnya. Itu adalah <Yellow:Anjing neraka>! Dia akan menyeretku ke Neraka!"
  },
  AvgDialog_19019_Content_4 = {
    Text = "Membuka kelopak mata yang terasa berat, tiba-tiba sepasang mata jernih dengan warna pucat langsung memenuhi pandangan."
  },
  AvgDialog_19019_Content_40 = {
    Text = [[
Janda itu mundur dengan panik, tiba-tiba menabrak sebuah sosok kecil. 
 Wajahnya langsung berubah.]]
  },
  AvgDialog_19019_Content_41 = {
    Text = "Sialan! Lagi-lagi kau! Pergi! Pergi!"
  },
  AvgDialog_19019_Content_42 = {
    Text = "Kamu sudah membunuh Lisa, apa lagi yang ingin kamu lakukan! Pergi dari sini!"
  },
  AvgDialog_19019_Content_43 = {
    Text = "Ekspresi janda itu sangat mengerikan, seolah-olah dia menyimpan kebencian yang luar biasa terhadap Lily, hingga ingin segera menyerang dan merobeknya menjadi empat bagian."
  },
  AvgDialog_19019_Content_44 = {
    Text = [[
Kamu melangkah setengah langkah ke depan, menutupi Lily di belakangmu. 
 Ramona dengan kompak membentuk penghalang bersamamu.]]
  },
  AvgDialog_19019_Content_45 = {
    Text = [[
Bu, mohon tenang sejenak. 
 Kami belum bisa memastikan kondisi Lisa, namun ada kemungkinan dia masih hidup.]]
  },
  AvgDialog_19019_Content_46 = {
    Text = "Apa kau pikir aku tidak ingin dia hidup? Apa kau pikir aku menginginkan kematiannya! Kemarin, saat aku melihat Anjing neraka, aku mendengar suara tangisnya!"
  },
  AvgDialog_19019_Content_47 = {
    Text = "Pasti monster itu! Pasti dia! Dia yang memakan Lisa-ku, Lisa-ku yang malang, putriku yang malang—"
  },
  AvgDialog_19019_Content_48 = {
    Text = "Kalau bukan karena penyihir ini, bagaimana mungkin putriku bisa pergi begitu jauh dari rumah? Bagaimana mungkin dia bisa menjadi sasaran anjing neraka? Bagaimana mungkin dia bisa mengalami nasib buruk!"
  },
  AvgDialog_19019_Content_49 = {
    Text = "Anakku, anakku—ibu meminta maaf padamu—maafkan ibu—"
  },
  AvgDialog_19019_Content_5 = {
    Text = "Kakak besar {Male=Tuan Penjaga Rahasia,Female=Nona Penjaga Rahasia}, selamat pagi…"
  },
  AvgDialog_19019_Content_50 = {
    Text = "Ibu janda memeluk dadanya dengan kedua tangan, menangis sambil bergetar, seolah-olah jiwa yang lemah sudah tidak bisa lagi menopang tubuhnya, seluruh tubuhnya terombang-ambing."
  },
  AvgDialog_19019_Content_51 = {
    Text = "Ramona menahan napas dan dengan lembut menopang wanita itu."
  },
  AvgDialog_19019_Content_52 = {
    Text = "Jangan berpikir seperti itu, Nyonya. Putri Anda mungkin hanya pergi bermain ke rumah temannya, siapa tahu besok dia sudah —"
  },
  AvgDialog_19019_Content_53 = {
    Text = "<Yellow:Lisa tidak akan kembali.>"
  },
  AvgDialog_19019_Content_54 = {
    Text = "Suara gadis yang polos memotong kata-kata yang belum sempat kamu ucapkan. Saat kamu menoleh, wajah Lily menampilkan semacam ekspresi yang tidak bisa kamu pahami, seperti ragu-ragu, atau mungkin acuh tak acuh."
  },
  AvgDialog_19019_Content_55 = {
    Text = "Kamu... apa yang kamu katakan?"
  },
  AvgDialog_19019_Content_56 = {
    Text = "Lisa berkata… dia tidak akan kembali lagi."
  },
  AvgDialog_19019_Content_57 = {
    Text = "Tidak mungkin, sama sekali tidak mungkin! \n Lisa adalah anak yang sangat mencintai rumahnya, dia tidak akan mengatakan hal seperti itu…"
  },
  AvgDialog_19019_Content_58 = {
    Text = "Lily, di mana kamu melihat Lisa?"
  },
  AvgDialog_19019_Content_59 = {
    Text = "Lily hanya menggelengkan kepalanya."
  },
  AvgDialog_19019_Content_6 = {
    Text = [[
<Shake: Uwaa?!>
Ramona, apa yang terjadi padanya?]]
  },
  AvgDialog_19019_Content_60 = {
    Text = [[
Tidak, kau benar-benar berbicara omong kosong, iblis, penyihir! 
 Lisa begitu baik padamu, tapi kau masih mengutuknya dan memfitnahnya!]]
  },
  AvgDialog_19019_Content_61 = {
    Text = "\"Dengan suara 'plak', janda itu menampar Lily.\""
  },
  AvgDialog_19019_Content_62 = {
    Text = "Kamu segera maju dan memisahkan kedua orang itu."
  },
  AvgDialog_19019_Content_63 = {
    Text = "Lily menutupi wajahnya, mundur dua langkah, dan bersembunyi di belakangmu."
  },
  AvgDialog_19019_Content_64 = {
    Text = "Tidak ada bukti yang menunjukkan bahwa Lily terkait dengan masalah putrimu!"
  },
  AvgDialog_19019_Content_65 = {
    Text = "Ramona memberi isyarat dengan mata, mengisyaratkan agar kamu berhenti bicara."
  },
  AvgDialog_19019_Content_66 = {
    Text = "Kalian ini, jangan coba-coba mempermainkan Ibu Lisa!"
  },
  AvgDialog_19019_Content_67 = {
    Text = "Siapa kalian?"
  },
  AvgDialog_19019_Content_68 = {
    Text = "Nama saya Hank, dia John, dan kami semua adalah teman Lisa!"
  },
  AvgDialog_19019_Content_69 = {
    Text = "Pada hari itu, Lily pergi ke pinggiran kota bersama Lisa. Kami melihatnya dengan mata kepala kami sendiri!"
  },
  AvgDialog_19019_Content_7 = {
    Text = "Kami tidak bisa membangunkanmu, anak ini hanya ingin melihat apa yang terjadi… Tidak disangka dia malah tertidur di dadamu."
  },
  AvgDialog_19019_Content_70 = {
    Text = "Jangan banyak bicara, {Male=dia,Female=dia} pasti satu kelompok dengan iblis ini, beri {Male=dia,Female=dia} pelajaran!"
  },
  AvgDialog_19019_Content_71 = {
    Text = "Lindungi Ibu Lisa!"
  },
  AvgDialog_19019_Content_72 = {
    Text = "...Apakah kamu merasa bahwa kita selalu berkonflik dengan anak-anak?"
  },
  AvgDialog_19019_Content_8 = {
    Text = [[
Gadis itu bangkit dengan berat hati, pandangannya terus mengikuti dadamu. 
 Kamu menunduk dan melihat Kunci perak yang masih memancarkan cahaya perak terang meskipun dalam tidur nyenyak.]]
  },
  AvgDialog_19019_Content_9 = {
    Text = "Apa nama kamu?"
  },
  AvgDialog_19021_Content_1 = {
    Text = "Tersimpan di bawah tepi topi"
  },
  AvgDialog_19021_Content_10 = {
    Text = [[
Jadi, kau mencariku karena alasan yang sah dan masuk akal. 
Mengingat definisi toko kelontong ini, kau pasti ingin melakukan transaksi tertentu.]]
  },
  AvgDialog_19021_Content_11 = {
    Text = "Kamu tidak mengungkitnya saat itu, melainkan memutar jauh untuk menemuiku. Ini menunjukkan bahwa ada orang di tempat kejadian yang tidak ingin kamu dengarkan transaksi ini."
  },
  AvgDialog_19021_Content_12 = {
    Text = "Oleh karena itu, saya bisa menyimpulkan: kamu ingin mengetahui informasi terkait Helot dan Lily."
  },
  AvgDialog_19021_Content_13 = {
    Text = [[
Ya. Lebih tepatnya, apa hubungan antara Helot dan Lily? 
Apa yang dimaksud dengan <Yellow:"asal yang sama">? Apa konsepnya?]]
  },
  AvgDialog_19021_Content_14 = {
    Text = "Ini bukan masalah sebenarnya yang kamu hadapi."
  },
  AvgDialog_19021_Content_15 = {
    Text = "Apa yang sebenarnya ingin kau tanyakan adalah tentang kekuatan yang ada pada dirimu sendiri, kan……\nKamu sudah pernah melihat keberadaan dengan kekuatan <Yellow:\"sejenis\">, bukan?"
  },
  AvgDialog_19021_Content_16 = {
    Text = "<Gray: Apakah Ramona sudah tahu?! Memang, aku tidak bisa menyembunyikan perjanjian antara aku dan Mulia darinya…>"
  },
  AvgDialog_19021_Content_17 = {
    Text = "Ekspresi Ramona berubah drastis, namun Dafdale tetap tersenyum lembut, wajahnya penuh dengan perhitungan."
  },
  AvgDialog_19021_Content_18 = {
    Text = "Tidak perlu khawatir, aku tidak punya kebiasaan buruk untuk melapor. Di hadapan Lord Mulia Dexter, kamu masih bisa terus berpura-pura bahwa semuanya baik-baik saja."
  },
  AvgDialog_19021_Content_19 = {
    Text = [[
Tetapi sayangnya, aku tidak bisa memberitahumu jawabannya. 
 Dalam transaksi dengan Universitas Mythag, tertulis jelas di atas kertas: tidak boleh ikut campur dalam urusan sekolah.]]
  },
  AvgDialog_19021_Content_2 = {
    Text = "Kami sudah tiba."
  },
  AvgDialog_19021_Content_20 = {
    Text = [[
Satu-satunya saran yang bisa kuberikan padamu adalah: 
Jika kamu begitu penasaran, kenapa tidak bertanya langsung pada <Yellow:dia>?]]
  },
  AvgDialog_19021_Content_21 = {
    Text = "Ramona terkejut."
  },
  AvgDialog_19021_Content_22 = {
    Text = "Mungkin karena jawabannya terlalu sederhana, sehingga justru menjadi titik buta baginya. Dia tak pernah mempertimbangkan kemungkinan ini."
  },
  AvgDialog_19021_Content_23 = {
    Text = "Dia mengangkat ujung roknya, lalu membungkuk dengan sopan."
  },
  AvgDialog_19021_Content_24 = {
    Text = "Terima kasih atas bimbingannya, saya pamit undur diri."
  },
  AvgDialog_19021_Content_25 = {
    Text = "Hati-hati. Jalan untuk pergi tidak semudah yang kau kira."
  },
  AvgDialog_19021_Content_26 = {
    Text = "Namun……"
  },
  AvgDialog_19021_Content_27 = {
    Text = "Mungkin, ini juga sesuai dengan harapan kalian."
  },
  AvgDialog_19021_Content_3 = {
    Text = [[
Yang muncul di hadapan adalah ruangan yang diselimuti kabut ungu. 
 Sedikit terasa familiar, namun detailnya memiliki perbedaan halus dibandingkan dengan memori.]]
  },
  AvgDialog_19021_Content_4 = {
    Text = "Kamu menelusuri kembali memori, dengan cermat membedakan, dan akhirnya menyadari perbedaannya…"
  },
  AvgDialog_19021_Content_5 = {
    Text = "Barang-barang di sini..."
  },
  AvgDialog_19021_Content_6 = {
    Text = "Aduh, sepertinya ada tamu tak diundang."
  },
  AvgDialog_19021_Content_7 = {
    Text = "Saya dengan jelas telah memalsukan dokumen-dokumen tersebut. Karena Anda tidak menghapus jejaknya, saya percaya bahwa Anda mengizinkan saya untuk berkunjung."
  },
  AvgDialog_19021_Content_8 = {
    Text = [[
Kamu sangat cerdas, dan juga cukup rendah hati. 
Nah, gadis kecil, mengapa kamu datang ke sini?]]
  },
  AvgDialog_19021_Content_9 = {
    Text = [[
Tidak, lebih baik aku yang menebak kali ini... 
 Jika kamu benar-benar ingin melacakku secara diam-diam, kamu tidak akan sengaja meninggalkan tanda yang begitu mencolok.]]
  },
  AvgDialog_19025_Content_1 = {
    Text = "Kalian mengejar monster hitam itu sampai ia lenyap ke dalam kegelapan malam yang pekat, tanpa meninggalkan jejak."
  },
  AvgDialog_19025_Content_10 = {
    Text = "Herbert? Yang <Blue:Herbert·Rosenthal> itu? Mantan peneliti Mythag, yang melarikan diri setelah membunuh gurunya dan sekarang menjadi buronan ——"
  },
  AvgDialog_19025_Content_11 = {
    Text = "Benar, dan Para pematung didirikan sepenuhnya olehnya — semoga tangan dan kaki kalian masih tetap pada tempatnya."
  },
  AvgDialog_19025_Content_12 = {
    Text = [[
Dia tidak memberikan kami hambatan apa pun. 
Namun, sepertinya dia sedang mencari seorang gadis berusia delapan atau sembilan tahun.]]
  },
  AvgDialog_19025_Content_13 = {
    Text = "Apa lagi yang sedang terjadi… Mengerti, William akan mengatur penyelidik lain untuk melacak keberadaan Herbert. \nPrioritas utama kalian tetap \"Clades\"."
  },
  AvgDialog_19025_Content_14 = {
    Text = [[
Bagaimanapun, monster-monster Pelarutan ini telah membuktikan keberadaan "Clades".
Mereka tidak seperti kabut di Londinium atau orang gila di Universitas Mythag yang bisa ditemui di mana saja.]]
  },
  AvgDialog_19025_Content_15 = {
    Text = "Mengerti, tapi... saat ini kita memiliki masalah yang lebih mendesak."
  },
  AvgDialog_19025_Content_16 = {
    Text = "Apakah ada anomali lain yang muncul?!"
  },
  AvgDialog_19025_Content_17 = {
    Text = "Tidak terlalu mendesak — hanya masalah penginapan saja. \n Kalau bisa, aku tidak berniat menggunakan tumpukan salju sebagai selimut."
  },
  AvgDialog_19025_Content_18 = {
    Text = "<Italic:{Male=Kakak laki-laki, kakak perempuan,Female=Kakak perempuan},apakah kalian tamu yang datang dari tempat yang sangat jauh?>"
  },
  AvgDialog_19025_Content_19 = {
    Text = "Suara yang masih terdengar polos memutus pembicaraan kalian."
  },
  AvgDialog_19025_Content_2 = {
    Text = "Melarikan diri dengan panik, apakah ini masih bisa dianggap sebagai <Yellow:Anjing neraka>?"
  },
  AvgDialog_19025_Content_20 = {Text = "Siapa itu?"},
  AvgDialog_19025_Content_21 = {
    Text = "Salju yang menumpuk di dinding memantulkan cahaya bulan yang terang. Di tengahnya berdiri seorang gadis yang lebih putih daripada cahaya bulan itu sendiri."
  },
  AvgDialog_19025_Content_22 = {
    Text = [[
Jika tidak menemukan tempat tinggal, <Blue:Wanita narsis> bersedia meminjamkan kamar. 
 Tepat di depan di tikungan.]]
  },
  AvgDialog_19025_Content_23 = {
    Text = "Kamu memberi isyarat mata kepada Ramona, dan Ramona membalas dengan tatapan yang mengiyakan."
  },
  AvgDialog_19025_Content_24 = {
    Text = "Gaun putih, kartu rekam medis, masih muda. Inilah gadis yang sedang dilacak oleh Herbert. Mungkin ada petunjuk terkait penyelidikan pada dirinya."
  },
  AvgDialog_19025_Content_25 = {
    Text = [[
Ayo pergi, apa yang kalian tunggu? 
 Apakah kalian benar-benar suka tinggal di luar dan berteriak seperti serigala sepanjang malam?]]
  },
  AvgDialog_19025_Content_26 = {
    Text = "Jika kalian ingin makan angin dan tidur di bawah langit, aku selalu siap menemani. Namun, aku khawatir tubuh kalian yang lemah tidak akan kuat menahan kondisi seperti itu."
  },
  AvgDialog_19025_Content_27 = {
    Text = "Lotan menepuk bahu Ramona dari belakang. Ramona menunjukkan ekspresi seperti orang yang baru saja memakan seekor lalat, tetapi dia tidak mengatakan apa-apa."
  },
  AvgDialog_19025_Content_28 = {
    Text = "Wanita narsis… terdengar seperti orang kaya yang berbaik hati, kan?"
  },
  AvgDialog_19025_Content_3 = {
    Text = [[
Sepertinya ia melarikan diri setelah menyadari bahwa kita tidak takut padanya sama sekali. 
Mencari keuntungan dan menghindari bahaya adalah insting hewan, namun belum pernah terdengar bahwa Clades memiliki perilaku serupa.]]
  },
  AvgDialog_19025_Content_4 = {
    Text = "Dan, itu terluka."
  },
  AvgDialog_19025_Content_5 = {
    Text = "Memang, aku mencium bau darah."
  },
  AvgDialog_19025_Content_6 = {
    Text = "Komunikator berbunyi dengan lembut."
  },
  AvgDialog_19025_Content_7 = {
    Text = "Akhirnya semuanya pulih. Setelah misi ini selesai, aku harus meningkatkan komunikator."
  },
  AvgDialog_19025_Content_8 = {
    Text = "Boneka? Apa yang baru saja terjadi?"
  },
  AvgDialog_19025_Content_9 = {
    Text = [[
Gangguan komunikasi, keahlian umum <Blue:Herbert>. 
 Sepertinya kalian sudah bertemu dengannya, orang gila yang memelihara seekor kucing bermuka dua.]]
  },
  AvgDialog_19026_Content_1 = {
    Text = "Lord Mulia Dexter berkata, sebaiknya jangan menggugah Nyonya Narsis."
  },
  AvgDialog_19026_Content_2 = {
    Text = "Tidak apa-apa, dia tidak berniat jahat."
  },
  AvgDialog_19026_Content_3 = {
    Text = "Mungkin monster-monster di depan tidak berpikir begitu..."
  },
  AvgDialog_19028_Content_1 = {
    Text = "Lepaskan aku, lepaskan aku, orang dewasa menindas anak kecil——"
  },
  AvgDialog_19028_Content_10 = {
    Text = "Saat melakukan penyelidikan, yang harus digerakkan bukan hanya tangan, melainkan yang lebih penting adalah otak."
  },
  AvgDialog_19028_Content_11 = {
    Text = "Siapa yang memberimu izin untuk menyela?"
  },
  AvgDialog_19028_Content_12 = {
    Text = [[
Maaf, maaf. 
Boneka, tolong bersikap lebih sopan kepada gadis kecil kita.]]
  },
  AvgDialog_19028_Content_13 = {
    Text = "Boneka, Mulia Dexter?"
  },
  AvgDialog_19028_Content_14 = {
    Text = "Apakah Ramona ada?"
  },
  AvgDialog_19028_Content_15 = {
    Text = "Entah mengapa, nada suara Boneka yang biasanya tenang tampaknya tercemar oleh semacam kecemasan."
  },
  AvgDialog_19028_Content_16 = {
    Text = "Ya. Ada apa?"
  },
  AvgDialog_19028_Content_17 = {
    Text = "Saya baru saja mencari catatan komunikasi, apakah kamu pernah bertanya kepada Erica tentang seseorang?"
  },
  AvgDialog_19028_Content_18 = {
    Text = "Wanita, memperkenalkan diri sebagai \"Nyonya Narcissus\", terlihat berusia sekitar dua puluh delapan tahun, memiliki rambut panjang berwarna abu-abu asap, dan berprofesi dalam perdagangan antik."
  },
  AvgDialog_19028_Content_19 = {
    Text = "Benar, tetapi Erica mengatakan bahwa tidak ada data terkait yang ditemukan di dalam arsip."
  },
  AvgDialog_19028_Content_2 = {
    Text = "Pertama, kalian yang memulai serangan."
  },
  AvgDialog_19028_Content_20 = {
    Text = "Itu karena dalam catatan resmi, dia <Blue:tidak ada>."
  },
  AvgDialog_19028_Content_21 = {Text = "Tidak ada?"},
  AvgDialog_19028_Content_22 = {
    Text = "Maksudmu... dia bisa memalsukan data Mythag?"
  },
  AvgDialog_19028_Content_23 = {
    Text = [[
Bukan pemalsuan, hanya sebuah transaksi. 
 Mythag menghancurkan dokumen kertas yang terkait dengannya, dan dia memberikan informasi kepada kami.]]
  },
  AvgDialog_19028_Content_24 = {
    Text = "Dan kurangi kerusakan."
  },
  AvgDialog_19028_Content_25 = {
    Text = "Apa kamu merasa ini menarik? Kita berjuang mati-matian untuk menyimpan catatan yang terkikis oleh pelarutan, tetapi ada orang yang berharap informasi mereka tidak tersimpan di media apa pun."
  },
  AvgDialog_19028_Content_26 = {
    Text = "Ramona tersayang, apakah kamu bisa mendengarku? Apakah eksplorasi kalian berjalan dengan lancar? Jika ada yang membutuhkan bantuan, kamu bisa menghubungi Ayah kapan saja——"
  },
  AvgDialog_19028_Content_27 = {
    Text = "Jika kamu tidak punya urusan penting, lebih baik serahkan waktu komunikasi yang berharga ini kepada Boneka dan kembali ke acara pesta, Ayah."
  },
  AvgDialog_19028_Content_28 = {
    Text = [[
Begitu dingin, apakah ini yang disebut masa pemberontakan? Aku datang jauh-jauh untuk memberikan informasi kepada kalian. 
Lagipula, informasi terkait Narsis hanya tersimpan di sini, lho.]]
  },
  AvgDialog_19028_Content_29 = {
    Text = "Kamu bisa membayangkan Dexter mengangkat satu jari telunjuknya, dengan senyuman yang selalu penuh percaya diri dan provokatif, sambil mengetuk pelan pelipisnya sendiri."
  },
  AvgDialog_19028_Content_3 = {
    Text = "Kedua, berdasarkan usia yang tercatat secara resmi, saya juga masih di bawah umur."
  },
  AvgDialog_19028_Content_30 = {
    Text = "Jika otak Mulia Dexter belum kehilangan keandalannya karena alkohol, berikut ini adalah informasi yang dikuasai Mythag tentang Narsis."
  },
  AvgDialog_19028_Content_31 = {
    Text = "Wanita Narsis secara resmi adalah seorang pedagang barang antik, tetapi secara rahasia dia memiliki hubungan erat dengan <Yellow:Gereja Penerang Kuil>, <Yellow:Para Pematung>, dan berbagai organisasi ilegal lainnya."
  },
  AvgDialog_19028_Content_32 = {
    Text = "Dalam catatan tiga ratus tahun Universitas Mythag, setidaknya ada 20 kasus di baliknya yang melibatkan dorongan darinya… dengan cara yang tidak kita harapkan."
  },
  AvgDialog_19028_Content_33 = {
    Text = "Di setiap akhir acara, dia selalu muncul, lalu, <Yellow:memanen semua kepala para korban>."
  },
  AvgDialog_19028_Content_34 = {
    Text = "Tiga ratus tahun?"
  },
  AvgDialog_19028_Content_35 = {
    Text = "Benar, tiga ratus tahun. Meskipun dengan cara khusus berhasil menyembunyikan aura, tidak diragukan lagi bahwa Wanita Narsis adalah Pembangun."
  },
  AvgDialog_19028_Content_36 = {
    Text = "Cara khusus? Mungkin hanya bau busuk dari mayat."
  },
  AvgDialog_19028_Content_37 = {
    Text = "Jika dia adalah Pembangun yang mengancam, mengapa baik Mythag maupun Komite tidak memasukkannya ke dalam bidang pengelolaan?"
  },
  AvgDialog_19028_Content_38 = {
    Text = "Kamu bertanya pada poin yang krusial. Saat manusia masih sibuk memikirkan cara naik kereta listrik, Dafudeer sudah menguasai <Yellow:kemampuan untuk bergerak bebas di antara dimensi>."
  },
  AvgDialog_19028_Content_39 = {
    Text = "Beberapa kali Komite mengejarnya, namun semuanya berakhir dengan kegagalan."
  },
  AvgDialog_19028_Content_4 = {
    Text = [[
Anak itu seolah-olah terkejut oleh pernyataan tersebut, dia menjadi tenang, memandang Ramona dengan mata terbelalak. 
 Ramona menghela napas, melepaskan lengan anak itu, dan mendorongnya dengan lembut di punggung.]]
  },
  AvgDialog_19028_Content_40 = {
    Text = "Adapun kami, Universitas Mythag bukanlah penjara. Hubungan kami dengan Pembangun didasarkan pada kerja sama sukarela. Jika dia tidak bersedia, kami juga tidak memaksa."
  },
  AvgDialog_19028_Content_41 = {
    Text = "Memang benar. Jangan lihat beberapa orang yang setiap hari berteriak ingin melarikan diri, setelah meninggalkan Kolam Hitam di bawah Mythag, mereka tidak bisa pergi ke mana-mana."
  },
  AvgDialog_19028_Content_42 = {
    Text = "Mengikat anjing dengan rantai, lalu mengklaim bahwa anjing itu melakukannya secara sukarela."
  },
  AvgDialog_19028_Content_43 = {
    Text = "Aneh, kenapa aku mendengar sesuatu berteriak?"
  },
  AvgDialog_19028_Content_44 = {
    Text = "Kurang berbicara, kurang berbicara saja."
  },
  AvgDialog_19028_Content_45 = {
    Text = [[
Heh.
Bagaimanapun, dengan kehadiran Wanita Narsis dalam urusan ini, tampaknya kompleksitasnya melebihi perkiraan.]]
  },
  AvgDialog_19028_Content_46 = {
    Text = "Jika aku bisa lebih awal menyadari bahwa Wanita Narsis mungkin memiliki anomali, sekarang…"
  },
  AvgDialog_19028_Content_47 = {
    Text = [[
Jangan terlalu keras pada dirimu sendiri, kamu sudah sadar dan secara aktif meminta data dari Erica, kan? 
 Anak muda selalu perlu mengumpulkan pengalaman untuk bisa menguasai cara menilai situasi.]]
  },
  AvgDialog_19028_Content_48 = {
    Text = "Saran dari Mythag adalah: Jika tidak perlu, jangan terlalu banyak berurusan dengan orang ini."
  },
  AvgDialog_19028_Content_49 = {
    Text = "Meskipun kalian memiliki Penjaga, anggota ekspedisi terkuat di sekolah—Penjaga ada di barisan kalian, dalam hal pengalaman, kalian masih kalah satu langkah dari wanita licik dan berpengalaman itu."
  },
  AvgDialog_19028_Content_5 = {
    Text = "Baiklah, ayo pulang. Kita tidak akan mengganggu Ibu Lisa lagi."
  },
  AvgDialog_19028_Content_50 = {
    Text = [[
Kasus terkait Anjing Neraka tidak sesuai dengan gayanya. Pasti ada kekuatan lain di kota ini. 
 Begitu terjebak dalam situasi yang rumit, kalian bukan tandingannya.]]
  },
  AvgDialog_19028_Content_51 = {
    Text = "Aku mengerti."
  },
  AvgDialog_19028_Content_52 = {
    Text = "Kami akan bertindak dengan hati-hati."
  },
  AvgDialog_19028_Content_53 = {
    Text = "Hmph. Jangan harap aku akan berdiam diri."
  },
  AvgDialog_19028_Content_54 = {
    Text = "Boneka mengabaikan perkataan Lotan, suaranya sedikit menjauh. Sepertinya dia memalingkan kepala untuk berbicara dengan seseorang di sampingnya."
  },
  AvgDialog_19028_Content_55 = {
    Text = "Dekster, apakah kamu masih ingin berbicara dua kalimat dengan putrimu?"
  },
  AvgDialog_19028_Content_56 = {
    Text = [[
Tentu, tentu. 
Selain dalam pertempuran, kalian juga harus berhati-hati dalam menangani hubungan pribadi dengan Nyonya Dafudeer.]]
  },
  AvgDialog_19028_Content_57 = {
    Text = "Bagaimanapun juga, entah bagaimana, dia adalah seorang wanita dengan pesona dewasa yang cukup menarik."
  },
  AvgDialog_19028_Content_58 = {
    Text = "Cinta akan keindahan adalah hal yang dimiliki setiap orang. Aku juga sangat mengagumi sikap dan penampilannya, tetapi jangan sampai begitu saja tunduk pada pesonanya…"
  },
  AvgDialog_19028_Content_59 = {
    Text = "\"Dengan suara 'plok', Ramona memutus komunikasi.\""
  },
  AvgDialog_19028_Content_6 = {
    Text = "Dia berbalik kepada wanita yang masih menangis, melunakkan suaranya dan berkata:"
  },
  AvgDialog_19028_Content_60 = {
    Text = "Ayo pergi, selanjutnya kita harus berbicara dengan Lily."
  },
  AvgDialog_19028_Content_7 = {
    Text = "Anda juga kembali beristirahat dengan baik dan tenangkan diri. Kami akan bertanya kepada Lily secara jelas mengenai situasinya."
  },
  AvgDialog_19028_Content_8 = {
    Text = "Jika ada perkembangan baru, kami akan memberi tahu Anda segera."
  },
  AvgDialog_19028_Content_9 = {
    Text = "Kalian lebih baik memilihkan aku lawan yang memenuhi syarat. Anak-anak ini tidak sesuai dengan harapanku."
  },
  AvgDialog_19033_Content_1 = {
    Text = "Kabar baik, kabar buruk"
  },
  AvgDialog_19033_Content_10 = {
    Text = "<Small:Lily, dengarkan. Nyonya akan membantu Ibu... Lily, dengarkan...>"
  },
  AvgDialog_19033_Content_11 = {
    Text = "Gadis itu menahan napas, berjongkok di antara semak-semak suram, menghindari kejaran seorang wanita yang ganas."
  },
  AvgDialog_19033_Content_12 = {
    Text = "Semak-semak tiba-tiba mengeluarkan suara gemerisik yang pelan."
  },
  AvgDialog_19033_Content_13 = {Text = "Keluar!"},
  AvgDialog_19033_Content_15 = {
    Text = "Setelah keheningan yang menyesakkan, sebuah sosok perlahan melangkah keluar dari semak-semak."
  },
  AvgDialog_19033_Content_17 = {
    Text = "...Lupakan saja."
  },
  AvgDialog_19033_Content_18 = {
    Text = "Tidak ada hubungannya denganmu… teruslah melarikan diri."
  },
  AvgDialog_19033_Content_19 = {
    Text = "Wanita itu melambaikan tangannya dengan tegas, memberi isyarat kepada monster untuk pergi. Kemudian, dia berbalik dan menghilang ke dalam kegelapan malam."
  },
  AvgDialog_19033_Content_2 = {
    Text = "Sebelum suara itu hilang, Lotan dan Ramona segera mencabut pedang mereka dan berhadapan dengan pria bermata satu yang tiba-tiba muncul."
  },
  AvgDialog_19033_Content_20 = {
    Text = "Luar penginapan"
  },
  AvgDialog_19033_Content_21 = {
    Text = [[
Baiklah, sepertinya kalian tidak tahu. 
Ah, jalan pintas tidak akan muncul begitu saja, ingin bermalas-malasan selalu keras.]]
  },
  AvgDialog_19033_Content_22 = {
    Text = "Ngomong-ngomong..."
  },
  AvgDialog_19033_Content_23 = {
    Text = "Pria bermata satu berhenti sejenak dengan penuh teka-teki."
  },
  AvgDialog_19033_Content_24 = {
    Text = "Anjing neraka…\nAda di belakang kalian, lho."
  },
  AvgDialog_19033_Content_25 = {
    Text = "Menggunakan tipu daya kecil seperti ini untuk mengalihkan perhatian kami, kamu benar-benar meremehkan kami."
  },
  AvgDialog_19033_Content_26 = {
    Text = [[
Perasaan berdebar tiba-tiba muncul, seperti ada duri menusuk di bagian belakang kepala, rasa tertekan merasuk hingga ke tulang sumsum. 
 Kamu tahu dengan pasti bahwa itu bukan sugesti mental.]]
  },
  AvgDialog_19033_Content_27 = {
    Text = "Hmm? Kenapa kalian tidak bergerak?"
  },
  AvgDialog_19033_Content_28 = {
    Text = "Lotan, tolong berbalik dan lihat."
  },
  AvgDialog_19033_Content_29 = {
    Text = "Lotan perlahan menoleh."
  },
  AvgDialog_19033_Content_3 = {
    Text = "Tidak perlu seperti itu, aku hanya datang untuk mengunjungi seorang teman dan tidak berniat berkonflik dengan kalian."
  },
  AvgDialog_19033_Content_30 = {Text = "Apa——"},
  AvgDialog_19033_Content_31 = {Text = "!"},
  AvgDialog_19033_Content_32 = {
    Text = [[
Dengan desahan kuat yang mengguncang gendang telinga, pupil vertikal yang berwarna keemasan merobek ruang di belakang Lotan.
Pupil yang tak bernama mengawasi tanah, akhirnya fokus pada kalian.]]
  },
  AvgDialog_19033_Content_33 = {
    Text = "Hatimu bergetar tanpa bisa dikendalikan, tatapan itu seolah datang dari tepi lautan bintang yang luas, telah menatap sejak zaman kuno——"
  },
  AvgDialog_19033_Content_34 = {
    Text = "Jangan panik, hati-hati menghadapi musuh!"
  },
  AvgDialog_19033_Content_4 = {
    Text = "Ngomong-ngomong, apakah kalian pernah melihat seorang gadis kecil? \n Tingginya sekitar seperti ini…"
  },
  AvgDialog_19033_Content_5 = {
    Text = "Menganggap kalian tidak ada, pria itu dengan santai mengisyaratkan gerakan tangannya."
  },
  AvgDialog_19033_Content_6 = {
    Text = "Mengenakan gaun putih, dengan sebuah papan kecil tergantung di tubuhnya…"
  },
  AvgDialog_19033_Content_7 = {
    Text = [[
Pada saat yang sama
Semak-semak Lai]]
  },
  AvgDialog_19033_Content_8 = {Text = "Di mana..."},
  AvgDialog_19033_Content_9 = {
    Text = "<Small: Harus melarikan diri… harus menemukan tamu…>"
  },
  AvgDialog_19034_Content_1 = {
    Text = "Lily, minggir! Kami tidak ingin memberikan kerusakan pada Francis!"
  },
  AvgDialog_19034_Content_2 = {
    Text = "Jangan biarkan ibumu terus melakukan kesalahan lagi!"
  },
  AvgDialog_19034_Content_3 = {
    Text = "Ibu... Ibu..."
  },
  AvgDialog_19035_Content_1 = {
    Text = "%player%{Male=Tuan Penjaga Rahasia,Female=Nona Penjaga Rahasia}, bertahan sebentar lagi!"
  },
  AvgDialog_19035_Content_2 = {
    Text = "Bisul ini bisa berubah bentuk untuk melindungi kamu!"
  },
  AvgDialog_19035_Content_3 = {
    Text = [[
Sekarang, rentangkan untuk menahan tusukan. 
 Tidak apa-apa, Lily tidak akan merasakan sakit!]]
  },
  AvgDialog_19036_Content_1 = {Text = "Penutup"},
  AvgDialog_19036_Content_10 = {
    Text = "Senang sekali, kapan aku bisa pergi ke tempat sejauh itu juga…"
  },
  AvgDialog_19036_Content_100 = {
    Text = "Ngomong-ngomong, aku pernah melihat sebuah <Yellow:logo> di Altar dalam mimpiku."
  },
  AvgDialog_19036_Content_101 = {
    Text = "Apa tanda itu?"
  },
  AvgDialog_19036_Content_102 = {
    Text = "Tunggu sebentar, aku akan menggambarnya."
  },
  AvgDialog_19036_Content_103 = {
    Text = "Kamu mengeluarkan buku catatan dari saku, dengan beberapa goresan cepat, menggambar sebuah kontur kasar."
  },
  AvgDialog_19036_Content_104 = {
    Text = "Tunggu, aku pernah melihat tanda ini…"
  },
  AvgDialog_19036_Content_105 = {
    Text = "Jadi, bagaimana rasanya hancur berkeping-keping, Nyonya Boneka yang tercinta?"
  },
  AvgDialog_19036_Content_106 = {
    Text = [[
Berkat Anda, aku sama sekali tidak merasakan apa-apa. 
Lagipula, aku tidak seperti beberapa orang yang menginginkan bentuk kehidupan baru tetapi masih enggan meninggalkan tubuh duniawi.]]
  },
  AvgDialog_19036_Content_107 = {
    Text = [[
Ngomong-ngomong, menelepon nomor kontak publik sekolah? Serius? 
 Sengaja datang untuk mengejek, itu tidak sesuai dengan kepribadianmu yang penakut dan serakah akan hidup.]]
  },
  AvgDialog_19036_Content_108 = {
    Text = "Astaga, jangan terburu-buru, dong. Aku punya kabar baik untukmu."
  },
  AvgDialog_19036_Content_109 = {
    Text = [[
Perak yang kau tinggalkan untukku, <Yellow:Perak>, memang barang yang sangat bagus. 
Perjalanan ini tidak sepenuhnya sia-sia.]]
  },
  AvgDialog_19036_Content_11 = {
    Text = "Anak ini, semoga dia segera mengirim surat begitu tiba di dermaga berikutnya…"
  },
  AvgDialog_19036_Content_110 = {
    Text = "Tapi Wanita Narsis sangat marah, katanya kepalanya yang dijadwalkan terkunci di tempat yang tidak bisa dijangkaunya, perdagangan yang merugikan sangat tidak menguntungkan."
  },
  AvgDialog_19036_Content_111 = {
    Text = [[
Demi masa lalu, aku sengaja datang untuk memberi nasihat, jangan kejar-kejar aku. 
Orang-orang yang mencoba mengambil keuntungan dariku semuanya akhirnya rugi besar.]]
  },
  AvgDialog_19036_Content_112 = {
    Text = "Apakah semuanya hilang begitu saja? Aku tidak berpikir demikian."
  },
  AvgDialog_19036_Content_113 = {
    Text = "Apakah kamu pernah berpikir, mengapa saat aku meledakkan diri, aku masih meninggalkan sepotong Perak untukmu?"
  },
  AvgDialog_19036_Content_114 = {
    Text = "Suara Boneka sangat dingin, tetapi di telinga Herbert, terdengar seperti mengandung senyuman penuh ejekan."
  },
  AvgDialog_19036_Content_115 = {
    Text = "Di buku sketsa Boneka, tergambar sebuah pola yang jelas."
  },
  AvgDialog_19036_Content_13 = {
    Text = "Shilo berdiri sendirian di dermaga, rambut panjangnya berkibar-kibar tertiup angin."
  },
  AvgDialog_19036_Content_14 = {
    Text = "Kapalnya akan berangkat, mau naik?"
  },
  AvgDialog_19036_Content_15 = {
    Text = [[
Shilo melambaikan tangan, mengisyaratkan feri agar tidak perlu menunggunya.
Dia belum memutuskan tujuan selanjutnya.]]
  },
  AvgDialog_19036_Content_16 = {
    Text = "Jika ada kesempatan, pergilah melihat dunia yang lebih luas."
  },
  AvgDialog_19036_Content_18 = {
    Text = "Di tengah teriakan kaget para pelaut, Helot mengaitkan rantai dan melompat ke atas dek."
  },
  AvgDialog_19036_Content_19 = {
    Text = "Di tengah suara peluit, pantai perlahan menghilang."
  },
  AvgDialog_19036_Content_2 = {
    Text = "Nymphaea! Tuan Crawford ingin mendengar lagi puisi tentang bunga teratai putih itu, cepatlah dan bacakan untuknya!"
  },
  AvgDialog_19036_Content_20 = {
    Text = "Hm… Orang-orang dari Mythag…"
  },
  AvgDialog_19036_Content_21 = {
    Text = "Kali ini, anggap saja aku berhutang budi pada mereka."
  },
  AvgDialog_19036_Content_23 = {
    Text = "Setelah kembali ke Mythag, kamu terbaring di tempat tidur asrama selama tiga hari tiga malam tanpa makan atau minum."
  },
  AvgDialog_19036_Content_24 = {
    Text = "Pingsan Penjaga menjadi berita besar di Mythag, ditulis oleh Hannah di halaman depan koran sekolah. Sesekali, ada mahasiswa dari jurusan lain yang mengintip di depan pintu kamarmu."
  },
  AvgDialog_19036_Content_25 = {
    Text = "Jadi, berita tentangmu yang telah bangkit juga tidak mengherankan menyebar dalam waktu singkat."
  },
  AvgDialog_19036_Content_26 = {
    Text = [[
Tentu saja, semua ini adalah cerita yang Ramona beritahukan kepadamu kemudian.
Pada saat itu, kamu hanya merasa tubuhmu lemas dan seperti kehabisan semua tenaga.]]
  },
  AvgDialog_19036_Content_27 = {
    Text = "Dan ketika kamu membuka mata, orang pertama yang muncul di depanmu membuatmu merasa seperti mengalami fatamorgana."
  },
  AvgDialog_19036_Content_28 = {
    Text = "Selamat, kamu telah pulih dari efek samping melintasi Dimensi, Penjaga. Aku membawa kabar baik untukmu."
  },
  AvgDialog_19036_Content_29 = {
    Text = "Tingkat kesulitan misi kali ini jauh melampaui penilaian awal, namun kalian telah menyelesaikannya dengan sangat baik. Hal ini akan tercermin dalam laporan akhir semester-mu."
  },
  AvgDialog_19036_Content_3 = {
    Text = "Tunggu sebentar, aku akan segera datang."
  },
  AvgDialog_19036_Content_30 = {
    Text = "Senang? Boneka jarang memuji orang lain seperti ini."
  },
  AvgDialog_19036_Content_31 = {
    Text = "Boneka, Boneka…? Bukankah kau sudah dibawa oleh Herbert…?"
  },
  AvgDialog_19036_Content_32 = {
    Text = "Saya ingin mengevaluasi kembali kesimpulan yang baru saja saya buat."
  },
  AvgDialog_19036_Content_33 = {
    Text = "<Shake:Jangan! Jangan sekali-kali!>"
  },
  AvgDialog_19036_Content_34 = {
    Text = "Saya dijuluki <Blue:\"Otak dalam toples\">, otak yang tinggal di Mythag inilah yang merupakan tubuh utama."
  },
  AvgDialog_19036_Content_35 = {
    Text = "Adapun <Yellow:Tubuh Buatan> yang meledak, jumlahnya tidak terbatas."
  },
  AvgDialog_19036_Content_36 = {
    Text = "Tentu saja tidak bisa Lelah sembarangan, jika tidak anggaran untuk sistem Bangun akan kehabisan dana. Pada saat itu, kamu harus membawa Ramona untuk mempertunjukkan tarian pedang di hadapan Mulia Dexter guna mendapatkan sponsor."
  },
  AvgDialog_19036_Content_37 = {
    Text = "Saya sangat menantikannya."
  },
  AvgDialog_19036_Content_38 = {
    Text = "Ngomong-ngomong, sekadar informasi, lensa dimensi tunggal yang kalian kenakan selama misi juga merupakan barang habis pakai."
  },
  AvgDialog_19036_Content_39 = {
    Text = "Karena dibeli dari Narsis, pedagang hitam itu, nilai satu kepingnya kira-kira bisa ditukar dengan 5 tubuh buatan saya."
  },
  AvgDialog_19036_Content_4 = {
    Text = "Ngomong-ngomong, sudah lama tidak bertemu dengan Direktur Ozwood."
  },
  AvgDialog_19036_Content_40 = {
    Text = "Jadi, jika kamu mengklaim penggantian beberapa keping ekstra, saya sarankan kamu bekerja untuk Mulia Dexter guna melunasi utangmu."
  },
  AvgDialog_19036_Content_41 = {
    Text = "Merupakan kehormatan besar."
  },
  AvgDialog_19036_Content_43 = {
    Text = "Orang-orang yang datang untuk menjengukmu berdatangan seperti gelombang, bahkan membuatmu merasa lebih lelah daripada saat melakukan Penyelidikan lapangan."
  },
  AvgDialog_19036_Content_44 = {
    Text = "Hingga semua orang pergi, kamu menutup mata dan menghela napas. Tepat saat hendak berbaring untuk beristirahat lagi, sebuah sosok yang sangat familiar tiba-tiba muncul di samping tempat tidurmu."
  },
  AvgDialog_19036_Content_45 = {
    Text = "Apakah kamu ingin... pergi melihat Lily?"
  },
  AvgDialog_19036_Content_46 = {
    Text = "Sosok kecil duduk di atas tempat tidur, bersandar pada bantal putih bersih sambil memandang keluar jendela."
  },
  AvgDialog_19036_Content_47 = {
    Text = "Lily, %player% datang untuk melihatmu."
  },
  AvgDialog_19036_Content_48 = {
    Text = "Kakak {Male=Tuan Penjaga Rahasia,Female=Nona Penjaga Rahasia}."
  },
  AvgDialog_19036_Content_49 = {
    Text = "Bagaimana dengan saran yang saya ajukan sebelumnya? \nDan tautan dengan %player%, menjadi mitra kami…"
  },
  AvgDialog_19036_Content_5 = {
    Text = "Direktur sedang... melakukan beberapa penelitian yang sangat penting sendirian, sepertinya dia akan membutuhkan waktu yang sangat lama sebelum kembali ke sanatorium."
  },
  AvgDialog_19036_Content_50 = {
    Text = "Lily memalingkan kepalanya, menghindari tatapan langsung kalian."
  },
  AvgDialog_19036_Content_51 = {
    Text = [[
Jika... jika aku tidak mau? 
Apakah kalian akan menganggapku sebagai monster... dan mengurungku?]]
  },
  AvgDialog_19036_Content_52 = {
    Text = "Maaf, aku tidak bermaksud memaksamu. Hanya saja..."
  },
  AvgDialog_19036_Content_53 = {
    Text = "Biarkan aku yang melakukannya."
  },
  AvgDialog_19036_Content_54 = {Text = "Lily."},
  AvgDialog_19036_Content_55 = {
    Text = "Hmm, aku ada di sini."
  },
  AvgDialog_19036_Content_56 = {
    Text = [[
Apa yang terjadi padamu, mungkin setiap orang memiliki kesalahannya masing-masing... 
 Namun, jika dipikirkan dari sudut pandang lain, baik kamu maupun ibumu tidak ada yang salah.]]
  },
  AvgDialog_19036_Content_57 = {
    Text = [[
Sumber dari semua kejahatan hanyalah pelarutan...
Penyakit yang membuat orang dilupakan.]]
  },
  AvgDialog_19036_Content_58 = {
    Text = "Justru karena orang-orang di sekitarmu melupakanmu, Francis secara obsesif mengejar bukti keberadaanmu."
  },
  AvgDialog_19036_Content_59 = {
    Text = "Tepat karena dia juga mulai melupakanmu secara perlahan, dia tidak bisa mengenali dirimu yang paling dekat dengannya."
  },
  AvgDialog_19036_Content_6 = {
    Text = [[
Benar! Bagaimana mungkin seseorang yang begitu cerdas seperti dia bisa terkekang oleh sanatorium yang buruk ini? Sungguh membuang-buang bakat! 
 Jika kamu punya kesempatan untuk bertemu dengannya, ingatlah untuk menyampaikan doaku agar Penelitiannya berjalan lancar.]]
  },
  AvgDialog_19036_Content_60 = {
    Text = "Jika rahasia di balik pelarutan tidak terpecahkan, tragedi seperti ini akan terus berulang."
  },
  AvgDialog_19036_Content_61 = {
    Text = "Pengejaran Francis adalah benar, Lily… ibumu, dia tidak bersalah. \nDia hanya telah dibimbing ke jalan yang salah."
  },
  AvgDialog_19036_Content_62 = {
    Text = [[
Dan kami akan berjalan di jalan yang benar, serta bertempur habis-habisan melawan Pelarutan. 
Jadi, tolong bantu kami, oke, Lily?]]
  },
  AvgDialog_19036_Content_63 = {
    Text = "<Small:Francis… Mama…>"
  },
  AvgDialog_19036_Content_64 = {
    Text = "Mendengar nama Francis, Lily mulai menangis tersedu-sedu, butiran air mata bening bergulir dari sudut matanya."
  },
  AvgDialog_19036_Content_65 = {
    Text = "Aku tahu, bagi kamu, tidak ada seorang pun yang bisa menggantikan ibumu."
  },
  AvgDialog_19036_Content_66 = {
    Text = "Tetapi kami... juga bisa menjadi keluargamu."
  },
  AvgDialog_19036_Content_67 = {
    Text = "Apa dengan keluarga atau bukan."
  },
  AvgDialog_19036_Content_68 = {
    Text = "Lotan masuk dengan langkah besar, bergabung dalam percakapan kalian dengan sikap penuh amarah."
  },
  AvgDialog_19036_Content_69 = {
    Text = [[
Kalian datang untuk melihat Lily, tapi tidak memanggil aku? 
 Apakah ini cara kalian memperlakukan teman yang sudah berjuang bersama dalam hidup dan mati?]]
  },
  AvgDialog_19036_Content_7 = {
    Text = "Hmm, semoga dia... segalanya berjalan dengan baik."
  },
  AvgDialog_19036_Content_70 = {
    Text = "Lotan, kau... tidak kembali ke Kolam Hitam?"
  },
  AvgDialog_19036_Content_71 = {
    Text = "Setiap hari menunggu juga terasa membosankan. Jika ikut dalam misi lapangan bersama kalian, siapa tahu bisa bertemu dengan lawan yang menarik."
  },
  AvgDialog_19036_Content_72 = {
    Text = "Sudah, jangan menangis lagi."
  },
  AvgDialog_19036_Content_73 = {
    Text = "Lotan menepuk bahu Lily yang kurus."
  },
  AvgDialog_19036_Content_74 = {
    Text = "Jika kamu tidak keberatan, mulai sekarang, kamu juga bisa memanggilku Ibu."
  },
  AvgDialog_19036_Content_75 = {Text = "Bagaimana?"},
  AvgDialog_19036_Content_76 = {
    Text = "A.F.290 Elworth"
  },
  AvgDialog_19036_Content_77 = {
    Text = "Francis perlahan menghapus noda di wajah gadis itu yang bercampur antara minyak dan lumpur hitam."
  },
  AvgDialog_19036_Content_78 = {
    Text = "<Yellow:Jika kamu tidak keberatan, mulai sekarang kamu juga bisa memanggilku Ibu.>"
  },
  AvgDialog_19036_Content_80 = {
    Text = "Rasanya seperti ada batu yang akhirnya jatuh dari hati."
  },
  AvgDialog_19036_Content_81 = {
    Text = "Dengan Lotan membawa, jika sering berinteraksi dengan Aurita dan yang lainnya... Lily seharusnya bisa cepat beradaptasi di sini."
  },
  AvgDialog_19036_Content_82 = {
    Text = "Untungnya, tidak semua orang seperti kamu, Boneka, dan William yang selalu cemberut setiap hari. Kalau tidak, hidup di Mythag akan sedikit menyusahkan."
  },
  AvgDialog_19036_Content_83 = {
    Text = "Kamu mencoba bercanda, tetapi Ramona tidak merespons leluconmu."
  },
  AvgDialog_19036_Content_84 = {Text = "Ramona?"},
  AvgDialog_19036_Content_85 = {
    Text = "Penjaga, saya ingin berbicara denganmu."
  },
  AvgDialog_19036_Content_86 = {
    Text = [[
Dia tidak menyebut namamu secara langsung, melainkan menggunakan sebutan ini. 
 Kamu tanpa sadar memperbaiki postur tubuhmu.]]
  },
  AvgDialog_19036_Content_87 = {
    Text = "Selama proses penyelidikan acara ini, banyak kali ekspresi wajahmu tampak tidak baik."
  },
  AvgDialog_19036_Content_88 = {
    Text = [[
Yang paling jelas adalah ketika kamu membaca catatan harian Francis... 
 Reaksimu benar-benar berbeda dari yang aku bayangkan.]]
  },
  AvgDialog_19036_Content_89 = {
    Text = [[
Bagian awal dari buku harian sangat panjang, tetapi kamu hanya membutuhkan waktu singkat untuk melewatinya. 
 Seolah-olah kamu sudah mengetahui hal-hal itu sejak lama.]]
  },
  AvgDialog_19036_Content_9 = {
    Text = "Bu Lisa, Lisa mengirim surat lagi! Dia berkata bahwa dia dan Wanita Narsis sudah meninggalkan gurun Kerajaan Remouahe, menyeberangi lautan dengan kapal besar menuju Republik Aglo yang baru berkembang."
  },
  AvgDialog_19036_Content_90 = {
    Text = "Mengenai hal ini, saya memiliki sebuah dugaan."
  },
  AvgDialog_19036_Content_91 = {
    Text = "<Italic:Apakah kamu melihat mimpinya?>"
  },
  AvgDialog_19036_Content_92 = {
    Text = "Setelah ragu sejenak, kamu akhirnya menceritakan semua yang kamu lihat dalam mimpi."
  },
  AvgDialog_19036_Content_93 = {
    Text = "<Yellow:Kekuatan sensorik> ternyata begitu kuat dalam dirimu…\nKamu sudah mengetahui keseluruhan Acara sejak awal, oleh karena itu, pada akhirnya, kamu sangat yakin."
  },
  AvgDialog_19036_Content_94 = {
    Text = "Beberapa hari ini saya terus memikirkan, bagi kita, Pembangun adalah rekan yang bertarung bersama, kadang-kadang bahkan sahabat yang bisa dipercayakan dengan nyawa."
  },
  AvgDialog_19036_Content_95 = {
    Text = [[
Namun, di mata Francis, Lily adalah kehidupan yang lahir dari pelarutan. 
 Baginya, itu tidak berbeda dengan monster yang merenggut orang yang paling dia cintai.]]
  },
  AvgDialog_19036_Content_96 = {
    Text = "Meskipun hanya menyampaikan kebenaran di hadapannya, apakah kata-kata yang aku ucapkan saat itu terlalu berlebihan? Sama sekali tidak mempertimbangkan perasaan dia dan Lily."
  },
  AvgDialog_19036_Content_97 = {
    Text = "Bagaimanapun, fakta bahwa dia melakukan eksperimen kejam pada Lily… adalah sesuatu yang tidak terbantahkan. Bahkan jika bukan kami, <Yellow:Komite Perjanjian Mystia> suatu hari pasti akan melacak mereka."
  },
  AvgDialog_19036_Content_98 = {Text = "..."},
  AvgDialog_19036_Content_99 = {
    Text = "Melihat ekspresi Ramona berubah muram, otakmu segera bekerja cepat dan menemukan topik yang sesuai."
  },
  AvgDialog_19037_Content_1 = {
    Text = "Bantu aku, Boneka!"
  },
  AvgDialog_19037_Content_2 = {
    Text = "Saya rasa tidak perlu, mengandalkan orang itu sudah lebih dari cukup."
  },
  AvgDialog_19037_Content_3 = {
    Text = "Aku sudah hampir tertidur, tidak adakah lawan yang lebih kuat?"
  },
  AvgDialog_19038_Content_1 = {
    Text = "Lily, cepat bangun! Ini aku, %player%, dan Ramona!"
  },
  AvgDialog_19038_Content_2 = {
    Text = "……%player% besar {Male=Tuan Penjaga Rahasia,Female=Nona Penjaga Rahasia}……"
  },
  AvgDialog_19039_Content_1 = {
    Text = "Sekelompok demi sekelompok, bergantian tanpa henti…"
  },
  AvgDialog_19039_Content_2 = {
    Text = "Kenapa mereka tampak seperti sudah siap?"
  },
  AvgDialog_19040_Content_1 = {
    Text = "Rumah Sakit Roh"
  },
  AvgDialog_19040_Content_10 = {
    Text = "Ramona terkejut dalam hati, lalu segera bersembunyi di rumah kosong terdekat."
  },
  AvgDialog_19040_Content_11 = {
    Text = [[
Ah, Bob juga tidak datang menjengukku...
Kapan hari-hari seperti ini akan berakhir...]]
  },
  AvgDialog_19040_Content_12 = {
    Text = [[
Saya sudah di sini selama beberapa tahun, tapi belum pernah melihat ada yang datang mengunjungi. 
 Kalau benar-benar peduli, dia tidak akan mengirim kamu ke tempat seperti ini.]]
  },
  AvgDialog_19040_Content_13 = {Text = "Haah..."},
  AvgDialog_19040_Content_14 = {
    Text = "Setelah kedua orang itu pergi sambil mengobrol, Ramona akhirnya mendapatkan kesempatan untuk mengamati ruangan tempat ia bersembunyi dengan lebih teliti."
  },
  AvgDialog_19040_Content_2 = {
    Text = "Ramona berhati-hati menapaki ujung kakinya, bergerak tanpa suara di antara bayangan koridor."
  },
  AvgDialog_19040_Content_3 = {
    Text = "Penjaga tidak menyetujui keputusannya, tetapi saat dia bersikeras, dia memilih untuk mengizinkan secara diam-diam. Dia hanya berpesan agar dia segera menarik diri, baik berhasil maupun gagal."
  },
  AvgDialog_19040_Content_4 = {
    Text = "Alasannya cukup kuat. Jika hanya bisa memilih satu orang untuk membantu Lily, dia yang masih memiliki kemampuan dalam pertempuran dan ahli dalam bertindak secara rendah hati adalah yang paling cocok."
  },
  AvgDialog_19040_Content_5 = {
    Text = [[
Setelah berbelok di sudut ketiga dan menghindari pasien yang sedang bergosip, Ramona mulai merasa ragu.
Dia mulai tidak yakin dengan alasan keberadaannya di sini.]]
  },
  AvgDialog_19040_Content_6 = {
    Text = "Di dalam hatinya, dia merasakan semacam panggilan samar-samar. Panggilan itu membuatnya merasa memiliki tanggung jawab tertentu terhadap anak itu."
  },
  AvgDialog_19040_Content_7 = {
    Text = "Panggilan seperti itulah yang membuatnya merasa ada semacam hubungan antara dirinya dan Lily, dan dia sangat yakin bahwa Lily berada di ruangan paling timur di sanatorium."
  },
  AvgDialog_19040_Content_8 = {
    Text = "Asalkan keberuntungannya cukup baik, dia bisa membawa Lily pergi tanpa suara. Kemudian, beritahu Mythag untuk mengirim orang melakukan pencarian menyeluruh di sanatorium guna menemukan penyebab kegagalan Perak…"
  },
  AvgDialog_19040_Content_9 = {Text = "Huh, huh!"},
  AvgDialog_19041_Content_1 = {
    Text = "Retakan di Kulit"
  },
  AvgDialog_19041_Content_10 = {
    Text = "Ini adalah..."
  },
  AvgDialog_19041_Content_11 = {
    Text = "Anjing neraka sejati."
  },
  AvgDialog_19041_Content_12 = {
    Text = [[
Ini bukan pertama kalinya kamu berhadapan langsung dengan monster ini, tapi sekarang kamu sangat yakin: 
Itulah target Penyelidikan kalian, akar sebenarnya dari kasus penghilangan Rai.]]
  },
  AvgDialog_19041_Content_13 = {
    Text = "Perasaan kelumpuhan di kulit kepala dan dingin di punggung itu sama persis seperti ketika \"ditangkap\" dua kali sebelumnya… tidak, bahkan lebih jelas dan intens."
  },
  AvgDialog_19041_Content_14 = {
    Text = "Kamu melihat sesuatu yang merah dan buram di depan mata."
  },
  AvgDialog_19041_Content_15 = {
    Text = "Dalam pandangan berwarna merah darah, kau mendengar suara menggoda Dafude'er berbisik di telingamu."
  },
  AvgDialog_19041_Content_16 = {
    Text = "Petik saja, jangan melihat ini. Kepalamu tidak akan pusing."
  },
  AvgDialog_19041_Content_17 = {
    Text = "Apa yang akan terjadi jika aku memetiknya?"
  },
  AvgDialog_19041_Content_18 = {
    Text = "Akan perlahan kehilangan kesadaran, lalu dalam ketenangan menjadi nutrisi bagi Anjing Dimensi."
  },
  AvgDialog_19041_Content_19 = {
    Text = "Kalau begitu, aku harus tetap bertahan."
  },
  AvgDialog_19041_Content_2 = {
    Text = "Tanah tiba-tiba berguncang dengan hebat."
  },
  AvgDialog_19041_Content_20 = {
    Text = "Kamu mengeluarkan sebuah reagen yang diberikan oleh Boneka, membuka sumbatnya, dan meminumnya sekaligus."
  },
  AvgDialog_19041_Content_21 = {
    Text = "Rasanya sangat berbeda dari yang kamu bayangkan, dengan manis yang kental dan langsung menusuk ubun-ubun."
  },
  AvgDialog_19041_Content_22 = {
    Text = "Seandainya tahu rasanya sebaik ini, aku seharusnya meminta lebih banyak lagi untuk dicampur dengan air minum."
  },
  AvgDialog_19041_Content_23 = {
    Text = "Asap menyebar di ruangan, lebih banyak monster yang terdistorsi muncul secara berturut-turut."
  },
  AvgDialog_19041_Content_24 = {
    Text = "Kamu mengusap darah dan air mata yang mengalir dari sudut matamu, jalinan benang merah di punggung tanganmu mengingatkan bahwa kamu harus segera menyelesaikan pertarungan ini."
  },
  AvgDialog_19041_Content_25 = {Text = "Ramona!"},
  AvgDialog_19041_Content_26 = {
    Text = "Ya! Mengamati clades \"Anjing Neraka\", bersiap untuk pertempuran terakhir!"
  },
  AvgDialog_19041_Content_3 = {
    Text = "Apa yang terjadi?"
  },
  AvgDialog_19041_Content_4 = {
    Text = "Rune di dinding terkoyak."
  },
  AvgDialog_19041_Content_5 = {
    Text = "Apakah itu goresan tidak sengaja saat menundukkan Lily, terkena imbas saat melawan Helot, ataukah ulah Narsis saat dia pergi?"
  },
  AvgDialog_19041_Content_6 = {
    Text = "Kamu sudah lupa."
  },
  AvgDialog_19041_Content_7 = {
    Text = "Tapi itu sudah tidak penting lagi."
  },
  AvgDialog_19041_Content_8 = {
    Text = "Dari celah-celah rune, muncul asap ungu yang tak berbentuk. Perlahan-lahan, asap itu berkumpul di tanah dan membentuk wujud."
  },
  AvgDialog_19041_Content_9 = {
    Text = [[
Penglihatan terbebani oleh tekanan berat, saraf berdenyut tanpa kendali. 
Yang meluap dari celah yang terdistorsi adalah monster tajam yang menyerupai binatang buas.]]
  },
  AvgDialog_19042_Content_1 = {
    Text = "Kami dikepung."
  },
  AvgDialog_19042_Content_2 = {
    Text = "Sebelumnya, saat melakukan pencarian, tidak menemukan begitu banyak monster."
  },
  AvgDialog_19042_Content_3 = {
    Text = "Ck, entah dari mana dia berasal."
  },
  AvgDialog_19043_Content_1 = {
    Text = "Melintasi Rumah Sakit Jiwa dengan Terbang"
  },
  AvgDialog_19043_Content_10 = {
    Text = "Selain Mia dan Koom, tempat ini benar-benar merupakan sanatorium yang biasa-biasa saja dan terisolasi dari dunia luar."
  },
  AvgDialog_19043_Content_11 = {
    Text = "Kali ini aku terlalu gegabah, membuat mereka waspada. Jika saja aku berpikir lebih matang…"
  },
  AvgDialog_19043_Content_12 = {
    Text = "Sementara pergi"
  },
  AvgDialog_19043_Content_13 = {
    Text = [[
Melihat keadaan seperti ini, lebih baik pergi untuk sementara waktu. 
 Tidak terlambat untuk kembali setelah mengumpulkan cukup informasi.]]
  },
  AvgDialog_19043_Content_14 = {Text = "Ragu-ragu"},
  AvgDialog_19043_Content_15 = {
    Text = "Apakah kamu memiliki pemikiran?"
  },
  AvgDialog_19043_Content_16 = {
    Text = [[
Di sini... sangat biasa, bahkan terlalu biasa. 
Biasa hingga terasa disengaja.]]
  },
  AvgDialog_19043_Content_17 = {
    Text = "Seorang dokter membuka sebuah panti rehabilitasi biasa di kota kecil yang sederhana, menghindari dunia dengan sikap pasif, namun tetap mengatur segala sesuatunya dengan rapi dan teratur."
  },
  AvgDialog_19043_Content_18 = {
    Text = [[
Secara kebetulan menyelamatkan seorang anak, tapi ternyata dia adalah Pembangun? 
 Terlalu banyak kebetulan.]]
  },
  AvgDialog_19043_Content_19 = {
    Text = "Intinya, hubungi Mythag dulu."
  },
  AvgDialog_19043_Content_2 = {
    Text = "Waktu berlalu sedikit demi sedikit. Kalian meninggalkan Francis di tempatnya, lalu berbalik dan memeriksa seluruh sanatorium — tidak ada pintu rahasia, tidak ada mekanisme, tidak ada ruangan tersembunyi."
  },
  AvgDialog_19043_Content_20 = {
    Text = "Ramona menyentuh pin perak di dadanya, kalian menahan napas, menunggu komunikasi terhubung."
  },
  AvgDialog_19043_Content_22 = {
    Text = [[
Sepuluh detik berlalu, yang tersisa di udara hanyalah keheningan yang menyesakkan. 
 Kamu bisa merasakan jantungmu berdetak kencang.]]
  },
  AvgDialog_19043_Content_23 = {
    Text = "Komunikasi... terputus lagi?"
  },
  AvgDialog_19043_Content_24 = {
    Text = [[
...Sepertinya tidak semudah itu.
Penjaga, apakah kamu bisa merasakan keberadaan Pembangun lainnya?]]
  },
  AvgDialog_19043_Content_25 = {
    Text = "Kamu berkonsentrasi, merasakan resonansi sesaat. Namun, benang halus yang tadinya ada secara samar-samar entah kapan telah putus. Di ujung tautan itu, hanya ada kehampaan putih yang membentang."
  },
  AvgDialog_19043_Content_26 = {
    Text = "Bahkan tautan antara Ramona dan Lotan di sisinya begitu lemah hingga hampir tak terdeteksi."
  },
  AvgDialog_19043_Content_27 = {
    Text = "Hanya bisa merasakan keberadaan kalian dengan susah payah, sedangkan yang di Mythag sama sekali tidak terasa."
  },
  AvgDialog_19043_Content_28 = {
    Text = "Sepertinya di sini terisolasi dari <Yellow:Teknologi chip perak>, atau bisa dikatakan, kekuatan terkait dengan <Yellow:Pelarutan> dibatasi di sini."
  },
  AvgDialog_19043_Content_29 = {Text = "Lotan."},
  AvgDialog_19043_Content_3 = {
    Text = "Bahkan di dalam kantor yang dilarang dimasuki tersebut, tidak ada keanehan apa pun."
  },
  AvgDialog_19043_Content_30 = {
    Text = "Apa, ada apa?"
  },
  AvgDialog_19043_Content_31 = {
    Text = "Kehilangan kontak dengan Mythag, tautan pembangun dengan Penjaga lemah, sudah terjadi situasi darurat kelas dua. Segera lakukan evakuasi tanpa syarat, prioritaskan keselamatan Penjaga."
  },
  AvgDialog_19043_Content_32 = {
    Text = "Baiklah, baiklah. Aku bilang, kali ini keluar hanya untuk menjadi pengasuh kalian…"
  },
  AvgDialog_19043_Content_33 = {
    Text = "Evakuasi? Bagaimana dengan Lily? Dan Koom?"
  },
  AvgDialog_19043_Content_34 = {
    Text = "Ramona menghela napas, lalu memandang ke arah koridor."
  },
  AvgDialog_19043_Content_35 = {
    Text = [[
Mereka telah mengikuti Francis untuk waktu yang lama, jadi dia tidak punya alasan untuk menyakiti mereka. 
Sebaliknya, kita hanyalah beberapa orang asing yang justru menjadi ancaman bagi Francis.]]
  },
  AvgDialog_19043_Content_36 = {
    Text = [[
Musuh bersembunyi dalam bayang-bayang, sedangkan kita berada di tempat terang. Tidak perlu terburu-buru.
Setelah persiapan matang, kami pasti akan membawa mereka pergi dari sini.]]
  },
  AvgDialog_19043_Content_37 = {
    Text = "Suara ketukan sepatu hak tinggi tiba-tiba terdengar di koridor, diikuti oleh suara yang tenang bak air mengalir."
  },
  AvgDialog_19043_Content_38 = {
    Text = "Apakah kalian sudah memeriksa sekali lagi? Bagaimana hasilnya? Apakah menemukan sesuatu?"
  },
  AvgDialog_19043_Content_39 = {
    Text = "Kita harus meninggalkan tempat ini."
  },
  AvgDialog_19043_Content_4 = {
    Text = "Keringat halus mulai bermunculan di dahi Ramona."
  },
  AvgDialog_19043_Content_40 = {
    Text = "Tentu, tentu. Meskipun Lily jarang dikunjungi teman, jika kalian ingin pergi, aku tidak akan memaksa kalian untuk tinggal."
  },
  AvgDialog_19043_Content_41 = {
    Text = "Lily dan Koom?"
  },
  AvgDialog_19043_Content_42 = {
    Text = [[
Saya baru saja menyelesaikan pengaturan mereka. 
 Kamu orang yang cerdas, pasti tidak akan mengatakan sesuatu seperti ingin membawa mereka pergi, kan?]]
  },
  AvgDialog_19043_Content_43 = {
    Text = "Meskipun saya sangat menghargai kalian karena telah membawanya kembali, tetap saja agak tidak sopan datang ke rumah orang lain dan langsung membawa putri serta hewan peliharaan mereka, bukan?"
  },
  AvgDialog_19043_Content_44 = {
    Text = "Francis mengangkat jari telunjuknya, melingkari helai rambut di pipinya, dengan suara yang terdengar suram."
  },
  AvgDialog_19043_Content_45 = {
    Text = "Itu sudah semestinya. Hanya saja, kita dan mereka berjalan bersama sepanjang jalan, mengucapkan perpisahan secara langsung lebih tepat."
  },
  AvgDialog_19043_Content_46 = {
    Text = "Saya rasa tidak perlu, mereka masih muda, selama perjalanan sudah terlalu banyak mengalami lelah, tadi sudah tidur."
  },
  AvgDialog_19043_Content_47 = {
    Text = "Urusan di panti perawatan cukup rumit, saya tidak akan mengantar. Silakan lanjutkan sendiri."
  },
  AvgDialog_19043_Content_48 = {
    Text = "Setelah dikatakan, Francis dengan berani berbalik pergi. Kalian menyaksikan sosoknya menghilang di bayangan ujung koridor, baru menyadari bahwa kalian telah berkeringat dingin."
  },
  AvgDialog_19043_Content_49 = {
    Text = "Lotan, antarkan Penjaga keluar."
  },
  AvgDialog_19043_Content_5 = {
    Text = "Ramona, apakah Komite menyebutkan kapan akan ada orang yang datang?"
  },
  AvgDialog_19043_Content_50 = {
    Text = "Lalu bagaimana denganmu?"
  },
  AvgDialog_19043_Content_51 = {
    Text = "Ramona mengeluarkan senjatanya, dengan wajah yang serius."
  },
  AvgDialog_19043_Content_52 = {
    Text = "Saya akan mencari Lily."
  },
  AvgDialog_19043_Content_6 = {
    Text = "...Aku selalu bersamamu, apakah kamu melihat aku memberi tahu siapa pun?"
  },
  AvgDialog_19043_Content_7 = {
    Text = "Tidak——apakah kau menipunya?!"
  },
  AvgDialog_19043_Content_8 = {
    Text = "Saya pikir bisa mengorek sedikit informasi darinya, tapi dia tidak menunjukkan sedikit pun celah."
  },
  AvgDialog_19043_Content_9 = {
    Text = "Saat melakukan penggeledahan tadi, saya memperhatikan bahwa di sini tidak ada sedikit pun D-marka."
  },
  AvgDialog_19044_Content_1 = {
    Text = "Setelah pertempuran sengit, Lily yang melindungi Francis sambil melakukan serangan sudah kehabisan tenaga, tampak jelas kelelahannya."
  },
  AvgDialog_19044_Content_10 = {
    Text = "\"Yang telah menjadi mangsa sebanyak tiga kali, jiwanya pasti akan kembali ke alam baka\"…"
  },
  AvgDialog_19044_Content_11 = {
    Text = "Benar, semua orang di sini dianggap oleh-Nya sebagai pelintas dimensi… dianggap sebagai mangsa Anjing Dimensi."
  },
  AvgDialog_19044_Content_12 = {
    Text = "Hei, wanita sialan, kau pasti tahu cara menghadapi orang ini, kan?"
  },
  AvgDialog_19044_Content_13 = {
    Text = "...Benar. Metodenya memang cukup sederhana."
  },
  AvgDialog_19044_Content_14 = {
    Text = "Perburuan monster ini adalah <Yellow:secara teratur melintasi semua Dimensi>."
  },
  AvgDialog_19044_Content_15 = {
    Text = [[
Jadi, di semua dimensi <Yellow:hanya ada satu-satunya "Anjing neraka">.
Selama Dia dikurung dalam sangkar, Dia tidak akan bisa memberikan kerusakan kepada siapa pun lagi.]]
  },
  AvgDialog_19044_Content_16 = {
    Text = "Bicara seenaknya! Bagaimana cara menangkap seekor anjing yang bisa berpindah dimensi!"
  },
  AvgDialog_19044_Content_17 = {
    Text = "... sandi di dinding. Dia muncul setelah sandi itu rusak."
  },
  AvgDialog_19044_Content_18 = {
    Text = "Pengamatanmu sangat tajam, nak. Sandi rahasia ini adalah sesuatu yang dijual oleh Wanita Narsis tadi kepadaku, dengan harga setelah aku mati harus memberikan kepalaku padanya."
  },
  AvgDialog_19044_Content_19 = {
    Text = "Lalu, apakah kamu masih bisa memperbaikinya?"
  },
  AvgDialog_19044_Content_2 = {
    Text = "Beberapa kali kista hitamnya tertusuk, untungnya dia bereaksi tepat waktu sehingga tidak terluka parah. Jika pertarungan berlanjut lebih lama, kemungkinan besar dia akan kehabisan tenaga sepenuhnya."
  },
  AvgDialog_19044_Content_20 = {
    Text = "Francis tercengang, seakan-akan dia tak pernah memikirkan pertanyaan ini sebelumnya."
  },
  AvgDialog_19044_Content_21 = {
    Text = "Cepat katakan, apakah bisa atau tidak?"
  },
  AvgDialog_19044_Content_22 = {
    Text = [[
Gambar itu terpahat dengan kuat di dalam otakku. 
 Namun, aku harus menggambarkannya dengan sangat teliti, tanpa sedikit pun penyimpangan.]]
  },
  AvgDialog_19044_Content_23 = {
    Text = "Saya membutuhkan lebih banyak waktu."
  },
  AvgDialog_19044_Content_24 = {
    Text = "Jika hanya soal waktu, serahkan saja pada kami."
  },
  AvgDialog_19044_Content_25 = {
    Text = "Lotan, maju!"
  },
  AvgDialog_19044_Content_26 = {
    Text = "Ha, sudah menunggu lama!"
  },
  AvgDialog_19044_Content_27 = {
    Text = "Jangan gegabah, perhatikan konsumsi!"
  },
  AvgDialog_19044_Content_3 = {
    Text = "Jangan berdiam diri! Apakah kita akan membiarkan anak itu melawan monster sendirian!"
  },
  AvgDialog_19044_Content_4 = {
    Text = "Tidak berguna… Tidak berguna!"
  },
  AvgDialog_19044_Content_5 = {
    Text = "Makhluk itu adalah <Yellow:monster hukum sebab-akibat>."
  },
  AvgDialog_19044_Content_6 = {
    Text = "Monster hukum sebab-akibat?"
  },
  AvgDialog_19044_Content_7 = {
    Text = "Artinya, monster ini ada karena hubungan sebab-akibat. Selama ada sebab, pasti akan ada akibat."
  },
  AvgDialog_19044_Content_8 = {
    Text = [[
<Yellow: Begitu seseorang memulai perjalanan melintasi Dimensi, Dia akan mulai memburu pelanggar ini.>
Tak peduli bagaimana prosesnya berubah, Dia tidak mati dan tidak bisa dimusnahkan hingga perburuan selesai.]]
  },
  AvgDialog_19044_Content_9 = {
    Text = "Dan ruang operasi ini, setelah dimodifikasi, waktu telah dipisahkan dari Dimensi secara independen."
  },
  AvgDialog_19045_Content_1 = {
    Text = "Fragmen Memori"
  },
  AvgDialog_19045_Content_10 = {
    Text = "3.Percobaan mengekang ■■■■ Anjing Pemburu\n3.1 Percobaan pertama mengekang ■■■■ Anjing Pemburu:\nGagal. Tidak dapat mengekang gerakan berpindahnya.\nRencana menyesuaikan skala dan presisi ukiran Lingkaran Sihir.\n \n3.2 Percobaan ke-51 mengekang ■■■■ Anjing Pemburu:\nGagal. Tidak dapat ■■■ gerakan berpindahnya.\nObjek yang diburu tidak bisa keluar dari ruang tertutup."
  },
  AvgDialog_19045_Content_11 = {
    Text = "3.3 Eksperimen pengurungan ke-73 terhadap Anjing pemburu ■■■■: \nGagal. Tidak dapat mengurung gerakan perpindahannya. \nNamun, setelah Anjing pemburu ■■■■ menyelesaikan perburuan, ia berkeliling di ruang tertutup selama sekitar ■ menit sebelum keluar melalui celah ■■■. \nRencana untuk menyesuaikan presisi ukiran pada teks rahasia ■■. \n \n3.4 Eksperimen ■■■■■■ terhadap Anjing pemburu ■■■■: \nBerhasil. \nAnjing pemburu ■■■■ berhasil dikunci dalam ruang berukuran panjang 2,86 kaki, lebar 2,08 kaki, dan tinggi ■ kaki. \nPenguncian berlangsung selama ■■■■■■, namun karena ■■ rusak dalam Pertempuran ■■■■, menyebabkan Anjing pemburu ■■■■ lolos. \nMenurut perhitungan, ruang berbentuk balok serupa adalah ■■■■ optimal untuk mengurung Anjing pemburu ■■■■. \nRencana untuk meningkatkan ■■■■■■■■■. \n\n3.5 ■■■■■■■■■■■■■■■■\nTingkat kesulitan mengurung Anjing pemburu ■■■■ terlalu tinggi, tetapi mengurung diri sendiri untuk menghindari kejarannya mungkin merupakan metode yang layak. \n■■■■■■■■■■"
  },
  AvgDialog_19045_Content_12 = {
    Text = "Bagian arsip ini terlalu banyak yang dihapus."
  },
  AvgDialog_19045_Content_13 = {
    Text = [[
Inilah gaya Dafude'er. 
 Hak penjelasan ada di tangannya, tapi dia menyebutnya sebagai transaksi yang adil.]]
  },
  AvgDialog_19045_Content_14 = {
    Text = "Sudah selesai? Jika terus berlama-lama, adik kecil yang menunggu pertolonganmu akan dimakan oleh monster."
  },
  AvgDialog_19045_Content_15 = {
    Text = "Mari berangkat."
  },
  AvgDialog_19045_Content_16 = {
    Text = "Sebelum itu, sepertinya kita perlu menyelesaikan beberapa masalah yang cukup rumit."
  },
  AvgDialog_19045_Content_17 = {
    Text = "Aku dan Ramona adalah teman sekelas..."
  },
  AvgDialog_19045_Content_18 = {
    Text = "Sebelum mengobrol, sepertinya kita perlu menyelesaikan beberapa masalah yang sulit terlebih dahulu."
  },
  AvgDialog_19045_Content_19 = {
    Text = "Tidak, kalian yang perlu menangani masakan."
  },
  AvgDialog_19045_Content_2 = {
    Text = "Jujur, aku sangat kagum dengan kemampuanmu untuk langsung tidur dalam situasi apa pun."
  },
  AvgDialog_19045_Content_20 = {
    Text = "<BigShake:Raung!>"
  },
  AvgDialog_19045_Content_3 = {
    Text = "...Apa situasinya sekarang?"
  },
  AvgDialog_19045_Content_4 = {
    Text = [[
Selesai, jika aku bisa terjebak dengan masalah seperti ini, apa bedanya otakku dengan Lotan? 
Pakailah ini.]]
  },
  AvgDialog_19045_Content_5 = {
    Text = "Boneka memberikan sebuah fragmen logam segitiga kecil berwarna perak."
  },
  AvgDialog_19045_Content_6 = {
    Text = "Tertanam di bros-mu, jangan sampai hilang."
  },
  AvgDialog_19045_Content_7 = {
    Text = "Ngomong-ngomong, tadi William mengirimkan sebuah dokumen, sepertinya dikirim oleh Dafudeer untukmu."
  },
  AvgDialog_19045_Content_8 = {
    Text = "Kode Nama: Kerberos\n\nSejak dimensi ditemukan, melintasi dimensi merupakan tabu bagi sebagian besar makhluk hidup. Ancamannya tidak hanya berasal dari lingkungan bertahan hidup yang abnormal antar dimensi dan tekanan visual akibat informasi ultra, tetapi juga karena keberadaan \"penegak hukum\" yang ketat di dalam dimensi tersebut.\n<Yellow:■■■■Anjing pemburu dapat muncul di semua dimensi, secara berurutan memburu semua makhluk hidup yang pernah melintasi dimensi.>"
  },
  AvgDialog_19045_Content_9 = {
    Text = "1. Kegagalan dalam pemburuan\nHanya ada beberapa jenis makhluk di alam semesta yang dapat melarikan diri dari pandangan mereka.\nDiketahui bahwa ras ■■ dapat menghindari pandangan anjing pemburu ■■■■ melalui teknologi transfer roh, sehingga dapat diasumsikan bahwa anjing pemburu tidak memiliki kemampuan untuk melacak dan berburu roh.\nMemverifikasi logika pelacakan mereka melalui pola transfer sebagian tubuh dan roh.\nEksperimen 1: Memindahkan bagian ekor objek yang tidak terkunci ke dimensi lain. Anjing pemburu ■■■■ tidak melakukan pelacakan.\nEksperimen 2: Memotong lengan objek yang sudah terkunci dan memindahkannya ke dimensi lain. Objek eksperimen dimelahap di dimensi aslinya. Anjing pemburu ■■■■ tidak melacak lengan tersebut.\nEksperimen 3: Memindahkan roh objek yang tidak terkunci ke dimensi lain. Anjing pemburu ■■■■ tidak melakukan pelacakan.\nKesimpulan eksperimen: Hanya ketika tubuh dan roh bersatu, anjing pemburu ■■■■ dapat mengunci target yang sesuai.\n\n2. Upaya membunuh anjing pemburu ■■■■\n■■. Luka fatal dalam arti umum akan menyebabkan anjing pemburu ■■■■ tetap hidup.\nAnjing pemburu ■■■■ dapat dikategorikan sebagai makhluk abadi, memotong bentuk fisiknya hanya dapat memperlambat tindakannya untuk sementara."
  },
  AvgDialog_19046_Content_1 = {
    Text = "Kamu kalah lagi. Ini yang ketiga kalinya."
  },
  AvgDialog_19046_Content_10 = {
    Text = [[
Jadi kamu ingin membalas dendam kepada penghianat, ingin melindungi Francis yang menyelamatkanmu.
Tetapi pertempuran tidak boleh seperti ini.]]
  },
  AvgDialog_19046_Content_11 = {
    Text = [[
Bukan demi melindungi, bukan demi balas dendam, bukan demi mencari jawaban.
Pertarungan hanyalah pertarungan, tidak lebih.]]
  },
  AvgDialog_19046_Content_12 = {
    Text = "Duniamu terlalu sempit, makanya kau selalu seperti ngengat yang terpaku pada secercah cahaya kecil yang dinyalakan orang lain."
  },
  AvgDialog_19046_Content_13 = {
    Text = "Jika ada kesempatan, pergilah melihat dunia yang lebih luas."
  },
  AvgDialog_19046_Content_14 = {
    Text = "Lotan berjalan melewatinya, terus maju tanpa menoleh sama sekali."
  },
  AvgDialog_19046_Content_2 = {
    Text = [[
Ini tidak... mungkin... 
Mengapa?]]
  },
  AvgDialog_19046_Content_3 = {
    Text = "Helot berlutut dengan posisi kekalahan, rambut panjangnya terjerat dalam genangan darah yang menetes, dan dari tenggorokannya terdengar dengungan serak."
  },
  AvgDialog_19046_Content_4 = {
    Text = "Jika aku ingin meresponsmu dengan tidak serius, aku akan memberitahumu bahwa ini adalah kesenjangan mutlak dalam kekuatan."
  },
  AvgDialog_19046_Content_5 = {
    Text = [[
Namun, kenyataannya tidak demikian.
Kelincahanmu cukup gesit, dan teknik pertempuranmu juga sangat matang.]]
  },
  AvgDialog_19046_Content_6 = {
    Text = "Lotan perlahan melangkah maju dengan pedang di tangan, melewati sisi Helot."
  },
  AvgDialog_19046_Content_7 = {
    Text = "Tetapi kamu begitu bingung, kamu masih mencari makna dari pertempuranmu."
  },
  AvgDialog_19046_Content_8 = {
    Text = "Di jembatan kereta api, kamu pernah menjadi monster yang tidak berpengetahuan... kamu telah dikhianati oleh penghubung, bukan?"
  },
  AvgDialog_19046_Content_9 = {Text = "!"},
  AvgDialog_19047_Content_1 = {
    Text = "Kalian bertanya kepada beberapa pasien yang sadar di Rumah sakit lai."
  },
  AvgDialog_19047_Content_2 = {
    Text = "Semua orang menilai Francis sebagai \"tampak tegas, tetapi sebenarnya sangat bertanggung jawab.\""
  },
  AvgDialog_19048_Content_1 = {
    Text = "Tidak akan membiarkan kalian bertemu dengan Nyonya Ozwood..."
  },
  AvgDialog_19049_Content_1 = {
    Text = "Saat kamu melangkah di atas jalan berbatu di luar sanatorium, perasaan tertekan itu akhirnya menghilang."
  },
  AvgDialog_19049_Content_10 = {
    Text = "Lotan! Saatnya kamu dan Penjaga bertindak!"
  },
  AvgDialog_19049_Content_11 = {
    Text = "Baiklah, baiklah! Jangan seenaknya memberi perintah padaku, aku bukan anjing penjaga yang kau pelihara!"
  },
  AvgDialog_19049_Content_2 = {
    Text = "Cahaya dari bros Perak juga menjadi lebih lembut dan bercahaya, mendapatkan kembali Hidupnya."
  },
  AvgDialog_19049_Content_3 = {
    Text = "Kamu sedang bersiap untuk menghubungi Mythag ketika mendengar panggilan dari Boneka yang lebih jelas daripada suara melalui komunikasi."
  },
  AvgDialog_19049_Content_4 = {
    Text = "Apa yang kalian tunggu? Cepat bantu!"
  },
  AvgDialog_19049_Content_5 = {
    Text = "Boneka?! Bagaimana bisa kamu ada di sini?"
  },
  AvgDialog_19049_Content_6 = {
    Text = "Saya tidak tahu bagaimana pola pikiran yang begitu lancar bisa membuatmu mengajukan pertanyaan seperti itu, kalian <Yellow:kehilangan kontak selama sepuluh hari>, namun kamu malah bertanya mengapa aku bisa berada di sini?"
  },
  AvgDialog_19049_Content_7 = {
    Text = "Sepuluh hari?! Tapi aku baru saja..."
  },
  AvgDialog_19049_Content_8 = {
    Text = "Tidak ada waktu untuk pertunjukan deduksi yang panjang lebar."
  },
  AvgDialog_19049_Content_9 = {
    Text = "Entah sejak kapan, orang aneh berbalut kain hitam sudah sepenuhnya mengelilingi kalian."
  },
  AvgDialog_19050_Content_1 = {
    Text = "Kantor Francis... berputar-putar, akhirnya kembali ke sini lagi."
  },
  AvgDialog_19050_Content_2 = {
    Text = "Yah, mencari sekali lagi tidak ada salahnya."
  },
  AvgDialog_19051_Content_1 = {
    Text = [[
Meskipun kondisi di panti rehabilitasi agak memprihatinkan dan kekurangan perabotan, namun masih terlihat rapi dan bersih. 
 Setelah berkeliling beberapa kali, kalian tidak menemukan apa pun selain pasien dan perlengkapan medis biasa.]]
  },
  AvgDialog_19051_Content_10 = {
    Text = "Risiko tidak terhindarkan."
  },
  AvgDialog_19051_Content_11 = {
    Text = "Ramona menurut, mendorong pintu kayu berat yang dingin dan menekan."
  },
  AvgDialog_19051_Content_12 = {
    Text = "Angin dingin berhembus keluar dari pintu, diikuti oleh sosok setinggi separuh manusia yang menyusul dengan erangan dan melompat keluar."
  },
  AvgDialog_19051_Content_2 = {
    Text = "Akhirnya, kalian berhenti di depan papan bertuliskan \"Ruang Direktur. Dilarang Masuk Kecuali Berkepentingan\"."
  },
  AvgDialog_19051_Content_3 = {
    Text = "Jika ada rahasia tersembunyi di panti rehabilitasi, itu pasti berada di sini."
  },
  AvgDialog_19051_Content_4 = {
    Text = "Maukah aku membantu kalian menjebol pintu?"
  },
  AvgDialog_19051_Content_5 = {
    Text = "Tidak perlu, lagipula——"
  },
  AvgDialog_19051_Content_6 = {
    Text = "Dia memegang gagang pintu dan memutarnya perlahan, lalu pintu terbuka dengan sendirinya."
  },
  AvgDialog_19051_Content_7 = {
    Text = "Tidak terkunci?"
  },
  AvgDialog_19051_Content_8 = {
    Text = "Percayalah, aku juga sama terkejutnya denganmu."
  },
  AvgDialog_19051_Content_9 = {Text = "Masuklah."},
  AvgDialog_19052_Content_1 = {
    Text = "Matahari terbenam"
  },
  AvgDialog_19052_Content_10 = {
    Text = "Pada saat itu, aku sama sekali tidak merasakan sakit, benar-benar tidak ada rasa sakit."
  },
  AvgDialog_19052_Content_11 = {
    Text = "Kemudian, segalanya menjadi sedikit berbeda. Ibu mengurungku dan melakukan lebih banyak eksperimen."
  },
  AvgDialog_19052_Content_12 = {
    Text = [[
Tapi ini bukan salah Ibu. 
Karena, Ibu juga terkurung bersamaku di kamar ini, yang tidak bisa kami tinggalkan.]]
  },
  AvgDialog_19052_Content_13 = {
    Text = [[
Karena aku, aku kehilangan kendali dan menyebabkan banyak orang meninggal. 
Karena aku... terlalu menderita.]]
  },
  AvgDialog_19052_Content_14 = {
    Text = "Lisa berkata, \"Karena dia adalah satu-satunya temanku, dia akan berusaha untuk menemaniku lebih lama.\""
  },
  AvgDialog_19052_Content_15 = {
    Text = "Kalau tidak, dia sudah lama menyerah."
  },
  AvgDialog_19052_Content_16 = {
    Text = "...sebenarnya aku juga, sudah tidak kuat lagi."
  },
  AvgDialog_19052_Content_17 = {
    Text = "Makhluk raksasa merobek lebih banyak ruang, cakarnya langsung mengarah ke Lily."
  },
  AvgDialog_19052_Content_19 = {
    Text = "Di depan gadis berpakaian putih yang tampak rapuh, cairan hitam berkumpul menjadi bola dan jaring, menangkis serangan-Nya satu per satu."
  },
  AvgDialog_19052_Content_2 = {
    Text = "Lily melangkah maju dengan kakinya yang lembut, cairan hitam kental berkumpul dan terbentuk di sekitar kakinya."
  },
  AvgDialog_19052_Content_20 = {
    Text = "Namun, meskipun begitu——"
  },
  AvgDialog_19052_Content_21 = {
    Text = "Itu juga ibu saya yang satu-satunya."
  },
  AvgDialog_19052_Content_23 = {
    Text = "Tidak boleh——memberikan kerusakan pada ibuku!"
  },
  AvgDialog_19052_Content_24 = {
    Text = "Bola hitam meledak, berkumpul menjadi duri, dan menancapkan cakar Anjing Neraka."
  },
  AvgDialog_19052_Content_25 = {
    Text = "Bola lendir yang tersisa membuka gigi tajam seperti belati dan menggigit putus pergelangan kaki yang terikat."
  },
  AvgDialog_19052_Content_27 = {
    Text = "Dia sepenuhnya membelah ruang, waktu yang membeku perlahan-lahan meloloskan diri dari celah itu, sinar matahari senja sepenuhnya dilahap."
  },
  AvgDialog_19052_Content_28 = {
    Text = [[
Cakar itu lenyap menjadi asap ungu iblis, lalu kembali terbentuk. 
 Dan anggota tubuh heterogen yang terdistorsi itu muncul dari celah ruang, menyerbu ke arah Lily!]]
  },
  AvgDialog_19052_Content_3 = {
    Text = "Lisa mengatakan bahwa ibunya sudah tidak mengenalinya lagi dan bahkan melukainya dengan senapan."
  },
  AvgDialog_19052_Content_30 = {
    Text = "Kamu bertukar pandang dengan Ramona, lalu bergabung dalam pertempuran."
  },
  AvgDialog_19052_Content_4 = {
    Text = "Lisa berkata bahwa ibunya sangat tegas. Setiap kali dia bermain denganku, ibunya akan memukul dan memarahinya."
  },
  AvgDialog_19052_Content_5 = {
    Text = "Lisa berkata, \"Jika ibuku tahu bahwa aku berubah menjadi anjing besar karena keluar bersamamu, dia pasti tidak akan memaafkanku.\""
  },
  AvgDialog_19052_Content_6 = {
    Text = "Tetapi dia tidak bisa menahan diri, dia terlalu lapar. Karena tidak ingin mencuri barang milik orang lain, dia akhirnya pulang untuk mencari makanan… dan baru kemudian dia ketahuan oleh ibunya…"
  },
  AvgDialog_19052_Content_7 = {
    Text = "Lily berhenti sejenak."
  },
  AvgDialog_19052_Content_8 = {
    Text = "Namun, ibuku tidak sama."
  },
  AvgDialog_19052_Content_9 = {
    Text = "Dia mengira aku orang lain, tetapi saat dia pertama kali menyayatku dengan pisau bedah, dia berkata maaf padaku."
  },
  AvgDialog_19053_Content_1 = {
    Text = "Aroma di sini... agak tidak biasa."
  },
  AvgDialog_19053_Content_2 = {
    Text = [[
Rasa. 
 Cara kamu menilai situasi ini benar-benar tidak berbeda dari Kuum.]]
  },
  AvgDialog_19053_Content_3 = {
    Text = "Sepertinya tidak perlu mengandalkan bau untuk mengetahuinya, mereka sudah datang."
  },
  AvgDialog_19054_Content_1 = {
    Text = "Kamu selalu suka menantang tugas yang tampaknya mustahil untuk diselesaikan."
  },
  AvgDialog_19054_Content_2 = {
    Text = [[
Di pertarungan bawah tanah pertama, kekuatanku dibatasi oleh Herbert. 
 Dalam pertarungan kedua, aku muncul dalam kondisi yang paling memalukan.]]
  },
  AvgDialog_19054_Content_3 = {
    Text = "Sekarang, Francis memberi saya kesempatan untuk bertanding secara adil denganmu."
  },
  AvgDialog_19054_Content_4 = {
    Text = "Sebanyak apapun pemberi daya, tetap tidak bisa menyembuhkan kelemahan batin."
  },
  AvgDialog_19054_Content_5 = {
    Text = "Tak perlu banyak bicara, rasakan sekarang juga kemarahan sang Pembalas!"
  },
  AvgDialog_19055_Content_1 = {
    Text = "<Shake:Ibu...anak...>"
  },
  AvgDialog_19055_Content_10 = {
    Text = "Kenapa tidak memberi tahu ibumu bahwa kamu sudah bisa merasakan sakit lagi?"
  },
  AvgDialog_19055_Content_11 = {
    Text = "Jika kamu sudah merasakan sakit, kenapa tidak pernah mengatakannya sama sekali?"
  },
  AvgDialog_19055_Content_12 = {
    Text = "<Shake: Ibu berkata… anak baik… tidak takut sakit…>"
  },
  AvgDialog_19055_Content_13 = {
    Text = "<Shake:Tapi... Ibu... sakit... Lily... sangat sakit...>"
  },
  AvgDialog_19055_Content_14 = {
    Text = "Di wajah Lily, mengalir dua garis air mata hitam yang bercampur dengan cairan pelarutan."
  },
  AvgDialog_19055_Content_15 = {
    Text = "Lily... kamu..."
  },
  AvgDialog_19055_Content_16 = {
    Text = "<Shake: Ibu... sakit...>"
  },
  AvgDialog_19055_Content_17 = {
    Text = "Tidak... meskipun kau memiliki rasa sakit seperti manusia, kau tetap saja monster..."
  },
  AvgDialog_19055_Content_18 = {
    Text = "<Small:Kamu bukan anakku…>\n<Small>Anakku yang sebenarnya, sudah tidak ada di mana pun…>"
  },
  AvgDialog_19055_Content_19 = {
    Text = [[
Francis mundur dengan putus asa, menyenggol meja operasi. 
 Peralatan eksperimen jatuh ke boneka di kepala tempat tidur dan ke selimut kelinci di lantai.]]
  },
  AvgDialog_19055_Content_2 = {
    Text = "Lily, kamu sebenarnya tidak ingin berpartisipasi dalam pertempuran dengan kami, kan?"
  },
  AvgDialog_19055_Content_20 = {
    Text = "<Italic:Jingling... Jingling...>"
  },
  AvgDialog_19055_Content_21 = {
    Text = "Di tengah-tengah pisau bedah yang berserakan, dering telepon tiba-tiba berbunyi, merobek suasana tegang di dalam kamar tidur. Tidak ada yang mengangkat telepon, namun suara seorang pria terdengar melalui gagang telepon."
  },
  AvgDialog_19055_Content_22 = {
    Text = "Halo semuanya."
  },
  AvgDialog_19055_Content_23 = {
    Text = "Herbert! Di mana Boneka?!"
  },
  AvgDialog_19055_Content_24 = {
    Text = "Dia? Tentu saja dia hancur menjadi abu di depanku."
  },
  AvgDialog_19055_Content_25 = {
    Text = "Inilah solidaritas kalian di Mythag — meninggalkan rekan setim pada saat genting, \"berkorban secara heroik\"."
  },
  AvgDialog_19055_Content_26 = {
    Text = "Ngomong-ngomong, saya melihat \"<Yellow:si raksasa besar itu>\" semakin dekat, sepertinya kalian sudah sangat dekat dengan kebenaran."
  },
  AvgDialog_19055_Content_27 = {
    Text = "Sebagai balasan atas usaha kalian semua dalam menjelajah, aku akan dengan murah hati memberikan kalian sebuah jawaban yang luar biasa."
  },
  AvgDialog_19055_Content_28 = {
    Text = [[
"Tok tok tok," terdengar suara ketukan pintu yang tidak terburu-buru. 
Hanya dari suara ini, kalian bisa merasakan sikap tamu yang datang dengan santai.]]
  },
  AvgDialog_19055_Content_29 = {
    Text = "Tidak ada yang menjawab ketika pintu diketuk, namun pintu tetap terbuka dengan sendirinya."
  },
  AvgDialog_19055_Content_3 = {
    Text = "<Shake:Ini... adalah perintah... dari tuan...>"
  },
  AvgDialog_19055_Content_30 = {
    Text = "Yang berdiri di sana adalah sang Wanita Ungu, yang selalu tersenyum dengan sikap anggun dan elegan."
  },
  AvgDialog_19055_Content_31 = {
    Text = "Ada apa, apakah tidak ada yang menyambutku?"
  },
  AvgDialog_19055_Content_4 = {
    Text = "Lily, kamu sama sekali tidak mau mendengarkan perkataan Tuan!"
  },
  AvgDialog_19055_Content_5 = {
    Text = [[
Karena kamu sudah ingat, kan? 
 Kamu sekarang adalah "kamu" dan bukan lagi "monster itu"!]]
  },
  AvgDialog_19055_Content_6 = {
    Text = "Apakah kamu bisa <Yellow:merasakan sakit>, kan?"
  },
  AvgDialog_19055_Content_7 = {
    Text = "\"Dengan suara 'plak', janda itu menampar Lily.\""
  },
  AvgDialog_19055_Content_8 = {
    Text = "Lily menutupi wajahnya, mundur dua langkah, dan bersembunyi di belakang %player%."
  },
  AvgDialog_19056_Content_1 = {
    Text = "Kalian berhasil mengusir monster aneh itu. Derap langkah kaki yang cepat terdengar di koridor, dan pintu kantor didorong terbuka dari luar."
  },
  AvgDialog_19056_Content_10 = {
    Text = "Benar-benar di luar dugaanmu, Ramona melancarkan serangan langsung."
  },
  AvgDialog_19056_Content_11 = {
    Text = "Francis tetap tenang sambil memiringkan kepalanya, tampaknya sama sekali tidak terkena serangan Ramona."
  },
  AvgDialog_19056_Content_12 = {
    Text = "Modifikasi tubuh? Mungkin ada kesalahpahaman di sini."
  },
  AvgDialog_19056_Content_13 = {
    Text = "Rumah perawatan ini hanya memiliki dua lantai dengan total tidak lebih dari dua puluh kamar. Sebagai direktur, saya melakukan inspeksi setiap hari. Jika ada yang melakukan eksperimen ilegal, saya pasti akan mengetahuinya."
  },
  AvgDialog_19056_Content_14 = {
    Text = "Ramona mengerutkan alis."
  },
  AvgDialog_19056_Content_15 = {
    Text = [[
Seseorang tidak bisa menjadi saksi bagi dirinya sendiri, Nyonya. Anda pasti memahami hal itu. 
 Apalagi, ada cukup banyak bukti yang merugikanmu di sekitar kita.]]
  },
  AvgDialog_19056_Content_16 = {
    Text = "\"Mia\" ini... sepertinya Anda sudah melakukan banyak operasi padanya, kan?"
  },
  AvgDialog_19056_Content_17 = {
    Text = [[
Dan juga Lily.
Jika kamu mengaku sebagai ibunya, mustahil bagi kamu untuk tidak mengetahui bahwa dia bukan manusia.]]
  },
  AvgDialog_19056_Content_18 = {
    Text = "Francis sedikit terkejut, lalu tertawa kecil."
  },
  AvgDialog_19056_Content_19 = {
    Text = "Para hadirin mungkin benar-benar salah paham. Lily memanggilku \"ibu,\" tapi aku belum tentu adalah ibunya kandungnya."
  },
  AvgDialog_19056_Content_2 = {Text = "Mia!"},
  AvgDialog_19056_Content_20 = {
    Text = "Dia adalah anak yatim yang kuselamatkan dari sarang pencuri. Semua kelainan pada tubuhnya disebabkan oleh para penjahat keji yang pertama kali menculiknya."
  },
  AvgDialog_19056_Content_21 = {
    Text = "Adapun Kum dan Mia, mereka adalah hewan peliharaan yang Lily temukan dari luar. Bahkan saya pun tidak tahu dari mana tepatnya mereka berasal."
  },
  AvgDialog_19056_Content_22 = {
    Text = "Tentu saja, orang biasa yang melihat penampilan Kuum dan Mia, meskipun tidak merasa takut, setidaknya akan bersikap hati-hati dan menjaga jarak mereka dari anak-anak."
  },
  AvgDialog_19056_Content_23 = {
    Text = "Namun, saat masih muda, saya pernah mengalami sebuah \"petualangan aneh\" dan menyaksikan beberapa keajaiban yang jarang terdengar oleh orang biasa."
  },
  AvgDialog_19056_Content_24 = {
    Text = "Jadi, meskipun Kum tampak agak... tidak biasa, karena Lily menyukainya, aku pun memutuskan untuk tetap membiarkannya tinggal. Lagipula, Kum adalah teman yang sulit ditemukan oleh Lily."
  },
  AvgDialog_19056_Content_25 = {
    Text = "Anak ini sudah memiliki jarak yang cukup besar dengan orang lain, bagaimana mungkin aku tega memisahkan mereka?"
  },
  AvgDialog_19056_Content_27 = {
    Text = "Jika ini masih belum bisa menghilangkan keraguan kalian, saya bersedia menemani kalian semua untuk memeriksa ulang di sanatorium, termasuk ruangan kantor saya."
  },
  AvgDialog_19056_Content_28 = {
    Text = "Tenang saja, sebelum Komite datang, aku tidak akan pergi ke mana-mana."
  },
  AvgDialog_19056_Content_3 = {
    Text = "Groaaa——"
  },
  AvgDialog_19056_Content_4 = {
    Text = "Aku bilang, kenapa tidak bisa menemukanmu di mana pun, ternyata kamu ada di sini. Cepat ikut aku——"
  },
  AvgDialog_19056_Content_5 = {
    Text = "Melihat kalian, Francis menghentikan ucapannya."
  },
  AvgDialog_19056_Content_6 = {
    Text = "Sepertinya aku sudah mengingatkan kalian berdua, ruang kerja dilarang dikunjungi, kan?"
  },
  AvgDialog_19056_Content_7 = {
    Text = "Maaf, tetapi \"kunjungan\" mungkin harus berakhir di sini."
  },
  AvgDialog_19056_Content_8 = {
    Text = "Berdasarkan Pasal 81, Butir A dari \"Perjanjian\", tanpa persetujuan dan otorisasi dari <Blue:Komite perjanjian mystia>, setiap individu, organisasi, atau lembaga dilarang melakukan eksperimen terhadap manusia atau entitas individu yang tidak dikenal."
  },
  AvgDialog_19056_Content_9 = {
    Text = "Saat ini, kami mencurigai adanya aktivitas modifikasi tubuh di panti rehabilitasi, dan sudah menghubungi <Blue:Komite>. Mereka akan menutup panti rehabilitasi. Mohon kerja samanya."
  },
  AvgDialog_19057_Content_1 = {
    Text = "Dari sudut bayangan jembatan baja, muncul beberapa makhluk asing dengan raungan yang membuat darah membeku."
  },
  AvgDialog_19057_Content_10 = {
    Text = "Setiap kali dia tidak bisa bernapas, dia berharap bisa bernapas seperti ikan."
  },
  AvgDialog_19057_Content_11 = {
    Text = "Untuk mencari dokter terkenal demi menyembuhkan penyakit anehnya, orang tuanya sering bepergian untuk berdagang. Karena kondisinya yang lemah dan tidak bisa bepergian jauh, orang tuanya menitipkannya di sanatorium, di mana ia tumbuh dewasa ditemani oleh buku-buku puisi."
  },
  AvgDialog_19057_Content_12 = {
    Text = "…Pada saat itu, tidak ada seorang pun yang memberitahunya bahwa itu bukan penyakit, melainkan fenomena misterius yang disebut \"Pelarutan\"."
  },
  AvgDialog_19057_Content_13 = {
    Text = "Panti jompo tempat dia tinggal menganggapnya sebagai pembawa penyakit yang menakutkan, mengenakan biaya pengelolaan yang tinggi, dan petugas pengantar makanan juga menolak untuk berkomunikasi dengannya."
  },
  AvgDialog_19057_Content_14 = {
    Text = [[
Semakin lama dia tinggal, semakin orang tuanya tidak dapat menemaninya. 
 Selain puisi dan lautan, tak ada yang menerima keberadaannya.]]
  },
  AvgDialog_19057_Content_15 = {
    Text = "Kemudian, orang tuanya meninggal dalam bencana laut. Dia diusir dari panti rehabilitasi dan hanya bisa memilih untuk kembali ke laut sendirian."
  },
  AvgDialog_19057_Content_16 = {
    Text = "Permisi, jika ada seorang dokter yang secara khusus melakukan penelitian tentang pelarutan, dan dia diberi tempat tinggal serta diperlakukan sebagai orang biasa yang terpengaruh oleh fenomena misterius, apakah dia seharusnya menunjukkan rasa terima kasih melalui tindakan?"
  },
  AvgDialog_19057_Content_17 = {
    Text = "Sekarang, saatnya tiba."
  },
  AvgDialog_19057_Content_2 = {
    Text = "Di belakang makhluk asing itu, terdapat seorang gadis muda mengenakan rok hitam."
  },
  AvgDialog_19057_Content_3 = {
    Text = "Salam sejahtera. Senang bisa bertemu dengan Anda kembali."
  },
  AvgDialog_19057_Content_4 = {
    Text = "Meskipun agak meminta maaf, bisakah kalian semua untuk sementara waktu meninggalkan La Yi?"
  },
  AvgDialog_19057_Content_5 = {
    Text = [[
Nymphaea, kamu yang bertanggung jawab merawat pasien, seharusnya tidak mungkin tidak tahu tentang perilaku Francis di sanatorium.
Meskipun begitu, apakah kamu tetap memilih untuk ikut terlibat?]]
  },
  AvgDialog_19057_Content_6 = {
    Text = "…Saya akan menceritakan sebuah cerita kepada kalian."
  },
  AvgDialog_19057_Content_7 = {
    Text = "Dahulu kala, ada seorang gadis muda yang lemah dan sering sakit-sakitan. Ia takut kepada manusia, namun hanya merasa akrab dengan aroma laut."
  },
  AvgDialog_19057_Content_8 = {
    Text = "Namun, laut tidak hanya memberinya ketenangan, tetapi juga semacam penyakit aneh yang menakutkan."
  },
  AvgDialog_19057_Content_9 = {
    Text = "Paru-parunya… perlahan-lahan menghilang."
  },
  AvgDialog_19058_Content_1 = {
    Text = "Jangan berbalik"
  },
  AvgDialog_19058_Content_10 = {Text = "Siap!"},
  AvgDialog_19058_Content_11 = {
    Text = "Semua orang menarik napas dalam-dalam. Lotan dengan sukarela maju ke barisan depan dan mendorong pintu besar sanatorium terbuka——"
  },
  AvgDialog_19058_Content_12 = {
    Text = "Apa. Apa yang terjadi di sini?!"
  },
  AvgDialog_19058_Content_13 = {
    Text = "Di dalam sanatorium, cahaya yang suram dan misterius menyelimuti, dinding dan lantai terbelah dengan retakan. Di balik celah-celah itu terdapat kekacauan yang tak berdasar serta kilauan bintang."
  },
  AvgDialog_19058_Content_14 = {
    Text = [[
Dimensi telah diserang.
Trik yang dilakukan Francis pada ruang waktu... menarik <Yellow:perhatian>.]]
  },
  AvgDialog_19058_Content_15 = {
    Text = "Pemelihara waktu dan ruang telah mencium aroma keberadaannya."
  },
  AvgDialog_19058_Content_16 = {
    Text = "Apakah ini Anjing neraka yang sebenarnya…!"
  },
  AvgDialog_19058_Content_17 = {
    Text = [[
Manfaatkan waktu dengan baik, fokus pada apa yang harus kita lakukan. 
Jangan terlibat dalam konflik langsung dengan-Nya.]]
  },
  AvgDialog_19058_Content_2 = {
    Text = [[
Kalian meninggalkan Nymphaea di seberang Jembatan Baja dan terus maju menuju arah Rumah Sakit Lai.
Setelah melewati jembatan, tidak ada jejak manusia, hanya hawa dingin yang menyelimuti.]]
  },
  AvgDialog_19058_Content_3 = {
    Text = [[
Nymphaea adalah orang yang dikirim untuk menunda waktu, kalau begitu tenang, mungkin perpindahan pasien sudah selesai.
Berita dari Para pematung memang sangat cepat.]]
  },
  AvgDialog_19058_Content_4 = {
    Text = "Francis dan Para pematung, hanya terlihat dekat tetapi hati jauh."
  },
  AvgDialog_19058_Content_5 = {
    Text = "Fokus penelitian Francis adalah metode penyembuhan pelarutan, yang tidak sesuai dengan prinsip Herbert, bahkan cenderung bertentangan."
  },
  AvgDialog_19058_Content_6 = {
    Text = "Ketika dia menyebut Herbert dalam catatannya, dia hanya memandangnya sebagai seorang pembantu dari luar."
  },
  AvgDialog_19058_Content_7 = {
    Text = "Membuka pintu ini berarti kita akan kembali masuk ke dalam sanatorium."
  },
  AvgDialog_19058_Content_8 = {
    Text = "Apakah kalian sudah siap?"
  },
  AvgDialog_19058_Content_9 = {
    Text = "Persiapan untuk membuat kehebohan besar?"
  },
  AvgDialog_19059_Content_1 = {
    Text = "Di sini lebih sunyi daripada yang kubayangkan."
  },
  AvgDialog_19059_Content_10 = {
    Text = [[
Baik, saya mengerti. 
Maaf, ada situasi darurat di sini. Selanjutnya, kalian harus melanjutkan kunjungan secara mandiri.]]
  },
  AvgDialog_19059_Content_11 = {
    Text = [[
Silakan bersikap lebih santai. Selain di kantor saya, Anda bisa menyebut nama saya untuk mendapatkan akses ke tempat lain. 
 Permisi dulu.]]
  },
  AvgDialog_19059_Content_12 = {
    Text = "Francis mengikuti dua pasien itu pergi, sosoknya menghilang di antara bayangan koridor."
  },
  AvgDialog_19059_Content_13 = {
    Text = "Kebetulan, kita bisa melakukan penyelidikan di sini."
  },
  AvgDialog_19059_Content_14 = {
    Text = "Benar. Jika modifikasi Koom dilakukan di sanatorium, pasti akan ada jejak yang tertinggal di sini."
  },
  AvgDialog_19059_Content_2 = {
    Text = [[
Ini juga merupakan prasangka umum terhadap penderita histeria. 
 Sebagian besar waktu, mereka sangat tenang, sama seperti orang biasa.]]
  },
  AvgDialog_19059_Content_3 = {
    Text = "Apakah malam juga?"
  },
  AvgDialog_19059_Content_4 = {
    Text = "Ini benar-benar menyentuh titik lemah saya. Malam hari adalah waktu dengan jumlah keluhan tertinggi."
  },
  AvgDialog_19059_Content_5 = {
    Text = "Namun, saya juga tidak bisa menyalahkan para pasien yang malang itu. Kebanyakan dari mereka telah ditinggalkan oleh keluarga mereka di sini, sering kali emosinya tidak stabil di malam hari, diam-diam menangis atau mengalami serangan penyakit."
  },
  AvgDialog_19059_Content_6 = {
    Text = "Sambil berbicara, Francis mendorong pintu ruang perawatan di depannya."
  },
  AvgDialog_19059_Content_7 = {
    Text = "Dekan, Anda sudah datang."
  },
  AvgDialog_19059_Content_8 = {
    Text = "Hmm, apakah semuanya baik-baik saja?"
  },
  AvgDialog_19059_Content_9 = {
    Text = "Kami tidak apa-apa, tapi Miya terus menangis dan meminta untuk bertemu dengan direktur. Dia sudah menangis cukup lama, tolong periksa dia segera."
  },
  AvgDialog_19060_Content_1 = {Text = "Ini!"},
  AvgDialog_19060_Content_2 = {
    Text = "Dari sudut ruangan, muncul monster yang sangat gelap."
  },
  AvgDialog_19060_Content_3 = {
    Text = "Bekas jahitan yang kasar menunjukkan asal-usul mereka — hasil transformasi dari Para pematung."
  },
  AvgDialog_19061_Content_1 = {
    Text = "Francis sudah ter-link dengan Lily, kalau begitu orang yang ter-link dengan Shilo..."
  },
  AvgDialog_19061_Content_2 = {
    Text = "Dalam kelas \"Dasar-Dasar Pembentukan dan Penautan Pembangun\", pernah dijelaskan bahwa dengan mengesampingkan efek samping yang tidak dapat dikendalikan, objek tautan terbaik untuk Pembangun sebenarnya adalah orang-orang yang kehilangan kemampuan."
  },
  AvgDialog_19061_Content_3 = {
    Text = [[
Pasien sanatorium...?
Karena kondisi mental mereka memang sudah tidak stabil, jadi tidak perlu takut kehilangan kendali?]]
  },
  AvgDialog_19061_Content_4 = {
    Text = "Benar sekali."
  },
  AvgDialog_19061_Content_5 = {
    Text = "Lily, Nymphaea, dan Helot... Pasien-pasien ini sepenuhnya adalah baterai kering bagi Francis."
  },
  AvgDialog_19062_Content_1 = {
    Text = "Huh—syukurlah Francis telah memperkuat pintu, suara gaduh yang baru saja terjadi seharusnya tidak ada yang mendengarnya."
  },
  AvgDialog_19062_Content_10 = {
    Text = "Terima kasih atas penghargaannya, tetapi penelitian ilmiah bukanlah tentang bermain pedang dan senjata, setiap langkah tidak selalu menghasilkan darah."
  },
  AvgDialog_19062_Content_11 = {
    Text = "Saya harus mengingatkanmu, jika sekarang diganti dengan para akademisi tua di departemen penelitian untuk menangani ini, meskipun mereka menghabiskan delapan belas jam lagi, mereka tetap tidak akan menemukan inti dari masalahnya."
  },
  AvgDialog_19062_Content_12 = {
    Text = "Ramona seharusnya sudah keluar, hanya dengan mencari ruangan sebentar, tidak akan memakan banyak waktu…"
  },
  AvgDialog_19062_Content_13 = {
    Text = [[
Ini memang tidak perlu dikhawatirkan. 
 Jika dihitung... bukankah dia hanya berada di dalam selama sekitar belasan menit?]]
  },
  AvgDialog_19062_Content_14 = {
    Text = "Tenang saja, perhitungan saya segera menghasilkan hasil."
  },
  AvgDialog_19062_Content_15 = {
    Text = "Kamu bisa beristirahat sejenak, kami akan segera masuk untuk menemui rekan baikmu."
  },
  AvgDialog_19062_Content_16 = {
    Text = "Pada saat yang sama\nRoh Rumah Sakit Jiwa Lay·ruang operasi"
  },
  AvgDialog_19062_Content_17 = {
    Text = "Ramona terbangun di atas ranjang yang lembut, dengan wajah cemas seorang gadis di hadapannya."
  },
  AvgDialog_19062_Content_18 = {
    Text = "<SmallShake:Ini…… di mana? Aku…… sudah tidur selama berapa lama?>"
  },
  AvgDialog_19062_Content_19 = {
    Text = "Dia memegang dahinya dan bangkit duduk, cahaya senja masuk melalui jendela, mengubah tempat ini menjadi lautan berwarna hangat."
  },
  AvgDialog_19062_Content_2 = {
    Text = [[
Dokumen ini... Francis sedang melakukan Penelitian... 
Pelarutan?!]]
  },
  AvgDialog_19062_Content_20 = {
    Text = "... ternyata terasa agak hangat."
  },
  AvgDialog_19062_Content_21 = {
    Text = "Tidak, bukan ilusi..."
  },
  AvgDialog_19062_Content_22 = {
    Text = "Ramona bergumam."
  },
  AvgDialog_19062_Content_23 = {
    Text = "Jika bukan karena peralatan bedah di samping tempat tidur yang memantulkan cahaya dingin dan tajam, suasana di sini jelas menyerupai kamar tidur seorang gadis."
  },
  AvgDialog_19062_Content_24 = {
    Text = "Kak Ramona, sudah waktunya kamu kembali. Bawa juga Kum... pergi."
  },
  AvgDialog_19062_Content_25 = {
    Text = "Gadis itu tidak merespons pertanyaan Ramona, malah mengatakan sesuatu dengan nada datar lalu membelai kepala Kum setelah memiringkan tubuhnya."
  },
  AvgDialog_19062_Content_26 = {
    Text = "Lalu bagaimana denganmu?"
  },
  AvgDialog_19062_Content_27 = {
    Text = "Jika keluar terlalu lama, <Yellow:Dia> akan menemukannya."
  },
  AvgDialog_19062_Content_28 = {
    Text = "Dia? ... Apakah yang dimaksud adalah \"Anjing neraka\"?"
  },
  AvgDialog_19062_Content_29 = {
    Text = "Lily, jangan takut. Kami berasal dari universitas yang khusus menangani fenomena abnormal, dan pasti ada cara untuk melindungimu."
  },
  AvgDialog_19062_Content_3 = {
    Text = "Jika ingin berkunjung lagi, kamu bisa menyapaku. Kenapa harus bersembunyi?"
  },
  AvgDialog_19062_Content_30 = {
    Text = [[
Tidak, tidak ada yang bisa lolos dari pandangan-Nya. 
Orang yang menjadi sasarannya pada akhirnya akan menjadi mangsa-Nya.]]
  },
  AvgDialog_19062_Content_31 = {
    Text = [[
Lagipula, Lily juga harus menemani ibunya. 
 Ibu sendirian, terlalu kesepian.]]
  },
  AvgDialog_19062_Content_32 = {
    Text = "Dia telah melakukan kejahatan kejam terhadapmu dan terhadap Kum. Aku tidak akan membiarkannya lolos dari hukuman."
  },
  AvgDialog_19062_Content_33 = {
    Text = "Tidak, Ibu tidak berbohong.\nKum menjadi seperti ini… bukan salah Ibu."
  },
  AvgDialog_19062_Content_34 = {
    Text = "Bisakah kamu memberitahuku apa yang kamu tahu?"
  },
  AvgDialog_19062_Content_35 = {
    Text = "Tidak ada waktu lagi."
  },
  AvgDialog_19062_Content_36 = {
    Text = "Wajah Lily jarang menampakkan ekspresi yang begitu sedih."
  },
  AvgDialog_19062_Content_37 = {
    Text = "Khum, bawa dia pergi."
  },
  AvgDialog_19062_Content_38 = {
    Text = "Dari belakang terdengar suara berderit ketika gagang pintu diputar."
  },
  AvgDialog_19062_Content_39 = {
    Text = [[
Khum mengangkat Ramona sesuai suara, melemparkannya ke punggungnya. 
 Ramona mencoba melawan, tetapi terikat erat oleh lendir hitam pada tubuh Khum.]]
  },
  AvgDialog_19062_Content_4 = {
    Text = "Dari balik lemari arsip, terdengar sebuah helaan napas."
  },
  AvgDialog_19062_Content_40 = {
    Text = [[
Jangan kembali lagi, lupakan aku, lupakan segalanya di sini... 
 Ibu tidak akan memberikan kerusakan kepada siapa pun lagi...]]
  },
  AvgDialog_19062_Content_41 = {
    Text = "Di bawah tatapan terkejut orang yang datang, Cum tiba-tiba menabraknya dari depan."
  },
  AvgDialog_19062_Content_42 = {
    Text = "Francis sesaat tidak bisa menstabilkan dirinya. Kum terobos keluar dan melompat ke dalam kegelapan yang tak berdasar."
  },
  AvgDialog_19062_Content_43 = {
    Text = "Ramona menoleh, hanya untuk melihat Lily menopang Francis, berdiri dalam siluet di bawah cahaya matahari senja, dengan tatapan yang hampir seperti permohonan saat mengucapkan perpisahan."
  },
  AvgDialog_19062_Content_44 = {
    Text = [[
Lupakan aku... 
 Seperti yang lainnya...]]
  },
  AvgDialog_19062_Content_5 = {Text = "?!"},
  AvgDialog_19062_Content_6 = {
    Text = "Atau mungkin..."
  },
  AvgDialog_19062_Content_7 = {
    Text = "Francis menjentikkan jarinya, dan tiba-tiba Ramona merasa pusing serta pandangannya menjadi aneh terdistorsi…"
  },
  AvgDialog_19062_Content_8 = {
    Text = "<Yellow: Apakah kamu juga terpengaruh oleh anak itu, lalu tanpa sengaja terjebak dalam pusaran ini?>"
  },
  AvgDialog_19062_Content_9 = {
    Text = [[
"Boneka yang serba bisa", "Otak dalam toples yang jenius". 
Sudah enam jam berlalu, apakah masalah kecil ini belum selesai juga?]]
  },
  AvgDialog_19063_Content_1 = {
    Text = "Kalian telah bertarung melawan Anjing neraka untuk waktu yang lama, tetapi pertempuran ini tidak sesulit yang kalian bayangkan."
  },
  AvgDialog_19063_Content_10 = {
    Text = "...Tidak! Hati-hati!"
  },
  AvgDialog_19063_Content_11 = {
    Text = "Di tengah teriakan Francis, asap ungu dengan cepat berkumpul membentuk figur dan menyerangmu serta Ramona dengan kekuatan seperti guntur."
  },
  AvgDialog_19063_Content_12 = {
    Text = "Kamu mendorong Ramona, berdiri di depannya. Insting manusiamu membuatmu menutup mata, bersiap menghadapi tusukan mengerikan seperti mimpi buruk."
  },
  AvgDialog_19063_Content_13 = {Text = "Ugh!"},
  AvgDialog_19063_Content_14 = {
    Text = "Rasa sakit yang dibayangkan tidak kunjung datang. Yang berdiri di hadapanmu adalah binatang buas yang sepenuhnya tertusuk oleh duri ungu."
  },
  AvgDialog_19063_Content_15 = {
    Text = "Duri tajam segera menghilang. Yang tersisa bukan luka mengerikan, melainkan lubang kosong berbentuk lingkaran."
  },
  AvgDialog_19063_Content_16 = {
    Text = "Kehampaan itu seakan-akan menghisap seluruh kekuatan yang menopang Kum, tubuh raksasanya perlahan-lahan ambruk ke tanah, dan napasnya pun secara bertahap berhenti."
  },
  AvgDialog_19063_Content_17 = {
    Text = "Segalanya terjadi begitu mendadak, kamu sama sekali tidak sempat bereaksi."
  },
  AvgDialog_19063_Content_18 = {
    Text = "Asap ungu kembali menyembur dari celah, tubuh yang jauh lebih besar daripada sebelumnya merobek tulisan rahasia yang patah di dinding, menciptakan luka yang mencolok."
  },
  AvgDialog_19063_Content_19 = {
    Text = "\"Anjing neraka\" telah menampakkan wujud aslinya. Sebelumnya, yang muncul hanyalah sebagian kecil dari Cerberus. Saat ini, Dia sedang mengamati kalian yang gegabah menyatakan kemenangan dalam wujud raksasa."
  },
  AvgDialog_19063_Content_2 = {
    Text = [[
Dia tampaknya hanya mahir dalam menekan Roh, sedangkan Kerusakan dari cakar hanya sedikit. 
Untungnya, Boneka memberikan ramuan emas yang dapat sangat meredakan Tekanan Roh yang Dia sebabkan.]]
  },
  AvgDialog_19063_Content_20 = {
    Text = "Di sudut ruangan, gadis berambut putih yang telah kembali tenang perlahan bangkit, mundur dua langkah, dan meninggalkan pelukan ibunya yang menangis tersedu-sedu."
  },
  AvgDialog_19063_Content_21 = {
    Text = "Bu, kamu bisa mengenali aku, itu sangat menyentuh."
  },
  AvgDialog_19063_Content_22 = {
    Text = [[
%player%{Male=Tuan Penjaga Rahasia,Female=Nona Penjaga Rahasia}, kakak Ramona telah membuatku bertekad...
Aku sangat bersyukur kepada {Male=dia,Female=dia}.]]
  },
  AvgDialog_19063_Content_23 = {
    Text = "Jadi, aku ingin membantu {Male=dia,Female=dia}."
  },
  AvgDialog_19063_Content_3 = {
    Text = "Tak lama kemudian, anjing neraka mengeluarkan suara erangan kekacauan, lalu menghilang di udara."
  },
  AvgDialog_19063_Content_4 = {
    Text = "Ramona menoleh sekali lagi ke arah ibu dan anak yang masih berpelukan sambil menangis, lalu menghela napas dan mengetuk bros di dadanya dua kali dengan ujung jarinya."
  },
  AvgDialog_19063_Content_5 = {
    Text = "Penyelidik Ramona, mencatat, \"Anjing neraka\" telah dikalahkan. Misi selesai."
  },
  AvgDialog_19063_Content_6 = {
    Text = "Penjaga %player%, bersiap untuk memulihkan Pembangun Lily, modifikasi Kum, dan mengajukan penahanan terhadap tersangka Francis Oswood…"
  },
  AvgDialog_19063_Content_7 = {
    Text = "...Memasukkan...desis...Neraka..."
  },
  AvgDialog_19063_Content_8 = {
    Text = "Di sisi lain komunikasi, suara Erica terdengar tidak jelas."
  },
  AvgDialog_19063_Content_9 = {
    Text = "Erica, apakah kamu di sana? Bisakah kamu mendengar dengan jelas?"
  },
  AvgDialog_19064_Content_1 = {
    Text = "Eksperimen Francis telah menyebabkan banyak orang tak berdosa mengalami kerusakan."
  },
  AvgDialog_19064_Content_10 = {
    Text = "Jika kalian ingin bertemu dengan Nyonya Ozwood, silakan lewati aku."
  },
  AvgDialog_19064_Content_2 = {
    Text = "Maksudmu orang-orang yang hilang itu? Orang-orang kejam yang meninggalkan kerabat mereka di panti rehabilitasi ini begitu saja?"
  },
  AvgDialog_19064_Content_3 = {
    Text = "Mereka mengingatkanku pada banyak orang, banyak yang pernah muncul di samping tempat tidurku namun tiba-tiba menghilang."
  },
  AvgDialog_19064_Content_4 = {
    Text = "Mereka adalah paman, om, bibi, dan tante saya... Setelah orang tua saya meninggalkan dunia, mereka hanya memikirkan harta kekayaan yang sedikit ditinggalkan oleh orang tua saya, namun tidak pernah memedulikan apa yang saya rasakan."
  },
  AvgDialog_19064_Content_6 = {
    Text = "Kamu tidak akan langsung mengizinkan kami masuk, kan?"
  },
  AvgDialog_19064_Content_7 = {
    Text = "Nymphaea mengangguk pelan."
  },
  AvgDialog_19064_Content_8 = {
    Text = "Bagaimanapun, saya ingin membantu Nyonya Ozwood dengan sesuatu."
  },
  AvgDialog_19064_Content_9 = {
    Text = "Saya adalah satu-satunya penghalang yang rapuh di sanatorium ini."
  },
  AvgDialog_19065_Content_1 = {
    Text = "Masih cukup santai, tetap lebih nyaman jika ada Penjaga di sekitar."
  },
  AvgDialog_19065_Content_10 = {
    Text = "Apa kamu akan mengatakan bahwa uang ini berasal dari pemimpin tertinggi Kerajaan Leo?"
  },
  AvgDialog_19065_Content_11 = {
    Text = "Jauh lebih menarik daripada itu — sumber dana berasal dari ketua Para pematung, <Blue:Herbert>."
  },
  AvgDialog_19065_Content_12 = {
    Text = "Benar saja."
  },
  AvgDialog_19065_Content_13 = {
    Text = "Ini adalah laporan terapi mental Francis."
  },
  AvgDialog_19065_Content_14 = {
    Text = "Apakah dia juga telah menerima sembuh roh?"
  },
  AvgDialog_19065_Content_15 = {
    Text = [[
Saya sudah merasa bahwa wanita itu memiliki masalah rohani sejak lama. 
 Tingkahnya aneh, lebih parah daripada siswa-siswa saat masa ujian akhir!]]
  },
  AvgDialog_19065_Content_16 = {
    Text = [[
Dia mengklaim bahwa dia "memiliki suami dan anak perempuan, tetapi mereka telah larut dalam cairan hitam." 
 Dokter mendiagnosisnya sebagai delirium yang disebabkan oleh tekanan, hanya memberikan beberapa obat tidur.]]
  },
  AvgDialog_19065_Content_17 = {
    Text = "Dia juga bisa \"melihat\" Pelarutan."
  },
  AvgDialog_19065_Content_18 = {
    Text = "Masih ada halaman ketiga — ini adalah foto bersama Francis dan seluruh tim saat mereka pergi ke Elworth."
  },
  AvgDialog_19065_Content_19 = {
    Text = "Tanggal di foto keluarga ini adalah <Yellow:25 tahun yang lalu>?!"
  },
  AvgDialog_19065_Content_2 = {
    Text = "Apakah ini sikapmu terhadap karakter kunci yang \"hilang selama sepuluh hari\"?"
  },
  AvgDialog_19065_Content_20 = {
    Text = "Benar. Dia seharusnya sudah berusia 52 tahun tahun ini, tetapi dari foto-foto terbaru, penampilannya sama persis seperti 25 tahun yang lalu."
  },
  AvgDialog_19065_Content_21 = {
    Text = "Apakah proyek yang dia teliti adalah <Yellow:hidup abadi>?"
  },
  AvgDialog_19065_Content_22 = {
    Text = "Hmm, untuk orang yang berpikir dengan otot seperti kamu, memahami sampai tingkat ini sudah cukup."
  },
  AvgDialog_19065_Content_23 = {
    Text = [[
Berdasarkan hasil penyelidikan ini, kami menggeledah laboratorium lama Francis.
Tempat itu sudah ditinggalkan, kondisi di dalamnya berantakan, seolah-olah ada delapan ratus Lotan yang bertarung di sana.]]
  },
  AvgDialog_19065_Content_24 = {Text = "Tapi?"},
  AvgDialog_19065_Content_25 = {
    Text = "Namun, William memiliki ketabahan luar biasa. Di tengah debu yang beterbangan, dia terus bergerak sambil batuk-batuk, memindahkan semua puing-puing kayu dan menemukan benda ini di dalam laci meja kantor yang terhimpit."
  },
  AvgDialog_19065_Content_26 = {
    Text = "Boneka memberikan sebuah buku catatan tua yang sudah usang, sampul kulit cokelatnya terlihat menggembung, seakan-akan di dalamnya penuh dengan halaman tambahan."
  },
  AvgDialog_19065_Content_27 = {
    Text = [[
21 November

Semua orang memberi selamat kepadaku, tidak hanya karena kesuksesan dalam karier medis, tetapi juga karena aku kini mendapatkan hubungan yang indah. 
Setelah pernikahan besok selesai, aku akan menjadi Francis Ozwood, dan bersama @3, suamiku, memulai kehidupan baru.

11 Januari

Kami tidak berencana untuk memiliki anak terlalu cepat, namun, @1 tetap menjadi saksi dan kristalisasi cinta antara aku dan @3. Aku bersumpah akan memberikan masa depan terbaik untuknya.]]
  },
  AvgDialog_19065_Content_28 = {
    Text = "7 Juli\nSaat makan malam, @1 dengan gembira berbagi denganku tentang pesta minum teh sore yang diadakan olehnya dan @3 di halaman.\nMelihat senyuman bahagianya, aku hampir tak bisa menahan air mata. Jika aku bisa meluangkan lebih banyak waktu di rumah, aku bisa tertawa bersama mereka di atas rumput, bukannya…\nPada saat itu, @3 – terpujilah Tuhan, dia adalah suami terbaik dan ayah terbaik di dunia – memelukku dari belakang. Dia tidak mengatakan apa-apa, tapi aku tahu maksudnya.\n\n\"Jangan khawatir, kita adalah, dan akan selalu menjadi keluarga paling bahagia.\""
  },
  AvgDialog_19065_Content_29 = {
    Text = "7 Februari\n\nMereka mengatakan kondisi saya sangat buruk, mereka menyarankan saya untuk mencatat apa yang terjadi, mereka berkata itu bisa menenangkan Roh saya — meskipun bukan untuk diri saya sendiri, setidaknya untuk @1. \n\nJadi, mari kita mulai dari awal. \n\nPada @2 Februari@2, saat membawa @1 ke taman hiburan, @3 tiba-tiba pingsan. Saya menerima telepon dan bergegas ke rumah sakit, hanya melihat @3 tersenyum lembut padaku dan menyuruhku untuk tidak khawatir. Saya bertanya padanya tentang lubang hitam di bahunya, dia memandangku dengan bingung, mengatakan bahwa mungkin saya terlalu lelah dan perlu beristirahat, lalu menepuk kepalaku dan berkata entah siapa yang sebenarnya sedang berbaring di tempat tidur dan membutuhkan istirahat. \n\nTapi ada cairan hitam kental yang mengalir di bahunya, aku benar-benar melihatnya. \n...Aku pasti pernah melihat cairan hitam ini di suatu tempat. Tapi di mana? Kenapa aku tidak bisa mengingatnya sama sekali?"
  },
  AvgDialog_19065_Content_3 = {
    Text = "Bukankah kamu sekarang tidak hilang?"
  },
  AvgDialog_19065_Content_30 = {
    Text = "Setelah @3, @1 juga roboh. Dada kiri @1 mulai mengeluarkan cairan hitam yang kental. Mereka tidak mau percaya padaku, mereka semua tidak bisa melihatnya, tetapi di sana benar-benar ada cairan hitam yang menetes seperti lumpur… \n\n @3 selalu tersenyum dan berkata bahwa dia menurunkan penyakit aneh tanpa nama ini kepada @1, sehingga mereka berdua jatuh sakit secara bergantian. Aku memegang tangannya yang pucat, melihat tubuhnya yang semakin lemah dan luka hitam di bahunya yang semakin membesar, aku tidak tahu harus berbuat apa. \n\n …Mereka berbohong, menuliskannya tidak membantu sama sekali."
  },
  AvgDialog_19065_Content_31 = {
    Text = [[
Pada tanggal 5 Maret, <Blue:Tuan Herbert> datang lagi untuk mengunjungi @3 dan @1. Dia membawakan @1 kue jari favoritnya. 
 Saya sangat berterima kasih padanya, sejak @3 dan @1 jatuh sakit, saya telah mengambil cuti panjang dari laboratorium, dan dia dengan sabar menasihati saya untuk lebih banyak meluangkan waktu bersama keluarga. 

 Mengenai hal cairan hitam itu, dia tidak seperti orang lain yang menyangkal perkataan saya, atau menganggap saya mengalami fatamorgana atau halusinasi, melainkan memperkenalkan beberapa pengetahuan tentang agama kepada saya, sebagian besar isinya terkait dengan sebuah organisasi bernama <Blue:Gereja penerang kuil>.]]
  },
  AvgDialog_19065_Content_32 = {
    Text = "Diary berhenti mendadak di sini."
  },
  AvgDialog_19065_Content_33 = {
    Text = "Herbert, Gereja Penerang Kuil… Tampaknya, dia memang terlibat dalam acara yang luar biasa."
  },
  AvgDialog_19065_Content_34 = {
    Text = "Sepertinya buku harian ini tidak lengkap, bagaimana dengan bagian selanjutnya?"
  },
  AvgDialog_19065_Content_35 = {
    Text = [[
Kami sudah memeriksa seluruh laboratorium dari atas ke bawah, tetapi tidak menemukan apa pun. 
 Ketika kami meninggalkan tempat itu, William yang malang hampir terkena pneumokoniosis.]]
  },
  AvgDialog_19065_Content_36 = {
    Text = "Ngomong-ngomong, di mana Ramona?"
  },
  AvgDialog_19065_Content_37 = {
    Text = "Aku sedang bersiap untuk memberitahumu..."
  },
  AvgDialog_19065_Content_4 = {
    Text = "Cukup dengan obrolan ini. Saya memiliki informasi penting untuk disampaikan kepada Anda, Penjaga."
  },
  AvgDialog_19065_Content_5 = {
    Text = "Setelah kontak terakhir dengan kalian, kami telah melakukan banyak Penyelidikan eksternal terhadap Rumah Sakit Roh Rai."
  },
  AvgDialog_19065_Content_6 = {
    Text = "Panti rehabilitasi sudah lama mengalami defisit, kelangsungan hidupnya sepenuhnya bergantung pada bantuan eksternal, dengan sumbangan terbesar berasal dari <Blue:Yayasan Nathan Green>. Dengan mengikuti jejak Penyelidikan ini, kami menemukan beberapa petunjuk."
  },
  AvgDialog_19065_Content_7 = {
    Text = "Yayasan tersebut dengan senang hati membayar untuk eksplorasi teknologi baru dan batas-batas manusia, seperti mendanai pengembangan kendaraan terbang, ekspedisi gletser, penelitian generator efisien, bahkan hal aneh seperti ekstraksi jiwa."
  },
  AvgDialog_19065_Content_8 = {
    Text = "Tapi berinvestasi di panti rehabilitasi? Ini tidak seperti gaya mereka."
  },
  AvgDialog_19065_Content_9 = {
    Text = "Setelah melakukan penyelidikan mendalam, kami menemukan bahwa dana untuk sanatorium berasal dari sumbangan terarah. Yayasan hanya bertindak sebagai perantara, dan donor sebenarnya adalah pihak lain."
  },
  AvgDialog_19066_Content_1 = {Text = "Dia"},
  AvgDialog_19066_Content_10 = {
    Text = "——Pada saat itu."
  },
  AvgDialog_19066_Content_11 = {
    Text = "Francis mengeluarkan suara, hampir tak terbayangkan bahwa itu adalah jeritan yang berasal dari seorang manusia."
  },
  AvgDialog_19066_Content_12 = {
    Text = "Dia seperti melihat sesuatu yang paling menakutkan di dunia, segera melempar jam saku dari tangannya, mundur dua langkah, lututnya gemetar dan jatuh terlentang di tanah."
  },
  AvgDialog_19066_Content_13 = {
    Text = "Dia mengalami kontraksi murid yang sangat cepat, matanya terbelalak penuh amarah, kedua tangannya bergerak liar memegang pisau bedah di tanah, mata pisaunya yang tajam melukai kulitnya, menyebabkan tetesan darah berdarah keluar satu per satu."
  },
  AvgDialog_19066_Content_14 = {
    Text = "Sedangkan Francis seolah-olah tidak merasakan apa pun, kakinya terus bergerak dengan cepat, sambil mulutnya mengucapkan gumaman yang kacau."
  },
  AvgDialog_19066_Content_15 = {
    Text = "<BigShake:Tidak mungkin, tidak mungkin, ini sama sekali tidak mungkin, aku tidak percaya!>"
  },
  AvgDialog_19066_Content_16 = {
    Text = [[
Ramona melangkah maju dan mengambil jam saku itu. 
Dia membuka kait logamnya, lalu dengan diam-diam menyerahkannya ke tanganmu.]]
  },
  AvgDialog_19066_Content_17 = {
    Text = "Itu adalah sebuah jam saku yang permukaannya sudah terkikis hingga tampak berlapis-lapis dan kacau, namun bagian dalamnya sangat bersih, seolah-olah seluruh jam saku direndam dengan cara ditutup rapat dalam cairan tertentu."
  },
  AvgDialog_19066_Content_18 = {
    Text = "Di bagian dalam jam saku, terdapat foto Francis sedang memeluk seorang gadis. Wajah gadis itu sama persis dengan Lily yang kalian kenal, tanpa ada perbedaan sedikit pun."
  },
  AvgDialog_19066_Content_19 = {
    Text = "Saya sudah menduga kemungkinan ini sejak lama..."
  },
  AvgDialog_19066_Content_2 = {
    Text = "Sejenak, semua orang memandang Dafude'er."
  },
  AvgDialog_19066_Content_20 = {
    Text = "Di dalam buku harian Francis, dikatakan bahwa Lily adalah sosok yang dia Bangun secara tidak sengaja di <Blue:Altar Elworth>."
  },
  AvgDialog_19066_Content_21 = {
    Text = "Pembentukan \"Pembangun\" memerlukan pijakan dari dunia ini, yang paling efektif adalah <Yellow:jaringan biologis manusia>."
  },
  AvgDialog_19066_Content_22 = {
    Text = "Dan di dalam buku harian itu, Francis menulis dengan tangannya sendiri bahwa dia menyimpan rambut bayi Lily di dalam jam saku yang selalu dibawanya ke Elworth."
  },
  AvgDialog_19066_Content_23 = {
    Text = "<Yellow:Lily… putri Fransisi>."
  },
  AvgDialog_19066_Content_24 = {
    Text = [[
Francis, jawab aku...
Sekarang, apakah kamu masih menganggapnya sebagai monster?]]
  },
  AvgDialog_19066_Content_25 = {
    Text = "Suara Ramona sangat pelan, tetapi ruangan ini terlalu sunyi. Bahkan suara jarum yang jatuh pun terdengar dengan jelas."
  },
  AvgDialog_19066_Content_26 = {
    Text = "Francis menggelengkan kepalanya dengan tidak percaya, terus mundur di atas tanah hingga menabrak tempat tidur operasi di tengah ruangan, mengeluarkan suara keras \"krang\"."
  },
  AvgDialog_19066_Content_27 = {
    Text = "Lily berjalan menuju Francis dengan kaki telanjang."
  },
  AvgDialog_19066_Content_28 = {
    Text = "Akhirnya kau mengingatnya lagi... Ibu..."
  },
  AvgDialog_19066_Content_29 = {
    Text = "Jangan... kamu... jangan mendekat..."
  },
  AvgDialog_19066_Content_3 = {
    Text = "Di bawah tatapan semua orang, Dafude'er dengan tenang melintasi sebagian besar ruangan dan meletakkan sebuah jam saku di tangan Francis."
  },
  AvgDialog_19066_Content_30 = {
    Text = "Francis tercekat, nadanya penuh dengan ketakutan dan gemetar, mengeluarkan erangan penolakan yang memilukan."
  },
  AvgDialog_19066_Content_31 = {
    Text = "Serpihan kaca di tanah menggores telapak kaki yang lembut, namun seketika sembuh. Lily seolah tidak mendengarnya, melangkah maju satu per satu mendekati Francis ——"
  },
  AvgDialog_19066_Content_32 = {
    Text = [[
Dia mengangkat telapak tangan wanita yang terus mengucurkan darah, lalu perlahan mendekatkannya ke pipinya sendiri. 
 Setelah itu, dia menampilkan senyuman bahagia yang belum pernah terlihat sebelumnya dalam hidupnya.]]
  },
  AvgDialog_19066_Content_33 = {
    Text = "Bu, tidak apa-apa, aku tidak merasa sakit, Bu."
  },
  AvgDialog_19066_Content_34 = {
    Text = "Bu, apakah kamu masih ingat? Kamu berjanji akan membawa Lily untuk naik kereta bawah tanah yang baru dioperasikan…"
  },
  AvgDialog_19066_Content_35 = {
    Text = "Namun, kereta bawah tanah belum beroperasi, Lily sudah jatuh sakit."
  },
  AvgDialog_19066_Content_36 = {
    Text = "Meskipun Ibu tidak berada di sisi Lily, Lily sudah merasakan pengalaman naik kereta bawah tanah, lho."
  },
  AvgDialog_19066_Content_37 = {
    Text = "Blok besi raksasa melaju di lorong yang gelap gulita… seperti terbang di bawah tanah."
  },
  AvgDialog_19066_Content_38 = {
    Text = "Ketika kembali ke permukaan, sudah berada di tempat yang sangat jauh dari titik awal keberangkatan."
  },
  AvgDialog_19066_Content_39 = {
    Text = [[
Kita... masih bisa mengalami lebih banyak hal seperti ini bersama. 
Lily ingin merasakan lebih banyak lagi dengan Ibu...]]
  },
  AvgDialog_19066_Content_4 = {
    Text = "Herbert berpesan, \"Harus dikembalikan kepada pemilik semula.\""
  },
  AvgDialog_19066_Content_40 = {
    Text = "Jadi, Ibu masih seperti dulu, mengelus wajah Lily, ya?"
  },
  AvgDialog_19066_Content_41 = {
    Text = "Bagaimana kalau kita mulai lagi dari awal?"
  },
  AvgDialog_19066_Content_43 = {
    Text = "Francis memeluk Lily erat, menangis dengan suara teredam."
  },
  AvgDialog_19066_Content_44 = {
    Text = "Lily… Lily…!"
  },
  AvgDialog_19066_Content_45 = {
    Text = "Apa... apa yang telah aku lakukan..."
  },
  AvgDialog_19066_Content_46 = {
    Text = [[
Ibu, jangan menangis, jangan menangis... 
 Ibu tidak bersalah sama sekali. Kamu tidak tahu bahwa Lily adalah Lily, dan Lily sendiri juga tidak tahu bahwa dia adalah dirinya sendiri.]]
  },
  AvgDialog_19066_Content_47 = {
    Text = "Jika bukan karena usaha keras Ibu, Lily sudah lama menghilang dan juga tidak bisa menghabiskan waktu yang sangat lama di sisi Ibu."
  },
  AvgDialog_19066_Content_48 = {
    Text = "Ibu teringat pada Lily. Lily sekarang sangat bahagia, seperti berbaring di antara awan. \n …… Ini sudah cukup."
  },
  AvgDialog_19066_Content_49 = {
    Text = "Tidak, tidak, Lily, semua ini adalah kesalahan Ibu…"
  },
  AvgDialog_19066_Content_5 = {
    Text = "Setelah mengucapkan kata-kata penuh makna, dia menyapa kalian dengan senyuman yang terkesan genit dan ambigu."
  },
  AvgDialog_19066_Content_50 = {
    Text = "Bu, Bu pasti akan mengganti rugimu…"
  },
  AvgDialog_19066_Content_51 = {
    Text = "Kita bisa pergi bersama naik kereta bawah tanah, ke taman hiburan, ke pameran..."
  },
  AvgDialog_19066_Content_52 = {
    Text = "Lily ingin pergi ke mana saja, Mama akan mengizinkanmu…"
  },
  AvgDialog_19066_Content_53 = {
    Text = "Mama akan selalu menemani kamu, membuatmu menjadi anak yang paling bahagia di dunia…"
  },
  AvgDialog_19066_Content_54 = {
    Text = "Lily sudah menjadi anak yang paling bahagia, Bu."
  },
  AvgDialog_19066_Content_6 = {
    Text = "Jika ada kebutuhan untuk membeli, baik itu lensa tunggal maupun informasi tentang Herbert, silakan hubungi saya melalui Mulia Dexter, ya?"
  },
  AvgDialog_19066_Content_7 = {
    Text = "Ramona menggertakkan giginya, seolah ingin mengatakan sesuatu, tetapi akhirnya dia memberi jalan."
  },
  AvgDialog_19066_Content_8 = {
    Text = "<Small:Mengamati perkembangannya.>"
  },
  AvgDialog_19066_Content_9 = {
    Text = "<Small:Hmm.>"
  },
  AvgDialog_19067_Content_1 = {
    Text = "Hei, Kepala Besar, modifikasi kamu sepertinya tidak memiliki efek sama sekali."
  },
  AvgDialog_19067_Content_10 = {
    Text = "Ramona, apakah kamu terluka?"
  },
  AvgDialog_19067_Content_11 = {
    Text = "Saya selamat, hanya Lily——"
  },
  AvgDialog_19067_Content_12 = {
    Text = [[
Jangan bicara soal Lily atau apapun, cepat bawa orang ini pergi. 
Orang yang tidak bisa mengikat ayam seperti ini, merawatnya benar-benar merepotkan.]]
  },
  AvgDialog_19067_Content_13 = {
    Text = "...aku masih di sini."
  },
  AvgDialog_19067_Content_14 = {
    Text = [[
Ini dia "Khum", kan? 
Para pematung itu, selera estetika mereka semakin aneh.]]
  },
  AvgDialog_19067_Content_15 = {
    Text = "Ramona, indeks gnostik kamu sangat tidak stabil, ada apa?"
  },
  AvgDialog_19067_Content_16 = {
    Text = "Ramona mengangguk, ekspresi muramnya yang sudah kelam kini semakin suram."
  },
  AvgDialog_19067_Content_17 = {
    Text = "Dari mana sebaiknya saya mulai berbicara?"
  },
  AvgDialog_19067_Content_18 = {
    Text = "Situasi sebelum kalian berpisah di sanatorium telah diceritakan kepada saya oleh Penjaga."
  },
  AvgDialog_19067_Content_19 = {
    Text = "Ramona menceritakan segala sesuatu, mulai dari ditinggalkan sendirian di sanatorium hingga diseret keluar dari kamarnya oleh Cume."
  },
  AvgDialog_19067_Content_2 = {
    Text = "...Kamu terlalu meremehkan direktur penelitian. \"Isolasi\" di sini sangat rumit, aku juga bukan Pembangun dari Alam ultra, jadi tentu saja operasinya tidak terlalu lancar."
  },
  AvgDialog_19067_Content_20 = {
    Text = "Lagipula, Lily memberi saya..."
  },
  AvgDialog_19067_Content_21 = {
    Text = "Dia tiba-tiba melihatmu dengan tatapan rumit, lalu melihat Boneka dan Lotan di samping."
  },
  AvgDialog_19067_Content_22 = {
    Text = [[
Baiklah, selanjutnya adalah persiapan sebelum pertempuran. 
 Lotan, kemarilah, ikut aku ke samping sebentar.]]
  },
  AvgDialog_19067_Content_23 = {
    Text = "Ha? Kenapa?"
  },
  AvgDialog_19067_Content_24 = {
    Text = [[
Tidak ada alasan khusus, bukankah kamu juga pernah mengalami gangguan Roh dalam serangan sebelumnya? 
 Ikuti aku, aku akan memeriksa Indeks gnostik-mu.]]
  },
  AvgDialog_19067_Content_25 = {
    Text = "Boneka mendorong Lotan pergi."
  },
  AvgDialog_19067_Content_26 = {
    Text = "Penjaga... bukan, %player%."
  },
  AvgDialog_19067_Content_27 = {
    Text = "Saya punya beberapa hal di sini, dan kamu juga perlu melihatnya."
  },
  AvgDialog_19067_Content_28 = {
    Text = "Ramona berhenti sejenak, menutup mata, dan dengan tegang menelan ludah."
  },
  AvgDialog_19067_Content_29 = {
    Text = "Dia memberikanmu sebuah map."
  },
  AvgDialog_19067_Content_3 = {
    Text = "%player%，coba aktifkan penelusuran Roh."
  },
  AvgDialog_19067_Content_30 = {
    Text = [[
Saya menemukan arsip ini di ruang rahasia kantor Francis, dan buku catatan di dalamnya... 
 sepertinya Lily yang diam-diam menyelipkannya.]]
  },
  AvgDialog_19067_Content_31 = {
    Text = "Saya pikir, ada beberapa keputusan yang perlu, dan hanya bisa kamu buat."
  },
  AvgDialog_19067_Content_32 = {
    Text = "Di dalam arsip terdapat puluhan catatan eksperimen singkat."
  },
  AvgDialog_19067_Content_33 = {
    Text = "Kamu melihat sekilas, ini adalah catatan observasi dan operasi pasien Pelarutan pada tahap penyakit yang berbeda."
  },
  AvgDialog_19067_Content_34 = {
    Text = "Kamu juga pernah melihat arsip serupa di Mythag, hanya saja metode eksperimen Francis lebih menantang batas etika dan moralitasmu."
  },
  AvgDialog_19067_Content_35 = {
    Text = "Sedangkan di dalam buku catatan, sepertinya ini adalah buku harian seseorang, tulisannya jelas dan rapi."
  },
  AvgDialog_19067_Content_36 = {
    Text = "13 Maret\nSaya mengambil beberapa sampel cairan hitam dan memverifikasi sifat fisik serta kimianya.\nSetelah dibakar, tersisa sedikit bubuk perak di dalam crucible.\n……"
  },
  AvgDialog_19067_Content_37 = {
    Text = [[
3 Mei
@1 telah meninggal.
@3 tidak datang ke pemakamannya, karena ia sudah terlalu lemah untuk meninggalkan tempat tidur sakit.]]
  },
  AvgDialog_19067_Content_38 = {
    Text = [[
6 Juli
Seperti terakhir kali, rumah sakit membantu mengurus pemakaman @3.
Namun saat aku berterima kasih kepada mereka karena telah membantu di saat aku sangat berduka untuk kedua kalinya, mereka dengan wajah aneh bertanya padaku, "Kapan terakhir kali itu?"
...]]
  },
  AvgDialog_19067_Content_4 = {
    Text = "Kamu berusaha merasakan tautan dan resonansi yang lemah di udara."
  },
  AvgDialog_19067_Content_40 = {
    Text = [[
Kamu membaca dengan kecepatan luar biasa. 
 Entah mengapa, isi catatan ini terasa familiar, seolah pernah kamu lihat atau dengar sebelumnya.]]
  },
  AvgDialog_19067_Content_41 = {
    Text = "Kamu mengetahui hal-hal ini."
  },
  AvgDialog_19067_Content_42 = {
    Text = "Di akhir catatan harian pertama, Francis memutuskan untuk pergi ke Elworth. Dia tidak berniat untuk kembali."
  },
  AvgDialog_19067_Content_43 = {
    Text = "Setengah pertama dari buku harian kedua mencatat hal-hal yang sudah kamu ketahui dalam bentuk kenangan, sedangkan catatan di setengah bagian belakang menjadi sangat kacau…"
  },
  AvgDialog_19067_Content_44 = {
    Text = [[
Profesor Herbert datang lagi menemui saya. Dia membawa beberapa "eksperimen" dari Para Pematung.
Orang-orang ini sudah terjangkit Pelarutan, penyakitnya sudah sangat parah, dan dalam waktu kurang dari sebulan mereka akan menghilang dari dunia ini.

...Sebelum bisa menyembuhkan penyakit ini, kita harus melakukan Penelitian dan memahaminya secara menyeluruh.
Orang biasa tidak bisa melihat cairan hitam ini. Saya sendiri tidak mungkin bisa mengumpulkan begitu banyak kasus tanpa bantuan.
Saya melakukan ini untuk menghentikan penyebaran Pelarutan, agar lebih sedikit orang yang menderita seperti yang dialami putri saya.
...
...]]
  },
  AvgDialog_19067_Content_45 = {
    Text = "Kemarin malam, Lily kehilangan kendali.\nLily melarikan diri. Profesor Herbert telah memperingatkan saya bahwa mereka yang baru di-Bangun semuanya sedikit tidak terkendali pada awalnya.\n……\nSaya harus segera menemukannya dan meninggalkan klinik."
  },
  AvgDialog_19067_Content_46 = {
    Text = [[
Tidak... apakah tempat itu masih bisa disebut klinik?
Peralatan eksperimen hancur menjadi bubuk halus, dan materi organik berubah menjadi cairan kental yang pekat.
Dia bahkan bisa meratakan seluruh brankas menjadi bentuk pipih seperti penjepit buku...
Hilang juga tiga peneliti yang direkomendasikan oleh Herbert. Aku tidak berani membayangkan nasib mereka...
...]]
  },
  AvgDialog_19067_Content_47 = {
    Text = "Modifikasi ketiga puluh lima, implan Perak.\nPerak ini disediakan oleh Herbert, katanya berasal dari Altar Elworth, tempat aku bertemu dengan Lily.\nTempat itu sudah ditinggalkan, Herbert menemukan Perak ini di antara api yang masih menyala.\nSetelah Perak diimplan, Lily mulai memiliki kemampuan komunikasi dasar dan bisa mengikuti instruksi dengan lebih baik.\n… Ini bukan tujuan awalku, tapi memikirkan bahwa dia tidak akan membahayakan lebih banyak orang, hatiku merasa sedikit lega."
  },
  AvgDialog_19067_Content_48 = {
    Text = "Entah kenapa, terkadang aku tiba-tiba merasa Lily sangat mirip dengannya.\n……Namun, monster tetaplah monster, tidak peduli berapa kali dia dioperasi, dia takkan pernah mengatakan sepatah kata pun \"Aku kesakitan\".\nDia tidak memiliki rasa sakit, bagi monster, membuka perut lalu sembuh dengan sendirinya adalah hal yang biasa.\nHanya saja, tatapan dingin itu seolah-olah mengingatkanku bahwa @1 ku, takkan pernah kembali lagi…."
  },
  AvgDialog_19067_Content_49 = {
    Text = [[
Mengapa kamu tidak merasakan sakit? 
 Mengapa kamu tidak bisa merasakan sakit seperti orang biasa?]]
  },
  AvgDialog_19067_Content_5 = {
    Text = "Bayangan Ramona muncul di benakmu yang dipenuhi kabut, awalnya hanya siluet, lalu semakin jelas."
  },
  AvgDialog_19067_Content_50 = {
    Text = [[
Tahun kedelapan belas setelah meninggalkan Elworth, eksperimen ke-374 pada Lily. 
 Ada suara di dalam pikiran saya yang mengatakan bahwa jawaban yang saya cari ada pada dirinya. 
 Saya tidak bisa menahan dorongan untuk melakukan operasi padanya.]]
  },
  AvgDialog_19067_Content_51 = {
    Text = "<Yellow:Itu dia yang memanggilku, seperti marmer yang memanggil pemahat, kertas putih yang memanggil pelukis.>"
  },
  AvgDialog_19067_Content_52 = {
    Text = "...\nLily melarikan diri lagi.\nNamun, saat ini aku tidak punya waktu luang atau cara untuk membawanya pulang.\nEksperimen sedang berada pada tahap kritis, dan \"Anjing pemburu\" sedang mengamati setiap langkahku dengan penuh ancaman.\nUntungnya, Lily sekarang memiliki kecerdasan dasar dan tidak akan melukai orang sembarangan.\nDan jika terjadi sesuatu yang tidak diinginkan, itu adalah pengorbanan yang diperlukan…\nIni demi kesejahteraan seluruh umat manusia…"
  },
  AvgDialog_19067_Content_53 = {
    Text = [[
Gadis itu bertanya padaku apakah ada eksperimen manusia di sini... Tentu saja tidak. 
...Mereka dulunya adalah manusia, tapi sekarang mereka hanyalah makhluk asing yang mengerikan. 
Ya, mereka hanyalah makhluk asing yang mengerikan. 
Aku melakukannya semua ini untuk menyembuhkan penyakit aneh yang dulu merenggut hidup putriku, agar lebih banyak orang tidak harus merasakan penderitaanku. Langkah demi langkah, aku sampai di sini.]]
  },
  AvgDialog_19067_Content_54 = {
    Text = "Saya sudah hampir menemukan jawabannya, tinggal selangkah lagi dari jawaban itu…"
  },
  AvgDialog_19067_Content_6 = {
    Text = "Dia bergerak dengan kecepatan yang tidak manusiawi, terus bergerak, \n semakin mendekati kalian, semakin cepat, semakin cepat…"
  },
  AvgDialog_19067_Content_7 = {Text = "Ramona!"},
  AvgDialog_19067_Content_8 = {
    Text = "Ramona menunggangi punggung makhluk raksasa yang mirip singa dan anjing, berlari ke arah kalian. Saat dia tiba-tiba berhenti, debu pun berterbangan."
  },
  AvgDialog_19067_Content_9 = {
    Text = "Dia melompat dan mendarat di tanah, sementara Kum bangkit dan meregangkan tubuhnya dengan malas."
  },
  AvgDialog_19068_Content_1 = {
    Text = "Lily masih mengendalikan bisul hitam dan Anjing neraka, namun gerakannya sudah tidak segesit tadi."
  },
  AvgDialog_19068_Content_10 = {
    Text = "Ramona menutupi pandanganmu, mengambil tabung reaksi dari sakumu, membuka tutupnya, dan menuangkannya ke dalam mulutmu."
  },
  AvgDialog_19068_Content_11 = {
    Text = "Buka pintu di sana, keluar, dan kalian tidak akan pernah lagi diganggu oleh-Nya."
  },
  AvgDialog_19068_Content_12 = {
    Text = "Bawa Lily juga…."
  },
  AvgDialog_19068_Content_13 = {
    Text = "Maukah kamu ikut dengan kami?"
  },
  AvgDialog_19068_Content_14 = {
    Text = [[
Anjing neraka hanya muncul saat berburu mangsa.
Jika tidak ada seorang pun di ruangan ini, mengapa Dia berhenti di sini?]]
  },
  AvgDialog_19068_Content_15 = {
    Text = "Kalian semua adalah anak-anak yang baik, dan aku harus menebus dosa atas kejahatan yang telah aku lakukan."
  },
  AvgDialog_19068_Content_16 = {
    Text = "Tolong... jaga Lily dengan baik."
  },
  AvgDialog_19068_Content_17 = {
    Text = "Bu! Lily tidak pergi!"
  },
  AvgDialog_19068_Content_18 = {
    Text = "Lily patuh."
  },
  AvgDialog_19068_Content_19 = {
    Text = [[
Lily tidak akan patuh lagi. Ibu sebelumnya berkata, anak baik tidak boleh mengeluh kesakitan... Lily mendengarkannya.
Namun, kali ini, Lily tidak akan patuh lagi!]]
  },
  AvgDialog_19068_Content_2 = {
    Text = "Lima menit."
  },
  AvgDialog_19068_Content_20 = {
    Text = "Dia berusaha keras mengangkat tangannya, mengarahkan bisul untuk menyerang ke arah asap ungu. Namun, Anjing neraka hanya membutuhkan sekejap untuk menusuknya, menyebabkan cairan kental jatuh ke tanah."
  },
  AvgDialog_19068_Content_21 = {
    Text = "Francis memandang kalian, tatapannya sama tulusnya dengan ucapannya."
  },
  AvgDialog_19068_Content_22 = {
    Text = "Bawa dia pergi."
  },
  AvgDialog_19068_Content_23 = {
    Text = "<Italic:Ini adalah permintaan terakhir saya, seorang pendosa dan ibu yang gagal menjalankan tugasnya.>"
  },
  AvgDialog_19068_Content_24 = {
    Text = "Kalian dengan kompak memilih untuk melaksanakan tugas sesuai rencana."
  },
  AvgDialog_19068_Content_25 = {
    Text = "Sama seperti yang pernah dia lakukan kepada Ramona, kamu dan Ramona mengangkat Lily ke atas bahu Lotan."
  },
  AvgDialog_19068_Content_26 = {
    Text = "Huh, dalam situasi seperti ini, pekerjaan berat masih harus aku yang melakukannya."
  },
  AvgDialog_19068_Content_27 = {Text = "Ibu!——"},
  AvgDialog_19068_Content_28 = {
    Text = "Lily, yang telah kehilangan kemampuan untuk melawan, dibawa pergi oleh kalian dari ruang yang terdistorsi ini. \nDibawa pergi dari tempat peristirahatan terakhir ibunya — Francis."
  },
  AvgDialog_19068_Content_29 = {
    Text = "Saat pergi, kamu sengaja melirik ke luar jendela yang berkilauan dengan cahaya bintang yang aneh dan misterius."
  },
  AvgDialog_19068_Content_3 = {
    Text = "Sepuluh menit."
  },
  AvgDialog_19068_Content_30 = {
    Text = "Di sana segalanya dalam kekacauan, selain cahaya yang dalam, tampaknya tidak ada apa-apa."
  },
  AvgDialog_19068_Content_33 = {
    Text = "Francis yang penuh kotoran melangkah perlahan menuju monster raksasa itu."
  },
  AvgDialog_19068_Content_34 = {
    Text = "Narsis pernah memperingatkanku bahwa perubahan yang sangat kecil dilakukan oleh manusia terhadap waktu akan menarik monster bernama \"Anjing pemburu @4\"."
  },
  AvgDialog_19068_Content_35 = {
    Text = "Pada saat itu, aku sepenuhnya ingin mengubah masa lalu, bahkan jika hanya bisa mendapatkan satu menit atau satu detik waktu, untuk membalikkan semua yang telah diubah oleh Pelarutan."
  },
  AvgDialog_19068_Content_36 = {
    Text = "Namun, hal yang paling penting sebenarnya selalu, selalu ada di sisiku."
  },
  AvgDialog_19068_Content_37 = {
    Text = "Aku benar-benar sudah menyadarinya..."
  },
  AvgDialog_19068_Content_38 = {
    Text = "Saya datang seorang diri karena ada hal penting yang harus kukatakan langsung kepadamu."
  },
  AvgDialog_19068_Content_39 = {
    Text = "Saya tidak bisa menyerahkan Lily kepadamu."
  },
  AvgDialog_19068_Content_4 = {
    Text = "Lima belas menit."
  },
  AvgDialog_19068_Content_40 = {
    Text = "Apakah kamu sudah mempertimbangkannya dengan matang? Selama kamu menyerahkan Lily padaku, baik merusak ritual maupun menyembunyikan eksperimen… semua yang telah kamu lakukan di masa lalu tidak akan dikejar lagi."
  },
  AvgDialog_19068_Content_41 = {
    Text = "Penelitianmu masih bisa dilanjutkan, asosiasi akan memberikan dukungan finansial seperti biasa."
  },
  AvgDialog_19068_Content_42 = {
    Text = "Gereja juga tidak ragu untuk berbagi hasil penelitian terbaru mereka tentang teknologi Pembangun, kamu bahkan bisa menciptakan \"Lily\" lainnya."
  },
  AvgDialog_19068_Content_43 = {
    Text = "Tolong izinkan saya menolak."
  },
  AvgDialog_19068_Content_44 = {
    Text = "Karena, setelah bertahun-tahun bersama, Lily sudah seperti anak perempuanku sendiri."
  },
  AvgDialog_19068_Content_45 = {
    Text = "Namun, aku memilih untuk mengabaikannya dan hanya mengurung diri dalam kenangan masa lalu."
  },
  AvgDialog_19068_Content_46 = {
    Text = "Meskipun menarik datangnya monster hukum sebab-akibat, sehingga sulit untuk meninggalkan ruang sempit di sanatorium, dia tetap tidak peduli."
  },
  AvgDialog_19068_Content_47 = {
    Text = "Ibu, lihat, poster kereta bawah tanah…"
  },
  AvgDialog_19068_Content_48 = {
    Text = "Apakah Lily juga ingin pergi berpergian? Tapi kita tidak bisa meninggalkan rumah sakit, maaf ya."
  },
  AvgDialog_19068_Content_49 = {
    Text = "Operasi akan segera mencapai tahap kritis. Setelah kamu sembuh, ke mana pun kamu ingin pergi, Ibu akan membawamu."
  },
  AvgDialog_19068_Content_51 = {
    Text = "Jadi, aku telah membuat keputusan."
  },
  AvgDialog_19068_Content_52 = {
    Text = "Kesalahanku, akan kuperbaiki sendiri."
  },
  AvgDialog_19068_Content_53 = {
    Text = "Kamu adalah monster yang \"Bangun\" olehku, keinginanku yang kuat membuka lorong dimensi, sehingga menyebabkan kedatanganmu di sini."
  },
  AvgDialog_19068_Content_54 = {
    Text = "Jika kebencian juga merupakan salah satu bentuk kekuatan roh ——"
  },
  AvgDialog_19068_Content_55 = {
    Text = "Sebelum semua energi saya habis, kau tidak akan bisa melacak anak saya!"
  },
  AvgDialog_19068_Content_6 = {
    Text = "Hei, sudah selesai belum!"
  },
  AvgDialog_19068_Content_7 = {
    Text = "Hmm, sudah selesai."
  },
  AvgDialog_19068_Content_8 = {
    Text = "Garis awal dan akhir saling bertaut seperti ular yang memakan ekornya sendiri. Pola di depan Francis tiba-tiba berkumpul menjadi sandi rahasia yang membuatmu merasa sedikit pusing."
  },
  AvgDialog_19068_Content_9 = {
    Text = "Jangan menatap!"
  },
  AvgDialog_19069_Content_1 = {
    Text = "Melampaui Batas"
  },
  AvgDialog_19069_Content_10 = {
    Text = "Helot? Bukankah seharusnya kamu sudah…"
  },
  AvgDialog_19069_Content_11 = {
    Text = "Sepertinya, ada orang yang suka mencampuri urusan orang lain."
  },
  AvgDialog_19069_Content_12 = {
    Text = "Ya, maaf. Aku kembali lagi dari Neraka."
  },
  AvgDialog_19069_Content_13 = {
    Text = [[
Penjaga, masih ingat perjanjian tiga poin kita? 
 Biarkan aku bertarung dengannya.]]
  },
  AvgDialog_19069_Content_14 = {
    Text = "Tenang saja, aku tidak akan sampai kalah darinya."
  },
  AvgDialog_19069_Content_15 = {
    Text = "Tepat seperti yang kumaksud."
  },
  AvgDialog_19069_Content_16 = {
    Text = "Pustula yang lembut mengikuti langkah-langkah Helot, masuk melalui celah pintu."
  },
  AvgDialog_19069_Content_17 = {
    Text = [[
Anak-anak, pergilah dan tahan yang lainnya. 
 Satu-satunya lawanku hanyalah kau, Lotan.]]
  },
  AvgDialog_19069_Content_2 = {
    Text = "Di dalam ruangan bergema tangisan pilu yang tidak sesuai dengan senja yang lembut."
  },
  AvgDialog_19069_Content_3 = {
    Text = "Apakah kamu berencana memberi tahu Komite?"
  },
  AvgDialog_19069_Content_4 = {
    Text = "Dia seharusnya diadili"
  },
  AvgDialog_19069_Content_5 = {
    Text = "Bawa dia kembali ke Mythag"
  },
  AvgDialog_19069_Content_6 = {
    Text = [[
Baiklah, kita lakukan seperti itu. 
Apapun keputusanmu, aku akan melaksanakannya dengan tegas.]]
  },
  AvgDialog_19069_Content_7 = {
    Text = "Nyonya Francis, mohon ikut bersama kami."
  },
  AvgDialog_19069_Content_8 = {
    Text = "<Italic:Maaf, dia belum bisa pergi bersama kalian.>"
  },
  AvgDialog_19069_Content_9 = {
    Text = "Suara benturan rantai seperti angin lonceng yang paling kasar dan berat, bergema dengan halus di belakang."
  },
  AvgDialog_19070_Content_1 = {Text = "28 hari"},
  AvgDialog_19070_Content_10 = {
    Text = [[
Kuum mengangguk, memberi isyarat kepada kalian untuk naik ke punggungnya. 
 Setelah melihat kalian sudah duduk dengan mantap, ia mengeluarkan teriakan panjang dan langsung menuju sanatorium.]]
  },
  AvgDialog_19070_Content_2 = {
    Text = "Bagaimana, sudah selesai berbisik?"
  },
  AvgDialog_19070_Content_3 = {
    Text = "Kamu secara refleks \"plak\" menutup laptop, punggungmu terasa dingin seperti baru saja diangkat dari gua es berusia ribuan tahun."
  },
  AvgDialog_19070_Content_4 = {
    Text = [[
Bisikan apa... 
 Tunggu, indeks gnostik saya tidak ada masalah, kan?]]
  },
  AvgDialog_19070_Content_5 = {
    Text = "Jika tidak diperiksa, bagaimana bisa tahu ada masalah atau tidak? Melihatmu seenergik saat pertama kali dibangun sungguh membuatku sangat lega."
  },
  AvgDialog_19070_Content_6 = {
    Text = "Kekacauan di Rai sudah melampaui perkiraan. Sepertinya kita tidak punya banyak waktu untuk disia-siakan. Mari segera berangkat."
  },
  AvgDialog_19070_Content_7 = {
    Text = [[
Boneka mengeluarkan beberapa lensa logam berbentuk aneh dan beberapa tabung reaksi dari ranselnya. 
Cairan di dalam tabung reaksi memancarkan kilauan logam dengan warna keemasan gelap.]]
  },
  AvgDialog_19070_Content_8 = {
    Text = "Pegang dengan baik, pakailah hanya saat aku menyuruhmu."
  },
  AvgDialog_19070_Content_9 = {
    Text = "Nak, apakah kamu akan mengikuti kami masuk?"
  },
  AvgDialog_19071_Content_1 = {
    Text = "Sungai Misteri"
  },
  AvgDialog_19071_Content_10 = {
    Text = "Bola mata hitam mengeluarkan suara aneh \"krek krek\", bibir gadis itu terbuka dan menutup bergantian, gumaman dari mulutnya bersama dengan suara aneh dari bola mata membentuk simfoni yang suram dan menekan."
  },
  AvgDialog_19071_Content_12 = {
    Text = "Bola monster hitam menyerbu para pengikut, kerumunan mulai bergolak."
  },
  AvgDialog_19071_Content_13 = {
    Text = "Kamu dan Kolonel Bertrand memanfaatkan celah di tengah kekacauan, lalu segera menyelinap ke dalam jalan kecil."
  },
  AvgDialog_19071_Content_15 = {
    Text = "……………"
  },
  AvgDialog_19071_Content_16 = {
    Text = "Entah sudah berapa lama berjalan dalam kegelapan, dari belakang tidak jauh selalu terdengar suara raungan, teriakan aneh, napas tersengal, gumaman, dan bisikan."
  },
  AvgDialog_19071_Content_17 = {
    Text = "Cepat, pijak pundakku! Kau naik dulu!"
  },
  AvgDialog_19071_Content_18 = {
    Text = [[
Dengan bantuan Kolonel Bertrand yang mengangkatmu, kamu lebih dulu keluar dari terowongan sempit itu. 
Di hadapanmu terbentang dataran salju yang luas dan memukau, hingga membuatmu merasa pusing.]]
  },
  AvgDialog_19071_Content_19 = {
    Text = "Tunggu sebentar, aku sedikit buta salju… Aku akan segera menarikmu…"
  },
  AvgDialog_19071_Content_2 = {
    Text = "Cepat, pintu keluar sudah di depan mata!"
  },
  AvgDialog_19071_Content_20 = {
    Text = "Tidak apa-apa, aku bisa sendiri…"
  },
  AvgDialog_19071_Content_21 = {
    Text = "Sebelum suara Kolonel Bertrand selesai, secara tiba-tiba, wajahnya dipenuhi oleh rasa ketakutan."
  },
  AvgDialog_19071_Content_22 = {
    Text = "Di antara dia dan celah di pintu keluar terowongan, muncul banyak cabang cairan yang tebal dan bengkok."
  },
  AvgDialog_19071_Content_23 = {
    Text = "Benda itu seolah-olah memiliki kehendak sendiri, erat melilit tubuh Kolonel Bertrand."
  },
  AvgDialog_19071_Content_24 = {
    Text = "Bertrand mengulurkan lima jarinya dengan erat mencengkeram permukaan tanah, namun sia-sia. Tanah yang tertutup salju tidak memberikan titik tumpu sama sekali, dan dalam satu tarikan napas, dia langsung tertarik ke bawah."
  },
  AvgDialog_19071_Content_25 = {
    Text = "Segera setelah itu, gendang telinga menangkap suara yang membuat saraf tegang…"
  },
  AvgDialog_19071_Content_26 = {
    Text = [[
Bergerak, mengunyah, tabrakan tulang... 
 Bahkan suara reaksi cairan pencernaan dengan bahan organik terdengar begitu jelas.]]
  },
  AvgDialog_19071_Content_27 = {
    Text = [[
...Beberapa detik yang mendebarkan berlalu, segalanya kembali sunyi.
Hanya angin salju yang meniupkan salju dari ranting pohon, jatuh dengan suara berderak di atas tanah bersalju.]]
  },
  AvgDialog_19071_Content_28 = {
    Text = "Rasa mual yang terlambat naik dari rongga perut ke dada, kamu mulai muntah kering di atas salju."
  },
  AvgDialog_19071_Content_29 = {Text = "Uh..."},
  AvgDialog_19071_Content_3 = {
    Text = "Kamu melihat ke arah yang ditunjuk Ramona, cahaya putih yang menyilaukan memenuhi pandangan."
  },
  AvgDialog_19071_Content_30 = {
    Text = "Air mata mengalir tak terkendali dari sudut matamu, kamu tidak bisa membedakan apakah itu karena kesedihan yang memenuhi dada ataukah rasa takut."
  },
  AvgDialog_19071_Content_31 = {
    Text = [[
Kamu meraba saku untuk merasakan jam saku, berharap itu bisa memberikanmu sedikit kenyamanan. 
Namun, di sana kosong, tidak ada apa pun.]]
  },
  AvgDialog_19071_Content_32 = {
    Text = "...Ternyata kamu tidak berhasil membawa apa pun kembali."
  },
  AvgDialog_19071_Content_33 = {
    Text = "Tubuh terasa berat, telapak tangan yang dingin mendarat di pundakmu."
  },
  AvgDialog_19071_Content_34 = {
    Text = "Berbahaya, Tuan. Berikan saya perintah."
  },
  AvgDialog_19071_Content_36 = {
    Text = "……………"
  },
  AvgDialog_19071_Content_37 = {
    Text = [[
Setelah beberapa hari berjalan, monster-monster dan pengikut yang mengejar kalian menghilang di padang salju. 
 Kamu dan gadis itu menyapu sedikit salju, lalu beristirahat sambil berdekatan di dekat api unggun.]]
  },
  AvgDialog_19071_Content_38 = {
    Text = "Dia akan meninggalkanmu dari waktu ke waktu, lalu kembali membawa potongan Caro berdarah yang entah berasal dari makhluk apa."
  },
  AvgDialog_19071_Content_39 = {
    Text = "Kamu sengaja tidak mempermasalahkannya, melainkan menyalakan api untuk memanggangnya hingga matang. Setelah itu, kamu menutup indera penciuman dan pengecapan, lalu mengunyah protein yang langka itu hingga halus dan menelannya."
  },
  AvgDialog_19071_Content_4 = {
    Text = "Penglihatan menghilang dalam fatamorgana putih yang kasar, seperti terserang buta salju."
  },
  AvgDialog_19071_Content_40 = {
    Text = "Gadis itu tampaknya tidak membutuhkan makanan, tetapi jika kamu memberinya makanan, dia juga akan melahapnya dengan rakus."
  },
  AvgDialog_19071_Content_41 = {
    Text = "Apakah kamu memiliki nama?"
  },
  AvgDialog_19071_Content_42 = {
    Text = "Dia mengunyah daging panggang yang berair sambil menggelengkan kepalanya."
  },
  AvgDialog_19071_Content_43 = {
    Text = "Lalu... bagaimana dengan keluargamu? Apakah kamu tahu di mana orang tuamu berada?"
  },
  AvgDialog_19071_Content_45 = {
    Text = "Dia melihatmu, memandang puncak salju di kejauhan, lalu menengadah ke arah langit yang luas tanpa batas, dan menggelengkan kepala."
  },
  AvgDialog_19071_Content_46 = {
    Text = "...pada akhirnya, tetap memerlukan sebuah nama."
  },
  AvgDialog_19071_Content_47 = {
    Text = "Boleh aku panggil kamu <Blue:Lily>, bisa?"
  },
  AvgDialog_19071_Content_48 = {
    Text = "Majikan berkata, \"Apa pun namanya, itulah namanya.\""
  },
  AvgDialog_19071_Content_49 = {
    Text = "Aku bukan tuan..."
  },
  AvgDialog_19071_Content_5 = {
    Text = "Dalam kekacauan yang terdistorsi, kesadaran ditarik keluar dari tubuh, dan persepsi dikirimkan ke dimensi yang sangat jauh dan sangat dingin. \n<Yellow:Mimpi> itu mengunjungi kamu lagi…"
  },
  AvgDialog_19071_Content_50 = {
    Text = "Tuan, berhati-hatilah. Ada sesuatu yang sedang mengejar kita."
  },
  AvgDialog_19071_Content_51 = {
    Text = "Bagaimana mungkin?! Bukankah kita sudah hampir meninggalkan dataran salju..."
  },
  AvgDialog_19071_Content_52 = {
    Text = "Saraf terasa kesemutan, kesadaran ditarik dan ditekan. \n<Yellow:Mimpi> menolakmu, berusaha mengusirmu dari dunia putih ini. \nTapi…"
  },
  AvgDialog_19071_Content_53 = {
    Text = "Tidak… mereka tidak boleh tertangkap… bahkan dalam mimpi saya…!"
  },
  AvgDialog_19071_Content_7 = {
    Text = "Apa yang terjadi di Elworth sudah melampaui pemahaman logis yang <Yellow:kamu> ketahui, tapi sekarang kamu tidak punya waktu untuk merasa bingung, ada hal yang lebih penting menantimu untuk diselesaikan."
  },
  AvgDialog_19071_Content_8 = {
    Text = "Tolong aku… hentikan mereka."
  },
  AvgDialog_19071_Content_9 = {
    Text = "Baik, Pemilik."
  },
  AvgDialog_19072_Content_1 = {
    Text = "Di lemari buku, ada sebuah kotak yang terkunci..."
  },
  AvgDialog_19072_Content_2 = {
    Text = "Di bawah lukisan tersembunyi sebuah kunci…"
  },
  AvgDialog_19073_Content_1 = {
    Text = "Suara raungan perlahan ditelan oleh bayangan, sisa cairan hitam di koridor juga dengan cepat lenyap tanpa jejak seperti air yang mendidih."
  },
  AvgDialog_19073_Content_10 = {
    Text = [[
Kata-kata ini tidak perlu terburu-buru diucapkan. 
Bagaimana menurutmu tentang undangan saya tadi, Nona Boneka?]]
  },
  AvgDialog_19073_Content_11 = {
    Text = "Lagipula, kamu juga tidak peduli dengan kelangsungan hidup manusia, kan?"
  },
  AvgDialog_19073_Content_12 = {Text = "Benar."},
  AvgDialog_19073_Content_13 = {Text = "Boneka?"},
  AvgDialog_19073_Content_14 = {
    Text = "Berbeda dari mereka, aku telah lama meninggalkan tubuh manusia. Kelangsungan hidup orang biasa memang tidak ada hubungannya dengan aku."
  },
  AvgDialog_19073_Content_15 = {
    Text = "Sebagai peneliti yang mengejar teknologi terdepan, siapa yang tidak ingin menanggalkan etika manusia yang seharusnya tidak membatasi kita dan melakukan eksperimen paling berani?"
  },
  AvgDialog_19073_Content_16 = {
    Text = "Sayang sekali..."
  },
  AvgDialog_19073_Content_17 = {
    Text = "Dibandingkan dengan makhluk seperti kamu yang hanya tahu bagaimana menghindari bahaya dan mencari keuntungan, aku lebih menghargai keberanian mereka yang tetap berusaha meskipun tahu itu mustahil."
  },
  AvgDialog_19073_Content_18 = {
    Text = [[
Cukup dengan obrolan ini. 
 Jika kau terus menunda, aku khawatir Francis akan membawa Lily lari ke seberang lautan.]]
  },
  AvgDialog_19073_Content_19 = {
    Text = "Benar-benar pantas disebut \"Otak Mythag\", tidak ada yang bisa tersembunyi darimu."
  },
  AvgDialog_19073_Content_2 = {
    Text = "Para pematung mengendalikan <Yellow:subjek eksperimen>, benar-benar murah dan efektif."
  },
  AvgDialog_19073_Content_20 = {
    Text = "Herbert bertepuk tangan, dan belasan pintu di belakangnya langsung terbuka serempak."
  },
  AvgDialog_19073_Content_21 = {
    Text = "Niat membunuh yang menusuk tulang menyebar dalam kegelapan, di koridor yang suram dan sempit bergema dengan raungan aneh yang melekat."
  },
  AvgDialog_19073_Content_22 = {
    Text = "Ramona, %player%!"
  },
  AvgDialog_19073_Content_23 = {
    Text = "Kami ada di sini!"
  },
  AvgDialog_19073_Content_24 = {
    Text = "Teman lama ini serahkan padaku, kalian pergi dan hentikan Francis."
  },
  AvgDialog_19073_Content_25 = {
    Text = "Lensa yang baru saja kuberikan kepada kalian, setelah memakainya, kalian akan bisa melihat \"<Yellow:Lorong>\" menuju Dimensi lain."
  },
  AvgDialog_19073_Content_26 = {
    Text = "Tanpa keadaan khusus, jangan dilepas. Pusing adalah fenomena normal. Jika benar-benar tidak tertahankan, minumlah sebotol obat."
  },
  AvgDialog_19073_Content_27 = {
    Text = "Tapi kau seorang diri——"
  },
  AvgDialog_19073_Content_28 = {Text = "Ayo!"},
  AvgDialog_19073_Content_29 = {
    Text = "Universitas Mythag dan Para Pematung sudah bertarung selama bertahun-tahun. Jika dia punya kemampuan untuk mengatasi kami, dia tidak akan menunggu sampai sekarang."
  },
  AvgDialog_19073_Content_3 = {
    Text = "Semoga kamu tidak memiliki pikiran untuk terkurung di bawah tanah."
  },
  AvgDialog_19073_Content_30 = {
    Text = "Semoga Kunci Perak menuntun jalanmu."
  },
  AvgDialog_19073_Content_32 = {
    Text = "Semoga Kunci Perak membimbing kita."
  },
  AvgDialog_19073_Content_33 = {
    Text = "Kamu memakai monokel logam, lalu berbalik bersama Ramona menuju sisi paling timur koridor untuk melakukan terobosan."
  },
  AvgDialog_19073_Content_34 = {
    Text = "Dalam pandangan sekilas, lebih dari sepuluh eksperimen yang dipanggil oleh Herbert telah mengelilingi Boneka dengan erat. Masing-masing tampak penuh keinginan dan siap untuk bergerak."
  },
  AvgDialog_19073_Content_35 = {
    Text = "Jangan lihat! Boneka bilang dia bisa menanganinya."
  },
  AvgDialog_19073_Content_36 = {
    Text = "Percayalah padanya, dan fokuslah pada misi kita!"
  },
  AvgDialog_19073_Content_4 = {
    Text = [[
Meskipun bergerak, itu tidak aneh, kan? 
Lagipula, posisi kita juga tidak berpihak kepada orang biasa.]]
  },
  AvgDialog_19073_Content_5 = {
    Text = "Jika kamu memiliki pemikiran seperti itu, mengapa tidak mempertimbangkan untuk bekerja sama dengan kami?"
  },
  AvgDialog_19073_Content_6 = {
    Text = "Teknologi dari <Yellow:Peradaban Alaemyces> telah lama membuat saya terpikat."
  },
  AvgDialog_19073_Content_7 = {
    Text = [[
Jarang sekali bisa melihatmu datang langsung ke tempat, Herbert. 
Aku pikir kamu paling benci harus muncul secara langsung.]]
  },
  AvgDialog_19073_Content_8 = {
    Text = "Aduh, bagaimanapun, biaya yang dikeluarkan oleh Para Pematung untuk \"jenius\" ini tidak sedikit. Jika kalian menangkapnya sekaligus, semua usaha kami akan sia-sia."
  },
  AvgDialog_19073_Content_9 = {
    Text = "Kalau begitu, kamu masih terlalu percaya diri. Usaha kalian sejak awal tidak pernah mengarah ke tempat lain."
  },
  AvgDialog_19074_Content_1 = {
    Text = "Jendela Rahasia"
  },
  AvgDialog_19074_Content_10 = {
    Text = "Bagaimana mungkin kita bisa tidak mendapatkan apa pun?"
  },
  AvgDialog_19074_Content_11 = {
    Text = "Cahaya di kejauhan..."
  },
  AvgDialog_19074_Content_12 = {
    Text = "Ini adalah keinginan terdalam dari tuan ruang kesadaran, sesuatu yang tidak dapat dilupakan."
  },
  AvgDialog_19074_Content_13 = {
    Text = "Tampaknya seperti sebuah pelatuk."
  },
  AvgDialog_19074_Content_14 = {
    Text = "Apakah orang itu bermaksud menjadi penguasa waktu?"
  },
  AvgDialog_19074_Content_15 = {
    Text = "Dia membutuhkan waktu yang sangat lama untuk mencapai tujuannya, jadi dia mengurung diri di ruangan itu, kan."
  },
  AvgDialog_19074_Content_16 = {
    Text = "Mengurung diri sendiri?"
  },
  AvgDialog_19074_Content_17 = {
    Text = "Ya, harga perjalanan dimensi bukanlah sesuatu yang bisa ditanggung oleh orang biasa."
  },
  AvgDialog_19074_Content_18 = {
    Text = "Setiap kali dia meninggalkan ruangan, kemungkinan besar dia menanggung risiko yang sangat tinggi——"
  },
  AvgDialog_19074_Content_19 = {Text = "Hati-hati!"},
  AvgDialog_19074_Content_2 = {
    Text = "Kamu dan Ramona berlari menyusuri koridor ke arah timur. Tak lama kemudian, sebuah dinding muncul di hadapan kalian."
  },
  AvgDialog_19074_Content_20 = {
    Text = "Monster segitiga dari Kekacauan muncul dari lumpur hitam di bawah kaki."
  },
  AvgDialog_19074_Content_21 = {
    Text = "Pergi dari sini dulu!"
  },
  AvgDialog_19074_Content_3 = {
    Text = "Di bagian atas dinding putih tergantung sebuah lukisan sederhana karya anak kecil, seorang ibu memeluk anaknya dengan penuh kasih sayang saat bermain——\ndan tempat yang dulunya adalah anak itu, hanya tersisa cairan hitam yang lengket."
  },
  AvgDialog_19074_Content_4 = {
    Text = "Tidak ada jalan?"
  },
  AvgDialog_19074_Content_5 = {
    Text = [[
Tidak... percayalah pada intuisimu. 
Masuklah.]]
  },
  AvgDialog_19074_Content_6 = {
    Text = "Pada saat melangkah melewati dinding itu, seolah-olah kamu melihat lukisan di permukaan dinding bergerak sesaat—\nbayangan gadis itu muncul dalam sekejap, lalu kembali tenggelam ke dalam kegelapan."
  },
  AvgDialog_19074_Content_7 = {
    Text = "Ruang ini..."
  },
  AvgDialog_19074_Content_8 = {
    Text = "Jika saya tidak salah, ini adalah lorong yang terbentuk dari kesadaran Francis."
  },
  AvgDialog_19074_Content_9 = {
    Text = "Bersembunyi sangat dalam."
  },
  AvgDialog_19075_Content_1 = {Text = "Ruang"},
  AvgDialog_19075_Content_10 = {
    Text = "Francis berdiri dengan tangan di belakang, memandang ke kejauhan dari depan jendela."
  },
  AvgDialog_19075_Content_11 = {
    Text = [[
Kalian telah mengecewakan niat baik Lily. 
Sebelum Herbert turun tangan, kita seharusnya bisa berpisah begitu saja.]]
  },
  AvgDialog_19075_Content_12 = {
    Text = "Kami tidak akan tinggal diam terhadap kekejamanmu."
  },
  AvgDialog_19075_Content_13 = {
    Text = [[
Kekejaman... apakah seperti itu kalian memandangku?
Seorang freak, seorang gila, seorang penjahat?]]
  },
  AvgDialog_19075_Content_14 = {
    Text = "Aku tidak seperti Herbert, aku tak pernah secara aktif memberikan kerusakan kepada siapa pun."
  },
  AvgDialog_19075_Content_15 = {
    Text = "Mungkin begitu dari sudut pandangmu, tetapi manusia yang telah teralienasi... mungkin masih ada orang yang bersedia menerima mereka, peduli pada mereka."
  },
  AvgDialog_19075_Content_16 = {
    Text = "Saya tahu kalian semua adalah orang-orang yang baik dan penuh keadilan, namun kalian masih terlalu muda."
  },
  AvgDialog_19075_Content_17 = {
    Text = "Saya pernah menangani narapidana kasus berat yang telah selesai menjalani hukuman. Setelah orang-orang di sekitarnya mengetahui rekam jejaknya, mereka semua menghindarinya… meskipun dia sudah benar-benar menyesali kesalahannya."
  },
  AvgDialog_19075_Content_18 = {
    Text = [[
Manusia adalah makhluk yang dibentuk oleh pengalaman mereka.
Setelah mengalami beberapa peristiwa, mereka bukan lagi manusia dan tidak pantas diperlakukan sebagai manusia.]]
  },
  AvgDialog_19075_Content_19 = {
    Text = "Ini bukan hanya pendapat pribadi saya, yang berubah adalah pandangan dunia terhadap mereka."
  },
  AvgDialog_19075_Content_2 = {
    Text = "Ini dia kamarnya, Lily dan Francis... seharusnya ada di dalam."
  },
  AvgDialog_19075_Content_20 = {
    Text = "Bahkan jika kamu tidak menganggap korban Pelarutan sebagai manusia, bagaimana dengan keluarga dan teman-teman yang membawa mereka ke panti rehabilitasi?"
  },
  AvgDialog_19075_Content_21 = {
    Text = [[
Mereka semua telah dimangsa oleh Anjing Neraka, ini pasti ulahmu, kan? 
 Mereka itu seratus persen manusia murni tanpa campuran apa pun.]]
  },
  AvgDialog_19075_Content_22 = {
    Text = "Bukankah mereka yang meninggalkan kerabatnya di panti jompo terpencil ini hanya karena orang tersebut sakit, atau sudah tua dan lemah, pantas untuk dihukum?"
  },
  AvgDialog_19075_Content_23 = {
    Text = "Ini juga bukan kesalahan yang pantas dihukum mati, kamu tidak memiliki hak untuk menghakimi mereka."
  },
  AvgDialog_19075_Content_24 = {
    Text = [[
Aku tidak memiliki hak untuk menghakimi mereka...
Lalu, apakah kalian memiliki hak untuk menghakimi aku?]]
  },
  AvgDialog_19075_Content_25 = {
    Text = [[
Apakah kamu tahu di mana ini? Ini adalah kamar putriku. 
Waktu di sini, selamanya berhenti pada senja hari ketika dia menghilang.]]
  },
  AvgDialog_19075_Content_26 = {
    Text = "Aku sudah mencoba segala cara untuk membuatnya tetap tinggal, bahkan rela menjual jiwa kepada iblis pun akan kulakukan. \nNamun… bahkan iblis pun tidak muncul, dan dia tetap pergi meninggalkanku."
  },
  AvgDialog_19075_Content_27 = {
    Text = [[
Saya memberi nama putri saya kepada <Blue:Lily>, tetapi dia pada akhirnya bukan putri saya.
Dia hanyalah monster yang seusia dengan putri saya.]]
  },
  AvgDialog_19075_Content_28 = {
    Text = "Di meja operasi, lubang besar di dada Lily perlahan-lahan sembuh, dan matanya yang kosong secara bertahap kembali mendapatkan warnanya."
  },
  AvgDialog_19075_Content_29 = {
    Text = "Dia adalah subjek eksperimen yang sempurna. Berapa pun jumlah luka yang dibuat, dia akan terus sembuh, dan operasi tidak akan terhenti karena reaksi rasa sakit."
  },
  AvgDialog_19075_Content_3 = {
    Text = "Kita sudah meninggalkan Lorong Dimensi, bagaimana perasaanmu sekarang? Apakah masih merasa pusing atau mual?"
  },
  AvgDialog_19075_Content_30 = {
    Text = "Tetapi yang aku inginkan hanyalah putriku! Seorang gadis biasa yang akan menangis, tertawa, dan meminta perhatianku karena rasa sakit!"
  },
  AvgDialog_19075_Content_31 = {
    Text = "Mereka... orang-orang yang tega meninggalkan keluarga mereka sendiri yang masih setia di sisi mereka... sudah kehilangan kemanusiaan mereka!"
  },
  AvgDialog_19075_Content_32 = {
    Text = [[
Manusia yang kehilangan kemanusiaannya, apakah masih bisa disebut manusia? 
Bukankah sudah seharusnya orang-orang yang sudah menjadi monster ini menjadi umpan bagi Anjing Neraka?]]
  },
  AvgDialog_19075_Content_33 = {
    Text = "Tidak dapat dipahami."
  },
  AvgDialog_19075_Content_34 = {
    Text = "Jarang-jarang kita memiliki pandangan yang sama."
  },
  AvgDialog_19075_Content_35 = {
    Text = "Francis melangkah maju, dengan lembut membelai pipi Lily yang putih dan halus. Kelembutan itu membentuk kontras yang mencolok dengan kata-kata kasar yang sebelumnya ia ucapkan."
  },
  AvgDialog_19075_Content_36 = {
    Text = "Saya tahu kalian tidak akan memahami."
  },
  AvgDialog_19075_Content_37 = {
    Text = "Dia bergumam dengan suara rendah, hampir tak terdengar."
  },
  AvgDialog_19075_Content_38 = {
    Text = "Saat bisikan di sela-sela gigi berputar hingga putaran ketiga, kalian akhirnya dapat membedakan nada itu —"
  },
  AvgDialog_19075_Content_4 = {
    Text = "Jauh lebih baik. Meskipun ada ketidaknyamanan mendadak lagi, aku akan berusaha sekuat tenaga untuk melawannya."
  },
  AvgDialog_19075_Content_42 = {
    Text = "Monster yang tertidur telah bangun. Lily, yang semula berbaring datar, bangkit dengan gerakan kaku, matanya memancarkan cahaya hijau kebiruan yang aneh..."
  },
  AvgDialog_19075_Content_43 = {
    Text = "<Change>Kembali ke sarang semula"
  },
  AvgDialog_19075_Content_44 = {
    Text = "<Change>Kembali ke dunia yang kekal"
  },
  AvgDialog_19075_Content_45 = {
    Text = "<Change>Kembali ke pelukan Ibu"
  },
  AvgDialog_19075_Content_46 = {
    Text = "<Change>Untuk ibu, musnahkan mereka"
  },
  AvgDialog_19075_Content_47 = {
    Text = "Ssshh——"
  },
  AvgDialog_19075_Content_48 = {
    Text = "Ramona, cari cara untuk Bangun Lily!"
  },
  AvgDialog_19075_Content_49 = {Text = "Mengerti!"},
  AvgDialog_19075_Content_5 = {
    Text = "Menghirup napas dalam-dalam, kamu mendorong pintu yang meneteskan cairan kental dan tiba di tempat terakhir."
  },
  AvgDialog_19075_Content_6 = {
    Text = "Yang terlihat di hadapan mata adalah matahari senja yang abadi tak pernah tenggelam, serta kamar seorang gadis yang memancarkan suasana hangat."
  },
  AvgDialog_19075_Content_7 = {
    Text = "Boneka barbie di kepala tempat tidur, rok merah muda di gantungan baju, kelambu tempat tidur dengan renda… \n Semua ini sangat kontras dengan suasana dingin dan suram di sanatorium."
  },
  AvgDialog_19075_Content_8 = {
    Text = "Di tengah meja operasi terbaring sosok kecil yang kalian kenal, dengan lubang besar di dadanya. Dia begitu tenang, seolah-olah sudah meninggal."
  },
  AvgDialog_19075_Content_9 = {Text = "Lily!"},
  AvgDialog_19076_Content_1 = {Text = "Mulut Gila"},
  AvgDialog_19076_Content_10 = {
    Text = "Yang menjawabnya hanyalah gumaman pelan \"Hmm\" dari Ramona, lalu semua suara kembali tenggelam dalam kesunyian seolah-olah terserap oleh kehampaan."
  },
  AvgDialog_19076_Content_11 = {
    Text = "Lily, sebentar lagi akan bertemu dengan Ibu. Apakah kamu senang?"
  },
  AvgDialog_19076_Content_12 = {
    Text = "Hmm, Ibu…"
  },
  AvgDialog_19076_Content_13 = {
    Text = "Tangan kecil Lily yang lembut dan ramping erat mencengkeram jari-jarimu. Kamu bisa merasakan keringat halus di telapak tangannya, lalu dengan lembut membalas genggamannya untuk memberikan penghiburan."
  },
  AvgDialog_19076_Content_14 = {
    Text = "Jika kamu tidak ingin kembali ke sini, apakah kamu mau pergi ke Mythag bersama kami?"
  },
  AvgDialog_19076_Content_15 = {
    Text = [[
Ayah dulu bisa mengadopsi saya, seharusnya sekarang juga tidak keberatan untuk mengadopsi satu lagi. 
 Memiliki seorang adik perempuan yang begitu penurut akan membuat saya sangat bahagia.]]
  },
  AvgDialog_19076_Content_16 = {
    Text = "Bukan itu masalahnya, Lily dia..."
  },
  AvgDialog_19076_Content_17 = {
    Text = [[
<Blue:Helot>. Jika kamu bertanya tentang identitas, aku bisa dianggap sebagai kakak dari anak itu.
Lebih tepatnya, kekuatan kami adalah <Yellow:"Kekuatan yang berasal dari sumber yang sama">.]]
  },
  AvgDialog_19076_Content_18 = {
    Text = "Jika apa yang dikatakan Helot benar, maka anak baik yang kamu pegang ini tanpa diragukan lagi juga seorang <Yellow:Pembangun>."
  },
  AvgDialog_19076_Content_19 = {
    Text = [[
Aku tahu, bukankah kamu di sini?
 Cukup lakukan Tautan sementara, bertahan sampai dia berhasil terhubung dengan Kolam hitam sekolah.]]
  },
  AvgDialog_19076_Content_2 = {
    Text = "Menyeberangi jembatan rel dan memasuki sanatorium, cahaya langit sudah muncul di cakrawala."
  },
  AvgDialog_19076_Content_20 = {
    Text = "Lily mencengkeram tanganmu dengan erat. Dia melihat ke arah Ramona, lalu menatapmu, matanya dipenuhi oleh rasa cemas."
  },
  AvgDialog_19076_Content_21 = {
    Text = [[
Lily... masih ingin bersama ibu. 
 Karena... Lily hanya punya satu ibu, dan ibu juga hanya punya satu Lily.]]
  },
  AvgDialog_19076_Content_22 = {
    Text = "Ibu juga bukan ingin menjadi seperti ini.\n<Small:Ibu kehilangan sesuatu yang penting, dia ingin mendapatkannya kembali, jadi……>"
  },
  AvgDialog_19076_Content_23 = {
    Text = "Suara Lily semakin lama semakin pelan, nada akhirnya hampir tertutupi oleh suara napas."
  },
  AvgDialog_19076_Content_24 = {
    Text = "<SmallShake: sss——>"
  },
  AvgDialog_19076_Content_25 = {
    Text = "Kalian akhirnya tiba. Selamat datang di Rumah Sakit Lai."
  },
  AvgDialog_19076_Content_26 = {
    Text = "Lily, kamu pergi beristirahat dulu bersama Kakak Nymphaea."
  },
  AvgDialog_19076_Content_27 = {
    Text = [[
Ayo, Lily.
Setelah perjalanan jauh, kamu pasti juga merasa lelah, kan?]]
  },
  AvgDialog_19076_Content_28 = {
    Text = "Lily dengan hati-hati menggandeng tangan Nymphaea, menoleh ke arahmu sekilas, lalu diam-diam berjalan menuju ujung koridor."
  },
  AvgDialog_19076_Content_29 = {
    Text = "Kalian semua sudah bekerja keras, izinkan saya untuk memperkenalkan diri secara resmi."
  },
  AvgDialog_19076_Content_3 = {
    Text = [[
Mendorong pintu besar, debu menyebar di koridor yang dipenuhi bau aneh. 
 Meskipun hari itu cerah setelah salju berhenti, koridor tetap gelap tanpa cahaya.]]
  },
  AvgDialog_19076_Content_30 = {
    Text = [[
Saya <Blue:Francis Ozwood>, pengelola sanatorium ini. 
 Orang-orang di sini memanggil saya Direktur, tentu saja, kalian bisa memanggil saya Francis.]]
  },
  AvgDialog_19076_Content_31 = {
    Text = "Melihat penampilan kalian berdua, apakah kalian siswa? Dan yang ini..."
  },
  AvgDialog_19076_Content_32 = {
    Text = [[
Ya, kami adalah mahasiswa baru tahun pertama Universitas Mythag. 
 Lotan... anggap saja dia sebagai guru pendamping kami.]]
  },
  AvgDialog_19076_Content_33 = {
    Text = "Ternyata begitu. Sungguh membuatku merindukan masa-masa sekolah, yang sudah terlalu jauh dari kehidupanku sekarang. Aku juga tidak lagi sefokus dan serius dulu, penuh keyakinan seperti waktu itu."
  },
  AvgDialog_19076_Content_34 = {
    Text = "Tatapanmu mengingatkanku pada diriku sendiri pada waktu itu, tapi… dibandingkan dengan semalam, kamu hari ini terlihat lebih ragu."
  },
  AvgDialog_19076_Content_35 = {
    Text = [[
Ada apa? Atau... 
Apakah kamu juga membuka kotak sihir yang tidak seharusnya dibuka?]]
  },
  AvgDialog_19076_Content_37 = {
    Text = "Tidak berani dibandingkan dengan Profesor Ozwood."
  },
  AvgDialog_19076_Content_38 = {
    Text = [[
Jika Profesor Ozwood terus mencurahkan diri pada penelitian, seharusnya dia bisa mencapai prestasi yang lebih tinggi di bidang kedokteran. 
 Namun, Anda justru memilih untuk mundur saat berada di puncak karier, menghilang dari dunia akademis.]]
  },
  AvgDialog_19076_Content_39 = {
    Text = "Ah, itu semua hanyalah cerita lama, tidak perlu disebutkan."
  },
  AvgDialog_19076_Content_4 = {
    Text = "Saya tidak menyukai tempat ini."
  },
  AvgDialog_19076_Content_40 = {
    Text = "Bagaimana mungkin? Anda adalah anggota dari <Blue:Tim Ekspedisi Elworth Icefield> yang pertama."
  },
  AvgDialog_19076_Content_41 = {
    Text = "Saya tidak bisa menahan rasa penasaran, bagaimana sanatorium ini bisa mempekerjakan seorang cendekiawan seperti Anda?"
  },
  AvgDialog_19076_Content_42 = {
    Text = "Dibandingkan dengan dipekerjakan, saya lebih suka menganggap bahwa saya yang memilih sanatorium ini."
  },
  AvgDialog_19076_Content_43 = {
    Text = [[
Kamu seharusnya sudah tahu, hasil dari ekspedisi itu sangat jauh dari kata "sukses". 
 Aku adalah satu-satunya yang selamat, sementara semua anggota ekspedisi lainnya terkubur di bawah salju dan es.]]
  },
  AvgDialog_19076_Content_44 = {
    Text = "Pengalaman itu telah mengubah saya secara mendalam. Saya mulai berpikir, apakah kita kehilangan sesuatu yang lebih berharga demi apa yang disebut \"kemajuan\"? Dan apa arti dari kehilangan itu sendiri?"
  },
  AvgDialog_19076_Content_45 = {
    Text = "Apakah ini jawaban Anda?"
  },
  AvgDialog_19076_Content_46 = {
    Text = "Setiap hari berpatroli dua kali, mengobrol dengan orang-orang yang dianggap \"histeris\", lalu kembali ke kantor sendiri untuk merenung sejenak."
  },
  AvgDialog_19076_Content_47 = {
    Text = "Dibandingkan dengan petualangan penuh kegilaan yang menjelajahi puncak-puncak tajam, saya lebih suka kehidupan seperti ini."
  },
  AvgDialog_19076_Content_48 = {
    Text = "Kedermawanan hati Anda sangat menyentuh."
  },
  AvgDialog_19076_Content_49 = {
    Text = "Maaf, hanya permukaan saja, tidak bisa benar-benar memperbaiki kehidupan mereka."
  },
  AvgDialog_19076_Content_50 = {
    Text = "Saya tidak berpikir ini hanya permukaan. Anda telah menyediakan tempat tinggal bagi pasien yang sering didiskriminasi, memberi mereka harapan untuk kembali ke kehidupan sehari-hari."
  },
  AvgDialog_19076_Content_51 = {
    Text = "Francis tersenyum dengan sikap yang tidak menunjukkan persetujuan ataupun penolakan."
  },
  AvgDialog_19076_Content_52 = {
    Text = "Mudah-mudahan."
  },
  AvgDialog_19076_Content_53 = {
    Text = "Kalian juga bukan datang untuk mendengar saya berbicara panjang lebar, ayo, biar saya ajak kalian berkeliling melihat-lihat sanatorium ini."
  },
  AvgDialog_19076_Content_6 = {
    Text = "Kamu menepuk kepala Lily, memberinya semangat untuk terus memimpin kelompok ini maju."
  },
  AvgDialog_19076_Content_7 = {
    Text = "Di koridor yang sunyi, hanya langkah kalian yang bergema. Gema yang berat membuat jantung berdebar."
  },
  AvgDialog_19076_Content_8 = {
    Text = "Bau desinfektan sudah meresap ke seluruh tempat ini, kalian tidak merasa hidung gatal?"
  },
  AvgDialog_19076_Content_9 = {
    Text = "Seolah ingin mengusir keheningan itu, Lotan sengaja melangkah dengan berat untuk menciptakan suara yang berirama."
  },
  AvgDialog_19077_Content_1 = {
    Text = "Saya tidak mengerti apa yang kalian pikirkan, tapi intinya, selama bisa menembus lebih banyak nanah sekaligus, itu sudah cukup, kan?"
  },
  AvgDialog_19077_Content_2 = {
    Text = "...melindungi...ibu..."
  },
  AvgDialog_19078_Content_1 = {
    Text = "Indra Keenam"
  },
  AvgDialog_19078_Content_11 = {
    Text = [[
Upacara akhirnya selesai, wanita yang memimpin turun dari Altar yang tinggi. 
 Sekelompok utusan berjubah hitam mengikuti di belakangnya, pergi secara berurutan seperti koloni semut yang bermigrasi.]]
  },
  AvgDialog_19078_Content_12 = {
    Text = "<Blue:Kamu> dengan susah payah bangkit, melepas pakaian yang basah kuyup di seluruh tubuhmu, dan menemukan jubah pendeta yang disebutkan Murphy di balik sebuah batu besar."
  },
  AvgDialog_19078_Content_13 = {
    Text = "Kamu buru-buru berganti pakaian, tanpa memedulikan dinginnya cuaca, lalu meraba-raba jalan menuju Lorong di utara."
  },
  AvgDialog_19078_Content_15 = {
    Text = "……………"
  },
  AvgDialog_19078_Content_16 = {
    Text = [[
Lorong ini sangat sempit, kamu harus maju dengan tubuh membungkuk. 
 Cahaya tidak bisa menembus ke sini, yang terlihat hanyalah kegelapan pekat, bahkan tangan di depan wajah pun tak terlihat.]]
  },
  AvgDialog_19078_Content_17 = {
    Text = "Apa... aku benar-benar bisa pergi dari sini?"
  },
  AvgDialog_19078_Content_18 = {
    Text = "Kamu meraba-raba saku bajumu, jam saku yang seharusnya memberimu kekuatan sudah tidak diketahui keberadaannya."
  },
  AvgDialog_19078_Content_19 = {
    Text = "...Itu adalah satu-satunya hubungan antara kamu dan @1 di dunia ini."
  },
  AvgDialog_19078_Content_2 = {
    Text = "Mungkin karena terlalu lelah akhir-akhir ini, Boneka berkata untuk beristirahat sebentar, namun kamu malah tertidur dengan tidak sadar…"
  },
  AvgDialog_19078_Content_21 = {
    Text = "Beruntung sekali, ritual telah selesai, tidak ada seorang pun di dalam gua."
  },
  AvgDialog_19078_Content_22 = {
    Text = "Kamu menggeledah pakaian lamamu untuk waktu yang lama, tidak menemukan jam saku, lalu berjalan ke tepi kolam dan meraba-raba di tempat kamu diletakkan."
  },
  AvgDialog_19078_Content_23 = {
    Text = "...Kamu merasa ada yang tidak beres."
  },
  AvgDialog_19078_Content_24 = {
    Text = "Ketinggian air di kolam menurun."
  },
  AvgDialog_19078_Content_25 = {
    Text = "Orang-orang yang pingsan dan dijadikan sebagai korban di dalam kolam tampaknya tanpa sadar meringkuk satu per satu, dengan posisi yang mirip bayi dalam pelukan ibu."
  },
  AvgDialog_19078_Content_26 = {
    Text = "Kamu meraba jam saku di dalam \"lumpur\". Saat hendak berbalik pergi, kamu memperhatikan sosok manusia yang terbaring di sisimu."
  },
  AvgDialog_19078_Content_28 = {
    Text = "Dia masih bernapas... Kamu ragu sejenak, namun tetap mencoba membangunkan Bertrand."
  },
  AvgDialog_19078_Content_29 = {
    Text = [[
Cecili sudah menghilang tanpa jejak, dan kamu juga tidak punya alasan kuat untuk kembali. 
Kalau begitu, menyelamatkan satu orang adalah lebih baik daripada tidak sama sekali.]]
  },
  AvgDialog_19078_Content_3 = {
    Text = "Dan sekali lagi tenggelam dalam <Yellow:Mimpi> yang mengerikan."
  },
  AvgDialog_19078_Content_30 = {
    Text = "<Small:...Kolonel Bertrand, Kolonel Bertrand.>"
  },
  AvgDialog_19078_Content_31 = {
    Text = "Kamu memanggilnya dengan suara pelan, dan dia perlahan-lahan tersadar."
  },
  AvgDialog_19078_Content_32 = {
    Text = "Di sini...?"
  },
  AvgDialog_19078_Content_33 = {
    Text = "Kami dianggap sebagai korban ritual sekte, ceritanya panjang lebar, kami harus segera melarikan diri."
  },
  AvgDialog_19078_Content_34 = {
    Text = "Pada saat itu, permukaan Kolam Hitam tiba-tiba memancarkan cahaya dengan warna yang aneh."
  },
  AvgDialog_19078_Content_35 = {
    Text = "Cahaya itu berkedip dengan cepat sebanyak tiga kali dalam beberapa detik, lalu tiba-tiba padam."
  },
  AvgDialog_19078_Content_36 = {
    Text = "Tak lama kemudian, langkah kaki mulai terdengar dari segala arah."
  },
  AvgDialog_19078_Content_37 = {
    Text = "Kalian telah dikepung."
  },
  AvgDialog_19078_Content_38 = {
    Text = "Lingkaran pengepungan secara bertahap menyempit, sosok hitam seperti dinding hitam yang menekan orang-orang di dalam lingkaran hingga mereka merasa sesak napas."
  },
  AvgDialog_19078_Content_39 = {
    Text = [[
Di kejauhan, di atas panggung tinggi, seorang gadis bernama Murphy berdiri di samping wanita yang berkuasa, dengan ekspresi yang halus dan sulit dipahami. 
 Sepertinya benci, namun juga terlihat seperti tidak punya pilihan lain.]]
  },
  AvgDialog_19078_Content_4 = {
    Text = "<Italic:Dia akan kembali… melalui kegoyahan @2, Dia akan bangkit dari @4, menyebabkan @3 kedatangan…>"
  },
  AvgDialog_19078_Content_40 = {
    Text = "...masih bisa melarikan diri?"
  },
  AvgDialog_19078_Content_41 = {
    Text = "...masih bisa bertemu @1 sekali lagi?"
  },
  AvgDialog_19078_Content_42 = {
    Text = "...atau dengan cara ini kita bisa bersatu kembali, ya?"
  },
  AvgDialog_19078_Content_43 = {
    Text = "...jika bisa... aku masih ingin... berpisah lagi..."
  },
  AvgDialog_19078_Content_45 = {
    Text = "Di dalam kolam air hitam, mulai muncul gelembung-gelembung dengan suara \"gulugulu\"."
  },
  AvgDialog_19078_Content_46 = {
    Text = "Di tengah gelembung air itu, muncul seorang gadis berpakaian serba putih."
  },
  AvgDialog_19078_Content_47 = {
    Text = "Di tangannya, terdapat bola hitam kental yang tidak diketahui apa itu. Benda besar berbentuk bola mata hitam itu terbelah, memperlihatkan gigi tajam seperti hiu, mengikuti gerakan lompatannya ke depan."
  },
  AvgDialog_19078_Content_48 = {
    Text = "<Yellow:Perintah, berikan aku perintah, Pemilik>."
  },
  AvgDialog_19078_Content_5 = {
    Text = [[
Wanita di atas Altar mengucapkan kata-kata dengan lirih. 
 Kamu merasakan ketegangan di seluruh sarafmu, sementara cairan hitam perlahan menutupi Tubuhmu, menyelimuti mulut dan hidungmu.]]
  },
  AvgDialog_19078_Content_6 = {
    Text = [[
Wajahmu sepenuhnya terendam di bawah air, namun saat ini kamu tidak merasakan sesak napas. 
 Air hitam di kolam itu seperti cairan ketuban seorang ibu, memberikan sensasi napas yang menenangkan untuk tidur.]]
  },
  AvgDialog_19078_Content_7 = {
    Text = "Tidak bisa tidur... tidak boleh tertidur..."
  },
  AvgDialog_19078_Content_9 = {
    Text = "……………"
  },
  AvgDialog_19079_Content_1 = {Text = "21 gram"},
  AvgDialog_19079_Content_10 = {
    Text = [[
Jangan berkata begitu, aku kan termasuk "lulusan" Mythag, bukankah itu berarti aku sudah mencapai sesuatu? 
Lagipula, tidak banyak orang yang bisa lulus hidup-hidup dari sekolah ini.]]
  },
  AvgDialog_19079_Content_11 = {
    Text = "Saya masih sering mengucapkan doa untuknya, berharap dia bisa segera bangkit seperti orang normal."
  },
  AvgDialog_19079_Content_12 = {
    Text = "Berkat harapanmu, setidaknya Alistair hidup lebih lama daripada guru lainnya."
  },
  AvgDialog_19079_Content_13 = {
    Text = [[
Guru Alistair, dengan nasib baiknya, pasti akan menyaksikan akhir dunia. 
Sayang sekali, sepertinya kamu tidak akan melihat hari itu.]]
  },
  AvgDialog_19079_Content_14 = {
    Text = "Dalam kepungan orang-orang ini, berapa lama lagi kamu bisa bertahan?"
  },
  AvgDialog_19079_Content_15 = {
    Text = "Bagaimana bisa tahu kalau tidak mencoba?"
  },
  AvgDialog_19079_Content_16 = {
    Text = "Apakah kamu benar-benar berpikir bahwa hanya dengan dirimu sendiri, kamu bisa menyelesaikan begitu banyak subjek eksperimen?"
  },
  AvgDialog_19079_Content_17 = {
    Text = "Jangan menganggap aku sesombong dirimu, Herbert."
  },
  AvgDialog_19079_Content_18 = {
    Text = "Organ bicaramu masih sangat menjengkelkan, Boneka."
  },
  AvgDialog_19079_Content_19 = {
    Text = "Itu jauh lebih berharga daripada otakmu yang kuno."
  },
  AvgDialog_19079_Content_2 = {
    Text = "Sekarang adalah saatnya bagi kita."
  },
  AvgDialog_19079_Content_20 = {
    Text = [[
Teman-teman sejawatmu mungkin belum tentu setuju dengan kesimpulanmu. 
 Jika ada tombol yang bisa menutup mulutmu, mereka mungkin akan langsung menekannya tanpa ragu.]]
  },
  AvgDialog_19079_Content_21 = {
    Text = "Kalau begitu, kamu meremehkan toleransi Mythag dan nilai pribadiku."
  },
  AvgDialog_19079_Content_22 = {
    Text = "Penglihatan orang memang dangkal. Betapapun kuatnya otak seseorang, menghadapi monster yang mengepungmu dari segala arah, tetap saja tak berdaya, bukan?"
  },
  AvgDialog_19079_Content_23 = {
    Text = [[
Hah? Tidak ada yang bisa dilakukan. 
Perhatikan baik-baik, apa sebenarnya ini yang menggantikan tangan manusia.]]
  },
  AvgDialog_19079_Content_24 = {
    Text = "Semoga Kunci Perak menuntun jalanmu."
  },
  AvgDialog_19079_Content_25 = {
    Text = "Murid Boneka mulai berubah bentuk."
  },
  AvgDialog_19079_Content_26 = {
    Text = "Apakah kalian sudah siap, amoeba-amoeba?"
  },
  AvgDialog_19079_Content_27 = {
    Text = "Tunggu! Apakah kamu tidak memperdulikan nyawamu sendiri?!"
  },
  AvgDialog_19079_Content_28 = {
    Text = "Dentuman seperti guntur, bergema di koridor yang sudah sangat sempit."
  },
  AvgDialog_19079_Content_29 = {
    Text = "Tubuh logam terpecah menjadi beberapa bagian, terbang dan menancap ke dinding yang suram."
  },
  AvgDialog_19079_Content_3 = {
    Text = "Herbert, apakah kamu masih belum menyerah pada pengejaranmu yang konyol itu?"
  },
  AvgDialog_19079_Content_30 = {
    Text = "Jeritan menyakitkan meledak dalam sekejap, lalu tiba-tiba berhenti."
  },
  AvgDialog_19079_Content_31 = {
    Text = "… Yang menyusul adalah puluhan detik keheningan mencekam, seluruh sanatorium hanya dipenuhi oleh asap tebal yang bergulung-gulung."
  },
  AvgDialog_19079_Content_32 = {
    Text = [[
Huh, huh, Boneka ini...
Untung aku sudah waspada...]]
  },
  AvgDialog_19079_Content_33 = {
    Text = "Di depan Herbert, Caro dari tubuh eksperimen bertumpuk menjadi dinding perisai, dengan bagian logam yang tertanam rapat di kulit dan tulang, jelas tidak ada tanda-tanda kehidupan."
  },
  AvgDialog_19079_Content_34 = {
    Text = "Tubuh ini hancur begitu parah, entah seberapa besar manfaat dari barang yang bisa diambil dari dalamnya…"
  },
  AvgDialog_19079_Content_4 = {
    Text = "Jika kamu memiliki kemampuan untuk membedakan antara yang absurd dan yang hebat, mungkin kamu akan mengubah cara bicaramu."
  },
  AvgDialog_19079_Content_5 = {
    Text = "Semua bentuk kehidupan tidak dapat melarikan diri dari pelarutan. Apa yang kau teliti hanya akan meninggalkan kekacauan di mana-mana."
  },
  AvgDialog_19079_Content_6 = {
    Text = "Boneka memandang dengan tidak puas pada makhluk-makhluk yang disebut \"Rongsokan\" yang tampak terdistorsi."
  },
  AvgDialog_19079_Content_7 = {
    Text = "Selera estetikamu masih buruk seperti biasa, aku tidak ingat Mythag pernah memberikan pengaruh seperti itu padamu."
  },
  AvgDialog_19079_Content_8 = {
    Text = "Tampaknya setelah aku pergi, Alistair menghapus semua Penelitian hebat yang kutinggalkan. Ngomong-ngomong — apakah Tubuhnya masih sehat?"
  },
  AvgDialog_19079_Content_9 = {
    Text = "Apakah kamu masih memikirkannya? Dia mungkin akan merasa malu karenanya."
  },
  AvgDialog_19080_Content_1 = {
    Text = [[
Apakah kalian masih akan menyelamatkan nyawaku? 
Setelah tempat ini hancur, kami semua akan kehilangan tempat tinggal lagi.]]
  },
  AvgDialog_19080_Content_2 = {
    Text = "Kami tidak datang untuk menyebabkan kehancuran."
  },
  AvgDialog_19080_Content_3 = {
    Text = "Saya baru saja menghubungi Tuan Mulia Dexter, dia sangat bersedia untuk melakukan sedikit amal dan mengambil alih operasi selanjutnya."
  },
  AvgDialog_19080_Content_4 = {
    Text = "Orang yang tidak bersalah masih bisa hidup di sini, dan dia juga akan menjamin dukungan inventaris yang sesuai."
  },
  AvgDialog_19080_Content_5 = {
    Text = "...Meskipun biasanya dia berbicara setengah benar dan setengah bohong, janji yang dia buat pasti akan dia penuhi."
  },
  AvgDialog_19080_Content_6 = {
    Text = "Setelah kami pergi, sanatorium ini pasti akan kembali beroperasi dengan lancar, dan tempat ini tetap menjadi tempat tinggal bagi kalian."
  },
  AvgDialog_19080_Content_7 = {
    Text = [[
Tapi... Nyonya Ozwood... 
Kumohon, jangan berikan kerusakan padanya. Segala sesuatu yang dilakukannya adalah demi kebenaran yang lebih besar...]]
  },
  AvgDialog_19081_Content_1 = {Text = "Keputusan"},
  AvgDialog_19081_Content_10 = {
    Text = "Siapa——<BigShake: Kapten!>"
  },
  AvgDialog_19081_Content_11 = {
    Text = "Pria tinggi itu tidak bisa langsung merespons gadis itu. Dia terengah-engah dan harus bersandar pada dinding kapal agar bisa berdiri dengan stabil."
  },
  AvgDialog_19081_Content_12 = {
    Text = "Elton menarik napas dalam-dalam beberapa kali sebelum akhirnya bisa berdiri stabil dengan bantuan Celeste."
  },
  AvgDialog_19081_Content_13 = {
    Text = "Dan Celeste…"
  },
  AvgDialog_19081_Content_14 = {Text = "Kalian..."},
  AvgDialog_19081_Content_15 = {
    Text = "Mereka semakin terjerumus dalam kelemahan."
  },
  AvgDialog_19081_Content_16 = {
    Text = "Kapten yang memberinya secercah harapan hidup, Pembangun yang menghentikan pertumbuhan <Red:makhluk aneh> di dalam tubuhnya, kekuatan hidupnya sedang berangsur-angsur menghilang."
  },
  AvgDialog_19081_Content_17 = {
    Text = "Ketakutan… ketakutan akan kematian, ketakutan akan kehilangan melanda pikiran, pandangan menjadi kosong."
  },
  AvgDialog_19081_Content_18 = {
    Text = "...aku... kalian..."
  },
  AvgDialog_19081_Content_19 = {
    Text = "Tidak apa-apa, Murphy, jangan takut."
  },
  AvgDialog_19081_Content_2 = {
    Text = [[
22:45
Kapal Sonanier
Lambung Kargo Ketiga]]
  },
  AvgDialog_19081_Content_20 = {
    Text = "Selalu ada jalan untuk menyelesaikan masalah, semuanya akan membaik, jangan khawatir tentang kami."
  },
  AvgDialog_19081_Content_21 = {
    Text = "Meninggalkan bantuan Celeste, sang kapten terhuyung-huyung berdiri tegak, lalu mengulurkan tangan— dengan keras mengacak puncak kepala Celeste."
  },
  AvgDialog_19081_Content_22 = {
    Text = "Jangan sentuh terlalu keras! Rambutnya sampai berdiri!"
  },
  AvgDialog_19081_Content_23 = {
    Text = "Kamu selalu berkata begitu! Lihat dirimu sendiri, kamu hampir tidak bisa berdiri!"
  },
  AvgDialog_19081_Content_24 = {
    Text = "Sekarang tidak ada masalah, kan? Lihat, aku sudah sembuh sepenuhnya."
  },
  AvgDialog_19081_Content_25 = {
    Text = "Lalu... bagaimana dengan mereka? Bagaimana dengan dua siswa yang tidak sengaja naik ke kapal itu?"
  },
  AvgDialog_19081_Content_26 = {
    Text = "Mereka membantu kita menunda waktu, sekarang semua perhatian tertuju pada ruang kekuatan."
  },
  AvgDialog_19081_Content_27 = {
    Text = "Ruang Kekuatan… Miryam ada di Ruang Kekuatan!"
  },
  AvgDialog_19081_Content_28 = {
    Text = [[
Mereka sangat sadar akan kemampuan mereka dan tahu apa yang harus dilakukan. 
Universitas itu... telah mendidik anak-anak dengan cukup baik.]]
  },
  AvgDialog_19081_Content_29 = {
    Text = "Namun, kita juga bukan tanpa harapan. Selama kita cukup dekat dengan daratan, Celeste bisa memindahkan mereka berdua ke pantai."
  },
  AvgDialog_19081_Content_3 = {
    Text = "Sol sepatu yang keras menginjak dek, menghasilkan suara langkah yang teratur dan berat."
  },
  AvgDialog_19081_Content_30 = {
    Text = "Tapi tubuhmu..."
  },
  AvgDialog_19081_Content_31 = {
    Text = "Tidak apa-apa, sedikit kehidupan ini masih bisa aku berikan."
  },
  AvgDialog_19081_Content_32 = {
    Text = "Berkolusi dengan sekte, memandang <Blue:Penderitaan>mu dengan acuh… dosaku sudah cukup berat, aku tidak ingin menanggung nyawa dua orang tak bersalah lagi."
  },
  AvgDialog_19081_Content_33 = {
    Text = "Penderitaanku...?"
  },
  AvgDialog_19081_Content_35 = {
    Text = "Orang yang menyerahkanmu ke tangan Miryam adalah aku."
  },
  AvgDialog_19081_Content_37 = {
    Text = [[
Kamu adalah "kargo" paling berharga yang pernah aku angkut setelah bergabung dengan ordo. 
Berkat pelayaran yang sempurna itu, aku akhirnya mendapatkan perhatian dari Miryam.]]
  },
  AvgDialog_19081_Content_38 = {
    Text = "Jadi ketika aku meminta bantuan kalian, kamu langsung menyetujui tanpa ragu-ragu…"
  },
  AvgDialog_19081_Content_39 = {
    Text = "Ketika cukup dekat dengan pantai, aku akan meminta Celeste untuk membawamu turun dari kapal. Semakin jauh kalian dari laut, semakin baik."
  },
  AvgDialog_19081_Content_4 = {
    Text = "Kapten... Celeste..."
  },
  AvgDialog_19081_Content_40 = {
    Text = "Seolah-olah sebagai tanggapan kepada kapten, Celeste menggoyangkan kompas di tangannya."
  },
  AvgDialog_19081_Content_41 = {
    Text = "Maksudmu menyuruh Celeste dan aku pergi bersama?"
  },
  AvgDialog_19081_Content_42 = {
    Text = "Kedua siswa itu memiliki kendaraan, asalkan mobil mereka juga berubah menjadi <Yellow:Domain>…"
  },
  AvgDialog_19081_Content_43 = {
    Text = [[
Jangan bercanda! Apakah kau pikir kau bisa menahan dua monster itu? 
Kau bahkan bukan seorang Pelaut, kau hanyalah manusia biasa!]]
  },
  AvgDialog_19081_Content_44 = {
    Text = "Aku harap kamu bisa keluar dari semua ini. Anggap saja ini sebagai permintaan terakhirku."
  },
  AvgDialog_19081_Content_45 = {
    Text = "Hasil terburuk apa lagi yang bisa terjadi selain mati di lautan? Aku seharusnya sudah tenggelam bersama Sonaniels dari dulu."
  },
  AvgDialog_19081_Content_46 = {
    Text = "Murphy dengan keras kepala memegang erat-erat ujung mantel kapten, menolak untuk melepaskan."
  },
  AvgDialog_19081_Content_47 = {
    Text = "Pembangun tidak berniat terlibat dalam pertengkaran ini. Dia merasakan negara Penjaga di ujung tautan lainnya dari luar pintu, bersiap untuk berangkat ke Ruang Kekuatan."
  },
  AvgDialog_19081_Content_48 = {
    Text = "—— Tunggu! Kamu mau pergi ke mana!"
  },
  AvgDialog_19081_Content_49 = {
    Text = "Gadis itu menabrak pintu kabin hingga terbuka, lalu meraih salah satu tentakel."
  },
  AvgDialog_19081_Content_5 = {
    Text = "Ramona, dan %player%… mengapa belum kembali."
  },
  AvgDialog_19081_Content_50 = {
    Text = "Bagaimana kau bisa tahu aku……"
  },
  AvgDialog_19081_Content_51 = {
    Text = "Apakah kamu \"Tulu\" yang disebutkan oleh Ramona? Apakah kamu akan membantu mereka?"
  },
  AvgDialog_19081_Content_52 = {
    Text = "Apa yang kulakukan, tidak ada tempat bagi orang luar untuk mencampuri."
  },
  AvgDialog_19081_Content_53 = {
    Text = "Saya juga akan pergi."
  },
  AvgDialog_19081_Content_54 = {
    Text = "Murphy! Jika kamu jatuh ke tangan Miryam, semua usaha kita akan sia-sia."
  },
  AvgDialog_19081_Content_55 = {Text = "Aku tahu."},
  AvgDialog_19081_Content_56 = {
    Text = [[
Tapi... aku tidak bisa... 
 Aku tidak ingin mati, tapi... jika mereka gugur sebelum kapal berlabuh...]]
  },
  AvgDialog_19081_Content_57 = {
    Text = "<SmallShake:Saya... tidak ingin... hal seperti itu...>"
  },
  AvgDialog_19081_Content_58 = {
    Text = "Uhuk, uhuk uhuk!"
  },
  AvgDialog_19081_Content_59 = {
    Text = "Maksudku… aku tidak bisa tinggal di Domain selamanya. Jika aku benar-benar ingin terbebas, aku membutuhkan bantuan dari dua murid itu."
  },
  AvgDialog_19081_Content_6 = {
    Text = "Murphy menggigit bibirnya, cemas berjalan mondar-mandir. Sesekali ia menendang kotak kargo, lalu mencengkeram tali pengikat yang menahan kotak kargo itu."
  },
  AvgDialog_19081_Content_60 = {
    Text = [[
Saya tidak bisa langsung mendatangi sekolah dan memberi tahu kepala sekolah bahwa siswa-siswa mereka telah berkorban demi membantu saya. 
 Saya membutuhkan mereka tetap hidup, dan saya ingin menjadi tamu mereka dengan cara yang terhormat.]]
  },
  AvgDialog_19081_Content_61 = {
    Text = "Yu tidak akan teralihkan untuk melindungimu."
  },
  AvgDialog_19081_Content_62 = {
    Text = "Tidak perlu kau melindungi aku. Aku sangat tahu kelemahan Pelaut, dan aku bisa menjaga diriku sendiri."
  },
  AvgDialog_19081_Content_63 = {
    Text = "Baik, jika kamu memaksa."
  },
  AvgDialog_19081_Content_64 = {
    Text = "Apa maksud dari tatapanmu ini?"
  },
  AvgDialog_19081_Content_65 = {
    Text = [[
Yu awalnya mengira bahwa kau tidak layak mendapatkan pengorbanan sebesar itu. 
 Sekarang tampaknya Yu terlalu cepat menyimpulkan.]]
  },
  AvgDialog_19081_Content_66 = {
    Text = "Apa teka-teki yang kamu bicarakan? Pergi, pergi!"
  },
  AvgDialog_19081_Content_67 = {
    Text = "Anak ini... sudahlah, jika ini adalah pilihannya."
  },
  AvgDialog_19081_Content_68 = {
    Text = "Celeste, pertahankan kecepatan penuh."
  },
  AvgDialog_19081_Content_7 = {
    Text = "Apakah mereka tidak akan mengalami masalah apa pun……"
  },
  AvgDialog_19081_Content_8 = {
    Text = "Dia tidak bisa tenang untuk berdoa, tidak bisa duduk dengan tenang."
  },
  AvgDialog_19081_Content_9 = {Text = "Bam——!"},
  AvgDialog_19082_Content_1 = {
    Text = "Apa lagi yang kamu tunggu? Apakah kamu menungguku untuk mengundangmu?"
  },
  AvgDialog_19082_Content_10 = {
    Text = "Cepat! Turun dulu!"
  },
  AvgDialog_19082_Content_11 = {
    Text = "Tidak bisa! Kamu hanyalah orang biasa, aku memiliki kewajiban untuk melindungimu——<BigShake:Ah!>"
  },
  AvgDialog_19082_Content_12 = {
    Text = "Gadis itu berpura-pura tidak mendengar omelanmu. Dia memanfaatkan tubuhnya yang mungil untuk dengan lincah mengitari dan bergerak ke belakangmu."
  },
  AvgDialog_19082_Content_13 = {
    Text = "—— Lalu, dengan keras menendangmu masuk ke dalam lubang pintu yang gelap."
  },
  AvgDialog_19082_Content_14 = {
    Text = "<SmallShake:Aduh aduh aduh…>"
  },
  AvgDialog_19082_Content_15 = {
    Text = "Gadis itu segera melompat masuk setelahnya. Dia menutup pintu besi dengan keras, lalu dengan cekatan memutar katrol untuk mengunci pintu."
  },
  AvgDialog_19082_Content_16 = {
    Text = "Hu——seharusnya aman untuk sementara."
  },
  AvgDialog_19082_Content_17 = {
    Text = "Gadis itu menekan sakelar, lampu tua berkedip beberapa kali sebelum cahayanya menyebar ke segala arah, mengusir kegelapan."
  },
  AvgDialog_19082_Content_18 = {
    Text = "Bagian kargo luas dan kosong, barang-barang tersebar tidak beraturan dan hanya sedikit yang terikat di sudut-sudut. Debu beterbangan di bawah cahaya redup, menunjukkan tanda-tanda kehancuran karena lama tidak ada jejak manusia."
  },
  AvgDialog_19082_Content_19 = {
    Text = "Di atas kepala terdengar suara ketukan yang terus-menerus, setiap suara mengguncang rongga tengkorakmu."
  },
  AvgDialog_19082_Content_2 = {
    Text = "Pintu Gelap?!"
  },
  AvgDialog_19082_Content_20 = {
    Text = "Kepalaku..."
  },
  AvgDialog_19082_Content_21 = {
    Text = "Pelipis berdenyut sesuai dengan frekuensi ketukan, rasa sakit yang hebat menyayat otak bagian kiri dan kananmu, asam lambung kembali naik ke tenggorokan."
  },
  AvgDialog_19082_Content_22 = {
    Text = "Mereka seharusnya tidak bisa masuk begitu cepat... Eh?! Apa yang terjadi padamu?!"
  },
  AvgDialog_19082_Content_23 = {
    Text = "Jangan, jangan takuti aku! Jangan mati!"
  },
  AvgDialog_19082_Content_24 = {
    Text = "Huh, akhirnya berhasil menghindari mereka."
  },
  AvgDialog_19082_Content_25 = {
    Text = "Pintu ini sangat kokoh, seharusnya aman untuk sementara sampai di sini… <BigShake:Sial!>"
  },
  AvgDialog_19082_Content_26 = {
    Text = "Sial sial sial! Kau ini sudah membuat masalah besar! Seluruh rencana nona kecil ini kacau berantakan! Harus memikirkan sesuatu…"
  },
  AvgDialog_19082_Content_27 = {
    Text = "Ngomong-ngomong, sebaiknya kau ingat baik-baik nama saya ——"
  },
  AvgDialog_19082_Content_28 = {
    Text = "Wajah cemas sang gadis dan fragmen yang muncul di benaknya perlahan menyatu, dua adegan serupa namun berbeda juga bergabung menjadi satu gambar."
  },
  AvgDialog_19082_Content_29 = {Text = "Murphy…?"},
  AvgDialog_19082_Content_3 = {
    Text = "Apa pintu rahasia? Sudah dalam situasi seperti ini, kamu masih berani bercanda dengan tuan putri ini?! Apakah kamu sudah gila?!"
  },
  AvgDialog_19082_Content_30 = {
    Text = "Kamu, apakah kamu baik-baik saja?"
  },
  AvgDialog_19082_Content_31 = {
    Text = "Jatuhnya sedikit sakit."
  },
  AvgDialog_19082_Content_32 = {
    Text = "Apa? Apakah terluka karena jatuh?"
  },
  AvgDialog_19082_Content_33 = {
    Text = "Dengan bantuan cahaya yang redup, dia berjinjit untuk memeriksa kondisimu."
  },
  AvgDialog_19082_Content_34 = {Text = "——!"},
  AvgDialog_19082_Content_35 = {Text = "Ada apa?"},
  AvgDialog_19082_Content_36 = {
    Text = "<SmallShake: Tidak, tidak ada...>"
  },
  AvgDialog_19082_Content_37 = {
    Text = "<Small:Sepertinya ada sesuatu yang bisa digunakan dalam kargo ini…>"
  },
  AvgDialog_19082_Content_38 = {
    Text = "Murphy bergumam dengan suara yang samar, bergerak kaku menuju tumpukan peti, lalu mulai mencari sesuatu."
  },
  AvgDialog_19082_Content_39 = {
    Text = "(Mendekatinya)"
  },
  AvgDialog_19082_Content_4 = {
    Text = "Lagipula bukan belum pernah masuk ke kabin kapal, jangan banyak bicara, bersiaplah!"
  },
  AvgDialog_19082_Content_40 = {
    Text = "Murphy membongkar kotak dengan sangat kasar, kertas dan jerami pengisi peti menyebar di mana-mana, sudut ini segera menjadi berantakan."
  },
  AvgDialog_19082_Content_41 = {
    Text = "Tidak... kotak ini berisi perhiasan yang rusak."
  },
  AvgDialog_19082_Content_42 = {
    Text = "Kamu melihat sekilas, di dalam peti terdapat satu set perhiasan platinum bergaya istana, dengan mutiara dan berlian yang tampak bernilai sangat tinggi."
  },
  AvgDialog_19082_Content_43 = {
    Text = "...Apa ini, semuanya adalah peralatan ritual."
  },
  AvgDialog_19082_Content_44 = {
    Text = "Di dalam kotak kedua penuh dengan berbagai macam barang dan ramuan herbal, seperti mortir batu, daun salvia, myrrh... Bagi seseorang yang tidak memiliki pengetahuan tentang alkimia, mungkin hanya akan mengira ini adalah barang dagangan dari seorang pedagang obat."
  },
  AvgDialog_19082_Content_45 = {
    Text = "Ketemu! Cepat, jongkoklah."
  },
  AvgDialog_19082_Content_46 = {
    Text = "Zat kental berbentuk pasta tanpa basa-basi menempel di bagian belakang kepalamu, terasa dingin dengan sedikit sensasi pedas, dan dalam batas tertentu meredakan rasa sakit."
  },
  AvgDialog_19082_Content_47 = {Text = "Ini…"},
  AvgDialog_19082_Content_48 = {
    Text = "Eh! Jangan sembarangan menyentuh."
  },
  AvgDialog_19082_Content_49 = {
    Text = "Murphy memberikanmu sebuah kaleng salep."
  },
  AvgDialog_19082_Content_5 = {
    Text = "Apakah di bawah aman?"
  },
  AvgDialog_19082_Content_50 = {
    Text = "Labelnya tidak mencantumkan resep atau nama obat, hanya terdapat pola aneh yang digambar. Sepertinya ini adalah obat buatan sendiri."
  },
  AvgDialog_19082_Content_51 = {
    Text = "...Apakah ini déjà vu? Pola pada label salep itu, sepertinya pernah kulihat di suatu tempat."
  },
  AvgDialog_19082_Content_52 = {
    Text = "Nah, ini dia. Tenang saja, tidak akan membunuhmu."
  },
  AvgDialog_19082_Content_53 = {
    Text = [[
Sejak kecil, setiap kali mengalami luka luar, nona ini selalu menggunakan krim obat ini. 
Bagaimana, apakah rasa sakitnya langsung hilang setelah dioleskan?]]
  },
  AvgDialog_19082_Content_54 = {
    Text = "Dia sangat cemas karena kamu jatuh menuruni tangga dan terbentur kepala, tatapannya penuh dengan rasa bersalah."
  },
  AvgDialog_19082_Content_55 = {
    Text = "Tidak terasa sakit lagi"
  },
  AvgDialog_19082_Content_56 = {
    Text = "Lihatlah, aku sudah bilang sangat efektif——"
  },
  AvgDialog_19082_Content_57 = {
    Text = "Setelah mendapatkan jawaban afirmatif, Murphy akhirnya merasa lega dan tersenyum."
  },
  AvgDialog_19082_Content_58 = {
    Text = "Bagian belakang kepala terasa lebih nyaman, namun pelipis masih terasa nyeri. \nMelihat ekspresi rileksnya, sebuah suara di dalam hati memberitahumu seperti ini ——"
  },
  AvgDialog_19082_Content_59 = {
    Text = "Ada beberapa hal yang bisa diselidiki lebih lanjut setelah bertemu dengan <Blue:rekanmu>."
  },
  AvgDialog_19082_Content_6 = {
    Text = "Mana aku tahu."
  },
  AvgDialog_19082_Content_7 = {
    Text = "Lebih baik daripada ditangkap oleh orang-orang gila ini dan dilemparkan untuk memberi makan ikan! Jangan ragu-ragu lagi, bersiaplah."
  },
  AvgDialog_19082_Content_8 = {
    Text = "Musuh sangat cepat. Kamu dengan susah payah menahan serangan musuh, sambil melindungi gadis itu saat ia menarik pintu besi."
  },
  AvgDialog_19082_Content_9 = {
    Text = "Di bawah ambang pintu, tangga besi membentang ke dalam kegelapan yang tak terduga."
  },
  AvgDialog_19083_Content_1 = {
    Text = "Realitas yang terdistorsi"
  },
  AvgDialog_19083_Content_10 = {
    Text = "Dengan bantuan cahaya, dia melihat bahwa di atas permukaan yang halus dari \"ibunya\", tersebar luka-luka hitam yang tak terhitung jumlahnya, besar dan kecil."
  },
  AvgDialog_19083_Content_11 = {
    Text = "\"Maafkan aku...\""
  },
  AvgDialog_19083_Content_12 = {
    Text = "Lumpur hitam bergelombang, menghancurkan ketenangan di dasar pantai."
  },
  AvgDialog_19083_Content_13 = {
    Text = "\"Ibu\"mengeluarkan suara merdu yang menyayat hati, tentakel-tentakelnya bergerak cepat, memasukkan sesuatu ke dalam rongga dada burung muda."
  },
  AvgDialog_19083_Content_14 = {
    Text = "Jalinan-jalinan lunak yang licin dan dingin melilitnya, air kolam hitam tidak lagi menyumbat mulut dan hidungnya, melainkan seperti cairan ketuban, menopang hidupnya."
  },
  AvgDialog_19083_Content_15 = {
    Text = "<Change>\"Maafkan aku……\"\n\"Aku……belum ingin mati……\""
  },
  AvgDialog_19083_Content_16 = {
    Text = "Permukaan air tetap tenang untuk waktu yang lama, bahkan angin yang menderu dari kutub tidak mampu membuat riak pada kolam yang kental."
  },
  AvgDialog_19083_Content_17 = {
    Text = "Miryam-sama, apakah Saintess sudah..."
  },
  AvgDialog_19083_Content_18 = {
    Text = "Dia lahir pada saat bintang Selaras sebelumnya, dan dia adalah anak yang \"dapat melihat\"."
  },
  AvgDialog_19083_Content_19 = {
    Text = "Di dunia ini, tidak ada seorang pun yang lebih layak mendapatkan pengakuan dari darah dewa selain dia."
  },
  AvgDialog_19083_Content_2 = {
    Text = "Burung muda yang sayapnya patah jatuh ke dalam kolam air hitam."
  },
  AvgDialog_19083_Content_20 = {
    Text = "Seiring dengan gumaman rendah, seolah-olah energi dari dalam bumi akan segera menyembur keluar, permukaan air tiba-tiba mulai mendidih."
  },
  AvgDialog_19083_Content_21 = {
    Text = "Air hitam yang kental dan pekat meluap dari tepi kolam, membanjiri mata kaki semua orang, dan mengalir hingga ke kaki telanjang wanita itu."
  },
  AvgDialog_19083_Content_22 = {
    Text = "Menyusuri kerumunan pemuda yang berbisik kaget, dia melangkah dalam diam di jalan yang dipenuhi cairan hitam, lalu mencelupkan kedua tangannya dalam-dalam ke dalam air kolam itu——"
  },
  AvgDialog_19083_Content_23 = {Text = "——Wah"},
  AvgDialog_19083_Content_24 = {
    Text = [[
Gadis itu meloncat keluar dari kolam dengan bertumpu pada kedua tangannya. 
 Cairan hitam mengalir menuruni kontur wajahnya, mirip seperti dua jejak air mata yang mengerikan.]]
  },
  AvgDialog_19083_Content_25 = {
    Text = "Hoh, lumayan juga. Tampaknya, <Blue:Janin Ilahi> sudah mengakui <Blue:Ibu> yang baru."
  },
  AvgDialog_19083_Content_26 = {
    Text = "Goliath tiba-tiba berbicara dengan nada mengejek, namun tidak ada seorang pun di sana yang memperhatikan ejekannya."
  },
  AvgDialog_19083_Content_27 = {
    Text = "Gadis Suci... berhasil? Kita berhasil!"
  },
  AvgDialog_19083_Content_28 = {
    Text = "Miryam perlahan menutup kedua matanya, melepaskan genggaman erat dengan gadis itu, lalu berbalik menghadap para pengikut yang tengah dilanda kegilaan."
  },
  AvgDialog_19083_Content_29 = {
    Text = "Dia mengangkat kedua tangannya, cairan hitam mengalir mengikuti tekstur kulitnya, dan kerudungnya langsung terwarnai menjadi hitam pekat."
  },
  AvgDialog_19083_Content_3 = {
    Text = "Doa sang pemimpin ritual terdengar samar namun tegas, kata-katanya yang penuh semangat menembus cairan hitam kental, berubah menjadi belati yang membelah rongga dada burung muda."
  },
  AvgDialog_19083_Content_30 = {
    Text = "Doa-doa saling bersahutan, akhirnya berpadu dalam gua yang dingin, penuh semangat, terdistorsi, dan memekakkan telinga."
  },
  AvgDialog_19083_Content_31 = {
    Text = "Dewi Ibu telah tiba!"
  },
  AvgDialog_19083_Content_32 = {
    Text = "Dia akan bangkit dari @1, menyebabkan @2 Kedatangan!"
  },
  AvgDialog_19083_Content_33 = {
    Text = "Dia akan bangkit dari @1, menyebabkan @2 Kedatangan!"
  },
  AvgDialog_19083_Content_34 = {
    Text = "Tiga bulan kemudian"
  },
  AvgDialog_19083_Content_35 = {
    Text = "Kamu membuat wanita itu semakin pusing. Bukankah beberapa bulan lalu dia masih sangat penurut? Kenapa sekarang tidak mau lagi mendengarkan perkataan Ibu?"
  },
  AvgDialog_19083_Content_36 = {
    Text = "Gadis itu melirik Goliath, lalu dengan keras menancapkan pahat ke kayu dan melemparkan alat serta bahan itu ke samping."
  },
  AvgDialog_19083_Content_37 = {Text = "Ibu, Ibu?"},
  AvgDialog_19083_Content_38 = {
    Text = "Kamu... dari mana kamu mempelajari ungkapan seperti itu?"
  },
  AvgDialog_19083_Content_39 = {
    Text = "Kamus! Lihat, \"wanita dewasa yang merawat anak kecil dan memiliki Tautan emosional.\""
  },
  AvgDialog_19083_Content_4 = {
    Text = "Cairan berwarna merah segar muncul di atas dada, mekar dengan memesona di permukaan air hitam yang tenang——"
  },
  AvgDialog_19083_Content_40 = {
    Text = "Tidak, aku tidak akan menjadi ibumu."
  },
  AvgDialog_19083_Content_41 = {
    Text = "Kamu adalah gadis suci dari ordo, orang terpilih yang mulia... Jika kamu bersedia, kamu bisa langsung memanggil namaku."
  },
  AvgDialog_19083_Content_42 = {
    Text = "Umm... Mili... Yam?"
  },
  AvgDialog_19083_Content_43 = {Text = "Ya, Santa."},
  AvgDialog_19083_Content_44 = {
    Text = "Saya adalah hamba setiamu."
  },
  AvgDialog_19083_Content_45 = {
    Text = "...Dia bukan ibuku, dan tak pernah menjadi ibuku."
  },
  AvgDialog_19083_Content_46 = {
    Text = "Hanya orang-orang dari Gereja Penerang Kuil yang tahu asal-usulku. Aku juga tidak memiliki ibu. Aku hanyalah hadiah yang mereka berikan kepada Miryam."
  },
  AvgDialog_19083_Content_47 = {
    Text = "Oh? Apakah dia benar-benar memberitahumu tentang hal ini?"
  },
  AvgDialog_19083_Content_48 = {
    Text = "Bagi seorang tahanan yang sudah ditentukan tanggal kematiannya, mengetahui berapa banyak rahasia tidak masalah lagi, karena pada akhirnya semua akan aku bawa ke dalam kubur."
  },
  AvgDialog_19083_Content_49 = {
    Text = "Ini juga merupakan kompensasi dari wanita itu untukmu. Ingatlah, pada hari ketika embrio dewa dipindahkan ke tubuhmu, Imam Agung kita tidak beristirahat sepanjang malam."
  },
  AvgDialog_19083_Content_5 = {
    Text = "Namun, dia terus tenggelam, akar yang berlumuran darah membawanya ke dalam kedalaman terdalam, ke dalam pelukan yang lembut namun dingin."
  },
  AvgDialog_19083_Content_50 = {
    Text = "Rasa bersalah benar-benar menyiksanya."
  },
  AvgDialog_19083_Content_51 = {
    Text = "Rasa bersalah? Apakah kamu bercanda? Dia tidak akan memiliki perasaan seperti itu."
  },
  AvgDialog_19083_Content_52 = {
    Text = [[
Benar-benar tanpa ampun, Putri Kecil. 
Jika seorang gadis terlalu dingin, itu bisa membuat Ibu bersedih, lho.]]
  },
  AvgDialog_19083_Content_53 = {
    Text = "Apa kamu tidak bosan! Sudah kubilang, dia bukan ibuku!"
  },
  AvgDialog_19083_Content_54 = {
    Text = "Ini belum tentu. Apakah kamu ingin mendengar sebuah cerita?"
  },
  AvgDialog_19083_Content_55 = {
    Text = [[
<BigShake: Tidak mau mendengar, aku juga tidak ingin melihatmu!>
Jika kau datang untuk mengejekku, kau bisa pergi!]]
  },
  AvgDialog_19083_Content_56 = {
    Text = "Tidak, kamu pasti ingin mendengarnya."
  },
  AvgDialog_19083_Content_57 = {
    Text = "Nada suara Goliath tiba-tiba menjadi dalam, membawa keagungan seorang veteran medan perang, hingga kedua jantung di tubuh Murphy nyaris berhenti berdetak karenanya."
  },
  AvgDialog_19083_Content_58 = {
    Text = "Dia tiba-tiba menyadari — raksasa itu sejak awal bukanlah mainan yang bisa dia kendalikan sesuka hati. \n Dia hanya memanfaatkan statusnya untuk bertindak semena-mena, sementara pihak lain hanya menikmati hiburan belaka."
  },
  AvgDialog_19083_Content_59 = {
    Text = "Ya... ya, silakan berbicara."
  },
  AvgDialog_19083_Content_60 = {
    Text = [[
Ada sebuah sekte misterius yang, demi menjaga kemurnian absolut garis keturunan, semua pernikahan ditentukan oleh pemimpin sekte. 
 Mereka yang menikah dan memiliki anak dengan orang luar pada akhirnya akan menghadapi hukuman.]]
  },
  AvgDialog_19083_Content_61 = {
    Text = "Dalam penyelesaian terakhir, sang eksekutor kembali dengan seorang bayi — bayi perempuan yang dapat melihat <Yellow:keberadaan Roh>."
  },
  AvgDialog_19083_Content_62 = {
    Text = "Bayi perempuan..."
  },
  AvgDialog_19083_Content_63 = {
    Text = "Dia berada terlalu lama di ruang rahasia di bawah tubuh ibunya. Ketika para penganut menemukannya, dia hampir tersedak oleh <Red:darah ibu kandungnya>."
  },
  AvgDialog_19083_Content_64 = {
    Text = "Wanita biasa yang tidak berprestasi ini, pencapaian terbesar dalam hidupnya adalah melahirkan seorang putri dengan kualitas yang luar biasa, dan berusaha keras agar dia tidak dibawa pergi oleh gereja."
  },
  AvgDialog_19083_Content_65 = {
    Text = "——Betapa indahnya ikatan ibu dan anak ini, aku hampir meneteskan air mata karenanya."
  },
  AvgDialog_19083_Content_66 = {
    Text = "Goliath... kamu..."
  },
  AvgDialog_19083_Content_67 = {
    Text = "Kenapa... kenapa kau memberitahuku semua ini?"
  },
  AvgDialog_19083_Content_68 = {
    Text = "Muram bukanlah hal yang baik, ingatlah bahwa perkembangan <Blue:Tuhan> bergantung pada Negara inang."
  },
  AvgDialog_19083_Content_69 = {
    Text = "Lakukan apa pun yang kamu sukai, buat kerusakan, cambuk Pelaut, siksa pelayanmu… terserah apa saja."
  },
  AvgDialog_19083_Content_70 = {
    Text = "Goliath secara sepihak mengakhiri percakapan ini, tanpa emosi menepuk puncak kepalanya."
  },
  AvgDialog_19083_Content_71 = {
    Text = "Saat pergi, dia melirik patung kayu yang dilemparkan Murphy ke sudut dinding. Keterampilan gadis itu sangat buruk; bentuk di atas alas kayu tampak besar dan aneh, membuat siapa pun merasa jengkel hanya dengan melihatnya sekilas."
  },
  AvgDialog_19083_Content_72 = {Text = "Cih."},
  AvgDialog_19083_Content_73 = {
    Text = "Setelah Goliath pergi, ruangan itu menjadi sepenuhnya sunyi. Bahkan korban-korban yang menunggu di dalam sangkar tidak mengeluarkan suara sedikit pun."
  },
  AvgDialog_19083_Content_74 = {
    Text = "Murphy duduk di samping api unggun untuk waktu yang lama, sampai cahayanya mulai meredup dan api unggun hampir padam. Barulah ia seperti tersadar dari mimpi dan menepuk pipinya sendiri."
  },
  AvgDialog_19083_Content_75 = {
    Text = "Dia menendang keras salah satu kandang di sisinya, membuat wanita yang tampak lelah dan meringkuk di sudut kandang itu gemetar karena takut."
  },
  AvgDialog_19083_Content_76 = {
    Text = "Hei, kau pasti sudah mendengarnya tadi, kan."
  },
  AvgDialog_19083_Content_77 = {Text = "Ya, ya..."},
  AvgDialog_19083_Content_78 = {
    Text = "Aku tidak membantumu dengan sia-sia. Setelah kamu berhasil melarikan diri, aku ingin kamu mencari cara untuk kembali dan membawaku juga."
  },
  AvgDialog_19083_Content_79 = {
    Text = "Saya khawatir tidak memiliki kemampuan sebesar itu, saya hanyalah seorang ilmuwan biasa…"
  },
  AvgDialog_19083_Content_8 = {
    Text = [[
Dia melihatnya. 
Dia menengadah, "Ibu" menurunkan tiga pasang tangkai mata, saling bertatapan dengannya.]]
  },
  AvgDialog_19083_Content_80 = {
    Text = "Jadi, coba pikirkan cara! Otak seorang ilmuwan pasti tidak akan kehabisan akal sama sekali!"
  },
  AvgDialog_19083_Content_81 = {
    Text = "Melihat wajah gadis yang menahan air mata, wanita itu teringat akan sosok putrinya yang sudah memudar dalam memori, akhirnya hatinya pun luluh oleh belas kasihan."
  },
  AvgDialog_19083_Content_82 = {
    Text = "Jangan terlalu bersedih."
  },
  AvgDialog_19083_Content_83 = {
    Text = "Dulu, ketika saya menghadapi hambatan dalam Penelitian, saya sering tidak bisa tidur sepanjang malam. Pada saat seperti itu, saya akan diam-diam pergi ke kamar putri saya dan duduk di sisi tempat tidurnya sambil memandanginya."
  },
  AvgDialog_19083_Content_84 = {
    Text = "Dia begitu kecil, begitu penurut... Saat memikirkan bahwa semua yang kulakukan adalah untuk memberinya masa depan yang lebih baik, semua rasa lelah terasa tidak berarti."
  },
  AvgDialog_19083_Content_85 = {
    Text = "Aku juga pernah menjadi seorang ibu, aku tahu... ibu kandungmu pasti sangat menantikan kelahiranmu. Di dunia ini, pasti ada seseorang yang mencintaimu."
  },
  AvgDialog_19083_Content_87 = {
    Text = "Apa kamu sudah cukup bicara? Jangan ikut campur urusan pribadi nona ini, pikirkan saja keselamatan dirimu sendiri!"
  },
  AvgDialog_19083_Content_88 = {
    Text = "\"Maafkan aku…\"\n\"Aku… tidak ingin mati…\""
  },
  AvgDialog_19083_Content_89 = {
    Text = "Aku juga tidak ingin... semuanya berakhir seperti ini..."
  },
  AvgDialog_19083_Content_9 = {
    Text = "Itu adalah sebuah benda raksasa berwarna merah tua, bagian yang terkena darah menjadi transparan putih. \"Ibu\"memancarkan cahaya redup, untuk sementara menerangi sepetak kecil dunia."
  },
  AvgDialog_19084_Content_1 = {
    Text = "Kalian membiarkan sopir pergi."
  },
  AvgDialog_19084_Content_10 = {
    Text = "Sejak awal, serangan mereka sudah memiliki tujuan tertentu, untuk memaksa kita ke sini —— <Blue:Pos 2 Deramaga Ketiga>."
  },
  AvgDialog_19084_Content_11 = {
    Text = "Tapi di sini sepertinya tidak ada yang istimewa……"
  },
  AvgDialog_19084_Content_12 = {
    Text = "Ya, dermaga nomor 2 ini tidak memiliki keistimewaan apa pun."
  },
  AvgDialog_19084_Content_13 = {
    Text = "Yang benar-benar bermasalah adalah <Blue:kapal> yang berhenti di sini."
  },
  AvgDialog_19084_Content_14 = {Text = "Kapal?"},
  AvgDialog_19084_Content_15 = {
    Text = "Kata-kata Ramona membangkitkan angin kencang, yang seketika membubarkan kabut tebal di pikiran."
  },
  AvgDialog_19084_Content_16 = {Text = "!"},
  AvgDialog_19084_Content_17 = {
    Text = "Sebuah kapal raksasa muncul tanpa suara di belakang kalian, menutupi bulan dan menghalangi sinarnya, menyelimuti semua orang dalam kegelapan."
  },
  AvgDialog_19084_Content_18 = {
    Text = "Apakah kapal ini baru saja berada di sini?"
  },
  AvgDialog_19084_Content_19 = {
    Text = "Sepertinya itu selalu ada, hanya saja karena beberapa alasan yang tidak diketahui, kita terus mengabaikannya."
  },
  AvgDialog_19084_Content_2 = {
    Text = "Jumlah musuh terlalu banyak, dan jalan mundur sudah terkepung oleh mereka."
  },
  AvgDialog_19084_Content_20 = {
    Text = "Korosi pada lambung kapal eksternal sangat parah, sehingga cat asli kapal raksasa itu sudah tidak terlihat lagi, dan nama kapal yang dicat putih juga sulit dibedakan."
  },
  AvgDialog_19084_Content_21 = {
    Text = "Sona… Neel?"
  },
  AvgDialog_19084_Content_22 = {
    Text = [[
<Blue:Sonanier>. 
Erica, are there any records in the Mythag archives?]]
  },
  AvgDialog_19084_Content_23 = {
    Text = "Sonnier, dulunya milik <Blue:Perusahaan Pelayaran Bintang Hitam>, beroperasi sebagai kapal penumpang untuk tugas pelayaran lintas samudra. Setelah perusahaan bangkrut, Sonnier diakuisisi secara anonim oleh pihak swasta, mengubah registrasi pelayaran dan dirombak menjadi kapal kargo."
  },
  AvgDialog_19084_Content_24 = {
    Text = "Senior William! Apakah Anda tahu tentang kapal ini?"
  },
  AvgDialog_19084_Content_25 = {
    Text = "Pada tahun Hongji 288, kapal Sonanier tenggelam dalam sebuah badai. Beberapa tahun kemudian, catatan penampakan <Blue:\"kapal hantu\"> mulai bermunculan di sepanjang pantai Laut Utara."
  },
  AvgDialog_19084_Content_26 = {
    Text = "Pernah ada Penyelidik Mythag yang naik ke kapal Sonnelier, tetapi tidak membawa kembali intelijen yang berguna."
  },
  AvgDialog_19084_Content_27 = {
    Text = "Tidak membawa kembali intelijen yang berguna..."
  },
  AvgDialog_19084_Content_28 = {
    Text = "Tapi ini berarti bahwa Penyelidik itu kembali ke sekolah dengan selamat, kan?"
  },
  AvgDialog_19084_Content_29 = {
    Text = [[
Ya, meskipun sebagian memori-nya hilang, naik kapal tidak membawa dampak abnormal lain pada tubuhnya. 
Setelah beristirahat sejenak, dia kembali ke garis depan penyelidikan.]]
  },
  AvgDialog_19084_Content_3 = {
    Text = "Permukaan laut yang diterangi cahaya bulan masih menyimpan riak, dan di kedalaman Aequor yang tidak dapat ditembus cahaya, entah berapa banyak musuh yang masih tersembunyi."
  },
  AvgDialog_19084_Content_30 = {
    Text = "Bisakah meminta senior itu untuk bergabung dalam komunikasi?"
  },
  AvgDialog_19084_Content_31 = {
    Text = "Sayang sekali, jauh sebelum kamu bergabung dengan Mythag, dia gugur saat menjalankan sebuah misi."
  },
  AvgDialog_19084_Content_32 = {Text = "Tunggu!"},
  AvgDialog_19084_Content_33 = {
    Text = "Ramona, jangan-jangan kamu ingin..."
  },
  AvgDialog_19084_Content_34 = {
    Text = "Ya, aku tidak berpikir mereka akan membiarkan kita menunggu sampai bantuan tiba."
  },
  AvgDialog_19084_Content_35 = {
    Text = "Lingkaran pengepungan semakin menyempit, senjata musuh sudah terarah ke ujung kaki."
  },
  AvgDialog_19084_Content_36 = {
    Text = "Kami sekarang menaiki kapal."
  },
  AvgDialog_19084_Content_4 = {
    Text = "Mundur@2——！@1！Ajar@1！"
  },
  AvgDialog_19084_Content_5 = {
    Text = "Setelah lingkaran pengepungan dipersempit seminimal mungkin, monster ikan tidak melanjutkan serangan, melainkan berdiri tegang di depan salah satu dermaga, terus-menerus mengucapkan gumaman aneh yang sulit dipahami."
  },
  AvgDialog_19084_Content_6 = {
    Text = "Serangan berhenti?"
  },
  AvgDialog_19084_Content_8 = {
    Text = "Ramona, ada apa?"
  },
  AvgDialog_19084_Content_9 = {
    Text = "Baik itu memanfaatkan jumlah untuk menggiring kita ke sisi utara, atau akhirnya menutup pintu keluar, musuh selalu memberikan jalan bagi kita."
  },
  AvgDialog_19085_Content_1 = {
    Text = "Akhirnya selesai…"
  },
  AvgDialog_19085_Content_10 = {
    Text = "Rahang bawah ikan Pelaut membuka hingga batas maksimal, dan jaringan membran daging Tautan yang menghubungkan rahang atas dan bawah teregang hingga menjadi semi-transparan."
  },
  AvgDialog_19085_Content_11 = {
    Text = "Dorongan dari rasa takut, harapan, dan keyakinan memunculkan vitalitas hidup yang luar biasa. Dengan tiba-tiba, ia menabrakmu dan berlari keluar menuju ruang kekuatan sambil melolong keras."
  },
  AvgDialog_19085_Content_12 = {
    Text = "Buruk, dia akan melarikan diri!"
  },
  AvgDialog_19085_Content_2 = {
    Text = "Murphy menendang Pelaut yang kehilangan kesadaran, tubuhnya yang mirip ikan berguling lemas menjauh."
  },
  AvgDialog_19085_Content_3 = {
    Text = "Kali ini mereka seharusnya tidak bisa melanjutkan pertempuran lagi... hanya beberapa orang yang menyedihkan, biarkan saja mereka."
  },
  AvgDialog_19085_Content_4 = {
    Text = "Ayo cepat tinggalkan tempat ini."
  },
  AvgDialog_19085_Content_5 = {
    Text = "Guh... guh..."
  },
  AvgDialog_19085_Content_6 = {
    Text = "Di antara para Pelaut yang terbaring lemas, ada satu orang yang menopang Tubuhnya dengan senjata patah, gemetar dan perlahan bangkit."
  },
  AvgDialog_19085_Content_7 = {
    Text = "Kenapa... kenapa... dari sisi Tuan @4... kenapa?"
  },
  AvgDialog_19085_Content_8 = {
    Text = "Ibu Dewa, Ibu Dewa… guk, guk…!"
  },
  AvgDialog_19085_Content_9 = {
    Text = "……Tuan, @4 Tuan!"
  },
  AvgDialog_19086_Content_1 = {
    Text = "Tangan berwarna abu-abu kebiruan menyembul dari bawah puing-puing, telapak tangan berselaput mencengkeram sepatu Murphy."
  },
  AvgDialog_19086_Content_2 = {
    Text = "Guh, guh uuuu..."
  },
  AvgDialog_19086_Content_3 = {
    Text = "Orang ini masih hidup!? Padahal sudah terjebak di bawah reruntuhan."
  },
  AvgDialog_19086_Content_4 = {
    Text = "Dewa... Dewa@1..."
  },
  AvgDialog_19086_Content_5 = {
    Text = "...Jangan mendekatiku!"
  },
  AvgDialog_19087_Content_1 = {
    Text = "Bau busuk yang menyengat perlahan-lahan masuk ke dalam hidung."
  },
  AvgDialog_19087_Content_2 = {
    Text = "Pelaut-pelaut dipanggil oleh pemimpin mereka, lalu mereka berbondong-bondong keluar dari kabin-kabin di segala arah."
  },
  AvgDialog_19088_Content_1 = {
    Text = "Dari ujung dek terdengar langkah kaki yang berat. Sebuah suara pria kasar berbicara dalam bahasa yang belum pernah didengar sebelumnya, dan musuh yang mengepung pun surut seperti air pasang."
  },
  AvgDialog_19088_Content_10 = {
    Text = "Ramona menoleh ke belakang, namun tidak ada seorang pun di sana. Keduanya ternyata terpisah di dalam lingkaran pengepungan musuh yang tertutup ini."
  },
  AvgDialog_19088_Content_11 = {
    Text = "Astaga! <Yellow:%player%>!"
  },
  AvgDialog_19088_Content_12 = {
    Text = "Dari balik tumpukan peti kargo yang tidak jauh, terdengar suara gesekan aneh."
  },
  AvgDialog_19088_Content_13 = {
    Text = "Jangan bersembunyi, aku tahu kamu di sana. Sekarang bukan waktunya untuk bercanda, \"Tuan Muda Ais\"."
  },
  AvgDialog_19088_Content_14 = {
    Text = "Ramona menggelengkan kepalanya dengan rasa putus asa, dia melemparkan darah kotor dari ujung pedangnya, lalu memasukkan senjatanya kembali ke dalam sarung sambil berjalan menuju sudut yang dipenuhi peti kargo."
  },
  AvgDialog_19088_Content_15 = {
    Text = "@1@2……!"
  },
  AvgDialog_19088_Content_16 = {Text = "Apa…!"},
  AvgDialog_19088_Content_18 = {
    Text = [[
Serangan kuat menembus peti kargo dan juga menembus musuh. 
 Darah biru kehitaman yang menempel di tentakel bercampur dengan serpihan kayu, mengeluarkan bau amis yang menyengat.]]
  },
  AvgDialog_19088_Content_19 = {
    Text = "Pemilik tentakel tiba-tiba melemparkan tubuh alien yang menempel padanya, kotak kargo pun hancur berantakan. \n——Sosok pemuda muncul di hadapan Ramona."
  },
  AvgDialog_19088_Content_2 = {
    Text = "Tuan! Ini adalah perintah dari pemimpin upacara…"
  },
  AvgDialog_19088_Content_20 = {Text = "!?"},
  AvgDialog_19088_Content_21 = {
    Text = "Tanpa persetujuan dari ketua tim operasi luar, dan sebelum dihubungkan oleh penyelidik, Pembangun tidak diizinkan meninggalkan wilayah Mythag, saya kira kamu sudah tahu hal ini..."
  },
  AvgDialog_19088_Content_22 = {
    Text = "Bangun Pembangun Tulu, nomor arsip-6291, kode nama <Blue:\"Tuan Tidur\">."
  },
  AvgDialog_19088_Content_23 = {
    Text = "Yu percaya bahwa kau juga sudah tahu, aturan-aturan yang kalian sebut \"hukum\" itu tidak berarti apa-apa di hadapan Yu."
  },
  AvgDialog_19088_Content_24 = {
    Text = "Lagipula, jangan gunakan kode nama bodoh itu untuk merujuk pada saya."
  },
  AvgDialog_19088_Content_25 = {Text = "Tulu."},
  AvgDialog_19088_Content_26 = {
    Text = "Saya bukan orang yang berpikiran kaku di Komite. Pembangun bagi saya bukanlah binatang buas yang perlu diborgol, dan sekarang juga bukan saatnya untuk mengejar apa yang disebut \"melarikan diri dari rumah\"."
  },
  AvgDialog_19088_Content_27 = {
    Text = [[
Yang aku khawatirkan adalah, kamu tidak ada dalam daftar personel untuk misi lapangan, tanpa tautan dari siapa pun. 
Menjauh terlalu lama dari <Yellow:Inti> Mythag akan membuatmu kehilangan kendali.]]
  },
  AvgDialog_19088_Content_28 = {
    Text = "Tidak apa-apa, aku tidak akan dikuasai oleh insting."
  },
  AvgDialog_19088_Content_29 = {
    Text = [[
Pembangun mempertahankan bentuk seorang pemuda, namun setiap ucapan dan tindakannya dipenuhi dengan tekanan dari seorang yang berkuasa. 
Hanya dengan sekilas pandang saja, sudah cukup membuat bulu kuduk orang merinding.]]
  },
  AvgDialog_19088_Content_3 = {
    Text = "Maksud Anda adalah..."
  },
  AvgDialog_19088_Content_30 = {Text = "… Huh."},
  AvgDialog_19088_Content_31 = {
    Text = "Ramona menghela napas panjang, lalu menatapnya kembali."
  },
  AvgDialog_19088_Content_32 = {
    Text = "——Aku hanya ingin tahu, mengapa kamu bisa muncul di sini? \nKamu selalu dalam keadaan tidur panjang, bahkan mutasi saat <Yellow:Upacara Penganugerahan Kunci Perak> pun tak mampu membangunkanmu."
  },
  AvgDialog_19088_Content_33 = {
    Text = "Tapi sekarang, kamu rela mengambil risiko kehilangan akal sehatmu hanya untuk muncul di sini… Pasti ada sesuatu yang sangat berarti bagimu terjadi di kapal ini."
  },
  AvgDialog_19088_Content_34 = {
    Text = [[
Segala sesuatu yang terjadi di sini, semuanya karena diriku. 
Adapun detailnya, itu tidak ada hubungannya denganmu.]]
  },
  AvgDialog_19088_Content_35 = {
    Text = "Benarkah? Apakah ikan-ikan yang mengejar kita tidak ada hubungannya denganku? Ataukah Penjaga yang tersesat tidak ada hubungannya denganku?"
  },
  AvgDialog_19088_Content_37 = {
    Text = [[
Prioritas utama adalah menemukan Penjaga, lalu meninggalkan kapal ini.
Oleh karena itu, aku tidak akan melanjutkan pertanyaan ini.]]
  },
  AvgDialog_19088_Content_38 = {
    Text = "Kamu bisa tetap diam sekarang, tapi kamu tahu bahwa aku akan menemukan jawabannya."
  },
  AvgDialog_19088_Content_4 = {
    Text = "...Baik, aku mengerti."
  },
  AvgDialog_19088_Content_5 = {
    Text = "Jangan pergi! Siapa kalian sebenarnya?"
  },
  AvgDialog_19088_Content_6 = {
    Text = "Pemuda Pembangun menyimpan senjatanya, dia berbalik dan melihat Ramona sekilas, tidak lagi terlibat dalam pertempuran, lalu menghilang di dek bersama kelompoknya."
  },
  AvgDialog_19088_Content_7 = {
    Text = "Apa ini… apa yang sedang terjadi?"
  },
  AvgDialog_19088_Content_8 = {
    Text = "Sekarang tidak ada waktu untuk memikirkan hal lain, tujuan sebenarnya mereka bukan kita… Manfaatkan kesempatan ini untuk segera mencari cara turun dari kapal."
  },
  AvgDialog_19088_Content_9 = {
    Text = "Kita harus berhati-hati dan menghindari para murloc... Penjaga!"
  },
  AvgDialog_19089_Content_1 = {
    Text = "Dalam waktu setengah jam bersama Murphy, kamu sudah muntah sebanyak tiga kali."
  },
  AvgDialog_19089_Content_2 = {
    Text = "Pusing yang kuat dan rasa mual selalu datang bersamaan, cairan lambung yang mengalir kembali membakar tenggorokan hingga terasa nyeri."
  },
  AvgDialog_19089_Content_3 = {
    Text = "Kepala terasa sakit..."
  },
  AvgDialog_19089_Content_4 = {
    Text = [[
Apakah kamu akan mati? 
 Aku, aku akan mencari bantuan untukmu, tunggu aku!]]
  },
  AvgDialog_19089_Content_5 = {
    Text = "Jangan, jangan bergerak sendirian, terlalu berbahaya."
  },
  AvgDialog_19089_Content_6 = {
    Text = [[
Saya merasa jauh lebih baik, sungguh.
Ayo pergi, rekan saya masih menunggu.]]
  },
  AvgDialog_19090_Content_1 = {
    Text = [[
Murphy menatap langit yang berputar dengan aliran cahaya aneh.
Burung-burung berputar di bawah tirai cahaya, sinarnya melengkung dan lembut, menghalangi kemungkinan badai dan angin kencang dari luar.]]
  },
  AvgDialog_19090_Content_10 = {
    Text = [[
Benar. Dengan kata lain, baik bagi Murphy maupun bagi kita, <Blue:Celeste> adalah kunci. 
Dan sekarang dia... mungkin berada di bawah kendali pemimpin Pelaut, Miryam.]]
  },
  AvgDialog_19090_Content_11 = {
    Text = "Sialan... perempuan itu..."
  },
  AvgDialog_19090_Content_12 = {
    Text = "Murphy menutupi dadanya dengan ekspresi serius saat dia menatap batas Domain."
  },
  AvgDialog_19090_Content_13 = {
    Text = "Yang dia pedulikan hanyalah kelahiran kembali Dewa, selain itu tidak ada yang lain yang dia anggap penting."
  },
  AvgDialog_19090_Content_14 = {
    Text = "Dia akan membunuh semua orang. Pada akhirnya, monster ini akan mengunyah jantungku hingga tidak tersisa sedikit pun."
  },
  AvgDialog_19090_Content_15 = {
    Text = "Aku tidak ingin... mati seperti ini..."
  },
  AvgDialog_19090_Content_16 = {
    Text = "Sejenak, keheningan menyebar bak kematian."
  },
  AvgDialog_19090_Content_2 = {
    Text = "Dalam catatan Ordo Pelaut, pentingnya <Blue:Selaras Bintang> ditekankan berulang kali. Upacara kelahiran juga harus dilakukan pada waktu tertentu, itulah alasan mengapa wanita itu membuatku tertidur."
  },
  AvgDialog_19090_Content_3 = {
    Text = [[
Kapten berspekulasi bahwa pertumbuhan-Nya mungkin terkait dengan aturan pergerakan benda langit. 
Oleh karena itu, Celeste menciptakan Domain ini dengan kapal sebagai pusatnya, menjadikannya tempat yang terisolasi dari dunia luar.]]
  },
  AvgDialog_19090_Content_4 = {
    Text = [[
Kami menebak dengan benar. Sejak meninggalkan langit yang sebenarnya, Dia juga menjadi tenang. 
 Selama kita bisa bersembunyi di Domain dan menghindari waktu Selaras ini, mungkin Dia akan terus berhibernasi selamanya.]]
  },
  AvgDialog_19090_Content_5 = {
    Text = "Tunggu, Celeste?"
  },
  AvgDialog_19090_Content_6 = {
    Text = "Bisakah seseorang menjelaskan ini padaku dulu? Siapa itu \"Celeste\"?"
  },
  AvgDialog_19090_Content_7 = {
    Text = "Eh? Apakah aku belum menjelaskan ini kepadamu?"
  },
  AvgDialog_19090_Content_8 = {
    Text = [[
Celeste adalah rekan kapten, sekaligus seorang Pembangun.
Dialah yang mengendalikan Sonnelier yang seharusnya tenggelam untuk tetap berlayar, dan menciptakan Domain ini.]]
  },
  AvgDialog_19090_Content_9 = {
    Text = "Apakah kita bisa kembali ke daratan juga bergantung padanya?"
  },
  AvgDialog_19091_Content_1 = {
    Text = "Murphy menjadi murung, kamu tidak tahu bagaimana cara menghiburnya. Sementara itu, Ramona terpaku memandang burung laut di langit."
  },
  AvgDialog_19091_Content_10 = {
    Text = [[
Berdasarkan perhitungan Observatorium Kerajaan, bulan seharusnya mencapai perigeenya sekitar <Blue:Hari St. Patrick>. 
Fase bulan saat ini bertentangan dengan hukum ilmiah.]]
  },
  AvgDialog_19091_Content_11 = {
    Text = "Apakah kamu bisa berbicara bahasa Inggris?"
  },
  AvgDialog_19091_Content_12 = {
    Text = [[
Ya, malam itu bulan sangat besar. 
Bulan bersinar begitu terang hingga semua konstelasi lainnya tidak terlihat.]]
  },
  AvgDialog_19091_Content_13 = {
    Text = "Apa, apa?! Ternyata hari ini..."
  },
  AvgDialog_19091_Content_14 = {
    Text = "Meskipun kita bisa melarikan diri dengan selamat dari tangan Pelaut, makhluk di dalam jantungku ini tetap akan menghabisi nyawaku."
  },
  AvgDialog_19091_Content_15 = {
    Text = "Jika ada metode lain yang dapat mengisolasi benda langit, mungkin itu bisa memberimu lebih banyak waktu."
  },
  AvgDialog_19091_Content_16 = {
    Text = "<Big:Bicara seenaknya!> Menghentikan waktu, menciptakan ruang... mana pun itu bukan permainan anak-anak. Bahkan aku tahu itu tidak semudah itu."
  },
  AvgDialog_19091_Content_17 = {
    Text = "Tunggu, ada! Francis!"
  },
  AvgDialog_19091_Content_18 = {
    Text = "Kamar Lily!"
  },
  AvgDialog_19091_Content_19 = {
    Text = "Ya. Boneka dan Nyonya Kerang sedang melakukan penelitian terhadap ruangan itu, berharap dapat menciptakan ruang yang tidak terdeteksi untuk eksperimen."
  },
  AvgDialog_19091_Content_2 = {
    Text = "Untuk menghindari tekanan udara berbahaya di kapal, formasi burung yang sedang berputar tercerai-berai, dan burung-burung laut langsung menukik ke arah cahaya dengan warna aneh itu —"
  },
  AvgDialog_19091_Content_20 = {
    Text = "Penelitian sudah mulai terbentuk. Sebelum keberangkatan kami kali ini, Nyonya Kerang telah mulai mempersiapkan eksperimen pada hewan."
  },
  AvgDialog_19091_Content_21 = {
    Text = "Jangan sia-siakan pikiranmu."
  },
  AvgDialog_19091_Content_22 = {
    Text = [[
Sekolah kalian... tidak mungkin berada di laut, kan.
Kembali ke daratan dari sini, lalu bergegas ke sekolah kalian... tidak akan sempat.]]
  },
  AvgDialog_19091_Content_23 = {
    Text = "Apalagi Celeste ada di tangan wanita itu… Masih belum jelas apakah kapal ini bisa berlabuh atau tidak."
  },
  AvgDialog_19091_Content_24 = {
    Text = [[
Tanpa sadar, kamu melihat ke arah Ramona.
Dia mengerutkan alisnya, namun posturnya tetap tegak dan tidak kenal menyerah. Dia masih memikirkan cara terbaik untuk melindungi semua orang.]]
  },
  AvgDialog_19091_Content_25 = {Text = "Ramona"},
  AvgDialog_19091_Content_26 = {
    Text = "Dia menatapmu selama beberapa saat, lalu dengan penuh pemahaman tersenyum."
  },
  AvgDialog_19091_Content_27 = {
    Text = "Ayo pergi, jika ini yang kamu harapkan."
  },
  AvgDialog_19091_Content_3 = {
    Text = "Satu, dua, tiga… mereka berbaris menabrak langit, berharap bisa melarikan diri dari ruang ini, namun semuanya terhalau kembali oleh Domain dengan lembut."
  },
  AvgDialog_19091_Content_5 = {
    Text = "Tirai, setelah terus-menerus dihantam oleh burung-burung laut, tiba-tiba menjadi transparan sesaat. Momen singkat ini segera lenyap, namun Ramona dengan tepat menangkapnya ——"
  },
  AvgDialog_19091_Content_6 = {
    Text = "Barusan apa ... Domain menghilang sesaat."
  },
  AvgDialog_19091_Content_7 = {
    Text = "Ya… memang benar, aku merasakan Dia berdetak sekali."
  },
  AvgDialog_19091_Content_8 = {
    Text = [[
Menopang Domain yang terisolasi dari tarikan benda langit, Nona Celeste mungkin sudah menggunakan seluruh kekuatannya. 
Melawan serangan Pelaut adalah beban yang terlalu besar baginya.]]
  },
  AvgDialog_19091_Content_9 = {
    Text = "Benda langit... eh, apakah sekarang sudah malam di luar? Bagaimana bentuk bintang dan bulan terlihat?"
  },
  AvgDialog_19092_Content_10 = {
    Text = "Di sini terdapat peta."
  },
  AvgDialog_19092_Content_11 = {
    Text = "Lantai ini memiliki pintu masuk ke Ruang Kekuatan… Mari kita lihat, arah jejak sepatu menuju ke sana."
  },
  AvgDialog_19092_Content_12 = {
    Text = "Bertindak sembarangan sangat berbahaya dan bukan pilihan yang bijaksana."
  },
  AvgDialog_19092_Content_13 = {
    Text = [[
Justru karena berbahaya, aku harus pergi. 
 Aku tidak bisa membiarkan Penjaga menghadapi musuh sendirian.]]
  },
  AvgDialog_19092_Content_14 = {
    Text = "...Baiklah, jika kamu bersikeras seperti itu."
  },
  AvgDialog_19092_Content_2 = {
    Text = "Ada beberapa jejak di sini."
  },
  AvgDialog_19092_Content_3 = {
    Text = "Air laut membasahi debu yang menumpuk, meninggalkan jejak-jejak kacau yang luas di ruang kargo: jejak kaki berselaput, bekas seretan berbentuk ular, dan jejak seretan kain…"
  },
  AvgDialog_19092_Content_4 = {
    Text = "Jejak sepatu!"
  },
  AvgDialog_19092_Content_5 = {
    Text = "Ramona berjongkok di samping tangga, memperhatikan sejenak, lalu bangkit dan dengan lembut menginjak di samping jejak sepatu."
  },
  AvgDialog_19092_Content_6 = {
    Text = "Pola pada sepatu seragam siswa konsisten, Penjaga pernah datang ke sini."
  },
  AvgDialog_19092_Content_7 = {
    Text = "Di sini terdapat pola lainnya."
  },
  AvgDialog_19092_Content_8 = {
    Text = "Ukuran sepatu lebih kecil daripada punyaku, mungkin ini bekas anak kecil."
  },
  AvgDialog_19092_Content_9 = {
    Text = "Tidak bisa melacak, jejak sepatu menghilang di sini…"
  },
  AvgDialog_19093_Content_1 = {
    Text = "Dia adalah Pembangun!"
  },
  AvgDialog_19093_Content_10 = {
    Text = "Tawa gila bergema di Domain, suasana semakin tegang ——"
  },
  AvgDialog_19093_Content_11 = {
    Text = "Kalian pergilah."
  },
  AvgDialog_19093_Content_12 = {Text = "Apa?"},
  AvgDialog_19093_Content_13 = {
    Text = "Jangan begitu waspada, memang bukan tanggung jawabku untuk menangani tikus kecil yang berkeliaran... Heh, <Blue:Lentera> orang-orang itu, bahkan hal sepele seperti ini saja tidak bisa mereka lakukan."
  },
  AvgDialog_19093_Content_14 = {
    Text = "Namun, berkat mereka, upacara ini sekarang menjadi lebih menarik."
  },
  AvgDialog_19093_Content_15 = {
    Text = "Tidak hanya terkait dengan <Blue:Gereja penerang kuil>, tetapi juga <Blue:ritual> yang kau sebutkan…"
  },
  AvgDialog_19093_Content_16 = {
    Text = "Goliath... siapa kamu sebenarnya?"
  },
  AvgDialog_19093_Content_17 = {
    Text = [[
Siapa aku? <Big:Hahahahaha!>
Kenapa tidak bertanya kepada orang di sebelahmu?]]
  },
  AvgDialog_19093_Content_18 = {
    Text = "Saya, dan dari mana para Pelaut ini berasal — Anda pasti bisa menebaknya, bukan? Lagipula, Anda adalah yang tertinggi..."
  },
  AvgDialog_19093_Content_19 = {
    Text = "Melampaui batas!"
  },
  AvgDialog_19093_Content_2 = {
    Text = "Kekuatan yang luar biasa, bahkan dari sudut pandang Pembangun, sulit ada yang bisa menyamai."
  },
  AvgDialog_19093_Content_20 = {
    Text = "Menakutkan, sangat menakutkan——namun sayangnya, aku bukan salah satu dari pengikut setiamu."
  },
  AvgDialog_19093_Content_21 = {
    Text = "Saya masih harus melanjutkan persiapan untuk ritual, tidak punya waktu untuk terus berdebat dengan kalian."
  },
  AvgDialog_19093_Content_22 = {
    Text = "Meskipun kamu bersembunyi ke sana-sini dengan menggunakan tentakel, kamu tahu — hanya kamu yang bisa memberikan apa yang diinginkan oleh wanita itu."
  },
  AvgDialog_19093_Content_23 = {
    Text = "——Goliath, tunggu sebentar!"
  },
  AvgDialog_19093_Content_24 = {
    Text = "Oh? Ada keperluan penting lainnya, Nona Kecil?"
  },
  AvgDialog_19093_Content_25 = {
    Text = "Saya suka orang yang punya keberanian untuk menantang otoritas. Sebelum saya kehilangan kesabaran, kamu masih memiliki satu kesempatan untuk bertanya."
  },
  AvgDialog_19093_Content_26 = {
    Text = "Terkait……"
  },
  AvgDialog_19093_Content_27 = {
    Text = "Tentang Gereja Penerang Kuil… Saya masih memiliki pertanyaan untukmu."
  },
  AvgDialog_19093_Content_3 = {
    Text = "Kekuatan ini…"
  },
  AvgDialog_19093_Content_4 = {
    Text = "Keraguan Tulu baru saja terlihat, raksasa itu juga berhenti melakukan serangan seolah-olah sedang memikirkan sesuatu."
  },
  AvgDialog_19093_Content_5 = {
    Text = "Jadi begitu… kamu ternyata bergaul dengan orang-orang dari Universitas Mythag."
  },
  AvgDialog_19093_Content_6 = {
    Text = "Goliath memandang kedua orang itu dengan tatapan tajam dan menusuk, lalu tertawa terbahak-bahak."
  },
  AvgDialog_19093_Content_7 = {
    Text = "<Big:Ha, hahahaha!> Menarik, sangat menarik!"
  },
  AvgDialog_19093_Content_8 = {
    Text = "Jika <Blue:wanita itu> melihat adegan ini, ekspresi macam apa yang akan dia tunjukkan——tidak akan langsung gila kan?"
  },
  AvgDialog_19093_Content_9 = {
    Text = "Hahahaha, aku sangat menantikan saat itu!"
  },
  AvgDialog_19094_Content_1 = {
    Text = [[
22:00
Sonanier
Ruang Kekuatan]]
  },
  AvgDialog_19094_Content_10 = {
    Text = "Di atas kapal sangat berbahaya. Aku akan berusaha membuat kapal sebisa mungkin mendekati pantai, tetapi setelah itu kalian harus menggunakan perahu penyelamat untuk kembali ke daratan dengan berlayar."
  },
  AvgDialog_19094_Content_11 = {
    Text = "Bagaimana dengan kalian? Sekarang musuh ada di mana-mana di kapal. Sangat berbahaya jika kalian tetap tinggal di sini."
  },
  AvgDialog_19094_Content_12 = {
    Text = "Ini adalah kapal kita, di dalam kapal adalah Domain milik <Blue:Celeste>, kita akan baik-baik saja."
  },
  AvgDialog_19094_Content_13 = {
    Text = "Gadis Pembangun yang bernama Celeste melihat sekilas ke arah semua orang dan mengeluarkan suara hidung yang hampir tak terdengar."
  },
  AvgDialog_19094_Content_14 = {
    Text = "Domain adalah manifestasi dari kehendak Celeste. Para Pelaut adalah keberadaan yang tidak diakui olehnya dan seharusnya dicegah masuk ke dalam Domain."
  },
  AvgDialog_19094_Content_15 = {
    Text = "Apakah mungkin…!"
  },
  AvgDialog_19094_Content_16 = {
    Text = "Kedatangan kami di kapal menyebabkan ketidakstabilan di Domain. \n Meskipun aku telah menurunkan tangga, Pelaut masih berhasil menembus Domain dari tempat lain… benar kan?"
  },
  AvgDialog_19094_Content_17 = {
    Text = "Maaf, kami…"
  },
  AvgDialog_19094_Content_18 = {
    Text = "Ini bukan kesalahan kalian. Keputusan untuk membiarkanmu naik kapal adalah keputusan bersama kami."
  },
  AvgDialog_19094_Content_19 = {
    Text = "\"Melindungi umat manusia\" adalah sebuah beban yang harus dipikul oleh Celeste. Sebagai temannya, saya akan berusaha semaksimal mungkin untuk mendukungnya."
  },
  AvgDialog_19094_Content_2 = {
    Text = "Terlalu berbahaya, bukankah aku sudah bilang untuk tidak mendekat?"
  },
  AvgDialog_19094_Content_20 = {
    Text = "Ugh...! Ekh, ekkk!"
  },
  AvgDialog_19094_Content_21 = {Text = "……!"},
  AvgDialog_19094_Content_22 = {
    Text = "Kapten batuk hebat, tubuh Pembangun yang Bangun juga berkedip sesaat."
  },
  AvgDialog_19094_Content_23 = {
    Text = "Tulu tiba-tiba muncul di samping Celeste, dengan tentakel yang menandakan identitasnya sebagai makhluk non-manusia menyentuh pundaknya."
  },
  AvgDialog_19094_Content_24 = {
    Text = "Keberadaannya sangat lemah, Yu berpikir bahwa dia tidak akan bisa mempertahankan kesadarannya untuk waktu yang lama."
  },
  AvgDialog_19094_Content_25 = {
    Text = "Celeste tidak akan kehilangan akal, aku tidak akan membiarkannya berubah menjadi monster yang tak terkendali."
  },
  AvgDialog_19094_Content_26 = {
    Text = "Berdasarkan hidup manusia yang rapuh dan Gnosis yang samar, dari mana datangnya kepercayaan dirimu?"
  },
  AvgDialog_19094_Content_27 = {Text = "Tulu!"},
  AvgDialog_19094_Content_28 = {
    Text = [[
Jangan terburu-buru, siswi. 
Pembangun muda berkata benar.]]
  },
  AvgDialog_19094_Content_29 = {
    Text = "Menjaga keberadaan Celeste membutuhkan konsumsi yang tidak sedikit… Namun, selalu ada cara."
  },
  AvgDialog_19094_Content_3 = {
    Text = [[
Anda baru saja melihatnya, saya memiliki kemampuan untuk menghadapi para Pelaut ini. 
Nama saya Ramona, apakah Anda kapten?]]
  },
  AvgDialog_19094_Content_30 = {
    Text = "Reaksi Celeste selalu sangat lemah, dia seperti lukisan indah namun tanpa kehidupan, atau patung haluan kapal layar dari zaman kuno, dengan tenang memandangi dunia dan lautan."
  },
  AvgDialog_19094_Content_31 = {
    Text = "Namun, pada saat itu, seolah-olah untuk merespons perkataan Kapten Elton, dia sedikit membungkuk dan menyentuh tepi topi kapten."
  },
  AvgDialog_19094_Content_32 = {
    Text = "Ramona baru menyadari kondisi sang kapten — pria tinggi besar itu bernapas dengan sangat lemah, dan saat berdiri, tangan serta kakinya gemetar tak terkendali."
  },
  AvgDialog_19094_Content_33 = {
    Text = "Tubuh Anda…"
  },
  AvgDialog_19094_Content_34 = {
    Text = "Aku baik-baik saja, ini sudah biasa."
  },
  AvgDialog_19094_Content_35 = {
    Text = "Ngomong-ngomong, kenapa hanya ada kamu di sini? Aku jelas-jelas melihat dua siswa—\nCeleste, apakah kamu bisa merasakan keberadaan siswa lainnya?"
  },
  AvgDialog_19094_Content_36 = {
    Text = [[
Gadis yang namanya dipanggil menatap ujung jarinya, tidak segera merespons perkataan kapten.
Setelah beberapa saat, Celeste baru mengangkat kepala dan menatap Ramona.]]
  },
  AvgDialog_19094_Content_37 = {
    Text = [[
... Tidak ada lagi. 
 Kecuali Elton, Murphy, dan ...]]
  },
  AvgDialog_19094_Content_38 = {
    Text = "Dan kamu... selain itu, tidak ada orang lain."
  },
  AvgDialog_19094_Content_39 = {
    Text = "Bagaimana mungkin?! Kita baru saja terpisah selama setengah jam."
  },
  AvgDialog_19094_Content_4 = {
    Text = "Elton, atau cukup panggil aku Kapten."
  },
  AvgDialog_19094_Content_40 = {
    Text = "Dan aku bisa merasakan hubungan dengan Penjaga, {Male=dia,Female=dia} pasti masih di kapal."
  },
  AvgDialog_19094_Content_41 = {
    Text = [[
Jangan terburu-buru, siswi. Segalanya akan beres pada waktunya. 
Jika temanmu sehebat dirimu, {Male=dia,Female=dia} pasti akan baik-baik saja.]]
  },
  AvgDialog_19094_Content_42 = {
    Text = "Jangan lupa bekas sepatu."
  },
  AvgDialog_19094_Content_43 = {
    Text = "Jejak sepatu.."
  },
  AvgDialog_19094_Content_44 = {
    Text = "Betul! Penjaga mungkin sedang bepergian bersama seorang anak."
  },
  AvgDialog_19094_Content_45 = {
    Text = [[
Anak? Aku mengerti...
Itu <Blue:Murphy>, satu-satunya penumpang di kapal ini.]]
  },
  AvgDialog_19094_Content_5 = {
    Text = "Kapten Elton mengeluarkan kotak rokok dari tas pinggangnya, baru saja mengambil sejumput daun tembakau terakhir, ketika saputangan putih yang berkibar tiba-tiba menyentuh tangannya."
  },
  AvgDialog_19094_Content_6 = {
    Text = "Dia menghela napas panjang dan menyimpan kembali kotak rokoknya."
  },
  AvgDialog_19094_Content_7 = {
    Text = "Kamu orang dari Universitas Mythag, kan? Aku ingat seragam sekolah ini."
  },
  AvgDialog_19094_Content_8 = {
    Text = "Ya, bertahun-tahun yang lalu, seorang senior dari sekolah kami pernah menaiki kapal ini."
  },
  AvgDialog_19094_Content_9 = {
    Text = [[
Sayang sekali, sekarang bukan waktu yang tepat. 
Jika di hari lain, aku masih bisa menuangkan segelas anggur dan mengobrol denganmu.]]
  },
  AvgDialog_19095_Content_10 = {
    Text = "Tidak... tidak... Dia telah berjanji kepadaku..."
  },
  AvgDialog_19095_Content_11 = {
    Text = "Wanita yang kurus akhirnya menunjukkan reaksi. Dia perlahan mengangkat kepalanya dengan tatapan kosong, sambil bergumam tanpa henti."
  },
  AvgDialog_19095_Content_12 = {
    Text = "Dewa yang Mahakuasa akan menjalankan kuasa-Nya... dan menurunkan hukuman kepada mereka yang membuat barang palsu, kaum kafir yang tidak terampuni!"
  },
  AvgDialog_19095_Content_13 = {
    Text = "Dia mencabut belati dari pinggangnya, api ungu-hitam seperti kabut kental menutupi mata pisaunya, memancarkan aura kematian yang mencekam."
  },
  AvgDialog_19095_Content_14 = {
    Text = "Ada api pada belati itu!"
  },
  AvgDialog_19095_Content_15 = {
    Text = "Palsu… matilah kau!"
  },
  AvgDialog_19095_Content_16 = {
    Text = "Ikuti aku ke belakang!"
  },
  AvgDialog_19095_Content_17 = {
    Text = "——Api kematian yang dingin dan misterius di atas belati, menyalakan debu batubara."
  },
  AvgDialog_19095_Content_18 = {
    Text = "<BigShake:Yaah!>"
  },
  AvgDialog_19095_Content_19 = {
    Text = "Di tengah reaksi berantai antara api dan debu, udara mengembang dengan cepat, dan gemuruh ledakan yang memekakkan telinga menyelimuti semua orang."
  },
  AvgDialog_19095_Content_2 = {
    Text = "Bangunan-bangunan ini sedang menghilang."
  },
  AvgDialog_19095_Content_20 = {
    Text = "Di depan adalah api yang membesar dengan cepat, di belakang adalah dinding kabin yang terbuka lebar akibat ledakan."
  },
  AvgDialog_19095_Content_21 = {
    Text = "%player%, berikan tanganmu padaku!"
  },
  AvgDialog_19095_Content_22 = {
    Text = "Gaya benturan merobek logam lambung kapal. Di tengah cahaya berkilauan dan api yang saling bersilangan, tanganmu dan tangan gadis itu hanya berlalu begitu saja tanpa bisa saling menyentuh."
  },
  AvgDialog_19095_Content_23 = {
    Text = "——Kamu jatuh ke dalam Aequor."
  },
  AvgDialog_19095_Content_3 = {
    Text = "Ini adalah ilusi yang dibangun oleh Miryam, mungkin inilah <Blue:Ranah dewa> yang pernah ia sebutkan…"
  },
  AvgDialog_19095_Content_4 = {
    Text = [[
Kedatangan kembali Ranah Dewa... obsesi yang menopangnya selama ribuan tahun akhirnya hancur begitu saja. 
 Tulu, apakah kamu... memiliki kata-kata penghiburan?]]
  },
  AvgDialog_19095_Content_6 = {
    Text = "Musuh mendapatkan kembali sebagian kesadaran dari kehilangan kendali, sambil kehilangan bentuk anehnya."
  },
  AvgDialog_19095_Content_7 = {
    Text = "Miryam terbaring dalam kelemahan di tengah debu hitam, pandangannya kosong dan penuh ilusi. Bahkan ketika Tulu datang ke hadapannya, dia tidak memberikan reaksi apa pun."
  },
  AvgDialog_19095_Content_8 = {
    Text = "Jangan bersikeras lagi, Miryam."
  },
  AvgDialog_19095_Content_9 = {
    Text = "Era kita, <Blue:Kerajaan Abadi> kita, kehancurannya sudah ditakdirkan."
  },
  AvgDialog_19096_Content_1 = {
    Text = "Komunikator kita, apakah harganya mahal?"
  },
  AvgDialog_19096_Content_2 = {
    Text = "Inti Perak yang digunakan dalam kernel dapat ditukar dengan properti di pusat Londinium di pasar gelap."
  },
  AvgDialog_19096_Content_3 = {Text = "?!"},
  AvgDialog_19097_Content_1 = {
    Text = "Serangan menembus dinding sisi Ruang Kekuatan, bayangan ular seperti kabut saling bertautan dalam kelompok, menghancurkan keseimbangan pertempuran yang sebelumnya berlangsung sengit."
  },
  AvgDialog_19097_Content_10 = {
    Text = "Kalian tidak perlu terlibat dalam hal ini."
  },
  AvgDialog_19097_Content_11 = {
    Text = "Elton menggertakkan gigi, melangkah maju selangkah, dan berdiri di depan Ramona dan Celeste."
  },
  AvgDialog_19097_Content_12 = {
    Text = "Yang Terhormat Pemimpin Upacara, saya tidak memahami apa yang Anda maksud."
  },
  AvgDialog_19097_Content_13 = {
    Text = "Sampai sekarang… apakah kamu masih keras kepala?"
  },
  AvgDialog_19097_Content_14 = {
    Text = "Wanita itu melangkah ke barisan terdepan para Pelaut, dan Ramona dapat dengan jelas melihat wajahnya."
  },
  AvgDialog_19097_Content_15 = {
    Text = "Ini adalah wanita yang muncul saat mereka untuk pertama kalinya dikepung setelah naik ke kapal."
  },
  AvgDialog_19097_Content_16 = {
    Text = "Tidak termaafkan... Tidak termaafkan, tidak bisa dimaafkan!"
  },
  AvgDialog_19097_Content_17 = {
    Text = "Celeste! Cepat!"
  },
  AvgDialog_19097_Content_18 = {
    Text = "Celeste mengangkat kompas di tangannya tinggi-tinggi, cahaya yang berkilauan seperti burung terbang berputar-putar di sekitar Ramona."
  },
  AvgDialog_19097_Content_19 = {
    Text = "Dalam sekejap, dia telah dikirim keluar dari ruang kekuatan oleh kekuatan yang tak terlawankan itu."
  },
  AvgDialog_19097_Content_2 = {
    Text = [[
Di antara kerumunan bayangan kosong, sosok wanita yang anggun perlahan melangkah masuk ke ruang kekuatan.
Seiring dengan kedatangannya, udara di sekitarnya tampak membeku.]]
  },
  AvgDialog_19097_Content_20 = {Text = "Ramona?!"},
  AvgDialog_19097_Content_21 = {Text = "Itu kamu!"},
  AvgDialog_19097_Content_3 = {Text = "Astaga…!"},
  AvgDialog_19097_Content_4 = {
    Text = "Harta karun dan harapanku..."
  },
  AvgDialog_19097_Content_5 = {
    Text = "Kapten Elton, aku pernah mempercayai kesetiaanmu... dan ini adalah balasanmu kepadaku?"
  },
  AvgDialog_19097_Content_6 = {
    Text = "Kekuatan yang dapat berkumpul menjadi bentuk... Apakah dia juga seorang Bangun?"
  },
  AvgDialog_19097_Content_7 = {
    Text = "Celeste, cepat antar siswi ini dan Pembangunnya pergi!"
  },
  AvgDialog_19097_Content_8 = {
    Text = "Tunggu?! Kapten, mungkin kami bisa membantu—"
  },
  AvgDialog_19097_Content_9 = {
    Text = "Melalui asap yang mengepul dari gerombolan ular, Ramona mencoba menangkap jejak Tulu, namun di Ruang Kekuatan tidak ditemukan tanda-tanda keberadaan Pembangun muda itu."
  },
  AvgDialog_19098_Content_1 = {
    Text = [[
<Yellow:Pelarutan> Apa ini? Luka hitam ini? 
 Di tubuh ibu kandungnya juga terdapat banyak bekas luka serupa.]]
  },
  AvgDialog_19098_Content_2 = {
    Text = "Setengah tahun yang lalu, ketika aku terbangun dari tidur panjang, Pelarutan itu masih seperti biji wijen. Seiring dengan pertumbuhan-Nya, luka itu juga semakin membesar…"
  },
  AvgDialog_19098_Content_3 = {
    Text = "Terkadang, saat malam yang sunyi, aku bahkan bisa mendengar suara cairan mengalir keluar dari lukaku…"
  },
  AvgDialog_19098_Content_4 = {Text = "Murphy…"},
  AvgDialog_19098_Content_5 = {
    Text = "Simpan ekspresi belas kasihan itu, selesaikan dulu orang-orang ini."
  },
  AvgDialog_19099_Content_1 = {
    Text = [[
22:30
Kapal Sonanier
Geladak Tiga]]
  },
  AvgDialog_19099_Content_10 = {
    Text = [[
Dia tidak memiliki seratus tahun pengalaman, tidak memiliki pengetahuan yang melampaui masanya, dan tidak memiliki pengalaman hidup di dunia manusia. 
 Menanggalkan identitasnya sebagai Perawan Suci dari ordo, kehidupannya bahkan lebih sederhana dibandingkan dengan gadis-gadis seusianya.]]
  },
  AvgDialog_19099_Content_11 = {
    Text = "Lepas peniti"
  },
  AvgDialog_19099_Content_12 = {
    Text = "Kamu pegang ini, tetaplah di sini."
  },
  AvgDialog_19099_Content_13 = {
    Text = [[
Warisan, warisan? 
 Aku memperingatkan kalian, jangan mati sembarangan!]]
  },
  AvgDialog_19099_Content_14 = {
    Text = "Ini adalah sebuah komunikator, meskipun untuk sementara tidak berfungsi di dalam Domain, pihak sekolah pasti terus mencoba menghubungi kita."
  },
  AvgDialog_19099_Content_15 = {
    Text = [[
Jika kamu bisa melihat <Yellow:Pelarutan> dengan mata telanjang, maka kamu pasti memiliki cukup kekuatan roh untuk menggunakan komunikator ini. 
 Fokuskan perhatianmu saat pin di dada menyala, dan kamu akan bisa berkomunikasi dengan orang di sisi lain.]]
  },
  AvgDialog_19099_Content_16 = {
    Text = "Apa sih... berlagak seolah-olah siap mati dengan gagah berani."
  },
  AvgDialog_19099_Content_17 = {
    Text = "Murphy mencengkeram erat pin dada."
  },
  AvgDialog_19099_Content_18 = {
    Text = "Hei! Cepat kembali! Jika kapal sudah berlabuh, aku tidak akan menunggu kalian!"
  },
  AvgDialog_19099_Content_2 = {
    Text = "Tunggu, kalian mau pergi ke mana?!"
  },
  AvgDialog_19099_Content_3 = {
    Text = [[
Miss Celeste tidak mampu menghadapi musuh, tapi mungkin kita bisa. 
Menghentikan ritual sesat juga merupakan salah satu tugas Penyelidik Mythag.]]
  },
  AvgDialog_19099_Content_4 = {
    Text = [[
Hanya kalian?! Jangan bercanda, ini sama saja dengan mencari mati! 
Dia itu monster, monster! Tidak ada yang bisa menghentikannya!]]
  },
  AvgDialog_19099_Content_5 = {
    Text = "Jika ini adalah jam terakhir dalam hidup, aku tidak akan menyia-nyiakan waktu untuk berdoa."
  },
  AvgDialog_19099_Content_6 = {
    Text = "Saya percaya kamu juga tidak akan melakukannya, kan? Kalau tidak, mengapa harus bersusah payah melarikan diri dari sekte?"
  },
  AvgDialog_19099_Content_7 = {Text = "Aku..."},
  AvgDialog_19099_Content_8 = {
    Text = "Ini bukan hanya untukmu, tahu tidak? Kami juga sedang menunggu untuk turun dari kapal."
  },
  AvgDialog_19099_Content_9 = {
    Text = "Kenyamanan yang diberikan Ramona secara halus tidak berhasil, Murphy masih kebingungan dengan wajah penuh kecemasan."
  },
  AvgDialog_19100_Content_1 = {
    Text = "Para Pelaut ini... benar-benar berwujud seperti ikan."
  },
  AvgDialog_19100_Content_10 = {
    Text = "Benar... Ini adalah sesuatu yang hanya bisa kita lakukan."
  },
  AvgDialog_19100_Content_11 = {
    Text = "Bersiaplah, Roh musuh akan datang!"
  },
  AvgDialog_19100_Content_2 = {
    Text = "Apakah Murphy dibesarkan sejak kecil oleh orang-orang yang penampilannya sama sekali berbeda dengannya?"
  },
  AvgDialog_19100_Content_3 = {
    Text = "Ya, jadi aku sangat terkejut bahwa dia memiliki pandangan hidup yang mirip dengan orang biasa. Ini sungguh sebuah keajaiban."
  },
  AvgDialog_19100_Content_4 = {
    Text = "Namun, untuk saat ini, kita harus berharap pada keajaiban lain."
  },
  AvgDialog_19100_Content_5 = {
    Text = "Untuk menggagalkan ritual"
  },
  AvgDialog_19100_Content_6 = {
    Text = "Benar. Jika ritual dibiarkan berlanjut, entah monster apa yang akan menetas dari sesuatu di dalam tubuh Murphy."
  },
  AvgDialog_19100_Content_7 = {
    Text = "Hanya dengan kekuatan kita, sepertinya kita tidak bisa mengakhiri semua ini. \nNamun, jika tujuannya hanya menyelamatkan Nyonya Celeste agar Murphy bisa meninggalkan kapal ini lebih dulu…"
  },
  AvgDialog_19100_Content_8 = {
    Text = "Ini adalah sesuatu yang hanya bisa kita lakukan."
  },
  AvgDialog_19101_Content_1 = {
    Text = "Siswi! Jangan mendekati area ini!"
  },
  AvgDialog_19101_Content_2 = {
    Text = "Pria paruh baya berteriak keras, sebagian besar perhatian para Pelaut tertuju padanya."
  },
  AvgDialog_19101_Content_3 = {
    Text = "Dengan pakaian ini, kemungkinan besar dia adalah kapten."
  },
  AvgDialog_19101_Content_4 = {
    Text = "Dan juga gadis di sisinya... tidak boleh membiarkan mereka dalam bahaya."
  },
  AvgDialog_19101_Content_5 = {
    Text = "Guh... serangan...!"
  },
  AvgDialog_19101_Content_6 = {
    Text = "Hati-hati, musuh telah melihat kita."
  },
  AvgDialog_19102_Content_1 = {
    Text = "Ciiiiiiiiisssssss——"
  },
  AvgDialog_19102_Content_10 = {
    Text = "Tapi tidak apa-apa, kita akan kembali ke daratan dengan selamat."
  },
  AvgDialog_19102_Content_11 = {
    Text = "Murphy... apakah kamu baik-baik saja? Tidak perlu memaksakan diri."
  },
  AvgDialog_19102_Content_12 = {
    Text = "Siapa yang memaksakan diri? Aku tidak melihatnya — tunggu, bukankah ada satu di depan mata?"
  },
  AvgDialog_19102_Content_13 = {
    Text = "Seseorang selamat dari <Yellow:ledakan>, tetapi mengalami kerusakan otak parah akibat benturan. Meski begitu, dia masih bersikeras mengatakan bahwa dirinya baik-baik saja."
  },
  AvgDialog_19102_Content_14 = {
    Text = "Tunggu, tunggu. Kamu sedang membicarakan siapa?"
  },
  AvgDialog_19102_Content_15 = {
    Text = "Kamu memang sangat beruntung, tapi melihat kondisimu sekarang, sepertinya kepalamu tetap mengalami cedera internal——"
  },
  AvgDialog_19102_Content_16 = {Text = "Ya!"},
  AvgDialog_19102_Content_17 = {
    Text = "Lambung kapal kembali mengeluarkan suara keras, seperti pertanda sebelum hancur berkeping-keping. Lantai dek di bawah kaki juga terasa bergetar dengan lembut."
  },
  AvgDialog_19102_Content_18 = {
    Text = "Sonanier kehilangan kendali... Waktuku sudah tidak banyak lagi."
  },
  AvgDialog_19102_Content_19 = {
    Text = "Harus menemukan Kapten dan yang lainnya, serta Ramona, lalu segera turun dari kapal."
  },
  AvgDialog_19102_Content_2 = {
    Text = "Ujung yang tajam menembus keluar dari dada abu-abu kebiruan, cairan berhamburan, dan Pelaut pun jatuh dengan suara keras."
  },
  AvgDialog_19102_Content_20 = {
    Text = "Kata-kata dari Murphy sekali lagi menusuk pikiranmu, hanya saja kali ini kamu tidak merasakan keinginan untuk muntah, melainkan merasa lebih sadar daripada sebelumnya."
  },
  AvgDialog_19102_Content_21 = {
    Text = "Murphy, apa yang baru saja kamu katakan?"
  },
  AvgDialog_19102_Content_22 = {
    Text = "Apakah yang rusak bukan hanya otak?"
  },
  AvgDialog_19102_Content_23 = {
    Text = "Aku berkata, harus·menemukan·kapten·mereka·dan·<Blue:La·Mon·Na>——"
  },
  AvgDialog_19102_Content_24 = {
    Text = "Inilah kalimatnya!"
  },
  AvgDialog_19102_Content_25 = {
    Text = "Murphy, dari awal hingga akhir, aku tidak pernah menyebutkan nama pasanganmu."
  },
  AvgDialog_19102_Content_26 = {
    Text = "Nama Ramona, dari mana kamu mengetahuinya?"
  },
  AvgDialog_19102_Content_3 = {
    Text = "...Maaf, aku tidak bisa membiarkanmu pergi."
  },
  AvgDialog_19102_Content_4 = {
    Text = "Murphy menundukkan pandangannya, menatap belati itu selama beberapa saat, lalu menghapus cairan kental berwarna abu-abu kehijauan yang menempel di atasnya."
  },
  AvgDialog_19102_Content_5 = {
    Text = "Dia baru saja ingin memberi tahu... Sial, apakah ada orang yang memimpin para Pelaut di kapal ini..."
  },
  AvgDialog_19102_Content_6 = {
    Text = "Ayo pergi, kita tidak bisa tinggal di sini terlalu lama."
  },
  AvgDialog_19102_Content_7 = {
    Text = "Ruang kekuatan sudah hancur."
  },
  AvgDialog_19102_Content_8 = {
    Text = "Ya... sudah sepenuhnya menjadi reruntuhan."
  },
  AvgDialog_19102_Content_9 = {
    Text = "Murphy berada di samping pintu kabin, menoleh ke belakang untuk melihat ruang kekuatan yang berantakan, dengan bulu matanya bergetar gelisah."
  },
  AvgDialog_19103_Content_1 = {
    Text = "Ramona, apakah kamu punya petunjuk untuk mengeluarkan benda itu?"
  },
  AvgDialog_19103_Content_2 = {
    Text = "Ramona melihat Murphy, lalu menatapmu, dengan wajah penuh kebingungan."
  },
  AvgDialog_19103_Content_3 = {
    Text = "Katakan saja apa yang ingin kamu katakan, jangan malu-malu."
  },
  AvgDialog_19103_Content_4 = {
    Text = "Pembuluh darah telah menyatu dengan aortamu, bahkan dokter bedah paling terampil pun tidak dapat menjamin keberhasilan operasi seperti itu."
  },
  AvgDialog_19103_Content_5 = {
    Text = "Dia sekarang berada dalam keadaan Negara tidur... Masih ada waktu untuk mencari cara lain."
  },
  AvgDialog_19103_Content_6 = {Text = "Tidur?"},
  AvgDialog_19103_Content_7 = {
    Text = "Kau bilang, Dia sedang beristirahat?"
  },
  AvgDialog_19103_Content_8 = {
    Text = "Hanya sementara."
  },
  AvgDialog_19104_Content_1 = {
    Text = "Murphy menginjak kakinya dengan keras, dengan wajah yang sangat enggan mendekati denah di dinding kabin."
  },
  AvgDialog_19104_Content_10 = {
    Text = "Hu, <Small:Aku pikir kamu juga tidak mengerti.>"
  },
  AvgDialog_19104_Content_11 = {Text = "Juga?"},
  AvgDialog_19104_Content_12 = {
    Text = [[
<BigShake: Tidak, tidak ada apa-apa!>
Lihatlah dengan baik.]]
  },
  AvgDialog_19104_Content_13 = {
    Text = "Baik, baik."
  },
  AvgDialog_19104_Content_14 = {
    Text = "Kami berada di bawah tangga sisi haluan... Murphy, menurutmu di mana orang lain mungkin berada? Apakah di ruang kemudi di buritan?"
  },
  AvgDialog_19104_Content_15 = {
    Text = "Aku mana tahu! Tapi kalau mau ke kokpit, harus lewat dek, atau bisa juga melewati ruang kekuatan."
  },
  AvgDialog_19104_Content_16 = {
    Text = "Musuh di dek terlalu banyak, kabin masih aman, lewati ruang kekuatan... <BigShake:Ugh!>"
  },
  AvgDialog_19104_Content_17 = {
    Text = "<Blue:\"Ruang kekuatan\"> Kata ini tampaknya membawa semacam kekuatan. Setelah suku kata terakhir diucapkan, serangan pusing yang sangat kuat hingga bisa menjatuhkan seseorang kembali menghantam otakmu."
  },
  AvgDialog_19104_Content_18 = {
    Text = "Rasa mual yang sangat kuat membuatmu tak mampu menjaga keseimbangan, kamu tiba-tiba menabrak dinding kabin dan mulai mengalami muntah kering dengan hebat."
  },
  AvgDialog_19104_Content_19 = {
    Text = "Hek, hekhek! … Ooh…"
  },
  AvgDialog_19104_Content_2 = {Text = "Hmm..."},
  AvgDialog_19104_Content_20 = {
    Text = "Tidak... tidak apa-apa, kan?! Kenapa kamu muntah lagi?"
  },
  AvgDialog_19104_Content_3 = {
    Text = "Saya akan melihat."
  },
  AvgDialog_19104_Content_4 = {
    Text = "Saat melihat denah, rasa déjà vu yang kuat langsung menyergapmu."
  },
  AvgDialog_19104_Content_5 = {
    Text = "Di <Blue:masa lalu>, di <Blue:dalam mimpi>, di <Blue:suatu waktu yang tak diketahui>, sepertinya kamu mengalami kejadian serupa."
  },
  AvgDialog_19104_Content_6 = {
    Text = "Di sisinya juga ada seorang gadis manja yang keras kepala dan tidak mau menundukkan kepala kepada orang lain. Mereka sama-sama berada di kapal asing, dan sama-sama sedang mengamati alur yang terukir pada pelat logam."
  },
  AvgDialog_19104_Content_7 = {
    Text = "Déjà vu seperti kail ikan yang tak terlihat, dan kamu adalah ikan kecil malang yang telah menggigit umpan, ditarik menuju ujung rawa tanpa bisa melawan——"
  },
  AvgDialog_19104_Content_8 = {
    Text = "Apa yang sedang kamu pikirkan?"
  },
  AvgDialog_19104_Content_9 = {
    Text = "...Tidak ada apa-apa, mungkin aku terlalu lelah."
  },
  AvgDialog_19105_Content_1 = {
    Text = "Ruang kekuatan tidak sesuai dengan bayanganmu yang penuh semangat: tidak ada pekerja berotot, tidak ada ketel uap yang menyala-nyala."
  },
  AvgDialog_19105_Content_10 = {
    Text = "Murphy menatap belati itu sejenak, lalu tiba-tiba menggunakan tangan dan kakinya untuk memanjat timbunan puing-puing yang bertumpuk, berusaha meraih belati itu——"
  },
  AvgDialog_19105_Content_11 = {
    Text = "Murphy, berhati-hatilah!"
  },
  AvgDialog_19105_Content_12 = {Text = "Ya!"},
  AvgDialog_19105_Content_2 = {
    Text = "Hanya percikan api yang tak terabaikan berterbangan ke segala arah."
  },
  AvgDialog_19105_Content_3 = {
    Text = "Bagaimana bisa di sini..."
  },
  AvgDialog_19105_Content_4 = {
    Text = "<Shake:khukhukh>… baunya sangat tidak sedap."
  },
  AvgDialog_19105_Content_5 = {
    Text = "Dinding kapal terbuka dengan lubang besar, angin dingin berhembus masuk ke dalam kabin satu per satu. Murphy mencubit cuping telinganya yang membeku hingga memerah, melangkahi api, dan melangkah ke dalam reruntuhan."
  },
  AvgDialog_19105_Content_6 = {
    Text = "Hmm? Sepertinya ada sesuatu..."
  },
  AvgDialog_19105_Content_7 = {
    Text = "Di antara reruntuhan, ada sesuatu yang memantulkan cahaya yang menyolok."
  },
  AvgDialog_19105_Content_8 = {
    Text = "—— adalah sebuah belati, tergeletak diam di antara bara api yang telah padam. Meskipun bilahnya penuh dengan debu, kelebatannya yang tajam masih terlihat jelas."
  },
  AvgDialog_19106_Content_1 = {
    Text = "Seseorang datang."
  },
  AvgDialog_19106_Content_2 = {
    Text = "... pintu depan, Pelaut."
  },
  AvgDialog_19107_Content_1 = {
    Text = "Dermaga ini juga terlalu besar."
  },
  AvgDialog_19107_Content_10 = {
    Text = "Saya setuju dengan pandanganmu tentang Herbert, tapi jangan lupa, Pelarutan juga bisa memicu mutasi massal seperti ini."
  },
  AvgDialog_19107_Content_11 = {
    Text = "Harap kali ini bukan pengaruh dari <Yellow:Clades>…"
  },
  AvgDialog_19107_Content_2 = {
    Text = "Jangan kendur, kita hampir sampai di pintu keluar utara."
  },
  AvgDialog_19107_Content_3 = {
    Text = [[
Setelah melewati pertempuran sepanjang jalan, musuh yang masih berdiri di hadapan kalian sudah tersisa sedikit. 
Di depan sana, yang tersisa untuk kalian kalahkan hanyalah beberapa musuh kecil.]]
  },
  AvgDialog_19107_Content_4 = {
    Text = "Musuh-musuh ini... apakah mereka ada hubungannya dengan apa yang kita lakukan dalam Penyelidikan?"
  },
  AvgDialog_19107_Content_5 = {
    Text = "Tidak bisa menyangkal kemungkinan ini. Berdasarkan informasi yang dikirimkan oleh perangkat mata-mata yang ditempatkan Boneka di Herbert, termasuk Para pematung, Gereja Penerang Kuil memiliki cukup banyak organisasi terkait."
  },
  AvgDialog_19107_Content_6 = {
    Text = "Namun, anggota Gereja Penerang Kuil yang kami temui di kota kecil Rai jauh lebih elegan daripada mereka."
  },
  AvgDialog_19107_Content_7 = {
    Text = "Mereka yang mengepung kalian adalah \"ikan kecil\" sejati — tubuh mereka mirip manusia namun bungkuk, dengan kepala ikan terlihat dari balik tudung lusuh mereka."
  },
  AvgDialog_19107_Content_8 = {
    Text = "Setiap kali mereka menyerang, kamu bisa mencium bau busuk dari hidup yang memudar."
  },
  AvgDialog_19107_Content_9 = {
    Text = "Kami juga tidak bisa menyingkirkan kecurigaan terhadap Para pematung. Herbert adalah brengsek yang mempermainkan Hidup atas nama keabadian."
  },
  AvgDialog_19108_Content_1 = {
    Text = [[
Benar, benar. Bukankah kamu tadi menyebut seorang pemimpin pria? 
Apakah orang itu menyebutkan... apakah dia mengatakan sesuatu?]]
  },
  AvgDialog_19108_Content_11 = {
    Text = "Apa teka-teki yang dia ucapkan?"
  },
  AvgDialog_19108_Content_12 = {
    Text = "Goliath itu..."
  },
  AvgDialog_19108_Content_13 = {Text = "Murphy."},
  AvgDialog_19108_Content_14 = {
    Text = "Apa, apa yang sedang kau lakukan? Kenapa tiba-tiba menatapku seperti ini?"
  },
  AvgDialog_19108_Content_15 = {
    Text = [[
Kamu sangat memahami organisasi <Blue:Pelaut>, mampu membedakan pengawal pribadi, bahkan mengenal pemimpinnya. 
Sejak kita bertemu hingga sekarang, aku belum sekali pun menyebut nama <Blue:Goliath>.]]
  },
  AvgDialog_19108_Content_16 = {
    Text = "Kamu pernah menjadi bagian dari Pelaut, mungkin menduduki posisi tinggi... atau lebih tepatnya, mereka datang karena kamu."
  },
  AvgDialog_19108_Content_17 = {
    Text = "Apakah kamu yang disebut oleh Goliath sebagai <Blue:Perawan Suci>, <Blue:Putri Boneka>, <Blue:Korban Kunci Pelaut>, benar begitu?"
  },
  AvgDialog_19108_Content_18 = {Text = "Aku tidak!"},
  AvgDialog_19108_Content_19 = {
    Text = "Lalu bagaimana kamu bisa menjelaskan keakrabanmu dengan Goliath, serta penghindaranmu terhadap pemimpin?"
  },
  AvgDialog_19108_Content_2 = {
    Text = "Ramona menatap Murphy dalam-dalam — dengan pandangannya yang khas, penuh rasa ingin tahu."
  },
  AvgDialog_19108_Content_20 = {
    Text = "Aku hanya... pelayan... pelayan biasa di markas ordo, ada banyak gadis seperti aku yang tak terhitung jumlahnya!"
  },
  AvgDialog_19108_Content_21 = {
    Text = "Dalam kelompok pelaut, penampilan manusia seharusnya sangat langka. Jika tidak, berdasarkan kekuatan tempur mereka, mereka tidak perlu bekerja sama dengan Gereja penerang kuil."
  },
  AvgDialog_19108_Content_22 = {
    Text = "Jika kamu hanyalah seorang pelayan manusia yang tidak penting, mengapa mereka begitu gigih mengejarmu?"
  },
  AvgDialog_19108_Content_23 = {
    Text = "Semua ini, ini hanya..."
  },
  AvgDialog_19108_Content_24 = {
    Text = "Apakah kamu ingin mengatakan bahwa semua ini hanyalah kebetulan? Aku tidak berpikir begitu."
  },
  AvgDialog_19108_Content_25 = {
    Text = "Kapten yang membawamu ke kapal juga sudah dianggap sebagai \"pengkhianat\". Sementara Pelaut mencari-cari dirimu, mereka juga tidak melewatkan kapten tersebut."
  },
  AvgDialog_19108_Content_26 = {
    Text = "Apakah kamu sudah bertemu dengan kapten dan Celeste? Apakah mereka masih aman?"
  },
  AvgDialog_19108_Content_27 = {
    Text = [[
Mereka jatuh ke tangan pemimpin wanita, yaitu Miryam. 
 "Penghianatan" terhadap Pelaut... Saya pikir, kau akan lebih memahaminya daripada saya.]]
  },
  AvgDialog_19108_Content_28 = {
    Text = "<Small:Tidak, tidak mungkin... Dia masih mengharapkan kapten untuk bertugas demi dirinya.>"
  },
  AvgDialog_19108_Content_29 = {
    Text = "Hanya untuk pengangkutan inventaris, ada banyak kapal yang bisa berlayar bolak-balik antara daratan dan kutub."
  },
  AvgDialog_19108_Content_3 = {
    Text = "Baik, saya akan menceritakan kembali percakapan antara dia dan saya kepada kalian."
  },
  AvgDialog_19108_Content_30 = {
    Text = "Ekspresi Ramona tenang dan teguh. Dia terus menekan, bahkan menggunakan kapten dan rekannya yang saat ini kondisi mereka tidak diketahui sebagai senjata, membuat tekanan psikologis semakin meningkat."
  },
  AvgDialog_19108_Content_31 = {Text = "Ramona..."},
  AvgDialog_19108_Content_32 = {
    Text = "Kamu hampir mulai merasa kasihan pada Murphy — saat itu, Ramona mengedipkan mata padamu."
  },
  AvgDialog_19108_Content_33 = {
    Text = "Keselarasan yang tercipta dari waktu yang lama membuatmu langsung memahami maksudnya."
  },
  AvgDialog_19108_Content_34 = {
    Text = "Murphy, kami perlu mengetahui apa yang terjadi."
  },
  AvgDialog_19108_Content_35 = {
    Text = "Hanya dengan cara ini, kita memiliki kesempatan untuk bertahan hidup, dan kita bisa membantu kamu."
  },
  AvgDialog_19108_Content_37 = {
    Text = "Baiklah……"
  },
  AvgDialog_19108_Content_4 = {
    Text = "Gereja Penerang Kuil? Ha, bukan rahasia yang harus disembunyikan."
  },
  AvgDialog_19108_Content_5 = {
    Text = "Gereja penerang kuil membantu mengumpulkan <Yellow:bahan> yang diperlukan untuk ritual, sebagai imbalan, Pelaut kadang-kadang akan melakukan hal-hal yang rahasia dan tersembunyi untuk mereka…"
  },
  AvgDialog_19108_Content_6 = {
    Text = "Pelaut sulit berjalan di dunia, dan mereka menginginkan kekuatan kita… Hanya saling memanfaatkan, saling menghangatkan dalam kesendirian saja."
  },
  AvgDialog_19108_Content_7 = {
    Text = "Lalu, apa sebenarnya \"ritual\" yang kau maksud adalah…"
  },
  AvgDialog_19108_Content_8 = {
    Text = "Ha! Ini sudah pertanyaan kedua. \n Dengarkan baik-baik, Nona Kecil — aku tidak punya kewajiban untuk melaporkan apapun padamu."
  },
  AvgDialog_19108_Content_9 = {
    Text = [[
Lari, lari lebih cepat. 
Setelah bulan terbit, kalian tidak akan punya kesempatan untuk bertahan hidup.]]
  },
  AvgDialog_19109_Content_1 = {
    Text = [[
Meskipun mereka semua adalah Pelaut, kelompok ini lebih kuat daripada yang sebelumnya kita temui. 
Murphy, apakah kamu punya petunjuk?]]
  },
  AvgDialog_19109_Content_10 = {
    Text = "Selesaikan mereka terlebih dahulu."
  },
  AvgDialog_19109_Content_2 = {
    Text = "Adalah pengawal pribadi <Blue:wanita itu>, bahkan di antara Pelaut yang sering muncul monster, mereka adalah yang terbaik."
  },
  AvgDialog_19109_Content_3 = {
    Text = "\"Wanita itu\"... Apakah kamu merujuk pada pemimpin Pelaut?"
  },
  AvgDialog_19109_Content_4 = {
    Text = "Miryam, namanya adalah Miryam."
  },
  AvgDialog_19109_Content_5 = {
    Text = "Pengawal pribadi pemimpin... Tak heran lebih sulit ditaklukkan daripada yang lain."
  },
  AvgDialog_19109_Content_6 = {
    Text = "Tulu sampai tadi masih bergerak bersamaku, namun setelah kami bertemu dengan Miryam, dia tiba-tiba menghilang entah ke mana."
  },
  AvgDialog_19109_Content_7 = {
    Text = "Dengan kekuatannya, menyelesaikan para \"pengawal pribadi\" ini adalah sesuatu yang bisa ia lakukan dengan mudah."
  },
  AvgDialog_19109_Content_8 = {
    Text = "Tulu?! Bagaimana dia bisa ada di sini?"
  },
  AvgDialog_19109_Content_9 = {
    Text = "Ramona tampak serius, lalu mengangkat pedangnya kembali."
  },
  AvgDialog_19110_Content_1 = {
    Text = "Siswi, kenapa berhenti berjalan?"
  },
  AvgDialog_19110_Content_10 = {
    Text = "Benar, kesadaran dan vitalitas Tautan akan segera memudar."
  },
  AvgDialog_19110_Content_11 = {
    Text = "Untuk mempertahankan keberadaan Celeste, aku melakukan <Blue:perjanjian> dengan pemimpin Pelaut."
  },
  AvgDialog_19110_Content_12 = {
    Text = "Dia secara teratur memberikan obat yang memungkinkan saya bertahan hidup, sebagai pertukaran, kami bertugas mengangkut inventaris untuk para pelaut sepanjang tahun."
  },
  AvgDialog_19110_Content_13 = {
    Text = "Ini berarti kamu adalah rekan mereka… kalau begitu, mengapa kalian diserang oleh Pelaut?"
  },
  AvgDialog_19110_Content_14 = {
    Text = "Karena... aku <Blue:Penghianatan> orang itu."
  },
  AvgDialog_19110_Content_2 = {
    Text = "Kapten, saya punya pertanyaan ingin bertanya kepada Anda."
  },
  AvgDialog_19110_Content_3 = {
    Text = "Apakah ada semacam hubungan atau ikatan antara kamu dan Pelaut?"
  },
  AvgDialog_19110_Content_4 = {
    Text = "Pelaut memiliki penampilan yang seragam, namun kamu dapat membedakan perbedaan antar individu……tetapi pada saat yang sama, kamu juga akan menghadapi serangan dari mereka."
  },
  AvgDialog_19110_Content_5 = {
    Text = "Jangan terlalu tegang, aku ini manusia asli."
  },
  AvgDialog_19110_Content_6 = {
    Text = [[
Hanya saja, tidak seperti siswa pilihan dari Mythag yang luar biasa, aku hanyalah orang biasa.
Aku tidak memiliki bakat bawaan untuk Tautan Bangun, dan aku juga tidak bisa melihat <Yellow:Pelarutan>.]]
  },
  AvgDialog_19110_Content_7 = {
    Text = "Selama proses kebangkitan kembali Pembangun, kesadaran akan tak terhindarkan tercemar oleh <Yellow:keberadaan yang tidak diketahui>, dan pencemaran inilah yang menyebabkan mereka kehilangan kendali…"
  },
  AvgDialog_19110_Content_8 = {
    Text = "Karena kamu adalah mahasiswa Universitas mythag, seharusnya kamu tahu cara menekan kehilangan kendali, kan?"
  },
  AvgDialog_19110_Content_9 = {
    Text = "<Yellow:Tautan roh>… tetapi jika yang melakukan tautan adalah orang awam tanpa kemampuan khusus…"
  },
  AvgDialog_19111_Content_1 = {
    Text = "Nyonya Ramona, Penjaga! Di sini!"
  },
  AvgDialog_19111_Content_10 = {
    Text = "Baik, baik. Harap berhati-hati sepenuhnya!"
  },
  AvgDialog_19111_Content_11 = {
    Text = "Sopir melompat kembali ke mobil. Suara mesin yang menyala menarik perhatian banyak musuh."
  },
  AvgDialog_19111_Content_12 = {
    Text = "Hei! Pandang ke langit, lihat ke sini!"
  },
  AvgDialog_19111_Content_2 = {Text = "Pak sopir!"},
  AvgDialog_19111_Content_3 = {
    Text = "Tidak jauh di depan, pria paruh baya yang tampak akrab dengan cemas menggoyang rantai besi di pintu, dengan ekspresi sulit di wajahnya."
  },
  AvgDialog_19111_Content_4 = {
    Text = "Nona Ramona, saya tidak bisa membuka kunci ini."
  },
  AvgDialog_19111_Content_5 = {
    Text = "Tidak apa-apa, saya bisa langsung memutus rantai. Silakan mundur sedikit."
  },
  AvgDialog_19111_Content_6 = {
    Text = "Hanya tersisa 10 meter lagi untuk berhasil melarikan diri."
  },
  AvgDialog_19111_Content_7 = {
    Text = "Suara gemerisik semakin keras, sesuatu secara berturut-turut muncul dari kegelapan, udara menjadi semakin lembap dan berat."
  },
  AvgDialog_19111_Content_8 = {
    Text = "Apa? Masih banyak sekali?! Mereka menghalangi jalan kita!"
  },
  AvgDialog_19111_Content_9 = {
    Text = "Pak sopir bukan anggota pertempuran, segera pergi!"
  },
  AvgDialog_19112_Content_1 = {
    Text = [[
Mereka ini termasuk Elit di antara para Pelaut. 
 Berhati-hatilah, jangan sampai terluka.]]
  },
  AvgDialog_19113_Content_1 = {
    Text = "Pada saat melangkahkan kaki, udara terasa lembap dan berat."
  },
  AvgDialog_19113_Content_2 = {
    Text = "Napas dan detak jantung terasa tertekan dengan kuat, sensasi berdebar-debar memicu kepanikan tanpa alasan yang jelas."
  },
  AvgDialog_19113_Content_3 = {Text = "Dia!"},
  AvgDialog_19114_Content_1 = {
    Text = [[
22:10
Kapal Sonaniel
Lambung Kargo Ketiga]]
  },
  AvgDialog_19114_Content_2 = {
    Text = "Sepertinya mereka tidak mengejar lagi."
  },
  AvgDialog_19114_Content_3 = {
    Text = "Hu... akhirnya bisa bernapas lega."
  },
  AvgDialog_19114_Content_4 = {
    Text = "Di kapal ini tidak ada tempat yang sepenuhnya aman, jangan lengah."
  },
  AvgDialog_19115_Content_1 = {
    Text = "Guh... guh..."
  },
  AvgDialog_19115_Content_10 = {
    Text = "\"Bintang-bintang sedang terbit menuju tempat yang seharusnya\" — ini menunjukkan bahwa kamu mengetahui syarat-syarat ritual."
  },
  AvgDialog_19115_Content_11 = {
    Text = "\"Segala sesuatu telah habis, upaya terakhir dalam keputusasaan\" — menunjukkan bahwa kamu memahami situasi musuh."
  },
  AvgDialog_19115_Content_12 = {
    Text = "Upacara pemanggilan roh——situasi apa ini sebenarnya? Dan dari mana asal makhluk ikan-ikan ini?"
  },
  AvgDialog_19115_Content_13 = {
    Text = "Kamu meniru gaya Ramona, satu per satu menunjuk informasi yang tersembunyi dalam ucapan dan tindakan Tulu."
  },
  AvgDialog_19115_Content_14 = {
    Text = "...Begitu ya."
  },
  AvgDialog_19115_Content_15 = {
    Text = [[
Tidak menyadari keanehanmu adalah kelalaian Yu. 
Terlibat dalam Acara seperti ini dalam wujud manusia, tampaknya memberikan pengaruh padamu.]]
  },
  AvgDialog_19115_Content_16 = {
    Text = "\"Acara seperti itu?\""
  },
  AvgDialog_19115_Content_17 = {
    Text = "Ada orang datang."
  },
  AvgDialog_19115_Content_18 = {
    Text = "Begitu Tulu selesai berbicara, getaran halus terasa di bawah kaki, dan sebuah sosok dengan cepat menyeruak dari ujung dek lainnya, mendekatimu."
  },
  AvgDialog_19115_Content_19 = {
    Text = "Wa——tolong——"
  },
  AvgDialog_19115_Content_2 = {
    Text = [[
Musuh-musuh dengan tubuh mirip manusia, namun memiliki ciri-ciri kehidupan air, mengeluarkan suara merintih yang aneh. 
 Suaranya tidak beraturan dan menusuk telinga, namun entah bagaimana kamu bisa memahami maksud mereka.]]
  },
  AvgDialog_19115_Content_20 = {
    Text = "Mereka akan segera mengejar kita!!!"
  },
  AvgDialog_19115_Content_21 = {Text = "Hati-hati!"},
  AvgDialog_19115_Content_22 = {
    Text = "Gadis itu terengah-engah berlari ke arahmu, dan yang mengikuti di belakangnya melewati dek tanpa diragukan lagi adalah lebih banyak musuh."
  },
  AvgDialog_19115_Content_3 = {
    Text = "Mereka berkata... \"Kembalikan kepada kami\"?"
  },
  AvgDialog_19115_Content_4 = {
    Text = "Apa yang harus kukembalikan kepada mereka? Aku tidak punya apa-apa di tanganku —"
  },
  AvgDialog_19115_Content_5 = {
    Text = "Bahkan bros pun lenyap tanpa jejak."
  },
  AvgDialog_19115_Content_6 = {
    Text = "Bertaruh semua, hanya perjuangan terakhir yang putus asa. Tidak perlu memedulikan apa yang mereka katakan."
  },
  AvgDialog_19115_Content_7 = {
    Text = "Tentakel, di bawah kendali Tulu, menyapu musuh terakhir keluar dari lambung kapal. Suara tubuh jatuh ke air terdengar, menandakan berakhirnya pertempuran untuk sementara."
  },
  AvgDialog_19115_Content_8 = {
    Text = "Baiklah, sekarang tidak ada yang mengganggu. Sekarang bisa menjelaskan dengan jelas, kan?"
  },
  AvgDialog_19115_Content_9 = {
    Text = "Apa yang harus dijelaskan dengan jelas?"
  },
  AvgDialog_19116_Content_1 = {
    Text = "Obat khusus"
  },
  AvgDialog_19116_Content_10 = {
    Text = "Ujung jari kaki yang terasa nyeri membawamu kembali ke dunia nyata. Kau melihat gadis di sisimu dan lingkaran pengepungan yang terus menyusut, lalu dengan teguh bersiap untuk pertempuran."
  },
  AvgDialog_19116_Content_11 = {
    Text = "Tulu, bersiap untuk pertempuran!"
  },
  AvgDialog_19116_Content_13 = {Text = "…Tulu?"},
  AvgDialog_19116_Content_14 = {
    Text = "Pada saat yang genting ini, kenapa tiba-tiba orangnya menghilang… Baiklah, sepertinya kita harus mengandalkan diri kita sendiri."
  },
  AvgDialog_19116_Content_2 = {
    Text = "Hah, hah……"
  },
  AvgDialog_19116_Content_3 = {
    Text = "Untung... untung aku menemukanmu..."
  },
  AvgDialog_19116_Content_4 = {
    Text = "Gadis itu berlari ke arahmu, menarik ujung jubahmu seperti orang yang memegang erat jerami penyelamat, berbicara dengan napas tersengal-sengal."
  },
  AvgDialog_19116_Content_5 = {
    Text = "Musuh tidak memberi kalian banyak ruang untuk bernapas. Mereka mengangkat senjata mereka, meraung, dan menyerbu ke arah kalian."
  },
  AvgDialog_19116_Content_6 = {
    Text = "Ibu@2——！@1Ibu！@2！"
  },
  AvgDialog_19116_Content_7 = {
    Text = "Dengungan yang kacau menjadi semakin jelas di telingamu. \n Hampir, hampir saja kamu bisa memahami apa yang mereka inginkan——"
  },
  AvgDialog_19116_Content_8 = {
    Text = "Saat kamu terpaku karena hal itu, gadis itu tiba-tiba menginjak sepatumu dengan keras."
  },
  AvgDialog_19116_Content_9 = {
    Text = "Apa kau hanya akan melihat saja! Lakukan sesuatu!"
  },
  AvgDialog_19117_Content_1 = {
    Text = "Keduanya berjalan bersama menuju Ruang Kekuatan. Ketika cukup dekat dengan Ruang Kekuatan, suara bising terdengar dari balik pintu kabin."
  },
  AvgDialog_19117_Content_2 = {
    Text = "Ada yang sedang dalam pertempuran!"
  },
  AvgDialog_19117_Content_3 = {
    Text = "Jangan gegabah."
  },
  AvgDialog_19118_Content_1 = {
    Text = "Sebelum suara itu hilang, pintu kabin terbuka dari dalam ke luar, dan aliran cahaya memukul beberapa pelaut keluar dari ruang kekuatan."
  },
  AvgDialog_19118_Content_10 = {
    Text = [[
Mereka dikelilingi oleh para pelaut, kita harus mencari cara untuk membantu mereka keluar dari kesulitan. 
 Ada pintu belakang di Ruang Kekuatan, kita bisa mengitari dari sana.]]
  },
  AvgDialog_19118_Content_2 = {
    Text = "Di bagian paling dalam Ruang Kekuatan, dua orang yang dikepung juga melihat ke arah pintu — bayangan putih di antara mereka bertemu pandang dengan Ramona."
  },
  AvgDialog_19118_Content_3 = {
    Text = [[
Murni, luhur, melampaui, rapuh, tak terhitung kata sifat melintas di benak Ramona. 
Segera setelah itu, sebuah pemahaman yang luar biasa muncul dari dalam dirinya.]]
  },
  AvgDialog_19118_Content_4 = {
    Text = "Dia juga..."
  },
  AvgDialog_19118_Content_5 = {
    Text = "...manusia."
  },
  AvgDialog_19118_Content_6 = {
    Text = "Melindungi..."
  },
  AvgDialog_19118_Content_7 = {
    Text = "Cahaya mengalir tanpa suara, berdiri di depan Ramona dan menghalanginya dari memasuki Ruang Kekuatan."
  },
  AvgDialog_19118_Content_8 = {
    Text = "Cahaya ini… sama seperti tirai cahaya yang membentuk batas Domain!"
  },
  AvgDialog_19118_Content_9 = {
    Text = "Sepertinya, dia adalah pemilik Domain ini."
  },
  AvgDialog_19119_Content_10 = {
    Text = "Dia menendang beberapa papan kayu, dan sebuah pintu di geladak pun terbuka dengan jelas."
  },
  AvgDialog_19119_Content_2 = {Text = "Ugh!"},
  AvgDialog_19119_Content_3 = {
    Text = "Mereka masih punya bala bantuan, aku tidak bisa bertahan lebih lama lagi."
  },
  AvgDialog_19119_Content_4 = {
    Text = "Turun ke kabin! Seharusnya tidak banyak <Blue:Pelaut> berkumpul di bawah dek."
  },
  AvgDialog_19119_Content_5 = {
    Text = "Kamu memandang sekeliling dek, dan pandanganmu menangkap sebuah pintu gerbang yang mengarah ke bawah."
  },
  AvgDialog_19119_Content_6 = {
    Text = "Belum lagi ada gembok di pintu — kita tidak bisa melewati mereka untuk mencapai pintu."
  },
  AvgDialog_19119_Content_7 = {
    Text = "Musuh yang mengejar dari ujung dek lainnya mengamuk, menggunakan senjata dingin dan caro untuk membangun penghalang yang tidak dapat kau tembus."
  },
  AvgDialog_19119_Content_8 = {
    Text = "Jangan pergi ke sana."
  },
  AvgDialog_19119_Content_9 = {
    Text = "Gadis itu melangkah beberapa langkah ke belakang sendirian, kamu segera melindunginya dan mengikuti dari belakang."
  },
  AvgDialog_19120_Content_1 = {
    Text = "Selama kita terpisah, apa saja yang kamu temui? Ternyata kamu langsung bertemu dengan pemimpin musuh."
  },
  AvgDialog_19120_Content_10 = {
    Text = "Orang yang menapaki semua lautan?"
  },
  AvgDialog_19120_Content_11 = {
    Text = "Gelar ini sungguh..."
  },
  AvgDialog_19120_Content_12 = {
    Text = [[
Aku dan Tulu bekerja sama, menghadapinya hanya sedikit lebih unggul. 
Mungkin dia benar-benar memiliki kekuatan seperti itu.]]
  },
  AvgDialog_19120_Content_13 = {
    Text = [[
Ngomong-ngomong, kenapa Tulu ada di kapal? 
Pembangun tanpa tautan sangat mudah jatuh ke dalam delirium setelah meninggalkan kampus.]]
  },
  AvgDialog_19120_Content_14 = {
    Text = "Hanya dengan kita, sepertinya tidak ada cara untuk menekan Tulu yang lepas kendali."
  },
  AvgDialog_19120_Content_15 = {
    Text = "Saat ini, Tulu tampak sangat stabil, namun tidak diketahui berapa lama lagi kestabilan ini dapat bertahan."
  },
  AvgDialog_19120_Content_16 = {
    Text = "Tampaknya Tulu itu cukup hebat, kan? Kalau begitu, abaikan saja dia!"
  },
  AvgDialog_19120_Content_17 = {
    Text = "<BigShake:Mereka akan menyusul, ya!>"
  },
  AvgDialog_19120_Content_2 = {
    Text = "Ini adalah cerita yang panjang, Tulu, musuh misterius, kapten manusia, dan Pembangun…"
  },
  AvgDialog_19120_Content_3 = {
    Text = "Ngomong-ngomong, pemimpin Pelaut yang bergerak di kapal bukan hanya Miryam saja."
  },
  AvgDialog_19120_Content_4 = {Text = "……!"},
  AvgDialog_19120_Content_5 = {
    Text = "Saat bertindak bersama Tulu, kami sempat berhadapan dengan seorang Pembangun pria yang menyebut dirinya <Blue:Penakluk Segala Lautan>."
  },
  AvgDialog_19120_Content_6 = {
    Text = [[
Sikapnya terhadap kita... terutama terhadap Tulu, sangat membingungkan. 
Meskipun berada di kubu Pelaut yang sama, dia tampaknya tidak peduli apakah <Blue:ritual> berjalan lancar atau tidak.]]
  },
  AvgDialog_19120_Content_7 = {Text = "Upacara?"},
  AvgDialog_19120_Content_8 = {
    Text = "Apakah ini tujuan para Pelaut? Untuk mengadakan ritual pagan di atas kapal?"
  },
  AvgDialog_19120_Content_9 = {
    Text = "Saat ini masih belum diketahui, tapi saya pikir Tulu mungkin mengetahui seluk-beluk di baliknya."
  },
  AvgDialog_19121_Content_1 = {
    Text = "Pengepungan dari Sepuluh Arah"
  },
  AvgDialog_19121_Content_10 = {
    Text = "Penyelidik Draplur diperkirakan akan tiba di Dermaga Ketiga dalam waktu setengah jam."
  },
  AvgDialog_19121_Content_11 = {
    Text = "Setengah jam terlalu lama. Terlalu banyak musuh di sisi selatan jalan, kami akan mencoba menembus dari sisi utara."
  },
  AvgDialog_19121_Content_12 = {
    Text = "Sopir telah diberitahu untuk menjemput di sisi utara Pintu Keluar Dermaga Tiga."
  },
  AvgDialog_19121_Content_13 = {
    Text = "Musuh tidak dikenal? Apakah <Yellow:Gereja penerang kuil> dan mereka yang terkait?"
  },
  AvgDialog_19121_Content_14 = {
    Text = "Apakah akan mencatat intelijen musuh baru?"
  },
  AvgDialog_19121_Content_15 = {
    Text = "Tolong, Erica, bukan sekarang."
  },
  AvgDialog_19121_Content_16 = {
    Text = "Adalah makhluk mirip manusia yang belum pernah tercatat keberadaannya. Setelah kembali, saya akan menyerahkan laporan."
  },
  AvgDialog_19121_Content_17 = {
    Text = "Penjaga, lindungi dirimu dengan baik dan bersiaplah untuk terobosan."
  },
  AvgDialog_19121_Content_2 = {
    Text = [[
21:00
Kota Pelabuhan - Brilport
Deretan Dermaga Ketiga]]
  },
  AvgDialog_19121_Content_3 = {
    Text = "<Shake:——Hati-hati di belakangmu!>"
  },
  AvgDialog_19121_Content_4 = {
    Text = [[
Mendeteksi gelombang suara frekuensi tinggi tanpa peringatan, sambungan komunikasi otomatis terhubung. 
Sekali lagi, selamat malam, Penjaga, Ramona.]]
  },
  AvgDialog_19121_Content_5 = {
    Text = "Tampaknya ada yang sudah ketakutan sampai kehilangan nyali."
  },
  AvgDialog_19121_Content_6 = {
    Text = "Harap jangan mengganggu petugas lapangan dengan gangguan bahasa yang tidak perlu."
  },
  AvgDialog_19121_Content_7 = {
    Text = [[
Baiklah, baiklah.
Lalu, apakah kalian membutuhkan bantuan?]]
  },
  AvgDialog_19121_Content_8 = {
    Text = "Kami membutuhkan bala bantuan!"
  },
  AvgDialog_19121_Content_9 = {
    Text = "Kami berada di <Blue:Brilport> di <Blue:Deramaga Ketiga>, dan terlibat dalam pertempuran dengan musuh yang tidak dikenal."
  },
  AvgDialog_19122_Content_1 = {
    Text = "Wajah-wajah buruk itu, hanya dengan menatapnya saja sudah membuat seseorang merasa seolah-olah menghina teori evolusi."
  },
  AvgDialog_19122_Content_2 = {
    Text = "Mereka saling mendorong, senjata dingin di tangan mereka beradu dan menghasilkan suara yang menusuk telinga. Di tengah kekacauan itu, sepertinya mereka sedang mengelilingi sesuatu…"
  },
  AvgDialog_19123_Content_1 = {
    Text = "Tidak ada jalan keluar"
  },
  AvgDialog_19123_Content_10 = {
    Text = "Di dermaga, musuh yang menyerang dan memaksa kalian naik tangga lambung kapal dikelilingi di bawah tangga itu. Sepasang mata ikan tanpa jiwa menatap tajam ke arah kalian."
  },
  AvgDialog_19123_Content_11 = {
    Text = "Mereka tidak mengikuti tangga kapal..."
  },
  AvgDialog_19123_Content_12 = {
    Text = "Ramona menurunkan suaranya dan berbicara dengan bisikan."
  },
  AvgDialog_19123_Content_13 = {
    Text = "Kami dijadikan tikus percobaan. Begitu kami naik ke dek, kemungkinan besar mereka akan kehilangan nilai guna dari kami."
  },
  AvgDialog_19123_Content_14 = {
    Text = "Jadi... aku punya sebuah ide."
  },
  AvgDialog_19123_Content_15 = {
    Text = "Kalian melangkah ke anak tangga terakhir dari tangga kapal."
  },
  AvgDialog_19123_Content_16 = {
    Text = "Ramona, ada yang tidak beres! Tunggu sebentar!"
  },
  AvgDialog_19123_Content_17 = {
    Text = "Tangga kapal bergetar hebat, musuh tidak memberi kalian kesempatan untuk bernapas. Mereka tidak lagi mengamati dari kejauhan, melainkan memanjat menggunakan tangan dan kaki mereka."
  },
  AvgDialog_19123_Content_18 = {
    Text = "Klang——!"
  },
  AvgDialog_19123_Content_19 = {
    Text = "Serangan pedang maksimal Ramona menghancurkan kait pengunci, tangga kapal pun jatuh, namun tidak mengeluarkan suara sedikit pun seperti benda berat yang menyentuh tanah."
  },
  AvgDialog_19123_Content_2 = {
    Text = [[
21:10
Kota Pelabuhan - Brilport
Derma III]]
  },
  AvgDialog_19123_Content_20 = {
    Text = "Setidaknya mereka tidak bisa lagi naik ke kapal melalui tangga ini."
  },
  AvgDialog_19123_Content_21 = {
    Text = "Tunggu, ini..."
  },
  AvgDialog_19123_Content_22 = {
    Text = "Seperti burung yang dicium oleh langit, mata kalian dielus oleh angin lembut dan hangat, dunia yang kalian lihat berubah sepenuhnya."
  },
  AvgDialog_19123_Content_23 = {
    Text = "Bulan purnama yang besar menghilang di langit, cahaya seperti aurora mengaduk ruang yang menyelimuti lambung kapal, dan bintik-bintik cahaya yang jatuh di dek juga memancarkan warna yang aneh."
  },
  AvgDialog_19123_Content_24 = {
    Text = "Visi aneh menghantam pikiran kalian, dan setelah beberapa saat kalian akhirnya mendapatkan kembali kemampuan untuk berbicara."
  },
  AvgDialog_19123_Content_25 = {Text = "Menarik..."},
  AvgDialog_19123_Content_26 = {
    Text = "Ramona, apa pendapatmu?"
  },
  AvgDialog_19123_Content_27 = {
    Text = "Menarik, sangat menarik. Tidak ada suara saat tangga itu jatuh — ini berarti kita mungkin berada di ruang yang terpisah."
  },
  AvgDialog_19123_Content_28 = {
    Text = "Ini adalah <Yellow:Domain> yang terlihat dengan mata telanjang!"
  },
  AvgDialog_19123_Content_29 = {
    Text = "Kabut pelindung sekolah didorong oleh <Yellow:Teknologi chip perak>, entah kekuatan macam apa yang akan menguasai kapal ini?"
  },
  AvgDialog_19123_Content_3 = {
    Text = "Bau karat besi yang menyengat langsung menusuk hidung. Setiap langkah membuat tangga kapal mengeluarkan erangan seakan-akan akan roboh."
  },
  AvgDialog_19123_Content_30 = {
    Text = "Apakah ini akan menjadi Pembangun?"
  },
  AvgDialog_19123_Content_31 = {
    Text = "Tidak ada catatan serupa dalam arsip, tetapi secara teori, Pembangun menciptakan ruang independen adalah mungkin — apakah kamu ingin mendengar teori spesifiknya?"
  },
  AvgDialog_19123_Content_32 = {
    Text = "Lepaskan aku..."
  },
  AvgDialog_19123_Content_33 = {
    Text = "Lihat situasinya dulu!"
  },
  AvgDialog_19123_Content_34 = {
    Text = "Maaf, maaf, tolong maafkan rasa penasaranku."
  },
  AvgDialog_19123_Content_35 = {
    Text = "Boneka, apakah kalian mendengarnya?"
  },
  AvgDialog_19123_Content_36 = {
    Text = "Ramona mengetuk bros di dadanya, permukaan komunikatornya tampak berkilauan seperti ada cahaya yang melintas."
  },
  AvgDialog_19123_Content_37 = {Text = "Eh…?"},
  AvgDialog_19123_Content_38 = {
    Text = [[
Ramona memiringkan tubuhnya, lalu menyentuh komunikator Anda dengan jarinya. 
 Anda mencoba berkonsentrasi seperti biasa, tetapi tidak ada hasil.]]
  },
  AvgDialog_19123_Content_39 = {
    Text = "Kekuatan roh seperti tetesan air mata yang jatuh ke lautan, kembali pada kesunyian."
  },
  AvgDialog_19123_Content_4 = {
    Text = "Kurang pemeliharaan dan perbaikan, tetapi selain tampak tua, kondisi badan kapal secara keseluruhan relatif utuh."
  },
  AvgDialog_19123_Content_40 = {
    Text = "Komunikator saya juga kehilangan tautan."
  },
  AvgDialog_19123_Content_41 = {
    Text = "Secara eksternal, komunikator tampak tidak rusak, namun tidak bisa mengirim pesan."
  },
  AvgDialog_19123_Content_42 = {
    Text = "<Small: Bagaimana bisa ada begitu banyak hal yang dapat memutus komunikasi, terakhir di Museum Lilin juga …>"
  },
  AvgDialog_19123_Content_43 = {
    Text = "Teknologi yang dihasilkan oleh Perak bukanlah segalanya. Lagipula, penelitian kita tentang Perak itu sendiri masih sangat dangkal."
  },
  AvgDialog_19123_Content_44 = {
    Text = "... kalau tidak, kita turun dari kapal saja, ya?"
  },
  AvgDialog_19123_Content_45 = {
    Text = "Coba lihat-lihat di sekitar dek, siapa tahu bisa menemukan cara lain untuk turun dari kapal."
  },
  AvgDialog_19123_Content_46 = {
    Text = "Berhati-hatilah terhadap lingkungan sekitar, dan berdoa agar kapal ini tidak berlayar."
  },
  AvgDialog_19123_Content_47 = {
    Text = "<Big:Uuuuuuh——>"
  },
  AvgDialog_19123_Content_48 = {
    Text = "Seperti burung gereja yang merespons kembang suara penyanyi opera, peluit panjang itu membalas doa Ramona."
  },
  AvgDialog_19123_Content_5 = {
    Text = "Jejak erosi air laut tidak terlalu jelas, di bawah garis muka air juga tidak ada kerang tempel, tiram…"
  },
  AvgDialog_19123_Content_51 = {
    Text = "Aku tahu apa yang ingin kau katakan, tapi tolong, bukan sekarang."
  },
  AvgDialog_19123_Content_52 = {
    Text = "Kita tidak bisa mengikuti kapal Sonaniel ke laut, ada terlalu banyak kejanggalan pada kapal ini."
  },
  AvgDialog_19123_Content_53 = {
    Text = "Pergi ke ujung dek lainnya. Kapal besar seharusnya dilengkapi dengan sekoci penyelamat, mungkin kita bisa menurunkan sekoci dan mengevakuasi melalui laut."
  },
  AvgDialog_19123_Content_54 = {
    Text = "Tunggu… sepertinya ada suara."
  },
  AvgDialog_19123_Content_56 = {
    Text = "Wajah yang menyerupai ikan muncul di dek, pelaku yang memaksa kalian naik ke kapal terus mendesak maju."
  },
  AvgDialog_19123_Content_6 = {
    Text = "Apa yang kamu temukan?"
  },
  AvgDialog_19123_Content_7 = {
    Text = "Sonanier tidak memiliki ciri-ciri khas kapal hantu yang tenggelam, dan tidak sesuai dengan catatan bahwa kapal itu pernah tenggelam dalam badai."
  },
  AvgDialog_19123_Content_8 = {
    Text = "Jika ada kesempatan, saya ingin melakukan Penyelidikan mendalam tentang asal-usul kapal ini…"
  },
  AvgDialog_19123_Content_9 = {
    Text = "Tapi sekarang jelas bukan saat yang tepat."
  },
  AvgDialog_19124_Content_1 = {
    Text = "Aah… kenapa… kenapa!"
  },
  AvgDialog_19124_Content_2 = {
    Text = "Miryam tampak agak aneh."
  },
  AvgDialog_19124_Content_3 = {
    Text = "Bukankah itu kebetulan? Ayo selamatkan <Yellow:%player%> sekarang juga."
  },
  AvgDialog_19125_Content_1 = {
    Text = "Seiring dengan gejolak dalam pikiran Miryam, kelompok Pelaut juga menjadi tidak stabil. Kekacauan dan ketidakteraturan mulai menyebar secara diam-diam."
  },
  AvgDialog_19125_Content_2 = {
    Text = "Ekor ular menghantam dinding kabin secara liar, resonansi baja berdengung."
  },
  AvgDialog_19125_Content_3 = {
    Text = "Debu yang telah menumpuk lama juga terangkat, menciptakan hujan salju hitam berderak di bawah Ruang Kekuatan."
  },
  AvgDialog_19126_Content_1 = {
    Text = "Mengejar bintang-bintang"
  },
  AvgDialog_19126_Content_10 = {
    Text = [[
Apa pun yang kau pikir terjadi, semuanya adalah keputusanku. Akulah tuan dari kapal ini. 
Celeste hampir tidak memiliki kesadaran diri, apalagi mengubahku?]]
  },
  AvgDialog_19126_Content_11 = {Text = "Benarkah?"},
  AvgDialog_19126_Content_12 = {
    Text = "Aku bisa membuatmu membangunkannya, dan aku juga bisa membuatnya kembali menjadi segenggam pasir perak."
  },
  AvgDialog_19126_Content_13 = {Text = "Kamu!"},
  AvgDialog_19126_Content_14 = {Text = "Sekarang!"},
  AvgDialog_19126_Content_15 = {Text = "Dor——!"},
  AvgDialog_19126_Content_16 = {Text = "Ugh!"},
  AvgDialog_19126_Content_17 = {
    Text = "Serangan menghantam dengan kuat perisai yang dikeluarkan Ramona, aliran cahaya hanya berlangsung selama setengah detik sebelum perisai itu hancur berkeping-keping."
  },
  AvgDialog_19126_Content_18 = {Text = "Siswi?!"},
  AvgDialog_19126_Content_19 = {Text = "Ramona!"},
  AvgDialog_19126_Content_2 = {
    Text = [[
22:35
Sonanier
Ruang Kekuatan]]
  },
  AvgDialog_19126_Content_20 = {
    Text = "Aku baik-baik saja, jangan mendekat!"
  },
  AvgDialog_19126_Content_21 = {
    Text = [[
Dalam keadaan harus melindungi orang lain, aku bukan tandingannya wanita ini.
Aku akan berusaha menahan serangannya, kau bawa mereka pergi dulu.]]
  },
  AvgDialog_19126_Content_22 = {
    Text = "Kamu akan datang dan bertemu denganku, kan?"
  },
  AvgDialog_19126_Content_23 = {
    Text = "Apa yang kamu khawatirkan?"
  },
  AvgDialog_19126_Content_24 = {
    Text = "Ramona mengayunkan pedangnya untuk membubarkan bayangan ular yang menyerang, lalu tersenyum padamu sejenak."
  },
  AvgDialog_19126_Content_26 = {
    Text = "Kapten, cepat!"
  },
  AvgDialog_19126_Content_27 = {
    Text = "——Seperti dikejar oleh binatang buas dan banjir, kalian berlari seolah-olah mempertaruhkan nyawa menuju ruang luar."
  },
  AvgDialog_19126_Content_3 = {
    Text = "Terharu karena kita berdua adalah orang-orang yang terombang-ambing dan kehilangan arah, aku akan menyerahkan metode untuk memanggil mereka yang telah tiada kepadamu."
  },
  AvgDialog_19126_Content_4 = {
    Text = "Kehadirannya melambangkan bahwa keinginanmu telah terpenuhi, sepertinya kamu sudah mendapatkan cukup penghiburan dari kerabat yang telah meninggal…"
  },
  AvgDialog_19126_Content_5 = {
    Text = [[
Dan harapanku, harapan besar yang diberikan Dewa kepadaku, adalah <Blue:anak itu>. 
Kembalikan padaku Sang Perawan Suci... tidak, kembalikan Ibu Dewa kepadaku.]]
  },
  AvgDialog_19126_Content_6 = {
    Text = "Dengan berkah suci-Ku, ketika dia dilahirkan kembali dalam rahim seorang perawan suci, saat kerajaan dewa kembali… engkau juga akan melangkah ke Ranah dewa, menemukan kedamaian abadi."
  },
  AvgDialog_19126_Content_7 = {
    Text = "Yang Terhormat, saya juga terkejut mendengar berita tentang hilangnya Sang Ibu Dewa. Namun, seperti yang sudah saya katakan, Sang Ibu Dewa tidak berada di kapal."
  },
  AvgDialog_19126_Content_8 = {
    Text = "Mengapa harus bersikap berlebihan, pura-pura menjadi orang bodoh?"
  },
  AvgDialog_19126_Content_9 = {
    Text = "Aku dulu sangat mengagumi kecerdasan dan ketekunanmu. Apa yang mengubah kesetiaanmu padaku? Apakah karena <Yellow:Golem> ini? Begitu lemah dan rapuh…"
  },
  AvgDialog_19127_Content_1 = {
    Text = "Orang yang melangkah ke lautan"
  },
  AvgDialog_19127_Content_10 = {
    Text = "Aku tidak berharap kamu akan turun tangan membantu."
  },
  AvgDialog_19127_Content_11 = {
    Text = "Namun, jika memang seperti yang kamu katakan, segalanya \"karena kamu,\" aku harap setidaknya aku tidak mendengar komentar sinis dari pelaku utamanya."
  },
  AvgDialog_19127_Content_12 = {
    Text = "Penjaga Rahasia…"
  },
  AvgDialog_19127_Content_13 = {
    Text = "Makhluk-makhluk itu menyerang dari sisi selatan dek. Penjaga tidak mungkin langsung menerjang ke dalam kepungan musuh. {Male=dia,Female=dia} tidak sebodoh itu."
  },
  AvgDialog_19127_Content_14 = {
    Text = "Deck utara tempat kami berada pasti memiliki pintu masuk ruangan yang tidak disadari keberadaannya."
  },
  AvgDialog_19127_Content_15 = {Text = "Kau……"},
  AvgDialog_19127_Content_16 = {
    Text = "Apa ada yang lain, apakah ada penemuan baru?"
  },
  AvgDialog_19127_Content_17 = {
    Text = "Yu bertanya, bagaimana menurutmu tentang \"monster-monster itu\"?"
  },
  AvgDialog_19127_Content_18 = {
    Text = "Di antara jari-jari terdapat selaput, bagian di atas tulang ekor sepenuhnya berubah menjadi seperti ikan, namun tetap memiliki sebagian kecerdasan."
  },
  AvgDialog_19127_Content_19 = {
    Text = "Bentuk mereka mengalir secara alami, tidak seperti karya Para pematung, yang selalu membuat eksperimen mereka menjadi kacau."
  },
  AvgDialog_19127_Content_2 = {
    Text = [[
21:30
Kapal Sonanier
Geladak]]
  },
  AvgDialog_19127_Content_20 = {
    Text = "Saya awalnya mengira bahwa penampilan mereka adalah hasil mutasi setelah terpengaruh oleh <Yellow:Clades>, tetapi dalam beberapa pertempuran ini, saya tidak menemukan adanya <Yellow:D-marka> yang jelas pada tubuh mereka."
  },
  AvgDialog_19127_Content_21 = {
    Text = "Mereka... lebih mirip lelucon bodoh yang diajukan oleh teori evolusi kepada manusia."
  },
  AvgDialog_19127_Content_22 = {
    Text = "\"Sebuah lelucon bodoh untuk manusia,\" Yu menghargai metafora Anda."
  },
  AvgDialog_19127_Content_23 = {
    Text = [[
Terima kasih, namun ini tidak membuatku mengurangi kewaspadaanku terhadapmu. 
 Terutama setelah kau sembarangan berkomentar tentang hubunganku dengan Penjaga.]]
  },
  AvgDialog_19127_Content_24 = {
    Text = "Yu tidak akan menyerang kalian."
  },
  AvgDialog_19127_Content_25 = {
    Text = "Benarkah? Lalu, mengapa kamu tidak mau mengungkapkan alasan sebenarnya di balik kepergianmu dari sekolah tanpa izin? Apakah itu sesuatu yang sulit untuk diucapkan?"
  },
  AvgDialog_19127_Content_26 = {
    Text = "Yu tidak punya kewajiban untuk menjelaskan kepada kalian, tetapi jika diperlukan, Yu akan memberikan bantuan."
  },
  AvgDialog_19127_Content_27 = {
    Text = "Saya dan Penjaga berharap untuk melakukan penyelidikan terkait Gereja Penerang Kuil, dan berharap bisa keluar dari kapal ini dengan selamat."
  },
  AvgDialog_19127_Content_28 = {
    Text = "Saya tidak berpikir ada konflik kepentingan di antara kita. Kalau tidak, saya tidak akan punya kesempatan untuk berbicara panjang lebar denganmu di sini. Bersikap jujur hanya akan menguntungkan kedua belah pihak."
  },
  AvgDialog_19127_Content_29 = {
    Text = "Urusan Yu tidak ada hubungannya dengan kalian."
  },
  AvgDialog_19127_Content_3 = {
    Text = "Ramona berpegangan pada tepi kapal, setengah tubuhnya menjulur keluar dari kapal."
  },
  AvgDialog_19127_Content_30 = {
    Text = "Lihat, sikap seperti inilah yang membuat orang tidak bisa mempercayaimu."
  },
  AvgDialog_19127_Content_31 = {
    Text = "Kemarahan yang kamu tunjukkan membuatmu sangat mirip dengan manusia."
  },
  AvgDialog_19127_Content_32 = {
    Text = "Lebih tepatnya, sikap dingin yang kamu tunjukkan membuat orang sulit mempercayai bahwa kamu pernah hidup sebagai manusia."
  },
  AvgDialog_19127_Content_33 = {
    Text = "Berdebat antara kita berdua hanyalah membuang-buang waktu. Ayo, kembali ke dek utara."
  },
  AvgDialog_19127_Content_34 = {
    Text = "Ramona dengan tenang mengakhiri percakapan ini, melewati Pembangun remaja, lalu berbalik dan berjalan menuju arah awal dia naik kapal."
  },
  AvgDialog_19127_Content_35 = {
    Text = "Hati-hati, musuh menyerang!"
  },
  AvgDialog_19127_Content_36 = {Text = "Apa?"},
  AvgDialog_19127_Content_4 = {
    Text = "Ujung pedang tipis yang terulur tenggelam ke dalam tirai cahaya, mengaduk-aduk pusaran warna kecil yang aneh di udara yang tampaknya kosong."
  },
  AvgDialog_19127_Content_5 = {
    Text = "Setelah beberapa saat, dia baru menarik kembali pedang tipisnya dan berdiri dengan mantap di atas dek."
  },
  AvgDialog_19127_Content_6 = {
    Text = "Kapal sudah berangkat, tetapi karena adanya tirai cahaya, tidak dapat menentukan arah pelayaran melalui titik referensi."
  },
  AvgDialog_19127_Content_7 = {
    Text = "Pelabuhan induk, tujuan, pemilik kapal... semuanya tidak penting. Yang paling mendesak saat ini adalah menemukan Penjaga."
  },
  AvgDialog_19127_Content_8 = {
    Text = "Aku pikir, dengan kemampuanmu, seharusnya kau tidak perlu selalu menuruti apa yang dikatakan oleh \"Penjaga\"."
  },
  AvgDialog_19127_Content_9 = {
    Text = "Kamu tidak memerlukan tautan untuk tetap waras, dan memiliki kemampuan bertarung sendirian."
  },
  AvgDialog_19128_Content_1 = {
    Text = "<Blue:Pelaut> kebanyakan memiliki tubuh yang kurang kuat, pedang raksasa ini milik orang lain, hati-hati saat menghadapinya."
  },
  AvgDialog_19128_Content_2 = {
    Text = "Apa kamu menyebut makhluk ikan-ikan ini sebagai apa?"
  },
  AvgDialog_19128_Content_3 = {
    Text = "Mereka mendekat, berhati-hatilah."
  },
  AvgDialog_19129_Content_1 = {
    Text = "Cahaya yang Hilang"
  },
  AvgDialog_19129_Content_10 = {
    Text = "Apakah kamu tahu tentang kami?"
  },
  AvgDialog_19129_Content_11 = {
    Text = "Jika ada sesuatu yang bisa membuat <Blue:\"Lampu Sumsum\"> membenci kalian, kalian adalah salah satunya... Namun, terhadap orang cerdas, aku selalu merasa iba."
  },
  AvgDialog_19129_Content_12 = {
    Text = "Sumsum lampu, lentera... Apakah mungkin, <Blue:\"sumsum lampu\"> mengacu pada seseorang dengan posisi istimewa dalam Gereja Penerang Kuil?"
  },
  AvgDialog_19129_Content_13 = {
    Text = "Pelaut sulit berjalan di dunia, dan mereka menginginkan kekuatan kita… Hanya saling memanfaatkan, saling menghangatkan dalam kesendirian saja."
  },
  AvgDialog_19129_Content_14 = {
    Text = [[
Kamu yang menguasai kekuatan Pelaut pasti adalah mitra yang sangat dihargai. 
 Atau, apakah kamu juga salah satu dari "sumbu"?]]
  },
  AvgDialog_19129_Content_15 = {
    Text = [[
Meskipun tubuh ini adalah <Yellow:cahaya lilin yang bergoyang>, visi dan keinginan sumbu-sumbu lain sangat berbeda. 
Menyelamatkan dunia dari <Yellow:kotoran hitam> dan <Blue:kedatangan kembali Ranah dewa> bukanlah dua hal yang saling bertentangan.]]
  },
  AvgDialog_19129_Content_16 = {
    Text = [[
Orang yang cerdas tidak seharusnya terkubur dalam kehidupan duniawi. 
 Meskipun tanah para dewa dibangun atas dasar garis keturunan, ia tetap bersedia menerima darah baru dari luar.]]
  },
  AvgDialog_19129_Content_17 = {
    Text = "Bergabunglah dengan kami, ikut serta dalam kedatangan kembali dan kebangkitan Ranah Dewa, penuh kemuliaan… Dengan demikian, engkau dan aku dapat melangkah di tanah kebahagiaan sempurna."
  },
  AvgDialog_19129_Content_18 = {
    Text = "Jika yang kamu maksud dengan \"kebangkitan\" adalah menggunakan orang hidup sebagai korban dan orang tak berdosa sebagai wadah bagi monster."
  },
  AvgDialog_19129_Content_19 = {
    Text = "Maaf, aku tidak bisa melakukannya. Penjaga juga tidak akan menyetujui."
  },
  AvgDialog_19129_Content_2 = {
    Text = [[
22:55
Sonanier
Ruang Kekuatan]]
  },
  AvgDialog_19129_Content_20 = {
    Text = "<Big:Orang yang tidak sopan!> Seharusnya merasa terhormat bisa menjadi wadah sebelum Dewa dilahirkan kembali."
  },
  AvgDialog_19129_Content_21 = {
    Text = "<Gray:Bagus, berhasil membuatnya marah… Selanjutnya, arahkan dia untuk melakukan serangan! Jika serangannya bisa membuka dinding kapal, ada kesempatan untuk melarikan diri dalam kekacauan…>"
  },
  AvgDialog_19129_Content_22 = {
    Text = "Kali ini aku yang keliru menilai, tak perlu banyak bicara dengan orang bodoh…"
  },
  AvgDialog_19129_Content_23 = {
    Text = "<Gray: Sekaranglah saatnya!>"
  },
  AvgDialog_19129_Content_24 = {
    Text = "Hai? Sepertinya kalian berdua cukup dekat."
  },
  AvgDialog_19129_Content_25 = {
    Text = "Berbagai pratinjau terus berputar di benak Ramona, namun kenyataan justru mengarah pada satu kemungkinan yang sengaja ia abaikan."
  },
  AvgDialog_19129_Content_26 = {Text = "%player%!"},
  AvgDialog_19129_Content_27 = {
    Text = "Kamu diseret oleh Goliath dengan jubahmu ke dalam Ruang Kekuatan."
  },
  AvgDialog_19129_Content_28 = {
    Text = "Ra... Monna..."
  },
  AvgDialog_19129_Content_29 = {
    Text = "Tautan dengan Tulu telah sepenuhnya menguras tenagamu, dan sebelum kamu mendapatkan waktu istirahat yang menenangkan, tampaknya akan sulit bagimu untuk melawan."
  },
  AvgDialog_19129_Content_3 = {
    Text = [[
Setelah melancarkan serangan pertama, Miryam tidak lagi menyerang. 
Hanya dengan kehadiran Pelaut yang sudah terbiasa dengan rasa sakit saja, Ramona sudah cukup terjebak dalam pertarungan sengit.]]
  },
  AvgDialog_19129_Content_30 = {
    Text = "Aku juga membawa anak ini kembali, bagaimana, apakah harus menghabisinya?"
  },
  AvgDialog_19129_Content_31 = {
    Text = "Drama konyol ini harus segera berakhir."
  },
  AvgDialog_19129_Content_32 = {
    Text = "Tidak memberi kalian lebih banyak waktu untuk memahami situasi. Kekuatan meledak di dalam Bayangan, dan entitas energi yang samar-samar menggumpal menjadi ular raksasa yang besar dan kokoh."
  },
  AvgDialog_19129_Content_33 = {
    Text = "Ular raksasa menabrak sembarangan di dalam ruang, pupil ular itu akhirnya terfokus pada dirimu ——"
  },
  AvgDialog_19129_Content_34 = {Text = "Berhenti!"},
  AvgDialog_19129_Content_35 = {
    Text = "Ular raksasa melilit di pinggangmu, mengangkatmu tanpa usaha."
  },
  AvgDialog_19129_Content_36 = {
    Text = "Cukup, lepaskan murid itu."
  },
  AvgDialog_19129_Content_37 = {Text = "Siapa!"},
  AvgDialog_19129_Content_38 = {
    Text = "Suara yang sangat dikenal melintasi jurang sejarah, seperti angin lepas pantai yang ringan, namun membangkitkan gelombang besar di dalam hati."
  },
  AvgDialog_19129_Content_39 = {
    Text = "Miryam, aku berkata, \"Lepaskan siswa itu.\""
  },
  AvgDialog_19129_Content_4 = {
    Text = [[
Dia tak pernah melihat Ramona lagi, meski hanya sekilas. 
 Dia menutup mata sedikit, berdiri dengan tenang di sudut ruangan, bagaikan sebuah patung suci.]]
  },
  AvgDialog_19129_Content_40 = {
    Text = "Drama ini memang sudah seharusnya berakhir."
  },
  AvgDialog_19129_Content_41 = {
    Text = "Ah… ah…"
  },
  AvgDialog_19129_Content_42 = {
    Text = "Suara serak terdengar dari tenggorokan, seperti roda gigi yang tak mampu menahan beban, lebih mirip runtuhnya altar suci."
  },
  AvgDialog_19129_Content_43 = {
    Text = "Matanya terbuka lebar sepenuhnya, warna pada bola mata ungu gelapnya perlahan memudar, dan ekspresinya tidak lagi dingin serta angkuh seperti saat menghadapi kalian."
  },
  AvgDialog_19129_Content_44 = {
    Text = [[
Tuan... bagaimana bisa muncul di sini... 
Kenapa di tubuhmu... ada bau <Blue:Golem>...]]
  },
  AvgDialog_19129_Content_45 = {
    Text = "Sisik ular yang dingin dan licin meluncur di tubuhmu, seperti saat mencekik mangsanya. Tubuh ular raksasa itu perlahan semakin erat."
  },
  AvgDialog_19129_Content_46 = {
    Text = "<Blue:Tuhanku>…aku yang mulia <Blue:Raja>……"
  },
  AvgDialog_19129_Content_47 = {
    Text = "Kamu telah berjanji padaku... Kamu berjanji padaku..."
  },
  AvgDialog_19129_Content_48 = {
    Text = "Miryam, <BigShake:Apakah kamu akan melanggar perintah Yu!>"
  },
  AvgDialog_19129_Content_49 = {
    Text = "Tidak... aku tidak akan... Yang Mulia.... tak dapat dibantah...."
  },
  AvgDialog_19129_Content_5 = {
    Text = "<Gray:Bagi dia, nyawa saya dan Penjaga hanyalah rumput liar yang tidak berarti.>"
  },
  AvgDialog_19129_Content_50 = {
    Text = "<Gray: Ada kesempatan!>"
  },
  AvgDialog_19129_Content_6 = {
    Text = "<Gray: Mungkin aku bisa memanfaatkan ini untuk melakukan sesuatu ……>"
  },
  AvgDialog_19129_Content_7 = {Text = "Berhenti."},
  AvgDialog_19129_Content_8 = {
    Text = "Di bawah tatapan waspada dan penuh rasa ingin tahu Ramona, para Pelaut kembali ke belakang tuan mereka seperti air pasang yang surut."
  },
  AvgDialog_19129_Content_9 = {
    Text = [[
Kamu berasal dari universitas itu. 
Begitu muda... Apakah kamu masih seorang murid magang?]]
  },
  AvgDialog_19130_Content_1 = {Text = "Kru kapal"},
  AvgDialog_19130_Content_10 = {
    Text = "Gedung opera?"
  },
  AvgDialog_19130_Content_11 = {
    Text = "<Yellow:%player%>Setelah bergabung dengan Mythag, setiap kali meninggalkan sekolah adalah untuk menjalankan misi. Saya selalu ingin mencari kesempatan untuk membawanya berkeliling Londinium."
  },
  AvgDialog_19130_Content_12 = {
    Text = "Gedung opera adalah landmark terkenal yang sudah dikenal luas, dan kebetulan ada pertunjukan baru yang sedang dipentaskan. Menggunakan gedung opera sebagai titik awal wisata adalah pilihan yang masuk akal."
  },
  AvgDialog_19130_Content_13 = {
    Text = "Namun, kamu tidak berharap menjadi penonton di bawah panggung."
  },
  AvgDialog_19130_Content_14 = {
    Text = "...kadang-kadang aku merasa kamu sangat tajam hingga menakutkan, seperti raja dalam dongeng yang mampu membaca isi hati orang lain."
  },
  AvgDialog_19130_Content_16 = {
    Text = "Saya tidak sepenuhnya tidak bisa memahami keindahan seni. Sejak kecil, ayah sering membawa saya ke teater atau pameran lukisan, bahkan pernah mengundang guru untuk mengajari saya tentang apresiasi seni."
  },
  AvgDialog_19130_Content_17 = {
    Text = "Namun, semakin dewasa, semakin saya memahami segala sesuatu yang terjadi di balik layar dunia, semakin sulit bagi saya untuk menikmati seni dengan hati yang menghargai."
  },
  AvgDialog_19130_Content_18 = {
    Text = "Saya berpikir, jika kita tidak bisa menemukan asal-usul <Yellow:Fenomena-d>, semua hal indah ini akan larut ke dalam Ilusi."
  },
  AvgDialog_19130_Content_19 = {
    Text = "Teman, keluarga, dan kekasih satu per satu menghilang. Tidak peduli berapa banyak orang yang pada akhirnya bisa selamat, dunia ini akan berubah menjadi tempat mati yang sunyi, di mana tidak ada seorang pun yang akan mengenal apa itu seni."
  },
  AvgDialog_19130_Content_2 = {
    Text = [[
21:50
Kapal Sonanier
Geladak]]
  },
  AvgDialog_19130_Content_20 = {
    Text = "Di dunia ini, memang tidak ada sesuatu pun yang dapat bertahan selamanya."
  },
  AvgDialog_19130_Content_21 = {
    Text = "Mengikuti aliran air, bertindak sesuai dengan takdir... kenapa tidak?"
  },
  AvgDialog_19130_Content_22 = {Text = "...Hmm."},
  AvgDialog_19130_Content_23 = {
    Text = "Kenapa tertawa?"
  },
  AvgDialog_19130_Content_24 = {
    Text = "Karena tidak ingin \"mengikuti takdir\", bukan hanya saya seorang."
  },
  AvgDialog_19130_Content_25 = {
    Text = [[
Kamu pernah berkata bahwa segala sesuatu yang terjadi di sini "karena kamu". 
 Karena sikapmu yang tertutup, awalnya aku tidak sepenuhnya mempercayai perkataanmu,]]
  },
  AvgDialog_19130_Content_26 = {
    Text = "Tetapi setelah Goliath muncul... sekarang aku percaya, meskipun kekuatannya berasal dari alam laut dalam, namun hubungan di antara kalian pasti lebih dari itu."
  },
  AvgDialog_19130_Content_27 = {
    Text = "Lalu prajurit itu melihat ke kiri dan kanan sebelum berbicara tentang hal lain. Kamu juga baru pertama kali bertemu dengannya, mengapa kamu begitu percaya pada ucapannya?"
  },
  AvgDialog_19130_Content_28 = {
    Text = "Yang benar-benar membuatku percaya padanya adalah sikapmu."
  },
  AvgDialog_19130_Content_29 = {
    Text = "Jika kamu benar-benar menuruti takdir, tanpa sedikit pun niat untuk melawan atau memperbaikinya… maka kamu tidak akan berada di sini, bukan?"
  },
  AvgDialog_19130_Content_3 = {Text = "Hmm..."},
  AvgDialog_19130_Content_30 = {
    Text = "Kata-kata Ramona tidak memberi sedikit pun ampunan. Kata-kata yang sebenarnya tidak bersifat serangan berubah menjadi pisau tajam, menghancurkan tabir penutup seseorang tanpa ampun."
  },
  AvgDialog_19130_Content_31 = {
    Text = "Tulu menyipitkan matanya, tetap mempertahankan posisi menyandarkan kepala dengan condong. Pandangannya meluncur melewati Ramona dan mengembara ke arah laut yang memantulkan cahaya berwarna aneh."
  },
  AvgDialog_19130_Content_32 = {
    Text = "Saya tidak bisa, dan juga tidak punya cara untuk memaksa kamu mengakui di sini. Saat ini bukan waktu yang tepat untuk saling berbagi perasaan."
  },
  AvgDialog_19130_Content_33 = {
    Text = [[
Prioritas utama adalah menemukan Penjaga, lalu mencari cara untuk kembali ke daratan. 
 Cobalah periksa bagian bawah dek, mungkin saja ada petunjuk.]]
  },
  AvgDialog_19130_Content_4 = {Text = "Ngh..."},
  AvgDialog_19130_Content_5 = {
    Text = "Masih memikirkan perkataan prajurit itu?"
  },
  AvgDialog_19130_Content_6 = {
    Text = "Ramona menghela napas panjang, dengan langka menampakkan ekspresi cemas di wajahnya."
  },
  AvgDialog_19130_Content_7 = {
    Text = "Semakin rumit, tak disangka ikan-ikan ini... Pelaut, benar-benar terkait dengan Gereja Penerang Kuil."
  },
  AvgDialog_19130_Content_8 = {
    Text = "Misi kali ini seharusnya hanya <Yellow:Penyelidikan Lapangan> biasa. Setelah memverifikasi isi buku harian Francis, kita bisa segera kembali ke Londinium."
  },
  AvgDialog_19130_Content_9 = {
    Text = "Jika beruntung, kamu masih bisa menyaksikan pertunjukan perdana dari drama baru <Blue:Londinium Opera House>."
  },
  AvgDialog_19131_Content_1 = {
    Text = "Kamu diangkat terbalik oleh ular raksasa, semua darah dalam tubuh mengalir ke otak, dan pandanganmu mulai berkunang-kunang."
  },
  AvgDialog_19131_Content_10 = {
    Text = "...%player%."
  },
  AvgDialog_19131_Content_11 = {
    Text = "Apakah aku berada di surga?"
  },
  AvgDialog_19131_Content_12 = {
    Text = "Maaf, kami masih berada di Sonnelier. Dan, krisis sudah hampir tiba…"
  },
  AvgDialog_19131_Content_13 = {
    Text = "<Small:Benar-benar tak termaafkan…>"
  },
  AvgDialog_19131_Content_14 = {
    Text = "Demi @3, dengan kekuasaan sebagai Pelaksana ke-18 Lemuria, aku mengeluarkan perintah!"
  },
  AvgDialog_19131_Content_15 = {
    Text = [[
Lemuria telah tenggelam, peradaban telah terputus. 
 Imam Agung Miryam, hentikan tindakan bodohmu!]]
  },
  AvgDialog_19131_Content_16 = {
    Text = "Kegilaan...? Aku <Yellow:telah melanglang buana sendirian selama ribuan tahun>, demi kedatangan kembali Ranah dewa... Apakah ini hanya kegilaan?"
  },
  AvgDialog_19131_Content_17 = {
    Text = "Bukan yang asli... tiruan sialan..."
  },
  AvgDialog_19131_Content_18 = {
    Text = [[
Yang Mulia... Tuan-ku yang terhormat... <Red:Dewa yang sebenarnya>... Murphy... 
 Benar... aku dan Murphy masih ada.]]
  },
  AvgDialog_19131_Content_2 = {
    Text = "Namun, dalam keadaan bingung, kamu masih melihat dua gadis... Mereka dikelilingi oleh Pelaut, mengapa semakin dekat?"
  },
  AvgDialog_19131_Content_20 = {
    Text = "Sekarang… masih ada ruang untuk bernegosiasi. \nKembali ke ordo, kau tetap menjadi \"Ibu Dewa\" yang terhormat."
  },
  AvgDialog_19131_Content_21 = {
    Text = "Pemakamanmu akan menjadi perayaan pengorbanan terbesar dalam sejarah Ranah Dewa, dihormati oleh puluhan ribu orang… Nama mu juga akan tercatat dalam sejarah, dikenang selama-lamanya."
  },
  AvgDialog_19131_Content_22 = {
    Text = "Kembali padaku, kita bersama-sama... bersama-sama menjatuhkan hukuman pada <Blue:orang yang tidak hormat ini>."
  },
  AvgDialog_19131_Content_23 = {
    Text = "Eksekusi… orang kotor yang menyamar sebagai Tuan!"
  },
  AvgDialog_19131_Content_24 = {
    Text = "Ular raksasa menghilang lalu terkumpul kembali. Di bawah dampak Kekuatan Miryam, ruang secara bertahap menjadi terdistorsi dan berubah."
  },
  AvgDialog_19131_Content_25 = {
    Text = "Miryam! Aku memerintahkanmu untuk berhenti!"
  },
  AvgDialog_19131_Content_26 = {
    Text = "Palsu, tiruan, penipu, orang yang tidak hormat… Tidak ada @1 @2 yang diizinkan menggunakan bentuk @3 @4!"
  },
  AvgDialog_19131_Content_27 = {
    Text = [[
Pada suatu saat, bayangan semu yang menutupi Ruang Kekuatan mengental menjadi entitas fisik. 
Bangunan dengan bentuk yang sulit digambarkan menjulang tinggi.]]
  },
  AvgDialog_19131_Content_28 = {
    Text = "<Change>Orang yang tidak hormat... orang yang tidak hormat... tidak hormat, tidak terkendali▼▼▼▼▼▼▼▼!"
  },
  AvgDialog_19131_Content_29 = {
    Text = "Suara kasar yang tidak beraturan keluar dari mulutnya. Miryam mencengkeram lehernya dengan kedua tangan, tubuhnya berubah bentuk dan memanjang."
  },
  AvgDialog_19131_Content_3 = {
    Text = "Ramona! Sekarang!"
  },
  AvgDialog_19131_Content_30 = {
    Text = "Hati-hati! Dia akan kehilangan kendali!"
  },
  AvgDialog_19131_Content_4 = {
    Text = "Ramona menarik napas dalam-dalam, sedikit menekuk satu kakinya, dan melompat tinggi-tinggi berkat energi yang terkumpul di bawah kakinya ——"
  },
  AvgDialog_19131_Content_6 = {
    Text = "Ujung pedang tipis menembus tubuh energi berbentuk sisik ular, menusuk bagian vital ular raksasa."
  },
  AvgDialog_19131_Content_7 = {
    Text = "Eh eh! Orang akan jatuh!"
  },
  AvgDialog_19131_Content_8 = {
    Text = "Kamu juga jatuh dalam teriakan dahsyat Ular Raksasa."
  },
  AvgDialog_19131_Content_9 = {
    Text = "—— lalu jatuh ke dalam pelukan hangat yang gemetar."
  },
  AvgDialog_19132_Content_2 = {
    Text = "Sial, orang-orang ini benar-benar tak kunjung pergi…"
  },
  AvgDialog_19132_Content_3 = {
    Text = "Meskipun tidak ada yang memberi mereka perintah lagi, para Pelaut hanya dengan jumlah mereka saja telah membangun tembok tinggi di antara Miryam dan Ramona."
  },
  AvgDialog_19132_Content_4 = {
    Text = "Tanpa instruksi dari Penjaga, otak harus melakukan perhitungan strategis dan menggerakkan otot secara bersamaan… Berapa lama lagi bisa bertahan?"
  },
  AvgDialog_19132_Content_5 = {
    Text = "<Big:Minggir semua!>"
  },
  AvgDialog_19132_Content_6 = {Text = "Murphy!?"},
  AvgDialog_19132_Content_7 = {
    Text = "Para Pelaut mengenali Murphy yang \"mengandung\" Dewa, hampir secara naluriah mereka mundur saat dia mendekat. Dia pun berlari kecil melewati kepungan monster."
  },
  AvgDialog_19132_Content_8 = {
    Text = "Jangan berisik. Mau mendekati wanita itu, kan? Ikuti aku dari belakang, biar aku yang membuka jalan."
  },
  AvgDialog_19133_Content_1 = {Text = "Murid"},
  AvgDialog_19133_Content_10 = {
    Text = "...Baiklah, silakan memimpin jalan."
  },
  AvgDialog_19133_Content_2 = {
    Text = [[
22:00
Sonanier
Ruang Kekuatan]]
  },
  AvgDialog_19133_Content_3 = {
    Text = [[
Ketika Pelaut naik ke kapal, Murphy tidak bersama kami. 
Celeste, di mana dia sekarang?]]
  },
  AvgDialog_19133_Content_4 = {
    Text = "Gadis Pembangun menutup matanya, beberapa titik cahaya muncul dari kompas di tangannya dan segera menghilang."
  },
  AvgDialog_19133_Content_5 = {
    Text = "Murphy… area asrama awak kapal."
  },
  AvgDialog_19133_Content_6 = {
    Text = "Asrama berada di buritan kapal. Aku akan membawa kalian ke sana."
  },
  AvgDialog_19133_Content_7 = {
    Text = "Namun, tubuh Anda..."
  },
  AvgDialog_19133_Content_8 = {
    Text = "Hanya berjalan dari haluan ke buritan, aku belum se-rapuh itu."
  },
  AvgDialog_19133_Content_9 = {
    Text = "Meskipun terjadi sesuatu — selalu ada cara untuk menyelesaikannya."
  },
  AvgDialog_19134_Content_1 = {
    Text = "Apakah suara kita terlalu keras sehingga mereka tertarik kemari?"
  },
  AvgDialog_19134_Content_2 = {
    Text = "Sekarang bukan waktu yang tepat untuk membahas ini, kita harus menghindari mereka terlebih dahulu."
  },
  AvgDialog_19134_Content_3 = {
    Text = "Ke buritan! Saya dan <Yellow:%player%> sudah membersihkan para Pelaut di sana!"
  },
  AvgDialog_19135_Content_1 = {Text = "Belati"},
  AvgDialog_19135_Content_10 = {
    Text = "Saya telah tinggal di kapal ini selama beberapa bulan. Di mana ada saluran ventilasi dan di mana ada lubang tikus, saya mengetahuinya dengan sangat jelas."
  },
  AvgDialog_19135_Content_11 = {
    Text = "Tapi kita bahkan tidak sedang merangkak di saluran ventilasi, hanya berputar-putar di dalam kabin kapal saja."
  },
  AvgDialog_19135_Content_12 = {
    Text = "Saya... saya jarang turun sendirian, biasanya saya selalu bersama dengan kapten dan yang lainnya."
  },
  AvgDialog_19135_Content_13 = {
    Text = "Ada denah di dinding."
  },
  AvgDialog_19135_Content_14 = {
    Text = "Apa maksudmu? Apakah kamu tidak percaya pada memori-ku?"
  },
  AvgDialog_19135_Content_15 = {
    Text = "Aku bilang kalau bisa menemukan, berarti bisa menemukan! Kapten mereka pasti di sini!"
  },
  AvgDialog_19135_Content_16 = {
    Text = "Namun, ini sudah kelima kalinya kita melewati tangga ini."
  },
  AvgDialog_19135_Content_17 = {
    Text = [[
Pasangan saya sedang menunggu untuk bertemu dengan kita. Dia pasti sangat cemas sekarang. 
 Tolong, Tuan Murphy, lihatlah denahnya.]]
  },
  AvgDialog_19135_Content_18 = {Text = "…Hm!"},
  AvgDialog_19135_Content_3 = {Text = "Hmm..."},
  AvgDialog_19135_Content_4 = {Text = "Murphy..."},
  AvgDialog_19135_Content_5 = {
    Text = "Jangan berisik! Kamu mengganggu aku berpikir."
  },
  AvgDialog_19135_Content_6 = {
    Text = [[
Terkait "mengganggu Murphy berpikir", kamu tidak memberikan pendapat.
Namun, kamu tahu bahwa kamu harus menghentikannya dari terus "berpikir".]]
  },
  AvgDialog_19135_Content_7 = {
    Text = "Karena kalian sudah bolak-balik, naik turun di dalam kapal untuk waktu yang sangat lama."
  },
  AvgDialog_19135_Content_8 = {
    Text = "Apakah kamu tersesat?"
  },
  AvgDialog_19135_Content_9 = {
    Text = "Tidak! Aku tidak mungkin tersesat!"
  },
  AvgDialog_19136_Content_1 = {
    Text = "Kapten, apakah Anda bisa membuat kapal segera berlabuh?"
  },
  AvgDialog_19136_Content_2 = {
    Text = "Jika bisa melakukan hal seperti ini, Sonaniel tidak akan dikejar oleh Pelaut."
  },
  AvgDialog_19136_Content_3 = {
    Text = "Lebih dekat lagi, lebih dekat lagi… hanya membiarkan kalian pergi… bisa dilakukan……\nPantai, sudah di ujung jari."
  },
  AvgDialog_19136_Content_4 = {
    Text = "Selama cukup dekat dengan daratan, kau akan punya cara untuk membuat semua orang meninggalkan kapal, kan? Celeste."
  },
  AvgDialog_19136_Content_5 = {
    Text = "Semuanya..."
  },
  AvgDialog_19136_Content_6 = {
    Text = "Hati-hati, mereka mengejar kita!"
  },
  AvgDialog_19137_Content_1 = {
    Text = "Melarikan diri"
  },
  AvgDialog_19137_Content_10 = {
    Text = "Penjaga, sudah cukup."
  },
  AvgDialog_19137_Content_11 = {
    Text = "Kikuk, sangat kikuk."
  },
  AvgDialog_19137_Content_12 = {
    Text = "Pertunjukan yang dibuat-buat memancing cemoohan dari penonton. Mereka menyeringai dengan wajah masam, lalu melompat ke atas panggung untuk menyerang pemeran utama — Murphy menghantam perutmu dengan satu serangan siku yang kuat."
  },
  AvgDialog_19137_Content_13 = {
    Text = "Hek, hek hek hek!"
  },
  AvgDialog_19137_Content_14 = {
    Text = "Menanggapi dia dengan penuh semangat"
  },
  AvgDialog_19137_Content_15 = {
    Text = "Untuk menanggapi kekhawatiran pasanganmu, kamu memperlihatkan senyuman penuh semangat, senyuman yang sedikit menyimpang, dengan delapan gigi yang tersusun rapi — membuatmu terlihat seperti hasil karya dari tangan Rogers."
  },
  AvgDialog_19137_Content_17 = {
    Text = "Sepertinya, saat aku tidak ada, kamu menjalani hidup dengan baik."
  },
  AvgDialog_19137_Content_18 = {
    Text = "Juga, juga tidak..."
  },
  AvgDialog_19137_Content_19 = {
    Text = "Benar, aku tidak melihat ada pelajar muda yang dikejar-kejar oleh Pelaut sampai-sampai terbentur dan akhirnya berguling-guling di tanah karena sakit pinggang."
  },
  AvgDialog_19137_Content_2 = {
    Text = [[
22:10
Kapal Sonaniel
Ruang Kekuatan Luar]]
  },
  AvgDialog_19137_Content_20 = {
    Text = "Murphy maju sedikit, menyelip di antara kamu dan Ramona — sambil tetap tidak lupa menabrak pinggang belakangmu yang cedera."
  },
  AvgDialog_19137_Content_21 = {
    Text = "Ssshh——"
  },
  AvgDialog_19137_Content_22 = {
    Text = "Ngomong-ngomong, apakah kamu tidak berniat untuk memperkenalkan kami satu sama lain?"
  },
  AvgDialog_19137_Content_23 = {
    Text = "Nama saya Murphy——"
  },
  AvgDialog_19137_Content_24 = {
    Text = "Musuh menabrak pintu ruang dalam, tersandung, lalu terhuyung-huyung menyerbu ke arah kalian."
  },
  AvgDialog_19137_Content_25 = {
    Text = "Di antara debu batubara yang diangkat oleh para penganut, wanita tinggi dan ramping melangkah dengan penuh kesalehan dan kegilaan."
  },
  AvgDialog_19137_Content_26 = {
    Text = "<BigShake: Cepat lari!>"
  },
  AvgDialog_19137_Content_3 = {
    Text = "Penjaga Rahasia!"
  },
  AvgDialog_19137_Content_4 = {
    Text = "Akhirnya, aku menemukanmu. Apakah kamu tidak terluka?"
  },
  AvgDialog_19137_Content_5 = {
    Text = "Ekspresi pasangan berubah-ubah antara terkejut, senang, dan cemas. Ekspresi yang begitu hidup seperti ini jarang terlihat darinya."
  },
  AvgDialog_19137_Content_6 = {
    Text = "Menjawabnya dengan suara yang sangat lemah, seperti benang yang hampir putus."
  },
  AvgDialog_19137_Content_7 = {
    Text = "Oleh karena itu, ketika Ramona menunjukkan kekhawatiran, kamu menutupi bagian perut bawahmu dan berpura-pura sekarat."
  },
  AvgDialog_19137_Content_8 = {
    Text = "Ramona... Aku tak menyangka... bisa bertemu denganmu lagi..."
  },
  AvgDialog_19138_Content_1 = {
    Text = [[
Murphy tidak banyak berbasa-basi. Dia menarik Ramona ke samping dan mulai membuka pakaiannya. 
 Saat kancing terakhir pada bagian depan terbuka, Ramona melihat "dewa" di dalam tubuh gadis itu.]]
  },
  AvgDialog_19138_Content_2 = {
    Text = "Di bagian dada terdapat sepotong kulit transparan. Kulit transparan ini menarik kulit dan otot di sekitarnya, menyebabkan seluruh rongga dada dan perut tampak berwarna putih pucat dengan tanda-tanda kemunduran."
  },
  AvgDialog_19138_Content_3 = {
    Text = "Fenomena aneh itu memperlihatkan organ di dalam rongga dada dengan jelas. Ramona melihat sebuah jantung muda berwarna merah pucat, serta sebuah \"telur\" berwarna susu."
  },
  AvgDialog_19138_Content_4 = {
    Text = "Tak terhitung jumlahnya benang halus menjulur dari \"telur\", erat berjalinan dengan pembuluh darah Murphy, saling bergantung satu sama lain."
  },
  AvgDialog_19138_Content_5 = {
    Text = "Seandainya keberadaannya tidak menekan jantung Murphy, Dia tampaknya menyatu sempurna dengan rongga dada transparan itu, tidak seperti benda asing."
  },
  AvgDialog_19138_Content_6 = {
    Text = "Dia Kekacauan namun tenang, orison segitiga terbalik yang terukir di atasnya juga ikut membeku, seperti sebuah karya seni yang aneh."
  },
  AvgDialog_19138_Content_7 = {
    Text = "<Yellow:Pelarutan>…barang ini sudah terkena pelarutan."
  },
  AvgDialog_19138_Content_8 = {
    Text = "Apakah sudah cukup melihat?"
  },
  AvgDialog_19138_Content_9 = {
    Text = "Maaf, aku terlalu lancang. Cepat kenakan bajumu."
  },
  AvgDialog_19139_Content_1 = {
    Text = "Pria kekar dan tinggi itu sama sekali tidak menahan amarahnya. Dia menendang Pelaut yang merangkak di kakinya, lalu mencabut pedang raksasa yang tertancap dalam di dek dengan nada yang tidak ramah."
  },
  AvgDialog_19139_Content_10 = {
    Text = "Kamu adalah pria yang muncul pada saat itu!"
  },
  AvgDialog_19139_Content_11 = {
    Text = "\"Pria itu\", terdengar sangat tidak sedap."
  },
  AvgDialog_19139_Content_12 = {
    Text = "Namaku <Blue:Goliath>. Ingatlah baik-baik, ini adalah nama orang yang telah menaklukkan semua lautan!"
  },
  AvgDialog_19139_Content_13 = {Text = "Menghadap!"},
  AvgDialog_19139_Content_2 = {
    Text = [[
Membiarkan kalian mencari <Blue:Saintess>, dan mendapatkan kembali <Blue:elemen kunci> dari ritual... apakah ini orang yang kalian temukan? 
 Selain jenis kelaminnya, apakah dia memiliki sedikit pun kemiripan dengan <Blue:Putri Boneka> itu!]]
  },
  AvgDialog_19139_Content_3 = {
    Text = "Penglihatan kalian sama buruknya dengan ikan mati."
  },
  AvgDialog_19139_Content_4 = {Text = "Guh..."},
  AvgDialog_19139_Content_5 = {
    Text = "<Big:Minggir semua!>"
  },
  AvgDialog_19139_Content_6 = {
    Text = "Raksasa berkulit hitam berdiri di barisan paling depan, dan Pelaut dengan patuh mundur ke kejauhan atas perintahnya."
  },
  AvgDialog_19139_Content_7 = {
    Text = "Hoh, bukankah ini makhluk malang yang dijadikan <Blue:batu loncatan>? Bagaimana kalian masih di kapal? Aku sudah memberi kalian kesempatan untuk pergi."
  },
  AvgDialog_19139_Content_8 = {
    Text = "Dari ujung dek terdengar langkah kaki yang berat. Sebuah suara pria kasar berbicara dalam bahasa yang belum pernah didengar sebelumnya, dan musuh yang mengepung pun surut seperti air pasang."
  },
  AvgDialog_19139_Content_9 = {
    Text = "Jangan pergi! Siapa kalian sebenarnya?"
  },
  AvgDialog_19140_Content_1 = {
    Text = "Murid, warna wajahmu sangat buruk."
  },
  AvgDialog_19140_Content_10 = {
    Text = "Gambar... Lu..."
  },
  AvgDialog_19140_Content_11 = {
    Text = "Di dalam kegelapan, ada beberapa sumber cahaya yang tampak sangat mencolok, namun betapapun kamu mengejarnya, itu hanya sia-sia. Roh-mu diblokade sepenuhnya oleh Pelaut."
  },
  AvgDialog_19140_Content_12 = {
    Text = "Murid! Cepat bangun!"
  },
  AvgDialog_19140_Content_13 = {Text = "Kapten...?"},
  AvgDialog_19140_Content_14 = {
    Text = "Orang hebat mengejar kita, cepat lari!"
  },
  AvgDialog_19140_Content_2 = {
    Text = "Musuhnya terlalu banyak. \n Jika serangan tidak melemah, aku tidak tahu bisa bertahan sampai kapan…"
  },
  AvgDialog_19140_Content_3 = {
    Text = "Dengan kekuatannya, menyelesaikan \"pasukan elit\" ini adalah hal yang mudah baginya."
  },
  AvgDialog_19140_Content_4 = {
    Text = "<Yellow:Tulu>?! Bagaimana dia bisa ada di sini?"
  },
  AvgDialog_19140_Content_5 = {
    Text = "Saya punya rencana! Kapten, tolong tahan musuh untuk sementara waktu."
  },
  AvgDialog_19140_Content_6 = {
    Text = "Kami tidak bisa bertahan terlalu lama, jadi apa pun yang ingin kamu lakukan, cepatlah."
  },
  AvgDialog_19140_Content_7 = {
    Text = "Kamu menutup mata, roh tenggelam dalam kegelapan, dan mulai mengejar kilauan di <Yellow:Dunia roh> seperti yang sudah lama tidak dilakukan."
  },
  AvgDialog_19140_Content_8 = {
    Text = "<BigShake: … terlalu banyak, terlalu banyak!>"
  },
  AvgDialog_19140_Content_9 = {
    Text = "Seperti melangkah ke kolam di hutan musim panas yang dalam, suara katak bergema seperti genderang perang yang terus-menerus... Setiap Pelaut ternyata memiliki jejaknya sendiri."
  },
  AvgDialog_19141_Content_1 = {
    Text = "Cukup, mereka hanyalah orang-orang yang tidak berarti."
  },
  AvgDialog_19141_Content_2 = {
    Text = "Berdiri diam di barisan paling belakang musuh, sosok yang sejak awal terdiam akhirnya berbicara."
  },
  AvgDialog_19141_Content_3 = {
    Text = "Itu adalah seorang wanita dewasa, Tubuhnya yang dibungkus oleh kain hitam tampak sangat kontras di antara ikan-ikan yang buruk rupa."
  },
  AvgDialog_19141_Content_4 = {
    Text = "Mengakhiri sandiwara ini… dan menyambut kembali <Blue:Dewi>."
  },
  AvgDialog_19141_Content_5 = {
    Text = "Dia berbalik menuju jembatan menara, dan atas perintahnya, seorang remaja berbadan tegap yang juga keluar dari kelompok manusia ikan maju ke depan."
  },
  AvgDialog_19141_Content_6 = {
    Text = "Manusia bersirip... tidak... mungkinkah <Yellow:Pembangun>?!"
  },
  AvgDialog_19142_Content_1 = {
    Text = "Keajaiban lainnya"
  },
  AvgDialog_19142_Content_10 = {
    Text = "Aigis, Nona Mason, Lily, Lisa… Hingga saat ini, kita telah bertemu dengan banyak orang yang tubuhnya telah dimodifikasi."
  },
  AvgDialog_19142_Content_11 = {
    Text = "Tetapi memindahkan <Blue:\"Dewa\"> ke dalam tubuh manusia hidup? Ini sungguh..."
  },
  AvgDialog_19142_Content_12 = {
    Text = "Tidak percaya juga tidak masalah, lagipula aku selalu berkata jujur."
  },
  AvgDialog_19142_Content_13 = {
    Text = "Maaf... hanya saja, semua ini terasa sangat sulit dipercaya."
  },
  AvgDialog_19142_Content_14 = {
    Text = "Murphy, bisakah kamu menunjukkan padaku itu... \"Dewa\"?"
  },
  AvgDialog_19142_Content_15 = {
    Text = "Masih mengatakan bahwa kamu tidak percaya!"
  },
  AvgDialog_19142_Content_16 = {
    Text = "Yah, tidak masalah. Di sini terlalu gelap, ayo pergi ke atas untuk melihat."
  },
  AvgDialog_19142_Content_2 = {
    Text = [[
22:20
Kapal Sonanier
Gudang Kargo Ketiga]]
  },
  AvgDialog_19142_Content_3 = {Text = "Ini……"},
  AvgDialog_19142_Content_4 = {
    Text = "Benar-benar sangat mengejutkan"
  },
  AvgDialog_19142_Content_5 = {
    Text = "Pelaut, Gereja Penerang Kuil, Dewa…"
  },
  AvgDialog_19142_Content_6 = {
    Text = "Dan tahanan itu... <Blue:Francis>, bukan?"
  },
  AvgDialog_19142_Content_7 = {
    Text = "Kalian mengenalnya? Penipu itu, menyebalkan! Dia sama sekali tidak kembali untuk membantu aku! Akhirnya, aku harus mencari cara untuk melarikan diri sendiri!"
  },
  AvgDialog_19142_Content_8 = {
    Text = "Dia juga memiliki alasan pahitnya sendiri..."
  },
  AvgDialog_19142_Content_9 = {
    Text = "Hmph... aku juga tidak menyalahkannya. Tidak lama setelah benda ini dimasukkan, Miryam memberi obat dan membuatku tertidur... Aku tidak tahu sudah berapa lama. Mungkin dia sudah datang, hanya saja aku melewatkannya."
  },
  AvgDialog_19143_Content_10 = {
    Text = "Sebelum kilatan pedang jatuh, dalam sekejap, kamu kembali memejamkan mata dengan penuh konsentrasi dan tenggelam ke dalam kegelapan."
  },
  AvgDialog_19143_Content_11 = {
    Text = "Kamu mengejar titik cahaya paling terang di sekitarmu, Roh-mu terjepit di antara kegelapan yang padat oleh tak terhitung banyaknya keberadaan, dan otakmu terasa sangat sakit akibat tarikan kuat."
  },
  AvgDialog_19143_Content_12 = {
    Text = "<Gray:Hanya sedikit lagi... sedikit lagi!>"
  },
  AvgDialog_19143_Content_13 = {
    Text = "Kamu berusaha \"menjulurkan tanganmu\" dan meraih bintang itu dengan tanganmu."
  },
  AvgDialog_19143_Content_14 = {
    Text = "Seperti jiwa yang meninggalkan tubuh, pandangan tiba-tiba meningkat, ditarik oleh kekuatan yang tak terelakkan keluar dari tubuh."
  },
  AvgDialog_19143_Content_15 = {
    Text = "Kamu melihat dirimu sendiri, melihat Celeste, melihat Ramona… akhirnya, kamu melihat seorang pemuda raja yang duduk di atas jembatan dengan ekspresi dingin."
  },
  AvgDialog_19143_Content_16 = {
    Text = "Dia awalnya dengan sikap sombong mengamati kekacauan di atas kapal, namun tiba-tiba seolah-olah menyadari sesuatu dan mengangkat kepala untuk melihat langit yang berkilauan dengan perubahan cahaya."
  },
  AvgDialog_19143_Content_17 = {
    Text = "Di langit yang tinggi, pandangan <Yellow:kamu> menembus Domain Celeste, bertemu dengan matanya yang terkejut."
  },
  AvgDialog_19143_Content_18 = {
    Text = "Swish——!"
  },
  AvgDialog_19143_Content_19 = {
    Text = "Tentakel-tentakel besar itu menarik sebuah serangan mematikan, tetapi sebelum pemiliknya mencapaimu, Penguasa Pedang Raksasa sudah mengunci gerakanmu dengan kuat."
  },
  AvgDialog_19143_Content_2 = {
    Text = "Penyelidik Universitas Mythag, apakah hanya punya kemampuan sejauh ini?"
  },
  AvgDialog_19143_Content_20 = {
    Text = "<BigShake: Hahahaha>, menarik, sangat menarik."
  },
  AvgDialog_19143_Content_21 = {
    Text = [[
Bocah ini sudah terhubung denganmu melalui Tautan, benar kan?
Hebat sekali, aku tidak sabar ingin melihat bagaimana wanita itu menjadi gila.]]
  },
  AvgDialog_19143_Content_22 = {
    Text = "<Big:Melampaui batas! Lepaskan dia!>"
  },
  AvgDialog_19143_Content_23 = {
    Text = "Saya harus membawa sesuatu untuk melapor, kalau bukan anak ini, pasti kapten."
  },
  AvgDialog_19143_Content_24 = {
    Text = "Jangan pedulikan aku!"
  },
  AvgDialog_19143_Content_25 = {
    Text = "Bawa kapten pergi, bawa mereka ke tempat yang aman!"
  },
  AvgDialog_19143_Content_26 = {Text = "Kau……"},
  AvgDialog_19143_Content_27 = {
    Text = "Lindungi mereka saat mereka pergi!"
  },
  AvgDialog_19143_Content_3 = {
    Text = "Bangun kekuatan Pembangun…\nKamu adalah pemimpin kedua dari Ordo Pelaut."
  },
  AvgDialog_19143_Content_4 = {
    Text = "Peringkat kedua? Hah, <BigShake:Serangga kecil yang berani besar!>"
  },
  AvgDialog_19143_Content_6 = {Text = "Ugh!"},
  AvgDialog_19143_Content_7 = {
    Text = "Pertempuran terus-menerus membuatmu kelelahan. Saat mencoba memobilisasi dan membangun kembali tautan dengan Pembangun, pandanganmu tiba-tiba menjadi gelap berkali-kali."
  },
  AvgDialog_19143_Content_8 = {
    Text = "Mampu menahan serangan ini, tidak buruk, tapi apakah kamu bisa menangkis serangan berikutnya!"
  },
  AvgDialog_19143_Content_9 = {
    Text = "<Gray:Ini adalah kesempatan terakhir...!>"
  },
  AvgDialog_19144_Content_1 = {Text = "Mata Badai"},
  AvgDialog_19144_Content_10 = {
    Text = "Bulan purnama raksasa menggantung tinggi di langit malam, kabut tipis menyelimuti permukaan laut, bau mesiu dan garam dari air laut memenuhi rongga hidung."
  },
  AvgDialog_19144_Content_11 = {
    Text = "Suara ombak yang saling mendorong terdengar lembut dan teratur. Mereka menopang lambung kapal dengan lembut, mengapungkannya menuju tujuan yang tidak diketahui."
  },
  AvgDialog_19144_Content_12 = {
    Text = [[
Tak diragukan lagi, kamu berada di sebuah kapal, sendirian.
Ramona tidak ada di sisimu, dan tidak ada seorang pun dalam pandangan.]]
  },
  AvgDialog_19144_Content_13 = {
    Text = "Mencoba menghubungkan alat komunikasi"
  },
  AvgDialog_19144_Content_14 = {
    Text = "Ramona? Bisa dengar?"
  },
  AvgDialog_19144_Content_15 = {
    Text = "Nyonya Boneka? Erica?"
  },
  AvgDialog_19144_Content_16 = {
    Text = "Kamu menunggu lama tanpa mendengar suara temanmu, dan baru menyadari bahwa <Yellow:brooch> yang melambangkan identitasmu tidak ada di kerah bajumu."
  },
  AvgDialog_19144_Content_17 = {
    Text = "...Sekarang situasinya sudah berbeda."
  },
  AvgDialog_19144_Content_18 = {
    Text = "Meskipun tidak separah kehilangan Kunci perak, kehilangan bros yang berfungsi sebagai alat komunikasi berarti kehilangan kontak dengan rekan dan dukungan."
  },
  AvgDialog_19144_Content_19 = {
    Text = "Tenang, tenang. \nMari kita pikirkan dari awal, mengapa aku bisa berada di kapal ini…"
  },
  AvgDialog_19144_Content_20 = {
    Text = "Diary Francis... Pelabuhan..."
  },
  AvgDialog_19144_Content_21 = {
    Text = "Jika sudah siap, ayo berangkat. Aku akan tetap menjadi pasanganmu seperti biasa."
  },
  AvgDialog_19144_Content_22 = {
    Text = "Kali ini… gereja… yang terkait… kau harus——"
  },
  AvgDialog_19144_Content_23 = {
    Text = "Kamu baru saja mengingat beberapa gambar yang tersebar, lalu rasa sakit yang hebat memotong memori-mu."
  },
  AvgDialog_19144_Content_24 = {Text = "……Ugh!"},
  AvgDialog_19144_Content_25 = {
    Text = "Asam lambung naik, membakar tenggorokanmu. Udara segar saat ini menjadi kemewahan."
  },
  AvgDialog_19144_Content_26 = {
    Text = "Hu——Apa yang sebenarnya terjadi?"
  },
  AvgDialog_19144_Content_27 = {
    Text = "Saya dan Ramona meninggalkan sekolah bersama... Ya, Ramona, aku harus menemukan Ramona."
  },
  AvgDialog_19144_Content_28 = {
    Text = "Jika itu dia, seharusnya dia tahu apa yang terjadi."
  },
  AvgDialog_19144_Content_29 = {Text = "——!"},
  AvgDialog_19144_Content_3 = {Text = "Ngh..."},
  AvgDialog_19144_Content_30 = {
    Text = "Logam mengeluarkan suara melengkung tajam. Raksasa baja ini mungkin sudah tidak bisa lagi menahan lautan."
  },
  AvgDialog_19144_Content_31 = {
    Text = "Tempat ini tidak cocok untuk tinggal terlalu lama."
  },
  AvgDialog_19144_Content_32 = {
    Text = "Keinginan untuk menemukan pasangan semakin mendesak. Kamu menahan rasa nyeri tumpul di bagian belakang kepala dan rasa mual, lalu berjalan dua langkah sambil bersandar pada lambung kapal."
  },
  AvgDialog_19144_Content_33 = {
    Text = "Jangan bertindak sembarangan."
  },
  AvgDialog_19144_Content_34 = {Text = "Tulu?!"},
  AvgDialog_19144_Content_35 = {Text = "Kau……"},
  AvgDialog_19144_Content_36 = {
    Text = "Kenapa kamu belum tidur?"
  },
  AvgDialog_19144_Content_37 = {
    Text = "Pemuda Bangun menatapmu sekilas, pandangan tenang namun penuh wibawa tertuju padamu."
  },
  AvgDialog_19144_Content_38 = {
    Text = "Ucapan tidak hormat kali ini, aku anggap seolah-olah tidak pernah mendengarnya."
  },
  AvgDialog_19144_Content_39 = {
    Text = "Kenapa kamu juga ada di sini?"
  },
  AvgDialog_19144_Content_4 = {
    Text = "Sudah pagi… ya?"
  },
  AvgDialog_19144_Content_40 = {
    Text = "Pemuda Pembangun dengan cukup terkejut mengangkat alisnya, lalu memandangmu beberapa kali dengan tatapan penuh penilaian."
  },
  AvgDialog_19144_Content_41 = {
    Text = "Masih bisa bercanda, sepertinya kamu baik-baik saja."
  },
  AvgDialog_19144_Content_42 = {
    Text = [[
Seperti Lotan, Ogier, dan lainnya, Tulu adalah salah satu Pembangun yang diawasi oleh <Yellow:Mythag>. 
 Namun, selama setahun berlatih di Mythag, kamu hanya bisa menghitung dengan satu tangan berapa kali kamu melihat Tulu.]]
  },
  AvgDialog_19144_Content_43 = {
    Text = "Konon, sebagian besar waktu Tulu berada dalam keadaan tidur, dan jumlah kali dia bangun bisa dihitung dengan jari. Oleh karena itu, Tulu secara alami dikeluarkan dari daftar Pembangun lapangan."
  },
  AvgDialog_19144_Content_44 = {
    Text = "Namun, pada saat ini, kalian terikat erat oleh <Yellow:Tautan> yang tak terlihat, dan kamu bisa merasakan energi roh Tulu yang sangat besar seperti badai."
  },
  AvgDialog_19144_Content_45 = {
    Text = "Aku... ada Tautan di antara kita?!"
  },
  AvgDialog_19144_Content_46 = {
    Text = "Pertanyaan yang bodoh."
  },
  AvgDialog_19144_Content_47 = {
    Text = "Tunggu, apakah kamu tahu di mana Ramona berada? Kami meninggalkan sekolah bersama."
  },
  AvgDialog_19144_Content_48 = {
    Text = "Sekarang bukan saatnya bercanda, waktu yang tersisa sudah tidak banyak."
  },
  AvgDialog_19144_Content_49 = {
    Text = "<Yellow:Upacara Pemanggilan> belum selesai, bintang-bintang sedang terbit menuju tempat yang dituju."
  },
  AvgDialog_19144_Content_5 = {
    Text = "Kepala pusing, pelipis terasa nyeri."
  },
  AvgDialog_19144_Content_50 = {
    Text = "\"Upacara Pemanggilan Roh\"?"
  },
  AvgDialog_19144_Content_51 = {
    Text = "Begitu pertanyaan keluar, atmosfer di antara kamu dan Tulu tiba-tiba menjadi kaku, udara terasa begitu berat hingga mulai membuatmu meragukan apakah kamu memiliki hak untuk mengajukan pertanyaan kepadanya."
  },
  AvgDialog_19144_Content_52 = {
    Text = "Namun, <Yellow:\"Penurunan Dewa\"> merupakan kata kunci yang terlalu sensitif dan penting bagi Penjaga Mythag."
  },
  AvgDialog_19144_Content_53 = {
    Text = "Tulu, aku..."
  },
  AvgDialog_19144_Content_54 = {
    Text = "Bersiaplah menghadapi musuh."
  },
  AvgDialog_19144_Content_55 = {Text = "Apa?"},
  AvgDialog_19144_Content_56 = {Text = "Plak..."},
  AvgDialog_19144_Content_57 = {
    Text = "Dengan suara aneh seperti pukulan kaki katak, musuh-musuh menyerbu dari kegelapan."
  },
  AvgDialog_19144_Content_6 = {
    Text = "Tenggorokan juga terasa seperti menelan seteguk besar kecap pedas, setiap napas membawa rasa sesak dan nyeri yang menyengat."
  },
  AvgDialog_19144_Content_7 = {
    Text = "Membuka mata, sakit kepala, tempat yang tidak dikenal."
  },
  AvgDialog_19144_Content_8 = {
    Text = "Ya Tuhan, apakah tidak ada pembukaan yang lebih inovatif?"
  },
  AvgDialog_19144_Content_9 = {
    Text = "Kamu bangkit berdiri, pemandangan yang tak terduga tiba-tiba terpampang di hadapan mata."
  },
  AvgDialog_19145_Content_1 = {
    Text = "Serangan musuh tidak memberi Ramona banyak waktu untuk bereaksi, pedangnya bahkan belum sempat terhunus——"
  },
  AvgDialog_19145_Content_2 = {
    Text = "Pedang raksasa dilemparkan dengan kasar dari kejauhan ke arah dua orang itu, dengan kekuatan begitu besar hingga merobek udara dan membangkitkan gelombang kejut yang hebat."
  },
  AvgDialog_19145_Content_3 = {
    Text = "Tentakel yang kokoh melilit pinggang Ramona, menariknya menjauh dari titik jatuhnya bilah raksasa."
  },
  AvgDialog_19145_Content_4 = {
    Text = "Setelah Ramona berdiri teguh, tentakel Tulu dengan cepat menarik diri dan bergabung dalam barisan untuk menghadapi serangan."
  },
  AvgDialog_19145_Content_5 = {
    Text = "Sepertinya sekarang kita harus bekerja sama."
  },
  AvgDialog_19145_Content_6 = {
    Text = "Tak perlu banyak kata."
  },
  AvgDialog_19163_Content_1 = {
    Text = "Pelayaran Tragis"
  },
  AvgDialog_19163_Content_10 = {
    Text = [[
Tidak apa-apa, kalian duluan bergabung dengan yang lain. 
 Aku perlu memastikan alasan mereka tidak menyerah untuk melaksanakan ritual.]]
  },
  AvgDialog_19163_Content_11 = {
    Text = "Tulu sedang melakukan penyelidikan sendirian. Dia ingin memastikan mengapa Pelaut masih terus beraksi."
  },
  AvgDialog_19163_Content_12 = {
    Text = "Tulu? Jika begitu, setelah ledakan kalian sudah bertemu. Apakah dia tidak mengalami kelainan akibat pertempuran dan ledakan?"
  },
  AvgDialog_19163_Content_13 = {
    Text = "Kamu dengan cermat mengingat semua percakapan dengan Tulu setelah ledakan——dia tampak sangat tenang."
  },
  AvgDialog_19163_Content_14 = {
    Text = "Tulu lebih sadar dibandingkan saat aku bangun dari pingsan, dan aku juga tidak merasakan adanya kelainan dari tautan."
  },
  AvgDialog_19163_Content_15 = {
    Text = "Kamu dengan hati-hati menyembunyikan tautan antara Tulu dan Ramona di tempat terdalam dunia roh, secara tidak sadar menutupi fakta bahwa badai pernah menerjang pikiranmu."
  },
  AvgDialog_19163_Content_16 = {
    Text = "Dome Gnosis yang retak sedang perlahan pulih, rasa sakit dari Jiwa yang tercabik dan kemudian disatukan kembali juga tidak lagi terasa jelas. Pada saat ini, kamu tidak ingin menambahkan beban baru pada pasanganmu yang sudah sangat lelah."
  },
  AvgDialog_19163_Content_17 = {
    Text = "Apakah kamu pingsan?!"
  },
  AvgDialog_19163_Content_18 = {
    Text = "Jangan khawatir, aku sekarang sangat sehat — Celeste sudah menyembuhkanku sepenuhnya."
  },
  AvgDialog_19163_Content_19 = {
    Text = [[
Kamu melirik Celeste dengan perasaan bersalah, dan dia yang namanya disebutkan juga menoleh untuk melihatmu. 
 Kamu berkedip padanya, dan dia hanya memandangmu sejenak tanpa mengatakan apa-apa.]]
  },
  AvgDialog_19163_Content_2 = {
    Text = [[
Waktu hingga Selaras
tersisa: 80 menit]]
  },
  AvgDialog_19163_Content_20 = {
    Text = "Karena kamu sudah berkata seperti ini……"
  },
  AvgDialog_19163_Content_21 = {
    Text = "Parasit di dalam tubuh Murphy perlu segera dioperasi untuk dilepaskan. Semakin lama ia berkembang di dalam tubuh Murphy, semakin berbahaya situasi bagi semua orang."
  },
  AvgDialog_19163_Content_22 = {
    Text = "Kita harus segera kembali ke daratan, tapi... aku tidak merasakan gerakan kapal."
  },
  AvgDialog_19163_Content_23 = {
    Text = "Kapten, negara kalian sudah tidak cukup untuk mendukung pengendalian Sonnel kembali ke pangkalan, bukan?"
  },
  AvgDialog_19163_Content_24 = {
    Text = "…Benar, keberadaan Celeste masih bisa bertahan. Bagi aku dan dia, itu adalah sebuah keajaiban."
  },
  AvgDialog_19163_Content_25 = {
    Text = "Bagaimana jika menggunakan sekoci penyelamat?"
  },
  AvgDialog_19163_Content_26 = {
    Text = "Elton menggelengkan kepalanya."
  },
  AvgDialog_19163_Content_27 = {
    Text = "Perahu penyelamat tidak bermotor, bagaimana mungkin bisa membawa begitu banyak dari kami kembali ke daratan hanya dengan dayung? Ini sangat tidak realistis."
  },
  AvgDialog_19163_Content_28 = {
    Text = "Bagaimana bisa… benar-benar tidak ada cara lain?"
  },
  AvgDialog_19163_Content_29 = {
    Text = "Elton menepuk kepala Murphy dengan penuh ketenangan. Begitu dia mengangkat kepala, dia menyadari bahwa dirinya sudah dikelilingi oleh tatapan cemas dari kamu dan Ramona. Dia terdiam sesaat, lalu tertawa kecil."
  },
  AvgDialog_19163_Content_3 = {
    Text = "Karang-karang ini... dari mana mereka tumbuh?"
  },
  AvgDialog_19163_Content_30 = {
    Text = "Kalian jangan sampai melupakan..."
  },
  AvgDialog_19163_Content_31 = {
    Text = "Sonanier adalah sebuah kapal."
  },
  AvgDialog_19163_Content_32 = {
    Text = "Saya setiap tahun merawat sistem tenaganya sesuai dengan manual standar, dan Ruang kekuatannya juga selalu menyala."
  },
  AvgDialog_19163_Content_33 = {
    Text = "Asalkan bisa menyentuh kemudi..."
  },
  AvgDialog_19163_Content_34 = {
    Text = "Tapi... pertempuran kita dengan Miryam telah menyebabkan kerusakan yang cukup besar pada ruang kekuatan, apalagi ledakan yang dia picu kemudian…"
  },
  AvgDialog_19163_Content_35 = {
    Text = [[
Hmm... aku justru lupa akan hal itu... 
 Jika tidak ada daya dari boiler, meskipun sampai di ruang kemudi pun tidak akan ada gunanya.]]
  },
  AvgDialog_19163_Content_36 = {
    Text = "Tidak... ada."
  },
  AvgDialog_19163_Content_37 = {
    Text = "Saya dan %player% datang melalui jalan memutar dari Ruang Kekuatan, meskipun sudah hancur seperti reruntuhan, setidaknya masih ada dua boiler yang menyala."
  },
  AvgDialog_19163_Content_38 = {
    Text = "Dua ketel uap sudah cukup untuk mengendalikan kapal ini."
  },
  AvgDialog_19163_Content_39 = {
    Text = "Jadi, apakah sekarang kita bisa pergi ke ruang kemudi untuk melihat? Jujur, aku sudah penasaran lama sekali——"
  },
  AvgDialog_19163_Content_4 = {
    Text = "Pandangan menyapu satu per satu Sanga dengan bentuk yang berbeda-beda, dan akhirnya berhenti pada individu Sanga terbesar yang menjadi fokus visual."
  },
  AvgDialog_19163_Content_40 = {
    Text = "Ssst, ssst, pelan-pelan! Musuh sudah terpancing!"
  },
  AvgDialog_19163_Content_5 = {
    Text = "Sanga tumbuh dari D-marka, dengan kasar mendorong dek terbuka, dan langsung menunjuk ke arah dinding bagian atas."
  },
  AvgDialog_19163_Content_6 = {
    Text = [[
Kami menyebut hal-hal ini sebagai D-hiperplasia. 
 Secara sederhana, semakin dekat dengan inti Fenomena-d, semakin mudah muncul D-hiperplasia.]]
  },
  AvgDialog_19163_Content_7 = {
    Text = "Pelarutan…lagi-lagi Pelarutan."
  },
  AvgDialog_19163_Content_8 = {
    Text = "Di antara kelompok Pelaut muncul individu abnormal yang terparasit, kemungkinan besar juga berkaitan erat dengan penyebaran Fenomena-d."
  },
  AvgDialog_19163_Content_9 = {
    Text = "Mengenai hal ini..."
  },
  AvgDialog_19170_Content_1 = {
    Text = "Lintasan Bintang yang Tidak Diketahui"
  },
  AvgDialog_19170_Content_10 = {
    Text = "Adapun para pelaut... Ketika kami tiba di laut, kapal Sonaniel sudah sepenuhnya tenggelam, dan kami tidak mendapatkan apa pun."
  },
  AvgDialog_19170_Content_11 = {
    Text = "Keberadaan Goliath juga?"
  },
  AvgDialog_19170_Content_12 = {
    Text = "Tidak tahu, mungkin berubah menjadi ikan sungguhan, mungkin tenggelam, mungkin melarikan diri dengan sekoci. Ngomong-ngomong, kami sedang mencoba untuk menangkap inti perak Miryam, tapi belum ada hasil untuk sementara waktu."
  },
  AvgDialog_19170_Content_13 = {
    Text = "Mari kita berhenti membicarakan ini. Saya datang untuk menjelaskan laporan pemeriksaan kepada Anda."
  },
  AvgDialog_19170_Content_14 = {
    Text = "Boneka meletakkan setumpuk laporan kertas di atas meja tulis, memberi isyarat agar kamu memeriksanya sendiri."
  },
  AvgDialog_19170_Content_15 = {
    Text = "Namun, setelah pemeriksaan tubuh selama tiga hari penuh, kamu merasa lelah secara fisik dan mental, dan sangat ingin mendapatkan jawaban dengan segera."
  },
  AvgDialog_19170_Content_16 = {
    Text = "Kalau ada kabar buruk, katakan saja. Saya bisa menerimanya."
  },
  AvgDialog_19170_Content_17 = {Text = "Tubuhmu…"},
  AvgDialog_19170_Content_18 = {
    Text = "Sangat sehat, kecuali anemia, tidak ada kelainan lainnya."
  },
  AvgDialog_19170_Content_19 = {
    Text = "Boneka berhenti sejenak, lalu melanjutkan."
  },
  AvgDialog_19170_Content_2 = {
    Text = "Tiga hari kemudian·Universitas mythag"
  },
  AvgDialog_19170_Content_20 = {
    Text = "Adapun alasan anemia… dugaan awalnya adalah bahwa terlalu banyak darah diambil selama pemeriksaan tiga hari ini."
  },
  AvgDialog_19170_Content_21 = {
    Text = "Sangat sehat... Bagaimana mungkin? Aku jelas-jelas.."
  },
  AvgDialog_19170_Content_22 = {
    Text = "Berdasarkan laporan Ramona dan yang lainnya, luka-luka yang kau alami di kapal cukup untuk membuat orang biasa mati sembilan kali. Bahkan monster seperti kucing pun tidak akan tahan dengan penyiksaan seperti itu."
  },
  AvgDialog_19170_Content_23 = {
    Text = "Saya hampir mulai curiga, apakah kamu memiliki darah troll."
  },
  AvgDialog_19170_Content_24 = {
    Text = "Jantungmu hampir sampai di tenggorokan, rasa tegang membuat semua otot di tubuhmu menegang."
  },
  AvgDialog_19170_Content_25 = {
    Text = "Bercanda, troll raksasa tidak ada di dunia ini, setidaknya tidak ada dalam dunia yang diketahui oleh manusia."
  },
  AvgDialog_19170_Content_26 = {
    Text = "Laranganmu untuk keluar sudah dicabut. Jika kamu ingin mengobrol dengan teman-teman yang telah mengalami hidup dan mati bersamamu di kapal Sonnelier, mereka sedang berada di halaman sekolah untuk memberikan penghormatan kepada kapten."
  },
  AvgDialog_19170_Content_27 = {
    Text = "Mengantar?!"
  },
  AvgDialog_19170_Content_28 = {
    Text = "Ya, meskipun Universitas Mythag tidak kekurangan tempat untuk berpijak, tampaknya Elton sendiri tidak mau tinggal di tempat yang sama terus-menerus."
  },
  AvgDialog_19170_Content_29 = {
    Text = "Kamu segera meraih jaketmu, melompat dari tempat tidur, dan mengangguk kepada Boneka. Namun, tepat saat kamu akan meninggalkan kamar asrama, Boneka memanggilmu."
  },
  AvgDialog_19170_Content_3 = {
    Text = "Kamu bangun cukup pagi hari ini, kenapa terlihat begitu cemas? Saat kamu menampilkan ekspresi ini, kamu tampak sangat mirip dengan William."
  },
  AvgDialog_19170_Content_30 = {
    Text = "...Aku sangat senang kamu bisa kembali dengan selamat."
  },
  AvgDialog_19170_Content_31 = {
    Text = "Baiklah, pergilah segera. Mereka sedang menunggumu."
  },
  AvgDialog_19170_Content_32 = {
    Text = "Penjaga, kami di sini."
  },
  AvgDialog_19170_Content_33 = {
    Text = "Semua orang berdiri di halaman tengah kampus, setelah tiga hari tidak bertemu, Negara semua orang tampaknya sudah pulih cukup banyak."
  },
  AvgDialog_19170_Content_34 = {
    Text = "——Kecuali Celeste. Dia masih mempertahankan postur semi-transparan, samar-samar seperti fatamorgana yang bisa hilang tertiup angin."
  },
  AvgDialog_19170_Content_35 = {
    Text = "Pada saat Sonaniel menghadapi pembongkaran setelah mengalahkan Anak Suci, angin putih yang familiar menyelimuti kalian. Celeste memulai teleportasi jarak jauh, mengirim semua orang kembali ke daratan."
  },
  AvgDialog_19170_Content_36 = {
    Text = "Sebagai harga yang harus dibayar, kondisi roh Kapten Elton mengalami kerusakan parah. Meskipun telah menjalani sembuh di Universitas Mythag, tautan antara dia dan Celeste sulit untuk diperbaiki kembali."
  },
  AvgDialog_19170_Content_37 = {
    Text = "Peneliti muda itu akhirnya membebaskanmu. Aku pikir aku tidak akan bisa bertemu denganmu lagi sebelum pergi, dan sedang merasa cemas karenanya."
  },
  AvgDialog_19170_Content_38 = {Text = "Kapten..."},
  AvgDialog_19170_Content_39 = {Text = "Intinya."},
  AvgDialog_19170_Content_4 = {
    Text = "Aku masih memikirkan apa yang terjadi di laut... para Pelaut itu, sang \"dewa palsu\" yang berubah menjadi debu dan menghilang di lautan..."
  },
  AvgDialog_19170_Content_40 = {
    Text = "Kapten berjalan mendekatimu, lalu melambaikan tangan kepada Celeste yang tubuhnya transparan hingga hanya tersisa sedikit siluet."
  },
  AvgDialog_19170_Content_41 = {
    Text = "Pembangun juga tidak mengerti apa-apa seperti kamu, tapi tetap tenang melayang ke sisimu ——"
  },
  AvgDialog_19170_Content_42 = {
    Text = "Murid, ulurkan tangan."
  },
  AvgDialog_19170_Content_43 = {Text = "(Mencapai)"},
  AvgDialog_19170_Content_44 = {
    Text = "Elton mengangkat tangan transparan miliknya dan meletakkannya di atas telapak tanganmu yang terbuka."
  },
  AvgDialog_19170_Content_45 = {
    Text = "Apa pun caranya, pastikan dia tetap tinggal."
  },
  AvgDialog_19170_Content_46 = {
    Text = "Dia sudah cukup menderita semasa hidupnya, tidak perlu lagi membiarkannya hidup demi keinginanku."
  },
  AvgDialog_19170_Content_47 = {
    Text = "...Apakah ini juga keinginanmu?"
  },
  AvgDialog_19170_Content_48 = {
    Text = "Kapten terkejut karena ucapan Pembangun, namun hanya beberapa detik kemudian, dia tertawa lepas dengan gembira."
  },
  AvgDialog_19170_Content_49 = {
    Text = "Pelayaran berikutnya \"Celeste\", aku menyerahkannya padamu."
  },
  AvgDialog_19170_Content_5 = {
    Text = "Dengan titik awal di tempat lenyapnya \"Pseudo-Dewa\", dunia Domain di sekitarnya berubah secara drastis. Ini adalah situasi yang belum pernah terjadi sejak \"Clades\" dimusnahkan di masa lalu."
  },
  AvgDialog_19170_Content_50 = {
    Text = "...Baiklah."
  },
  AvgDialog_19170_Content_51 = {
    Text = [[
Dengan momen tautan Celeste, kesadaran yang rapuh dan megah mengaliri otakmu.
Padahal berdiri di darat, namun dadamu masih merasakan sesak seperti tenggelam.]]
  },
  AvgDialog_19170_Content_52 = {
    Text = "Bentuk Celeste tidak lagi samar-samar. Dia benar-benar ada di dunia ini."
  },
  AvgDialog_19170_Content_53 = {
    Text = "Elton melambaikan tangan untuk perpisahan terakhir, kalian mengamati dia memulai perjalanan baru untuk mencari Rumah yang hilang."
  },
  AvgDialog_19170_Content_54 = {
    Text = "Ngomong-ngomong, di mana Caecus? Bukankah dia yang paling dekat dengan kapten? Kenapa dia tidak datang untuk mengantarnya?"
  },
  AvgDialog_19170_Content_55 = {
    Text = "Ramona menunjuk ke arah pohon lanskap yang tidak jauh. Di bawah naungan pohon itu, terdapat pemuda Caecus. Pandangannya erat mengikuti mobil yang mulai bergerak, hingga akhirnya benar-benar menghilang di Domain Kabut Mythag."
  },
  AvgDialog_19170_Content_56 = {
    Text = "Mood Caecus... selalu tidak terlalu baik. Selama di kapal, hidupnya juga telah mengalami perubahan besar. Biarkan dia sendiri untuk sementara."
  },
  AvgDialog_19170_Content_57 = {
    Text = "Mungkin, kamu ingin bertemu dengan Murphy?"
  },
  AvgDialog_19170_Content_58 = {
    Text = [[
Universitas Mythag
Luar Asrama Pembangun]]
  },
  AvgDialog_19170_Content_59 = {
    Text = "Murphy, ini saya."
  },
  AvgDialog_19170_Content_6 = {
    Text = "Apakah segalanya berubah total?"
  },
  AvgDialog_19170_Content_60 = {Text = "Masuklah."},
  AvgDialog_19170_Content_61 = {
    Text = "Bagian logistik telah menyiapkan asrama paling mewah untuk Murphy. Saat kamu membuka pintu dan masuk, Murphy sedang duduk di atas kasur wol yang lembut sambil minum teh, dan nampan teh diletakkan begitu saja di atas tempat tidur."
  },
  AvgDialog_19170_Content_62 = {
    Text = "Kamu... apa kabar?"
  },
  AvgDialog_19170_Content_63 = {
    Text = "Apa bagaimana? Apakah kamu sedang membicarakan hidangan penutup yang hambar di Universitas Mythag? Atau tentang bagaimana kita akhirnya terbebas dari Pelaut? Atau tentang bagaimana aku menjadi Pembangun?"
  },
  AvgDialog_19170_Content_64 = {
    Text = "Saya, saya... maaf, saya tidak meminta izinmu dulu..."
  },
  AvgDialog_19170_Content_65 = {
    Text = "Jadi, aku diubah menjadi Pembangun, kan?"
  },
  AvgDialog_19170_Content_66 = {
    Text = "Maaf, aku tahu ini mungkin bukan hasil yang kamu harapkan… tapi aku hanya…"
  },
  AvgDialog_19170_Content_67 = {
    Text = "Aku hanya... tidak ingin lagi..."
  },
  AvgDialog_19170_Content_69 = {
    Text = "Saya merasa sangat lega."
  },
  AvgDialog_19170_Content_7 = {
    Text = "Lingkungan lebih berbahaya, mutan lebih kuat, kemampuan Teknologi chip perak hingga Pembangun di sana dibatasi di mana-mana… Tim penyelidik memberi situasi ini sebuah nama, disebut <Yellow:\"Efek-d regional\">."
  },
  AvgDialog_19170_Content_70 = {
    Text = "Perasaan ketika jantung tidak lagi berdetak, sangat asing, sangat menakutkan. Namun..."
  },
  AvgDialog_19170_Content_71 = {
    Text = "Saya benar-benar merasakan kebebasan yang belum pernah saya rasakan sebelumnya."
  },
  AvgDialog_19170_Content_72 = {
    Text = "Ekspresi Murphy tampak santai, tidak terlihat dibuat-buat. Berdasarkan pemahamanmu tentang dia, dia memang bukan orang yang pandai berbohong."
  },
  AvgDialog_19170_Content_73 = {
    Text = "Benarkah? Saat aku berpisah dengan kapten tadi, kau tidak datang. Aku sempat berpikir..."
  },
  AvgDialog_19170_Content_74 = {
    Text = "Apa kau pikir aku menangis diam-diam di bawah selimut?"
  },
  AvgDialog_19170_Content_75 = {
    Text = "Ada apa yang perlu disedihkan? Bukankah dia sudah memberitahumu? Dia berkata setiap malam Silver Frost, dia akan datang untuk melihat aku dan Caecus."
  },
  AvgDialog_19170_Content_76 = {
    Text = "Dan kapten juga mengajakku minum teh sepanjang pagi, berbicara panjang lebar tentang bagaimana dia berharap aku bebas, berharap aku tidak terikat oleh identitas sebagai Pembangun… Hmph, memangnya harus dia yang memberitahu nona ini?"
  },
  AvgDialog_19170_Content_77 = {
    Text = "Ngomong-ngomong, mau coba camilan teh? Brownies cokelat dari dapur hari ini rasanya cukup enak——"
  },
  AvgDialog_19170_Content_78 = {
    Text = "Baru saja, siapa yang bilang kalau hidangan penutup di universitas terasa hambar..."
  },
  AvgDialog_19170_Content_79 = {
    Text = "Garpu sudah ada di depan mulutmu, lalu kamu menggigit sepotong kue."
  },
  AvgDialog_19170_Content_8 = {
    Text = "Kabar baiknya adalah, Efek-d regional saat ini bersifat lokal; kabar buruknya adalah, kita saat ini tidak dapat mengendalikan kemunculan dan perpindahan Efek-d regional. Itu seperti ikan lele di dalam minyak yang sangat licin."
  },
  AvgDialog_19170_Content_80 = {
    Text = "Rasa asam, manis, dan pahit cokelat melebur bersamaan di dalam mulut, sedangkan minyak dari kacang-kacangan dengan cerdik menyatukan berbagai sensasi rasa, membuat Brownie menari di atas indra pengecapan Anda."
  },
  AvgDialog_19170_Content_81 = {
    Text = "Kamu dan Murphy duduk di tepi tempat tidur, berbincang santai, dan melahap habis semua hidangan penutup untuk lima orang dari teh sore itu."
  },
  AvgDialog_19170_Content_9 = {
    Text = "Pokoknya, wilayah laut itu sudah ditetapkan oleh Komite sebagai zona terlarang Efek-d regional. Saya pikir, itu akan selamanya menghilang dari peta sumber daya yang sudah miskin di Kerajaan Leo."
  },
  AvgDialog_19196_Content_10 = {
    Text = "……Hm. \n<Small: Lumayan, orang ini setidaknya masih ingat Ramona…>"
  },
  AvgDialog_19196_Content_11 = {
    Text = "Kedatangan orang hidup membawa panas yang berasal dari hidup. Dalam kegelapan, serangan rasa sakit yang tajam menyebar dari dahi ke seluruh anggota tubuh."
  },
  AvgDialog_19196_Content_12 = {
    Text = "Seseorang mengetuk dahi Anda dengan ujung jari."
  },
  AvgDialog_19196_Content_13 = {
    Text = "Aduh, sakit!"
  },
  AvgDialog_19196_Content_14 = {
    Text = "Masih bisa merasakan sakit, itu berarti kamu masih cukup sehat."
  },
  AvgDialog_19196_Content_15 = {
    Text = "Aku… baru saja mengingat semuanya."
  },
  AvgDialog_19196_Content_16 = {
    Text = "Ramona. Tulu. Kapten Elton. Celeste. Pelaut. Dan kamu dengan parasit itu…"
  },
  AvgDialog_19196_Content_17 = {
    Text = "Mengikatku bersama monster ini sudah cukup, apakah kamu bahkan tidak mau mengingatku sebelum Pelaut!"
  },
  AvgDialog_19196_Content_18 = {
    Text = "Saya... Saya sama sekali tidak bermaksud begitu..."
  },
  AvgDialog_19196_Content_19 = {
    Text = "Murphy mendengus dan menarikmu berdiri dari tanah."
  },
  AvgDialog_19196_Content_2 = {
    Text = "Realitas Reboot"
  },
  AvgDialog_19196_Content_20 = {
    Text = "Aku sudah bilang, setelah ledakan kamu berperilaku begitu aneh, ternyata benar-benar terbentur kepala ya…"
  },
  AvgDialog_19196_Content_21 = {
    Text = "Tapi ada satu hal yang masih belum aku pahami..."
  },
  AvgDialog_19196_Content_22 = {
    Text = "Siapa yang menyelamatkan semua orang dari lokasi ledakan saat Miryam memicu ledakan di Ruang Kekuatan?"
  },
  AvgDialog_19196_Content_23 = {
    Text = "Itu pasti Celeste, tidak ada orang lain di kapal ini yang bisa memancarkan cahaya putih seperti itu."
  },
  AvgDialog_19196_Content_24 = {
    Text = "Pelukan laut menjadi tajam, air laut bereaksi dengan kulit yang terbakar menghasilkan perjuangan yang menyesakkan. Kekacauan buta seperti hantu di malam hari, merobek dan mematahkan tubuhmu."
  },
  AvgDialog_19196_Content_25 = {
    Text = "Lalu, dari kekacauan itu muncul seberkas kehangatan. Di tengah kegelapan tanpa batas, kesendirian, ketidakberdayaan, dan kehancuran dengan cepat surut, memancarkan cahaya hangat yang misterius di alam semesta yang sangat dingin."
  },
  AvgDialog_19196_Content_26 = {
    Text = "Seolah menyentuh belas kasih alam semesta, kesadaran berjalan di tepi Gnosis. Tubuh secara bertahap menyatu dengan oksigen dalam air laut, lalu kamu tiba-tiba membuka mata, dan air laut mengalir ke tubuh melalui sudut matamu."
  },
  AvgDialog_19196_Content_27 = {
    Text = "Terakhir, cahaya lembut menembus kegelapan di dasar laut. Kekuatan biru pucat mengulurkan tangan padamu — seperti seorang Dewi yang melindungi perjalanan kapal, memberikan bantuan padamu."
  },
  AvgDialog_19196_Content_28 = {
    Text = "<Gray:Memang, kekuatan yang menarikku dari air tidak diragukan lagi milik Celeste.>"
  },
  AvgDialog_19196_Content_29 = {
    Text = "Kamu menutup mata sejenak, mengingat kembali saat api membakar kedua matamu. Hangatnya cahaya itu merobek dan menyatukan kembali tekadmu pada momen tersebut."
  },
  AvgDialog_19196_Content_3 = {
    Text = "Bangun, %player%, kau harus segera bangun."
  },
  AvgDialog_19196_Content_30 = {
    Text = "<Gray:Tapi kekuatan sebelum itu… pasti bukan Celeste. Terlalu asing, namun terlalu familiar…>"
  },
  AvgDialog_19196_Content_31 = {
    Text = "Apa lagi yang sedang kamu pikirkan? Apakah aku sudah merusakmu? Aku sudah berusaha mengendalikan kekuatanku ……"
  },
  AvgDialog_19196_Content_32 = {
    Text = "Murphy bergumam sambil berjingkat, lalu mengangkat tangan untuk menyingkap poni Anda. Ketika dia menjentikkan jari ke dahi, dia benar-benar mengendalikan kekuatannya—cukup membuat orang sadar, namun tidak sampai terasa sakit untuk waktu yang lama."
  },
  AvgDialog_19196_Content_33 = {
    Text = "Aku hanya khawatir tentang yang lainnya… Melihat dari keadaan saat kita berdua bertemu, situasi saat ledakan terjadi sangat mendesak. Celeste mungkin tidak bisa mengontrol titik jatuhnya semua orang dengan akurat."
  },
  AvgDialog_19196_Content_34 = {
    Text = "Harus segera menemukan Ramona, lalu bergabung dengan kapten dan yang lainnya."
  },
  AvgDialog_19196_Content_35 = {
    Text = "Apakah tubuhmu benar-benar sudah tidak apa-apa? Jika merasa tidak nyaman, kamu harus segera mengatakannya."
  },
  AvgDialog_19196_Content_36 = {
    Text = "Hmm, aku akan melakukannya."
  },
  AvgDialog_19196_Content_4 = {
    Text = "Jangan, jangan menakutiku... Jangan tidur, cepat bangun."
  },
  AvgDialog_19196_Content_5 = {
    Text = "Isak tangis seorang gadis terdengar jelas di gendang telinga, menarik kesadaranmu keluar dari aliran memori."
  },
  AvgDialog_19196_Content_7 = {
    Text = [[
Memori seperti slide, satu per satu dimasukkan ke dalam proyektor tua milikmu. 
 Setiap pergantian gambar, jiwamu mengirimkan jeritan tajam dari kedalaman.]]
  },
  AvgDialog_19196_Content_8 = {
    Text = "Umm… Raman… Nana…"
  },
  AvgDialog_19196_Content_9 = {
    Text = "Kamu ini..."
  },
  AvgDialog_19200_Content_1 = {
    Text = "Pertempuran hanya akan menarik lebih banyak musuh kepada kita. Selanjutnya, kita harus lebih berhati-hati dan menghindari konflik."
  },
  AvgDialog_19200_Content_10 = {
    Text = "Nah, kalau begini, kita sudah impas, kan?"
  },
  AvgDialog_19200_Content_11 = {
    Text = "Aku sudah mengendalikan kekuatanku, kalau tidak, kamu pasti sudah terpental sejauh 30 kaki olehku."
  },
  AvgDialog_19200_Content_12 = {
    Text = "Hah?! Dari mana kamu mendapatkan kekuatan sebesar itu? Jangan bercanda! Aku melihat semuanya saat Miryam menggantungmu."
  },
  AvgDialog_19200_Content_13 = {
    Text = "Atmosfer yang begitu berat hingga terasa kental tiba-tiba buyar, rasa gelisah dan sedih di matanya dengan cepat tertutupi oleh semangat kompetitif."
  },
  AvgDialog_19200_Content_14 = {
    Text = "Baik, Nyonya Murphy, baik, Tuan Murphy."
  },
  AvgDialog_19200_Content_15 = {
    Text = "Hei! Apakah kamu sengaja mengolok-olokku!"
  },
  AvgDialog_19200_Content_16 = {
    Text = "Murphy mengangkat tinjunya tinggi-tinggi, namun tiba-tiba melepaskan kekuatannya tepat sebelum mengenai tubuhmu. Akhirnya, tinjunya hanya menyentuh pakaianmu dengan lembut."
  },
  AvgDialog_19200_Content_17 = {
    Text = "Nona Besar, tolong ampuni saya, sangat sakit——"
  },
  AvgDialog_19200_Content_18 = {
    Text = "Tunggu, ada suara."
  },
  AvgDialog_19200_Content_19 = {
    Text = "Ujung telinga menangkap suara mendesis aneh yang samar, dan di tengah kekacauan suara tersebut, kamu mendengar ritme berpola yang sangat teratur."
  },
  AvgDialog_19200_Content_2 = {
    Text = "Murphy? Apakah kamu mendengarnya?"
  },
  AvgDialog_19200_Content_20 = {
    Text = "Ini Ramona."
  },
  AvgDialog_19200_Content_21 = {
    Text = "Bagaimana bisa kamu mendengarnya?!"
  },
  AvgDialog_19200_Content_22 = {
    Text = "Kamu dan Murphy saling bertatapan. Dia mengatupkan bibirnya dan mengangguk. Tanpa bicara, kalian berdua langsung berlari ke arah suara itu."
  },
  AvgDialog_19200_Content_23 = {
    Text = [[
Waktu hingga Selaras
tersisa: 90 menit]]
  },
  AvgDialog_19200_Content_3 = {
    Text = "Gadis itu masih berjongkok di samping karang, memikirkan sesuatu dengan ekspresi terpaku. Panggilanmu tidak berhasil menarik perhatiannya."
  },
  AvgDialog_19200_Content_4 = {
    Text = "Kamu juga berjongkok di sampingnya, melihat beberapa kali ke arah karang di ujung pandangannya, lalu memperhatikan matanya yang begitu terfokus hingga hampir kehilangan kesadaran."
  },
  AvgDialog_19200_Content_5 = {
    Text = "Entah karena muncul pikiran buruk untuk \"balas dendam\", atau hanya sekadar bermain-main lagi."
  },
  AvgDialog_19200_Content_6 = {
    Text = "Kamu menggosokkan tanganmu, lalu melengkungkan jari ke arah dahi Murphy ——"
  },
  AvgDialog_19200_Content_7 = {Text = "Aduh!"},
  AvgDialog_19200_Content_8 = {
    Text = "Apa yang kamu lakukan!"
  },
  AvgDialog_19200_Content_9 = {
    Text = "Murphy yang menutupi dahinya dengan tangan, berniat untuk memamerkan wibawa seorang putri kepadamu, tampaknya menyadari kesalahannya sendiri, lalu tiba-tiba menelan sisa kata-katanya kembali."
  },
  AvgDialog_19967_Content_1 = {
    Text = "Jujur, aku tidak tertarik untuk mem-bully anak kecil."
  },
  AvgDialog_19967_Content_2 = {
    Text = "Demi keadilan, saya memiliki beberapa <Yellow:koleksi berharga>, kamu bisa memilih salah satu dari koleksi tersebut."
  },
  AvgDialog_19967_Content_3 = {
    Text = "Mereka akan menghasilkan beberapa <Red:efek yang tidak terduga>, mau coba?"
  },
  AvgDialog_19967_Content_4 = {
    Text = "Maaf, sejak saya masih kecil, para senior telah memperingatkan saya untuk tidak sembarangan menerima barang dari orang asing."
  },
  AvgDialog_19967_Content_5 = {
    Text = "Begitu? Sungguh disayangkan... Hidupmu kehilangan banyak kesenangan sejak saat itu."
  },
  AvgDialog_19967_Content_6 = {
    Text = "Jika menolakku, kamu mungkin akan menghadapi hukuman yang berat, lho~"
  },
  AvgDialog_19968_Content_1 = {
    Text = "Bola lendir hitam berkilau dengan cahaya hijau yang aneh, bergerak liar ke segala arah di dalam gerbong, seolah-olah sedang mencari target."
  },
  AvgDialog_19968_Content_2 = {
    Text = "Kaca jendela pecah berderai menjadi fragmen-fragmen yang berkilauan dingin, mengeluarkan suara yang membuat orang merinding."
  },
  AvgDialog_19969_Content_10 = {
    Text = [[
Pengemudi segera menarik rem tangan, kereta bergetar hebat dan melambat. 
 Penumpang yang tidak mengetahui situasi tersebut buru-buru melompat dari kereta bawah tanah dan berlarian ke segala arah.]]
  },
  AvgDialog_19969_Content_11 = {
    Text = [[
Kondisi darurat, lindungi masyarakat! 
Boneka, Boneka, apakah kamu bisa mendengarku?]]
  },
  AvgDialog_19969_Content_12 = {
    Text = "Deteksi … gangguan komunikasi … fluktuasi Perak … diduga … zzzzrrr … Resonansi …"
  },
  AvgDialog_19969_Content_13 = {
    Text = [[
Ada pepatah yang bagaimana ya? Air jauh tak dapat memadamkan api dekat. 
 Sepertinya, sudah waktunya aku bertindak.]]
  },
  AvgDialog_19969_Content_2 = {
    Text = "Apa, apa itu?!"
  },
  AvgDialog_19969_Content_3 = {
    Text = "Di atas rel di ujung terowongan gelap, di area yang disinari cahaya, berdiri sosok yang seharusnya tidak mungkin ada."
  },
  AvgDialog_19969_Content_4 = {
    Text = "Wanita itu bertubuh tinggi, tatapannya tajam bagaikan mata pisau, dengan tenang menghadapi kereta yang datang menderu."
  },
  AvgDialog_19969_Content_5 = {
    Text = "Ketemu kamu."
  },
  AvgDialog_19969_Content_6 = {
    Text = "Hanya dalam sekejap, sosok wanita itu menghilang ——"
  },
  AvgDialog_19969_Content_8 = {
    Text = "Tidak, bukan menghilang, dia melakukan serangan ke arah kereta yang melaju kencang!"
  },
  AvgDialog_19970_Content_1 = {
    Text = [[
Monster dalam kegilaan mengeluarkan raungan kesakitan penuh kemarahan. 
 Api merah yang haus akan balas dendam meledakkan percikan terakhirnya, lalu padam dengan penuh ketidakrelaan.]]
  },
  AvgDialog_19970_Content_11 = {
    Text = [[
Monster hitam bergerak perlahan, menjerit, dan akhirnya jatuh lemas di sudut dinding yang hancur. 
 Dia berusaha keras untuk tetap membuka mata, kedua matanya yang kosong tampak melihat sedikit kekacauan yang mulai memudar.]]
  },
  AvgDialog_19970_Content_12 = {
    Text = [[
Di garis cakrawala yang jauh, terlihat sedikit cahaya langit.
Namun, itu sudah tidak ada hubungannya dengannya lagi.]]
  },
  AvgDialog_19970_Content_13 = {
    Text = "<Shake:Mengapa… menyerah… pada saya…>"
  },
  AvgDialog_19970_Content_14 = {
    Text = "Ini anak siapa lagi... Apakah kamu juga tidak bisa menemukan tuannya?"
  },
  AvgDialog_19970_Content_15 = {
    Text = "<Shake:Tolong... aku...>"
  },
  AvgDialog_19970_Content_16 = {
    Text = "Kamu terluka sangat parah."
  },
  AvgDialog_19970_Content_17 = {
    Text = [[
Maaf, aku tidak bisa menjadi tuanmu. 
 Aku sudah memiliki Lily.]]
  },
  AvgDialog_19970_Content_18 = {Text = "Namun..."},
  AvgDialog_19970_Content_19 = {
    Text = "<Yellow: Jika hanya membutuhkan Tautan, di sini ada banyak, lho?>"
  },
  AvgDialog_19970_Content_2 = {
    Text = "Ramona mengangkat pedang tipisnya, bersiap untuk memberikan perpisahan terakhir kepada monster yang dulunya dikenal sebagai Helot."
  },
  AvgDialog_19970_Content_4 = {Text = "Rotan?!"},
  AvgDialog_19970_Content_5 = {
    Text = "Pedang Lotan menghalangi pedang tipis yang akan menyerang ke bawah."
  },
  AvgDialog_19970_Content_6 = {
    Text = [[
Biarkan dia menghadapi nasibnya sendiri. 
Pembangun yang kehilangan Tautan, dalam waktu kurang dari 24 jam akan menghilang dari dunia ini.]]
  },
  AvgDialog_19970_Content_7 = {
    Text = "Melihat negaranya, sepertinya dia tidak akan bertahan sampai pagi."
  },
  AvgDialog_19970_Content_8 = {
    Text = [[
Dia sudah tidak dapat melukai siapa pun lagi. 
 Biarkan dia menghadapi ajalnya dengan damai.]]
  },
  AvgDialog_19971_Content_1 = {
    Text = "Apakah suara itu sedang mengatakan sesuatu?"
  },
  AvgDialog_19971_Content_2 = {
    Text = "Sepertinya \"Hei... menyerah...\""
  },
  AvgDialog_19971_Content_3 = {
    Text = "Monster seperti itu muncul di dekat sanatorium..."
  },
  AvgDialog_19971_Content_4 = {
    Text = "Francis mungkin menyimpan lebih banyak rahasia daripada yang kita bayangkan."
  },
  AvgDialog_19971_Content_5 = {
    Text = "Bagaimanapun, aku hanya bisa melewati jembatan ini terlebih dahulu dan melihat situasinya nanti."
  },
  AvgDialog_19972_Content_1 = {
    Text = "Kalian melintasi dimensi, suara tetesan air melewati tangkapan daun telinga dan getaran gendang telinga, langsung bergema di dalam pikiran."
  },
  AvgDialog_19972_Content_2 = {
    Text = "Rasa kekacauan di dada bergelora, membesar, dan hampir meledak."
  },
  AvgDialog_19972_Content_3 = {
    Text = "Tanpa sadar, kamu sudah menahan napas."
  },
  AvgDialog_19973_Content_10 = {
    Text = "Kamu bukan bagian dari Para pematung. Mengapa kamu membantu mereka?"
  },
  AvgDialog_19973_Content_11 = {
    Text = "Oh? Bagaimana kamu tahu aku bukan?"
  },
  AvgDialog_19973_Content_12 = {
    Text = "Geng \"seniman\" yang memegang pahat itu, tidak sebesar hati seperti yang kamu lakukan sekarang."
  },
  AvgDialog_19973_Content_13 = {
    Text = "Siapa kamu? Mengapa membawa anak ini?"
  },
  AvgDialog_19973_Content_14 = {
    Text = [[
<Blue:Helot>. Jika kamu bertanya tentang identitas, aku bisa dianggap sebagai kakak dari anak itu.
Lebih tepatnya, kekuatan kami adalah <Yellow:"Kekuatan yang berasal dari sumber yang sama">.]]
  },
  AvgDialog_19973_Content_15 = {
    Text = "Dia perlu kembali ke sisi \"<Yellow:Pemilik>\", jadi aku datang untuk membawanya pergi."
  },
  AvgDialog_19973_Content_16 = {
    Text = "Ramona mengangguk, lalu berbalik dan mengelus kepala Lily."
  },
  AvgDialog_19973_Content_17 = {
    Text = "Lily, apakah kamu ingin pergi dengannya?"
  },
  AvgDialog_19973_Content_18 = {
    Text = "Lily dengan rasa takut mengangkat kepalanya, pandangannya bergerak di antara Helot dan Ramona, lalu menatapmu dengan tatapan penuh permohonan bantuan."
  },
  AvgDialog_19973_Content_19 = {Text = "Dorong dia"},
  AvgDialog_19973_Content_2 = {
    Text = "Duri tajam datang seperti angin kencang yang membelah udara, langsung mengarah ke arahmu yang sedang digandeng oleh Lily."
  },
  AvgDialog_19973_Content_20 = {
    Text = "Tidak apa-apa, katakan saja apa yang sebenarnya kamu pikirkan."
  },
  AvgDialog_19973_Content_21 = {
    Text = [[
Tangan Lily menegang. 
 Lalu, dia dengan perlahan namun tegas menggelengkan kepalanya.]]
  },
  AvgDialog_19973_Content_22 = {
    Text = "Apakah kamu melihatnya? Dia tidak mau kembali untuk bertemu dengan \"tuan\" itu."
  },
  AvgDialog_19973_Content_23 = {
    Text = "Helot mengangkat tangannya, aliran udara yang sangat kuat entah dari mana mulai berkumpul di sekitar tubuhnya, membentuk badai yang siap meletus."
  },
  AvgDialog_19973_Content_24 = {
    Text = "Mengenai hal ini, dia tidak memiliki hak untuk memutuskan."
  },
  AvgDialog_19973_Content_25 = {
    Text = "Kalau begitu, coba saja!"
  },
  AvgDialog_19973_Content_4 = {
    Text = "Sebelum kamu bersiap untuk memanggil Ramona, suara benturan antar bilah pedang yang nyaring sudah terdengar."
  },
  AvgDialog_19973_Content_5 = {
    Text = [[
Lotan berdiri dengan gagah di hadapanmu, tanpa rasa takut menghadapi musuh yang datang. 
 Sehelai rambut jatuh dari dahinya.]]
  },
  AvgDialog_19973_Content_6 = {
    Text = "Hm, lumayan juga."
  },
  AvgDialog_19973_Content_7 = {
    Text = "Tujuan saya bukan kamu. Minggir."
  },
  AvgDialog_19973_Content_8 = {
    Text = "Tidak bisa begitu. Sudah lama aku tidak melatih tubuhku, jadi seharusnya kau menemaniku berlatih, kan?"
  },
  AvgDialog_19974_Content_2 = {
    Text = "Sosok berjubah hitam yang aneh menghilang di ujung pandangan, kalian berusaha mengejarnya namun tetap kehilangan jejak."
  },
  AvgDialog_19974_Content_3 = {
    Text = "Orang-orang ini adalah..."
  },
  AvgDialog_19974_Content_4 = {
    Text = "Boneka juga sedang melacak asal-usul mereka, hingga saat ini belum ada kesimpulan yang dapat diandalkan."
  },
  AvgDialog_19974_Content_5 = {
    Text = "Mereka ini cukup menarik juga, tampaknya sesekali keluar untuk bermain rumah-rumahan dengan anak kecil juga tidak buruk."
  },
  AvgDialog_19974_Content_6 = {
    Text = "Rumah, di seberang <Blue:Follers Steel Bridge>."
  },
  AvgDialog_19974_Content_7 = {Text = "Ayo pergi."},
  AvgDialog_19975_Content_1 = {
    Text = "Monster-monster ini adalah mereka yang secara kebetulan jatuh ke dalam Lorong Dimensi, tentu saja ada juga produk dari Pelarutan yang terkikis."
  },
  AvgDialog_19975_Content_2 = {
    Text = "Melakukan perjalanan Dimensi secara sembarangan seperti menyelam ke dasar Aequor sedalam sepuluh ribu meter tanpa perlindungan, atau hanya mengenakan kemeja saat mendaki puncak Elworth yang dilanda badai salju."
  },
  AvgDialog_19975_Content_3 = {
    Text = "Perlu diingat, mayoritas orang sulit menanggung beban perjalanan Dimensi."
  },
  AvgDialog_19975_Content_4 = {
    Text = "Wanita Narsis tidak membuat jebakan, melainkan memilih jalur ini yang tekanannya masih bisa ditanggung ——"
  },
  AvgDialog_19975_Content_5 = {
    Text = "Apakah dia... mengundang kita?"
  },
  AvgDialog_19975_Content_6 = {
    Text = [[
Di depan adalah pintu keluar, kita segera bisa bertemu dengan Wanita Narsis lagi.
Saat itu, kita bisa bertanya dengan jelas.]]
  },
  AvgDialog_19976_Content_1 = {
    Text = [[
Itu datang. 
Anjing neraka yang telah kalian tunggu-tunggu perlahan membuka murid berwarna merah keemasan di belakang kalian.]]
  },
  AvgDialog_19976_Content_2 = {
    Text = [[
Pandangan itu datang dari ketinggian yang jauh tak terjangkau. 
 Tatapan penuh ancaman itu tajam menusuk kalian, seperti mata pisaunya yang tajam menembus ruang.]]
  },
  AvgDialog_19976_Content_3 = {
    Text = "Kalian tidak dapat melawan, hanya bisa melarikan diri."
  },
  AvgDialog_19977_Content_1 = {
    Text = "Desa kecil di malam bersalju begitu sunyi, salju tebal yang mengembang memantulkan cahaya bulan yang dingin."
  },
  AvgDialog_19977_Content_10 = {Text = "Sekarang!"},
  AvgDialog_19977_Content_11 = {
    Text = "Makhluk hitam yang mirip bayangan gelap tanpa bentuk itu tampaknya terkejut, berbalik dan melarikan diri dengan panik, namun terjerat oleh jebakan, tidak bisa bergerak."
  },
  AvgDialog_19977_Content_12 = {
    Text = "Monster menundukkan kepalanya dan mengeluarkan geraman rendah ke arahmu, seolah-olah mencoba mengintimidasi agar kamu tidak mendekat lebih jauh."
  },
  AvgDialog_19977_Content_13 = {
    Text = "Orang ini... apakah kalian bisa melihatnya dengan jelas?"
  },
  AvgDialog_19977_Content_14 = {
    Text = "Tidak, sepertinya... tidak punya wajah."
  },
  AvgDialog_19977_Content_15 = {
    Text = "Di tengah kepala monster yang tertunduk, samar-samar terlihat kontur yang menyerupai wajah manusia. Namun, di tempat yang seharusnya menjadi posisi lima indera, seperti lubang hitam, semua cahaya diserap habis."
  },
  AvgDialog_19977_Content_16 = {
    Text = "Kendalikan dia, Lotan! Aku di sebelah kiri, kamu di sebelah kanan!"
  },
  AvgDialog_19977_Content_17 = {
    Text = "Mudah sekali!"
  },
  AvgDialog_19977_Content_2 = {
    Text = "Tiga orang berjongkok di balik pagar yang rusak, menyembunyikan diri dalam kegelapan malam yang pekat sambil sesekali menoleh ke belakang."
  },
  AvgDialog_19977_Content_3 = {
    Text = "Hei, apakah penyergapan seperti ini benar-benar berguna? Hanya dengan beberapa anak ayam ini?"
  },
  AvgDialog_19977_Content_4 = {
    Text = "Kita lihat saja dulu. Cobalah bertahan, jangan terburu-buru keluar."
  },
  AvgDialog_19977_Content_5 = {
    Text = "Hmph, membuang-buang waktuku."
  },
  AvgDialog_19977_Content_6 = {
    Text = "Ssst, ada sesuatu yang mendekat."
  },
  AvgDialog_19977_Content_7 = {
    Text = "Dari dalam bayangan muncul cakar hewan dari keluarga anjing, disertai dengan suara napas yang berat."
  },
  AvgDialog_19977_Content_8 = {
    Text = "Satu langkah, dua langkah."
  },
  AvgDialog_19977_Content_9 = {
    Text = "Itu menerjang maju, langkahnya bagaikan guntur."
  },
  AvgDialog_19978_Content_10 = {
    Text = "Sedangkan laporan pertama tentang Anjing neraka muncul <Blue:sepuluh hari> yang lalu, sepuluh hari untuk memahami jalan-jalan kecil yang rumit ini bukanlah hal yang mudah."
  },
  AvgDialog_19978_Content_11 = {
    Text = "Apa sekarang?"
  },
  AvgDialog_19978_Content_12 = {
    Text = "Ramona berbalik. Kamu mengikuti pandangannya, dan sepanjang jalur yang dilaluinya, terdapat cairan berwarna hitam dan merah yang tersebar secara sporadis."
  },
  AvgDialog_19978_Content_13 = {
    Text = "Kehilangan darah biasanya disertai dengan kehilangan stamina — itu pasti akan keluar lagi untuk mencari makan, kita hanya perlu bersiap."
  },
  AvgDialog_19978_Content_14 = {
    Text = "Lotan mengayunkan pedangnya dengan ekspresi penuh kesombongan."
  },
  AvgDialog_19978_Content_15 = {
    Text = "Itu lebih baik. Selama masih hidup, bisa ditangkap, bisa dibunuh… \n Bertemu denganku, mungkin lebih bahagia mati lebih awal daripada hidup."
  },
  AvgDialog_19978_Content_16 = {
    Text = "Ayo, berusaha menyelesaikan persiapan sebelum hari gelap."
  },
  AvgDialog_19978_Content_2 = {
    Text = "……………"
  },
  AvgDialog_19978_Content_3 = {
    Text = "Kalian mengejar monster hitam melewati beberapa persimpangan, namun kehilangan jejaknya setelah keluar dari sebuah gang kecil."
  },
  AvgDialog_19978_Content_4 = {
    Text = "Sial, lari ke mana lagi? Orang ini benar-benar licin, seperti tikus di selokan!"
  },
  AvgDialog_19978_Content_5 = {
    Text = "Seharusnya ini adalah jalan buntu, seharusnya tidak bisa melarikan diri dengan sukses, kecuali ——"
  },
  AvgDialog_19978_Content_6 = {
    Text = "Ada yang menyambut? Atau mungkin... menghilang?! Lotan, waspada!"
  },
  AvgDialog_19978_Content_8 = {
    Text = "...Keduanya merupakan perkembangan yang sangat dramatis. Sayangnya, alasan sebenarnya mungkin jauh lebih sederhana — di gang ini, kemungkinan besar terdapat <Blue:jalan rahasia atau cabang> yang tidak ada di peta standar."
  },
  AvgDialog_19978_Content_9 = {
    Text = "Kota kecil ini sudah ada sebelum banjir besar, dengan industri peternakan dan keramik yang sangat berkembang. Berbagai saluran pembuangan dan lorong-lorong di dalam kota membentuk jaringan yang kompleks, sehingga mustahil untuk memahami keseluruhan tata letak hanya dengan peta."
  },
  AvgDialog_19979_Content_1 = {
    Text = "Tidak mau mendongak, tak bisa kembali."
  },
  AvgDialog_19979_Content_2 = {
    Text = "Bahkan bayangan yang mungkin terpantul di tanah saat kamu menunduk membuat hatimu gemetar."
  },
  AvgDialog_19979_Content_3 = {
    Text = "Di dalam dimensi yang suram ini, kalian bahkan tidak memiliki kemampuan untuk melawan."
  },
  AvgDialog_19980_Content_10 = {
    Text = "Sungguh kasihan, hanya karena kehilangan link Silver Core, sudah merosot menjadi seperti ini."
  },
  AvgDialog_19980_Content_11 = {
    Text = "Monster bernanah mengabaikan ejekan Lotan, hanya menerjang maju ke arah musuh dengan raungan."
  },
  AvgDialog_19980_Content_12 = {
    Text = "<Change>Letakkan dia…… kepada…… saya……"
  },
  AvgDialog_19980_Content_13 = {
    Text = "Asalkan bisa menangkap gadis itu... asalkan bisa menjadi Kembar Suci bersamanya..."
  },
  AvgDialog_19980_Content_14 = {
    Text = "Dia tidak akan ditinggalkan, tak perlu meratapi asal-usulnya, dan takkan menjadi pion yang diperintah seenaknya."
  },
  AvgDialog_19980_Content_17 = {
    Text = "<Change>Serahkan… dia… padaku!"
  },
  AvgDialog_19980_Content_18 = {
    Text = "Bahkan kemampuan berkomunikasi pun sudah hilang?"
  },
  AvgDialog_19980_Content_19 = {
    Text = [[
Jika demikian, sampaikanlah kata-katamu, curahkan perasaanmu melalui pedangmu! 
 Mari, tunjukkan padaku amarahmu!]]
  },
  AvgDialog_19980_Content_2 = {
    Text = "<BigShake:Raung——>"
  },
  AvgDialog_19980_Content_3 = {
    Text = "Tidak lama setelah kalian berjalan dalam kegelapan, seekor monster lengket merayap keluar dari bawah jembatan. Tubuh besarnya menyeret tak terhitung bola-bola lengket dan tiba-tiba jatuh tepat di depan kalian."
  },
  AvgDialog_19980_Content_4 = {
    Text = "Monster itu mengangkat tubuh bagian atasnya yang masih samar-samar berbentuk manusia, memandang kalian satu putaran, lalu pandangannya tertuju pada Lily. Ekspresinya secara bertahap menjadi kegilaan."
  },
  AvgDialog_19980_Content_6 = {
    Text = "Serahkan dia…… kepadaku!"
  },
  AvgDialog_19980_Content_7 = {
    Text = "Lotan melangkah maju untuk menghalangi kalian, dengan gagah menatap monster itu."
  },
  AvgDialog_19980_Content_8 = {
    Text = "Borgol terpecah menjadi empat bagian, anggota tubuh membengkak dan berubah bentuk. Hanya wajah kotor di bawah rambut panjang yang kusut seperti rerumputan yang masih membuktikan identitas pemilik tubuh tersebut."
  },
  AvgDialog_19980_Content_9 = {
    Text = "Kamu adalah... Helot..."
  },
  AvgDialog_19981_Content_1 = {
    Text = "Bayangan secepat angin semakin mendekati kalian, firasat akan pertempuran besar mulai menyelimuti seluruh gerbong."
  },
  AvgDialog_19981_Content_2 = {
    Text = "Lotan meletakkan tangan di gagang pedangnya, siap untuk menghadapi pertempuran."
  },
  AvgDialog_19981_Content_3 = {
    Text = "Lily, apakah kamu mengenalnya?"
  },
  AvgDialog_19981_Content_4 = {
    Text = "Lily erat memegang ujung bajumu, mundur setengah langkah, lalu menggelengkan kepala dan mengangguk."
  },
  AvgDialog_19981_Content_5 = {
    Text = "Lily tahu... dia datang untuk mencari Lily."
  },
  AvgDialog_19982_Content_1 = {
    Text = "Saya punya firasat buruk… Kali ini sepertinya akan kehilangan jejak."
  },
  AvgDialog_19982_Content_2 = {
    Text = "Dalam permainan petak umpet, Lotan bukan tandingan anjing neraka yang muncul dan menghilang secara misterius."
  },
  AvgDialog_19983_Content_1 = {
    Text = "Lotan! Berhenti sejenak! Terus mengejar seperti ini bukanlah solusi."
  },
  AvgDialog_19983_Content_2 = {
    Text = "Apa? Apakah kamu punya rencana yang cemerlang?"
  },
  AvgDialog_19983_Content_3 = {
    Text = "Kita terbagi menjadi tiga kelompok, bekerja sama untuk mengepungnya ke dalam gang di depan!"
  },
  AvgDialog_19984_Content_1 = {
    Text = "Tertangkap!"
  },
  AvgDialog_19984_Content_10 = {
    Text = "Makhluk raksasa dengan penampilan aneh saat ini menundukkan kepalanya dengan patuh, seolah-olah mengharapkan belaian dari gadis berpakaian putih."
  },
  AvgDialog_19984_Content_11 = {
    Text = "Di atas leher tubuh raksasa anjing itu tampak jelas sebuah kepala manusia yang memakai mahkota, membuat adegan ini menjadi sangat aneh."
  },
  AvgDialog_19984_Content_12 = {Text = "Lily…"},
  AvgDialog_19984_Content_13 = {
    Text = "Gadis berpakaian putih perlahan mendekati makhluk raksasa dengan penampilan aneh, mengulurkan lengan rampingnya, dan membelai kepalanya seperti membelai hewan peliharaan biasa."
  },
  AvgDialog_19984_Content_14 = {
    Text = "Di atas leher tubuh raksasa anjing itu terlihat jelas sebuah kepala manusia yang memakai mahkota, membuat adegan ini menjadi sangat aneh."
  },
  AvgDialog_19984_Content_16 = {
    Text = "Kamu dan Ramona saling berpandangan, ribuan kata tersimpan di dalam dada, namun sesaat tidak tahu bagaimana cara memulai."
  },
  AvgDialog_19984_Content_17 = {
    Text = "Hei, kalian tidak hanya akan berdiri di sana, kan? Anjing neraka sudah ada di depan mata."
  },
  AvgDialog_19984_Content_18 = {
    Text = "Dalang utama acara ini ada di sekitar, bagaimana harus mengatakannya? \"Mendapatkan tanpa susah payah\"?"
  },
  AvgDialog_19984_Content_19 = {
    Text = "Gadis itu seolah-olah tidak mendengarnya, berbisik di dekat telinga Kum. Angin malam yang lembut membawa suara halus itu ke dalam gendang telinga."
  },
  AvgDialog_19984_Content_2 = {
    Text = "Ramona melompat maju, monster yang terdesak menggeram dengan ganas, dengan niat melakukan perlawanan terakhir."
  },
  AvgDialog_19984_Content_20 = {
    Text = [[
Kum, jadi anak baik dan dengarkan perintah tuan.
Anak yang patuh adalah anak yang baik.]]
  },
  AvgDialog_19984_Content_21 = {
    Text = "Suara itu perlahan terdengar, Lily berputar dan berjalan mendekati kalian."
  },
  AvgDialog_19984_Content_22 = {
    Text = "Wanita Narsis berkata, jika Kuum ditemukan oleh seseorang, Lily harus kembali ke sisi <Blue:ibu>."
  },
  AvgDialog_19984_Content_23 = {
    Text = "Kembali ke toko dulu. Wanita Narsis, mungkin ada sesuatu untuk dikatakan."
  },
  AvgDialog_19984_Content_24 = {
    Text = [[
Sepanjang jalan tidak ada bicara apa-apa. 
 Narsis memegang pipa rokok, duduk santai di kursi kayu yang tinggi, seolah-olah sudah menunggu kedatanganmu.]]
  },
  AvgDialog_19984_Content_25 = {
    Text = [[
Sudah kubilang, anjing besar tidak bisa bersembunyi di antara keramaian. 
Lily, <Yellow:hukuman> yang telah kita sepakati, kau belum lupa kan?]]
  },
  AvgDialog_19984_Content_26 = {
    Text = "Hmm, Lily tahu."
  },
  AvgDialog_19984_Content_27 = {
    Text = "Jangan berbicara dalam teka-teki lagi. Katakan yang sebenarnya! Apa yang terjadi dengan Anjing neraka ini?"
  },
  AvgDialog_19984_Content_28 = {
    Text = [[
Tenang saja, para tamu. 
Aku akan menjelaskan semuanya nanti.]]
  },
  AvgDialog_19984_Content_29 = {
    Text = "Atau kalian ingin membawa Kuum kembali untuk menyelesaikan tugas, dan dengan begitu kasus ini dianggap selesai?"
  },
  AvgDialog_19984_Content_3 = {
    Text = "<Italic:Jangan, jangan, Kumu, kembali!>"
  },
  AvgDialog_19984_Content_30 = {
    Text = "Khum bukan Anjing neraka yang sebenarnya."
  },
  AvgDialog_19984_Content_31 = {
    Text = "Narsis menampilkan senyuman penuh penghargaan."
  },
  AvgDialog_19984_Content_32 = {
    Text = "Benar-benar menarik. Apa spekulasi Anda?"
  },
  AvgDialog_19984_Content_33 = {
    Text = "Di Kota Rai terdapat tiga Acara mendadak: <Yellow:Serangan terhadap ternak>, <Yellow:Hilangnya Lisa>, dan <Yellow:Rumor Anjing neraka>."
  },
  AvgDialog_19984_Content_34 = {
    Text = "Hewan ternak yang tercabik-cabik tampaknya diserang oleh binatang buas... tetapi sebenarnya, yang tersisa di tubuh mereka adalah <Yellow:bekas gigitan manusia>."
  },
  AvgDialog_19984_Content_35 = {
    Text = "Sekarang, kita sudah menangkap Kuum. Cukup membandingkan bekas gigitan, dan saya yakin kesimpulan akan segera diperoleh — \n<Yellow:Dialah pelaku serangan terhadap ternak>."
  },
  AvgDialog_19984_Content_36 = {
    Text = [[
Namun <Yellow:Anjing neraka tidak ada hubungannya dengan itu>. 
 Tidak ada rasa penindasan pada Kum... tidak ada kejahatan yang melintasi dimensi.]]
  },
  AvgDialog_19984_Content_37 = {
    Text = "Senapan para penduduk desa dapat meninggalkan luka yang sulit sembuh di tubuhnya, dan Lotan juga mampu mengalahkannya sendirian. Kekuatannya tidak cukup untuk menjadi ancaman yang menutupi kota."
  },
  AvgDialog_19984_Content_38 = {
    Text = "Jadi, saya menyimpulkan bahwa <Yellow:di kota kecil ini terdapat dua anjing neraka>."
  },
  AvgDialog_19984_Content_39 = {
    Text = "Tebakan yang menarik, apakah ada lagi?"
  },
  AvgDialog_19984_Content_4 = {
    Text = "Suara ini... sepertinya pernah kudengar di suatu tempat?"
  },
  AvgDialog_19984_Content_40 = {
    Text = "Bekas gigitan manusia pada unggas, ditambah dengan aktivitas Para Pematung di wilayah ini... Saya menduga bahwa Kuum adalah hasil modifikasi dari Para Pematung."
  },
  AvgDialog_19984_Content_41 = {
    Text = "Pertanyaan yang tersisa adalah: siapakah korban dari tragedi ini?"
  },
  AvgDialog_19984_Content_42 = {
    Text = "Dalam proses pengejaran terhadap Kum, kami menemukan bahwa ia memiliki kecerdasan tertentu dan sangat memahami jalan-jalan rumit di Rai, yang menunjukkan bahwa… ketika masih menjadi manusia, mungkin ia pernah tinggal di Rai untuk waktu yang lama."
  },
  AvgDialog_19984_Content_43 = {
    Text = "Rumah Lisa terletak di tengah kota. Bagi binatang buas atau pencuri, memilih target yang berdekatan dengan hutan adalah pilihan yang lebih alami — jadi, pasti ada alasan \"kenapa harus makan di sini.\""
  },
  AvgDialog_19984_Content_44 = {
    Text = "Dan pada titik ini, saya mengambil risiko. Saya bertaruh bahwa alasan \"Anjing neraka\" memilih rumah Lisa adalah karena tempat itu memiliki arti khusus bagi mereka."
  },
  AvgDialog_19984_Content_45 = {
    Text = "Oleh karena itu, kami meletakkan umpan di depan rumah Lisa, dan tebakan saya ternyata benar."
  },
  AvgDialog_19984_Content_46 = {
    Text = "Mengingat apa yang dikatakan Lily, \"Lisa tidak mau kembali lagi\", saya curiga Lisa sudah tidak bisa menghadapi ibunya sendiri karena suatu alasan — mungkin sudah di<Red:modifikasi> sampai tidak dikenali lagi."
  },
  AvgDialog_19984_Content_47 = {
    Text = "Jika semua ini digabungkan, identitas sebenarnya dari \"Anjing neraka\" di depan mata ini pun mulai terungkap——\n<Yellow:Khum, alias Lisa>."
  },
  AvgDialog_19984_Content_48 = {
    Text = "Untuk memverifikasi dugaan ini, saya meletakkan umpan di depan rumah Lisa dan berhasil \"menangkap\"-nya."
  },
  AvgDialog_19984_Content_49 = {
    Text = [[
Khum yang berbaring di samping mengeluarkan suara tangisan rendah. 
 Lily membelai kepala Khum... lalu kepala Lisa, sepertinya untuk menenangkan mereka.]]
  },
  AvgDialog_19984_Content_5 = {
    Text = "Dari bayangan lampu yang gelap, muncul sosok kecil yang menyusut."
  },
  AvgDialog_19984_Content_50 = {
    Text = "Lisa adalah anak yang baik. Bahkan saat dia sangat lapar, dia hanya mau pulang untuk \"makan\"."
  },
  AvgDialog_19984_Content_51 = {
    Text = "Kamu sangat cerdas, gadis kecil. Tak heran Profesor Dexter memuji murid berprestasi sepertimu dengan penuh antusias."
  },
  AvgDialog_19984_Content_52 = {
    Text = "Terima kasih atas pujian Anda. Profesor Dexter juga telah menceritakan kepada saya tentang \"prestasi luar biasa\" Anda, Nyonya."
  },
  AvgDialog_19984_Content_53 = {
    Text = "Semua itu adalah transaksi bisnis yang normal, tidak ada yang layak disebutkan."
  },
  AvgDialog_19984_Content_54 = {
    Text = "Tebakanmu sangat akurat, Kum adalah \"Lisa\", dan faksi yang melakukan modifikasi kejam ini terhadapnya sudah merupakan kenalan lama kalian."
  },
  AvgDialog_19984_Content_55 = {
    Text = "Aku sama sekali tidak ingin memiliki kenalan lama seperti ini."
  },
  AvgDialog_19984_Content_56 = {
    Text = "Meskipun Anda tidak menyebutnya, bekas jahitan ini juga kemungkinan besar mengarah pada Para Pematung."
  },
  AvgDialog_19984_Content_57 = {
    Text = "……ini adalah Para pematung"
  },
  AvgDialog_19984_Content_58 = {
    Text = "Kelompok orang gila yang menyebut diri mereka \"<Yellow:Pygmalion>\" terus-menerus mengganggu seperti lalat yang berdengung. Mereka benar-benar menjengkelkan."
  },
  AvgDialog_19984_Content_59 = {
    Text = [[
Evaluasi yang tepat. Berikut ini adalah poin pentingnya. 
 Saya yakin dengan jaringan informasi kalian, pasti sudah mendeteksi aktivitas yang tidak biasa dari Para Pematung akhir-akhir ini.]]
  },
  AvgDialog_19984_Content_6 = {
    Text = "Khum, tidak boleh memberikan Kerusakan kepada Kakak laki-laki, Kakak perempuan ya."
  },
  AvgDialog_19984_Content_60 = {
    Text = "Mereka begitu gelisah karena ketua mereka, Herbert, baru-baru ini mendapatkan <Red:dokumen rahasia mutlak>."
  },
  AvgDialog_19984_Content_61 = {
    Text = "Saya tidak bisa mengungkapkan isi materi tersebut, satu-satunya yang bisa dipastikan adalah materi itu membakar fantasi paling kegilaan di dalam diri Herbert."
  },
  AvgDialog_19984_Content_62 = {
    Text = "Saat ini, dia sedang melakukan segala cara untuk melanjutkan eksperimen."
  },
  AvgDialog_19984_Content_63 = {
    Text = "Apa tujuannya?"
  },
  AvgDialog_19984_Content_64 = {
    Text = [[
Bagian yang bisa diungkapkan sampai di sini saja. 
Lagipula, kalian juga bukan <Yellow:satu-satunya pelanggan> saya, kan?]]
  },
  AvgDialog_19984_Content_65 = {
    Text = "Narsis menepuk pipa rokoknya dan menyeringai dengan senyum yang penuh tipu daya."
  },
  AvgDialog_19984_Content_66 = {
    Text = "Kalau begitu, izinkan saya mengajukan dua pertanyaan lagi dengan hormat."
  },
  AvgDialog_19984_Content_67 = {
    Text = "Tentang \"Anjing neraka\" lainnya... berapa banyak informasi yang Anda kuasai?"
  },
  AvgDialog_19984_Content_68 = {
    Text = "Atau mungkin Anda juga belum lama berada di kota ini dan tidak mengetahui rahasia di dalamnya?"
  },
  AvgDialog_19984_Content_69 = {
    Text = "Astaga, bahkan ini juga ketahuan?"
  },
  AvgDialog_19984_Content_7 = {
    Text = "Anjing besar yang disebut \"Khum\" duduk di tanah dan dengan patuh menjilati cakarnya."
  },
  AvgDialog_19984_Content_70 = {
    Text = "Meskipun aku tidak bisa menjelaskan secara rinci asal-usul Anjing neraka itu kepadamu, aku juga bukan sama sekali tidak tahu."
  },
  AvgDialog_19984_Content_71 = {
    Text = "Namun, di toko pertukaran ini, tidak ada jawaban yang gratis."
  },
  AvgDialog_19984_Content_72 = {
    Text = "Apa yang Anda inginkan?"
  },
  AvgDialog_19984_Content_73 = {
    Text = "Hmm, coba kuingat-ingat..."
  },
  AvgDialog_19984_Content_74 = {
    Text = "Pandangan Narsis menyapu ke arahmu, Ramona, dan Lotan, lalu berhenti pada Lily di samping."
  },
  AvgDialog_19984_Content_75 = {
    Text = "Kemudian, dia menyeringai dengan senyuman yang maknanya sulit dipahami."
  },
  AvgDialog_19984_Content_76 = {
    Text = "Melihat pertunjukan luar biasa yang kau tunjukkan padaku tadi, aku akan memberikan diskon yang sangat menarik."
  },
  AvgDialog_19984_Content_77 = {
    Text = "Ayo, \"jawaban\" dan \"harga\" kalian... sudah tiba."
  },
  AvgDialog_19984_Content_8 = {Text = "Khum..."},
  AvgDialog_19984_Content_9 = {
    Text = "Pada saat itulah kamu baru menyadari bahwa wajah hitam pekat itu sebenarnya bukan tanpa fitur wajah. Hanya saja, mata yang tertutup, lubang hidung yang datar, serta bibir yang hampir tak terlihat semuanya berwarna hitam pekat, menciptakan ilusi wajah tanpa raut."
  },
  AvgDialog_20082_Content_1 = {
    Text = "Hah……ada apa ini……tingkat kesulitan pendakian meningkat drastis dibanding sebelumnya, belum pernah se……sesulit ini!"
  },
  AvgDialog_20082_Content_2 = {
    Text = "Gunung salju mulai terbangun, medan terus berubah setiap saat. Pegang tanganku——"
  },
  AvgDialog_20082_Content_3 = {
    Text = "Kamu menggenggam tangan Shilo, berjuang keras memanjat keluar dari celah batu, namun melihat Lily membentangkan tangannya ke arahmu."
  },
  AvgDialog_20082_Content_4 = {
    Text = "Lily, sakit……mau digendong, sebentar saja."
  },
  AvgDialog_20082_Content_5 = {
    Text = "Kamu menggendongnya sesuai permintaan. Sepanjang perjalanan Lily selalu bersikap penurut dan baik, tapi sekarang kondisinya tampak tidak baik-baik saja……"
  },
  AvgDialog_20082_Content_6 = {
    Text = "Lily, bertahanlah sebentar lagi, sebentar saja……"
  },
  AvgDialog_20082_Content_7 = {
    Text = "Di atas batu hitam pekat di tanah masih tersisa sedikit salju. Kamu menghentak-hentakkan kaki dan menyadari permukaan tanah menjadi agak lengket."
  },
  AvgDialog_20082_Content_8 = {
    Text = "Dia melunakkan badan gunung untuk memperlambat langkah kita……tidak akan kubiarkan berhasil!"
  },
  AvgDialog_20233_Content_1 = {
    Text = "Apakah kamu memperhatikan? Kelemahannya adalah \"orang mati\"di belakangnya."
  },
  AvgDialog_20233_Content_2 = {
    Text = "Aku akan memberimu sebuah \"Hadiah kecil\"."
  },
  AvgDialog_20475_Content_1 = {
    Text = "Akhirnya……bertemu denganmu."
  },
  AvgDialog_20475_Content_10 = {
    Text = "Gunung salju sudah mulai menelan kalian……harus segera mengalahkan monster itu dan menghancurkan intinya!"
  },
  AvgDialog_20475_Content_11 = {
    Text = "Shilo mengangguk, mencabut Duri Hitam, dan melesat menuju monster itu——"
  },
  AvgDialog_20475_Content_2 = {
    Text = "Kalian bertarung mati-matian, akhirnya tiba di puncak gunung yang dijaga oleh monster biru berpendar."
  },
  AvgDialog_20475_Content_3 = {
    Text = "Di puncak gunung salju yang tenggelam dalam kesunyian maut, bergoyang-goyang sebuah kobaran api biru yang menyala-nyala, bagaikan jantung gunung salju yang berdenyut."
  },
  AvgDialog_20475_Content_4 = {
    Text = "Kau tidak bisa menghalangi kami."
  },
  AvgDialog_20475_Content_5 = {
    Text = "Suaranya bergema di gunung salju yang luas. Monster biru yang melayang di udara menatapnya, sang raksasa yang mengambang di udara tidak memberikan respons sedikit pun."
  },
  AvgDialog_20475_Content_6 = {
    Text = "Kaki……tidak bisa bergerak……"
  },
  AvgDialog_20475_Content_7 = {
    Text = "Kamu menoleh ke arah Lily. Batu hitam pekat telah meleleh menjadi cairan, dan kaki Lily sudah setengah tertelan lumpur hitam."
  },
  AvgDialog_20475_Content_8 = {
    Text = "Kamu menariknya sekuat tenaga, namun kedua kaki Lily tetap terselimuti cairan hitam yang mengalir, semakin tenggelam semakin dalam."
  },
  AvgDialog_20475_Content_9 = {
    Text = "Tumit sepatu Shilo juga tertarik oleh cairan lengket itu. Pegunungan di bawah cahaya merah gelap berkilau dengan kilauan aneh, seolah hendak menarik keduanya masuk ke dalam neraka."
  },
  AvgDialog_20483_Content_1 = {
    Text = "Dengan nama @2 Pelaku, aku memerintahkanmu untuk berhenti!"
  },
  AvgDialog_20483_Content_2 = {
    Text = "Pikiran telah dilahap oleh kemarahan. Miryam, yang sebelumnya dikenal sebagai monster, hanya berhenti sesaat, lalu kembali melancarkan serangan kegilaan."
  },
  AvgDialog_20483_Content_3 = {
    Text = "Dia sudah menganggap Yu sebagai pemalsu… kalau begitu, Yu hanya bisa menghadapinya dengan cara Lemuria."
  },
  AvgDialog_20483_Content_4 = {
    Text = [[
Miryam...
Semoga serangan dari zaman kuno ini... dapat membuatmu tersadar sepenuhnya.]]
  },
  AvgDialog_20503_Content_1 = {
    Text = "Tidak bisa lagi membiarkan kemarahan terus menggerogotinya. Jika dia benar-benar kehilangan kendali, dia akan berubah menjadi monster yang sepenuhnya tak terkendali."
  },
  AvgDialog_20503_Content_2 = {
    Text = [[
Pada titik itu, semuanya akan menjadi tidak dapat dipulihkan lagi. 
Taklukkan dia, atau... bunuh dia.]]
  },
  AvgDialog_20503_Content_3 = {
    Text = [[
Hamba paling setia... 
Semoga engkau... tidak lagi ragu.]]
  },
  AvgDialog_21363_Content_1 = {Text = "Sisyphus"},
  AvgDialog_21363_Content_10 = {
    Text = "Adalah… orang yang penting bagiku."
  },
  AvgDialog_21363_Content_11 = {
    Text = [[
Pusaran hitam kuno itu menelan {Male=dia,Female=dia}.
Aku hanya bisa menyaksikan dengan tak berdaya, badai Kolam Hitam menyapu habis seluruh Misagek.]]
  },
  AvgDialog_21363_Content_12 = {
    Text = "Seluruh Inti Perak yang disimpan dengan hati-hati oleh faksi Kebangkitan dilarutkan oleh Kolam Hitam."
  },
  AvgDialog_21363_Content_13 = {
    Text = "Sebagian besar Tubuh Kebangkitan yang ada kehilangan kendali—menjerit, pingsan, meratap, linglung, tertawa histeris…"
  },
  AvgDialog_21363_Content_14 = {
    Text = "Kholet dan William mengorganisir evakuasi terakhir, dan menyegel Penghalang Kabut sepenuhnya."
  },
  AvgDialog_21363_Content_15 = {
    Text = "Aku seorang diri tersegel di dalam Kolam Hitam."
  },
  AvgDialog_21363_Content_16 = {
    Text = "Entah berapa lama waktu yang kuhabiskan, akhirnya aku menemukan sebuah cara dari pengetahuan yang Tavi berikan kepadaku."
  },
  AvgDialog_21363_Content_17 = {
    Text = "Sebuah lorong—yang bisa membawaku kembali ke masa lalu, mengubah tragedi yang telah terjadi.\nNamun baik aku maupun Tavi, tak ada yang bisa memprediksi konsekuensi dari tindakan semacam ini."
  },
  AvgDialog_21363_Content_18 = {
    Text = "Melakukan tindakan seperti ini hanya demi diri sendiri, sungguh terlalu gegabah."
  },
  AvgDialog_21363_Content_19 = {
    Text = "Aku mulai menunggu."
  },
  AvgDialog_21363_Content_2 = {
    Text = "Hitungan pembukaan jalur: 0"
  },
  AvgDialog_21363_Content_20 = {
    Text = [[
Hingga hari itu.
Tuan Alistair duduk di kursi roda, didorong kembali ke tepi Kolam Hitam oleh Doll yang tubuhnya sudah usang.]]
  },
  AvgDialog_21363_Content_21 = {
    Text = "Lihat, sudah kuduga dia ada di sini."
  },
  AvgDialog_21363_Content_22 = {
    Text = "Meskipun dunia sudah kiamat, aku tetap tidak akan bertaruh denganmu, Alistair—walaupun sekarang memang benar-benar kiamat."
  },
  AvgDialog_21363_Content_23 = {Text = "...?"},
  AvgDialog_21363_Content_24 = {
    Text = "Ah, kau belum tahu. Dunia di luar sudah berakhir, Misage…"
  },
  AvgDialog_21363_Content_25 = {
    Text = "Biar kukatakan begini, kita adalah segalanya yang tersisa."
  },
  AvgDialog_21363_Content_26 = {
    Text = "Semuanya sudah lenyap?"
  },
  AvgDialog_21363_Content_27 = {
    Text = "Bersih tanpa sisa."
  },
  AvgDialog_21363_Content_28 = {
    Text = "Kalau bukan karena tempat terakhir yang bisa dijadikan laboratorium pun sudah musnah, planet ini akan menjadi tempat eksperimen yang sempurna."
  },
  AvgDialog_21363_Content_29 = {
    Text = "……Kalau begitu……tidak ada lagi yang perlu dikhawatirkan."
  },
  AvgDialog_21363_Content_3 = {
    Text = "Pada hari anomali Kolam Hitam, Tavi menghampiriku dan memeluk jiwaku dengan lembut."
  },
  AvgDialog_21363_Content_31 = {
    Text = "Aku memejamkan mata, merasakan kekuatan mengalir di dalam tubuhku. Dalam penantian yang panjang, aku telah menjadi sangat akrab dengannya. Kini, ia membawa kembali vitalitas yang hampir kulupakan."
  },
  AvgDialog_21363_Content_32 = {
    Text = "Aku akan menemukannya, cara untuk mengubah semua ini."
  },
  AvgDialog_21363_Content_33 = {
    Text = "Rasa sakit yang menyayat menenggelamkanku, tanpa sadar aku teringat sore itu.\n%player%Apakah saat itu juga sesakit ini? Atau bahkan lebih parah……?"
  },
  AvgDialog_21363_Content_34 = {
    Text = "Tragedi tidak boleh terulang lagi."
  },
  AvgDialog_21363_Content_35 = {
    Text = "Hitungan pembukaan saluran: 1"
  },
  AvgDialog_21363_Content_36 = {
    Text = "Saat Tavi menerjang ke arahku, aku menarik Sang Penjaga Rahasia mundur setengah langkah."
  },
  AvgDialog_21363_Content_37 = {
    Text = [[
Mengapa?
Kau mendirikan Misage karena ingin mengubah masa depan, bukan?]]
  },
  AvgDialog_21363_Content_38 = {
    Text = "Mengapa kau masih melakukan ini?"
  },
  AvgDialog_21363_Content_39 = {
    Text = "Tavi tidak berkata apa-apa, hanya mengangkat tangannya perlahan, memanggil badai yang sama seperti sebelumnya."
  },
  AvgDialog_21363_Content_4 = {
    Text = "Kemudian, gelombang hitam mulai bergejolak."
  },
  AvgDialog_21363_Content_40 = {
    Text = "Hitungan pembukaan saluran: 2"
  },
  AvgDialog_21363_Content_41 = {
    Text = "Saat Doer meminta aku dan Sang Penjaga Rahasia untuk melarikan diri, kami tidak menolak."
  },
  AvgDialog_21363_Content_42 = {
    Text = "Kami menyusuri pintu belakang di luar pemakaman, menembus tabir kabut yang tipis, melewati hutan kecil yang gelap dan misterius."
  },
  AvgDialog_21363_Content_43 = {
    Text = "Pemandangan di depan mata terbuka lebar — jalanan Londinium yang ramai dengan lalu lalang kendaraan, warga biasa yang hidup dalam keseharian yang bahagia."
  },
  AvgDialog_21363_Content_44 = {
    Text = "Namun, kebahagiaan itu tidak bertahan lama."
  },
  AvgDialog_21363_Content_45 = {
    Text = "Bayangan hitam yang kental mengejar kami dari belakang."
  },
  AvgDialog_21363_Content_46 = {
    Text = "Kali ini, hal-hal yang lenyap di depan mataku ratusan bahkan ribuan kali lebih banyak dari sebelumnya."
  },
  AvgDialog_21363_Content_47 = {
    Text = "Orang-orang yang berjalan dan tertawa di jalanan, tiba-tiba tak bisa melangkah lagi — kaki mereka terendam dalam lumpur hitam, kehilangan \"keberadaan\" mereka."
  },
  AvgDialog_21363_Content_48 = {
    Text = "Mereka mencoba bergerak, tetapi terjatuh ke dalam lumpur tak kasat mata, dan akhirnya…"
  },
  AvgDialog_21363_Content_49 = {
    Text = "Mereka kehilangan keberadaan itu sendiri."
  },
  AvgDialog_21363_Content_5 = {
    Text = "%player%, pegang tanganku, %player%!"
  },
  AvgDialog_21363_Content_50 = {
    Text = "Hitungan pembukaan lorong: 3"
  },
  AvgDialog_21363_Content_51 = {
    Text = "Aku menyembunyikan keberadaan menara lonceng dan kolam hitam, berusaha keras membujuk Penjaga Rahasia untuk meninggalkan kampus sendirian, sementara aku sendiri melangkah menuju jalan untuk menghadapi Tavi."
  },
  AvgDialog_21363_Content_52 = {
    Text = "Tanpa komando Penjaga Rahasia dan bantuan rekan, aku bahkan tidak bisa mencapai kolam hitam. Di tengah perjalanan, aku sudah dikalahkan oleh entitas terbangun lain yang tak terkendali."
  },
  AvgDialog_21363_Content_53 = {
    Text = "Hitungan pembukaan lorong: 4"
  },
  AvgDialog_21363_Content_54 = {
    Text = "Hitungan pembukaan lorong: 5"
  },
  AvgDialog_21363_Content_56 = {
    Text = "Hitungan pembukaan lorong: @3"
  },
  AvgDialog_21363_Content_57 = {
    Text = "Sudah yang keberapa kali ini?"
  },
  AvgDialog_21363_Content_58 = {
    Text = "Haruskah aku menyaksikan dunia ini, menyaksikan %player% mati lagi?"
  },
  AvgDialog_21363_Content_59 = {
    Text = "Jika apapun yang kulakukan, {Male=dia,Female=dia} sebagai Penjaga Rahasia pasti akan mati, maka biarlah {Male=dia,Female=dia} tidak menjadi Penjaga Rahasia."
  },
  AvgDialog_21363_Content_6 = {
    Text = "Aku berusaha sekuat tenaga mengulurkan tangan."
  },
  AvgDialog_21363_Content_60 = {
    Text = [[
Aku menyembunyikan kemampuan %hisorher%, dan membiarkan {Male=dia,Female=dia} tetap di Akut.
Selama {Male=dia,Female=dia} bisa tetap hidup, aku tidak peduli apakah aku harus maju sendirian.]]
  },
  AvgDialog_21363_Content_61 = {
    Text = "Kali ini, aku bahkan tidak bisa meninggalkan pemakaman."
  },
  AvgDialog_21363_Content_62 = {
    Text = "Kalian duduk di tepi kolam hitam, Ramona membalut lukamu sambil menceritakan penderitaannya dengan nada datar."
  },
  AvgDialog_21363_Content_63 = {
    Text = "Aku pernah mencoba melarikan diri dari kampus, juga pernah mencoba menghadapi Tavi secara langsung."
  },
  AvgDialog_21363_Content_64 = {
    Text = "Aku pernah mencoba membawa Rotan, Ogier, Dor, dan orang-orang lain yang kutemui di kampus, juga pernah mencoba untuk tidak bersama salah satu atau beberapa dari mereka."
  },
  AvgDialog_21363_Content_65 = {
    Text = "Pernah mencoba bernegosiasi dengan lembut, juga pernah mencoba menggunakan kekerasan."
  },
  AvgDialog_21363_Content_66 = {
    Text = "Namun, semua itu seolah tak ada gunanya."
  },
  AvgDialog_21363_Content_67 = {
    Text = "Kemudian, aku mulai mengasah teknik bertarungku."
  },
  AvgDialog_21363_Content_68 = {
    Text = "Satu-satunya kemungkinan yang tersisa adalah pada hari Kolam Hitam mengalami perubahan, saat Tavi menunjukkan wujud aslinya, menembus intinya dengan satu serangan."
  },
  AvgDialog_21363_Content_69 = {
    Text = "Harus cukup cepat, cukup cepat."
  },
  AvgDialog_21363_Content_7 = {
    Text = "Seperti saat di Akut, jika aku bisa meraih {Male=dia,Female=dia}, {Male=dia,Female=dia} bisa menyelamatkan kita yang terjebak dalam badai."
  },
  AvgDialog_21363_Content_70 = {
    Text = "Cukup cepat untuk membuat Rotan panik, cukup cepat untuk membuat Dor kehilangan suaranya, cukup cepat agar Tavi tak sempat bereaksi."
  },
  AvgDialog_21363_Content_71 = {
    Text = "Setiap orang yang kutemui menjadi objek untuk mengasah teknik pedangku. Di jalan ini, aku tak lagi memiliki sesuatu yang disebut \"rekan\"."
  },
  AvgDialog_21363_Content_72 = {
    Text = "Aku bahkan tak lagi berbicara dengan Penjaga Rahasia, hanya sepenuh hati mengasah satu tebasan \"Pedang Takdir\" itu."
  },
  AvgDialog_21363_Content_73 = {
    Text = "Apakah kau berhasil?"
  },
  AvgDialog_21363_Content_74 = {
    Text = "Aku berhasil… sekaligus gagal."
  },
  AvgDialog_21363_Content_75 = {
    Text = "Hari itu, Tavi mengulurkan kedua tangannya kepadaku."
  },
  AvgDialog_21363_Content_76 = {
    Text = "Dengan insting yang telah kutempa ribuan kali, aku menghunuskan serangan penuh ke arah cahaya tersembunyi di balik dada Tavi."
  },
  AvgDialog_21363_Content_78 = {
    Text = "Suara benturan logam keras menggema, mengguncang pergelangan tanganku yang menggenggam rapier erat."
  },
  AvgDialog_21363_Content_79 = {
    Text = "Wujud Tavi lenyap, berubah menjadi abu keperakan yang beterbangan."
  },
  AvgDialog_21363_Content_8 = {
    Text = "Terlebih lagi—"
  },
  AvgDialog_21363_Content_80 = {
    Text = "Berakhir sudah, akhirnya…"
  },
  AvgDialog_21363_Content_81 = {
    Text = "Berakhir…!"
  },
  AvgDialog_21363_Content_82 = {
    Text = "%player%, kita berhasil——"
  },
  AvgDialog_21363_Content_83 = {
    Text = "<Big:%player%!>"
  },
  AvgDialog_21363_Content_84 = {
    Text = "Di belakangku tak ada Penjaga Rahasia."
  },
  AvgDialog_21363_Content_85 = {
    Text = "Yang ada hanyalah sebuah tangan yang tengah tenggelam ke dalam pusaran hitam."
  },
  AvgDialog_21363_Content_86 = {
    Text = "Hari itu, aku melompat terjun ke dalam Kolam Hitam."
  },
  AvgDialog_21363_Content_87 = {
    Text = "Kemudian, sekilas aku melihat sebuah masa depan yang bukan milikku."
  },
  AvgDialog_21363_Content_88 = {
    Text = "\"Tavi\" masih berdiri diam di tempat, hanya saja sikapnya tidak lagi setenang sebelumnya."
  },
  AvgDialog_21363_Content_89 = {
    Text = "Sebelum yang lain sempat bereaksi, Dia membentangkan sayap peraknya dengan kasar, menerjang ke arah Ramona—ke arah diriku yang lain."
  },
  AvgDialog_21363_Content_9 = {
    Text = "{Male=Dia,Female=Dia} adalah temanku."
  },
  AvgDialog_21363_Content_90 = {
    Text = "Waktu seolah membeku."
  },
  AvgDialog_21363_Content_92 = {
    Text = "Sang Penjaga Rahasia berlari cepat, menghalangi di depan diriku yang lain."
  },
  AvgDialog_21363_Content_93 = {
    Text = "Barulah saat itu aku mengerti."
  },
  AvgDialog_21363_Content_94 = {
    Text = "Masa depan dunia bukanlah sesuatu yang bisa kupilih atau kuubah."
  },
  AvgDialog_21363_Content_96 = {
    Text = "Satu langkah, itulah jurang takdir yang tak terseberangi."
  },
  AvgDialog_21364_Content_1 = {Text = "Naik."},
  AvgDialog_21364_Content_2 = {
    Text = "Tunggu, Ramona! Doer dan Augier tidak ada di sini, kalau hanya kamu sendiri……"
  },
  AvgDialog_21364_Content_3 = {
    Text = "Sudah terlambat, Tavi sudah meraung dan membentangkan enam sayap peraknya."
  },
  AvgDialog_21364_Content_4 = {
    Text = "Rasa hangat asam yang familiar membakar Mata-mu, kali ini jauh lebih menyengat dan perih dari sebelumnya, air mata tak terbendung mengalir deras."
  },
  AvgDialog_21364_Content_5 = {
    Text = "Ramona menoleh ke arahmu, merendahkan suaranya dan berbisik padamu."
  },
  AvgDialog_21364_Content_6 = {
    Text = "Bertautlah denganku, dan berikan aku perintah untuk terakhir kalinya."
  },
  AvgDialog_21364_Content_7 = {
    Text = "Sang Penjaga Rahasia."
  },
  AvgDialog_21365_Content_2 = {
    Text = "Satu tebasan bersih dan tegas mengakhiri pertarungan dalam sekejap. Ramona mengibaskan lendir dari pedangnya, tanpa sekalipun menoleh ke arahmu."
  },
  AvgDialog_21365_Content_3 = {
    Text = "Kau menatap punggungnya yang bisa dibilang dingin itu dengan terkejut, merasakan keasing yang tak biasa."
  },
  AvgDialog_21365_Content_4 = {
    Text = "Ini... benar-benar ingatan?"
  },
  AvgDialog_21365_Content_5 = {
    Text = "Ramona melangkahi tubuh Aberrant yang belum lenyap, menggenggam pedangnya dan berlari menuju arah alun-alun."
  },
  AvgDialog_21366_Content_1 = {
    Text = "Kamu bergegas mengejar Ramona, dan di detik terakhir sebelum pintu elevator tertutup, kamu membuka paksa pintu elevator dengan risiko tanganmu terjepit."
  },
  AvgDialog_21366_Content_10 = {
    Text = [[
Apakah Mistscape Buatan memutus tautan?
Semua yang kamu lihat ini, sebenarnya apa?]]
  },
  AvgDialog_21366_Content_11 = {
    Text = [[
Kamu tidak tahu.
Kamu bahkan tidak tahu kapan kamu bisa keluar dari sini.]]
  },
  AvgDialog_21366_Content_12 = {Text = "Ding——"},
  AvgDialog_21366_Content_13 = {
    Text = "Ramona melangkah keluar dari elevator, melemparkan sebuah jawaban di belakangnya:"
  },
  AvgDialog_21366_Content_14 = {
    Text = "Sudah lama bukan."
  },
  AvgDialog_21366_Content_2 = {
    Text = "Hah, hah……"
  },
  AvgDialog_21366_Content_3 = {
    Text = "Baru saat itulah, setelah memasuki \"Mistscape Buatan\", kamu akhirnya melihat wajahnya untuk pertama kali."
  },
  AvgDialog_21366_Content_4 = {
    Text = "Ra, Ramona?"
  },
  AvgDialog_21366_Content_5 = {
    Text = "Ramona di hadapanmu mengenakan penutup mata hitam. Wajahnya menunjukkan raut tidak senang, tampaknya ia kesal karena kamu memperlambat laju turunnya."
  },
  AvgDialog_21366_Content_6 = {
    Text = "Kamu…… bukan Ramona yang kukenal, kan?"
  },
  AvgDialog_21366_Content_7 = {
    Text = [[
Elevator bergemuruh.
Ramona menghadap ke arahmu, tanpa berkata apa-apa.]]
  },
  AvgDialog_21366_Content_8 = {
    Text = "Kamu mencoba merasakan tautan di antara kalian, tetapi tidak menemukan apa pun."
  },
  AvgDialog_21366_Content_9 = {
    Text = "Tidak ada tautan……"
  },
  AvgDialog_21367_Content_1 = {
    Text = "Ini Bukan Perpisahan Selamanya"
  },
  AvgDialog_21367_Content_10 = {
    Text = "Pemandangan Kolam Hitam memudar perlahan bagaikan warna yang meluntur, dan di tempat \"Tavi\" berada tadi, samar-samar tampak siluet perangkat kebangkitan."
  },
  AvgDialog_21367_Content_11 = {
    Text = "Meskipun aku tahu ini mustahil, tapi…"
  },
  AvgDialog_21367_Content_12 = {
    Text = "Kuharap kita bisa bertemu lagi."
  },
  AvgDialog_21367_Content_13 = {
    Text = "Ruang buatan perlahan menghilang, kamu duduk di depan perangkat kebangkitan, menatap Ramona yang berbaring di kursi rebah."
  },
  AvgDialog_21367_Content_14 = {
    Text = "Lalu dengan terkejut kamu menyadari, di wajahnya masih terpasang penutup mata milik \"Ramona\" yang lain itu."
  },
  AvgDialog_21367_Content_15 = {
    Text = "…Ramona…?"
  },
  AvgDialog_21367_Content_16 = {
    Text = "……Ini juga di luar dugaanku.\nSenang bisa bertemu denganmu lagi secepat ini, %player%."
  },
  AvgDialog_21367_Content_17 = {
    Text = "Kamu benar-benar \"Ramona\" itu?! Apa yang sebenarnya terjadi——"
  },
  AvgDialog_21367_Content_18 = {
    Text = "Biar aku yang menjawab pertanyaan itu."
  },
  AvgDialog_21367_Content_19 = {
    Text = [[
Suara yang familiar tiba-tiba muncul, membuatmu terkejut.
Kamu menoleh ke belakang dan mendapati Doer entah sejak kapan sudah berdiri di belakang kalian, bahkan dengan santai menyeruput teh.]]
  },
  AvgDialog_21367_Content_2 = {
    Text = "Kamu menatap \"Ramona\" di hadapanmu, sesaat tak mampu berkata-kata."
  },
  AvgDialog_21367_Content_20 = {
    Text = "Sebelum kamu datang, aku dan Ramona melakukan uji coba sederhana pada perangkat Mystic Realm buatan, terutama untuk melihat sejauh mana jiwanya bisa meluas dan seberapa kuat Mystic Realm yang terbentuk."
  },
  AvgDialog_21367_Content_21 = {
    Text = "Saat pengujian berlangsung, <Blue:Pengukur Nous> tiba-tiba mendeteksi fluktuasi abnormal. Pada saat yang sama, Mystic Realm terbuka sepenuhnya, hanya membutuhkan 3 detik untuk membentuk domain independen, menyertakan Ramona, pintu kamar, dan sebagian perangkat ke dalamnya."
  },
  AvgDialog_21367_Content_22 = {
    Text = "Untungnya, meskipun <Yellow:Indeks Nous>-nya sangat tinggi hingga menakutkan, Mystic Realm tidak terpengaruh oleh fluktuasi mental dan tetap stabil."
  },
  AvgDialog_21367_Content_23 = {
    Text = "Sayangnya, kamu sudah melangkah masuk ke dalam Mystic Realm begitu kamu masuk ke ruangan, sementara aku entah kenapa tidak bisa masuk, bahkan tidak bisa melihat pemandangan di dalam Mystic Realm."
  },
  AvgDialog_21367_Content_24 = {
    Text = "Situasi ini belum pernah terjadi dalam eksperimen sebelumnya, dan karena kamu ada di dalam, aku tidak bisa bertindak sembarangan."
  },
  AvgDialog_21367_Content_25 = {
    Text = "Untungnya, aku sudah merancang durasi Mystic Realm buatan sebelumnya, jadi yang perlu kulakukan hanyalah menunggu sebentar di sini."
  },
  AvgDialog_21367_Content_26 = {
    Text = "Jadi itu alasanmu minum teh?! Tunggu, aroma harum ini——kue kecil!\nKamu langsung memulai acara teh sore, ya."
  },
  AvgDialog_21367_Content_27 = {
    Text = [[
Mencatat data tidak memakan banyak waktu, lagipula seperti yang kukatakan tadi, aku tidak bisa melihat keadaan di dalam Mystic Realm.
Kalau bisa, pagiku pasti akan jauh lebih produktif.]]
  },
  AvgDialog_21367_Content_28 = {
    Text = "Sudah menemukan masalahnya?"
  },
  AvgDialog_21367_Content_29 = {
    Text = "Doer melirik \"Ramona\" sekilas, jelas menahan rasa ingin tahunya, lalu melanjutkan penjelasan untuk kalian:"
  },
  AvgDialog_21367_Content_3 = {
    Text = "Dia telah melewati terlalu banyak hal, memikul terlalu banyak beban. Wajahnya tetap dingin, namun gerakan tangannya saat membalut lukamu begitu lembut."
  },
  AvgDialog_21367_Content_30 = {
    Text = "Berdasarkan analisis situasi yang ada, alasan Mystic Realm buatan membaca memori \"Ramona\" ini, alih-alih membaca memori Ramona kita sesuai rencana awal, hanya ada satu kemungkinan."
  },
  AvgDialog_21367_Content_31 = {
    Text = "Yaitu: <Yellow:semacam resonansi mental yang ada di antara \"Awakened Sumber Sama\">, yang diperkuat oleh perangkat kebangkitan hingga menembus batas dimensi, menyebabkan dua jiwa yang sangat mirip <Yellow:tumpang tindih sesaat>, sehingga Mystic Realm terkonstruksi secara keliru."
  },
  AvgDialog_21367_Content_32 = {
    Text = "\"Ramona\" ini bisa datang ke dunia kita, kemungkinan besar juga berkat <Yellow:tumpang tindih mental> tersebut."
  },
  AvgDialog_21367_Content_33 = {
    Text = "Sumber sama……maksudnya mereka berbagi satu sumber kekuatan yang sama?"
  },
  AvgDialog_21367_Content_34 = {
    Text = "Bisa dibilang begitu. Kekuatan tempur Awakened, pada dasarnya adalah kekuatan yang <Blue:\"dipinjam\"> dari makhluk berdimensi tinggi yang kita sebut <Blue:\"Asal Mula\">."
  },
  AvgDialog_21367_Content_35 = {
    Text = "Awakened yang memiliki <Yellow:\"Asal Mula\"> yang sama, itulah yang disebut <Yellow:\"Awakened Sumber Sama\">."
  },
  AvgDialog_21367_Content_36 = {
    Text = "Tapi bukankah kalian orang yang sama?"
  },
  AvgDialog_21367_Content_37 = {
    Text = "Mungkin dari sudut pandang tertentu, memang begitu. Tapi, kami memiliki pengalaman dan ingatan yang berbeda."
  },
  AvgDialog_21367_Content_38 = {
    Text = "Lagipula, dibandingkan Ramona kami, \"Ramona\" yang ini menggunakan kekuatannya dengan cara yang berbeda, dan secara mental lebih dekat dengan \"Sumber\" mereka — kamu sudah pernah bertemu dengan <Yellow:Tavi>, kan?"
  },
  AvgDialog_21367_Content_39 = {
    Text = "Ya. Dengan bantuannya, aku pernah membuka jalur menuju masa lalu."
  },
  AvgDialog_21367_Content_4 = {Text = "Aku..."},
  AvgDialog_21367_Content_40 = {
    Text = "Pantas saja, dibandingkan Ramona kami, kemampuanmu lebih……"
  },
  AvgDialog_21367_Content_41 = {
    Text = "Aku semakin penasaran denganmu, kamu, dan semua Awakened lain yang lebih dekat dengan Sumber."
  },
  AvgDialog_21367_Content_42 = {
    Text = "Melihat Dor yang sebentar lagi akan meminta orang lain untuk ikut dalam eksperimennya, kamu buru-buru mengalihkan topik."
  },
  AvgDialog_21367_Content_43 = {
    Text = "Awakened yang lebih dekat dengan Sumber, bisakah disebut <Yellow:\"Awakened Sumber\">?"
  },
  AvgDialog_21367_Content_44 = {
    Text = "Awakened Sumber? Nama yang bagus juga. Tumben kamu cerdas sekali, %player%."
  },
  AvgDialog_21367_Content_45 = {
    Text = "Ada lagi yang ingin kamu tanyakan?"
  },
  AvgDialog_21367_Content_46 = {
    Text = "Kamu…… ingin tinggal di sini?"
  },
  AvgDialog_21367_Content_47 = {
    Text = "Setelah perangkat dimatikan, efek amplifikasi terhadap mental akan berangsur memudar, dan resonansi di antara mereka juga akan melemah secara bertahap."
  },
  AvgDialog_21367_Content_48 = {
    Text = "Kalau soal membiarkan perangkat terus menyala — maaf, alat ini punya batasan jangkauan.\nJadi sayangnya, apa pun keinginan kalian, pada akhirnya dia harus kembali ke dunianya sendiri."
  },
  AvgDialog_21367_Content_49 = {
    Text = "Untuk saat ini, membuat mereka hidup berdampingan itu mustahil. Satu tubuh mana bisa menjadi wadah bagi dua jiwa?\nTapi di masa depan, siapa tahu? Mungkin <Small:…… tidak, kalau menggunakan…… harus mengumpulkan data……>"
  },
  AvgDialog_21367_Content_5 = {
    Text = "Tidak apa-apa, kamu tidak perlu mengatakan apa pun."
  },
  AvgDialog_21367_Content_50 = {
    Text = [[
Suara Dor semakin pelan, perlahan tenggelam dalam pikirannya sendiri.
"Ramona" tersenyum kepadamu.]]
  },
  AvgDialog_21367_Content_51 = {
    Text = [[
Saat kamu membutuhkanku, panggil aku melalui tautan di antara kita.
Dengan meminjam tubuhnya, aku bisa bertindak sebentar di dunia ini.]]
  },
  AvgDialog_21367_Content_52 = {
    Text = "Jalurnya sudah terbuka. Selama aku masih memiliki kesadaran, aku pasti akan datang ke sisimu."
  },
  AvgDialog_21367_Content_53 = {
    Text = "Saat kamu ada di sini, apakah Ramona memiliki kesadaran?"
  },
  AvgDialog_21367_Content_54 = {
    Text = [[
Selama aku terjaga, Ramona yang kamu kenal akan tertidur sepenuhnya.
Dengan kata lain, dia tidak akan tahu tentang keberadaanku.]]
  },
  AvgDialog_21367_Content_55 = {
    Text = "Hal-hal yang berkaitan denganku, tolong sampaikan kepadanya atas namaku, ya."
  },
  AvgDialog_21367_Content_56 = {
    Text = "Apakah semua Awakened Body yang satu asal akan mengalami situasi serupa?"
  },
  AvgDialog_21367_Content_57 = {
    Text = "Misalnya menggunakan komponen Erica untuk merakit satu automaton lagi——"
  },
  AvgDialog_21367_Content_58 = {
    Text = [[
Apa yang kaupikirkan? Tidak dengar aku tadi bilang "jiwa yang sangat mirip"?
Selain diri sendiri dari dunia lain, mungkin tidak ada jiwa lain yang memenuhi standar ini.]]
  },
  AvgDialog_21367_Content_59 = {
    Text = "Tapi, siapa yang tahu? Mungkin dengan bantuan Hollow buatan, kita bisa perlahan menemukan \"Awakened Body Asal\" semua orang, kalau begitu……"
  },
  AvgDialog_21367_Content_6 = {
    Text = "Kamu cukup tinggal sebentar lagi sebelum kembali."
  },
  AvgDialog_21367_Content_60 = {
    Text = "Kau agak tak berdaya melihat gadis di hadapanmu tenggelam dalam brainstorming, sementara \"Ramona\" menyentuh tanganmu saat itu."
  },
  AvgDialog_21367_Content_61 = {
    Text = [[
Aku harus kembali.
Bagaimanapun, tidak seharusnya aku menempati tubuh orang lain terlalu lama.]]
  },
  AvgDialog_21367_Content_62 = {
    Text = "Kau ragu sesaat, tetapi tetap tak bisa mengucapkan kata-kata untuk menahannya."
  },
  AvgDialog_21367_Content_63 = {
    Text = "Apakah ada sesuatu yang ingin kausampaikan kepada Ramona?"
  },
  AvgDialog_21367_Content_64 = {
    Text = "Dia terdiam cukup lama, menarik napas dalam-dalam, lalu berpura-pura tenang saat mengungkapkannya."
  },
  AvgDialog_21367_Content_65 = {
    Text = "Tolong sampaikan padanya…… dia sangat beruntung."
  },
  AvgDialog_21367_Content_66 = {
    Text = "Aku…… sedikit iri."
  },
  AvgDialog_21367_Content_67 = {
    Text = "Setelah meninggalkan kata-kata itu, \"Ramona\" duduk kembali di kursi bersandar, perlahan menutup matanya, dan napasnya berangsur tenang."
  },
  AvgDialog_21367_Content_68 = {
    Text = "Kau tahu, yang akan terbangun nanti adalah asisten cerdas dan dingin yang kau kenal."
  },
  AvgDialog_21367_Content_69 = {
    Text = "Sementara gadis bertopeng yang dingin itu, masih berada di kolam hitam dimensi lain, mendongak menatap langit malam hitam pekat yang tak berujung."
  },
  AvgDialog_21367_Content_7 = {
    Text = "Kembali? Kamu tahu—"
  },
  AvgDialog_21367_Content_70 = {
    Text = "Menunggu, panggilan dari dimensi yang jauh."
  },
  AvgDialog_21367_Content_8 = {
    Text = [[
Aku tahu.
Kamu bukan milikku, bukan milik diriku di dunia ini.]]
  },
  AvgDialog_21367_Content_9 = {
    Text = "Tapi mengetahui masih ada satu dunia yang belum hancur, masih ada satu dirimu yang aman, aku juga… sudah cukup puas."
  },
  AvgDialog_21368_Content_1 = {
    Text = "Pertaruhan Terakhir"
  },
  AvgDialog_21368_Content_10 = {
    Text = "Sebelum kau sempat memberikan perintah kepada Ramona, dia sudah bergerak."
  },
  AvgDialog_21368_Content_2 = {
    Text = "Bau amis darah menusuk hidung, para siswa berteriak ketakutan, berlarian ke segala arah di hadapan monster hitam yang bergerak-gerak—semuanya seolah kembali ke hari ketika kau dianugerahi Kunci Perak."
  },
  AvgDialog_21368_Content_3 = {
    Text = "Hari ketika Ramona terluka."
  },
  AvgDialog_21368_Content_4 = {
    Text = "Ini... Upacara Penyerahan Kunci?"
  },
  AvgDialog_21368_Content_5 = {
    Text = "Air hujan meresap ke pakaianmu membawa sedikit rasa dingin. Kau menggigil, sesaat bahkan merasa seolah semua yang terjadi sebelumnya hanyalah khayalan sesaat, dan kau tidak pernah meninggalkan bencana ini."
  },
  AvgDialog_21368_Content_6 = {
    Text = "Sepertinya Dor telah mengaktifkan Mystic Realm buatan lebih awal. Entah bagaimana keadaan Ramona..."
  },
  AvgDialog_21368_Content_7 = {
    Text = "Pandanganmu terhenti mendadak. Di tengah kekacauan, sosok yang familiar berdiri membelakangimu, menghadap angin."
  },
  AvgDialog_21368_Content_8 = {
    Text = "Tangan yang menggenggam rapier terarah mantap ke depan, menunjuk ke arah \"Emily\" yang pernah memperkenalkan diri padamu di gerbang pemakaman, kini sudah tak berbentuk lagi."
  },
  AvgDialog_21368_Content_9 = {Text = "Ramona!"},
  AvgDialog_21369_Content_1 = {
    Text = "\"Tavi\" masih berdiri diam di tempat, hanya saja sikapnya tidak lagi setenang sebelumnya."
  },
  AvgDialog_21369_Content_11 = {
    Text = "Yang muncul di hadapanmu adalah wajah seorang wanita dengan ekspresi dingin."
  },
  AvgDialog_21369_Content_12 = {
    Text = "Dia mengulurkan tangannya, dengan lembut menyentuh kunci perak di dadamu."
  },
  AvgDialog_21369_Content_13 = {
    Text = "Kunci perak itu berkilau merespons dengan cahaya redup."
  },
  AvgDialog_21369_Content_14 = {
    Text = "Kaulah variabelnya, jawaban dari awal mula sekaligus akhir dari segalanya."
  },
  AvgDialog_21369_Content_15 = {
    Text = "Semoga kau, adalah titik balik dari segalanya……"
  },
  AvgDialog_21369_Content_17 = {
    Text = "Monster bersayap enam yang putih bersih, makhluk lumpur yang menyerbu ke segala arah, bayangan Awakened yang meraung-raung dengan tubuh terdistorsi……"
  },
  AvgDialog_21369_Content_18 = {
    Text = "Semuanya melebur menjadi genangan air hitam, lalu menghilang tanpa jejak."
  },
  AvgDialog_21369_Content_19 = {
    Text = "Kau menggenggam kunci perak di dadamu, perlahan menghembuskan napas."
  },
  AvgDialog_21369_Content_2 = {
    Text = "Sebelum kau sempat bereaksi, Dia tiba-tiba membentangkan sayap peraknya dan menerjang ke arah Ramona."
  },
  AvgDialog_21369_Content_20 = {
    Text = "……Kenapa."
  },
  AvgDialog_21369_Content_21 = {Text = "?"},
  AvgDialog_21369_Content_22 = {
    Text = "Kenapa kau menghalangi di depanku?"
  },
  AvgDialog_21369_Content_23 = {
    Text = "Kau tidak tahu itu berbahaya?"
  },
  AvgDialog_21369_Content_24 = {
    Text = "Kau tidak takut mati?"
  },
  AvgDialog_21369_Content_25 = {Text = "Aku——"},
  AvgDialog_21369_Content_26 = {
    Text = "Aku tidak mau kau mati."
  },
  AvgDialog_21369_Content_27 = {
    Text = "Kedua mata Ramona yang tertutup kain entah sedang menatap ke mana, kain hitam itu sedikit basah, seolah diresapi air mata."
  },
  AvgDialog_21369_Content_28 = {
    Text = "Aku sudah melihatnya terlalu banyak kali, aku tidak ingin lagi……"
  },
  AvgDialog_21369_Content_29 = {
    Text = "Dia menarik napas dalam-dalam, menelan kembali kata-kata yang tersisa."
  },
  AvgDialog_21369_Content_3 = {
    Text = "Waktu seolah membeku."
  },
  AvgDialog_21369_Content_30 = {
    Text = "Gadis yang sejak tadi bersikap dingin tanpa emosi kini seolah menemukan kembali perasaannya. Dia gemetar, perlahan mendekat, dan dengan lembut menyandarkan kepalanya di dadamu."
  },
  AvgDialog_21369_Content_31 = {
    Text = "Air mata menetes di bahu yang terluka tanpa sengaja, rasa perih merambat melalui pembuluh darah hingga ke ujung saraf. Tubuhmu gemetar tak terkendali, namun pada akhirnya, kehangatan air mata itu meluluhkannya sepenuhnya."
  },
  AvgDialog_21369_Content_32 = {
    Text = "Ramona, aku……"
  },
  AvgDialog_21369_Content_33 = {
    Text = "Dia tiba-tiba menggenggam tanganmu erat, seolah kau adalah layang-layang terakhir. Selain berdoa agar kau tidak lagi menghilang tertiup angin waktu, dia tidak bisa melakukan apa pun."
  },
  AvgDialog_21369_Content_34 = {
    Text = "Jangan mengambil risiko lagi……%player%."
  },
  AvgDialog_21369_Content_4 = {
    Text = "Kau berlari secepat mungkin dan menghalangi jalan di depan Ramona."
  },
  AvgDialog_21369_Content_6 = {
    Text = "Pedang tipis perak menusuk dari belakang, menembus bahu kirimu."
  },
  AvgDialog_21369_Content_7 = {Text = "?!"},
  AvgDialog_21369_Content_8 = {
    Text = "Monster putih itu menatapmu langsung."
  },
  AvgDialog_21369_Content_9 = {
    Text = "Dengan tubuh pucatnya yang tanpa wajah, diam-diam memandangimu."
  },
  AvgDialog_21391_Content_1 = {
    Text = "Matahari terbenam"
  },
  AvgDialog_21391_Content_10 = {
    Text = "Pada saat itu, aku sama sekali tidak merasakan sakit, benar-benar tidak ada rasa sakit."
  },
  AvgDialog_21391_Content_11 = {
    Text = "Kemudian, segalanya menjadi sedikit berbeda. Ibu mengurungku dan melakukan lebih banyak eksperimen."
  },
  AvgDialog_21391_Content_12 = {
    Text = [[
Tapi ini bukan salah Ibu. 
Karena, Ibu juga terkurung bersamaku di kamar ini, yang tidak bisa kami tinggalkan.]]
  },
  AvgDialog_21391_Content_13 = {
    Text = [[
Karena aku, aku kehilangan kendali dan menyebabkan banyak orang meninggal. 
Karena aku... terlalu menderita.]]
  },
  AvgDialog_21391_Content_14 = {
    Text = "Lisa berkata, \"Karena dia adalah satu-satunya temanku, dia akan berusaha untuk menemaniku lebih lama.\""
  },
  AvgDialog_21391_Content_15 = {
    Text = "Kalau tidak, dia sudah lama menyerah."
  },
  AvgDialog_21391_Content_16 = {
    Text = "...sebenarnya aku juga, sudah tidak kuat lagi."
  },
  AvgDialog_21391_Content_17 = {
    Text = "Makhluk raksasa merobek lebih banyak ruang, cakarnya langsung mengarah ke Lily."
  },
  AvgDialog_21391_Content_19 = {
    Text = "Di depan gadis berpakaian putih yang tampak rapuh, cairan hitam berkumpul menjadi bola dan jaring, menangkis serangan-Nya satu per satu."
  },
  AvgDialog_21391_Content_2 = {
    Text = "Langkah lembut Lily maju dengan telanjang kaki, cairan hitam berkumpul dan membentuk genangan di sekitar kakinya."
  },
  AvgDialog_21391_Content_20 = {
    Text = "Namun, meskipun begitu——"
  },
  AvgDialog_21391_Content_21 = {
    Text = "Itu juga ibu saya yang satu-satunya."
  },
  AvgDialog_21391_Content_22 = {
    Text = "Tidak boleh——memberikan kerusakan pada ibuku!"
  },
  AvgDialog_21391_Content_24 = {
    Text = "Bola hitam meledak, berkumpul menjadi duri, dan menancapkan cakar Anjing Neraka."
  },
  AvgDialog_21391_Content_25 = {
    Text = "Bola lendir yang tersisa membuka gigi tajam seperti belati dan menggigit putus pergelangan kaki yang terikat."
  },
  AvgDialog_21391_Content_27 = {
    Text = "Cakar itu menghilang menjadi asap ungu iblis, lalu kembali terbentuk."
  },
  AvgDialog_21391_Content_28 = {
    Text = "Dia sepenuhnya membelah ruang, waktu yang membeku perlahan-lahan meloloskan diri dari celah itu, sinar matahari senja sepenuhnya dilahap."
  },
  AvgDialog_21391_Content_3 = {
    Text = "Lisa mengatakan bahwa ibunya sudah tidak mengenalinya lagi dan bahkan melukainya dengan senapan."
  },
  AvgDialog_21391_Content_30 = {
    Text = "Dia membuka mulutnya yang aneh dan menerkam Lily!"
  },
  AvgDialog_21391_Content_4 = {
    Text = "Lisa berkata bahwa ibunya sangat tegas. Setiap kali dia bermain denganku, ibunya akan memukul dan memarahinya."
  },
  AvgDialog_21391_Content_5 = {
    Text = "Lisa berkata, \"Jika ibuku tahu bahwa aku berubah menjadi anjing besar karena keluar bersamamu, dia pasti tidak akan memaafkanku.\""
  },
  AvgDialog_21391_Content_6 = {
    Text = "Tetapi dia tidak bisa menahan diri, dia terlalu lapar. Karena tidak ingin mencuri barang milik orang lain, dia akhirnya pulang untuk mencari makanan… dan baru kemudian dia ketahuan oleh ibunya…"
  },
  AvgDialog_21391_Content_7 = {
    Text = "Lily berhenti sejenak."
  },
  AvgDialog_21391_Content_8 = {
    Text = "Namun, ibuku tidak sama."
  },
  AvgDialog_21391_Content_9 = {
    Text = "Dia mengira aku orang lain, tetapi saat dia pertama kali menyayatku dengan pisau bedah, dia berkata maaf padaku."
  },
  AvgDialog_21392_Content_10 = {
    Text = [[
Pengemudi segera menarik rem tangan, kereta bergetar hebat dan melambat. 
 Penumpang yang tidak mengetahui situasi tersebut buru-buru melompat dari kereta bawah tanah dan berlarian ke segala arah.]]
  },
  AvgDialog_21392_Content_11 = {
    Text = [[
Kondisi darurat, lindungi masyarakat! 
Boneka, Boneka, apakah kamu bisa mendengarku?]]
  },
  AvgDialog_21392_Content_12 = {
    Text = "Deteksi … gangguan komunikasi … fluktuasi Perak … diduga … zzzzrrr … Resonansi …"
  },
  AvgDialog_21392_Content_13 = {
    Text = [[
Ada pepatah yang bagaimana ya? Air jauh tak dapat memadamkan api dekat. 
 Sepertinya, sudah waktunya aku bertindak.]]
  },
  AvgDialog_21392_Content_2 = {
    Text = "Apa, apa itu?!"
  },
  AvgDialog_21392_Content_3 = {
    Text = "Di atas rel di ujung terowongan gelap, di area yang disinari cahaya, berdiri sosok yang seharusnya tidak mungkin ada."
  },
  AvgDialog_21392_Content_4 = {
    Text = "Wanita itu bertubuh tinggi, tatapannya tajam bagaikan mata pisau, dengan tenang menghadapi kereta yang datang menderu."
  },
  AvgDialog_21392_Content_5 = {
    Text = "Ketemu kamu."
  },
  AvgDialog_21392_Content_6 = {
    Text = "Hanya dalam sekejap, sosok wanita itu menghilang ——"
  },
  AvgDialog_21392_Content_8 = {
    Text = "Tidak, bukan menghilang, dia melakukan serangan ke arah kereta yang melaju kencang!"
  },
  AvgDialog_21761_Content_1 = {
    Text = "Sedang melakukan uji layar hitam dengan 10 transisi cepat"
  },
  AvgDialog_21761_Content_11 = {
    Text = [[
[Film Tua] Tes, 2
Selesai]]
  },
  AvgDialog_21761_Content_12 = {
    Text = "Selanjutnya, lakukan tes dengan mata tertutup."
  },
  AvgDialog_21761_Content_14 = {
    Text = "Menutup mata bukan efek sirkular, ingat untuk menggunakan 2 untuk mengakhirinya ya."
  },
  AvgDialog_21761_Content_15 = {
    Text = "Selanjutnya, cahaya merah berkedip sekali, 1"
  },
  AvgDialog_21761_Content_17 = {
    Text = "Kilatan cahaya merah bukan efek sirkulasi, ingatlah untuk mengakhirinya dengan 2 ya."
  },
  AvgDialog_21761_Content_3 = {
    Text = "Sedang melakukan tes [Kabut], 1"
  },
  AvgDialog_21761_Content_5 = {
    Text = [[
[Kabut Tipis] Tes, 2
Selesai]]
  },
  AvgDialog_21761_Content_6 = {
    Text = "Sedang melakukan tes [Hujan Kecil], 1"
  },
  AvgDialog_21761_Content_8 = {
    Text = [[
[Hujan Kecil] Tes, 2
Selesai]]
  },
  AvgDialog_21761_Content_9 = {
    Text = "Sedang melakukan tes [Film Tua], 1"
  },
  AvgDialog_21801_Content_1 = {
    Text = "Koleksi Teman Besar"
  },
  AvgDialog_21801_Content_10 = {
    Text = "Kenapa jalanmu oleng-oleng begitu, apa kakimu terluka?"
  },
  AvgDialog_21801_Content_11 = {
    Text = "Kamu menoleh ke belakang melihat jalan yang telah kamu lalui: demi menghindari cairan Erosi yang menggenang di mana-mana, jejak kakimu membentuk garis lengkung aneh di atas tanah berlumpur."
  },
  AvgDialog_21801_Content_12 = {
    Text = "Kalau begitu, kalau begitu biar Aurita gendong kamu saja!"
  },
  AvgDialog_21801_Content_13 = {
    Text = "Tidak, tidak perlu. Aku hanya merasa jalan seperti ini lebih seru, Aurita tidak merasa menarik?"
  },
  AvgDialog_21801_Content_14 = {
    Text = "Seperti lompat kotak!"
  },
  AvgDialog_21801_Content_15 = {
    Text = "Ya, seperti lompat kotak."
  },
  AvgDialog_21801_Content_16 = {
    Text = "……Aureta, ayo kita main injak bayangan, mau?"
  },
  AvgDialog_21801_Content_17 = {
    Text = "Aku jalan di depan, kamu ikuti jejak kakiku…… bagaimana?"
  },
  AvgDialog_21801_Content_18 = {
    Text = "Hmm… boleh juga! Kalau begitu teman jalan duluan, Aureta akan menunjukkan jalannya."
  },
  AvgDialog_21801_Content_19 = {
    Text = "Aureta dengan patuh mundur dua langkah untuk memberimu jalan, dan saat melompat-lompat, dia hampir menginjak genangan cairan korosi."
  },
  AvgDialog_21801_Content_2 = {
    Text = "Hm~ hmhmhm~"
  },
  AvgDialog_21801_Content_20 = {
    Text = "Kamu segera menariknya, tapi dia sama sekali tidak menyadarinya dan hanya mengerjapkan mata, wajahnya masih dipenuhi kegembiraan karena permainan telah dimulai."
  },
  AvgDialog_21801_Content_21 = {
    Text = "Tut tut—— Kereta kecil berangkat! Alun-alun pusat—— belok kiri!"
  },
  AvgDialog_21801_Content_3 = {
    Text = "Aurita bersenandung riang, berjalan berdampingan denganmu di jalanan yang telah tergerus oleh Erosi."
  },
  AvgDialog_21801_Content_4 = {
    Text = "Jendela-jendela gelap tanpa lampu menunjukkan bahwa tempat ini sudah lama ditinggalkan penghuninya. Di kedua sisi jalan yang sunyi, hanya tersisa siluet reruntuhan bangunan."
  },
  AvgDialog_21801_Content_5 = {
    Text = "Ke mana para penduduk itu? Apakah mereka sudah pergi sebelum fenomena Erosi meledak, apakah mereka menemukan tempat tinggal baru, atau…"
  },
  AvgDialog_21801_Content_6 = {
    Text = "Cairan hitam kental mengalir tanpa suara di dekat kakimu. Kamu menarik napas dalam-dalam, menahan rasa mual yang hampir naik ke tenggorokan."
  },
  AvgDialog_21801_Content_7 = {
    Text = "Atau… mereka tidak pernah meninggalkan tanah kelahiran yang mereka cintai?"
  },
  AvgDialog_21801_Content_9 = {
    Text = "Gumaman yang dikeluarkan saat berpikir serius menarikmu keluar dari kemurungan. Aurita mengamatimu dari atas ke bawah, lalu akhirnya bertanya dengan bingung."
  },
  AvgDialog_21803_Content_1 = {
    Text = "Istana di Dalam Air"
  },
  AvgDialog_21803_Content_10 = {
    Text = "Benarkah! Terima kasih, Nenek!"
  },
  AvgDialog_21803_Content_11 = {
    Text = "Nenek Betty membujuk Aurita dengan beberapa kata saja, menatap gadis itu berlari melompat-lompat ke reruntuhan di sisi lain, baru kemudian berbalik ke arahmu dengan senyuman."
  },
  AvgDialog_21803_Content_12 = {
    Text = "Anda sengaja menyuruh Aurita pergi, sebenarnya apa yang ingin Anda bicarakan dengan saya?"
  },
  AvgDialog_21803_Content_13 = {
    Text = "Jangan terlalu waspada, aku hanya ingin… menceritakan sebuah kisah."
  },
  AvgDialog_21803_Content_14 = {
    Text = "Dulu, tempat ini adalah pelabuhan nelayan. Anak muda yang punya cita-cita pergi ke kota, ada juga yang tetap tinggal di kampung halaman dan hidup dari menangkap ikan… Tenang dan damai, tak berbeda dari desa nelayan lainnya."
  },
  AvgDialog_21803_Content_15 = {
    Text = "Perubahan terjadi tanpa disadari. Tanpa terasa, yang tersisa di sini hanyalah para wanita dan anak-anak."
  },
  AvgDialog_21803_Content_16 = {
    Text = "Perahu-perahu nelayan pergi satu per satu, tapi yang kembali ke pantai terbawa arus hanyalah potongan-potongan lunas kapal yang hancur."
  },
  AvgDialog_21803_Content_17 = {
    Text = "Air hitam meluap melewati tanggul, jalanan tergerus hingga hancur berkeping-keping."
  },
  AvgDialog_21803_Content_18 = {
    Text = "Saat Aurita tersadar, teman-teman bermainnya, keluarganya, bahkan seluruh penduduk kota kecil ini, semuanya sudah lenyap tanpa jejak…"
  },
  AvgDialog_21803_Content_19 = {
    Text = "Tunggu, lalu bagaimana dengan Nenek sendiri?"
  },
  AvgDialog_21803_Content_2 = {
    Text = "Wanita tua yang menyebut dirinya Betty tersenyum sambil mengamatimu, tampaknya sedang menilai kelayakanmu sebagai \"teman Aurita\" tanpa meninggalkan jejak."
  },
  AvgDialog_21803_Content_20 = {
    Text = "Dia menggelengkan kepala, mengisyaratkanmu untuk melihat ke tubuh bagian bawahnya."
  },
  AvgDialog_21803_Content_21 = {
    Text = [[
Yang mengalir keluar dari balik rok kain goninya, ternyata adalah cairan korosi.
Tubuh bagian bawahnya hampir sepenuhnya terendam dalam kehancuran dan kekosongan.]]
  },
  AvgDialog_21803_Content_22 = {Text = "?!"},
  AvgDialog_21803_Content_23 = {
    Text = "A-Anda, bagaimana kondisi tubuh Anda sekarang?"
  },
  AvgDialog_21803_Content_24 = {
    Text = "Wanita tua itu tertawa kecil. Dia menepuk bahumu, seperti seorang tetua sejati."
  },
  AvgDialog_21803_Content_25 = {
    Text = "Jangan takut, Anak Muda, jangan takut."
  },
  AvgDialog_21803_Content_26 = {
    Text = "\"Nenek Betty\" sudah lama menghilang. Obsesi anak itu-lah yang membuatku tetap berada di sini."
  },
  AvgDialog_21803_Content_27 = {
    Text = [[
Saat berbicara, angin entah dari mana meniupkan selembar selebaran.
Gambar di atas kertas itu sebagian besar sudah dihitamkan oleh cairan korosi, tapi kata-kata promosinya masih samar-samar terlihat.]]
  },
  AvgDialog_21803_Content_28 = {
    Text = "\"Toko Roti Betty, roti buatan tangan ala nenek kampung halaman\""
  },
  AvgDialog_21803_Content_29 = {
    Text = "Astaga… sepertinya, \"Betty\" belum tentu nama asliku."
  },
  AvgDialog_21803_Content_3 = {
    Text = "Setelah cukup lama, dia akhirnya menarik tatapannya dan menepuk punggung Aurita."
  },
  AvgDialog_21803_Content_30 = {
    Text = "…Kenapa Anda menceritakan semua ini kepada saya?"
  },
  AvgDialog_21803_Content_31 = {
    Text = "Nenek Betty memandang ke arah gedung bobrok yang miring tak jauh dari sana. Aurita sedang \"berburu harta karun\" di sana, membuat debu beterbangan ke mana-mana."
  },
  AvgDialog_21803_Content_32 = {
    Text = "Agar Aurita tidak bersedih, aku sudah berbohong banyak kepadanya."
  },
  AvgDialog_21803_Content_33 = {
    Text = "Misalnya…"
  },
  AvgDialog_21803_Content_34 = {
    Text = "\"Rumah di dalam laut\""
  },
  AvgDialog_21803_Content_35 = {
    Text = "Dia bahkan memberitahumu soal itu? Sepertinya dia benar-benar percaya dengan cerita itu……\nTapi selain merangkai kebohongan, apa lagi yang bisa dilakukan nenek tirinya?"
  },
  AvgDialog_21803_Content_36 = {
    Text = [[
Bisakah kita memberitahunya bahwa orang tuanya tidak akan pernah kembali lagi?
Di kota yang tak punya masa depan ini, kata-kata seperti itu terlalu kejam.]]
  },
  AvgDialog_21803_Content_37 = {
    Text = "Karena itu, aku ingin memohon satu hal kepadamu……Tolong, tolong rahasiakan ini darinya."
  },
  AvgDialog_21803_Content_38 = {
    Text = "Jangan beritahu dia apa yang sedang terjadi di dunia nyata……Setidaknya, biarkan dia pergi dalam kebahagiaan."
  },
  AvgDialog_21803_Content_39 = {
    Text = "Ini adalah keinginanku, dan juga……keinginannya."
  },
  AvgDialog_21803_Content_4 = {
    Text = [[
Aurita, pergi main sendiri dulu sebentar, ya.
Nenek mau ngobrol sebentar dengan teman baru ini, nanti segera menyusulmu.]]
  },
  AvgDialog_21803_Content_40 = {
    Text = "Nada bicara Nenek Betty begitu tulus, suaranya bahkan terdengar memohon."
  },
  AvgDialog_21803_Content_41 = {Text = "Pergi?"},
  AvgDialog_21803_Content_42 = {
    Text = "Jelas-jelas tidak ada apa-apa sama sekali!"
  },
  AvgDialog_21803_Content_43 = {
    Text = "Apa Nenek benar-benar menyembunyikan boneka tanah liatnya di sana? Oreta sudah mengobrak-abrik semuanya!"
  },
  AvgDialog_21803_Content_44 = {
    Text = [[
Suara Oreta yang kesal membuatmu refleks menoleh ke arahnya. Dia berdiri di atas reruntuhan dengan punggung menghadapmu.
Kali ini, kamu akhirnya melihat dengan jelas noda hitam yang sempat berkilat di punggungnya.]]
  },
  AvgDialog_21803_Content_45 = {
    Text = "Di tubuh mungilnya, terdapat sebuah rongga yang menganga — itu jelas-jelas adalah bekas korosi yang sangat besar."
  },
  AvgDialog_21803_Content_46 = {
    Text = [[
Kamu tertegun, lalu menoleh ke tempat "Nenek Betty" tadi berdiri.
Di sana hanya tersisa genangan cairan kental, menyatu dengan air kotor yang menghitam.]]
  },
  AvgDialog_21803_Content_47 = {
    Text = "Di dalam genangan kotor itu, keramik memantulkan cahaya yang lembut."
  },
  AvgDialog_21803_Content_48 = {
    Text = "Ambil boneka keramik"
  },
  AvgDialog_21803_Content_49 = {
    Text = "Di luar dugaan, setelah \"Nenek Betty\" menghilang, yang tertinggal bukanlah boneka keramik berbentuk wanita tua."
  },
  AvgDialog_21803_Content_5 = {
    Text = "Aurita tidak boleh ikut ngobrol?"
  },
  AvgDialog_21803_Content_50 = {
    Text = "Tudung payung yang bulat dan penuh, tentakel yang halus dan rapat, dihiasi glasir biru bermotif daun semanggi empat di atas dasar putih porselen."
  },
  AvgDialog_21803_Content_51 = {
    Text = "Waaah — ini ubur-ubur favorit Oreta!"
  },
  AvgDialog_21803_Content_52 = {
    Text = "Ternyata kamu curang! Kamu menipu Oreta untuk mencari di sana, padahal jelas-jelas ada di tanganmu!"
  },
  AvgDialog_21803_Content_53 = {
    Text = "Ja-jangan marah…Lihat, ini apa?"
  },
  AvgDialog_21803_Content_54 = {
    Text = "Kamu memaksakan sebuah senyuman, lalu mengeluarkan \"Poni\" dan \"Salju\" dari saku, dan menyerahkannya bersama patung tanah liat \"Ubur-ubur\" kepada Oreta."
  },
  AvgDialog_21803_Content_55 = {
    Text = "Semuanya untuk Oreta?! Terima kasih, teman!"
  },
  AvgDialog_21803_Content_56 = {
    Text = "Akuarium~ Akuarium Oreta~"
  },
  AvgDialog_21803_Content_57 = {
    Text = "Istana~ Teman dan istana di dalam air~"
  },
  AvgDialog_21803_Content_58 = {
    Text = "Oreta bersenandung riang, tenggelam dalam kegembiraan mendapatkan mainan baru. Vitter, Poni, Salju, dan Nenek Betty tampaknya tidak meninggalkan bekas sedikit pun di hatinya."
  },
  AvgDialog_21803_Content_59 = {
    Text = "Hei yo… Hei yo…… Apakah semuanya berdiri seperti ini sudah oke?"
  },
  AvgDialog_21803_Content_6 = {
    Text = "Anak baik, topik pembicaraan orang dewasa, kamu pasti akan bosan mendengarnya. Aurita kecil kita kan paling takut bosan?"
  },
  AvgDialog_21803_Content_60 = {
    Text = "Taruh \"Poni\" lebih ke luar sedikit, seekor kuda berdiri di dalam ruangan rasanya agak aneh."
  },
  AvgDialog_21803_Content_61 = {
    Text = "Benar juga! Ngomong-ngomong, apakah \"Poni\" itu nama yang kamu berikan?"
  },
  AvgDialog_21803_Content_63 = {
    Text = "Istana Oreta sudah selesai ditata!"
  },
  AvgDialog_21803_Content_64 = {
    Text = "Rumah Oreta nanti, rumah Oreta di dalam air……"
  },
  AvgDialog_21803_Content_65 = {
    Text = "Oreta mau tidur di kamar sebelah Papa dan Mama, kadang-kadang juga mau tidur bersama mereka!"
  },
  AvgDialog_21803_Content_66 = {
    Text = "Anjing kecil tidur di tempat tidur Oreta, kuda kecil di ruang tamu——di taman."
  },
  AvgDialog_21803_Content_67 = {
    Text = "Ubur-ubur boleh melayang-layang di mana saja, dan teman-teman Oreta semuanya harus minum cokelat panas di depan perapian……"
  },
  AvgDialog_21803_Content_68 = {
    Text = "Hmm… di dasar air…… bisa menyalakan perapian tidak?"
  },
  AvgDialog_21803_Content_69 = {
    Text = "Mata Oreta berkedip-kedip, ternyata mulai terlihat mengantuk. Dia menguap panjang, tatapannya sayu."
  },
  AvgDialog_21803_Content_7 = {
    Text = "Uuu…uuuu……tapi aku ingin bersama Nenek……"
  },
  AvgDialog_21803_Content_70 = {
    Text = "Oreta mengantuk?"
  },
  AvgDialog_21803_Content_71 = {
    Text = "Oreta… masih bisa…… main……"
  },
  AvgDialog_21803_Content_72 = {
    Text = "Tidurlah dengan tenang, Oreta."
  },
  AvgDialog_21803_Content_73 = {
    Text = "Perapiannya akan menyala hangat."
  },
  AvgDialog_21803_Content_74 = {
    Text = "Cokelat panas yang disajikan akan ditambahkan banyak sekali gula."
  },
  AvgDialog_21803_Content_75 = {
    Text = "Saat kau terbangun, teman-temanmu akan ada di sini."
  },
  AvgDialog_21803_Content_76 = {
    Text = "Hh… Teman……"
  },
  AvgDialog_21803_Content_77 = {
    Text = "Jangan… tinggalkan Aurita sendirian ya……"
  },
  AvgDialog_21803_Content_8 = {
    Text = "Anak baik Nenek, ayo main permainan dengan Nenek?"
  },
  AvgDialog_21803_Content_9 = {
    Text = "Aurita kan ingin menghias rumah teman-teman? Nenek menyembunyikan beberapa patung keramik kecil di sekitar sini……kalau Aurita menemukannya, semuanya jadi milik Aurita."
  },
  AvgDialog_21805_Content_1 = {
    Text = "Hari yang Sunyi"
  },
  AvgDialog_21805_Content_10 = {
    Text = "Ah……tidak boleh! Air di dalamnya tidak boleh diminum! Kamu kan sudah minum sebanyak itu."
  },
  AvgDialog_21805_Content_11 = {
    Text = "Aku ini hampir mati tenggelam, bukan karena kebanyakan minum air."
  },
  AvgDialog_21805_Content_12 = {
    Text = "Menghadapi ekspresi polos gadis itu yang cemberut kesal, kamu merasakan nyeri di paru-paru. Setelah beberapa kali menarik napas dalam, akal sehat akhirnya kembali memenuhi otakmu."
  },
  AvgDialog_21805_Content_13 = {
    Text = "Kehendak beresonansi dengan ingatan, kamu akhirnya menyadari bahwa sekali lagi, kamu telah memasuki kenangan sang Awakened—"
  },
  AvgDialog_21805_Content_14 = {
    Text = "Tenggelam…tenggelam……"
  },
  AvgDialog_21805_Content_15 = {
    Text = "Aurita sangat pandai berenang! Selama kamu menjadi teman Aurita, kamu tidak akan tenggelam lagi!"
  },
  AvgDialog_21805_Content_16 = {
    Text = "Aurita berputar-putar mengelilingi tempat tidur dengan ribut, sambil dengan susah payah menyalakan perapian di kamar."
  },
  AvgDialog_21805_Content_17 = {
    Text = "Diiringi batuk gadis itu yang tersedak abu perapian, ruangan perlahan menghangat, pakaian yang basah mengeluarkan beberapa uap air, dan anggota tubuh yang membeku berangsur pulih kehangatannya."
  },
  AvgDialog_21805_Content_18 = {
    Text = "Aurita… Kamu Aurita, kalau begitu ini rumahmu……"
  },
  AvgDialog_21805_Content_19 = {
    Text = "Mm-hm! Ini rumah Aurita, dan kamu adalah tamu yang Aurita undang dari laut!"
  },
  AvgDialog_21805_Content_2 = {
    Text = "Uhuk…uhuk uhuk!"
  },
  AvgDialog_21805_Content_20 = {
    Text = "Pecahan Memori tubuh muncul ke permukaan, kamu perlahan memahami peran yang kamu mainkan dalam Mimpi ini —"
  },
  AvgDialog_21805_Content_21 = {
    Text = "Seorang awak kapal yang jatuh ke laut saat badai, terdorong ke pantai oleh ombak yang berbaik hati, dan akhirnya diseret pulang oleh gadis di hadapanmu……"
  },
  AvgDialog_21805_Content_22 = {
    Text = "Identitas yang biasa-biasa saja."
  },
  AvgDialog_21805_Content_23 = {
    Text = "Kamu sudah cukup terbiasa dengan pengalaman luar biasa seperti \"memasuki mimpi\". Biasanya, begitu kamu menyaksikan ingatan yang membentuk mimpi tersebut, kamu akan terbangun pada saat yang tepat."
  },
  AvgDialog_21805_Content_24 = {
    Text = "Masalahnya sekarang adalah, kamu tidak bisa memastikan \"ingatan\" Aurita."
  },
  AvgDialog_21805_Content_25 = {
    Text = "\"Ingatan\" Aurita adalah sebuah misteri. Erosi telah melahap masa lalunya sebelum dia dibangunkan, dan dari tutur katanya yang seperti anak kecil, sulit menemukan detail yang cukup untuk menyusun gambaran utuh."
  },
  AvgDialog_21805_Content_26 = {
    Text = "Sekarang, mungkin ini saat yang tepat untuk mengisi kekosongan dalam arsip Aurita."
  },
  AvgDialog_21805_Content_27 = {
    Text = "Kenapa? Kenapa diam begitu lama?"
  },
  AvgDialog_21805_Content_28 = {
    Text = "Kalau kamu tidak mau bermain dengan Aurita, mengantarmu pergi juga bukan hal yang tidak bisa dilakukan…"
  },
  AvgDialog_21805_Content_29 = {
    Text = "Secepat itu mau mengusir tamu?"
  },
  AvgDialog_21805_Content_3 = {
    Text = "Cairan terdorong keluar dari saluran napas oleh hantaman keras, rasa asin amis air laut tiba-tiba menyerbu ke tenggorokan, menari liar di pangkal lidah bagaikan tarian cancan yang membara."
  },
  AvgDialog_21805_Content_30 = {
    Text = "Mengusir… tamu?"
  },
  AvgDialog_21805_Content_31 = {
    Text = "Maksudmu, kamu mau bermain bersama Aurita!"
  },
  AvgDialog_21805_Content_32 = {
    Text = [[
Hore hore hore!
Tamu baru, teman baru, <Yellow:teman baru untuk akuarium> Aurita!]]
  },
  AvgDialog_21805_Content_33 = {Text = "Akuarium?"},
  AvgDialog_21805_Content_34 = {
    Text = "Akuarium? Jangan-jangan, yang kamu maksud itu tabung kaca itu?"
  },
  AvgDialog_21805_Content_35 = {
    Text = "Itu persiapan yang dilakukan Aurita untuk mendekorasi rumah barunya di masa depan lho!"
  },
  AvgDialog_21805_Content_36 = {
    Text = "Gadis itu melambaikan tangannya dengan penuh semangat, dan akhirnya kamu pun memperhatikan dengan saksama akuarium kaca berisi air di dekat jendela itu——"
  },
  AvgDialog_21805_Content_37 = {
    Text = [[
Di dalamnya terdapat dekorasi kastil yang indah, namun riak kehidupan yang seharusnya ada tak dapat ditemukan di mana pun.
Tak ubahnya sebuah dongeng yang tenggelam.]]
  },
  AvgDialog_21805_Content_38 = {
    Text = "Teman baru?"
  },
  AvgDialog_21805_Content_39 = {
    Text = "Um! Teman baru Aurita! Kalau nanti Aurita sudah kembali ke rumah di laut dan berkumpul lagi dengan Papa dan Mama, semua teman Aurita bisa datang berkunjung."
  },
  AvgDialog_21805_Content_4 = {
    Text = "Wah! Kamu minum banyak sekali air!"
  },
  AvgDialog_21805_Content_40 = {
    Text = "Jelas-jelas kamu sedang berbaring di atas kasur yang empuk, tapi kata-kata Aurita entah mengapa membuatmu merasakan dingin merambat di punggung."
  },
  AvgDialog_21805_Content_41 = {
    Text = "Saat itulah kamu menyadari——terlalu sunyi."
  },
  AvgDialog_21805_Content_42 = {
    Text = "Suara serangga, angin, daun-daun yang saling bergesekan……\nPercakapan, canda tawa, suara sepatu yang menggesek jalanan……"
  },
  AvgDialog_21805_Content_43 = {
    Text = "Dunia ini sunyi senyap, hanya Aurita sebagai pemilik mimpi ini yang hidup dan nyata."
  },
  AvgDialog_21805_Content_44 = {
    Text = "Aurita……tinggal sendirian di sini?"
  },
  AvgDialog_21805_Content_45 = {
    Text = "Sendirian? Tidak kok. Vitter, Shiroyuki, Polni…… Teman-teman Aurita semuanya ada di kota!\nDan juga Nenek, <Yellow:Nenek> Aurita juga tinggal bersama Aurita!"
  },
  AvgDialog_21805_Content_46 = {
    Text = "Oh iya! Nenek! Nenek pernah bilang, kalau Aurita punya teman baru, Aurita harus memperkenalkannya pada Nenek juga!"
  },
  AvgDialog_21805_Content_47 = {
    Text = "Saat menyebut \"Nenek\", mata Aurita langsung berbinar, ia melompat-lompat kembali ke depan tempat tidur dan hendak menarikmu bangun, tapi seolah teringat sesuatu, gerakannya tiba-tiba terhenti."
  },
  AvgDialog_21805_Content_48 = {
    Text = "Kamu masih mau minum air?"
  },
  AvgDialog_21805_Content_49 = {
    Text = "Itu tenggelam……"
  },
  AvgDialog_21805_Content_5 = {
    Text = "Bau air laut dan darah memenuhi rongga hidung yang terendam terlalu lama. Seiring batukmu yang hebat, bahkan butiran pasir kasar tersembur keluar dari dalam rongga hidungmu."
  },
  AvgDialog_21805_Content_50 = {
    Text = "Aku juga ingin bertemu keluarga Aurita. Bisakah Aurita membawaku menemui Nenek?"
  },
  AvgDialog_21805_Content_51 = {
    Text = "Um! Nenek seharusnya ada di alun-alun pusat kota!"
  },
  AvgDialog_21805_Content_52 = {
    Text = "Aurita melangkah riang menuruni tangga, kamu pun tak lagi ragu, menepuk-nepuk pipi agar benar-benar tersadar sepenuhnya."
  },
  AvgDialog_21805_Content_53 = {
    Text = "Di luar agak gerimis——"
  },
  AvgDialog_21805_Content_54 = {
    Text = "Suara Aurita terdengar dari luar rumah, terhalang pintu kayu, suaranya yang jernih dan riang pun terdengar tak begitu jelas lagi."
  },
  AvgDialog_21805_Content_55 = {
    Text = "Kamu menarik napas dalam-dalam, mendorong pintu dan meninggalkan bangunan kecil tempat Aurita tinggal."
  },
  AvgDialog_21805_Content_56 = {
    Text = "Rumah-rumah miring ditelan oleh tanah, gunung di kejauhan dan sungai kecil di dekatmu tertarik mengeluarkan kabut hitam yang halus."
  },
  AvgDialog_21805_Content_57 = {
    Text = "Yang muncul di hadapanmu adalah sebuah kota yang tenggelam oleh Erosi—"
  },
  AvgDialog_21805_Content_58 = {
    Text = "Aurita suka kehujanan gerimis, rasanya sejuk dan nyaman!"
  },
  AvgDialog_21805_Content_59 = {
    Text = "Hmm… tapi, lebih baik kucarikan payung untukmu."
  },
  AvgDialog_21805_Content_6 = {
    Text = "Aku ini……"
  },
  AvgDialog_21805_Content_60 = {
    Text = [[
Senyap sunyi, semua yang terlihat hanyalah kegelapan.
Di tengah kekacauan, hanya sosok Aurita yang masih tampak hidup.]]
  },
  AvgDialog_21805_Content_7 = {
    Text = "Perlahan membuka mata, yang terlihat adalah langit-langit yang asing."
  },
  AvgDialog_21805_Content_8 = {
    Text = "Tua, rapi, tapi tanpa ciri khas. Hanya sebuah akuarium kaca berisi air yang membuat tempat ini tidak terlalu mirip kamar hotel biasa."
  },
  AvgDialog_21805_Content_9 = {
    Text = "Kamu sedang melihat apa? Melihat rumah teman-teman Aurita ya?"
  },
  AvgDialog_21813_Content_1 = {
    Text = "……@2…ta……\n@4……"
  },
  AvgDialog_21813_Content_10 = {
    Text = "Eh…? Siapa namanya tadi ya……"
  },
  AvgDialog_21813_Content_12 = {
    Text = "Oreta, jangan lupa, kita harus pergi ke alun-alun pusat untuk menemui nenekmu."
  },
  AvgDialog_21813_Content_13 = {
    Text = "Oh iya! Kalau begitu lewat sini sini—"
  },
  AvgDialog_21813_Content_14 = {
    Text = "Oreta seketika melupakan teman kecilnya yang \"kabur\" itu, mendorongmu untuk terus berjalan menuju tujuan."
  },
  AvgDialog_21813_Content_15 = {
    Text = "Kamu mengangkat kaki, melangkahi genangan cairan Korosi yang dulunya adalah \"Vitter\", hatimu dipenuhi perasaan campur aduk."
  },
  AvgDialog_21813_Content_16 = {
    Text = "Hidup di kota yang nyaris habis terkorosi, namun tak mampu melihat atau merasakan keberadaan Korosi itu."
  },
  AvgDialog_21813_Content_17 = {
    Text = "Dunianya sedang mati, tapi dia…… sama sekali tidak menyadarinya."
  },
  AvgDialog_21813_Content_2 = {
    Text = "Tubuh yang bermutasi itu roboh kaku ke tanah bagaikan kulit sapi yang terlalu banyak disamak, perlahan menyatu dengan cairan Korosi di permukaan tanah, hingga akhirnya lenyap sepenuhnya dari pandangan."
  },
  AvgDialog_21813_Content_3 = {
    Text = "Eh……? Mana Vitter?"
  },
  AvgDialog_21813_Content_4 = {
    Text = "Kok tiba-tiba menghilang begitu saja! Oreta kan tidak mengajaknya main petak umpet……"
  },
  AvgDialog_21813_Content_5 = {
    Text = "Di tempat \"Vitter\" pernah duduk, sebuah figurin keramik loper koran kecil tergeletak di tanah."
  },
  AvgDialog_21813_Content_7 = {
    Text = "Oreta, Vitter meninggalkan hadiah untukmu."
  },
  AvgDialog_21813_Content_8 = {
    Text = "Mana mana— Wah! Ini figurin yang katanya mau diberikan untuk Oreta!"
  },
  AvgDialog_21813_Content_9 = {
    Text = "Oreta mau menaruhnya di rumah teman-teman! Terima kasih, terima kasih……"
  },
  AvgDialog_21814_Content_1 = {
    Text = "Ah! Itu Vitter!"
  },
  AvgDialog_21814_Content_10 = {
    Text = "Kalau Aureta sudah kembali nanti, pasti akan mengajak semua orang berkunjung."
  },
  AvgDialog_21814_Content_11 = {
    Text = "Sebelum kamu sempat merenungkan rasa dingin yang tersirat dari kata-kata Aureta, \"teman\" Aureta tiba-tiba bergerak."
  },
  AvgDialog_21814_Content_12 = {
    Text = "……@2…ta……"
  },
  AvgDialog_21814_Content_13 = {
    Text = [[
Anak laki-laki itu berdiri dengan terhuyung-huyung, cairan hitam merembes keluar dari tubuhnya.
Cairan korosi itu merekatkan tubuhnya dengan tanah, dan saat dia bangkit, suara daging yang tersobek terdengar sangat mengerikan.]]
  },
  AvgDialog_21814_Content_14 = {
    Text = "Mm-hm! Vitter jangan terburu-buru, aku pasti akan menyisakan kamar tamu paling mewah untukmu!"
  },
  AvgDialog_21814_Content_15 = {
    Text = "Di balik kulit pucat itu, otot-ototnya bergerak aneh, seolah-olah sesuatu akan menembus keluar dari dalam—"
  },
  AvgDialog_21814_Content_16 = {
    Text = "Oreta, hati-hati!"
  },
  AvgDialog_21814_Content_2 = {
    Text = "Gadis itu menepuk punggungmu dengan keras, dan atas isyaratnya, kamu menoleh ke arah pemuda yang duduk di sudut jalan."
  },
  AvgDialog_21814_Content_3 = {
    Text = [[
Aureta berlari ke arahnya dengan penuh semangat, dan di sela gerakannya, tampak sekilas noda hitam di punggungnya.
Tapi sebelum kamu sempat melihat jelas, gadis itu sudah melesat melewatimu bagai angin.]]
  },
  AvgDialog_21814_Content_4 = {
    Text = "Vitter, lihat teman baru kita!"
  },
  AvgDialog_21814_Content_5 = {
    Text = "Anak laki-laki itu meringkuk di sudut tembok, menundukkan kepala, tanpa reaksi sama sekali terhadap kedatangan Aureta."
  },
  AvgDialog_21814_Content_6 = {
    Text = "{Male=Dia,Female=Dia} lebih tinggi dari kita semua, nanti kalau kita kembali ke Istana Lautan, kita suruh {Male=dia,Female=dia} jalan paling depan! Pasti terlihat gagah!"
  },
  AvgDialog_21814_Content_7 = {
    Text = "Istana Lautan?"
  },
  AvgDialog_21814_Content_8 = {
    Text = "Nenek pernah bilang, Aureta adalah anak lautan, suatu hari nanti kita akan kembali ke dalam air."
  },
  AvgDialog_21814_Content_9 = {
    Text = "Seperti ayah dan ibu Aureta, mereka sudah lebih dulu kembali ke dalam air untuk menata rumah baru! Setelah mereka selesai mempersiapkan semuanya, Aureta akan kembali bersama nenek untuk menemui mereka."
  },
  AvgDialog_21815_Content_1 = {
    Text = "Oreta mendorongmu berjalan melewati kota yang telah lapuk. Seiring berjalannya waktu, langit yang sudah dipenuhi awan gelap semakin kelam."
  },
  AvgDialog_21815_Content_10 = {
    Text = "Benar! Berubah jadi kuda laut!"
  },
  AvgDialog_21815_Content_11 = {
    Text = "Saat berbicara, dari kejauhan sudah terdengar ringkikan dan dengus kuda. Suara langkahnya terlalu berat, sulit untuk menentukan dari suaranya saja apakah \"Poni\" adalah mutan erosi yang lain."
  },
  AvgDialog_21815_Content_12 = {
    Text = "Poni, Poni——"
  },
  AvgDialog_21815_Content_13 = {
    Text = "Hiiiiii————"
  },
  AvgDialog_21815_Content_14 = {
    Text = "Kali ini, kamu yang sudah siap dengan sigap menangkap kerah baju Oreta, mencegahnya berlari menuju teman besarnya yang hanya tersisa kerangka tulang."
  },
  AvgDialog_21815_Content_2 = {
    Text = "Oreta, seberapa jauh lagi kita dari alun-alun?"
  },
  AvgDialog_21815_Content_3 = {
    Text = "Gadis itu menelungkup di punggungmu, menjulurkan kepalanya sambil menoleh ke kiri dan kanan, lalu akhirnya menunjuk ke sebuah tikungan."
  },
  AvgDialog_21815_Content_4 = {
    Text = "Di sana! Setelah melewati kandang kuda di sana, jalan ke utara lima puluh meter lagi sampai!"
  },
  AvgDialog_21815_Content_5 = {
    Text = "Di sini dulu pernah memelihara kuda?"
  },
  AvgDialog_21815_Content_6 = {
    Text = "Sekarang juga ada! Poni juga teman Oreta, Oreta mau membawanya pulang ke rumah di laut!"
  },
  AvgDialog_21815_Content_7 = {
    Text = "Kalau sudah di sana, Poni akan berubah jadi……"
  },
  AvgDialog_21815_Content_8 = {
    Text = "Berubah jadi……"
  },
  AvgDialog_21815_Content_9 = {
    Text = "Berubah jadi kuda laut?"
  },
  AvgDialog_21816_Content_1 = {
    Text = "Salju Putih! Itu Salju Putih!"
  },
  AvgDialog_21816_Content_2 = {
    Text = "Oreta sekali lagi melepaskan tanganmu, berlari langsung menuju sesuatu yang terbaring di genangan cairan Korosi—"
  },
  AvgDialog_21816_Content_3 = {
    Text = "Seekor anjing kecil berwarna hitam."
  },
  AvgDialog_21816_Content_4 = {
    Text = "Ba, Bai Xue?"
  },
  AvgDialog_21817_Content_1 = {
    Text = "Dua kali sebelumnya meninggalkan mainan kecil, kali ini seharusnya juga……"
  },
  AvgDialog_21817_Content_2 = {
    Text = "Kamu mengambil garpu jerami di kandang kuda, lalu mengaduk-aduk cairan korosi yang dulunya adalah \"Pony\". Benar saja, sebuah kuda kecil keramik yang sangat halus memantulkan cahaya di dalamnya."
  },
  AvgDialog_21817_Content_3 = {
    Text = "Ambil \"Pony\""
  },
  AvgDialog_21817_Content_4 = {
    Text = "Kamu ragu sesaat, tapi akhirnya melepas jaketmu dan mengambil kuda keramik kecil itu melalui kain."
  },
  AvgDialog_21817_Content_5 = {
    Text = "Kalian sedang apa?"
  },
  AvgDialog_21817_Content_6 = {
    Text = "Saat kamu hampir terbiasa dengan dunia kosong yang hanya dipenuhi suara Aurita, sebuah suara tua tiba-tiba terdengar, membuatmu langsung berdiri tegak."
  },
  AvgDialog_21817_Content_7 = {
    Text = "Nenek—— Aurita membawa teman baru untuk menemui Nenek!"
  },
  AvgDialog_21817_Content_8 = {
    Text = "Wajah tua itu mengembangkan senyum penuh kasih sayang. Dia mengelus kepala Aurita dengan penuh sayang, baru kemudian berbalik ke arahmu."
  },
  AvgDialog_21817_Content_9 = {
    Text = "Halo, anak muda. Aku nenek Aurita, Betty. Seperti anak ini, panggil saja aku Nenek."
  },
  AvgDialog_21818_Content_1 = {
    Text = "\"Bai Xue\" mengeluarkan lolongan rendah, keempat kakinya perlahan larut dalam cairan erosi, tak lagi bisa dikenali sebagai bentuk anjing."
  },
  AvgDialog_21818_Content_2 = {
    Text = "Di tempat \"Bai Xue\" menghilang, sebuah patung anjing kecil dari keramik putih seukuran telapak tangan terbaring diam di sana."
  },
  AvgDialog_21818_Content_3 = {
    Text = "Memungut \"Bai Xue\""
  },
  AvgDialog_21818_Content_4 = {
    Text = "Ternyata kamu memang berwarna putih……"
  },
  AvgDialog_21875_Content_1 = {
    Text = "Sepertinya jebakan telah berhasil menahannya."
  },
  AvgDialog_21875_Content_2 = {
    Text = "Gunakan alat-alat ini untuk menangkapnya!"
  },
  AvgDialog_22111_Content_1 = {Text = "Ah!——"},
  AvgDialog_22111_Content_10 = {
    Text = "Di sana... di sana adalah..."
  },
  AvgDialog_22111_Content_100 = {
    Text = "Saya tidak terlalu mengerti, apa artinya sesuatu yang tidak bisa dimengerti oleh semua orang…"
  },
  AvgDialog_22111_Content_101 = {
    Text = "Hmm... menurut saya, puisi bukanlah sekadar kata-kata atau gambar, melainkan lebih seperti sebuah kunci."
  },
  AvgDialog_22111_Content_102 = {Text = "Kunci?"},
  AvgDialog_22111_Content_103 = {
    Text = "Benar! Hati setiap orang seperti sebuah kotak, di dalamnya terdapat banyak sekali perasaan. Kotak ini terkunci, dan perasaan-perasaan itu biasanya terkurung di dalam kotak, ingin mengambilnya pun tidak bisa."
  },
  AvgDialog_22111_Content_104 = {
    Text = "Puisi adalah kunci untuk membuka kotak ini."
  },
  AvgDialog_22111_Content_105 = {
    Text = "Sebenarnya, puisi tidak perlu dipahami, bahkan tidak perlu dibaca."
  },
  AvgDialog_22111_Content_106 = {
    Text = "Setiap orang, baik membaca puisi atau tidak, cepat atau lambat, pada suatu saat dalam hidup mereka, pasti akan menemukan kunci ini."
  },
  AvgDialog_22111_Content_107 = {
    Text = "Kalau begitu, kamu pasti akan menjadi tukang Kunci terbaik!"
  },
  AvgDialog_22111_Content_108 = {
    Text = "Menipu... Baru saja kamu bilang tidak mengerti."
  },
  AvgDialog_22111_Content_109 = {
    Text = "Aku tidak mengerti apa yang kamu katakan. Namun, aku percaya padamu, Horla."
  },
  AvgDialog_22111_Content_11 = {
    Text = "Kalian berdiri di alun-alun tepi taman. D-rongga yang terlihat jelas merambat dari bawah gedung ke atas, mencakup area kosong di tengah taman."
  },
  AvgDialog_22111_Content_110 = {
    Text = "Puisi pertamamu,\"Tempat Tinggal Mawar\", adalah karyamu yang pertama. Mulai hari ini, semua puisimu akan aku simpan dengan baik."
  },
  AvgDialog_22111_Content_111 = {
    Text = "Saya akan menggunakan peniti untuk merapikannya menjadi satu, dan jika saya punya uang nanti, saya akan mencetaknya menjadi sebuah kumpulan Puisi yang indah!"
  },
  AvgDialog_22111_Content_112 = {
    Text = "Dia mengulurkan tangan yang selama ini disembunyikan di belakang tubuhnya. Tangan itu penuh dengan luka bekas duri, hitam dan kasar, sehingga sepenuhnya tidak terlihat seperti tangan seorang gadis."
  },
  AvgDialog_22111_Content_113 = {
    Text = "I-ini... Ini adalah..."
  },
  AvgDialog_22111_Content_114 = {
    Text = "Menurut para bangsawan baru, Cité adalah kota bunga dan puisi. Sebuah puisi indah dapat ditukar dengan seikat mawar…"
  },
  AvgDialog_22111_Content_115 = {
    Text = "Mawar yang kutanam mekar hari ini. Meskipun tidak banyak, semuanya sudah kugunakan untuk membayar sewa rumah dan sewa tanah."
  },
  AvgDialog_22111_Content_116 = {
    Text = "Namun, saat mereka tidak memperhatikan, aku diam-diam meninggalkan satu bunga…"
  },
  AvgDialog_22111_Content_117 = {
    Text = "Tangan yang penuh luka itu menyodorkan sebuah mawar yang agak rusak namun tetap segar merah ke hadapan Horla."
  },
  AvgDialog_22111_Content_118 = {
    Text = "Sebuah puisi yang indah, Horla… Mulai sekarang, aku akan menukar bunga-bungaku dengan puisi-puisimu!"
  },
  AvgDialog_22111_Content_12 = {
    Text = "Itu... taman kita... tidak... Colette, tidak..."
  },
  AvgDialog_22111_Content_13 = {
    Text = "Horla menundukkan kepalanya. Colette mendekatinya, mengangkat dagunya, dan membuatnya memandang ke arah tengah taman."
  },
  AvgDialog_22111_Content_14 = {
    Text = "Apakah kamu tahu, Horla? Banyak tahun yang lalu, di tempat inilah aku melihat api besar itu mulai menyala."
  },
  AvgDialog_22111_Content_15 = {
    Text = "Saya telah mengubah tempat ini menjadi alun-alun, dan di sini saya mendirikan patung saya sendiri… Lihat, saya juga paham akan simbolisme."
  },
  AvgDialog_22111_Content_16 = {
    Text = "Lihat. Lihat dengan jelas. Itulah tempat kita tinggal... itulah taman kita. Segera, segala sesuatu di sana akan lenyap."
  },
  AvgDialog_22111_Content_17 = {
    Text = "Hidupku, secara resmi dimulai pada hari kau meninggal. Hari ini, ia akan kembali menuju kejayaan di sini…"
  },
  AvgDialog_22111_Content_18 = {
    Text = "Celah hitam dengan cepat menyebar. Dalam waktu singkat, vila yang megah itu sepenuhnya ditelan."
  },
  AvgDialog_22111_Content_19 = {
    Text = "Taman, abu, gambar sketsa, puisi, memori, tawa, sumpah… semuanya tenggelam ke dalam kegelapan tanpa ujung."
  },
  AvgDialog_22111_Content_2 = {
    Text = "Serangan kalian berhasil menjatuhkan monster yang dipanggil oleh Colette. Dunia dalam puisi mengalami kegoncangan, dan Cité menampakkan sebagian wujud aslinya."
  },
  AvgDialog_22111_Content_20 = {Text = "Tik——"},
  AvgDialog_22111_Content_21 = {
    Text = "Eh? Mataku, ada apa ini……"
  },
  AvgDialog_22111_Content_22 = {
    Text = "Perasaan seperti tadi adalah... rasa sakit di hati? Mengapa bisa..."
  },
  AvgDialog_22111_Content_23 = {
    Text = "Sebuah tetesan air mata meluncur di wajah Horla."
  },
  AvgDialog_22111_Content_24 = {
    Text = "Air mata jatuh ke tanah, seperti jatuh ke permukaan danau yang tenang tanpa riak. Riak yang tenang itu menyebar tanpa suara, menyapu dunia ilusi ini dan melewati semua hati yang pucat."
  },
  AvgDialog_22111_Content_25 = {
    Text = "!! Tidak... perasaan ini.."
  },
  AvgDialog_22111_Content_26 = {
    Text = "Colette menyadari perubahan emosinya. Dia menatap Horla di sisinya dengan rasa heran."
  },
  AvgDialog_22111_Content_27 = {
    Text = "<LightGray:Ini adalah... kemampuan Horla untuk menyebarkan emosi?!!>"
  },
  AvgDialog_22111_Content_28 = {
    Text = "<LightGray:Kemampuannya mungkin bisa dimanfaatkan! Aku harus memanfaatkan kesempatan ini…>"
  },
  AvgDialog_22111_Content_29 = {
    Text = "Kau ingin membunuhku, menukar puisi untuk mendapatkan kehidupan yang kau inginkan… Apa pun yang kau lakukan, aku tak pernah membencimu, Colette."
  },
  AvgDialog_22111_Content_3 = {
    Text = "Namun, pada saat kalian mendekati Collette, tak terhitung banyaknya sulur bunga muncul dari tanah di sekitarnya. Duri-duri di atas sulur itu menembus tubuh kalian dan mengikat kalian dengan kuat."
  },
  AvgDialog_22111_Content_30 = {
    Text = "Colette yang dulu adalah teman terbaikku. Namun, jika kau menghancurkan tempat ini... maka hanya Colette saat ini yang tersisa."
  },
  AvgDialog_22111_Content_31 = {
    Text = "Aku tidak bisa... melihat Colette yang dulu, dihapus olehmu..."
  },
  AvgDialog_22111_Content_32 = {
    Text = "Lihatlah dirimu, Horla... apa lagi yang bisa kau lakukan selain menulis puisi?"
  },
  AvgDialog_22111_Content_33 = {
    Text = "Kamu benar… aku tidak bisa apa-apa selain menulis puisi…"
  },
  AvgDialog_22111_Content_34 = {
    Text = "Cité adalah kota bunga dan puisi, rumah kita... tapi mawar di sini sudah mati, Colette..."
  },
  AvgDialog_22111_Content_35 = {
    Text = "Mawar-mawar ini adalah yang pernah kau berikan padaku. Hari ini, aku mengembalikannya kepadamu."
  },
  AvgDialog_22111_Content_36 = {
    Text = "Dia melangkah maju."
  },
  AvgDialog_22111_Content_37 = {Text = "Jleb——"},
  AvgDialog_22111_Content_38 = {Text = "Horla!!!"},
  AvgDialog_22111_Content_39 = {
    Text = "Duri tajam merobek pakaiannya dan menusuk kulitnya, namun dia sama sekali tidak mempedulikannya."
  },
  AvgDialog_22111_Content_4 = {
    Text = "Kamu... telah mengotori pakaianku..."
  },
  AvgDialog_22111_Content_40 = {
    Text = "Duri mawar raksasa menembus jantungnya. Darahnya mengalir melalui sulur hitam, melewati cabang pertama."
  },
  AvgDialog_22111_Content_41 = {
    Text = "Bunga hitam dengan cepat layu di cabang. Sebuah kuncup mawar merah muncul dari cabang, merekah, dan mekar sepenuhnya."
  },
  AvgDialog_22111_Content_42 = {
    Text = "Darah mengalir melalui sulur-sulur, seperti urat daun, ke seluruh penjuru kota."
  },
  AvgDialog_22111_Content_43 = {
    Text = "Tempat yang dilaluinya, kegelapan hitam yang suram lenyap. Ia mengembalikan warna dan emosi, serta bunga dan puisi kepada Cité."
  },
  AvgDialog_22111_Content_44 = {
    Text = "Baik... sangat sakit..."
  },
  AvgDialog_22111_Content_45 = {
    Text = "Jantung... seperti tertusuk..."
  },
  AvgDialog_22111_Content_46 = {
    Text = "Itu... Ibu! Ibu..."
  },
  AvgDialog_22111_Content_47 = {
    Text = "Anak... anak saya telah lahir..."
  },
  AvgDialog_22111_Content_48 = {
    Text = "Seiring dengan menyebarluasnya darah, serangkaian gambaran muncul di hadapan orang-orang."
  },
  AvgDialog_22111_Content_49 = {
    Text = "Itu adalah kelahiran baru seorang bayi, nyanyian pengantar tidur seorang ibu, dan perpisahan terakhir para kekasih."
  },
  AvgDialog_22111_Content_5 = {
    Text = "Apakah kamu tahu berapa banyak uang yang dihabiskan untuk membeli pakaian ini?"
  },
  AvgDialog_22111_Content_50 = {
    Text = "Itu adalah momen paling berharga dalam hidup kalian."
  },
  AvgDialog_22111_Content_52 = {
    Text = "Rasa sakit yang luar biasa dialami oleh Horla, bersamaan dengan darahnya, menyebar seperti riak ke seluruh Cité."
  },
  AvgDialog_22111_Content_53 = {
    Text = "Duri mawar menembus tak terhitung banyaknya jantung. Bunga merah segar mekar di hati setiap orang."
  },
  AvgDialog_22111_Content_54 = {
    Text = "Colette, kamu sudah memiliki seluruh Cité, namun kamu masih tinggal di sini."
  },
  AvgDialog_22111_Content_55 = {
    Text = "Tinggal di rumah yang pernah kita impikan untuk ditinggali, tinggal di taman tempat kita pernah hidup bersama…"
  },
  AvgDialog_22111_Content_56 = {
    Text = "Kamu pernah menyelamatkan hidupku. Puisi ini, yang ditulis dengan hidup, kupersembahkan untukmu, untuk taman."
  },
  AvgDialog_22111_Content_57 = {
    Text = "Ini adalah musim semi, sebuah puisi untuk taman."
  },
  AvgDialog_22111_Content_58 = {
    Text = "Horla… kamu…"
  },
  AvgDialog_22111_Content_59 = {
    Text = "Air mata menghapus riasan halusnya, namun dia tidak peduli, membiarkannya meninggalkan jejak kacau yang tidak pantas di wajahnya."
  },
  AvgDialog_22111_Content_6 = {
    Text = "Kemarahan Colette segera menghilang. Dia kembali memasang senyuman yang pantas dan anggun seperti bangsawan."
  },
  AvgDialog_22111_Content_60 = {
    Text = "Colette lupa, sejak kapan air matanya mulai mengalir."
  },
  AvgDialog_22111_Content_61 = {
    Text = "——Gambar-gambar masa lalu terbentang jelas di depan matanya. Ini adalah pertama kalinya dia benar-benar memahami puisi Horla. Akhirnya, dia mengerti apa yang paling dia hargai."
  },
  AvgDialog_22111_Content_62 = {
    Text = "Bukan hanya dia. Semua orang di Cité ini memahami puisi Horla. Mereka tersentuh oleh emosi Horla, hingga tak mampu bergerak."
  },
  AvgDialog_22111_Content_63 = {Text = "Sekarang!"},
  AvgDialog_22111_Content_64 = {
    Text = "Kamu sudah bersiap, kekuatan roh yang kuat memungkinkanmu melepaskan diri dari emosi Horla."
  },
  AvgDialog_22111_Content_65 = {
    Text = "Kamu melepaskan diri dari belenggu duri dan merebut puisi dari tangan Colette."
  },
  AvgDialog_22111_Content_66 = {
    Text = "Selamat tinggal… Cité dalam puisi!"
  },
  AvgDialog_22111_Content_67 = {
    Text = "Cahaya perak berkilauan tiba-tiba. Di bawah sinar yang menyilaukan, D-marka pada Puisi dengan cepat menguap dan melebur."
  },
  AvgDialog_22111_Content_68 = {Text = "Hmm!——"},
  AvgDialog_22111_Content_69 = {
    Text = "Rasa sakit yang menyengat menyerangmu. Kehilangan banyak kekuatan roh membuatmu tidak mampu menanggungnya."
  },
  AvgDialog_22111_Content_7 = {
    Text = "Tidak apa-apa, tidak apa-apa…"
  },
  AvgDialog_22111_Content_70 = {
    Text = "Kumpulan puisi yang telah dibersihkan dari pelarutan berubah menjadi tumpukan naskah tua yang menguning, dijepit bersama dengan penjepit sederhana, dan terjatuh ke tanah."
  },
  AvgDialog_22111_Content_71 = {
    Text = "Ah! Ah!! ——"
  },
  AvgDialog_22111_Content_72 = {
    Text = "Ribuan monster mengaum, terjatuh ke tanah, dan secara bertahap kembali ke bentuk manusia."
  },
  AvgDialog_22111_Content_73 = {
    Text = "Nafsu akan kekuasaan memudar, emosi mulai kembali. Dasar yang menjadi fondasi dunia ini telah lenyap sepenuhnya."
  },
  AvgDialog_22111_Content_74 = {
    Text = "Colette merasakannya."
  },
  AvgDialog_22111_Content_75 = {
    Text = "Dia merasakan kekuatan menghilang. Dia merasakan kedatangan kegagalan. Dia memanggil duri tajam seperti belati dan melangkah menuju Horla."
  },
  AvgDialog_22111_Content_76 = {
    Text = "\"Collette\", kemenangan... Anjing Nyonya Tua telah mati, dan ketika dia memberikan nama anjing itu kepadaku, kamu berada di sampingku."
  },
  AvgDialog_22111_Content_77 = {
    Text = "Ini adalah nama anjing, tapi aku tak pernah menggantinya. Aku harus mengingatkan diriku sendiri bahwa aku tidak boleh kalah lagi."
  },
  AvgDialog_22111_Content_78 = {
    Text = "Kamu benar. Aku tidak bisa melupakanmu, tidak bisa melupakan segalanya di sini…"
  },
  AvgDialog_22111_Content_79 = {
    Text = "Aku ingin menang. Aku hanya ingin menang. Apa salahnya ingin menang?"
  },
  AvgDialog_22111_Content_8 = {
    Text = "Ingin mengalahkanku di tamanku, sangat berani, dan juga sangat bodoh."
  },
  AvgDialog_22111_Content_80 = {
    Text = "Maaf, Horla."
  },
  AvgDialog_22111_Content_81 = {
    Text = "Colette terisak dalam kesakitan, perlahan mendekati Horla."
  },
  AvgDialog_22111_Content_82 = {
    Text = "Domain menghilang, rencanamu telah gagal, Colette!"
  },
  AvgDialog_22111_Content_83 = {
    Text = "Meskipun kamu bertindak terhadapnya sekarang, itu tidak akan mengubah apa pun!"
  },
  AvgDialog_22111_Content_84 = {
    Text = "Kamu berjuang, ingin mendekati Horla, namun rasa sakit yang luar biasa membuatmu tak mampu bergerak."
  },
  AvgDialog_22111_Content_85 = {
    Text = "Duri menjulur ke arah kepala Horla."
  },
  AvgDialog_22111_Content_86 = {Text = "Tunggu!!"},
  AvgDialog_22111_Content_87 = {
    Text = "Kraak——"
  },
  AvgDialog_22111_Content_88 = {
    Text = "Sebuah mawar dipotong. Colette mengambilnya dan menyodorkannya kepada Horla."
  },
  AvgDialog_22111_Content_89 = {
    Text = "Sebuah puisi yang indah, Horla... Aku akan menukar bunga milikku dengan puisimu."
  },
  AvgDialog_22111_Content_9 = {
    Text = "Kalian telah menyia-nyiakan kesempatan terakhir untuk melarikan diri... Perayaan ini, kalian harus menemaniku sampai akhir."
  },
  AvgDialog_22111_Content_90 = {Text = "BRAK—"},
  AvgDialog_22111_Content_91 = {
    Text = "Mungkin karena lenyapnya Domain membuat Peramu Bunga berubah."
  },
  AvgDialog_22111_Content_92 = {
    Text = "Atau mungkin perubahan yang dibuat oleh tukang kebun menyebabkan Domain lenyap."
  },
  AvgDialog_22111_Content_93 = {
    Text = "Cité dalam kumpulan puisi perlahan memudar, kekuatan yang menopang Colette juga tidak ada lagi."
  },
  AvgDialog_22111_Content_94 = {
    Text = "Tubuhnya berubah menjadi genangan lumpur hitam yang bercampur dengan kelopak-kelopak bunga yang berserakan, lalu tenggelam ke dalam tanah di depan Horla."
  },
  AvgDialog_22111_Content_95 = {
    Text = "Colette, apakah kamu sudah selesai membaca?"
  },
  AvgDialog_22111_Content_96 = {
    Text = "Hmm… sudah selesai membacanya… tapi sepertinya aku tidak terlalu paham."
  },
  AvgDialog_22111_Content_97 = {
    Text = "Ah, begitu ya… Ini adalah puisi pertama yang kutulis, tidak terlalu bagus…"
  },
  AvgDialog_22111_Content_98 = {
    Text = "Bukan salahmu, Horla. Aku tidak mengerti puisi siapa pun."
  },
  AvgDialog_22111_Content_99 = {
    Text = "Saya bertanya kepada banyak orang di sekitar saya, tetapi mereka juga tidak mengerti."
  },
  AvgDialog_22120_Content_1 = {
    Text = "Taman dengan jalan setapak yang bercabang"
  },
  AvgDialog_22120_Content_10 = {
    Text = "Jika bahkan sahabat terbaikku tidak bisa melihatnya, itu akan sangat disayangkan."
  },
  AvgDialog_22120_Content_11 = {
    Text = "Di seberang taman, wanita tua itu tersenyum kepada kalian."
  },
  AvgDialog_22120_Content_12 = {
    Text = "Teman pemahat saya memberi tahu saya bahwa hanya orang dengan bakat tertentu yang bisa menjadi Pembangun."
  },
  AvgDialog_22120_Content_13 = {
    Text = "Benar-benar membuat iri, Horla."
  },
  AvgDialog_22120_Content_14 = {
    Text = "Kamu memperhatikan jejak modifikasi pelarutan di tubuhnya, serta orang yang berdiri di belakangnya."
  },
  AvgDialog_22120_Content_15 = {
    Text = "Para pematung ya... Sepertinya, situasi di sini disebabkan oleh tukang kebun dan Para pematung."
  },
  AvgDialog_22120_Content_16 = {
    Text = "Puisi itu, ada di tanganmu?"
  },
  AvgDialog_22120_Content_17 = {
    Text = "Barang peninggalan teman lama, tentu saja harus disimpan dengan baik."
  },
  AvgDialog_22120_Content_18 = {
    Text = "Selain itu, perlu diingatkan bahwa ini bukan Puisi milikmu — dari awal hingga akhir, ini adalah milikku."
  },
  AvgDialog_22120_Content_19 = {
    Text = "Cité menjadi seperti ini... apakah ini karena kamu, benar?"
  },
  AvgDialog_22120_Content_2 = {
    Text = "Kamu adalah... Collette..."
  },
  AvgDialog_22120_Content_20 = {
    Text = "Di sini, seharusnya disebut \"Cité-ku\" baru benar."
  },
  AvgDialog_22120_Content_21 = {
    Text = "Masih ingatkah kamu, dulu impian terbesar kita hanyalah membeli sebuah rumah."
  },
  AvgDialog_22120_Content_22 = {
    Text = "Tapi sekarang? Puisi, rakyat, tanah... dan gedung ini yang selalu kita impikan."
  },
  AvgDialog_22120_Content_23 = {
    Text = "Lihatlah, Horla yang tercinta. Sekarang, seluruh Cité adalah milikku."
  },
  AvgDialog_22120_Content_24 = {
    Text = "Colette, pertanyaan ini telah menggangguku selama bertahun-tahun banyak sekali..."
  },
  AvgDialog_22120_Content_25 = {
    Text = "Jari-jari Horla saling berputar dengan gugup. Dia mengangkat kepalanya, matanya yang berkaca-kaca menatap Collette."
  },
  AvgDialog_22120_Content_26 = {
    Text = "Kenapa kau melakukan semua ini... Kenapa kau berubah menjadi seperti ini..."
  },
  AvgDialog_22120_Content_27 = {
    Text = "Colette tersenyum dan menggelengkan kepalanya."
  },
  AvgDialog_22120_Content_28 = {
    Text = "Kamu sangat cerdas, meskipun belum pernah keluar rumah, kamu tetap bisa menulis puisi-puisi yang indah. Namun, mengenai manusia, kamu sama sekali tidak memahaminya..."
  },
  AvgDialog_22120_Content_29 = {
    Text = "Aku tidak pernah berubah, Horla."
  },
  AvgDialog_22120_Content_3 = {
    Text = "Horla sedikit membuka mulutnya, memandang lurus ke arah nenek itu melalui sebuah taman yang telah terbakar."
  },
  AvgDialog_22120_Content_30 = {
    Text = "Tidak... tidak mungkin... dulu kamu jelas-jelas..."
  },
  AvgDialog_22120_Content_31 = {
    Text = "Ada kalanya, aku benar-benar iri padamu. Iri pada bakatmu, pada talenta alamiahmu, dan juga pada kepolosanmu."
  },
  AvgDialog_22120_Content_32 = {
    Text = "Tapi kenapa... kenapa kamu bisa hidup dengan begitu polos?"
  },
  AvgDialog_22120_Content_33 = {
    Text = "——Horla, orang seperti kita tidak memiliki hak untuk menjadi naif."
  },
  AvgDialog_22120_Content_34 = {
    Text = "Bukan seperti itu, Colette..."
  },
  AvgDialog_22120_Content_35 = {
    Text = "Hal-hal yang terjadi di masa lalu, aku sama sekali tidak memedulikannya. Tolong kembalikan Puisi kepada kami, dan biarkan Cité kembali normal…"
  },
  AvgDialog_22120_Content_36 = {
    Text = "Apakah kamu tidak peduli?"
  },
  AvgDialog_22120_Content_37 = {
    Text = "Seolah mendengar lelucon yang konyol, Colette tertawa terbahak-bahak sampai hampir tidak bisa meluruskan pinggangnya."
  },
  AvgDialog_22120_Content_38 = {
    Text = "Kamu tidak peduli... lalu apa hakmu untuk tidak peduli?"
  },
  AvgDialog_22120_Content_39 = {
    Text = "Simpan belas kasihanmu, Horla. Kau tak pernah mengerti aku. Kau tidak mengerti apa-apa."
  },
  AvgDialog_22120_Content_4 = {Text = "!!!"},
  AvgDialog_22120_Content_40 = {
    Text = "Dia berdiri, mengembalikan sikap anggunnya, dan mengangguk kepada orang di sebelahnya."
  },
  AvgDialog_22120_Content_41 = {
    Text = "Upacara akan segera dimulai malam ini. Segala sesuatu di sini, aku serahkan padamu."
  },
  AvgDialog_22120_Content_42 = {
    Text = "Upacara? Apa yang ingin kamu lakukan?!"
  },
  AvgDialog_22120_Content_43 = {
    Text = "Colette mengabaikanmu, merapikan pakaiannya, lalu masuk ke dalam gedung."
  },
  AvgDialog_22120_Content_44 = {Text = "Tunggu!"},
  AvgDialog_22120_Content_45 = {
    Text = "Kamu ingin mengejarnya, tetapi gedung di depanmu tiba-tiba menghilang dan muncul di belakangmu."
  },
  AvgDialog_22120_Content_46 = {
    Text = "Kamu menyadari bahwa struktur taman sepenuhnya terbalik, seperti makhluk hidup yang bisa bergerak."
  },
  AvgDialog_22120_Content_47 = {
    Text = "Struktur taman ini, sepertinya mengalami perubahan?"
  },
  AvgDialog_22120_Content_48 = {
    Text = "Di dalam kumpulan puisi saya, saya pernah menulis tentang taman yang memiliki hidup… Namun, taman dalam puisi itu tidak seperti ini…"
  },
  AvgDialog_22120_Content_49 = {
    Text = "Puisi ada di tangan tukang kebun, struktur di sini seharusnya sudah dirubah olehnya…"
  },
  AvgDialog_22120_Content_5 = {
    Text = "Dia adalah... sang tukang kebun itu..."
  },
  AvgDialog_22120_Content_50 = {
    Text = "Belum jelas bagaimana tempat ini terbentuk. Namun, sepertinya akan sedikit sulit untuk menemukannya."
  },
  AvgDialog_22120_Content_51 = {
    Text = "Ayo kita kejar mereka!"
  },
  AvgDialog_22120_Content_52 = {
    Text = "Kamu membawa Horla mendekati gedung, dan tepat saat kamu bersiap untuk masuk, Horla mengeluarkan seruan kaget."
  },
  AvgDialog_22120_Content_53 = {
    Text = "Penjaga {Male=tuan,Female=nyonya}, menurut Anda, apa ini?"
  },
  AvgDialog_22120_Content_54 = {
    Text = "Horla menunjuk ke arah tangga. Di tempat mereka berada sebelumnya, terdapat sebuah amplop putih kecil."
  },
  AvgDialog_22120_Content_55 = {
    Text = "Kamu mengambil surat itu dan membukanya."
  },
  AvgDialog_22120_Content_56 = {
    Text = "\"Untuk Tuan Herbert — Colette\"…"
  },
  AvgDialog_22120_Content_57 = {Text = "Klik——"},
  AvgDialog_22120_Content_58 = {
    Text = "Mendengar suara pintu ruang tamu terbuka, pria itu tidak menoleh dan tetap memandang ke luar jendela dengan penuh minat."
  },
  AvgDialog_22120_Content_59 = {
    Text = "Benar-benar sebuah taman yang indah, Nyonya Colette."
  },
  AvgDialog_22120_Content_6 = {
    Text = "Melihatmu masih begitu muda sekarang, sungguh menyenangkan."
  },
  AvgDialog_22120_Content_60 = {
    Text = "Rumah Anda begitu megah sehingga menimbulkan rasa iri yang mendalam."
  },
  AvgDialog_22120_Content_61 = {
    Text = "Beruntung ada Tuan Herbert. Jika tanpa bantuan Anda, saya pasti sudah mati karena pelarutan."
  },
  AvgDialog_22120_Content_62 = {
    Text = "Apalagi, bisa memiliki lebih banyak hal daripada sebelumnya…"
  },
  AvgDialog_22120_Content_63 = {
    Text = "Masing-masing mengambil apa yang dibutuhkan. Saya membutuhkan bantuan Anda untuk memverifikasi kemungkinan keselarasan antara Domain dan dunia nyata."
  },
  AvgDialog_22120_Content_64 = {
    Text = "Kumpulan puisi yang mengalami Pelarutan, ternyata dapat menghasilkan Domain yang begitu unik. Puisi-puisi yang mengalami Pelarutan, ternyata dapat mengganggu objek di dunia nyata…"
  },
  AvgDialog_22120_Content_65 = {
    Text = "Bahkan Mythag pun tidak bisa menemukan banyak penelitian yang begitu menarik."
  },
  AvgDialog_22120_Content_66 = {
    Text = "Jika seseorang bisa terus hidup dalam kebohongan, maka kebohongan itu sendiri tidak akan lagi dianggap sebagai kebohongan."
  },
  AvgDialog_22120_Content_67 = {
    Text = "Kecerdasan Anda sangat mengagumkan, Nyonya."
  },
  AvgDialog_22120_Content_68 = {
    Text = "Bagaimana persiapan ritual kita?"
  },
  AvgDialog_22120_Content_69 = {
    Text = "Segera… Sesuai perintah Anda, ritual akan dimulai bulan depan."
  },
  AvgDialog_22120_Content_7 = {
    Text = "Bagaimana kamu bisa melihat Horla?"
  },
  AvgDialog_22120_Content_70 = {
    Text = "Menurut perkataan Anda, pada saat itu, pelarutan puisi akan menyebar, bahkan mungkin memengaruhi seluruh Cité?"
  },
  AvgDialog_22120_Content_71 = {
    Text = "Saya tidak ingat Anda sebagai orang yang memperhatikan moral."
  },
  AvgDialog_22120_Content_72 = {
    Text = "Tentu. Tapi aku peduli dengan apa yang kumiliki… Pada saat itu, apakah Domain-ku akan terpengaruh?"
  },
  AvgDialog_22120_Content_73 = {
    Text = "Hoho... Mohon tenang, Nyonya. Pembentukan Domain erat kaitannya dengan Pelarutan. Semakin kuat Pelarutan, semakin stabil Domain Anda."
  },
  AvgDialog_22120_Content_74 = {
    Text = "Domain saat ini hanya mencakup area yang tidak terlalu luas, setelah ritual selesai, itu akan menyebar ke seluruh Cité."
  },
  AvgDialog_22120_Content_75 = {
    Text = "Pada saat itu, semua kekuasaan dan kekayaan di Cité akan menjadi milik Anda."
  },
  AvgDialog_22120_Content_76 = {
    Text = "\"Colette\", kemenangan... bukankah kamu selalu menjadi pemenang? Benarkah?"
  },
  AvgDialog_22120_Content_77 = {
    Text = "Tukang kebun berjalan ke sisi jendela dan memandang ke arah tamannya."
  },
  AvgDialog_22120_Content_78 = {
    Text = "Dia berusaha mempertahankan senyuman yang pantas bagi seorang bangsawan, tetapi gelas anggur di tangannya bergetar tak terkendali."
  },
  AvgDialog_22120_Content_79 = {
    Text = "Wajah wanita bangsawan itu terpantul di gelas anggur yang bergoyang, seperti luka yang membusuk."
  },
  AvgDialog_22120_Content_8 = {
    Text = "Saya sudah memberitahumu jawabannya."
  },
  AvgDialog_22120_Content_80 = {
    Text = "Kita semua akan menjadi pemenang, Tuan Herbert."
  },
  AvgDialog_22120_Content_9 = {
    Text = "Di Cité Baru, segala sesuatu yang indah harus terlihat."
  },
  AvgDialog_22121_Content_1 = {
    Text = "Pemakaman yang Tertunda"
  },
  AvgDialog_22121_Content_10 = {
    Text = "Mungkin terpengaruh oleh kobaran api besar itu"
  },
  AvgDialog_22121_Content_11 = {
    Text = "Bagaimanapun caranya, ini seharusnya tempat yang kita cari."
  },
  AvgDialog_22121_Content_12 = {
    Text = "Horla, di mana puisi itu diletakkan?"
  },
  AvgDialog_22121_Content_13 = {
    Text = "Ketika api mulai menyala, untuk melindungi puisi itu, saya menggali lubang kecil, meletakkannya di dalam kotak, dan menguburnya."
  },
  AvgDialog_22121_Content_14 = {
    Text = "Kami tinggal di rumah kaca tempat menanam mawar. Lewati taman bunga itu, dan kalian akan menemukannya."
  },
  AvgDialog_22121_Content_15 = {Text = "Ah!"},
  AvgDialog_22121_Content_16 = {
    Text = "Ada bahaya?!"
  },
  AvgDialog_22121_Content_17 = {
    Text = "Ah, bukan... Penjaga {Male=tuan,Female=nyonya}, lihatlah ke sana."
  },
  AvgDialog_22121_Content_18 = {
    Text = "Horla menunjuk ke arah sebuah dinding dengan penuh semangat. Di dinding itu terdapat gambar sketsa kasar yang dibuat menggunakan kapur warna-warni."
  },
  AvgDialog_22121_Content_19 = {
    Text = "Dua gadis kecil yang mengenakan rok sedang berperan sebagai nyonya bangsawan dan pelayan."
  },
  AvgDialog_22121_Content_2 = {Text = "Kami tiba!"},
  AvgDialog_22121_Content_20 = {
    Text = "Setelah datang ke sini, kami sering memainkan permainan ini. Kadang-kadang saya berperan sebagai bangsawan, kadang-kadang Colette yang memerankannya."
  },
  AvgDialog_22121_Content_21 = {
    Text = "Lukisan ini adalah hasil karyanya, meskipun tidak terlalu bagus. Namun, saat itu kami kehabisan kapur."
  },
  AvgDialog_22121_Content_22 = {
    Text = "Gaun merah ini, dia mencelupkannya dengan sari bunga mawar... Sekarang sudah tidak terlalu jelas terlihat, sangat disayangkan."
  },
  AvgDialog_22121_Content_23 = {
    Text = "Jari-jari Horla menyapu lembut gambar sketsa itu, dan sudut bibirnya terangkat dengan pelan."
  },
  AvgDialog_22121_Content_24 = {
    Text = "Colette... apakah dia adalah tukang kebun yang membakarmu sampai mati, ya?"
  },
  AvgDialog_22121_Content_25 = {
    Text = "Juga sahabat terbaik saya."
  },
  AvgDialog_22121_Content_26 = {
    Text = "Waktu kecil tinggal di rumah bunga, meskipun juga sangat nyaman, tetapi sedikit sempit. Kami bermimpi suatu hari nanti bisa memiliki sebuah Rumah di lantai atas sana."
  },
  AvgDialog_22121_Content_27 = {
    Text = "Namun, hingga akhirnya juga tidak berhasil tinggal di sana…"
  },
  AvgDialog_22121_Content_28 = {
    Text = "Horla dengan rasa sesal memandang vila megah di depannya, lalu melanjutkan langkahnya."
  },
  AvgDialog_22121_Content_29 = {
    Text = "Penjaga {Male=tuan,Female=nyonya}, melewati taman mawar ini, kita hampir sampai."
  },
  AvgDialog_22121_Content_3 = {
    Text = "Melewati Medici Avenue yang ramai di Cité, berjalan terus ke arah timur laut, tak lama kemudian tiba di sebuah area apartemen yang indah."
  },
  AvgDialog_22121_Content_30 = {
    Text = "Taman mawar? Di mana ada taman mawar…"
  },
  AvgDialog_22121_Content_31 = {
    Text = "Halaman belakang kediaman ini dulunya dipenuhi dengan bunga mawar."
  },
  AvgDialog_22121_Content_32 = {
    Text = "Apakah ini spesies Coleoptera?"
  },
  AvgDialog_22121_Content_33 = {
    Text = "Hmm! Pada saat itu, kami baru saja diusir dari kediaman lama kami dan tidak punya tempat untuk pergi..."
  },
  AvgDialog_22121_Content_34 = {
    Text = "Tunggu! Colette... Aku baru saja melihat papan nama. Apakah ini taman milik sang Countess?"
  },
  AvgDialog_22121_Content_35 = {
    Text = "Bukankah kamu bilang sudah lama tidak melihat taman? Nah, ini adalah taman terindah di area ini."
  },
  AvgDialog_22121_Content_36 = {
    Text = "Colette, ayo kita pergi… Jika kita ketahuan, akan sangat merepotkan!"
  },
  AvgDialog_22121_Content_37 = {
    Text = "Tidak akan. Lihatlah —"
  },
  AvgDialog_22121_Content_38 = {
    Text = "Dia memetik sebuah mawar dan meletakkannya di tangan Horla."
  },
  AvgDialog_22121_Content_39 = {
    Text = "Aaa! Colette, kita akan tinggal di penjara…"
  },
  AvgDialog_22121_Content_4 = {
    Text = "Sebuah vila megah seperti istana berdiri di hadapan kalian, tampak sangat mencolok."
  },
  AvgDialog_22121_Content_40 = {
    Text = "Tidak ada yang akan tinggal di penjara. Horla, lihat ke sana!"
  },
  AvgDialog_22121_Content_41 = {
    Text = "Mengikuti arah yang ditunjuk oleh Colette, Horla melihat sebuah rumah kaca tempat menumbuhkan mawar-mawar berharga."
  },
  AvgDialog_22121_Content_42 = {
    Text = "Di dalam rumah kaca terdapat dua buah tempat tidur serta beberapa barang bawaan mereka yang tidak banyak."
  },
  AvgDialog_22121_Content_43 = {
    Text = "Colette... Apa ini?"
  },
  AvgDialog_22121_Content_44 = {
    Text = "Saya sudah menyewa tempat ini."
  },
  AvgDialog_22121_Content_45 = {
    Text = "Tapi... bagaimana bisa..."
  },
  AvgDialog_22121_Content_46 = {
    Text = "Dia baru menyadari bahwa kalung yang ditinggalkan oleh ibu Collete tidak tergantung di lehernya."
  },
  AvgDialog_22121_Content_47 = {
    Text = "Colette! Kamu…"
  },
  AvgDialog_22121_Content_48 = {
    Text = "Semua ini tidak penting, Horla. Yang penting, ini bukan taman milik seorang earl — ini taman kita."
  },
  AvgDialog_22121_Content_49 = {
    Text = "Kita akan tidur di taman, memasak... Saya akan mengandalkan bunga-bunga yang tumbuh di tanah ini untuk membeli pakaian dan makanan bagi kita."
  },
  AvgDialog_22121_Content_5 = {
    Text = "Namun... mengapa tempat ini berubah menjadi seperti ini?"
  },
  AvgDialog_22121_Content_50 = {
    Text = "Suatu hari nanti, aku akan membeli rumah di gedung di atas juga!"
  },
  AvgDialog_22121_Content_51 = {
    Text = "Tapi... apa yang bisa aku lakukan..."
  },
  AvgDialog_22121_Content_52 = {
    Text = "Selain menulis beberapa puisi yang tak seorang pun membaca, aku tidak bisa membantu apa-apa…"
  },
  AvgDialog_22121_Content_53 = {
    Text = "Jujur, aku juga tidak mengerti puisi-puisimu itu… Tapi, itu tidak penting. Kamu cukup menulis puisi yang ingin kamu tulis saja."
  },
  AvgDialog_22121_Content_54 = {
    Text = "Setiap orang memiliki hal yang harus dilakukan sejak lahir. Saya dilahirkan untuk berusaha demi taman ini, demi Rumah itu…"
  },
  AvgDialog_22121_Content_55 = {
    Text = "Adapun kamu, kamu dilahirkan untuk menulis puisi."
  },
  AvgDialog_22121_Content_56 = {
    Text = "Setelah itu, dia membesarkan kami berdua dengan bunga-bunga dari taman ini."
  },
  AvgDialog_22121_Content_57 = {
    Text = "Meskipun sangat sulit, masih jauh sekali dari kemampuan kami untuk membeli Rumah, saya bisa merasakan bahwa pada waktu itu, kami sebenarnya hidup dengan sangat bahagia."
  },
  AvgDialog_22121_Content_58 = {
    Text = "Hingga suatu hari, penerbit mengirimkan honorarium pertama untuk puisi saya…"
  },
  AvgDialog_22121_Content_59 = {
    Text = "Meskipun dia kemudian mengunci kamu di rumah kaca dan membakarnya, sepertinya kamu tidak membencinya."
  },
  AvgDialog_22121_Content_6 = {
    Text = "Di kebun raksasa di bawahnya, tumbuh rumput kering berwarna kelabu mati. Kalian berjalan menuju kebun itu."
  },
  AvgDialog_22121_Content_60 = {
    Text = "Entahlah... mungkin. Aku juga tidak tahu harus berbuat apa."
  },
  AvgDialog_22121_Content_61 = {
    Text = "Aku hanya tahu, jika bukan karena puisi-puisi itu, semua ini tidak akan terjadi…"
  },
  AvgDialog_22121_Content_62 = {Text = "Horla…"},
  AvgDialog_22121_Content_63 = {
    Text = "Gambar dalam pikiran Horla terbuka di hadapanmu, kesedihannya tampak menyebar seperti memiliki substansi, meresap ke dalam segala sesuatu di sekitarnya."
  },
  AvgDialog_22121_Content_64 = {
    Text = "Maafkan saya! Penjaga {Male=tuan,Female=nyonya} …… aku membuatmu sedih lagi ……"
  },
  AvgDialog_22121_Content_65 = {
    Text = "Tidak apa-apa, jangan menahan perasaanmu."
  },
  AvgDialog_22121_Content_66 = {
    Text = "Mari kita lanjutkan mencari Puisi."
  },
  AvgDialog_22121_Content_67 = {
    Text = "Puisi tersembunyi di sana! Penjaga {Male=tuan,Female=nyonya}, silakan ikuti saya!"
  },
  AvgDialog_22121_Content_68 = {
    Text = "Kalian berjalan menyusuri jalan setapak yang berkelok di taman, melewati rak-rak kayu yang hangus terbakar, dan akhirnya sampai di sebuah area kosong di bagian belakang halaman."
  },
  AvgDialog_22121_Content_69 = {Text = "Kami tiba!"},
  AvgDialog_22121_Content_7 = {
    Text = "Semakin dekat ke sini, warna di sekitarnya menjadi semakin pudar… Apakah ini juga bagian dari imajinasimu dalam Puisi?"
  },
  AvgDialog_22121_Content_70 = {
    Text = "Dia menunjuk ke sebuah area kecil di tengah halaman belakang. Mawar-mawar di sekitarnya telah berubah menjadi abu dan nutrisi, lalu berubah menjadi rumput liar berwarna hitam yang kini tumbuh subur."
  },
  AvgDialog_22121_Content_71 = {
    Text = "Laporan Mythag mengatakan bahwa mereka menemukan inti perak Horla di sebuah tanah kosong yang hangus terbakar."
  },
  AvgDialog_22121_Content_72 = {
    Text = "—— Itu adalah tempat pemakaman puisi. Itu adalah tempat peristirahatan terakhirnya."
  },
  AvgDialog_22121_Content_73 = {
    Text = "Aneh... tempat ini, ada sebuah lubang..."
  },
  AvgDialog_22121_Content_74 = {
    Text = "Puisi… Puisi seharusnya memang dikubur di sini!"
  },
  AvgDialog_22121_Content_75 = {
    Text = "Itu sudah tidak ada di sana beberapa tahun yang lalu."
  },
  AvgDialog_22121_Content_76 = {Text = "!!!"},
  AvgDialog_22121_Content_77 = {
    Text = "Siapa?! ——"
  },
  AvgDialog_22121_Content_78 = {
    Text = "Suara yang terdengar familiar terdengar. Kalian berbalik dengan tiba-tiba."
  },
  AvgDialog_22121_Content_79 = {
    Text = "Pintu belakang vila terbuka, wanita bangsawan yang kalian temui di kapal berdiri di pintu, memandang kalian dengan tatapan merendahkan."
  },
  AvgDialog_22121_Content_8 = {
    Text = "Aku tidak terlalu ingat... Namun, seharusnya tidak akan seperti itu kan..."
  },
  AvgDialog_22121_Content_80 = {
    Text = "Setelah kebakaran besar itu, aku mengadakan pemakaman yang megah untukmu. Kamu tidak bisa melihatnya dengan matamu sendiri, dan aku selalu merasa sangat menyesal karenanya."
  },
  AvgDialog_22121_Content_81 = {
    Text = "Saat melihatmu di kapal, aku sangat bahagia. Sudah lama aku tidak merasa sebahagia ini."
  },
  AvgDialog_22121_Content_82 = {
    Text = "Puluhan tahun. Puluhan tahun, akhirnya kita bertemu lagi…"
  },
  AvgDialog_22121_Content_83 = {
    Text = "Selamat datang kembali, Horla."
  },
  AvgDialog_22121_Content_9 = {
    Text = "Mungkin karena pernah menulis beberapa puisi tentang kematian."
  },
  AvgDialog_22122_Content_1 = {
    Text = "Tak terhitung banyaknya monster menyerbu ke arah panggung."
  },
  AvgDialog_22122_Content_2 = {
    Text = "Seperti ini terus bukan solusi. Horla, ikuti aku erat-erat, kita terobos keluar dari sini!"
  },
  AvgDialog_22122_Content_3 = {
    Text = "Tapi kalau begitu... Collete akan menghancurkan tempat ini..."
  },
  AvgDialog_22122_Content_4 = {
    Text = "Sekarang bukan saatnya ragu. Jumlah monster terlalu banyak, kita tidak bisa menghentikan Collette saat ini... Percayalah padaku, Horla."
  },
  AvgDialog_22122_Content_5 = {
    Text = "Melihat tekad di matamu, Horla masih belum memahami maksudmu, namun dia mengangguk."
  },
  AvgDialog_22122_Content_6 = {
    Text = "Aku... aku mengerti..."
  },
  AvgDialog_22122_Content_7 = {
    Text = "Penjaga {Male=tuan,Female=nyonya}, hati-hati!"
  },
  AvgDialog_22125_Content_1 = {
    Text = "Orang dalam puisi"
  },
  AvgDialog_22125_Content_10 = {
    Text = "Cahaya terang yang tak diketahui dari mana asalnya, menerangi atap serta meja dan kursi kafe di pinggir jalan."
  },
  AvgDialog_22125_Content_100 = {
    Text = "Ayo pergi, Penjaga {Male=tuan,Female=nyonya}, kita ke Taman Mawar… ke tempat aku meninggal."
  },
  AvgDialog_22125_Content_11 = {
    Text = "Horla mandi dalam cahaya, kedua kakinya bergoyang-goyang di udara, memukul irama yang tak dikenal."
  },
  AvgDialog_22125_Content_12 = {
    Text = "Saya ingat di koran tertulis bahwa Jalan Maret awalnya merupakan jalan yang biasa saja, namun menjadi terkenal karena seorang pelukis membuat lukisan untuk kafe ini."
  },
  AvgDialog_22125_Content_13 = {
    Text = "Saya sangat menyukai cerita ini, bahkan pernah menulis sebuah puisi untuknya. Dalam puisi itu, pelukis tersebut akhirnya menetap di nomor 99 di ujung Jalan Maret."
  },
  AvgDialog_22125_Content_14 = {
    Text = "Namun, menurut saya, bukan pelukis yang bertemu dengan Jalan Maret, melainkan Jalan Maret yang bertemu dengan pelukis."
  },
  AvgDialog_22125_Content_15 = {
    Text = "Cité menjadi begitu aneh, kamu tampaknya sama sekali tidak takut, malah menikmatinya?"
  },
  AvgDialog_22125_Content_16 = {
    Text = "Di sini tidak perlu berinteraksi dengan orang lain, namun bisa mengalami banyak hal baru yang menarik."
  },
  AvgDialog_22125_Content_17 = {
    Text = "Saya tidak tahu mengapa, tapi entah bagaimana, dibandingkan dengan Cité di koran dan foto-foto, tempat ini terasa lebih akrab bagi saya…"
  },
  AvgDialog_22125_Content_18 = {
    Text = "Ah, lihat! Penjaga {Male=tuan,Female=nyonya}! Itu adalah bintang!"
  },
  AvgDialog_22125_Content_19 = {
    Text = "Bintang? Tapi sepertinya di sini tidak ada siang dan malam..."
  },
  AvgDialog_22125_Content_2 = {
    Text = "Dua, dua cangkir kopi... terima kasih."
  },
  AvgDialog_22125_Content_20 = {
    Text = "Kamu mengangkat kepalamu. Di sisi bintang-bintang yang berkilauan dengan cahaya keemasan, muncul kelopak bunga putih."
  },
  AvgDialog_22125_Content_21 = {
    Text = "Bintang-bintang sebesar krisan raksasa telah mengubah langit menjadi sebuah taman."
  },
  AvgDialog_22125_Content_22 = {
    Text = "Cité adalah kota puitis dan bunga... Jika tidak ada hal-hal mendesak, tempat ini memang cukup menyenangkan untuk dinikmati."
  },
  AvgDialog_22125_Content_23 = {
    Text = "Setelah tiga puluh menit, kami bertemu sekitar seratus lebih warga, dan tidak mengalami serangan… kereta listrik itu sepertinya tidak menipu kami."
  },
  AvgDialog_22125_Content_24 = {
    Text = "Ah, jadi Penjaga {Male=tuan,Female=nyonya} selalu mengamati, ya?"
  },
  AvgDialog_22125_Content_25 = {
    Text = "Tidak ada jalan lain. Jika ada orang yang memandang bintang di langit, maka harus ada orang yang memperhatikan tanah di bawah kakinya."
  },
  AvgDialog_22125_Content_26 = {
    Text = "Meskipun tidak memiliki bakat dalam puisi, setidaknya sebagai Penjaga Mythag, hal ini masih bisa dilakukan."
  },
  AvgDialog_22125_Content_27 = {
    Text = "Kontaknya berada di Jalan Maret No. 101. Bersiaplah, kita akan berangkat."
  },
  AvgDialog_22125_Content_29 = {
    Text = "Boom boom——"
  },
  AvgDialog_22125_Content_3 = {
    Text = "Tak lama, rakun yang mengenakan seragam pelayan itu memberikan dua cangkir kopi kepada kalian."
  },
  AvgDialog_22125_Content_30 = {Text = "Siapa?!"},
  AvgDialog_22125_Content_31 = {
    Text = "Tidak tahu bahaya apa yang mungkin ada di sini, kamu waspada sambil memandang sekeliling."
  },
  AvgDialog_22125_Content_32 = {
    Text = "Ah, hai orang, halo!"
  },
  AvgDialog_22125_Content_33 = {
    Text = "Hu... kita bertemu lagi..."
  },
  AvgDialog_22125_Content_34 = {
    Text = "Halo! Nyonya Kupu-kupu, Tuan Ulat!"
  },
  AvgDialog_22125_Content_35 = {
    Text = "Apa maksud kalian?"
  },
  AvgDialog_22125_Content_36 = {
    Text = "Saya dan suamiku sudah makan malam, dan kami sedang bersiap untuk berjalan-jalan di jalan."
  },
  AvgDialog_22125_Content_37 = {
    Text = "Benar-benar kebetulan. Saya mendengar puisi yang ditulis oleh sang nyonya, sungguh sangat indah!"
  },
  AvgDialog_22125_Content_38 = {
    Text = "Terima kasih……"
  },
  AvgDialog_22125_Content_39 = {
    Text = "Kalian berdua, apakah kalian kehilangan arah?"
  },
  AvgDialog_22125_Content_4 = {
    Text = "Kemajuan cukup besar, sekarang sudah bisa berbicara dengan orang asing."
  },
  AvgDialog_22125_Content_40 = {
    Text = "Jalan di sini tidak sesuai dengan yang ditandai di peta, nomor rumah semuanya kacau..."
  },
  AvgDialog_22125_Content_41 = {
    Text = "Permisi, apakah kalian tahu di mana Nomor 101 Jalan Maret berada?"
  },
  AvgDialog_22125_Content_42 = {
    Text = "101... Saya ingat, sepertinya tidak ada nomor 101 di Jalan Maret?"
  },
  AvgDialog_22125_Content_43 = {
    Text = "Begitu ya..."
  },
  AvgDialog_22125_Content_44 = {
    Text = "Tempat ini tidak terlalu besar, mari kita cari dengan tenang."
  },
  AvgDialog_22125_Content_45 = {
    Text = "Maaf, saya tidak bisa banyak membantu."
  },
  AvgDialog_22125_Content_46 = {
    Text = "Kalian berdua bisa mencarinya dengan santai. Semoga kalian bersenang-senang di Cité~"
  },
  AvgDialog_22125_Content_47 = {
    Text = "Setelah berpisah dengan Nyonya Kupu-kupu dan Tuan Ulat, kalian melanjutkan perjalanan menyusuri gang-gang di Jalan Maret, memeriksa nomor di papan alamat satu per satu."
  },
  AvgDialog_22125_Content_48 = {
    Text = "Eh, kalau tidak salah ingat, Jalan San Yue sepertinya tidak sepanjang ini ya…"
  },
  AvgDialog_22125_Content_49 = {
    Text = "Kami sudah berkeliling dua kali."
  },
  AvgDialog_22125_Content_5 = {
    Text = "Hanya satu orang, dan penampilannya mirip hewan, akan sedikit lebih baik..."
  },
  AvgDialog_22125_Content_50 = {
    Text = "Apa? Tapi, aku tidak melihat di mana Nomor 101 berada..."
  },
  AvgDialog_22125_Content_51 = {
    Text = "Pertama kali saya juga tidak melihatnya, tapi kedua kalinya saya memperhatikan dengan cermat semua nomor di pintu."
  },
  AvgDialog_22125_Content_52 = {
    Text = "Jalan San Yue… Tidak ada nomor 101."
  },
  AvgDialog_22125_Content_53 = {
    Text = "Nomor pelat terbesar di sini adalah ini."
  },
  AvgDialog_22125_Content_54 = {
    Text = "Kalian berdiri di samping tembok di ujung jalan. Plakat logam di depan gedung kecil telah dilepas dan diganti dengan sebuah lukisan."
  },
  AvgDialog_22125_Content_55 = {
    Text = "Jalan Maret... Nomor 99..."
  },
  AvgDialog_22125_Content_56 = {Text = "Siapa?"},
  AvgDialog_22125_Content_57 = {
    Text = "Pintu terbuka dengan keras, dan sebuah sosok kurus muncul di hadapan kalian."
  },
  AvgDialog_22125_Content_58 = {
    Text = "Pada pakaian compang-camping yang penuh dengan cat, terdapat wajah seekor serangga."
  },
  AvgDialog_22125_Content_59 = {
    Text = "Kalian pencuri?!"
  },
  AvgDialog_22125_Content_6 = {
    Text = "Meskipun tidak tahu apakah ini hal yang baik, jumlah orang akhirnya bertambah."
  },
  AvgDialog_22125_Content_60 = {
    Text = "Eh... bukan, kami adalah wisatawan, datang untuk mencari teman, dia berada di Jalan Maret No. 101..."
  },
  AvgDialog_22125_Content_61 = {
    Text = "Nomor berapa?!!!"
  },
  AvgDialog_22125_Content_62 = {
    Text = "1... eh, 88."
  },
  AvgDialog_22125_Content_63 = {
    Text = "Kamu membicarakan 101... Tidak ada nomor 101 di sini..."
  },
  AvgDialog_22125_Content_64 = {
    Text = "Kalian adalah pencuri… kalian mencuri lukisanku! Kalian benar-benar mencuri lukisanku!!"
  },
  AvgDialog_22125_Content_65 = {
    Text = "Seiring dengan gerakan pelukis, adegan di sekitarnya tiba-tiba berubah."
  },
  AvgDialog_22125_Content_66 = {
    Text = "Beberapa warna cemerlang dan aneh tiba-tiba muncul di bangunan terdekat, seperti sebuah lukisan utuh yang telah dirobek oleh kekuatan tak dikenal menjadi kumpulan warna-warna yang kacau."
  },
  AvgDialog_22125_Content_67 = {
    Text = "Ini adalah... Pelarutan?!"
  },
  AvgDialog_22125_Content_68 = {
    Text = "Kamu tidak terlalu yakin dengan prinsip di balik fenomena ini, sambil membawa Horla melangkah mundur dengan cepat."
  },
  AvgDialog_22125_Content_69 = {
    Text = "Kembalikan lukisanku…!"
  },
  AvgDialog_22125_Content_7 = {
    Text = "Bukankah Tuan Ulat Bulu berkata bahwa selama kita tidak melakukan tindakan aneh, kebanyakan orang tidak akan memberikan kerusakan kepada kita?"
  },
  AvgDialog_22125_Content_70 = {
    Text = "Tangannya terulur ke arah kalian. Sebelum tangannya menyentuh kalian, warna aneh datang menghampirinya, seperti banjir, membungkus dan melahapnya…"
  },
  AvgDialog_22125_Content_71 = {
    Text = "Segera, warna aneh itu berhenti bergerak. Kamu terdiam, mengamati adegan di depanmu."
  },
  AvgDialog_22125_Content_72 = {
    Text = "Lambang sekolah di dada memancarkan cahaya perak."
  },
  AvgDialog_22125_Content_73 = {
    Text = "Cité... Apakah ada sesuatu yang terjadi lagi?"
  },
  AvgDialog_22125_Content_74 = {
    Text = "Sebuah bangunan, menghilang."
  },
  AvgDialog_22125_Content_75 = {
    Text = "Lokasi, berada di Jalan Maret…"
  },
  AvgDialog_22125_Content_76 = {Text = "Nomor 99."},
  AvgDialog_22125_Content_77 = {
    Text = "Kamu menatap sisa-sisa nomor pintu 99 di depanmu, lalu menghirup napas dalam-dalam."
  },
  AvgDialog_22125_Content_78 = {
    Text = "Tidak bisa membiarkan keadaan seperti ini terus berlanjut… Saat ini tidak ada kontak yang bisa dihubungi, kita perlu memikirkan metode lain."
  },
  AvgDialog_22125_Content_79 = {
    Text = "Penjaga {Male=tuan,Female=nyonya}, saya punya dugaan…"
  },
  AvgDialog_22125_Content_8 = {
    Text = "Semoga tidak ada lagi lebah yang datang untuk 'menyanyikan lagu' kepadaku..."
  },
  AvgDialog_22125_Content_80 = {
    Text = "Tidak, bukan sekadar tebakan, aku sangat yakin."
  },
  AvgDialog_22125_Content_81 = {
    Text = "Ini bukan Cité!"
  },
  AvgDialog_22125_Content_82 = {
    Text = "...Horla, apakah kamu mau mendengarkan dengan serius apa yang kamu katakan."
  },
  AvgDialog_22125_Content_83 = {
    Text = "Maksud saya, ini bukan Cité yang sebenarnya."
  },
  AvgDialog_22125_Content_84 = {
    Text = "Bukan Cité yang sebenarnya…"
  },
  AvgDialog_22125_Content_85 = {
    Text = "Ulat bulu trem yang membutuhkan puisi untuk tiket, Nyonya Kupu-kupu, Jalan Maret dengan hanya nomor 99, Pelukis, Bintang Daisy…"
  },
  AvgDialog_22125_Content_86 = {
    Text = "Barang-barang yang kita lihat ini, aku selalu merasa sangat, sangat akrab dengannya. Baru saja aku akhirnya ingat."
  },
  AvgDialog_22125_Content_87 = {
    Text = "Semua hal ini pernah muncul di dalam puisi saya. Segala sesuatu di sini adalah seperti yang saya bayangkan dalam puisi saya…"
  },
  AvgDialog_22125_Content_88 = {
    Text = "Penjaga {Male=tuan,Female=nyonya}, ini bukan Cité yang sebenarnya."
  },
  AvgDialog_22125_Content_89 = {
    Text = "Di sini, adalah <Yellow:Cité dalam puisi saya>…"
  },
  AvgDialog_22125_Content_9 = {
    Text = "Di jalan yang luas, para penduduk dengan kepala berbagai macam hewan berlalu lalang, tanpa menunjukkan sifat agresi."
  },
  AvgDialog_22125_Content_90 = {
    Text = "Di bawah keriuhan warna-warni Jalan Maret, Horla perlahan berputar, memandangi segala sesuatu yang ada dalam puisinya."
  },
  AvgDialog_22125_Content_91 = {
    Text = "Cahaya jatuh seperti selubung kasa, menerangi wajahnya yang dipenuhi rasa ingin tahu, kesedihan, dan kebingungan."
  },
  AvgDialog_22125_Content_92 = {
    Text = "Jadi begitu… tak heran di sini ada banyak hal aneh dan unik."
  },
  AvgDialog_22125_Content_93 = {
    Text = "Namun, bagaimana Cité seperti itu terbentuk……"
  },
  AvgDialog_22125_Content_94 = {
    Text = "Saya juga tidak tahu… Ada sesuatu di sini yang tidak sepenuhnya sama dengan apa yang kutulis dalam puisiku."
  },
  AvgDialog_22125_Content_95 = {
    Text = "Semua ini dalam puisi seharusnya indah dan abadi… Aku juga tidak tahu mengapa bisa menjadi seperti sekarang…"
  },
  AvgDialog_22125_Content_96 = {
    Text = "Namun, aku pikir jika ingin menangani masalah di sini, mungkin kita perlu menemukan puisi itu terlebih dahulu."
  },
  AvgDialog_22125_Content_97 = {
    Text = "Jalan, apakah kamu masih ingat?"
  },
  AvgDialog_22125_Content_98 = {
    Text = "Dalam puisi saya, Jalan Maret sangat dekat dengan rumah. Jalan untuk pulang, selalu ku ingat."
  },
  AvgDialog_22125_Content_99 = {
    Text = "Dia mengarah ke pemukiman, kesedihan seperti kabut yang berwujud, perlahan membungkus dirimu."
  },
  AvgDialog_22126_Content_1 = {
    Text = "Hah... hah... Penjaga {Male=tuan,Female=nyonya}, jumlah monster terlalu banyak, sama sekali tidak bisa diatasi..."
  },
  AvgDialog_22126_Content_10 = {
    Text = "——Melarikan diri untuk mencari bala bantuan hanyalah kedok. Ini adalah kesempatan yang selama ini kamu nantikan."
  },
  AvgDialog_22126_Content_11 = {
    Text = "Tahan dia, Horla!"
  },
  AvgDialog_22126_Content_12 = {
    Text = "Kamu tiba-tiba berbalik."
  },
  AvgDialog_22126_Content_13 = {
    Text = "Horla sedikit terkejut, memahami niatmu, lalu bersamamu berlari menuju Colette…"
  },
  AvgDialog_22126_Content_14 = {Text = "Ini!!"},
  AvgDialog_22126_Content_15 = {
    Text = "Sebuah monster raksasa berbentuk bunga muncul dari sulur-sulur di sekitar alun-alun, menghalangi jalan di depan Colete."
  },
  AvgDialog_22126_Content_16 = {
    Text = "Gagasan yang bagus, Penjaga. Namun, aku tidak akan membiarkan hal-hal tak terduga memengaruhi rencanaku."
  },
  AvgDialog_22126_Content_17 = {
    Text = "Dengarkanlah, Horla. Puisi ini kutulis untukmu——"
  },
  AvgDialog_22126_Content_2 = {
    Text = "Pelarutan semakin membesar, jika terus seperti ini, kita juga akan terjebak di sini…"
  },
  AvgDialog_22126_Content_3 = {
    Text = "Ketika kalian tiba di Cité, saya sudah mendengar percakapan kalian."
  },
  AvgDialog_22126_Content_4 = {
    Text = "Mau mencari bala bantuan? Aku tidak akan memberimu kesempatan itu, Penjaga."
  },
  AvgDialog_22126_Content_5 = {
    Text = "Berdasarkan perintah Colette, gerombolan monster berlari menuju pintu keluar, sepenuhnya memblokir jalanmu."
  },
  AvgDialog_22126_Content_6 = {
    Text = "Kesempatan telah tiba. Hanya satu kali."
  },
  AvgDialog_22126_Content_7 = {
    Text = "Apa? …… apa …… apa maksudnya ……"
  },
  AvgDialog_22126_Content_8 = {
    Text = "Dari sudut pandangmu, kamu memperhatikan bahwa Colette telah mengirim semua monster di belakang panggung untuk memblokir jalan keluar kalian."
  },
  AvgDialog_22126_Content_9 = {
    Text = "Sedangkan di sekitarnya, jumlah monster menjadi sangat sedikit, cukup untuk kalian mencoba sekali."
  },
  AvgDialog_22127_Content_1 = {Text = "Kota Bunga"},
  AvgDialog_22127_Content_10 = {
    Text = "Pemandangan-pemandangan indah ini tampaknya membuat Horla melupakan memori-memori menyakitkan tersebut, serta melupakan keberadaan orang asing di sekitarnya."
  },
  AvgDialog_22127_Content_100 = {
    Text = "Halo, jika Anda tidak naik mobil, saya akan pergi. Ada penumpang lain yang menunggu."
  },
  AvgDialog_22127_Content_101 = {
    Text = "Kamu mengamati dengan penuh kewaspadaan. Trem ulat tampaknya tidak memiliki niat bermusuhan."
  },
  AvgDialog_22127_Content_102 = {
    Text = "Permisi, apakah mobil ini bisa sampai ke Jalan Medici?"
  },
  AvgDialog_22127_Content_103 = {
    Text = "Tentu, tentu... trem ini bisa membawamu ke mana saja."
  },
  AvgDialog_22127_Content_104 = {
    Text = "Kereta rel yang bisa pergi ke mana saja, ya ... Memang, sangat masuk akal."
  },
  AvgDialog_22127_Content_105 = {
    Text = "Bagaimanapun, setidaknya mobil ini memang digunakan untuk mengangkut penumpang."
  },
  AvgDialog_22127_Content_106 = {
    Text = "Tubuh ulat bulu terbuka, memperlihatkan kursi yang rapi di dalamnya."
  },
  AvgDialog_22127_Content_107 = {
    Text = "Melihat tatapan penuh harap dari Horla, kalian pun duduk di atasnya."
  },
  AvgDialog_22127_Content_108 = {
    Text = "Permisi, bagaimana cara membayar untuk tiket?"
  },
  AvgDialog_22127_Content_109 = {
    Text = "Tidak perlu uang."
  },
  AvgDialog_22127_Content_11 = {
    Text = "Matanya berbinar, mengikuti di belakang kalian saat melintasi kota yang indah bak lukisan ini."
  },
  AvgDialog_22127_Content_110 = {
    Text = "Tampaknya hari ini tidak terlalu buruk, setidaknya masih ada tumpangan gratis yang bisa kutumpangi…"
  },
  AvgDialog_22127_Content_111 = {
    Text = "Bukan gratis, lho. Tiket untuk mobil ini harus dibeli dengan puisi."
  },
  AvgDialog_22127_Content_112 = {Text = "???"},
  AvgDialog_22127_Content_113 = {
    Text = "Ah, benar benar… Gadis kecil ini sepertinya penduduk lokal."
  },
  AvgDialog_22127_Content_114 = {
    Text = "Horla, bagaimana kamu bisa mengetahui aturan seperti ini…"
  },
  AvgDialog_22127_Content_115 = {
    Text = "Saya juga tidak terlalu yakin... Yang saya ingat, memang seperti itu."
  },
  AvgDialog_22127_Content_116 = {
    Text = "Namun, harganya juga tidak mahal. Setiap orang hanya perlu menulis satu kalimat yang sangat sederhana."
  },
  AvgDialog_22127_Content_117 = {
    Text = "Aku yang pertama..."
  },
  AvgDialog_22127_Content_118 = {
    Text = "Dia mendekati bagian depan mobil dan diam-diam mengatakan sesuatu kepada kotak tiket di kursi pengemudi."
  },
  AvgDialog_22127_Content_119 = {
    Text = "Ah... betapa indahnya puisi itu! Silakan duduk, Nona."
  },
  AvgDialog_22127_Content_12 = {
    Text = "... Sulit untukmu, masih punya suasana hati untuk memikirkan ini."
  },
  AvgDialog_22127_Content_120 = {
    Text = "Tidak bisa aku juga menikmatinya?"
  },
  AvgDialog_22127_Content_121 = {
    Text = "Saya... agak malu... setelah saya kembali, saya akan menulisnya diam-diam untuk Anda, Penjaga {Male=tuan,Female=nyonya}."
  },
  AvgDialog_22127_Content_122 = {
    Text = "Giliran Anda, Tuan atau Nyonya {Male=tuan,Female=nyonya}."
  },
  AvgDialog_22127_Content_123 = {
    Text = "Hmm, biarkan aku memikirkannya…"
  },
  AvgDialog_22127_Content_124 = {
    Text = "Kereta listrik merayap di atas rel, mirip dengan ulat bulu."
  },
  AvgDialog_22127_Content_125 = {
    Text = "Perumpamaanku sangat halus, seperti sesuatu yang sulit dijelaskan."
  },
  AvgDialog_22127_Content_126 = {
    Text = "Ayo cepat, ke Medici Boulevard"
  },
  AvgDialog_22127_Content_129 = {
    Text = "Umumnya, Anda perlu menulis ulang kalimat tersebut, tetapi puisi dari sang Nona dapat membeli tiket tahunan untuk semua posisi, dan saya juga tidak ingin mengalami lebih banyak penderitaan. Silakan duduk."
  },
  AvgDialog_22127_Content_13 = {
    Text = "Horla, tidakkah kamu merasa bahwa kota Cité ini menjadi sangat aneh?"
  },
  AvgDialog_22127_Content_130 = {
    Text = "Ulat bulu membuka matanya, cahaya terang memancar keluar dari matanya."
  },
  AvgDialog_22127_Content_131 = {
    Text = "Itu bergerak dengan tenang ke arah depan."
  },
  AvgDialog_22127_Content_14 = {
    Text = "Tidak juga, meskipun aku sudah lupa seperti apa Cité itu, tapi menurutku, Cité seharusnya memang terlihat seperti ini."
  },
  AvgDialog_22127_Content_15 = {
    Text = "Tuan Putri ini benar. Cité adalah kota bunga dan puisi. Memang seharusnya terlihat seperti ini."
  },
  AvgDialog_22127_Content_16 = {
    Text = "Nyonya bangsawan tersenyum dan menepuk punggung Horla."
  },
  AvgDialog_22127_Content_17 = {Text = "Hehe..."},
  AvgDialog_22127_Content_18 = {
    Text = "Sepertinya pada saat inilah dia baru menyadari bahwa ada orang asing di sisinya. Dengan malu-malu, dia tersenyum tipis dan sedikit menyembunyikan diri di balik gulungan kertas domba, sementara wajahnya mulai memerah."
  },
  AvgDialog_22127_Content_19 = {
    Text = "Sebuah suara lonceng yang jernih terdengar, dan sebuah kereta muncul di hadapan kalian."
  },
  AvgDialog_22127_Content_2 = {
    Text = "Ini... ini terlalu..."
  },
  AvgDialog_22127_Content_20 = {
    Text = "Ah, mobilku hampir sampai... aku tidak bisa terus menemani kalian."
  },
  AvgDialog_22127_Content_21 = {
    Text = "Tidak disangka kalian akan datang, aku tidak menyiapkan hadiah apa pun… ini untukmu, semoga kau tidak keberatan."
  },
  AvgDialog_22127_Content_22 = {
    Text = "Dia mengulurkan tangannya dan menyerahkan sesuatu kepada Horla."
  },
  AvgDialog_22127_Content_23 = {Text = "Ini…"},
  AvgDialog_22127_Content_24 = {
    Text = "Sebuah mawar yang diwarnai dengan teknik aquarel, bergetar pelan tertiup angin yang entah dari mana datangnya."
  },
  AvgDialog_22127_Content_25 = {
    Text = "Horla mengangkat kepalanya dengan senyum untuk berterima kasih, namun wanita tua itu sudah naik ke kereta."
  },
  AvgDialog_22127_Content_26 = {
    Text = "Sampai jumpa lagi, Horla."
  },
  AvgDialog_22127_Content_27 = {
    Text = "Kereta kuda bergerak maju, dan segera menyatu dalam pemandangan tinta di kejauhan."
  },
  AvgDialog_22127_Content_28 = {
    Text = "Nyonya tua ini sangat baik. Namun, ada sesuatu yang terasa sedikit aneh……"
  },
  AvgDialog_22127_Content_29 = {
    Text = "Memang... Ah, lupa bertanya padanya tentang arah."
  },
  AvgDialog_22127_Content_3 = {
    Text = "Cité adalah kota bunga dan puisi."
  },
  AvgDialog_22127_Content_30 = {
    Text = "Lupakan saja, cari lagi orang-orang di sekitar sini."
  },
  AvgDialog_22127_Content_31 = {
    Text = "Kota sebesar ini, di jalanan hampir tidak terlihat ada orang... sungguh aneh."
  },
  AvgDialog_22127_Content_32 = {
    Text = "Perubahan dalam ciri-ciri visual, perbedaan jumlah orang… deskripsi dari para saksi mata itu tidak salah."
  },
  AvgDialog_22127_Content_33 = {
    Text = "… Bagus. Situasi di Cité lebih kurang seperti ini."
  },
  AvgDialog_22127_Content_34 = {
    Text = "Di sini situasinya agak aneh, tapi saat ini tidak ada bahaya yang dihadapi, dan juga tidak ditemukan tanda-tanda pelarutan."
  },
  AvgDialog_22127_Content_35 = {
    Text = "Saya dan Horla bersiap untuk melanjutkan perjalanan, segera menemukan petugas kontak, dan memverifikasi situasi di sini dengannya."
  },
  AvgDialog_22127_Content_36 = {
    Text = "Pihak sekolah sudah mempersiapkan Tugas, tetapi persiapan personel membutuhkan waktu."
  },
  AvgDialog_22127_Content_37 = {
    Text = "Mengerti, sebelum itu, penyelidikan di Cité akan kami tangani."
  },
  AvgDialog_22127_Content_38 = {
    Text = "Matikan komunikasi Perak, kamu waspada memandang sekeliling."
  },
  AvgDialog_22127_Content_39 = {
    Text = "Kota ini tampaknya diselimuti oleh semacam filter aneh, semua bangunan seperti lukisan cat minyak yang telah dicoret-coret secara sembarangan, berdiri dengan cara yang sangat tidak masuk akal namun tetap memiliki keanehan tersendiri."
  },
  AvgDialog_22127_Content_4 = {
    Text = "Cité saat ini, memang pantas menyandang gelar ini."
  },
  AvgDialog_22127_Content_40 = {
    Text = "Kalian telah berjalan di jalan ini selama sepuluh menit, tanpa melihat seorang pun. Hanya ada bangunan-bangunan aneh di tepi jalan, serta bunga-bunga indah yang mengelilingi bangunan-bangunan tersebut."
  },
  AvgDialog_22127_Content_41 = {
    Text = "Di siang bolong seperti ini, sudah berjalan begitu lama tapi masih belum terlihat seorang pun… Apakah orang-orang di Cité tidak keluar rumah?"
  },
  AvgDialog_22127_Content_42 = {Text = "Ah!"},
  AvgDialog_22127_Content_43 = {
    Text = "Kenapa kamu bersembunyi di dalam gulungan kertas domba lagi..."
  },
  AvgDialog_22127_Content_44 = {
    Text = "Ting, ting, ting…"
  },
  AvgDialog_22127_Content_45 = {
    Text = "Seorang penduduk bersenandung lagu yang tidak dikenal, melewati persimpangan di depan kalian, meninggalkan bayangan punggungnya."
  },
  AvgDialog_22127_Content_46 = {
    Text = "Dia mengenakan setelan jas yang terlihat sangat kaku, dan bentuk kepalanya tampak sedikit aneh."
  },
  AvgDialog_22127_Content_47 = {
    Text = "Ah… Syukurlah, akhirnya aku melihat seseorang."
  },
  AvgDialog_22127_Content_48 = {
    Text = "Kamu melangkah dengan cepat ke depan."
  },
  AvgDialog_22127_Content_49 = {
    Text = "Tuan, selamat siang."
  },
  AvgDialog_22127_Content_5 = {
    Text = "Di bawah bimbingan wanita bangsawan, kamu melangkah maju. Segala sesuatu yang memasuki pandanganmu hampir membuatmu kehilangan kemampuan berpikir."
  },
  AvgDialog_22127_Content_50 = {
    Text = "Ah, halo! Yang terhormat {Male=tuan,Female=nyonya}. Apakah ada yang bisa saya bantu?"
  },
  AvgDialog_22127_Content_51 = {Text = "!!!"},
  AvgDialog_22127_Content_52 = {
    Text = "Dia berbalik. Di atas setelan jasnya, terdapat kepala lebah raksasa."
  },
  AvgDialog_22127_Content_53 = {
    Text = "Ada apa, {Male=tuan,Female=nyonya}? Apakah ada kata-kata saya yang kurang pantas sehingga membuat Anda merasa tidak nyaman?"
  },
  AvgDialog_22127_Content_54 = {
    Text = "Tidak... eh, tidak."
  },
  AvgDialog_22127_Content_55 = {
    Text = "Saya ingin bertanya, bagaimana cara menuju Medici Avenue?"
  },
  AvgDialog_22127_Content_56 = {
    Text = "Ah, {Male=tuan,Female=nyonya}, apakah Anda baru tiba di Cité, ya?"
  },
  AvgDialog_22127_Content_57 = {Text = "Ya."},
  AvgDialog_22127_Content_58 = {
    Text = "Tidak heran, bahkan jalan paling terkenal ini pun tidak diketahui.."
  },
  AvgDialog_22127_Content_59 = {
    Text = "Tenang saja, tenang saja, warga Cité sangat ramah dan suka menolong. Jalan Medici ada di …"
  },
  AvgDialog_22127_Content_6 = {
    Text = "Kamu berjalan melewati jalan yang samar-samar terlihat, membelai batu bata yang ternoda pada bangunan, dan memetik daun tunggul yang seperti tinta warna."
  },
  AvgDialog_22127_Content_60 = {Text = "Ukh——"},
  AvgDialog_22127_Content_61 = {
    Text = "Tuan Lebah ini tiba-tiba mulai kejang-kejang sebelum menyelesaikan ucapannya."
  },
  AvgDialog_22127_Content_62 = {
    Text = "Sepasang sayap membran besar menyobek jaketnya, meleleh dan menetes dengan cepat seperti mentega di bawah terik matahari."
  },
  AvgDialog_22127_Content_63 = {
    Text = "Madu, Tuan Lebah! …"
  },
  AvgDialog_22127_Content_64 = {Text = "Pak—"},
  AvgDialog_22127_Content_65 = {
    Text = "Tubuh lebah berbentuk manusia jatuh ke tanah, berubah menjadi hitam, kemudian berubah menjadi serbuk dan menghilang di udara."
  },
  AvgDialog_22127_Content_66 = {
    Text = "Bukan manifestasi tipikal dari tubuh alien Pelarutan…"
  },
  AvgDialog_22127_Content_67 = {
    Text = "Kamu sekali lagi memeriksa lingkungan sekitar dengan saksama."
  },
  AvgDialog_22127_Content_68 = {
    Text = "Bangunan-bangunan yang mengelilingimu tampak seperti lukisan abstrak. Jika diamati dengan cermat, penduduk yang sesekali muncul di kejauhan memiliki tubuh yang menyerupai berbagai jenis hewan dan tumbuhan."
  },
  AvgDialog_22127_Content_69 = {
    Text = "——Cité di depannya, seolah-olah berasal dari mimpi aneh yang entah dari mana."
  },
  AvgDialog_22127_Content_7 = {
    Text = "Kota ini tampaknya diselimuti oleh semacam filter aneh, semua bangunan dan tanaman seakan-akan menjadi lukisan yang diwarnai dengan kuas cat air, berdiri secara aneh dalam bentuk yang sangat tidak masuk akal."
  },
  AvgDialog_22127_Content_70 = {Text = "Ding——"},
  AvgDialog_22127_Content_71 = {
    Text = "Lencana di dada berkilauan dengan cahaya perak. Kamu menyalakan komunikasi."
  },
  AvgDialog_22127_Content_72 = {
    Text = "Profesor Boneka, saya baru saja menemui sebuah anomali pelarutan non-tipe…"
  },
  AvgDialog_22127_Content_73 = {
    Text = "Cité menelepon. Seorang warga di jalan kota yang ramai berubah menjadi D-debu."
  },
  AvgDialog_22127_Content_74 = {Text = "!!!"},
  AvgDialog_22127_Content_75 = {
    Text = "Dan situasi yang aku alami di sini... benar-benar sama..."
  },
  AvgDialog_22127_Content_76 = {
    Text = "Tapi aku berada di Cité, di sini sama sekali tidak terasa seperti kawasan yang ramai."
  },
  AvgDialog_22127_Content_77 = {
    Text = "Memang, di sini juga tidak terlihat adanya antarmuka antara dunia nyata dan Domain. Namun, jika ini bukan Domain, mengapa tempat ini dan orang-orang ini berubah seperti ini… Tidak masuk akal…"
  },
  AvgDialog_22127_Content_78 = {
    Text = "Dengan demikian, Domain ini kemungkinan besar berbeda dari Domain biasa, dan merupakan ruang yang sepenuhnya independen."
  },
  AvgDialog_22127_Content_79 = {
    Text = "Namun, dampaknya terhadap Cité memang nyata."
  },
  AvgDialog_22127_Content_8 = {
    Text = "Penjaga {Male=tuan,Female=nyonya}, apakah Anda melihat rumah ini? Sepertinya ada beberapa garis yang melayang di atasnya?"
  },
  AvgDialog_22127_Content_80 = {
    Text = "Bagaimanapun, sebelum situasi menjadi lebih rumit, penyebabnya harus segera ditemukan."
  },
  AvgDialog_22127_Content_81 = {Text = "Paham."},
  AvgDialog_22127_Content_82 = {
    Text = "Komunikasi berakhir, suasana menjadi semakin tegang."
  },
  AvgDialog_22127_Content_83 = {
    Text = "Penjaga {Male=tuan,Female=nyonya}… Tuan Lebah, apakah sudah mati?"
  },
  AvgDialog_22127_Content_84 = {
    Text = "Kamu memandang Horla dan menepuk punggungnya."
  },
  AvgDialog_22127_Content_85 = {
    Text = "Ini bukan Cité yang sebenarnya. Mungkin, dia hanyalah semacam ilusi saja…"
  },
  AvgDialog_22127_Content_86 = {
    Text = "Mudah-mudahan begitu..."
  },
  AvgDialog_22127_Content_87 = {
    Text = "Horla memetik selembar daun wutong dan meletakkannya di atas sisa-sisa D-debu."
  },
  AvgDialog_22127_Content_88 = {
    Text = "Ayo pergi ke Medici Boulevard, cari kontak untuk melakukan penyelidikan."
  },
  AvgDialog_22127_Content_9 = {
    Text = "Seperti puisi yang terukir di bangunan… sungguh indah!"
  },
  AvgDialog_22127_Content_90 = {
    Text = "Lihat, Penjaga {Male=tuan,Female=nyonya}! Trem!"
  },
  AvgDialog_22127_Content_91 = {
    Text = "Kalian berjalan maju beberapa langkah. Sebuah gumpalan hitam pekat mendekati kalian."
  },
  AvgDialog_22127_Content_92 = {
    Text = "Ada trem, tetapi tidak menemukan papan halte. Tidak tahu apakah bisa sampai ke tempat yang ingin kita kunjungi."
  },
  AvgDialog_22127_Content_93 = {
    Text = "Pernahkah saya ceritakan kepada Anda? Dulu, jika melihat keluar dari pagar taman itu, bisa melihat trem lewat, namun saya tak pernah benar-benar menaikinya."
  },
  AvgDialog_22127_Content_94 = {
    Text = "Saya sangat ingin mencobanya sekali. Saya pikir, itu bisa membawa saya ke mana saja."
  },
  AvgDialog_22127_Content_95 = {
    Text = "Setiap kali melihat trem itu, saya merasa seperti itu adalah sesuatu yang besar ……"
  },
  AvgDialog_22127_Content_96 = {
    Text = "Halo, apakah Anda membutuhkan tumpangan?"
  },
  AvgDialog_22127_Content_97 = {Text = "!!!"},
  AvgDialog_22127_Content_98 = {
    Text = "Di atas rel yang berkelok, seekor ulat raksasa berhenti tepat di depan kalian."
  },
  AvgDialog_22127_Content_99 = {
    Text = "Ah! Sama seperti yang aku bayangkan! Ini kereta ulat bulu!"
  },
  AvgDialog_22128_Content_1 = {Text = "Sisa Harum"},
  AvgDialog_22128_Content_10 = {
    Text = "...Saya masih ada urusan, mohon izinkan saya undur diri lebih dulu..."
  },
  AvgDialog_22128_Content_11 = {
    Text = "Hei hei hei! Nymphaea!"
  },
  AvgDialog_22128_Content_12 = {Text = "Hanna."},
  AvgDialog_22128_Content_13 = {
    Text = "Tunggu sebentar, Penjaga! Saya ada urusan mendesak dengan Nona Nymphaea! Mungkin ini akan menjadi berita utama!"
  },
  AvgDialog_22128_Content_14 = {
    Text = "Horla menyuruhku untuk menemuimu."
  },
  AvgDialog_22128_Content_15 = {Text = "Hmm?!!!"},
  AvgDialog_22128_Content_16 = {
    Text = "Hanna tiba-tiba menghentikan langkahnya."
  },
  AvgDialog_22128_Content_17 = {
    Text = "Dia meminta saya untuk memberikan ini kepada Anda."
  },
  AvgDialog_22128_Content_18 = {
    Text = "\"Tempat Tinggal Mawar\"，Horla·Colette..."
  },
  AvgDialog_22128_Content_19 = {
    Text = "Ini!! Koleksi puisi Horla?!!! Dan nama pena baru Horla?!"
  },
  AvgDialog_22128_Content_2 = {
    Text = "Nymphaea! Nymphaea!"
  },
  AvgDialog_22128_Content_20 = {
    Text = "Dia meminta saya untuk menyampaikan, jika kamu merasa cocok, tolong bantu dia mempublikasikannya di ……"
  },
  AvgDialog_22128_Content_21 = {
    Text = "Tidak masalah, tidak masalah! Bagus atau tidaknya puisi tidak penting, yang penting ada topik untuk dibahas!"
  },
  AvgDialog_22128_Content_22 = {
    Text = "Selain itu, Penjaga, apakah Horla bersedia menerima wawancara khusus saya?!"
  },
  AvgDialog_22128_Content_23 = {
    Text = "Kamu diam-diam bawa aku untuk bertemu dengannya..."
  },
  AvgDialog_22128_Content_24 = {
    Text = "Jika terlalu serakah, hati-hati nanti tidak ada puisi yang bisa diterbitkan."
  },
  AvgDialog_22128_Content_25 = {Text = "Oh……"},
  AvgDialog_22128_Content_26 = {
    Text = "Puisi telah diberikan kepada Hanna."
  },
  AvgDialog_22128_Content_27 = {
    Text = "Kamu sebelumnya mengatakan padaku bahwa Puisi tidak membawa kesialan, aku sama sekali tidak percaya."
  },
  AvgDialog_22128_Content_28 = {
    Text = "Setelah kejadian ini, saya akhirnya benar-benar memahaminya."
  },
  AvgDialog_22128_Content_29 = {
    Text = "Terima kasih, Penjaga {Male=tuan,Female=nyonya}!"
  },
  AvgDialog_22128_Content_3 = {
    Text = "Ah, Nona Hannah, kau datang mencariku lagi…"
  },
  AvgDialog_22128_Content_30 = {
    Text = "Kata-kata ini bisa kamu simpan untuk saat Hanna memberikan wawancara eksklusif kepadamu..."
  },
  AvgDialog_22128_Content_31 = {
    Text = "Ah… jangan, jangan… aku masih agak takut berbicara dengan orang lain… tapi aku akan mencoba menyesuaikan diri perlahan-lahan!"
  },
  AvgDialog_22128_Content_32 = {
    Text = "Hanya bercanda. Aku sudah menolaknya untukmu."
  },
  AvgDialog_22128_Content_33 = {
    Text = "Horla menghela napas panjang. Kamu berjalan mendekatinya."
  },
  AvgDialog_22128_Content_34 = {
    Text = "Kamu tahu, meskipun Hannah menerbitkan puisi, tidak banyak orang yang benar-benar akan peduli."
  },
  AvgDialog_22128_Content_35 = {
    Text = "Yang semua orang perhatikan sebenarnya hanyalah cerita dan topik seputar puisi itu."
  },
  AvgDialog_22128_Content_36 = {
    Text = "Hmm, saya mengerti, Penjaga {Male=tuan,Female=nyonya}."
  },
  AvgDialog_22128_Content_37 = {
    Text = "Bahkan di kota seperti Cité, sangat sedikit orang yang benar-benar membaca puisi…"
  },
  AvgDialog_22128_Content_38 = {
    Text = "Tidak masalah?"
  },
  AvgDialog_22128_Content_39 = {
    Text = "Bagi Colette, ini adalah cara terbaik untuk mengenang."
  },
  AvgDialog_22128_Content_4 = {
    Text = "Saya juga sangat senang bertemu denganmu!"
  },
  AvgDialog_22128_Content_40 = {
    Text = "Adapun puisi itu sendiri..."
  },
  AvgDialog_22128_Content_41 = {
    Text = "Dia melepas satu kelopak dari mawar di atas matanya, lalu mendekatkannya ke ujung hidungnya."
  },
  AvgDialog_22128_Content_42 = {
    Text = "Di Cité, meskipun tidak terlihat bunga di mana-mana, aroma bunga tetap tercium di udara."
  },
  AvgDialog_22128_Content_43 = {
    Text = "Puisi seperti bunga, tidak harus selalu dilihat oleh orang lain…"
  },
  AvgDialog_22128_Content_44 = {
    Text = "Dia berbalik dan tersenyum ke arahmu."
  },
  AvgDialog_22128_Content_45 = {
    Text = "Penjaga {Male=tuan,Female=nyonya}, apakah Anda percaya?"
  },
  AvgDialog_22128_Content_46 = {
    Text = "Cité masih jarang ada orang yang membaca puisi, tapi menurut saya, mawar sebenarnya sudah lama mekar di hati setiap orang."
  },
  AvgDialog_22128_Content_47 = {
    Text = "Dia mengangkat tangannya. Kelopak bunga merah menyala meninggalkan telapak tangannya, melayang dengan anggun ke kejauhan."
  },
  AvgDialog_22128_Content_48 = {
    Text = "Angin membawa aroma mawar, seperti yang terbawa dari Cité puluhan tahun lalu."
  },
  AvgDialog_22128_Content_5 = {
    Text = "Eh, ada urusan mendesak yang ingin kutanyakan padamu..."
  },
  AvgDialog_22128_Content_6 = {
    Text = "Saya tidak tahu di mana Horla berada."
  },
  AvgDialog_22128_Content_7 = {
    Text = "Apa?! Bagaimana mungkin! Dia sudah kembali selama sehari, dan masih belum menghubungimu!"
  },
  AvgDialog_22128_Content_8 = {
    Text = "Apakah rumor tentang hubungan buruk antara kalian berdua di luar sana benar?"
  },
  AvgDialog_22128_Content_9 = {
    Text = "Apakah karena saling merendahkan di antara para pecinta sastra? Atau karena mereka menjadi rival dalam cinta?!"
  },
  AvgDialog_22129_Content_1 = {
    Text = "Mazmur 1843"
  },
  AvgDialog_22129_Content_10 = {
    Text = "Horla... tidak apa-apa, mereka semua hanyalah representasi dari Puisi, jangan khawatir..."
  },
  AvgDialog_22129_Content_11 = {
    Text = "Kandang ini seharusnya merupakan produk dari Pelarutan. Bantu aku membeli sedikit waktu, aku akan segera mencari cara untuk keluar dari sini."
  },
  AvgDialog_22129_Content_12 = {
    Text = "Ah, aku hampir lupa, kau masih sangat pemalu seperti dulu, Horla."
  },
  AvgDialog_22129_Content_13 = {
    Text = "Horla perlahan muncul dari balik gulungan perkamen."
  },
  AvgDialog_22129_Content_14 = {
    Text = "Colette, saya sudah membaca suratmu untuk Herbert..."
  },
  AvgDialog_22129_Content_15 = {
    Text = "Aku sangat ingin mendengarnya, pada saat seperti ini, bagaimana kamu akan membujukku?"
  },
  AvgDialog_22129_Content_16 = {
    Text = "Aku tidak bermaksud membujukmu… Aku bisa memahami apa yang kamu lakukan."
  },
  AvgDialog_22129_Content_17 = {
    Text = "Heh... apa?"
  },
  AvgDialog_22129_Content_18 = {
    Text = "Demi ketenaran dan kekuasaan, mengorbankan diriku, mengorbankan puisi, mengorbankan Cité, semua itu bisa kumengerti… Semua ini masuk akal bagiku."
  },
  AvgDialog_22129_Content_19 = {
    Text = "Saya suka menulis puisi, Colette. Saya mencoba mendengarkan suara hati dari semua orang dan segala sesuatu… Kamu adalah teman terbaikku, bagaimana mungkin aku tidak mendengar suara hatimu?"
  },
  AvgDialog_22129_Content_2 = {
    Text = "Nyonya Colette! Rakyat Cité akan selalu setia kepada Anda!"
  },
  AvgDialog_22129_Content_20 = {
    Text = "Setelah difusi pelarutan... taman ini akan dihapus dari memori semua orang..."
  },
  AvgDialog_22129_Content_21 = {
    Text = "Semua hal yang terjadi di sini, hari-hari bahagia dan sedih yang telah kita lalui bersama… Apakah kau benar-benar bisa meninggalkan semuanya begitu saja?"
  },
  AvgDialog_22129_Content_22 = {
    Text = "Colette terkejut sejenak, lalu tertawa. Dia semakin tertawa keras, hampir lupa menjaga sikapnya sebagai seorang bangsawan."
  },
  AvgDialog_22129_Content_23 = {
    Text = "Aku pikir... kamu mau bicara sesuatu denganku..."
  },
  AvgDialog_22129_Content_24 = {
    Text = "Cité memiliki begitu banyak orang, aku bahkan tidak peduli dengan nyawa mereka. Sekarang kau bertanya padaku, apakah aku peduli dengan sebuah taman?"
  },
  AvgDialog_22129_Content_25 = {
    Text = "Dia menghela napas dan mengangkat tubuhnya."
  },
  AvgDialog_22129_Content_26 = {
    Text = "Horla, sejak kecil kau sudah sangat disukai. Meskipun aku adalah orang yang menghidupi kita berdua dengan kerja keras, orang-orang selalu memuji dirimu…"
  },
  AvgDialog_22129_Content_27 = {
    Text = "Kamu memiliki bakat yang luar biasa, tapi apa gunanya? Ada beberapa hal yang tidak akan pernah kamu pahami."
  },
  AvgDialog_22129_Content_28 = {
    Text = "Puisi, emosi, kenangan, moralitas... semuanya adalah beban. Hanya kekuasaan dan kemasyhuran yang benar-benar abadi."
  },
  AvgDialog_22129_Content_29 = {
    Text = "Kata-kata yang bagus! Nyonya Colette!"
  },
  AvgDialog_22129_Content_3 = {
    Text = "Minggir! Kamu menghalangi aku!"
  },
  AvgDialog_22129_Content_30 = {
    Text = "Tepuk tangan dan sorakan meriah bergema dari alun-alun, gelombang suara yang besar menenggelamkan kalian."
  },
  AvgDialog_22129_Content_31 = {
    Text = "Dengar, Horla. Dengarkan suara hati rakyat Cité."
  },
  AvgDialog_22129_Content_32 = {
    Text = "Di dunia ini, puisi tidak memiliki makna. Di dunia lain pun, tetap sama."
  },
  AvgDialog_22129_Content_33 = {
    Text = "Ternyata, beginilah cara kamu memikirkannya... Aku mengerti, Colette."
  },
  AvgDialog_22129_Content_34 = {
    Text = "Jujur, aku sangat senang kamu bisa datang ke sini."
  },
  AvgDialog_22129_Content_35 = {
    Text = "Di tahap paling penting dalam hidupku, kau kembali menjadi saksi bagiku."
  },
  AvgDialog_22129_Content_36 = {
    Text = "Dia mengangkat kedua tangannya."
  },
  AvgDialog_22129_Content_37 = {
    Text = "Di alun-alun, semua orang berlutut ke arahnya."
  },
  AvgDialog_22129_Content_38 = {
    Text = "Tidak ada puisi, tidak ada ceramah. Hanya ada pemujaan fanatik yang dibayangkan. Hanya ada kekuasaan murni."
  },
  AvgDialog_22129_Content_39 = {
    Text = "Tanah mulai bergetar pelan. Kamu memperhatikan bahwa Pelarutan sedang meluas dengan kecepatan yang terlihat jelas, dan Puisi menjadi pusatnya."
  },
  AvgDialog_22129_Content_4 = {
    Text = "Nyonya Colette! Nyonya Colette, lihat ke sini!"
  },
  AvgDialog_22129_Content_40 = {
    Text = "Lihatlah, Horla. Lihatlah aku, meraih kemenangan lain —"
  },
  AvgDialog_22129_Content_41 = {
    Text = "Klong——"
  },
  AvgDialog_22129_Content_42 = {Text = "?!"},
  AvgDialog_22129_Content_43 = {
    Text = "Kilauan perak lenyap dalam sekejap. Sangkar menghilang, dan kamu serta Horla jatuh ke tanah."
  },
  AvgDialog_22129_Content_44 = {
    Text = "Mungkin sebuah kesalahan bagiku untuk datang ke sini sebagai penonton, Nyonya Colette."
  },
  AvgDialog_22129_Content_45 = {
    Text = "Kunci perak Mythag… bahkan Tuan Herbert pun sangat iri."
  },
  AvgDialog_22129_Content_46 = {
    Text = "Tapi aku sangat ingin tahu, di tempat seperti ini, meskipun kalian berhasil melarikan diri dari kurungan, apa yang bisa kalian lakukan?"
  },
  AvgDialog_22129_Content_5 = {
    Text = "Di atas Alun-Alun Mawar, kepala-kepala orang bergerak seperti lautan manusia. Seluruh warga Cité berdesakan di sini, dan jika dilihat dari ketinggian, tampak seperti bola hitam raksasa yang bergerak perlahan."
  },
  AvgDialog_22129_Content_6 = {
    Text = "Betapa menggembirakan pemandangan ini... bukankah begitu?"
  },
  AvgDialog_22129_Content_7 = {
    Text = "Colette mengenakan gaun megah, berdiri di atas panggung yang indah, dan dengan anggun melambaikan tangan ke bawah."
  },
  AvgDialog_22129_Content_8 = {
    Text = "Di belakangnya, kandang hitam dengan material yang tidak diketahui mengurungmu dan Horla, tergantung di bagian belakang panggung."
  },
  AvgDialog_22129_Content_9 = {
    Text = "Di bawah tatapan orang banyak, Horla meringkuk di bawah gulungan kertas domba, tubuhnya gemetar tak terkendali."
  },
  AvgDialog_22130_Content_10 = {
    Text = "Mungkin, pria tua yang merokok tadi adalah salah satu anggota rahasia dari Komite."
  },
  AvgDialog_22130_Content_100 = {
    Text = "Anda, halo... Nyonya ini..."
  },
  AvgDialog_22130_Content_101 = {
    Text = "Horla, apakah kamu memutus kemampuan untuk menjadi tak terlihat?"
  },
  AvgDialog_22130_Content_102 = {
    Text = "Aku tidak... Bu, apakah Anda bisa melihatku?"
  },
  AvgDialog_22130_Content_103 = {
    Text = "Di Cité Baru, segala sesuatu yang indah harus terlihat."
  },
  AvgDialog_22130_Content_104 = {
    Text = "Cité baru…"
  },
  AvgDialog_22130_Content_105 = {
    Text = "Ah, kita sudah tiba."
  },
  AvgDialog_22130_Content_106 = {
    Text = "Kamu menoleh."
  },
  AvgDialog_22130_Content_107 = {
    Text = "Sebuah lukisan yang belum pernah kau lihat terbentang di hadapanmu."
  },
  AvgDialog_22130_Content_108 = {
    Text = "Kapal pesiar menabrak perangkat penyangga di sepanjang pantai, mengeluarkan suara yang berat dan tumpul."
  },
  AvgDialog_22130_Content_109 = {
    Text = "Kamu dan Horla terpaku memandangi adegan di depan mata, seakan-akan lupa bagaimana cara berjalan."
  },
  AvgDialog_22130_Content_11 = {
    Text = "Saya selalu merasa bahwa dia memiliki aura misterius yang sangat kuat… siapa yang tahu?"
  },
  AvgDialog_22130_Content_110 = {
    Text = "Mobil saya masih agak lama datang, izinkan saya mengajak kalian berkeliling sebentar."
  },
  AvgDialog_22130_Content_111 = {
    Text = "Dia mengangkat tangannya, lengan itu membentuk busur yang anggun."
  },
  AvgDialog_22130_Content_112 = {
    Text = "Selamat datang di Cité, para tamu dari jauh."
  },
  AvgDialog_22130_Content_12 = {
    Text = "Sinar matahari menyinari dek. Horla menutup matanya dan sedikit membuka kedua tangannya."
  },
  AvgDialog_22130_Content_13 = {
    Text = "Setelah menyadari tatapanmu, dia dengan malu-malu menarik kembali kedua tangannya dan menyilangkannya di belakang punggungnya."
  },
  AvgDialog_22130_Content_14 = {
    Text = "Tidak buruk, jauh lebih baik daripada yang kubayangkan."
  },
  AvgDialog_22130_Content_15 = {
    Text = "Saya kira, setelah melihat begitu banyak orang di kapal pesiar, kamu akan berpikir untuk kembali."
  },
  AvgDialog_22130_Content_16 = {
    Text = "Saat itu saya memang berpikir begitu, hanya saja merasa canggung untuk mengatakannya kepada Anda…"
  },
  AvgDialog_22130_Content_17 = {
    Text = "Ah! Penjaga {Male=tuan,Female=nyonya}, lihat! Itu Sungai szenyér!"
  },
  AvgDialog_22130_Content_18 = {
    Text = "Keluasan tanpa batas dari lautan hanya bertahan selama waktu yang singkat. Segera, sebuah mercusuar perlahan-lahan muncul dari bawah garis cakrawala."
  },
  AvgDialog_22130_Content_19 = {
    Text = "Di belakangnya, sebuah muara yang luas dan kota-kota di kedua sisinya yang tampak kabur pun masuk ke dalam pandangan kalian."
  },
  AvgDialog_22130_Content_2 = {Text = "Rumah"},
  AvgDialog_22130_Content_20 = {
    Text = "Nymphaea! Nymphaea!"
  },
  AvgDialog_22130_Content_21 = {
    Text = "Halo, ada yang bisa saya bantu?"
  },
  AvgDialog_22130_Content_22 = {
    Text = "Apakah kamu melihat Horla? Sangat mendesak!"
  },
  AvgDialog_22130_Content_23 = {
    Text = "Bukankah kamu punya semacam acara pembacaan puisi~? Menurut informan saya, Horla sering hadir di acara kalian."
  },
  AvgDialog_22130_Content_24 = {
    Text = "Kamu begitu dekat dengannya, pasti tahu di mana dia berada, kan?!"
  },
  AvgDialog_22130_Content_25 = {
    Text = "Maaf, terakhir kali saya melihat Horla sudah dua bulan yang lalu… Dia tidak suka tempat yang ramai."
  },
  AvgDialog_22130_Content_26 = {
    Text = "Lalu, apakah kamu memiliki puisinya? Pasti kalian sudah mengumpulkan banyak karyanya di pertemuan pembacaan puisi kalian, kan?!"
  },
  AvgDialog_22130_Content_27 = {
    Text = "Jika kamu memilikinya, aku sangat bersedia membayar mahal untuk itu."
  },
  AvgDialog_22130_Content_28 = {
    Text = "Hanna, apakah ada urusan yang ingin kamu bicarakan dengannya?"
  },
  AvgDialog_22130_Content_29 = {
    Text = "Edisi terbaru dari surat kabar sekolah tidak memiliki topik yang menarik. Horla tidak pernah suka diwawancarai, bahkan enggan menerbitkan kumpulan puisinya sendiri."
  },
  AvgDialog_22130_Content_3 = {
    Text = "Baiklah, Horla, para penumpang di sebelah sudah pergi."
  },
  AvgDialog_22130_Content_30 = {
    Text = "Jika bisa menerbitkan Puisi-nya, bahkan melakukan wawancara dengannya, penjualan majalah sekolah bulan ini pasti akan meningkat dua kali lipat!"
  },
  AvgDialog_22130_Content_31 = {
    Text = "Judulnya sudah kudapatkan, yaitu \"Taman dan Musim Semi——Kisah Tak Diketahui Sang Penyair Gadis Horla\"..."
  },
  AvgDialog_22130_Content_32 = {
    Text = "...Menurut statistik, jumlah kasus penampakan saat ini telah mencapai dua digit."
  },
  AvgDialog_22130_Content_33 = {
    Text = "Menurut deskripsi saksi mata, perubahan di Cité tidak tampak seperti yang disebabkan oleh pelarutan biasa."
  },
  AvgDialog_22130_Content_34 = {
    Text = "Cité sekarang, sangat..."
  },
  AvgDialog_22130_Content_35 = {Text = "Apa...?"},
  AvgDialog_22130_Content_36 = {
    Text = "Menurut saksi mata, \"sangat indah.\""
  },
  AvgDialog_22130_Content_37 = {
    Text = "Pelarutan... sangat indah?"
  },
  AvgDialog_22130_Content_38 = {
    Text = "Kurangnya logika adalah ciri umum dari kesaksian saksi mata."
  },
  AvgDialog_22130_Content_39 = {
    Text = "Dari omongan mereka yang kacau bisa disimpulkan bahwa keunikan dan cakupan pengaruh dari Acara kali ini sangatlah langka, namun tingkat bahayanya sangat rendah. Kedua hal ini sama sekali tidak sebanding."
  },
  AvgDialog_22130_Content_4 = {
    Text = "Benarkah? Tidak menipuku?"
  },
  AvgDialog_22130_Content_40 = {
    Text = "Kami belum pernah mengalami acara serupa. Apakah ini dipengaruhi oleh pelarutan, saat ini masih belum bisa dipastikan."
  },
  AvgDialog_22130_Content_41 = {
    Text = "Apa yang dikatakan oleh kontak di Cité?"
  },
  AvgDialog_22130_Content_42 = {
    Text = "Kontak melaporkan semuanya normal, jadi tingkat Acara ini tidak terlalu tinggi. Namun, kita masih perlu mengirim seseorang ke Cité untuk memeriksa…"
  },
  AvgDialog_22130_Content_43 = {Text = "BRAK—"},
  AvgDialog_22130_Content_44 = {
    Text = "Boneka belum selesai berbicara, sebuah sosok putih masuk seperti hantu ke dalam kantor dan bersembunyi di balik tirai."
  },
  AvgDialog_22130_Content_47 = {
    Text = "Horla, jika kamu sedang bersembunyi dari seseorang... kamu lupa menutup pintu."
  },
  AvgDialog_22130_Content_48 = {
    Text = "Ah! Maaf, maaf! Kami telah merepotkanmu... Penjaga {Male=tuan,Female=nyonya}! Nyonya Boneka!"
  },
  AvgDialog_22130_Content_49 = {
    Text = "Dia berlari keluar untuk menutup pintu kantor, lalu dengan cepat kembali bersembunyi di balik tirai."
  },
  AvgDialog_22130_Content_5 = {Text = "...benar."},
  AvgDialog_22130_Content_50 = {
    Text = "Horla! Di mana kamu? Horla!"
  },
  AvgDialog_22130_Content_51 = {
    Text = "Cepat keluar, Horla tersayang! Kami hanya ingin melakukan wawancara kecil saja~ Aku berjanji tidak akan menyakitimu!"
  },
  AvgDialog_22130_Content_52 = {
    Text = "Suara Hanna terdengar dari balik pintu, perlahan-lahan memudar."
  },
  AvgDialog_22130_Content_53 = {
    Text = "Akhirnya mulai mem-bully Horla, ya… Tampaknya tekanan penjualan majalah sekolah belakangan ini memang sangat besar."
  },
  AvgDialog_22130_Content_54 = {
    Text = "Tidak ingin diwawancarai juga tidak masalah, kamu sudah menulis begitu banyak puisi, cukup serahkan beberapa kepada Hanna, dan dia pasti akan membiarkanmu pergi."
  },
  AvgDialog_22130_Content_55 = {
    Text = "Saya... tidak begitu ingin..."
  },
  AvgDialog_22130_Content_56 = {
    Text = "Puisi-puisi itu hanya akan membawa kesengsaraan bagi semua orang… Aku tidak ingin hal seperti itu terjadi lagi."
  },
  AvgDialog_22130_Content_57 = {
    Text = "Mengingat masa lalu yang dialami Horla, kamu memahami maksudnya dan mengangguk."
  },
  AvgDialog_22130_Content_58 = {
    Text = "Aku seharusnya tetap tinggal di luar, bukan di tempat ramai seperti sekolah ini…"
  },
  AvgDialog_22130_Content_59 = {
    Text = "Penjaga {Male=tuan,Female=nyonya}, bisakah Anda membantu saya memikirkan solusi?"
  },
  AvgDialog_22130_Content_6 = {
    Text = "Horla mengintip dari bawah gulungan perkamen raksasa itu, dengan hati-hati memandang ke kiri dan kanan."
  },
  AvgDialog_22130_Content_60 = {
    Text = "Jujur saja, menghadapi indra penciuman dan mobilitas cerpelai itu, aku juga tidak punya cara yang terlalu baik."
  },
  AvgDialog_22130_Content_61 = {
    Text = "——Namun, jika kamu bersedia keluar, ada satu cara yang bisa membantu."
  },
  AvgDialog_22130_Content_62 = {
    Text = "Ah... Apakah harus keluar rumah..."
  },
  AvgDialog_22130_Content_63 = {
    Text = "Kemana perginya?"
  },
  AvgDialog_22130_Content_64 = {
    Text = "Kamu mengambil foto di atas meja dan menggoyangkannya ke arahnya."
  },
  AvgDialog_22130_Content_65 = {
    Text = "Cité, rumah."
  },
  AvgDialog_22130_Content_66 = {
    Text = "Kapal pesiar bergerak tanpa suara, rumah-rumah dan hamparan bunga di kedua sisi perlahan mengalir ke belakang, menghilang di tikungan lembut Sungai Szenyér."
  },
  AvgDialog_22130_Content_67 = {
    Text = "Horla menutup matanya. Senyuman merekah di wajahnya."
  },
  AvgDialog_22130_Content_68 = {
    Text = "Angin dari Cité! Cité adalah kota bunga, bahkan anginnya pun membawa aroma bunga."
  },
  AvgDialog_22130_Content_69 = {
    Text = "Meskipun sudah bertahun-tahun berlalu, aku masih bisa mengingatnya begitu mencium aromanya."
  },
  AvgDialog_22130_Content_7 = {
    Text = "Setelah memastikan tidak ada orang asing di sekitarnya, dia menghela napas lega dan keluar dari balik gulungan kertas domba."
  },
  AvgDialog_22130_Content_70 = {
    Text = "Apakah kamu akan merindukan pemandangan-pemandangan di Cité ini?"
  },
  AvgDialog_22130_Content_71 = {
    Text = "Sangat merindukannya! Namun, aku selalu hidup di rumah kaca. Sebagian besar tempat di Cité ini belum pernah kulihat secara nyata."
  },
  AvgDialog_22130_Content_72 = {
    Text = "Saya menulis banyak pemandangan Cité dalam puisi, namun pada akhirnya itu semua hanyalah khayalan... Jika ada kesempatan kali ini, saya ingin pergi melihat tempat-tempat itu."
  },
  AvgDialog_22130_Content_73 = {
    Text = "Tempat mana yang paling ingin kamu kunjungi?"
  },
  AvgDialog_22130_Content_74 = {
    Text = "Tempat yang paling ingin aku kunjungi, hmm... mungkin taman tempat aku tinggal dulu?"
  },
  AvgDialog_22130_Content_75 = {
    Text = "Setiap kali musim mawar bermekaran tiba, taman itu dipenuhi dengan bunga mawar, seakan-akan tinggal di dalam Mimpi!"
  },
  AvgDialog_22130_Content_76 = {
    Text = "Hanya saja, aku tidak tahu, setelah kebakaran besar itu, apakah masih ada mawar di sana sekarang. Dan juga Puisi…"
  },
  AvgDialog_22130_Content_77 = {
    Text = "Ketika api besar menyala, saya melihat bahwa tidak mungkin untuk keluar, jadi saya mengubur puisi yang saya tulis di tanah kebun. Kali ini, setelah kembali, saya ingin menemukannya."
  },
  AvgDialog_22130_Content_78 = {
    Text = "Kamu telah mengalami begitu banyak di Cité, aku pikir kamu tidak akan menyukai tempat ini dan tidak ingin melihat puisi itu lagi."
  },
  AvgDialog_22130_Content_79 = {
    Text = "Hal-hal itu tidak ada hubungannya dengan tanah dan orang-orang di sini... Cité adalah tempat yang sangat indah."
  },
  AvgDialog_22130_Content_8 = {
    Text = "Apakah kamu tahu bahwa mereka tidak bisa melihatmu, benar kan?"
  },
  AvgDialog_22130_Content_80 = {
    Text = "Adapun puisi... saya tidak bisa menjelaskan, Penjaga {Male=tuan,Female=nyonya}."
  },
  AvgDialog_22130_Content_81 = {
    Text = "Itu telah membawa banyak penderitaan kepada orang-orang di sekitarnya. Aku tidak suka hal itu, tetapi... itu juga merupakan hal yang paling berharga bagiku."
  },
  AvgDialog_22130_Content_82 = {
    Text = "Baik ingin menyimpan maupun menghancurkan, aku tetap ingin menemukannya."
  },
  AvgDialog_22130_Content_83 = {
    Text = "Tenang, aku pasti akan membawamu untuk melihatnya. Hanya saja, setelah bertahun-tahun, aku tidak tahu apakah masih bisa menemukannya."
  },
  AvgDialog_22130_Content_84 = {
    Text = "Seekor kupu-kupu hitam melayang dengan anggun dan hinggap di ujung jari Horla yang terentang."
  },
  AvgDialog_22130_Content_85 = {
    Text = "Lihat, Penjaga {Male=tuan,Female=nyonya}, seekor kupu-kupu!"
  },
  AvgDialog_22130_Content_86 = {
    Text = "Jika seekor kupu-kupu hinggap di tubuh seseorang, itu berarti di mata kupu-kupu, hidup orang tersebut seperti bunga."
  },
  AvgDialog_22130_Content_87 = {
    Text = "Di mata orang Cité, sebuah hidup yang seperti bunga selalu bisa mendapatkan keberuntungan~"
  },
  AvgDialog_22130_Content_88 = {
    Text = "Benar, Nona. Kamu memiliki aroma mawar."
  },
  AvgDialog_22130_Content_89 = {
    Text = "Cité memiliki banyak kebun mawar yang indah, kalian pasti akan sangat menyukai tempat ini~"
  },
  AvgDialog_22130_Content_9 = {
    Text = "Itu belum tentu. Di antara para pelancong mungkin ada Pembangun, peneliti dengan peralatan khusus, orang-orang berbakat dengan kemampuan luar biasa…"
  },
  AvgDialog_22130_Content_90 = {Text = "!!!"},
  AvgDialog_22130_Content_91 = {
    Text = "Horla, berhati-hatilah!"
  },
  AvgDialog_22130_Content_92 = {
    Text = "Kamu belum pernah melihat kupu-kupu berbentuk manusia seperti ini. Kamu mengulurkan tangan dan sedikit menarik Horla ke belakang."
  },
  AvgDialog_22130_Content_93 = {
    Text = "Ya, kupu-kupu yang bisa berbicara?!"
  },
  AvgDialog_22130_Content_94 = {
    Text = "Nyonya Kupu-kupu, maafkan saya... saya tidak terlalu pandai berbicara dengan orang lain..."
  },
  AvgDialog_22130_Content_95 = {
    Text = "Tidak memiliki serangan, tidak seperti tubuh pelarutan... juga bukan Fatamorgana..."
  },
  AvgDialog_22130_Content_96 = {
    Text = "Kupu-kupu berbentuk manusia berwarna hitam pekat mengepakkan sayapnya, bergoyang pergi meninggalkan kapal pesiar. Kamu waspada memandang sekeliling. Sungai Szenyér masih mengalir dengan tenang."
  },
  AvgDialog_22130_Content_97 = {
    Text = "Manusia yang berubah menjadi kupu-kupu... sebuah imaji yang sangat indah, bukan?"
  },
  AvgDialog_22130_Content_98 = {
    Text = "Seorang wanita bangsawan yang berpakaian mewah entah sejak kapan muncul di samping kalian. Dia memalingkan wajahnya dari Sungai Szenyér dan memberikan senyuman kecil kepada Horla."
  },
  AvgDialog_22130_Content_99 = {
    Text = "Namun, Nona. Mawar di matamu jauh lebih indah daripada kupu-kupu."
  },
  AvgDialog_22132_Content_1 = {
    Text = "Elegi Taman"
  },
  AvgDialog_22132_Content_10 = {
    Text = "Anak yang malang... kamu dan Horla seperti saudara kandung..."
  },
  AvgDialog_22132_Content_100 = {
    Text = "Kamu mengeluarkan puisi."
  },
  AvgDialog_22132_Content_101 = {
    Text = "Apakah kamu merindukannya?"
  },
  AvgDialog_22132_Content_102 = {
    Text = "Sangat, sangat merindukannya... Namun, tidak apa-apa, Penjaga {Male=tuan,Female=nyonya}."
  },
  AvgDialog_22132_Content_103 = {
    Text = "Dia mengusap air mata di sudut matanya, lalu tersenyum sambil menggelengkan kepala."
  },
  AvgDialog_22132_Content_104 = {
    Text = "Baik untukku, untuk Colette, maupun untuk seluruh Cité, kumpulan puisi ini hanya membawa penderitaan tanpa akhir…"
  },
  AvgDialog_22132_Content_105 = {
    Text = "Penjaga {Male=tuan,Female=nyonya}, bisakah aku melakukannya sendiri?"
  },
  AvgDialog_22132_Content_106 = {
    Text = "Berikan puisi kepada Horla"
  },
  AvgDialog_22132_Content_107 = {
    Text = "Aku akan merindukannya. Seharusnya, itu hanya ada dalam kenanganku."
  },
  AvgDialog_22132_Content_108 = {
    Text = "Selamat tinggal..."
  },
  AvgDialog_22132_Content_109 = {
    Text = "Api menyala di tangan Horla. Tak lama, kumpulan puisi itu berubah menjadi abu di tengah nyala api."
  },
  AvgDialog_22132_Content_11 = {
    Text = "Horla sudah tiada, kau harus hidup dengan baik. Rohnya di surga juga akan memberkati mu…"
  },
  AvgDialog_22132_Content_110 = {
    Text = "Bertahun-tahun yang lalu, seharusnya sudah menjadi abu bersamaku… Dengan begitu, mungkin tidak akan ada masalah seperti sekarang ini."
  },
  AvgDialog_22132_Content_111 = {
    Text = "Akhirnya, masalah teratasi."
  },
  AvgDialog_22132_Content_112 = {
    Text = "Penjaga {Male=tuan,Female=nyonya}, sepertinya saya tidak merasakan adanya perubahan?"
  },
  AvgDialog_22132_Content_113 = {
    Text = "Dampak seluas ini mungkin baru bisa hilang setelah beberapa waktu. Kita pergi dulu…"
  },
  AvgDialog_22132_Content_114 = {
    Text = "Apakah kamu suka ruangan ini, Horla? Semuanya di sini masih dipertahankan seperti beberapa dekade yang lalu."
  },
  AvgDialog_22132_Content_115 = {Text = "!!!"},
  AvgDialog_22132_Content_116 = {
    Text = "Puisi sudah terbakar… Rencanamu gagal, Colette."
  },
  AvgDialog_22132_Content_117 = {
    Text = "Puisi? Ah, yang kamu maksud adalah ini…"
  },
  AvgDialog_22132_Content_118 = {
    Text = "Dia melambaikan tangannya. Sebuah puisi baru muncul di tangannya, identik dengan yang terbakar sebelumnya."
  },
  AvgDialog_22132_Content_119 = {
    Text = "Cairan hitam pelarutan, menetes dari puisi ke tanah."
  },
  AvgDialog_22132_Content_12 = {
    Text = "Jangan biarkan dia bersedih... Colette, jalani hidup dengan baik."
  },
  AvgDialog_22132_Content_120 = {Text = "!!!"},
  AvgDialog_22132_Content_121 = {Text = "Kau……"},
  AvgDialog_22132_Content_122 = {
    Text = "Ini jebakan… Horla, bersiap untuk serangan! …"
  },
  AvgDialog_22132_Content_123 = {Text = "BRAK—"},
  AvgDialog_22132_Content_124 = {
    Text = "Sebuah sangkar tiba-tiba muncul di samping kalian, mengurung kalian di dalamnya."
  },
  AvgDialog_22132_Content_125 = {
    Text = "Ini... dalam Puisi, seharusnya tidak ada hal seperti ini..."
  },
  AvgDialog_22132_Content_126 = {
    Text = "Dalam puisi Horla, memang tidak pernah ada tulisan seperti ini."
  },
  AvgDialog_22132_Content_127 = {
    Text = "Namun, maaf, ini adalah puisi saya. Apa pun yang saya inginkan, akan muncul di sini."
  },
  AvgDialog_22132_Content_128 = {
    Text = "Dia tersenyum tipis sambil mengangkat tangannya, lalu menyimpan Puisi ke dalam pelukannya."
  },
  AvgDialog_22132_Content_129 = {
    Text = "… Di Cité ini, aku adalah satu-satunya tuan."
  },
  AvgDialog_22132_Content_13 = {
    Text = "Pada awalnya, banyak orang datang untuk menghiburnya. Perlahan-lahan, orang-orang di sekitarnya mulai pergi, meninggalkan waktu bagi dirinya sendiri."
  },
  AvgDialog_22132_Content_130 = {
    Text = "Dang——Dang——Dang——"
  },
  AvgDialog_22132_Content_131 = {
    Text = "Dengarlah, Horla. Lonceng tengah malam telah berbunyi."
  },
  AvgDialog_22132_Content_132 = {
    Text = "Hari ini adalah hari perayaan terbesar di Cité… Saya merasa sangat terhormat bisa menyambut dua tamu terhormat untuk menyaksikan upacara ini."
  },
  AvgDialog_22132_Content_133 = {
    Text = "Penjaga, bawa mereka ke alun-alun."
  },
  AvgDialog_22132_Content_134 = {
    Text = "Saya telah menyiapkan posisi terbaik untuk dua tamu terhormat menyaksikan upacara ini."
  },
  AvgDialog_22132_Content_14 = {
    Text = "Colette berdiri di samping abu dari rumah kaca yang telah ia kelola dengan susah payah, tak bergerak, membiarkan sisa-sisa api membakar wajahnya."
  },
  AvgDialog_22132_Content_15 = {
    Text = "Setetes air mata meluncur di wajahnya, lalu segera menguap dalam sisa panas api."
  },
  AvgDialog_22132_Content_16 = {
    Text = "Horla, mereka benar… kau akan memberkatiku. Kau tidak akan membenciku."
  },
  AvgDialog_22132_Content_17 = {
    Text = "Tidak akan membenciku karena telah merenggut segalanya darimu. Bakatmu, hidupmu… meskipun begitu, kau tetap tidak akan membenciku."
  },
  AvgDialog_22132_Content_18 = {
    Text = "Kamu begitu baik dan mulia. Semua orang di hadapanmu tampak rendah dan tidak berarti."
  },
  AvgDialog_22132_Content_19 = {
    Text = "Aku sudah berusaha keras untuk hidup... tapi dibandingkan denganmu, kenapa aku selalu menjadi orang yang rendah?"
  },
  AvgDialog_22132_Content_2 = {
    Text = "Padamkan api! Cepat padamkan api!"
  },
  AvgDialog_22132_Content_20 = {
    Text = "Sungguh kejam, Horla. Kau bahkan tidak memberiku satu alasan pun untuk membencimu. Apakah kau benar-benar ingin aku menghabiskan sisa hidupku dalam penderitaan…"
  },
  AvgDialog_22132_Content_21 = {
    Text = "Isak tangis terdengar. Colette menghapus air mata dari wajahnya. Abu menyebar, menghiasi wajahnya secara sembarangan."
  },
  AvgDialog_22132_Content_22 = {
    Text = "Dia meniru sikap seorang bangsawan, dengan angkuh mengangkat kepalanya dan tersenyum ke arah taman yang telah berubah menjadi bara api dan abu."
  },
  AvgDialog_22132_Content_23 = {
    Text = "...Kalau begitu, selamat tinggal, Horla."
  },
  AvgDialog_22132_Content_24 = {
    Text = "Pletak——"
  },
  AvgDialog_22132_Content_25 = {
    Text = "Setetes air mata jatuh di atas Puisi, menghasilkan suara yang jelas di dalam ruangan."
  },
  AvgDialog_22132_Content_26 = {
    Text = "Sudah sangat lama aku tidak merasakan ini... Horla, kau masih sama seperti dulu, penuh dengan kejutan."
  },
  AvgDialog_22132_Content_27 = {
    Text = "Kamu berkata, \"Mengapa kamu tidak meninggalkan gambaran dirimu sendiri di dalam Puisi?\""
  },
  AvgDialog_22132_Content_28 = {
    Text = "Sungguh tidak mudah untuk bertemu denganmu... Sayang sekali."
  },
  AvgDialog_22132_Content_29 = {
    Text = "Nyonya Colette, lonceng tengah malam segera berbunyi. Mohon bersiap lebih awal."
  },
  AvgDialog_22132_Content_3 = {
    Text = "Tidak ada waktu lagi… Tidak ada yang tersisa di kebun…"
  },
  AvgDialog_22132_Content_30 = {
    Text = "Hmm, mengerti."
  },
  AvgDialog_22132_Content_31 = {
    Text = "Dia duduk di depan cermin, dan pelayan mengeluarkan saputangan untuk dengan hati-hati menghapus jejak air mata di wajahnya."
  },
  AvgDialog_22132_Content_32 = {
    Text = "Hari ini adalah hari besar, bahkan penonton terbaik sudah memasuki tempatnya… riasan hari ini tidak boleh luntur."
  },
  AvgDialog_22132_Content_33 = {
    Text = "Dia dengan cermat memperhatikan dirinya di cermin, mengangkat sudut bibirnya, dan menampilkan senyuman seorang bangsawan pemenang."
  },
  AvgDialog_22132_Content_34 = {
    Text = "Penjaga {Male=tuan,Female=nyonya}, ke sini!"
  },
  AvgDialog_22132_Content_35 = {
    Text = "Jalan menuju menara lonceng memang sangat rumit… Banyak monster yang berjaga di sepanjang jalan."
  },
  AvgDialog_22132_Content_36 = {
    Text = "Dalam puisi \"Suara Lonceng Kota Puisi\", jalan menuju menara lonceng adalah sebuah labirin. Ini melambangkan kebingungan batin penduduk Kota Puisi."
  },
  AvgDialog_22132_Content_37 = {
    Text = "Imaji yang sangat sesuai"
  },
  AvgDialog_22132_Content_38 = {
    Text = "Benar-benar retorika yang tidak sesuai dengan situasi..."
  },
  AvgDialog_22132_Content_39 = {
    Text = "Menghindari pencarian para monster, kalian tiba di lantai atas."
  },
  AvgDialog_22132_Content_4 = {
    Text = "Apakah semua orang sudah berhasil diselamatkan?"
  },
  AvgDialog_22132_Content_40 = {
    Text = "Menara jam ada di sana! Lewati lorong ini, dan kita akan sampai."
  },
  AvgDialog_22132_Content_41 = {
    Text = "Apakah hanya ada satu monster yang berjaga di sini?"
  },
  AvgDialog_22132_Content_42 = {
    Text = "Monster lainnya pasti sudah pergi mencari kita… Monster ini, sepertinya dia yang bertugas untuk mengetuk lonceng."
  },
  AvgDialog_22132_Content_43 = {
    Text = "Apakah menurutmu ada cara untuk mengelabuinya?"
  },
  AvgDialog_22132_Content_44 = {
    Text = "Mm, seharusnya bisa… Di dalam puisi disebutkan bahwa utusan Patung akan memberikan sebuah surat kepada penabuh lonceng, dan itulah sinyal bahwa tengah malam telah tiba."
  },
  AvgDialog_22132_Content_45 = {
    Text = "Bagus sekali… Horla, nanti kau berpura-pura menjadi utusan dan tipu dia untuk membunyikan lonceng. Aku akan mencari kesempatan untuk menyingkirkannya sebelum dia menyadarinya."
  },
  AvgDialog_22132_Content_46 = {
    Text = "Apa? A-aku harus... berbohong kepada orang asing..."
  },
  AvgDialog_22132_Content_47 = {
    Text = "Uh... lupakan saja, biar aku yang pergi... kau tetap sembunyi di sini. Jika lawan melakukan gerakan mencurigakan, bantu aku menahannya."
  },
  AvgDialog_22132_Content_48 = {Text = "Ya!"},
  AvgDialog_22132_Content_49 = {
    Text = "Kamu merapikan pakaianmu, lalu melangkah maju."
  },
  AvgDialog_22132_Content_5 = {
    Text = "Sebagian besar sudah berhasil diselamatkan... ada satu, masih berada di rumah kaca..."
  },
  AvgDialog_22132_Content_50 = {Text = "Siapa?"},
  AvgDialog_22132_Content_51 = {
    Text = "Ini saya, utusan Nyonya Colette."
  },
  AvgDialog_22132_Content_52 = {
    Text = "Ah... rupanya Tuan Utusan..."
  },
  AvgDialog_22132_Content_53 = {
    Text = "Saya datang untuk menyampaikan pesan kepadamu. Tengah malam akan segera tiba."
  },
  AvgDialog_22132_Content_54 = {
    Text = "Kamu menyerahkan surat yang ditulis Collette untuk Herbert kepadanya. Dia menerimanya dengan hormat."
  },
  AvgDialog_22132_Content_55 = {
    Text = "Tetapi... Tuan Utusan, melihat fenomena langit saat ini, waktu belum mencapai tengah malam..."
  },
  AvgDialog_22132_Content_56 = {
    Text = "Fenomena langit hari ini mengalami penyimpangan"
  },
  AvgDialog_22132_Content_57 = {
    Text = "Berani kamu mempertanyakan keputusan Nyonya Colette?"
  },
  AvgDialog_22132_Content_58 = {
    Text = "Mengerti… mengerti! Saya akan segera melaksanakannya!"
  },
  AvgDialog_22132_Content_59 = {
    Text = "Pengring lonceng menekan tombol. Roda-roda gigi yang presisi mulai berputar, palu jatuh, dan memukul badan lonceng raksasa."
  },
  AvgDialog_22132_Content_6 = {
    Text = "Benar-benar kasihan… dua anak itu, kehidupan mereka baru saja mulai membaik."
  },
  AvgDialog_22132_Content_60 = {
    Text = "Dang——Dang——Dang——"
  },
  AvgDialog_22132_Content_61 = {
    Text = "Palu besi jatuh berulang kali, dua belas kali suara lonceng tengah malam bergema di Cité."
  },
  AvgDialog_22132_Content_62 = {
    Text = "Tuan Utusan, lonceng tengah malam telah berbunyi."
  },
  AvgDialog_22132_Content_63 = {
    Text = "Bagus… Selanjutnya, kita bisa pergi menghadiri perayaan Nyonya Collette."
  },
  AvgDialog_22132_Content_64 = {
    Text = "Ah, Nyonya Collette yang hebat, merupakan kehormatan bagi saya untuk membunyikan lonceng perayaan untuk Anda. Melihat tulisan tangan Anda sendiri adalah sebuah..."
  },
  AvgDialog_22132_Content_65 = {
    Text = "Eh…… \"Tuan Herbert, dengan hormat — Colette\" ……"
  },
  AvgDialog_22132_Content_66 = {
    Text = "Ini bukan perintah untuk membunyikan lonceng... kamu..."
  },
  AvgDialog_22132_Content_67 = {
    Text = "Sebelum dia menyelesaikan ucapannya, beberapa jejak tulisan melayang masuk ke dalam otaknya, dan kelopak matanya pun terkulai."
  },
  AvgDialog_22132_Content_68 = {
    Text = "Setelah berputar dua kali di udara, tubuh yang berat jatuh ke tanah dengan suara \"bum\"."
  },
  AvgDialog_22132_Content_69 = {
    Text = "Horla muncul dari balik dinding dan melambaikan tangan ke arahmu."
  },
  AvgDialog_22132_Content_7 = {
    Text = "Colette, Colette... jangan terlalu bersedih."
  },
  AvgDialog_22132_Content_70 = {
    Text = "Sepertinya dia harus melewatkan perayaan ini. Mari kita pergi."
  },
  AvgDialog_22132_Content_71 = {
    Text = "Dang——Dang——Dang——"
  },
  AvgDialog_22132_Content_72 = {
    Text = "Dua belas kali suara lonceng yang jernih dan menggema, mengumumkan kedatangan tengah malam."
  },
  AvgDialog_22132_Content_73 = {
    Text = "Orang-orang keluar dari pintu rumah, berkumpul di jalan-jalan Cité, seperti aliran sungai hitam yang perlahan mengalir menuju alun-alun di luar Taman Colette."
  },
  AvgDialog_22132_Content_74 = {
    Text = "Hari itu akhirnya tiba! Segera aku akan bertemu dengan Nyonya Colette!"
  },
  AvgDialog_22132_Content_75 = {
    Text = "Ah, Nyonya Colette, satu-satunya penyair, keyakinan seluruh Cité…"
  },
  AvgDialog_22132_Content_76 = {
    Text = "Kudengar upacara kali ini akan menjadi yang paling meriah. Jika bisa berdiri di bawah panggung dan menjabat tangannya…"
  },
  AvgDialog_22132_Content_77 = {
    Text = "Mimpi saja! Banyak orang ingin bertemu dengan Nyonya Colette. Apa yang membuatmu bisa mendahului mereka?"
  },
  AvgDialog_22132_Content_78 = {
    Text = "Hanya memikirkannya saja, kan tidak melanggar hukum…"
  },
  AvgDialog_22132_Content_79 = {
    Text = "Dengarkan aku, jangan terlalu banyak berpikir. Ikutlah denganku dan tenang saja menonton dari luar."
  },
  AvgDialog_22132_Content_8 = {
    Text = "Api menyala dalam sekejap. Mungkin karena suhu tinggi, mungkin karena puntung rokok para tuan-tuan, atau mungkin karena hal lain."
  },
  AvgDialog_22132_Content_80 = {
    Text = "Hanya dengan melihat Nyonya Colette dari kejauhan dan mendengar suaranya, aku sudah merasa cukup puas."
  },
  AvgDialog_22132_Content_81 = {
    Text = "Pintu terbuka dengan lembut. Kamu waspada dan melihat ke dalam."
  },
  AvgDialog_22132_Content_82 = {
    Text = "Masuklah. Bunyi lonceng telah berfungsi, semua orang pergi ke alun-alun."
  },
  AvgDialog_22132_Content_83 = {
    Text = "Horla, apakah ini tempatnya?"
  },
  AvgDialog_22132_Content_84 = {
    Text = "Horla tidak langsung menjawab. Dia memandang sekeliling ruangan ini, matanya berkilau dengan cahaya yang jernih."
  },
  AvgDialog_22132_Content_85 = {Text = "Horla?"},
  AvgDialog_22132_Content_86 = {
    Text = "Sama seperti yang kita lihat saat kecil, tidak ada yang berubah…"
  },
  AvgDialog_22132_Content_87 = {
    Text = "Meskipun sudah memiliki begitu banyak hal, meskipun sudah memiliki seluruh Cité… di sini selalu menjadi tempat impian Colette."
  },
  AvgDialog_22132_Content_88 = {
    Text = "Emosi Horla menyebar kembali, kamu merasakan hatimu ikut tersentuh."
  },
  AvgDialog_22132_Content_89 = {Text = "Horla…"},
  AvgDialog_22132_Content_9 = {
    Text = "Api berkobar di tengah kebun yang dipenuhi rumput kering, mengelilingi rumah kaca. Sebelum orang-orang sempat menyadari, api itu sudah padam."
  },
  AvgDialog_22132_Content_90 = {
    Text = "Ah! Maaf, Penjaga {Male=tuan,Female=nyonya}... Saya selalu sulit mengendalikan emosi saya..."
  },
  AvgDialog_22132_Content_91 = {
    Text = "Tidak masalah, ini normal."
  },
  AvgDialog_22132_Content_92 = {
    Text = "Tidak seorang pun seharusnya menanggalkan masa lalunya"
  },
  AvgDialog_22132_Content_93 = {
    Text = "Terima kasih kepada Anda... Penjaga {Male=tuan,Female=nyonya}..."
  },
  AvgDialog_22132_Content_94 = {
    Text = "Kami pernah membicarakannya, Colette berkata bahwa setelah membeli rumah ini, dia akan menempatkan semua barang berharganya di sebuah etalase khusus untuk dilihat oleh semua tamu."
  },
  AvgDialog_22132_Content_95 = {
    Text = "Perhiasan, tas tangan, pakaian berharga... dan juga, puisi yang ditandatangani dengan namanya."
  },
  AvgDialog_22132_Content_96 = {
    Text = "Di bawah pimpinan Horla, kalian tiba di depan sebuah etalase kaca dengan desain yang sangat halus."
  },
  AvgDialog_22132_Content_97 = {
    Text = "Di rak tengah etalase, puisi tebal dan megah itu tertidur dengan tenang, seperti seorang penguasa yang tidur di istananya."
  },
  AvgDialog_22132_Content_98 = {
    Text = "\"Tempat Peristirahatan Mawar\"，karya Colette..."
  },
  AvgDialog_22132_Content_99 = {
    Text = "Dulu, kumpulan puisi ini hanyalah beberapa lembar kertas yang dijepit dengan peniti… sekarang, penampilannya sudah sangat berbeda."
  },
  AvgDialog_22133_Content_1 = {
    Text = "Patung Retorika"
  },
  AvgDialog_22133_Content_10 = {
    Text = "Bantu Nyonya Colette! Tangkap penyusup itu! Cepat, cari!"
  },
  AvgDialog_22133_Content_11 = {
    Text = "Sebuah kelompok monster dengan berbagai bentuk berlari masuk ke dalam gedung, melesat melewati tempat yang tidak jauh dari kalian."
  },
  AvgDialog_22133_Content_12 = {
    Text = "Monster dari dunia puisi juga telah menyerbu ke dunia nyata..."
  },
  AvgDialog_22133_Content_13 = {
    Text = "Upacara mereka akan segera dimulai, kita harus bertindak lebih cepat."
  },
  AvgDialog_22133_Content_14 = {
    Text = "Kamu mengintip keluar, monster itu untuk sementara pergi. Kamu menarik Horla dan dengan cepat berlari menaiki tangga."
  },
  AvgDialog_22133_Content_15 = {
    Text = "Horla, kita menaiki tangga dan menemukan... Eh?"
  },
  AvgDialog_22133_Content_16 = {
    Text = "Kalian berjalan menaiki tangga, namun kalian menyadari bahwa tangga itu tidak membawa kalian ke lantai atas, melainkan terputus di tengah jalan."
  },
  AvgDialog_22133_Content_17 = {
    Text = "Ini... apa yang sedang terjadi..."
  },
  AvgDialog_22133_Content_18 = {
    Text = "Saya pernah menulis sebuah puisi, di dalamnya ada yang menyebutkan tentang tangga yang terputus di tengah jalan, seperti Hidup kita yang penuh dengan kejutan dan kesulitan."
  },
  AvgDialog_22133_Content_19 = {
    Text = "Namun, ini jelas bukan dunia dalam puisi saya, bagaimana mungkin…"
  },
  AvgDialog_22133_Content_2 = {
    Text = "Penjaga {Male=tuan,Female=nyonya}, dunia dalam puisi... menghilang?"
  },
  AvgDialog_22133_Content_20 = {
    Text = "Ah! Aku paham!"
  },
  AvgDialog_22133_Content_21 = {
    Text = "Horla tiba-tiba mengangkat kepalanya, begitu bersemangat hingga tidak bisa menahan diri untuk meloncat-loncat."
  },
  AvgDialog_22133_Content_22 = {
    Text = "Itu Colette! Tempat ini sangat penting bagi kita semua… Dia secara khusus menyisihkannya dan merenovasinya sesuai dengan deskripsi dalam puisi!"
  },
  AvgDialog_22133_Content_23 = {
    Text = "Aku sudah tahu, Penjaga! Colette bukan orang seperti itu!"
  },
  AvgDialog_22133_Content_24 = {
    Text = "Ini adalah pertama kalinya kamu melihat Horla begitu gembira. Kamu menghela napas dalam-dalam."
  },
  AvgDialog_22133_Content_25 = {
    Text = "Kamu tidak tega menghancurkan khayalannya, lalu dengan lembut menepuk pundaknya."
  },
  AvgDialog_22133_Content_26 = {
    Text = "Mungkin saja... kamu sudah terbiasa dengan tempat ini, jadi aku serahkan padamu untuk memimpin jalan, bagaimana?"
  },
  AvgDialog_22133_Content_27 = {Text = "Ya!"},
  AvgDialog_22133_Content_28 = {
    Text = "Di bawah pimpinan Horla, kalian menghindari pencarian monster dan terus berjalan ke depan."
  },
  AvgDialog_22133_Content_29 = {
    Text = "Penjaga {Male=tuan,Female=nyonya}, di depan sana adalah…"
  },
  AvgDialog_22133_Content_3 = {
    Text = "Lihatlah ke luar pintu."
  },
  AvgDialog_22133_Content_30 = {Text = "Ssst!"},
  AvgDialog_22133_Content_31 = {
    Text = "Kamu menutup mulut Horla dengan satu tangan dan menariknya ke sudut dinding."
  },
  AvgDialog_22133_Content_32 = {
    Text = "Apa yang kita lakukan di sini sebenarnya?"
  },
  AvgDialog_22133_Content_33 = {
    Text = "Bodoh! Nyonya Colette menyuruh kita berjaga di sini karena... karena..."
  },
  AvgDialog_22133_Content_34 = {
    Text = "...pada akhirnya, Nyonya Colette yang memerintahkan kami untuk berjaga di sini!"
  },
  AvgDialog_22133_Content_35 = {
    Text = "Kami sudah berjaga begitu lama, tapi tidak melihat apa pun. Apakah nanti kita akan terlambat untuk upacara perayaan?"
  },
  AvgDialog_22133_Content_36 = {
    Text = "Tidak, lonceng belum berbunyi. Sebelum lonceng berbunyi, kita tidak bisa pergi ke mana pun!"
  },
  AvgDialog_22133_Content_37 = {
    Text = "Benar-benar dinantikan, bisa menyaksikan langsung karya panggung Nyonya Colette…"
  },
  AvgDialog_22133_Content_38 = {
    Text = "Karya langsung Nyonya Colette, hanya sekali setahun. Bersiaplah, prajurit. Nanti kita harus berebut tempat dengan semua orang di Cité!"
  },
  AvgDialog_22133_Content_39 = {
    Text = "Lalu kenapa kita tidak pergi sekarang?"
  },
  AvgDialog_22133_Content_4 = {
    Text = "Horla menoleh ke luar."
  },
  AvgDialog_22133_Content_40 = {
    Text = "...karena kita harus berjaga di sini."
  },
  AvgDialog_22133_Content_41 = {
    Text = "Jadi... apa yang sebenarnya kita lakukan di sini?"
  },
  AvgDialog_22133_Content_42 = {
    Text = "Bodoh! Nyonya Colette yang menyuruh kita berjaga di sini!!!"
  },
  AvgDialog_22133_Content_43 = {
    Text = "Kedua orang ini tampaknya tidak terlalu cerdas..."
  },
  AvgDialog_22133_Content_44 = {
    Text = "Tidak ada jalan lain di sini, Horla. Bersiaplah dan bersihkan mereka."
  },
  AvgDialog_22133_Content_45 = {
    Text = "Horla mengangguk padamu. Kamu memegang kunci perak, lalu Horla mengeluarkan kertas dan pena."
  },
  AvgDialog_22133_Content_46 = {
    Text = "Aah!!——"
  },
  AvgDialog_22133_Content_47 = {
    Text = "Disertai dengan cahaya perak, beberapa jejak indah melintas di udara dan terukir ke dalam tubuh para monster. Dua monster tersebut jatuh ke dalam tidur yang dalam."
  },
  AvgDialog_22133_Content_48 = {
    Text = "Setelah mengalahkan monster, kalian bersembunyi di ruangan yang ada di belakang mereka."
  },
  AvgDialog_22133_Content_49 = {
    Text = "Sepertinya ini adalah gudang... Tempat ini seharusnya aman untuk sementara."
  },
  AvgDialog_22133_Content_5 = {
    Text = "Taman di luar pintu masih mempertahankan tampilan dunia dalam puisi, tetapi dunia di dalam ruangan sama persis dengan dunia nyata, tanpa jejak Domain sama sekali."
  },
  AvgDialog_22133_Content_50 = {
    Text = "Kita bisa beristirahat di sini sebentar, lalu menemukan Collette lagi... Horla? Ekspresimu tampaknya tidak terlalu baik?"
  },
  AvgDialog_22133_Content_51 = {Text = "Ah... ada?"},
  AvgDialog_22133_Content_52 = {
    Text = "Kamu tadi mengerutkan alis, apa sedang memikirkan sesuatu?"
  },
  AvgDialog_22133_Content_53 = {
    Text = "Oh... Penjaga {Male=tuan,Female=nyonya}, aku sedang memikirkan percakapan antara dua monster tadi..."
  },
  AvgDialog_22133_Content_54 = {
    Text = "Saat menguping sebelumnya, aku sudah merasa familiar, dan baru saja aku akhirnya menyadarinya…"
  },
  AvgDialog_22133_Content_55 = {
    Text = "Di dalam kumpulan puisi itu, saya pernah menulis sebuah puisi tentang patung Kota Puisi."
  },
  AvgDialog_22133_Content_56 = {
    Text = "Kota Puisi adalah sebuah kota yang menggunakan puisi sebagai makanan. Kota ini tidak memiliki raja, dan keyakinan mereka adalah sebuah patung."
  },
  AvgDialog_22133_Content_57 = {
    Text = "Setiap tahun pada hari perayaan, ketika lonceng di menara berbunyi, Patung akan hidup dan menulis sebuah puisi untuk penduduk kota ini."
  },
  AvgDialog_22133_Content_58 = {
    Text = "Puisinya sangat indah, mampu menopang kehidupan seluruh kota ini selama satu tahun penuh."
  },
  AvgDialog_22133_Content_59 = {
    Text = "Jadi, setiap tahun pada hari perayaan, orang-orang akan berkumpul di alun-alun tempat Patung berada, untuk mendengarkan puisi yang diciptakan langsung oleh Patung tersebut…"
  },
  AvgDialog_22133_Content_6 = {
    Text = "Ini seharusnya Cité di dunia nyata. Sepertinya kita telah melewati suatu Tautan antara kenyataan dan Domain."
  },
  AvgDialog_22133_Content_60 = {
    Text = "Aku mengerti. Colette telah mengubah citra patung itu menjadi dirinya sendiri…"
  },
  AvgDialog_22133_Content_61 = {
    Text = "Di mana menara lonceng itu?"
  },
  AvgDialog_22133_Content_62 = {
    Text = "Ketika menulis puisi, aku tidak terlalu tahu seperti apa dunia luar... Jadi, menara jam itu adalah berdasarkan menara jam di samping gedung ini."
  },
  AvgDialog_22133_Content_63 = {
    Text = "Dua gedung tersambung, bisa dilewati melalui sebuah jembatan."
  },
  AvgDialog_22133_Content_64 = {
    Text = "…Horla, bisakah kau menebak di mana Collette meletakkan puisi?"
  },
  AvgDialog_22133_Content_65 = {
    Text = "Seharusnya... bisa kan..."
  },
  AvgDialog_22133_Content_66 = {
    Text = "Di dalam gedung ini terdapat sebuah ruangan yang sangat mewah, milik sang Countess. Dia hanya sesekali menginap di sini satu atau dua kali dalam setahun, sedangkan biasanya hanya meminta pelayan wanita untuk membersihkannya secara berkala."
  },
  AvgDialog_22133_Content_67 = {
    Text = "Colette sangat menyukai ruangan itu, bahkan diam-diam membawaku masuk untuk melihatnya. Dia berkata bahwa setelah dia mendapatkan uang, dia pasti akan tinggal di ruangan itu."
  },
  AvgDialog_22133_Content_68 = {
    Text = "Saya pikir, dia dan puisi itu, seharusnya berada di sana."
  },
  AvgDialog_22133_Content_69 = {
    Text = "Jadi begitu… aku punya cara!"
  },
  AvgDialog_22133_Content_7 = {
    Text = "Di mana pun dia berada, aku harus menemukan Colette dan merebut kembali Puisi itu…"
  },
  AvgDialog_22133_Content_70 = {
    Text = "Apakah harus pergi ke kamar Colette untuk merebut Puisi? Tapi ada banyak monster di sini…"
  },
  AvgDialog_22133_Content_71 = {
    Text = "Benar, ada banyak monster di sini. Kita mungkin tidak bisa mengatasinya."
  },
  AvgDialog_22133_Content_72 = {
    Text = "Jadi, kita akan mengalihkan perhatian mereka terlebih dahulu, lalu pergi ke kamarnya untuk mengambil Puisi."
  },
  AvgDialog_22133_Content_73 = {
    Text = "Tapi mereka sekarang begitu waspada… Apa yang harus kita gunakan untuk mengalihkan perhatian mereka?"
  },
  AvgDialog_22133_Content_74 = {
    Text = "Gunakan menara lonceng."
  },
  AvgDialog_22133_Content_75 = {
    Text = "Menara jam? … Ah! Aku mengerti!"
  },
  AvgDialog_22133_Content_76 = {
    Text = "Kita pergi ke menara lonceng untuk membunyikan lonceng lebih awal, sehingga monster-monster akan berkumpul di alun-alun dan tidak ada yang akan menghalangi kita lagi!"
  },
  AvgDialog_22133_Content_77 = {
    Text = "Benar. Colette akan bersiap untuk memulai pertunjukannya, tidak ada tempat di tubuhnya untuk membawa puisi yang tebal ini, kemungkinan besar akan diletakkan di tempat yang aman di kamarnya."
  },
  AvgDialog_22133_Content_78 = {
    Text = "Memanfaatkan selisih waktu ini, mari kita pergi ke kamarnya dan hancurkan puisi itu!"
  },
  AvgDialog_22133_Content_8 = {
    Text = "Dung dung dung——"
  },
  AvgDialog_22133_Content_9 = {
    Text = "Lantai bergetar dengan hebat, kamu segera menarik Horla dan bersembunyi di balik sebuah pintu."
  },
  AvgDialog_22145_Content_1 = {
    Text = "Tolong... aku tidak layak kalian melakukan ini untukku..."
  },
  AvgDialog_22145_Content_2 = {
    Text = "Aigis, aku bisa membantu! Kita bisa menstabilkan Roh!"
  },
  AvgDialog_22145_Content_3 = {
    Text = "Untuk mendukung perkataanmu, kamu mengeluarkan Kunci perak dari balik jubahmu — di atasnya bersinar cahaya hangat, seperti embun dan sinar matahari."
  },
  AvgDialog_22145_Content_4 = {
    Text = "Kunci… Tuan Anderson pernah menyebutkan…"
  },
  AvgDialog_22145_Content_5 = {
    Text = "<LightGray:Tapi… sudah terlambat…… benar-benar terlambat……>"
  },
  AvgDialog_22145_Content_6 = {
    Text = "Dia pergi ke arah menara lonceng! Kejar dia!"
  },
  AvgDialog_22297_Content_1 = {
    Text = "Membuka mata"
  },
  AvgDialog_22297_Content_10 = {
    Text = "Pemimpin rapat?"
  },
  AvgDialog_22297_Content_100 = {
    Text = "Asap tebal mengepul dari buritan, tepat ke arah Ruang Kekuatan."
  },
  AvgDialog_22297_Content_101 = {Text = "Astaga!"},
  AvgDialog_22297_Content_102 = {
    Text = "Kamu berpegangan pada rel kapal dan melangkah ke arah asap tebal yang mengepul."
  },
  AvgDialog_22297_Content_103 = {
    Text = "Tenggorokan dipenuhi dengan bau darah dan asap mesiu. Setiap kali bernapas saat berjalan, terasa seperti ditusuk jarum."
  },
  AvgDialog_22297_Content_104 = {
    Text = "Ramona, Murphy, Celeste… harus segera bergabung dengan mereka."
  },
  AvgDialog_22297_Content_105 = {
    Text = "Belum berjalan dua langkah, getaran hebat yang hampir merobek lambung kapal terasa dari bawah kaki."
  },
  AvgDialog_22297_Content_106 = {
    Text = "Dalam ledakan besar, kobaran api menyambar ke langit dan udara yang sangat panas melemparkanmu dengan keras ke tanah."
  },
  AvgDialog_22297_Content_107 = {
    Text = "——Hal terakhir yang terlintas di mata sebelum kehilangan kesadaran adalah burung laut yang melintasi langit malam dengan bulan penuh."
  },
  AvgDialog_22297_Content_11 = {
    Text = "Bagaimana tidurmu?"
  },
  AvgDialog_22297_Content_12 = {Text = "Boneka?!"},
  AvgDialog_22297_Content_13 = {
    Text = "Jangan takut, sekarang bukan saatnya menyalahkanmu karena menginjak rumput di siang hari kerja."
  },
  AvgDialog_22297_Content_14 = {
    Text = "<Gray: Itu berarti cepat atau lambat akan dituntut…>"
  },
  AvgDialog_22297_Content_15 = {
    Text = "Ramona menghindari tatapanmu, seakan-akan tertulis \"tak bisa membantu\" di bagian belakang kepalanya."
  },
  AvgDialog_22297_Content_16 = {
    Text = "Di dalam buku harian Francis, ada beberapa informasi tentang <Yellow:\"Gereja penerang kuil\"> —— Ngomong-ngomong, kamu belum sempat mempelajari tiga mata pelajaran wajib itu, kan."
  },
  AvgDialog_22297_Content_17 = {
    Text = "Gereja Penerang Kuil, yang mempercayai \"Pelarutan adalah berkat dari Tuhan, satu-satunya penyelamatan bagi umat manusia\", menipu pasien yang menderita penyakit untuk bergabung dan terinfeksi oleh Pelarutan."
  },
  AvgDialog_22297_Content_18 = {
    Text = [[
Terima kasih atas pengulangannya, Profesor Dexter. 
Namun, saya pikir Erica tidak akan senang jika Anda ikut campur dalam pekerjaannya.]]
  },
  AvgDialog_22297_Content_19 = {
    Text = "Maafkan aku, maafkan aku. Sisa waktunya kuserahkan kepada kalian."
  },
  AvgDialog_22297_Content_2 = {
    Text = "Kenapa kamu tidur di sini?"
  },
  AvgDialog_22297_Content_20 = {
    Text = "Francis meninggalkan banyak petunjuk yang mengarah ke Gereja Penerang Kuil, di antaranya \"orang mati hidup kembali\"ini sangat menarik perhatian."
  },
  AvgDialog_22297_Content_21 = {
    Text = "Dengan munculnya Lily, kita memiliki alasan untuk mencurigai bahwa Gereja Penerang Kuil telah menguasai metode pemanggilan Bangun."
  },
  AvgDialog_22297_Content_22 = {
    Text = "Bukankah keberadaan Pembangun seharusnya menjadi rahasia di dunia ini?"
  },
  AvgDialog_22297_Content_23 = {
    Text = [[
Sepertinya kamu juga tidak memperhatikan dengan baik pelajaran tentang sejarah Bangun. 
Aku mulai penasaran bagaimana kamu bisa lulus tes awal.]]
  },
  AvgDialog_22297_Content_24 = {
    Text = "Tentu saja, tidak hanya Mythag yang menguasai teknologi Bangun Perak atau yang serupa."
  },
  AvgDialog_22297_Content_25 = {
    Text = "Kemunculan Pembangun dapat ditelusuri hingga sebelum zaman Hongji, bahkan di makam Dinasti Kesembilan Belas Gulumwah, terdapat lukisan dinding yang diduga menggambarkan pemanggilan Pembangun."
  },
  AvgDialog_22297_Content_26 = {
    Text = "Di antara semua ini, \"Golem\" yang paling mirip dengan teknologi Pembangun Mythag diwariskan dari klan Penyihir di wilayah Levant."
  },
  AvgDialog_22297_Content_27 = {
    Text = "Melenceng jauh."
  },
  AvgDialog_22297_Content_28 = {
    Text = "Berdasarkan deskripsi dalam jurnal mengenai keyakinan dan spesifikasi ritual, tampaknya <Yellow:Gereja penerang kuil> yang dihubungi oleh Francis berbeda dengan informasi yang telah kami kumpulkan."
  },
  AvgDialog_22297_Content_29 = {
    Text = "Tugas lapangan kalian berikutnya adalah memverifikasi isi dari catatan harian tersebut."
  },
  AvgDialog_22297_Content_3 = {
    Text = "Bangun, tidur di sini bisa membuatmu masuk angin."
  },
  AvgDialog_22297_Content_30 = {
    Text = "Francis mencatat perjalanannya sebelum berangkat ke kutub di dalam buku hariannya. \n Kali ini, kita akan pergi ke tempat dia naik kapal — Kota Brilport, mungkin ada petunjuk yang tertinggal di sana."
  },
  AvgDialog_22297_Content_31 = {
    Text = "Jika sudah siap, ayo berangkat. Aku akan tetap menjadi pasanganmu seperti biasa."
  },
  AvgDialog_22297_Content_32 = {
    Text = "Tas keberangkatan selalu siap."
  },
  AvgDialog_22297_Content_33 = {
    Text = "Tidak perlu tidur sebentar lagi?"
  },
  AvgDialog_22297_Content_34 = {
    Text = [[
Tidak perlu! 
Saya sudah sepenuhnya memahami persyaratan tugas, dan saya juga sudah mengingat semua detail tugas yang saya baca kemarin malam!]]
  },
  AvgDialog_22297_Content_35 = {
    Text = [[
Kalau begitu, sekarang kita berangkat. 
Jika kita berangkat hari ini, mungkin kita masih bisa kembali tepat waktu untuk pertunjukan perdana drama baru di Opera House Londinium.]]
  },
  AvgDialog_22297_Content_36 = {
    Text = "Saya akan mencari sopir. Ketemu di gerbang sekolah."
  },
  AvgDialog_22297_Content_37 = {
    Text = "Punggung Ramona segera menghilang dari pandangan, dan kamu pun bersiap kembali ke asrama untuk mengambil barang bawaan."
  },
  AvgDialog_22297_Content_38 = {
    Text = "Sang Penjaga Rahasia."
  },
  AvgDialog_22297_Content_39 = {
    Text = "Misi kali ini mungkin akan berhadapan langsung dengan Gereja Penerang Kuil."
  },
  AvgDialog_22297_Content_4 = {
    Text = "Hmm… Ramona?"
  },
  AvgDialog_22297_Content_40 = {
    Text = [[
Mengungkap rahasia tersembunyi mereka adalah tugas sekunder. Prioritas utamamu adalah memastikan dirimu tetap hidup.
Aku tidak tahu harus mencari Penjaga dari mana lagi di antara reruntuhan ini.]]
  },
  AvgDialog_22297_Content_41 = {
    Text = "Jangan terlalu keras pada anak muda."
  },
  AvgDialog_22297_Content_42 = {
    Text = [[
Namun, Boneka benar. 
Pengikut yang kalian temui sebelumnya hanyalah anggota luar, inti sebenarnya dari gereja belum muncul ke permukaan.]]
  },
  AvgDialog_22297_Content_43 = {
    Text = "Tampaknya Profesor sangat familiar dengan Gereja Penerang Kuil?"
  },
  AvgDialog_22297_Content_44 = {
    Text = "Ha, haha... hanya sebuah hubungan karma saja."
  },
  AvgDialog_22297_Content_45 = {
    Text = "Jika perlu, Mythag akan mengirim penyelidik yang lebih berpengalaman dalam pertempuran, atau bahkan meminta bantuan kepada Komite Perjanjian Mystia untuk menyelesaikan masalah ini."
  },
  AvgDialog_22297_Content_46 = {
    Text = "Harus kembali dengan selamat."
  },
  AvgDialog_22297_Content_47 = {
    Text = "Aku mengerti, kami akan kembali dengan selamat."
  },
  AvgDialog_22297_Content_49 = {
    Text = "Apa yang masih kamu lihat? Mereka sudah berangkat."
  },
  AvgDialog_22297_Content_5 = {
    Text = "Berapa lama saya sudah tidur?"
  },
  AvgDialog_22297_Content_50 = {
    Text = "Jangan khawatir, mereka semua adalah anak-anak yang tahu batas."
  },
  AvgDialog_22297_Content_51 = {
    Text = [[
Aku tidak khawatir. 
Meskipun harus melatih Penjaga baru, dana akan tetap diambil dari rekening bank keluarga Dexter.]]
  },
  AvgDialog_22297_Content_52 = {
    Text = "Lebih perhatikan dirimu sendiri. Aku baru saja mendengar bahwa putri seseorang akan pergi berkencan ke opera."
  },
  AvgDialog_22297_Content_53 = {Text = "Pemuda..."},
  AvgDialog_22297_Content_54 = {Text = "Malam itu"},
  AvgDialog_22297_Content_55 = {
    Text = "Kapal reguler ke kutub? Kalian pasti gila! Tidak ada kapal reguler di sini, juga tidak ada gereja atau organisasi keagamaan!"
  },
  AvgDialog_22297_Content_56 = {
    Text = "Jangan tanya lagi, kami hanya nelayan biasa, kami tidak tahu apa-apa!"
  },
  AvgDialog_22297_Content_57 = {
    Text = "Bu, tolong tunggu sebentar——"
  },
  AvgDialog_22297_Content_58 = {
    Text = "Kalian ini memanfaatkan status tuan kota untuk menindas penduduk desa!"
  },
  AvgDialog_22297_Content_59 = {
    Text = "Kami sama sekali tidak bermaksud demikian——Eh!"
  },
  AvgDialog_22297_Content_6 = {
    Text = "Siapa yang tahu? Kamu bahkan absen di pertemuan sebelum keberangkatan sore ini."
  },
  AvgDialog_22297_Content_60 = {
    Text = "Wanita itu membanting pintu. Jika Ramona tidak menarikmu tepat waktu, mungkin kamu akan kembali ke sekolah dengan hidung yang bengkok."
  },
  AvgDialog_22297_Content_61 = {
    Text = "Brillport... Kota kecil ini sangat aneh."
  },
  AvgDialog_22297_Content_62 = {
    Text = "Ini adalah pintu ketiga yang kami ketuk, namun tidak ada seorang pun yang mau berbagi informasi tentang kota kecil ini dengan kami."
  },
  AvgDialog_22297_Content_63 = {
    Text = "Kami bahkan hanya bertanya arah. Sepertinya mereka sedang berusaha menutupi sesuatu secara kolektif, ini sangat tidak biasa."
  },
  AvgDialog_22297_Content_64 = {
    Text = "Pergi ke dermaga dan lihatlah, mungkin ada petunjuk di sana."
  },
  AvgDialog_22297_Content_66 = {Text = "Ada apa?"},
  AvgDialog_22297_Content_67 = {
    Text = "Mungkin itu hanya fatamorgana, sepertinya ada suara orang berbicara di dalam angin."
  },
  AvgDialog_22297_Content_69 = {
    Text = [[
Hei, kebetulan, ada dua orang pendatang yang ceroboh. 
Menghalangi mereka? Supaya tidak perlu mencari orang lain.]]
  },
  AvgDialog_22297_Content_7 = {Text = "Rapat?"},
  AvgDialog_22297_Content_70 = {
    Text = "Menggiring mereka ke arah kapal."
  },
  AvgDialog_22297_Content_71 = {
    Text = "Hmph, orang yang berniat jahat."
  },
  AvgDialog_22297_Content_72 = {
    Text = "Pergilah, Caecus, inilah kesempatanmu untuk menunjukkan kemampuan."
  },
  AvgDialog_22297_Content_73 = {
    Text = "Baik, Tuan Goliath."
  },
  AvgDialog_22297_Content_74 = {
    Text = "Hitung Mundur: Tiga Jam"
  },
  AvgDialog_22297_Content_75 = {
    Text = "Tunggu! Jangan tutup pintunya dulu!"
  },
  AvgDialog_22297_Content_76 = {
    Text = [[
Gadis itu mengabaikan ucapamu dan dengan cepat menarik papan pintu ke bawah. 
 Tentakel monster yang menjulur masuk ke dalam pintu terjepit hingga putus, berdenyut beberapa kali sebelum akhirnya benar-benar diam.]]
  },
  AvgDialog_22297_Content_77 = {
    Text = "Teman saya masih di luar!"
  },
  AvgDialog_22297_Content_78 = {
    Text = "Ha?! Apakah ada orang lain di kapal?"
  },
  AvgDialog_22297_Content_79 = {
    Text = [[
Dikelilingi begitu banyak monster, bahkan dewa pun tak bisa melarikan diri. 
 Jangan terus memikirkan orang itu, aku akan membawamu menemui kapten untuk mencari tahu bagaimana cara mengirim kamu turun dari kapal.]]
  },
  AvgDialog_22297_Content_8 = {
    Text = "Ini tentang Francis——"
  },
  AvgDialog_22297_Content_80 = {
    Text = "Dia sangat kuat, dia pasti tidak akan apa-apa."
  },
  AvgDialog_22297_Content_81 = {
    Text = "Ya, ya, ya, dia akan selamat. Setelah aku bertemu dengan kapten, aku akan membawamu menemuinya."
  },
  AvgDialog_22297_Content_82 = {
    Text = "Namun, berapa banyak yang tersisa… aku tidak bisa menjamin."
  },
  AvgDialog_22297_Content_83 = {
    Text = "Siapa kamu?"
  },
  AvgDialog_22297_Content_84 = {
    Text = "Ini baru ucapan yang seharusnya aku katakan, kau penyelundup! Kapten pernah berkata, naik ke kapal tanpa izin dianggap sebagai penyelundupan."
  },
  AvgDialog_22297_Content_85 = {
    Text = "Nona, kamu salah paham. Kami tidak bermaksud untuk menyelundup, hanya saja kami bertemu dengan monster dan terpaksa naik ke kapal..."
  },
  AvgDialog_22297_Content_86 = {
    Text = "Simpan saja kata-kata itu untuk kapten, aku tidak peduli."
  },
  AvgDialog_22297_Content_87 = {
    Text = "Sial sial sial! Kau ini sudah membuat masalah besar! Seluruh rencana nona kecil ini kacau berantakan! Harus memikirkan sesuatu…"
  },
  AvgDialog_22297_Content_88 = {
    Text = "Ngomong-ngomong, sebaiknya kau ingat baik-baik nama saya ——"
  },
  AvgDialog_22297_Content_89 = {
    Text = "Hitung mundur @2 menit"
  },
  AvgDialog_22297_Content_9 = {
    Text = "Lupakan saja, biarkan pembawa acara rapat menjelaskan langsung kepadamu."
  },
  AvgDialog_22297_Content_90 = {
    Text = "Kami sekarang menaiki kapal."
  },
  AvgDialog_22297_Content_91 = {
    Text = "Apakah sudah cukup melihat?"
  },
  AvgDialog_22297_Content_92 = {
    Text = "Benar. Jika ritual dibiarkan berlanjut, entah monster apa yang akan menetas dari sesuatu di dalam tubuh Murphy."
  },
  AvgDialog_22297_Content_93 = {
    Text = "Palsu… matilah kau!"
  },
  AvgDialog_22297_Content_94 = {
    Text = "%player%, berikan tanganmu padaku!"
  },
  AvgDialog_22297_Content_96 = {
    Text = "Sesaat sebelum jubah itu dibasahi oleh air laut, angin sepoi-sepoi yang terasa begitu familiar menerpa permukaan laut."
  },
  AvgDialog_22297_Content_97 = {
    Text = "Aku ingat sekarang... aku tidak berhasil menangkap tangannya, lalu jatuh ke laut... Tidak, tapi... ini adalah dek kapal Sonaniel."
  },
  AvgDialog_22297_Content_98 = {
    Text = "Warna hangat yang penuh dengan mimpi dan kelembutan digantikan oleh cahaya bulan yang dingin dan pucat. Tirai yang menyelimuti kapal perlahan retak, menghilang, dan jatuh ke dalam Aequor."
  },
  AvgDialog_22297_Content_99 = {
    Text = "Tirai... menghilang?!"
  },
  AvgDialog_22403_Content_1 = {
    Text = "Sudah giliran Auretta belum sudah giliran Auretta belum?"
  },
  AvgDialog_22403_Content_2 = {
    Text = "Sst, tidak lihat mereka sedang berakting dengan tangan dan kaki terikat? Dengan tubuhmu ini bagaimana mau menyelamatkan mereka?"
  },
  AvgDialog_22403_Content_3 = {
    Text = "Brown, sudah waktunya kita tampil!"
  },
  AvgDialog_22403_Content_4 = {Text = "Cit cit!"},
  AvgDialog_22403_Content_5 = {
    Text = "Jenkin dan hewan-hewan sahabatnya menyelinap ke dalam bayangan lokasi syuting, meninggalkan Auretta yang cemberut berputar-putar di belakang kamera."
  },
  AvgDialog_22403_Content_6 = {
    Text = [[
Jangan terburu-buru, kau pasti akan dapat giliran tampil.
Nanti, biar Master Kassia membuatkan "adegan besar" untukmu.]]
  },
  AvgDialog_22403_Content_7 = {
    Text = "Benarkah?! Terima kasih Master Kassia!"
  },
  AvgDialog_22403_Content_8 = {
    Text = "Master? Hmhm~ Nah begitu baru benar."
  },
  AvgDialog_22406_Content_1 = {
    Text = "Berhenti! Kalian mau membawa properti kesayanganku ke mana!"
  },
  AvgDialog_22406_Content_10 = {
    Text = "Iiih!? Air liur tikus!!"
  },
  AvgDialog_22406_Content_11 = {Text = "Cit!"},
  AvgDialog_22406_Content_12 = {
    Text = "Menjilat Houdini dengan penuh tenaga!"
  },
  AvgDialog_22406_Content_13 = {
    Text = "Pertarungan besar akan segera pecah. Gadis yang ditawan itu menatap rekan yang berdiri di depannya dalam pose melindunginya, dengan ekspresi yang sulit dibaca."
  },
  AvgDialog_22406_Content_14 = {
    Text = "—— Dia menggertakkan giginya, dan dari balik punggungnya, dia membentuk sebuah bisul hitam pekat!"
  },
  AvgDialog_22406_Content_2 = {
    Text = "Bayangan turun, cakar tajam menjulur dari dunia lain, iblis sulap itu menggertak dengan gigi dan cakar, menghalangi jalan para petualang pemberani."
  },
  AvgDialog_22406_Content_3 = {
    Text = "Atas nama ksatria……"
  },
  AvgDialog_22406_Content_4 = {
    Text = "Uhuk uhuk!!"
  },
  AvgDialog_22406_Content_5 = {
    Text = [[
Uhuk, uhuk. Demi kehormatan detektif Londinium, aku bersumpah akan melindungi semua orang!
Jangan harap kau bisa selangkah lebih dekat lagi!]]
  },
  AvgDialog_22406_Content_6 = {
    Text = "Oh— Detektif G, sebagai orang yang pernah kalah di tanganku, apa kau belum cukup merasakan pahitnya kekalahan?"
  },
  AvgDialog_22406_Content_7 = {
    Text = "Kalau begitu jangan salahkan aku kalau aku tidak segan lagi!"
  },
  AvgDialog_22406_Content_8 = {
    Text = "Ranger, sekarang!"
  },
  AvgDialog_22406_Content_9 = {
    Text = "Ranger berbulu lebat itu melesat cepat menembus kegelapan, memanjat ke paha Houdini dengan kecepatan yang hampir tak terlihat oleh mata telanjang, lalu menggigit dengan keras……"
  },
  AvgDialog_22708_Content_1 = {
    Text = "Menang…… kita menang!"
  },
  AvgDialog_22708_Content_10 = {
    Text = "Sang asisten mengangkat Ranger Malam tinggi-tinggi, untuk sementara melindungi bulu indah sang Ranger."
  },
  AvgDialog_22708_Content_11 = {
    Text = "Hei!! Mayat jangan bicara lagi! Penjaga Rahasia! Rotan! Cepat pikirkan sesuatu!!"
  },
  AvgDialog_22708_Content_12 = {
    Text = "Rotan menggelengkan kepalanya dengan ekspresi antara tertawa dan menangis, bayangan makhluk paus muncul dari belakangnya. Namun tepat saat dia hendak menarik semua orang keluar dari air, sebuah sosok ringan terjun masuk ke dalam air."
  },
  AvgDialog_22708_Content_13 = {
    Text = "Air! Ini air~ Ini lautan yang paling disukai Aurita!"
  },
  AvgDialog_22708_Content_14 = {
    Text = "Ucapkanlah permohonanmu padaku, wahai orang-orang yang membutuhkan bantuan! Lautan akan menjawab semua harapan kalian!"
  },
  AvgDialog_22708_Content_15 = {
    Text = "Inspektur G dan duo Midnight Ranger saling berpandangan, lalu serempak mendorong gadis berpakaian putih yang sudah lama terdiam ke hadapan peri laut."
  },
  AvgDialog_22708_Content_16 = {Text = "……?!"},
  AvgDialog_22708_Content_17 = {
    Text = "To, tolong bawa kami pergi dari sini."
  },
  AvgDialog_22708_Content_18 = {
    Text = "Cassia yang setengah badannya sudah terendam di air menyunggingkan sudut bibirnya, menampilkan senyum puas."
  },
  AvgDialog_22708_Content_19 = {
    Text = "Ilusi sihir berubah bentuk dan cahaya di bawah lambaian tangannya."
  },
  AvgDialog_22708_Content_2 = {
    Text = "Pesulap jahat itu dikalahkan berkat kerja sama semua orang. Dia ambruk ke tanah, dengan lemah mengulurkan tangannya ke arah sebuah tombol."
  },
  AvgDialog_22708_Content_20 = {
    Text = "Dalam sekejap, semua orang terendam di dalam air"
  },
  AvgDialog_22708_Content_21 = {
    Text = "Tak ada yang selamat."
  },
  AvgDialog_22708_Content_22 = {
    Text = "Kau serius!?"
  },
  AvgDialog_22708_Content_23 = {
    Text = "Peri telah kembali ke lautan yang bebas, dan semua orang berhasil keluar dari bengkel sihir Houdini, bukankah itu sudah memenuhi permohonan sang gadis?"
  },
  AvgDialog_22708_Content_24 = {
    Text = "Perkataan Anda memang ada benarnya, ta, tapi bagaimana cerita ini bisa mencapai akhir yang diinginkan Lily?"
  },
  AvgDialog_22708_Content_25 = {
    Text = "\"Gadis itu pun hidup bahagia bersama ibunya selamanya\""
  },
  AvgDialog_22708_Content_26 = {
    Text = [[
Tch, ini terakhir kalinya aku membantumu mengurus anak-anak.
Kalau ada urusan merepotkan seperti ini lagi, jangan cari aku.]]
  },
  AvgDialog_22708_Content_27 = {
    Text = "Lily, Pak Polisi, cepat lihat apa itu di dalam air sana?!"
  },
  AvgDialog_22708_Content_29 = {
    Text = "Punggung raksasa muncul dari dalam air, itu adalah makhluk besar yang telah bersemayam di kedalaman laut Kadath sejak planet ini terlahir. Dia menjawab panggilan kehidupan, menembus tirai waktu untuk datang!"
  },
  AvgDialog_22708_Content_3 = {
    Text = "Melihat situasi itu, Lotan melemparkan speaker ke arahmu. Dia melangkah besar menuju Casiah dan berbisik di telinganya."
  },
  AvgDialog_22708_Content_30 = {
    Text = "Ro……tan?"
  },
  AvgDialog_22708_Content_31 = {
    Text = "Mau ikut tidak? Kalau tidak, kalian akan menyambut akhir cerita di dalam air ini."
  },
  AvgDialog_22708_Content_32 = {
    Text = "Wah! Ikan besar!"
  },
  AvgDialog_22708_Content_33 = {
    Text = "Jangan terburu-buru, satu per satu ya. Punggung Nona Rotan sangat luas."
  },
  AvgDialog_22708_Content_34 = {
    Text = "Bisakah kau, peri laut setengah-setengah, berhenti berdesakan di depan!? Aku dan Bu... aku dan Ranger Malam Abadilah yang jelas-jelas paling berjasa, kan?"
  },
  AvgDialog_22708_Content_35 = {Text = "Anu..."},
  AvgDialog_22708_Content_36 = {
    Text = "Ikan besar adalah teman Oreta! Jadi Oreta harus duduk paling depan!"
  },
  AvgDialog_22708_Content_37 = {Text = "Anu...!"},
  AvgDialog_22708_Content_38 = {
    Text = "Li, Lily... aku..."
  },
  AvgDialog_22708_Content_39 = {
    Text = "Aku ingin duduk paling depan, boleh?"
  },
  AvgDialog_22708_Content_4 = {
    Text = "Kau punya ide nakal apa lagi? Jangan bikin semuanya jadi tak terkendali ya."
  },
  AvgDialog_22708_Content_40 = {
    Text = "Karena kau lebih kecil dariku... hati-hati! Di punggung si besar ini tidak ada kursinya."
  },
  AvgDialog_22708_Content_41 = {
    Text = "Oreta mau bersama teman-teman!"
  },
  AvgDialog_22708_Content_42 = {
    Text = "Hei! Kenapa badanmu licin sekali!? Kalau kau bisa berenang, tidak usah naik ke sini!"
  },
  AvgDialog_22708_Content_43 = {
    Text = "Sang makhluk raksasa mengeluarkan raungan dari saluran napasnya. Dia melompat keluar dari air membawa tawa dan harapan."
  },
  AvgDialog_22708_Content_44 = {
    Text = "Cahaya fajar menembus awan dan kabut air, menyelimuti permukaan laut, sang makhluk raksasa, dan para petualang dengan kerudung merah muda kemerahan."
  },
  AvgDialog_22708_Content_45 = {
    Text = "Ti, tinggi sekali——!"
  },
  AvgDialog_22708_Content_47 = {
    Text = "Inspektur G, peri laut, dan asisten Ranger Malam Abadi bersama-sama menangkap gadis itu, mencegahnya tergelincir dari punggung sang makhluk raksasa."
  },
  AvgDialog_22708_Content_48 = {
    Text = "Mereka tertawa dan bercanda dengan riang, saling mengusapkan air ke pakaian rekan mereka."
  },
  AvgDialog_22708_Content_49 = {
    Text = "Pada saat itu, gadis yang berani tiba-tiba menatap lurus dengan senyuman yang sangat cerah dan lembut di wajahnya."
  },
  AvgDialog_22708_Content_5 = {
    Text = "Aiya, cuma ujian kecil saja kok——"
  },
  AvgDialog_22708_Content_50 = {
    Text = "Lili yang melewatkan masa berbunga,"
  },
  AvgDialog_22708_Content_51 = {
    Text = "Akhirnya menyambut saat untuk mekar."
  },
  AvgDialog_22708_Content_6 = {
    Text = "Seiring senyum di wajah Kaschey yang perlahan melebar, suara arus bawah yang bergejolak terdengar di telinga semua orang."
  },
  AvgDialog_22708_Content_7 = {
    Text = "Mengalirlah masuk! Banjir! Selesaikan penutupan pertunjukan Maestro Houdini—— pelarian tangki air yang terakhir!"
  },
  AvgDialog_22708_Content_8 = {
    Text = "Permukaan air naik dengan cepat, segera merendam punggung kaki anak-anak, lalu betis mereka…… dan akhirnya, air naik hingga paha, membuat mereka sulit melangkah."
  },
  AvgDialog_22708_Content_9 = {
    Text = "Kaschey!!! Apa yang kau lakukan!? Kau benar-benar mau menenggelamkan kami?!"
  },
  AvgDialog_23346_Content_1 = {
    Text = "Gumpalan hitam itu surut bagai air pasang, dan ketenangan kembali menyelimuti balkon."
  },
  AvgDialog_23346_Content_10 = {
    Text = "Kelopak mawar merah darah berterbangan jatuh, aroma bunga busuk yang pekat menyelimuti kotak penonton yang gelap gulita."
  },
  AvgDialog_23346_Content_11 = {
    Text = "Bayangan bertopeng muncul tanpa suara di belakang Nyonya Soreil."
  },
  AvgDialog_23346_Content_12 = {
    Text = "Permisi, Tuan-tuan dan Nyonya-nyonya. Selanjutnya silakan nikmati——"
  },
  AvgDialog_23346_Content_15 = {
    Text = "Setangkai mawar yang merekah indah menembus dada Soreil, tetesan embun di kelopaknya berkilau biru pucat dalam kegelapan malam."
  },
  AvgDialog_23346_Content_16 = {
    Text = "I-ini……ini apa……"
  },
  AvgDialog_23346_Content_17 = {
    Text = "Bayangan itu hanya muncul sesaat lalu menghilang, meninggalkan Soreil yang menatap bingung darah yang mengalir dari dadanya."
  },
  AvgDialog_23346_Content_18 = {
    Text = "Aaaaah!! Nyonya, dada Anda……"
  },
  AvgDialog_23346_Content_19 = {
    Text = "Darah? Jorok sekali……Garen, cepat bersihkan untukku……"
  },
  AvgDialog_23346_Content_2 = {
    Text = "Kau maju dan langsung menggenggam tangan Soreil."
  },
  AvgDialog_23346_Content_20 = {
    Text = "Jangan mundur, Nyonya Soreil! Anda bisa jatuh!"
  },
  AvgDialog_23346_Content_21 = {
    Text = "Nyonya Soreil!!"
  },
  AvgDialog_23346_Content_23 = {
    Text = "Aaaaah, ada orang jatuh dari gedung!!"
  },
  AvgDialog_23346_Content_24 = {
    Text = "<Shake:I-itu sepertinya Nyonya Soreil……>"
  },
  AvgDialog_23346_Content_25 = {
    Text = "Anggur keemasan tumpah dari gelas, menari di udara bersama kelopak mawar yang merekah indah."
  },
  AvgDialog_23346_Content_26 = {
    Text = "To……tolong aku……"
  },
  AvgDialog_23346_Content_27 = {
    Text = "Musik mewah nan megah masih menggema di seluruh gedung opera."
  },
  AvgDialog_23346_Content_28 = {
    Text = "Matanya penuh ketakutan dan kebingungan, naluri bertahan hidup mendorongnya mengulurkan tangan kepadamu, namun nyaris meleset di saat ujung jari hampir bersentuhan."
  },
  AvgDialog_23346_Content_3 = {
    Text = "Di sini tidak aman, Nyonya Soreil. Silakan ikut saya pergi."
  },
  AvgDialog_23346_Content_30 = {
    Text = "Wanita cantik nan memesona ini, akhirnya jatuh bersama gaun mewah, anggur indah, bunga segar, dan tepuk tangan yang paling dicintainya."
  },
  AvgDialog_23346_Content_31 = {
    Text = "<Yellow:Catatan Investigasi Mystic Realm Buatan Pertama>\n\n■Nomor Mystic Realm: M-B04-001\n■Waktu Pengaturan: Tahun Diluvian 315, Juni @1, 8:00-9:00pm (hari kematian Soreil).\n■Lokasi Pengaturan: Teater Covent"
  },
  AvgDialog_23346_Content_32 = {
    Text = "■Pemilik Mystic Realm: Soreil·@2\n■Penyusup Mystic Realm: %player%, Ramona\n\n■Tujuan Penyusupan: <Yellow:Menyelidiki kasus jatuhnya Soreil dari gedung serta @3>"
  },
  AvgDialog_23346_Content_33 = {
    Text = "■<Yellow:Hasil Investigasi>\n\nPelaku sementara diidentifikasi sebagai <Red:sosok bayangan hitam bertopeng>.\nSoleil tewas jatuh dari gedung, Penjaga Rahasia menarik diri dari Mystic Realm buatan."
  },
  AvgDialog_23346_Content_34 = {
    Text = [[
Ruang Istirahat Misager
Setelah Mystic Realm buatan pertama berakhir]]
  },
  AvgDialog_23346_Content_35 = {
    Text = "Sudah bangun?"
  },
  AvgDialog_23346_Content_36 = {
    Text = "<Shake:Ngh… kepalaku… sakit sekali…>"
  },
  AvgDialog_23346_Content_37 = {
    Text = "Denyut jantung dan tekanan darah normal, fluktuasi energi spiritual sedikit tinggi, tapi masih dalam batas yang terkendali."
  },
  AvgDialog_23346_Content_38 = {
    Text = "Bagus. Sepertinya setelah mengalami <Blue:Mystic Realm buatan Ramona> sebelumnya, kamu sudah mulai beradaptasi."
  },
  AvgDialog_23346_Content_39 = {
    Text = "Juga berkat perbaikan berkelanjutan yang kulakukan pada Mystic Realm, sekarang kita bahkan bisa mengatur waktu dan lokasi awal serta akhir Mystic Realm."
  },
  AvgDialog_23346_Content_4 = {Text = "!!"},
  AvgDialog_23346_Content_40 = {
    Text = "Tentu saja, dana penelitian yang diajukan Nona Coherit untuk kita juga berperan… sekitar 1%."
  },
  AvgDialog_23346_Content_41 = {
    Text = "Benarkah cuma 1%…"
  },
  AvgDialog_23346_Content_42 = {
    Text = "Bagaimana dengan Ramona? Kami masuk bersama…"
  },
  AvgDialog_23346_Content_43 = {
    Text = "Dia beristirahat di ruangan sebelah. Tenang saja, kondisinya sama sepertimu, tidak ada masalah serius."
  },
  AvgDialog_23346_Content_44 = {
    Text = "Apakah pelakunya tertangkap, di dalam Mystic Realm Nyonya Soleil?"
  },
  AvgDialog_23346_Content_45 = {
    Text = "Kau menggelengkan kepala."
  },
  AvgDialog_23346_Content_46 = {
    Text = "Hanya sempat mencium bau dari tubuh pelaku, seperti… <Red:bau mawar yang membusuk.>"
  },
  AvgDialog_23346_Content_47 = {
    Text = "Semua yang ada di depan mata terasa tidak nyata, pikiran terus berganti dan melompat-lompat."
  },
  AvgDialog_23346_Content_48 = {
    Text = "Dari kehancuran gedung opera hingga pembunuhan di sudut gang, dari kerumunan yang bersorak dan menjerit hingga pelayan yang menyimpan niat tersembunyi…"
  },
  AvgDialog_23346_Content_49 = {
    Text = "Hingga akhirnya pikiran itu berhenti pada tiga minggu lalu, awal mula cerita ini—"
  },
  AvgDialog_23346_Content_5 = {
    Text = "Berani-beraninya menyentuh tangan Nyonya, dan menggenggamnya begitu erat……"
  },
  AvgDialog_23346_Content_6 = {
    Text = "Sambil berkata demikian, sang pelayan tiba-tiba mendekatkan bibirnya ke telingamu."
  },
  AvgDialog_23346_Content_7 = {
    Text = "<SmallShake:Hei, bukankah kita sepakat hanya datang untuk menonton pertunjukan, kau menipuku!>"
  },
  AvgDialog_23346_Content_8 = {
    Text = "……Nanti kujelaskan lagi."
  },
  AvgDialog_23347_Content_1 = {
    Text = "Kau terdorong keras oleh kekuatan dahsyat."
  },
  AvgDialog_23347_Content_2 = {
    Text = "Dunia berubah menjadi kelopak bunga yang perlahan menghilang, dan kau jatuh ke dalam lautan bunga yang tak berujung."
  },
  AvgDialog_23347_Content_3 = {
    Text = "AAAAAH——!!!"
  },
  AvgDialog_23347_Content_4 = {
    Text = "<Yellow:Catatan Investigasi Ruang Tersembunyi Buatan Kedua Ⅱ>\n\n■Nomor Ruang Tersembunyi: M-B04-002\n■Waktu Pengaturan: 11 Juni tahun 315 Diluvian, 8:00-9:00pm (hari kematian Soreil).\n■Lokasi Pengaturan: Teater Covent"
  },
  AvgDialog_23347_Content_5 = {
    Text = "■Pemilik Ruang Tersembunyi: Soreil·@2\n■Penyusup Ruang Tersembunyi: %player%, Ramona\n\n■Tujuan Penyusupan: <Yellow:Berdasarkan hasil penyusupan ruang tersembunyi pertama, mencari sumber fluktuasi Inti Perak di lantai satu.>"
  },
  AvgDialog_23347_Content_6 = {
    Text = "■<Yellow:Hasil Investigasi>\n\nMunculnya @2 tak dikenal yang menginterupsi investigasi, Penjaga Rahasia kehilangan sebagian besar ingatan terkait.\n<Red:Penjaga Rahasia dipaksa keluar dari ruang tersembunyi, nyawanya dalam bahaya.>"
  },
  AvgDialog_23348_Content_1 = {
    Text = "Mohon berhenti sebentar, Tuan-tuan."
  },
  AvgDialog_23348_Content_2 = {
    Text = "Kami ada urusan mendesak dengan tuan tua itu, bisakah Anda sampaikan?"
  },
  AvgDialog_23348_Content_3 = {
    Text = "Maaf, tuan kami menderita penyakit menular yang parah, tidak bisa menerima tamu dari luar."
  },
  AvgDialog_23348_Content_4 = {
    Text = "Kami bisa berbicara dengannya dari luar kereta, tidak akan mendekat selangkah pun."
  },
  AvgDialog_23348_Content_5 = {
    Text = "Pria-pria bertubuh kekar bersenjata lengkap itu mengabaikan usulan kalian. Ini adalah kawasan tersibuk di Distrik Barat, jika memulai pertarungan, pasti akan menarik perhatian semua orang."
  },
  AvgDialog_23348_Content_6 = {
    Text = "Kamu tidak ingin menimbulkan masalah yang tidak perlu."
  },
  AvgDialog_23348_Content_7 = {
    Text = "Kalau begitu diam-diam ikuti dari belakang, lihat sebenarnya mereka ini siapa."
  },
  AvgDialog_23349_Content_1 = {
    Text = "Kalian mengikuti kereta itu berbelok ke sana kemari, tanpa sadar sudah jauh meninggalkan kota, tiba di pinggiran yang tandus."
  },
  AvgDialog_23349_Content_10 = {
    Text = "Masuk dulu dan lihat-lihat."
  },
  AvgDialog_23349_Content_2 = {
    Text = "Kabut tebal menyelimuti segalanya, di depan hanya tersisa siluet hitam kereta yang samar-samar."
  },
  AvgDialog_23349_Content_3 = {
    Text = "Siluet itu perlahan memudar, hingga akhirnya tak bisa ditemukan lagi."
  },
  AvgDialog_23349_Content_4 = {
    Text = "Tempat macam apa ini... Akhir-akhir ini Londinium dipenuhi kabut tebal di mana-mana, sangat menghambat efisiensi kerja polisi dan penyelidik."
  },
  AvgDialog_23349_Content_5 = {
    Text = "Menembus kabut tebal, sebuah mansion tua yang diselimuti awan suram tampak samar di kejauhan."
  },
  AvgDialog_23349_Content_6 = {
    Text = "Permukaan kayu pinus mansion itu retak dengan celah-celah, aura suram mengalir keluar tanpa suara dari dalamnya."
  },
  AvgDialog_23349_Content_7 = {
    Text = "Kabut tebal, mansion terbengkalai, sosialita yang mati secara misterius, pria tua yang penuh misteri... Bagus, semua elemen novel sudah lengkap."
  },
  AvgDialog_23349_Content_8 = {
    Text = "Menurutmu, mungkinkah tuan tua itu ada di dalam sana?"
  },
  AvgDialog_23349_Content_9 = {
    Text = "Daerah sekitar sini tandus sejauh mata memandang, sepertinya kita tidak punya pilihan lain."
  },
  AvgDialog_23351_Content_1 = {
    Text = "Kau menyibak tirai berat itu dengan satu tarikan."
  },
  AvgDialog_23351_Content_10 = {
    Text = "…Anda sudah bangun?"
  },
  AvgDialog_23351_Content_11 = {Text = "?"},
  AvgDialog_23351_Content_12 = {
    Text = "Kau segera menoleh ke belakang, namun tak ada siapa pun di sana."
  },
  AvgDialog_23351_Content_13 = {
    Text = "Nyonya Soreil?"
  },
  AvgDialog_23351_Content_14 = {
    Text = "Soreil segera memulihkan ketenangannya dan memaksakan senyum kepadamu."
  },
  AvgDialog_23351_Content_15 = {
    Text = "Kita baru saling kenal belum sampai setengah jam, dan kau sudah mengucapkan maaf tiga kali kepadaku."
  },
  AvgDialog_23351_Content_16 = {
    Text = "Kalau benar-benar ingin minta maaf, lebih tulus kalau pakai ini."
  },
  AvgDialog_23351_Content_17 = {
    Text = "Soreil menggoyang-goyangkan cairan emas di dalam gelasnya."
  },
  AvgDialog_23351_Content_18 = {
    Text = "Orang yang kutunggu tidak datang, jadi temani aku bermain sebuah permainan, ya.\nAku akan mengajukan tiga pertanyaan kepadamu, kalau kau tidak bisa menjawab…"
  },
  AvgDialog_23351_Content_19 = {
    Text = "Soreil meletakkan gelasnya perlahan di atas meja, lalu menunjuk dengan santai ke arah sampanye di troli hidangan di sampingnya."
  },
  AvgDialog_23351_Content_2 = {
    Text = "Akhirnya kau kembali, ksatriaku."
  },
  AvgDialog_23351_Content_20 = {
    Text = "Maka minumlah satu gelas."
  },
  AvgDialog_23351_Content_3 = {
    Text = "Soreil duduk dengan anggun di sudut ruangan sambil tersenyum, tampak tetap berseri-seri seperti biasa."
  },
  AvgDialog_23351_Content_4 = {
    Text = "Syukurlah, kau baik-baik saja."
  },
  AvgDialog_23351_Content_5 = {
    Text = "Bukankah kau bilang akan datang melindungiku? Aku sudah menunggumu lama sekali, lho."
  },
  AvgDialog_23351_Content_6 = {
    Text = "Dia tertawa dengan santai, namun ada sedikit kesepian yang nyaris tak terdeteksi dalam nada suaranya."
  },
  AvgDialog_23351_Content_7 = {
    Text = "Maafkan aku, Nyonya Soreil…"
  },
  AvgDialog_23351_Content_8 = {
    Text = "<Red:Hihi.>"
  },
  AvgDialog_23351_Content_9 = {
    Text = "Soreil tiba-tiba menatap tajam ke belakangmu, kedua matanya dipenuhi kegelisahan."
  },
  AvgDialog_23352_Content_1 = {
    Text = "Saat pintu didorong terbuka, aroma bunga yang membusuk langsung menyergap. Aula dipenuhi mawar merah, namun karena tak ada yang merawat, semuanya perlahan layu."
  },
  AvgDialog_23352_Content_10 = {
    Text = "Ramona memandang ke langit di luar."
  },
  AvgDialog_23352_Content_11 = {
    Text = "Cukup sampai di sini penyelidikan hari ini. Lokasi rumah ini sudah kucatat, kita bisa pulang dan memeriksa catatan kepemilikannya."
  },
  AvgDialog_23352_Content_12 = {
    Text = "Mm. Rencana aksi besok tetap sama seperti biasa."
  },
  AvgDialog_23352_Content_13 = {
    Text = "Pertama ambil undangan dari Karen, lalu aku ke lantai dua untuk melindungi Nyonya Soreil, kau bertanggung jawab mengawasi lantai satu."
  },
  AvgDialog_23352_Content_14 = {
    Text = "Kalau beruntung, mungkin kita bisa bertemu dengan tuan tua di dalam kereta itu."
  },
  AvgDialog_23352_Content_2 = {
    Text = "Hoek... Bau yang sama seperti yang ada pada bayangan bertopeng itu."
  },
  AvgDialog_23352_Content_3 = {
    Text = "Tidak ada apa-apa di sini... Sepertinya sudah lama tidak ada yang tinggal."
  },
  AvgDialog_23352_Content_4 = {
    Text = "Kamu memandang sekeliling aula yang gelap dan lembap. Tempat ini kosong, sarang laba-laba bergoyang tertiup angin di sudut-sudut yang tak dipedulikan, lantai dipenuhi kelopak bunga layu dan dedaunan kering."
  },
  AvgDialog_23352_Content_5 = {
    Text = "Eh, ada lukisan tergantung di sini."
  },
  AvgDialog_23352_Content_6 = {
    Text = "Di sudut tangga tergantung sebuah lukisan potret berbingkai indah, yang menggambarkan seorang wanita berpakaian mewah dengan sapuan kuas yang lembut dan samar."
  },
  AvgDialog_23352_Content_7 = {
    Text = "Riasan wanita itu sangat halus, namun sudut matanya turun, bibir tipisnya terkatup rapat membentuk satu garis, tampak sangat muram dan gelisah."
  },
  AvgDialog_23352_Content_8 = {
    Text = "Lukisan tempera? Sekarang sudah sangat jarang ada orang yang menggunakan teknik ini."
  },
  AvgDialog_23352_Content_9 = {
    Text = "Aneh sekali, lukisan ini sama sekali tidak berdebu, seolah ada seseorang yang merawatnya secara berkala."
  },
  AvgDialog_23353_Content_1 = {Text = "Telur"},
  AvgDialog_23353_Content_10 = {
    Text = "Alis Ramona berkerut erat, matanya penuh kekhawatiran."
  },
  AvgDialog_23353_Content_11 = {Text = "Ramona..."},
  AvgDialog_23353_Content_12 = {
    Text = [[
Mungkin bisa masuk ke Domain sekali lagi?
Aku akan ke lantai dua untuk melindungi Nyonya Sorel, Ramona bertugas mengawasi lantai satu.]]
  },
  AvgDialog_23353_Content_13 = {
    Text = "Domain buatan bukan tempat wisata yang bisa dikunjungi kapan saja. Yang paling penting bagi kalian sekarang adalah istirahat."
  },
  AvgDialog_23353_Content_14 = {
    Text = "Tapi kita juga perlu sedikit <Yellow:cara luar biasa> untuk memajukan penyelidikan……"
  },
  AvgDialog_23353_Content_15 = {
    Text = "Kupikir memasuki Mystic Realm buatan sudah cukup nekat."
  },
  AvgDialog_23353_Content_16 = {
    Text = "Di wajah Doer yang selalu datar tanpa ekspresi, muncul senyuman yang bisa disebut \"licik\"."
  },
  AvgDialog_23353_Content_17 = {
    Text = "Aku punya rencana yang lebih nekat lagi, tinggal lihat kalian berani ambil risiko atau tidak."
  },
  AvgDialog_23353_Content_18 = {
    Text = "Jalan Brinsburg, 23:00"
  },
  AvgDialog_23353_Content_19 = {
    Text = "Hahahaha! Malam yang indah, minuman yang nikmat!"
  },
  AvgDialog_23353_Content_2 = {
    Text = "Lalu? Di gedung opera, selain bayangan bertopeng itu, apakah kalian menemukan petunjuk lain?"
  },
  AvgDialog_23353_Content_20 = {
    Text = "Tuan Nicholas, botol racikan lama spesialmu ini adalah pahlawan besar yang menyelamatkanku dari penjara."
  },
  AvgDialog_23353_Content_21 = {
    Text = "Menyamakan Missage dengan penjara, berarti putri angkatmu adalah kepala penjara dong? Hahahaha……"
  },
  AvgDialog_23353_Content_22 = {
    Text = "Kedua pipi Dexter memerah, tatapannya sayu. Dia mengangkat jari telunjuk dan meletakkannya di bibir."
  },
  AvgDialog_23353_Content_23 = {
    Text = "Sst…… Kali ini aku diam-diam kabur keluar, jangan sampai ketahuan Ramona."
  },
  AvgDialog_23353_Content_25 = {
    Text = "Aku benar-benar iri padamu, Tuan Dexter. Kau punya keluarga yang benar-benar peduli padamu."
  },
  AvgDialog_23353_Content_26 = {
    Text = "Sedangkan aku? Belum lama ini, cinta sejati seumur hidupku meninggalkanku. Tulang-belulangnya bahkan belum dingin, ayahku juga meninggal!"
  },
  AvgDialog_23353_Content_27 = {
    Text = "Nicholas berkata demikian, lalu berjongkok di tanah dan menangis terisak-isak."
  },
  AvgDialog_23353_Content_28 = {
    Text = "Sorrel…… Setelah aku menangkap pelakunya, aku pasti akan membalaskan dendammu!"
  },
  AvgDialog_23353_Content_29 = {
    Text = "<Gray:Cinta sejati seumur hidup? Menarik, setidaknya tiga orang teman mengatakan hal yang sama padaku……>"
  },
  AvgDialog_23353_Content_3 = {
    Text = "Saat berpatroli di lantai satu, pengukur Inti Perak mengalami fluktuasi data sesaat, tapi segera menghilang."
  },
  AvgDialog_23353_Content_30 = {
    Text = "<Gray:Nyonya Sorrel memang sungguh mengagumkan.>"
  },
  AvgDialog_23353_Content_31 = {
    Text = "Hmhmhm~ Nyanyiannya penuh dengan perasaan tulus, membuatku sangat tersentuh~"
  },
  AvgDialog_23353_Content_32 = {
    Text = "Di gang yang sunyi, seorang pria berpakaian rapi berjalan sempoyongan di jalan berbatu. Cahaya lampu jalan yang temaram menarik bayangannya memanjang."
  },
  AvgDialog_23353_Content_33 = {
    Text = "<BigShake:Aku hidup untuk kebahagiaan!>"
  },
  AvgDialog_23353_Content_34 = {
    Text = "<RedItalic:Begitu banyak air mata malam ini, sungguh membekas tak terlupakan.>"
  },
  AvgDialog_23353_Content_35 = {
    Text = "<RedItalic:Biarkan darah indah kita meresap ke jendela kaca patri, menyinari pesta karnaval yang meriah.>"
  },
  AvgDialog_23353_Content_36 = {
    Text = "Suara rendah yang bergema menggema di jalanan yang sepi, Bayangan bertopeng melayang dari sudut gelap ke hadapan Dexter."
  },
  AvgDialog_23353_Content_37 = {
    Text = "Selamat malam, Lord Dexter."
  },
  AvgDialog_23353_Content_38 = {
    Text = "Eh… Anda salah menyanyikannya.\nBaris selanjutnya seharusnya \"Matanya berkaca-kaca penuh air mata, membuatku terpesona begitu dalam\"."
  },
  AvgDialog_23353_Content_39 = {
    Text = "Bayangan hitam itu mengangguk seolah baru tersadar, lalu menepuk kepalanya sendiri dengan kesal."
  },
  AvgDialog_23353_Content_4 = {
    Text = "Jadi kemungkinan besar pelakunya adalah salah satu tamu dari lantai satu."
  },
  AvgDialog_23353_Content_40 = {
    Text = "Astaga. Padahal aku ingin memberikan pertunjukan yang megah sebelum membunuhmu, tapi ternyata liriknya saja sudah salah."
  },
  AvgDialog_23353_Content_41 = {
    Text = "Membunuhku…?"
  },
  AvgDialog_23353_Content_42 = {
    Text = "Maaf jika lancang, Anda tampak seperti pria yang beradab. Mengapa harus merenggut nyawa seorang bujangan tak berdosa di tengah malam begini?"
  },
  AvgDialog_23353_Content_43 = {
    Text = "Bayangan hitam itu mengangkat kedua tangannya dengan polos."
  },
  AvgDialog_23353_Content_44 = {
    Text = "Aku hanyalah seorang pelayan hina, segala yang kulakukan semata-mata untuk memenuhi keinginan tuanku."
  },
  AvgDialog_23353_Content_45 = {
    Text = "Setelah berkata demikian, ia tiba-tiba melebur bagai tinta yang menguar, lenyap ke dalam kegelapan malam yang luas."
  },
  AvgDialog_23353_Content_46 = {Text = "……Eh?"},
  AvgDialog_23353_Content_47 = {
    Text = "Tiba-tiba rasa dingin menusuk tulang menjalar dari punggung, diikuti aroma bunga busuk yang pekat, begitu manis hingga hampir membuat mual."
  },
  AvgDialog_23353_Content_48 = {
    Text = "Perhatikan belakangmu, Tuan Dexter."
  },
  AvgDialog_23353_Content_49 = {
    Text = "Tenang saja, aku tidak membencimu. Bahkan bisa dibilang aku cukup mengaguminya."
  },
  AvgDialog_23353_Content_5 = {
    Text = "Ramona mengangguk."
  },
  AvgDialog_23353_Content_50 = {
    Text = "Jadi aku akan berusaha membuatmu mati dengan senyaman mungkin—"
  },
  AvgDialog_23353_Content_6 = {
    Text = "Setelah Nyonya Soreil jatuh dari gedung, lokasi kejadian ditutup cukup lama, dan semua orang dimintai keterangan."
  },
  AvgDialog_23353_Content_7 = {
    Text = "Tapi sebagian besar tamu di lantai satu berasal dari kalangan menengah dan tidak memiliki hubungan apa pun dengan Nyonya Soreil."
  },
  AvgDialog_23353_Content_8 = {
    Text = "Sepertinya penyelidikan menemui jalan buntu."
  },
  AvgDialog_23353_Content_9 = {
    Text = "Di antara para bangsawan yang pernah menghadiri pemakaman, tidak banyak yang masih hidup. Situasi Dexter sekarang sangat berbahaya."
  },
  AvgDialog_23354_Content_1 = {
    Text = "Keinginan Sang Pelayan"
  },
  AvgDialog_23354_Content_10 = {
    Text = "Minggir, beri aku tiga sendok! Di rumahku masih ada beberapa anak perempuan……"
  },
  AvgDialog_23354_Content_11 = {
    Text = "Mana mungkin penipu kecil punya undangan \"Nama Mawar\"?"
  },
  AvgDialog_23354_Content_12 = {
    Text = "Dia bukan hanya penipu kecil, tapi juga pelayan sejati Nyonya Soreil."
  },
  AvgDialog_23354_Content_13 = {
    Text = "Kamu berdeham, lalu maju dan mengeluarkan tanda pengenal penyelidik dari sakumu."
  },
  AvgDialog_23354_Content_14 = {
    Text = "Kepolisian Londinium sedang menyelidiki kasus, mohon warga sekalian menyingkir sebentar."
  },
  AvgDialog_23354_Content_15 = {Text = "Polisi?!"},
  AvgDialog_23354_Content_16 = {
    Text = "Transaksi hari ini, bukan, acara hari ini sampai di sini saja! Galen tiba-tiba teringat ada urusan mendesak……"
  },
  AvgDialog_23354_Content_17 = {
    Text = "Maksudku kecuali kamu, Nona Galen. Yang lain boleh pergi."
  },
  AvgDialog_23354_Content_18 = {
    Text = "Kerumunan perlahan bubar. Galen sedikit gelisah menggerakkan tubuhnya, tapi segera menenangkan diri."
  },
  AvgDialog_23354_Content_19 = {
    Text = "Dia mengamatimu dan Ramona dengan saksama dari atas ke bawah, lalu tiba-tiba menunjukkan senyum cerah."
  },
  AvgDialog_23354_Content_2 = {
    Text = "Perlu ditegaskan terlebih dahulu, ini bukan air mandi biasa!"
  },
  AvgDialog_23354_Content_20 = {
    Text = "Baik, Tuan Petugas, Galen tidak akan ke mana-mana."
  },
  AvgDialog_23354_Content_21 = {
    Text = "Ta-tapi Galen hanyalah pelayan rendahan, tidak tahu apa yang bisa membantu kalian?"
  },
  AvgDialog_23354_Content_22 = {
    Text = "Tenang saja. Kami tidak tertarik dengan bisnis kecilmu, kami hanya perlu kamu……"
  },
  AvgDialog_23354_Content_23 = {
    Text = "BRAAAK——!!"
  },
  AvgDialog_23354_Content_24 = {
    Text = "Seember air dingin disiramkan ke kepala kamu dan Ramona, seketika membuat kalian berdua basah kuyup seperti ayam tercebur air."
  },
  AvgDialog_23354_Content_27 = {
    Text = "Dia tidak bohong, di dalamnya memang ada aroma bunga mawar."
  },
  AvgDialog_23354_Content_28 = {
    Text = "Hehe! Tukang tipu, mau membujukku supaya nurut masuk penjara bersama kalian, ya?"
  },
  AvgDialog_23354_Content_29 = {
    Text = "<Big:Kalau berani, coba kejar aku!!>"
  },
  AvgDialog_23354_Content_3 = {
    Text = "Garen menambahkan garam mandi laut langka dari Pulau Sira ke dalamnya, ditambah lavender, jeruk, cengkeh, dan delapan belas jenis rempah lainnya……"
  },
  AvgDialog_23354_Content_30 = {
    Text = "Karen memasang wajah mengejek ke arah kalian, mengangkat roknya, lalu kabur secepat kilat."
  },
  AvgDialog_23354_Content_31 = {
    Text = "Jangan lari! Kalau sudah tertangkap, lihat saja bagaimana aku memberimu pelajaran!"
  },
  AvgDialog_23354_Content_4 = {
    Text = "Terakhir, diasapi dengan kelopak mawar yang didatangkan dari selatan Constance selama sehari semalam, hingga sekarang pun masih semerbak wangi!"
  },
  AvgDialog_23354_Content_5 = {
    Text = "Rahasia awet muda Nyonya Soreil, tersimpan di dalam tong air mandi yang harum semerbak ini……"
  },
  AvgDialog_23354_Content_6 = {
    Text = "Uwaaah——!!"
  },
  AvgDialog_23354_Content_7 = {
    Text = "Ya ampun, luar biasa! Apa ini bisa menyembuhkan bekas luka di wajahku……"
  },
  AvgDialog_23354_Content_8 = {
    Text = "Jangan berdesakan…… antre, semuanya antre! Dengarkan baik-baik, lima Leo Fang per sendok!"
  },
  AvgDialog_23354_Content_9 = {
    Text = "Beri aku satu sendok! Aku duluan yang datang……!!"
  },
  AvgDialog_23355_Content_1 = {
    Text = "Panduan Wanita Terhormat"
  },
  AvgDialog_23355_Content_10 = {
    Text = "Bos……aku menemukan ini di bawah roda!"
  },
  AvgDialog_23355_Content_11 = {
    Text = "Mawar lagi? Heh, percaya diri sekali. Sepertinya pelaku ini mengirimkan surat tantangan kepada kita."
  },
  AvgDialog_23355_Content_12 = {
    Text = "Periksa, bangsawan mana saja yang pernah menghadiri pemakaman itu dan masih tersisa."
  },
  AvgDialog_23355_Content_13 = {
    Text = "Situasi mereka sekarang sangat berbahaya."
  },
  AvgDialog_23355_Content_14 = {
    Text = "Terowongan Bawah Tanah Misage"
  },
  AvgDialog_23355_Content_15 = {
    Text = "Rombongan berjalan di lorong bawah tanah yang gelap dan dalam, langkah kaki yang sedikit berantakan bergema di dalamnya."
  },
  AvgDialog_23355_Content_17 = {
    Text = "Jarang sekali melihatmu seperti ini, jangan-jangan kau benar-benar ketakutan oleh hantu sampai tidak bisa tidur?"
  },
  AvgDialog_23355_Content_18 = {
    Text = "Begitulah. Sekarang semua orang di kalangan kita merasa terancam, menulis surat belasungkawa saja sudah menguras setengah nyawaku."
  },
  AvgDialog_23355_Content_19 = {
    Text = "Belum lagi harus menghadapi para detektif yang merepotkan dan wartawan tabloid itu……"
  },
  AvgDialog_23355_Content_2 = {
    Text = [[
Jalan Brynsburg, 19:30
Tiga minggu setelah kematian Nyonya Soreil]]
  },
  AvgDialog_23355_Content_20 = {
    Text = [[
Tinggallah di sekolah selama beberapa hari ini.
Sebagai penyintas pemakaman, kau sekarang menjadi objek perlindungan utama kami.]]
  },
  AvgDialog_23355_Content_21 = {
    Text = "Tenang saja, aku akan mengawasinya, sekalian mengoreksi kebiasaan buruk seseorang yang suka minum-minum dan berfoya-foya."
  },
  AvgDialog_23355_Content_22 = {
    Text = "Berfoya-foya? Jelas-jelas itu pergaulan sosial yang normal, tapi di mulutmu jadi terdengar begitu buruk."
  },
  AvgDialog_23355_Content_23 = {
    Text = "<SmallShake:Ehm ehm, kalian berdua tenanglah sebentar……>"
  },
  AvgDialog_23355_Content_24 = {
    Text = "Kudengar setelah Nyonya Sorel meninggal, ia berubah menjadi segenggam Inti Perak, dan sekarang sedang menjalani ekstraksi di tubuh Kebangkitan, menunggu <Yellow:Kebangkitan Kedua>?"
  },
  AvgDialog_23355_Content_25 = {
    Text = "Informasimu cukup cepat juga. Tapi tingkat keberhasilan Kebangkitan Kedua sangat kecil, jangan menaruh harapan padanya."
  },
  AvgDialog_23355_Content_26 = {
    Text = "Mengerti, aku hanya tidak menyangka bahwa Tubuh Kebangkitan masih bisa menghasilkan Inti Perak setelah mati. Lalu apa perbedaan Tubuh Kebangkitan yang baru dengan yang sebelumnya?"
  },
  AvgDialog_23355_Content_27 = {
    Text = [[
Akan mewarisi ingatan dan kepribadian pendahulunya, tetapi kemampuannya akan jauh berkurang.
Makanya aku selalu mengingatkan Tubuh Kebangkitan kita, usahakan jangan mati terlalu sembarangan.]]
  },
  AvgDialog_23355_Content_28 = {
    Text = [[
Nyonya Sorel sebagai Tubuh Kebangkitan, apakah memiliki kemampuan khusus?
Seseorang yang berkedudukan tinggi seperti beliau, pasti memiliki kekuatan yang luar biasa, kan?]]
  },
  AvgDialog_23355_Content_29 = {
    Text = "Dorl menggelengkan kepalanya."
  },
  AvgDialog_23355_Content_3 = {
    Text = "Langkah kaki tergesa-gesa terdengar di ujung gang yang sempit. Di balik kerumunan penonton yang berdiri jauh, para detektif Londinium sedang sibuk bekerja."
  },
  AvgDialog_23355_Content_30 = {
    Text = "Berkas datanya merupakan informasi rahasia tertinggi Misage, bahkan aku pun tidak berwenang membacanya.\nTapi aku dengar kemampuannya agak……hmm, keterampilan yang cukup abstrak."
  },
  AvgDialog_23355_Content_31 = {
    Text = "Ini juga menjelaskan mengapa meskipun dia seorang Awakened, dia tetap bisa ditikam hingga tewas di gedung opera di depan banyak orang."
  },
  AvgDialog_23355_Content_32 = {
    Text = "Superfisial? Maksudnya seperti memikat lawan jenis, mempertahankan kemudaan abadi, dan semacamnya?"
  },
  AvgDialog_23355_Content_33 = {
    Text = "Mungkin saja, tapi aku tidak tertarik membuat spekulasi yang tidak perlu."
  },
  AvgDialog_23355_Content_34 = {
    Text = "Informasi sangat rahasia… Kenapa?"
  },
  AvgDialog_23355_Content_35 = {
    Text = "Tentu saja karena dia cukup berkuasa. Soreil memiliki hubungan erat jangka panjang dengan Misager dan para pejabat tinggi pemerintah, tetapi asal-usulnya selalu menjadi misteri."
  },
  AvgDialog_23355_Content_36 = {
    Text = "Bagaimana dengan korban lainnya? Hubungan kekerabatan, aliran dana, sikap politik… Aku perlu mengetahui semua informasi, siapa yang paling diuntungkan dari rangkaian kasus ini."
  },
  AvgDialog_23355_Content_37 = {
    Text = "Sedang dalam penyelidikan, tapi prosesnya akan agak lambat. Jaringan sosial para bangsawan ini lebih rumit daripada cabang-cabang Sungai Isis."
  },
  AvgDialog_23355_Content_38 = {
    Text = "Para tokoh terkemuka yang menghadiri pemakaman itu tewas satu per satu."
  },
  AvgDialog_23355_Content_39 = {
    Text = "Melihat situasi saat ini, kemungkinan besar Dexter akan menjadi target berikutnya…"
  },
  AvgDialog_23355_Content_4 = {
    Text = "Korban adalah Baron @1·Cavendish, 32 tahun. Semalam dia pergi sendirian setelah pesta bersama teman-temannya, dan ditemukan tergeletak di sini pada pukul 4 pagi."
  },
  AvgDialog_23355_Content_40 = {
    Text = "Jangan khawatir, inilah alasan aku membawa kalian ke sini."
  },
  AvgDialog_23355_Content_41 = {
    Text = "Selagi berbicara, kalian sudah tiba di tujuan perjalanan ini. Doer menghentikan langkahnya dan menunjuk pintu yang terkunci rapat di sudut ruangan gelap."
  },
  AvgDialog_23355_Content_42 = {
    Text = "Kamu pernah melewatinya untuk memasuki Mystic Realm buatan Ramona, sebuah pengalaman yang tak terlupakan."
  },
  AvgDialog_23355_Content_43 = {
    Text = "Karena metode penyelidikan tradisional penuh kesulitan, lebih baik kita manfaatkan <Yellow:Mystic Realm Buatan>."
  },
  AvgDialog_23355_Content_44 = {
    Text = "Aku mengerti, kita bisa kembali ke lokasi kejadian melalui Mystic Realm Nyonya Soreil dan menyelidiki semuanya sekaligus!"
  },
  AvgDialog_23355_Content_45 = {
    Text = "Mystic Realm Soreil saja mungkin tidak cukup. Kita juga perlu menggabungkan Mystic Realm <Blue:pelayannya, Karen>, bahkan lebih banyak pihak terkait untuk mengumpulkan petunjuk."
  },
  AvgDialog_23355_Content_46 = {
    Text = "Pelayan Karen?"
  },
  AvgDialog_23355_Content_47 = {
    Text = "Doer mengangguk."
  },
  AvgDialog_23355_Content_48 = {
    Text = "Dia sangat terpukul atas kematian Soreil, dan bersumpah akan bekerja sama sepenuhnya dengan penyelidikan kita untuk menemukan pelaku sebenarnya."
  },
  AvgDialog_23355_Content_49 = {
    Text = [[
Misager, Pintu Masuk Mystic Realm Buatan
Sebelum Berangkat]]
  },
  AvgDialog_23355_Content_5 = {
    Text = "Ini sudah bangsawan ke-7 yang meninggal secara tidak wajar. Kalau tidak salah, yang pertama meninggal adalah……"
  },
  AvgDialog_23355_Content_50 = {
    Text = "Setelah semua persiapan selesai, Ramona berbalik dan menatap Dexter."
  },
  AvgDialog_23355_Content_51 = {
    Text = "Jangan tinggalkan sekolah, dan jangan berkeliaran sembarangan di dalam sekolah. Tunggu sampai kami kembali."
  },
  AvgDialog_23355_Content_52 = {
    Text = "Lagi-lagi nada bicara seperti membujuk anak kecil. Kau masih ingat kalau aku ini ayahmu yang lebih tua dan terhormat, kan?"
  },
  AvgDialog_23355_Content_54 = {
    Text = "Baik, baik, aku menyerah……\nAku akan tinggal di sini setiap hari, tidak pergi ke mana-mana, dan sama sekali tidak akan merepotkan siapa pun."
  },
  AvgDialog_23355_Content_55 = {
    Text = "Dexter masih tersenyum ramah seperti biasa. Dia meletakkan tangannya di punggung kamu dan Ramona, lalu mendorong pelan ke depan—"
  },
  AvgDialog_23355_Content_56 = {
    Text = "Pergilah, anak-anak. Nyawaku bergantung pada kalian."
  },
  AvgDialog_23355_Content_6 = {
    Text = "<Red:Duke Harold>. Kasus ini aku ingat dengan sangat jelas, itu kan mobil Porsche, di seluruh kerajaan pun tidak ada berapa unit!"
  },
  AvgDialog_23355_Content_7 = {
    Text = "Sayangnya hancur menjadi besi rongsokan……Saat itu yang duduk di dalam mobil ada Duke Harold beserta butler dan sopirnya, ketiganya tewas semua."
  },
  AvgDialog_23355_Content_8 = {
    Text = "Selain sama-sama kalangan atas, satu-satunya kesamaan para korban adalah mereka semua menghadiri pemakaman Nyonya Soreil tiga minggu lalu."
  },
  AvgDialog_23355_Content_9 = {
    Text = "Jangan-jangan benar seperti yang ditulis tabloid, mereka diikuti oleh <Red:arwah Nyonya Soreil>……"
  },
  AvgDialog_23356_Content_1 = {
    Text = "Pemakaman Mawar"
  },
  AvgDialog_23356_Content_10 = {
    Text = "Hannah belum berhasil menggali informasi lebih lanjut dari kantor polisi……tapi tidak apa-apa, reporter Hannah pantang menyerah! Sekarang aku kembali dengan informasi baru!"
  },
  AvgDialog_23356_Content_11 = {
    Text = "Informasi 1: Konon pemakaman hari ini dihiasi ribuan mawar \"Red Celebration\" yang didatangkan dari Constance, dengan total biaya mencapai sepuluh ribu Leofang!"
  },
  AvgDialog_23356_Content_12 = {
    Text = "Informasi 2: Coba tebak, wajah-wajah familiar siapa saja yang kulihat di luar tadi?"
  },
  AvgDialog_23356_Content_13 = {
    Text = "Keluarga Cavendish, Adipati dan Adipatni Windsor, serta yang paling kalian nantikan……"
  },
  AvgDialog_23356_Content_14 = {
    Text = "<Big:Yang terhormat Adipati Harold beserta putra tunggalnya, Nicholas Harold!>"
  },
  AvgDialog_23356_Content_15 = {
    Text = "Dulu, berita tentang ayah dan anak yang saling menantang duel demi Nyonya Soleil sempat menghebohkan seluruh kota……"
  },
  AvgDialog_23356_Content_16 = {
    Text = "Sementara itu, di dalam Pemakaman Woodlawn……"
  },
  AvgDialog_23356_Content_17 = {
    Text = "Hari ini kita berkumpul di sini untuk mengenang dan memperingati kehidupan Soleil·@1."
  },
  AvgDialog_23356_Content_18 = {
    Text = "Dia adalah putri paling saleh dari Bapa Ilahi, seorang wanita berbudi luhur dan patut dikagumi……"
  },
  AvgDialog_23356_Content_19 = {
    Text = "Hatsyi……<Big:Hatsyi!>"
  },
  AvgDialog_23356_Content_2 = {
    Text = [[
Di Luar Pemakaman Woodlawn
Tiga minggu lalu]]
  },
  AvgDialog_23356_Content_20 = {
    Text = "Yang Mulia Adipati sedang flu? Anda terus bersin-bersin."
  },
  AvgDialog_23356_Content_21 = {
    Text = "Aku tidak tahan dengan bau bunga-bunga norak ini……Mengangkutnya ke sini pasti menghabiskan biaya beberapa ribu Leofang, bukan?"
  },
  AvgDialog_23356_Content_22 = {
    Text = "Soleil sampai mati pun tetap konsisten dengan gaya khas orang kaya baru, sungguh patut dikagumi……Hatsyi!"
  },
  AvgDialog_23356_Content_23 = {
    Text = "Memang patut dikagumi."
  },
  AvgDialog_23356_Content_24 = {
    Text = "Gaya seperti ini bisa menjadi bahan perbincangan bagi reporter gosip dan warga di luar sana, pantas saja dia bisa menjadi idola publik Londinium."
  },
  AvgDialog_23356_Content_25 = {
    Text = "Hmph. Trik murahan."
  },
  AvgDialog_23356_Content_26 = {
    Text = "Dexter mengangkat bahu dan memandang sekeliling dengan bosan."
  },
  AvgDialog_23356_Content_27 = {
    Text = "Para selebritas berpakaian mewah berkumpul dalam kelompok kecil di depan makam, bisikan-bisikan yang sengaja diredam sesekali terdengar bersama doa sang pembawa acara."
  },
  AvgDialog_23356_Content_28 = {
    Text = "<Gray:Gadis kampung, tapi berpura-pura jadi bangsawan dari luar negeri…>"
  },
  AvgDialog_23356_Content_29 = {
    Text = "<Gray:Gaun yang dikenakannya untuk pemakaman ini, terbuat dari flanel ya? Teksturnya bagus sekali…>"
  },
  AvgDialog_23356_Content_3 = {
    Text = "Kresek… kresek…"
  },
  AvgDialog_23356_Content_30 = {
    Text = "<Gray:…selir Raja…dan Pangeran…Ratu justru diam saja…>"
  },
  AvgDialog_23356_Content_32 = {
    Text = "Sepertinya nyonya ini memang tidak begitu disukai orang ya."
  },
  AvgDialog_23356_Content_33 = {
    Text = "Debu kembali ke debu, tanah kembali ke tanah.\nJiwa Nona Soreil telah memasuki tanah kekal, kembali ke pelukan Bapa…"
  },
  AvgDialog_23356_Content_34 = {
    Text = "Lord Dexter, melihat reaksimu, sepertinya kau tidak begitu setuju dengan pandangan kami tentang Nyonya Soreil?"
  },
  AvgDialog_23356_Content_35 = {
    Text = "Jangan-jangan kau juga salah satu pengagumnya? Atau bisa dibilang…pernah? Akan segera?"
  },
  AvgDialog_23356_Content_36 = {
    Text = "Tawa tertahan meledak dari kerumunan, Dexter mengerutkan alis."
  },
  AvgDialog_23356_Content_37 = {
    Text = "Aku tidak begitu dekat dengan Nyonya Soreil semasa hidupnya, dan aku juga tidak tertarik mengetahui perselisihan antara dia dan kalian."
  },
  AvgDialog_23356_Content_38 = {
    Text = "Tapi akal sehatku mengatakan, membicarakan orang yang sudah meninggal di pemakamannya bukanlah perilaku seorang pria terhormat."
  },
  AvgDialog_23356_Content_39 = {
    Text = "Hati-hati, nanti tengah malam ada hantu wanita mengetuk pintumu lho."
  },
  AvgDialog_23356_Content_4 = {
    Text = "Uhuk uhuk… Lensa dan pengukur cahayanya sudah siap belum? Ceroboh sekali, cepat!"
  },
  AvgDialog_23356_Content_40 = {
    Text = "…Semoga Bapa memberkati, anakku."
  },
  AvgDialog_23356_Content_41 = {
    Text = "Malam tiba, sebuah mobil Ferdinand Porsche yang masih baru melaju di jalan berbatu yang tidak rata."
  },
  AvgDialog_23356_Content_42 = {
    Text = "Sialan, ke mana pun selalu ada wartawan tabloid itu."
  },
  AvgDialog_23356_Content_43 = {
    Text = "Di luar sana beredar rumor bahwa aku dan Nicholas berkelahi memperebutkan Soreil, sungguh omong kosong!"
  },
  AvgDialog_23356_Content_44 = {
    Text = "Bagaimana mungkin rakyat jelata memahami apa yang sebenarnya dipikirkan Tuan Duke? Mereka lebih suka percaya kisah cinta klise yang absurd itu."
  },
  AvgDialog_23356_Content_45 = {
    Text = "Cinta, hmph. Nicholas juga bilang padaku ini namanya \"cinta\"."
  },
  AvgDialog_23356_Content_46 = {
    Text = "Biasanya aku bisa pura-pura tidak melihat apapun yang mereka berdua lakukan, tapi wanita itu ternyata mengincar lahan perburuan di pinggiran kota Shoreditch."
  },
  AvgDialog_23356_Content_47 = {
    Text = "Keserakahan pasti akan mendatangkan bencana, jadi jangan salahkan kami kalau kami tidak bersikap sopan lagi……"
  },
  AvgDialog_23356_Content_48 = {Text = "——!!"},
  AvgDialog_23356_Content_49 = {
    Text = "Mobil berhenti mendadak, suara rem yang memekik memecah keheningan yang hanya dimiliki malam."
  },
  AvgDialog_23356_Content_5 = {
    Text = "Zzzzt……"
  },
  AvgDialog_23356_Content_50 = {
    Text = "<Shake:Aduh!! Pinggangku……>"
  },
  AvgDialog_23356_Content_51 = {
    Text = "Kemampuan menyetirmu makin lama makin parah, Fred. Bahkan mengerem saja tidak bisa lagi?"
  },
  AvgDialog_23356_Content_52 = {
    Text = "<Shake:Bukan, Tuan……a-ada……sesuatu……di depan……>"
  },
  AvgDialog_23356_Content_53 = {
    Text = "Bayangan hitam itu berdiri sendirian di bawah cahaya bulan yang dingin, wajah tersenyum yang dilukis dengan darah di topengnya membentang hingga sudut mata yang kosong."
  },
  AvgDialog_23356_Content_54 = {
    Text = "Dia merentangkan kedua lengannya di ujung gang yang sepi, bersenandung pelan menyanyikan lagu pesta minum yang riang."
  },
  AvgDialog_23356_Content_55 = {
    Text = "<RedItalic:Mari kita angkat tinggi piala perjamuan, anggur di dalamnya memabukkan hati.>"
  },
  AvgDialog_23356_Content_56 = {
    Text = "<RedItalic:Waktu yang menyenangkan memang indah, tapi kematian yang tulus jauh lebih berharga……>"
  },
  AvgDialog_23356_Content_57 = {
    Text = "Selamat malam, Tuan Harold."
  },
  AvgDialog_23356_Content_6 = {
    Text = "Sudah bisa merekam? Bagus……3, 2, 1, mulai!"
  },
  AvgDialog_23356_Content_7 = {
    Text = "Selamat pagi, teman-teman Misager! Di sini reporter koran sekolah, Hannah, membawakan laporan ek·sklu·sif untuk kalian!"
  },
  AvgDialog_23356_Content_8 = {
    Text = "<Blue:Pemakaman Nyonya Soleil>, sosialita ternama yang sangat dicintai warga Londinium, sedang berlangsung di Pemakaman Woodlawn yang tak jauh dari tempatku berdiri!"
  },
  AvgDialog_23356_Content_9 = {
    Text = "Waktu berlalu begitu cepat! Tanpa terasa, sudah genap satu minggu sejak kematian misterius Nyonya Soleil di gedung opera."
  },
  AvgDialog_23359_Content_10 = {
    Text = "Kau orang yang cerdas, Soreil. Tuan Binder adalah keluarga terbaik yang bisa kita dekati, mengerti?"
  },
  AvgDialog_23359_Content_11 = {
    Text = "Tidak suka juga tidak apa-apa. Selama bisa mendapatkan hartanya, kau bisa melakukan apa pun yang kau mau, berkencan dengan siapa pun yang kau suka."
  },
  AvgDialog_23359_Content_13 = {
    Text = "Aku tidak suka cara seperti ini, Ayah."
  },
  AvgDialog_23359_Content_14 = {
    Text = [[
Keluarga seperti kita tidak punya hak untuk bertindak sesuka hati.
Lihatlah penyakit ibumu, tega kah kau melihatnya terus menderita?]]
  },
  AvgDialog_23359_Content_15 = {
    Text = "<Shake:Uhuk uhuk…… Jangan pedulikan aku, Soreil. Lagipula aku juga tidak akan hidup lama lagi……>"
  },
  AvgDialog_23359_Content_16 = {Text = "Mama……"},
  AvgDialog_23359_Content_17 = {
    Text = "Soreil, aku dan ibumu sudah tua. Kau adalah satu-satunya harapan kami."
  },
  AvgDialog_23359_Content_18 = {
    Text = "Kami menghabiskan begitu banyak uang untukmu bukan untuk beramal, tapi agar suatu hari bisa mendapatkan imbalan yang lebih besar, mengerti?"
  },
  AvgDialog_23359_Content_19 = {
    Text = "Jangan lakukan hal yang membuatmu menyesal."
  },
  AvgDialog_23359_Content_2 = {
    Text = "245 tahun sebelum Banjir Besar, Konstan bagian selatan"
  },
  AvgDialog_23359_Content_20 = {
    Text = "Di malam yang sunyi, sang gadis duduk di tepi tempat tidur, menatap cahaya bulan yang terang di luar jendela dengan pandangan menerawang."
  },
  AvgDialog_23359_Content_21 = {
    Text = "Ia memeluk erat lututnya, diam-diam menyemangati dirinya sendiri dalam hati seperti yang selalu ia lakukan."
  },
  AvgDialog_23359_Content_22 = {
    Text = "Jangan takut, Soreil. Kau pasti akan menemukan jalan keluarnya."
  },
  AvgDialog_23359_Content_23 = {
    Text = "<Red:Sungguh disayangkan… Inikah harga yang harus dibayar untuk keindahan?>"
  },
  AvgDialog_23359_Content_24 = {
    Text = "<Red:Bahkan bulan purnama yang paling sempurna sekalipun, begitu jatuh ke dunia fana, akan ternoda oleh debu.>"
  },
  AvgDialog_23359_Content_25 = {
    Text = "Kabut di sudut ruangan bergerak-gerak perlahan dengan suara gemerisik, lalu memadat menjadi sosok bayangan yang tak berbentuk."
  },
  AvgDialog_23359_Content_26 = {Text = "?!"},
  AvgDialog_23359_Content_27 = {
    Text = "Siapa kau? Aku akan memanggil orang——"
  },
  AvgDialog_23359_Content_28 = {
    Text = "Ssst… Aku hanyalah arwah pengembara yang berkelana di dunia fana, identitasku sepenuhnya fiktif, dan rupaku pun hanyalah penyamaran."
  },
  AvgDialog_23359_Content_29 = {
    Text = "Perkenalkan, kau boleh memanggilku <Red:\"N\">."
  },
  AvgDialog_23359_Content_3 = {
    Text = "Soreil, Soreil-ku yang cantik. Ini gaun baru yang kubeli untukmu, warna putih kesukaanmu."
  },
  AvgDialog_23359_Content_30 = {
    Text = "Didorong oleh kesenangan tertentu yang tak bisa kujelaskan, aku mengumpulkan kisah, dan juga menulis ulang kisah.\nJika bertemu manusia yang menarik perhatianku, aku tak keberatan membantu mereka——dalam batas yang wajar."
  },
  AvgDialog_23359_Content_31 = {
    Text = "Jadi, ceritakanlah kebingunganmu padaku."
  },
  AvgDialog_23359_Content_32 = {
    Text = [[
Suara kabut hitam itu rendah dan merdu, entah mengapa memiliki kekuatan yang mampu menghanyutkan hati.
Sang gadis perlahan menjadi tenang.]]
  },
  AvgDialog_23359_Content_33 = {
    Text = "Ayahku tidak cukup cerdas, dan Tuan Binder juga bukan pasangan yang baik. Dia serakah dan gemar berjudi, tidak sampai tiga tahun ia bisa menghabiskan seluruh harta keluarga."
  },
  AvgDialog_23359_Content_34 = {
    Text = "Tapi aku terlalu lemah, aku tidak bisa melawan mereka."
  },
  AvgDialog_23359_Content_35 = {
    Text = "Sedangkan ibuku… dia selalu menangis. Dia tidak bisa membantuku."
  },
  AvgDialog_23359_Content_36 = {
    Text = "Sang gadis menundukkan kepala, raut wajahnya muram."
  },
  AvgDialog_23359_Content_37 = {
    Text = "Aku sudah lelah. Lelah selalu dihantui ketakutan akan uang, lelah dengan perasaan bahwa nasibku digenggam di tangan orang lain."
  },
  AvgDialog_23359_Content_38 = {
    Text = "Kau bilang kau bisa membantuku, bisakah kau memberiku banyak uang?"
  },
  AvgDialog_23359_Content_39 = {
    Text = "Sayangnya tidak bisa, anakku."
  },
  AvgDialog_23359_Content_4 = {
    Text = "Cantik sekali, terima kasih, Ayah. Tapi kelihatannya terlalu mahal……"
  },
  AvgDialog_23359_Content_40 = {
    Text = "Kalau membunuh orang untukku?"
  },
  AvgDialog_23359_Content_41 = {
    Text = "Hahaha…… Itu bukan kata-kata yang seharusnya diucapkan oleh seorang gadis berusia 13 tahun, tapi itulah alasan aku memilihmu."
  },
  AvgDialog_23359_Content_42 = {
    Text = [[
Sayangnya, aku tidak bisa membunuh orang untukmu.
Tapi aku jamin, jika kita menandatangani kontrak, kau akan mendapatkan beberapa "bantuan yang diperlukan".]]
  },
  AvgDialog_23359_Content_43 = {
    Text = "Cara-cara ini memang tidak langsung, tapi cukup mematikan."
  },
  AvgDialog_23359_Content_44 = {
    Text = "Semua itu akan membantumu mendaki ke ketinggian yang belum pernah kau capai, membawamu menikmati pemandangan yang belum pernah kau lihat, dan kau tidak perlu lagi menikahi penjudi tua botak."
  },
  AvgDialog_23359_Content_45 = {
    Text = "Gadis itu mendengarkan dengan tenang, senyum perlahan muncul di wajahnya yang dingin."
  },
  AvgDialog_23359_Content_46 = {
    Text = "Sejak kecil aku sudah menjadi anak yang cantik dan populer. Banyak orang mendekatiku, ingin berteman denganku."
  },
  AvgDialog_23359_Content_47 = {
    Text = "Mereka menatapku seperti serigala, setiap orang ingin mendapatkan sesuatu dariku beserta bunganya — persis seperti yang sering dikatakan ayahku."
  },
  AvgDialog_23359_Content_48 = {
    Text = "Jadi sejak dini aku sudah memahami, keajaiban tidak akan pernah turun kepadaku."
  },
  AvgDialog_23359_Content_49 = {
    Text = "Aku tidak bodoh, Tuan N. Anda sudah mengajukan begitu banyak syarat yang menggiurkan, jadi……"
  },
  AvgDialog_23359_Content_5 = {
    Text = "Ya, memang mahal. Menghabiskan 200 Sterling penuh."
  },
  AvgDialog_23359_Content_50 = {
    Text = "Apa harganya?"
  },
  AvgDialog_23359_Content_51 = {
    Text = [[
Pinggiran Londinium
Kediaman Lombert]]
  },
  AvgDialog_23359_Content_52 = {
    Text = "Tuan Lombert, Anda dituduh terlibat dalam pembunuhan Nyonya Soreil, silakan ikut kami."
  },
  AvgDialog_23359_Content_53 = {
    Text = "Waktu seolah telah lama berhenti. Cahaya matahari pucat membanjiri ruangan, menyelimuti aula yang sunyi dengan lapisan kain putih."
  },
  AvgDialog_23359_Content_54 = {
    Text = "Angin dingin terus-menerus menerobos masuk melalui celah jendela yang pecah, meniup mawar dan dedaunan kering di lantai hingga berdesir."
  },
  AvgDialog_23359_Content_55 = {
    Text = "Uhuk uhuk, akhirnya kalian datang…… Aku sudah menunggu kalian sangat lama……"
  },
  AvgDialog_23359_Content_56 = {
    Text = "Orang tua yang sudah renta itu terduduk dalam di kursi beludru yang empuk, menggenggam segelas anggur merah sambil menggoyang-goyangkannya perlahan."
  },
  AvgDialog_23359_Content_57 = {
    Text = "Jika aku bilang yang membunuhnya bukan aku, apakah kalian akan percaya?"
  },
  AvgDialog_23359_Content_58 = {
    Text = "Sebagai satu-satunya penerima manfaat dari wasiat Soreil, ditambah belakangan ini Anda terlilit utang karena judi, Anda memiliki motif kejahatan yang sempurna."
  },
  AvgDialog_23359_Content_59 = {
    Text = "Selain itu……"
  },
  AvgDialog_23359_Content_6 = {
    Text = "200 Sterling?! Penghasilan Ayah setahun saja hanya…… Tidak boleh, kita harus segera mengembalikannya."
  },
  AvgDialog_23359_Content_60 = {
    Text = "Ramona mengeluarkan belati indah itu."
  },
  AvgDialog_23359_Content_61 = {
    Text = "Ini adalah barang yang kami temukan di lokasi kejadian, barang impor berharga dari Timur Jauh."
  },
  AvgDialog_23359_Content_62 = {
    Text = "Kami menemukan penjualnya, pedagang barang antik itu mengakui bahwa Tuan Lambert membelinya dua bulan lalu."
  },
  AvgDialog_23359_Content_63 = {
    Text = "Mungkin Anda bisa menjelaskan alasan membawanya ke gedung opera hari itu?"
  },
  AvgDialog_23359_Content_64 = {
    Text = "Alasan? Hehehe…"
  },
  AvgDialog_23359_Content_65 = {
    Text = "Terdengar suara kursi berderit di telinga."
  },
  AvgDialog_23359_Content_66 = {
    Text = "Lambert berdiri dengan susah payah, lalu melangkah tertatih-tatih menuju Ramona."
  },
  AvgDialog_23359_Content_67 = {
    Text = "Karena dia pantas mati.\nAkulah yang mengangkatnya ke posisi tinggi. Kekayaan, status, ketenaran… semua itu aku yang mengatur di balik layar."
  },
  AvgDialog_23359_Content_68 = {
    Text = "Tapi dia? Setelah sukses besar, bukannya membalas budi, malah ingin menjauh dariku sejauh mungkin."
  },
  AvgDialog_23359_Content_69 = {
    Text = "Lihatlah rumah ini… Aku sudah menggadaikan semua yang bisa digadaikan, yang tersisa hanyalah mawar-mawar yang memenuhi ruangan ini."
  },
  AvgDialog_23359_Content_7 = {
    Text = "Kau pantas mendapatkan yang terbaik, Soreil."
  },
  AvgDialog_23359_Content_70 = {
    Text = [[
Ini adalah bunga favorit istriku semasa hidupnya.
Setelah istriku meninggal, satu-satunya ikatan antara aku dan Sorel pun lenyap.]]
  },
  AvgDialog_23359_Content_71 = {
    Text = "Jadi aku memutuskan untuk membunuhnya…"
  },
  AvgDialog_23359_Content_72 = {
    Text = "Kelopak bunga beterbangan jatuh dari udara."
  },
  AvgDialog_23359_Content_73 = {
    Text = "Pria tua itu mendongak, wajahnya sudah separuh lebih dimakan oleh Cairan Erosi, cairan hitam pekat mengalir dari sudut matanya bagaikan air mata."
  },
  AvgDialog_23359_Content_74 = {
    Text = "…Sama seperti tekadku untuk membunuh kalian."
  },
  AvgDialog_23359_Content_8 = {
    Text = "Tiga hari lagi, Tuan Binder akan bertamu ke Rumah. Saat itu, kenakanlah gaun ini dan bergaullah baik-baik dengannya."
  },
  AvgDialog_23359_Content_9 = {
    Text = "……Tuan tua yang sombong dan angkuh itu? Aku tidak menyukainya."
  },
  AvgDialog_23360_Content_1 = {
    Text = "Tahanan Takdir"
  },
  AvgDialog_23360_Content_10 = {
    Text = "<Red:Hihi.>"
  },
  AvgDialog_23360_Content_11 = {
    Text = "<Red:Aku suka {Male=dia,Female=dia}.>"
  },
  AvgDialog_23360_Content_12 = {
    Text = "Dia tampaknya sedang takut akan sesuatu."
  },
  AvgDialog_23360_Content_13 = {
    Text = "…Kamu benar-benar sangat ingin aku menemanimu bermain permainan ini?"
  },
  AvgDialog_23360_Content_14 = {
    Text = "Nyonya Soleil terdiam sesaat, lalu mengangguk pelan."
  },
  AvgDialog_23360_Content_15 = {
    Text = "<Gray:Minum dua gelas sampanye seharusnya tidak masalah…>"
  },
  AvgDialog_23360_Content_16 = {
    Text = [[
Aku menerima tawaranmu, mari kita selesaikan dengan cepat.
Apa pertanyaan pertamanya?]]
  },
  AvgDialog_23360_Content_17 = {Text = "Ngh..."},
  AvgDialog_23360_Content_18 = {
    Text = "Soleil menopang dagunya dengan satu tangan, jari-jarinya yang ramping mengetuk-ngetuk pelan di pipi."
  },
  AvgDialog_23360_Content_19 = {
    Text = "Pertanyaan pertama, bagaimana Misage tahu bahwa malam ini akan ada orang yang datang untuk membunuhku?"
  },
  AvgDialog_23360_Content_2 = {
    Text = "Mi, minum alkohol?!"
  },
  AvgDialog_23360_Content_20 = {
    Text = "Jika kamu tidak bisa menjawab, apakah aku boleh menduga secara wajar bahwa kalian juga terlibat di dalamnya sampai tingkat tertentu?"
  },
  AvgDialog_23360_Content_21 = {
    Text = "Ini bukan pertanyaan yang bisa dijawab sembarangan…"
  },
  AvgDialog_23360_Content_22 = {
    Text = "Kamu mengangkat gelas sampanye di atas meja dan meneguknya dalam sekali teguk."
  },
  AvgDialog_23360_Content_23 = {
    Text = "Di luar dugaan, cairan berwarna emas pucat itu memiliki rasa yang ringan dan halus, dan kamu juga mencium aroma jeruk yang samar."
  },
  AvgDialog_23360_Content_24 = {
    Text = "<Gray:Hmm… ternyata cukup enak.>"
  },
  AvgDialog_23360_Content_25 = {
    Text = "Pelan-pelan minumnya, Penjaga Rahasia. Sebotol anggur ini cukup untuk membeli satu unit rumah di pusat kota Londinium."
  },
  AvgDialog_23360_Content_26 = {
    Text = "Uhuk uhuk…… <Big:Apa?!>"
  },
  AvgDialog_23360_Content_27 = {
    Text = "Selanjutnya pertanyaan kedua. Ini atas nama para nona dan nyonya di Londinium……"
  },
  AvgDialog_23360_Content_28 = {
    Text = "Soreil tersenyum tipis kepadamu. Entah mengapa, kau merasakan firasat buruk."
  },
  AvgDialog_23360_Content_29 = {
    Text = "Siapa sebenarnya ibu kandung dari putri Lord Dexter?"
  },
  AvgDialog_23360_Content_3 = {
    Text = "<Gray:Nona Doer bilang aku belum cukup umur untuk minum alkohol, dan selama penyelidikan juga tidak boleh minum…>"
  },
  AvgDialog_23360_Content_30 = {
    Text = "Bruusshh——!!"
  },
  AvgDialog_23360_Content_31 = {
    Text = "Anggur yang belum sempat kau telan menyembur keluar semuanya. Soreil mengangkat alisnya, dan Galen segera maju untuk menyeka cairan anggur di meja."
  },
  AvgDialog_23360_Content_32 = {
    Text = "<SmallShake:Tsk tsk, seteguk kecil pun itu uang lho! Cukup untuk membeli kalung baru di Harrods Department Store……>"
  },
  AvgDialog_23360_Content_33 = {
    Text = "Tak kusangka Nyonya Soreil juga tertarik dengan gosip membosankan seperti ini, sungguh mengejutkan…… Ha, haha."
  },
  AvgDialog_23360_Content_34 = {
    Text = "Kuberitahu sebuah rahasia: \"sosialita\" seperti kami, setidaknya setengah dari waktu dalam sehari dihabiskan dalam gosip."
  },
  AvgDialog_23360_Content_35 = {
    Text = "Kalau tidak, menurutmu <Blue:Salon Nyonya Soreil> bisa berjalan berkat apa?"
  },
  AvgDialog_23360_Content_36 = {
    Text = "……Bisa kubayangkan."
  },
  AvgDialog_23360_Content_37 = {
    Text = "Semua orang tidak percaya cerita ayah-anak angkat itu lho. Menurut rumor di kalangan atas, ibu kandung anak itu seharusnya adalah simpanan seorang bangsawan……"
  },
  AvgDialog_23360_Content_38 = {
    Text = "Ja-jangan bicara sembarangan.\nLord Dexter orangnya lurus dan menjaga kehormatan diri, sama sekali bukan seperti yang orang-orang kira……"
  },
  AvgDialog_23360_Content_39 = {
    Text = "%player%, komunikator ini selalu dalam keadaan aktif, aku mendengar semuanya."
  },
  AvgDialog_23360_Content_4 = {
    Text = "Maaf, Nyonya Soleil."
  },
  AvgDialog_23360_Content_40 = {
    Text = "Kusarankan kalian jangan buang-buang tenaga, bahkan aku sendiri tidak tahu siapa ibu kandungku."
  },
  AvgDialog_23360_Content_42 = {
    Text = "Entah karena pengaruh alkohol atau bukan, kau tiba-tiba merasa agak pusing."
  },
  AvgDialog_23360_Content_43 = {
    Text = "Sama sekali bukan seperti yang orang-orang kira? Lalu seperti apa?"
  },
  AvgDialog_23360_Content_44 = {
    Text = "Kau menggelengkan kepala dan mengangkat gelas anggur di atas meja."
  },
  AvgDialog_23360_Content_45 = {
    Text = "Apakah pertanyaan ini penting bagimu?"
  },
  AvgDialog_23360_Content_46 = {
    Text = "Tidak penting, hanya untuk melengkapi tiga pertanyaan saja."
  },
  AvgDialog_23360_Content_47 = {
    Text = "<Red:Bagus, Soleil. Selanjutnya……>"
  },
  AvgDialog_23360_Content_48 = {
    Text = "Soleil dengan lembut menekan gelas minuman di hadapanmu. Entah mengapa, kau merasa otot-otot di wajahnya seolah berkedut sesaat."
  },
  AvgDialog_23360_Content_49 = {
    Text = "Anak kecil jangan sembarangan minum alkohol ya, anggap saja gelas ini jadi utangmu padaku. Pertanyaan yang benar-benar ingin kutanyakan adalah……"
  },
  AvgDialog_23360_Content_5 = {
    Text = "Bagaimana kalau kubilang, aku selama ini tahu siapa yang ingin membunuhku?"
  },
  AvgDialog_23360_Content_50 = {
    Text = "Begitu kata-katanya selesai, wajah Nyonya Soleil tiba-tiba mulai berubah bentuk, menjadi kabur……"
  },
  AvgDialog_23360_Content_51 = {
    Text = "Lalu berubah sepenuhnya menjadi rupa yang sama sekali berbeda."
  },
  AvgDialog_23360_Content_52 = {
    Text = "Selamat malam, {Male=tuan,Female=nyonya}. Izinkan aku menyapamu melalui mulut orang lain."
  },
  AvgDialog_23360_Content_53 = {
    Text = "Sepuluh menit lagi, kau akan melupakan seluruh isi percakapan ini sepenuhnya, jadi jangan takut untuk menjawab pertanyaanku apa pun itu."
  },
  AvgDialog_23360_Content_54 = {
    Text = "Pertanyaanku juga sangat sederhana……"
  },
  AvgDialog_23360_Content_55 = {
    Text = "Wajahnya diselimuti kabut hitam pekat. Kau tidak bisa melihat jelas wajahnya, namun merasakan keakraban yang tak bisa dijelaskan."
  },
  AvgDialog_23360_Content_56 = {
    Text = "Seolah-olah dahulu kala, kalian pernah berpapasan di suatu tempat, atau mungkin, dia pernah berdiri di kejauhan memandangimu, terdiam lama."
  },
  AvgDialog_23360_Content_57 = {
    Text = "Namamu yang dulu, apakah @2?"
  },
  AvgDialog_23360_Content_59 = {
    Text = "Dunia seolah surut bagai gelombang pasang dalam sekejap."
  },
  AvgDialog_23360_Content_6 = {Text = "?!"},
  AvgDialog_23360_Content_60 = {
    Text = "Semua suara menghilang, semua pemandangan juga lenyap."
  },
  AvgDialog_23360_Content_61 = {
    Text = "Bibir terbuka dan tertutup, mengucapkan kata-kata tanpa suara. Tapi kau tahu, dia mengucapkan <Yellow:nama aslimu> dengan tepat tanpa kesalahan."
  },
  AvgDialog_23360_Content_62 = {
    Text = "%player%? Kenapa di sana tiba-tiba tidak ada suara sama sekali, apa yang terjadi?"
  },
  AvgDialog_23360_Content_63 = {
    Text = "Kau membuka bibirmu yang kering, namun tidak bisa mengeluarkan suara apa pun lagi."
  },
  AvgDialog_23360_Content_64 = {
    Text = "Dengungan yang sangat padat terus berputar dan bergejolak di kedalaman kesadaranmu, merobek-robek sarafmu dengan ganas."
  },
  AvgDialog_23360_Content_65 = {
    Text = "<Change>Aku tidak tahu……"
  },
  AvgDialog_23360_Content_66 = {Text = "...?"},
  AvgDialog_23360_Content_67 = {
    Text = "Tetap di sana jangan bergerak, %player%. Aku akan segera ke atas——"
  },
  AvgDialog_23360_Content_68 = {Text = "BRAK!"},
  AvgDialog_23360_Content_69 = {
    Text = "Lampu di dalam teater tiba-tiba padam."
  },
  AvgDialog_23360_Content_7 = {
    Text = "Temani aku menyelesaikan permainan ini, dan aku akan memberitahumu jawabannya."
  },
  AvgDialog_23360_Content_70 = {
    Text = "Di satu-satunya sumber cahaya di depan panggung, bayangan hitam yang familiar sekaligus asing itu muncul kembali."
  },
  AvgDialog_23360_Content_71 = {
    Text = "Ia menggenggam setangkai mawar, nyanyian aneh yang memekakkan telinga mengalir keluar dari kabut hitam yang terus bergerak-gerak di wajahnya."
  },
  AvgDialog_23360_Content_72 = {
    Text = "<RedItalic:Wahai tahanan takdir.>"
  },
  AvgDialog_23360_Content_73 = {
    Text = "<RedItalic:Kau menyamar sebagai utusan cahaya untuk membodohi semua makhluk, kau menerobos masuk ke wilayah terlarang yang tak dikenal demi mencari kebenaran.>"
  },
  AvgDialog_23360_Content_74 = {
    Text = "<RedItalic:Ingatanmu yang hilang tumbuh dan mengalir dari mata yang kosong, masa depanmu yang menyedihkan mati dalam alunan seruling.>"
  },
  AvgDialog_23360_Content_75 = {
    Text = "<RedItalic:Sekarang aku perintahkan kau——>"
  },
  AvgDialog_23360_Content_76 = {
    Text = "<Red:Buka matamu.>"
  },
  AvgDialog_23360_Content_8 = {
    Text = [[
Ancaman?
Kamu mengerutkan dahi, baru hendak menolaknya, tetapi kamu menyadari detail lain.]]
  },
  AvgDialog_23360_Content_9 = {
    Text = "Tersembunyi di balik godaan ringannya, adalah pupil mata yang terus menyempit, serta buku-buku jari yang sedikit memutih."
  },
  AvgDialog_23361_Content_1 = {Text = "Lagu Minum"},
  AvgDialog_23361_Content_10 = {
    Text = "Aah! Ka-kamu siapa? Ini kotak VIP pribadi milik Nyonya Soreil!"
  },
  AvgDialog_23361_Content_11 = {
    Text = "Karen memerintahkanmu untuk segera pergi dari sini, jangan mengganggu kesenangan Nyonya…… <Big:Aduh!>"
  },
  AvgDialog_23361_Content_12 = {
    Text = "Kau mendorong pelayan yang cerewet itu dan berjalan menuju seorang wanita berpakaian mewah."
  },
  AvgDialog_23361_Content_13 = {
    Text = "Ia dikelilingi sutra halus dan perhiasan, bak sekuntum mawar yang mekar sempurna, berkilauan dengan pesona memukau di bawah cahaya lampu."
  },
  AvgDialog_23361_Content_14 = {
    Text = "Kilauan yang rapuh, yang membuat orang tak tahan ingin meremukkannya dengan tangan sendiri."
  },
  AvgDialog_23361_Content_16 = {
    Text = "Sekarang bukan waktunya mengagumi kecantikan, kita hanya punya waktu kurang dari setengah jam, %player%."
  },
  AvgDialog_23361_Content_17 = {
    Text = "Hah? Aah……!"
  },
  AvgDialog_23361_Content_18 = {
    Text = "Selamat malam, Nyonya Soreil. Departemen Investigasi @2 Kepolisian Londinium, %player%."
  },
  AvgDialog_23361_Content_19 = {
    Text = "Departemen Investigasi @2……?"
  },
  AvgDialog_23361_Content_2 = {
    Text = "Para hadirin sekalian, selamat malam."
  },
  AvgDialog_23361_Content_20 = {
    Text = "Jangan coba-coba membodohiku dengan itu. Semua orang di kalangan ini tahu, Departemen Investigasi @2 hanyalah kedok yang digunakan Misage untuk bernaung di bawah kepolisian."
  },
  AvgDialog_23361_Content_21 = {
    Text = "Tapi wajahmu terlihat asing…… Anak baru yang direkrut Misage?"
  },
  AvgDialog_23361_Content_22 = {
    Text = "Misage lagi, setiap kali kalian menemui Nyonya pasti tidak ada kabar baik! Kalau bukan soal orang mati ya bencana, atau pinjam uang……"
  },
  AvgDialog_23361_Content_23 = {
    Text = "Soreil sedikit mengangkat bulu matanya, melirik Karen dengan tampak acuh tak acuh."
  },
  AvgDialog_23361_Content_24 = {
    Text = "Karen, tempat ini bukan sembarang orang bisa masuk. {Male=dia,Female=dia} bisa masuk ke sini, ada hubungannya denganmu?"
  },
  AvgDialog_23361_Content_25 = {
    Text = "Ha-hah? Nyonya, apa maksud Anda! Kesetiaan Karen sama murninya seperti batu rubi <Blue:Cameo> di mahkota Anda!"
  },
  AvgDialog_23361_Content_26 = {
    Text = "<SmallShake:Tentu saja, tolong jangan salah paham, ucapan ini sama sekali tidak bermaksud mengincarnya……>"
  },
  AvgDialog_23361_Content_27 = {
    Text = "Pokoknya Nyonya, biar Karen gali dan tunjukkan sekarang juga — sebuah hati yang setia!"
  },
  AvgDialog_23361_Content_28 = {
    Text = "Sst…… Karen. Satu kata lagi, kuhukum kau satu Leo Fang."
  },
  AvgDialog_23361_Content_29 = {
    Text = "Dengan nada lembut, ia memberikan perintah yang tak terbantahkan kepada pelayannya."
  },
  AvgDialog_23361_Content_3 = {
    Text = "Kisah yang akan kuceritakan malam ini terjadi di Lumiterra yang terkenal dengan kabut tebalnya."
  },
  AvgDialog_23361_Content_30 = {
    Text = "Apa?! Satu…… <Small:Wuaah!>"
  },
  AvgDialog_23361_Content_31 = {
    Text = "Karen terlambat menyadarinya dan buru-buru menutup mulutnya, tak berani mengucapkan sepatah kata pun lagi."
  },
  AvgDialog_23361_Content_32 = {
    Text = "Soreil menyesap sampanye-nya perlahan, mata merah mudanya menatapmu dengan penuh pertimbangan."
  },
  AvgDialog_23361_Content_33 = {
    Text = "Sebentar lagi lagu favoritku akan dimainkan, aku tidak ingin melewatkannya. Jadi……"
  },
  AvgDialog_23361_Content_34 = {
    Text = "Kuberi kau waktu satu menit. Katakan, apa maumu?"
  },
  AvgDialog_23361_Content_35 = {
    Text = "Pukul 8.40, masih ada 20 menit lagi."
  },
  AvgDialog_23361_Content_36 = {
    Text = [[
Baik.
Nyonya Soreil, silakan ikut saya meninggalkan tempat ini.]]
  },
  AvgDialog_23361_Content_37 = {
    Text = "<Red:Ada yang ingin membunuhmu.>"
  },
  AvgDialog_23361_Content_38 = {Text = "?!"},
  AvgDialog_23361_Content_39 = {
    Text = "Sementara mereka berbicara, cairan hitam terus merembes keluar dari lantai dan langit-langit balkon, lalu mengental menjadi gumpalan yang bergerak-gerak."
  },
  AvgDialog_23361_Content_4 = {
    Text = "Tahun @1, seorang gadis desa naik kereta kuda datang ke tempat ini, dan mengubahnya menjadi kota yang dipenuhi mawar bermekaran."
  },
  AvgDialog_23361_Content_40 = {Text = "Uuu……"},
  AvgDialog_23361_Content_41 = {
    Text = "<Change>Auuu——!!"
  },
  AvgDialog_23361_Content_5 = {
    Text = "Bunga-bunga indah terus tumbuh di sudut-sudut kota, menjadi bahan sempurna yang melahirkan berbagai kisah."
  },
  AvgDialog_23361_Content_6 = {
    Text = "Cinta, nafsu, kebencian. Tentu saja, tentu saja…… dan juga yang paling kita berdua sukai……"
  },
  AvgDialog_23361_Content_7 = {
    Text = "<Red:Pembunuhan.>"
  },
  AvgDialog_23361_Content_8 = {
    Text = "Selanjutnya, silakan nikmati dengan tenang——"
  },
  AvgDialog_23361_Content_9 = {
    Text = "Kau menyibak tirai merah gelap di hadapanmu."
  },
  AvgDialog_23362_Content_1 = {
    Text = "La Traviata"
  },
  AvgDialog_23362_Content_10 = {
    Text = "Kamu punya hak untuk menolak. Biar orang-orang di atas itu aku yang urus."
  },
  AvgDialog_23362_Content_100 = {
    Text = "Lalu, Anda memanfaatkan kebangkitan kedua untuk hidup kembali secara megah di depan publik, demi membersihkan kecurigaan terhadap diri Anda semaksimal mungkin."
  },
  AvgDialog_23362_Content_101 = {
    Text = "Lagipula, tidak ada orang yang cukup gila untuk menganggap orang mati sebagai pelakunya."
  },
  AvgDialog_23362_Content_102 = {
    Text = "Apakah saya benar, Nyonya Soreil?"
  },
  AvgDialog_23362_Content_103 = {
    Text = "Hehe…… penalaranmu cukup menggemaskan. Lalu bagaimana kau menjelaskan bayangan hitam itu?"
  },
  AvgDialog_23362_Content_104 = {
    Text = "Bayangan itu membunuh orang di depan banyak saksi. Bagaimana kau bisa membuktikan hubunganku dengannya?"
  },
  AvgDialog_23362_Content_105 = {Text = "Bau."},
  AvgDialog_23362_Content_106 = {
    Text = "Terakhir kali kau menerjang ke arahku, aku menciumnya. Kalian berdua memiliki bau yang sama……\n<Red:Bau mawar yang membusuk>."
  },
  AvgDialog_23362_Content_107 = {
    Text = "Bayangan itu sebenarnya semacam klon dirimu, bukan?"
  },
  AvgDialog_23362_Content_109 = {
    Text = "Tidak salah lagi, kau memang Penjaga Rahasia. Penciumanmu sangat tajam."
  },
  AvgDialog_23362_Content_11 = {
    Text = "Orang-orang di atas?"
  },
  AvgDialog_23362_Content_110 = {
    Text = "Soreil melepas sarung tangan merah di tangan kanannya, dan bau busuk yang menyengat langsung menyebar."
  },
  AvgDialog_23362_Content_111 = {
    Text = "Di balik goresan dan bekas luka yang saling bersilangan dengan mengerikan, huruf-huruf merah gelap samar-samar terlihat."
  },
  AvgDialog_23362_Content_112 = {Text = "<Red:\"N\">"},
  AvgDialog_23362_Content_113 = {
    Text = "Soreil dengan santai mendekatkan tangannya ke bawah hidung, lalu mengendusnya pelan."
  },
  AvgDialog_23362_Content_114 = {
    Text = "Kau lihat? Bekas luka di punggung tangan ini. Selama bekas luka ini masih ada, kontrakku dengan <Yellow:Dia> akan terus berlaku."
  },
  AvgDialog_23362_Content_115 = {
    Text = "Aku tetap harus mengikuti perintah-Nya untuk terus memicu perselisihan dan menciptakan kekacauan… Para bangsawan yang tewas itu adalah persembahan yang kukurbankan untuk-Nya."
  },
  AvgDialog_23362_Content_116 = {
    Text = "Tapi aku sudah lama muak. Manusia dan sebagian besar Awakened secara naluriah mendambakan keteraturan. Hanya orang gila yang bisa menikmati kekacauan tanpa akhir."
  },
  AvgDialog_23362_Content_117 = {
    Text = "Bayaran untuk membatalkan kontrak ini juga sederhana: <Red:Kematian>."
  },
  AvgDialog_23362_Content_118 = {
    Text = "…Jadi ini tujuan akhirmu yang sebenarnya."
  },
  AvgDialog_23362_Content_119 = {
    Text = [[
Ya. Para bangsawan itu, termasuk ayahku, hanyalah hidangan penutup tambahan.
Menyingkirkan mereka tidak memerlukan pengorbanan nyawa.]]
  },
  AvgDialog_23362_Content_120 = {
    Text = "Dia tidak pernah menampakkan diri secara langsung. Bahkan, sudah lama Dia tidak merespons panggilanku."
  },
  AvgDialog_23362_Content_121 = {
    Text = "Ada banyak sekali malam di mana aku bersujud berlutut, menangis memohon agar Dia membatalkan kontrak ini."
  },
  AvgDialog_23362_Content_122 = {
    Text = "Namun aku tidak mendengar apa pun, tidak melihat apa pun. Yang menjawabku hanyalah kesunyian bagai kematian."
  },
  AvgDialog_23362_Content_123 = {
    Text = "Karena itu aku tidak mau menunggu lagi. Kali ini, aku akan memutuskan kontrak ini dengan tanganku sendiri."
  },
  AvgDialog_23362_Content_124 = {
    Text = "…Meskipun harus membayarnya dengan kematian."
  },
  AvgDialog_23362_Content_13 = {
    Text = "Maaf, itu bukan sesuatu yang bisa kamu ketahui sekarang."
  },
  AvgDialog_23362_Content_14 = {
    Text = "Tidak apa-apa, Nona Dor."
  },
  AvgDialog_23362_Content_15 = {
    Text = "Saat ini aku masih punya beberapa kecurigaan dan dugaan. Kalau bisa masuk ke Mystic Realm untuk memverifikasinya, itu akan sangat bagus."
  },
  AvgDialog_23362_Content_16 = {
    Text = "Doer mengangguk."
  },
  AvgDialog_23362_Content_17 = {
    Text = "Pedagang informasi yang kalian temui di Mystic Realm, masih ingat? Kami mengirim orang untuk menyelidiki pemasoknya, dan tak disangka kami mendapat kejutan besar."
  },
  AvgDialog_23362_Content_18 = {
    Text = "Juga data identitas dan jaringan hubungan para bangsawan yang tewas itu……"
  },
  AvgDialog_23362_Content_19 = {
    Text = "Ini laporan investigasi yang baru dikirim dari kepolisian. Buka dan lihatlah."
  },
  AvgDialog_23362_Content_2 = {
    Text = "Ruang Medis Misage"
  },
  AvgDialog_23362_Content_20 = {
    Text = "Kamu menerima laporan investigasi itu dan mulai membaliknya halaman demi halaman."
  },
  AvgDialog_23362_Content_21 = {Text = "?!"},
  AvgDialog_23362_Content_22 = {
    Text = "Ternyata memang begitu……"
  },
  AvgDialog_23362_Content_23 = {
    Text = "Apa yang perlu kulakukan di dalam sana?"
  },
  AvgDialog_23362_Content_24 = {
    Text = "Dor menyerahkan sebuah amplop dokumen tebal kepadamu."
  },
  AvgDialog_23362_Content_25 = {
    Text = "<Yellow:Sederhana saja, sebuah negosiasi.>"
  },
  AvgDialog_23362_Content_26 = {
    Text = [[
Mystic Realm Buatan Ketiga: Teater Covent
Hari pertunjukan "Nama Mawar"]]
  },
  AvgDialog_23362_Content_27 = {
    Text = "Nyanyian yang indah bagaikan Arus mengapung yang tak putus-putusnya, mengalir perlahan di dalam teater."
  },
  AvgDialog_23362_Content_28 = {
    Text = "Para penonton di bawah panggung tampak terkagum, tubuh mereka berayun lembut mengikuti irama musik, sudah lama tenggelam dalam mimpi yang dirajut oleh nada-nada."
  },
  AvgDialog_23362_Content_29 = {
    Text = "Ngomong-ngomong, pertunjukan ini dulunya punya nama lain — \"Kematian Mawar\"."
  },
  AvgDialog_23362_Content_3 = {
    Text = "Kudengar perkembangan di sisi Ramona berjalan sangat lancar. Bagaimana denganmu, bagaimana perasaanmu sekarang?"
  },
  AvgDialog_23362_Content_30 = {
    Text = "Pemeran utamanya adalah seorang gadis desa yang berjuang sendirian di Cité. Selain wajahnya yang muda dan cantik, dia tidak punya apa-apa."
  },
  AvgDialog_23362_Content_31 = {
    Text = "Sama seperti diriku dulu."
  },
  AvgDialog_23362_Content_32 = {
    Text = "Nyonya adalah seorang putri yang mengasingkan diri di negeri asing, bagaimana mungkin gadis desa bisa dibandingkan dengan Anda!"
  },
  AvgDialog_23362_Content_33 = {
    Text = "Hehe…… Yang disebut putri dari negeri asing itu hanyalah kedok palsu belaka. Aku ini asli orang desa dari Constance."
  },
  AvgDialog_23362_Content_34 = {
    Text = "Ah……<Big:Aah!>"
  },
  AvgDialog_23362_Content_35 = {
    Text = "<Gray:Rahasia sebesar ini, Nyonya begitu saja memberitahuku!>"
  },
  AvgDialog_23362_Content_36 = {
    Text = "<Gray:Jangan-jangan karena aku memberikan undangan itu kepada si rambut keriting, dan Nyonya mengetahuinya, lalu ingin membunuhku untuk membungkam……>"
  },
  AvgDialog_23362_Content_37 = {
    Text = "\"Kematian Mawar\" adalah pertunjukan favoritku sewaktu kecil."
  },
  AvgDialog_23362_Content_38 = {
    Text = "Mengunjungi teman, jalan-jalan untuk menyegarkan pikiran saat sakit, keluar berbelanja……"
  },
  AvgDialog_23362_Content_39 = {
    Text = "Aku pernah mencari banyak alasan, hanya agar bisa berdiri di luar teater dan diam-diam mendengarkan selama lima menit."
  },
  AvgDialog_23362_Content_4 = {
    Text = "Rasanya jauh lebih baik."
  },
  AvgDialog_23362_Content_40 = {
    Text = "Karena aku terlalu sibuk. Piano, sulaman, dan juga tata krama……\nSemua keterampilan yang bisa menyenangkan kaum bangsawan harus kupelajari."
  },
  AvgDialog_23362_Content_41 = {
    Text = "Sikap dan tata krama Nyonya bahkan membuat putri kerajaan pun kalah! Bukankah ini seperti pepatah yang bilang, eh, burung yang bangun pagi mendapat cacing……"
  },
  AvgDialog_23362_Content_42 = {
    Text = "Ah, bukan, maksudnya kesempatan hanya datang bagi mereka yang siap!"
  },
  AvgDialog_23362_Content_43 = {
    Text = "<Gray:Aku ini memang bodoh. Malam ini mungkin adalah ajalku, hehe……>"
  },
  AvgDialog_23362_Content_44 = {
    Text = "Kemudian aku mendengarkan opera itu sampai selesai secara terputus-putus, tapi aku tidak suka endingnya."
  },
  AvgDialog_23362_Content_45 = {
    Text = "Gadis desa itu berhasil menyusup ke kalangan atas Cité, tetapi jatuh cinta pada pemuda bangsawan yang tidak becus, dan akhirnya mati karenanya."
  },
  AvgDialog_23362_Content_46 = {
    Text = "Akhir yang, yang menyedihkan sekali…… Karen juga tidak suka. Karen benci tragedi!"
  },
  AvgDialog_23362_Content_47 = {
    Text = "Ya, tidak ada yang suka tragedi."
  },
  AvgDialog_23362_Content_48 = {
    Text = "Setelah berinvestasi di teater, hal pertama yang kulakukan adalah mengubah nama dan akhir dari \"Kematian Mawar\"."
  },
  AvgDialog_23362_Content_49 = {
    Text = [[
Akhirnya aku bisa melakukan semua hal yang ingin kulakukan sesuka hati.
Atau lebih tepatnya, aku <Yellow:mengira> aku akhirnya bisa melakukan segalanya sesuka hati.]]
  },
  AvgDialog_23362_Content_5 = {
    Text = "Syukurlah. Sepertinya teknologi medis yang selama ini diotak-atik Winkel memang ada gunanya juga."
  },
  AvgDialog_23362_Content_50 = {
    Text = "Soreil menatap dengan pandangan menerawang ke cairan keemasan di dalam gelas, serta gelembung-gelembung yang naik perlahan dari dasar gelas."
  },
  AvgDialog_23362_Content_51 = {
    Text = "Kekayaan, ketenaran, pengetahuan… Orang-orang mengejarnya karena begitu memilikinya, mereka akan memiliki kebebasan."
  },
  AvgDialog_23362_Content_52 = {
    Text = "Kebebasan untuk mengubah akhir opera yang tidak disukai, atau kebebasan untuk membeli batu rubi cameo yang diinginkan."
  },
  AvgDialog_23362_Content_53 = {
    Text = "Manusia memang makhluk sesederhana itu."
  },
  AvgDialog_23362_Content_54 = {
    Text = "Nyonya, kenapa tiba-tiba membicarakan hal seperti ini, rasanya agak berat, haha…"
  },
  AvgDialog_23362_Content_55 = {
    Text = "Kamu selalu anak yang cerdas. Bahkan tanpaku, kamu pasti bisa hidup dengan baik."
  },
  AvgDialog_23362_Content_56 = {
    Text = "Soreil dengan lembut mengelus kepala Garen."
  },
  AvgDialog_23362_Content_57 = {
    Text = "Nyo, Nyonya…"
  },
  AvgDialog_23362_Content_58 = {
    Text = "Anda berkata begitu, apakah Anda ingin meninggalkan Garen…"
  },
  AvgDialog_23362_Content_59 = {
    Text = "Tidak ada yang akan meninggalkanmu, Garen. Kamu selalu bebas."
  },
  AvgDialog_23362_Content_6 = {
    Text = "Selanjutnya aku tidak akan berbelit-belit lagi denganmu. %player%, kamu mungkin harus bersiap untuk memasuki Mystic Realm buatan sekali lagi."
  },
  AvgDialog_23362_Content_60 = {Text = "Sss……"},
  AvgDialog_23362_Content_61 = {
    Text = "Dari sudut ruangan, perlahan muncul bayangan hitam yang merayap tanpa suara menuju belakang Soreil."
  },
  AvgDialog_23362_Content_62 = {
    Text = "Soreil dengan penuh perhatian mendengarkan nyanyian merdu dari bawah panggung, seolah sama sekali tidak menyadari pergerakan aneh di belakangnya."
  },
  AvgDialog_23362_Content_63 = {Text = "Sss……"},
  AvgDialog_23362_Content_64 = {
    Text = "Suara gemerisik perlahan melemah, namun bayangan hitam itu sudah tidak bergerak lagi."
  },
  AvgDialog_23362_Content_65 = {Text = "Eh…?"},
  AvgDialog_23362_Content_66 = {
    Text = "Soreil berbalik dengan terkejut."
  },
  AvgDialog_23362_Content_67 = {
    Text = "Selamat malam, Nyonya Soreil. Sepertinya Anda kehilangan sesuatu?"
  },
  AvgDialog_23362_Content_68 = {
    Text = "<Change>Nyonya…"
  },
  AvgDialog_23362_Content_69 = {
    Text = "Bayangan hitam itu di tanganmu seolah berubah menjadi selembar kain lusuh, dilemparkan dengan lemas di hadapan Soreil."
  },
  AvgDialog_23362_Content_7 = {
    Text = "Apa……?!"
  },
  AvgDialog_23362_Content_70 = {
    Text = "Menangkap makhluk ini cukup merepotkan. Berkat pertarungan terakhir kali, akhirnya aku berhasil memahami pola bertarungnya."
  },
  AvgDialog_23362_Content_71 = {
    Text = "<Red:Kembali lagi……>"
  },
  AvgDialog_23362_Content_72 = {
    Text = "Soreil sama sekali tidak melirik bayangan hitam di kakinya. Wajahnya tegang, menatapmu dengan tajam."
  },
  AvgDialog_23362_Content_73 = {
    Text = "Kau lagi…… Kenapa kembali, pelajaran dariDomain terakhir belum cukup bagimu?"
  },
  AvgDialog_23362_Content_74 = {
    Text = "<Gray:Tebakan Nona Dor tidak salah, dia memang sudah menyadari bahwa dirinya berada di dalamDomain.>"
  },
  AvgDialog_23362_Content_75 = {
    Text = "Aku hanya ingin datang untuk memastikan beberapa hal."
  },
  AvgDialog_23362_Content_76 = {
    Text = "Kau menyingkap topeng dari wajah bayangan hitam itu."
  },
  AvgDialog_23362_Content_77 = {
    Text = "Detik berikutnya, bayangan hitam itu menyebar seperti tinta yang larut dalam air."
  },
  AvgDialog_23362_Content_78 = {
    Text = "Hanya menyisakan setangkai mawar merah tua yang terbaring diam di antara kau dan Soreil."
  },
  AvgDialog_23362_Content_79 = {
    Text = "Telur-telur putih di kelopak bunga bergerak-gerak lembut, perlahan merayap ke ujung rok Soreil, menyatu dengannya."
  },
  AvgDialog_23362_Content_8 = {
    Text = "Dor mengerutkan alis, tanpa sadar meraba perangkat kaca yang menyimpan otak segar di dalamnya."
  },
  AvgDialog_23362_Content_81 = {
    Text = "Waktu bermain sudah berakhir, Nyonya Soreil."
  },
  AvgDialog_23362_Content_82 = {
    Text = "<Yellow:Catatan Investigasi Domain Buatan Ketiga>\n\n■Nomor Domain: M-B04-003\n■Waktu Pengaturan: @1 Juni Tahun 315 Aluvi, 8:00-9:00pm (hari kematian Sorel).\n■Lokasi Pengaturan: Teater Covent"
  },
  AvgDialog_23362_Content_83 = {
    Text = "■Pemilik Domain: Sorel·@2.\n■Penyusup Domain: %player%.\n\n■Tujuan Penyusupan: <Yellow:Membongkar konspirasi Sorel, dan melakukan negosiasi \"yang diperlukan\" dengannya.>"
  },
  AvgDialog_23362_Content_84 = {
    Text = "Kenapa kau lagi! Nyonya Soreil, biar Karen yang mengurus orang ini……"
  },
  AvgDialog_23362_Content_85 = {
    Text = "Soreil menggelengkan kepalanya."
  },
  AvgDialog_23362_Content_86 = {
    Text = "Mundurlah, Karen."
  },
  AvgDialog_23362_Content_87 = {
    Text = "%player%, kau menerobos masuk begitu saja, hanya untuk menunjukkan ini padaku?"
  },
  AvgDialog_23362_Content_88 = {
    Text = "Nyonya Soreil yang selalu menyukai kemewahan, justru pada hari kematiannya hanya membawa pelayan pribadinya untuk menonton pertunjukan."
  },
  AvgDialog_23362_Content_89 = {
    Text = "Apa-apaan itu, memangnya salah kalau Nyonya ingin menikmati musik dengan tenang bersamaku!"
  },
  AvgDialog_23362_Content_9 = {
    Text = "Ini bukan perintah dariku. Kalau bisa, aku ingin kamu berbaring dengan tenang di sini sampai hari kamu benar-benar pulih."
  },
  AvgDialog_23362_Content_90 = {
    Text = "Jangan terburu-buru, Nona Karen. Masih ingat para pedagang di Lincoln High Street yang menjual informasi pergerakan Soreil?"
  },
  AvgDialog_23362_Content_91 = {
    Text = "Kami sudah menyelidikinya, <Yellow:informasi yang mereka miliki justru disebarkan olehmu.>"
  },
  AvgDialog_23362_Content_92 = {
    Text = "Menjual informasi majikan adalah kejahatan berat. Aku menduga kau mendapat instruksi dari tuanmu."
  },
  AvgDialog_23362_Content_93 = {Text = "!!"},
  AvgDialog_23362_Content_94 = {
    Text = "<Shake:O-omong kosong……>Karlen sendiri yang ingin mencari uang tambahan, ini tidak ada hubungannya dengan Nyonya Soreil!"
  },
  AvgDialog_23362_Content_95 = {
    Text = "Jangan berani-berani memfitnah nyonya kami seperti itu!"
  },
  AvgDialog_23362_Content_96 = {
    Text = "Kau tidak menghiraukan protes Karlen, dan malah menoleh ke arah Nyonya Soreil."
  },
  AvgDialog_23362_Content_97 = {
    Text = "Dan para bangsawan yang tewas itu, hampir semuanya pernah berkonflik dengan Anda dalam hal pandangan politik maupun bisnis.\nBolehkah saya berasumsi secara logis……"
  },
  AvgDialog_23362_Content_98 = {
    Text = "<Yellow:Anda mendalangi kematian Anda sendiri, dan memanfaatkannya untuk menyingkirkan semua penghalang, termasuk ayah Anda.>"
  },
  AvgDialog_23362_Content_99 = {
    Text = [[
Mengumumkan secara terbuka bahwa Tuan Lambert adalah satu-satunya penerima warisan, hanyalah untuk memancingnya bertindak nekat.
Bahkan jika dia akhirnya gagal, senjata dan motifnya sudah cukup untuk menarik perhatian polisi.]]
  },
  AvgDialog_23363_Content_1 = {
    Text = "Topeng dan Harmoni"
  },
  AvgDialog_23363_Content_10 = {
    Text = "Diterima. Lantai dua saat ini semuanya normal."
  },
  AvgDialog_23363_Content_11 = {
    Text = "Masih dua puluh menit sebelum pertunjukan dimulai…… tidak ada hal mendesak, aku pergi menemui Nyonya Soreil dulu."
  },
  AvgDialog_23363_Content_12 = {
    Text = "Hmm, berhati-hatilah dalam segala hal. Semoga Kunci Perak menuntun jalanmu."
  },
  AvgDialog_23363_Content_13 = {
    Text = "Pertunjukan yang sama, koridor yang sama."
  },
  AvgDialog_23363_Content_14 = {
    Text = "Dengan langkah yang sudah terbiasa, kau menyibak tirai kotak VIP mewah itu."
  },
  AvgDialog_23363_Content_15 = {
    Text = "Diiringi aroma anggur yang pekat dan dentingan perhiasan yang saling beradu, sesuatu yang lembut dan hangat tiba-tiba menabrak pelukanmu."
  },
  AvgDialog_23363_Content_16 = {
    Text = "Akhirnya kau datang juga, aku sudah menunggumu lama sekali……"
  },
  AvgDialog_23363_Content_17 = {
    Text = "Soreil memelukmu dengan mesra, napasnya yang hangat membuat wajahmu merah padam."
  },
  AvgDialog_23363_Content_18 = {
    Text = "<Shake:Tu-tunggu, menungguku?>"
  },
  AvgDialog_23363_Content_19 = {
    Text = "Iya, bukankah kita sudah janji untuk berdiskusi…… Eh, kau bukan Nyonya Bernard?"
  },
  AvgDialog_23363_Content_2 = {
    Text = [[
Domain buatan kedua: Teater Covent
Hari kematian Sorel]]
  },
  AvgDialog_23363_Content_20 = {
    Text = "Ehem. Kepolisian Londinium, @2Divisi Investigasi, %player%."
  },
  AvgDialog_23363_Content_21 = {
    Text = [[
Jangan coba-coba membodohiku dengan itu.
Semua orang di kalangan ini tahu, @2Divisi Investigasi hanyalah kedok yang dipasang Messager di kepolisian~]]
  },
  AvgDialog_23363_Content_22 = {
    Text = "Aduh, apa aku baru saja membocorkan rahasia kalian…… Maaf, sepertinya aku minum terlalu banyak."
  },
  AvgDialog_23363_Content_23 = {
    Text = "Kata Soreil sambil menyentuh pipinya yang merona merah."
  },
  AvgDialog_23363_Content_24 = {
    Text = "<Gray:Kenapa dia minum alkohol……? Terakhir kali dia jelas-jelas sangat sadar.>"
  },
  AvgDialog_23363_Content_25 = {
    Text = "Ternyata kau! Nyonya, orang ini adalah perampok, {Male=dia,Female=dia}merampas undangan milik Karen!"
  },
  AvgDialog_23363_Content_26 = {
    Text = "Bukankah semua undangan sudah dikirimkan? Kenapa masih ada yang tersisa?"
  },
  AvgDialog_23363_Content_27 = {Text = "!!"},
  AvgDialog_23363_Content_28 = {
    Text = "<Shake:Eh, sebenarnya…… pada kenyataannya, ini……>"
  },
  AvgDialog_23363_Content_29 = {
    Text = "Karen mulai tergagap, seperti mesin yang macet."
  },
  AvgDialog_23363_Content_3 = {
    Text = "<Yellow:Catatan Investigasi Domain Buatan Kedua II>\n\n■Nomor Domain: M-B04-002\n■Waktu Pengaturan: @1 Juni Tahun 315 Aluvi, 8:00-9:00pm (hari kematian Sorel).\n■Lokasi Pengaturan: Teater Covent"
  },
  AvgDialog_23363_Content_30 = {
    Text = [[
Maaf membuatmu melihat hal memalukan, %player%{Male=tuan,Female=nyonya}.
Pelayan wanitaku ini tidak punya niat buruk, hanya sedikit bodoh saja.]]
  },
  AvgDialog_23363_Content_31 = {
    Text = "Hari ini adalah hari yang patut dirayakan, teater yang kusahamkan menampilkan pertunjukan favoritku."
  },
  AvgDialog_23363_Content_32 = {
    Text = "Mengirim orang datang di saat seperti ini, apakah para kolot di Messager itu sengaja?"
  },
  AvgDialog_23363_Content_33 = {
    Text = "Maaf mengganggu, Nyonya Soreil. Kami menerima informasi bahwa seseorang akan mencoba membunuh Anda malam ini."
  },
  AvgDialog_23363_Content_34 = {
    Text = "Di sini sangat tidak aman, silakan ikut saya pergi."
  },
  AvgDialog_23363_Content_35 = {
    Text = "Aku menolak."
  },
  AvgDialog_23363_Content_36 = {Text = "...?"},
  AvgDialog_23363_Content_37 = {
    Text = "Soreil menyesap sedikit sampanye dari gelasnya, bulu mata panjangnya berkedip lembut, mengedipkan mata padamu dengan ramah."
  },
  AvgDialog_23363_Content_38 = {
    Text = "Kau pasti yang mereka kirim untuk melindungiku, kan? Karena aku sudah punya seorang ksatria kecil, kenapa harus pergi?"
  },
  AvgDialog_23363_Content_39 = {
    Text = "Sayangnya, kenyataan tidak seindah buku bergambar. Seorang ksatria yang bertarung sendirian tidak bisa menyelamatkan sang putri, hanya bisa membawanya melarikan diri."
  },
  AvgDialog_23363_Content_4 = {
    Text = "■Pemilik Domain: Sorel·@2\n■Penyusup Domain: %player%, Ramona\n\n■Tujuan Penyusupan: <Yellow:Berdasarkan hasil penyusupan Domain pertama, mencari sumber fluktuasi Perak di lantai satu>"
  },
  AvgDialog_23363_Content_40 = {
    Text = "Melarikan diri… ke mana? Ke tempat yang tidak bisa ditemukan orang jahat?"
  },
  AvgDialog_23363_Content_41 = {
    Text = "Bisa dibilang begitu…"
  },
  AvgDialog_23363_Content_42 = {
    Text = "Pfft. Di dunia ini ternyata masih ada tempat yang tidak bisa ditemukan orang jahat? Aku belum pernah melihatnya."
  },
  AvgDialog_23363_Content_43 = {
    Text = "Arah jam sepuluh lewat tiga puluh, ada seorang pria yang diam-diam naik ke atas. Cepat ke pintu keluar sebelah kanan, kita hadang dia bersama-sama."
  },
  AvgDialog_23363_Content_44 = {Text = "?!"},
  AvgDialog_23363_Content_45 = {
    Text = "Maaf, Nyonya Soreil. Saya keluar sebentar, akan segera kembali."
  },
  AvgDialog_23363_Content_5 = {
    Text = "Bagus, kali ini kita datang dengan persiapan matang, berhasil menghindari air mandi Karen, dan merebut dua undangan dari tangannya."
  },
  AvgDialog_23363_Content_6 = {
    Text = "Sungguh memuaskan!"
  },
  AvgDialog_23363_Content_7 = {
    Text = "Harus kuakui, kelincahanmu dalam menghindar memberiku kesan yang mendalam."
  },
  AvgDialog_23363_Content_8 = {
    Text = "Ehm, mari kembali ke topik utama. Ada pergerakan mencurigakan di lantai satu?"
  },
  AvgDialog_23363_Content_9 = {
    Text = "Untuk sementara aman. Saat memasuki Domain terakhir kali, di arah pukul sepuluh pernah muncul tanda aktivitas Silver Core yang lemah, kali ini aku akan lebih memperhatikannya."
  },
  AvgDialog_23364_Content_1 = {
    Text = [[
Dimensi Buatan Kedua: Teater Covent
Koridor Lantai Dua]]
  },
  AvgDialog_23364_Content_10 = {
    Text = "Bagus. Operasi penangkapan kedua di Ruang Buatan, dimulai sekarang!"
  },
  AvgDialog_23364_Content_11 = {
    Text = "Kamu meregangkan tubuh sejenak, lalu segera melesat menuju pria itu."
  },
  AvgDialog_23364_Content_2 = {
    Text = "Hati-hati. Dia ada di tikungan depan sana."
  },
  AvgDialog_23364_Content_3 = {
    Text = "<Small:Sst… jangan bicara. Aku melihatnya.>"
  },
  AvgDialog_23364_Content_4 = {
    Text = "Pria itu bersembunyi tidak jauh dari kotak penonton, hampir menyatu dengan bayangan di belakangnya. Dari napasnya yang berat dan lambat, tampaknya dia seorang pria tua."
  },
  AvgDialog_23364_Content_5 = {
    Text = "Begitu kau selesai berbicara, bayangan itu bergerak nyaris tak terlihat sesaat."
  },
  AvgDialog_23364_Content_6 = {
    Text = "Siapa di sana?!"
  },
  AvgDialog_23364_Content_7 = {
    Text = "Kau dan dia terpisah setidaknya 30 kaki, tak disangka kau sudah ketahuan."
  },
  AvgDialog_23364_Content_8 = {
    Text = "Cukup tajam juga, jadi aku tidak perlu repot menyapa. Ramona, sudah siap?"
  },
  AvgDialog_23364_Content_9 = {
    Text = "Siap bertempur kapan saja."
  },
  AvgDialog_23365_Content_1 = {
    Text = "Uuh——!!"
  },
  AvgDialog_23365_Content_10 = {
    Text = "Apa itu——"
  },
  AvgDialog_23365_Content_11 = {
    Text = "Saat tersadar kembali, di depan mata sudah tak ada siapa pun."
  },
  AvgDialog_23365_Content_13 = {
    Text = "Orang ini bukan bayangan bertopeng itu, bisa jadi ini pengalihan dari musuh."
  },
  AvgDialog_23365_Content_14 = {
    Text = "Aku akan mengejarnya, kamu segera kembali ke kotak VIP Soreil dan periksa keadaannya."
  },
  AvgDialog_23365_Content_15 = {
    Text = "Mengerti, tetap jaga komunikasi setiap saat."
  },
  AvgDialog_23365_Content_16 = {
    Text = "Setelah Ramona pergi dengan tergesa, kamu memungut benda yang tadi dilemparkan pria itu."
  },
  AvgDialog_23365_Content_17 = {
    Text = "Itu adalah sebuah belati yang indah dan tajam, gagang pisaunya diukir dengan ornamen rumit nan halus, tampak sangat mahal."
  },
  AvgDialog_23365_Content_18 = {
    Text = "Jangan-jangan dia berharap bisa membunuh Nyonya Soreil dengan benda ini?"
  },
  AvgDialog_23365_Content_19 = {
    Text = "Selain itu, untuk seorang pria tua, gerakannya terlalu lincah… Penderita Erosi?"
  },
  AvgDialog_23365_Content_2 = {
    Text = "Pria tua itu dengan mudah kalian jatuhkan ke tanah. Dia segera mengangkat tangan, menutupi wajahnya rapat-rapat dengan lengan bajunya."
  },
  AvgDialog_23365_Content_20 = {
    Text = "Kalau memang penderita Erosi yang sudah bermutasi, bukan tidak mungkin dia bisa membunuh Soreil…"
  },
  AvgDialog_23365_Content_21 = {
    Text = "Kamu menggaruk kepala dengan bingung."
  },
  AvgDialog_23365_Content_23 = {
    Text = "Pertunjukan akan segera dimulai. Bagaimanapun juga, lebih baik kembali dulu dan lihat keadaannya."
  },
  AvgDialog_23365_Content_3 = {
    Text = "Bicara, siapa kamu? Kenapa kamu menyerang Nyonya Soreil?"
  },
  AvgDialog_23365_Content_4 = {
    Text = "Menginterogasiku? Heh… Memangnya kalian siapa. Katakan, siapa atasan kalian?"
  },
  AvgDialog_23365_Content_5 = {
    Text = "François atau Olivier·@2? Aku mau… uhuk uhuk, bicara dengannya."
  },
  AvgDialog_23365_Content_6 = {Text = "?!"},
  AvgDialog_23365_Content_7 = {
    Text = "Pria itu tanpa ragu menyebutkan nama dua petinggi kepolisian, nada bicaranya dipenuhi keangkuhan dan ketidakpedulian yang tak bisa ditahan."
  },
  AvgDialog_23365_Content_8 = {
    Text = "Kemudian dia tiba-tiba mengangkat tangan dan melemparkan sesuatu yang berkilau dengan keras."
  },
  AvgDialog_23366_Content_1 = {
    Text = [[
Artificial Metafield Pertama: Lincoln High Street
Hari Kematian Sorelle]]
  },
  AvgDialog_23366_Content_10 = {
    Text = "Sekadar mengingatkan, sekarang sudah pukul 6 lewat 15 malam, kita masih harus mencari cara untuk mendapatkan undangan agar bisa masuk ke gedung opera."
  },
  AvgDialog_23366_Content_11 = {
    Text = "Lebih tepatnya, undangan untuk pertunjukan perdana opera <Blue:\"The Name of the Rose\"> malam ini."
  },
  AvgDialog_23366_Content_12 = {
    Text = "Kamu melemparkan senyum penuh percaya diri kepada Ramona."
  },
  AvgDialog_23366_Content_13 = {
    Text = "Tenang saja. Aku sudah menyelidikinya terlebih dahulu, cara mendapatkan undangannya sangat mudah."
  },
  AvgDialog_23366_Content_14 = {
    Text = "Ikuti saja aku, Ramona."
  },
  AvgDialog_23366_Content_2 = {Text = "Ukh……!"},
  AvgDialog_23366_Content_3 = {
    Text = "Uhuk uhuk…"
  },
  AvgDialog_23366_Content_4 = {
    Text = "Kawasan kota yang ramai terbentang di hadapan kalian. Saat ini sudah menjelang malam, lampu-lampu jalan menyala satu per satu, menerangi papan-papan nama toko yang berjejer di sepanjang jalan."
  },
  AvgDialog_23366_Content_5 = {
    Text = "Orang-orang berlalu-lalang dengan tergesa di jalanan, suara tawa dan percakapan bercampur dengan suara kendaraan, terjalin menjadi sebuah simfoni yang riang."
  },
  AvgDialog_23366_Content_6 = {
    Text = "Sudah lama tidak ke kawasan barat, ternyata masih sama seperti dulu!"
  },
  AvgDialog_23366_Content_7 = {
    Text = "Menurutku kita bisa menyusuri Lincoln Street terus ke bawah, di sana ada toko kue manis yang punya kue-kue kecil paling enak di seluruh dunia!"
  },
  AvgDialog_23366_Content_8 = {
    Text = "Entah bagaimana rasanya kue kecil yang dimakan di dalam Artificial Metafield ya……"
  },
  AvgDialog_23366_Content_9 = {
    Text = "Ramona mengangkat pergelangan tangannya dengan wajah tanpa ekspresi untuk melihat waktu."
  },
  AvgDialog_23367_Content_1 = {
    Text = "Penghakiman yang Jatuh"
  },
  AvgDialog_23367_Content_10 = {
    Text = [[
Hehe, orang-orang itu masih seperti biasa, selera mereka besar sekali.
Kalau aku menyetujui semuanya, bukankah usaha bertahun-tahun ini jadi sia-sia?]]
  },
  AvgDialog_23367_Content_11 = {
    Text = "Mana boleh begitu?"
  },
  AvgDialog_23367_Content_12 = {
    Text = "Tapi jika Anda menolak, Misage akan segera menghentikan Kebangkitan Kedua sesuai ketentuan tambahan dalam perjanjian, dan mengungkap semua tindakan Anda ke seluruh dunia."
  },
  AvgDialog_23367_Content_13 = {
    Text = "Sejujurnya, Anda tidak punya pilihan lain, Nyonya Soleil."
  },
  AvgDialog_23367_Content_14 = {
    Text = "Tidak punya pilihan lain? Kau masih belum cukup mengenalku, Penjaga Rahasia."
  },
  AvgDialog_23367_Content_15 = {
    Text = "Mengungkap ke seluruh dunia…… menurutmu, haruskah aku mengungkap keberadaan Erosi ke seluruh dunia, atau mengungkap keberadaan Tubuh Kebangkitan ke seluruh dunia?"
  },
  AvgDialog_23367_Content_16 = {
    Text = "Kalian pilih yang mana?"
  },
  AvgDialog_23367_Content_17 = {
    Text = "Sudut bibirnya tersenyum, namun tatapan matanya dingin membeku. Kau tahu betul bahwa kau sudah menyinggung nyonya ini."
  },
  AvgDialog_23367_Content_18 = {
    Text = "Untungnya, reaksinya ini sudah diperhitungkan oleh para petinggi itu. Kau hanya bisa memberanikan diri melontarkan kata-kata yang sudah disiapkan sebelumnya."
  },
  AvgDialog_23367_Content_19 = {
    Text = "Maaf, Nyonya Soleil. Tolong jangan anggap negosiasi ini sebagai ancaman. Ini adalah kerja sama yang saling menguntungkan, para petinggi di atas memiliki ketulusan mutlak dalam hal ini……"
  },
  AvgDialog_23367_Content_2 = {
    Text = "Kontrak… Aku mengerti sekarang.\nDia menganugerahimu kemampuan khusus, dan sebagai imbalannya, kau harus menjalankan tugas untuk-Nya."
  },
  AvgDialog_23367_Content_20 = {
    Text = "<Red:Benar-benar membosankan, mengantuk rasanya.>"
  },
  AvgDialog_23367_Content_21 = {
    Text = "Entah sejak kapan musik berhenti, seluruh gedung opera sunyi senyap bagaikan sebuah makam raksasa."
  },
  AvgDialog_23367_Content_22 = {
    Text = "Semua aktor, tamu undangan, bahkan termasuk Karen, semuanya seperti membeku di tempat, hanya menatapmu dan Soleil dengan mata yang gelap dan kosong."
  },
  AvgDialog_23367_Content_23 = {Text = "……Hah?"},
  AvgDialog_23367_Content_24 = {
    Text = "Soleil menopang dagunya sambil memandangi wajah-wajah yang kaku itu, lalu menghela napas panjang."
  },
  AvgDialog_23367_Content_25 = {
    Text = "Sejak saat kau berdiri di hadapanku lagi, aku sudah tahu akan berakhir seperti ini."
  },
  AvgDialog_23367_Content_26 = {
    Text = "Hal terburuk akhirnya terjadi……\nKau mungkin sama sekali tidak tahu tentang keberadaan yang kau undang kemari, Penjaga Rahasia."
  },
  AvgDialog_23367_Content_27 = {
    Text = "Suaranya sangat pelan saat berbicara, seolah takut mengganggu keberadaan itu."
  },
  AvgDialog_23367_Content_28 = {
    Text = "Bayangan hitam yang pernah kau lihat di Ranah Rahasia terakhir kali, seketika melintas di benakmu."
  },
  AvgDialog_23367_Content_29 = {
    Text = "Keberadaan yang kau maksud, jangan-jangan……?!"
  },
  AvgDialog_23367_Content_3 = {
    Text = "Pantas saja duplikatmu sangat mirip dengan-Nya, karena kau meminjam kekuatan-Nya."
  },
  AvgDialog_23367_Content_30 = {
    Text = "Mencoba menggunakan Misage untuk menahan langkahku, orang-orang di atas memang cerdas, tapi mereka juga punya kelalaian — mereka tidak memperhitungkan keberadaanmu."
  },
  AvgDialog_23367_Content_31 = {Text = "……Aku?"},
  AvgDialog_23367_Content_32 = {
    Text = "Dung dung. Dung dung."
  },
  AvgDialog_23367_Content_33 = {
    Text = "Dari kejauhan terdengar suara genderang yang pelan, diikuti oleh nada seruling yang halus dan monoton."
  },
  AvgDialog_23367_Content_34 = {
    Text = "Kemudian kau mendengar nyanyian."
  },
  AvgDialog_23367_Content_35 = {
    Text = "<RedItalic:Wahai pemberontak takdir.>"
  },
  AvgDialog_23367_Content_36 = {
    Text = "Sosok yang lahir dari kegelapan berdiri tegak di bawah sorotan cahaya, kabut yang mengambang di wajah-Nya bagaikan tentakel hitam pekat, mengembang perlahan mengikuti alunan seruling."
  },
  AvgDialog_23367_Content_37 = {
    Text = "Nyanyian-Nya parau dan menistakan, kau merasakan denyut nadi yang panjang di dalamnya, bagaikan pasang surut yang tak berujung."
  },
  AvgDialog_23367_Content_38 = {
    Text = "<RedItalic:Kau mekar penuh kemudaan di dalam lumpur yang membusuk, kau memanjat sulur hijau yang menjulang tinggi, kau menginjak sesama makhluk yang sama kecilnya.>"
  },
  AvgDialog_23367_Content_39 = {
    Text = "<RedItalic:Hasratmu tak berbatas, jiwamu telah lama lapuk.>"
  },
  AvgDialog_23367_Content_4 = {
    Text = "Ini bukan urusanmu, investigator kecil."
  },
  AvgDialog_23367_Content_40 = {
    Text = "<RedItalic:Di taman mawar-mu yang sakit itu, aku melihatnya. Pembantaian sunyi itu……>"
  },
  AvgDialog_23367_Content_41 = {
    Text = "<Red:Akan segera dimulai.>"
  },
  AvgDialog_23367_Content_5 = {
    Text = "Sekarang kau sudah mendapatkan kebenaran yang kau inginkan. Lalu apa? Apa yang akan kau lakukan?"
  },
  AvgDialog_23367_Content_6 = {
    Text = "Sejujurnya, memang tidak banyak yang bisa kulakukan."
  },
  AvgDialog_23367_Content_7 = {
    Text = "Aku hanyalah seseorang yang menerima perintah untuk datang bernegosiasi dengan Anda. Ini adalah ketentuan yang disusun oleh atasan. Silakan Nyonya tinjau."
  },
  AvgDialog_23367_Content_8 = {
    Text = "Kau menyerahkan dokumen yang telah disiapkan sebelumnya kepada Nyonya Soreil."
  },
  AvgDialog_23367_Content_9 = {
    Text = "Soreil dengan cepat menelusuri pasal-pasal yang tercetak rapat di atas kertas putih, sudut bibirnya terangkat membentuk senyum sinis."
  },
  AvgDialog_23368_Content_1 = {
    Text = "Jangan harap bisa kabur!!"
  },
  AvgDialog_23368_Content_10 = {
    Text = "Uwaaah——!!"
  },
  AvgDialog_23368_Content_11 = {
    Text = "Kamu ketakutan dan melempar mawar itu jauh-jauh."
  },
  AvgDialog_23368_Content_12 = {
    Text = "Di atasnya penuh telur."
  },
  AvgDialog_23368_Content_13 = {Text = "……Iya."},
  AvgDialog_23368_Content_14 = {
    Text = "Ini barang bukti penting, kamu yang ambil."
  },
  AvgDialog_23368_Content_15 = {
    Text = "Aku tidak mau."
  },
  AvgDialog_23368_Content_16 = {
    Text = "Bagus, karena kita berdua tidak mau, maka——"
  },
  AvgDialog_23368_Content_17 = {
    Text = "Ramona menoleh ke arah Dexter."
  },
  AvgDialog_23368_Content_18 = {Text = "?"},
  AvgDialog_23368_Content_19 = {
    Text = "Bukankah ada seseorang yang diam-diam menyebutku sipir penjara? Sekarang sipir memerintahkanmu, pergi ambil bunga itu."
  },
  AvgDialog_23368_Content_2 = {
    Text = "Kamu melangkah maju, mencengkeram topeng bayangan hitam itu dan menariknya dengan keras."
  },
  AvgDialog_23368_Content_20 = {
    Text = "Pernyataan resmi, bukan aku yang bilang itu. Si Nicholas yang mabuk lalu……"
  },
  AvgDialog_23368_Content_21 = {
    Text = "Tapi kamu juga tidak membantah, bukan?"
  },
  AvgDialog_23368_Content_23 = {
    Text = "Baik baik baik, aku ambil."
  },
  AvgDialog_23368_Content_24 = {
    Text = "Dexter memainkan kancing manset elegannya, menggulung lengan bajunya, lalu berjalan ke sana dengan lesu."
  },
  AvgDialog_23368_Content_25 = {
    Text = "<Gray:Senyuman yang mengerikan sekali……Lebih baik jangan sembarangan menyinggung orang ini di kemudian hari.>"
  },
  AvgDialog_23368_Content_26 = {
    Text = "Nona Dor bilang,Domain buatan Nyonya Sorrel sudah selesai dikalibrasi, kita bisa masuk lagi."
  },
  AvgDialog_23368_Content_27 = {
    Text = "Bagaimana, kali ini yakin bisa menangkap pelakunya?"
  },
  AvgDialog_23368_Content_28 = {
    Text = "Kamu mengangguk pelan."
  },
  AvgDialog_23368_Content_29 = {
    Text = "Aku mencium bau yang sangat aneh……Kurasa aku tahu cara melacaknya."
  },
  AvgDialog_23368_Content_3 = {
    Text = "Di luar dugaan, di balik topeng itu tidak ada wajah yang kamu harapkan — lebih tepatnya, tidak ada apa-apa di dalamnya."
  },
  AvgDialog_23368_Content_4 = {
    Text = "Dia lenyap bagaikan kabut yang menghilang."
  },
  AvgDialog_23368_Content_5 = {
    Text = "Eh, apa ini?"
  },
  AvgDialog_23368_Content_6 = {
    Text = "Setangkai mawar merah darah tergeletak diam di dekat kakimu."
  },
  AvgDialog_23368_Content_7 = {
    Text = "Mawar lagi? Kudengar di beberapa lokasi kejadian sebelumnya juga ditemukan setangkai mawar……"
  },
  AvgDialog_23368_Content_8 = {
    Text = "Kamu tenggelam dalam pikiran, ketika ujung jarimu tiba-tiba terasa gatal dan kebas."
  },
  AvgDialog_23368_Content_9 = {
    Text = "Saat menunduk, barulah kamu menyadari beberapa ekor belatung gemuk putih muncul dari kelopak bunga dan merayap ke tanganmu."
  },
  AvgDialog_23369_Content_1 = {
    Text = "Uuh——!!"
  },
  AvgDialog_23369_Content_10 = {
    Text = "Buka matamu lebar-lebar dan lihat air di badan kami, memangnya kamu memberi kami kesempatan untuk bicara baik-baik?"
  },
  AvgDialog_23369_Content_11 = {
    Text = "Eh…… kesalahpahaman yang tidak menyenangkan biarlah berlalu! Karena semua datang untuk berbisnis, Karen juga harus menunjukkan sikap profesional sebagai tanda hormat."
  },
  AvgDialog_23369_Content_12 = {
    Text = "Setelah berkata demikian, dia membuka telapak tangannya yang montok ke arah kalian."
  },
  AvgDialog_23369_Content_13 = {
    Text = "Satu undangan sepuluh Leofang, dua undangan dua puluh. Tidak bisa ditawar ya."
  },
  AvgDialog_23369_Content_14 = {
    Text = "Pertunjukannya akan segera dimulai, kalian juga tidak ingin melewatkannya, bukan, Tuan Pe-tu-gas?"
  },
  AvgDialog_23369_Content_15 = {
    Text = "Kamu menyisir rambut basahmu yang sudah kusut dengan jari, lalu menghela napas panjang."
  },
  AvgDialog_23369_Content_16 = {
    Text = "Ramona, kesabaranku sudah habis. Bagaimana kalau kita hajar dia dulu?"
  },
  AvgDialog_23369_Content_17 = {
    Text = "……Tunggu."
  },
  AvgDialog_23369_Content_18 = {
    Text = "Nona Karen, tidak masalah kalau kami tidak menonton pertunjukan itu."
  },
  AvgDialog_23369_Content_19 = {
    Text = "Tapi bagaimana perasaan Nyonya Soleil kalau tahu pelayan kesayangannya menjual air mandi secara diam-diam di luar?"
  },
  AvgDialog_23369_Content_2 = {
    Text = "Karen terpojok oleh kalian di ujung gang, dengan panik mengangkat tangan untuk melindungi dadanya."
  },
  AvgDialog_23369_Content_20 = {
    Text = "A-aku tidak takut! Dengan status kalian, mustahil bisa bertemu Nyonya Soleil, dasar pembohong!"
  },
  AvgDialog_23369_Content_21 = {
    Text = "Tidak bisa bertemu, memangnya kenapa? Aku akan pergi ke depan gedung opera sekarang juga dan mengumumkan semua perbuatanmu dengan lantang…"
  },
  AvgDialog_23369_Content_22 = {
    Text = "<Big:Tunggu dulu!>"
  },
  AvgDialog_23369_Content_23 = {
    Text = "Karen buru-buru berdiri, meraba-raba celemeknya cukup lama, lalu menyerahkan dua lembar undangan yang kusut kepada kalian."
  },
  AvgDialog_23369_Content_24 = {
    Text = [[
Ini, ambil semuanya!
Hmph, bisanya cuma menindas rakyat kecil, hati-hati sering jalan malam nanti ketemu hantu!]]
  },
  AvgDialog_23369_Content_25 = {
    Text = "Terima kasih atas doa baiknya, Nona Karen, kami akan berhati-hati."
  },
  AvgDialog_23369_Content_26 = {
    Text = "Kamu dengan girang mengulurkan tangan. Tepat saat jarimu menyentuh undangan itu, Karen perlahan mengangkat tangannya dan menarik undangan itu kembali."
  },
  AvgDialog_23369_Content_27 = {
    Text = "Kalian sebaiknya memang hanya ingin menonton pertunjukan, jangan coba-coba macam-macam."
  },
  AvgDialog_23369_Content_28 = {
    Text = "Kalau sampai terjadi sesuatu pada Nyonya Soleil, Karen tidak akan membiarkan kalian lolos."
  },
  AvgDialog_23369_Content_29 = {
    Text = "<Red:Dia juga tidak akan membiarkan kalian lolos.>"
  },
  AvgDialog_23369_Content_3 = {
    Text = "Jangan tangkap aku, jangan tangkap aku…… <Big:Aaaah!>"
  },
  AvgDialog_23369_Content_30 = {Text = "Dia……?"},
  AvgDialog_23369_Content_31 = {
    Text = "Aduh, sepertinya Karen tidak sengaja keceplosan, benar-benar gawat!"
  },
  AvgDialog_23369_Content_32 = {
    Text = [[
Pokoknya, lakukan saja urusan kalian sendiri, jangan tanya yang tidak seharusnya ditanyakan.
Sampai jumpa, Tuan Petugasku~]]
  },
  AvgDialog_23369_Content_33 = {
    Text = "Karen mengedipkan mata dengan nakal ke arah kalian, lalu dengan susah payah mengangkat ember di tanah dan pergi sambil terengah-engah."
  },
  AvgDialog_23369_Content_34 = {
    Text = [[
Ruang Istirahat Misager
Setelah Mystic Realm buatan pertama berakhir]]
  },
  AvgDialog_23369_Content_35 = {
    Text = "Kalian mendapatkan undangan dari pelayan wanita itu. Lalu apa yang terjadi?"
  },
  AvgDialog_23369_Content_36 = {
    Text = "Seperti yang sudah kuceritakan tadi, kami berhasil masuk ke teater dan menemukan Nyonya Soreil di lantai dua."
  },
  AvgDialog_23369_Content_37 = {
    Text = "Tapi kami tetap tidak bisa menghentikan si pembunuh……"
  },
  AvgDialog_23369_Content_38 = {
    Text = "To……tolong aku……"
  },
  AvgDialog_23369_Content_39 = {
    Text = "Tolong aku……"
  },
  AvgDialog_23369_Content_4 = {
    Text = "Aku bahkan belum melakukan apa-apa."
  },
  AvgDialog_23369_Content_40 = {
    Text = "Aku melihatnya jatuh dari atas, bersama bunga-bunga dan sampanye itu…… Itulah semua yang terjadi diDomain pertama."
  },
  AvgDialog_23369_Content_41 = {
    Text = "Akhir tragis sang wanita cantik memang menyedihkan. Kau terlihat hampir menangis."
  },
  AvgDialog_23369_Content_42 = {
    Text = [[
Tidak apa-apa.
Tujuan memasuki Domain hanyalah untuk merekonstruksi TKP, agar penyelidikan selanjutnya memiliki arah.]]
  },
  AvgDialog_23369_Content_43 = {
    Text = "Tahu cara mendapatkan undangan dari pelayan wanita yang suka mengambil barang orang itu…… Tidak buruk, ada kemajuan."
  },
  AvgDialog_23369_Content_5 = {
    Text = "Tenang, kami tidak akan menangkapmu, kami hanya ingin minta bantuan kecil."
  },
  AvgDialog_23369_Content_6 = {
    Text = "Kami butuh dua undangan \"Nama Mawar\". Kurasa Nona Karen masih punya stok, kan?"
  },
  AvgDialog_23369_Content_7 = {
    Text = "Nama Mawar……?"
  },
  AvgDialog_23369_Content_8 = {
    Text = "Karen menurunkan kedua tangan yang melindungi dadanya, mata bulatnya yang besar berputar-putar."
  },
  AvgDialog_23369_Content_9 = {
    Text = "Ternyata Tuan Petugas juga ingin undangan ya, bilang dari awal kan beres!\nLangsung menangkap orang begitu, bikin kaget saja……"
  },
  AvgDialog_23370_Content_10 = {
    Text = "Melihatmu berakting begitu asyik, aku benar-benar tak tega mengganggu."
  },
  AvgDialog_23370_Content_11 = {
    Text = "Memanggil Tim B-01 dan A-03, segera kepung target."
  },
  AvgDialog_23370_Content_12 = {
    Text = "Suara gemerisik terdengar dari segala penjuru jalanan, diikuti oleh derap langkah kaki yang kacau."
  },
  AvgDialog_23370_Content_13 = {
    Text = "Tak lama kemudian, para agen lapangan dari Missage telah mengepung bayangan hitam itu rapat-rapat."
  },
  AvgDialog_23370_Content_14 = {
    Text = "Begitu rupanya, menyamar sebagai orang mabuk untuk memancingku keluar."
  },
  AvgDialog_23370_Content_15 = {
    Text = "Aktingnya bagus sekali, Tuan Dexter, terutama bagian menyanyinya."
  },
  AvgDialog_23370_Content_16 = {
    Text = "Terima kasih atas apresiasinya. Kuberitahu sebuah rahasia, cita-citaku sejak kecil adalah menjadi aktor opera terkenal di Distrik Barat……"
  },
  AvgDialog_23370_Content_17 = {
    Text = "Belum selesai bicara, bayangan hitam itu tiba-tiba melayang pergi, gerakannya begitu mulus bagai air mengalir, tanpa sedikit pun keraguan."
  },
  AvgDialog_23370_Content_19 = {
    Text = "Aku belum selesai bicara…… Cepat tangkap dia!"
  },
  AvgDialog_23370_Content_2 = {
    Text = "Dexter terjatuh ke tanah dengan keadaan berantakan, menggenggam tongkatnya erat-erat dan menghalangi dadanya dengan sia-sia."
  },
  AvgDialog_23370_Content_3 = {
    Text = "Tuan, kurasa ada sedikit kesalahpahaman di antara kita…"
  },
  AvgDialog_23370_Content_4 = {
    Text = "Oh, kesalahpahaman apa? Silakan karang dulu, baru ceritakan padaku."
  },
  AvgDialog_23370_Content_5 = {
    Text = "Bayangan hitam itu membungkuk, topengnya hanya berjarak kurang dari satu inci dari ujung hidung Dexter."
  },
  AvgDialog_23370_Content_6 = {
    Text = "Ugh! Ti-tidak perlu sedekat ini…"
  },
  AvgDialog_23370_Content_7 = {
    Text = "Kulit kepala Dexter merinding, tiba-tiba ia berbalik dan berteriak ke arah sudut di belakangnya."
  },
  AvgDialog_23370_Content_8 = {
    Text = "<Big:Kalian semua, sudah puas menonton pertunjukannya?!>"
  },
  AvgDialog_23370_Content_9 = {Text = "?!"},
  AvgDialog_23371_Content_1 = {
    Text = "Sambil menikmati kue kecil, kamu membawa Ramona masuk ke gang yang sepi."
  },
  AvgDialog_23371_Content_10 = {
    Text = "Ah, aroma lembut ini! <Shake:Rasanya aku hampir tidak bisa bernapas……>"
  },
  AvgDialog_23371_Content_11 = {
    Text = "Ini apa-apaan, kipas milikku ini juga edisi terbatas yang dibawa Nyonya Sorel dari Lemvahi!"
  },
  AvgDialog_23371_Content_12 = {
    Text = "Lihat, di atasnya bahkan tertanam Mata Firaun!"
  },
  AvgDialog_23371_Content_13 = {
    Text = "Hahahaha, memangnya kau pernah lihat mata Firaun itu bentuknya seperti apa? <Shake:Hati-hati kena kutukan lho~>"
  },
  AvgDialog_23371_Content_14 = {
    Text = "Ka-kau apa maksudnya?! Kau meragukan selera Nyonya Soreil?"
  },
  AvgDialog_23371_Content_15 = {Text = "...?"},
  AvgDialog_23371_Content_16 = {
    Text = "Orang-orang ini sedang apa?"
  },
  AvgDialog_23371_Content_17 = {
    Text = "Uhuk uhuk…… Tenang, semuanya tenang! Momen yang mendebarkan akan segera tiba!"
  },
  AvgDialog_23371_Content_18 = {
    Text = "Selanjutnya, izinkan kami memperkenalkan barang dagangan andalan kami! Yaitu——"
  },
  AvgDialog_23371_Content_19 = {
    Text = "<Big:Air mandi yang baru digunakan Nyonya Soreil minggu lalu!>"
  },
  AvgDialog_23371_Content_2 = {
    Text = "Nyam nyam nyam…… Hmm, kue kecil ini rasanya persis sama seperti yang kumakan di dunia nyata!\nRamona, mau coba satu gigitan juga?"
  },
  AvgDialog_23371_Content_3 = {
    Text = "Kamu menyodorkan kue kecil itu ke mulut Ramona. Ramona menghela napas, lalu dengan setengah hati ikut menggigit sedikit."
  },
  AvgDialog_23371_Content_4 = {
    Text = "Hmm…… Lumayan."
  },
  AvgDialog_23371_Content_5 = {
    Text = "Uhuk uhuk, kembali ke topik utama dulu. Bukankah kau mau membawaku mencari undangan?"
  },
  AvgDialog_23371_Content_6 = {
    Text = "Tenang saja, undangannya tidak akan ke mana-mana. Cara ini diajarkan Hannah kepadaku, orang biasa tidak akan terpikirkan."
  },
  AvgDialog_23371_Content_7 = {
    Text = "Nah, lihat ke sana."
  },
  AvgDialog_23371_Content_8 = {
    Text = "Kau menunjuk ke ujung gang. Di sana berkumpul cukup banyak orang, mereka berbincang dengan suara keras sambil melambaikan tangan dengan penuh semangat, suasananya meriah dan penuh antusiasme."
  },
  AvgDialog_23371_Content_9 = {
    Text = "Hihi, stoking nilon ini adalah edisi langka dari \"Panduan Wanita Terhormat\"! Katanya sudah dibeli semua oleh Nyonya Soreil, sama sekali tidak beredar di pasaran..."
  },
  AvgDialog_23372_Content_1 = {
    Text = "Perayaan Merah"
  },
  AvgDialog_23372_Content_10 = {
    Text = "\"Bukan itu, melainkan menerima undangan dari 《Nama mawar》.\""
  },
  AvgDialog_23372_Content_11 = {
    Text = [[
Berhenti, jangan membaca koran lagi. 
 Saya juga warga negara Londinium, saya tahu gosip ini tidak kalah banyak dari kamu.]]
  },
  AvgDialog_23372_Content_12 = {
    Text = "Huh, hampir lupa bahwa ada seseorang yang harus bangun pagi-pagi setiap hari, minum teh, dan membaca koran. Meskipun masih muda, ia hidup seperti seorang nenek-nenek."
  },
  AvgDialog_23372_Content_13 = {
    Text = "Memahami lebih banyak tentang situasi dunia dan berita saat ini juga sangat membantu dalam pekerjaan Penyelidikan."
  },
  AvgDialog_23372_Content_14 = {
    Text = "Karena semuanya demi pekerjaan… mari kita kembali ke topik pekerjaan."
  },
  AvgDialog_23372_Content_15 = {
    Text = "Pertunjukan baru akan dimainkan besok, mengapa harus datang sehari lebih awal? Kekuatan roh saya yang lemah sudah hampir tidak bisa bertahan…"
  },
  AvgDialog_23372_Content_16 = {
    Text = "Dexter memberi tahu saya bahwa Sorel adalah wanita yang suka kemewahan. Dia sering menyewa seluruh lantai dua teater untuk dinikmati bersama teman-temannya."
  },
  AvgDialog_23372_Content_17 = {
    Text = "Jadi, setiap kali dia muncul, ruangannya tidak tetap — tentu saja, ini juga ada pertimbangan faktor keamanan."
  },
  AvgDialog_23372_Content_18 = {
    Text = [[
Begitu ya. 
Namun, pelaku tampaknya sangat yakin akan lokasinya... Apakah ada orang di sekitar Sorel yang membocorkan informasi?]]
  },
  AvgDialog_23372_Content_19 = {
    Text = "Dengan berkata begitu, sosok Karen muncul di benakmu."
  },
  AvgDialog_23372_Content_2 = {
    Text = [[
Domain buatan kedua: Lincoln High Street
Satu hari sebelum kematian Sorel]]
  },
  AvgDialog_23372_Content_20 = {
    Text = "Pelayan perempuan yang banyak bicara itu sangat mencurigakan..."
  },
  AvgDialog_23372_Content_21 = {Text = "Bumm!!"},
  AvgDialog_23372_Content_22 = {
    Text = "Seseorang yang lewat tiba-tiba menabrak bahu kamu. Kamu mengerutkan dahi dan menggeser tubuh, tetapi pergelangan tanganmu malah dipegang erat."
  },
  AvgDialog_23372_Content_23 = {
    Text = "<SmallShake: Hei, aku melihatmu berdiri di depan poster Nyonya Sorel cukup lama, apakah kamu juga pengagumnya?>"
  },
  AvgDialog_23372_Content_24 = {
    Text = "<SmallShake:Saya menjual murah nomor box Nyonya Soreil malam ini, serta lorong yang akan dilaluinya saat pergi…>"
  },
  AvgDialog_23372_Content_25 = {
    Text = "<SmallShake:Ingin melihat sang dewi dari dekat? Malam ini adalah kesempatan terbaik, jangan sampai terlewatkan!>"
  },
  AvgDialog_23372_Content_26 = {Text = "...?"},
  AvgDialog_23372_Content_27 = {
    Text = "Aku tahu Soreil sangat populer, tapi tidak menyangka sampai seperti ini…"
  },
  AvgDialog_23372_Content_28 = {
    Text = "Aku cuma punya satu pertanyaan: perlu sampai segitunya?"
  },
  AvgDialog_23372_Content_29 = {
    Text = "Tsk, ternyata bukan ya.\nJangan menghalangi, ini tempat pertemuan rutin kami para pemuja Soreil…"
  },
  AvgDialog_23372_Content_3 = {
    Text = "<Yellow:Catatan Investigasi Domain Buatan Kedua I>\n\n■Nomor Domain: M-B04-002\n■Waktu Pengaturan: @1 Juni Tahun 315 Aluvi, 2:00-6:00pm (sehari sebelum kematian Sorel).\n■Lokasi Pengaturan: Jalan Raya Lincoln"
  },
  AvgDialog_23372_Content_30 = {
    Text = "Tunggu, siapa yang membocorkan informasi tentang Soreil kepada kalian? Beritahu aku, akan kubayar dua kali lipat."
  },
  AvgDialog_23372_Content_31 = {
    Text = "Memang pantas disebut Ramona, selalu setajam biasanya."
  },
  AvgDialog_23372_Content_32 = {
    Text = "Eh…? Ke-kenapa kau peduli! Jangan-jangan kalian polisi ya?"
  },
  AvgDialog_23372_Content_33 = {
    Text = "Di tengah tarik-menarik itu, sebuah kereta kuda mewah perlahan berhenti di hadapan kalian."
  },
  AvgDialog_23372_Content_34 = {
    Text = "Sebuah tangan pucat kurus yang dipenuhi cincin permata terjulur keluar, menggenggam setumpuk voucher emas Rosegold."
  },
  AvgDialog_23372_Content_35 = {
    Text = "Uhuk uhuk… Informasimu kubeli, Nona kecil."
  },
  AvgDialog_23372_Content_36 = {
    Text = "Dari dalam kereta terdengar suara tua yang aneh. Pemilik suara itu tampaknya sedang sakit parah, terus-menerus batuk, bagaikan sebuah puputan tua yang sudah lama tak diperbaiki."
  },
  AvgDialog_23372_Content_37 = {
    Text = "Uwaa! Se-sebanyak ini? Semuanya untukku?"
  },
  AvgDialog_23372_Content_38 = {
    Text = "Orang di dalam kereta tampak agak tidak sabar, bergerak hendak menarik kembali tangannya."
  },
  AvgDialog_23372_Content_39 = {
    Text = "Gadis itu buru-buru menyelipkan secarik kertas, lalu dengan kecepatan kilat menarik voucher emas itu, tersenyum lebar hingga matanya menyipit menjadi segaris."
  },
  AvgDialog_23372_Content_4 = {
    Text = "■Pemilik Domain: Sorel·@2\n■Penyusup Domain: %player%, Ramona\n\n■Tujuan Penyusupan: <Yellow:Melakukan penyelidikan di sekitar teater, mengumpulkan lebih banyak petunjuk.>"
  },
  AvgDialog_23372_Content_40 = {
    Text = "Ini informasi yang Anda minta! Tuan yang terhormat dan dermawan, semoga Anda lekas sembuh dan panjang umur!"
  },
  AvgDialog_23372_Content_41 = {
    Text = "Sebelum gadis itu selesai bicara, kereta kuda sudah melaju pergi dengan cepat."
  },
  AvgDialog_23372_Content_42 = {
    Text = "Orang tua itu tidak terlihat seperti pemuja Soreil. Ayo kejar dan lihat."
  },
  AvgDialog_23372_Content_5 = {
    Text = "Di jalan yang ramai, pejalan kaki dan kendaraan bergantian melintas, sementara suasana penuh kegembiraan hari raya terasa di mana-mana."
  },
  AvgDialog_23372_Content_6 = {
    Text = "Sehari sebelum pertunjukan opera, poster acara tersebut sudah menutupi seluruh sudut jalan besar dan kecil."
  },
  AvgDialog_23372_Content_7 = {
    Text = "Menariknya, Nyonya Sorel mendominasi sebagian besar poster sebagai pemegang saham teater, dan tak seorang pun benar-benar peduli tentang apa yang sebenarnya diceritakan dalam pertunjukan tersebut."
  },
  AvgDialog_23372_Content_8 = {
    Text = "\"《Nama mawar》 adalah opera pertama yang dipentaskan setelah Nyonya Sorel menanamkan modal di <Blue: Covent Theatre>.\""
  },
  AvgDialog_23372_Content_9 = {
    Text = "\"Saat ini, tanda masuk ke kalangan atas bukanlah mengenakan sutra dari Timur, bukan pula memiliki guci antik dari Lemvahi...\""
  },
  AvgDialog_23841_Content_1 = {
    Text = "Kalian membiarkan sopir pergi, apakah bala bantuan musuh banyak?"
  },
  AvgDialog_23841_Content_10 = {
    Text = "Sejak awal, serangan mereka sudah dilakukan dengan tujuan tertentu, untuk memaksa kita ke sini —— Dermaga Tiga, Berth No. 2."
  },
  AvgDialog_23841_Content_11 = {
    Text = "Tapi di sini sepertinya tidak ada yang istimewa……"
  },
  AvgDialog_23841_Content_12 = {
    Text = "Ya, dermaga nomor 2 ini tidak memiliki keistimewaan apa pun."
  },
  AvgDialog_23841_Content_13 = {
    Text = "Yang benar-benar bermasalah adalah <Yellow:kapal> yang berhenti di sini."
  },
  AvgDialog_23841_Content_14 = {Text = "Kapal?"},
  AvgDialog_23841_Content_15 = {
    Text = "Kata-kata Ramona membangkitkan angin kencang, yang seketika membubarkan kabut tebal di pikiran."
  },
  AvgDialog_23841_Content_16 = {Text = "!"},
  AvgDialog_23841_Content_17 = {
    Text = "Sebuah kapal raksasa muncul tanpa suara di belakang kalian, menutupi bulan dan menghalangi sinarnya, menyelimuti semua orang dalam kegelapan."
  },
  AvgDialog_23841_Content_18 = {
    Text = "Setelah kapal raksasa muncul entah dari mana, gerombolan manusia ikan yang mengepung kalian meledakkan sorakan luar biasa, lalu melakukan perilaku yang sangat aneh."
  },
  AvgDialog_23841_Content_19 = {
    Text = "Cepat, lihat mereka!"
  },
  AvgDialog_23841_Content_2 = {
    Text = "Jumlah musuh terlalu banyak, dan jalan mundur sudah terkepung oleh mereka."
  },
  AvgDialog_23841_Content_20 = {
    Text = "Ikan manusia membentuk barisan panjang, bergantian menyerbu kapal raksasa seperti sekumpulan possum laut yang tidak takut mati."
  },
  AvgDialog_23841_Content_21 = {
    Text = "Yang lebih aneh adalah, setiap kali sirip tangan para ikan itu hampir menyentuh lambung kapal, lambung kapal mengeluarkan getaran dengan cahaya fluoresen yang hampir tak terlihat, membuat semua ikan yang mencoba menyentuhnya terpental ke dalam air."
  },
  AvgDialog_23841_Content_22 = {
    Text = "Kapal ini... apakah menolak kedatangan murloc-murloc ini?"
  },
  AvgDialog_23841_Content_23 = {
    Text = "Korosi pada lambung kapal eksternal sangat parah, sehingga cat asli kapal raksasa itu sudah tidak terlihat lagi, dan nama kapal yang dicat putih juga sulit dibedakan."
  },
  AvgDialog_23841_Content_24 = {Text = "Sona..."},
  AvgDialog_23841_Content_25 = {
    Text = [[
<Blue:Sonanier>. 
Erica, are there any records in the Mythag archives?]]
  },
  AvgDialog_23841_Content_26 = {
    Text = "Sonanier, yang dulunya merupakan bagian dari <Blue:Perusahaan Pelayaran Bintang Hitam>, bertugas sebagai kapal penumpang untuk melaksanakan pelayaran lintas samudra."
  },
  AvgDialog_23841_Content_27 = {
    Text = "Setelah perusahaan Black Star bangkrut, kapal Sonaniel dibeli secara anonim oleh pihak swasta, registrasi pengiriman diubah, dan kapal direnovasi menjadi kapal kargo."
  },
  AvgDialog_23841_Content_28 = {
    Text = "Senior William! Apakah Anda tahu tentang kapal ini?"
  },
  AvgDialog_23841_Content_29 = {
    Text = "Pada tahun Hongji 288, kapal Sonanier tenggelam dalam sebuah badai. Beberapa tahun kemudian, catatan penampakan \"<Blue:Kapal Hantu>\" mulai muncul di sepanjang pantai Laut Utara."
  },
  AvgDialog_23841_Content_3 = {
    Text = "Permukaan laut yang diterangi cahaya bulan masih bergelombang, dan di sudut-sudut yang tidak tembus cahaya, entah berapa banyak musuh yang masih bersembunyi."
  },
  AvgDialog_23841_Content_30 = {
    Text = "Pernah ada Penyelidik Mythag yang naik ke kapal Sonnelier, tetapi tidak membawa kembali intelijen yang berguna."
  },
  AvgDialog_23841_Content_31 = {
    Text = "Tidak membawa kembali intelijen yang berguna..."
  },
  AvgDialog_23841_Content_32 = {
    Text = "Tapi ini berarti bahwa Penyelidik itu kembali ke sekolah dengan selamat, kan?"
  },
  AvgDialog_23841_Content_33 = {
    Text = [[
Ya, meskipun sebagian memori-nya hilang, naik kapal tidak membawa dampak abnormal lain pada tubuhnya. 
Setelah beristirahat sejenak, dia kembali ke garis depan penyelidikan.]]
  },
  AvgDialog_23841_Content_34 = {
    Text = "Bisakah meminta senior itu untuk bergabung dalam komunikasi?"
  },
  AvgDialog_23841_Content_35 = {
    Text = [[
...Sayang sekali. 
Sebelum kamu bergabung dengan Mythag, dia sudah gugur dalam sebuah misi.]]
  },
  AvgDialog_23841_Content_36 = {
    Text = "Tunggu! Ramona, jangan-jangan kamu mau..."
  },
  AvgDialog_23841_Content_37 = {
    Text = "Ya, aku tidak berpikir mereka akan membiarkan kita menunggu sampai bantuan tiba."
  },
  AvgDialog_23841_Content_38 = {
    Text = "Murloc tidak lagi berbondong-bondong mencoba menyentuh kapal Sonaniel, melainkan mengarahkan senjata mereka ke arah kalian. Lingkaran pengepungan semakin mengecil, kamu dan Ramona tidak punya tempat untuk mundur, hampir menabrak badan kapal."
  },
  AvgDialog_23841_Content_39 = {
    Text = "Ramona mengambil napas dalam-dalam, lalu menyentuh tangga kapal yang diturunkan dari lambung kapal."
  },
  AvgDialog_23841_Content_4 = {
    Text = "Mundur@2——！@1！Ajar@1！"
  },
  AvgDialog_23841_Content_40 = {
    Text = [[
Berbeda dengan ikan-ikan itu yang terpental beberapa meter jauhnya, jari-jarinya benar-benar menyentuh lambung kapal. 
 Kamu bertatapan dengannya sejenak, lalu juga meletakkan tanganmu di atas kapal.]]
  },
  AvgDialog_23841_Content_41 = {
    Text = "Sebuah hambatan ringan membuat tanganmu terhenti di udara, namun hambatan itu segera menghilang. Sensasi dingin baja menembus sarung tangan, membuat kulit kepalamu merinding karena dingin yang menusuk."
  },
  AvgDialog_23841_Content_42 = {
    Text = "Kapal Sonnelier ini, <Yellow:tidak menolak kalian>."
  },
  AvgDialog_23841_Content_43 = {
    Text = "Kami sekarang menaiki kapal."
  },
  AvgDialog_23841_Content_5 = {
    Text = "Setelah lingkaran pengepungan dipersempit seminimal mungkin, monster ikan tidak melanjutkan serangan, melainkan berdiri tegang di depan salah satu dermaga, terus-menerus mengucapkan gumaman aneh yang sulit dipahami."
  },
  AvgDialog_23841_Content_6 = {
    Text = "Mengapa mereka tidak melanjutkan serangan terhadap kita?"
  },
  AvgDialog_23841_Content_8 = {
    Text = "Ramona, ada apa?"
  },
  AvgDialog_23841_Content_9 = {
    Text = "Baik itu memanfaatkan jumlah untuk menggiring kita ke sisi utara, atau akhirnya menutup pintu keluar, musuh selalu memberikan jalan bagi kita."
  },
  AvgDialog_23842_Content_1 = {
    Text = "Rumah aman yang disebutkan oleh Kapten kepada saya berada di balik pintu ini."
  },
  AvgDialog_23842_Content_10 = {
    Text = "Anak dengan wajah sombong yang memakai mahkota ini bernama Tulu, dan nama orang di sebelahnya adalah…"
  },
  AvgDialog_23842_Content_12 = {
    Text = "Aku... Apakah aku belum pernah bertanya nama kamu...?"
  },
  AvgDialog_23842_Content_13 = {
    Text = "Murphy dengan malu-malu menggaruk kepalanya, lalu bersembunyi di belakang kapten, menyerahkan aktivitas sosial yang tidak tepat ini kepada satu-satunya orang dewasa."
  },
  AvgDialog_23842_Content_14 = {
    Text = "Saya %player%, seorang mahasiswa di Universitas Mythag."
  },
  AvgDialog_23842_Content_15 = {
    Text = "Anda pasti kapten, kan? Di sekolah kami ada catatan bahwa seorang senior pernah naik ke kapal Sonnelier."
  },
  AvgDialog_23842_Content_16 = {
    Text = "Kapten mengeluarkan kotak rokok dari tas pinggangnya, baru saja mengambil sejumput daun tembakau terakhir, ketika Murphy dengan lembut menepuk tangan kapten itu."
  },
  AvgDialog_23842_Content_17 = {
    Text = "Bukankah kamu sudah berjanji padaku untuk tidak merokok lagi mulai sekarang?"
  },
  AvgDialog_23842_Content_18 = {
    Text = "Dengan senyum penuh kepasrahan, sang kapten menaruh kembali kotak rokoknya."
  },
  AvgDialog_23842_Content_19 = {
    Text = [[
Saya ingat seragam sekolahmu ini. Sayang sekali, sekarang bukan waktu yang tepat. 
Jika di hari lain naik kapal, aku masih bisa menuangkan segelas anggur dan mengobrol denganmu.]]
  },
  AvgDialog_23842_Content_2 = {
    Text = "Apa kode ketuk pintu yang sudah kami sepakati dulu... tiga kali ringan satu kali berat? Ringan-ringan-berat-ringan?"
  },
  AvgDialog_23842_Content_20 = {
    Text = "Elton, nama saya Elton."
  },
  AvgDialog_23842_Content_21 = {
    Text = "Ketika kalian sedang memperkenalkan diri, Murphy berjalan mengitari ruang kabin yang redup. Ketika dia muncul kembali di hadapan kalian, wajahnya dipenuhi dengan kebingungan."
  },
  AvgDialog_23842_Content_22 = {
    Text = "Kapten, apakah Celeste tidak berada di sisimu?"
  },
  AvgDialog_23842_Content_3 = {Text = "——Ya!"},
  AvgDialog_23842_Content_4 = {
    Text = "Tepat saat Murphy berusaha keras mengingat kata sandi hingga keringat bercucuran di kepalanya, pintu tiba-tiba dibuka dari dalam, dan sebuah tangan menariknya masuk."
  },
  AvgDialog_23842_Content_5 = {
    Text = "Tulu dengan cekatan menahan pintu agar tidak tertutup. Setelah bertukar pandang denganmu, kalian berdua segera melangkah masuk melewati pintu tersebut."
  },
  AvgDialog_23842_Content_6 = {
    Text = "Kapal, Kapten! Syukurlah, kau benar-benar menungguku di sini…"
  },
  AvgDialog_23842_Content_7 = {
    Text = "Pria paruh baya dengan kulit gelap, mengenakan pakaian awak kapal, menepuk kepala Murphy sebagai bentuk perhatian."
  },
  AvgDialog_23842_Content_8 = {
    Text = "Menepati janji adalah sesuatu yang harus dipatuhi oleh orang dewasa."
  },
  AvgDialog_23842_Content_9 = {
    Text = "Ngomong-ngomong, siapa mereka berdua?"
  },
  AvgDialog_23843_Content_10 = {
    Text = "Ramona, berhati-hatilah!"
  },
  AvgDialog_23843_Content_11 = {
    Text = "Kamu mengeluarkan Kunci perak, mencoba menekan Pembangun remaja yang tiba-tiba bangkit dengan Tautan."
  },
  AvgDialog_23843_Content_12 = {
    Text = "Namun, hampir seketika kamu menyadari ada yang tidak beres: Roh-nya sangat stabil, dan sebuah rantai ular sedang menarik Roh-nya ke arah yang tak jauh."
  },
  AvgDialog_23843_Content_13 = {
    Text = "——Menarik ke arah Tautan."
  },
  AvgDialog_23843_Content_14 = {
    Text = "Bayangan yang terdistorsi bergerak cepat dari kerumunan Pelaut, menyerang seperti kilat dan membuka paksa tanganmu yang erat memegang Kunci perak. Kamu terhempas ke arah rel kapal oleh kekuatan kuat itu."
  },
  AvgDialog_23843_Content_15 = {
    Text = "Caecus, sudah terlalu lama."
  },
  AvgDialog_23843_Content_16 = {
    Text = "Miryam, Miryam! Beri saya satu kesempatan lagi, saya pasti akan menyingkirkan dua orang ini."
  },
  AvgDialog_23843_Content_17 = {
    Text = "Wanita yang mengenakan mahkota berduri menyipitkan mata padanya, tanpa menjawab. Pandangannya berpindah ke Ramona yang memegang pedang, lalu mengarah ke arahmu, dan akhirnya tertuju pada Kunci perak di dadamu yang masih berkilau dengan cahaya samar."
  },
  AvgDialog_23843_Content_18 = {
    Text = "Kunci perak…"
  },
  AvgDialog_23843_Content_19 = {
    Text = "Sesaat kemudian, bayangan ular meluncur keluar dari balik kerudungnya dan merayap ke Tubuhmu seperti seekor ular berbisa."
  },
  AvgDialog_23843_Content_2 = {
    Text = "Hmm…! Meskipun hanyalah manusia biasa, mengapa bisa begitu sulit diatasi…"
  },
  AvgDialog_23843_Content_20 = {
    Text = "Itu sebenarnya adalah \"Ular berbisa\", jiwa energi ungu membentuk ular yang melilit pergelangan tanganmu dengan erat, gigi tajam yang menyebarkan energi tidak menyenangkan mengarah kepadamu——"
  },
  AvgDialog_23843_Content_22 = {
    Text = "Jangan sentuh {Male=dia,Female=dia}!"
  },
  AvgDialog_23843_Content_23 = {
    Text = "Ramona berbalik dan melemparkan pedang tipisnya, menghalau bayangan ular yang sedang menatapmu dengan penuh ancaman."
  },
  AvgDialog_23843_Content_24 = {
    Text = "Detik berikutnya, kedua kakinya melepaskan kekuatan luar biasa. Dia hampir seperti terbang, melompati dua orang itu dan tiba di sisimu. Dengan cepat, dia menarikmu berguling di tanah, menghindari serangan lain dari bayangan ular saat ia mencabut senjatanya."
  },
  AvgDialog_23843_Content_25 = {
    Text = "Kita bukan tandingan wanita itu, cepat naik ke kapal penyelamat!"
  },
  AvgDialog_23843_Content_26 = {
    Text = "Ramona tidak memberimu kesempatan untuk melawan, tanpa banyak bicara dia mendorongmu ke dalam kapal penyelamat."
  },
  AvgDialog_23843_Content_27 = {
    Text = [[
Kemudian dia melompat ke sisi kapal, sedikit menekuk lutut untuk menstabilkan tubuhnya, lalu dengan cekatan mencabut pedangnya ke samping. 
Perangkat mekanis yang menahan perahu penyelamat pun hancur seketika, rasa kehilangan gravitasi yang besar langsung membanjiri otakmu.]]
  },
  AvgDialog_23843_Content_28 = {
    Text = "<Big:Ramona!>"
  },
  AvgDialog_23843_Content_29 = {
    Text = "Ramona setengah tergantung di luar kapal, bayangan ular mengait pergelangan kakinya dan menariknya kembali ke dalam lambung kapal."
  },
  AvgDialog_23843_Content_3 = {
    Text = "Pemuda itu membelalakkan mata dengan takjub, dalam pertarungan sengit, sirip dan ekornya terluka oleh serangan pedang Ramona yang seperti hujan deras. Darah berwarna abu-abu kemerahan mengalir bebas di atas dek, memenuhi celah-celah papan kayu."
  },
  AvgDialog_23843_Content_30 = {
    Text = "Perahu penyelamat kehilangan keseimbangan saat jatuh, dan kegelapan serta air laut yang sangat dingin segera memenuhi tenggorokanmu."
  },
  AvgDialog_23843_Content_31 = {
    Text = "Yang terakhir kali muncul di hadapan mata adalah tangan Ramona yang terentang ke arahmu."
  },
  AvgDialog_23843_Content_32 = {
    Text = "Ramona terduduk lemas di dek, memegang pergelangan kakinya, dengan alis yang berkerut."
  },
  AvgDialog_23843_Content_33 = {
    Text = "Kraaaak——"
  },
  AvgDialog_23843_Content_34 = {
    Text = "Dia menggertakkan gigi, lalu dengan susah payah menyesuaikan kembali pergelangan kakinya yang terlepas. Ekspresinya hanya berubah sesaat, sebelum kembali ke keteguhan biasanya."
  },
  AvgDialog_23843_Content_35 = {
    Text = "Seorang wanita dengan sikap seorang pemimpin melangkah santai ke depan Ramona, lalu memandangnya dari atas ke bawah."
  },
  AvgDialog_23843_Content_36 = {
    Text = "Kunci Perak, Tautan, Pembangun…"
  },
  AvgDialog_23843_Content_37 = {
    Text = "Saat berada di pelabuhan, aku tidak memperhatikan penampilan kalian. Sekarang setelah kupikirkan, ramalan \"Tuhanku\"memang benar — tak ada yang bisa menghentikan bintang-bintang mencapai posisi Selaras, segala sesuatu di dunia fana ini sedang menuju ke tempat yang seharusnya."
  },
  AvgDialog_23843_Content_38 = {
    Text = "Pelabuhan... Orang yang memerintahkan para Pelaut ini untuk mengejar kita, memanfaatkan kita demi menembus batas Domain di kapal, adalah kamu."
  },
  AvgDialog_23843_Content_39 = {
    Text = "Miryam tidak memberikan jawaban yang jelas, wajahnya yang cantik menampakkan senyuman penuh kesungguhan."
  },
  AvgDialog_23843_Content_4 = {
    Text = "Dia terpaksa menopang tubuhnya dengan senjata agar tetap berdiri, jelas sudah sulit untuk melanjutkan menahan serangan kalian."
  },
  AvgDialog_23843_Content_40 = {
    Text = "Mahasiswa Universitas Mythag, sebagai bahan yang dipersembahkan kepada \"Tuan-ku\", sangatlah cocok."
  },
  AvgDialog_23843_Content_41 = {
    Text = "Miryam tidak lagi melihat Ramona, dan juga tidak peduli bahwa Ramona masih menggenggam senjata di tangannya. Dia tampak begitu yakin diri dan sama sekali tidak khawatir dengan perlawanan Ramona."
  },
  AvgDialog_23843_Content_42 = {
    Text = "Mungkin bisa dikatakan, dia sangat yakin bahwa perlawanan Ramona tidak lagi mampu menimbulkan riak."
  },
  AvgDialog_23843_Content_43 = {
    Text = [[
Ini kesempatan terakhirmu, Caecus. 
Bawa dia ke bawah dan awasi dia dengan baik.]]
  },
  AvgDialog_23843_Content_44 = {
    Text = "Dia akan menjadi bagian terakhir dari ritual, <Yellow:\"Tuan-ku\"> setelah dilahirkan kembali, akan meminum habis darah dan Caro manis dari orang bodoh."
  },
  AvgDialog_23843_Content_45 = {
    Text = "<Yellow:Dia> akan membuat kota kami muncul dari lautan, dan negara kami akan kembali bersinar di dunia yang penuh kekacauan ini, menjadi harapan baru bagi para pelaut."
  },
  AvgDialog_23843_Content_5 = {
    Text = "Kamu berbeda dari monster-monster berkepala ikan dan berbadan manusia itu, dan kekuatanmu..."
  },
  AvgDialog_23843_Content_6 = {
    Text = "Ramona mengangkat pedangnya, ujung pedang mengukir jejak yang indah namun tajam, langsung menunjuk ke arah pemuda yang berlutut dengan satu lutut."
  },
  AvgDialog_23843_Content_7 = {
    Text = "Kamu adalah Pembangun... benar kan?"
  },
  AvgDialog_23843_Content_8 = {
    Text = "Berani sekali! Darah kami jauh lebih mulia daripada manusia rendahan, kau tidak punya hak untuk menyebut Pelaut sebagai monster!"
  },
  AvgDialog_23843_Content_9 = {
    Text = "Kata-kata Ramona menusuk saraf pemuda itu. Tubuhnya tiba-tiba dipenuhi kekuatan, duri di punggungnya berdiri tegak satu per satu, lalu dengan keras ia menangkis pedang Ramona."
  },
  AvgDialog_23844_Content_1 = {
    Text = "Tentakel-tentakel itu menghantam dengan keras, tubuh Pelaut hancur berkeping-keping, namun secara ajaib berhasil menghindari tempat di mana gadis itu berada."
  },
  AvgDialog_23844_Content_10 = {
    Text = "Ah! Ngomong-ngomong tentang ritual... Adik kecil, apakah mereka menyakitimu? Kamu terus memegang pergelangan tanganmu, apakah keseleo?"
  },
  AvgDialog_23844_Content_11 = {
    Text = "Aku bukan adik kecil, aku punya nama."
  },
  AvgDialog_23844_Content_12 = {
    Text = "Murphy, panggil aku Murphy."
  },
  AvgDialog_23844_Content_13 = {
    Text = "Murphy, saya telah dilatih dalam penanganan cedera luar. Bolehkah saya melihat tanganmu?"
  },
  AvgDialog_23844_Content_14 = {
    Text = "Gadis itu ragu-ragu memandangmu, namun akhirnya mengizinkanmu untuk mendekat dan mengulurkan satu tangannya."
  },
  AvgDialog_23844_Content_15 = {
    Text = "Kamu dengan lembut memegang tangannya dan mendorong lengan bajunya sedikit ke atas. Dia mengenakan pakaian musim dingin yang tebal, selain sedikit kemerahan karena mungkin tergesek, tidak terlihat ada luka luar lainnya."
  },
  AvgDialog_23844_Content_16 = {
    Text = "Mungkin ada sedikit cedera otot, dengan tingkat seperti ini, cukup beristirahat selama dua hari dan tidak akan ada masalah."
  },
  AvgDialog_23844_Content_17 = {
    Text = "Merasakan emosi Murphy sedikit mereda, kamu menghindari lukanya dan tiba-tiba menggenggam erat lengan atasnya."
  },
  AvgDialog_23844_Content_18 = {
    Text = "Apa yang kamu lakukan?!"
  },
  AvgDialog_23844_Content_19 = {
    Text = [[
Kamu mengenal Miryam, pemimpin Pelaut, namun kamu juga diburu oleh Pelaut. 
Murphy, sebenarnya siapa kamu?]]
  },
  AvgDialog_23844_Content_2 = {
    Text = "Tulu menarik kembali tentakelnya dan melihat cairan berwarna abu-abu kehijauan serta merah putih yang bercampur di atasnya. Ekspresi jijik di wajahnya menghilang seketika setelah ia diam-diam menggosokkan kotoran itu di dek kapal."
  },
  AvgDialog_23844_Content_20 = {
    Text = "Saya, saya..."
  },
  AvgDialog_23844_Content_21 = {
    Text = "Pada saat itu, Tulu menyelesaikan pengamatan terhadap rune dan bergabung dalam percakapan."
  },
  AvgDialog_23844_Content_22 = {
    Text = "Rune itu adalah bagian dari ritual yang digunakan oleh Pelaut untuk hipnotis. Mereka ingin membuatnya tertidur sejenak guna menghindari masalah tambahan…"
  },
  AvgDialog_23844_Content_23 = {
    Text = "Begitu Tulu selesai berbicara, wajah Murphy langsung menjadi pucat. Gerakan perlawanannya yang tadinya menendang dan menggigitmu juga berhenti, sepertinya dia sedang memikirkan sesuatu."
  },
  AvgDialog_23844_Content_24 = {Text = "Murphy?"},
  AvgDialog_23844_Content_25 = {
    Text = "—— Dang!"
  },
  AvgDialog_23844_Content_26 = {
    Text = "Rasa sakit yang luar biasa menyerang dahi, benturan membuatmu merasa pusing dan kehilangan keseimbangan. Sementara itu, Murphy berhasil melepaskan diri dari genggamanmu, lalu ia menutupi dahinya dan berlari lebih jauh ke dalam kabin kapal."
  },
  AvgDialog_23844_Content_27 = {
    Text = "Aku sudah tahu kalian bukan orang baik!!"
  },
  AvgDialog_23844_Content_28 = {
    Text = "Jangan, jangan... Dengarkan penjelasanku..."
  },
  AvgDialog_23844_Content_29 = {
    Text = "Murphy jelas tidak akan mendengarkan penjelasanmu yang terdengar lemah, sosoknya segera menghilang di tikungan."
  },
  AvgDialog_23844_Content_3 = {
    Text = "Hah, hah……"
  },
  AvgDialog_23844_Content_30 = {
    Text = "...Tulu, kenapa tidak mencoba menghentikannya?"
  },
  AvgDialog_23844_Content_32 = {
    Text = "Jangan menatap Yu seperti itu. Yu juga tidak menduganya, kepalanya ternyata sekeras ini."
  },
  AvgDialog_23844_Content_4 = {
    Text = "Gadis itu menutup pergelangan tangannya sambil bernapas dengan terengah-engah, tampak masih belum tenang setelah mengalami ketakutan hebat."
  },
  AvgDialog_23844_Content_5 = {
    Text = "Apa kamu baik-baik saja?"
  },
  AvgDialog_23844_Content_6 = {
    Text = "Jangan mendekat!!"
  },
  AvgDialog_23844_Content_7 = {
    Text = "Kamu hanya melangkah setengah langkah ke depan, namun gadis itu langsung berteriak dengan tegang. Matanya dipenuhi rasa waspada."
  },
  AvgDialog_23844_Content_8 = {
    Text = "Melihat situasi ini, kamu tidak mendekat lagi, melainkan mengangkat kedua tanganmu untuk menunjukkan bahwa kamu tidak berniat jahat."
  },
  AvgDialog_23844_Content_9 = {
    Text = "Jangan takut, kami bukan orang jahat. Kalau bukan karena kami, kamu sudah lama diambil oleh pria berwajah ular itu untuk digunakan dalam ritual, kan?"
  },
  AvgDialog_23845_Content_1 = {
    Text = "Kalian berjalan dengan sangat hati-hati melewati dek, Murphy menutup mulutnya dan menunjuk ke arah jembatan yang tidak jauh, memberi isyarat bahwa ruang mesin ada di dalam sana."
  },
  AvgDialog_23845_Content_10 = {
    Text = "Pedang raksasa dilemparkan dengan kasar dari kejauhan ke arah kalian, dengan kekuatan begitu besar hingga menyobek udara dan membangkitkan gelombang kejut yang sangat kuat."
  },
  AvgDialog_23845_Content_11 = {Text = "Hati-hati!"},
  AvgDialog_23845_Content_12 = {
    Text = "Tentakel yang kokoh melilit pinggangmu dan dengan cepat menarikmu menjauh dari titik jatuhnya bilah raksasa."
  },
  AvgDialog_23845_Content_13 = {
    Text = "Pelaut umumnya memiliki tubuh yang lemah dan mahir menggunakan senjata ringan. Pedang raksasa ini memiliki pemilik lain, jadi berhati-hatilah."
  },
  AvgDialog_23845_Content_14 = {
    Text = "Tubuh lemah… Saya setuju dengan pandanganmu tentang mereka ini."
  },
  AvgDialog_23845_Content_15 = {
    Text = "Namun, sebagai ujung tombak perang, orang yang kekurangan kesadaran diri tidak bisa lebih berguna lagi."
  },
  AvgDialog_23845_Content_16 = {
    Text = "Pria kekar dan tinggi menyeret sirip ekor panjangnya, menendang Pelaut yang merangkak di kakinya, dan melangkah dengan berat menuju kalian."
  },
  AvgDialog_23845_Content_17 = {
    Text = "Dia mencabut pedang raksasa yang dalam tertancap di dek, dengan nada mengejek. Pandangannya ke arahmu dipenuhi oleh rasa ingin tahu dan pengamatan."
  },
  AvgDialog_23845_Content_18 = {
    Text = "Status lebih tinggi daripada Pembangun Pelaut… Apakah orang ini juga kaki tangan Miryam?!"
  },
  AvgDialog_23845_Content_19 = {
    Text = "\"Kaki tangan Miryam\"? Huh, terdengar sangat tidak enak."
  },
  AvgDialog_23845_Content_2 = {
    Text = "Asalkan bisa mengalihkan perhatian Pelaut di depan pintu, kalian bisa masuk ke gedung secara diam-diam..."
  },
  AvgDialog_23845_Content_20 = {
    Text = [[
Namaku Goliath.
Ingatlah, ini adalah nama orang yang menaklukkan segala lautan!]]
  },
  AvgDialog_23845_Content_3 = {
    Text = "Kamu mengangguk dengan paham, sambil meraba-raba di dalam saku untuk mencari barang-barang yang bisa dilemparkan, ketika langkah kaki berat terdengar semakin dekat."
  },
  AvgDialog_23845_Content_4 = {
    Text = "Murphy menghirup napas dingin, wajahnya dipenuhi rasa takut. Dia memandang ke kiri dan kanan, lalu tiba-tiba membuka terpal di atas peti kargo dengan gerakan cepat, menggunakan tangan dan kakinya untuk merangkak masuk ke dalam peti."
  },
  AvgDialog_23845_Content_5 = {
    Text = "<Small:Murphy?>"
  },
  AvgDialog_23845_Content_6 = {
    Text = "Kotak itu tidak lagi mengeluarkan suara atau gerakan apa pun, melahap Murphy seperti lubang hitam yang sunyi."
  },
  AvgDialog_23845_Content_7 = {
    Text = "Diam, ada orang di sana."
  },
  AvgDialog_23845_Content_8 = {
    Text = [[
Yang memanggil Penjaga Pelaut dengan bahasa kuno tak diragukan lagi adalah seorang raksasa.
Dari sudut pandang kalian, kalian tidak bisa melihat tubuh aslinya, tetapi bayangannya di dek tampak sangat besar.]]
  },
  AvgDialog_23845_Content_9 = {
    Text = "Begitu besar, seolah-olah cukup untuk meratakan gunung dan menelan matahari serta bulan——"
  },
  AvgDialog_23846_Content_1 = {
    Text = "Dermaga ini juga terlalu besar."
  },
  AvgDialog_23846_Content_10 = {
    Text = "Harap kali ini bukan pengaruh dari <Yellow:Clades>…"
  },
  AvgDialog_23846_Content_2 = {
    Text = "Jangan kendur, kita hampir sampai di pintu keluar utara."
  },
  AvgDialog_23846_Content_3 = {
    Text = [[
Setelah melewati pertempuran sepanjang jalan, musuh yang masih berdiri di hadapan kalian sudah tersisa sedikit. 
Di depan sana, yang tersisa untuk kalian kalahkan hanyalah beberapa musuh kecil.]]
  },
  AvgDialog_23846_Content_4 = {
    Text = [[
Musuh-musuh ini... apakah mereka dikirim oleh Gereja Penerang Kuil?
Jika tidak ada hubungannya dengan mereka, ini terlalu kebetulan.]]
  },
  AvgDialog_23846_Content_5 = {
    Text = [[
Saya tidak bisa menyangkal kemungkinan ini. 
Namun, anggota Gereja Penerang Kuil yang kami temui di kota kecil Rai jauh lebih elegan daripada mereka.]]
  },
  AvgDialog_23846_Content_6 = {
    Text = "Mereka yang mengepung kalian adalah \"ikan kecil\" sejati — tubuh mereka mirip manusia namun bungkuk, dengan kepala ikan terlihat dari balik tudung lusuh mereka."
  },
  AvgDialog_23846_Content_7 = {
    Text = "Setiap kali mereka menyerang, kamu bisa mencium bau busuk dari hidup yang memudar."
  },
  AvgDialog_23846_Content_8 = {
    Text = "Tak bisa mengabaikan kemungkinan keterlibatan para pematung, Herbert adalah orang yang mempermainkan kehidupan dengan nama eksperimen."
  },
  AvgDialog_23846_Content_9 = {
    Text = "Saya suka penilaianmu tentang Herbert. Namun, jangan lupa bahwa pelarutan juga dapat memicu mutasi kelompok seperti ini."
  },
  AvgDialog_23847_Content_1 = {
    Text = "Kamu dan Tulu bersembunyi di sudut yang cukup tersembunyi. Dia waspada terhadap sekitarnya, sementara kamu tenggelam dalam dunia roh yang seperti ilusi."
  },
  AvgDialog_23847_Content_10 = {
    Text = "Manusia biasa biasanya memiliki keberadaan yang lemah di Dunia roh. Jika tidak ada begitu banyak Pelaut, mencari Murphy di kapal hantu tanpa awak seharusnya bukan tugas yang sulit."
  },
  AvgDialog_23847_Content_11 = {
    Text = "Akar-akar Roh bergerak sia-sia di antara kumpulan Pelaut, dengan canggung menabrak satu demi satu titik cahaya."
  },
  AvgDialog_23847_Content_12 = {
    Text = "<Gray:Roh Murphy…yang mana sebenarnya dia…>"
  },
  AvgDialog_23847_Content_13 = {
    Text = "Saat nama Murphy sedang kau gumamkan dalam hati, tiba-tiba, sebuah suara wanita yang samar-samar muncul di frekuensi yang sama denganmu."
  },
  AvgDialog_23847_Content_14 = {
    Text = "Ketika membuka mata kembali, ruang kesadaran tiba-tiba terdistorsi menjadi bentuk lain."
  },
  AvgDialog_23847_Content_15 = {
    Text = "Di ujung cakrawala, kota yang miring dan terdistorsi menjulang tinggi. Roh yang bising tidak lagi dapat mengganggu pikiranmu. Sekelilingmu sunyi senyap, hanya ada satu cahaya redup di depanmu yang terus-menerus memancarkan dingin."
  },
  AvgDialog_23847_Content_16 = {
    Text = "Ini... siapa?"
  },
  AvgDialog_23847_Content_17 = {
    Text = "Miryam yang terhormat, Altar Elworth telah dirusak oleh orang-orang dari tim petualang! Waktu Selaras telah berlalu, dan sesuatu yang bisa Bangun…"
  },
  AvgDialog_23847_Content_18 = {
    Text = "<Gray:Miryam... Ini benar-benar dunia roh Miryam?!>"
  },
  AvgDialog_23847_Content_19 = {
    Text = "Itu sama sekali bukan ibu dewa yang bisa melahirkan \"Tuan-ku\"! Itu adalah mesin pembunuh yang hanya tahu membantai!"
  },
  AvgDialog_23847_Content_2 = {
    Text = "Setelah rasa tenggelam yang familiar memudar, angin tak terlihat dari Dunia Roh memenuhi otak. Kamu membuka mata, Dunia Roh di hadapanmu terasa familiar, namun juga sedikit asing."
  },
  AvgDialog_23847_Content_20 = {
    Text = [[
...Tidak apa-apa, ini hanyalah menunggu sekali lagi saat bintang-bintang berada dalam posisi selaras.
Aku sudah menunggu lima ribu siklus pergerakan bintang, menunggu satu kali lagi dalam siklus, apa masalahnya.]]
  },
  AvgDialog_23847_Content_21 = {
    Text = "Beri tahu Gereja Penerang Kuil untuk membawa barang yang rusak itu pergi."
  },
  AvgDialog_23847_Content_22 = {Text = "Ya, ya..."},
  AvgDialog_23847_Content_23 = {
    Text = "Wadah baru yang dapat menumbuhkan \"Tuan\"-ku... apa yang harus kulakukan?"
  },
  AvgDialog_23847_Content_24 = {
    Text = "Wadah saat ini… bukankah Anda berkata bahwa karena gangguan Fenomena-d, benda itu sudah tidak bisa bertahan selama 25 tahun lagi?"
  },
  AvgDialog_23847_Content_25 = {
    Text = "Meskipun kita tidak dapat melihat pelarutan, kelemahan wadah yang semakin parah dapat dilihat oleh semua orang."
  },
  AvgDialog_23847_Content_26 = {
    Text = "Calon baru untuk \"Ibu Dewa\"…"
  },
  AvgDialog_23847_Content_27 = {
    Text = "Miryam menundukkan pandangannya ke arah gadis yang duduk di tepi kolam sambil tertidur. Di dalam gua es kutub yang suram ini, rambut merah muda gadis itu tampak sangat mencolok, memancarkan vitalitas yang luar biasa."
  },
  AvgDialog_23847_Content_28 = {
    Text = "Di antara para pengikutnya yang berkerumun, dia menggendong gadis muda yang sedang tertidur."
  },
  AvgDialog_23847_Content_29 = {
    Text = "Dia berjalan tanpa alas kaki menuju puncak altar, menuju kursi batu yang dingin namun melambangkan kemuliaan mutlak."
  },
  AvgDialog_23847_Content_3 = {
    Text = "<Gray:……kapal?>"
  },
  AvgDialog_23847_Content_30 = {
    Text = "Dia merasakan kehangatan yang dimiliki oleh manusia. Lama kemudian, kata-kata yang pelan namun cukup jelas untuk didengar oleh semua orang keluar dari mulutnya."
  },
  AvgDialog_23847_Content_31 = {
    Text = "\"Induk Ilahi\" yang baru... sudah lama dianugerahkan oleh surga."
  },
  AvgDialog_23847_Content_32 = {
    Text = "Di antara para pengikut yang berlutut, segera terdengar bisikan-bisikan pelan."
  },
  AvgDialog_23847_Content_33 = {
    Text = "Murphy, Sang Perawan Suci? Tapi bukankah dia tidak..."
  },
  AvgDialog_23847_Content_34 = {
    Text = "Ya, dia adalah anak angkat dari Nyonya Miryam…"
  },
  AvgDialog_23847_Content_35 = {
    Text = "Meskipun Gereja Penerang Kuil mungkin tidak akan lagi menyediakan bahan Bangun yang baru, Tuan Miryam tidak akan sampai membiarkan Nyonya Murphy kehilangan nyawa, bukan……"
  },
  AvgDialog_23847_Content_36 = {
    Text = "Apakah Imam Miryam terlalu keras kepala? Dalam ajaran Daulat Laut, dikatakan bahwa Ranah Dewa telah musnah puluhan ribu tahun yang lalu."
  },
  AvgDialog_23847_Content_37 = {
    Text = "Murphy adalah anak yang tumbuh dewasa di bawah pengamatan semua orang... Sungguh, Pemimpin Upacara juga sangat sabar, sudah menunggu selama ribuan tahun, apa salahnya mencari inang baru lagi dengan sedikit lebih banyak waktu?"
  },
  AvgDialog_23847_Content_38 = {
    Text = "Namun, dikabarkan bahwa Saintess lahir pada saat bintang-bintang berada dalam posisi Selaras sebelumnya. Tampaknya tidak ada yang lebih cocok untuk posisi ini daripada dirinya…"
  },
  AvgDialog_23847_Content_39 = {
    Text = "Berbagai macam pembicaraan tidak membuat Miryam bereaksi sedikit pun, sebaliknya, Murphy terganggu oleh keributan itu dan perlahan sadar kembali."
  },
  AvgDialog_23847_Content_4 = {
    Text = "Kapal layar putih melayang di ujung cakrawala, tampak putih, rapuh, dan asing."
  },
  AvgDialog_23847_Content_40 = {Text = "Ini……"},
  AvgDialog_23847_Content_41 = {
    Text = "Miryam, apa yang terjadi? Kenapa kau membawaku ke sini?"
  },
  AvgDialog_23847_Content_42 = {
    Text = "Miryam tidak menjawab, melainkan mengulurkan tangan untuk merapikan rambut Murphy yang acak-acakan."
  },
  AvgDialog_23847_Content_43 = {
    Text = "Dia berbicara lagi, kali ini dengan suara yang tegas dan penuh keyakinan."
  },
  AvgDialog_23847_Content_44 = {
    Text = "\"Dewa Ibu\"telah tiba! Dia akan bangkit dari @1, membuat @2 Kedatangan!"
  },
  AvgDialog_23847_Content_45 = {
    Text = "Altar Elworth, tim petualangan…"
  },
  AvgDialog_23847_Content_46 = {
    Text = "Apakah itu Francis…!"
  },
  AvgDialog_23847_Content_47 = {
    Text = "Begitu ide itu muncul, tengkuk langsung merasakan dingin yang menusuk tulang. Pandangan dingin seperti ular berbisa terus-menerus menatapmu, membuatmu tiba-tiba terlempar keluar dari Dunia roh Miryam."
  },
  AvgDialog_23847_Content_48 = {Text = "Ukh……!"},
  AvgDialog_23847_Content_49 = {
    Text = "Bagaimana, sudah menemukannya?"
  },
  AvgDialog_23847_Content_5 = {
    Text = "<Gray: Apakah karena Sonnelier berada di dalam Domain khusus, Dunia roh bisa berubah karenanya.>"
  },
  AvgDialog_23847_Content_50 = {
    Text = "Pemisahan yang tidak biasa membuatmu merasa pusing, kamu harus berpegangan pada tentakel Tulu agar bisa tetap berdiri."
  },
  AvgDialog_23847_Content_51 = {
    Text = "Saya menerobos ke dalam dunia roh Miryam, dan sekarang dia tahu bahwa saya masih hidup."
  },
  AvgDialog_23847_Content_52 = {Text = "!?"},
  AvgDialog_23847_Content_53 = {
    Text = "Suara sirip berlari di atas dek terdengar, semakin dekat dari kejauhan. Tidak tahu apakah Miryam memanfaatkan penelusuran Roh secara terbalik, tetapi saat ini para Pelaut sedang mengelilingi kalian."
  },
  AvgDialog_23847_Content_54 = {
    Text = "Hei! Masih berdiri diam di sana? Ikuti aku!"
  },
  AvgDialog_23847_Content_55 = {
    Text = "Murphy berdiri di samping sebuah pintu dan melambaikan tangan kepada kalian."
  },
  AvgDialog_23847_Content_56 = {
    Text = "Kamu bertukar pandang dengan Tulu, lalu berlari ke arah yang dia tunjuk."
  },
  AvgDialog_23847_Content_57 = {
    Text = "Miryam duduk dengan tenang di posisi tertinggi jembatan kapal, matanya sedikit terpejam, satu tangannya menopang dahi, tampak seperti seseorang yang kelelahan secara Roh."
  },
  AvgDialog_23847_Content_58 = {
    Text = "Hei, jarang melihatmu menunjukkan ekspresi seperti ini. Ada apa, tidak ingin bermain rumah-rumahan dengan Nona kita lagi?"
  },
  AvgDialog_23847_Content_59 = {
    Text = "Jangan bertindak sembarangan, Goliath."
  },
  AvgDialog_23847_Content_6 = {
    Text = "Di sekitar kapal berkeliaran tak terhitung titik cahaya, seperti melangkah ke kolam di hutan lebat musim panas, suara katak saling bersahutan seperti genderang perang... Setiap Pelaut ternyata memiliki jejaknya sendiri."
  },
  AvgDialog_23847_Content_60 = {
    Text = "Dewi... sebagai manusia biasa, dia tidak dapat melarikan diri dari takdir yang telah aku tetapkan untuknya."
  },
  AvgDialog_23847_Content_61 = {
    Text = "Begitu percaya diri, kenapa masih repot-repot memanggilku ke sini? Aku sedang asyik mengejar kapten itu."
  },
  AvgDialog_23847_Content_62 = {
    Text = "…Seorang mahasiswa Universitas Mythag lainnya, {Male=dia,Female=dia} masih hidup."
  },
  AvgDialog_23847_Content_63 = {
    Text = "Pergi dan selesaikan {Male=dia,Female=dia}, jangan biarkan {Male=dia,Female=dia} menjadi penghalang upacara. Upacara harus dilaksanakan saat bintang-bintang berada dalam posisi Selaras…"
  },
  AvgDialog_23847_Content_64 = {
    Text = "\"Tuan-ku\" pasti akan memperoleh kelahiran kembali pada malam ini."
  },
  AvgDialog_23847_Content_7 = {
    Text = "<Gray:Tenang, tenang… yang terdekat denganku adalah Tulu, yang memiliki tautan denganku adalah Ramona…>"
  },
  AvgDialog_23847_Content_8 = {
    Text = "Di dalam kegelapan, ada beberapa sumber cahaya yang tampak sangat mencolok, namun betapapun kamu mengejarnya, itu hanya sia-sia. Roh-mu diblokade sepenuhnya oleh Pelaut."
  },
  AvgDialog_23847_Content_9 = {
    Text = "<Gray: Minggir... cepat minggir.>"
  },
  AvgDialog_23848_Content_1 = {
    Text = "Sol sepatu yang keras dengan kuat menginjak tubuh mutan, D-lendir berceceran ke mana-mana."
  },
  AvgDialog_23848_Content_10 = {
    Text = "Aduh, apakah kamu sudah selesai bertanya?"
  },
  AvgDialog_23848_Content_11 = {
    Text = "Murphy mengentakkan kakinya dan menunjuk ke arahmu yang berada di belakang Tulu."
  },
  AvgDialog_23848_Content_12 = {
    Text = "Bukankah teman orang ini masih ada di tangan Pelaut? Jika kalian terus berlama-lama dan membuang waktu, dan sesuatu terjadi pada orang itu, aku tidak akan bertanggung jawab."
  },
  AvgDialog_23848_Content_14 = {
    Text = "Tulu melirikmu sejenak, tampaknya sedang mengamati ekspresi di wajahmu."
  },
  AvgDialog_23848_Content_15 = {
    Text = [[
Teman dalam bahaya, kami terus berada dalam pertempuran sepanjang jalan, Tulu menjadi sangat tegang. 
Semoga kamu tidak mempermasalahkan ketidaksopanan kami.]]
  },
  AvgDialog_23848_Content_16 = {
    Text = "Tolong bawa kami menemui kapten, menemui… seseorang yang bisa membantu saya menemukan Ramona."
  },
  AvgDialog_23848_Content_2 = {
    Text = "Murphy menurunkan sekop yang sedang diayunkannya, dengan jijik mengibaskan tangannya, seolah-olah ingin menyingkirkan D-lendir yang sebenarnya tidak menempel di tangannya."
  },
  AvgDialog_23848_Content_3 = {
    Text = [[
Hu... untung bukan Pelaut, kalau tidak, aku mungkin tidak akan berani bertindak... 
 Kalian datang terlalu lambat, ayo cepat pergi.]]
  },
  AvgDialog_23848_Content_4 = {
    Text = "Tunggu sebentar."
  },
  AvgDialog_23848_Content_5 = {
    Text = "Tulu berbicara dengan nada dingin dan keras, tetapi ketika memikirkan kata-katanya sebelumnya tentang Murphy dan misteri-misteri yang menyelimutinya, akhirnya kamu memilih untuk tetap diam."
  },
  AvgDialog_23848_Content_6 = {
    Text = "Meskipun kabin-kabin yang kamu bawa kami lewati tidak memiliki jejak Pelaut, semakin ke dalam, aktivitas tubuh aneh hasil Pelarutan semakin sering terjadi."
  },
  AvgDialog_23848_Content_7 = {
    Text = "Kamu terus membawa kami ke tempat-tempat berbahaya."
  },
  AvgDialog_23848_Content_8 = {
    Text = "Entitas abnormal? … Ah, apakah kamu maksud monster-monster ini?"
  },
  AvgDialog_23848_Content_9 = {
    Text = "Kapten berkata bahwa kapal ini pernah mengalami Clades. Beberapa pelaut berubah menjadi monster atau semacamnya, tetapi dia tidak tega membersihkannya, jadi kebanyakan dari mereka dikunci di dalam kabin kapal."
  },
  AvgDialog_23849_Content_1 = {
    Text = "Pintu kabin terbuka sedikit, cahaya yang memukau berlomba-lomba masuk ke dalam kabin yang redup."
  },
  AvgDialog_23849_Content_2 = {
    Text = "Jika bukan karena Pelaut yang berkeliaran di kejauhan, mungkin Sonanier benar-benar bisa menjadi utopia yang terisolasi dari dunia luar…"
  },
  AvgDialog_23850_Content_1 = {
    Text = "Nyonya Ramona, Penjaga! Di sini!"
  },
  AvgDialog_23850_Content_10 = {
    Text = "Apakah murloc ini sengaja menghadang kita?!"
  },
  AvgDialog_23850_Content_11 = {
    Text = "Pak sopir bukan anggota pertempuran, segera pergi!"
  },
  AvgDialog_23850_Content_12 = {
    Text = "Baik, baik. Harap berhati-hati sepenuhnya!"
  },
  AvgDialog_23850_Content_13 = {
    Text = "Sopir melompat kembali ke mobil. Suara mesin yang menyala menarik perhatian banyak musuh."
  },
  AvgDialog_23850_Content_14 = {
    Text = "Hei! Pandang ke langit, lihat ke sini!"
  },
  AvgDialog_23850_Content_2 = {Text = "Pak sopir!"},
  AvgDialog_23850_Content_3 = {
    Text = "Tidak jauh di depan, pria paruh baya yang tampak akrab dengan cemas menggoyang rantai besi di pintu, dengan ekspresi sulit di wajahnya."
  },
  AvgDialog_23850_Content_4 = {
    Text = "Pintu ini terkunci, apa yang harus aku lakukan?"
  },
  AvgDialog_23850_Content_5 = {
    Text = "Tidak apa-apa, saya akan langsung memutus rantai ini. Anda mundur sedikit."
  },
  AvgDialog_23850_Content_6 = {
    Text = "Sopir mendengar itu dan mundur beberapa langkah, menghindari terluka oleh mata pedang. Ramona mengangkat senjatanya di depan dada, menarik napas dalam-dalam untuk mengisi muatan ——"
  },
  AvgDialog_23850_Content_8 = {
    Text = "Suara gemerisik semakin keras, sesuatu secara berturut-turut muncul dari kegelapan, membuat udara menjadi semakin lembap dan berat."
  },
  AvgDialog_23850_Content_9 = {
    Text = "Musuh berbentuk ikan menghalangi jalan antara kalian dan pintu besi. Sopir itu menjerit ketakutan, lalu langsung duduk di atas kap mesin."
  },
  AvgDialog_23851_Content_1 = {
    Text = "Kekuatan yang sangat mengagumkan...! Bahkan menurut standar Pembangun, ini bisa dianggap mengerikan."
  },
  AvgDialog_23851_Content_10 = {
    Text = "Tawa liar bergema di Domain, suasana menjadi semakin tegang."
  },
  AvgDialog_23851_Content_11 = {
    Text = "Jangan terlalu tegang, aku tidak berniat menghabisi kalian di sini."
  },
  AvgDialog_23851_Content_12 = {
    Text = "Gereja Penerang Kuil mengajarkan orang-orang yang tak berguna itu, bahkan tidak bisa menjalankan tugas penjagaan dengan baik, membiarkan kurcaci kecil ini menyelinap masuk... Namun, berkat ketidakmampuan mereka, sekarang ritual ini menjadi lebih menarik."
  },
  AvgDialog_23851_Content_13 = {
    Text = "Gereja Penerang Kuil... Apakah Pelaut dan Gereja Penerang Kuil ternyata satu kelompok?"
  },
  AvgDialog_23851_Content_14 = {
    Text = "Ha? Jangan samakan aku dengan kelompok orang gila itu. Pelaut sulit berjalan di dunia karena penampilan mereka, dan mereka menginginkan kekuatan kami... Hanya saling memanfaatkan, bergantung satu sama lain untuk bertahan hidup."
  },
  AvgDialog_23851_Content_15 = {
    Text = "Tidak hanya terkait dengan Gereja Penerang Kuil, tetapi juga <Blue:ritual> yang kau sebutkan…"
  },
  AvgDialog_23851_Content_16 = {
    Text = "Goliath... siapa kamu sebenarnya?"
  },
  AvgDialog_23851_Content_17 = {
    Text = "Siapa aku? Hahahaha! Kenapa tidak bertanya kepada orang di sebelahmu?"
  },
  AvgDialog_23851_Content_18 = {
    Text = "Saya, dan dari mana para Pelaut ini berasal — Anda pasti bisa menebaknya, bukan? Lagipula, Anda adalah yang tertinggi..."
  },
  AvgDialog_23851_Content_19 = {
    Text = "Melampaui batas!"
  },
  AvgDialog_23851_Content_2 = {
    Text = "Kekuatan ini…"
  },
  AvgDialog_23851_Content_20 = {
    Text = "Menakutkan, sangat menakutkan——namun sayangnya, aku bukan salah satu dari pengikut setiamu."
  },
  AvgDialog_23851_Content_21 = {
    Text = "Saya masih harus melanjutkan persiapan untuk ritual, tidak punya waktu untuk terus berdebat dengan kalian."
  },
  AvgDialog_23851_Content_22 = {
    Text = "Meskipun kamu bersembunyi ke sana-sini dengan menggunakan tentakel, kamu tahu — hanya kamu yang bisa memberikan apa yang diinginkan oleh wanita itu."
  },
  AvgDialog_23851_Content_23 = {
    Text = "Perwujudan yang membagi kekuatan dewa yang tak berdaya... Uh!"
  },
  AvgDialog_23851_Content_24 = {
    Text = "Ejekan itu belum selesai terdengar ketika bayangan ungu tiba-tiba keluar dari luka di leher Goliath. Ia melingkar di sekitar leher seperti selendang, dan akhirnya berubah menjadi bentuk ular."
  },
  AvgDialog_23851_Content_25 = {
    Text = "Goliath memelintir wajahnya karena munculnya bayangan ular, racun dari taring itu bahkan menancapkan giginya ke dalam bekas luka di lehernya."
  },
  AvgDialog_23851_Content_26 = {
    Text = "Di bawah pengaruh rasa sakit dan racun yang saling terjalin, senyuman menyimpul muncul di wajahnya, deretan gigi putih seperti taring hiu bergetar karena kegembiraan."
  },
  AvgDialog_23851_Content_27 = {
    Text = "Ha, ha… wanita itu benar-benar berhati kecil, tak bisa menerima sepatah kata pun yang menghina Dewa-nya yang samar."
  },
  AvgDialog_23851_Content_28 = {
    Text = "Jelas-jelas hanya seorang pengecut yang tak berdaya dan tanpa belas kasihan… Haa!"
  },
  AvgDialog_23851_Content_29 = {
    Text = "Bayangan Ular dengan keras menarik leher Goliath, melengkungkan tulang punggung raksasa itu hingga membungkuk, dan memaksanya untuk mengambil posisi merangkak."
  },
  AvgDialog_23851_Content_3 = {
    Text = "Miryam membagikan kekuatan yang diberikan kepadanya, kepada kamu."
  },
  AvgDialog_23851_Content_30 = {
    Text = "Apakah hanya segini kemampuanmu!"
  },
  AvgDialog_23851_Content_31 = {
    Text = "Mengendalikanmu dengan keyakinan yang sulit dipahami, membiarkan Clades menghancurkan peradaban... Ha, pada akhirnya, Dia tidak pernah ada, itu hanyalah khayalanmu!"
  },
  AvgDialog_23851_Content_32 = {
    Text = "Bayangan ular tiba-tiba menyusut, Goliath batuk sekali dan menyemburkan beberapa tetes darah."
  },
  AvgDialog_23851_Content_33 = {
    Text = "Dia, apa ini?!"
  },
  AvgDialog_23851_Content_34 = {
    Text = "Sebuah hukuman kuno… yang digunakan di Lemuria untuk menghukum, menundukkan orang tanpa keyakinan dan para tahanan."
  },
  AvgDialog_23851_Content_35 = {
    Text = "Tulu memandang Goliath, yang masih menyeringai dengan senyum liar di wajahnya, lalu menghela napas."
  },
  AvgDialog_23851_Content_36 = {
    Text = "Apakah ini yang disiapkan oleh Miryam? \n … Tunggu! Jadi, ini berarti Miryam sudah tahu posisi kita?!"
  },
  AvgDialog_23851_Content_37 = {
    Text = "Ha, tidak perlu begitu gugup."
  },
  AvgDialog_23851_Content_38 = {
    Text = [[
Goliath menggunakan bilah raksasa untuk menopang tubuhnya, lalu bangkit dari tanah.
Dia menyeka bekas darah di wajahnya dengan punggung tangannya. Hukuman itu tampaknya hanya seperti gatal bagi kulitnya.]]
  },
  AvgDialog_23851_Content_39 = {
    Text = "Hanyalah sebuah rantai anjing yang dianggap berharga oleh orang sombong saja."
  },
  AvgDialog_23851_Content_4 = {
    Text = "Oh? Bagaimana mungkin kamu, si kurcaci ini..."
  },
  AvgDialog_23851_Content_40 = {
    Text = "Pergilah, sebelum aku menikmati pertunjukan yang cukup. Jangan sampai kalian dikalahkan oleh prajurit biasa yang kebetulan lewat."
  },
  AvgDialog_23851_Content_41 = {
    Text = "——Goliath, tunggu sebentar!"
  },
  AvgDialog_23851_Content_42 = {
    Text = "Oh? Ada urusan penting lainnya? Aku suka orang yang berani menantang otoritas. Sebelum aku kehilangan kesabaran, kau masih punya satu kesempatan untuk bertanya."
  },
  AvgDialog_23851_Content_43 = {
    Text = "Ramona... bagaimana kondisi partner saya sekarang? Apa yang akan kalian lakukan terhadapnya?"
  },
  AvgDialog_23851_Content_44 = {
    Text = [[
Ha... Saya ingin mengklarifikasi satu hal terlebih dahulu: aku tidak memiliki kebiasaan memakan wanita. 
Sementara ini, membiarkan dia tetap hidup adalah atas permintaan Miryam.]]
  },
  AvgDialog_23851_Content_45 = {
    Text = "\"Ibu Dewa\" saat ini... wadah untuk melahirkan dewa baru, hanyalah seorang anak kecil yang tidak signifikan. Dengan postur \"Ibu Dewa\" yang seperti itu, mustahil baginya untuk menahan tangisan pertama dari dewa baru."
  },
  AvgDialog_23851_Content_46 = {
    Text = "Bayangan ular lenyap tiba-tiba saat dia menghentikan hinaannya terhadap \"Dewa\". Dia memutar leher beberapa kali ke kiri dan kanan, lalu mengangkat pedang raksasa di pundaknya dan berbalik pergi tanpa sedikit pun ragu mengekspos punggungnya kepada kalian."
  },
  AvgDialog_23851_Content_47 = {
    Text = "——Sebelum dia berbalik, kamu dengan jelas melihatnya melirik ke arah peti kargo tempat Murphy bersembunyi."
  },
  AvgDialog_23851_Content_5 = {
    Text = [[
Keraguan Tulu baru saja terlihat, raksasa itu juga berhenti menyerang dengan ekspresi penuh pikiran. 
 Dia menyipitkan mata memandang Tulu dari atas ke bawah, pandangannya akhirnya tertuju pada mahkota yang mencolok itu.]]
  },
  AvgDialog_23851_Content_6 = {
    Text = "Mahkota ini berbentuk…!"
  },
  AvgDialog_23851_Content_7 = {
    Text = "Murid Goliath menyusut, menatap kalian dengan pandangan telanjang dan tajam, akhirnya dia tertawa terbahak-bahak tanpa rasa takut."
  },
  AvgDialog_23851_Content_8 = {
    Text = "Ha, hahahaha! Menarik, sangat menarik!"
  },
  AvgDialog_23851_Content_9 = {
    Text = "Jika wanita itu melihat adegan ini, ekspresi apa yang akan dia tunjukkan——tidak akan langsung gila kan? Hahahaha, aku sangat menantikan saat itu!"
  },
  AvgDialog_23852_Content_1 = {Text = "Mata Badai"},
  AvgDialog_23852_Content_10 = {
    Text = "Membuka mata, sakit kepala, tempat yang tidak dikenal."
  },
  AvgDialog_23852_Content_100 = {
    Text = [[
Tulu menyapu monster ikan lainnya keluar dari lambung kapal, lalu akhirnya menoleh ke arah kalian. 
 Dia meraih tepi pintu dengan tangannya, namun gerakan selanjutnya melampaui dugaanmu.]]
  },
  AvgDialog_23852_Content_101 = {
    Text = [[
Tidak apa-apa, kalian duluan bergabung dengan yang lain. 
 Aku perlu memastikan alasan mereka tidak menyerah untuk melaksanakan ritual.]]
  },
  AvgDialog_23852_Content_102 = {
    Text = "Pintu besi ditutup dengan keras, kamu dan gadis itu tiba-tiba terperangkap dalam kegelapan total."
  },
  AvgDialog_23852_Content_103 = {
    Text = "Gadis itu mendengus dengan nada tidak puas, lalu dengan cekatan memutar kerek dan mengunci pintu."
  },
  AvgDialog_23852_Content_104 = {
    Text = "Hu——seharusnya aman untuk sementara."
  },
  AvgDialog_23852_Content_105 = {
    Text = "Gadis itu menekan sakelar, lampu tua berkedip beberapa kali sebelum cahayanya menyebar ke segala arah, mengusir kegelapan."
  },
  AvgDialog_23852_Content_106 = {
    Text = "Dan akhirnya, kamu bisa melihat dengan jelas \"rumput laut\" di bawah tubuhmu."
  },
  AvgDialog_23852_Content_107 = {
    Text = [[
Tubuh dan roh seolah-olah tenggelam dalam lahar tergelap di Neraka, itu sama sekali bukan rumput laut.
Pangkal telapak tanganmu menekan ke dalam lumpur merah gelap yang bercampur dengan jaringan tak dikenal, terasa sangat sakit karena tulang yang hancur menggoresnya.]]
  },
  AvgDialog_23852_Content_108 = {
    Text = "Rune misterius telah terbaur oleh cairan, mirip dengan karpet berwarna mencolok di ruang dansa——ini jelas menunjukkan bahwa sebuah ritual keagamaan kecil pernah dilakukan di sini."
  },
  AvgDialog_23852_Content_109 = {
    Text = "Bau busuk menyebar di dalam kabin, kamu sangat yakin bahwa sisa-sisa ikan yang membusuk tidak cukup untuk menghasilkan bau sekuat ini. Dalam pesta tarian Caro ini, pasti ada penari yang lebih besar, dengan lebih banyak lemak."
  },
  AvgDialog_23852_Content_11 = {
    Text = "Berapa kali ini sudah terjadi? Apakah tidak ada pembuka yang lebih kreatif?"
  },
  AvgDialog_23852_Content_110 = {Text = "Ngh..."},
  AvgDialog_23852_Content_111 = {
    Text = "Sepertinya ini adalah hasil karya Pelaut, mereka memang tidak pernah terlalu mempermasalahkan hal-hal seperti ini…"
  },
  AvgDialog_23852_Content_112 = {
    Text = "Gadis itu bergumam, memandangmu yang terbaring di atas Altar dengan ekspresi jijik. Namun, setelah berjalan dua kali mengelilingimu, akhirnya dia menopang lenganmu yang masih bersih dan membantumu berdiri dengan satu tarikan."
  },
  AvgDialog_23852_Content_113 = {
    Text = [[
Dengan Tulu di sini, mereka seharusnya tidak punya waktu luang untuk mengejar kita dalam waktu dekat... 
 Aku akan mencari selembar kain untuk menutupi Altar ini, baunya sangat tidak sedap.]]
  },
  AvgDialog_23852_Content_114 = {
    Text = "Pelipis berdenyut sesuai dengan frekuensi ketukan, rasa sakit yang hebat mengoyak otak bagian kiri dan kananmu. Bau busuk menyebabkan asam lambung naik ke tenggorokan, hingga akhirnya kamu tak kuasa menahan diri dan membungkuk untuk muntah."
  },
  AvgDialog_23852_Content_115 = {
    Text = "Eh?! Apa yang terjadi padamu?! Jangan, jangan menakutiku!"
  },
  AvgDialog_23852_Content_116 = {
    Text = "Jangan mendekat!!"
  },
  AvgDialog_23852_Content_117 = {
    Text = "Aku bukan adik kecil, aku punya nama."
  },
  AvgDialog_23852_Content_118 = {
    Text = "Murphy, panggil aku Murphy."
  },
  AvgDialog_23852_Content_119 = {
    Text = "Wajah cemas sang gadis dan fragmen yang muncul di benaknya perlahan menyatu, dua adegan serupa namun berbeda juga bergabung menjadi satu gambar."
  },
  AvgDialog_23852_Content_12 = {
    Text = "Kamu berusaha keras untuk bangkit, dan pemandangan yang tak terduga tiba-tiba terpampang di hadapanmu."
  },
  AvgDialog_23852_Content_120 = {Text = "Murphy…?"},
  AvgDialog_23852_Content_121 = {
    Text = "Kamu... apakah kamu baik-baik saja? Apakah kamu merasa jijik karena Altar?"
  },
  AvgDialog_23852_Content_122 = {
    Text = "Dia mengitari kamu dua kali, lalu memanfaatkan sumber cahaya yang redup, berjinjit untuk memeriksa kondisimu."
  },
  AvgDialog_23852_Content_123 = {Text = "——!"},
  AvgDialog_23852_Content_124 = {
    Text = "Kenapa bisa jatuh seperti ini… \n Sepertinya ada sesuatu yang bisa digunakan di antara barang-barang ini…"
  },
  AvgDialog_23852_Content_125 = {
    Text = "Murphy bergumam dengan suara yang samar, bergerak kaku menuju tumpukan peti, lalu mulai mencari sesuatu."
  },
  AvgDialog_23852_Content_126 = {
    Text = "Tidak... kotak ini berisi perhiasan yang rusak."
  },
  AvgDialog_23852_Content_127 = {
    Text = "Kamu melihat sekilas, di sana terdapat sebuah perhiasan yang dihiasi dengan Sanga, mutiara, dan lapis lazuli, tampak sangat mahal. Sedangkan gaya desainnya yang misterius membuat orang merasa pusing hanya dengan melihatnya."
  },
  AvgDialog_23852_Content_128 = {
    Text = "… Sial, kenapa semuanya alat ritual."
  },
  AvgDialog_23852_Content_129 = {
    Text = "Di dalam peti kedua penuh dengan berbagai macam barang: mortir batu, daun salvia, myrrh... Orang yang tidak memiliki pengetahuan dasar tentang Alkimia mungkin hanya akan mengira ini adalah barang dagangan dari pedagang obat."
  },
  AvgDialog_23852_Content_13 = {
    Text = "Bulan purnama raksasa menggantung tinggi di langit malam, kabut tipis menyelimuti permukaan laut, bau mesiu dan garam dari air laut memenuhi rongga hidung."
  },
  AvgDialog_23852_Content_130 = {
    Text = "Ketemu! Cepat, jongkoklah."
  },
  AvgDialog_23852_Content_131 = {
    Text = "Salep menempel di bagian belakang kepala, dingin dengan sedikit sensasi pedas, yang hingga batas tertentu meredakan rasa sakit. Rambut saling menempel akibat efek salep, membuatmu tak tahan untuk mengangkat tangan dan merapikannya —"
  },
  AvgDialog_23852_Content_132 = {
    Text = "Eh! Jangan sembarangan menyentuh! Bukan racun, kok."
  },
  AvgDialog_23852_Content_133 = {
    Text = "Murphy berbicara sambil memberikanmu sebuah kaleng salep. Tidak ada formula atau nama obat yang tertulis di labelnya, hanya terdapat pola aneh yang digambar. Sepertinya ini adalah obat buatan sendiri."
  },
  AvgDialog_23852_Content_134 = {
    Text = "... Apakah ini déjà vu? Pola pada label tersebut, sepertinya pernah kulihat di suatu tempat."
  },
  AvgDialog_23852_Content_135 = {
    Text = "Sejak kecil, setiap kali saya mengalami luka luar, mereka selalu mengoleskan obat ini pada saya."
  },
  AvgDialog_23852_Content_136 = {
    Text = "Bagaimana, apakah setelah dioleskan langsung tidak terasa sakit lagi?"
  },
  AvgDialog_23852_Content_137 = {
    Text = "Dia sangat cemas karena kamu jatuh menuruni tangga dan terbentur kepala, tatapannya penuh dengan rasa bersalah."
  },
  AvgDialog_23852_Content_138 = {
    Text = "Hmm… sudah tidak terasa sakit lagi."
  },
  AvgDialog_23852_Content_139 = {
    Text = "Pelipis masih terasa nyeri, namun bagian belakang kepala memang terasa lebih nyaman."
  },
  AvgDialog_23852_Content_14 = {
    Text = "Suara ombak yang saling mendorong terdengar lembut dan teratur, mengangkat lambung kapal untuk bergerak perlahan, menuju destinasi yang tidak diketahui."
  },
  AvgDialog_23852_Content_140 = {
    Text = "Pandanganmu tanpa sadar tertuju pada \"Altar\" yang telah kamu hancurkan saat menabraknya. Murphy, yang khawatir kamu akan muntah lagi, sudah menutupi tempat itu dengan selembar kain."
  },
  AvgDialog_23852_Content_141 = {
    Text = "Pada saat itu, cairan merah tua dan hijau kelabu bercampur di atas kain rami, membentuk pola yang aneh. Bentuknya mirip belati yang unik, atau seperti bayi yang akan mengeluarkan tangisan pertamanya."
  },
  AvgDialog_23852_Content_142 = {
    Text = "Lihatlah, aku sudah bilang sangat efektif——"
  },
  AvgDialog_23852_Content_143 = {
    Text = "Setelah mendapatkan jawaban afirmatif, Murphy akhirnya merasa lega dan tersenyum. \n Melihat ekspresi rileksnya, sebuah suara di dalam hatimu memberitahu seperti ini ——"
  },
  AvgDialog_23852_Content_144 = {
    Text = "Dia adalah pusat badai, dan dia adalah jawaban dari semua pertanyaan."
  },
  AvgDialog_23852_Content_15 = {Text = "Di kapal?!"},
  AvgDialog_23852_Content_16 = {
    Text = "Tak diragukan lagi, kamu berada di kapal yang sedang berlayar di tengah lautan. Ramona tidak berada di sisimu, dan tidak ada tanda-tanda keberadaan siapa pun di sekitarmu."
  },
  AvgDialog_23852_Content_17 = {
    Text = "Tenang, tenang. \nMari kita pikirkan dari awal, mengapa aku bisa berada di kapal ini…"
  },
  AvgDialog_23852_Content_18 = {
    Text = "Herbert tentang... pola... catatan harian Francis... pelabuhan..."
  },
  AvgDialog_23852_Content_19 = {
    Text = "Jika sudah siap, ayo berangkat. Aku akan tetap menjadi pasanganmu seperti biasa."
  },
  AvgDialog_23852_Content_2 = {
    Text = "Penjaga! Jangan lepaskan tangan saya!"
  },
  AvgDialog_23852_Content_20 = {
    Text = "Kali ini... gereja... rahasia... kamu harus——"
  },
  AvgDialog_23852_Content_21 = {Text = "……Ugh!"},
  AvgDialog_23852_Content_22 = {
    Text = [[
Baru saja kamu mengingat beberapa gambar yang terfragmentasi, rasa sakit yang hebat langsung memotong memori-mu. 
 Asam lambung naik, membakar tenggorokanmu, dan udara segar saat ini menjadi barang mewah.]]
  },
  AvgDialog_23852_Content_23 = {
    Text = "Hu—— Aku dan Ramona meninggalkan sekolah bersama... Ya, Ramona, aku harus menemukan Ramona. \n Jika dia yang kutemui, dia pasti tahu apa yang terjadi."
  },
  AvgDialog_23852_Content_24 = {
    Text = "Tautan Komunikator"
  },
  AvgDialog_23852_Content_25 = {
    Text = "Ramona, apakah kamu bisa mendengarku? Di mana kamu?"
  },
  AvgDialog_23852_Content_26 = {
    Text = "Mengabaikan rasa sakit yang menjalar dari kedalaman Jiwa, kau seperti biasa mengoperasikan komunikator Perak."
  },
  AvgDialog_23852_Content_27 = {
    Text = "Pada saat itu, kamu baru menyadari bahwa <Yellow:brooch> yang melambangkan identitasmu tidak ada di kerah bajumu."
  },
  AvgDialog_23852_Content_28 = {
    Text = "Bagaimana bisa?!"
  },
  AvgDialog_23852_Content_29 = {
    Text = "Tenang, tenang…\nMasih ada cara, coba lacak Roh."
  },
  AvgDialog_23852_Content_3 = {
    Text = "Ujung hidung dipenuhi bau pahit setelah batubara terbakar habis. Dalam sekejap setelah bersentuhan, salah satu pihak ditarik keras oleh gravitasi ke jurang."
  },
  AvgDialog_23852_Content_30 = {
    Text = "Kamu menarik napas dalam-dalam, mengisyaratkan diri sendiri untuk mengabaikan ketidaknyamanan di seluruh tubuh, dan kembali tenggelam ke dalam kedalaman Roh."
  },
  AvgDialog_23852_Content_31 = {
    Text = "Dunia roh berkilauan dengan banyak bintik cahaya, setiap titik bintang mewakili sebuah jiwa yang hidup — jumlahnya jauh melebihi imajinasi kamu."
  },
  AvgDialog_23852_Content_32 = {
    Text = "Di kapal ternyata ada begitu banyak orang? Aneh..."
  },
  AvgDialog_23852_Content_33 = {
    Text = [[
Menekan rasa ingin tahu dan sedikit rasa takut yang tidak beralasan, kamu memusatkan perhatian pada dirimu sendiri. 
"Tautan"ibarat tali pusat yang kuat, menarik dua jiwa yang sangat cemerlang menuju dirimu.]]
  },
  AvgDialog_23852_Content_34 = {
    Text = "Dua tautan? Selain Ramona, apakah ada orang lain yang berpartisipasi dalam misi ini?"
  },
  AvgDialog_23852_Content_35 = {
    Text = "Pengamatanmu memicu riak, salah satu Gnosis tampaknya terganggu. Sebelum kamu bisa merasakannya lebih detail, Dia perlahan berputar beberapa kali, dan akhirnya mengunci posisimu."
  },
  AvgDialog_23852_Content_36 = {
    Text = "Rasa dingin yang tak terduga merayap di punggungmu, sebelum kamu sempat bereaksi, objek Tautan asing itu tiba-tiba menyerang ke arahmu!"
  },
  AvgDialog_23852_Content_37 = {
    Text = "Tidak sempat memikirkan siapa sebenarnya di ujung tautan, insting mendorongmu untuk menarik diri dari dunia roh dan melangkah ke arah yang berlawanan."
  },
  AvgDialog_23852_Content_38 = {Text = "——!"},
  AvgDialog_23852_Content_39 = {
    Text = "Secara kebetulan, badan kapal mengeluarkan suara jeritan tajam pada saat kau menapakkan kaki, seperti ratapan sedih dari raksasa baja yang sekarat, memberi isyarat bahwa ia akan segera kehilangan kekuatan untuk melawan lautan."
  },
  AvgDialog_23852_Content_4 = {
    Text = "Suara yang akrab dan kehangatan tubuh orang itu perlahan menjauh, sementara kelembapan dan dingin secara bertahap meresap di sepanjang tulang belakang."
  },
  AvgDialog_23852_Content_40 = {
    Text = [[
Dalam situasi seperti ini, menyelami dunia roh seakan-akan tidak ada krisis. 
Ceroboh, sombong.]]
  },
  AvgDialog_23852_Content_41 = {
    Text = "Tentakel yang lembut dan dingin seperti daging jeruk menghalangi tubuh yang hampir kehilangan keseimbangan, menopangmu dengan mantap di tempat."
  },
  AvgDialog_23852_Content_42 = {
    Text = "Yu tidak menyangka bahwa kau adalah orang yang begitu gegabah."
  },
  AvgDialog_23852_Content_43 = {Text = "Tulu?!"},
  AvgDialog_23852_Content_44 = {Text = "Kau……"},
  AvgDialog_23852_Content_45 = {
    Text = "Kenapa kamu belum tidur?"
  },
  AvgDialog_23852_Content_46 = {
    Text = "Pemuda Bangun menatapmu sekilas, pandangan tenang namun penuh wibawa tertuju padamu."
  },
  AvgDialog_23852_Content_47 = {
    Text = "Ucapan tidak hormat kali ini, aku anggap seolah-olah tidak pernah mendengarnya."
  },
  AvgDialog_23852_Content_48 = {
    Text = "Kenapa kamu juga ada di sini?"
  },
  AvgDialog_23852_Content_49 = {
    Text = "Pemuda Pembangun dengan cukup terkejut mengangkat alisnya, lalu memandangmu beberapa kali dengan tatapan penuh penilaian."
  },
  AvgDialog_23852_Content_5 = {
    Text = "Penjaga Rahasia!"
  },
  AvgDialog_23852_Content_50 = {
    Text = "Masih bisa bercanda, sepertinya kamu baik-baik saja."
  },
  AvgDialog_23852_Content_51 = {
    Text = "Tampaknya, hilangnya Tautan sesaat tadi hanyalah kebingungan singkat yang disebabkan oleh gangguan pada Gnosis."
  },
  AvgDialog_23852_Content_52 = {
    Text = [[
Sama seperti Lotan, Ogier, dan lainnya, Tulu adalah salah satu Pembangun yang diawasi oleh <Yellow:Mythag>. 
Namun, selama setahun berlatih di Mythag, kamu hanya bertemu dengannya beberapa kali.]]
  },
  AvgDialog_23852_Content_53 = {
    Text = "Konon, Tulu sebagian besar waktu berada dalam keadaan tidur, dan hanya terbangun beberapa kali saja. Membiarkannya bekerja sama dengan Penyelidik untuk menjalankan misi adalah sesuatu yang mustahil."
  },
  AvgDialog_23852_Content_54 = {
    Text = "Namun, pada saat ini, kalian terikat erat oleh <Yellow:Tautan> yang tak terlihat, dan Gnosis Tulu yang sangat kuat seperti badai terus-menerus menyapu bidang Roh kalian."
  },
  AvgDialog_23852_Content_55 = {
    Text = "Tautan menghilang? Tidak... pada akhirnya, apa sebenarnya yang terjadi dengan Tautan antara aku dan kamu? Dan kenapa kamu berada di luar kampus?"
  },
  AvgDialog_23852_Content_56 = {
    Text = [[
Pertanyaan bodoh. Sekarang bukan waktunya untuk bercanda, waktu yang tersisa untuk gadis itu sudah tidak banyak lagi. 
Pelaut masih belum menyerah untuk melaksanakan ritual pemanggilan roh, <Yellow:bintang-bintang sedang terbit menuju tempat yang seharusnya>.]]
  },
  AvgDialog_23852_Content_57 = {
    Text = "Gadis itu? Ritual pemanggilan roh?"
  },
  AvgDialog_23852_Content_58 = {
    Text = "Suasana di antara kamu dan Tulu tiba-tiba menjadi kaku. Setelah beberapa saat, dia menghela napas panjang, dan wajahnya menunjukkan ekspresi serius yang tidak sesuai dengan penampilannya yang masih muda dan polos."
  },
  AvgDialog_23852_Content_59 = {
    Text = "Berapa banyak yang masih kamu ingat?"
  },
  AvgDialog_23852_Content_6 = {
    Text = "Barusan itu... mimpi, ya?"
  },
  AvgDialog_23852_Content_60 = {
    Text = "Saya dan Ramona meninggalkan sekolah untuk melaksanakan tugas penyelidikan, sedangkan sisanya…"
  },
  AvgDialog_23852_Content_61 = {
    Text = "Kamu menggelengkan kepala. Kamu tidak tahu apakah ada pengaruh eksternal yang memengaruhimu, tetapi satu hal yang sangat kamu yakini: Tubuhmu sedang menghalangimu untuk mengingatnya."
  },
  AvgDialog_23852_Content_62 = {
    Text = "\"Bintang-bintang sedang terbit menuju tempat yang seharusnya\" — ini menunjukkan bahwa kamu mengetahui syarat-syarat ritual."
  },
  AvgDialog_23852_Content_63 = {
    Text = "Upacara pemanggilan roh——situasi apa ini sebenarnya? Dan dari mana asal makhluk ikan-ikan ini?"
  },
  AvgDialog_23852_Content_64 = {
    Text = "Meskipun aku tidak bisa mengingat dengan jelas apa yang sebenarnya terjadi, tautan ini pasti tidak berbohong. Kita seharusnya berada di kubu yang sama — Tulu, aku butuh kau memberitahuku apa yang sebenarnya terjadi."
  },
  AvgDialog_23852_Content_65 = {
    Text = "Tulu tampak sedikit lelah. Dia menutup matanya, seolah membutuhkan waktu untuk merapikan pikirannya."
  },
  AvgDialog_23852_Content_66 = {
    Text = [[
Tidak menyadari keanehanmu adalah kelalaian Yu. 
Terlibat dalam Acara seperti ini dalam wujud manusia, tampaknya memberikan pengaruh padamu.]]
  },
  AvgDialog_23852_Content_67 = {
    Text = [[
Namun, "upacara pemanggilan roh"adalah kata kunci yang terlalu sensitif bagi Penjaga Mythag.
Ketika kamu hendak mendesak lebih jauh, tentakel Tulu tiba-tiba melintang di depanmu.]]
  },
  AvgDialog_23852_Content_68 = {
    Text = "Seseorang mendekat, tingkatkan waspada."
  },
  AvgDialog_23852_Content_69 = {Text = "Plak..."},
  AvgDialog_23852_Content_7 = {
    Text = "Sudah pagi, ya..."
  },
  AvgDialog_23852_Content_70 = {
    Text = "Di antara langkah-langkah tergesa-gesa, terdengar suara aneh seperti kaki berselaput memukul tanah. Getaran halus terasa di bawah kaki, dan sebuah sosok dengan kasar berlari mendekatimu dari ujung dek lainnya."
  },
  AvgDialog_23852_Content_71 = {
    Text = "Guk... guk uh..."
  },
  AvgDialog_23852_Content_72 = {
    Text = "Wa——tolong——"
  },
  AvgDialog_23852_Content_73 = {
    Text = "Tolong aku!! %player%!"
  },
  AvgDialog_23852_Content_74 = {
    Text = "Gadis itu berlari ke arahmu, napasnya tersengal-sengal. Namun, ia menarik ujung jubahmu seperti seseorang yang sedang memegang erat jerami penyelamat."
  },
  AvgDialog_23852_Content_75 = {
    Text = "Masih…@2…@1 Ibu!@2!"
  },
  AvgDialog_23852_Content_76 = {
    Text = "Musuh-musuh dengan tubuh mirip manusia, namun memiliki ciri-ciri kehidupan air, mengeluarkan suara tangisan aneh. Suaranya tidak beraturan dan menusuk telinga, namun entah bagaimana kamu bisa memahami maksud mereka."
  },
  AvgDialog_23852_Content_77 = {
    Text = "Mereka berkata... \"Kembalikan kepada kami\"?"
  },
  AvgDialog_23852_Content_78 = {
    Text = "Dengungan yang kacau menjadi semakin jelas di telingamu. \n Hampir, hampir saja kamu bisa memahami apa yang mereka inginkan——"
  },
  AvgDialog_23852_Content_79 = {
    Text = "Saat kamu terpaku karena hal itu, gadis itu tiba-tiba menginjak sepatumu dengan keras."
  },
  AvgDialog_23852_Content_8 = {
    Text = [[
Setiap tulang terasa seperti telah dihancurkan dan disusun kembali, tubuh dipenuhi dengan kelelahan yang tak semestinya. 
 Pelipis terasa nyeri, mata juga terasa kering seolah-olah ada jarum yang menusuk.]]
  },
  AvgDialog_23852_Content_80 = {
    Text = "Ssshh——"
  },
  AvgDialog_23852_Content_81 = {
    Text = "Apa kau hanya akan melihat saja! Lakukan sesuatu!"
  },
  AvgDialog_23852_Content_82 = {
    Text = "Dan kamu juga! Jangan menatapku, fokuslah pada tuan putri ini! Hati-hati agar tidak tertangkap oleh mereka."
  },
  AvgDialog_23852_Content_83 = {
    Text = "Tulu memalingkan wajahnya, tidak lagi melihatmu dan sang gadis. Tentakel-tentakelnya bergerak dengan kuat, menyapu musuh-musuh yang terus berdatangan satu per satu keluar dari kapal."
  },
  AvgDialog_23852_Content_84 = {
    Text = "Masih ada bala bantuan, mereka datang untukmu."
  },
  AvgDialog_23852_Content_85 = {
    Text = "Gadis itu menutup bibirnya sejenak, lalu matanya berbinar sesaat kemudian, menampilkan ekspresi seperti mendapatkan inspirasi tiba-tiba."
  },
  AvgDialog_23852_Content_86 = {
    Text = "Pergi ke kabin! Kita bisa bersembunyi dari mereka untuk sementara."
  },
  AvgDialog_23852_Content_87 = {
    Text = "Gadis itu melangkah beberapa langkah ke belakang tanpa menghiraukan sekitarnya, dan kamu buru-buru mengikuti sambil melindunginya. Tampak olehmu dia menendang beberapa papan kayu, dan di geladak itu tiba-tiba terlihat sebuah pintu bawah tanah."
  },
  AvgDialog_23852_Content_88 = {
    Text = "Pintu Gelap?!"
  },
  AvgDialog_23852_Content_89 = {
    Text = "Apa pintu rahasia? Apakah kamu benar-benar harus bercanda dengan nona ini di saat yang krusial seperti ini!"
  },
  AvgDialog_23852_Content_9 = {
    Text = "Tenggorokan terasa seperti baru saja menelan seteguk besar saus Worcester, setiap napas membawa rasa sesak dan nyeri yang menyengat."
  },
  AvgDialog_23852_Content_90 = {
    Text = "Lagipula bukan belum pernah masuk ke kabin kapal, jangan banyak bicara, bersiaplah!"
  },
  AvgDialog_23852_Content_91 = {
    Text = "Tulu tidak menentang rencana sang gadis. Dengan diamnya sebagai perlindungan, kamu dan gadis itu bersama-sama membuka gerbang besi."
  },
  AvgDialog_23852_Content_92 = {
    Text = "Di bawah ambang pintu, tangga besi membentang ke bawah, menghilang ke dalam kegelapan yang tak terlihat."
  },
  AvgDialog_23852_Content_93 = {
    Text = "Cepat! Turun dulu!"
  },
  AvgDialog_23852_Content_94 = {
    Text = "Kamu tidak memiliki kemampuan pertempuran, aku memiliki kewajiban melindungimu——Ah!"
  },
  AvgDialog_23852_Content_95 = {
    Text = "Gadis itu berpura-pura tidak mendengar omelanmu. Dia memanfaatkan tubuhnya yang mungil untuk dengan lincah mengitari dan bergerak ke belakangmu."
  },
  AvgDialog_23852_Content_96 = {
    Text = "—— Lalu, dengan keras menendangmu masuk ke dalam lubang pintu yang gelap."
  },
  AvgDialog_23852_Content_97 = {
    Text = "<SmallShake:Aduh aduh aduh…>"
  },
  AvgDialog_23852_Content_98 = {
    Text = "Sepertinya kamu jatuh ke dalam seikat rumput laut yang lembut. Bau amis ikan dan rasa asin air laut langsung memenuhi rongga hidungmu, membuat kepalamu yang sudah terasa tumpul semakin pusing dan berputar-putar."
  },
  AvgDialog_23852_Content_99 = {
    Text = "Hei! Jangan terus menahan beban, cepat turun!"
  },
  AvgDialog_23853_Content_1 = {
    Text = "Dalam sekejap, orang itu sudah menghilang… \n Melanjutkan pencarian seperti ini bukanlah solusi. Kalau begitu, mungkin lebih baik aku mencari Ramona dulu…"
  },
  AvgDialog_23853_Content_2 = {
    Text = "Tidak, dia tidak bisa pergi!"
  },
  AvgDialog_23853_Content_3 = {
    Text = "Khe... Maksudku, mungkin dia memiliki kunci untuk memecahkan misteri Pelaut."
  },
  AvgDialog_23853_Content_4 = {
    Text = "Dari tingkat keakrabannya dengan para Pelaut, dia pasti mengetahui tujuan mereka."
  },
  AvgDialog_23853_Content_6 = {
    Text = [[
Baik, selanjutnya saya akan mencoba menggunakan penelusuran Roh untuk menemukannya. 
Ini adalah pertama kalinya saya menggunakan penelusuran Roh untuk melacak manusia, jadi tidak ada jaminan bahwa itu akan berhasil.]]
  },
  AvgDialog_23854_Content_1 = {Text = "Belati"},
  AvgDialog_23854_Content_10 = {
    Text = "Jujur saja, bahkan nama kamu baru saja kuingat."
  },
  AvgDialog_23854_Content_11 = {
    Text = [[
...Ah! Jangan-jangan kamu terbentur kepala saat aku menendangmu ke bawah!
Sial, kenapa harus terjadi masalah sekarang...]]
  },
  AvgDialog_23854_Content_12 = {
    Text = "Murphy dengan gelisah menggaruk kepalanya, tampaknya juga tidak tahu harus berbuat apa."
  },
  AvgDialog_23854_Content_13 = {
    Text = "Penyebab dan akibatnya… terlalu rumit untuk dijelaskan. Tempat ini juga bukan tempat yang sangat aman, jadi kita harus segera bertemu dengan yang lain."
  },
  AvgDialog_23854_Content_14 = {
    Text = "Siapa yang dimaksud dengan \"orang lain\"?"
  },
  AvgDialog_23854_Content_15 = {
    Text = "Para kapten kapal Sonnelier, dan Ramona."
  },
  AvgDialog_23854_Content_16 = {
    Text = "Benar! Bisakah kamu mencoba lagi yang itu? Metode untuk mencari seseorang di Dunia roh."
  },
  AvgDialog_23854_Content_17 = {
    Text = [[
Penelusuran Roh? Kau tidak hanya mengenal Ramona dan Tulu, bahkan tahu bahwa aku bisa melakukan penelusuran roh... 
Apa sebenarnya yang terjadi sebelumnya?]]
  },
  AvgDialog_23854_Content_18 = {
    Text = "Jangan berlama-lama! Kamu cari dulu posisi Ramona, di jalan aku akan menjelaskan pelan-pelan."
  },
  AvgDialog_23854_Content_19 = {
    Text = "Proses tenggelam ke dalam dunia roh terasa lebih menyakitkan daripada sebelumnya, roh seperti melewati semak berduri, setiap bagian terasa nyeri yang halus dan menyiksa. Dan ketika akhirnya kamu melihat bintik cahaya yang familiar ——"
  },
  AvgDialog_23854_Content_2 = {
    Text = "Tulu berkata bahwa kita harus bertemu dengan yang lain terlebih dahulu… Hmph, dia menganggapnya begitu mudah."
  },
  AvgDialog_23854_Content_20 = {
    Text = "Pletak——"
  },
  AvgDialog_23854_Content_21 = {Text = "Ukh……!"},
  AvgDialog_23854_Content_22 = {
    Text = "Ujung-ujung Roh baru saja merambat ke tepi ruang spiritual, lalu putus satu per satu seperti sulur pohon yang kering."
  },
  AvgDialog_23854_Content_23 = {
    Text = "Rasa sakit yang begitu hebat hingga bisa merobek jiwa dan tubuh menembus pelipis, membuatmu jatuh di depan Murphy."
  },
  AvgDialog_23854_Content_24 = {
    Text = "Eh, eh?! Jangan menakutiku, jangan mati ya?!"
  },
  AvgDialog_23854_Content_25 = {
    Text = "Aku... aku tidak apa-apa..."
  },
  AvgDialog_23854_Content_26 = {
    Text = "Melacak roh selalu menjadi keahlian utamamu, namun saat ini tubuhmu tampaknya menghalangi perjalananmu di dunia roh."
  },
  AvgDialog_23854_Content_27 = {
    Text = "Kamu sangat yakin: yang mengusirmu dari dunia roh adalah tubuhmu sendiri, bukan entitas misterius lainnya."
  },
  AvgDialog_23854_Content_28 = {
    Text = "@2…Guh uhh…"
  },
  AvgDialog_23854_Content_29 = {
    Text = [[
Suara Pelaut, mereka telah menemukan kita! 
 Kita tidak bisa tinggal di sini lebih lama, ikuti aku.]]
  },
  AvgDialog_23854_Content_3 = {
    Text = [[
Murphy bergumam sambil berputar-putar di ruang kargo, ekspresinya dipenuhi kegelisahan. 
 Kamu menarik napas dalam-dalam dan memanggilnya.]]
  },
  AvgDialog_23854_Content_30 = {
    Text = "Murphy dengan susah payah menopangmu, berat badanmu membuat kedua kakinya gemetar. Melihat hal itu, kau sedikit memindahkan pusat gravitasi tubuhmu ke arah kabin, sehingga akhirnya, dengan bantuannya, kau bisa berjalan menuju bagian dalam kapal…"
  },
  AvgDialog_23854_Content_31 = {
    Text = "Kalian berhenti di depan sebuah pintu besi tebal dengan lekukan dan tonjolan aneh. Dari celah pintu yang sudah tidak bisa tertutup sepenuhnya, tercium bau menyengat seperti sesuatu yang terbakar."
  },
  AvgDialog_23854_Content_32 = {
    Text = "Murphy, apakah kita akan masuk?"
  },
  AvgDialog_23854_Content_33 = {
    Text = "Shh, biarkan aku mendengarkan…"
  },
  AvgDialog_23854_Content_34 = {
    Text = "Murphy dengan hati-hati melepaskanmu, lalu menempelkan telinganya di pintu dan mendengarkan dengan mata tertutup selama beberapa saat."
  },
  AvgDialog_23854_Content_35 = {
    Text = "Sepertinya tidak ada orang, kita bersembunyi dulu di dalam."
  },
  AvgDialog_23854_Content_36 = {
    Text = "Sebelum Murphy mendorong pintu terbuka, kamu melihat sekilas label di atas pintu — \"Ruang Kekuatan\"."
  },
  AvgDialog_23854_Content_37 = {
    Text = "Di balik pintu tidak ada pemandangan yang kamu bayangkan: tidak ada pekerja dengan otot kekar, tidak ada boiler yang menyala terang, hanya percikan api yang beterbangan ke mana-mana dan sulit diabaikan."
  },
  AvgDialog_23854_Content_38 = {
    Text = "Di tanah tergeletak tak terhitung banyaknya tubuh yang dingin dan keras — itu adalah monster ikan yang mengejar kalian sepanjang jalan."
  },
  AvgDialog_23854_Content_39 = {
    Text = "Murphy dan Tulu menyebut mereka sebagai \"<Yellow:Pelaut>\"."
  },
  AvgDialog_23854_Content_4 = {Text = "Murphy."},
  AvgDialog_23854_Content_40 = {
    Text = "Dinding kapal terbuka dengan lubang besar, angin dingin berhembus masuk ke kabin satu per satu. Murphy mencubit cuping telinganya yang membeku hingga memerah, lalu menuntunmu melewati api, melangkah ke dalam reruntuhan."
  },
  AvgDialog_23854_Content_41 = {
    Text = "Hek, hek hek hek… Bau ini sangat tidak sedap."
  },
  AvgDialog_23854_Content_42 = {
    Text = "Di sini... apakah pernah terjadi pertempuran sengit?"
  },
  AvgDialog_23854_Content_43 = {
    Text = "Pertempuran sengit? Apakah kau menggunakan kata se-ringan itu untuk menggambarkan pertempuran itu?"
  },
  AvgDialog_23854_Content_44 = {
    Text = "Oh... Ngomong-ngomong, kamu masih belum tahu apa yang terjadi."
  },
  AvgDialog_23854_Content_45 = {
    Text = "Di antara reruntuhan, ada sesuatu yang memantulkan cahaya yang menyolok."
  },
  AvgDialog_23854_Content_46 = {
    Text = "Kamu belum sempat melihat dengan jelas apa itu, ketika Murphy berubah ekspresi, tampak seperti takut sekaligus sedih."
  },
  AvgDialog_23854_Content_47 = {
    Text = "Entah sejak kapan, wanita itu berubah menjadi seperti ini... gila-gilaan."
  },
  AvgDialog_23854_Content_48 = {
    Text = "Dia menarik sudut bibirnya, sambil tanpa aturan menceritakan \"masa lalu\" kepadamu, dan melangkah menuju kilauan di antara reruntuhan."
  },
  AvgDialog_23854_Content_49 = {
    Text = "Dia tidak mendengarkan apa pun. Tidak peduli bagaimana aku memohon kepadanya, dia tetap bersikeras untuk melaksanakan ritual ini…"
  },
  AvgDialog_23854_Content_5 = {
    Text = "Lebih baik aku mencari pojokan untuk berjongkok saja..."
  },
  AvgDialog_23854_Content_50 = {
    Text = "——Kilauan itu adalah sebuah belati dengan bentuk yang aneh, tergeletak diam di antara sisa-sisa abu api yang telah padam. Meskipun badan belati tertutup debu, ketajaman ujungnya tetap terlihat jelas."
  },
  AvgDialog_23854_Content_51 = {
    Text = "Jelas... dia dulu sangat baik padaku..."
  },
  AvgDialog_23854_Content_52 = {
    Text = "Murphy menatap belati itu sejenak, lalu tiba-tiba merangkak dengan tangan dan kakinya ke dalam reruntuhan yang bertumpuk, berusaha meraih belati tersebut."
  },
  AvgDialog_23854_Content_53 = {
    Text = "Guh... guh..."
  },
  AvgDialog_23854_Content_54 = {
    Text = "Di antara para Pelaut yang terbaring lemas, salah satu dari mereka menopang tubuhnya dengan senjata patah, berdiri dengan gemetar, dan menatap Murphy di tempat tinggi dengan bola mata yang hampir keluar dari rongganya."
  },
  AvgDialog_23854_Content_55 = {
    Text = "Kenapa… kenapa…… dari sisi Imam Agung…… kenapa?"
  },
  AvgDialog_23854_Content_56 = {
    Text = "Ibu Dewa, Ibu Dewa… guk, guk…! Aku menemukan Ibu Dewa!"
  },
  AvgDialog_23854_Content_57 = {
    Text = "Pemimpin Upacara, Pemimpin Upacara! Upacara akan segera dimulai, <Big:Upacara akan segera dimulai!>"
  },
  AvgDialog_23854_Content_58 = {
    Text = "Rahang bawah ikan Pelaut membuka hingga batas maksimal, dan jaringan membran daging Tautan yang menghubungkan rahang atas dan bawah teregang hingga menjadi semi-transparan."
  },
  AvgDialog_23854_Content_59 = {
    Text = [[
Dorongan dari rasa takut, harapan, dan keyakinan membuatnya memancarkan vitalitas hidup yang luar biasa. 
Pelaut tiba-tiba menabrakmu dan berlari menuju ruang kekuatan sambil berteriak keras.]]
  },
  AvgDialog_23854_Content_6 = {
    Text = "<BigShake:Murphy! Ada sesuatu yang harus aku katakan padamu!>"
  },
  AvgDialog_23854_Content_60 = {
    Text = "Buruk, dia akan melarikan diri!"
  },
  AvgDialog_23854_Content_61 = {
    Text = "Ciiiiiiiiisssssss——"
  },
  AvgDialog_23854_Content_62 = {
    Text = "Ujung yang tajam menembus keluar dari dada abu-abu kebiruan, cairan berhamburan, dan Pelaut pun jatuh dengan suara keras."
  },
  AvgDialog_23854_Content_63 = {
    Text = "Murphy entah sejak kapan telah berjaga di sisi pintu Ruang Kekuatan, darah kental berwarna abu-abu kehijauan perlahan menetes dari ujung belati di tangannya."
  },
  AvgDialog_23854_Content_64 = {
    Text = "Di atasnya tergantung serpihan kain, ukiran yang cekung dipenuhi oleh Caro. Tubuh Murphy terlihat gemetar dengan jelas, namun tangan yang memegang pisau tetap sangat teguh dan kuat."
  },
  AvgDialog_23854_Content_65 = {
    Text = "...Maaf, aku tidak bisa membiarkanmu pergi."
  },
  AvgDialog_23854_Content_66 = {
    Text = "Murphy menundukkan pandangannya, menatap belati selama beberapa saat, lalu menghapus darah Pelaut yang menempel di atasnya."
  },
  AvgDialog_23854_Content_67 = {
    Text = "Reaksinya adalah ingin melaporkan berita..."
  },
  AvgDialog_23854_Content_68 = {
    Text = "Murphy bersandar di samping pintu, melirik ke arah Ruang Kekuatan yang berantakan, bulu matanya bergerak gelisah."
  },
  AvgDialog_23854_Content_69 = {
    Text = "Apa <Blue:Miryam> bukankah sudah… kenapa masih belum menyerah…"
  },
  AvgDialog_23854_Content_7 = {
    Text = "Jangan berteriak begitu keras! Bagaimana jika benar-benar menarik perhatian Pelaut!"
  },
  AvgDialog_23854_Content_70 = {
    Text = "Nama yang diucapkan Murphy dengan gumaman membuatmu merasa pusing tanpa alasan. Kau berkedip, menunggu rasa mual dan tidak nyaman berlalu, lalu mengajukan pertanyaan yang ada di benakmu."
  },
  AvgDialog_23854_Content_71 = {
    Text = "Miryam adalah?"
  },
  AvgDialog_23854_Content_72 = {
    Text = "Dia adalah Pelaut… yaitu pemimpin dari makhluk ikan ini."
  },
  AvgDialog_23854_Content_73 = {
    Text = "Yang disebut \"Ibu Dewa\"…"
  },
  AvgDialog_23854_Content_74 = {
    Text = "Begitu pertanyaan keluar, kamu langsung menelan ludah beberapa kali dengan gerakan mekanis karena gugup."
  },
  AvgDialog_23854_Content_75 = {
    Text = "Tubuhmu sepertinya sudah mengetahui jawabannya sejak awal, namun alam bawah sadarmu takut untuk mengingatkanmu akan jawaban itu."
  },
  AvgDialog_23854_Content_77 = {
    Text = "Murphy menatap ke arahmu, dengan aliran kesedihan yang tersembunyi di matanya."
  },
  AvgDialog_23854_Content_78 = {Text = "Ini aku."},
  AvgDialog_23854_Content_79 = {
    Text = "Saya adalah orang malang yang dirasuki oleh monster, dan merupakan pembawa takdir dalam kelahiran kembali Dewa sesat."
  },
  AvgDialog_23854_Content_8 = {
    Text = "Katakanlah, ada apa?"
  },
  AvgDialog_23854_Content_80 = {
    Text = "Aku... adalah \"Ibu Suci\" dari Ordo Pelaut."
  },
  AvgDialog_23854_Content_81 = {
    Text = "Begitu kata terakhir keluar dari mulut Murphy, cahaya putih meledak di depan mata disertai rasa sakit yang luar biasa."
  },
  AvgDialog_23854_Content_82 = {
    Text = "Halo?! Halo! %player%?!"
  },
  AvgDialog_23854_Content_83 = {
    Text = "Tubuh tidak terkendali jatuh ke belakang, suara dengungan frekuensi rendah berputar di sekitar telinga, teriakan gadis itu tenggelam dalam gelombang rasa sakit."
  },
  AvgDialog_23854_Content_84 = {
    Text = "Di ujung cahaya putih, ada pandangan yang samar-samar seolah-olah sedang mengamati kamu."
  },
  AvgDialog_23854_Content_85 = {
    Text = "Keberadaan yang tak dikenal itu tampaknya sedang menilaimu, menilai apakah tengkorakmu yang retak layak untuk disatukan kembali, dan menilai apakah jiwa yang tercerai-berai dapat ditenun ulang."
  },
  AvgDialog_23854_Content_86 = {
    Text = "Kamu membuka mata lebar-lebar, kesadaranmu terlepas dari tubuh…"
  },
  AvgDialog_23854_Content_9 = {
    Text = [[
Saya... agak bingung dengan apa yang terjadi. 
Kenapa saya ada di kapal, dan kenapa saya mengenal kamu...]]
  },
  AvgDialog_23855_Content_1 = {
    Text = "Murphy, jangan lari! Kami bukan orang jahat!"
  },
  AvgDialog_23855_Content_2 = {
    Text = "Mana ada penjahat yang akan mengakui dirinya sebagai penjahat!"
  },
  AvgDialog_23855_Content_3 = {
    Text = "Bocah ini sudah bisa melihat fungsi rune, bagaimana kalian masih berani mengatakan bahwa kalian dan Pelaut bukan satu kelompok!"
  },
  AvgDialog_23855_Content_4 = {
    Text = "Itu adalah mantra yang ditulis dengan Lomoria kuno, siapa pun yang memahami bahasa Lomoria tidak ada alasan untuk tidak dapat membaca rune tersebut."
  },
  AvgDialog_23855_Content_5 = {
    Text = "Apakah kamu masih ingat, Lemuria adalah peradaban yang hilang sebelum kelahiran sejarah manusia. Bahkan di Universitas Mythag, jumlah makalah penelitian terkait Lemuria bisa dihitung dengan satu tangan."
  },
  AvgDialog_23855_Content_6 = {
    Text = "……Hmph."
  },
  AvgDialog_23855_Content_7 = {
    Text = "Ayo, kejar dia!"
  },
  AvgDialog_23856_Content_1 = {
    Text = "Realitas yang terdistorsi"
  },
  AvgDialog_23856_Content_10 = {
    Text = "Apa, apa yang kalian lakukan? Kenapa tiba-tiba menatapku seperti ini? Apa maksud dari tatapan kalian berdua?"
  },
  AvgDialog_23856_Content_100 = {
    Text = "Goliath… kamu…"
  },
  AvgDialog_23856_Content_101 = {
    Text = "Kenapa... kenapa kau memberitahuku semua ini?"
  },
  AvgDialog_23856_Content_102 = {
    Text = "Berkemurungan bukanlah hal yang baik, ingatlah bahwa Negaramu menentukan pertumbuhan \"dewa\"."
  },
  AvgDialog_23856_Content_103 = {
    Text = "Pergeseran bintang selaras berikutnya akan terjadi dua puluh lima tahun lagi. Aku memperkirakan, Miryam akan datang dalam dua hari ini untuk membuatmu tertidur."
  },
  AvgDialog_23856_Content_104 = {
    Text = "Lakukan apa pun yang kamu sukai, buat kerusakan, cambuk Pelaut, siksa pelayanmu… terserah apa saja."
  },
  AvgDialog_23856_Content_105 = {
    Text = "Goliath secara sepihak mengakhiri percakapan ini, tanpa emosi menepuk puncak kepalanya."
  },
  AvgDialog_23856_Content_106 = {
    Text = "Saat pergi, dia melirik patung kayu yang dilemparkan Murphy ke sudut dinding. Keterampilan gadis itu sangat buruk; bentuk di atas alas kayu tampak besar dan aneh, membuat siapa pun merasa jengkel hanya dengan melihatnya sekilas."
  },
  AvgDialog_23856_Content_107 = {Text = "Cih."},
  AvgDialog_23856_Content_108 = {
    Text = "Setelah Goliath pergi, ruangan itu menjadi sepenuhnya sunyi. Bahkan korban-korban yang menunggu di dalam sangkar tidak mengeluarkan suara sedikit pun."
  },
  AvgDialog_23856_Content_109 = {
    Text = "Murphy duduk di samping api unggun untuk waktu yang lama, sampai cahayanya mulai meredup dan api unggun hampir padam. Barulah ia seperti tersadar dari mimpi dan menepuk pipinya sendiri."
  },
  AvgDialog_23856_Content_11 = {
    Text = "Kamu bisa mengetahui bahwa orang yang datang adalah Goliath hanya dari suara langkah kakinya, dan sebelumnya, ucapan serta tindakanmu sudah menunjukkan bahwa kamu sangat mengenal Miryam."
  },
  AvgDialog_23856_Content_110 = {
    Text = "Dia menendang keras sangkar di sampingnya, mengingat kembali wanita yang beberapa bulan lalu merusak ritual itu… wanita yang dengan keteguhan kuat berhasil melarikan diri dari tangan Miryam."
  },
  AvgDialog_23856_Content_113 = {
    Text = "\"Maafkan aku…\"\n\"Aku… tidak ingin mati…\""
  },
  AvgDialog_23856_Content_115 = {
    Text = "Aku juga tidak ingin... semuanya berakhir seperti ini..."
  },
  AvgDialog_23856_Content_12 = {
    Text = "Kamu sangat memahami organisasi \"Pelaut\", kamu adalah bagian dari \"Pelaut\", bahkan menempati posisi tinggi… atau bisa dibilang, mereka datang untukmu."
  },
  AvgDialog_23856_Content_13 = {
    Text = "Apakah kamu \"Ibu Dewa\" yang disebutkan oleh Pelaut, wadah yang melahirkan dewa baru…, benar?"
  },
  AvgDialog_23856_Content_14 = {
    Text = "<Big:Aku tidak!>"
  },
  AvgDialog_23856_Content_15 = {
    Text = "Lalu bagaimana kamu bisa menjelaskan keakrabanmu dengan Goliath dan Miryam, serta penghindaranmu terhadap Pelaut?"
  },
  AvgDialog_23856_Content_16 = {
    Text = "Aku hanya... pelayan... pelayan biasa di markas ordo. Gadis seperti aku jumlahnya tak terhitung."
  },
  AvgDialog_23856_Content_17 = {
    Text = "Dalam kelompok pelaut, penampilan manusia seharusnya sangat langka. Jika tidak, berdasarkan kekuatan tempur mereka, mereka tidak perlu bekerja sama dengan Gereja penerang kuil."
  },
  AvgDialog_23856_Content_18 = {
    Text = "Jika kamu hanyalah seorang pelayan manusia yang tidak penting, mengapa mereka begitu gigih mengejarmu?"
  },
  AvgDialog_23856_Content_19 = {
    Text = "Semua ini, ini hanya..."
  },
  AvgDialog_23856_Content_2 = {
    Text = "Murphy, Murphy?"
  },
  AvgDialog_23856_Content_20 = {
    Text = "Murphy, aku perlu tahu apa yang terjadi."
  },
  AvgDialog_23856_Content_21 = {
    Text = "Hanya dengan cara ini, kita memiliki kesempatan untuk bertahan hidup, dan kita bisa membantu kamu."
  },
  AvgDialog_23856_Content_23 = {
    Text = "Baiklah……"
  },
  AvgDialog_23856_Content_25 = {
    Text = "Burung muda yang sayapnya patah jatuh ke dalam kolam air hitam."
  },
  AvgDialog_23856_Content_26 = {
    Text = "Doa sang pemimpin ritual terdengar samar namun tegas, kata-katanya yang penuh semangat menembus cairan hitam kental, berubah menjadi belati yang membelah rongga dada burung muda."
  },
  AvgDialog_23856_Content_27 = {
    Text = "Cairan berwarna merah segar muncul di atas dada, mekar dengan memesona di permukaan air hitam yang tenang——"
  },
  AvgDialog_23856_Content_28 = {
    Text = "Namun, dia terus tenggelam, akar yang berlumuran darah membawanya ke dalam kedalaman terdalam, ke dalam pelukan yang lembut namun dingin."
  },
  AvgDialog_23856_Content_3 = {
    Text = "Tidak perlu bersembunyi lagi, Goliath sudah cukup jauh."
  },
  AvgDialog_23856_Content_30 = {
    Text = "……………"
  },
  AvgDialog_23856_Content_31 = {
    Text = [[
Dia melihatnya. 
Dia menengadah, "Ibu" menurunkan tiga pasang tangkai mata, saling bertatapan dengannya.]]
  },
  AvgDialog_23856_Content_32 = {
    Text = [[
Itu adalah benda raksasa berwarna merah tua, bagian yang terkena darah tampak transparan putih. 
 "Ibu"memancarkan cahaya redup, untuk sementara menerangi sepetak kecil dunia.]]
  },
  AvgDialog_23856_Content_33 = {
    Text = "Dengan bantuan cahaya, dia melihat bahwa di atas permukaan yang halus dari \"ibunya\", tersebar luka-luka hitam yang tak terhitung jumlahnya, besar dan kecil."
  },
  AvgDialog_23856_Content_34 = {
    Text = "\"Maafkan aku...\""
  },
  AvgDialog_23856_Content_35 = {
    Text = "Lumpur hitam bergelombang, menghancurkan ketenangan di dasar pantai."
  },
  AvgDialog_23856_Content_36 = {
    Text = "\"Ibu\"mengeluarkan suara merdu yang menyayat hati, tentakel-tentakelnya bergerak cepat, memasukkan sesuatu ke dalam rongga dada burung muda."
  },
  AvgDialog_23856_Content_37 = {
    Text = "Jalinan-jalinan lunak yang licin dan dingin melilitnya, air kolam hitam tidak lagi menyumbat mulut dan hidungnya, melainkan seperti cairan ketuban, menopang hidupnya."
  },
  AvgDialog_23856_Content_38 = {
    Text = "\"Maafkan aku……\"\n\"Aku……belum ingin mati……\""
  },
  AvgDialog_23856_Content_39 = {
    Text = "Permukaan air tetap tenang untuk waktu yang lama, bahkan angin yang menderu dari kutub tidak mampu membuat riak pada kolam yang kental."
  },
  AvgDialog_23856_Content_4 = {
    Text = "Benar, apakah benar?"
  },
  AvgDialog_23856_Content_40 = {
    Text = "Miryam-sama, apakah Saintess sudah..."
  },
  AvgDialog_23856_Content_41 = {
    Text = "Dia lahir pada <Blue:Momen Bintang Selaras sebelumnya>, seorang anak yang \"dapat melihat\"."
  },
  AvgDialog_23856_Content_42 = {
    Text = "Di dunia ini, tidak ada seorang pun yang lebih layak mendapatkan pengakuan dari darah dewa selain dia."
  },
  AvgDialog_23856_Content_43 = {
    Text = [[
Wanita yang kurus itu dikelilingi oleh kerumunan, berdiri di tempat tertinggi yang bisa menatap rendah semua orang. 
 Kain tipis mengaburkan wajahnya, bahkan pelayan dekatnya pun tak mampu membaca apa yang ada di pikiran tuannya.]]
  },
  AvgDialog_23856_Content_44 = {Text = "Murphy…"},
  AvgDialog_23856_Content_45 = {
    Text = "Seiring dengan gumaman rendah, seolah-olah energi dari dalam bumi akan segera menyembur keluar, permukaan air tiba-tiba mulai mendidih."
  },
  AvgDialog_23856_Content_46 = {
    Text = "Air hitam yang kental dan pekat meluap dari tepi kolam, membanjiri mata kaki semua orang, dan mengalir hingga ke kaki telanjang wanita itu."
  },
  AvgDialog_23856_Content_47 = {
    Text = "Menyusuri kerumunan pemuda yang berbisik kaget, dia melangkah dalam diam di jalan yang dipenuhi cairan hitam, lalu mencelupkan kedua tangannya dalam-dalam ke dalam air kolam itu——"
  },
  AvgDialog_23856_Content_48 = {Text = "——Wah"},
  AvgDialog_23856_Content_49 = {
    Text = [[
Gadis itu meloncat keluar dari kolam dengan bertumpu pada kedua tangannya. 
 Cairan hitam mengalir menuruni kontur wajahnya, mirip seperti dua jejak air mata yang mengerikan.]]
  },
  AvgDialog_23856_Content_5 = {
    Text = [[
Tidak apa-apa, para pelaut di dek juga mengikuti dia pergi. 
 Ayo, berikan tanganmu, aku akan membantumu keluar.]]
  },
  AvgDialog_23856_Content_50 = {
    Text = "Hoh, tidak buruk. Sepertinya, <Blue:Dewa> sudah mengakui <Blue:ibu> yang baru."
  },
  AvgDialog_23856_Content_51 = {
    Text = "Goliath tiba-tiba berbicara dengan nada mengejek, namun tidak ada seorang pun di sana yang memperhatikan ejekannya."
  },
  AvgDialog_23856_Content_52 = {
    Text = "Gadis Suci... berhasil? Kita berhasil!"
  },
  AvgDialog_23856_Content_53 = {
    Text = "Doa-doa saling bersahutan, akhirnya berpadu dalam gua yang dingin, penuh semangat, terdistorsi, dan memekakkan telinga."
  },
  AvgDialog_23856_Content_54 = {
    Text = "Miryam, seperti yang kau minta, aku telah menyelesaikan tugas yang kau berikan."
  },
  AvgDialog_23856_Content_55 = {
    Text = "\"Dia\"… sudah berdetak di sini."
  },
  AvgDialog_23856_Content_56 = {
    Text = [[
Bukan hanya Murphy, Miryam juga bisa mendengarnya. 
 Dua jantung dengan ritme berbeda sedang berdetak di dalam rongga dada gadis itu.]]
  },
  AvgDialog_23856_Content_57 = {
    Text = "Sekarang, bisakah kamu menjawab pertanyaanku?"
  },
  AvgDialog_23856_Content_58 = {
    Text = "Tahu segalanya."
  },
  AvgDialog_23856_Content_59 = {
    Text = "Apakah kamu membesarkanku sejak awal hanya untuk hari ini?"
  },
  AvgDialog_23856_Content_6 = {
    Text = "Begitu Murphy berdiri, tentakel Tulu segera mengikat erat pergelangan kakinya dengan persetujuan diam-diam darimu."
  },
  AvgDialog_23856_Content_61 = {Text = "Tidak."},
  AvgDialog_23856_Content_62 = {
    Text = "Kamu adalah \"Perawan Suci\"ku, seharusnya menjadi jembatan yang menghubungkan ranah dewa… Setelah itu, jiwa-mu akan disambut masuk ke dalam ranah dewa."
  },
  AvgDialog_23856_Content_63 = {
    Text = [[
Upacara hari ini adalah di luar rencana... tapi, tidak perlu panik. 
 Setelah ritual kelahiran dewa, aku akan menyimpan jiwamu dengan baik. Kau tidak akan berkeliaran dalam malam abadi.]]
  },
  AvgDialog_23856_Content_64 = {
    Text = "Bicara tentang jiwa, jiwa..."
  },
  AvgDialog_23856_Content_65 = {
    Text = "Tanggal kematiannya, dari awal sudah ditentukan pada saat yang disebut \"Waktu Bintang Selaras\", benar kan?"
  },
  AvgDialog_23856_Content_66 = {
    Text = [[
Miryam menutup matanya perlahan, dia tidak lagi menjawab pertanyaan dan berbalik menghadap para pengikut yang tenggelam dalam kegilaan. 
 Dia mengangkat kedua tangannya tinggi-tinggi, cairan hitam mengalir menuruni tekstur kulitnya, dan kerudungnya langsung berubah menjadi hitam pekat.]]
  },
  AvgDialog_23856_Content_67 = {
    Text = "Dewi Ibu telah tiba!"
  },
  AvgDialog_23856_Content_68 = {
    Text = "Dia akan bangkit dari @1, menyebabkan @2 Kedatangan!"
  },
  AvgDialog_23856_Content_69 = {
    Text = "Dia akan bangkit dari @1, menyebabkan @2 Kedatangan!"
  },
  AvgDialog_23856_Content_7 = {
    Text = "Apa, apa yang kalian lakukan?! Aku tahu meninggalkan kalian sendirian menghadapi Goliath adalah kesalahanku..."
  },
  AvgDialog_23856_Content_70 = {
    Text = "Tiga bulan kemudian"
  },
  AvgDialog_23856_Content_71 = {
    Text = [[
Kamu membuat wanita itu semakin pusing. Bukankah beberapa bulan lalu dia masih sangat penurut? 
Apa, sekarang tidak mau mendengarkan kata-kata Ibu lagi?]]
  },
  AvgDialog_23856_Content_72 = {
    Text = "Gadis itu melirik Goliath, lalu dengan keras menancapkan pahat ke kayu dan melemparkan alat serta bahan itu ke samping."
  },
  AvgDialog_23856_Content_73 = {Text = "Ibu, Ibu?"},
  AvgDialog_23856_Content_74 = {
    Text = "Kamu... dari mana kamu mempelajari ungkapan seperti itu?"
  },
  AvgDialog_23856_Content_75 = {
    Text = "Kamus! Lihat, \"wanita dewasa yang merawat anak kecil dan memiliki Tautan emosional.\""
  },
  AvgDialog_23856_Content_76 = {
    Text = "Tidak… Aku tidak akan menjadi ibumu."
  },
  AvgDialog_23856_Content_77 = {
    Text = "Kamu adalah gadis suci dari ordo, orang terpilih yang mulia... Jika kamu bersedia, kamu bisa langsung memanggil namaku."
  },
  AvgDialog_23856_Content_78 = {
    Text = "Umm... Mili... Yam?"
  },
  AvgDialog_23856_Content_79 = {Text = "Ya, Santa."},
  AvgDialog_23856_Content_8 = {
    Text = "Tapi, tapi jika dia datang untuk mencariku, jika dia menangkapku, aku pasti akan mati! Aku, aku..."
  },
  AvgDialog_23856_Content_80 = {
    Text = "...Dia bukan ibuku, dan tak pernah menjadi ibuku."
  },
  AvgDialog_23856_Content_81 = {
    Text = "Hanya orang-orang dari Gereja Penerang Kuil yang tahu asal-usulku. Aku juga tidak memiliki ibu. Aku hanyalah hadiah yang mereka berikan kepada Miryam."
  },
  AvgDialog_23856_Content_82 = {
    Text = "Oh? Apakah dia benar-benar memberitahumu tentang hal ini?"
  },
  AvgDialog_23856_Content_83 = {
    Text = "Bagi seorang tahanan yang sudah ditentukan tanggal kematiannya, mengetahui berapa banyak rahasia tidak masalah lagi, karena pada akhirnya semua akan aku bawa ke dalam kubur."
  },
  AvgDialog_23856_Content_84 = {
    Text = "Ini juga merupakan kompensasi dari wanita itu untukmu. Ketahuilah, pada hari Dewa dipindahkan ke dalam dirimu, Imam Agung kita begitu bersedih hingga tidak bisa tidur sepanjang malam."
  },
  AvgDialog_23856_Content_85 = {
    Text = "Sedih? Apa maksudnya bercanda, dia tidak akan memiliki perasaan seperti itu."
  },
  AvgDialog_23856_Content_86 = {
    Text = [[
Benar-benar tanpa ampun, Putri Kecil. 
Jika seorang gadis terlalu dingin, itu bisa membuat Ibu bersedih, lho.]]
  },
  AvgDialog_23856_Content_87 = {
    Text = "Apa kamu tidak bosan! Sudah kubilang, dia bukan ibuku!"
  },
  AvgDialog_23856_Content_88 = {
    Text = "Ini belum tentu. Apakah kamu ingin mendengar sebuah cerita?"
  },
  AvgDialog_23856_Content_89 = {
    Text = [[
<BigShake: Tidak mau mendengar, aku juga tidak ingin melihatmu!>
Jika kau datang untuk mengejekku, kau bisa pergi!]]
  },
  AvgDialog_23856_Content_9 = {Text = "Murphy."},
  AvgDialog_23856_Content_90 = {
    Text = "Tidak, kamu pasti ingin mendengarnya."
  },
  AvgDialog_23856_Content_91 = {
    Text = "Nada suara Goliath tiba-tiba menjadi dalam, membawa keagungan seorang veteran medan perang, hingga kedua jantung di tubuh Murphy nyaris berhenti berdetak karenanya."
  },
  AvgDialog_23856_Content_92 = {
    Text = "Dia tiba-tiba menyadari — raksasa itu sejak awal bukanlah mainan yang bisa dia kendalikan sesuka hati. \n Dia hanya memanfaatkan statusnya untuk bertindak semena-mena, sementara pihak lain hanya menikmati hiburan belaka."
  },
  AvgDialog_23856_Content_93 = {
    Text = "Ya... ya, silakan berbicara."
  },
  AvgDialog_23856_Content_94 = {
    Text = "Ada sebuah sekte misterius yang, demi menjaga kemurnian absolut garis keturunan, semua pernikahan ditentukan oleh pemimpin tertinggi. Mereka yang menikah dan memiliki anak dengan orang luar pada akhirnya akan menghadapi hukuman berat."
  },
  AvgDialog_23856_Content_95 = {
    Text = "Pada penyelesaian terakhir, algojo membawa kembali seorang bayi — bayi perempuan yang dapat melihat keberadaan Roh."
  },
  AvgDialog_23856_Content_96 = {
    Text = "Bayi perempuan..."
  },
  AvgDialog_23856_Content_97 = {
    Text = "Dia telah bersembunyi di ruang rahasia di bawah tubuh ibunya terlalu lama, dan saat para penganut menemukannya, dia hampir tersedak darah ibu kandungnya sendiri."
  },
  AvgDialog_23856_Content_98 = {
    Text = "Wanita biasa yang tidak berprestasi ini, pencapaian terbesar dalam hidupnya adalah melahirkan seorang putri dengan kualitas yang luar biasa, dan berusaha keras agar dia tidak dibawa pergi oleh gereja."
  },
  AvgDialog_23856_Content_99 = {
    Text = "——Betapa indahnya ikatan ibu dan anak ini, aku hampir meneteskan air mata karenanya."
  },
  AvgDialog_23857_Content_1 = {
    Text = "Benih Takdir"
  },
  AvgDialog_23857_Content_10 = {
    Text = "Berapa lama lagi?"
  },
  AvgDialog_23857_Content_11 = {
    Text = "Apa lagi? Berapa lama lagi?"
  },
  AvgDialog_23857_Content_12 = {
    Text = "Dewa. Berapa lama lagi sampai Dia dilahirkan?"
  },
  AvgDialog_23857_Content_13 = {
    Text = "...Aku tidak tahu. Lebih baik kamu memastikannya sendiri, lagipula dari sikapmu terhadap Miryam dan Goliath, sepertinya kamu sudah terlibat sejak lama."
  },
  AvgDialog_23857_Content_14 = {
    Text = [[
Murphy tidak banyak berbasa-basi, langsung mulai membuka pakaiannya. 
Begitu kancing terakhir di bagian depan terbuka, kalian melihat "dewa" yang berada di dalam tubuh gadis itu.]]
  },
  AvgDialog_23857_Content_15 = {
    Text = "Tubuh di bawah bagian depan bajunya tampak transparan, dengan tekstur transparan yang menarik kulit dan otot di sekitarnya, membuat seluruh rongga dada dan perut terlihat berwarna putih pucat yang suram."
  },
  AvgDialog_23857_Content_16 = {
    Text = "Transparansi aneh memperlihatkan organ-organ di dalam rongga dada dengan jelas. Kamu melihat sebuah jantung muda berwarna merah pucat, serta sebuah \"telur\" berwarna susu."
  },
  AvgDialog_23857_Content_17 = {
    Text = "Tak terhitung jumlahnya benang halus menjulur dari \"telur\", erat berjalinan dengan pembuluh darah Murphy, saling bergantung satu sama lain."
  },
  AvgDialog_23857_Content_18 = {
    Text = "Seandainya keberadaannya tidak menekan jantung Murphy, Dia tampaknya menyatu sempurna dengan rongga dada transparan itu, tidak seperti benda asing."
  },
  AvgDialog_23857_Content_19 = {
    Text = "Dia Kekacauan namun tenang, orison segitiga terbalik yang terukir di atasnya juga ikut membeku, seperti sebuah karya seni yang aneh."
  },
  AvgDialog_23857_Content_2 = {
    Text = "Perkumpulan Pelaut, ritual yang dihancurkan oleh tim petualang, induk sebelumnya yang mengalami pelarutan... dan \"Dewa\" di dalam tubuhmu..."
  },
  AvgDialog_23857_Content_20 = {
    Text = "Pelarutan… benda ini sudah terkena pelarutan."
  },
  AvgDialog_23857_Content_21 = {
    Text = "Apakah sudah cukup melihat?"
  },
  AvgDialog_23857_Content_22 = {
    Text = "Maaf… Harap segera merapikan pakaianmu."
  },
  AvgDialog_23857_Content_23 = {
    Text = "Murphy menundukkan kepalanya, sambil merapikan pakaiannya dan memandangmu."
  },
  AvgDialog_23857_Content_24 = {
    Text = "Apakah \"Pelarutan\" yang kau sebutkan terus-menerus merujuk pada luka hitam di atas tubuh-Nya?"
  },
  AvgDialog_23857_Content_25 = {
    Text = "Wadah sebelumnya... yaitu, orang yang benar-benar melahirkan hal ini, tubuhnya dipenuhi dengan bekas seperti itu."
  },
  AvgDialog_23857_Content_26 = {
    Text = "Jika bukan karena \"Pelarutan\" ini yang membuat wadah sebelumnya semakin lemah, aku juga tidak akan…"
  },
  AvgDialog_23857_Content_27 = {
    Text = [[
Suara Murphy perlahan meredup. 
 Dia menelan kata-kata yang belum selesai diucapkan, lalu mengangkat tangan untuk menekan dadanya, dengan ekspresi yang suram.]]
  },
  AvgDialog_23857_Content_28 = {
    Text = [[
Tulu, kamu juga melihat wujud Dewa itu. 
Berapa lama lagi sampai Ia tumbuh sepenuhnya?]]
  },
  AvgDialog_23857_Content_29 = {
    Text = [[
Cukup sehat, bahkan hanya selangkah lagi...
Tinggal menggunakan bintang-bintang untuk membimbing-Nya, membimbing-Nya merobek Tubuh wadah-Nya.]]
  },
  AvgDialog_23857_Content_3 = {
    Text = "Aigis, Nona Mason, Lily, Lisa… Hingga saat ini, kamu telah bertemu banyak orang yang mengalami modifikasi tubuh."
  },
  AvgDialog_23857_Content_30 = {
    Text = "Yu sangat terkejut, bahkan sampai sekarang kamu masih bisa bergerak dengan bebas."
  },
  AvgDialog_23857_Content_31 = {
    Text = "Benarkah… ternyata sudah sampai pada saat seperti ini……"
  },
  AvgDialog_23857_Content_32 = {
    Text = "Saya masih belum kehilangan kesadaran karena <Blue:Celeste> telah membantu saya."
  },
  AvgDialog_23857_Content_33 = {
    Text = "Celeste adalah?"
  },
  AvgDialog_23857_Content_34 = {
    Text = [[
Murphy menatap langit yang berputar dengan aliran cahaya aneh.
Burung-burung berputar di bawah tirai cahaya, sinarnya melengkung dan lembut, menghalangi kemungkinan badai dan angin kencang dari luar.]]
  },
  AvgDialog_23857_Content_35 = {
    Text = "Dalam catatan Ordo Pelaut, pentingnya <Blue:Selaras Bintang> ditekankan berulang kali. Upacara kelahiran juga harus dilakukan pada waktu tertentu, itulah alasan mengapa wanita itu membuatku tertidur."
  },
  AvgDialog_23857_Content_36 = {
    Text = [[
Kapten berspekulasi bahwa pertumbuhan-Nya mungkin terkait dengan aturan pergerakan benda langit. 
Oleh karena itu, Celeste menciptakan Domain ini dengan kapal sebagai pusatnya, menjadikannya tempat yang terisolasi dari dunia luar.]]
  },
  AvgDialog_23857_Content_37 = {
    Text = "Kami menebak dengan benar. Sejak meninggalkan langit yang sebenarnya, Dia menjadi sunyi. Selama kami bisa bersembunyi di kapal dan melewati \"saat bintang-bintang selaras\" kali ini, mungkin Dia akan terus berhibernasi selamanya."
  },
  AvgDialog_23857_Content_38 = {
    Text = "Tepat Celeste inilah yang menciptakan Domain ini, dan dia juga yang mengendalikan kapal Sonnelier yang seharusnya tenggelam untuk tetap berlayar."
  },
  AvgDialog_23857_Content_39 = {
    Text = "Tampaknya, dia juga seorang Pembangun. \n Tunggu sebentar… Apakah dia orang yang kau maksud \"bisa membantu menemukan Ramona\"?"
  },
  AvgDialog_23857_Content_4 = {
    Text = "Tetapi memindahkan <Blue:\"Dewa\"> ke dalam tubuh manusia hidup? Ini sungguh..."
  },
  AvgDialog_23857_Content_40 = {
    Text = "Benar, tidak ada satu pun hal di kapal ini yang bisa lepas dari pengamatan matanya."
  },
  AvgDialog_23857_Content_41 = {
    Text = "Dia pasti membawa kapten menghindari Pelaut. Selama kita menemukannya, menemukan lokasi temanmu akan semudah membalikkan telapak tangan."
  },
  AvgDialog_23857_Content_42 = {
    Text = "Dengan kata lain, baik kami memilih untuk membantu kamu terlebih dahulu atau menyelamatkan Ramona, Celeste tetap menjadi kunci."
  },
  AvgDialog_23857_Content_43 = {
    Text = "Tulu tidak bicara lagi, hanya memiringkan kepalanya dan menatapmu, menunggumu membuat keputusan."
  },
  AvgDialog_23857_Content_44 = {
    Text = "Benar. Baik untuk membawa kapal ini kembali ke darat, menghentikan ritual pemanggilan roh, atau menyelamatkan Ramona, satu-satunya jalan sekarang adalah menemukan \"Celeste\"."
  },
  AvgDialog_23857_Content_45 = {
    Text = [[
Murphy, tunjukkan jalan. 
Temui kapten, temui Celeste.]]
  },
  AvgDialog_23857_Content_5 = {
    Text = "Apa ekspresi itu? Jika kamu tidak percaya, ya sudah. Aku juga tidak berharap kamu bisa langsung mengerti apa yang aku katakan."
  },
  AvgDialog_23857_Content_6 = {
    Text = "Maaf... hanya saja, semua ini terasa sangat sulit dipercaya."
  },
  AvgDialog_23857_Content_7 = {
    Text = "Murphy, bisakah kamu menunjukkan padaku itu... \"Dewa\"?"
  },
  AvgDialog_23857_Content_8 = {
    Text = "Masih mengatakan bahwa kamu tidak percaya!"
  },
  AvgDialog_23857_Content_9 = {
    Text = "Saya, saya hanya..."
  },
  AvgDialog_23858_Content_1 = {
    Text = "Pengepungan dari Sepuluh Arah"
  },
  AvgDialog_23858_Content_10 = {
    Text = "Kami berada di <Blue:Brilport> di <Blue:Deramaga Ketiga>, dan terlibat dalam pertempuran dengan musuh yang tidak dikenal."
  },
  AvgDialog_23858_Content_11 = {
    Text = [[
Menghubungi penyelidik lapangan terdekat...
Penyelidik Drapool diperkirakan akan tiba di Dermaga Ketiga dalam waktu setengah jam.]]
  },
  AvgDialog_23858_Content_12 = {
    Text = "Setengah jam terlalu lama. Terlalu banyak musuh di sisi selatan jalan, kami akan mencoba menembus dari sisi utara."
  },
  AvgDialog_23858_Content_13 = {
    Text = "Sopir telah diberitahu untuk menjemput di sisi utara Pintu Keluar Dermaga Tiga."
  },
  AvgDialog_23858_Content_14 = {
    Text = "Musuh tidak dikenal? Bukankah ini <Yellow:Gereja penerang kuil>?"
  },
  AvgDialog_23858_Content_15 = {
    Text = "Apakah akan mencatat intelijen musuh baru?"
  },
  AvgDialog_23858_Content_16 = {
    Text = "Tolong, Erica, bukan sekarang."
  },
  AvgDialog_23858_Content_17 = {
    Text = "Adalah makhluk mirip manusia yang belum pernah tercatat keberadaannya. Setelah kembali, saya akan menyerahkan laporan."
  },
  AvgDialog_23858_Content_18 = {
    Text = "%player%, lindungi dirimu dan bersiap untuk terobosan."
  },
  AvgDialog_23858_Content_2 = {
    Text = "Tiga jam yang lalu\nKota Pelabuhan·Brillpart\nDermaga Ketiga"
  },
  AvgDialog_23858_Content_3 = {
    Text = "%player%, hati-hati dengan musuh di belakangmu!"
  },
  AvgDialog_23858_Content_5 = {
    Text = [[
Mendeteksi gelombang suara frekuensi tinggi tanpa peringatan, sambungan komunikasi otomatis terhubung. 
Sekali lagi, selamat malam, Penjaga, Ramona.]]
  },
  AvgDialog_23858_Content_6 = {
    Text = "Tampaknya ada yang sudah ketakutan sampai kehilangan nyali."
  },
  AvgDialog_23858_Content_7 = {
    Text = "Harap jangan mengganggu petugas lapangan dengan gangguan bahasa yang tidak perlu."
  },
  AvgDialog_23858_Content_8 = {
    Text = [[
Baiklah, baiklah.
Lalu, apakah kalian membutuhkan bantuan?]]
  },
  AvgDialog_23858_Content_9 = {
    Text = "Kami membutuhkan bala bantuan!"
  },
  AvgDialog_23859_Content_1 = {
    Text = "Tidak ada jalan keluar"
  },
  AvgDialog_23859_Content_10 = {
    Text = "Ternyata, mereka tidak mengikuti tangga kapal…"
  },
  AvgDialog_23859_Content_11 = {
    Text = "Ramona menurunkan suaranya dan berbicara dengan bisikan."
  },
  AvgDialog_23859_Content_12 = {
    Text = "Makhluk ikan ini terhalang oleh Sonanier, tetapi entah mengapa, kami tidak ditolak oleh kapal ini."
  },
  AvgDialog_23859_Content_13 = {
    Text = "Kami dijadikan batu loncatan. Begitu mereka juga naik ke kapal, kami akan kehilangan nilai guna."
  },
  AvgDialog_23859_Content_14 = {
    Text = "Benar. Jadi… aku punya sebuah ide."
  },
  AvgDialog_23859_Content_15 = {
    Text = "Kalian melangkah ke anak tangga terakhir dari tangga kapal."
  },
  AvgDialog_23859_Content_16 = {
    Text = "Bagai burung yang dicium oleh langit, mata ditiup angin lembut dan hangat, dunia yang terlihat berubah sepenuhnya."
  },
  AvgDialog_23859_Content_17 = {
    Text = "Bulan purnama yang besar menghilang di langit, cahaya seperti aurora mengaduk ruang yang menyelimuti lambung kapal, dan bintik-bintik cahaya yang jatuh di dek juga memancarkan warna yang aneh."
  },
  AvgDialog_23859_Content_18 = {
    Text = "Ramona, ada yang tidak beres!"
  },
  AvgDialog_23859_Content_19 = {
    Text = "Tangga itu bergetar. Setelah kalian berhasil naik ke dek, suku ikan tidak lagi mengamati dan mulai memanjat dengan tangan dan kaki mereka."
  },
  AvgDialog_23859_Content_2 = {
    Text = "Tiga jam yang lalu\nKota Pelabuhan·Brillpart\nDermaga Ketiga"
  },
  AvgDialog_23859_Content_20 = {
    Text = "Tidak ada waktu lagi, mereka akan segera menyusul."
  },
  AvgDialog_23859_Content_21 = {
    Text = "Serangan pedang maksimal Ramona menghancurkan kait pengunci, tangga kapal pun jatuh, namun tidak mengeluarkan suara sedikit pun seperti benda berat yang menyentuh tanah."
  },
  AvgDialog_23859_Content_22 = {
    Text = "Jantung berdebar kencang, fenomena aneh di kapal membanjiri pikiran. Setelah beberapa saat, kalian akhirnya mendapatkan kembali kemampuan untuk berbicara."
  },
  AvgDialog_23859_Content_23 = {
    Text = "Setidaknya mereka tidak bisa lagi naik ke kapal melalui tangga ini."
  },
  AvgDialog_23859_Content_24 = {
    Text = "Pemandangan di kapal ini… memang sesuai dengan stereotip saya tentang \"kapal hantu\"."
  },
  AvgDialog_23859_Content_25 = {
    Text = "Tangga itu jatuh tanpa mengeluarkan suara — yang menunjukkan bahwa kita mungkin berada di ruang terpisah. Menarik, bukan?"
  },
  AvgDialog_23859_Content_26 = {
    Text = "Ini adalah <Yellow:Domain> yang terlihat dengan mata telanjang."
  },
  AvgDialog_23859_Content_27 = {
    Text = "Kabut pelindung sekolah didorong oleh <Yellow:Teknologi chip perak>, entah kekuatan macam apa yang akan menguasai kapal ini?"
  },
  AvgDialog_23859_Content_28 = {
    Text = "Apakah ini akan menjadi Pembangun?"
  },
  AvgDialog_23859_Content_29 = {
    Text = "Tidak ada catatan serupa dalam arsip, tetapi secara teori, Pembangun menciptakan ruang independen adalah mungkin — apakah kamu ingin mendengar teori spesifiknya?"
  },
  AvgDialog_23859_Content_3 = {
    Text = "Bau karat besi menusuk hidung, setiap langkah membuat tangga kapal mengeluarkan erangan yang terdengar seperti akan runtuh."
  },
  AvgDialog_23859_Content_30 = {
    Text = "Lepaskan aku..."
  },
  AvgDialog_23859_Content_31 = {
    Text = "Boneka, apakah kalian mendengarnya?"
  },
  AvgDialog_23859_Content_32 = {
    Text = "Lihat situasinya dulu!"
  },
  AvgDialog_23859_Content_33 = {
    Text = "Maaf, maaf, tolong maafkan rasa penasaranku."
  },
  AvgDialog_23859_Content_34 = {
    Text = "Boneka, apakah kalian mendengarnya?"
  },
  AvgDialog_23859_Content_35 = {
    Text = "Ramona mengetuk jarum di dadanya, permukaan logam perak dari komunikator tampak berkilauan seolah-olah ada cahaya yang melintas."
  },
  AvgDialog_23859_Content_36 = {Text = "Eh…?"},
  AvgDialog_23859_Content_37 = {
    Text = [[
Ramona memiringkan tubuhnya, lalu menyentuh komunikator Anda dengan jarinya. 
 Anda mencoba berkonsentrasi seperti biasa, tetapi tidak ada hasil.]]
  },
  AvgDialog_23859_Content_38 = {
    Text = "Kekuatan roh seperti tetesan air mata yang jatuh ke lautan, kembali pada kesunyian."
  },
  AvgDialog_23859_Content_39 = {
    Text = "Secara eksternal, komunikator tidak rusak, namun tidak bisa mengirim pesan."
  },
  AvgDialog_23859_Content_4 = {
    Text = "Tidak ada tanda-tanda pemeliharaan atau perbaikan, tetapi selain tampak tua, badan kapal relatif utuh. \n Erosi air laut tidak terlalu jelas, di bawah garis air juga tidak ada kerang, tiram…"
  },
  AvgDialog_23859_Content_40 = {
    Text = "<Small: Bagaimana bisa ada begitu banyak hal yang dapat memutus komunikasi, terakhir di Museum Lilin juga …>"
  },
  AvgDialog_23859_Content_41 = {
    Text = [[
Teknologi yang dihasilkan oleh Perak bukanlah segalanya. 
Lagipula, untuk Perak itu sendiri, penelitian kita masih sangat dangkal.]]
  },
  AvgDialog_23859_Content_42 = {
    Text = "Semoga para ikan itu tidak merangkak naik dari tempat lain…"
  },
  AvgDialog_23859_Content_43 = {
    Text = "Hmm, berhati-hatilah terhadap lingkungan sekitar, dan berdoa agar kapal ini tidak berlayar."
  },
  AvgDialog_23859_Content_44 = {
    Text = "<Big:Uuuuuuh——>"
  },
  AvgDialog_23859_Content_45 = {
    Text = "Seperti burung gereja yang merespons kembang suara penyanyi opera, peluit panjang itu membalas doa Ramona."
  },
  AvgDialog_23859_Content_48 = {
    Text = "Aku tahu apa yang ingin kau katakan, tapi tolong, bukan sekarang."
  },
  AvgDialog_23859_Content_49 = {
    Text = "Kita tidak bisa mengikuti kapal Sonaniel ke laut, ada terlalu banyak kejanggalan pada kapal ini."
  },
  AvgDialog_23859_Content_5 = {
    Text = "Kamu dan Ramona berjalan berdampingan menaiki tangga kapal yang goyah. Jalan ke atas tampak seperti tenggelam dalam kabut, membuatmu sama sekali tidak bisa melihat ujungnya."
  },
  AvgDialog_23859_Content_50 = {
    Text = "Pergi ke ujung dek lainnya! Aku melihat tali yang mengikat perahu penyelamat di sana, mari kita coba evakuasi dari permukaan laut."
  },
  AvgDialog_23859_Content_51 = {
    Text = "Tunggu… sepertinya ada suara."
  },
  AvgDialog_23859_Content_53 = {
    Text = "Wajah yang menyerupai ikan muncul di dek, pelaku yang memaksa kalian naik ke kapal terus mendesak maju."
  },
  AvgDialog_23859_Content_6 = {
    Text = "Apa yang kamu temukan?"
  },
  AvgDialog_23859_Content_7 = {
    Text = "Sonanier tidak memiliki ciri-ciri khas kapal hantu yang tenggelam, dan tidak sesuai dengan catatan bahwa kapal itu pernah tenggelam dalam badai."
  },
  AvgDialog_23859_Content_8 = {
    Text = "Saya ingin melakukan Penyelidikan terhadap asal-usul kapal ini dengan baik, tapi sekarang jelas bukan waktu yang tepat."
  },
  AvgDialog_23859_Content_9 = {
    Text = "Dia menoleh ke belakang, musuh yang memaksa kalian naik tangga itu telah mengelilingi kaki tangga, bertatapan dengan sepasang mata ikan tanpa jiwa."
  },
  AvgDialog_23860_Content_1 = {
    Text = "Penggemar yang tenggelam dalam dosa"
  },
  AvgDialog_23860_Content_10 = {
    Text = "Terakhir, muncul wajah yang tampak akrab namun juga asing."
  },
  AvgDialog_23860_Content_11 = {
    Text = "Hek, hek hek hek…!"
  },
  AvgDialog_23860_Content_12 = {
    Text = "Udara kering bercampur dengan air laut yang tersisa di saluran pernapasan, menyebabkan iritasi parah pada sistem pernapasan. Otot-otot berkontraksi secara tidak terkendali, memicu batuk hebat yang sulit ditahan."
  },
  AvgDialog_23860_Content_13 = {
    Text = "Pemuda berambut hijau sedikit mengerutkan alisnya, tentakel-tentakel di bawah kendalinya kembali melilit tubuhmu, lalu —"
  },
  AvgDialog_23860_Content_14 = {
    Text = "Tentakel berkontraksi beberapa kali dengan kekuatan yang tepat, air laut dan ikan kecil di tenggorokan sepenuhnya terdorong keluar akibat tekanan."
  },
  AvgDialog_23860_Content_15 = {
    Text = "Huh, huh... terima kasih."
  },
  AvgDialog_23860_Content_16 = {
    Text = "Tidak perlu berterima kasih, suaramu terlalu keras, akan menarik perhatian para Pelaut lain."
  },
  AvgDialog_23860_Content_17 = {
    Text = "...Maksudku, tentang menyelamatkanku dari laut."
  },
  AvgDialog_23860_Content_18 = {
    Text = [[
Meskipun menjadi Pembangun bukanlah keinginanku, Universitas Mythag pada akhirnya mengakhiri tidur panjangku selama ribuan tahun. 
 Baik secara emosional maupun logis, aku tidak akan membiarkan "Penjaga" mati begitu saja.]]
  },
  AvgDialog_23860_Content_19 = {
    Text = [[
Tapi... kamu seharusnya tidak berada di sini, kan? 
Dalam daftar keberangkatan untuk misi Penyelidikan kali ini, hanya ada aku dan Ramona.]]
  },
  AvgDialog_23860_Content_2 = {
    Text = "Air terus-menerus masuk ke dalam tubuhmu tanpa henti.\nRongga hidung, saluran telinga, tenggorokan, sudut mata… semua lubang di bagian tubuh atas dipenuhi oleh air laut."
  },
  AvgDialog_23860_Content_20 = {
    Text = "Tanpa persetujuan dari ketua tim operasi luar, dan sebelum dihubungkan oleh penyelidik, Pembangun tidak diizinkan meninggalkan wilayah Mythag. Saya kira kamu sudah tahu hal ini..."
  },
  AvgDialog_23860_Content_21 = {
    Text = "Bangun Pembangun Tulu, nomor arsip-6291, kode nama \"Tuan Tidur\"."
  },
  AvgDialog_23860_Content_22 = {
    Text = "Yuu percaya bahwa kamu juga sudah tahu, aturan-aturan yang disebut-sebut dari Universitas Mythag, di hadapan Yuu tidak lebih dari sekadar formalitas belaka."
  },
  AvgDialog_23860_Content_23 = {
    Text = "Lagipula, jangan gunakan kode nama bodoh itu untuk merujuk pada saya."
  },
  AvgDialog_23860_Content_24 = {Text = "Tulu."},
  AvgDialog_23860_Content_25 = {
    Text = "Aku bukan orang yang berpikiran kaku di Komite, Pembangun bagi aku bukanlah binatang buas yang perlu diborgol."
  },
  AvgDialog_23860_Content_26 = {
    Text = [[
Yang aku khawatirkan adalah, kamu tidak ada dalam daftar personel untuk misi lapangan, dan tidak terhubung dengan siapa pun melalui Tautan. 
Jika kamu terlalu lama meninggalkan Mythag di <Yellow:Kolam hitam>, kamu akan menghadapi risiko kehilangan kendali.]]
  },
  AvgDialog_23860_Content_27 = {
    Text = "Tidak apa-apa, aku tidak akan dikuasai oleh insting."
  },
  AvgDialog_23860_Content_28 = {
    Text = [[
Pembangun mempertahankan bentuk seorang pemuda, namun setiap ucapan dan tindakannya dipenuhi dengan tekanan dari seorang yang berkuasa. 
Hanya dengan sekilas pandang saja, sudah cukup membuat bulu kuduk orang merinding.]]
  },
  AvgDialog_23860_Content_29 = {Text = "… Huh."},
  AvgDialog_23860_Content_3 = {
    Text = "Darahmu bereaksi dengan air laut, sel-sel dikeluarkan dari tubuh. Yang mengalir di dalam pembuluh darah tampaknya menjadi garam kasar dan pasir."
  },
  AvgDialog_23860_Content_30 = {
    Text = "——Aku hanya ingin tahu, apa yang kau lakukan di sini?\nKau terus-menerus tidur dalam waktu lama, bahkan mutasi di <Yellow:Upacara Pemberian Kunci Perak> pun tidak bisa membangunkanmu."
  },
  AvgDialog_23860_Content_31 = {
    Text = "Tapi kamu rela mengambil risiko kehilangan akal sehatmu untuk muncul di sini… Apa pun yang terjadi, pasti memiliki arti yang sangat penting bagimu."
  },
  AvgDialog_23860_Content_32 = {
    Text = [[
Segala sesuatu yang terjadi di sini, semuanya karena diriku. 
Adapun detailnya, itu tidak ada hubungannya denganmu.]]
  },
  AvgDialog_23860_Content_33 = {
    Text = "Benarkah? Apakah tidak peduli apa yang terjadi antara aku, Ramona, dan wanita bernama Miryam, kamu tetap sulit muncul untuk menyelamatkan kami?"
  },
  AvgDialog_23860_Content_34 = {
    Text = "Yu tidak punya kewajiban untuk menjelaskan kepada kalian, tetapi jika diperlukan, Yu akan memberikan bantuan."
  },
  AvgDialog_23860_Content_35 = {
    Text = "Sikap Tulu yang tertutup hampir saja memicu kemarahanmu, tetapi realitas membuatmu tetap rasional."
  },
  AvgDialog_23860_Content_36 = {
    Text = "Kedua tangan beberapa kali mengepal, lalu kembali terbuka. Setelah menarik napas dalam beberapa kali, akhirnya kamu melihat ke arah remaja Bangun di depanmu."
  },
  AvgDialog_23860_Content_37 = {
    Text = "Ramona ada di tangan Pelaut. Tulu, aku membutuhkan bantuanmu."
  },
  AvgDialog_23860_Content_38 = {
    Text = "Tulu menatap lama ke dalam matamu, tampaknya sedang memikirkan kata-kata penolakan."
  },
  AvgDialog_23860_Content_39 = {
    Text = "Tepat saat otot di sudut bibirnya bergerak sedikit, bersiap untuk mengucapkan balasan, terdengar teriakan memilukan dari seorang gadis di kedalaman kabin."
  },
  AvgDialog_23860_Content_4 = {
    Text = "Mereka menggores tubuh dan jiwa dari dalam, paru-paru dipenuhi cairan. Kesadaran perlahan tenggelam bersama tubuh, kekhawatiran terhadap rekan pun terdesak keluar dari pikiran oleh rasa sakit dan sesak napas…"
  },
  AvgDialog_23860_Content_40 = {
    Text = "Apakah itu Ramona!? Ayo cepat pergi melihat!"
  },
  AvgDialog_23860_Content_41 = {
    Text = "Masih belum tahu berapa banyak Pelaut yang telah naik ke kapal. Kamu begitu ceroboh masuk tanpa persiapan, sungguh bodoh."
  },
  AvgDialog_23860_Content_42 = {Text = "Bodoh?"},
  AvgDialog_23860_Content_43 = {
    Text = "Jika benar seperti yang kamu katakan, kamu tidak akan membiarkan \"Penjaga\" mati begitu saja."
  },
  AvgDialog_23860_Content_44 = {
    Text = "Tulu, aku akan pergi untuk menghadapi kematian."
  },
  AvgDialog_23860_Content_45 = {
    Text = "Tulu memegang kepalanya tanpa menjawab, tetapi sebelum kamu berbalik dan berlari ke dalam kedalaman kabin, kamu mendengar helaan napas samar-samar dari pemuda itu."
  },
  AvgDialog_23860_Content_6 = {
    Text = "Riak di permukaan laut menghantam gendang telinga. Sambil berjuang untuk membuka mata, sesuatu yang melawan cahaya menyelam ke dalam air."
  },
  AvgDialog_23860_Content_7 = {
    Text = "Itu melilit pinggangmu dengan lentur, seperti rumput laut... tidak, itu bukan rumput laut, melainkan semacam otot yang lembut namun sangat tangguh..."
  },
  AvgDialog_23860_Content_8 = {
    Text = "BYURRR——"
  },
  AvgDialog_23860_Content_9 = {
    Text = "Otot berbentuk memanjang menarikmu ke atas. Dalam pandangan muncul cahaya merah muda dari langit Domain, lalu balok kayu di dek bawah, dan kemudian lampu listrik di kabin yang berkedip-kedip."
  },
  AvgDialog_23861_Content_1 = {
    Text = "Wajah-wajah buruk itu, hanya dengan menatapnya saja sudah membuat seseorang merasa seolah-olah menghina teori evolusi."
  },
  AvgDialog_23861_Content_2 = {
    Text = "Mereka saling mendorong, senjata dingin di tangan mereka bertabrakan mengeluarkan suara yang menusuk telinga. Di tengah kekacauan itu, sepertinya mereka sedang mengelilingi sesuatu…"
  },
  AvgDialog_23862_Content_1 = {
    Text = "Sialan, sial sial sial!"
  },
  AvgDialog_23862_Content_2 = {
    Text = "Pelaut seharusnya terhalang oleh Domain Sonaniel ini. Kalau bukan karena makhluk kecil berjubah hitam ini, aku bisa saja melarikan diri dengan tenang ke benua baru…"
  },
  AvgDialog_23862_Content_3 = {
    Text = "Tetapi… mereka telah menjatuhkan begitu banyak Pelaut… Apakah orang itu benar-benar tidak berbohong padaku?"
  },
  AvgDialog_23863_Content_1 = {
    Text = "Tapi… sejak kapan Miryam menggunakan tipu daya seperti ini. \nMengirim orang untuk menipuku agar kembali… ini tidak seperti gayanya."
  },
  AvgDialog_23863_Content_2 = {
    Text = "Murphy? Apakah kamu di sini?"
  },
  AvgDialog_23863_Content_3 = {
    Text = "Ck, juga terlalu menghantui, ya."
  },
  AvgDialog_23864_Content_1 = {Text = "Kru kapal"},
  AvgDialog_23864_Content_10 = {
    Text = "Kamu sudah menggunakan trik-trik Roh itu untuk menyinggung Miryam, dan masih berkata \"Aku tahu kamu masih hidup\"... Ikan mati di pantai pun sudah tahu kalau kalian bukan satu kelompok."
  },
  AvgDialog_23864_Content_11 = {
    Text = "Tempat yang kamu sebut aman, itu di mana?"
  },
  AvgDialog_23864_Content_12 = {
    Text = "Jangan terlalu banyak dipikirkan, ikuti aku dengan suara pelan saja."
  },
  AvgDialog_23864_Content_13 = {
    Text = "Murphy juga tidak peduli apakah kamu dan Tulu mengikuti dia atau tidak. Dia dengan cekatan mendorong gerbang lainnya, lalu masuk ke dalam dengan gesit."
  },
  AvgDialog_23864_Content_14 = {
    Text = "Ketika kamu bersiap untuk mengejarnya, Tulu mengulurkan salah satu tentakelnya dan menghalangi antara kamu dan pintu."
  },
  AvgDialog_23864_Content_15 = {
    Text = "Penjaga, jangan merendahkan kewaspadaan terhadap gadis ini."
  },
  AvgDialog_23864_Content_16 = {Text = "Kenapa?"},
  AvgDialog_23864_Content_17 = {
    Text = "Tulu tidak menjawab pertanyaanmu secara langsung, melainkan justru balik bertanya kepadamu."
  },
  AvgDialog_23864_Content_18 = {
    Text = "Yu ingin tahu, bagaimana menurutmu tentang Pelaut?"
  },
  AvgDialog_23864_Content_19 = {
    Text = "Pelaut? Jari-jari memiliki selaput, bagian di atas tulang ekor sepenuhnya menyerupai ikan, namun tetap mempertahankan sejumlah kecerdasan."
  },
  AvgDialog_23864_Content_2 = {
    Text = "Murphy membawa kalian bergerak di antara kabin, berjalan dengan hati-hati untuk menghindari pencarian oleh Pelaut."
  },
  AvgDialog_23864_Content_20 = {
    Text = "Bentuknya mengalir dengan alami, tidak seperti karya Para Pematung, yang selalu membuat eksperimen mereka menjadi berantakan."
  },
  AvgDialog_23864_Content_21 = {
    Text = "Saya awalnya mengira bahwa penampilan mereka adalah hasil mutasi setelah terpengaruh oleh <Yellow:Clades>, tetapi dalam beberapa pertempuran ini, saya tidak menemukan adanya <Yellow:D-marka> yang jelas pada tubuh mereka."
  },
  AvgDialog_23864_Content_22 = {
    Text = "Pelaut… lebih mirip lelucon bodoh yang diajukan oleh teori evolusi kepada manusia."
  },
  AvgDialog_23864_Content_23 = {
    Text = "Mereka mengangkat Miryam sebagai pemimpin utama. Mereka bukan sekadar kelompok etnis, melainkan komunitas yang terbentuk karena ikatan keyakinan."
  },
  AvgDialog_23864_Content_24 = {
    Text = "\"Sebuah lelucon bodoh untuk manusia,\" Yu menghargai metafora Anda."
  },
  AvgDialog_23864_Content_25 = {
    Text = "Gadis ini — Murphy, ketika kami bertemu dengannya, Pelaut berbaring di sisinya. Dan dari pengetahuannya yang akrab dengan Miryam, dia pasti bukan anggota biasa."
  },
  AvgDialog_23864_Content_26 = {
    Text = "Katakan pada Yu, apakah ada \"Murphy\" di dunia roh Miryam?"
  },
  AvgDialog_23864_Content_27 = {
    Text = "Kamu membuka mulut, tapi sebelum pita suara bergetar, terdengar jeritan kecil dan suara aneh yang tidak jelas dari balik pintu."
  },
  AvgDialog_23864_Content_3 = {
    Text = "Kita akan pergi ke mana?"
  },
  AvgDialog_23864_Content_4 = {
    Text = "Pergi ke tempat yang aman, dan carilah orang yang bisa membantu."
  },
  AvgDialog_23864_Content_5 = {
    Text = "Bukankah kau masih punya teman yang diculik? Aku tahu seseorang yang sangat memahami segala sesuatu di kapal ini."
  },
  AvgDialog_23864_Content_6 = {
    Text = "Pergi dulu cari dia, lalu biarkan dia menemukan lokasi temanmu... Bukankah ini lebih baik daripada kamu berlarian tanpa arah seperti lalat yang kehilangan kepala?"
  },
  AvgDialog_23864_Content_7 = {
    Text = "Ngomong-ngomong, apakah kamu sekarang tidak lagi menganggap kami sebagai orang jahat?"
  },
  AvgDialog_23864_Content_8 = {
    Text = "Murphy menoleh dan menatapmu dengan tajam, lalu mendengus seperti seekor kucing."
  },
  AvgDialog_23864_Content_9 = {
    Text = "Aku bukan orang bodoh, aku mendengar semua yang kalian bicarakan dengan anak tentakel ini."
  },
  AvgDialog_23865_Content_1 = {
    Text = "Cukup, mereka hanyalah orang-orang yang tidak berarti."
  },
  AvgDialog_23865_Content_2 = {
    Text = [[
Berdiri diam di barisan belakang musuh, sosok yang sejak awal terdiam akhirnya berbicara.
Dia adalah seorang wanita dewasa, tubuhnya yang dibungkus kain hitam tampak sangat kontras di antara ikan-ikan buruk rupa dan cacat.]]
  },
  AvgDialog_23865_Content_3 = {
    Text = "Saat selaras akan tiba. Para pengikut setia lautan, pemeluk Ranah dewa, akhiri sandiwara ini… sambut kembali <Blue:Dewi Ibu>, sambut kembali kedatangan Dewa."
  },
  AvgDialog_23865_Content_4 = {
    Text = [[
Di bawah perintahnya, seorang pemuda yang tampak tidak cocok dengan orang-orang di sekitarnya melangkah ke depan. 
 Dia membungkuk dengan hormat kepada wanita itu, punggung tegapnya menunduk, dengan nada suara yang dipenuhi kesetiaan dan kebanggaan yang sulit tersembunyi.]]
  },
  AvgDialog_23865_Content_5 = {
    Text = "Mengikuti misi dengan setia, Nyonya Miryam."
  },
  AvgDialog_23866_Content_1 = {
    Text = "Cepat, lihat ke sana!"
  },
  AvgDialog_23866_Content_10 = {
    Text = "Apa yang kalian mau lakukan!? Kalian belum layak untuk berani-berani menyentuhku! Kalau punya nyali, bawa aku menghadap Miryam!"
  },
  AvgDialog_23866_Content_11 = {
    Text = "Miryam… itu adalah nama wanita tadi! Apakah gadis ini satu kelompok dengan pemimpin itu? Tapi kenapa Pelaut mengejarnya…"
  },
  AvgDialog_23866_Content_12 = {
    Text = "Sebelum kamu bisa memahami situasi, tentakel tebal menyapu bahu kamu dan tiba-tiba menyerang Pelaut."
  },
  AvgDialog_23866_Content_13 = {
    Text = "Yang terakhir tertabrak secara tiba-tiba, tetapi segera bereaksi, menjulurkan lidah ularnya dan bergulat dengan tentakel Tulu."
  },
  AvgDialog_23866_Content_2 = {
    Text = "@1 Ibu... Dewi @2..."
  },
  AvgDialog_23866_Content_3 = {
    Text = "Beberapa Pelaut membentuk lingkaran, mengelilingi sudut ruang kabin. Mereka melafalkan nada-nada yang menusuk telinga, hampir menenggelamkan isak tangis gadis itu."
  },
  AvgDialog_23866_Content_4 = {
    Text = "Jangan... jangan mendekatiku! Jangan harap bisa menangkap dan membawaku kembali!"
  },
  AvgDialog_23866_Content_5 = {
    Text = "Itu... bukan Ramona."
  },
  AvgDialog_23866_Content_6 = {
    Text = "Pemimpin Pelaut dengan hormat merunduk di depan gadis itu, sementara yang lain menahan tangannya dan kakinya dengan telapak tangan berselaput."
  },
  AvgDialog_23866_Content_7 = {
    Text = "Pemimpin itu tiba-tiba bangkit, dan baru sekarang kamu bisa melihat dengan jelas bahwa di bawah kerudungnya ternyata terdapat beberapa kepala ular yang bergerak-gerak, tampak sangat aneh."
  },
  AvgDialog_23866_Content_8 = {
    Text = "Manusia berkepala ular menggambar rune aneh di tanah, lalu menerima tas dari Pelaut. Di dalam tas itu tercium bau busuk yang memuakkan."
  },
  AvgDialog_23866_Content_9 = {
    Text = "Taring ular menggigit sebuah lubang di tas ransel, organ-organ yang membusuk tumpah keluar seperti ikan sarden, semuanya jatuh di atas rune, dan bau busuk segera menyebar ke seluruh kabin."
  },
  AvgDialog_23867_Content_1 = {
    Text = "Penjahat dan Pedang Raksasa"
  },
  AvgDialog_23867_Content_10 = {
    Text = [[
Tapi lihatlah apa yang ada di depan kita. 
Hanya dinding buntu, bahkan tidak ada saluran ventilasi untuk dipanjat.]]
  },
  AvgDialog_23867_Content_11 = {
    Text = "Saya... saya jarang turun sendirian, biasanya saya selalu bersama dengan kapten dan yang lainnya."
  },
  AvgDialog_23867_Content_12 = {
    Text = "Ada denah di dinding."
  },
  AvgDialog_23867_Content_13 = {
    Text = "Apa maksudmu? Apakah kamu tidak percaya pada memori-ku?"
  },
  AvgDialog_23867_Content_14 = {
    Text = "Aku bilang kalau bisa menemukan, berarti bisa menemukan! Kapten mereka pasti di sini!"
  },
  AvgDialog_23867_Content_15 = {
    Text = [[
Rekan saya masih menunggu bantuan kita. 
 Kumohon, Murphy, lihatlah denahnya.]]
  },
  AvgDialog_23867_Content_16 = {Text = "…Hm!"},
  AvgDialog_23867_Content_17 = {
    Text = "Murphy menginjak kakinya dengan keras, dengan wajah yang sangat enggan mendekati denah di dinding kabin."
  },
  AvgDialog_23867_Content_18 = {Text = "Hmm..."},
  AvgDialog_23867_Content_19 = {
    Text = "Saya akan melihat."
  },
  AvgDialog_23867_Content_2 = {
    Text = "Aneh... Aku ingat kapten pernah berkata, jika ada bahaya, kita harus menuju ke arah ruang mesin..."
  },
  AvgDialog_23867_Content_20 = {
    Text = "Jika ingin pergi ke ruang mesin, kamu perlu meninggalkan lapisan kabin ini melalui tangga ini dan naik ke dek atas."
  },
  AvgDialog_23867_Content_21 = {
    Text = "Benar, benar! Aku juga ingat, ruang mesin itu sangat tertutup, tetapi karena hanya ada satu jalan masuk dan keluar, maka lebih aman."
  },
  AvgDialog_23867_Content_22 = {
    Text = "Kalau begitu, sepertinya aku harus kembali ke geladak."
  },
  AvgDialog_23867_Content_23 = {
    Text = "Saya dan Ramona dikepung oleh Pelaut di dek... Pasti masih ada Pelaut yang berkeliaran dan berpatroli di dek. Kita harus berhati-hati dan menghindari Pertempuran sebisa mungkin."
  },
  AvgDialog_23867_Content_3 = {Text = "Murphy..."},
  AvgDialog_23867_Content_4 = {
    Text = "Jangan berisik, mengganggu saya saat sedang berpikir."
  },
  AvgDialog_23867_Content_5 = {
    Text = [[
Terkait "mengganggu Murphy berpikir", kamu tidak memberikan pendapat.
Namun, kamu tahu bahwa kamu harus menghentikannya dari terus "berpikir".]]
  },
  AvgDialog_23867_Content_6 = {
    Text = "Di bawah kepemimpinan Murphy, kalian bertiga berjalan hingga ke ujung ruang kapal. Di hadapan kalian terdapat dinding baja yang dingin dan keras, dengan hanya sebuah tangga menuju ke atas; tidak ada jalan lain untuk dilanjutkan."
  },
  AvgDialog_23867_Content_7 = {
    Text = "Apakah kamu tersesat?"
  },
  AvgDialog_23867_Content_8 = {
    Text = "Tidak! Aku tidak mungkin tersesat!"
  },
  AvgDialog_23867_Content_9 = {
    Text = "Saya telah tinggal di kapal ini selama beberapa bulan. Di mana ada saluran ventilasi dan di mana ada lubang tikus, saya mengetahuinya dengan sangat jelas."
  },
  AvgDialog_23872_Content_1 = {Text = "Murid"},
  AvgDialog_23880_Content_1 = {
    Text = "Kabut hitam diam-diam melepaskan Soleil, mengalir tanpa arah ke segala penjuru."
  },
  AvgDialog_23880_Content_10 = {
    Text = "Kemudian dunia tempat kalian berada mulai runtuh berantakan."
  },
  AvgDialog_23880_Content_11 = {
    Text = "Kubah langit terkelupas helai demi helai bagaikan kapas yang beterbangan, dunia yang terlihat seolah layar yang tertiup angin kencang—pertama berubah bentuk, lalu robek, dan hancur berkeping-keping."
  },
  AvgDialog_23880_Content_12 = {
    Text = [[
8:58PM
Waktu tersisa sebelum Ruang Rahasia runtuh: <Red:2> menit]]
  },
  AvgDialog_23880_Content_13 = {
    Text = "Ruang rahasia akan runtuh! Kita hanya perlu bertahan sampai detik terakhir, jangan sampai tersentuh kabut hitam ini…"
  },
  AvgDialog_23880_Content_14 = {
    Text = "Kalian terhuyung-huyung menuju tepi teras."
  },
  AvgDialog_23880_Content_15 = {
    Text = "Gawat… kita sudah tidak punya jalan mundur!"
  },
  AvgDialog_23880_Content_16 = {
    Text = "Di belakang kalian, kabut hitam yang mengaum dan bergulung datang menyerbu bagaikan ombak laut."
  },
  AvgDialog_23880_Content_17 = {
    Text = "Sementara di depan adalah jurang hitam tak berujung."
  },
  AvgDialog_23880_Content_18 = {
    Text = [[
8:59PM
Waktu sebelum runtuhnya ruang rahasia: <Red:1> menit]]
  },
  AvgDialog_23880_Content_19 = {
    Text = "Soreil perlahan menggenggam tanganmu."
  },
  AvgDialog_23880_Content_2 = {
    Text = "……Dia sudah pergi?"
  },
  AvgDialog_23880_Content_20 = {
    Text = "Kali ini pegang yang erat ya, Penjaga Rahasia."
  },
  AvgDialog_23880_Content_21 = {
    Text = "Detik berikutnya, kalian bersama-sama terjun ke dalam kegelapan pekat di depan."
  },
  AvgDialog_23880_Content_22 = {
    Text = "Suara angin menderu terdengar di telinga, bagaikan napas lembut para dewa yang berguling dalam tidur."
  },
  AvgDialog_23880_Content_23 = {
    Text = "Tangan Soreil menggenggam erat tanganmu, helai rambutnya yang berantakan saling terjalin dengan kegelapan. Tiba-tiba dia tertawa."
  },
  AvgDialog_23880_Content_24 = {
    Text = "Kenapa kamu tertawa?"
  },
  AvgDialog_23880_Content_25 = {
    Text = "…Kamu sekarang terlihat seperti seorang ksatria sejati."
  },
  AvgDialog_23880_Content_26 = {
    Text = "Seorang ksatria sejati yang terhormat, yang terpaksa menyelamatkan sang putri palsu."
  },
  AvgDialog_23880_Content_27 = {
    Text = "Kamu memandangi wajahnya yang begitu dekat. Berbeda dari kesempurnaan tanpa cela di masa lalu, saat ini dia penuh luka dan kelelahan."
  },
  AvgDialog_23880_Content_28 = {
    Text = "Justru menurutku… kamu sekarang juga terlihat seperti seorang putri sejati."
  },
  AvgDialog_23880_Content_29 = {
    Text = "Mata Soreil melengkung lembut, bagaikan danau yang tak terukur dalamnya, memantulkan cahaya bintang yang lembut."
  },
  AvgDialog_23880_Content_3 = {
    Text = "Soleil perlahan memejamkan kedua matanya."
  },
  AvgDialog_23880_Content_30 = {
    Text = "Suatu kehormatan bagiku, %player%."
  },
  AvgDialog_23880_Content_32 = {
    Text = "Kabut hitam pekat yang terus menyebar tertinggal jauh di belakang kalian. Kamu memeluk erat Soreil, membiarkan dirimu terjun bebas dalam kegelapan."
  },
  AvgDialog_23880_Content_33 = {
    Text = [[
9:00PM
<Red:Ruang Rahasia Runtuh>]]
  },
  AvgDialog_23880_Content_34 = {
    Text = "Dong—— dong——"
  },
  AvgDialog_23880_Content_35 = {
    Text = "Dentang lonceng penanda waktu mengalun perlahan, tenggelam hingga ke dasar jurang terdalam."
  },
  AvgDialog_23880_Content_36 = {
    Text = "Kemudian kau mendengar suara Secret Realm yang hancur berkeping-keping, bagaikan sebuah hati yang tiba-tiba pecah di kejauhan tanpa ada yang menyadari."
  },
  AvgDialog_23880_Content_37 = {
    Text = "Kau juga mendengar suara tulang-tulang kalian patah bersamaan, darah dan daging berhamburan."
  },
  AvgDialog_23880_Content_38 = {
    Text = "Aroma mawar samar-samar tercium di ujung hidung. Kau memejamkan mata, untuk pertama kalinya merasa beban di pundakmu terangkat."
  },
  AvgDialog_23880_Content_39 = {
    Text = "■<Yellow:Ringkasan Investigasi Secret Realm Buatan Ketiga>\n\nKami berhasil mengusir N dan serangan kabut hitam itu sebelum Secret Realm runtuh.\nAku tidak yakin apakah ini berhasil, tetapi setelah kebangkitan kedua Nyonya Soreil, punggung tangannya bersih, tanpa sisa kontrak apa pun.\n\nMenurut Nona Dorel, kalimat pertama yang diucapkan Nyonya Soreil setelah terbangun adalah——"
  },
  AvgDialog_23880_Content_4 = {
    Text = "Aku tidak bisa merasakan aura-Nya lagi, sepertinya sudah pergi."
  },
  AvgDialog_23880_Content_40 = {
    Text = "<Yellow:Kita berhasil melarikan diri bersama.>"
  },
  AvgDialog_23880_Content_5 = {
    Text = "Dia selalu benci hal-hal yang merepotkan."
  },
  AvgDialog_23880_Content_6 = {
    Text = "Lalu kabut hitam ini……?"
  },
  AvgDialog_23880_Content_7 = {
    Text = "Jangan sentuh mereka, kalau tidak kau bisa terbawa ke dimensi yang tak terduga."
  },
  AvgDialog_23880_Content_8 = {
    Text = "Dung dung. Dung dung."
  },
  AvgDialog_23880_Content_9 = {
    Text = "Kau seperti mendengar detak nadi yang cepat dari kedalaman alam semesta, kabut hitam pekat itu bagaikan pasang surut yang tak berujung."
  },
  AvgDialog_23881_Content_1 = {
    Text = "Eh…… Dia sepertinya menghilang lagi?"
  },
  AvgDialog_23881_Content_10 = {
    Text = "Rencanaku… sudah ketahuan… Ukh!"
  },
  AvgDialog_23881_Content_11 = {
    Text = "Soreil mengerang tertahan. Cairan lengket merembes keluar dari huruf-huruf yang terukir di punggung tangannya, lalu perlahan merambat ke seluruh tubuhnya."
  },
  AvgDialog_23881_Content_13 = {
    Text = "Pisau tajam itu tanpa ragu memotong duri-duri yang menjalar, bahkan rok mewahnya ikut terkoyak, memperlihatkan kulit di baliknya yang penuh luka."
  },
  AvgDialog_23881_Content_14 = {
    Text = "Soreil menggenggam bilah tajam di tangannya, wajahnya tanpa ekspresi, bahkan matanya pun tak berkedip."
  },
  AvgDialog_23881_Content_15 = {
    Text = "Pisau ini… bukankah milik Tuan Lambert…?"
  },
  AvgDialog_23881_Content_16 = {
    Text = "Benar. Sejak awal aku sudah tahu dia bersembunyi di luar, menggenggam pisau ini di tangannya."
  },
  AvgDialog_23881_Content_17 = {
    Text = "Sayang sekali, aku menunggu dan terus menunggu… tapi pada akhirnya dia membuang pisau ini dan melarikan diri."
  },
  AvgDialog_23881_Content_18 = {
    Text = "Heh… ayahku tersayang, selain menambah masalah, apa lagi yang bisa dia lakukan?"
  },
  AvgDialog_23881_Content_19 = {
    Text = "Dia bahkan tidak sanggup membunuhku."
  },
  AvgDialog_23881_Content_2 = {
    Text = "Hanya bermain petak umpet dengan kita. Bersembunyi di tempat gelap, menikmati rasa takut dan penderitaanku……"
  },
  AvgDialog_23881_Content_21 = {
    Text = "Soreil menyayat sulur-sulur yang tumbuh liar satu demi satu, daging-daging yang membusuk pun dia keruk habis."
  },
  AvgDialog_23881_Content_22 = {
    Text = "Dia mendongak menatap langit-langit yang gelap gulita tak terlihat ujungnya."
  },
  AvgDialog_23881_Content_23 = {
    Text = "Anda pasti sangat senang sekarang, bukan? Melihat penampilanku yang begitu menyedihkan ini…"
  },
  AvgDialog_23881_Content_24 = {
    Text = "Seperti yang sudah tak terhitung kali sebelumnya, dia tidak mendapat jawaban apa pun — selain kabut yang melilit tubuhnya."
  },
  AvgDialog_23881_Content_25 = {
    Text = "Jadi ini hukuman karena melanggar perjanjian? Aku tidak akan jatuh di sini…"
  },
  AvgDialog_23881_Content_26 = {
    Text = "Ketika baru keluar dari pedesaan Constance, aku seorang diri, tanpa uang, tanpa nama."
  },
  AvgDialog_23881_Content_27 = {
    Text = [[
Kebohongan adalah jubahku, desas-desus adalah senjataku, dan orang-orang biasa adalah tangga yang kupanjat ke atas.
Segala sesuatu di dunia ini, semuanya kumanfaatkan untuk kepentinganku.]]
  },
  AvgDialog_23881_Content_28 = {
    Text = "Aku bisa sampai di titik ini bukan berkat ayahku, juga bukan karena N."
  },
  AvgDialog_23881_Content_29 = {
    Text = "Satu-satunya hal yang benar-benar kuandalkan sejak dulu — adalah diriku sendiri."
  },
  AvgDialog_23881_Content_3 = {
    Text = "Uuh——!!"
  },
  AvgDialog_23881_Content_30 = {
    Text = "Akulah yang memilih menandatangani perjanjian dengan-Nya, akulah yang memilih melanggar perjanjian itu, dan akulah yang memilih…"
  },
  AvgDialog_23881_Content_31 = {
    Text = "Untuk selamanya bebas dari ayahku."
  },
  AvgDialog_23881_Content_32 = {
    Text = "Dia perlahan menggenggam pergelangan tanganmu."
  },
  AvgDialog_23881_Content_33 = {
    Text = "Bayangan hitam ini hanyalah proyeksi-Nya di dunia nyata, bukan berarti tidak ada cara untuk menghadapinya."
  },
  AvgDialog_23881_Content_34 = {
    Text = "Selama bisa <Yellow:bertahan hingga Secret Realm berakhir>, aku akan kembali menjadi Soleil yang bangkit dari kematian, dan kontrak itu pun akan kehilangan efeknya."
  },
  AvgDialog_23881_Content_35 = {
    Text = "Bantu aku melewati krisis ini, dan aku akan mempertimbangkan untuk menyetujui syarat yang kalian ajukan."
  },
  AvgDialog_23881_Content_36 = {
    Text = "<Gray:Di saat seperti ini masih hanya \"mempertimbangkan\"……?>"
  },
  AvgDialog_23881_Content_37 = {
    Text = [[
Aku tahu apa yang kaupikirkan.
Tenang saja, kalau aku bisa menyetujui tujuh puluh persen dari persyaratan itu, para tetua itu seharusnya sudah buka sampanye untuk merayakannya.]]
  },
  AvgDialog_23881_Content_38 = {
    Text = "Tapi ini hanya Secret Realm buatan, Anda tidak akan menerima luka apa pun di dunia nyata, kenapa……"
  },
  AvgDialog_23881_Content_4 = {
    Text = "Soreil terduduk lemas di tanah. Di bawahnya, genangan darah merah gelap perlahan meluas dari balik roknya."
  },
  AvgDialog_23881_Content_40 = {
    Text = "Desahan penuh kenikmatan terdengar dari atas kepala kalian, seolah sudah cukup puas menikmati ketakutan dan keputusasaan kalian."
  },
  AvgDialog_23881_Content_41 = {
    Text = "Kabut hitam terus merembes keluar dari mata, hidung, dan tenggorokannya, lalu menelan seluruh gedung opera."
  },
  AvgDialog_23881_Content_42 = {
    Text = "Sebuah celah terkoyak dalam kegelapan, seolah alam semesta membuka mulutnya yang raksasa, dengan planet-planet yang berguling tanpa tujuan di dalamnya."
  },
  AvgDialog_23881_Content_43 = {
    Text = "Atau seolah para dewa membuka mata mereka dengan malas dari dalam mimpi."
  },
  AvgDialog_23881_Content_44 = {
    Text = "Tanpa cahaya, tanpa kepemilikan, tanpa perasaan."
  },
  AvgDialog_23881_Content_45 = {
    Text = "Gemuruh——"
  },
  AvgDialog_23881_Content_46 = {
    Text = "Diiringi dentuman keras, balkon tempat kalian berada menjadi satu-satunya pulau terpencil di tengah lautan kegelapan."
  },
  AvgDialog_23881_Content_47 = {
    Text = "Soleil saat ini berlutut di depan celah itu. Tak terhitung lengan yang terbentuk dari kabut pekat mencengkeramnya erat-erat, berusaha menyeretnya masuk ke dalam celah di belakangnya."
  },
  AvgDialog_23881_Content_48 = {
    Text = "Nyonya Soreil!!"
  },
  AvgDialog_23881_Content_49 = {
    Text = "Kau lihat itu……Dia adalah keberadaan yang mengabaikan segala hukum.\nRealitas, mimpi, bagi-Nya tidak ada perbedaan sama sekali."
  },
  AvgDialog_23881_Content_5 = {
    Text = "Nyonya, Anda— Anda berdarah!"
  },
  AvgDialog_23881_Content_50 = {
    Text = "Kabut hitam menembus tubuhnya, lalu meluap dengan ganas dari mata, hidung, dan telinganya."
  },
  AvgDialog_23881_Content_51 = {
    Text = "Darah segar semakin banyak mengalir dari sudut bibir Soleil, dia tersenyum lembut kepadamu."
  },
  AvgDialog_23881_Content_52 = {
    Text = "Bantu aku, kita usir Dia bersama-sama."
  },
  AvgDialog_23881_Content_54 = {
    Text = "Uang, kekuasaan, atau apa pun yang kau mau. Selama kau bisa menyelamatkanku, aku akan berusaha memenuhi keinginanmu."
  },
  AvgDialog_23881_Content_55 = {
    Text = "Dia berjuang untuk mendekat ke arahmu, namun wajahnya tidak menunjukkan raut memohon sedikit pun."
  },
  AvgDialog_23881_Content_56 = {
    Text = "Yang lebih terasa adalah naluri bertahan hidup seekor hewan yang sekarat, yang akan melakukan apa saja demi tetap hidup."
  },
  AvgDialog_23881_Content_57 = {
    Text = "%player%……Kau masih berutang segelas minuman padaku, sudah lupa?"
  },
  AvgDialog_23881_Content_58 = {
    Text = "Membantu, atau tidak?"
  },
  AvgDialog_23881_Content_59 = {
    Text = "Meski tahu dia bisa mengingkari janjinya kapan saja, kau tetap memutuskan untuk bertaruh."
  },
  AvgDialog_23881_Content_6 = {
    Text = "Soreil dengan hati-hati menyeka darah segar yang merembes dari sudut bibirnya. Bahkan di saat seperti ini, ia tak akan kehilangan setitik pun keanggunannya."
  },
  AvgDialog_23881_Content_60 = {Text = "Aku setuju"},
  AvgDialog_23881_Content_61 = {
    Text = "Tolong jangan salah paham, aku hanya ingin memastikan negosiasi berjalan lancar……"
  },
  AvgDialog_23881_Content_62 = {
    Text = "Sudut bibir Soleil sedikit terangkat, matanya berbinar bagai bintang, menerangi sekelilingnya di malam yang sunyi ini."
  },
  AvgDialog_23881_Content_63 = {
    Text = "Kau bukan hanya seorang ksatria, tapi juga ksatria yang cerdas."
  },
  AvgDialog_23881_Content_7 = {
    Text = "Dengan susah payah ia mengangkat kepalanya, menatap lurus ke kedua matamu."
  },
  AvgDialog_23881_Content_8 = {
    Text = "Dia sangat tertarik padamu. Kau yang berulang kali menyelinap ke dalam kesadaranku, akhirnya menarik perhatian-Nya."
  },
  AvgDialog_23881_Content_9 = {
    Text = "Di mana darah mengalir, bunga mawar yang mengerikan bermekaran sepanjang jalan, duri-duri tajamnya berubah menjadi kabut hitam pekat, perlahan melilit tubuhnya."
  },
  AvgDialog_23882_Content_1 = {
    Text = "Racikan Spesial Lamprey"
  },
  AvgDialog_23882_Content_10 = {
    Text = "<Red:BRAK——!!>"
  },
  AvgDialog_23882_Content_11 = {
    Text = "Bagus, ada respons. Siapkan kejut listrik kedua."
  },
  AvgDialog_23882_Content_12 = {
    Text = "<Red:BRAK——!!>"
  },
  AvgDialog_23882_Content_14 = {
    Text = "Huf… akhirnya berhasil diselamatkan."
  },
  AvgDialog_23882_Content_15 = {
    Text = "Selamat datang kembali, %player%."
  },
  AvgDialog_23882_Content_16 = {
    Text = [[
Ruang Medis Misagor
Dua jam kemudian]]
  },
  AvgDialog_23882_Content_17 = {
    Text = "Nona Sylvia, kenapa kamu juga ada di sini…"
  },
  AvgDialog_23882_Content_18 = {
    Text = "Kudengar ada orang yang masuk-keluarDomain buatan dua kali berturut-turut. Sebagai konselor psikologis Misagor, tentu saja aku harus datang untuk memperhatikan kondisi mental kalian semua."
  },
  AvgDialog_23882_Content_19 = {
    Text = "Maaf, Nona Sylvia, sudah merepotkan kalian…"
  },
  AvgDialog_23882_Content_2 = {
    Text = "Adrenalin pun tak berguna, mata dan hidung terus mengeluarkan darah…… telinga juga……"
  },
  AvgDialog_23882_Content_20 = {
    Text = "Sylvia menggelengkan kepalanya pelan."
  },
  AvgDialog_23882_Content_21 = {
    Text = "Tenang saja, kali ini aku datang dengan persiapan matang——"
  },
  AvgDialog_23882_Content_22 = {
    Text = "Kali ini aku membawa <Blue:Teh Oolong Lamprey> racikan terbaruku, yang memiliki khasiat menyegarkan pikiran lho~"
  },
  AvgDialog_23882_Content_23 = {
    Text = "Lamprey? Teh Oolong? Bagaimana bisa keduanya dikombinasikan…"
  },
  AvgDialog_23882_Content_24 = {
    Text = [[
Teh ini memancarkan aura tak menyenangkan yang kuat, baik dari namanya maupun aromanya.
Kamu memberanikan diri meminumnya beberapa teguk.]]
  },
  AvgDialog_23882_Content_25 = {
    Text = "Bagaimana? Kamu adalah orang pertama yang mencobanya lho."
  },
  AvgDialog_23882_Content_26 = {
    Text = "Ramona itu, bahkan tidak mau melirik sedikit pun dan langsung menolak, benar-benar kejam…"
  },
  AvgDialog_23882_Content_27 = {
    Text = "Pahit. Benar-benar terlalu pahit."
  },
  AvgDialog_23882_Content_28 = {
    Text = "Sylvia menatapmu dengan penuh antusias, kamu hanya bisa memberanikan diri minum dua teguk lagi."
  },
  AvgDialog_23882_Content_29 = {
    Text = "Lu-lumayan… harus kuakui, rasanya sangat berkesan, memang benar-benar menyegarkan pikiran."
  },
  AvgDialog_23882_Content_3 = {
    Text = "Jantung berhenti berdetak. Bagaimana kalau kita coba seperti yang dikatakan Winkel…… kejut listrik……"
  },
  AvgDialog_23882_Content_30 = {
    Text = "Setengah jam kemudian"
  },
  AvgDialog_23882_Content_31 = {
    Text = "Apa sebenarnya yang terjadi di dalamDomain?"
  },
  AvgDialog_23882_Content_32 = {
    Text = "Ramona bilang kau dan Nyonya Sorrel minum-minum sambil bercanda soal Dexter, lalu setelah itu tidak bisa dihubungi lagi."
  },
  AvgDialog_23882_Content_33 = {
    Text = "……Aku ketahuan."
  },
  AvgDialog_23882_Content_34 = {Text = "?!"},
  AvgDialog_23882_Content_35 = {
    Text = "Kesadaran Nyonya Sorrel, atau sesuatu yang lain, menyadari bahwa aku menyusup ke dalam Mystic Realm."
  },
  AvgDialog_23882_Content_36 = {
    Text = "Bayangan hitam yang muncul di atas panggung itu……adalah keberadaan yang sangat kuat."
  },
  AvgDialog_23882_Content_37 = {
    Text = "Dia menyadari keberadaanku, lalu melemparku keluar."
  },
  AvgDialog_23882_Content_38 = {
    Text = "Begitu rupanya, kita meremehkan Nyonya Sorrel. Bayangan hitam itu mungkin bagian dari kesadarannya……"
  },
  AvgDialog_23882_Content_39 = {
    Text = "Karena insting perlindungan, dia akan mengusir semua penyusup dari luar."
  },
  AvgDialog_23882_Content_4 = {
    Text = "Tidak bisa, risikonya terlalu besar."
  },
  AvgDialog_23882_Content_40 = {
    Text = "Mungkin saja……Ingatanku seperti ada yang hilang, aku merasa bayangan hitam itu juga mengatakan sesuatu yang sangat penting……"
  },
  AvgDialog_23882_Content_41 = {
    Text = "Proses pemurnian Silver Core Nyonya Sorrel berjalan lancar. Pertanyaan-pertanyaan ini hanya bisa dijawab setelah dia bangkit untuk kedua kalinya, kita tanyakan langsung padanya."
  },
  AvgDialog_23882_Content_42 = {
    Text = "Kalau begitu, apakah kita masih perlu masuk ke Mystic Realm untuk menyelidiki?"
  },
  AvgDialog_23882_Content_43 = {
    Text = "Khasiat teh oolong memang luar biasa. Kau dengan tajam menyadari bahwa tatapan Dor untuk sesaat tampak menghindar—sesuatu yang sangat jarang terjadi."
  },
  AvgDialog_23882_Content_44 = {
    Text = "……Jangan terburu-buru, istirahatlah dulu dengan baik."
  },
  AvgDialog_23882_Content_45 = {Text = "Tok tok."},
  AvgDialog_23882_Content_46 = {
    Text = "Ketukan pintu yang teratur terdengar, dan Dexter melangkah masuk dengan kaki panjangnya."
  },
  AvgDialog_23882_Content_47 = {
    Text = "Syukurlah kau akhirnya sadar. Ramona menangis merengek ingin menjengukmu, bajuku hampir dicakar habis olehnya."
  },
  AvgDialog_23882_Content_48 = {
    Text = "Mau coba teh oolong yang ada di tanganku ini? Bisa membantu menyegarkan pikiran dan segera menyingkirkan delusi yang tidak perlu."
  },
  AvgDialog_23882_Content_49 = {
    Text = "Mana boleh begitu? Racikan spesial yang disiapkan Nona Sylvia dengan penuh perhatian untukmu, aku tidak layak menikmatinya."
  },
  AvgDialog_23882_Content_51 = {
    Text = "Wajahmu pucat begitu? Kalau begitu, mari kita bicara hal yang menyenangkan saja."
  },
  AvgDialog_23882_Content_52 = {
    Text = "Kali ini kalian berhasil mencapai terobosan besar di dalam Mystic Realm buatan."
  },
  AvgDialog_23882_Content_53 = {
    Text = "Aku sangat penasaran dengan bangsawan tua yang kalian temui di dalam sana, jadi aku pergi minum-minum dengan teman dari kepolisian."
  },
  AvgDialog_23882_Content_54 = {
    Text = "……Minum-minum itulah tujuan sebenarnya, kan."
  },
  AvgDialog_23882_Content_55 = {
    Text = "Uhuk uhuk. Singkat cerita, mereka memberitahuku bahwa pada hari kematian Nyonya Sorrel, sebenarnya ada satu orang yang pergi tanpa membuat pernyataan."
  },
  AvgDialog_23882_Content_56 = {Text = "?!"},
  AvgDialog_23882_Content_57 = {
    Text = "Bukankah dikatakan semua orang sudah membuat pernyataan?"
  },
  AvgDialog_23882_Content_58 = {
    Text = "Mereka tidak berkata jujur. Identitas tamu ini sangat terhormat, bukan orang yang bisa mereka berani usik."
  },
  AvgDialog_23882_Content_59 = {
    Text = "Setelah berkata demikian, Dexter membanting selembar koran di hadapan kalian."
  },
  AvgDialog_23882_Content_6 = {
    Text = "……………"
  },
  AvgDialog_23882_Content_60 = {
    Text = "Di koran itu tertulis judul dengan huruf besar yang menggemparkan:\"Kasih Sayang Ayah dan Anak! Sorrel Menjadikan Ayahnya Sebagai Pewaris Tunggal dalam Wasiat\", disertai sebuah foto."
  },
  AvgDialog_23882_Content_61 = {
    Text = "Dalam foto itu, Sorrel berpelukan erat dengan seorang pria tua bernama <Blue:Lambert>. Tentu saja, sambil menyeka air mata, dia tidak lupa dengan sengaja memamerkan cincin pirus yang dikenakannya."
  },
  AvgDialog_23882_Content_62 = {
    Text = "Cincin itu dengan cepat menjadi tren populer tahun itu, berbagai tiruan bermunculan tanpa henti."
  },
  AvgDialog_23882_Content_63 = {
    Text = "Coba kenali, apakah Tuan Lambert ini adalah tuan rumah yang kalian temui di dalam Densitas Buatan?"
  },
  AvgDialog_23882_Content_64 = {
    Text = "Saat itu dia hanya memperlihatkan satu tangan. Sangat kurus, seperti orang yang sedang sakit parah, dan mengenakan banyak cincin…"
  },
  AvgDialog_23882_Content_65 = {
    Text = "Pria tua di foto itu mengenakan pakaian mewah, wajahnya tidak terlihat jelas. Kamu memandang tangannya yang memeluk erat Sorrel."
  },
  AvgDialog_23882_Content_66 = {
    Text = "Gaya berpakaian yang sama mencoloknya, tubuh yang sama kurusnya, bahkan posisi bintik-bintik penuaan pun sama…\nItu memang dia."
  },
  AvgDialog_23882_Content_67 = {
    Text = "Selain itu, kami juga menemukan sebuah kediaman di dalam sana, dipenuhi tanaman mawar liar. Aku menduga itu berkaitan dengan Nyonya Sorrel…"
  },
  AvgDialog_23882_Content_68 = {
    Text = "Dexter mengangguk."
  },
  AvgDialog_23882_Content_69 = {
    Text = "Aku meminta temanku untuk memeriksanya, rumah itu sekarang terdaftar atas nama ayah Sorrel, Tuan Lambert."
  },
  AvgDialog_23882_Content_7 = {
    Text = "Lakukan saja. Siapkan kejut listrik pertama."
  },
  AvgDialog_23882_Content_70 = {
    Text = "Di dalam Densitas, ada seseorang yang mondar-mandir dengan pisau di luar kamar VIP Nyonya Sorrel. Dilihat dari postur tubuhnya, seharusnya juga Tuan Lambert ini."
  },
  AvgDialog_23882_Content_71 = {
    Text = "Bagus, sekarang semuanya terhubung. <Yellow:Tuan Lambert memiliki kecurigaan kuat sebagai pelaku.>"
  },
  AvgDialog_23882_Content_72 = {
    Text = "Bagaimana dengan bayangan bertopeng itu? Kita melihat dengan mata kepala sendiri dia membunuh Sorrel."
  },
  AvgDialog_23882_Content_73 = {
    Text = "Mungkin saja dia kaki tangan, tangkap Lambert dulu baru bicara."
  },
  AvgDialog_23882_Content_75 = {
    Text = "Kudengar hubungan antara Sorrel dan Tuan Lambert sangat dekat, mereka sering terlihat bersama di berbagai acara sosial. Tidak disangka di baliknya ada cerita seperti ini."
  },
  AvgDialog_23882_Content_76 = {
    Text = "Seorang ayah mencelakai putri kandungnya sendiri? Sungguh belum pernah kudengar sebelumnya."
  },
  AvgDialog_23882_Content_77 = {
    Text = "Dexter mengangkat bahu dengan tampak tak acuh."
  },
  AvgDialog_23882_Content_78 = {
    Text = "Semakin dekat dengan kekuasaan dan uang, semakin jauh dari kemanusiaan. Orang-orang di lingkaran ini paling pandai berakting."
  },
  AvgDialog_23882_Content_79 = {
    Text = "Kalau kau sendiri, Lord Dexter? Apa kau juga pandai berakting?"
  },
  AvgDialog_23882_Content_80 = {
    Text = "Dexter terdiam sesaat, lalu tertawa terbahak-bahak."
  },
  AvgDialog_23882_Content_81 = {
    Text = "Jawabanku tidak punya nilai referensi apa pun, Nak. Kau harus percaya pada penilaianmu sendiri."
  },
  AvgDialog_23882_Content_82 = {
    Text = "……Lebih baik kita kembali ke pokok permasalahan. Ke mana Ramona pergi?"
  },
  AvgDialog_23882_Content_83 = {
    Text = "Dia pulih lebih cepat, dan pergi bersama pihak kepolisian untuk menangkap Tuan Lambert."
  },
  AvgDialog_23882_Content_84 = {
    Text = "Rubah tua ini sangat licik, kita tidak boleh memberinya kesempatan untuk melarikan diri."
  },
  AvgDialog_23882_Content_85 = {
    Text = [[
Universitas Misagar
Kantor Administrasi]]
  },
  AvgDialog_23882_Content_86 = {
    Text = "Sekarang tinggal kita berdua saja, mari bicara terus terang."
  },
  AvgDialog_23882_Content_87 = {
    Text = "%player% dan Ramona mungkin tidak paham situasinya, tapi aku tidak semudah itu dibodohi."
  },
  AvgDialog_23882_Content_88 = {
    Text = "<Yellow:Soreil adalah Awakened yang sudah hidup ratusan tahun, dari mana dia punya ayah?>"
  },
  AvgDialog_23882_Content_9 = {
    Text = "Aku… sudah mati…?"
  },
  AvgDialog_23882_Content_90 = {
    Text = "Soal dia, sebaiknya jangan kau tanyakan. Tanya pun percuma — pengambil keputusan akhir dalam penyelidikan ini bukan aku."
  },
  AvgDialog_23882_Content_91 = {
    Text = "Benar juga, sepertinya kita memang menerima kasus yang luar biasa merepotkan."
  },
  AvgDialog_23882_Content_92 = {
    Text = "Situasinya mungkin lebih serius dari yang kau kira. <Yellow:Atasan> mengirim orang ke sini hari ini, memintaku berbicara empat mata dengan %player%, ada tugas baru untuk {Male=dia,Female=dia}."
  },
  AvgDialog_23882_Content_93 = {
    Text = "Sampai mengusik para petinggi di atas……"
  },
  AvgDialog_23882_Content_94 = {
    Text = "Soreil bukan Awakened biasa. Kekuatan di belakangnya, sumber daya yang bisa dia gerakkan, semuanya tidak bisa diremehkan, bahkan melampaui klanmu."
  },
  AvgDialog_23882_Content_95 = {
    Text = "Kejadian yang berkaitan dengannya, orang-orang di atas tidak akan membiarkan Misagar menanganinya secara independen."
  },
  AvgDialog_23882_Content_96 = {
    Text = "Aku tidak peduli apa yang direncanakan para orang tua itu. Batas terakhirku hanya satu —"
  },
  AvgDialog_23882_Content_97 = {
    Text = "Keselamatan kedua anak itu."
  },
  AvgDialog_23882_Content_98 = {
    Text = "Doer menghela napas yang nyaris tak terdengar."
  },
  AvgDialog_23882_Content_99 = {
    Text = "Entah kau percaya atau tidak, itu juga batas terakhirku."
  },
  AvgDialog_23883_Content_1 = {
    Text = "Bukan hanya mawar, ada juga aroma lavender dan jeruk……"
  },
  AvgDialog_23883_Content_2 = {
    Text = "Jangan-jangan ini benar-benar air mandi Nyonya Soleil?"
  },
  AvgDialog_23883_Content_4 = {
    Text = "Apakah ini sepenting itu bagimu?"
  },
  AvgDialog_23883_Content_5 = {
    Text = "Kalau ini memang air mandinya, memangnya kamu mau apa?"
  },
  AvgDialog_23884_Content_1 = {
    Text = "Dipersembahkan untuk Soreil"
  },
  AvgDialog_23884_Content_10 = {
    Text = "Sedangkan ayahnya yang malang itu, kini menjadi pembunuh yang menyiksa putrinya sendiri, bahkan tuduhan percobaan pembunuhan bangsawan pun dibebankan kepadanya."
  },
  AvgDialog_23884_Content_100 = {
    Text = "Seluruh tubuh Rambert gemetar tanpa henti, tawa tajam dan pelan terus mengalir keluar dari kedalaman tenggorokannya."
  },
  AvgDialog_23884_Content_101 = {
    Text = "Aku memang pernah berkata, hanya kematian sejati yang bisa mengakhiri kontrak kita, dan kau tanpa ragu langsung mempercayainya."
  },
  AvgDialog_23884_Content_102 = {
    Text = "Jiwa yang lemah selalu berharap pada belas kasihan penguasa, dan percaya sepenuhnya pada aturan dunia ini."
  },
  AvgDialog_23884_Content_103 = {
    Text = "Tapi semua ini tak lebih dari permainan Kami belaka."
  },
  AvgDialog_23884_Content_104 = {
    Text = "<Shake:Kau bukan dia…… Kau adalah……>"
  },
  AvgDialog_23884_Content_105 = {
    Text = "Lambert menyelimuti dirinya dalam kabut hitam pekat. Sosoknya mulai berubah dan bermutasi seiring dengan denyut napas kabut itu…"
  },
  AvgDialog_23884_Content_106 = {
    Text = "<RedItalic:Aku yang membuat aturan, dan aku pula yang menghancurkannya.>"
  },
  AvgDialog_23884_Content_107 = {
    Text = [[
Lama tidak bertemu, Soleil.
Aku sangat merindukanmu, jadi aku meminjam tubuh Tuan Lambert sebentar.]]
  },
  AvgDialog_23884_Content_108 = {
    Text = "Sungguh menyedihkan… Sepertinya kau tidak ingin bertemu denganku, bahkan sudah melakukan segala cara untuk melepaskan diri dariku."
  },
  AvgDialog_23884_Content_109 = {
    Text = "Kabut hitam tak berujung membanjir keluar, menembus tubuh Soleil."
  },
  AvgDialog_23884_Content_11 = {
    Text = "Ngomong-ngomong, Soreil seharusnya berterima kasih padamu. Kalau bukan karena kau yang menariknya keluar di dalam Secret Realm buatan itu……"
  },
  AvgDialog_23884_Content_110 = {
    Text = "Ti-tidak… Kontrak kita, seharusnya sudah kuhancurkan…"
  },
  AvgDialog_23884_Content_111 = {
    Text = [[
Tapi kau malah berbalik dan menandatangani perjanjian dengan para bodoh itu.
Kau pernah menjadi milikku, mana mungkin aku rela melihatmu dikendalikan oleh mereka?]]
  },
  AvgDialog_23884_Content_112 = {
    Text = "Tentu saja aku ingin menyadarkanmu agar kembali ke jalan yang benar. Permainan petak umpet di dalam Alam Rahasia itu hanyalah hadiah pertemuan kecil, suka tidak?"
  },
  AvgDialog_23884_Content_113 = {
    Text = "Soleil jatuh berlutut kesakitan. Di punggung tangannya yang pucat, huruf yang familiar itu muncul samar sesaat, lalu menghilang dengan cepat."
  },
  AvgDialog_23884_Content_114 = {
    Text = "Secepat kehidupan manusia yang berlalu dalam sekejap mata."
  },
  AvgDialog_23884_Content_115 = {
    Text = "Aku sudah merencanakannya selama ini, apakah semuanya sia-sia…"
  },
  AvgDialog_23884_Content_116 = {
    Text = "<Gray:Tidak, aku tidak percaya… Pasti ada jalan…>"
  },
  AvgDialog_23884_Content_117 = {
    Text = "Angin sepoi bertiup lembut, kelopak mawar liar merah delima menari-nari di udara. Soleil mencium aroma bunga yang samar, milik kenangan yang jauh."
  },
  AvgDialog_23884_Content_118 = {
    Text = "Soleil, kau tahu apa makna bunga mawar liar?"
  },
  AvgDialog_23884_Content_119 = {
    Text = "Hmm… Cinta yang setia dan abadi?"
  },
  AvgDialog_23884_Content_12 = {
    Text = "Kau menggelengkan kepala."
  },
  AvgDialog_23884_Content_120 = {
    Text = "Bukan hanya itu. Kudengar di Londinium yang jauh, mawar liar juga melambangkan harapan yang indah."
  },
  AvgDialog_23884_Content_121 = {
    Text = [[
Harapan akan cinta, kasih sayang keluarga, dan segala keindahan di dunia ini.
Soleil, suatu hari nanti kau juga akan menjadi harapan bagi semua orang.]]
  },
  AvgDialog_23884_Content_122 = {
    Text = "Menjadi harapan bagi semua orang…? Mengapa?"
  },
  AvgDialog_23884_Content_123 = {
    Text = [[
Karena kau seperti mawar liar ini, cantik dan tangguh.
Kau tidak akan pernah seperti aku, yang selalu menangis.]]
  },
  AvgDialog_23884_Content_124 = {
    Text = [[
Putriku, dia tidak pernah mudah menangis, dan tidak pernah mudah menyerah.
Dia akan meraih takdirnya sendiri dengan tangannya sendiri.]]
  },
  AvgDialog_23884_Content_125 = {
    Text = "Soreil menyeka darah yang mengalir dari sudut bibirnya, meremas erat ujung roknya. Ia masih tak berani menatap langsung wajah N, tetapi suaranya tak lagi gemetar."
  },
  AvgDialog_23884_Content_126 = {
    Text = [[
Tuan, Anda sedang ketakutan.
Anda takut pada Misager, dan juga takut pada Penjaga Rahasia yang baru itu.]]
  },
  AvgDialog_23884_Content_127 = {
    Text = "Kabut hitam di balik pinggiran topi N bergetar pelan, dan tawa serak penuh kesenangan terdengar dari dalamnya."
  },
  AvgDialog_23884_Content_128 = {
    Text = "Itu bukan ketakutan, anakku. Bukankah kalian manusia punya ungkapan \"gugup saat mendekati kampung halaman\"?"
  },
  AvgDialog_23884_Content_129 = {
    Text = "Memang ada alasan tertentu yang tak bisa kuhindarkan, yang membuatku ingin menjaga jarak dari Misager, dan dari %player%."
  },
  AvgDialog_23884_Content_13 = {
    Text = "Aku hanyalah alat negosiasi yang ditugaskan dari atas. Kalau dia benar-benar mati, bukankah negosiasinya jadi sia-sia?"
  },
  AvgDialog_23884_Content_130 = {
    Text = "Karena itulah Anda tidak mau berlama-lama di dalam Alam Tersembunyi, dan itu memberi kami kesempatan untuk melarikan diri."
  },
  AvgDialog_23884_Content_131 = {
    Text = "Tuan, Anda telah berjalan di dunia manusia selama ribuan tahun, tentu Anda sudah paham—"
  },
  AvgDialog_23884_Content_132 = {
    Text = "Ketika seseorang terpojok tanpa jalan keluar, hatinya sudah tak mengenal rasa takut lagi."
  },
  AvgDialog_23884_Content_133 = {
    Text = "Benar, hari ini aku kembali menjadi tawananmu, karena kelemahanku dan kebodohanku."
  },
  AvgDialog_23884_Content_134 = {
    Text = "Tapi tidak apa-apa.\nSekali, dua kali… selama masih ada secercah kesempatan untuk melarikan diri, aku tidak akan menyia-nyiakannya."
  },
  AvgDialog_23884_Content_135 = {
    Text = "Entah kesempatan itu datang dari Misager atau %player%, bagiku sama saja."
  },
  AvgDialog_23884_Content_136 = {
    Text = "Bukankah Anda sangat suka bertaruh dengan orang lain? Bagaimana kalau kita juga bertaruh…"
  },
  AvgDialog_23884_Content_137 = {
    Text = "Perkembanganmu sungguh semakin mengejutkan. Katakan, apa taruhannya?"
  },
  AvgDialog_23884_Content_138 = {
    Text = "Soreil perlahan memejamkan matanya. Ia menganggap dirinya rasional, dan selalu membenci risiko."
  },
  AvgDialog_23884_Content_139 = {
    Text = "Tapi hidup berbeda. Hidup itu sendiri adalah pertaruhan besar, tak ada yang bisa menghindar darinya."
  },
  AvgDialog_23884_Content_14 = {
    Text = "Jadi ya…… hanya pekerjaan rutin biasa saja."
  },
  AvgDialog_23884_Content_140 = {
    Text = "Taruhannya adalah… segalanya yang kumiliki."
  },
  AvgDialog_23884_Content_141 = {
    Text = [[
Baiklah, cerita ini sampai di sini dulu.
Adapun nasib gadis mawar itu selanjutnya, mari kita nantikan bersama.]]
  },
  AvgDialog_23884_Content_142 = {
    Text = "Agar akhir cerita ini tidak terkesan terlalu asal-asalan, biar kutambahkan sedikit lagi."
  },
  AvgDialog_23884_Content_143 = {
    Text = "Manusia maupun Awakened… kalian selalu naif, mengira bisa melepaskan diri dariku, menciptakan masa depan dengan usaha kalian sendiri."
  },
  AvgDialog_23884_Content_144 = {
    Text = "<Red:Tapi semua itu sia-sia belaka.>"
  },
  AvgDialog_23884_Content_145 = {
    Text = "Kalian tidak akan pernah bisa lepas dariku, sama seperti kalian tidak akan pernah bisa lepas dari <Yellow:takdir>."
  },
  AvgDialog_23884_Content_146 = {
    Text = "Ingatlah……"
  },
  AvgDialog_23884_Content_147 = {
    Text = "Saat kalian menghindari <Yellow:takdir>, kalian sudah berhadapan dengan <Red:takdir>."
  },
  AvgDialog_23884_Content_15 = {
    Text = "<Shake:Uwaaah! Nyonya Soreil muncul!!>"
  },
  AvgDialog_23884_Content_17 = {
    Text = "Kedua sisi jalan dipenuhi oleh warga yang sudah menunggu sejak awal. Ini adalah penampilan publik pertama Nyonya Soreil sejak insiden jatuh dari gedung."
  },
  AvgDialog_23884_Content_18 = {
    Text = "Dia mengenakan pakaian megah, dengan tenang menyambut tatapan kagum semua orang di tengah kelopak mawar yang beterbangan di udara, tampak bagaikan boneka yang sangat indah."
  },
  AvgDialog_23884_Content_19 = {
    Text = "Rambut panjangnya berkilau keemasan di bawah sinar matahari, bagaikan pita-pita sutra yang berkibar anggun."
  },
  AvgDialog_23884_Content_2 = {
    Text = [[
Pusat Kota Londinium
Satu bulan kemudian]]
  },
  AvgDialog_23884_Content_20 = {
    Text = "Nyonya Soreil! <Big:Nyonya Soreil——!!>"
  },
  AvgDialog_23884_Content_21 = {
    Text = "Ya Tuhan, dia tadi melihatku, dia melihatku!"
  },
  AvgDialog_23884_Content_22 = {
    Text = "Kamu dan Ramona terdesak ke pinggir oleh kerumunan yang ramai, hanya bisa memandang Soreil dari kejauhan."
  },
  AvgDialog_23884_Content_23 = {
    Text = "Merobek kontrak, menyingkirkan lawan, lalu sekalian menendang ayahnya yang menjadi beban — dalam waktu singkat satu bulan, dia telah melampaui pencapaian dari keinginan lamanya."
  },
  AvgDialog_23884_Content_24 = {
    Text = "Tidak lagi dikendalikan orang lain, tidak lagi dipermainkan siapa pun."
  },
  AvgDialog_23884_Content_25 = {
    Text = "Soreil mengangkat kepalanya tinggi-tinggi, dengan tenang melangkah melewati barisan bunga dan tepuk tangan, menuju masa depan yang menjadi miliknya."
  },
  AvgDialog_23884_Content_27 = {
    Text = "Tiba-tiba teringat, ini pertama kalinya aku melihatnya di luar Mystic Realm."
  },
  AvgDialog_23884_Content_28 = {
    Text = "Pada hari Soreil berhasil dibangunkan, semua orang dilarang keras untuk menjenguknya."
  },
  AvgDialog_23884_Content_29 = {
    Text = "Kamu hanya tahu bahwa setelah itu dia melakukan negosiasi alot selama seminggu dengan pihak yang disebut <Yellow:petinggi>, dan kedua belah pihak akhirnya menandatangani sebuah perjanjian rahasia."
  },
  AvgDialog_23884_Content_3 = {
    Text = "<BigShake:Berita besar!!>"
  },
  AvgDialog_23884_Content_30 = {
    Text = "Adapun isi perjanjian itu sebenarnya apa, kamu tidak berhak untuk bertanya."
  },
  AvgDialog_23884_Content_31 = {
    Text = "Kamu kelihatannya agak melamun. Ada yang mengganggu pikiranmu?"
  },
  AvgDialog_23884_Content_32 = {
    Text = "……Dengan penampilannya yang sekarang, aku hampir tidak mengenalinya."
  },
  AvgDialog_23884_Content_33 = {
    Text = "Soreil di dalam Mystic Realm tampaknya jauh lebih hidup — dia dengan ceroboh memelukmu, mentraktirmu sampanye yang sangat mahal…"
  },
  AvgDialog_23884_Content_34 = {
    Text = "Dan tanpa ragu menarikmu jatuh bersama ke dalam jurang."
  },
  AvgDialog_23884_Content_36 = {
    Text = "Mungkin dia sudah tidak ingat apa-apa lagi.\nAku bahkan curiga, memanfaatkanku untuk menyingkirkan N juga termasuk dalam perhitungannya…"
  },
  AvgDialog_23884_Content_37 = {
    Text = "Pipinya tiba-tiba terasa dingin sesaat oleh sesuatu."
  },
  AvgDialog_23884_Content_38 = {
    Text = "<Shake:Sss——! Ada apa ini……>"
  },
  AvgDialog_23884_Content_39 = {
    Text = "Kenapa, baru beberapa hari tidak bertemu, sudah tidak ingat aku lagi!"
  },
  AvgDialog_23884_Content_4 = {
    Text = "Tak disangka, Nyonya Soreil yang beberapa waktu lalu meninggal karena jatuh dari gedung ternyata hidup kembali dari kematian!"
  },
  AvgDialog_23884_Content_40 = {
    Text = "Nona Karen……"
  },
  AvgDialog_23884_Content_41 = {
    Text = "Karen dengan senyum lebar menyerahkan sebotol Champagne berpita kepadamu."
  },
  AvgDialog_23884_Content_42 = {
    Text = "Nyonya kami sangat berterima kasih atas bantuanmu kepadanya di dalam Secret Realm, dan secara khusus menugaskan Karen untuk mengantarkan hadiah istimewa untukmu."
  },
  AvgDialog_23884_Content_43 = {
    Text = "Kamu menerima sampanye yang dingin itu dan mengamatinya dengan penasaran."
  },
  AvgDialog_23884_Content_44 = {
    Text = "Ini adalah botol sampanye yang pernah kamu minum di Secret Realm. Di bawah sinar matahari, botol hijau tua berlapis emas itu berkilauan dengan cahaya keemasan yang lembut, terlihat jelas harganya sangat mahal."
  },
  AvgDialog_23884_Content_45 = {
    Text = "Simpan baik-baik ya, botol anggur ini super duper mahal lho!"
  },
  AvgDialog_23884_Content_46 = {
    Text = "<SmallShake:Kalau aku jadi kamu, pasti akan memilih menjualnya kembali, seumur hidup tidak perlu khawatir soal makan dan pakaian lagi!>"
  },
  AvgDialog_23884_Content_47 = {
    Text = "Ternyata dia mengingat semuanya……"
  },
  AvgDialog_23884_Content_48 = {
    Text = "Kamu mendongak dengan sedikit terkejut."
  },
  AvgDialog_23884_Content_5 = {
    Text = "Kabarnya dia nyaris dibunuh oleh ayahnya sendiri, @2·Lambert, dan kemudian salah didiagnosis meninggal oleh dokter yang tidak kompeten!"
  },
  AvgDialog_23884_Content_50 = {
    Text = "Soreil semakin mendekat kepadamu, dan tepat di saat kalian berpapasan, dia tersenyum tipis kepadamu."
  },
  AvgDialog_23884_Content_51 = {
    Text = "Ujung hidungmu mencium aroma bunga yang segar, seperti mawar yang baru mekar menghadap mentari pagi, tak ada lagi bau busuk."
  },
  AvgDialog_23884_Content_52 = {
    Text = "Kelopak bunga merah yang beterbangan menari anggun di bawah sinar matahari, helai rambut emasnya bergoyang bagai ombak laut, berkilauan dengan cahaya sang surya."
  },
  AvgDialog_23884_Content_53 = {
    Text = "Di saat menatapmu, riasan sempurnanya seolah menampakkan sedikit retakan, memperpendek jarak di antara kalian."
  },
  AvgDialog_23884_Content_54 = {
    Text = "Di balik hiruk-pikuk kerumunan, kamu seperti mendengarnya berkata——"
  },
  AvgDialog_23884_Content_55 = {
    Text = "Kamu masih berhutang segelas anggur padaku, Penjaga Rahasia."
  },
  AvgDialog_23884_Content_58 = {
    Text = [[
Pinggiran Londinium
Kediaman Lombert]]
  },
  AvgDialog_23884_Content_59 = {
    Text = "Pria tua yang muram itu duduk di aula yang sepi sendirian, menatap dalam diam tamu tak diundang yang mendorong pintu masuk."
  },
  AvgDialog_23884_Content_6 = {
    Text = "Setelah dikubur di dalam peti mati selama hampir satu bulan, pada suatu malam yang gelap gulita, penjaga hutan Jacob tiba-tiba mendengar suara ketukan dari dalam peti mati……"
  },
  AvgDialog_23884_Content_60 = {
    Text = "Selamat siang, Ayahku."
  },
  AvgDialog_23884_Content_61 = {
    Text = "Sungguh tamu langka, Soreil. Setelah bangkrut, berapa kali aku ditolak mentah-mentah olehmu, bahkan aku sendiri sudah tidak ingat lagi."
  },
  AvgDialog_23884_Content_62 = {
    Text = "Kukira kau sudah lama lupa bahwa kau masih punya seorang ayah."
  },
  AvgDialog_23884_Content_63 = {
    Text = "Inikah sikapmu terhadap orang yang menyelamatkan nyawamu? Mengeluarkanmu dari penjara membutuhkan banyak usaha dariku."
  },
  AvgDialog_23884_Content_64 = {
    Text = "Kau sudah cukup cerdas untuk sengaja menyebarkan kabar wasiat demi memancingku datang, lalu kau pikir aku akan percaya, uhuk uhuk…… kau mengeluarkanku demi menyelamatkan nyawaku?"
  },
  AvgDialog_23884_Content_66 = {
    Text = [[
Kudengar saat dibawa polisi, kau mengakui "kejahatanmu" tanpa pembelaan sedikit pun.
Mengapa?]]
  },
  AvgDialog_23884_Content_67 = {
    Text = "Sejak saat kau jatuh dari gedung itu, aku sudah menyadarinya. Aku bukan tandinganmu."
  },
  AvgDialog_23884_Content_68 = {
    Text = "Putriku adalah iblis yang cukup kejam untuk membunuh dirinya sendiri, lalu mengirim ayah kandungnya ke tiang gantungan."
  },
  AvgDialog_23884_Content_69 = {
    Text = "Karena aku punya guru yang hebat, ayahku yang paling tercinta."
  },
  AvgDialog_23884_Content_7 = {
    Text = "Menyebut kebangkitan kedua sebagai hidup kembali dari kematian, karangannya lumayan bagus."
  },
  AvgDialog_23884_Content_70 = {
    Text = "Pria tua itu tertawa terbahak-bahak, lalu menoleh memandang lukisan potret yang tergantung di dinding."
  },
  AvgDialog_23884_Content_71 = {
    Text = "Pergilah, Soleil."
  },
  AvgDialog_23884_Content_72 = {
    Text = "Kalau ibumu Rebecca masih hidup, dia pasti tidak ingin melihat kita menjadi seperti ini."
  },
  AvgDialog_23884_Content_73 = {
    Text = "Soleil melangkah melewati kelopak bunga dan dedaunan kering yang berserakan di lantai, menghampiri ayahnya."
  },
  AvgDialog_23884_Content_74 = {
    Text = "Dia berjongkok dan menyandarkan kepalanya perlahan di atas lutut sang ayah yang rapuh dan gemetar."
  },
  AvgDialog_23884_Content_75 = {
    Text = "Jangan menghindar dariku, Ayah. Ini seharusnya menjadi pertemuan terakhir kita."
  },
  AvgDialog_23884_Content_76 = {
    Text = "Masih ingat waktu kecil, aku paling suka bersandar di lututmu seperti ini……"
  },
  AvgDialog_23884_Content_77 = {
    Text = "Lambert terdiam, tubuhnya yang lapuk gemetar sesaat."
  },
  AvgDialog_23884_Content_78 = {
    Text = "Kita adalah orang yang sama. Ambisi yang tak pernah berhenti mengalir dalam pembuluh darah kita, mengubah kita menjadi iblis yang diperbudak nama dan kekuasaan."
  },
  AvgDialog_23884_Content_79 = {
    Text = "Aku tidak akan pernah bisa membenci Anda, seperti aku tidak akan pernah membenci diriku sendiri."
  },
  AvgDialog_23884_Content_8 = {
    Text = "Sekarang reputasi Soreil di kalangan rakyat semakin tinggi. Kudengar di distrik barat sudah ada enam atau tujuh pertunjukan terkait yang sedang dipersiapkan."
  },
  AvgDialog_23884_Content_80 = {
    Text = "Lambert memandang potret mendiang istrinya, air mata mengalir tak terbendung."
  },
  AvgDialog_23884_Content_81 = {
    Text = "Benarkah…… Tapi saat aku memandang wajah ibumu, hatiku terasa sangat sedih.\nAku berbeda denganmu, Soleil."
  },
  AvgDialog_23884_Content_82 = {
    Text = "Aku tidak mau menjadi sepertimu, aku tidak mau……"
  },
  AvgDialog_23884_Content_83 = {
    Text = "Aku mengerti, aku mengerti semuanya…… Membangkitkanmu, lalu membiarkan Erosi menyebar ke tubuhmu, semua itu ide N, kan?"
  },
  AvgDialog_23884_Content_84 = {
    Text = "Tujuannya untuk mengawasiku dan membuatku muak. Selera-Nya masih saja buruk seperti biasa."
  },
  AvgDialog_23884_Content_85 = {
    Text = "Bagaimana kau bisa tahu?! Berani-beraninya menyebut langsung nama Yang Mulia itu……"
  },
  AvgDialog_23884_Content_86 = {
    Text = "Sungguh ironis. Kita berdua, ayah dan anak, pertama menjadi budak kekuasaan, lalu bersama-sama menjadi budak-Nya."
  },
  AvgDialog_23884_Content_87 = {
    Text = "Saudara saling membunuh, sesama saling memangsa, bukankah itu tontonan favorit-Nya?"
  },
  AvgDialog_23884_Content_88 = {
    Text = "Sekarang kontrakku dengan-Nya sudah lama berakhir. Kita sudah bebas, Ayah."
  },
  AvgDialog_23884_Content_89 = {
    Text = "Aku sudah menyisihkan sejumlah uang dan membuatkan identitas palsu untukmu. Setelah ini kau bisa pergi ke mana pun yang kau mau."
  },
  AvgDialog_23884_Content_9 = {
    Text = "Ya. Dia telah menjadi legenda yang hidup."
  },
  AvgDialog_23884_Content_90 = {
    Text = "Selama seumur hidup ini kau tidak pernah muncul di hadapanku lagi, kau boleh melakukan apa saja."
  },
  AvgDialog_23884_Content_91 = {
    Text = "Heh heh…… Kau sedang menyindirku?\nDengan kondisiku yang mengerikan seperti ini, aku sudah tidak bisa pergi ke mana-mana lagi……"
  },
  AvgDialog_23884_Content_92 = {
    Text = [[
Aku akan mencarikan dokter terbaik untukmu.
Kau adalah ayahku. Selama kau mau, kau pasti bisa bertahan hidup sampai hari dunia ini hancur.]]
  },
  AvgDialog_23884_Content_93 = {
    Text = "Ucap Soreil seraya menghembuskan napas panjang."
  },
  AvgDialog_23884_Content_94 = {
    Text = "Aku sudah cukup lama menunggu hari ini. Sekarang akhirnya aku memiliki cukup modal untuk memutus semua ini dengan tanganku sendiri……"
  },
  AvgDialog_23884_Content_95 = {
    Text = "Selamat tinggal, Ayahku."
  },
  AvgDialog_23884_Content_96 = {
    Text = "<Red:Hihi.>"
  },
  AvgDialog_23884_Content_97 = {
    Text = "Sebuah tawa dingin yang singkat namun familiar tiba-tiba menusuk telinga."
  },
  AvgDialog_23884_Content_98 = {Text = "?!"},
  AvgDialog_23884_Content_99 = {
    Text = "Selamat… tinggal? Soreil, oh Soreil-ku yang naif……"
  },
  AvgDialog_24075_Content_1 = {Text = "Ugh!!"},
  AvgDialog_24075_Content_10 = {
    Text = "Bahkan sampai rela membunuh putri kandungmu sendiri…"
  },
  AvgDialog_24075_Content_11 = {
    Text = "Lambert dengan santai mengangkat gelas anggur dari meja, lalu menyesap sedikit anggur merah di dalamnya."
  },
  AvgDialog_24075_Content_12 = {
    Text = "Heh heh… Di mata kalian, tentu saja aku sudah lama tak bisa mengecap rasa anggur ini."
  },
  AvgDialog_24075_Content_13 = {
    Text = "Tapi tahukah kau? Saat aku menelannya, ingatan dan imajinasiku terus-menerus memberitahuku…"
  },
  AvgDialog_24075_Content_14 = {
    Text = "Ini adalah anggur merah Montrachet tahun @2. Awalnya, aromanya seharusnya tercium seperti akar manis, dan setelah dua jam, kau akan merasakan aroma mawar yang pekat…"
  },
  AvgDialog_24075_Content_15 = {
    Text = "Lambert menghirup aroma anggur merah di gelasnya dengan penuh kenikmatan, wajahnya menampakkan senyum penuh kepuasan."
  },
  AvgDialog_24075_Content_16 = {
    Text = "Itu hanyalah imajinasi belaka. Cepat atau lambat Anda harus menghadapi kenyataan, Tuan Lambert."
  },
  AvgDialog_24075_Content_17 = {
    Text = "Ya, imajinasi! Itu adalah kekuatan yang dahsyat."
  },
  AvgDialog_24075_Content_18 = {
    Text = "Imajinasi akan uang, imajinasi akan kekuasaan, imajinasi akan nafsu… Ia mampu menjatuhkan biarawan paling suci, sekaligus mengubah pencuri paling hina menjadi seorang nabi."
  },
  AvgDialog_24075_Content_19 = {
    Text = "Lalu putriku yang paling tersayang? Dia berani-beraninya merampas imajinasi terakhirku."
  },
  AvgDialog_24075_Content_2 = {
    Text = "Tuan Lambert, Anda sudah tidak punya jalan mundur lagi. Tolong bekerja sama dengan kami."
  },
  AvgDialog_24075_Content_20 = {
    Text = "Sekarang satu-satunya barang berharga yang tersisa padaku hanyalah sebotol anggur ini. Sungguh hal paling kejam di dunia ini…"
  },
  AvgDialog_24075_Content_21 = {
    Text = "Maka aku terpaksa melakukan kejahatan yang memalukan ini."
  },
  AvgDialog_24075_Content_22 = {
    Text = "Sekarang kalian boleh membawaku pergi, timpakan semua tuduhan pada diriku seorang."
  },
  AvgDialog_24075_Content_23 = {
    Text = [[
Berbeda dengan orang-orang tertentu, aku hanyalah sosok kecil yang tak berarti.
Bagi dunia ini, hidup matiku tak memiliki arti apa pun.]]
  },
  AvgDialog_24075_Content_24 = {
    Text = "Ada makna tersembunyi dalam kata-kata Anda… Apakah Anda sedang menyindir sesuatu, Tuan Lambert?"
  },
  AvgDialog_24075_Content_25 = {
    Text = "Lambert tidak menjawab. Dia tersenyum tipis, lalu membentangkan kedua tangannya ke hadapan semua orang."
  },
  AvgDialog_24075_Content_26 = {
    Text = "Bawalah aku pergi, Tuan Inspektur."
  },
  AvgDialog_24075_Content_27 = {
    Text = "Di luar mansion terdengar hiruk-pikuk, para detektif masih sibuk bekerja di sekitar sana."
  },
  AvgDialog_24075_Content_28 = {
    Text = "Menoleh ke belakang memandang mansion itu, dinding luarnya yang bobrok diselimuti kabut suram yang tak pernah sirna sepanjang tahun, bagaikan bangkai kapal yang tenggelam di dasar laut."
  },
  AvgDialog_24075_Content_29 = {
    Text = "Ramona perlahan melepas lencana di dadanya dan membuka saluran komunikasi dengan Dexter."
  },
  AvgDialog_24075_Content_3 = {
    Text = "Lambert menopang tubuhnya dengan tongkat ramping dari kayu beech, lalu tiba-tiba tertawa terbahak-bahak."
  },
  AvgDialog_24075_Content_30 = {
    Text = "Target telah ditangkap, dan mengakui semua fakta kejahatannya."
  },
  AvgDialog_24075_Content_31 = {
    Text = "Kerja bagus, memang pantas disebut putriku."
  },
  AvgDialog_24075_Content_33 = {
    Text = "Tapi dia? Setelah sukses besar, bukannya membalas budi, malah ingin menjauh dariku sejauh mungkin."
  },
  AvgDialog_24075_Content_34 = {
    Text = "Membalas budi. Ramona diam-diam merenungkan kata itu dalam hatinya."
  },
  AvgDialog_24075_Content_35 = {
    Text = "Ayah, apakah ada sesuatu yang kau ingin aku lakukan untukmu?"
  },
  AvgDialog_24075_Content_36 = {
    Text = "Melakukan sesuatu? Ini kode rahasia baru yang kau dan %player% ciptakan? Aku bahkan tidak mengerti maksudmu."
  },
  AvgDialog_24075_Content_37 = {
    Text = "Umm... misalnya membantumu menghasilkan banyak uang, atau melakukan pekerjaan investigasi atau penelitian untukmu..."
  },
  AvgDialog_24075_Content_38 = {
    Text = "Stop... stop! Permintaan seperti itu tidak berani kuajukan, kau cukup hidup dengan baik saja."
  },
  AvgDialog_24075_Content_39 = {
    Text = "Diiringi dengungan arus listrik yang lembut, ocehan Dexter yang tak henti-hentinya terdengar agak samar, dan Ramona tak bisa menahan diri untuk tertawa."
  },
  AvgDialog_24075_Content_4 = {
    Text = "Apa yang lucu dari semua ini?"
  },
  AvgDialog_24075_Content_40 = {
    Text = "Ayah, terima kasih."
  },
  AvgDialog_24075_Content_41 = {
    Text = "Kau hari ini aneh sekali, tiba-tiba begitu formal. Berterima kasih untuk apa?"
  },
  AvgDialog_24075_Content_42 = {
    Text = "Ramona menundukkan kepala, ujung sepatunya perlahan menginjak-injak dedaunan gugur di bawah kakinya. Sepatu ini juga dibelikan Dexter untuknya."
  },
  AvgDialog_24075_Content_43 = {
    Text = "Gaun kecil, kotak musik, kumbang longhorn merah muda... Dexter juga pernah membelikannya banyak hal lainnya. Tapi dia tidak pernah meminta balasan darinya."
  },
  AvgDialog_24075_Content_44 = {
    Text = "Untuk segalanya."
  },
  AvgDialog_24075_Content_5 = {
    Text = "Jangan takut, Nak… Aku hanya menertawakan diriku sendiri."
  },
  AvgDialog_24075_Content_6 = {
    Text = "Cairan Erosi hitam pekat mengalir deras dari rongga matanya, bagaikan air mata hitam."
  },
  AvgDialog_24075_Content_7 = {
    Text = "Gejala tahap akhir Erosi…\nKalau tebakanku benar, organ-organ dalammu sudah lama berubah menjadi Cairan Erosi."
  },
  AvgDialog_24075_Content_8 = {
    Text = "Kau tidak bisa mencium aroma mawar, merasakan hangatnya matahari, ataupun mengecap rasa anggur merah."
  },
  AvgDialog_24075_Content_9 = {
    Text = "Bagi seseorang sepertimu, uang dan kekuasaan duniawi sudah lama kehilangan maknanya. Lalu mengapa masih mengejarnya?"
  },
  AvgDialog_24078_Content_1 = {
    Text = "Bau busuk yang menyengat perlahan-lahan masuk ke dalam hidung."
  },
  AvgDialog_24078_Content_10 = {Text = "Ngh..."},
  AvgDialog_24078_Content_11 = {
    Text = "Penyelidik dari Universitas Mythag, ditambah dengan Pembangun yang mencuri kekuatan ilahi Lemuria… Apa hanya segini kemampuanmu?"
  },
  AvgDialog_24078_Content_12 = {
    Text = "Tulu melompat ke depanmu, sementara Ramona dengan keringat dingin berlutut di sisimu, berusaha mencabut pedang raksasa Goliath."
  },
  AvgDialog_24078_Content_13 = {
    Text = "Tulu, bawa mereka pergi."
  },
  AvgDialog_24078_Content_14 = {
    Text = "Apa omong kosong yang kamu katakan?!"
  },
  AvgDialog_24078_Content_15 = {
    Text = "Ramona semakin kuat menarik senjata Goliath, mata pisaunya menggores sarung tangan, dan darah berwarna merah gelap seketika meresap melalui lengan bajunya."
  },
  AvgDialog_24078_Content_16 = {
    Text = "Aku akan baik-baik saja. Bukankah Miryam ingin menangkap orang untuk memberi makan Dewa yang akan lahir? Lindungi Celeste dan Murphy, hentikan ritualnya… aku akan mencari cara untuk melarikan diri."
  },
  AvgDialog_24078_Content_17 = {
    Text = "Otakmu kosong, dengan kaku menyusun alasan yang bahkan tidak bisa meyakinkan dirimu sendiri."
  },
  AvgDialog_24078_Content_18 = {Text = "Kau……"},
  AvgDialog_24078_Content_19 = {
    Text = "Lindungi mereka saat mereka pergi!"
  },
  AvgDialog_24078_Content_2 = {
    Text = [[
Pelaut-pelaut dipanggil oleh pemimpin mereka, keluar berbondong-bondong dari kabin-kabin di segala arah.
Dan yang memimpin pengejaran terhadap kalian adalah raksasa yang sangat kalian takuti.]]
  },
  AvgDialog_24078_Content_21 = {
    Text = "Tulu tidak lagi berdebat, lalu memandangmu untuk terakhir kalinya seolah-olah ingin memastikan tekadmu."
  },
  AvgDialog_24078_Content_22 = {
    Text = "Tulu! Cepat turunkan aku!"
  },
  AvgDialog_24078_Content_23 = {
    Text = "Dua tentakel yang kuat masing-masing melilit Ramona dan Celeste. Dalam sekejap, Tulu sudah mengikat keduanya dan membawa mereka berlari ke dalam koridor."
  },
  AvgDialog_24078_Content_24 = {
    Text = "Goliath tertawa keras sambil mencabut senjatanya, berjongkok di depanmu, lalu mencengkeram dagumu dan memaksamu untuk menatapnya langsung."
  },
  AvgDialog_24078_Content_25 = {
    Text = "Seperti yang kukatakan: Jangan sampai dikalahkan oleh prajurit rendahan sebelum aku melihat cukup pertunjukan."
  },
  AvgDialog_24078_Content_26 = {
    Text = "Nada suaranya separuh mengolok-olok, separuh serius, membuat orang sama sekali tidak bisa menebak maksud sebenarnya."
  },
  AvgDialog_24078_Content_27 = {
    Text = [[
Tapi kamu memang orang yang pemberani. 
Sayang sekali, kali ini Miryam sudah menentukan untuk membawa seseorang kembali demi tugas.]]
  },
  AvgDialog_24078_Content_28 = {
    Text = "Hanya bermain-main saja? Atau Goliath benar-benar memiliki niat buruk terhadap Miryam…"
  },
  AvgDialog_24078_Content_3 = {
    Text = "Musuh yang sangat sulit diatasi...!"
  },
  AvgDialog_24078_Content_4 = {
    Text = "Jangan berbantah dengannya! Tulu, lindungi kami dan bantu kami mundur!"
  },
  AvgDialog_24078_Content_5 = {
    Text = "Kamu menarik Ramona keluar dari pertempuran, berlari tanpa memedulikan apa pun menuju luar ruangan."
  },
  AvgDialog_24078_Content_6 = {
    Text = "Cara bertarung Goliath tetap langsung seperti biasa, dia tersenyum santai dan melemparkan belati besar ke arah kalian yang melarikan diri."
  },
  AvgDialog_24078_Content_7 = {Text = "Hati-hati!"},
  AvgDialog_24078_Content_8 = {
    Text = "Kamu tiba-tiba mendorong Ramona ke depan, tetapi bilah raksasa itu menembus betis, menancapkan seluruh tubuhmu di tanah, dan komunikator yang tersemat di dada pun jatuh."
  },
  AvgDialog_24078_Content_9 = {
    Text = "Rasa sakit yang menyengat membuat pandanganmu tiba-tiba memutih, dan suara berdengung bergema di dalam otakmu, bahkan menutupi teriakan kaget Ramona."
  },
  AvgDialog_24079_Content_1 = {
    Text = "Mengejar bintang-bintang"
  },
  AvgDialog_24079_Content_10 = {
    Text = "Setiap kali Ramona bergerak, bahkan hanya mengubah posisi duduk untuk meredakan rasa sakit, Caecus akan memandangnya dengan penuh kewaspadaan dan mengarahkan senjatanya kepadanya."
  },
  AvgDialog_24079_Content_11 = {
    Text = "Caecus, kamu…"
  },
  AvgDialog_24079_Content_12 = {
    Text = [[
Bersikaplah jujur! 
Jangan coba-coba berbuat curang di bawah pengawasan Nyonya Miryam. Aku akan mengawasimu.]]
  },
  AvgDialog_24079_Content_13 = {
    Text = "<Gray: …… sepenuhnya menolak berkomunikasi denganku, apakah karena takut pada Miryam?>"
  },
  AvgDialog_24079_Content_14 = {
    Text = "<Gray:Sebagai Pembangun yang terhubung dengan keberadaan Pembangun lain melalui Tautan, siapakah sebenarnya Miryam ini…>"
  },
  AvgDialog_24079_Content_15 = {
    Text = "Ramona menghela napas panjang, menyesuaikan ritme pernapasannya untuk mengabaikan rasa sakit yang samar-samar di pergelangan kakinya. Sambil serius mengamati situasi di dalam Ruang Kekuatan, ia khawatir melewatkan kesempatan apa pun yang bisa dimanfaatkan."
  },
  AvgDialog_24079_Content_16 = {
    Text = "Saat suara putaran inti kunci terdengar, semua otot di tubuh langsung menegang."
  },
  AvgDialog_24079_Content_17 = {
    Text = "Huh, huhuhu... Sebuah nafas busuk yang sudah lama terasa."
  },
  AvgDialog_24079_Content_18 = {
    Text = "Sosok tubuh wanita yang anggun dan tegak membentuk kontras yang sangat mencolok dengan para Pelaut. Wajahnya dipenuhi rasa jijik, jelas bahwa dia tidak bersedia berjalan bersama kelompok Pelaut."
  },
  AvgDialog_24079_Content_19 = {
    Text = "Jangan berjalan begitu cepat, bantu aku sedikit! Yang aku pegang ini adalah Pembangun!"
  },
  AvgDialog_24079_Content_2 = {
    Text = "Kapal Kargo Luar Negeri · Sonnier \n Ruang Kekuatan"
  },
  AvgDialog_24079_Content_20 = {Text = "Pembangun?"},
  AvgDialog_24079_Content_21 = {
    Text = "Ramona tiba-tiba mengangkat kepalanya dan melihat ke arah pintu. Seorang gadis berbaju putih sedang dikekang oleh pengikut berpakaian hitam itu, namun dia juga menengadah dan bertemu pandangan Ramona."
  },
  AvgDialog_24079_Content_22 = {
    Text = "Murni, luhur, melampaui, rapuh, tak terhitung kata sifat melintas di benak Ramona."
  },
  AvgDialog_24079_Content_23 = {
    Text = "...manusia."
  },
  AvgDialog_24079_Content_24 = {
    Text = "Pengikut berjubah hitam mendorong Pembangun muda itu sekali, yang kemudian menyingkirkan ekspresi terkejutnya yang samar dan kembali menjadi tanpa kesedihan, tanpa kegembiraan."
  },
  AvgDialog_24079_Content_25 = {
    Text = "Apa yang kamu khawatirkan? Jika tingkat ancamannya lebih tinggi darimu, apakah Miryam masih akan meminta kita untuk mengantarnya kembali ke pos sementara?"
  },
  AvgDialog_24079_Content_26 = {
    Text = "Hmph… Ternyata mereka bersarang di tempat yang begitu kumuh dan kotor. \nOrang-orang barbar ini benar-benar tidak tahu cara menjaga kebersihan."
  },
  AvgDialog_24079_Content_27 = {
    Text = [[
Oke, oke, setelah menyelesaikan misi dan kembali ke <Yellow:Pos Lentera>, kamu bisa berkata apa pun yang kamu inginkan. 
Jangan lupa bahwa kita sekarang berada di wilayah orang lain.]]
  },
  AvgDialog_24079_Content_28 = {
    Text = "<Gray:Pos lentera... Apakah kedua orang ini anggota Gereja Penerang Kuil? Ternyata mereka memang terkait dengan Pelaut.>"
  },
  AvgDialog_24079_Content_29 = {
    Text = "Pengikut wanita itu mendengus dingin, mengambil tali yang mengikat Pembangun, dan dengan kasar menyeretnya ke hadapan Caecus."
  },
  AvgDialog_24079_Content_3 = {
    Text = "Abu batu bara menumpuk seperti gunungan, para pelaut dengan kulit lembap berjalan hilir mudik di ruang kekuatan, sirip ekor mereka meninggalkan jejak hitam yang mirip lumpur di tanah."
  },
  AvgDialog_24079_Content_30 = {
    Text = "Miryam memintaku untuk menyampaikan padamu: awasi mereka berdua."
  },
  AvgDialog_24079_Content_31 = {
    Text = "Menghadapi ketidaksopanan dari Penerang Cahaya Kuil, Caecus saat ini justru menunjukkan ketenangan yang luar biasa. Dia membawa Pembangun ke sisi Ramona, dan kembali menjadi prajurit yang diam."
  },
  AvgDialog_24079_Content_32 = {
    Text = "Keduanya sama-sama aneh, bagaimana mungkin mereka berusaha membuat Raja Dewa yang telah mengalami Pelarutan \"dilahirkan kembali\"? Sungguh tidak masuk akal."
  },
  AvgDialog_24079_Content_33 = {
    Text = "Benar-benar tidak mengerti kenapa <Blue: Tuan Lentera> mau bekerja sama dengan segerombolan orang gila ini, padahal dua puluh lima tahun lalu kalian sudah menyia-nyiakan kesempatan itu."
  },
  AvgDialog_24079_Content_34 = {
    Text = "Kurangi bicara!"
  },
  AvgDialog_24079_Content_35 = {
    Text = "Hai, cukup ramai juga."
  },
  AvgDialog_24079_Content_36 = {
    Text = "Suara rendah dan kasar terdengar, dua Penerang Cahaya Kuil langsung terdiam."
  },
  AvgDialog_24079_Content_37 = {Text = "Goliath."},
  AvgDialog_24079_Content_38 = {
    Text = [[
Caecus dengan hormat menundukkan kepalanya yang angkuh kepada raksasa, nada suaranya penuh dengan pengagungan. 
 Namun, sang raksasa sepertinya mengabaikan kesetiaannya dan malah dengan penuh minat terus menanyai para Penerang cahaya kuil.]]
  },
  AvgDialog_24079_Content_39 = {
    Text = "Kenapa berhenti? Aku belum puas mendengarnya. Ceritakan lebih banyak tentang Lemuria."
  },
  AvgDialog_24079_Content_4 = {
    Text = "<Gray:Ruang Kekuatan hanya memiliki satu pintu masuk dan keluar. Dari posisi saya, seharusnya hanya butuh 7 detik untuk berlari ke sana dengan sekuat tenaga, tetapi…>"
  },
  AvgDialog_24079_Content_40 = {
    Text = "Dia tidak memberikan kesempatan kepada Penerang cahaya kuil untuk membela diri, lalu mengalihkan topik pembicaraan. Matanya langsung tertuju ke arah pintu."
  },
  AvgDialog_24079_Content_41 = {
    Text = "Tentang evaluasi terhadap \"Kerajaan Tuhan\", sepertinya belum ada yang berani mengatakannya langsung kepadamu, Miryam."
  },
  AvgDialog_24079_Content_42 = {
    Text = "Bayangan Miryam melebur ke dalam bayangan di sisi pintu. Tak seorang pun bisa melihat ekspresinya dengan jelas, namun dari dirinya terasa dingin yang menusuk tulang."
  },
  AvgDialog_24079_Content_43 = {
    Text = "<Gray:Kapan dia ada di sana?! Aku sama sekali tidak menyadari kedatangannya…>"
  },
  AvgDialog_24079_Content_44 = {
    Text = "Angin dingin merayap di sekitar kaki, warna darah di wajah para penganut Penerang Cahaya Kuil langsung hilang tersapu — Apakah dia kembali bersama Goliath? Berapa banyak yang didengarnya?"
  },
  AvgDialog_24079_Content_45 = {
    Text = "Namun, baik Ramona maupun dua pengikut Penerang Cahaya Kuil tidak menyangka bahwa Miryam tidak marah besar, bahkan tidak menunjukkan sedikit pun ketidakpuasan."
  },
  AvgDialog_24079_Content_46 = {
    Text = "Dia memandang rendah semua orang dengan sikap angkuh, seolah-olah sandiwara di depannya hanyalah kicauan burung yang tidak berarti."
  },
  AvgDialog_24079_Content_47 = {
    Text = "Goliath, bagaimana kemajuan tugas yang kuberikan padamu?"
  },
  AvgDialog_24079_Content_48 = {
    Text = "Ha... tikus kecil Mythag pandai membuat lubang di mana-mana. Sudah kubilang, jika kita tidak bisa membongkar kapal ini, aku tidak akan menemukan orang lain. Lagipula, bukankah kita masih punya sandera?"
  },
  AvgDialog_24079_Content_49 = {
    Text = "Goliath berkata sambil mengayunkan pedang raksasa ke arah Ramona."
  },
  AvgDialog_24079_Content_5 = {
    Text = "Dia membungkuk untuk memijat pergelangan kakinya. Meskipun sudah melakukan penanganan darurat pada sendi yang terkilir, bagian yang cedera tetap membengkak secara tak terhindarkan. Bahkan sentuhan ringan saja bisa menimbulkan rasa sakit seperti terbakar."
  },
  AvgDialog_24079_Content_50 = {
    Text = "Selama menahan nona ini, saya yakin rekannya akan segera datang mengikuti jejaknya."
  },
  AvgDialog_24079_Content_51 = {
    Text = "Ngomong-ngomong, bagaimana kamu bisa membawa Pembangun milik Elton kemari? Di mana Elton sekarang?"
  },
  AvgDialog_24079_Content_52 = {
    Text = "Upacara semakin dekat, \"negara\" \"Ibu Dewa\" sangatlah penting. Para penolong ritual sudah terbiasa dengan rune tidur damai, namun jika memungkinkan, aku tidak ingin melihat Ibu Dewa menderita."
  },
  AvgDialog_24079_Content_53 = {
    Text = "Selama Celeste berada dalam kendali kami, demi memastikan kapal Sonnelier ini tidak kehilangan kendali, Elton pasti akan dengan patuh menyerahkan Sang Ibu Dewa…"
  },
  AvgDialog_24079_Content_54 = {
    Text = [[
<Gray:Tampaknya, Pembangun inilah yang mengendalikan kapal hantu Sonaniel. 
Jadi, Domain ini juga merupakan karyanya.>]]
  },
  AvgDialog_24079_Content_55 = {
    Text = "<Gray: Tunggu sebentar… mungkin ada cara.>"
  },
  AvgDialog_24079_Content_56 = {
    Text = "Saat semua perhatian tertuju pada Miryam, Ramona diam-diam menyentuh tangan Pembangun gadis itu. Gadis itu menengadah ke arahnya, ekspresi di wajahnya tampak tidak mengandung emosi apa pun."
  },
  AvgDialog_24079_Content_57 = {
    Text = "<Small:Celeste… Mungkin aku punya cara untuk kita melarikan diri.>"
  },
  AvgDialog_24079_Content_58 = {
    Text = "Kabut di mata Celeste sedikit memudar, menampakkan beberapa kilatan rasa terkejut."
  },
  AvgDialog_24079_Content_59 = {
    Text = "<Small:Kamu adalah pemilik Domain, jika kamu bisa membuat Domain menghilang selama beberapa saat dan menyebabkan kekacauan di antara Pelaut…>"
  },
  AvgDialog_24079_Content_6 = {
    Text = "<Gray: Tingkat nyeri sekitar level 4. Berdasarkan evaluasi disfungsi motorik saya pada semester ini, kecepatan akan menurun sebesar 20%…>"
  },
  AvgDialog_24079_Content_60 = {
    Text = "Celeste tidak meresponsnya, hanya berkedip. Ramona tidak tahu apakah dia bisa memahaminya, tetapi dia sendiri menyadari bahwa di bawah sarung tangan sudah berkeringat karena gugup."
  },
  AvgDialog_24079_Content_61 = {
    Text = "<Small:Ini…… permintaanmu?>"
  },
  AvgDialog_24079_Content_62 = {
    Text = "Ramona terkejut, tetapi tubuhnya bereaksi lebih dulu daripada pikirannya — dia tanpa sadar mengangguk."
  },
  AvgDialog_24079_Content_63 = {
    Text = "Celeste mengangkat kompas di tangannya tinggi-tinggi, cahaya berkilauan berputar di sekitar tepi roknya, dan segera menghilang tanpa jejak."
  },
  AvgDialog_24079_Content_64 = {
    Text = "Pada saat yang sama, permukaan laut utara yang sebenarnya membawa udara yang lembap dan dingin. Bersamaan dengan itu, terdengar suara gaduh dan teriakan kaget dari dek kapal."
  },
  AvgDialog_24079_Content_65 = {
    Text = "Bulan! Bulan!"
  },
  AvgDialog_24079_Content_66 = {
    Text = "Pada saat itu, ruang kekuatan tenggelam dalam kegelapan total. Keheningan yang asing dan mendalam menyebar di sekitarnya, kegelapan menelan semua bentuk, namun membuat adrenalin Ramona melonjak tajam."
  },
  AvgDialog_24079_Content_67 = {
    Text = "<Small:Sekaranglah saatnya!>"
  },
  AvgDialog_24079_Content_68 = {
    Text = "Ramona menahan tangan Pembangun, seluruh kekuatannya terfokus pada bagian bawah tubuhnya. Dia menabrak Pelaut di sisinya dan berlari dengan kecepatan penuh menuju Ruang Kekuatan."
  },
  AvgDialog_24079_Content_7 = {
    Text = "<Gray:Waktu tidak cukup. Sekarang ruang kekuatan telah menjadi markas mereka, terlalu banyak musuh, saya akan dihentikan oleh pelaut sebelum mencapai pintu.>"
  },
  AvgDialog_24079_Content_8 = {
    Text = "<Gray:Lagipula... orang ini mengamati terlalu ketat.>"
  },
  AvgDialog_24079_Content_9 = {
    Text = "Pelaut sedang mempersiapkan \"upacara\", dan pemuda Pembangun itu juga dengan setia menjalankan misinya, tidak bergerak sedikit pun, tetap menjaga dia."
  },
  AvgDialog_24080_Content_1 = {
    Text = "Kamu menggelengkan kepala, mengangkat jari telunjuk ke bibir sebagai isyarat agar dia tetap diam untuk sementara. Namun, saat pandanganmu menyapu orang di dalam Bayangan, justru kamu yang hampir tidak bisa menahan teriakan kaget."
  },
  AvgDialog_24080_Content_2 = {
    Text = "<Small:Dia adalah Celeste, seorang Pembangun…>"
  },
  AvgDialog_24080_Content_3 = {
    Text = "Kamu berada di atas kapal Sonnelier, beberapa kali melihatnya dalam Fatamorgana — bayangan yang terasa familiar namun asing ini ternyata adalah Celeste, sosok yang mengendalikan Domain."
  },
  AvgDialog_24080_Content_4 = {
    Text = "Tokoh kunci yang seharusnya dikendalikan oleh Miryam, ternyata berhasil melarikan diri bersama Ramona — benar-benar tak terduga, namun juga dapat diprediksi."
  },
  AvgDialog_24080_Content_5 = {
    Text = "Bagaimanapun juga, pasanganmu bukanlah orang yang hanya duduk diam menunggu."
  },
  AvgDialog_24080_Content_6 = {
    Text = "<Small:… Tunggu, tunggu? Ini adalah Pembangun dengan nomor arsip -6291 Tulu?!>"
  },
  AvgDialog_24080_Content_7 = {
    Text = "<Small:Kita bertemu dulu dengan kapten dan Murphy, nanti aku akan menjelaskan secara perlahan apa yang terjadi.>"
  },
  AvgDialog_24081_Content_1 = {
    Text = "Keajaiban lainnya"
  },
  AvgDialog_24081_Content_10 = {
    Text = "Kapten, seluruh tubuhmu gemetar."
  },
  AvgDialog_24081_Content_11 = {
    Text = "…Penyakit lama. Lagipula, berbeda dengan murid-murid pilihan Misagar, aku hanyalah orang biasa. Tidak punya kekuatan mental yang tangguh, juga tidak bisa melihat <Yellow:Erosi>."
  },
  AvgDialog_24081_Content_12 = {
    Text = "Kesadaran, dalam proses Bangun kembali Pembangun, akan tercemar secara tak terhindarkan oleh keberadaan yang tidak dikenal, dan pencemaran inilah yang menyebabkan mereka kehilangan kendali."
  },
  AvgDialog_24081_Content_13 = {
    Text = "Tautan adalah salah satu metode untuk menekan kehilangan kendali, tetapi jika yang melakukan tautan adalah orang biasa tanpa bakat…"
  },
  AvgDialog_24081_Content_14 = {
    Text = "Apa yang kalian bicarakan? Apa yang dimaksud dengan \"kehilangan kendali\"?"
  },
  AvgDialog_24081_Content_15 = {
    Text = "Elton mengambil kotak rokok yang dijatuhkan Murphy, melihat gerakan kecilnya saat diam-diam menendang tembakau ke sudut, dan tertawa pelan."
  },
  AvgDialog_24081_Content_16 = {
    Text = "Maksudnya, jika kita tidak menemukan Celeste, kapal ini mungkin akan kehilangan kendali dan tenggelam."
  },
  AvgDialog_24081_Content_17 = {
    Text = "Wajah Murphy dengan cepat menjadi lesu, bibirnya bergerak-gerak tanpa tahu harus berkata apa."
  },
  AvgDialog_24081_Content_18 = {
    Text = "Baiklah, baiklah, jangan takut."
  },
  AvgDialog_24081_Content_19 = {
    Text = "Dia menepuk kepala Murphy yang kaku dengan sikap menenangkan, lalu berbalik untuk melihatmu dan Tulu."
  },
  AvgDialog_24081_Content_2 = {Text = "Celeste…"},
  AvgDialog_24081_Content_20 = {
    Text = "Saya bisa merasakan posisi umum Celeste. Kalian bisa membawa Murphy menemukan saya sepanjang jalan, saya yakin membantu saya menemukan Celeste juga tidak akan menjadi masalah, bukan?"
  },
  AvgDialog_24081_Content_21 = {
    Text = "Tulu, bisakah?"
  },
  AvgDialog_24081_Content_22 = {
    Text = "Tulu tidak menjawab, melainkan berbalik dan membuka pintu ruang aman, memberi isyarat untuk berjalan di depan."
  },
  AvgDialog_24081_Content_3 = {
    Text = "Elton menutup matanya sejenak, menghela napas panjang seperti membentuk lingkaran asap, seolah-olah dengan cara itu ia bisa mengeluarkan semua kotoran dari tubuhnya."
  },
  AvgDialog_24081_Content_4 = {
    Text = [[
Ketika Pelaut naik ke kapal, aku dan Celeste tidak bersama. 
 Setelah menunggu begitu lama di safe house, kalian adalah orang pertama yang menemukanku.]]
  },
  AvgDialog_24081_Content_5 = {
    Text = "Bagaimana, bagaimana bisa? Celeste tidak mahir dalam pertempuran, bagaimana jika dia..."
  },
  AvgDialog_24081_Content_6 = {
    Text = "Dia baik-baik saja, tautan antara aku dan dia sangat stabil."
  },
  AvgDialog_24081_Content_7 = {
    Text = "Tautan? Jadi, Celeste ini memang Pembangun…"
  },
  AvgDialog_24081_Content_8 = {
    Text = "Elton tersenyum pahit, dan dia kembali ingin meraih kotak rokok. Namun begitu dia mendapatkan kotak aluminium dingin itu, tangannya tiba-tiba bergetar, dan kotak itu jatuh ke tanah, menyebar daun tembakau ke seluruh tanah."
  },
  AvgDialog_24081_Content_9 = {
    Text = "Kamu tiba-tiba menyadari bahwa kedua tangan Elton gemetar, entah karena masih syok atau sudah kelelahan fisik dan mental hingga mencapai batas maksimalnya."
  },
  AvgDialog_24082_Content_1 = {
    Text = "Tulu, apa yang sedang kamu lihat?"
  },
  AvgDialog_24082_Content_10 = {
    Text = [[
Tubuh dan jiwa Penghubung tidak mampu menopang Kebangkitan dalam menggunakan kemampuannya.
Membentangkan Ruang Tertutup yang mampu mengisolasi tarikan benda langit, Kebangkitan itu mungkin sudah mengerahkan seluruh kekuatannya.]]
  },
  AvgDialog_24082_Content_11 = {
    Text = "Menyekat tarikan benda langit… Murphy!"
  },
  AvgDialog_24082_Content_12 = {
    Text = "Semua orang menoleh ke arah Murphy setelah teriakanmu. Dia erat memegang bagian depan jaket musim dinginnya, dan jari-jarinya tak henti-hentinya bergetar."
  },
  AvgDialog_24082_Content_13 = {
    Text = "Dia mengangkat kepalanya dengan putus asa, tulang rawan di tenggorokannya bergerak menyakitkan. Setiap tarikan dan hembusan napas membakar paru-parunya, dan setiap sel dalam tubuhnya gemetar akibat rangsangan tersebut."
  },
  AvgDialog_24082_Content_14 = {Text = "Murphy?!"},
  AvgDialog_24082_Content_15 = {
    Text = "Kondisinya tidak normal, cepat selesaikan hal-hal yang mengikuti bau ini."
  },
  AvgDialog_24082_Content_2 = {
    Text = "Setelah menyelesaikan gelombang musuh lainnya, Tulu tiba-tiba berhenti di sisi kapal, mengerutkan alisnya sambil memandangi batas Domain yang membungkus seluruh kapal."
  },
  AvgDialog_24082_Content_3 = {
    Text = "Eksistensi Domain melemah."
  },
  AvgDialog_24082_Content_4 = {
    Text = "Untuk menghindari tekanan udara berbahaya di kapal, formasi burung yang sedang berputar tercerai-berai, dan burung-burung laut langsung menukik ke arah cahaya dengan warna aneh itu —"
  },
  AvgDialog_24082_Content_5 = {
    Text = "Satu, dua, tiga... mereka berbaris menabrak cakrawala, berharap bisa melarikan diri dari ruang ini, namun semuanya diblokir dengan lembut oleh batas Domain."
  },
  AvgDialog_24082_Content_6 = {
    Text = "Domain menjadi transparan akibat serangan beruntun dari burung-burung laut, memperlihatkan bulan purnama yang sangat dekat dan bulat sempurna."
  },
  AvgDialog_24082_Content_7 = {
    Text = "Momen itu berlalu dalam sekejap, namun semua orang berhasil menangkapnya dengan tepat——"
  },
  AvgDialog_24082_Content_8 = {
    Text = "Apakah tadi... Domain menghilang sesaat?"
  },
  AvgDialog_24082_Content_9 = {
    Text = "Tidak, tidak mungkin! Celeste seharusnya tidak bisa..."
  },
  AvgDialog_24083_Content_1 = {
    Text = [[
Di bawah bimbingan Celeste, keduanya berjalan melewati ruang-ruang yang seperti labirin. 
 Tidak lama kemudian, mereka memasuki sebuah ruangan yang redup.]]
  },
  AvgDialog_24083_Content_10 = {
    Text = "Pintu berat kabin terbuka, cahaya amber memasuki ruangan. Sarafnya yang tegang tiba-tiba rileks setelah melihat jubah yang dikenakan."
  },
  AvgDialog_24083_Content_11 = {
    Text = "Sang Penjaga Rahasia."
  },
  AvgDialog_24083_Content_2 = {
    Text = "Langkah-langkah berat menembus dek di atas, setiap langkah terasa seperti palu dewa takdir yang jatuh, memukul ketakutan yang tak tertahankan di dalam Jiwa."
  },
  AvgDialog_24083_Content_3 = {
    Text = "<Small:Suara langkah kaki yang sangat berat... Celeste, apakah kamu tahu siapa yang membuat suara ini?>"
  },
  AvgDialog_24083_Content_4 = {
    Text = "Celeste menggelengkan kepalanya, tidak ada emosi yang terlihat di wajah itu."
  },
  AvgDialog_24083_Content_5 = {
    Text = "<Small: Apakah ini orang yang dikirim oleh Pelaut untuk mengejar kita…? Semoga Penjaga tidak bertemu langsung dengan pemilik langkah. Aku tidak ada di sisinya, jika {Male=dia,Female=dia} harus berkelahi sendirian, kemungkinan besar bukan tandingannya…>"
  },
  AvgDialog_24083_Content_6 = {
    Text = "... datang."
  },
  AvgDialog_24083_Content_7 = {Text = "Apa?"},
  AvgDialog_24083_Content_8 = {
    Text = "Belum habis suara Celeste, langkah-langkah terburu-buru terdengar di dek lantai ini. Dari jauh semakin dekat, hingga akhirnya berhenti tepat di luar ruangan tempat mereka bersembunyi."
  },
  AvgDialog_24083_Content_9 = {
    Text = "Ramona memberi isyarat kepada Celeste untuk tidak bergerak, sementara dia sendiri menggenggam senjata dengan erat dan bersembunyi di balik pintu."
  },
  AvgDialog_24084_Content_1 = {
    Text = "Kamu membaringkan Murphy di pangkuanmu. Otot-otot di seluruh tubuhnya sangat kaku, dan kamu merasakan seperti sedang memeluk sebuah patung batu."
  },
  AvgDialog_24084_Content_10 = {
    Text = "Dia mungkin sudah berada di Domain terlalu lama, sehingga reaksinya begitu kuat. Sekarang Domain kembali stabil, dia akan segera pulih."
  },
  AvgDialog_24084_Content_11 = {
    Text = "Tulu belum selesai berbicara, Murphy sudah duduk dengan keringat bercucuran. Dia memegang dadanya, wajahnya tampak bingung."
  },
  AvgDialog_24084_Content_12 = {
    Text = "Aku... aku masih hidup..."
  },
  AvgDialog_24084_Content_13 = {
    Text = "Harus segera mengeluarkan-Nya. Meskipun Domain ini bisa mencegah tarikan benda langit terhadap-Nya, keberadaan-Nya sendiri sudah menjadi beban bagimu."
  },
  AvgDialog_24084_Content_14 = {
    Text = "Bicaranya mudah..."
  },
  AvgDialog_24084_Content_15 = {
    Text = "Kamu teringat kembali pada benda asing yang bersarang di jantungnya."
  },
  AvgDialog_24084_Content_16 = {
    Text = "Pembuluh darahnya menyatu dengan aortanya, bahkan dokter bedah terhebat di Londinium pun tidak dapat menjamin keberhasilan operasi semacam itu."
  },
  AvgDialog_24084_Content_17 = {
    Text = "Domain Sonanier menghentikan pengaruh benda langit. Apakah ada cara lain yang bisa memberi Murphy lebih banyak waktu…"
  },
  AvgDialog_24084_Content_18 = {
    Text = "Waktu... waktu... berhenti..."
  },
  AvgDialog_24084_Content_19 = {Text = "Murphy…"},
  AvgDialog_24084_Content_2 = {
    Text = "Kapten, apakah Anda tahu apa yang terjadi padanya?"
  },
  AvgDialog_24084_Content_20 = {
    Text = "Kapten membantunya berdiri dengan gerakan yang lambat dan penuh kehati-hatian, seperti menangani sebuah porselen dengan sangat hati-hati."
  },
  AvgDialog_24084_Content_21 = {
    Text = "Murid, saya melihat kamu sedang memikirkan sesuatu tadi, apakah kamu punya solusi?"
  },
  AvgDialog_24084_Content_22 = {
    Text = "Bukan solusi... dan sangat berbahaya."
  },
  AvgDialog_24084_Content_23 = {
    Text = "Sampai sejauh ini, sudah tidak bisa lagi memperkirakan apakah itu berbahaya atau tidak. \nKamu boleh katakan saja, asalkan bisa membuat Murphy terbebas dari bahaya…"
  },
  AvgDialog_24084_Content_24 = {
    Text = "Universitas Mythag sedang melakukan Penelitian tentang \"penghentian waktu\"."
  },
  AvgDialog_24084_Content_25 = {
    Text = "Jangan-jangan itu adalah rune yang kalian bawa kembali dari Rumah sakit lai…"
  },
  AvgDialog_24084_Content_26 = {
    Text = "Benar. Boneka dan Nyonya Kerang sedang melakukan penelitian terhadap rune itu, berharap dapat menciptakan ruang yang tidak diburu oleh <Red:Anjing dimensi> untuk eksperimen."
  },
  AvgDialog_24084_Content_27 = {
    Text = "Penelitian sudah mulai terbentuk. Sebelum keberangkatan kami kali ini, Nyonya Kerang telah mulai mempersiapkan eksperimen pada hewan."
  },
  AvgDialog_24084_Content_28 = {
    Text = "Jangan sia-siakan pikiranmu."
  },
  AvgDialog_24084_Content_29 = {
    Text = [[
Sekolah kalian... tidak mungkin berada di laut, kan.
Kembali ke daratan dari sini, lalu bergegas ke sekolah kalian... tidak akan sempat.]]
  },
  AvgDialog_24084_Content_3 = {
    Text = "Dewa… Dewa di dalam tubuhnya…"
  },
  AvgDialog_24084_Content_30 = {
    Text = "Apalagi Celeste... Jika dia jatuh ke tangan wanita itu, masih belum diketahui apakah kapal ini bisa berlabuh atau tidak."
  },
  AvgDialog_24084_Content_31 = {
    Text = "Jadi, kita harus mempercepat. Kapten, bisakah kau menunjukkan lokasi perkiraan di mana Celeste berada? Aku dan Tulu akan mencari cara untuk menemukannya, sementara kau dan Murphy sebaiknya bersembunyi dulu di safe house."
  },
  AvgDialog_24084_Content_32 = {
    Text = "Tidak boleh!"
  },
  AvgDialog_24084_Content_33 = {
    Text = "Kapal. Kapten?"
  },
  AvgDialog_24084_Content_34 = {
    Text = "Elton menyadari kecanggungannya, dia gemetar saat meraih bungkus rokok, namun baru ingat bahwa daun tembakau sudah lama melayang ke tempat yang tak terjangkau saat membuka kotaknya."
  },
  AvgDialog_24084_Content_35 = {
    Text = "...Jangan mencari Celeste."
  },
  AvgDialog_24084_Content_36 = {
    Text = "Kenapa? Apakah Kapten mengetahui sesuatu?"
  },
  AvgDialog_24084_Content_37 = {
    Text = "Elton melepaskan tangan Murphy yang sedari tadi ditopangnya, lalu mundur dua langkah. Dia menunduk memandang kalian, sosoknya yang tinggi sebagian tersembunyi di dalam bayangan."
  },
  AvgDialog_24084_Content_38 = {
    Text = "Celeste… ada di tangan Miryam."
  },
  AvgDialog_24084_Content_39 = {Text = "Apa?!"},
  AvgDialog_24084_Content_4 = {
    Text = "Tulu mendengar itu, ekspresinya sedikit berubah. Salah satu tentakelnya menggulung lengan kiri Murphy di bawah kendalinya."
  },
  AvgDialog_24084_Content_40 = {
    Text = "Raksasa itu... Goliath, begitu naik ke kapal langsung menemukan aku dan Celeste, lalu kami dibawa menghadap Miryam…"
  },
  AvgDialog_24084_Content_41 = {
    Text = "Terharu karena kita berdua adalah orang-orang yang terombang-ambing dan kehilangan arah, aku akan menyerahkan metode untuk memanggil mereka yang telah tiada kepadamu."
  },
  AvgDialog_24084_Content_42 = {
    Text = "Kehadirannya melambangkan bahwa keinginanmu telah terpenuhi, sepertinya kamu sudah mendapatkan cukup penghiburan dari kerabat yang telah meninggal…"
  },
  AvgDialog_24084_Content_43 = {
    Text = [[
Dan harapanku, harapan besar yang diberikan Dewa kepadaku, adalah anak itu. 
Kembalikan padaku Sang Perawan Suci... tidak, kembalikan padaku Ibu Dewa.]]
  },
  AvgDialog_24084_Content_44 = {
    Text = "Dengan tubuh sebagai imam besar, aku berjanji bahwa saat dewaku dilahirkan kembali dan Ranah dewa tiba kembali… engkau juga akan melangkah ke dalam Ranah dewa, menemukan kedamaian abadi."
  },
  AvgDialog_24084_Content_45 = {
    Text = [[
Yang Mulia Imam, saya juga terkejut mendengar kabar tentang hilangnya Sang Ibu Dewa. 
Namun, seperti yang sudah saya katakan, Sang Ibu Dewa tidak berada di kapal.]]
  },
  AvgDialog_24084_Content_46 = {
    Text = "Mengapa harus bersikap berlebihan, pura-pura menjadi orang bodoh?"
  },
  AvgDialog_24084_Content_47 = {
    Text = "Aku pernah sangat mengagumi kecerdasan dan keteguhanmu, apa yang membuatmu berubah dalam kesetiaanmu padaku? \nApakah karena <Blue:Golem> ini? Begitu lemah dan rapuh…"
  },
  AvgDialog_24084_Content_48 = {
    Text = "Semua keputusan diambil olehku. Aku adalah pemilik kapal ini. Celeste hampir tidak memiliki kesadaran diri, apalagi mengubahku?"
  },
  AvgDialog_24084_Content_49 = {
    Text = "Benarkah? Aku bisa membuatmu membangunkannya, dan aku juga bisa membuatnya kembali menjadi segenggam pasir perak."
  },
  AvgDialog_24084_Content_5 = {Text = "Diam."},
  AvgDialog_24084_Content_50 = {Text = "Kau……!"},
  AvgDialog_24084_Content_51 = {
    Text = "Temukan Dewi dan bawa dia kembali ke sisiku dengan utuh."
  },
  AvgDialog_24084_Content_52 = {
    Text = "Ini adalah kesempatan terakhirmu, Elton."
  },
  AvgDialog_24084_Content_6 = {
    Text = "Tulu menutup mata, merasakan informasi yang disampaikan oleh tentakel. Untuk sementara waktu, selain suara ombak yang memukul lambung kapal, hanya ada erangan menyakitkan Murphy di atas dek."
  },
  AvgDialog_24084_Content_7 = {
    Text = "Beberapa detik terasa sangat lama. Tepat sebelum akal sehat hampir tidak bisa bertahan, Tulu akhirnya menarik kembali tentakelnya."
  },
  AvgDialog_24084_Content_8 = {
    Text = "Bagaimana kondisinya?"
  },
  AvgDialog_24084_Content_9 = {
    Text = "Pada detik Domain menghilang, \"dewa palsu\"di dalam tubuhnya merasakan tarikan yang sangat kuat."
  },
  AvgDialog_24091_Content_1 = {
    Text = "Pelaut tidak terlalu takut sakit. Waktu kecil, saya sering menginjak ekor mereka, tapi tidak banyak orang yang bereaksi."
  },
  AvgDialog_24091_Content_10 = {
    Text = "Hanya satu kali ini saja, setelah kembali ke sekolah, putuskan sendiri."
  },
  AvgDialog_24091_Content_11 = {
    Text = "Kamu mengangguk, lalu erat menggenggam Kunci perak di tangan. Dengan penuh konsentrasi, kamu menutup mata dan tenggelam ke dalam kegelapan."
  },
  AvgDialog_24091_Content_12 = {
    Text = "Kamu mengejar bintik cahaya paling terang dalam pandanganmu, Roh-mu terjepit di antara kegelapan yang padat oleh banyak keberadaan, dan otakmu terasa sangat sakit akibat ditarik dengan kuat."
  },
  AvgDialog_24091_Content_13 = {
    Text = "Kamu berusaha \"menjulurkan tanganmu\" dan meraih bintang itu dengan tanganmu."
  },
  AvgDialog_24091_Content_14 = {
    Text = "Seperti jiwa yang meninggalkan tubuh, pandangan tiba-tiba meningkat, ditarik oleh kekuatan yang tak terelakkan keluar dari tubuh."
  },
  AvgDialog_24091_Content_15 = {
    Text = "Kamu melihat dirimu sendiri, melihat Miryam, melihat menara kota yang miring di tengah banjir… Pada akhirnya, kamu melihat seorang pemuda raja yang duduk di atas gunung tinggi dengan ekspresi dingin."
  },
  AvgDialog_24091_Content_16 = {
    Text = [[
Saat membuka mata kembali, aliran Gnosis menyengat sarafmu seperti sengatan listrik. 
 Rasa sakit, namun penuh dengan kekuatan yang belum pernah dirasakan sebelumnya.]]
  },
  AvgDialog_24091_Content_17 = {
    Text = "Hah… akhirnya saat ini tiba juga."
  },
  AvgDialog_24091_Content_18 = {
    Text = "Kali ini, Tulu langsung menyerang Goliath yang tiba-tiba muncul, tidak memberinya kesempatan untuk bertindak lebih dulu."
  },
  AvgDialog_24091_Content_2 = {
    Text = "Ini berarti Pelaut akan terus bangkit tanpa henti… kita tidak bisa menjamin setiap kali dapat membunuh mereka sepenuhnya. Terus bertarung seperti ini bukanlah solusi."
  },
  AvgDialog_24091_Content_20 = {
    Text = [[
Tentakel menghantam terak batubara, menimbulkan awan debu berwarna abu-abu kehitaman. 
 Ketika debu itu jatuh seperti hujan, sosok Miryam tiba-tiba muncul.]]
  },
  AvgDialog_24091_Content_21 = {
    Text = "Miryam, apakah kamu melihat? Anak tiruan itu telah terhubung dengan orang lain——"
  },
  AvgDialog_24091_Content_22 = {
    Text = "Ular raksasa melancarkan serangan seperti badai kepada Goliath dengan kekuatan yang begitu dahsyat, hingga mendorong Goliath dengan keras ke dinding besi Ruang Kekuatan."
  },
  AvgDialog_24091_Content_23 = {
    Text = "Seperti meteor yang jatuh ke bumi, seluruh tubuh Goliath terbenam di dinding kabin."
  },
  AvgDialog_24091_Content_24 = {
    Text = "Tidak termaafkan."
  },
  AvgDialog_24091_Content_25 = {
    Text = "Kotoran, berani menyentuh Tuan dan membagi kekuatan dewa Lemuria..."
  },
  AvgDialog_24091_Content_26 = {
    Text = "Miryam menundukkan kepalanya, melangkah mendekati kalian dengan langkah yang semakin cepat. Meskipun ia berjalan tanpa alas kaki di atas tanah, telinga kalian tetap menangkap suara riak seperti daun yang menyentuh permukaan air."
  },
  AvgDialog_24091_Content_27 = {
    Text = "Tidak termaafkan... Selain aku, tidak ada seorang pun yang bisa Bangun pelaksana Ranah dewa, tidak ada seorang pun!"
  },
  AvgDialog_24091_Content_28 = {
    Text = "Dia, kondisinya tidak baik! Cepat lari!"
  },
  AvgDialog_24091_Content_29 = {
    Text = [[
Pada suatu saat, bayangan semu yang menutupi Ruang Kekuatan mengental menjadi entitas fisik. 
Bangunan dengan bentuk yang sulit digambarkan menjulang tinggi.]]
  },
  AvgDialog_24091_Content_3 = {
    Text = "Yang bisa bertempur hanyalah aku, Tulu, dan Penjaga. Ruang untuk meningkatkan kekuatan pertempuran juga sangat terbatas…"
  },
  AvgDialog_24091_Content_30 = {
    Text = "Yang… Tuan-ku… Murphy… Murphy…"
  },
  AvgDialog_24091_Content_32 = {
    Text = "Sekarang… masih ada ruang untuk bernegosiasi. \nKembali ke ordo, kau tetap menjadi \"Ibu Dewa\" yang terhormat."
  },
  AvgDialog_24091_Content_33 = {
    Text = "Pemakamanmu akan menjadi perayaan pengorbanan terbesar dalam sejarah Ranah Dewa, dihormati oleh puluhan ribu orang… Nama mu juga akan tercatat dalam sejarah, dikenang selama-lamanya."
  },
  AvgDialog_24091_Content_34 = {
    Text = "Kembali padaku, kita bersama-sama... bersama-sama menjatuhkan hukuman pada <Blue:orang yang tidak hormat ini>."
  },
  AvgDialog_24091_Content_35 = {
    Text = [[
Hukum orang kotor yang menyamar sebagai tuanku, dan kembalikan kekuatan tuanku kepada-Nya. 
 Dengan demikian... pemimpin Kerajaan Surgawi akan menjadi sempurna.]]
  },
  AvgDialog_24091_Content_36 = {
    Text = "Miryam, buka matamu dan lihat aku, lihat siapa aku!"
  },
  AvgDialog_24091_Content_37 = {Text = "Diam!"},
  AvgDialog_24091_Content_38 = {
    Text = "Ular raksasa menghilang lalu terkumpul kembali. Di bawah dampak Kekuatan Miryam, ruang secara bertahap menjadi terdistorsi dan berubah."
  },
  AvgDialog_24091_Content_39 = {
    Text = "Palsu, tiruan, penipu, orang yang tidak hormat… orang tanpa keyakinan… dilarang menggunakan bentuk @2!"
  },
  AvgDialog_24091_Content_4 = {
    Text = "Di tengah pembicaraan, mata Ramona tiba-tiba berbinar."
  },
  AvgDialog_24091_Content_40 = {
    Text = "<Change>▼▼ orang... tidak hormat ▼▼… tidak hormat, tidak terbatas ▼▼▼▼▼▼▼▼▼!"
  },
  AvgDialog_24091_Content_41 = {
    Text = "Suara kasar yang tidak beraturan keluar dari mulutnya. Miryam mencengkeram lehernya dengan kedua tangan, tubuhnya berubah bentuk dan memanjang."
  },
  AvgDialog_24091_Content_42 = {
    Text = "Hati-hati! Dia akan kehilangan kendali!"
  },
  AvgDialog_24091_Content_5 = {
    Text = "Tulu dan Penjaga… belum ada Tautan, benar?"
  },
  AvgDialog_24091_Content_6 = {
    Text = "Memang tidak ada. Apa maksudmu aku dan Tulu..."
  },
  AvgDialog_24091_Content_7 = {
    Text = "Tautan tidak hanya untuk menekan kesadaran alamiah kegilaan pemanggilan, tetapi juga memungkinkan penyelidik untuk mengarahkan aliran kegilaan, sehingga mengarahkan performa pemanggilan tubuh dalam pertempuran."
  },
  AvgDialog_24091_Content_8 = {
    Text = "Secara sederhana, tautan dapat memperkuat kemampuan pertempuran Pembangun."
  },
  AvgDialog_24092_Content_1 = {
    Text = "Membuka mata"
  },
  AvgDialog_24092_Content_10 = {
    Text = "Pemimpin rapat?"
  },
  AvgDialog_24092_Content_100 = {
    Text = "Belum berjalan dua langkah, getaran hebat yang hampir merobek lambung kapal terasa dari telapak kaki."
  },
  AvgDialog_24092_Content_101 = {
    Text = "Dalam ledakan besar, kobaran api menyambar ke langit dan udara yang sangat panas melemparkanmu dengan keras ke tanah."
  },
  AvgDialog_24092_Content_102 = {
    Text = "——Sebelum kesadaran terputus lagi, yang terakhir tampak di mata adalah burung laut yang melintasi langit malam purnama."
  },
  AvgDialog_24092_Content_11 = {
    Text = "Bagaimana tidurmu?"
  },
  AvgDialog_24092_Content_12 = {Text = "Boneka?!"},
  AvgDialog_24092_Content_13 = {
    Text = "Jangan takut, sekarang bukan saatnya menyalahkanmu karena menginjak rumput di siang hari kerja."
  },
  AvgDialog_24092_Content_14 = {
    Text = "<Gray: Itu berarti cepat atau lambat akan dituntut…>"
  },
  AvgDialog_24092_Content_15 = {
    Text = "Ramona menghindari tatapanmu, seakan-akan tertulis \"tak bisa membantu\" di bagian belakang kepalanya."
  },
  AvgDialog_24092_Content_16 = {
    Text = "Di dalam buku harian Francis, ada beberapa informasi tentang \"Gereja penerang kuil\"—— Ngomong-ngomong, kamu belum sempat mempelajari tiga mata pelajaran wajib itu, kan."
  },
  AvgDialog_24092_Content_17 = {
    Text = "Gereja Penerang Kuil, yang mempercayai \"Kehancuran adalah berkat dari Tuhan, satu-satunya penyelamatan bagi manusia\", menipu pasien yang menderita penyakit untuk bergabung dan terinfeksi oleh pelarutan."
  },
  AvgDialog_24092_Content_18 = {
    Text = [[
Terima kasih atas pengulangannya, Profesor Dexter. 
Namun, saya pikir Erica tidak akan senang jika Anda ikut campur dalam pekerjaannya.]]
  },
  AvgDialog_24092_Content_19 = {
    Text = "Maafkan aku, maafkan aku. Sisa waktunya kuserahkan kepada kalian."
  },
  AvgDialog_24092_Content_2 = {
    Text = "Kenapa kamu tidur di sini?"
  },
  AvgDialog_24092_Content_20 = {
    Text = "Francis meninggalkan banyak petunjuk yang mengarah ke Gereja Penerang Kuil, di antaranya \"orang mati hidup kembali\"ini sangat menarik perhatian."
  },
  AvgDialog_24092_Content_21 = {
    Text = "Dengan munculnya Lily, kita memiliki alasan untuk mencurigai bahwa Gereja Penerang Kuil telah menguasai metode pemanggilan Bangun."
  },
  AvgDialog_24092_Content_22 = {
    Text = "Bukankah keberadaan Pembangun seharusnya menjadi rahasia di dunia ini?"
  },
  AvgDialog_24092_Content_23 = {
    Text = [[
Sepertinya kamu juga tidak memperhatikan dengan baik pelajaran tentang sejarah Bangun. 
Aku mulai penasaran bagaimana kamu bisa lulus tes awal.]]
  },
  AvgDialog_24092_Content_24 = {
    Text = "Tentu saja, tidak hanya Mythag yang menguasai teknologi Bangun Perak atau yang serupa."
  },
  AvgDialog_24092_Content_25 = {
    Text = "Kemunculan Pembangun dapat ditelusuri hingga sebelum zaman Hongji, bahkan di makam Dinasti Kesembilan Belas Gulumwah, terdapat lukisan dinding yang diduga menggambarkan pemanggilan Pembangun."
  },
  AvgDialog_24092_Content_26 = {
    Text = "Di antara semua ini, \"Golem\" yang paling mirip dengan teknologi Pembangun Mythag diwariskan dari klan Penyihir di wilayah Levant."
  },
  AvgDialog_24092_Content_27 = {
    Text = "Melenceng jauh."
  },
  AvgDialog_24092_Content_28 = {
    Text = "Berdasarkan deskripsi dalam jurnal tentang keyakinan dan spesifikasi ritual, \"Gereja Penerang Kuil\" yang dihubungi oleh Francis berbeda dengan informasi yang kita miliki."
  },
  AvgDialog_24092_Content_29 = {
    Text = [[
Lalu, perangkat transmisi gambar jarak jauh yang saya letakkan di Herbert mengembalikan runa ini. 
 Kami menduga bahwa Herbert adalah perantara yang menjembatani Francis dan Gereja Penerang Kuil.]]
  },
  AvgDialog_24092_Content_3 = {
    Text = "Bangun, tidur di sini bisa membuatmu masuk angin."
  },
  AvgDialog_24092_Content_30 = {
    Text = "Tugas lapangan kalian berikutnya adalah memverifikasi isi catatan harian —— sekalian melakukan penyelidikan terhadap hubungan antara simbol rune ini dengan Gereja Penerang Kuil."
  },
  AvgDialog_24092_Content_31 = {
    Text = "Francis mencatat perjalanannya sebelum berangkat ke kutub di dalam buku hariannya. \n Kali ini, kita akan pergi ke tempat dia naik kapal — Kota Brilport, mungkin ada petunjuk yang tertinggal di sana."
  },
  AvgDialog_24092_Content_32 = {
    Text = "Jika sudah siap, ayo berangkat. Aku akan tetap menjadi pasanganmu seperti biasa."
  },
  AvgDialog_24092_Content_33 = {
    Text = "Tas keberangkatan selalu siap."
  },
  AvgDialog_24092_Content_34 = {
    Text = "Tidak perlu tidur sebentar lagi?"
  },
  AvgDialog_24092_Content_35 = {
    Text = [[
Tidak perlu! 
Saya sudah sepenuhnya memahami persyaratan tugas, dan saya juga sudah mengingat semua detail tugas yang saya baca kemarin malam!]]
  },
  AvgDialog_24092_Content_36 = {
    Text = [[
Kalau begitu, sekarang kita berangkat. 
Jika kita berangkat hari ini, mungkin kita masih bisa kembali tepat waktu untuk pertunjukan perdana drama baru di Opera House Londinium.]]
  },
  AvgDialog_24092_Content_37 = {
    Text = "Saya akan mencari sopir. Ketemu di gerbang sekolah."
  },
  AvgDialog_24092_Content_38 = {
    Text = "Punggung Ramona segera menghilang dari pandangan, dan kamu pun bersiap kembali ke asrama untuk mengambil barang bawaan."
  },
  AvgDialog_24092_Content_39 = {
    Text = "Sang Penjaga Rahasia."
  },
  AvgDialog_24092_Content_4 = {
    Text = "Hmm… Ramona?"
  },
  AvgDialog_24092_Content_40 = {
    Text = "Misi kali ini mungkin akan berhadapan langsung dengan Gereja Penerang Kuil."
  },
  AvgDialog_24092_Content_41 = {
    Text = "Mengungkap rahasia tersembunyi mereka adalah tugas sekunder. Prioritasmu yang utama adalah memastikan bahwa kamu tetap hidup. Aku tidak tahu harus mencari Penjaga lain dari reruntuhan mana lagi."
  },
  AvgDialog_24092_Content_42 = {
    Text = "Jangan terlalu keras pada anak muda."
  },
  AvgDialog_24092_Content_43 = {
    Text = "Namun, Boneka benar. Pengikut yang kalian temui sebelumnya hanyalah anggota luar, inti sebenarnya dari Gereja Penerang Kuil belum muncul ke permukaan."
  },
  AvgDialog_24092_Content_44 = {
    Text = "Tampaknya Profesor sangat familiar dengan Gereja Penerang Kuil?"
  },
  AvgDialog_24092_Content_45 = {
    Text = "Ha, haha... hanya sebuah hubungan karma saja."
  },
  AvgDialog_24092_Content_46 = {
    Text = "Jika perlu, Mythag akan mengirim penyelidik yang lebih berpengalaman dalam pertempuran, atau bahkan meminta bantuan kepada Komite Perjanjian Mystia untuk menyelesaikan masalah ini."
  },
  AvgDialog_24092_Content_47 = {
    Text = "Harus kembali dengan selamat."
  },
  AvgDialog_24092_Content_48 = {
    Text = "Aku mengerti, kami akan kembali dengan selamat."
  },
  AvgDialog_24092_Content_5 = {
    Text = "Berapa lama saya sudah tidur?"
  },
  AvgDialog_24092_Content_50 = {
    Text = "Apa yang masih kamu lihat? Mereka sudah berangkat."
  },
  AvgDialog_24092_Content_51 = {
    Text = "Jangan khawatir, mereka semua adalah anak-anak yang tahu batas."
  },
  AvgDialog_24092_Content_52 = {
    Text = "Saya tidak khawatir. Bahkan jika harus melatih Penjaga baru, dana akan tetap diambil dari rekening bank keluarga Dexter."
  },
  AvgDialog_24092_Content_53 = {
    Text = "Lebih perhatikan dirimu sendiri. Aku baru saja mendengar bahwa putri seseorang akan pergi berkencan ke opera."
  },
  AvgDialog_24092_Content_54 = {
    Text = "Ha, hahaha... anak muda zaman sekarang..."
  },
  AvgDialog_24092_Content_55 = {Text = "Malam itu"},
  AvgDialog_24092_Content_56 = {
    Text = "Kapal reguler ke kutub? Kalian pasti gila! Tidak ada kapal reguler di sini, juga tidak ada gereja atau organisasi keagamaan!"
  },
  AvgDialog_24092_Content_57 = {
    Text = "Jangan tanya lagi, kami hanya nelayan biasa, kami tidak tahu apa-apa!"
  },
  AvgDialog_24092_Content_58 = {
    Text = "Bu, tolong tunggu sebentar——"
  },
  AvgDialog_24092_Content_59 = {
    Text = "Kalian ini memanfaatkan status tuan kota untuk menindas penduduk desa!"
  },
  AvgDialog_24092_Content_6 = {
    Text = "Siapa yang tahu? Kamu bahkan absen di pertemuan sebelum keberangkatan sore ini."
  },
  AvgDialog_24092_Content_60 = {
    Text = "Kami sama sekali tidak bermaksud demikian——Eh!"
  },
  AvgDialog_24092_Content_61 = {
    Text = "Wanita itu membanting pintu. Jika Ramona tidak menarikmu tepat waktu, mungkin kamu akan kembali ke sekolah dengan hidung yang bengkok."
  },
  AvgDialog_24092_Content_62 = {
    Text = "Brillport... Kota kecil ini sangat aneh."
  },
  AvgDialog_24092_Content_63 = {
    Text = "Ini adalah pintu ketiga yang kami ketuk, namun tidak ada seorang pun yang mau berbagi informasi tentang kota kecil ini dengan kami."
  },
  AvgDialog_24092_Content_64 = {
    Text = "Kami bahkan hanya bertanya arah. Sepertinya mereka sedang berusaha menutupi sesuatu secara kolektif, ini sangat tidak biasa."
  },
  AvgDialog_24092_Content_65 = {
    Text = "Pergi ke dermaga dan lihatlah, mungkin ada petunjuk di sana."
  },
  AvgDialog_24092_Content_67 = {Text = "Ada apa?"},
  AvgDialog_24092_Content_68 = {
    Text = "Mungkin itu hanya fatamorgana, sepertinya ada suara orang berbicara di dalam angin."
  },
  AvgDialog_24092_Content_69 = {
    Text = [[
Hei, kebetulan, ada dua orang pendatang yang ceroboh. 
Menghalangi mereka? Supaya tidak perlu mencari orang lain.]]
  },
  AvgDialog_24092_Content_7 = {Text = "Rapat?"},
  AvgDialog_24092_Content_70 = {
    Text = "Menggiring mereka ke arah kapal."
  },
  AvgDialog_24092_Content_71 = {
    Text = "Hmph, orang yang berniat jahat."
  },
  AvgDialog_24092_Content_72 = {
    Text = "Pergilah, Caecus, inilah kesempatanmu untuk menunjukkan kemampuan."
  },
  AvgDialog_24092_Content_73 = {
    Text = "Baik, Tuan Goliath."
  },
  AvgDialog_24092_Content_74 = {
    Text = "Hitung Mundur: Tiga Jam"
  },
  AvgDialog_24092_Content_75 = {
    Text = "—— Dang!"
  },
  AvgDialog_24092_Content_76 = {
    Text = "Rasa sakit yang luar biasa menyerang dahi, benturan membuatmu merasa pusing dan kehilangan keseimbangan. Sementara itu, Murphy berhasil melepaskan diri dari genggamanmu, lalu ia menutupi dahinya dan berlari lebih jauh ke dalam kabin kapal."
  },
  AvgDialog_24092_Content_77 = {
    Text = "Aku sudah tahu kalian bukan orang baik!!"
  },
  AvgDialog_24092_Content_78 = {
    Text = "Jangan, jangan... Dengarkan penjelasanku..."
  },
  AvgDialog_24092_Content_79 = {
    Text = "Hitung mundur @2 menit"
  },
  AvgDialog_24092_Content_8 = {
    Text = "Ini tentang Francis——"
  },
  AvgDialog_24092_Content_80 = {
    Text = "Kami sekarang menaiki kapal."
  },
  AvgDialog_24092_Content_81 = {
    Text = "Apakah sudah cukup melihat?"
  },
  AvgDialog_24092_Content_82 = {
    Text = "Pada detik Domain menghilang, \"dewa palsu\"di dalam tubuhnya merasakan tarikan yang sangat kuat."
  },
  AvgDialog_24092_Content_83 = {
    Text = "Palsu… matilah kau!"
  },
  AvgDialog_24092_Content_84 = {
    Text = "Penjaga! Jangan lepaskan tangan saya!"
  },
  AvgDialog_24092_Content_86 = {
    Text = [[
Pelukan laut menjadi tajam, air laut bereaksi dengan kulit yang terbakar, menciptakan perjuangan yang menyengat. 
 Kekacauan buta seperti hantu di malam hari, merobek dan mematahkan tubuhmu.]]
  },
  AvgDialog_24092_Content_87 = {
    Text = "Lalu, dari kekacauan itu muncul seberkas kehangatan. Di tengah kegelapan tanpa batas, kesendirian, ketidakberdayaan, dan kehancuran dengan cepat surut, memancarkan cahaya hangat yang misterius di alam semesta yang sangat dingin."
  },
  AvgDialog_24092_Content_88 = {
    Text = "Seolah menyentuh belas kasih alam semesta, kesadaran berjalan di tepi Gnosis. Tubuh secara bertahap menyatu dengan oksigen dalam air laut, lalu kamu tiba-tiba membuka mata, dan air laut mengalir ke tubuh melalui sudut matamu."
  },
  AvgDialog_24092_Content_89 = {
    Text = "Terakhir, cahaya lembut menembus kegelapan di dasar laut. Kekuatan biru pucat mengulurkan tangan padamu — seperti seorang Dewi yang melindungi perjalanan kapal, memberikan bantuan padamu."
  },
  AvgDialog_24092_Content_9 = {
    Text = "Lupakan saja, biarkan pembawa acara rapat menjelaskan langsung kepadamu."
  },
  AvgDialog_24092_Content_90 = {
    Text = "Aku ingat sekarang… jeritan sekarat Miryam memicu ledakan, aku tak bisa menangkap tangan Ramona, lalu jatuh ke laut… Tidak, tapi… ini adalah dek kapal Sonaniel."
  },
  AvgDialog_24092_Content_91 = {
    Text = "Kekuatan terakhir yang membantu saya... apakah itu Celeste? Dia menyelamatkan saya dari Aequor..."
  },
  AvgDialog_24092_Content_92 = {
    Text = "Kalau begitu, yang lain pasti juga masih baik-baik saja!"
  },
  AvgDialog_24092_Content_93 = {
    Text = "Warna hangat yang penuh dengan mimpi dan kelembutan digantikan oleh cahaya bulan yang dingin dan pucat. Tirai yang menyelimuti kapal perlahan retak, menghilang, dan jatuh ke dalam Aequor."
  },
  AvgDialog_24092_Content_94 = {
    Text = "Tirai... menghilang?!"
  },
  AvgDialog_24092_Content_95 = {
    Text = "Asap tebal mengepul dari buritan, tepat ke arah Ruang Kekuatan."
  },
  AvgDialog_24092_Content_96 = {Text = "Astaga!"},
  AvgDialog_24092_Content_97 = {
    Text = "Kamu memaksa diri untuk mengabaikan rasa sakit yang mendalam dari dalam jiwa, bersandar pada pagar kapal, dan berjalan menuju arah asap tebal yang mengepul."
  },
  AvgDialog_24092_Content_98 = {
    Text = "Tenggorokan dipenuhi dengan bau darah dan asap mesiu, setiap tarikan napas saat berjalan terasa seperti siksaan."
  },
  AvgDialog_24092_Content_99 = {
    Text = "Ramona, Murphy, Celeste, Tulu… harus segera bergabung dengan mereka."
  },
  AvgDialog_24093_Content_1 = {Text = "Keputusan"},
  AvgDialog_24093_Content_10 = {
    Text = "Siapa—Celeste!"
  },
  AvgDialog_24093_Content_11 = {
    Text = "Elton menarik napas dalam-dalam beberapa kali dan menghadapi kedatangan tiga orang yang tampak tergesa-gesa."
  },
  AvgDialog_24093_Content_12 = {
    Text = "Tentakel Tulu menopang Ramona, yang tampak serius. Namun, dari otot-ototnya yang bergetar, terlihat beberapa tanda kesulitan."
  },
  AvgDialog_24093_Content_13 = {
    Text = "Seragam sekolah... kau adalah rekan %player%."
  },
  AvgDialog_24093_Content_14 = {
    Text = "Ramona memandang sekeliling kepada semua orang. Selain Tulu, yang sudah dikenalnya di sekolah, dan Celeste, yang melarikan diri bersamanya, ada juga dua wajah asing."
  },
  AvgDialog_24093_Content_15 = {
    Text = "Mereka... adalah Murphy dan kapten kapal Sonaniel, orang-orang yang Penjaga bersedia melindungi meskipun harus mengambil risiko."
  },
  AvgDialog_24093_Content_16 = {
    Text = [[
Ramona Dexter, panggil saja aku Ramona. 
 Basa-basi tidak perlu. Sekarang aku perlu tahu semua yang terjadi di kapal ini, singkat dan cepat.]]
  },
  AvgDialog_24093_Content_17 = {
    Text = "Siapa kalian, mengapa Pelaut mengejar kalian, serta \"ritual\" yang menjadi obsesi fanatik Miryam…"
  },
  AvgDialog_24093_Content_18 = {
    Text = "Saya... saya adalah..."
  },
  AvgDialog_24093_Content_19 = {
    Text = "Elton menghentikan Murphy yang ingin segera berbicara. Dia tahu bahwa anak ini tidak akan mampu menjelaskan situasi secara menyeluruh di bawah tekanan besar."
  },
  AvgDialog_24093_Content_2 = {
    Text = "Kapal Kargo Luar Laut · Sonnier \n Gudang Kargo Ketiga"
  },
  AvgDialog_24093_Content_20 = {
    Text = "Saya adalah Elton, dan itu adalah rekan saya Celeste. Kami berdua adalah satu-satunya awak di kapal kargo Sonnelier."
  },
  AvgDialog_24093_Content_21 = {
    Text = "Pada masa mudaku, Miryam membantu saya membangunkan Celeste. Sebagai balasannya, kami mengendarai Sonnelier, bolak-balik antara daratan dan kutub, untuk mengangkut inventaris bagi perkumpulan Pelaut."
  },
  AvgDialog_24093_Content_22 = {
    Text = "Akhirnya, kami dikejar oleh Miryam karena telah membantu Murphy melarikan diri dari sekte."
  },
  AvgDialog_24093_Content_23 = {
    Text = "Dalam tubuh Murphy, ada parasit niat Miryam untuk memanggil dewa palsu, saya tidak tahu apakah itu benar-benar dewa, tetapi upacara telah dilaksanakan, Murphy tidak bisa menghindar dari malapetaka."
  },
  AvgDialog_24093_Content_24 = {
    Text = "Murphy juga menceritakan beberapa hal: tentang tubuhnya, tentang dirinya dan Miryam, serta tentang masa lalunya di ordo tersebut…"
  },
  AvgDialog_24093_Content_25 = {
    Text = "Ternyata begitu banyak hal terjadi……"
  },
  AvgDialog_24093_Content_26 = {
    Text = "Aku akan memastikan Celeste berlayar dengan kecepatan penuh menuju daratan, tetapi apakah %player% bisa diselamatkan, aku tidak bisa memberikan jaminan padamu."
  },
  AvgDialog_24093_Content_27 = {
    Text = "Elton belum selesai berbicara ketika semua orang terhuyung dua langkah karena inersia — seperti yang dia katakan, Celeste telah meningkatkan kecepatan kapal."
  },
  AvgDialog_24093_Content_28 = {
    Text = "Hek, hek hek…"
  },
  AvgDialog_24093_Content_29 = {
    Text = "Kapten! Mengendarai kapal secepat ini memberikan beban yang terlalu besar untukmu."
  },
  AvgDialog_24093_Content_3 = {
    Text = "Sol sepatu yang keras menginjak dek, menghasilkan suara langkah yang teratur dan berat."
  },
  AvgDialog_24093_Content_30 = {
    Text = "...semua hal kecil."
  },
  AvgDialog_24093_Content_31 = {
    Text = "Berkolusi dengan gereja, mengabaikan penderitaanmu dengan tega, dosaku sudah cukup berat."
  },
  AvgDialog_24093_Content_32 = {
    Text = "Penderitaanku...?"
  },
  AvgDialog_24093_Content_33 = {
    Text = "Orang yang menyerahkanmu ke tangan Miryam adalah aku."
  },
  AvgDialog_24093_Content_35 = {
    Text = "Kamu adalah \"kargo\" paling berharga yang pernah aku angkut setelah bergabung dengan ordo. Dengan memanfaatkan pelayaran yang sempurna itu, aku berhasil mendapatkan perhatian Miryam."
  },
  AvgDialog_24093_Content_36 = {
    Text = "Jadi, saat berada di markas ordo, kau langsung menerima permintaan bantuanku tanpa ragu-ragu..."
  },
  AvgDialog_24093_Content_37 = {
    Text = "Ketika cukup dekat dengan pantai, aku akan membiarkan Celeste turun dari kapal bersamamu. Kalian harus menjauh dari laut sejauh mungkin."
  },
  AvgDialog_24093_Content_38 = {
    Text = "Seolah-olah sebagai tanggapan kepada kapten, Celeste menggoyangkan kompas di tangannya."
  },
  AvgDialog_24093_Content_39 = {
    Text = "Maksudmu menyuruh Celeste dan aku pergi bersama?"
  },
  AvgDialog_24093_Content_4 = {
    Text = "Celeste, %player%…"
  },
  AvgDialog_24093_Content_40 = {
    Text = "Ramona lebih dulu memahami maksud sang kapten."
  },
  AvgDialog_24093_Content_41 = {
    Text = "Saya dan Penjaga bisa menghubungi alat transportasi, asalkan Celeste mengubah mobil kita juga menjadi Domain…"
  },
  AvgDialog_24093_Content_42 = {
    Text = "Benar, dengan cara ini kamu bisa mendapatkan waktu yang cukup."
  },
  AvgDialog_24093_Content_43 = {
    Text = "Jangan bercanda! Apakah kau pikir kau bisa menahan monster-monster itu? Kau bahkan bukan seorang Pelaut, kau hanyalah manusia biasa!"
  },
  AvgDialog_24093_Content_44 = {
    Text = "Tidak, ini serahkan kepada kami."
  },
  AvgDialog_24093_Content_45 = {
    Text = [[
Menghentikan ritual sesat, melindungi dunia dari yang tidak diketahui... 
 Ini adalah tanggung jawab setiap orang di Universitas Mythag.]]
  },
  AvgDialog_24093_Content_46 = {
    Text = "Apakah kamu juga gila? Kamu bahkan tidak tahu apakah kami berbohong padamu atau tidak!"
  },
  AvgDialog_24093_Content_47 = {
    Text = "Penjaga telah memilih untuk mempercayimu, jadi saya juga akan mempercayaimu."
  },
  AvgDialog_24093_Content_48 = {
    Text = "Kapten tersandung dan dengan cepat mengatur keseimbangan tubuhnya, lalu ia mengulurkan tangan kepada Murphy —— \n Ia dengan kuat mengacak-acak rambut Murphy."
  },
  AvgDialog_24093_Content_49 = {
    Text = "<Small: Apa! Jangan sentuh terlalu keras! Rambutku jadi kusut!>"
  },
  AvgDialog_24093_Content_5 = {
    Text = "Dan Tulu... kenapa belum kembali."
  },
  AvgDialog_24093_Content_50 = {
    Text = "Aku harap kamu bisa keluar dari semua ini. Anggap saja ini sebagai permintaan terakhirku."
  },
  AvgDialog_24093_Content_51 = {
    Text = "Hasil terburuk apa lagi yang bisa terjadi selain mati di lautan? Aku seharusnya sudah tenggelam bersama Sonaniels dari dulu."
  },
  AvgDialog_24093_Content_52 = {
    Text = "Murphy dengan keras kepala memegang erat-erat ujung mantel kapten, menolak untuk melepaskan."
  },
  AvgDialog_24093_Content_53 = {
    Text = "Ramona menggenggam erat-erat di telapak tangannya, akhirnya seakan-akan membulatkan tekad, ia memberikan benda yang dipegangnya dengan kuat kepada Murphy — ternyata itu adalah komunikator dari Universitas Mythag."
  },
  AvgDialog_24093_Content_54 = {
    Text = "Warisan, warisan?"
  },
  AvgDialog_24093_Content_55 = {
    Text = "Ini adalah sebuah komunikator, meskipun untuk sementara tidak berfungsi di dalam Domain, pihak sekolah pasti terus mencoba menghubungi kita."
  },
  AvgDialog_24093_Content_56 = {
    Text = [[
Jika kamu benar-benar bisa melihat pelarutan dengan mata telanjang, maka kamu pasti memiliki cukup kekuatan roh untuk menggunakannya. 
 Fokuskan perhatianmu saat bros menyala, dan kamu akan dapat berkomunikasi dengan orang di seberang.]]
  },
  AvgDialog_24093_Content_57 = {
    Text = "Meskipun saya dan Penjaga tidak kembali untuk menemui kalian, rekan-rekan kami pasti akan membantu kalian."
  },
  AvgDialog_24093_Content_58 = {
    Text = "Murphy menerima bros itu, dia memandang ukiran logam yang indah di atasnya, matanya tiba-tiba menjadi merah."
  },
  AvgDialog_24093_Content_59 = {
    Text = "Apa sih... berlagak seolah-olah siap mati dengan gagah berani."
  },
  AvgDialog_24093_Content_6 = {
    Text = "Murphy menggigit bibirnya, cemas berjalan mondar-mandir. Sesekali ia menendang kotak kargo, lalu mencengkeram tali pengikat yang menahan kotak kargo itu."
  },
  AvgDialog_24093_Content_60 = {
    Text = "Tulu tidak berniat terlibat dalam pertengkaran ini. Dia merasakan aliran kekuatan di luar pintu dengan tenang, lalu bersiap untuk menuju ruang kekuatan."
  },
  AvgDialog_24093_Content_61 = {
    Text = "—— Tunggu! Kamu mau pergi ke mana!"
  },
  AvgDialog_24093_Content_62 = {
    Text = "Gadis itu menabrak pintu kabin hingga terbuka, lalu meraih salah satu tentakel."
  },
  AvgDialog_24093_Content_63 = {
    Text = "Apakah kamu akan menyelamatkan {Male=dia,Female=dia}?"
  },
  AvgDialog_24093_Content_64 = {
    Text = "Apa yang kulakukan, tidak ada tempat bagi orang luar untuk mencampuri."
  },
  AvgDialog_24093_Content_65 = {
    Text = "Saya juga akan pergi."
  },
  AvgDialog_24093_Content_66 = {
    Text = "Murphy! Jangan bersikap keras kepala."
  },
  AvgDialog_24093_Content_67 = {
    Text = [[
Kamu tetap di sini, aku dan Tulu akan membantu Penjaga untuk keluar dari kesulitan. 
Jika kamu jatuh ke tangan Miryam, semua usaha kita akan sia-sia.]]
  },
  AvgDialog_24093_Content_68 = {Text = "Aku tahu."},
  AvgDialog_24093_Content_69 = {
    Text = [[
Tapi... aku tidak bisa... 
 Aku tidak ingin mati, tapi... jika, jika kalian tidak kembali?]]
  },
  AvgDialog_24093_Content_7 = {
    Text = "Apakah mereka tidak akan mengalami masalah apa pun……"
  },
  AvgDialog_24093_Content_70 = {
    Text = "Aku... tidak ingin... hal semacam itu..."
  },
  AvgDialog_24093_Content_71 = {
    Text = "...Aku tidak bisa selamanya tinggal di Domain. Jika aku ingin benar-benar terbebas, aku...aku membutuhkan kalian untuk merekomendasikanku."
  },
  AvgDialog_24093_Content_72 = {
    Text = [[
Saya tidak bisa langsung mendatangi sekolah dan memberi tahu kepala sekolah bahwa siswa mereka telah mengorbankan diri untuk membantu saya. 
 Saya membutuhkan kalian untuk merekomendasikan saya, kalian berdua tidak boleh mati.]]
  },
  AvgDialog_24093_Content_73 = {
    Text = "Yu tidak akan teralihkan untuk melindungimu."
  },
  AvgDialog_24093_Content_74 = {
    Text = "Tidak perlu kau melindungi aku. Aku sangat tahu kelemahan Pelaut, dan aku bisa menjaga diriku sendiri."
  },
  AvgDialog_24093_Content_75 = {
    Text = "Baik, jika kamu memaksa."
  },
  AvgDialog_24093_Content_76 = {
    Text = "Apa maksud dari tatapanmu ini?"
  },
  AvgDialog_24093_Content_77 = {
    Text = [[
Yu awalnya mengira bahwa kau tidak layak mendapatkan pengorbanan sebesar itu. 
 Sekarang tampaknya Yu terlalu cepat menyimpulkan.]]
  },
  AvgDialog_24093_Content_78 = {
    Text = "Apa teka-teki yang kamu bicarakan? Pergi, pergi!"
  },
  AvgDialog_24093_Content_79 = {
    Text = "Murphy mendorong Tulu dengan satu tangan dan menarik Ramona dengan tangan lainnya, segera menghilang di lorong yang dalam dan gelap di kapal."
  },
  AvgDialog_24093_Content_8 = {
    Text = "Dia tidak bisa tenang untuk berdoa, tidak bisa duduk dengan tenang."
  },
  AvgDialog_24093_Content_80 = {
    Text = "Anak ini... sudahlah, jika ini adalah pilihannya."
  },
  AvgDialog_24093_Content_81 = {
    Text = "Celeste, pertahankan kecepatan penuh."
  },
  AvgDialog_24093_Content_9 = {Text = "Bam——!"},
  AvgDialog_24094_Content_1 = {
    Text = "Seiring dengan gejolak dalam pikiran Miryam, kelompok Pelaut juga menjadi tidak stabil. Kekacauan dan ketidakteraturan mulai menyebar secara diam-diam."
  },
  AvgDialog_24094_Content_2 = {
    Text = "Para Pelaut mengenali Murphy yang \"mengandung\" Dewa, hampir secara naluriah mereka mundur saat dia mendekat. Kalian pun berlari kecil melewati kepungan monster."
  },
  AvgDialog_24095_Content_1 = {
    Text = "Tentakel menyapu para Pelaut yang mendekat. Tulu berjalan di belakang rombongan, membersihkan sisa-sisa untuk kalian."
  },
  AvgDialog_24095_Content_2 = {
    Text = [[
Pelaut, meskipun berintelegensi rendah, tetapi hingga saat ini, tiba-tiba menjadi bimbang.
Di dalam kelompok mulai terdengar bisikan-bisikan. Bahasa itu kuno dan sulit dipahami, namun Tulu malah mengernyitkan alis karena hal itu.]]
  },
  AvgDialog_24095_Content_3 = {
    Text = "Kecurigaan para pelaut hanya akan membangkitkan kemarahan Miryam."
  },
  AvgDialog_24095_Content_4 = {
    Text = "Kecurigaan? Apakah kamu bisa mengerti apa yang mereka katakan?"
  },
  AvgDialog_24095_Content_5 = {
    Text = "Tidak ada waktu untuk menjelaskan kepada Tulu. Miryam, dengan tindakannya, sepenuhnya menerjemahkan bahasa kuno itu."
  },
  AvgDialog_24095_Content_6 = {
    Text = "Belati menyayat leher beberapa Pelaut, dia mandi dalam percikan darah abu-abu kebiruan, melewati gerombolan Pelaut."
  },
  AvgDialog_24095_Content_7 = {
    Text = [[
Raja Dewa lahir kembali? Tidak... 
 Dia hanya akan turun ke dunia melalui ritual saat bintang-bintang berada dalam posisi selaras!]]
  },
  AvgDialog_24095_Content_8 = {
    Text = "Hanya ritualku yang bisa membuat Raja Dewa dilahirkan kembali, dan membuat Ranah Dewa kembali lagi! Hanya aku!"
  },
  AvgDialog_24095_Content_9 = {
    Text = "Pelaut... Biarkan para penjahat yang telah menistakan nama Tuhanku menyaksikan keagungan garis keturunan Ranah Dewa!"
  },
  AvgDialog_24096_Content_1 = {
    Text = "Cahaya yang Hilang"
  },
  AvgDialog_24096_Content_10 = {
    Text = "Anggota tubuhnya terpuntir, ekspresi di bagian wajah bawah yang tersisa membeku pada saat kematian. Darah yang mengalir membeku menjadi rune yang tak terpahami, membuat udara dipenuhi dengan kegilaan kematian."
  },
  AvgDialog_24096_Content_11 = {
    Text = [[
"Dewa"mu, sepertinya tidak akan menyukai pengorbanan yang begitu mengerikan, bukan?
Utusan mereka menghilang di tempat kita, bagaimana kamu akan menjelaskan ini kepada orang-orang dari Gereja Penerang Kuil?]]
  },
  AvgDialog_24096_Content_12 = {
    Text = "Goliath belum selesai berbicara, ketika bekas luka di lehernya tiba-tiba berdenyut kuat, mengencangkan ototnya."
  },
  AvgDialog_24096_Content_13 = {
    Text = "Menyatukan tengkorakmu dengan darah Lemuria bukan dimaksudkan agar kau berbicara dengan angkuh kepada Dewaku, Goliath."
  },
  AvgDialog_24096_Content_14 = {
    Text = "Tuhanku yang agung dan mahakuasa, Dia dapat memperoleh kekuatan dari doa-doaku, dan juga dapat mengenali kesalehanku dari pengorbananku."
  },
  AvgDialog_24096_Content_15 = {
    Text = "Adapun kedua utusan lentera ini... tidak sopan, bodoh, dan merupakan sampah yang tidak penting. Jika pihak lentera memiliki keluhan mengenai hal ini, maka aku juga tidak perlu melanjutkan perjalanan bersama mereka."
  },
  AvgDialog_24096_Content_16 = {
    Text = "Miryam mengusap noda darah di antara jarinya, akhirnya berbalik untuk menatapmu. Tubuhnya dipenuhi aroma busuk yang tak kunjung hilang, setiap langkah mendekat adalah siksaan bagi kesadaranmu."
  },
  AvgDialog_24096_Content_17 = {
    Text = "Apa yang telah kau lakukan pada mereka…?"
  },
  AvgDialog_24096_Content_18 = {
    Text = "Kamu berbeda dari mereka."
  },
  AvgDialog_24096_Content_19 = {
    Text = "Miryam tidak menjawab pertanyaanmu. Dia menatapmu dengan mata seperti kolam dalam yang sulit diguncang riaknya, menyimpan sisa-sisa sejarah panjang yang telah dilaluinya."
  },
  AvgDialog_24096_Content_2 = {
    Text = "Kapal Kargo Luar Negeri · Sonnier \n Ruang Kekuatan"
  },
  AvgDialog_24096_Content_20 = {
    Text = "Kamu memiliki jiwa yang paling unik dan berbeda yang pernah kulihat sejak aku menjadi Pembangun… lebih cemerlang, namun juga lebih redup dibandingkan dengan temanmu itu."
  },
  AvgDialog_24096_Content_21 = {
    Text = "Penjaga Universitas Mythag... Terhadap orang berbakat, aku selalu merasa iba. Aku sungguh-sungguh berharap, kau dapat mandi dalam cahaya ilahi Tuhanku."
  },
  AvgDialog_24096_Content_22 = {
    Text = "Orang yang cerdas tidak seharusnya tenggelam dalam kehidupan duniawi. Meskipun tanah para dewa telah terjalin melalui garis keturunan, ia tetap terbuka untuk menerima darah baru dari luar."
  },
  AvgDialog_24096_Content_23 = {
    Text = "Kalian berharap menyelamatkan dunia dari kekotoran hitam, dan <Blue:Kedatangan Kembali Ranah Dewa> tidak bertentangan satu sama lain."
  },
  AvgDialog_24096_Content_24 = {
    Text = "Bergabunglah dengan kami, ikut serta dalam kedatangan kembali dan kebangkitan Ranah Dewa, penuh kemuliaan… Dengan demikian, engkau dan aku dapat melangkah di tanah kebahagiaan sempurna."
  },
  AvgDialog_24096_Content_25 = {
    Text = "Jika yang kamu maksud dengan \"kedatangan kembali\" dan \"kebangkitan\" adalah menggunakan orang hidup sebagai korban dan orang tak bersalah sebagai wadah monster…"
  },
  AvgDialog_24096_Content_26 = {
    Text = [[
Maaf, aku tidak bisa melakukannya. 
 Ritualmu sangat biadab dan kejam. Aku tidak melihat sedikit pun jejak rasionalitas atau peradaban di dalamnya.]]
  },
  AvgDialog_24096_Content_27 = {
    Text = "Bisa menjadi wadah sebelum Dewa dilahirkan kembali, bisa menjadi batu penjuru untuk kedatangan kembali Ranah Dewa, seharusnya merasa bangga!"
  },
  AvgDialog_24096_Content_28 = {
    Text = "Kali ini aku keliru menilai, tidak perlu membuang waktu berbicara dengan orang bodoh... sandiwara ini harus segera berakhir."
  },
  AvgDialog_24096_Content_29 = {
    Text = "Kekuatan meledak di dalam bayangan, tubuh energi yang samar-samar menggumpal menjadi ular berbentuk besar dan kokoh."
  },
  AvgDialog_24096_Content_3 = {
    Text = "Miryam berdiri dengan tenang di tengah ruangan, matanya sedikit terpejam, bagaikan sebuah patung suci. Bahkan ketika Goliath dengan kasar melemparkanmu ke depannya, dia hanya sedikit mengangkat matanya dan melirikmu sekilas."
  },
  AvgDialog_24096_Content_30 = {
    Text = "Ular raksasa menabrak sembarangan di dalam ruang, pupil ular itu akhirnya terfokus pada dirimu — Jalinan ular raksasa melilit pinggangmu dan dengan mudah mengangkatmu tinggi-tinggi."
  },
  AvgDialog_24096_Content_31 = {
    Text = "Berhenti, Miryam."
  },
  AvgDialog_24096_Content_32 = {Text = "Siapa!"},
  AvgDialog_24096_Content_33 = {
    Text = "Suara yang sangat dikenal melintasi jurang sejarah, seperti angin lepas pantai yang ringan, namun membangkitkan gelombang besar di dalam hati."
  },
  AvgDialog_24096_Content_34 = {
    Text = "Miryam, aku berkata, \"Lepaskan siswa itu.\""
  },
  AvgDialog_24096_Content_35 = {
    Text = "Drama ini memang sudah seharusnya berakhir."
  },
  AvgDialog_24096_Content_36 = {
    Text = "Aku tidak ingat wajahmu, tetapi di tubuhmu... ada jejak keberadaan Tuhanku."
  },
  AvgDialog_24096_Content_37 = {
    Text = "Wajah Miryam menunjukkan sedikit belas kasihan. Matanya seperti bunga yang telah dirusak oleh hujan lebat yang tak masuk akal, dipenuhi dengan kesedihan dan penderitaan tanpa akhir."
  },
  AvgDialog_24096_Content_38 = {
    Text = "Sisik ular yang dingin dan licin meluncur di tubuhmu, seperti saat mencekik mangsanya. Tubuh ular raksasa itu perlahan semakin erat."
  },
  AvgDialog_24096_Content_39 = {
    Text = "Air mata telah mengukir jejak yang tak terhapuskan di wajahnya. Matanya menatap tajam pada Tulu, seolah-olah ingin menembus jiwanya dan melihat tembus sejarah mereka dari sepuluh ribu tahun yang lalu."
  },
  AvgDialog_24096_Content_4 = {
    Text = "Pandangan matanya dingin seperti ular berbisa, memancarkan kekejaman dan kebengisan, namun sepenuhnya mengabaikanmu — kamu bukan lawannya, juga bukan bagian dari rantai makanannya."
  },
  AvgDialog_24096_Content_40 = {
    Text = "<Blue:Tuan-ku>… aku yang terhormat <Blue:Raja>… \nBagaimana mungkin… ada jejak keberadaan Pembangun?"
  },
  AvgDialog_24096_Content_41 = {
    Text = "Siapa yang telah menodai relik suci-mu? Siapa yang… menodai janji kita?"
  },
  AvgDialog_24096_Content_42 = {
    Text = "Kamu diangkat terbalik oleh ular raksasa, semua darah dalam tubuh mengalir ke otak, dan pandanganmu mulai berkunang-kunang."
  },
  AvgDialog_24096_Content_43 = {
    Text = "Namun, dalam keadaan bingung, kamu masih melihat dua gadis... Mereka dikelilingi oleh Pelaut, mengapa semakin dekat?"
  },
  AvgDialog_24096_Content_44 = {
    Text = "Ramona! Sekarang!"
  },
  AvgDialog_24096_Content_45 = {
    Text = "Ramona menarik napas dalam-dalam, sedikit menekuk satu kakinya, dan melompat tinggi-tinggi berkat energi yang terkumpul di bawah kakinya ——"
  },
  AvgDialog_24096_Content_47 = {
    Text = "Ujung pedang tipis menembus tubuh energi berbentuk sisik ular, menusuk bagian vital ular raksasa."
  },
  AvgDialog_24096_Content_48 = {
    Text = "Eh eh! Orang akan jatuh!"
  },
  AvgDialog_24096_Content_49 = {
    Text = "Kamu juga jatuh dalam teriakan dahsyat Ular Raksasa."
  },
  AvgDialog_24096_Content_5 = {
    Text = "Bagaimana dengan yang lain?"
  },
  AvgDialog_24096_Content_50 = {
    Text = "—— lalu jatuh ke dalam pelukan hangat yang gemetar."
  },
  AvgDialog_24096_Content_51 = {
    Text = "... Apakah kamu baik-baik saja, %player%?"
  },
  AvgDialog_24096_Content_52 = {
    Text = "Ramona... saya..."
  },
  AvgDialog_24096_Content_53 = {
    Text = "Maaf, sekarang bukan saat yang tepat untuk bernostalgia."
  },
  AvgDialog_24096_Content_54 = {
    Text = "Ramona memelukmu dan berlari menjauh dari Miryam tanpa menoleh ke belakang."
  },
  AvgDialog_24096_Content_55 = {
    Text = "Kamu menoleh kembali ke Miryam, ular itu terbentuk kembali, dan pandangannya juga tertuju pada kamu dan Ramona."
  },
  AvgDialog_24096_Content_56 = {
    Text = "Mata itu seperti ular berbisa yang memandang mangsanya."
  },
  AvgDialog_24096_Content_57 = {
    Text = "Tulu! Jangan terlibat dengannya, prioritaskan melindungi Murphy untuk pergi."
  },
  AvgDialog_24096_Content_6 = {
    Text = "Bukankah aku sudah bilang? Tikus kecil dari Mythag pandai membuat lubang di mana-mana. Bisa menahan salah satu dari mereka saja sudah cukup sulit."
  },
  AvgDialog_24096_Content_7 = {
    Text = [[
Tapi yang lainnya sudah tidak penting lagi, bukan? 
Sepertinya, kamu sudah membangun altar untuk "Dewa".]]
  },
  AvgDialog_24096_Content_8 = {
    Text = "Miryam perlahan berbalik, bayangan ular menghilang seiring dengan gerakannya, membuatnya mandi dalam cahaya redup ungu, mirip seperti seorang penganut yang sedang dibaptis."
  },
  AvgDialog_24096_Content_9 = {
    Text = "Altar di belakangnya perlahan menampakkan wujud aslinya, cahaya redup dari Ruang Kekuatan menciptakan bayangan aneh di wajahnya. Di tengah altar, dua tubuh yang tak dapat dikenali bentuk aslinya terbaring diam."
  },
  AvgDialog_24097_Content_10 = {
    Text = "Ngomong-ngomong, apakah betis kamu masih terasa sakit? Sepertinya pendarahannya sudah berhenti."
  },
  AvgDialog_24097_Content_11 = {
    Text = "Hampir tidak merasakan sakit lagi..."
  },
  AvgDialog_24097_Content_12 = {
    Text = [[
Saat kalian berbicara tentang masa depan, ilusi Miryam menghilang seperti salju yang mencair. 
 Musuh mendapatkan kembali sebagian kesadarannya dari keadaan tidak terkendali, sambil kehilangan bentuknya yang aneh.]]
  },
  AvgDialog_24097_Content_13 = {
    Text = "Miryam terbaring dalam kelemahan di tengah debu hitam, pandangannya kosong dan penuh ilusi. Bahkan ketika Tulu datang ke hadapannya, dia tidak memberikan reaksi apa pun."
  },
  AvgDialog_24097_Content_14 = {
    Text = "Jangan bersikeras lagi, Miryam."
  },
  AvgDialog_24097_Content_15 = {
    Text = "Era kita, <Blue:Kerajaan Abadi> kita, kehancurannya sudah ditakdirkan."
  },
  AvgDialog_24097_Content_16 = {
    Text = "Tidak... tidak... Dia telah berjanji kepadaku..."
  },
  AvgDialog_24097_Content_17 = {
    Text = "<Yellow:Kamu> berjanji pada saya."
  },
  AvgDialog_24097_Content_18 = {
    Text = "Wanita yang kurus akhirnya menunjukkan reaksi. Dia perlahan mengangkat kepalanya dengan tatapan kosong, sambil bergumam tanpa henti."
  },
  AvgDialog_24097_Content_19 = {
    Text = "Dewa yang Mahakuasa akan menjalankan kuasa-Nya… dan menjatuhkan hukuman kepada kaum kafir yang membuat barang palsu ini, mereka yang tidak terampuni dosanya!"
  },
  AvgDialog_24097_Content_2 = {
    Text = "Bangunan-bangunan ini sedang menghilang, apakah semuanya… sudah berakhir?"
  },
  AvgDialog_24097_Content_20 = {
    Text = "Dia mencabut belati dari pinggangnya, api ungu-hitam seperti kabut kental menutupi mata pisaunya, memancarkan aura kematian yang mencekam."
  },
  AvgDialog_24097_Content_21 = {
    Text = "Palsu… matilah kau!"
  },
  AvgDialog_24097_Content_22 = {
    Text = "——Api yang dingin dan misterius di atas belati, menyulut debu batubara."
  },
  AvgDialog_24097_Content_23 = {
    Text = "<BigShake:Yaah!>"
  },
  AvgDialog_24097_Content_24 = {
    Text = "Di tengah reaksi berantai antara api dan debu, gemuruh ledakan yang menggelegar menelan semua orang, dan badan kapal tiba-tiba miring ke satu arah dengan keras."
  },
  AvgDialog_24097_Content_25 = {
    Text = "Di depan adalah api yang membesar dengan cepat, di belakang adalah dinding kabin yang terbuka lebar akibat ledakan."
  },
  AvgDialog_24097_Content_26 = {
    Text = "Penjaga! Jangan lepaskan tangan saya!"
  },
  AvgDialog_24097_Content_27 = {
    Text = "Ujung hidung dipenuhi bau pahit setelah batubara terbakar habis. Dalam sekejap setelah bersentuhan, salah satu pihak ditarik keras oleh gravitasi ke jurang."
  },
  AvgDialog_24097_Content_28 = {
    Text = "Suara yang akrab dan kehangatan tubuh orang itu perlahan menjauh, sementara kelembapan dan dingin secara bertahap meresap di sepanjang tulang belakang."
  },
  AvgDialog_24097_Content_29 = {
    Text = "Penjaga Rahasia!"
  },
  AvgDialog_24097_Content_3 = {
    Text = "Ini adalah ilusi yang dibangun oleh Miryam, mungkin inilah <Blue:Ranah dewa> yang pernah ia sebutkan…"
  },
  AvgDialog_24097_Content_30 = {
    Text = "Pada saat itu, waktu seolah membeku. Gelombang panas yang menyala seperti ribuan pedang tajam mengoyak kulit, setiap inci tendon terpanggang hingga rapuh seperti sayap belalang."
  },
  AvgDialog_24097_Content_31 = {
    Text = "Suara terompet yang kacau dan memekakkan telinga menembus alam roh, menghancurkan kewarasan dan ketenangan selama setahun terakhir. Dalam momen tanpa akhir ini, kamu merasakan kegelisahan dan perjuangan di tengah Kekacauan."
  },
  AvgDialog_24097_Content_32 = {
    Text = "Namun, pada akhirnya segalanya dilahap oleh nyala api, kesadaran berakhir di dalam kegelapan tanpa batas itu…"
  },
  AvgDialog_24097_Content_4 = {
    Text = "Negara di bawah kekuasaan Dewa, Lemuria yang abadi."
  },
  AvgDialog_24097_Content_5 = {
    Text = "\"Lemuria\"… Saya punya kesan bahwa beberapa sarjana dari departemen sejarah Mythag sedang berdebat tanpa henti tentang apakah itu benar-benar ada."
  },
  AvgDialog_24097_Content_6 = {
    Text = "Jika bencana itu tidak pernah terjadi, seharusnya ia tetap berdiri di sini, di tempat ini sekarang…"
  },
  AvgDialog_24097_Content_7 = {
    Text = "Karena itu sudah menjadi sejarah, bisakah kita membicarakan masalah kota ini setelah kita benar-benar aman? Mari kita selesaikan dulu masalah ini."
  },
  AvgDialog_24097_Content_8 = {
    Text = [[
Ramona, setelah kapal berlabuh, kita akan meninggalkan area Domain untuk menghubungi sekolah dan melakukan persiapan. 
 Tulu, kamu tetap di kapal untuk sementara waktu dan menjaga Murphy.]]
  },
  AvgDialog_24097_Content_9 = {
    Text = "Hmm, harus memberi tahu semua orang untuk mempersiapkan ruang operasi yang telah dipasangi runtun waktu. Adapun operasi pengelupasan parasit, mungkin Dekan Czort perlu melakukannya sendiri."
  },
  AvgDialog_24260_Content_1 = {
    Text = "Ternyata pulih lagi…?! Apakah serangan kita benar-benar tidak ada gunanya?"
  },
  AvgDialog_24260_Content_2 = {
    Text = "Tidak… Lihat dua ular energi raksasa itu, mereka memiliki aura Miryam yang sangat kuat. Mungkin kita perlu mengalahkan mereka terlebih dahulu…"
  },
  AvgDialog_24260_Content_3 = {
    Text = "Ketika Ranah Dewa masih ada, dia hanya bisa memanggil satu bayangan ular. Setelah bersembunyi selama sepuluh ribu tahun, sekarang dia mungkin bisa mengendalikan hingga <Yellow:delapan> bayangan pengikutnya."
  },
  AvgDialog_24260_Content_4 = {
    Text = "Rahasia Lemuria yang tak tersampaikan... Tidak bisa lagi membiarkannya terus-menerus terkikis oleh kemarahan. Jika dia sepenuhnya kehilangan kendali, dia akan menjadi monster yang sesungguhnya."
  },
  AvgDialog_24261_Content_1 = {
    Text = "Bayangan pengikut sudah tercerai-berai semua, tapi kenapa dia masih...!"
  },
  AvgDialog_24261_Content_2 = {
    Text = "Dia ingin memaksakan ritual, tetapi ini hanyalah ilusi miliknya… tanpa tarikan bintang-bintang, ritual hanya akan menghabiskan Jiwa semua orang."
  },
  AvgDialog_24261_Content_3 = {
    Text = "Imam Miryam! Atas nama @2 pelaku tindakan, saya memerintahkanmu untuk berhenti!"
  },
  AvgDialog_24261_Content_4 = {
    Text = "Pikiran telah dilahap oleh kemarahan. Miryam, yang sebelumnya dikenal sebagai monster, hanya berhenti sesaat, lalu kembali melancarkan serangan kegilaan."
  },
  AvgDialog_24261_Content_5 = {
    Text = "Dia sudah menganggap Yu sebagai pemalsu… Kalau begitu, Yu hanya bisa menghadapinya dengan cara Lemuria. Menundukkannya, atau… membunuhnya."
  },
  AvgDialog_24261_Content_6 = {
    Text = [[
Miryam... hamba paling setia...
Semoga kamu... tidak lagi bimbang.]]
  },
  AvgDialog_24282_Content_1 = {
    Text = "Selanjutnya akan menguji getaran layar 2"
  },
  AvgDialog_24282_Content_2 = {
    Text = "Secara teori, ilustrasi karakter harus bergetar bersama dengan latar belakang."
  },
  AvgDialog_24282_Content_3 = {
    Text = "Selanjutnya akan menguji pergeseran horizontal ke kiri dan kanan 2"
  },
  AvgDialog_24282_Content_4 = {
    Text = "Secara teori, ilustrasi karakter harus bergeser bersama dengan latar belakang."
  },
  AvgDialog_24282_Content_5 = {
    Text = "Pengujian selesai"
  },
  AvgDialog_24296_Content_1 = {
    Text = "Tidak bisa, orangnya terlalu banyak... Kalau terus begini hanya akan semakin buruk..."
  },
  AvgDialog_24296_Content_10 = {
    Text = "Tidak, Tuan Goliya——!!"
  },
  AvgDialog_24296_Content_11 = {
    Text = "Segalanya di depan mata seolah ditekan tombol jeda."
  },
  AvgDialog_24296_Content_12 = {
    Text = "Naluri tubuhmu melampaui kendalimu. Tubuhmu menerjang ke depan, tanpa pikir panjang menghalangi serangan yang mengarah ke Goliath."
  },
  AvgDialog_24296_Content_13 = {Text = "Ukh——"},
  AvgDialog_24296_Content_14 = {
    Text = "Mata pisau mengiris tenggorokanmu, kau gemetar menutupi luka yang terus mengucurkan darah, pikiranmu kacau balau."
  },
  AvgDialog_24296_Content_15 = {
    Text = "Kau sudah gila ya, datang menghalangi untuk apa?!"
  },
  AvgDialog_24296_Content_16 = {
    Text = "Aku tidak tahu… tubuhku… bergerak sendiri…"
  },
  AvgDialog_24296_Content_17 = {
    Text = "Maaf, Tuan Goliath…"
  },
  AvgDialog_24296_Content_2 = {
    Text = "Aku... masih bisa... terus membunuh!"
  },
  AvgDialog_24296_Content_20 = {
    Text = "Anak panah berlumur racun mematikan membelah udara, menancap di bahu Goliath. Ia tak mampu menahan tubuhnya dan terjatuh ke arahmu."
  },
  AvgDialog_24296_Content_21 = {
    Text = "Goliath… sang raksasa Goliath, akhirnya tumbang!"
  },
  AvgDialog_24296_Content_22 = {
    Text = "Kepalanya milikku, jangan ada yang berani merebutnya dariku!!!"
  },
  AvgDialog_24296_Content_23 = {
    Text = "Permukaan laut mengeluarkan gemuruh murka yang teredam, sang raksasa menutupi terik matahari di hadapanmu, lalu runtuh dengan dahsyat."
  },
  AvgDialog_24296_Content_24 = {
    Text = "Darah kalian berdua menyatu, mewarnai lautan biru menjadi merah darah."
  },
  AvgDialog_24296_Content_25 = {
    Text = "Di telingamu terdengar suara angin, deburan ombak, serta sorak-sorai dan suara perkelahian dari kejauhan. Setelah ini, yang menanti kalian hanyalah pembantaian dan penghinaan tanpa akhir."
  },
  AvgDialog_24296_Content_26 = {
    Text = "Air laut yang asin dan amis menjilati luka di lehermu, rasa sakitnya membuatmu terus-menerus meringis menghirup napas."
  },
  AvgDialog_24296_Content_27 = {
    Text = "Keadaan Goliath tak jauh lebih baik darimu."
  },
  AvgDialog_24296_Content_28 = {
    Text = "Melihatmu begitu kepayahan, dia masih sempat menyeringai dengan senyum menyebalkan ke arahmu."
  },
  AvgDialog_24296_Content_29 = {
    Text = "Hei… kau benar-benar harus bercermin, lihat penampilanmu yang konyol itu sekarang."
  },
  AvgDialog_24296_Content_3 = {
    Text = "Suara terompet berat terus bergema di atas permukaan laut. Di bawah iming-iming hadiah besar, para prajurit terus berdatangan bergabung dalam permainan perburuan ini."
  },
  AvgDialog_24296_Content_30 = {
    Text = "Sudah kuduga, memang tidak berguna."
  },
  AvgDialog_24296_Content_4 = {
    Text = "Goliya sudah hampir kehabisan tenaga. Ia kembali mengayunkan bilah raksasa di tangannya, namun kali ini, gerakannya yang lambat memberi celah bagi musuh untuk menyerang."
  },
  AvgDialog_24296_Content_6 = {
    Text = "Ia berlutut jatuh ke tanah, tulang putih terlihat jelas dari penampang lukanya, darah mengalir deras bagaikan sungai yang tak pernah kering."
  },
  AvgDialog_24296_Content_8 = {
    Text = "Sekarang saatnya, habisi dia dalam satu serangan!!"
  },
  AvgDialog_24296_Content_9 = {
    Text = "Para prajurit yang mengepung menyerbu maju bagaikan kawanan hiu yang haus darah."
  },
  AvgDialog_24297_Content_1 = {
    Text = "Uuh——!!"
  },
  AvgDialog_24297_Content_10 = {
    Text = "Di bawah iming-iming hadiah besar, pasti ada yang berani maju. Para prajurit mengeluarkan sorak penuh semangat, senjata-senjata beradu, menggemakan dentingan logam yang menggugah."
  },
  AvgDialog_24297_Content_11 = {
    Text = "Benar, ta-takut apa, kita kan banyak orang!"
  },
  AvgDialog_24297_Content_12 = {
    Text = "Potong dulu tangan yang memegang pedangnya!"
  },
  AvgDialog_24297_Content_13 = {
    Text = "Para prajurit yang semula gemetar kini berteriak murka, menyerbu maju bagaikan kawanan belalang yang haus darah."
  },
  AvgDialog_24297_Content_14 = {
    Text = "Hehe... wahai kaumku yang tercinta. Aku pernah mengajari kalian cara bertarung, cara membunuh, cara bertahan hidup."
  },
  AvgDialog_24297_Content_15 = {
    Text = "Tapi aku tidak pernah mengajari kalian, bagaimana cara melarikan diri saat menghadapi musuh yang berkali lipat lebih kuat."
  },
  AvgDialog_24297_Content_16 = {
    Text = "Goliya menjilat darah di sudut bibirnya, memperlihatkan taringnya yang tajam."
  },
  AvgDialog_24297_Content_17 = {
    Text = "...Karena kalian sudah tidak punya jalan untuk lari."
  },
  AvgDialog_24297_Content_18 = {
    Text = "Setelah berkata demikian, ia mencekik tenggorokan dua orang dengan santai, mengangkat kepala mereka dan menghantamkannya dengan keras—"
  },
  AvgDialog_24297_Content_19 = {Text = "Bumm!!"},
  AvgDialog_24297_Content_2 = {
    Text = "Tebasan pedang besar yang membabi buta menghancurkan kapal hingga berkeping-keping. Igren menyeret satu-satunya kaki yang tersisa dan mundur dengan panik ke sudut kapal."
  },
  AvgDialog_24297_Content_20 = {
    Text = "Campuran cairan putih kekuningan bercampur darah yang hancur menyembur keluar. Goliya tertawa terbahak-bahak, kobaran nafsu membunuh menyala di kedua pupil matanya."
  },
  AvgDialog_24297_Content_21 = {
    Text = "Hahaha! Kudengar ada yang ingin mengambil kepala ini?"
  },
  AvgDialog_24297_Content_22 = {
    Text = "Kalau berani, berbaris yang rapi dan maju satu per satu untuk mengambilnya!"
  },
  AvgDialog_24297_Content_3 = {
    Text = "<Shake:Bukankah kau terluka, bagaimana bisa...>"
  },
  AvgDialog_24297_Content_4 = {
    Text = "Maaf ya, untuk menghadapi anak buah rendahan sepertimu, aku sama sekali tidak perlu mengeluarkan seluruh kekuatanku."
  },
  AvgDialog_24297_Content_5 = {
    Text = "Goliath berdiri angkuh di haluan kapal, bilah raksasanya mengukir goresan melengkung di hadapannya, memisahkan para mantan saudara sebangsanya di luar garis itu."
  },
  AvgDialog_24297_Content_6 = {
    Text = "Ada lagi yang mau naik menemani aku bermain? Satu orang mana cukup untuk dibunuh?"
  },
  AvgDialog_24297_Content_7 = {
    Text = "Tertekan oleh tekanan mengerikan sang raksasa, para prajurit menggigil bagai serigala muda, tak seorang pun berani melangkahi garis lengkung di hadapan mereka, seolah itu adalah tanah terlarang yang tak boleh diinjak."
  },
  AvgDialog_24297_Content_8 = {
    Text = "Dasar sampah semua! Dia sudah terluka separah ini, sudah bukan lagi penguasa lautan yang dulu."
  },
  AvgDialog_24297_Content_9 = {
    Text = "Aku, prajurit Igren, bersumpah dengan nyawaku—siapa pun yang bisa memenggal kepala orang ini, kekayaan, tanah, dan wanitaku akan kuserahkan kepadanya!"
  },
  AvgDialog_24415_Content_1 = {
    Text = "Tunggu, Ramona!"
  },
  AvgDialog_24415_Content_10 = {
    Text = "Nona Ramona!"
  },
  AvgDialog_24415_Content_11 = {
    Text = "Dari sudut pandangmu, kau hanya bisa melihat Ramona tampak sedikit memiringkan kepala dan mengatakan sesuatu, sementara wajah Ogier memucat, lalu ia mundur dua langkah sambil menopang Doer."
  },
  AvgDialog_24415_Content_12 = {
    Text = "Ramona mengibaskan cairan hitam dari ujung pedangnya, lalu bergegas menuju menara lonceng tanpa ekspresi."
  },
  AvgDialog_24415_Content_13 = {
    Text = "Ramona, tunggu sebentar!"
  },
  AvgDialog_24415_Content_14 = {
    Text = "Ini bukan ingatan."
  },
  AvgDialog_24415_Content_15 = {
    Text = "Ini bahkan bukan Ramona yang kau kenal."
  },
  AvgDialog_24415_Content_16 = {
    Text = "Dingin, kejam, membuat orang gentar — rekanmu tidak seperti ini."
  },
  AvgDialog_24415_Content_17 = {
    Text = "Dia tidak akan melangkahi jasad rekan lamanya, tidak akan membunuh Rotan tanpa ampun, dan juga tidak akan… mengabaikan panggilanmu begitu saja."
  },
  AvgDialog_24415_Content_18 = {
    Text = "Ramona, Ramona!"
  },
  AvgDialog_24415_Content_19 = {
    Text = "Sosoknya perlahan menjauh, kau tak sempat memikirkan hal lain, hanya bisa bergegas mengejar."
  },
  AvgDialog_24415_Content_3 = {
    Text = [[
Di alun-alun sekolah, Rotan yang kehilangan kendali sedang mengamuk membabi buta.
Ogier berusaha sekuat tenaga melindungi Doer, tampak sudah hampir tak sanggup bertahan.]]
  },
  AvgDialog_24415_Content_4 = {
    Text = "Sebelum kau sempat mengejar, Ramona sudah mengacungkan rapiernya, menusuk tanpa ampun langsung ke wajah Rotan."
  },
  AvgDialog_24415_Content_5 = {
    Text = "Ramona, bahay——"
  },
  AvgDialog_24415_Content_6 = {
    Text = "Saat rapier mendekati dahi Rotan, sebuah kekosongan muncul di tempat yang ditunjuk ujung pedang, dan wajah bengis Rotan terpaku kosong sesaat."
  },
  AvgDialog_24415_Content_7 = {
    Text = "Detik berikutnya, pedang berkilat sekejap, dan Silver Core Rotan pecah seketika."
  },
  AvgDialog_24415_Content_8 = {
    Text = "Ini tidak… mungkin…"
  },
  AvgDialog_24415_Content_9 = {
    Text = "Rapier itu ditarik keluar tanpa belas kasihan, garis tajam yang ditoreh ujung pedang nyaris melukai Ogier yang berada di samping."
  },
  AvgDialog_24422_Content_1 = {
    Text = "<Gray:Senior yang telah tiada, pemakaman sekolah... Ini pasti ingatan Ramona tentang hari Upacara Penyerahan Kunci.>"
  },
  AvgDialog_24422_Content_2 = {
    Text = "<Gray:Tapi aku ingat, saat itu...>"
  },
  AvgDialog_24422_Content_3 = {
    Text = [[
Terima kasih, Penjaga Rahasia. Kau menyelamatkanku sekali lagi.
Kalau bukan karena tautan ini, mungkin nyawaku sudah di ujung tanduk sekarang.]]
  },
  AvgDialog_24422_Content_4 = {
    Text = "Menunda-nunda hanya akan merugikan kita. Kita harus menyelesaikan ini dengan cepat."
  },
  AvgDialog_24422_Content_5 = {
    Text = "Hah, maaf, sekarang tidak ada waktu untuk menunggu kau beradaptasi."
  },
  AvgDialog_24422_Content_6 = {
    Text = "<Gray:Ini sebenarnya ingatan siapa? Ramona itu, sebenarnya……>"
  },
  AvgDialog_24422_Content_7 = {
    Text = "<Gray:Tidak bisa begini, harus segera mengejarnya.>"
  },
  AvgDialog_25177_Content_1 = {
    Text = "Kondisi Tavi sudah pulih?! Bagaimana bisa?"
  },
  AvgDialog_25177_Content_2 = {
    Text = "Dalam ingatanku tentang pertempuran ini, Dia tidak pernah menunjukkan kemampuan seperti ini."
  },
  AvgDialog_25177_Content_3 = {
    Text = "Tidak……memang tidak pernah."
  },
  AvgDialog_25177_Content_4 = {
    Text = "Atau lebih tepatnya, tidak pernah sekalipun."
  },
  AvgDialog_25177_Content_5 = {
    Text = "Ramona menunduk menatap kunci perak di dadamu, bergumam pelan."
  },
  AvgDialog_25177_Content_6 = {
    Text = "Satu-satunya variabel……ternyata……"
  },
  AvgDialog_25177_Content_7 = {
    Text = "Ramona menyingkirkan ekspresi terkejutnya, dan sekali lagi mengarahkan pedangnya ke Tavi."
  },
  AvgDialog_25177_Content_8 = {
    Text = "Teruskan perintahmu, akhiri semua ini……\nSang Penjaga Rahasia."
  },
  AvgDialog_25186_Content_1 = {
    Text = "Peniup Seruling"
  },
  AvgDialog_25186_Content_10 = {
    Text = "Jangan takut, aku akan mencari cara untuk membawa kalian pergi."
  },
  AvgDialog_25186_Content_11 = {
    Text = "Para penduduk desa hanya menatapmu dalam diam, tanpa harapan maupun permusuhan di mata mereka."
  },
  AvgDialog_25186_Content_12 = {
    Text = "Oh iya, pelayan wanita itu……"
  },
  AvgDialog_25186_Content_13 = {
    Text = "Ayah dan adikku dikurung Di Bawah. Aku harus menyelamatkan mereka—"
  },
  AvgDialog_25186_Content_14 = {
    Text = "Permisi, apakah kalian mengenal seorang pelayan bernama Susanna?"
  },
  AvgDialog_25186_Content_15 = {
    Text = "Susanna, itu kakak perempuanku!"
  },
  AvgDialog_25186_Content_16 = {
    Text = "Suara anak-anak yang jernih terdengar dari sudut ruangan."
  },
  AvgDialog_25186_Content_17 = {
    Text = "Dengan cahaya lilin yang redup, barulah kamu menyadari seorang pria tua yang terbaring di sudut dan seorang anak laki-laki bermata bulat di sampingnya."
  },
  AvgDialog_25186_Content_18 = {
    Text = "Susanna adalah putriku…… Ada apa dengannya?"
  },
  AvgDialog_25186_Content_19 = {
    Text = "Dia sangat mengkhawatirkan keselamatan kalian dan ingin menyelamatkan kalian dari sini."
  },
  AvgDialog_25186_Content_2 = {
    Text = [[
Kastil Cambrian
Penjara Bawah Tanah]]
  },
  AvgDialog_25186_Content_20 = {
    Text = "Kami tidak bisa meninggalkan tempat ini……"
  },
  AvgDialog_25186_Content_21 = {
    Text = "Tubuh pria tua itu dipenuhi lubang-lubang korosi, cairan lengket yang mengalir darinya sudah lama menghitamkan jerami di bawahnya."
  },
  AvgDialog_25186_Content_22 = {
    Text = "Kami tinggal di sini atas kemauan sendiri. Setelah terjangkit penyakit, orang bisa menjadi gila, bahkan berubah menjadi monster."
  },
  AvgDialog_25186_Content_23 = {
    Text = "Benar, sudah banyak kasus pembunuhan terjadi di sekitar sini…… Kemudian Nyonya membawa orang-orangnya memeriksa dari rumah ke rumah, dan mengurung semua yang sakit di sini."
  },
  AvgDialog_25186_Content_24 = {
    Text = "Kalau tidak mau dikurung, maka harus pergi dari wilayah feodal ini dan bersumpah untuk tidak pernah kembali."
  },
  AvgDialog_25186_Content_25 = {
    Text = "Di sini setiap hari bisa minum bubur dan makan roti yang manis lho!"
  },
  AvgDialog_25186_Content_26 = {
    Text = "<Gray:Ternyata begitu. Jangan-jangan kita salah paham tentang dia?>"
  },
  AvgDialog_25186_Content_27 = {
    Text = "Apakah Nyonya Wanda baik kepada kalian sejak datang ke wilayah feodal ini?"
  },
  AvgDialog_25186_Content_28 = {
    Text = "Baik? Aku tidak tahu. Aku bahkan belum pernah melihatnya, hanya mendengar bahwa dia sangat kejam, membawa kematian bagi empat suaminya, dan merupakan penjelmaan iblis."
  },
  AvgDialog_25186_Content_29 = {
    Text = "Tapi selama bertahun-tahun dia berada di wilayah feodal ini, dia sudah melakukan banyak hal baik, dan kehidupan kita memang jauh lebih baik dari sebelumnya."
  },
  AvgDialog_25186_Content_3 = {
    Text = "Pintu besi yang berat tertutup di belakangmu."
  },
  AvgDialog_25186_Content_30 = {
    Text = "Dia mengajari kami membuka lahan pertanian, memelihara domba, lalu setiap musim festival, membawa wol ke pasar <Blue:Shariqi>, bisa menghasilkan banyak uang lho."
  },
  AvgDialog_25186_Content_31 = {
    Text = "Benar, pasar Shariqi itu juga direbut olehnya dari tangan Earl Goodrich, kedua belah pihak sudah berperang hampir setahun karenanya……"
  },
  AvgDialog_25186_Content_32 = {
    Text = "Para penduduk desa berebut menceritakan berbagai kisah tentang Wanda dalam mengelola wilayah feodal. Pertanian, peternakan, peleburan, pengelolaan manor……"
  },
  AvgDialog_25186_Content_33 = {
    Text = "Kamu terkejut dengan pemahaman mendalam Wanda terhadap berbagai urusan wilayah kekuasaannya. Dia sama sekali bukan tuan tanah yang hanya tenggelam dalam kesenangan."
  },
  AvgDialog_25186_Content_34 = {
    Text = "Seorang penguasa yang cukup baik, sayang harus menghadapi Erosi."
  },
  AvgDialog_25186_Content_35 = {
    Text = "<Gray:Penyebaran sebesar ini, di sekitar sini mungkin ada celah Erosi…>"
  },
  AvgDialog_25186_Content_36 = {
    Text = "Pintu besi di belakang tiba-tiba terbuka."
  },
  AvgDialog_25186_Content_37 = {
    Text = "Entah sejak kapan Wanda sudah berdiri di luar pintu penjara, cahaya lilin melapisi siluetnya dengan sinar jingga yang hangat."
  },
  AvgDialog_25186_Content_38 = {
    Text = "Keluarkan orang ini, ada hal yang ingin kubicarakan dengannya secara pribadi."
  },
  AvgDialog_25186_Content_39 = {
    Text = [[
Kastil Cambrian
Taman]]
  },
  AvgDialog_25186_Content_4 = {
    Text = "Kau berbalik, dan tanpa diduga bertemu dengan pasang-pasang mata yang berkilau, mengepungmu dalam kegelapan bagai binatang buas."
  },
  AvgDialog_25186_Content_40 = {
    Text = "Kalian berjalan bersama di atas rumput yang lembut, hingga sampai di tepi danau."
  },
  AvgDialog_25186_Content_41 = {
    Text = "Air danau di tengah malam bagaikan cermin gelap pekat, memantulkan samar-samar cahaya bulan yang terpecah di permukaannya."
  },
  AvgDialog_25186_Content_42 = {
    Text = "Kurasa kamu sudah paham, Cambrian sekarang sedang dilanda bencana yang sangat serius, dan aku tidak berdaya menghadapinya."
  },
  AvgDialog_25186_Content_43 = {
    Text = "Sedangkan kamu, saat bertarung melawan monster-monster itu di kastil, gerakanmu sangat terlatih. Kelihatannya kamu sudah berpengalaman."
  },
  AvgDialog_25186_Content_44 = {
    Text = "<Gray:Ini memang pekerjaanku, bagaimanapun juga…>"
  },
  AvgDialog_25186_Content_45 = {
    Text = "Bukankah Nyonya saat itu berada di kamar tidur? Bagaimana bisa tahu sedetail itu?"
  },
  AvgDialog_25186_Content_46 = {
    Text = "Mata dan telingaku tersebar di seluruh Cambrian. Bunga freesia di sini pun harus mendapat izinku untuk mekar. Tidak ada hal yang tidak kuketahui."
  },
  AvgDialog_25186_Content_47 = {
    Text = "Lalu bagaimana dengan pelayan itu? Sudah tahu dia mata-mata, kenapa masih dibiarkan?"
  },
  AvgDialog_25186_Content_48 = {
    Text = "Wanda melambaikan tangannya dengan acuh tak acuh."
  },
  AvgDialog_25186_Content_49 = {
    Text = "Dia hanyalah manusia biasa yang malang, tidak bisa menyentuh sehelai rambutku pun."
  },
  AvgDialog_25186_Content_5 = {
    Text = "<Shake:Uwaaah!!>"
  },
  AvgDialog_25186_Content_50 = {
    Text = "Lagipula dia melayaniku dengan cukup nyaman. Menemukan pelayan manusia yang memuaskan bukanlah hal yang mudah."
  },
  AvgDialog_25186_Content_51 = {
    Text = "Singkatnya, aku ingin kamu membantuku mengatasi Erosi. Jangan buru-buru menolak—soal harga dan semacamnya bisa dibicarakan, apa pun yang kamu inginkan akan kuusahakan untuk dipenuhi."
  },
  AvgDialog_25186_Content_52 = {
    Text = "Kamu juga tidak tega melihat para penduduk desa mati sia-sia, bukan, \"Tuan Biarawan\" yang terhormat?"
  },
  AvgDialog_25186_Content_54 = {
    Text = "Selalu menyebut \"kalian manusia\" di setiap kesempatan, ditambah duri-duri aneh itu… Nyonya Wanda, Anda sebenarnya bukan manusia, kan?"
  },
  AvgDialog_25186_Content_55 = {
    Text = "Makhluk yang berasal dari tempat yang jauh, tapi peduli pada hidup matinya penduduk desa yang lemah. Apa tujuan sebenarnya Anda, Nyonya?"
  },
  AvgDialog_25186_Content_56 = {
    Text = "Menghadapi pertanyaan tajammu, Wanda mengangkat alisnya, lalu tiba-tiba tertawa terbahak-bahak."
  },
  AvgDialog_25186_Content_57 = {
    Text = "Apakah yang baru saya katakan itu lucu?"
  },
  AvgDialog_25186_Content_58 = {
    Text = "Tidak… Hahahahaha! Aku hanya terlalu senang. Bertahun-tahun di sini, akhirnya aku bertemu seseorang yang sama-sama bukan berasal dari \"sini\"."
  },
  AvgDialog_25186_Content_59 = {
    Text = "Bagaimana kau tahu—"
  },
  AvgDialog_25186_Content_6 = {
    Text = "Setelah penglihatanmu beradaptasi, barulah kau bisa melihat jelas pemandangan di hadapanmu."
  },
  AvgDialog_25186_Content_60 = {
    Text = "Wanda mengulurkan jari telunjuknya dan menyentuh bibirmu dengan lembut."
  },
  AvgDialog_25186_Content_61 = {
    Text = "Sst… Ikut aku, ada sesuatu yang ingin kutunjukkan."
  },
  AvgDialog_25186_Content_62 = {
    Text = "Kalian melewati hutan dan tiba di tepi danau yang tenang."
  },
  AvgDialog_25186_Content_63 = {
    Text = "Kadang-kadang aku mengalami ilusi yang indah… Seolah-olah dari pantulan danau ini, aku bisa melihat kota tempat tinggalku dulu."
  },
  AvgDialog_25186_Content_64 = {
    Text = "Kota raksasa yang terdiri dari batu-batu hitam, batasnya terus meluas, hingga akhirnya merambat ke ujung yang tak terlihat…"
  },
  AvgDialog_25186_Content_65 = {
    Text = "Air danau biru gelap itu hampir tak terlihat dasarnya. Mendengarkan deskripsi Wanda, di hadapanmu seolah muncul wujud kota itu sebagaimana mestinya."
  },
  AvgDialog_25186_Content_66 = {
    Text = "Menara runcing berbentuk spiral hitam, dinding-dinding bersudut tumpul yang menyeramkan…"
  },
  AvgDialog_25186_Content_67 = {
    Text = "Saat itu, aku memiliki istana yang sangat besar. Pelayan yang melayani aku saja berjumlah ribuan orang."
  },
  AvgDialog_25186_Content_68 = {
    Text = "Seperti yang kau katakan, aku tidak pernah peduli pada hidup mati para pelayan itu."
  },
  AvgDialog_25186_Content_69 = {
    Text = "Aku selalu bertindak sesuka hati. Para pelayanku, bahkan seluruh kota, adalah perpanjangan dari hasrat dan ambisiku."
  },
  AvgDialog_25186_Content_7 = {
    Text = "Ada yang duduk, ada yang berbaring, ada yang bersandar di dinding…… semuanya penduduk desa berpakaian compang-camping."
  },
  AvgDialog_25186_Content_70 = {
    Text = "Kemudian planetku mengalami bencana yang kalian sebut \"Erosi\", dan semua orang mati."
  },
  AvgDialog_25186_Content_71 = {
    Text = "Aku duduk sendirian di aula untuk waktu yang sangat, sangat lama, menyaksikan istanaku, ibu kotaku, segalanya berubah menjadi reruntuhan."
  },
  AvgDialog_25186_Content_72 = {
    Text = "Sejujurnya, perasaan itu sangat buruk. Tidak ada yang mau mengalaminya untuk kedua kalinya."
  },
  AvgDialog_25186_Content_73 = {
    Text = "Nyonya Wanda… Maaf, kali ini aku tidak bisa membantumu."
  },
  AvgDialog_25186_Content_74 = {
    Text = "Tidak perlu khawatir, ceritakan kegelisahanmu, aku akan memberikan segala bantuan yang kau butuhkan."
  },
  AvgDialog_25186_Content_75 = {
    Text = "Kau menggelengkan kepala."
  },
  AvgDialog_25186_Content_76 = {
    Text = "Bukan hanya itu… Lingkungan tempat kita berada sekarang juga memiliki beberapa, ehm, keistimewaan…"
  },
  AvgDialog_25186_Content_77 = {
    Text = "Selama berada di dalam mimpi, kau tidak bisa menutup Celah Erosi."
  },
  AvgDialog_25186_Content_78 = {
    Text = "<Gray:Bagaimana caranya menjelaskan hal ini kepada Nyonya Wanda…>"
  },
  AvgDialog_25186_Content_79 = {
    Text = "Karena kita sekarang berada di dalam mimpi, jadi Anda tidak bisa membantuku, benar?"
  },
  AvgDialog_25186_Content_8 = {
    Text = "Tubuh mereka semua dipenuhi luka erosi besar dan kecil, ada yang tubuhnya sudah terkorosi sebagian besar, udara dipenuhi aroma penyakit dan kematian."
  },
  AvgDialog_25186_Content_80 = {Text = "?!"},
  AvgDialog_25186_Content_81 = {
    Text = "Anda sudah menyadarinya?"
  },
  AvgDialog_25186_Content_82 = {
    Text = "Wanda menunduk menatap kota hitam di dalam air, matanya berkilauan memantulkan cahaya bulan putih yang lembut."
  },
  AvgDialog_25186_Content_83 = {
    Text = "Sejak tiba di sini, aku sudah bermimpi banyak kali. Tentang perang, bencana, waktu… Tapi tak sekalipun aku memimpikan ibu kotaku."
  },
  AvgDialog_25186_Content_84 = {
    Text = "Tepat saat aku hampir melupakannya, aku bertemu denganmu, lalu melihatnya lagi di dasar danau."
  },
  AvgDialog_25186_Content_85 = {
    Text = "Kau tahu? Ketika seseorang yang akan mati melihat peniup seruling berjalan menembus kabut, dia tidak akan takut, juga tidak akan penasaran."
  },
  AvgDialog_25186_Content_86 = {
    Text = "Dia hanya akan diam-diam mengikuti sang peniup seruling, menuju tempat yang menjadi miliknya."
  },
  AvgDialog_25186_Content_87 = {
    Text = "Wanda menghela napas pelan."
  },
  AvgDialog_25186_Content_88 = {
    Text = "Ibu kotaku yang telah tiada itu… indahnya bagaikan mimpi orang yang akan mati."
  },
  AvgDialog_25186_Content_89 = {
    Text = "Dia lembut membelai pelayan buta yang diam membisu di sampingnya."
  },
  AvgDialog_25186_Content_9 = {
    Text = "Wanda ternyata mengurung kalian di sini……"
  },
  AvgDialog_25186_Content_90 = {
    Text = "<Change>Nyonya…"
  },
  AvgDialog_25186_Content_91 = {
    Text = "Cambrian adalah kampung halaman keduaku. Waktu kebersamaan kami tidak lama, tak kusangka sudah tiba saatnya untuk berpisah lagi."
  },
  AvgDialog_25186_Content_92 = {
    Text = "Maafkan aku, Nyonya Wanda…"
  },
  AvgDialog_25186_Content_93 = {
    Text = "Wanda melambaikan tangan padamu. Saat mengangkat kepalanya kembali, awan mendung di wajahnya sudah lenyap sepenuhnya."
  },
  AvgDialog_25186_Content_94 = {
    Text = "Tenang saja. Karena sudah menjadi penguasa wilayah ini, aku harus bertanggung jawab kepada semua orang."
  },
  AvgDialog_25186_Content_95 = {
    Text = "Bukankah ini hanya soal mati bersama? Kalau begitu, mari kita mati dengan gagah berani bersama-sama."
  },
  AvgDialog_25186_Content_96 = {
    Text = "Apa yang kau rencanakan?"
  },
  AvgDialog_25186_Content_97 = {
    Text = "Wanda menunjukkan senyum penuh misteri dan mengedipkan mata padamu."
  },
  AvgDialog_25186_Content_98 = {
    Text = "Sebuah pesta perpisahan yang megah."
  },
  AvgDialog_25187_Content_1 = {
    Text = "Empat Pernikahan"
  },
  AvgDialog_25187_Content_10 = {
    Text = "Akhirnya kau mengikuti langkah dayang dengan patuh, tak henti-hentinya mencium aroma bedak yang menyengat dari tubuhmu sendiri."
  },
  AvgDialog_25187_Content_11 = {
    Text = "Ini adalah kastil khas era lama, dindingnya seluruhnya terbuat dari batu bata tebal, untuk menahan serangan musuh yang bisa datang kapan saja."
  },
  AvgDialog_25187_Content_12 = {
    Text = "Kelihatannya agak bocor anginnya, pasti sangat dingin saat musim dingin."
  },
  AvgDialog_25187_Content_13 = {
    Text = "Eh, ini……?"
  },
  AvgDialog_25187_Content_14 = {
    Text = "Di celah-celah dinding bata, cairan korosi hitam perlahan merembes keluar."
  },
  AvgDialog_25187_Content_15 = {
    Text = "Mereka berkumpul tanpa suara di satu titik, hingga mengeras dan terbentuk."
  },
  AvgDialog_25187_Content_16 = {
    Text = "Awooo——!!"
  },
  AvgDialog_25187_Content_17 = {
    Text = "<Shake:Kau merasakannya? Ada sesuatu di dekat sini……>"
  },
  AvgDialog_25187_Content_18 = {
    Text = "Datang lagi……monster datang lagi!"
  },
  AvgDialog_25187_Content_19 = {
    Text = "Berdirilah di belakangku."
  },
  AvgDialog_25187_Content_2 = {
    Text = "Byurrr——"
  },
  AvgDialog_25187_Content_20 = {
    Text = "Tapi kau kan……"
  },
  AvgDialog_25187_Content_21 = {
    Text = "Dayang itu menatapmu dengan ragu, memandangi rantai berat yang membelenggu tangan dan kakimu."
  },
  AvgDialog_25187_Content_22 = {
    Text = "Kau memejamkan mata, menangkap koneksi samar dengan Awakened Body lain di kedalaman kesadaranmu."
  },
  AvgDialog_25187_Content_23 = {
    Text = "Meskipun selama bermimpi, dibatasi oleh kekuatan spiritual biarawan yang lemah, Awakened Body yang kau panggil memiliki kemampuan yang rendah, tapi——"
  },
  AvgDialog_25187_Content_24 = {
    Text = "Untuk menghadapi kalian, ini sudah lebih dari cukup."
  },
  AvgDialog_25187_Content_3 = {
    Text = "Air dingin disiramkan ke kepalamu."
  },
  AvgDialog_25187_Content_4 = {
    Text = "Rasa nyeri tumpul menjalar di dada, seseorang menendang lukamu dengan keras dua kali."
  },
  AvgDialog_25187_Content_5 = {
    Text = "Ugh! Uhuk uhuk……"
  },
  AvgDialog_25187_Content_6 = {
    Text = "<Change>Menemani tidur. Menemani tidur."
  },
  AvgDialog_25187_Content_7 = {
    Text = "Sudah berapa kali disiram air sampai terbangun……"
  },
  AvgDialog_25187_Content_8 = {
    Text = "Kau menghela napas, membiarkan para pelayan menyeretmu keluar."
  },
  AvgDialog_25187_Content_9 = {
    Text = "Mandi, berganti pakaian, berdandan……"
  },
  AvgDialog_25188_Content_1 = {
    Text = [[
Kastil Cambrian
Kamar Tidur Wanda]]
  },
  AvgDialog_25188_Content_10 = {
    Text = "Maaf… saya tidak mengerti maksud Anda, Nyonya Wanda."
  },
  AvgDialog_25188_Content_11 = {
    Text = "Oh? Tapi ekspresimu berkata lain."
  },
  AvgDialog_25188_Content_12 = {
    Text = "Wanda mengangkat dagunya, menunjuk ke arah cincin yang tergeletak tak jauh dari sana."
  },
  AvgDialog_25188_Content_13 = {
    Text = "Itu cincin pemberian <Blue:suami keempatku>, tahu kenapa dia menghilang kemudian?"
  },
  AvgDialog_25188_Content_14 = {
    Text = "<Shake:Ti-tidak begitu tahu…>"
  },
  AvgDialog_25188_Content_15 = {
    Text = "Dia dulu dijuluki \"Plantagenet dari Cambrian\", seorang ksatria yang sangat hebat."
  },
  AvgDialog_25188_Content_16 = {
    Text = "Tapi kemudian, dia berani berkomplot dengan bangsawan lain untuk menggulingkanku, bahkan meracuni anggur dan makananku."
  },
  AvgDialog_25188_Content_17 = {
    Text = "Sayang sekali, sekarang dia tak bisa lagi meracuni siapa pun…"
  },
  AvgDialog_25188_Content_18 = {
    Text = "Wanda mengulurkan tangan membelai lembut pipi dingin seorang pelayan, matanya penuh kasih sayang."
  },
  AvgDialog_25188_Content_19 = {
    Text = "Aku benar, kan, suamiku tersayang?"
  },
  AvgDialog_25188_Content_2 = {
    Text = "Akhirnya kau datang juga, Tuan Vien. Kemari, bantu aku melepaskan cincin-cincin ini."
  },
  AvgDialog_25188_Content_20 = {
    Text = "<Change>Nyonya, sa…sayang……"
  },
  AvgDialog_25188_Content_21 = {
    Text = "Pelayan buta itu dengan patuh bersandar di pelukan Wanda, tampak sangat menikmati belaian darinya."
  },
  AvgDialog_25188_Content_22 = {
    Text = "?! Kau berani menjadikan suamimu……"
  },
  AvgDialog_25188_Content_23 = {
    Text = "Baiklah, cerita pengantar tidurku sudah selesai. Sekarang giliranmu, biarawan kecil."
  },
  AvgDialog_25188_Content_24 = {
    Text = "Coba pikirkan baik-baik, be·nar·-be·nar tidak ada yang ingin kau katakan padaku?"
  },
  AvgDialog_25188_Content_25 = {
    Text = "Wanda menyimpan senyumnya, menatapmu tanpa ekspresi. Aura tekanan yang kuat terpancar dari sekujur tubuhnya, hampir membuatmu tak bisa bernapas."
  },
  AvgDialog_25188_Content_27 = {
    Text = "Sudah sampai di titik ini, segala penyembunyian terasa sia-sia. Kau mengeluarkan catatan dari sakumu dan menyerahkannya kepada Wanda."
  },
  AvgDialog_25188_Content_28 = {
    Text = "Nyonya Wanda, aku bisa menjelaskan! Bukan aku yang memulainya!"
  },
  AvgDialog_25188_Content_29 = {
    Text = "Kaulah yang memberikan catatan itu kepadanya, benar?"
  },
  AvgDialog_25188_Content_3 = {
    Text = "Wanda duduk di depan meja rias yang besar, mengulurkan jari-jarinya yang ramping ke arahmu, dengan cincin-cincin mewah yang bertumpuk di atasnya."
  },
  AvgDialog_25188_Content_30 = {
    Text = "Wanda sedikit mengangkat kelopak matanya, melirik ke arah pelayan wanita di sampingnya."
  },
  AvgDialog_25188_Content_31 = {
    Text = "Benar…… catatan itu dariku."
  },
  AvgDialog_25188_Content_32 = {
    Text = "Pelayan wanita itu menundukkan kepala, seluruh tubuhnya gemetar tanpa henti. Kemudian dia menarik napas dalam-dalam dan menegakkan punggungnya."
  },
  AvgDialog_25188_Content_33 = {
    Text = "Iblis, kau iblis!"
  },
  AvgDialog_25188_Content_34 = {
    Text = "Ayah dan adikku dikurung di bawah sana, aku harus menyelamatkan mereka——"
  },
  AvgDialog_25188_Content_35 = {
    Text = "GRRRUMMMM——!"
  },
  AvgDialog_25188_Content_36 = {
    Text = "Duri-duri tajam muncul dari bawah tanah, mengepung pelayan wanita itu."
  },
  AvgDialog_25188_Content_37 = {
    Text = "Aku sama sekali tidak tertarik dengan kisah tragismu. Penjaga, buang dia keluar."
  },
  AvgDialog_25188_Content_38 = {
    Text = "Nyonya Wanda, dia hanyalah bagian paling tidak penting dalam permainan ini, tolong jangan membunuh sembarangan……"
  },
  AvgDialog_25188_Content_39 = {
    Text = "Kata-katamu belum selesai terucap, Wanda sudah mencekik erat tenggorokanmu, mengangkatmu hingga sejajar dengan tatapan matanya."
  },
  AvgDialog_25188_Content_4 = {
    Text = "Para pelayan buta yang tangan dan kakinya telah dipotong berdiri bagai hantu di belakangnya, membisu dalam cahaya bulan."
  },
  AvgDialog_25188_Content_40 = {
    Text = "Saat aku menyuruhmu bicara, barulah kau boleh bicara. Mengerti?"
  },
  AvgDialog_25188_Content_41 = {
    Text = "<Shake:Uhuk uhuk…… Ugh……>"
  },
  AvgDialog_25188_Content_42 = {
    Text = "Kau ini, masih ketagihan menyamar jadi biarawan? Datang ke hadapanku berpura-pura jadi orang suci?"
  },
  AvgDialog_25188_Content_43 = {Text = "?!"},
  AvgDialog_25188_Content_44 = {
    Text = "Bagaimana kau, bisa tahu……"
  },
  AvgDialog_25188_Content_45 = {
    Text = "Wanda melepaskan tangannya, dan kau langsung ambruk ke tanah. Dia menyilangkan kaki dengan santai, menikmati pemandanganmu yang terus-menerus terbatuk."
  },
  AvgDialog_25188_Content_46 = {
    Text = "Trik-trik kecil kalian manusia sudah lama membuatku bosan, tentu saja kau bukan Verne·@2."
  },
  AvgDialog_25188_Content_47 = {
    Text = "Lemparkan dia ke penjara, baru keluarkan kalau dia mau bicara jujur."
  },
  AvgDialog_25188_Content_48 = {
    Text = "<Change>Siap!"
  },
  AvgDialog_25188_Content_5 = {
    Text = "Kau melangkah berat berdiri di hadapannya, menunduk melepaskan cincin satu per satu, sementara pikiranmu tak henti memikirkan catatan itu."
  },
  AvgDialog_25188_Content_6 = {
    Text = "<Gray:Tempat biasa itu di mana ya…>"
  },
  AvgDialog_25188_Content_7 = {
    Text = "Kenapa, sepertinya ada yang ingin kau katakan padaku?"
  },
  AvgDialog_25188_Content_8 = {Text = "?!"},
  AvgDialog_25188_Content_9 = {
    Text = "Pergelangan tanganmu bergetar, cincin batu mata kucing jatuh ke lantai, menggelinding hingga ke tepi tempat tidur."
  },
  AvgDialog_25189_Content_1 = {
    Text = "Ratu yang Terasing"
  },
  AvgDialog_25189_Content_10 = {
    Text = "Belum bangun juga? Kalau begitu, buat dia segar sedikit."
  },
  AvgDialog_25189_Content_11 = {
    Text = "Ugh……!!"
  },
  AvgDialog_25189_Content_12 = {
    Text = "Rasa dingin menusuk di dada."
  },
  AvgDialog_25189_Content_13 = {
    Text = "<Change>Masih tidak ada reaksi… Nyonya…"
  },
  AvgDialog_25189_Content_14 = {
    Text = "Kalau begitu potong saja, yang rapi."
  },
  AvgDialog_25189_Content_15 = {Text = "!!"},
  AvgDialog_25189_Content_16 = {
    Text = "<Big:Po, potong apa?!>"
  },
  AvgDialog_25189_Content_17 = {
    Text = "Kau terikat di atas tiang eksekusi yang dingin membeku, pisau guillotine yang berat berada kurang dari 10 inci di atas pahamu, tampak akan segera jatuh—"
  },
  AvgDialog_25189_Content_18 = {
    Text = "Tunggu sebentar…… <Big:Sssh!>"
  },
  AvgDialog_25189_Content_19 = {
    Text = "Rasa sakit yang hebat menjalar dari dada. Jubahmu sudah tercabik-cabik tak berbentuk, memperlihatkan bekas luka yang mengerikan di mana-mana."
  },
  AvgDialog_25189_Content_2 = {
    Text = "Dahulu kala……"
  },
  AvgDialog_25189_Content_20 = {
    Text = "Jelas, tubuh ini pernah mengalami penyiksaan yang tidak manusiawi."
  },
  AvgDialog_25189_Content_21 = {
    Text = "Akhirnya kau sadar juga."
  },
  AvgDialog_25189_Content_22 = {
    Text = "Suara wanita yang lembut namun tetap berwibawa menggema di aula yang luas."
  },
  AvgDialog_25189_Content_23 = {
    Text = "Lady Wanda yang agung bersandar pada pelayannya, memandangmu dengan mata menyipit."
  },
  AvgDialog_25189_Content_24 = {
    Text = "Apa yang sedang terjadi?!"
  },
  AvgDialog_25189_Content_25 = {
    Text = "\"Senantiasa berbuat cabul, memperturutkan hawa nafsu…\""
  },
  AvgDialog_25189_Content_26 = {
    Text = "Apa kalimat selanjutnya? Lanjutkan hafalanmu, biarawan kecil."
  },
  AvgDialog_25189_Content_27 = {Text = "...?"},
  AvgDialog_25189_Content_28 = {
    Text = "Kenapa, di gerbang kota kau mengulang-ulang kitab suci begitu lama, begitu masuk langsung lupa semuanya?"
  },
  AvgDialog_25189_Content_29 = {
    Text = "Gerbang kota, kitab suci……"
  },
  AvgDialog_25189_Content_3 = {
    Text = "Semua yang terlihat olehnya berada di bawah kekuasaannya."
  },
  AvgDialog_25189_Content_30 = {
    Text = "Setelah mengalami hukuman yang kejam, kesadaran tubuh ini sudah lama kacau. Kau memusatkan perhatian, akhirnya berhasil menyusun sebagian ingatan."
  },
  AvgDialog_25189_Content_31 = {
    Text = "<Blue:Vien·@2>, 23 tahun, lahir di selatan Shropshire, tiga bulan lalu menjadi biarawan di keuskupan Cambrian."
  },
  AvgDialog_25189_Content_32 = {
    Text = "Seorang yang beriman dan penuh kasih, merasa prihatin dengan gaya hidup Wanda yang mewah dan penuh nafsu, setiap pagi datang ke gerbang kastil untuk membacakan kitab suci."
  },
  AvgDialog_25189_Content_33 = {
    Text = "Hingga akhirnya dikawal masuk oleh para penjaga yang sudah tidak tahan lagi, Vien telah bertahan selama 23 hari."
  },
  AvgDialog_25189_Content_34 = {
    Text = "Senantiasa berbuat cabul, memperturutkan hawa nafsu…… selanjutnya adalah……"
  },
  AvgDialog_25189_Content_35 = {
    Text = "Hmm. Sepertinya benar-benar lupa? Kalau begitu belah saja dia jadi dua."
  },
  AvgDialog_25189_Content_36 = {
    Text = "Wanda menguap, melambaikan tangan dengan malas."
  },
  AvgDialog_25189_Content_37 = {
    Text = "Jatuh——"
  },
  AvgDialog_25189_Content_38 = {
    Text = "Tiang eksekusi berderak-derak berputar, pisau guillotine jatuh dengan cepat, angin dingin yang ditimbulkannya segera membangkitkan naluri bertahan hidupmu."
  },
  AvgDialog_25189_Content_39 = {
    Text = "Tu-tunggu sebentar! Aku sudah ingat lagi!"
  },
  AvgDialog_25189_Content_4 = {
    Text = "Di malam hari, ia duduk sendirian di teras yang tinggi, memandangi planet-planet yang berputar perlahan di sekelilingnya."
  },
  AvgDialog_25189_Content_40 = {
    Text = "<Shake:Akan menerima hukuman apa, sebagai peringatan, peringat……>"
  },
  AvgDialog_25189_Content_41 = {
    Text = "<Gray:Sialan, andai saja aku punya daya ingat seperti Ramona.>"
  },
  AvgDialog_25189_Content_42 = {
    Text = "<Change>Nyonya, mata-mata……"
  },
  AvgDialog_25189_Content_43 = {
    Text = "Pelayan yang sejak tadi diam itu menggerakkan tenggorokannya, mengeluarkan suara gumaman yang parau."
  },
  AvgDialog_25189_Content_44 = {
    Text = "Oh? Coba jelaskan."
  },
  AvgDialog_25189_Content_45 = {
    Text = "<Change>Paroki, kitab suci."
  },
  AvgDialog_25189_Content_46 = {
    Text = "Begitu rupanya……"
  },
  AvgDialog_25189_Content_47 = {
    Text = "Peliharaan kecilku memberitahuku, sepertinya kau ini mata-mata. Seorang biarawan yang ditugaskan oleh paroki, tapi bahkan tidak bisa mengingat ayat-ayat dasar kitab suci."
  },
  AvgDialog_25189_Content_48 = {Text = "Tapi——"},
  AvgDialog_25189_Content_49 = {Text = "Duaaarr!!"},
  AvgDialog_25189_Content_5 = {
    Text = "Ia bernyanyi, berbicara sendiri, dan terkadang tertidur tanpa disadari."
  },
  AvgDialog_25189_Content_50 = {
    Text = "Duri-duri tajam muncul dari tanah, mengarah tepat ke tenggorokan pelayan buta itu. Wanda mengangkat kelopak matanya, menatapnya dengan dingin."
  },
  AvgDialog_25189_Content_51 = {
    Text = "Kau boleh bicara hanya saat aku menyuruhmu bicara. Saat aku tidak menyuruhmu bicara, kau adalah orang bisu. Paham?"
  },
  AvgDialog_25189_Content_52 = {
    Text = "<Change>Patuh. Paham."
  },
  AvgDialog_25189_Content_53 = {
    Text = "Pelayan buta itu langsung terdiam, kembali mundur ke balik bayangan di sudut ruangan."
  },
  AvgDialog_25189_Content_54 = {
    Text = "Aula yang tadinya riuh mendadak sunyi senyap, bahkan suara jarum jatuh pun tak terdengar."
  },
  AvgDialog_25189_Content_55 = {
    Text = "Wanda memegang gelas anggur merah, melangkah dengan anggun namun penuh kekuatan menghampirimu."
  },
  AvgDialog_25189_Content_56 = {
    Text = "Dia mengulurkan tangannya, kuku-kuku panjangnya menyapu dadamu, lalu berhenti di lehermu yang rentan."
  },
  AvgDialog_25189_Content_57 = {
    Text = "Dia tadi bilang kau mata-mata. <Red:Jadi…… benarkah?>"
  },
  AvgDialog_25189_Content_58 = {
    Text = "Wanda menyipitkan kedua matanya yang berwarna kuning kobalt, sedikit kebuasan dan kekejaman tersembunyi dengan baik di dalamnya, hanya sesekali berkilat dalam lirikan yang tak disengaja."
  },
  AvgDialog_25189_Content_59 = {
    Text = "Jika jawabanmu berikutnya tidak memuaskannya, kuku-kukunya pasti akan menusuk tenggorokanmu tanpa ampun."
  },
  AvgDialog_25189_Content_6 = {
    Text = [[
Ia selalu sebebas ini.
Sebelum bencana, ia adalah ratu di sini; setelah bencana, ia adalah satu-satunya yang tersisa.]]
  },
  AvgDialog_25189_Content_60 = {
    Text = "Kau menarik napas dalam-dalam, berusaha memaksa dirimu menatap langsung kedua mata Wanda."
  },
  AvgDialog_25189_Content_61 = {
    Text = "Kalau aku benar-benar mata-mata, aku tidak akan memilih identitas seperti ini."
  },
  AvgDialog_25189_Content_62 = {
    Text = "Pertama, itu terlalu mencolok, akan menarik banyak perhatian dan masalah."
  },
  AvgDialog_25189_Content_63 = {
    Text = "Kedua, itu terlalu berbahaya. Siapa di Cambrian yang tidak tahu bahwa hal yang paling dibenci Nyonya Wanda adalah biarawan—umph!"
  },
  AvgDialog_25189_Content_64 = {
    Text = "Cairan anggur dingin mengalir di sepanjang leher, dengan cepat meresap ke dalam luka."
  },
  AvgDialog_25189_Content_65 = {
    Text = "Wanda melempar gelas anggur kosong di tangannya, lalu tersenyum padamu."
  },
  AvgDialog_25189_Content_66 = {
    Text = "Aku memang tidak suka biarawan. Lalu? Lanjutkan, Tuan Verne."
  },
  AvgDialog_25189_Content_68 = {
    Text = "<Shake:Me-menyamar sebagai biarawan, setiap hari membaca doa di gerbang kota, aku mungkin sudah mati beberapa kali sebelum sempat bertemu denganmu…>"
  },
  AvgDialog_25189_Content_69 = {
    Text = "Wanda tertawa terbahak-bahak, tampaknya sangat puas dengan jawabanmu."
  },
  AvgDialog_25189_Content_7 = {
    Text = "Maka ia selalu bisa sebebas ini."
  },
  AvgDialog_25189_Content_70 = {
    Text = "Sungguh mengejutkan, ternyata kau juga bukan orang yang kaku dan membosankan."
  },
  AvgDialog_25189_Content_71 = {
    Text = "Aku suka orang pintar, dan lebih suka orang yang pintar sekaligus tampan."
  },
  AvgDialog_25189_Content_72 = {
    Text = "Wanda menepuk-nepuk pipimu dengan penuh sayang, lalu memanggil pelayan dengan suara lantang."
  },
  AvgDialog_25189_Content_73 = {
    Text = "Bawa dia pergi, malam nanti mandikan dia bersih-bersih dan bawa ke kamar tidurku."
  },
  AvgDialog_25189_Content_74 = {
    Text = "Kamar tidur? Mau apa ini…"
  },
  AvgDialog_25189_Content_75 = {
    Text = [[
Tidak ada yang peduli dengan keraguanmu.
Wanda menguap, lalu pergi dengan megah diiringi para pelayan.]]
  },
  AvgDialog_25189_Content_76 = {
    Text = "Melihat wajahmu yang kebingungan, dayang di sampingmu tak tahan untuk memutar matanya."
  },
  AvgDialog_25189_Content_77 = {
    Text = "Masa ini saja tidak tahu? Kau diminta menemani tidur malam ini. Ini kesempatan yang diimpikan banyak orang…"
  },
  AvgDialog_25189_Content_78 = {
    Text = "<Shake:Menemani tidur?!>"
  },
  AvgDialog_25189_Content_79 = {
    Text = "Pandanganmu menggelap, dan kau pingsan lagi."
  },
  AvgDialog_25189_Content_8 = {
    Text = "Ya, semua yang terlihat olehnya berada di bawah kekuasaannya, namun semuanya telah lama lenyap menjadi debu di alam semesta."
  },
  AvgDialog_25189_Content_9 = {
    Text = [[
Seorang ratu tanpa rakyat, masih bisakah disebut ratu?
Wanda pun tidak tahu.]]
  },
  AvgDialog_25190_Content_1 = {
    Text = "<Change>Auu auu……"
  },
  AvgDialog_25190_Content_10 = {
    Text = [[
<Yellow:Tanggal 17 malam pukul 9, di tempat biasa>@1berkumpul, membahas rencana besar.
Waspadai@1wanita@2Duri

Teman lamamu,
Guderian]]
  },
  AvgDialog_25190_Content_11 = {
    Text = "<Gray:Membahas rencana besar? Rencana besar apa?>"
  },
  AvgDialog_25190_Content_12 = {
    Text = "Peliharaan kecilku memberitahuku, sepertinya kau ini mata-mata. Seorang biarawan yang ditugaskan oleh paroki, tapi bahkan tidak bisa mengingat ayat-ayat dasar kitab suci."
  },
  AvgDialog_25190_Content_13 = {
    Text = "Jangan-jangan pelayan pria itu benar, aku memang seorang mata-mata?"
  },
  AvgDialog_25190_Content_14 = {
    Text = "Informasi sepenting ini sama sekali tidak tertangkap dalam ingatannya… Sepertinya dia memang sudah disiksa sampai kehilangan kesadaran."
  },
  AvgDialog_25190_Content_15 = {
    Text = "Kau menyimpan kertas itu, pikiranmu berkecamuk."
  },
  AvgDialog_25190_Content_16 = {
    Text = "Bengong untuk apa? Nyonya tidak punya banyak kesabaran, orang terakhir yang terlambat sekarang sudah dikurung di penjara selama dua tahun."
  },
  AvgDialog_25190_Content_17 = {Text = "……Hei."},
  AvgDialog_25190_Content_18 = {
    Text = "Kau diam-diam mendekati pelayan wanita itu, berusaha merendahkan suaramu sepelan mungkin."
  },
  AvgDialog_25190_Content_19 = {
    Text = "<SmallShake:Kau juga orang dalam dari Comte Guderian?>"
  },
  AvgDialog_25190_Content_2 = {
    Text = "Kau dengan mudah mengusir monster-monster yang menyerang."
  },
  AvgDialog_25190_Content_20 = {
    Text = "Uhuk uhuk! Bisik-bisik apa, cepat jalan!"
  },
  AvgDialog_25190_Content_21 = {
    Text = "Pelayan wanita itu terus menggerutu, namun sudut matanya tak henti-hentinya melirik ke arahmu, wajahnya dipenuhi antusiasme dan isyarat."
  },
  AvgDialog_25190_Content_22 = {
    Text = "<Gray:Nona, Anda terlalu mencolok dalam bertindak.>"
  },
  AvgDialog_25190_Content_23 = {
    Text = "Apa yang harus dilakukan selanjutnya? Menyelesaikan rencana pemilik sebelumnya, atau menyerahkan diri kepada Wanda?"
  },
  AvgDialog_25190_Content_24 = {
    Text = "<Gray:Sejujurnya, aku cukup penasaran apa sebenarnya rencana sang Count itu…>"
  },
  AvgDialog_25190_Content_3 = {
    Text = "<Gray:Cairan Erosi sudah menyebar sampai ke dalam kastil, mungkinkah Wanda tidak mengetahuinya?>"
  },
  AvgDialog_25190_Content_4 = {
    Text = "Sudah kuduga, dia memang <Blue:\"Tuan itu\"> yang disebut Tuan Comte."
  },
  AvgDialog_25190_Content_5 = {
    Text = "Kalau memang dia, pasti bisa……"
  },
  AvgDialog_25190_Content_6 = {
    Text = "Secarik kertas tiba-tiba diselipkan ke tanganmu."
  },
  AvgDialog_25190_Content_7 = {
    Text = "Kau mendongak, pelayan wanita yang tadi meringkuk di belakangmu sudah menegakkan punggungnya, kembali ke sikap angkuh dan dinginnya."
  },
  AvgDialog_25190_Content_8 = {Text = "?"},
  AvgDialog_25190_Content_9 = {
    Text = "Kau membuka kertas itu, di atasnya tertulis sederet sandi dengan tulisan yang tidak rapi. Berbekal ingatan Vien, kau dengan susah payah menerjemahkan isinya."
  },
  AvgDialog_25191_Content_1 = {
    Text = "Malam Kematian, Mead, dan Nyanyian"
  },
  AvgDialog_25191_Content_10 = {
    Text = "Apa yang sebenarnya dipikirkan wanita itu, tak ada yang bisa menebak. Tapi—"
  },
  AvgDialog_25191_Content_11 = {
    Text = "Wabah di Cambrian sudah tak tertolong lagi. Jika kita membiarkan para yang terinfeksi keluar, entah apa yang akan terjadi."
  },
  AvgDialog_25191_Content_12 = {
    Text = "Terlepas dari apakah ini memang niat Wanda atau bukan, tindakannya ini memang telah menyelamatkan tanah-tanah feodal di sekitarnya…"
  },
  AvgDialog_25191_Content_13 = {
    Text = [[
Kastil Cambrian
Aula Perjamuan]]
  },
  AvgDialog_25191_Content_14 = {
    Text = "Kau mendorong pintu kayu besar aula yang berat."
  },
  AvgDialog_25191_Content_15 = {
    Text = "Cahaya gemerlap bagaikan bintang-bintang yang jatuh ke dunia, aroma manis anggur merah dan hidangan lezat mengambang di seluruh aula."
  },
  AvgDialog_25191_Content_16 = {
    Text = "Para penduduk desa Cambrian mengenakan pakaian terbaik mereka, menari dengan riang mengikuti irama musik."
  },
  AvgDialog_25191_Content_17 = {
    Text = "Meskipun di luar sudah lama tenggelam oleh Korosi, suasana di dalam aula tetap dipenuhi keceriaan."
  },
  AvgDialog_25191_Content_18 = {
    Text = "Jadi ini puding apel yang legendaris itu? Seumur hidup aku belum pernah makan sesuatu yang seenak ini……"
  },
  AvgDialog_25191_Content_19 = {
    Text = "Hahahaha, aku senang sekali! Mati pun tak apa!"
  },
  AvgDialog_25191_Content_2 = {
    Text = [[
Tanah Feodal Guderian
Area Perburuan]]
  },
  AvgDialog_25191_Content_20 = {
    Text = "Menari, ayo menari bersama!"
  },
  AvgDialog_25191_Content_21 = {
    Text = "Kau menyibak kerumunan orang yang ramai dan melihat Wanda yang duduk di ujung sana."
  },
  AvgDialog_25191_Content_23 = {
    Text = "Dia bersandar malas di tubuh para pelayannya, anggur merah di gelasnya berkilauan bagai permata."
  },
  AvgDialog_25191_Content_24 = {
    Text = "Selamat malam, Tuan Biarawan. Kukira kau tak sudi ikut pesta liar kami yang konyol ini."
  },
  AvgDialog_25191_Content_25 = {
    Text = "Sesekali aku juga ingin memuaskan rasa penasaranku."
  },
  AvgDialog_25191_Content_26 = {
    Text = "<Gray:Lagipula, di luar sana penuh dengan Cairan Erosi, memangnya aku bisa pergi ke mana……>"
  },
  AvgDialog_25191_Content_27 = {
    Text = "Ujung bajumu ditarik pelan oleh seseorang."
  },
  AvgDialog_25191_Content_28 = {
    Text = "Kau adalah……adiknya Susanna!"
  },
  AvgDialog_25191_Content_29 = {
    Text = "Aku juga punya nama, lho. Semua orang memanggilku Beckman Kecil."
  },
  AvgDialog_25191_Content_3 = {
    Text = "Apa? Kau bilang Wanda melelehkan semua kunci pintu dan menyeret seluruh penduduk desa Cambrian untuk mengadakan pesta dansa di dalam kastil?"
  },
  AvgDialog_25191_Content_30 = {
    Text = "Selamat malam, Beckman Kecil. Ke mana kakakmu pergi?"
  },
  AvgDialog_25191_Content_31 = {
    Text = "Kakak pergi bersama orang-orang lain yang tidak sakit……"
  },
  AvgDialog_25191_Content_32 = {
    Text = "Beckman Kecil menundukkan kepalanya dengan murung. Dia mengusap hidungnya, lalu mendongak menatapmu dengan mata bulatnya yang besar."
  },
  AvgDialog_25191_Content_33 = {
    Text = "Kakak Biarawan, mau menari bersama? Beckman Kecil tidak punya pasangan dansa, huhu……"
  },
  AvgDialog_25191_Content_34 = {
    Text = "Nak, seorang biarawan tidak boleh menari."
  },
  AvgDialog_25191_Content_35 = {
    Text = "Sekarang aku nyatakan kau boleh menari. Jangan pedulikan aturan-aturan kuno itu."
  },
  AvgDialog_25191_Content_36 = {
    Text = "Di Cambrian, aku — <Big:adalah hukum!>"
  },
  AvgDialog_25191_Content_37 = {
    Text = "Kau menatap mata besar Beckman Kecil yang penuh harapan, dan diam-diam menelan kata-kata penolakanmu."
  },
  AvgDialog_25191_Content_38 = {
    Text = "Maaf, aku tidak pernah belajar menari, tapi aku bisa menemanimu berputar beberapa kali."
  },
  AvgDialog_25191_Content_39 = {
    Text = "Kamu menggandeng tangan Beckmann kecil dan berjalan ke tengah aula. Di sana, para penduduk desa sedang menari mengikuti alunan musik."
  },
  AvgDialog_25191_Content_4 = {
    Text = "Be-benar adanya! Kudengar orang-orang yang tidak terinfeksi sudah pergi, dan yang tersisa di pesta dansa hanyalah mereka yang sudah sakit parah."
  },
  AvgDialog_25191_Content_40 = {
    Text = "Rok-rok panjang berkibar ringan mengikuti musik, bagaikan kue-kue kecil warna-warni yang berputar tanpa henti."
  },
  AvgDialog_25191_Content_41 = {
    Text = "Kamu mengarungi lautan emas yang dirajut oleh cahaya dan musik, akhirnya tenggelam sepenuhnya dalam gelembung-gelembung kegembiraan yang terus bermunculan dari segala penjuru."
  },
  AvgDialog_25191_Content_42 = {
    Text = "Kemampuan menari Beckmann kecil jelas tidak jauh lebih baik darimu. Dia bergoyang-goyang tanpa pola mengikuti irama musik, dan tak lama kemudian wajahnya sudah memerah."
  },
  AvgDialog_25191_Content_43 = {
    Text = "Hahaha, senangnya! Hari ini adalah hari paling bahagia Beckmann kecil!"
  },
  AvgDialog_25191_Content_44 = {
    Text = "Kak Biarawan, pegang tanganku, ayo kita berputar-putar bersama!"
  },
  AvgDialog_25191_Content_45 = {
    Text = "Lebih cepat!"
  },
  AvgDialog_25191_Content_46 = {
    Text = "<BigShake:Lebih cepat lagi!>"
  },
  AvgDialog_25191_Content_47 = {
    Text = "<Red:Lebih cepat lagi…>"
  },
  AvgDialog_25191_Content_48 = {Text = "Cep@2…"},
  AvgDialog_25191_Content_49 = {
    Text = "Beckmann kecil, wajahmu kenapa……?!"
  },
  AvgDialog_25191_Content_5 = {
    Text = "Hahahaha! Aku sudah susah payah menempatkan mata-mata di sisinya, ternyata itu tidak perlu."
  },
  AvgDialog_25191_Content_50 = {
    Text = "<Change>Menari, temani aku…"
  },
  AvgDialog_25191_Content_51 = {
    Text = "Dari mata anak laki-laki itu terus mengalir cairan erosi hitam pekat, dia tersenyum sambil mengulurkan tangan ke arahmu."
  },
  AvgDialog_25191_Content_52 = {
    Text = "Ujung hidungmu tiba-tiba merasakan dingin. Kamu mendongak, cairan hitam lengket menetes perlahan dari lampu kristal."
  },
  AvgDialog_25191_Content_53 = {
    Text = "Satu tetes, dua tetes…"
  },
  AvgDialog_25191_Content_54 = {
    Text = "Kamu memandang sekeliling dengan panik, baru menyadari bahwa pakaian, lengan, bahkan wajah banyak orang sudah mengalami pembusukan dalam berbagai tingkat."
  },
  AvgDialog_25191_Content_55 = {
    Text = "Tapi mereka tetap menari dengan gembira."
  },
  AvgDialog_25191_Content_56 = {
    Text = "Kak Biarawan, kenapa kamu mengabaikanku… Kamu tidak suka Beckmann kecil lagi ya…"
  },
  AvgDialog_25191_Content_57 = {
    Text = "Anak laki-laki itu mengulurkan kedua tangan lengketnya dan memelukmu, kesedihan meluap dari rongga matanya yang kosong."
  },
  AvgDialog_25191_Content_58 = {
    Text = "Temani aku… Temani aku…"
  },
  AvgDialog_25191_Content_6 = {
    Text = "Wabah semengerikan itu, dia bukan hanya tidak berniat pergi, malah mengunci semua orang di dalam untuk menunggu ajal…"
  },
  AvgDialog_25191_Content_7 = {
    Text = "Apakah benar seperti rumor yang beredar, dia sudah benar-benar gila?"
  },
  AvgDialog_25191_Content_8 = {
    Text = "Ucapanmu sungguh menarik. Memangnya dulu dia pernah menjadi wanita yang waras?"
  },
  AvgDialog_25191_Content_9 = {
    Text = "Eh… itu…"
  },
  AvgDialog_25199_Content_1 = {
    Text = "Kau akhirnya berhasil melepaskan diri dari gangguan Beckmann kecil, namun penduduk desa yang terus berdatangan mengalami perubahan aneh."
  },
  AvgDialog_25199_Content_10 = {
    Text = "Jika kita ditakdirkan untuk menyambut kematian, mengapa kita tidak bisa pergi dengan bahagia?"
  },
  AvgDialog_25199_Content_11 = {
    Text = "Atau, haruskah kami meringkuk di tempat tidur menangis sendirian, memenuhi semua imajinasimu tentang orang yang akan mati?"
  },
  AvgDialog_25199_Content_12 = {
    Text = "Sudah kubilang, di Cambrian, akulah satu-satunya hukum."
  },
  AvgDialog_25199_Content_13 = {
    Text = [[
Sekarang sang ratu memerintahkan, menari, terus menari!
Dulu, sekarang, dan masa depan, kami tidak akan pernah takut pada kematian.]]
  },
  AvgDialog_25199_Content_14 = {
    Text = "Seiring perintah Wanda—"
  },
  AvgDialog_25199_Content_16 = {
    Text = "Suasana aula mencapai puncaknya."
  },
  AvgDialog_25199_Content_17 = {
    Text = "<Change>Menari, menari…"
  },
  AvgDialog_25199_Content_19 = {
    Text = "Gila… semuanya sudah gila…"
  },
  AvgDialog_25199_Content_2 = {
    Text = "Aula perjamuan berubah menjadi kuburan raksasa, cairan korosi yang terus meluap bagaikan kutu-kutu yang berkerumun di balik jubah mewah."
  },
  AvgDialog_25199_Content_20 = {
    Text = "Kau memandang dengan linglung semua yang terjadi di hadapanmu. Bahkan dalam mimpi terliar sekalipun, kau tidak pernah melihat pemandangan seaneh dan seabsurd ini."
  },
  AvgDialog_25199_Content_21 = {
    Text = "Semua orang sudah gila. Semua orang penuh luka."
  },
  AvgDialog_25199_Content_22 = {
    Text = "Tapi semua orang tampak bahagia."
  },
  AvgDialog_25199_Content_24 = {
    Text = "Aku pernah mendengar orang berkata: mereka yang tak bisa mendengar musik, menganggap mereka yang menari adalah orang gila."
  },
  AvgDialog_25199_Content_25 = {
    Text = "Kau menarik kerah bajumu, lalu merosot duduk di tanah dengan lelah."
  },
  AvgDialog_25199_Content_26 = {
    Text = "Kalau dipikir-pikir, cukup menarik juga. Aku pernah bersumpah di makam Misage bahwa aku tak gentar menghadapi hidup dan mati, tapi aku tak pernah benar-benar siap menghadapi kematian."
  },
  AvgDialog_25199_Content_27 = {
    Text = "Kalian memberiku inspirasi baru — meskipun aku berharap diriku tak pernah harus menghadapi dilema seperti ini."
  },
  AvgDialog_25199_Content_28 = {
    Text = "Kau mengangkat gelas anggur di sampingmu, bersulang dari kejauhan dengan Wanda melewati cairan hitam pekat, percikan anggur merah, dan bunga-bunga yang berterbangan."
  },
  AvgDialog_25199_Content_29 = {
    Text = "Untuk keberanian."
  },
  AvgDialog_25199_Content_3 = {
    Text = "Tidak bisa, orang yang bermutasi terlalu banyak…"
  },
  AvgDialog_25199_Content_30 = {
    Text = "Wanda tertawa terbahak-bahak, mengangkat gelasnya dan mengayunkannya ke arahmu."
  },
  AvgDialog_25199_Content_31 = {
    Text = "Untuk kematian. Kematian kita yang paling megah dan paling manis."
  },
  AvgDialog_25199_Content_32 = {
    Text = "Aroma manis mayat membusuk tercium di ujung hidungmu, kau mendengar ratapan, tangisan, dan tawa dari tak terhitung banyaknya orang."
  },
  AvgDialog_25199_Content_33 = {
    Text = "Namun mereka tak pernah menghentikan langkah tarian mereka."
  },
  AvgDialog_25199_Content_34 = {
    Text = "Sang Ratu tak pernah meninggalkan rakyatnya. Segera, mereka akan bersama-sama menuju perjamuan kematian yang megah ini."
  },
  AvgDialog_25199_Content_36 = {
    Text = "Kali ini, akhirnya dia tidak sendirian lagi."
  },
  AvgDialog_25199_Content_37 = {
    Text = "Sekarang, masih bisakah kau mengingat ayat itu? Yang kau lantunkan di gerbang kota?"
  },
  AvgDialog_25199_Content_38 = {
    Text = "……Ingat."
  },
  AvgDialog_25199_Content_39 = {
    Text = "<Red:Mereka yang menyerahkan diri pada percabulan, menuruti hawa nafsu, akan menerima hukuman api kekal, sebagai peringatan.>"
  },
  AvgDialog_25199_Content_4 = {
    Text = "Secara refleks kau menoleh ke arah Wanda."
  },
  AvgDialog_25199_Content_40 = {
    Text = "Kalau begitu, sudah siapkah kau? Menerima hukuman api kekal."
  },
  AvgDialog_25199_Content_41 = {
    Text = "Dalam kegelapan, kau hanya mendengar suara tawa yang jauh."
  },
  AvgDialog_25199_Content_42 = {
    Text = "Mereka bagaikan pecahan meteor yang jatuh ke danau, perlahan tenggelam ke kedalaman kesadaranmu."
  },
  AvgDialog_25199_Content_43 = {
    Text = "Hingga akhirnya kau tak bisa mendengar apa pun lagi."
  },
  AvgDialog_25199_Content_5 = {
    Text = "Di balik kerumunan yang riuh, Wanda tersenyum dan mengangkat gelasnya ke arahmu sebagai salam."
  },
  AvgDialog_25199_Content_6 = {
    Text = "Sudah ketakutan begitu, biarawan kecil?"
  },
  AvgDialog_25199_Content_7 = {
    Text = "Aku tidak mengerti. Kau hanya diam melihat semua orang menjadi gila lalu mati begitu saja?"
  },
  AvgDialog_25199_Content_8 = {
    Text = "Wanda tertawa terbahak-bahak, air mata hitam mengalir dari sudut matanya — tubuhnya juga dipenuhi luka akibat korosi."
  },
  AvgDialog_25199_Content_9 = {
    Text = "Tidak ada yang abadi, biarawan kecil, termasuk dewa yang kau hormati sekalipun."
  },
  AvgDialog_34830_Content_1 = {
    Text = "Peniup Seruling"
  },
  AvgDialog_34830_Content_10 = {
    Text = "Jangan takut, aku akan mencari cara untuk membawa kalian pergi."
  },
  AvgDialog_34830_Content_11 = {
    Text = "Para penduduk desa hanya menatapmu dalam diam, tanpa harapan maupun permusuhan di mata mereka."
  },
  AvgDialog_34830_Content_12 = {
    Text = "Oh iya, pelayan wanita itu……"
  },
  AvgDialog_34830_Content_13 = {
    Text = "Ayah dan adikku dikurung Di Bawah. Aku harus menyelamatkan mereka—"
  },
  AvgDialog_34830_Content_14 = {
    Text = "Permisi, apakah kalian mengenal seorang pelayan bernama Susanna?"
  },
  AvgDialog_34830_Content_15 = {
    Text = "Susanna, itu kakak perempuanku!"
  },
  AvgDialog_34830_Content_16 = {
    Text = "Suara anak yang renyah terdengar dari sudut ruangan."
  },
  AvgDialog_34830_Content_17 = {
    Text = "Dengan cahaya lilin yang redup, barulah kamu menyadari seorang pria tua yang terbaring di sudut dan seorang anak laki-laki bermata bulat di sampingnya."
  },
  AvgDialog_34830_Content_18 = {
    Text = "Susanna adalah putriku…… Ada apa dengannya?"
  },
  AvgDialog_34830_Content_19 = {
    Text = "Dia sangat mengkhawatirkan keselamatan kalian dan ingin menyelamatkan kalian dari sini."
  },
  AvgDialog_34830_Content_2 = {
    Text = [[
Kastil Cambrian
Penjara Bawah Tanah]]
  },
  AvgDialog_34830_Content_20 = {
    Text = "Kami tidak bisa meninggalkan tempat ini……"
  },
  AvgDialog_34830_Content_21 = {
    Text = "Si tua menggelengkan kepalanya. Tubuhnya dipenuhi dengan lubang-lubang pelarutan besar dan kecil, dan cairan kental yang keluar dari lubang-lubang itu telah lama menghitamkan jerami di bawahnya."
  },
  AvgDialog_34830_Content_22 = {
    Text = "Kami tinggal di sini atas kemauan sendiri. Setelah terjangkit penyakit, orang bisa menjadi gila, bahkan berubah menjadi monster."
  },
  AvgDialog_34830_Content_23 = {
    Text = "Benar, sudah banyak kasus pembunuhan terjadi di sekitar sini…… Kemudian Nyonya membawa orang-orangnya memeriksa dari rumah ke rumah, dan mengurung semua yang sakit di sini."
  },
  AvgDialog_34830_Content_24 = {
    Text = "Kalau tidak mau dikurung, maka harus pergi dari wilayah feodal ini dan bersumpah untuk tidak pernah kembali."
  },
  AvgDialog_34830_Content_25 = {
    Text = "Di sini setiap hari bisa minum bubur dan makan roti yang manis lho!"
  },
  AvgDialog_34830_Content_26 = {
    Text = "<Gray:Ternyata begitu. Jangan-jangan kita salah paham tentang dia?>"
  },
  AvgDialog_34830_Content_27 = {
    Text = "Apakah Nyonya Wanda baik kepada kalian sejak datang ke wilayah feodal ini?"
  },
  AvgDialog_34830_Content_28 = {
    Text = "Baik? Aku tidak tahu. Aku bahkan belum pernah melihatnya, hanya mendengar bahwa dia sangat kejam, membawa kematian bagi empat suaminya, dan merupakan penjelmaan iblis."
  },
  AvgDialog_34830_Content_29 = {
    Text = "Tapi selama bertahun-tahun dia berada di wilayah feodal ini, dia sudah melakukan banyak hal baik, dan kehidupan kita memang jauh lebih baik dari sebelumnya."
  },
  AvgDialog_34830_Content_3 = {
    Text = "Pintu besi yang berat tertutup erat di belakangmu."
  },
  AvgDialog_34830_Content_30 = {
    Text = "Dia mengajari kami membuka lahan pertanian, menggembalakan domba, lalu setiap tahun saat festival, dia pergi ke pasar musim panas dengan membawa wol dan bisa mendapatkan banyak uang."
  },
  AvgDialog_34830_Content_31 = {
    Text = "Benar, pasar Shariqi itu juga direbut olehnya dari tangan Earl Goodrich, kedua belah pihak sudah berperang hampir setahun karenanya……"
  },
  AvgDialog_34830_Content_32 = {
    Text = "Para penduduk desa berebut menceritakan berbagai kisah tentang Wanda dalam mengelola wilayah feodal. Pertanian, peternakan, peleburan, pengelolaan manor……"
  },
  AvgDialog_34830_Content_33 = {
    Text = "Kamu terkejut dengan pemahaman mendalam Wanda terhadap berbagai urusan wilayah kekuasaannya. Dia sama sekali bukan tuan tanah yang hanya tenggelam dalam kesenangan."
  },
  AvgDialog_34830_Content_34 = {
    Text = "Seorang penguasa yang cukup baik, sayang harus menghadapi Erosi."
  },
  AvgDialog_34830_Content_35 = {
    Text = "<Gray:Penyebaran sebesar ini, di sekitar sini mungkin ada celah Erosi…>"
  },
  AvgDialog_34830_Content_36 = {
    Text = "Pintu besi di belakang tiba-tiba terbuka."
  },
  AvgDialog_34830_Content_37 = {
    Text = "Kamu berbalik, dan entah sejak kapan Wanda sudah berdiri di luar pintu penjara. Cahaya lilin di koridor terhalang oleh tubuhnya yang tinggi, memberikan siluetnya sebuah lapisan cahaya oranye yang hangat."
  },
  AvgDialog_34830_Content_38 = {
    Text = "Lepaskan orang ini, aku ada sesuatu untuk {Male=dia,Female=dia} bicarakan secara pribadi."
  },
  AvgDialog_34830_Content_39 = {
    Text = [[
Kastil Cambrian
Taman]]
  },
  AvgDialog_34830_Content_4 = {
    Text = "Kamu berbalik dan tanpa sengaja melihat sepasang mata yang berkilauan, mengelilingimu seperti binatang buas di tengah bayangan gelap."
  },
  AvgDialog_34830_Content_40 = {
    Text = "Kalian berjalan bersama di atas rumput yang lembut, hingga sampai di tepi danau."
  },
  AvgDialog_34830_Content_41 = {
    Text = "Air danau di tengah malam bagaikan cermin gelap pekat, memantulkan samar-samar cahaya bulan yang terpecah di permukaannya."
  },
  AvgDialog_34830_Content_42 = {
    Text = "Saya pikir kamu seharusnya mengerti, sekarang Cambrian sedang mengalami bencana pelarutan yang sangat parah, dan saya tidak bisa berbuat apa-apa tentang itu."
  },
  AvgDialog_34830_Content_43 = {
    Text = "Sedangkan kamu, saat bertarung dengan monster-monster di kastil, kamu terlihat sangat mahir, seolah-olah ini adalah pekerjaanmu sehari-hari."
  },
  AvgDialog_34830_Content_44 = {
    Text = "<Gray:Memang benar ini adalah pekerjaan profesional saya…>"
  },
  AvgDialog_34830_Content_45 = {
    Text = "Bukankah Nyonya saat itu berada di kamar tidur? Bagaimana bisa tahu sedetail itu?"
  },
  AvgDialog_34830_Content_46 = {
    Text = "Mata dan telingaku tersebar di seluruh Cambrian. Bunga freesia di sini pun harus mendapat izinku untuk mekar. Tidak ada hal yang tidak kuketahui."
  },
  AvgDialog_34830_Content_47 = {
    Text = "Lalu bagaimana dengan pelayan itu? Sudah tahu dia mata-mata, kenapa masih dibiarkan?"
  },
  AvgDialog_34830_Content_48 = {
    Text = "Wanda melambaikan tangannya dengan acuh tak acuh."
  },
  AvgDialog_34830_Content_49 = {
    Text = "Dia hanyalah manusia biasa yang malang, tidak bisa menyentuh sehelai rambutku pun."
  },
  AvgDialog_34830_Content_5 = {
    Text = "<Shake:Uwaaah!!>"
  },
  AvgDialog_34830_Content_50 = {
    Text = "Lagipula dia melayaniku dengan cukup nyaman. Menemukan pelayan manusia yang memuaskan bukanlah hal yang mudah."
  },
  AvgDialog_34830_Content_51 = {
    Text = "Singkatnya, aku ingin kamu membantuku mengatasi Erosi. Jangan buru-buru menolak—soal harga dan semacamnya bisa dibicarakan, apa pun yang kamu inginkan akan kuusahakan untuk dipenuhi."
  },
  AvgDialog_34830_Content_52 = {
    Text = "Kamu juga tidak tega melihat para penduduk desa mati sia-sia, bukan, \"Tuan Biarawan\" yang terhormat?"
  },
  AvgDialog_34830_Content_54 = {
    Text = "Terakhir kali di istana, Anda pernah menyebutkan \"kalian manusia\", dan mengingat kemampuan khusus yang Anda gunakan... Nyonya Wanda, Anda sebenarnya bukan manusia, kan?"
  },
  AvgDialog_34830_Content_55 = {
    Text = "Keberadaan dari tempat yang jauh, kuat dan kejam, namun peduli terhadap hidup dan mati para penduduk desa. Apa tujuan sebenarnya dari Nyonya ini?"
  },
  AvgDialog_34830_Content_56 = {
    Text = "Menghadapi pertanyaan tajammu, Wanda mengangkat alisnya, lalu tiba-tiba tertawa terbahak-bahak."
  },
  AvgDialog_34830_Content_57 = {
    Text = "Apakah yang baru saya katakan itu lucu?"
  },
  AvgDialog_34830_Content_58 = {
    Text = "Tidak… Hahahahaha! Aku hanya terlalu senang. Bertahun-tahun di sini, akhirnya aku bertemu seseorang yang sama-sama bukan berasal dari \"sini\"."
  },
  AvgDialog_34830_Content_59 = {
    Text = "Bagaimana kau tahu—"
  },
  AvgDialog_34830_Content_6 = {
    Text = "Setelah penglihatanmu beradaptasi, barulah kau bisa melihat jelas pemandangan di hadapanmu."
  },
  AvgDialog_34830_Content_60 = {
    Text = "Wanda mengulurkan jari telunjuknya dan menyentuh bibirmu dengan lembut."
  },
  AvgDialog_34830_Content_61 = {
    Text = "Sst… Ikut aku, ada sesuatu yang ingin kutunjukkan."
  },
  AvgDialog_34830_Content_62 = {
    Text = "Tahukah kamu? Dari pantulan danau ini, aku bisa melihat kota tempat aku tinggal dulu."
  },
  AvgDialog_34830_Content_63 = {
    Text = "Kalian semakin dekat dengan danau. Air danau yang berwarna biru kehitaman hampir tidak terlihat dasarnya, di dalamnya samar-samar terlihat rumput air dan batu hitam besar yang kabur."
  },
  AvgDialog_34830_Content_64 = {
    Text = "Cahaya bulan menerangi dasar danau yang dalam dan gelap, akhirnya kamu bisa membedakan menara spiral hitam di atas batu serta dinding dengan sudut tumpul."
  },
  AvgDialog_34830_Content_65 = {
    Text = "Di dalam air... ada sebuah kota?!"
  },
  AvgDialog_34830_Content_66 = {
    Text = "Saat itu, aku memiliki istana yang sangat besar. Pelayan yang melayani aku saja berjumlah ribuan orang."
  },
  AvgDialog_34830_Content_67 = {
    Text = "Seperti yang kau katakan, aku tak pernah peduli dengan hidup atau matinya para pelayanku."
  },
  AvgDialog_34830_Content_68 = {
    Text = "Aku selalu bertindak sesuka hati. Para pelayanku, bahkan seluruh kota, adalah perpanjangan dari hasrat dan ambisiku."
  },
  AvgDialog_34830_Content_69 = {
    Text = "Kemudian planetku mengalami bencana yang kalian sebut \"Erosi\", dan semua orang mati."
  },
  AvgDialog_34830_Content_7 = {
    Text = "Ada yang duduk, ada yang berbaring, ada yang bersandar di dinding…… semuanya penduduk desa berpakaian compang-camping."
  },
  AvgDialog_34830_Content_70 = {
    Text = "Aku duduk sendirian di aula untuk waktu yang sangat, sangat lama, menyaksikan istanaku, ibu kotaku, segalanya berubah menjadi reruntuhan."
  },
  AvgDialog_34830_Content_71 = {
    Text = "Sejujurnya, perasaan itu sangat buruk. Tidak ada yang mau mengalaminya untuk kedua kalinya."
  },
  AvgDialog_34830_Content_72 = {
    Text = "Nyonya Wanda…"
  },
  AvgDialog_34830_Content_73 = {
    Text = "Maaf, kali ini saya tidak bisa membantu. Menutup D-rongga adalah hal yang sangat rumit, sepertinya mustahil dilakukan sendirian."
  },
  AvgDialog_34830_Content_74 = {
    Text = "Tidak perlu khawatir, ceritakan kegelisahanmu, aku akan memberikan segala bantuan yang kau butuhkan."
  },
  AvgDialog_34830_Content_75 = {
    Text = "Kau menggelengkan kepala."
  },
  AvgDialog_34830_Content_76 = {
    Text = "Bukan hanya itu… Lingkungan tempat kita berada sekarang juga memiliki beberapa, ehm, keistimewaan…"
  },
  AvgDialog_34830_Content_77 = {
    Text = "Selama periode memasuki mimpi, kamu tidak dapat menyelesaikan operasi rumit seperti menutup celah."
  },
  AvgDialog_34830_Content_78 = {
    Text = "<Gray:Bagaimana caranya menjelaskan hal ini kepada Nyonya Wanda…>"
  },
  AvgDialog_34830_Content_79 = {
    Text = "Karena kita sekarang berada di dalam mimpi, jadi Anda tidak bisa membantuku, benar?"
  },
  AvgDialog_34830_Content_8 = {
    Text = "Tubuh mereka semua dipenuhi luka erosi besar dan kecil, ada yang tubuhnya sudah terkorosi sebagian besar, udara dipenuhi aroma penyakit dan kematian."
  },
  AvgDialog_34830_Content_80 = {Text = "?!"},
  AvgDialog_34830_Content_81 = {
    Text = "Anda sudah menyadarinya?"
  },
  AvgDialog_34830_Content_82 = {
    Text = "Wanda menunduk menatap kota hitam di dalam air, matanya berkilauan memantulkan cahaya bulan putih yang lembut."
  },
  AvgDialog_34830_Content_83 = {
    Text = "Sejak tiba di sini, aku sudah bermimpi banyak kali. Tentang perang, bencana, waktu… Tapi tak sekalipun aku memimpikan ibu kotaku."
  },
  AvgDialog_34830_Content_84 = {
    Text = "Tepat saat aku hampir melupakannya, aku bertemu denganmu, lalu melihatnya lagi di dasar danau."
  },
  AvgDialog_34830_Content_85 = {
    Text = "Kau tahu? Ketika seseorang yang akan mati melihat peniup seruling berjalan menembus kabut, dia tidak akan takut, juga tidak akan penasaran."
  },
  AvgDialog_34830_Content_86 = {
    Text = "Dia hanya akan diam-diam mengikuti sang peniup seruling, menuju tempat yang menjadi miliknya."
  },
  AvgDialog_34830_Content_87 = {
    Text = "Wanda menghela napas dengan lemas."
  },
  AvgDialog_34830_Content_88 = {
    Text = "Ibu kotaku yang telah tiada itu… indahnya bagaikan mimpi orang yang akan mati."
  },
  AvgDialog_34830_Content_89 = {
    Text = "Dia lembut membelai pelayan buta yang diam membisu di sampingnya."
  },
  AvgDialog_34830_Content_9 = {
    Text = "Wanda ternyata mengurung kalian di sini……"
  },
  AvgDialog_34830_Content_90 = {
    Text = "<Change>Nyonya…"
  },
  AvgDialog_34830_Content_91 = {
    Text = "Cambrian adalah kampung halaman keduaku. Waktu kebersamaan kami tidak lama, tak kusangka sudah tiba saatnya untuk berpisah lagi."
  },
  AvgDialog_34830_Content_92 = {
    Text = "Maafkan aku, Nyonya Wanda…"
  },
  AvgDialog_34830_Content_93 = {
    Text = "Wanda melambaikan tangan padamu. Saat mengangkat kepalanya kembali, awan mendung di wajahnya sudah lenyap sepenuhnya."
  },
  AvgDialog_34830_Content_94 = {
    Text = "Tenang saja. Karena sudah menjadi penguasa wilayah ini, aku harus bertanggung jawab kepada semua orang."
  },
  AvgDialog_34830_Content_95 = {
    Text = "Bukankah ini hanya soal mati bersama? Kalau begitu, mari kita mati dengan gagah berani bersama-sama."
  },
  AvgDialog_34830_Content_96 = {
    Text = "Apa yang kau rencanakan?"
  },
  AvgDialog_34830_Content_97 = {
    Text = "Wanda menunjukkan senyum penuh misteri dan mengedipkan mata padamu."
  },
  AvgDialog_34830_Content_98 = {
    Text = "Sebuah pesta perpisahan yang megah."
  },
  AvgDialog_34831_Content_1 = {
    Text = "Kau akhirnya berhasil melepaskan diri dari gangguan Beckmann kecil, namun penduduk desa yang terus berdatangan mengalami perubahan aneh."
  },
  AvgDialog_34831_Content_10 = {
    Text = "Jika kita ditakdirkan untuk menyambut kematian, mengapa kita tidak bisa pergi dengan bahagia?"
  },
  AvgDialog_34831_Content_11 = {
    Text = "Atau haruskah kita meringkuk di tempat tidur sendiri, menangis dalam kesendirian, memenuhi semua bayanganmu tentang orang yang akan mati?"
  },
  AvgDialog_34831_Content_12 = {
    Text = "Sudah kubilang, di Cambrian, akulah satu-satunya hukum."
  },
  AvgDialog_34831_Content_13 = {
    Text = "Sekarang Ratu memerintahkan, \"Menari, terus menari!\" Masa lalu, sekarang, dan masa depan, kita tidak akan pernah takut mati."
  },
  AvgDialog_34831_Content_14 = {
    Text = "Seiring perintah Wanda—"
  },
  AvgDialog_34831_Content_16 = {
    Text = "Suasana aula mencapai puncaknya."
  },
  AvgDialog_34831_Content_17 = {
    Text = "<Change>Menari, menari…"
  },
  AvgDialog_34831_Content_19 = {
    Text = "Gila… semuanya sudah gila…"
  },
  AvgDialog_34831_Content_2 = {
    Text = "Aula perjamuan yang sebelumnya penuh kegembiraan berubah menjadi kuburan raksasa, dengan D-lendir yang terus meluap seperti kutu-kutu yang memenuhi jubah megah."
  },
  AvgDialog_34831_Content_20 = {
    Text = "Kau memandang dengan linglung semua yang terjadi di hadapanmu. Bahkan dalam mimpi terliar sekalipun, kau tidak pernah melihat pemandangan seaneh dan seabsurd ini."
  },
  AvgDialog_34831_Content_21 = {
    Text = "Semua orang sudah gila. Semua orang penuh luka."
  },
  AvgDialog_34831_Content_22 = {
    Text = "Tapi semua orang tampak bahagia."
  },
  AvgDialog_34831_Content_24 = {
    Text = "Sudahlah, aku menyerah."
  },
  AvgDialog_34831_Content_25 = {
    Text = "Kau menarik kerah bajumu, lalu merosot duduk di tanah dengan lelah."
  },
  AvgDialog_34831_Content_26 = {
    Text = "Begitu ironis. Aku pernah bersumpah di depan makam Mythag untuk tidak takut mati, namun aku tak pernah benar-benar siap menghadapi kematian."
  },
  AvgDialog_34831_Content_27 = {
    Text = "Kamu telah memberi aku pelajaran, Wanda."
  },
  AvgDialog_34831_Content_28 = {
    Text = "Kau mengangkat gelas anggur di sampingmu, bersulang dari kejauhan dengan Wanda melewati cairan hitam pekat, percikan anggur merah, dan bunga-bunga yang berterbangan."
  },
  AvgDialog_34831_Content_29 = {
    Text = "——Untuk kematian termanis dan termegah kita."
  },
  AvgDialog_34831_Content_3 = {
    Text = "Tidak bisa, orang yang bermutasi terlalu banyak…"
  },
  AvgDialog_34831_Content_30 = {
    Text = "Ujung hidungmu mencium aroma manis dari mayat-mayat yang membusuk, dan kau mendengar tangisan pilu dari tak terhitung banyaknya orang."
  },
  AvgDialog_34831_Content_31 = {
    Text = "Namun mereka tak pernah menghentikan langkah tarian mereka."
  },
  AvgDialog_34831_Content_32 = {
    Text = "Sang Ratu tak pernah meninggalkan rakyatnya. Segera, mereka akan bersama-sama menuju perjamuan kematian yang megah ini."
  },
  AvgDialog_34831_Content_34 = {
    Text = "Kali ini, dia akhirnya tidak lagi sendirian."
  },
  AvgDialog_34831_Content_35 = {
    Text = "Sekarang, masih bisakah kau mengingat ayat itu? Yang kau lantunkan di gerbang kota?"
  },
  AvgDialog_34831_Content_37 = {
    Text = "<Red:Mereka yang menyerahkan diri pada percabulan, menuruti hawa nafsu, akan menerima hukuman api kekal, sebagai peringatan.>"
  },
  AvgDialog_34831_Content_38 = {
    Text = "Apakah kamu sudah siap?"
  },
  AvgDialog_34831_Content_39 = {
    Text = "Akan menerima hukuman api kekal."
  },
  AvgDialog_34831_Content_4 = {
    Text = "Secara refleks kau menoleh ke arah Wanda."
  },
  AvgDialog_34831_Content_41 = {
    Text = "Dalam kegelapan, kau hanya mendengar suara tawa yang jauh."
  },
  AvgDialog_34831_Content_42 = {
    Text = "Mereka bagaikan pecahan meteor yang jatuh ke danau, perlahan tenggelam ke kedalaman kesadaranmu."
  },
  AvgDialog_34831_Content_43 = {
    Text = "Hingga akhirnya kau tak bisa mendengar apa pun lagi."
  },
  AvgDialog_34831_Content_5 = {
    Text = "Di tengah keramaian orang-orang yang bersukacita, Wanda tersenyum dan mengangkat gelasnya untuk memberi hormat kepadamu."
  },
  AvgDialog_34831_Content_6 = {
    Text = "Sudah ketakutan begitu, biarawan kecil?"
  },
  AvgDialog_34831_Content_7 = {
    Text = "Aku tidak mengerti. Kau hanya diam melihat semua orang menjadi gila lalu mati begitu saja?"
  },
  AvgDialog_34831_Content_8 = {
    Text = "Wanda tertawa terbahak-bahak, sudut matanya mengalirkan air mata berwarna hitam. Baru pada saat itulah kamu menyadari bahwa tubuhnya juga dipenuhi luka akibat pelarutan."
  },
  AvgDialog_34831_Content_9 = {
    Text = "Tidak ada yang abadi, biarawan kecil, termasuk dewa yang kau hormati sekalipun."
  },
  AvgDialog_34965_Content_1 = {
    Text = "Setelah berhasil mengalahkan sekumpulan musuh yang datang mengikuti suara, kalian akhirnya mendapatkan sedikit ruang untuk bernapas."
  },
  AvgDialog_34965_Content_10 = {
    Text = "Cairan-cairan ini tidak bersifat korosif, namun untuk berjaga-jaga, tetap diperlukan beberapa tindakan pencegahan."
  },
  AvgDialog_34965_Content_11 = {
    Text = "Sebelum kamu sempat mencegahnya, Ramona merobek kain yang melilit tubuh Pelaut dan membuat jalinan di ujung senjata, lalu memasukkan senjata itu ke dalam rongga perut mayat Pelaut dan mengaduknya."
  },
  AvgDialog_34965_Content_12 = {
    Text = "...Apakah dia selalu seperti ini?"
  },
  AvgDialog_34965_Content_13 = {
    Text = "Jangan kaget, ini adalah manifestasi dari Roh akademik."
  },
  AvgDialog_34965_Content_14 = {
    Text = "Baiklah, aku sudah memutus pembuluh darah parasit yang melekat."
  },
  AvgDialog_34965_Content_15 = {
    Text = "Ujung pedang terangkat, parasit yang sudah sepenuhnya kehilangan tanda-tanda hidup jatuh berguling ke tanah. Air kotor yang keruh mengalir melalui celah-celah di geladak ke segala arah, dan sang kapten buru-buru menarik Celeste untuk berdiri di tempat lain."
  },
  AvgDialog_34965_Content_16 = {
    Text = "Parasit itu tampak seperti gumpalan kehidupan gelatin dengan tentakel. Saat diamati lebih cermat, terasa aura embrio mamalia pada tubuhnya. Bahkan hanya dengan mengamati dari balik kulit, seseorang dapat merasakan penghinaan yang sangat kuat."
  },
  AvgDialog_34965_Content_17 = {
    Text = "Ramona mengerutkan alisnya, menyimpan rapier-nya, lalu mengambil tombak panjang Pelaut yang tergeletak di tanah, dan dengan lembut merobek kulit gelatin parasit itu ——"
  },
  AvgDialog_34965_Content_18 = {
    Text = "Sejumlah besar cairan nanah hitam memancar keluar dengan cepat, membuat Murphy berteriak dan melompat beberapa langkah menjauh."
  },
  AvgDialog_34965_Content_19 = {
    Text = "Ada apa? Apakah ada sesuatu?"
  },
  AvgDialog_34965_Content_2 = {
    Text = "Kenapa perut Pelaut ini bisa sebesar ini?"
  },
  AvgDialog_34965_Content_20 = {
    Text = "Hitam! Cairan berwarna hitam! Apakah Kapten tidak bisa melihatnya?"
  },
  AvgDialog_34965_Content_21 = {
    Text = "Kamu dan Ramona saling bertatapan, yang muncul dari tubuh parasit itu tanpa diragukan lagi adalah \"teman baik\" kalian: D-lendir."
  },
  AvgDialog_34965_Content_22 = {
    Text = "Para pelaut sebelumnya tidak menunjukkan sedikit pun tanda-tanda terinfeksi parasit, setidaknya tidak sampai sebelum ledakan terjadi…"
  },
  AvgDialog_34965_Content_23 = {
    Text = "Sebelum ledakan... Sebelum ledakan... Sebelum Domain menghilang!"
  },
  AvgDialog_34965_Content_24 = {
    Text = [[
Domain menghilang?!
Celeste, apakah kamu sudah tidak mampu mempertahankan Domain?]]
  },
  AvgDialog_34965_Content_25 = {
    Text = "Setelah mendapatkan jawaban pasti dari kapten, Ramona menyatukan semua informasi."
  },
  AvgDialog_34965_Content_26 = {
    Text = "Dia menatap Murphy dengan serius, yang sedang menarik kapten untuk menghindari aliran D-lendir yang mengalir."
  },
  AvgDialog_34965_Content_27 = {
    Text = "Dewa yang belum lahir menjadi \"inti\" dari Clades, dan memengaruhi semua makhluk di kapal."
  },
  AvgDialog_34965_Content_28 = {
    Text = "Para pelaut yang lemah roh dan kacau mental adalah yang pertama-tama terpengaruh oleh Clades. Parasit-parasit ini mungkin juga merupakan manifestasi dari D-hiperplasia."
  },
  AvgDialog_34965_Content_29 = {Text = "Juga?"},
  AvgDialog_34965_Content_3 = {
    Text = "Murphy dengan hati-hati mendekati Pelaut yang telah kalian kalahkan, Ramona mengikuti di belakangnya."
  },
  AvgDialog_34965_Content_30 = {
    Text = [[
Kamu mengangguk, meminta semua orang untuk bergerak bersama, lalu meninggalkan ruang persembunyian secara bersamaan. 
 Menuju arah dari mana kamu dan Murphy mendengar suara, kalian kembali ke dek bawah.]]
  },
  AvgDialog_34965_Content_31 = {
    Text = "Kabin yang dipenuhi pertumbuhan abnormal begitu sunyi, dan pertumbuhan itu tumbuh liar, menjadi lebih tidak teratur dan penuh kegilaan dibandingkan saat kau meninggalkan tempat ini."
  },
  AvgDialog_34965_Content_4 = {
    Text = "Mereka saling bertukar pandang, lalu bersama-sama membalikkan Tubuh Pelaut yang sedang terbaring telungkup."
  },
  AvgDialog_34965_Content_5 = {
    Text = "Perutnya membengkak tinggi akibat parasit, kulitnya tertarik dari dalam hingga menjadi transparan, dan organ di dalamnya hampir terlihat dengan mata telanjang."
  },
  AvgDialog_34965_Content_6 = {
    Text = "Bergerak, itu bergerak!"
  },
  AvgDialog_34965_Content_7 = {
    Text = "Parasit bergerak di hadapan semua orang, kulit perut inangnya meregang hingga kehilangan teksturnya ——"
  },
  AvgDialog_34965_Content_8 = {Text = "Cih!"},
  AvgDialog_34965_Content_9 = {
    Text = "Perut Pelaut mengempis seperti balon, parasit di dalamnya tidak bergerak lagi. Ramona melambaikan pedangnya ke arah udara kosong, melemparkan air kotor yang menempel di ujung pedangnya."
  },
  AvgDialog_34966_Content_1 = {
    Text = "Telah ditinggalkan, menunggu untuk dihapus"
  },
  AvgDialog_34967_Content_10 = {
    Text = "Kali ini, meskipun kamu berhasil masuk ke Dimensi Roh, saat baru ingin membuka mata dan memicu Tautan, berbagai adegan aneh dan kabur seperti potongan gambar yang kacau membanjiri pikiranmu."
  },
  AvgDialog_34967_Content_11 = {
    Text = "Kau menatap kehampaan di hatimu, berusaha menahan tekanan abnormal ini, tetapi rohmu pada akhirnya terjatuh dengan keras ke tanah."
  },
  AvgDialog_34967_Content_12 = {Text = "Ukh……!"},
  AvgDialog_34967_Content_13 = {
    Text = "Murid, kamu mengalami mimisan."
  },
  AvgDialog_34967_Content_14 = {
    Text = "Kamu tersentak kaget, lalu memutar kepala dan mengusap hidungmu dengan kain di bahumu. Benar saja, kain hitam itu ternoda oleh bercak darah berwarna gelap."
  },
  AvgDialog_34967_Content_15 = {
    Text = "Kamu terlalu lelah, biar aku yang membawa Murphy."
  },
  AvgDialog_34967_Content_16 = {
    Text = "Kamu menggelengkan kepala, lalu dengan segenap tenaga menopang Murphy agar tetap stabil."
  },
  AvgDialog_34967_Content_17 = {
    Text = "Aku tidak apa-apa, teruskan berjalan."
  },
  AvgDialog_34967_Content_2 = {
    Text = "Kehampaan putus asa dan perjuangan menyelimuti kesadaran Murphy, mengubah gumamannya menjadi satu demi satu sangkar."
  },
  AvgDialog_34967_Content_3 = {
    Text = "Gambar…@1……"
  },
  AvgDialog_34967_Content_4 = {
    Text = "Apakah kamu memanggil Tulu?"
  },
  AvgDialog_34967_Content_5 = {Text = "Kenapa..."},
  AvgDialog_34967_Content_6 = {
    Text = "Tangannya tanpa sadar mengencang, seluruh tubuhnya tenggelam dalam fatamorgana ketakutan."
  },
  AvgDialog_34967_Content_7 = {
    Text = [[
Tulu... memang, jika Tulu ada di sini, dia pasti tahu cara membangunkanmu. 
 Meski tidak berhasil, setidaknya dia bisa membuatmu merasa lebih baik...]]
  },
  AvgDialog_34967_Content_8 = {
    Text = "Ngomong-ngomong… tautan. Aku bisa mencoba memanggilnya lagi menggunakan tautan."
  },
  AvgDialog_34967_Content_9 = {
    Text = "Kamu menoleh untuk melihat Ramona yang masih menahan serangan Pelaut, lalu menghirup napas dalam-dalam, dan akhirnya menutup mata serta tenggelam ke dalam Dimensi Roh…"
  },
  AvgDialog_34968_Content_1 = {
    Text = "Perlindungan Beban Berlebih"
  },
  AvgDialog_34968_Content_10 = {
    Text = "Ketika bintang-bintang berada pada posisi yang selaras, benda langit akan membimbing kelahiran kembali dari sisa-sisa. Pada saat itu, ranah dewa juga akan naik, dan seberkas cahaya fajar akan sekali lagi menyinari Lemuria."
  },
  AvgDialog_34968_Content_100 = {Text = "Siapa!"},
  AvgDialog_34968_Content_101 = {
    Text = "Pendengar gelap mengangkat tombak tulang panjang dan bergegas pergi. Ramona mengejarnya, namun hanya melihat sosok berjubah hitam menghilang di ujung koridor."
  },
  AvgDialog_34968_Content_102 = {Text = "…Caecus."},
  AvgDialog_34968_Content_103 = {
    Text = "Pemuda Pembangun itu tidak kehilangan kendali, begitu pula Goliath."
  },
  AvgDialog_34968_Content_104 = {
    Text = "Kapten, baru saja kau berkata bahwa Tautan Caecus adalah Miryam… Apakah kau sangat yakin tentang hal ini?"
  },
  AvgDialog_34968_Content_105 = {
    Text = "Sejauh yang saya tahu, tidak mungkin salah."
  },
  AvgDialog_34968_Content_106 = {
    Text = "Boneka, apakah kamu mendengarnya?"
  },
  AvgDialog_34968_Content_107 = {
    Text = "Ini berarti bahwa Pelaut utama Miryam belum kehilangan kemampuannya."
  },
  AvgDialog_34968_Content_108 = {
    Text = "Adapun pingsan Penjaga… selama setahun di Mythag, {Male=dia,Female=dia} belum pernah mengalami pingsan mendadak seperti ini."
  },
  AvgDialog_34968_Content_109 = {
    Text = "Sebelum melakukan pemeriksaan Tubuh yang lengkap, saya tidak dapat menentukan apa yang salah dengan Tubuh %hisorher%."
  },
  AvgDialog_34968_Content_11 = {
    Text = "Ini adalah perjanjian antara Dewa dan tubuh yang dangkal ini…"
  },
  AvgDialog_34968_Content_110 = {
    Text = [[
William telah memimpin tim untuk membersihkan musuh yang berkeliaran di dermaga, dan sekarang hanya menunggu kalian kembali... 
 Kembalilah hidup-hidup, semuanya.]]
  },
  AvgDialog_34968_Content_111 = {
    Text = "Pada saat yang sama\nSonaniel·Ruang Kekuatan"
  },
  AvgDialog_34968_Content_112 = {
    Text = "Papan dek yang rapuh dan struktur baja tidak mampu menahan fluktuasi Gnosis. Gelombang kejut energi menyapu ruang kekuatan setelah ledakan."
  },
  AvgDialog_34968_Content_113 = {
    Text = "Dari sisa-sisa puing-puing berwarna hitam kecokelatan, dia bergerak dengan kaku, seolah-olah tergoda oleh aroma darah, atau seperti boneka tanpa kemampuan berpikir."
  },
  AvgDialog_34968_Content_114 = {
    Text = "Tubuhnya digerakkan oleh semacam kekuatan tak terlihat. Dia dengan ekspresi kosong, bahkan sedikit aneh, perlahan mendorong puing-puing dan merangkak keluar dari reruntuhan."
  },
  AvgDialog_34968_Content_115 = {
    Text = "Tidak ada yang tahu jenis keinginan kelam dan kekuatan apa yang menguasai dirinya. Wajahnya yang cantik penuh dengan debu, matanya kosong dan suram, tanpa secercah cahaya, namun berkilauan dengan cahaya yang aneh."
  },
  AvgDialog_34968_Content_116 = {
    Text = "Seperti ketakutan dan bahaya yang muncul dari Jurang keputusasaan."
  },
  AvgDialog_34968_Content_12 = {
    Text = "...Tidak, ini adalah perjanjian antara kau dan aku."
  },
  AvgDialog_34968_Content_13 = {
    Text = "Sekarang, terimalah tidur sementara ini."
  },
  AvgDialog_34968_Content_14 = {
    Text = "Imam Miryam."
  },
  AvgDialog_34968_Content_15 = {
    Text = "Banjir dan tsunami datang silih berganti. Rakyat belum sempat berpamitan dengan orang yang paling mereka cintai, sudah hancur lebur oleh kekuatan alam yang luar biasa."
  },
  AvgDialog_34968_Content_16 = {
    Text = "Kami sudah berjanji..."
  },
  AvgDialog_34968_Content_17 = {
    Text = "Aku tidak akan menyerah pada dirinya."
  },
  AvgDialog_34968_Content_18 = {
    Text = "Apakah itu... %player% ...?"
  },
  AvgDialog_34968_Content_19 = {
    Text = "Murphy berjuang untuk duduk dan dengan tatapan bingung memandang sekeliling."
  },
  AvgDialog_34968_Content_2 = {
    Text = "Kepala... sangat sakit..."
  },
  AvgDialog_34968_Content_20 = {
    Text = "Orang-orang yang dikenalnya berkumpul tidak jauh, berdiskusi dengan suara rendah tentang sesuatu. Setelah Murphy bersuara, semua orang serentak menoleh."
  },
  AvgDialog_34968_Content_21 = {
    Text = "Murphy! Bagaimana perasaanmu sekarang?"
  },
  AvgDialog_34968_Content_22 = {
    Text = "Pemandangan di depan mata perlahan menjadi jelas. Murphy mengusap matanya, dan baru menyadari bahwa di tengah lingkaran pengepungan, %player% sedang tertidur dalam keadaan tidak sadar."
  },
  AvgDialog_34968_Content_23 = {
    Text = "{Male=Dia,Female=Dia}, apa yang terjadi dengan {Male=dia,Female=dia}?"
  },
  AvgDialog_34968_Content_24 = {
    Text = "Tidak tahu… %player% tidak memiliki luka luar yang jelas, seharusnya tidak pingsan begitu tiba-tiba."
  },
  AvgDialog_34968_Content_25 = {
    Text = "Tautan antara Yu dan {Male=dia,Female=dia} sangat stabil. Stabil sampai... terasa agak tidak normal."
  },
  AvgDialog_34968_Content_26 = {
    Text = "Kami sudah melakukan pemeriksaan rutin sebelum meninggalkan sekolah, %player% saat itu masih sangat stabil…"
  },
  AvgDialog_34968_Content_27 = {
    Text = "Murphy, apakah %player% menunjukkan perilaku aneh saat bertindak bersama {Male=dia,Female=dia}?"
  },
  AvgDialog_34968_Content_28 = {
    Text = "Maksudmu, setelah ledakan itu, sebelum kalian ditemukan di ruang kargo? Biarkan aku berpikir..."
  },
  AvgDialog_34968_Content_29 = {
    Text = "Eh, eh?! Jangan menakutiku, jangan mati ya?!"
  },
  AvgDialog_34968_Content_3 = {
    Text = "Di mana ini…%player%? Di mana kamu?"
  },
  AvgDialog_34968_Content_30 = {
    Text = "Aku... aku tidak apa-apa..."
  },
  AvgDialog_34968_Content_31 = {
    Text = "Bangun, %player%, kau harus segera bangun."
  },
  AvgDialog_34968_Content_32 = {
    Text = "Jangan, jangan menakutiku... Jangan tidur, cepat bangun."
  },
  AvgDialog_34968_Content_33 = {
    Text = "Setidaknya ada dua kali... Pertama kali saat mencoba menggunakan semacam trik pelacakan untuk menemukan seseorang, dan yang kedua kalinya tiba-tiba pingsan, namun segera sadar kembali tak lama kemudian."
  },
  AvgDialog_34968_Content_34 = {
    Text = "{Male=Dia,Female=Dia}……Apakah {Male=dia,Female=dia} akan baik-baik saja?"
  },
  AvgDialog_34968_Content_35 = {
    Text = "Ramona memandang pasangannya — {Male=dia,Female=dia} terbaring di sisinya, tenggelam dalam pusaran pingsan. Wajahnya tampak kemerahan dan tenang, seakan-akan dia hanya sedang menikmati mimpi indah."
  },
  AvgDialog_34968_Content_36 = {
    Text = "Di dalam hatinya mengalir emosi yang sulit dijelaskan, pandangannya terpaku pada wajah tenang rekan kerjanya, dan seluruh dunia seolah-olah menjadi hening."
  },
  AvgDialog_34968_Content_37 = {
    Text = [[
Saya... saya tidak tahu... 
 Mungkin ada seseorang di sekolah yang bisa membantu, tapi saya...]]
  },
  AvgDialog_34968_Content_38 = {
    Text = "Menghubungi sekolah? Mungkin bisa mencoba telegram nirkabel..."
  },
  AvgDialog_34968_Content_39 = {
    Text = "Nakhoda menelan sisa kalimatnya."
  },
  AvgDialog_34968_Content_4 = {
    Text = "Dia tidak mendapatkan tanggapan dari siapa pun. Yang bergema dalam kegelapan pekat hanyalah aliran air yang tak pernah berhenti."
  },
  AvgDialog_34968_Content_40 = {
    Text = "Peralatan radio berada di ruang kemudi, dan sangat jelas — kembali ke sana sekarang sama saja dengan mencari kematian."
  },
  AvgDialog_34968_Content_41 = {
    Text = "Komunikator, bukankah kalian punya komunikator ajaib itu?"
  },
  AvgDialog_34968_Content_42 = {
    Text = "Mata Ramona berbinar, aura suram di tubuhnya lenyap seketika. Dia diam-diam mengejek dirinya sendiri atas kepanikan dan kegelisahannya, sambil mengangkat tangan dan menekan komunikator lambang sekolah."
  },
  AvgDialog_34968_Content_43 = {
    Text = "Zzz—zzz—"
  },
  AvgDialog_34968_Content_44 = {
    Text = "Menarik...&*…"
  },
  AvgDialog_34968_Content_45 = {
    Text = "Boneka?! Apakah itu Boneka!"
  },
  AvgDialog_34968_Content_46 = {
    Text = "Menjaga rahasia...%#...kapal**...?"
  },
  AvgDialog_34968_Content_47 = {
    Text = "Tidak bisa, tidak terdengar dengan jelas. Masih terlalu jauh dari daratan, melebihi jangkauan efektif komunikator."
  },
  AvgDialog_34968_Content_48 = {
    Text = "Tunggu sebentar, mungkin aku bisa sementara meningkatkan kinerja komunikator."
  },
  AvgDialog_34968_Content_49 = {
    Text = "Ramona dengan tegas melepas brosnya, lalu dengan cekatan menggunakan peniti besar yang selalu dibawanya untuk membuka casing komunikator."
  },
  AvgDialog_34968_Content_5 = {
    Text = "Air, air yang tak berujung."
  },
  AvgDialog_34968_Content_50 = {
    Text = "Kamu... mengeluarkan jarum dari mana?"
  },
  AvgDialog_34968_Content_51 = {
    Text = "Lebih baik mencegah daripada mengobati. Melakukan lebih banyak persiapan tidak akan salah."
  },
  AvgDialog_34968_Content_52 = {
    Text = "Ramona memainkan struktur di dalam komunikator, tak lama kemudian, dia merusak lapisan pelindung terakhir dari inti energi komunikator dengan menggunakan sebuah peniti sederhana."
  },
  AvgDialog_34968_Content_53 = {
    Text = "Gumpalan Perak yang bergerak tenang tiba-tiba muncul di hadapan semua orang."
  },
  AvgDialog_34968_Content_54 = {
    Text = "Perak... Jadi, apakah semua Perak yang indeks gnostiknya tidak mencapai standar Bangun dijadikan alat?"
  },
  AvgDialog_34968_Content_55 = {
    Text = "Penjelasan prinsip secara rinci dan perdebatan etika, mari kita lanjutkan setelah kembali ke sekolah."
  },
  AvgDialog_34968_Content_56 = {
    Text = "Selanjutnya, saya akan membuat inti komunikator mengalami korsleting, melalui fluktuasi Gnosis yang besar secara instan, untuk sementara meningkatkan efisiensi komunikator."
  },
  AvgDialog_34968_Content_57 = {
    Text = "Secara teori, ini memang bisa dilakukan. Aku belum pernah mencoba melakukannya seperti ini sebelumnya… Aku butuh sedikit waktu."
  },
  AvgDialog_34968_Content_58 = {
    Text = "Dua menit kemudian"
  },
  AvgDialog_34968_Content_59 = {
    Text = "Murphy, bisakah kamu membantuku memegang komponen ini?"
  },
  AvgDialog_34968_Content_6 = {
    Text = "Ombak hitam, tingginya melebihi gunung tertinggi di Elworth. Ombak itu langsung jatuh ke arah kota, sejarah dan masa depan hancur serta tenggelam sepenuhnya…"
  },
  AvgDialog_34968_Content_60 = {
    Text = "Untuk apa ini digunakan?"
  },
  AvgDialog_34968_Content_61 = {
    Text = "Ini adalah sebuah pengaman untuk menstabilkan Perak. Setelah dilepas, Perak yang telah diaktifkan secara khusus dapat saya hubung singkat."
  },
  AvgDialog_34968_Content_62 = {
    Text = "Cobalah untuk memegangnya dengan hati-hati, nanti kita harus memasangnya kembali. Tanpa pengaman ini, inti komunikator tidak bisa didinginkan dan mudah meledak."
  },
  AvgDialog_34968_Content_63 = {Text = "Iya?!"},
  AvgDialog_34968_Content_64 = {
    Text = "Satu menit kemudian"
  },
  AvgDialog_34968_Content_65 = {
    Text = "Tampak Ramona memainkan struktur internal komunikator dengan jarum. Beberapa roda gigi dan kawat logam yang fungsinya tidak jelas semuanya dikeluarkan ulang olehnya untuk disusun kembali."
  },
  AvgDialog_34968_Content_66 = {Text = "Selesai!"},
  AvgDialog_34968_Content_67 = {
    Text = "Murphy berjongkok di samping Ramona, dengan gemetar memegang komponen. Namun, setelah mendengar perkataan itu, dia tetap penasaran dan mendekatkan kepalanya."
  },
  AvgDialog_34968_Content_68 = {
    Text = "Apakah ini sudah cukup?"
  },
  AvgDialog_34968_Content_69 = {
    Text = "Tinggal selangkah lagi, semuanya pejamkan mata, jangan menatap langsung ke arahku."
  },
  AvgDialog_34968_Content_7 = {
    Text = "Ini adalah firman ilahi yang Anda turunkan, tak seorang pun berhak mempersalahkannya."
  },
  AvgDialog_34968_Content_70 = {
    Text = "Ramona berkata sambil menutupi mata Murphy dengan tangannya."
  },
  AvgDialog_34968_Content_71 = {
    Text = "Seberkas cahaya putih menyilaukan melesat dari pusat komunikator ke sekelilingnya, seperti kilatan petir di langit, menerangi seluruh ruang kargo dengan cahaya pucat."
  },
  AvgDialog_34968_Content_72 = {
    Text = "Energi bergelombang seperti ombak yang menggelegak, menyebar dalam sekejap."
  },
  AvgDialog_34968_Content_73 = {
    Text = "Gelombang energi ini berdengung, seperti suara bintang dari kedalaman ruang angkasa, membuat perangkat komunikasi memancarkan cahaya redup yang misterius, seolah menghubungkan galaksi yang jauh di langit."
  },
  AvgDialog_34968_Content_74 = {
    Text = "Ramona? Apakah kamu bisa mendengar dengan jelas?"
  },
  AvgDialog_34968_Content_75 = {
    Text = "Aku tak pernah begitu mengharapkan untuk mendengar suaramu..."
  },
  AvgDialog_34968_Content_76 = {
    Text = [[
Untuk menjaga komunikasi yang stabil, saya membakar dua puluh kali lipat jumlah Perak yang biasa digunakan sehari-hari. 
 Singkat cerita, bagaimana Negara kalian?]]
  },
  AvgDialog_34968_Content_77 = {
    Text = "Ramona memberi tahu Boneka secara singkat tentang semua yang terjadi di kapal: tentang ritual pemanggilan roh, tentang perkumpulan Pelaut, tentang Murphy, tentang Penjaga yang pingsan…"
  },
  AvgDialog_34968_Content_78 = {
    Text = "Hasil eksperimen Francis diperlukan untuk menghentikan perkembangan \"Dewa\"… Saya mengerti. \nBawa gadis itu kembali ke sekolah, aku dan Kerang akan mempersiapkan ruangan."
  },
  AvgDialog_34968_Content_79 = {
    Text = "Kerang, kita masih punya dua jam untuk memperkuat tindakan pencegahan terhadap anjing."
  },
  AvgDialog_34968_Content_8 = {
    Text = "Siapa... tidak, ini suaranya adalah..."
  },
  AvgDialog_34968_Content_80 = {
    Text = "Eksperimen masih tidak stabil, masih tidak stabil... Harus melakukan sesuatu, sekarang, segera! Kalau tidak, akan kehilangan kendali, akan kehilangan kendali!"
  },
  AvgDialog_34968_Content_81 = {
    Text = "Erica, tarik Kerang ke bawah."
  },
  AvgDialog_34968_Content_83 = {
    Text = "Erica menemukan informasi tentang Pelaut di perpustakaan. Jangan terlalu berharap, hanya ada sedikit informasi."
  },
  AvgDialog_34968_Content_84 = {
    Text = [[
Ketika banjir besar terjadi, ada laporan penampakan di benua baru. 
 Sekelompok pengungsi "berwajah buruk, menyerupai ikan"melintasi lautan dan menghilang di tengah banjir.]]
  },
  AvgDialog_34968_Content_85 = {
    Text = "Konon, mereka menyebut diri mereka sebagai pewaris peradaban kuno, dengan darah yang diberkati oleh \"Dewa\"."
  },
  AvgDialog_34968_Content_86 = {
    Text = "Orang-orang ini dilahirkan dalam wujud manusia. Darah dewa menyebabkan mereka berubah secara bertahap menjadi bentuk yang kalian lihat sekarang."
  },
  AvgDialog_34968_Content_87 = {
    Text = "Jadi, pemuda itu pada akhirnya juga akan berubah menjadi penampilan seperti manusia ikan……"
  },
  AvgDialog_34968_Content_88 = {
    Text = "Apakah kamu sedang berbicara tentang Caecus? Jika ingin tahu tentang dia, aku bisa memberitahumu."
  },
  AvgDialog_34968_Content_89 = {
    Text = "Ramona mengangguk, memberi isyarat kepada kapten untuk melanjutkan."
  },
  AvgDialog_34968_Content_9 = {
    Text = "Pengikut paling setia dari Ranah Dewa, sisa keabadian yang tak terhingga, kemakmuran dan kehancuran negara… aku menyerahkannya padamu."
  },
  AvgDialog_34968_Content_90 = {
    Text = [[
Berbicara tentang Caecus... anak itu juga golem, dalam bahasamu disebut Pembangun. 
Mungkin dia memiliki Tautan dengan Miryam.]]
  },
  AvgDialog_34968_Content_91 = {
    Text = "Tautan ke Miryam?! Bahkan bisa menautkan Pembangun lain dalam kondisi Bangun, aku belum pernah mendengarnya…"
  },
  AvgDialog_34968_Content_92 = {
    Text = "Ha, wanita itu memang monster yang patut diakui."
  },
  AvgDialog_34968_Content_93 = {
    Text = "Untuk mengendalikan saya, ordo secara berkala memberikan obat penenang kepada saya. Setelah kontak sebelumnya benar-benar kehilangan akal, Caecus menjadi pengantar obat yang baru."
  },
  AvgDialog_34968_Content_94 = {
    Text = "Selama bertahun-tahun, kita bertemu setiap musim... mengajarinya minum dan memancing, menunjukkan kepadanya bintang pagi di musim panas, membantunya melepas sisik kering di musim dingin..."
  },
  AvgDialog_34968_Content_95 = {
    Text = "Haha... aku mengira kita sudah berteman. Jadi, ketika dia mengirim pesan bahwa dia bisa memberiku obat untuk terakhir kalinya, aku tidak ragu sedikit pun."
  },
  AvgDialog_34968_Content_96 = {
    Text = "Namun... dia jugalah yang memberi tahu kelompok tentang keberadaan kapal Sonnelier."
  },
  AvgDialog_34968_Content_97 = {
    Text = "Tidak ada yang mengajarnya tentang apa yang benar, dan dia juga tidak menemukan makna keberadaannya di luar sebagai Pelaut."
  },
  AvgDialog_34968_Content_98 = {
    Text = "Jika menurutnya, menyerahkan saya dapat meningkatkan posisinya dalam ordo… saya tidak akan membencinya karenanya."
  },
  AvgDialog_34968_Content_99 = {
    Text = "Suara benturan logam tiba-tiba terdengar, Ramona dengan cepat mengambil posisi bertarung, melindungi Kapten dan Murphy di depan mereka."
  },
  AvgDialog_34969_Content_1 = {
    Text = "Sekali lagi, lambung kapal mengeluarkan suara berderit yang menyedihkan, diikuti oleh guncangan hebat seperti masuk ke dalam badai. Kapal bergoyang tak terkendali, dan puing-puing mekanis berserakan di mana-mana."
  },
  AvgDialog_34969_Content_10 = {
    Text = "Tidak perlu, aku merasa tidak enak meminta bantuan seseorang yang terluka."
  },
  AvgDialog_34969_Content_11 = {
    Text = "Dia mengamati seluruh tubuhmu dari atas ke bawah, lalu dengan malu-malu memalingkan wajahnya."
  },
  AvgDialog_34969_Content_12 = {
    Text = "Namun... terima kasih."
  },
  AvgDialog_34969_Content_13 = {
    Text = "Apa yang sebenarnya terjadi dengan guncangan tadi, jangan-jangan Celeste tidak sengaja membawa kapal ke arus bawah tanpa sadar…"
  },
  AvgDialog_34969_Content_14 = {
    Text = "Saya pikir… Celeste sedang kehilangan kendali atas Sonnelier. \n Memindahkan semua orang dari pusat ledakan mungkin telah membuatnya sangat lelah."
  },
  AvgDialog_34969_Content_15 = {
    Text = "Dia sudah memiliki Kelemahan sejak awal, dan sekarang lebih..."
  },
  AvgDialog_34969_Content_16 = {
    Text = "Murphy menekan dadanya dan memaksakan senyuman yang terlihat jelek."
  },
  AvgDialog_34969_Content_17 = {
    Text = "Tidak apa-apa, selama kita kembali ke daratan, semuanya akan berakhir…"
  },
  AvgDialog_34969_Content_18 = {
    Text = "Frekuensi kedipan lampu secara bertahap sejalan dengan napas, saat ruang kabin tiba-tiba menjadi gelap, musuh tidak lagi puas hanya bersembunyi dalam kegelapan…"
  },
  AvgDialog_34969_Content_2 = {Text = "Ya?!"},
  AvgDialog_34969_Content_3 = {
    Text = "Suara keras lainnya yang mirip dengan patahnya tulang terdengar entah dari mana. Sebelum kamu dan Murphy menyadarinya, seperti didorong ke puncak gelombang, badan kapal tiba-tiba miring dengan hebat ke satu sisi."
  },
  AvgDialog_34969_Content_4 = {Text = "Murphy!"},
  AvgDialog_34969_Content_5 = {
    Text = "Kamu segera meraih pipa logam yang menonjol untuk menstabilkan tubuhmu, dan saat ingin membantu Murphy, dia sudah terhuyung-huyung meluncur ke ujung lain ruang kekuatan."
  },
  AvgDialog_34969_Content_6 = {
    Text = "Tidak apa-apa! Jangan berteriak seakan-akan aku akan mati."
  },
  AvgDialog_34969_Content_7 = {
    Text = "Kabin segera kembali tenang, hanya kekacauan di mana-mana yang membuktikan adanya goncangan hebat sebelumnya."
  },
  AvgDialog_34969_Content_8 = {
    Text = "Murphy jelas masih trauma, dia berjalan ke arahmu sambil memegang dinding kapal, kakinya terus gemetar."
  },
  AvgDialog_34969_Content_9 = {
    Text = "Apakah kamu terbentur di suatu tempat? Apakah kamu butuh aku untuk membantu berjalan?"
  },
  AvgDialog_34970_Content_1 = {
    Text = "Cepat! Kamu masuk dulu, aku akan menutupi belakang."
  },
  AvgDialog_34970_Content_10 = {
    Text = "Ini benar-benar..."
  },
  AvgDialog_34970_Content_11 = {
    Text = "Kamu mendekati sebuah Sanga, yang bercahaya dengan indah dan elegan. Di balai lelang Londinium, ornamen serupa bisa terjual hingga puluhan ribu Taring."
  },
  AvgDialog_34970_Content_12 = {
    Text = "——Jika akarnya tidak tertambat kuat di dalam sebuah D-marka kecil."
  },
  AvgDialog_34970_Content_13 = {
    Text = "D-hiperplasia."
  },
  AvgDialog_34970_Content_14 = {
    Text = "Dalam kelas \"Teori Dasar Fenomena-d\", Boneka pernah menggambarkan pertumbuhan abnormal sebagai berikut: Setelah Fenomena-d berkembang sampai tahap tertentu, ada kemungkinan pertumbuhan abnormal akan muncul dari D-marka."
  },
  AvgDialog_34970_Content_15 = {
    Text = "Pertumbuhan neoplasma, distribusi berbagai jenis neoplasma, dan sebagainya saat ini belum dapat dirangkum menjadi pola yang jelas. Namun, satu hal yang pasti: neoplasma umumnya hanya muncul di area yang terdapat \"Clades\"."
  },
  AvgDialog_34970_Content_16 = {
    Text = "Hal-hal ini tanpa diragukan lagi semuanya terkait dengan Aequor, di sekitar kita pasti ada \"Clades\" yang berhubungan dengan Alam laut dalam."
  },
  AvgDialog_34970_Content_17 = {
    Text = "\"Clades\"…"
  },
  AvgDialog_34970_Content_18 = {
    Text = "Murphy mendekati Anda, menundukkan kepala untuk melihat D-marka di pangkal pertumbuhan berlebih itu. Salah satu tangannya diletakkan di dada, sementara tangan lainnya menyentuh permukaan kasar karang."
  },
  AvgDialog_34970_Content_19 = {
    Text = "Dari belakang terdengar suara benda berat jatuh. Saat berbalik, tatapanmu bertemu dengan Pelaut yang terjatuh karena tertimpa beban berat."
  },
  AvgDialog_34970_Content_2 = {
    Text = "Murphy tidak menolak atau ragu-ragu, dengan lincah meluncur masuk ke balik pintu yang kamu tahan."
  },
  AvgDialog_34970_Content_20 = {Text = "Guh……"},
  AvgDialog_34970_Content_21 = {
    Text = "Murphy terdiam lama. Melihat dia tidak bereaksi untuk waktu yang lama, kamu melangkah maju dan berdiri di antara dia dan Pelaut."
  },
  AvgDialog_34970_Content_3 = {
    Text = "Mutant laut mengikuti bau di tubuh kalian dan mengejar dengan ganas. Tepat sebelum cakar mereka menyentuh jubah, kamu berbalik dan masuk ke dalam pintu."
  },
  AvgDialog_34970_Content_4 = {
    Text = "Kamu menahan pintu dengan tubuhmu, sementara Murphy meraba-raba dan mengunci pintu dari dalam. Bau dan penampilan kalian terisolasi, suara cakaran tajam di atas baja juga segera melemah."
  },
  AvgDialog_34970_Content_5 = {
    Text = "Hah, hah… benar-benar mengejar dengan keras."
  },
  AvgDialog_34970_Content_6 = {
    Text = "Murphy, kamu duluan nyalakan lampunya... eh?!"
  },
  AvgDialog_34970_Content_7 = {
    Text = "Saat berbalik, cahaya fluoresen yang aneh langsung menyergap retina."
  },
  AvgDialog_34970_Content_8 = {
    Text = "Struktur seperti cabang tumbuh kasar dari celah-celah di dek, mereka saling bersilangan dan membentuk jalinan, menciptakan lebih banyak ruang satu sama lain. Seiring dengan suara \"kraak\" yang terus-menerus, dek mulai runtuh di berbagai tempat karena tidak mampu menahan beban."
  },
  AvgDialog_34970_Content_9 = {
    Text = "Itu adalah sanga, anemon laut, dan banyak lagi kehidupan laut yang tidak bisa kamu sebutkan namanya. Mereka kuat dan penuh kekuatan, sedikit demi sedikit membuka permukaan dek."
  },
  AvgDialog_34971_Content_1 = {
    Text = "Kamu membawa Murphy di punggungmu dan melarikan diri dari ruang kemudi bersama Kapten serta Celeste, dengan Ramona mengikuti di belakang."
  },
  AvgDialog_34971_Content_10 = {
    Text = "Goliath, kenapa?"
  },
  AvgDialog_34971_Content_11 = {
    Text = "Kenapa apanya?"
  },
  AvgDialog_34971_Content_12 = {
    Text = "Kamu berpura-pura patuh kepada Miryam, beberapa kali sengaja membiarkan kami lolos selama pengejaran sebelumnya…"
  },
  AvgDialog_34971_Content_13 = {
    Text = "Jangan membantah, kamu terlalu jelas melakukannya."
  },
  AvgDialog_34971_Content_14 = {
    Text = "Saya tidak percaya bahwa saat di Ruang Kekuatan, kamu tidak sengaja memancing amarah Miryam—kamu tidak ingin terlibat dalam konfrontasi langsung yang lebih intens dengan kami, atau lebih tepatnya, dengan Tulu."
  },
  AvgDialog_34971_Content_15 = {
    Text = "Saat menyebut Tulu, kepalamu tiba-tiba terasa sakit tanpa alasan yang jelas. Rasa sakit ini sulit diungkapkan dengan kata-kata, seperti angin kencang yang menerjang di tengah malam, menghancurkan akal sehatmu, membakar saraf dan tekad."
  },
  AvgDialog_34971_Content_16 = {Text = "Ngh..."},
  AvgDialog_34971_Content_17 = {
    Text = "Tanda-tanda pingsan berkedip-kedip di depan mata, sensasi yang bekerja pada kedalaman Jiwa ini seperti rasa sakit yang tak terlukiskan, terus-menerus membuka luka di kedalaman Jiwa yang hampir sembuh dan menjahitnya kembali."
  },
  AvgDialog_34971_Content_18 = {
    Text = "Penjaga? Penjaga?"
  },
  AvgDialog_34971_Content_19 = {
    Text = "Ramona tampaknya menyadari ketidaknyamananmu. Dia waspada terhadap Goliath, sambil hati-hati menyentuh lenganmu yang menopang Murphy."
  },
  AvgDialog_34971_Content_2 = {
    Text = "Tepat saat akan menuruni tangga, sang raksasa melompat dari ketinggian."
  },
  AvgDialog_34971_Content_20 = {
    Text = "Aku baik-baik saja."
  },
  AvgDialog_34971_Content_21 = {
    Text = "Kamu menjawab dengan suara rendah atas perhatian Ramona, menghirup dalam-dalam untuk menekan bau amis darah yang memenuhi rongga hidung dengan hembusan angin laut yang asin."
  },
  AvgDialog_34971_Content_22 = {
    Text = "Setelah itu, kamu baru mengangkat kepala dan melihat ke arah Goliath. Dia sedang memperhatikanmu dengan penuh minat, seolah-olah gerakan kecil menyakitkan yang kamu lakukan telah menghiburnya. Di wajahnya terlihat senyuman sombong dan angkuh."
  },
  AvgDialog_34971_Content_23 = {
    Text = "Jelas... kamu tidak sepenuhnya setia kepada Pelaut, bahkan meremehkan keyakinan mereka, Dewa mereka..."
  },
  AvgDialog_34971_Content_24 = {
    Text = [[
Miryam sudah kalah, sekarang tidak ada alasan permusuhan antara kamu dan kami. 
Kenapa, kenapa sekarang kamu malah mulai terobsesi dengan Murphy?]]
  },
  AvgDialog_34971_Content_25 = {
    Text = "Jika kalian ingin mati dengan jelas, cobalah gunakan otak cerdas kalian untuk menganalisis dan menyimpulkan."
  },
  AvgDialog_34971_Content_26 = {
    Text = "Pemimpin utama mati syahid, pelaut kehilangan pemimpin mereka."
  },
  AvgDialog_34971_Content_27 = {
    Text = "Apakah saya harus mendirikan kekaisaran baru, atau terus memimpin kelompok ini menuju keabadian… Katakan padaku, apa yang harus saya lakukan?"
  },
  AvgDialog_34971_Content_28 = {
    Text = "... kekuasaan yang dominan."
  },
  AvgDialog_34971_Content_29 = {
    Text = "Kamu akan menjadi pemimpin utama dari Pelaut dan satu-satunya kepala baru dalam ordo."
  },
  AvgDialog_34971_Content_3 = {Text = "Hati-hati!"},
  AvgDialog_34971_Content_30 = {
    Text = "Untuk itu... kamu membutuhkan \"Ibu Dewa\", harus menyelesaikan ritual ini secara formal untuk memperkuat posisimu dalam kelompok Pelaut..."
  },
  AvgDialog_34971_Content_31 = {
    Text = "Meskipun merupakan anak anjing yang dibesarkan di universitas, kecerdasannya cukup baik."
  },
  AvgDialog_34971_Content_32 = {
    Text = [[
Serahkan Murphy padaku. 
 Jika kau menurut sekarang, saat pasukanku menghancurkan peradaban manusia di masa depan, aku tidak akan membuatmu menderita.]]
  },
  AvgDialog_34971_Content_33 = {
    Text = "Jangan sia-siakan pikiranmu."
  },
  AvgDialog_34971_Content_34 = {
    Text = "Aku... Apakah aku belum pernah bertanya nama kamu...?"
  },
  AvgDialog_34971_Content_35 = {
    Text = "Sejak kecil, setiap kali saya mengalami luka luar, mereka selalu mengoleskan obat ini pada saya."
  },
  AvgDialog_34971_Content_36 = {
    Text = "Bagaimana, apakah setelah dioleskan langsung tidak terasa sakit lagi?"
  },
  AvgDialog_34971_Content_37 = {
    Text = "Berat tubuh gadis itu menekan tubuhmu, punggung dan anggota tubuhmu mulai gemetar tak terkendali."
  },
  AvgDialog_34971_Content_38 = {
    Text = "Kami sudah berjanji, akan membawanya kembali, akan membantunya terbebas dari parasit \"Dewa\"itu."
  },
  AvgDialog_34971_Content_39 = {
    Text = "Kamu menggigit gigi dengan kuat, berusaha menahan beban jiwa."
  },
  AvgDialog_34971_Content_4 = {
    Text = "Ramona melangkah cepat ke arahmu."
  },
  AvgDialog_34971_Content_40 = {
    Text = "Aku tidak akan menyerah pada dirinya."
  },
  AvgDialog_34971_Content_41 = {
    Text = "Terdengar suara berdengung yang terus-menerus di telinga, sementara suara seruling yang kacau terdengar di tengah dengungan itu."
  },
  AvgDialog_34971_Content_42 = {
    Text = "Simfoni absurd ini membuat kelopak matamu bergetar, dan pikiranmu dipenuhi dengan kegelisahan serta kekacauan."
  },
  AvgDialog_34971_Content_43 = {
    Text = "Kamu merasakan sejenis kelelahan yang aneh, sebuah kelelahan yang terasa familiar, namun juga tak pernah dirasakan sebelumnya. Saraf perlahan mengalami kelumpuhan, dan anggota tubuh mulai terasa lemah tak bertenaga."
  },
  AvgDialog_34971_Content_44 = {
    Text = "Pandangan di depanmu mulai menggelap, tirai hitam yang tebal secara perlahan menutupi duniamu. Suara bising dan segala kekacauan tampaknya menjauh, sementara melodi seruling tanpa suara menyentuh otakmu seperti bulu tak terlihat yang lembut."
  },
  AvgDialog_34971_Content_45 = {
    Text = "Tidak bisa tidur... tidak boleh tertidur."
  },
  AvgDialog_34971_Content_46 = {
    Text = "Kamu melawan rasa kantuk yang misterius ini, namun tampaknya tidak ada gunanya. Suara Ramona semakin memudar dengan cepat, dan sebelum kamu menyadari apa yang terjadi, tubuhmu jatuh berat ke tanah."
  },
  AvgDialog_34971_Content_47 = {Text = "Gambar..."},
  AvgDialog_34971_Content_49 = {
    Text = "Otakmu sulit memproses apa yang sedang terjadi di depan mata, tapi satu hal yang pasti: tentakel berwarna hijau ganggang berhasil menahan pedang raksasa itu, dan tentakel itu seharusnya terasa lembut seperti daging jeruk."
  },
  AvgDialog_34971_Content_5 = {
    Text = "Saya menyukai orang yang memiliki keberanian untuk melawan, namun lebih membenci mereka yang tidak mengerti situasi."
  },
  AvgDialog_34971_Content_7 = {
    Text = "Goliath tidak hanya menabrak tangga luar besi yang sudah rapuh akibat hujan dan angin, tetapi juga meletakkan pedang raksasa di depan kalian, menghalangi jalan kalian."
  },
  AvgDialog_34971_Content_8 = {
    Text = "Murid Mythag… Ha, masih begitu polos."
  },
  AvgDialog_34971_Content_9 = {
    Text = "Kalian tidak benar-benar berpikir bisa melarikan diri, kan? Hanya dengan kapal tua yang hampir roboh ini, hanya dengan golem yang hampir kehilangan bentuknya dan Tautannya?"
  },
  AvgDialog_34972_Content_1 = {
    Text = "Ngengat Pemadam Api"
  },
  AvgDialog_34972_Content_10 = {
    Text = "Caecus menundukkan kepalanya dan melihat sirip ekornya yang telah berubah menjadi cokelat akibat terbakar api, lalu menunduk dalam diam."
  },
  AvgDialog_34972_Content_11 = {
    Text = "Adapun Yang Terhormat Imam Agung itu..."
  },
  AvgDialog_34972_Content_12 = {
    Text = "Goliath berkata dengan tatapan sombong yang menyapu satu per satu dari kalian, akhirnya berhenti pada Celeste dan sang kapten."
  },
  AvgDialog_34972_Content_13 = {
    Text = "Mungkin, mereka tidak akan begitu murah hati untuk menyelamatkan Imam Agung dari pusat ledakan, bukan?"
  },
  AvgDialog_34972_Content_15 = {
    Text = [[
Pergilah, Caecus. 
Tunjukkan kemampuanmu dan buktikan apakah kau memiliki kualifikasi untuk bergabung denganku.]]
  },
  AvgDialog_34972_Content_17 = {
    Text = "Ya, Tuan Goliath."
  },
  AvgDialog_34972_Content_18 = {
    Text = "Caecus, apa yang akan kamu lakukan!"
  },
  AvgDialog_34972_Content_19 = {
    Text = [[
Caecus menatap kapten sejenak, ingin berbicara tapi kemudian mengurungkannya. 
 Setelah beberapa saat hening, dia akhirnya mengambil napas dalam-dalam seolah telah membulatkan tekad.]]
  },
  AvgDialog_34972_Content_2 = {
    Text = "Goliath membungkuk saat memasuki ruang kemudi. Tubuhnya yang besar hampir sepenuhnya memblokir pintu di sisi itu."
  },
  AvgDialog_34972_Content_20 = {
    Text = "Maaf, Tuan Elton."
  },
  AvgDialog_34972_Content_21 = {
    Text = "Dia mengayunkan senjatanya dan dengan kuat memukul dinding kabin sebanyak dua kali."
  },
  AvgDialog_34972_Content_22 = {
    Text = "Gema besar yang dihasilkan oleh getaran logam bergema di ruang tersebut, seperti raungan kemarahan kegelapan yang terjebak dalam Jurang tanpa harapan, membuat siapa pun yang mendengarnya merasa tuli oleh suara itu."
  },
  AvgDialog_34972_Content_23 = {
    Text = "Pelaut! Saat bintang-bintang selaras akan segera tiba!"
  },
  AvgDialog_34972_Content_24 = {
    Text = [[
Atas nama Goliath, rebut kembali Sang Ibu dari tangan para bodoh! 
 Ritual ini pasti akan dilaksanakan malam ini!]]
  },
  AvgDialog_34972_Content_3 = {
    Text = [[
Kamu jauh lebih cerdik daripada orang-orang yang sombong itu. 
Jadi, aku jadi ragu untuk memberikanmu kekuatan penuh dari Aequor.]]
  },
  AvgDialog_34972_Content_4 = {
    Text = "Membiarkanmu tetap dalam bentuk setengah manusia dan setengah ikan seperti sekarang, tampaknya lebih berguna."
  },
  AvgDialog_34972_Content_5 = {
    Text = "Tuan! Imam Agung pernah berjanji kepadaku akan kesucian tubuhku sepenuhnya…"
  },
  AvgDialog_34972_Content_6 = {
    Text = "Napas sang Pelaut muda terhenti, matanya yang seperti ikan membulat karena ketegangan, pandangannya terpaku erat pada Goliath."
  },
  AvgDialog_34972_Content_7 = {
    Text = "Imam Utama? Shh..."
  },
  AvgDialog_34972_Content_8 = {
    Text = "Goliath tidak menyadari tatapan pemuda itu, atau lebih tepatnya, sedikit kegembiraan yang dimiliki pemuda itu sama sekali tidak cukup untuk menarik perhatiannya."
  },
  AvgDialog_34972_Content_9 = {
    Text = [[
Kamu mengalami ledakan di Ruang Kekuatan, kekuatan ledakan itu sudah kita saksikan bersama. 
 Jika aku tidak ada di sana, kamu pasti sudah hancur menjadi debu perak.]]
  },
  AvgDialog_34973_Content_1 = {
    Text = "Dengan perlindungan Ramona, kalian menaiki tangga ke atas. Elton membantu menopang beban Murphy, meski begitu, mendaki jembatan setinggi sekitar empat lantai tetap membutuhkan banyak usaha."
  },
  AvgDialog_34973_Content_10 = {
    Text = "Penjaga, kalian bisa masuk."
  },
  AvgDialog_34973_Content_11 = {
    Text = "Kamu mengangguk, dan dengan bantuan Ramona, Murphy berbaring."
  },
  AvgDialog_34973_Content_12 = {
    Text = "Napasnya menjadi lebih teratur, tidak seperti sebelumnya yang napasnya lebih banyak keluar daripada masuk."
  },
  AvgDialog_34973_Content_13 = {
    Text = [[
Sepertinya, Tubuhnya untuk sementara telah beradaptasi dengan keadaan kekurangan oksigen yang disebabkan oleh parasit. 
Namun, jika Negara ini berlangsung terlalu lama, saya khawatir akan menimbulkan efek samping yang tidak dapat dipulihkan.]]
  },
  AvgDialog_34973_Content_14 = {
    Text = "Hmm, harus segera membawanya pergi."
  },
  AvgDialog_34973_Content_15 = {
    Text = "Kapten, bagaimana situasi di ruang kemudi?"
  },
  AvgDialog_34973_Content_16 = {
    Text = "Beberapa perangkat mengalami kerusakan, peluit uap dan saklar radio macet. Untungnya, sistem kontrol tenaga inti serta kemudi masih dalam kondisi baik."
  },
  AvgDialog_34973_Content_17 = {
    Text = "Elton berbicara sambil dengan cekatan memutar roda kemudi di tengah, menarik satu per satu piston."
  },
  AvgDialog_34973_Content_18 = {
    Text = "Kamu menjulurkan kepala keluar dari lubang kapal dan melihat ke sisi lain dek. Beberapa perangkat berbentuk tabung, yang kemungkinan merupakan pipa ventilasi, mengeluarkan asap putih tipis. Tak lama kemudian, terdengar suara air memercik dari buritan kapal."
  },
  AvgDialog_34973_Content_19 = {
    Text = "Apakah itu suara kemudi yang berfungsi? Kita sedang berbelok."
  },
  AvgDialog_34973_Content_2 = {
    Text = "Hah, hah... akhirnya sampai juga."
  },
  AvgDialog_34973_Content_20 = {
    Text = "Elton mengangguk dan menghela napas panjang."
  },
  AvgDialog_34973_Content_21 = {
    Text = "Sonanier adalah kapal besar, saat berbelok akan terasa canggung dan lambat. Namun, setelah belokan selesai, kita bisa kembali dengan kecepatan penuh sesuai kemampuan kapal."
  },
  AvgDialog_34973_Content_22 = {
    Text = "Bagaimana keadaan Murphy?"
  },
  AvgDialog_34973_Content_23 = {
    Text = "Sementara tidak ada tanda-tanda memburuk, parasit menekan jantungnya dan memengaruhi sirkulasi normal organ tubuhnya…"
  },
  AvgDialog_34973_Content_24 = {
    Text = "Belum lagi parasit itu telah menjadi titik awal bencana Pelarutan, dengan jarak sedekat ini bersentuhan dengan <Yellow:\"Inti Clades\">, aku khawatir Murphy juga akan terkena dampak Pelarutan…"
  },
  AvgDialog_34973_Content_25 = {
    Text = "Fenomena-d…lagi-lagi Fenomena-d."
  },
  AvgDialog_34973_Content_26 = {
    Text = "Benda sialan ini, berapa banyak lagi yang harus diambil dari duniaku...!"
  },
  AvgDialog_34973_Content_27 = {
    Text = "Kapten, apakah kamu masih ingat keberadaan lain yang menghilang karena Fenomena-d?"
  },
  AvgDialog_34973_Content_28 = {
    Text = "Elton menutup matanya sejenak, pipa rokoknya berderak keras karena dia gigit dengan kuat."
  },
  AvgDialog_34973_Content_29 = {
    Text = "Pembangun yang terus diam-diam melihat Elton sekilas, dengan tenang berjalan ke arahnya, lalu mengulurkan kedua tangannya yang sudah setengah transparan ke depannya."
  },
  AvgDialog_34973_Content_3 = {
    Text = "Elton mengangguk ke arahmu, mengeluarkan kunci dari tasnya, lalu bersama Ramona mendorong membuka pintu ruang kemudi."
  },
  AvgDialog_34973_Content_30 = {
    Text = "Celeste... Apakah ini memengaruhimu? Maaf, aku akan berusaha mengendalikan emosiku."
  },
  AvgDialog_34973_Content_31 = {
    Text = "Elton mengambil beberapa napas dalam, tampaknya berhasil menenangkan hatinya yang bergejolak. Dia memandang Ramona dan kamu, nadanya juga menjadi jauh lebih tenang."
  },
  AvgDialog_34973_Content_32 = {
    Text = "Fenomena-d… aku sudah lama berselisih dengannya."
  },
  AvgDialog_34973_Content_33 = {
    Text = "Masa laluku... itulah yang menyebabkan kehancurannya."
  },
  AvgDialog_34973_Content_4 = {
    Text = "Astaga! Sanga-sanga ini juga sudah tumbuh sampai ke sini!"
  },
  AvgDialog_34973_Content_5 = {
    Text = "Kapten, tunggu sebentar—!"
  },
  AvgDialog_34973_Content_6 = {
    Text = "Elton menerobos masuk ke ruang kemudi, diikuti oleh Ramona yang mengejarnya."
  },
  AvgDialog_34973_Content_7 = {
    Text = "Kabin lebih besar dari yang kamu bayangkan, dengan struktur dua tingkat yang sangat langka, lebih megah daripada foto kabin apa pun yang pernah kamu lihat."
  },
  AvgDialog_34973_Content_8 = {
    Text = "Bisa dibayangkan, sebelum diubah menjadi kapal kargo, Sonnelier pernah menjadi surga laut yang begitu gemerlap."
  },
  AvgDialog_34973_Content_9 = {
    Text = "Hu... Untung saja kapten mengunci pintu. Selain pertumbuhan abnormal, tidak ada Pelaut atau tubuh bermutasi yang masuk."
  },
  AvgDialog_34974_Content_1 = {Text = "Parasit"},
  AvgDialog_34974_Content_10 = {
    Text = "Setelah mengalami ledakan dengan intensitas seperti ini, tinnitus yang berlangsung selama tiga hingga lima hari masih dianggap normal."
  },
  AvgDialog_34974_Content_11 = {
    Text = "Hmm, dari apa yang kurasakan, setidaknya gendang telingaku masih utuh."
  },
  AvgDialog_34974_Content_12 = {
    Text = "Penjaga, bagaimana perasaanmu… tunggu sebentar…"
  },
  AvgDialog_34974_Content_13 = {
    Text = "Aku, aku tidak bisa menahan tangan Penjaga... {Male=dia,Female=dia}, {Male=dia,Female=dia}..."
  },
  AvgDialog_34974_Content_14 = {
    Text = "Jangan tegang, jangan tegang. Domain Sonanier juga mencakup wilayah laut di sekitarnya, dan Celeste tidak akan melewatkan %hisorher%."
  },
  AvgDialog_34974_Content_15 = {
    Text = "Celeste berkedip, seolah-olah untuk membenarkan pernyataan sang kapten."
  },
  AvgDialog_34974_Content_16 = {
    Text = "Eh, eh, setelah itu, tautan di antara kita terputus sesaat…"
  },
  AvgDialog_34974_Content_17 = {
    Text = "Meskipun perasaan itu cepat menghilang lagi, sensasi seperti kehilangan gravitasi hingga tidak bisa berkata sepatah kata pun bukanlah ilusi saya."
  },
  AvgDialog_34974_Content_18 = {
    Text = "Saya memang menyentuh {Male=dia,Female=dia}, hanya saja…"
  },
  AvgDialog_34974_Content_19 = {
    Text = "Celeste berhenti berbicara di tengah kalimat, seperti roda gigi yang mengalami pemindahan dan berhenti berputar. Bibirnya bergerak beberapa kali, namun tak sepatah kata pun yang keluar."
  },
  AvgDialog_34974_Content_2 = {
    Text = "Pada milidetik berikutnya setelah menyentuh punggung tangan Penjaga, angin putih yang lembut dan tanpa suara menabrak titik pusat ledakan."
  },
  AvgDialog_34974_Content_20 = {
    Text = "Elton menepuk punggungnya dengan sikap menenangkan dan melanjutkan kalimat yang belum selesai."
  },
  AvgDialog_34974_Content_21 = {
    Text = "Hanya saja, sebelumnya kami belum pernah mencoba memindahkan makhluk hidup dengan ukuran lebih besar daripada tikus."
  },
  AvgDialog_34974_Content_22 = {
    Text = "Kemampuan untuk memindahkan koordinat makhluk di dalam kapal bersumber dari penguasaan Celeste terhadap Domain, dalam keadaan saya yang semakin lemah, kontrolnya terhadap titik jatuh... tidak terlalu tepat."
  },
  AvgDialog_34974_Content_23 = {
    Text = "Anak itu, dan Murphy, {Male=dia,Female=dia} mungkin berada di mana saja di kapal ini."
  },
  AvgDialog_34974_Content_24 = {
    Text = "Bagus sekali... Maaf, Kapten. Saya tadi terlalu cemas, semoga tidak membuat kalian merasa tersinggung."
  },
  AvgDialog_34974_Content_25 = {
    Text = "Ngomong-ngomong… Sonanier adalah kapal kargo yang diubah dari kapal penumpang, jumlah kabinnya…"
  },
  AvgDialog_34974_Content_26 = {
    Text = "Ada 7 dek dan 648 kabin."
  },
  AvgDialog_34974_Content_27 = {
    Text = "Mencari dari satu ruangan ke ruangan lainnya akan memakan waktu cukup lama…"
  },
  AvgDialog_34974_Content_28 = {
    Text = "Kapten, apakah kamu dan Celeste bisa melindungi diri sendiri? Aku harus segera berangkat untuk mencari Penjaga dan Murphy dengan kecepatan penuh. Semakin lama kita menemukan {Male=dia,Female=dia}, semakin besar kemungkinan {Male=dia,Female=dia} akan menghadapi bahaya."
  },
  AvgDialog_34974_Content_29 = {
    Text = "Elton menatap matanya yang berbeda warna dengan tekad yang kuat, dan setelah beberapa saat, dia tiba-tiba tertawa."
  },
  AvgDialog_34974_Content_3 = {
    Text = "Meskipun kekuatannya begitu lembut, ketika menarik Ramona ke dalam malam putih tanpa batas, terasa sangat kuat. Saat koordinat berubah dengan cepat, dia merasa isi perutnya hampir terpilin hingga berdarah."
  },
  AvgDialog_34974_Content_30 = {
    Text = "Jangan terlalu terburu-buru, siswi. Aku dan Celeste bisa mencoba lagi."
  },
  AvgDialog_34974_Content_31 = {Text = "Mau coba?"},
  AvgDialog_34974_Content_32 = {
    Text = "Celeste, cari tahu di mana semua orang berada."
  },
  AvgDialog_34974_Content_33 = {
    Text = "Celeste mendengarnya, dengan mata yang tak terbaca perasaannya menatap kapten selama beberapa saat, lalu mengangguk pelan dan mengangkat kompas tinggi-tinggi ——"
  },
  AvgDialog_34974_Content_34 = {
    Text = "Pembangun menutup matanya, cahaya putih berputar di tangannya, dan terdengar samar-samar suara burung laut yang memekik panjang…"
  },
  AvgDialog_34974_Content_35 = {Text = "Ukh……!"},
  AvgDialog_34974_Content_36 = {
    Text = "Kapten! Segera berhenti!"
  },
  AvgDialog_34974_Content_37 = {
    Text = "Seiring dengan erangan kesakitan Elton, cahaya tiba-tiba lenyap."
  },
  AvgDialog_34974_Content_38 = {
    Text = "Celeste melihat kapten, lalu melihat Ramona yang wajahnya penuh kecemasan, dan akhirnya dengan bingung menatap ujung jarinya sendiri."
  },
  AvgDialog_34974_Content_39 = {
    Text = "Ramona membantu kapten bangkit, dua jarinya menekan di sisi leher kapten untuk merasakan denyut nadinya, ekspresinya semakin berat."
  },
  AvgDialog_34974_Content_4 = {
    Text = "Hek, hek hek…"
  },
  AvgDialog_34974_Content_40 = {
    Text = "Membuat Tautan dengan Pembangun, menciptakan Domain, mempertahankan memori pelaut yang terdampar... Setiap kali Celeste menggunakan Kekuatan non-manusia, itu menguras Hidupmu."
  },
  AvgDialog_34974_Content_41 = {
    Text = "Apakah memindahkan kami beberapa orang dari lokasi ledakan Ruang Kekuatan... sudah menghabiskan kekuatan terakhir kalian?"
  },
  AvgDialog_34974_Content_42 = {
    Text = "Elton mengambil beberapa napas dalam-dalam, meredakan kejang pada otot jantungnya."
  },
  AvgDialog_34974_Content_43 = {
    Text = "——Lalu, ia mengangkat sebuah cangkir kayu berisi anggur ke hadapan Ramona. \n Entah dari mana dia mengeluarkan cangkir itu."
  },
  AvgDialog_34974_Content_44 = {
    Text = "Mau coba? Siapa tahu bisa meredakan tinnitus."
  },
  AvgDialog_34974_Content_45 = {
    Text = "...Tidak, peraturan sekolah Mythag tidak menganjurkan kami untuk minum alkohol."
  },
  AvgDialog_34974_Content_46 = {
    Text = "Kapten menunjukkan ekspresi yang tidak terkejut, mengangkat kepalanya dan meneguk habis minuman keras dalam cangkirnya. Cangkir itu kemudian dilemparkannya begitu saja ke lantai."
  },
  AvgDialog_34974_Content_47 = {
    Text = "Hek, hek hek hek…!"
  },
  AvgDialog_34974_Content_48 = {
    Text = "Anggur ini sangat menyengat."
  },
  AvgDialog_34974_Content_49 = {
    Text = "Menghubungkan Pembangun membutuhkan kekuatan roh yang sangat kuat. Bahkan Penyelidik yang telah menjalani pelatihan ketat dari Mythag harus memutus Tautan untuk mengembalikan energi setiap kali kembali ke sekolah, apalagi orang biasa…"
  },
  AvgDialog_34974_Content_5 = {
    Text = "Celeste menghela napas dan meletakkan kompas, dia duduk dengan bantuan kapten, kedua tangannya dilipat di atas paha, terlihat lebih lemah daripada sebelumnya."
  },
  AvgDialog_34974_Content_50 = {
    Text = "Kapten, tubuhmu…"
  },
  AvgDialog_34974_Content_51 = {
    Text = "Jangan khawatir, saat memilih Tautan Celeste, saya sudah siap secara mental bahwa hari ini akan tiba."
  },
  AvgDialog_34974_Content_52 = {
    Text = "Sekarang, senyuman Elton membawa sedikit rasa lega, seolah-olah seperti yang dia katakan: dia sudah siap untuk kedatangan malaikat maut."
  },
  AvgDialog_34974_Content_53 = {
    Text = "Celeste juga menutup matanya. Tubuhnya menjadi sedikit transparan, namun tautan antara dirinya dan kapten menjadi semakin cemerlang, kokoh, dan berkilau hingga hampir dapat dilihat dengan mata telanjang."
  },
  AvgDialog_34974_Content_55 = {
    Text = "Seiring dengan kelemahan bertahap dari Pembangun, Sonnelier kembali menjadi kayu apung di tengah badai, didorong oleh ombak raksasa satu per satu ke ketinggian yang tak terbayangkan."
  },
  AvgDialog_34974_Content_56 = {
    Text = "Sistem kelistrikan di kabin menjadi rapuh setelah serangan berulang, dan ketika busur listrik meledak untuk terakhir kalinya, ruang kabin tenggelam dalam kegelapan total."
  },
  AvgDialog_34974_Content_57 = {
    Text = "Segalanya tidak lagi terlihat jelas, hanya geraman rendah musuh yang terdengar sangat menusuk telinga."
  },
  AvgDialog_34974_Content_58 = {
    Text = "Ramona mengeluarkan senjatanya, memberi isyarat kepada dua orang di belakangnya untuk tetap diam. Dia sendiri mendekati sisi pintu, mengeluarkan senjata dan bersiap dengan waspada. Gerakan Gnosis membangkitkan suara berputarnya jam yang hampir tak terdengar."
  },
  AvgDialog_34974_Content_59 = {
    Text = "Persepsi terhadap waktu ditarik ke dalam tempat yang sunyi pada saat ini. Sarafnya begitu tegang hingga sulit baginya untuk membedakan berapa lama waktu telah berlalu — lima detik, dua puluh detik, satu menit? Atau mungkin waktu tak pernah dimulai kembali?"
  },
  AvgDialog_34974_Content_6 = {
    Text = "Bagaimana perasaanmu?"
  },
  AvgDialog_34974_Content_60 = {
    Text = "Kamu cepat lari ke depanku, biar aku menutup belakang. Jangan sampai mereka menyentuhmu."
  },
  AvgDialog_34974_Content_61 = {
    Text = "Masih perlu kau ingatkan! Lagipula, lampu di sini bahkan mati, mana mungkin ada orang. Sepertinya Ramona memang tidak di sini! Aku benar-benar percaya pada intuisimu… tapi hasilnya begini."
  },
  AvgDialog_34974_Content_62 = {
    Text = "Tidak... dia pasti berada di sekitar sini."
  },
  AvgDialog_34974_Content_63 = {
    Text = "Suara logam jatuh tiba-tiba terdengar. Sebelum kamu sempat bereaksi, pintu kabin di depanmu tiba-tiba dibuka dengan paksa dari dalam. Sepasang tangan menarikmu dan Murphy masuk ke dalam, satu di kiri dan satu di kanan."
  },
  AvgDialog_34974_Content_64 = {
    Text = "Kabel di dalam rangka dek kembali mengeluarkan suara operasi halus, bola lampu berkedip beberapa kali, dan akhirnya menyala dengan redup."
  },
  AvgDialog_34974_Content_65 = {
    Text = "Ramona dengan canggung mengambil pedang tipis yang terlepas saat ia panik, sambil menunjukkan senyuman terkejut di wajahnya."
  },
  AvgDialog_34974_Content_66 = {
    Text = "Kamu tidak apa-apa... sungguh melegakan."
  },
  AvgDialog_34974_Content_67 = {
    Text = "Aku kira... aku kira aku harus pergi ke laut lagi untuk bisa bertemu denganmu..."
  },
  AvgDialog_34974_Content_7 = {
    Text = "Celeste menggelengkan kepalanya tanpa bersuara. Dalam pikiran Ramona yang menjadi lambat akibat ledakan dan perpindahan koordinat, dia tidak bisa memastikan apakah responsnya berarti jawaban afirmatif."
  },
  AvgDialog_34974_Content_8 = {
    Text = "Melihat pandangan kedua orang itu beralih ke arahnya, Ramona baru saja hendak berbicara ketika tiba-tiba terdengar dengungan frekuensi rendah yang terus-menerus di telinganya. Bahkan, sinyal listrik yang mengganggu pun terasa hingga ke dalam otaknya."
  },
  AvgDialog_34974_Content_9 = {
    Text = "Umm... telingaku terasa sakit..."
  },
  AvgDialog_34975_Content_1 = {
    Text = "Ramona, tutupi aku! Aku akan memanggul Murphy, kita menyerang dari sisi lain!"
  },
  AvgDialog_34975_Content_2 = {
    Text = "Ramona sedang membelakangimu, sepenuhnya menghadapi serangan tak henti-hentinya dari Pelaut. Namun, punggungnya yang tegak dan tak tergoyahkan adalah jawaban terbaik."
  },
  AvgDialog_34975_Content_3 = {Text = "Hati-hati!"},
  AvgDialog_34975_Content_4 = {
    Text = "Melihat Pelaut hendak menyerang Ramona dari arah gelap, sang kapten tiba-tiba memutar kemudi sepenuhnya ke satu arah."
  },
  AvgDialog_34975_Content_5 = {
    Text = "Inersia membuat badan kapal bergoyang secara tiba-tiba, seperti seekor makhluk raksasa yang sedang panik dan bergerak liar. Barang-barang di dalam kabin terlempar ke satu sisi, menciptakan kekacauan di medan perang."
  },
  AvgDialog_34975_Content_6 = {
    Text = "Dengan bantuan Celeste, kamu kembali membuat Murphy berbaring di punggungmu. Sepertinya dia juga sudah memperkirakan bahwa kapten akan memutar kemudi sepenuhnya, menopang kalian dengan stabil saat kapal miring."
  },
  AvgDialog_34975_Content_7 = {
    Text = "Ramona mengayunkan pedangnya, menusuk dada penyerang, lalu menoleh sekilas ke belakang dan memberi kalian anggukan."
  },
  AvgDialog_34976_Content_1 = {
    Text = "Kabut tebal menyelimuti permukaan laut, namun dek kapal disinari dengan terang oleh cahaya bulan purnama, sehingga ekspresi sekecil apa pun dapat dengan mudah ditangkap."
  },
  AvgDialog_34976_Content_10 = {
    Text = "Baru berjalan beberapa langkah, terdengar suara \"dong\" dari belakang. Ketika semua orang menoleh, mereka melihat Murphy berlutut dengan kedua lutut di atas dek, tubuh bagian atasnya juga jatuh lemas ke depan, hampir menempel pada dek."
  },
  AvgDialog_34976_Content_11 = {Text = "Murphy?!"},
  AvgDialog_34976_Content_12 = {
    Text = [[
Kamu berlari cepat ke arahnya dan menopang Murphy yang terkulai di atas dek. 
 Kesadaran Murphy sudah tidak jelas, poninya basah oleh keringat dingin, dan tampak sangat kacau menempel di dahinya.]]
  },
  AvgDialog_34976_Content_13 = {
    Text = "@1…sakit sekali…"
  },
  AvgDialog_34976_Content_14 = {
    Text = "Umm…@1…@1……"
  },
  AvgDialog_34976_Content_15 = {
    Text = "Dia menggenggam erat tanganmu yang menopangnya, rasa sakit membuatnya secara tidak sadar mengeratkan jari-jarinya, lima jarinya menancap ke dalam dagingmu, namun kamu tak terlalu memperhatikan sedikit rasa sakit itu."
  },
  AvgDialog_34976_Content_16 = {
    Text = "Kamu mendengar ketukan drum yang semakin keras — otot parasit yang tidak termasuk dalam jaringan tubuh manusia bersemayam di rongga dada gadis itu, berdenyut dengan hidupnya sebagai nutrisi."
  },
  AvgDialog_34976_Content_17 = {
    Text = "\"Dewa\"…sedang menghisap hidupnya."
  },
  AvgDialog_34976_Content_18 = {
    Text = "Mi…@2……"
  },
  AvgDialog_34976_Content_19 = {
    Text = "Di jantungnya bersemayam inti Clades. Jika ini terus berlanjut, dia…"
  },
  AvgDialog_34976_Content_2 = {Text = "Bulan…"},
  AvgDialog_34976_Content_20 = {
    Text = "Kamu menengadah ke arah jendela persegi di ruang kemudi bagian atas, di dalamnya gelap gulita, dari kejauhan terlihat seperti mulut paus raksasa yang mampu melahap cahaya."
  },
  AvgDialog_34976_Content_21 = {
    Text = "Murphy, bisakah kamu mendengar aku berbicara?"
  },
  AvgDialog_34976_Content_22 = {Text = "Murphy?"},
  AvgDialog_34976_Content_23 = {
    Text = "Dengan kehendak-Nya…@2……"
  },
  AvgDialog_34976_Content_24 = {
    Text = "Pernapasan Murphy kehilangan ritmenya, ia terjebak dalam mimpi yang cemas dan berbahaya, tidak menjawab panggilanmu."
  },
  AvgDialog_34976_Content_25 = {
    Text = "...Harus bertahan."
  },
  AvgDialog_34976_Content_26 = {
    Text = "Murid, biarkan aku yang memikulnya."
  },
  AvgDialog_34976_Content_27 = {
    Text = [[
Tubuhmu lebih lemah dari milikku, biarkan aku yang melakukan, Ramona tetap waspada di sekeliling.
Aku telah dilatih untuk membawa beban, berat Murphy bisa kutanggung.]]
  },
  AvgDialog_34976_Content_28 = {
    Text = "Elton juga tidak memaksakan diri lagi. Dengan bantuannya, kamu menopang lutut Murphy dengan kedua tanganmu, membiarkannya berbaring di punggungmu."
  },
  AvgDialog_34976_Content_29 = {
    Text = "Kamu menggunakan seluruh kekuatan tubuhmu untuk menopang Murphy, menghirup napas dalam-dalam, dan bersiap untuk melangkah naik tangga—"
  },
  AvgDialog_34976_Content_3 = {
    Text = "Apa yang terjadi dengan bulan?"
  },
  AvgDialog_34976_Content_30 = {
    Text = "Gadis yang dalam kondisi pingsan berbaring di punggungmu, gumaman samar terus mengalun melewati telingamu."
  },
  AvgDialog_34976_Content_31 = {
    Text = "Dewa…@2…@4……"
  },
  AvgDialog_34976_Content_32 = {
    Text = [[
Selain mengerang kesakitan, Murphy hanya bisa mengucapkan kata-kata tanpa makna yang jelas.
Di tengah gumaman kacau ini, musuh muncul dari bayangan.]]
  },
  AvgDialog_34976_Content_4 = {
    Text = "Semakin terang, dan juga…"
  },
  AvgDialog_34976_Content_5 = {
    Text = "Murphy menelan sisa kalimatnya, tapi kamu tahu apa yang ingin dia katakan——"
  },
  AvgDialog_34976_Content_6 = {
    Text = "Waktu yang tersisa untuknya semakin berkurang."
  },
  AvgDialog_34976_Content_7 = {
    Text = "Cepat pergi ke ruang kemudi. Kapten, langkah selanjutnya bergantung pada arahan Anda."
  },
  AvgDialog_34976_Content_8 = {
    Text = "Kita perlu menyeberangi dek dan menuju lantai tertinggi jembatan kapal."
  },
  AvgDialog_34976_Content_9 = {
    Text = "Ramona mengangguk, melindungi kapten sambil melangkah maju."
  },
  AvgDialog_34977_Content_1 = {
    Text = "Aaa——! %player%, cepat pikirkan cara, mereka sedang menangkap sepatu botku!"
  },
  AvgDialog_34977_Content_2 = {
    Text = "Pergi ke ruang kabin di sana, gunakan pintu kabin untuk menahan mereka di luar!"
  },
  AvgDialog_34978_Content_1 = {
    Text = "Pembantaian"
  },
  AvgDialog_34978_Content_10 = {
    Text = "Panti yatim..."
  },
  AvgDialog_34978_Content_100 = {
    Text = "Apa yang begitu menakutkan!"
  },
  AvgDialog_34978_Content_101 = {
    Text = "Seorang gadis merangkak keluar dari bawah rok Celeste, membuatku hampir terjatuh karena kaget."
  },
  AvgDialog_34978_Content_102 = {
    Text = "Dia tampak... sangat familiar. Aku bersumpah, aku pasti pernah melihatnya di suatu tempat."
  },
  AvgDialog_34978_Content_103 = {
    Text = "Celeste, apakah kamu yang mengizinkan gadis kasar ini naik ke kapal?"
  },
  AvgDialog_34978_Content_104 = {
    Text = "Berhenti memanggil! Apakah kamu sengaja ingin para Pelaut mendengarnya!"
  },
  AvgDialog_34978_Content_105 = {
    Text = "Dan siapa yang kau sebut gadis kasar! Nama saya adalah Murphy, Murphy!"
  },
  AvgDialog_34978_Content_106 = {
    Text = "Aku ingat, di suatu upacara yang tersembunyi jauh di dalam memori, aku pernah melihatnya."
  },
  AvgDialog_34978_Content_107 = {
    Text = "Setelah \"Dewa Ibu\" terganggu oleh pelarutan, Miryam memilih \"induk\" baru untuk embrio dewa, lalu membuat \"induk\" tersebut jatuh ke dalam tidur panjang selama lebih dari dua puluh tahun."
  },
  AvgDialog_34978_Content_108 = {
    Text = "Seiring dengan posisi bintang yang semakin selaras, imam utama membangunkannya dari tidur. Inventaris yang diangkut kali ini adalah persiapan untuk \"upacara penurunan dewa\"."
  },
  AvgDialog_34978_Content_109 = {
    Text = "Bayi yang kupegang erat dan kuberi air saat badai akan selamanya kehilangan kesempatan untuk tumbuh dewasa."
  },
  AvgDialog_34978_Content_11 = {
    Text = "Tidak, tidak akan. Keluarga…"
  },
  AvgDialog_34978_Content_110 = {
    Text = "Aku tahu kalian, kalian bukan Pelaut, hanya mitra pengangkutan... asalkan kalian bisa membawaku pergi dari sini, semakin jauh semakin baik — semua harta ini akan menjadi milikmu."
  },
  AvgDialog_34978_Content_111 = {
    Text = "Seperti sulap, dia mengeluarkan beberapa patung dari tasnya — ukiran kayu yang kasar dan membuat orang merasa pusing hanya dengan melihat sekilas. Patung-patung itu sangat diagungkan oleh Pelaut, namun di mata orang luar, mereka tidak bernilai."
  },
  AvgDialog_34978_Content_112 = {
    Text = "Murphy… akan pergi bersama kami."
  },
  AvgDialog_34978_Content_113 = {
    Text = "Dia... pelarutan..."
  },
  AvgDialog_34978_Content_115 = {
    Text = "Korban dari zaman lama, korban praktik biadab, kerabat jauh nenek moyang saya, satu-satunya bukti bahwa \"Rumah\" pernah ada."
  },
  AvgDialog_34978_Content_116 = {
    Text = "\"Diri\" Celeste telah terkunci jauh di dalam Jiwa-nya oleh pengalaman hidupnya sebelum meninggal. Aku tidak punya alasan untuk menolak permintaan pertama yang diajukannya padaku."
  },
  AvgDialog_34978_Content_117 = {Text = "Apalagi..."},
  AvgDialog_34978_Content_118 = {
    Text = "Berangkatlah, Celeste."
  },
  AvgDialog_34978_Content_119 = {
    Text = "Kamu, apakah kamu setuju untuk membawaku pergi?"
  },
  AvgDialog_34978_Content_12 = {
    Text = [[
Apa kamu benar-benar kehilangan ingatan? Kita sudah bermain di jalan ini sejak kecil. 
Aku bahkan memanjat tembok untuk membawakan makanan ke panti asuhan tempatmu, dan dikejar-kejar biarawati sejauh tiga blok. Apakah kamu lupa semuanya?]]
  },
  AvgDialog_34978_Content_120 = {
    Text = "Karena Celeste menginginkannya, aku akan berusaha untuk mengirim kamu sejauh mungkin."
  },
  AvgDialog_34978_Content_121 = {
    Text = "Wow... begitu memanjakannya?"
  },
  AvgDialog_34978_Content_122 = {
    Text = "Anak muda yang tidak sopan. Ketahuilah, aku bisa saja mengubah pikiran kapan saja dan melemparmu ke laut es."
  },
  AvgDialog_34978_Content_123 = {
    Text = "Kikir... Nona ini tidak bisa tidak bertanya, kan..."
  },
  AvgDialog_34978_Content_124 = {
    Text = "Apalagi... aku sendiri yang membawa Murphy ke jalan ini."
  },
  AvgDialog_34978_Content_125 = {
    Text = "Sebuah jalan penuh pelarutan, menuju kehancuran dan dilupakan."
  },
  AvgDialog_34978_Content_126 = {
    Text = "Saya harus menebus dosa ini."
  },
  AvgDialog_34978_Content_14 = {
    Text = [[
Maaf, teman. Mungkin aku sedang merasakan gejala homesick, akhir-akhir ini sering menganggap mimpi sebagai kenyataan. 
 Sudah lama kita tidak bertemu, bagaimana kalau hari ini kita pergi ke tempat lama dan minum beberapa gelas?]]
  },
  AvgDialog_34978_Content_15 = {
    Text = [[
Hehe, Paman John tahun lalu berhasil membuat rasa baru untuk wiski, rasanya sangat enak! 
 Hari ini kita tetap seperti biasa, minum sampai puas!]]
  },
  AvgDialog_34978_Content_16 = {
    Text = "Baiklah... tidak pulang sebelum mabuk."
  },
  AvgDialog_34978_Content_17 = {
    Text = "Saya tidak tahu apa-apa tentang tambang, belum pernah ke panti asuhan mana pun, dan juga tidak mengenal Old John dari tempat lama."
  },
  AvgDialog_34978_Content_18 = {
    Text = "Aku hanya tahu, segala sesuatu tentang kota kecil itu semakin menjauh."
  },
  AvgDialog_34978_Content_19 = {
    Text = "Masa kecilku, orang tuaku, saudara-saudaraku, semuanya dianggap oleh orang lain sebagai mimpi yang tidak masuk akal."
  },
  AvgDialog_34978_Content_2 = {
    Text = [[
A.F.2@1 Tahun Awal Musim Gugur 
 Selatan Kerajaan Leo]]
  },
  AvgDialog_34978_Content_20 = {
    Text = "Bahkan aku sendiri hampir mempercayainya."
  },
  AvgDialog_34978_Content_21 = {
    Text = "Namun, mana mungkin ada mimpi yang begitu sulit untuk dilupakan di dunia ini?"
  },
  AvgDialog_34978_Content_22 = {
    Text = [[
A.F.2@2 Tahun Akhir Musim Dingin 
 "Pelaut" Sekte, Elworth Sanctuary]]
  },
  AvgDialog_34978_Content_23 = {
    Text = "Kali ini, barang yang dikirim adalah pasokan sehari-hari dan... sembilan belas bahan eksperimen gagal, disediakan oleh... gereja"
  },
  AvgDialog_34978_Content_24 = {
    Text = "Informasi dari pihak penyedia telah basah terkena air laut dan tidak dapat dibaca dengan jelas. Apakah kalian masih ingin mengonfirmasi penerimaannya?"
  },
  AvgDialog_34978_Content_25 = {
    Text = "Konfirmasi... tanpa kesalahan..."
  },
  AvgDialog_34978_Content_26 = {
    Text = [[
Belum habis suaraku, orang yang membungkukkan tubuh di depanku segera merampas daftar barang dari tanganku. 
 Sepertinya dia tidak peduli dengan apa yang kukatakan, hanya bergumam tidak jelas sambil mengulang-ulang "konfirmasi".]]
  },
  AvgDialog_34978_Content_27 = {
    Text = "Angin kutub yang ganas meniupkan tudung penyambung, memperlihatkan kepala yang sangat buruk rupa."
  },
  AvgDialog_34978_Content_28 = {
    Text = "Mata yang besar dan menonjol, kelopak mata tak bisa tertutup, jaringan seperti rahang menghubungkan dagu dan tulang selangka, terlihat seperti ikan yang hidup."
  },
  AvgDialog_34978_Content_29 = {
    Text = "Menahan rasa jijik dan mual di dalam hati, aku terpaksa melepas topi untuk memberi hormat kepada orang itu."
  },
  AvgDialog_34978_Content_3 = {
    Text = "Bagaimana mungkin kamu belum pernah mendengar tentang kota kecil itu!?"
  },
  AvgDialog_34978_Content_30 = {
    Text = "Jika tidak ada hal lain, malam ini kapal Sonaniel akan kembali berlayar, dan pasokan berikutnya akan tiba di Elworth sekitar 114 hari lagi."
  },
  AvgDialog_34978_Content_31 = {
    Text = "@1… mohon Anda, semoga Anda… selamat sampai tujuan…"
  },
  AvgDialog_34978_Content_32 = {
    Text = "……Tunggu."
  },
  AvgDialog_34978_Content_33 = {
    Text = "Saat akan kembali ke kapal, sebuah suara wanita yang terdengar sedikit asing memanggilku."
  },
  AvgDialog_34978_Content_34 = {
    Text = [[
Dia adalah seorang wanita dewasa yang mengenakan selubung hitam, pakaiannya terlalu tipis, bahkan dia tidak mengenakan alas kaki. 
Di tempat yang sangat dingin di Planet Elworth, penampilannya tampak sangat tidak sesuai.]]
  },
  AvgDialog_34978_Content_35 = {
    Text = "Pemimpin Upacara, Pemimpin Upacara…"
  },
  AvgDialog_34978_Content_36 = {
    Text = "Pelaut yang sedang berada di tepi laut tiba-tiba berlutut, tubuhnya menabrak batu hitam yang dingin dan keras, suara itu membuat telinga terasa nyeri."
  },
  AvgDialog_34978_Content_37 = {
    Text = "Selama sepuluh tahun berlayar, dengan kerja keras, keberuntungan, dan beberapa pekerjaan yang tidak terlalu terhormat, aku berhasil memiliki kapal sendiri dan menjadi seorang kapten. Namun, di dalam sekte rahasia ini, status sebagai kapten tidak memiliki nilai apa pun."
  },
  AvgDialog_34978_Content_38 = {
    Text = "Meskipun saya belum pernah bertemu dengan para petinggi ordo, dari reaksi Pelaut di sekitar saya, saya tahu bahwa status orang yang datang ini sangatlah tinggi."
  },
  AvgDialog_34978_Content_39 = {
    Text = "Maka aku meniru cara dia dan berlutut tanpa ragu."
  },
  AvgDialog_34978_Content_4 = {
    Text = "Di muara sungai @2, dengan gunung @3 di belakangnya… itu adalah tempat kami berdua dibesarkan!"
  },
  AvgDialog_34978_Content_40 = {
    Text = "Yang Terhormat Pemimpin Upacara."
  },
  AvgDialog_34978_Content_41 = {
    Text = [[
Di sekitarmu, terdapat jiwa-jiwa yang menghilang. 
 Wahai nahkoda, apakah kau membawa benda peninggalan orang mati?]]
  },
  AvgDialog_34978_Content_42 = {
    Text = "Relik Peninggalan..."
  },
  AvgDialog_34978_Content_43 = {
    Text = "Berdasarkan petunjuk dari pemimpin upacara, saya membuka penutup jam saku, bagian yang seharusnya menjadi dial tertutup oleh aliran perak cair yang bergerak."
  },
  AvgDialog_34978_Content_44 = {
    Text = "Benar, meskipun Gnosis yang terkandung di dalamnya sangat lemah… tapi tidak diragukan lagi, ini adalah Perak."
  },
  AvgDialog_34978_Content_45 = {
    Text = "Di setiap Perak, terkandung sebuah kenangan yang terlupakan… Apakah kamu ingin Bangun Perak ini?"
  },
  AvgDialog_34978_Content_46 = {
    Text = "Kenangan yang terlupakan..."
  },
  AvgDialog_34978_Content_47 = {
    Text = "Masa laluku ditolak oleh semua orang. Cairan perak yang kudapat dari <Yellow:rawa yang pernah menjadi Rumahku> mungkin adalah petunjuk terakhirku."
  },
  AvgDialog_34978_Content_48 = {
    Text = "Saya ingin…! Mohon Pemimpin Upacara tidak segan-segan untuk memberikan bimbingan."
  },
  AvgDialog_34978_Content_49 = {
    Text = "Selesaikan misi pengiriman berikutnya… dengan begitu, aku akan memberikan metode untuk Bangun Perak kepadamu."
  },
  AvgDialog_34978_Content_5 = {
    Text = [[
Setelah bertahun-tahun berlayar, apakah kau tidak bertemu dengan Siren sampai kehilangan akal sehat? 
Tempat yang kau maksudkan aku tahu, sejak awal era Hongji sudah menjadi rawa.]]
  },
  AvgDialog_34978_Content_50 = {
    Text = "Bawalah <Yellow:harapan>ku ke sisiku."
  },
  AvgDialog_34978_Content_51 = {
    Text = [[
Pelaut utama Miryam memberi saya tugas baru. 
 Muatan yang diangkut dalam pelayaran itu berubah menjadi seorang <Yellow:bayi perempuan>.]]
  },
  AvgDialog_34978_Content_52 = {
    Text = [[
Sebelum ini, aku hanya pernah memeluk adik-adikku dalam "mimpi". 
Sayangnya, kenangan bahagia dan damai itu juga sudah menghilang seiring dengan bangun dari mimpi.]]
  },
  AvgDialog_34978_Content_53 = {
    Text = "Perjalanan diperpanjang oleh angin barat. Pada minggu terakhir di laut, semua air tawar diberikan kepada si kecil ini."
  },
  AvgDialog_34978_Content_54 = {
    Text = "Dia tidak memedulikan jenggotku yang kusut, tertawa sambil berbaring di pangkuanku."
  },
  AvgDialog_34978_Content_55 = {
    Text = "Aku menyerahkannya kepada pemimpin upacara."
  },
  AvgDialog_34978_Content_56 = {
    Text = [[
A.F.3@1 Tahun Titik Balik Matahari Musim Panas 
 Samudra Atlas]]
  },
  AvgDialog_34978_Content_57 = {
    Text = "Kapten! Semua kompas tidak berfungsi, dan kemudi juga rusak terbawa ombak!"
  },
  AvgDialog_34978_Content_58 = {
    Text = "Ketel, air masuk ke boiler! Kita kehilangan tenaga!"
  },
  AvgDialog_34978_Content_59 = {
    Text = "Apa yang kamu lakukan?! Sekarang kita benar-benar dalam masalah, kita tidak bisa berbelok, arus laut sedang mendorong kita ke dalam badai petir!"
  },
  AvgDialog_34978_Content_6 = {Text = "Rawa?"},
  AvgDialog_34978_Content_60 = {
    Text = "Semuanya diam! Sekarang bukan saatnya untuk saling menyalahkan!"
  },
  AvgDialog_34978_Content_61 = {
    Text = [[
Wakil kapten, bawa para pelaut untuk menurunkan sekoci. 
Satu perahu harus membawa lebih banyak orang, berusaha sekuat tenaga untuk mendayung menjauh sebelum terhisap ke dalam pusaran air.]]
  },
  AvgDialog_34978_Content_62 = {
    Text = "Di mana kapten?"
  },
  AvgDialog_34978_Content_63 = {
    Text = "...kalian segera menarik diri."
  },
  AvgDialog_34978_Content_64 = {
    Text = "@Setelah 2 tahun berlalu, aku mencoba berkali-kali sesuai dengan metode rahasia yang diajarkan oleh pemimpin upacara, namun aku tak pernah bisa membuat Perak itu bersinar."
  },
  AvgDialog_34978_Content_65 = {
    Text = "Kegagalan yang berkepanjangan dan kesibukan dalam realitas telah hampir membuatku menyerah untuk menemukan kebenaran… kebenaran di balik menghilangnya Rumah."
  },
  AvgDialog_34978_Content_66 = {
    Text = "Saya mengirim sebagian besar awak kapal ke perahu penyelamat, lalu dengan kerinduan akan masa lalu, tenggelam bersama kapal Sonaniel."
  },
  AvgDialog_34978_Content_67 = {
    Text = "Dalam tenggelam yang terus-menerus, angin menyapu wajahku."
  },
  AvgDialog_34978_Content_68 = {
    Text = "Angin mendorong keluar air laut yang memenuhi paru-paru, meniupkan butiran garam yang mengikis luka, dan di dalam Aequor, mengangkat mimpi yang tenggelam."
  },
  AvgDialog_34978_Content_69 = {
    Text = "Lalu, aku melihat seorang gadis yang dikelilingi oleh angin sejuk dan burung-burung putih."
  },
  AvgDialog_34978_Content_7 = {
    Text = "Benar! Konon katanya, dulunya ada tambang di sana, tetapi hancur karena banjir besar saat aliran sungai berubah arah. Dua tahun lalu, seorang bangsawan membeli tanah itu, kabarnya ingin membangun sebuah taman."
  },
  AvgDialog_34978_Content_70 = {
    Text = "\"Nama saya Celeste, selama kamu masih membutuhkanku, aku akan tetap ada di sini.\""
  },
  AvgDialog_34978_Content_71 = {
    Text = [[
Dia adalah jejak dari tanah kelahiran yang pernah ada, sebuah dongeng yang kudengar dari mulut orang tua saat kecil. 
Dia membuatku menyadari bahwa masa lalu yang selalu kurindukan benar-benar nyata.]]
  },
  AvgDialog_34978_Content_72 = {
    Text = "Kedatangannya akhirnya membuktikan bahwa aku bukan orang gila yang tidak memiliki asal-usul."
  },
  AvgDialog_34978_Content_73 = {
    Text = [[
Tiga bulan yang lalu
"Pelaut"ordo, Elworth Sanctuary]]
  },
  AvgDialog_34978_Content_74 = {
    Text = "Pasokan 135 kotak dari cabang Neo-Leo, 12 persembahan dari asosiasi, dan 120 kotak makanan yang dibeli dari Pulau Horn… sudah dikonfirmasi tanpa kesalahan."
  },
  AvgDialog_34978_Content_75 = {
    Text = "Hek, hek hek…"
  },
  AvgDialog_34978_Content_76 = {
    Text = "Anda adalah anggota penting dari ordo, harap jaga tubuh Anda dengan baik."
  },
  AvgDialog_34978_Content_77 = {
    Text = "Ngomong-ngomong, Ordo sudah menyelesaikan pembuatan batch baru <Blue:Ramuan Stabil> lebih awal, dan sudah diserahkan ke tangan saya. Saya akan segera memberikan jatah Anda untuk kuartal ini kepada—"
  },
  AvgDialog_34978_Content_78 = {
    Text = "Shh——simpan hingga waktu yang telah kita sepakati, lalu serahkan padaku. Tempat yang sama, <Yellow:Deretan Pelabuhan Ketiga Brillerport Utara Dua>."
  },
  AvgDialog_34978_Content_79 = {
    Text = "Aku dan Celeste akan menunggumu di sana. Kali ini kami berencana pergi ke Laut Dalam untuk mengambil beberapa bahan makanan khas. Bagaimana kalau saat bertemu di pelabuhan, kamu naik ke kapal untuk mencicipi masakanku?"
  },
  AvgDialog_34978_Content_8 = {
    Text = "Tapi... rumahku..."
  },
  AvgDialog_34978_Content_80 = {
    Text = "Kehormatan, sangat terhormat."
  },
  AvgDialog_34978_Content_81 = {
    Text = "Dengarlah, Miryam telah Bangun <Blue:Dewi Ibu> dari tidurnya hari ini untuk menyambut saat bintang-bintang Selaras berikutnya, menyambut kebangkitan Tuan kami."
  },
  AvgDialog_34978_Content_82 = {
    Text = "Tiga bulan ke depan, kemungkinan besar akan sangat sibuk baik di dalam maupun di luar ordo. Namun, saya pasti akan menepati janji saya kepada Anda."
  },
  AvgDialog_34978_Content_83 = {
    Text = "Baiklah, itu sudah disepakati. Tiga bulan lagi, jangan sampai tidak bertemu."
  },
  AvgDialog_34978_Content_84 = {
    Text = "Pemuda yang dulu mengalirkan darah Pelaut, namun kini telah menjadi tubuh golem, tersenyum malu-malu — bagi saya, Caecus memang masih seorang anak."
  },
  AvgDialog_34978_Content_85 = {
    Text = "Mirip dengan saudara yang pernah ada dalam memori saya, dia juga seorang pemuda yang pemalu dan sensitif."
  },
  AvgDialog_34978_Content_86 = {
    Text = "Laut Wild akan segera berangin, saya sarankan Anda segera kembali. Kami tidak bisa menahan Anda untuk bermalam."
  },
  AvgDialog_34978_Content_87 = {
    Text = "Ya, aku tidak ingin berangkat dari pelabuhan dalam badai es."
  },
  AvgDialog_34978_Content_88 = {
    Text = "Berpisah dengan Caecus, aku berpapasan dengan \"barang\" terakhir yang sedang dipindahkan, lalu melangkah menaiki jembatan menuju kapal."
  },
  AvgDialog_34978_Content_89 = {
    Text = "Benda itu masih bernapas, kain putihnya bergerak naik turun dengan lemah. Seiring tetesan cairan hitam pekat, sesuatu juga perlahan-lahan memudar."
  },
  AvgDialog_34978_Content_9 = {
    Text = "Begitu mencapai usia untuk meninggalkan panti asuhan, kamu langsung berlayar. Meskipun kamu belum kembali selama belasan tahun, tidak mungkin kamu melupakan semuanya begitu saja, kan? Apakah kamu sakit?"
  },
  AvgDialog_34978_Content_90 = {
    Text = [[
Kendalikan rasa ingin tahumu, Elton!
Jangan <Red:melihat>.
Jangan <Red:memikirkan>.
<Big:Jangan><RedBig:menghadapinya>.]]
  },
  AvgDialog_34978_Content_91 = {
    Text = "Celeste, aku sudah kembali."
  },
  AvgDialog_34978_Content_93 = {
    Text = "Sudah waktunya untuk kembali, mari kembali ke tempat semula."
  },
  AvgDialog_34978_Content_95 = {Text = "Celeste?"},
  AvgDialog_34978_Content_96 = {
    Text = "Baik, menuju Republik aglo… berlayar."
  },
  AvgDialog_34978_Content_97 = {
    Text = [[
Tidak, tidak, tujuannya adalah <Blue:Laut dalam>, kita akan mengambil beberapa bahan makanan lokal kali ini. 
 Kenapa kamu tampak tidak fokus? Apa ada sesuatu yang terjadi di kapal?]]
  },
  AvgDialog_34978_Content_98 = {
    Text = "... Hmm, Laut dalam, berlayar."
  },
  AvgDialog_34978_Content_99 = {
    Text = "Celeste! Lihat aku!"
  },
  AvgDialog_34979_Content_1 = {
    Text = [[
Kapten, musuh di sini sudah selesai. 
Aku dan Penjaga akan melihat lebih jauh ke depan, kamu bisa membawa Murphy dan Celeste untuk mengikuti.]]
  },
  AvgDialog_34979_Content_10 = {
    Text = [[
Tapi kamu... bukankah kamu sangat menyukainya? 
 Kamu sering datang untuk merawat mesinnya, aku sudah melihat semuanya.]]
  },
  AvgDialog_34979_Content_11 = {
    Text = "Eh, eh! Apa yang kamu lakukan——"
  },
  AvgDialog_34979_Content_12 = {
    Text = "Elton membungkuk dan mencubit otot wajah Murphy yang kencang."
  },
  AvgDialog_34979_Content_13 = {
    Text = "Jika kamu ingin mengganti semua kerugian saya, bertahanlah hidup."
  },
  AvgDialog_34979_Content_14 = {
    Text = "Setelah Elton selesai berbicara, dia tidak memberi Murphy kesempatan untuk bereaksi. Dia mengulurkan tangan dan mendorong punggung Murphy, membuatnya tersandung dan terhuyung-huyung ke depan, meninggalkan ruang kabin yang gelap dan menyeramkan seperti Jurang yang dalam."
  },
  AvgDialog_34979_Content_15 = {
    Text = "Murphy berdiri di samping pintu ruang kargo lainnya, mengamati gerakan kapten dari seberang koridor yang lebarnya hanya sekitar satu meter."
  },
  AvgDialog_34979_Content_16 = {
    Text = "Dia pertama-tama membantu Celeste meninggalkan ruangan yang dipenuhi dengan pertumbuhan abnormal, lalu menyerahkannya kepada Murphy, sebelum kembali melangkah ke dalam kegelapan untuk menarik pintu ruangan."
  },
  AvgDialog_34979_Content_17 = {Text = "Kapten..."},
  AvgDialog_34979_Content_18 = {
    Text = "Kenapa masih menatapku? Kedua siswa itu akan segera pergi jauh."
  },
  AvgDialog_34979_Content_19 = {
    Text = "Benarkah? Kamu dan Celeste mengambil risiko hidup untuk membantuku, kamu benar-benar—tidak meminta imbalan dariku?"
  },
  AvgDialog_34979_Content_2 = {
    Text = "Baik, terima kasih atas bantuannya."
  },
  AvgDialog_34979_Content_20 = {
    Text = "Anak ini..."
  },
  AvgDialog_34979_Content_21 = {
    Text = "Kapten——Murphy——kenapa belum menyusul?"
  },
  AvgDialog_34979_Content_22 = {
    Text = "Segera datang!"
  },
  AvgDialog_34979_Content_23 = {
    Text = "Akhirnya, dia menutup pintu di belakangnya, dan cahaya fluoresen yang terpantul pada mantelnya juga menghilang."
  },
  AvgDialog_34979_Content_24 = {
    Text = [[
Kalau begitu, hiduplah dengan baik dan tumbuh dewasa dengan baik. Setelah dewasa, bekerja dan hasilkan cukup uang. 
Lalu, belikan aku mobil model terbaru sebagai ganti rugi.]]
  },
  AvgDialog_34979_Content_3 = {
    Text = "Elton melihat dari samping pintu kabin, setelah memastikan bahwa area depan untuk sementara aman, dia kemudian melambaikan tangan kepada Murphy dan Celeste."
  },
  AvgDialog_34979_Content_4 = {
    Text = "Pada saat terakhir sebelum meninggalkan ruang kargo, Elton menghentikan langkahnya. Dia berbalik untuk melihat kendaraan yang rusak akibat pertumbuhan berbentuk Sanga, dengan nada suara yang mengungkapkan rasa penyesalan."
  },
  AvgDialog_34979_Content_5 = {
    Text = "Ini adalah model mesin empat-silinder yang masih dalam tahap eksperimen… Sayang sekali, si cantik ini belum pernah benar-benar melaju di daratan."
  },
  AvgDialog_34979_Content_7 = {
    Text = "Murphy menggigit bibir bawahnya, memandang sedan yang jelas-jelas sudah rusak parah, lalu dengan hati-hati mencuri beberapa pandangan ke arah Elton."
  },
  AvgDialog_34979_Content_8 = {
    Text = "Kenapa menunjukkan ekspresi seperti ini?"
  },
  AvgDialog_34979_Content_9 = {
    Text = "Apa yang kamu takutkan? Tenang saja, aku tidak berniat meminta ganti rugi mobil baru darimu."
  },
  AvgDialog_34980_Content_1 = {
    Text = "Bulan Krisis"
  },
  AvgDialog_34980_Content_10 = {
    Text = "Kami percaya padamu."
  },
  AvgDialog_34980_Content_11 = {Text = "Murid..."},
  AvgDialog_34980_Content_12 = {
    Text = "Selama ratusan tahun, Universitas Mythag tidak pernah berhenti melawan Fenomena-d, dan tak terhitung banyaknya Penyelidik telah mengorbankan Hidup mereka untuk ini."
  },
  AvgDialog_34980_Content_13 = {
    Text = "Di antara mereka, ada yang telah gugur karena Pelarutan… Memori dunia tentang mereka semakin memudar, bahkan surat-surat yang mereka tinggalkan pun sulit terhindar dari D-marka."
  },
  AvgDialog_34980_Content_14 = {
    Text = "Apakah kalian berdua tidak merasa takut?"
  },
  AvgDialog_34980_Content_15 = {
    Text = "Takut... tentu saja takut. Siapa yang tidak takut menghilang sepenuhnya dari dunia ini?"
  },
  AvgDialog_34980_Content_16 = {
    Text = "Namun, seseorang harus mengumpulkan keberanian untuk menghadapi semua ini, bukankah begitu?"
  },
  AvgDialog_34980_Content_17 = {
    Text = "Jika kita semua mundur, bagaimana dengan para pendahulu yang telah gugur dalam penyelidikan kami, mereka yang menghilang karena pelarutan…"
  },
  AvgDialog_34980_Content_18 = {
    Text = "Jika kita semua menyerah, maka keberadaan mereka akan benar-benar kehilangan maknanya."
  },
  AvgDialog_34980_Content_19 = {
    Text = "Untuk masa depan kita, juga untuk mereka yang telah menghilang, baik itu dugaan yang tampak mustahil sekalipun, kita akan memperlakukannya sebagai fakta untuk dilakukan Penyelidikan."
  },
  AvgDialog_34980_Content_2 = {
    Text = "Pengakuan Elton membuatmu dan Ramona kehilangan suara. Kamu terdiam menatap Ramona, dan dari mata satu sama lain, kalian membaca kejutan yang sama."
  },
  AvgDialog_34980_Content_20 = {Text = "Heh……"},
  AvgDialog_34980_Content_21 = {
    Text = "Tampaknya di dunia ini, orang-orang gila masih menjadi mayoritas."
  },
  AvgDialog_34980_Content_22 = {
    Text = "Uuuuh————"
  },
  AvgDialog_34980_Content_23 = {
    Text = [[
Deru peluit meledak di telinga, semua orang terkejut. 
Elton adalah yang pertama bereaksi dan langsung menuju ke konsol, mencoba menarik tuas peluit secara manual untuk menghentikannya.]]
  },
  AvgDialog_34980_Content_24 = {
    Text = [[
Astaga! Jalur kontrol sirene rusak karena terkena serangan karang Sanga! 
Dengan suara sebesar ini, mereka pasti akan segera menyadari bahwa ada orang di ruang kemudi.]]
  },
  AvgDialog_34980_Content_25 = {
    Text = "Ramona berlari keluar dari ruang kemudi, kamu juga ikut berlari keluar, dan bersamaan dengannya memegang tepi kapal untuk melihat ke bawah——"
  },
  AvgDialog_34980_Content_26 = {
    Text = "Pelaut yang berkeliaran di dek bawah semuanya menengadah, sepasang mata ikan tanpa jiwa bertemu dengan pandangan kalian."
  },
  AvgDialog_34980_Content_27 = {
    Text = "Bagaimana, Pelaut tidak memperhatikan kita, kan?"
  },
  AvgDialog_34980_Content_29 = {
    Text = "Kapten, fokuslah pada kemudi."
  },
  AvgDialog_34980_Content_3 = {
    Text = "Rumah yang menghilang karena Pelarutan, satu-satunya bukti keberadaannya di dunia adalah Celeste…"
  },
  AvgDialog_34980_Content_30 = {
    Text = "Adapun gangguan eksternal… Saya akan berdiskusi dengan Penjaga untuk mencari solusi."
  },
  AvgDialog_34980_Content_4 = {
    Text = "Karena merasa bersalah telah memberikan Murphy kepada ordo secara pribadi… Apakah ini alasan untuk Penghianatan terhadap Pelaut?"
  },
  AvgDialog_34980_Content_5 = {
    Text = [[
Elton berjongkok di samping Murphy, menyibakkan helaian rambut yang menempel di dahinya karena keringat dingin. 
 Setelah memeriksa Negaranya, dia menghela napas panjang, lalu bangkit dan akhirnya melihat kembali kepada kalian.]]
  },
  AvgDialog_34980_Content_6 = {
    Text = "Jika aku tidak memberikannya kepada Miryam, dia tidak akan dirasuki oleh dewa apa pun, dan juga tidak akan terbaring di sini seperti sekarang, dengan hidup yang hampir habis."
  },
  AvgDialog_34980_Content_7 = {
    Text = "Apakah terasa seperti mendengar sebuah lelucon?"
  },
  AvgDialog_34980_Content_8 = {
    Text = "Bukankah manusia sangat pandai menulis sejarah? Bahkan catatan tentang acara olahraga dari ribuan tahun yang lalu pun bisa tersisa. Bagaimana mungkin ada kota yang lenyap begitu saja, hingga tidak ada jejak sedikit pun yang tersisa?"
  },
  AvgDialog_34980_Content_9 = {
    Text = "Lupakan omong kosong ini, anggap saja sebagai cerita tidur yang buruk yang saya buat."
  },
  AvgDialog_34981_Content_1 = {
    Text = "Ramona, kamu sedang..."
  },
  AvgDialog_34981_Content_10 = {
    Text = "Tidak ada… bagaimana mungkin?"
  },
  AvgDialog_34981_Content_11 = {
    Text = "Apa yang tidak ada lagi?"
  },
  AvgDialog_34981_Content_12 = {
    Text = "Luka di betismu menghilang. \n Tapi aku jelas melihatnya… senjata musuh menahanmu di sana."
  },
  AvgDialog_34981_Content_13 = {
    Text = "Jadi, kau menyuruhku membawa Celeste pergi lebih dulu, dan karena itulah aku terpaksa meninggalkanmu di sana…"
  },
  AvgDialog_34981_Content_14 = {
    Text = "Kamu juga tidak bisa melupakan rasa sakit yang begitu mendalam dan menghancurkan."
  },
  AvgDialog_34981_Content_15 = {
    Text = "Sama seperti algojo yang membersihkan tempat eksekusi tanpa memedulikan narapidana yang dihukum mati, Goliath mencabut senjatanya tanpa pernah memperdulikan perasaanmu."
  },
  AvgDialog_34981_Content_16 = {
    Text = "Darah meresap ke dalam seragam sekolahmu, daging yang hancur berceceran di tangan Goliath. Betis kecil yang kontras dengan ukuran besar bilah raksasa itu hampir patah menjadi dua bagian, namun adrenalin dari rasa takut membuatmu tetap sadar."
  },
  AvgDialog_34981_Content_17 = {
    Text = "Meskipun rasa sakit masih mengoyak sarafmu... memang sudah tidak ada lagi, luka mengerikan itu menghilang."
  },
  AvgDialog_34981_Content_18 = {
    Text = [[
Pakaian memiliki dua lubang besar, tetapi kulit di bawahnya sangat halus. 
 Selain tampak terlalu pucat karena jarang terpapar cahaya, kondisinya memang sehat dan utuh.]]
  },
  AvgDialog_34981_Content_19 = {
    Text = "Luka sudah sembuh? Itu pasti karena Kemampuan Celeste."
  },
  AvgDialog_34981_Content_2 = {
    Text = "Shh... pelan-pelan, masih banyak Pelaut yang berkeliaran di luar."
  },
  AvgDialog_34981_Content_20 = {
    Text = "Murphy berlari kecil menuju Celeste, dengan lembut memegang sehelai kain putih yang menjuntai dari bahu Celeste — saat ini, terlihat sangat mirip perban."
  },
  AvgDialog_34981_Content_21 = {
    Text = "Kamu menengadah dan menatap Celeste, bertemu dengan pandangannya yang sedang mengarah padamu. Karena melemahnya tubuh Tautan, kondisinya juga semakin memburuk, tampaknya ia sudah kehilangan tenaga untuk berbicara."
  },
  AvgDialog_34981_Content_22 = {
    Text = "Dia menggerakkan bibirnya, mengeluarkan suara napas yang hampir tak terdengar. Kamu tak pernah melakukan Penelitian tentang pembacaan gerak bibir, namun dengan jelas kamu bisa melihat apa yang ingin dia katakan ——"
  },
  AvgDialog_34981_Content_23 = {Text = "Bukan aku."},
  AvgDialog_34981_Content_24 = {
    Text = [[
Ya, bukan dia. 
Kamu sangat yakin akan hal itu.]]
  },
  AvgDialog_34981_Content_25 = {
    Text = "Energi yang begitu besar seperti gugusan bintang, tidak mungkin berasal dari dirinya yang penuh kelemahan."
  },
  AvgDialog_34981_Content_3 = {
    Text = "Ramona erat memegang tanganmu, matanya tajam menyapu tubuhmu dari atas ke bawah. Dia tidak memberimu kesempatan untuk bicara, tangannya perlahan mengukur bekas luka di tubuhmu…"
  },
  AvgDialog_34981_Content_4 = {
    Text = "Kamu terluka cukup parah saat menghadapi Miryam dan Goliath. Aku akan memeriksa lukamu untuk memastikan tidak ada infeksi atau kondisi yang memburuk…"
  },
  AvgDialog_34981_Content_5 = {
    Text = "Pinggang yang pernah ditekan dan dipelintir oleh Kekuatan Miryam, tidak merasakan sedikit pun rasa sakit saat telapak tangan Ramona menekannya."
  },
  AvgDialog_34981_Content_6 = {
    Text = [[
Kemudian, dia mencium bau obat dan berjalan mengitari ke belakangmu, lalu mengangkat rambut di bagian belakang kepalamu. 
 Setelah dia memperhatikan dengan cermat rambut yang berantakan itu selama beberapa saat, kamu merasakan bahwa dia terdiam langka untuk sesaat.]]
  },
  AvgDialog_34981_Content_7 = {
    Text = "... Siapa yang mengoleskan salep ke seluruh kepalamu? Meskipun ada noda darah di sini, tetapi tidak ada luka sama sekali."
  },
  AvgDialog_34981_Content_8 = {
    Text = "Huh, huh... Ternyata tidak terluka ya, aku melihat bagian belakang kepalamu penuh darah, kukira..."
  },
  AvgDialog_34981_Content_9 = {
    Text = "Dia akhirnya berjongkok dengan cepat di sampingmu, memperhatikan betis kakimu dengan seksama."
  },
  AvgDialog_34982_Content_1 = {
    Text = "Kamu menjulurkan kepalamu keluar dari pintu ruang kemudi, dan di dek terbaring sekelompok pelaut. Ada yang tampak normal, ada yang menyimpan parasit, ada yang berwajah seperti ular..."
  },
  AvgDialog_34982_Content_10 = {
    Text = "Kamu cepat datang dan lihat Pelaut ini."
  },
  AvgDialog_34982_Content_11 = {
    Text = "Ramona menyibakkan tumpukan rumput laut, serpihan karang yang berantakan, memperlihatkan seorang Pelaut yang terkubur di bagian paling bawah."
  },
  AvgDialog_34982_Content_12 = {
    Text = "Itu juga sudah tidak bernapas, bagian putih mata menjadi keruh dan abu-abu, kulitnya yang licin menjadi dehidrasi dan berkerut dalam waktu singkat. Meski begitu, kamu masih bisa dengan jelas mengenalinya."
  },
  AvgDialog_34982_Content_13 = {
    Text = "Kulitnya berwarna putih, sangat mencolok di antara para Pelaut yang berwarna kelabu. Seperti angsa di antara kawanan burung gereja, atau kuda putih dari Dayuan di antara keledai abu-abu."
  },
  AvgDialog_34982_Content_14 = {
    Text = "Aku ingat itu, untuk sementara belum menunjukkan tanda-tanda terinfeksi parasit, jadi saat kita menanganinya pun tidak terlalu sulit... tapi kenapa? Aku tidak melihat ada yang istimewa darinya."
  },
  AvgDialog_34982_Content_15 = {
    Text = "Coba pikirkan lagi, dalam situasi apa kita sebelumnya bertarung dengan Pelaut putih?"
  },
  AvgDialog_34982_Content_16 = {
    Text = "Hmm… saat dikejar oleh Goliath?"
  },
  AvgDialog_34982_Content_17 = {
    Text = "Tunggu, Goliath?!"
  },
  AvgDialog_34982_Content_18 = {
    Text = "Benar, Pelaut berwarna putih… adalah pengawal pribadi Goliath."
  },
  AvgDialog_34982_Content_19 = {
    Text = "Goliath... Setelah pertempuran di Ruang Kekuatan, apakah belum ada seorang pun yang melihatnya?"
  },
  AvgDialog_34982_Content_2 = {
    Text = "Hu——sangat lelah. \nJika Tulu ada di sini, menangani mereka pasti akan lebih mudah."
  },
  AvgDialog_34982_Content_20 = {
    Text = "Sebelum ledakan terjadi, dia sudah tidak berada di Ruang Kekuatan."
  },
  AvgDialog_34982_Content_21 = {
    Text = "Kami telah membuat kesalahan yang mungkin berakibat fatal: sepenuhnya mengabaikan keberadaan Goliath."
  },
  AvgDialog_34982_Content_22 = {
    Text = "Sebelum Ramona selesai berbicara, benturan keras membuat pintu kabin hancur seketika."
  },
  AvgDialog_34982_Content_23 = {
    Text = "Pemuda berbentuk ikan itu menarik kembali tombak panjangnya dan menundukkan kepala untuk melihat para pelaut yang terbaring di tanah. Separuh tubuhnya tersembunyi dalam bayangan besar yang dilemparkan oleh pipa asap raksasa, kamu sama sekali tidak bisa melihat ekspresi di wajahnya."
  },
  AvgDialog_34982_Content_24 = {Text = "Caecus!"},
  AvgDialog_34982_Content_25 = {
    Text = [[
Caecus hanya melirik kapten sekilas, lalu memalingkan kepala, tak lagi melihat siapa pun di dalam ruang kemudi. 
Dia memutar tubuhnya menghadap dek dan membungkuk dalam-dalam, dengan hormat menyambut tuannya yang baru.]]
  },
  AvgDialog_34982_Content_26 = {
    Text = "Tuan, mereka memang bersembunyi di ruang kemudi."
  },
  AvgDialog_34982_Content_27 = {
    Text = "Raksasa melangkah dengan langkah berat, tangannya bertumpu pada bagian atas kusen pintu, menutup semua cahaya bulan di luar pintu."
  },
  AvgDialog_34982_Content_28 = {
    Text = [[
Waktu hingga Selaras
tersisa: 60 menit]]
  },
  AvgDialog_34982_Content_3 = {
    Text = "Tidak ada suara lagi di bawah tangga, tampaknya untuk sementara ini sudah berakhir."
  },
  AvgDialog_34982_Content_4 = {
    Text = "Kamu menendang Pelaut yang sudah kehilangan tanda-tanda Hidup di dekat kakimu."
  },
  AvgDialog_34982_Content_5 = {
    Text = "Dalam pertempuran, kalian menganggap rongga perutnya yang tumbuh parasit secara misterius sebagai kelemahan. Kulitnya robek akibat serangan berulang, mengeluarkan darah kotor yang kental ke mana-mana."
  },
  AvgDialog_34982_Content_6 = {
    Text = [[
Tidak tahu apakah darah yang terpengaruh oleh Pelarutan ini beracun, sepertinya bercampur banyak D-lendir. 
 Ramona, bagaimana kalau kita buang saja mereka ke laut?]]
  },
  AvgDialog_34982_Content_7 = {
    Text = "Tunggu… Aku ingat, Boneka pernah berkata bahwa ini tidak boleh dilakukan."
  },
  AvgDialog_34982_Content_8 = {
    Text = "\"Buku Panduan Lapangan Penyelidik Universitas Mythag\" dengan jelas menyatakan bahwa karena mekanisme penyebaran dan perbanyakan belum sepenuhnya dipahami, penyelidik harus menghindari sejauh mungkin memasukkan D-lendir ke dalam siklus alami saat melakukan tugas."
  },
  AvgDialog_34982_Content_9 = {
    Text = "Saya senang kamu masih ingat pelajaran yang diberikan Boneka, tapi sekarang bukan saatnya memikirkan tentang pencemaran ekologi."
  },
  AvgDialog_34983_Content_1 = {
    Text = "Para siswa, apakah kalian masih bisa menghadapinya?"
  },
  AvgDialog_34983_Content_2 = {
    Text = "Mereka semua adalah pelaut yang kehilangan akal, serta beberapa tubuh mutan yang mengalami pelarutan."
  },
  AvgDialog_34983_Content_3 = {
    Text = [[
Tindakan mereka sangat sembarangan, tidak seperti ada pemimpin yang mengoordinasi mereka. 
 Sepertinya mereka terpikat oleh peluit uap, dan jika musuh yang muncul selalu seperti ini, kita masih bisa menghadapinya.]]
  },
  AvgDialog_34983_Content_4 = {
    Text = "Baik, jika membutuhkan bantuan, cobalah memanggil nama Celeste dalam hati."
  },
  AvgDialog_34983_Content_5 = {
    Text = [[
Meskipun saat ini kendali atas kapal telah hilang, kapal ini selama bertahun-tahun menjadi wilayahnya. 
 Saya pikir, kekuatan Celeste pasti meninggalkan jejak yang bisa membantu kalian.]]
  },
  AvgDialog_34983_Content_6 = {
    Text = "Aku akan memacu kecepatan penuh, pegangan yang kuat, hati-hati mabuk perjalanan!"
  },
  AvgDialog_35167_Content_1 = {
    Text = "Malam Kematian, Mead, dan Nyanyian"
  },
  AvgDialog_35167_Content_10 = {
    Text = "Apa yang sebenarnya dipikirkan wanita itu, tak ada yang bisa menebak. Tapi—"
  },
  AvgDialog_35167_Content_11 = {
    Text = "Wabah di Cambrian sudah tak tertolong lagi. Jika kita membiarkan para yang terinfeksi keluar, entah apa yang akan terjadi."
  },
  AvgDialog_35167_Content_12 = {
    Text = "Terlepas dari apakah ini memang niat Wanda atau bukan, tindakannya ini memang telah menyelamatkan tanah-tanah feodal di sekitarnya…"
  },
  AvgDialog_35167_Content_13 = {
    Text = [[
Kastil Cambrian
Aula Perjamuan]]
  },
  AvgDialog_35167_Content_14 = {
    Text = "Kau mendorong pintu kayu besar aula yang berat."
  },
  AvgDialog_35167_Content_15 = {
    Text = "Cahaya gemerlap bagaikan bintang-bintang yang jatuh ke dunia, aroma manis anggur merah dan hidangan lezat mengambang di seluruh aula."
  },
  AvgDialog_35167_Content_16 = {
    Text = "Para penduduk desa Cambrian mengenakan pakaian terbaik mereka, menari dengan riang mengikuti irama musik."
  },
  AvgDialog_35167_Content_17 = {
    Text = "Meskipun di luar sudah lama tenggelam oleh Korosi, suasana di dalam aula tetap dipenuhi keceriaan."
  },
  AvgDialog_35167_Content_18 = {
    Text = "Jadi ini puding apel yang legendaris itu? Seumur hidup aku belum pernah makan sesuatu yang seenak ini……"
  },
  AvgDialog_35167_Content_19 = {
    Text = "Hahahaha, aku senang sekali! Mati pun tak apa!"
  },
  AvgDialog_35167_Content_2 = {
    Text = [[
Tanah Feodal Guderian
Area Perburuan]]
  },
  AvgDialog_35167_Content_20 = {
    Text = "Menari, ayo menari bersama!"
  },
  AvgDialog_35167_Content_21 = {
    Text = "Kau menyibak kerumunan orang yang ramai dan melihat Wanda yang duduk di ujung sana."
  },
  AvgDialog_35167_Content_23 = {
    Text = "Dia malas-malasan bersandar pada pelayan undead, memegang segelas anggur merah sambil dengan santai mengamati kamu."
  },
  AvgDialog_35167_Content_24 = {
    Text = "Selamat malam, Tuan Biksu. Aku mengira kau tidak akan hadir di pesta ini."
  },
  AvgDialog_35167_Content_25 = {
    Text = "Sesekali aku juga ingin memuaskan rasa penasaranku."
  },
  AvgDialog_35167_Content_26 = {
    Text = "<Gray:Lagipula, di luar sana penuh dengan Cairan Erosi, memangnya aku bisa pergi ke mana……>"
  },
  AvgDialog_35167_Content_27 = {
    Text = "Ujung bajumu ditarik pelan oleh seseorang."
  },
  AvgDialog_35167_Content_28 = {
    Text = "Kau adalah……adiknya Susanna!"
  },
  AvgDialog_35167_Content_29 = {
    Text = "Aku juga punya nama, lho. Semua orang memanggilku Beckman Kecil."
  },
  AvgDialog_35167_Content_3 = {
    Text = "Apa? Kau bilang Wanda melelehkan semua kunci, lalu mengajak seluruh penduduk desa Cambrian untuk mengadakan pesta dansa mewah di istana?"
  },
  AvgDialog_35167_Content_30 = {
    Text = "Selamat malam, Beckman Kecil. Ke mana kakakmu pergi?"
  },
  AvgDialog_35167_Content_31 = {
    Text = "Kakak pergi bersama orang-orang lain yang tidak sakit……"
  },
  AvgDialog_35167_Content_32 = {
    Text = "Beckman Kecil menundukkan kepalanya dengan murung. Dia mengusap hidungnya, lalu mendongak menatapmu dengan mata bulatnya yang besar."
  },
  AvgDialog_35167_Content_33 = {
    Text = "Kakak Biarawan, mau menari bersama? Beckman Kecil tidak punya pasangan dansa, huhu……"
  },
  AvgDialog_35167_Content_34 = {
    Text = "Nak, seorang biarawan tidak boleh menari."
  },
  AvgDialog_35167_Content_35 = {
    Text = "Sekarang saya umumkan bahwa kamu boleh menari, abaikan saja klise-klise lama itu."
  },
  AvgDialog_35167_Content_36 = {
    Text = "Di Cambrian, aku — <Big:adalah hukum!>"
  },
  AvgDialog_35167_Content_37 = {
    Text = "Kau menatap mata besar Beckman Kecil yang penuh harapan, dan diam-diam menelan kata-kata penolakanmu."
  },
  AvgDialog_35167_Content_38 = {
    Text = "Maaf, aku juga tidak terlalu pandai menari, tapi aku bisa menemanimu berputar dua kali."
  },
  AvgDialog_35167_Content_39 = {
    Text = "Kamu menggandeng tangan Beckmann kecil dan berjalan ke tengah aula. Di sana, para penduduk desa sedang menari mengikuti alunan musik."
  },
  AvgDialog_35167_Content_4 = {
    Text = "Be-benar adanya! Kudengar orang-orang yang tidak terinfeksi sudah pergi, dan yang tersisa di pesta dansa hanyalah mereka yang sudah sakit parah."
  },
  AvgDialog_35167_Content_40 = {
    Text = "Rok-rok panjang berkibar ringan mengikuti musik, bagaikan kue-kue kecil warna-warni yang berputar tanpa henti."
  },
  AvgDialog_35167_Content_41 = {
    Text = "Kamu mengarungi lautan emas yang dirajut oleh cahaya dan musik, akhirnya tenggelam sepenuhnya dalam gelembung-gelembung kegembiraan yang terus bermunculan dari segala penjuru."
  },
  AvgDialog_35167_Content_42 = {
    Text = "Kemampuan menari Beckmann kecil jelas tidak jauh lebih baik darimu. Dia bergoyang-goyang tanpa pola mengikuti irama musik, dan tak lama kemudian wajahnya sudah memerah."
  },
  AvgDialog_35167_Content_43 = {
    Text = "Hahaha, senangnya! Hari ini adalah hari paling bahagia Beckmann kecil!"
  },
  AvgDialog_35167_Content_44 = {
    Text = "Kak Biarawan, pegang tanganku, ayo kita berputar-putar bersama!"
  },
  AvgDialog_35167_Content_45 = {
    Text = "Cepat, lebih cepat lagi!"
  },
  AvgDialog_35167_Content_46 = {
    Text = "<Red:Lebih cepat lagi…>"
  },
  AvgDialog_35167_Content_47 = {Text = "Cep@2…"},
  AvgDialog_35167_Content_48 = {
    Text = "Beckman kecil, wajahmu?!"
  },
  AvgDialog_35167_Content_49 = {
    Text = "<Change>Menari, temani aku…"
  },
  AvgDialog_35167_Content_5 = {
    Text = "Hahahaha! Aku sudah susah payah menempatkan mata-mata di sisinya, ternyata itu tidak perlu."
  },
  AvgDialog_35167_Content_50 = {
    Text = "Dari mata anak laki-laki itu terus mengalir cairan erosi hitam pekat, dia tersenyum sambil mengulurkan tangan ke arahmu."
  },
  AvgDialog_35167_Content_51 = {
    Text = "Ujung hidung tiba-tiba terasa dingin. Kamu mengangkat kepala, dan cairan hitam menetes perlahan dari lampu kristal."
  },
  AvgDialog_35167_Content_52 = {
    Text = "Satu tetes, dua tetes…"
  },
  AvgDialog_35167_Content_53 = {
    Text = "Kamu dengan panik melihat sekeliling, dan baru menyadari bahwa banyak orang memiliki pakaian, lengan, bahkan wajah yang telah mengalami pembusukan dalam berbagai tingkat keparahan."
  },
  AvgDialog_35167_Content_54 = {
    Text = "Namun, mereka tetap menari dengan riang."
  },
  AvgDialog_35167_Content_55 = {
    Text = "Kak Biarawan, kenapa kamu mengabaikanku… Kamu tidak suka Beckmann kecil lagi ya…"
  },
  AvgDialog_35167_Content_56 = {
    Text = "Bocah itu mengulurkan kedua tangannya yang lengket untuk memelukmu, kesedihan mengalir dari matanya yang kosong."
  },
  AvgDialog_35167_Content_57 = {
    Text = "Temani aku… Temani aku…"
  },
  AvgDialog_35167_Content_6 = {
    Text = "Wabah semengerikan itu, dia bukan hanya tidak berniat pergi, malah mengunci semua orang di dalam untuk menunggu ajal…"
  },
  AvgDialog_35167_Content_7 = {
    Text = "Apakah benar seperti rumor yang beredar, dia sudah benar-benar gila?"
  },
  AvgDialog_35167_Content_8 = {
    Text = "Ucapanmu sungguh menarik. Memangnya dulu dia pernah menjadi wanita yang waras?"
  },
  AvgDialog_35167_Content_9 = {
    Text = "Eh… itu…"
  },
  AvgDialog_35529_Content_1 = {
    Text = "Kapten, apakah kamu benar-benar akan mempercayai kata-kata ikan kecil itu? Di dalam ordo, dia bukan hanya sekadar pesuruh atau tukang serabutan."
  },
  AvgDialog_35529_Content_10 = {
    Text = "Caecus... dia hanya sangat mengharapkan pengakuan."
  },
  AvgDialog_35529_Content_11 = {
    Text = "Saya tahu kalian mungkin memiliki kekhawatiran tentang dia, tapi saya cukup mengenal anak ini. Kali ini dia datang kepada kita dengan sukarela, yang menunjukkan bahwa dia sudah memutuskan untuk berpihak."
  },
  AvgDialog_35529_Content_12 = {
    Text = "Setelah sampai di ruang kemudi, saya akan masuk terlebih dahulu untuk memeriksa situasinya. Jika semuanya aman, saya akan memanggil kalian untuk masuk."
  },
  AvgDialog_35529_Content_2 = {
    Text = "Jika saya tidak salah ingat, Caecus sebagai Pembangun yang mempertahankan rasionalitasnya bahkan mendapatkan kekuatan roh dari Miryam… Ini adalah sesuatu yang Anda sendiri telah konfirmasikan."
  },
  AvgDialog_35529_Content_3 = {
    Text = "Lagipula, jika kami tidak mempercayai informasi yang dia kirimkan pada saat itu, kami juga tidak akan berhenti di pelabuhan itu…"
  },
  AvgDialog_35529_Content_4 = {Text = "Informasi?"},
  AvgDialog_35529_Content_5 = {
    Text = "Murphy melirik Elton, dan setelah melihat yang terakhir memberikan persetujuan diam dengan tatapannya, dia pun membersihkan tenggorokannya dan melanjutkan."
  },
  AvgDialog_35529_Content_6 = {
    Text = "Rencana awal kami adalah tinggal di Domain Sonanier selama setengah tahun penuh untuk menghindari saat bintang-bintang berada dalam posisi Selaras."
  },
  AvgDialog_35529_Content_7 = {
    Text = "Setelah itu, kami akan berkeliling seluruh dunia. Sambil menghindari pengejaran Pelaut, kami mencari cara untuk melepaskannya, tetapi…"
  },
  AvgDialog_35529_Content_8 = {
    Text = [[
Namun, saat berlabuh untuk mendapatkan pasokan, saya menerima pesan dari perantara.
Pesan tersebut menyebutkan bahwa Caecus bersedia menyerahkan obat kepada saya untuk terakhir kalinya.]]
  },
  AvgDialog_35529_Content_9 = {
    Text = "Lokasi ditentukan di Kota Brilport? Yaitu kota nelayan tempat kita dikejar oleh Pelaut ke atas kapal."
  },
  AvgDialog_35530_Content_1 = {
    Text = [[
Tulu, tolong lindungi Murphy dan Celeste di luar ruang kemudi. 
Aku dan Ramona akan mengikuti kapten masuk lebih dulu untuk melihat situasi di dalam.]]
  },
  AvgDialog_35530_Content_2 = {
    Text = "Tulu tidak menentang. Dia menggunakan tentakelnya untuk menghentikan Murphy yang ingin masuk, lalu menggulungnya bersama Celeste dan mundur ke dalam bayangan di sisi pintu."
  },
  AvgDialog_35530_Content_3 = {
    Text = "Elton melangkah ke arahmu dan menyingkirkan tanganmu yang berada di pintu kabin."
  },
  AvgDialog_35530_Content_4 = {
    Text = "Biarkan aku yang melakukannya."
  },
  AvgDialog_35530_Content_5 = {
    Text = "Di dalam ruang kemudi, memang tidak terlihat jejak Goliath. Hanya beberapa Pelaut yang dengan linglung berkeliaran di dalam ruangan."
  },
  AvgDialog_35530_Content_6 = {
    Text = "Tidak tampak seperti ada jebakan. \n Kapten benar… Caecus memang tidak berbohong kepada kita."
  },
  AvgDialog_35530_Content_7 = {
    Text = "Haha, seperti yang kukatakan, sifat asli Caecus tidak buruk... hanya saja tidak ada yang pernah mengajarnya mana yang benar."
  },
  AvgDialog_35530_Content_8 = {
    Text = "Menyelesaikan masalah ini masih harus mengandalkan kalian. Cepatlah, jangan biarkan mereka bermain dengan kemudi saya lagi."
  },
  AvgDialog_35531_Content_1 = {
    Text = "Kamu dan Ramona berjalan mengitari hingga akhirnya sampai di depan pintu sisi lain Ruang Kekuatan."
  },
  AvgDialog_35531_Content_10 = {
    Text = "Ramona berbisik, sambil menunjuk para Pelaut yang terpengaruh oleh \"Clades\", menghasilkan pertumbuhan abnormal di perut mereka."
  },
  AvgDialog_35531_Content_11 = {
    Text = "Sebisa mungkin hindari mereka. Memeriksa kondisi boiler adalah prioritas utama kita."
  },
  AvgDialog_35531_Content_2 = {
    Text = "Pintu ini terkena dampak selama pertempuran kalian dengan Miryam. Papan pintunya benar-benar berubah bentuk dan bergoyang lemah di bingkai pintu. Kalian tidak perlu banyak usaha untuk masuk ke dalam."
  },
  AvgDialog_35531_Content_3 = {Text = "Ini——"},
  AvgDialog_35531_Content_4 = {
    Text = "Ramona dengan cepat menutupi mulutmu dan menarikmu bersembunyi di balik beberapa puing besi."
  },
  AvgDialog_35531_Content_5 = {
    Text = "Mereka yang memegang tombak, mereka yang menggenggam pedang panjang, mereka yang posturnya bungkuk, serta mereka yang berlutut dan merangkak..."
  },
  AvgDialog_35531_Content_6 = {
    Text = "Di mana pun pandangan mata memandang, terlihat para Pelaut dengan berbagai postur tubuh. Mereka berjalan perlahan di antara reruntuhan Ruang Kekuatan, mengumpulkan berbagai material yang hangus akibat ledakan."
  },
  AvgDialog_35531_Content_7 = {
    Text = "Kamu mencari-cari di dalam otakmu selama beberapa saat, sebelum akhirnya menemukan sebuah kata yang menggambarkan perilaku ini —"
  },
  AvgDialog_35531_Content_8 = {
    Text = "\"Membangun Sarang\"."
  },
  AvgDialog_35531_Content_9 = {
    Text = "Memang... mereka menunjukkan perilaku bersarang yang khas. Mungkin karena pengaruh inti Clades, ingin melahirkan makhluk-makhluk tambahan itu..."
  },
  AvgDialog_35532_Content_1 = {
    Text = "Bergoyang-goyang dan hampir jatuh"
  },
  AvgDialog_35532_Content_10 = {
    Text = "Juga terpaksa melakukannya, coba lihat bulan di luar jendela."
  },
  AvgDialog_35532_Content_11 = {
    Text = [[
Bulan terlalu besar dan juga terlalu terang. 
Metode seperti pengukuran jarak bulan serta pemilihan bintang untuk penentuan posisi tidak berfungsi dalam kondisi seperti ini.]]
  },
  AvgDialog_35532_Content_12 = {
    Text = "Di bawah bimbingan Ramona, kamu melihat bulan purnama yang sangat besar."
  },
  AvgDialog_35532_Content_13 = {
    Text = "Ukurannya sangat tidak normal. Seluruh langit malam dan permukaan laut dilapisi oleh cahaya redup yang sama dengan bulan purnama."
  },
  AvgDialog_35532_Content_14 = {
    Text = "Kamu menyadari bahwa itu semakin mendekat. Begitu dekat hingga Roh-mu seolah sudah merasakan radiasi abnormal yang dipancarkannya, dingin dan panas secara bersamaan."
  },
  AvgDialog_35532_Content_15 = {
    Text = "Huh… huh…"
  },
  AvgDialog_35532_Content_16 = {Text = "Selaras…"},
  AvgDialog_35532_Content_17 = {
    Text = "Napas Murphy semakin keras, hingga semua pandangan tertuju padanya. Setiap tarikan napasnya mulai terdengar seperti suara siulan yang bocor."
  },
  AvgDialog_35532_Content_18 = {
    Text = "Murphy? Apakah kamu baik-baik saja? Aku akan membantu kamu duduk dan beristirahat."
  },
  AvgDialog_35532_Content_19 = {
    Text = "Aku baik-baik saja! Huh, huh…"
  },
  AvgDialog_35532_Content_2 = {
    Text = "Celeste, arah angin?"
  },
  AvgDialog_35532_Content_20 = {
    Text = "Murphy menaikkan suaranya untuk menjawabmu, tapi tanpa sengaja tersedak dan mulai batuk hebat."
  },
  AvgDialog_35532_Content_21 = {
    Text = "Semua orang bisa melihat bahwa dia sedang bertahan dengan susah payah."
  },
  AvgDialog_35532_Content_23 = {
    Text = "Tapi aku merasa \"tidak nyaman\"."
  },
  AvgDialog_35532_Content_24 = {
    Text = "Kakiku sudah kehabisan tenaga, dan kepalaku masih terasa sedikit sakit."
  },
  AvgDialog_35532_Content_25 = {
    Text = "Saat berbicara, kamu duduk bersandar di dinding ruang kemudi."
  },
  AvgDialog_35532_Content_26 = {
    Text = "Saat kamu \"jatuh\", Murphy juga berhenti berpura-pura bahwa semuanya baik-baik saja. Dia langsung kehilangan tenaga, meraba dinding untuk melangkah mendekati kamu."
  },
  AvgDialog_35532_Content_27 = {
    Text = "Kalau begitu, istirahat sebentar… hanya sebentar……"
  },
  AvgDialog_35532_Content_28 = {
    Text = "Dia bersandar di dinding, lalu terduduk di tanah, tak lagi memedulikan apakah sikap duduknya anggun atau tidak."
  },
  AvgDialog_35532_Content_29 = {
    Text = "Dia ingin menemukan sebuah titik tumpu agar tidak benar-benar jatuh. Setelah meraba-raba sejenak, dia akhirnya bersandar di pundakmu."
  },
  AvgDialog_35532_Content_3 = {
    Text = "Celeste mengulurkan tangannya keluar pintu, menutup mata, dan merasakan arah kemajuan kalian. Ia juga merasakan angin laut menerpa pergelangan tangannya yang ramping."
  },
  AvgDialog_35532_Content_30 = {
    Text = "Sebentar saja..."
  },
  AvgDialog_35532_Content_31 = {
    Text = [[
Tak beberapa detik kemudian, terdengar napas cepat namun teratur di samping telinga. 
 Murphy kembali kehilangan kesadaran.]]
  },
  AvgDialog_35532_Content_32 = {
    Text = "Jejak hitam kehijauan yang mengerikan muncul di wajah Murphy, seperti sistem akar tanaman yang tertanam dalam di bawah kulitnya, menyerap hidup yang hampir goyah."
  },
  AvgDialog_35532_Content_33 = {
    Text = "Dewa yang kuhubungkan datang dari ribuan bintang. Meskipun itu adalah tiruan, manusia tetap tidak mampu menahannya."
  },
  AvgDialog_35532_Content_34 = {
    Text = "Aliran darah inang sedang diputus oleh-Nya."
  },
  AvgDialog_35532_Content_35 = {
    Text = "Bagaimana jika operasi dilakukan sekarang?"
  },
  AvgDialog_35532_Content_36 = {
    Text = "Penjaga, saat ini kita sama sekali tidak memiliki kondisi untuk melakukan operasi pada dirinya."
  },
  AvgDialog_35532_Content_37 = {
    Text = "Kecepatan maksimum sudah didorong hingga batas tertinggi, dan dalam kondisi boiler tenaga yang rusak, tidak ada cara untuk mempercepat lebih lanjut."
  },
  AvgDialog_35532_Content_38 = {
    Text = "Tidak bisa melakukan operasi, juga tidak bisa kembali ke daratan tepat waktu… Apakah benar-benar tidak ada cara lain?"
  },
  AvgDialog_35532_Content_39 = {
    Text = "Tulu melirik bulan raksasa di luar jendela, lalu menggelengkan kepalanya."
  },
  AvgDialog_35532_Content_4 = {
    Text = "Angin barat, 22 knot."
  },
  AvgDialog_35532_Content_40 = {
    Text = "Bahkan kamu tidak bisa berbuat apa-apa? Apakah kamu, yang menurunkan ramalan kebangkitan kembali Dewa, juga tidak punya cara?"
  },
  AvgDialog_35532_Content_41 = {
    Text = "Bagaimana kamu bisa tahu……"
  },
  AvgDialog_35532_Content_42 = {
    Text = "Dari sikap Miryam terhadapmu, dan dari beberapa kata-katanya sebelum dia jatuh ke dalam kegilaan, tidak sulit untuk menyimpulkan kebenarannya."
  },
  AvgDialog_35532_Content_43 = {
    Text = "Hanya penghianatan dari pemimpin ilahi yang dapat membuat para penganut setia jatuh dalam kegilaan sedemikian rupa."
  },
  AvgDialog_35532_Content_44 = {Text = "...ya."},
  AvgDialog_35532_Content_45 = {
    Text = "Yu memang telah memberikan ramalan seperti itu kepadanya, tetapi yang disebut \"wahyu ilahi\" sebenarnya tidak ada."
  },
  AvgDialog_35532_Content_46 = {Text = "Apa?"},
  AvgDialog_35532_Content_47 = {
    Text = [[
Jauh sebelum banjir itu datang, Yu telah kehilangan kemampuan untuk melihat masa depan dari mimpi Dewa.
Yu tidak tahu ke mana Dia pergi. Mungkin Dia telah bangun, atau mungkin Dia telah pergi.]]
  },
  AvgDialog_35532_Content_48 = {
    Text = "Lalu ramalanmu..."
  },
  AvgDialog_35532_Content_49 = {
    Text = "Miryam adalah seorang penganut yang saleh. Dia mencurahkan seluruh pikirannya untuk Ranah Dewa, digerakkan oleh kehendak sisa."
  },
  AvgDialog_35532_Content_5 = {
    Text = "Mengerti, sedang menyesuaikan haluan."
  },
  AvgDialog_35532_Content_50 = {
    Text = "Yu hanya berharap kata-kata itu bisa menenangkan ketakutannya sebelum kematiannya, tidak pernah menyangka dia akan menganggapnya sebagai prinsip utama dan memiliki niat membangun kembali ranah dewa."
  },
  AvgDialog_35532_Content_51 = {
    Text = "Semua ini ..."
  },
  AvgDialog_35532_Content_52 = {
    Text = "Ya, semua ini adalah kesalahanku."
  },
  AvgDialog_35532_Content_53 = {
    Text = "Detik berikutnya, dunia seakan-akan dihentikan sementara, semua suara mulai menjauh."
  },
  AvgDialog_35532_Content_54 = {
    Text = "Jika bukan karena hembusan napas lemah Murphy yang menyentuh tubuhmu, hampir saja kau mengira bahwa bahkan waktu pun telah berhenti."
  },
  AvgDialog_35532_Content_55 = {
    Text = "Tunggu... Aku tidak bisa mendengar suara baling-baling menghantam air lagi."
  },
  AvgDialog_35532_Content_56 = {
    Text = "Elton tersadar, dia berjalan mengitari konsol, mencoba setiap operasi yang bisa ia pikirkan, namun semuanya sia-sia."
  },
  AvgDialog_35532_Content_57 = {
    Text = [[
Sonanier terapung diam di antara ombak, seperti raksasa kesepian yang jatuh ke dalam pelukan lautan. 
 Kehilangan kilau, terpencil dan tanpa bantuan.]]
  },
  AvgDialog_35532_Content_58 = {
    Text = "Ada masalah dengan pasokan kekuatan, saya harus pergi ke ruang kekuatan untuk memeriksa."
  },
  AvgDialog_35532_Content_59 = {
    Text = [[
Biarkan aku pergi, aku sedikit paham tentang struktur mekanis. 
Jika hanya untuk menyalakan api dan melakukan perbaikan sederhana, aku bisa melakukannya.]]
  },
  AvgDialog_35532_Content_6 = {
    Text = "Elton kembali berdiri di depan kemudi. Tanpa gangguan musuh, gerakannya mengemudikan kapal terlihat lebih tenang dan penuh keyakinan."
  },
  AvgDialog_35532_Content_60 = {
    Text = "Aku akan pergi bersamamu."
  },
  AvgDialog_35532_Content_61 = {
    Text = "Ketika aku dan Ramona pergi untuk menyelidiki situasi, keselamatan semua orang kuserahkan padamu, Tulu."
  },
  AvgDialog_35532_Content_62 = {
    Text = "Tulu mengangguk, memanjangkan tentakelnya untuk membantu menopang Murphy, lalu perlahan-lahan membaringkannya di tanah."
  },
  AvgDialog_35532_Content_63 = {
    Text = "Terakhir kali saya memelihara lambung kapal, saya mengganti busi di beberapa boiler. Jika api hanya padam, setelah menambahkan cukup batubara, api bisa dinyalakan kembali melalui perangkat."
  },
  AvgDialog_35532_Content_64 = {
    Text = "Baik, kami akan ke sana sekarang."
  },
  AvgDialog_35532_Content_65 = {
    Text = "Kamu mengangguk kepada Ramona, dan tepat saat kamu akan beranjak, telapak tangan yang dingin dengan lembut memegang pergelangan kakimu."
  },
  AvgDialog_35532_Content_66 = {
    Text = "Murphy dengan susah payah duduk. Saat oksigen masuk dan keluar, bekas hitam di wajahnya juga menjadi kurang terlihat."
  },
  AvgDialog_35532_Content_67 = {
    Text = "Dia berbicara dengan suara lemah seperti bunga yang layu, namun nadanya tetap keras kepala."
  },
  AvgDialog_35532_Content_68 = {
    Text = "Kalian akan kembali... kan?"
  },
  AvgDialog_35532_Content_69 = {
    Text = "Ya, kami akan kembali."
  },
  AvgDialog_35532_Content_7 = {
    Text = "Dia dan Celeste bekerja sama dengan baik, keduanya mengendalikan kapal kargo besar yang biasanya membutuhkan setidaknya satu tim untuk dioperasikan."
  },
  AvgDialog_35532_Content_70 = {
    Text = "Kamu berjongkok di sisinya, menggenggam erat tangannya, mencoba menyalurkan kehangatan kepadanya."
  },
  AvgDialog_35532_Content_71 = {
    Text = "Bukankah kita sudah berjanji untuk membawamu kembali ke daratan, kan?"
  },
  AvgDialog_35532_Content_8 = {
    Text = "Hembusan angin sesekali membuat percikan ombak meloncat dari permukaan air ke udara, namun kendali mereka berdua membuat kapal Sonnelier tetap stabil seperti mainan yang mengapung di bak mandi."
  },
  AvgDialog_35532_Content_9 = {
    Text = "Begitu terampil, bahkan tanpa menggunakan alat pengukur, mereka sudah tahu ke arah mana harus pergi."
  },
  AvgDialog_35533_Content_1 = {
    Text = "Teman lama dan baru"
  },
  AvgDialog_35533_Content_10 = {
    Text = "Apakah aku masih diriku yang dulu?"
  },
  AvgDialog_35533_Content_11 = {
    Text = "Saya... siapa?"
  },
  AvgDialog_35533_Content_13 = {
    Text = "……………"
  },
  AvgDialog_35533_Content_14 = {
    Text = "Tidak tahu di mana diri berada, juga tidak tahu sudah berapa lama waktu berlalu."
  },
  AvgDialog_35533_Content_15 = {
    Text = "Selain suara seruling yang semakin keras, kamu tidak merasakan apa pun."
  },
  AvgDialog_35533_Content_16 = {
    Text = "Jangan bersiul... jangan bersiul! Sekarang bukan waktunya mendengarkan musik, aku masih punya urusan yang belum selesai!"
  },
  AvgDialog_35533_Content_17 = {
    Text = "Suara seruling semakin kuat, namun tiba-tiba berhenti setelah melewati batas toleransi fisiologis, menyisakan white noise yang sulit dilacak Sumbernya bergema di dalam kehampaan."
  },
  AvgDialog_35533_Content_18 = {
    Text = "<Change>Selamanya…"
  },
  AvgDialog_35533_Content_19 = {
    Text = "Sebuah gema samar terdengar dari kedalaman alam semesta, mirip dengan gumaman mimpi yang kacau, atau seperti kegelisahan bintang-bintang yang terusik saat bergerak."
  },
  AvgDialog_35533_Content_2 = {
    Text = "Kesadaran terlepas dari tubuh, melayang dan berkeliaran di dalam mimpi ilusi."
  },
  AvgDialog_35533_Content_20 = {
    Text = "Cahaya perak mekar di tempat, saraf yang tegang pun perlahan-lahan terputus."
  },
  AvgDialog_35533_Content_21 = {
    Text = "Ruang kesadaran terang benderang seperti siang hari. Sebelum kamu bisa bereaksi, kamu merasakan jatuh tiba-tiba —"
  },
  AvgDialog_35533_Content_22 = {
    Text = "{Male=Dia,Female=Dia} akan segera bangun."
  },
  AvgDialog_35533_Content_23 = {
    Text = "Penjaga, Penjaga! Apakah kamu bisa mendengar suaraku?"
  },
  AvgDialog_35533_Content_24 = {
    Text = "...Apa yang terjadi padaku?"
  },
  AvgDialog_35533_Content_25 = {
    Text = "Dengan bantuan Ramona, kamu duduk dan melihat sekeliling. Kamu menyadari bahwa kamu berada di ruang kargo, dikelilingi oleh D-hiperplasia dan teman-temanmu."
  },
  AvgDialog_35533_Content_26 = {
    Text = "Bagaimana perasaanmu sekarang?"
  },
  AvgDialog_35533_Content_27 = {
    Text = "Kamu menundukkan kepala dan menatap kedua tanganmu, mencoba bersenandung mengikuti nada seruling yang terus berulang di Dunia roh, namun kamu menyadari bahwa tidak peduli bagaimana caranya, yang keluar hanyalah hembusan napas berulang-ulang."
  },
  AvgDialog_35533_Content_28 = {
    Text = "Saya merasa… tidak ada yang berbeda."
  },
  AvgDialog_35533_Content_29 = {
    Text = [[
Kalau dihitung, ini sudah ketiga kalinya kamu pingsan. 
Katanya tidak merasakan apa-apa, mungkin kamu sedang berbohong?]]
  },
  AvgDialog_35533_Content_3 = {
    Text = "Di mana... saya?"
  },
  AvgDialog_35533_Content_30 = {
    Text = "Pingsan mendadak yang terjadi berulang kali dalam waktu singkat kemungkinan besar terkait dengan gejala intrakranial atau sistem saraf."
  },
  AvgDialog_35533_Content_31 = {
    Text = "Ramona berbicara sambil memeriksa kepalamu dengan sangat teliti lagi, menggunakan ujung jarinya untuk menekan hampir setiap inci tulang tengkorak."
  },
  AvgDialog_35533_Content_32 = {
    Text = "Tidak ditemukan patah tulang, tetapi jika ada hematoma atau infeksi lainnya… harus kembali ke sekolah. Setelah Boneka memeriksa, baru bisa didiagnosis."
  },
  AvgDialog_35533_Content_33 = {
    Text = "Prioritas utama tetap kembali ke daratan dan segera kembali ke sekolah. \n Hal ini sangat penting, baik bagi kamu maupun bagi Murphy…"
  },
  AvgDialog_35533_Content_34 = {
    Text = "Murphy terdiam menatapmu. Setelah waktu yang lama, dia menggelengkan kepalanya tanpa ekspresi."
  },
  AvgDialog_35533_Content_35 = {
    Text = [[
%player% sudah seperti ini, jangan bertindak sebagai pahlawan lagi. 
 Kalian pergi saja.]]
  },
  AvgDialog_35533_Content_36 = {
    Text = "Kalian naik perahu penyelamat, baik mendayung maupun hanyut tidak masalah. Dengan Tulu dan Ramona di sana, kembali ke pantai bukanlah hal yang sulit. Asalkan, asalkan…"
  },
  AvgDialog_35533_Content_37 = {
    Text = "<Small:Asalkan tidak ada beban dari diriku…>"
  },
  AvgDialog_35533_Content_38 = {
    Text = "Sebelum menyelesaikan parasit di tubuhmu, Yu tidak akan pergi."
  },
  AvgDialog_35533_Content_39 = {
    Text = "Murphy mengentakkan kakinya, menunjuk ke arahmu dan Ramona, lalu menunjuk ke arah kapten dan rekannya."
  },
  AvgDialog_35533_Content_4 = {
    Text = "Di sekelilingmu segalanya gelap gulita, dan titik-titik cahaya perak yang kau tinggalkan di jalur yang kau lalui segera dilahap oleh kegelapan yang datang silih berganti."
  },
  AvgDialog_35533_Content_40 = {
    Text = [[
Lalu bagaimana dengan mereka? 
 Bagaimana jika "Dewa" yang menetas ini sangat besar, sampai-sampai bisa membuat kapal tenggelam?]]
  },
  AvgDialog_35533_Content_41 = {
    Text = "Kami juga tidak akan pergi."
  },
  AvgDialog_35533_Content_42 = {Text = "Hei!?"},
  AvgDialog_35533_Content_43 = {
    Text = "Pada hari resmi menjadi Penyelidik, kami bersumpah atas nama keberadaan kami untuk memberikan segalanya demi melawan Fenomena-d."
  },
  AvgDialog_35533_Content_44 = {
    Text = "Kami telah mempersiapkan diri untuk menghabiskan sisa hidup kami bersama kematian dan kegilaan, meskipun yang menanti di depan adalah kematian kami sendiri…"
  },
  AvgDialog_35533_Content_45 = {
    Text = [[
Hanya kalian? Jangan bercanda, ini sama saja dengan mencari mati! 
 Parasit ini adalah monster, bahkan Dewa!]]
  },
  AvgDialog_35533_Content_46 = {
    Text = "Jika ini adalah jam terakhir dalam hidup, aku tidak akan menyia-nyiakan waktu untuk berdoa."
  },
  AvgDialog_35533_Content_47 = {
    Text = "Saya percaya kamu juga tidak akan, bukan? Jika tidak, mengapa kamu berusaha keras untuk melarikan diri dari sekte?"
  },
  AvgDialog_35533_Content_48 = {Text = "Aku..."},
  AvgDialog_35533_Content_49 = {
    Text = "Ini bukan hanya untukmu, tahu tidak? Kami juga sedang menunggu untuk turun dari kapal."
  },
  AvgDialog_35533_Content_5 = {
    Text = "Kamu bisa merasakan ada sesuatu yang menghilang dari Dunia rohmu, kamu tiba-tiba meraih ke dalam kegelapan, hanya untuk menemukan bahwa itu adalah sebagian dari Memori-mu."
  },
  AvgDialog_35533_Content_50 = {
    Text = "Parasit di tubuhmu kini menjadi inti dari Clades Pelarutan, yang berarti kamu sekarang juga menjadi salah satu tanggung jawab Penyelidik Mythag."
  },
  AvgDialog_35533_Content_51 = {
    Text = "Aku berjanji tidak akan menyerah pada dirimu... Aku tidak akan mengingkari janjiku."
  },
  AvgDialog_35533_Content_52 = {
    Text = "...orang gila, semuanya adalah orang gila."
  },
  AvgDialog_35533_Content_53 = {
    Text = "Murphy mengendus, menelan nada suara yang bergetar karena tangis."
  },
  AvgDialog_35533_Content_54 = {
    Text = "Lalu, apa yang harus kita lakukan sekarang? Goliath dan yang lainnya sudah menguasai ruang kemudi. Dengan begini, kita tidak bisa menjalankan kapal."
  },
  AvgDialog_35533_Content_55 = {
    Text = "Celeste, berapa lama lagi kita bisa berlabuh?"
  },
  AvgDialog_35533_Content_56 = {
    Text = "Kosong, angin dari timur laut, kecepatan 15 knot. \n… Waktu standar Kadath, 60 menit."
  },
  AvgDialog_35533_Content_57 = {
    Text = "Berapa lama lagi sampai waktu Selaras…?"
  },
  AvgDialog_35533_Content_58 = {
    Text = "Masih ada waktu."
  },
  AvgDialog_35533_Content_59 = {
    Text = "Celeste menatap kapten dengan ragu, seolah sedang memastikan sesuatu."
  },
  AvgDialog_35533_Content_6 = {
    Text = "Dalam memori, kamu baru saja dibawa kembali ke Universitas Mythag oleh Ramona. Boneka berdiri di alun-alun sekolah untuk menyambut kalian, menunjukkan perhatian terhadap Ramona dan keraguan terhadap dirimu."
  },
  AvgDialog_35533_Content_60 = {
    Text = "Tubuhnya sudah semakin samar di luar kenyataan. Sang kapten awalnya ingin mengulurkan tangan untuk menepuk kepalanya, namun akhirnya hanya bergerak lembut di atas kepalanya tanpa menyentuh."
  },
  AvgDialog_35533_Content_61 = {
    Text = "Celeste, ayo percepat."
  },
  AvgDialog_35533_Content_62 = {
    Text = "Kapten! Apa yang kalian lakukan!? Negara mu dan Celeste sangat buruk, kalian tidak bisa lagi menggunakan Kemampuan super untuk mengemudikan kapal!"
  },
  AvgDialog_35533_Content_63 = {
    Text = "Pembangun sedikit mengangguk, lalu mengangkat kedua tangannya tinggi-tinggi. Kompas di tangannya bergerak sendiri tanpa angin, menyebarkan titik-titik cahaya berkilauan."
  },
  AvgDialog_35533_Content_64 = {
    Text = "Elton, hentikan!"
  },
  AvgDialog_35533_Content_65 = {
    Text = "Pemuda Pelaut menabrak membuka pintu kabin. Begitu dia masuk ke dalam kabin, Ramona dan Tulu segera bangkit dan berdiri menghalangi di depannya."
  },
  AvgDialog_35533_Content_66 = {
    Text = "Celeste dengan ragu menurunkan tangannya, dia memandang Elton, menunggu instruksi berikutnya dari Tautan."
  },
  AvgDialog_35533_Content_67 = {
    Text = "Saya tidak datang untuk mencari pertempuran."
  },
  AvgDialog_35533_Content_68 = {
    Text = "Aku... punya sesuatu yang ingin kuberikan padamu."
  },
  AvgDialog_35533_Content_69 = {
    Text = "Pandangannya melewati semua orang dan tertuju pada Kapten Elton."
  },
  AvgDialog_35533_Content_7 = {Text = "Lalu..."},
  AvgDialog_35533_Content_70 = {
    Text = "Elton melambaikan tangannya. Saat dia mendekati Caecus, dia menggunakan tatapan untuk mengisyaratkan Ramona dan Tulu menurunkan posisi serangan mereka."
  },
  AvgDialog_35533_Content_71 = {
    Text = "Jangan mendekat...!"
  },
  AvgDialog_35533_Content_72 = {
    Text = "Jangan terlalu dekat denganku, kalau kalian meninggalkan terlalu banyak bau kalian, aku bisa diperhatikan oleh Pelaut lain."
  },
  AvgDialog_35533_Content_73 = {
    Text = "Dia melemparkan sebuah botol kaca ke dek, membiarkannya menggelinding mengikuti kemiringan kapal hingga berhenti di dekat kaki Elton."
  },
  AvgDialog_35533_Content_74 = {
    Text = [[
Obat untuk menstabilkan Roh... 
 Apakah memberikan obat ini kepada saya adalah keinginanmu sendiri?]]
  },
  AvgDialog_35533_Content_75 = {
    Text = "Jika kamu khawatir ada masalah dengan obatnya..."
  },
  AvgDialog_35533_Content_76 = {
    Text = "Elton tidak memberi kesempatan pada orang itu untuk menyelesaikan perkataannya, dia membuka penutup botol dan tanpa ragu menelan sekumpulan pil."
  },
  AvgDialog_35533_Content_77 = {
    Text = [[
Jangan salah paham, anak. 
Aku hanya khawatir kamu akan menerima hukuman dari internal Pelaut karena hal ini.]]
  },
  AvgDialog_35533_Content_79 = {
    Text = "Mereka tidak akan mengetahuinya. Pelaut yang bertanggung jawab menyimpan obat-obatan telah tewas dalam operasi ini."
  },
  AvgDialog_35533_Content_8 = {
    Text = "Lalu memori Anda bergerak mundur dengan cepat, menghilang seperti aliran air."
  },
  AvgDialog_35533_Content_80 = {
    Text = "Caecus menutup matanya sejenak, ekspresinya tenang. Kamu tidak bisa memastikan apakah dia sedang berduka atas kematian rekan-rekannya."
  },
  AvgDialog_35533_Content_81 = {
    Text = "Kapten, jika Anda masih mempercayai saya... mohon kembali ke ruang kemudi melalui rute lain."
  },
  AvgDialog_35533_Content_82 = {
    Text = "Saya akan kembali sekarang dan mencoba menarik perhatian Tuan Goliath. Namun, jika saya mengusulkan untuk menarik semua orang, itu akan terlihat terlalu mencolok."
  },
  AvgDialog_35533_Content_83 = {
    Text = "Tuan Goliath pasti akan meninggalkan orang untuk menjaga ruang kemudi. Terhadap para Pelaut yang berjaga itu, aku tidak bisa berbuat apa-apa."
  },
  AvgDialog_35533_Content_84 = {
    Text = "Setelah Caecus selesai berbicara, dia berbalik dan hendak pergi."
  },
  AvgDialog_35533_Content_85 = {
    Text = "Caecus, tunggu!"
  },
  AvgDialog_35533_Content_86 = {
    Text = "Kesempatan ini, tidak cocok untuk kita bernostalgia, tetapi..."
  },
  AvgDialog_35533_Content_87 = {
    Text = "Apa yang kamu katakan sebelumnya, bahwa kamu tidak akan membenciku karena Penghianatanku, apakah itu benar?"
  },
  AvgDialog_35533_Content_89 = {
    Text = "Benar sekali."
  },
  AvgDialog_35533_Content_9 = {
    Text = "Suara seruling yang aneh dan misterius terdengar, seperti sebuah kait yang menusuk ke dalam dunia rohmu, dan kelima indra tiba-tiba tertutup."
  },
  AvgDialog_35534_Content_1 = {
    Text = "Lubang pengisian batu bara di boiler ini sudah macet, sepertinya sudah rusak cukup lama."
  },
  AvgDialog_35534_Content_10 = {
    Text = "Ramona mengangguk, berjongkok di bawah bayangan yang dilemparkan oleh boiler, dan mulai memeriksa kondisi mesin."
  },
  AvgDialog_35534_Content_11 = {
    Text = "Kata kapten benar, busi itu baru."
  },
  AvgDialog_35534_Content_12 = {
    Text = "Secara kasat mata, dinding luar boiler juga tidak rusak... negaranya baik seperti baru keluar dari pabrik."
  },
  AvgDialog_35534_Content_13 = {
    Text = "Ini adalah sudut yang terlindung dari angin. Angin yang masuk melalui lubang di badan kapal seharusnya tidak memengaruhi boiler... dari mana masalah ini berasal?"
  },
  AvgDialog_35534_Content_14 = {
    Text = "Mungkinkah ini hanya karena bahan bakar yang habis saja?"
  },
  AvgDialog_35534_Content_15 = {
    Text = "Ramona mengangguk, lalu berjalan mengitari bagian depan boiler dan membuka pintu tungku. Segera setelah itu, ekspresinya berubah menjadi kaget."
  },
  AvgDialog_35534_Content_16 = {Text = "Ada apa?"},
  AvgDialog_35534_Content_17 = {
    Text = "Sebelum kamu sempat bereaksi, Ramona menarikmu dan bergegas menuju pintu Ruang Kekuatan, tak lagi peduli apakah langkah mereka akan mengganggu Pelaut yang sedang bersarang."
  },
  AvgDialog_35534_Content_18 = {
    Text = "Tungku basah! Seseorang dengan sengaja memadamkan boiler tenaga!"
  },
  AvgDialog_35534_Content_19 = {Text = "Jebakan?!"},
  AvgDialog_35534_Content_2 = {
    Text = "Semuanya di sini terkena dampak ledakan, tampaknya tidak mungkin untuk menyalakan api."
  },
  AvgDialog_35534_Content_20 = {
    Text = "Tubuh kurus pemuda itu menimbulkan bayangan yang sangat besar di depan pintu keluar. Beberapa pelaut berdiri di belakangnya, membuat udara dingin semakin dipenuhi dengan ketegangan dan aroma bahaya."
  },
  AvgDialog_35534_Content_21 = {Text = "Caecus…"},
  AvgDialog_35534_Content_22 = {
    Text = "Jangan... lihat aku seperti ini..."
  },
  AvgDialog_35534_Content_23 = {
    Text = "Caecus menatap dengan mata berkilauan, bibirnya bergerak-gerak seolah ingin mengatakan sesuatu, tetapi akhirnya dia memalingkan kepala dan menghindari tatapan pemeriksaanmu serta Ramona."
  },
  AvgDialog_35534_Content_24 = {
    Text = [[
Apakah dari awal kamu sudah berpikir seperti ini? Dengan langkah-langkah yang dirancang secara hati-hati, memancing kami ke dalam jebakan. 
 Apakah semua yang kamu katakan kepada kami hanyalah kedokmu?]]
  },
  AvgDialog_35534_Content_25 = {Text = "Aku..."},
  AvgDialog_35534_Content_26 = {
    Text = "Kalian tidak pernah mengalami apa yang aku alami, tidak mengerti apa artinya kekuatan seorang Pelaut…"
  },
  AvgDialog_35534_Content_27 = {
    Text = "Kalian tidak akan mengerti, dan <Yellow:seharusnya tidak berada di sini>… Jika aku kalian, sekarang aku akan mencari cara apapun untuk <Yellow:melarikan diri dari Miryam>…"
  },
  AvgDialog_35534_Content_28 = {
    Text = "Nada suara, intonasi, bahkan tata bahasa Caecus menjadi sangat aneh, begitu aneh hingga tidak lagi terdengar seperti bahasa Leo standar."
  },
  AvgDialog_35534_Content_29 = {
    Text = "Jika ada seseorang yang memaksa kamu melakukan sesuatu yang tidak kamu inginkan..."
  },
  AvgDialog_35534_Content_3 = {
    Text = "Kamu dan Ramona melakukan pertukaran informasi dengan suara yang sangat pelan, takut menarik perhatian para Pelaut."
  },
  AvgDialog_35534_Content_30 = {
    Text = "Tidak! Berhenti!"
  },
  AvgDialog_35534_Content_31 = {
    Text = "Caecus tiba-tiba berteriak dengan suara keras, ekspresinya berubah dalam sekejap. Dari dasar matanya terpancar rasa takut yang membuatnya merasa sesak napas."
  },
  AvgDialog_35534_Content_32 = {
    Text = "Dia dengan kaku meraba leher, dan sebuah cincin hitam suram pun muncul, persis seperti tanda yang sebelumnya kamu lihat di tubuh Goliath."
  },
  AvgDialog_35534_Content_33 = {
    Text = "Hukuman kuno dari Lemuria perlahan-lahan semakin ketat, membuat napasnya menjadi cepat dan sulit."
  },
  AvgDialog_35534_Content_34 = {
    Text = "Meskipun Pembangun tidak membutuhkan oksigen untuk bernapas, rasa sakit yang luar biasa membuat wajahnya dipenuhi oleh penderitaan yang tak terungkapkan."
  },
  AvgDialog_35534_Content_35 = {
    Text = "Maafkan aku..."
  },
  AvgDialog_35534_Content_36 = {
    Text = "Maafkan aku... aku... harus..."
  },
  AvgDialog_35534_Content_4 = {
    Text = "Ruang Kekuatan dengan puluhan boiler sudah padam, kamu dan Ramona hanya bisa memeriksa satu per satu."
  },
  AvgDialog_35534_Content_5 = {
    Text = "Kamu meraba satu per satu boiler yang dingin. Pelaut yang berkeliaran di sekitar memperbesar rasa putus asa dan ketakutan hingga mencapai puncaknya."
  },
  AvgDialog_35534_Content_6 = {
    Text = "Jantung seakan sudah berdetak di bawah tengkorak, membuatmu hanya bisa mendengar suara otot jantung berdenyut."
  },
  AvgDialog_35534_Content_7 = {
    Text = "Lalu, detak jantung yang kencang tiba-tiba terhenti."
  },
  AvgDialog_35534_Content_8 = {
    Text = "Ramona, aku menemukannya!"
  },
  AvgDialog_35534_Content_9 = {
    Text = [[
Dinding luar boiler yang baru saja dimatikan masih sangat panas. Sarung tangan menempel di permukaannya, menguapkan uap air sedikit demi sedikit. 
 Namun, kamu tidak punya waktu untuk memikirkan hal lain. Dengan penuh kegembiraan, kamu memanggil rekanmu dengan suara pelan.]]
  },
  AvgDialog_35535_Content_1 = {
    Text = "Caecus jatuh berlutut dengan berat, senjatanya menjadi penopang tubuhnya yang telah kalah. Dengan sisa kekuatannya, ia menggenggam erat gagang tombak itu seolah memegang secercah cahaya terakhir."
  },
  AvgDialog_35535_Content_2 = {
    Text = "Caecus, kamu…"
  },
  AvgDialog_35535_Content_3 = {
    Text = [[
Dia bernapas dengan berat, tampaknya mengucapkan beberapa kata. 
Untuk mendengar dengan jelas perkataannya yang tidak jelas, kamu harus berjongkok di depannya.]]
  },
  AvgDialog_35535_Content_4 = {
    Text = "Pergi... <Big:Lari!>"
  },
  AvgDialog_35535_Content_5 = {
    Text = "Caecus mendorongmu dengan keras, kehilangan keseimbangannya sendiri, dan jatuh terduduk ke belakang dengan berat di atas permukaan tanah yang dingin dan keras."
  },
  AvgDialog_35535_Content_6 = {
    Text = "Detik berikutnya, suara langkah kaki yang sangat familiar, diiringi oleh para Pelaut, semakin mendekat ke arah kalian."
  },
  AvgDialog_35535_Content_7 = {
    Text = "Caecus, kau seharusnya tidak bersikap terlalu lembut."
  },
  AvgDialog_35536_Content_1 = {
    Text = "Cahaya yang menggoda"
  },
  AvgDialog_35536_Content_10 = {
    Text = "Suara angin... Aku ingat ruang kekuatan meledak, meninggalkan lubang yang sangat besar."
  },
  AvgDialog_35536_Content_11 = {
    Text = "Sebelumnya, Sonnelier terus berlayar ke utara, dan suhu di permukaan laut sangat dingin. Tidak ada yang menambahkan batu bara untuk menjaga api tetap menyala, kemungkinan besar api tungku telah padam tertiup angin laut."
  },
  AvgDialog_35536_Content_12 = {Text = "Huu……"},
  AvgDialog_35536_Content_13 = {Text = "Ada apa?"},
  AvgDialog_35536_Content_14 = {
    Text = "Hanya terasa... sedikit tidak nyata."
  },
  AvgDialog_35536_Content_15 = {
    Text = [[
Pelabuhan diserang, bertemu Murphy dan kapten, berhadapan dengan Miryam, ledakan... 
 Padahal kami baru meninggalkan sekolah sebelum makan malam, tapi sekarang terasa seperti sudah dua bulan berlayar.]]
  },
  AvgDialog_35536_Content_16 = {
    Text = "Malam yang sangat sibuk. Jika Boneka tahu, dia pasti akan memuji saya dengan wajah dingin karena jarang begitu rajin."
  },
  AvgDialog_35536_Content_17 = {
    Text = "\"Kerja bagus, Penjaga. Pengalaman malam ini akan menjadi catatan penting di lembar hasil akhirmu.\""
  },
  AvgDialog_35536_Content_18 = {
    Text = "Kamu menjawab Ramona dengan nada yang terdengar santai. Dia mengeluarkan beberapa suara hidung yang tidak jelas, menahan diri untuk tidak tertawa terbahak-bahak."
  },
  AvgDialog_35536_Content_19 = {
    Text = "Apakah kamu akan diam-diam memberi tahu Boneka?"
  },
  AvgDialog_35536_Content_2 = {
    Text = [[
Waktu hingga Selaras
tersisa: 20 menit]]
  },
  AvgDialog_35536_Content_20 = {
    Text = "Jika aku mau, saat berkomunikasi dengan Boneka tadi, aku pasti sudah mencurahkan semua keluhan padanya."
  },
  AvgDialog_35536_Content_21 = {
    Text = "\"Penjaga Mythag berkorban untuk orang lain, menempatkan diri mereka dalam bahaya, dan mengalami luka parah hingga pingsan.\""
  },
  AvgDialog_35536_Content_22 = {
    Text = "Ssst! Jangan sampai——"
  },
  AvgDialog_35536_Content_23 = {
    Text = "Tapi apakah kamu sudah berhubungan dengan Boneka? Apakah komunikatornya sudah bisa terhubung?"
  },
  AvgDialog_35536_Content_24 = {
    Text = "Ketika Domain masih ada, sinyal memang terputus. Setelah kekuatan Celeste melemah, awalnya juga karena jarak yang terlalu jauh, komunikasi tidak berjalan dengan lancar."
  },
  AvgDialog_35536_Content_25 = {
    Text = "Ramona menggeledah saku dekatnya dengan cekatan, lalu mengeluarkan sebuah komunikator yang hancur berkeping-keping. Panel yang diukir dengan lambang Universitas Mythag telah dilepas, memperlihatkan roda gigi internal yang memiliki bekas terbakar."
  },
  AvgDialog_35536_Content_26 = {
    Text = "Saya mencoba mengubah frekuensi osilasi inti referensi komunikator, sehingga berhasil menghubungi sekolah. Meskipun waktu kontak singkat, itu cukup untuk menjelaskan semua hal yang perlu disampaikan."
  },
  AvgDialog_35536_Content_27 = {
    Text = "Boneka dan yang lainnya akan mempersiapkan operasi pemisahan \"Benih Suci\", dan Kakak William juga sudah tiba di pelabuhan untuk menyambut."
  },
  AvgDialog_35536_Content_28 = {
    Text = "Tapi di laut selama waktu ini... kita hanya bisa mengandalkan diri sendiri."
  },
  AvgDialog_35536_Content_29 = {
    Text = "Melindungi Murphy, melawan Goliath, membantu kapten membawa kapal kembali ke daratan... Untung ada Tulu yang membantu kita, dan Caecus tampaknya juga bersedia memberikan bantuan, jika tidak..."
  },
  AvgDialog_35536_Content_3 = {
    Text = [[
Kamu dan Ramona kembali ke luar Ruang Kekuatan. 
 Pertumbuhan jaringan berlebih semakin parah, terlihat jelas sepanjang jalan.]]
  },
  AvgDialog_35536_Content_30 = {
    Text = "Kalau tidak, hanya dengan kekuatan kita berdua... sepertinya kita tidak akan bisa bertahan sampai sekarang."
  },
  AvgDialog_35536_Content_31 = {
    Text = "Harus menghentikan kelahiran \"Benih Suci\""
  },
  AvgDialog_35536_Content_32 = {
    Text = "Jika ritual dibiarkan berlanjut, tidak diketahui monster seperti apa yang akan menetas dari \"Benih Suci\" di dalam tubuh Murphy."
  },
  AvgDialog_35536_Content_33 = {
    Text = "Benar… bagi Murphy, bagi dunia, kelahiran \"Saint Embryo\" hanya akan menjadi bencana."
  },
  AvgDialog_35536_Content_34 = {
    Text = "Apalagi karena itu sudah menjadi inti dari Clades, kita tidak bisa membiarkannya begitu saja."
  },
  AvgDialog_35536_Content_35 = {
    Text = "Ini adalah sesuatu yang hanya bisa kita lakukan."
  },
  AvgDialog_35536_Content_37 = {
    Text = "Benar... Ini adalah sesuatu yang hanya bisa kita lakukan."
  },
  AvgDialog_35536_Content_38 = {
    Text = "Tetap Roh, terus maju."
  },
  AvgDialog_35536_Content_4 = {
    Text = "Ramona menempelkan telinganya di pintu dan mendengarkan sejenak. Setelah memastikan tidak ada suara dari dalam, dia mengangguk ke arahmu sebagai tanda."
  },
  AvgDialog_35536_Content_5 = {
    Text = "Kraaaak——"
  },
  AvgDialog_35536_Content_6 = {
    Text = "Pintu kabin yang dulunya memungkinkanmu dan Murphy keluar masuk dengan bebas, sekarang tersangkut macet di bingkai pintu akibat terumbu karang yang tumbuh menjulang. Tak peduli seberapa keras kamu dan Ramona berusaha, pintu itu tetap tidak bergerak sedikit pun."
  },
  AvgDialog_35536_Content_7 = {
    Text = "Ruang kekuatan memiliki pintu lain, mari kita mengitari."
  },
  AvgDialog_35536_Content_8 = {
    Text = "Selain suara angin, aku tidak mendengar suara lain sebelumnya, tapi tetap harus berhati-hati."
  },
  AvgDialog_35536_Content_9 = {Text = "Baiklah."},
  AvgDialog_35537_Content_1 = {
    Text = "Lemuria\"Kemuliaan\""
  },
  AvgDialog_35537_Content_10 = {
    Text = "Pembantu manusia dari Sang Ibu Ilahi sama sekali tidak berarti, ancaman sebenarnya adalah dia…"
  },
  AvgDialog_35537_Content_11 = {
    Text = "<Yellow:\"Yang Mulia\"> sudah di ujung lidah, namun Caecus akhirnya menarik napas dalam-dalam dan menelan kata itu kembali."
  },
  AvgDialog_35537_Content_12 = {
    Text = "Replika golem Mythag itulah lawan sebenarnya kita… lawan sebenarnya bagi Pelaut."
  },
  AvgDialog_35537_Content_13 = {
    Text = "Tidak buruk, tampaknya aturan-aturan konyol itu sudah tidak bisa membelenggu kamu lagi."
  },
  AvgDialog_35537_Content_14 = {
    Text = "Setelah urusan di sini selesai, aku akan secara pribadi bertanggung jawab atas Tautan-mu."
  },
  AvgDialog_35537_Content_15 = {
    Text = [[
Hanya tinggal menunggu satu kesempatan yang tepat sebelum kamu benar-benar berdiri di tempat tinggi. 
Jangan kecewakan aku, nak.]]
  },
  AvgDialog_35537_Content_16 = {
    Text = "Ya, ya. Terima kasih atas promosi Anda…"
  },
  AvgDialog_35537_Content_17 = {
    Text = "Dia menundukkan kepalanya dengan patuh, sementara Goliath bergerak dan menyebabkan kerusakan besar di Ruang Kekuatan yang sudah hampir tidak berbeda dari reruntuhan."
  },
  AvgDialog_35537_Content_18 = {
    Text = "Bilah raksasa menyeret di atas jejak-jejak yang rusak. Abu batu bara dan debu setelah ledakan terbelah oleh ujung bilah, mirip dengan aliran sungai yang terbuka."
  },
  AvgDialog_35537_Content_19 = {
    Text = "Bukankah dikatakan bahwa ada situasi khusus di Ruang Kekuatan, dan hanya saya yang bisa menyelesaikannya?"
  },
  AvgDialog_35537_Content_2 = {Text = "Hei, sial."},
  AvgDialog_35537_Content_20 = {
    Text = "Ya, ya... Saya merasakannya melalui Tautan, merasakannya..."
  },
  AvgDialog_35537_Content_21 = {
    Text = "Miryam-sama... Ya, aku bisa merasakan kehadiran Miryam-sama."
  },
  AvgDialog_35537_Content_22 = {Text = "Ah——!"},
  AvgDialog_35537_Content_23 = {
    Text = "Raksasa itu menendang keras di belakang lututnya, rasa sakit akibat tulang yang terkilir membuat Caecus terjatuh tak terkendali di antara puing-puing."
  },
  AvgDialog_35537_Content_24 = {
    Text = "Caecus tidak pandai berbohong, setiap kali berbohong selalu terbata-bata. Kebohongan yang buruk bahkan tidak bisa meyakinkan dirinya sendiri, apalagi menipu Goliath?"
  },
  AvgDialog_35537_Content_25 = {
    Text = "Lupakan wanita gila itu! Apakah kamu belum menyadarinya? Dia sama sekali tidak peduli dengan kalian, para manusia ikan!"
  },
  AvgDialog_35537_Content_26 = {
    Text = "Yang dia inginkan hanyalah Dewa itu, Dewa yang telah meninggalkan dia dan rakyat Lemuria sejak zaman prasejarah, menghilang tanpa jejak, Dewa yang hina!"
  },
  AvgDialog_35537_Content_27 = {
    Text = "Akan... akan mati."
  },
  AvgDialog_35537_Content_28 = {
    Text = "Rambutnya dijambak oleh Goliath dan ditarik ke atas, dia terpaksa mengangkat kepala untuk menatap mata raksasa itu. Keringat dingin mengalir masuk ke matanya, menyengat membran mukosa yang rapuh."
  },
  AvgDialog_35537_Content_29 = {
    Text = "Dia akan mati, dia akan mati karena pengkhianatan terhadap tuan Goliath…"
  },
  AvgDialog_35537_Content_3 = {
    Text = "Setelah menghindar selama ribuan hingga jutaan tahun, sekarang orang pendek itu tiba-tiba muncul untuk ikut campur dalam masalah yang kacau ini."
  },
  AvgDialog_35537_Content_30 = {
    Text = "Pada detik berikutnya setelah pikiran itu muncul, Caecus langsung dibanting keras oleh Goliath ke tanah, seperti tiang kapal yang patah."
  },
  AvgDialog_35537_Content_31 = {
    Text = "Pergilah, cari semua orang bodoh yang berkeliaran di luar sana."
  },
  AvgDialog_35537_Content_32 = {
    Text = [[
Caecus melarikan diri dari ruang kekuatan.
Setelah memastikan sosoknya tidak terlihat lagi, Goliath meletakkan senjatanya di samping tungku kekuatan yang menyala.]]
  },
  AvgDialog_35537_Content_33 = {
    Text = "… Hah, pantas saja disebut \"Raja Dewa\"."
  },
  AvgDialog_35537_Content_34 = {
    Text = "Hanya dengan satu pukulan, Tentakel meninggalkan luka terbuka di pinggang belakang raksasa. Darah kotor berwarna aneh mengalir pelan dari luka tersebut, meresap ke dalam tekstur kulit gelap."
  },
  AvgDialog_35537_Content_35 = {
    Text = "Tanganmu benar-benar tak kenal ampun... Heh."
  },
  AvgDialog_35537_Content_36 = {
    Text = "Tapi tidak apa-apa... dengan menggunakan boneka ilahi, orang-orang bodoh yang tinggal di Elworth akan tunduk pada saya dan mengakui saya sebagai raja."
  },
  AvgDialog_35537_Content_37 = {
    Text = "Kesempatan yang sangat langka, tak ada seorang pun yang bisa mengambilnya dari tangan saya."
  },
  AvgDialog_35537_Content_38 = {
    Text = "Goliath mengambil kembali senjatanya dari api, tanpa ragu meletakkan bilah raksasa itu di atas lukanya."
  },
  AvgDialog_35537_Content_39 = {
    Text = "Otot menyusut dengan cepat akibat suhu tinggi, disertai bau karat dari logam yang terbakar. Luka tersebut tidak lagi mengeluarkan cairan berwarna biru-hitam."
  },
  AvgDialog_35537_Content_4 = {
    Text = "Pelaut muda mengikuti raksasa dari belakang, melangkah dengan hati-hati dan tetap terdiam."
  },
  AvgDialog_35537_Content_40 = {
    Text = "Tuan Goliath, para Pelaut di kapal, sebagian besar sudah berada di sini."
  },
  AvgDialog_35537_Content_41 = {
    Text = "Caecus yang sempat pergi selama beberapa saat, kembali muncul dengan kelelahan yang jelas terlihat. Namun, Goliath tidak peduli dengan hal itu."
  },
  AvgDialog_35537_Content_42 = {
    Text = "Hanya segini orangnya?"
  },
  AvgDialog_35537_Content_43 = {
    Text = "Ya… Dan karena <Yellow:Pelarutan> menyebar, banyak orang tidak bisa berpartisipasi dalam Pertempuran."
  },
  AvgDialog_35537_Content_44 = {Text = "Cukup."},
  AvgDialog_35537_Content_45 = {
    Text = "Guh... Tuan Goliath..."
  },
  AvgDialog_35537_Content_46 = {
    Text = "Pemimpin Utama... guum... kembali... @2..."
  },
  AvgDialog_35537_Content_47 = {
    Text = "Kata-kata yang terucap dari mulut Pelaut membuat Goliath mengerutkan alis. Kata-kata itu sulit dikenali, tidak dapat dipahami, dan menolaknya — menolak mereka yang tidak memiliki darah ilahi mengalir di tubuhnya."
  },
  AvgDialog_35537_Content_48 = {
    Text = [[
...Cukup. 
Buka matamu lebar-lebar dan lihatlah kenyataan!]]
  },
  AvgDialog_35537_Content_49 = {
    Text = [[
Imam utama telah tiada, tapi Sang Ibu Ilahi masih ada! 
 Kita masih memiliki kesempatan untuk melanjutkan ritual, merebut kembali Sang Ibu Ilahi dari tangan para pendatang, dan menyambut kembalinya Sang Janin Ilahi!]]
  },
  AvgDialog_35537_Content_5 = {
    Text = "Anak muda, apa pendapatmu?"
  },
  AvgDialog_35537_Content_50 = {
    Text = "Pedang raksasa ini tidak akan mengecewakan misinya… Aku akan menjadi pisau terkuat dari dewa baru!"
  },
  AvgDialog_35537_Content_51 = {
    Text = "Guh... guh uh... @2 Kembali..."
  },
  AvgDialog_35537_Content_52 = {
    Text = "Dia akan kembali… Dia akan kembali!"
  },
  AvgDialog_35537_Content_54 = {
    Text = "Doa yang tidak terucapkan akhirnya membentuk aliran seperti pembacaan kitab suci, membuat Goliath merasa sangat jengkel."
  },
  AvgDialog_35537_Content_55 = {
    Text = "Dalam doa penuh semangat para pelaut, energi tak terwujud melayang masuk melalui celah pada badan kapal, melilit di sekitar Goliath."
  },
  AvgDialog_35537_Content_56 = {
    Text = "Rasa sakit dan kekencangan yang sudah dikenal membuat Goliath menutupi lehernya. Pembuluh darah di bawah pelipisnya menonjol satu per satu, matanya terbelalak penuh dengan urat darah."
  },
  AvgDialog_35537_Content_57 = {
    Text = "Sejak hari ia menandatangani kontrak dengan \"Miko Laut\", belenggu yang mengikatnya —— belenggu yang ia kira sudah sepenuhnya terlepas setelah ledakan itu ——"
  },
  AvgDialog_35537_Content_58 = {
    Text = "Kembali menjatuhkan hukuman padanya atas penghinaannya terhadap \"dewa\"."
  },
  AvgDialog_35537_Content_6 = {
    Text = "Saya, saya?"
  },
  AvgDialog_35537_Content_60 = {
    Text = "Ketika raksasa menyadarinya, kabut telah mengental menjadi lumpur yang kental dan nyata, berubah menjadi belati berbentuk aneh yang mengarah ke luka di lehernya."
  },
  AvgDialog_35537_Content_61 = {
    Text = "Perishite…"
  },
  AvgDialog_35537_Content_62 = {Text = "Kau……"},
  AvgDialog_35537_Content_63 = {
    Text = "Mengetahui identitasnya di masa lalu, seharusnya hanya tersisa satu orang di dunia ini ——"
  },
  AvgDialog_35537_Content_64 = {
    Text = "Miryam-sama?!"
  },
  AvgDialog_35537_Content_65 = {Text = "Miriam…"},
  AvgDialog_35537_Content_66 = {
    Text = "Setelah sesaat berpikir dan terdiam, para Pelaut meledak dalam sorakan penuh kegembiraan."
  },
  AvgDialog_35537_Content_67 = {
    Text = "Pemimpin Utama! <Big:Pemimpin Utama!><BigShake:Pemimpin Utama!>"
  },
  AvgDialog_35537_Content_68 = {
    Text = "Ha, ha… Kamu tidak apa-apa, itu sudah sangat bagus."
  },
  AvgDialog_35537_Content_69 = {
    Text = "Goliath mencoba menyingkirkan belati itu, namun ujung belati yang tiba-tiba menjadi lebih tajam melukai jarinya."
  },
  AvgDialog_35537_Content_7 = {
    Text = "Caecus sama sekali tidak siap untuk diinterogasi, kaget karena tiba-tiba ditanya."
  },
  AvgDialog_35537_Content_70 = {
    Text = "Aku tahu apa yang kamu pikirkan, Perishite."
  },
  AvgDialog_35537_Content_72 = {
    Text = "Membersihkan pengkhianat, menghilangkan hambatan penurunan dewa… menyingkirkan yang palsu, merebut kembali Ibu Dewa."
  },
  AvgDialog_35537_Content_73 = {
    Text = "Dengan cara ini, aku masih bisa memberikanmu kematian yang bermartabat."
  },
  AvgDialog_35537_Content_74 = {
    Text = [[
Waktu hingga Selaras
tersisa: <Red:30> menit]]
  },
  AvgDialog_35537_Content_8 = {
    Text = "Apakah ada hambatan komunikasi di antara kita? Apakah ada orang ketiga yang berakal di sini?"
  },
  AvgDialog_35537_Content_9 = {
    Text = "Ya, ya... sangat meminta maaf, Goliath."
  },
  AvgDialog_35538_Content_1 = {
    Text = "Komunikator kita, apakah harganya mahal?"
  },
  AvgDialog_35538_Content_2 = {
    Text = "Inti Perak yang digunakan dalam kernel dapat ditukar dengan properti di pusat Londinium di pasar gelap."
  },
  AvgDialog_35538_Content_3 = {
    Text = "Apa? Tiba-tiba teringat untuk bertanya tentang ini."
  },
  AvgDialog_35538_Content_4 = {
    Text = "Tidak, tidak ada apa-apa..."
  },
  AvgDialog_35820_Content_1 = {
    Text = "Bagaimana keadaan Caecus?"
  },
  AvgDialog_35820_Content_2 = {
    Text = "Tidak ada reaksi, juga tidak terlihat seperti akan melakukan serangan kepada kami."
  },
  AvgDialog_35820_Content_3 = {
    Text = "Fokus dulu pada Pelaut, tapi perhatikan Negara Caecus."
  },
  AvgDialog_35821_Content_1 = {
    Text = "Dewa palsu runtuh dan mengalami pembongkaran dalam tangisan, debu asap abu-abu biru memenuhi langit dan jatuh dengan suara berderak."
  },
  AvgDialog_35821_Content_10 = {
    Text = "Pelabuhan Kota Brilport, tempat Penjaga dan saya naik kapal. Kami... kembali?"
  },
  AvgDialog_35821_Content_11 = {
    Text = "Kami sudah kembali."
  },
  AvgDialog_35821_Content_12 = {
    Text = "Penjaga, Tulu, Kapten Elton, Celeste, Caecus… serta Murphy."
  },
  AvgDialog_35821_Content_13 = {
    Text = "Juga William Delaplume."
  },
  AvgDialog_35821_Content_14 = {
    Text = "Wey, Kakak Senior William..."
  },
  AvgDialog_35821_Content_15 = {
    Text = "Ketika kalian meninggalkan sekolah, kalian hanyalah tim berdua. Sekarang, sepertinya mobil yang telah kusiapkan tidak cukup untuk menampung semua orang."
  },
  AvgDialog_35821_Content_16 = {
    Text = "William menyapu pelabuhan dengan pandangan tajamnya. Akhirnya, dia menghela napas panjang dan tersenyum."
  },
  AvgDialog_35821_Content_17 = {
    Text = "Selamat datang kembali, Penjaga."
  },
  AvgDialog_35821_Content_18 = {
    Text = "William menyambutmu, kamu mencoba mengatakan sesuatu kepadanya dengan sedikit menyeringai. Namun, tiba-tiba saja, pandangan matamu tanpa terkendali menjadi sayu."
  },
  AvgDialog_35821_Content_19 = {
    Text = "Semua kelelahan, kebingungan, dan penderitaan lenyap dalam kehampaan. Bayangan temanmu yang berlari ke arahmu dengan cemas menjadi gambar terakhir dalam memori, diikuti oleh keheningan gelap yang menenangkan…"
  },
  AvgDialog_35821_Content_2 = {
    Text = "Hati-hati, jangan sampai menghirup debu ini."
  },
  AvgDialog_35821_Content_3 = {
    Text = "Sebelum suara itu hilang, dek di bawah kaki mulai bergetar hebat. Badan kapal mengeluarkan suara berderit yang tajam, seolah-olah itu adalah jeritan terakhir seorang korban tenggelam."
  },
  AvgDialog_35821_Content_4 = {
    Text = "Ya?! Kapal, kapal... apakah akan tenggelam?!"
  },
  AvgDialog_35821_Content_5 = {
    Text = "Badan kapal bergoyang tak beraturan, semua orang memegang tepi kapal pun tidak ada gunanya. Dunia seakan runtuh, dan debu yang berjatuhan memenuhi langit, sepenuhnya menghalangi pandangan kalian."
  },
  AvgDialog_35821_Content_6 = {
    Text = "Tidak bisa melihat bulan dengan jelas lagi, tidak bisa melihat permukaan laut, dan sulit melihat teman di sebelah."
  },
  AvgDialog_35821_Content_7 = {
    Text = "Sesaat sebelum tiruan debu menelan segalanya, dunia di hadapan mata menjadi luar biasa jelas."
  },
  AvgDialog_35821_Content_8 = {
    Text = "Gelombang laut yang tak henti-hentinya terdengar akhirnya mereda, dan di malam yang cerah, cahaya bulan terasa begitu lembut dan tenang."
  },
  AvgDialog_35821_Content_9 = {
    Text = "Apakah ini... pelabuhan?"
  },
  AvgDialog_35822_Content_1 = {
    Text = "Bintang bengkok"
  },
  AvgDialog_35822_Content_10 = {
    Text = "Bayangan ular raksasa tiba-tiba mengangkat kepalanya tinggi-tinggi, mengangkat Murphy ke dalam cahaya bulan."
  },
  AvgDialog_35822_Content_11 = {
    Text = "Sepasang demi sepasang tangan kecil dan halus berwarna hitam muncul dari rongga dada gadis itu, bergerak dan menenun, lapis demi lapis membungkus tubuh gadis itu, dan akhirnya membentuk kepompong raksasa berwarna hitam."
  },
  AvgDialog_35822_Content_12 = {
    Text = "Dalam raungan yang tuli, tangan dan benang hitam menjadikan ular raksasa sebagai penyangga, membuat kepompong melilit erat di tubuh besar ular tersebut."
  },
  AvgDialog_35822_Content_13 = {
    Text = "Kulit kepompong menjadi transparan akibat pembengkakan, tak terhitung banyaknya tangan saling bertautan membentuk singgasana, mengangkat tinggi-tinggi sebuah jantung pucat."
  },
  AvgDialog_35822_Content_15 = {
    Text = "Wanita itu berlutut di haluan kapal, menundukkan kepalanya kepada keberadaan yang sangat terdistorsi."
  },
  AvgDialog_35822_Content_16 = {
    Text = "Angin membawa bisikan yang jauh dan tidak dikenal, seperti ular berbisa di Bayangan mengeluarkan lidahnya, membuat bulu kudukmu berdiri."
  },
  AvgDialog_35822_Content_17 = {
    Text = "Bagaimana mungkin… Murphy bisa berada di tangan Miryam?"
  },
  AvgDialog_35822_Content_18 = {
    Text = "Ramona dan Caecus menopangmu dari kiri dan kanan, kalian bertiga berdiri dalam satu garis lurus, memandang ke atas menuju monster raksasa yang menghalangi cahaya bulan."
  },
  AvgDialog_35822_Content_19 = {
    Text = "Terlambat… semuanya sudah terlambat."
  },
  AvgDialog_35822_Content_2 = {
    Text = "Kalian mengikuti arah penyelaman Miryam dan segera mengejarnya ke dek utama."
  },
  AvgDialog_35822_Content_20 = {
    Text = "Inilah hal yang sebelumnya ingin aku peringatkan kalian... Tuan Miriam memerintahkan aku untuk memadamkan dapur tenaga terakhir, bermaksud memperdaya kalian semua ke dalam jebakan yang telah kami siapkan."
  },
  AvgDialog_35822_Content_21 = {
    Text = "Meskipun Sang Ibu… meskipun Murphy tidak bertindak bersama kalian, ini memberi Goliath kesempatan untuk merebutnya."
  },
  AvgDialog_35822_Content_22 = {
    Text = "Tautan Caecus memberikan rangsangan singkat seperti jarum adrenalin yang menusuk roh, kesadaran secara bertahap tersusun kembali di tengah rasa sakit."
  },
  AvgDialog_35822_Content_23 = {
    Text = "Tidak ada lagi suara peluit dan bisikan yang melengkung di dalam pikiranmu. Kamu berkedip, untuk pertama kalinya sejak ledakan merasakan dunia roh begitu jelas ——"
  },
  AvgDialog_35822_Content_24 = {
    Text = "Pembentukan kepompong raksasa membawa banyak polusi ke dunia Domain di sekitarnya. Sulit untuk menemukan Murphy di dalam cairan keruh di dalam kepompong. Namun, tanpa diragukan lagi, kamu melihat kilatan cahaya yang berasal dari seseorang yang masih hidup."
  },
  AvgDialog_35822_Content_25 = {
    Text = "Tidak, masih sempat."
  },
  AvgDialog_35822_Content_26 = {
    Text = "Dia masih hidup, kita masih punya kesempatan. Apapun yang terjadi… coba dekati mereka terlebih dahulu."
  },
  AvgDialog_35822_Content_27 = {
    Text = [[
Tapi tubuhmu... Tidak, biarkan aku pergi sendiri. 
 Caecus, bisakah kau sementara menjaga Penjaga?]]
  },
  AvgDialog_35822_Content_28 = {
    Text = "Ramona, dengan sikap tegas yang jarang terlihat, menolakmu. Dia melepaskan tanganmu dari lengannya dan dengan khidmat menyerahkanmu kepada Caecus."
  },
  AvgDialog_35822_Content_29 = {
    Text = "Baiklah… aku akan berusaha sepenuhnya."
  },
  AvgDialog_35822_Content_3 = {
    Text = "Saat meninggalkan anak tangga terakhir, sebuah makhluk raksasa yang tidak dikenal tiba-tiba menabrak kapal kargo, menyebabkan badan kapal miring dan mengubah arahnya."
  },
  AvgDialog_35822_Content_30 = {
    Text = "Tunggu dulu, aku belum mengatakan bahwa aku akan membiarkanmu pergi sendirian!"
  },
  AvgDialog_35822_Content_31 = {
    Text = "Caecus hanya dengan satu tangan sudah mencengkeram kamu, dengan mudah menghentikan perlawananmu."
  },
  AvgDialog_35822_Content_32 = {
    Text = "Namun, Ramona baru saja melangkah beberapa langkah, telinga sirip Caecus sudah bergerak dengan gesit."
  },
  AvgDialog_35822_Content_33 = {
    Text = "Saat berikutnya, dia menjatuhkan senjatanya, memelukmu, dan berguling menjauh dari posisi berdiri sebelumnya. Pedang raksasa terbang dari kejauhan, menghancurkan serpihan papan dek yang patah dan menyebarkan pecahan ke segala arah."
  },
  AvgDialog_35822_Content_34 = {
    Text = "Penjaga, Caecus!"
  },
  AvgDialog_35822_Content_35 = {
    Text = "Caecus menggelengkan kepala, memberi isyarat bahwa dia tidak apa-apa. Setelah memeriksa bahwa tidak ada luka baru pada tubuhmu, dia mengambil senjata dan berdiri di depanmu untuk melindungimu."
  },
  AvgDialog_35822_Content_36 = {
    Text = "Pada saat itulah kamu baru menyadari bahwa mata pisaunya telah menggores sirip punggungnya. Jaringan yang semula sekuat sirip ikan pedang itu kini robek tanpa ampun, dan menempel miring di punggungnya."
  },
  AvgDialog_35822_Content_37 = {
    Text = "Wajahnya berkerut karena rasa sakit, namun pada akhirnya, Caecus tetap meluruskan punggungnya dengan bangga, menatap lurus ke arah raksasa yang menyeringai dari kejauhan."
  },
  AvgDialog_35822_Content_38 = {
    Text = "Tuan Goliath, tolong jangan maju lagi."
  },
  AvgDialog_35822_Content_39 = {
    Text = [[
Dia menggunakan seluruh kekuatannya untuk mendorongmu ke arah Ramona. 
Sedangkan tubuhnya yang kurus, berdiri di antara kamu dan Goliath.]]
  },
  AvgDialog_35822_Content_4 = {Text = "Hati-hati!"},
  AvgDialog_35822_Content_40 = {
    Text = "Percayalah pada Caecus! Biar dia menahan Goliath dulu, kita segera mengambil jalan memutar melalui kargo untuk mendekati benda itu!"
  },
  AvgDialog_35822_Content_5 = {
    Text = "Caecus dan Ramona menopangmu dari sisi kiri dan kanan, lalu berdiri tegak bersama-sama."
  },
  AvgDialog_35822_Content_6 = {
    Text = "Saat berikutnya, diiringi suara gemuruh ombak yang memekakkan telinga, bayangan menutupi langit dan mendarat di atas kalian."
  },
  AvgDialog_35822_Content_7 = {
    Text = "Lihat! Itu!"
  },
  AvgDialog_35822_Content_9 = {
    Text = "Itu... itu Murphy!"
  },
  AvgDialog_35823_Content_1 = {
    Text = "Barusan kau menggunakan penelusuran Roh, kan? Tubuhmu…"
  },
  AvgDialog_35823_Content_2 = {
    Text = "Saya baik-baik saja… Ugh!"
  },
  AvgDialog_35823_Content_3 = {
    Text = "Efek analgesik dari lonjakan adrenalin tiba-tiba menghilang, kedua kakimu langsung lemas. Jika Ramona tidak menopangmu, mungkin kamu sudah terbaring di tanah sekarang."
  },
  AvgDialog_35823_Content_4 = {
    Text = "Sebelum menjalani pemeriksaan menyeluruh, jangan coba-coba menggunakan kekuatan roh lagi."
  },
  AvgDialog_35824_Content_1 = {
    Text = "Jalan yang tersesat"
  },
  AvgDialog_35824_Content_10 = {
    Text = "Miryam... saya... tidak..."
  },
  AvgDialog_35824_Content_11 = {
    Text = "Dia mencoba melepaskan diri dari siksaan ini, tetapi semakin dia berjuang, semakin kuat kekuatan kuno itu menjadi, seolah-olah mengejek ketidakberdayaannya dan kelemahannya."
  },
  AvgDialog_35824_Content_12 = {
    Text = "Pandangan sekilasnya akhirnya jatuh pada dirimu dan Ramona, dengan kilatan pandangan meminta bantuan."
  },
  AvgDialog_35824_Content_13 = {
    Text = "Cukup! Miryam!"
  },
  AvgDialog_35824_Content_14 = {
    Text = "Ramona segera memahami situasi, dia menghunus pedangnya untuk menghalangi Miryam. Mata pedang langsung menunjuk leher jenjang wanita itu, sementara tetesan darah yang tampak lebih kelam perlahan mengalir menuruni tekstur logam."
  },
  AvgDialog_35824_Content_15 = {
    Text = "Namun, rasa sakit di wajah Caecus tidak berkurang sedikit pun. Dia jatuh berlutut dengan kewalahan, bahkan tidak mampu mengangkat kepalanya lagi."
  },
  AvgDialog_35824_Content_16 = {
    Text = "Kami akan melindungi Murphy dan menggagalkan ritual ini. Selama kami masih ada, \"mimpi besar\" yang ingin kau wujudkan tidak akan pernah berhasil."
  },
  AvgDialog_35824_Content_17 = {
    Text = "Menyiksa Pembangun yang terhubung dengan Rohmu... kami juga tidak akan menjadi lemah karenanya."
  },
  AvgDialog_35824_Content_18 = {
    Text = "... Apakah begitu?"
  },
  AvgDialog_35824_Content_19 = {
    Text = "Miryam mengangkat kepalanya dan memperlihatkan senyuman yang penuh misteri. Matanya telah tercemar oleh kegilaan, dipenuhi dengan ketakutan dingin yang sulit dijelaskan."
  },
  AvgDialog_35824_Content_2 = {
    Text = "Miryam berdiri di atas reruntuhan, kedua kakinya terluka oleh serpihan besi yang menonjol. Darah berwarna gelap mengalir deras."
  },
  AvgDialog_35824_Content_20 = {
    Text = "Mereka yang berjalan bersama Pseudo-Raja, orang-orang yang menghina Kekuatan Tuan kami dengan ketidak hormatan... perasaan kalian tidak pernah menjadi perhatian bagi tubuh yang dangkal ini."
  },
  AvgDialog_35824_Content_21 = {
    Text = "Nada suaranya meninggi, membawa serta rasa mencekam yang membuat orang merinding, seolah-olah akan melahap segalanya dalam kegilaan."
  },
  AvgDialog_35824_Content_22 = {
    Text = "Miryam tiba-tiba menarik kembali tangannya, Caecus terjatuh ke tanah seperti boneka yang ditinggalkan oleh pemiliknya."
  },
  AvgDialog_35824_Content_23 = {
    Text = "Dia membungkuk dan terbaring di tanah, otot lehernya berkedut, merayakan kelangsungan hidup tubuhnya dengan batuk yang hebat."
  },
  AvgDialog_35824_Content_24 = {
    Text = "Bangkitlah, lanjutkan pertempuran, Caecus."
  },
  AvgDialog_35824_Content_25 = {
    Text = "Mengelilingi dia, para Pelaut yang sudah gelisah segera menerjang maju, mengelilingi kalian."
  },
  AvgDialog_35824_Content_26 = {
    Text = "Ini adalah kesempatan terakhirmu, bangkitlah, sapu bersih orang-orang ini… sapu bersih musuh dari Kedatangan Ranah dewa!"
  },
  AvgDialog_35824_Content_3 = {
    Text = "Seiring dengan dia berdiri tegak, jejak yang ditinggalkan oleh langkah-langkahnya membentuk jalan berdarah yang mengerikan, memancarkan hawa dingin yang menusuk tulang."
  },
  AvgDialog_35824_Content_4 = {Text = "Miriam…"},
  AvgDialog_35824_Content_5 = {
    Text = "Miryam memberimu pandangan sinis, dengan sikap angkuh dan tanpa sedikit pun menunjukkan keputusasaan meskipun telah dikalahkan."
  },
  AvgDialog_35824_Content_6 = {
    Text = "Jika bukan karena tubuhnya terus-menerus menyampaikan rasa sakit dari ledakan sesaat, adegan kegilaannya yang kehilangan akal sehat tampaknya hanya merupakan khayalanmu."
  },
  AvgDialog_35824_Content_7 = {
    Text = "Caecus, kau seharusnya tidak bersikap terlalu lembut."
  },
  AvgDialog_35824_Content_8 = {
    Text = [[
Dia sepenuhnya mengabaikan keberadaanmu dan Ramona, hanya terus mendesak Caecus dengan langkah mantap. 
Seiring dengan semakin dekatnya dia, cincin hitam di leher Caecus berkedip lagi.]]
  },
  AvgDialog_35824_Content_9 = {
    Text = "Cincin hitam itu seperti sulur gelap yang setiap kali jantung Caecus berdetak, ikatan tidak menyenangkan itu semakin erat. Seperti bayangan yang merambat ke jalan-jalan saat senja, menggerogoti vitalitas hidupnya."
  },
  AvgDialog_35825_Content_1 = {
    Text = "Benar-benar menyusahkan, aku berharap saat aku masih kecil, aku tidak sesulit Dia."
  },
  AvgDialog_35825_Content_10 = {
    Text = "Penghalang berwarna merah muda pucat hancur saat terkena pukulan, langkah kaki yang ringan semakin mendekat dari kejauhan. Suara itu bahkan menembus gendang telingamu yang tersumbat, terdengar sangat jelas seperti tak pernah sebelumnya."
  },
  AvgDialog_35825_Content_11 = {
    Text = "Bagaimana mungkin bisa menghukum si cengeng tanpa kehadiran \"Ibu\" yang agung?"
  },
  AvgDialog_35825_Content_12 = {
    Text = "Murphy! <Yellow:Pembentukan Pembangun>mu... berhasil seperti yang diharapkan!"
  },
  AvgDialog_35825_Content_13 = {
    Text = "Hmph... aku akan datang lagi untuk mencari masalah denganmu nanti. Sekarang, aku harus menyelesaikan urusan dengan orang ini!"
  },
  AvgDialog_35825_Content_2 = {
    Text = "Penjaga yang bisa jatuh tertidur di mana saja saat kecil pasti sangat penurut."
  },
  AvgDialog_35825_Content_3 = {
    Text = "Ramona menjawab dengan nada bercanda. Tangannya yang memegang pedang sudah gemetar tak terkendali, jelas bahwa dia telah mencapai batas fisiknya."
  },
  AvgDialog_35825_Content_4 = {
    Text = "Namun, ketika tentakel \"Anak Suci\" kembali menghantam, Ramona tetap maju dengan teguh dan memukul menyimpang tentakel yang sedang diayunkan."
  },
  AvgDialog_35825_Content_5 = {
    Text = "Gaya besar menghantam tangan kanan, senjata hampir terlepas. Namun, dia hanya menarik napas dalam-dalam dan kembali mencengkeram rapier dengan kuat."
  },
  AvgDialog_35825_Content_6 = {
    Text = "Pastikan untuk menyingkirkan-Nya sebelum kapal berlabuh."
  },
  AvgDialog_35825_Content_7 = {
    Text = "Di sudut pandang, hawa dingin yang tidak biasa mulai menyebar. Ketika kamu menyadari bahwa itu adalah Tentakel lain, ia sudah meluncur ke belakang kalian —"
  },
  AvgDialog_35825_Content_9 = {
    Text = "Dia telah menyiksa saya begitu lama... kalian ingin menyingkirkan-Nya secara diam-diam? Aku yang pertama tidak setuju!"
  },
  AvgDialog_35826_Content_1 = {
    Text = "Api yang terinternalisasi"
  },
  AvgDialog_35826_Content_10 = {
    Text = "Murphy, bagaimana kondisi Tubuhmu?"
  },
  AvgDialog_35826_Content_11 = {
    Text = "Murphy duduk di sudut ruang kemudi, ujung kuncir kuda jatuh dengan santai di atas bahunya. Penampilannya tampak pucat dan kusut, sama sekali tidak menunjukkan kesan manja dan sombong seperti sebelumnya."
  },
  AvgDialog_35826_Content_12 = {
    Text = "Murphy, Murphy?"
  },
  AvgDialog_35826_Content_13 = {
    Text = "Matanya tampak kosong dan bingung, pandangannya jatuh pada dadanya sendiri."
  },
  AvgDialog_35826_Content_14 = {
    Text = "Tangan dengan lembut membelai dada, ujung jarinya menggambar lingkaran kecil di atas jantungnya. Di bawah sana adalah jantung manusianya yang rapuh, sekaligus bom waktu yang terus-menerus menggerogoti hidupnya."
  },
  AvgDialog_35826_Content_15 = {
    Text = "Setiap detak jantung dipenuhi dengan rasa sakit, tidak hanya menyiksa tubuhnya, tetapi yang lebih menakutkan adalah teror dan ketidaktenangan yang memengaruhi Roh."
  },
  AvgDialog_35826_Content_16 = {
    Text = "Semakin aktif... Dia terus bergerak."
  },
  AvgDialog_35826_Content_17 = {
    Text = "Pikirannya perlahan tenggelam ke dalam kabut di dalam hatinya. Dia menutup mata dan berusaha untuk melakukan percakapan tanpa suara dengan parasit yang sedang menggerogotinya."
  },
  AvgDialog_35826_Content_18 = {
    Text = "Namun, Murphy belum sempat mendapatkan respons dari jantungnya, ketika perhatiannya tiba-tiba teralihkan oleh suara benda berat yang jatuh di luar pintu kabin."
  },
  AvgDialog_35826_Content_19 = {
    Text = "Setelah menyentuh tentakel lagi, rasa sakit yang tajam muncul dari kedalaman jiwa. Rasa sesak yang tiba-tiba menghancurkan kekuatan Tulu yang terakumulasi, menciptakan suara benturan saat tentakel jatuh ke dek."
  },
  AvgDialog_35826_Content_2 = {
    Text = "Kedua siswa itu sudah pergi begitu lama..."
  },
  AvgDialog_35826_Content_20 = {
    Text = "Hukuman rahasia Lemuria…"
  },
  AvgDialog_35826_Content_21 = {
    Text = "Tulu? Ada apa?"
  },
  AvgDialog_35826_Content_22 = {
    Text = "Jangan keluar!"
  },
  AvgDialog_35826_Content_23 = {
    Text = "Organ dalam terasa hampir robek oleh kekuatan ini, Tulu terengah-engah sambil menumbangkan satu lagi Pelaut yang menyerbu maju, lalu tidak dapat bangkit kembali."
  },
  AvgDialog_35826_Content_24 = {
    Text = "Ini adalah rasa sakit yang disampaikan melalui Tautan… Penjaga sedang dalam masalah."
  },
  AvgDialog_35826_Content_25 = {
    Text = "Lebih banyak pelaut membanjiri platform dek di luar ruang kemudi, bau rumput laut dan plankton yang membusuk seketika menyelimuti semua orang."
  },
  AvgDialog_35826_Content_26 = {Text = "Goliath…"},
  AvgDialog_35826_Content_27 = {
    Text = "Oh... entah harus mengatakan bahwa wanita itu sangat memahami hati manusia, atau kalian terlalu polos."
  },
  AvgDialog_35826_Content_28 = {
    Text = "Awalnya, aku hanya berpikir untuk mencoba-coba. Tak disangka, kalian benar-benar bertindak sesuai dengan rencana wanita itu — bergerak terpisah meskipun kalian tahu bahwa Pelaut masih memburu kalian."
  },
  AvgDialog_35826_Content_29 = {
    Text = "Wanita itu... Apakah Miryam benar-benar tidak mati?!"
  },
  AvgDialog_35826_Content_3 = {
    Text = "Elton memutar kemudi beberapa kali dengan sia-sia. Seperti yang sudah diduga, tidak ada umpan balik kontrol yang terasa."
  },
  AvgDialog_35826_Content_30 = {
    Text = "Goliath meludah darah, nadanya penuh dengan penghinaan dan ejekan—penuh dengan ejekan terhadap dirinya sendiri."
  },
  AvgDialog_35826_Content_31 = {
    Text = "Sebagai <Yellow:\"Golem\">, kami tidak semudah itu mati, namun…"
  },
  AvgDialog_35826_Content_32 = {
    Text = [[
Goliath berjongkok di depan Tulu, meskipun hanya dengan satu lutut menyentuh tanah, dia tetap jauh lebih tinggi daripada Tulu.
Dia memandang Tulu dari atas ke bawah, melihat keringat dingin mengalir ke mata oranye muda milik Tulu.]]
  },
  AvgDialog_35826_Content_33 = {
    Text = "Namun, seperti halnya dirimu yang begitu luhur, pada akhirnya hanyalah keberadaan rapuh yang bergantung pada tautan untuk mempertahankan akal sehat."
  },
  AvgDialog_35826_Content_34 = {
    Text = "Apa pun yang dilakukan Miryam pada Penjaga-mu… sepertinya, itu telah memengaruhimu. \nDengan begini, aku yang diuntungkan."
  },
  AvgDialog_35826_Content_35 = {
    Text = "Goliath tidak lagi memfokuskan perhatiannya pada Tulu, dia langsung melewati Tulu dan mendekati bagian dalam ruang kemudi."
  },
  AvgDialog_35826_Content_36 = {
    Text = "Elton melangkah maju untuk melindungi Murphy, tetapi Goliath bahkan tidak repot-repot memberinya tatapan."
  },
  AvgDialog_35826_Content_37 = {
    Text = "Apa yang kau gunakan untuk menghentikanku? Apakah kau mengandalkan gadis semi-transparan ini?"
  },
  AvgDialog_35826_Content_38 = {
    Text = "Elton tanpa sadar melihat Celeste sekilas, tampaknya ingin seperti dulu, mendapatkan dorongan dari Pembangun yang jarang bicara."
  },
  AvgDialog_35826_Content_39 = {
    Text = "Namun, dia tidak mendapatkan respons seperti biasanya. Meskipun dia sudah meminum obat yang dikirimkan oleh Caecus, keberadaan Celeste tetap dalam bahaya."
  },
  AvgDialog_35826_Content_4 = {
    Text = "Tidak akan menghadapi masalah apa pun, kan……"
  },
  AvgDialog_35826_Content_40 = {
    Text = "Elton ragu."
  },
  AvgDialog_35826_Content_41 = {
    Text = "Aku akan pergi bersamamu, jangan mempersulit mereka."
  },
  AvgDialog_35826_Content_42 = {Text = "Murphy?!"},
  AvgDialog_35826_Content_43 = {
    Text = "Tulu terkejut mendengarnya. Dia berusaha untuk bangkit kembali, namun rasa sakit yang datang dari Tautan begitu menyayat hati, hingga akal sehatnya tercerai-berai ke sudut-sudut anggota tubuhnya, membuatnya sama sekali tidak bisa berkonsentrasi."
  },
  AvgDialog_35826_Content_44 = {
    Text = "Tidak apa-apa... jangan melanjutkan demi aku..."
  },
  AvgDialog_35826_Content_45 = {
    Text = [[
Oh? Apakah gadis suci yang melarikan diri akhirnya sadar sekarang? 
Jangan berpikir yang tidak-tidak, hati-hati jika salah langkah, semua orang akan ikut menanggung akibatnya.]]
  },
  AvgDialog_35826_Content_46 = {
    Text = "Saya tahu... apa yang harus dilakukan..."
  },
  AvgDialog_35826_Content_47 = {
    Text = "Murphy melangkah maju dua langkah, berdiri di bawah sinar bulan lalu menoleh ke belakang untuk memandang orang-orang yang ia pedulikan dan juga memperhatikannya. Siluetnya tampak kesepian dan terlihat seperti dalam keadaan bingung."
  },
  AvgDialog_35826_Content_48 = {
    Text = "Apakah itu ritual atau hal lainnya... Kali ini, aku tahu apa yang harus kulakukan."
  },
  AvgDialog_35826_Content_5 = {
    Text = "Laut menjadi bergelora di bawah cahaya bulan yang pucat. Kapal bergoyang di antara ombak, dan dek berderit seiring dengan goncangan kapal."
  },
  AvgDialog_35826_Content_6 = {
    Text = "Tulu bagaikan patung dewa yang tak tergoyahkan, berdiri tegak di luar pintu melawan angin, menghalangi para Pelaut yang tampaknya tak pernah lelah."
  },
  AvgDialog_35826_Content_7 = {
    Text = "Yu tahu apa yang sedang kamu pikirkan, Tautan antara Yu dan Penjaga dalam Negara yang baik."
  },
  AvgDialog_35826_Content_8 = {
    Text = "Sambil berbicara, tentakelnya dengan lincah melemparkan musuh lain ke laut."
  },
  AvgDialog_35826_Content_9 = {
    Text = "Mudah-mudahan {Male=dia,Female=dia} selamat…"
  },
  AvgDialog_35827_Content_1 = {
    Text = [[
"Pelaut" menyandang darah yang diberkati oleh dewa, sebagai kunci utama Tuan kita melampaui bencana purba...
Bintang-bintang telah selaras, kelahiran Tuan kita semakin dekat... Kaum pengecut tidak layak lagi berjalan bersama Ranah dewa.]]
  },
  AvgDialog_35827_Content_10 = {
    Text = "Caecus menundukkan kepalanya dan menggunakan senjatanya untuk menopang tubuhnya saat berdiri."
  },
  AvgDialog_35827_Content_11 = {
    Text = "Benar… Ini adalah kesempatan terakhirmu, kesempatan terakhir untuk membuktikan kesetiaanmu kepada Ranah dewa."
  },
  AvgDialog_35827_Content_13 = {
    Text = "Tombak itu bergerak dengan anggun di depan tubuh, menciptakan bayangan residu yang indah. Ujungnya akhirnya mengarah tepat pada Miryam, \"tuan\"-nya."
  },
  AvgDialog_35827_Content_14 = {
    Text = "Caecus masih tidak berani menengadah untuk menahan tatapan Miryam, tetapi dia berdiri di antara kalian dan Miryam, seperti dinding tipis yang kokoh."
  },
  AvgDialog_35827_Content_15 = {
    Text = "Maaf, Nyonya Miryam. Saya..."
  },
  AvgDialog_35827_Content_16 = {
    Text = "Tidak apa-apa, kamu bukan seorang Pelaut… Aku sudah mengetahuinya sejak awal."
  },
  AvgDialog_35827_Content_17 = {
    Text = "Miryam tertawa kecil, memutar bola matanya yang berwarna ungu mencolok, lalu mengalihkan pandangannya ke arahmu dan Ramona. Sepertinya, dia tiba-tiba kehilangan minat pada Caecus."
  },
  AvgDialog_35827_Content_18 = {
    Text = "Caecus menghela napas lega setelah menahan napasnya terus-menerus. Tepat pada detik berikutnya, ketika hembusan napas menyapu kulitnya, dia merasakan seluruh tubuhnya menjadi berat."
  },
  AvgDialog_35827_Content_19 = {
    Text = [[
Kedua kakinya tidak mampu lagi menopang tubuh bagian atasnya. Dia terjatuh ke tanah, dan perutnya mulai mengembang seperti ditiup angin. 
 Tulang punggung yang tumbuh secara mendadak merobek pakaiannya, memperlihatkan sirip punggung yang menyerupai ikan.]]
  },
  AvgDialog_35827_Content_2 = {
    Text = "Angkat kepalamu, Caecus."
  },
  AvgDialog_35827_Content_20 = {
    Text = "<Change>Mili…am……Tuan……"
  },
  AvgDialog_35827_Content_21 = {
    Text = "Bola mata tertekan oleh rongga mata dan otot yang berubah bentuk, menunjukkan warna abu-abu pucat seperti pembusukan. Kulit mulai ditumbuhi sisik-sisik kecil, dan erangan kesakitan terdengar seperti ratapan sedih dari Aequor."
  },
  AvgDialog_35827_Content_22 = {
    Text = "Miryam memutus Tautan Caecus!"
  },
  AvgDialog_35827_Content_23 = {
    Text = "Shh... Jangan panik, jangan panik."
  },
  AvgDialog_35827_Content_24 = {
    Text = "Miryam membungkuk dan menyentuh wajah Caecus. Segera, tangannya dipenuhi dengan cairan kental dan licin, menjadi bukti bahwa tubuh Caecus sedang mengalami transformasi."
  },
  AvgDialog_35827_Content_25 = {
    Text = "Ini adalah ujian bagimu… Hanya mereka yang benar-benar menguasai kekuatan Aequor yang dapat memperoleh panggilan dari tuanku…"
  },
  AvgDialog_35827_Content_26 = {
    Text = "Tidak seperti sebelumnya yang berubah menjadi monster sepenuhnya, kali ini Miryam tampak sangat tenang dan terkendali, berbahaya namun tetap anggun."
  },
  AvgDialog_35827_Content_27 = {
    Text = "Namun, bayangan di belakangnya yang sedang bergumam dan berubah bentuk, serta D-lendir yang meninggalkan jejak di bibir setiap kali kedua bibir bertemu, sepenuhnya mengungkapkan kegelapan yang mulai menyebar di dalam hatinya."
  },
  AvgDialog_35827_Content_28 = {
    Text = "Semua ini... adalah... ujian dari Tuhanku kepadaku..."
  },
  AvgDialog_35827_Content_29 = {
    Text = "Ini pengaruh dari \"Clades\"! Dia benar-benar membiarkan Pelarutan Clades menggerogoti Roh-nya sendiri…"
  },
  AvgDialog_35827_Content_3 = {
    Text = "Terus bertarung melawan Pelaut tidak akan membantu. Kami tidak bisa terus menghalangi Pelaut. Jika dia tetap dalam keadaan Negara linglung, kami hanya bisa meninggalkannya di tangan Miryam."
  },
  AvgDialog_35827_Content_30 = {
    Text = "Tidak hormat @2! Ini adalah ujian dari Tuan-ku kepadaku. Dialah yang telah menyucikan Perak-ku dan memberiku kesempatan untuk bangkit kembali!"
  },
  AvgDialog_35827_Content_31 = {
    Text = "Ini adalah anugerah yang diberikan-Nya kepadaku!"
  },
  AvgDialog_35827_Content_4 = {
    Text = "Bangun! Caecus!"
  },
  AvgDialog_35827_Content_5 = {
    Text = "Anak seperti kamu, bagaimana bisa bergaul dengan Pelaut?"
  },
  AvgDialog_35827_Content_6 = {
    Text = "Kau bilang, kau sudah menjadi golem? Maaf, aku tidak sengaja menyebutkannya…"
  },
  AvgDialog_35827_Content_7 = {
    Text = [[
Aku hanya merasa bahwa kamu tidak seburuk yang kamu bayangkan. 
Memilih untuk melarikan diri dari lingkungan yang menyakitkan, bukankah itu menunjukkan bahwa kamu memiliki kekuatan batin yang lebih besar daripada kebanyakan orang?]]
  },
  AvgDialog_35827_Content_8 = {
    Text = [[
Aku adalah temanmu, Caecus. 
 Tak peduli bagaimana kamu memandang dirimu sendiri, aku akan selalu mendukungmu untuk mengambil langkah yang benar.]]
  },
  AvgDialog_35828_Content_1 = {
    Text = "Di sinilah..."
  },
  AvgDialog_35828_Content_10 = {
    Text = "Elton tertawa 'haha' dua kali, lalu melambaikan tangan kepada semua orang yang hampir keluar dari area dermaga."
  },
  AvgDialog_35828_Content_11 = {
    Text = "Anak kecil tidak perlu ikut campur dalam urusan orang dewasa, baik itu aku yang mungkin selamanya takkan menemukan kampung halaman yang hilang, ataupun Celeste yang akan perlahan-lahan menghilang. Jika ini adalah akhir dari kita, aku akan menerimanya."
  },
  AvgDialog_35828_Content_12 = {
    Text = "Pergilah bersama mereka, nak. Jangan terlalu memikirkan kami."
  },
  AvgDialog_35828_Content_13 = {
    Text = "Siapa yang kamu sebut 'kecil'!"
  },
  AvgDialog_35828_Content_14 = {
    Text = "Ayo pergi, jangan menoleh lagi."
  },
  AvgDialog_35828_Content_15 = {
    Text = "Pergilah ke tempat yang kamu inginkan dan lakukan apa yang ingin kamu lakukan."
  },
  AvgDialog_35828_Content_16 = {
    Text = "Selalu merasa ada yang tidak beres, apakah sikap Kapten terlalu santai?"
  },
  AvgDialog_35828_Content_17 = {
    Text = "Untuk menemukan masa lalu yang hilang, dia menukar setengah dari kebebasannya demi Celeste."
  },
  AvgDialog_35828_Content_18 = {
    Text = "Apakah dia akan melepaskannya dengan begitu mudah dan tanpa beban?"
  },
  AvgDialog_35828_Content_2 = {
    Text = "Benar, itu daratan."
  },
  AvgDialog_35828_Content_20 = {
    Text = "Mobil beroda empat melaju cepat melewati pedesaan, menyusuri jalan-jalan di Londinium, lalu menerjang masuk ke daerah terpencil yang tidak berpenghuni, dan akhirnya berhenti di sebuah alun-alun."
  },
  AvgDialog_35828_Content_21 = {
    Text = "Kami sudah tiba."
  },
  AvgDialog_35828_Content_22 = {
    Text = [[
Lama sekali, aku pikir kalian tidak akan kembali kali ini. 
 Otakku memberitahuku bahwa kalian membawa masalah besar.]]
  },
  AvgDialog_35828_Content_23 = {Text = "Otak?"},
  AvgDialog_35828_Content_24 = {
    Text = "Kamu... Apakah Anda Guru Boneka?"
  },
  AvgDialog_35828_Content_25 = {
    Text = "Apa kamu sudah mengenalku?"
  },
  AvgDialog_35828_Content_26 = {
    Text = "Ramona, %player%, dan saya pernah membicarakan Anda... serta eksperimen penghentian waktu yang sedang Anda kerjakan."
  },
  AvgDialog_35828_Content_27 = {
    Text = "Oh? Bagaimana mereka memperkenalkan saya kepada Anda?"
  },
  AvgDialog_35828_Content_28 = {
    Text = "Murphy tanpa sadar melihat Penjaga, yang sedang mengedipkan mata dan membuat gestur aneh kepadanya. Jelas, dia tidak ingin Murphy mengatakan yang sebenarnya."
  },
  AvgDialog_35828_Content_29 = {
    Text = "Dia menutup mata, berusaha mengingat kembali saat Penjaga berbicara padanya tentang Universitas Mythag. Namun, segalanya bagaikan air yang mengalir, gambar yang baru saja terbentuk lenyap tanpa jejak di antara celah-celah jari dalam sekejap."
  },
  AvgDialog_35828_Content_3 = {
    Text = "Apa yang kau katakan, aku tahu ini daratan!"
  },
  AvgDialog_35828_Content_30 = {
    Text = "Murphy menjadi sangat penurut saat menghadapi Boneka…"
  },
  AvgDialog_35828_Content_31 = {
    Text = "Mungkin dia tidak pernah bersekolah, mungkin inilah rasa hormatnya terhadap Pengetahuan."
  },
  AvgDialog_35828_Content_32 = {
    Text = "Hei! Nona ini bisa mendengarnya!"
  },
  AvgDialog_35828_Content_33 = {
    Text = "Basakan sampai di sini."
  },
  AvgDialog_35828_Content_34 = {
    Text = [[
Topik penelitian tentang stagnasi waktu masih dalam tahap penelitian dan belum diverifikasi melalui percobaan pada hewan. 
Begitu kamu memasuki ruangan itu, kamu tidak akan memiliki kesempatan untuk kembali.]]
  },
  AvgDialog_35828_Content_35 = {
    Text = "Bagaimana, apakah kamu sudah membuat pilihan?"
  },
  AvgDialog_35828_Content_36 = {
    Text = "Pilih...an?"
  },
  AvgDialog_35828_Content_37 = {
    Text = "Apakah saya harus mengikuti keputusan orang lain?"
  },
  AvgDialog_35828_Content_38 = {
    Text = "Apakah saya bisa... memilih?"
  },
  AvgDialog_35828_Content_39 = {
    Text = "Tidak... tidak benar... aku seharusnya tidak berada di sini... aku sudah mempersiapkan semuanya dengan baik..."
  },
  AvgDialog_35828_Content_4 = {
    Text = [[
Jangan terlalu bersemangat. Jika tekanan darah naik, aktivitas parasit juga akan menjadi lebih sering. 
 Aku yakin kamu tidak ingin dibedah di tengah jalan, kan.]]
  },
  AvgDialog_35828_Content_40 = {
    Text = "Ini adalah mimpi buruk lain yang tidak dapat aku kendalikan, bukan?"
  },
  AvgDialog_35828_Content_41 = {
    Text = "\"Dia\"telah dilahirkan?"
  },
  AvgDialog_35828_Content_42 = {
    Text = "Apa semuanya sudah berakhir? Aku jelas... telah<Yellow:memutuskan> dengan tegas."
  },
  AvgDialog_35828_Content_43 = {
    Text = [[
Memori dan kesadaran tersesat dalam ilusi, dunia di bawah kaki hancur dan larut.
Murphy tiba-tiba mengulurkan tangan ingin meraih penjaga di sampingnya, tetapi hanya memegang segenggam debu di kekosongan.]]
  },
  AvgDialog_35828_Content_44 = {
    Text = "%player%……? Di mana kamu?"
  },
  AvgDialog_35828_Content_45 = {
    Text = "Pandangan jatuh ke dalam kegelapan yang penuh dengan chaos, pendengaran diperkuat hingga ekstrem, detak jantung terdengar memekakkan telinga. Benda-benda langit berputar dan bergulir di ruang gelap tanpa akhir, menggores dinding Hambatan Dimensi, bahkan membawa sedikit Ratapan sedih."
  },
  AvgDialog_35828_Content_46 = {
    Text = "Bukankah sudah disepakati... tidak akan meninggalkanku begitu saja?"
  },
  AvgDialog_35828_Content_47 = {
    Text = "Apakah kamu hampir \"kehilangan kendali\" barusan? Apakah ada masalah dengan siswa?"
  },
  AvgDialog_35828_Content_48 = {
    Text = "Tulu memegang dadanya, menunjukkan ekspresi masih merasa ngeri untuk pertama kalinya."
  },
  AvgDialog_35828_Content_49 = {
    Text = "...Tidak apa-apa. Goliath menculik Murphy, Penjaga pasti akan segera menghadapi pertempuran sengit, {Male=dia,Female=dia} membutuhkan bantuan Yu."
  },
  AvgDialog_35828_Content_5 = {
    Text = [[
Penjaga, jangan menggoda dia lagi. 
Tenang saja, Nyonya Celeste telah memberikanmu waktu. Kita akan kembali dengan selamat ke Londinium.]]
  },
  AvgDialog_35828_Content_50 = {
    Text = "Pergilah, aku dan Celeste akan baik-baik saja."
  },
  AvgDialog_35828_Content_51 = {
    Text = "...Apa ada masalah? Apakah semua orang baik-baik saja?"
  },
  AvgDialog_35828_Content_52 = {
    Text = "Sepertinya Miryam sudah sepenuhnya menyerah pada dirimu, Caecus."
  },
  AvgDialog_35828_Content_53 = {
    Text = "Caecus dengan susah payah bangkit berkali-kali, ejekan Goliath sudah tidak mampu mengguncang akal sehatnya."
  },
  AvgDialog_35828_Content_54 = {
    Text = "Apakah Anda juga... tidak setia kepada Tuan Miryam, bukan?"
  },
  AvgDialog_35828_Content_55 = {
    Text = "Maaf, Goliath. Saya tidak akan membiarkan Anda melewati saya lagi."
  },
  AvgDialog_35828_Content_56 = {
    Text = "Kenapa… kenapa? Kenapa kau membuat keputusan untukku tanpa izin lagi?"
  },
  AvgDialog_35828_Content_57 = {
    Text = "Dinding luar kepompong terlalu tebal, cairan di dalamnya juga sangat keruh, kami sama sekali tidak bisa melihat negara Murphy di dalam."
  },
  AvgDialog_35828_Content_58 = {
    Text = "Caecus tidak bisa menahan Goliath terlalu lama, izinkan aku mencoba penelusuran Roh lagi."
  },
  AvgDialog_35828_Content_59 = {
    Text = [[
Tidak bisa! Dunia rohmu tidak akan tahan dengan kekacauan seperti ini. 
Jika dunia roh runtuh, memperbaiki tubuh fisik sebanyak apa pun tidak akan ada gunanya!]]
  },
  AvgDialog_35828_Content_6 = {
    Text = "Terima kasih, Ramona... Berbicara denganmu benar-benar terasa menenangkan."
  },
  AvgDialog_35828_Content_60 = {
    Text = "Tapi Murphy dia——"
  },
  AvgDialog_35828_Content_61 = {
    Text = "Satu, dua... semuanya seperti ini... sekumpulan orang yang berbicara sendiri-sendiri."
  },
  AvgDialog_35828_Content_62 = {
    Text = [[
Tidak ada yang pernah meminta pendapatku, meski hanya sekali... Hmph. 
Dengan pengorbanan kalian demi bertahan hidup... Apakah aku pernah mengatakan bahwa aku menginginkannya?]]
  },
  AvgDialog_35828_Content_63 = {
    Text = "Syukurlah… <Yellow:barang itu> belum hilang…"
  },
  AvgDialog_35828_Content_64 = {
    Text = "Kapal kargo bergoyang di tengah ombak besar, satu demi satu gelombang mendorong badan kapal menjauh dari permukaan laut. Kamu merangkak keluar dari kabin, menatap kepompong hitam di atas, dan menggelengkan kepala kepada Ramona."
  },
  AvgDialog_35828_Content_65 = {
    Text = "——Lalu mengabaikan halangannya, menggenggam erat kunci perak yang bergetar, dan kembali tenggelam ke dalam ruang kesadaran."
  },
  AvgDialog_35828_Content_66 = {
    Text = "Di ruang yang dilapisi D-lendir, cahaya yang melambangkan kehidupan dan pengetahuan menjadi semakin bersinar."
  },
  AvgDialog_35828_Content_67 = {
    Text = "——Itu adalah pisau ritual yang memantulkan cahaya bulan yang dingin."
  },
  AvgDialog_35828_Content_68 = {Text = "——Uh!!"},
  AvgDialog_35828_Content_7 = {
    Text = "Hmph, kenapa ada orang yang tidak bisa belajar sesuatu yang baik darimu."
  },
  AvgDialog_35828_Content_70 = {
    Text = "Cahaya meledak dalam sekejap, bahkan memaksamu keluar dari dunia roh."
  },
  AvgDialog_35828_Content_71 = {
    Text = "Cahaya yang terlalu menyilaukan menusuk mata, membuat air mata mengalir tanpa bisa dikendalikan."
  },
  AvgDialog_35828_Content_73 = {
    Text = "Cairan keruh mengalir habis, dan mata akhirnya bisa fokus kembali pada gadis itu."
  },
  AvgDialog_35828_Content_74 = {
    Text = "Mata pisaunya menembus dalam ke arah dada, gadis yang mandi di bawah cahaya bulan membuka matanya."
  },
  AvgDialog_35828_Content_75 = {
    Text = "Bulan purnama yang melambangkan kematian sudah sangat dekat, namun di wajah muda itu tidak terlihat sedikit pun rasa takut."
  },
  AvgDialog_35828_Content_76 = {
    Text = "Aku berhasil... aku berhasil."
  },
  AvgDialog_35828_Content_77 = {
    Text = "Aku... menembus-Nya... Dia tidak akan dilahirkan lagi..."
  },
  AvgDialog_35828_Content_78 = {
    Text = "Dengan cara ini..."
  },
  AvgDialog_35828_Content_79 = {
    Text = "Tangan yang erat memegang gagang pisau terkulai lemas, cairan berwarna merah segar, kental, dan pekat mengalir deras dari mulut luka, mengalir melewati celah jari-jari dan masuk ke laut."
  },
  AvgDialog_35828_Content_8 = {
    Text = "Murphy berbalik untuk melihat dermaga. Elton dan Celeste masih berada di sisi kapal, memandangnya dari jauh."
  },
  AvgDialog_35828_Content_80 = {
    Text = "Darah dengan cepat mengalir keluar dari tubuhnya, Murphy tampak sangat pucat, namun seluruh tubuhnya memancarkan semangat hidup yang luar biasa."
  },
  AvgDialog_35828_Content_82 = {
    Text = "Tidak... tidak, tidak<Big:tidak tidak><BigShake:aaa——>"
  },
  AvgDialog_35828_Content_83 = {
    Text = "Ya Tuhan yang Maha Kuasa, ampunilah aku, ampunilah anak ini, ampunilah hamba-Mu yang setia…"
  },
  AvgDialog_35828_Content_84 = {
    Text = "Selaras akan tiba, Selaras akan tiba, akan tiba…"
  },
  AvgDialog_35828_Content_86 = {
    Text = "\"Plasenta\"pecah, \"jantung\"juga runtuh — tak terhitung banyaknya tangan menembus keluar dari tubuh, rongga dada hancur menjadi serpihan."
  },
  AvgDialog_35828_Content_87 = {
    Text = "Tangan yang cacat mencengkeram erat sisa-sisa yang sudah tak berbentuk, bertumpuk, mengembang, bertumpuk, mengembang——"
  },
  AvgDialog_35828_Content_88 = {
    Text = "Ah ah... Anda mendengarku... Anda menanggapiku..."
  },
  AvgDialog_35828_Content_9 = {
    Text = "Celeste, Kapten? Apakah kalian tidak bersama?"
  },
  AvgDialog_35828_Content_90 = {
    Text = "Mereka mendorong sebuah entitas cacat ke bawah sinar bulan."
  },
  AvgDialog_35828_Content_91 = {
    Text = "<Big:Dewa yang agung...!>"
  },
  AvgDialog_35829_Content_1 = {
    Text = "Kamu dan Ramona dipenuhi dengan kelelahan dan luka, akhirnya dengan susah payah mendekati \"Newborn\"."
  },
  AvgDialog_35829_Content_10 = {
    Text = "Jangan meminta maaf padaku, ini bukan salahmu... bukan salah siapa-siapa di antara kita."
  },
  AvgDialog_35829_Content_11 = {
    Text = "Sebaliknya, kami justru yang terakhir, menjadi penghalang untuk menghentikan hal ini masuk ke dalam masyarakat manusia."
  },
  AvgDialog_35829_Content_12 = {
    Text = "Tenang saja, polusi udara di Londinium sangat parah. Orang ini pasti tidak akan menemukan jalan masuk ke kota."
  },
  AvgDialog_35829_Content_13 = {
    Text = "Dengan bercanda untuk meredakan ketegangan, kamu dan Ramona melakukan pertukaran pandang terakhir kalinya, lalu melangkah maju dengan teguh—"
  },
  AvgDialog_35829_Content_14 = {
    Text = [[
Waktu hingga Selaras
tersisa: 0 menit]]
  },
  AvgDialog_35829_Content_2 = {
    Text = "\"Bayi baru lahir\" di dalam kokon hitam transparan memiliki bentuk yang terdistorsi, mirip dengan embrio primata raksasa yang rapuh."
  },
  AvgDialog_35829_Content_3 = {
    Text = "Kepala besar dan bulat, anggota tubuh bergerak kejang dengan canggung, seolah-olah sedang mencari arah untuk berkembang."
  },
  AvgDialog_35829_Content_4 = {
    Text = "Dia memancarkan aura kejahatan yang tak terlukiskan, membuatmu dan Ramona saling bertatapan sekilas — makhluk ini mungkin juga bisa menguasai Aequor, tetapi Dia bukanlah Genesis dari Kekuatan Tulu."
  },
  AvgDialog_35829_Content_5 = {
    Text = "Makhluk seperti itu... apakah kita benar-benar punya peluang untuk menang?"
  },
  AvgDialog_35829_Content_6 = {
    Text = "Aku tidak tahu."
  },
  AvgDialog_35829_Content_7 = {
    Text = "Kamu menggenggam tangan Ramona, menggerakkan otot-otot yang kaku dan lelah, lalu memberinya senyuman yang terlihat aneh."
  },
  AvgDialog_35829_Content_8 = {
    Text = "Maaf… Aku tidak tahu apakah kali ini kita masih bisa kembali ke Mythag."
  },
  AvgDialog_35829_Content_9 = {
    Text = "Ramona menggenggam tanganmu dengan erat, tanpa ragu."
  },
  AvgDialog_35830_Content_1 = {
    Text = "Caecus masih tidak bereaksi?"
  },
  AvgDialog_35830_Content_10 = {
    Text = "Kapal saya berlabuh di dermaga, bagaimana kalau kita menghangatkan diri di kapal saya?"
  },
  AvgDialog_35830_Content_11 = {
    Text = "Caecus terdiam di tempat, setelah beberapa saat, dia baru membuka mulut dengan kaku."
  },
  AvgDialog_35830_Content_12 = {
    Text = "Jika itu demi menjaga hubungan dengan ordo, tidak perlu mencoba menyenangkan saya."
  },
  AvgDialog_35830_Content_13 = {
    Text = "Menyogok? Aku bukan tipe orang yang akan membiarkan seseorang mati kedinginan di salju. Lendir di wajahmu sudah membeku sampai mengilap, jadi jangan menolak."
  },
  AvgDialog_35830_Content_14 = {
    Text = "Elton, memanfaatkan kesempatan saat Caecus terpaku, melangkah maju dua langkah dan dengan cepat meraih lengan kurus serta dinginnya."
  },
  AvgDialog_35830_Content_15 = {
    Text = "Ayo pergi, anggap saja sebagai perkenalan — aku Elton. Apakah kamu punya nama, nak?"
  },
  AvgDialog_35830_Content_17 = {
    Text = "Caecus, panggil aku Caecus saja."
  },
  AvgDialog_35830_Content_2 = {
    Text = "Sepertinya sedang melamun..."
  },
  AvgDialog_35830_Content_3 = {
    Text = "Pada saat yang genting ini?!"
  },
  AvgDialog_35830_Content_4 = {
    Text = "Ini adalah obat untuk musim ini. Jika tidak ingin mengalami keruntuhan Roh dan berubah menjadi mayat hidup, pastikan untuk meminumnya setiap tujuh hari sekali."
  },
  AvgDialog_35830_Content_5 = {
    Text = "Caecus meletakkan obat di tanah, mendorongnya perlahan sehingga botol itu menggelinding ke arah pria yang berdiri sepuluh kaki jauhnya."
  },
  AvgDialog_35830_Content_6 = {
    Text = "Di malam musim dingin, angin dingin berhembus kencang. Dia menarik jubah hitamnya yang lebar dan bergegas melawan angin, masuk ke dalam kegelapan."
  },
  AvgDialog_35830_Content_7 = {
    Text = "Tunggu… sebentar lagi akan turun salju. Pelabuhan alami ini bukan tempat tinggal tetap para Pelaut, kamu mau pergi ke mana untuk menghindari salju?"
  },
  AvgDialog_35830_Content_8 = {
    Text = "Ujung kalimatnya ditelan oleh angin yang sangat ganas dan menusuk tulang. Tudung jubah hitam tiba-tiba tersingkap, memperlihatkan sepasang sirip telinga berbentuk ikan di kepala pemuda itu, yang bergetar kedinginan karena terpaan angin."
  },
  AvgDialog_35830_Content_9 = {
    Text = "Hatinya terasa sesak, dengan canggung ia mengenakan tudungnya, dan langkah kakinya semakin tergesa-gesa saat meninggalkan tempat itu."
  },
  AvgDialog_35831_Content_1 = {
    Text = "Kotor@2……grrr!"
  },
  AvgDialog_35831_Content_10 = {
    Text = "Suara di sekitarnya tiba-tiba berhenti. Para Pelaut yang sebelumnya berteriak untuk mengusirnya terdiam dan menatap wanita di atas podium, menunggu instruksi selanjutnya dari tuan mereka."
  },
  AvgDialog_35831_Content_11 = {
    Text = "Angkat kepalamu."
  },
  AvgDialog_35831_Content_12 = {
    Text = "Dia akhirnya mengumpulkan keberanian untuk menengadah, dengan penuh rasa hormat seolah-olah sedang memandang dewi takdirnya."
  },
  AvgDialog_35831_Content_13 = {
    Text = "Tuan... saya..."
  },
  AvgDialog_35831_Content_14 = {
    Text = "Tak diragukan lagi, keturunan keluarga Aon... kamu dan nenek moyangmu memiliki beberapa kemiripan dalam penampilan."
  },
  AvgDialog_35831_Content_15 = {
    Text = "Tapi... terlalu lemah."
  },
  AvgDialog_35831_Content_16 = {
    Text = "Hatinya tiba-tiba tenggelam. Namun, hanya dengan menatap langsung ke Miryam saja sudah menghabiskan seluruh keberaniannya, apalagi membantah kesimpulan yang diambil oleh Miryam."
  },
  AvgDialog_35831_Content_17 = {
    Text = "Karena kamu sudah dibangunkan, demi keluarga Oen, aku bisa mempertahankan keberadaanmu sebagai golem... Pekerjaan menjaga hubungan antara Pelaut dan kolaborator manusia akan kuserahkan padamu di masa depan."
  },
  AvgDialog_35831_Content_18 = {
    Text = "Sebagai \"keturunan campuran\", kamu seharusnya paling memahami cara berkomunikasi dengan manusia, kan."
  },
  AvgDialog_35831_Content_2 = {
    Text = "Pelaut mengayunkan senjata, senjata dingin itu memantulkan cahaya perak di bawah sinar bulan, membuat Caecus tanpa sadar menyipitkan matanya."
  },
  AvgDialog_35831_Content_3 = {
    Text = "Dari pandangan yang kabur, dia melihat punggung kaki Miryam. Memori itu tiba-tiba terbawa kembali ke masa lalu, ke saat ketika dia merunduk di bawah altar dingin."
  },
  AvgDialog_35831_Content_4 = {
    Text = "Orang asing... guk..."
  },
  AvgDialog_35831_Content_5 = {
    Text = "Akhirnya… dia akhirnya tiba di sini."
  },
  AvgDialog_35831_Content_6 = {
    Text = "Pergi...@1…keluar!"
  },
  AvgDialog_35831_Content_7 = {
    Text = "Kegigihannya terhadap asal-usulnya, serta kegigihannya terhadap Pelaut, membawanya ke sini."
  },
  AvgDialog_35831_Content_8 = {
    Text = "Keturunan campuran... kotor! <Big:kotor!>"
  },
  AvgDialog_35831_Content_9 = {Text = "Diam."},
  AvgDialog_35832_Content_1 = {
    Text = "Cukup… Tugas yang kuberikan kepada Perishite, dia sudah menyelesaikannya."
  },
  AvgDialog_35832_Content_10 = {
    Text = "Kamu menahan rasa sakit dengan teguh, menggunakan akal sehat untuk memimpin ujung-ujung rohani masuk ke dalam Dunia Roh Caecus."
  },
  AvgDialog_35832_Content_11 = {
    Text = "Rumah di dunia rohnya runtuh. Begitu berhenti melangkah, kata-kata ejekan dan kebencian akan keluar dari sudut-sudut dunia seperti serangga beracun yang menggerogoti tekad pendatang."
  },
  AvgDialog_35832_Content_12 = {
    Text = "Kamu mengikuti suara rintihan minta tolong dan menemukan Caecus yang sedang meringkuk di sudut."
  },
  AvgDialog_35832_Content_13 = {
    Text = "Rohnya terjepit, terdesak, dan hanya bisa bersembunyi di dalam sebuah ruangan yang menyerupai kabin kapal. Jika bukan karena dia mengeluarkan suara teratur seperti memancarkan sinyal SOS, hampir saja kamu mengabaikan keberadaannya."
  },
  AvgDialog_35832_Content_14 = {Text = "Caecus…"},
  AvgDialog_35832_Content_15 = {
    Text = "Kamu mengulurkan tanganmu ke arahnya, dan pada saat kesadaran spiritual kalian bersentuhan, rasa sesak yang kuat langsung menyergap tenggorokanmu."
  },
  AvgDialog_35832_Content_16 = {
    Text = "Reaksi hipoksia kembali memunculkan pusing dan rasa sakit yang kau kira sudah berlalu. Semua orang yang terhubung secara Roh denganmu menunjukkan ekspresi pahit selama beberapa saat."
  },
  AvgDialog_35832_Content_17 = {
    Text = "Ramona yang paling terdampak, saat itu juga dia berkeringat dingin dan langsung jatuh berlutut di tanah."
  },
  AvgDialog_35832_Content_18 = {
    Text = "Kamu ingin meraihnya untuk menopangnya, tetapi hanya merasakan pandanganmu berputar-putar. Kamu tersandung dua langkah sebelum akhirnya terjatuh ke tanah ——"
  },
  AvgDialog_35832_Content_19 = {Text = "Hati-hati."},
  AvgDialog_35832_Content_2 = {
    Text = "Miryam mundur ke tepi celah yang robek di badan kapal, bersandar pada besi tajam. Ekspresinya tersembunyi dalam bayangan yang dibuat oleh mahkota, hanya bisa terlihat bibirnya bergerak seolah mengucapkan sesuatu."
  },
  AvgDialog_35832_Content_20 = {
    Text = "Hah... hah... Seolah-olah dalam sekejap, aku merasakan kematian begitu dekat..."
  },
  AvgDialog_35832_Content_21 = {
    Text = "Penjaga, apa yang sebenarnya terjadi pada Tubuhmu?"
  },
  AvgDialog_35832_Content_22 = {
    Text = "Kamu menggelengkan kepala dengan napas tersengal, lalu berdiri stabil dengan bantuan Caecus."
  },
  AvgDialog_35832_Content_23 = {
    Text = "Sekarang tidak ada waktu untuk menjelaskan, kita, kita—"
  },
  AvgDialog_35832_Content_24 = {
    Text = "Cepat ke dek! Ini adalah jebakan dari Miryam dan Goliath!"
  },
  AvgDialog_35832_Content_25 = {
    Text = [[
Ramona tidak bertanya lebih lanjut, tetapi dia juga tidak segera mengikuti kamu dan Caecus. 
 Dia menggunakan tangannya untuk mengeluarkan abu arang basah dari boiler, lalu dengan cepat menambahkan beberapa genggam batubara kering.]]
  },
  AvgDialog_35832_Content_26 = {
    Text = "Busi berputar, sisa-sisa air dengan cepat menguap, dan bau terbakar kembali memenuhi ruang kekuatan."
  },
  AvgDialog_35832_Content_27 = {
    Text = "Lebih baik kita pergi dari sini, Caecus. Kau yang memimpin jalan."
  },
  AvgDialog_35832_Content_3 = {
    Text = "——Lalu, dia melepaskan tangannya, membiarkan dirinya jatuh ke dalam laut."
  },
  AvgDialog_35832_Content_4 = {
    Text = "Permukaan laut yang disinari cahaya bulan tiba-tiba teraduk, membentuk jejak busa. Jejak itu membelah ombak dan terus berlanjut hingga ke sisi lain kapal."
  },
  AvgDialog_35832_Content_5 = {
    Text = "Cepat periksa kondisi Caecus!"
  },
  AvgDialog_35832_Content_6 = {
    Text = "Caecus sudah tidak mampu berbicara lagi. Setiap kali dia mencoba membuka mulut, yang keluar hanyalah aliran demi aliran lendir, seakan-akan organ dalamnya yang berlebih telah terasimilasi."
  },
  AvgDialog_35832_Content_7 = {
    Text = "Dia sudah hampir kehilangan wujud manusia, tetapi untungnya, dia hanya meringkuk kesakitan di sudut, tidak se-gila Helot yang terputus tautannya."
  },
  AvgDialog_35832_Content_8 = {
    Text = "Kamu berjongkok di depan Caecus dan tanpa ragu menggenggam tangannya."
  },
  AvgDialog_35832_Content_9 = {
    Text = "Tautkan dia"
  },
  AvgDialog_35984_Content_1 = {Text = "Grand Slam"},
  AvgDialog_35984_Content_10 = {Text = "BRAK!"},
  AvgDialog_35984_Content_11 = {
    Text = "Vas bunga melesat melewati wajah George dengan cepat."
  },
  AvgDialog_35984_Content_12 = {
    Text = "Setiap hari terkurung di museum lilin sampai hampir gila karena bosan, masa orang bahkan tidak punya kebebasan untuk bernyanyi?!"
  },
  AvgDialog_35984_Content_13 = {
    Text = "Seseorang silakan lanjut bernyanyi, George juga akan terus mengomeli, hihihi."
  },
  AvgDialog_35984_Content_14 = {
    Text = "Tuan Rogers, tolong kendalikan peliharaan kesayangan Anda, dia sudah benar-benar menjadi iblis!"
  },
  AvgDialog_35984_Content_15 = {
    Text = "Hmm…… Botticelli…… Primavera……"
  },
  AvgDialog_35984_Content_16 = {
    Text = "Model kali ini harus di-dicari dari mana ya……"
  },
  AvgDialog_35984_Content_18 = {
    Text = "Toh tidak ada kerjaan, bagaimana kalau kita main kartu saja!"
  },
  AvgDialog_35984_Content_19 = {
    Text = "Pandiya dengan cekatan mengeluarkan satu set kartu dari laci dan membantingnya ke meja."
  },
  AvgDialog_35984_Content_2 = {
    Text = "Mystic Realm Buatan: Museum Lilin Rogers"
  },
  AvgDialog_35984_Content_20 = {
    Text = "Bridge lagi, George tidak suka main bridge.\nLagipula, budak vampir tidak ada, kita masih kurang satu orang——"
  },
  AvgDialog_35984_Content_21 = {
    Text = "Pandia menunjuk ke sudut ruangan. Di samping lemari yang tidak diperhatikan siapa pun,\"24\" sedang membersihkan benda-benda pameran Di Dalam."
  },
  AvgDialog_35984_Content_22 = {
    Text = "Kalau dia dihitung, bukankah sudah cukup."
  },
  AvgDialog_35984_Content_23 = {
    Text = "Hmm…… sekarang aturannya sudah dipahami semua kan?"
  },
  AvgDialog_35984_Content_24 = {Text = "Paham."},
  AvgDialog_35984_Content_25 = {
    Text = "Kenapa orang ini masih pakai kacamata segala, rakyat miskin dari distrik timur mau pura-pura terpelajar ya, memalukan sekali!"
  },
  AvgDialog_35984_Content_26 = {
    Text = "Kamu benar-benar sudah paham? Ini cukup rumit lho——"
  },
  AvgDialog_35984_Content_27 = {
    Text = "52 kartu masing-masing 13 kartu saat bermain setiap menang satu ronde@21trik kontrak dengan 6 trik sebagai dasar@16trik ke atas baru bisa dihitung sebagai trik kemenangan……"
  },
  AvgDialog_35984_Content_28 = {
    Text = "Eh…… lumayan."
  },
  AvgDialog_35984_Content_29 = {
    Text = "Tiba-tiba aku merasa kamu sangat berpotensi, bagaimana kalau kita satu tim saja!"
  },
  AvgDialog_35984_Content_3 = {
    Text = "Ah! Pangeran berkuda putih yang turun dari langit~"
  },
  AvgDialog_35984_Content_30 = {
    Text = "Tuan Rogers. Jika saya menang, bisakah Anda mengabulkan satu permintaan saya?"
  },
  AvgDialog_35984_Content_31 = {
    Text = "Hihihi, seseorang lupa diri sendiri seberapa mampu, siap-siap menderita ya!"
  },
  AvgDialog_35984_Content_32 = {
    Text = "Ka-katakan, permintaan apa?"
  },
  AvgDialog_35984_Content_33 = {
    Text = "Bukankah kelompok patung lilin Anda masih membutuhkan seorang model? Saya bisa menjadi model Anda."
  },
  AvgDialog_35984_Content_34 = {
    Text = "Wah~ Miss 24, apakah Anda dengan sukarela bergegas menuju kematian?"
  },
  AvgDialog_35984_Content_35 = {
    Text = "\"24\" diam-diam menundukkan kepala, buku-buku jari yang menggenggam sapu tampak memutih samar."
  },
  AvgDialog_35984_Content_36 = {
    Text = "<Gray:《Musim Semi》 adalah karya yang direncanakan Rogers untuk dipamerkan di pameran. Selama bisa terpilih sebagai model, eksposurnya akan meningkat dan bisa dilihat oleh lebih banyak orang.>"
  },
  AvgDialog_35984_Content_37 = {
    Text = "<Gray:Jenkin……>"
  },
  AvgDialog_35984_Content_38 = {
    Text = "Tentu saja bisa. Miss 24, garis tulangmu halus dan tetap indah, sepenuhnya mampu memerankan karakter ini."
  },
  AvgDialog_35984_Content_39 = {
    Text = "Aku sangat, sangat senang kamu sukarela bergabung dalam seni agungku."
  },
  AvgDialog_35984_Content_4 = {
    Text = "Dia melangkah melewati pintu ini, membawa pergi hatiku——"
  },
  AvgDialog_35984_Content_40 = {
    Text = "Dua jam kemudian"
  },
  AvgDialog_35984_Content_41 = {Text = "Tsk……"},
  AvgDialog_35984_Content_42 = {Text = "Ah……"},
  AvgDialog_35984_Content_43 = {
    Text = "Wah, Grand Slam! 24, sungguh beruntung bisa satu tim denganmu, la la la~"
  },
  AvgDialog_35984_Content_44 = {
    Text = "Kalian berdua, cepat bayar!"
  },
  AvgDialog_35984_Content_45 = {
    Text = "Rogers dengan senyum lebar melemparkan beberapa keping perak."
  },
  AvgDialog_35984_Content_46 = {
    Text = "Tidak disangka di sini te-ternyata ada jagoan tersembunyi, benar-benar membuatku kagum."
  },
  AvgDialog_35984_Content_47 = {
    Text = "Mana mungkin…… orang ini tadi bahkan tidak mengerti aturannya!"
  },
  AvgDialog_35984_Content_48 = {
    Text = "George sudah diam-diam mengamati 24 selama sebulan, dan sudah memastikan bahwa dia adalah babi bodoh sejati, bagaimana mungkin dia bisa sepintar itu..."
  },
  AvgDialog_35984_Content_49 = {
    Text = "Sopan santun, George. Sopan santun. Orang yang tidak mau bayar utang tidak akan tumbuh tinggi lho~"
  },
  AvgDialog_35984_Content_5 = {Text = "Ha-"},
  AvgDialog_35984_Content_50 = {
    Text = "George marah sampai wajahnya merah padam."
  },
  AvgDialog_35984_Content_51 = {
    Text = "Curang, dia pasti curang!"
  },
  AvgDialog_35984_Content_52 = {
    Text = "Hanya beberapa soal matematika sederhana. Berdasarkan informasi yang sudah ada di meja, probabilitas distribusi 4 kartu trump sekop dapat dihitung masing-masing 0,023, 0,183, 0,412……"
  },
  AvgDialog_35984_Content_54 = {
    Text = "Wah, sama sekali ti-tidak mengerti."
  },
  AvgDialog_35984_Content_55 = {
    Text = "……0,314, 0,069. Jadi saat membersihkan trump, aku akan fokus mempertimbangkan situasi @1 dan @2, lalu menghitung berdasarkan urutan kartu yang kalian keluarkan……"
  },
  AvgDialog_35984_Content_56 = {
    Text = "Mendengarkan penjelasan rekap yang sangat rinci dari \"24\", George menunduk dan mulai menghitung dengan jari-jarinya yang gemuk."
  },
  AvgDialog_35984_Content_57 = {
    Text = "Tidak benar. Kenapa aku tidak bisa menghitungnya……"
  },
  AvgDialog_35984_Content_58 = {
    Text = "Alasan! Semua itu cuma alasan! Kau pikir dengan mengatakan hal-hal yang tidak kami mengerti kau bisa lolos dari hukuman?!"
  },
  AvgDialog_35984_Content_59 = {
    Text = "Sambil berkata demikian, George menerjang \"24\"."
  },
  AvgDialog_35984_Content_6 = {Text = "ti-"},
  AvgDialog_35984_Content_60 = {
    Text = "Biar kulihat, apa kau menyembunyikan sesuatu——"
  },
  AvgDialog_35984_Content_61 = {
    Text = "GRRRUMM——!!"
  },
  AvgDialog_35984_Content_62 = {
    Text = "Atap museum lilin tiba-tiba terbuka lubang besar, sesuatu yang berat menghantam George dengan keras, menghancurkannya menjadi gumpalan daging."
  },
  AvgDialog_35984_Content_63 = {Text = "Auww!!"},
  AvgDialog_35984_Content_64 = {
    Text = "Belum sempat mengucapkan satu kalimat utuh, George sudah tidak bersuara lagi."
  },
  AvgDialog_35984_Content_65 = {
    Text = "Uhuk uhuk……apa ini, pantatku lengket-lengket……"
  },
  AvgDialog_35984_Content_66 = {
    Text = "Eh, bukankah seharusnya aku sudah kembali? Kenapa malah di museum lilin?"
  },
  AvgDialog_35984_Content_67 = {
    Text = "%player%{Male=tuan,Female=nyonya}, Anda tidak apa-apa?"
  },
  AvgDialog_35984_Content_68 = {
    Text = "Nona Mason, kenapa kamu juga ada di sini?! Jangan-jangan aku belum keluar dari Secret Realm……"
  },
  AvgDialog_35984_Content_69 = {
    Text = "Aaaaah! Ja-jatuh dari langit……"
  },
  AvgDialog_35984_Content_7 = {Text = "<Big:ku!>"},
  AvgDialog_35984_Content_70 = {Text = "Ge-George?"},
  AvgDialog_35984_Content_71 = {
    Text = "Rogers menatap terkejut pada George yang sudah tak berbentuk di bawah pantatmu, matanya dipenuhi kemarahan dan kesedihan tanpa batas."
  },
  AvgDialog_35984_Content_72 = {
    Text = "Pandiya……ta-tangkap mereka!"
  },
  AvgDialog_35984_Content_8 = {
    Text = "Tsk tsk, seseorang yang sudah lama bersama budak vampir, juga belajar bernyanyi rupanya."
  },
  AvgDialog_35984_Content_9 = {
    Text = "Jelek, jelek sekali!"
  },
  AvgDialog_35985_Content_1 = {
    Text = "Uuh——!!"
  },
  AvgDialog_35985_Content_10 = {
    Text = "Tidak, patung-patung lilinku……"
  },
  AvgDialog_35985_Content_11 = {
    Text = "Belum sempat bereaksi, pergelangan tanganmu sudah digenggam erat."
  },
  AvgDialog_35985_Content_12 = {
    Text = "Cepat ikut aku pergi."
  },
  AvgDialog_35985_Content_13 = {
    Text = "Di malam yang sunyi, tiga orang bergandengan tangan berlari melewati persimpangan demi persimpangan."
  },
  AvgDialog_35985_Content_14 = {
    Text = "Hah... yang berkacamata itu, eh, Miss 24, kita masih harus berlari berapa lama lagi..."
  },
  AvgDialog_35985_Content_15 = {
    Text = "Di sini sudah cukup. Rogers tidak akan mau datang ke kuburan massal yang tak punya nilai estetika seperti ini."
  },
  AvgDialog_35985_Content_16 = {
    Text = "Kali ini berkat kalian semua."
  },
  AvgDialog_35985_Content_17 = {
    Text = "Anak kecil itu mengawasiku terus-menerus, di seluruh museum lilin ada mata-mata mereka di mana-mana. 23 rencana pelarian yang kususun semuanya gagal."
  },
  AvgDialog_35985_Content_18 = {
    Text = "Sebenarnya ini hanya kebetulan……Kami juga tidak mengerti bagaimana bisa sampai di sini."
  },
  AvgDialog_35985_Content_19 = {
    Text = "Eh, kalian tidak merasa terkejut? Berhadapan langsung dengan diri kalian yang lain."
  },
  AvgDialog_35985_Content_2 = {
    Text = "Lumayan hebat juga. Sepertinya <Red:anak-anak kecil> di bawah tanah juga sudah waktunya bangun dan bekerja……"
  },
  AvgDialog_35985_Content_20 = {
    Text = "\"24\" dan Mason menatapmu bersamaan, seolah kamu baru saja mengajukan pertanyaan yang sangat aneh."
  },
  AvgDialog_35985_Content_21 = {
    Text = "Aku tidak mengerti maksudmu… Memang ada banyak 24 di dunia ini, kita pasti akan selalu bertemu dengan mereka."
  },
  AvgDialog_35985_Content_22 = {
    Text = "<Gray:Mungkinkah ini aturan aneh di dalam dunia rahasia ini……>"
  },
  AvgDialog_35985_Content_23 = {
    Text = "Sudahlah, anggap saja aku tidak pernah bertanya."
  },
  AvgDialog_35985_Content_24 = {
    Text = "Aku harus segera pulang, Jenkin pasti sangat mengkhawatirkanku."
  },
  AvgDialog_35985_Content_25 = {
    Text = "Tunggu, Miss 24!!"
  },
  AvgDialog_35985_Content_26 = {
    Text = "\"24\" melangkah maju dengan mantap, dia masih memiliki hal yang lebih penting untuk dilakukan. Namun——"
  },
  AvgDialog_35985_Content_27 = {Text = "Tok tok."},
  AvgDialog_35985_Content_28 = {
    Text = "Organ-organ tubuhnya seolah ditarik oleh benang tak kasat mata, dengan cepat terlepas dari posisi semula."
  },
  AvgDialog_35985_Content_29 = {
    Text = "Uuh——!!"
  },
  AvgDialog_35985_Content_3 = {
    Text = "Anak-anak kecil di bawah……"
  },
  AvgDialog_35985_Content_30 = {
    Text = "Di dekat sini, ada sesuatu…… Siapa di sana?!"
  },
  AvgDialog_35985_Content_31 = {
    Text = "\"24\" menutup dadanya, membungkuk kesakitan."
  },
  AvgDialog_35985_Content_32 = {
    Text = "Detik berikutnya, tanah di bawah lututnya dengan cepat memutih, seluruh dunia berubah menjadi hamparan putih yang tak berujung."
  },
  AvgDialog_35985_Content_33 = {
    Text = "Saat membuka mata kembali, langit dan daratan yang tertutup salju melebur menjadi satu kekosongan yang misterius dan tak terduga, hanya deretan pegunungan yang menjulang di depan."
  },
  AvgDialog_35985_Content_34 = {
    Text = "Segalanya bermandikan cahaya matahari kutub berwarna biru pucat, dingin, tajam, tanpa duka maupun suka."
  },
  AvgDialog_35985_Content_35 = {
    Text = "Dia berlutut di kaki gunung bersalju."
  },
  AvgDialog_35985_Content_4 = {
    Text = "Yang dimaksud mungkin adalah patung-patung lilin yang terlihat di ruang bawah tanah museum lilin sebelumnya."
  },
  AvgDialog_35985_Content_5 = {
    Text = "Kalau memang mereka, ini pasti akan jadi pertarungan yang berat……"
  },
  AvgDialog_35985_Content_6 = {Text = "Klik."},
  AvgDialog_35985_Content_7 = {
    Text = "Di sudut yang tak diperhatikan siapa pun, seseorang menyalakan lilin dan membakar sisa tubuh George."
  },
  AvgDialog_35985_Content_8 = {
    Text = "Tak lama kemudian, museum lilin dilalap api yang berkobar hebat."
  },
  AvgDialog_35985_Content_9 = {
    Text = "Aduh, kenapa bisa kebakaran!"
  },
  AvgDialog_35987_Content_1 = {Text = "\"Sumber\""},
  AvgDialog_35987_Content_10 = {
    Text = "Eh? Kata Nona Winkel, Mystic Realm-ku sangat menakutkan, penuh dengan monster-monster ganas di mana-mana……"
  },
  AvgDialog_35987_Content_11 = {
    Text = [[
Itu hanya khayalannya saja.
Tapi aku memang melihat sesuatu yang sangat istimewa, misalnya "kamu".]]
  },
  AvgDialog_35987_Content_12 = {Text = "Aku……?"},
  AvgDialog_35987_Content_13 = {
    Text = "Kamu tertawa pelan, lalu mengedipkan mata padanya."
  },
  AvgDialog_35987_Content_14 = {
    Text = "Ini rahasia antara aku dan \"dia\", kalau ada kesempatan di masa depan, akan kuceritakan pelan-pelan padamu."
  },
  AvgDialog_35987_Content_15 = {
    Text = "Kakak——!!"
  },
  AvgDialog_35987_Content_16 = {
    Text = "Jenkins tiba-tiba melompat keluar dari semak bunga di dekat kalian."
  },
  AvgDialog_35987_Content_17 = {
    Text = "Aku dan Aigis sudah kembali dari jalan-jalan. Lihat apa yang kami temukan?"
  },
  AvgDialog_35987_Content_18 = {
    Text = [[
Jenkins mengayun-ayunkan sebuah pita merah di tangannya.
Berbeda dengan pita yang biasa dipakai Mason, di ujungnya tergantung sebuah lonceng kecil yang sudah menguning.]]
  },
  AvgDialog_35987_Content_19 = {
    Text = "Angin sepoi berhembus, lonceng itu mengeluarkan bunyi gemerincing yang jernih, bagaikan peri kecil yang riang."
  },
  AvgDialog_35987_Content_2 = {
    Text = [[
Universitas Misage, di dalam kampus
Tiga hari kemudian]]
  },
  AvgDialog_35987_Content_20 = {
    Text = "Ini yang pernah kulihat di Mystic Realm……"
  },
  AvgDialog_35987_Content_21 = {
    Text = "Eh, kamu juga pernah melihatnya di Mystic Realm? Kalau begitu, kamu pasti bertemu dengan kakak yang berubah jadi kucing, kan!"
  },
  AvgDialog_35987_Content_22 = {
    Text = "Ja-jangan bilang lagi……"
  },
  AvgDialog_35987_Content_23 = {
    Text = "Kenapa tidak boleh bilang? Pita ini adalah kenang-kenangan yang sangat, benar-benar, luar biasa penting!"
  },
  AvgDialog_35987_Content_24 = {
    Text = "Selama masa itu, setiap hari aku merawatmu, menemanimu bermain, senang sekali rasanya!"
  },
  AvgDialog_35987_Content_25 = {
    Text = "Jenkins dengan lembut meletakkan pita itu di tangan Mason."
  },
  AvgDialog_35987_Content_26 = {
    Text = "Aku masih ingat seseorang pernah bilang, di kehidupan selanjutnya ingin jadi seekor kucing."
  },
  AvgDialog_35987_Content_27 = {
    Text = "Kalau benar-benar bisa hidup tanpa beban seperti itu, pasti menyenangkan sekali. Aku juga bisa terus merawatmu!"
  },
  AvgDialog_35987_Content_28 = {
    Text = "Ikan kering kecil, rumput catnip, semuanya serahkan saja pada Tuan Besar ini!"
  },
  AvgDialog_35987_Content_29 = {
    Text = "Mason menunduk sambil tersenyum, jari-jarinya mengusap lembut pita yang dingin dan halus itu."
  },
  AvgDialog_35987_Content_3 = {
    Text = "Begitu rupanya. Tidak lama setelah membunuh Albino, kamu dibawa pergi oleh orang-orang dari Asosiasi Pematung."
  },
  AvgDialog_35987_Content_30 = {
    Text = "Jadi seekor kucing? Itu urusan kehidupan selanjutnya."
  },
  AvgDialog_35987_Content_31 = {
    Text = "Sekarang aku hanya ingin hidup sebagai \"Mason\", bersama semua orang dengan sebaik-baiknya."
  },
  AvgDialog_35987_Content_32 = {
    Text = "Eh…… Sepertinya Mystic Realm kali ini sangat mengubah Kakak ya, dulu dia tidak seperti ini."
  },
  AvgDialog_35987_Content_33 = {
    Text = "Aku jadi saksi, semua yang dikatakan Nona Mason itu benar."
  },
  AvgDialog_35987_Content_34 = {
    Text = "Kamu dan Mason saling bertukar senyum. Pikiranmu kembali ke saat itu, tepat sebelum Mystic Realm runtuh……"
  },
  AvgDialog_35987_Content_35 = {
    Text = "Begitu rupanya… Aku mengerti sekarang."
  },
  AvgDialog_35987_Content_36 = {
    Text = "Kamu adalah asal mula segalanya, dan juga akhir dari segalanya…"
  },
  AvgDialog_35987_Content_37 = {
    Text = "Seiring lenyapnya cahaya bintang terakhir, dunia seolah ditelan oleh tinta hitam."
  },
  AvgDialog_35987_Content_38 = {
    Text = "Kamu mendengar dentang lonceng dari kejauhan, bagaikan gemuruh kacau dari kedalaman mantel bumi."
  },
  AvgDialog_35987_Content_39 = {
    Text = "Ini…… Mystic Realm akan runtuh?!"
  },
  AvgDialog_35987_Content_4 = {
    Text = "Dari situlah cerita selanjutnya bermula."
  },
  AvgDialog_35987_Content_40 = {
    Text = "Pegang tanganku, %player%{Male=tuan,Female=nyonya}!"
  },
  AvgDialog_35987_Content_41 = {
    Text = "Kamu menggenggam erat tangan Mason."
  },
  AvgDialog_35987_Content_42 = {
    Text = "Pada saat itu, darahmu seolah mengalir ke tubuhnya tanpa hambatan, kesadaran kalian mulai menyatu menjadi satu."
  },
  AvgDialog_35987_Content_43 = {
    Text = "Kamu merasa dirimu perlahan tertidur, mimpi-mimpi tak terhitung berdatangan silih berganti, membawamu meluncur ke dalam kegelapan."
  },
  AvgDialog_35987_Content_44 = {
    Text = "Saat kau membuka mata lagi, kau berdiri sendirian di dalam gua. Di bawah kakimu mengalir sungai emas berkilauan, bagaikan pembuluh darah yang menembus bumi."
  },
  AvgDialog_35987_Content_45 = {
    Text = "Ini cahaya bintang yang pernah kulihat sebelumnya… Jadi semuanya berkumpul di sini?"
  },
  AvgDialog_35987_Content_46 = {
    Text = "<Red:Kembalilah, kembalilah……>"
  },
  AvgDialog_35987_Content_47 = {
    Text = "Kau mengikuti arah aliran cahaya bintang, melangkah menuju kedalaman gua."
  },
  AvgDialog_35987_Content_48 = {
    Text = "Ini… apa?!"
  },
  AvgDialog_35987_Content_49 = {
    Text = "Tempat ini bagaikan sumber utama dari segala sesuatu yang terdistorsi, cacat, dan najis."
  },
  AvgDialog_35987_Content_5 = {
    Text = "Ya. Sekarang aku sudah mengingat semuanya, itu bukan kenangan yang menyenangkan……"
  },
  AvgDialog_35987_Content_50 = {
    Text = "Gumpalan abu-abu pucat terus bergetar dan membengkak, membelah diri menjadi makhluk-makhluk cacat yang menggeliat, seperti lambung yang terus-menerus meronta."
  },
  AvgDialog_35987_Content_51 = {
    Text = "Namun sebelum sempat naik ke darat, mereka sudah jatuh kembali ke dalam kolam, ditelan oleh mulut besar yang terbuka di tubuh gumpalan itu."
  },
  AvgDialog_35987_Content_52 = {
    Text = "Siluet makhluk-makhluk ini tampak familiar… Jangan-jangan…"
  },
  AvgDialog_35987_Content_53 = {
    Text = "Tiba-tiba kau merasakan firasat yang sangat kuat. Kau melangkah menembus cairan abu-abu itu, mendekati gumpalan tersebut."
  },
  AvgDialog_35987_Content_54 = {
    Text = "Mason… apakah itu kau?"
  },
  AvgDialog_35987_Content_55 = {
    Text = "Gumpalan itu terdiam sesaat, lalu mulai menggeliat pelan kembali."
  },
  AvgDialog_35987_Content_56 = {
    Text = "Ia mengeluarkan suara gemerisik halus, seolah sapaan yang ramah."
  },
  AvgDialog_35987_Content_57 = {
    Text = "Kau memandang makhluk-makhluk yang merangkak berlutut di dalam kolam, bergerak susah payah, mengejang tanpa henti di dalam cairan lengket itu, hanya demi bisa kembali ke pelukan gumpalan tersebut."
  },
  AvgDialog_35987_Content_58 = {
    Text = "Seperti para peziarah yang menerjang badai salju demi mencari mukjizat."
  },
  AvgDialog_35987_Content_59 = {
    Text = "<Red:Akar dari segala yang tak murni, tak suci, tak bertuah…>"
  },
  AvgDialog_35987_Content_6 = {
    Text = "Kamu perlahan menggenggam tangan Mason."
  },
  AvgDialog_35987_Content_60 = {
    Text = "<Red:Kembalilah…>"
  },
  AvgDialog_35987_Content_62 = {
    Text = "Karena di sinilah ujung dari semua sungai, tak peduli seberapa jauh jaraknya, pada akhirnya semuanya akan berkumpul di sini."
  },
  AvgDialog_35987_Content_63 = {
    Text = "Jadi begitu… Kaulah tujuan akhir yang mereka rindukan untuk kembali. Jadi inilah yang kau lakukan setiap hari?"
  },
  AvgDialog_35987_Content_64 = {
    Text = "Dengan tubuh yang lemah, menarik kembali kepribadian-kepribadian yang tercerai-berai, dan berusaha sekuat tenaga mempertahankan penampilan sebagaimana layaknya \"orang normal\"."
  },
  AvgDialog_35987_Content_65 = {
    Text = "Seperti seorang ibu yang lelah menunggu kepulangan anak-anaknya, di bawah tarikan panjang antara perpecahan dan penyatuan, bahkan identitasnya sendiri sebagai seorang ibu pun telah terlupakan."
  },
  AvgDialog_35987_Content_66 = {
    Text = "……Pantas saja aku memimpikan hal-hal di masa lalu."
  },
  AvgDialog_35987_Content_67 = {
    Text = "Terakhir kali melihat cahaya bintang ini, aku tiba-tiba merasa diriku sangat mirip dengan mereka."
  },
  AvgDialog_35987_Content_68 = {
    Text = "……Tapi ada juga yang berbeda. Mereka tahu di mana kampung halaman mereka, sedangkan aku bahkan kehilangan ingatanku."
  },
  AvgDialog_35987_Content_69 = {
    Text = "Hidungmu tiba-tiba terasa perih, kamu perlahan mengusap gumpalan daging itu, merasakan denyut nadinya yang tenang."
  },
  AvgDialog_35987_Content_7 = {
    Text = "Semua sudah berlalu, Nona Mason. Aku berjanji padamu, hal-hal itu tidak akan pernah terjadi lagi."
  },
  AvgDialog_35987_Content_70 = {
    Text = "Mason…… Suatu hari nanti aku juga akan menemukan kampung halamanku, kan? Seperti yang kalian lakukan sekarang……"
  },
  AvgDialog_35987_Content_71 = {
    Text = "Gumpalan daging itu bergerak-gerak, membelah ujungnya menjadi tentakel lembut dan licin, perlahan menyeka air mata di sudut matamu."
  },
  AvgDialog_35987_Content_72 = {
    Text = "<Change>Pasti akan……"
  },
  AvgDialog_35987_Content_73 = {
    Text = "<Change>Jangan menangis……"
  },
  AvgDialog_35987_Content_74 = {
    Text = "Gemuruh……"
  },
  AvgDialog_35987_Content_75 = {
    Text = "Getaran samar terdengar dari kedalaman bumi, dinding batu terkoyak membentuk retakan-retakan."
  },
  AvgDialog_35987_Content_76 = {
    Text = "Waktu hingga runtuhnya Alam Rahasia: <Red:0> menit"
  },
  AvgDialog_35987_Content_77 = {
    Text = "Kamu berbalik dan meninggalkan gua."
  },
  AvgDialog_35987_Content_78 = {
    Text = "Saat sampai di mulut gua, kamu tak bisa menahan diri untuk menoleh dan melihatnya untuk terakhir kalinya."
  },
  AvgDialog_35987_Content_79 = {
    Text = "Sampai jumpa, Nona Mason."
  },
  AvgDialog_35987_Content_8 = {
    Text = "Terima kasih……%player%{Male=tuan,Female=nyonya}."
  },
  AvgDialog_35987_Content_80 = {
    Text = "Kebahagiaan, kesedihan, penderitaan…… Kepribadian dan emosi yang berbeda datang dan pergi, tapi dia selalu tetap tinggal di gua batu itu."
  },
  AvgDialog_35987_Content_81 = {
    Text = "——Dia hidup."
  },
  AvgDialog_35987_Content_9 = {
    Text = [[
Seharusnya akulah yang berterima kasih padamu.
Saat Mystic Realm runtuh, kamu memberiku banyak semangat dan penghiburan.]]
  },
  AvgDialog_35988_Content_1 = {
    Text = "Ular Insomnia"
  },
  AvgDialog_35988_Content_10 = {
    Text = "Dia mengangkat kedua tangannya tinggi-tinggi sambil gemetar, mendongak menatap langit-langit yang gelap gulita, mulutnya terus-menerus mengeluarkan igauan yang samar."
  },
  AvgDialog_35988_Content_11 = {
    Text = "Akar dari segala yang tidak murni, tidak suci, dan tidak bertuah……"
  },
  AvgDialog_35988_Content_12 = {
    Text = "Kembalilah…… <Big:Kembalilah!>"
  },
  AvgDialog_35988_Content_13 = {
    Text = "Ugh…… kepalaku sakit sekali……"
  },
  AvgDialog_35988_Content_14 = {
    Text = "Delirium menyebar keluar seperti riak gelombang. Mason dengan kesakitan menutup kepalanya dan juga berlutuh di belakang \"24\"."
  },
  AvgDialog_35988_Content_15 = {
    Text = "Berhenti…… <Big:Berhentilah>!"
  },
  AvgDialog_35988_Content_16 = {
    Text = "Dia menerjang dengan tiba-tiba, memeluk \"24\" yang wajahnya penuh darah dari belakang."
  },
  AvgDialog_35988_Content_17 = {
    Text = "Kumohon, berhentilah……"
  },
  AvgDialog_35988_Content_18 = {
    Text = "Mason berusaha keras mencengkeram kedua tangan \"24\" yang terangkat tinggi, darah dan air mata mereka bercampur satu sama lain. Namun semua itu sia-sia."
  },
  AvgDialog_35988_Content_19 = {
    Text = "<Red:Kembalilah, kembalilah……>"
  },
  AvgDialog_35988_Content_2 = {
    Text = "Wanita bertelanjang kaki merangkak maju."
  },
  AvgDialog_35988_Content_20 = {
    Text = "<Red:Nikmatilah bersama pesta yang najis dan kotor ini——Perjamuan!!>"
  },
  AvgDialog_35988_Content_21 = {
    Text = "Miss 24, jangan——!!"
  },
  AvgDialog_35988_Content_22 = {
    Text = "Lengan-lengan yang terdistorsi dan cacat tumbuh dari dalam tubuh \"24\". Mereka bermandikan darah dan cahaya bulan, lalu—"
  },
  AvgDialog_35988_Content_23 = {
    Text = "Dengan lembut namun Teguh mematahkan leher \"24\"."
  },
  AvgDialog_35988_Content_25 = {
    Text = "Tidak ada pemandangan berdarah seperti yang dibayangkan. Tubuh \"24\" berubah menjadi sedikit demi sedikit cahaya bintang keemasan, seolah-olah kunang-kunang yang bergerak di malam pekat."
  },
  AvgDialog_35988_Content_26 = {
    Text = "Eh…… ini……"
  },
  AvgDialog_35988_Content_27 = {
    Text = "Cahaya bintang itu dengan lembut mengelilingi Mason, ada yang meresap ke dalam tubuhnya, ada yang menari di ujung jarinya, lalu melayang pergi dengan ringan."
  },
  AvgDialog_35988_Content_28 = {
    Text = "……Aku pernah melihat cahaya bintang ini."
  },
  AvgDialog_35988_Content_29 = {
    Text = "Dalam mimpi, dalam kenyataan…… mereka datang untuk menjemput \"kami\"."
  },
  AvgDialog_35988_Content_3 = {
    Text = "Rambut panjangnya terseret di tanah, terjerat rumput kering, salju, dan gumpalan darah yang membeku, sudah lama kehilangan kilau masa lalunya."
  },
  AvgDialog_35988_Content_30 = {
    Text = "Kamu mengulurkan tangan menyentuh cahaya bintang itu. Ujung jarimu merasakan kehangatan, seolah ada ikatan tersembunyi yang mengalir di antara kamu dan mereka."
  },
  AvgDialog_35988_Content_31 = {
    Text = "<Gray:Aneh, tiba-tiba hatiku merasa sedikit sedih……>"
  },
  AvgDialog_35988_Content_32 = {
    Text = "GRRRUMM——!!"
  },
  AvgDialog_35988_Content_33 = {
    Text = "Setelah cahaya bintang terakhir menghilang, kau merasakan getaran murka yang familiar dari kedalaman bumi."
  },
  AvgDialog_35988_Content_34 = {
    Text = "Gawat, jangan-janganDomain akan runtuh lagi?"
  },
  AvgDialog_35988_Content_35 = {
    Text = "Pegang tanganku, Nona Mason!"
  },
  AvgDialog_35988_Content_36 = {
    Text = "<Yellow:Catatan Investigasi Domain Buatan II>\n\n■Nomor Domain: M-C06\n■Waktu Jatuh: 17 Desember Tahun 315 Aluvi\n■Lokasi Jatuh: Jalan Southwark@2"
  },
  AvgDialog_35988_Content_37 = {
    Text = "<Yellow:■Hasil Investigasi>\n\nBayangan yang memburu \"24\" lainnya/kecenderungan bunuh diri yang tidak jelas/agama@2?\nApa hubungan di antara mereka?\n\n……Butuh lebih banyak petunjuk."
  },
  AvgDialog_35988_Content_38 = {
    Text = "Sementara itu, di luar Domain buatan…"
  },
  AvgDialog_35988_Content_39 = {
    Text = "Di pintu masuk Domain, para peneliti berjas putih terus sibuk keluar masuk."
  },
  AvgDialog_35988_Content_4 = {
    Text = "Di dekatnya, terkubur di dalam salju dan tergantung di pohon, terdapat mayat-mayat \"24\" yang telah mengering."
  },
  AvgDialog_35988_Content_40 = {
    Text = "Sudah lewat satu hari, %player% belum juga sadar. Haruskah kita mengajukan pemutusan paksa Domain?"
  },
  AvgDialog_35988_Content_41 = {
    Text = "Semua data tanda vital %hisorher% sangat stabil, tampaknya tidak mengalami perubahan drastis yang berbahaya."
  },
  AvgDialog_35988_Content_42 = {
    Text = "Observasi lagi beberapa waktu."
  },
  AvgDialog_35988_Content_43 = {
    Text = "Kalau terus ditunda, bagaimana nasib Miss 24? Komite Peninjauan sudah lama ingin memanfaatkan kasus ini sebagai dalih, agar mereka bisa ikut campur dalam urusan pengelolaan Awakener..."
  },
  AvgDialog_35988_Content_44 = {
    Text = "Winkel memeluk kepalanya dengan putus asa."
  },
  AvgDialog_35988_Content_45 = {
    Text = "<Shake:Ini semua salahku karena terlalu ingin meneliti Domain-nya, sekarang Penjaga Rahasia kita malah jadi Putri Tidur, bagaimana ini……>"
  },
  AvgDialog_35988_Content_46 = {
    Text = "Jangan khawatir, kami sudah punya rencana cadangan untuk ini. William sedang dalam perjalanan menuju Distrik Timur untuk investigasi."
  },
  AvgDialog_35988_Content_47 = {
    Text = "Adapun %player%……beri {Male=dia,Female=dia} sedikit waktu lagi."
  },
  AvgDialog_35988_Content_48 = {
    Text = [[
Klinik Bernard
Distrik Timur Londinium]]
  },
  AvgDialog_35988_Content_49 = {
    Text = "Berdasarkan Pasal 3 Bab 2 Ayat 13 \"Perjanjian Mysteria\", jika Awakened melanggar hukum sekuler, Dewan Peninjauan harus melakukan investigasi terlebih dahulu."
  },
  AvgDialog_35988_Content_5 = {
    Text = "Apa yang mereka cari dengan mendaki ke tempat setinggi ini, tak ada yang pernah memberikan penjelasan."
  },
  AvgDialog_35988_Content_50 = {
    Text = "Pasal 3 Bab 3 Ayat 2, jika perilaku tersangka bersifat menghindar atau melarikan diri, Dewan Peninjauan berhak segera membawanya kembali."
  },
  AvgDialog_35988_Content_51 = {
    Text = "Pasal 4 Bab 1, jika organisasi atau individu mana pun melindungi Awakened…"
  },
  AvgDialog_35988_Content_53 = {
    Text = "Tuan William, apakah kau mendengarkan perkataanku?"
  },
  AvgDialog_35988_Content_54 = {
    Text = "<Small:……Aku mendengarkan.>"
  },
  AvgDialog_35988_Content_56 = {
    Text = "Jangan buang-buang tenaga, mayat dan barang bukti sudah lama dibersihkan. Kau tidak akan menemukan apa pun di sini."
  },
  AvgDialog_35988_Content_57 = {
    Text = "Oh ya? Kalau begitu, ini apa?"
  },
  AvgDialog_35988_Content_58 = {
    Text = "William dengan hati-hati menggunakan pinset untuk mengambil segumpal zat kering semi-transparan."
  },
  AvgDialog_35988_Content_59 = {
    Text = "Kelihatannya seperti semacam kulit ular yang berganti. Tapi apa hubungannya dengan kasus ini?"
  },
  AvgDialog_35988_Content_6 = {
    Text = "Dia hanya tahu @2 sedang menunggunya, di ujung tempat es, salju, dan cahaya langit melebur."
  },
  AvgDialog_35988_Content_60 = {
    Text = "Ini sudah bulan Desember, bagaimana mungkin ada kulit ular yang berganti?"
  },
  AvgDialog_35988_Content_61 = {Text = "BRAK!"},
  AvgDialog_35988_Content_62 = {
    Text = "Tiba-tiba terdengar suara peralatan terjatuh dari ruang dalam klinik."
  },
  AvgDialog_35988_Content_63 = {
    Text = "Suara apa itu?! Bukankah tempat ini sudah lama disegel……"
  },
  AvgDialog_35988_Content_64 = {Text = "Keluar."},
  AvgDialog_35988_Content_65 = {
    Text = "Langkah kaki yang tidak terburu-buru terdengar mendekat dari kejauhan, seorang pria yang sangat pucat berjalan keluar dari ruang dalam."
  },
  AvgDialog_35988_Content_66 = {
    Text = "Selamat malam, Tuan Petugas."
  },
  AvgDialog_35988_Content_67 = {
    Text = "Saya adalah rekan kerja Dokter Bernard, diperintahkan oleh atasan untuk mengambil data penelitian beliau semasa hidup……"
  },
  AvgDialog_35988_Content_68 = {
    Text = "Mata pria itu setengah terbuka, tampak agak mengantuk. Dia tersenyum ramah sambil menyodorkan sebuah kartu nama."
  },
  AvgDialog_35988_Content_69 = {
    Text = "Dokter terdaftar di Royal Medical Society, Pierce·@2……"
  },
  AvgDialog_35988_Content_7 = {
    Text = "<Red:Tidak murni. Tidak suci. Tidak bertuah.>"
  },
  AvgDialog_35988_Content_70 = {
    Text = "Maaf, kami sudah lama menyelidiki lingkaran sosial Dokter Bernard. Kalau tidak salah ingat, Pierce ini adalah seorang pria tua berusia 50-an tahun."
  },
  AvgDialog_35988_Content_71 = {
    Text = "Katakan, sebenarnya siapa kau?"
  },
  AvgDialog_35988_Content_72 = {
    Text = "Hehe…… Memang pantas disebut Tuan dari Dewan Pemeriksa, kemampuan mengingat yang luar biasa sungguh mengagumkan."
  },
  AvgDialog_35988_Content_73 = {
    Text = "Dia tiba-tiba membuka lebar kedua matanya, pupil vertikal berwarna kuning kobalt berkilau dingin dalam kegelapan."
  },
  AvgDialog_35988_Content_74 = {
    Text = "Kalau begitu, aku temani kalian bermain sebentar."
  },
  AvgDialog_35988_Content_75 = {Text = "Sss……"},
  AvgDialog_35988_Content_76 = {
    Text = "Sensasi dingin dan licin terasa di wajah."
  },
  AvgDialog_35988_Content_77 = {
    Text = "Entah sejak kapan langit-langit dipenuhi ular-ular kecil pucat, mereka bergerak merayap dengan cepat tanpa suara, berjatuhan bagaikan tetesan hujan."
  },
  AvgDialog_35988_Content_78 = {
    Text = "Ular…… di mana-mana ada ular!"
  },
  AvgDialog_35988_Content_79 = {
    Text = "Langit-langit, lantai, dinding…… entah sejak kapan sekeliling dipenuhi ular, bagaikan rumput air pucat tak terhitung yang melayang-layang di sungai hitam yang sunyi."
  },
  AvgDialog_35988_Content_8 = {
    Text = "Akar dari segala yang tidak murni, tidak suci, dan tidak bertuah……"
  },
  AvgDialog_35988_Content_80 = {
    Text = "Memanggil regu A-2, B-1, ada bahaya di dalam, segera ambil posisi."
  },
  AvgDialog_35988_Content_81 = {
    Text = "William segera mengeluarkan kunci perak, namun pria di hadapannya sudah lenyap entah ke mana."
  },
  AvgDialog_35988_Content_82 = {
    Text = "Aku tahu kau masih di sini. Keluarlah."
  },
  AvgDialog_35988_Content_83 = {
    Text = "Udara kental di sekeliling bergetar sesaat, lalu kembali mengembang dengan riang."
  },
  AvgDialog_35988_Content_84 = {
    Text = "Terdengar suara \"desisan\" samar di telinga, bagaikan aliran udara dingin yang lembut membelai pipi."
  },
  AvgDialog_35988_Content_85 = {
    Text = "Hanya sedikit hadiah perkenalan, tolong Tuan Investigator merawat mereka dengan baik untukku."
  },
  AvgDialog_35988_Content_86 = {
    Text = "Selamat malam."
  },
  AvgDialog_35988_Content_9 = {
    Text = "\"24\" tiba-tiba jatuh berlutut di tanah."
  },
  AvgDialog_35989_Content_1 = {
    Text = "Menunggu Komedi"
  },
  AvgDialog_35989_Content_10 = {
    Text = "Aku juga melihatnya! Kalian bergandengan tangan, rambut berkibar-kibar, cantik seperti boneka!"
  },
  AvgDialog_35989_Content_11 = {
    Text = "Sst! Berisik sekali, jangan ganggu orang lain menonton pertunjukan!"
  },
  AvgDialog_35989_Content_12 = {
    Text = "Di atas panggung yang didirikan sementara, seorang badut dengan riasan tebal di wajahnya sedang tampil menghibur semua orang."
  },
  AvgDialog_35989_Content_13 = {
    Text = "Konon pada zaman dahulu kala, di pegunungan bersalju di ujung utara, di penghujung sungai kuno, tertidur seekor monster berwarna abu-abu~~~"
  },
  AvgDialog_35989_Content_14 = {
    Text = "Halo semuanya, aku adalah monster itu. <BigShake:Rawr——>"
  },
  AvgDialog_35989_Content_15 = {
    Text = "<Shake:Waaaa——>Eh, bukankah itu Jenkin?"
  },
  AvgDialog_35989_Content_16 = {
    Text = "Tak seorang pun tahu asal-usul dan nama monster itu, kecuali selera makannya yang besar — setiap musim dingin, penduduk yang tinggal di kaki gunung bersalju akan mengisi keranjang dengan makanan lezat dan minuman…"
  },
  AvgDialog_35989_Content_17 = {
    Text = "Nyalakan sebatang lilin perak, lalu letakkan keranjang itu di sungai terdekat dari rumah, dengan begitu monster bisa menerima persembahan dari warga."
  },
  AvgDialog_35989_Content_18 = {
    Text = [[
A-aku punya pertanyaan!
Bukannya monster itu tinggal di gunung bersalju, bagaimana bisa menerima persembahan dari sungai?]]
  },
  AvgDialog_35989_Content_19 = {
    Text = "Karena ujung semua sungai berada di kaki gunung bersalju, tak peduli seberapa jauh jaraknya, semuanya pada akhirnya akan berkumpul di sana."
  },
  AvgDialog_35989_Content_2 = {
    Text = "Mystic Realm Buatan: Panti Asuhan Lillian, Distrik Timur"
  },
  AvgDialog_35989_Content_20 = {
    Text = "Oh… lalu?"
  },
  AvgDialog_35989_Content_21 = {
    Text = "Nyam nyam nyam, aku sudah terima persembahan dari kalian semua! Aku sangat senang, dan memutuskan untuk membalas kebaikan kalian!"
  },
  AvgDialog_35989_Content_22 = {
    Text = "Setelah berkata demikian, Jenkin menundukkan kepalanya dan menggoyang-goyangkan rambutnya dengan keras seperti mesin."
  },
  AvgDialog_35989_Content_23 = {
    Text = "Berhenti goyang-goyang, kutunya berjatuhan semua… Eh, turun salju?"
  },
  AvgDialog_35989_Content_24 = {
    Text = "Wah, benar-benar turun salju!"
  },
  AvgDialog_35989_Content_25 = {
    Text = "Kepingan salju dari potongan kertas perak berjatuhan berterbangan. Aegis bersembunyi di belakang kalian, diam-diam menaburkan potongan kertas kecil."
  },
  AvgDialog_35989_Content_26 = {
    Text = "<Small:Sst… Tuan, tolong pura-pura tidak melihat Aegis…>"
  },
  AvgDialog_35989_Content_27 = {
    Text = "Tak lama kemudian, lilin-lilin beraneka warna menyala perlahan, wajah mungil anak-anak diselimuti cahaya oranye yang hangat dan lembut."
  },
  AvgDialog_35989_Content_28 = {
    Text = "Kemudian, setiap kali salju pertama turun setiap tahunnya, lilin-lilin perak akan mengapung di sungai, bersama keranjang-keranjang penuh hadiah."
  },
  AvgDialog_35989_Content_29 = {
    Text = "Criiiit——"
  },
  AvgDialog_35989_Content_3 = {
    Text = "<Shake:Uhuk uhuk, pinggangku……>"
  },
  AvgDialog_35989_Content_30 = {
    Text = "Keranjang penuh hadiah sudah datang!!"
  },
  AvgDialog_35989_Content_31 = {
    Text = "Sarah mendorong kereta makanan kecil keluar dengan senyum ceria."
  },
  AvgDialog_35989_Content_32 = {
    Text = "Waaah!! Puding plum, salad salmon, dan... dan babi panggang!!"
  },
  AvgDialog_35989_Content_33 = {
    Text = "Tunggu dulu. Sebelum makan, kita harus bilang apa dulu?"
  },
  AvgDialog_35989_Content_34 = {
    Text = "Anak-anak saling berpandangan dan tersenyum, lalu menjawab serempak—"
  },
  AvgDialog_35989_Content_35 = {
    Text = "<BigShake:Selamat Festival Embun Perak—!!>"
  },
  AvgDialog_35989_Content_36 = {
    Text = "Ternyata ada legenda seperti itu di balik Festival Embun Perak, ini pertama kalinya aku mendengarnya."
  },
  AvgDialog_35989_Content_37 = {
    Text = "<Gray:Mystic Realm milik Nona Mason seperti mimpi, bisa berpindah-pindah sesuka hati ke berbagai pemandangan, dan tak ada yang mempertanyakan kehadiranku.>"
  },
  AvgDialog_35989_Content_38 = {
    Text = "<Gray:Semua pemandangan dan karakter bisa dikombinasikan sesuka hati, pemandangan seperti ini mungkin tak pernah ada di dunia nyata...>"
  },
  AvgDialog_35989_Content_39 = {
    Text = "<Gray:Mungkin ini juga merupakan keinginan terdalam Nona Mason?>"
  },
  AvgDialog_35989_Content_4 = {
    Text = "Maaf sekali, %player%{Male=tuan,Female=nyonya}! Sepertinya aku agak gemukan akhir-akhir ini……"
  },
  AvgDialog_35989_Content_40 = {
    Text = "Nona Mason, kamu tidak mau bergabung dengan mereka?"
  },
  AvgDialog_35989_Content_41 = {
    Text = "Kamu menunjuk ke arah yang tidak jauh. Anak-anak masih berkumpul di sekitar badut, mendengarkan kisah-kisah megah dan menakjubkan darinya."
  },
  AvgDialog_35989_Content_42 = {
    Text = "Aku orang yang membosankan, lelucon yang kuceritakan hanya akan membuat orang mengantuk."
  },
  AvgDialog_35989_Content_43 = {Text = "Huhuhu..."},
  AvgDialog_35989_Content_44 = {
    Text = "Kak Mason, Jenkins dia, dia menggangguku...!"
  },
  AvgDialog_35989_Content_45 = {
    Text = "Hmph, kalah terus mengadu, memalukan! Siapa suruh tadi bilang aku kutuan!"
  },
  AvgDialog_35989_Content_46 = {
    Text = "Sst— Mac adalah ksatria kecil yang pemberani, ksatria kecil tidak boleh menangis, ya."
  },
  AvgDialog_35989_Content_47 = {
    Text = "Mason dengan lembut menyeka air mata dan ingus Mac kecil, sambil pelan-pelan menenangkan anak laki-laki yang masih terisak."
  },
  AvgDialog_35989_Content_48 = {
    Text = "Kak Mason, mata beruang Bobby hilang..."
  },
  AvgDialog_35989_Content_49 = {
    Text = "Agnes menggenggam bonekanya dan juga menghampiri."
  },
  AvgDialog_35989_Content_5 = {
    Text = "<Shake:Hanya agak saja? Nona Mason, tolong tu-turun dulu dari badanku……>"
  },
  AvgDialog_35989_Content_50 = {
    Text = "Coba sini lihat… Aduh, sepertinya memang hilang. Nanti malam kakak jahitkan yang baru ya?"
  },
  AvgDialog_35989_Content_51 = {Text = "Iya~!"},
  AvgDialog_35989_Content_53 = {
    Text = "Huh, selalu saja begini, bisanya cuma merepotkan kakakku!"
  },
  AvgDialog_35989_Content_54 = {
    Text = "Tapi Nona Mason juga terlihat senang, aku jarang sekali melihatnya seperti itu."
  },
  AvgDialog_35989_Content_55 = {
    Text = "Sarah duduk di sampingmu, menopang dagu dengan kedua tangan, tersenyum memandangi Mason yang dikerumuni anak-anak."
  },
  AvgDialog_35989_Content_56 = {
    Text = "Dibutuhkan orang lain juga merupakan sebuah kebahagiaan lho."
  },
  AvgDialog_35989_Content_58 = {
    Text = "Perlahan, anak-anak yang mengerumuni Mason semakin banyak, sementara sang badut justru menjadi pihak yang terabaikan."
  },
  AvgDialog_35989_Content_59 = {
    Text = "Ma-masih ada yang mau dengar cerita? Pada zaman dahulu kala…"
  },
  AvgDialog_35989_Content_6 = {
    Text = "Eh, ini sudah masuk ke Mystic Realm baru?"
  },
  AvgDialog_35989_Content_60 = {
    Text = "Dahulu kala…"
  },
  AvgDialog_35989_Content_61 = {
    Text = "Malam semakin larut, anak-anak satu per satu kembali ke kamar mereka, dan panti asuhan kembali ke kesunyian seperti biasa."
  },
  AvgDialog_35989_Content_62 = {
    Text = "Pertunjukan usai, kerumunan bubar—\nHei!"
  },
  AvgDialog_35989_Content_63 = {
    Text = "Hanya tersisa sang badut yang sendirian membereskan sisa-sisa pertunjukan, ditemani bayangan kesepian miliknya."
  },
  AvgDialog_35989_Content_64 = {
    Text = "Sang badut berceloteh sambil menggeleng-gelengkan kepala, menatap ke arah bayangan di sudut ruangan."
  },
  AvgDialog_35989_Content_65 = {
    Text = "Sungguh menyedihkan, bukankah begitu, Tuan Penonton?"
  },
  AvgDialog_35989_Content_67 = {
    Text = "Oh, aku sudah lama mendengar tentangmu:\"24\" pembunuh yang terkenal, datang dan pergi tanpa jejak, bersenang-senang dengan memburu kepribadian."
  },
  AvgDialog_35989_Content_68 = {
    Text = "Persona yang menjadi targetmu, tak akan bertahan lebih dari tiga hari— <BigShake:Uwaa!>"
  },
  AvgDialog_35989_Content_69 = {
    Text = "Sungguh mengerikan! Tapi sang badut di hadapanmu tidak takut dan tidak menghindar, mengapa begitu?"
  },
  AvgDialog_35989_Content_7 = {
    Text = "Apakah kalian malaikat?"
  },
  AvgDialog_35989_Content_70 = {
    Text = "Huh, sok misterius."
  },
  AvgDialog_35989_Content_71 = {
    Text = "Sang badut tertawa terbahak-bahak, sekilas cahaya berkilat di matanya."
  },
  AvgDialog_35989_Content_72 = {
    Text = "Karena sang pembunuh tidak tahu, bahwa persona-persona rendahan dan tidak stabil itu bahkan tak bisa bertahan sehari pun."
  },
  AvgDialog_35989_Content_73 = {
    Text = "Mereka lahir dari tak terhitung momen kebetulan, dan setelah menyelesaikan misi yang telah ditentukan, mereka akan lenyap selamanya."
  },
  AvgDialog_35989_Content_74 = {
    Text = "Apa misi \"Badut24\"? Tentu saja pada hari Festival Embun Perak ini, membawa kebahagiaan kepada Jenkin, kepada semua orang."
  },
  AvgDialog_35989_Content_75 = {
    Text = "Sang badut mengembangkan senyum lebar, riasan di wajahnya berubah menjadi butiran cahaya bintang keemasan."
  },
  AvgDialog_35989_Content_76 = {
    Text = "Sekarang aku sudah menyelesaikan misi melebihi target, sudah waktunya kembali~"
  },
  AvgDialog_35989_Content_77 = {
    Text = "Kembali ke mana?"
  },
  AvgDialog_35989_Content_78 = {
    Text = "Tentu saja kembali ke tempat <Yellow:kami pertama kali dilahirkan>."
  },
  AvgDialog_35989_Content_79 = {
    Text = "Akan kuberitahu sebuah rahasia: setiap kepribadian adalah rumput liar yang mengembara di dunia, kembali menjadi utuh adalah harapan bersama kami."
  },
  AvgDialog_35989_Content_8 = {
    Text = "Gadis itu mengerjap-ngerjapkan mata besarnya menatap kalian, menunjuk lubang besar di langit-langit yang kalian tembus."
  },
  AvgDialog_35989_Content_80 = {
    Text = "Tertawa bersama, menangis bersama, merasakan cinta dan kepercayaan dari Jenkin bersama…"
  },
  AvgDialog_35989_Content_81 = {
    Text = "Heh, kau masih punya muka menyebut nama Jenkin. Tahu apa misiku?"
  },
  AvgDialog_35989_Content_82 = {
    Text = "<Red:Membunuh semua orang yang berusaha mendapat sesuatu tanpa usaha. Tak satu pun tersisa.>"
  },
  AvgDialog_35989_Content_84 = {
    Text = "Di langit malam yang gelap gulita, kawanan gagak berterbangan, mengepakkan sayap meninggalkan pucuk-pucuk pohon."
  },
  AvgDialog_35989_Content_85 = {
    Text = "Ini adalah malam musim dingin yang tenang."
  },
  AvgDialog_35989_Content_9 = {
    Text = "Agnes melihat semuanya, kalian terbang turun dari langit."
  },
  AvgDialog_35990_Content_1 = {
    Text = "Fuga Keemasan"
  },
  AvgDialog_35990_Content_10 = {
    Text = "Kalian sudah terpisah terlalu lama."
  },
  AvgDialog_35990_Content_12 = {
    Text = "Sepertinya ini pertama kalinya aku memimpikan hal-hal dari masa lalu."
  },
  AvgDialog_35990_Content_13 = {
    Text = "Kamu memegangi kepalamu, kesadaranmu seolah ditarik oleh benang tak kasat mata, membawamu bangkit dari tempat tidur."
  },
  AvgDialog_35990_Content_14 = {
    Text = "Lalu kamu membuka jendela, dan melihat salju pertama di tahun baru."
  },
  AvgDialog_35990_Content_15 = {
    Text = "Wah, turun salju!!"
  },
  AvgDialog_35990_Content_16 = {
    Text = "Teriakan gembira anak-anak bergema di langit malam yang sunyi, diiringi derap langkah kaki yang riuh, anak-anak panti asuhan berkumpul bersama di lantai bawah."
  },
  AvgDialog_35990_Content_17 = {
    Text = "Saljunya banyak sekali, berkilauan, cantik sekali."
  },
  AvgDialog_35990_Content_18 = {
    Text = "Aigis ingin membuat boneka salju, yang seperti Beruang Bobby."
  },
  AvgDialog_35990_Content_19 = {
    Text = "Apa susahnya, biar aku yang——"
  },
  AvgDialog_35990_Content_2 = {
    Text = "Kau bermimpi yang sangat, sangat panjang."
  },
  AvgDialog_35990_Content_20 = {
    Text = "Tadaa! Lihatlah mahakarya Tuan Besar ini!"
  },
  AvgDialog_35990_Content_21 = {
    Text = "Umm…… sepertinya dia tidak terlalu mirip Beruang Bobby. Dia, dia……"
  },
  AvgDialog_35990_Content_22 = {
    Text = "Dia mirip anjing! Anjing pug!"
  },
  AvgDialog_35990_Content_23 = {
    Text = "<Big:Wahahahaha!>"
  },
  AvgDialog_35990_Content_24 = {
    Text = "O-omong kosong! Mana mirip anjing!"
  },
  AvgDialog_35990_Content_25 = {Text = "Cit cit!"},
  AvgDialog_35990_Content_26 = {
    Text = "Anak-anak berlarian sambil tertawa melewati lorong-lorong. Mason entah sejak kapan sudah terbangun, berdiri di sampingmu."
  },
  AvgDialog_35990_Content_27 = {
    Text = "Dia mengulurkan tangannya, menampung beberapa butir salju lembut di telapak tangannya."
  },
  AvgDialog_35990_Content_28 = {
    Text = "Butiran salju berbaring tenang di telapak tangannya, segera mencair menjadi air salju yang dingin, berkilauan dengan cahaya bintang keemasan."
  },
  AvgDialog_35990_Content_29 = {
    Text = "Eh, ini cahaya yang pernah kulihat waktu itu……"
  },
  AvgDialog_35990_Content_30 = {
    Text = "Cahaya bintang yang tak terhitung berterbangan keluar dari jendela lorong di sebelah kalian, bertemu di langit malam membentuk sungai cahaya keemasan."
  },
  AvgDialog_35990_Content_31 = {
    Text = "Mereka mengalir dengan ringan, membentang hingga ke bulan dan pegunungan yang jauh."
  },
  AvgDialog_35990_Content_32 = {
    Text = "Ini aura Nona Badut itu. Dia telah meninggalkan kita."
  },
  AvgDialog_35990_Content_33 = {
    Text = "Tapi aku tidak merasakan kesedihan… Dia sepertinya pergi dengan sukarela, seperti pulang ke rumah."
  },
  AvgDialog_35990_Content_34 = {
    Text = "Pulang ke rumah…"
  },
  AvgDialog_35990_Content_35 = {
    Text = "Aku juga mendengarnya… keinginan mereka untuk pulang ke rumah."
  },
  AvgDialog_35990_Content_36 = {
    Text = "Keinginan itu begitu kuat, sampai membuatku bermimpi tentang beberapa hal di masa lalu."
  },
  AvgDialog_35990_Content_37 = {
    Text = "Sekarang aku sudah tidak berani berharap untuk pulang ke rumah, bisa mendapatkan kembali sedikit kenangan masa lalu saja sudah cukup bagiku."
  },
  AvgDialog_35990_Content_38 = {
    Text = "Kamu menghela napas pelan, dengan sedikit canggung mengacak-acak rambutmu sendiri."
  },
  AvgDialog_35990_Content_39 = {
    Text = "Sudahlah, jangan bicara hal-hal yang menyedihkan. Ceritakan tentang dirimu, Nona Mason."
  },
  AvgDialog_35990_Content_4 = {
    Text = "Dalam mimpi, langit seperti pemakaman yang sudut-sudutnya telah dirobek, dan zat-zat hitam itu mengalir masuk bagai tinta."
  },
  AvgDialog_35990_Content_40 = {
    Text = "Kudengar kamu sudah mencari nafkah di Londinium sejak kecil, apakah sekarang masih rindu rumah?"
  },
  AvgDialog_35990_Content_41 = {
    Text = "Mason memandang Jenkin yang sedang bergulat dengan si kecil Mac di lantai bawah, lalu tersenyum lembut."
  },
  AvgDialog_35990_Content_42 = {
    Text = "Ingatanku sangat buruk. Waktu kecil, suster di sekolah gereja bilang aku memang bukan bahan untuk belajar."
  },
  AvgDialog_35990_Content_43 = {
    Text = "Orang tua, kampung halaman… aku sudah tidak begitu ingat, dan juga tidak ingin mengingatnya.\nKenangan itu untuk menyimpan kebahagiaan."
  },
  AvgDialog_35990_Content_44 = {
    Text = [[
Di buku dongeng yang pernah kubaca, hanya tempat yang penuh kebahagiaan dan kehangatan yang bisa disebut rumah.
Aku ingin menjadi rumah bagi Jenkin dan Brown.]]
  },
  AvgDialog_35990_Content_45 = {
    Text = [[
Begitu rupanya.
Nona Mason, kamu jauh lebih kuat dari yang kubayangkan.]]
  },
  AvgDialog_35990_Content_46 = {
    Text = "Saat pertama kali bertemu di museum lilin, kamu tidak seperti ini."
  },
  AvgDialog_35990_Content_47 = {
    Text = "<Gray:Sepertinya \"Terapi Stabilisasi Endorfin Dosis Super\" dari Nona Winkel ada manfaatnya juga ya.>"
  },
  AvgDialog_35990_Content_48 = {
    Text = "Semua orang berusaha sekuat tenaga membantuku, mana mungkin aku tidak berubah sama sekali?"
  },
  AvgDialog_35990_Content_49 = {
    Text = "Aku juga berharap bisa membantu semua orang."
  },
  AvgDialog_35990_Content_5 = {
    Text = "Kau terbaring telentang di bawah celah itu, mendekatkan jantungmu ke bumi sedekat dan sedalam mungkin."
  },
  AvgDialog_35990_Content_50 = {
    Text = "Kamu meregangkan badan, memandang tanpa tujuan ke kawasan pemukiman yang tenang dan damai di bawah."
  },
  AvgDialog_35990_Content_51 = {
    Text = "Entah itu hanya perasaanmu atau bukan, kamu sepertinya melihat sebuah bayangan berdiri di ujung gang yang gelap, ikut memandang sungai cahaya di langit bersama kalian."
  },
  AvgDialog_35990_Content_53 = {
    Text = "Itu cahaya bintang dari waktu itu…"
  },
  AvgDialog_35990_Content_54 = {
    Text = "Akan kuberitahu sebuah rahasia: setiap kepribadian adalah rumput apung yang mengembara di dunia, kembali menjadi utuh adalah harapan bersama kita."
  },
  AvgDialog_35990_Content_55 = {
    Text = "Tertawa bersama, menangis bersama, merasakan cinta dan kepercayaan dari Jenkin bersama…"
  },
  AvgDialog_35990_Content_56 = {
    Text = "……Semua hanyalah delusi yang menyedihkan."
  },
  AvgDialog_35990_Content_57 = {
    Text = "Angin bertiup lembut, kepingan salju menari di udara bagai kapas yang halus, jatuh ke segala arah tanpa tujuan."
  },
  AvgDialog_35990_Content_58 = {
    Text = "Cahaya bintang perlahan memudar, kesadaranmu seolah ikut melayang semakin jauh bersama mereka."
  },
  AvgDialog_35990_Content_59 = {
    Text = "Entah seperti apa Alam Cermin berikutnya yang menantimu?"
  },
  AvgDialog_35990_Content_60 = {
    Text = "Tanpa disadari, kau justru merasa sedikit penasaran."
  },
  AvgDialog_35990_Content_61 = {
    Text = "<Yellow:Catatan Investigasi Domain Buatan III>\n\n■Nomor Domain: M-C06\n■Waktu Jatuh: 24 Desember Tahun 315 Aluvi\n■Lokasi Jatuh: Rumah Miskin Lilian"
  },
  AvgDialog_35990_Content_62 = {
    Text = "<Yellow:■Hasil Investigasi>\n\nAku melihat salju, serta cahaya bintang keemasan yang menari di dalamnya.\nEntah mengapa, mereka selalu mengingatkanku pada masa lalu. Kabut naik, cahaya jatuh, tawa perlahan memudar.\nIni adalah malam musim dingin yang tenang.\n\n<Yellow:Selamat Tahun Baru.>\n\nTambahan: Kue kecil berlapis gula buatan Nona Sarah sangat enak."
  },
  AvgDialog_35990_Content_7 = {
    Text = "Kau memejamkan mata, merasakan getaran yang datang dari kedalaman mantel bumi. Itu adalah ritme yang melankolis dan kuno, yang membuatmu teringat akan kampung halamanmu."
  },
  AvgDialog_35990_Content_8 = {
    Text = [[
Entah sudah berapa lama berlalu, kau mendengar suara tawa yang samar, seseorang menggenggam tanganmu.
Kau membalas genggaman kehangatan yang telah lama hilang ini.]]
  },
  AvgDialog_35990_Content_9 = {
    Text = [[
Ibu.
Belum sempat kau memanggil, air mata sudah lebih dulu mengalir.]]
  },
  AvgDialog_35992_Content_1 = {
    Text = "Berhenti di sini"
  },
  AvgDialog_35992_Content_10 = {
    Text = "<Red:Tidak murni. Tidak suci. Tidak bertuah.>"
  },
  AvgDialog_35992_Content_100 = {
    Text = "Cahaya bintang keemasan terus mengalir dari luka, bergoyang rapuh di udara, lalu semuanya membanjiri tubuh Mason."
  },
  AvgDialog_35992_Content_101 = {
    Text = "Kita bersama-sama…… barulah Mason yang sesungguhnya, meow……"
  },
  AvgDialog_35992_Content_102 = {
    Text = "Mason yang sesungguhnya……"
  },
  AvgDialog_35992_Content_103 = {
    Text = "Itu adalah ujung dari semua sungai, tak peduli seberapa jauh jaraknya, semuanya pada akhirnya akan berkumpul di sini."
  },
  AvgDialog_35992_Content_104 = {
    Text = "Aku mendengarnya…… keinginan mereka untuk pulang."
  },
  AvgDialog_35992_Content_105 = {
    Text = "Akan kuberitahu sebuah rahasia: setiap kepribadian adalah rumput apung yang mengembara di dunia, kembali menjadi utuh adalah harapan bersama kita."
  },
  AvgDialog_35992_Content_106 = {
    Text = "Mason perlahan memejamkan mata, merasakan siklus keemasan cahaya bintang di dalam tubuhnya."
  },
  AvgDialog_35992_Content_107 = {
    Text = "Dia melihat wajah dan organ dalamnya, melihat badut, cendekiawan, dan wajah dirinya yang tak terhitung jumlahnya."
  },
  AvgDialog_35992_Content_108 = {
    Text = "Wajah-wajah terpantul di cermin yang pecah, mata-mata itu serentak menatap ke arahnya, penuh ketenangan tanpa batas, penuh kesedihan tanpa batas."
  },
  AvgDialog_35992_Content_109 = {
    Text = "Itu adalah bayangannya, air matanya, dan retakannya, juga darah dan daging yang mengalir jauh di kedalaman bumi."
  },
  AvgDialog_35992_Content_11 = {
    Text = "Aku harus ke sana……aku harus ke sana……"
  },
  AvgDialog_35992_Content_110 = {
    Text = "Mereka dipaksa merobek tubuhnya, terlahir, mengembara, lalu akhirnya kembali dengan tubuh yang lelah."
  },
  AvgDialog_35992_Content_111 = {
    Text = "<Red:Berakhir di sini, berakhir pada diriku.>"
  },
  AvgDialog_35992_Content_12 = {
    Text = "Hei, jangan lari-lari. Aku masih menyisir bulumu.\nAduh aduh, kenapa malah menggigit!\n\n<Gray:Serius deh, dibandingkan kucing Misage, kakakmu ini sudah termasuk sangat penurut……>"
  },
  AvgDialog_35992_Content_13 = {
    Text = "Tawa dan obrolan samar terdengar dari kejauhan, membawa kehangatan dan kerinduan yang begitu akrab baginya, seolah sangat dekat."
  },
  AvgDialog_35992_Content_14 = {
    Text = "Jenkin meow?!"
  },
  AvgDialog_35992_Content_15 = {
    Text = "Kucing itu menegakkan tubuhnya, berusaha keras mencari sumber suara itu."
  },
  AvgDialog_35992_Content_16 = {
    Text = "<Red:Kembalilah.>"
  },
  AvgDialog_35992_Content_17 = {
    Text = "Umm— tidak, aku tidak mau ke sana, nyaa!"
  },
  AvgDialog_35992_Content_18 = {
    Text = "Jenkin, aku harus kembali ke sisi Jenkin… kembali ke sisi semua orang…"
  },
  AvgDialog_35992_Content_19 = {
    Text = "Pergi… <Big:Pergi sana, nyaa!!>"
  },
  AvgDialog_35992_Content_2 = {
    Text = "Kucing yang tertidur lelap bermimpi banyak hal."
  },
  AvgDialog_35992_Content_20 = {
    Text = [[
Iya iya iya, kami tidak akan menyentuhmu lagi.
Kenapa tiba-tiba melompat setinggi itu, mimpi buruk ya?]]
  },
  AvgDialog_35992_Content_21 = {
    Text = "\"24\" dengan waspada memandang sekeliling, pupil mata dan ujung hidungnya terus bergetar."
  },
  AvgDialog_35992_Content_22 = {
    Text = "Sniff sniff… ada orang jahat, tepat di dekat sini…"
  },
  AvgDialog_35992_Content_23 = {
    Text = "Dia melompat tinggi dan menerjang ke sudut. Namun—"
  },
  AvgDialog_35992_Content_25 = {Text = "Uuu……"},
  AvgDialog_35992_Content_26 = {
    Text = "\"24\" meringkuk di tanah sambil meraung pelan. Dari Luka yang menganga mengerikan, Darah merah tua mengalir perlahan."
  },
  AvgDialog_35992_Content_27 = {
    Text = "Tidak buruk, kau cukup waspada. Sayang, kau salah memilih lawan."
  },
  AvgDialog_35992_Content_28 = {
    Text = "Kau?! Di mana Nona Mason, sejak tadi dia tidak terlihat, jangan-jangan—"
  },
  AvgDialog_35992_Content_29 = {
    Text = "Bayangan itu tertawa kecil, lalu melemparkan Mason yang penuh luka di hadapan kalian."
  },
  AvgDialog_35992_Content_3 = {
    Text = "Bercak cahaya yang melayang perlahan di bawah atap sore hari, bubur putih yang menggelegak mengeluarkan uap panas, lonceng tua, kertas permen berwarna-warni……"
  },
  AvgDialog_35992_Content_30 = {
    Text = "%player%{Male=tuan,Female=nyonya}…uhuk uhuk, maafkan aku…"
  },
  AvgDialog_35992_Content_31 = {
    Text = "Bayangan itu mengangkat kakinya, perlahan-lahan menginjak dan menggilas luka Mason."
  },
  AvgDialog_35992_Content_32 = {
    Text = "Ugh… AAAAHH!!"
  },
  AvgDialog_35992_Content_33 = {
    Text = "Sudah kubilang, aku akan membereskan kalian satu per satu."
  },
  AvgDialog_35992_Content_34 = {
    Text = "Diiringi rintihan kesakitan Mason, angin berhenti, debu menahan napasnya, bahkan cahaya matahari pun membeku dalam momen yang abadi."
  },
  AvgDialog_35992_Content_35 = {
    Text = "Bahkan Jenkin di sampingmu pun terdiam bagai patung."
  },
  AvgDialog_35992_Content_36 = {
    Text = "Pada saat yang sama, ruang di sekitar tiba-tiba berguncang beberapa kali, dan langit mulai mengelupas."
  },
  AvgDialog_35992_Content_37 = {
    Text = "Potongan besar langit jatuh dari ketinggian, hancur berkeping-keping."
  },
  AvgDialog_35992_Content_38 = {
    Text = "Dimensi saku runtuh…? Tidak, ini lebih parah dari itu. Apa yang terjadi?!"
  },
  AvgDialog_35992_Content_39 = {
    Text = "Bayangan itu tertawa dingin sambil menendang Mason yang sekarat di kakinya."
  },
  AvgDialog_35992_Content_4 = {
    Text = "Dan gunung bersalju."
  },
  AvgDialog_35992_Content_40 = {
    Text = "Kau belum tahu, ya? Orang ini bisa dibilang <Yellow:kepribadian utama> kami. Kalau dia mati, tempat ini akan jatuh ke dalam kekacauan."
  },
  AvgDialog_35992_Content_41 = {
    Text = "Kalau begitu, yang kau lakukan ini sama saja dengan bunuh diri. Kenapa?"
  },
  AvgDialog_35992_Content_42 = {
    Text = [[
Ini adalah dunia di mana yang kuat memangsa yang lemah. Tidak ada yang menetapkan bahwa kepribadian utama harus dipegang olehnya.
Benar begitu, Nona Mason?]]
  },
  AvgDialog_35992_Content_43 = {
    Text = "Jangan sakiti %player%{Male=tuan,Female=nyonya}…… {Male=dia,Female=dia} adalah penyelamat yang menolong Jenkin……"
  },
  AvgDialog_35992_Content_44 = {
    Text = "Heh heh…… pengecut yang lemah dan tak berdaya."
  },
  AvgDialog_35992_Content_45 = {
    Text = "Kebohongan buruk orang-orang itu, kau tidak menyadarinya."
  },
  AvgDialog_35992_Content_46 = {
    Text = "Pisau bedah menyayat tubuhmu, kau tidak melawan."
  },
  AvgDialog_35992_Content_47 = {
    Text = "Dipaksa bekerja untuk mereka, kau tidak memberontak."
  },
  AvgDialog_35992_Content_48 = {
    Text = "Menyaksikan keluarga tercinta masuk ke rumah miskin, kau tidak mencegahnya."
  },
  AvgDialog_35992_Content_5 = {
    Text = "Eh, ini tempat apa?"
  },
  AvgDialog_35992_Content_50 = {
    Text = "Dan pada akhirnya, kau bahkan gagal memenuhi kewajibanmu sebagai \"kakak\"."
  },
  AvgDialog_35992_Content_51 = {
    Text = "……………"
  },
  AvgDialog_35992_Content_52 = {
    Text = "Semua ingatan itu kau buang kepada kami seperti membuang sampah. Kau berjalan di kampus, di bawah sinar matahari, membiarkan kami mengunyah penderitaan dalam kegelapan kesadaran."
  },
  AvgDialog_35992_Content_53 = {
    Text = [[
Kaulah akar penyebab semua orang tenggelam dalam penderitaan.
Dan sekarang, kau ingin mengendalikanku?]]
  },
  AvgDialog_35992_Content_54 = {
    Text = "<Red:Kau tidak layak menggunakan tubuh ini.>"
  },
  AvgDialog_35992_Content_55 = {
    Text = "Layak atau tidak, bukan kau yang menentukan— Ugh!!"
  },
  AvgDialog_35992_Content_56 = {
    Text = "Kau jatuh berlutut, merasakan dunia berputar. Di sisi lain, bayangan itu bernapas dengan tenang, berjalan perlahan ke arah kalian."
  },
  AvgDialog_35992_Content_57 = {
    Text = "Tidak bisa…… Sekarang aku bahkan tidak bisa berdiri tegak. Aku harus menenangkan jiwa kepribadian utama terlebih dahulu."
  },
  AvgDialog_35992_Content_58 = {
    Text = "Kau merangkak ke sisi Mason dan menggenggam tangannya."
  },
  AvgDialog_35992_Content_59 = {
    Text = "Nona Mason, jangan terpengaruh olehnya——"
  },
  AvgDialog_35992_Content_6 = {
    Text = "Jenkin—miaow—miaow—"
  },
  AvgDialog_35992_Content_60 = {
    Text = "Apakah aku…… terlalu lemah……"
  },
  AvgDialog_35992_Content_61 = {
    Text = "Seandainya aku adalah orang yang lebih kuat..."
  },
  AvgDialog_35992_Content_62 = {
    Text = "Seandainya itu dia, Mason hari ini pasti akan memiliki akhir yang berbeda..."
  },
  AvgDialog_35992_Content_63 = {
    Text = "Hehe, sakit ya? Kalikan rasa sakitmu sekarang dengan sepuluh kali, seratus kali lipat, itulah yang kami rasakan!"
  },
  AvgDialog_35992_Content_64 = {
    Text = "Benar, benar, benar."
  },
  AvgDialog_35992_Content_65 = {
    Text = "Kau tidak layak menggunakan tubuh ini, tubuh, tu, tu, tu."
  },
  AvgDialog_35992_Content_66 = {
    Text = "Maaf, maaf maaf maaf..."
  },
  AvgDialog_35992_Content_67 = {
    Text = "Aku bukan Mason, aku tidak bisa menjadi Mason——"
  },
  AvgDialog_35992_Content_68 = {Text = "Miauw."},
  AvgDialog_35992_Content_69 = {
    Text = "Kucing yang terluka bergerak ke sisi Mason, perlahan menjilati luka berdarahnya."
  },
  AvgDialog_35992_Content_7 = {
    Text = [[
Suara kucing yang lemah dan tipis segera tenggelam dalam badai salju.
Pegunungan megah nan tandus menjulang di depan, menyebarkan cahaya kebiruan yang samar ke seluruh penjuru.]]
  },
  AvgDialog_35992_Content_70 = {
    Text = "Kemudian dia menundukkan kepalanya, melepaskan sesuatu dengan suara gemerisik."
  },
  AvgDialog_35992_Content_71 = {
    Text = "Ini untukmu, jangan menangis miauw."
  },
  AvgDialog_35992_Content_72 = {
    Text = "Di tengah kehampaan, sesuatu diselipkan ke telapak tangannya."
  },
  AvgDialog_35992_Content_73 = {
    Text = "Sehelai kain yang lembut dan dingin, dengan lonceng berkarat tergantung di ujungnya."
  },
  AvgDialog_35992_Content_74 = {
    Text = "Tidak ada satu pun \"24\" yang berlebihan, karena..."
  },
  AvgDialog_35992_Content_75 = {
    Text = "Kau adalah cendekiawan yang cerdas dan tajam"
  },
  AvgDialog_35992_Content_76 = {
    Text = "Tuan Rogers. Jika saya menang, bisakah Anda mengabulkan satu permintaan saya?"
  },
  AvgDialog_35992_Content_77 = {
    Text = "Bukankah kelompok patung lilin Anda masih membutuhkan seorang model? Saya bisa menjadi model Anda."
  },
  AvgDialog_35992_Content_78 = {
    Text = "<Gray:\"Musim Semi\" adalah karya yang direncanakan Rogers untuk tampil di pameran. Selama bisa terpilih sebagai model, eksposur akan meningkat, dan lebih banyak orang bisa melihatnya.>"
  },
  AvgDialog_35992_Content_79 = {
    Text = "<Gray:Jenkin……>"
  },
  AvgDialog_35992_Content_8 = {
    Text = "Sniff sniff……hah?!"
  },
  AvgDialog_35992_Content_80 = {
    Text = "Kau adalah penyemarak suasana bagi semua orang"
  },
  AvgDialog_35992_Content_81 = {
    Text = "Konon pada zaman dahulu kala, di pegunungan bersalju di ujung utara, di penghujung sungai kuno, tertidur seekor monster berwarna abu-abu~~~"
  },
  AvgDialog_35992_Content_82 = {
    Text = "Halo semuanya, aku adalah monster itu.<Shake: Auuu—>"
  },
  AvgDialog_35992_Content_83 = {
    Text = "<Shake:Waaah——>"
  },
  AvgDialog_35992_Content_84 = {
    Text = "Kau adalah kucing yang disukai semua orang"
  },
  AvgDialog_35992_Content_85 = {
    Text = "Ngantuk sekali, huaaah..."
  },
  AvgDialog_35992_Content_86 = {
    Text = "Grrr grrr..."
  },
  AvgDialog_35992_Content_87 = {
    Text = "Benar-benar mengeluarkan suara mendengkur seperti kucing... sama seperti kucing-kucing di kampus Misagar."
  },
  AvgDialog_35992_Content_88 = {
    Text = "Hei, kenapa kamu tersenyum!"
  },
  AvgDialog_35992_Content_89 = {
    Text = "Dia terlihat sangat bahagia sekarang, benar-benar seperti anak kucing yang tanpa beban."
  },
  AvgDialog_35992_Content_9 = {
    Text = "Dia mencium suara-suara. Mereka melayang bercampur di udara, tanpa kata tanpa nada, seperti panggilan lembut seorang ibu."
  },
  AvgDialog_35992_Content_90 = {
    Text = [[
Iya... mereka semua adalah "24" yang sangat baik.
Dibandingkan dengan mereka, aku tidak berguna sama sekali...]]
  },
  AvgDialog_35992_Content_91 = {
    Text = "Kamu menggelengkan kepala pelan."
  },
  AvgDialog_35992_Content_92 = {
    Text = "Justru sebaliknya, kamu lebih kuat dan berani dari mereka semua, karena——"
  },
  AvgDialog_35992_Content_93 = {
    Text = "Kamu adalah kakak perempuan terbaik di dunia"
  },
  AvgDialog_35992_Content_94 = {
    Text = "Tuan, semua ini bermula karena diriku."
  },
  AvgDialog_35992_Content_95 = {
    Text = "Dia hanyalah seorang anak dari kawasan kumuh, tidak tahu apa-apa, tidak akan menjadi ancaman bagi kalian sama sekali……"
  },
  AvgDialog_35992_Content_96 = {
    Text = "<Shake:Bi-biarkan dia pergi……>"
  },
  AvgDialog_35992_Content_97 = {
    Text = "<Shake:Biarkan dia pergi……>"
  },
  AvgDialog_35992_Content_98 = {
    Text = "Kucing itu mengulurkan cakar berbulunya dan menggenggam tangan Mason."
  },
  AvgDialog_35992_Content_99 = {
    Text = "Ada Mason yang berani, ada juga Mason yang penakut. Ada Mason yang pintar, ada juga Mason yang bodoh.\nSemua itu tidak masalah, karena——"
  },
  AvgDialog_35993_Content_1 = {
    Text = "Nyanyian Sang Peziarah"
  },
  AvgDialog_35993_Content_10 = {
    Text = "<Yellow:Kurus, berambut panjang, diduga memiliki lebih dari sepasang tungkai atas.>"
  },
  AvgDialog_35993_Content_11 = {
    Text = "Menurut <Blue:《Laporan Insiden Fusi Southwark Street: C06》>, di sini kebetulan ada makhluk yang sesuai baik dari penampilan maupun jangkauan aktivitasnya."
  },
  AvgDialog_35993_Content_12 = {
    Text = [[
Yang mengarsipkan laporan ini ke dalam arsip gabungan adalah Universitas Misagar sendiri.
Ataukah, Anda sekarang ingin menyangkal keasliannya?]]
  },
  AvgDialog_35993_Content_13 = {
    Text = "Saya hanya sedikit mempertanyakan keandalan laporan saksi mata, reaksi kalian semua agak berlebihan."
  },
  AvgDialog_35993_Content_14 = {
    Text = "Daripada bermain kata-kata, lebih baik kita tanya langsung orangnya."
  },
  AvgDialog_35993_Content_15 = {
    Text = "Miss 24, pada tanggal 17 Desember pukul 9:15 malam, apakah kamu masih ingat apa yang kamu lakukan di <Blue:klinik Dokter Bernard>?"
  },
  AvgDialog_35993_Content_16 = {
    Text = "Hah? Aku…"
  },
  AvgDialog_35993_Content_17 = {
    Text = "Sebagai pengingat: menurut catatan konsultasi <Blue:Dokter Bernard>, kamu adalah pasien terakhir yang diperiksa sebelum ia meninggal."
  },
  AvgDialog_35993_Content_19 = {
    Text = "Apa yang sudah kulakukan ya?"
  },
  AvgDialog_35993_Content_2 = {
    Text = "Sang peziarah bertelanjang kaki merangkak maju."
  },
  AvgDialog_35993_Content_20 = {
    Text = "<Red:…Tentu saja membunuhnya.>"
  },
  AvgDialog_35993_Content_21 = {
    Text = "Miss 24? Apakah Anda mendengarkan?"
  },
  AvgDialog_35993_Content_22 = {
    Text = "Satu kali, dua kali, tiga kali… Aku menghancurkan wajahnya yang tampan itu hingga remuk, bahkan tulangnya pun tak tersisa."
  },
  AvgDialog_35993_Content_23 = {
    Text = "Bau darah menempel di tubuhku, selama seminggu penuh tak kunjung hilang."
  },
  AvgDialog_35993_Content_24 = {
    Text = "<Small:Sayang sekali, tersangka menunjukkan perilaku menghindar. Berdasarkan ketentuan dalam《Perjanjian》, Dewan Peninjauan berhak segera membawanya kembali.>"
  },
  AvgDialog_35993_Content_25 = {
    Text = "<Small:Tidak bisa. Nona 1月24日 berbeda dari Awakened lainnya, dia—>"
  },
  AvgDialog_35993_Content_26 = {
    Text = "<Small:Dia mengidap histeria, dia gila, kita semua tahu itu. Tapi apakah orang gila bisa seenaknya membunuh seorang dokter yang sangat dihormati?>"
  },
  AvgDialog_35993_Content_27 = {
    Text = "<Small:Ini tidak masuk akal, Nona Dor.>"
  },
  AvgDialog_35993_Content_28 = {
    Text = "<Red:Aku adalah seorang pembunuh.>"
  },
  AvgDialog_35993_Content_29 = {
    Text = "Miss 24……? <Big:Miss 24!>"
  },
  AvgDialog_35993_Content_3 = {
    Text = "Badai salju dari tanah ujung utara menutupi wajah sang peziarah. Jari-jari kakinya sudah lama pecah-pecah, pandangannya sudah lama kabur, darahnya menyeret jejak panjang di atas salju."
  },
  AvgDialog_35993_Content_30 = {
    Text = "Cepat bangun, jarumnya belum aku tusukkan! Sekarang bukan waktunya tidur……"
  },
  AvgDialog_35993_Content_31 = {
    Text = "Eh…… ini……"
  },
  AvgDialog_35993_Content_32 = {
    Text = "Syukurlah, kamu akhirnya sadar!"
  },
  AvgDialog_35993_Content_33 = {
    Text = "Ruang Istirahat Misage"
  },
  AvgDialog_35993_Content_34 = {
    Text = "Kudengar belakangan ini ingatanmu sangat kacau, biar kujelaskan sedikit."
  },
  AvgDialog_35993_Content_35 = {
    Text = "Terakhir kali, interogasi mengenai <Yellow:kematian Dokter Bernard> membuat hubungan kita dengan Dewan Peninjauan sangat tidak menyenangkan."
  },
  AvgDialog_35993_Content_36 = {
    Text = "Kesimpulan akhirnya adalah: tujuh hari. Kita hanya punya waktu tujuh hari untuk mengungkap kebenaran."
  },
  AvgDialog_35993_Content_37 = {
    Text = "Kalau aku tidak salah ingat, kejadian ini terjadi sebelum kamu dikirim ke Museum Lilin, jadi kami juga tidak tahu apa-apa soal ini."
  },
  AvgDialog_35993_Content_38 = {
    Text = "Arsipnya sudah disegel selama berbulan-bulan, entah dari mana mereka menemukannya. Lagipula, menyelidiki di tempat sekacau Distrik Timur itu seperti mimpi di siang bolong……"
  },
  AvgDialog_35993_Content_39 = {
    Text = "Jadi, kami memutuskan untuk membiarkan %player% memasukiDomain buatanmu untuk menyelidiki. Untuk itu, kami butuh sedikit kerja samamu……"
  },
  AvgDialog_35993_Content_4 = {
    Text = "Namun ia tetap melangkah dengan teguh, tanpa ragu menuju puncak."
  },
  AvgDialog_35993_Content_40 = {
    Text = "Begitu rupanya. Maaf, belakangan ini aku selalu merasa linglung……"
  },
  AvgDialog_35993_Content_41 = {
    Text = "Seolah-olah di dalam tubuh sedang mengumpulkan badai dahsyat, namun sang pemilik tubuh sama sekali tidak menyadarinya."
  },
  AvgDialog_35993_Content_42 = {Text = "Tunggu."},
  AvgDialog_35993_Content_43 = {
    Text = "Apakah \"aku\" benar-benar pemilik tubuh ini?"
  },
  AvgDialog_35993_Content_44 = {
    Text = "Ting——!"
  },
  AvgDialog_35993_Content_45 = {
    Text = "Winkel dengan cepat mengeluarkan jarum suntik yang sudah disiapkan sejak tadi."
  },
  AvgDialog_35993_Content_46 = {
    Text = "Tenang saja, aku datang memang untuk ini.\nSekali suntik, kepalamu yang kacau itu akan jauh lebih jernih……"
  },
  AvgDialog_35993_Content_47 = {
    Text = "<Shake:Dengan begini%player%di dalam juga bisa tidak terlalu menderita lagipula siapa yang tahu apa saja yang ada di dalam kalau sampai terjadi bencana alam atau musibah bagaimana……>"
  },
  AvgDialog_35993_Content_48 = {
    Text = "Atau seperti waktu itu bertemu keberadaan mengerikan seperti \"N\"——<Big:Aah!!>"
  },
  AvgDialog_35993_Content_49 = {
    Text = "Winkel dengan cemas menggaruk-garuk rambutnya, lalu terkejut sambil menarik napas tajam."
  },
  AvgDialog_35993_Content_5 = {
    Text = "Ya——\nDi balik pegunungan putih itu, jauh di kedalaman gua yang gelap, bersemayam <Red:sumber> dari segala kenajisan."
  },
  AvgDialog_35993_Content_50 = {
    Text = "<Shake:Sial! Kenapa rontok sebanyak ini lagi……>"
  },
  AvgDialog_35993_Content_51 = {
    Text = "Miss 24 membutuhkan ketenangan, bukan kecemasanmu dan Rambut. Winkle, setelah menyuntik segera pergi."
  },
  AvgDialog_35993_Content_52 = {
    Text = "Sepuluh menit kemudian"
  },
  AvgDialog_35993_Content_53 = {
    Text = "Apakah sekarang sudah merasa lebih baik, Miss 24?"
  },
  AvgDialog_35993_Content_54 = {
    Text = "Aku tidak apa-apa, hanya sedikit pusing……Di mana %player%?"
  },
  AvgDialog_35993_Content_55 = {
    Text = [[
Sudah berada di jalur Metaspace buatan.
Tenang saja, kali ini waktu yang kami atur hanya setengah jam, tidak akan berlama-lama.]]
  },
  AvgDialog_35993_Content_56 = {
    Text = "Bagaimana dengan Nona Ramona, apakah dia tidak ikut menyelidiki bersama?"
  },
  AvgDialog_35993_Content_57 = {
    Text = "Mengingat kondisi mental pemilik Metaspace yang tidak terlalu……stabil, apa yang akan muncul di dalam Metaspace, tak seorang pun dari kita bisa membayangkan."
  },
  AvgDialog_35993_Content_58 = {
    Text = "Kekuatan mental Ramona belum tentu mampu menahannya."
  },
  AvgDialog_35993_Content_59 = {
    Text = "24 menundukkan kepala dengan lesu, diam-diam menggenggam sudut selimut dengan erat."
  },
  AvgDialog_35993_Content_6 = {
    Text = "Itulah ketakutannya, mimpi buruknya."
  },
  AvgDialog_35993_Content_60 = {
    Text = "Nona Dor, bagaimana jika kukatakan……pelakunya memang benar aku?"
  },
  AvgDialog_35993_Content_61 = {
    Text = "Aku mengingatnya. Hari itu aku pergi ke klinik, lalu——"
  },
  AvgDialog_35993_Content_62 = {
    Text = "Sst……aku tidak bisa menjamin bahwa Dewan Audit tidak menempatkan mata-mata di sini lho."
  },
  AvgDialog_35993_Content_63 = {
    Text = "Dor mengingat-ingat rupa Sylvia, berusaha keras memasang senyuman yang melambangkan penghiburan pada wajahnya."
  },
  AvgDialog_35993_Content_64 = {
    Text = "Miss 24, kamu mungkin jauh lebih tidak mengenal dirimu sendiri daripada yang kamu kira."
  },
  AvgDialog_35993_Content_65 = {
    Text = "Apa yang kau sebut \"kebenaran\" yang kau lihat, belum tentu benar."
  },
  AvgDialog_35993_Content_66 = {
    Text = "Aku tidak mengerti… bukan kebenaran…?"
  },
  AvgDialog_35993_Content_67 = {
    Text = "Kau sudah berada di Misage selama beberapa bulan, tapi kami sama sekali tidak tahu apa-apa tentang penyakitmu maupun pengalamanmu."
  },
  AvgDialog_35993_Content_68 = {
    Text = "Anggaplah penyelidikan Domain kali ini sebagai kesempatan untuk mengenalmu kembali, Miss 24."
  },
  AvgDialog_35993_Content_69 = {
    Text = "Kami semua ingin memahami dirimu dengan baik."
  },
  AvgDialog_35993_Content_7 = {
    Text = "Dan juga tempat kembalinya."
  },
  AvgDialog_35993_Content_8 = {
    Text = "Saya tidak menerima apa yang kalian sebut sebagai \"bukti\"."
  },
  AvgDialog_35993_Content_9 = {
    Text = "Laporan saksi mata ini hanya bisa membuktikan bahwa pelakunya adalah makhluk non-manusia, tidak bisa menunjuk individu tertentu."
  },
  AvgDialog_35994_Content_1 = {
    Text = "Dongeng Bayangan"
  },
  AvgDialog_35994_Content_10 = {
    Text = "<Red:Ssshh…>"
  },
  AvgDialog_35994_Content_11 = {
    Text = "Dari kegelapan terdengar gerakan samar, seperti ular berbisa menjulurkan lidahnya di sudut yang tak berpenghuni."
  },
  AvgDialog_35994_Content_12 = {
    Text = "Ular… siapa di sana?!"
  },
  AvgDialog_35994_Content_13 = {
    Text = "Tak tak tak."
  },
  AvgDialog_35994_Content_14 = {
    Text = "Langkah kaki tergesa-gesa terdengar mendekat dari kejauhan, rambut panjang melesat melewati wajahmu."
  },
  AvgDialog_35994_Content_15 = {
    Text = "Nona Mason?!"
  },
  AvgDialog_35994_Content_16 = {
    Text = "Lepaskan aku... Aduh, siapa kamu? Kamu sekongkol dengan <Yellow:dia>?"
  },
  AvgDialog_35994_Content_17 = {
    Text = "Eh, kamu tidak mengenaliku?"
  },
  AvgDialog_35994_Content_18 = {
    Text = "<Gray:Aku baru ingat, kasus pembunuhan terjadi sebelum Nona Mason memasuki museum lilin, saat itu kami belum saling kenal...>"
  },
  AvgDialog_35994_Content_19 = {
    Text = "Tak, tak, tak."
  },
  AvgDialog_35994_Content_2 = {
    Text = "<Yellow:Jurnal Penyelidikan Domain Buatan>\n\n■Nomor Domain: M-C06\n\n■Waktu Pengaturan: 17 Desember Tahun 315 Aluvi, 9:00-9:30pm\n■Lokasi Pengaturan: Klinik Dokter Bernard"
  },
  AvgDialog_35994_Content_20 = {
    Text = "Berbeda dari langkah kaki terburu-buru sebelumnya, kali ini langkahnya terdengar lebih mantap."
  },
  AvgDialog_35994_Content_21 = {
    Text = "<Shake:Dia datang, dia datang...>"
  },
  AvgDialog_35994_Content_22 = {
    Text = "Siapa yang datang?"
  },
  AvgDialog_35994_Content_23 = {
    Text = "Dia... bukan, \"aku\" yang datang!"
  },
  AvgDialog_35994_Content_24 = {
    Text = "<Big:\"Aku\" datang untuk membunuhku!>"
  },
  AvgDialog_35994_Content_25 = {Text = "?"},
  AvgDialog_35994_Content_26 = {
    Text = "Tinju yang disertai desiran angin menyerang ke arah kalian."
  },
  AvgDialog_35994_Content_28 = {
    Text = "<Big:Matilah kalian semua!>"
  },
  AvgDialog_35994_Content_29 = {
    Text = "Sepuluh menit kemudian"
  },
  AvgDialog_35994_Content_3 = {
    Text = "■Pemilik Domain: Mason·@2\n■Penyusup Domain: %player%\n■Tujuan Penyusupan: <Yellow:Menginvestigasi kasus kematian Dokter Bernard>"
  },
  AvgDialog_35994_Content_31 = {
    Text = "Tolong tenang sebentar, Orang Ini... Nona \"24\"."
  },
  AvgDialog_35994_Content_32 = {
    Text = "Kamu berdiri di depan Mason, dengan susah payah menahan serangan brutal sang bayangan."
  },
  AvgDialog_35994_Content_33 = {
    Text = "Selangkah lagi maju, aku tidak akan segan-segan lagi."
  },
  AvgDialog_35994_Content_34 = {
    Text = "Heh, sepertinya si cengeng sudah menemukan seorang penolong."
  },
  AvgDialog_35994_Content_35 = {
    Text = "Cahaya redup menyingkap siluet ramping yang familiar: rambut panjang, gaun putih, iris mata merah seperti darah."
  },
  AvgDialog_35994_Content_36 = {
    Text = "Itu adalah \"24\" yang lain."
  },
  AvgDialog_35994_Content_37 = {
    Text = "Tidak ada waktu lagi... Tenang saja, aku akan membereskan kalian satu per satu."
  },
  AvgDialog_35994_Content_38 = {
    Text = "Giliranmu akan tiba."
  },
  AvgDialog_35994_Content_39 = {
    Text = "Meninggalkan sepatah kata yang tidak jelas ujung pangkalnya,\"24\" pergi dengan tegas dan cepat."
  },
  AvgDialog_35994_Content_4 = {
    Text = "<Shake:Uhuk uhuk… bau sekali…>"
  },
  AvgDialog_35994_Content_40 = {Text = "Tunggu—"},
  AvgDialog_35994_Content_41 = {
    Text = "Jangan dikejar, kita tidak bisa mengalahkannya..."
  },
  AvgDialog_35994_Content_42 = {
    Text = "Apa yang terjadi? Kenapa ada dirimu yang lain di sini?"
  },
  AvgDialog_35994_Content_43 = {
    Text = "Aku tidak tahu... Dia tiba-tiba muncul begitu saja dan bilang ingin membunuhku..."
  },
  AvgDialog_35994_Content_44 = {
    Text = "Dokter itu, dia juga yang membunuhnya?"
  },
  AvgDialog_35994_Content_45 = {
    Text = "Ternyata dia yang membunuhnya?! Tidak, bukan hanya itu... Ada juga ular-ular yang berhibernasi..."
  },
  AvgDialog_35994_Content_46 = {
    Text = "Ribuan ular@2membunuh saudara-saudara mereka sendiri, jari-jari dimasukkan ke mulut... Umm..."
  },
  AvgDialog_35994_Content_47 = {
    Text = "Nona Mason? Kamu tahu apa yang kamu bicarakan?"
  },
  AvgDialog_35994_Content_48 = {
    Text = "Bicara? Yang penting bukan apa yang dikatakan, tapi apa yang dilakukan! Ini yang diajarkan Tuan @2 kepadaku..."
  },
  AvgDialog_35994_Content_49 = {
    Text = "Mason sepenuhnya tenggelam dalam dunianya sendiri, mulutnya mengucapkan serangkaian igauan yang kacau."
  },
  AvgDialog_35994_Content_5 = {
    Text = "Bau amis darah yang pekat menyelimuti klinik, peralatan medis, buku-buku, dan catatan pasien berserakan di mana-mana."
  },
  AvgDialog_35994_Content_50 = {
    Text = "Kamu... Sepertinya aku pernah melihatmu di suatu tempat..."
  },
  AvgDialog_35994_Content_51 = {
    Text = "%player%... Kamu adalah Penjaga Rahasia {Male=tuan,Female=nyonya}!"
  },
  AvgDialog_35994_Content_53 = {
    Text = "Kenapa tiba-tiba ingat siapa aku?"
  },
  AvgDialog_35994_Content_54 = {
    Text = "Kamu tiba-tiba merasa sedikit sakit kepala."
  },
  AvgDialog_35994_Content_55 = {
    Text = "Jangan buru-buru masuk, aku belum selesai bicara."
  },
  AvgDialog_35994_Content_56 = {
    Text = "Domain Miss 24 berbeda dengan Ramona dan Nyonya Sorel. Dia tidak memiliki kepribadian yang stabil, dan sifat ini pasti akan tercermin dalam Domain-nya."
  },
  AvgDialog_35994_Content_57 = {
    Text = "Kepribadian-kepribadian yang berbeda saling terisolasi satu sama lain, namun juga saling berbaur. Kamu bahkan akan melihat banyak 24 di dalamnya."
  },
  AvgDialog_35994_Content_58 = {
    Text = "Segalanya—tokoh, tempat, waktu... mungkin semuanya tidak nyata."
  },
  AvgDialog_35994_Content_59 = {
    Text = "Kalau semuanya palsu, apakah masih perlu diselidiki?"
  },
  AvgDialog_35994_Content_6 = {
    Text = "Jasad Dokter Bernard terkulai di sisi dinding. Kepalanya sudah hancur, wajahnya tak lagi bisa dikenali."
  },
  AvgDialog_35994_Content_60 = {
    Text = "Tentu saja. Bahkan jika hanya ada satu persen kebenaran di dalamnya, kita harus menangkapnya."
  },
  AvgDialog_35994_Content_61 = {
    Text = "Miss 24 sama sekali bukan orang jahat yang membunuh orang tak bersalah sembarangan, hal ini sudah kita ketahui bersama."
  },
  AvgDialog_35994_Content_62 = {
    Text = "Semua itu tidak nyata... Tenang, %player%. Tentukan dulu tujuan penyelidikan."
  },
  AvgDialog_35994_Content_63 = {
    Text = "Kamu menarik jari-jari Mason. Jari-jarinya sangat bersih, tanpa bekas luka atau tanda-tanda perkelahian."
  },
  AvgDialog_35994_Content_64 = {
    Text = "Nona Mason, apakah kamu punya masalah dengan Dokter Bernard?"
  },
  AvgDialog_35994_Content_65 = {
    Text = "Dia... dia mengobati penyakitku, belakangan ini aku selalu merasa badanku gatal-gatal, aneh sekali..."
  },
  AvgDialog_35994_Content_66 = {
    Text = "Sambil berbicara, Mason dengan santai menggaruk bola mata putih yang tumbuh dari luka erosi di tubuhnya."
  },
  AvgDialog_35994_Content_67 = {
    Text = "Tentu saja, dia sama sekali tidak menyadari tindakannya sendiri itu."
  },
  AvgDialog_35994_Content_68 = {
    Text = "Dia mengobatimu. Lalu apa, kalian bertengkar?"
  },
  AvgDialog_35994_Content_69 = {
    Text = "Setelah itu, setelah itu aku tidak bisa mengingat apa-apa lagi..."
  },
  AvgDialog_35994_Content_7 = {
    Text = "\"Laki-laki 30 tahun, tinggi 6 kaki, pernah lulus dengan predikat sangat baik dari Fakultas Kedokteran Universitas Londinium…\""
  },
  AvgDialog_35994_Content_70 = {
    Text = "Begitu rupanya, aku kira-kira sudah paham."
  },
  AvgDialog_35994_Content_71 = {
    Text = "<Gray:Amnesia adalah gejala penting dari kepribadian ganda. Kemungkinan besar sesuatu terjadi selama pengobatan, menyebabkan kepribadian bayangan muncul dan membunuh dokter itu...>"
  },
  AvgDialog_35994_Content_72 = {
    Text = "<Gray:Selanjutnya tinggal memutar waktu Mystic Field berikutnya mundur satu jam lagi, untuk melihat apa yang terjadi saat itu...>"
  },
  AvgDialog_35994_Content_73 = {
    Text = "Kamu mengangkat tangan dan melihat jam."
  },
  AvgDialog_35994_Content_74 = {
    Text = "Mystic Field akan segera berakhir, penyelidikan kali ini cukup sampai di sini dulu."
  },
  AvgDialog_35994_Content_75 = {
    Text = "Nona Dor sepertinya terlalu khawatir, Mystic Field ini jauh lebih sederhana dibanding milik Nyonya Soreil..."
  },
  AvgDialog_35994_Content_76 = {
    Text = "Kamu meregangkan badan, lalu berjongkok di depan Mason, menatap langsung ke kedua matanya."
  },
  AvgDialog_35994_Content_77 = {
    Text = "Nona Mason, penyakitmu ini bukan penyakit biasa, bukan sesuatu yang bisa diobati oleh dokter mana pun yang punya ijazah bagus."
  },
  AvgDialog_35994_Content_78 = {
    Text = "Lain kali ingat datang ke Misage untuk mencari kami, mengerti?"
  },
  AvgDialog_35994_Content_79 = {
    Text = "Mi, sa, ge..."
  },
  AvgDialog_35994_Content_8 = {
    Text = "\"Dikenal dermawan dan suka menolong, selama bertahun-tahun menjalankan layanan medis sukarela di berbagai tempat di Distrik Timur…\""
  },
  AvgDialog_35994_Content_80 = {
    Text = "Benar, Universitas Misage. Kami ini profesional."
  },
  AvgDialog_35994_Content_81 = {Text = "Oh……"},
  AvgDialog_35994_Content_82 = {
    Text = "Krak. Krak."
  },
  AvgDialog_35994_Content_83 = {
    Text = "Dinding di atas kepala mulai mengelupas sedikit demi sedikit, Mystic Realm tidak lagi stabil."
  },
  AvgDialog_35994_Content_84 = {
    Text = "Sampai jumpa, Nona Mason."
  },
  AvgDialog_35994_Content_86 = {
    Text = [[
Waktu menunjukkan pukul 9:30 malam.
Angin dingin bertiup kencang, dari luar jendela terdengar satu dua kali suara gagak yang sepi.]]
  },
  AvgDialog_35994_Content_87 = {
    Text = "Kamu masih berdiri tegap di dalam klinik, di sampingmu Mason duduk berlutut dengan ekspresi bingung."
  },
  AvgDialog_35994_Content_88 = {
    Text = "Eh…… Penjaga Rahasia {Male=tuan,Female=nyonya}, Anda tidak berencana pergi lagi?"
  },
  AvgDialog_35994_Content_89 = {
    Text = "<Shake:Ugh, jangan-jangan peralatannya rusak?>"
  },
  AvgDialog_35994_Content_9 = {
    Text = "Rekam jejak yang tak tercela, pantas saja kepolisian dan dewan peninjau begitu menaruh perhatian."
  },
  AvgDialog_35994_Content_90 = {
    Text = "GRRRUMM——!!"
  },
  AvgDialog_35994_Content_91 = {
    Text = "Detik berikutnya, dunia runtuh dengan cepat, kamu jatuh ke dalam jurang tanpa dasar."
  },
  AvgDialog_35994_Content_92 = {
    Text = "<Big:AAAAAAH——!!!>"
  },
  AvgDialog_35994_Content_93 = {
    Text = "<Yellow:Log Investigasi Mystic Realm Buatan I>\n\n■Nomor Realm: M-C06\n■Waktu Pengaturan: 17 Desember tahun Diluvian 315, 9:00-9:30pm\n■Lokasi Pengaturan: Klinik Dokter Bernard"
  },
  AvgDialog_35994_Content_94 = {
    Text = "<Yellow:■Hasil Investigasi>\n\n——Penjaga Rahasia hilang kontak."
  },
  AvgDialog_35996_Content_1 = {
    Text = "Kenapa……kenapa……"
  },
  AvgDialog_35996_Content_10 = {
    Text = "Yang terjebak dalam kesulitan hidup dan tidak tahu harus meminta bantuan ke mana, adalah \"24\"."
  },
  AvgDialog_35996_Content_11 = {
    Text = "Yang merasa bahagia dengan kehidupan yang sederhana, adalah \"24\"."
  },
  AvgDialog_35996_Content_12 = {
    Text = "Yang disiksa oleh Asosiasi Pematung, juga adalah \"24\"."
  },
  AvgDialog_35996_Content_13 = {
    Text = "Tidak…kalau bukan karena kepengecutanmu, kita juga tidak akan diapa-apakan oleh dokter itu……"
  },
  AvgDialog_35996_Content_14 = {Text = "Ssst……"},
  AvgDialog_35996_Content_15 = {
    Text = "Mason dengan lembut menutup bibir bayangan itu. Dia menundukkan kepala, berbisik di telinga sang bayangan."
  },
  AvgDialog_35996_Content_16 = {
    Text = "Akan kuberitahu sebuah rahasia: <Red:Dokter itu dibunuh olehku.>"
  },
  AvgDialog_35996_Content_17 = {
    Text = "Tidak mungkin. Bagaimana mungkin kau punya keberanian seperti itu……?!"
  },
  AvgDialog_35996_Content_18 = {
    Text = "Membunuh orang bukanlah hal yang sulit. Saat itu aku tidak punya senjata, jadi aku menggunakan tanganku untuk—"
  },
  AvgDialog_35996_Content_19 = {
    Text = "Pada akhirnya, tanganku sudah lama kehilangan rasa, dan yang terlihat di mataku hanyalah darah, tidak ada yang lain."
  },
  AvgDialog_35996_Content_2 = {
    Text = "Bayangan itu dikalahkan oleh kalian. Dia tersungkur di tanah, tubuhnya memancarkan titik-titik cahaya halus yang melayang keluar."
  },
  AvgDialog_35996_Content_20 = {
    Text = "Karena aku harus memastikan dia benar-benar mati. Selama dia masih bernapas, dia pasti akan menyakiti anak-anak di rumah penampungan, dan juga Jenkin…"
  },
  AvgDialog_35996_Content_21 = {
    Text = "Dia sama seperti orang-orang di Asosiasi Pematung itu, tidak—dia bahkan lebih mengerikan dari mereka…"
  },
  AvgDialog_35996_Content_22 = {
    Text = "Dia adalah iblis yang sesungguhnya."
  },
  AvgDialog_35996_Content_23 = {
    Text = "Ternyata kamu… tidak kusangka ternyata kamu…"
  },
  AvgDialog_35996_Content_24 = {
    Text = "Saat itu, apa yang sedang kulakukan… Aku sama sekali tidak tahu…"
  },
  AvgDialog_35996_Content_25 = {
    Text = "Mason menggelengkan kepalanya pelan."
  },
  AvgDialog_35996_Content_26 = {
    Text = "Kamu dan 「24」-「24」 lainnya yang meminjamkan keberanian kepadaku."
  },
  AvgDialog_35996_Content_27 = {
    Text = [[
Semua "24" bergabung, barulah terbentuk satu "Mason".
Tidak ada "24" yang bisa berdiri sendiri.]]
  },
  AvgDialog_35996_Content_28 = {
    Text = "Seperti semua sungai yang akan bermuara ke satu tempat, semua \"24\" pun akan berkumpul di satu tempat..."
  },
  AvgDialog_35996_Content_29 = {
    Text = "Mason mencium lembut dahi sang bayangan."
  },
  AvgDialog_35996_Content_3 = {
    Text = "Aku yang sekuat ini, aku yang penuh amarah……bagaimana mungkin kalah dari kalian, kalah dari pengecut ini……"
  },
  AvgDialog_35996_Content_30 = {
    Text = "Kembali kepadaku."
  },
  AvgDialog_35996_Content_32 = {
    Text = "Tubuh sang bayangan berubah menjadi cahaya bintang yang bertebaran. Mereka melayang-layang di sekitar Mason, lalu meresap ke dalam kulitnya."
  },
  AvgDialog_35996_Content_33 = {
    Text = "Begitu rupanya… Aku mengerti sekarang."
  },
  AvgDialog_35996_Content_34 = {
    Text = "Kamu adalah asal mula segalanya, dan juga akhir dari segalanya…"
  },
  AvgDialog_35996_Content_35 = {
    Text = "Suaranya perlahan menghilang dalam pelukan yang hangat."
  },
  AvgDialog_35996_Content_36 = {
    Text = "Cahaya bintang bagaikan kunang-kunang di kegelapan malam, samar-samar terlihat, hingga akhirnya lenyap tak terlihat."
  },
  AvgDialog_35996_Content_37 = {
    Text = "Selamat malam,\"seperduapuluh empat\"-ku."
  },
  AvgDialog_35996_Content_38 = {
    Text = "<Yellow:Catatan Investigasi Ruang Buatan Ⅳ>\n\n■Nomor Ruang: M-C06\n■Waktu Jatuh: Tahun Diluvian 315, Desember@1\n■Lokasi Jatuh: Jalan Camberwell, Distrik Timur"
  },
  AvgDialog_35996_Content_39 = {
    Text = "<Yellow:■Hasil Investigasi>\n\nDunia rahasia itu berakhir dengan cara yang tenang.\nSetelah itu, kondisi Nona Mason menjadi jauh lebih stabil, sesuatu yang membuat semua orang sangat bahagia.\n\n<Yellow:Kita semakin mendekati sosok Nona Mason yang sesungguhnya.>"
  },
  AvgDialog_35996_Content_4 = {
    Text = "Karena……"
  },
  AvgDialog_35996_Content_40 = {
    Text = [[
Universitas Misagor, Kantor Administrasi
Satu hari kemudian]]
  },
  AvgDialog_35996_Content_41 = {
    Text = "Apa, dewan peninjau mencabut tuntutannya?"
  },
  AvgDialog_35996_Content_42 = {
    Text = "Banyak hal menarik terjadi saat kamu tidak ada. Mereka sekarang sibuk membersihkan wabah ular bersama orang-orang dari Dinas Lingkungan Hidup kota."
  },
  AvgDialog_35996_Content_43 = {
    Text = "Wabah ular……?"
  },
  AvgDialog_35996_Content_44 = {
    Text = "Doer membentangkan edisi Londinium Post beberapa hari lalu dan mengangkatnya di depanmu."
  },
  AvgDialog_35996_Content_45 = {
    Text = "\"Baru-baru ini, dari klinik mendiang Dokter Bernard tiba-tiba muncul sejumlah besar ular albino dari spesies yang tidak diketahui, menyebabkan kemacetan serius pada lalu lintas dan kehidupan warga setempat……\""
  },
  AvgDialog_35996_Content_46 = {
    Text = "\"Saksi mata menyatakan bahwa ini adalah pemandangan paling mengerikan yang pernah dilihatnya seumur hidup. Jika Anda, para pembaca, juga tidak beruntung menyaksikan kejadian tersebut, silakan hubungi psikolog @2 untuk mendapatkan bantuan……\""
  },
  AvgDialog_35996_Content_47 = {
    Text = "\"Nomor @4……\""
  },
  AvgDialog_35996_Content_48 = {
    Text = "Di samping berita itu juga terlampir foto, dan kamu sepertinya melihat beberapa sosok familiar dari dewan peninjau."
  },
  AvgDialog_35996_Content_49 = {
    Text = "Mereka memegang jaring penangkap, dengan rajin membersihkan ular-ular kecil yang terus bermunculan, wajah mereka dipenuhi kelelahan dan ketidaksabaran yang tak bisa disembunyikan."
  },
  AvgDialog_35996_Content_50 = {
    Text = "\"Dokter Bernard\" yang disebut-sebut itu sangat mencurigakan."
  },
  AvgDialog_35996_Content_51 = {
    Text = "Kami menemui orang-orang dari Perhimpunan Kedokteran Kerajaan, dan foto serta data yang mereka berikan sama sekali tidak cocok dengan deskripsi penduduk sekitar."
  },
  AvgDialog_35996_Content_52 = {
    Text = "Dengan kata lain, si korban telah mencuri identitas Dokter Bernard ini. Namun melihat situasi saat ini, apakah dokter palsu ini benar-benar sudah mati masih belum bisa dipastikan."
  },
  AvgDialog_35996_Content_53 = {
    Text = "Lagipula, di lokasi kejadian bahkan tidak ditemukan jejak mayat sama sekali……"
  },
  AvgDialog_35996_Content_54 = {
    Text = [[
17 Desember, hari kejadian
Klinik Dokter Bernard]]
  },
  AvgDialog_35996_Content_55 = {
    Text = "Sesi terapi hari ini sampai di sini saja. Nona Mason, pemulihanmu cukup baik."
  },
  AvgDialog_35996_Content_56 = {
    Text = "Benarkah? Tapi semua orang bilang kondisiku semakin parah……"
  },
  AvgDialog_35996_Content_57 = {
    Text = [[
Pemahaman saya dan manusia lainnya tentang "parah" mungkin agak berbeda.
Apakah semua tinktur yang saya resepkan sudah diminum tepat waktu?]]
  },
  AvgDialog_35996_Content_58 = {Text = "BRASSHH!!"},
  AvgDialog_35996_Content_59 = {
    Text = "Dokter tidak sengaja menyenggol tumpukan dokumen di sampingnya, kertas-kertas yang telah menguning berhamburan ke lantai."
  },
  AvgDialog_35996_Content_6 = {
    Text = "Serahkan padaku."
  },
  AvgDialog_35996_Content_60 = {
    Text = "Maaf, akhir-akhir ini wabah penyakit sering melanda distrik timur, berkas-berkas yang menumpuk di klinik juga semakin banyak——"
  },
  AvgDialog_35996_Content_61 = {
    Text = "Tidak apa-apa! Anda kan dokter hebat yang bekerja keras siang dan malam, hal kecil seperti memungut barang serahkan saja pada……"
  },
  AvgDialog_35996_Content_62 = {Text = "Saya……"},
  AvgDialog_35996_Content_63 = {
    Text = "Tangannya berhenti kurang dari 2 inci dari dokumen tersebut. Ini adalah setumpuk arsip identitas, dan Mason dengan susah payah mengenali beberapa kata yang cukup familiar."
  },
  AvgDialog_35996_Content_64 = {
    Text = "Laporan eksperimen, catatan pemindahan……?"
  },
  AvgDialog_35996_Content_65 = {
    Text = "<Shake:Ini… anak-anak yang hilang dari panti asuhan! Tidak, bukan hanya itu……>"
  },
  AvgDialog_35996_Content_66 = {
    Text = "Di sudut arsip paling bawah yang tersingkap, wajah Jenkins yang sedikit keras kepala muncul di hadapan Mason."
  },
  AvgDialog_35996_Content_67 = {
    Text = "Ini adikmu, kan? Aku pernah melihatnya. Dia sangat mengkhawatirkanmu, bahkan pernah mencoba menyelinap masuk ke sini."
  },
  AvgDialog_35996_Content_68 = {
    Text = "Dia tersenyum tipis, ekspresinya pun menjadi lembut."
  },
  AvgDialog_35996_Content_69 = {
    Text = "Aku juga pernah punya banyak saudara… Mereka hanya takut padaku, gentar padaku, jadi aku memakan mereka semua."
  },
  AvgDialog_35996_Content_70 = {
    Text = "Semua… dimakan……?"
  },
  AvgDialog_35996_Content_71 = {
    Text = "Tenang saja, Nona Mason. Aku tidak memakan teman-temanmu, hanya mengirim mereka ke <Red:tempat yang aman>."
  },
  AvgDialog_35996_Content_72 = {
    Text = "Jadi kaulah dalang di balik semua kasus penghilangan ini……"
  },
  AvgDialog_35996_Content_73 = {
    Text = "<Shake:Lelucon ini sama sekali tidak lucu, Tuan Bernard……>"
  },
  AvgDialog_35996_Content_74 = {
    Text = "Tuan Bernard… maksudmu dia?"
  },
  AvgDialog_35996_Content_75 = {
    Text = "Setelah berkata demikian, dari mulut pria itu menjulur lidah bercabang yang panjang, di ujungnya terlilit sebuah jari putus yang berlumuran darah."
  },
  AvgDialog_35996_Content_76 = {
    Text = "Tubuhnya terlalu besar, sampai sekarang aku belum selesai mencernanya."
  },
  AvgDialog_35996_Content_77 = {
    Text = "Mari berkenalan kembali, namaku <Yellow:Albino>, apoteker dari Asosiasi Pematung."
  },
  AvgDialog_35996_Content_78 = {
    Text = "AAAAAAA——!!"
  },
  AvgDialog_35996_Content_79 = {
    Text = "Kaki Mason melemas, dan ia jatuh terduduk ke tanah dengan keras."
  },
  AvgDialog_35996_Content_8 = {
    Text = "Mason duduk di samping bayangan itu, memeluk bayangan yang tak bisa bergerak lagi ke dalam dekapannya."
  },
  AvgDialog_35996_Content_80 = {
    Text = "<Shake:Kau orang jahat…… kau mau menjadikan Jenkin juga……>"
  },
  AvgDialog_35996_Content_81 = {
    Text = "Pria itu membetulkan bingkai kacamatanya, mengeluarkan catatan medis dan menulis dengan cepat di atasnya."
  },
  AvgDialog_35996_Content_82 = {
    Text = "Pupil membesar, tubuh gemetar hebat, detak jantung meningkat…… Kau pasti sangat ketakutan sekarang. Kedinginan?"
  },
  AvgDialog_35996_Content_83 = {
    Text = "Tidak…… jangan mendekat……"
  },
  AvgDialog_35996_Content_84 = {
    Text = "Sebentar lagi, kau akan pingsan karena suplai darah ke otak yang tidak mencukupi, sama seperti manusia-manusia membosankan lainnya."
  },
  AvgDialog_35996_Content_85 = {
    Text = "Dia mengangkat kepalanya dari buku catatan medis, pupil vertikal keemasannya samar-samar berkilat dengan secercah kegembiraan."
  },
  AvgDialog_35996_Content_86 = {
    Text = "Atau…… kau akan menunjukkan reaksi yang berbeda?"
  },
  AvgDialog_35996_Content_87 = {
    Text = "Dua puluh menit kemudian"
  },
  AvgDialog_35996_Content_88 = {
    Text = "Aku membunuh orang, aku benar-benar membunuh seorang dokter…… Mereka tidak akan mempercayaiku……"
  },
  AvgDialog_35996_Content_89 = {
    Text = "Tidak, kenapa tadi aku membunuhnya……"
  },
  AvgDialog_35996_Content_9 = {
    Text = "Karena... kamu tidak menerima semua \"24\"."
  },
  AvgDialog_35996_Content_90 = {
    Text = "Mason tersadar seperti baru bangun dari mimpi, dan meninggalkan tempat kejadian dengan panik."
  },
  AvgDialog_35996_Content_91 = {
    Text = "Tubuh pria itu terkulai lemas di sudut dinding. Kepalanya sudah hancur sejak tadi, darah terus merembes keluar darinya."
  },
  AvgDialog_35996_Content_92 = {
    Text = "Entah berapa lama berlalu, tiba-tiba serangkaian belenggu kutukan hitam menyala di leher mayat itu."
  },
  AvgDialog_35996_Content_93 = {
    Text = "Belenggu kutukan itu berputar perlahan bagaikan ular, daging dan darah yang sudah hancur menjadi bubur pun mulai berkumpul dan menyusun ulang diri……"
  },
  AvgDialog_35996_Content_94 = {
    Text = "Hingga akhirnya, \"mayat\" itu perlahan-lahan bangkit duduk."
  },
  AvgDialog_35996_Content_95 = {
    Text = "Huh…… tidak buruk, tinktur-tinktur itu cukup berguna. Seluruh potensi tersembunyi dalam tubuhnya telah meledak keluar."
  },
  AvgDialog_35996_Content_96 = {
    Text = "Albino menjulurkan lidah ular panjangnya, dengan santai menjilati bersih semua darah di wajahnya."
  },
  AvgDialog_35996_Content_97 = {
    Text = "Mangsa sudah tumbuh dewasa. Sudah waktunya melapor kepada Tuan Ketua kita."
  },
  AvgDialog_35996_Content_98 = {
    Text = "Dia memungut buku catatan medis di kakinya, lalu pergi dengan santai."
  },
  AvgDialog_35997_Content_1 = {
    Text = "Kucing Mengetahui Segalanya"
  },
  AvgDialog_35997_Content_10 = {
    Text = "Cih, untuk menghadapi ikan-ikan teri seperti kalian, aku dan Brown saja sudah cukup."
  },
  AvgDialog_35997_Content_11 = {
    Text = "Apa katamu?!"
  },
  AvgDialog_35997_Content_12 = {
    Text = "Mike Kecil melambaikan tangan, dan anak-anak yang ribut langsung terdiam."
  },
  AvgDialog_35997_Content_13 = {
    Text = "Kalian sudah paham aturannya, kan? Jika kau kalah dari kami, kau harus menyerahkan kekuasaan atas Jalan Camberwell."
  },
  AvgDialog_35997_Content_14 = {
    Text = "—Selamanya."
  },
  AvgDialog_35997_Content_15 = {
    Text = "Jangan banyak omong, mau berkelahi ayo cepat maju!"
  },
  AvgDialog_35997_Content_16 = {
    Text = "Cit cit cit!"
  },
  AvgDialog_35997_Content_17 = {
    Text = "Bagus, sekarang aku resmi mengumumkan, \"Pertempuran Camberwell\" ke-13 resmi dimulai.\nSaudara-saudara——"
  },
  AvgDialog_35997_Content_18 = {
    Text = "<Big:Serbuuu!!>"
  },
  AvgDialog_35997_Content_2 = {
    Text = "Alam Cermin Buatan: Jalan Camberwell, Distrik Timur"
  },
  AvgDialog_35997_Content_20 = {
    Text = "Aduh! Sakit sakit sakit... Mereka terlalu banyak..."
  },
  AvgDialog_35997_Content_21 = {
    Text = "<Shake:Cit……>"
  },
  AvgDialog_35997_Content_22 = {
    Text = "Hmph! Siapa suruh kamu bikin masalah di mana-mana, sekarang tahu hebatnya kami kan!"
  },
  AvgDialog_35997_Content_23 = {
    Text = "Semuanya serbu, kemenangan ada di depan mata——"
  },
  AvgDialog_35997_Content_24 = {Text = "Meong~"},
  AvgDialog_35997_Content_25 = {
    Text = "Teriakan penuh amarah yang bercampur nada kekanakan memecah pertempuran kecil di depan mata."
  },
  AvgDialog_35997_Content_26 = {
    Text = "Tidak boleh menindas Jenkins meow!"
  },
  AvgDialog_35997_Content_27 = {
    Text = "Ku... kucing? Bukan, itu Kak Mason?!"
  },
  AvgDialog_35997_Content_29 = {
    Text = "Sebelum sempat bereaksi, wajah si kecil Mike sudah bertambah tiga goresan merah."
  },
  AvgDialog_35997_Content_3 = {
    Text = "Angin dingin yang menyayat bertiup melewati, menyapu dedaunan kering yang berguguran."
  },
  AvgDialog_35997_Content_31 = {
    Text = "<BigShake:Huwaaaaaa!!>"
  },
  AvgDialog_35997_Content_32 = {
    Text = "Anak-anak berhamburan melarikan diri. Tangisan memekakkan telinga, bergema hingga ke sudut gang yang tak diperhatikan siapa pun."
  },
  AvgDialog_35997_Content_33 = {
    Text = "Tak disangka ada 24 yang seperti kucing… Nona Mason, mau keluar untuk melihatnya?"
  },
  AvgDialog_35997_Content_34 = {
    Text = "Tak ada yang merespons permintaanmu. Di tengah kekacauan tadi, Mason entah kapan sudah menghilang tanpa jejak."
  },
  AvgDialog_35997_Content_35 = {
    Text = "Nona Mason...? Pergi pun tidak pamit dulu."
  },
  AvgDialog_35997_Content_36 = {Text = "Slurp."},
  AvgDialog_35997_Content_37 = {
    Text = "Sensasi basah terasa di sisi wajahmu."
  },
  AvgDialog_35997_Content_38 = {
    Text = "Kamu membalikkan kepala dengan tidak percaya, hanya untuk melihat \"24\" menggantung di tubuhmu seperti boneka raksasa, tersenyum manja ke arahmu."
  },
  AvgDialog_35997_Content_39 = {
    Text = "Miao, miaoo?"
  },
  AvgDialog_35997_Content_4 = {
    Text = "Mike Kecil dan sekelompok anak-anak berdiri di ujung gang. Dia berkacak pinggang dengan ekspresi sangat serius."
  },
  AvgDialog_35997_Content_40 = {Text = "...?"},
  AvgDialog_35997_Content_41 = {
    Text = "Snif snif... ada tikus miao!"
  },
  AvgDialog_35997_Content_43 = {
    Text = "Cit cit cit@3!"
  },
  AvgDialog_35997_Content_44 = {
    Text = "Teriakan melengking membelah langit. Kalian menunduk mengikuti suara itu, dan terlihat \"24\" sudah menggigit Cokelat di mulutnya."
  },
  AvgDialog_35997_Content_45 = {
    Text = "<BigShake:Cit cit cit cit cit aaaaaa!>"
  },
  AvgDialog_35997_Content_46 = {
    Text = "Brown berusaha keras meliuk-liukkan tubuh lenturnya, kumisnya bergetar dengan cepat."
  },
  AvgDialog_35997_Content_48 = {
    Text = "Ce-cepat, lihat itu apa?"
  },
  AvgDialog_35997_Content_49 = {
    Text = "Jenkins dengan terampil memungut pecahan cermin dari tanah dan memantulkan cahayanya ke dinding di seberang."
  },
  AvgDialog_35997_Content_5 = {
    Text = "Tap. Tap. Tap."
  },
  AvgDialog_35997_Content_50 = {
    Text = "Seketika, bercak cahaya yang bergetar hebat muncul di dinding batu, berhasil menarik perhatian \"24\"."
  },
  AvgDialog_35997_Content_51 = {
    Text = "Berkilau-kilau miaoo!"
  },
  AvgDialog_35997_Content_52 = {
    Text = "\"24\" melesat pergi dengan cepat, meninggalkan Cokelat yang terus terisak di tempat."
  },
  AvgDialog_35997_Content_53 = {
    Text = "Hiks hiks cit..."
  },
  AvgDialog_35997_Content_54 = {
    Text = "Haah. Sejak menemui dokter gadungan itu, kondisi kakakku semakin parah saja."
  },
  AvgDialog_35997_Content_55 = {
    Text = "Dokter gadungan? Maksudmu Dokter Bernard?"
  },
  AvgDialog_35997_Content_56 = {
    Text = "Memangnya siapa lagi kalau bukan dia. \"Dokter ajaib\" lah, \"Penyelamat orang miskin di distrik timur\" lah, cih!"
  },
  AvgDialog_35997_Content_57 = {
    Text = "Mana ada makan siang gratis di dunia ini, pasti dia punya niat buruk..."
  },
  AvgDialog_35997_Content_58 = {
    Text = "Dokter Bernard orang baik miao!"
  },
  AvgDialog_35997_Content_59 = {
    Text = "\"24\" yang tadinya masih mengejar bercak cahaya tiba-tiba menjulurkan kepalanya dari balik Jenkin."
  },
  AvgDialog_35997_Content_6 = {
    Text = "Gadis itu melangkah mendekat dengan langkah yang mantap, angin meniup jubah compang-campingnya."
  },
  AvgDialog_35997_Content_60 = {
    Text = "Iya iya iya, dia baik sekali, dia dokter paling hebat sedunia."
  },
  AvgDialog_35997_Content_61 = {
    Text = [[
Jenkin dengan terampil mengelus rambut "24".
"24" menyipitkan matanya, tampak sangat menikmatinya.]]
  },
  AvgDialog_35997_Content_62 = {
    Text = "Jenkin kecil juga orang baik, miauu."
  },
  AvgDialog_35997_Content_63 = {
    Text = "Gejala... ehm, aneh seperti ini pada Nona Mason pertama kali muncul sejak kapan?"
  },
  AvgDialog_35997_Content_64 = {
    Text = "Kira-kira setelah tiga atau empat kali menemui dokter gadungan itu. Suatu hari dia tiba-tiba bilang padaku bahwa sebenarnya dia adalah seekor ikan kod perak."
  },
  AvgDialog_35997_Content_65 = {
    Text = "Setelah itu dia bahkan menyusun rencana untuk menghancurkan restoran fish and chips, katanya untuk menyelamatkan teman-teman sebangsanya..."
  },
  AvgDialog_35997_Content_66 = {
    Text = "<Gray:Begitu rupanya. Sebelumnya terlalu percaya pada dewan peninjauan, sampai mengabaikan masalah kualifikasi dokternya sendiri.>"
  },
  AvgDialog_35997_Content_67 = {
    Text = "<Gray:Orang ini bisa jadi sama seperti Dokter Miller, keduanya adalah antek Asosiasi Pematung...>"
  },
  AvgDialog_35997_Content_68 = {
    Text = "Ngantuk sekali, huaaah..."
  },
  AvgDialog_35997_Content_69 = {
    Text = "\"24\" merentangkan kedua lengannya, melakukan peregangan panjang, lalu dengan sangat alami bersandar di bahu Jenkin."
  },
  AvgDialog_35997_Content_7 = {
    Text = "Kau tetap datang sesuai janji. Sendirian?"
  },
  AvgDialog_35997_Content_70 = {
    Text = "Grrr grrr..."
  },
  AvgDialog_35997_Content_71 = {
    Text = "Dia tertidur."
  },
  AvgDialog_35997_Content_72 = {
    Text = "Benar-benar mengeluarkan suara mendengkur seperti kucing... sama seperti kucing-kucing di kampus Misagar."
  },
  AvgDialog_35997_Content_73 = {
    Text = "Kamu dengan penasaran berjongkok di depan \"24\"."
  },
  AvgDialog_35997_Content_74 = {
    Text = "Sinar matahari turun merata, mewarnai bulu-bulu halus di wajahnya menjadi keemasan."
  },
  AvgDialog_35997_Content_75 = {
    Text = "Hei, kenapa kamu tersenyum!"
  },
  AvgDialog_35997_Content_76 = {
    Text = "Dia terlihat sangat bahagia sekarang, benar-benar seperti anak kucing yang tanpa beban."
  },
  AvgDialog_35997_Content_78 = {
    Text = "Kakak pernah bilang dulu, hidup ini terlalu berat. Kalau bisa bereinkarnasi, dia ingin jadi seekor kucing."
  },
  AvgDialog_35997_Content_79 = {
    Text = "Jenkin berkata, lalu tiba-tiba mengeluarkan sehelai pita merah dari sakunya. Ini adalah pita yang sering dipakai Mason, di ujungnya tergantung sebuah lonceng kecil yang berkarat."
  },
  AvgDialog_35997_Content_8 = {Text = "Cit cit!"},
  AvgDialog_35997_Content_80 = {
    Text = "Tenang saja. Entah kucing atau ikan kod perak, semuanya tetap kakakku."
  },
  AvgDialog_35997_Content_81 = {
    Text = "Tapi, supaya kamu tidak hilang, aku harus mengikatkan lonceng padamu."
  },
  AvgDialog_35997_Content_82 = {
    Text = [[
Jenkin dengan lembut mengikatkan pita di pergelangan tangan "24".
"24" masih dalam mimpi, hanya sedikit mengerutkan hidungnya.]]
  },
  AvgDialog_35997_Content_83 = {
    Text = "Ini kurebut dari si kecil Mac dan teman-temannya, pakai yang benar ya."
  },
  AvgDialog_35997_Content_84 = {
    Text = "Sinar matahari sore mengalir perlahan melewati kalian berdua bagai waktu yang meluap. Jenkin memandang bayangan rumah yang belang-belang terpotong cahaya matahari di seberang, lalu perlahan memejamkan mata."
  },
  AvgDialog_35997_Content_85 = {
    Text = "Kakak sangat sibuk. Harus merawat aku dan Brown, sekaligus bekerja beberapa pekerjaan paruh waktu, seperti mesin yang tidak pernah rusak."
  },
  AvgDialog_35997_Content_86 = {
    Text = "Sekarang mesin itu akhirnya tumbang, giliran aku yang merawatnya."
  },
  AvgDialog_35997_Content_87 = {
    Text = "Dia membutuhkanku."
  },
  AvgDialog_35997_Content_9 = {
    Text = "Tidak buruk, berani datang sendirian. Kau adalah lawan yang patut dihormati."
  },
  AvgDialog_35999_Content_1 = {
    Text = "Ikatan Kutukan Pahit"
  },
  AvgDialog_35999_Content_10 = {
    Text = "Aku sudah mengingat semuanya……"
  },
  AvgDialog_35999_Content_2 = {
    Text = "Kenangan membanjir masuk bersama cahaya bintang yang berserakan."
  },
  AvgDialog_35999_Content_4 = {
    Text = "Kenangan-kenangan yang sengaja diciptakan dan dicabik-cabik secara paksa membanjiri benak Mason, lalu surut dengan cepat bagaikan ombak."
  },
  AvgDialog_35999_Content_5 = {
    Text = "Hingga akhirnya, dia tiba di kaki gunung bersalju, di depan pintu masuk gua yang gelap gulita."
  },
  AvgDialog_35999_Content_6 = {
    Text = "Mengikuti aliran sungai di bawah kaki, dia bisa mencapai sarang sang raksasa yang tertidur lelap."
  },
  AvgDialog_35999_Content_7 = {
    Text = "Dung dung. Dung dung."
  },
  AvgDialog_35999_Content_8 = {
    Text = "Itu adalah detak jantung yang terdengar seperti jam tua, detak jantung milik bersama—miliknya dan sang raksasa."
  },
  AvgDialog_35999_Content_9 = {
    Text = "Aku mengerti sekarang……"
  },
  AvgDialog_36227_Content_1 = {
    Text = "\"Pseudo-dewa\"benar-benar terlepas dari induknya yang rapuh namun gigih, Murphy terlempar dari ketinggian dan akhirnya jatuh dengan keras di atas dek."
  },
  AvgDialog_36227_Content_10 = {Text = "\"Perak\"."},
  AvgDialog_36227_Content_11 = {
    Text = "Murphy masih hidup, namun di dalam tubuhnya terdapat Perak yang telah terpisah — ini tidak sesuai dengan prinsip dasar yang kamu pelajari di kelas."
  },
  AvgDialog_36227_Content_12 = {
    Text = "Namun, situasi tidak memungkinkanmu berpikir panjang, dan hampir secara naluriah, kamu menggenggam tangan Murphy."
  },
  AvgDialog_36227_Content_13 = {
    Text = "Kunci perak yang tergantung di dada bergetar dan mengeluarkan suara gemetar, dari tangan mereka yang saling bertautan memancarkan cahaya perak yang begitu menyilaukan hingga menerangi setiap sudut, menelan semua orang."
  },
  AvgDialog_36227_Content_14 = {
    Text = "Waktu menjadi tak terbatas dalam cahaya, jiwa berulang kali dimampatkan dan dilipat dalam waktu yang tiada akhir."
  },
  AvgDialog_36227_Content_15 = {
    Text = "Dalam momen abadi ini, rasa sakit selalu menyertaimu, berusaha membuatmu melepaskan Perak yang menembus telapak tanganmu."
  },
  AvgDialog_36227_Content_16 = {
    Text = "——Kamu menolak. Membiarkan rasa sakit yang hebat tanpa ampun menyerang ruang kesadaranmu, jaringan di dalam rongga kepalamu hancur oleh Gnosis yang kacau, membuat darah bercampur gumpalan keluar dari mulut, hidung, dan telingamu."
  },
  AvgDialog_36227_Content_17 = {
    Text = "Kamu selalu erat memegang jiwa Murphy."
  },
  AvgDialog_36227_Content_18 = {
    Text = "Cahaya runtuh menuju titik asal, suara seruling aneh yang membuatmu sangat mengantuk terdengar kembali, dengan paksa menarik perhatianmu."
  },
  AvgDialog_36227_Content_19 = {
    Text = "Kamu merasakan tanganmu menjadi kosong."
  },
  AvgDialog_36227_Content_2 = {
    Text = "Seluruh tulang di tubuh patah saat jatuh, rongga dada terbuka lebar akibat luka yang diciptakan sendiri, kemudian hancur berantakan setelah ditabrak oleh \"Pseudo-Dewa\" yang muncul dari dalam tubuh."
  },
  AvgDialog_36227_Content_20 = {
    Text = "Setelah cahaya perak menghilang, di dek di hadapan kalian tidak ada apa pun, hanya menyisakan noda darah di mana-mana."
  },
  AvgDialog_36227_Content_21 = {Text = "Penjaga!?"},
  AvgDialog_36227_Content_22 = {
    Text = "Ramona gemetar saat menghapus darah yang keluar dari sudut matamu, tetapi semakin ia menghapus, semakin kotor, hingga wajahmu penuh dengan bekas darah."
  },
  AvgDialog_36227_Content_23 = {Text = "Murphy…"},
  AvgDialog_36227_Content_24 = {
    Text = "Keterkejutan dan rasa penasaran Ramona baru saja terlintas di ujung bibirnya ketika dari kejauhan, di bagian depan kapal, terdengar suara rendah yang dalam. Suara itu seperti gumaman makhluk dari Jurang dalam tidurnya, membawa aura yang tidak menyenangkan."
  },
  AvgDialog_36227_Content_25 = {
    Text = "Kalian berdua tanpa sadar menoleh bersamaan, hanya untuk melihat makhluk aneh bernama \"Miryam\" yang hampir fanatik menatap sang Dewa. Dia berlutut di haluan kapal, membuka kedua tangannya ke arah dewa palsu itu."
  },
  AvgDialog_36227_Content_26 = {
    Text = "Dan ribuan tangan hitam itu pun membuka pelukan mereka ke arahnya. Dengan lembut, mereka menggenggam pinggangnya dan mengangkat penganut yang setia ini ke arah mulut mereka."
  },
  AvgDialog_36227_Content_27 = {
    Text = "——<Red:Kacha>."
  },
  AvgDialog_36227_Content_28 = {
    Text = "Detik berikutnya, suara kunyahan dan menelan terdengar bergantian."
  },
  AvgDialog_36227_Content_29 = {
    Text = "Seolah-akhirnya terbebas dari batas ketakutan yang tak dikenal, bayi baru lahir itu mengeluarkan suara puas yang mirip dengan dengkuran. Seolah-olah sedang mencerna \"Miryam\", hidangan lezat yang langka."
  },
  AvgDialog_36227_Content_3 = {
    Text = "Ombak terus-menerus menerjang dek, menyapu genangan darah di bawah tubuhnya satu demi satu, seolah-olah ingin sepenuhnya menghapus jejak keberadaannya."
  },
  AvgDialog_36227_Content_30 = {
    Text = "\"Bayi baru lahir\" di dalam kokon hitam transparan, mirip dengan embrio primata raksasa yang rapuh. Anggota tubuh-Nya berkedut canggung, seolah-olah mencari arah untuk tumbuh ——"
  },
  AvgDialog_36227_Content_31 = {
    Text = [[
Waktu hingga Selaras
tersisa: <Red:0> menit]]
  },
  AvgDialog_36227_Content_4 = {
    Text = "Luka seperti ini... kami tidak bisa mengatasinya."
  },
  AvgDialog_36227_Content_5 = {
    Text = [[
Murphy masih bergumam dengan bibir bawahnya, namun pandangannya mulai mengabur. 
 Ramona tidak tahan melihat pemandangan mengerikan ini. Dia menggigit giginya dan menatap ke arah "dewa palsu"itu.]]
  },
  AvgDialog_36227_Content_6 = {
    Text = "Harus menghentikan-Nya. Inti Clades sebesar ini, jika kita tidak bisa menyelesaikannya di kapal dan membiarkan-Nya mencapai daratan… akibatnya akan tak terbayangkan."
  },
  AvgDialog_36227_Content_7 = {
    Text = "Penjaga, kita harus bertindak. Bahkan demi Murphy."
  },
  AvgDialog_36227_Content_8 = {
    Text = "Tunggu sebentar! Mungkin aku punya cara."
  },
  AvgDialog_36227_Content_9 = {
    Text = "Kamu menatap dengan intens jaringan yang hancur di bawah tulang rusuk Murphy, yakin bahwa kamu melihat sesuatu itu —"
  },
  AvgDialog_36276_Content_1 = {
    Text = "Bagian luarnya... ternyata bukan tubuh asli-Nya?!"
  },
  AvgDialog_36276_Content_2 = {
    Text = "Inilah apa yang dicari Miryam. Dewa yang dia dambakan, yang dapat membawa kebangkitan masa lalu baginya…"
  },
  AvgDialog_36276_Content_3 = {
    Text = "Selanjutnya tidak boleh ceroboh, sedikit pun tidak boleh lengah!"
  },
  AvgDialog_36276_Content_4 = {
    Text = "Hal jelek ini benar-benar terbangun... Aku bisa merasakannya."
  },
  AvgDialog_36277_Content_1 = {
    Text = "Penjaga Rahasia!"
  },
  AvgDialog_36277_Content_2 = {
    Text = "Tulu! Akhirnya kamu datang."
  },
  AvgDialog_36277_Content_3 = {
    Text = "Mengatasi musuh di sisi Elton memakan waktu cukup lama… <Small: Tunggu, Murphy?>"
  },
  AvgDialog_36277_Content_4 = {
    Text = "Mata Tulu meluncur melewati \"Anak Suci\" dan akhirnya tertuju pada Murphy. Setelah memiliki tubuh Pembangun, tentakel di bagian bawah roknya bergoyang-goyang tak menentu di udara."
  },
  AvgDialog_36277_Content_5 = {
    Text = "...Kekuatan-Nya berasal dari sumber yang sama dengan milikku, yang berarti Dia juga adalah rakyatku. Meskipun aku tidak bisa langsung memerintah-Nya, kekuasaan kerajaanku pernah dihormati oleh ribuan rakyat Lemuria, dan pasti tidak dapat ditentang oleh tiruan dewa."
  },
  AvgDialog_36277_Content_6 = {
    Text = "Kesempatan ini hanya sekali, manfaatkan kekuasaan Tuan Yu Luo Yan… turunkan hukuman ilahi atas-Nya!"
  },
  AvgDialog_37962_Content_1 = {
    Text = "Berikutnya yang akan diuji adalah: Efek layar - merah terus-menerus"
  },
  AvgDialog_37962_Content_10 = {
    Text = "Berikutnya yang akan diuji adalah: Efek Layar - Cahaya Bintang"
  },
  AvgDialog_37962_Content_14 = {Text = "Selesai"},
  AvgDialog_37962_Content_15 = {
    Text = "Berikutnya yang akan diuji adalah: Efek Layar - Lampu"
  },
  AvgDialog_37962_Content_19 = {Text = "Selesai"},
  AvgDialog_37962_Content_20 = {
    Text = "Berikutnya yang akan diuji adalah: Tipe teks berjalan nomor 9"
  },
  AvgDialog_37962_Content_21 = {
    Text = [[
Musim semi, fajar adalah yang paling indah. Puncak gunung yang perlahan berubah menjadi putih mulai sedikit terang, dan awan tipis berwarna ungu melayang di atasnya. 
Musim panas adalah malam. Saat bulan bersinar sudah pasti luar biasa, tetapi pada malam tanpa bulan yang gelap, ada kunang-kunang yang beterbangan. Jika turun hujan, itu akan menambah suasana. 
Musim gugur adalah senja. Matahari terbenam menyinari, memantul di lereng gunung, burung gagak kembali ke sarang, tiga, empat, dua ekor terbang melewati, menambah kesedihan. Kadang-kadang kita melihat bayangan angsa kecil, berbaris terbang di langit jauh, sangat penuh dengan suasana. Apalagi setelah matahari terbenam, masih ada suara angin dan serangga bernyanyi. 
Musim dingin adalah pagi hari. Saat salju turun tidak perlu diragukan lagi, kadang-kadang warna embun beku yang putih, bahkan jika tidak ada salju atau embun beku, udara dingin yang menusuk membuat kita segera menyalakan api di tungku, membawa arang yang menyala melewati koridor, juga sangat sesuai dengan suasana; hanya saja saat tengah hari, bara di dalam tungku perlahan ditutupi abu putih, maka tidak ada lagi yang bisa dinikmati.]]
  },
  AvgDialog_37962_Content_22 = {Text = "Selesai"},
  AvgDialog_37962_Content_5 = {Text = "Selesai"},
  AvgDialog_37962_Content_6 = {
    Text = "Berikutnya yang akan diuji adalah: Efek pembesaran ilustrasi"
  },
  AvgDialog_37962_Content_7 = {
    Text = "Ilustrasi diperbesar (1.5, 0.3)"
  },
  AvgDialog_37962_Content_8 = {
    Text = "Ilustrasi diperbesar dan direstorasi"
  },
  AvgDialog_37962_Content_9 = {
    Text = "Tes selesai, jiu~"
  },
  AvgDialog_38725_Content_1 = {
    Text = "Cahaya biru yang redup menyelimutimu, menyapu bersih seluruh kelelahan dan rasa sakit dari tubuhmu."
  },
  AvgDialog_38725_Content_2 = {
    Text = "Dewa Bapa menurunkan \"Berkah\" kepadamu."
  },
  AvgDialog_38725_Content_3 = {
    Text = "Uskup Salvadore!"
  },
  AvgDialog_38725_Content_4 = {
    Text = "Kau adalah utusan yang pucat, api yang mengusir kegelapan."
  },
  AvgDialog_38725_Content_5 = {
    Text = "Kau akan mengakhiri semua penderitaan ini, dan aku akan memberikanmu segala bantuan."
  },
  AvgDialog_38727_Content_1 = {
    Text = "Simbol Berdarah"
  },
  AvgDialog_38727_Content_10 = {
    Text = "Memang, mungkin… sekte sesat?"
  },
  AvgDialog_38727_Content_11 = {
    Text = "Tak terhitung gambaran bermunculan di benakmu—gadis yang menggenggam belati, wanita berkerudung hitam, ruangan di kedalaman Sanatorium Lai yang tidak boleh dibuka selamanya…"
  },
  AvgDialog_38727_Content_12 = {
    Text = "Sebenarnya berapa banyak lagi organisasi seperti <Yellow:Penerjun Laut> dan <Yellow:Gereja Lentera> yang ada di dunia ini, dan berapa banyak orang yang harus menjadi korban mereka?"
  },
  AvgDialog_38727_Content_13 = {
    Text = [[
Yang Mulia Uskup, apakah Edward pernah mengatakan sesuatu kepadamu?
Entah itu agama lain, kepercayaan kuno, atau bahkan legenda rakyat sekalipun.]]
  },
  AvgDialog_38727_Content_14 = {
    Text = "Salvador meletakkan sapu tangannya. Dia berbalik menghadapmu, meskipun kedua matanya tertutup perban, kamu tetap bisa merasakan tatapannya."
  },
  AvgDialog_38727_Content_15 = {
    Text = "Jika benar begitu, apakah kalian berencana menyelidiki hal ini?"
  },
  AvgDialog_38727_Content_16 = {
    Text = "Ya. Aku… pernah berurusan dengan organisasi serupa, aku tahu betapa berbahayanya mereka.\nJika memungkinkan, aku tidak ingin melihat lebih banyak korban berjatuhan."
  },
  AvgDialog_38727_Content_17 = {
    Text = [[
Kau memiliki jiwa yang cemerlang, %player%, hangat, kuat, dan mengagumkan.
Semoga cahaya Bapa Ilahi menyinarimu, sebagaimana ia menyinari semua anggota <Yellow:Misage>.]]
  },
  AvgDialog_38727_Content_18 = {
    Text = "Bagaimana kau tahu—"
  },
  AvgDialog_38727_Content_19 = {
    Text = "Uskup sebelumnya adalah temanku, ia memimpin paroki Katedral selama puluhan tahun dan mengetahui banyak hal."
  },
  AvgDialog_38727_Content_2 = {
    Text = "Pintu kayu perlahan menutup, menghalangi teriakan pedagang dan hiruk-pikuk kerumunan di luar. Dalam keheningan, tanpa sadar kamu meringankan napasmu."
  },
  AvgDialog_38727_Content_20 = {
    Text = "Aku akan berusaha membantu kalian, tapi aku khawatir apa yang kuketahui tidak jauh lebih banyak dari kalian."
  },
  AvgDialog_38727_Content_21 = {
    Text = "Sebenarnya, Edward bukanlah korban pertama dari aliran keagamaan misterius ini."
  },
  AvgDialog_38727_Content_22 = {
    Text = "Setengah tahun lalu, seorang pemuda bernama Philip dari paroki Katedral dijatuhi hukuman mati karena membunuh istrinya."
  },
  AvgDialog_38727_Content_23 = {
    Text = [[
Saat ia baru ditangkap, aku mengunjunginya atas undangan kepala penjara.
Ia sangat pucat, sangat kurus, dan menolak berkomunikasi dengan siapa pun.]]
  },
  AvgDialog_38727_Content_24 = {
    Text = "Aku menemaninya duduk seharian, dan saat aku hendak pergi, ia mengucapkan satu-satunya kalimat hari itu."
  },
  AvgDialog_38727_Content_25 = {
    Text = "\"Apakah kau melihatnya, <Red:darah> hitam itu?\""
  },
  AvgDialog_38727_Content_26 = {
    Text = "Sebelum eksekusi dilaksanakan, ia bunuh diri."
  },
  AvgDialog_38727_Content_27 = {
    Text = "Seluruh ruangan dipenuhi darah, di lantai, dinding, langit-langit — hanya berdiri di sana saja sudah cukup membuat orang merasa sesak napas. Di balik lapisan darah yang tebal, aku menemukan sebuah simbol yang menyeramkan."
  },
  AvgDialog_38727_Content_28 = {
    Text = "Simbol itu sangat tipis dan kecil, seperti digoreskan dengan kuku seseorang. Jika bukan karena darah yang meresap ke dalam celahnya, mungkin tak seorang pun akan menyadarinya."
  },
  AvgDialog_38727_Content_29 = {
    Text = "Di samping simbol itu, ada satu goresan lain yang lebih samar."
  },
  AvgDialog_38727_Content_3 = {
    Text = "Yang Mulia Uskup, airnya sudah datang."
  },
  AvgDialog_38727_Content_30 = {
    Text = "Goresan itu tidak beraturan, seolah orang yang mengukirnya sudah kehabisan tenaga, atau sudah kehilangan kesadaran. Dengan bimbingan Bapa Ilahi, aku berhasil membacanya — itu adalah sebuah kata."
  },
  AvgDialog_38727_Content_31 = {
    Text = "<Red:Pemurnian>"
  },
  AvgDialog_38727_Content_32 = {
    Text = "Aliran itu sangat berhati-hati dan pandai menyembunyikan diri. Jika bukan karena Edward menyebut \"pemurnian\" hari ini, aku mungkin tidak akan pernah tahu bahwa ia sudah jatuh ke dalam cengkeraman mereka."
  },
  AvgDialog_38727_Content_33 = {
    Text = "Simbol itu, apakah kau masih ingat bentuknya? Mungkin Misage memiliki catatan mengenai mereka."
  },
  AvgDialog_38727_Content_34 = {
    Text = "Tentu saja, ulurkan tanganmu."
  },
  AvgDialog_38727_Content_35 = {
    Text = "Ia mengulurkan satu jari dan dengan lembut menggambar sebuah simbol sederhana di telapak tanganmu."
  },
  AvgDialog_38727_Content_36 = {Text = "Ini……!"},
  AvgDialog_38727_Content_37 = {
    Text = "Kamu mengeluarkan buku catatan dari saku dan dengan cepat menyalin pola yang digambar Salvado di atasnya."
  },
  AvgDialog_38727_Content_38 = {
    Text = "Tuan, ada apa? Itu simbol apa?"
  },
  AvgDialog_38727_Content_39 = {
    Text = "Segitiga terbalik, dengan satu titik di tengah—"
  },
  AvgDialog_38727_Content_4 = {
    Text = "Terima kasih, Augier."
  },
  AvgDialog_38727_Content_40 = {
    Text = "Ini adalah simbol Gereja Lentera."
  },
  AvgDialog_38727_Content_41 = {Text = "BRAK!"},
  AvgDialog_38727_Content_42 = {
    Text = "Pintu aula suci terbanting terbuka. Sofia dengan rambut sedikit berantakan, terengah-engah, berdiri di bawah sinar matahari sambil berpegangan pada pintu dan berteriak kepada kalian."
  },
  AvgDialog_38727_Content_43 = {
    Text = "Uskup Salvado, gawat! Orang-orang di luar—"
  },
  AvgDialog_38727_Content_44 = {
    Text = "Jangan menghalangi jalan, biarkan kami masuk!"
  },
  AvgDialog_38727_Content_45 = {
    Text = "Sebuah tangan mendorong Sofia dengan kasar, teriakan dan makian seketika memenuhi aula suci."
  },
  AvgDialog_38727_Content_46 = {
    Text = "Lebih dari sepuluh warga berdesakan masuk, ada yang membawa sapu, ada yang membawa penggilas adonan, salah satu dari mereka mengayunkan tinjunya yang masih ada bekas gigitan Edward."
  },
  AvgDialog_38727_Content_47 = {
    Text = "Suruh bajingan Edward itu keluar! Kami mau menuntut pertanggungjawaban darinya!"
  },
  AvgDialog_38727_Content_5 = {
    Text = "Salvador mengeluarkan sapu tangan putih bersih dari sakunya, membasahinya di ember air yang dibawa Augier, lalu perlahan-lahan menyeka debu yang menempel di tubuh Edward."
  },
  AvgDialog_38727_Content_6 = {
    Text = "Kain yang sedikit basah menyapu dada, mengarahkan pandanganmu ke tulang rusuk yang menonjol satu per satu—dia terlalu kurus, kurus seolah baru saja melewati kelaparan besar."
  },
  AvgDialog_38727_Content_7 = {
    Text = "<Small:…Dosa…darah…penyucian…>"
  },
  AvgDialog_38727_Content_8 = {
    Text = "Pertumpahan darah, dosa… Meskipun kamu tidak begitu familiar dengan <Blue:《Kitab Suci》> milik <Blue:Takhta Suci Kehidupan>, konsep yang cukup berdarah ini sangat tidak sesuai dengan kesanmu terhadap agama ini."
  },
  AvgDialog_38727_Content_9 = {
    Text = "\"Tanah suci tanpa dosa\" ini, dan juga \"penyucian\"… sepertinya bukan berasal darierta《Kitab Suci》?"
  },
  AvgDialog_38729_Content_1 = {
    Text = "Nyalakan harapan putih"
  },
  AvgDialog_38729_Content_10 = {
    Text = "Hapuskanlah rasa sakit mereka, tenangkanlah hati mereka."
  },
  AvgDialog_38729_Content_100 = {
    Text = "Memberikan pengampunan kepada para pendosa, menganugerahkan mereka \"Berkah\"…… Sudah bertahun-tahun, kau benar-benar tidak berubah sama sekali ya, Uskup Salvado."
  },
  AvgDialog_38729_Content_101 = {
    Text = "Tiang pembakaran tidak bisa mengubahmu, bangkit dari kematian pun tidak bisa mengubahmu. Kapan kau baru mau melihat kenyataan? Mungkin——"
  },
  AvgDialog_38729_Content_102 = {
    Text = "Tangannya menunjuk ke udara dari kejauhan, seolah menyentuh sesuatu yang tak terlihat dari jarak jauh."
  },
  AvgDialog_38729_Content_103 = {
    Text = [[
<Yellow:Penjaga Rahasia> yang memiliki jiwa pucat namun hangat seperti dalam ramalan itu, bisa membawa lebih banyak variabel.
Menurutmu, apakah {Male=dia,Female=dia} bersedia bergabung dengan kita?]]
  },
  AvgDialog_38729_Content_104 = {
    Text = "Seekor anjing raksasa muncul dari bayang-bayang di samping wanita itu, tubuhnya yang terdistorsi ternyata memiliki kemiripan dengan Sophia yang bermutasi. Mendengar perkataan wanita itu, ia mendengus, seolah merespons."
  },
  AvgDialog_38729_Content_105 = {
    Text = "Benar juga, hari esok selalu merupakan hari yang baru."
  },
  AvgDialog_38729_Content_106 = {
    Text = "Ayo pergi, sayangku. Jika ada kesempatan, kita akan bertemu mereka lagi."
  },
  AvgDialog_38729_Content_11 = {
    Text = "Tatapan orang-orang menjadi hampa, tubuh mereka semakin rileks. Kepanikan dan ketakutan tersapu bersih, digantikan oleh ketenangan dan kedamaian."
  },
  AvgDialog_38729_Content_12 = {
    Text = "Bebaskan mereka dari siksaan penderitaan, dan berikanlah kepada mereka \"Berkah\"."
  },
  AvgDialog_38729_Content_13 = {
    Text = "Cahaya bagai gelombang pasang menyebar ke segala arah, semua orang memejamkan mata, seolah tenggelam dalam kedamaian."
  },
  AvgDialog_38729_Content_14 = {
    Text = "Mentari hangat memandang ke bawah menyaksikan segalanya, semua tampak seperti biasa, hanya alun-alun yang berantakan menjadi bukti kegilaan yang baru saja terjadi."
  },
  AvgDialog_38729_Content_15 = {
    Text = [[
Lempengan batu berdenting pelan, lalu berubah menjadi bayangan tak kasat mata yang melebur ke dalam kegelapan malam.
Salvador merapikan pakaiannya dan berjalan ke sisi Sofia.]]
  },
  AvgDialog_38729_Content_16 = {
    Text = "……Kau seharusnya tidak menyelamatkanku."
  },
  AvgDialog_38729_Content_17 = {
    Text = "\"Siapa pun yang tersadar dari kesesatan, dapat kembali ke dalam pelukanku\"."
  },
  AvgDialog_38729_Content_18 = {
    Text = [[
"Karena kalian semua adalah anak-anakku, dan aku mencintai kalian semua".
Tapi kau salah, Uskup, dan Kitab Suci juga salah.]]
  },
  AvgDialog_38729_Content_19 = {
    Text = "Ada orang yang tidak akan pernah berubah."
  },
  AvgDialog_38729_Content_2 = {
    Text = "Lempengan batu terangkat kembali."
  },
  AvgDialog_38729_Content_20 = {
    Text = "Kau datang untuk apa?"
  },
  AvgDialog_38729_Content_21 = {
    Text = "Sofia, aku—"
  },
  AvgDialog_38729_Content_22 = {
    Text = "Diam! Membunuh kakakku dan ibuku belum cukup, kau masih mau datang ke makam mereka untuk pamer kemenanganmu?!"
  },
  AvgDialog_38729_Content_23 = {
    Text = "Aku datang untuk meminta maaf, aku tidak menyangka…"
  },
  AvgDialog_38729_Content_24 = {
    Text = "Sofia tertawa sinis."
  },
  AvgDialog_38729_Content_25 = {
    Text = "Apakah kau juga meminta maaf seperti ini kepada <Blue:Thompson>, setelah membunuh satu-satunya keluarganya, membunuh <Blue:Millie>?"
  },
  AvgDialog_38729_Content_26 = {
    Text = "Kau membuatku muak, Edward Bailey."
  },
  AvgDialog_38729_Content_27 = {
    Text = "Aku benar-benar menyesal, Sofia. Aku tahu aku tidak bisa mendapatkan pengampunanmu—"
  },
  AvgDialog_38729_Content_28 = {
    Text = "Kalau kau benar-benar menyesal, seharusnya kau tidak pergi mencari Uskup Salvador pada hari Thompson membunuhmu."
  },
  AvgDialog_38729_Content_29 = {
    Text = "Benar, aku tahu bagaimana kau bisa selamat, dasar pengecut. <Yellow:Lentera> yang memberitahuku."
  },
  AvgDialog_38729_Content_30 = {
    Text = "Memberimu \"<Yellow:Berkat>\" adalah keputusan paling bodoh yang pernah dibuat sang uskup. Kau seharusnya mati, Bailey, mati dalam siksaan."
  },
  AvgDialog_38729_Content_31 = {
    Text = "Aku juga tidak ingin begini, aku sudah mencoba mengendalikan diriku, aku sudah mencoba! Setelah uskup menyelamatkanku, aku setiap hari kembali melapor ke gereja, setiap minggu aku pergi ke rumah amal milik keluargamu untuk menjadi sukarelawan, kau masih ingat?"
  },
  AvgDialog_38729_Content_32 = {
    Text = "Aku ingin berubah menjadi lebih baik, aku benar-benar ingin. Orang dari Agro itulah yang bilang ini bisnis tanpa risiko, dia yang menyuruhku memperkenalkan seorang penjamin. Aku juga korban!"
  },
  AvgDialog_38729_Content_33 = {
    Text = "Sampai sekarang kau masih melempar tanggung jawab, sampai sekarang… kau belum pernah benar-benar bertobat."
  },
  AvgDialog_38729_Content_34 = {
    Text = "Dia mengeluarkan sebuah benda perak keputihan dari saku tersembunyi di roknya. Permukaan halusnya berkilau samar di bawah sinar matahari, mewarnai pantulan cahaya menjadi merah darah yang menyeramkan."
  },
  AvgDialog_38729_Content_35 = {Text = "Sophia…?"},
  AvgDialog_38729_Content_36 = {
    Text = "Bertobatlah."
  },
  AvgDialog_38729_Content_37 = {
    Text = [[
Ikutilah ajaran Sang Pembawa Lentera yang adil, sucikan dosa dari dalam jiwamu.
Hanya dengan begitu, pengampunan mungkin diperoleh.]]
  },
  AvgDialog_38729_Content_38 = {
    Text = "Apa dirimu?"
  },
  AvgDialog_38729_Content_39 = {
    Text = "Aku… aku adalah Edward…"
  },
  AvgDialog_38729_Content_4 = {
    Text = "Salvador mengangkat tangannya, darah mengalir tanpa henti dari tubuhnya, dari sekelilingnya menuju lempengan batu. Cahaya biru kembali mengalir mengikuti ukiran, terang dan redup silih berganti, bagai napas."
  },
  AvgDialog_38729_Content_40 = {
    Text = [[
Cermin berkilat sesaat, tatapan pemuda yang berlutut di tanah kembali linglung.
Dia gemetar mengangkat tongkat di tangannya, lalu menghantamkannya keras-keras ke tubuhnya sendiri.]]
  },
  AvgDialog_38729_Content_41 = {
    Text = "Aku tanya sekali lagi, kau ini apa?"
  },
  AvgDialog_38729_Content_42 = {
    Text = "Aku adalah pendosa."
  },
  AvgDialog_38729_Content_43 = {
    Text = "Dosa apa yang telah kau perbuat?"
  },
  AvgDialog_38729_Content_44 = {
    Text = "Aku serakah tanpa batas, aku memanjakan nafsu, aku membiarkan iblis mencemari jiwaku, lalu membawa penderitaan kepada orang-orang tak bersalah."
  },
  AvgDialog_38729_Content_45 = {
    Text = "Apa yang seharusnya kau lakukan?"
  },
  AvgDialog_38729_Content_46 = {
    Text = [[
Aku harus bertobat kepada mereka yang telah kusakiti, aku harus bertobat kepada para dewa.
Aku harus menerima hukuman cambuk, harus berdarah hingga dosa hitam mengalir keluar, demi memperoleh <Red:penyucian>.]]
  },
  AvgDialog_38729_Content_47 = {
    Text = "Penghakiman akan tiba, hanya jiwa yang murni yang dapat memasuki tanah suci tanpa dosa."
  },
  AvgDialog_38729_Content_48 = {
    Text = "<Red:Semoga lentera senantiasa menyala>."
  },
  AvgDialog_38729_Content_49 = {
    Text = "Sama sepertimu, meskipun telah menjalani dua kehidupan, kau tetap melakukan kesalahan yang sama."
  },
  AvgDialog_38729_Content_5 = {
    Text = "Dewa Bapa sang Pencipta, Sang Pembuat yang penuh belas kasih, dengarkanlah doaku."
  },
  AvgDialog_38729_Content_50 = {
    Text = "…Bagaimana kau bisa tahu?"
  },
  AvgDialog_38729_Content_51 = {
    Text = [[
Apakah itu penting?
Dosa kesombonganmu begitu berat, Uskup, jiwamu pasti sangat kotor.]]
  },
  AvgDialog_38729_Content_52 = {
    Text = "Katakan padaku, pendosa, mengapa kau tidak bertobat atas dosa-dosamu seperti yang kau khotbahkan?"
  },
  AvgDialog_38729_Content_53 = {
    Text = "…Karena itu bukan dosa."
  },
  AvgDialog_38729_Content_54 = {
    Text = "Ciptaan Bapa selalu menyimpan cahaya-Nya, setiap orang bisa terbutakan, dan begitu pula, setiap orang bisa menemukan kembali cahaya Bapa."
  },
  AvgDialog_38729_Content_55 = {
    Text = "Kita tidak bisa merampas seluruh kehidupan seseorang hanya karena perbuatannya sesaat."
  },
  AvgDialog_38729_Content_56 = {
    Text = "Kau berkata demikian, tapi sama sekali tidak pernah memikirkan orang-orang yang menjadi korban mereka."
  },
  AvgDialog_38729_Content_57 = {
    Text = "Saat para Edward itu menemukan kembali cahaya mereka, berapa banyak Milly yang harus dikorbankan untuk itu? Berapa banyak Olivia?"
  },
  AvgDialog_38729_Content_58 = {
    Text = "Dosa tetaplah dosa, kesalahan tetaplah kesalahan. Begitu dilakukan, tidak ada jalan kembali."
  },
  AvgDialog_38729_Content_59 = {
    Text = "Dia memandang ke arah kalian."
  },
  AvgDialog_38729_Content_6 = {
    Text = "Biru yang lembut menjulurkan akar-akar rapat ke segala arah dengan lempengan batu sebagai pusatnya, menembus kerumunan orang, mengusir sisa bau amis darah, meninggalkan aroma dupa yang samar."
  },
  AvgDialog_38729_Content_60 = {
    Text = "Bawalah aku pergi, serahkan aku kepada hukum kalian yang korup. Tapi ingatlah, hari penghakiman pasti akan tiba."
  },
  AvgDialog_38729_Content_61 = {
    Text = "Saat itu tiba, kalian semua akan diusir dari tanah suci yang tanpa dosa."
  },
  AvgDialog_38729_Content_62 = {
    Text = "Objek khusus sudah selesai diamankan, Penjaga Rahasia. Warga sipil yang terdampak juga sudah dikirim ke berbagai rumah sakit. Mereka bisa pulang setelah diperiksa dan dinyatakan baik-baik saja."
  },
  AvgDialog_38729_Content_63 = {
    Text = "Pernyataan resminya adalah ini merupakan insiden halusinasi massal akibat kebocoran gas beracun dari pabrik. Pemerintah kota akan meminta maaf secara terbuka besok dan memberikan sanksi kepada pihak-pihak terkait."
  },
  AvgDialog_38729_Content_64 = {
    Text = "Aku mengerti, terima kasih atas kerja keras kalian."
  },
  AvgDialog_38729_Content_65 = {
    Text = "Ini sudah menjadi tugas kami."
  },
  AvgDialog_38729_Content_66 = {
    Text = "Pria muda berseragam itu ragu-ragu sejenak, lalu berkata:"
  },
  AvgDialog_38729_Content_67 = {
    Text = "Bagaimana kau bisa melakukannya?"
  },
  AvgDialog_38729_Content_68 = {Text = "Apa?"},
  AvgDialog_38729_Content_69 = {
    Text = "Situasi saat itu sangat kacau, tapi kau berhasil menekan korban hanya belasan orang hanya dengan dirimu sendiri dan seorang Awakened. Ini hampir bisa disebut keajaiban."
  },
  AvgDialog_38729_Content_7 = {
    Text = "Orang-orang yang berdiri perlahan duduk."
  },
  AvgDialog_38729_Content_70 = {
    Text = "Kau dan Augier diam-diam saling bertatapan. Ksatria kecil itu menyembunyikan kedua tangannya di belakang punggung dan batuk pelan dua kali."
  },
  AvgDialog_38729_Content_71 = {
    Text = "Mungkin ini yang namanya keselarasan antara aku dan tuanku."
  },
  AvgDialog_38729_Content_72 = {
    Text = "Bagaimanapun juga, atas nama Tim Respons Pertama Dewan Inspeksi, aku ingin menyampaikan terima kasih kepadamu.\nDi tengah krisis, kau tidak meninggalkan orang-orang kami dan membuat mereka bisa pulang dengan selamat. Dan juga……"
  },
  AvgDialog_38729_Content_73 = {
    Text = [[
Banyak di antara kami yang tumbuh besar di sini, Distrik Katedral sangat berarti bagi kami.
Terima kasih banyak atas semua yang telah kau lakukan.]]
  },
  AvgDialog_38729_Content_74 = {
    Text = "Itu sudah menjadi tugas kami."
  },
  AvgDialog_38729_Content_75 = {
    Text = "Ucapan terima kasih tidak pernah berlebihan."
  },
  AvgDialog_38729_Content_76 = {
    Text = "Nona Sophia…… apa yang akan terjadi padanya selanjutnya?"
  },
  AvgDialog_38729_Content_77 = {
    Text = "Interogasi. Setelah kami mencari tahu asal-usul benda khusus itu, kami akan menjatuhkan vonis terhadapnya."
  },
  AvgDialog_38729_Content_78 = {
    Text = "Melakukan ritual bidah yang menyebabkan kekacauan berskala besar, beberapa orang tewas dan terluka…… Uskup berharap dia tidak akan dijatuhi hukuman mati, tapi aku tidak optimis."
  },
  AvgDialog_38729_Content_79 = {
    Text = "Yang menantinya, bukanlah hasil yang baik."
  },
  AvgDialog_38729_Content_8 = {
    Text = "Mereka yang duduk menganga, menatap kosong pemandangan yang bisa disebut mukjizat di hadapan mereka."
  },
  AvgDialog_38729_Content_80 = {
    Text = "Uskup Salvador."
  },
  AvgDialog_38729_Content_81 = {
    Text = "Kalian akan pergi?"
  },
  AvgDialog_38729_Content_82 = {
    Text = "Ya, terima kasih banyak atas bantuanmu dalam insiden kali ini."
  },
  AvgDialog_38729_Content_83 = {
    Text = "Semua ini terjadi karena aku, dan kalian bahkan menyembunyikan identitasku. Seharusnya akulah yang berterima kasih kepada kalian."
  },
  AvgDialog_38729_Content_84 = {
    Text = "Kau benar-benar tidak mau ikut kembali bersama kami?"
  },
  AvgDialog_38729_Content_85 = {
    Text = "Tidak perlu khawatir soal mengurus paroki. Selama kondisinya memenuhi syarat, kami mengizinkan Awakened untuk beraktivitas sendiri di luar."
  },
  AvgDialog_38729_Content_86 = {
    Text = "Terima kasih atas kebaikanmu, tapi aku lebih memilih untuk tetap tinggal di sini."
  },
  AvgDialog_38729_Content_87 = {
    Text = [[
Bapa membangkitkanku di sini, tentunya Beliau juga berharap aku membantu lebih banyak orang.
Jika kau membutuhkan sesuatu, <Yellow:Api Pucat>, kau bisa datang menemuiku kapan saja. Aku pasti akan memberikan yang terbaik untukmu.]]
  },
  AvgDialog_38729_Content_88 = {
    Text = "Maaf, tapi…… boleh saya bertanya, apa sebenarnya <Yellow:Utusan Pucat> dan <Yellow:Api Pucat> itu?"
  },
  AvgDialog_38729_Content_89 = {
    Text = "Itu adalah nubuat Bapa dalam \"Kitab Suci\"."
  },
  AvgDialog_38729_Content_9 = {
    Text = "Mereka yang kehilangan kesadaran, bahkan yang sudah berhenti bernapas, perlahan membuka mata dalam hembusan angin lembut."
  },
  AvgDialog_38729_Content_90 = {
    Text = "\"Kegelapan tanpa batas akan menyelimuti dunia, jiwa yang pucat dan hangat itulah utusan harapan, {Male=dia,Female=dia}akan menyalakan api putih, menerangi jalan ke depan.\""
  },
  AvgDialog_38729_Content_91 = {
    Text = "Belum tentu itu aku, kan? Ada begitu banyak orang di dunia ini."
  },
  AvgDialog_38729_Content_92 = {
    Text = [[
Meskipun mataku tertutup, aku tidak akan salah mengenali cahaya sebuah jiwa.
Milikmu begitu hangat, begitu terang. Selama bertahun-tahun, aku tidak pernah melihat yang kedua.]]
  },
  AvgDialog_38729_Content_93 = {
    Text = "Penjaga Rahasia muda itu berbalik dan pergi. Salvador menatap titik cahaya itu menjauh, dan berdoa pelan saat engsel pintu berputar."
  },
  AvgDialog_38729_Content_94 = {
    Text = "Semoga kau menerangi kegelapan dengan harapan yang pucat."
  },
  AvgDialog_38729_Content_95 = {
    Text = "<Yellow:Laporan Insiden Anomali Distrik Katedral Londinium>\n\nA.F. 315 @2@3, Distrik Katedral Agung Londinium, kerusuhan mendadak terjadi di alun-alun depan Katedral Agung Bapa Penyelamat. Warga yang hadir menunjukkan perilaku kekerasan parah dan tindakan menyakiti diri sendiri, tidak dapat berkomunikasi secara normal.\n……\nPerilaku abnormal meningkat setelah sumber cahaya tak dikenal berkedip, dan berkembang menjadi kanibalisme berskala besar. Setelah diselidiki, sumber cahaya tak dikenal tersebut ternyata adalah cermin genggam bermuka perak murni. Cermin ini memperoleh energi dengan memantulkan cahaya matahari dan bulan. Individu yang terkena pantulan cahaya cermin akan didorong oleh hasrat terkuat dalam hati mereka, termasuk namun tidak terbatas pada kekerasan, kerakusan, kantuk berlebihan, dan sebagainya, sehingga melakukan tindakan ekstrem.\nCermin tersebut telah diamankan oleh Penjaga Rahasia %player% dan Awakened Ogier. Penilaian awal menunjukkan bahwa cermin tersebut mengandung Inti Perak atau komponen serupa Inti Perak. Untuk detail lebih lanjut, silakan lihat laporan penelitian yang dikeluarkan oleh Departemen Penelitian Peralatan Khusus Universitas Misathega.\n……"
  },
  AvgDialog_38729_Content_96 = {
    Text = "Melalui interogasi oleh Dewan Peninjauan Perjanjian Mysteria, <Yellow:Sophia Chaztan> mengakui bahwa ia bergabung dengan Gereja Lentera tiga tahun lalu, dan memperoleh Cermin Ritual dari pemimpin gereja, Lentera (yaitu Nona <Yellow:Eve>), pada kegiatan gereja terakhir.\nKetika penyelidik bertanya lebih lanjut, Sophia Chaztan beralih berdoa dengan suara pelan dan tidak lagi memberikan respons apa pun.\n……"
  },
  AvgDialog_38729_Content_97 = {
    Text = "Matahari terbenam mengusir sisa kabut kelabu di langit, lonceng gereja berdentang, dan peluit kapal berbunyi dari dermaga di tepi sungai."
  },
  AvgDialog_38729_Content_98 = {
    Text = "Di atap sebuah gedung tinggi, sosok berjubah berdiri sendirian membelakangi cahaya matahari."
  },
  AvgDialog_38729_Content_99 = {
    Text = [[
Meskipun sudah memasukkan pendosa yang bermutasi, tetap tidak ada <Red:Stigmata> yang muncul.
Tampaknya nilai <Yellow:cermin itu> hanya sebatas ini saja.]]
  },
  AvgDialog_38841_Content_1 = {Text = "Ugh!"},
  AvgDialog_38841_Content_10 = {Text = "Tuan!"},
  AvgDialog_38841_Content_12 = {
    Text = "Detik berikutnya, sebuah Tablet raksasa jatuh di depanmu."
  },
  AvgDialog_38841_Content_13 = {
    Text = "Orang-orang yang dengan kegilaan menerjangmu, darah yang memenuhi udara, jeritan kacau dan memilukan yang membuat hati terguncang… semua itu terisolasi di balik tablet."
  },
  AvgDialog_38841_Content_14 = {
    Text = "Sebuah tangan dengan sarung tangan hitam menutupi lenganmu, kain yang sedikit dingin meredakan rasa sakit dan juga menyeka darah yang mengalir di lenganmu."
  },
  AvgDialog_38841_Content_15 = {
    Text = "Orang yang menggigitmu entah ke mana, yang berdiri di sisimu dan memegang lenganmu adalah seorang uskup yang mengenakan jubah panjang hitam."
  },
  AvgDialog_38841_Content_16 = {
    Text = "Di belakangnya tergantung empat buah Tablet, masing-masing diukir dengan rune yang rumit. Setiap rune tersebut bersinar dengan cahaya biru yang mengalir, seperti galaksi yang diperkecil berkali-kali lipat."
  },
  AvgDialog_38841_Content_17 = {
    Text = "Salah satu sinar biru mengalir dari lengannya menuju dirimu. Kamu menunduk, gigitan di lengan bawahmu sudah berhenti berdarah, bahkan sembuh secara bertahap di bawah tatapanmu."
  },
  AvgDialog_38841_Content_18 = {
    Text = "Salvador… Uskup?"
  },
  AvgDialog_38841_Content_2 = {
    Text = "Gigi yang tumpul menggigit pakaian dan menarik dengan kuat. Orang itu sudah sepenuhnya dikuasai oleh rasa lapar, hanya tahu mencengkeram lenganmu dan menggigit sekuat tenaga."
  },
  AvgDialog_38841_Content_3 = {Text = "Tuan!"},
  AvgDialog_38841_Content_4 = {
    Text = "Melihat gerakanmu dibatasi, orang-orang di sekitarmu yang juga kelaparan mulai melihat ke arahmu."
  },
  AvgDialog_38841_Content_5 = {
    Text = "Bunuh mereka! Kalau tidak, mereka akan terus menyerang. Cepat, bunuh mereka!"
  },
  AvgDialog_38841_Content_6 = {
    Text = "Sepasang-sepasang mata merah menyala menatapmu, sepasang-sepasang tangan meraihmu, diikuti oleh mulut-mulut yang terbuka lebar dan gigi-gigi putih yang tajam."
  },
  AvgDialog_38841_Content_7 = {
    Text = "Teriakan Ogier diperpanjang tanpa batas."
  },
  AvgDialog_38841_Content_8 = {
    Text = "Kamu mendengar suara kain yang robek."
  },
  AvgDialog_38841_Content_9 = {
    Text = "Sensasi panas datang kembali, diikuti oleh rasa nyeri yang menyengat. Kamu tahu, itu adalah serangan dari seseorang yang akhirnya menggigit tanganmu."
  },
  AvgDialog_38842_Content_1 = {Text = "Dosa Kita"},
  AvgDialog_38842_Content_10 = {
    Text = "Tuan... Pemimpin..."
  },
  AvgDialog_38842_Content_11 = {
    Text = "Begitu merah, mengapa bisa begitu merah? Di mana-mana dipenuhi dengan warna merah yang pekat, menekanmu hingga sulit bernapas. Kamu harus meninggalkan cahaya ini, harus pergi…"
  },
  AvgDialog_38842_Content_12 = {
    Text = "Sedikit sejuk, lalu aroma dupa dari Gereja."
  },
  AvgDialog_38842_Content_13 = {
    Text = "Cahaya biru menerangi sebagian kegelapan. Kamu tiba-tiba membuka mata dan melihat Ogier berlutut di depanmu, dengan cairan hitam mengalir dari sudut bibirnya."
  },
  AvgDialog_38842_Content_14 = {
    Text = "Sama persis seperti saat melakukan latihan pemutusan rantai dengannya."
  },
  AvgDialog_38842_Content_15 = {Text = "Ogier!"},
  AvgDialog_38842_Content_16 = {
    Text = "Segera fokuskan rohmu, Kunci perak di dadamu bergetar pelan. Setelah kilatan cahaya perak singkat, Ogier bangkit kembali."
  },
  AvgDialog_38842_Content_17 = {
    Text = "Pembersihan, <Big:Pembersihan!>"
  },
  AvgDialog_38842_Content_18 = {
    Text = "Cermin di tanganmu semakin terang. Saat kamu hendak menutupi mata, tiba-tiba kamu menyadari ada sebuah Bayangan jatuh di depanmu."
  },
  AvgDialog_38842_Content_19 = {
    Text = "Tablet raksasa menggantung di depanmu, rune-rune rumit di atasnya berkilauan dengan cahaya biru, namun sudah jauh lebih redup dibandingkan sebelumnya."
  },
  AvgDialog_38842_Content_2 = {
    Text = "Bulan darah menggantung tinggi, cahaya merah bagaikan katalis paling ampuh, seketika membakar kerumunan."
  },
  AvgDialog_38842_Content_20 = {
    Text = "Kamu berbalik, namun sosok Salvador sudah tidak terlihat lagi."
  },
  AvgDialog_38842_Content_21 = {
    Text = "Ogier, pergi dan ambil cermin itu."
  },
  AvgDialog_38842_Content_22 = {
    Text = "Namun, Tuan—"
  },
  AvgDialog_38842_Content_23 = {
    Text = "Aku bisa menjaga diriku sendiri. Waktu yang diberikan Yang Mulia Uskup untuk kita tidak banyak lagi, cepat bergerak!"
  },
  AvgDialog_38842_Content_24 = {Text = "Baik!"},
  AvgDialog_38842_Content_3 = {
    Text = "Perkelahian berubah menjadi penyiksaan, melukai diri berubah menjadi bunuh diri, dan mereka yang memang sudah aktif mencari kematian mulai mengakhiri hidup mereka dengan cara-cara yang tak terbayangkan."
  },
  AvgDialog_38842_Content_4 = {
    Text = "Bau amis darah sepenuhnya menenggelamkan aroma dupa yang tadinya menyelimuti langit di atas kalian. Di bawah cahaya merah, darah yang terciprat tampak hitam pekat bagai tinta, orang-orang yang gila menampakkan wajah mengerikan, bagaikan iblis."
  },
  AvgDialog_38842_Content_5 = {
    Text = "Di tengah neraka dunia ini, hanya gaun Sophia yang tetap bersih. Dia menghapus darah yang memercik ke wajahnya dan tertawa terbahak-bahak."
  },
  AvgDialog_38842_Content_6 = {
    Text = "Mengalirlah, alirkan dosa dari tubuh kalian! Alirkan dosa hitam!"
  },
  AvgDialog_38842_Content_7 = {
    Text = "Bertobatlah, para pendosa! Sebelum Sang Pembawa Lentera yang tegas menjatuhkan penghakiman, sucikanlah jiwa kalian yang kotor!"
  },
  AvgDialog_38842_Content_8 = {
    Text = "Cermin genggam terus berkedip-kedip, cahaya merah darah menusuk matamu, bahkan menembus kedua mata, langsung menghujam jauh ke dalam otak dan jiwamu."
  },
  AvgDialog_38842_Content_9 = {
    Text = "Ada sesuatu yang semakin ditarik semakin erat, semakin ditarik semakin erat, apa itu? Sangat tidak nyaman, sangat sakit, ingin muntah…"
  },
  AvgDialog_38843_Content_1 = {
    Text = "Sucikan segala dosa"
  },
  AvgDialog_38843_Content_10 = {
    Text = [[
Batuk tersedak, genangan cairan menghantam lantai.
Bau darah segar semakin menyengat.]]
  },
  AvgDialog_38843_Content_11 = {
    Text = "Sekarang dia sudah mati… <Blue:Mili> sudah mati…! <Blue:Thompson> orang gila itu memaksaku untuk mati bersamanya. Aku… aku tidak ingin mati, Yang Mulia Uskup, tapi aku juga…"
  },
  AvgDialog_38843_Content_12 = {
    Text = "Maaf, maaf... Ampuni saya, Yang Mulia Uskup. Hanya Bapa yang dapat mengampuni saya, hanya Bapa..."
  },
  AvgDialog_38843_Content_13 = {
    Text = "...\"Mereka yang pernah berbuat kesalahan, Dia juga bersedia membuka pelukan-Nya, selama mereka dengan tulus bertobat.\""
  },
  AvgDialog_38843_Content_14 = {
    Text = "Cahaya biru berpendar dari bawah ke atas menerangi sebagian jendela kaca patri. Sang Bapa di jendela kaca itu menundukkan pandangan-Nya dengan tenang, sama seperti yang telah dilakukan-Nya selama ratusan tahun."
  },
  AvgDialog_38843_Content_15 = {
    Text = "Di bawah tangan Salvador, luka-luka di sekujur tubuh pemuda itu sembuh dengan cepat, bahkan nyaris tanpa meninggalkan bekas luka."
  },
  AvgDialog_38843_Content_16 = {
    Text = "Bukalah matamu, Edward, hargailah kesempatan yang Bapa berikan kepadamu."
  },
  AvgDialog_38843_Content_17 = {
    Text = [[
Cahaya biru meliuk-liuk di tubuhmu seperti ular, semua rasa sakit dan kelelahan lenyap seketika saat ia menyentuhmu. 
 Tubuhmu terasa ringan, dipenuhi energi yang belum pernah kau rasakan sebelumnya.]]
  },
  AvgDialog_38843_Content_18 = {
    Text = "Uskup Salvador… adalah…"
  },
  AvgDialog_38843_Content_19 = {
    Text = "Runa di tablet berkilau mengikuti ritme seperti pernapasan, lebih banyak cahaya biru menjalar ke segala arah seperti akar pohon raksasa. Tak terhitung kerusakan dan kematian, tangisan dan jeritan, ditemukan di dalam keajaiban yang tiba-tiba datang ini."
  },
  AvgDialog_38843_Content_2 = {
    Text = "Uskup…… Uskup Salvador……"
  },
  AvgDialog_38843_Content_20 = {
    Text = "Aroma dupa dari Gereja menyentuh ujung hidungmu, samar-samar, lembut, seolah tak pernah ada, namun sepenuhnya menutupi aroma darah."
  },
  AvgDialog_38843_Content_21 = {
    Text = "…Tubuh Kebangkitan."
  },
  AvgDialog_38843_Content_22 = {
    Text = "Dia tiba-tiba memutar tubuhnya dan langsung menggigit tanganmu. Gigi-giginya mendekati lenganmu bersamaan dengan hembusan napas yang hangat dan lembap, membuat bulu kudukmu berdiri, Tubuhmu menegang, dan kamu sudah bersiap menghadapi rasa sakit yang akan datang."
  },
  AvgDialog_38843_Content_23 = {
    Text = "Tiba-tiba, sebuah tangan dengan sarung tangan hitam menutupi lenganmu."
  },
  AvgDialog_38843_Content_24 = {
    Text = "Kesejukan kain dan aroma menenangkan dari dupa di Gereja menyebar."
  },
  AvgDialog_38843_Content_25 = {
    Text = [[
Apakah kamu juga menyembuhkanku seperti ini pada waktu itu?
Ini... apakah ini kemampuanmu?]]
  },
  AvgDialog_38843_Content_26 = {
    Text = "Salvador memandangmu, tatapannya yang lembut dan penuh belas kasih tetap terasa meski melewati perban putih."
  },
  AvgDialog_38843_Content_27 = {
    Text = "Kau lagi-lagi menyelamatkan para pendosa itu."
  },
  AvgDialog_38843_Content_28 = {
    Text = "Sebuah suara dingin memotong ucapamu, kamu berbalik dan, seperti yang diharapkan, melihat bayangan Sophia."
  },
  AvgDialog_38843_Content_29 = {
    Text = "Kamu diberkati dengan <Yellow:\"Berkat\">, memiliki kekuatan yang tidak dimiliki orang biasa, namun hanya tahu memanjakan jiwa-jiwa penuh dosa ini, membiarkan mereka menyebarkan penderitaan."
  },
  AvgDialog_38843_Content_3 = {Text = "Edward?"},
  AvgDialog_38843_Content_30 = {
    Text = "Kamu adalah pendosa terbesar di sini, Salvador. Aku bersumpah akan membuatmu menyadari dosa-dosamu."
  },
  AvgDialog_38843_Content_31 = {
    Text = "Nona Sophia, apa yang sebenarnya kamu maksud?"
  },
  AvgDialog_38843_Content_32 = {
    Text = "Masih belum mengerti? Uskup yang berdiri di hadapan kalian ini, seorang munafik yang menyalahgunakan kekuatan ilahi, menyembunyikan identitas aslinya, dan berulang kali menyelamatkan orang-orang berdosa dari ambang kematian."
  },
  AvgDialog_38843_Content_33 = {
    Text = "Dia memberi mereka kesempatan berkali-kali atas nama belas kasihan, membuat orang benar menderita berkali-kali — ini tidak bisa dibiarkan terus berlanjut."
  },
  AvgDialog_38843_Content_34 = {
    Text = "<Yellow:Lentera> memberi saya petunjuk, <Yellow:Pemegang lentera berlapis perak murni> menurunkan misi kepada saya, memerintahkan saya untuk memulai pengadilan suci."
  },
  AvgDialog_38843_Content_35 = {
    Text = "Dia mengangkat tangannya, sebuah cermin genggam dengan bentuk aneh diarahkan ke langit malam. Saat sinar matahari jatuh ke dalamnya, warnanya berubah menjadi merah darah."
  },
  AvgDialog_38843_Content_36 = {
    Text = "Saya akan <Red:membersihkan> dosa hari ini, menyambut datangnya tanah suci yang tidak bersalah."
  },
  AvgDialog_38843_Content_37 = {
    Text = [[
Langit tiba-tiba menjadi gelap, matahari menghilang di langit, sementara bayangan merah di samping semakin membesar. 
Itu adalah bulan, sebuah bulan raksasa berwarna darah.]]
  },
  AvgDialog_38843_Content_38 = {
    Text = "Kegelapan melahap seluruh langit, cahaya bulan tumpah, mewarnai segalanya menjadi merah yang menyilaukan."
  },
  AvgDialog_38843_Content_39 = {
    Text = "Wahai para pendosa, sayatlah daging kalian, biarkan dosa kalian mengalir keluar—"
  },
  AvgDialog_38843_Content_4 = {
    Text = "Bau amis manis darah semakin menyengat seiring langkah kaki yang mendekat. Salvador telah lama meninggalkan penglihatan biasa, namun setelah terbangun kembali, ia menjadi mampu melihat cahaya yang memancar dari jiwa."
  },
  AvgDialog_38843_Content_40 = {
    Text = "Orang-orang yang tadinya saling berkelahi tiba-tiba berbalik, mengoyak kulit dan daging mereka sendiri dengan pisau dan gigi."
  },
  AvgDialog_38843_Content_41 = {
    Text = "Hapus mereka yang menolak untuk dimurnikan!"
  },
  AvgDialog_38843_Content_43 = {
    Text = "Mereka satu per satu berbalik ke arahmu, mata mereka memantulkan cahaya bulan merah."
  },
  AvgDialog_38843_Content_5 = {
    Text = "Saat ini, jiwa di hadapannya tenggelam dan timbul dalam kegelapan, nyaris padam."
  },
  AvgDialog_38843_Content_6 = {
    Text = "Ya Tuhan, Edward, pegangi aku, aku akan membawamu ke rumah sakit."
  },
  AvgDialog_38843_Content_7 = {
    Text = "Tidak! Aku…… tidak. Ini akibat perbuatanku sendiri."
  },
  AvgDialog_38843_Content_8 = {
    Text = [[
Jiwa itu kembali berkedip, bahkan semakin redup.
Waktunya tidak banyak lagi.]]
  },
  AvgDialog_38843_Content_9 = {
    Text = "Kau sudah memperingatkanku, jangan lagi hidup dari penderitaan orang lain, jangan lagi menipu. Seharusnya aku berubah, tapi aku tidak pernah mendengarkan…… Uhuk!"
  },
  AvgDialog_38844_Content_1 = {
    Text = "Tombak menyapu tanah dan menghantam betis pemuda itu. Pria muda yang terjebak dalam kegilaan tersandung, jatuh tertelungkup ke tanah. Kamu memanfaatkan kesempatan ini untuk memutar balikkan tangannya dan menekannya ke tanah."
  },
  AvgDialog_38844_Content_10 = {
    Text = "Sophia, Sophia, aku tahu aku salah, Sophia, kumohon sucikanlah aku!"
  },
  AvgDialog_38844_Content_11 = {
    Text = "E-Edward……?"
  },
  AvgDialog_38844_Content_12 = {
    Text = "Itu aku, itu aku! Aku tidak seharusnya menipumu, Kakak. Aku sangat menyesal, sungguh-sungguh menyesal!"
  },
  AvgDialog_38844_Content_13 = {
    Text = "Sambil menangis, ia merangkak maju dengan lututnya, terus membungkuk kepada Sophia dengan postur yang sangat canggung."
  },
  AvgDialog_38844_Content_14 = {
    Text = "Iblis telah membutakan mataku, telah mencemari jiwaku, tolong cambuk saya, bersihkan saya! Penghakiman akan datang, saya tidak ingin diusir dari tanah yang tidak bersalah!"
  },
  AvgDialog_38844_Content_15 = {
    Text = "Tenanglah, Edward, sebenarnya apa yang kau bicarakan?"
  },
  AvgDialog_38844_Content_16 = {
    Text = "Kumohon, Sophia!"
  },
  AvgDialog_38844_Content_17 = {
    Text = "Edward, hentikan."
  },
  AvgDialog_38844_Content_18 = {
    Text = "Pemuda itu tetap dalam posisi membungkuk sambil mendongakkan kepalanya, menatap Salvador dengan tatapan kosong."
  },
  AvgDialog_38844_Content_19 = {
    Text = "Us……kup……?"
  },
  AvgDialog_38844_Content_2 = {
    Text = "Lepaskan aku, biarkan aku dimurnikan! Biarkan aku dimurnikan!"
  },
  AvgDialog_38844_Content_20 = {
    Text = "Seberkas cahaya menyilaukan melintas di tepi penglihatanmu. Sebelum kau sempat mengedipkan bintik-bintik cahaya yang tersisa dari matamu, kau sudah mendengar suara Edward yang mulai menggila."
  },
  AvgDialog_38844_Content_21 = {
    Text = [[
Tidak... bukan... kau juga <Red:Pelaku Dosa>, kita semua adalah pelaku dosa! 
 Bertobatlah, bersihkan diri! Jika tidak, kita semua akan terbakar di lautan penderitaan tanpa akhir!]]
  },
  AvgDialog_38844_Content_23 = {
    Text = "Tubuh pemuda itu goyang, lalu langsung terjatuh ke tanah. Ogier diam-diam menyimpan tombak panjang yang digunakan untuk membuatnya pingsan, lalu berbalik menatapmu."
  },
  AvgDialog_38844_Content_24 = {
    Text = "Sebelum dia melukai orang lain, bawa dia ke tempat yang aman dulu. Lalu panggil polisi, biarkan orang yang profesional menanganinya."
  },
  AvgDialog_38844_Content_25 = {
    Text = "Orang-orang di Gereja sudah keluar, sekarang seharusnya kosong."
  },
  AvgDialog_38844_Content_26 = {
    Text = [[
Baiklah. 
Semoga setelah dia bangun, dia bisa lebih tenang.]]
  },
  AvgDialog_38844_Content_27 = {
    Text = "Dia berjongkok, dan bersama denganmu mengangkat Edward dari tanah, menyangga tubuhnya di bahu."
  },
  AvgDialog_38844_Content_28 = {
    Text = "Biarkan aku yang melakukannya, %player%{Male=tuan,Female=nyonya}."
  },
  AvgDialog_38844_Content_29 = {
    Text = "Tidak apa-apa, aku sudah terbiasa menanggungnya. Setelah berdiri, malah sulit untuk mengubah tangan."
  },
  AvgDialog_38844_Content_3 = {
    Text = "Apa yang terjadi?"
  },
  AvgDialog_38844_Content_30 = {
    Text = [[
Ini... kalau begitu, aku merepotkanmu. 
 Aku akan tinggal di sini sebentar lagi, melihat apakah ada orang yang ketakutan atau terluka karena Edward dan membutuhkan bantuan.]]
  },
  AvgDialog_38844_Content_31 = {
    Text = "Kamu mengangguk, baru saja hendak berbalik, ketika kilatan cahaya yang serupa dengan tadi kembali melintas di tepi pandanganmu."
  },
  AvgDialog_38844_Content_32 = {Text = "?"},
  AvgDialog_38844_Content_33 = {
    Text = [[
Kamu baik-baik saja, %player%?
Kalau badanmu tidak enak, aku bisa melakukannya sendiri.]]
  },
  AvgDialog_38844_Content_34 = {
    Text = [[
Tidak apa-apa, mungkin mataku terkena pantulan kaca. 
 Ayo pergi.]]
  },
  AvgDialog_38844_Content_4 = {
    Text = "Suara yang tenang terdengar dari belakang kalian. Bisik-bisik di sekitar perlahan mereda hingga sunyi, orang-orang secara otomatis membuka jalan agar sang uskup berpakaian jubah hitam keagamaan dapat lewat dengan lancar."
  },
  AvgDialog_38844_Content_5 = {
    Text = "Uskup Salvador dengan mata tertutup kain, namun berjalan menuju kalian dengan tepat seolah ia bisa melihat. Sophia mengikuti di belakangnya dengan wajah penuh kekhawatiran."
  },
  AvgDialog_38844_Content_6 = {
    Text = "Sophia... Sophia!"
  },
  AvgDialog_38844_Content_7 = {
    Text = "Pemuda itu tiba-tiba menjadi sangat bersemangat. Dengan kekuatan yang tak terduga olehmu, dia melepaskan diri dari cengkeramanmu dan langsung melompat ke depan Sophia ——"
  },
  AvgDialog_38844_Content_8 = {Text = "Hati-hati!"},
  AvgDialog_38844_Content_9 = {
    Text = "Lalu jatuh berlutut dengan keras."
  },
  AvgDialog_38845_Content_1 = {
    Text = "Ogier melemparkan dengan sekuat tenaga, tombak panjang menancap di cermin perak."
  },
  AvgDialog_38845_Content_10 = {
    Text = "Ini di mana? Kenapa aku……"
  },
  AvgDialog_38845_Content_11 = {
    Text = "Yang Mulia Uskup, apakah itu Yang Mulia Uskup? Apa yang terjadi padanya?"
  },
  AvgDialog_38845_Content_12 = {
    Text = "Tolong…… tunggu……"
  },
  AvgDialog_38845_Content_13 = {
    Text = "Cahaya biru entah kapan telah menghilang sepenuhnya."
  },
  AvgDialog_38845_Content_14 = {
    Text = "Salvador berlutut di antara tablet, dia mengangkat kepalanya ke arahmu, dua aliran air mata darah mengalir dari balik perban putih."
  },
  AvgDialog_38845_Content_15 = {
    Text = "Tuanku, apa yang terjadi pada Uskup?"
  },
  AvgDialog_38845_Content_16 = {
    Text = "Sepertinya kekuatan spiritual penghubung tidak cukup, tapi ketidakstabilan separah ini…… aku belum pernah melihatnya."
  },
  AvgDialog_38845_Content_17 = {
    Text = "Penghubungku…… adalah…… mantan uskup di sini…… aku tidak bisa…… memforsirnya……"
  },
  AvgDialog_38845_Content_18 = {
    Text = "Utusan yang pucat…… kumohon…… tolong kau……"
  },
  AvgDialog_38845_Content_19 = {
    Text = [[
Dia mengangkat tangannya yang gemetar, perlahan meletakkannya di bahumu.
Tapi kau hampir tak bisa merasakan beban tangannya lagi.]]
  },
  AvgDialog_38845_Content_2 = {
    Text = "Pecahan cermin perak berjatuhan bagai bintang yang gugur, dan bersamaan dengan itu, bulan merah penuh retakan di langit turut hancur sepenuhnya."
  },
  AvgDialog_38845_Content_20 = {
    Text = "Dia menghilang dengan cepat, kecuali—"
  },
  AvgDialog_38845_Content_21 = {
    Text = "Kau menggenggam tangan Salvado dan memejamkan mata."
  },
  AvgDialog_38845_Content_22 = {
    Text = [[
Kegelapan.
Kegelapan yang begitu damai, seperti sebuah pelukan, dan seperti tidur yang lelap.]]
  },
  AvgDialog_38845_Content_23 = {
    Text = "Bercak cahaya yang rumit muncul dalam kesadaranmu: bingung adalah warga sipil di sekitarmu, tegas adalah Ogier, dan ada seorang uskup yang lemah yang memancarkan cahaya biru samar, hampir tidak terlihat."
  },
  AvgDialog_38845_Content_24 = {
    Text = "Kau mendekat ke arahnya, mendengar suara percakapan yang samar."
  },
  AvgDialog_38845_Content_25 = {
    Text = "Keluargaku selalu berupaya menghapus penderitaan dan menyebarkan rahmat Sang Bapa, mengapa kami justru jatuh ke keadaan seperti ini?"
  },
  AvgDialog_38845_Content_26 = {
    Text = "Diam! Kau tidak boleh memfitnah ayahku seperti itu, dia bukan orang seperti itu! Bukan!"
  },
  AvgDialog_38845_Content_27 = {
    Text = "Yang Mulia Uskup, mengapa dunia selalu dipenuhi penderitaan?"
  },
  AvgDialog_38845_Content_28 = {
    Text = "Jika di dunia ini tidak ada orang berdosa, apakah... orang-orang seperti kakak saya, ibu saya, dan anak-anak di panti asuhan tidak akan lagi menjadi korban kejahatan orang lain?"
  },
  AvgDialog_38845_Content_29 = {
    Text = "Apakah mereka bisa terbebas dari penderitaan dan hidup bahagia selamanya?"
  },
  AvgDialog_38845_Content_3 = {
    Text = "Monster mengeluarkan teriakan sedih yang memilukan, lalu jatuh dengan keras. Tubuhnya yang besar dengan cepat larut menjadi genangan darah berwarna gelap, hanya menyisakan sosok manusia yang terbaring di tanah."
  },
  AvgDialog_38845_Content_30 = {
    Text = "Ini adalah tanggung jawabku."
  },
  AvgDialog_38845_Content_31 = {
    Text = [[
Bayangan Salvador muncul di sisimu. 
 Kenangan terus berubah di hadapan kalian. Dia tampak tanpa ekspresi, namun kamu bisa merasakan sedikit kesedihan.]]
  },
  AvgDialog_38845_Content_32 = {
    Text = "Aku selalu tahu, di dalam hatinya selalu tersimpan dendam. Kukira dia akan melepaskannya, tapi ternyata dia justru membiarkan kebencian itu tumbuh."
  },
  AvgDialog_38845_Content_33 = {
    Text = [[
Dia bilang hari itu kaulah yang menyelamatkannya, benarkah begitu, Uskup Salvado? Tapi mengapa?
Dia sudah melakukan begitu banyak kejahatan, menipu begitu banyak orang, mengapa kau masih mau membantunya?]]
  },
  AvgDialog_38845_Content_34 = {
    Text = "Kesempatan kedua? Siapa yang bisa memberi keluargaku kesempatan kedua, siapa yang bisa memberi kakakku, ibuku kesempatan kedua? \nMereka sudah meninggal, Uskup Salvador, mereka kembali ke pelukan Bapa, hanya aku yang tersisa…"
  },
  AvgDialog_38845_Content_35 = {
    Text = "Hanya tersisa aku…"
  },
  AvgDialog_38845_Content_36 = {
    Text = "Dewa Bapa mengasihani, memberiku kesempatan hidup sekali lagi. Seharusnya aku berbuat lebih baik, namun kini aku mengulangi kesalahan yang sama."
  },
  AvgDialog_38845_Content_37 = {
    Text = "Para pencuri, penjudi, pecandu itu, yang mereka cari darimu bukanlah pengampunan dan kesempatan, melainkan penghiburan diri! Sebuah alasan untuk terus berbuat jahat!"
  },
  AvgDialog_38845_Content_38 = {
    Text = [[
Orang berdosa tidak menunjukkan penyesalan, dan tidak akan pernah menyesal. Pengampunan tanpa batas hanya akan membuat orang baik kecewa, sementara yang jahat semakin bertindak sewenang-wenang.
Jika ini terus berlanjut, kamu tidak akan mampu menyelamatkan siapa pun.]]
  },
  AvgDialog_38845_Content_39 = {
    Text = [[
Aku mengampuni mereka dan memberi mereka ketenteraman, sama seperti aku mengampuni semua orang dan memberi semua orang ketenteraman. 
Semua orang mendapatkan cinta dari Bapa, dan setiap orang memiliki hak untuk berbuat salah serta kembali ke jalan yang benar.]]
  },
  AvgDialog_38845_Content_4 = {
    Text = [[
Bulan darah menghilang, sinar matahari kembali menyinari permukaan tanah, menerangi sosok yang terbaring di genangan darah.
Sophia menatap langit dengan tatapan kosong, mulutnya masih berbisik pelan.]]
  },
  AvgDialog_38845_Content_40 = {
    Text = "Penderitaan adalah hal yang tidak ingin dilihat oleh Dewa Bapa, penderitaan adalah hal yang ingin Dewa Bapa hapuskan, dan juga yang harus kuhapuskan sebagai pelaksana kehendak-Nya."
  },
  AvgDialog_38845_Content_41 = {
    Text = "Penderitaan yang kusebabkan, harus kutebus sendiri."
  },
  AvgDialog_38845_Content_42 = {
    Text = "Dia mengulurkan tangan dan mengusap perlahan, kenangan yang menguning beriak seperti air lalu perlahan menghilang, berkumpul kembali menjadi titik-titik cahaya yang melambangkan jiwanya."
  },
  AvgDialog_38845_Content_43 = {
    Text = "Dia berbalik ke arahmu, menyodorkan titik-titik cahaya yang digenggamnya ke hadapanmu."
  },
  AvgDialog_38845_Content_44 = {
    Text = [[
Tolong bantu aku, Utusan Pucat.
Bantu aku menghapus penderitaan dari tubuh mereka, agar mereka bisa menjalani sisa perjalanan mereka dengan tenang.]]
  },
  AvgDialog_38845_Content_45 = {
    Text = "Menerima titik cahaya"
  },
  AvgDialog_38845_Content_46 = {
    Text = "Cahaya biru berayun di hadapanmu bagai benang laba-laba, satu ujung terhubung ke jiwa yang tua namun lembut, ujung lainnya menyelam jauh ke dalam titik cahaya di hadapanmu."
  },
  AvgDialog_38845_Content_47 = {
    Text = "Kau dengan hati-hati memutus benang halus itu, mewarnainya dengan warna milikmu sendiri."
  },
  AvgDialog_38845_Content_48 = {
    Text = "Putih mengalir sepanjang benang ke dalam, semakin dalam, titik cahaya menyala, perlahan mengusir kegelapan."
  },
  AvgDialog_38845_Content_49 = {
    Text = "Terima kasih."
  },
  AvgDialog_38845_Content_5 = {
    Text = "Nona <Yellow:Eve>…… Aku telah mengecewakanmu, mengecewakan <Yellow:Sang Pembawa Lentera>……\nAku gagal memurnikan mereka, gagal memurnikan dosa……"
  },
  AvgDialog_38845_Content_6 = {
    Text = "Sang Pembawa Lentera…… orang yang bertubuh perak murni…… kumohon……"
  },
  AvgDialog_38845_Content_7 = {
    Text = "Dia menghirup napas, lalu, tak pernah lagi mampu menghembuskannya."
  },
  AvgDialog_38845_Content_8 = {
    Text = "Seluruh alun-alun porak-poranda — orang-orang yang terluka oleh monster terbaring di tanah, banyak yang sudah kehilangan nyawa, sementara yang lain merintih kesakitan, tidak mengerti mengapa mereka menjadi seperti ini."
  },
  AvgDialog_38845_Content_9 = {
    Text = "Ugh…… kepalaku sakit sekali……"
  },
  AvgDialog_38846_Content_1 = {
    Text = "Nyalakan harapan putih"
  },
  AvgDialog_38846_Content_10 = {
    Text = "Mereka yang kehilangan kesadaran, bahkan yang sudah berhenti bernapas, perlahan membuka mata dalam hembusan angin lembut."
  },
  AvgDialog_38846_Content_11 = {
    Text = "Hapuskanlah rasa sakit mereka, tenangkanlah hati mereka."
  },
  AvgDialog_38846_Content_12 = {
    Text = "Pandangan orang-orang menjadi kosong, tubuh mereka semakin rileks. Kepanikan dan ketakutan lenyap begitu saja, digantikan oleh perasaan tenang dan damai."
  },
  AvgDialog_38846_Content_13 = {
    Text = "Agar mereka tidak lagi menderita dalam penderitaan, dan berikan mereka Berkat."
  },
  AvgDialog_38846_Content_14 = {
    Text = "Cahaya seperti gelombang pasang menyebar ke segala arah, semua orang menutup mata mereka, seolah-olah tenggelam dalam ketenangan."
  },
  AvgDialog_38846_Content_15 = {
    Text = "Bulan yang terang memandangi segalanya dari atas, seperti biasa. Hanya alun-alun yang berantakan yang membuktikan kegilaan yang baru saja terjadi."
  },
  AvgDialog_38846_Content_16 = {
    Text = "Tablet berbunyi pelan, lalu berubah menjadi bayangan tak terlihat dan menyatu ke dalam kegelapan malam. Salvador merapikan pakaiannya, kemudian berjalan mendekati Sophia."
  },
  AvgDialog_38846_Content_17 = {
    Text = "……Kau seharusnya tidak menyelamatkanku."
  },
  AvgDialog_38846_Content_18 = {
    Text = "\"Siapa pun yang tersadar dari kesesatan, dapat kembali ke dalam pelukanku\"."
  },
  AvgDialog_38846_Content_19 = {
    Text = [[
"Karena kalian semua adalah anak-anakku, dan aku mencintai kalian semua".
Tapi kau salah, Uskup, dan Kitab Suci juga salah.]]
  },
  AvgDialog_38846_Content_2 = {
    Text = "Lempengan batu terangkat kembali."
  },
  AvgDialog_38846_Content_20 = {
    Text = "Ada orang yang tidak akan pernah berubah."
  },
  AvgDialog_38846_Content_21 = {
    Text = "Kau datang untuk apa?"
  },
  AvgDialog_38846_Content_22 = {
    Text = "Sofia, aku—"
  },
  AvgDialog_38846_Content_23 = {
    Text = "Diam! Membunuh kakakku dan ibuku belum cukup, kau masih mau datang ke makam mereka untuk pamer kemenanganmu?!"
  },
  AvgDialog_38846_Content_24 = {
    Text = "Aku datang untuk meminta maaf, aku tidak menyangka…"
  },
  AvgDialog_38846_Content_25 = {
    Text = "Sofia tertawa sinis."
  },
  AvgDialog_38846_Content_26 = {
    Text = [[
Apakah kamu juga meminta maaf seperti ini kepada <Blue:Thompson>, setelah membunuh satu-satunya keluarganya, setelah membunuh <Blue:Milly>? 
 Kamu membuatku jijik, Edward Bailey.]]
  },
  AvgDialog_38846_Content_27 = {
    Text = "Aku benar-benar menyesal, Sofia. Aku tahu aku tidak bisa mendapatkan pengampunanmu—"
  },
  AvgDialog_38846_Content_28 = {
    Text = "Kalau kau benar-benar menyesal, seharusnya kau tidak pergi mencari Uskup Salvador pada hari Thompson membunuhmu."
  },
  AvgDialog_38846_Content_29 = {
    Text = [[
Benar, aku tahu bagaimana kau bisa bertahan hidup, pengecut. <Yellow:Lentera> memberitahuku. 
 Memberimu "<Yellow:Berkat>" adalah keputusan terbodoh dari sang Uskup. Kau seharusnya mati, Beili, mati dalam penderitaan.]]
  },
  AvgDialog_38846_Content_30 = {
    Text = "Aku juga tidak ingin begini, aku sudah mencoba mengendalikan diriku, aku sudah mencoba! Setelah uskup menyelamatkanku, aku setiap hari kembali melapor ke gereja, setiap minggu aku pergi ke rumah amal milik keluargamu untuk menjadi sukarelawan, kau masih ingat?"
  },
  AvgDialog_38846_Content_31 = {
    Text = "Aku ingin berubah menjadi lebih baik, aku benar-benar ingin. Orang dari Agro itulah yang bilang ini bisnis tanpa risiko, dia yang menyuruhku memperkenalkan seorang penjamin. Aku juga korban!"
  },
  AvgDialog_38846_Content_32 = {
    Text = "Sampai sekarang kau masih melempar tanggung jawab, sampai sekarang… kau belum pernah benar-benar bertobat."
  },
  AvgDialog_38846_Content_33 = {
    Text = "Dia mengeluarkan sebuah benda berwarna perak putih dari saku dalam roknya. Permukaan yang halus itu berkilau samar di bawah sinar matahari, memantulkan cahaya menjadi merah menyala yang membawa firasat tidak menyenangkan."
  },
  AvgDialog_38846_Content_34 = {Text = "Sophia…?"},
  AvgDialog_38846_Content_35 = {
    Text = "Bertobatlah."
  },
  AvgDialog_38846_Content_36 = {
    Text = [[
Ikutilah ajaran Sang Pembawa Lentera yang adil, sucikan dosa dari dalam jiwamu.
Hanya dengan begitu, pengampunan mungkin diperoleh.]]
  },
  AvgDialog_38846_Content_37 = {
    Text = "Apa dirimu?"
  },
  AvgDialog_38846_Content_38 = {
    Text = "Aku… aku adalah Edward…"
  },
  AvgDialog_38846_Content_39 = {
    Text = [[
Cermin berkilat sesaat, tatapan pemuda yang berlutut di tanah kembali linglung.
Dia gemetar mengangkat tongkat di tangannya, lalu menghantamkannya keras-keras ke tubuhnya sendiri.]]
  },
  AvgDialog_38846_Content_4 = {
    Text = "Salvador mengangkat tangannya, darah terus-menerus mengalir dari tubuhnya dan sekitarnya menuju Tablet."
  },
  AvgDialog_38846_Content_40 = {
    Text = "Aku tanya sekali lagi, kau ini apa?"
  },
  AvgDialog_38846_Content_41 = {
    Text = "Aku adalah pendosa."
  },
  AvgDialog_38846_Content_42 = {
    Text = "Dosa apa yang telah kau perbuat?"
  },
  AvgDialog_38846_Content_43 = {
    Text = "Aku serakah tanpa batas, aku memanjakan nafsu, aku membiarkan iblis mencemari jiwaku, lalu membawa penderitaan kepada orang-orang tak bersalah."
  },
  AvgDialog_38846_Content_44 = {
    Text = "Apa yang seharusnya kau lakukan?"
  },
  AvgDialog_38846_Content_45 = {
    Text = [[
Aku harus bertobat kepada mereka yang telah kusakiti, aku harus bertobat kepada para dewa.
Aku harus menerima hukuman cambuk, harus berdarah hingga dosa hitam mengalir keluar, demi memperoleh <Red:penyucian>.]]
  },
  AvgDialog_38846_Content_46 = {
    Text = "Penghakiman akan tiba, hanya jiwa yang murni yang dapat memasuki tanah suci tanpa dosa."
  },
  AvgDialog_38846_Content_47 = {
    Text = "<Red:Semoga lentera senantiasa menyala>."
  },
  AvgDialog_38846_Content_48 = {
    Text = [[
Orang berdosa tidak akan berubah selama mereka masih ada, penderitaan pun tidak akan pernah lenyap. 
 Hanya dengan menghapus mereka semua, dunia baru bisa mendapatkan ketenangan.]]
  },
  AvgDialog_38846_Content_49 = {
    Text = "…Relik Pencipta selalu menyimpan cahaya-Nya. Setiap orang mungkin tertutupi, dan sama halnya, setiap orang mungkin menemukan kembali cahaya Pencipta."
  },
  AvgDialog_38846_Content_5 = {
    Text = "Cahaya biru kembali mengalir sepanjang pola, terang lalu redup, mirip dengan napas."
  },
  AvgDialog_38846_Content_50 = {
    Text = "Kita tidak bisa merampas seluruh kehidupan seseorang hanya karena perbuatannya sesaat."
  },
  AvgDialog_38846_Content_51 = {
    Text = "Kamu berkata seperti itu, tapi sama sekali tidak memikirkan orang-orang yang menjadi korban mereka. Saat para Edward menemukan kembali cahaya mereka, berapa banyak Millie yang harus dikorbankan? Berapa banyak Olivia?"
  },
  AvgDialog_38846_Content_52 = {
    Text = "Dosa tetaplah dosa, kesalahan tetaplah kesalahan. Begitu dilakukan, tidak ada jalan kembali."
  },
  AvgDialog_38846_Content_53 = {
    Text = "Dia memandang ke arah kalian."
  },
  AvgDialog_38846_Content_54 = {
    Text = [[
Bawalah aku pergi, lemparkan aku kepada hukum korup kalian. Tapi ingat, hari penghakiman pasti akan tiba.
Saat itu, kalian semua akan diusir dari tanah tidak bersalah.]]
  },
  AvgDialog_38846_Content_55 = {
    Text = "Objek khusus sudah selesai diamankan, Penjaga Rahasia. Warga sipil yang terdampak juga sudah dikirim ke berbagai rumah sakit. Mereka bisa pulang setelah diperiksa dan dinyatakan baik-baik saja."
  },
  AvgDialog_38846_Content_56 = {
    Text = "Pernyataan resminya adalah ini merupakan insiden halusinasi massal akibat kebocoran gas beracun dari pabrik. Pemerintah kota akan meminta maaf secara terbuka besok dan memberikan sanksi kepada pihak-pihak terkait."
  },
  AvgDialog_38846_Content_57 = {
    Text = "Aku mengerti, terima kasih atas kerja keras kalian."
  },
  AvgDialog_38846_Content_58 = {
    Text = "Ini sudah menjadi tugas kami."
  },
  AvgDialog_38846_Content_59 = {
    Text = "Pria muda berseragam itu ragu-ragu sejenak, lalu berkata:"
  },
  AvgDialog_38846_Content_6 = {
    Text = "Dewa Bapa sang Pencipta, Sang Pembuat yang penuh belas kasih, dengarkanlah doaku."
  },
  AvgDialog_38846_Content_60 = {
    Text = "Bagaimana kau bisa melakukannya?"
  },
  AvgDialog_38846_Content_61 = {Text = "Apa?"},
  AvgDialog_38846_Content_62 = {
    Text = "Situasi saat itu sangat kacau, tapi kau berhasil menekan korban hanya belasan orang hanya dengan dirimu sendiri dan seorang Awakened. Ini hampir bisa disebut keajaiban."
  },
  AvgDialog_38846_Content_63 = {
    Text = "Kau dan Augier diam-diam saling bertatapan. Ksatria kecil itu menyembunyikan kedua tangannya di belakang punggung dan batuk pelan dua kali."
  },
  AvgDialog_38846_Content_64 = {
    Text = "Mungkin ini yang namanya keselarasan antara aku dan tuanku."
  },
  AvgDialog_38846_Content_65 = {
    Text = "Bagaimanapun juga, atas nama Tim Respons Pertama Dewan Inspeksi, aku ingin menyampaikan terima kasih kepadamu.\nDi tengah krisis, kau tidak meninggalkan orang-orang kami dan membuat mereka bisa pulang dengan selamat. Dan juga……"
  },
  AvgDialog_38846_Content_66 = {
    Text = [[
Banyak di antara kami yang tumbuh besar di sini, Distrik Katedral sangat berarti bagi kami.
Terima kasih banyak atas semua yang telah kau lakukan.]]
  },
  AvgDialog_38846_Content_67 = {
    Text = "Itu sudah menjadi tugas kami."
  },
  AvgDialog_38846_Content_68 = {
    Text = "Ucapan terima kasih tidak pernah berlebihan."
  },
  AvgDialog_38846_Content_69 = {
    Text = "Nona Sophia…… apa yang akan terjadi padanya selanjutnya?"
  },
  AvgDialog_38846_Content_7 = {
    Text = "Biru yang lembut berpusat pada Tablet, menjalar ke akar-akar halus yang rapat di sekitarnya. Mereka melewati kerumunan orang, angin sejuk mengusir sisa-sisa bau darah, meninggalkan aroma wewangian yang samar."
  },
  AvgDialog_38846_Content_70 = {
    Text = "Interogasi. Setelah kami mencari tahu asal-usul benda khusus itu, kami akan menjatuhkan vonis terhadapnya."
  },
  AvgDialog_38846_Content_71 = {
    Text = "Melakukan ritual bidah yang menyebabkan kekacauan berskala besar, beberapa orang tewas dan terluka…… Uskup berharap dia tidak akan dijatuhi hukuman mati, tapi aku tidak optimis."
  },
  AvgDialog_38846_Content_72 = {
    Text = "Uskup Salvador."
  },
  AvgDialog_38846_Content_73 = {
    Text = "Kalian akan pergi?"
  },
  AvgDialog_38846_Content_74 = {
    Text = "Ya, terima kasih banyak atas bantuanmu dalam insiden kali ini."
  },
  AvgDialog_38846_Content_75 = {
    Text = "Semua ini terjadi karena aku, dan kalian bahkan menyembunyikan identitasku. Seharusnya akulah yang berterima kasih kepada kalian."
  },
  AvgDialog_38846_Content_76 = {
    Text = "Kau benar-benar tidak mau ikut kembali bersama kami?"
  },
  AvgDialog_38846_Content_77 = {
    Text = "Tidak perlu khawatir soal mengurus paroki. Selama kondisinya memenuhi syarat, kami mengizinkan Awakened untuk beraktivitas sendiri di luar."
  },
  AvgDialog_38846_Content_78 = {
    Text = "Terima kasih atas kebaikanmu, tapi aku lebih memilih untuk tetap tinggal di sini."
  },
  AvgDialog_38846_Content_79 = {
    Text = "Salvador berbalik ke arah altar, menampilkan senyuman yang lembut."
  },
  AvgDialog_38846_Content_8 = {
    Text = "Orang-orang yang berdiri perlahan duduk."
  },
  AvgDialog_38846_Content_80 = {
    Text = [[
Dewa Ayah membangkitkanku di sini, mungkin Dia juga berharap aku bisa membantu lebih banyak orang. 
 Jika kamu membutuhkan bantuan, <Yellow:Api pucat>, kamu bisa datang padaku kapan saja. Aku pasti akan berusaha sepenuhnya untukmu.]]
  },
  AvgDialog_38846_Content_81 = {
    Text = "Maaf, tapi…… boleh saya bertanya, apa sebenarnya <Yellow:Utusan Pucat> dan <Yellow:Api Pucat> itu?"
  },
  AvgDialog_38846_Content_82 = {
    Text = "Adalah ramalan dari Sang Ayah dalam <Yellow:《Kitab Suci》>."
  },
  AvgDialog_38846_Content_83 = {
    Text = "\"Kegelapan tanpa batas akan menyelimuti dunia, jiwa yang pucat dan hangat itulah utusan harapan, {Male=dia,Female=dia}akan menyalakan api putih, menerangi jalan ke depan.\""
  },
  AvgDialog_38846_Content_84 = {
    Text = "Belum tentu itu aku, kan? Ada begitu banyak orang di dunia ini."
  },
  AvgDialog_38846_Content_85 = {
    Text = [[
Meskipun mataku tertutup, aku tidak akan salah mengenali cahaya sebuah jiwa.
Milikmu begitu hangat, begitu terang. Selama bertahun-tahun, aku tidak pernah melihat yang kedua.]]
  },
  AvgDialog_38846_Content_86 = {
    Text = "[Di sini tergantung pada desain alur utama, lihat apakah perlu menyebutkan informasi terkait lentera]"
  },
  AvgDialog_38846_Content_87 = {
    Text = "Penjaga Rahasia muda itu berbalik dan pergi. Salvador menatap titik cahaya itu menjauh, dan berdoa pelan saat engsel pintu berputar."
  },
  AvgDialog_38846_Content_88 = {
    Text = "Semoga kau menerangi kegelapan dengan harapan yang pucat."
  },
  AvgDialog_38846_Content_89 = {
    Text = "<Yellow:Laporan Acara Anomali Distrik Gereja Londinium>\n\nA.F. 315 @2@3, distrik Gereja Agung Londinium, terjadi kekacauan di alun-alun depan Gereja Londinium Berkat Abadi Dari Ayah. Orang-orang yang hadir menunjukkan perilaku kekerasan berat dan tindakan melukai diri sendiri, komunikasi normal tidak mungkin dilakukan.\n……\nPerilaku anomali meningkat setelah sumber cahaya yang tidak diketahui berkedip, dan berkembang menjadi aksi kanibalisme berskala besar. Menurut penyelidikan, sumber cahaya yang tidak diketahui sebenarnya adalah sebuah cermin tangan perak murni. Cermin ini mendapatkan energi melalui memantulkan sinar matahari dan bulan, individu yang terkena refleksi cermin akan terdorong oleh keinginan terkuat dalam hati mereka, termasuk tapi tidak terbatas pada kekerasan, kerakusan, kantuk, dan lain-lain, hingga melakukan tindakan yang berlebihan.\nCermin tersebut telah diperoleh kembali oleh Penjaga %player% dan Pembangun Ogier, diduga mengandung inti perak atau bahan seperti inti perak, untuk rincian lebih lanjut silakan lihat laporan penelitian yang dikeluarkan oleh Departmen Penelitian Alat Khusus Universitas Mythag.\n……\nDiinterogasi oleh Komite Perjanjian Mystia, <Blue:Sophia Chaztan> mengakui dirinya bergabung dengan Gereja Penerang Tiga tahun lalu, dan mendapatkan cermin ritual dari pemimpin gereja Penerang (yaitu, Ny. <Yellow:Eva>) dalam kegiatan gereja terakhir.\nSaat agen menanyakan lebih lanjut, Sophia Chaztan mulai berdoa dengan suara rendah dan tidak memberikan jawaban lebih lanjut.\n……"
  },
  AvgDialog_38846_Content_9 = {
    Text = "Mereka yang duduk menganga, menatap kosong pemandangan yang bisa disebut mukjizat di hadapan mereka."
  },
  AvgDialog_38846_Content_90 = {
    Text = "Matahari terbenam mengusir sisa kabut kelabu di langit, lonceng gereja berdentang, dan peluit kapal berbunyi dari dermaga di tepi sungai."
  },
  AvgDialog_38846_Content_91 = {
    Text = "Di atap sebuah gedung tinggi, sosok berjubah berdiri sendirian membelakangi cahaya matahari."
  },
  AvgDialog_38846_Content_92 = {
    Text = [[
Meskipun sudah memasukkan pendosa yang bermutasi, tetap tidak ada <Red:Stigmata> yang muncul.
Tampaknya nilai <Yellow:cermin itu> hanya sebatas ini saja.]]
  },
  AvgDialog_38846_Content_93 = {
    Text = "Memberikan pengampunan kepada para pendosa, memberi mereka \"Berkat\"… Kamu benar-benar tidak berubah sama sekali, Uskup Salvador."
  },
  AvgDialog_38846_Content_94 = {
    Text = "Tiang pembakaran tidak bisa mengubahmu, bangkit dari kematian pun tidak bisa mengubahmu. Kapan kau baru mau melihat kenyataan? Mungkin——"
  },
  AvgDialog_38846_Content_95 = {
    Text = "Tangannya menunjuk ke udara dari kejauhan, seolah menyentuh sesuatu yang tak terlihat dari jarak jauh."
  },
  AvgDialog_38846_Content_96 = {
    Text = "Yang memiliki jiwa pucat namun hangat seperti dalam ramalan, <Yellow:Penjaga>, dapat membawa lebih banyak variabel. Menurutmu, apakah {Male=dia,Female=dia} mau bergabung dengan kita?"
  },
  AvgDialog_38846_Content_97 = {
    Text = "Seekor anjing raksasa muncul dari bayang-bayang di samping wanita itu, tubuhnya yang terdistorsi ternyata memiliki kemiripan dengan Sophia yang bermutasi. Mendengar perkataan wanita itu, ia mendengus, seolah merespons."
  },
  AvgDialog_38846_Content_98 = {
    Text = "Benar juga, hari esok selalu merupakan hari yang baru."
  },
  AvgDialog_38846_Content_99 = {
    Text = "Ayo pergi, sayangku. Jika ada kesempatan, kita akan bertemu mereka lagi."
  },
  AvgDialog_43774_Content_1 = {
    Text = "Tidak lama setelah berjalan, beberapa titik hijau yang penuh kehidupan muncul dari balik bukit pasir yang terus-menerus bergelombang."
  },
  AvgDialog_43774_Content_2 = {
    Text = "Meskipun sedang musim kemarau, anak sungai kecil yang hampir kering ini mungkin agak dipaksakan disebut sebagai \"Oase di Padang Pasir\", tetapi setidaknya cukup untuk mengisi penuh kantong air kalian."
  },
  AvgDialog_43774_Content_3 = {
    Text = "Saya pergi untuk mengambil air, %player%, jagalah Ramona dengan baik."
  },
  AvgDialog_43774_Content_4 = {
    Text = "Penjaga menjaga Ramona dengan baik, dan saya menjaga Penjaga dengan baik.\nBagaimanapun, mereka yang hidup bergantung pada oasis mungkin bukan hanya para pelancong dari jauh…"
  },
  AvgDialog_43774_Content_5 = {
    Text = "Dan \"penduduk asli\", kalian setuju kan?"
  },
  AvgDialog_43775_Content_1 = {Text = "Oase"},
  AvgDialog_43775_Content_10 = {
    Text = "Wanita Narsis itu... gaya bertindaknya sungguh tak terpuji."
  },
  AvgDialog_43775_Content_11 = {
    Text = "Berdasarkan hasil perhitungan Alistair, Kolam Hitam telah mengalami fluktuasi abnormal sejak upacara pemberian kunci tahun ini."
  },
  AvgDialog_43775_Content_12 = {
    Text = "Mungkin ini adalah tanda pemulihan stabilitas Tawil. Saya sarankan departemen pemantauan untuk meningkatkan…"
  },
  AvgDialog_43775_Content_13 = {
    Text = "Tunggu sebentar."
  },
  AvgDialog_43775_Content_14 = {
    Text = "Apakah Anda punya saran, Profesor Boneka?"
  },
  AvgDialog_43775_Content_15 = {
    Text = "Saya menyarankan manusia untuk meningkatkan ketajaman organ mereka sendiri, guna menghindari membahas informasi rahasia Mythag dalam situasi invasi pihak luar."
  },
  AvgDialog_43775_Content_16 = {
    Text = "Setelah diingatkan oleh Boneka, aroma violet yang samar masuk ke dalam hidung, dan seorang wanita anggun dengan tenang bangkit dari sofa tamu."
  },
  AvgDialog_43775_Content_17 = {
    Text = "Mengapa harus begitu waspada? Laut Kabut Abu-abu telah mengirimkan informasi Kolam Hitam kepadaku beberapa hari sebelum kalian memasukkan alat-alat presisi itu ke dalam air kolam."
  },
  AvgDialog_43775_Content_18 = {
    Text = "Tanpa banyak bicara lagi, saya datang untuk mengunjungi kalian semua karena ada petunjuk penting yang bocor dari organisasi lain, dan saya ingin memberikannya kepada Tuan William ini."
  },
  AvgDialog_43775_Content_19 = {
    Text = "Tentang esensi keinginan — <Yellow:\"Pohon ibu\">."
  },
  AvgDialog_43775_Content_2 = {
    Text = "Aku juga pernah tertidur lelap, tetapi sekarang sudah bangun. \nBinatang buas di padang pasir akan datang untuk minum di ▼▼sungai, dan mereka akan beristirahat di tepi sungai itu, \nkarena tidak ada yang membuat mereka merasa takut."
  },
  AvgDialog_43775_Content_20 = {
    Text = "Intinya, karena beberapa kata-kata tak penting dari \"Wanita narsis\" ini, beberapa pria dan wanita terhormat ditinggalkan di gurun primitif yang sama sekali tidak mengikuti arus zaman."
  },
  AvgDialog_43775_Content_21 = {
    Text = "Lapisan keputusan Mythag juga tidak kalah dalam hal berjudi dibandingkan dengan saya."
  },
  AvgDialog_43775_Content_22 = {
    Text = "Setelah beberapa minggu terpapar badai pasir, mantel kesayanganku hampir habis terkikis. Entah apakah bisa mendapatkan persetujuan untuk anggaran pembaruan pakaian?"
  },
  AvgDialog_43775_Content_23 = {
    Text = "Jika Anda benar-benar akan membeli mantel baru, bukan menggunakan uang itu untuk berjudi di kasino bawah tanah, kami tidak keberatan, Tuan Ryker."
  },
  AvgDialog_43775_Content_24 = {
    Text = "Hanya dalam satu malam, kamu bisa mendapatkan cukup uang untuk membeli mantel baru dan modal untuk taruhan berikutnya. Bukankah ini sebuah kesempatan yang sangat menguntungkan?"
  },
  AvgDialog_43775_Content_25 = {
    Text = "William batuk pelan, memutus pembicaraan yang tidak bermanfaat."
  },
  AvgDialog_43775_Content_26 = {
    Text = "<Yellow:Tubuh intelektual> Tawil tertidur di Kolam Hitam Mythag, <Yellow:Tubuh kebahagiaan> berkelana di dunia manusia dalam wujud avatar, hanya <Yellow:Tubuh nafsu> yang tetap misterius keberadaannya."
  },
  AvgDialog_43775_Content_27 = {
    Text = "Berdasarkan informasi yang diberikan oleh Dafude'er, tempat Pohon Ibu berada terputus oleh <Yellow:Dinding Badai> yang tiba-tiba muncul pada tahun 225 setelah banjir, dan hingga kini sudah 90 tahun tidak ada seorang pun yang mendekat."
  },
  AvgDialog_43775_Content_28 = {
    Text = "Sementara itu, bangsa Aram sedang merencanakan ritual pengorbanan besar-besaran, dengan mencemari Pohon Ibu untuk mencapai penyebaran pelarutan pada skala global."
  },
  AvgDialog_43775_Content_29 = {
    Text = "Apa yang harus kalian lakukan adalah mengikuti suku nomaden setempat, Aram, dan merusak inti dari ritual — Pohon Ibu."
  },
  AvgDialog_43775_Content_3 = {
    Text = "Dua minggu lalu \"Operasi Lemwah\""
  },
  AvgDialog_43775_Content_30 = {
    Text = "Baiklah, baiklah. Namun, dibandingkan dengan tugas yang diberikan oleh komandan jarak jauh dengan penuh keberanian, menyelesaikan masalah di depan mata tampaknya lebih penting, bukan?"
  },
  AvgDialog_43775_Content_31 = {
    Text = [[
Lihatlah gadis kecil ini, wajahnya pucat akibat dehidrasi. 
 Jika kita tidak segera menemukan sumber air, kemungkinan besar kita semua akan mati kehausan di sini.]]
  },
  AvgDialog_43775_Content_32 = {
    Text = "Jangan bicara sembarangan, aku baik-baik saja——"
  },
  AvgDialog_43775_Content_33 = {
    Text = "Tak perlu berkeras kepala, Nona Kecil. Persediaan air kami baru saja habis diminum, tapi kau tidak menyentuh kantung air-mu sejak kemarin, kan?"
  },
  AvgDialog_43775_Content_34 = {
    Text = "Apa yang ada di dalamnya?"
  },
  AvgDialog_43775_Content_35 = {Text = "!"},
  AvgDialog_43775_Content_36 = {
    Text = "Kamu dengan kasar merebut kantung air Ramona, di dalamnya terasa berat, dan bayangan hitam yang tidak jelas bergoyang."
  },
  AvgDialog_43775_Content_37 = {
    Text = "Ryker mengangkat ujung kantong air, cairan hitam pekat pun tumpah ke bawah."
  },
  AvgDialog_43775_Content_38 = {
    Text = "Ini adalah D-lendir."
  },
  AvgDialog_43775_Content_39 = {
    Text = "Ramona, kantong air minummu... kapan?"
  },
  AvgDialog_43775_Content_4 = {
    Text = "Sebelum berangkat, tidak ada yang memberitahuku bahwa selain <Yellow:\"Pohon ibu\">, di sini juga ada ini——"
  },
  AvgDialog_43775_Content_40 = {
    Text = [[
Sekitar dua hari yang lalu. 
 Saya memperhatikan dengan seksama, tampaknya hanya air di dalam kantong air saya yang mengalami masalah ini.]]
  },
  AvgDialog_43775_Content_41 = {
    Text = "Mungkin ini ada hubungannya dengan kontak langsungmu dengan monster-monster ini?"
  },
  AvgDialog_43775_Content_42 = {
    Text = [[
Nanti kita selidiki penyebabnya, kita sangat membutuhkan tambahan persediaan air. 
Ryker?]]
  },
  AvgDialog_43775_Content_43 = {
    Text = "Mengerti, mengerti, keberuntungan baik juga tidak digunakan seperti ini kan?\nKalau aku tahu kalian membawaku bertugas untuk urusan seperti ini, pasti aku akan pura-pura sakit kepala dan demam selama dua minggu…"
  },
  AvgDialog_43775_Content_44 = {
    Text = "Ryker mengeluh, menggoyangkan hidungnya, menangkap kelembapan dalam udara panas."
  },
  AvgDialog_43775_Content_45 = {
    Text = "Pergilah ke barat, pasti ada sumber air di sana."
  },
  AvgDialog_43775_Content_6 = {
    Text = "Ramona menusuk monster bengkok yang menyerang dengan sebuah pedang, tentakel-tentakel berjuang beberapa kali, jatuh di atas bukit pasir, dan sisa-sisa itu tenggelam seolah-olah diserap oleh kerikil, hanya dalam beberapa detik hancur oleh pasir yang menggelinding."
  },
  AvgDialog_43775_Content_7 = {
    Text = "Pada akhirnya, legenda tentang \"Pohon Ibu\" yang disebut-sebut hanya memiliki catatan samar di perpustakaan Mythag."
  },
  AvgDialog_43775_Content_8 = {
    Text = "Sebagian besar wilayah Kerajaan Remouahe masih merupakan lembaran kosong dalam catatan sejarah manusia yang ada. Kecuali sesekali munculnya orang Aram di pasar, tak seorang pun tahu apa yang tersembunyi di balik badai pasir."
  },
  AvgDialog_43775_Content_9 = {
    Text = "Namun, Guru Alistair telah memastikan validitas informasi terkait Pohon Ibu yang diberikan oleh Wanita Narsis."
  },
  AvgDialog_43776_Content_1 = {Text = "Hati-hati!"},
  AvgDialog_43776_Content_10 = {
    Text = "Monster mengeluarkan teriakan mengerikan, tentakel berlendirnya bergerak lemah tak berdaya, kejang-kejang hingga mengalami pembongkaran dan menghilang."
  },
  AvgDialog_43776_Content_11 = {
    Text = "Di balik bukit pasir muncul rombongan unta. Anjing pemburu menggonggong dengan gembira dan berlari menuju wanita yang memimpin rombongan itu."
  },
  AvgDialog_43776_Content_12 = {
    Text = "Anak baik, anak baik."
  },
  AvgDialog_43776_Content_13 = {
    Text = [[
Mm, aku sudah tahu semuanya. 
 Bagus sekali, kau akan mendapatkan hadiah yang dijanjikan.]]
  },
  AvgDialog_43776_Content_14 = {
    Text = "Dia melompat dari unta, lalu menatap lurus ke matamu."
  },
  AvgDialog_43776_Content_15 = {
    Text = [[
Melihat pakaian kalian, sepertinya kalian orang dari luar daerah, ya? 
Kalian semua tampak lelah, pasti sudah mengalami beberapa kesulitan di Remwahi.]]
  },
  AvgDialog_43776_Content_16 = {
    Text = [[
Mengambil air dari Sungai Suci Aran juga bisa dianggap sebagai suatu takdir. 
 Jika tidak keberatan, bagaimana kalau kita beristirahat di perkemahan Aran bersama? Apa pendapatmu?]]
  },
  AvgDialog_43776_Content_17 = {
    Text = [[
Pada saat yang sama
Mythag Kolam Hitam]]
  },
  AvgDialog_43776_Content_18 = {
    Text = "Kamu tidak pernah memberikan informasi secara cuma-cuma, dan tidak ada sistem utang. Jika Mythag tidak membayar untuk ini, maka pasti seseorang sudah membayar di muka."
  },
  AvgDialog_43776_Content_19 = {
    Text = "Siapa yang menginginkan Penjaga Mythag muncul di gurun itu?"
  },
  AvgDialog_43776_Content_20 = {
    Text = "Bisa menipu semua orang, namun tidak bisa menipumu."
  },
  AvgDialog_43776_Content_21 = {
    Text = "Sayangnya, transaksi ini terjadi terlalu dini, sehingga saya tidak dapat mengingat wajah pelanggan tersebut dengan jelas."
  },
  AvgDialog_43776_Content_22 = {
    Text = "……Aku mengerti."
  },
  AvgDialog_43776_Content_23 = {
    Text = [[
Lermuahi
Sungai Suci]]
  },
  AvgDialog_43776_Content_24 = {
    Text = "Jadi, apakah kamu, Xiaoyu Li, dibangun oleh denyut bumi di Leremwah dan dipanggil oleh Mimpi untuk memimpin Aran?"
  },
  AvgDialog_43776_Content_25 = {
    Text = "Ini terdengar sangat keren!"
  },
  AvgDialog_43776_Content_26 = {
    Text = [[
Awalnya, aku juga tidak terlalu percaya, tetapi mimpi terus berulang setiap hari.
Mengetahui bahwa ada sekelompok orang di dunia yang menantiku, sebagai wakil Tuhan, sulit untuk tidak memberikan bantuan, bukan?]]
  },
  AvgDialog_43776_Content_27 = {
    Text = "Untung saja kamu memilih untuk merespons pemanggilan takdir dan datang, kalau tidak, entah berapa lama lagi kita akan berputar-putar seperti lalat tanpa kepala!"
  },
  AvgDialog_43776_Content_28 = {
    Text = "Merupakan kehormatan bagi Aran untuk bisa menyambut tamu seberharga Anda."
  },
  AvgDialog_43776_Content_29 = {
    Text = "Kamu membantu Ramona duduk di atas unta, tidak jauh dari sana terdengar suara tawa dan peluit Juliette dan Ryker."
  },
  AvgDialog_43776_Content_3 = {
    Text = "Ramona goyang, pedang tipisnya dengan susah payah menahan cakar tajam monster itu."
  },
  AvgDialog_43776_Content_30 = {
    Text = "Meskipun orang Aram lainnya sangat rendah hati, Juliette tetap bersikeras untuk berjalan sendiri dan memberikan unta kepada kalian."
  },
  AvgDialog_43776_Content_31 = {
    Text = "Apakah penampilannya sedikit terlalu berlebihan?"
  },
  AvgDialog_43776_Content_32 = {
    Text = "Kalian ini, harus ada seseorang yang bertanggung jawab untuk mendekatkan hubungan dengan penduduk setempat."
  },
  AvgDialog_43776_Content_33 = {
    Text = "Ah, pemuda ini, bukan hanya kemampuan bermain kartunya yang luar biasa, tetapi juga daya tarik pribadinya hampir sebanding denganku."
  },
  AvgDialog_43776_Content_34 = {
    Text = [[
Semoga Tuan Mulia tidak salah memahami penggunaan kata "tidak berbeda jauh". 
 Aku masih ingat ekspresi kecewamu setelah bermain poker semalaman dengan Ryker.]]
  },
  AvgDialog_43776_Content_35 = {
    Text = "Sebagai penembak terbaik di meja permainan Londinium, dia merasakan kekalahan untuk pertama kalinya dan sedikit kecewa. Namun, hal ini masih bisa dimengerti."
  },
  AvgDialog_43776_Content_36 = {
    Text = "Pada hari itu, kamu kehilangan semua uangmu dan tidak makan sarapan keesokan harinya."
  },
  AvgDialog_43776_Content_37 = {
    Text = "Pasien sebaiknya tidak berdebat, istirahatlah dengan baik."
  },
  AvgDialog_43776_Content_38 = {
    Text = "Ramona di pelukanmu berbicara dengan suara serak. Sensasi panas yang berbeda dari udara menyampaikan getaran melalui guncangan kepadamu."
  },
  AvgDialog_43776_Content_39 = {
    Text = "Demam tinggi datang secara tidak wajar, kamu memiliki firasat buruk."
  },
  AvgDialog_43776_Content_4 = {
    Text = "Dan di belakang——"
  },
  AvgDialog_43776_Content_40 = {
    Text = "Lihat ke sana."
  },
  AvgDialog_43776_Content_41 = {
    Text = "Detak cemas menyebar di antara langit dan bumi bersamaan dengan angin berpasir, debu yang terhirup menciptakan rasa sesak napas yang tak terjelaskan."
  },
  AvgDialog_43776_Content_42 = {
    Text = "Suara genta unta terdengar jauh dan panjang, di ujung pandangan, udara panas membuat matahari terbenam tampak berdenyut. Di tepi cakrawala, titik-titik kemah seperti fatamorgana yang samar-samar muncul."
  },
  AvgDialog_43776_Content_43 = {
    Text = "Setelah berminggu-minggu berjalan, kalian akhirnya menemukan target dari penyelidikan kali ini — Aram."
  },
  AvgDialog_43776_Content_44 = {
    Text = "Di depan adalah pemukiman Aram, untuk berjaga-jaga, aku akan bergerak terpisah dari kalian."
  },
  AvgDialog_43776_Content_45 = {
    Text = "Kebetulan, ada beberapa hal yang ingin saya lakukan penyelidikan..."
  },
  AvgDialog_43776_Content_5 = {
    Text = "Ramona tidak sempat berbalik, tentakel monster yang muncul dari pasir berkumpul seperti duri, menusuk lurus ke punggungnya dari udara ——"
  },
  AvgDialog_43776_Content_6 = {Text = "Ding——"},
  AvgDialog_43776_Content_7 = {
    Text = "Seekor anjing pemburu berbadan besar meloncat dari sisi dan menjatuhkan monster itu ke tanah."
  },
  AvgDialog_43776_Content_8 = {
    Text = "Monster yang diserang mengulurkan tentakel berdarahnya, siap mencekik leher anjing pemburu yang sedang menggigit."
  },
  AvgDialog_43776_Content_9 = {
    Text = "Ramona berguling ke belakang, pedang tipisnya dengan cekatan menancap ke mata monster itu."
  },
  AvgDialog_43777_Content_10 = {
    Text = "\"Pohon Ibu\", adalah salah satu dari <Yellow:tiga besar plasmon>——<Yellow:Plasmon Keinginan Tifeleisod> yang bertindak sebagai perwakilan di dunia."
  },
  AvgDialog_43777_Content_11 = {
    Text = "Penelitian terkait kerangka Pohon Ibu mungkin akan menjadi pilar penting bagi kita untuk memahami Fenomena-d."
  },
  AvgDialog_43777_Content_12 = {
    Text = "Sekarang, upacara pembukaan peti secara resmi dimulai."
  },
  AvgDialog_43777_Content_13 = {
    Text = "Haruskah memanggil murid untuk membantu?"
  },
  AvgDialog_43777_Content_14 = {
    Text = "Tidak perlu repot, hanya mendorong peti mati saja."
  },
  AvgDialog_43777_Content_15 = {
    Text = "Kabarnya, anak-anak Kerajaan Elke sejak kecil sudah berkelahi dengan beruang. Sepertinya Dekan Czort juga memiliki kemampuan yang luar biasa."
  },
  AvgDialog_43777_Content_16 = {
    Text = "Czort melangkah maju, menarik napas dalam-dalam, otot-ototnya menegang, lalu mengumpulkan seluruh kekuatannya untuk mendorong ke depan dengan segenap tenaga ——"
  },
  AvgDialog_43777_Content_17 = {
    Text = "Tutup peti sama sekali tidak bergerak."
  },
  AvgDialog_43777_Content_18 = {
    Text = [[
Masih menganggap dirimu seperti saat masih muda? 
 Apakah kamu tidak sadar sudah berapa lama kamu tidak masuk ke ruang latihan?]]
  },
  AvgDialog_43777_Content_19 = {
    Text = "Astaga, urusan Dekan Czort yang begitu rumit bukanlah sesuatu yang diinginkan olehnya."
  },
  AvgDialog_43777_Content_2 = {Text = "Thais"},
  AvgDialog_43777_Content_20 = {
    Text = "Saya akan mencobanya."
  },
  AvgDialog_43777_Content_21 = {
    Text = "Pandanganmu menyapu seluruh peti mati, menyapu lapisan cat hitam dan emas yang terkelupas di permukaannya, menyapu pola-pola rumit yang diukir di sekitar badan peti, dan menyapu batu-batu permata berkilauan yang menghiasi keempat sudutnya."
  },
  AvgDialog_43777_Content_22 = {
    Text = "Kamu mendorong tutup peti, namun tutup peti tetap diam."
  },
  AvgDialog_43777_Content_23 = {
    Text = "Kamu menggertakkan gigi, mengangkat tanganmu, dan menggigit ujung jari telunjukmu hingga berdarah. Menahan rasa sakit, kamu menggoreskan darah di atas peti mati ——"
  },
  AvgDialog_43777_Content_24 = {
    Text = "Disertai dengan suara gemuruh yang menggelegar, peti mati perlahan-lahan terbuka."
  },
  AvgDialog_43777_Content_25 = {
    Text = "Di dalam peti mati terbaring diam sesuatu yang dulunya adalah mumi ——"
  },
  AvgDialog_43777_Content_26 = {
    Text = "Dahulu adalah mumi, tetapi sekarang hanya tersisa selembar kain linen kuno, genangan perban yang berantakan, dan cairan hitam kental yang bergolak."
  },
  AvgDialog_43777_Content_27 = {
    Text = "Kirimkan ke departemen inspeksi untuk menganalisis komposisi peti mati dan kain linen."
  },
  AvgDialog_43777_Content_28 = {
    Text = "Melalui pemeriksaan bertahun-tahun, mungkin dapat disimpulkan identitas pemilik mumi tersebut."
  },
  AvgDialog_43777_Content_29 = {
    Text = "Tidak perlu."
  },
  AvgDialog_43777_Content_3 = {
    Text = "\"Operasi Lemwah\"berakhir satu minggu kemudian"
  },
  AvgDialog_43777_Content_30 = {
    Text = "Saya tahu siapa dia."
  },
  AvgDialog_43777_Content_31 = {
    Text = "Kamu menyentuh dengan lembut tulisan terukir di bagian dalam peti mati, merasakan tekstur yang tidak rata secara perlahan membentuk nama yang sudah sangat kamu kenal di hati."
  },
  AvgDialog_43777_Content_32 = {Text = "Thais."},
  AvgDialog_43777_Content_33 = {
    Text = "Semoga dia mendapatkan ketenangan di sini."
  },
  AvgDialog_43777_Content_4 = {
    Text = "Sebuah peti mati megah tergeletak di bawah tanah Mythag. Warna hitam keemasan yang melambangkan keabadian mengingatkanmu pada asal-usulnya dan sejarah yang tersembunyi di baliknya."
  },
  AvgDialog_43777_Content_5 = {
    Text = "Itu tampak begitu khidmat dan megah, menceritakan tentang kemuliaan yang telah hilang dari peradaban yang dulunya makmur, serta cerita luas yang penuh dengan nyanyian yang kau alami."
  },
  AvgDialog_43777_Content_6 = {
    Text = "Ini adalah jarahan yang disita oleh Penjaga selama operasi \"Lemwah\" kali ini."
  },
  AvgDialog_43777_Content_7 = {
    Text = "Isi dari peti mati disebut oleh suku nomaden setempat, Aram, sebagai \"Kerangka Pohon Ibu\"."
  },
  AvgDialog_43777_Content_8 = {
    Text = "Pandanganmu tertuju pada pola ukiran di bagian tengah peti mati."
  },
  AvgDialog_43777_Content_9 = {
    Text = "Pola pohon tertanam dalam pelat penutup yang materialnya tidak diketahui. Mahkota pohon lebat, akar saling berbelit, dan warna gelapnya memantulkan cahaya redup yang samar."
  },
  AvgDialog_43788_Content_1 = {
    Text = "Ngomong-ngomong, Ryker, kemarilah sebentar."
  },
  AvgDialog_43788_Content_10 = {
    Text = "Aduh, Yu Li memang punya beberapa cara yang cukup unik."
  },
  AvgDialog_43788_Content_100 = {
    Text = [[
Jadi, begitu ya!
Kalau begitu, kau pasti seorang pelancong yang sedang mengunjungi Remwahi!]]
  },
  AvgDialog_43788_Content_101 = {
    Text = [[
Rumwah sudah lama tidak kedatangan tamu baru! 
 Aku akan segera mengatur pesta api unggun terbesar, kau harus benar-benar bersenang-senang!]]
  },
  AvgDialog_43788_Content_102 = {
    Text = "Pesta malam?"
  },
  AvgDialog_43788_Content_103 = {
    Text = "Benar! Meskipun kurang pengetahuan dari luar, hati orang Aram tidak tertutup."
  },
  AvgDialog_43788_Content_104 = {
    Text = "Selama kamu mengikuti pesta malam, kamu dianggap sebagai anggota keluarga Aran!"
  },
  AvgDialog_43788_Content_105 = {
    Text = "Sebagai salah satu dari kita, selama kamu berjanji untuk tidak menyebarkan apa yang terjadi di dalam tenda, kamu tidak perlu menerima hukuman."
  },
  AvgDialog_43788_Content_106 = {
    Text = "Rasakan semangat hangat orang Aram di dalam jamuan malam ini!"
  },
  AvgDialog_43788_Content_11 = {
    Text = "Begitu kalian tiba di perkemahan, sekelompok penduduk yang mengenakan pakaian gaya Yalan segera mengepung unta Juliette."
  },
  AvgDialog_43788_Content_12 = {
    Text = "Nyonya Juliette telah kembali, cepat bawa persembahan yang sudah disiapkan!"
  },
  AvgDialog_43788_Content_13 = {
    Text = "Apakah Juliette sudah membawa tamu kembali?"
  },
  AvgDialog_43788_Content_14 = {
    Text = "Nona Juliette, kami menemukan kumpulan Nubia sejauh delapan ratus meter di selatan, jumlahnya sekitar tiga puluh!"
  },
  AvgDialog_43788_Content_15 = {
    Text = [[
Mengerti. Aku akan menanganinya satu per satu. 
Apakah Alva ada di tenda Ratu?]]
  },
  AvgDialog_43788_Content_16 = {
    Text = "Kepala Suku membawa tim untuk memastikan situasi di Nubia."
  },
  AvgDialog_43788_Content_17 = {
    Text = "Mengerti. Saya akan membawa beberapa tamu untuk beristirahat terlebih dahulu, silakan tunggu saya di tenda kepala suku."
  },
  AvgDialog_43788_Content_18 = {
    Text = "Orang-orang Aram berhamburan, Juliette menarik kendali kuda dan berbalik ke arah kalian."
  },
  AvgDialog_43788_Content_19 = {
    Text = "Seperti yang kalian lihat, urusan suku Alan sangat banyak. Sebagai utusan, saya juga sering membantu mereka menangani beberapa tugas kecil."
  },
  AvgDialog_43788_Content_2 = {Text = "Hm?"},
  AvgDialog_43788_Content_20 = {
    Text = [[
Namun, untuk bermalam di sini tetap memerlukan persetujuan dari Ratu dan Kepala Suku. 
Kalian bisa beristirahat dulu di tendaku, atau mencoba berinteraksi dengan orang-orang Aram.]]
  },
  AvgDialog_43788_Content_22 = {
    Text = "……………"
  },
  AvgDialog_43788_Content_23 = {
    Text = "Mari kita rangkum informasi."
  },
  AvgDialog_43788_Content_24 = {
    Text = "Menurut Juliette, <Yellow:Pohon Ibu> telah layu sebelum <Yellow:Dinding Badai> muncul."
  },
  AvgDialog_43788_Content_25 = {
    Text = "Karena kematian Pohon Ibu, anak sungai Sungai Suci semakin menyusut, desertifikasi semakin parah, dan sekarang sudah tidak cukup untuk menopang kelangsungan hidup banyak desa kecil."
  },
  AvgDialog_43788_Content_26 = {
    Text = "Regu ini membawa kerangka Pohon Ibu, mencari kesempatan untuk memasuki Dinding Badai guna membangun kembali Pohon Ibu."
  },
  AvgDialog_43788_Content_27 = {
    Text = "Monster yang bernama Nubia, baru-baru ini muncul di Remwahi."
  },
  AvgDialog_43788_Content_28 = {
    Text = "Peradaban Aram cukup primitif. Menghancurkan Pembangun Nubia di Juliette membuat mereka dianggap sebagai utusan yang memiliki \"kekuatan dewa\"."
  },
  AvgDialog_43788_Content_29 = {
    Text = "Berhenti sejenak, ada orang yang datang."
  },
  AvgDialog_43788_Content_3 = {
    Text = "Sebelum memasuki permukiman, tetap perlu menangani masalah penampilanmu terlebih dahulu."
  },
  AvgDialog_43788_Content_30 = {
    Text = "Para hadirin, apakah kalian sudah beristirahat dengan cukup?"
  },
  AvgDialog_43788_Content_31 = {
    Text = "Jika memungkinkan, utuslah seorang perwakilan untuk menghadap Ratu."
  },
  AvgDialog_43788_Content_33 = {
    Text = [[
Langit semakin gelap, matahari terbenam berwarna merah darah. 
Elang gurun berputar beberapa kali, memancarkan suara tangisan panjang terakhirnya, lalu hinggap di dahan kering yang mati.]]
  },
  AvgDialog_43788_Content_34 = {
    Text = "Di bawah bimbingan Juliette, kamu tiba di depan sebuah tenda dengan desain yang unik."
  },
  AvgDialog_43788_Content_35 = {
    Text = "Inilah kemah Ratu. Menurut tradisi Aram, semua tamu terhormat perlu mendapatkan izin dari kepala suku di bawah pengawasan Ratu."
  },
  AvgDialog_43788_Content_36 = {
    Text = "Kamu tunggu kepala suku di sini, aku akan menyelesaikan urusan tadi terlebih dahulu."
  },
  AvgDialog_43788_Content_37 = {
    Text = "Ingat, jangan masuk."
  },
  AvgDialog_43788_Content_38 = {
    Text = "Jika saya menyinggung Ratu, bantuan yang dapat saya berikan akan sangat terbatas."
  },
  AvgDialog_43788_Content_4 = {
    Text = "Harap bawa wewangian ini di barang bawaanmu kapan saja. Bisa diselipkan di dasi, digantung di tongkat, atau dimasukkan ke telinga, terserah."
  },
  AvgDialog_43788_Content_40 = {
    Text = "Angin sepoi-sepoi sedikit mengangkat tirai, pemandangan di dalam tenda tampak samar-samar melalui celah."
  },
  AvgDialog_43788_Content_41 = {
    Text = "Sebuah keinginan yang tak terdefinisikan menyusup ke tenggorokanmu, membuatmu tak mampu menahan hasrat untuk mencari tahu lebih lanjut."
  },
  AvgDialog_43788_Content_42 = {
    Text = "Entah mengapa, ada suara samar yang memberitahumu bahwa segala sesuatu yang kamu cari dalam perjalanan ini tersembunyi di dalam tenda ini. Kamu harus menyingkap tirai untuk mendapatkan jawabannya."
  },
  AvgDialog_43788_Content_43 = {
    Text = "Tak ada seorang pun di sekitar, hanya suara angin yang menderu-deru menggulung pasir dan kerikil."
  },
  AvgDialog_43788_Content_44 = {
    Text = "Masuk ke tenda"
  },
  AvgDialog_43788_Content_45 = {
    Text = "Mengintip ke dalam tenda"
  },
  AvgDialog_43788_Content_46 = {
    Text = "Tidak melakukan apa pun"
  },
  AvgDialog_43788_Content_47 = {
    Text = "Kamu tidak terlalu familiar dengan situasi Aram. Jika melewatkan kesempatan saat ini, entah kapan lagi bisa mendekati tempat ini."
  },
  AvgDialog_43788_Content_48 = {
    Text = "Tanpa ragu-ragu, kamu memanfaatkan kesempatan saat tidak ada orang di sekitar, lalu dengan hati-hati membuka tirai dan masuk ke dalam tenda."
  },
  AvgDialog_43788_Content_49 = {
    Text = [[
Hanya dengan melihat sekilas, meskipun tertangkap, ada cara untuk menghindari konsekuensi. 
 Dengan pemikiran itu, kamu perlahan-lahan mengangkat tirai dan mengintip ke dalam.]]
  },
  AvgDialog_43788_Content_5 = {
    Text = "Ryker menerima sepotong kecil pewangi, menjulurkan satu jarinya, dan menempelkannya di dalam sarung tangan kirinya."
  },
  AvgDialog_43788_Content_50 = {
    Text = "Perasaan pusing tiba-tiba menyerang, dan beberapa detik kemudian dunia di depan mata baru kembali menjadi jelas."
  },
  AvgDialog_43788_Content_51 = {
    Text = [[
Sejauh ini, kamu mengetahui sangat sedikit tentang suku Alan.
Untuk berjaga-jaga, sebaiknya tidak melakukan apa pun.]]
  },
  AvgDialog_43788_Content_52 = {
    Text = [[
Tawa yang memikat, mirip dengan mutiara berkilauan yang menggelinding, terdengar dari belakang. 
Dari bawah pintu kemah, muncul selembar kain sutra putih yang lembut.]]
  },
  AvgDialog_43788_Content_53 = {
    Text = "Perasaan pusing tiba-tiba menyerang, dan beberapa detik kemudian dunia di depan mata baru kembali menjadi jelas."
  },
  AvgDialog_43788_Content_54 = {
    Text = "Di tengah tenda kubah yang menjadi fokus pandangan, terdapat sebuah peti mati."
  },
  AvgDialog_43788_Content_55 = {
    Text = "Seolah-olah terpesona oleh suatu kekuatan, saat kesadaranmu pulih, kamu sudah berdiri di samping peti mati, mengulurkan tangan untuk menyentuh sudut emas yang indah dengan permata yang tersemat."
  },
  AvgDialog_43788_Content_56 = {
    Text = "<Gray:Ini adalah——>"
  },
  AvgDialog_43788_Content_57 = {
    Text = "Kamu terperangkap dalam ilusi pohon."
  },
  AvgDialog_43788_Content_58 = {
    Text = "Benih tenggelam ke dalam tanah hitam yang lembap dan subur. Akar yang rapuh menembus kulit biji yang keras, kemudian muncul dari tanah."
  },
  AvgDialog_43788_Content_59 = {
    Text = "Tak terhitung cabang berubah menjadi tentakel yang menari-nari, berlomba-lomba memanjat tangga tak terlihat menuju langit. Daun dan ranting yang bergetar mengeluarkan raungan tangis yang mengerikan."
  },
  AvgDialog_43788_Content_60 = {
    Text = "Kemudian pembuluh darah pada tonjolan pohon yang bengkak meledak, menyemburkan nanah hitam kental yang berjatuhan ke sungai jernih yang berkilauan seperti es terapung."
  },
  AvgDialog_43788_Content_61 = {Text = "Bum!"},
  AvgDialog_43788_Content_62 = {
    Text = "Pohon itu roboh dengan suara gemuruh, sepotong kayu apung yang sudah lapuk mengikuti aliran air. Bentuk kayu apung tersebut mirip dengan peti mati..."
  },
  AvgDialog_43788_Content_63 = {
    Text = "...Inilah...kerangka Pohon Ibu."
  },
  AvgDialog_43788_Content_64 = {
    Text = "Apa yang harus kalian lakukan adalah mengikuti suku nomaden setempat, Aram, dan merusak inti dari ritual — Pohon Ibu."
  },
  AvgDialog_43788_Content_65 = {
    Text = "Menurut Juliette, Pohon Ibu telah layu sebelum Dinding Badai muncul."
  },
  AvgDialog_43788_Content_66 = {
    Text = "Regu ini membawa kerangka Pohon Ibu, mencari kesempatan untuk memasuki Dinding Badai guna membangun kembali Pohon Ibu."
  },
  AvgDialog_43788_Content_67 = {
    Text = "Artinya, kau hanya perlu menerjang, membakar sisa pohon suci dalam peti mati, maka tujuan utama dari aksi ini tercapai."
  },
  AvgDialog_43788_Content_68 = {
    Text = "Bagaimana cara keluar dari kepungan Aram setelah itu? Apakah masih ada waktu untuk memikirkannya saat itu tiba?"
  },
  AvgDialog_43788_Content_69 = {
    Text = "Hatimu berdebar-debar, pikiran antara afirmasi dan negasi saling bertautan menjadi gulungan yang rumit."
  },
  AvgDialog_43788_Content_7 = {
    Text = "Ramona, apa yang terjadi padamu?"
  },
  AvgDialog_43788_Content_70 = {
    Text = "Suara nyanyian seperti doa terdengar ——"
  },
  AvgDialog_43788_Content_71 = {
    Text = "Kematian sudah mendekat, kehancuran telah dimulai."
  },
  AvgDialog_43788_Content_72 = {
    Text = "Kerangka ibu tidak terlihat, darah dan benih hanyut di bumi, dilahap oleh binatang liar yang baru lahir."
  },
  AvgDialog_43788_Content_73 = {
    Text = "Langit dan para dewa dipenuhi awan mendung, hingga Kedatangan utusan dari negeri asing."
  },
  AvgDialog_43788_Content_74 = {
    Text = "Pohon Ibu melahirkan kembali Sungai Suci, memberikan mahkota kepada yang telah tiada, dan mengembalikan garis keturunan kepada Alen."
  },
  AvgDialog_43788_Content_75 = {
    Text = "Mengapa yang terlihat di depan mata hanyalah kegelapan?"
  },
  AvgDialog_43788_Content_76 = {
    Text = "Siapa lagi yang bernyanyi?"
  },
  AvgDialog_43788_Content_77 = {
    Text = "Tamu yang datang dari jauh..."
  },
  AvgDialog_43788_Content_78 = {
    Text = "Tawa kecil membuyarkan pikiranmu. Kamu mengangkat kepala dan tanpa sadar, sosok seorang wanita telah muncul di atas peti mati."
  },
  AvgDialog_43788_Content_79 = {
    Text = "Matanya penuh dengan senyuman, kedua tangannya mengangkat ujung roknya seperti seorang pengantin yang mengangkat gaunnya, lalu ia membungkuk untuk memandangmu dari atas."
  },
  AvgDialog_43788_Content_8 = {
    Text = "Kamu melihat wajah Ryker."
  },
  AvgDialog_43788_Content_80 = {
    Text = "Saya Thais, Ratu Aran. Tamu yang datang dari jauh, apakah kamu telah menyiapkan hadiah?"
  },
  AvgDialog_43788_Content_81 = {
    Text = "Dia melompat turun dari peti mati, langsung berjalan ke sisimu, dengan pandangan yang cerdik mengitari dirimu."
  },
  AvgDialog_43788_Content_82 = {
    Text = "Apa kejutan yang bisa kau berikan padaku, {Male=tuan,Female=nyonya} muda ini?"
  },
  AvgDialog_43788_Content_84 = {
    Text = "Juliette memilih untuk memungkinkanmu bertemu denganku di bawah pengawasan Ratu, yang berarti kamu adalah tamu yang sangat terhormat."
  },
  AvgDialog_43788_Content_85 = {
    Text = "Apakah dia tidak memberitahumu tentang hukuman apa yang akan diterima jika mengganggu Sang Ratu?"
  },
  AvgDialog_43788_Content_86 = {
    Text = "Tirai tenda didorong terbuka, seorang wanita Aran berusia akhir tiga puluhan dengan wajah serius melangkah masuk ke dalam tenda dengan langkah besar."
  },
  AvgDialog_43788_Content_87 = {
    Text = "Thais dengan panik melompat kembali ke atas peti mati, memperlihatkan sikap anggun yang layaknya seorang ratu angkuh di atas takhta."
  },
  AvgDialog_43788_Content_88 = {
    Text = "Tamu yang terhormat, ..."
  },
  AvgDialog_43788_Content_89 = {
    Text = "Suara yang dibuat-buatnya tiba-tiba terputus oleh kedatangan orang itu."
  },
  AvgDialog_43788_Content_9 = {
    Text = "De. Mulia Dexter!"
  },
  AvgDialog_43788_Content_90 = {
    Text = "Alva, pemimpin Suku Alan."
  },
  AvgDialog_43788_Content_91 = {
    Text = "Juliette telah memperkenalkan asalmu kepadaku."
  },
  AvgDialog_43788_Content_92 = {
    Text = "Namun, bagian terpenting dari perkenalannya hilang — Pemuda, mengapa kamu datang ke Lemwah?"
  },
  AvgDialog_43788_Content_93 = {
    Text = "Kamu terkejut oleh pertanyaan yang tiba-tiba, dan otakmu secara naluriah memberikan reaksi ——"
  },
  AvgDialog_43788_Content_94 = {
    Text = "Melakukan eksplorasi ilmiah"
  },
  AvgDialog_43788_Content_95 = {
    Text = "Wisata dan Pengamatan"
  },
  AvgDialog_43788_Content_96 = {
    Text = "...memang tidak ada tujuan lain?"
  },
  AvgDialog_43788_Content_97 = {
    Text = "Pandangannya yang tajam menusuk langsung ke matamu, seolah-olah ingin menembus kebohonganmu."
  },
  AvgDialog_43788_Content_98 = {
    Text = "Kamu berusaha menenangkan diri, menyembunyikan kepanikanmu, dan menjawab pertanyaannya dengan tenang."
  },
  AvgDialog_43789_Content_1 = {Text = "Permukiman"},
  AvgDialog_43789_Content_2 = {
    Text = "Seekor kuda cepat datang berlari dari kemah dan berhenti mendadak di depan Juliette."
  },
  AvgDialog_43789_Content_3 = {
    Text = "Teman-teman, sepertinya ada tugas mendesak."
  },
  AvgDialog_43789_Content_4 = {
    Text = "Baru saja kita menangkal monster, penduduk setempat menyebut mereka \"Nubia\". Saat ini, ada sekelompok kecil yang sedang mengamati perkemahan dengan penuh ancaman."
  },
  AvgDialog_43789_Content_5 = {
    Text = "Untuk keamanan perkemahan, aku harus membersihkannya terlebih dahulu."
  },
  AvgDialog_43789_Content_6 = {
    Text = "Lebih baik bersama-sama!"
  },
  AvgDialog_43789_Content_7 = {
    Text = "Hanya khawatir akan terlalu merepotkan kalian semua."
  },
  AvgDialog_43789_Content_8 = {
    Text = "Urusan Yu Li adalah urusan kita juga. Jangan khawatir, beberapa Nubia saja tidak masalah."
  },
  AvgDialog_43802_Content_1 = {
    Text = "Di sini adalah..."
  },
  AvgDialog_43802_Content_2 = {
    Text = [[
Lautan kesadaran Pohon Ibu.
Dengan menelusuri kembali peti mati dari kerangka Pohon Ibu, kamu bisa tiba di sini.]]
  },
  AvgDialog_43802_Content_3 = {
    Text = "Anak ini... terlalu dekat dengan akar Pohon Ibu, sehingga terlalu jauh dari dunia ini untuk bisa menyatu."
  },
  AvgDialog_43802_Content_4 = {
    Text = "Suara berderak perak membimbing kalian, maju menuju tepi yang jauh."
  },
  AvgDialog_43802_Content_5 = {
    Text = "Apakah kalian bisa mendengar suara?"
  },
  AvgDialog_43802_Content_6 = {
    Text = "Suara tetesan air. Dengungan resonansi Perak."
  },
  AvgDialog_43802_Content_7 = {
    Text = "Perhatikan dengan cermat."
  },
  AvgDialog_43802_Content_8 = {
    Text = "Tangisan hidup. Tangisan pertama bayi yang baru lahir, tetesan air mata terakhir yang jatuh dari seorang tua renta karena hidup mengalir pergi."
  },
  AvgDialog_43802_Content_9 = {
    Text = "Air mata yang mengalir berubah menjadi makhluk pelarutan berbentuk lubang segitiga dalam hitungan detik, melesat ke arah kalian dengan kecepatan luar biasa dan keganasan yang menakutkan."
  },
  AvgDialog_43803_Content_1 = {
    Text = "Pesta Megah"
  },
  AvgDialog_43803_Content_10 = {
    Text = "Kamu seharusnya beristirahat dengan baik."
  },
  AvgDialog_43803_Content_100 = {
    Text = "Tiba-tiba, suara lonceng yang tidak diketahui dari mana asalnya berbunyi, dan kamu pun tersadar."
  },
  AvgDialog_43803_Content_101 = {
    Text = [[
Rasa takut yang tak terkendali langsung muncul, kamu buru-buru melepaskan diri dari pelukan Thais.
Ketika berbalik, kamu melihat dia masih menatapmu dengan penuh antusiasme.]]
  },
  AvgDialog_43803_Content_102 = {
    Text = "Ramona duduk dari tempat tidurnya, mata dinginnya menatap penuh semangat pada Thais."
  },
  AvgDialog_43803_Content_103 = {
    Text = "<Change>{Male=dia,Female=dia} bukan rakyatmu"
  },
  AvgDialog_43803_Content_104 = {
    Text = "<Change>Kamu tidak bisa memaksa {Male=dia,Female=dia}"
  },
  AvgDialog_43803_Content_105 = {
    Text = "<Change>S...-N...igath..."
  },
  AvgDialog_43803_Content_106 = {
    Text = [[
Meskipun suara itu keluar melalui pita suara Ramona, kamu dengan jelas memahami bahwa itu bukan bahasa Ramona.
Itu adalah suara dari dimensi yang lebih tinggi yang bersemayam di dalam dirinya.]]
  },
  AvgDialog_43803_Content_107 = {
    Text = "Baiklah, benar-benar pelit. \nJarang sekali menemukan benih sebagus ini…"
  },
  AvgDialog_43803_Content_108 = {
    Text = "Thais dengan berat hati melepaskan lenganmu, berbalik dan meninggalkan kemah, hanya menyisakan sepatah kata yang penuh makna."
  },
  AvgDialog_43803_Content_109 = {
    Text = [[
Kita pasti akan bertemu lagi. 
 Lain kali, jangan lepaskan tangan saya lagi.]]
  },
  AvgDialog_43803_Content_11 = {
    Text = "Tidak, aku tidak tahu kenapa, selalu ada suara yang mengingatkanku bahwa penyelidikan kali ini... harus aku yang melakukannya."
  },
  AvgDialog_43803_Content_12 = {
    Text = "Ramona berbicara dengan nada tegas, dan kau juga memiliki dugaan tentang hal itu. Baik secara emosional maupun logis, sulit untuk membantahnya."
  },
  AvgDialog_43803_Content_13 = {
    Text = "Di mana Ryker?"
  },
  AvgDialog_43803_Content_14 = {
    Text = [[
Dia sedang berbaur dengan orang-orang Aram di luar. 
Berkat dia, setidaknya kita sudah memahami situasi orang-orang Aram ini.]]
  },
  AvgDialog_43803_Content_15 = {
    Text = "Seperti yang kita ketahui, beberapa tahun yang lalu, Pohon Ibu menghilang dalam semalam. Setelah itu, Dinding Badai menutupi situs Pohon Ibu, yang juga merupakan sumber Sungai Suci."
  },
  AvgDialog_43803_Content_16 = {
    Text = "Tidak lama kemudian, utusan dalam nyanyian itu mengunjungi Juliette atas bimbingan Mimpi, dan membantu orang Aram mengusir kelompok Nubia serta mendekati Dinding Badai."
  },
  AvgDialog_43803_Content_17 = {
    Text = "Namun, mereka mengalami hambatan saat mencoba menembus Dinding badai."
  },
  AvgDialog_43803_Content_18 = {
    Text = "Semua konten tersebut tercatat dalam lagu rakyat yang diwariskan secara turun-temurun oleh Suku Alan."
  },
  AvgDialog_43803_Content_19 = {
    Text = "Semakin Ramona berbicara, semakin pucat wajahnya."
  },
  AvgDialog_43803_Content_2 = {
    Text = "Pesta Api Unggun?"
  },
  AvgDialog_43803_Content_20 = {
    Text = "Masih merepotkanmu, Boneka, untuk menjelaskan isi dari lagu tersebut."
  },
  AvgDialog_43803_Content_21 = {
    Text = [[
Aku tidak akan membacakan puisi bodoh itu. 
 Dalam hal memperkuat memori dan pengulangan, ada ahli yang lebih mahir daripada aku.]]
  },
  AvgDialog_43803_Content_22 = {
    Text = "Erica, siap melayani Anda——"
  },
  AvgDialog_43803_Content_23 = {
    Text = "Kematian sudah mendekat, kehancuran telah dimulai."
  },
  AvgDialog_43803_Content_24 = {Text = "Tunggu—"},
  AvgDialog_43803_Content_25 = {
    Text = "Erica tampaknya tidak mendengar instruksimu, ia terus membaca secara mekanis."
  },
  AvgDialog_43803_Content_26 = {
    Text = "Kerangka ibu tidak terlihat, darah dan benih hanyut di bumi, dilahap oleh binatang liar yang baru lahir."
  },
  AvgDialog_43803_Content_27 = {
    Text = "Langit dan para dewa dipenuhi awan mendung, hingga Kedatangan utusan dari negeri asing."
  },
  AvgDialog_43803_Content_28 = {
    Text = "Utusan——Kedatangan——Kretek——Kedatangan——Kretek——Hihi, Utusan——"
  },
  AvgDialog_43803_Content_29 = {
    Text = "Suara yang tajam dan dingin, tanpa emosi, tiba-tiba bergema di dalam tenda."
  },
  AvgDialog_43803_Content_3 = {
    Text = "Juliette menampakkan raut ragu."
  },
  AvgDialog_43803_Content_30 = {Text = "Sebentar."},
  AvgDialog_43803_Content_31 = {
    Text = "Suara alarm mekanis berbunyi, diikuti oleh suara halaman kertas dibalik, suara sekrup diputar, dan benturan logam yang berdentang."
  },
  AvgDialog_43803_Content_32 = {
    Text = "Maaf, saya baru saja memeriksa kondisi pemeliharaan Erica, dan belum menemukan penyebab kerusakannya."
  },
  AvgDialog_43803_Content_33 = {
    Text = "Tidak penting lagi, lagu ini tinggal satu kalimat terakhir, biar aku saja yang menyelesaikannya…"
  },
  AvgDialog_43803_Content_34 = {
    Text = "… Pohon Ibu melahirkan kembali Sungai Suci, memberikan mahkota kepada yang telah tiada, dan mengembalikan darah kehidupan kepada Aran."
  },
  AvgDialog_43803_Content_35 = {
    Text = "Dari segi efisiensi komunikasi, jika kamu memberi tahu lebih awal bahwa kamu sudah mendengarnya, kita bisa menghemat banyak waktu."
  },
  AvgDialog_43803_Content_36 = {
    Text = "Apa yang kamu lihat di tenda Ratu?"
  },
  AvgDialog_43803_Content_37 = {
    Text = "Sebelum kamu sempat berbicara, terdengar seruan penuh semangat dari luar tenda."
  },
  AvgDialog_43803_Content_38 = {
    Text = "Para tamu yang terhormat, jamuan makan malam sudah siap!"
  },
  AvgDialog_43803_Content_39 = {
    Text = "Setelah ragu selama beberapa saat, kamu berbisik di telinga Ramona dan memberitahunya informasi yang paling penting."
  },
  AvgDialog_43803_Content_4 = {
    Text = "Seperti yang aku sebutkan sebelumnya, Suku Alan sebagai suku primitif memiliki banyak tradisi \"unik\" yang mungkin sulit dipahami oleh orang luar."
  },
  AvgDialog_43803_Content_40 = {
    Text = "Sisa pohon suci ada di dalam tenda ratu."
  },
  AvgDialog_43803_Content_41 = {
    Text = "Anda begitu tampan dan humoris, sepertinya bahkan Tuan Alva pun bisa terpikat oleh Anda!"
  },
  AvgDialog_43803_Content_42 = {
    Text = "Anda terlalu memuji. Saya justru mendengar bahwa yang paling pandai bercerita di sini adalah Nona Juliette."
  },
  AvgDialog_43803_Content_43 = {
    Text = "Apakah Anda berbicara tentang Yang Mulia Utusan?"
  },
  AvgDialog_43803_Content_44 = {
    Text = "Ceritanya sendiri mungkin tidak semenarik cerita \"Dadu Terakhir\" yang Anda ceritakan, tetapi berbicara dengan Utusan Dewasa benar-benar terasa seperti angin segar."
  },
  AvgDialog_43803_Content_45 = {
    Text = "Dan lagi, entah mengapa, \"Mata buta yang tergantung terbalik\"itu memiliki daya tarikan yang sangat kuat dari dalam hati…"
  },
  AvgDialog_43803_Content_46 = {
    Text = "Eh, sedang membicarakan aku?"
  },
  AvgDialog_43803_Content_47 = {
    Text = "Medinate sedang memuji kemampuanmu dalam bercerita."
  },
  AvgDialog_43803_Content_48 = {
    Text = "Apakah Anda keberatan jika saya bergabung?"
  },
  AvgDialog_43803_Content_49 = {
    Text = "Tentu saja tidak, Nyonya."
  },
  AvgDialog_43803_Content_5 = {
    Text = "Pesta api unggun adalah salah satu contoh paling khas."
  },
  AvgDialog_43803_Content_50 = {
    Text = "Akhir-akhir ini, serangan dari Nubia semakin sering terjadi. Sudah waktunya untuk mengadakan upacara api unggun."
  },
  AvgDialog_43803_Content_51 = {
    Text = [[
Kedatangan tamu baru adalah pertanda baik, jangan bersedih! 
 Ayo, minum beberapa gelas dulu!]]
  },
  AvgDialog_43803_Content_52 = {
    Text = [[
Tamu juga, minumlah lebih banyak! 
 Nikmati pesta ini, kami akan menyuguhkan yang terbaik untuk menjamu tamu terhormat!]]
  },
  AvgDialog_43803_Content_53 = {Text = "Bersulang!"},
  AvgDialog_43803_Content_54 = {
    Text = "Saya tidak minum alkohol"
  },
  AvgDialog_43803_Content_55 = {
    Text = "Kamu mengangkat cangkir, dan bersulang dengan orang Aram yang penuh semangat."
  },
  AvgDialog_43803_Content_56 = {
    Text = "Saat dia lengah, kamu diam-diam membuang cairan anggur dari gelasnya."
  },
  AvgDialog_43803_Content_57 = {
    Text = "Kerangka Pohon Ibu berada di dalam tenda yang jaraknya kurang dari seratus meter dari tempatmu, sekarang bukan saat yang tepat untuk bersantai."
  },
  AvgDialog_43803_Content_58 = {
    Text = "Itu sangat disayangkan! Ritual dengan sedikit alkohol adalah yang paling sempurna!"
  },
  AvgDialog_43803_Content_59 = {
    Text = "Tidak peduli bagaimana Aram membujuk, kau hanya menolak."
  },
  AvgDialog_43803_Content_6 = {
    Text = "Detail-detail spesifik... kalian akan mengetahuinya pada malam hari."
  },
  AvgDialog_43803_Content_60 = {
    Text = "Kerangka Pohon Ibu berada di dalam tenda yang jaraknya kurang dari seratus meter dari tempatmu, sekarang bukan saat yang tepat untuk bersantai."
  },
  AvgDialog_43803_Content_62 = {
    Text = "……………"
  },
  AvgDialog_43803_Content_63 = {
    Text = "Seiring dengan meningkatnya rasa mabuk orang-orang Aram, suasana pesta juga mencapai puncaknya."
  },
  AvgDialog_43803_Content_64 = {
    Text = "Beberapa prajurit Aran mengangkat para wanita Aran dengan menggunakan tubuh mereka sebagai tandu, berparade di sekitar arena."
  },
  AvgDialog_43803_Content_65 = {
    Text = "Wanita-wanita dengan pandangan mata yang kabur karena mabuk memetik butiran anggur yang berkilauan dengan tetesan air, tertawa liar sambil melemparkannya ke kerumunan orang."
  },
  AvgDialog_43803_Content_66 = {
    Text = "Swish~ ke sini, ke sini, berikan aku dua buah juga!"
  },
  AvgDialog_43803_Content_67 = {
    Text = "Wanita itu seolah mendengar panggilan Ryker, lalu memandu para pejuang menuju ke arah Ryker. Setelah itu, dia terbang melayang dan langsung jatuh ke dalam pelukan Ryker."
  },
  AvgDialog_43803_Content_68 = {
    Text = "Jangan-jangan, tubuh kecilku ini tidak bisa menanggungnya..."
  },
  AvgDialog_43803_Content_69 = {
    Text = "Sebelum suara Ryker selesai, pemandangan di depan tiba-tiba membuat kalian terbelalak."
  },
  AvgDialog_43803_Content_7 = {
    Text = "...jadi, tujuan migrasi Aram juga situs Pohon Ibu?"
  },
  AvgDialog_43803_Content_70 = {
    Text = "Wanita itu merobek jubahnya sendiri, telanjang bulat menekan Ryker."
  },
  AvgDialog_43803_Content_71 = {
    Text = "Gerakannya seolah-olah menjadi semacam perintah, semua orang Aram mulai melepas pakaian dan baju besi mereka, mengubah tempat itu menjadi lautan yang penuh dengan kemaksiatan."
  },
  AvgDialog_43803_Content_72 = {
    Text = "Melihat Ryker tidak bergerak, wanita itu tanpa ragu langsung menyerbu prajurit Alan di sisinya, mengeluarkan erangan yang membuat wajah memerah."
  },
  AvgDialog_43803_Content_73 = {Text = "?!"},
  AvgDialog_43803_Content_74 = {
    Text = "Ayo, bergabunglah dengan kami dan nikmati kebahagiaan luar biasa dari pesta api unggun!"
  },
  AvgDialog_43803_Content_75 = {
    Text = "Lari! Lari! Kembali ke tenda Ramona!"
  },
  AvgDialog_43803_Content_76 = {
    Text = "Kamu merasa pikiranmu kosong, hanya bisa mengikuti kata-kata Ryker, berlari sekuat tenaga menuju tempat Ramona berada… bukan, melarikan diri."
  },
  AvgDialog_43803_Content_77 = {
    Text = "Di luar tenda, wanita yang bertugas merawat Ramona sudah menghilang."
  },
  AvgDialog_43803_Content_78 = {
    Text = "Ramona saat ini mengalami demam tinggi dan tidak sadarkan diri, sehingga dia tidak bisa menyaksikan dengan mata kepala sendiri pemandangan kegilaan dari ritual tersebut. Entah apakah ini suatu keberuntungan atau tidak."
  },
  AvgDialog_43803_Content_79 = {
    Text = "Itu adalah..."
  },
  AvgDialog_43803_Content_8 = {
    Text = "Ya, mereka juga tidak bisa menembus Dinding Badai."
  },
  AvgDialog_43803_Content_80 = {
    Text = [[
Upacara api unggun. Sepertinya begitu... 
 Upacara api unggun Aram adalah ritual perkawinan primitif.]]
  },
  AvgDialog_43803_Content_81 = {
    Text = "Di sini... agak jauh dari lokasi upacara, aku akan berjaga di luar untuk mencegah orang lain mendekat."
  },
  AvgDialog_43803_Content_82 = {
    Text = "Kamu tinggal untuk merawat Ramona."
  },
  AvgDialog_43803_Content_83 = {
    Text = "Gerombolan primitif ini... benar-benar gila."
  },
  AvgDialog_43803_Content_84 = {
    Text = "Dibandingkan dengan keramaian di luar tenda, di dalam tenda sangat sunyi. Hanya terdengar napas Ramona yang sedikit berat akibat demam tinggi."
  },
  AvgDialog_43803_Content_85 = {
    Text = "Bisikan kotor dari ritual di kejauhan terdengar samar-samar, menembus kain tenda yang tebal dan menyusup ke dalam gendang telingamu, membuatmu tidak bisa menahan perasaan gelisah."
  },
  AvgDialog_43803_Content_86 = {Text = "...Ryker?"},
  AvgDialog_43803_Content_87 = {
    Text = "Sayang sekali, apakah orang yang kamu harapkan bukan aku?"
  },
  AvgDialog_43803_Content_88 = {
    Text = "Ratu Aran — Thais masuk dengan mengangkat tirai, dia tanpa ragu mendekat. Kain tipis yang hampir tak terasa menyentuh lengan kecilmu, mengeluarkan undangan yang terang-terangan."
  },
  AvgDialog_43803_Content_89 = {
    Text = "Ayo, terimalah darah keturunan Alan dan jadilah salah satu dari kami."
  },
  AvgDialog_43803_Content_9 = {
    Text = "Penjaga, kamu datang. Aku dan Boneka sedang membahas rencana selanjutnya."
  },
  AvgDialog_43803_Content_90 = {
    Text = "Mendekatlah padaku, peluk aku... berikan darahmu, benihmu..."
  },
  AvgDialog_43803_Content_91 = {
    Text = "Kilatan api bergerak di dalam muridnya yang penuh semangat, pipinya yang kemerahan menunjukkan keinginan yang tidak sehat."
  },
  AvgDialog_43803_Content_92 = {
    Text = "Hanya satu tetes saja, asalkan daging tulang kita bersatu, Dia akan memberikan masa depan yang kita dambakan…"
  },
  AvgDialog_43803_Content_93 = {
    Text = "Mari kita... melahirkan keturunan untuk komunitas kita, dan berbagi keabadian..."
  },
  AvgDialog_43803_Content_94 = {
    Text = "Akalmu memberitahumu bahwa seharusnya kau menolak. Kau tidak tahu apa-apa tentang suku Alan, dan ritual kegilaan ini entah akan membawamu ke mana."
  },
  AvgDialog_43803_Content_95 = {
    Text = "Namun, tangan dan kakimu tidak menuruti perintahmu. Suara yang memikat itu menguasai anggota tubuh dan jiwamu, membangunkan keinginan dan hasrat nalurimu."
  },
  AvgDialog_43803_Content_96 = {
    Text = "Kamu belum menyentuh setetes pun alkohol, namun merasa mabuk. Dalam pandangan yang memabukkan, segala sesuatu di dunia terlihat indah dengan kabur, ringan mengambang, dan hanya panggilan dari Genesis Hidup yang terus terngiang."
  },
  AvgDialog_43803_Content_97 = {
    Text = "Berkembang biaklah, berkembang biaklah."
  },
  AvgDialog_43803_Content_98 = {
    Text = "<RedBig:Berkembang biaklah, berkembang biaklah!>"
  },
  AvgDialog_43803_Content_99 = {
    Text = "<Big:Menyebarkan benih ke bumi, biarkan <Red:garis keturunan> mengalir ke Kadath!>"
  },
  AvgDialog_43804_Content_1 = {
    Text = "Tidak perlu terlalu khawatir, meskipun Tuan Alva tegas, dia cukup pengertian."
  },
  AvgDialog_43804_Content_2 = {
    Text = [[
Nanti, saya akan mengundang kalian ke tenda saya untuk berdiskusi lebih lanjut. 
Sebelum itu, mari kita habisi dulu Nubia ini.]]
  },
  AvgDialog_43804_Content_3 = {
    Text = "Saya sudah menyaksikan kemampuan kalian, mengusir kotoran-kotoran ini seharusnya tidak menjadi masalah, bukan?"
  },
  AvgDialog_43805_Content_1 = {
    Text = "Berkembang biak"
  },
  AvgDialog_43805_Content_10 = {
    Text = "Suara dari luar sudah berhenti."
  },
  AvgDialog_43805_Content_11 = {
    Text = "Pergilah mengunjungi Kepala Suku Alva."
  },
  AvgDialog_43805_Content_12 = {
    Text = "Pergi dan diskusikan dengan Juliette."
  },
  AvgDialog_43805_Content_13 = {
    Text = "Benar, berputar di tempat memang bukan solusi."
  },
  AvgDialog_43805_Content_14 = {
    Text = "Ryker mendorong tirai pintu, tubuhnya bergetar, lalu membeku di tempat."
  },
  AvgDialog_43805_Content_15 = {
    Text = "Ada apa, Ryker?"
  },
  AvgDialog_43805_Content_16 = {
    Text = "Ryker tidak merespons, kamu penasaran dan berjalan ke arah belakangnya."
  },
  AvgDialog_43805_Content_17 = {
    Text = "Dia menarik napas dalam-dalam, dan suara serak keluar dari tenggorokannya."
  },
  AvgDialog_43805_Content_18 = {
    Text = "Kalian tunggu dulu... jangan mendekat."
  },
  AvgDialog_43805_Content_19 = {
    Text = "Ini tidak mungkin, Ryker. Kita tidak bisa terjebak di tenda ini…"
  },
  AvgDialog_43805_Content_2 = {
    Text = "Kapan aku... tertidur?"
  },
  AvgDialog_43805_Content_20 = {
    Text = "Nada bicaramu terhenti."
  },
  AvgDialog_43805_Content_21 = {
    Text = [[
Ryker berkata dengan benar, kamu seharusnya tidak melihat pemandangan di depanmu ini.
Namun, tragedi itu memaku murid matamu, membuatmu tak mampu mengalihkan pandangan.]]
  },
  AvgDialog_43805_Content_22 = {
    Text = "Itu adalah neraka dari air darah, bencana reproduksi, mimpi buruk aneh yang melanggar norma kemanusiaan dan hukum alam."
  },
  AvgDialog_43805_Content_23 = {
    Text = "Lubang tikus yang paling kotor pun tak mampu menggambarkan kekacauan di hadapan mata. Anggota tubuh baru yang lembut dan plasenta terjerat menjadi bentuk yang cacat, cairan merah meresap ke dalam tekstur gurun."
  },
  AvgDialog_43805_Content_24 = {
    Text = "Bau cairan tubuh yang menyebar di udara membawa sedikit rasa karat yang menusuk jiwa, membuat orang hampir muntah."
  },
  AvgDialog_43805_Content_25 = {
    Text = "Angin mengangkat tirai kemah ratu, Thais melangkah keluar dengan perlahan."
  },
  AvgDialog_43805_Content_26 = {
    Text = "Dia mengangkat jarinya, menunjuk ke garis cakrawala yang jauh dan terbagi oleh bukit-bukit pasir. Seiring dengan gerakannya, sinar pertama dari matahari yang baru terbit memancarkan cahaya pertamanya."
  },
  AvgDialog_43805_Content_27 = {
    Text = "Dalam sekejap, tangisan bayi meledak serempak dari tak terhitung banyaknya tenda, bergabung menjadi simfoni hidup baru."
  },
  AvgDialog_43805_Content_28 = {
    Text = "Namun, kamu tidak merasakan kegembiraan baru di dalamnya, hanya dingin yang menusuk tulang dari kepala hingga kaki."
  },
  AvgDialog_43805_Content_29 = {
    Text = "Akhir-akhir ini, serangan dari Nubia semakin sering terjadi. Sudah waktunya untuk mengadakan upacara api unggun."
  },
  AvgDialog_43805_Content_3 = {
    Text = "Di luar tenda, segalanya begitu sunyi. Pesta semalam yang penuh dengan kegilaan dan antusiasme aneh terasa seperti mimpi buruk yang telah lenyap."
  },
  AvgDialog_43805_Content_30 = {
    Text = [[
Itu bukanlah upacara untuk meningkatkan semangat, melainkan pertemuan reproduksi untuk menambah pasukan. 
Apa mereka menganggap hidup sebagai alat untuk bertahan hidup?]]
  },
  AvgDialog_43805_Content_31 = {
    Text = "Menurut catatan, kekuatan dari Esensi Keinginan berkaitan dengan reproduksi dan perkembangbiakan."
  },
  AvgDialog_43805_Content_32 = {
    Text = "Pohon Ibu yang subur tertanam di sumber Sungai Karagae yang disebut sebagai Sungai Suci, menyuburkan tanah dan air di kedua tepiannya, serta memberikan kemampuan reproduksi luar biasa kepada orang Aram melebihi manusia biasa."
  },
  AvgDialog_43805_Content_33 = {
    Text = "Berkat rahmat dari Sungai Suci, darah keturunan Aran dapat terus berlanjut di padang pasir Lemwahi yang memiliki lingkungan hidup keras dari generasi ke generasi."
  },
  AvgDialog_43805_Content_34 = {
    Text = "Memelihara, subur, melanjutkan... Manifestasi dari kata-kata penuh kasih sayang ini ternyata begitu kotor dan kejam."
  },
  AvgDialog_43805_Content_35 = {
    Text = "Sekarang, di hadapan kita terdapat dua jalan."
  },
  AvgDialog_43805_Content_36 = {
    Text = "Lanjutkan mengikuti pasukan Aram maju, atau lepaskan diri dari tim dan cari cara sendiri untuk mencapai tujuan misi."
  },
  AvgDialog_43805_Content_37 = {
    Text = "Perilaku membuang janin cacat secara sembarangan demi kecepatan reproduksi yang ekstrem, di masyarakat beradab setara dengan sebuah kasus pembunuhan massal. Saya tahu sulit bagimu untuk mengabaikannya."
  },
  AvgDialog_43805_Content_38 = {
    Text = "Lagipula, ada misteri dalam adegan ini — apakah kamu memperhatikan proporsi janin yang cacat?"
  },
  AvgDialog_43805_Content_39 = {
    Text = "Mengapa Pohon Ibu memberikan kemampuan reproduksi luar biasa kepada orang Aram, membuat mereka bisa hamil dan melahirkan dalam semalam, tetapi hanya satu dari sepuluh bayi yang lahir normal?"
  },
  AvgDialog_43805_Content_4 = {
    Text = "Tidak tahu, saat aku bangun, kamu sudah tertidur."
  },
  AvgDialog_43805_Content_40 = {
    Text = [[
Lihatlah, baik dari sudut pandang Penyelidik Mythag maupun detektif, pilihan pertama adalah keharusan. 
 Kita harus tetap berada di tempat yang paling dekat dengan target dan kebenaran, bukan?]]
  },
  AvgDialog_43805_Content_41 = {
    Text = "Sebelum kamu memberikan jawaban, pasukan di depanmu mulai bergerak. Mulai dari kemah kepala suku, orang-orang Aram sibuk berlarian dan berteriak di depan beberapa kemah, lalu semua orang meninggalkan kemah mereka dan mulai bersiap-siap."
  },
  AvgDialog_43805_Content_42 = {
    Text = "Apa yang terjadi?"
  },
  AvgDialog_43805_Content_43 = {
    Text = "Nubia, segerombolan besar Nubia menyerang perkemahan! Para penjaga di depan tidak bisa menahan mereka!"
  },
  AvgDialog_43805_Content_44 = {
    Text = "Begitu kebetulan, pesta baru saja berakhir, Nubia langsung melancarkan serangan?"
  },
  AvgDialog_43805_Content_45 = {
    Text = "Siapa yang tahu? Selalu seperti ini. Binatang sialan itu tak pernah memberi kesempatan untuk bersantai!"
  },
  AvgDialog_43805_Content_46 = {
    Text = "Kalian juga cepat lari, sekarang tidak ada yang bisa menjaga kalian!"
  },
  AvgDialog_43805_Content_47 = {
    Text = "Kami ingin bertemu Alva, di mana dia?"
  },
  AvgDialog_43805_Content_48 = {
    Text = "Kepala Klan sedang memimpin di garis depan!"
  },
  AvgDialog_43805_Content_49 = {
    Text = "Barisan kiri, berkumpul! Migrasi belum selesai, jangan biarkan satu pun Nubia lewat!"
  },
  AvgDialog_43805_Content_5 = {Text = "Ryker?"},
  AvgDialog_43805_Content_50 = {
    Text = "Nain, pertahankan sisi kamu! Jika tangan dan kaki terasa lemas, jangan memaksakan diri, biarkan Vajet menggantikan posisimu!"
  },
  AvgDialog_43805_Content_51 = {
    Text = [[
Apa yang kalian lakukan di sini? 
 Tidakkah kalian lihat bahwa pertempuran di garis depan sedang berlangsung?]]
  },
  AvgDialog_43805_Content_52 = {
    Text = "Kaum Alan tidak menyambut tamu yang menolak untuk melahirkan \"Benih\", silakan para tamu bertindak sesuai keinginan masing-masing!"
  },
  AvgDialog_43805_Content_53 = {
    Text = "Tuan Alva, bolehkah saya mengatakan beberapa kata?"
  },
  AvgDialog_43805_Content_54 = {
    Text = "%player% masuk ke tenda Ratu secara tidak sengaja, dan Yang Mulia Ratu tampaknya tidak marah, bukan?"
  },
  AvgDialog_43805_Content_55 = {
    Text = "Jika harus dihitung, saya juga memiliki separuh tanggung jawab karena tidak menjelaskan prinsipnya dengan jelas sebelum membiarkan {Male=dia,Female=dia} menunggu sendirian di tenda Ratu."
  },
  AvgDialog_43805_Content_56 = {
    Text = "Kamu menatap Juliette dengan tercengang, matanya bergetar, lalu dia menggelengkan kepala pelan-pelan, seolah-olah mengingatkanmu untuk tidak banyak bicara."
  },
  AvgDialog_43805_Content_57 = {
    Text = "Kamu tidak tahu mengapa dia melindungimu, tetapi kamu tidak punya alasan untuk menolaknya."
  },
  AvgDialog_43805_Content_58 = {
    Text = "Akhir-akhir ini, serangan dari Nubia semakin sering terjadi. Dalam melawan makhluk jahat ini, mereka mungkin bisa memberikan bantuan."
  },
  AvgDialog_43805_Content_6 = {
    Text = "Ramona menunjuk ke arah pintu tenda."
  },
  AvgDialog_43805_Content_60 = {
    Text = "Biarkan mereka mengikuti kamu."
  },
  AvgDialog_43805_Content_61 = {
    Text = [[
Awasi mereka, jangan sampai aku melihat mereka di dekat kemah utama. 
Jika tidak, hukumannya bukan hanya sekadar diusir dari perkemahan.]]
  },
  AvgDialog_43805_Content_7 = {
    Text = "Ryker bersandar di pintu dan tertidur pulas, tampaknya terbangun oleh suara gerakanmu saat bangkit. Sepasang telinga berbulunya dengan cepat bergetar, bulu matanya berkedut dua kali, lalu dia membuka mata serigalanya yang panjang."
  },
  AvgDialog_43805_Content_8 = {
    Text = "Upacara kemarin... itu bukan mimpi, kan?"
  },
  AvgDialog_43805_Content_9 = {
    Text = "Untuk menjaga sikap seorang gentleman di Londinium, seharusnya aku tidak sembarangan mengomentari gaya hidup orang lain, tetapi ritual suku primitif ini benar-benar sudah keterlaluan."
  },
  AvgDialog_43806_Content_1 = {
    Text = "Jika makhluk sebesar ini datang beberapa sekaligus, pinggang tua saya benar-benar tidak akan kuat menahan."
  },
  AvgDialog_43806_Content_10 = {
    Text = "Tunggu, itu adalah——"
  },
  AvgDialog_43806_Content_11 = {
    Text = "Itu adalah seseorang yang menyeret Nubia di atas pasir. Angin dari lautan pasir meniupkan tudung jubah hitamnya, dan cahaya bulan yang dingin membuat rambut emasnya berkilauan terang."
  },
  AvgDialog_43806_Content_12 = {
    Text = "Kak William!"
  },
  AvgDialog_43806_Content_2 = {
    Text = "Menurut Alva, ini hanyalah pemimpin dari kelompok kecil. Ancaman sebenarnya mungkin jauh lebih menakutkan daripada ini."
  },
  AvgDialog_43806_Content_3 = {
    Text = "Jangan bicara lagi. Sebelum bertabrakan, biarkan aku berpura-pura tidak tahu dan menikmati beberapa hari yang menyenangkan dengan santai."
  },
  AvgDialog_43806_Content_4 = {
    Text = "Masih belum saatnya untuk bersantai! %player%, lihat ke sana!"
  },
  AvgDialog_43806_Content_5 = {
    Text = "Siluet aneh yang sudah lama kalian bosankan muncul dari balik bukit pasir di malam yang gelap, merangkak lunglai ke arah kalian."
  },
  AvgDialog_43806_Content_6 = {
    Text = "Masih ada ikan yang lolos?"
  },
  AvgDialog_43806_Content_7 = {
    Text = "Ayo, biarkan kalian juga menikmati kebahagiaan dari tiga kemenangan beruntun!"
  },
  AvgDialog_43806_Content_8 = {
    Text = "Tidak, masih ada yang tidak benar——"
  },
  AvgDialog_43806_Content_9 = {
    Text = "Saat diperhatikan dengan saksama, gerakan Nubia ini terlihat sangat lambat dan kaku."
  },
  AvgDialog_43807_Content_1 = {Text = "Jejak"},
  AvgDialog_43807_Content_10 = {
    Text = "Seperti dalam pertempuran..."
  },
  AvgDialog_43807_Content_11 = {Text = "Gagal."},
  AvgDialog_43807_Content_12 = {
    Text = "Saya pikir, kedua anak ini sudah tidak sabar ingin mendengar penjelasan dari kakak senior."
  },
  AvgDialog_43807_Content_13 = {
    Text = "William mendorong kacamatanya dan mengangguk kepada kalian."
  },
  AvgDialog_43807_Content_14 = {
    Text = "Ini adalah satu-satunya sampel Nubia yang utuh yang berhasil kami kumpulkan sejauh ini."
  },
  AvgDialog_43807_Content_15 = {
    Text = "Sebelum tahun ini, hampir tidak ada catatan penampakan Nubia. Kemunculannya di Gurun Remwahi adalah kejadian baru-baru ini, tetapi dalam waktu singkat sudah menyebar ke seluruh gurun, mengikis wilayah hidup Aram."
  },
  AvgDialog_43807_Content_16 = {
    Text = "Mutasi biologis tidak cukup untuk menjelaskan asal-usulnya; modifikasi buatan lebih sesuai dengan peluang dan kondisi kemunculannya."
  },
  AvgDialog_43807_Content_17 = {
    Text = "Maksudmu, ada orang yang sedang membuat Nubia?"
  },
  AvgDialog_43807_Content_18 = {
    Text = "William mengangguk, tampaknya puas dengan tebakanmu."
  },
  AvgDialog_43807_Content_19 = {
    Text = "Dan dengan sengaja menyembunyikan sumbernya. Jika bagian tubuh mana pun dari Nubia dipotong, bagian dalamnya akan segera mengeluarkan tentakel untuk memperbaiki luka, sehingga bekas luka tetap berada di dalam."
  },
  AvgDialog_43807_Content_2 = {
    Text = "Di tengah tenda yang kasar dan primitif, tubuh Nubia yang lemas menjulang seperti gunung daging hitam, cahaya redup membuat bayangan menjadi menakutkan."
  },
  AvgDialog_43807_Content_20 = {
    Text = [[
Jika terkena luka fatal, maka akan segera menguap, meninggalkan tidak ada jejak yang dapat diteliti.
Harap diketahui, lumpur pelarutan biasa tidak akan menghilang secara alami dalam waktu yang singkat seperti itu.]]
  },
  AvgDialog_43807_Content_21 = {
    Text = "\"Desainer\" dari orang-orang ini menyembunyikan sesuatu."
  },
  AvgDialog_43807_Content_22 = {
    Text = "Dibandingkan dengan struktur internal mereka, saya lebih peduli tentang jalur pergerakan Nubia."
  },
  AvgDialog_43807_Content_23 = {
    Text = "Beberapa hari ini, saya terus bertanya kepada Aram tentang informasi. Menurut deskripsi mereka, setiap kali mereka berhenti, berkemah selama beberapa hari atau mengadakan upacara, kawanan Nubia yang awalnya diam akan menyerang perkemahan."
  },
  AvgDialog_43807_Content_24 = {
    Text = "Insting saya mengatakan bahwa orang-orang Nubia ini sedang menggiring orang Aram ke arah tertentu."
  },
  AvgDialog_43807_Content_25 = {
    Text = "William mengeluarkan peta dan menandai titik-titik padat di Nubia satu per satu."
  },
  AvgDialog_43807_Content_26 = {
    Text = "Juga harus mempertimbangkan rute migrasi bangsa Aram."
  },
  AvgDialog_43807_Content_27 = {
    Text = "Ryker menggunakan paku besar untuk menahan benang katun merah, menggambarkan jalur sesuai dengan titik-titik yang diberitahukan oleh Aram."
  },
  AvgDialog_43807_Content_28 = {
    Text = "Bayangan hitam mengejar garis merah, melangkah maju dengan tekanan yang terus meningkat, secara bertahap mendorong garis merah menuju sumber Sungai Suci."
  },
  AvgDialog_43807_Content_29 = {
    Text = "Intuisi kamu selalu akurat."
  },
  AvgDialog_43807_Content_3 = {
    Text = "William mengeluarkan seperangkat alat bedah presisi dari lapisan pembalut di kakinya. Pisau bedah, gunting bedah, pinset bergerigi halus, dan klem hemostat tersusun seperti tim kecil yang terbuat dari stainless steel."
  },
  AvgDialog_43807_Content_30 = {
    Text = "Sungai suci berada di sumbernya, menyembunyikan diri di dalam Dinding badai."
  },
  AvgDialog_43807_Content_31 = {
    Text = "Ada yang tidak ingin Aram berkeliaran di luar Dinding Badai, dia sedang mempersempit ruang hidup Aram, memaksa mereka masuk ke dalam Dinding Badai."
  },
  AvgDialog_43807_Content_32 = {
    Text = "Kontur kasus sudah terungkap, whydunit (motif) dan howdunit (metode) telah dibongkar."
  },
  AvgDialog_43807_Content_33 = {
    Text = "Lalu muncul pertanyaan, whodunit (siapa pelakunya)?"
  },
  AvgDialog_43807_Content_34 = {
    Text = [[
Petunjuk terlalu sedikit, saat ini masih belum bisa menentukan. 
 Mari sinkronkan pengalaman baru-baru ini terlebih dahulu, petunjuk selalu dapat membantu dalam membuat keputusan.]]
  },
  AvgDialog_43807_Content_36 = {
    Text = "……………"
  },
  AvgDialog_43807_Content_37 = {
    Text = "Kami membutuhkan lebih banyak informasi tentang Nubia."
  },
  AvgDialog_43807_Content_38 = {
    Text = "Tugas utama kalian tetap tidak berubah: menyelidiki kebenaran di balik kerangka Pohon Ibu di kemah Ratu, dan menunggu kesempatan untuk menghancurkannya."
  },
  AvgDialog_43807_Content_39 = {
    Text = "Saya akan melanjutkan penelitian Nubia."
  },
  AvgDialog_43807_Content_4 = {
    Text = "Tidak disangka senior masih membawa ini kemana-mana, apakah berencana beralih profesi untuk menyelamatkan nyawa?"
  },
  AvgDialog_43807_Content_40 = {
    Text = "Saya punya firasat bahwa kebenaran tentang suku Alan dan Pohon Ibu yang Subur tersembunyi di balik sumber-sumber Nubia ini."
  },
  AvgDialog_43807_Content_41 = {
    Text = "William berkata, lalu berbalik dan mengambil jubahnya."
  },
  AvgDialog_43807_Content_42 = {
    Text = "Apakah Kakak William akan pergi?"
  },
  AvgDialog_43807_Content_43 = {
    Text = [[
Berangkat sebelum fajar. 
Hati-hati, jangan biarkan Juliette mengetahui pergerakanku.]]
  },
  AvgDialog_43807_Content_44 = {
    Text = "William menyingkap tirai dan keluar, lalu berbalik untuk memberi tahu kalian, hampir saja bertabrakan dengan orang yang datang."
  },
  AvgDialog_43807_Content_45 = {
    Text = "Sejak bertemu dengan kalian di Sungai Suci, sepertinya aku telah memberikan banyak kemudahan kepada kalian semua dan tidak melakukan tindakan yang membahayakan. Mengapa Tuan William begitu waspada terhadap diriku?"
  },
  AvgDialog_43807_Content_46 = {
    Text = "Di dalam tenda yang sempit, udara terasa tegang. Tidak ada yang menjawab untuk sementara waktu, dan angin panas dari lautan pasir yang biasanya terasa kini menjadi sedikit dingin dan suram."
  },
  AvgDialog_43807_Content_47 = {
    Text = "Beberapa detik kemudian, Juliette akhirnya memecah keheningan."
  },
  AvgDialog_43807_Content_48 = {
    Text = "Hanya bercanda, tidak perlu terlalu tegang."
  },
  AvgDialog_43807_Content_49 = {
    Text = "Juliette terlalu berlebihan. Semua orang menikmati perjalanan ini dengan menyenangkan. Hanya saja, Tuan William memiliki sifat pemalu dan tidak suka bergaul dengan orang asing…"
  },
  AvgDialog_43807_Content_5 = {
    Text = "William mengabaikan candaanmu, dengan alis berkerut, dia hati-hati memotong untuk pertama kalinya."
  },
  AvgDialog_43807_Content_50 = {
    Text = "Ryker mulai berbicara panjang lebar, kamu memperhatikan Ramona yang sedang berbaring di kasur tidak bisa menahan diri untuk memutar matanya."
  },
  AvgDialog_43807_Content_51 = {
    Text = "Hm, jadi, intinya, kedatangan Juliette di tengah malam, apakah ada urusan penting yang ingin dibicarakan?"
  },
  AvgDialog_43807_Content_52 = {
    Text = "Ngomong-ngomong, ini bukan sesuatu yang terlalu penting — ayo, masuk ke tendaku dan kita bicarakan lagi."
  },
  AvgDialog_43807_Content_6 = {
    Text = "Pisau bedah memasuki tubuh Nubia, namun tidak seperti yang diperkirakan, cairan hitam kental tidak mengalir keluar."
  },
  AvgDialog_43807_Content_7 = {
    Text = "William dengan tegang, perlahan membenamkan mata pisaunya lebih dalam, lalu menggores ke bawah ——"
  },
  AvgDialog_43807_Content_8 = {
    Text = "Zi-la——"
  },
  AvgDialog_43807_Content_9 = {
    Text = "Nubia yang tertusuk langsung berubah menjadi genangan lumpur hitam, lalu menguap dalam sekejap. Meja operasi tampak begitu bersih seolah-olah tidak pernah ada kotoran apa pun di sana."
  },
  AvgDialog_43808_Content_1 = {
    Text = "Suara-suara yang berkumpul di ruang kesadaran ini adalah kumpulan kesadaran semua orang Aram dari zaman kuno hingga sekarang."
  },
  AvgDialog_43808_Content_10 = {
    Text = "Juliette berlutut di depan buaian, dengan khidmat menyenandungkan lagu."
  },
  AvgDialog_43808_Content_11 = {
    Text = "Hummingnya tanpa lirik, namun kamu memahami melodi ini."
  },
  AvgDialog_43808_Content_12 = {
    Text = "Dia mengangkat bungkusan bayi itu dan masuk ke dalam Sungai Suci."
  },
  AvgDialog_43808_Content_13 = {
    Text = "Pasir mengalir dengan cepat menutupi hidup yang baru saja hilang."
  },
  AvgDialog_43808_Content_14 = {
    Text = "Kematian sudah mendekat, kehancuran telah dimulai."
  },
  AvgDialog_43808_Content_15 = {
    Text = "Nyanyian itu indah dan penuh kerinduan, dengan sedikit kesedihan, mengalir jauh ke kejauhan mengikuti aliran Air sungai suci."
  },
  AvgDialog_43808_Content_16 = {
    Text = "Pukul 4:00 Pagi Tenda Pengunjung"
  },
  AvgDialog_43808_Content_17 = {
    Text = "Saya akan merangkum:"
  },
  AvgDialog_43808_Content_18 = {
    Text = "Bagi orang Aram, Pohon Ibu tidak akan tumbuh lagi, seluruh Sungai Suci akan mengering, dan Lermwah akan berubah menjadi negara gurun yang sepenuhnya tandus."
  },
  AvgDialog_43808_Content_19 = {
    Text = "Juliette berniat untuk membangkitkan Pohon Ibu dan mengajarkan Aram menerima serta beradaptasi dengan kehidupan modern."
  },
  AvgDialog_43808_Content_2 = {
    Text = "Aram... sedang menangis?"
  },
  AvgDialog_43808_Content_20 = {
    Text = "Namun, sumber informasi dari Dafude memberi tahu kami bahwa begitu Pohon Ibu yang subur pulih, kemungkinan besar akan terjadi pelarutan skala global."
  },
  AvgDialog_43808_Content_21 = {
    Text = "Sisa pohon suci ada di dalam tenda ratu, jika berhasil menghancurkan sisa pohon suci sebelum memasuki dinding badai, kemungkinan besar akan menyelesaikan misi dengan biaya yang minimal."
  },
  AvgDialog_43808_Content_22 = {
    Text = "Jadi, pertanyaannya adalah, menurut kalian, bagaimana reputasi pedagang bernama Narsis? Apakah sumber informasinya dapat diandalkan?"
  },
  AvgDialog_43808_Content_23 = {
    Text = "Alistair telah berusaha semampunya, hanya bisa memastikan bahwa seseorang dengan sengaja menyampaikan pesan ini. Namun, keakuratan pesan tersebut tidak dapat dievaluasi."
  },
  AvgDialog_43808_Content_24 = {
    Text = "Dengan gegabah membakar sisa pohon suci, mungkin akan memutuskan jalur mundur terakhir bagi Aram."
  },
  AvgDialog_43808_Content_25 = {
    Text = [[
Di hadapan Pelarutan, kita juga tidak memiliki jalan mundur.
Jangan biarkan belas kasihan yang tak berguna mengganggu penilaianmu.]]
  },
  AvgDialog_43808_Content_26 = {
    Text = "Tidak apa-apa, Boneka. Bahkan jika pada akhirnya kita harus menerobos masuk ke lokasi upacara untuk membakar Pohon Ibu, aku akan tetap mendampingi."
  },
  AvgDialog_43808_Content_27 = {
    Text = "Saya setuju dengan pandangan Penjaga, kita tahu sangat sedikit tentang segala sesuatu yang terkait dengan Aran, dan melancarkan serangan sekarang juga tampak kurang bijaksana."
  },
  AvgDialog_43808_Content_28 = {
    Text = [[
Saya akan terus melakukan penelitian tentang Nubia. 
Penjaga, Ryker, penyelidikan terhadap Sisa pohon suci akan menjadi tanggung jawab kalian.]]
  },
  AvgDialog_43808_Content_3 = {
    Text = [[
Ya, jiwa Aram meratap. 
Karena dosa kehidupan dan ketakutan akan kematian.]]
  },
  AvgDialog_43808_Content_4 = {
    Text = "Jika aku bisa memimpin Aram melewati Dinding Badai, dan menemukan kembali Pohon Ibu…\nAram akan menganggapku sebagai pemimpin baru."
  },
  AvgDialog_43808_Content_5 = {
    Text = "Pada saat itu, aku akan mengakhiri ritual jahat dan sakit ini, membebaskan Aram selamanya dari gurun tandus yang keras ini."
  },
  AvgDialog_43808_Content_6 = {
    Text = "Semua orang akan menetap di tanah yang murni dan damai, bebas dari penderitaan akibat dosa yang dibawa sejak lahir."
  },
  AvgDialog_43808_Content_7 = {
    Text = "%player%, tolong bantu saya."
  },
  AvgDialog_43808_Content_8 = {
    Text = "Kamu terbangun dari mimpi, napas anak di dada Juliette telah berhenti."
  },
  AvgDialog_43808_Content_9 = {
    Text = "Biarkan dia mengembalikan Sungai Suci."
  },
  AvgDialog_43809_Content_1 = {
    Text = "Sumber Aliran"
  },
  AvgDialog_43809_Content_10 = {
    Text = "Juliette mengusap kepala remaja itu yang penuh dengan rambut lebat."
  },
  AvgDialog_43809_Content_11 = {
    Text = "Baiklah, jika ada yang perlu bantuan..."
  },
  AvgDialog_43809_Content_12 = {
    Text = "Pemuda itu memandang kalian dengan penuh kehati-hatian beberapa kali."
  },
  AvgDialog_43809_Content_13 = {
    Text = "Bangunkan saya kapan pun."
  },
  AvgDialog_43809_Content_14 = {
    Text = "Pemuda itu pergi, Juliette memberikan senyuman maaf kepada kalian."
  },
  AvgDialog_43809_Content_15 = {
    Text = "Maaf, dia sedikit terlalu protektif."
  },
  AvgDialog_43809_Content_16 = {
    Text = "Tebakanmu benar, dia adalah yang berkembang paling cepat di antara anak-anak ini."
  },
  AvgDialog_43809_Content_17 = {
    Text = "Sebagai perbandingan..."
  },
  AvgDialog_43809_Content_18 = {
    Text = "Juliette membawa kalian ke samping sebuah buaian yang sederhana."
  },
  AvgDialog_43809_Content_19 = {
    Text = "Lihatlah anak ini."
  },
  AvgDialog_43809_Content_2 = {
    Text = "Pukul 2:00 Tenda Utusan"
  },
  AvgDialog_43809_Content_20 = {
    Text = "Itu adalah bayi yang masih dalam buaian, dengan pola kegelapan berbentuk pohon menjalar di sekujur tubuhnya."
  },
  AvgDialog_43809_Content_21 = {
    Text = "Secara eksternal tidak terlihat adanya kelainan, tetapi sebenarnya sudah terinfeksi oleh penyakit Pohon ibu."
  },
  AvgDialog_43809_Content_22 = {
    Text = "Cobalah letakkan tanganmu di kulitnya."
  },
  AvgDialog_43809_Content_23 = {
    Text = "Kamu menyentuh permukaan tubuh anak itu sesuai dengan instruksi. Bukan kulit bayi yang lembut seperti yang kamu bayangkan, melainkan memiliki tekstur kasar dan kering seperti kulit pohon yang retak."
  },
  AvgDialog_43809_Content_3 = {
    Text = [[
Di dalam tenda utusan terdapat banyak alas tidur, beberapa anak berusia lima atau enam tahun terbaring meringkuk di tempat tidur, tertidur dengan nyenyak. 
 Seorang pemuda yang tampak gagah berani menyambut kalian.]]
  },
  AvgDialog_43809_Content_4 = {
    Text = "Kepada Nyonya Juliette, Anda telah kembali."
  },
  AvgDialog_43809_Content_5 = {
    Text = [[
Nefrure, anak baikku. 
Apakah semua orang sudah beristirahat?]]
  },
  AvgDialog_43809_Content_6 = {
    Text = "Ya, Nyonya Juliette."
  },
  AvgDialog_43809_Content_7 = {
    Text = "Anak-anak ini adalah..."
  },
  AvgDialog_43809_Content_8 = {
    Text = "Sebelum hari ini, kamu belum pernah melihat anak di bawah umur di antara barisan Aram."
  },
  AvgDialog_43809_Content_9 = {
    Text = [[
Nefruri, silakan beristirahat dulu.
Tidak mudah membuat semua orang tertidur, besok minta Alva-sama memberikanmu hadiah.]]
  },
  AvgDialog_43816_Content_1 = {
    Text = "Api yang tak terduga"
  },
  AvgDialog_43816_Content_10 = {
    Text = "Suara pria yang licin mengarahkanmu yang sedang kebingungan——dirimu yang dengan canggung berputar-putar di bawah sorotan lampu."
  },
  AvgDialog_43816_Content_11 = {
    Text = "Gadis-gadis di sekitar mereka mengembangkan tubuh mereka seperti angsa, langkah tari mereka seragam dan menampilkan keindahan yang berirama."
  },
  AvgDialog_43816_Content_12 = {
    Text = "Seseorang malah berperilaku seperti bebek liar yang tersesat di antara kawanan angsa."
  },
  AvgDialog_43816_Content_13 = {
    Text = "Kamu hampir seketika menyadari bahwa ini adalah tubuh seorang penari — namun memori tubuhnya belum sepenuhnya kembali, bahkan berjalan pun terasa tersendat-sendat, apalagi mengingat gerakan tarian yang rumit."
  },
  AvgDialog_43816_Content_14 = {
    Text = "Hanya tahu menambah masalah, \"kepala\" sepertimu benar-benar pantas disebut kompeten."
  },
  AvgDialog_43816_Content_15 = {
    Text = "Ketua? Saya... Ketua.."
  },
  AvgDialog_43816_Content_16 = {
    Text = "Tidak ada yang menjawab pertanyaanmu. Para penari terus melangkah, berbaris melewati tubuhmu dengan gesit — namun dalam prosesnya, siku seseorang menabrak tubuhmu dengan keras."
  },
  AvgDialog_43816_Content_17 = {
    Text = "Kamu kehilangan keseimbangan dan tersandung dua langkah. Saat formasi tarian berubah, kamu sudah terdorong ke tepi panggung, namun tetap tidak bisa lepas dari pandangan tajam penonton——"
  },
  AvgDialog_43816_Content_18 = {
    Text = "Di bawah panggung tidak terdapat deretan tempat duduk penonton. Di tanah lapang yang luas, terdapat set-set meja dan kursi yang berpasangan."
  },
  AvgDialog_43816_Content_19 = {
    Text = "Meja dihiasi dengan sutra mewah berenda, perhiasan penonton memantulkan cahaya panggung di tempat gelap, membuat wajah yang mengenakan topeng terlihat lebih menyeramkan."
  },
  AvgDialog_43816_Content_2 = {
    Text = "Satu, dua, tiga, satu, dua, tiga... Bagus, barisan sangat rapi dan anggun."
  },
  AvgDialog_43816_Content_20 = {
    Text = "Apa yang terjadi dengan anak di barisan paling depan? Apakah dia melakukan kesalahan?"
  },
  AvgDialog_43816_Content_21 = {
    Text = "Hmph... Apakah mereka menari dengan baik atau buruk, mereka sama sekali tidak peduli. Apakah kamu masih belum mengerti pikiran orang seperti itu?"
  },
  AvgDialog_43816_Content_22 = {
    Text = "Juga. Ngomong-ngomong, meskipun dia tidak terlalu pandai melompat, tubuhnya sungguh luar biasa…"
  },
  AvgDialog_43816_Content_23 = {
    Text = "<Small:These people don't seem to be ordinary dance spectators…>"
  },
  AvgDialog_43816_Content_24 = {
    Text = "Apa yang masih kau pikirkan!"
  },
  AvgDialog_43816_Content_25 = {
    Text = "Tangan yang gemuk dan terbiasa hidup mewah mencengkeram lengan atasmu yang telanjang, berusaha menarikmu ke dalam bayangan tirai panggung."
  },
  AvgDialog_43816_Content_26 = {
    Text = "Kamu hampir saja merusak pertunjukan tari ini! Ini adalah gladi resik terakhir sebelum penampilan resmi. Apa yang sebenarnya ada di pikiranmu!"
  },
  AvgDialog_43816_Content_27 = {
    Text = "Maaf, aku... aku..."
  },
  AvgDialog_43816_Content_28 = {
    Text = "Suara instrumen satu per satu menghantam gendang telinga, pandanganmu mulai berkunang-kunang, dan langkah dansa terus terperangkap dalam kabut memori. Tarikan pria itu memberimu kesempatan, kamu memanfaatkan tenaganya untuk mencoba meninggalkan panggung —"
  },
  AvgDialog_43816_Content_29 = {
    Text = [[
Jangan pergi, setelah aku naik ke atas panggung, aku membutuhkan seseorang untuk menyeimbangkan formasi barisan. 
Pergilah ke bagian kiri belakang barisan untuk mengisi kekosongan, tiru gerakan dansaku.]]
  },
  AvgDialog_43816_Content_3 = {
    Text = "Suara gesekan senar dan tiupan pipa bergema di belakang, berpadu dengan ketukan di lantai membentuk kebisingan yang teratur namun elegan, menari dalam irama yang sangat memikat secara sensoris."
  },
  AvgDialog_43816_Content_30 = {
    Text = "Tangan pria itu terbuka dengan sebuah tepukan, dan dalam tatapannya yang penuh kejutan dan sukacita, sepasang tangan putih pucat yang ramping mencengkeram pinggangmu, membawamu menuju cahaya lampu."
  },
  AvgDialog_43816_Content_31 = {
    Text = "Seseorang dengan langkah tari yang ringan dan lemah gemulai, menggunakan gerakan tari untuk mendorong barisan yang sudah mulai terpecah, lalu dengan tegas memasukkanmu ke dalam kelompok penari."
  },
  AvgDialog_43816_Content_32 = {
    Text = "Para penari saling bertatapan, namun tak seorang pun berani mengomentari tindakan gadis itu. Mereka hanya mendengus dengan nada meremehkan ke arahmu, lalu kembali menunduk dan mengayunkan lengan mereka, melanjutkan tarian."
  },
  AvgDialog_43816_Content_33 = {
    Text = "Cepat! Segera arahkan cahaya ke arahnya! Elizabeth akhirnya bersedia naik ke panggung untuk menari! Ini adalah penampilan pertamanya setelah tiga bulan!"
  },
  AvgDialog_43816_Content_34 = {Text = "Elizabeth?"},
  AvgDialog_43816_Content_35 = {
    Text = "Kamu merenungkan nama itu, ingin melihat gadis yang tanpa banyak bicara menarikmu ke atas panggung."
  },
  AvgDialog_43816_Content_36 = {
    Text = "Pada saat mendongak, cahaya dari lantai dua tiba-tiba menyapu lintasan yang menyilaukan, langsung menghantam matamu, membuat duniamu tak terkendali tenggelam dalam lautan putih."
  },
  AvgDialog_43816_Content_37 = {
    Text = "——Ketika membuka mata kembali, gadis berpakaian tari hitam sudah melompat ke barisan paling depan."
  },
  AvgDialog_43816_Content_38 = {
    Text = [[
Semua orang memberi jalan untuk kemunculannya, menyisakan ruang bagi kibaran roknya. 
 Di atas panggung kecil ini, dialah penyihir satu-satunya yang memikat hati, bintang mutlak.]]
  },
  AvgDialog_43816_Content_39 = {
    Text = "Itu adalah Elizabeth, penari andalan Adley Dance Troupe… Ya Tuhan, dia sangat cantik."
  },
  AvgDialog_43816_Content_4 = {
    Text = "Apa itu suara..."
  },
  AvgDialog_43816_Content_40 = {
    Text = "Manajer, bukankah dikatakan bahwa Nona Elizabeth mengalami masalah dengan tubuhnya dan akan absen dalam pertunjukan kali ini?"
  },
  AvgDialog_43816_Content_41 = {
    Text = "Para tuan dan nyonya, ini adalah… kejutan yang disiapkan Elizabeth untuk kalian semua! Ya, sebuah kejutan."
  },
  AvgDialog_43816_Content_42 = {
    Text = "Meskipun tubuhnya tidak sehat, sebagai pengarah pementasan drama baru ini, Elizabeth tidak akan membiarkan satu pun kesalahan terjadi di atas panggung!"
  },
  AvgDialog_43816_Content_43 = {
    Text = "Manajer kelompok tari dengan bangga membusungkan dadanya, tatapannya yang menyapu sekeliling tampak seperti ayam jago yang sedang mencari musuh."
  },
  AvgDialog_43816_Content_44 = {
    Text = "Sepatu balet penari menjejakkan kaki berat di panggung, menarik perhatianmu kepadanya."
  },
  AvgDialog_43816_Content_45 = {
    Text = "Sepasang mata hijau yang dingin menatap ke arahmu, dan dalam sekejap, tubuhmu seperti merasakan ancaman, membangkitkan memori otot. Dalam waktu singkat, tubuhmu membawamu menyatu dengan kerumunan penari."
  },
  AvgDialog_43816_Content_46 = {
    Text = "Benar… kamu sudah melakukan dengan baik."
  },
  AvgDialog_43816_Content_47 = {
    Text = "Menjadi daun di pohon, hindari tatapan orang-orang itu, jangan biarkan mata mereka melihatmu lagi."
  },
  AvgDialog_43816_Content_48 = {
    Text = "Jangan biarkan pandangan kotor itu... menyadari keberadaanmu."
  },
  AvgDialog_43816_Content_5 = {
    Text = "Dibangunkan oleh musik dari tidur yang dalam, anggota tubuh yang lemas secara naluriah meregang, namun mata terasa sangat berat."
  },
  AvgDialog_43816_Content_6 = {
    Text = "Kelopak mata atas dan bawah menempel erat satu sama lain, tak peduli seberapa keras berusaha, tidak bisa membuka sedikit pun celah."
  },
  AvgDialog_43816_Content_7 = {
    Text = "Ugh... perasaan ini... seperti memasuki mimpi..."
  },
  AvgDialog_43816_Content_8 = {
    Text = "Di tengah suara musik yang memekakkan telinga, kesadaranmu secara bertahap mendapatkan kendali atas tubuh. Pada saat mata mulai merasakan rangsangan cahaya, tiba-tiba anggota tubuh menjadi kaku."
  },
  AvgDialog_43816_Content_9 = {
    Text = "Melompat dengan sangat baik, gadis-gadisku. Pertahankan momentum ini, ikuti irama musik terus—hei! Jangan melamun!"
  },
  AvgDialog_44435_Content_1 = {
    Text = "Ikatan Kutukan Pahit"
  },
  AvgDialog_44435_Content_2 = {
    Text = "Kenangan membanjir masuk bersama cahaya bintang yang berserakan."
  },
  AvgDialog_44435_Content_3 = {
    Text = "Kenangan-kenangan yang sengaja diciptakan dan dicabik-cabik secara paksa membanjiri benak Mason, lalu surut dengan cepat bagaikan ombak."
  },
  AvgDialog_44435_Content_4 = {
    Text = "Hingga akhirnya, dia tiba di kaki gunung bersalju, di depan pintu masuk gua yang gelap gulita."
  },
  AvgDialog_44435_Content_5 = {
    Text = "Mengikuti aliran sungai di bawah kaki, dia bisa mencapai sarang sang raksasa yang tertidur lelap."
  },
  AvgDialog_44435_Content_6 = {
    Text = "Dung dung. Dung dung."
  },
  AvgDialog_44435_Content_7 = {
    Text = "Itu adalah suara detak jantung seperti jam tua. Detak jantung yang dimiliki bersama olehnya dan sang raksasa."
  },
  AvgDialog_44435_Content_8 = {
    Text = "Aku mengerti sekarang……"
  },
  AvgDialog_44435_Content_9 = {
    Text = "Aku sudah memahami semuanya……"
  },
  AvgDialog_44436_Content_1 = {
    Text = "Kenapa……kenapa……"
  },
  AvgDialog_44436_Content_10 = {
    Text = "Yang merasa bahagia dengan kehidupan yang sederhana, adalah \"24\"."
  },
  AvgDialog_44436_Content_11 = {
    Text = "Yang disiksa oleh Asosiasi Pematung, juga adalah \"24\"."
  },
  AvgDialog_44436_Content_12 = {
    Text = "Tidak... jika bukan karena kepengecutanmu, kamu juga tidak akan diperlakukan seperti itu oleh Dokter itu…"
  },
  AvgDialog_44436_Content_13 = {Text = "Ssst……"},
  AvgDialog_44436_Content_14 = {
    Text = "Mason dengan lembut menutup bibir bayangan itu. Dia menundukkan kepala, berbisik di telinga sang bayangan."
  },
  AvgDialog_44436_Content_15 = {
    Text = "Akan kuberitahu sebuah rahasia: <Red:Dokter itu dibunuh olehku.>"
  },
  AvgDialog_44436_Content_16 = {
    Text = "Bagaimana mungkin kamu bisa memiliki keberanian seperti itu...?!"
  },
  AvgDialog_44436_Content_17 = {
    Text = "Membunuh bukanlah hal yang sulit. Saya tidak memiliki senjata di tangan saya, jadi saya menggunakan tangan untuk menghancurkan kepalanya seperti kenari."
  },
  AvgDialog_44436_Content_18 = {
    Text = "Pada akhirnya, tanganku sudah lama kehilangan rasa, dan yang terlihat di mataku hanyalah darah, tidak ada yang lain."
  },
  AvgDialog_44436_Content_19 = {
    Text = "Karena aku harus memastikan dia benar-benar mati. Selama dia masih bernapas, dia pasti akan menyakiti anak-anak di rumah penampungan, dan juga Jenkin…"
  },
  AvgDialog_44436_Content_2 = {
    Text = "Bayangan dikalahkan oleh kalian. Dia yang kalah di ruang kesadaran terbaring di tanah, tubuhnya mengeluarkan titik-titik cahaya halus."
  },
  AvgDialog_44436_Content_20 = {
    Text = "Dia sama seperti orang-orang di Asosiasi Pematung itu, tidak—dia bahkan lebih mengerikan dari mereka…"
  },
  AvgDialog_44436_Content_21 = {
    Text = "Dia adalah iblis yang sesungguhnya."
  },
  AvgDialog_44436_Content_22 = {
    Text = "Saat itu, apa yang sedang kulakukan… Aku sama sekali tidak tahu…"
  },
  AvgDialog_44436_Content_23 = {
    Text = "Mason menggelengkan kepalanya pelan."
  },
  AvgDialog_44436_Content_24 = {
    Text = "Sebenarnya kau tahu, ini adalah keberanian yang kau dan \"24\" lainnya pinjamkan padaku."
  },
  AvgDialog_44436_Content_25 = {
    Text = "Semua \"24\" bergabung menjadi satu \"Mason\". Tidak ada \"24\" yang dapat berada dalam keadaan terpencil."
  },
  AvgDialog_44436_Content_26 = {
    Text = "Seperti semua sungai yang akan bermuara ke satu tempat, semua \"24\" pun akan berkumpul di satu tempat..."
  },
  AvgDialog_44436_Content_27 = {
    Text = "Mason mencium lembut dahi sang bayangan."
  },
  AvgDialog_44436_Content_28 = {
    Text = "Kembali kepadaku."
  },
  AvgDialog_44436_Content_29 = {
    Text = "Tubuh sang bayangan berubah menjadi cahaya bintang yang bertebaran. Mereka melayang-layang di sekitar Mason, lalu meresap ke dalam kulitnya."
  },
  AvgDialog_44436_Content_3 = {
    Text = "Aku yang sekuat ini, aku yang penuh amarah……bagaimana mungkin kalah dari kalian, kalah dari pengecut ini……"
  },
  AvgDialog_44436_Content_30 = {
    Text = "Begitu rupanya… Aku mengerti sekarang."
  },
  AvgDialog_44436_Content_31 = {
    Text = "Kamu adalah asal mula segalanya, dan juga akhir dari segalanya…"
  },
  AvgDialog_44436_Content_32 = {
    Text = "Suaranya perlahan menghilang dalam pelukan yang hangat."
  },
  AvgDialog_44436_Content_33 = {
    Text = "Cahaya bintang bagaikan kunang-kunang di kegelapan malam, samar-samar terlihat, hingga akhirnya lenyap tak terlihat."
  },
  AvgDialog_44436_Content_34 = {
    Text = "…Selamat malam, \"dua puluh empat bagian dari diriku\"."
  },
  AvgDialog_44436_Content_35 = {
    Text = "<Yellow:Catatan Investigasi Ruang Buatan Ⅳ>\n\n■Nomor Ruang: M-C06\n■Waktu Jatuh: Tahun Diluvian 315, Desember@1\n■Lokasi Jatuh: Jalan Camberwell, Distrik Timur"
  },
  AvgDialog_44436_Content_36 = {
    Text = "<Yellow:Hasil Penyelidikan Ⅰ>\n\nDomain berakhir dengan cara yang tenang.\nSetelah itu, kondisi Miss Mason menjadi jauh lebih stabil, ini adalah hal yang sangat membahagiakan bagi semua orang.\nKami sedang mendekati sosok Miss Mason yang sebenarnya."
  },
  AvgDialog_44436_Content_37 = {
    Text = [[
Universitas Misagor, Kantor Administrasi
Satu hari kemudian]]
  },
  AvgDialog_44436_Content_38 = {
    Text = "Apa, dewan peninjau mencabut tuntutannya?"
  },
  AvgDialog_44436_Content_39 = {
    Text = "Ya. Mereka sekarang sibuk bekerja sama dengan orang-orang dari Dinas Lingkungan Hidup Kota untuk menangani wabah ular."
  },
  AvgDialog_44436_Content_4 = {
    Text = "Karena……"
  },
  AvgDialog_44436_Content_40 = {
    Text = "Wabah ular……?"
  },
  AvgDialog_44436_Content_41 = {
    Text = "Kerang membuka halaman \"Londinium Post\" beberapa hari lalu dan menunjukkannya di depanmu."
  },
  AvgDialog_44436_Content_42 = {
    Text = "\"Baru-baru ini, dari klinik mendiang Dokter Bernard tiba-tiba muncul sejumlah besar ular albino dari spesies yang tidak diketahui, menyebabkan kemacetan serius pada lalu lintas dan kehidupan warga setempat……\""
  },
  AvgDialog_44436_Content_43 = {
    Text = "\"Menurut kesaksian saksi mata, ini adalah adegan paling mengerikan yang pernah dia lihat seumur hidupnya. Jika pembaca yang tidak beruntung juga menyaksikan tempat kejadian, silakan hubungi Dokter @2 untuk mendapatkan bantuan…\""
  },
  AvgDialog_44436_Content_44 = {
    Text = "\"Nomor @4……\""
  },
  AvgDialog_44436_Content_45 = {
    Text = "Di samping berita itu juga terlampir foto, dan kamu sepertinya melihat beberapa sosok familiar dari dewan peninjau."
  },
  AvgDialog_44436_Content_46 = {
    Text = "Mereka mengenakan masker dan membawa jaring, bekerja keras membersihkan ular-ular kecil yang terus bermunculan. Wajah mereka dipenuhi rasa lelah dan ketidaknyamanan yang sulit disembunyikan."
  },
  AvgDialog_44436_Content_47 = {
    Text = "Masalahnya sangat besar dengan yang disebut \"Dokter Bernard\"."
  },
  AvgDialog_44436_Content_48 = {
    Text = "Kami menemukan orang dari Royal Medical Society, dan deskripsi penampilan yang diberikan oleh mereka benar-benar berbeda dari pria yang dilihat William."
  },
  AvgDialog_44436_Content_49 = {
    Text = "Dengan kata lain, si korban telah mencuri identitas Dokter Bernard ini. Namun melihat situasi saat ini, apakah dokter palsu ini benar-benar sudah mati masih belum bisa dipastikan."
  },
  AvgDialog_44436_Content_50 = {
    Text = "Lagipula, di lokasi kejadian bahkan tidak ditemukan jejak mayat sama sekali……"
  },
  AvgDialog_44436_Content_51 = {
    Text = [[
17 Desember, hari kejadian
Klinik Dokter Bernard]]
  },
  AvgDialog_44436_Content_52 = {
    Text = "Sesi terapi hari ini sampai di sini saja. Nona Mason, pemulihanmu cukup baik."
  },
  AvgDialog_44436_Content_53 = {
    Text = "Benarkah? Tapi semua orang bilang kondisiku semakin parah……"
  },
  AvgDialog_44436_Content_54 = {
    Text = "Aku dan mereka mungkin memiliki pemahaman yang berbeda tentang hal-hal serius. Apakah kamu sudah meminum beberapa Tetesi yang kuberikan sesuai waktu?"
  },
  AvgDialog_44436_Content_55 = {
    Text = "BRAAAKK——!!"
  },
  AvgDialog_44436_Content_56 = {
    Text = "Pria itu tanpa sengaja menyenggol dokumen di sisinya, halaman-halamannya yang berwarna kuning tersebar di seluruh lantai."
  },
  AvgDialog_44436_Content_57 = {
    Text = "Anda adalah seorang Dokter yang bekerja siang malam, hal kecil seperti mengambil barang saja biarlah..."
  },
  AvgDialog_44436_Content_58 = {Text = "Saya……"},
  AvgDialog_44436_Content_59 = {
    Text = "Tangan berhenti kurang dari 2 inci dari dokumen. Ini adalah tumpukan arsip identitas, Mason dengan susah payah mengenali beberapa kata yang masih terdengar familiar."
  },
  AvgDialog_44436_Content_6 = {
    Text = "Biarkan aku yang melakukannya."
  },
  AvgDialog_44436_Content_60 = {
    Text = "Laporan eksperimen, catatan pemindahan……?"
  },
  AvgDialog_44436_Content_61 = {
    Text = "<Shake:Ini… anak-anak yang hilang dari panti asuhan! Tidak, bukan hanya itu……>"
  },
  AvgDialog_44436_Content_62 = {
    Text = "Di sudut arsip paling bawah yang tersingkap, wajah Jenkins yang sedikit keras kepala muncul di hadapan Mason."
  },
  AvgDialog_44436_Content_63 = {
    Text = "Ini adikmu, kan? Aku pernah melihatnya. Dia sangat mengkhawatirkanmu, bahkan pernah mencoba menyelinap masuk ke sini."
  },
  AvgDialog_44436_Content_64 = {
    Text = "Dia tersenyum tipis, ekspresinya pun menjadi lembut."
  },
  AvgDialog_44436_Content_65 = {
    Text = "Aku juga pernah punya banyak saudara… Mereka hanya takut padaku, gentar padaku, jadi aku memakan mereka semua."
  },
  AvgDialog_44436_Content_66 = {
    Text = "Semua… dimakan……?"
  },
  AvgDialog_44436_Content_67 = {
    Text = "Tenang saja, Nona Mason. Aku tidak memakan anak-anak ini, hanya mengirim mereka ke <Red:tempat yang aman>."
  },
  AvgDialog_44436_Content_68 = {
    Text = "Jadi, kau adalah dalang di balik kasus-kasus penghilangan ini..."
  },
  AvgDialog_44436_Content_69 = {
    Text = "<Shake:Lelucon ini sama sekali tidak lucu, Tuan Bernard……>"
  },
  AvgDialog_44436_Content_7 = {
    Text = "Mason duduk di samping bayangan itu, memeluk bayangan yang tak bisa bergerak lagi ke dalam dekapannya."
  },
  AvgDialog_44436_Content_70 = {
    Text = "Tuan Bernard… maksudmu dia?"
  },
  AvgDialog_44436_Content_71 = {
    Text = "Setelah berkata demikian, dari mulut pria itu menjulur lidah bercabang yang panjang, di ujungnya terlilit sebuah jari putus yang berlumuran darah."
  },
  AvgDialog_44436_Content_72 = {
    Text = "Tubuhnya terlalu besar, sampai sekarang aku belum selesai mencernanya."
  },
  AvgDialog_44436_Content_73 = {
    Text = "Mari berkenalan kembali, namaku <Yellow:Albino>, apoteker dari Asosiasi Pematung."
  },
  AvgDialog_44436_Content_74 = {
    Text = "AAAAAAA——!!"
  },
  AvgDialog_44436_Content_75 = {
    Text = "Kaki Mason melemas, dan ia jatuh terduduk ke tanah dengan keras."
  },
  AvgDialog_44436_Content_76 = {
    Text = "Kamu... apakah kamu juga akan membawa Jenkin...?"
  },
  AvgDialog_44436_Content_77 = {
    Text = "Pria itu membetulkan bingkai kacamatanya, mengeluarkan catatan medis dan menulis dengan cepat di atasnya."
  },
  AvgDialog_44436_Content_78 = {
    Text = "Pupil membesar, tubuh gemetar hebat, detak jantung meningkat…… Kau pasti sangat ketakutan sekarang. Kedinginan?"
  },
  AvgDialog_44436_Content_79 = {
    Text = "Tidak…… jangan mendekat……"
  },
  AvgDialog_44436_Content_8 = {
    Text = "Karena... kamu tidak menerima semua \"24\"."
  },
  AvgDialog_44436_Content_80 = {
    Text = "Segera, kamu akan pingsan akibat suplai darah ke otak tidak mencukupi, sama seperti manusia lain yang membosankan."
  },
  AvgDialog_44436_Content_81 = {
    Text = "Dia mengangkat kepalanya dari buku catatan medis, pupil vertikal keemasannya samar-samar berkilat dengan secercah kegembiraan."
  },
  AvgDialog_44436_Content_82 = {
    Text = "Atau…… kau akan menunjukkan reaksi yang berbeda?"
  },
  AvgDialog_44436_Content_83 = {
    Text = "Dua puluh menit kemudian"
  },
  AvgDialog_44436_Content_84 = {
    Text = "Aku membunuh orang, aku benar-benar membunuh seorang dokter…… Mereka tidak akan mempercayaiku……"
  },
  AvgDialog_44436_Content_85 = {
    Text = "Tidak, kenapa tadi aku membunuhnya……"
  },
  AvgDialog_44436_Content_86 = {
    Text = "Mason tersadar seperti baru bangun dari mimpi, dan meninggalkan tempat kejadian dengan panik."
  },
  AvgDialog_44436_Content_87 = {
    Text = "Tubuh pria itu terkulai lemas di sudut dinding. Kepalanya sudah hancur sejak tadi, darah terus merembes keluar darinya."
  },
  AvgDialog_44436_Content_88 = {
    Text = "Entah berapa lama berlalu, tiba-tiba serangkaian belenggu kutukan hitam menyala di leher mayat itu."
  },
  AvgDialog_44436_Content_89 = {
    Text = "Belenggu kutukan itu berputar perlahan bagaikan ular, daging dan darah yang sudah hancur menjadi bubur pun mulai berkumpul dan menyusun ulang diri……"
  },
  AvgDialog_44436_Content_9 = {
    Text = "Yang terjebak dalam kesulitan hidup dan tidak tahu harus meminta bantuan ke mana, adalah \"24\"."
  },
  AvgDialog_44436_Content_90 = {
    Text = "Hingga akhirnya, \"mayat\" itu perlahan-lahan bangkit duduk."
  },
  AvgDialog_44436_Content_91 = {
    Text = "Huh…… tidak buruk, tinktur-tinktur itu cukup berguna. Seluruh potensi tersembunyi dalam tubuhnya telah meledak keluar."
  },
  AvgDialog_44436_Content_92 = {
    Text = "Albino menjulurkan lidah ular panjangnya, dengan santai menjilati bersih semua darah di wajahnya."
  },
  AvgDialog_44436_Content_93 = {
    Text = "Mangsa sudah tumbuh dewasa. Sudah waktunya melapor kepada Tuan Ketua kita."
  },
  AvgDialog_44436_Content_94 = {
    Text = "Dia memungut buku catatan medis di kakinya, lalu pergi dengan santai."
  },
  AvgDialog_44437_Content_1 = {
    Text = "Melodi Keemasan"
  },
  AvgDialog_44437_Content_10 = {
    Text = "Ketenangan pucat di permukaan laut pecah. Ular laut berwarna ungu kehitaman tiba-tiba menyembur keluar, melilit semua orang dengan erat."
  },
  AvgDialog_44437_Content_11 = {
    Text = "Ugh… AAAAAAAH!!"
  },
  AvgDialog_44437_Content_12 = {
    Text = "Diiringi suara samar yang aneh, tubuh ular berubah menjadi bilah hitam pekat yang menembus tubuh manusia sepenuhnya."
  },
  AvgDialog_44437_Content_13 = {
    Text = "<Big:Jangan mendekat>...Eh?"
  },
  AvgDialog_44437_Content_15 = {
    Text = "Sentuhan lembut dan dingin terasa di leher yang dililit ular hitam, dan luka-luka itu perlahan mulai sembuh."
  },
  AvgDialog_44437_Content_16 = {
    Text = "Luka-lukaku… semuanya sembuh?"
  },
  AvgDialog_44437_Content_17 = {
    Text = "Ular hitam tanpa ragu meninggalkan kalian, lalu dengan kecepatan tinggi melilit erat Glen."
  },
  AvgDialog_44437_Content_18 = {
    Text = "Cepat lari, penyihir itu da… tang…"
  },
  AvgDialog_44437_Content_19 = {
    Text = "Ular-ular hitam merayap keluar dari mata dan mulut Igren. Dia bahkan tidak sempat mengucapkan satu kalimat utuh sebelum ambruk tak berdaya."
  },
  AvgDialog_44437_Content_2 = {
    Text = [[
Mendesah untuk Rasul Lautan.
Mendesah untuk cahaya kita, harapan kita.

Karena takdir dibuang ke lautan, kami meraung, meratap, dan menangis hingga air mata habis.]]
  },
  AvgDialog_44437_Content_21 = {
    Text = "Tak lama kemudian, jasad-jasad yang hancur tak terhitung jumlahnya mengapung di permukaan laut."
  },
  AvgDialog_44437_Content_22 = {
    Text = "Ini adalah pembantaian yang sunyi."
  },
  AvgDialog_44437_Content_23 = {
    Text = "<Gray:Sudah selesai? Hebat sekali, memang pantas disebut Miriam.>"
  },
  AvgDialog_44437_Content_24 = {
    Text = "Kau membantu kami… Siapa kau?"
  },
  AvgDialog_44437_Content_25 = {
    Text = "Wanita berkerudung hitam itu tidak berkata apa-apa. Dia berdiri tegak di haluan kapal, di antara kalian hanya terhalang selapis kabut tebal."
  },
  AvgDialog_44437_Content_26 = {
    Text = "Tampak begitu dekat, namun terasa jauh tak terjangkau."
  },
  AvgDialog_44437_Content_27 = {
    Text = "Wanita itu menatap Goliath yang terpaku, sudut bibirnya menyunggingkan senyuman. Ia mengulurkan tangan menunjuk ke kejauhan, seolah sebuah undangan tanpa kata."
  },
  AvgDialog_44437_Content_28 = {
    Text = "Kemudian ia memutar haluan perahunya dan pergi dengan tenang."
  },
  AvgDialog_44437_Content_29 = {
    Text = "Tunggu, jangan pergi… <Big:Jangan pergi!>"
  },
  AvgDialog_44437_Content_3 = {
    Text = "Pandangan tiba-tiba meredup, cahaya matahari yang menyilaukan perlahan menghilang, kabut pekat menyelimuti seluruh permukaan laut."
  },
  AvgDialog_44437_Content_30 = {
    Text = "Kabut menghilang, seberkas cahaya menembus celah awan, dan buih ombak berkilau bagai emas."
  },
  AvgDialog_44437_Content_31 = {
    Text = "Kau mengerjapkan mata, di ujung lautan sudah tak ada siapa pun."
  },
  AvgDialog_44437_Content_32 = {
    Text = "Angin dan ombak berangsur mereda, kau dan Goliath berdesakan di satu-satunya papan yang masih utuh, terus terengah-engah."
  },
  AvgDialog_44437_Content_33 = {
    Text = "Lautan yang semula biru telah diwarnai merah oleh darah, kalian berdua bagaikan rumput apung yang terhanyut di dalamnya."
  },
  AvgDialog_44437_Content_34 = {
    Text = "Pada akhirnya tetap tidak berhasil mendapatkan kapal… Sekarang entah bagaimana caranya pulang."
  },
  AvgDialog_44437_Content_35 = {
    Text = "Tidak usah pulang."
  },
  AvgDialog_44437_Content_36 = {
    Text = "Goliath menopang satu kakinya, menatap kosong ke arah kepergian Miriam."
  },
  AvgDialog_44437_Content_37 = {
    Text = "Aku sudah memutuskan, aku akan mencari penyihir itu. Mau ikut denganku?"
  },
  AvgDialog_44437_Content_38 = {
    Text = "Uhuk uhuk, \"Hanya orang bodoh yang mempercayakan nyawanya pada orang lain.\""
  },
  AvgDialog_44437_Content_39 = {
    Text = "Kau sengaja merendahkan suaramu, menirukan nada bicara Goliath sebelumnya dan mengulang kata-katanya."
  },
  AvgDialog_44437_Content_4 = {
    Text = "Oh, lindungilah mereka yang tertimpa banyak bencana.\nArahkan tatapan belas kasihmu kepada kami…"
  },
  AvgDialog_44437_Content_40 = {
    Text = "Hmph, itu karena taruhannya belum cukup besar. Kekuatan yang bisa menghancurkan segalanya dalam sekejap seperti itu, aku belum pernah melihatnya."
  },
  AvgDialog_44437_Content_41 = {
    Text = "Lagipula, tadi dia membantu kita, dan bahkan mengundangku…"
  },
  AvgDialog_44437_Content_42 = {
    Text = "Tapi bagaimana kalau… itu jebakan?"
  },
  AvgDialog_44437_Content_43 = {Text = "Jebakan…"},
  AvgDialog_44437_Content_44 = {
    Text = "Masih ingat pertanyaan yang kau ajukan padaku sebelumnya?"
  },
  AvgDialog_44437_Content_45 = {
    Text = "…Yang penting adalah berkat Tuan, kita berdua sekarang masih hidup."
  },
  AvgDialog_44437_Content_46 = {
    Text = "Menurut Anda, kenapa bisa begitu?"
  },
  AvgDialog_44437_Content_47 = {
    Text = "Sekarang aku tahu jawabannya."
  },
  AvgDialog_44437_Content_48 = {
    Text = "Apa jawabannya?"
  },
  AvgDialog_44437_Content_49 = {
    Text = "Sekawanan burung laut tiba-tiba terbang mendekat secara bergerombol. Sayap putih yang mengepak bagaikan awan yang terbang, berkibar bebas di tengah angin laut."
  },
  AvgDialog_44437_Content_5 = {
    Text = "Nyanyian kuno nan misterius mengambang di udara. Sosok wanita yang berdiri di haluan kapal tampak samar-samar, bagaikan hantu yang berkeliaran di dalam kabut."
  },
  AvgDialog_44437_Content_50 = {
    Text = "Goliath sama sekali tidak terganggu oleh kawanan burung itu. Ia menatap lurus ke depan dengan penuh fokus, matanya berkilau penuh semangat."
  },
  AvgDialog_44437_Content_51 = {
    Text = "Karena aku adalah Goliath."
  },
  AvgDialog_44437_Content_52 = {
    Text = "Pemimpin dengan masa pemerintahan terlama dalam sejarah Filistin, raksasa perkasa dengan kehendak tak terpatahkan, pahlawan suku yang disegani di seluruh penjuru — Goliath sang Raksasa."
  },
  AvgDialog_44437_Content_53 = {
    Text = "Meskipun hanya tersisa satu pengikut, selama masih ada secercah kesempatan terakhir, aku bisa bangkit kembali."
  },
  AvgDialog_44437_Content_54 = {
    Text = "Penyihir itu adalah kesempatan terakhirku. Hanya dia yang bisa memberiku kekuatan absolut."
  },
  AvgDialog_44437_Content_55 = {
    Text = "Meskipun itu jebakan, aku tetap akan pergi."
  },
  AvgDialog_44437_Content_56 = {
    Text = "Lalu kenapa kau menyelamatkanku? \"Sampah\" sepertiku mungkin tidak bisa membantumu sama sekali…"
  },
  AvgDialog_44437_Content_57 = {
    Text = "Kau sengaja menekankan pengucapan kata tertentu, membuat Goliath tertawa terbahak-bahak."
  },
  AvgDialog_44437_Content_58 = {
    Text = "Sinar matahari menembus awan dan menyinari segalanya dengan cahaya keemasan. Helai-helai rambut yang berantakan menari lembut di bawah langit biru."
  },
  AvgDialog_44437_Content_59 = {
    Text = "Mana ada di dunia ini pemimpin tanpa pengikut yang bisa mencapai sesuatu."
  },
  AvgDialog_44437_Content_6 = {
    Text = "Eh, ada seseorang yang bernyanyi?"
  },
  AvgDialog_44437_Content_60 = {
    Text = "Bocah, kau bukan sampah. Kau adalah satu-satunya pengikut raksasa Goliath, tak ada yang bisa menggantikan posisimu."
  },
  AvgDialog_44437_Content_61 = {
    Text = "Setelah aku meraih kejayaan, paling tidak aku akan mengangkatmu menjadi kepala suku!"
  },
  AvgDialog_44437_Content_62 = {
    Text = "…Tidak perlu juga."
  },
  AvgDialog_44437_Content_63 = {
    Text = "Tanpa terasa langit perlahan menggelap. Senja di ufuk barat bagaikan aliran sungai berkilauan keemasan, mengalir di antara cakrawala."
  },
  AvgDialog_44437_Content_64 = {
    Text = "Hei, kau tahu tidak? Alasan seorang pahlawan bisa menjadi pahlawan adalah karena ada orang seperti kita yang menjadi latar belakangnya."
  },
  AvgDialog_44437_Content_65 = {
    Text = "<Small:Jadi aku juga sangat penting, paham kan…>"
  },
  AvgDialog_44437_Content_66 = {
    Text = "<Small:Hmm…>"
  },
  AvgDialog_44437_Content_67 = {
    Text = "Kata-kata lirih itu bagaikan bunga dandelion yang tertiup angin laut, terbawa pergi ke tempat yang sangat jauh."
  },
  AvgDialog_44437_Content_68 = {
    Text = "Kau dan Goliath duduk di atas papan kayu tipis, dilihat dari kejauhan, kalian tampak seperti daun kecil yang hanyut di lautan keemasan."
  },
  AvgDialog_44437_Content_69 = {
    Text = "Tak ada yang tahu ke mana kalian pada akhirnya akan berlayar."
  },
  AvgDialog_44437_Content_7 = {
    Text = "<Shake:Penyihir, itu penyihir itu!!>"
  },
  AvgDialog_44437_Content_8 = {
    Text = "Bagaimana mungkin… Jadi legenda itu benar adanya…"
  },
  AvgDialog_44437_Content_9 = {
    Text = "<Red:Belas kasihan. Belas kasihan. Belas kasihan…>"
  },
  AvgDialog_44438_Content_1 = {Text = "\"Sumber\""},
  AvgDialog_44438_Content_10 = {
    Text = "Eh? Kata Nona Winkel, Mystic Realm-ku sangat menakutkan, penuh dengan monster-monster ganas di mana-mana……"
  },
  AvgDialog_44438_Content_11 = {
    Text = "Itu semua hanyalah khayalannya belaka. Namun, aku memang melihat sesuatu yang sangat istimewa, seperti \"dirimu\"."
  },
  AvgDialog_44438_Content_12 = {Text = "Aku……?"},
  AvgDialog_44438_Content_13 = {
    Text = "Kamu tertawa pelan, lalu mengedipkan mata padanya."
  },
  AvgDialog_44438_Content_14 = {
    Text = "Ini rahasia antara aku dan \"dia\", kalau ada kesempatan di masa depan, akan kuceritakan pelan-pelan padamu."
  },
  AvgDialog_44438_Content_15 = {
    Text = "Kakak——!!"
  },
  AvgDialog_44438_Content_16 = {
    Text = "Jenkins tiba-tiba melompat keluar dari semak bunga di dekat kalian."
  },
  AvgDialog_44438_Content_17 = {
    Text = "Aku dan Aigis sudah kembali dari jalan-jalan. Lihat apa yang kami temukan?"
  },
  AvgDialog_44438_Content_18 = {
    Text = "Jenkin menggoyangkan sebuah pita merah di tangannya. Berbeda dari pita yang sering digunakan Mason, ujungnya terdapat lonceng berwarna kuning pudar."
  },
  AvgDialog_44438_Content_19 = {
    Text = "Angin sepoi berhembus, lonceng itu mengeluarkan bunyi gemerincing yang jernih, bagaikan peri kecil yang riang."
  },
  AvgDialog_44438_Content_2 = {
    Text = [[
Universitas Misage, di dalam kampus
Tiga hari kemudian]]
  },
  AvgDialog_44438_Content_20 = {
    Text = "Ini yang pernah kulihat di Mystic Realm……"
  },
  AvgDialog_44438_Content_21 = {
    Text = "Eh, kamu juga pernah melihatnya di Mystic Realm? Kalau begitu, kamu pasti bertemu dengan kakak yang berubah jadi kucing, kan!"
  },
  AvgDialog_44438_Content_22 = {
    Text = "Ja-jangan bilang lagi……"
  },
  AvgDialog_44438_Content_23 = {
    Text = "Kenapa tidak bisa dikatakan? Pita ini adalah benda peringatan yang sangat penting!"
  },
  AvgDialog_44438_Content_24 = {
    Text = "Pada masa itu, setiap hari aku merawatmu dan menemanimu bermain, rasanya sangat bahagia."
  },
  AvgDialog_44438_Content_25 = {
    Text = "Jenkins dengan lembut meletakkan pita itu di tangan Mason."
  },
  AvgDialog_44438_Content_26 = {
    Text = "Aku masih ingat kamu pernah berkata, di kehidupan selanjutnya ingin menjadi seekor kucing."
  },
  AvgDialog_44438_Content_27 = {
    Text = "Kalau benar-benar bisa hidup tanpa beban seperti itu, pasti menyenangkan sekali. Aku juga bisa terus merawatmu!"
  },
  AvgDialog_44438_Content_28 = {
    Text = "Mason menunduk sambil tersenyum, jari-jarinya mengusap lembut pita yang dingin dan halus itu."
  },
  AvgDialog_44438_Content_29 = {
    Text = "Jadi seekor kucing? Itu urusan kehidupan selanjutnya."
  },
  AvgDialog_44438_Content_3 = {
    Text = "Begitu rupanya. Tidak lama setelah membunuh Albino, kamu dibawa pergi oleh orang-orang dari Asosiasi Pematung."
  },
  AvgDialog_44438_Content_30 = {
    Text = "Sekarang aku hanya ingin hidup dengan baik sebagai \"Mason\"."
  },
  AvgDialog_44438_Content_31 = {
    Text = "Jenkin memandangmu dengan sedikit terkejut."
  },
  AvgDialog_44438_Content_32 = {
    Text = "Eh…… Sepertinya Mystic Realm kali ini sangat mengubah Kakak ya, dulu dia tidak seperti ini."
  },
  AvgDialog_44438_Content_33 = {
    Text = "Aku jadi saksi, semua yang dikatakan Nona Mason itu benar."
  },
  AvgDialog_44438_Content_34 = {
    Text = "Kamu dan Mason saling bertukar senyum. Pikiranmu kembali ke saat itu, tepat sebelum Mystic Realm runtuh……"
  },
  AvgDialog_44438_Content_35 = {
    Text = "Begitu rupanya… Aku mengerti sekarang."
  },
  AvgDialog_44438_Content_36 = {
    Text = "Kamu adalah asal mula segalanya, dan juga akhir dari segalanya…"
  },
  AvgDialog_44438_Content_37 = {
    Text = "Seiring lenyapnya cahaya bintang terakhir, dunia seolah ditelan oleh tinta hitam."
  },
  AvgDialog_44438_Content_38 = {
    Text = "Kamu mendengar suara lonceng dari kejauhan. Dong——Dong——"
  },
  AvgDialog_44438_Content_39 = {
    Text = "Ini…… Mystic Realm akan runtuh?!"
  },
  AvgDialog_44438_Content_4 = {
    Text = "Dari situlah cerita selanjutnya bermula."
  },
  AvgDialog_44438_Content_40 = {
    Text = "Pegang tanganku, %player%{Male=tuan,Female=nyonya}!"
  },
  AvgDialog_44438_Content_41 = {
    Text = "Kamu menggenggam erat tangan Mason."
  },
  AvgDialog_44438_Content_42 = {
    Text = "Pada saat itu, darahmu seolah mengalir ke tubuhnya tanpa hambatan, kesadaran kalian mulai menyatu menjadi satu."
  },
  AvgDialog_44438_Content_43 = {
    Text = "Kamu merasa dirimu perlahan tertidur, mimpi-mimpi tak terhitung berdatangan silih berganti, membawamu meluncur ke dalam kegelapan."
  },
  AvgDialog_44438_Content_45 = {
    Text = "Kamu berdiri di dalam gua, di bawah kakimu mengalir sungai emas yang berkilauan, seolah-olah pembuluh darah yang menembus bumi."
  },
  AvgDialog_44438_Content_46 = {
    Text = "Ini cahaya bintang yang pernah kulihat sebelumnya… Jadi semuanya berkumpul di sini?"
  },
  AvgDialog_44438_Content_47 = {
    Text = "<Red:Kembalilah, kembalilah……>"
  },
  AvgDialog_44438_Content_48 = {
    Text = "Kau mengikuti arah aliran cahaya bintang, melangkah menuju kedalaman gua."
  },
  AvgDialog_44438_Content_5 = {
    Text = "Ya. Sekarang aku sudah mengingat semuanya, itu bukan kenangan yang menyenangkan……"
  },
  AvgDialog_44438_Content_50 = {
    Text = "Ini… apa?!"
  },
  AvgDialog_44438_Content_51 = {
    Text = "Tempat ini bagaikan sumber utama dari segala sesuatu yang terdistorsi, cacat, dan najis."
  },
  AvgDialog_44438_Content_52 = {
    Text = "Gumpalan abu-abu pucat terus bergetar dan membengkak, membelah diri menjadi makhluk-makhluk cacat yang menggeliat, seperti lambung yang terus-menerus meronta."
  },
  AvgDialog_44438_Content_53 = {
    Text = "Namun sebelum sempat naik ke darat, mereka sudah jatuh kembali ke dalam kolam, ditelan oleh mulut besar yang terbuka di tubuh gumpalan itu."
  },
  AvgDialog_44438_Content_54 = {
    Text = "Siluet makhluk-makhluk ini tampak familiar… Jangan-jangan…"
  },
  AvgDialog_44438_Content_55 = {
    Text = "Tiba-tiba kau merasakan firasat yang sangat kuat. Kau melangkah menembus cairan abu-abu itu, mendekati gumpalan tersebut."
  },
  AvgDialog_44438_Content_56 = {
    Text = "Mason… apakah itu kau?"
  },
  AvgDialog_44438_Content_57 = {
    Text = "Gumpalan itu berhenti sejenak, lalu mulai bergerak pelan-pelan. Itu mengeluarkan suara gemerisik, seolah-olah memberikan sapaan yang ramah."
  },
  AvgDialog_44438_Content_58 = {
    Text = "Kau memandang makhluk-makhluk yang merangkak berlutut di dalam kolam, bergerak susah payah, mengejang tanpa henti di dalam cairan lengket itu, hanya demi bisa kembali ke pelukan gumpalan tersebut."
  },
  AvgDialog_44438_Content_59 = {
    Text = "Seperti para peziarah yang menerjang badai salju demi mencari mukjizat."
  },
  AvgDialog_44438_Content_6 = {
    Text = "Kamu perlahan menggenggam tangan Mason."
  },
  AvgDialog_44438_Content_60 = {
    Text = "<Change>Semua akar dari segala sesuatu yang tidak suci, tidak bersih, dan tidak baik…"
  },
  AvgDialog_44438_Content_61 = {
    Text = "<Change>Kembali!"
  },
  AvgDialog_44438_Content_62 = {
    Text = "Karena di sinilah ujung dari semua sungai, tak peduli seberapa jauh jaraknya, pada akhirnya semuanya akan berkumpul di sini."
  },
  AvgDialog_44438_Content_63 = {
    Text = "Jadi begitu… Ini yang kamu lakukan setiap hari?"
  },
  AvgDialog_44438_Content_64 = {
    Text = "Dengan tubuh yang lemah, menarik kembali kepribadian-kepribadian yang tercerai-berai, dan berusaha sekuat tenaga mempertahankan penampilan sebagaimana layaknya \"orang normal\"."
  },
  AvgDialog_44438_Content_65 = {
    Text = "……Pantas saja aku memimpikan hal-hal di masa lalu."
  },
  AvgDialog_44438_Content_66 = {
    Text = "Terakhir kali melihat cahaya bintang ini, aku tiba-tiba merasa diriku sangat mirip dengan mereka."
  },
  AvgDialog_44438_Content_67 = {
    Text = "……Tapi ada juga yang berbeda. Mereka tahu di mana kampung halaman mereka, sedangkan aku bahkan kehilangan ingatanku."
  },
  AvgDialog_44438_Content_68 = {
    Text = "Hidungmu tiba-tiba terasa perih, kamu perlahan mengusap gumpalan daging itu, merasakan denyut nadinya yang tenang."
  },
  AvgDialog_44438_Content_69 = {
    Text = "Mason…… Suatu hari nanti aku juga akan menemukan kampung halamanku, kan? Seperti yang kalian lakukan sekarang……"
  },
  AvgDialog_44438_Content_7 = {
    Text = "Semuanya sudah berlalu. Aku menjamin kepadamu, hal-hal itu tidak akan pernah terjadi lagi."
  },
  AvgDialog_44438_Content_70 = {
    Text = "Gumpalan daging itu bergerak-gerak, membelah ujungnya menjadi tentakel lembut dan licin, perlahan menyeka air mata di sudut matamu."
  },
  AvgDialog_44438_Content_71 = {
    Text = "<Change>Pasti akan."
  },
  AvgDialog_44438_Content_72 = {
    Text = "<Change>Jangan menangis."
  },
  AvgDialog_44438_Content_73 = {
    Text = "Gemuruh……"
  },
  AvgDialog_44438_Content_74 = {
    Text = "Dari kedalaman mantel terdengar getaran samar, dinding batu terbelah membentuk retakan-retakan."
  },
  AvgDialog_44438_Content_75 = {
    Text = "Waktu hingga runtuhnya Alam Rahasia: <Red:0> menit"
  },
  AvgDialog_44438_Content_76 = {
    Text = "Kamu berbalik dan meninggalkan gua. Saat mencapai pintu gua, kamu tidak bisa menahan diri untuk menoleh ke arahnya sekali terakhir."
  },
  AvgDialog_44438_Content_77 = {
    Text = "Sampai jumpa, Nona Mason."
  },
  AvgDialog_44438_Content_78 = {
    Text = "Kebahagiaan, kesedihan, penderitaan…… Kepribadian dan emosi yang berbeda datang dan pergi, tapi dia selalu tetap tinggal di gua batu itu."
  },
  AvgDialog_44438_Content_79 = {Text = "Dia hidup."},
  AvgDialog_44438_Content_8 = {
    Text = "Terima kasih……%player%{Male=tuan,Female=nyonya}."
  },
  AvgDialog_44438_Content_9 = {
    Text = "Seharusnya aku yang berterima kasih padamu. Saat Domain runtuh, kamu memberiku banyak dorongan dan penghiburan."
  },
  AvgDialog_44439_Content_1 = {
    Text = "Fuga Keemasan"
  },
  AvgDialog_44439_Content_11 = {
    Text = "Sepertinya ini pertama kalinya aku memimpikan hal-hal dari masa lalu."
  },
  AvgDialog_44439_Content_12 = {
    Text = "Kamu memegangi kepalamu, kesadaranmu seolah ditarik oleh benang tak kasat mata, membawamu bangkit dari tempat tidur."
  },
  AvgDialog_44439_Content_13 = {
    Text = "Lalu kamu membuka jendela, dan melihat salju pertama di tahun baru."
  },
  AvgDialog_44439_Content_14 = {
    Text = "Uwaa, salju turun!!"
  },
  AvgDialog_44439_Content_15 = {
    Text = "Teriakan gembira anak-anak bergema di langit malam yang sunyi, diiringi derap langkah kaki yang riuh, anak-anak panti asuhan berkumpul bersama di lantai bawah."
  },
  AvgDialog_44439_Content_16 = {
    Text = "Saljunya banyak sekali, berkilauan, cantik sekali."
  },
  AvgDialog_44439_Content_17 = {
    Text = "Aigis ingin membuat boneka salju, yang seperti Beruang Bobby."
  },
  AvgDialog_44439_Content_18 = {
    Text = "Apa susahnya, biar aku yang——"
  },
  AvgDialog_44439_Content_19 = {
    Text = "Tadaa! Lihatlah mahakarya Tuan Besar ini!"
  },
  AvgDialog_44439_Content_2 = {
    Text = "Kau bermimpi yang sangat, sangat panjang."
  },
  AvgDialog_44439_Content_20 = {
    Text = "Umm…… sepertinya dia tidak terlalu mirip Beruang Bobby. Dia, dia……"
  },
  AvgDialog_44439_Content_21 = {
    Text = "Dia mirip anjing! Anjing pug!"
  },
  AvgDialog_44439_Content_22 = {
    Text = "<Big:Wahahahaha!>"
  },
  AvgDialog_44439_Content_23 = {
    Text = "O-omong kosong! Mana mirip anjing!"
  },
  AvgDialog_44439_Content_24 = {Text = "Cit cit!"},
  AvgDialog_44439_Content_25 = {
    Text = "Anak-anak berlarian sambil tertawa melewati lorong-lorong. Mason entah sejak kapan sudah terbangun, berdiri di sampingmu."
  },
  AvgDialog_44439_Content_26 = {
    Text = "Dia mengulurkan tangannya, menampung beberapa butir salju lembut di telapak tangannya."
  },
  AvgDialog_44439_Content_27 = {
    Text = "Butiran salju berbaring tenang di telapak tangannya, segera mencair menjadi air salju yang dingin, berkilauan dengan cahaya bintang keemasan."
  },
  AvgDialog_44439_Content_28 = {
    Text = "Eh, ini cahaya yang pernah kulihat waktu itu……"
  },
  AvgDialog_44439_Content_29 = {
    Text = "Cahaya bintang yang tak terhitung berterbangan keluar dari jendela lorong di sebelah kalian, bertemu di langit malam membentuk sungai cahaya keemasan."
  },
  AvgDialog_44439_Content_3 = {
    Text = "Dalam mimpi, langit seperti pemakaman yang sudut-sudutnya telah dirobek, dan zat-zat hitam itu mengalir masuk bagai tinta."
  },
  AvgDialog_44439_Content_30 = {
    Text = "Mereka mengalir dengan ringan, membentang hingga ke bulan dan pegunungan yang jauh."
  },
  AvgDialog_44439_Content_31 = {
    Text = "Mason perlahan menutup matanya."
  },
  AvgDialog_44439_Content_32 = {
    Text = "Ini aura Nona Badut itu. Dia telah meninggalkan kita."
  },
  AvgDialog_44439_Content_33 = {
    Text = "Tapi aku tidak merasakan kesedihan… Dia sepertinya pergi dengan sukarela, seperti pulang ke rumah."
  },
  AvgDialog_44439_Content_34 = {
    Text = "Pulang ke rumah…"
  },
  AvgDialog_44439_Content_35 = {
    Text = "Nona Mason, saya dengar kamu pergi bekerja di kota sejak usia muda. Apakah kamu masih merindukan rumahmu?"
  },
  AvgDialog_44439_Content_36 = {
    Text = "Mason memandang Jenkin yang sedang bergulat dengan si kecil Mac di lantai bawah, lalu tersenyum lembut."
  },
  AvgDialog_44439_Content_37 = {
    Text = "Ingatanku sangat buruk. Waktu kecil, suster di sekolah gereja bilang aku memang bukan bahan untuk belajar."
  },
  AvgDialog_44439_Content_38 = {
    Text = "Orang tua, kampung halaman... aku sudah tidak terlalu ingat, dan juga tidak mau mengingatnya. Memori seharusnya digunakan untuk menyimpan kebahagiaan."
  },
  AvgDialog_44439_Content_39 = {
    Text = "Dalam buku dongeng yang pernah kubaca, hanya tempat yang penuh kebahagiaan dan kehangatan yang bisa disebut rumah. Aku ingin menjadi rumah bagi Jenkin dan Cokelat."
  },
  AvgDialog_44439_Content_4 = {
    Text = "Kau terbaring telentang di bawah celah itu, mendekatkan jantungmu ke bumi sedekat dan sedalam mungkin."
  },
  AvgDialog_44439_Content_40 = {
    Text = "Ternyata begitu. Nona Mason, kamu jauh lebih kuat daripada yang kubayangkan."
  },
  AvgDialog_44439_Content_41 = {
    Text = "Saat pertama kali bertemu di museum lilin, kamu tidak seperti ini."
  },
  AvgDialog_44439_Content_42 = {
    Text = "<Gray:Sepertinya \"Terapi Stabilisasi Endorfin Dosis Super\" dari Nona Winkel ada manfaatnya juga ya.>"
  },
  AvgDialog_44439_Content_43 = {
    Text = "Mason tertawa, matanya membentuk lengkungan."
  },
  AvgDialog_44439_Content_44 = {
    Text = "Semua orang berusaha sekuat tenaga membantuku, mana mungkin aku tidak berubah sama sekali?"
  },
  AvgDialog_44439_Content_45 = {
    Text = "Aku juga berharap bisa membantu semua orang."
  },
  AvgDialog_44439_Content_46 = {
    Text = "Kamu meregangkan tubuh, memandang tanpa tujuan ke arah pemukiman penduduk yang gelap gulita di bawah."
  },
  AvgDialog_44439_Content_47 = {
    Text = "Entah apakah ini ilusi atau bukan, sepertinya kamu melihat \"Bayangan 24\"berdiri di ujung gang gelap, memandang sungai cahaya di langit bersama kalian."
  },
  AvgDialog_44439_Content_49 = {
    Text = "Akan kuberitahu sebuah rahasia: setiap kepribadian adalah rumput apung yang mengembara di dunia, kembali menjadi utuh adalah harapan bersama kita."
  },
  AvgDialog_44439_Content_5 = {
    Text = "Dung dung. Dung dung."
  },
  AvgDialog_44439_Content_50 = {
    Text = "Tertawa bersama, menangis bersama, merasakan cinta dan kepercayaan dari Jenkin bersama…"
  },
  AvgDialog_44439_Content_51 = {
    Text = "Hanyalah angan-angan yang menyedihkan saja."
  },
  AvgDialog_44439_Content_52 = {
    Text = "Angin bertiup lembut, kepingan salju menari di udara bagai kapas yang halus, jatuh ke segala arah tanpa tujuan."
  },
  AvgDialog_44439_Content_53 = {
    Text = "Cahaya bintang perlahan memudar, kesadaranmu seolah ikut melayang semakin jauh bersama mereka."
  },
  AvgDialog_44439_Content_54 = {
    Text = "Entah seperti apa Alam Cermin berikutnya yang menantimu?"
  },
  AvgDialog_44439_Content_55 = {
    Text = "Tanpa disadari, kau justru merasa sedikit penasaran."
  },
  AvgDialog_44439_Content_56 = {
    Text = "<Yellow:Catatan Investigasi Domain Buatan III>\n\n■Nomor Domain: M-C06\n■Waktu Jatuh: 24 Desember Tahun 315 Aluvi\n■Lokasi Jatuh: Rumah Miskin Lilian"
  },
  AvgDialog_44439_Content_57 = {
    Text = [[
<Yellow:Hasil Penyelidikan>

Aku melihat salju, serta bintang emas yang menari di antara salju.
Entah kenapa, mereka selalu mengingatkanku pada masa lalu. Kabut naik, cahaya jatuh, tawa bergantian memudar.
Ini adalah malam musim dingin yang tenang.

<Yellow:Selamat Tahun Baru.>

P.S.: Kue kecil dengan gula buatan Miss Sarah sangat enak.]]
  },
  AvgDialog_44439_Content_6 = {
    Text = "Kau memejamkan mata, merasakan getaran yang datang dari kedalaman mantel bumi. Itu adalah ritme yang melankolis dan kuno, yang membuatmu teringat akan kampung halamanmu."
  },
  AvgDialog_44439_Content_7 = {
    Text = "Entah berapa lama telah berlalu, kamu mendengar tawa yang samar-samar. Seseorang menggenggam tanganmu. Kamu membalas genggaman itu dan merasakan kehangatan yang sudah lama tidak dirasakan."
  },
  AvgDialog_44439_Content_8 = {
    Text = "Ibu. Sebelum sempat berseru, air mata sudah mengalir lebih dulu."
  },
  AvgDialog_44439_Content_9 = {
    Text = "Kalian sudah terpisah terlalu lama."
  },
  AvgDialog_44440_Content_1 = {
    Text = "Tidak bisa, orangnya terlalu banyak... Kalau terus begini hanya akan semakin buruk..."
  },
  AvgDialog_44440_Content_10 = {
    Text = "Tidak, Tuan Goliya——!!"
  },
  AvgDialog_44440_Content_11 = {
    Text = "Segalanya di depan mata seolah ditekan tombol jeda."
  },
  AvgDialog_44440_Content_12 = {
    Text = "Insting tubuh ini melampaui kendalimu. Ia menerjang maju tanpa memedulikan apa pun, berdiri di depan Goliath."
  },
  AvgDialog_44440_Content_13 = {Text = "Ukh——"},
  AvgDialog_44440_Content_16 = {
    Text = "Mata pisau mengiris tenggorokanmu, kau gemetar menutupi luka yang terus mengucurkan darah, pikiranmu kacau balau."
  },
  AvgDialog_44440_Content_17 = {
    Text = "Kau sudah gila ya, datang menghalangi untuk apa?!"
  },
  AvgDialog_44440_Content_18 = {
    Text = "Aku tidak tahu… tubuhku… bergerak sendiri…"
  },
  AvgDialog_44440_Content_19 = {
    Text = "Maaf, Tuan Goliath…"
  },
  AvgDialog_44440_Content_2 = {
    Text = "Aku... masih bisa... terus membunuh!"
  },
  AvgDialog_44440_Content_22 = {
    Text = "Anak panah berlumur racun mematikan membelah udara, menancap di bahu Goliath. Ia tak mampu menahan tubuhnya dan terjatuh ke arahmu."
  },
  AvgDialog_44440_Content_23 = {
    Text = "Goliath… sang raksasa Goliath, akhirnya tumbang!"
  },
  AvgDialog_44440_Content_24 = {
    Text = "Kepalanya milikku, jangan ada yang berani merebutnya dariku!!!"
  },
  AvgDialog_44440_Content_25 = {
    Text = "Permukaan laut mengeluarkan gemuruh murka yang teredam, sang raksasa menutupi terik matahari di hadapanmu, lalu runtuh dengan dahsyat."
  },
  AvgDialog_44440_Content_26 = {
    Text = "Darah kalian berdua menyatu, mewarnai lautan biru menjadi merah darah."
  },
  AvgDialog_44440_Content_27 = {
    Text = "Di telingamu terdengar suara angin, deburan ombak, serta sorak-sorai dan suara perkelahian dari kejauhan. Setelah ini, yang menanti kalian hanyalah pembantaian dan penghinaan tanpa akhir."
  },
  AvgDialog_44440_Content_28 = {
    Text = "Air laut yang asin dan amis menjilati luka di lehermu, rasa sakitnya membuatmu terus-menerus meringis menghirup napas."
  },
  AvgDialog_44440_Content_29 = {
    Text = "Keadaan Goliath tak jauh lebih baik darimu."
  },
  AvgDialog_44440_Content_3 = {
    Text = "Suara terompet berat terus bergema di atas permukaan laut. Di bawah iming-iming hadiah besar, para prajurit terus berdatangan bergabung dalam permainan perburuan ini."
  },
  AvgDialog_44440_Content_30 = {
    Text = "Melihatmu dalam kondisi berantakan seperti ini, dia menyeringai padamu dengan senyuman yang penuh niat jahat."
  },
  AvgDialog_44440_Content_32 = {Text = "...sampah."},
  AvgDialog_44440_Content_4 = {
    Text = "Goliya sudah hampir kehabisan tenaga. Ia kembali mengayunkan bilah raksasa di tangannya, namun kali ini, gerakannya yang lambat memberi celah bagi musuh untuk menyerang."
  },
  AvgDialog_44440_Content_6 = {
    Text = "Goliath berlutut di tanah, puncak luka memperlihatkan tulang putih yang mengerikan, darah mengalir seperti aliran yang tidak akan pernah kering."
  },
  AvgDialog_44440_Content_8 = {
    Text = "Sekarang saatnya, habisi dia dalam satu serangan!!"
  },
  AvgDialog_44440_Content_9 = {
    Text = "Para prajurit yang mengepung menyerbu maju bagaikan kawanan hiu yang haus darah."
  },
  AvgDialog_44441_Content_1 = {
    Text = "Kisah Sang Raksasa"
  },
  AvgDialog_44441_Content_10 = {
    Text = "Goliath menyeringai dengan nada meremehkan dari tenggorokannya."
  },
  AvgDialog_44441_Content_11 = {
    Text = "Penyihir apaan? Jangan bilang kau benar-benar percaya omong kosong mereka."
  },
  AvgDialog_44441_Content_12 = {
    Text = "Hanya orang bodoh yang mempercayakan nyawanya pada orang lain."
  },
  AvgDialog_44441_Content_13 = {
    Text = "<Gray:Penyihir…>"
  },
  AvgDialog_44441_Content_14 = {
    Text = "Berdasarkan arsip Kebangkitan Goliath, \"penyihir\" yang dimaksud sudah pasti adalah Miriam."
  },
  AvgDialog_44441_Content_15 = {
    Text = "Meskipun perkembangan selanjutnya tidak sesuai harapan, Miriam memang telah menyelamatkan nyawa Goliath."
  },
  AvgDialog_44441_Content_16 = {
    Text = "Tuan, Anda terluka parah, tampaknya tidak ada cara lain untuk saat ini——"
  },
  AvgDialog_44441_Content_17 = {Text = "Bumm!!"},
  AvgDialog_44441_Content_18 = {
    Text = "Disertai hentakan yang kuat, tenggorokanmu yang rapuh dicekik dengan keras. Kakimu terangkat dari tanah saat kau diangkat ke hadapan sang raksasa."
  },
  AvgDialog_44441_Content_19 = {
    Text = "Aku hanya akan mengatakannya sekali: jangan tatap aku dengan pandangan seperti itu, dan jangan bicara padaku dengan nada seperti itu."
  },
  AvgDialog_44441_Content_2 = {
    Text = "Sinar matahari memanggang permukaan laut, seolah-olah ingin menghabiskan semua hidup dalam panas tak berujung ini."
  },
  AvgDialog_44441_Content_20 = {
    Text = "Yang paling tidak dibutuhkan oleh Goliath ini adalah belas kasihan dari yang lemah."
  },
  AvgDialog_44441_Content_21 = {
    Text = "Nada bicara Goliath datar, ekspresinya biasa saja, seolah hanya sedang membicarakan cuaca denganmu."
  },
  AvgDialog_44441_Content_22 = {
    Text = "Tapi kalian begitu dekat, cukup dekat hingga kau bisa melihat dengan jelas lingkar matanya yang memerah karena rasa sakit dan ketidakrelaan."
  },
  AvgDialog_44441_Content_23 = {
    Text = "Pada saat ini, ia seolah telah menanggalkan segala kemuliaan sebagai penguasa lautan, menjadi ikan yang tersesat di samudra tak berujung ini—sama sepertimu."
  },
  AvgDialog_44441_Content_24 = {
    Text = "Maaf……eh, Tuan……"
  },
  AvgDialog_44441_Content_25 = {
    Text = "<Shake:Wuuu——>"
  },
  AvgDialog_44441_Content_26 = {
    Text = "Suara tanduk yang rendah terdengar samar dari kejauhan."
  },
  AvgDialog_44441_Content_27 = {
    Text = "Lehermu tiba-tiba terasa ringan. Goliath melepaskan tangannya dan menatap ke arah suara tanduk itu berasal."
  },
  AvgDialog_44441_Content_28 = {
    Text = "<Gray:Uhuk uhuk……hah, selamat……>"
  },
  AvgDialog_44441_Content_29 = {
    Text = "Menarik……mereka khawatir aku mati kurang cepat, jadi sengaja datang beramai-ramai untuk mengantarku ke liang kubur?"
  },
  AvgDialog_44441_Content_3 = {
    Text = "Papan kayu yang kau dan Goliath pegangan menjadi satu-satunya pulau di tengah lautan. Menatap matahari yang terik di atas kepala, kau kembali merasakan gelombang pusing yang datang silih berganti."
  },
  AvgDialog_44441_Content_30 = {
    Text = "Tak lama kemudian, armada kapal yang megah telah mengepung kalian di tengah-tengah. Papan kayu yang terombang-ambing menjadi satu-satunya pulau terpencil di perairan ini."
  },
  AvgDialog_44441_Content_31 = {
    Text = "Kalian sudah terjebak dalam kepungan."
  },
  AvgDialog_44441_Content_32 = {
    Text = "Izinkan aku memperkenalkan dengan meriah, pemimpin paling perkasa dalam sejarah Filistin! Raksasa berkekuatan besar dengan kehendak yang tak terpatahkan! Pahlawan suku yang mengguncang empat penjuru lautan dan memandang rendah segalanya——"
  },
  AvgDialog_44441_Content_33 = {
    Text = "<BigShake:Tuan Goliath!>"
  },
  AvgDialog_44441_Content_34 = {
    Text = "Cahaya matahari yang terpantul dari permukaan laut terlalu menyilaukan. Kamu hanya bisa melihat sekilas siluet hitam berdiri di haluan kapal, memandang kalian dari atas."
  },
  AvgDialog_44441_Content_35 = {
    Text = "Saudara-saudara yang baru bergabung mungkin belum tahu, tuan yang terhormat ini terluka parah dalam sebuah duel dan nyaris tertawan, menyebabkan seluruh suku kita jatuh ke dalam kebinasaan yang belum pernah terjadi sebelumnya!"
  },
  AvgDialog_44441_Content_36 = {
    Text = "Kehancuran yang begitu dekat telah menelan sebagian besar anggota suku! Terpujilah engkau! Tuan Goliath yang paling kuhormati!"
  },
  AvgDialog_44441_Content_37 = {
    Text = "Heh heh……prestasi sebesar ini mana berani aku nikmati sendiri, Igrun?"
  },
  AvgDialog_44441_Content_38 = {
    Text = "Dulu siapa yang bersembunyi di belakangku dan tak berani mengerahkan pasukan, dan siapa yang pertama kali membuang senjata sambil menangis meraung berlari pulang?"
  },
  AvgDialog_44441_Content_39 = {Text = "Kau……!"},
  AvgDialog_44441_Content_4 = {
    Text = "<Shake:Maaf, aku kurang enak badan… biarkan aku tidur sebentar…>"
  },
  AvgDialog_44441_Content_40 = {
    Text = "Wajah Igrun memerah menahan amarah, bola matanya yang keruh bergetar tak henti, dan akhirnya tertuju padamu."
  },
  AvgDialog_44441_Content_41 = {
    Text = "Oh, Tuan Pemimpin yang agung, meskipun sukunya sudah bubar, tetap masih memiliki seorang……pengikut yang sangat manis."
  },
  AvgDialog_44441_Content_42 = {
    Text = "Aib bangsa Filistin——sampah yang bahkan tak sanggup menerima satu pukulan pun di dalam suku, tapi ingin mengikutimu menjadi pejuang……"
  },
  AvgDialog_44441_Content_43 = {
    Text = "Hahahaha……!!"
  },
  AvgDialog_44441_Content_44 = {
    Text = "Goliath mendongak, menatapmu dengan terkejut dari balik gelak tawa kerumunan."
  },
  AvgDialog_44441_Content_45 = {
    Text = "Nak kecil, kau secara sukarela mengikutiku kemari?"
  },
  AvgDialog_44441_Content_46 = {
    Text = "<Gray:Ehm... kalau tidak salah ingat, memang begitu...>"
  },
  AvgDialog_44441_Content_47 = {
    Text = "Mengharukan, bukan? Aku hanya asal menyebut soal penyihir, dan si bodoh kecil ini langsung mempercayainya, dengan penuh harap ingin ikut denganmu kemari..."
  },
  AvgDialog_44441_Content_48 = {
    Text = "Ditahan pun tak bisa, haha——"
  },
  AvgDialog_44441_Content_49 = {Text = "BRASSHH!!"},
  AvgDialog_44441_Content_5 = {Text = "BRAK!"},
  AvgDialog_44441_Content_50 = {
    Text = "Tawa terhenti seketika. Angin ganas meraung menerjang, dan sepotong kaki yang terputus seketika menggelinding di hadapan semua orang."
  },
  AvgDialog_44441_Content_51 = {
    Text = "Aaaaah... kakiku, KAKIKU!!"
  },
  AvgDialog_44441_Content_52 = {
    Text = "Sang penguasa lautan masa lalu berdiri tegak bagai gunung di hadapan Igren, memancarkan aura yang membuat siapa pun gemetar ketakutan."
  },
  AvgDialog_44441_Content_53 = {
    Text = "Sejak tadi, ada seekor lalat yang terus terbang bolak-balik di telingaku..."
  },
  AvgDialog_44441_Content_54 = {
    Text = "Goliath dengan santai mengusap noda darah di mata pisaunya, lalu mendongak dan tersenyum dingin ke arah Igren."
  },
  AvgDialog_44441_Content_55 = {
    Text = "Igren, tadi aku bertanya padamu, hah?"
  },
  AvgDialog_44441_Content_6 = {
    Text = "Sebuah jubah yang bercampur keringat dan bau amis darah menutupi kepalamu, baunya membuatmu langsung terlonjak bangun."
  },
  AvgDialog_44441_Content_7 = {
    Text = "Uhuk uhuk……Hoek!"
  },
  AvgDialog_44441_Content_8 = {
    Text = "Kau terkena sengatan matahari. Tutupi kepalamu dengan ini untuk menghalangi matahari, jangan dilepas."
  },
  AvgDialog_44441_Content_9 = {
    Text = "Terima kasih, Tuan... Ke mana kita harus pergi selanjutnya? Mencari penyihir?"
  },
  AvgDialog_44442_Content_1 = {
    Text = "Uuh——!!"
  },
  AvgDialog_44442_Content_10 = {
    Text = "Aku, prajurit Igren, bersumpah dengan nyawaku—siapa pun yang bisa memenggal kepala orang ini, kekayaan, tanah, dan wanitaku akan kuserahkan kepadanya!"
  },
  AvgDialog_44442_Content_11 = {
    Text = "Di bawah iming-iming hadiah besar, pasti ada yang berani maju. Para prajurit mengeluarkan sorak penuh semangat, senjata-senjata beradu, menggemakan dentingan logam yang menggugah."
  },
  AvgDialog_44442_Content_12 = {
    Text = "Benar, ta-takut apa, kita kan banyak orang!"
  },
  AvgDialog_44442_Content_13 = {
    Text = "Potong dulu tangan yang memegang pedangnya!"
  },
  AvgDialog_44442_Content_14 = {
    Text = "Para prajurit yang semula gemetar kini berteriak murka, menyerbu maju bagaikan kawanan belalang yang haus darah."
  },
  AvgDialog_44442_Content_15 = {
    Text = "Hehe... wahai kaumku yang tercinta. Aku pernah mengajari kalian cara bertarung, cara membunuh, cara bertahan hidup."
  },
  AvgDialog_44442_Content_16 = {
    Text = "Namun, aku tak pernah mengajari kalian cara menyelamatkan diri saat menghadapi musuh yang jauh lebih kuat."
  },
  AvgDialog_44442_Content_17 = {
    Text = "Goliya menjilat darah di sudut bibirnya, memperlihatkan taringnya yang tajam."
  },
  AvgDialog_44442_Content_18 = {
    Text = "...Karena kalian sudah tidak punya jalan untuk lari."
  },
  AvgDialog_44442_Content_19 = {
    Text = "Setelah berkata demikian, ia mencekik tenggorokan dua orang dengan santai, mengangkat kepala mereka dan menghantamkannya dengan keras—"
  },
  AvgDialog_44442_Content_2 = {
    Text = "Tebasan pedang besar yang membabi buta menghancurkan kapal hingga berkeping-keping. Igren menyeret satu-satunya kaki yang tersisa dan mundur dengan panik ke sudut kapal."
  },
  AvgDialog_44442_Content_20 = {Text = "BRASSHH!!"},
  AvgDialog_44442_Content_21 = {
    Text = "Campuran cairan putih kekuningan bercampur darah yang hancur menyembur keluar. Goliya tertawa terbahak-bahak, kobaran nafsu membunuh menyala di kedua pupil matanya."
  },
  AvgDialog_44442_Content_22 = {
    Text = "Hahaha! Kudengar ada yang ingin mengambil kepala ini?"
  },
  AvgDialog_44442_Content_23 = {
    Text = "Berani? Ayo @1 ambil!"
  },
  AvgDialog_44442_Content_3 = {
    Text = "<Shake:Bukankah kau terluka, bagaimana bisa...>"
  },
  AvgDialog_44442_Content_4 = {
    Text = "Maaf ya, untuk menghadapi anak buah rendahan sepertimu, aku sama sekali tidak perlu mengeluarkan seluruh kekuatanku."
  },
  AvgDialog_44442_Content_5 = {
    Text = "Goliath berdiri angkuh di haluan kapal, bilah raksasanya mengukir goresan melengkung di hadapannya, memisahkan para mantan saudara sebangsanya di luar garis itu."
  },
  AvgDialog_44442_Content_6 = {
    Text = "Ada lagi yang mau naik menemani aku bermain? Satu orang mana cukup untuk dibunuh?"
  },
  AvgDialog_44442_Content_7 = {
    Text = "Glen memandang sekeliling dengan panik."
  },
  AvgDialog_44442_Content_8 = {
    Text = "Tertekan oleh tekanan mengerikan sang raksasa, para prajurit menggigil bagai serigala muda, tak seorang pun berani melangkahi garis lengkung di hadapan mereka, seolah itu adalah tanah terlarang yang tak boleh diinjak."
  },
  AvgDialog_44442_Content_9 = {
    Text = "Dasar sampah semua! Dia sudah terluka separah ini, sudah bukan lagi penguasa lautan yang dulu."
  },
  AvgDialog_44811_Content_1 = {
    Text = "Es yang menyala"
  },
  AvgDialog_44811_Content_10 = {
    Text = "Mogok main? Pemimpin yang setengah-setengah?"
  },
  AvgDialog_44811_Content_11 = {
    Text = "Tubuh masih menolak untuk terbuka kepada jiwamu, memori tersembunyi di suatu sudut yang tak diketahui."
  },
  AvgDialog_44811_Content_12 = {
    Text = "Dengan rasa putus asa, kamu menerobos kerumunan penari yang berisik seperti kawanan burung, lalu mengulurkan tanganmu kepada gadis yang sedang berbalik untuk pergi ——"
  },
  AvgDialog_44811_Content_13 = {
    Text = "Liz, kamu mau ke mana?"
  },
  AvgDialog_44811_Content_14 = {
    Text = "Benar, Liz."
  },
  AvgDialog_44811_Content_15 = {
    Text = "Penari berbaju hitam yang menyelamatkanmu dari kesulitan dan juga menyelamatkan panggung ini tidak lain adalah Pembangun Liz yang sudah kamu kenal."
  },
  AvgDialog_44811_Content_16 = {
    Text = "Tak diragukan lagi, mimpi ini milik Liz, gadis yang selalu mengurung diri di ruang dansa Mythag."
  },
  AvgDialog_44811_Content_18 = {
    Text = "Liz menoleh ke arahmu, otot di sudut bibirnya berkedut dua kali, tampaknya ingin mengatakan sesuatu——"
  },
  AvgDialog_44811_Content_19 = {
    Text = "Elizabeth, Elizabeth-ku yang baik. Aku tahu kau tak bisa melepaskan tarian ini —"
  },
  AvgDialog_44811_Content_2 = {
    Text = "<Small:Hu... Hu... Akhirnya selesai.>"
  },
  AvgDialog_44811_Content_20 = {
    Text = "Manajer kelompok tari yang berotot di sekujur tubuhnya tersenyum lebar, dengan sikap sangat merendah mendekati Liz."
  },
  AvgDialog_44811_Content_21 = {
    Text = "Liz mundur dua langkah, menghindari tangan manajer yang terulur ke arahnya, seperti kupu-kupu yang anggun dan tanpa meninggalkan jejak."
  },
  AvgDialog_44811_Content_22 = {
    Text = "Tidak ada yang berani menghentikannya, mereka hanya bisa melihatnya menghilang di lorong belakang. Senyuman manajer kelompok tari membeku di wajahnya, dan setelah beberapa saat, dia mendengus dengan nada meremehkan."
  },
  AvgDialog_44811_Content_23 = {
    Text = "Berlagak suci, ya? Kalau bukan karena apresiasi Tuan Jue, aku sudah lama menghajar gadis rendahan ini…"
  },
  AvgDialog_44811_Content_24 = {
    Text = "Apa yang kalian lihat-lihat! Cepat siapkan tarian berikutnya! Jika sampai para tuan dan nyonya tidak senang, kalian sendiri yang akan menanggung akibatnya!"
  },
  AvgDialog_44811_Content_25 = {
    Text = "Gadis-gadis itu gemetar sejenak, tetapi pada akhirnya tidak ada yang berani menantang manajer. Mereka semua patuh bangkit dari panggung dan kembali membentuk formasi tarian."
  },
  AvgDialog_44811_Content_26 = {
    Text = "Dan kamu, siapa namamu tadi... ah, tidak penting."
  },
  AvgDialog_44811_Content_27 = {
    Text = "Manajer menunjuk secara acak, lalu mengeluarkan seorang penari dengan wajah yang cantik dari barisan. Gadis yang ditunjuk tampak gembira, dengan senyum lebar ia segera maju ke depan."
  },
  AvgDialog_44811_Content_28 = {
    Text = "Manajer, nama saya Caroline…"
  },
  AvgDialog_44811_Content_29 = {
    Text = "Aku tidak peduli apakah kamu Caroline atau Carol, kamu yang memimpin untuk membungkuk memberi penghormatan."
  },
  AvgDialog_44811_Content_3 = {
    Text = "Permainan musik semakin melemah, Tubuhmu akhirnya mengikuti para penari lainnya untuk membentuk pose statis, siap menyambut tepuk tangan yang memenuhi ruangan."
  },
  AvgDialog_44811_Content_30 = {
    Text = "Di usiamu sekarang, tidak lama lagi kamu akan dikeluarkan dari kelompok. Ini adalah kesempatan terakhirmu untuk menemukan jalan keluar bagi dirimu sendiri."
  },
  AvgDialog_44811_Content_31 = {
    Text = "Terima kasih, Manajer! Terima kasih banyak!"
  },
  AvgDialog_44811_Content_32 = {
    Text = "Manajer terus-menerus mengucapkan kata-kata yang merendahkan, namun penari itu menundukkan kepala dan menyerahkan harga dirinya yang telah diinjak-injak kepada manajer. Adegan ini membuat orang merasa sangat tidak nyaman."
  },
  AvgDialog_44811_Content_33 = {
    Text = "...Kamu masuk ke dalam mimpi bukan untuk menjadi bintang tari."
  },
  AvgDialog_44811_Content_34 = {
    Text = "Saat gadis itu sedang berterima kasih dengan penuh semangat kepada manajer, kamu sedikit membungkukkan badan, mencoba untuk menyembunyikan diri di antara para gadis."
  },
  AvgDialog_44811_Content_35 = {
    Text = "Lorong belakang kepergian Liz sudah sangat dekat, namun sebuah telapak tangan besar mencengkeram pergelangan tangan tubuh yang kurus ini. Kekuatan yang sulit ditolak menyeretmu masuk ke belakang panggung."
  },
  AvgDialog_44811_Content_36 = {
    Text = "Sakit, sakit... Manajer, kamu——"
  },
  AvgDialog_44811_Content_37 = {
    Text = "——Plak!"
  },
  AvgDialog_44811_Content_38 = {
    Text = "Dengungan bergema di dalam saluran telinga, sisi wajah membengkak dan memerah dengan kecepatan yang terlihat jelas oleh mata telanjang, sensasi nyeri tajam hampir menembus keluar dari bawah kulit."
  },
  AvgDialog_44811_Content_39 = {
    Text = "(Serang dia)"
  },
  AvgDialog_44811_Content_4 = {
    Text = "Namun, yang terdengar dari bawah panggung hanyalah bisikan rendah yang saling bersahutan."
  },
  AvgDialog_44811_Content_40 = {
    Text = "Para penari, demi menjaga bentuk tubuh mereka, menjadi vegetarian sepanjang tahun. Setelah meninggalkan panggung, tubuh ini bisa dikatakan lemah tanpa kekuatan untuk melakukan tugas berat."
  },
  AvgDialog_44811_Content_41 = {
    Text = "Tetapi kamu berbeda, Roh-mu telah melewati pelatihan paling keras di dunia. Bahkan saat \"masuk mimpi\", kamu masih bisa menggunakan Kekuatan Pembangun untuk menjatuhkan orang ini ——"
  },
  AvgDialog_44811_Content_42 = {
    Text = "Meskipun kepalan tangan sudah terkepal erat, kamu masih menahan amarah yang hampir meledak."
  },
  AvgDialog_44811_Content_43 = {
    Text = "(Menahan kemarahan)"
  },
  AvgDialog_44811_Content_44 = {
    Text = "...Ya sudah, lagipula ini bukan tubuhku sendiri."
  },
  AvgDialog_44811_Content_45 = {
    Text = "\"Mimpi\"bukanlah tentang dirimu. Jika sembarangan melakukan serangan terhadap karakter dalam mimpi, hanya akan membuatmu semakin jauh dari pemilik mimpi, bahkan mungkin membuatmu sulit untuk keluar dari \"Mimpi\" dalam waktu yang lama."
  },
  AvgDialog_44811_Content_46 = {
    Text = "Apa kamu tahu apa yang sudah kamu lakukan hari ini! Aku menjadikanmu kepala baru, dan kamu membalasnya dengan sikap bodoh seperti ini? Membuat kekacauan di panggung pratinjau yang penting?"
  },
  AvgDialog_44811_Content_47 = {
    Text = "Apa kamu tahu betapa memalukannya dirimu! Sebagai penari utama, kamu bahkan lupa gerakan tariannya, hampir saja merusak reputasi kelompok tari Adli kita!"
  },
  AvgDialog_44811_Content_48 = {
    Text = "Ketua... Jika aku menjadi ketua, maka Liz dia.."
  },
  AvgDialog_44811_Content_49 = {
    Text = "Liz? Hmph, kalau bukan karena dia berhenti tampil, bagaimana mungkin kursi pertama ini bisa jatuh ke tanganmu."
  },
  AvgDialog_44811_Content_5 = {
    Text = "…harga…?"
  },
  AvgDialog_44811_Content_50 = {
    Text = "Mogok pentas... artinya, Liz adalah pemain utama yang seharusnya, tapi kenapa dia..."
  },
  AvgDialog_44811_Content_51 = {
    Text = "Dari mana semua pertanyaan ini! Kembali ke kamarmu!"
  },
  AvgDialog_44811_Content_52 = {
    Text = "Manajer yang marah tidak lagi menjawab pertanyaanmu. Dia menarik tanganmu dan mendorongmu ke dalam sebuah ruangan sempit yang redup."
  },
  AvgDialog_44811_Content_53 = {
    Text = "Manajer dengan geram membanting pintu, lalu berteriak padamu dari balik pintu."
  },
  AvgDialog_44811_Content_54 = {
    Text = "Sebaiknya kau berdoa agar mengingat langkah tari Elizabeth, jika tidak, bersiaplah untuk dijual ke Rumah Kesenangan!"
  },
  AvgDialog_44811_Content_55 = {
    Text = "Apa, apa itu rumah?"
  },
  AvgDialog_44811_Content_56 = {
    Text = "——Klik."
  },
  AvgDialog_44811_Content_57 = {
    Text = "Setelah suara dingin kunci terkunci, kamu tahu bahwa tidak akan ada jawaban lagi — manajer kelompok tari telah mengunci kamu di dalam ruangan."
  },
  AvgDialog_44811_Content_58 = {
    Text = "Manusia tua yang licik dan culas! Sikapmu sangat buruk, aku mengutukmu duduk di toilet sepanjang malam ini!"
  },
  AvgDialog_44811_Content_59 = {
    Text = "Kamu menendang pintu dengan penuh kekesalan. Kayu tua yang tebal itu tetap diam, tersangkut di bingkai pintu, menahan protes kecilmu yang tak berarti."
  },
  AvgDialog_44811_Content_6 = {
    Text = "Apa yang mendesak! Lagipula… pertunjukan… lelang…"
  },
  AvgDialog_44811_Content_60 = {Text = "Ugh——!"},
  AvgDialog_44811_Content_61 = {
    Text = "Kamu terlalu mengandalkan perlindungan yang bisa diberikan oleh sepatu balet. Rasa sakit menusuk datang dari jempol kakimu, seolah-olah kuku jari kakimu terbalik akibat tendangan ini."
  },
  AvgDialog_44811_Content_62 = {
    Text = "Kamu tak bisa menahan diri untuk mengeluarkan erangan kesakitan, lalu terjatuh ke belakang di atas tempat tidur. Dengan lutut ditekuk, kamu memeluk kakimu dan berguling dua kali."
  },
  AvgDialog_44811_Content_63 = {
    Text = "Seseorang mengetuk jendela."
  },
  AvgDialog_44811_Content_64 = {
    Text = "Kamu baru saja masuk ke dalam ruangan, belum sempat mengunci jendela. Seseorang langsung mendorong jendela terbuka dan dengan lincah melompat masuk."
  },
  AvgDialog_44811_Content_65 = {
    Text = "Biasanya terlihat begitu agresif, tapi saat benar-benar memaki, mengapa terdengar begitu lemah?"
  },
  AvgDialog_44811_Content_66 = {
    Text = "Dia berdiri di samping tempat tidur, dengan tangan di belakang punggung, membungkuk untuk menatapmu dari atas. Rambut panjangnya yang kelabu jatuh melewati bahunya dan menyentuh wajahmu."
  },
  AvgDialog_44811_Content_67 = {Text = "Liz——!"},
  AvgDialog_44811_Content_68 = {
    Text = "Ssst, lebih pelan sedikit. Asrama dan tribun penonton hanya dipisahkan oleh satu dinding. Saat musik berhenti, orang-orang di luar mungkin bisa mendengar pembicaraan kita."
  },
  AvgDialog_44811_Content_69 = {
    Text = "Liz berkata sambil menempelkan sebuah bungkusan kain yang mengeluarkan hawa dingin ke wajahmu."
  },
  AvgDialog_44811_Content_7 = {
    Text = "Sebelum kamu bisa mendengar dengan jelas percakapan para tamu, tirai perlahan turun, dan kain tebal itu memisahkan panggung dan penonton menjadi dua dunia yang berbeda."
  },
  AvgDialog_44811_Content_70 = {
    Text = "Sss—sangat dingin!"
  },
  AvgDialog_44811_Content_71 = {
    Text = "Barusan di sini kena pukul, kan?"
  },
  AvgDialog_44811_Content_72 = {
    Text = "Liz duduk di tempat tidur, menggulirkan kantong kain di wajahmu yang memerah dan bengkak. Dingin dan rasa sakit membuatmu tidak bisa menahan diri untuk tidak menampakkan ekspresi meringis."
  },
  AvgDialog_44811_Content_73 = {
    Text = "Balok es... dari mana kamu mendapatkannya?"
  },
  AvgDialog_44811_Content_74 = {
    Text = "Diambil dari lemari es pribadi babi tua yang gemuk itu."
  },
  AvgDialog_44811_Content_75 = {
    Text = "Babi tua? Apakah manajer? ——Aduh, pelan-pelan, pelan-pelan."
  },
  AvgDialog_44811_Content_76 = {
    Text = "Sekarang musim panas, es sangat berharga. Bagaimana mungkin manajer mau memberikannya padamu?"
  },
  AvgDialog_44811_Content_77 = {
    Text = "Tangan Liz tidak menunjukkan sedikit pun belas kasihan, malah menekan lebih kuat lagi——"
  },
  AvgDialog_44811_Content_78 = {
    Text = "Saya mengambilnya sendiri."
  },
  AvgDialog_44811_Content_79 = {
    Text = "Setelah Liz selesai berbicara, dia melepaskan tangannya, lalu menarikmu untuk berdiri dan membuatmu duduk di tepi tempat tidur. Dia menggali di dalam kantong es sederhana, mengeluarkan sepotong kecil es, dan memasukkannya ke dalam mulutmu."
  },
  AvgDialog_44811_Content_8 = {
    Text = "Terlalu indah, inilah akhir sebenarnya dari \"Swan Song\"... Jika dia tidak datang untuk menyelamatkan situasi, aku tidak berani membayangkan..."
  },
  AvgDialog_44811_Content_80 = {
    Text = "Rasa manis yang tidak biasa disertai rasa dingin menyebar di mulut, meredakan sensasi perih yang menyengat di sisi wajah. Kamu mengulum es dan menerima kompres dingin yang diberikan Liz, lalu meletakkannya di wajahmu."
  },
  AvgDialog_44811_Content_81 = {
    Text = "Apakah kamu hari ini menolak untuk menari di atas panggung karena sudah mengetahui sesuatu?"
  },
  AvgDialog_44811_Content_82 = {Text = "A-apa?"},
  AvgDialog_44811_Content_83 = {
    Text = "Ekspresinya menjadi sangat dingin dan serius. Dia juga duduk di sisi tempat tidur, mengulurkan kedua tangannya untuk memegang wajahmu, dengan tegas membuatmu menatapnya."
  },
  AvgDialog_44811_Content_84 = {
    Text = "Apakah kamu sudah menemukan \"kebenaran\" tentang kelompok tari? Apakah manajer dan agen lainnya memaksa kamu melakukan sesuatu —"
  },
  AvgDialog_44811_Content_85 = {
    Text = "Kecemasan dan kemarahan perlahan menyulut cahaya hijau di matanya, sementara telapak tangannya menjadi lebih dingin daripada kantung es."
  },
  AvgDialog_44811_Content_86 = {
    Text = "Kamu meletakkan kantong es, lalu menatapnya langsung."
  },
  AvgDialog_44811_Content_87 = {
    Text = "Bagaimana denganmu, Liz? Apa yang mereka paksa kamu lakukan?"
  },
  AvgDialog_44811_Content_88 = {
    Text = "Pandangan dengan gelisah berpindah dari dirimu, jatuh pada bintang-bintang di langit malam di luar jendela."
  },
  AvgDialog_44811_Content_89 = {
    Text = "Kota di malam hari kehilangan keriuhan di siang hari; hanya suara derit kereta yang melewati ubin masih bergema di jalan."
  },
  AvgDialog_44811_Content_9 = {
    Text = "Menyelamatkan situasi? Kau terlalu memujanya! Jika dia tidak menolak tampil, kita tidak akan sampai mengganti pemain utama dengan amatir dadakan..."
  },
  AvgDialog_44811_Content_90 = {
    Text = "Namun, suara tawa dan niat jahat itu benar-benar menembus dinding, datang dari atas panggung."
  },
  AvgDialog_44812_Content_1 = {
    Text = "Mimpi Tengah Musim Panas"
  },
  AvgDialog_44812_Content_10 = {
    Text = "Elizabeth Saleh... Saleh, Saleh, aku ingat ini adalah nama sebuah kelompok tari istana."
  },
  AvgDialog_44812_Content_100 = {
    Text = "Kamu menangis..."
  },
  AvgDialog_44812_Content_101 = {
    Text = "Liz tiba-tiba mendekatimu sedikit lebih dekat, memegang wajahmu dengan kedua tangannya, dan menghapus air mata yang jatuh dengan ibu jarinya."
  },
  AvgDialog_44812_Content_102 = {
    Text = "Ini berarti, kamu setuju denganku, kan?"
  },
  AvgDialog_44812_Content_103 = {
    Text = "Mata abu-hijau itu begitu dekat, kali ini kamu dengan jelas melihat pergulatan dan penderitaan di dalamnya. Dia menunggumu dengan penuh kerinduan, menanti jawaban pasti darimu."
  },
  AvgDialog_44812_Content_104 = {
    Text = "...Benar, kamu benar."
  },
  AvgDialog_44812_Content_105 = {
    Text = "Kamu mengingat kembali percakapan dengan Liz yang tercatat dalam arsip Universitas Mythag."
  },
  AvgDialog_44812_Content_106 = {
    Text = "Tarian... itu murni. Seorang penari sejati harus menggunakan gerakan tari untuk mengekspresikan hatinya, bukan tubuhnya."
  },
  AvgDialog_44812_Content_107 = {
    Text = "Mata Liz bersinar terang, kegembiraan terpancar tanpa terbendung."
  },
  AvgDialog_44812_Content_108 = {
    Text = "Kita memang sama, kau bisa mengerti aku..."
  },
  AvgDialog_44812_Content_109 = {
    Text = "Jadi, bisakah kamu membantu saya?"
  },
  AvgDialog_44812_Content_11 = {
    Text = "Ya, pendiri kelompok tari Salle adalah kakek saya."
  },
  AvgDialog_44812_Content_110 = {
    Text = "Membantumu? Liz, apa kamu punya rencana?"
  },
  AvgDialog_44812_Content_111 = {
    Text = "Aku tidak ingin dosa mereka terus menyebar... Aku akan mengakhiri dosa ini di tanganku."
  },
  AvgDialog_44812_Content_112 = {
    Text = "Baik. Aku akan membantu kamu. Apa yang perlu aku lakukan?"
  },
  AvgDialog_44812_Content_113 = {
    Text = "Liz menyentuh pipimu, nadanya melunak, dan matanya dipenuhi rasa sedih serta bersalah."
  },
  AvgDialog_44812_Content_114 = {
    Text = "Manajer sangat waspada terhadap saya, dia pasti tidak akan percaya bahwa saya akan naik ke atas panggung dengan sukarela…"
  },
  AvgDialog_44812_Content_115 = {
    Text = "Dia menggunakan dua jari untuk menjepit kain tas es sederhana. Es di dalamnya telah mencair lebih dari separuh, dan seluruh kain basah hingga bisa diperas airnya."
  },
  AvgDialog_44812_Content_116 = {
    Text = "Secara tiba-tiba, rasa kantuk yang tak terjelaskan langsung melanda, bahkan napas pun tersumbat di tenggorokan——"
  },
  AvgDialog_44812_Content_117 = {
    Text = "Liz... Elizabeth... apa yang telah kau lakukan padaku..."
  },
  AvgDialog_44812_Content_118 = {
    Text = "Kamu adalah kepala utama yang dia tetapkan, hanya jika kamu tidak hadir, dia akan terpaksa meminta bantuan dariku…"
  },
  AvgDialog_44812_Content_119 = {
    Text = "Liz menutupi mulut dan hidungmu dengan kain. Aroma manis yang familiar namun mengganggu perlahan menyebar di rongga hidung."
  },
  AvgDialog_44812_Content_12 = {
    Text = "Oh... begitu. Elizabeth, boleh aku memanggilmu Liz? Apakah kamu suka menari?"
  },
  AvgDialog_44812_Content_120 = {
    Text = "Di dalam es... obat..."
  },
  AvgDialog_44812_Content_121 = {
    Text = "... Benar-benar hebat kamu bisa menggigit balok es begitu lama, akhirnya mencair juga."
  },
  AvgDialog_44812_Content_122 = {
    Text = "Kamu tidak akan apa-apa, aku pernah melihat manajer menggunakan obat ini untuk membuat \"gadis-gadis yang tidak patuh\" menjadi penurut... Hanya tidur sebentar saja."
  },
  AvgDialog_44812_Content_123 = {
    Text = "Benar, setelah terbangun, semuanya akan berakhir…"
  },
  AvgDialog_44812_Content_13 = {
    Text = "Saya sangat menyukai tarian, Tuan. Hanya dengan satu kali pandang, saya sudah bisa mengingat gerakan-gerakannya, dan pada usia dua belas tahun, saya telah menciptakan sebuah balet utuh."
  },
  AvgDialog_44812_Content_14 = {
    Text = "Oh? Apakah kamu juga bisa membuat koreografi? Bagaimana tanggapan terhadap pertunjukan tari ini?"
  },
  AvgDialog_44812_Content_15 = {
    Text = "Maaf, Manajer. Drama tari saya tak pernah dipentaskan. Orang tua selalu mengatakan akan memutuskan hubungan denganku jika aku terus menari, bahkan kakek pun telah memukulku berkali-kali karena hal itu…"
  },
  AvgDialog_44812_Content_16 = {
    Text = "<Small:Tidak disangka bahwa orang tua itu begitu pandai berlagak…>"
  },
  AvgDialog_44812_Content_17 = {
    Text = "Manajer? Apakah kamu baru saja mengatakan sesuatu?"
  },
  AvgDialog_44812_Content_18 = {
    Text = "Hah… Aku sedang mengatakan bahwa Saler, pria tua itu, benar-benar menyia-nyiakan bakatmu!"
  },
  AvgDialog_44812_Content_19 = {
    Text = "Manajer berjalan mengelilingi Liz, menilainya dari atas ke bawah dengan tatapan penuh perhatian, seolah-olah sedang mengamati sebuah karya seni yang sangat berharga."
  },
  AvgDialog_44812_Content_2 = {
    Text = "Dari seberang koridor, bisikan percakapan di dalam teater tidak terdengar dengan jelas. Kamu hanya merasakan bahwa suara-suara itu mengandung nada meremehkan dan ejekan yang angkuh."
  },
  AvgDialog_44812_Content_20 = {
    Text = "Otot lenganmu lebih indah dibandingkan dengan gadis mana pun di kelompok ini. Meskipun terlihat ramping, dari tarian audisi yang kamu tampilkan, mereka pasti sangat kuat!"
  },
  AvgDialog_44812_Content_21 = {
    Text = "Dan proporsi pinggang serta kakimu... Liz, kamu adalah penari alami! Menyembunyikan dirimu dan bakatmu di rumah benar-benar sebuah penghinaan terhadap seni!"
  },
  AvgDialog_44812_Content_22 = {
    Text = "Maksud Anda, apakah grup tari Adli akan menerima saya untuk bergabung?"
  },
  AvgDialog_44812_Content_23 = {
    Text = "Benar! Benar sekali. Kamu tidak hanya bisa bergabung dengan kelompok tari, tetapi juga akan menjadi pemimpin baru, kartu as baruku! Pertunjukan tari kamu — itu akan diresmikan di teater terbesar di Londinium!"
  },
  AvgDialog_44812_Content_24 = {
    Text = "Kepala? Tapi jika aku menjadi kepala, bagaimana dengan pemimpin saat ini dari kelompok tari, Nyonya Denaf... Aku mendengar bahwa dia adalah seorang penari yang sangat bangga dan luar biasa.."
  },
  AvgDialog_44812_Content_25 = {
    Text = [[
Dia tidak penting! Yang terpenting sekarang adalah, kami memiliki kamu! 
Tandatangani kontrak keanggotaan ini, aku jamin bisa menjadikanmu bintang kelas dunia!]]
  },
  AvgDialog_44812_Content_26 = {
    Text = "Manajer menggenggam tangan Liz, yang kemudian diliputi oleh kebahagiaan dan rasa penuh semangat, lalu dengan khidmat menandatangani namanya sendiri di atas kertas itu."
  },
  AvgDialog_44812_Content_27 = {
    Text = "Sedangkan pandangan gadis-gadis lain, baik itu pandangan hina atau kasihan, semuanya dianggapnya sebagai kecemburuan terhadap pengakuan yang diterimanya."
  },
  AvgDialog_44812_Content_28 = {
    Text = "Tiga bulan yang lalu"
  },
  AvgDialog_44812_Content_29 = {
    Text = "Putaran cambuk terakhir, satu, dua, tiga, sangat bagus."
  },
  AvgDialog_44812_Content_3 = {
    Text = "...Jangan dengarkan suara-suara itu."
  },
  AvgDialog_44812_Content_30 = {
    Text = "Keningnya mengeluarkan keringat dingin karena gugup, hingga para penari berhasil menyelesaikan gerakan dengan tepat. Liz akhirnya bisa bernapas lega dan memberikan senyuman penuh kegembiraan kepada para penari yang selalu bersamanya sepanjang hari."
  },
  AvgDialog_44812_Content_31 = {
    Text = "Hebat... hebat sekali! Tinggal setengah bagian lagi,\"Swan Song\" ku akan selesai."
  },
  AvgDialog_44812_Content_32 = {
    Text = "Liz ingin meraih tangan para penari, ingin memeluk gadis-gadis itu, tetapi mereka menghindar satu per satu dengan tubuh menyamping, menghindari antusiasmenya."
  },
  AvgDialog_44812_Content_33 = {
    Text = "Teman-teman... ada apa? Jika kita berusaha sedikit lagi, bulan depan kita bisa membawa \"Swan Song\" ke atas panggung."
  },
  AvgDialog_44812_Content_34 = {
    Text = "Ah... maaf, aku terlalu bersemangat. Karena kalian semua,\"Swan Song\" bisa lahir. Ini adalah anak dari kerja keras kami di Adley Dance Troupe —"
  },
  AvgDialog_44812_Content_35 = {
    Text = "Cukup, Liz! Kami sudah bersabar begitu lama, manajer itu sama sekali——"
  },
  AvgDialog_44812_Content_36 = {
    Text = "Cukup! Pikirkan nasib Denaf!"
  },
  AvgDialog_44812_Content_37 = {
    Text = "Penari menahan temannya yang penuh semangat, ekspresinya tampak masih trauma, pandangannya bergerak ke segala arah."
  },
  AvgDialog_44812_Content_38 = {
    Text = "Nasib Nyonya Denaf...? Manajer berkata bahwa dia keluar dari grup untuk kembali ke kampung halaman dan merawat orang tua, bukan?"
  },
  AvgDialog_44812_Content_39 = {
    Text = "Merawat orang tua... hah, tempat yang dipilih manajer untuknya, Count Jeffrey memang bisa dianggap sebagai orang tua."
  },
  AvgDialog_44812_Content_4 = {
    Text = "Liz mengangkat kedua tangannya dan menutupi telingamu."
  },
  AvgDialog_44812_Content_40 = {
    Text = "Tapi manajer juga sangat menyayangi Denaf, pria-pria tua yang dipilihkan untuknya sudah hampir mendekati ajal… Mungkin tidak lama lagi, dia bisa mendapatkan warisan besar dan berkeliling dunia."
  },
  AvgDialog_44812_Content_41 = {
    Text = "Hei! Bukankah manajer sudah secara khusus memperingatkan kita untuk tidak membicarakan hal-hal ini dengannya!"
  },
  AvgDialog_44812_Content_42 = {
    Text = "Graf tua, memilih, warisan…"
  },
  AvgDialog_44812_Content_43 = {
    Text = "Apa yang kalian... bicarakan?"
  },
  AvgDialog_44812_Content_44 = {
    Text = "Melihat bahwa kamu benar-benar mencintai tari —— tinggalkan kelompok tari. Itu saja yang bisa kukatakan."
  },
  AvgDialog_44812_Content_45 = {
    Text = "Ssst, jangan bicara! Cepat sembunyi di belakang panggung, manajer datang!"
  },
  AvgDialog_44812_Content_46 = {
    Text = "Dari sisi lain panggung terdengar suara langkah sepatu, para penari yang lebih akrab satu sama lain buru-buru saling mendorong untuk kembali ke belakang panggung, hanya menyisakan Liz sendirian berdiri dengan linglung di bawah sorotan lampu."
  },
  AvgDialog_44812_Content_47 = {
    Text = "Dia mendapat tepuk tangan yang panjang dan meriah: dari manajer yang membawanya ke dalam kelompok tari. Matanya berbinar dengan cahaya yang bisa disebut fanatik, membuat Liz merasa sedikit tidak nyaman."
  },
  AvgDialog_44812_Content_48 = {
    Text = "Liz, kamu adalah jenius sejati. Pertunjukan balet ini bisa membawa trup tari, bahkan meningkatkan statusmu ke ketinggian yang belum pernah dicapai siapa pun!"
  },
  AvgDialog_44812_Content_49 = {
    Text = "Nilai diri...?"
  },
  AvgDialog_44812_Content_5 = {
    Text = "Bukankah kamu selalu penasaran dengan alasan aku berhenti tampil?"
  },
  AvgDialog_44812_Content_50 = {
    Text = "Graf Jeffrey bersedia membayar biaya operasional kelompok tari selama satu kuartal hanya untuk bertemu denganmu. Ini adalah kabar yang sangat baik."
  },
  AvgDialog_44812_Content_51 = {
    Text = "Manajer, saya tidak mengerti... siapa sebenarnya Count ini? Mengapa dia bersedia mengeluarkan uang untukku?"
  },
  AvgDialog_44812_Content_52 = {
    Text = "Earl adalah penyokong terbesar kelompok tari dan sangat menghargai penari berbakat."
  },
  AvgDialog_44812_Content_53 = {
    Text = "Dengarkan aku, Countess secara tak terduga meninggal dunia sepuluh hari yang lalu. Ini adalah kesempatan sempurna bagimu."
  },
  AvgDialog_44812_Content_54 = {
    Text = "Graf Jeffrey..."
  },
  AvgDialog_44812_Content_55 = {
    Text = "Cukup! Pikirkan nasib Denaf!"
  },
  AvgDialog_44812_Content_56 = {
    Text = "Nasib Nyonya Denaf...? Manajer berkata bahwa dia keluar dari grup untuk kembali ke kampung halaman dan merawat orang tua, bukan?"
  },
  AvgDialog_44812_Content_57 = {
    Text = "Merawat orang tua... hah, tempat yang dipilih manajer untuknya, Count Jeffrey memang bisa dianggap sebagai orang tua."
  },
  AvgDialog_44812_Content_58 = {
    Text = "Tapi manajer juga sangat menyayangi Denaf, pria-pria tua yang dipilihkan untuknya sudah hampir mendekati ajal… Mungkin tidak lama lagi, dia bisa mendapatkan warisan besar dan berkeliling dunia."
  },
  AvgDialog_44812_Content_59 = {
    Text = "Nyonya Earl yang telah meninggal adalah mantan kepala, Miss Denaf, benar kan?"
  },
  AvgDialog_44812_Content_6 = {
    Text = "Kemudian, dengan nada yang lembut dan perlahan, suaranya terdengar berat saat masuk ke telingamu melalui kedua tangannya."
  },
  AvgDialog_44812_Content_60 = {
    Text = "...Dari siapa kamu mendengarnya?"
  },
  AvgDialog_44812_Content_61 = {
    Text = [[
Manajer, tolong katakan yang sebenarnya kepadaku. 
 "Bertemu dengan Count," apakah benar hanya sesederhana itu?]]
  },
  AvgDialog_44812_Content_62 = {
    Text = "Liz menatap lurus ke arah manajer yang berperut buncit dengan tatapan tajam, membuatnya secara tidak sadar memalingkan kepala untuk menghindari kontak mata."
  },
  AvgDialog_44812_Content_63 = {
    Text = "Katakan padaku, apakah kamu menjual Miss Denaf kepada Earl Jeffrey?"
  },
  AvgDialog_44812_Content_64 = {Text = "Jual?"},
  AvgDialog_44812_Content_65 = {
    Text = "Sepertinya manajer menangkap celah dalam ucapan Liz, semangatnya meningkat pesat. Ia membusungkan dada dan berbicara dengan penuh keyakinan."
  },
  AvgDialog_44812_Content_66 = {
    Text = "Denaf menikah dengan sang earl secara sukarela! Adapun hal-hal yang terjadi setelah pernikahan mereka, itu bukan sesuatu yang bisa saya, sebagai manajer kelompok tari kecil, komentari sembarangan. Lagipula, mereka adalah bangsawan!"
  },
  AvgDialog_44812_Content_68 = {
    Text = "Jadi, kelompok tari selalu menjadi alat untuk meraih ketenaran semu bagimu, dan merupakan tangga bagi kalian untuk mendekati mereka yang berkuasa…"
  },
  AvgDialog_44812_Content_69 = {Text = "Benar."},
  AvgDialog_44812_Content_7 = {
    Text = "Adiri Dance Troupe memiliki sejarah panjang dan terkenal di seluruh Federasi, sering menjadi tamu kehormatan bagi bangsawan bahkan keluarga kerajaan… Sejak kecil, aku sudah mendengar nama trupe tersebut."
  },
  AvgDialog_44812_Content_70 = {
    Text = "Apakah kamu tahu bagaimana penonton memandang kita, bagaimana mereka memandangmu? Yang miskin mengagumimu, yang kaya sedang menilaimu! Di seluruh benua, setiap kelompok tari itu sama saja."
  },
  AvgDialog_44812_Content_71 = {
    Text = "Keluargaku bukan! Mereka juga anggota kelompok tari, mereka…"
  },
  AvgDialog_44812_Content_72 = {
    Text = "Tua Saller benar-benar telah merajut mimpi indah untukmu, tidakkah kau tahu apa yang dilakukan tarian Saller? Kakekmu yang baik, Saller, adalah mucikari paling terkenal di seluruh Federasi Constante!"
  },
  AvgDialog_44812_Content_73 = {
    Text = "Apakah kamu sudah bisa tersadar sekarang? Di dunia ini, seni murni sama sekali tidak ada!"
  },
  AvgDialog_44812_Content_74 = {
    Text = "Kontrak yang kamu tanda tangani saat bergabung dengan kelompok tari membuktikan bahwa aku memiliki hak penuh atas dirimu — jadi, sampai kamu bersedia \"menemui\" sang Count, kamu tidak akan bisa pergi ke mana pun!"
  },
  AvgDialog_44812_Content_75 = {
    Text = "Baik, aku tidak akan meninggalkan teater."
  },
  AvgDialog_44812_Content_76 = {
    Text = "Anggap saja kau tahu diri, asalkan kau——"
  },
  AvgDialog_44812_Content_77 = {
    Text = "Namun, sebagai gantinya, saya tidak akan melanjutkan partisipasi dalam latihan \"Swan Song\". Saya tidak akan mengajari kalian langkah tarian untuk adegan terakhir."
  },
  AvgDialog_44812_Content_78 = {
    Text = "Kamu——!"
  },
  AvgDialog_44812_Content_79 = {
    Text = "Aku tidak akan membiarkan kalian terus menodai karyaku. Itu tidak akan menjadi alat untukmu bersekongkol diam-diam dengan kaum bangsawan."
  },
  AvgDialog_44812_Content_8 = {
    Text = "Pada malam pertengahan musim panas setahun yang lalu, saya meninggalkan rumah dan bergabung dengan kelompok tari Adley."
  },
  AvgDialog_44812_Content_80 = {
    Text = "Saya ingin mogok tampil."
  },
  AvgDialog_44812_Content_81 = {Text = "Sekarang"},
  AvgDialog_44812_Content_82 = {
    Text = "Kenyataan yang kejam membuatmu berkeringat dingin dan merinding. Kantong es di tanganmu tanpa sadar mencair menjadi air, mengalir melewati lengan dan membasahi gaun dansamu."
  },
  AvgDialog_44812_Content_83 = {
    Text = "Manajer kelompok tari… ternyata melakukan hal seperti ini."
  },
  AvgDialog_44812_Content_84 = {
    Text = "Apakah kamu... tidak menyadari kejahatan mereka sebelumnya?"
  },
  AvgDialog_44812_Content_85 = {
    Text = "Kamu adalah pendatang baru yang ditemukan dari kalangan rakyat oleh orang bodoh itu, sama seperti aku setahun yang lalu. Aku pikir kamu juga menemukan sesuatu, itulah sebabnya di atas panggung..."
  },
  AvgDialog_44812_Content_86 = {
    Text = "Tidak, aku hanya merasa terlalu tegang..."
  },
  AvgDialog_44812_Content_87 = {
    Text = "Semua yang dikatakan Liz berputar-putar di pikiranmu. Secara naluriah, kamu ingin mempercayainya, tapi…"
  },
  AvgDialog_44812_Content_88 = {
    Text = "Kamu melihat sekilas kalender di samping tempat tidur. Mimpi ini sangat mirip dengan \"kenyataan\"mu, Elizabeth Salle sedang hidup di masa lalu kurang dari tiga puluh tahun yang lalu."
  },
  AvgDialog_44812_Content_89 = {
    Text = "Di era kamu, pertunjukan balet adalah acara yang sangat elegan. Dengan dukungan dari Tuan Mulia Dexter, kamu telah menemani Ramona menonton beberapa pertunjukan dari berbagai kelompok tari."
  },
  AvgDialog_44812_Content_9 = {
    Text = "Setahun yang lalu"
  },
  AvgDialog_44812_Content_90 = {
    Text = "Jika kelompok tari saat ini begitu kotor dan penuh dengan hal-hal buruk, apa sebenarnya yang terjadi sehingga menyebabkan perubahan besar pada kelompok tari tersebut?"
  },
  AvgDialog_44812_Content_91 = {
    Text = "Namun, karena kamu sudah berhenti tampil, mengapa malam ini kamu tetap naik panggung untuk menyelamatkan pertunjukan?"
  },
  AvgDialog_44812_Content_92 = {
    Text = "Liz menatapmu sekilas, seperti seorang dewasa memandang anak kecil yang bodoh — meskipun pada saat ini, dia seharusnya juga masih di bawah umur."
  },
  AvgDialog_44812_Content_93 = {
    Text = "Karena aku tidak rela."
  },
  AvgDialog_44812_Content_94 = {
    Text = "Sebelum bisa berjalan, saya sudah terlebih dahulu belajar bagaimana mengayunkan kedua lengan saya. Saat anak-anak seusiaku hanya sibuk memikirkan permainan petak umpet, aku diam-diam bersembunyi di gudang untuk berlatih berjalan dengan ujung kaki, dan merasa senang karenanya."
  },
  AvgDialog_44812_Content_95 = {
    Text = "Saya tidak bisa meninggalkan tarian, juga tidak bisa melepaskan karya-karya saya... Saya tidak tega melihat manajer mengisi \"Swan Song\" dengan gerakan tari yang kasar dan kaku."
  },
  AvgDialog_44812_Content_96 = {
    Text = "Dia mempermalukan saya dengan cara ini... mempermalukan seni saya."
  },
  AvgDialog_44812_Content_97 = {
    Text = "Liz menggenggam kedua tanganmu semakin erat, dengan kekuatan begitu besar sehingga kamu merasa sebentar lagi akan melebur ke dalam penderitaannya."
  },
  AvgDialog_44812_Content_98 = {
    Text = "Pada suatu saat, jiwa Anda seolah-olah memahami kemarahannya dan kesedihannya, tubuh ini juga demikian."
  },
  AvgDialog_44812_Content_99 = {
    Text = "Tanpa bisa dikendalikan, mata berkedip, dan air mata pun menggantung di bulu mata, membuat dunia di depan mata menjadi kabur."
  },
  AvgDialog_44833_Content_1 = {Text = "Lagu Angsa"},
  AvgDialog_44833_Content_10 = {
    Text = "Apa aroma ini... terasa sangat familiar."
  },
  AvgDialog_44833_Content_11 = {
    Text = "Saat tanganmu menyentuh pintu, kamu merasakan panas yang menguar di koridor belakang panggung, dan asap tebal perlahan masuk ke dalam ruangan melalui celah-celah."
  },
  AvgDialog_44833_Content_12 = {Text = "Terbakar?!"},
  AvgDialog_44833_Content_13 = {
    Text = "Akalmu mengatakan bahwa pintu ruangan tidak akan bertahan lama. Jika struktur teater ini hanya terbuat dari kayu biasa, maka seluruh bangunan akan segera tenggelam dalam lautan api."
  },
  AvgDialog_44833_Content_14 = {
    Text = "Ingin meninggalkan ruangan, tapi tidak bisa keluar atau masuk dari pintu — pandanganmu beralih ke satu-satunya jendela. \n Jika Liz sebelumnya bisa masuk lewat jendela, maka kamu juga bisa keluar lewat jendela."
  },
  AvgDialog_44833_Content_15 = {
    Text = "Tepat di bawah jendela, seperti yang diharapkan, terdapat sebuah kereta kuda. Kamu melompat keluar dari jendela dan mendarat di atap kereta, lalu dengan mudah meninggalkan ruangan yang berada di lantai dua."
  },
  AvgDialog_44833_Content_16 = {
    Text = "Kamu mengikuti suara dan berjalan mengitari alun-alun di depan gedung teater. Alun-alun dipenuhi dengan keriuhan, para tamu yang mengenakan pakaian mewah saling mendorong satu sama lain, berusaha untuk segera meninggalkan teater —"
  },
  AvgDialog_44833_Content_17 = {
    Text = "Minggir! Saya adalah pelayan Count Geoffrey, biarkan saya lewat dulu!"
  },
  AvgDialog_44833_Content_18 = {
    Text = "Gila! Dia benar-benar gila!"
  },
  AvgDialog_44833_Content_19 = {
    Text = "Dengan gerakan cepat dan cermat, kamu berhasil menangkap seorang bangsawan wanita yang berlari begitu kencang hingga sanggulnya terlepas."
  },
  AvgDialog_44833_Content_2 = {Text = "Pletak."},
  AvgDialog_44833_Content_20 = {
    Text = "Bu, apa yang terjadi di dalam teater?"
  },
  AvgDialog_44833_Content_21 = {
    Text = "Apa kamu penari?! Jangan sentuh aku! Kamu pasti satu kelompok dengan wanita gila di Teater Kedua itu!"
  },
  AvgDialog_44833_Content_22 = {
    Text = "Teater Kedua... Apakah itu Liz? Apakah Elizabeth? Gadis yang mengenakan gaun hitam?"
  },
  AvgDialog_44833_Content_23 = {
    Text = "Kau mengenal orang gila itu! Jangan bilang kau bukan kaki tangannya! Cepat! Cepat bunuh penari ini untukku!"
  },
  AvgDialog_44833_Content_24 = {
    Text = "Pekerja kasar dan beberapa penonton yang melihat keramaian saling bertukar pandang, jelas tidak mau melanggar hukum demi kaum bangsawan."
  },
  AvgDialog_44833_Content_25 = {
    Text = "Aku berikan 100 Taring kepada orang pertama yang memenggal kepala! Tidak, 300 Taring!"
  },
  AvgDialog_44833_Content_26 = {
    Text = "Sejumlah besar uang dilemparkan kepada para pekerja kasar yang semula masih menyusut, mendorong mereka untuk segera mengangkat alat dan menyerbu ke arahmu——"
  },
  AvgDialog_44833_Content_3 = {
    Text = [[
Kamu memegang kepalamu dan perlahan tersadar, tak tahu berapa lama waktu telah berlalu. Di luar jendela masih gelap. 
 Mungkin kamu hanya pingsan selama setengah jam, atau mungkin sudah terbaring selama satu hari penuh.]]
  },
  AvgDialog_44833_Content_4 = {
    Text = "Ini adalah bau eter konsentrasi tinggi… Manajer ternyata membekukan sesuatu yang sangat berbahaya di dalam balok es."
  },
  AvgDialog_44833_Content_6 = {
    Text = "Begitu masuk, Liz memberi saya es batu untuk dimakan, jadi... tidak peduli bagaimana pun saya menjawabnya nanti, sejak awal dia sudah memutuskan untuk memberi saya obat itu..."
  },
  AvgDialog_44833_Content_7 = {
    Text = "Elizabeth Salle, Liz… apa sebenarnya yang ingin kamu lakukan?"
  },
  AvgDialog_44833_Content_8 = {Text = "Pletak."},
  AvgDialog_44833_Content_9 = {
    Text = "Sebuah aroma asap alami yang khas langsung menyeruak ke rongga hidung, menghantam jauh ke dalam otak, dengan kuat mendesak sisa-sisa kekuatan obat keluar."
  },
  AvgDialog_44835_Content_1 = {
    Text = "Kamu memberanikan diri mendorong pintu besar Teater Pertama. Meskipun api belum menjalar ke sini, asap tebal dan gelombang panas tak ketinggalan menyergap wajahmu, membuat mata perih."
  },
  AvgDialog_44835_Content_10 = {
    Text = "Penari itu gemetar hebat seperti mendengar nama iblis."
  },
  AvgDialog_44835_Content_11 = {
    Text = "Elizabeth, Elizabeth gila! Dia memberi obat dalam makanan untuk penonton dan orang lain! Semua orang pingsan!"
  },
  AvgDialog_44835_Content_12 = {
    Text = "Hanya orang-orang seperti saya, seorang yang tidak diizinkan makan karena kelebihan berat badan, dan beberapa nyonya yang menjaga bentuk tubuh mereka sehingga tidak makan, yang berhasil melarikan diri…"
  },
  AvgDialog_44835_Content_13 = {
    Text = "Eh! Eh, jangan lari! Sudah kubilang, jangan masuk!"
  },
  AvgDialog_44835_Content_14 = {
    Text = "Kamu mengabaikan nasihat sang penari dan tanpa ragu bergegas menuju arah Teater Kedua."
  },
  AvgDialog_44835_Content_15 = {
    Text = "@2 Taman Teater Kedua"
  },
  AvgDialog_44835_Content_16 = {Text = "Liz!"},
  AvgDialog_44835_Content_17 = {
    Text = "Mendorong pintu gedung teater kedua, pemandangan yang terlihat membuat darah di seluruh tubuhmu langsung berubah menjadi dingin. Para tamu dan penari yang pingsan tergeletak di lantai, hidup atau mati tidak diketahui."
  },
  AvgDialog_44835_Content_18 = {
    Text = "Aula yang dulunya penuh dengan suara saling bersulang kini sunyi senyap, lidah api menjalar ke segala arah, hanya area yang memiliki D-marka yang selamat — di dunia ini, ada hal-hal yang tidak bisa dilahap oleh api."
  },
  AvgDialog_44835_Content_19 = {
    Text = "Kamu seharusnya tidak datang."
  },
  AvgDialog_44835_Content_2 = {
    Text = "Hek, hek hek…"
  },
  AvgDialog_44835_Content_20 = {
    Text = "Liz berdiri di sudut panggung. Kamu tidak bisa melihatnya, hanya suaranya yang terdengar dari kejauhan, seakan-akan terpisah oleh jarak setengah teater."
  },
  AvgDialog_44835_Content_21 = {
    Text = "Liz, apakah kamu yang menyalakan api ini?"
  },
  AvgDialog_44835_Content_22 = {
    Text = [[
Dari arah panggung terdengar dua tawaan ringan yang terdistorsi, kamu juga tahu bahwa pertanyaan ini terlalu hambar. 
 Apakah Liz yang menyulut api ini atau bukan, dia dan "kamu" sudah menemui takdir mereka.]]
  },
  AvgDialog_44835_Content_23 = {
    Text = "█A.F.29@1 tahun@2 Kebakaran besar di Teater Kedua Taman meletus saat pertunjukan balet 《Swan Song》 sedang dipentaskan. \n█Termasuk bangsawan terhormat, Pangeran Elbert, total 13 bangsawan, 25 pelayan, 12 penari, dan 1 manajer perusahaan tari tewas dalam kebakaran tersebut. \n█Setelah Penyelidikan, pelaku pembakaran ternyata adalah pemimpin balet pertama \"Elizabeth Salle\" yang ada dalam daftar korban."
  },
  AvgDialog_44835_Content_24 = {
    Text = "Liz tidak menjawabmu, dia masih membelakangimu, mengayunkan satu tangannya ke depan dan ke belakang, seolah-olah sedang memutar sesuatu."
  },
  AvgDialog_44835_Content_25 = {Text = "Baik."},
  AvgDialog_44835_Content_26 = {
    Text = "Dia melangkah maju dua langkah, lalu berdiri tegak di tengah panggung. Musik yang mengalir pun segera terdengar, menyatu dengan suara gemeretak api."
  },
  AvgDialog_44835_Content_27 = {
    Text = "\"Swan Song\" yang sebenarnya hanya bisa dipentaskan dengan bantuan gramofon."
  },
  AvgDialog_44835_Content_28 = {
    Text = "Kamu membiarkan musisi pergi karena mereka tidak bersalah, kan?"
  },
  AvgDialog_44835_Content_29 = {
    Text = "Kamu juga bisa pergi. Aku sudah mengamati kamu cukup lama, dan kamu tidak menjadi kaki tangan mereka."
  },
  AvgDialog_44835_Content_3 = {
    Text = "Kamu menarik selembar taplak meja, menjatuhkan vas hiasan, dan membasahi taplak meja dengan air dari pot bunga."
  },
  AvgDialog_44835_Content_30 = {
    Text = "Saya... tidak, saya telah menista seni Anda. Apakah kamu lupa? Aku hampir saja menghancurkan \"Swan Song\" milikmu."
  },
  AvgDialog_44835_Content_31 = {
    Text = "Liz berlutut di atas panggung, menunjuk agar Anda mendekatinya, barulah Anda menyadari bahwa panggung telah dipenuhi lendir hitam — apakah itu lendir pelarutan?"
  },
  AvgDialog_44835_Content_32 = {
    Text = "Kamu baru saja melangkah dua langkah ke arahnya, ketika tiba-tiba angin menerpa jendela teater hingga terbuka. Api yang semula hanya menyala diam-diam di tempat gelap tiba-tiba berkembang pesat, lidah api dengan cepat menjalar dan mulai melahap tirai panggung."
  },
  AvgDialog_44835_Content_33 = {
    Text = "Liz! Cepat turun, api sudah menyala!"
  },
  AvgDialog_44835_Content_34 = {
    Text = "Kusen pintu di Teater Kedua runtuh dengan gemuruh, balok kayu yang terkarbonisasi jatuh ke tanah, menimbulkan abu karbon dan percikan api. Sementara itu, karpet wol juga mulai terbakar."
  },
  AvgDialog_44835_Content_35 = {
    Text = "Liz, Elizabeth! Jangan bertindak bodoh, cepat lari bersamaku, masih ada waktu!"
  },
  AvgDialog_44835_Content_36 = {
    Text = "Memberi dunia satu kesempatan lagi... Dunia tiga puluh tahun kemudian, tarian akan menjadi salah satu seni paling murni, asalkan diberi sedikit lebih banyak waktu..."
  },
  AvgDialog_44835_Content_37 = {
    Text = "Liz berbaring di tepi panggung, sekali lagi mengulurkan tangannya ke arahmu."
  },
  AvgDialog_44835_Content_38 = {
    Text = "Telapak tangannya penuh dengan D-lendir, namun saat menempel di pipi Anda, tetap terasa hangat seperti suhu tubuh manusia hidup."
  },
  AvgDialog_44835_Content_39 = {
    Text = "Saya tahu hari ini saya tidak bisa mengakhiri semua kejahatan ini… Saya sudah tahu sejak awal."
  },
  AvgDialog_44835_Content_4 = {
    Text = "Menutupi hidung dan mulut dengan kain basah, uap air yang membawa aroma tanah serta akar tanaman masuk ke dalam paru-paru saat dihirup. Kamu membungkuk, meraba karpet, dan bergerak maju secara perlahan."
  },
  AvgDialog_44835_Content_40 = {
    Text = "Apa yang saya inginkan adalah membuat dunia melihat kegelapan. Saya ingin sinar matahari masuk, tetapi selain cara ini, saya tidak punya pilihan lain."
  },
  AvgDialog_44835_Content_41 = {
    Text = "Setelah mengatakannya, dia mendorongmu dengan kuat."
  },
  AvgDialog_44835_Content_42 = {
    Text = "Maaf, aku memberikan obat padamu tanpa membicarakannya terlebih dahulu."
  },
  AvgDialog_44835_Content_43 = {
    Text = "Apakah kamu benar-benar tidak akan pergi? Masih ada waktu untuk melompat keluar dari jendela."
  },
  AvgDialog_44835_Content_44 = {
    Text = "Kamu menggelengkan kepala, lalu duduk di tepi panggung sambil memeluk lutut."
  },
  AvgDialog_44835_Content_45 = {
    Text = "Kamu menghitung orang yang mengenakan rok tari di dalam teater, termasuk Liz, totalnya hanya 11 orang."
  },
  AvgDialog_44835_Content_46 = {
    Text = "Kamu adalah orang ke-12 yang tewas dalam kobaran api."
  },
  AvgDialog_44835_Content_47 = {
    Text = "Baik, kalau begitu, tolong perhatikan aku dengan baik."
  },
  AvgDialog_44835_Content_48 = {
    Text = "Elizabeth Salle, dengan senang hati mempersembahkan tarian solo \"Swan Song\"."
  },
  AvgDialog_44835_Content_49 = {
    Text = "Liz membungkuk padamu, lalu dengan santai menyingkap tirai yang menyala. D-lendir di tangannya dan tubuhnya langsung terbakar — tidak, itu jelaga."
  },
  AvgDialog_44835_Content_5 = {
    Text = "——Aduh!"
  },
  AvgDialog_44835_Content_50 = {
    Text = "Api merah menyala dengan diam di ujung rok, seperti sayap angsa yang bergetar saat terbebas dari debu."
  },
  AvgDialog_44835_Content_51 = {
    Text = "Liz berputar dengan ringan, setiap putaran membuatnya semakin dekat dengan meteor api yang melintas di langit malam."
  },
  AvgDialog_44835_Content_52 = {
    Text = "Putri seni sedang berteriak pada babak terakhir hidup, api bergulung di atas panggung, namun matanya tidak menunjukkan rasa takut."
  },
  AvgDialog_44835_Content_53 = {
    Text = "Api melahap pemain rekaman hingga menjadi abu, nada terakhir pun lenyap di tengah kobaran api, dan sosoknya perlahan memudar dalam cahaya api."
  },
  AvgDialog_44835_Content_54 = {
    Text = "Dalam lompatan terakhir yang dipeluk oleh api, sebuah cerita mencapai akhirnya, dan sebuah era menyambut penutupannya."
  },
  AvgDialog_44835_Content_6 = {
    Text = "Gadis yang sedang berlari menabrakmu, dan kalian berdua langsung terjatuh berguling-guling."
  },
  AvgDialog_44835_Content_7 = {
    Text = "Kamu, kenapa kamu masih terus masuk! Cepat lari!"
  },
  AvgDialog_44835_Content_8 = {
    Text = "Kamu memiliki kesan terhadap penari ini. Dari deskripsi Liz, dia tampaknya adalah orang yang sangat berhati hangat."
  },
  AvgDialog_44835_Content_9 = {
    Text = "Apakah Liz ada di dalam?"
  },
  AvgDialog_45413_Content_10 = {Text = "N..."},
  AvgDialog_45413_Content_11 = {
    Text = "Sudah lama aku tidak mengingat kembali soal bagaimana aku mendapatkan rupa ini."
  },
  AvgDialog_45413_Content_12 = {
    Text = "Apakah karena mendengar nama pria itu, atau kilasan kenangan menjelang ajal?"
  },
  AvgDialog_45413_Content_13 = {
    Text = "Memori dari masa lalu yang sangat jauh, tiba-tiba muncul di benak saya."
  },
  AvgDialog_45413_Content_14 = {
    Text = "Sebelum menjadi \"binatang buas\", aku hanyalah seorang detektif biasa yang hidup dalam keseharian. Setelah menerima uang dari klien, aku akan pergi minum dua gelas dan bermain kartu."
  },
  AvgDialog_45413_Content_15 = {
    Text = "Karena keberuntungan luar biasa yang melebihi orang biasa, Inspektur Londinium sering meminta bantuan saya untuk mengumpulkan petunjuk dan melacak tersangka."
  },
  AvgDialog_45413_Content_16 = {
    Text = "Komisi yang datang dengan sendirinya tidak ada alasan untuk tidak diambil."
  },
  AvgDialog_45413_Content_17 = {
    Text = "Hingga tersangka yang saya tangkap menghilang secara misterius di rumah tahanan, hanya menyisakan sepasang borgol perak yang terkunci erat. Bentuknya utuh dan berbunyi gemerincing tertiup angin."
  },
  AvgDialog_45413_Content_18 = {
    Text = "Tentu saja, ini tidak ada hubungannya dengan saya. Saya hanya biasa pergi ke kasino bawah tanah yang penuh dengan lampu-lampu terang dan hiruk-pikuk untuk merasa lelah dengan komisi yang baru saja saya terima."
  },
  AvgDialog_45413_Content_19 = {
    Text = "Kamu... buronan itu!"
  },
  AvgDialog_45413_Content_2 = {
    Text = "Cakar kait transparan raksasa muncul di udara tinggi, lalu dengan keras menampar Ryker ke arah dinding."
  },
  AvgDialog_45413_Content_20 = {
    Text = "Ah, apakah kau yang menangkapku?"
  },
  AvgDialog_45413_Content_21 = {
    Text = "Aku tidak keberatan kembali bersamamu dan mendekam di penjara selama dua hari lagi——"
  },
  AvgDialog_45413_Content_22 = {
    Text = "Pria mengguncangkan cangkir dadu di sisinya."
  },
  AvgDialog_45413_Content_23 = {
    Text = "Tapi kamu harus mengalahkanku terlebih dahulu."
  },
  AvgDialog_45413_Content_24 = {
    Text = "Saya tidak merasa akan kalah."
  },
  AvgDialog_45413_Content_25 = {
    Text = "Ryker telah hidup selama dua puluh lima tahun dan belum pernah kalah."
  },
  AvgDialog_45413_Content_26 = {
    Text = "Selama saya sepenuhnya fokus, membiarkan cahaya yang berputar di kasino, suara dadu yang bergulir, dan gambar kartu yang berkedip masuk ke dalam pikiran saya..."
  },
  AvgDialog_45413_Content_27 = {
    Text = "Intuisi akan memberikan jawaban kepadaku."
  },
  AvgDialog_45413_Content_28 = {Text = "Buka."},
  AvgDialog_45413_Content_29 = {
    Text = "Eh, tunggu sebentar, kamu belum mengatakan apa yang kamu pertaruhkan."
  },
  AvgDialog_45413_Content_3 = {
    Text = "Darah mengalir dari sudut bibir Ryker, udara di paru-parunya terdesak keluar, bahkan bernapas pun menjadi sulit."
  },
  AvgDialog_45413_Content_30 = {
    Text = "Apa yang kamu inginkan?"
  },
  AvgDialog_45413_Content_31 = {
    Text = [[
Aku tidak pernah berniat untuk mempertaruhkan apa pun. 
Lagipula, apa pun yang kupertaruhkan, tetap aku yang akan menang.]]
  },
  AvgDialog_45413_Content_32 = {
    Text = "Tenang saja, kamu bisa meminta apapun."
  },
  AvgDialog_45413_Content_33 = {
    Text = "Hmm... apakah aku akan memilih cerutu ini?"
  },
  AvgDialog_45413_Content_34 = {
    Text = "Dia menunjuk ke arah cerutu yang sedang kuhisap."
  },
  AvgDialog_45413_Content_36 = {
    Text = "Maaf, terima saja ya."
  },
  AvgDialog_45413_Content_37 = {
    Text = "Pria itu dengan senyuman lebar mengambil cerutu yang menyala dari tanganku, mengabaikan ekspresi terkejutku, menarik napas dalam-dalam, lalu dengan nada mengejek menghembuskan lingkaran asap putih."
  },
  AvgDialog_45413_Content_38 = {
    Text = "Bagaimana, masih mau main satu putaran lagi?"
  },
  AvgDialog_45413_Content_39 = {
    Text = "Pada hari itu, saya kehilangan dompet saya. tongkat saya. topi pemburu saya. dasi saya. dan jas saya."
  },
  AvgDialog_45413_Content_4 = {
    Text = "Apakah masih ada gunanya membuang-buang waktu? Pelurumu pasti akan habis, cepat atau lambat."
  },
  AvgDialog_45413_Content_40 = {
    Text = "Kami bermain membandingkan ukuran, blackjack, dan Texas Hold'em."
  },
  AvgDialog_45413_Content_41 = {
    Text = "Saya telah bertempur ratusan kali, namun tak pernah sekalipun meraih kemenangan."
  },
  AvgDialog_45413_Content_42 = {
    Text = "Akhirnya, dia mengeluarkan sebuah revolver."
  },
  AvgDialog_45413_Content_43 = {
    Text = "Itu adalah permainan kejam bernama roulette, dengan nyawa manusia sebagai taruhannya."
  },
  AvgDialog_45413_Content_44 = {
    Text = "Orang-orang di meja judi bergiliran menggunakan revolver untuk menembak ke arah kepala mereka sendiri, sampai peluru satu-satunya mengenai pelipis salah satu penjudi."
  },
  AvgDialog_45413_Content_45 = {
    Text = "Saya menembak tanpa ragu, peluru itu tanpa ampun merenggut nyawa saya."
  },
  AvgDialog_45413_Content_46 = {
    Text = "Untuk membuatnya mengakui kesalahannya dan menerima hukuman, aku mengejar pria bernama \"N\" dan bertaruh sebanyak 316 kali."
  },
  AvgDialog_45413_Content_47 = {
    Text = "Tidak disangka kamu memiliki rasa keadilan yang cukup kuat."
  },
  AvgDialog_45413_Content_48 = {
    Text = "Bukan, ini tidak ada hubungannya dengan rasa keadilan. Aku hanya belum pernah kalah."
  },
  AvgDialog_45413_Content_49 = {
    Text = "Tidak suka kalah, tidak mau kalah, tidak ingin kalah?"
  },
  AvgDialog_45413_Content_5 = {
    Text = "Dan setiap napasmu, setiap detak jantungmu, akan memberikan energi baru pada penampilanku."
  },
  AvgDialog_45413_Content_50 = {
    Text = "Ini bukanlah kontes analisis kata, teman saya."
  },
  AvgDialog_45413_Content_51 = {
    Text = "Aku hanya... murni saja, belum pernah kalah sebelumnya."
  },
  AvgDialog_45413_Content_52 = {
    Text = "Bagi saya, kemenangan adalah takdir yang sudah ditentukan. Oleh karena itu, saya penasaran. Saya ingin tahu bagaimana pria itu bisa mematahkan dan mengendalikan takdir."
  },
  AvgDialog_45413_Content_53 = {
    Text = "Dengan hidup sebagai taruhannya, semua orang memanggilku orang gila. Aku bahkan tidak tahu siapa di antara kau dan aku yang lebih mirip orang gila."
  },
  AvgDialog_45413_Content_54 = {
    Text = "Kamu menggambarkannya secara berlebihan. Orang-orang ini telah mencurahkan hidup mereka untuk penelitian dan memecahkan pelarutan. Herbert mengejar kenaikan tubuh manusia, sedangkan bangsa Aram mengejar warisan abadi dari darah mereka."
  },
  AvgDialog_45413_Content_55 = {
    Text = "Semua orang merasa lelah karena menghabiskan waktu untuk hal-hal yang tidak pasti hasilnya. Rasa ingin tahu saya juga tidak berbeda, jadi tidak bisa dikatakan sebagai pengorbanan."
  },
  AvgDialog_45413_Content_56 = {
    Text = "Lagipula, pria itu membantu saya membentuk Tubuh baru dan perjanjian baru. Sekarang saya memiliki waktu yang tak terbatas untuk menjelajahi dunia baru, mungkin ini bisa dianggap sebagai berkah dari musibah."
  },
  AvgDialog_45413_Content_57 = {
    Text = "Sebuah peluru, serangan rasa sakit, dia akan bertaruh di sisi yang berlawanan denganku dan pasti akan menang——"
  },
  AvgDialog_45413_Content_58 = {
    Text = "Kali ini, aku bertaruh bahwa kamu bisa menghentikan %player% untuk pergi ke tempat upacara."
  },
  AvgDialog_45413_Content_59 = {
    Text = "Ryker menempelkan revolver ke pelipisnya."
  },
  AvgDialog_45413_Content_6 = {
    Text = "Semakin kamu berusaha, semakin kuat jeruji itu menutup."
  },
  AvgDialog_45413_Content_60 = {
    Text = "Terlalu percaya diri, terlalu ceroboh!"
  },
  AvgDialog_45413_Content_61 = {
    Text = [[
Jika aku memberitahumu bahwa di balik semua ini ada bayangan Sang Dewasa. 
Menurutmu, apakah dia masih akan membantumu?]]
  },
  AvgDialog_45413_Content_62 = {
    Text = "Ryker menghela napas dengan pelan."
  },
  AvgDialog_45413_Content_63 = {
    Text = "Sebagai sesama pencari kesenangan, kamu tidak pernah bisa merasakan emosi manusia, sehingga pemahamanmu tentang kebahagiaan juga tidak mencapai tingkat yang paling mendalam."
  },
  AvgDialog_45413_Content_64 = {
    Text = "Saya bertaruh dengan hidup saya kali ini — saya yakin dia akan memenuhi janjinya."
  },
  AvgDialog_45413_Content_65 = {
    Text = "\"Dengan suara 'bum', terdengar suara tembakan.\""
  },
  AvgDialog_45413_Content_66 = {
    Text = "Kemudian terdapat beberapa detik keheningan."
  },
  AvgDialog_45413_Content_67 = {
    Text = "Apa sih, bikin aku kaget banget…"
  },
  AvgDialog_45413_Content_68 = {
    Text = "Di atas layar, tawa riang bergema secara mendadak."
  },
  AvgDialog_45413_Content_69 = {
    Text = [[
Bagus, bagus! Kau masih sesombong dulu, tidak sia-sia aku memberimu tubuh yang sempurna ini. 
Jika begitu, aku akan menikmati sisa hidupmu dan mengabulkan keinginanmu.]]
  },
  AvgDialog_45413_Content_7 = {
    Text = "Orang yang memberimu penampilan ini, namanya \"N\", kan? Sungguh pelit sekali, ya?"
  },
  AvgDialog_45413_Content_70 = {
    Text = "Dua dadu 10-sisi berwarna hitam dengan hiasan emas muncul di telapak tangan Ryker."
  },
  AvgDialog_45413_Content_71 = {
    Text = "Lemparkan dadu. Jika kamu bisa mendapatkan angka 1, aku akan melahap musuhmu."
  },
  AvgDialog_45413_Content_72 = {
    Text = "Ryker tertawa terbahak-bahak, darah yang tersembur dari batuknya memercik di bawah sorot lampu."
  },
  AvgDialog_45413_Content_73 = {
    Text = "Sulit dipahami."
  },
  AvgDialog_45413_Content_74 = {
    Text = "Ryker melempar dua dadu 10-sisi."
  },
  AvgDialog_45413_Content_75 = {
    Text = "Dadu bergulir dengan suara \"gulu gulu\"."
  },
  AvgDialog_45413_Content_76 = {
    Text = "Hanya dalam hal keberuntungan ini..."
  },
  AvgDialog_45413_Content_77 = {
    Text = "Sebuah dadu berhenti di 00."
  },
  AvgDialog_45413_Content_78 = {
    Text = "Aku Ryker, tak pernah kalah."
  },
  AvgDialog_45413_Content_79 = {
    Text = "Dadu lainnya berhenti di 01."
  },
  AvgDialog_45413_Content_8 = {
    Text = "Cakar terlepas, Ryker jatuh bebas, batuk hebat, dan terserang kelemahan, lalu terkulai lemas di tanah."
  },
  AvgDialog_45413_Content_80 = {
    Text = "Sesaat berikutnya yang terdengar adalah tawa pria dari kalangan atas tanpa rasa takut, serta jeritan menyayat hati dari sang pesulap."
  },
  AvgDialog_45413_Content_81 = {
    Text = "D-lendir hitam melarutkan seluruh tirai, hingga tersisa dua serpihan berbentuk bulan sabit, yang melayang jatuh ke atas pasir."
  },
  AvgDialog_45413_Content_82 = {
    Text = "Seolah-olah mata pria itu dipenuhi oleh senyuman yang lembut."
  },
  AvgDialog_45413_Content_9 = {
    Text = "Kamu lemah sekali, bahkan tidak mirip Pembangun, apakah Indeks gnostik sudah melewati 21?"
  },
  AvgDialog_45414_Content_1 = {
    Text = "Aneh, monster——"
  },
  AvgDialog_45414_Content_10 = {
    Text = "Kerangka, kerangka ada di ruangan gelap di depan!"
  },
  AvgDialog_45414_Content_11 = {
    Text = "Pada saat yang sama - Pipa pabrik yang ditinggalkan"
  },
  AvgDialog_45414_Content_12 = {
    Text = "Pemuda itu merangkak melalui pipa pabrik yang terbengkalai, karat dan jelaga telah menodai wajahnya yang tampan menjadi hitam belang-belang."
  },
  AvgDialog_45414_Content_13 = {
    Text = "Dia berusaha meminimalkan gerakan, mengikuti tim di bawahnya dengan maju secara perlahan."
  },
  AvgDialog_45414_Content_14 = {
    Text = "Saya sudah memperingatkan Juliette sejak awal, para pelancong itu pasti bukan orang baik-baik…"
  },
  AvgDialog_45414_Content_16 = {
    Text = "……………"
  },
  AvgDialog_45414_Content_17 = {
    Text = "Di pintu masuk ruang gelap, pria berkepala serigala menendang pintu besi hingga terbuka lebar, meninggalkan seorang prajurit Alan di ambang pintu ruang gelap. Sementara itu, yang lainnya mulai memasuki ruangan melalui pintu gelap yang runtuh."
  },
  AvgDialog_45414_Content_18 = {
    Text = "Pemuda itu memanfaatkan kesempatan untuk meluncur turun dari pipa, lalu melepas penutup kepala dan tali prajurit Aran."
  },
  AvgDialog_45414_Content_19 = {
    Text = "Shh, jangan menggoyang sarang semut. Aku akan mengikuti mereka, kau pergi memberi tahu Tuan Alva…"
  },
  AvgDialog_45414_Content_2 = {
    Text = "Setiap hari saling berkelahi dengan Nubia, heran kalian masih bisa menganggap aku seperti monster."
  },
  AvgDialog_45414_Content_3 = {
    Text = "Katakanlah, di mana kamu menyembunyikan sisa pohon suci itu?"
  },
  AvgDialog_45414_Content_4 = {
    Text = "Pohon Ibu di atas, kami tidak akan membocorkan informasi apapun——"
  },
  AvgDialog_45414_Content_5 = {
    Text = "Oh? Apakah benar?"
  },
  AvgDialog_45414_Content_6 = {
    Text = "Ryker membungkuk, napas serigala mengeluarkan geraman rendah yang serak. Suara taring yang saling beradu terdengar jelas di pabrik yang sunyi."
  },
  AvgDialog_45414_Content_7 = {
    Text = "Tahukah kamu bagaimana rasanya diloloskan oleh serigala? Biar aku beritahu, rasa sakit ketika gigi tajam menembus dalam, lalu Caro dan saraf sekaligus ditarik keluar—"
  },
  AvgDialog_45414_Content_8 = {
    Text = "<Shake: Jangan, jangan makan aku, aku bilang——>"
  },
  AvgDialog_45414_Content_9 = {
    Text = "Hei, kau ini——"
  },
  AvgDialog_45415_Content_1 = {
    Text = "Badai semakin ganas, tentara Aran menangis tersedu-sedu, kalap, berteriak keras, memohon, dan mengutuk."
  },
  AvgDialog_45415_Content_10 = {
    Text = "Banyak orang Aram menghadap ke arah Thais dengan khidmat, lalu berlutut penuh kesungguhan."
  },
  AvgDialog_45415_Content_11 = {
    Text = "Makhluk pasir yang gelisah perlahan mereda amarahnya di bawah pengaruh doa, dan badai pun mulai mereda."
  },
  AvgDialog_45415_Content_12 = {
    Text = "Ini Ratu! Ini Ratu!"
  },
  AvgDialog_45415_Content_13 = {
    Text = "Terima kasih atas perlindungan Ratu!"
  },
  AvgDialog_45415_Content_14 = {
    Text = "Mata sang ratu masih mengamati kita!"
  },
  AvgDialog_45415_Content_15 = {
    Text = "Kami… tiba!"
  },
  AvgDialog_45415_Content_2 = {
    Text = "Tidak jauh dari bukit pasir tersebut, kamu melihat sosok itu."
  },
  AvgDialog_45415_Content_3 = {
    Text = "Dari siluetnya, kamu mengenali bahwa itu Thais."
  },
  AvgDialog_45415_Content_4 = {
    Text = "Badai... apakah sudah mereda?"
  },
  AvgDialog_45415_Content_5 = {
    Text = "Dia melantunkan doa yang tak dikenal, membiarkan angin kencang menyeret jubah sutranya, melangkah perlahan namun mantap ke dalam badai pasir yang pekat."
  },
  AvgDialog_45415_Content_6 = {
    Text = "Dentuman terdengar memekakkan telinga, namun suara doa tetap terdengar dengan jelas, seolah-olah bergema di bagian dalam tengkorakmu."
  },
  AvgDialog_45415_Content_7 = {
    Text = "Di tengah badai yang menelan langit dan bumi, dia tampak seperti sedang berbicara dengan tenang kepada suatu makhluk hidup yang tinggal di gurun."
  },
  AvgDialog_45415_Content_8 = {
    Text = "Itu Ratu! Ratu datang untuk menyelamatkan kita, menyelamatkan Aran!"
  },
  AvgDialog_45415_Content_9 = {
    Text = "Tim Aran yang semula bersiap untuk melarikan diri tiba-tiba berhenti."
  },
  AvgDialog_45416_Content_1 = {
    Text = "Sepertinya, nak, kau mengenal makhluk-makhluk kecil ini?"
  },
  AvgDialog_45416_Content_10 = {
    Text = "Berkat perlindungan Pohon Ibu, orang Aram dapat menggunakan kecepatan reproduksi yang luar biasa untuk melawan tingkat kematian dini dan angka kematian yang sangat tinggi."
  },
  AvgDialog_45416_Content_11 = {
    Text = "Jadi, kita memerlukan acara api unggun... kita tidak bisa melakukannya tanpa acara api unggun."
  },
  AvgDialog_45416_Content_12 = {
    Text = "Tentang Nubia"
  },
  AvgDialog_45416_Content_13 = {
    Text = "Saya juga tidak tahu dari mana asalnya, tapi saya mencium aroma yang familiar dari tubuh mereka."
  },
  AvgDialog_45416_Content_14 = {
    Text = "Terkadang saya merasa bahwa Nubia juga merupakan salah satu keturunan Aran."
  },
  AvgDialog_45416_Content_15 = {
    Text = "...Apakah kamu bilang mereka sedang mengusir Aram untuk membuka Dinding Badai?"
  },
  AvgDialog_45416_Content_16 = {
    Text = "Ini sesuai dengan dugaanku. Lihat, Aram juga ingin masuk ke dalam Dinding Badai untuk mencari Pohon Ibu, bukan?"
  },
  AvgDialog_45416_Content_17 = {
    Text = "Namun, itu tidak akan berhasil. Dinding badai hanya akan terbuka untuk utusan yang diakui."
  },
  AvgDialog_45416_Content_18 = {
    Text = "Apakah ada pertanyaan lain?"
  },
  AvgDialog_45416_Content_19 = {
    Text = "Tentang Juliette"
  },
  AvgDialog_45416_Content_2 = {
    Text = "Hmm, tidak. Dibandingkan dengan binatang-binatang ini, kau justru tampak seperti monster sejati."
  },
  AvgDialog_45416_Content_20 = {
    Text = "Lagipula, mengenai \"Utusan\" Juliette, saya ingin mengetahui informasi tentang dia."
  },
  AvgDialog_45416_Content_21 = {
    Text = "\"Utusan dari negeri asing\"kah?"
  },
  AvgDialog_45416_Content_22 = {
    Text = "Pertanyaan ini seharusnya aku yang mengajukannya padamu."
  },
  AvgDialog_45416_Content_23 = {
    Text = "%player%, apakah kamu mempercayai utusan bernama Juliette?"
  },
  AvgDialog_45416_Content_24 = {Text = "Percaya"},
  AvgDialog_45416_Content_25 = {
    Text = "Tidak percaya"
  },
  AvgDialog_45416_Content_26 = {
    Text = "Sebelum kamu sempat berbicara, Thais mendekat dan dengan lembut meletakkan jari telunjuknya di puncak bibirmu."
  },
  AvgDialog_45416_Content_27 = {
    Text = "Tidak perlu terburu-buru, ceritakanlah dengan perlahan."
  },
  AvgDialog_45416_Content_28 = {
    Text = "Waktu kita... masih sangat lama."
  },
  AvgDialog_45416_Content_3 = {
    Text = "Makhluk kecil, apakah ada hal yang ingin kamu tanyakan kepada Ratu Alana?"
  },
  AvgDialog_45416_Content_4 = {
    Text = "Tentang Pesta Api Unggun"
  },
  AvgDialog_45416_Content_5 = {
    Text = "Ah, kamu benar-benar menanyakan sesuatu yang membuatku sedih."
  },
  AvgDialog_45416_Content_6 = {
    Text = "Aku juga tidak menyangka, ternyata ada orang yang menolak untuk melahirkan keturunan bagi Ratu Alan."
  },
  AvgDialog_45416_Content_7 = {
    Text = "Singkatnya, menurutmu apakah gurun ini cocok untuk kehidupan manusia?"
  },
  AvgDialog_45416_Content_8 = {
    Text = "Kamu mengingat kembali badai pasir yang melanda, sumber air yang hampir kering, binatang buas yang muncul di malam hari, ular dan semut beracun, serta tempat penyimpanan air yang mengalami pelarutan, lalu menggelengkan kepala."
  },
  AvgDialog_45416_Content_9 = {
    Text = "Namun, rakyat Aran tidak bisa meninggalkan tempat ini."
  },
  AvgDialog_45417_Content_1 = {
    Text = "Cabang-cabang Pohon Ibu seolah memiliki kehendak sendiri, berlomba-lomba menjulur ke segala arah. Kontur Tubuh manusia samar-samar terlihat di dalamnya, dengan gerakan yang kaku dan penuh penderitaan."
  },
  AvgDialog_45417_Content_10 = {
    Text = "Ramona, nyalakan Pohon Ibu dengan Api Chip Perak! Hanya kamu yang bisa melakukannya!"
  },
  AvgDialog_45417_Content_11 = {
    Text = "Fatamorgana perak menghantam akar Pohon Ibu, api perak menyala dalam sekejap, berubah menjadi kobaran api yang disebut Kehancuran."
  },
  AvgDialog_45417_Content_12 = {
    Text = "Lidah api seperti ular perak merambat naik di sepanjang cabang, dedaunan bergoyang dan berteriak dalam amukan api, mengeluarkan suara mendesis yang menusuk telinga, seolah-olah Pohon Ibu sedang merintih dan menangis dalam penderitaan."
  },
  AvgDialog_45417_Content_13 = {
    Text = "Tunggu, pohon akan tumbang, Penjaga belum turun!"
  },
  AvgDialog_45417_Content_14 = {
    Text = "Tenang saja, anak baik. Aku pasti akan mengembalikan {Male=dia,Female=dia} dengan selamat kepada mu."
  },
  AvgDialog_45417_Content_15 = {
    Text = "Pohon raksasa berguncang, langit dan bumi bergetar."
  },
  AvgDialog_45417_Content_16 = {
    Text = "Kamu kehilangan keseimbangan dan terjatuh lurus ke bawah——"
  },
  AvgDialog_45417_Content_17 = {
    Text = "Berapa tinggi di sini? Seribu kaki? Atau lebih?"
  },
  AvgDialog_45417_Content_18 = {
    Text = "Lalu, sebuah pelukan yang hangat dan lembut menyelimutimu."
  },
  AvgDialog_45417_Content_19 = {
    Text = "Anak baik, kamu sudah melakukan dengan sangat baik."
  },
  AvgDialog_45417_Content_2 = {
    Text = "Orang pertama yang berevolusi memiliki tenggorokan mengeluarkan erangan, dengan susah payah melepaskan diri dari ikatan Pohon Ibu, jatuh dari ketinggian ke Sungai Suci."
  },
  AvgDialog_45417_Content_20 = {
    Text = "Di dadanya, giok putih yang kau pasang sendiri bersinar terang, berpadu indah dengan kulitnya yang halus seperti sutra."
  },
  AvgDialog_45417_Content_21 = {
    Text = "Thais mengulurkan tangan untuk memetiknya, memasukkannya ke dalam mulut, lalu perlahan menggigitnya hingga pecah."
  },
  AvgDialog_45417_Content_22 = {
    Text = [[
Aku akan kembali ke Sungai Suci, memberi makan seluruh bumi.
Ini adalah hadiah perpisahan untukmu.]]
  },
  AvgDialog_45417_Content_23 = {
    Text = "Pada saat jatuh ke Sungai Suci yang bergelombang, bibirnya menyentuh bibirmu."
  },
  AvgDialog_45417_Content_24 = {
    Text = "Napas kalian saling bersilangan, jiwa menyatu."
  },
  AvgDialog_45417_Content_25 = {
    Text = "Ujung lidah mendorong masuk, hangat, lembap, penuh kasih sayang, dan tak terelakkan."
  },
  AvgDialog_45417_Content_26 = {
    Text = "Ciuman itu bercampur dengan manisnya cinta, bau amis darah, dan sebuah benda kecil yang bulat."
  },
  AvgDialog_45417_Content_27 = {
    Text = "Benih pohon."
  },
  AvgDialog_45417_Content_3 = {Text = "...Dong!"},
  AvgDialog_45417_Content_31 = {
    Text = "Meskipun tidak dalam bentuk yang kubayangkan… tapi sudah berakhir."
  },
  AvgDialog_45417_Content_32 = {
    Text = "Sebagai keturunan dari esensi keinginan, bangsa Alan sangat berdedikasi untuk melanjutkan garis keturunan mereka."
  },
  AvgDialog_45417_Content_33 = {
    Text = "Oleh karena itu, kami menyembah Pohon Ibu, mengintegrasikan susu Pohon Ibu ke dalam daging tulang kami, dan berdoa untuk kemampuan reproduksi yang melampaui manusia."
  },
  AvgDialog_45417_Content_34 = {
    Text = "Selama ada satu orang yang selamat dari malapetaka hitam, peradaban dapat terus berlanjut di generasi berikutnya."
  },
  AvgDialog_45417_Content_35 = {
    Text = "Namun, kami keliru."
  },
  AvgDialog_45417_Content_36 = {
    Text = "Yang melanjutkan garis keturunan bangsa Aran bukanlah salah satu etnis Aran. Dalam perjalanan waktu yang panjang, mereka terlalu bergantung pada konsep \"keturunan\"dan menjadi budak dari \"Keinginan\"untuk berkembang biak."
  },
  AvgDialog_45417_Content_37 = {
    Text = "Selama ratusan tahun dalam pengasingan... adalah Alva yang menopang bangsa Aram untuk terus maju."
  },
  AvgDialog_45417_Content_38 = {
    Text = "Tawil, kamu benar. Kita harus percaya pada kehendak manusia."
  },
  AvgDialog_45417_Content_39 = {
    Text = "Meskipun malam yang panjang sulit terang, meskipun cahayanya lemah, Roh mereka yang tak pernah menyerahlah yang benar-benar dapat mengubah masa depan yang telah ditakdirkan."
  },
  AvgDialog_45417_Content_4 = {Text = "Dong!"},
  AvgDialog_45417_Content_40 = {
    Text = "Sekarang, aku sudah mendapatkan jawaban baru."
  },
  AvgDialog_45417_Content_41 = {
    Text = "Jadi, kamu juga harus bersikap murah hati dan meminjamkan Pewarismu padaku, oke?"
  },
  AvgDialog_45417_Content_42 = {
    Text = "Saya bersedia mempercayai orang ini dan menyerahkan api kepada {Male=dia,Female=dia}."
  },
  AvgDialog_45417_Content_43 = {
    Text = "Benih ini suatu hari nanti akan berakar dan bertunas, tumbuh menjadi pohon yang menjulang tinggi,"
  },
  AvgDialog_45417_Content_44 = {
    Text = "Tepat seperti hari ketika Pohon Ibu pertama kali dilahirkan."
  },
  AvgDialog_45417_Content_46 = {
    Text = "Ini adalah Benih terakhir, aku akan meninggalkannya di dalam tubuhmu."
  },
  AvgDialog_45417_Content_47 = {
    Text = "Sebelum ia menyebarkan darahku ke bumi, kau... jangan mati."
  },
  AvgDialog_45417_Content_48 = {
    Text = "Selalu ingat aku, jangan lupakan aku."
  },
  AvgDialog_45417_Content_49 = {
    Text = "Gelombang pasang bergelora."
  },
  AvgDialog_45417_Content_5 = {
    Text = "Dung! Dung!"
  },
  AvgDialog_45417_Content_50 = {
    Text = "Pelukan yang hangat itu mendorongmu menjauh."
  },
  AvgDialog_45417_Content_51 = {
    Text = "Di tengah hanyutanmu yang terombang-ambing oleh arus, kau melihatnya melayang ke arah yang lebih dalam di sungai."
  },
  AvgDialog_45417_Content_53 = {
    Text = "Sebuah tangan putih yang ramping menarikmu, kekuatan itu terasa akrab dan teguh."
  },
  AvgDialog_45417_Content_54 = {Text = "%player%!"},
  AvgDialog_45417_Content_6 = {
    Text = "Satu per satu orang Aram jatuh."
  },
  AvgDialog_45417_Content_7 = {
    Text = "Beberapa detik kemudian, beberapa kepala kecil muncul dengan susah payah di permukaan air dan berenang menuju tepi sungai."
  },
  AvgDialog_45417_Content_8 = {
    Text = "Cabang di bawah kaki mulai bergetar."
  },
  AvgDialog_45417_Content_9 = {
    Text = "Sudah waktunya!"
  },
  AvgDialog_45418_Content_1 = {
    Text = "Huh, huh, kalian curang, tidak tahu malu."
  },
  AvgDialog_45418_Content_10 = {
    Text = [[
Tidak perlu. 
Benih Pohon Ibu tidak ada di dalamnya.]]
  },
  AvgDialog_45418_Content_11 = {
    Text = "Tak disangka, Sisa pohon suci umat Aram sudah terpelarut sampai seperti ini..."
  },
  AvgDialog_45418_Content_12 = {
    Text = "Herbert dan Casiah menghilang di ujung lautan pasir, kalian bertiga akhirnya mendapatkan sedikit kesempatan untuk bernapas."
  },
  AvgDialog_45418_Content_13 = {
    Text = "Sudah bisa memberitahu Alva untuk mengambil Kerangka."
  },
  AvgDialog_45418_Content_14 = {
    Text = "Tidak perlu terburu-buru, ini adalah kesempatan terbaik kita untuk memahami kerangka Pohon Ibu, bukan?"
  },
  AvgDialog_45418_Content_15 = {
    Text = "Lagipula... kalian lihat sudut tempat Casiah berada tadi."
  },
  AvgDialog_45418_Content_16 = {
    Text = "Di celah sudut kerangka, cairan hitam perlahan-lahan mengalir keluar, masuk ke dalam alur yang sengaja dipahat di tanah."
  },
  AvgDialog_45418_Content_17 = {
    Text = "Tunggu, aku merasa pernah melihat struktur serupa di tenda Ratu..."
  },
  AvgDialog_45418_Content_18 = {
    Text = [[
Ini menunjukkan bahwa itu bukan perbuatan Casiah, melainkan struktur yang dibuat oleh Aram. 
 Mereka mengekstraksi D-lendir dari kerangka untuk tujuan tertentu.]]
  },
  AvgDialog_45418_Content_19 = {
    Text = "Rasa penasaran kalian semua akan saya jawab."
  },
  AvgDialog_45418_Content_2 = {Text = "Namun, ..."},
  AvgDialog_45418_Content_20 = {
    Text = [[
Entah sejak kapan, Juliette telah kembali. 
Dia muncul di balik gerbang besi, melangkah melewati tangga batu bertingkat-tingkat menuju kalian.]]
  },
  AvgDialog_45418_Content_21 = {
    Text = "Karena kita semua terlibat dalam hal-hal misterius, saya akan langsung bertanya: Apakah Universitas Mythag memiliki pemahaman tentang ketiga badan tersebut?"
  },
  AvgDialog_45418_Content_22 = {
    Text = [[
Ramona dan Ryker sama-sama menatapmu. 
 Mengingat sikap Juliette sepanjang jalan, setelah ragu sejenak, kamu mengangguk.]]
  },
  AvgDialog_45418_Content_23 = {
    Text = "Karena kalian sudah mendengar tentang Esensi Keinginan, akan lebih mudah untuk menjelaskannya."
  },
  AvgDialog_45418_Content_24 = {
    Text = "Sisa pohon suci yang disebut-sebut... adalah mumi dari entitas hasrat <Yellow:Tifreyayeth>."
  },
  AvgDialog_45418_Content_25 = {
    Text = "Bagi orang Aram, yang paling krusial adalah cairan yang terkumpul di dalam peti mati ini."
  },
  AvgDialog_45418_Content_26 = {
    Text = "Itu mengalir dari dalam mumi, tanpa henti."
  },
  AvgDialog_45418_Content_27 = {
    Text = "Kamu dan aku sama-sama tahu... ini, adalah D-lendir."
  },
  AvgDialog_45418_Content_28 = {
    Text = "Kekuatan ilahi Tifreysod membuat erosi pelarutan menjadi sangat lambat, dan Aram memperoleh kekuatan untuk berkembang biak serta beregenerasi darinya."
  },
  AvgDialog_45418_Content_29 = {
    Text = "Tunggu, maksudmu……"
  },
  AvgDialog_45418_Content_3 = {
    Text = "Tempat Casiah juga sudah siap!"
  },
  AvgDialog_45418_Content_30 = {
    Text = "Ramona mulai merasa mual dan keringat dingin."
  },
  AvgDialog_45418_Content_31 = {
    Text = "Kalian... menggunakan <Yellow:D-lendir> dari kerangka Pohon Ibu... untuk membuat <Yellow:minuman> pesta."
  },
  AvgDialog_45418_Content_32 = {
    Text = "Jadi, mereka akan jatuh ke dalam kegilaan, dan mereka akan memperoleh kemampuan reproduksi yang abnormal…"
  },
  AvgDialog_45418_Content_33 = {
    Text = "Itu tidak berasal dari darah daging, melainkan dari mumi ini."
  },
  AvgDialog_45418_Content_34 = {
    Text = "Karena Pohon Ibu menghilang, kekuatan ilahi melemah, sehingga proporsi janin cacat terus meningkat."
  },
  AvgDialog_45418_Content_35 = {
    Text = "Kalian juga memperhatikannya, kan? Kabut hitam pelarutan yang menguap dari tubuh orang-orang Aram."
  },
  AvgDialog_45418_Content_36 = {
    Text = "Aram berbeda dari manusia biasa, pada dasarnya mereka semua adalah keturunan Pohon Ibu."
  },
  AvgDialog_45418_Content_37 = {
    Text = "Jika Pohon Ibu sepenuhnya terlarut, yang akan hilang bukan hanya kemampuan mereka untuk berkembang biak, tetapi juga seluruh garis keturunan Alan yang ada."
  },
  AvgDialog_45418_Content_38 = {
    Text = "Jadi, orang Aram harus menembus Dinding Badai untuk membuat Pohon Ibu dilahirkan kembali."
  },
  AvgDialog_45418_Content_39 = {
    Text = "Saya tidak tahu apa alasan Mythag mengirim seseorang ke Remwasi, tetapi berdasarkan kepercayaan yang telah kita bangun, saya akan memberi tahu kalian Rahasia terdalam Alan."
  },
  AvgDialog_45418_Content_4 = {
    Text = "Sebuah cakar raksasa transparan merobek udara, menembus dinding luar yang longgar. Casiah melompat ke atasnya, dan cakar raksasa itu mengangkat gadis itu, lalu melarikan diri menuju lautan pasir di kejauhan."
  },
  AvgDialog_45418_Content_40 = {
    Text = "Jika ritual ini berhasil dihentikan, semua orang Aram yang kalian temui di Remwasi sejauh ini akan mati, tanpa terkecuali."
  },
  AvgDialog_45418_Content_41 = {
    Text = "William, yang menerima pesan, sekali lagi tiba di kemah pada larut malam."
  },
  AvgDialog_45418_Content_42 = {
    Text = "Ramona sudah tidur?"
  },
  AvgDialog_45418_Content_43 = {
    Text = "Hmm, tubuhku terasa sangat panas."
  },
  AvgDialog_45418_Content_44 = {
    Text = "Apa pendapatmu tentang hal yang berkaitan dengan Esensi Keinginan?"
  },
  AvgDialog_45418_Content_45 = {
    Text = "Aku tidak tahu."
  },
  AvgDialog_45418_Content_46 = {
    Text = "Seharusnya sudah terpikirkan saat mendengar tentang pesta api unggun yang tidak wajar itu."
  },
  AvgDialog_45418_Content_47 = {
    Text = "Metode reproduksi ini memang berbeda dari cara umum yang dilakukan oleh orang Kadath."
  },
  AvgDialog_45418_Content_48 = {
    Text = "Lagipula, Ramona terus mengalami demam sejak kedatangannya di Remwah."
  },
  AvgDialog_45418_Content_49 = {
    Text = "Apa ini juga ada hubungannya?"
  },
  AvgDialog_45418_Content_5 = {
    Text = "Sampai bertemu lagi!"
  },
  AvgDialog_45418_Content_50 = {
    Text = "Saya punya sebuah dugaan..."
  },
  AvgDialog_45418_Content_51 = {
    Text = "Kamu pernah melihat Tawil dan mengetahui keberadaan <Blue:Ramona-loop>. Hubungannya dengan Tawil seharusnya sudah kamu ketahui sedikit banyak."
  },
  AvgDialog_45418_Content_52 = {
    Text = "Kekuatan dari tiga protoplasma akan saling menolak. Sumber air minum Lermwah berasal dari garis keturunan protoplasma keinginan, yang bagi Ramona pada dasarnya adalah racun."
  },
  AvgDialog_45418_Content_53 = {
    Text = "Semakin maju ke depan, semakin dekat dengan tempat asal Sungai Suci, pengaruh penolakan ini menjadi semakin intens."
  },
  AvgDialog_45418_Content_54 = {
    Text = "Aram akan mencoba menembus Dinding Badai lagi besok."
  },
  AvgDialog_45418_Content_55 = {
    Text = "Ramona harus tetap berada di luar Dinding Badai."
  },
  AvgDialog_45418_Content_56 = {
    Text = "Jalan selanjutnya akan ditempuh oleh kami bertiga."
  },
  AvgDialog_45418_Content_57 = {
    Text = "Tidak mungkin, aku juga anggota Mythag, tidak mungkin…"
  },
  AvgDialog_45418_Content_58 = {
    Text = "Ramona dengan susah payah bangkit dari kasur, bergoyang sejenak, hampir jatuh kembali."
  },
  AvgDialog_45418_Content_59 = {
    Text = "Ramona, kondisi tubuhmu tidak cocok untuk bersama kami."
  },
  AvgDialog_45418_Content_6 = {Text = "Hai——"},
  AvgDialog_45418_Content_60 = {
    Text = [[
Kamu menarik selimutnya hingga ke dagu.
Gadis yang terguncang oleh gelombang panas itu gemetar dan memberimu tatapan tajam tanpa mengatakan apa pun.]]
  },
  AvgDialog_45418_Content_61 = {
    Text = "Kalian jangan meninggalkan aku sendirian..."
  },
  AvgDialog_45418_Content_7 = {
    Text = "Biarkan mereka pergi, sisa pohon suci masih ada di sini, mungkin ini adalah trik untuk mengelabui harimau dari gunung."
  },
  AvgDialog_45418_Content_8 = {
    Text = "Casiah menggoyangkan labu yang penuh dengan cairan hitam kental di tangannya."
  },
  AvgDialog_45418_Content_9 = {
    Text = "Apa ini sudah cukup? Aku bisa mengangkat peti mati itu juga."
  },
  AvgDialog_45419_Content_1 = {
    Text = "Patung raksasa dari Para pematung jatuh dengan keras, udara dipenuhi dengan bau karat yang menyengat."
  },
  AvgDialog_45419_Content_10 = {
    Text = "Di wilayah Aran, hal terpenting mungkin tidak ditentukan oleh kalian semua."
  },
  AvgDialog_45419_Content_11 = {
    Text = [[
Suara kemarahan bergema di ruang pabrik yang kosong. 
 Kepala suku Aran memimpin puluhan tentara Aran, sepenuhnya mengepung kalian di reruntuhan ini.]]
  },
  AvgDialog_45419_Content_12 = {
    Text = "Prajurit yang kalian sembunyikan di luar pabrik entah kapan melepaskan ikatannya, mengikuti di belakangnya dan menunjuk ke arah tempat kalian berada."
  },
  AvgDialog_45419_Content_13 = {
    Text = "Saya rasa, kita sudah tidak punya ruang untuk bernegosiasi lagi, orang asing."
  },
  AvgDialog_45419_Content_2 = {
    Text = "…Kerangka tidak berada di sini."
  },
  AvgDialog_45419_Content_3 = {
    Text = "Tidak, dulu pernah di sini."
  },
  AvgDialog_45419_Content_4 = {
    Text = [[
Ujung jari Ryker menyentuh permukaan tanah dengan lembut, mengangkat tangan lalu meremas-remasnya, dan meniupnya.
Debu Dispersi dari sarung tangan hitam, melayang-layang dalam cahaya yang masuk melalui kusen jendela.]]
  },
  AvgDialog_45419_Content_5 = {
    Text = "Ketebalan debu tidak merata, dan masih ada jejak kaki yang bisa dibedakan dengan jelas."
  },
  AvgDialog_45419_Content_6 = {
    Text = [[
Bayangan yang memasuki jendela yang pecah jatuh pada platform semen yang masih menyisakan jejak kontur peti mati. 
Namun, peti mati itu sudah lenyap tanpa jejak.]]
  },
  AvgDialog_45419_Content_7 = {
    Text = "Kita seharusnya memikirkan—Nyonya Narsis tidak akan puas hanya menjual informasi dengan satu harga."
  },
  AvgDialog_45419_Content_8 = {
    Text = "Mungkin dia harus menawarkan harga eksklusif untuk pembelian penuh?"
  },
  AvgDialog_45419_Content_9 = {
    Text = "Simpan humor berlebihanmu, yang terpenting sekarang adalah keberadaan kerangka Pohon Ibu."
  },
  AvgDialog_45420_Content_1 = {
    Text = "Tuan Alva, izinkan saya berbicara beberapa kata dengan {Male=dia,Female=dia}."
  },
  AvgDialog_45420_Content_10 = {
    Text = "Ekspresinya tampak luar biasa bersemangat, kecepatan bicaranya sangat cepat, tubuhnya tanpa sadar condong ke depan, dan matanya seperti hantu."
  },
  AvgDialog_45420_Content_11 = {
    Text = "Selamat tinggal, Mata Buta."
  },
  AvgDialog_45420_Content_13 = {
    Text = "Tidak, ini belum berakhir. Karena orang itu pernah dengan suara paling penuh semangat, meminta kamu untuk memanggil namanya."
  },
  AvgDialog_45420_Content_14 = {
    Text = "Mengingat tatapan Thais, kamu mengaktifkan Kunci perak."
  },
  AvgDialog_45420_Content_15 = {
    Text = "Benang perak bergoyang, menarik, dan mencari..."
  },
  AvgDialog_45420_Content_16 = {
    Text = "Di ujung benang itu, tidak ada apa pun."
  },
  AvgDialog_45420_Content_17 = {
    Text = "Fenomena yang disebut Pelarutan sepenuhnya menelan dirinya, bahkan kamu tidak dapat menemukan jejaknya."
  },
  AvgDialog_45420_Content_18 = {
    Text = "Apakah kau masih berharap dia akan kembali? Orang-orang Aram sudah tunduk padaku."
  },
  AvgDialog_45420_Content_19 = {
    Text = "Thais… Thais!"
  },
  AvgDialog_45420_Content_2 = {
    Text = "Saat kamu dan Alva saling berhadapan tanpa ada yang mengalah, Juliette bersuara untuk menghentikan kalian."
  },
  AvgDialog_45420_Content_20 = {
    Text = "Jika dia bisa muncul, jika dia bisa dengan kekuatan ilahi-Nya, menunjukkan masa depan bangsa Aran kepada Alva."
  },
  AvgDialog_45420_Content_21 = {
    Text = "Bahkan jika hanya mengeluarkan suara untuk membela diri, kamu tidak perlu berada di sini, berhadapan dengan pedang Alva."
  },
  AvgDialog_45420_Content_22 = {
    Text = "Thais… Thais—!"
  },
  AvgDialog_45420_Content_23 = {
    Text = "Tidak peduli seberapa sering kamu memanggil, itu tidak akan membantu. Percakapan terakhirmu dengannya berakhir pada tuduhan yang kamu lontarkan kepadanya."
  },
  AvgDialog_45420_Content_24 = {
    Text = "Keberadaan yang sudah terkikis oleh Pelarutan, tanpa jejak kontak dari Perak, mustahil bagimu untuk menyentuh sedikit pun keberadaannya."
  },
  AvgDialog_45420_Content_26 = {
    Text = "Apa, perjalanan sebelumnya membuatmu terlalu sombong?"
  },
  AvgDialog_45420_Content_27 = {
    Text = "Atau setelah meninggalkanku, apakah kamu menjadi orang yang menangis tersedu-sedu dan tak berguna?"
  },
  AvgDialog_45420_Content_28 = {
    Text = "Bagaimanapun juga, meskipun kamu kehilangan semua temanmu, kamu tetap berhasil sampai di sini seorang diri. Keteguhan seperti ini patut dihargai."
  },
  AvgDialog_45420_Content_29 = {
    Text = "Jadi, aku akan meminjamkan kekuasaanku padanya dan juga padamu."
  },
  AvgDialog_45420_Content_3 = {
    Text = "Karena kamu memaksa seperti ini."
  },
  AvgDialog_45420_Content_30 = {
    Text = "Ketenangan gurun dilanggar oleh suara angin yang mendesak, langit dengan cepat menjadi gelap, seolah-olah semua warna terang telah dilahap oleh amukan badai yang akan datang."
  },
  AvgDialog_45420_Content_31 = {
    Text = "Badai pasir bagaikan binatang raksasa yang marah, meraung dan menyapu dengan kekuatan penuh, mengangkat jutaan ton pasir halus, menutupi langit dan matahari, membuat panas terik serta birunya langit lenyap sepenuhnya."
  },
  AvgDialog_45420_Content_32 = {
    Text = "Di tengah keganasan kekuatan alam ini, sebuah sosok raksasa tampak samar-samar, berkilauan tak menentu di antara debu pasir."
  },
  AvgDialog_45420_Content_33 = {
    Text = "Dinding Badai…"
  },
  AvgDialog_45420_Content_34 = {
    Text = "Dinding Badai adalah sesuatu yang pada awalnya kupanggil menggunakan kekuasaanku."
  },
  AvgDialog_45420_Content_35 = {
    Text = "Apakah kamu... Thais...?"
  },
  AvgDialog_45420_Content_36 = {
    Text = "Sepertinya ia memiliki kekuatan tanpa batas. Seiring dengan tarian gila pasir, bayangannya melompat dan berkelok, seperti seekor monster gurun kuno yang sedang mencari mangsa di tengah badai debu."
  },
  AvgDialog_45420_Content_37 = {
    Text = "Bentuknya sangat besar dan menakutkan, kepala yang besar dan berkelok, cakar serta taring yang tajam, dan empat kaki yang berat, semuanya samar-samar terlihat di tengah debu yang beterbangan."
  },
  AvgDialog_45420_Content_38 = {
    Text = "Memanggilnya seperti itu juga tidak bisa dianggap salah."
  },
  AvgDialog_45420_Content_39 = {
    Text = "Namun, aku bukanlah ratu yang kau harapkan."
  },
  AvgDialog_45420_Content_4 = {
    Text = "Penjaga, jangan biarkan mereka melukai Tuan Utusan sedikit pun."
  },
  AvgDialog_45420_Content_40 = {
    Text = "Jika kamu ingin meminjam kekuatanku, bacalah nama suciku dengan lantang.\nAku adalah esensi dari nafsu ——"
  },
  AvgDialog_45420_Content_41 = {
    Text = "Bayangan besar dan aneh itu perlahan memudar, sosok yang selalu kamu rindukan muncul dari badai pasir yang menderu."
  },
  AvgDialog_45420_Content_42 = {
    Text = "Kerikil berderu dan menari liar tanpa ampun di sekitar tubuhnya, namun sedikit pun tidak menggoyahkan langkahnya."
  },
  AvgDialog_45420_Content_44 = {
    Text = "Ratu! Ratu telah kembali!"
  },
  AvgDialog_45420_Content_45 = {
    Text = "Ratu, pandangan Ratu terus tertuju pada kita!"
  },
  AvgDialog_45420_Content_46 = {
    Text = "Matanya terus tertuju pada Alan, menatap masa lalu dan masa depan yang mengalir dalam darahnya."
  },
  AvgDialog_45420_Content_47 = {
    Text = "Thais... Tuan..."
  },
  AvgDialog_45420_Content_48 = {
    Text = "Semua etnis Alan dengarkan baik-baik! Ramalan kuno telah digenapi, Pohon Ibu muncul kembali di dunia, dan kita harus memahkotai mereka yang telah tiada!"
  },
  AvgDialog_45420_Content_49 = {
    Text = "Ratu kembali melangkah di atas pasir, kembali ke Takhta!"
  },
  AvgDialog_45420_Content_5 = {Text = "Baik!"},
  AvgDialog_45420_Content_50 = {
    Text = "Kepada satu-satunya Ratu Aran, Yang Mulia Thais——"
  },
  AvgDialog_45420_Content_51 = {
    Text = "Persembahkan kesetiaan dan tekad kalian!"
  },
  AvgDialog_45420_Content_6 = {
    Text = "Juliette mendekat, berbisik padamu dari jarak satu lengan."
  },
  AvgDialog_45420_Content_7 = {
    Text = "Kembali ke Sungai Suci adalah takdir orang Aram. Aku hanya membantu mempercepat prosesnya sedikit."
  },
  AvgDialog_45420_Content_8 = {
    Text = "Ketika pandangan-Nya meliputi seluruh Kadath, mereka akan menyatu dengan Sungai Suci ke dalam dunia baru."
  },
  AvgDialog_45420_Content_9 = {
    Text = "Bukankah ini sudah menjadi kehendakmu sendiri?"
  },
  AvgDialog_45421_Content_1 = {
    Text = "Siapa di sana?!"
  },
  AvgDialog_45421_Content_2 = {
    Text = "Astaga, di depan ada penyergapan, di belakang ada pasukan pengejar."
  },
  AvgDialog_45421_Content_3 = {
    Text = "Kita tidak boleh membiarkan tentara Aran menemukan kita."
  },
  AvgDialog_45421_Content_4 = {
    Text = "Sepertinya, kita tidak punya pilihan lain selain terus maju?"
  },
  AvgDialog_45422_Content_1 = {
    Text = [[
Agak merepotkan. Kami tidak tahu di mana kerangka berada. 
 Lorong di dalam pabrik sangat rumit, banyak sekat, dan jika kita mencari satu per satu, entah kapan akan selesai.]]
  },
  AvgDialog_45422_Content_10 = {
    Text = "Kalian bersembunyi di tempat gelap dan bantu, jangan muncul! Aku akan mengikat mata mereka!"
  },
  AvgDialog_45422_Content_2 = {
    Text = "Saya punya sebuah trik kecil."
  },
  AvgDialog_45422_Content_3 = {
    Text = "Kita cari seorang prajurit Aran, ikat dia, lalu tanyai semuanya."
  },
  AvgDialog_45422_Content_4 = {
    Text = "Lalu? Apakah kamu berniat menguburnya di pasir untuk membungkamnya, atau membiarkan mereka pergi dan menjadikan kita buronan nomor satu di Arlan?"
  },
  AvgDialog_45422_Content_5 = {
    Text = "Astaga, aku benar-benar tidak memikirkan ini. Sungguh kelalaian besar."
  },
  AvgDialog_45422_Content_6 = {
    Text = [[
Kesalahannya diungkapkan dengan nada ringan, tampaknya dia tidak terlalu mempedulikannya. 
 Dari intonasi suaranya yang ambigu, kamu bisa merasakan bahwa dia masih menyimpan sesuatu di balik itu.]]
  },
  AvgDialog_45422_Content_7 = {
    Text = "Adakah cara untuk tidak membocorkan identitas kita, namun tetap bisa mendapatkan petunjuk?"
  },
  AvgDialog_45422_Content_8 = {
    Text = "Bukankah ini sangat mudah?"
  },
  AvgDialog_45422_Content_9 = {
    Text = "Ryker melepas patch aroma dari sarung tangannya, sepasang murid yang berkilauan dengan cahaya hijau berkedip dalam kegelapan."
  },
  AvgDialog_45423_Content_1 = {
    Text = "Tidak, tidak mungkin, Dinding badai sama sekali tidak berujung!"
  },
  AvgDialog_45423_Content_2 = {
    Text = "Kita tidak mungkin bisa masuk ke Dinding Badai, Sang Ratu sudah meninggalkan kita!"
  },
  AvgDialog_45423_Content_3 = {
    Text = "Ratu sudah lama meninggalkan kita!"
  },
  AvgDialog_45423_Content_4 = {
    Text = "Teriakan dan ratapan terus terdengar di sekitar."
  },
  AvgDialog_45424_Content_1 = {
    Text = "Ratu, semoga Ratu melindungi kita!"
  },
  AvgDialog_45424_Content_2 = {
    Text = "Ratu melindungi Aran!"
  },
  AvgDialog_45424_Content_3 = {
    Text = "<Small:Thais memang tidak ada di sini…>"
  },
  AvgDialog_45424_Content_4 = {
    Text = "Nubia semakin banyak berkumpul!"
  },
  AvgDialog_45424_Content_5 = {
    Text = "Tidak ada jalan lain, kita hanya bisa maju bersama orang-orang gila ini!"
  },
  AvgDialog_45425_Content_1 = {Text = "Judii"},
  AvgDialog_45425_Content_10 = {
    Text = "Kamu membuka kedua matamu. Selain warna langit di luar tenda yang sudah terang benderang, segalanya tetap seperti saat sebelum kamu tidur."
  },
  AvgDialog_45425_Content_11 = {
    Text = [[
Saya mengerti. 
Jawabannya adalah motivasi.]]
  },
  AvgDialog_45425_Content_12 = {
    Text = "Jika semua ini adalah perbuatan Gereja Penerang Kuil, dia tidak perlu meninggalkan penerang kuil ini di dalam tubuh Nubia."
  },
  AvgDialog_45425_Content_13 = {
    Text = "Berdasarkan apa yang kita lihat sepanjang perjalanan ini, saya pikir pelakunya hanya bisa jadi —"
  },
  AvgDialog_45425_Content_14 = {
    Text = "Cakar serigala merobek tirai, pesulap yang berjalan dengan hati-hati dan lautan pasir tanpa batas muncul bersamaan di lubang sobekan tenda."
  },
  AvgDialog_45425_Content_15 = {
    Text = "Para pematung asosiasi yang kedua."
  },
  AvgDialog_45425_Content_16 = {
    Text = "Haiya haiya, ketahuan ya? Aku masih ingin mendengarkan lebih lama lagi."
  },
  AvgDialog_45425_Content_17 = {
    Text = "Nada suaranya ringan dan ceria, tanpa sedikit pun rasa tegang meskipun upaya penyadapan gagal."
  },
  AvgDialog_45425_Content_18 = {
    Text = "Casiah, kamu——"
  },
  AvgDialog_45425_Content_19 = {
    Text = "Sebelumnya sudah kukatakan, setiap kesalahan pasti ada pelakunya. Orang itu bukan aku, jadi kalian tidak bisa menyalahkan aku."
  },
  AvgDialog_45425_Content_2 = {
    Text = "Kamu kembali ke tenda dengan lelah. Ryker duduk diam di sudut tenda, satu tangan menopang dagu, tenggelam dalam pikiran."
  },
  AvgDialog_45425_Content_20 = {
    Text = "Misi saya hanya satu, membawa orang ini ——"
  },
  AvgDialog_45425_Content_21 = {
    Text = "Dia menunjuk ke arahmu."
  },
  AvgDialog_45425_Content_22 = {
    Text = "Dikemas untuk dipersembahkan kepada seorang tuan yang terhormat."
  },
  AvgDialog_45425_Content_3 = {
    Text = "Besok mungkin akan ada pertempuran besar. Kenapa kamu masih belum beristirahat?"
  },
  AvgDialog_45425_Content_4 = {
    Text = [[
Kamu tidur dulu saja. 
 Intuisiku mengatakan bahwa masih ada teka-teki di "tempat kejadian perkara" ini.]]
  },
  AvgDialog_45425_Content_5 = {
    Text = "Kamu begitu lelah sehingga bergegas mencuci muka dan beristirahat."
  },
  AvgDialog_45425_Content_6 = {
    Text = "Malam yang penuh kekacauan, tak terhitung wajah-wajah yang familiar namun asing muncul dalam memori Anda. Mereka samar-samar, serak, dan menyeramkan, satu per satu memanggil nama Anda."
  },
  AvgDialog_45425_Content_7 = {
    Text = "Aku ingin tetap hidup..."
  },
  AvgDialog_45425_Content_8 = {
    Text = "<RedBig:Aku ingin tetap hidup…>"
  },
  AvgDialog_45425_Content_9 = {Text = "Cukup!"},
  AvgDialog_45426_Content_1 = {
    Text = "Cium perpisahan"
  },
  AvgDialog_45426_Content_10 = {
    Text = "Kamu menarik napas dalam-dalam, tepat saat hendak kembali ke tenda, tiba-tiba Thais melambaikan tangan padamu dari belakang tenda."
  },
  AvgDialog_45426_Content_100 = {
    Text = "Namun, darah Aran terlalu bergantung pada kekuatan Pohon Ibu yang berlimpah."
  },
  AvgDialog_45426_Content_101 = {
    Text = "Ketergantungan ini seperti menara pasir yang rapuh, tampak kokoh, namun cukup satu kali hempasan ombak untuk sepenuhnya runtuh."
  },
  AvgDialog_45426_Content_102 = {
    Text = "Meskipun hanya ada sedikit harapan, bahkan yang paling kecil dan samar, aku tidak bisa begitu saja membiarkan mereka menyerah."
  },
  AvgDialog_45426_Content_103 = {
    Text = "Aku tidak mengerti lagi..."
  },
  AvgDialog_45426_Content_104 = {
    Text = "Agar perpisahan tidak terlalu menyedihkan, pertemuan kembali menjadi sangat berharga... Kamu tak perlu mengerti."
  },
  AvgDialog_45426_Content_105 = {
    Text = "Namun, kamu pasti akan bersama mereka mencapai akhir dari perjalanan ini."
  },
  AvgDialog_45426_Content_106 = {
    Text = "Kamu kehilangan kata-kata untuk sesaat."
  },
  AvgDialog_45426_Content_107 = {
    Text = "Pada saat itu... harap pastikan untuk memanggil namaku."
  },
  AvgDialog_45426_Content_108 = {
    Text = "Dia mencium dahimu dengan lembut."
  },
  AvgDialog_45426_Content_109 = {
    Text = "Kamu tersadar sejenak, dia melangkah beberapa kali, kamu mengulurkan tanganmu, namun tak bisa menyentuhnya."
  },
  AvgDialog_45426_Content_11 = {
    Text = "Besok adalah upacara kebangkitan Pohon Ibu. \n Ada apa, Yang Mulia Ratu mencari saya pada saat seperti ini…?"
  },
  AvgDialog_45426_Content_110 = {
    Text = "Kamu mengamati sosoknya yang semakin menjauh dan mengecil, hingga akhirnya sekecil butiran pasir, menghilang di bawah cahaya bulan yang terang."
  },
  AvgDialog_45426_Content_12 = {
    Text = "Begitu kata-kata keluar, kamu menyadari bahwa nada suaramu tidak ramah."
  },
  AvgDialog_45426_Content_13 = {
    Text = [[
Saya... melihatnya. 
 Mengenai temanmu... aku turut berduka.]]
  },
  AvgDialog_45426_Content_14 = {
    Text = "Keheningan yang tak terelakkan mengambang di antara kalian."
  },
  AvgDialog_45426_Content_15 = {
    Text = "Ini tidak ada hubungannya dengan Aran."
  },
  AvgDialog_45426_Content_16 = {
    Text = "Ini bukan kesalahan Thais. Kamu mengingatkan diri sendiri dalam hati, tetapi kata-kata yang terucap masih seperti landak yang waspada di padang pasir."
  },
  AvgDialog_45426_Content_17 = {
    Text = "Upacara kebangkitan Pohon Ibu... kamu pasti juga punya persiapan yang harus dilakukan, kan?"
  },
  AvgDialog_45426_Content_18 = {
    Text = "Kamu mencoba memperbaikinya, tetapi kata-kata yang terucap tetap terdengar seperti penolakan yang dingin."
  },
  AvgDialog_45426_Content_19 = {
    Text = "Menurutmu, setelah Pohon Ibu hidup kembali, ke mana Suku Alan akan pergi?"
  },
  AvgDialog_45426_Content_2 = {
    Text = [[
Dalam perjalanan ini, kamu telah menyaksikan banyak orang pergi. 
Namun, tak satu pun kematian terasa begitu menyesakkan dengan nada yang begitu ringan.]]
  },
  AvgDialog_45426_Content_20 = {
    Text = "Kamu terdiam."
  },
  AvgDialog_45426_Content_21 = {
    Text = "Saya tahu tujuan Mythag datang ke Remwasi, dan saya juga tahu mengapa kalian belum bertindak."
  },
  AvgDialog_45426_Content_22 = {
    Text = "Saya sangat berterima kasih kepada kalian karena telah memberikan Alan sebuah kesempatan."
  },
  AvgDialog_45426_Content_23 = {
    Text = "Namun, kesempatan itu sudah tidak ada lagi."
  },
  AvgDialog_45426_Content_24 = {
    Text = "Thais, apakah kamu tahu bahwa Pohon Ibu sudah tercemar oleh pelarutan?"
  },
  AvgDialog_45426_Content_26 = {
    Text = "Aku tahu, aku... sudah mengetahuinya sejak lama."
  },
  AvgDialog_45426_Content_27 = {
    Text = "Jadi, kamu seharusnya tahu bahwa Mythag tidak akan membiarkan penyebaran Pelarutan terus berlanjut."
  },
  AvgDialog_45426_Content_28 = {
    Text = [[
Aku akan menghentikan kelahiran Pohon Ibu.
Thais, kita sudah menjadi musuh.]]
  },
  AvgDialog_45426_Content_29 = {
    Text = "Angin yang awalnya segar di lautan pasir tiba-tiba berubah menjadi kental dan lengket. Debu yang terhirup seakan menggores tenggorokanmu, membuat leher terasa nyeri."
  },
  AvgDialog_45426_Content_3 = {
    Text = "Apalagi itu William —\n Penyelidik legendaris Mythag, pembimbingmu di jalan menjadi seorang Penyelidik."
  },
  AvgDialog_45426_Content_30 = {
    Text = "Yang membuatmu terkejut, Thais tidak menghindar, melainkan mendekat dan memelukmu."
  },
  AvgDialog_45426_Content_31 = {
    Text = "Anak baik, aku bisa memahami pemikiranmu."
  },
  AvgDialog_45426_Content_32 = {
    Text = "Saya tidak berniat untuk memberikan kerusakan kepada kalian, apalagi melakukan sesuatu yang merugikan kepentingan bangsa Alan."
  },
  AvgDialog_45426_Content_33 = {
    Text = "Namun, orang Aram tidak memiliki pilihan. Beberapa tahun yang lalu, kekuatan ilahi sang ratu sudah mulai melemah, bahkan menjaga Pohon Ibu pun menjadi sulit."
  },
  AvgDialog_45426_Content_34 = {
    Text = "Hanya bisa meminjam kekuatan vena bumi dari Leremwah untuk menutupi keberadaan Pohon Ibu dengan Dinding Badai."
  },
  AvgDialog_45426_Content_35 = {
    Text = "Maksudmu... Dinding Badai, dipanggil oleh kekuatan Ratu?"
  },
  AvgDialog_45426_Content_36 = {
    Text = "Ya. Dinding badai… akan menolak utusan palsu."
  },
  AvgDialog_45426_Content_37 = {
    Text = "Namun, setiap kali upacara diadakan, banyak orang Aram yang mati!"
  },
  AvgDialog_45426_Content_38 = {
    Text = "Selama kekuatan regenerasi masih ada, suku Alan tidak akan punah."
  },
  AvgDialog_45426_Content_39 = {
    Text = "Jadi, apakah kamu membiarkan mereka melakukan ritual terkutuk seperti itu, membiarkan mereka terjebak berulang kali di Dinding Badai?"
  },
  AvgDialog_45426_Content_4 = {
    Text = "Siapa yang bisa membunuh seorang Penyelidik legendaris secara diam-diam dari jarak sedekat itu?"
  },
  AvgDialog_45426_Content_40 = {
    Text = "Ini adalah takdir bangsa Aram, kami dilahirkan di sini, tumbuh di sini."
  },
  AvgDialog_45426_Content_41 = {
    Text = "Begitu banyak orang telah mengorbankan hidup mereka untuk keyakinan sakitmu ini!"
  },
  AvgDialog_45426_Content_42 = {
    Text = "Sekarang, bukan hanya orang-orang dari sukumu, tetapi juga Kak William…"
  },
  AvgDialog_45426_Content_43 = {
    Text = "Nada akhir suaramu terdengar sedikit tercekat, hampir tak bisa kau kenali sebagai suaramu sendiri."
  },
  AvgDialog_45426_Content_44 = {
    Text = "Katakan padaku, Thais, kau tidak benar-benar berpikir seperti itu, kan?"
  },
  AvgDialog_45426_Content_45 = {
    Text = "Thais tidak menjawab pertanyaanmu."
  },
  AvgDialog_45426_Content_46 = {
    Text = "Dia hanya menarik lengan bajunya lebih erat."
  },
  AvgDialog_45426_Content_47 = {
    Text = "Aku tahu kamu sangat lelah, sangat marah…"
  },
  AvgDialog_45426_Content_48 = {
    Text = [[
Kamu memiliki rasa dendam dan ketidakpahaman terhadapku. 
Namun, aku juga punya alasan tersendiri.]]
  },
  AvgDialog_45426_Content_49 = {
    Text = "Aku akan menceritakan sebuah cerita kepadamu, sebuah cerita yang sangat, sangat panjang."
  },
  AvgDialog_45426_Content_5 = {
    Text = "Kamu terhuyung lemah mundur dua langkah, lalu menabrak sebuah sosok tinggi besar."
  },
  AvgDialog_45426_Content_50 = {
    Text = "Pada zaman dahulu kala, ribuan tahun sebelum terjadinya banjir besar, ada sebuah peradaban yang memuja dewa yang disebut Pohon Ibu."
  },
  AvgDialog_45426_Content_51 = {
    Text = "Namun, kehendak Pohon Ibu tidak dapat mengokohkan pemerintahan kekaisaran, maka mereka pun merancang sebuah rencana."
  },
  AvgDialog_45426_Content_52 = {
    Text = "Mereka memilih banyak gadis, memaksa mereka meminum susu merah segar dari Pohon Ibu, dan mandi dalam cairan pohon tersebut hingga gadis-gadis itu menyatu dengan pohon."
  },
  AvgDialog_45426_Content_53 = {
    Text = "Sejak saat itu, gadis yang seperti boneka tersebut mewakili kehendak pohon."
  },
  AvgDialog_45426_Content_54 = {
    Text = "Namun, tak seorang pun pernah mendengar suaranya atau menaati perkataannya. Karena gadis itu tidak memiliki suara maupun kehendaknya sendiri. Apa yang ia sampaikan hanyalah kata-kata yang diperintahkan oleh Raja Nineveh untuk dihafal dan diucapkan kembali."
  },
  AvgDialog_45426_Content_55 = {
    Text = "Pada usia lima belas tahun, gadis itu mulai menentang dengan suaranya."
  },
  AvgDialog_45426_Content_56 = {
    Text = "Kenapa? Kenapa harus membunuhnya, dia kan ayah Ameyette!"
  },
  AvgDialog_45426_Content_57 = {
    Text = "Dia melanggar Tabu, Thais. Dia melarikan diri di medan perang."
  },
  AvgDialog_45426_Content_58 = {
    Text = "Pertempuran itu telah berakhir dengan kekalahan total, hanya dia yang selamat. Dia tidak mungkin melawan begitu banyak musuh seorang diri!"
  },
  AvgDialog_45426_Content_59 = {
    Text = "Masalah perang, kamu masih terlalu muda untuk mengerti, Thais."
  },
  AvgDialog_45426_Content_6 = {
    Text = "Saya mengerti kesulitanmu sekarang, tapi ini bukan saatnya untuk menunjukkan kelemahan."
  },
  AvgDialog_45426_Content_60 = {
    Text = "Dia harus maju tanpa ragu, lalu mati dengan penuh kehormatan."
  },
  AvgDialog_45426_Content_61 = {
    Text = "Bukankah lebih baik jika satu orang bisa bertahan hidup? Selama satu orang tetap hidup... Ameyet bisa menjadi pejuang, adik Ameyet juga bisa menjadi pejuang, begitu pula anak-anak Ameyet di masa depan..."
  },
  AvgDialog_45426_Content_62 = {
    Text = "Lagi pula, berbicara pun tidak ada gunanya."
  },
  AvgDialog_45426_Content_63 = {
    Text = "Menyampaikan kehendak Pohon Ibu, orang berdosa harus menerima hukuman dimakan serangga."
  },
  AvgDialog_45426_Content_64 = {
    Text = "Saya tidak mengatakannya!"
  },
  AvgDialog_45426_Content_65 = {
    Text = "Menyampaikan kehendak Pohon Ibu, orang berdosa harus menerima hukuman dimakan serangga."
  },
  AvgDialog_45426_Content_66 = {
    Text = "Saya tidak mengatakannya!"
  },
  AvgDialog_45426_Content_67 = {
    Text = "Mewarisi kehendak Pohon Ibu…"
  },
  AvgDialog_45426_Content_68 = {
    Text = "Tidak, jangan…!"
  },
  AvgDialog_45426_Content_69 = {
    Text = "Orang berdosa pantas menerima hukuman cacing menggigit."
  },
  AvgDialog_45426_Content_7 = {
    Text = "Dia… meninggalkan informasi kunci untuk kita."
  },
  AvgDialog_45426_Content_70 = {
    Text = "Tangisan putus asa dan lantang seorang gadis, tak seorang pun yang mendengarnya."
  },
  AvgDialog_45426_Content_71 = {
    Text = "Kamu, siapa kamu?"
  },
  AvgDialog_45426_Content_72 = {
    Text = "Anak baik, pelan-pelan saja, dengarkan aku, cepat ikut aku pergi."
  },
  AvgDialog_45426_Content_73 = {
    Text = "Kamu bukan gadis pertama yang dijadikan boneka pohon. Setiap kali gadis itu melawan kehendak mereka, mereka akan melakukan pengorbanan terhadap gadis itu kepada Sungai suci."
  },
  AvgDialog_45426_Content_74 = {
    Text = "Aku dilahirkan dengan meminum susu Pohon Ibu, aku abadi!"
  },
  AvgDialog_45426_Content_75 = {
    Text = "Anak bodoh, mereka menipumu. Setiap orang yang melompat ke sungai pasti akan tenggelam."
  },
  AvgDialog_45426_Content_76 = {
    Text = "Saya tidak akan melakukannya."
  },
  AvgDialog_45426_Content_77 = {
    Text = "Pada akhirnya, siapa kamu? Aku belum pernah melihatmu sebelumnya."
  },
  AvgDialog_45426_Content_78 = {
    Text = "Saya bertugas membersihkan tamanmu dan akan pergi sebelum fajar setiap hari, jadi kamu belum pernah melihatku."
  },
  AvgDialog_45426_Content_79 = {
    Text = "Tapi kau mengenal cucuku... namanya Amayet."
  },
  AvgDialog_45426_Content_8 = {
    Text = [[
Di balik Nubia, ada Gereja Penerang Kuil.
Apa yang dikatakan Dafude'er memang benar, sepertinya menghentikan ritual sudah menjadi suatu keharusan.]]
  },
  AvgDialog_45426_Content_80 = {
    Text = "Apakah gadis itu sudah pergi?"
  },
  AvgDialog_45426_Content_81 = {Text = "Tidak."},
  AvgDialog_45426_Content_82 = {
    Text = "Gadis itu menyadari banyak hal dalam sekejap."
  },
  AvgDialog_45426_Content_83 = {
    Text = "Ternyata, taman yang kotor tidak akan membersihkan dirinya sendiri."
  },
  AvgDialog_45426_Content_84 = {
    Text = "Ternyata ada beberapa hal yang tampaknya ada, tetapi tak pernah terlihat."
  },
  AvgDialog_45426_Content_85 = {
    Text = "Ternyata tidak bisa mengeluarkan suara... rasanya begitu menyakitkan."
  },
  AvgDialog_45426_Content_86 = {
    Text = "…Pada hari upacara pengorbanan, dia secara sukarela melompat ke Sungai Suci."
  },
  AvgDialog_45426_Content_87 = {
    Text = "Pada saat itu, kehendak gadis dan pohon tersebut beresonansi dengan mendalam."
  },
  AvgDialog_45426_Content_88 = {
    Text = "Kemudian, kehendak pohon bertanya kepadanya:"
  },
  AvgDialog_45426_Content_89 = {
    Text = "Apakah kamu bersedia menjadi pembawa pohon, melahirkan Caro dan Jiwa pohon?"
  },
  AvgDialog_45426_Content_9 = {
    Text = "Di langit yang luas, bintang-bintang berkedip. Angin malam di gurun akhirnya membuat napas tersengal-sengal Anda kembali normal."
  },
  AvgDialog_45426_Content_90 = {
    Text = [[
Karena resonansi jiwa yang ajaib, gadis itu bisa mendengar suara pohon.
Pada malam itu, dia mengetahui tentang pengetahuan terkait <Red:Hari Kiamat Hitam>.]]
  },
  AvgDialog_45426_Content_91 = {
    Text = "Hari Kiamat Hitam... apakah itu merujuk pada Pelarutan?"
  },
  AvgDialog_45426_Content_92 = {
    Text = [[
Gadis itu kembali ke sisi pohon, namun tidak lagi menjalankan perintah raja. 
 Tidak... karena panggilan darah, semua rakyat hanya akan mengikuti kehendak pohon.]]
  },
  AvgDialog_45426_Content_93 = {
    Text = "Gadis adalah pohon, dan pohon adalah gadis. Dia lebih peduli tentang apakah seluruh spesiesnya dapat melarikan diri dari takdir kehancuran bersama dengan dunia, dibandingkan dengan kelangsungan hidupnya sendiri."
  },
  AvgDialog_45426_Content_94 = {
    Text = "Ketika kekaisaran runtuh, dia membawa sekelompok orang bersembunyi di kedalaman gurun yang paling terpencil, di tengah badai yang jarang dilalui manusia, hanya untuk menghindari pembantaian dan menyelamatkan garis keturunan terakhir."
  },
  AvgDialog_45426_Content_95 = {
    Text = "Ini adalah... suku nomaden Ailan?"
  },
  AvgDialog_45426_Content_96 = {
    Text = "Setelah waktu yang sangat lama, gadis itu menghilang sekali lagi."
  },
  AvgDialog_45426_Content_97 = {
    Text = "Masih belum ada yang mendengar suaranya, dan tak seorang pun lagi yang menyebut namanya."
  },
  AvgDialog_45426_Content_98 = {
    Text = "Namun, semua orang berusaha keras untuk berkembang biak guna menghindari hari kiamat sesuai dengan keinginannya…"
  },
  AvgDialog_45426_Content_99 = {
    Text = "Hanya untuk menyimpan \"benih\" kemakmuran saat kedatangan hari kiamat."
  },
  AvgDialog_45427_Content_1 = {Text = "Tari"},
  AvgDialog_45427_Content_10 = {
    Text = "Anak-anak akan melangkah di jalan mereka sendiri."
  },
  AvgDialog_45427_Content_100 = {
    Text = "Kamu mengikuti pandangan Thais, dan melihat Ramona berlari ke arahmu. Ryker mengikuti di belakangnya, langkahnya cepat namun mantap, tetap mempertahankan sikap anggun dan elegan."
  },
  AvgDialog_45427_Content_101 = {
    Text = "Jangan lupa, malam ini adalah rahasia yang hanya milik kita."
  },
  AvgDialog_45427_Content_102 = {
    Text = "Ketika berbalik lagi, sosok Thais menghilang, hanya angin yang menderu melewati gurun."
  },
  AvgDialog_45427_Content_103 = {
    Text = "Di depanmu, jejak hitam D-lendir meresap ke dalam pasir yang mengalir, menyatu dengan tanah."
  },
  AvgDialog_45427_Content_12 = {
    Text = "Kamu perlahan membuka mata, yang pertama kali terlihat adalah langit malam yang luas, cerah, dan penuh bintang."
  },
  AvgDialog_45427_Content_13 = {
    Text = "Bagaimana aku bisa... tertidur?"
  },
  AvgDialog_45427_Content_14 = {
    Text = "Setelah berjalan lama di padang pasir, kelelahan adalah hal yang sangat wajar."
  },
  AvgDialog_45427_Content_15 = {
    Text = "Saya masih memiliki banyak pertanyaan..."
  },
  AvgDialog_45427_Content_16 = {
    Text = "Mimpi yang panjang tampaknya telah membawamu menjauh dari perjalanan yang penuh ketegangan, satu per satu pertanyaan mulai muncul di benakmu."
  },
  AvgDialog_45427_Content_17 = {
    Text = "Mengapa air dalam kantung air Ramona berubah menjadi D-lendir?"
  },
  AvgDialog_45427_Content_18 = {
    Text = "Siapa sebenarnya yang menyebarkan Nubia?"
  },
  AvgDialog_45427_Content_19 = {
    Text = "Apa yang tersembunyi di dalam Dinding Badai?"
  },
  AvgDialog_45427_Content_2 = {
    Text = "▼▼Dalam kekacauan, tak seorang pun mengetahui akhirnya. \nApa yang akan terjadi terkandung dalam ucapanku, namun pendengaran dan penglihatan manusia telah lenyap, \nhanya mereka yang membisu tersebar di seluruh bumi."
  },
  AvgDialog_45427_Content_20 = {
    Text = "Apa tujuan utusan misterius Juliette?"
  },
  AvgDialog_45427_Content_21 = {
    Text = "Apa maksud dari ritual Alan?"
  },
  AvgDialog_45427_Content_22 = {
    Text = "Dan Thais, apakah Thais di depan mata ini benar-benar bisa dipercaya?"
  },
  AvgDialog_45427_Content_23 = {
    Text = "Sejak datang ke Lemuwah, insiden aneh terus terjadi tanpa henti, satu demi satu misteri mengejar hingga kamu sulit bernapas."
  },
  AvgDialog_45427_Content_24 = {
    Text = "Kamu perlu tenang, dan perlu berpikir."
  },
  AvgDialog_45427_Content_25 = {
    Text = "Tidak perlu dipikirkan, kamu sangat lelah dan butuh istirahat."
  },
  AvgDialog_45427_Content_26 = {
    Text = "Ketika berbalik, hanya ada satu bulan purnama yang menyinari wajah Thais yang halus dan lembut, memberikan kesan tembus cahaya."
  },
  AvgDialog_45427_Content_27 = {
    Text = "Di sisi lain Dinding Badai… semua pertanyaanmu akan terjawab."
  },
  AvgDialog_45427_Content_28 = {
    Text = "Di sisi lain Dinding Badai."
  },
  AvgDialog_45427_Content_29 = {
    Text = "Juliette juga mengatakan hal yang sama, apakah kamu harus mengikuti maksud orang di balik layar itu dan masuk ke dalam badai?"
  },
  AvgDialog_45427_Content_3 = {
    Text = "Data pemantauan Tawil secara bertahap menjadi stabil."
  },
  AvgDialog_45427_Content_30 = {
    Text = "Apakah ada semacam kekuatan gaib yang mendorong semua orang untuk berbondong-bondong menuju pusat badai seperti peziarah?"
  },
  AvgDialog_45427_Content_31 = {
    Text = "Pikiran terus berkecamuk, menanamkan Benih keraguan dan kecemasan di Laut Pikiran-mu."
  },
  AvgDialog_45427_Content_32 = {
    Text = "Apakah hatimu tidak pernah tenang?"
  },
  AvgDialog_45427_Content_33 = {
    Text = "Tutuplah matamu."
  },
  AvgDialog_45427_Content_34 = {
    Text = "Napas Thais hanya berjarak beberapa sentimeter dari Anda."
  },
  AvgDialog_45427_Content_35 = {
    Text = "Tutuplah mata"
  },
  AvgDialog_45427_Content_36 = {
    Text = "Menolak untuk menutup mata"
  },
  AvgDialog_45427_Content_37 = {
    Text = "Mata yang begitu jernih… sama sekali tidak menjadi keruh meski setelah perjalanan yang melelahkan ini."
  },
  AvgDialog_45427_Content_38 = {
    Text = "Thais meletakkan jari telunjuknya di bibir atas Anda."
  },
  AvgDialog_45427_Content_39 = {
    Text = "Wajahnya begitu dekat denganmu, cahaya bulan memberikan semburat lembut pada kulitnya."
  },
  AvgDialog_45427_Content_4 = {
    Text = "Kalian sudah bekerja keras selama ini."
  },
  AvgDialog_45427_Content_40 = {
    Text = "Kamu merasakan napas yang mendekat, lembut dan hangat."
  },
  AvgDialog_45427_Content_41 = {
    Text = "Benar-benar aroma yang membawa kenangan lama."
  },
  AvgDialog_45427_Content_42 = {
    Text = "Berapa lama kita tidak sedekat ini satu sama lain?"
  },
  AvgDialog_45427_Content_43 = {
    Text = "Terasa sentuhan dingin di bibir."
  },
  AvgDialog_45427_Content_44 = {
    Text = [[
Kamu membuka mata, jari telunjuk Thais menyentuh bibir kamu.
Wajahnya begitu dekat denganmu, cahaya bulan memberikan semburat cahaya lembut pada kulitnya.]]
  },
  AvgDialog_45427_Content_45 = {
    Text = "Apakah kamu tahu? Aku melihat Clades di matamu, melihat abu dari zaman purba, dan melihat napas alam semesta."
  },
  AvgDialog_45427_Content_46 = {
    Text = [[
Perjalanan yang kamu jalani sangat panjang, pasti sudah sangat lelah, kan?
Namun pandangan matamu tetap begitu teguh, tanpa sedikit pun keraguan.]]
  },
  AvgDialog_45427_Content_47 = {
    Text = "Bintang-bintang tidak dapat mengubahmu, dan Gurun Pasir mungkin juga tidak bisa."
  },
  AvgDialog_45427_Content_48 = {
    Text = "Saya tidak memahami maksudmu."
  },
  AvgDialog_45427_Content_49 = {
    Text = "Kamu belum perlu memahami sekarang."
  },
  AvgDialog_45427_Content_5 = {
    Text = [[
Selanjutnya, kita juga tidak boleh lengah. 
Selama lebih dari tiga ratus tahun, aktivitas aneh di Kolam Hitam belum pernah serumit tahun ini.]]
  },
  AvgDialog_45427_Content_50 = {
    Text = "Thais bangkit dan berjalan santai menuruni bukit pasir."
  },
  AvgDialog_45427_Content_51 = {
    Text = "Di bawah langit berbintang seperti ini, hanya duduk diam tanpa menikmati pemandangan sungguh terlalu tidak romantis."
  },
  AvgDialog_45427_Content_52 = {
    Text = "Angin menopang kain putih transparan yang ringan, dia melangkah dengan gemulai di atas pasir lembut."
  },
  AvgDialog_45427_Content_53 = {
    Text = "Izinkan aku mempersembahkan tarian Aran ini untukmu."
  },
  AvgDialog_45427_Content_54 = {
    Text = "Bel berbunyi, dia mengangkat satu tangannya, bergoyang untuk memulai tarian."
  },
  AvgDialog_45427_Content_55 = {
    Text = "Dia membungkuk, meregangkan tubuh, terkadang ekspresif, terkadang penuh kesederhanaan."
  },
  AvgDialog_45427_Content_56 = {
    Text = "Aku selalu menantikan seseorang."
  },
  AvgDialog_45427_Content_57 = {
    Text = "Tubuhnya lembut seolah tanpa tulang, gerakan dansanya seperti ular yang meliuk."
  },
  AvgDialog_45427_Content_58 = {
    Text = "Seorang penjaga yang dapat memimpin Aran menuju \"masa depan\"."
  },
  AvgDialog_45427_Content_59 = {
    Text = "Dia berputar dan bergoyang, sisa-sisa bayangannya menunjukkan keanggunan alami serta kelenturan yang luar biasa."
  },
  AvgDialog_45427_Content_6 = {
    Text = [[
Tidak perlu terlalu cemas, ini adalah sesuatu yang cepat atau lambat pasti akan terjadi. 
Bagi "Dia", baik bersembunyi di masa lalu maupun di masa depan, bukanlah solusi jangka panjang.]]
  },
  AvgDialog_45427_Content_60 = {
    Text = "Bukankah Alva adalah orang itu?"
  },
  AvgDialog_45427_Content_61 = {
    Text = "Thais memutar tubuhnya, menundukkan kepala dan matanya, ujung jarinya menyentuh bunga yang tergenggam saat napas berat terhela di sudut bibirnya."
  },
  AvgDialog_45427_Content_62 = {
    Text = "Alva adalah anak yang baik, namun dia belum mampu membuka jalan baru."
  },
  AvgDialog_45427_Content_63 = {
    Text = "Bagaimana dengan Juliette? Bukankah dia utusan dari negeri asing?"
  },
  AvgDialog_45427_Content_64 = {
    Text = "Apa yang kamu katakan tadi, jalan yang diminta Juliette untuk suku Alan adalah keluar dari gurun, benar kan?"
  },
  AvgDialog_45427_Content_65 = {
    Text = "Thais mengulurkan kedua tangannya, pandangan kosongnya tertuju pada bulan di ujung jarinya, seolah-olah melepas burung tak terlihat yang terbang menjauh."
  },
  AvgDialog_45427_Content_66 = {
    Text = "Orang-orang yang mampu pergi, sudah lama pergi. Aran tak pernah membatasi siapa pun. Baik karena rindu kampung halaman maupun terbiasa dengan gaya hidup gurun, mereka yang tetap tinggal hanya bisa bertahan di sini."
  },
  AvgDialog_45427_Content_67 = {
    Text = "Lagipula, itu bukan jawaban yang aku harapkan."
  },
  AvgDialog_45427_Content_68 = {
    Text = "Jawaban yang kamu harapkan... seperti apa?"
  },
  AvgDialog_45427_Content_69 = {
    Text = "Sudah lama tercantum dalam lagu."
  },
  AvgDialog_45427_Content_7 = {
    Text = "Yang aku khawatirkan bukan \"Dia\", melainkan anak itu."
  },
  AvgDialog_45427_Content_70 = {
    Text = "Pohon Ibu melahirkan kembali Sungai Suci, memberikan mahkota kepada yang telah tiada, dan mengembalikan garis keturunan kepada Alen."
  },
  AvgDialog_45427_Content_71 = {
    Text = "Kelahiran kembali Pohon Ibu di Sungai Suci mudah dipahami, tetapi siapakah yang dimaksud dengan yang telah meninggal? Dan bagaimana cara mengembalikan darah ke Alan?"
  },
  AvgDialog_45427_Content_72 = {Text = "Ssst——"},
  AvgDialog_45427_Content_73 = {
    Text = "Detail-detail tersebut terlalu rumit, ramalan @1 tidak bisa memberikan semua jawaban."
  },
  AvgDialog_45427_Content_74 = {
    Text = [[
Satu-satunya hal yang perlu kamu lakukan adalah mempercayaiku sepenuhnya. 
Percayalah pada Ratu Aran.]]
  },
  AvgDialog_45427_Content_75 = {
    Text = "Bunga padang pasir mekar di malam bulan yang redup, dia mengangkat tangan, berputar, dan melangkah, menciptakan ritme kuno dan rumit di atas pasir."
  },
  AvgDialog_45427_Content_76 = {
    Text = "Selama kamu percaya padaku, aku adalah senjata rahasia mutlak, satu-satunya, dan hanya milikmu —— Rahasia."
  },
  AvgDialog_45427_Content_77 = {
    Text = "Di bawah cahaya bulan, siluetnya tampak lembut dan misterius. Matanya bergerak lincah, mengungkapkan perasaan yang tak terucapkan."
  },
  AvgDialog_45427_Content_78 = {
    Text = "Jika ini adalah mimpi yang akan segera berakhir——\nBintang-bintang yang jauh menjadi saksi bagi dirinya."
  },
  AvgDialog_45427_Content_79 = {
    Text = "Tunggu, Thais, di bawah kakimu——"
  },
  AvgDialog_45427_Content_8 = {
    Text = "Ini bukan urusan yang bisa kita ikut campur."
  },
  AvgDialog_45427_Content_80 = {
    Text = "Kamu berteriak dengan cemas."
  },
  AvgDialog_45427_Content_81 = {
    Text = "Dia melangkah di atas riak. Bukan, riak hitam yang menyebar dari ujung kakinya."
  },
  AvgDialog_45427_Content_82 = {
    Text = "Ujung kain putih berkibar seperti daun teratai yang bergoyang, menyebarkan butiran air yang berkilauan. Warna hitamnya pekat dan dalam seperti obsidian."
  },
  AvgDialog_45427_Content_83 = {
    Text = "Itu adalah... D-lendir...?"
  },
  AvgDialog_45427_Content_84 = {
    Text = "Dia menari di dalam kolam pelarutan yang seperti fatamorgana. Dia berulang kali melangkah di atas permukaan cairan hitam."
  },
  AvgDialog_45427_Content_87 = {
    Text = "Dia seakan-akan tidak mendengar panggilanmu, menari mengikuti ritme yang tak terduga."
  },
  AvgDialog_45427_Content_88 = {
    Text = "Dia berbalik ke arahmu, posturnya anggun dan terbuka. Kalung yang kau pasangkan di lehernya berkilauan cemerlang di dadanya."
  },
  AvgDialog_45427_Content_89 = {
    Text = "Dia mengundangmu untuk menari, dan tanpa sadar kau meletakkan tanganmu di telapak tangannya."
  },
  AvgDialog_45427_Content_9 = {
    Text = "Mythag telah membayar harga selama tiga ratus tahun warisan. Penerus yang kami tetapkan tidak boleh menyimpang dari jalur yang telah ditentukan."
  },
  AvgDialog_45427_Content_90 = {
    Text = "Dia menarik telapak tanganmu, membimbing ujung jarimu menyentuh batu giok putih yang tampak berdenyut seperti memiliki kehidupan."
  },
  AvgDialog_45427_Content_91 = {
    Text = [[
Di langit jauh, meteor jatuh. 
 Matanya lebih berkilau daripada bintang-bintang.]]
  },
  AvgDialog_45427_Content_93 = {
    Text = "Bibirnya sedikit terbuka, angin malam membawa bisikan lembutnya."
  },
  AvgDialog_45427_Content_94 = {
    Text = "Bisakah aku menitipkan mereka padamu dengan tenang?"
  },
  AvgDialog_45427_Content_95 = {
    Text = "Sensasi tarikan yang mirip dengan malam pesta api unggun itu menangkapmu, hampir tanpa sadar, kamu bergumam."
  },
  AvgDialog_45427_Content_96 = {
    Text = "Bisa, pasti bisa."
  },
  AvgDialog_45427_Content_97 = {Text = "Itu bagus."},
  AvgDialog_45427_Content_98 = {
    Text = "Thais tersenyum."
  },
  AvgDialog_45427_Content_99 = {
    Text = "Teman-temanmu sudah tiba."
  },
  AvgDialog_45429_Content_1 = {
    Text = "Kain merah Casiah berkibar ke segala arah, cangkir dan piring di dalam tenda berantakan pecah menjadi tujuh bagian delapan potongan."
  },
  AvgDialog_45429_Content_10 = {
    Text = "Dia dengan sigap membuka topi sulap raksasa, dan di dalamnya muncul sosok yang tak terduga."
  },
  AvgDialog_45429_Content_11 = {
    Text = "Bagaimana bisa kamu?!"
  },
  AvgDialog_45429_Content_12 = {
    Text = "Astaga, sedikit keberuntungan."
  },
  AvgDialog_45429_Content_13 = {
    Text = "Casiah buru-buru melihat ke luar jendela, sosok Penjaga sudah terlihat bergoyang di atas unta dan semakin menjauh."
  },
  AvgDialog_45429_Content_14 = {
    Text = "Tiga dadu menembus tirai, menggores pipi Casiah saat melesat."
  },
  AvgDialog_45429_Content_15 = {
    Text = "Baiklah, apakah kau benar-benar ingin terus berdebat denganku sampai akhir?"
  },
  AvgDialog_45429_Content_16 = {
    Text = "Kalau begitu, masuklah ke dalam void dimensi lain untuk merenungkan kesalahanmu!"
  },
  AvgDialog_45429_Content_17 = {
    Text = "Ilusi tiba-tiba menelan ruang di depan mata, warna-warna seperti lukisan minyak memenuhi pandangan. Ketika kekacauan berwarna-warni kembali ke tatanan, ruang telah berubah menjadi panggung pesulap."
  },
  AvgDialog_45429_Content_18 = {
    Text = "Mari kita mulai, \"Karnaval Ajaib Casiah!\""
  },
  AvgDialog_45429_Content_2 = {
    Text = [[
Kamu dan Ryker bertukar pandang. 
Saat ini, yang terpenting adalah melarikan diri untuk menghentikan upacara pengorbanan Alan yang dimanipulasi oleh Gereja Penerang Kuil.]]
  },
  AvgDialog_45429_Content_3 = {
    Text = "Topi sulap Casiah melayang menutupi kepalamu. Kamu dan Ryker mengikuti rencana untuk berpisah menjadi dua arah, dan sebuah topi sulap langsung mengejarmu ——"
  },
  AvgDialog_45429_Content_4 = {
    Text = "Hm hm, tebak di mana Penjaga berada di antara topi-topi ini?"
  },
  AvgDialog_45429_Content_5 = {
    Text = "Kiri juga kosong, kanan juga kosong~"
  },
  AvgDialog_45429_Content_6 = {
    Text = "Cang cang~ Sebenarnya, tidak ada satu pun topi di sana, lihat, {Male=dia,Female=dia} berada di balik tirai Casiah!"
  },
  AvgDialog_45429_Content_7 = {
    Text = "Kain sutra merah menyembul dari celah kehampaan, bergerak seperti gelombang yang bergoyang tak menentu, dan membungkus Penjaga dengan erat menjadi mumi merah menyala."
  },
  AvgDialog_45429_Content_8 = {
    Text = "Bagaimana, apakah ini pertunjukan yang sangat khas Arland?"
  },
  AvgDialog_45429_Content_9 = {
    Text = "Mengambil barang dari jarak jauh~ Hehe, saatnya aku mengambil barangku."
  },
  AvgDialog_45430_Content_1 = {Text = "Titik Temu"},
  AvgDialog_45430_Content_10 = {
    Text = "Pohon Ibu... Bukankah itu ada di sana?"
  },
  AvgDialog_45430_Content_100 = {
    Text = "Kalian berlari menuju perkemahan di bawah gundukan pasir."
  },
  AvgDialog_45430_Content_101 = {
    Text = "Pada saat ujung jari menyentuh tirai, rasa takut yang luar biasa langsung menghantui dirimu."
  },
  AvgDialog_45430_Content_103 = {
    Text = "Rasa takut ini berbeda dari saat menghadapi Anjing pemburu atau melawan janin suci…"
  },
  AvgDialog_45430_Content_104 = {
    Text = "Itu adalah ketakutan yang meresap hingga ke tulang sumsum, tak terhadapi dan tak dapat diperbaiki, sulit untuk diungkapkan."
  },
  AvgDialog_45430_Content_105 = {
    Text = "Itu adalah mimpi buruk mengambang, fantasi abnormal, kenyataan yang tak tertahankan dan menyulitkan untuk bertahan."
  },
  AvgDialog_45430_Content_106 = {
    Text = "Monster raksasa dan liar mengayunkan tentakel berlendirnya, sementara tubuh kurus William bergoyang seperti alang-alang yang rapuh di antaranya."
  },
  AvgDialog_45430_Content_108 = {
    Text = "Bekas luka di pelipisnya, konon akibat luka bakar dari ibunya yang gila, kini tampak seperti alur dangkal yang mengalirkan cairan merah segar."
  },
  AvgDialog_45430_Content_109 = {
    Text = "Kunci Perak hancur di dada, sarung tangan standar Mythag ternoda oleh noda darah, cairan lengket yang tidak menyenangkan menetes bebas melawan gravitasi."
  },
  AvgDialog_45430_Content_11 = {
    Text = "Horizon yang jauh, tempat bertemunya langit dan bumi."
  },
  AvgDialog_45430_Content_110 = {
    Text = "Di balik mimpi buruk yang bergoyang itu——"
  },
  AvgDialog_45430_Content_111 = {
    Text = "Gunungan daging raksasa terbuka seperti mulut tumbuhan venus."
  },
  AvgDialog_45430_Content_112 = {
    Text = "Lipatan plasenta di kedua sisi dan bayi dengan kelainan tampak jelas seperti cap berdarah yang terpatri di benakmu."
  },
  AvgDialog_45430_Content_113 = {
    Text = "Di tengah gumpalan daging yang bengkak dan terpilin, terbaring hadiah terakhir dari perjalanannya yang terus ia telusuri dan cari, dipersembahkan kepada kalian."
  },
  AvgDialog_45430_Content_114 = {
    Text = "Itulah kebenaran dari inti Nubia——"
  },
  AvgDialog_45430_Content_115 = {
    Text = "Sebuah lampu lentera kecil."
  },
  AvgDialog_45430_Content_12 = {
    Text = "Pohon ibu yang menjulang tinggi hingga ke awan, berdiri tegak di tanah yang bagaikan tepi dunia lain."
  },
  AvgDialog_45430_Content_13 = {
    Text = "Maksudmu, kamu bisa melihat Pohon Ibu?"
  },
  AvgDialog_45430_Content_14 = {
    Text = "Kamu menengadah ke langit, mengulurkan tanganmu, dan melukiskan kontur Pohon Ibu."
  },
  AvgDialog_45430_Content_15 = {
    Text = "Sebatang pohon tua yang kurus… menjulang tinggi, namun kesepian…"
  },
  AvgDialog_45430_Content_16 = {
    Text = "Mungkin... Pohon Ibu menghilang karena pelarutan."
  },
  AvgDialog_45430_Content_17 = {
    Text = "Apakah kalian masih ingat? %player% memiliki memori tentang hal-hal yang menghilang karena pelarutan."
  },
  AvgDialog_45430_Content_18 = {
    Text = "Kamu membuka surat kabar yang dibawa Jenkin, tapi tinta di atasnya tampak seperti memiliki hidup sendiri, perlahan-lahan mulai menghilang ——"
  },
  AvgDialog_45430_Content_19 = {
    Text = "Hingga kamu tidak bisa lagi melihat dengan jelas laporan tentang \"Spring\"."
  },
  AvgDialog_45430_Content_2 = {
    Text = "Kemudian, ▼▼▼ akan kembali ke Takhtanya, \n kekacauan akan diusir. \n Orang yang melihat semua ini akan bersorak, \n mereka yang melayani Raja juga akan bersorak."
  },
  AvgDialog_45430_Content_20 = {
    Text = "Kerusakan pada watermark dan noda tinta ini seolah-olah bertekad untuk sepenuhnya menghapus keberadaan Mason."
  },
  AvgDialog_45430_Content_22 = {
    Text = "Apa, apakah ini sihir? Surat kabar ini sudah kubaca sebanyak delapan ratus kali."
  },
  AvgDialog_45430_Content_23 = {
    Text = "Tapi sekarang... satu kata pun, aku tidak bisa mengingat apa pun."
  },
  AvgDialog_45430_Content_24 = {
    Text = "Eh, kalian benar-benar tidak ingat apa pun?"
  },
  AvgDialog_45430_Content_25 = {
    Text = "\"Pembela utama aliran Kubisme, reinkarnasi jiwa Botticelli saat ini bersembunyi di museum lilin di sudut jalan Southwark…\""
  },
  AvgDialog_45430_Content_26 = {
    Text = "Lihat, aku bahkan bisa mengulangi isi berita itu."
  },
  AvgDialog_45430_Content_27 = {
    Text = "Koran telah terlarut. Ini menunjukkan bahwa kemungkinan besar ini adalah fenomena <Yellow:kehilangan ingatan massal> yang disebabkan oleh pelarutan, namun…"
  },
  AvgDialog_45430_Content_28 = {
    Text = "Ramona dan Jenkin serempak menatapmu."
  },
  AvgDialog_45430_Content_29 = {
    Text = "Tampaknya tidak berpengaruh pada seseorang."
  },
  AvgDialog_45430_Content_3 = {
    Text = "Regu itu... hanya tiga orang yang selamat, termasuk Nefrure."
  },
  AvgDialog_45430_Content_31 = {
    Text = "Percaya atau tidak, rasanya agak tidak nyaman…"
  },
  AvgDialog_45430_Content_32 = {
    Text = "Sepertinya tanpa disadari, masa lalu telah diubah, dan Cerita pun menyimpang dari jalur yang telah ditentukan."
  },
  AvgDialog_45430_Content_33 = {
    Text = "Dan kamu menjadi satu-satunya saksi atas perubahan-perubahan ini."
  },
  AvgDialog_45430_Content_34 = {
    Text = "Sebagai pembawa tubuh esensi keinginan, keberadaan Pohon Ibu pasti telah meninggalkan jejak yang cukup dalam di Planet."
  },
  AvgDialog_45430_Content_35 = {
    Text = "Kehidupan yang gigih dari Pohon Ibu membuat kecepatan pelarutan terhadapnya menjadi ribuan hingga jutaan kali lebih lambat dibandingkan dengan manusia biasa."
  },
  AvgDialog_45430_Content_36 = {
    Text = "Jadi, bagimu, dia belum sepenuhnya menghilang."
  },
  AvgDialog_45430_Content_37 = {
    Text = "Jika ratusan atau ribuan tahun berlalu, orang Aram mungkin akan melupakan keberadaan Pohon Ibu."
  },
  AvgDialog_45430_Content_38 = {
    Text = "Dan ritual Aran, mungkin bisa menangkap sisa-sisa keberadaan lemah dari Pohon Ibu."
  },
  AvgDialog_45430_Content_39 = {
    Text = "Seperti Upacara kebangkitan?"
  },
  AvgDialog_45430_Content_4 = {
    Text = "Namun, orang Aram tampaknya masih sangat bersemangat.\nPengorbanan seperti ini… bagi mereka sudah menjadi hal yang biasa."
  },
  AvgDialog_45430_Content_40 = {
    Text = "Ya, Upacara Kebangkitan pada dasarnya meminjam Kekuatan Roh dari Penyelidik untuk membuat keberadaan Roh di dalam Perak muncul kembali di dunia. \"Kelahiran Kembali\" Pohon Ibu seharusnya serupa dengan itu."
  },
  AvgDialog_45430_Content_41 = {
    Text = "%player%, seperti apa Pohon Ibu yang kamu lihat?"
  },
  AvgDialog_45430_Content_42 = {
    Text = "Hmm… bagaimana ya, seperti batang pohon yang gundul tumbuh di tanah yang tandus… sama sekali tidak ada hubungannya dengan kata \"subur\"."
  },
  AvgDialog_45430_Content_43 = {
    Text = "Seperti… bentuk akhir dari Pohon ibu sebelum kematiannya."
  },
  AvgDialog_45430_Content_44 = {
    Text = "Besok adalah Upacara Alan, apakah kalian masih belum beristirahat?"
  },
  AvgDialog_45430_Content_45 = {
    Text = "Hasil pemeriksaan anatomi saya akan segera keluar."
  },
  AvgDialog_45430_Content_46 = {
    Text = "Sudah jam berapa sekarang, masih memikirkan anatomi itu… \nMeskipun aku sangat ingin mengatakannya, kamu benar. Kita hanya kurang satu potongan terakhir dari teka-teki ini."
  },
  AvgDialog_45430_Content_47 = {
    Text = "%player%, ini sudah kesempatan terakhir."
  },
  AvgDialog_45430_Content_48 = {
    Text = "Dia tidak tidur demi melakukan pembedahan, lalu kamu untuk apa?"
  },
  AvgDialog_45430_Content_49 = {
    Text = "Saya... sedang mengingat sebuah mimpi."
  },
  AvgDialog_45430_Content_5 = {
    Text = "Kamu memandang kerumunan orang yang biasanya terdiam, di dalam murid mereka berkilauan cahaya seperti oasis."
  },
  AvgDialog_45430_Content_50 = {
    Text = "Itu adalah salah satu mimpi yang sering kamu alami."
  },
  AvgDialog_45430_Content_51 = {
    Text = "Dalam mimpi, segalanya gelap gulita. Hanya ada suara deru air pasang yang menghantam tepi sungai dengan gegap gempita."
  },
  AvgDialog_45430_Content_52 = {
    Text = "Jantungmu berdetak mengikuti ritme aliran air. Jantung banyak orang juga ikut berdetak mengikuti ritmenya."
  },
  AvgDialog_45430_Content_53 = {
    Text = "Detak jantung tak terhitung banyaknya bergabung menjadi sungai berwarna hitam pekat, dan gelombang hitam itu tanpa ragu mengalir deras menuju muara, mewarnai seluruh lautan menjadi warna tinta…"
  },
  AvgDialog_45430_Content_54 = {
    Text = "Saya mendengar bahwa mimpi-mimpimu sering mengandung ramalan."
  },
  AvgDialog_45430_Content_55 = {
    Text = "Terkadang itu adalah memori, terkadang itu adalah ramalan."
  },
  AvgDialog_45430_Content_56 = {
    Text = "Apa pun itu, ini menunjukkan bahwa hidup mereka benar-benar telah dilahap oleh pelarutan…"
  },
  AvgDialog_45430_Content_57 = {
    Text = "Jangan terlalu banyak berpikir. Bahkan jika Pelarutan tidak pernah ada, manusia tetap terus maju dan menghilang dalam perjalanan mereka."
  },
  AvgDialog_45430_Content_58 = {
    Text = "Membicarakan topik seperti ini, rasanya selalu perlu mengajak William dan menambahkan sedikit minuman."
  },
  AvgDialog_45430_Content_59 = {
    Text = "Mythag, sang penyelidik legendaris terhebat, telah mengalami lebih banyak acara misterius daripada jumlah taruhan yang telah saya menangkan."
  },
  AvgDialog_45430_Content_6 = {
    Text = "Pohon Ibu yang mulia, mohon berikan kesuburan pada tanah dan air Aran, serta lindungi generasi penerusnya."
  },
  AvgDialog_45430_Content_60 = {
    Text = "Kamu menyentuh pin di dada, lalu memanggil William."
  },
  AvgDialog_45430_Content_61 = {
    Text = "Saya seharusnya... seharusnya sudah memikirkannya."
  },
  AvgDialog_45430_Content_62 = {
    Text = [[
Di tengah tenda, mayat Nubia terbuka dengan luka sayatan yang lancar dan tepat. 
 Jika diperhatikan dengan seksama, masih bisa dirasakan napasnya yang naik turun pelan.]]
  },
  AvgDialog_45430_Content_63 = {
    Text = "Itu adalah batas maksimal yang bisa dicapai setelah ratusan hingga ribuan kali percobaan, berdenyut di ambang kehidupan dan kematian."
  },
  AvgDialog_45430_Content_64 = {
    Text = "Mampu memanipulasi proses Pelarutan, membuat anomali Nubia menghilang."
  },
  AvgDialog_45430_Content_65 = {
    Text = "Musuh kita memiliki pemahaman dan kendali yang luar biasa terhadap pelarutan."
  },
  AvgDialog_45430_Content_66 = {
    Text = "Dia meletakkan pisau bedah, menarik napas dalam-dalam. Bau busuk yang mirip air darah langsung membuatnya tersedak, lalu dia batuk hebat."
  },
  AvgDialog_45430_Content_67 = {
    Text = "Dan lagu itu..."
  },
  AvgDialog_45430_Content_68 = {
    Text = "Kerangka ibu tidak terlihat, darah dan benih hanyut di bumi, dilahap oleh binatang liar yang baru lahir."
  },
  AvgDialog_45430_Content_69 = {
    Text = "Langit dan para dewa dipenuhi awan mendung, hingga Kedatangan utusan dari negeri asing."
  },
  AvgDialog_45430_Content_7 = {
    Text = "Setelah Anda dilahirkan kembali, Alan pasti akan mempersembahkan air yang paling manis kepada Anda…"
  },
  AvgDialog_45430_Content_70 = {
    Text = "Kedatangan binatang buas harus mendahului kedatangan utusan."
  },
  AvgDialog_45430_Content_71 = {
    Text = "Jadi Juliette terus berkeliaran di luar Dinding Badai, sehingga dia sangat yakin bahwa kali ini pasti bisa menembus Dinding Badai."
  },
  AvgDialog_45430_Content_72 = {
    Text = "Juliette, sama sekali bukan utusan legendaris dari negeri asing…"
  },
  AvgDialog_45430_Content_73 = {
    Text = "Dia berasal dari Gereja Penerang Kuil, mengarang apa yang disebut sebagai panggilan mimpi, dan memperoleh kepercayaan orang Aram. \nTujuannya… kemungkinan besar adalah berjalan bersama orang Aram, mencemari Pohon Ibu dan Sungai Suci."
  },
  AvgDialog_45430_Content_74 = {
    Text = "Utusan sejati dari negeri asing…\nTak perlu menebak, tak diragukan lagi, adalah Penjaga."
  },
  AvgDialog_45430_Content_75 = {
    Text = "Tidak, masih belum cukup."
  },
  AvgDialog_45430_Content_76 = {
    Text = "Sebuah perasaan aneh mendorong William untuk terus menyempurnakan kesimpulannya."
  },
  AvgDialog_45430_Content_77 = {
    Text = [[
Dan antarmuka abnormal ini...
Itu adalah karya Herbert dari Para pematung.]]
  },
  AvgDialog_45430_Content_78 = {
    Text = "Jika kesimpulanmu bisa berhenti di langkah sebelumnya, kamu sebenarnya bisa meninggalkan Lemuwahi dengan selamat."
  },
  AvgDialog_45430_Content_79 = {
    Text = "Bisa dikatakan, memang pantas menjadi Penyelidik legendaris Mythag, selangkah lebih maju dari semua orang dalam menemukan jawabannya."
  },
  AvgDialog_45430_Content_8 = {
    Text = "Setiap hari mendengar orang Aram ini membicarakan Pohon Ibu, entah seperti apa sebenarnya pemandangan megah itu."
  },
  AvgDialog_45430_Content_80 = {Text = "Herbert!"},
  AvgDialog_45430_Content_81 = {
    Text = "Jangan gugup, aku selalu lebih percaya pada kemampuanmu dibandingkan orang lain."
  },
  AvgDialog_45430_Content_82 = {
    Text = "Mereka juga sama, jika tidak, mengapa mereka meninggalkanmu sendirian di sini, bahkan tanpa seorang Pembangun yang mengikuti?"
  },
  AvgDialog_45430_Content_83 = {
    Text = [[
Sama-sama. 
Jika aku tidak salah ingat, Pembangunmu terputus dari Rai saat kalian kehilangan sambungan.]]
  },
  AvgDialog_45430_Content_84 = {
    Text = "Mengenai tubuh yang kau pekerjakan untuk membangunkan... saya percaya Wanita narsis tidak akan langsung bermusuhan dengan Universitas Mythag."
  },
  AvgDialog_45430_Content_85 = {
    Text = "Apakah menurutmu aku tidak memiliki kemampuan untuk membunuhmu di sini?"
  },
  AvgDialog_45430_Content_86 = {
    Text = "Saya tidak pernah meremehkan musuh saya, terutama pembunuh Profesor Crowley."
  },
  AvgDialog_45430_Content_87 = {
    Text = "Saya tahu, tentu saja saya tahu."
  },
  AvgDialog_45430_Content_88 = {
    Text = [[
Selama penyelidikan di studio lukis, pada upacara di Sentinel Ridge...
Para pelayan dari kehendak tinggi tidak mampu mengalahkanmu, apalagi Pembangun biasa.]]
  },
  AvgDialog_45430_Content_89 = {
    Text = "Jadi, ketika saya mendengar bahwa Mythag mengirimkanmu, saya tahu saya harus melakukan persiapan yang sangat matang."
  },
  AvgDialog_45430_Content_9 = {
    Text = "Ryker, apa yang kau... katakan..."
  },
  AvgDialog_45430_Content_90 = {
    Text = "Ramona-loop, benar?"
  },
  AvgDialog_45430_Content_91 = {
    Text = "Dengan suatu cara membuka lorong yang menghubungkan ke dunia lain, dan menjadikan roh dari keberadaan tinggi di dunia lain untuk bersemayam pada individu yang berasal dari sumber yang sama."
  },
  AvgDialog_45430_Content_92 = {
    Text = "Herbert mengelus masing-masing kepala dari kucing dua kepala di pundaknya."
  },
  AvgDialog_45430_Content_93 = {
    Text = "Sayang kecil, aku mencintaimu sama seperti aku mencintainya."
  },
  AvgDialog_45430_Content_94 = {
    Text = "<Blue:Helot-catena>."
  },
  AvgDialog_45430_Content_95 = {
    Text = "Hei hei, Kak William..."
  },
  AvgDialog_45430_Content_96 = {
    Text = "Lima detik."
  },
  AvgDialog_45430_Content_97 = {
    Text = "Sepuluh detik."
  },
  AvgDialog_45430_Content_98 = {
    Text = "William berada di dalam tenda yang berjarak seratus langkah dari Anda, namun sisi lain komunikasi tetap sunyi."
  },
  AvgDialog_45430_Content_99 = {
    Text = "Rasa gelisah tiba-tiba muncul, ketakutan seperti palu berat yang bertubi-tubi menghantam jiwa."
  },
  AvgDialog_45431_Content_1 = {Text = "Kerangka"},
  AvgDialog_45431_Content_10 = {
    Text = "Sedikit lebih tenang. Karena William tidak ada, aku merasa tidak bisa mempercayai kalian berdua."
  },
  AvgDialog_45431_Content_11 = {
    Text = "Pipinya masih sedikit memerah. Kamu menyentuh dahinya dengan lembut, tampaknya tidak sepanas sebelumnya."
  },
  AvgDialog_45431_Content_12 = {
    Text = "Di sini...?"
  },
  AvgDialog_45431_Content_13 = {
    Text = "Berbeda dengan suku Alan yang penuh suasana primitif, yang terlihat adalah reruntuhan peradaban manusia yang lebih dekat dengan apa yang kamu kenal — sebuah pabrik yang tampaknya telah lama ditinggalkan."
  },
  AvgDialog_45431_Content_14 = {
    Text = "Setelah banjir bandang, rezim Lemuwah pernah melakukan pembangunan industri di sini, mendirikan beberapa pabrik dan sekolah."
  },
  AvgDialog_45431_Content_15 = {
    Text = "Namun, masyarakat Aram terbiasa dengan kehidupan nomaden, sehingga dukungan mereka terhadap industrialisasi gurun sangat terbatas. Bangunan-bangunan tersebut akhirnya ditinggalkan seiring dengan semakin parahnya penggurunan dan perubahan kekuasaan."
  },
  AvgDialog_45431_Content_16 = {
    Text = "Aram tidak menyia-nyiakan atap-atap ini, mereka menyimpan barang-barang yang perlu berventilasi dan terlindung dari kelembapan di pabrik-pabrik yang ditinggalkan—seperti sisa pohon suci yang kita ketahui."
  },
  AvgDialog_45431_Content_17 = {
    Text = "Tunggu, ada sesuatu yang mendekat dengan cepat!"
  },
  AvgDialog_45431_Content_2 = {
    Text = [[
Begitu aku menoleh, kamu sudah menghilang. 
 Kamu tadi sedang berbicara dengan siapa?]]
  },
  AvgDialog_45431_Content_4 = {
    Text = [[
Satu-satunya hal yang perlu kamu lakukan adalah mempercayaiku sepenuhnya. 
Percayalah pada Ratu Aran.]]
  },
  AvgDialog_45431_Content_5 = {
    Text = "Jangan lupa, malam ini adalah rahasia yang hanya milik kita."
  },
  AvgDialog_45431_Content_6 = {
    Text = "Keraguanmu tidak luput dari mata detektif."
  },
  AvgDialog_45431_Content_7 = {
    Text = [[
Teman kecil kita memiliki sedikit rahasia yang tidak ingin diungkapkan. 
 Tenang saja, orang dewasa yang pengertian tidak akan menanyakan lebih lanjut.]]
  },
  AvgDialog_45431_Content_8 = {
    Text = [[
Saya dan Ramona baru saja mengikuti rombongan Yalan, mengonfirmasi lokasi penempatan Sisa pohon suci. 
Tanpa membuang waktu, mari kita menyelinap masuk saat tengah malam.]]
  },
  AvgDialog_45431_Content_9 = {
    Text = "Ramona, apakah Tubuhmu tidak apa-apa?"
  },
  AvgDialog_45432_Content_1 = {
    Text = "Dinding badai"
  },
  AvgDialog_45432_Content_10 = {
    Text = "Dinding badai bukanlah dinding yang nyata, melainkan penghalang untuk menyembunyikan diri yang diciptakan oleh Pohon Suci."
  },
  AvgDialog_45432_Content_11 = {
    Text = "Jika tidak memiliki tujuan untuk bertemu dengan Pohon Ibu, bahkan Dinding Badai saja tidak akan terlihat, apalagi menembusnya."
  },
  AvgDialog_45432_Content_12 = {
    Text = "Oleh karena itu, mereka membutuhkan \"Utusan dari Negeri Asing\"."
  },
  AvgDialog_45432_Content_13 = {
    Text = "Barisan bergerak teratur ke sisi kiri dan kanan, dengan jarak lima hingga sepuluh langkah, membentuk ular panjang yang terdiri dari manusia."
  },
  AvgDialog_45432_Content_14 = {
    Text = "Semua orang telah siap, berdiri di posisi masing-masing."
  },
  AvgDialog_45432_Content_15 = {
    Text = "Alva mengangkat bendera tinggi-tinggi, mereka serempak menyapukan tombak mereka melintasi padang pasir yang tandus, menimbulkan debu pasir yang membutakan mata, sambil melantunkan nyanyian yang aneh dan mistis."
  },
  AvgDialog_45432_Content_16 = {
    Text = "Kematian sudah mendekat, kehancuran telah dimulai."
  },
  AvgDialog_45432_Content_17 = {
    Text = "Kerangka ibu tidak terlihat, darah dan benih hanyut di bumi, dilahap oleh binatang liar yang baru lahir."
  },
  AvgDialog_45432_Content_18 = {
    Text = "Langit dan para dewa dipenuhi awan mendung, hingga Kedatangan utusan dari negeri asing."
  },
  AvgDialog_45432_Content_19 = {
    Text = "Pohon Ibu melahirkan kembali Sungai Suci, memberikan mahkota kepada yang telah tiada, dan mengembalikan garis keturunan kepada Alen."
  },
  AvgDialog_45432_Content_2 = {
    Text = [[
Aku baik-baik saja. 
Alva sudah mulai memeriksa anggota tim, ayo kita ikuti.]]
  },
  AvgDialog_45432_Content_20 = {
    Text = "Kembalikan darah… kepada Aran…"
  },
  AvgDialog_45432_Content_21 = {
    Text = "Entah sejak kapan, matahari terik di padang pasir menghilang, langit menjadi suram, dan suara angin berubah nada."
  },
  AvgDialog_45432_Content_22 = {
    Text = "Rasa takut yang tak terjelaskan menyergapmu, kamu tiba-tiba kehilangan fokus, lalu segera dibangun oleh sebuah teriakan."
  },
  AvgDialog_45432_Content_23 = {
    Text = "Itu, itu datang——!"
  },
  AvgDialog_45432_Content_24 = {
    Text = "Pada saat pandanganmu terfokus, kau memahami apa yang disebut \"Dinding badai\"."
  },
  AvgDialog_45432_Content_25 = {
    Text = "Itu adalah tirai abu-abu raksasa yang menelan langit dan bumi, bergulung mendekat dalam bentuk yang menutupi langit."
  },
  AvgDialog_45432_Content_26 = {
    Text = "Seharusnya itu seperti pasang surut, tetapi bukan pasang surut. Ia begitu besar dan sunyi, bergerak maju namun seolah-olah diam."
  },
  AvgDialog_45432_Content_27 = {
    Text = "Perbatasannya seperti binatang raksasa yang menjilat bumi, dan barisan Aran pun tertelan ke dalam Kabut, ditarik serta dicerna oleh perut badai."
  },
  AvgDialog_45432_Content_28 = {
    Text = "Terus melompat, jangan berhenti!"
  },
  AvgDialog_45432_Content_29 = {
    Text = "Utusan dari negeri asing telah tiba, Ratu akan membuka jalan bagi kita menuju Pohon Ibu!"
  },
  AvgDialog_45432_Content_3 = {
    Text = "Hari ini adalah hari keberangkatan menuju Dinding Badai."
  },
  AvgDialog_45432_Content_30 = {
    Text = "Kamu memperhatikan Juliette di sebelahmu tersenyum tipis."
  },
  AvgDialog_45432_Content_31 = {
    Text = "Kepala Suku, Kepala Suku, badai hari ini terlalu hebat! Kami benar-benar tidak bisa kehilangan begitu banyak orang. Mari kita mundur dulu!"
  },
  AvgDialog_45432_Content_32 = {
    Text = "Tidak boleh!"
  },
  AvgDialog_45432_Content_33 = {
    Text = "Nada suaranya penuh wibawa, namun kalimatnya bergetar karena suara angin."
  },
  AvgDialog_45432_Content_34 = {
    Text = "Tingkat kelainan dalam ritual api unggun semakin tinggi. Jika terus berlanjut seperti ini, sebelum menemukan Pohon Ibu, garis keturunan Alan akan punah di aliran waktu yang panjang."
  },
  AvgDialog_45432_Content_35 = {
    Text = "Juliette menempelkan dua jarinya membentuk lingkaran, lalu meniupkan peluit yang nyaring. Nada panjang itu dibawa oleh badai, mengalun menuju kejauhan yang tak terjangkau."
  },
  AvgDialog_45432_Content_36 = {
    Text = "Saya adalah utusan Juliette, saya telah mendengar titah Ratu. Hari ini, kita pasti bisa menembus Dinding Badai!"
  },
  AvgDialog_45432_Content_37 = {
    Text = "Semua orang, hanya maju, tidak boleh mundur!"
  },
  AvgDialog_45432_Content_38 = {
    Text = "Patuh pada perintah Tuan Utusan, hanya maju, tidak boleh mundur!"
  },
  AvgDialog_45432_Content_39 = {
    Text = "<Small:Ya... jalan mundur... memang sama sekali tidak ada...>"
  },
  AvgDialog_45432_Content_4 = {
    Text = "Para pahlawan, apakah kalian sudah siap?"
  },
  AvgDialog_45432_Content_40 = {
    Text = "Tunggu, Penjaga, ada segerombolan besar Nubia di belakangmu…\nLihat jumlahnya… setidaknya ada… dua ratus!"
  },
  AvgDialog_45432_Content_41 = {
    Text = "Lihatlah! Ini adalah perintah Ratu! Kalian hanya bisa maju!"
  },
  AvgDialog_45432_Content_42 = {
    Text = "Nubia mengaum dan berlari ke arah kalian dengan ganas."
  },
  AvgDialog_45432_Content_5 = {
    Text = [[
Kamu memperhatikan dua barisan tentara yang mengikuti Alva. 
 Ekspresi mereka khidmat, seakan-akan siap menghadapi kematian.]]
  },
  AvgDialog_45432_Content_6 = {
    Text = "Pemuda yang berdiri di posisi terdepan memiliki kontur wajah yang tegas, postur tubuh tegap, dan tampak sedikit familiar."
  },
  AvgDialog_45432_Content_7 = {
    Text = "Dinding Badai?"
  },
  AvgDialog_45432_Content_8 = {
    Text = "Kamu memandang jauh ke cakrawala, langit biru cerah, pandanganmu bersih dan jelas, tampaknya tidak ada tanda-tanda badai pasir."
  },
  AvgDialog_45432_Content_9 = {
    Text = "Juliette melangkah maju."
  },
  AvgDialog_45433_Content_1 = {Text = "Penutup"},
  AvgDialog_45433_Content_10 = {
    Text = "Tapi setidaknya, kami berhasil mencegah hasil terburuk."
  },
  AvgDialog_45433_Content_11 = {
    Text = "Begitu Pohon Ibu kembali hidup di bawah kendali Gereja Penerang Kuil, yang tercemar bukan hanya gurun utara Remwahi saja."
  },
  AvgDialog_45433_Content_12 = {
    Text = "Namun, kami juga mengalami kerugian terberat sejak pendirian sekolah ini."
  },
  AvgDialog_45433_Content_13 = {
    Text = "Pada tubuh William… tidak ada Perak yang terbentuk."
  },
  AvgDialog_45433_Content_14 = {
    Text = "Kami telah kehilangan Penyelidik terbaik sejak berdirinya Mythag untuk selamanya, bahkan tidak ada kemungkinan untuk memanggil kembali sebagian dari kesadarannya."
  },
  AvgDialog_45433_Content_15 = {
    Text = "Hari ini, jenazahnya akan dimakamkan di sini."
  },
  AvgDialog_45433_Content_16 = {
    Text = "William adalah penyelidik paling berbakat yang pernah saya kenal. Kejelian pandangannya, sikap tenang dalam situasi bahaya, dan kemampuan fisiknya yang luar biasa membuatnya menonjol di antara manusia."
  },
  AvgDialog_45433_Content_17 = {
    Text = "Guru Alistair!"
  },
  AvgDialog_45433_Content_18 = {
    Text = "Di tengah suara berderit kursi roda, kerumunan memberi jalan bagi Alistair."
  },
  AvgDialog_45433_Content_19 = {
    Text = "Meskipun kariernya telah ditelan oleh bayangan misterius, prestasi cemerlangnya akan tetap bersinar seperti bintang di langit."
  },
  AvgDialog_45433_Content_2 = {
    Text = "Hujan rintik-rintik di Key Mound, sama seperti pada hari upacara pemberian kunci."
  },
  AvgDialog_45433_Content_20 = {
    Text = "Kematian selalu mengikuti, di hadapan Pelarutan, kita tidak punya banyak waktu untuk Surai."
  },
  AvgDialog_45433_Content_21 = {
    Text = "%player%, ikut aku. Tentang Tawil, tentang tiga badan besar, tentang Pelarutan... ada banyak informasi yang harus kamu ketahui sekarang."
  },
  AvgDialog_45433_Content_22 = {
    Text = "Saya tidak menyangka bahwa sikapmu yang dingin terhadap rekanmu sudah sampai pada tingkat tidak menghadiri pemakamannya."
  },
  AvgDialog_45433_Content_23 = {
    Text = "Saya tidak bisa membiasakan diri dengan suasana seperti itu."
  },
  AvgDialog_45433_Content_24 = {
    Text = "Lagipula, Tubuh Intelektual terbangun, Tubuh Keinginan tenggelam, Tubuh Kebahagiaan muncul… William tidak ada, seharusnya giliranku yang pusing tujuh keliling."
  },
  AvgDialog_45433_Content_25 = {
    Text = "Kehadiran Kualitas Yue?"
  },
  AvgDialog_45433_Content_26 = {
    Text = "Pemeriksaan jejak di tempat kematian William tidak sia-sia."
  },
  AvgDialog_45433_Content_27 = {
    Text = "Sebuah inti perak dari alam ultra, setelah pemeriksaan ternyata milik Casiah."
  },
  AvgDialog_45433_Content_28 = {
    Text = "Selain itu, kami juga mendeteksi jejak aktivitas tubuh Yueli ——"
  },
  AvgDialog_45433_Content_29 = {
    Text = "Siapa yang membuat kalian begitu tidak menghargai mainanku, sampai-sampai aku harus repot-repot menggunakan jari kelingkingku untuk mengambilnya kembali?"
  },
  AvgDialog_45433_Content_3 = {
    Text = "Semua orang berdiri khidmat di depan batu nisan yang telah lama terukir dengan nama-nama mereka, menyaksikan sebuah pemakaman yang sebenarnya."
  },
  AvgDialog_45433_Content_30 = {
    Text = "Harus banyak berterima kasih kepada Tuan N atas bantuannya."
  },
  AvgDialog_45433_Content_31 = {
    Text = "Lain kali kita bertemu, ingatkan aku untuk berterima kasih atas kelapangan dada N, kebaikan hatinya, kedermawanannya, dan sifat pemaafnya…"
  },
  AvgDialog_45433_Content_32 = {
    Text = "Ryker menggaruk bagian belakang kepalanya yang berbulu."
  },
  AvgDialog_45433_Content_33 = {
    Text = "Jadi, itu juga tidak sepenuhnya benar. Kita sudah berjanji bahwa sampai aku mengalahkanmu dalam satu pertandingan, kau akan terus membuatku merasakan penderitaan kekalahan dan kematian berulang kali, bukan?"
  },
  AvgDialog_45433_Content_34 = {
    Text = "Untuk mati lagi, pasti harus dihidupkan kembali dulu kan? Jadi, kamu pasti akan menghidupkanku kembali."
  },
  AvgDialog_45433_Content_35 = {
    Text = [[
Kamu memang sangat pandai memanfaatkan celah dalam aturan. 
 Apakah kamu mengira aku akan selalu membiarkanmu berbuat sesukamu?]]
  },
  AvgDialog_45433_Content_36 = {
    Text = "Kamu adalah sosok yang berjiwa besar, berhati lembut, bersikap terbuka, dan pemaaf. Saya pikir, tidak akan ada masalah."
  },
  AvgDialog_45433_Content_37 = {
    Text = "Lalu, kita lihat apa yang bisa kamu tampilkan untukku dalam drama yang menarik ini."
  },
  AvgDialog_45433_Content_38 = {
    Text = [[
Setelah mengucapkan kalimat terakhirnya, bayangan N menghilang. 
 Ryker berbalik menghadap semua orang.]]
  },
  AvgDialog_45433_Content_39 = {
    Text = [[
Intinya, aku sudah kembali lagi. 
Tuan Mulia Dexter, apakah Anda ingin bermain satu putaran lagi?]]
  },
  AvgDialog_45433_Content_4 = {
    Text = "Hari ini, seorang teman baru menjadi rekan perjalanan kita."
  },
  AvgDialog_45433_Content_40 = {
    Text = "Pada saat yang sama, Gurun Lermwah"
  },
  AvgDialog_45433_Content_41 = {
    Text = "Sayang, sayang, tidak apa-apa."
  },
  AvgDialog_45433_Content_42 = {
    Text = "Wahai anjingku yang setia dan patuh, tolong bantu aku menemukan jejak dua anak itu."
  },
  AvgDialog_45433_Content_43 = {
    Text = "Dengan cara ini, kita bisa memberikan penjelasan kepada Tuan Firaun."
  },
  AvgDialog_45433_Content_44 = {
    Text = "Pemuda itu meringkuk di sudut pabrik, sesekali memandang ke kejauhan."
  },
  AvgDialog_45433_Content_45 = {
    Text = "Sudah melarikan diri ke sini, seharusnya aman untuk sementara waktu…"
  },
  AvgDialog_45433_Content_46 = {
    Text = "Selanjutnya, harus mencari cara untuk membuatnya memahami dunia luar."
  },
  AvgDialog_45433_Content_47 = {
    Text = "Sebelum orang itu menemukan kita."
  },
  AvgDialog_45433_Content_48 = {
    Text = "Dia sama sekali tidak menyadari bahwa cahaya dari luar jendela memanjangkan bayangannya."
  },
  AvgDialog_45433_Content_49 = {
    Text = "Di atas bayangan panjang itu, tiba-tiba muncul senyuman aneh yang penuh keanehan."
  },
  AvgDialog_45433_Content_5 = {
    Text = [[
Merupakan suatu kehormatan bisa menjadi bagian dari Mythag. 
Saya akan berjuang bersama kalian semua untuk menyelamatkan masa depan umat manusia.]]
  },
  AvgDialog_45433_Content_6 = {
    Text = "Pada hari keberangkatannya dari Lermwah, Alva berdiri di tepi Sungai Suci, mengambil segenggam air sungai, dan meminumnya."
  },
  AvgDialog_45433_Content_7 = {
    Text = "Tidak ada yang berani bertanya, bagaimana rasanya menyaksikan semua anggota sukumu berubah menjadi air sungai yang mengalir deras tepat di depan matamu sendiri."
  },
  AvgDialog_45433_Content_8 = {
    Text = "Namun, di tengah hujan lebat hari ini, ekspresi teguh Alva membuatmu yakin bahwa dia telah memutuskan langkah selanjutnya."
  },
  AvgDialog_45433_Content_9 = {
    Text = "Dalam penyelidikan lapangan kali ini, kami menghadapi musuh yang paling rumit, gagal menghentikan erosi Gereja Penerang Kuil terhadap Pohon Ibu, dan harus menerima hasil di mana etnis Aran dihapus dari sejarah."
  },
  AvgDialog_45434_Content_1 = {
    Text = "Kalian maju menyusuri jalan sempit di pabrik, berhati-hati agar tidak menyentuh mesin tua yang sudah berkarat dan akan mengeluarkan suara berderit jika tersentuh."
  },
  AvgDialog_45434_Content_10 = {
    Text = [[
Namun, saya bersedia mempercayai Penjaga.
Seperti Mythag yang memilih untuk mempercayai Penjaga.]]
  },
  AvgDialog_45434_Content_11 = {
    Text = "Tunggu, apakah di sana yang tadi disebutkan oleh prajurit itu——"
  },
  AvgDialog_45434_Content_12 = {
    Text = "Mengitari mesin berat, sebuah jendela pecah muncul di hadapanmu, dan yang mengintai di bawah jendela adalah monster raksasa yang sudah kalian kenal ——"
  },
  AvgDialog_45434_Content_2 = {
    Text = "Bahkan di Londinium, pabrik dengan skala sebesar ini tidak banyak."
  },
  AvgDialog_45434_Content_3 = {
    Text = "Hanya dalam beberapa dekade, tempat ini sudah menjadi sangat terbengkalai seperti sekarang."
  },
  AvgDialog_45434_Content_4 = {
    Text = [[
Pada tahun Hongji 308, Kerajaan Remouahe pernah secara terbuka mengundang Aram untuk menetap di ibu kota <Blue:Nasha>. 
 Jelas, mereka tidak menerima tanggapan apa pun.]]
  },
  AvgDialog_45434_Content_5 = {
    Text = "Orang Aram tidak memiliki kemampuan maupun keinginan untuk mempertahankan masyarakat industri secara mandiri. Mereka percaya pada kekuatan yang lebih primitif dan transendental."
  },
  AvgDialog_45434_Content_6 = {
    Text = "Saya mengira bahwa orang-orang di pihak kita mungkin lebih bisa memahami pemikiran mereka dibandingkan dengan masyarakat pada umumnya."
  },
  AvgDialog_45434_Content_7 = {
    Text = "Apakah kamu percaya <Yellow:Teknologi Inti Perak> dapat mengubah masa depan umat manusia?"
  },
  AvgDialog_45434_Content_8 = {
    Text = "Kami tidak tahu apa pun tentang masa depan umat manusia. Tiga ratus tahun penelitian belum membuat kami benar-benar menyentuh kebenaran tentang pelarutan."
  },
  AvgDialog_45434_Content_9 = {
    Text = "Mungkin setiap jalan dapat membawa ke akhir, mungkin setiap jalan menuju kehancuran."
  },
  AvgDialog_45435_Content_1 = {Text = "Magis"},
  AvgDialog_45435_Content_11 = {
    Text = "Kata-kata kosong tidak ada gunanya, kami akan merebut kembali Sisa Pohon Suci dan mengembalikannya pada Aylan."
  },
  AvgDialog_45435_Content_12 = {
    Text = "Alva tenggelam dalam pikiran mendalam, tidak tahu apakah dia mempercayai perkataan kalian."
  },
  AvgDialog_45435_Content_13 = {
    Text = "Setelah beberapa saat, tampaknya dia akhirnya membuat keputusan."
  },
  AvgDialog_45435_Content_14 = {
    Text = "Tim akan berangkat menuju Dinding Badai pada siang hari esok."
  },
  AvgDialog_45435_Content_15 = {
    Text = "Sebelum itu, saya harus melihat sisa pohon suci."
  },
  AvgDialog_45435_Content_16 = {
    Text = "Kalau tidak, tolong jangan muncul lagi di depanku."
  },
  AvgDialog_45435_Content_17 = {
    Text = "Alva dan para prajurit pergi secara bergiliran, pabrik yang kosong itu kini hanya menyisakan kalian bertiga."
  },
  AvgDialog_45435_Content_18 = {
    Text = "Cukup hebat, sangat panjang lebar."
  },
  AvgDialog_45435_Content_19 = {
    Text = "Alva tidak percaya kepada kita, dia hanya membutuhkan sebuah penjelasan."
  },
  AvgDialog_45435_Content_2 = {
    Text = "<Small:Haruskah kita katakan bahwa ini adalah kegagalan di antara seratus kehati-hatian? Tulang orang ini memang lebih keras daripada yang kita bayangkan.>"
  },
  AvgDialog_45435_Content_20 = {
    Text = "Saat ini, sisa pohon suci jelas bukan di tangan kita, baik memaksa kita menyerahkannya, maupun memanfaatkan kekuatan kita untuk menemukannya, lebih sesuai dengan kepentingannya ketimbang menciptakan konflik dengan kita."
  },
  AvgDialog_45435_Content_21 = {
    Text = "Bisakah kamu menemukan Sisa pohon suci dalam satu hari?"
  },
  AvgDialog_45435_Content_22 = {
    Text = "Hanya bisa dibilang ada sedikit petunjuk, layak untuk dicoba."
  },
  AvgDialog_45435_Content_23 = {
    Text = "Kamu menutup kedua matamu dan tenggelam ke dalam lautan kesadaran."
  },
  AvgDialog_45435_Content_24 = {
    Text = "Suara nyanyian seperti doa terdengar ——"
  },
  AvgDialog_45435_Content_25 = {
    Text = "Kematian sudah mendekat, kehancuran telah dimulai."
  },
  AvgDialog_45435_Content_26 = {
    Text = "Kerangka ibu tidak terlihat, darah dan benih hanyut di bumi, dilahap oleh binatang liar yang baru lahir."
  },
  AvgDialog_45435_Content_27 = {
    Text = "Tawa kecil membuyarkan pikiranmu. Kamu mengangkat kepala dan tanpa sadar, sosok seorang wanita telah muncul di atas peti mati."
  },
  AvgDialog_45435_Content_28 = {
    Text = "Bisakah aku menyerahkan mereka kepadamu dengan damai?"
  },
  AvgDialog_45435_Content_3 = {
    Text = [[
Ryker menggaruk bagian belakang kepalanya. 
 Prajurit Aran yang teguh memberinya tatapan tajam. Ryker menyeringai, dan lawannya langsung menarik diri kembali.]]
  },
  AvgDialog_45435_Content_30 = {
    Text = "Pikiran yang kacau muncul di benakmu, terpotong-potong, lalu bergabung."
  },
  AvgDialog_45435_Content_31 = {
    Text = "Sebuah benang pemicu tak berwarna yang lemah dan samar terbentuk, mengarah pada jawaban akhir."
  },
  AvgDialog_45435_Content_32 = {
    Text = "Sisa pohon suci ada di sini."
  },
  AvgDialog_45435_Content_33 = {
    Text = "Kamu dengan lembut mengusap dinding itu, lalu menutup mata, tanpa ragu memasukkan tanganmu, merasakan sepotong kain yang lembut, lalu menariknya keluar——"
  },
  AvgDialog_45435_Content_34 = {
    Text = "Eh, berhenti berhenti berhenti——"
  },
  AvgDialog_45435_Content_35 = {
    Text = "\"Dinding\"hancur berantakan, cahaya palsu digantikan oleh sinar matahari yang nyata, terangnya agak menyilaukan."
  },
  AvgDialog_45435_Content_36 = {
    Text = "Sial, jubah Casiah sampai miring!"
  },
  AvgDialog_45435_Content_37 = {
    Text = "Haruskah aku katakan bahwa pertemuan dengan musuh membuat darah mendidih, ataukah persahabatan sebagai alumni yang membawa kita melangkah bersama sedikit demi sedikit?"
  },
  AvgDialog_45435_Content_38 = {
    Text = "Penelitian Francis terbatas pada pelarutan, sandi rahasia di sanatorium itu disusun olehmu."
  },
  AvgDialog_45435_Content_39 = {
    Text = "Mungkin subjek eksperimen ini bisa menyusup ke pabrik saat para penjaga lengah, tetapi memindahkan kerangka adalah pekerjaan besar, dan tidak mungkin dilakukan tanpa suara."
  },
  AvgDialog_45435_Content_4 = {
    Text = "Tuan Alva, saya mengundang mereka untuk menjadi penjaga Sisa pohon suci..."
  },
  AvgDialog_45435_Content_40 = {
    Text = "Kami tidak bisa melihat kerangka, ini adalah <Blue:Ilusi> —— dinding ini telah kamu geser ke dalam sejauh dua meter."
  },
  AvgDialog_45435_Content_41 = {
    Text = "Hebat sekali, kamu jauh lebih baik dibandingkan saat terakhir kita bertemu. Saat itu, kamu hanya tahu cara meninggalkan rekan setim untuk melarikan diri."
  },
  AvgDialog_45435_Content_42 = {
    Text = "Jadi, Casiah, ilusimu terlalu mudah untuk dihilangkan."
  },
  AvgDialog_45435_Content_43 = {
    Text = "Hmph, harga sesuai kualitas, kan? Setiap orang dari Mythag yang bertugas di lapangan memiliki kendali emosi yang baik, namun mereka tidak mendapatkan banyak bayaran."
  },
  AvgDialog_45435_Content_44 = {
    Text = "Bukan tidak ada yang lebih tinggi, langsung meminta Nona Narsis membuka pintu untuk mengeluarkan peti kecil ini juga tidak sulit, hanya saja..."
  },
  AvgDialog_45435_Content_45 = {Text = "Hmm?"},
  AvgDialog_45435_Content_46 = {
    Text = "Harus tambah bayaran!"
  },
  AvgDialog_45435_Content_47 = {
    Text = "Wanita Narsis juga bukan tidak tahu kondisi keuangan saya, benar-benar menguras saya habis. Bukankah dia hanya kehilangan seorang pelanggan lama?"
  },
  AvgDialog_45435_Content_48 = {
    Text = "Aliran air yang tenang dan stabil adalah kunci untuk rencana jangka panjang."
  },
  AvgDialog_45435_Content_49 = {
    Text = "Huh, huh, bagaimana kalau kalian berdua menunggu sampai urusan di sini selesai, lalu kita diskusikan masalah harga?"
  },
  AvgDialog_45435_Content_5 = {
    Text = "Jadi mereka bisa mengikat tentara saya dan menyiksa untuk mencari lokasi Sisa Pohon Suci?"
  },
  AvgDialog_45435_Content_50 = {
    Text = "Ryker memainkan dadu di tangannya, lalu melemparkannya dengan keras ——"
  },
  AvgDialog_45435_Content_51 = {
    Text = [[
Topi sulap terbang ke udara, menangkap dadu yang meluncur cepat, lalu kembali ke tangan pemiliknya. 
 Casiah menarik tepi topi dan mengguncangkannya, serbuk dadu yang hancur menjadi bubuk berjatuhan.]]
  },
  AvgDialog_45435_Content_52 = {
    Text = "Lihat, mereka juga tidak akan membiarkanmu pergi begitu saja."
  },
  AvgDialog_45435_Content_53 = {
    Text = "Teman-teman dari Universitas Mythag, demi hubungan alumni, bagaimana kalau kita saling mundur selangkah?"
  },
  AvgDialog_45435_Content_54 = {
    Text = "Saya datang untuk sisa pohon suci, dan dari posisi Mythag, pasti berharap <Yellow:menghapus pencemaran sisa pohon suci>, agar tidak mencemari sungai suci."
  },
  AvgDialog_45435_Content_55 = {
    Text = "Mari kita lakukan kesepakatan, Sisa Pohon Suci menjadi milikku, Pohon Ibu tentu saja tidak akan terlahir kembali, semua orang bisa pulang dengan leluasa, tidakkah ini saling menguntungkan?"
  },
  AvgDialog_45435_Content_56 = {
    Text = "<Yellow:Kontaminasi Sisa Pohon Suci>? Sepertinya informasi tentang pohon suci yang dijual oleh Narsis kepada Para Pematung lebih banyak daripada kami."
  },
  AvgDialog_45435_Content_57 = {
    Text = "Dengan demikian, kita tidak dapat menyerahkan sisa pohon suci ini begitu saja."
  },
  AvgDialog_45435_Content_58 = {
    Text = "Kalau begitu, biarkan pertunjukan sihir Casiah dimulai lebih awal!"
  },
  AvgDialog_45435_Content_6 = {
    Text = "Mengingat monster yang baru saja kamu temui secara kebetulan, kamu segera memutar otak."
  },
  AvgDialog_45435_Content_7 = {
    Text = "Tadi, kami menyaksikan presidenPerkumpulan Pematung Herbert memasuki pabrik yang terletak di sisa pohon suci, yaitu di tempat ini."
  },
  AvgDialog_45435_Content_8 = {
    Text = "Orang ini Herbert demi kepentingan pribadi, berusaha merebut artefak dengan kemampuan khusus, kami curiga dia mengincar kekuatan sisa pohon suci."
  },
  AvgDialog_45435_Content_9 = {
    Text = "Karena keadaan mendesak, kami terpaksa memaksa tentara untuk memberi tahu kami lokasi kerangka tersebut, namun sayangnya tetap terlambat."
  },
  AvgDialog_45436_Content_1 = {Text = "Benih Api"},
  AvgDialog_45436_Content_2 = {
    Text = "Mengapa... sisa pohon suci masih ada..."
  },
  AvgDialog_45436_Content_3 = {
    Text = "Apakah kamu masih belum mengerti? Yang disebut kerangka Pohon Ibu hanyalah kedok."
  },
  AvgDialog_45436_Content_4 = {
    Text = "Yang kami butuhkan hanyalah \"Utusan dari Negeri Asing\" dan \"Caro Aram\" saja."
  },
  AvgDialog_45436_Content_5 = {
    Text = "Saat ini, utusan bodoh dari negeri asing telah membuka Dinding Badai untukku, dan orang-orang Aram juga telah meminum air sungai yang bercampur dengan abu dari lentera."
  },
  AvgDialog_45436_Content_6 = {
    Text = "Harapanku telah berada di jalur yang benar, sisanya hanya perlu menunggu Pohon Ibu tumbuh."
  },
  AvgDialog_45436_Content_7 = {
    Text = "Ah, aku sudah tidak sabar untuk melihat saat ketika pelarutan menyebar di seluruh bumi, dan gerbang ranah dewa terbuka sepenuhnya…"
  },
  AvgDialog_45437_Content_1 = {Text = "Kalung"},
  AvgDialog_45437_Content_10 = {
    Text = "Kerumunan masih belum membubarkan diri."
  },
  AvgDialog_45437_Content_11 = {
    Text = "Baiklah, semuanya, kembali ke urusan masing-masing."
  },
  AvgDialog_45437_Content_12 = {
    Text = "Dua hari lagi kita akan berangkat menuju Dinding Badai, aku juga perlu beristirahat dengan baik!"
  },
  AvgDialog_45437_Content_13 = {
    Text = "Kami membersihkan kamar setiap hari, hanya menunggu Anda kembali. Baru saja kami juga sudah meminta seseorang untuk menyalakan dupa penenang. Pohon Ibu bersaksi, semoga Anda dapat menikmati tidur yang nyenyak dan damai."
  },
  AvgDialog_45437_Content_14 = {
    Text = "Di sudut yang tidak mencolok, Thais melompat turun dari peti mati dan dengan mudah mengalir ke dalam kerumunan."
  },
  AvgDialog_45437_Content_15 = {
    Text = "Apakah kamu sudah memperhatikan ke mana arah sisa pohon suci?"
  },
  AvgDialog_45437_Content_16 = {
    Text = "Sudah lama Penjaga terus mengamati."
  },
  AvgDialog_45437_Content_17 = {
    Text = "Eh, di mana Penjaga?"
  },
  AvgDialog_45437_Content_18 = {
    Text = "Permisi, mohon beri jalan."
  },
  AvgDialog_45437_Content_19 = {
    Text = "Kamu melewati dua tikungan, mendorong dirimu melalui kerumunan orang yang berdesakan, sambil mencari-cari sosok itu dengan pandanganmu."
  },
  AvgDialog_45437_Content_2 = {
    Text = "Pasar di depan... begitu banyak orang!"
  },
  AvgDialog_45437_Content_20 = {
    Text = "Rasa cemas karena kehilangan jejak muncul di benakmu, dan kamu dengan enggan bersiap kembali ke tim. Namun, saat itulah kamu melihat Thais berdiri di balik bayangan gedung kecil, tersenyum sambil melambaikan tangan ke arahmu."
  },
  AvgDialog_45437_Content_21 = {
    Text = "Apakah kamu sedang mencari aku?"
  },
  AvgDialog_45437_Content_22 = {
    Text = "Kamu mengikuti Thais dari belakang, dia berjalan dengan sangat tenang melewati jalan-jalan."
  },
  AvgDialog_45437_Content_23 = {
    Text = "Saat melewati sebuah kios kecil yang penuh dengan aksesoris, dia akhirnya berhenti, berbalik, dan berbisik di telingamu sambil membungkuk."
  },
  AvgDialog_45437_Content_24 = {
    Text = "Bisakah kamu memberikan ini kepadaku?"
  },
  AvgDialog_45437_Content_25 = {
    Text = "Kamu mengikuti arah jarinya, dan pandanganmu tertuju pada sebuah kalung logam."
  },
  AvgDialog_45437_Content_26 = {
    Text = "Tamu memiliki mata yang tajam! Apakah Anda ingin melihat kalung ini?"
  },
  AvgDialog_45437_Content_27 = {
    Text = "Ini dipilih dan dibuat oleh putri saya sendiri, terutama batu lapis lazuli di tengah ini. Teksturnya seragam dan warnanya sangat halus. Anda yang sangat paham pasti bisa melihat kualitasnya!"
  },
  AvgDialog_45437_Content_28 = {
    Text = "Jangan gunakan lapis lazuli."
  },
  AvgDialog_45437_Content_29 = {
    Text = "Tidak mau Lapis Lazuli?"
  },
  AvgDialog_45437_Content_3 = {
    Text = "Utusan! Itu adalah rombongan utusan yang kembali!"
  },
  AvgDialog_45437_Content_30 = {
    Text = "Ah? Lapis lazuli adalah sentuhan akhir yang sempurna untuk kalung ini, apakah Anda yakin tidak menginginkannya?"
  },
  AvgDialog_45437_Content_31 = {
    Text = "Jika menambahkan batu lazurit ini, dana yang disiapkan Mythag untukmu akan sangat terbatas."
  },
  AvgDialog_45437_Content_32 = {
    Text = "Hmm, tidak memerlukan Lapis Lazuli."
  },
  AvgDialog_45437_Content_33 = {
    Text = "Baiklah, bungkus untuk tamu ini."
  },
  AvgDialog_45437_Content_34 = {
    Text = "Kamu dan Thais berjalan hingga keluar dari desa. Yang terlihat hanyalah angin dan pasir di mana-mana, beberapa burung nasar melintasi langit, meninggalkan suara tangisan yang terdengar seperti jeritan tua."
  },
  AvgDialog_45437_Content_35 = {
    Text = "Keterampilan keluarga Kara, diwariskan dari generasi ke generasi hingga saat ini, masih sangat luar biasa."
  },
  AvgDialog_45437_Content_36 = {
    Text = "Dia dengan lembut mengusap bekas goresan pada kalungnya, lalu membalikkan tempat permata ke arahmu untuk menunjukkannya."
  },
  AvgDialog_45437_Content_37 = {
    Text = "Pola ini adalah simbol dari Pohon Ibu, dan juga digambar oleh tanganku sendiri."
  },
  AvgDialog_45437_Content_38 = {
    Text = "Utusan dari tempat jauh, bisakah kau membantuku memakaikan kalung ini?"
  },
  AvgDialog_45437_Content_39 = {
    Text = "Kamu mengambil kalung sesuai instruksi, Thais sedikit menundukkan kepalanya, membiarkan lenganmu melingkari kepalanya dan lehernya, napas saling terasa."
  },
  AvgDialog_45437_Content_4 = {
    Text = "Penduduk desa memadati jalan sempit hingga tak ada celah, di tangan mereka terdapat persembahan untuk Juliette."
  },
  AvgDialog_45437_Content_40 = {
    Text = "Sebuah permata yang menyerupai giok putih tersemat di tengah liontin, dengan warna putih bersinar yang samar-samar memancarkan merah Hidup, seperti wajah gadis yang malu-malu, memperlihatkan keanggunan yang tepat."
  },
  AvgDialog_45437_Content_41 = {
    Text = [[
Hmm, aku sangat menyukainya. Demi hadiah ini, aku akan menjawab pertanyaanmu, oke?
Kamu pasti punya banyak pertanyaan yang ingin diajukan, kan?]]
  },
  AvgDialog_45437_Content_42 = {
    Text = "Namun, sebelum itu, beberapa orang yang tidak berniat baik telah tiba. Mari kita hukum bersama-sama monster kecil yang tidak peka ini, ya?"
  },
  AvgDialog_45437_Content_5 = {
    Text = "Untuk Yang Terhormat Utusan, ini adalah persembahan untukmu!"
  },
  AvgDialog_45437_Content_6 = {
    Text = "Di bagian belakang tim, Thais duduk santai di atas peti mati, dibawa masuk oleh empat prajurit Alan."
  },
  AvgDialog_45437_Content_7 = {
    Text = "Dibandingkan dengan sambutan hangat yang diterima Juliette, sorakan yang dia terima begitu jarang sehingga gelar Ratu terasa kurang pantas."
  },
  AvgDialog_45437_Content_8 = {
    Text = "Terima kasih kepada kalian semua. Matahari terik menguji setiap orang yang melangkah ke gurun, semangat kalian seperti air sungai suci, sulit untuk dilupakan."
  },
  AvgDialog_45437_Content_9 = {
    Text = "Sepertinya kalian semua sudah lelah, silakan kembali ke tempat masing-masing dan nikmati ketenangan malam."
  },
  AvgDialog_45438_Content_1 = {
    Text = "Juliette... mengapa..."
  },
  AvgDialog_45438_Content_2 = {
    Text = "Sudah sampai pada titik ini, tidak ada lagi yang perlu dihindari."
  },
  AvgDialog_45438_Content_3 = {
    Text = "Aram mempertahankan kelangsungan hidup spesies mereka dengan mengorbankan darah orang-orang cacat; keberadaan kalian adalah noda dan dosa."
  },
  AvgDialog_45438_Content_4 = {
    Text = "Orang yang dilahirkan dengan dosa asal hanya pantas menjadi kayu bakar untuk meletakkan fondasi Ranah dewa."
  },
  AvgDialog_45438_Content_5 = {
    Text = "Dan anak yang paling berharga sudah ada dalam genggamanku, menjadi kandidat yang memenuhi syarat untuk pergi ke dunia baru."
  },
  AvgDialog_45438_Content_6 = {
    Text = "Di hadapan Alva, seekor anjing berwajah manusia sedang merunduk di tanah."
  },
  AvgDialog_45438_Content_7 = {
    Text = "Anak yang sangat patuh, pantas menjadi pilihan saya."
  },
  AvgDialog_45438_Content_8 = {
    Text = "Nefr… Rurui…"
  },
  AvgDialog_45438_Content_9 = {
    Text = "Pergilah, anak, untuk melindungi kelahiran kembali Pohon Ibu, robeklah musuhmu."
  },
  AvgDialog_45439_Content_1 = {
    Text = "Apa yang begitu berisik?"
  },
  AvgDialog_45439_Content_10 = {
    Text = "Apa bukti yang kamu miliki?"
  },
  AvgDialog_45439_Content_11 = {
    Text = [[
Kematian tragis William muncul di hadapanmu. 
 Dia tewas akibat serangan monster yang sangat kejam, dan hal ini erat kaitannya dengan Gereja Penerang Kuil.]]
  },
  AvgDialog_45439_Content_12 = {
    Text = "Namun, tuduhan terhadap Juliette... kamu tidak bisa memberikan bukti apa pun."
  },
  AvgDialog_45439_Content_13 = {
    Text = "Tolong ingat kembali dengan baik, hari-hari yang telah kita lalui bersama."
  },
  AvgDialog_45439_Content_14 = {
    Text = "Apakah kamu akan mendengarkan omong kosong %hisorher%?"
  },
  AvgDialog_45439_Content_15 = {
    Text = "Suara-suara keraguan terus bermunculan, tanpa sedikit pun rasa percaya terhadapmu."
  },
  AvgDialog_45439_Content_16 = {
    Text = "%player%, aku juga sangat sedih. Sejauh ini, aku selalu mempercayaimu, mengabaikan berbagai sikap kasarmu di Alan, bahkan aku telah memohon kepada kepala suku untukmu."
  },
  AvgDialog_45439_Content_17 = {
    Text = "Sekarang setelah kupikirkan lagi, memang aku yang keliru menilaimu."
  },
  AvgDialog_45439_Content_18 = {
    Text = "Tuan Alva, mohon maafkan kesalahanku."
  },
  AvgDialog_45439_Content_19 = {
    Text = "Tidak peduli bagaimana perselisihan antara kamu dan Juliette pada akhirnya diselesaikan, hari ini, upacara harus dilanjutkan hingga selesai."
  },
  AvgDialog_45439_Content_2 = {
    Text = "Kerumunan memberikan jalan."
  },
  AvgDialog_45439_Content_20 = {
    Text = "Siapa pun yang menghalangi kelahiran kembali Pohon Ibu akan menjadi korban di jalan menuju kebangkitan Pohon Ibu!"
  },
  AvgDialog_45439_Content_3 = {Text = "Kalian?"},
  AvgDialog_45439_Content_4 = {
    Text = "Ya, kami memiliki hal penting untuk dilaporkan."
  },
  AvgDialog_45439_Content_5 = {
    Text = "Juliette... telah menipu kalian sepanjang waktu."
  },
  AvgDialog_45439_Content_6 = {
    Text = "Dia bukan utusan legendaris, dan dia juga tidak memiliki kekuatan ilahi untuk menghidupkan kembali Pohon Ibu."
  },
  AvgDialog_45439_Content_7 = {
    Text = "Dia bahkan tidak bisa mendapatkan akses ke Dinding Badai, karena Dinding Badai dibangun oleh Ratu Thais, penghalang yang memisahkan orang-orang dengan niat berbeda!"
  },
  AvgDialog_45439_Content_8 = {
    Text = "Kamu melihat sekeliling, Juliette berdiri di depan kerumunan. Sepertinya perkataanmu tidak menimbulkan riak apa pun di hatinya."
  },
  AvgDialog_45439_Content_9 = {
    Text = "Apa bukti yang kamu miliki untuk mendukung tuduhan seperti itu?"
  },
  AvgDialog_45440_Content_1 = {
    Text = "Juliette... akan... memberi hadiah padaku... kan..."
  },
  AvgDialog_45440_Content_2 = {
    Text = "Mm, anak yang baik, kamu benar-benar sangat membantu."
  },
  AvgDialog_45440_Content_3 = {
    Text = "Pohon ibu… sudah mulai terbentuk."
  },
  AvgDialog_45441_Content_1 = {Text = "Lawan"},
  AvgDialog_45441_Content_2 = {
    Text = "Ryker menendang pintu besi yang berkarat, menyebabkan debu dan asap beterbangan."
  },
  AvgDialog_45441_Content_3 = {
    Text = "Suara raungan aneh namun familiar, serta suara persendian berderak datang dari segala arah."
  },
  AvgDialog_45441_Content_4 = {
    Text = "Saya tidak salah lihat, kan? Itu adalah subjek percobaan yang dimodifikasi oleh Para pematung?"
  },
  AvgDialog_45441_Content_5 = {
    Text = "Saya juga melihatnya."
  },
  AvgDialog_45441_Content_6 = {
    Text = "Pertempuran besar. Aku mencium bau yang tidak sedap."
  },
  AvgDialog_45441_Content_7 = {
    Text = "Kerangka Pohon Ibu ada di paling dalam, dekat jendela!"
  },
  AvgDialog_45441_Content_8 = {
    Text = "Lebih baik kita lihat ke depan dulu, jika terus menunggu, takutnya dia akan buang air kecil di celananya."
  },
  AvgDialog_45442_Content_1 = {Text = "Mimpi"},
  AvgDialog_45442_Content_10 = {
    Text = "Begitu tidak bisa, Alva."
  },
  AvgDialog_45442_Content_101 = {
    Text = "Saya mendengar sebuah desahan yang dalam dan panjang."
  },
  AvgDialog_45442_Content_102 = {
    Text = "Pada akhirnya, boneka itu tetap tidak sempurna, masih membutuhkan terlalu banyak kelelahan untuk dikendalikan."
  },
  AvgDialog_45442_Content_103 = {
    Text = "Seberapa teguh tekadmu untuk berkorban demi Alan, setelah menyadari kebenarannya, kamu akan memberontak dengan sangat hebat."
  },
  AvgDialog_45442_Content_104 = {
    Text = "Untungnya, aku sudah memperkirakan situasi seperti ini sejak awal."
  },
  AvgDialog_45442_Content_105 = {
    Text = "Waktunya hampir tiba, kalian semua, untuk Pohon Ibu yang paling kalian cintai…"
  },
  AvgDialog_45442_Content_106 = {
    Text = "Persembahkan Caro dan Hidupmu."
  },
  AvgDialog_45442_Content_107 = {
    Text = [[
Saya membuka mulut, terkejut karena menyadari bahwa saya tidak bisa mengeluarkan suara. 
Segala sesuatu di sekitar saya tiba-tiba terhenti dalam keheningan yang mencekam.]]
  },
  AvgDialog_45442_Content_108 = {
    Text = "Bukan, yang diam bukan dunia, melainkan persepsi saya. Setiap kedipan kecil terasa seperti berlalunya satu abad."
  },
  AvgDialog_45442_Content_109 = {
    Text = "Di dalam urutan yang terhenti dan berkepanjangan, hanya rekan-rekanku sebelumnya, satu per satu tentara Aran, yang berlari tanpa henti menuju Sungai Suci."
  },
  AvgDialog_45442_Content_11 = {
    Text = "Bagaimana kalau begini, tadi <Blue:Halaiman> mengirimkan undangan. Dia telah menyiapkan anggur berkualitas tinggi dan mengundang saya untuk mencicipinya."
  },
  AvgDialog_45442_Content_110 = {
    Text = "Byurrr——"
  },
  AvgDialog_45442_Content_111 = {
    Text = "Dunia kembali dipenuhi suara dan warna."
  },
  AvgDialog_45442_Content_112 = {
    Text = "Mereka satu per satu, tanpa ragu melompat ke Sungai Suci yang mengalir deras, berusaha sepenuhnya merentangkan lengan mereka untuk memeluk batang tubuh kering Pohon Ibu."
  },
  AvgDialog_45442_Content_113 = {
    Text = "Mereka berteriak dengan penuh semangat, memancarkan teriakan kegilaan yang tak terlukiskan."
  },
  AvgDialog_45442_Content_114 = {
    Text = "Kulit mereka menjadi kendur, seolah-olah lumpur yang meleleh; cairan tubuh mereka terpisah dari daging, mengalir deras membentuk aliran Sungai Suci."
  },
  AvgDialog_45442_Content_115 = {
    Text = "Tulang mereka seolah-olah melunak seperti daging, anggota tubuh mereka berkelok, memanjang, dan saling membentuk jalinan dengan cara yang bukan manusiawi, menggunakan Caro mereka sendiri untuk membentuk batang pohon suci yang besar dan bengkak."
  },
  AvgDialog_45442_Content_116 = {
    Text = "Mereka dengan lambat dan menyakitkan menyatu dengan Pohon Suci."
  },
  AvgDialog_45442_Content_12 = {
    Text = "Mau pergi bersamaku, tidak pulang sebelum mabuk, bagaimana?"
  },
  AvgDialog_45442_Content_13 = {
    Text = "Thais, saya khawatir…"
  },
  AvgDialog_45442_Content_14 = {
    Text = "Prajurit bertindak atas perintah, bukankah itu yang kamu katakan?"
  },
  AvgDialog_45442_Content_15 = {
    Text = "Perintah saya adalah——tidak pulang sebelum mabuk."
  },
  AvgDialog_45442_Content_16 = {
    Text = "Apakah ada utopia tanpa darah dan air mata?"
  },
  AvgDialog_45442_Content_17 = {
    Text = "Benar-benar tak disangka, kamu tampak begitu kaku dan serius, tetapi ternyata dalam hatimu menyimpan mimpi yang begitu polos."
  },
  AvgDialog_45442_Content_18 = {
    Text = "Nyonya Thais, jangan tertawa padaku..."
  },
  AvgDialog_45442_Content_19 = {
    Text = "Bagaimana mungkin aku akan menertawakanmu."
  },
  AvgDialog_45442_Content_2 = {
    Text = "Alva, kamu telah dipanggil cukup lama. Setiap hari, selain latihan pagi, kamu hanya bekerja. Terakhir kali Karune mengundangmu ke pesta makan malam, kamu juga menolak."
  },
  AvgDialog_45442_Content_20 = {
    Text = "Dengan tulangku, darahku memelihara seluruh Lemvahi, memastikan aliran darah Aran terus mengalir."
  },
  AvgDialog_45442_Content_21 = {
    Text = "Mengembangbiakkan keturunan tanpa batas, berharap salah satu dari mereka dapat lolos dari pandangan sang dewasa itu, dan melanjutkan kehendak saya dalam siklus awal dan akhir…"
  },
  AvgDialog_45442_Content_22 = {
    Text = "Aku dan kamu, bukankah sama-sama naif dan konyol?"
  },
  AvgDialog_45442_Content_24 = {
    Text = "Apakah kamu sudah tertidur?"
  },
  AvgDialog_45442_Content_25 = {
    Text = "Lagipula, kamu memang bukan keturunan Aran, jadi tidak seharusnya terjebak di gurun tandus ini."
  },
  AvgDialog_45442_Content_26 = {
    Text = "Ketika hidupku mencapai akhir, tinggalkan Lemuwahi dan carilah Kontrak baru."
  },
  AvgDialog_45442_Content_27 = {
    Text = "Hari itu... sudah hampir tiba."
  },
  AvgDialog_45442_Content_28 = {
    Text = "Saya duduk di dalam tenda Ratu. Di luar, terdengar tangisan pilu dari upacara pemakaman yang dipenuhi dengan kesedihan, penderitaan, dan rasa tidak rela."
  },
  AvgDialog_45442_Content_29 = {
    Text = [[
Mampu menangis untuk seseorang yang dipercaya juga bisa dianggap sebagai sebuah keberuntungan. 
 Di medan perang, biasanya kami tidak memiliki waktu luang untuk meneteskan air mata bagi rekan yang telah gugur.]]
  },
  AvgDialog_45442_Content_3 = {
    Text = "Apakah kamu tidak menginginkan hadiah?"
  },
  AvgDialog_45442_Content_30 = {
    Text = [[
Bagi saya, yang lebih penting adalah ke mana orang Aram yang kehilangan ratu mereka harus pergi. 
 Jika orang Aram berhenti berpikir karena kesedihan, maka biarlah saya yang memikirkannya.]]
  },
  AvgDialog_45442_Content_31 = {
    Text = "Tuan Thais tidak percaya padaku, aku selalu tahu."
  },
  AvgDialog_45442_Content_32 = {
    Text = "Orang Aram membedakan kedekatan berdasarkan garis keturunan. Di mata mereka, saya selalu dianggap sebagai orang luar karena mengalir darah asing dalam diri saya."
  },
  AvgDialog_45442_Content_33 = {
    Text = "Namun, Aram membutuhkan pemimpin, baik dalam Roh maupun dalam kenyataan."
  },
  AvgDialog_45442_Content_34 = {
    Text = "Saya akan menjabat sebagai kepala suku, menjaga peti mati Thais."
  },
  AvgDialog_45442_Content_35 = {
    Text = "Setiap langkah masa depan bangsa Aran akan berjalan di bawah pengawasan <Red:Thais>."
  },
  AvgDialog_45442_Content_36 = {
    Text = "Setiap langkah masa depan bangsa Aran akan berjalan di bawah pandangan <Red:Yang Mulia Ratu>."
  },
  AvgDialog_45442_Content_37 = {
    Text = "Setiap langkah masa depan suku Yalan akan berjalan di bawah pengawasan <Red:@1 Yang Mulia>."
  },
  AvgDialog_45442_Content_39 = {
    Text = "Kenapa aku berada di sini?"
  },
  AvgDialog_45442_Content_4 = {
    Text = "Selama Arland tetap aman dan makmur, itu adalah hadiah terbaik bagi saya, Tuan Thais."
  },
  AvgDialog_45442_Content_40 = {
    Text = "Apa yang terdapat di dalam peti mati itu... benar, sepertinya adalah sisa pohon suci."
  },
  AvgDialog_45442_Content_41 = {
    Text = "Mengapa sisa pohon suci harus diletakkan di dalam tenda ratu?"
  },
  AvgDialog_45442_Content_42 = {
    Text = "Lupakan saja, aku tidak bisa memikirkannya."
  },
  AvgDialog_45442_Content_43 = {
    Text = "Tapi tidak masalah."
  },
  AvgDialog_45442_Content_44 = {
    Text = "<Big:Selama Pohon Ibu dilahirkan kembali, <Red:segalanya> akan baik-baik saja.>"
  },
  AvgDialog_45442_Content_46 = {
    Text = "Selama ratusan tahun dalam hidup saya, saya telah membimbing banyak penerus."
  },
  AvgDialog_45442_Content_47 = {
    Text = "Saya percaya akan ada seorang pahlawan yang membawa fajar bagi Aran."
  },
  AvgDialog_45442_Content_48 = {
    Text = "Penerus pertama tewas akibat bisa ular."
  },
  AvgDialog_45442_Content_49 = {
    Text = "Penerus kedua meninggal dalam badai."
  },
  AvgDialog_45442_Content_5 = {
    Text = "Kamu sama sekali tidak menyukai Aran, kan? Kamu bahkan menolak untuk menghadiri pesta api unggun."
  },
  AvgDialog_45442_Content_50 = {
    Text = "Penerus ketiga tewas akibat kebencian dan iri orang lain."
  },
  AvgDialog_45442_Content_51 = {
    Text = "Ada terlalu banyak kejutan dan ketidakpastian di gurun. Ras yang paling lama bertahan hidup di gurun bukanlah elang mahkota tinggi yang ganas atau ular tanduk gurun yang sangat beracun, melainkan semut perak yang hanya aktif selama sepuluh menit setiap hari."
  },
  AvgDialog_45442_Content_52 = {
    Text = "Menaruh harapan pada individu tertentu terlalu bodoh bagi Aran."
  },
  AvgDialog_45442_Content_53 = {
    Text = [[
Sementara kecepatan penurunan populasi benar-benar tidak memberi kesempatan bagi manusia. 
 Cukup satu badai yang tak terduga saja, beberapa kelompok orang bisa tersapu habis.]]
  },
  AvgDialog_45442_Content_54 = {
    Text = "Pada saat yang paling sedikit, pasukan Aran menyusut hingga kurang dari seratus orang."
  },
  AvgDialog_45442_Content_55 = {
    Text = "<Red: Jika terus berlanjut seperti ini, Klan Alan akan punah di tanganku.>"
  },
  AvgDialog_45442_Content_56 = {
    Text = "Besok malam… mulai kembali acara api unggun."
  },
  AvgDialog_45442_Content_57 = {
    Text = [[
Di pesta malam itu, mereka bernyanyi dan minum dengan riang. 
Pada saat fajar tiba, lahirlah bayi yang lahir dari satu malam tersebut.]]
  },
  AvgDialog_45442_Content_58 = {
    Text = "Saat mengangkat bayi yang baru lahir itu, aku tak dapat menahan air mata kebahagiaan."
  },
  AvgDialog_45442_Content_59 = {
    Text = "Kekuasaan Pohon Ibu adalah keajaiban yang diberikan oleh surga kepada Arlan, dan aku bahkan menolaknya sebagai sesuatu yang aneh karena pandanganku yang sempit dan dangkal."
  },
  AvgDialog_45442_Content_6 = {
    Text = [[
Tak perlu berkilah, aku bisa melihat semuanya. 
Di sini semua orang adalah orang gila yang bertindak sesuka hati, dan mereka tidak cocok denganmu.]]
  },
  AvgDialog_45442_Content_60 = {Text = "Hanya..."},
  AvgDialog_45442_Content_61 = {
    Text = "Kekuatan ilahi Pohon Ibu terus melemah."
  },
  AvgDialog_45442_Content_62 = {
    Text = "Janin cacat semakin bertambah."
  },
  AvgDialog_45442_Content_63 = {
    Text = "Saya merasa sangat kewalahan hingga seorang wanita paruh baya secara kebetulan menyebutkan ——"
  },
  AvgDialog_45442_Content_64 = {
    Text = "Apakah Anda masih ingat nyanyian itu?"
  },
  AvgDialog_45442_Content_65 = {
    Text = "Kematian sudah mendekat, kehancuran telah dimulai."
  },
  AvgDialog_45442_Content_66 = {
    Text = "Kerangka ibu tidak terlihat, darah dan benih hanyut di bumi, dilahap oleh binatang liar yang baru lahir."
  },
  AvgDialog_45442_Content_67 = {
    Text = "Langit dan para dewa dipenuhi awan mendung, hingga Kedatangan utusan dari negeri asing."
  },
  AvgDialog_45442_Content_68 = {
    Text = "Pohon Ibu melahirkan kembali Sungai Suci, memberikan mahkota kepada yang telah tiada, dan mengembalikan garis keturunan kepada Alen."
  },
  AvgDialog_45442_Content_69 = {
    Text = "Asalkan bisa menemukan <Yellow:Utusan Asing>, mungkin kita bisa menyaksikan kelahiran kembali Pohon Ibu!"
  },
  AvgDialog_45442_Content_7 = {
    Text = "Namun, apakah kamu tidak merasa bosan menjalani hidup yang hanya didasarkan pada tanggung jawab saja?"
  },
  AvgDialog_45442_Content_70 = {
    Text = "Thais, Thais——!"
  },
  AvgDialog_45442_Content_71 = {
    Text = "Seseorang, memanggil nama seseorang."
  },
  AvgDialog_45442_Content_72 = {
    Text = "Kepala terasa seperti akan meledak, ribuan jarum perak menusuk otak secara liar. Suara bising yang tajam merobek gendang telinga, namun suara aliran darah di dalam pembuluh darah masih terdengar dengan jelas."
  },
  AvgDialog_45442_Content_73 = {
    Text = "<Big:Thais, Thais——!>"
  },
  AvgDialog_45442_Content_74 = {
    Text = "Thais, siapa itu?"
  },
  AvgDialog_45442_Content_75 = {
    Text = "Jangan hiraukan suara-suara mengganggu itu, karena mereka hanya akan mengalihkan fokusmu."
  },
  AvgDialog_45442_Content_76 = {
    Text = "Pohon Ibu akan segera kembali ke bumi, apakah kamu tidak merasa gembira karenanya?"
  },
  AvgDialog_45442_Content_77 = {
    Text = "Saya yakin pernah mendengar nama Thais di suatu tempat."
  },
  AvgDialog_45442_Content_78 = {
    Text = "Tapi, sebenarnya di mana tempat itu?"
  },
  AvgDialog_45442_Content_79 = {
    Text = [[
Medan perang yang berubah dalam sekejap saat masih hidup, senyuman rekan tempur di detik-detik terakhir, jawaban dingin dan tanpa ampun dari komandan... 
 Bukan, bukan itu.]]
  },
  AvgDialog_45442_Content_8 = {
    Text = [[
Pemimpin Thais, Anda mengetahuinya. 
Saya dulunya seorang tentara. Seorang tentara selalu melaksanakan perintah.]]
  },
  AvgDialog_45442_Content_80 = {
    Text = "Setelah Bangun, bekerja keras hari demi hari, mengorganisir pesta, melawan kawanan binatang buas…"
  },
  AvgDialog_45442_Content_81 = {
    Text = "Setelah Bangun...?"
  },
  AvgDialog_45442_Content_82 = {
    Text = "Siapa yang Bangun aku?"
  },
  AvgDialog_45442_Content_84 = {
    Text = "<Red:Thais.>"
  },
  AvgDialog_45442_Content_85 = {
    Text = "Kenapa bisa melupakan namanya?"
  },
  AvgDialog_45442_Content_86 = {
    Text = "Aku setiap hari, selalu memanggilnya—"
  },
  AvgDialog_45442_Content_87 = {
    Text = "Di tengah badai pasir, muncul sosok yang selalu kuingat siang dan malam."
  },
  AvgDialog_45442_Content_88 = {
    Text = "Setiap langkahnya tercetak dengan berat di tanah yang terkikis oleh angin, membangkitkan gelombang emosi dalam dadaku hingga air mata panas mengalir deras."
  },
  AvgDialog_45442_Content_89 = {Text = "Thais..."},
  AvgDialog_45442_Content_9 = {
    Text = [[
Kamu adalah Tautanku. 
Melindungi Aran adalah keinginanmu, maka itu juga menjadi keinginanku.]]
  },
  AvgDialog_45442_Content_90 = {
    Text = [[
Saya selalu menunggu Anda. 
 Saya tahu Anda pasti akan kembali. Anda tak pernah melupakan Aran.]]
  },
  AvgDialog_45442_Content_91 = {
    Text = "Semua etnis Alan dengarkan baik-baik! Ramalan kuno telah digenapi, Pohon Ibu muncul kembali di dunia, dan kita harus memahkotai mereka yang telah tiada!"
  },
  AvgDialog_45442_Content_92 = {
    Text = "Ratu kembali melangkah di atas pasir, kembali ke Takhta!"
  },
  AvgDialog_45442_Content_93 = {
    Text = "Kepada satu-satunya Ratu Aran, Yang Mulia Thais——"
  },
  AvgDialog_45442_Content_94 = {
    Text = "Persembahkan kesetiaan dan tekad kalian!"
  },
  AvgDialog_45442_Content_95 = {
    Text = "Akhirnya, akhirnya aku berhasil bertahan hingga saat ini."
  },
  AvgDialog_45442_Content_96 = {
    Text = "Jadi, bisakah Anda memberikan saya sebuah pujian sekarang?"
  },
  AvgDialog_45442_Content_97 = {
    Text = "Memuji kesabaran saya selama ratusan tahun, keteguhan saya yang tak pernah pudar selama ratusan tahun, dan akhirnya setelah ratusan tahun menemukan utusan yang dapat menghidupkan kembali Pohon Ibu —"
  },
  AvgDialog_45442_Content_98 = {
    Text = "Bersama-sama, mari kita jadikan Aran sebagai negara ideal tanpa darah dan air mata, sebuah utopia yang murni tanpa cacat."
  },
  AvgDialog_45442_Content_99 = {
    Text = "Ah, Tuan Thais, mengapa Anda menggelengkan kepala kepada saya?"
  },
  AvgDialog_45443_Content_1 = {Text = "Kembali"},
  AvgDialog_45443_Content_10 = {
    Text = "Sendirian, kamu membutuhkan sekutu yang mendukungmu — wajah Thais muncul di hadapanmu."
  },
  AvgDialog_45443_Content_11 = {
    Text = [[
Satu-satunya hal yang perlu kamu lakukan adalah mempercayaiku sepenuhnya. 
Percayalah pada Ratu Aran.]]
  },
  AvgDialog_45443_Content_12 = {
    Text = "Dia pasti juga akan membalas dengan kepercayaan yang sama."
  },
  AvgDialog_45443_Content_13 = {
    Text = "Thais? Siapa?"
  },
  AvgDialog_45443_Content_14 = {
    Text = "Siapa lagi? Ratu kalian, Thais!"
  },
  AvgDialog_45443_Content_15 = {
    Text = "Apa kamu gila? Jika ingin bertemu dengan Yang Mulia, potong saja lehermu dengan pisau ini!"
  },
  AvgDialog_45443_Content_16 = {
    Text = "Ratu... ada masalah apa?"
  },
  AvgDialog_45443_Content_17 = {
    Text = "Apa lagi? Ratu sudah meninggal beberapa ratus tahun yang lalu. Jika kamu masih berbicara dengan tidak hormat, aku tidak akan tinggal diam!"
  },
  AvgDialog_45443_Content_18 = {
    Text = "Melihat ekspresi seriusnya, hatimu terasa seperti jatuh ke dalam jurang es."
  },
  AvgDialog_45443_Content_2 = {
    Text = "Hampir seribu keturunan Aran berkumpul di tepi Sungai Suci, lagu pujian yang rendah terdengar bergema dan menyebar, bersatu dengan suara raungan binatang buas dari kejauhan membentuk sebuah simfoni Kekacauan."
  },
  AvgDialog_45443_Content_20 = {
    Text = "Kamu menatap ke kejauhan, di pusat upacara."
  },
  AvgDialog_45443_Content_21 = {
    Text = [[
Peti mati terbaring diam di atas rak kayu Altar yang tinggi. 
Tentu saja, di sana tidak ada bayangan Thais yang pernah kamu lihat.]]
  },
  AvgDialog_45443_Content_22 = {
    Text = [[
Bukan hanya di sana. 
Tidak ada di mana pun.]]
  },
  AvgDialog_45443_Content_23 = {
    Text = "Tirai tenda didorong terbuka, seorang wanita Aran berusia akhir tiga puluhan dengan wajah serius melangkah masuk ke dalam tenda dengan langkah besar."
  },
  AvgDialog_45443_Content_24 = {
    Text = "Thais dengan cemas meloncat kembali ke atas peti mati, sikapnya anggun dan terlihat seperti seorang ratu yang angkuh di atas Takhta."
  },
  AvgDialog_45443_Content_25 = {
    Text = "Tamu yang terhormat, ..."
  },
  AvgDialog_45443_Content_26 = {
    Text = "<Red:Dengan tegas memotong suara berlagak soknya yang anggun.>"
  },
  AvgDialog_45443_Content_27 = {
    Text = "Alva tentu saja tidak akan \"menginterupsi\" deklarasi Ratu."
  },
  AvgDialog_45443_Content_28 = {
    Text = "Utusan! Itu adalah rombongan utusan yang kembali!"
  },
  AvgDialog_45443_Content_29 = {
    Text = "Penduduk desa memadati jalan sempit hingga tak ada celah, di tangan mereka terdapat persembahan untuk Juliette."
  },
  AvgDialog_45443_Content_3 = {
    Text = "Sebuah Altar kayu raksasa berdiri di tengah kerumunan, dengan peti mati yang diukir simbol-simbol sulit dipahami dipajang di atasnya, sementara pandangan sekitarnya bercampur antara ketakutan, fanatisme, dan antisipasi."
  },
  AvgDialog_45443_Content_30 = {
    Text = "Di bagian belakang tim, Thais duduk santai di atas peti mati, dibawa masuk oleh empat prajurit Alan."
  },
  AvgDialog_45443_Content_31 = {
    Text = "Dibandingkan dengan sambutan hangat yang diterima Juliette, <Red: sorakan yang diterimanya begitu jarang sehingga gelar Ratu terasa kurang sesuai dengan kenyataan>."
  },
  AvgDialog_45443_Content_32 = {
    Text = "Di mata semua rakyat, tidak ada ratu yang duduk di atas kerangka."
  },
  AvgDialog_45443_Content_33 = {
    Text = "Bisakah kamu memberikan ini kepadaku?"
  },
  AvgDialog_45443_Content_34 = {
    Text = "Kamu mengikuti arah jarinya, dan pandanganmu tertuju pada sebuah kalung logam."
  },
  AvgDialog_45443_Content_35 = {
    Text = "Tamu memiliki mata yang tajam! Apakah Anda ingin melihat kalung ini?"
  },
  AvgDialog_45443_Content_36 = {
    Text = "Ini dibuat oleh putri saya sendiri, terutama batu lapis lazuli di tengah ini. Teksturnya seragam dan warnanya sangat halus. Anda yang paham barang pasti bisa mengenali kualitasnya!"
  },
  AvgDialog_45443_Content_37 = {
    Text = "Jangan gunakan lapis lazuli."
  },
  AvgDialog_45443_Content_38 = {
    Text = "Tidak mau Lapis Lazuli?"
  },
  AvgDialog_45443_Content_39 = {
    Text = "Apa? Apakah Anda yakin tidak ingin Lapis Lazuli?"
  },
  AvgDialog_45443_Content_4 = {
    Text = "Begitu kamu baru saja melangkah masuk, kamu langsung menghadapi penolakan yang keras."
  },
  AvgDialog_45443_Content_40 = {
    Text = "Jika menambahkan batu lazurit ini, dana yang disiapkan Mythag untukmu akan sangat terbatas."
  },
  AvgDialog_45443_Content_41 = {
    Text = "Hmm, tidak memerlukan Lapis Lazuli."
  },
  AvgDialog_45443_Content_42 = {
    Text = "Baiklah, bungkus untuk <Red:Tamu ini>."
  },
  AvgDialog_45443_Content_43 = {
    Text = "Pemilik kios hanya merespons ucapanmu."
  },
  AvgDialog_45443_Content_44 = {
    Text = "Tidak jauh dari bukit pasir tersebut, kamu melihat sosok itu."
  },
  AvgDialog_45443_Content_45 = {
    Text = "Dari siluetnya, kamu mengenali bahwa itu Thais."
  },
  AvgDialog_45443_Content_46 = {
    Text = "Badai... apakah sudah mereda?"
  },
  AvgDialog_45443_Content_47 = {
    Text = "Dia melantunkan doa yang tak dikenal, membiarkan angin kencang menyeret jubah sutranya, melangkah perlahan namun mantap ke dalam badai pasir yang pekat."
  },
  AvgDialog_45443_Content_48 = {
    Text = "Dentuman terdengar memekakkan telinga, namun suara doa tetap terdengar dengan jelas, seolah-olah bergema di bagian dalam tengkorakmu."
  },
  AvgDialog_45443_Content_49 = {
    Text = "Di tengah badai yang menelan langit dan bumi, dia tampak seperti sedang berbicara dengan tenang kepada suatu makhluk hidup yang tinggal di gurun."
  },
  AvgDialog_45443_Content_5 = {Text = "Siapa!"},
  AvgDialog_45443_Content_50 = {
    Text = "Itu Ratu! Ratu datang untuk menyelamatkan kita, menyelamatkan Aran!"
  },
  AvgDialog_45443_Content_51 = {
    Text = "Tim Aran yang semula bersiap untuk melarikan diri tiba-tiba berhenti."
  },
  AvgDialog_45443_Content_52 = {
    Text = "Banyak orang Aram menghadap ke arah Thais dengan khidmat, lalu berlutut penuh kesungguhan."
  },
  AvgDialog_45443_Content_53 = {
    Text = [[
Namun, di ujung arah sujud mereka... 
 Di sana tidak ada apa-apa, hanya kamu yang bisa melihat ujung gaun Thais yang tertiup angin pasir.]]
  },
  AvgDialog_45443_Content_54 = {
    Text = "Sebagai pembawa tubuh esensi keinginan, keberadaan Pohon Ibu pasti telah meninggalkan jejak yang cukup dalam di Planet."
  },
  AvgDialog_45443_Content_55 = {
    Text = "Kehidupan yang gigih dari Pohon Ibu membuat kecepatan pelarutan terhadapnya menjadi ribuan hingga jutaan kali lebih lambat dibandingkan dengan manusia biasa."
  },
  AvgDialog_45443_Content_56 = {
    Text = "Jadi, <Red:bagimu, dia belum sepenuhnya menghilang>."
  },
  AvgDialog_45443_Content_57 = {
    Text = "Jika berlalu ratusan atau ribuan tahun lagi, <Red:Aram mungkin akan melupakan keberadaan Pohon ibu>."
  },
  AvgDialog_45443_Content_59 = {
    Text = "Mereka tak pernah melihat ratu bernama Thais. Apa yang mereka imani dan sujudi hanyalah ilusi yang tersebar dari mulut ke mulut."
  },
  AvgDialog_45443_Content_6 = {
    Text = "Sekarang adalah momen krusial dalam ritual, orang-orang yang tidak berkepentingan dilarang masuk!"
  },
  AvgDialog_45443_Content_60 = {
    Text = "Thais, yang membawamu berkeliling, menari untukmu, dan duduk di atas peti mati dengan sikap angkuh, <Red:tidak pernah ada di mata mereka>."
  },
  AvgDialog_45443_Content_61 = {
    Text = "Tapi kamu sangat yakin, sangat yakin——"
  },
  AvgDialog_45443_Content_62 = {
    Text = "Pastikan memori di bawah bulan malam."
  },
  AvgDialog_45443_Content_63 = {
    Text = "Pasti ada sisa kehangatan di ujung jarinya."
  },
  AvgDialog_45443_Content_64 = {
    Text = "Pastikan bisikannya yang lembut."
  },
  AvgDialog_45443_Content_65 = {
    Text = "Apakah kamu tahu? Aku melihat Clades di matamu, melihat abu dari zaman purba, dan melihat napas alam semesta."
  },
  AvgDialog_45443_Content_66 = {
    Text = "Perjalanan yang kau jalani sangat panjang, pasti sudah sangat lelah, bukan? Namun, tatapanmu masih begitu teguh, tanpa sedikit pun kekaburan."
  },
  AvgDialog_45443_Content_67 = {
    Text = "Bintang-bintang tidak dapat mengubahmu, dan Gurun Pasir mungkin juga tidak bisa."
  },
  AvgDialog_45443_Content_68 = {
    Text = [[
Napasnya terasa dekat denganmu. 
Lautan bintang membara di kedalaman matanya.]]
  },
  AvgDialog_45443_Content_69 = {
    Text = "Aku akan mengakhiri ritual Aran."
  },
  AvgDialog_45443_Content_7 = {
    Text = "Aku ingin bertemu Thais!"
  },
  AvgDialog_45443_Content_70 = {
    Text = "Thais… pasti menungguku di sana."
  },
  AvgDialog_45443_Content_8 = {
    Text = "Kamu tidak akan salah membaca petunjuk penting yang ditinggalkan William untukmu — Nubia, utusan palsu, pencemaran Pohon Ibu… semua ini adalah hasil dari tangan Gereja Penerang Kuil."
  },
  AvgDialog_45443_Content_9 = {
    Text = "Ramona, William, Ryker… rekan-rekan Mythag saat ini sudah pergi."
  },
  AvgDialog_45444_Content_1 = {
    Text = "Di bawah Pohon Ibu, Alva yang tak berdaya menangis sambil berlutut."
  },
  AvgDialog_45444_Content_10 = {
    Text = "Hanya di antara celah-celah sempit, bisa melihat cahaya dari dunia lain di luar."
  },
  AvgDialog_45444_Content_11 = {
    Text = "Tepat di celah sesaat itu, aku mengikuti rombongan Suku Alan berpindah-pindah dalam pengembaraan."
  },
  AvgDialog_45444_Content_12 = {
    Text = "Saya menyaksikan tekad Alva yang dengan tegas mengambil tanggung jawab besar di saat tidak ada pemimpin."
  },
  AvgDialog_45444_Content_13 = {
    Text = "Saya menyaksikan tekad Alva saat membatalkan ritual api unggun, penderitaan ketika calon penerus yang dibesarkan meninggal, dan rasa putus asa saat memulai kembali ritual api unggun."
  },
  AvgDialog_45444_Content_14 = {
    Text = "Menyaksikan Alva memimpin tim untuk mencari inventaris air dengan sibuk, serta menyaksikan perjuangannya saat melawan Nubia secara aktif."
  },
  AvgDialog_45444_Content_15 = {
    Text = "Alva, kamu sudah melakukan yang terbaik."
  },
  AvgDialog_45444_Content_16 = {
    Text = "Meskipun aku tetap di sini, aku tidak bisa berbuat lebih baik daripada dirimu."
  },
  AvgDialog_45444_Content_17 = {
    Text = "Jadi, serahkan urusan selanjutnya padaku."
  },
  AvgDialog_45444_Content_18 = {
    Text = "Thais mengelus kepala Alva, lalu berbalik untuk menghadapi ribuan prajurit Arlan yang kehilangan kesadaran."
  },
  AvgDialog_45444_Content_19 = {
    Text = "Aku adalah Ibu Bumi, manifestasi dari esensi keinginan."
  },
  AvgDialog_45444_Content_2 = {
    Text = "Yang Mulia... saya... maafkan aku... Aran..."
  },
  AvgDialog_45444_Content_20 = {
    Text = "Nama saya Thais, nama suci <Yellow:Tipharet Yesod>."
  },
  AvgDialog_45444_Content_21 = {
    Text = "Aku, satu-satunya Ratu Aran, mengutukmu, Pohon Ibu yang palsu, yang melahap makhluk hidup dan menyebarkan kematian."
  },
  AvgDialog_45444_Content_22 = {
    Text = "Aku akan membebaskan rakyat Aran dari dalam dirimu dan mencari jalan untuk kelangsungan hidup mereka."
  },
  AvgDialog_45444_Content_23 = {
    Text = "Wahai rakyat Aran, jika kalian masih bisa mendengar suaraku, bangunlah!"
  },
  AvgDialog_45444_Content_24 = {
    Text = "Dunia tenggelam dalam keheningan sesaat."
  },
  AvgDialog_45444_Content_25 = {
    Text = "Namun, hanya beberapa detik kemudian, tim Alan kembali jatuh ke Sungai Suci seperti lemming yang tak kenal lelah dan tak pernah menoleh ke belakang."
  },
  AvgDialog_45444_Content_26 = {
    Text = "Tidak ada gunanya, kamu dan Pohon Ibu memiliki akar yang sama, keduanya telah tercemar oleh kehendak orang itu. Dengan kekuatanmu saat ini, kamu sama sekali tidak bisa menggoyahkan kehendak Pohon Ibu yang telah terkikis."
  },
  AvgDialog_45444_Content_27 = {
    Text = "Tentu saja aku tahu."
  },
  AvgDialog_45444_Content_28 = {
    Text = "Jika tidak demikian, untuk apa melakukan perjalanan selama ratusan tahun ini?"
  },
  AvgDialog_45444_Content_29 = {
    Text = "Bukankah aku menyembunyikan tubuh Pohon Ibu di Sungai Suci, dan dengan tubuhku menanggung pelarutan untuk menyembunyikan benih Pohon Ibu, semua ini demi menunggu saat ini?"
  },
  AvgDialog_45444_Content_3 = {
    Text = "Tidak perlu khawatir. Suara hatimu, aku sudah mendengarnya."
  },
  AvgDialog_45444_Content_30 = {
    Text = "Saatnya pertempuran penentuan!"
  },
  AvgDialog_45444_Content_31 = {
    Text = "Dengan nama Tifare Yessod yang berwujud keinginan, aku mengajukan permintaan kepada <Yellow:Tawil>, tolong jawab perjanjian kita dari seribu tahun yang lalu——"
  },
  AvgDialog_45444_Content_32 = {
    Text = "Ketika utusan dari negeri asing tiba, dengan wujudmu sebagai pengantar, untuk sementara mengusir bayangan yang menyelimuti Lemwahsi."
  },
  AvgDialog_45444_Content_33 = {
    Text = "Di langit terdengar ratapan sedih yang lantang."
  },
  AvgDialog_45444_Content_34 = {
    Text = "Thais membuka peti mati, dan yang bangkit dari dalamnya adalah Ramona dengan wajah memerah karena terbakar."
  },
  AvgDialog_45444_Content_35 = {
    Text = "Akhirnya... apakah kau membutuhkanku..."
  },
  AvgDialog_45444_Content_36 = {
    Text = "Bersembunyi di sini dan mengikuti, sungguh ide yang cerdas, Nona Kecil."
  },
  AvgDialog_45444_Content_37 = {
    Text = "Untung juga kamu ikut, kalau tidak, setiap menit untuk kembali menjemputmu akan membuat Lelah entah berapa banyak Hidup."
  },
  AvgDialog_45444_Content_38 = {
    Text = "Suara di dalam kepala saya... dia memberi tahu saya... aku harus tetap bertahan..."
  },
  AvgDialog_45444_Content_39 = {
    Text = [[
Namun, meskipun dia tidak mengatakannya...
Aku adalah asisten satu-satunya %player%, di saat-saat paling berbahaya, aku harus tetap berada di sisi {Male=dia,Female=dia}.]]
  },
  AvgDialog_45444_Content_4 = {
    Text = "Karena, tidak ada yang lebih memahami penderitaan karena tidak didengar selain diriku."
  },
  AvgDialog_45444_Content_40 = {
    Text = "Bukankah ini adalah tugasku sebagai satu-satunya asisten, kan?"
  },
  AvgDialog_45444_Content_41 = {
    Text = "Kata \"satu-satunya\" yang diucapkannya terdengar sangat tegas."
  },
  AvgDialog_45444_Content_42 = {
    Text = "Di tanah ini, bangun kekuatannya, pengaruh yang diterima tubuhmu akan semakin parah."
  },
  AvgDialog_45444_Content_43 = {
    Text = "Jika ada cara lain, saya juga tidak rela menggunakan cara ini."
  },
  AvgDialog_45444_Content_44 = {
    Text = "Mythag datang untuk menghentikan ritual. Saya adalah anggota Mythag, siap mati berkali-kali tanpa ragu!"
  },
  AvgDialog_45444_Content_45 = {
    Text = "Bagus! Ramona menekan esensi keinginan. %player%, kamu dan aku bersama-sama akan sepenuhnya menghancurkan Pohon Ibu!"
  },
  AvgDialog_45444_Content_46 = {
    Text = "Di langit yang luas terdengar suara melengkung yang memekakkan telinga, dan bayangan perak melintasi langit gurun yang tinggi."
  },
  AvgDialog_45444_Content_48 = {
    Text = "Kamu merasakan tubuhmu menjadi ringan, detik berikutnya kamu sudah berada di depan gumpalan tumor yang kotor dan bau."
  },
  AvgDialog_45444_Content_49 = {
    Text = "Orang Aram yang ditelan oleh Pohon Ibu berkumpul di sini dalam bentuk telur. Di dalam lubang tembus cahaya, tak terhitung wajah yang terdistorsi dan kabur. Hanya cairan berwarna merah-hitam yang terus-menerus mengalir keluar dari lubang tersebut, bergabung ke dalam Sungai Suci yang tidak lagi jernih."
  },
  AvgDialog_45444_Content_5 = {
    Text = "Saya mengikuti rombongan Aran dan bermigrasi selama ratusan tahun."
  },
  AvgDialog_45444_Content_6 = {
    Text = "Tidak ada yang dapat melihat saya, tidak ada yang dapat mendengar saya."
  },
  AvgDialog_45444_Content_7 = {
    Text = [[
Aku pernah menjadi penari terindah di pesta malam, juga ratu yang paling dihormati dari suku Alan.
Namun saat ini, tak ada yang melihat tarianku, tak ada yang mendengar titahku.]]
  },
  AvgDialog_45444_Content_8 = {
    Text = "Di dalam Pelarutan, terdapat dunia lain."
  },
  AvgDialog_45444_Content_9 = {
    Text = "Gelap pekat, sunyi, dan penuh keputusasaan."
  },
  AvgDialog_46539_Content_1 = {
    Text = "Setelah satu tahun mengajar dan melakukan penyelidikan tugas baru-baru ini, kualifikasi kamu sekarang sudah cukup untuk memahami \"Traphase\"."
  },
  AvgDialog_46539_Content_10 = {
    Text = "Tentu saja, mereka yang terlibat dalam pertempuran adalah semua Pembangun —— namun, selama proses fase, keberadaan tertentu akan mengalami <Yellow:pembengkokan> batas fisik."
  },
  AvgDialog_46539_Content_11 = {
    Text = "<Yellow:Kemampuan Pembangun>, <Yellow:Hambatan Alam> hingga <Yellow:Aturan Pertempuran> sangat berbeda dari kenyataan."
  },
  AvgDialog_46539_Content_12 = {
    Text = "Pengembanganmu terhadap Pembangun juga akan gagal, namun <Yellow:pihak lawan juga demikian>. Dalam beberapa hal, \"Traphase\" adalah sebuah <Yellow:permainan yang adil>."
  },
  AvgDialog_46539_Content_13 = {
    Text = "Aktifkan instrumen fase, coba lakukan permainan. Semua pertanyaan akan terjawab dalam pertempuran nyata. Semoga Kunci Perak membimbing jalan ke depan."
  },
  AvgDialog_46539_Content_2 = {
    Text = "Ngomong-ngomong, apakah kamu pernah mendengar tentang \"Traphase\" dari orang lain?"
  },
  AvgDialog_46539_Content_3 = {
    Text = "Memiliki pemahaman tertentu"
  },
  AvgDialog_46539_Content_4 = {
    Text = "Baik, namun berdasarkan peraturan sekolah, saya harus menjelaskan kepada Anda secara lebih menyeluruh mengenai risiko dan aturan yang terkait."
  },
  AvgDialog_46539_Content_5 = {
    Text = "Belum pernah terdengar"
  },
  AvgDialog_46539_Content_6 = {
    Text = "Baik, saya akan mulai menjelaskan semuanya dari awal."
  },
  AvgDialog_46539_Content_7 = {
    Text = "Dalam penelitian terhadap Perak, kami menemukan bahwa gelombang getaran yang dihasilkan saat Perak bergetar kadang-kadang dapat melampaui batas fisik. Kami menyebut posisi terjadinya gelombang ini sebagai <Yellow:Fase>."
  },
  AvgDialog_46539_Content_8 = {
    Text = "Dan \"Traphase\", adalah sebuah metode pelatihan khusus yang memanfaatkan fase untuk <Yellow:melawan> diri sendiri di dimensi lain, sehingga mencapai Efek dalam melatih Roh dan kesadaran Pertempuran."
  },
  AvgDialog_46539_Content_9 = {
    Text = "Diri sendiri dari dimensi lain..."
  },
  AvgDialog_46700_Content_1 = {
    Text = "Indeks Gnostik 89.8, frekuensi pasang 762Hz, masih terus meningkat…"
  },
  AvgDialog_46700_Content_2 = {
    Text = "Tidak diragukan lagi, itu adalah <Yellow:Arus Hitam>. Semua departemen siap, tim pengawasan melaporkan indeks gnostik secara real-time, tim taktis menyiapkan rencana, tim aksi meluncurkan domain buatan, bersiap untuk menyusup ke zona terlarang bencana melalui dimensi roh!"
  },
  AvgDialog_46700_Content_3 = {
    Text = "Arus Hitam?"
  },
  AvgDialog_46700_Content_4 = {
    Text = "Dimensi kesadaran di dalam Kolam Hitam yang terpengaruh oleh pasang surut dapat menyebabkan gelombang fase. Jika tidak ditangani dengan benar, hal ini juga bisa memicu bencana besar di berbagai <Yellow:Zona Terlarang Efek-d regional> yang saling terhubung."
  },
  AvgDialog_46700_Content_5 = {
    Text = "Keberadaan aneh melayang yang disebutkan oleh Dekan Czort dalam upacara pemberian kunci adalah pertanda ledakan Arus Hitam D-tide."
  },
  AvgDialog_46700_Content_6 = {
    Text = "Gelombang roh yang tidak diketahui dapat mengganggu stabilitas Domain, lingkungan internal berubah setiap saat, <Yellow:Pembangun dan musuh mungkin terpengaruh oleh Arus hitam>…"
  },
  AvgDialog_46700_Content_7 = {
    Text = "Prinsipnya akan dibahas di kelas. Gelombang pertama Efek-d regional sudah tiba! Bersiaplah menghadapi bencana Arus hitam!"
  },
  AvgDialog_46700_Content_8 = {
    Text = "Semoga Kunci Perak membimbing kalian."
  },
  AvgDialog_46733_Content_1 = {
    Text = "Meskipun ini hanyalah malam tugas lapangan biasa, tidurmu selalu kurang nyenyak saat bermalam di luar sekolah."
  },
  AvgDialog_46733_Content_10 = {
    Text = "Augier, apakah kamu merasa tidak enak badan?"
  },
  AvgDialog_46733_Content_11 = {
    Text = "Tuanku, a-aku… tidak……ini mereka……"
  },
  AvgDialog_46733_Content_12 = {
    Text = "Augier dengan susah payah memeluk benda tak kasat mata yang tak terkendali. Benda-benda yang biasanya hanya melingkari tubuhnya seperti kekuatan Augier kini menjadi sangat aktif——"
  },
  AvgDialog_46733_Content_13 = {Text = "Slurp."},
  AvgDialog_46733_Content_14 = {
    Text = "Begitu aktifnya, hingga saat kau mendekat untuk melihat, benda-benda itu \"menjilat\" wajahmu seperti lidah kucing."
  },
  AvgDialog_46733_Content_15 = {
    Text = "Tuanku——?!"
  },
  AvgDialog_46733_Content_16 = {
    Text = "A-aku, Augi-, tidak…sengaja……"
  },
  AvgDialog_46733_Content_17 = {
    Text = "Kau mendorong benda tak kasat mata yang menempel seperti kucing itu, lalu jari-jarimu tenggelam ke dalam rambut emas Augier yang lembut, mengusap-usap helai rambutnya dengan menenangkan."
  },
  AvgDialog_46733_Content_18 = {
    Text = "Tidak apa-apa, pelan-pelan saja bicaranya."
  },
  AvgDialog_46733_Content_19 = {
    Text = "Aku……aku tidak tahu kenapa, hari ini aku sangat ingin berada di sisi Tuanku. Perasaan ini begitu kuat, begitu kuat hingga benda-benda tak kasat mata pun tidak begitu menuruti perintahku……"
  },
  AvgDialog_46733_Content_2 = {
    Text = "Suara-suara dunia terdengar begitu jelas di kegelapan, terutama napas muda yang berat itu, satu demi satu——"
  },
  AvgDialog_46733_Content_20 = {
    Text = "<Small:Apakah ini pengaruh dari Sungai Suci dan Pohon Induk?>"
  },
  AvgDialog_46733_Content_21 = {
    Text = "Kalau aku mengganggu Tuanku……"
  },
  AvgDialog_46733_Content_22 = {
    Text = "Tidak apa-apa kok."
  },
  AvgDialog_46733_Content_23 = {
    Text = "Be-benarkah?!"
  },
  AvgDialog_46733_Content_24 = {
    Text = "Kau menarik Augier masuk ke kamar, dengan tegas mendorongnya ke atas tempat tidur, sementara kau sendiri menarik sebuah kursi dan duduk di sisi ranjang."
  },
  AvgDialog_46733_Content_25 = {
    Text = "Malam ini tinggal saja di sini, dengan begitu kau bisa tidur nyenyak, kan."
  },
  AvgDialog_46733_Content_26 = {
    Text = "Bagaimana mungkin aku bermalam di ranjang Tuanku, ini tidak sesuai tata krama——"
  },
  AvgDialog_46733_Content_27 = {
    Text = "Augier dibungkus oleh selimut olehmu hingga menjadi satu gulungan, seluruh tubuhnya bergerak-gerak gelisah seperti ulat bulu, hingga kau meletakkan tanganmu di dahinya."
  },
  AvgDialog_46733_Content_28 = {
    Text = "Tidurlah, tidurlah…"
  },
  AvgDialog_46733_Content_29 = {
    Text = "Kau tidak hafal banyak lagu pengantar tidur, dan melodi yang tanpa sadar kau senandungkan saat ini pun hanyalah salah satu dari sekian banyak lagu anak-anak menyeramkan dari Londinium."
  },
  AvgDialog_46733_Content_3 = {
    Text = "Besok masih ada misi investigasi yang menunggu kita, kenapa belum tidur juga?"
  },
  AvgDialog_46733_Content_30 = {
    Text = "Namun kedua mata Augier yang berbinar-binar itu, benar-benar perlahan meredup, bagaikan bintang malam yang tenggelam ke dalam kabut tipis sebelum fajar."
  },
  AvgDialog_46733_Content_31 = {
    Text = "Tuan……huu……Tuanku……"
  },
  AvgDialog_46733_Content_32 = {
    Text = "Kau memandanginya lama di sisi ranjang, hingga napasnya menjadi panjang dan teratur, dan langit berbintang di luar jendela pun mulai meredup. Barulah kau mengusap rambut halus di pelipisnya, lalu berjingkat-jingkat meninggalkan kamar."
  },
  AvgDialog_46733_Content_33 = {
    Text = "Tidurlah yang nyenyak, anak baik."
  },
  AvgDialog_46733_Content_4 = {
    Text = "Tu-Tuanku! Augier tidak bermaksud mengganggu istirahat Tuanku, hanya saja, hanya saja……"
  },
  AvgDialog_46733_Content_5 = {
    Text = "Augier memeluk senjatanya, bersandar di lorong, berdiri menjaga di depan pintumu bak patung ksatria."
  },
  AvgDialog_46733_Content_6 = {
    Text = "Entah sudah berapa lama ia berdiri kaku di lorong itu. Melihatmu membuka pintu, ia secara refleks hendak memberi hormat, namun tubuhnya justru terhuyung tak berdaya."
  },
  AvgDialog_46733_Content_7 = {
    Text = "——Hati-hati!"
  },
  AvgDialog_46733_Content_8 = {
    Text = "Kau dengan sigap menopang pemuda yang nyaris terjatuh itu, tetapi hal itu justru membuat Augier semakin salah tingkah."
  },
  AvgDialog_46733_Content_9 = {
    Text = "Wajahnya merah padam, tangannya panik, seolah ingin menahan sesuatu tak kasat mata yang mengalir tak terkendali, seolah juga ingin melarikan diri dari sisimu."
  },
  AvgDialog_46734_Content_1 = {
    Text = "Maaf, Penjaga Rahasia, tolong jangan lihat aku untuk sementara."
  },
  AvgDialog_46734_Content_10 = {
    Text = "Tangan wanita itu menggenggam lenganmu. Jari-jarinya panjang dan kuat—bahkan melalui kain, kau bisa merasakan kapalan tipis yang terbentuk dari bertahun-tahun menggunakan senjata api."
  },
  AvgDialog_46734_Content_11 = {
    Text = "Selama tahun-tahun yang panjang ini, aku sudah terbiasa menahan pengaruh dari Sungai Suci… Benar, Dia suci, penuh belas kasih, memungkinkan kaum kami untuk terus bertahan. Namun, apa yang kukejar tidak bisa diperoleh dalam kobaran panas-Nya."
  },
  AvgDialog_46734_Content_12 = {
    Text = "Saat mengucapkan kata-kata yang begitu lurus seperti itu, Elva… tindakanmu sepertinya tidak seharusnya seperti ini kan?!"
  },
  AvgDialog_46734_Content_13 = {
    Text = "Maksudku, saat ini aku sangat tenang. Tindakanku bukan berasal dari Sungai Suci, juga bukan dari kekuatan luar mana pun."
  },
  AvgDialog_46734_Content_14 = {
    Text = "<LightGray:(Tidak, kau sama sekali tidak terlihat tenang.)>"
  },
  AvgDialog_46734_Content_15 = {
    Text = "Mungkin kata \"terlihat\" kurang tepat—bahkan tanpa penglihatan, kau tahu bahwa tindakan saat ini bukanlah sesuatu yang bisa dilakukan Elva yang biasanya."
  },
  AvgDialog_46734_Content_16 = {
    Text = "……Tapi pihak yang bersangkutan jelas tidak berpikir demikian."
  },
  AvgDialog_46734_Content_17 = {
    Text = "Karena aku sudah tahu, untuk mewujudkan visi yang kuimpikan, apa yang harus kulindungi, dan untuk siapa aku mengabdi."
  },
  AvgDialog_46734_Content_18 = {
    Text = "Jadi, aku berpikir—apakah sekarang, aku sudah bisa memilih untuk mengikuti naluriku, untuk menjelajahi sesuatu yang belum pernah kusentuh sebelumnya."
  },
  AvgDialog_46734_Content_19 = {
    Text = "Narasi Elva sangat stabil, seolah-olah ini hanyalah laporan mengenai suatu rencana latihan."
  },
  AvgDialog_46734_Content_2 = {
    Text = "Elva, kau yakin kau baik-baik saja? Suaramu terdengar tidak begitu baik."
  },
  AvgDialog_46734_Content_20 = {
    Text = "Namun detak jantung mengkhianati tuannya, dentuman itu tak bisa dengan mudah disembunyikan seperti cahaya di depan matamu."
  },
  AvgDialog_46734_Content_21 = {
    Text = "Orang yang pernah mengorbankan dirinya demi keadilan ini, jelas sedang mengalami perang lain melawan dirinya sendiri."
  },
  AvgDialog_46734_Content_22 = {
    Text = "Anda bisa kapan saja mendorong saya, memukul saya hingga pingsan."
  },
  AvgDialog_46734_Content_23 = {
    Text = "Atau — membimbing saya."
  },
  AvgDialog_46734_Content_24 = {
    Text = "Di jalan pencarian tanpa akhir ini, saya akan mempersembahkan kesetiaan abadi kepada Anda……"
  },
  AvgDialog_46734_Content_25 = {
    Text = "Saya bersedia selamanya menjaga di sisi Anda."
  },
  AvgDialog_46734_Content_3 = {
    Text = "Wanita yang selalu tegas dan tangguh ini, kini suaranya parau dan bergetar. Dahinya menempel di belakang kepalamu, telapak tangannya menutupi pandanganmu dalam kegelapan total."
  },
  AvgDialog_46734_Content_4 = {
    Text = "Setelah sesi latihan hari itu, Elva untuk pertama kalinya menerobos masuk ke asramamu, melakukan tantangan terengah-engah selama tiga puluh detik penuh, lalu dengan paksa memalingkan tatapan bingungmu ke arah lain."
  },
  AvgDialog_46734_Content_5 = {
    Text = "……Aku sedang berpikir, %player%, aku sedang berpikir."
  },
  AvgDialog_46734_Content_6 = {
    Text = "Kau tidak tahu apa yang sebenarnya dia pikirkan, tapi akal sehatmu mengatakan bahwa saat ini, selain gumaman bingung satu suku kata, sebaiknya kau tidak mengeluarkan suara lain."
  },
  AvgDialog_46734_Content_7 = {
    Text = "Dan itulah yang kau lakukan. Elva merespons kekakuan canggungmu dengan tawa penuh pengertian."
  },
  AvgDialog_46734_Content_8 = {
    Text = "Aku tahu dari mana pengaruh Sungai Suci berasal, dan apa maknanya."
  },
  AvgDialog_46734_Content_9 = {
    Text = "Aku pernah mengabdi pada banyak entitas, tapi yang selalu kukejar hanyalah keadilan. Meskipun di mata banyak orang, apa yang disebut keadilan mungkin hanyalah gelembung yang tak menentu."
  },
  AvgDialog_46735_Content_1 = {
    Text = "Teman! Teman, cepat kemari!"
  },
  AvgDialog_46735_Content_10 = {
    Text = "Teman-teman baru! Kelenjar Aurita hari ini membelah banyak sekali teman baru!"
  },
  AvgDialog_46735_Content_11 = {
    Text = "Dia tertawa gembira, memasukkan semua ubur-ubur beracun itu ke tanganmu sekaligus."
  },
  AvgDialog_46735_Content_12 = {
    Text = "Mereka semua bilang ingin bersamamu, jadi Aurita juga mau ikut bersama!"
  },
  AvgDialog_46735_Content_13 = {
    Text = "<Small:Sebanyak ini ubur-ubur… untungnya tubuhku tidak mudah alergi.>"
  },
  AvgDialog_46735_Content_14 = {
    Text = "Tapi, kalaupun mudah alergi, menukar beberapa suntikan epinefrin demi senyumannya sepertinya juga tidak buruk."
  },
  AvgDialog_46735_Content_2 = {
    Text = "<Small:Suara ini… jangan-jangan…>"
  },
  AvgDialog_46735_Content_3 = {
    Text = "Tunggu sebentar, aku segera membuka pintu—"
  },
  AvgDialog_46735_Content_4 = {
    Text = "Orang yang datang tanpa basa-basi mendobrak pintu asrama dan langsung menabrakmu."
  },
  AvgDialog_46735_Content_5 = {
    Text = "Kamu menopang gadis itu sambil terhuyung dua langkah, namun akhirnya tak mampu melawan gravitasi, memeluknya dan jatuh ke lantai, pandanganmu berputar-putar."
  },
  AvgDialog_46735_Content_6 = {
    Text = "Teman, cepat lihat!"
  },
  AvgDialog_46735_Content_7 = {
    Text = "Belum sempat kamu bangkit dari lantai, Aurita sudah menyodorkan \"kedua tangannya\" ke depanmu."
  },
  AvgDialog_46735_Content_8 = {
    Text = "Kedua lengan berbentuk payung itu merapat, menangkup segenggam ubur-ubur sebesar ibu jari."
  },
  AvgDialog_46735_Content_9 = {
    Text = "Ubur-ubur ini apa?"
  },
  AvgDialog_47150_Content_1 = {
    Text = "<Italic:Malam ini begitu banyak air mata, membuatku tak ingin beranjak~>"
  },
  AvgDialog_47150_Content_10 = {
    Text = "Pelayanmu seharusnya sudah menyiapkan teh penghilang mabuk, biar aku minta dia membawanya ke sini."
  },
  AvgDialog_47150_Content_11 = {
    Text = "Jangan——"
  },
  AvgDialog_47150_Content_12 = {
    Text = "Soleil menarikmu, dan kalian berdua berguling bersama di atas sofa empuk. Penampilannya berantakan, namun gelas anggur di tangannya masih dipegang dengan mantap."
  },
  AvgDialog_47150_Content_13 = {
    Text = "Semua lampu di manor telah padam, hanya cairan emas di dalam gelasnya yang membiaskan cahaya bulan, mewarnai ruang di antara kalian dengan semburat cahaya yang penuh keintiman."
  },
  AvgDialog_47150_Content_14 = {
    Text = "Aku tidak mabuk, tidak butuh teh penghilang mabuk."
  },
  AvgDialog_47150_Content_15 = {
    Text = "Salonku…… belum pernah setenang ini, namun juga belum pernah membuatku merasa sedamai ini."
  },
  AvgDialog_47150_Content_16 = {
    Text = "Di setiap perjamuan yang lalu, aku selalu menghitung tamu-tamu salon di dalam benakku. Yang memenuhi undanganku, yang membeli tiket undangan, yang menyelinap masuk…… Aku mengingat wajah setiap orang."
  },
  AvgDialog_47150_Content_17 = {
    Text = "Jika ada yang menerima undangan namun tidak muncul, aku juga akan mengingatnya…… Di tangan orang-orang itu, pasti masih tersimpan rahasia yang belum kuketahui."
  },
  AvgDialog_47150_Content_18 = {
    Text = "Aku tak bisa untuk tidak merasa gelisah akan bahaya tersembunyi ini, tak bisa untuk tidak merasa cemas akan masa depan yang tak bisa kukendalikan……"
  },
  AvgDialog_47150_Content_19 = {
    Text = "Sambil berkata demikian, ia mengangkat dagumu dengan satu tangan, mencegah tatapanmu mengembara ke tempat lain."
  },
  AvgDialog_47150_Content_2 = {
    Text = "Nyonya Soleil? Galen mengirim pesan bahwa Anda ingin bertemu dengan saya?"
  },
  AvgDialog_47150_Content_20 = {
    Text = "Tapi terhadap hal yang tak diketahui bernama \"kau\", yang kurasakan hanyalah rasa penasaran."
  },
  AvgDialog_47150_Content_21 = {
    Text = "Mungkin……kau dan aku, bisa bersama-sama menumbuhkan kuncup yang paling cantik dan tangguh."
  },
  AvgDialog_47150_Content_22 = {
    Text = "Kita, akan berdiri bersama di puncak yang tak terjangkau oleh siapa pun……"
  },
  AvgDialog_47150_Content_23 = {Text = "Huu……"},
  AvgDialog_47150_Content_24 = {
    Text = "Kata-kata Soleil belum selesai terucap, tubuhnya sudah melemas, dan seluruh berat badannya bersandar padamu."
  },
  AvgDialog_47150_Content_25 = {
    Text = "Gelas anggur menggelinding di lantai marmer, cairan anggur dengan cepat meresap ke celah-celah sambungan batu. Hembusan napas beraroma alkohol pun diam-diam merasuk ke otakmu yang nyaris meleleh."
  },
  AvgDialog_47150_Content_3 = {
    Text = "Ah…… Penjaga Rahasia kecil, kau datang."
  },
  AvgDialog_47150_Content_4 = {
    Text = "Pe-Penjaga Rahasia kecil?"
  },
  AvgDialog_47150_Content_5 = {
    Text = "Sebelum kau sempat bereaksi lebih jauh, Soleil sudah mendekatkan segelas anggur ke bibirmu."
  },
  AvgDialog_47150_Content_6 = {
    Text = "Saat ia mendekat, aroma alkohol yang pekat mekar dari ujung rambutnya dan lipatan gaunnya. Wangi alkohol berpadu dengan aroma buah dan bunga, menerpa pergelangan tanganmu lewat hembusan napasnya yang hangat."
  },
  AvgDialog_47150_Content_7 = {
    Text = "Nyonya Soleil, kau mabuk lagi."
  },
  AvgDialog_47150_Content_8 = {
    Text = "Mabuk? Mungkin saja, sepertinya aku memang sudah mabuk."
  },
  AvgDialog_47150_Content_9 = {
    Text = "Melihatmu tak menyentuh setetes pun, Soleil menggelengkan kepalanya dengan pura-pura kesal, lalu menarik kembali gelasnya dan menyesapnya sendiri."
  },
  AvgDialog_47164_Content_1 = {
    Text = "Dengarkanlah, wahai bintang-bintang"
  },
  AvgDialog_47164_Content_10 = {
    Text = "Aku di sini, Deborah. Aku ada di sini."
  },
  AvgDialog_47164_Content_100 = {
    Text = "……Ke mana para pengawal di luar?"
  },
  AvgDialog_47164_Content_101 = {
    Text = "Saat kalian asyik bersulang, para pengawal itu sudah kami habisi."
  },
  AvgDialog_47164_Content_102 = {
    Text = "Adapun pasukan di luar kota…… tak perlu lagi berharap untuk menghubungi mereka."
  },
  AvgDialog_47164_Content_103 = {
    Text = "Darah mewarnai setiap sudut aula menjadi merah, jeritan-jeritan memantul dan bergema liar di dinding-dinding, bagaikan simfoni dari neraka."
  },
  AvgDialog_47164_Content_104 = {
    Text = "Orang-orang yang tidak meminum anggur beracun dan masih dalam keadaan normal, tubuh mereka gemetar, bahkan tidak memiliki tenaga untuk mencabut pedang atau melarikan diri."
  },
  AvgDialog_47164_Content_105 = {
    Text = "Golia menikmati gulungan lukisan berdarah di aula besar ini, memandangi ekspresi ketakutan para bangsawan, menghela napas penuh kenikmatan, lalu mengangkat bilah pedang raksasa itu."
  },
  AvgDialog_47164_Content_106 = {
    Text = "Minum anggur beracun dan berubah menjadi manusia ikan, atau mati di sini. Pilih salah satu."
  },
  AvgDialog_47164_Content_108 = {
    Text = "AHHH!!!——"
  },
  AvgDialog_47164_Content_109 = {
    Text = "Jeritan memilukan menghantam lantai batu, menghasilkan gema yang suram."
  },
  AvgDialog_47164_Content_11 = {
    Text = "Miriam? Kau sedang… apa yang kau lakukan?"
  },
  AvgDialog_47164_Content_110 = {
    Text = "Dia ingin meronta, melarikan diri, tetapi tubuhnya dikendalikan oleh Miriam, tidak bisa bergerak sedikit pun."
  },
  AvgDialog_47164_Content_111 = {
    Text = "Dia ingin pingsan, tetapi otaknya sangat jernih, menyambut rasa sakit dan ketakutan."
  },
  AvgDialog_47164_Content_112 = {
    Text = "Ucapkan bersamaku, \"Bagi yang beriman, Tuhanku akan memberkati…\""
  },
  AvgDialog_47164_Content_113 = {
    Text = "Darah Deborah memercik memenuhi tubuh Miriam. Dia teringat bertahun-tahun lalu, di atas altar persembahan kuil, dia juga seperti ini, melepas kepergian ayahnya."
  },
  AvgDialog_47164_Content_114 = {
    Text = "Perpisahan, adalah demi perjumpaan yang lebih baik, bukan begitu, Tuhanku?"
  },
  AvgDialog_47164_Content_115 = {
    Text = "Dia menatap penuh kasih ke perut Deborah, belati bergerak menggores, menyelesaikan goresan terakhir dari lukisan ini."
  },
  AvgDialog_47164_Content_116 = {
    Text = "Ayo, Deborah. Ucapkan bersamaku. Bagi yang berharap…"
  },
  AvgDialog_47164_Content_117 = {
    Text = "Tangan Miriam memasuki perut Deborah, mengaduk, merobek."
  },
  AvgDialog_47164_Content_118 = {
    Text = "Tenggorokan Deborah yang parau menjerit kesakitan, mata merahnya terbuka lebar dengan gila, menatap lurus ke rongga perutnya sendiri."
  },
  AvgDialog_47164_Content_119 = {
    Text = "…\"Bagi yang berharap, Tuhanku akan mengabulkan.\""
  },
  AvgDialog_47164_Content_12 = {
    Text = "Lelucon ini sama sekali tidak lucu, Miriam… Cepat lepaskan aku…"
  },
  AvgDialog_47164_Content_120 = {
    Text = "Miriam menarik putus sesuatu, mungkin seharusnya sangat menyakitkan, tetapi Deborah sudah tidak bisa merasakannya lagi."
  },
  AvgDialog_47164_Content_121 = {
    Text = "Otaknya sudah menjadi mati rasa, emosi dan persepsi telah meninggalkannya jauh."
  },
  AvgDialog_47164_Content_122 = {
    Text = "Dia melihat samar-samar, Miriam mengeluarkan gumpalan daging berlumuran darah dari rongga perutnya."
  },
  AvgDialog_47164_Content_123 = {
    Text = "Sa… Sa…"
  },
  AvgDialog_47164_Content_124 = {
    Text = "Sara. Miriam pernah memberitahunya, itu adalah nama adik perempuannya."
  },
  AvgDialog_47164_Content_125 = {
    Text = "Dia sudah membicarakannya dengan Nord, mereka akan menamai putri mereka dengan nama ini. Tapi dia belum sempat memberitahu Miriam."
  },
  AvgDialog_47164_Content_126 = {
    Text = "Namakan dia Sarah. Deborah bergumam lirih, tapi dia sudah tak mampu lagi mengeluarkan suara apa pun."
  },
  AvgDialog_47164_Content_127 = {
    Text = "\"Wahai Tuhan kami, semoga nyanyian kami menembus lautan dalam, bersama-Mu, menuju alam ketenangan dan kebahagiaan abadi.\""
  },
  AvgDialog_47164_Content_128 = {
    Text = "Miriam dengan penuh kasih mencium putri baptisnya, darah di tubuh bayi itu mewarnai bibirnya merah. Darah menetes dari sudut bibirnya, sementara ia perlahan menutup mata Deborah."
  },
  AvgDialog_47164_Content_13 = {
    Text = "Tidak, Deborah, ini bukan lelucon. Tidak ada hal yang lebih sakral dari ini di dunia."
  },
  AvgDialog_47164_Content_130 = {
    Text = "Tap, tap, tap..."
  },
  AvgDialog_47164_Content_131 = {
    Text = "Suara langkah kaki ringan terdengar dari dalam ruangan."
  },
  AvgDialog_47164_Content_132 = {
    Text = "Gubuk sederhana yang dibangun dari lempengan batu gelap ini, bentuknya persis sama dengan rumah tempat Miriam pernah tinggal."
  },
  AvgDialog_47164_Content_133 = {
    Text = "Di ruangan ini, dia telah mengucapkan selamat tinggal kepada ibu, ayah, adik perempuan, dan sahabatnya."
  },
  AvgDialog_47164_Content_134 = {
    Text = "Di ruangan ini, dia akan bertemu kembali dengan mereka."
  },
  AvgDialog_47164_Content_135 = {
    Text = "Langkah kaki berhenti di ambang pintu."
  },
  AvgDialog_47164_Content_136 = {
    Text = "Puji Yang Mulia Pendeta Agung!"
  },
  AvgDialog_47164_Content_137 = {
    Text = "Puji Yang Mulia Pendeta Agung!"
  },
  AvgDialog_47164_Content_138 = {
    Text = "Goliath berlutut. Di belakangnya, tak terhitung manusia ikan menyerukan kalimat yang sama, berlutut serempak di tanah."
  },
  AvgDialog_47164_Content_139 = {
    Text = "Mereka mengelilingi gubuk, bagaikan gelombang yang tak berujung, menunggu perintah dari lautan dalam."
  },
  AvgDialog_47164_Content_14 = {
    Text = "Apa yang ingin kau lakukan? Miriam… Bukankah kau bilang aku adalah sahabat terbaikmu?"
  },
  AvgDialog_47164_Content_140 = {
    Text = "Miriam mendekap bayi yang berlumuran darah, berjalan menuju kerumunan. Para manusia ikan dengan sendirinya membuka jalan untuknya."
  },
  AvgDialog_47164_Content_141 = {
    Text = "Bintang-bintang telah mencapai posisi yang tepat. Janin suci Sang Raja telah ditanamkan ke dalam tubuh bayi suci. Segera, Sang Raja akan kembali hadir di dunia."
  },
  AvgDialog_47164_Content_142 = {
    Text = "Sang Raja akan melindungi umat-Nya yang saleh, dan membawa Kerajaan Ilahi!"
  },
  AvgDialog_47164_Content_143 = {
    Text = "Kerajaan Ilahi! Kerajaan Ilahi!"
  },
  AvgDialog_47164_Content_144 = {
    Text = "Para manusia ikan bersorak dan menari dengan penuh kegilaan. Miriam tiba di tengah kerumunan. Cahaya bintang turun, menerangi wajahnya yang dipenuhi darah dan air mata."
  },
  AvgDialog_47164_Content_145 = {
    Text = "Ajaran Sang Raja akan tersebar ke seluruh dunia. Yang Mulia Pendeta Agung, berikanlah nama untuk aliran kepercayaan ini."
  },
  AvgDialog_47164_Content_146 = {
    Text = "Sepasang mata yang dingin namun membara berputar perlahan. Miriam memandang sekeliling kepada para prajurit dan rakyatnya. Dia mengulas senyum seorang Pendeta Agung kepada mereka."
  },
  AvgDialog_47164_Content_147 = {
    Text = "Kami melangkah ke lautan, mengikuti jejak Sang Raja.\nKami datang dari lautan, membawa kerajaan Sang Raja……"
  },
  AvgDialog_47164_Content_148 = {
    Text = "Dunia akan menyebut kami, Para Pengarung Lautan."
  },
  AvgDialog_47164_Content_149 = {
    Text = "Pengarung Lautan! Pengarung Lautan!!"
  },
  AvgDialog_47164_Content_15 = {
    Text = "Kau… dulu kau juga punya seorang teman, juga bernama Deborah… Bukankah kita sangat berjodoh, Miriam? Kumohon… kumohon jangan sakiti aku…"
  },
  AvgDialog_47164_Content_150 = {
    Text = "Di tengah gemuruh seruan para manusia ikan yang memekakkan telinga, Miriam mengulurkan kedua tangannya, mengangkat tinggi-tinggi bayi dalam dekapannya."
  },
  AvgDialog_47164_Content_151 = {
    Text = "Di tempat yang semula menjadi jantungnya, Janin Suci bersinar dengan cahaya putih murni di bawah gemerlap bintang."
  },
  AvgDialog_47164_Content_152 = {
    Text = "Uwaaaa——"
  },
  AvgDialog_47164_Content_153 = {
    Text = "Segalanya menjadi hening. Bayi yang berlumuran darah menggeliatkan tubuhnya, dan di tengah reruntuhan kuno itu, bergema tangisan pertamanya yang terlambat."
  },
  AvgDialog_47164_Content_154 = {
    Text = "Bintang-bintang di langit terdiam, mendengarkan tangisan yang bagaikan wahyu ilahi. Sebuah bintang jatuh, menggoreskan catatan kaki yang memilukan di langit malam."
  },
  AvgDialog_47164_Content_155 = {
    Text = "——Kisah lain tentang bintang-bintang, akan segera dimulai."
  },
  AvgDialog_47164_Content_16 = {
    Text = "Mana mungkin, Deborah? Mana mungkin aku tega menyakitimu? Kau adalah sahabat terbaikku, kau adalah satu-satunya temanku…"
  },
  AvgDialog_47164_Content_17 = {
    Text = "Ia membelai wajah Deborah, menyeka air mata ketakutannya. Sentuhan yang dingin dan licin itu membuat Deborah tak kuasa menahan gemetar."
  },
  AvgDialog_47164_Content_18 = {
    Text = "Aku tidak akan pernah, tidak akan pernah menyakitimu, Deborah. Aku hanya ingin memberikanmu sebuah hadiah."
  },
  AvgDialog_47164_Content_19 = {
    Text = "Ha, hadiah?"
  },
  AvgDialog_47164_Content_2 = {
    Text = "Wilayah kekuasaan Keluarga Orne, altar persembahan."
  },
  AvgDialog_47164_Content_20 = {
    Text = "Betapa aku berharap bisa menjadi orang yang mengandung Janin Suci itu. Tapi kau sudah melihat apa yang terjadi saat Janin Suci ditanamkan padaku, aku tidak memiliki kualifikasi itu."
  },
  AvgDialog_47164_Content_21 = {
    Text = "Kemuliaan ini, bukan sembarang orang yang layak mendapatkannya. Tidak bisa menikmati kemuliaan ini, adalah penyesalanku……"
  },
  AvgDialog_47164_Content_22 = {
    Text = "Deborah, aku adalah ibu baptis putrimu. Aku akan memberikan kemuliaan tertinggi ini kepada anak baptisku, dan juga kepadamu, satu-satunya sahabat sejatiku."
  },
  AvgDialog_47164_Content_23 = {
    Text = "Miriam, aku bersedia…… Aku bersedia menjadikan putriku sebagai wadah, untuk menikmati kemuliaan ini……"
  },
  AvgDialog_47164_Content_24 = {
    Text = "Tapi, dia masih tiga bulan lagi baru lahir…… Aku juga tidak bisa berbuat apa-apa……"
  },
  AvgDialog_47164_Content_25 = {
    Text = "Tidak ada waktu lagi, Deborah. Tidak ada waktu lagi."
  },
  AvgDialog_47164_Content_26 = {
    Text = "Miriam menatap Deborah dengan penuh kasih sayang, nada bicaranya menjadi semakin lembut."
  },
  AvgDialog_47164_Content_27 = {
    Text = "Dia adalah kandidat yang paling tepat. Dia harus, lahir hari ini."
  },
  AvgDialog_47164_Content_29 = {
    Text = "Wilayah kekuasaan Keluarga Edmond, Aula Perjamuan."
  },
  AvgDialog_47164_Content_3 = {Text = "Tik——"},
  AvgDialog_47164_Content_30 = {
    Text = "Sekarang, mari kita sambut tuan rumah perjamuan ini — Goliath dari Orn!"
  },
  AvgDialog_47164_Content_31 = {
    Text = "Sorak-sorai meriah bergema di aula yang luas. Goliath naik ke panggung, perlahan menyapu pandangannya ke sekeliling."
  },
  AvgDialog_47164_Content_32 = {
    Text = "Edmond, Pappas, Ennom…… Orang-orang dari setiap keluarga besar telah berkumpul di sini."
  },
  AvgDialog_47164_Content_33 = {
    Text = "Busana mewah mereka menyimpan sejarah pembantaian, mata mereka yang tertawa berkilauan dengan cahaya keserakahan."
  },
  AvgDialog_47164_Content_34 = {
    Text = "Mereka adalah tuan atas tanah dan sejarah. Mereka adalah budak dari kekuasaan dan nafsu."
  },
  AvgDialog_47164_Content_35 = {
    Text = "Goliath tersenyum kepada mereka."
  },
  AvgDialog_47164_Content_36 = {
    Text = "Hadirin sekalian, pada hari ini, aliansi tujuh keluarga besar resmi didirikan. Rincian perjanjiannya akan disampaikan kepada kalian semua nanti."
  },
  AvgDialog_47164_Content_37 = {
    Text = "Sekarang, mari kita nikmati perjamuan yang luar biasa ini. Untuk tanah, untuk kekayaan, untuk kekuasaan, bersulang!"
  },
  AvgDialog_47164_Content_38 = {
    Text = "Semua orang bersorak sambil mengangkat gelas di tangan mereka. Hidangan-hidangan mewah nan berlimpah disajikan satu per satu ke meja makan."
  },
  AvgDialog_47164_Content_39 = {
    Text = "Perjamuan dimulai, para bangsawan mengangkat gelas merayakan keuntungan yang akan segera mereka bagi, suara hiruk-pikuk menutupi segala pergerakan di luar pintu."
  },
  AvgDialog_47164_Content_4 = {
    Text = "Suara tetesan air terdengar jelas di telinga Deborah. Perlahan ia membuka mata."
  },
  AvgDialog_47164_Content_40 = {
    Text = "Di luar pintu."
  },
  AvgDialog_47164_Content_41 = {Text = "Aah——"},
  AvgDialog_47164_Content_42 = {
    Text = "Kalian adalah……ugh!……"
  },
  AvgDialog_47164_Content_43 = {
    Text = "Abishai mencabut pisau yang tertancap di tubuh penjaga."
  },
  AvgDialog_47164_Content_44 = {
    Text = "Hah……andai saja aku tidak mengerti bahasa orang-orang ikan ini, mungkin aku tidak akan disuruh melakukan pekerjaan seperti ini……"
  },
  AvgDialog_47164_Content_45 = {
    Text = "Dia melirik prajurit ikan di sampingnya dan menghela napas panjang."
  },
  AvgDialog_47164_Content_46 = {
    Text = "Semua jalan keluar lainnya sudah dikuasai? Pasukan pengawal pribadi yang dibawa keluarga-keluarga itu, sudah dibunuh semua?"
  },
  AvgDialog_47164_Content_47 = {
    Text = "Bagus kalau begitu……kalian jaga semua jalan keluar di dalam kastil ini, siapkan satu regu prajurit untuk berjaga bersamaku di dekat aula perjamuan, menunggu perintah selanjutnya dari Tuan Goliath."
  },
  AvgDialog_47164_Content_48 = {
    Text = "Pasukan utama mereka mungkin baru akan mengetahui apa yang terjadi di sini setelah satu atau dua jam, berdoalah semoga Tuan Goliath bisa menyelesaikan semuanya sebelum itu……"
  },
  AvgDialog_47164_Content_5 = {
    Text = "Sebuah ruangan yang dikelilingi lempengan batu gelap, cahaya bintang jatuh dari lubang di atas kepala, menyinari perutnya."
  },
  AvgDialog_47164_Content_50 = {
    Text = "Tidak……Miriam……jangan!"
  },
  AvgDialog_47164_Content_51 = {
    Text = "Kumohon……kumohon……demi persahabatan kita……ampuni aku……"
  },
  AvgDialog_47164_Content_52 = {
    Text = "Aku memberikan kehormatan tertinggi kepadamu, dan kau justru menghina persahabatan ini, Deborah."
  },
  AvgDialog_47164_Content_53 = {
    Text = "Tapi tidak apa-apa, Tuanku bisa memahami ketakutanmu. Persahabatan kita tidak akan berubah karena penghinaan ini."
  },
  AvgDialog_47164_Content_54 = {
    Text = "Dengan penuh khidmat, dia meletakkan patung Thulu di tepi altar persembahan, lalu memberi hormat kepadanya."
  },
  AvgDialog_47164_Content_55 = {
    Text = "Terpujilah Tuanku……Lemuria, sang Raja agung……malam ini, aku akan menyambut kepulangan-Mu."
  },
  AvgDialog_47164_Content_56 = {
    Text = "Mohon bersabarlah. Saat bintang-bintang sejajar, akan segera tiba……"
  },
  AvgDialog_47164_Content_57 = {
    Text = "Dia berdiri dan berjalan dengan lembut menuju Deborah. Di tangan pucatnya, belati persembahan dengan bentuk aneh berkilau dalam cahaya redup."
  },
  AvgDialog_47164_Content_58 = {
    Text = "Tidak! Miriam!! Kumohon……kumohon……jangan lakukan hal sekejam ini……"
  },
  AvgDialog_47164_Content_59 = {
    Text = "Tatap aku, Deborah. Tatap aku……"
  },
  AvgDialog_47164_Content_6 = {
    Text = "Tubuhnya tak berbalut sehelai benang pun, perutnya membuncit tinggi, urat-urat nadi di atasnya terlihat jelas di bawah cahaya bintang."
  },
  AvgDialog_47164_Content_60 = {
    Text = "Aku tahu, kau sangat ketakutan. Aku telah melihat banyak pengikut, saat menghadapi akhir kehidupan mereka, mereka semua akan merasa takut."
  },
  AvgDialog_47164_Content_61 = {
    Text = "Tapi, jangan khawatir. Kau adalah rakyat tertinggi Kerajaan Tuhan, semua penderitaan yang kau alami akan mendapat gantinya di Kerajaan Tuhan."
  },
  AvgDialog_47164_Content_62 = {
    Text = "Mari, berdoalah bersamaku, Deborah."
  },
  AvgDialog_47164_Content_63 = {
    Text = "Tidak……Miriam……aku mohon……"
  },
  AvgDialog_47164_Content_64 = {
    Text = "Ikuti aku: \"Segala yang menderita, Tuhan akan membalasnya.\""
  },
  AvgDialog_47164_Content_65 = {
    Text = "Segala……segala yang menderita……tidak, Miriam……"
  },
  AvgDialog_47164_Content_66 = {
    Text = "Ikuti aku. \"Segala yang berdosa, Tuhan akan menghukumnya.\""
  },
  AvgDialog_47164_Content_67 = {
    Text = "Miriam melantunkan doa, menghampiri sisinya."
  },
  AvgDialog_47164_Content_68 = {
    Text = "Biarkan aku bicara sepatah kata dengan Nord! Miriam……biarkan aku bicara sepatah kata dengannya……"
  },
  AvgDialog_47164_Content_69 = {
    Text = "<Big:AHHH!!!——>"
  },
  AvgDialog_47164_Content_7 = {
    Text = "Ini… apa yang terjadi… Miriam?!"
  },
  AvgDialog_47164_Content_70 = {
    Text = "Rasa sakit yang luar biasa menjalar dari perutnya. Ia mendongak, melihat tangan Miriam yang pucat bagai ular membawa belati itu, menusuk ke dalam rongga perutnya, menggoreskan jejak merah darah di rongga perutnya."
  },
  AvgDialog_47164_Content_71 = {
    Text = "Miriam tidak mendengar jeritan memilukan Deborah, tidak melihat wajahnya yang terdistorsi oleh ketakutan dan rasa sakit yang luar biasa."
  },
  AvgDialog_47164_Content_72 = {
    Text = "Belati itu bergerak dengan stabil, darah hangat menyembur ke wajah Miriam. Ia dengan khusyuk melantunkan doa, melangkah menaiki tangga menuju Kerajaan Tuhan."
  },
  AvgDialog_47164_Content_74 = {
    Text = "Bunuh Miriam! Bagi-bagi klan Orn! Persekutuan kita makmur sejahtera! Bersulang!!"
  },
  AvgDialog_47164_Content_75 = {
    Text = "Gelas-gelas beradu, keserakahan yang tak disembunyikan menyebar bersama aroma daging dan anggur."
  },
  AvgDialog_47164_Content_76 = {
    Text = "Goliath menjilat bibirnya, menikmati rasa yang membuatnya terpesona itu."
  },
  AvgDialog_47164_Content_77 = {
    Text = "Ayo, lanjutkan, ada apa denganmu?"
  },
  AvgDialog_47164_Content_78 = {
    Text = "Kau……wajahmu……"
  },
  AvgDialog_47164_Content_79 = {Text = "Wajahku?"},
  AvgDialog_47164_Content_8 = {
    Text = "Ia ingin bangkit, namun mendapati tubuh serta tangan dan kakinya terikat di altar batu, tak bisa bergerak."
  },
  AvgDialog_47164_Content_80 = {
    Text = "Ia memandang ke ubin yang halus bagai cermin di sampingnya, dan melihat sebuah wajah yang menyerupai ikan."
  },
  AvgDialog_47164_Content_81 = {Text = "Aaaahhh!!!"},
  AvgDialog_47164_Content_82 = {
    Text = "Luka demi luka muncul di dadanya, seolah digores oleh belati tak kasat mata. Telinga dan alis matanya menghilang, bola matanya membengkak dengan cepat, tumbuh melebar ke kedua sisi."
  },
  AvgDialog_47164_Content_83 = {
    Text = "Rasa sakit yang luar biasa menembus pengaruh alkohol dan adrenalin, menghantam otaknya. Ia jatuh tersungkur ke lantai, mengeluarkan jeritan kesakitan yang terlambat, kedua tangannya mencakar-cakar wajahnya sendiri secara membabi buta."
  },
  AvgDialog_47164_Content_84 = {
    Text = "Ini apa? Aakh!!——"
  },
  AvgDialog_47164_Content_85 = {
    Text = "Satu, dua, tiga…… Di dalam aula perjamuan yang mewah, para bangsawan berjatuhan satu per satu ke lantai."
  },
  AvgDialog_47164_Content_86 = {
    Text = "Luka-luka merah darah bermunculan silih berganti di tubuh mereka, darah dan daging melukiskan sebuah pola kuno di atas tubuh mereka."
  },
  AvgDialog_47164_Content_87 = {
    Text = "Jeritan kesakitan menyatu menjadi simfoni yang megah, darah menyembur, mengisi setiap gelas anggur hingga penuh."
  },
  AvgDialog_47164_Content_88 = {
    Text = "Ini…… ini…… ritual manusia ikan!"
  },
  AvgDialog_47164_Content_89 = {
    Text = "Benar sekali, ritual manusia ikan. Nasib tragis Keluarga Orn, kalian semua pasti sudah pernah mendengarnya."
  },
  AvgDialog_47164_Content_9 = {
    Text = "Sepasang tangan terjulur, menggenggam tangannya. Tangan itu dingin dan licin, bagaikan seekor ular pucat."
  },
  AvgDialog_47164_Content_90 = {
    Text = "Kenapa…… Goliya?"
  },
  AvgDialog_47164_Content_91 = {Text = "Kenapa?"},
  AvgDialog_47164_Content_92 = {
    Text = "Goliya tampak seperti mendengar lelucon yang lucu. Ia berdiri dari kursi utamanya dan mengambil pisaunya."
  },
  AvgDialog_47164_Content_93 = {
    Text = "Bekerja sama dengan kalian, aku hanya mendapat sepotong kecil wilayah Keluarga Orn."
  },
  AvgDialog_47164_Content_94 = {
    Text = "Bekerja sama dengan Miriam, aku bisa mendapatkan kekuatan dahsyat yang tak bisa kalian bayangkan, bisa mengubah kalian semua menjadi bagian dari manusia ikan, menguasai seluruh kekayaan kalian……"
  },
  AvgDialog_47164_Content_95 = {
    Text = "Katakan padaku, Tuan Edmond, kalau kau jadi aku, apa yang akan kau pilih?"
  },
  AvgDialog_47164_Content_96 = {
    Text = "Aku…… kami tidak akan menyerah begitu saja!"
  },
  AvgDialog_47164_Content_97 = {
    Text = "Benar! Goliya, demi kehormatan Keluarga Enorm, kami akan…… Aakh——"
  },
  AvgDialog_47164_Content_98 = {
    Text = "Bilah raksasa itu jatuh menghujam secara vertikal, tubuh bangsawan muda itu terbelah menjadi dua dan roboh ke kedua sisi, kehilangan kemampuan untuk membuktikan kehormatannya."
  },
  AvgDialog_47164_Content_99 = {
    Text = "Pintu-pintu di sekeliling terbuka, manusia ikan yang tak terhitung jumlahnya membanjiri aula bagai gelombang pasang."
  },
  AvgDialog_47165_Content_1 = {
    Text = "Sahabat Karib"
  },
  AvgDialog_47165_Content_10 = {
    Text = "Tidak perlu tegang, Tuan Edmond. Miriam telah merampas kebebasanku. Aku dan kalian memiliki musuh yang sama."
  },
  AvgDialog_47165_Content_100 = {
    Text = "Miriam, jangan terlalu khawatir, kita masih bisa memikirkan cara lain bersama-sama..."
  },
  AvgDialog_47165_Content_101 = {
    Text = "Tidak ada cara lain lagi, Deborah. Hanya tersisa satu..."
  },
  AvgDialog_47165_Content_102 = {
    Text = "Dia mengangkat kepalanya, menghapus air matanya, dan membelai wajah Deborah."
  },
  AvgDialog_47165_Content_103 = {
    Text = "Dia teringat beberapa pertanyaan dari masa yang sangat lampau. Pertanyaan-pertanyaan itu telah terkubur oleh waktu, kini tiba-tiba muncul, membawa aroma debu yang memenuhi benaknya."
  },
  AvgDialog_47165_Content_104 = {
    Text = "Deborah, apakah kau beriman kepada Raja?"
  },
  AvgDialog_47165_Content_105 = {
    Text = "Tentu saja..."
  },
  AvgDialog_47165_Content_106 = {
    Text = "Deborah, apakah kau tahu, apa itu iman?"
  },
  AvgDialog_47165_Content_107 = {
    Text = "Guruku pernah memberitahuku, iman adalah segala tanggung jawab dan makna, dan selain itu, tidak ada pikiran lain."
  },
  AvgDialog_47165_Content_108 = {
    Text = "Hmm... Kata-katamu terdengar rumit sekali..."
  },
  AvgDialog_47165_Content_109 = {
    Text = "Sebenarnya sangat sederhana. Deborah, kau adalah satu-satunya sahabat sejatiku, sejak dulu..."
  },
  AvgDialog_47165_Content_11 = {
    Text = "Miriam memiliki kekuatan yang luar biasa. Kalian memiliki banyak pejuang yang gagah berani, tetapi untuk memusnahkannya, kalian harus membayar harga yang sangat mahal."
  },
  AvgDialog_47165_Content_110 = {
    Text = "Aku pernah berjanji padamu, akan memberikanmu kehormatan tertinggi, menjadikanmu warga pertama Kerajaan Tuhan. Aku akan menjadikan keluargamu, keluarga paling bahagia di Kerajaan Tuhan."
  },
  AvgDialog_47165_Content_111 = {
    Text = "Aku akan menepatinya, Deborah. Aku akan mengingat harapanmu untuk masa depan. Sekarang, aku akan menganugerahkan kehormatan ini kepadamu."
  },
  AvgDialog_47165_Content_112 = {
    Text = "Kerajaan Tuhan pasti akan turun, dan tangga menuju Kerajaan Tuhan akan dinamai dengan namamu. Semua umat beriman, semua warga Kerajaan Tuhan, akan mengingatmu..."
  },
  AvgDialog_47165_Content_113 = {Text = "!!!"},
  AvgDialog_47165_Content_114 = {
    Text = "Tunggu, Miriam, aku..."
  },
  AvgDialog_47165_Content_115 = {
    Text = "Deborah bahkan belum sempat merasa takut. Kata-katanya belum selesai terucap ketika kabut hitam berbentuk ular merasuk ke dalam tubuhnya. Ia merasa pusing, lalu terkulai di bahu Miriam."
  },
  AvgDialog_47165_Content_116 = {
    Text = "Kau tidak boleh melakukan ini..."
  },
  AvgDialog_47165_Content_117 = {
    Text = "Aku harus melakukannya."
  },
  AvgDialog_47165_Content_118 = {
    Text = "Ayah dan Raja tidak akan ingin melihatmu seperti ini!"
  },
  AvgDialog_47165_Content_119 = {
    Text = "Kau hanyalah anak berusia sembilan tahun, Miriam. Kau tidak mengerti."
  },
  AvgDialog_47165_Content_12 = {
    Text = "Aku bersedia bekerja sama dengan kalian. Ini... adalah tanda ketulusanku."
  },
  AvgDialog_47165_Content_120 = {
    Text = "Ayah dan Raja ingin melihat turunnya Kerajaan Tuhan."
  },
  AvgDialog_47165_Content_121 = {
    Text = "Aku sedang mewujudkan keinginan mereka, bukan?"
  },
  AvgDialog_47165_Content_122 = {
    Text = "Tapi... ini salah..."
  },
  AvgDialog_47165_Content_123 = {
    Text = "Hanya Kerajaan Tuhan, yang benar."
  },
  AvgDialog_47165_Content_124 = {
    Text = "Suara Miriam sangat tenang, seolah menceritakan sesuatu yang seharusnya dipahami semua orang sebagai hal yang sudah semestinya."
  },
  AvgDialog_47165_Content_125 = {
    Text = "Miriam kecil menatap dirinya bertahun-tahun kemudian. Dia percaya diri, teguh, dan kuat. Dia adalah Pendeta Agung Lemuria yang tak terbantahkan, utusan tunggal Kerajaan Tuhan."
  },
  AvgDialog_47165_Content_126 = {
    Text = "Gadis kecil yang gemetar di bawah reruntuhan, memanggil-manggil ayahnya, sudah tidak ada hubungannya lagi dengannya."
  },
  AvgDialog_47165_Content_127 = {
    Text = "Aku mengerti... Kurasa, sudah waktunya aku pergi."
  },
  AvgDialog_47165_Content_128 = {
    Text = "Dia menatapnya dengan sedih."
  },
  AvgDialog_47165_Content_129 = {
    Text = "Semoga kau bisa menemukan Kerajaan Tuhanmu sendiri, Miriam."
  },
  AvgDialog_47165_Content_13 = {
    Text = "Para penjaga mengangkut beberapa peti masuk ke ruang tamu. Peti-peti itu dibuka, dan cahaya emas yang berkilauan menyinari wajah Edmond tua, membuatnya terpana sesaat."
  },
  AvgDialog_47165_Content_130 = {
    Text = "Pasti akan kutemukan."
  },
  AvgDialog_47165_Content_131 = {
    Text = "Dia tahu, itu adalah harapan dan perpisahan terakhir. Miriam kecil pergi, seolah tak pernah ada. Miriam tidak menoleh sedikit pun ke arah dia menghilang."
  },
  AvgDialog_47165_Content_132 = {
    Text = "Dia memeluk Deborah, tersenyum sambil menepuk-nepuk punggungnya, mulutnya pelan bersenandung lagu anak-anak Lemuria, seolah sedang menidurkan seorang anak."
  },
  AvgDialog_47165_Content_133 = {
    Text = "Di luar jendela, matahari senja tenggelam, dan bintang-bintang mulai memasuki lintasan masing-masing."
  },
  AvgDialog_47165_Content_134 = {
    Text = "——Saat bintang-bintang kembali ke posisinya, sebentar lagi akan tiba."
  },
  AvgDialog_47165_Content_14 = {
    Text = "Ketulusanmu sudah kurasakan, Tuan Goliah... Apa rencanamu?"
  },
  AvgDialog_47165_Content_15 = {
    Text = "Papas, Enorm, dan beberapa keluarga besar lainnya, sudah kukunjungi satu per satu."
  },
  AvgDialog_47165_Content_16 = {
    Text = "Pasukan dari masing-masing keluarga sudah mulai berkumpul. Sebelum pasukan mulai bergerak, kurasa kita perlu mengadakan sebuah pertemuan."
  },
  AvgDialog_47165_Content_17 = {
    Text = "Aku akan memberitahu kalian segalanya tentang Keluarga Orn, dan juga memberikan saran-saranku kepada kalian."
  },
  AvgDialog_47165_Content_18 = {
    Text = "Aku akan membuat kalian bisa membunuh Miriam dengan harga seminimal mungkin. Dan juga..."
  },
  AvgDialog_47165_Content_19 = {
    Text = "Dia mendekatkan mulutnya ke telinga Edmond tua."
  },
  AvgDialog_47165_Content_2 = {
    Text = "Silakan duduk, Goliath dari keluarga Orne."
  },
  AvgDialog_47165_Content_20 = {
    Text = "Terus terang saja, Tuan Edmond, aku sedang mencari orang yang tepat untuk kerja sama yang lebih mendalam."
  },
  AvgDialog_47165_Content_21 = {
    Text = "Maaf jika ini terdengar kurang sopan, tetapi kekuatan Keluarga Edmond tidaklah termasuk yang terkuat di antara keluarga-keluarga besar. Justru itulah alasan aku bersedia bekerja sama denganmu."
  },
  AvgDialog_47165_Content_22 = {
    Text = "Kekayaan dan tanah Keluarga Orn, bahkan sebagian kekuatan Miriam, aku bisa mempersembahkan sebagiannya kepadamu."
  },
  AvgDialog_47165_Content_23 = {
    Text = "Yang kuinginkan adalah hubungan aliansi yang mendalam. Bagaimanapun, yang kita kejar bukan hanya sekadar mengalahkan Miriam dan Keluarga Orn, bukan begitu?"
  },
  AvgDialog_47165_Content_24 = {
    Text = "Sang lelaki tua menatap Goliah dan menampilkan senyum penuh pengertian."
  },
  AvgDialog_47165_Content_25 = {
    Text = "Hehehe, dasar anak muda yang penuh ambisi..."
  },
  AvgDialog_47165_Content_26 = {
    Text = "Pandanganmu sangat jauh ke depan, Tuan Goliah. Benar, kehancuran Keluarga Orn hanyalah sebuah pembukaan."
  },
  AvgDialog_47165_Content_27 = {
    Text = "Aliansi kita pasti akan membawa tanah ini memasuki sebuah dinasti yang baru..."
  },
  AvgDialog_47165_Content_29 = {
    Text = "Adikku... Ayah... Aah!..."
  },
  AvgDialog_47165_Content_3 = {
    Text = "Pilihan kata sang pria tua masih mempertahankan sopan santun dasar kaum bangsawan, namun nada meremehkan dalam suaranya tidak disembunyikan sama sekali."
  },
  AvgDialog_47165_Content_30 = {
    Text = "Miriam? Miriam, kau baik-baik saja?"
  },
  AvgDialog_47165_Content_31 = {
    Text = "Miriam terbangun dari tidurnya dengan terkejut, keringat membasahi punggungnya."
  },
  AvgDialog_47165_Content_32 = {
    Text = "Bayangan ayah dan adik perempuannya menghilang dari hadapannya, yang terlihat kini adalah wajah Deborah yang penuh kekhawatiran."
  },
  AvgDialog_47165_Content_33 = {
    Text = "Memimpikan keluargamu?"
  },
  AvgDialog_47165_Content_34 = {
    Text = "Aku melihat Ayah dan adikku, mereka semua berwajah manusia ikan... Ayah bilang, mereka sudah hidup seperti itu selama puluhan ribu tahun..."
  },
  AvgDialog_47165_Content_35 = {
    Text = "Dia bertanya padaku, berapa lama lagi dia harus menunggu..."
  },
  AvgDialog_47165_Content_36 = {
    Text = "Deborah, aku sudah... tidak bisa mengingat wajah Ayah lagi..."
  },
  AvgDialog_47165_Content_37 = {
    Text = "Miriam tidak sanggup melanjutkan kata-katanya. Dia bersandar lemah di pagar tempat tidur."
  },
  AvgDialog_47165_Content_38 = {
    Text = "Deborah menempelkan sapu tangan di dahi Miriam, sambil menepuk-nepuk lembut punggungnya."
  },
  AvgDialog_47165_Content_39 = {
    Text = "Belakangan ini kamu terus-terusan bermimpi buruk... Lukamu belum sembuh sepenuhnya, jangan terlalu memikirkan hal-hal itu."
  },
  AvgDialog_47165_Content_4 = {
    Text = "Tuan Edmond, saya sangat memahami permusuhan kalian terhadap keluarga Orne."
  },
  AvgDialog_47165_Content_40 = {
    Text = "Tidak apa-apa, tidak apa-apa. Setelah tubuhmu pulih dan Kerajaan Tuhan tiba, kamu akan segera bisa bertemu dengan keluargamu."
  },
  AvgDialog_47165_Content_41 = {
    Text = "Maaf, Deborah... Baik di Lemuria maupun sekarang, kamu sudah banyak membantuku..."
  },
  AvgDialog_47165_Content_42 = {
    Text = "Kamu bicara hal yang tidak kumengerti lagi... Untuk apa minta maaf?"
  },
  AvgDialog_47165_Content_43 = {
    Text = "Miriam menggelengkan kepala, tidak menjelaskan lebih lanjut. Dengan ekspresi rumit, dia memandang perut Deborah yang membesar."
  },
  AvgDialog_47165_Content_44 = {
    Text = "Lukaku sudah hampir sembuh. Kamu sebentar lagi akan menjadi seorang ibu, lebih baik jaga dirimu sendiri dulu."
  },
  AvgDialog_47165_Content_45 = {
    Text = "Aku dan dia sama-sama sehat kok..."
  },
  AvgDialog_47165_Content_46 = {
    Text = "Ah! Miriam! Miriam, cepat dengarkan... Dia sedang menendangku!"
  },
  AvgDialog_47165_Content_47 = {
    Text = "Benarkah? Coba aku dengarkan..."
  },
  AvgDialog_47165_Content_48 = {
    Text = "Miriam membungkukkan badan, mendekatkan telinganya ke perut Deborah."
  },
  AvgDialog_47165_Content_49 = {
    Text = "Ah, benar... Aku bisa mendengarnya..."
  },
  AvgDialog_47165_Content_5 = {
    Text = "Saat ini, keluarga Orne telah menempuh jalan yang agak... tidak biasa..."
  },
  AvgDialog_47165_Content_50 = {
    Text = "Nak, lihatlah, ini ibu baptismu, pendeta utama kita, Miriam. Dialah yang merasakan kehadiranmu, sehingga kami bisa tahu sejak awal bahwa kamu seorang putri, dan menyiapkan hadiah untuk kelahiranmu."
  },
  AvgDialog_47165_Content_51 = {
    Text = "Setelah itu, dia juga akan membawa seluruh keluarga kita bersama-sama, pergi ke Negeri Dewa yang ada dalam legenda!"
  },
  AvgDialog_47165_Content_52 = {
    Text = "Saat itu tiba, ayahmu akan terus menjadi kusir Pendeta Agung, dan aku akan terus menjadi pelayan Pendeta Agung…"
  },
  AvgDialog_47165_Content_53 = {
    Text = "Di Negeri Dewa tidak perlu kusir dan pelayan."
  },
  AvgDialog_47165_Content_54 = {
    Text = "Tidak boleh begitu, kalau begitu tidak akan semenyenangkan saat bersamamu."
  },
  AvgDialog_47165_Content_55 = {
    Text = "Miriam menatap perut Deborah, menampakkan senyum yang rumit."
  },
  AvgDialog_47165_Content_56 = {
    Text = "Deborah, kau satu-satunya temanku. Ada sesuatu yang ingin kusampaikan padamu…"
  },
  AvgDialog_47165_Content_57 = {
    Text = "Lapor, Yang Mulia Pendeta Agung, Tuan Goliath sedang menunggu di pintu masuk."
  },
  AvgDialog_47165_Content_58 = {
    Text = "…Suruh dia masuk."
  },
  AvgDialog_47165_Content_59 = {
    Text = "Sepertinya, kejutan ini baru bisa kudengar nanti~"
  },
  AvgDialog_47165_Content_6 = {
    Text = "Jalan yang tidak biasa? Kalian para makhluk aneh mutan itu... Bagi semua orang di benua ini, keberadaan kalian adalah sebuah penistaan."
  },
  AvgDialog_47165_Content_60 = {
    Text = "Deborah memasang wajah lucu pada Miriam, lalu mundur ke ruangan sebelah. Goliath mendorong pintu masuk, menatap sosok Deborah yang berlalu, tampak memikirkan sesuatu."
  },
  AvgDialog_47165_Content_61 = {
    Text = "Bagaimana perkembangan komunikasi dengan keluarga-keluarga lain?"
  },
  AvgDialog_47165_Content_62 = {
    Text = "Orang-orang di daratan memang lebih cerdas daripada bangsa Filistin, tapi selama mereka manusia, apa yang mereka inginkan tidak akan jauh berbeda."
  },
  AvgDialog_47165_Content_63 = {
    Text = "Aku bilang pada setiap keluarga bahwa aku ingin menjadi sekutu terdekat mereka. Kita akan bersama-sama membunuhmu, memusnahkan Keluarga Orn, lalu aku akan membagikan tanah, kekayaan, dan kekuatan di sini kepada mereka."
  },
  AvgDialog_47165_Content_64 = {
    Text = "Janji ini penuh celah, tapi orang-orang itu semua adalah maniak sombong yang percaya bahwa mereka bisa berdiri di puncak dunia, menganggap semua itu adalah takdir mereka, tanpa keraguan sedikit pun."
  },
  AvgDialog_47165_Content_65 = {
    Text = "Pasukan mereka sudah mulai berkumpul. Hari Bintang Sejajar tinggal beberapa hari lagi, saat itu kita akan mengadakan sebuah perjamuan."
  },
  AvgDialog_47165_Content_66 = {
    Text = "Itu pasti akan menjadi perjamuan yang sangat menakjubkan."
  },
  AvgDialog_47165_Content_67 = {
    Text = "Goliath tersenyum jahat, memperlihatkan gigi-gigi tajam bak hiu."
  },
  AvgDialog_47165_Content_68 = {
    Text = "Kerja bagus."
  },
  AvgDialog_47165_Content_69 = {
    Text = "Bagaimana denganmu? Pencarian Bayi Suci, sudah sejauh mana persiapannya?"
  },
  AvgDialog_47165_Content_7 = {
    Text = "Percayalah, Tuan Edmond, ini hanyalah sebuah kecelakaan. Penyihir perempuan itu, Miriam, dialah yang menyebabkan semua ini."
  },
  AvgDialog_47165_Content_70 = {
    Text = "Di seluruh wilayah Keluarga Orn, semua orang sudah kucari habis."
  },
  AvgDialog_47165_Content_71 = {
    Text = "Aku menemukan beberapa bayi yang akan lahir tepat pada saat bintang berada di posisi yang benar, tapi keluarga mereka tidak menganut kepercayaan Kerajaan Dewa."
  },
  AvgDialog_47165_Content_72 = {
    Text = "Orang seperti itu tidak layak menjadi wadah untuk mengandung sang Raja."
  },
  AvgDialog_47165_Content_73 = {
    Text = "Harus lahir tepat pada saat itu, dan keluarganya juga harus menganut kepercayaan Kerajaan Dewamu. Ini memang sulit."
  },
  AvgDialog_47165_Content_74 = {
    Text = "Sekarang wilayah kekuasaan Klan Orn sangat sempit, kepercayaanmu belum sempat tersebar luas, orang yang bisa kita temukan juga sangat sedikit..."
  },
  AvgDialog_47165_Content_75 = {
    Text = "Sayang anak Deborah masih tiga bulan lagi baru lahir. Kalau tidak, dia pasti akan menjadi kandidat yang sempurna."
  },
  AvgDialog_47165_Content_76 = {
    Text = "Lalu sekarang bagaimana? Bagaimana kalau kita coba saja dengan bayi-bayi yang lahir pada saat bintang berada di posisi yang benar?"
  },
  AvgDialog_47165_Content_77 = {
    Text = "Jika penanaman kembali gagal, Janin Suci bisa rusak... Aku tidak bisa membiarkan sang Raja menanggung risiko seperti itu."
  },
  AvgDialog_47165_Content_78 = {
    Text = "Kalau begitu memang sulit... Aku tidak bisa memikirkan cara lain untuk membantumu."
  },
  AvgDialog_47165_Content_79 = {
    Text = "Goliat bersandar ke belakang di kursinya. Melihat arah pandangan Miriam dan tatapan matanya, Goliat tiba-tiba duduk tegak."
  },
  AvgDialog_47165_Content_8 = {
    Text = "Saya tahu, Anda dan beberapa keluarga lainnya sedang diam-diam merundingkan rencana untuk mengepung dan menumpas keluarga Orne..."
  },
  AvgDialog_47165_Content_80 = {
    Text = "Tunggu... Jangan bilang kau bermaksud..."
  },
  AvgDialog_47165_Content_81 = {
    Text = "Miriam perlahan menolehkan kepalanya, menatap Goliat. Kedua mata itu membuat Goliat merasakan hawa dingin yang menjalar dari tulang belakang hingga ke ubun-ubun."
  },
  AvgDialog_47165_Content_82 = {
    Text = "Memang kau banget ya, Miriam. Kau benar-benar@2orang gila."
  },
  AvgDialog_47165_Content_83 = {
    Text = "Tapi tenang saja, aku tidak keberatan soal itu. Pilihanku tidak salah. Hanya dengan bekerja sama dengan orang gila sepertimu, barulah bisa melakukan hal yang tidak bisa dilakukan orang biasa."
  },
  AvgDialog_47165_Content_84 = {
    Text = "Pergilah bersiap... Aku juga harus mulai mempersiapkan ritualku."
  },
  AvgDialog_47165_Content_85 = {
    Text = "Hehe... Saat bintang berada di posisi yang benar, pasti akan menjadi malam yang menakjubkan. Sampai jumpa nanti, Tuan Pendeta Agung."
  },
  AvgDialog_47165_Content_87 = {
    Text = "Pintu terbuka, cahaya senja yang lembut menyinari Deborah."
  },
  AvgDialog_47165_Content_88 = {
    Text = "Sambil bersenandung lagu daerah, ia mengelus perutnya yang membuncit. Mungkin di benaknya ia sedang memikirkan apa yang harus disiapkan untuk sang bayi, atau mungkin sedang memikirkan nama apa yang akan diberikan untuk anaknya."
  },
  AvgDialog_47165_Content_89 = {
    Text = "Melihat Miriam masuk, ia melambaikan tangan kepadanya."
  },
  AvgDialog_47165_Content_9 = {
    Text = "Tubuh Edmond tua mendadak menegang, sedikit menegakkan duduknya. Goliath melihat semua itu, lalu tersenyum kepadanya."
  },
  AvgDialog_47165_Content_90 = {
    Text = "Miriam, kalian sudah selesai bicara? Bagaimana hasilnya?!"
  },
  AvgDialog_47165_Content_91 = {
    Text = "Sangat lancar, Goliat sudah mempersiapkan semuanya dengan baik."
  },
  AvgDialog_47165_Content_92 = {
    Text = "Bagus sekali! Kalau begitu, apakah kita akan segera menyambut Kerajaan Tuhan!"
  },
  AvgDialog_47165_Content_93 = {
    Text = "Miriam tersenyum padanya. Deborah sudah terlalu lama bersamanya, sehingga kelelahan di balik senyum Miriam dengan mudah tertangkap olehnya."
  },
  AvgDialog_47165_Content_94 = {
    Text = "Miriam, sepertinya kondisimu kurang baik."
  },
  AvgDialog_47165_Content_95 = {
    Text = "Kau bilang semuanya berjalan lancar di sisi Goliath... Lalu bagaimana dengan sisi kita? Apakah ada masalah?"
  },
  AvgDialog_47165_Content_96 = {
    Text = "Aku tidak bisa menemukan orang yang tepat, Deborah... Keyakinan kita belum tersebar luas, tidak ada bayi suci yang memenuhi syarat..."
  },
  AvgDialog_47165_Content_97 = {
    Text = "Aku ingin menunggu, menunggu hingga saat bintang-bintang kembali sejajar. Tapi Ayah terus mendesak, Raja terus mendesak... Aku tidak bisa menunggu lebih lama lagi, Deborah..."
  },
  AvgDialog_47165_Content_98 = {
    Text = "Dia memeluk Deborah, membenamkan wajahnya di perut Deborah. Air mata jatuh, membasahi pakaian Deborah."
  },
  AvgDialog_47165_Content_99 = {
    Text = "Ah, andai saja anakku lahir dua atau tiga bulan lebih awal, maka aku bisa membantumu..."
  },
  AvgDialog_47166_Content_1 = {
    Text = "Gelembung Masa Lalu"
  },
  AvgDialog_47166_Content_10 = {
    Text = "Awalnya berencana untuk kembali lagi kalau ada waktu, tapi belum sempat, sudah terjadi segudang masalah seperti pemberontakan Igren."
  },
  AvgDialog_47166_Content_100 = {
    Text = "Heh, si kecil, kau makin lama makin memahami diriku."
  },
  AvgDialog_47166_Content_101 = {
    Text = "Tuan Goliath, mengapa Anda tidak membunuh Miriam?"
  },
  AvgDialog_47166_Content_102 = {
    Text = "Membunuhnya, aku memang bisa bebas. Tapi, apa gunanya kebebasan?"
  },
  AvgDialog_47166_Content_103 = {
    Text = "Goliath memandangi kawanan burung di atas laut, lalu memejamkan mata dengan nyaman."
  },
  AvgDialog_47166_Content_104 = {
    Text = "Aku bisa pergi menuntut balas pada suku-suku yang pernah mengalahkan bangsa Filistin, bisa terus membawa kaumku merampok di pesisir. Tapi, hanya sebatas itu saja."
  },
  AvgDialog_47166_Content_105 = {
    Text = "Miriam memberiku kekuatan, tapi kekuatan ini belum cukup. Jauh dari cukup."
  },
  AvgDialog_47166_Content_106 = {
    Text = "Hanya kekuatan kasar belaka, menghadapi pasukan reguler yang kuat dari kerajaan-kerajaan itu, kami tetap hanya bisa diburu, terus melarikan diri di perairan ini seperti anjing liar."
  },
  AvgDialog_47166_Content_107 = {
    Text = "Yang kuinginkan adalah kekuatan yang jauh lebih besar dari apa yang Miriam berikan padaku."
  },
  AvgDialog_47166_Content_108 = {
    Text = "—Namanya kekuasaan, Abishai. Dibandingkan kekuasaan, kebebasan tak ada artinya."
  },
  AvgDialog_47166_Content_109 = {
    Text = "Cahaya merah menyala berpendar samar di matanya, ia menjilat bibirnya sendiri, tersenyum penuh kenikmatan."
  },
  AvgDialog_47166_Content_11 = {
    Text = "Ini kampung halamanmu, benar?"
  },
  AvgDialog_47166_Content_110 = {
    Text = "Miriam sekarang mengendalikan Klan Orn. Aku bisa memanfaatkannya untuk memperbesar kekuasaan ini berlipat-lipat ganda."
  },
  AvgDialog_47166_Content_111 = {
    Text = "Pada saat itu, barulah aku merebut kekuasaan itu dari tangannya."
  },
  AvgDialog_47166_Content_112 = {
    Text = "Tapi, Miriam begitu kuat, risikonya terlalu besar…"
  },
  AvgDialog_47166_Content_113 = {
    Text = "Abisa, aku adalah pemimpin bangsa Filistin, masih ingat? Kita terus-menerus kalah, melarikan diri. Aku ingin membawa bangsa Filistin meraih satu kemenangan."
  },
  AvgDialog_47166_Content_114 = {
    Text = "Soal risiko... menurutmu, apa lagi yang bisa kupertaruhkan?"
  },
  AvgDialog_47166_Content_115 = {
    Text = "Sang raksasa menepuk bahu Abisa dengan lembut, lalu bangkit dan berjalan menuju ranjang tempat Miriam terbaring."
  },
  AvgDialog_47166_Content_117 = {
    Text = "Raja... Tuanku... Engkau meninggalkanku... mengapa..."
  },
  AvgDialog_47166_Content_118 = {
    Text = "Darah merembes dari perban di dadanya, namun Miriam sama sekali tak menyadarinya. Dia terbaring lemah di atas ranjang, menatap kosong ke hamparan laut yang tak berujung."
  },
  AvgDialog_47166_Content_119 = {
    Text = "Sejak kau sadar, kau terus mengulang kalimat itu sepanjang jalan. Bisakah kau mengganti kata-katamu sedikit?"
  },
  AvgDialog_47166_Content_12 = {
    Text = "Penampilan pulau ini sudah banyak berubah. Mungkin ini Lemuria, mungkin juga bukan, aku tidak yakin."
  },
  AvgDialog_47166_Content_120 = {
    Text = "Penampilanmu sekarang seperti ikan mati yang digantung."
  },
  AvgDialog_47166_Content_121 = {
    Text = "Janin suci itu pasti bisa dipelihara dengan tubuh, aku merasakannya dengan sangat jelas... Caraku tidak salah!"
  },
  AvgDialog_47166_Content_122 = {
    Text = "Tapi Raja menolakku... Raja menolakku!"
  },
  AvgDialog_47166_Content_123 = {
    Text = "Goliath melihat dengan jelas kesakitan dan kebingungan Miriam. Semuanya berlalu dalam sekejap."
  },
  AvgDialog_47166_Content_124 = {
    Text = "Raja pernah memberitahuku, pada saat bintang-bintang berada di posisi yang tepat, Dia akan kembali hadir di dunia, Lemuria akan kembali hadir di dunia..."
  },
  AvgDialog_47166_Content_125 = {
    Text = "Bintang, bintang... jangan-jangan ini berkaitan dengan bintang-bintang..."
  },
  AvgDialog_47166_Content_126 = {
    Text = "Aku mengerti, aku mengerti! Kekuatan Raja berasal dari bintang-bintang. Mungkin, hanya orang yang lahir pada saat bintang-bintang berada di posisi yang tepat yang bisa memelihara janin suci Raja..."
  },
  AvgDialog_47166_Content_127 = {
    Text = "Saat bintang-bintang berada di posisi yang tepat berikutnya akan segera tiba, aku bisa mencari bayi yang baru saja lahir... uhuk uhuk..."
  },
  AvgDialog_47166_Content_128 = {
    Text = "Mata Miriam berkilat penuh semangat. Dia bangkit tiba-tiba, menarik luka di tubuhnya, dan mulai batuk dengan hebat."
  },
  AvgDialog_47166_Content_129 = {
    Text = "Pulihkan dulu lukamu. Kalau kau mati di sini, Rajamu juga tidak akan bisa hidup."
  },
  AvgDialog_47166_Content_13 = {
    Text = "Puluhan ribu tahun, banyak hal yang bisa berubah……"
  },
  AvgDialog_47166_Content_130 = {
    Text = "Mencari bayi suci, memelihara janin suci, mengumpulkan pengikut... semua yang akan kau lakukan selanjutnya membutuhkan banyak uang, kekuatan, tenaga kerja, dan kekuasaan."
  },
  AvgDialog_47166_Content_131 = {
    Text = "Aku tidak punya waktu untuk memikirkan semua itu..."
  },
  AvgDialog_47166_Content_132 = {
    Text = "Itulah makna kerja sama kita. Aku punya waktu. Banyak sekali."
  },
  AvgDialog_47166_Content_133 = {
    Text = "Untuk apa yang harus dilakukan selanjutnya, kekuatan keluarga Orn saja jauh dari cukup. Kita perlu mendapatkan dukungan dari lebih banyak keluarga di benua ini."
  },
  AvgDialog_47166_Content_134 = {
    Text = "Semua kekuatan keluarga Orne, kau berhak menggunakannya. Urusan ini, kuserahkan padamu."
  },
  AvgDialog_47166_Content_135 = {
    Text = "Sebelum saat penyelarasan bintang berikutnya tiba, aku akan mencari wadah yang cocok untuk janin suci sang Raja."
  },
  AvgDialog_47166_Content_136 = {
    Text = "Miriam sedikit memiringkan kepalanya, melirik Goliath sekilas."
  },
  AvgDialog_47166_Content_137 = {
    Text = "Kekuatan, kekuasaan, kekayaan, kehormatan... Aku tahu apa yang ingin kaulakukan, orang Filistin. Aku tidak peduli."
  },
  AvgDialog_47166_Content_138 = {
    Text = "Nyawamu kubiarkan, karena kau cukup cerdas. Jangan berbuat bodoh."
  },
  AvgDialog_47166_Content_139 = {
    Text = "Goliath menyunggingkan senyum yang jahat."
  },
  AvgDialog_47166_Content_14 = {
    Text = "Miriam dengan hati-hati meraba pasir halus di tepi pantai. Dia teringat kehancuran kampung halamannya, teringat dirinya berdiri di antara para manusia ikan, menatap putus asa saat lautan menelan segalanya dari Lemuria."
  },
  AvgDialog_47166_Content_140 = {
    Text = "Siap, Tuan Pendeta Agung."
  },
  AvgDialog_47166_Content_141 = {
    Text = "Miriam, kita sudah sampai di rumah!"
  },
  AvgDialog_47166_Content_142 = {
    Text = "Di sepanjang garis pantai berkelok-kelok wilayah keluarga Orne, makhluk-makhluk manusia ikan yang aneh itu menerima panggilan, berjajar rapat di tepi pantai, menyambut tuan mereka."
  },
  AvgDialog_47166_Content_143 = {
    Text = "Goliath memandang puas sosok-sosok aneh mereka, bilah tajam di tangan mereka, serta tatapan yang setia sekaligus bodoh."
  },
  AvgDialog_47166_Content_144 = {
    Text = "Dia memandang ke tanah subur tak berujung di balik para manusia ikan itu, bagaikan hiu memandang paus yang sekarat."
  },
  AvgDialog_47166_Content_15 = {
    Text = "Kini, dia kembali muncul di sini. Tak lama lagi, dia akan membawa Lemuria kembali ke perairan ini."
  },
  AvgDialog_47166_Content_16 = {
    Text = "Di mana kau menemukan patung itu, bawa aku ke sana."
  },
  AvgDialog_47166_Content_17 = {Text = "Ikuti aku."},
  AvgDialog_47166_Content_18 = {
    Text = "Kau bilang sebelumnya, apa yang kau cari? Relikui suci Sang Raja? Benda itu bisa digunakan untuk apa?"
  },
  AvgDialog_47166_Content_19 = {
    Text = "Untuk membangkitkan Sang Raja, perlu menemukan substansi perak yang ditinggalkan setelah kematian Sang Raja. Ini adalah kebutuhan mutlak untuk ritual tersebut."
  },
  AvgDialog_47166_Content_2 = {
    Text = "Lambung kapal bergesekan dengan pasir halus, merapat di tepi pantai. Miriam turun dari kapal, memandang pulau terpencil di hadapannya."
  },
  AvgDialog_47166_Content_20 = {
    Text = "Seperti apa tepatnya ritual itu? Mirip dengan ritual saat kau mengubah kami menjadi manusia ikan?"
  },
  AvgDialog_47166_Content_21 = {
    Text = "Bukankah itu berarti kau harus menggali mayat Rajamu? Dia sudah mati puluhan ribu tahun, mayatnya pasti langsung hancur kalau disentuh……"
  },
  AvgDialog_47166_Content_22 = {
    Text = "Ssshh——"
  },
  AvgDialog_47166_Content_23 = {
    Text = "Cahaya ungu di lehernya berkedip, rasa sakit yang menusuk membuat Golia menarik napas tajam."
  },
  AvgDialog_47166_Content_24 = {
    Text = "Kalau berani tidak sopan lagi terhadap Sang Raja, hukumannya tidak akan seringan ini. Tunjukkan jalannya dengan benar."
  },
  AvgDialog_47166_Content_26 = {
    Text = "Rumput liar dan hutan lebat tersingkap oleh kabut hitam, sebuah teluk kecil muncul di hadapan semua orang."
  },
  AvgDialog_47166_Content_27 = {
    Text = "Eh, tadi saat melihat ke arah sini dari arah lain, sepertinya teluk ini tidak terlihat? Bentuk teluk ini juga aneh sekali……"
  },
  AvgDialog_47166_Content_28 = {
    Text = "Benar, jika diamati dari arah yang berbeda, penampilannya akan berubah, bahkan menghilang. Jadi kupikir, mungkin semacam sihir atau sejenisnya……"
  },
  AvgDialog_47166_Content_29 = {
    Text = "Ini adalah mimpi. Mimpi yang diciptakan oleh Sang Raja untuk melindungi Lemuria, ditujukan bagi para penyerbu!"
  },
  AvgDialog_47166_Content_3 = {
    Text = "Pulau ini sangat kecil, bagaikan sebongkah karang yang terjal. Vegetasi kuno dan rimbun menutupi karang itu, menceritakan kisah kesendirian sepanjang waktu yang panjang."
  },
  AvgDialog_47166_Content_30 = {
    Text = "Tatapan Miriam mulai dipenuhi kegembiraan."
  },
  AvgDialog_47166_Content_31 = {Text = "\"Mimpi\"?"},
  AvgDialog_47166_Content_32 = {
    Text = "Patung itu, ditemukan di mana?"
  },
  AvgDialog_47166_Content_33 = {Text = "Di sana."},
  AvgDialog_47166_Content_34 = {
    Text = "Goliath menunjuk ke sebuah altar tak jauh dari sana. Altar itu tertutup rumput liar, hampir tak bisa dikenali bentuk aslinya."
  },
  AvgDialog_47166_Content_35 = {
    Text = "Deborah mengeluarkan patung Thulu dan meletakkannya di atas altar. Alasnya pas sempurna dengan altar."
  },
  AvgDialog_47166_Content_36 = {
    Text = "Sepertinya... tidak ada perubahan apa pun... Apa aku salah menaruhnya?"
  },
  AvgDialog_47166_Content_37 = {
    Text = "Kalau cuma menaruhnya saja sudah ada perubahan, aku sudah masuk dari dulu dan mengambil semua barang berharga di dalamnya."
  },
  AvgDialog_47166_Content_38 = {
    Text = "Dia menatap Miriam dengan pandangan bertanya. Miriam berjalan ke sisi altar, mengeluarkan belati, dan menyayat jarinya sendiri."
  },
  AvgDialog_47166_Content_39 = {
    Text = "Dari ujung jari putihnya yang bersih, setetes darah merah pekat jatuh menetes ke atas patung."
  },
  AvgDialog_47166_Content_4 = {
    Text = "Peradaban Lemuria yang hilang, ini adalah legenda kuno yang beredar di antara suku Filistin."
  },
  AvgDialog_47166_Content_40 = {Text = "BYUR—"},
  AvgDialog_47166_Content_41 = {
    Text = "Seolah ada riak yang menyebar dari udara, pulau kecil tempat mereka berpijak mulai bergetar."
  },
  AvgDialog_47166_Content_42 = {Text = "Ini...?"},
  AvgDialog_47166_Content_43 = {
    Text = "Bentuk teluk mulai mengabur, air laut berputar dan menjulang tegak, membentuk pusaran raksasa, bagaikan sebuah gerbang besar yang mengundang mereka semua untuk masuk."
  },
  AvgDialog_47166_Content_44 = {
    Text = "Sang Raja, jadi inilah makam yang Anda siapkan untuk diri sendiri... Benih harapan yang Anda tinggalkan untuk Lemuria ada di dalamnya, bukan?"
  },
  AvgDialog_47166_Content_45 = {
    Text = "Hei, tunggu, kau tidak sayang nyawamu?!..."
  },
  AvgDialog_47166_Content_46 = {
    Text = "Miriam berjalan penuh semangat menuju pusat pusaran, mengabaikan teriakan Goliath. Goliath mengumpat pelan, lalu menyusul."
  },
  AvgDialog_47166_Content_47 = {
    Text = "Ini... di dalam air?"
  },
  AvgDialog_47166_Content_48 = {
    Text = "Di sini bisa bernapas, bahkan bisa bicara... Ini benar-benar mukjizat!"
  },
  AvgDialog_47166_Content_49 = {
    Text = "Sebuah tangga batu sempit muncul di hadapan mereka, menuju ke dasar laut yang tak terlihat ujungnya. Mereka semua mengikuti Miriam turun ke bawah."
  },
  AvgDialog_47166_Content_5 = {
    Text = "Setelah sebuah perampasan di pesisir berakhir, armadaku terjebak badai dan secara kebetulan tiba di tempat ini."
  },
  AvgDialog_47166_Content_50 = {
    Text = "Benda di depan sana……apa itu?"
  },
  AvgDialog_47166_Content_51 = {
    Text = "Setelah menyusuri tangga batu entah berapa lama, yang muncul di hadapan semua orang adalah sebuah reruntuhan yang megah."
  },
  AvgDialog_47166_Content_52 = {
    Text = "Pilar-pilar batu yang gelap berdiri bagaikan penjaga yang telah dipenggal kepalanya, dengan khidmat menggenggam tombak berjajar di kedua sisi."
  },
  AvgDialog_47166_Content_53 = {
    Text = "Dinding dan jalan yang terbuat dari batu-batu raksasa telah retak dan lapuk, ganggang kotor merambati sisa-sisa tubuh mereka, menceritakan kejayaan masa lalu dan takdir kesepian selama puluhan ribu tahun."
  },
  AvgDialog_47166_Content_54 = {
    Text = "Rombongan itu melangkah perlahan melewati air laut dan pecahan batu, menaiki tangga yang telah patah."
  },
  AvgDialog_47166_Content_55 = {
    Text = "Ini adalah……takhta Lemuria?"
  },
  AvgDialog_47166_Content_56 = {
    Text = "Sebuah takhta batu yang hancur berdiri tegak di ujung jalan. Di atas takhta itu, sebuah kerangka yang telah lama mati menopang dagunya, menatap lelah pada sisa-sisa mimpi masa lalu."
  },
  AvgDialog_47166_Content_57 = {
    Text = "Ini Anda, Tuanku……ini relikui suci Anda! Akhirnya saya menemukan Anda!"
  },
  AvgDialog_47166_Content_58 = {
    Text = "Puluhan ribu tahun, sudah puluhan ribu tahun, akhirnya saya bisa melihat Anda lagi……"
  },
  AvgDialog_47166_Content_59 = {
    Text = "Miriam dengan khusyuk membungkukkan badan, berlutut menyembah kerangka itu."
  },
  AvgDialog_47166_Content_6 = {
    Text = "Patung itu, ditemukan di sini."
  },
  AvgDialog_47166_Content_60 = {
    Text = "Dia berdiri, kedua tangannya menjangkau ke dalam tubuh kotor sang kerangka. Saat dia menarik tangannya keluar, cahaya perak yang redup muncul di tengah reruntuhan yang gelap."
  },
  AvgDialog_47166_Content_61 = {
    Text = "Sebuah bola cahaya perak terbaring di tangan Miriam, sinar berkilauan mengambang di permukaannya, membiaskan cahaya bak mimpi di dasar laut. Miriam mendekatkan diri padanya, mendengarkan napasnya."
  },
  AvgDialog_47166_Content_62 = {
    Text = "Jadi ini yang kau sebut……zat perak itu?"
  },
  AvgDialog_47166_Content_63 = {
    Text = "Berbeda dari apa yang Thales katakan……tapi ini pasti benda yang ingin kucari!"
  },
  AvgDialog_47166_Content_64 = {
    Text = "Kau yakin……benda ini kelihatannya bukan sesuatu yang bagus……"
  },
  AvgDialog_47166_Content_65 = {
    Text = "Jika kau berani tidak sopan lagi terhadap Sang Raja, aku akan menghadiahimu kematian yang paling menyakitkan."
  },
  AvgDialog_47166_Content_66 = {
    Text = "Cuma bercanda, tidak perlu setegang itu……"
  },
  AvgDialog_47166_Content_67 = {
    Text = "Kau bilang deskripsi Thales tentang benda itu berbeda, maka metodenya mungkin juga tidak bisa dipakai. Lalu selanjutnya, apa rencanamu?"
  },
  AvgDialog_47166_Content_68 = {
    Text = "Aku mendengar detak jantung darinya……ini adalah detak jantung Sang Raja……"
  },
  AvgDialog_47166_Content_69 = {
    Text = "Kehidupannya sedang menghilang, aku bisa merasakannya……Jika kita menyuplai kehidupan untuknya, Sang Raja bisa terlahir kembali! Pasti begitu, pasti begitu!"
  },
  AvgDialog_47166_Content_7 = {
    Text = "Apakah ada benda lain?"
  },
  AvgDialog_47166_Content_70 = {
    Text = "Dia mengeluarkan belati."
  },
  AvgDialog_47166_Content_71 = {
    Text = "Miriam! Apa yang mau kau lakukan?"
  },
  AvgDialog_47166_Content_72 = {
    Text = "Mempersembahkan nyawa sendiri untuk memberi makan Sang Raja, menumbuhkan kelahiran kembali Sang Raja… Sungguh kehormatan yang tiada tara… Inilah misi hidupku!"
  },
  AvgDialog_47166_Content_73 = {
    Text = "Berkahilah aku, Deborah…"
  },
  AvgDialog_47166_Content_74 = {Text = "Jleb——"},
  AvgDialog_47166_Content_75 = {
    Text = "Belati persembahan menusuk dada Miriam. Belati itu berputar, mengukir sebuah rongga yang berlumuran darah."
  },
  AvgDialog_47166_Content_76 = {
    Text = "Darah segar menyembur tak terhitung banyaknya, bercampur dengan air laut, mengelilingi singgasana yang telah lapuk. Tulang-belulang yang kering bermandikan darah panas, memandang dingin pemandangan di hadapannya."
  },
  AvgDialog_47166_Content_77 = {
    Text = "Miriam tampak sama sekali tidak merasakan sakit, senyumnya justru semakin fanatik."
  },
  AvgDialog_47166_Content_78 = {
    Text = "Dia menangkup bola cahaya perak yang bergerak-gerak itu, lalu menekannya ke dalam rongga di dadanya."
  },
  AvgDialog_47166_Content_79 = {Text = "Ugh aah—"},
  AvgDialog_47166_Content_8 = {
    Text = "Ada beberapa yang tersebar, sebagian besar tadi sudah kutunjukkan padamu."
  },
  AvgDialog_47166_Content_80 = {
    Text = "Saat memasuki tubuh Miriam, bola cahaya itu memancarkan sinar yang sangat terang dan bergerak-gerak liar. Ia menolak."
  },
  AvgDialog_47166_Content_81 = {
    Text = "Kehidupan Miriam mengalir ke dalamnya, diserap olehnya, lalu dimuntahkan kembali."
  },
  AvgDialog_47166_Content_82 = {
    Text = "Api membakar setiap inci kulitnya, mata pisau menguliti setiap helai dagingnya. Penderitaan tanpa akhir menyerang Miriam, ia berusaha mati-matian mempertahankan senyum terdistorsinya."
  },
  AvgDialog_47166_Content_83 = {
    Text = "Tuanku… kumohon… terimalah… aku…"
  },
  AvgDialog_47166_Content_84 = {Text = "BRAK—"},
  AvgDialog_47166_Content_85 = {Text = "Miriam!"},
  AvgDialog_47166_Content_86 = {
    Text = "Miriam tidak sanggup bertahan lagi dan pingsan tak sadarkan diri."
  },
  AvgDialog_47166_Content_87 = {
    Text = "Keluarkan benda terkutuk itu dari tubuhnya, bawa dia ke kapal."
  },
  AvgDialog_47166_Content_88 = {
    Text = "Tapi Miriam bilang…"
  },
  AvgDialog_47166_Content_89 = {
    Text = "Kalau mau dia hidup, cepat lakukan."
  },
  AvgDialog_47166_Content_9 = {
    Text = "Aku sudah menjelajahi seluruh pulau ini, tidak menemukan reruntuhan apa pun, hanya membawa pergi barang-barang kecil ini."
  },
  AvgDialog_47166_Content_91 = {
    Text = "Kabut dan ombak telah mereda, pulau itu menyusut menjadi sebuah titik tinta yang kesepian di kejauhan."
  },
  AvgDialog_47166_Content_92 = {
    Text = "Goliath bersandar di lambung kapal, menikmati goyangan kapal yang tenang."
  },
  AvgDialog_47166_Content_93 = {
    Text = "Tuan Goliath, sepertinya suasana hati Anda sedang bagus. Matahari ini, pasti mengingatkan Anda pada pantai tanah air Filistin, bukan?"
  },
  AvgDialog_47166_Content_94 = {
    Text = "Pantai tanah air? Hah. Aku hanya berpikir, kalau aku membunuh Miriam sekarang, aku bisa pergi ke mana pun sesukaku."
  },
  AvgDialog_47166_Content_95 = {
    Text = "Hah? Tuan, itu… kurang baik, bukan…"
  },
  AvgDialog_47166_Content_96 = {
    Text = "Kekuatan Miriam jauh lebih besar dariku. Dia sekarang terluka parah, kalau melewatkan hari ini, mungkin akan sulit mendapat kesempatan lagi."
  },
  AvgDialog_47166_Content_97 = {
    Text = "Anda tidak akan melakukan hal seperti itu."
  },
  AvgDialog_47166_Content_98 = {
    Text = "Kenapa, di matamu aku ini orang yang berhati lembut?"
  },
  AvgDialog_47166_Content_99 = {
    Text = "Bukan begitu juga… Hanya saja, kalau Anda benar-benar ingin membunuhnya, Anda sudah bertindak sejak tadi, tidak akan mengobrol santai dengan saya di sini."
  },
  AvgDialog_47167_Content_1 = {
    Text = "Sosok dalam Kabut"
  },
  AvgDialog_47167_Content_10 = {
    Text = "Sampah. Sang raksasa memandang para pengikutnya yang sekarat di sekelilingnya, menyeringai dengan senyum kejam, lalu memejamkan mata."
  },
  AvgDialog_47167_Content_100 = {
    Text = "Kau sudah punya cara untuk mengendalikanku, kesetiaanku seharusnya menjadi lebih kokoh bagimu."
  },
  AvgDialog_47167_Content_101 = {
    Text = "Kerja sama kita masih berlaku. Tidak ada mitra yang lebih cocok dariku, terimalah pengabdianku, dan mari kita lanjutkan kerja sama ini."
  },
  AvgDialog_47167_Content_102 = {
    Text = "Seperti yang kau tahu, aku bukanlah orang yang setia, tapi yang kau butuhkan juga bukan kesetiaanku, melainkan kemampuanku, bukan begitu?"
  },
  AvgDialog_47167_Content_103 = {
    Text = "Miriam memandang Goliat dengan agak terkejut, sesaat kemudian, dia tersenyum."
  },
  AvgDialog_47167_Content_104 = {
    Text = "Tipu muslihat dan kerendahanmu membuatku terkejut……Kau benar, Goliat, orang sepertimu bisa melakukan banyak hal yang tidak bisa kulakukan."
  },
  AvgDialog_47167_Content_105 = {
    Text = "Jadi, kerja sama kita lanjut?"
  },
  AvgDialog_47167_Content_106 = {
    Text = "Goliat tersenyum sambil mengulurkan tangan, Miriam tidak menghiraukannya dan berbalik menuju tenda kapal."
  },
  AvgDialog_47167_Content_107 = {
    Text = "Mulai sekarang, panggil aku Pendeta Agung."
  },
  AvgDialog_47167_Content_108 = {
    Text = "Goliat menarik kembali tangannya, meraba tanda di lehernya. Dia tersenyum memandang lautan, taring barunya berkilau tajam di bawah sinar matahari."
  },
  AvgDialog_47167_Content_109 = {
    Text = "Senang bekerja sama, Tuan Pendeta Agung."
  },
  AvgDialog_47167_Content_11 = {
    Text = "Mendesah untuk cahaya kita, harapan kita."
  },
  AvgDialog_47167_Content_12 = {
    Text = "Karena takdir dibuang ke lautan, kami meraung, meratap, menumpahkan seluruh air mata…"
  },
  AvgDialog_47167_Content_13 = {
    Text = "Pasti halusinasi menjelang kematian, begitu pikir sang raksasa."
  },
  AvgDialog_47167_Content_14 = {
    Text = "Nyanyian kuno nan misterius masuk ke telinganya. Di balik kabut yang pekat, sosok seorang wanita muncul dalam pandangannya yang kabur."
  },
  AvgDialog_47167_Content_15 = {
    Text = "Ah, Miriam, itu dia, raksasa Filistin itu! Ada banyak legenda tentangnya di sepanjang pesisir..."
  },
  AvgDialog_47167_Content_16 = {
    Text = "Tapi sepertinya dia akan mati?"
  },
  AvgDialog_47167_Content_17 = {
    Text = "Dia tidak akan mati."
  },
  AvgDialog_47167_Content_18 = {
    Text = "Sentuhan lembut dan dingin terasa di leher yang dibelit ular hitam. Kedua mata sang raksasa yang telah keruh dan menghitam perlahan menjadi jernih kembali."
  },
  AvgDialog_47167_Content_19 = {
    Text = "Penyihir, itu penyihir itu!"
  },
  AvgDialog_47167_Content_20 = {
    Text = "Peristiwa yang terjadi di wilayah kekuasaan klan Orn telah tersebar ke seluruh perairan. Dia melangkah keluar dari kabut legenda dan berdiri di hadapan para fana."
  },
  AvgDialog_47167_Content_21 = {
    Text = "Hyena-hyena Filistin tersadar. Mereka mulai melarikan diri, atau menerjang ke perahu kecil ini untuk pertarungan mati-matian terakhir."
  },
  AvgDialog_47167_Content_22 = {
    Text = "Miriam memandang sang raksasa yang terpaku, tersenyum, lalu mengulurkan tangan menunjuk ke kejauhan. Dia menepuk Deborah dan memutar haluan perahu."
  },
  AvgDialog_47167_Content_23 = {
    Text = "Terhadap larian dan perlawanan para hyena, dia tidak memiliki minat sedikit pun."
  },
  AvgDialog_47167_Content_24 = {
    Text = "Ular-ular hitam merayap, memburu, menggigit, dan menelan. Di dalam kabut tebal di permukaan laut, tubuh-tubuh yang hancur semakin banyak bermunculan."
  },
  AvgDialog_47167_Content_25 = {
    Text = "Pembantaian sunyi itu segera berakhir, menyisakan perairan yang diwarnai darah merah, dan wajah sang raksasa yang menatap kosong."
  },
  AvgDialog_47167_Content_27 = {
    Text = "Miriam, karena sudah menemukan dia, kenapa kita pergi?"
  },
  AvgDialog_47167_Content_28 = {
    Text = "Mencari Tuanku adalah hal yang sakral. Beliau tidak akan ingin aku membicarakan hal seperti ini di tempat kotor seperti itu."
  },
  AvgDialog_47167_Content_29 = {
    Text = "Tapi kamu tidak mengatakan apa pun pada si besar itu... Apa dia akan datang mencarimu?"
  },
  AvgDialog_47167_Content_3 = {
    Text = "Sang raksasa mengerang tertahan, mencabut anak panah yang menancap di bahunya."
  },
  AvgDialog_47167_Content_30 = {
    Text = "Berdua, tolong tunggu sebentar!"
  },
  AvgDialog_47167_Content_31 = {
    Text = "Suara itu menembus kabut tebal. Deborah menjulurkan lidah ke arah Miriam, lalu perlahan menghentikan perahu."
  },
  AvgDialog_47167_Content_32 = {
    Text = "Tak lama kemudian, sebuah perahu kayu yang rusak berhenti di depan perahu mereka."
  },
  AvgDialog_47167_Content_33 = {
    Text = "Racun di tubuhmu belum sepenuhnya dibersihkan. Dengan kecepatan berlayar orang Filistin, kamu bisa beristirahat sejenak sebelum datang mencariku."
  },
  AvgDialog_47167_Content_34 = {
    Text = "Dibandingkan dengan sebuah transaksi yang sangat penting, luka kecil seperti ini tidak ada artinya."
  },
  AvgDialog_47167_Content_35 = {
    Text = "Aku tidak pernah bilang ingin melakukan transaksi apapun denganmu."
  },
  AvgDialog_47167_Content_36 = {
    Text = [[
Saya tidak ingin membuang waktu Anda, Yang Mulia Penyihir.
Saya tahu kabar tentang Lemuria, dan saya rasa, itulah alasan Anda menemukan saya.]]
  },
  AvgDialog_47167_Content_37 = {
    Text = "Kau tahu apa yang kuinginkan?"
  },
  AvgDialog_47167_Content_38 = {
    Text = "Apa yang Anda lakukan terhadap orang-orang Filistin di Manor Orne telah tersebar ke seluruh perairan. Sejujurnya, sebelum ini, saya tidak pernah percaya legenda-legenda itu."
  },
  AvgDialog_47167_Content_39 = {
    Text = "Tapi sekarang, Anda yang datang menemui saya. Anda melakukan ini, pasti ada alasannya."
  },
  AvgDialog_47167_Content_4 = {
    Text = "Darah beracun dari bahunya terciprat ke dek kapal, menampakkan warna hitam kotor di bawah sinar matahari."
  },
  AvgDialog_47167_Content_40 = {
    Text = "Menurut kabar, Anda tertarik pada patung-patung hitam itu. Patung-patung itu saya yang menemukannya, dan saya tahu apa yang mereka representasikan."
  },
  AvgDialog_47167_Content_41 = {
    Text = "Ceritakan padaku apa yang kau ketahui."
  },
  AvgDialog_47167_Content_42 = {
    Text = "Sebelum itu, Yang Mulia Penyihir, mungkin kita bisa mencapai sebuah kerja sama."
  },
  AvgDialog_47167_Content_43 = {
    Text = "Saya telah menyaksikan kekuatan besar Anda…… Saya rasa, Anda pasti punya cara untuk menganugerahkan kekuatan itu kepada saya?"
  },
  AvgDialog_47167_Content_44 = {
    Text = "Aku punya banyak cara untuk membuatmu bicara, orang Filistin. Menurutmu, kau punya hak untuk mengajukan transaksi?"
  },
  AvgDialog_47167_Content_45 = {
    Text = "Anda salah paham, Yang Mulia Penyihir…… Anda telah menyelamatkan nyawa saya, bahkan jika Anda tidak bersedia bertransaksi dengan saya, informasi itu tetap akan saya persembahkan sepenuhnya kepada Anda."
  },
  AvgDialog_47167_Content_46 = {
    Text = "Yang ingin saya transaksikan dengan Anda, bukanlah informasi ini."
  },
  AvgDialog_47167_Content_47 = {
    Text = "Selain itu, apa lagi yang bisa kau tawarkan?"
  },
  AvgDialog_47167_Content_48 = {
    Text = "Kesetiaan saya."
  },
  AvgDialog_47167_Content_49 = {
    Text = "Aku tidak tertarik pada kesetiaanmu, Goliat."
  },
  AvgDialog_47167_Content_5 = {
    Text = "Hebat juga kau, Eglun… Orang-orang Filistin… sekarang juga pakai benda-benda beracun begini…"
  },
  AvgDialog_47167_Content_50 = {
    Text = "Benarkah? Saya mendengar tentang bagaimana Anda mengendalikan keluarga Orne, sangat mengesankan…… Yang Mulia Penyihir, Anda sedang menyelesaikan suatu misi besar, dan membutuhkan orang, bukan?"
  },
  AvgDialog_47167_Content_51 = {
    Text = "Anda telah bersusah payah selama ini, berapa banyak orang yang bisa Anda perintah? Dalam proses Anda mencari apa yang Anda inginkan, siapa yang bisa membantu Anda mengatur semuanya?"
  },
  AvgDialog_47167_Content_52 = {
    Text = "Mohon maaf atas keberanian saya, Yang Mulia Penyihir, Anda adalah sosok yang kuat, tetapi hati manusia, kekuasaan, dan pembantaian dalam arti yang sesungguhnya, bukanlah keahlian Anda."
  },
  AvgDialog_47167_Content_53 = {
    Text = "Saya memang tidak tahu apa sebenarnya misi besar Anda. Tapi Anda pasti akan membutuhkan bantuan saya."
  },
  AvgDialog_47167_Content_54 = {
    Text = "Terimalah kesetiaan saya! Ini hanya akan menguntungkan Anda tanpa kerugian apapun."
  },
  AvgDialog_47167_Content_55 = {
    Text = "Miriam menatapnya dalam diam. Setelah beberapa saat, dia mengangguk."
  },
  AvgDialog_47167_Content_56 = {
    Text = "Persuasimu telah meyakinkanku, Goliath. Kau telah membuktikan kemampuanmu."
  },
  AvgDialog_47167_Content_57 = {
    Text = "Sekarang, lemparkan pisaumu ke dasar laut."
  },
  AvgDialog_47167_Content_58 = {
    Text = "Pisauku……"
  },
  AvgDialog_47167_Content_59 = {
    Text = "Goliath melirik bilah raksasa yang telah menemaninya selama bertahun-tahun, menggertakkan gigi, lalu melemparkannya ke laut."
  },
  AvgDialog_47167_Content_6 = {
    Text = "Pandangan sang raksasa mulai kabur, kepalanya mulai pusing. Dia tak sanggup bertahan lagi, dan ambruk dengan suara menggelegar."
  },
  AvgDialog_47167_Content_60 = {
    Text = "Kapal berguncang, seolah ada sesuatu yang mengaduk lautan di bawah mereka."
  },
  AvgDialog_47167_Content_61 = {
    Text = "Miriam mengulurkan tangannya. Bilah raksasa itu melompat kembali dari laut, memancarkan kilau gelap yang belum pernah terlihat sebelumnya."
  },
  AvgDialog_47167_Content_62 = {
    Text = "Bilah raksasa itu jatuh ke tangan Miriam, digenggam ringan oleh tangan rampingnya bagai sehelai bulu."
  },
  AvgDialog_47167_Content_63 = {
    Text = "Apakah kau takut rasa sakit?"
  },
  AvgDialog_47167_Content_64 = {
    Text = "Aku menikmati rasa sakit, Yang Mulia Penyihir."
  },
  AvgDialog_47167_Content_65 = {
    Text = "Goliath tersenyum dan berlutut di hadapan Miriam."
  },
  AvgDialog_47167_Content_66 = {
    Text = "Miriam mengangkat bilah raksasa itu dan meletakkannya di leher Goliath."
  },
  AvgDialog_47167_Content_67 = {
    Text = "Tuan Goliath!"
  },
  AvgDialog_47167_Content_68 = {Text = "Jleb——"},
  AvgDialog_47167_Content_69 = {
    Text = "Bilah raksasa itu menebas leher Goliath, dengan mudah memotongnya menjadi dua, darah menyembur deras."
  },
  AvgDialog_47167_Content_7 = {
    Text = "Goliath… sang raksasa Goliath, akhirnya tumbang!"
  },
  AvgDialog_47167_Content_70 = {
    Text = "Sebelum orang-orang di sekitar sempat bereaksi, cahaya ungu kehitaman berpendar samar di luka leher Goliath."
  },
  AvgDialog_47167_Content_71 = {
    Text = "Cahaya itu merambat, mengukir pola kuno nan rumit di atas kulit gelapnya."
  },
  AvgDialog_47167_Content_72 = {
    Text = "Arrghhh!!!——"
  },
  AvgDialog_47167_Content_73 = {
    Text = "Rasa sakit yang luar biasa menyerang Goliath. Rasa sakit itu bukan hanya berasal dari lukanya, melainkan membanjir dari seluruh tubuhnya."
  },
  AvgDialog_47167_Content_74 = {
    Text = "Butiran keringat mengalir dari dahi sang raksasa. Dia menggertakkan gigi, seluruh tubuhnya gemetar, melawan rasa sakit itu."
  },
  AvgDialog_47167_Content_75 = {
    Text = "Di tengah rasa sakit yang dahsyat itu, kedua telinga Goliath memanjang membentuk bilah tajam menyerupai sirip ikan, giginya berlapis-lapis dan sangat tajam, dan kedua matanya berubah merah darah."
  },
  AvgDialog_47167_Content_76 = {
    Text = "Tuan Goliath……Anda……Anda sekarang……"
  },
  AvgDialog_47167_Content_77 = {
    Text = "Ini adalah proses yang sangat panjang. Goliath merasa seolah-olah ia telah mengalami rasa sakit yang luar biasa selama setahun penuh. Dalam waktu yang panjang itu, ia mati karena rasa sakit, dan terlahir kembali dari rasa sakit."
  },
  AvgDialog_47167_Content_78 = {
    Text = "Ketika kesadaran Goliath kembali jernih, ia mendapati ritual telah lama berakhir. Ia tengah tertelungkup di atas kapal, keringat yang menetes akibat rasa sakit membasahi dek kapal."
  },
  AvgDialog_47167_Content_79 = {
    Text = "Ia menatap wajahnya yang terpantul di permukaan laut. Ciri-ciri manusia ikan tampak jelas pada tubuh raksasanya. Seekor hiu yang ganas, terpampang di hadapan semua orang."
  },
  AvgDialog_47167_Content_8 = {
    Text = "Kepalanya milikku, jangan ada yang berani merebutnya dariku!!!"
  },
  AvgDialog_47167_Content_80 = {
    Text = "Efek transformasi manusia ikan ditentukan oleh potensimu sendiri. Kau sangat berbakat, Goliath."
  },
  AvgDialog_47167_Content_81 = {
    Text = "Nikmatilah kekuatanmu."
  },
  AvgDialog_47167_Content_82 = {
    Text = "Kekuatan dahsyat yang belum pernah ia miliki sebelumnya muncul di dalam tubuh Goliath. Ia dengan mudah mengangkat pedang raksasa di sampingnya dan menebas ke arah permukaan air."
  },
  AvgDialog_47167_Content_83 = {
    Text = "BLARR——"
  },
  AvgDialog_47167_Content_84 = {
    Text = "Permukaan laut yang tenang terangkat menjadi gelombang besar, dua perahu kecil tersapu ombak dan bergoyang hebat."
  },
  AvgDialog_47167_Content_85 = {
    Text = "Hehehe……Hahahaha!!!"
  },
  AvgDialog_47167_Content_86 = {
    Text = "Di tengah guncangan hebat itu, Goliath tertawa terbahak-bahak. Ia berbalik menatap Miriam, cahaya merah di matanya berkilat tajam."
  },
  AvgDialog_47167_Content_87 = {
    Text = "Terima kasih, Nona Penyihir. Aku akan sangat menikmati kekuatan yang kau berikan padaku."
  },
  AvgDialog_47167_Content_88 = {
    Text = "Namun maafkan aku, aku tidak punya waktu untuk menyatakan kesetiaan padamu. Para pengkhianat dan musuh Filistin masih menungguku untuk membantai mereka."
  },
  AvgDialog_47167_Content_89 = {
    Text = "Jangan salahkan aku, salahkan dirimu sendiri yang tidak waspada. Kelak, aku akan mempersembahkan darah musuh sebagai sesaji untukmu!"
  },
  AvgDialog_47167_Content_9 = {
    Text = "Orang-orang Filistin yang semula gentar terhadap Goliath, kini mengerubunginya dengan membabi buta, bagai sekawanan hyena pemberani yang melihat bangkai singa."
  },
  AvgDialog_47167_Content_90 = {
    Text = "Goliath tiba-tiba mengayunkan pedangnya ke arah Miriam. Namun bilah tajam yang sangat perkasa itu, tepat saat hampir mencapai tubuh Miriam, tiba-tiba seolah membeku di tempat dan kehilangan seluruh kekuatannya."
  },
  AvgDialog_47167_Content_91 = {
    Text = "Ugh—AAAH!!"
  },
  AvgDialog_47167_Content_92 = {
    Text = "Bekas luka di leher Goliath berpendar ungu bagaikan lidah ular yang menyala-nyala. Ia jatuh tersungkur ke tanah dalam kesakitan. Rasa sakit yang menusuk tulang dan mengoyak daging yang baru saja ia alami kembali menyerangnya, dan kekuatan dalam tubuhnya lenyap seketika."
  },
  AvgDialog_47167_Content_93 = {
    Text = "Kau……melakukan……apa……"
  },
  AvgDialog_47167_Content_94 = {
    Text = "Aku adalah pendeta agung Lemuria. Memang aku tidak pandai dalam hal-hal yang kau sebutkan, tapi aku memahami apa itu sifat manusia, orang Filistin."
  },
  AvgDialog_47167_Content_95 = {
    Text = "Rasa sakit dan kekuatan, keduanya kuberikan padamu secara bersamaan. Di mana pun kau berada, sekuat apa pun dirimu, selama aku menginginkannya, aku bisa mencabut kekuatanmu dan mengembalikan rasa sakitmu."
  },
  AvgDialog_47167_Content_96 = {
    Text = "Kau menikmatinya, bukan?"
  },
  AvgDialog_47167_Content_97 = {
    Text = "Hebat sekali……Nyonya Penyihir……"
  },
  AvgDialog_47167_Content_98 = {
    Text = "Beritahu aku informasi yang kau ketahui, setelah itu, aku akan menganugerahimu kematian yang mudah."
  },
  AvgDialog_47167_Content_99 = {
    Text = "Ini hanyalah selingan kecil saja……Mengapa harus begitu, Nyonya Penyihir?"
  },
  AvgDialog_47168_Content_1 = {
    Text = "Perjamuan Darah"
  },
  AvgDialog_47168_Content_10 = {
    Text = "Tidak apa-apa, tidak apa-apa, ini hanya pertemuan keluarga biasa. Kondisi tubuhmu tidak masalah kan?"
  },
  AvgDialog_47168_Content_100 = {
    Text = "Hahaha, mana mungkin sesederhana itu?"
  },
  AvgDialog_47168_Content_101 = {
    Text = "Mantra, tubuh, dan juga..."
  },
  AvgDialog_47168_Content_102 = {
    Text = "Mata mabuknya yang sayu tiba-tiba terbuka lebar, dan dengan kejam dia merapalkan serangkaian mantra tanpa suara."
  },
  AvgDialog_47168_Content_103 = {Text = "Ah!——"},
  AvgDialog_47168_Content_104 = {
    Text = "Miriam jatuh berlutut ke tanah. Rasa sakit seperti tusukan jarum menyerang jiwanya, penderitaan yang luar biasa membuatnya tak mampu berdiri."
  },
  AvgDialog_47168_Content_105 = {
    Text = "@2, kau pikir aku tidak tahu apa yang ada di pikiranmu?"
  },
  AvgDialog_47168_Content_106 = {
    Text = "Memanggilku ayah, membantuku melakukan berbagai hal... Yang sebenarnya kau inginkan adalah hal lain, bukan?"
  },
  AvgDialog_47168_Content_107 = {
    Text = "Miriam, aku tidak tahu seperti apa kampung halamanmu, tapi jelas sekali, kalian sama sekali tidak mengerti apa itu perjuangan."
  },
  AvgDialog_47168_Content_108 = {
    Text = "Kalau aku orang bodoh, aku sudah ditenggelamkan di kandang kuda saat umur enam tahun, dan tidak mungkin bisa sampai di titik ini."
  },
  AvgDialog_47168_Content_109 = {
    Text = "Seperti tali tak kasat mata yang semakin kencang ditarik, rasa sakit di jiwa Miriam semakin kuat."
  },
  AvgDialog_47168_Content_11 = {
    Text = "Sudah hampir pulih sepenuhnya. Ah, Kakak juga sudah tiba?"
  },
  AvgDialog_47168_Content_110 = {
    Text = "Kau memang kuat, lalu apa? Kau hanyalah seekor anjing pemburu, apa yang kusuruh, itulah yang harus kau lakukan!"
  },
  AvgDialog_47168_Content_111 = {
    Text = "Sekarang, tujuanku sudah tercapai, untuk sementara aku tidak membutuhkanmu lagi. Membangkitkanmu kembali memang merepotkan, tapi menyimpan senjata yang punya pikiran sendiri jauh lebih merepotkan."
  },
  AvgDialog_47168_Content_112 = {
    Text = "Jadi, matilah sekali lagi. Tenang saja, saat aku membutuhkanmu nanti, aku akan membiarkanmu melihat matahari lagi..."
  },
  AvgDialog_47168_Content_113 = {
    Text = "Talis menatap Miriam dengan penuh kebencian dan mengucapkan serangkaian mantra. Tali tak kasat mata itu tiba-tiba mengencang, berubah menjadi jerat yang melilit leher Miriam."
  },
  AvgDialog_47168_Content_114 = {
    Text = "Tangan Talis yang mengendalikan jerat itu mencengkeram dengan kuat..."
  },
  AvgDialog_47168_Content_115 = {
    Text = "??! Ini... apa yang terjadi?!"
  },
  AvgDialog_47168_Content_116 = {
    Text = "Jerat itu masih ada, tapi Talis tidak bisa merasakan kendalinya atas tali tersebut. Tidak peduli bagaimana dia merapal mantra, tali itu hanya tergeletak di sana, tidak bergerak sama sekali."
  },
  AvgDialog_47168_Content_117 = {Text = "BYUR—"},
  AvgDialog_47168_Content_118 = {
    Text = "Aah!!——"
  },
  AvgDialog_47168_Content_119 = {
    Text = "Rasa sakit yang luar biasa menjalar dari tubuh Talis. Di dadanya muncul luka baru yang panjang dan lurus, seolah seseorang dengan khidmat menggoreskan belati di sana."
  },
  AvgDialog_47168_Content_12 = {
    Text = "Talis tersenyum dan memberi hormat kepadanya."
  },
  AvgDialog_47168_Content_120 = {
    Text = "Para tamu di aula segera terdiam, berdiri membeku di tempat. Para penjaga mengacungkan tombak dan mengelilingi Miriam, tetapi tidak berani mendekat lebih jauh."
  },
  AvgDialog_47168_Content_121 = {
    Text = "Ini... ini adalah...?"
  },
  AvgDialog_47168_Content_122 = {
    Text = "Di kampung halamanku, ini disebut Ritual Manusia Ikan."
  },
  AvgDialog_47168_Content_123 = {
    Text = "Dulu untuk menyelesaikannya, aku perlu menggunakan belati untuk membuka tubuh seseorang, lalu menuangkan darah dewa ke dalam tubuhnya. Tapi sekarang tidak perlu lagi."
  },
  AvgDialog_47168_Content_124 = {
    Text = "Cukup dengan meminum darahku, ditambah kekuatanku sebagai katalis, ritual ini bisa diselesaikan."
  },
  AvgDialog_47168_Content_125 = {
    Text = "Darahmu... dicampurkan ke dalam, ke dalam..."
  },
  AvgDialog_47168_Content_126 = {
    Text = "Di dalam anggur, benar. Di perjamuan ini, kalian sudah menikmatinya."
  },
  AvgDialog_47168_Content_127 = {
    Text = "Miriam berdiri, membersihkan debu dari tubuhnya."
  },
  AvgDialog_47168_Content_128 = {
    Text = "Kau... sudah merencanakannya sejak awal..."
  },
  AvgDialog_47168_Content_129 = {
    Text = "Orang-orang di dunia ini telah berubah. Iman, kasih keluarga, martabat... di mata kalian, semua itu tak bernilai. Aku sangat paham akan hal itu, Tharis."
  },
  AvgDialog_47168_Content_13 = {
    Text = "Aku juga baru saja tiba, sedang bersiap mempersembahkan hadiah untuk Ayah."
  },
  AvgDialog_47168_Content_130 = {
    Text = "Tapi tak apa, aku akan membawa dunia yang lebih baik. Membantumu menjadi kepala klan akan menjadikan Klan Orn sebagai pendukungku, turut serta bersamaku dalam misi agung nan suci ini."
  },
  AvgDialog_47168_Content_131 = {
    Text = "Kalian memiliki hati yang hina, seharusnya tak layak menjadi rakyat kerajaan ilahi. Tapi kalian telah menyelesaikan misi untuk membangkitkanku kembali. Ini, adalah hadiah yang kuberikan sebagai balasan untuk kalian."
  },
  AvgDialog_47168_Content_132 = {
    Text = "Kau bisa... bisa bernegosiasi denganku... kau tak perlu melakukan ini..."
  },
  AvgDialog_47168_Content_133 = {
    Text = "Anjing pemburu tidak punya hak untuk bernegosiasi. Maka, aku hanya bisa menjadi tuanmu. Sekarang, kurasa aku sudah memiliki hak itu."
  },
  AvgDialog_47168_Content_134 = {
    Text = "Aku ingin menghidupkan kembali seseorang. Katakan padaku, apa yang harus kulakukan."
  },
  AvgDialog_47168_Content_135 = {
    Text = "Kalau kukatakan, kau mau membiarkanku hidup?"
  },
  AvgDialog_47168_Content_136 = {
    Text = "Aah!!——"
  },
  AvgDialog_47168_Content_137 = {
    Text = "Miriam tidak berkata apa-apa. Sebuah luka yang sangat dalam muncul di tubuh Tharis, darah mengalir deras dari luka itu."
  },
  AvgDialog_47168_Content_138 = {
    Text = "Akan kukatakan! Akan kukatakan!"
  },
  AvgDialog_47168_Content_139 = {
    Text = "Di ruang kerjaku... di dalam meja tulis... ada sebuah buku yang mencatat semua hasil penelitianku."
  },
  AvgDialog_47168_Content_14 = {
    Text = "Baiklah, sekarang, kalian semua bersaudara sudah berkumpul lengkap."
  },
  AvgDialog_47168_Content_140 = {
    Text = "Semua yang berkaitan dengan golem, semuanya tertulis di sana!"
  },
  AvgDialog_47168_Content_141 = {
    Text = "Miriam meliriknya sekilas, lalu mengangguk."
  },
  AvgDialog_47168_Content_142 = {
    Text = "Aku tahu, kau berkata jujur."
  },
  AvgDialog_47168_Content_143 = {
    Text = "Kau benar, orang Lemuria tidak memiliki pertarungan seperti ini."
  },
  AvgDialog_47168_Content_144 = {
    Text = "Namun, setelah seseorang memiliki misi suci yang harus diselesaikan, mempelajari semua ini bukanlah hal yang sulit."
  },
  AvgDialog_47168_Content_145 = {
    Text = "Benar, benar... jadi sekarang bisa kau lepaskan aku?"
  },
  AvgDialog_47168_Content_146 = {Text = "Aaaahhh!!!"},
  AvgDialog_47168_Content_147 = {
    Text = "Luka-luka terus bermunculan di tubuhnya. Garis-garis darah dan daging saling bersilangan, membentuk sebuah pola dari peradaban kuno."
  },
  AvgDialog_47168_Content_148 = {
    Text = "Pada saat yang sama, garis-garis itu muncul di tubuh sebagian besar tamu dan penjaga. Jeritan bercampur darah, muncrat ke setiap sudut aula ini."
  },
  AvgDialog_47168_Content_149 = {
    Text = "Aula yang megah berubah menjadi neraka darah dan daging, dipenuhi ratapan keluarga Orne."
  },
  AvgDialog_47168_Content_15 = {
    Text = "Jamuan sedang disiapkan. Sebelum itu, ada beberapa hal penting yang perlu kusampaikan kepada kalian. Ini mengenai urusan setelah kepergianku."
  },
  AvgDialog_47168_Content_150 = {
    Text = "Wajah Thalis mulai berubah bentuk, sisik ikan muncul di kulitnya. Jeritan memilukan itu perlahan menjadi parau, tak jelas, membawa bau amis laut dalam."
  },
  AvgDialog_47168_Content_151 = {
    Text = "Tanah ini sudah membusuk… Aku akan menunjukkan kepada mereka, sebuah kerajaan dewa yang sempurna."
  },
  AvgDialog_47168_Content_152 = {
    Text = "Semua yang dikatakan Sang Raja itu benar. Kerajaan dewa akan segera turun… Aku sudah tahu ke mana harus mencari-Nya. Tunggulah sebentar lagi, segera, kita akan bersatu kembali."
  },
  AvgDialog_47168_Content_153 = {
    Text = "Rintihan kesakitan Thalis hampir sepenuhnya lenyap. Di bawah katalisasi kekuatan dahsyat Miriam, transformasi manusia-ikannya jauh lebih menyeluruh dibanding orang-orang Lemuria dahulu."
  },
  AvgDialog_47168_Content_154 = {
    Text = "Dia membungkuk, membelai wajah Thalis yang berubah bentuk dan lengannya yang dipenuhi sisik. Di tengah bau darah dan tangisan yang memenuhi ruangan, dia menangis, dan dia tersenyum."
  },
  AvgDialog_47168_Content_155 = {
    Text = "Lama tak jumpa, Ayah."
  },
  AvgDialog_47168_Content_156 = {
    Text = "Dia menyampaikan salam paling penuh kasih kepada manusia-ikan yang mengejang kesakitan itu."
  },
  AvgDialog_47168_Content_16 = {
    Text = "Ayah! Tolong jangan berkata seperti itu……"
  },
  AvgDialog_47168_Content_17 = {
    Text = "Putra kedua melangkah dua langkah ke depan, menopang lengan sang ayah. Orang tua itu menepuk pelan punggung tangannya."
  },
  AvgDialog_47168_Content_18 = {
    Text = "Dengarkan aku dulu. Kondisi tubuhku, aku sendiri sangat paham. Ada beberapa hal yang perlu diatur lebih awal, agar keluarga Orn dapat terus makmur dan sejahtera."
  },
  AvgDialog_47168_Content_19 = {
    Text = "Setelah perjamuan malam ini selesai, aku akan menyerahkan posisi kepala keluarga Orn kepada anak kedua. Aku sendiri berencana menikmati beberapa tahun kehidupan yang tenang."
  },
  AvgDialog_47168_Content_2 = {
    Text = "Salam hormat untuk Anda, Ayah, pemimpin abadi Keluarga Orn."
  },
  AvgDialog_47168_Content_20 = {
    Text = "Ayah, tapi... ini terlalu mendadak, aku belum siap..."
  },
  AvgDialog_47168_Content_21 = {
    Text = "Kau adalah pewaris terbaik keluarga Orn, memiliki garis keturunan paling mulia dan didikan paling baik. Ini adalah janji yang pernah kubuat kepada ibumu, dan aku pasti akan menepatinya."
  },
  AvgDialog_47168_Content_22 = {
    Text = "Tenang saja, aku sudah lebih dulu memberitahu teman-teman lama keluarga kita, dan saudara-saudaramu juga akan membantumu."
  },
  AvgDialog_47168_Content_23 = {
    Text = "Dia memandangi beberapa putranya yang lain."
  },
  AvgDialog_47168_Content_24 = {
    Text = "Wilayah kalian tidak akan berubah. Aku tahu hubungan kalian dengan anak kedua. Yang namanya kepala keluarga hanyalah sebuah gelar, kita semua adalah satu keluarga, harus bersatu."
  },
  AvgDialog_47168_Content_25 = {
    Text = "Sedangkan kau..."
  },
  AvgDialog_47168_Content_26 = {
    Text = "Dia mengangkat kepalanya, menatap Talis."
  },
  AvgDialog_47168_Content_27 = {
    Text = "Wilayahmu juga tidak akan berubah. Namun, akhir-akhir ini kau terlalu banyak memikirkan hal-hal yang membebanimu."
  },
  AvgDialog_47168_Content_28 = {
    Text = "Kau juga sudah berumur, serahkan komando pasukanmu kepada adikmu. Kurasa, kau juga seharusnya seperti aku, menjalani hari-hari yang lebih santai."
  },
  AvgDialog_47168_Content_3 = {
    Text = "Talis membungkuk memberi hormat, Miriam berdiri di belakangnya, menganggukkan kepala kepada orang tua di kursi utama."
  },
  AvgDialog_47168_Content_30 = {
    Text = "Ini adalah perintah yang tidak bisa ditolak, bukan?"
  },
  AvgDialog_47168_Content_31 = {
    Text = "Sang lelaki tua tampaknya sudah menduga jawaban ini, dan bersandar ke belakang di kursinya."
  },
  AvgDialog_47168_Content_32 = {
    Text = "Tiga hari yang lalu, aku sudah mengirim pasukan menuju markasmu."
  },
  AvgDialog_47168_Content_33 = {
    Text = "Ambisimu sudah lama kuketahui, tapi bagaimanapun kau tetap putraku. Aku akan memberimu kesempatan untuk memilih."
  },
  AvgDialog_47168_Content_34 = {
    Text = "Ini adalah keputusan yang kubuat demi masa depan keluarga Orn. Kuharap kau tidak menyalahkanku."
  },
  AvgDialog_47168_Content_35 = {
    Text = "...Bagaimana mungkin, Ayah? Aku justru harus berterima kasih kepadamu."
  },
  AvgDialog_47168_Content_36 = {
    Text = "Talis menunjukkan senyum penuh kelegaan."
  },
  AvgDialog_47168_Content_37 = {
    Text = "Dalam perjalanan ke sini, setiap kali memikirkan apa yang akan kulakukan, kau tidak tahu betapa tersiksa diriku..."
  },
  AvgDialog_47168_Content_38 = {
    Text = "Terima kasih kepadamu, dan juga kepada kalian, saudara-saudaraku. Sekarang, aku tidak memiliki beban apa pun lagi."
  },
  AvgDialog_47168_Content_39 = {
    Text = "Orang tua itu mengetuk kursinya, dan sepasukan besar penjaga berlari keluar dari balik tirai, mengepung Thalis dan Miriam."
  },
  AvgDialog_47168_Content_4 = {
    Text = "Orang tua itu melambaikan tangannya dengan tak sabar."
  },
  AvgDialog_47168_Content_40 = {
    Text = "Di sampingnya, putra kedua membelalakkan matanya, suaranya menjadi sedikit serak karena tegang."
  },
  AvgDialog_47168_Content_41 = {
    Text = "\"Ayah? Apa yang kau...\""
  },
  AvgDialog_47168_Content_42 = {
    Text = "Persiapanmu sungguh matang, Ayah. Menyuruhku menempatkan pasukan pribadiku di luar kota, lalu menyita senjataku, tak memberiku kesempatan sedikit pun."
  },
  AvgDialog_47168_Content_43 = {
    Text = "Anak haram yang dilahirkan oleh seorang pelayan, tidak berpendidikan, sepanjang hari meneliti alkimimu yang konyol itu, dan ambisimu yang konyol itu... Kau tidak punya perasaan apa pun terhadap keluarga, yang kau inginkan hanyalah kekuasaan."
  },
  AvgDialog_47168_Content_44 = {
    Text = "Menoleransimu hingga sekarang, aku sudah cukup memenuhi kewajibanku."
  },
  AvgDialog_47168_Content_45 = {
    Text = "Para prajurit mencabut pedang mereka dan berjalan menuju mereka. Thalis melambaikan tangannya, Miriam melangkah maju, kabut hitam mengumpul di belakangnya."
  },
  AvgDialog_47168_Content_46 = {
    Text = "Pelayan ini?..."
  },
  AvgDialog_47168_Content_47 = {
    Text = "Aku setuju, Ayah. Kau menoleransiku, terlalu banyak menoleransiku."
  },
  AvgDialog_47168_Content_48 = {
    Text = "Hasil dari alkimiku yang konyol ini, nikmatilah baik-baik, Ayah!"
  },
  AvgDialog_47168_Content_49 = {
    Text = "Para prajurit merasakan bahaya dan langsung menerjang ke arah mereka berdua."
  },
  AvgDialog_47168_Content_5 = {
    Text = "\"Kau ini sebagai kakak, harus memberi contoh yang baik bagi yang lain. Etika seorang bawahan saja tidak bisa kau ajarkan?\""
  },
  AvgDialog_47168_Content_50 = {
    Text = "BYURRR——"
  },
  AvgDialog_47168_Content_51 = {
    Text = "Seberkas kabut berbentuk ular menyapu wajahnya. Sesaat kemudian, tubuh tanpa kepala itu ambruk lemas ke tanah."
  },
  AvgDialog_47168_Content_52 = {
    Text = "I-ini adalah..."
  },
  AvgDialog_47168_Content_53 = {
    Text = "Prajurit lainnya belum sempat bereaksi, kabut hitam berbentuk ular sudah muncul di samping setiap orang."
  },
  AvgDialog_47168_Content_54 = {
    Text = "Kabut hitam melilit tubuh mereka, menjulurkan lidah ular, mengamati mereka."
  },
  AvgDialog_47168_Content_55 = {
    Text = "Tidak... jangan..."
  },
  AvgDialog_47168_Content_56 = {
    Text = "Beberapa gumpalan asap hitam tertinggal di udara. Mulut ular-ular hitam itu menggigit mangsa mereka, jeritan memilukan silih berganti memenuhi ruangan."
  },
  AvgDialog_47168_Content_57 = {
    Text = "Tak lama kemudian, jeritan mereda. Anggota keluarga Orn tergeletak di tanah, duduk di antara potongan mayat dan genangan darah, tenggorokan mereka tak mampu mengeluarkan suara apa pun selain rintihan pelan."
  },
  AvgDialog_47168_Content_58 = {
    Text = "Buka lebar matamu, lihatlah baik-baik, hasil dari alkimiku... \"putriku\"."
  },
  AvgDialog_47168_Content_59 = {
    Text = "Selama beberapa bulan ini, aku menggunakan segala cara untuk menyembunyikan keberadaannya, semuanya demi hari ini."
  },
  AvgDialog_47168_Content_6 = {
    Text = "Hah…… sudahlah, hal-hal seperti ini mungkin kau juga tidak paham."
  },
  AvgDialog_47168_Content_60 = {
    Text = "Ini hadiah besar yang kusiapkan untukmu. Suka tidak, orang tua?"
  },
  AvgDialog_47168_Content_61 = {
    Text = "Talis menatap pria tua yang gemetar hingga tak mampu berkata-kata, lalu menyunggingkan senyum penuh kepuasan."
  },
  AvgDialog_47168_Content_62 = {
    Text = "Kau benar sekali, hanya dengan perencanaan yang matang, keluarga Orn bisa makmur dan sejahtera."
  },
  AvgDialog_47168_Content_63 = {
    Text = "Tenang saja, Ayah. Aku selalu sangat mencintai keluarga Orn, juga mencintai anggota keluargaku…"
  },
  AvgDialog_47168_Content_64 = {
    Text = "Serahkan keluarga Orn padaku, akan kubuat keluarga ini — makmur dan sejahtera—"
  },
  AvgDialog_47168_Content_65 = {Text = "Jleb——"},
  AvgDialog_47168_Content_66 = {
    Text = "Pisau tajam menghujam dada kurus sang pria tua. Hal terakhir yang dilihatnya adalah senyum penuh kepuasan di wajah si anak haram."
  },
  AvgDialog_47168_Content_68 = {
    Text = "Hadirin sekalian."
  },
  AvgDialog_47168_Content_69 = {
    Text = "Brak brak brak——"
  },
  AvgDialog_47168_Content_7 = {
    Text = "……Teguran Ayah benar adanya."
  },
  AvgDialog_47168_Content_70 = {
    Text = "Sendok perak mengetuk gelas berkaki tinggi berukiran rumit, menghasilkan bunyi nyaring yang jernih."
  },
  AvgDialog_47168_Content_71 = {
    Text = "Aula perjamuan yang riuh mendadak sunyi. Semua mata tertuju pada kursi utama."
  },
  AvgDialog_47168_Content_72 = {
    Text = "Noda darah di kursi itu belum sepenuhnya mengering. Talis menghirup bau amis darah yang menguar di sekelilingnya, menatap puas semua pandangan yang tertuju padanya."
  },
  AvgDialog_47168_Content_73 = {
    Text = "Aku tahu, aku tahu, kalian semua datang untuk menghadiri pesta ulang tahun ayahku. Tapi aku tetap sangat berterima kasih atas kehadiran kalian."
  },
  AvgDialog_47168_Content_74 = {
    Text = "Sebuah pertunjukan yang luar biasa, tanpa penonton, akan sangat membosankan."
  },
  AvgDialog_47168_Content_75 = {
    Text = "Terima kasih banyak telah datang ke sini. Kini, keluarga Orn berkumpul bersama, untuk menyaksikan momen terpenting dalam hidupku."
  },
  AvgDialog_47168_Content_76 = {
    Text = "Terutama saudara-saudara tersayangku…"
  },
  AvgDialog_47168_Content_77 = {
    Text = "Dia berdiri, mengangkat gelas anggurnya dan mengayunkannya ke arah sudut ruangan."
  },
  AvgDialog_47168_Content_78 = {
    Text = "Di bawah pengawasan sepasukan prajurit bersenjata lengkap, adik-adik Talis duduk di sebuah meja, ketakutan dan membisu."
  },
  AvgDialog_47168_Content_79 = {
    Text = "Dengan bantuan mereka, hari ini, kalian akan menyaksikan sebuah momen yang agung."
  },
  AvgDialog_47168_Content_8 = {
    Text = "Terdengar langkah kaki tergesa-gesa dari luar pintu. Seorang pemuda yang wajahnya agak mirip dengan Talis muncul di aula."
  },
  AvgDialog_47168_Content_80 = {
    Text = "Sejarah keluarga Orn, hari ini, akan berubah sepenuhnya."
  },
  AvgDialog_47168_Content_81 = {
    Text = "Dia mencabut pedang dari pinggangnya dan menancapkannya di atas meja kayu."
  },
  AvgDialog_47168_Content_82 = {
    Text = "Aku, Talis, seorang anak liar, seorang anak haram. Mulai hari ini, akulah penguasa tunggal keluarga Orn!"
  },
  AvgDialog_47168_Content_83 = {
    Text = "Hadirin sekalian, kalian akan menjadi teman baru saya, Talis. Kita akan membentuk aliansi yang kuat, dan semua musuh akan dihancurkan oleh aliansi ini!"
  },
  AvgDialog_47168_Content_84 = {
    Text = "Para tamu mungkin pernah menjadi teman kepala klan sebelumnya, tapi sekarang tidak lagi. Teman mereka hanyalah sang pemenang."
  },
  AvgDialog_47168_Content_85 = {
    Text = "Di tengah pidato Talis yang penuh semangat, para tamu mengangkat gelas mereka."
  },
  AvgDialog_47168_Content_86 = {
    Text = "Untuk Talis!"
  },
  AvgDialog_47168_Content_87 = {
    Text = "Hahahaha... Untuk kalian, teman-temanku! Untuk aliansi agung kita! Untuk masa depan cerah Klan Orn!"
  },
  AvgDialog_47168_Content_88 = {Text = "Bersulang!"},
  AvgDialog_47168_Content_9 = {
    Text = "Ayah! Maaf, kemarin saya sakit, baru saja bangun……"
  },
  AvgDialog_47168_Content_90 = {
    Text = "Gelas-gelas berdentingan, suara riuh rendah memenuhi ruangan. Orang-orang berbaur dalam pesta ini dengan tulus maupun berpura-pura, menjadi bagian dari perjamuan ini."
  },
  AvgDialog_47168_Content_91 = {
    Text = "Miriam berdiri di samping sambil tersenyum, memandangi para tamu ini, memandangi hukum era baru ini."
  },
  AvgDialog_47168_Content_92 = {
    Text = "Talis duduk kembali di kursi utama dengan penuh kemabukan. Dia bersulang dengan setiap orang, minum dengan puas, menikmati momen paling membahagiakan dalam hidupnya."
  },
  AvgDialog_47168_Content_93 = {
    Text = "Miriam, bersulang juga untukmu... Kau adalah kebanggaanku!"
  },
  AvgDialog_47168_Content_94 = {
    Text = "Kau tidak tahu, betapa banyak hal yang telah kulakukan untuk menemukanmu, untuk membangunkanmu..."
  },
  AvgDialog_47168_Content_95 = {
    Text = "Yang Anda sebutkan sebelumnya, \"substansi perak\" itu..."
  },
  AvgDialog_47168_Content_96 = {
    Text = "Ya, benar, substansi perak itu... Emas? Permata? Hahaha, itu semua sampah!"
  },
  AvgDialog_47168_Content_97 = {
    Text = "Apa itu substansi perak, apa itu alkimia? Itu adalah kekuatan! Di hadapan kekuatan, apa artinya kekayaan? Itu hanyalah bonus dari kekuatan semata."
  },
  AvgDialog_47168_Content_98 = {
    Text = "Alkimia adalah kekuatan... Miriam, kaulah kekuatan itu! Ayo, bersulang!"
  },
  AvgDialog_47168_Content_99 = {
    Text = "Untuk menghidupkan kembali seseorang, apakah cukup hanya dengan substansi perak itu saja?"
  },
  AvgDialog_47169_Content_1 = {
    Text = "Kenalan Lama"
  },
  AvgDialog_47169_Content_10 = {
    Text = "Thales membangkitkanku kembali, dia pasti mengetahui sesuatu. Aku akan menemukan cara untuk membangkitkan-Mu darinya!"
  },
  AvgDialog_47169_Content_100 = {
    Text = "Dia akan membayar mahal atas keraguannya."
  },
  AvgDialog_47169_Content_101 = {
    Text = "Persediaan makanan dan air kita hanya cukup untuk dua atau tiga hari..."
  },
  AvgDialog_47169_Content_102 = {
    Text = "Meskipun tubuhmu kecil, tapi kalau sudah benar-benar tidak bisa bertahan hidup, aku tidak keberatan memakanmu."
  },
  AvgDialog_47169_Content_103 = {
    Text = "Tenang saja, sebagai rasa terima kasih atas kesetiaanmu, aku akan memberimu kematian yang cepat saat kau sedang bermimpi."
  },
  AvgDialog_47169_Content_104 = {
    Text = "Tuan Goliath, saya ini pengikut Anda, jangan menakut-nakuti saya..."
  },
  AvgDialog_47169_Content_105 = {
    Text = "Tapi Tuan, jangan terlalu pesimis begitu. Iglen menyuruh kita mencari penyihir yang membunuh anggota klan. Kalau kita berhasil menemukannya, mungkin kita masih bisa selamat!"
  },
  AvgDialog_47169_Content_106 = {
    Text = "Dasar si kecil yang naif. Iglen bukan orang yang sebaik itu. Mana ada penyihir, itu cuma omong kosong untuk membohongi anggota klan."
  },
  AvgDialog_47169_Content_107 = {
    Text = "Namun karena sudah sampai di titik ini, aku justru berharap, legenda itu benar adanya……"
  },
  AvgDialog_47169_Content_108 = {
    Text = "Sang raksasa membuka matanya, memandang hamparan lautan yang tak berujung."
  },
  AvgDialog_47169_Content_109 = {
    Text = "Jika orang seperti itu benar-benar ada, mungkin, aku benar-benar bisa melakukan sesuatu."
  },
  AvgDialog_47169_Content_11 = {
    Text = "\"Saat bintang-bintang kembali ke posisinya, Lemuria akan muncul kembali di dunia.\""
  },
  AvgDialog_47169_Content_12 = {
    Text = "Aku akan membawa-Mu kembali, membawa kembali Lemuria… Itulah firman yang Engkau sampaikan kepadaku. Tenanglah, Tuanku, aku pasti akan menyelesaikan misiku!"
  },
  AvgDialog_47169_Content_13 = {
    Text = "Ia menatap bayangan itu dengan penuh semangat."
  },
  AvgDialog_47169_Content_14 = {
    Text = "Bayangan itu tidak berkata apa-apa. Cahaya dan tentakel menutupi wajahnya, ekspresinya tak terlihat jelas. Ia menundukkan kepala dan menghela napas pelan."
  },
  AvgDialog_47169_Content_15 = {
    Text = "Helaan napas yang lembut itu bagaikan guntur yang menggelegar di ruang hampa, dan cahaya mulai berpencar melarikan diri ke segala arah."
  },
  AvgDialog_47169_Content_16 = {
    Text = "Tuanku? Tuanku?…"
  },
  AvgDialog_47169_Content_17 = {
    Text = "Tuanku!!…"
  },
  AvgDialog_47169_Content_18 = {
    Text = "Cahaya yang menyilaukan membuat mata Miriam terasa perih."
  },
  AvgDialog_47169_Content_19 = {
    Text = "Dalam pandangan yang perlahan berubah dari kabur menjadi jelas, sebuah patung terpajang dengan tenang di ambang jendela."
  },
  AvgDialog_47169_Content_2 = {
    Text = "Kesunyian mutlak. Kegelapan mutlak."
  },
  AvgDialog_47169_Content_20 = {
    Text = "Bahan batu gelap itu dipahat dengan sangat detail—sang Raja menopang dagunya, duduk miring di atas takhta yang dijalar tentakel, menatap Miriam dengan tenang."
  },
  AvgDialog_47169_Content_21 = {
    Text = "Sinar matahari terbit dari balik punggungnya, memantulkan sebuah siluet yang samar."
  },
  AvgDialog_47169_Content_22 = {
    Text = "Miriam tersenyum dan memberi hormat dengan khidmat kepada patung itu."
  },
  AvgDialog_47169_Content_23 = {
    Text = "Bersabarlah menunggu, Tuanku."
  },
  AvgDialog_47169_Content_24 = {
    Text = "Miriam, tadi aku dengar kamu mengigau lagi... Kamu baik-baik saja?"
  },
  AvgDialog_47169_Content_25 = {
    Text = "Mm... Aku tidak apa-apa, Deborah."
  },
  AvgDialog_47169_Content_26 = {
    Text = "Kenapa kamu selalu mengigau sih, aku sudah mendengarnya berkali-kali."
  },
  AvgDialog_47169_Content_27 = {
    Text = "Sang pelayan melangkah mendekat, dengan penuh perhatian menyentuh dahinya. Miriam menatapnya dengan pandangan kosong."
  },
  AvgDialog_47169_Content_28 = {
    Text = "Kenapa melihatku seperti itu?"
  },
  AvgDialog_47169_Content_29 = {
    Text = "Aku sedang berpikir, nama Deborah itu benar-benar indah."
  },
  AvgDialog_47169_Content_3 = {
    Text = "Ia berada di tengah kegelapan. Ke mana pun ia memandang, yang terlihat hanyalah kehampaan abadi."
  },
  AvgDialog_47169_Content_30 = {
    Text = "Hehe, iya kan? Anak seorang budak seharusnya tidak punya nama, tapi dulu Nyonya Besar menyukaiku dan memberiku nama ini. Aku juga sangat suka!"
  },
  AvgDialog_47169_Content_31 = {
    Text = "Wajah sahabat dalam ingatannya dan wajah sang pelayan melebur menjadi satu."
  },
  AvgDialog_47169_Content_32 = {
    Text = "Pendeta Deborah pernah membantu Miriam menjadi Pendeta Utama, dan pelayan Deborah, mungkin juga akan membantu Miriam menyambut datangnya Kerajaan Tuhan."
  },
  AvgDialog_47169_Content_33 = {
    Text = "Betapa indahnya kebetulan ini. Betapa sucinya takdir ini. Miriam menatapnya, tanpa sadar tersenyum."
  },
  AvgDialog_47169_Content_34 = {
    Text = "Kepalamu juga tidak panas... Kenapa rasanya kamu jadi linglung begitu..."
  },
  AvgDialog_47169_Content_35 = {
    Text = "Kalau kamu sampai kenapa-kenapa, Tuan Thales tidak akan memaafkanku."
  },
  AvgDialog_47169_Content_36 = {
    Text = "Meskipun sama-sama pelayan, tapi kamu ini jauh lebih berharga dibanding kami!"
  },
  AvgDialog_47169_Content_37 = {
    Text = "Kita tidak ada bedanya. Semua orang di dunia ini hanyalah hamba dari Sang Maha Agung."
  },
  AvgDialog_47169_Content_38 = {
    Text = "Aduh, kamu mulai bicara yang aneh-aneh lagi..."
  },
  AvgDialog_47169_Content_39 = {
    Text = "Deborah, selama ini, kamu sudah banyak mengobrol denganku. Tempat ini sangat asing bagiku, aku sangat bersyukur ada seseorang yang bisa diajak bicara."
  },
  AvgDialog_47169_Content_4 = {
    Text = "Miriam merasa dirinya telah menjadi bintang tanpa cahaya. Energi dalam tubuhnya mengalir menuju suatu tempat—sebuah perasaan yang begitu familiar dan membuatnya rindu."
  },
  AvgDialog_47169_Content_40 = {
    Text = "Kamu adalah sahabat terbaikku. Selalu begitu."
  },
  AvgDialog_47169_Content_41 = {
    Text = "Dia tersenyum, lalu menggenggam tangan sang pelayan."
  },
  AvgDialog_47169_Content_42 = {
    Text = "Ayo, Tuan Thales pasti sudah menunggu kita."
  },
  AvgDialog_47169_Content_44 = {
    Text = "Aku mau ceritakan sesuatu lagi, tapi kamu jangan bilang siapa-siapa ya!"
  },
  AvgDialog_47169_Content_45 = {
    Text = "Tenang, aku tidak akan mengatakannya."
  },
  AvgDialog_47169_Content_46 = {
    Text = "Tapi kamu tidak perlu menambahkan kalimat itu setiap kali mau menceritakan rahasia, ini sudah kelima kalinya kamu mengatakannya hari ini."
  },
  AvgDialog_47169_Content_47 = {
    Text = "Lagipula, menurutku kamu bilang kamu punya orang yang disukai itu bukan rahasia lagi. Semua orang di manor seharusnya sudah tahu siapa orangnya."
  },
  AvgDialog_47169_Content_48 = {
    Text = "Mana mungkin! Aku sudah menyembunyikannya dengan sangat baik... Jangan coba-coba memancingku untuk mengatakannya!"
  },
  AvgDialog_47169_Content_49 = {
    Text = "Aduh, pokoknya, ini juga hal yang penting... Menurutku Tuan Tallis sedang merencanakan sesuatu yang berbahaya."
  },
  AvgDialog_47169_Content_5 = {
    Text = "Ia menoleh ke arah sana. Cahaya bergerak deras, menyatu di kejauhan membentuk sebuah siluet yang samar."
  },
  AvgDialog_47169_Content_50 = {
    Text = "Tuan itu orangnya sangat licik, kamu harus berhati-hati!"
  },
  AvgDialog_47169_Content_51 = {Text = "Benarkah?"},
  AvgDialog_47169_Content_52 = {
    Text = "Miriamme berkata demikian, namun senyum di wajahnya tidak berubah sedikit pun, tanpa ekspresi terkejut sama sekali."
  },
  AvgDialog_47169_Content_53 = {
    Text = "Benar! Lihat saja dia, belakangan ini dia menyuruhmu membunuh banyak orang. Orang-orang itu adalah teman keluarga Orn, dan hubungan mereka dengan ayah Tuan Tallis sangat baik..."
  },
  AvgDialog_47169_Content_54 = {
    Text = "Setiap kali di permukaan dia bergaul sangat baik dengan orang-orang itu, seperti sahabat dekat, tapi begitu berbalik, dia langsung menyuruhmu membunuh mereka semua."
  },
  AvgDialog_47169_Content_55 = {
    Text = "Aku tahu kamu pasti tidak mau melakukan hal seperti itu, tapi mau bagaimana lagi, kamu harus menuruti perintah Tuan Tallis."
  },
  AvgDialog_47169_Content_56 = {
    Text = "Dunia ini tidak punya bencana alam, tapi hati manusia di dunia ini lebih mengerikan daripada bencana alam mana pun."
  },
  AvgDialog_47169_Content_57 = {
    Text = "Di dunia yang tidak sempurna seperti ini, pembunuhan akan selalu ada. Ini adalah sesuatu yang tidak bisa kita hindari."
  },
  AvgDialog_47169_Content_58 = {
    Text = "Haah, aku tidak mengerti... Berbagai kerajaan, berbagai keluarga, kenapa harus terus-menerus saling berebut seperti ini, padahal masih banyak orang yang hidupnya saja belum layak."
  },
  AvgDialog_47169_Content_59 = {
    Text = "Aku hanya berharap suatu hari nanti bisa menemukan tempat kecil yang damai, membangun sebuah rumah, dan bersama Nord..."
  },
  AvgDialog_47169_Content_6 = {
    Text = "Tuanku… apakah itu Anda?"
  },
  AvgDialog_47169_Content_60 = {Text = "Aduh!..."},
  AvgDialog_47169_Content_61 = {
    Text = "Menyadari dirinya keceplosan, wajah Debora langsung memerah, dan dia segera menutup mulutnya rapat-rapat."
  },
  AvgDialog_47169_Content_62 = {
    Text = "Tidak apa-apa, semua orang sudah tahu kamu menyukai kusir muda itu. Bahkan Tuan Tallis pernah membicarakannya denganku."
  },
  AvgDialog_47169_Content_63 = {
    Text = "Dia tersenyum sambil menepuk-nepuk wajah Debora yang sudah merah padam."
  },
  AvgDialog_47169_Content_64 = {
    Text = "Tenang saja, Debora. Suatu hari nanti, akan ada dunia yang sempurna."
  },
  AvgDialog_47169_Content_65 = {
    Text = "Benarkah? Bagaimana kamu bisa tahu?"
  },
  AvgDialog_47169_Content_66 = {
    Text = "Ini sungguhan, Deborah. Ada beberapa hal yang akan kuceritakan padamu perlahan. Aku akan menjadikanmu penganut pertama era baru ini, warga pertama kerajaan Tuhan."
  },
  AvgDialog_47169_Content_67 = {
    Text = "Aku akan membawa kerajaan Tuhan yang sempurna turun ke dunia... Ini adalah misiku."
  },
  AvgDialog_47169_Content_68 = {
    Text = "Menyuruhku menunggu di sini, sementara kau membawa Miriam mengobrol di jalan, senang sekali, ya?"
  },
  AvgDialog_47169_Content_69 = {
    Text = "Suara muram Talis memotong percakapan mereka berdua."
  },
  AvgDialog_47169_Content_7 = {
    Text = "Sosok bayangan yang terbentuk dari kumpulan cahaya itu duduk miring di atas takhta, satu tangan menopang dagu, menatap Miriam dalam diam."
  },
  AvgDialog_47169_Content_70 = {
    Text = "Aku menyuruhmu menjemput Nona Miriam, dan begini caramu bekerja?"
  },
  AvgDialog_47169_Content_71 = {
    Text = "Memanggil nama langsung, berjalan berdampingan... Prajurit, seret makhluk tak tahu aturan ini keluar dan bereskan dia."
  },
  AvgDialog_47169_Content_72 = {
    Text = "Tuan Talis! Ampuni aku... Aku... aku hanya..."
  },
  AvgDialog_47169_Content_73 = {
    Text = "Ini salahku, tidak ada hubungannya dengan Deborah. Mohon \"Ayah\" mengampuninya."
  },
  AvgDialog_47169_Content_74 = {
    Text = "Talis melirik Deborah sekilas dan melambaikan tangannya dengan tidak sabar."
  },
  AvgDialog_47169_Content_75 = {
    Text = "Karena Miriam memohon untukmu, kali ini kumaafkan. Kalau ada lain kali, siapa pun yang memohon tak akan berguna. Pergi sana."
  },
  AvgDialog_47169_Content_76 = {
    Text = "Putriku, kemarilah, ke sini..."
  },
  AvgDialog_47169_Content_77 = {
    Text = "Deborah memberi hormat kepadanya, diam-diam mengedipkan mata kepada Miriam, lalu dengan bijak pergi ke luar dan menutup pintu."
  },
  AvgDialog_47169_Content_78 = {
    Text = "Setelah mulai berbicara dengan Miriam, suara Talis langsung berubah menjadi penuh antusiasme."
  },
  AvgDialog_47169_Content_79 = {
    Text = "Beberapa bulan ini kau bekerja dengan sangat baik, luar biasa baik."
  },
  AvgDialog_47169_Content_8 = {
    Text = "Tuanku… aku mati dengan membawa keraguan terhadap-Mu. Itu adalah dosaku…"
  },
  AvgDialog_47169_Content_80 = {
    Text = "Dulu ketika mendalami alkimia, Ayah selalu bilang aku tidak serius. Tapi anak yang dilahirkan dari pelayan seperti ibuku, apa pun yang kulakukan, dia tidak akan pernah suka... Pelayan, huh."
  },
  AvgDialog_47169_Content_81 = {
    Text = "Urat-urat di tangannya yang menggenggam gagang pedang menonjol, lalu perlahan mengendur."
  },
  AvgDialog_47169_Content_82 = {
    Text = "Sekarang berbeda, Miriam. Dengan adanya dirimu, aku memiliki sepasukan tentara... tidak, lebih kuat dari tentara mana pun!"
  },
  AvgDialog_47169_Content_83 = {
    Text = "Kita juga bisa membuat lebih banyak golem sepertiku. Ritual semacam ini membutuhkan banyak kekuatan spiritual, aku bisa membantumu."
  },
  AvgDialog_47169_Content_84 = {
    Text = "Aku juga terus memikirkan hal ini. Tapi, substansi perak itu tidak bisa ditemukan di sembarang tempat."
  },
  AvgDialog_47169_Content_85 = {
    Text = "\"Substansi perak\"..."
  },
  AvgDialog_47169_Content_86 = {
    Text = "Nanti kalau ada waktu, aku akan menjelaskannya padamu. Sekarang tidak perlu terburu-buru soal ini. Selama ada kamu, itu sudah cukup untuk melakukan apa yang ingin kulakukan."
  },
  AvgDialog_47169_Content_87 = {
    Text = "Dia menarik napas dalam-dalam, menggenggam pisau di tangannya, dan memandang ke arah lautan di luar jendela."
  },
  AvgDialog_47169_Content_88 = {
    Text = "Tidak lama lagi, akan tiba ulang tahun ke tujuh puluh ayahku. Aku akan membawa hadiah dan pergi ke kota utama wilayah Klan Orn untuk merayakan hari ulang tahunnya."
  },
  AvgDialog_47169_Content_89 = {
    Text = "Persiapan kita sudah hampir selesai. Saat itu tiba, kita akan memberikannya sebuah hadiah yang sangat berharga. Benar kan, Miriam?"
  },
  AvgDialog_47169_Content_9 = {
    Text = "Aku tidak berani berharap pengampunan-Mu… Aku akan menanggung dosaku! Namun sebelum itu, aku akan menyelesaikan apa yang seharusnya kuselesaikan!"
  },
  AvgDialog_47169_Content_90 = {
    Text = "Benar, \"Ayah\". Bagi seluruh Klan Orn, ini akan menjadi hadiah yang tak ternilai harganya."
  },
  AvgDialog_47169_Content_92 = {
    Text = "Beberapa hari kemudian."
  },
  AvgDialog_47169_Content_93 = {
    Text = "Di atas laut, sebuah perahu kayu terapung-apung sendirian."
  },
  AvgDialog_47169_Content_94 = {
    Text = "Tuan Goliath, kapal-kapal anggota klan sudah tidak terlihat lagi."
  },
  AvgDialog_47169_Content_95 = {Text = "Bagus."},
  AvgDialog_47169_Content_96 = {
    Text = "Sang raksasa melempar pisaunya, bersandar pada tiang layar, dan memejamkan mata untuk beristirahat."
  },
  AvgDialog_47169_Content_97 = {
    Text = "Luka yang diderita saat bertarung melawan musuh, lalu tipu daya dan pengkhianatan anggota klan setelah dia terluka... Dia sendiri yang lengah, tidak bisa menyalahkan orang lain."
  },
  AvgDialog_47169_Content_98 = {
    Text = "Tapi bahkan bagi dirinya, dia merasa sedikit lelah."
  },
  AvgDialog_47169_Content_99 = {
    Text = "Heh, si pengecut Iglen. Ingin membunuhku, tapi takut merusak reputasinya sendiri. Mengusirku dari klan dengan dalih mencari penyihir, sungguh cara yang merepotkan."
  },
  AvgDialog_47170_Content_1 = {
    Text = "Patung Gelap"
  },
  AvgDialog_47170_Content_10 = {
    Text = "\"Bangunlah, kembalilah ke pelukan keluarga...\""
  },
  AvgDialog_47170_Content_100 = {
    Text = "Tak lama kemudian, orang-orang di dalam rumah tidak lagi bisa mendengar suara orang Filistin mana pun."
  },
  AvgDialog_47170_Content_101 = {
    Text = "Miriam seolah tidak melihat semua yang terjadi di sekelilingnya. Dia berjalan menuju sisa-sisa tubuh di dalam rumah, dan dengan khidmat mengambil patung gelap itu lalu memeriksanya dengan saksama."
  },
  AvgDialog_47170_Content_102 = {
    Text = "\"Ini patung Lemuria… Benar, ini patung Lemuria…\""
  },
  AvgDialog_47170_Content_103 = {
    Text = "\"Inilah Golem... Inilah kekuatan Golem!!\""
  },
  AvgDialog_47170_Content_104 = {Text = "@2@3......"},
  AvgDialog_47170_Content_105 = {
    Text = "Talis berdiri, wajahnya memerah karena kegembiraan. Ia merapalkan sebuah mantra dan melambaikan tangannya."
  },
  AvgDialog_47170_Content_106 = {
    Text = "Miriam merasakan kekuatan dahsyat yang mengalir dari ujung lain tautan itu. Kekuatan itu lenyap seketika sebelum sempat menyebabkan kerusakan nyata padanya."
  },
  AvgDialog_47170_Content_107 = {
    Text = "\"Golem, aku adalah penautmu. Akulah yang memberimu kehidupan. Mulai sekarang, aku adalah ayahmu.\""
  },
  AvgDialog_47170_Content_108 = {
    Text = "\"Kekuatanmu memang dahsyat, tapi kapan pun aku mau, aku bisa mengubahmu kembali menjadi mayat.\""
  },
  AvgDialog_47170_Content_109 = {
    Text = "\"Takdirmu telah terikat denganku. Jika aku mati, kau pun tak akan bisa terus ada.\""
  },
  AvgDialog_47170_Content_11 = {Text = "\"Ayah!...\""},
  AvgDialog_47170_Content_110 = {
    Text = "\"Jadi, jangan punya pikiran yang tidak seharusnya. Bantu aku sepenuh hati untuk menjadi kepala klan Orn.\""
  },
  AvgDialog_47170_Content_111 = {
    Text = "\"'Ayah'? 'Ayah'... Sang Raja benar, akulah orang yang menanggung takdir itu! Aku tahu apa yang harus kulakukan. Aku bisa melakukan banyak, banyak hal...\""
  },
  AvgDialog_47170_Content_112 = {
    Text = "\"Tenang saja, Ayah. Miriam pasti akan merebut kembali Kerajaan Suci bersamamu!\""
  },
  AvgDialog_47170_Content_113 = {
    Text = "Miriam menatap Talis dengan penuh semangat. Tatapan itu aneh—jelas-jelas memandang Talis, namun matanya seolah menembus dirinya, melihat sesuatu yang jauh di baliknya, sesuatu yang tak bisa ia pahami."
  },
  AvgDialog_47170_Content_114 = {
    Text = "Tatapan itu membara seperti matahari, namun juga gelap dan dingin seperti kedalaman lautan."
  },
  AvgDialog_47170_Content_115 = {
    Text = "\"Kerajaan Suci apa? Maksudmu tanah milik klan Orn? Kebiasaan yang aneh. Tapi bukan hal penting, terserah kau saja.\""
  },
  AvgDialog_47170_Content_116 = {
    Text = "\"Orang-orang Filistin itu masih berpesta di kastil dan tanah milikku. Miriam, bunuh mereka. Tunjukkan padaku, apa yang bisa kau lakukan.\""
  },
  AvgDialog_47170_Content_117 = {
    Text = "\"Sesuai kehendakmu, 'Ayah'.\""
  },
  AvgDialog_47170_Content_118 = {
    Text = "Miriam memberi hormat kepada Talis, lalu berjalan keluar."
  },
  AvgDialog_47170_Content_119 = {
    Text = "Darah menetes dari patung yang gelap. Di belakang Miriam, ular-ular hitam membentang bagai sayap, memperlihatkan taring-taring tajamnya."
  },
  AvgDialog_47170_Content_12 = {
    Text = "Ia membuka matanya dengan tiba-tiba dan melompat keluar dari permukaan laut."
  },
  AvgDialog_47170_Content_13 = {
    Text = "\"Dia bangun! Tuan Thales, dia sudah bangun!\""
  },
  AvgDialog_47170_Content_14 = {
    Text = "\"Ini di mana?...\""
  },
  AvgDialog_47170_Content_15 = {
    Text = "Miriam berada di sebuah aula besar yang luas dan mewah, berlutut di tengah lingkaran formasi ritual di lantai."
  },
  AvgDialog_47170_Content_16 = {
    Text = "Orang-orang di sekitarnya memiliki wajah yang belum pernah ia lihat, mengenakan pakaian yang belum pernah ia lihat, berteriak-teriak dengan penuh semangat."
  },
  AvgDialog_47170_Content_17 = {
    Text = "Seorang pria paruh baya berdiri di luar lingkaran formasi, menatapnya dengan lelah namun penuh kegembiraan."
  },
  AvgDialog_47170_Content_18 = {
    Text = "\"Berhasil... Aku berhasil memanggil golem! Seumur hidupku meneliti... akhirnya berhasil!!\""
  },
  AvgDialog_47170_Content_19 = {
    Text = "\"Raja... ke mana Raja pergi? Bukankah ini Lemuria?\""
  },
  AvgDialog_47170_Content_2 = {
    Text = "\"Atas nama @3, kupanggil engkau, anakku...\""
  },
  AvgDialog_47170_Content_20 = {
    Text = "Pelayan wanita yang tampak agak familiar itu menatapnya dengan bingung."
  },
  AvgDialog_47170_Content_21 = {
    Text = "\"Lemuria? Apa itu?\""
  },
  AvgDialog_47170_Content_22 = {
    Text = "\"Mungkin semacam peradaban kuno atau semacamnya… siapa yang tahu?\""
  },
  AvgDialog_47170_Content_23 = {
    Text = "\"Dilihat dari pakaiannya, dia pasti orang yang sangat penting… Usahaku pasti tidak sia-sia!\""
  },
  AvgDialog_47170_Content_24 = {
    Text = "Tatapannya pada Miriam menjadi semakin membara. Dia berjalan menuju Miriam dan mengulurkan tangannya ke depan dahinya."
  },
  AvgDialog_47170_Content_25 = {
    Text = "\"Aku adalah penghubungmu… Sekarang, buka matamu, dan lihatlah semua ini…\""
  },
  AvgDialog_47170_Content_26 = {
    Text = "Realitas menghilang sesaat. Informasi yang tak terhitung jumlahnya membanjiri pikiran Miriam, bagaikan lautan yang menenggelamkannya."
  },
  AvgDialog_47170_Content_27 = {
    Text = "Dia melihat tenggelamnya tanah kelahirannya, melihat perubahan permukaan laut, melihat pulau terpencil terhubung dengan daratan."
  },
  AvgDialog_47170_Content_28 = {
    Text = "Dia melihat, peradaban baru lahir, negara baru berdiri, penganut baru melantunkan doa baru, raja baru naik ke takhta baru."
  },
  AvgDialog_47170_Content_29 = {
    Text = "Dia melihat, waktu yang panjang berlalu dengan cepat dalam pergantian siang dan malam yang tak terhitung, Lemuria menghilang dari ingatan dunia ini, tanpa meninggalkan jejak apa pun."
  },
  AvgDialog_47170_Content_3 = {
    Text = "\"Biarkan pelukan keluarga menenangkan ragamu yang lelah, biarkan aroma tanah kelahiran menyembuhkan jiwamu yang mengembara.\""
  },
  AvgDialog_47170_Content_30 = {
    Text = "\"Aku tertidur selama… puluhan ribu tahun?\""
  },
  AvgDialog_47170_Content_31 = {
    Text = "\"Tertidur? Hahaha… Tidak, bukan begitu. Kau mati, pernah mati sekali.\""
  },
  AvgDialog_47170_Content_32 = {
    Text = "\"Akulah, akulah yang membangunkanmu, membuatmu hidup kembali!\""
  },
  AvgDialog_47170_Content_33 = {
    Text = "\"Cepat, ceritakan padaku, kemampuan apa yang kau miliki, apa yang bisa kau lakukan untukku?\""
  },
  AvgDialog_47170_Content_34 = {
    Text = "\"Lemuria… telah lenyap, tidak meninggalkan apa pun…\""
  },
  AvgDialog_47170_Content_35 = {
    Text = "Tanpa menghiraukan pertanyaan Talis yang mendesak, Miriam masih tenggelam dalam emosi kebingungan."
  },
  AvgDialog_47170_Content_36 = {
    Text = "Perubahan dunia, lenyapnya tanah kelahiran, waktu puluhan ribu tahun, semua ini membuat otaknya yang baru saja terbangun belum mampu berpikir."
  },
  AvgDialog_47170_Content_37 = {
    Text = "Sang pelayan menepuk dahinya sendiri dan menghela napas."
  },
  AvgDialog_47170_Content_38 = {
    Text = "\"Gawat, Tuan Talis… Sepertinya kepalanya tidak terlalu pintar?\""
  },
  AvgDialog_47170_Content_39 = {
    Text = "\"Tapi tidak apa-apa, setelah aku merawatnya dengan baik selama beberapa waktu, mungkin dia akan…\""
  },
  AvgDialog_47170_Content_4 = {Text = "\"Ayah?...\""},
  AvgDialog_47170_Content_40 = {
    Text = "\"Aah!——\""
  },
  AvgDialog_47170_Content_41 = {
    Text = "Suara gaduh terdengar samar-samar dari luar rumah."
  },
  AvgDialog_47170_Content_42 = {
    Text = "\"Suara apa itu?\""
  },
  AvgDialog_47170_Content_43 = {
    Text = "\"Orang Filistin... Orang Filistin menyerang! Semua prajurit sedang berjaga untuk ritual kebangkitan, garis pertahanan pantai telah ditembus!\""
  },
  AvgDialog_47170_Content_44 = {
    Text = "\"Peringatan! Orang Filistin... Aakh!...\""
  },
  AvgDialog_47170_Content_45 = {
    Text = "Seorang penjaga berlari sambil berteriak. Sebelum ia sempat menyelesaikan kata-katanya, sebuah tombak ikan raksasa melesat dari kejauhan, menembus jantungnya."
  },
  AvgDialog_47170_Content_46 = {
    Text = "Sekelompok prajurit asing berkulit gelap tanpa mengenakan baju besi, mulut mereka meneriakkan teriakan perang yang aneh, mengepung dari segala arah."
  },
  AvgDialog_47170_Content_47 = {
    Text = "\"Cepat... Golem! Cepat bantu aku bunuh mereka!\""
  },
  AvgDialog_47170_Content_48 = {Text = "\"...\""},
  AvgDialog_47170_Content_49 = {
    Text = "Miriam terduduk lemas di lantai, menundukkan kepalanya dengan tatapan kosong, tanpa menjawab."
  },
  AvgDialog_47170_Content_5 = {
    Text = "Kesadaran dan indra perlahan kembali ke tubuh Miriam. Di antara sadar dan tidak, ia merasakan dirinya diselimuti oleh air laut yang hangat."
  },
  AvgDialog_47170_Content_50 = {
    Text = "\"@2! Tidak kusangka yang terbangun adalah barang rongsokan...\""
  },
  AvgDialog_47170_Content_51 = {
    Text = "\"Jadi begini rupanya bagian dalam kastil Keluarga Orn. Benar-benar mewah.\""
  },
  AvgDialog_47170_Content_52 = {
    Text = "\"Kalian para barbar, ini adalah wilayah Keluarga Orn. Kalau tidak ingin dibantai oleh pasukan Keluarga Orn, lebih baik segera angkat kaki dari sini!\""
  },
  AvgDialog_47170_Content_53 = {Text = "Crassh—"},
  AvgDialog_47170_Content_54 = {Text = "\"AAKH!!\""},
  AvgDialog_47170_Content_55 = {
    Text = "Tombak ikan menembus bahunya, ia menjerit kesakitan, mencengkeram lukanya dengan penuh derita."
  },
  AvgDialog_47170_Content_56 = {
    Text = "\"Kalau kau menggonggong sekali lagi, berikutnya, yang ditusuk adalah bola matamu, lalu tenggorokanmu.\""
  },
  AvgDialog_47170_Content_57 = {
    Text = "Semua orang di dalam ruangan telah dikuasai, para penjaga di luar ruangan semuanya tewas oleh tombak ikan. Orang-orang Filistin berjalan mondar-mandir di dalam ruangan, memandangi semuanya dengan penuh keserakahan."
  },
  AvgDialog_47170_Content_58 = {
    Text = "\"Goliath dulu sering bilang, jangan pernah mengincar kastil Keluarga Orn, itu adalah hal yang sangat berbahaya. Tapi lihat sekarang? Kita berdiri di dalam kastil Keluarga Orn.\""
  },
  AvgDialog_47170_Content_59 = {
    Text = "\"Semua yang ada di sini, sebentar lagi akan menjadi milik kita!\""
  },
  AvgDialog_47170_Content_6 = {
    Text = "Suara-suara bergema samar-samar, siluet matahari menembus air laut, berpendar kabur di atasnya."
  },
  AvgDialog_47170_Content_60 = {
    Text = "Di sampingnya, seorang prajurit Filistin lainnya dengan tidak sabar mengangkat tinggi tombak ikannya."
  },
  AvgDialog_47170_Content_61 = {
    Text = "\"Benar, Goliath si pengecut itu! Kita seharusnya mendengarkan Igrun. Dialah yang seharusnya menggantikan Goliath dan menjadi pemimpin suku kita!\""
  },
  AvgDialog_47170_Content_62 = {
    Text = "\"Bos, kali ini kau berhasil merebut kastil keluarga Orne, setelah kembali nanti, Igrene pasti akan menghargaimu!\""
  },
  AvgDialog_47170_Content_63 = {
    Text = "\"Kalau bukan karena aku sedang melakukan ritual kebangkitan, kalian tidak akan berhasil menyerangku secara diam-diam... Dasar kalian orang-orang barbar yang licik!\""
  },
  AvgDialog_47170_Content_64 = {
    Text = "\"Golem! Akulah yang menyelamatkanmu! Kalau aku mati, kau juga tidak akan bisa hidup! Cepat... sadarlah, tolong aku!...\""
  },
  AvgDialog_47170_Content_65 = {
    Text = "\"Dia? Kau menaruh harapanmu pada seorang wanita? Hahahaha...\""
  },
  AvgDialog_47170_Content_66 = {
    Text = "Tawa ejekan orang Filistin bergema di seluruh ruangan. Kapten Filistin menggelengkan kepalanya, menjambak rambut Thalis, dan mengeluarkan belati dari tangannya."
  },
  AvgDialog_47170_Content_67 = {
    Text = "Dia berdiri menyamping menghadap Miriam. Di pinggangnya, sebuah patung kecil bergoyang-goyang. Mata Miriam tiba-tiba terbelalak."
  },
  AvgDialog_47170_Content_68 = {
    Text = "\"Patung itu... dari mana kau mendapatkannya?\""
  },
  AvgDialog_47170_Content_69 = {
    Text = "\"Wah... ternyata kau bisa bicara, kukira kau orang bodoh.\""
  },
  AvgDialog_47170_Content_7 = {
    Text = "Ini adalah tidur panjang tanpa mimpi. Miriam tidak tahu sudah berapa lama ia tertidur, mungkin seharian? Atau seminggu?"
  },
  AvgDialog_47170_Content_70 = {
    Text = "\"Patung itu, dari mana?\""
  },
  AvgDialog_47170_Content_71 = {
    Text = "Kapten Filistin menurunkan pisaunya. Dia menunduk menatap patung di pinggangnya."
  },
  AvgDialog_47170_Content_72 = {
    Text = "Patung itu terbuat dari bahan batu yang tampak sangat kuno dan kusam, menggambarkan sosok yang duduk di atas takhta. Beberapa tentakel aneh menjulur ke segala arah, menutupi wajahnya."
  },
  AvgDialog_47170_Content_73 = {
    Text = "\"Heh... yang ini? Goliath yang menemukannya. Karena keberanianku, dia menghadiahkannya padaku.\""
  },
  AvgDialog_47170_Content_74 = {
    Text = "\"Aku mempertaruhkan nyawaku untuknya, dan dia hanya memberiku benda seperti ini. Entah peninggalan peradaban bodoh mana, sebuah barang rongsokan yang tidak berguna.\""
  },
  AvgDialog_47170_Content_75 = {Text = "\"...Oh?\""},
  AvgDialog_47170_Content_76 = {
    Text = "Kapten Filistin masih berbicara, ketika tiba-tiba dia menyadari wanita di hadapannya telah berdiri."
  },
  AvgDialog_47170_Content_77 = {
    Text = "Dia mengamatinya dengan penuh minat — pakaiannya yang aneh, serta perhiasan-perhiasan di tubuhnya yang tampak misterius sekaligus mahal."
  },
  AvgDialog_47170_Content_78 = {
    Text = "\"Tadi kau bilang, patung ini, apa?\""
  },
  AvgDialog_47170_Content_79 = {
    Text = "\"Kubilang, barang rongsokan tidak berguna, sama sepertimu. Kenapa, telingamu sama seperti mulutmu, sama-sama tidak berfungsi?\""
  },
  AvgDialog_47170_Content_8 = {
    Text = "Kesadarannya perlahan menjadi jernih, menyatu kembali dengan tubuhnya. Samar-samar, sekelompok orang mengulurkan tangan ke arahnya dari permukaan laut."
  },
  AvgDialog_47170_Content_80 = {
    Text = "\"Kapten, jangan buang waktu bicara dengannya, satu tebasan saja... AAAAHHH!!!!...\""
  },
  AvgDialog_47170_Content_81 = {
    Text = "Kabut hitam itu muncul hampir dalam sekejap mata."
  },
  AvgDialog_47170_Content_82 = {
    Text = "Kabut hitam mengumpul membentuk beberapa ular raksasa, dan dengan rakus menerjang prajurit Filistin itu."
  },
  AvgDialog_47170_Content_83 = {
    Text = "Pisaunya meninggalkan leher Miriam, tangan yang memegang pisau itu digigit putus oleh ular hitam, darah menyembur, membasahi pakaian Miriam."
  },
  AvgDialog_47170_Content_84 = {
    Text = "Ular-ular hitam menerjang orang Filistin itu, dan sebelum ia sempat mengeluarkan lebih banyak jeritan, ia sudah ditelan habis."
  },
  AvgDialog_47170_Content_85 = {
    Text = "Di tanah hanya tersisa beberapa potongan tubuh dan genangan darah."
  },
  AvgDialog_47170_Content_86 = {
    Text = "\"I-ini… ini…\""
  },
  AvgDialog_47170_Content_87 = {
    Text = "Semua orang di ruangan itu terkejut oleh pemandangan mendadak ini, mulai meragukan penglihatan mereka sendiri."
  },
  AvgDialog_47170_Content_88 = {
    Text = "Miriam menunduk memandangi kedua tangannya. Senyuman yang semakin cerah perlahan muncul di wajahnya."
  },
  AvgDialog_47170_Content_89 = {
    Text = [[
Dia memandang ke arah kapten Filistin, tetapi bukan melihat dia, melainkan menatap patung yang ada di pinggangnya.
Air mata memenuhi kedua matanya.]]
  },
  AvgDialog_47170_Content_9 = {
    Text = "Ayah, ibu, adik perempuan, pendeta agung, raja, Deborah... Mereka semua mengulurkan tangan, mengundangnya."
  },
  AvgDialog_47170_Content_90 = {
    Text = "\"Rajaku, aku bertemu denganmu lagi… Ternyata, semua yang Engkau katakan itu benar…\""
  },
  AvgDialog_47170_Content_91 = {
    Text = "\"Aku benar-benar terlahir kembali! Aku memiliki kekuatan yang lebih dahsyat dari sebelumnya!\""
  },
  AvgDialog_47170_Content_92 = {
    Text = "\"Tuanku… aku memohon maaf atas keraguanku… Engkau benar-benar tidak membohongiku…\""
  },
  AvgDialog_47170_Content_93 = {Text = "\"Ahhh!!!\""},
  AvgDialog_47170_Content_94 = {
    Text = "Penyihir mengerikan ini sedang tenggelam dalam emosi yang rumit. Kehidupan merampok dan membunuh sejak kecil memberi orang Filistin naluri alami terhadap bahaya, dan dia tahu, ini adalah satu-satunya kesempatannya."
  },
  AvgDialog_47170_Content_95 = {
    Text = "Dia berteriak murka, menggenggam pisau, dan melesat menuju Miriam dengan kecepatan tertingginya."
  },
  AvgDialog_47170_Content_96 = {Text = "Crassh—"},
  AvgDialog_47170_Content_97 = {
    Text = "Ular hitam muncul dari ketiadaan dalam bentuk yang tak bisa dia pahami, menembus tubuhnya."
  },
  AvgDialog_47170_Content_98 = {
    Text = "Di dalam dan di luar rumah, sebagian orang Filistin mengangkat senjata dan menyerbu maju, sebagian melarikan diri ke segala arah, dan sebagian berlutut memohon ampun."
  },
  AvgDialog_47170_Content_99 = {
    Text = "Miriam tidak peduli dengan pilihan mereka yang berani maupun yang hina. Ular-ular hitam muncul dan menghilang dari ketiadaan, mempermainkan, menggigit, dan memburu nyawa-nyawa rendah ini."
  },
  AvgDialog_47171_Content_1 = {
    Text = "Kebajikan dari Kebohongan"
  },
  AvgDialog_47171_Content_10 = {
    Text = "Melihat ekspresi Deborah, para pengikut mengangguk dengan penuh pengertian."
  },
  AvgDialog_47171_Content_100 = {
    Text = "Apa yang dikatakan Guru... semua itu bohong, kan?"
  },
  AvgDialog_47171_Content_101 = {
    Text = "Selama bertahun-tahun ini, semua bencana alam telah lenyap, Lemuria sudah semakin dekat dengan Kerajaan Dewa... tinggal selangkah lagi, kita hanya tinggal selangkah lagi..."
  },
  AvgDialog_47171_Content_102 = {
    Text = "Anda pasti akan membawa Kerajaan Dewa, Tuanku! Saya adalah hamba Anda yang setia, saya akan selalu..."
  },
  AvgDialog_47171_Content_103 = {
    Text = "Kami telah mencari sekian lama... Dalam mimpi Kami, sosok Dewa sudah tidak ada lagi."
  },
  AvgDialog_47171_Content_104 = {
    Text = "Thulu mengalihkan pandangannya dari wajah Miriam."
  },
  AvgDialog_47171_Content_105 = {
    Text = "Peradaban kita, pada akhirnya akan musnah, tak terelakkan... Itulah kalimat terakhir yang Dia sampaikan kepadaku."
  },
  AvgDialog_47171_Content_106 = {
    Text = "Cuaca yang baik, kedamaian di seluruh penjuru negeri, itulah senja terakhir Lemuria."
  },
  AvgDialog_47171_Content_107 = {
    Text = "Menghadapi malapetaka ini, adalah hukuman yang harus ditanggung oleh Raja dan Pendeta Agung."
  },
  AvgDialog_47171_Content_108 = {
    Text = "Jadi... jadi maksud Anda... semua doa dan harapan rakyat Lemuria, semuanya hanyalah kebohongan..."
  },
  AvgDialog_47171_Content_109 = {
    Text = "Semua orang, dari lahir hingga mati, hidup dalam sebuah kebohongan, benarkah, Tuanku?"
  },
  AvgDialog_47171_Content_11 = {
    Text = "Mereka menutup mulut rapat-rapat dan berlutut di hadapan Miriam. Tatapan penuh hormat dan penuh harap, tertuju padanya tanpa bergeming."
  },
  AvgDialog_47171_Content_110 = {
    Text = "Gurumu, sudah memberitahumu."
  },
  AvgDialog_47171_Content_111 = {
    Text = "Saya ingin mendengarnya langsung dari mulut Anda, Tuanku..."
  },
  AvgDialog_47171_Content_112 = {
    Text = "Tolong katakan langsung kepada saya, bahwa doa-doa kami tidak berarti apa-apa. Para perintis ini, mengorbankan segalanya, kecerdasan, emosi, martabat, berdesakan di kolam ini, yang mereka tunggu hanyalah sebuah kebohongan yang jauh..."
  },
  AvgDialog_47171_Content_113 = {
    Text = "Tolong katakan langsung kepada saya, Kerajaan Dewa... tidak akan pernah datang..."
  },
  AvgDialog_47171_Content_114 = {
    Text = "Ini adalah keruntuhan yang sunyi. Miryam tidak menangis, tidak jatuh ke dalam kegilaan. Dia menatap Thulu, dan dengan lemah mengucapkan semua kata-katanya."
  },
  AvgDialog_47171_Content_115 = {
    Text = "Matanya tak berkedip, seperti manusia-ikan di sekelilingnya, tak lagi berpikir, tanpa emosi, hanya menatap Thulu dengan diam dan sungguh-sungguh."
  },
  AvgDialog_47171_Content_116 = {
    Text = "Seperti api yang akan padam, menantikan fajar yang jauh."
  },
  AvgDialog_47171_Content_117 = {
    Text = "Thulu memejamkan mata, menarik napas dalam-dalam. Di saat itu, tatapan-tatapan itu mengingatkannya pada banyak hal."
  },
  AvgDialog_47171_Content_118 = {
    Text = "Mungkin, dia teringat akan orang-orang yang hidup turun-temurun dalam kebohongan."
  },
  AvgDialog_47171_Content_119 = {
    Text = "Mungkin, dia teringat akan para penganut yang mempersembahkan kecerdasan, emosi, dan martabat mereka, teringat akan jiwa-jiwa yang telah diubah dan dibelokkan."
  },
  AvgDialog_47171_Content_12 = {
    Text = "Wahai pengikut setia Tuhan kami, Tuhan kami akan senantiasa memberkatimu."
  },
  AvgDialog_47171_Content_120 = {
    Text = "Mungkin, dia hanya teringat bahwa sebelum kebohongan tentang tidur panjang ini, dia pun pernah seperti rakyat Lemuria, percaya bahwa dirinya bisa membawa fajar baru bagi tanah ini."
  },
  AvgDialog_47171_Content_121 = {
    Text = "Memberikan harapan kepada rakyat, itulah tugas seorang raja, itulah satu-satunya makna dari kebohongan ini. Jika demikian, biarlah kebohongan ini terus berlanjut."
  },
  AvgDialog_47171_Content_122 = {
    Text = "Thulu membuka matanya, dan menghampiri Miryam."
  },
  AvgDialog_47171_Content_123 = {
    Text = "Sudah lama aku tidak bertemu dengan Dewa... Tapi aku tahu, Dia masih ada di sana, di kedalaman mimpi."
  },
  AvgDialog_47171_Content_124 = {
    Text = "Kerajaan Dewa, masih ada."
  },
  AvgDialog_47171_Content_125 = {
    Text = "Miriam tiba-tiba mengangkat kepalanya."
  },
  AvgDialog_47171_Content_126 = {
    Text = "Ta-tapi Guru berkata……"
  },
  AvgDialog_47171_Content_127 = {
    Text = "Hingga Lemuria hancur, Kerajaan Dewa tetap tidak akan turun. Semua orang akan mati dalam malapetaka ini."
  },
  AvgDialog_47171_Content_128 = {
    Text = "Tuanku, jadi maksud Anda……"
  },
  AvgDialog_47171_Content_129 = {
    Text = "……Namun, bintang-bintang pernah menunjukkan kepada-ku, Lemuria akan terlahir kembali."
  },
  AvgDialog_47171_Content_13 = {
    Text = "Ular hitam menari di belakang Miriam. Tangannya dengan lembut menyentuh dahi setiap pengikut."
  },
  AvgDialog_47171_Content_130 = {
    Text = "Dia tidak memandang Miriam, berbalik dan berjalan menuju takhta."
  },
  AvgDialog_47171_Content_131 = {
    Text = "Saat bintang-bintang kembali ke posisinya, Lemuria akan muncul kembali di dunia."
  },
  AvgDialog_47171_Content_132 = {
    Text = "Yang menyelamatkan Lemuria bukanlah aku. Yang menyelamatkan Lemuria adalah kamu."
  },
  AvgDialog_47171_Content_133 = {Text = "?!!"},
  AvgDialog_47171_Content_134 = {
    Text = "Miriam, Pendeta Agung Lemuria. Kau akan terlahir kembali di dunia. Kau akan membawa kembali aku, membawa kembali Lemuria."
  },
  AvgDialog_47171_Content_135 = {
    Text = "Saat itu tiba, aku akan membuat Kerajaan Dewa abadi di Lemuria."
  },
  AvgDialog_47171_Content_136 = {
    Text = "Tulu duduk di atas takhta. Dia menopang dagunya, bersandar dengan lelah."
  },
  AvgDialog_47171_Content_137 = {
    Text = "Dia tidak memandang ekspresi terkejut dan penuh pergolakan di wajah Miriam. Dia tahu, Miriam tidak sepenuhnya percaya pada kata-kata itu. Tidak ada seorang pun yang benar-benar bisa mempercayai kata-kata itu."
  },
  AvgDialog_47171_Content_138 = {
    Text = "Kebohongan dan kebenaran, mana yang lebih kejam? Dia merenungkannya cukup lama, namun tetap tidak menemukan jawaban."
  },
  AvgDialog_47171_Content_139 = {
    Text = "Jika pilihannya adalah sebuah kesalahan, maka biarlah kesalahan itu menjadi akhirnya."
  },
  AvgDialog_47171_Content_14 = {
    Text = "Terpujilah Tuhan kami... Terpujilah Pendeta Agung!"
  },
  AvgDialog_47171_Content_140 = {
    Text = "Tapi……Tuanku, aku……apa yang harus aku lakukan?"
  },
  AvgDialog_47171_Content_141 = {
    Text = "Menunggu. Sebelum saat itu tiba, berjalanlah bersama Lemuria menuju akhir."
  },
  AvgDialog_47171_Content_142 = {
    Text = "Lemuria, masih ada……"
  },
  AvgDialog_47171_Content_143 = {
    Text = "Tiga hari. Tiga hari lagi, Lemuria akan menemui ajalnya."
  },
  AvgDialog_47171_Content_144 = {
    Text = "Apa yang Anda rencanakan……Tuanku?"
  },
  AvgDialog_47171_Content_145 = {
    Text = "Sebuah upacara persembahan yang megah, biarkan para pengikut terus berdoa……Serukan nama-ku, dan aku akan membuat seluruh penduduk Lemuria tertidur lelap."
  },
  AvgDialog_47171_Content_146 = {
    Text = "Aku akan memberikan mereka mimpi yang paling indah."
  },
  AvgDialog_47171_Content_147 = {
    Text = "Pendeta Agung berkata, dia tidak mau tertidur. Dia ingin menyaksikan dengan mata kepalanya sendiri saat Lemuria tenggelam ke dasar laut."
  },
  AvgDialog_47171_Content_148 = {
    Text = "Bagaimana denganmu?"
  },
  AvgDialog_47171_Content_15 = {
    Text = "Di bawah arahan beberapa pengawal, para pengikut yang telah menerima berkat dari Pendeta Agung pergi dengan penuh suka cita."
  },
  AvgDialog_47171_Content_150 = {
    Text = "……Aku bersedia menyambut akhir dalam keadaan sadar, Tuanku."
  },
  AvgDialog_47171_Content_151 = {
    Text = "Miriam pergi. Thulu bersandar lelah di atas takhta, memandangi ruangan yang kosong, memandangi para manusia ikan yang berserakan, memandangi punggung Miriam yang ragu-ragu melangkah pergi."
  },
  AvgDialog_47171_Content_152 = {
    Text = [[
Percakapan antara Raja dan Pendeta Agung Lemuria telah berakhir.
Dalam puluhan ribu tahun siang dan malam yang panjang di masa depan, ini akan menjadi satu-satunya pertemuan mereka.]]
  },
  AvgDialog_47171_Content_16 = {
    Text = "Memandangi punggung mereka yang menjauh, Deborah menghela napas dengan puas."
  },
  AvgDialog_47171_Content_17 = {
    Text = "Sejak kau menjadi Pendeta Agung, Lemuria sudah lama tidak mengalami bencana alam."
  },
  AvgDialog_47171_Content_18 = {
    Text = "Kau mengelola tempat ini dengan sangat baik. Lihatlah para pengikut ini, mereka begitu mengagumimu!"
  },
  AvgDialog_47171_Content_19 = {
    Text = "Aku hanyalah penyampai pesan Tuanku. Yang seharusnya diagungkan oleh rakyat Lemuria, hanyalah Tuanku seorang."
  },
  AvgDialog_47171_Content_2 = {
    Text = "Beberapa tahun kemudian."
  },
  AvgDialog_47171_Content_20 = {
    Text = "Sebelum Tuanku naik takhta, aku tidak pernah melihat Lemuria yang seperti ini. Aku tidak pernah membayangkan, bahwa benar-benar akan ada Lemuria yang seperti ini……"
  },
  AvgDialog_47171_Content_21 = {
    Text = "Miryam dan Deborah berdiri bersama di atas batu karang di tepi pantai, memandangi ladang-ladang yang penuh kehidupan, kota yang semakin megah, dan kuil kuno nan agung yang sangat mereka kenal."
  },
  AvgDialog_47171_Content_22 = {
    Text = "Suaranya lembut dan tenang, tetapi matanya berkilau dengan warna yang jauh lebih fanatik daripada para pengikut biasa."
  },
  AvgDialog_47171_Content_23 = {
    Text = "Berdoalah untuk Raja kita, Deborah…… Kita semakin dekat dengan Kerajaan Ilahi."
  },
  AvgDialog_47171_Content_25 = {
    Text = "\"Di jurang kelam yang jauh, jiwa agung purba tertidur lelap...\""
  },
  AvgDialog_47171_Content_26 = {
    Text = "\"...Kehendak-Nya terjalin bagai jaring bintang, Dia menanti engkau bermimpi dalam kekosongan abadi...\""
  },
  AvgDialog_47171_Content_27 = {
    Text = "Di posisi terdekat dengan patung, Miryam berlutut seorang diri dengan penuh khidmat. Doa-doa mengalir lancar dari mulutnya, bagaikan mata air yang memancar dari celah pegunungan."
  },
  AvgDialog_47171_Content_28 = {
    Text = "Air mata air itu berputar dan mengalir di dalam ruangan ini, menjadi tirai kegelapan yang menenggelamkannya."
  },
  AvgDialog_47171_Content_29 = {
    Text = "Kehampaan abadi dari dimensi spiritual turun di sekelilingnya. Ia tidak merasakan ketidaknyamanan apa pun, hanya kehangatan yang tak terhingga."
  },
  AvgDialog_47171_Content_3 = {
    Text = "Hujan gerimis baru saja reda, dan langit dengan cepat menjadi cerah. Sinar matahari turun dengan lembut, menyinari beberapa anak Lemuria yang sedang bermain di tepi pantai."
  },
  AvgDialog_47171_Content_30 = {
    Text = "Titik-titik cahaya menyala dalam kegelapan, benang-benang samar tertarik keluar dari titik-titik cahaya itu."
  },
  AvgDialog_47171_Content_31 = {
    Text = "Di tempat cahaya-cahaya itu berkumpul, sebuah siluet besar yang bersinar terang bagaikan bulan di langit malam, menerangi sebuah malam putih abadi di ruang hampa ini."
  },
  AvgDialog_47171_Content_32 = {
    Text = "Tuanku, Raja Lemuria yang tertidur…… Mohon maafkan hamba, yang telah memasuki mimpi agung-Mu."
  },
  AvgDialog_47171_Content_33 = {
    Text = "Wahyu-Mu telah menyelamatkan umat, segala bencana alam mundur demi-Mu. Hamba menyampaikan penghormatan dari seluruh umat Lemuria kepada-Mu……"
  },
  AvgDialog_47171_Content_34 = {
    Text = "Engkau adalah pelaksana kehendak para dewa, sang juru selamat Lemuria. Kami rela mempersembahkan segalanya, untuk membantu-Mu menerima wahyu dan menyambut datangnya Kerajaan Ilahi."
  },
  AvgDialog_47171_Content_35 = {
    Text = "Berikanlah hamba petunjuk. Jawablah pengikut-Mu yang paling setia……"
  },
  AvgDialog_47171_Content_36 = {
    Text = "Kesadarannya melayang ke depan, menuju patung yang terbentuk dari kumpulan cahaya bintang. Ia mengulurkan tangan, dengan khidmat menyentuh berkas-berkas cahaya itu……"
  },
  AvgDialog_47171_Content_37 = {
    Text = "BRAKK!——"
  },
  AvgDialog_47171_Content_38 = {
    Text = "Sebelum ia sempat menyentuh berkas cahaya itu, patung tersebut sudah hancur berkeping-keping dengan gemuruh. Berkas-berkas cahaya itu saling bertabrakan, berbalik, dan bertebaran ke segala arah."
  },
  AvgDialog_47171_Content_39 = {
    Text = "Miryam terdorong ke belakang oleh arus udara yang dahsyat dan terjatuh ke tanah."
  },
  AvgDialog_47171_Content_4 = {
    Text = "Beberapa penduduk kota duduk di tangga batu di tepi pantai, menyanyikan sebuah himne kuno yang riang."
  },
  AvgDialog_47171_Content_40 = {
    Text = "Kegelapan lenyap. Miryam berdiri dengan linglung. Di tengah debu dan asap, sebuah batu besar jatuh entah dari mana, menembus dinding kuil, dan menghantam patung sang Raja dengan keras."
  },
  AvgDialog_47171_Content_41 = {
    Text = "Tidak! Tuanku! I-ini adalah……"
  },
  AvgDialog_47171_Content_42 = {
    Text = "Tentakel dan kepala hancur berkeping-keping berserakan di lantai, hanya menyisakan setengah tubuh yang masih duduk tegak di atas takhta. Tetesan hujan dari luar merembes masuk melalui lubang di dinding, jatuh menimpa reruntuhan yang memenuhi lantai."
  },
  AvgDialog_47171_Content_43 = {
    Text = "Miriam panik dan berlutut di hadapan sisa-sisa patung yang masih tersisa."
  },
  AvgDialog_47171_Content_44 = {
    Text = "A-apakah aku melakukan kesalahan? Tolong beritahu aku..."
  },
  AvgDialog_47171_Content_45 = {
    Text = "Uhuk uhuk…"
  },
  AvgDialog_47171_Content_46 = {
    Text = "Suara batuk seorang lelaki tua terdengar di ruang doa. Beberapa tahun sudah cukup panjang bagi seorang yang sudah lanjut usia. Dengan susah payah ia mengibas-ngibaskan tangan mengusir debu yang menyesakkan, lalu perlahan melangkah maju."
  },
  AvgDialog_47171_Content_47 = {
    Text = "Guru? Mengapa Anda datang sendirian..."
  },
  AvgDialog_47171_Content_48 = {
    Text = "Ingin berjalan-jalan sendiri. Sudah lama tidak keluar untuk berjalan santai."
  },
  AvgDialog_47171_Content_49 = {
    Text = "Ia berjalan menuju patung yang kini tinggal reruntuhan, lalu memberi hormat dengan perlahan dan penuh khidmat."
  },
  AvgDialog_47171_Content_5 = {
    Text = "Nyanyian itu, diiringi kicauan camar laut, sampai ke telinga Miriam."
  },
  AvgDialog_47171_Content_50 = {
    Text = "Miriam melihat matanya—kedua mata itu masih tajam, namun di dalamnya terdapat emosi yang tak mampu ia pahami."
  },
  AvgDialog_47171_Content_51 = {
    Text = "Itu adalah emosi yang sangat kompleks, bagaikan seorang bayi yang baru lahir menghadapi dunia asing untuk pertama kalinya, bagaikan seorang pengkhianat menghadapi tanah air yang sangat dicintainya."
  },
  AvgDialog_47171_Content_52 = {
    Text = "Guru... apa yang terjadi? Pertanda buruk ini... haruskah kita mengadakan upacara persembahan yang agung?"
  },
  AvgDialog_47171_Content_53 = {
    Text = "Miriam, beri hormat kepada Sang Raja, dan dengarkanlah titah-Nya."
  },
  AvgDialog_47171_Content_54 = {Text = "Baik!"},
  AvgDialog_47171_Content_55 = {
    Text = "Ia menundukkan badan dengan penuh hormat. Setelah selesai memberi hormat kepada patung, ia menatap gurunya dengan penuh harap, menantikan."
  },
  AvgDialog_47171_Content_56 = {
    Text = "\"Dalam mimpi Sang Raja, para dewa telah lenyap tanpa jejak. Lemuria, telah ditinggalkan oleh para dewa.\""
  },
  AvgDialog_47171_Content_57 = {
    Text = "\"Saat terakhir akan segera tiba. Kerajaan akan tenggelam ke dasar laut, dan peradaban Lemuria, akan lenyap di sini.\""
  },
  AvgDialog_47171_Content_58 = {
    Text = "\"Kerajaan Dewa, takkan pernah turun ke dunia.\""
  },
  AvgDialog_47171_Content_59 = {
    Text = "Guru... A-apa yang Anda katakan? Kata-kata ini... kata-kata penistaan ini..."
  },
  AvgDialog_47171_Content_6 = {
    Text = "Itu... bukankah itu Pendeta Agung?"
  },
  AvgDialog_47171_Content_60 = {
    Text = "Ini ujian, bukan? Tenang saja, aku sangat beriman kepada Sang Raja! Aku akan membantu Sang Raja, kita akan membawa Kerajaan Dewa..."
  },
  AvgDialog_47171_Content_61 = {
    Text = "Kata-kata ini, diucapkan langsung oleh Sang Raja sendiri."
  },
  AvgDialog_47171_Content_62 = {
    Text = "Sebelum Beliau naik takhta, Beliau telah menyadarinya dalam mimpi, dan memberitahukannya kepadaku... Beliau mencari dalam mimpi-Nya, hingga kini, Beliau akhirnya melihat dengan jelas masa depan."
  },
  AvgDialog_47171_Content_63 = {
    Text = "Sang Raja, tidak dapat menyelamatkan Lemuria."
  },
  AvgDialog_47171_Content_64 = {
    Text = "Dia berbalik, menatap Miriam dengan sungguh-sungguh."
  },
  AvgDialog_47171_Content_65 = {
    Text = "Dia melihat cahaya di mata gadis itu perlahan meredup. Dia melihatnya terpaku di tempat, kedua tangan yang telah terbiasa memberi hormat itu kini tak tahu harus diletakkan di mana."
  },
  AvgDialog_47171_Content_66 = {
    Text = "Raut kebingungan itu, persis sama seperti dirinya saat pertama kali mengetahui semua ini."
  },
  AvgDialog_47171_Content_67 = {
    Text = "Miriam, kau tahu, apa tanggung jawab terpenting seorang Pendeta Agung Lemuria?"
  },
  AvgDialog_47171_Content_68 = {
    Text = "Mendengarkan wahyu ilahi yang dibawa Sang Raja, membantu Sang Raja mewujudkan kerajaan para dewa, mengorganisir para penganut untuk menjalankan ritual... semua itu bukan."
  },
  AvgDialog_47171_Content_69 = {
    Text = "Tugas terpenting seorang Pendeta Agung adalah menipu."
  },
  AvgDialog_47171_Content_7 = {
    Text = "Pendeta Agung!"
  },
  AvgDialog_47171_Content_70 = {
    Text = "Menipu para penganut Lemuria, memberi mereka secercah cahaya, agar mereka bisa hidup tanpa begitu banyak penderitaan hingga saat Lemuria runtuh..."
  },
  AvgDialog_47171_Content_71 = {
    Text = "Kita berbagi rahasia yang sama dengan Sang Raja. Kita adalah juru bicara Sang Raja, sekaligus kaki tangan Sang Raja. Kita adalah para pendosa yang berkedudukan tinggi di Lemuria..."
  },
  AvgDialog_47171_Content_72 = {
    Text = "Sekarang, kau juga menjadi salah satu dari kami."
  },
  AvgDialog_47171_Content_73 = {
    Text = "Guru... Maksud Anda... Hah, tidak... Aku..."
  },
  AvgDialog_47171_Content_74 = {
    Text = "Miriam tersenyum secara refleks."
  },
  AvgDialog_47171_Content_75 = {
    Text = "Ini lelucon, kan? Atau semacam ujian? Pasti begitu."
  },
  AvgDialog_47171_Content_76 = {
    Text = "Pasti karena selama ini dirinya kurang taat kepada Sang Raja, maka Sang Raja sengaja mengujinya seperti ini."
  },
  AvgDialog_47171_Content_77 = {
    Text = "Asalkan bisa lebih baik sedikit lagi, lebih taat sedikit lagi..."
  },
  AvgDialog_47171_Content_78 = {
    Text = "Miriam berpikir demikian. Tangannya mencengkeram erat alas patung itu, seolah menggenggam seutas tali penyelamat."
  },
  AvgDialog_47171_Content_79 = {
    Text = "Tepian patung yang tajam merobek telapak tangannya, darah menetes, namun dia sama sekali tak menyadarinya."
  },
  AvgDialog_47171_Content_8 = {
    Text = "Melihat jubah ungu itu, beberapa penduduk Lemuria mengerumuni Miriam."
  },
  AvgDialog_47171_Content_80 = {
    Text = "Sang lelaki tua menggelengkan kepalanya perlahan, tatapannya menembus patung yang hancur dan lempengan batu yang tebal, memandang jauh ke langit yang membentang."
  },
  AvgDialog_47171_Content_81 = {
    Text = "Bintang-bintang memberitahuku, untuk menyerahkan takdir Lemuria ke tanganmu. Ini seharusnya menjadi tanggung jawab yang harus kupikul. Tapi sekarang, beban berat ini justru diserahkan kepadamu..."
  },
  AvgDialog_47171_Content_82 = {
    Text = "Ini tidak adil bagimu, Nak. Sangat tidak adil. Tapi, bintang-bintang, takdir, para dewa... Di hadapan Mereka, kata keadilan tak berarti apa-apa."
  },
  AvgDialog_47171_Content_83 = {
    Text = "Aku tak mampu memberimu keadilan, juga tak bisa lagi mengajarkan lebih banyak hal kepadamu."
  },
  AvgDialog_47171_Content_84 = {
    Text = "Jadi, apa pun yang ingin kaulakukan, lakukanlah. Sebagai korban ketidakadilan, sebagai pendosa Lemuria, kau berhak melakukannya."
  },
  AvgDialog_47171_Content_85 = {
    Text = "Tatapan Pendeta Agung Tua itu tak lagi tajam dan berwibawa, hanya tersisa kelelahan dan kekosongan. Ia berjalan keluar dengan tubuh membungkuk."
  },
  AvgDialog_47171_Content_86 = {
    Text = "Sang Raja telah terbangun, Beliau menunggumu."
  },
  AvgDialog_47171_Content_87 = {
    Text = "Kurasa, kau ingin menemui-Nya."
  },
  AvgDialog_47171_Content_89 = {
    Text = "Ia menatap air kolam."
  },
  AvgDialog_47171_Content_9 = {
    Text = "Sst! Jangan sampai orang lain tahu!"
  },
  AvgDialog_47171_Content_90 = {
    Text = "Kepala-kepala licin bermunculan ke permukaan air, lalu tenggelam kembali, silih berganti, menimbulkan riak-riak kotor di permukaan kolam."
  },
  AvgDialog_47171_Content_91 = {
    Text = "Bola mata raksasa tumbuh di kedua sisi kepala manusia ikan, berputar tanpa arah, menatapnya. Bibir mereka terbuka dan tertutup, mengucapkan suku kata samar tak bermakna, seolah menanyakan sesuatu kepadanya."
  },
  AvgDialog_47171_Content_92 = {
    Text = "Di belakangnya, pintu batu bergeser terbuka."
  },
  AvgDialog_47171_Content_93 = {
    Text = "Terpujilah Tuanku... Lemuria, Raja yang agung..."
  },
  AvgDialog_47171_Content_94 = {
    Text = "Setiap kali bertemu dengan kalian, Kami selalu mendengar sindiran ini."
  },
  AvgDialog_47171_Content_95 = {
    Text = "Mahkota raksasa Lemuria memantulkan kilau redup yang entah dari mana asalnya di ruangan ini, sangat tidak proporsional dengan tubuh sang pemuda."
  },
  AvgDialog_47171_Content_96 = {
    Text = "Namun mahkota itu bertengger di kepalanya tanpa kejanggalan sedikit pun, seolah sejak awal memang bagian dari tubuhnya."
  },
  AvgDialog_47171_Content_97 = {
    Text = "Mata yang masih mengantuk memandang Miriam, bagaikan lautan dalam yang bernapas perlahan. Di wajah mudanya yang masih kekanakan, tak terlihat emosi apa pun yang seharusnya dimiliki seorang pemuda."
  },
  AvgDialog_47171_Content_98 = {
    Text = "Kami pernah menduga, kau akan menangis, menjadi gila, atau mencoba membunuh Kami."
  },
  AvgDialog_47171_Content_99 = {
    Text = "Kau sangat tenang. Kami tidak tahu, apakah ketenangan ini adalah sebuah berkah, atau sebuah kutukan."
  },
  AvgDialog_47172_Content_1 = {
    Text = "Di Tengah Hujan"
  },
  AvgDialog_47172_Content_10 = {
    Text = "\"Kamu ini, pikirkan dulu bagaimana keadaanmu sendiri, kalau terus begini bukan solusi!\""
  },
  AvgDialog_47172_Content_100 = {
    Text = "\"Sang Raja melindungi kita. Aku hanyalah orang tak berguna, tapi sang Raja tetap melindungiku……\""
  },
  AvgDialog_47172_Content_101 = {
    Text = "\"Kau berbeda dari Ayah, Miriam. Kau adalah orang yang bisa menjadi pendeta, kebanggaan kita. Kau memiliki makna……\""
  },
  AvgDialog_47172_Content_102 = {
    Text = "\"Kau bisa membantu sang Raja, menyelamatkan Lemuria, menyambut……Kerajaan Ilahi……\""
  },
  AvgDialog_47172_Content_103 = {
    Text = "\"Ayah……Ayah!!!\""
  },
  AvgDialog_47172_Content_104 = {
    Text = "Darah dari luka-lukanya hampir mengering habis, air hujan bercampur sisa-sisa darah, mewarnai gaun panjang Miriam menjadi merah."
  },
  AvgDialog_47172_Content_105 = {
    Text = "Tubuh Inos masih membungkuk, melindungi putrinya yang telah tiada dari angin dan hujan yang tak mungkin dibendung."
  },
  AvgDialog_47172_Content_106 = {
    Text = "Ia membungkukkan badan, seolah hanya memeluk putrinya, mengucapkan selamat tinggal pada hari yang melelahkan, dan terlelap dalam tidur malam yang manis."
  },
  AvgDialog_47172_Content_107 = {
    Text = "\"Ayah…… Aku…… maafkan aku…… Aku gagal……\""
  },
  AvgDialog_47172_Content_108 = {
    Text = "Penyesalan dan kesakitan bagaikan kabut gelap tak berujung, menyumbat hati Miriam, membuatnya hampir tak bisa bernapas. Ia memeluk erat tubuh ayah dan adiknya."
  },
  AvgDialog_47172_Content_109 = {
    Text = "Hujan tampaknya mulai mereda sedikit. Ia mendongakkan kepala dan melihat payung hitam yang menutupi langit di atasnya."
  },
  AvgDialog_47172_Content_11 = {
    Text = "\"Untung hari ini cuma latihan, tidak ada pendeta yang mengawasi di sini, kalau tidak kamu pasti dimarahi lagi……\""
  },
  AvgDialog_47172_Content_110 = {
    Text = "Miriam menoleh ke belakang, melihat barisan pengawal, serta seorang lelaki tua berpakaian jubah suci yang berdiri di tengah-tengah mereka."
  },
  AvgDialog_47172_Content_111 = {
    Text = "Seolah melihat sepotong kayu penyelamat, ia berlutut dan beringsut mendekati sang lelaki tua."
  },
  AvgDialog_47172_Content_112 = {
    Text = "\"Tuan Pendeta Agung! Tuan Pendeta Agung, kumohon selamatkan ayahku!\""
  },
  AvgDialog_47172_Content_113 = {
    Text = "\"Penjaga, bawa dia pergi.\""
  },
  AvgDialog_47172_Content_114 = {
    Text = "\"Dosaku akan kutanggung sendiri! Tapi ayahku, dia selalu menjadi pengikut paling setia sang Raja…… Kumohon selamatkan dia!\""
  },
  AvgDialog_47172_Content_115 = {
    Text = "\"Kau tidak mengerti, Miriam.\""
  },
  AvgDialog_47172_Content_116 = {
    Text = "\"Lemuria tidak peduli pada hidup matinya seorang pengikut, juga tidak peduli pada dosamu.\""
  },
  AvgDialog_47172_Content_117 = {
    Text = "\"Yang dipedulikan Lemuria hanyalah masa depan dalam mimpi — masa depan menjadi kerajaan para dewa.\""
  },
  AvgDialog_47172_Content_118 = {
    Text = "\"Kau mungkin bagian dari masa depan itu, tapi…… itu tergantung pada pilihanmu sendiri.\""
  },
  AvgDialog_47172_Content_119 = {
    Text = "Pendeta Agung tua itu mendongak, menatap langit sekilas. Sepasang mata tajamnya seolah sedang berdialog dengan langit — sebuah percakapan yang tak mampu dipahami Miriam."
  },
  AvgDialog_47172_Content_12 = {
    Text = "\"Dimarahi itu masih hal kecil. Kalau aku jadi pendeta, mungkin aku sendiri sudah mengeluarkan diriku dari daftar murid pendeta.\""
  },
  AvgDialog_47172_Content_120 = {
    Text = "\"Miriam, apakah kau beriman kepada sang Raja?\""
  },
  AvgDialog_47172_Content_121 = {
    Text = "\"Aku beriman kepada sang Raja, Tuan Pendeta Agung, aku beriman kepada sang Raja! Aku adalah pengikut sang Raja…… Aku bersedia melakukan apa pun!\""
  },
  AvgDialog_47172_Content_122 = {
    Text = "\"Kalau begitu, apakah kau bersedia membunuh ayahmu demi sang Raja?\""
  },
  AvgDialog_47172_Content_123 = {
    Text = "\"Ini…… Aku……\""
  },
  AvgDialog_47172_Content_124 = {
    Text = "\"Miriam, apakah kau, beriman kepada sang Raja?!\""
  },
  AvgDialog_47172_Content_125 = {
    Text = "Sang Pendeta Agung tiba-tiba mendekat padanya, kedua matanya menatapnya tajam, bagaikan sebilah pisau yang terasah."
  },
  AvgDialog_47172_Content_126 = {
    Text = "Miriam terpaku di tempat. Pertanyaan tajam sang Pendeta Agung membuatnya hampir lupa untuk memohon pertolongan bagi ayahnya."
  },
  AvgDialog_47172_Content_127 = {
    Text = "\"Ada satu cara, agar ayahmu bisa tetap hidup.\""
  },
  AvgDialog_47172_Content_128 = {
    Text = "\"Pendeta Agung?!!!\""
  },
  AvgDialog_47172_Content_129 = {
    Text = "\"Sekarang, jawab aku. Apa itu keimanan.\""
  },
  AvgDialog_47172_Content_13 = {
    Text = "\"Kamu juga sadar ya? Heran kamu masih bisa tersenyum! Ini sudah hampir setengah tahun, setiap kali ritual manusia ikan kamu selalu tidak bisa melakukannya, kalau terus begini sangat berbahaya!\""
  },
  AvgDialog_47172_Content_130 = {
    Text = "\"Aku…tidak tahu…Yang Mulia…\""
  },
  AvgDialog_47172_Content_131 = {
    Text = "\"Keimanan, adalah segala tanggung jawab dan makna. Adalah selain itu, tiada pikiran lain.\""
  },
  AvgDialog_47172_Content_132 = {
    Text = [[
"Hanya keimanan kepada Raja, yang bisa menyelamatkan ayahmu.
Untuk memiliki keimanan ini, kau harus terlebih dahulu membunuh ayahmu."]]
  },
  AvgDialog_47172_Content_133 = {
    Text = "\"Pendeta Agung…aku…tidak mengerti…\""
  },
  AvgDialog_47172_Content_134 = {
    Text = "Pendeta Agung berjalan perlahan menuju Miriam, matanya menatap tajam ke dalam kedua mata Miriam, menangkap setiap riak halus di dalamnya."
  },
  AvgDialog_47172_Content_135 = {
    Text = "\"Ubah ayahmu, menjadi manusia ikan, baru bisa menyelamatkan nyawanya.\""
  },
  AvgDialog_47172_Content_136 = {
    Text = "\"Lupakan ayahmu. Lupakan keluargamu. Sepenuh hati beriman kepada Raja Lemuria, panjatkan pujian kepada-Nya, berserah diri kepada-Nya. Seperti seorang pendeta, ikuti petunjuk Raja, selesaikan ritual transformasi.\""
  },
  AvgDialog_47172_Content_137 = {
    Text = "\"Jika ingin menyelamatkan ayahmu, jika ingin menebus dosamu, ini satu-satunya jalan.\""
  },
  AvgDialog_47172_Content_138 = {
    Text = "Ia menatap sosok kurus Miriam yang terduduk lemas di tanah, bagaikan menatap sebuah ramalan tentang kehancuran dan kelahiran kembali, tentang jurang dan harapan."
  },
  AvgDialog_47172_Content_139 = {
    Text = "\"Kalau begitu, Miriam, apakah kau sudah siap, untuk membunuh ayahmu?\""
  },
  AvgDialog_47172_Content_14 = {
    Text = "\"Kamu ini, pelajaran teori ramuan herbal yang rumit itu, kamu belajar lebih cepat dari siapa pun, kenapa begitu sampai ritual ini kamu tidak bisa……\""
  },
  AvgDialog_47172_Content_15 = {
    Text = "\"Maaf, aku…… kalau membayangkan harus melakukan hal sekejam itu pada mereka, aku benar-benar tidak sanggup…… aku tidak bisa……\""
  },
  AvgDialog_47172_Content_16 = {
    Text = "\"Bakatmu sehebat itu, mana mungkin tidak bisa! Seperti yang dikatakan Pendeta Agung, kamu hanya perlu sepenuh hati berdoa kepada Raja, lupakan hal-hal lainnya, pasti bisa!\""
  },
  AvgDialog_47172_Content_17 = {
    Text = "\"Deborah, aku benar-benar…… setiap kali aku melihat doa-doa itu, dan makhluk-makhluk yang mirip ikan itu, aku teringat keluargaku.\""
  },
  AvgDialog_47172_Content_18 = {
    Text = "\"Yang selalu muncul di sisiku untuk melindungiku, selalu keluargaku, bukan Raja……\""
  },
  AvgDialog_47172_Content_19 = {
    Text = "\"Sst! Apa yang kamu bicarakan?!\""
  },
  AvgDialog_47172_Content_2 = {
    Text = "Beberapa bulan kemudian."
  },
  AvgDialog_47172_Content_20 = {
    Text = "\"Tuanku, mohon maafkan Miriam, pikirannya sedang kacau karena ketakutan oleh manusia ikan…… mohon maafkan, mohon maafkan……\""
  },
  AvgDialog_47172_Content_21 = {
    Text = "Deborah memberi hormat dengan khidmat ke arah patung di ruang doa, lalu melotot tajam ke Miriam."
  },
  AvgDialog_47172_Content_22 = {
    Text = "\"Kamu harus hati-hati bicara! Kalau sampai didengar Raja, kamu akan dihukum!\""
  },
  AvgDialog_47172_Content_23 = {
    Text = "\"Maaf…… aku seharusnya tidak mengatakan hal itu……\""
  },
  AvgDialog_47172_Content_24 = {
    Text = "\"Kamu seharusnya tidak berpikir seperti itu! Hah, sudahlah sudahlah, hal seperti ini memang tidak bisa dipaksakan. Kita pelan-pelan saja.\""
  },
  AvgDialog_47172_Content_25 = {
    Text = "\"Kebanyakan orang Lemuria lebih peduli pada Raja, tapi kamu sepertinya lebih peduli pada keluargamu sendiri. Tapi, sepertinya aku belum pernah mendengarmu bercerita tentang mereka?\""
  },
  AvgDialog_47172_Content_26 = {
    Text = "\"Sudah setengah tahun tidak bertemu mereka, pasti sangat merindukan mereka kan…… Mau bercerita padaku?\""
  },
  AvgDialog_47172_Content_27 = {
    Text = "\"Boleh? Tapi mungkin akan lama, dan semuanya hanya hal-hal kecil yang tidak beraturan……\""
  },
  AvgDialog_47172_Content_28 = {
    Text = "\"Toh tidak ada hal lain, kamu cerita pelan-pelan, aku dengarkan pelan-pelan.\""
  },
  AvgDialog_47172_Content_29 = {
    Text = "\"Coba kuingat mulai dari mana…… Hmm, dulu, di rumahku ada ayah, ibu, dan seorang adik perempuan.\""
  },
  AvgDialog_47172_Content_3 = {
    Text = "Ia memegang belati upacara, memandangi makhluk setengah manusia setengah ikan di atas altar batu."
  },
  AvgDialog_47172_Content_30 = {
    Text = "\"Waktu aku masih kecil, ibuku meninggal karena Bencana Alam, dan ayah membesarkan kami seorang diri. Dia adalah orang yang sangat hebat, selalu melindungi keluarga ini.\""
  },
  AvgDialog_47172_Content_31 = {
    Text = "\"Adik perempuanku juga sangat manis, meskipun sifatnya agak ceroboh, tapi dia sangat pintar dan pengertian……\""
  },
  AvgDialog_47172_Content_32 = {
    Text = "\"Ngomong-ngomong, sifat kalian cukup mirip lho. Bagaimana kalau hari ini aku mengambil satu adik perempuan lagi?\""
  },
  AvgDialog_47172_Content_33 = {
    Text = "\"Dasar kamu Miriam, pandai sekali mengambil kesempatan dariku!\""
  },
  AvgDialog_47172_Content_34 = {
    Text = "Miriam jarang bercerita tentang hal-hal ini kepada orang lain. Awalnya dia belum terbiasa, bicaranya terputus-putus. Tapi tak lama kemudian, kata-katanya menjadi lancar dan riang."
  },
  AvgDialog_47172_Content_35 = {
    Text = "Dia menceritakan kepada Deborah setiap kenangan kecil tentang keluarganya dengan detail, wajahnya tanpa sadar tersenyum, seolah sedang memamerkan harta karun rahasianya."
  },
  AvgDialog_47172_Content_36 = {
    Text = "Di tengah samar-samar suara guntur dan hujan, mereka berjalan menyusuri koridor panjang yang tenang, sambil bercanda dan berjalan ke depan."
  },
  AvgDialog_47172_Content_37 = {
    Text = "\"……Sehari sebelum datang ke kuil, dia memasakkan semeja penuh ikan untukku. Aku pura-pura sangat suka, dan menghabiskan sepiring ikan itu. Ekspresinya waktu itu sangat bahagia.\""
  },
  AvgDialog_47172_Content_38 = {
    Text = "\"Hahahaha…… Kalau ayahmu tahu yang sebenarnya, pasti dia akan kesal setengah mati!\""
  },
  AvgDialog_47172_Content_39 = {
    Text = "\"Aku sudah berjanji dengan adikku, hal ini tidak akan pernah kami biarkan dia tahu. Kalau aku pulang nanti, aku harus makan ikan buatannya lagi…… Aduh, memikirkannya saja sudah pusing.\""
  },
  AvgDialog_47172_Content_4 = {
    Text = "Suara angin, hujan, dan gemuruh guntur samar menembus dinding batu yang tebal, terdengar redam di dalam kuil."
  },
  AvgDialog_47172_Content_40 = {
    Text = "\"Pusing? Tapi kelihatannya kamu tersenyum cukup senang tuh. Kamu itu menderita sekaligus menikmati, cari masalah sendiri, rasakan~\""
  },
  AvgDialog_47172_Content_41 = {
    Text = "Klang klang klang—"
  },
  AvgDialog_47172_Content_42 = {
    Text = "Suara benturan senjata disertai langkah kaki yang tergesa-gesa bergema di dalam kuil, memotong pembicaraan mereka."
  },
  AvgDialog_47172_Content_43 = {
    Text = "\"Berhenti!\""
  },
  AvgDialog_47172_Content_44 = {
    Text = "\"Situasi darurat!……Bencana Alam……lembah selatan……korban jiwa……tim pengumpul jenazah……mencegah wabah……\""
  },
  AvgDialog_47172_Content_45 = {
    Text = "Beberapa kata samar-samar terdengar di telinga Miryam, para pengawal bergegas menuju ke bagian dalam kuil. Langkahnya terhenti mendadak."
  },
  AvgDialog_47172_Content_46 = {
    Text = "\"Lembah selatan... Miryam, tadi kamu bilang, rumahmu sepertinya ada di...\""
  },
  AvgDialog_47172_Content_47 = {
    Text = "\"Deborah, aku harus kembali!\""
  },
  AvgDialog_47172_Content_48 = {
    Text = "Miryam mengangguk cepat, menoleh ke sana kemari dengan cemas, seolah mencari sesuatu."
  },
  AvgDialog_47172_Content_49 = {
    Text = "\"Kamu gila? Murid pendeta kabur diam-diam dari kuil itu dosa besar!\""
  },
  AvgDialog_47172_Content_5 = {
    Text = "\"'Wahai pengikut Tuanku, silakan, silakan buka hatimu, terimalah…… terimalah Tuanku……'\""
  },
  AvgDialog_47172_Content_50 = {
    Text = "\"Jangan khawatir, Miryam... Keluargamu pasti baik-baik saja...\""
  },
  AvgDialog_47172_Content_51 = {
    Text = "\"Tidak, Deborah... Medan di Lembah Selatan sangat mudah... Ibu dulu juga pernah...\""
  },
  AvgDialog_47172_Content_52 = {
    Text = "\"Aku punya firasat... Aku harus kembali untuk melihat!\""
  },
  AvgDialog_47172_Content_53 = {
    Text = "\"Tapi... Sebentar lagi akan diadakan pertemuan seluruh murid, aku tidak bisa memikirkan cara untuk membantu...\""
  },
  AvgDialog_47172_Content_54 = {
    Text = "\"Ah! Miryam... Kamu...\""
  },
  AvgDialog_47172_Content_55 = {
    Text = "Rasa kantuk yang luar biasa menyerang otaknya. Itu adalah ramuan hipnotis yang digunakan dalam upacara ritual, yang selalu dibawa oleh para pendeta."
  },
  AvgDialog_47172_Content_56 = {
    Text = "Ramuan itu membantu para umat menemukan ketenangan, dan juga membantu para pendeta meringankan dosa."
  },
  AvgDialog_47172_Content_57 = {
    Text = "Di antara semua murid, Miryam adalah yang paling mahir dalam pelajaran ini, Deborah selalu mengetahui hal itu."
  },
  AvgDialog_47172_Content_58 = {
    Text = "\"Aku tidak ingin melibatkanmu. Tidurlah yang nyenyak.\""
  },
  AvgDialog_47172_Content_59 = {
    Text = "\"Aku harus kembali... Maaf, Deborah.\""
  },
  AvgDialog_47172_Content_6 = {
    Text = "\"Maaf…… ugh——\""
  },
  AvgDialog_47172_Content_60 = {
    Text = "Dia membaringkan Deborah dengan lembut di sudut yang tak terlihat siapa pun, dan sementara para penjaga belum kembali ke posisi mereka, dia berbalik berlari menuju luar kuil."
  },
  AvgDialog_47172_Content_62 = {
    Text = "\"Dengarkanlah Tuhan kami. Berserahlah kepada Tuhan kami.\""
  },
  AvgDialog_47172_Content_63 = {
    Text = "Hujan lebat. Angin kencang. Guntur menggelegar."
  },
  AvgDialog_47172_Content_64 = {
    Text = "\"Yang beriman dengan tulus, Tuhan kami akan melindungi.\""
  },
  AvgDialog_47172_Content_65 = {
    Text = "Rumah-rumah runtuh. Kerumunan orang menangis. Batu-batu pecah berjatuhan seperti balok-balok mainan yang berantakan dari lereng gunung di kedua sisi."
  },
  AvgDialog_47172_Content_66 = {
    Text = "\"Segala yang didambakan, Tuhan kami akan mengabulkannya.\""
  },
  AvgDialog_47172_Content_67 = {
    Text = "Dunia di matanya berubah menjadi warna lain, seolah tertutup filter berlumur darah."
  },
  AvgDialog_47172_Content_68 = {
    Text = "Setelah berlari berjam-jam di tengah hujan, ia tidak yakin apakah tempat yang ia tuju benar-benar kampung halamannya."
  },
  AvgDialog_47172_Content_69 = {
    Text = "Jalan-jalan dan bangunan yang begitu familiar itu, mengapa semuanya lenyap?"
  },
  AvgDialog_47172_Content_7 = {
    Text = "Dia menutup mulutnya dan berlari ke samping, kejang di perutnya membuatnya harus berpegangan pada dinding agar bisa berdiri dengan susah payah."
  },
  AvgDialog_47172_Content_70 = {
    Text = "Tetangga-tetangga yang begitu dikenalnya, mengapa banyak yang tak lagi terlihat?"
  },
  AvgDialog_47172_Content_71 = {
    Text = "Ia telah menempuh perjalanan panjang untuk sampai ke sini, dan kini ia hanya ingin pergi dari tempat ini. Namun kedua kakinya tetap menyeretnya, membawanya kembali ke rumahnya sendiri."
  },
  AvgDialog_47172_Content_72 = {
    Text = "——Rumah yang menyimpan tawa dan air mata tak terhitung darinya. Rumah yang telah berkali-kali hancur dihantam bencana, dan berkali-kali dibangun kembali."
  },
  AvgDialog_47172_Content_73 = {
    Text = "Rumah yang kini hanya menyisakan reruntuhan."
  },
  AvgDialog_47172_Content_74 = {
    Text = "\"Segala penderitaan, Tuhan kami akan membalasnya.\""
  },
  AvgDialog_47172_Content_75 = {
    Text = "Pria itu berlutut membungkuk di antara reruntuhan, sama sekali tak menghiraukan batu-batu tajam dan serpihan kayu."
  },
  AvgDialog_47172_Content_76 = {
    Text = "Hujan deras menghantam punggungnya tanpa ampun. Tulang punggungnya membungkuk sekuat tenaga, berusaha melengkungkan tubuhnya menjadi atap yang setidaknya bisa menahan angin dan hujan."
  },
  AvgDialog_47172_Content_77 = {
    Text = "Namun atap itu tak mampu melindungi apa pun. Tak peduli sekeras apa ia berusaha menghalangi, hujan deras tetap menembus tubuh kecilnya, jatuh menimpa jasad gadis kecil dalam dekapannya."
  },
  AvgDialog_47172_Content_78 = {
    Text = "Ia hanya bisa berulang kali membelai wajahnya, menggunakan kedua tangan kasarnya untuk menyeka air hujan dari wajah yang perlahan mendingin dan memucat itu."
  },
  AvgDialog_47172_Content_79 = {
    Text = "\"Sa... Sara... tidak...\""
  },
  AvgDialog_47172_Content_8 = {
    Text = "\"Miriam, kamu tidak apa-apa?\""
  },
  AvgDialog_47172_Content_80 = {
    Text = "Pita suara Miriam nyaris tak bergetar, suaranya hampir tak terdengar. Ia melangkah maju, terjatuh, merangkak dengan mati rasa ke sisi jasad adiknya, membelainya dengan tangan gemetar."
  },
  AvgDialog_47172_Content_81 = {
    Text = "\"Saat itu dia sedang tidur. Kau tahu sendiri, kalau Sara tidur, dia selalu tidur sangat nyenyak. Tak ada yang bisa membangunkannya.\""
  },
  AvgDialog_47172_Content_82 = {
    Text = "\"Dia pergi dengan tenang... tanpa ketakutan, tanpa kesakitan, tanpa kerinduan, tanpa apa pun.\""
  },
  AvgDialog_47172_Content_83 = {
    Text = "\"Waktu itu, saat ibumu meninggal, aku juga berkata hal yang sama pada diriku sendiri.\""
  },
  AvgDialog_47172_Content_84 = {
    Text = "\"Aku hanya bisa menghibur diriku seperti ini, Miriam... Aku tak mampu melindungi mereka, aku hanya bisa menghibur diriku seperti ini...\""
  },
  AvgDialog_47172_Content_85 = {
    Text = "Pria itu mengira air matanya sudah lama kering, namun begitu beberapa patah kata terucap, air mata kembali bercampur dengan air hujan. Ia tergagap, bibir yang memutih karena dingin dan kelelahan itu bergerak-gerak tanpa suara."
  },
  AvgDialog_47172_Content_86 = {
    Text = "Inos terbatuk kesakitan dua kali. Baru saat itulah Miriam menyadari, di kaki dan perutnya, dua luka besar sedang merembeskan sisa-sisa darah terakhir dari tubuhnya."
  },
  AvgDialog_47172_Content_87 = {
    Text = "\"Ayah! Kau……kau terluka?……\""
  },
  AvgDialog_47172_Content_88 = {
    Text = "Dengan panik, ia mengeluarkan entah ramuan herbal apa dan menempelkannya pada luka ayahnya, lalu menoleh ke sana kemari dengan kalut, berusaha mencari sesuatu yang bisa digunakan."
  },
  AvgDialog_47172_Content_89 = {
    Text = "\"Miriam, tidak ada gunanya.\""
  },
  AvgDialog_47172_Content_9 = {
    Text = "\"Aku tidak apa-apa…… maaf, Deborah, aku menghambatmu……\""
  },
  AvgDialog_47172_Content_90 = {
    Text = "\"Aku bisa menyelamatkanmu……aku bisa menyelamatkanmu, Ayah!\""
  },
  AvgDialog_47172_Content_91 = {
    Text = "\"Aku sudah melakukan semua yang bisa kulakukan, Miriam. Tapi tidak ada artinya……mereka tetap mati. Ibumu, adikmu……\""
  },
  AvgDialog_47172_Content_92 = {
    Text = "\"Di Lemuria, orang sepertiku, melakukan apa pun tidak ada artinya……\""
  },
  AvgDialog_47172_Content_93 = {
    Text = "Ia berusaha mengangkat kepalanya, menatap pegunungan yang runtuh, menatap reruntuhan di mana-mana, menatap langit yang tanpa emosi menjatuhkan bencana begitu saja ke pulau ini."
  },
  AvgDialog_47172_Content_94 = {
    Text = "Mengikuti arah pandangannya, Miriam melihat ke lereng gunung di kedua sisi."
  },
  AvgDialog_47172_Content_95 = {
    Text = "\"Ayah, itu……\""
  },
  AvgDialog_47172_Content_96 = {
    Text = "Bongkahan batu raksasa berguling jatuh dari gunung, seharusnya menenggelamkan seluruh kota kecil ini sepenuhnya."
  },
  AvgDialog_47172_Content_97 = {
    Text = "Beberapa tentakel raksasa menjulur keluar dari dalam tanah, menahan sebagian besar batu-batu mengerikan itu."
  },
  AvgDialog_47172_Content_98 = {
    Text = "Inos menundukkan kepalanya, memandang putrinya di sampingnya, memandang satu-satunya harapan dan kebanggaan yang tersisa baginya."
  },
  AvgDialog_47172_Content_99 = {
    Text = "\"Itu mukjizat sang Raja……\""
  },
  AvgDialog_47173_Content_1 = {
    Text = "Persembahan untuk Raja"
  },
  AvgDialog_47173_Content_10 = {
    Text = "Aku ingat, Ayah. Semua hal ini, aku ingat semuanya..."
  },
  AvgDialog_47173_Content_100 = {
    Text = "Jika kau tidak bisa terhubung dengan mimpi Raja, kau akan mati dalam kesakitan."
  },
  AvgDialog_47173_Content_101 = {
    Text = "Jika kau bertahan hidup, kenakan pakaian ini. Aku akan membimbingmu menjadi seorang pendeta Lemuria yang sejati."
  },
  AvgDialog_47173_Content_102 = {
    Text = "Seolah baru menyelesaikan tugas berat, atau baru melakukan kejahatan yang keji. Orang tua itu menghembuskan napas panjang, membungkukkan tubuhnya, dan meninggalkan ruang doa."
  },
  AvgDialog_47173_Content_103 = {
    Text = "Miryam berjalan seperti mesin menuju patung itu, lalu mengangkat piala."
  },
  AvgDialog_47173_Content_104 = {
    Text = "Kau membunuh Ayah."
  },
  AvgDialog_47173_Content_105 = {
    Text = "Itu adalah wajah yang sangat dikenal Miryam, namun sekaligus terasa sangat asing."
  },
  AvgDialog_47173_Content_106 = {
    Text = "Miryam yang berusia delapan belas tahun menoleh ke samping, dan melihat dirinya yang berusia sembilan tahun duduk di sisinya, menatap patung di hadapan mereka."
  },
  AvgDialog_47173_Content_107 = {
    Text = "Tidak, aku menyelamatkan Ayah... Dia pernah melindungi kita berkali-kali. Sekarang, giliran kita yang melindunginya."
  },
  AvgDialog_47173_Content_108 = {
    Text = "Tapi, Ayah tidak akan ingin melihatmu seperti ini..."
  },
  AvgDialog_47173_Content_109 = {
    Text = "Dia akan mau. Ayah akan merasa sakit, akan sedih, tapi dia akan mendukungku."
  },
  AvgDialog_47173_Content_11 = {
    Text = "Jalan ini, benar-benar mirip jalan pulang ke rumah kita dulu."
  },
  AvgDialog_47173_Content_110 = {
    Text = "Hanya dengan cara ini, aku benar-benar bisa membantu Lemuria, membawakan kerajaan dewa untuknya……"
  },
  AvgDialog_47173_Content_111 = {
    Text = "Darah ular sebanyak ini, sangat sedikit orang yang bisa menahannya. Kau ingin mati, kan?"
  },
  AvgDialog_47173_Content_112 = {
    Text = "Miriam……apakah kau percaya pada kerajaan dewa?"
  },
  AvgDialog_47173_Content_113 = {
    Text = "Dia menatap matanya, seolah menatap seorang dewa yang naif. Mata anak berusia sembilan tahun itu dipenuhi kesedihan yang jauh lebih dalam daripada Miriam yang berusia delapan belas tahun."
  },
  AvgDialog_47173_Content_114 = {
    Text = "……Apa lagi yang bisa kupercayai?"
  },
  AvgDialog_47173_Content_115 = {
    Text = "Miriam tersenyum padanya, mengangkat piala, dan memandang patung di hadapannya dengan penuh khidmat."
  },
  AvgDialog_47173_Content_116 = {
    Text = "Kupersembahkan segalanya kepada-Mu. Jawablah harapanku, Tuanku."
  },
  AvgDialog_47173_Content_117 = {
    Text = "Darah sang ayah menetes dari wajahnya, bercampur dengan darah ular di dalam piala."
  },
  AvgDialog_47173_Content_118 = {
    Text = "Tanpa keraguan sedikit pun, dia mendongakkan kepala dan meneguk habis cairan yang berbau amis pekat itu dalam sekali teguk."
  },
  AvgDialog_47173_Content_12 = {
    Text = "Sekarang putriku sudah besar. Saat ayah lelah, akhirnya ada seseorang yang bisa dijadikan sandaran."
  },
  AvgDialog_47173_Content_13 = {
    Text = "Miriam menatap ayahnya. Ayah yang dulu muncul di hadapannya bagaikan dewa, melindunginya dan menopang seluruh keluarga, kini telah menjadi begitu tua dan lemah."
  },
  AvgDialog_47173_Content_14 = {
    Text = "Bagaikan batu yang tampak kokoh, namun ketika cangkang kerasnya pecah, barulah terlihat bahwa di dalamnya tersimpan hati yang rapuh."
  },
  AvgDialog_47173_Content_15 = {
    Text = "Sudah sampai, turunlah."
  },
  AvgDialog_47173_Content_16 = {
    Text = "Kereta berhenti. Di dalam ruang upacara yang remang-remang, lampu minyak menyala. Dudukan lampu berputar perlahan, dengan ukiran tentakel dan mata yang menatap bolak-balik ke arah orang-orang yang sibuk bekerja."
  },
  AvgDialog_47173_Content_17 = {
    Text = "Di tengah lingkaran sihir berwarna darah yang dilukis dengan simbol-simbol kuno, sebuah ranjang batu yang sepi menunggu dengan sunyi."
  },
  AvgDialog_47173_Content_18 = {
    Text = "Miriam memapah ayahnya dan membaringkannya di atas ranjang batu."
  },
  AvgDialog_47173_Content_19 = {
    Text = "Hanya beberapa langkah pendek, namun seolah telah menguras seluruh tenaga Enos. Dia terbatuk-batuk kesakitan, hampir pingsan."
  },
  AvgDialog_47173_Content_2 = {
    Text = "Ternyata begini rupanya bagian dalam kuil…"
  },
  AvgDialog_47173_Content_20 = {
    Text = "Tidak apa-apa, Ayah, tidak apa-apa... Kau akan segera sembuh..."
  },
  AvgDialog_47173_Content_21 = {
    Text = "Di ruangan inilah, upacaramu pernah gagal. Gagal berkali-kali."
  },
  AvgDialog_47173_Content_22 = {
    Text = "Aku... ingat, Tuan Imam Agung."
  },
  AvgDialog_47173_Content_23 = {
    Text = "Jika kau tidak bisa sepenuh hati meyakini titah Sang Raja dan tidak mendapat pengakuan dari Sang Raja, upacaramu akan tetap gagal."
  },
  AvgDialog_47173_Content_24 = {
    Text = "Kau bisa memilih untuk menyerah. Aku akan membuatnya pergi tanpa rasa sakit."
  },
  AvgDialog_47173_Content_25 = {Text = "Aku..."},
  AvgDialog_47173_Content_26 = {
    Text = "Ini adalah takdirmu. Pikirkanlah baik-baik, lalu buatlah keputusanmu."
  },
  AvgDialog_47173_Content_27 = {
    Text = "Para pengawal di sampingnya meletakkan peralatan dan bahan yang diperlukan untuk upacara di sisi ruangan, lalu mengikuti Imam Agung meninggalkan ruangan."
  },
  AvgDialog_47173_Content_28 = {
    Text = "Cahaya lilin yang dingin menerangi dua orang yang tersisa di ruangan itu."
  },
  AvgDialog_47173_Content_29 = {
    Text = "Miriam berlutut di sisi ranjang batu, membenamkan kepalanya di dada sang ayah."
  },
  AvgDialog_47173_Content_3 = {
    Text = "Beberapa hari lalu Sara masih berkata, dia merindukan kakaknya, ingin datang melihat seperti apa tempat kakaknya tinggal."
  },
  AvgDialog_47173_Content_30 = {
    Text = "Apa yang harus kulakukan... Ayah..."
  },
  AvgDialog_47173_Content_31 = {
    Text = "Kau menangis, Nak... Apa yang membuat Miriam kecil kita begitu sedih?"
  },
  AvgDialog_47173_Content_32 = {
    Text = "Sepasang tangan diletakkan di kepala Miriam, mengelusnya dengan lembut, seperti yang selalu dilakukan setiap kali ia bersedih sejak kecil."
  },
  AvgDialog_47173_Content_33 = {
    Text = "Miriam tak bisa lagi menahan air matanya. Seluruh tubuhnya berguncang, air mata menetes jatuh ke tubuh Inos yang basah dan dingin."
  },
  AvgDialog_47173_Content_34 = {
    Text = "Ia menggenggam erat tangan ayahnya, seolah selama ia menggenggam cukup erat, sang ayah akan terus menemaninya."
  },
  AvgDialog_47173_Content_35 = {
    Text = "Miriam, kau dengar itu? Itu suara ibumu... Dia memanggil kita pulang untuk makan malam. Dan Sara juga, dia sedang melambaikan tangan ke arah kita..."
  },
  AvgDialog_47173_Content_36 = {
    Text = "Aku melihatnya... Ayah, aku melihatnya..."
  },
  AvgDialog_47173_Content_37 = {
    Text = "Aku sudah bilang pada ibumu, hari ini kita masak ikan untukmu. Ayah tahu, kau paling suka makan ikan."
  },
  AvgDialog_47173_Content_38 = {
    Text = "Ibumu belum tahu, Miriam kita sudah menjadi murid pendeta. Nanti kalau kita beritahu, pasti dia akan sangat terkejut."
  },
  AvgDialog_47173_Content_39 = {
    Text = "Sebentar lagi, kau akan menjadi pendeta, kan?"
  },
  AvgDialog_47173_Content_4 = {
    Text = "Inos lembut membelai wajah putri kecilnya."
  },
  AvgDialog_47173_Content_40 = {
    Text = "...Ya, Ayah, sebentar lagi, aku akan menjadi pendeta..."
  },
  AvgDialog_47173_Content_41 = {
    Text = "Sudah kuduga. Kau memang berbakat, aku selalu tahu itu."
  },
  AvgDialog_47173_Content_42 = {
    Text = "Orang-orang Lemuria hidup terlalu menderita. Aku tidak pernah menyukai Lemuria, Nak, tapi aku tak bisa meninggalkannya... Karena kalian ada di sini, rumahku ada di sini."
  },
  AvgDialog_47173_Content_43 = {
    Text = "Aku bisa melakukan banyak hal, membangun rumah, menangkap ikan untuk mencari nafkah, memasak untuk kalian... Tapi aku tak bisa mengubah apa pun."
  },
  AvgDialog_47173_Content_44 = {
    Text = "Kau berbeda, Miriam. Kau akan menjadi pengikut yang paling dipercaya oleh Raja, kau akan membantu Raja, menjadikan Lemuria... kerajaan dewa seperti dalam legenda..."
  },
  AvgDialog_47173_Content_45 = {
    Text = "Di kerajaan dewa, ada makanan dan anggur yang tak terhitung banyaknya, setiap hari cuaca cerah dan langit biru membentang. Tak ada lagi orang yang mati karena bencana."
  },
  AvgDialog_47173_Content_46 = {
    Text = "Kita akan punya rumah batu yang kokoh... Inos, Paya, Miriam, Sara, di rumah itu, kita sekeluarga akan hidup bahagia bersama..."
  },
  AvgDialog_47173_Content_47 = {
    Text = "Benar, Ayah... Kita akan bertemu lagi di kerajaan dewa! Kita sekeluarga akan hidup bersama di kerajaan dewa..."
  },
  AvgDialog_47173_Content_48 = {
    Text = "Dia mengusap air mata dari wajahnya, perlahan berdiri, dan mengambil belati di sampingnya."
  },
  AvgDialog_47173_Content_49 = {
    Text = "Belati itu melengkung dalam sudut yang aneh, dengan simbol hieroglif rumit yang sama seperti pada doa-doa yang terukir di permukaannya."
  },
  AvgDialog_47173_Content_5 = {
    Text = "Ramuan herbal yang mahal untuk sementara menyelamatkan nyawanya. Umat yang saleh ini untuk pertama kalinya memasuki aula suci ini, datang ke tempat yang begitu dekat dengan Raja."
  },
  AvgDialog_47173_Content_50 = {
    Text = "Di dalam bejana batu di samping belati, darah yang berasal dari sumber yang sama dengan para dewa beriak pelan, cahaya lilin terpantul, membiaskan kilau yang gelap dan misterius."
  },
  AvgDialog_47173_Content_51 = {
    Text = "Delirium yang parah telah merenggut hampir seluruh kesadaran Inos. Dia membuka matanya, menatap Miriam dengan penasaran, seperti bayi yang baru lahir, memandangi dunia baru yang asing di hadapannya."
  },
  AvgDialog_47173_Content_52 = {
    Text = "Miriam, sekarang kau sudah menjadi pendeta… Apakah kau sudah bertanya kepada Raja? Apakah Raja memberitahumu, kapan Kerajaan Tuhan akan turun ke Lemuria?"
  },
  AvgDialog_47173_Content_53 = {
    Text = "Sudah kutanyakan, Ayah… Raja berkata, segera, segera…"
  },
  AvgDialog_47173_Content_54 = {
    Text = "Di antara air mata, muncul senyuman yang pilu. Dia mendekati Inos, membungkuk, dan membelai wajahnya."
  },
  AvgDialog_47173_Content_55 = {
    Text = "Aku tidak akan mengecewakanmu, Ayah."
  },
  AvgDialog_47173_Content_56 = {
    Text = "Kerajaan Tuhan akan segera turun, Ayah. Sebentar lagi, keluarga kita akan bersatu kembali…"
  },
  AvgDialog_47173_Content_57 = {Text = "Jleb——"},
  AvgDialog_47173_Content_58 = {
    Text = "Belati menghujam dada Inos dengan keras, Inos menjerit kesakitan. Darah menyembur, mewarnai separuh wajah kanan Miriam."
  },
  AvgDialog_47173_Content_59 = {
    Text = "Miriam membelalakkan matanya, menatap dengan saksama sayatan antara belati dan daging, seolah sedang memandangi sebuah mahakarya lukisan."
  },
  AvgDialog_47173_Content_6 = {
    Text = "Kebencian terhadap bencana, kesedihan kehilangan putrinya, ketakutan akan kematian, serta kegembiraan berziarah…emosi yang rumit saling merobek dalam tubuhnya yang biasa. Ia bersandar di bahu Miriam."
  },
  AvgDialog_47173_Content_60 = {
    Text = "Belati bergerak, meluncur, membelah kulit dan tulang. Inos meraung kesakitan, seperti seekor binatang buas yang sedang dicabik-cabik."
  },
  AvgDialog_47173_Content_61 = {
    Text = "Jeritan dan darah membanjiri ruang ritual, bagaikan duri-duri tak terhitung yang menembus wajah dan kulit Miriam, menusuk hingga ke jantung dan paru-parunya."
  },
  AvgDialog_47173_Content_63 = {
    Text = "\"Wahai pengikut Tuanku, bukalah hatimu, terimalah Tuanku…\""
  },
  AvgDialog_47173_Content_64 = {
    Text = "Darah dan air mata membasuh wajah Miriam yang terdistorsi mengerikan. Dia merapalkan doa, gerakan tangannya semakin cepat, semakin cepat."
  },
  AvgDialog_47173_Content_65 = {
    Text = "Belati berhenti. Di tubuh Inos, dengan tulang dan darahnya sendiri, terlukis simbol-simbol yang melambangkan kebahagiaan dan harapan."
  },
  AvgDialog_47173_Content_66 = {
    Text = "\"Yang beriman dengan tulus, Tuanku akan memberkati…\""
  },
  AvgDialog_47173_Content_67 = {
    Text = "<Big:\"Yang berharap dengan sungguh, Tuanku akan mengabulkan…\">"
  },
  AvgDialog_47173_Content_68 = {
    Text = "Dia menangkup darah suci itu dan menuangkannya ke dalam luka-luka berbentuk simbol di tubuh Inos."
  },
  AvgDialog_47173_Content_69 = {
    Text = "Saat darah dewa menyentuh simbol-simbol itu, seperti ular yang merasakan sumber panas mangsanya, darah itu menjadi hidup dan bergairah."
  },
  AvgDialog_47173_Content_7 = {
    Text = "Waktu kecil, kau ikut aku pergi ke laut untuk menangkap ikan. Setelah capek bermain, saat pulang, kau bersandar padaku seperti ini untuk beristirahat."
  },
  AvgDialog_47173_Content_70 = {
    Text = "Tanpa perlu arahan dari Miriam, darah itu mengikuti panduan sumber panas, meresap masuk ke tubuh Inos melalui luka-luka itu."
  },
  AvgDialog_47173_Content_71 = {
    Text = "Seiring mengalirnya darah dewa, jeritan kesakitan Inos semakin hebat. Luka-luka di tubuhnya sembuh dengan kecepatan yang kasat mata."
  },
  AvgDialog_47173_Content_72 = {
    Text = "Bersamaan dengan itu, wajahnya mulai berubah—kedua matanya membesar dan menonjol keluar, bibirnya menjadi berlendir, dan bentuk tengkoraknya menjadi pipih dan memanjang."
  },
  AvgDialog_47173_Content_73 = {
    Text = "Organ menyerupai insang muncul di lehernya, dan sisik menggantikan rambut, tumbuh dari berbagai bagian tubuhnya."
  },
  AvgDialog_47173_Content_74 = {
    Text = "Dia masih mengeluarkan suara kesakitan, dari lolongan pria dewasa manusia, perlahan berubah menjadi desisan yang membawa aura lembap dan kotor dari dasar laut..."
  },
  AvgDialog_47173_Content_75 = {
    Text = "Aku berhasil, Ayah... Aku tidak mengecewakanmu, kan?"
  },
  AvgDialog_47173_Content_76 = {
    Text = "Desisan itu berhenti. Kesadaran lenyap, makhluk setengah ikan setengah manusia itu menatapnya dengan mata besar pucat yang kosong, memandanginya dengan linglung."
  },
  AvgDialog_47173_Content_77 = {
    Text = "Miriam berjalan ke sisi altar batu, membelai makhluk itu, merasakan bau amis ikan yang pekat di udara, serta sentuhan berlendir di tangannya."
  },
  AvgDialog_47173_Content_78 = {
    Text = "Bau amis dan sentuhan itu dulu membuatnya mual, tetapi sekarang, dia merasa semuanya begitu hangat."
  },
  AvgDialog_47173_Content_79 = {
    Text = "Aku sangat suka ikan. Saat kita bertemu kembali di Kerajaan Dewa, aku akan makan ikan buatanmu setiap hari..."
  },
  AvgDialog_47173_Content_8 = {
    Text = "Begitu kau terbangun, kita sudah sampai di rumah. Ibumu saat itu sedang mengandung adikmu, tapi tetap berjalan jauh untuk menjemput kita."
  },
  AvgDialog_47173_Content_80 = {
    Text = "Tunggulah aku, Ayah."
  },
  AvgDialog_47173_Content_81 = {
    Text = "Dia membungkuk dan mencium wajahnya yang licin dan lembap."
  },
  AvgDialog_47173_Content_83 = {
    Text = "Pintu batu bergeser terbuka. Para pengawal dengan sigap menyingkir membuka jalan."
  },
  AvgDialog_47173_Content_84 = {
    Text = "Langkah kaki yang tenang dan perlahan memasuki ruang doa, berhenti di belakang Pendeta Agung."
  },
  AvgDialog_47173_Content_85 = {
    Text = "Jika kau ingin menjadi manusia ikan dan hidup bersama ayahmu, aku bisa membantumu."
  },
  AvgDialog_47173_Content_86 = {
    Text = "Miriam menggelengkan kepalanya pelan."
  },
  AvgDialog_47173_Content_87 = {
    Text = "Bagimu, hidup dengan akal sehat seharusnya jauh lebih menyakitkan daripada kehilangan akal sehat."
  },
  AvgDialog_47173_Content_88 = {
    Text = "Memang benar, Yang Mulia Pendeta Agung. Tapi aku tidak takut akan penderitaan..."
  },
  AvgDialog_47173_Content_89 = {
    Text = "Dia berlutut di hadapan Pendeta Agung."
  },
  AvgDialog_47173_Content_9 = {
    Text = "Setiap kali aku bilang padanya untuk istirahat saja di rumah, dia tidak pernah mau dengar... Masih ingat, Miriam?"
  },
  AvgDialog_47173_Content_90 = {
    Text = "Tolong beri saya satu kesempatan lagi... Saya akan membuktikan kepada Anda, bahwa saya bisa menjadi pendeta terbaik di Lemuria."
  },
  AvgDialog_47173_Content_91 = {
    Text = "Saya akan bersama Anda, membantu Raja, membawa Kerajaan Ilahi ke Lemuria!"
  },
  AvgDialog_47173_Content_92 = {
    Text = "Kalau begitu, apakah kau bersedia membunuh ayahmu demi Raja?"
  },
  AvgDialog_47173_Content_93 = {
    Text = "Ya, Tuan Pendeta Agung. Saya bersedia. Saya bersedia melakukan apa pun demi Raja."
  },
  AvgDialog_47173_Content_94 = {
    Text = "Ini satu-satunya cara untuk menyelamatkan keluargaku, menyelamatkan Ayah."
  },
  AvgDialog_47173_Content_95 = {
    Text = "Raja adalah ayah, Raja adalah keluargaku... Di Lemuria, ini adalah satu-satunya kebenaran."
  },
  AvgDialog_47173_Content_96 = {
    Text = "Separuh wajah Miryam diwarnai merah oleh darah ayahnya, bagaikan sebuah topeng yang cantik memesona."
  },
  AvgDialog_47173_Content_97 = {
    Text = "Pendeta Agung menatapnya, tatapan tajamnya akhirnya melembut sesaat."
  },
  AvgDialog_47173_Content_98 = {
    Text = "Dia menunjuk ke sampingnya. Di atas meja, sebuah piala dan satu set pakaian sudah disiapkan sejak tadi."
  },
  AvgDialog_47173_Content_99 = {
    Text = "Minumlah darah Basilisk, lafalkan doa, dan bersembahyanglah kepada Raja."
  },
  AvgDialog_47174_Content_1 = {
    Text = "Ritual Pendeta"
  },
  AvgDialog_47174_Content_10 = {
    Text = "Di setiap gereja di berbagai tempat beredar kisah tentangnya. Katanya, ketika dia masih menjadi murid pendeta, saat pertama kali berdoa dia sudah melihat bayangan Sang Raja."
  },
  AvgDialog_47174_Content_11 = {
    Text = "Pendeta lain setelah meminum darah ular, setidaknya seminggu tidak bisa bangun dari tempat tidur, tapi dia sama sekali tidak apa-apa."
  },
  AvgDialog_47174_Content_12 = {
    Text = "Semuda itu, sudah bisa berdiri begitu dekat dengan Raja, melakukan begitu banyak hal untuk Lemuria. Sungguh iri rasanya."
  },
  AvgDialog_47174_Content_13 = {
    Text = "Kalau bisa bertukar posisi dengannya, aku rela mengorbankan apa pun..."
  },
  AvgDialog_47174_Content_14 = {
    Text = "Ah! Lihat, lihat, Wakil Pendeta Agung sudah keluar!"
  },
  AvgDialog_47174_Content_15 = {
    Text = "Nyala lilin di dalam ruangan bergoyang tertiup angin. Sekelompok pengawal keluar berbaris, berjajar di kedua sisi altar persembahan."
  },
  AvgDialog_47174_Content_16 = {
    Text = "Dalam mimpi di atas takhta, Raja mendengarkan wahyu para dewa:"
  },
  AvgDialog_47174_Content_17 = {
    Text = "Badai Lemuria akan mereda. Jurang Lemuria akan lenyap."
  },
  AvgDialog_47174_Content_18 = {
    Text = "Raja akan melindungi rakyatnya yang saleh, dan membawa kerajaan para dewa."
  },
  AvgDialog_47174_Content_19 = {
    Text = "Terpujilah Tuan kita."
  },
  AvgDialog_47174_Content_2 = {
    Text = "Melihat cuaca ini, sepertinya sebentar lagi akan turun hujan deras……cuacanya benar-benar semakin buruk."
  },
  AvgDialog_47174_Content_20 = {
    Text = "Terpujilah Tuan kita!"
  },
  AvgDialog_47174_Content_21 = {
    Text = "Suara itu seolah datang dari tempat yang jauh, lembut namun sangat jelas."
  },
  AvgDialog_47174_Content_22 = {
    Text = "Di bawah tatapan para murid pendeta, sosok berjubah ungu perlahan melangkah keluar dari dalam kuil."
  },
  AvgDialog_47174_Content_23 = {
    Text = "Dia berdiri di atas altar persembahan, matanya menatap menembus kerudung ungu muda, dengan tenang menyapu pandangan ke seluruh hadirin. Dua untai kabut hitam, bagai ular yang belum terbentuk sempurna, melingkar di belakangnya."
  },
  AvgDialog_47174_Content_24 = {
    Text = "Di balik tatapan tenang itu seolah tersimpan kekuatan dahsyat, membuat napas semua orang melambat."
  },
  AvgDialog_47174_Content_25 = {
    Text = "Pendeta Agung sedang tidak enak badan belakangan ini. Ritual transformasi manusia ikan akan diajarkan oleh saya kepada kalian semua."
  },
  AvgDialog_47174_Content_26 = {
    Text = "Bawa masuk sang Perintis."
  },
  AvgDialog_47174_Content_27 = {
    Text = "Di bawah pengawalan para penjaga, sepasang ayah dan anak perempuan dibawa masuk ke dalam ruangan."
  },
  AvgDialog_47174_Content_28 = {
    Text = "Tempat lilin yang lembap, cahaya lilin yang dingin. Semuanya tampak sama seperti tiga tahun lalu."
  },
  AvgDialog_47174_Content_29 = {
    Text = "Sang ayah yang setengah sadar dibaringkan di atas meja batu, putrinya yang baru belasan tahun terus meronta dan menangis meraung dalam cengkeraman para penjaga."
  },
  AvgDialog_47174_Content_3 = {
    Text = "Beberapa tahun terakhir ini bencana alam besar maupun kecil jauh lebih sering dari sebelumnya. Terutama bencana di Lembah Selatan tiga tahun lalu, banyak sekali orang yang tewas……"
  },
  AvgDialog_47174_Content_30 = {
    Text = "Pendeta! Kumohon, kumohon kasihanilah kami..."
  },
  AvgDialog_47174_Content_31 = {
    Text = "Ayahku hanya mencuri sedikit saja... Ibuku meninggal dalam bencana, ayah tidak punya uang, makanya dia terpaksa mencuri..."
  },
  AvgDialog_47174_Content_32 = {
    Text = "Aku bersedia melakukan apa saja, kumohon lepaskan ayahku……"
  },
  AvgDialog_47174_Content_33 = {
    Text = "Bersedia melakukan apa saja…… Kalau begitu, apakah kau bersedia membunuh ayahmu demi sang Raja?"
  },
  AvgDialog_47174_Content_34 = {
    Text = "……Yang Mulia Pendeta?"
  },
  AvgDialog_47174_Content_35 = {
    Text = "Kebingungan di wajah gadis itu terasa sangat familiar bagi Miriam. Setiap orang pasti melewati fase seperti ini, dan tidak ada yang lebih memahaminya selain Miriam."
  },
  AvgDialog_47174_Content_36 = {
    Text = "Ia melangkah maju, dengan lembut menepuk kepala gadis itu."
  },
  AvgDialog_47174_Content_37 = {
    Text = "Jangan takut, wahai pengikut Tuanku."
  },
  AvgDialog_47174_Content_38 = {
    Text = "Kemarilah, ke sini."
  },
  AvgDialog_47174_Content_39 = {
    Text = "Ia menggenggam tangan gadis itu, membimbingnya, membelai pipi ayahnya sendiri."
  },
  AvgDialog_47174_Content_4 = {
    Text = "Memang benar……tapi sejak Wakil Pendeta Agung yang baru dilantik, cukup banyak hal yang telah dilakukan. Renovasi rumah para pengikut, seleksi pendeta berskala besar, dan kegiatan ritual, semuanya dia yang mengurus."
  },
  AvgDialog_47174_Content_40 = {
    Text = "Katakan padaku, kau dan ayahmu, apakah kalian merindukan Kerajaan Dewa?"
  },
  AvgDialog_47174_Content_41 = {
    Text = "Kami…… kami merindukan Kerajaan Dewa……"
  },
  AvgDialog_47174_Content_42 = {
    Text = "Benar, orang Lemuria, sudah seharusnya merindukan Kerajaan Dewa."
  },
  AvgDialog_47174_Content_43 = {
    Text = "Di sana ada segalanya yang kalian inginkan. Tidak ada bencana, tidak ada penyakit…… Kerajaan Dewa, itulah satu-satunya hal yang seharusnya kita kejar."
  },
  AvgDialog_47174_Content_44 = {
    Text = "Ia meletakkan belati persembahan di tangan gadis itu. Kedua tangan itu gemetar tanpa henti, dan Miriam menggenggamnya dengan lembut."
  },
  AvgDialog_47174_Content_45 = {
    Text = "Kalian bukan penjahat. Kalian saling mencintai, dan cinta seperti ini layak dipuji, tidak seharusnya disebut dosa."
  },
  AvgDialog_47174_Content_46 = {
    Text = "Justru karena itulah, kalian layak berada di sini. Layak untuk mempersembahkan kekuatan kalian sendiri, demi turunnya Kerajaan Dewa."
  },
  AvgDialog_47174_Content_47 = {
    Text = "Tidak…… Yang Mulia Pendeta, jika ini bukan dosa, tolong jangan hukum kami…… kumohon, kumohon jangan……"
  },
  AvgDialog_47174_Content_48 = {
    Text = "Hukuman? Tidak, wahai pengikut Tuanku, ini bukan hukuman. Ini adalah anugerah sang Raja, untuk kalian——"
  },
  AvgDialog_47174_Content_49 = {Text = "Jleb——"},
  AvgDialog_47174_Content_5 = {
    Text = "Termasuk upacara transformasi manusia ikan secara terbuka seperti hari ini, sebelumnya tidak pernah ada yang seperti itu."
  },
  AvgDialog_47174_Content_50 = {Text = "Aaaahhh!!!"},
  AvgDialog_47174_Content_51 = {
    Text = "Miriam membawa tangan gadis itu menghujam dengan keras. Mata pisau belati persembahan itu, sepenuhnya tertancap ke dalam dada sang pria."
  },
  AvgDialog_47174_Content_52 = {
    Text = "Darah menyembur keluar, memenuhi wajah gadis itu. Jeritan kesakitan sang ayah dan tangisan memilukan sang putri, bergema di seluruh ruangan."
  },
  AvgDialog_47174_Content_53 = {
    Text = "Tenang, wahai pengikut yang setia. Setelah ritual ayahmu selesai, akan tiba giliranmu."
  },
  AvgDialog_47174_Content_54 = {
    Text = "Kau masih bisa hidup bersama ayahmu. Bayaran dari kesadaran itu, biar aku yang menanggungnya untuk kalian."
  },
  AvgDialog_47174_Content_55 = {
    Text = "Sambil berkata demikian, ia memandu belati itu menyusuri tubuh sang pria. Selama beberapa tahun ini, ritual seperti ini sudah tak terhitung berapa kali ia lakukan."
  },
  AvgDialog_47174_Content_56 = {
    Text = "Rasa kebahagiaan yang luar biasa menyelimutinya. Darah yang bermuncratan dan wajah-wajah yang terdistorsi adalah tangga menuju Kerajaan Ilahi. Sebagai orang Lemuria, sudah seharusnya menerimanya dengan penuh kebahagiaan."
  },
  AvgDialog_47174_Content_57 = {
    Text = "Seperti diriku, percayalah pada Sang Raja. Seperti diriku, bersabarlah menunggu. Segera, kau dan keluargamu akan bertemu kembali di Kerajaan Ilahi."
  },
  AvgDialog_47174_Content_59 = {Text = "Byur—"},
  AvgDialog_47174_Content_6 = {
    Text = "Kudengar, Wakil Pendeta Agung itu berasal dari Lembah Selatan?"
  },
  AvgDialog_47174_Content_60 = {
    Text = "Bagi para murid pendeta, ritual ini mungkin terasa agak panjang. Tapi bagi Miriam, ritual ini segera berakhir."
  },
  AvgDialog_47174_Content_61 = {
    Text = "Dua makhluk setengah manusia setengah ikan dilemparkan ke dalam kolam. Miriam berdiri di tepi kolam, membungkuk, dan dengan lembut membelai kulit mereka yang licin."
  },
  AvgDialog_47174_Content_62 = {
    Text = "Bau amis yang pekat merasuk ke dalam paru-parunya, air kolam yang kotor membasahi gaunnya, namun ia sama sekali tak peduli."
  },
  AvgDialog_47174_Content_63 = {
    Text = "Perubahan manusia-ikan ini jauh lebih sempurna dari sebelumnya. Keahlian Anda semakin mahir, Wakil Pendeta Agung."
  },
  AvgDialog_47174_Content_64 = {
    Text = "Deborah, sudah berapa kali kubilang, jangan panggil aku Wakil Pendeta Agung."
  },
  AvgDialog_47174_Content_65 = {
    Text = "Ia berbalik dan tersenyum ramah kepada satu-satunya sahabatnya ini."
  },
  AvgDialog_47174_Content_66 = {
    Text = "Waktu berlalu begitu cepat. Aku masih ingat wajahmu yang ketakutan saat pertama kali melihat para Pelopor ini. Sekarang kau sudah berubah menjadi sosok penting di Lemuria~"
  },
  AvgDialog_47174_Content_67 = {
    Text = "Pendeta Agung yang lama kesehatannya kurang baik. Saat Raja baru naik takhta, kemungkinan besar kau akan menjadi Pendeta Agung kita!"
  },
  AvgDialog_47174_Content_68 = {
    Text = "Semuanya sama saja, Deborah. Guru akan membimbing kita bersama, mempersembahkan segalanya kepada Sang Raja. Segera, Kerajaan Ilahi akan turun."
  },
  AvgDialog_47174_Content_69 = {
    Text = "Waktu penobatan Raja baru sudah semakin dekat, kita masih perlu mempersiapkan dengan saksama. Aku pergi ke ruang doa dulu…"
  },
  AvgDialog_47174_Content_7 = {
    Text = "Benar! Tiga tahun lalu masih seorang murid pendeta, tapi dalam waktu kurang dari setahun, dia sudah menjadi Wakil Pendeta Agung termuda di Lemuria……"
  },
  AvgDialog_47174_Content_70 = {Text = "Miriam…"},
  AvgDialog_47174_Content_71 = {
    Text = "Ia menunjuk ke tubuh Miriam. Miriam menunduk dan baru menyadari bahwa seluruh tubuhnya berlumuran darah."
  },
  AvgDialog_47174_Content_72 = {
    Text = "Ah, maaf… Baru selesai ritual, sampai lupa soal ini…"
  },
  AvgDialog_47174_Content_73 = {
    Text = "Miriam, kau baik-baik saja?"
  },
  AvgDialog_47174_Content_74 = {
    Text = "Aku? Aku baik-baik saja... Kenapa bertanya begitu?"
  },
  AvgDialog_47174_Content_75 = {
    Text = "Aku juga tidak tahu. Hanya saja setelah kejadian itu, rasanya kamu seperti berubah menjadi orang yang berbeda..."
  },
  AvgDialog_47174_Content_76 = {
    Text = "Aku tidak berubah, hanya bertumbuh. Semua orang pasti akan bertumbuh."
  },
  AvgDialog_47174_Content_77 = {
    Text = "Deborah, masih ingat keinginan kita? Dulu kamu pernah bilang padaku, kita akan menjadi pendeta bersama, membantu Raja, dan membawa Kerajaan Tuhan ke Lemuria."
  },
  AvgDialog_47174_Content_78 = {
    Text = "Tentu saja ingat. Waktu itu, kamu masih seorang murid yang bahkan tidak bisa berdoa dengan benar~"
  },
  AvgDialog_47174_Content_79 = {
    Text = "Lihat, janji-janji yang dulu, semuanya sudah kutepati. Seharusnya kamu senang untukku, bukan?"
  },
  AvgDialog_47174_Content_8 = {
    Text = "Sekarang kondisi kesehatan Pendeta Agung semakin memburuk, sebagian besar urusan sudah diserahkan kepadanya. Mungkin saja, dia akan segera menjadi Pendeta Agung termuda di Lemuria."
  },
  AvgDialog_47174_Content_80 = {
    Text = "Aku selalu merasa senang untukmu setiap hari! Hanya saja kadang-kadang melihat keadaanmu, rasanya kamu tampak sangat lelah. Aku agak khawatir..."
  },
  AvgDialog_47174_Content_81 = {
    Text = "Tenang saja, Deborah, aku baik-baik saja. Dari kecil hingga sekarang, selama bertahun-tahun, aku tidak pernah merasa sebaik ini."
  },
  AvgDialog_47174_Content_82 = {
    Text = "Dia menepuk bahu Deborah, tersenyum padanya, lalu berjalan menuju tempat tinggalnya."
  },
  AvgDialog_47174_Content_83 = {
    Text = "Upacara penobatan Raja Baru membutuhkan banyak persiapan, dan waktu-waktu yang sibuk akan segera datang."
  },
  AvgDialog_47174_Content_84 = {
    Text = "Di perjalanan, dia memandang ke arah istana Raja Baru yang tidak berhak ia masuki."
  },
  AvgDialog_47174_Content_85 = {
    Text = "Tentang legenda Raja Baru, rakyat Lemuria kurang lebih sudah pernah mendengarnya."
  },
  AvgDialog_47174_Content_86 = {
    Text = "Dengan penobatan Raja Baru, saat Lemuria menjadi Kerajaan Tuhan semakin dekat. Dia tersenyum, dan dengan santai menyerahkan kain sutra yang digunakan untuk menyeka darah kepada pengawal."
  },
  AvgDialog_47174_Content_9 = {
    Text = "Dia baru berusia dua puluhan tahun sekarang, sungguh luar biasa……"
  },
  AvgDialog_47175_Content_1 = {Text = "Raja Baru"},
  AvgDialog_47175_Content_11 = {
    Text = "Di luar Kuil Lemuria."
  },
  AvgDialog_47175_Content_12 = {
    Text = "Raja Baru! Tuanku!"
  },
  AvgDialog_47175_Content_13 = {
    Text = "Terpujilah Tuanku! Sambut Kerajaan Dewa!"
  },
  AvgDialog_47175_Content_14 = {
    Text = "Kuil Lemuria yang megah menjulang tinggi, berdiri kokoh bagai puncak gunung di tepi pantai yang luas."
  },
  AvgDialog_47175_Content_15 = {
    Text = "Para pengikut berdatangan bagai air bah, berdesakan di alun-alun di luar kuil, memandangi altar agung yang berpendar dengan cahaya temaram."
  },
  AvgDialog_47175_Content_16 = {
    Text = "Orang-orang berjinjit, menatap melewati lautan manusia dan barisan pengawal, berusaha keras mengintip ke dalam altar, ingin melihat sekilas sosok raja baru."
  },
  AvgDialog_47175_Content_17 = {
    Text = "Di belakang altar, pintu batu megah kuil yang jarang terbuka kini menganga di hadapan para jemaat. Angin yang membawa aura kedalaman laut berhembus dari dalam kuil, tirai-tirai semi-transparan melayang perlahan tertiup angin."
  },
  AvgDialog_47175_Content_18 = {
    Text = "Miriam berdiri di depan barisan pendeta di luar altar, kedua tangannya tergenggam erat, menatap tak bergeming ke balik tirai."
  },
  AvgDialog_47175_Content_19 = {
    Text = "Sebuah siluet samar bersandar di atas takhta di balik tirai, tampak sedang tertidur. Mahkota yang menjadi lambang tunggal seorang raja itu membuat napas Miriam tanpa sadar menjadi tak beraturan."
  },
  AvgDialog_47175_Content_2 = {
    Text = "Dong… dong…"
  },
  AvgDialog_47175_Content_20 = {
    Text = "BLARR——"
  },
  AvgDialog_47175_Content_21 = {Text = "Ah!——"},
  AvgDialog_47175_Content_22 = {
    Text = "Gemuruh petir yang tiba-tiba menggelegar membuat para pengikut terhenti. Ketakutan akan bencana langit mengalir dalam darah mereka, dan mereka mendongak dengan panik."
  },
  AvgDialog_47175_Content_23 = {
    Text = "Langit yang semula tertutup awan menjadi semakin gelap. Kilat menyambar dan petir menggelegar, lautan meraung, membangkitkan gelombang-gelombang yang melambangkan bencana dan kematian."
  },
  AvgDialog_47175_Content_24 = {
    Text = "Bencana langit... Ini bencana langit! Bencana langit akan datang!"
  },
  AvgDialog_47175_Content_25 = {
    Text = "Kalau kuil terkena bencana langit, maka kita..."
  },
  AvgDialog_47175_Content_26 = {
    Text = "Kenapa harus di saat seperti ini... Di hari penobatan raja baru..."
  },
  AvgDialog_47175_Content_27 = {
    Text = "Jangan-jangan... raja baru ini..."
  },
  AvgDialog_47175_Content_28 = {
    Text = "Di bawah pertanda buruk ini, para pengikut yang berdesakan di sekitar kuil menjadi gelisah. Keresahan menyebar di antara kerumunan."
  },
  AvgDialog_47175_Content_29 = {
    Text = "Dari balik tirai, terdengar helaan napas pelan. Sosok mungil bangkit berdiri dari atas takhta."
  },
  AvgDialog_47175_Content_3 = {
    Text = "Dentang lonceng yang rendah dan panjang, bagaikan titah suci, bergema dari kuil Lemuria."
  },
  AvgDialog_47175_Content_30 = {
    Text = "Bencana langit tidak akan turun."
  },
  AvgDialog_47175_Content_31 = {
    Text = "Di dalam mimpi, aku menerima wahyu ilahi:"
  },
  AvgDialog_47175_Content_32 = {
    Text = "Pada hari ini, Lemuria akan menyambut raja baru."
  },
  AvgDialog_47175_Content_33 = {
    Text = "Pada hari ini, segala bencana alam akan menyingkir di hadapanku."
  },
  AvgDialog_47175_Content_34 = {
    Text = "Suara muda itu sangat tenang, namun bagaikan lonceng raksasa, terdengar begitu jelas di telinga setiap orang."
  },
  AvgDialog_47175_Content_35 = {
    Text = "Itu... Raja Baru? Itu suara Raja Baru!"
  },
  AvgDialog_47175_Content_36 = {
    Text = "Lihat! Lihat langit!"
  },
  AvgDialog_47175_Content_37 = {
    Text = "Hampir bersamaan dengan kata-kata Tulu terucap, awan gelap di langit mulai menghilang dengan kecepatan yang terlihat oleh mata telanjang."
  },
  AvgDialog_47175_Content_38 = {
    Text = "Raungan lautan mulai mereda, sinar matahari yang cerah menyinari wajah setiap umat."
  },
  AvgDialog_47175_Content_39 = {
    Text = "Mukjizat... Ini mukjizat!"
  },
  AvgDialog_47175_Content_4 = {
    Text = "Dentang lonceng merambat ke pesisir, ke pegunungan, ke kota dan pedesaan."
  },
  AvgDialog_47175_Content_40 = {
    Text = "Di atas tirai di belakang altar suci, tersinari cahaya matahari, tampak sebuah siluet yang jelas."
  },
  AvgDialog_47175_Content_41 = {
    Text = "Sebuah tubuh mungil datang ke tepi tirai, perlahan mengangkat lengannya."
  },
  AvgDialog_47175_Content_42 = {Text = "Grrmm..."},
  AvgDialog_47175_Content_43 = {
    Text = "Seiring gerakannya, beberapa tentakel raksasa menembus lautan, daratan, dan pegunungan, muncul di hadapan semua orang."
  },
  AvgDialog_47175_Content_44 = {
    Text = "Cahaya samar-samar terpancar dari tentakel-tentakel itu. Cahaya itu perlahan menyatu, terjalin menjadi sebuah lukisan megah di hadapan seluruh umat."
  },
  AvgDialog_47175_Content_45 = {
    Text = "I-ini... Ini adalah..."
  },
  AvgDialog_47175_Content_46 = {
    Text = "Miriam membelalakkan matanya, memandangi semua yang ada di hadapannya."
  },
  AvgDialog_47175_Content_47 = {
    Text = "Dunia di matanya telah berubah. Pegunungan tak lagi hancur, lautan tak lagi bergejolak. Ia melihat sinar matahari turun, menyinari sebuah negeri yang damai dan tenteram."
  },
  AvgDialog_47175_Content_48 = {Text = "Kakak!"},
  AvgDialog_47175_Content_49 = {
    Text = "Suara itu masuk ke telinga Miriam. Ia mendongak dengan terkejut, melihat sosok yang familiar di hadapannya."
  },
  AvgDialog_47175_Content_5 = {
    Text = "Raja Baru Lemuria… Raja Baru akan segera dinobatkan!!"
  },
  AvgDialog_47175_Content_50 = {
    Text = "Sa... Sara? Bagaimana bisa kau..."
  },
  AvgDialog_47175_Content_51 = {
    Text = "Kakak, sudah selama ini berlalu, kenapa Kakak tidak berubah sama sekali? Lihat aku, aku sudah bertambah tinggi!"
  },
  AvgDialog_47175_Content_52 = {
    Text = "Miriam... kamu di kuil, apakah semuanya baik-baik saja?"
  },
  AvgDialog_47175_Content_53 = {
    Text = "Sudah lama tidak bertemu denganmu... Ibu merindukanmu."
  },
  AvgDialog_47175_Content_54 = {
    Text = "Ibu... Ibu... Anda..."
  },
  AvgDialog_47175_Content_55 = {
    Text = "Miriam menatap kosong dua orang yang berjalan ke arahnya. Suara langkah kaki terdengar dari belakang. Perlahan ia berbalik."
  },
  AvgDialog_47175_Content_56 = {
    Text = "Ah, pendeta keluarga kita sudah pulang!"
  },
  AvgDialog_47175_Content_57 = {Text = "Ayah..."},
  AvgDialog_47175_Content_58 = {
    Text = "Air mata mengaburkan pandangannya. Tenggorokannya serak, tak mampu berkata-kata."
  },
  AvgDialog_47175_Content_59 = {
    Text = "Sebuah tangan diletakkan di kepalanya, mengelusnya dengan lembut."
  },
  AvgDialog_47175_Content_6 = {
    Text = "Seruan-seruan mengiringi dentang lonceng, sampai ke telinga setiap rakyat kerajaan besar ini."
  },
  AvgDialog_47175_Content_60 = {
    Text = "Jangan bersedih, Miriam. Kamu berhasil... kamu membantu Sang Raja membawa Kerajaan Tuhan!"
  },
  AvgDialog_47175_Content_61 = {
    Text = "Sekarang, kita tidak perlu takut akan apa pun lagi. Keluarga kita akan hidup bersama dengan baik di Kerajaan Tuhan. Selamanya dan selamanya..."
  },
  AvgDialog_47175_Content_62 = {
    Text = "Aku... aku berhasil? Aku berhasil..."
  },
  AvgDialog_47175_Content_63 = {
    Text = "Adiknya berlari ke sisinya, memeluknya. Ibunya datang ke sisinya, memeluknya. Ayahnya datang ke sisinya, memeluknya."
  },
  AvgDialog_47175_Content_64 = {
    Text = "Pelukan. Pelukan di mana tubuh saling bersentuhan. Pelukan yang membawa kehangatan. Pelukan hanya untuk perjumpaan, bukan perpisahan. Pelukan tanpa seorang pun yang absen."
  },
  AvgDialog_47175_Content_65 = {
    Text = "Pelukan, itulah segalanya yang ia cari selama ini."
  },
  AvgDialog_47175_Content_66 = {
    Text = "Air mata mengalir deras, meluncur di wajah Miriam. Ia mendongakkan kepalanya."
  },
  AvgDialog_47175_Content_67 = {
    Text = "Pelukan itu lenyap. Cahaya berubah, ia kembali ke depan kuil. Di hadapannya, ada tak terhitung umat yang sama-sama berlinang air mata."
  },
  AvgDialog_47175_Content_68 = {
    Text = "Pemandangan agung Kerajaan Tuhan, hasrat terdalam di hati setiap orang, terhampar begitu nyata di hadapan para umat."
  },
  AvgDialog_47175_Content_69 = {
    Text = "Aku melihatnya... aku melihatnya, Tuhanku!"
  },
  AvgDialog_47175_Content_7 = {
    Text = "Jutaan rakyat Lemuria membanjiri jalanan, memenuhi setiap jalan dan alun-alun, berteriak dengan penuh semangat dan penuh harapan."
  },
  AvgDialog_47175_Content_70 = {
    Text = "Inilah Kerajaan Tuhan... inilah Kerajaan Tuhan yang akan Engkau bawa untuk kami!"
  },
  AvgDialog_47175_Content_71 = {
    Text = "Tuanku…… Aku melihatnya!"
  },
  AvgDialog_47175_Content_72 = {
    Text = "Mirriam bergumam mengulang kata-kata itu, lalu berlutut di hadapan raja baru di balik tirai."
  },
  AvgDialog_47175_Content_73 = {
    Text = "Tanpa perlu siapa pun mengatur, di belakangnya, tak terhitung umat ikut berlutut dan memberi hormat."
  },
  AvgDialog_47175_Content_74 = {
    Text = "Melalui mata yang berkaca-kaca, tak terhitung pasang mata menatap penuh hasrat ke altar suci, menatap ke balik tirai, pada siluet mungil sang raja baru."
  },
  AvgDialog_47175_Content_75 = {
    Text = "Inilah kemegahan Kerajaan Ilahi. Inilah keagungan Tuan kita."
  },
  AvgDialog_47175_Content_76 = {
    Text = "Aku sudah tua. Atas titah Tuan kita, Mirriam akan menggantikan jabatan Pendeta Agung, mendampingi raja baru Lemuria."
  },
  AvgDialog_47175_Content_77 = {Text = "Tuanku."},
  AvgDialog_47175_Content_78 = {
    Text = "Pendeta Agung menyingkir ke samping dan merendahkan suaranya."
  },
  AvgDialog_47175_Content_79 = {
    Text = "Tuanku, Lemuria telah menyaksikan keagungan Anda. Silakan lanjutkan sabda Anda. Bawalah harapan bagi Lemuria."
  },
  AvgDialog_47175_Content_8 = {
    Text = "Raja tua mungkin telah turun takhta, atau mungkin telah wafat. Rakyat Lemuria tidak tahu, dan tidak peduli."
  },
  AvgDialog_47175_Content_80 = {
    Text = "Ia membuat gestur mempersilakan, lalu membungkuk memberi hormat kepada Thulu."
  },
  AvgDialog_47175_Content_81 = {
    Text = "Sang raja baru yang masih belia terdiam sejenak, lalu melangkah maju."
  },
  AvgDialog_47175_Content_82 = {
    Text = "Kami, wakil para dewa, Raja Lemuria."
  },
  AvgDialog_47175_Content_83 = {
    Text = "Kami…… akan membawa Kerajaan Ilahi bagi Lemuria."
  },
  AvgDialog_47175_Content_84 = {
    Text = "Para dewa…… Para dewa memberkati Lemuria!"
  },
  AvgDialog_47175_Content_85 = {
    Text = "Tuanku! Terpujilah Tuanku!"
  },
  AvgDialog_47175_Content_86 = {
    Text = "Terpujilah Tuanku!!"
  },
  AvgDialog_47175_Content_87 = {
    Text = "Ribuan umat berlutut di tanah, sorak-sorai bagai gelombang samudera menggema di setiap penjuru kerajaan."
  },
  AvgDialog_47175_Content_88 = {
    Text = "Thulu berbalik dengan lelah."
  },
  AvgDialog_47175_Content_89 = {
    Text = "Apa yang Lemuria harapkan untuk kami ucapkan, telah kami ucapkan."
  },
  AvgDialog_47175_Content_9 = {
    Text = "Dalam tahun-tahun panjang berjuang melawan bencana langit, mereka telah belajar untuk tidak meratapi hari kemarin. Di mata mereka, hanya ada hari esok yang bersinar dengan cahaya kerajaan dewa, yang dibawa oleh raja baru."
  },
  AvgDialog_47175_Content_90 = {
    Text = "Kami lelah. Tak perlu mengikuti."
  },
  AvgDialog_47175_Content_91 = {
    Text = "Dia melambaikan tangan, menghentikan pengawal dan pendeta agung yang hendak mengikutinya,"
  },
  AvgDialog_47175_Content_92 = {
    Text = "Di tengah seruan fanatik para pengikut, raja muda yang baru dinobatkan itu terdiam, berjalan seorang diri menuju kuil yang kosong."
  },
  AvgDialog_47176_Content_1 = {Text = "Ramalan"},
  AvgDialog_47176_Content_10 = {
    Text = "Rumah hampir runtuh seluruhnya, puing-puing batu mengurungnya di sudut sempit ini. Hujan deras merembes melalui celah-celah di antara batu, menghantam tubuhnya."
  },
  AvgDialog_47176_Content_100 = {
    Text = "\"Tapi, tapi ayahku adalah penganut yang taat, Sang Raja menyayangi umat-Nya, Dia tidak akan menyuruhku...\""
  },
  AvgDialog_47176_Content_101 = {
    Text = "\"Kau seharusnya tidak menjadi pendeta. Kau seharusnya tidak dilahirkan di Lemuria. Kau seharusnya diasingkan, atau dihukum mati.\""
  },
  AvgDialog_47176_Content_102 = {
    Text = "\"Miriam, bukan itu maksud Pendeta Agung...\""
  },
  AvgDialog_47176_Content_103 = {
    Text = "\"Pendeta Agung! Mohon maafkan Miriam, dia hanya kurang pandai mengungkapkan kata-kata... Kami bersedia mempersembahkan segalanya untuk Sang Raja! ...\""
  },
  AvgDialog_47176_Content_104 = {
    Text = "\"Para dewa membimbingku datang ke sini. Inilah takdir yang ditunjukkan oleh bintang-bintang... Takdir, heh.\""
  },
  AvgDialog_47176_Content_105 = {
    Text = "Pendeta Agung tidak menghiraukan perkataan Inos dan Miriam. Dia menghela napas panjang, lalu berjalan kembali ke kedalaman kuil."
  },
  AvgDialog_47176_Content_106 = {
    Text = "Tak lama kemudian, seorang pendeta berlari menghampiri, langkah kakinya bergema di aula yang sunyi."
  },
  AvgDialog_47176_Content_107 = {
    Text = "Dia berhenti di hadapan Miriam, tersenyum kepadanya, dan menyerahkan sebuah lencana."
  },
  AvgDialog_47176_Content_108 = {
    Text = "\"Tujuh hari lagi, bawalah ini ke kuil untuk mengikuti pelatihan.\""
  },
  AvgDialog_47176_Content_109 = {
    Text = "\"Selamat, Miriam. Kau sekarang adalah murid pendeta Lemuria.\""
  },
  AvgDialog_47176_Content_11 = {
    Text = "Beberapa bongkahan batu besar menggantung di atas kepalanya, ditopang dengan susah payah oleh sebuah pilar batu tipis yang penuh retakan, bergetar dalam hujan deras."
  },
  AvgDialog_47176_Content_110 = {Text = "\"!!!\""},
  AvgDialog_47176_Content_111 = {
    Text = "\"Kakak terpilih! Kakak terpilih!\""
  },
  AvgDialog_47176_Content_112 = {
    Text = "Sara melompat kegirangan, sementara Inos menghadap ke arah patung, kedua tangannya yang tergenggam erat gemetar pelan di depan dadanya."
  },
  AvgDialog_47176_Content_113 = {
    Text = "\"Terima kasih, Yang Mulia Pendeta, terima kasih!\""
  },
  AvgDialog_47176_Content_114 = {
    Text = "\"Tuan kita mendengar suara kita... Syukur kepada Tuan kita... Syukur...\""
  },
  AvgDialog_47176_Content_115 = {
    Text = "\"Paya, kau dengar itu? Anak kita menjadi murid pendeta!\""
  },
  AvgDialog_47176_Content_116 = {
    Text = "\"Kalau kau bisa melihatnya, pasti kau akan sangat bahagia, Paya...\""
  },
  AvgDialog_47176_Content_117 = {
    Text = "Miriam terpaku di tempat, belum memahami apa yang baru saja terjadi."
  },
  AvgDialog_47176_Content_118 = {
    Text = "Adiknya bersorak tanpa sungkan, ayahnya diam-diam menyeka air mata, dan dari kerumunan di sekitar terdengar ucapan selamat yang tulus maupun iri."
  },
  AvgDialog_47176_Content_119 = {
    Text = "Sebuah lencana gelap berukiran tentakel dan badai terbaring diam di telapak tangannya, tak terpengaruh oleh segala pemandangan dan suara di sekitarnya, bagaikan sebuah ramalan yang dingin."
  },
  AvgDialog_47176_Content_12 = {
    Text = "\"Yang Mu-Mulia, Raja......\""
  },
  AvgDialog_47176_Content_120 = {
    Text = "\"Kau suka makan ikan, setelah pulang nanti, aku akan memasakkan semua hidangan kesukaanmu!\""
  },
  AvgDialog_47176_Content_121 = {
    Text = "\"Aku harus memberitahu semua orang, menyampaikan kabar baik ini kepada mereka!\""
  },
  AvgDialog_47176_Content_122 = {
    Text = "\"Miriam kami akan menjadi pendeta Lemuria!\""
  },
  AvgDialog_47176_Content_123 = {
    Text = "\"Masih murid saja kok...\""
  },
  AvgDialog_47176_Content_124 = {
    Text = "\"Pendeta Agung sendiri sudah memberikan perhatian khusus padamu, itu artinya bakat Miriam kita sungguh luar biasa! Pasti tidak akan ada masalah!\""
  },
  AvgDialog_47176_Content_125 = {
    Text = "Miriam tidak mengerti maksud Pendeta Agung, juga tidak mengerti mengapa dirinya mendapatkan kesempatan ini. Ia memandang ayah dan adiknya. Sudah lama sekali ia tidak melihat ekspresi sebahagia itu di wajah mereka."
  },
  AvgDialog_47176_Content_126 = {
    Text = "Miriam membelai lencana itu, senyum perlahan muncul di wajahnya."
  },
  AvgDialog_47176_Content_127 = {
    Text = "Akhirnya ia pun bisa seperti ayahnya, membawa senyuman bagi keluarganya. Kalau begitu, biarlah senyuman ini terus berlanjut. Pikirnya."
  },
  AvgDialog_47176_Content_13 = {
    Text = "\"Kumohon...... selamatkanlah pengikut setia-Mu......\""
  },
  AvgDialog_47176_Content_14 = {
    Text = "Dia menatap reruntuhan batu yang nyaris jatuh di atasnya, merapatkan tubuhnya sejauh mungkin ke sudut, kedua tangan dengan jari-jari saling bertautan, terkatup di depan dada sambil berdoa."
  },
  AvgDialog_47176_Content_15 = {
    Text = "Hujan badai. Petir menggelegar. Gempa bumi. Tsunami."
  },
  AvgDialog_47176_Content_16 = {
    Text = "Rakyat Lemuria hidup berdampingan dengan bencana alam, dan doa adalah hal pertama yang mereka pelajari."
  },
  AvgDialog_47176_Content_17 = {
    Text = "\"Engkau adalah wakil para dewa, kepercayaan rakyat Lemuria...... Aku akan mempersembahkan segalanya untukmu......\""
  },
  AvgDialog_47176_Content_18 = {
    Text = "\"Kumohon, tolonglah aku...... selamatkan aku......\""
  },
  AvgDialog_47176_Content_19 = {
    Text = "Ayah berkata, para dewa dan Raja akan menyelamatkan rakyat Lemuria. Dia tidak tahu apa itu dewa, apa itu raja. Dia memanggil-manggil berulang kali."
  },
  AvgDialog_47176_Content_2 = {
    Text = "\"Dalam mimpi singgasana, Sang Raja mendengarkan wahyu para dewa:\""
  },
  AvgDialog_47176_Content_20 = {
    Text = "Para dewa masih belum muncul, para dewa tidak pernah muncul di hadapannya. Namun selain berdoa, dia tidak bisa melakukan apa-apa."
  },
  AvgDialog_47176_Content_21 = {
    Text = "Retakan pada pilar batu semakin jelas terlihat. Pilar itu sudah tidak mampu lagi menopang beban reruntuhan di atasnya."
  },
  AvgDialog_47176_Content_22 = {
    Text = "\"Tuhanku...... kumohon selamatkan aku......\""
  },
  AvgDialog_47176_Content_23 = {
    Text = "Miryam teringat tubuh ibunya yang kotor dan compang-camping saat digali keluar dari bawah reruntuhan."
  },
  AvgDialog_47176_Content_24 = {
    Text = "Di saat-saat terakhirnya, apakah ibu juga merasakan hal yang sama seperti dirinya sekarang — kedinginan, ketakutan, dan keputusasaan?"
  },
  AvgDialog_47176_Content_25 = {
    Text = "Air mata bercampur tak berdaya dengan air hujan. Suaranya semakin lemah, bergetar bersama tubuhnya......"
  },
  AvgDialog_47176_Content_26 = {
    Text = "BLARR——"
  },
  AvgDialog_47176_Content_27 = {
    Text = "\"Aaaaah!!!......\""
  },
  AvgDialog_47176_Content_28 = {Text = "\"Miryam!\""},
  AvgDialog_47176_Content_29 = {
    Text = "Pilar batu itu patah. Sesaat sebelum bongkahan batu raksasa itu menghantam ke bawah, sosok yang familiar melesat mendekat dan menarik Miryam ke dalam pelukannya."
  },
  AvgDialog_47176_Content_3 = {
    Text = "\"Badai Lemuria akan mereda. Jurang Lemuria akan lenyap.\""
  },
  AvgDialog_47176_Content_30 = {
    Text = "\"A-Ayah!......\""
  },
  AvgDialog_47176_Content_31 = {
    Text = "Miryam perlahan menurunkan lengan yang secara refleks menutupi matanya."
  },
  AvgDialog_47176_Content_32 = {
    Text = "\"Huwaaa......\""
  },
  AvgDialog_47176_Content_33 = {
    Text = "Dia langsung memeluk sosok yang familiar itu."
  },
  AvgDialog_47176_Content_34 = {
    Text = "\"Jangan takut, Miriam. Jangan takut. Aku di sini.\""
  },
  AvgDialog_47176_Content_35 = {
    Text = "\"Ssshh… hati-hati, Nak… jangan sentuh bahuku…\""
  },
  AvgDialog_47176_Content_36 = {
    Text = "\"Anda berdarah?!\""
  },
  AvgDialog_47176_Content_37 = {
    Text = "Batu-batu berjatuhan, pecahan batu beterbangan. Pria itu berdiri menghalangi antara batu dan gadis kecil itu. Kulitnya yang menghitam karena bertahun-tahun terpapar angin dan matahari kini dipenuhi luka dari pecahan batu dan serpihan genteng."
  },
  AvgDialog_47176_Content_38 = {
    Text = "Dengan gila-gilaan dia menggali batu dan tanah, hingga kedua tangan kasarnya pun berlumuran darah."
  },
  AvgDialog_47176_Content_39 = {
    Text = "Air hujan membasuh tubuh pria itu, membawa darah segar yang mewarnai reruntuhan di tanah menjadi merah tua."
  },
  AvgDialog_47176_Content_4 = {
    Text = "\"Sang Raja akan melindungi rakyatnya yang baik hati, membawa kerajaan Tuhan.\nAir yang lembut, membasahi setiap jengkal rerumputan dan pepohonan……\""
  },
  AvgDialog_47176_Content_40 = {
    Text = "\"Ayah… aku… akulah yang membuat Ayah terluka…\""
  },
  AvgDialog_47176_Content_41 = {
    Text = "Sebuah tangan yang kasar dan lebar diletakkan di atas kepalanya, mengelusnya dengan lembut."
  },
  AvgDialog_47176_Content_42 = {
    Text = "\"Dasar anak bodoh, bicara apa kamu. Selama kamu baik-baik saja, sebanyak apa pun luka ini tidak ada artinya.\""
  },
  AvgDialog_47176_Content_43 = {
    Text = "\"Syukurlah, syukurlah… akhirnya sempat…\""
  },
  AvgDialog_47176_Content_44 = {
    Text = "\"Terima kasih, Tuanku! Telah melindungi keluargaku…\""
  },
  AvgDialog_47176_Content_45 = {
    Text = "\"Yang melindungiku, jelas-jelas adalah Ayah…\""
  },
  AvgDialog_47176_Content_46 = {
    Text = "\"Orang-orang Lemuria bisa bertahan hidup, semua berkat pertolongan Sang Raja. Hanya dengan beriman setia kepada Sang Raja, kita bisa melindungi keluarga kita. Kamu masih kecil sekarang, ketika kamu besar nanti, kamu akan mengerti.\""
  },
  AvgDialog_47176_Content_47 = {
    Text = "Inos tersenyum dan menepuk kepalanya. Dia membawa Miriam bersamanya, menghadap ke arah kuil, dan memberi hormat dengan khidmat."
  },
  AvgDialog_47176_Content_48 = {
    Text = "\"Ayo, ucapkan bersamaku.\nSegala yang tersesat, Tuanku akan menuntun…\""
  },
  AvgDialog_47176_Content_5 = {
    Text = "BLARR——"
  },
  AvgDialog_47176_Content_50 = {
    Text = "…Segala yang diharapkan, Tuanku akan mengabulkan…"
  },
  AvgDialog_47176_Content_51 = {Text = "\"Miriam?\""},
  AvgDialog_47176_Content_52 = {
    Text = "…Segala yang beriman, Tuanku akan memberkati…"
  },
  AvgDialog_47176_Content_53 = {
    Text = "\"Miriam? Sudah tertidur?\""
  },
  AvgDialog_47176_Content_54 = {
    Text = "\"Ah, Ayah! Maaf... Tadi aku sedang memikirkan beberapa hal dari masa lalu...\""
  },
  AvgDialog_47176_Content_55 = {
    Text = "\"Miriam, kau yakin ingin menjadi murid pendeta?\""
  },
  AvgDialog_47176_Content_56 = {
    Text = "\"Ya, Ayah.\""
  },
  AvgDialog_47176_Content_57 = {
    Text = "\"Syukurlah, syukurlah. Melihatmu yang tampak melamun, dan biasanya juga tidak terlalu suka membicarakan hal ini, Ayah kira kau tidak menyukainya...\""
  },
  AvgDialog_47176_Content_58 = {
    Text = "\"Waktu kau berinisiatif bilang ingin ikut seleksi murid pendeta, Ayah benar-benar senang sekali. Anak perempuan kita sudah dewasa...\""
  },
  AvgDialog_47176_Content_59 = {
    Text = "\"Karena sudah datang, mari kita dengarkan baik-baik perkataan pendeta. Sang Raja adalah orang yang paling dekat dengan dewa, Beliau bisa melihat segalanya. Orang yang tidak taat, tidak akan bisa mendapatkan berkat Sang Raja.\""
  },
  AvgDialog_47176_Content_6 = {
    Text = "\"Ah!……\""
  },
  AvgDialog_47176_Content_60 = {
    Text = "\"Hmm... Aku mengerti, Ayah.\""
  },
  AvgDialog_47176_Content_61 = {
    Text = "Yang selama ini memberkatinya bukanlah Sang Raja. Miriam berpikir demikian, namun tidak mengatakannya."
  },
  AvgDialog_47176_Content_62 = {
    Text = "\"Ayah, apakah Kakak bisa terpilih?\""
  },
  AvgDialog_47176_Content_63 = {
    Text = "\"Tentu saja bisa! Pendeta di kota sudah bilang, bakat kekuatan spiritual kakakmu bahkan lebih kuat dari pendeta itu sendiri.\""
  },
  AvgDialog_47176_Content_64 = {
    Text = "\"Dia tidak hanya bisa menjadi pendeta, bahkan mungkin suatu hari nanti bisa menjadi pendeta agung!\""
  },
  AvgDialog_47176_Content_65 = {
    Text = "\"Itu adalah kehormatan tertinggi... Kalau benar begitu, ibu kalian di dunia sana pasti juga akan merasa bahagia untuk kalian!\""
  },
  AvgDialog_47176_Content_66 = {
    Text = "\"Ah! Pendeta Yang Mulia datang!\""
  },
  AvgDialog_47176_Content_67 = {
    Text = "Di tengah seruan antusias Sara, semua orang menoleh ke depan."
  },
  AvgDialog_47176_Content_68 = {
    Text = "Pendeta yang mengenakan kerudung ungu berjalan sambil merapalkan doa. Dia melewati anak-anak peserta seleksi satu per satu, lalu tiba di hadapan keluarga Miriam."
  },
  AvgDialog_47176_Content_69 = {
    Text = "\"Tuanku, dengarkanlah suara hati hambamu yang tulus, terimalah putriku, Miriam...\""
  },
  AvgDialog_47176_Content_7 = {
    Text = "Guntur menggelegar di langit pulau. Tubuh mungil itu gemetar di bawah reruntuhan."
  },
  AvgDialog_47176_Content_70 = {
    Text = "Doa lirih sang ayah dan kewibawaan pendeta membuat Miriam tidak berkata apa-apa lagi."
  },
  AvgDialog_47176_Content_71 = {
    Text = "Dia menundukkan kepala dan menunggu. Tangan pendeta yang terangkat diletakkan di atas dahinya."
  },
  AvgDialog_47176_Content_72 = {
    Text = "\"Pendeta Yang Mulia, bolehkah saya bertanya tentang anak saya...\""
  },
  AvgDialog_47176_Content_73 = {
    Text = "Sang ayah memandang pendeta dengan rendah hati. Pendeta tidak menjawab, juga tanpa ekspresi apa pun. Dia sudah terlalu sering melihat kisah seperti ini, dan tidak lagi memiliki ketertarikan terhadap rintihan hewan-hewan rendahan."
  },
  AvgDialog_47176_Content_74 = {
    Text = "Tangan yang terawat dengan baik itu tak berhenti barang sedetik pun. Sang pendeta berbalik bersama pengiringnya, meninggalkan tempat itu dan kembali ke altar upacara."
  },
  AvgDialog_47176_Content_75 = {
    Text = "\"Tidak terpilih ya...\""
  },
  AvgDialog_47176_Content_76 = {
    Text = "\"Ayah, maafkan aku, aku tetap tidak bisa membantu keluarga kita...\""
  },
  AvgDialog_47176_Content_77 = {
    Text = "\"Apa yang kamu bicarakan, anak bodoh. Bintang-bintang telah menentukan takdir setiap orang. Bukankah Ayah sendiri juga gagal menjadi pendeta?\""
  },
  AvgDialog_47176_Content_78 = {
    Text = "\"Selama kalian bisa hidup dengan sehat dan bahagia, Ayah sudah merasa puas. Meskipun tidak bisa menjadi pendeta, kamu tetap anak Ayah yang baik.\""
  },
  AvgDialog_47176_Content_79 = {
    Text = "\"Ayah, kalau aku bagaimana?\""
  },
  AvgDialog_47176_Content_8 = {
    Text = "Lautan mengaum dengan murka tak jauh darinya, hampir menelan suara guntur sekalipun. Pulau Lemuria yang megah bagaikan sehelai daun kering tanpa sandaran, gemetar di tengah lautan yang tak bertepi."
  },
  AvgDialog_47176_Content_80 = {
    Text = "\"Hahaha, kalian semua anak-anak yang baik!\""
  },
  AvgDialog_47176_Content_81 = {
    Text = "Miriam bisa melihat, ekspresi ayahnya sedikit kecewa. Namun tangan yang kasar dan lebar itu tetap dengan lembut diletakkan di atas kepalanya."
  },
  AvgDialog_47176_Content_82 = {
    Text = "Sejak kecil hingga besar, saat ia ketakutan, saat ia kecewa, saat ia bersedih, tangan itu selalu muncul, mengelus kepalanya seperti ini, membuatnya merasa tenang."
  },
  AvgDialog_47176_Content_83 = {
    Text = "Tapi sejak kecil hingga besar, apa yang telah ditanggung oleh pemilik tangan itu? Dan apa yang telah ia lakukan untuk membantunya?"
  },
  AvgDialog_47176_Content_84 = {
    Text = "Miriam menundukkan kepalanya, menyembunyikan lingkaran matanya yang memerah."
  },
  AvgDialog_47176_Content_85 = {
    Text = "\"Eh, Kakak, lihat! Ada seorang kakek tua naik ke panggung!\""
  },
  AvgDialog_47176_Content_86 = {
    Text = "\"Pakaian itu!... Jubah ungu itu!...\""
  },
  AvgDialog_47176_Content_87 = {
    Text = "Seorang umat dengan bersemangat berdesakan ke samping Inos, berjinjit sambil memandang ke depan."
  },
  AvgDialog_47176_Content_88 = {
    Text = "\"Itu Pendeta Agung? Pendeta Agung keluar dari kuil?! Tidak ada yang memberitahu soal ini sebelumnya...\""
  },
  AvgDialog_47176_Content_89 = {
    Text = "Seorang pria tua berjalan keluar dari ruangan di bagian belakang. Wajahnya sudah tua, namun langkahnya masih tegap. Pakaiannya dirawat dengan sangat rapi, tanpa satu kerutan pun."
  },
  AvgDialog_47176_Content_9 = {
    Text = "Gempa bumi dahsyat di pulau itu telah mereda, tetapi ia masih merasakan pusing."
  },
  AvgDialog_47176_Content_90 = {
    Text = "Pendeta Agung, satu-satunya orang yang bisa menghadap Raja. Di seluruh Lemuria, selain Raja yang mampu berkomunikasi dengan para dewa, kedudukannya adalah yang tertinggi."
  },
  AvgDialog_47176_Content_91 = {
    Text = "Tatapan tajam sang pria tua menyapu seluruh ruangan. Ia tidak mengucapkan sepatah kata pun, namun di bawah tatapan itu, kuil yang semula ramai langsung hening."
  },
  AvgDialog_47176_Content_92 = {
    Text = "Tak lama kemudian, tatapan itu tertuju ke arah Miriam. Mengikuti arahan sang pendeta, pria tua itu datang ke hadapan Miriam dan meletakkan tangannya yang penuh keriput di atas dahinya."
  },
  AvgDialog_47176_Content_93 = {
    Text = "Para pendeta yang angkuh itu kini membungkuk di hadapan sang pria tua. Segalanya di dalam kuil seolah membeku karena kehadirannya. Ia tidak bisa bernapas, juga tidak bisa merasakan berlalunya waktu."
  },
  AvgDialog_47176_Content_94 = {
    Text = "\"Apakah kau akan membunuh ayahmu demi Sang Raja?\""
  },
  AvgDialog_47176_Content_95 = {
    Text = "Suara dingin itu keluar dari mulut Pendeta Agung, bagaikan petir yang memecah kebekuan waktu."
  },
  AvgDialog_47176_Content_96 = {
    Text = "Miriam mendongakkan kepalanya dengan terkejut, menatap wajah tua nan berwibawa milik Pendeta Agung."
  },
  AvgDialog_47176_Content_97 = {
    Text = "\"A-Anda... Apa yang Anda katakan?\""
  },
  AvgDialog_47176_Content_98 = {
    Text = "\"Katakan padaku, apa itu keimanan.\""
  },
  AvgDialog_47176_Content_99 = {
    Text = "\"Keimanan adalah... adalah mempersembahkan segalanya untuk Sang Raja...\""
  },
  AvgDialog_47177_Content_1 = {
    Text = "Daging ikan"
  },
  AvgDialog_47177_Content_10 = {
    Text = "Kakak, ikan kan enak sekali, kenapa Kakak tidak suka makan ikan?"
  },
  AvgDialog_47177_Content_11 = {
    Text = "Mungkin karena waktu kecil terlalu banyak makan ikan, mungkin karena bau amisnya terlalu menyengat, atau mungkin..."
  },
  AvgDialog_47177_Content_12 = {
    Text = "Sarah, aku belum pernah menceritakan tentang saat Ibu meninggal, kan?"
  },
  AvgDialog_47177_Content_13 = {
    Text = "Sarah menggelengkan kepalanya, diam-diam meringkuk di pelukan Miriam sambil mendengarkan."
  },
  AvgDialog_47177_Content_14 = {
    Text = "Saat itu kamu baru saja lahir, Ibu sedang terbaring sakit di tempat tidur. Ketika batu-batu dari gunung jatuh berguling ke bawah, Ibu tidak sempat menghindar."
  },
  AvgDialog_47177_Content_15 = {
    Text = "Hari itu anginnya sangat kencang, ikan-ikan berjatuhan dari langit, jatuh menimpa tubuh Ibu."
  },
  AvgDialog_47177_Content_16 = {
    Text = "Matanya terbuka lebar membulat, sama seperti mata ikan-ikan itu..."
  },
  AvgDialog_47177_Content_17 = {
    Text = "Miriam tidak melanjutkan ceritanya, Sarah pun tidak bertanya lagi. Sang adik memeluk erat di dekapan kakaknya, menepuk-nepuk punggungnya."
  },
  AvgDialog_47177_Content_18 = {
    Text = "Kalau Kakak sudah tidak suka, kenapa tidak bilang ke Ayah?"
  },
  AvgDialog_47177_Content_19 = {
    Text = "Kalau aku tidak suka sesuatu, aku pasti langsung bilang ke kalian."
  },
  AvgDialog_47177_Content_2 = {Text = "Sreeess—"},
  AvgDialog_47177_Content_20 = {
    Text = "Setelah Ibu meninggal, Ayah sendirian menghidupi seluruh keluarga kita. Hidupnya sangat berat."
  },
  AvgDialog_47177_Content_21 = {
    Text = "Di Lemuria, ikan adalah makanan yang paling murah."
  },
  AvgDialog_47177_Content_22 = {
    Text = "Aku tidak punya kemampuan apa-apa, tidak bisa banyak membantu keluarga. Satu-satunya yang bisa kulakukan adalah tidak menambah beban untuknya..."
  },
  AvgDialog_47177_Content_23 = {
    Text = "Sarah, kamu juga harus ingat, kalau sudah besar nanti, kamu juga harus membantu Ayah dengan baik, ya?"
  },
  AvgDialog_47177_Content_24 = {
    Text = "Iya! Eh, Kakak, waktu Kakak bilang suka jadi pendeta, apa itu juga sama seperti Kakak bilang suka makan ikan?"
  },
  AvgDialog_47177_Content_25 = {
    Text = "Ayo! Dua putri kecilku, hidangan terakhir sudah siap!"
  },
  AvgDialog_47177_Content_26 = {
    Text = "Suara sang ayah terdengar dari dapur, memotong pertanyaan Sarah. Miriam tersenyum dan mengalihkan pembicaraan."
  },
  AvgDialog_47177_Content_27 = {
    Text = "Sarah, hal-hal yang kuceritakan ini, jangan diceritakan ke orang lain, ya?"
  },
  AvgDialog_47177_Content_28 = {
    Text = "Tahu! Sara juga tidak akan merepotkan Kakak dan Ayah~"
  },
  AvgDialog_47177_Content_29 = {
    Text = "Miriam tersenyum sambil menepuk kepala adiknya, lalu membawanya berjalan menuju dapur, menyambut perjamuan yang telah disiapkan sang ayah untuknya."
  },
  AvgDialog_47177_Content_3 = {
    Text = "Daging ikan segar dimasukkan ke dalam wajan, suara yang nikmat dan aroma harum menguar bersamaan dari dapur yang sederhana."
  },
  AvgDialog_47177_Content_30 = {
    Text = "Tak lama kemudian, berbagai hidangan ikan telah memenuhi meja kecil di rumah mereka."
  },
  AvgDialog_47177_Content_31 = {
    Text = "Saat kalian pergi belanja, aku sudah memberitahu orang-orang di kota. Untuk kerabat yang tinggal jauh, aku juga sudah menulis surat. Beberapa hari lagi mereka juga akan tahu."
  },
  AvgDialog_47177_Content_32 = {
    Text = "Para paman dan bibi di sekitar sini yang sudah melihatmu tumbuh besar sejak kecil, semuanya turut senang untukmu. Mereka mengirimkan banyak makanan dan minuman ke sini."
  },
  AvgDialog_47177_Content_33 = {
    Text = "Oh iya, dan juga pendeta di kota itu, setelah mendengar bahwa kamu dipilih oleh Pendeta Agung, dia datang dan berbicara denganku dengan sukarela. Sikapnya sangat baik!"
  },
  AvgDialog_47177_Content_34 = {
    Text = "Ini cuma hal kecil… Tidak perlu memberitahu sebanyak itu kan…"
  },
  AvgDialog_47177_Content_35 = {
    Text = "Ini bukan hal kecil! Kalau Kakak jadi pendeta, Kakak bisa menghasilkan banyak sekali uang, dan juga bisa menyuruh orang untuk membantuku menyapu lantai…"
  },
  AvgDialog_47177_Content_36 = {
    Text = "Jangan bicara sembarangan, Sara. Pendeta adalah profesi yang suci. Menjadi pendeta bukan untuk hal-hal seperti itu."
  },
  AvgDialog_47177_Content_37 = {
    Text = "Lalu pendeta itu tugasnya apa?"
  },
  AvgDialog_47177_Content_38 = {
    Text = "Misi seorang pendeta… Ini harus diceritakan dari masa yang sangat lampau. Ini adalah kisah yang seharusnya diketahui oleh setiap orang Lemuria."
  },
  AvgDialog_47177_Content_39 = {
    Text = "Inos menggendong Sara dan mendudukkannya di pangkuannya, sambil mengelus kepalanya."
  },
  AvgDialog_47177_Content_4 = {
    Text = "Semua ini adalah hidangan favorit putri-putrinya. Inos sudah memasak hidangan ini selama belasan tahun, bahkan dengan mata terpejam pun ia bisa mengontrol takaran setiap bumbu dengan tepat."
  },
  AvgDialog_47177_Content_40 = {
    Text = "Lemuria memiliki sejarah yang gemilang dan peradaban yang cemerlang. Kekuatan para dewa melindungi negeri ini, menganugerahkan kita kebahagiaan dan kedamaian tanpa akhir."
  },
  AvgDialog_47177_Content_41 = {
    Text = "Di sini tidak ada bencana alam, tidak ada penyakit, setiap orang memiliki makanan dan minuman yang tak pernah habis. Bahkan orang yang telah tiada, dengan bantuan para dewa, bisa bersatu kembali dengan yang masih hidup."
  },
  AvgDialog_47177_Content_42 = {
    Text = "Tapi entah sejak kapan, orang-orang di sini tidak lagi bisa mendengar suara para dewa. Bencana alam menjadi semakin sering terjadi…"
  },
  AvgDialog_47177_Content_43 = {
    Text = "Negeri kita dikelilingi oleh lautan tak bertepi, tidak pernah ada seorang pun yang bisa pergi dari sini. Hanya para dewa yang bisa mengubah semua ini."
  },
  AvgDialog_47177_Content_44 = {
    Text = "Dan Raja kita adalah satu-satunya orang yang bisa berkomunikasi dengan para dewa. Raja akan mendengarkan wahyu ilahi dan membawa kembali anugerah dewa untuk kita."
  },
  AvgDialog_47177_Content_45 = {
    Text = "Pada saat itu tiba, semua bencana alam akan lenyap, kerabat yang telah meninggal akan hidup kembali, dan kita akan selamanya tinggal dengan damai di tanah ini… Lemuria akan kembali menjadi negeri dewa yang sempurna!"
  },
  AvgDialog_47177_Content_46 = {
    Text = "Jakun di tenggorokannya bergerak naik turun, saat ia menarik kembali tatapan penuh harapannya dari arah kuil."
  },
  AvgDialog_47177_Content_47 = {
    Text = "Namun, kekuatan Raja terbatas dan membutuhkan bantuan rakyatnya. Hanya mereka yang memiliki kekuatan spiritual yang cukup kuat yang mampu menjadi pendeta, untuk menyampaikan titah Raja dan membantu Raja."
  },
  AvgDialog_47177_Content_48 = {
    Text = "Orang biasa sepertiku, tidak punya bakat seperti itu, tidak bisa berbuat apa-apa, hanya bisa menyaksikan ibu kalian..."
  },
  AvgDialog_47177_Content_49 = {
    Text = "Sudahlah, sudahlah, hari ini adalah hari yang baik, jangan kita bicarakan hal itu."
  },
  AvgDialog_47177_Content_5 = {Text = "Ukh——"},
  AvgDialog_47177_Content_50 = {
    Text = "Dia mengusap sudut matanya, tersenyum sambil menepuk kepala kedua putrinya."
  },
  AvgDialog_47177_Content_51 = {
    Text = "Menjadi pendeta, membantu Raja, menyelamatkan Lemuria, ini adalah kehormatan tertinggi."
  },
  AvgDialog_47177_Content_52 = {
    Text = "Terima kasih kepada Raja, yang telah memberikan kesempatan seperti ini kepada keluarga sederhana kita..."
  },
  AvgDialog_47177_Content_53 = {
    Text = "Inos mengangkat gelasnya. Cairan keruh bergoyang di dalam gelas, mengeluarkan bau menyengat alkohol murahan."
  },
  AvgDialog_47177_Content_54 = {
    Text = "Orang-orang miskin Lemuria menyukai minuman keras seperti ini—murah, kuat, memberikan mereka penghiburan sesaat dengan harga yang rendah."
  },
  AvgDialog_47177_Content_55 = {
    Text = "Kotoran dalam alkohol akan membuat mereka terbangun keesokan harinya dengan sakit kepala luar biasa. Namun bagi mereka, mabuk dan rasa sakit adalah anugerah yang berharga."
  },
  AvgDialog_47177_Content_56 = {
    Text = "Dia meneguknya hingga habis."
  },
  AvgDialog_47177_Content_57 = {
    Text = "Sara, ayahmu ini memang tidak berguna, tapi kakakmu adalah kebanggaan seluruh keluarga kita!"
  },
  AvgDialog_47177_Content_58 = {
    Text = "Ayo, Miriam, ini irisan ikan goreng kesukaanmu. Pak tua Ona baru menangkapnya hari ini! Aku sengaja memintanya menyisihkannya untukku."
  },
  AvgDialog_47177_Content_59 = {
    Text = "Ayah tidak ingin memberimu terlalu banyak tekanan, lakukanlah dengan bebas, aku tahu kamu pasti bisa melakukannya dengan baik!"
  },
  AvgDialog_47177_Content_6 = {
    Text = "Kakak, perutmu tidak enak lagi... Setiap kali mencium bau ikan selalu mual, haah."
  },
  AvgDialog_47177_Content_60 = {
    Text = "Ayah hanya berharap, kamu bisa menjaga dirimu baik-baik nanti. Kalau ada hal yang membuatmu tidak bahagia, tulislah surat dan ceritakan padaku."
  },
  AvgDialog_47177_Content_61 = {
    Text = "Besok setelah meninggalkan rumah, entah kapan lagi bisa makan ikan buatan ayah..."
  },
  AvgDialog_47177_Content_62 = {
    Text = "Piring penuh ikan diletakkan di hadapan Miriam. Warna keemasan, aroma yang harum semerbak."
  },
  AvgDialog_47177_Content_63 = {
    Text = "Adiknya tersenyum. Ayahnya tersenyum, matanya berkaca-kaca. Ibunya juga seolah duduk di sampingnya, tersenyum kepadanya."
  },
  AvgDialog_47177_Content_64 = {
    Text = "Dia berpakaian compang-camping, tubuhnya tidak utuh, kedua matanya terbuka bulat, persis sama seperti ikan di atas piring."
  },
  AvgDialog_47177_Content_65 = {
    Text = "Aku akan menjadi pendeta... Aku pasti tidak akan mengecewakanmu, Ayah."
  },
  AvgDialog_47177_Content_66 = {
    Text = "Miriam memasukkan ikan ke mulutnya. Dia mengunyah, menelan. Dia membalas senyuman kepada keluarganya."
  },
  AvgDialog_47177_Content_7 = {
    Text = "Adiknya menepuk-nepuk punggung Miriam sambil menggelengkan kepala dan mengeluh."
  },
  AvgDialog_47177_Content_8 = {
    Text = "Ekspresi seperti wanita tua muncul di wajah anak berusia sepuluh tahun ini, membuat Miriam tertawa geli."
  },
  AvgDialog_47177_Content_9 = {
    Text = "Aku tidak apa-apa, Sarah."
  },
  AvgDialog_47178_Content_1 = {
    Text = "Berdoa di Laut Dalam"
  },
  AvgDialog_47178_Content_10 = {
    Text = "BYURRR——"
  },
  AvgDialog_47178_Content_100 = {
    Text = "Mata yang samar-samar terlihat itu seolah melampaui para pengikut di ruangan ini, melampaui pintu-pintu batu raksasa, menatap seluruh rakyat Lemuria."
  },
  AvgDialog_47178_Content_101 = {
    Text = "Yang terukir di kedua mata itu, entah keyakinan, belas kasihan, ataukah kejenuhan."
  },
  AvgDialog_47178_Content_11 = {
    Text = "<Shake:Mmmphhh!!!……>"
  },
  AvgDialog_47178_Content_12 = {
    Text = "Makhluk basah kuyup menyembur keluar dari air. Rambut manusia yang jarang menjuntai dari kepalanya, menutupi wajah yang menyerupai ikan."
  },
  AvgDialog_47178_Content_13 = {
    Text = "Insangnya sedikit terbuka, bibir licin bergerak-gerak, pita suara yang bermutasi bergetar pelan, mengeluarkan suku kata kacau yang tak bermakna."
  },
  AvgDialog_47178_Content_14 = {
    Text = "Anggota tubuh manusianya dipenuhi sisik yang berantakan, memantulkan kilau kotor, memukul-mukul permukaan air dengan liar."
  },
  AvgDialog_47178_Content_15 = {
    Text = "Plak plak plak plak……"
  },
  AvgDialog_47178_Content_16 = {
    Text = "Dari dalam dua kolam raksasa itu, tak terhitung makhluk berwajah ikan dengan rupa yang sama menyembulkan tubuh dari air, memukul-mukul permukaan air dengan gila-gilaan sambil mengeluarkan jeritan aneh."
  },
  AvgDialog_47178_Content_17 = {
    Text = "Mereka berdesak-desakan di dalam air, mata ikan yang tak terhitung jumlahnya terbelalak bulat, menatap Miriam tanpa emosi."
  },
  AvgDialog_47178_Content_18 = {Text = "Ukh——"},
  AvgDialog_47178_Content_19 = {
    Text = "Miriam mengerahkan seluruh tenaganya untuk menahan diri agar tidak muntah."
  },
  AvgDialog_47178_Content_2 = {
    Text = "Dengungan rendah, bagaikan panggilan yang bergema dari zaman purba."
  },
  AvgDialog_47178_Content_20 = {
    Text = "Jadi ini adalah……"
  },
  AvgDialog_47178_Content_21 = {
    Text = "Benar sekali, mereka adalah para Perintis yang agung! Ini juga pertama kalinya aku melihat mereka, ternyata begini rupanya!"
  },
  AvgDialog_47178_Content_22 = {
    Text = "Murid pendeta bernama Deborah berdiri di samping Miriam, dengan antusias menepuk-nepuk bahunya, sama sekali tidak canggung meski ini pertama kalinya mereka bertemu."
  },
  AvgDialog_47178_Content_23 = {
    Text = "Menurut legenda, Raja menerima wahyu ilahi bahwa sebelum Lemuria berubah menjadi negeri para dewa, rakyat harus diubah menggunakan darah dewa agar mereka memiliki kemampuan untuk menghadapi bencana alam."
  },
  AvgDialog_47178_Content_24 = {
    Text = "Para pelopor ini, demi masa depan bangsa Lemuria, dengan berani mengambil langkah pertama lebih dahulu."
  },
  AvgDialog_47178_Content_25 = {
    Text = "Setelah kita menjadi pendeta, ritual transformasi menjadi manusia ikan akan dilaksanakan oleh kita. Saat itu tiba, aku pasti akan terlalu bersemangat sampai tidak bisa tidur!"
  },
  AvgDialog_47178_Content_26 = {
    Text = "Deborah dengan penuh sukacita memberi hormat kepada para manusia ikan ini, dengan lembut membelai wajah mereka yang licin."
  },
  AvgDialog_47178_Content_27 = {
    Text = "Para murid lain di sampingnya juga membungkuk, memberi penghormatan kepada para pendahulu yang agung ini. Miriam berdiri di tempatnya, menyaksikan pemandangan ini."
  },
  AvgDialog_47178_Content_28 = {
    Text = "\"Pelopor yang agung\"... entah apakah keluarga mereka akan berpikir demikian jika melihat mereka dalam keadaan seperti ini..."
  },
  AvgDialog_47178_Content_29 = {
    Text = "Ruang doa ada di depan. Semuanya, ikuti aku."
  },
  AvgDialog_47178_Content_3 = {
    Text = "Pintu batu raksasa yang dihiasi relief didorong oleh kekuatan misterius, bergeser terbuka ke dua sisi. Cahaya dari luar tak mampu menembus masuk sedikit pun."
  },
  AvgDialog_47178_Content_31 = {
    Text = "Pintu batu menutup tanpa suara, memisahkan geraman para manusia ikan serta kebisingan dari luar."
  },
  AvgDialog_47178_Content_32 = {
    Text = "Para murid masing-masing berlutut di tempat doa, memandang ke arah altar di depan, serta patung raksasa di belakang altar yang terdiri dari tubuh manusia, takhta, dan tentakel."
  },
  AvgDialog_47178_Content_33 = {
    Text = "Wajah manusia pada patung itu agak kabur, tubuh manusia yang berada di antara takhta besar dan tentakel menciptakan kontras yang mencolok."
  },
  AvgDialog_47178_Content_34 = {
    Text = "Ini adalah patung yang melambangkan sang Raja."
  },
  AvgDialog_47178_Content_35 = {
    Text = "Seorang pria tua keluar dari sisi kanan ruangan patung, melambaikan tangan untuk mencegah para murid yang hendak berdiri memberi hormat."
  },
  AvgDialog_47178_Content_36 = {
    Text = "Doa tertulis ada di hadapan kalian. Bacalah, ucapkanlah. Yang terpenting, percayalah padanya."
  },
  AvgDialog_47178_Content_37 = {
    Text = "Tuan Pendeta Agung, dengan melakukan semua ini, apakah kami bisa memberikan bantuan kepada sang Raja?"
  },
  AvgDialog_47178_Content_38 = {
    Text = "Pendeta Agung meliriknya sekilas."
  },
  AvgDialog_47178_Content_39 = {
    Text = "Raja akan memberitahu kalian. Berdoalah."
  },
  AvgDialog_47178_Content_4 = {
    Text = "Kegelapan yang pekat dan murni dari balik pintu mengundang semua orang masuk."
  },
  AvgDialog_47178_Content_40 = {
    Text = "Pria tua itu meninggalkan ruangan, di dalam hanya tersisa seorang pendeta dan beberapa pengawal."
  },
  AvgDialog_47178_Content_41 = {
    Text = "Cahaya di dalam ruang doa menjadi redup, patung di depan berkilau dengan kemilau misterius yang samar."
  },
  AvgDialog_47178_Content_42 = {
    Text = "Miriam mengambil teks doa di hadapannya."
  },
  AvgDialog_47178_Content_43 = {Text = "Ah……"},
  AvgDialog_47178_Content_44 = {
    Text = "Yang tertulis di kertas itu bukanlah bahasa umum Lemuria, melainkan simbol hieroglif yang rumit, memiliki dimensi lebih banyak daripada ruang realitas."
  },
  AvgDialog_47178_Content_45 = {
    Text = "Simbol-simbol itu berasal dari zaman purba, atau bahkan dari dunia lain, yang belum pernah dilihat Miriam sebelumnya. Namun saat membaca simbol-simbol itu, maknanya secara otomatis memasuki benaknya."
  },
  AvgDialog_47178_Content_46 = {
    Text = "Setiap huruf mengandung informasi yang sangat besar, kitab suci yang tak terhitung jumlahnya membanjiri otak Miriam, membuat kepala manusia yang rapuh itu tak sanggup menanggung bebannya."
  },
  AvgDialog_47178_Content_47 = {
    Text = "<Shake:Ke... kepalaku sakit sekali...>"
  },
  AvgDialog_47178_Content_48 = {
    Text = "Dari waktu ke waktu, orang-orang di sekitarnya berjatuhan. Miriam menahan rasa sakit dengan sekuat tenaga dan membacakan doa yang tertulis di atas kertas itu."
  },
  AvgDialog_47178_Content_49 = {
    Text = "\"Di jurang kelam yang jauh, jiwa agung purba tertidur lelap...\""
  },
  AvgDialog_47178_Content_5 = {
    Text = "Bagian luar kuil terbuka untuk ibadah umat biasa, namun hanya mereka yang memiliki bakat menjadi pendeta yang bisa sampai ke sini."
  },
  AvgDialog_47178_Content_50 = {
    Text = "Miriam mengucapkan kata-kata itu dalam bahasa Lemuria biasa, tetapi begitu keluar dari mulutnya, kata-kata itu berubah menjadi bahasa lain."
  },
  AvgDialog_47178_Content_51 = {
    Text = "Pada saat yang sama, suaranya saling tumpang tindih dan terjalin, bergema dengan kompleksitas yang luar biasa. Seperti halnya tulisan itu, suaranya pun berubah menjadi struktur berdimensi tinggi, seolah bergema dari ruang-waktu yang tak dapat dibayangkan manusia."
  },
  AvgDialog_47178_Content_52 = {
    Text = "\"...Kehendak-Nya terjalin bagai jaring bintang, Dia menanti engkau bermimpi dalam kekosongan abadi...\""
  },
  AvgDialog_47178_Content_53 = {
    Text = "Miriam terus membacakan doa itu."
  },
  AvgDialog_47178_Content_54 = {
    Text = "Entah sejak kapan, dunia di hadapannya menghilang."
  },
  AvgDialog_47178_Content_55 = {
    Text = "Dia berada di dasar laut dalam, ke arah mana pun dia memandang, yang terlihat hanyalah hamparan air laut yang hampa."
  },
  AvgDialog_47178_Content_56 = {
    Text = "Di kedalaman laut itu, titik-titik cahaya bertebaran bagaikan bintang-bintang di alam semesta."
  },
  AvgDialog_47178_Content_57 = {
    Text = "Miriam merasa dirinya juga telah menjadi sebuah bintang, dan cahaya dari tubuhnya tengah mengalir berkumpul ke suatu tempat. Dia mengarahkan pandangannya ke sana."
  },
  AvgDialog_47178_Content_58 = {
    Text = "Berkas-berkas cahaya yang tak terhitung mengalir deras dan berkumpul, membentuk siluet samar di sana. Itu adalah siluet yang terdiri dari tubuh manusia, takhta, dan tentakel."
  },
  AvgDialog_47178_Content_59 = {
    Text = "Itu... sang Raja?"
  },
  AvgDialog_47178_Content_6 = {
    Text = "Selamat datang di ruang dalam kuil, semuanya. Selamat datang di kediaman Sang Raja."
  },
  AvgDialog_47178_Content_60 = {Text = "Pak—"},
  AvgDialog_47178_Content_61 = {
    Text = "Seolah terganggu oleh suatu suara, dia terbangun dari singgasana batu. Seiring dengan terbangunnya dia, seluruh ruang hampa itu seakan meredup sesaat."
  },
  AvgDialog_47178_Content_62 = {
    Text = "Di belakangnya, siluet samar seorang pria tua muncul."
  },
  AvgDialog_47178_Content_63 = {
    Text = "Anda mendengar suaranya, Tuanku."
  },
  AvgDialog_47178_Content_64 = {
    Text = "Raja Lemuria masih berada di atas takhta, aku hanyalah penerus. Kau tidak seharusnya memanggilku demikian."
  },
  AvgDialog_47178_Content_65 = {
    Text = "Raja Lemuria tidak pernah ditentukan oleh siapa yang duduk di atas takhta. Siapa pun yang paling dekat dengan para dewa, dialah Tuan kami."
  },
  AvgDialog_47178_Content_66 = {
    Text = "Aku tidak suka sebutan itu."
  },
  AvgDialog_47178_Content_67 = {
    Text = "Sepanjang hidupnya, Raja tua pernah mendengar satu kali wahyu ilahi. Satu wahyu itu membuatnya duduk teguh di takhta, menjadi kepercayaan rakyatnya."
  },
  AvgDialog_47178_Content_68 = {
    Text = "Wahyu ilahi yang Anda dengar telah melampaui tak terhitung raja-raja terdahulu Lemuria. Dan Anda... masih seorang anak kecil."
  },
  AvgDialog_47178_Content_69 = {
    Text = "Anda adalah harapan Lemuria. Raja tua tidak punya banyak waktu lagi, beliau sudah memberikan perintahnya. Segera, Anda akan naik ke takhta. Anda perlu membiasakan diri dengan sebutan ini, Tuanku."
  },
  AvgDialog_47178_Content_7 = {
    Text = "Angin berhembus dari dalam ruang kuil yang tertutup, membawa bau amis laut dalam yang menyengat."
  },
  AvgDialog_47178_Content_70 = {
    Text = "Anak laki-laki yang masih belia itu bersandar lelah di punggung kursinya, tidak lagi berdebat dengan sang lelaki tua."
  },
  AvgDialog_47178_Content_71 = {
    Text = "Pada doa pertamanya, dia sudah bisa terhubung denganku, menyaksikan wujudku. Orang yang ditunjukkan oleh bintang-bintang, apakah itu dia?"
  },
  AvgDialog_47178_Content_72 = {
    Text = "Ya, dia orangnya. Saya sudah memeriksanya. Jika petunjuk bintang-bintang tidak salah, dia... adalah masa depan Lemuria."
  },
  AvgDialog_47178_Content_73 = {
    Text = "Kau tidak berpikir demikian."
  },
  AvgDialog_47178_Content_74 = {
    Text = "Berbakat, tapi pikirannya terpecah. Dia tidak akan bisa membantu Anda, Tuanku."
  },
  AvgDialog_47178_Content_75 = {
    Text = "Dia tidak percaya pada doa-doa, tidak percaya pada Anda, dan juga tidak percaya pada masa depan Lemuria. Dia hanya percaya pada keluarganya."
  },
  AvgDialog_47178_Content_76 = {
    Text = "Miryam adalah seseorang yang hidup dalam kenyataan. Orang seperti itu tidak mampu memikul takdir Lemuria."
  },
  AvgDialog_47178_Content_77 = {
    Text = "Hidup dalam kenyataan dan bukan dalam ilusi, itulah justru harapanku."
  },
  AvgDialog_47178_Content_78 = {
    Text = "Takdir Lemuria... seharusnya tidak ada yang harus memikulnya."
  },
  AvgDialog_47178_Content_79 = {
    Text = "Harapan yang indah, Tuanku. Namun terlahir di Lemuria, kita semua memiliki tanggung jawab yang harus dipikul."
  },
  AvgDialog_47178_Content_8 = {
    Text = "Mengikuti langkah sang pendeta memasuki ruang dalam, kegelapan lenyap secara ajaib. Entah dari mana asalnya, cahaya menerangi jalan batu kerikil yang tampak tak berujung."
  },
  AvgDialog_47178_Content_80 = {
    Text = "Kita tidak bisa memilih. Baik dia, saya, maupun Anda, semuanya sama."
  },
  AvgDialog_47178_Content_81 = {
    Text = "...Membosankan. Aku mau istirahat."
  },
  AvgDialog_47178_Content_82 = {
    Text = "Dia melambaikan tangannya. Sang lelaki tua membungkuk memberi hormat kepadanya, lalu menghilang ke dalam kehampaan yang tak bertepi."
  },
  AvgDialog_47178_Content_83 = {
    Text = "Sebelum tertidur, dia melirik sekilas orang-orang yang mempersembahkan cahaya mereka kepadanya. Sebuah desahan yang tak terdengar siapa pun, lenyap ke dalam kekosongan yang tak berujung."
  },
  AvgDialog_47178_Content_84 = {Text = "Ah!"},
  AvgDialog_47178_Content_85 = {
    Text = "Menyusul sensasi jatuh yang mencekam hati, datanglah rasa sakit yang tajam dan menusuk."
  },
  AvgDialog_47178_Content_86 = {
    Text = "Rasa sakit itu tidak berlangsung lama. Miriam meninggalkan ruang hampa itu dan memandang ke sekelilingnya."
  },
  AvgDialog_47178_Content_87 = {
    Text = "Beberapa orang yang tidak mampu membaca atau melafalkan doa telah diminta keluar dari ruang sembahyang. Dari separuh orang yang tersisa, beberapa tergeletak di lantai kesakitan, sementara yang lain memejamkan mata sambil berdoa, wajah mereka menampakkan senyum bahagia."
  },
  AvgDialog_47178_Content_88 = {
    Text = "Deborah duduk di sampingnya, tersenyum sambil perlahan membuka mata. Melihat keadaan Miriam, raut wajahnya berubah khawatir."
  },
  AvgDialog_47178_Content_89 = {
    Text = "Hei, Miriam? Kamu baik-baik saja?"
  },
  AvgDialog_47178_Content_9 = {
    Text = "Di kedua sisi jalan, terdapat dua kolam raksasa. Miriam mendekati salah satu kolam dan sedikit mencondongkan kepalanya untuk mengintip ke dalam."
  },
  AvgDialog_47178_Content_90 = {
    Text = "Kepalaku sakit sekali…… Tadi jelas-jelas baik-baik saja, kenapa aku tiba-tiba terlempar keluar? Apa ada yang salah……"
  },
  AvgDialog_47178_Content_91 = {
    Text = "Sepertinya kamu…… gagal. Alam mimpi Sang Raja menolakmu."
  },
  AvgDialog_47178_Content_92 = {
    Text = "Tapi kenapa…… Aku jelas-jelas melihat sebuah siluet, kenapa tiba-tiba……"
  },
  AvgDialog_47178_Content_93 = {
    Text = "Para pendeta memasuki alam mimpi Sang Raja melalui doa untuk memberikan bantuan kepada-Nya. Seharusnya, bisa melihat siluet Sang Raja itu sudah merupakan pencapaian luar biasa. Hanya pendeta paling berbakat yang bisa melakukannya!"
  },
  AvgDialog_47178_Content_94 = {
    Text = "Aku juga tidak tahu pasti masalahnya di mana…… Tapi ini baru pertama kali! Mungkin kamu hanya belum terbiasa, nanti pasti akan lebih baik!"
  },
  AvgDialog_47178_Content_95 = {
    Text = "Terima kasih……"
  },
  AvgDialog_47178_Content_96 = {
    Text = "Tidak perlu sungkan~ Semangat ya! Doa ini harus dikuasai oleh setiap pendeta. Ke depannya, baik untuk sembahyang maupun ritual transformasi manusia-ikan, doa ini diperlukan untuk membangun koneksi dengan Sang Raja."
  },
  AvgDialog_47178_Content_97 = {
    Text = "Nanti kita akan tinggal bersama di kuil, menjadi pendeta Sang Raja, dan menjadikan Lemuria kembali menjadi negeri para dewa!"
  },
  AvgDialog_47178_Content_98 = {
    Text = "Kebaikan sang sahabat meredakan rasa lemah yang dirasakan Miriam. Saat bersiap berdiri untuk pergi, ia sekali lagi memandang patung di hadapannya. Bayangan cahaya yang dilihatnya di dimensi spiritual bertumpang tindih dengan patung itu."
  },
  AvgDialog_47178_Content_99 = {
    Text = "Sosok samar itu duduk miring di atas takhta, wajahnya tertutupi oleh tentakel-tentakel yang melambangkan kekuatan agung."
  },
  AvgDialog_47232_Content_1 = {
    Text = "Zona kontrol di depan, orang yang tidak berkepentingan dilarang masuk. Silakan tunjukkan identitas Anda."
  },
  AvgDialog_47232_Content_10 = {
    Text = "Semoga Kunci Perak membimbing kita."
  },
  AvgDialog_47232_Content_2 = {
    Text = "Penyelidik Universitas Mythag William Delaplume, ID Kunci Perak I-2083."
  },
  AvgDialog_47232_Content_3 = {
    Text = "%player%, K-0617."
  },
  AvgDialog_47232_Content_4 = {
    Text = "Ramona, I-3017."
  },
  AvgDialog_47232_Content_5 = {
    Text = "Matanya terlihat seolah-olah sedang melihat seseorang yang akan menghadapi ajalnya…"
  },
  AvgDialog_47232_Content_6 = {
    Text = "Di dalam zona terlarang Efek-d regional, dimensi roh mengalami kekacauan yang luar biasa. Kita sering kali harus <Yellow:menghadapi beberapa medan pertempuran rohani secara bersamaan>. Kerusakan terhadap roh jauh lebih besar daripada pada tubuh fisik."
  },
  AvgDialog_47232_Content_7 = {
    Text = "Tidak sedikit penyelidik yang mengalami gangguan roh akibat menekan zona terlarang efek-d regional, kalian juga harus memperhatikan keseimbangan alokasi sumber daya di berbagai medan pertempuran untuk menghindari hasil terburuk."
  },
  AvgDialog_47232_Content_8 = {
    Text = "Di kaca spion, penjaga yang bertugas melepas topinya untuk memberi hormat kepada kalian."
  },
  AvgDialog_47232_Content_9 = {
    Text = "Semoga Kunci Perak menuntun jalanmu."
  },
  AvgDialog_47798_Content_1 = {
    Text = "Apa tidak apa-apa kita menyelinap masuk seperti ini? Nona Sylvia……ini kan ruang kerjanya."
  },
  AvgDialog_47798_Content_10 = {Text = "Mau coba?"},
  AvgDialog_47798_Content_11 = {
    Text = "Murphy mengambil sebongkah cokelat susu, menundukkan kepala dalam diam. Ruang konseling tenggelam dalam keheningan yang mencekam, membuatmu tak bisa menahan diri untuk bergidik."
  },
  AvgDialog_47798_Content_12 = {
    Text = "A-apa jangan-jangan kamu tidak suka cokelat? Atau kamu alergi biji kakao?"
  },
  AvgDialog_47798_Content_13 = {
    Text = "Ayo kita ke kafetaria sekolah dan cari sesuatu yang lain! Meskipun koki sudah istirahat di jam segini, tapi kita bisa coba membuat sesuatu sendiri—umph!"
  },
  AvgDialog_47798_Content_14 = {
    Text = "Sebelum kau sempat bereaksi, sebongkah cokelat susu sudah dimasukkan ke mulutmu."
  },
  AvgDialog_47798_Content_15 = {
    Text = "Saat dia menarik tangannya, ujung jarinya yang dingin menyapu lidahmu. Detik berikutnya, aroma kakao yang kaya dan pekat meledak di rongga mulut, meluncur masuk ke perutmu."
  },
  AvgDialog_47798_Content_16 = {
    Text = "Aku tidak bilang tidak mau makan—"
  },
  AvgDialog_47798_Content_17 = {
    Text = "Kata Murphy sambil memilih cokelat berwarna paling gelap dari kotak hadiah. Kemurniannya sangat tinggi, tampaknya tanpa tambahan gula apa pun——"
  },
  AvgDialog_47798_Content_18 = {
    Text = "Asam sekali……! Asam dan pahit……"
  },
  AvgDialog_47798_Content_19 = {
    Text = "Melihat seluruh wajahnya berkerut, kamu buru-buru mengambil sebatang cokelat susu untuknya."
  },
  AvgDialog_47798_Content_2 = {
    Text = "Tidak apa-apa. Nona Sylvia pernah bilang, makanan manis di ruang konseling bisa kuambil kapan saja."
  },
  AvgDialog_47798_Content_20 = {
    Text = "Te-terima kasih……"
  },
  AvgDialog_47798_Content_21 = {
    Text = "Ruang konseling psikologi memiliki perangkat teh lengkap. Kalian menyeduh sepoci teh merah yang ringan, mengobrol santai tanpa topik tertentu."
  },
  AvgDialog_47798_Content_22 = {
    Text = "Baru setelah Murphy menghabiskan cokelat susu terakhir dan menjilati jarinya dengan puas, kamu melirik jam dinding."
  },
  AvgDialog_47798_Content_23 = {
    Text = "Sebentar lagi aku harus pergi menjalankan misi. Kamu sudah makan makanan manis tengah malam, jangan lupa sikat gigi sebelum tidur."
  },
  AvgDialog_47798_Content_24 = {
    Text = "Menjalankan misi? Selarut ini?"
  },
  AvgDialog_47798_Content_25 = {
    Text = [[
Masih karena dampak anomali Lemvashi, seluruh Universitas Misagar sibuk luar biasa.
Ayo, aku antar kamu kembali ke kamar dulu.]]
  },
  AvgDialog_47798_Content_26 = {
    Text = "Kamu melangkah keluar lebih dulu, dan detik berikutnya, kamu terjatuh ke lantai tanpa sempat bereaksi."
  },
  AvgDialog_47798_Content_27 = {
    Text = "Hah?! Ma-maaf."
  },
  AvgDialog_47798_Content_28 = {
    Text = "Murphy dengan panik membantumu berdiri. Kamu menunduk ke bawah dan baru menyadari sebuah tentakel merah gelap sedang mengait erat kakimu."
  },
  AvgDialog_47798_Content_29 = {
    Text = "Itu adalah bagian dari gaun Murphy, atau lebih tepatnya bagian dari \"tubuh\"-nya."
  },
  AvgDialog_47798_Content_3 = {
    Text = "Kalau memang begitu, kita tidak perlu masuk lewat jendela kan?"
  },
  AvgDialog_47798_Content_30 = {
    Text = "Kamu…… harus pergi sekarang?"
  },
  AvgDialog_47798_Content_31 = {
    Text = "Karena pengaruh Sungai Suci Lemvashi, Secret Realm di seluruh dunia mengalami anomali."
  },
  AvgDialog_47798_Content_32 = {
    Text = "Tim investigator tahun kedua berpatroli semalaman. Aku sudah berjanji dengan mereka untuk mengambil alih patroli Secret Realm di distrik timur jam delapan pagi."
  },
  AvgDialog_47798_Content_33 = {
    Text = "Anomali……"
  },
  AvgDialog_47798_Content_34 = {
    Text = "A-aku merasa…… aku juga…… sedikit tidak normal……"
  },
  AvgDialog_47798_Content_35 = {
    Text = "Tidak enak badan? Apa kamu demam?"
  },
  AvgDialog_47798_Content_36 = {
    Text = "Sambil berkata begitu, kamu melepas sarung tangan dan mengulurkan tangan untuk memeriksa dahinya. Namun Murphy tiba-tiba mundur selangkah, menghindari tanganmu—tetapi tentakelnya tetap melilit di kakimu."
  },
  AvgDialog_47798_Content_37 = {
    Text = "Setahuku, menyuruh sopir mengantarmu ke distrik timur hanya butuh setengah jam, tidak perlu berangkat sepagi ini."
  },
  AvgDialog_47798_Content_38 = {
    Text = "Sebagai… imbalannya, nona ini akan menemanimu berpatroli di siang hari……"
  },
  AvgDialog_47798_Content_39 = {
    Text = "Po, pokoknya… temani aku sampai fajar saja……"
  },
  AvgDialog_47798_Content_4 = {
    Text = "……Tidak apa-apa, lagipula Nona Sylvia sedang tidak ada di sekolah. Untuk meredam dampak dari insiden Lemwashi, dia pergi bersama penyelidik lain ke pusat kota Londinium."
  },
  AvgDialog_47798_Content_5 = {Text = "Ketemu."},
  AvgDialog_47798_Content_6 = {
    Text = "Dari lemari makanan manis di ruang konseling, kau mengeluarkan sebuah kotak hadiah yang elegan—"
  },
  AvgDialog_47798_Content_7 = {
    Text = "Merek cokelat ini……"
  },
  AvgDialog_47798_Content_8 = {
    Text = "Kertas pembungkus berlapis emas tampak rapi dan sempurna, bahkan pita hiasannya pun disulam dengan benang perak di sekelilingnya, cukup membuktikan bahwa kotak hadiah cokelat ini bernilai tinggi."
  },
  AvgDialog_47798_Content_9 = {
    Text = "Aroma pahit kakao langsung menyeruak keluar begitu pita dibuka."
  },
  AvgDialog_47803_Content_1 = {
    Text = "Heh… Penjaga Rahasia kecil dari Misagar, ternyata benar-benar berkenan mengunjungi gubuk sederhana ini.\nStudio kecilku ini bersinar berkat kedatangan Anda."
  },
  AvgDialog_47803_Content_10 = {Text = "Nona Shan!"},
  AvgDialog_47803_Content_11 = {
    Text = "Sst, sst… diam dan biarkan aku melihat."
  },
  AvgDialog_47803_Content_12 = {
    Text = "Dia berhenti mengayunkan pisau ukir, dan menempelkan ujungnya di wajahmu, mengusapnya perlahan ke sana kemari."
  },
  AvgDialog_47803_Content_13 = {
    Text = "Kamu tahu, setiap seniman memiliki muse yang unik."
  },
  AvgDialog_47803_Content_14 = {
    Text = "Catullus memiliki Lesbia-nya, Petrarch memiliki Laura yang dicintainya…"
  },
  AvgDialog_47803_Content_15 = {
    Text = "Di dalam mata yang tak terselami itu tak ada setitik pun keganasan atau kebengisan, justru dipenuhi emosi yang sulit kamu gambarkan —"
  },
  AvgDialog_47803_Content_16 = {
    Text = "Dan sekarang, aku juga memiliki <Blue:Camille>-ku. Benar begitu, Tuan Penjaga Rahasia?"
  },
  AvgDialog_47803_Content_2 = {
    Text = "Kamu menyingkirkan material pahatan yang menumpuk di dekat pintu, dan dengan susah payah berhasil masuk ke studio Shan yang terletak di sayap barat Misagar."
  },
  AvgDialog_47803_Content_3 = {
    Text = "Sang seniman pemahat duduk di atas alas karang, pisau ukir berputar-putar di antara jari-jarinya, pemandangan yang membuat jantung berdebar — pisau ukir itu terlalu tajam, cukup untuk memotong jari-jarinya."
  },
  AvgDialog_47803_Content_4 = {
    Text = "Bukankah kamu yang bilang pada investigator penjaga bahwa kamu ingin bertemu denganku?"
  },
  AvgDialog_47803_Content_5 = {
    Text = "Para Awakened menikmati kebebasan mutlak dalam batas aturan di dalam sekolah, tetapi Shan adalah pengecualian — berdasarkan kejahatan yang dilakukannya di panti asuhan, dia tidak diizinkan bertindak sendirian."
  },
  AvgDialog_47803_Content_6 = {
    Text = "Ah… memang benar. Anda lihat, kurangnya inspirasi membuat otakku juga dipenuhi karang."
  },
  AvgDialog_47803_Content_7 = {
    Text = "Tolong mendekatlah sedikit lagi, biarkan aku melihat matamu sekali lagi dengan jelas… biarkan orang malang yang tak bisa meninggalkan ruangan ini, melihat dunia melalui matamu."
  },
  AvgDialog_47803_Content_8 = {
    Text = "Alasannya begitu meyakinkan, kamu tak bisa menemukan alasan untuk menolaknya, dan terpaksa mendekat padanya —"
  },
  AvgDialog_47803_Content_9 = {
    Text = "Shan tiba-tiba menarik jubah seragammu, memaksa wajahmu mendekat tepat di hadapannya."
  },
  AvgDialog_47807_Content_1 = {
    Text = "Kabut tebal yang tak kunjung sirna menyelimuti indra dalam tidur, kegelapan yang membentang tampak tenang, namun gelombang hitam raksasa sebenarnya telah bergulung-gulung menghantam benteng jiwa."
  },
  AvgDialog_47807_Content_10 = {
    Text = "Celeste mengayunkan kompasnya dan menahanmu tetap di tempat tidur."
  },
  AvgDialog_47807_Content_11 = {
    Text = "Dia menunjuk bulan purnama yang tergantung tinggi di luar jendela, lalu menunjukmu—"
  },
  AvgDialog_47807_Content_12 = {
    Text = "……Mimpi buruk."
  },
  AvgDialog_47807_Content_13 = {
    Text = "Selama aku ada, takkan ada mimpi buruk."
  },
  AvgDialog_47807_Content_14 = {
    Text = "Napasmu perlahan selaras dengan ritme lembut tangannya yang membelai selimut, setiap tarikan napas bagaikan harmoni bersama angin. Kesadaranmu kembali tenggelam, masuk ke dalam mimpi yang lain."
  },
  AvgDialog_47807_Content_15 = {
    Text = "Mimpi yang lembut dan tenang, yang mampu berlayar menuju fajar yang damai."
  },
  AvgDialog_47807_Content_2 = {
    Text = "Hingga hari ini, pengaruh Sungai Suci dan Pohon Raksasa masih membelitmu."
  },
  AvgDialog_47807_Content_3 = {
    Text = "Kenangan masa lalu mengkristal menjadi gelembung-gelembung rapuh dalam mimpi, setiap kali kau berguling gelisah, gelembung itu pecah bagai bayangan bulan di air—lenyap begitu disentuh."
  },
  AvgDialog_47807_Content_4 = {
    Text = "Kegelapan tanpa keteraturan menarikmu tenggelam ke kedalaman kesadaran. Tepat sebelum kau merasa akan hancur berkeping-keping akibat jatuh, angin lembut yang samar berhembus masuk ke dalam mimpimu."
  },
  AvgDialog_47807_Content_5 = {
    Text = "Angin itu seolah memiliki warna, tak bisa diabaikan namun juga tak mencolok. Ia bagaikan penjaga yang lemah, membuktikan dengan kehadirannya bahwa kau takkan tersesat dalam mimpi—"
  },
  AvgDialog_47807_Content_6 = {
    Text = "Saat kau membuka mata, pandanganmu bertemu dengan sang \"Penjaga Mimpi\"."
  },
  AvgDialog_47807_Content_7 = {
    Text = "Celeste... kenapa kau ada di sini?"
  },
  AvgDialog_47807_Content_8 = {
    Text = "Awakened yang pendiam itu mengangguk, lalu duduk di tepi tempat tidurmu. Kasur yang empuk sedikit melesak karena bebannya."
  },
  AvgDialog_47807_Content_9 = {
    Text = "Apa ada situasi darurat dalam misi? Aku segera—"
  },
  AvgDialog_47808_Content_1 = {
    Text = "Faros, kau sedang melihat apa?"
  },
  AvgDialog_47808_Content_10 = {
    Text = "Cahaya Pharos berkedip-kedip beberapa kali."
  },
  AvgDialog_47808_Content_11 = {
    Text = "Tidak pernah. Saat usiaku sudah cukup untuk mengikuti perkumpulan itu, Lemuria sudah terkepung oleh bencana alam."
  },
  AvgDialog_47808_Content_13 = {
    Text = "Penjaga Rahasia, maukah kau tinggal di sini menemaniku malam ini?"
  },
  AvgDialog_47808_Content_14 = {
    Text = "Anggap saja…… mendengarkan orang gila bercerita. Satu malam, cukup satu malam saja……"
  },
  AvgDialog_47808_Content_2 = {
    Text = "Kau sudah melihat Faros dari kejauhan—dia terlalu \"menyilaukan\" di malam hari. Di lautan pasir yang sunyi senyap, cahayanya adalah satu-satunya yang berbeda dari benda langit."
  },
  AvgDialog_47808_Content_3 = {
    Text = "Sang Penjaga Rahasia."
  },
  AvgDialog_47808_Content_4 = {
    Text = "Dengan bantuannya, kau memanjat bukit pasir. Angin malam gurun yang dingin dan kering menerpa wajahmu, bagaikan mata pisau yang menggesek kulit."
  },
  AvgDialog_47808_Content_5 = {
    Text = "Sebagai Awakened dari Realm Laut Dalam, gaun yang dikenakan Faros selalu terasa lembap. Namun sekarang, bahkan tentakelnya pun tampak lesu karena kekeringan."
  },
  AvgDialog_47808_Content_6 = {
    Text = "Aku sedang melihat... sungai ini."
  },
  AvgDialog_47808_Content_7 = {
    Text = "Sungai ini mengingatkanku pada Lemuria. Tanah airku juga pernah dihidupi oleh sungai agung seperti ini."
  },
  AvgDialog_47808_Content_8 = {
    Text = "Sebelum semua bencana terjadi, setiap malam musim panas para pemuda akan berkumpul di tepi sungai…… untuk menemukan pasangan seumur hidup, untuk membangun keluarga baru."
  },
  AvgDialog_47808_Content_9 = {
    Text = "Kedengarannya pasti sangat meriah. Bagaimana denganmu, Pharos? Apakah kau juga pernah ikut perkumpulan malam musim panas?"
  },
  AvgDialog_47977_Content_10 = {
    Text = "Baiklah, kembali ke topik. Tindakan kali ini bertujuan untuk mengamati aktivitas kesadaran di dalam tengkorak \"24\" melalui pemindaian, guna memberikan referensi untuk Sembuh selanjutnya."
  },
  AvgDialog_47977_Content_11 = {
    Text = "Jangan pergi ke tempat yang tidak seharusnya kamu kunjungi, kecuali kamu ingin terjebak selamanya dalam pikiran orang lain."
  },
  AvgDialog_47977_Content_12 = {
    Text = "Jangan bermalas-malas, dan jangan sampai tertidur!"
  },
  AvgDialog_47977_Content_13 = {
    Text = "<Shake: Saya memiliki beberapa teman yang menghilang seperti itu ribuan tahun yang lalu, hingga sekarang saya tidak tahu apakah mereka masih hidup atau sudah mati…>"
  },
  AvgDialog_47977_Content_14 = {
    Text = "...Saya akan memperhatikannya."
  },
  AvgDialog_47977_Content_15 = {
    Text = "Jangan khawatir, kami akan memperhatikan dengan cermat negaramu. Begitu ada perubahan situasi, tindakan akan segera dihentikan."
  },
  AvgDialog_47977_Content_16 = {
    Text = "Apakah kamu sudah siap, %player%?"
  },
  AvgDialog_47977_Content_17 = {
    Text = "Kamu menatap ruang-ruang yang saling terhubung di depanmu. Mereka mengembang dan berkontraksi secara teratur, bagian yang menonjol naik turun perlahan seiring napas, membuatmu teringat pada lautan yang luas tanpa batas."
  },
  AvgDialog_47977_Content_18 = {
    Text = "Adapun kamu, adalah seorang pelaut yang berdiri sendirian di atas dek."
  },
  AvgDialog_47977_Content_19 = {Text = "Siap!"},
  AvgDialog_47977_Content_2 = {
    Text = "Bangun? Perhatikan petunjuk berikut: lurus 100 mikrometer, lalu belok kanan kemudian belok kiri, lompat ke atas, dan terakhir masuk ke ventrikel ketiga…"
  },
  AvgDialog_47977_Content_20 = {
    Text = "Kalau begitu, mari kita berangkat. Kami dan \"24\" sangat menantikan hasil kerjamu."
  },
  AvgDialog_47977_Content_21 = {
    Text = "Selamat menikmati perjalanan, Penjaga."
  },
  AvgDialog_47977_Content_3 = {
    Text = "Tunggu, apa itu ventrikel ketiga——<ShakeBig:Uwaa, tangan saya?!>"
  },
  AvgDialog_47977_Content_4 = {
    Text = "Kamu bermaksud mengusap mata, tetapi tiba-tiba menyadari bahwa anggota tubuhmu telah berubah menjadi sinapsis yang lembut, melayang perlahan di lautan merah yang hangat."
  },
  AvgDialog_47977_Content_5 = {
    Text = "Jangan takut, Kerang telah melakukan beberapa iterasi kecil berdasarkan <Yellow:Yang berkelana>. Kesadaranmu sekarang melayang di dalam pikiran \"24\", dan semua yang kamu rasakan akan dikirim kembali ke terminal jarak jauh."
  },
  AvgDialog_47977_Content_6 = {
    Text = "Tubuh berubah menjadi kerucut, bahkan ada antena yang tumbuh di atas kepala!"
  },
  AvgDialog_47977_Content_7 = {
    Text = "Jangan sembarangan menyentuh! Tentakel-tentakel ini adalah organ penting yang membantu kamu merasakan lingkungan. Di planet asalku, mereka merupakan simbol status. Semakin panjang tentakelnya, semakin tinggi statusnya…"
  },
  AvgDialog_47977_Content_8 = {
    Text = "Mengerti. Jadi, apakah antena Nona Kerang juga sangat panjang?"
  },
  AvgDialog_47977_Content_9 = {
    Text = "Eh... itu, itu alami!"
  },
  AvgDialog_48091_Content_1 = {Text = "!"},
  AvgDialog_48091_Content_10 = {Text = "Ya!"},
  AvgDialog_48091_Content_11 = {
    Text = "Belum lama beristirahat, kamu menyadari Lily masih terus melirik dadamu dengan hati-hati, wajahnya penuh keraguan seolah ingin mengatakan sesuatu."
  },
  AvgDialog_48091_Content_12 = {
    Text = "Entah mengapa, kunci yang berkilau keperakan itu tampaknya memiliki daya tarik yang luar biasa bagi anak ini."
  },
  AvgDialog_48091_Content_13 = {
    Text = "<Gray:Di sekolah seharusnya tidak apa-apa, kan…>"
  },
  AvgDialog_48091_Content_14 = {
    Text = "Kamu ragu sesaat, tapi akhirnya melepas kunci perak itu dan meletakkannya di telapak tangannya yang mungil dan lembut."
  },
  AvgDialog_48091_Content_15 = {
    Text = "Dinginnya……"
  },
  AvgDialog_48091_Content_16 = {
    Text = "Apa terlalu dingin?"
  },
  AvgDialog_48091_Content_17 = {
    Text = "Tidak…… Sejuknya, nyaman sekali……"
  },
  AvgDialog_48091_Content_18 = {
    Text = "Dulu sekali, waktu Lily sakit, Mama akan memeluk Lily dan menceritakan dongeng sebelum tidur……"
  },
  AvgDialog_48091_Content_19 = {
    Text = "Biar aku ceritakan untukmu."
  },
  AvgDialog_48091_Content_2 = {
    Text = "Lily berbaring di dadamu, sama seperti pagi hari ketika kamu pertama kali terbangun di toko kecil Daphodel."
  },
  AvgDialog_48091_Content_20 = {
    Text = "Dahulu kala, di sebuah menara yang jauh, ada seorang putri dengan rambut yang sangat panjang……"
  },
  AvgDialog_48091_Content_21 = {
    Text = "Kamu menepuk-nepuk punggungnya dengan lembut, memandanginya perlahan terlelap dalam tidur yang damai."
  },
  AvgDialog_48091_Content_22 = {Text = "Mama……"},
  AvgDialog_48091_Content_23 = {
    Text = "Lily berbaring di pelukanmu, tertidur dengan tenang, napasnya teratur dan lembut. Kamu perlahan menarik selimut tipis dan menutupinya bersama bisul-bisul kecilnya."
  },
  AvgDialog_48091_Content_24 = {
    Text = "<Gray:Aku juga, agak mengantuk…>"
  },
  AvgDialog_48091_Content_25 = {
    Text = "Tapi yang lebih penting sekarang adalah menjaga momen kebahagiaan gadis kecil di hadapanmu ini."
  },
  AvgDialog_48091_Content_3 = {
    Text = "Berbeda dengan hari itu, tubuh mungilnya meringkuk, wajahnya merah merona."
  },
  AvgDialog_48091_Content_4 = {
    Text = "Tuan, sepertinya Lily demam."
  },
  AvgDialog_48091_Content_5 = {
    Text = "Aku antar kamu ke ruang kesehatan."
  },
  AvgDialog_48091_Content_6 = {
    Text = "Lily menggelengkan kepalanya dengan tegas, beberapa bisul ikut bergoyang bersamanya, berayun-ayun seperti balon yang saling berbenturan di tangan pedagang taman hiburan."
  },
  AvgDialog_48091_Content_7 = {
    Text = "Lily tidak mau disuntik."
  },
  AvgDialog_48091_Content_8 = {
    Text = "Kalau begitu, mau berbaring dan istirahat?"
  },
  AvgDialog_48091_Content_9 = {
    Text = "Kamu memiringkan badan, memberi sedikit ruang di sisi tempat tidur untuknya."
  },
  AvgDialog_48092_Content_1 = {
    Text = "Tunggu sebentar, Penjaga Rahasia, ada hal penting yang perlu kubicarakan denganmu."
  },
  AvgDialog_48092_Content_10 = {
    Text = "Dor langsung menarik tanganmu dan meletakkannya di pinggangnya."
  },
  AvgDialog_48092_Content_11 = {
    Text = [[
Belum cukup. Aku harus mengkatalisasi intensitas hasrat ini agar bisa melakukan pelacakan dan penentuan posisi secara real-time terhadap pikiran penyusup itu.
Dengan kata lain, jangan berhenti sebelum aku merasakan sesuatu.]]
  },
  AvgDialog_48092_Content_12 = {
    Text = "Ini…… kurang pantas, bukan……?"
  },
  AvgDialog_48092_Content_13 = {
    Text = [[
Tidak ada yang lebih tidak pantas daripada membiarkan pikiran abnormal bersarang di benakku.
Bagi dirimu sendiri, ini juga pengalaman langka, bukan?]]
  },
  AvgDialog_48092_Content_14 = {
    Text = "Kedua matanya menatapmu lekat-lekat. Kau merasa seperti kelinci malang yang tak bisa lari ke mana pun, diincar oleh seekor cheetah."
  },
  AvgDialog_48092_Content_15 = {
    Text = "Ini cuma misi, ini cuma misi……"
  },
  AvgDialog_48092_Content_16 = {
    Text = [[
Meyakinkan dirimu sendiri, kau mendekatkan bibirmu.
Sentuhan dingin dari tabung otak membuatmu sesak napas seketika.]]
  },
  AvgDialog_48092_Content_17 = {
    Text = "Titik-titik api berkilauan di pupil Dor, kau bisa merasakan tubuhnya gemetar dalam kegembiraan."
  },
  AvgDialog_48092_Content_18 = {
    Text = "Lokalisasi pikiran penyusup selesai."
  },
  AvgDialog_48092_Content_19 = {
    Text = "Selanjutnya, saatnya menjalankan prosedur pembersihan."
  },
  AvgDialog_48092_Content_2 = {
    Text = "Ada seseorang yang sedang menyusup ke dalam pikiranku."
  },
  AvgDialog_48092_Content_20 = {
    Text = "Jangan lepaskan tanganmu sebelum prosesnya selesai."
  },
  AvgDialog_48092_Content_3 = {
    Text = "Bagaimana kau bisa tahu……"
  },
  AvgDialog_48092_Content_4 = {
    Text = "Peradaban Alemethes sudah lama meninggalkan tubuh jasmani dan hasrat reproduksi. Pikiran usang dan terbelakang seperti ini, begitu muncul di benakku, sudah pasti berasal dari penyusupan luar."
  },
  AvgDialog_48092_Content_5 = {
    Text = "Perlu aku melakukan sesuatu untukmu?"
  },
  AvgDialog_48092_Content_6 = {
    Text = "Kemari, peluk aku."
  },
  AvgDialog_48092_Content_7 = {Text = "??"},
  AvgDialog_48092_Content_8 = {
    Text = "Meskipun agak canggung, kau tetap menurut dan memeluk tubuh mungil Dor. Helai rambut lembut yang bergelombang menyapu ujung hidungmu, menimbulkan rasa gatal yang sulit ditahan."
  },
  AvgDialog_48092_Content_9 = {
    Text = [[
Hal sekecil ini saja tidak bisa dilakukan dengan benar?
Lebih dekat lagi.]]
  },
  AvgDialog_48093_Content_1 = {
    Text = "Pen~ja~ga~ Ra~ha~sia~"
  },
  AvgDialog_48093_Content_10 = {
    Text = "Lilin di perutnya menyala sangat kuat, seolah hendak ikut membakar cahaya api di dasar matanya, cambuk berminyak mengecutkan udara dengan suara lecutan."
  },
  AvgDialog_48093_Content_11 = {
    Text = "Boleh kan, Penjaga Rahasia. Kau dan aku sudah sedekat ini, aku merasakan begitu banyak begitu banyak — begitu banyak cintamu~"
  },
  AvgDialog_48093_Content_12 = {
    Text = "Mmph mmph! Pan…diya! Puah pfft, tenang!"
  },
  AvgDialog_48093_Content_13 = {
    Text = "Perlawanan yang nyaris membabi buta memberimu secercah harapan hidup, kau dengan panik memuntahkan kain dari mulutmu, secara refleks memejamkan mata bersiap menghindari lecutan yang kau bayangkan…"
  },
  AvgDialog_48093_Content_14 = {
    Text = "Tapi cambuk itu hanya berhenti dengan lembut di ujung hidungmu."
  },
  AvgDialog_48093_Content_15 = {
    Text = "Mata Pandiya kehilangan fokus karena kebingungan, menggaruk-garuk wajahnya sendiri dengan gelisah dan kesal."
  },
  AvgDialog_48093_Content_16 = {
    Text = "Tidak, tidak, perasaan yang aku inginkan bukan ini~!"
  },
  AvgDialog_48093_Content_17 = {
    Text = "Apakah harus menampar wajah Penjaga Rahasia, atau menginjak-injak @2 Penjaga Rahasia dengan kaki, tidak tidak tidak, semuanya sa-lah!"
  },
  AvgDialog_48093_Content_18 = {
    Text = "Penculik yang gagal itu menjadi marah karena malu, pengaruh Sungai Suci membuatnya gelisah mengayunkan cambuknya sembarangan."
  },
  AvgDialog_48093_Content_19 = {
    Text = "Kenapa saat membayangkan melakukan @2 dan @2 pada Penjaga Rahasia, aku sama~ sekali tidak merasakan manisnya sensasi panas membara itu?"
  },
  AvgDialog_48093_Content_2 = {
    Text = "Mmph mmph mmph!"
  },
  AvgDialog_48093_Content_20 = {
    Text = "Pergulatan dengan tali tidak membuahkan kemenangan, otakmu sudah sepenuhnya berhenti bekerja, dan mulai secara otomatis melontarkan lelucon garing yang hambar."
  },
  AvgDialog_48093_Content_21 = {
    Text = "Kalau kamu memukul aku rasanya tidak pas, bagaimana kalau aku yang memukulmu?"
  },
  AvgDialog_48093_Content_22 = {
    Text = "Sebelum kamu sempat menelan lidahmu karena kalimat itu, pupil Pandiya tiba-tiba membesar."
  },
  AvgDialog_48093_Content_23 = {
    Text = "Benar juga! Kenapa aku tidak kepikiran, yang benar-benar~ benar-benar, benar-benar aku dambakan……!"
  },
  AvgDialog_48093_Content_24 = {
    Text = "Tubuhnya mulai gemetar pelan karena kegembiraan yang luar biasa."
  },
  AvgDialog_48093_Content_25 = {
    Text = "Selain lilin yang masih berkobar-kobar di dalam tubuhnya, semua cahaya di ruangan itu padam."
  },
  AvgDialog_48093_Content_26 = {
    Text = "Di bawah cahaya bulan, gadis itu membalik gagang cambuknya, menggigit cambuk kulitnya, suaranya menjadi kental dan tak jelas, seperti lapisan gula yang tak sabar untuk dicicipi…atau semacam kegelapan dingin yang berat dan lembap."
  },
  AvgDialog_48093_Content_27 = {
    Text = "Terdengar bunyi berdebum, tali yang mengikat lenganmu terjatuh."
  },
  AvgDialog_48093_Content_28 = {
    Text = "Hukumlah aku, cambuklah aku, siksa aku……"
  },
  AvgDialog_48093_Content_29 = {
    Text = "Seperti yang aku berikan kepada orang lain, berikan juga rasa sakit yang manis itu kepadaku~!"
  },
  AvgDialog_48093_Content_3 = {
    Text = "Aku sangat kesepian~ sangat sepi~ api kecil di dalam tubuhku terus menyala~"
  },
  AvgDialog_48093_Content_4 = {
    Text = "Rasanya hampir membakar seluruh tubuhku~! Kenapa kau tidak mau merespons aku~"
  },
  AvgDialog_48093_Content_5 = {
    Text = "(Mungkinkah itu karena kau menyumbat mulutku?!)"
  },
  AvgDialog_48093_Content_6 = {
    Text = "Dalam sistem pendidikan Misagar, tidak ada satu pun pelajaran yang mengajarkan bagaimana menghadapi tubuh Kebangkitan yang secara harfiah \"terbakar oleh gairah\" dalam situasi seperti ini."
  },
  AvgDialog_48093_Content_7 = {
    Text = "Lagipula, dia sudah hampir sepenuhnya menindih dadamu dengan pahanya yang licin seperti lilin cair."
  },
  AvgDialog_48093_Content_8 = {
    Text = "(Pandiya, kalau kau tidak segera bangun, aku akan mati lemas karena berat badanmu sebelum mati lemas karena gairahmu.)"
  },
  AvgDialog_48093_Content_9 = {
    Text = "Kau berusaha keras menyampaikan pesan rumit ini melalui tatapan mata, tapi jelas, perhatian gadis itu sama sekali tidak tertuju pada meningkatkan peluang hidupmu."
  },
  AvgDialog_48094_Content_1 = {
    Text = "Aegis? Yang lain bilang kamu sudah mengurung diri di kamar selama tiga hari."
  },
  AvgDialog_48094_Content_10 = {
    Text = "Tidak apa-apa, tidak apa-apa. Ini bukan salah Aigis……"
  },
  AvgDialog_48094_Content_11 = {
    Text = "Sambil menenangkannya, kau mendekatinya, solusi berkilat cepat di benakmu——"
  },
  AvgDialog_48094_Content_12 = {
    Text = "Jangan mendekat! Nanti kamu terluka……"
  },
  AvgDialog_48094_Content_13 = {
    Text = "Tidak apa-apa, aku kan satu-satunya Penjaga Rahasia. Waktu di panti asuhan dulu, Aigis juga tidak bisa mengubahku jadi batu, kan?"
  },
  AvgDialog_48094_Content_14 = {
    Text = "Agar emosi abnormal para Awakened Body bisa \"dilepaskan\", maka harus membimbing Aigis untuk membuka matanya——"
  },
  AvgDialog_48094_Content_15 = {
    Text = "Gadis kecil itu goyah, matanya terbuka sedikit——tapi detik berikutnya, kulit yang terekspos di tubuhmu mulai ditumbuhi sirup kuning kecokelatan yang lengket."
  },
  AvgDialog_48094_Content_16 = {
    Text = "Uwaaah!! Penjaga Rahasia {Male=tuan,Female=nyonya}!!"
  },
  AvgDialog_48094_Content_17 = {
    Text = "Huhu……Ini semua salah Aigis…Aigis seharusnya tidak membuka mata……"
  },
  AvgDialog_48094_Content_18 = {
    Text = "Tidak apa-apa, cuma selapis gula kan? Lihat, sekarang sudah tidak masalah lagi."
  },
  AvgDialog_48094_Content_19 = {
    Text = "Aigis mengerjapkan mata, merasakan panas yang seperti terbakar di tenggorokannya, dan menggerakkan mulutnya dengan ragu."
  },
  AvgDialog_48094_Content_2 = {
    Text = "Kamu mengetuk pintu kamar gadis itu, dan segera terdengar suara sesuatu yang jatuh dari dalam — seperti batu yang menghantam lantai dan pecah menjadi berkeping-keping."
  },
  AvgDialog_48094_Content_20 = {
    Text = "Suaranya terlalu kecil, Aigis."
  },
  AvgDialog_48094_Content_21 = {Text = "Uuu……"},
  AvgDialog_48094_Content_22 = {
    Text = "Bo, bolehkah minta tolong carikan Aigis cokelat panas? Cukup seteguk saja, bisa menyembuhkan penyakit Aigis……Nona Sarah pernah bilang begitu waktu masih ada."
  },
  AvgDialog_48094_Content_3 = {
    Text = "Suara apa itu? Aegis, aku masuk ya."
  },
  AvgDialog_48094_Content_4 = {
    Text = "Saat mendorong pintu kamar, kamu tidak merasakan hambatan seperti yang dibayangkan. Secara refleks kamu menoleh ke belakang: kunci pintu telah berubah menjadi lempengan batu yang tipis dan rapuh, sudah hancur berserakan di lantai akibat gerakanmu."
  },
  AvgDialog_48094_Content_5 = {
    Text = "Pe, Penjaga Rahasia {Male=tuan,Female=nyonya}……Ai, Aigis tidak apa-apa……"
  },
  AvgDialog_48094_Content_6 = {
    Text = "Aigis duduk di tengah ruangan yang bisa dibilang sudah seperti reruntuhan Romawi, kedua matanya terpejam erat."
  },
  AvgDialog_48094_Content_7 = {
    Text = "Ai, Aigis sepertinya demam……Mata besar juga tidak mau menuruti Aigis, setiap kali membuka mata, benda-benda berubah jadi batu……"
  },
  AvgDialog_48094_Content_8 = {
    Text = "Demam, lagi-lagi demam misterius dari Awakened Body."
  },
  AvgDialog_48094_Content_9 = {
    Text = "Kau langsung paham: ini lagi-lagi dampak dari insiden Lemvashi."
  },
  AvgDialog_48095_Content_1 = {
    Text = "1 usus buntu, 3 perut sapi, 16 gigi dari spesies berbeda, ditambah setumpuk besar tulang-tulang pecah……"
  },
  AvgDialog_48095_Content_10 = {
    Text = "Yuuhashi memamerkan sebuah tulang rahang berkilauan di hadapanmu seperti sedang menunjukkan harta karun. Di bawah sinar bulan, cahaya hijau redup berpendar dari sela-sela giginya."
  },
  AvgDialog_48095_Content_11 = {
    Text = "Bagaimana, menarik kan? Hahahaha!!"
  },
  AvgDialog_48095_Content_12 = {
    Text = "<Shake:Uwaaaaaaaa——!!>"
  },
  AvgDialog_48095_Content_13 = {
    Text = "Kamu menepis tangan Yuuha dengan keras. Tulang rahang itu tidak sengaja jatuh ke tanah dan seketika pecah menjadi dua."
  },
  AvgDialog_48095_Content_14 = {
    Text = "@3! Aku susah payah membelinya dari pelayan itu..."
  },
  AvgDialog_48095_Content_15 = {
    Text = "Pelayan? Jangan-jangan Garen... Berapa yang kamu bayar?"
  },
  AvgDialog_48095_Content_16 = {
    Text = "Aku tidak tahu namanya, pokoknya makhluk aneh yang seluruh tubuhnya hijau. Kira-kira 100 Leofang."
  },
  AvgDialog_48095_Content_17 = {
    Text = "Dia bilang ini koleksi agung dari Dinasti Lemvasi ke-108."
  },
  AvgDialog_48095_Content_19 = {
    Text = "Kamu ditipu. Dinasti Lemvasi hanya sampai generasi ke-30, dan tulang ini kemungkinan disambung-sambung, kalau tidak, tidak mungkin sepecah ini."
  },
  AvgDialog_48095_Content_2 = {
    Text = "Kau melemparkan karung goni berlumuran darah dengan keras ke hadapan Youwu."
  },
  AvgDialog_48095_Content_20 = {
    Text = "Berani-beraninya menipu aku... Hehe. Tunggu sepuluh menit, aku mau pergi membunuh makhluk hijau itu."
  },
  AvgDialog_48095_Content_21 = {
    Text = "Tunggu dulu, Yuuhashi."
  },
  AvgDialog_48095_Content_22 = {
    Text = "Kamu memungut pecahan di tanah dan meletakkannya perlahan di tangan Yuuha."
  },
  AvgDialog_48095_Content_23 = {
    Text = "Terima kasih atas hadiahmu. Tapi lain kali sebelum memberiku sesuatu, aku harap kamu bisa bertanya dulu pendapatku."
  },
  AvgDialog_48095_Content_24 = {
    Text = "Yuuhashi menundukkan kepala, sosok tubuhnya yang tinggi besar menutupi cahaya bulan di belakangnya, tampak seperti seekor singa yang jinak."
  },
  AvgDialog_48095_Content_25 = {
    Text = "Kukira kau akan menyukainya. Aku jelas-jelas mencium aroma sejenis dari tubuhmu, apalagi beberapa hari terakhir ini——"
  },
  AvgDialog_48095_Content_26 = {
    Text = "Meskipun sejenis, belum tentu menyukai hal yang persis sama. Kalau kau berpikir begitu, artinya kita belum cukup saling mengenal, bukan?"
  },
  AvgDialog_48095_Content_27 = {
    Text = "Yuuhashi mengernyit dengan tidak nyaman. Ini bukan suasana percakapan yang biasa baginya."
  },
  AvgDialog_48095_Content_28 = {
    Text = "……Oh. Kalau begitu, sebutkan sesuatu yang kau suka."
  },
  AvgDialog_48095_Content_29 = {
    Text = "<Small:Kalau soal yang kusukai, kue lemon dari Toko Roti Sam di Lincoln High Street lumayan enak, ingat minta dia tambahkan lebih banyak frosting dan custard, oh ya jangan terlalu banyak krim kalau tidak Ramona akan mengeluh……>"
  },
  AvgDialog_48095_Content_3 = {
    Text = "Kalau penglihatanku tidak salah kemarin, orang yang diam-diam memanjat masuk ke asramaku dan melemparkan barang-barang sembarangan ke dalam adalah kamu."
  },
  AvgDialog_48095_Content_31 = {
    Text = "Baik, akan kubelikan untukmu. Tapi sebelum itu aku harus menyelesaikan urusan dengan si monster rambut hijau itu dulu, berani-beraninya mempermainkan aku……"
  },
  AvgDialog_48095_Content_32 = {
    Text = "Terserah kalian mau ribut apa, asal jangan sampai ada yang mati."
  },
  AvgDialog_48095_Content_33 = {
    Text = "Yuuhashi berjalan ke jendela dengan gusar, lalu seperti tiba-tiba teringat sesuatu, ekspresinya menjadi sangat canggung."
  },
  AvgDialog_48095_Content_34 = {
    Text = "Kau……jaga dirimu baik-baik, besok aku akan datang lagi menemuimu."
  },
  AvgDialog_48095_Content_35 = {
    Text = "Setelah berkata demikian, ia melompat keluar. Sosok kurusnya berkilat sesaat di bawah cahaya bulan lalu menghilang."
  },
  AvgDialog_48095_Content_36 = {
    Text = "Sampai jumpa besok, Yuuhashi."
  },
  AvgDialog_48095_Content_37 = {
    Text = "Kamarku punya pintu, <Big:lain kali tolong lewat pintu depan——!!>"
  },
  AvgDialog_48095_Content_4 = {
    Text = "Yuuhashi, ada yang mau kamu jelaskan soal ini?"
  },
  AvgDialog_48095_Content_5 = {
    Text = "……Hmph."
  },
  AvgDialog_48095_Content_6 = {
    Text = "Berkat ulahmu, semua orang tidak mau mendekat ke asramaku. Sekarang aku tercium seperti kubis busuk."
  },
  AvgDialog_48095_Content_7 = {
    Text = "Sepertinya kamu tidak suka hadiah-hadiah yang kuberikan. Hehe, kukira kita punya selera yang mirip..."
  },
  AvgDialog_48095_Content_8 = {
    Text = "<Gray:Demi Sang Bapa, apa yang sudah kulakukan sampai dia punya kesalahpahaman seperti ini.>"
  },
  AvgDialog_48095_Content_9 = {
    Text = "Kamu benar-benar tidak mau menerima tulang rahang ini? Kalau dilihat malam-malam ada kejutannya lho."
  },
  AvgDialog_48096_Content_1 = {
    Text = "Aduh, Dole molor lagi, kelas berikutnya di Gedung F, bagaimana ini."
  },
  AvgDialog_48096_Content_10 = {
    Text = "Asalkan menambahkanmu, asalkan menambahkanmu ke dalam semuanya, bencana hitam itu akan menjadi sangat jauh. Harus tetap bersamamu, kalau tidak hal buruk akan terjadi, hal buruk yang hitam akan terjadi……"
  },
  AvgDialog_48096_Content_11 = {
    Text = "Terang, terang, jiwa yang terang……kamu sangat bersinar……di sekitarmu pasti sangat aman……"
  },
  AvgDialog_48096_Content_12 = {
    Text = "Gumaman kecilnya melintas di telingamu, kamu sudah tidak bisa mempedulikan hal itu lagi, karena——"
  },
  AvgDialog_48096_Content_13 = {
    Text = "Winkel, lepaskan, bel masuk sudah berbunyi aku akan terlambat, <BigShake:Winkel!>"
  },
  AvgDialog_48096_Content_2 = {Text = "<Big:Ah!>"},
  AvgDialog_48096_Content_3 = {
    Text = "Hantaman besar dari belakang membuatmu terhuyung-huyung, nyaris terjatuh ke tanah."
  },
  AvgDialog_48096_Content_4 = {
    Text = "Wenkoer? Kau ini……?"
  },
  AvgDialog_48096_Content_5 = {
    Text = "Maaf maaf maaf, a-aku tidak sengaja! Aku hanya harus bersamamu, harus……"
  },
  AvgDialog_48096_Content_6 = {
    Text = "……Wenkoer?"
  },
  AvgDialog_48096_Content_7 = {
    Text = "Aku mencoba menggunakan rumus @3 dan konjektur @1@4 untuk menghitung jarak antara Bencana Hitam dengan kita, tapi hasilnya selalu salah, selalu salah……"
  },
  AvgDialog_48096_Content_8 = {
    Text = "Akhirnya aku menemukan bahwa aku melewatkan satu variabel, sebuah jiwa yang paling terang——"
  },
  AvgDialog_48096_Content_9 = {
    Text = "Yaitu kamu!"
  },
  AvgDialog_48139_Content_1 = {
    Text = "——Gemerimincing."
  },
  AvgDialog_48139_Content_10 = {
    Text = "Kalau soal minta tolong, kamu bisa langsung datang ke Misage untuk mencariku— hmph?!"
  },
  AvgDialog_48139_Content_11 = {
    Text = "Dia mencekik tenggorokanmu dengan satu tangan, lendir di sekujur tubuhnya berubah menjadi bilah tajam yang menyobek kerah seragam sekolahmu. Mata pisau menempel di leher, membuat setiap tarikan napasmu berada dalam bahaya."
  },
  AvgDialog_48139_Content_12 = {
    Text = "Sst……pelan sedikit. Pustula-pustula ini tidak boleh dikejutkan."
  },
  AvgDialog_48139_Content_13 = {
    Text = "Satu jari ditekan ke bibirmu. Atas isyarat Hilo, kamu menoleh ke arah pustula di belakangnya——"
  },
  AvgDialog_48139_Content_14 = {
    Text = "Pustula-pustula baru ini lahir dari pembelahan diriku, tapi mereka belum memiliki kesadaran diri……belum bisa menjadi kekuatan untuk membantuku membalas dendam."
  },
  AvgDialog_48139_Content_15 = {
    Text = "Masih belum cukup memiliki kesadaran diri?"
  },
  AvgDialog_48139_Content_16 = {
    Text = "Pustula-pustula itu berperilaku sangat aktif. Sekarang mereka menempel di kakimu, saling bertabrakan sambil mengeluarkan suara kecipak yang aneh."
  },
  AvgDialog_48139_Content_17 = {
    Text = "Tidak cukup, makanya aku butuh bantuanmu."
  },
  AvgDialog_48139_Content_18 = {Text = "Aku?"},
  AvgDialog_48139_Content_19 = {
    Text = "Shilo dengan paksa menarik tanganmu dan menekannya ke paha yang terekspos. Sentuhan lengket itu diam-diam menyelinap masuk melalui kerah yang terbuka."
  },
  AvgDialog_48139_Content_2 = {
    Text = "Gerakan bangkit menarik rantai, suara benturan logam terus bergema dalam kegelapan."
  },
  AvgDialog_48139_Content_20 = {
    Text = "Hei?! Shilo, apa yang mau kamu lakukan?!"
  },
  AvgDialog_48139_Content_21 = {
    Text = "Mereka melintasi setiap inci kulit dengan lembab, seperti air yang mengalir ke dasar sungai, terus turun mengikuti tekstur otot."
  },
  AvgDialog_48139_Content_22 = {
    Text = "Pemiliknya menggenggam erat tanganmu. Kedua mata merah delima itu tampak sangat menyala, seolah akan segera terbakar habis."
  },
  AvgDialog_48139_Content_23 = {
    Text = "Gunakan Kognisi-mu, anugerahkan kepada mereka \"kesadaran\" yang sesungguhnya."
  },
  AvgDialog_48139_Content_3 = {
    Text = "Kamu sudah bangun. Tidak ada waktu untuk disia-siakan, mari kita mulai."
  },
  AvgDialog_48139_Content_4 = {
    Text = "Suara ini… Hilo?! Apa yang kamu lakukan? Kukira kesalahpahaman di antara kita sudah terselesaikan."
  },
  AvgDialog_48139_Content_5 = {
    Text = "Sekarang mengikatku di sini ini maksudnya apa?"
  },
  AvgDialog_48139_Content_6 = {
    Text = "Memang benar……tidak ada lagi konflik kepentingan di antara kita."
  },
  AvgDialog_48139_Content_7 = {
    Text = "Hilo berlutut dengan satu kaki di hadapanmu, menggunakan lendir di tangannya untuk melarutkan rantai besi yang membelenggu kakimu."
  },
  AvgDialog_48139_Content_8 = {
    Text = "Sudah kulepaskan, tapi jangan berpikir untuk kabur. Jalur bawah tanah ini sudah terbengkalai akibat pertempuran kita, kamu juga tidak akan menemukan bantuan lain."
  },
  AvgDialog_48139_Content_9 = {
    Text = "Aku butuh bantuanmu."
  },
  AvgDialog_48142_Content_1 = {
    Text = "Di tengah kesibukan Anda, Anda masih bersedia meluangkan waktu berharga untuk datang jauh-jauh ke Katedral Agung. Kebaikan ini akan selalu kukenang seumur hidupku."
  },
  AvgDialog_48142_Content_10 = {
    Text = "…Aku mengerti.\nRuntuhnya Pohon Suci Lemvashi menyebabkan para Awakened di seluruh dunia mengalami… yang sangat kuat…"
  },
  AvgDialog_48142_Content_11 = {
    Text = "Uhuk, uhuk, yang sangat kuat…"
  },
  AvgDialog_48142_Content_12 = {
    Text = "Begitu rupanya, \"hasrat untuk berkembang biak\" yang terkatalisis secara abnormal sedang memanggilku."
  },
  AvgDialog_48142_Content_13 = {
    Text = "Maaf, aku kehilangan ketenangan."
  },
  AvgDialog_48142_Content_14 = {
    Text = "……Tidak, tidak ada apa-apa. A-aku mengampuni dosamu, apakah cukup mengatakan itu saja?"
  },
  AvgDialog_48142_Content_15 = {
    Text = "Saya yang lalai, Anda belum pernah memiliki pengalaman dalam pengakuan dosa."
  },
  AvgDialog_48142_Content_16 = {
    Text = "Salvador membuka jendela kecil ruang pengakuan dosa, meletakkan kedua tangannya di kusen jendela, dengan telapak tangan menghadap ke atas ke arahmu."
  },
  AvgDialog_48142_Content_17 = {
    Text = "Jika berkenan, tolong genggam tanganku."
  },
  AvgDialog_48142_Content_18 = {
    Text = "(Mengulurkan kedua tangan)"
  },
  AvgDialog_48142_Content_19 = {
    Text = "Meskipun kalian berdua mengenakan sarung tangan, itu tak mampu menghalangi suhu tubuhnya yang luar biasa. Seperti nyala api yang membara saat jiwa mendidih, membakar nadimu tanpa bisa ditahan."
  },
  AvgDialog_48142_Content_2 = {
    Text = "Tidak perlu sungkan, selama aku bisa membantu Uskup Salvado…"
  },
  AvgDialog_48142_Content_20 = {
    Text = "Kunci perak di dadamu juga memanas membara, membuat jiwa kalian terkelupas lapis demi lapis, hanya menyisakan inti yang paling telanjang dan terbuka."
  },
  AvgDialog_48142_Content_21 = {
    Text = "Selanjutnya, tolong ulangi kata-kataku."
  },
  AvgDialog_48142_Content_22 = {
    Text = "Dosa bagaikan belenggu, namun kunci pengampunan dan penebusan juga tersimpan di atas belenggu itu."
  },
  AvgDialog_48142_Content_23 = {
    Text = "Dosa bagaikan belenggu, namun kunci pengampunan dan penebusan juga tersimpan di atas belenggu itu."
  },
  AvgDialog_48142_Content_24 = {
    Text = "Hatinya telah habis terbakar oleh derita kebajikan, ia telah merasakan buah pahitnya."
  },
  AvgDialog_48142_Content_25 = {
    Text = "Hatinya telah habis terbakar oleh derita kebajikan, ia telah merasakan buah pahitnya……"
  },
  AvgDialog_48142_Content_26 = {
    Text = "Sebuah kilatan inspirasi bagai petir menyatukan kata-kata di benakmu, dan sebelum Salvador melanjutkan, sebuah naluri mengendalikanmu untuk bersuara lebih dulu."
  },
  AvgDialog_48142_Content_27 = {
    Text = "……Bapa yang penuh belas kasih, izinkanlah ia berjalan dalam terang, ampunilah dosanya."
  },
  AvgDialog_48142_Content_28 = {
    Text = "Anda juga mendengar bimbingan Bapa……"
  },
  AvgDialog_48142_Content_29 = {
    Text = "Utusan yang pucat, terima kasih telah sekali lagi mengusir kegelapanku."
  },
  AvgDialog_48142_Content_3 = {
    Text = "Ruang pengakuan dosa ini remang dan sempit. Kamu duduk gelisah di kursi kayu ek, tetapi rasa \"penasaran\" mengapa kamu dipanggil ke sini jauh melampaui rasa cemas."
  },
  AvgDialog_48142_Content_4 = {
    Text = "Biasanya, Salvado-lah yang duduk di ruang pengakuan dosa. Tapi begitu kamu tiba di Katedral Agung, dia langsung memintamu duduk di sini. Pasti ada alasan khusus."
  },
  AvgDialog_48142_Content_5 = {
    Text = "Izinkan aku melewatkan basa-basi yang lebih panjang, Api Pucat, dan dengarkanlah pengakuanku."
  },
  AvgDialog_48142_Content_6 = {
    Text = "Belakangan ini, aku… entah mengapa muncul hasrat yang seharusnya tidak ada."
  },
  AvgDialog_48142_Content_7 = {
    Text = "Suaranya bagaikan gema dari pegunungan jauh, perlahan-lahan tenggelam dan meresap ke dinding kayu kuno ruang pengakuan dosa. Suara beratnya mengekang seekor binatang buas tak bernama, takut ia menyentuh tabu yang tak terlihat."
  },
  AvgDialog_48142_Content_8 = {
    Text = "Aku harus mengakui, meskipun aku mengetahui hasrat-hasrat ini, aku belum pernah benar-benar merasakannya, apalagi mengerti bagaimana mereka bisa mengalahkan kemuliaan Sang Bapa dan merasuki hatiku."
  },
  AvgDialog_48142_Content_9 = {
    Text = "Namun, sebagaimana tabib pun membutuhkan pengobatan, aku yang seorang wakil ini pun perlu mengaku dosa kepada utusan Sang Bapa, memohon bimbingan dan pengampunan."
  },
  AvgDialog_48238_Content_1 = {
    Text = "Apakah sudah merasa lebih baik, Liz?"
  },
  AvgDialog_48238_Content_10 = {
    Text = "Sebuah tangan terulur dari atas panggung, dengan anggun teracung di hadapanmu."
  },
  AvgDialog_48238_Content_11 = {
    Text = "Aku? Tapi aku belum pernah... Hei..."
  },
  AvgDialog_48238_Content_12 = {
    Text = "Sebelum kau sempat menyelesaikan kalimatmu, tangan itu tanpa basa-basi menarikmu ke atas panggung."
  },
  AvgDialog_48238_Content_13 = {
    Text = "...Tolong pegang pinggangku, Penjaga Rahasia."
  },
  AvgDialog_48238_Content_14 = {
    Text = "Aku masih belum bisa menari, tapi kurasa, aku bisa mengajarkan gerakan-gerakan indah itu kepadamu."
  },
  AvgDialog_48238_Content_15 = {
    Text = "Kau sendiri yang bilang mau membantuku mengatasi pengaruh Sungai Suci..."
  },
  AvgDialog_48238_Content_16 = {
    Text = "Saat tangan itu menuntun tanganmu untuk bertumpu di pinggangnya, tubuhnya yang proporsional bergetar sesaat."
  },
  AvgDialog_48238_Content_17 = {
    Text = "Ujung jarimu merasakan sentuhan dingin sutra. Di balik sutra itu, pinggang dan perut yang lembut nan kencang naik-turun perlahan mengikuti irama napas."
  },
  AvgDialog_48238_Content_18 = {
    Text = "Aku sama sekali belum pernah menyentuh balet... Apa ini benar-benar tidak apa-apa?"
  },
  AvgDialog_48238_Content_19 = {
    Text = "Ikuti musiknya, lakukan apa yang ingin kaulakukan, itu saja."
  },
  AvgDialog_48238_Content_2 = {
    Text = "Di dalam teater yang kosong tanpa seorang pun, gadis itu menggelengkan kepalanya. Kau mendengar napasnya yang tak beraturan, melihat pipinya yang sedikit memerah di bawah cahaya redup."
  },
  AvgDialog_48238_Content_20 = {
    Text = "Ingatlah, rahasia balet adalah putaran."
  },
  AvgDialog_48238_Content_21 = {
    Text = "Dari kedua tangan ke pinggang, dari pinggang ke kedua kaki. Sang penari menuntunmu, menyelesaikan setiap gerakan anggun, merasakan setiap perubahan halus di setiap bagian tubuhnya."
  },
  AvgDialog_48238_Content_22 = {
    Text = "Tendangan kaki. Lengkungan badan. Lompatan."
  },
  AvgDialog_48238_Content_23 = {
    Text = "Musik yang ringan bergema di teater yang kosong tanpa penonton, seberkas cahaya dingin mengikuti kalian berdua di atas panggung."
  },
  AvgDialog_48238_Content_24 = {
    Text = "Kalian berputar bersama. Wajah Liz semakin merona merah, kedua mata hijaunya menatapmu dengan malu-malu."
  },
  AvgDialog_48238_Content_25 = {
    Text = "Bagaimana tarianku?"
  },
  AvgDialog_48238_Content_26 = {
    Text = "Tidak ada apa-apanya. Tapi ini akan menjadi pertunjukan tari favoritku, Penjaga Rahasia."
  },
  AvgDialog_48238_Content_27 = {
    Text = "Mau kita berputar lebih pelan sedikit? Aku merasa agak……"
  },
  AvgDialog_48238_Content_28 = {
    Text = "Mata hijau itu perlahan terpejam, bibir dingin itu mencium bibirmu."
  },
  AvgDialog_48238_Content_29 = {
    Text = "Berputar. Berputar."
  },
  AvgDialog_48238_Content_3 = {
    Text = "Awalnya kukira, teater bisa membuatmu merasa tenang, menghilangkan pengaruh Sungai Suci."
  },
  AvgDialog_48238_Content_30 = {
    Text = "Helaian rambut putih berkibar tertiup angin, api zamrud menyelimuti kalian berdua, tanpa suhu apa pun, menari mengikuti irama musik. Kostum tari hitam-hijau itu mengukir lengkungan bak angsa di udara."
  },
  AvgDialog_48238_Content_31 = {
    Text = "Pusing. Kau ingin bilang pusing."
  },
  AvgDialog_48238_Content_32 = {
    Text = "Napas Liz yang semakin berat menerpa wajahmu, secara refleks kedua lenganmu memeluk erat pinggangnya, kekuatan yang besar itu membuatnya sedikit mengernyit. Kalian terus berputar."
  },
  AvgDialog_48238_Content_33 = {
    Text = "Ingatlah, Penjaga Rahasia. Rahasia balet adalah berputar……"
  },
  AvgDialog_48238_Content_34 = {
    Text = "Malam ini, di bawah cahaya gemerlap teater, sepasang penari tersesat dalam putaran."
  },
  AvgDialog_48238_Content_4 = {
    Text = "Mungkin kita bisa melakukan sesuatu yang lain untuk mengalihkan perhatian. Biar kupikirkan……"
  },
  AvgDialog_48238_Content_5 = {
    Text = "Mata hijaunya berkilau, rok hitamnya mengayun membentuk busur di hadapanmu, gadis itu dengan lincah naik ke atas panggung."
  },
  AvgDialog_48238_Content_6 = {
    Text = "Kupikir, kau masih punya beban di hati soal menari..."
  },
  AvgDialog_48238_Content_7 = {
    Text = "Aku tidak bilang mau menari."
  },
  AvgDialog_48238_Content_8 = {
    Text = "Lalu maksudmu...?"
  },
  AvgDialog_48238_Content_9 = {
    Text = "Biar kuajari kau menari, Penjaga Rahasia."
  },
  AvgDialog_48555_Content_1 = {
    Text = "Melewati tikungan lain di gedung pengajaran, tekanan rendah yang menyelimutimu sejak pagi tadi semakin parah, menekanmu hingga hampir tak bisa bernapas."
  },
  AvgDialog_48555_Content_10 = {
    Text = "Kantung bulat itu memancarkan cahaya redup di telapak tanganmu, mengalirkan vitalitas kehidupan yang dahsyat."
  },
  AvgDialog_48555_Content_11 = {
    Text = "Di balik dinding kantung yang semi-transparan, ranting-ranting menyerupai sayap jangkrik saling mengatup berpasangan, sesekali mengepakkan sayap tanpa pola, seolah sedang berada dalam mimpi panjang yang tak berujung."
  },
  AvgDialog_48555_Content_12 = {Text = "Ini……?"},
  AvgDialog_48555_Content_13 = {
    Text = "Feint melihat kau tidak menolak hadiahnya, barulah menghela napas lega dan menampakkan senyum puas."
  },
  AvgDialog_48555_Content_14 = {
    Text = "Ini adalah benih baru dari ras @2 kami, selama kami sudah matang, kami semua akan menghasilkan buah seperti ini."
  },
  AvgDialog_48555_Content_15 = {
    Text = "Selama waktu yang begitu lama, begitu lama, aku tidak pernah bertunas…… Aku awalnya mengira, aku tidak akan pernah menjadi @2 yang utuh."
  },
  AvgDialog_48555_Content_16 = {
    Text = "<Small:Perkembangan abnormal…… lagi-lagi pengaruh yang dibawa dari sisi Lemvashi.>"
  },
  AvgDialog_48555_Content_17 = {
    Text = "Bagaimana perasaan Feint sekarang? Setelah bertunas, apakah ada kelainan lain pada tubuhmu?"
  },
  AvgDialog_48555_Content_18 = {
    Text = "Feint menggelengkan kepalanya, wajah mudanya dipenuhi kegembiraan."
  },
  AvgDialog_48555_Content_19 = {
    Text = "Panas…… Kepala dan anggota tubuhku terasa sangat panas. Mungkin inilah yang pernah dikatakan Tincture, rasanya menjadi dewasa?"
  },
  AvgDialog_48555_Content_2 = {
    Text = "Kau berpegangan pada dinding dan berjongkok, di sela gerakanmu pandanganmu menangkap bayangan familiar yang melintas sekilas."
  },
  AvgDialog_48555_Content_3 = {
    Text = "……Feint? Apakah itu kau?"
  },
  AvgDialog_48555_Content_4 = {
    Text = "Bayangan putih itu terdiam sejenak, akhirnya tak lagi menyembunyikan keberadaannya. Kerangka putih membawa pemiliknya melayang ke hadapanmu."
  },
  AvgDialog_48555_Content_5 = {
    Text = "……Penjaga Rahasia."
  },
  AvgDialog_48555_Content_6 = {
    Text = "Dia mengulurkan tangan ke arahmu, seolah ingin memanjat keluar dari \"Buaian\" — tetapi meninggalkan \"Buaian\" sebagai pembatas hanya akan membuat nalurinya semakin tak terkendali."
  },
  AvgDialog_48555_Content_7 = {
    Text = "Feint segera menyadari keanehan pada dirinya, sehingga akhirnya hanya mengatupkan bibir, dan melepas kantung bulat yang paling dekat dengan tubuhnya dari \"Buaian\"."
  },
  AvgDialog_48555_Content_8 = {
    Text = "Tolong terima…… terima ini."
  },
  AvgDialog_48555_Content_9 = {
    Text = "Kau mengulurkan tangan, saat mengambil kantung bulat itu ujung jarimu menyentuh telapak tangannya yang lembut. Feint langsung gemetar seluruh tubuh, meringkuk bersembunyi lebih dalam ke dalam buaian."
  },
  AvgDialog_48556_Content_1 = {
    Text = "Penjaga Rahasia, jika tidak keberatan, bisakah Anda berhenti sejenak untuk saya sekarang?"
  },
  AvgDialog_48556_Content_10 = {
    Text = "Itu sama sekali bukan melodi yang seharusnya ada di Kadath, suara yang mengalir ke girus temporal transversal itu semisterius alam semesta, namun berkilauan dengan kelembutan bintang fajar."
  },
  AvgDialog_48556_Content_11 = {
    Text = "Kesadaran menjadi sebuah perahu tanpa kemudi, dituntun oleh nyanyian Tincture, menghanyut menuju tepian hasrat."
  },
  AvgDialog_48556_Content_12 = {
    Text = "Sentuhan dingin dan lembap tercetak di sudut bibir, api tak bernama menjalar di tenggorokan."
  },
  AvgDialog_48556_Content_13 = {
    Text = "Saat membuka mata lagi, Tincture juga sedang mendongak, bibirnya tampak sangat lembap dan penuh."
  },
  AvgDialog_48556_Content_14 = {
    Text = "Sebuah jawaban yang tak terbayangkan hampir meluncur dari mulutmu, tetapi akal sehat segera tersapu oleh nyanyian yang kembali mendarat di tepi bibirmu."
  },
  AvgDialog_48556_Content_15 = {
    Text = "Nyanyian itu mempermainkan hasrat terpendam di lubuk hati terdalam, batas antara kenyataan dan khayalan kembali kabur, tak berdaya melawan, tak berdaya melarikan diri."
  },
  AvgDialog_48556_Content_16 = {
    Text = "Ssst…… hanya malam ini, jadilah tawanan nyanyianku……"
  },
  AvgDialog_48556_Content_2 = {
    Text = "Tentu, apa kamu mengalami sesuatu yang tidak menyenangkan di sekolah akhir-akhir ini?"
  },
  AvgDialog_48556_Content_3 = {
    Text = "Ti-tidak…… bukan seperti itu."
  },
  AvgDialog_48556_Content_4 = {
    Text = "Hanya saja ada sebuah lagu yang bagaimanapun juga…… ingin sekali saya nyanyikan untuk Anda."
  },
  AvgDialog_48556_Content_5 = {
    Text = "Kau mengangguk, lalu duduk kembali di sofa ruang istirahat — hanya sebuah lagu saja."
  },
  AvgDialog_48556_Content_6 = {
    Text = "Kegelisahan di antara alis dan mata Tubuh Kebangkitan itu lenyap dalam sekejap, wajah yang begitu indah bak bukan milik dunia fana itu mengembangkan sebuah senyuman yang tak kau pahami —"
  },
  AvgDialog_48556_Content_7 = {
    Text = "Sebuah lagu yang lahir hanya karena Anda, dan juga lagu yang dinyanyikan hanya untuk Anda."
  },
  AvgDialog_48556_Content_8 = {
    Text = "Kesadaranmu, saat nyanyian itu memasuki telinga, terseret masuk ke dalam dunia ilusi yang samar."
  },
  AvgDialog_48556_Content_9 = {
    Text = "Nyanyian Tincture melewati pertahanan akal sehat, menyelinap melalui celah-celah raga hingga merasuk ke dalam jiwa —"
  },
  AvgDialog_48596_Content_1 = {
    Text = "Berdasarkan petunjuk yang diberikan Erica, jubah gantiku terakhir kali terlihat di luar asrama lama Kebangkitan……"
  },
  AvgDialog_48596_Content_10 = {Text = "Ha-hantu?!"},
  AvgDialog_48596_Content_11 = {
    Text = "Brown, ayo kita pergi—— Kamu juga, ngapain masih bengong di situ!"
  },
  AvgDialog_48596_Content_12 = {
    Text = "Jenkin dengan panik menarik tanganmu, ingin menyeretmu keluar dari \"Rumah Penyihir\" ini. Tapi suhu yang tidak biasa di telapak tangannya langsung membuatmu menyadari ada yang tidak beres."
  },
  AvgDialog_48596_Content_13 = {
    Text = "<Small:Pengaruh Lermwashi……>"
  },
  AvgDialog_48596_Content_14 = {
    Text = "Tanpa menghiraukan ekspresi tegang Jenkin, kamu selangkah lebih dulu membuka lemari pakaian. Berbagai macam kain berjatuhan menimpamu, menguburmu sepenuhnya di bawahnya."
  },
  AvgDialog_48596_Content_15 = {
    Text = "%player%?! Jangan mati dong!"
  },
  AvgDialog_48596_Content_16 = {Text = "Cit cit!!!"},
  AvgDialog_48596_Content_17 = {
    Text = "Jenkin dan Brown bekerja sama menyelamatkanmu dari bawah tumpukan jubahmu yang hilang, kemeja barumu, selimut musim dingin yang jelas-jelas sudah kamu simpan rapi, serta pakaian-pakaian lainnya."
  },
  AvgDialog_48596_Content_2 = {
    Text = "Uhuk, uhuk, penuh debu…… Tempat ini sepertinya sudah terbengkalai bertahun-tahun, benarkah ada orang di——sini?"
  },
  AvgDialog_48596_Content_20 = {
    Text = "Kamu……baik-baik saja?"
  },
  AvgDialog_48596_Content_21 = {
    Text = "Kenapa kamu mencuri…… kenapa kamu mengumpulkan pakaianku?"
  },
  AvgDialog_48596_Content_22 = {
    Text = "Jenkins bergumam pelan, tubuhnya sudah bersiap dalam posisi untuk kabur kapan saja."
  },
  AvgDialog_48596_Content_23 = {
    Text = "Kamu dengan pasrah berjongkok, menyandera seorang \"sandera\". Brown mengeluarkan pekikan aneh, matanya yang bulat membelalak lebar, tampak sangat polos."
  },
  AvgDialog_48596_Content_24 = {
    Text = "Brown—Baiklah! Aku bicara! Aku bicara!"
  },
  AvgDialog_48596_Content_25 = {
    Text = "Karena aku sudah masuk masa cubercas. Kakak pernah bilang, saat masa cubercas, akan ada pikiran-pikiran aneh di kepala."
  },
  AvgDialog_48596_Content_26 = {
    Text = "Itu masa pubertas."
  },
  AvgDialog_48596_Content_27 = {
    Text = "Iya iya! Pubertas! Sepertinya kalau di diriku, itu terwujud sebagai keinginan kuat untuk mencuri barang-barangmu. Ini bukti bahwa aku menghargaimu lho!"
  },
  AvgDialog_48596_Content_28 = {
    Text = "Kamu menarik tudungnya ke bawah, menggelengkan kepala sambil tertawa di tengah seruan \"aduh\"-nya."
  },
  AvgDialog_48596_Content_29 = {
    Text = "Masa pubertasmu belum datang secepat itu. Istirahatlah lebih awal beberapa hari ini, dan kamu akan segera kembali seperti semula."
  },
  AvgDialog_48596_Content_3 = {
    Text = "Dua jejak kaki membentang dari tangga menuju ruangan di ujung lorong. Jejak yang lebih kecil tampaknya milik seorang teman dari ras pengerat."
  },
  AvgDialog_48596_Content_30 = {
    Text = "Tapi kalau nanti masih ingin \"mengoleksi\" barang-barangku, ingat beritahu aku dulu sebelumnya."
  },
  AvgDialog_48596_Content_5 = {
    Text = "Kamu meringankan langkah dan napasmu, mengikuti arah jejak kaki itu, dan akhirnya mendorong sebuah pintu di kedalaman lorong."
  },
  AvgDialog_48596_Content_6 = {
    Text = "Krieet——!"
  },
  AvgDialog_48596_Content_7 = {
    Text = [[
<Shake:Waa!>
Bukannya ini Penjaga Rahasia{Male=tuan,Female=nona}, kenapa tiba-tiba datang kemari?]]
  },
  AvgDialog_48596_Content_8 = {
    Text = "Jenkin langsung menutup lemari pakaian dengan keras, dalam kepanikannya hampir menjepit ekor Brown. Ruangan kecil itu seketika menjadi kacau balau."
  },
  AvgDialog_48596_Content_9 = {
    Text = "Justru aku yang mau bertanya kenapa kamu ada di sini. Gedung ini sudah bertahun-tahun tidak dipakai, katanya dulu ada hantu berkeliaran, makanya para siswa menyebutnya \"Rumah Penyihir\"……"
  },
  AvgDialog_48597_Content_1 = {
    Text = "Sudah tenang?"
  },
  AvgDialog_48597_Content_10 = {
    Text = "Aku ingin…… seperti tadi, memelukmu sekali lagi."
  },
  AvgDialog_48597_Content_11 = {
    Text = "Kamu mengangguk."
  },
  AvgDialog_48597_Content_12 = {
    Text = "Lalu, tubuh yang dingin itu menempel padamu."
  },
  AvgDialog_48597_Content_13 = {
    Text = "Di hari-hari di sanatorium itu, aku tidak pernah merasakan kehangatan seperti ini.\nAlangkah baiknya jika kamu selalu ada di sisiku……"
  },
  AvgDialog_48597_Content_14 = {
    Text = "Kehangatan ini seperti racun yang lain, perlahan menelanku.\nAku sering berpikir, jika pada akhirnya air laut tetap memisahkan kita, betapa kesepiannya itu……"
  },
  AvgDialog_48597_Content_15 = {
    Text = "Kamu bisa terus tinggal di sini."
  },
  AvgDialog_48597_Content_16 = {
    Text = "Keheningan berlangsung selama puluhan detik, hingga napas yang terhenti kembali normal, barulah dia perlahan melepaskanmu."
  },
  AvgDialog_48597_Content_17 = {
    Text = "Ayo pergi, sudah waktunya untuk \"pengobatan\"."
  },
  AvgDialog_48597_Content_18 = {
    Text = [[
Nymphia menggandeng tanganmu, selangkah demi selangkah tenggelam ke dalam pelukan laut.
Air laut dengan lembut mengangkat ujung gaunnya, bagai menopang sekuntum teratai ungu pucat yang perlahan mekar.]]
  },
  AvgDialog_48597_Content_19 = {
    Text = "Tangannya sangat dingin, namun tatapannya hampir membakar kulitmu."
  },
  AvgDialog_48597_Content_2 = {
    Text = "Ah, ya, maaf……"
  },
  AvgDialog_48597_Content_20 = {
    Text = "Tenanglah, air laut akan membersihkan racun yang kutinggalkan di dalam tubuhmu."
  },
  AvgDialog_48597_Content_21 = {
    Text = "Adapun \"racun\" yang kautinggalkan di hatiku… akan kusimpan baik-baik."
  },
  AvgDialog_48597_Content_3 = {
    Text = "Jangan khawatir, akhir-akhir ini semua orang terpengaruh oleh banjir Sungai Suci, tindakan yang sedikit di luar kebiasaan juga sudah bisa diduga."
  },
  AvgDialog_48597_Content_4 = {
    Text = "Aku mengerti, hanya saja…… kontak yang terlalu mendalam denganku akan membuatmu terinfeksi oleh \"racun\" di dalam tubuhku."
  },
  AvgDialog_48597_Content_5 = {
    Text = "Kamu memandangi telapak tanganmu sendiri. Di tempat yang tadi menyentuh tulang kurus nan aneh milik Nymph, sudah muncul semburat ungu kebiruan yang samar."
  },
  AvgDialog_48597_Content_6 = {
    Text = "Aku tahu……aku tahu cara menyembuhkannya.\nSilakan ikuti aku."
  },
  AvgDialog_48597_Content_7 = {
    Text = "Ombak menderu, angin laut yang asin meniup rambut halus di pelipis Nymph. Dia mengangkat tangan untuk menekan pinggiran topinya, bunga sutra hitam bergoyang lembut mengikuti gerakannya."
  },
  AvgDialog_48597_Content_8 = {
    Text = "Racun yang terakumulasi dalam tulang-tulang ini akan larut dalam air laut."
  },
  AvgDialog_48597_Content_9 = {
    Text = "Karena \"penawar\" sudah ada di depan mata, bolehkah aku mengajukan satu permintaan yang egois?"
  },
  AvgDialog_48598_Content_1 = {
    Text = "Kau mengenali tempat ini. Dalam suatu insiden sebelumnya, sang pemilik tempat ini pernah menyambutmu masuk ke ruang ini."
  },
  AvgDialog_48598_Content_10 = {
    Text = "Kau melihat originium murni menempel pada tengkorak yang mengerikan itu, selapis demi selapis, berlapis-lapis, saling melilit dan membentuk wajah yang kau kenal."
  },
  AvgDialog_48598_Content_11 = {
    Text = "Nyonya Daffodel……"
  },
  AvgDialog_48598_Content_12 = {
    Text = "Sang penyihir yang melintasi dimensi menampakkan senyum yang sulit ditebak. Ia mengangkat kepalanya, menjauhkan bibir kelabu keunguan dari bibir sang pengembara yang tak berdaya merindukan udara."
  },
  AvgDialog_48598_Content_13 = {
    Text = "Aku menyelamatkanmu dari bahaya sekali lagi, tamu kecilku yang manis."
  },
  AvgDialog_48598_Content_14 = {
    Text = "Uhm… tapi aku tidak mungkin masuk ke Lautan Originium Murni tanpa alasan, kau yang…"
  },
  AvgDialog_48598_Content_15 = {
    Text = "Sst… dengarkan, dengarkan suara tengkorak-tengkorak itu berbicara."
  },
  AvgDialog_48598_Content_16 = {
    Text = "Mereka mendambakanmu. Kalau bukan karena aku, kau sudah ditelan hidup-hidup oleh mereka, lho."
  },
  AvgDialog_48598_Content_17 = {
    Text = "Lalu… bagaimana denganmu? Tanpa persetujuanmu, tengkorak-tengkorak ini mustahil bisa menarikku masuk ke dimensi ini."
  },
  AvgDialog_48598_Content_18 = {
    Text = "……Tentu saja, aku juga sama."
  },
  AvgDialog_48598_Content_19 = {
    Text = "Jadi, imbalan untuk transaksi kali ini……akan kutentukan sendiri."
  },
  AvgDialog_48598_Content_2 = {
    Text = "Terbaring telentang di atas permukaan air yang gelap, matamu menatap matahari kelabu pucat, sementara tengkorak-tengkorak di sekelilingmu tertawa-tawa, saling menghina, dan meratap sendirian."
  },
  AvgDialog_48598_Content_3 = {
    Text = "Mereka berdatangan silih berganti, menabrak lenganmu, hampir membuatmu terjungkal ke dalam air dengan wajah lebih dulu—"
  },
  AvgDialog_48598_Content_4 = {
    Text = "Lautan Originium Murni, tempat persembunyian Penyihir Dimensi, tempat paling berharga milik Dafdael."
  },
  AvgDialog_48598_Content_5 = {
    Text = "Mengapa kau bisa berada di sini? Apakah ini undangan dari Dafdael lagi? Ataukah ini hanyalah mimpi yang absurd…"
  },
  AvgDialog_48598_Content_6 = {
    Text = "Keempat anggota tubuhmu terentang, membiarkan Lautan Originium Murni mendorongmu menuju tepian yang tak pernah ada. Tengkorak-tengkorak yang tak terhitung jumlahnya saling berdesakan di antara ombak kelabu, suara tulang berbenturan terdengar nyaring namun menyeramkan."
  },
  AvgDialog_48598_Content_7 = {
    Text = "Air originium murni meresap masuk ke tubuh dari sudut mata, tubuhmu tenggelam ke bawah permukaan air akibat himpitan tengkorak-tengkorak, dan dalam sekejap, tengkorak-tengkorak yang menutupi langit telah menghalangi semua cahaya."
  },
  AvgDialog_48598_Content_8 = {
    Text = "—Lalu, tengkorak-tengkorak kacau itu bersandar mesra di sisi wajahmu, bibir bertemu bibir."
  },
  AvgDialog_48598_Content_9 = {
    Text = "Dari celah rahang atas dan bawah mengalir udara dingin nan lembap, aroma violet menyebar dari dalam organ tubuhmu ke luar."
  },
  AvgDialog_4870_Content_1 = {
    Text = "Tch, membawa orang ini hanya jadi beban saja."
  },
  AvgDialog_4870_Content_2 = {
    Text = "Kassia belum sadar dari pingsannya, jadi Rotan terpaksa menggendongnya sambil bergerak bersama."
  },
  AvgDialog_4870_Content_3 = {
    Text = "Serahkan pertempurannya padaku!"
  },
  AvgDialog_4871_Content_1 = {
    Text = "Komunikator di dada sedikit menghangat, suara jernih seorang wanita pun bergema di benak, dengan sedikit nada cemas dan khawatir."
  },
  AvgDialog_4871_Content_10 = {
    Text = [[
Film dan kamera adalah penemuan baru, di pasaran permintaan melebihi pasokan, harganya tentu tidak murah.
Dan "Film" yang <Yellow:telah diproses oleh Missage>, harganya bahkan jauh lebih mahal.]]
  },
  AvgDialog_4871_Content_11 = {
    Text = "Diproses? Film dari department store tidak bisa langsung digunakan?"
  },
  AvgDialog_4871_Content_12 = {
    Text = "Silver Core akan menyebabkan film terekspos secara abnormal, hanya film yang telah diproses oleh <Blue:Laboratorium Silver Core Missage> yang bisa merekam wujud Awakened."
  },
  AvgDialog_4871_Content_13 = {
    Text = "Gulungan film prototipe yang tak ada duanya di tanganmu itu, mungkin hanya bisa merekam sekitar 20 menit gambar… Bagaimana, sudah selesai syutingnya?"
  },
  AvgDialog_4871_Content_14 = {
    Text = "Hmm… Mungkin… masih butuh sedikit waktu lagi…… Semuanya sedang…… menyusun konsep!"
  },
  AvgDialog_4871_Content_15 = {
    Text = "Benar juga, lagipula menguji efek kamera hanyalah tugas sekunder — bersenang-senang adalah yang terpenting, bukan?"
  },
  AvgDialog_4871_Content_16 = {
    Text = "Kalau begitu, semoga kalian menikmati liburan yang menyenangkan. Aku menantikan karya kalian."
  },
  AvgDialog_4871_Content_17 = {
    Text = "Ramona memutus komunikasi, meninggalkanmu dengan wajah pucat pasi."
  },
  AvgDialog_4871_Content_2 = {
    Text = "Aku merasakan fluktuasi kekuatan spiritual, apakah kamu menghadapi pertempuran? Tidak terluka kan?"
  },
  AvgDialog_4871_Content_3 = {
    Text = "Hanya bertemu beberapa mutan saja, semua baik-baik saja."
  },
  AvgDialog_4871_Content_4 = {
    Text = "Syukurlah, apakah semuanya berjalan lancar?"
  },
  AvgDialog_4871_Content_5 = {
    Text = "Cukup… lancar, kurasa."
  },
  AvgDialog_4871_Content_6 = {
    Text = "Kamu bertatapan dengan beberapa wajah yang memelas, wajah-wajah muda ini kurang lebih menunjukkan rasa takut terhadap \"pemilik kamera\"."
  },
  AvgDialog_4871_Content_7 = {
    Text = "Oh ya, kebetulan ada yang ingin kutanyakan — apakah film kamera itu mahal? Aureta sangat penasaran."
  },
  AvgDialog_4871_Content_8 = {
    Text = "Aureta juga tidak begitu — mmph!"
  },
  AvgDialog_4871_Content_9 = {
    Text = "Kassia yang entah kapan turun dari bahu Rotan membekap mulut Aureta, membawa gadis yang ribut itu ke samping."
  },
  AvgDialog_4872_Content_1 = {
    Text = "Aku mencium bau Toko Tukar, lewat sini."
  },
  AvgDialog_4872_Content_2 = {
    Text = "Snif, snif……"
  },
  AvgDialog_4872_Content_3 = {
    Text = "Selain bau Brown, Aurita tidak mencium apa-apa!"
  },
  AvgDialog_4872_Content_4 = {
    Text = "Kalian berdua bukan anak anjing!"
  },
  AvgDialog_4873_Content_1 = {
    Text = "Akulah orang yang paling mengenal Daphodel, dia bukan tipe yang tertarik dengan ocehan anak-anak."
  },
  AvgDialog_4873_Content_10 = {
    Text = "Cerita. Kamu tidak ingin membuat film tentang ceritamu sendiri?"
  },
  AvgDialog_4873_Content_11 = {
    Text = [[
Tugasku adalah membawa kalian semua kembali ke sekolah dengan selamat.
Jangan libatkan aku dalam urusan menulis naskah dan membuat film.]]
  },
  AvgDialog_4873_Content_13 = {
    Text = "Wujud Aberrant lenyap di tengah deru angin dari tebasan pedang panjang. Rotan menyeka lumpur hitam dari pedangnya, lalu menoleh dan tersenyum padamu."
  },
  AvgDialog_4873_Content_14 = {
    Text = "Inilah yang seharusnya kulakukan."
  },
  AvgDialog_4873_Content_2 = {
    Text = "Hanya emosi yang paling intens, paling ekstrem…… yang bisa membuatnya menunjukkan senyuman sejati."
  },
  AvgDialog_4873_Content_3 = {
    Text = "Itu adalah penderitaan! Dia pasti mendambakan sebuah cerita yang penuh penderitaan mendalam, yang bisa membuat semua orang <Red:berlumuran darah>!"
  },
  AvgDialog_4873_Content_4 = {
    Text = "Di balik penampilan yang begitu anggun ternyata kepribadiannya seperti itu ya?\nKalau begitu ceritaku… mungkin tidak akan menarik perhatiannya."
  },
  AvgDialog_4873_Content_5 = {
    Text = [[
Jangan dengarkan omong kosong orang ini.
Meskipun Daphodel memang suka menonton keributan, tapi sifatnya tidak seburuk itu.]]
  },
  AvgDialog_4873_Content_6 = {
    Text = "Apa yang ada di pikiranmu, coba ceritakan?"
  },
  AvgDialog_4873_Content_7 = {
    Text = "Itu cerita yang kubaca dari buku. Mengisahkan tentang seorang pemimpi yang berkelana ke mana-mana dengan membawa impian menjadi ksatria, di era ketika para ksatria sudah menghilang."
  },
  AvgDialog_4873_Content_8 = {
    Text = "Rasanya aku juga pernah membaca buku itu… Ngomong-ngomong, bagaimana denganmu, Rotan?"
  },
  AvgDialog_4873_Content_9 = {Text = "Apanya?"},
  AvgDialog_4874_Content_1 = {
    Text = "Kali ini jangan biarkan Pesulap menulis cerita lagi!"
  },
  AvgDialog_4874_Content_10 = {
    Text = "Cit cit cit!!"
  },
  AvgDialog_4874_Content_11 = {
    Text = "Brown, jangan terburu-buru, sebentar lagi giliranmu tampil!"
  },
  AvgDialog_4874_Content_12 = {
    Text = "Apa? Kamu bilang musuh?"
  },
  AvgDialog_4874_Content_13 = {
    Text = "Aaaaaah——! Sejak kapan makhluk-makhluk aneh ini muncul!"
  },
  AvgDialog_4874_Content_2 = {
    Text = "Kenapa tidak boleh? Waktu, tempat, tokoh, konflik, ketegangan, bukankah ceritaku sudah mencakup semuanya? Dan aku sudah memperkenalkan semuanya di awal, bukankah itu benar?"
  },
  AvgDialog_4874_Content_3 = {
    Text = "Kon, konflik apa? Kamu bicara terlalu cepat, aku tidak dengar jelas."
  },
  AvgDialog_4874_Content_4 = {
    Text = "Aduh, pokoknya terlalu klise! Bahkan Auretta pun akan merasa bosan."
  },
  AvgDialog_4874_Content_5 = {
    Text = "Hmm? Auretta merasa semuanya bagus!"
  },
  AvgDialog_4874_Content_6 = {
    Text = "Dasar kamu ini……!"
  },
  AvgDialog_4874_Content_7 = {
    Text = "Sudahlah, kalau aku yang menulis, aku pasti akan menulis \"<Blue:Ksatria Tengah Malam Londinium>\"!"
  },
  AvgDialog_4874_Content_8 = {
    Text = "Cit——cit cit!"
  },
  AvgDialog_4874_Content_9 = {
    Text = "Di hotel yang mewah berwarna merah, di bawah meja restoran mewah hotel itu, tangan sang pencuri mulia mengincar dompet pedagang kaya yang jahat……"
  },
  AvgDialog_4875_Content_1 = {
    Text = "Hanya film khusus yang bisa merekam Awakened, tapi kita baru saja merusak satu-satunya sampel percobaan……"
  },
  AvgDialog_4875_Content_10 = {
    Text = "Trik apanya! Ini sulap, <Big:sulap!!>"
  },
  AvgDialog_4875_Content_11 = {
    Text = "Rotan, jangan menggodanya dulu."
  },
  AvgDialog_4875_Content_12 = {
    Text = "Nona Cassia, cara yang kamu maksud adalah……"
  },
  AvgDialog_4875_Content_13 = {
    Text = [[
Pergi menemui Nyonya Narcissus, dia pasti punya solusinya.
Wanita yang begitu suka menonton keramaian, tidak mungkin tidak tertarik pada mesin yang <Yellow:bisa merekam Awakened>.]]
  },
  AvgDialog_4875_Content_14 = {
    Text = "Tsk… Harus berurusan dengan wanita itu lagi?"
  },
  AvgDialog_4875_Content_15 = {
    Text = "Pergi meminta bantuan Nyonya Daffodil? Bukan solusi yang buruk, asalkan apa yang ingin dia tukarkan tidak terlalu berlebihan……"
  },
  AvgDialog_4875_Content_16 = {
    Text = "Sebuah tarikan kecil terasa di jubahmu. Kau menunduk dan melihat Lily yang berjinjit menarik jubahmu, matanya yang berkedip-kedip menatapmu."
  },
  AvgDialog_4875_Content_17 = {
    Text = "Lily ingin mengunjungi Nyonya Daffodil?"
  },
  AvgDialog_4875_Content_18 = {
    Text = "Nyonya Narcissus… teman Mama, um!"
  },
  AvgDialog_4875_Content_19 = {
    Text = "Kalau Lily sudah bilang begitu, ayo pergi, Penjaga Rahasia."
  },
  AvgDialog_4875_Content_2 = {
    Text = "Uji penelitian Nona Doll… Tuan, kurasa kita……"
  },
  AvgDialog_4875_Content_3 = {
    Text = "Wajah Augier memucat, tenggelam dalam kesakitan dan ketakutan yang sama denganmu."
  },
  AvgDialog_4875_Content_4 = {
    Text = "Kita pasti akan dihukum mati, kan."
  },
  AvgDialog_4875_Content_5 = {
    Text = "Tuan, aku tidak akan… membiarkan hal seperti itu…… terjadi……"
  },
  AvgDialog_4875_Content_6 = {
    Text = "Kata-kata Augier kehilangan keteguhan yang biasanya, dan menghadapi kemungkinan kemarahan Doll, sikapnya pun tampak goyah."
  },
  AvgDialog_4875_Content_7 = {
    Text = "Kenapa satu per satu memasang wajah muram begitu?\nAyo — tersenyum!"
  },
  AvgDialog_4875_Content_8 = {
    Text = "Bukankah cuma film khusus? Aku punya cara."
  },
  AvgDialog_4875_Content_9 = {
    Text = "Kamu juga tahu trik untuk memperbaiki barang?"
  },
  AvgDialog_4876_Content_10 = {
    Text = "Putriku… Putriku!"
  },
  AvgDialog_4876_Content_11 = {
    Text = "Ini semua salahku, Ibu gagal melindungimu, hingga kau tersesat dalam kegelapan!"
  },
  AvgDialog_4876_Content_12 = {
    Text = "{Male=Dia,Female=Dia}Aktingnya seperti monyet yang kakinya terinjak."
  },
  AvgDialog_4876_Content_13 = {
    Text = "Di mana kau pernah melihat monyet? Di kebun binatang Londinium?"
  },
  AvgDialog_4876_Content_14 = {
    Text = "Diam, diam!!"
  },
  AvgDialog_4876_Content_15 = {
    Text = "Nona Cassia, tenang! Ada Mutan yang tertarik kemari lagi!"
  },
  AvgDialog_4876_Content_2 = {
    Text = "Ibu, Ibu, kau di mana?"
  },
  AvgDialog_4876_Content_3 = {
    Text = "Aku tidak sengaja tersesat, maafkan aku, Ibu, maafkan aku."
  },
  AvgDialog_4876_Content_4 = {
    Text = "Li… Aku bukan anak nakal, tolong jangan tinggalkan aku……"
  },
  AvgDialog_4876_Content_5 = {
    Text = "Suara gadis itu lenyap tertiup angin, air matanya menetes ke dalam tanah yang hitam."
  },
  AvgDialog_4876_Content_6 = {
    Text = "Dia menangis tersedu di dalam ruangan tanpa cahaya, dan setetes air mata kesedihan yang lain menyirami bunga lili putih di samping tempat tidurnya."
  },
  AvgDialog_4876_Content_7 = {
    Text = "%player%Cepat, cepat, cepat, giliranmu tampil!"
  },
  AvgDialog_4876_Content_8 = {
    Text = "Jangan berisik! Pelankan suaramu!"
  },
  AvgDialog_4876_Content_9 = {
    Text = "Kamu merapikan kerah bajumu, berusaha sekuat tenaga memasang ekspresi sedih, lalu berjalan terpincang-pincang ke depan kamera."
  },
  AvgDialog_4877_Content_10 = {
    Text = "Wajah cemas sang gadis kecil."
  },
  AvgDialog_4877_Content_11 = {
    Text = "Ibu……! Ibu!"
  },
  AvgDialog_4877_Content_12 = {
    Text = "Tangan-tangan mungil menggali tumpukan salju, tubuh kecil yang ringkih berdiri menghalangi di depannya, menghadang badai salju yang meraung—"
  },
  AvgDialog_4877_Content_2 = {
    Text = "Wanita itu berjalan di hamparan salju dengan pakaian musim dingin yang tebal, beban bawaan yang berat memperlambat langkahnya, meninggalkan jejak kaki yang dalam di atas salju."
  },
  AvgDialog_4877_Content_3 = {
    Text = "Tunggu aku… putriku, ibu akan segera sampai di sisimu……"
  },
  AvgDialog_4877_Content_4 = {
    Text = "Dari pegunungan bersalju yang jauh, terdengar gemuruh dahsyat sesuatu yang runtuh."
  },
  AvgDialog_4877_Content_5 = {
    Text = "Longsor salju?!"
  },
  AvgDialog_4877_Content_6 = {
    Text = "Tunggu, longsor salju di dalam <Yellow:Ilusi Sihir> tidak benar-benar berbahaya, kan?"
  },
  AvgDialog_4877_Content_7 = {
    Text = "Apa itu Ilusi Sihir? Ia adalah imajinasi agung sang petualang penyendiri, mahakarya sang penyihir besar. Sebuah seni puncak yang memadukan dingin, ketakutan, mimpi buruk, dan krisis menjadi satu!"
  },
  AvgDialog_4877_Content_8 = {
    Text = "Dikejar oleh longsoran salju yang runtuh, sang petualang menerobos lebih dalam ke padang salju. Namun bagaimana manusia yang lemah bisa mengalahkan alam? Dalam sekejap kelengahan, dia terjatuh ke dalam gua es yang tak berdasar."
  },
  AvgDialog_4877_Content_9 = {
    Text = "Tumpukan salju yang tebal menekan saluran napasnya, pandangan sang petualang mulai menggelap, kenangan masa lalu bermunculan satu per satu — luka hitam penyakit, hujan deras di hari pemakaman, dan juga—"
  },
  AvgDialog_4878_Content_10 = {
    Text = "Konflik! Bagian ini harus menjadi salah satu klimaks cerita, perlu ada konflik!"
  },
  AvgDialog_4878_Content_2 = {
    Text = "Aku mendengar suaramu, hangat, dan basah…… Ibu, apakah kau menangis?"
  },
  AvgDialog_4878_Content_3 = {
    Text = "Ibu…… Ibu? Mengapa kau menangis?"
  },
  AvgDialog_4878_Content_4 = {
    Text = [[
Sang ibu terisak di depan sebuah batu nisan, tangisan pilu sang gadis terhalang oleh campuran tanah dan kayu.
Padahal jaraknya hanya sejengkal, namun dia tak mampu mendengar permohonan putri tercintanya.]]
  },
  AvgDialog_4878_Content_5 = {
    Text = "Ibu, tolong jangan menangis, aku akan jadi anak baik…… Tolong jangan tak melihatku……"
  },
  AvgDialog_4878_Content_6 = {
    Text = "Ibu… aku sangat lelah…… Saat aku terbangun, apakah kau akan menemukanku?"
  },
  AvgDialog_4878_Content_7 = {
    Text = "Seperti lilin yang hampir padam, suaranya semakin lemah, semakin pelan.\nPada akhirnya, bahkan dia sendiri pun tak bisa mendengar suaranya lagi……"
  },
  AvgDialog_4878_Content_8 = {
    Text = "Seiring gadis itu terlelap dalam tidur nyenyak, kegelapan yang mengintai di pemakaman menyerbu maju! Menerjang sang ibu yang berduka tanpa menyadari apa pun!"
  },
  AvgDialog_4878_Content_9 = {
    Text = "Tunggu! Di naskah tidak tertulis ada pertarungan, kan?"
  },
  AvgDialog_4879_Content_1 = {Text = "Di sana."},
  AvgDialog_4879_Content_10 = {
    Text = "Kamu dan Nymphia diam-diam memperhatikan gadis itu dari kejauhan. Matanya terpejam erat, namun wajahnya menampakkan senyum bahagia dan puas."
  },
  AvgDialog_4879_Content_11 = {
    Text = "Kamu tak tega mengganggu ketenangan ini, namun para pasien di halaman tidak memberi lebih banyak waktu untuk kedamaian itu."
  },
  AvgDialog_4879_Content_12 = {
    Text = "Kak Nymphia… Tuan…"
  },
  AvgDialog_4879_Content_13 = {
    Text = "Maaf, aku pergi meninggalkan kalian tanpa izin……"
  },
  AvgDialog_4879_Content_14 = {
    Text = "Tidak apa-apa, Lily. Apa kamu masih ingin menemani ibumu sebentar lagi?"
  },
  AvgDialog_4879_Content_15 = {
    Text = "Lily menggenggam tanganmu, menoleh ke pintu yang membisu itu, lalu menggelengkan kepalanya dengan tegas."
  },
  AvgDialog_4879_Content_16 = {
    Text = "Lily sudah tahu cerita apa yang akan diceritakan. Ayo kita segera kembali."
  },
  AvgDialog_4879_Content_17 = {
    Text = "Berpamitan dengan Nymphia, kalian meninggalkan sanatorium dan melangkah menuju perjalanan pulang ke Londinium."
  },
  AvgDialog_4879_Content_18 = {
    Text = "Cahaya bulan menembus udara berkabut, melewati kaca keruh sanatorium."
  },
  AvgDialog_4879_Content_19 = {
    Text = "Di sudut tempat waktu membeku, lingkaran sihir ungu gelap memancarkan cahaya tersembunyi."
  },
  AvgDialog_4879_Content_2 = {
    Text = "Gadis yang kalian cari sedang duduk di lantai di ujung koridor, bersandar pada sebuah pintu besar yang sangat kamu kenal."
  },
  AvgDialog_4879_Content_3 = {
    Text = "Pola-pola rumit dan misterius menembus daun pintu, memancarkan cahaya ungu gelap."
  },
  AvgDialog_4879_Content_4 = {Text = "Ibu……"},
  AvgDialog_4879_Content_5 = {
    Text = "Lily bicara, apa Ibu bisa mendengarnya?"
  },
  AvgDialog_4879_Content_6 = {
    Text = "Igauan lirih bagai anak hewan itu tak mendapat jawaban. Mungkin pintunya terlalu tebal, atau mungkin di balik sana sudah tak ada lagi kehidupan."
  },
  AvgDialog_4879_Content_7 = {
    Text = "Maaf… cerita-cerita yang pernah Ibu ceritakan kepada Lily, Lily tidak sengaja melupakannya."
  },
  AvgDialog_4879_Content_8 = {
    Text = "Lily ingin bercerita kepada teman-teman… bisakah Ibu mengajari Lily?"
  },
  AvgDialog_4880_Content_10 = {
    Text = "Jangan-jangan kalian adalah legenda Londinium yang——!"
  },
  AvgDialog_4880_Content_11 = {
    Text = "Benar sekali! Menjelajahi Londinium di kegelapan malam, menjaga malam-malam biasa di Distrik Timur, bersuara untuk para pekerja, berteriak untuk kaum miskin——"
  },
  AvgDialog_4880_Content_12 = {
    Text = "Kami adalah <Blue:Ksatria Sepanjang Malam> dan asisten setianya!"
  },
  AvgDialog_4880_Content_13 = {
    Text = "Ksatria Sepanjang Malam yang agung melompat turun dari bahu asistennya, dan dalam sekejap menggigit putus tali rami dengan senjata tajam anugerah langit!"
  },
  AvgDialog_4880_Content_14 = {
    Text = "Cit cit, cit!"
  },
  AvgDialog_4880_Content_15 = {
    Text = "Brown berkata… ehm ehm, Ksatria Sepanjang Malam berkata: Tali ini memang sulit digigit tikus!\nTapi kita tetap berhasil! Cahaya kebebasan tikus sedang melambaikan tangan kepada kita!"
  },
  AvgDialog_4880_Content_16 = {
    Text = "Terima kasih, Ksatria Sepanjang Malam dan rekan……"
  },
  AvgDialog_4880_Content_17 = {
    Text = "Gadis itu terdiam sejenak setelah berbicara, lalu mengangkat tangan menunjuk ke arah gerombolan tikus kecil yang tertarik oleh Ksatria Sepanjang Malam."
  },
  AvgDialog_4880_Content_2 = {
    Text = "Inspektur, aku mendengar suara gigi retak."
  },
  AvgDialog_4880_Content_3 = {
    Text = "Sebentar lagi… hampir selesai……"
  },
  AvgDialog_4880_Content_4 = {
    Text = "Inspektur yang gagah dan tampan itu tengkurap di tanah seperti seekor anjing. Kedua tangannya juga diikat ke belakang, tapi dia menolak menyerah, berusaha keras menggigit tali rami di tangan gadis itu dengan giginya."
  },
  AvgDialog_4880_Content_5 = {
    Text = "Di sudut yang tak terlihat oleh keduanya, sepasang mata berkilat ganas menyala dari kegelapan! Sesuatu akan menembus kegelapan, membawakan cahaya fajar bagi semua orang!"
  },
  AvgDialog_4880_Content_6 = {
    Text = "Cit cit, cit cit cit!"
  },
  AvgDialog_4880_Content_7 = {
    Text = "<Blue:Ksatria Sepanjang Malam> berkata: Dia menyarankan untuk berhenti menggigit, tali rami ajaib milik Maestro Houdini sekeras baja."
  },
  AvgDialog_4880_Content_8 = {
    Text = "Satu orang……"
  },
  AvgDialog_4880_Content_9 = {
    Text = "Satu tikus……"
  },
  AvgDialog_4881_Content_1 = {
    Text = "Menang…… kita menang!"
  },
  AvgDialog_4881_Content_10 = {
    Text = "Sang asisten mengangkat Ranger Malam tinggi-tinggi, untuk sementara melindungi bulu indah sang Ranger."
  },
  AvgDialog_4881_Content_11 = {
    Text = "Hei!! Mayat jangan bicara lagi! Penjaga Rahasia! Rotan! Cepat pikirkan sesuatu!!"
  },
  AvgDialog_4881_Content_12 = {
    Text = "Rotan menggelengkan kepalanya dengan ekspresi antara tertawa dan menangis, bayangan makhluk paus muncul dari belakangnya. Namun tepat saat dia hendak menarik semua orang keluar dari air, sebuah sosok ringan terjun masuk ke dalam air."
  },
  AvgDialog_4881_Content_13 = {
    Text = "Air! Ini air~ Ini lautan yang paling disukai Aurita!"
  },
  AvgDialog_4881_Content_14 = {
    Text = "Ucapkanlah permohonanmu padaku, wahai orang-orang yang membutuhkan bantuan! Lautan akan menjawab semua harapan kalian!"
  },
  AvgDialog_4881_Content_15 = {
    Text = "Inspektur G dan duo Midnight Ranger saling berpandangan, lalu serempak mendorong gadis berpakaian putih yang sudah lama terdiam ke hadapan peri laut."
  },
  AvgDialog_4881_Content_16 = {Text = "……?!"},
  AvgDialog_4881_Content_17 = {
    Text = "To, tolong bawa kami pergi dari sini."
  },
  AvgDialog_4881_Content_18 = {
    Text = "Cassia yang setengah badannya sudah terendam di air menyunggingkan sudut bibirnya, menampilkan senyum puas."
  },
  AvgDialog_4881_Content_19 = {
    Text = "Ilusi sihir berubah bentuk dan cahaya di bawah lambaian tangannya."
  },
  AvgDialog_4881_Content_2 = {
    Text = "Pesulap jahat itu dikalahkan berkat kerja sama semua orang. Dia ambruk ke tanah, dengan lemah mengulurkan tangannya ke arah sebuah tombol."
  },
  AvgDialog_4881_Content_20 = {
    Text = "Dalam sekejap, semua orang terendam di dalam air"
  },
  AvgDialog_4881_Content_21 = {
    Text = "Tak ada yang selamat."
  },
  AvgDialog_4881_Content_22 = {
    Text = "Kau serius!?"
  },
  AvgDialog_4881_Content_23 = {
    Text = "Peri telah kembali ke lautan yang bebas, dan semua orang berhasil keluar dari bengkel sihir Houdini, bukankah itu sudah memenuhi permohonan sang gadis?"
  },
  AvgDialog_4881_Content_24 = {
    Text = "Perkataan Anda memang ada benarnya, ta, tapi bagaimana cerita ini bisa mencapai akhir yang diinginkan Lily?"
  },
  AvgDialog_4881_Content_25 = {
    Text = "\"Gadis itu pun hidup bahagia bersama ibunya selamanya\""
  },
  AvgDialog_4881_Content_26 = {
    Text = [[
Tch, ini terakhir kalinya aku membantumu mengurus anak-anak.
Kalau ada urusan merepotkan seperti ini lagi, jangan cari aku.]]
  },
  AvgDialog_4881_Content_27 = {
    Text = "Lily, Pak Polisi, cepat lihat apa itu di dalam air sana?!"
  },
  AvgDialog_4881_Content_29 = {
    Text = "Punggung raksasa muncul dari dalam air, itu adalah makhluk besar yang telah bersemayam di kedalaman laut Kadath sejak planet ini terlahir. Dia menjawab panggilan kehidupan, menembus tirai waktu untuk datang!"
  },
  AvgDialog_4881_Content_3 = {
    Text = [[
Melihat itu, Lotten langsung melemparkan pengeras suara kepadamu.
Dia melangkah lebar menuju Kaschey dan berbisik di telinganya.]]
  },
  AvgDialog_4881_Content_30 = {
    Text = "Ro……tan?"
  },
  AvgDialog_4881_Content_31 = {
    Text = "Mau ikut tidak? Kalau tidak, kalian akan menyambut akhir cerita di dalam air ini."
  },
  AvgDialog_4881_Content_32 = {
    Text = "Wah! Ikan besar!"
  },
  AvgDialog_4881_Content_33 = {
    Text = "Jangan terburu-buru, satu per satu ya. Punggung Nona Rotan sangat luas."
  },
  AvgDialog_4881_Content_34 = {
    Text = "Bisakah kau, peri laut setengah-setengah, berhenti berdesakan di depan!? Aku dan Bu... aku dan Ranger Malam Abadilah yang jelas-jelas paling berjasa, kan?"
  },
  AvgDialog_4881_Content_35 = {Text = "Anu..."},
  AvgDialog_4881_Content_36 = {
    Text = "Ikan besar adalah teman Oreta! Jadi Oreta harus duduk paling depan!"
  },
  AvgDialog_4881_Content_37 = {Text = "Anu...!"},
  AvgDialog_4881_Content_38 = {
    Text = "Li, Lily... aku..."
  },
  AvgDialog_4881_Content_39 = {
    Text = "Aku ingin duduk paling depan, boleh?"
  },
  AvgDialog_4881_Content_4 = {
    Text = "Kau punya ide nakal apa lagi? Jangan bikin semuanya jadi tak terkendali ya."
  },
  AvgDialog_4881_Content_40 = {
    Text = "Karena kau lebih kecil dariku... hati-hati! Di punggung si besar ini tidak ada kursinya."
  },
  AvgDialog_4881_Content_41 = {
    Text = "Oreta mau bersama teman-teman!"
  },
  AvgDialog_4881_Content_42 = {
    Text = "Hei! Kenapa badanmu licin sekali!? Kalau kau bisa berenang, tidak usah naik ke sini!"
  },
  AvgDialog_4881_Content_43 = {
    Text = "Sang makhluk raksasa mengeluarkan raungan dari saluran napasnya. Dia melompat keluar dari air membawa tawa dan harapan."
  },
  AvgDialog_4881_Content_44 = {
    Text = "Cahaya fajar menembus awan dan kabut air, menyelimuti permukaan laut, sang makhluk raksasa, dan para petualang dengan kerudung merah muda kemerahan."
  },
  AvgDialog_4881_Content_45 = {
    Text = "Ti, tinggi sekali——!"
  },
  AvgDialog_4881_Content_47 = {
    Text = "Inspektur G, peri laut, dan asisten Ranger Malam Abadi bersama-sama menangkap gadis itu, mencegahnya tergelincir dari punggung sang makhluk raksasa."
  },
  AvgDialog_4881_Content_48 = {
    Text = "Mereka tertawa dan bercanda dengan riang, saling mengusapkan air ke pakaian rekan mereka."
  },
  AvgDialog_4881_Content_49 = {
    Text = "Mungkin bagi para orang beruntung yang lolos dari maut ini, akhir cerita yang semula ingin mereka capai sudah tidak lagi begitu penting."
  },
  AvgDialog_4881_Content_5 = {
    Text = "Aiya, cuma ujian kecil saja kok——"
  },
  AvgDialog_4881_Content_50 = {
    Text = "Saat itu, gadis pemberani itu tiba-tiba menatap lurus ke arahmu, ke arahmu yang duduk diam di atas batu karang."
  },
  AvgDialog_4881_Content_51 = {
    Text = "Bintik-bintik cahaya menari di matanya, dan wajah mudanya itu menampilkan senyuman yang luar biasa cerah."
  },
  AvgDialog_4881_Content_52 = {
    Text = "Bunga bakung yang terkurung oleh waktu, yang melewatkan musim mekarnya—"
  },
  AvgDialog_4881_Content_53 = {
    Text = "Akhirnya menyambut saat untuk mekar."
  },
  AvgDialog_4881_Content_54 = {
    Text = "Prok— prok— prok—"
  },
  AvgDialog_4881_Content_55 = {
    Text = "Tepuk tangan terdengar dari luar set syuting, aroma violet perlahan menyebar memenuhi ruangan. Seseorang menyeret gaun panjang yang anggun, berjalan mendekat dengan langkah gemulai."
  },
  AvgDialog_4881_Content_56 = {Text = "Daphdale!"},
  AvgDialog_4881_Content_57 = {
    Text = "Daphodel tersenyum sambil melepas film khusus itu, lalu meniup debu yang tak ada di atasnya dengan anggun."
  },
  AvgDialog_4881_Content_58 = {
    Text = "Memang sebuah cerita yang luar biasa. Pertukaran ini, akan kuterima."
  },
  AvgDialog_4881_Content_59 = {
    Text = [[
Tunggu! Waktu itu kau tidak pernah bilang akan membawa filmnya pergi.
Kalau begini, kami tidak bisa melapor kepada Doll.]]
  },
  AvgDialog_4881_Content_6 = {
    Text = "Seiring senyum di wajah Kaschey yang perlahan melebar, suara arus bawah yang bergejolak terdengar di telinga semua orang."
  },
  AvgDialog_4881_Content_60 = {
    Text = "Kau masih saja tidak sabaran seperti biasa, pendekar hitam.\nCoba pikirkan baik-baik tugas dari Nona Doll—"
  },
  AvgDialog_4881_Content_61 = {
    Text = "\"Menguji mesin yang sudah dimodifikasi\"… bukan menguji film khusus, benar kan?"
  },
  AvgDialog_4881_Content_62 = {
    Text = "Tapi aku belum menonton filmnya! Berbeda dengan komik strip, kan?"
  },
  AvgDialog_4881_Content_63 = {
    Text = "Mesin itu merekam cerita kalian dengan setia, film hanyalah wadah dari momen indah ini…\nTugas yang diberikan oleh \"Otak dalam Tabung\" itu, kalian sudah menyelesaikannya sejak lama, bukan?"
  },
  AvgDialog_4881_Content_64 = {
    Text = "Adapun film jadinya, aku sangat menyambut kalian semua untuk berkunjung ke toko pertukaran dan menontonnya bersama."
  },
  AvgDialog_4881_Content_65 = {
    Text = "Kau baru hendak melanjutkan membujuk sang pedagang untuk meninggalkan filmnya, ketika komunikator di dadamu berbunyi pada saat yang tidak tepat."
  },
  AvgDialog_4881_Content_66 = {
    Text = "Selama ini baru tersambung, sepertinya kalian sangat bersenang-senang ya? Kuharap kau bisa seserius ini juga saat mengerjakan tugas akademikmu."
  },
  AvgDialog_4881_Content_67 = {
    Text = "Basa-basinya tidak perlu. Ada sesuatu yang tidak bisa kutemukan— saat meninggalkan laboratorium, aku hanya memberikanmu satu kotak film khusus, benar kan?"
  },
  AvgDialog_4881_Content_68 = {
    Text = "Hmm… memang benar, hanya satu kamera dan satu kotak film."
  },
  AvgDialog_4881_Content_69 = {
    Text = "Suara Doll yang tanpa emosi mengalir ke dalam otak semua personel terkait Missage yang hadir. Semua orang yang tadinya tertawa dan bercanda menahan napas, takut membocorkan sedikit pun informasi."
  },
  AvgDialog_4881_Content_7 = {
    Text = "Mengalirlah masuk! Banjir! Selesaikan penutupan pertunjukan Maestro Houdini—— pelarian tangki air yang terakhir!"
  },
  AvgDialog_4881_Content_70 = {
    Text = "Benar juga, kalau bahkan di tempat Erica tidak ada catatan pengeluaran barang, bertanya padamu juga percuma."
  },
  AvgDialog_4881_Content_71 = {
    Text = "Cepat kembali, kalian sudah cukup lama bermain di luar."
  },
  AvgDialog_4881_Content_72 = {
    Text = "Doll tanpa belas kasihan memutus komunikasi. Saat arus listrik menghilang dari otak, semua orang menghela napas lega."
  },
  AvgDialog_4881_Content_73 = {
    Text = "Nyonya Daphodel! Jangan-jangan film yang Anda berikan kepada kami itu—"
  },
  AvgDialog_4881_Content_74 = {
    Text = "Wanita jahat itu mana?! Sejak kapan dia menghilang?!"
  },
  AvgDialog_4881_Content_75 = {
    Text = "Lily menatap Lautan Abu-abu menghilang di tikungan lokasi syuting. Menyadari tatapanmu, dia berbalik dan melangkah menghampirimu."
  },
  AvgDialog_4881_Content_76 = {
    Text = "Ada apa, Lily?"
  },
  AvgDialog_4881_Content_77 = {
    Text = "Lily sangat senang……"
  },
  AvgDialog_4881_Content_78 = {
    Text = "Dia menggenggam erat ujung jubahmu, mendongak dan menunjukkan senyuman cerah kepadamu."
  },
  AvgDialog_4881_Content_79 = {
    Text = "Terima kasih…… \"Ibu\"."
  },
  AvgDialog_4881_Content_8 = {
    Text = "Permukaan air naik dengan cepat, segera merendam punggung kaki anak-anak, lalu betis mereka…… dan akhirnya, air naik hingga paha, membuat mereka sulit melangkah."
  },
  AvgDialog_4881_Content_80 = {Text = "Akhir"},
  AvgDialog_4881_Content_9 = {
    Text = "Kaschey!!! Apa yang kau lakukan!? Kau benar-benar mau menenggelamkan kami?!"
  },
  AvgDialog_4882_Content_1 = {
    Text = [[
Makhluk bermutasi itu mengeluarkan jeritan terakhirnya, titik-titik perak bertebaran ke udara.
Tak lama lagi, Dia akan dilupakan oleh dunia bersama dengan kesedihan ini.]]
  },
  AvgDialog_4882_Content_10 = {
    Text = "Aku menyaksikannya layu hari demi hari, dari matahari menjadi genangan air mati yang bahkan angin pun tak mampu meriak."
  },
  AvgDialog_4882_Content_11 = {
    Text = "Pada akhirnya, hanya cairan hitam pekat yang menetes dari sela-sela jarinya, menyatu dengan tanah."
  },
  AvgDialog_4882_Content_12 = {
    Text = "Berbeda dengan puisi, cerita selalu berasal dari manusia. Pedagang dan saudagar, pelajar dan prajurit, bangsawan dan pelayan… mereka semua adalah cerita."
  },
  AvgDialog_4882_Content_13 = {
    Text = "Tapi kedekatanku… kedekatan kesedihan hanya akan membawa cerita menuju akhir yang sama."
  },
  AvgDialog_4882_Content_14 = {
    Text = "Nona Aurla…"
  },
  AvgDialog_4882_Content_15 = {
    Text = "Tuan, ini bukan salah Nona Aurla, kan?"
  },
  AvgDialog_4882_Content_17 = {
    Text = "Tidak apa-apa, Lily kecil, aku sudah menerima kenyataan ini."
  },
  AvgDialog_4882_Content_18 = {
    Text = "Tidak, ini bukan salahmu."
  },
  AvgDialog_4882_Content_19 = {
    Text = "Anda… mengapa berkata demikian?"
  },
  AvgDialog_4882_Content_2 = {
    Text = "Bayangan kesedihan… kau mengenal dia yang dulu, bukan?"
  },
  AvgDialog_4882_Content_20 = {
    Text = "Aku mendengar suara dari entitas bermutasi. Setidaknya kehancuran pemilik toko bunga ini tidak ada hubungannya denganmu."
  },
  AvgDialog_4882_Content_21 = {Text = "A-apa?"},
  AvgDialog_4882_Content_22 = {
    Text = "Dari potongan kata-kata yang ditinggalkan oleh entitas erosi, aku menduga dia sudah menunjukkan gejala erosi sejak lama, jauh sebelum kamu mengajukan permohonan untuk meninggalkan Misagger."
  },
  AvgDialog_4882_Content_23 = {
    Text = "Sakit…aku jatuh sakit.\nAku mulai tidak bisa mengingat banyak hal, dan kadang-kadang aku melihat hal-hal aneh.\nDokter bilang, itu halusinasi, gejala dari histeria.\nHisteria……kedengarannya, begitu jauh dari diriku."
  },
  AvgDialog_4882_Content_24 = {
    Text = "Kudengar dari orang lain, tetangga baru yang pindah ke ujung jalan adalah orang yang sangat berbakat……"
  },
  AvgDialog_4882_Content_25 = {
    Text = "Dia membeli seikat bunga dariku, dan memberiku sebuah puisi. Senangnya, ibu menyulam puisi itu di tirai!"
  },
  AvgDialog_4882_Content_27 = {
    Text = [[
Sakitku semakin parah, ibu juga mulai sering lupa.
Bagaimana ini? Kalau aku pergi, siapa yang akan merawatnya? Siapa yang akan menjaga toko ini?]]
  },
  AvgDialog_4882_Content_28 = {
    Text = "Aku tidak ingin meninggalkan rumah…keluargaku masih membutuhkanku."
  },
  AvgDialog_4882_Content_29 = {
    Text = "Kematian…tidak, aku belum mau……"
  },
  AvgDialog_4882_Content_3 = {
    Text = "Sebelum <Yellow:wabah> melanda Reini, dia adalah pemilik toko bunga di kota."
  },
  AvgDialog_4882_Content_30 = {
    Text = "Kesedihannya berasal dari kepedihan berpisah dengan keluarga, dari ketakutan akan meninggalkan dunia ini."
  },
  AvgDialog_4882_Content_31 = {
    Text = "Benarkah…tidak ada hubungannya denganku?"
  },
  AvgDialog_4882_Content_32 = {
    Text = "Apakah dia…meninggalkan pesan?"
  },
  AvgDialog_4882_Content_33 = {
    Text = "Dia berkata……"
  },
  AvgDialog_4882_Content_34 = {
    Text = "\"Tetangga baru, layak mendapatkan bunga yang terbaik.\""
  },
  AvgDialog_4882_Content_35 = {
    Text = "<Italic:Pernah mekar, berarti pernah bersinar……>"
  },
  AvgDialog_4882_Content_36 = {
    Text = "Terima kasih telah menyampaikannya…aku akan menulis puisi terakhir untuk kisahnya."
  },
  AvgDialog_4882_Content_37 = {
    Text = "Aurla membungkuk, ujung jarinya menyapu dahi Lily, membawa aroma pekat kelopak bunga dan kesegaran air yang jernih."
  },
  AvgDialog_4882_Content_38 = {
    Text = "Bawalah dia mencari cerita, ke kota, ke alam, ke masa depannya, ke masa lalunya……"
  },
  AvgDialog_4882_Content_39 = {
    Text = "Cerita akan datang menemuimu tanpa terduga."
  },
  AvgDialog_4882_Content_4 = {
    Text = "Aurla berjongkok di samping cairan korosi yang ditinggalkan makhluk bermutasi itu, mengulurkan tangannya dan mengusap perlahan di atas cairan itu."
  },
  AvgDialog_4882_Content_5 = {
    Text = "Ayah dan kakak laki-lakinya meninggal dalam kecelakaan tambang, tapi dia tetap tegar menopang keluarganya."
  },
  AvgDialog_4882_Content_6 = {
    Text = "Setangkai mawar mengkristal dari dalam lumpur, mekar dengan tenang di atas telapak tangannya yang terbuka."
  },
  AvgDialog_4882_Content_7 = {
    Text = "Dia mewarisi toko bunga neneknya, menghidupi dirinya sendiri dan ibunya yang sakit parah… seharusnya dia mendapat akhir yang bahagia dan damai."
  },
  AvgDialog_4882_Content_8 = {
    Text = "Seandainya… dia tidak pernah mengenalku…"
  },
  AvgDialog_4882_Content_9 = {
    Text = "Aurla menundukkan pandangannya, bunga korosi itu perlahan layu dan gugur di bawah tatapannya…"
  },
  AvgDialog_4883_Content_1 = {
    Text = "Bolehkah Aureta juga bercerita? Aureta juga punya cerita!"
  },
  AvgDialog_4883_Content_10 = {Text = "Laut…"},
  AvgDialog_4883_Content_11 = {
    Text = "Terakhir kali melihat laut, adalah saat perjalanan meninggalkan dataran salju bersama Mama…"
  },
  AvgDialog_4883_Content_12 = {
    Text = "Lily juga punya cerita? Oreta ingin mendengarnya!"
  },
  AvgDialog_4883_Content_13 = {
    Text = "Cerita… Sebelum Mama sakit, dia sering menceritakan dongeng sebelum tidur untukku."
  },
  AvgDialog_4883_Content_14 = {
    Text = "Tapi aku… aku juga sudah tidak ingat lagi."
  },
  AvgDialog_4883_Content_15 = {
    Text = "Lily curang——!"
  },
  AvgDialog_4883_Content_16 = {
    Text = "Kamu harus berusaha! Harus berusaha mengingatnya!"
  },
  AvgDialog_4883_Content_17 = {Text = "Tapi..."},
  AvgDialog_4883_Content_18 = {
    Text = "Lily jahat sekali, jangan-jangan mau bermalas-malasan ya?"
  },
  AvgDialog_4883_Content_19 = {
    Text = "Kalau Oreta malas tidak masuk kelas, PR-nya jadi dua kali lipat. Kalau Lily malas, ceritanya juga harus dua kali lipat!"
  },
  AvgDialog_4883_Content_2 = {
    Text = "Dahulu kala— dahulu sekali, Nenek bilang Aureta adalah anak yang berasal dari laut!"
  },
  AvgDialog_4883_Content_20 = {Text = "?!"},
  AvgDialog_4883_Content_21 = {
    Text = "Bukankah ini bagus! Kamu selalu menempel pada Rotan dan \"Ash{Male=tuan,Female=nyonya}\", biasanya tidak pernah bermain dengan kami."
  },
  AvgDialog_4883_Content_22 = {
    Text = "Manfaatkan kesempatan ini supaya semua orang bisa mengenal baumu!"
  },
  AvgDialog_4883_Content_23 = {
    Text = "Cit! Cit cit!"
  },
  AvgDialog_4883_Content_24 = {
    Text = "Naskah! Naskah! Lily tulis naskah!"
  },
  AvgDialog_4883_Content_25 = {
    Text = "Naskah! Naskah! Lily tulis naskah!"
  },
  AvgDialog_4883_Content_3 = {
    Text = "Ayah dan ibu Aureta sudah kembali ke kerajaan di dasar laut, dan ketika Aureta sudah besar nanti, Aureta akan berkumpul kembali dengan mereka."
  },
  AvgDialog_4883_Content_4 = {
    Text = "Mereka pasti sangat mengkhawatirkan Aureta, jadi Aureta akan membawa banyak sekali teman untuk pulang bersama!\nAureta akan membawa anjing, kucing, gagak, Penjaga Rahasia… dan juga ubur-ubur kesukaan Aureta!"
  },
  AvgDialog_4883_Content_5 = {
    Text = "Dengan begitu mereka akan tahu, kehidupan Aureta di daratan juga sangat menyenangkan!"
  },
  AvgDialog_4883_Content_6 = {
    Text = "Rasanya banyak makhluk yang tidak cocok dibawa ke dalam laut ya…"
  },
  AvgDialog_4883_Content_7 = {
    Text = "Aku juga termasuk yang akan dibawa ke dalam laut?"
  },
  AvgDialog_4883_Content_8 = {
    Text = "Iya! Iya iya! Penjaga Rahasia adalah teman Aureta! Lily juga harus ikut!"
  },
  AvgDialog_4883_Content_9 = {Text = "……!"},
  AvgDialog_4884_Content_1 = {
    Text = "Di bawah pimpinan Kassia, kalian berhenti di depan department store terbesar di Londinium, dikelilingi oleh kerumunan pelanggan yang ramai."
  },
  AvgDialog_4884_Content_10 = {
    Text = "Hampir lupa, maksudnya dua orang pendiam membosankan."
  },
  AvgDialog_4884_Content_11 = {
    Text = "Kassia mundur ke belakang semua orang dan mendorong Lily yang sejak tadi diam ke depan."
  },
  AvgDialog_4884_Content_12 = {
    Text = "Nyonya Daffodil, selamat pagi."
  },
  AvgDialog_4884_Content_13 = {
    Text = "Selamat pagi, tamu-tamu kecilku. Biar kutebak kali ini, kalian datang untuk apa……"
  },
  AvgDialog_4884_Content_14 = {
    Text = "\"Film yang bisa merekam bayangan Awakened\"… Aku memang bisa mencarikan benda seperti itu untuk para tamu."
  },
  AvgDialog_4884_Content_15 = {
    Text = "Bagaimana kau bisa tahu? Jangan bilang kau menyuruh seseorang menguntit kami lagi?!"
  },
  AvgDialog_4884_Content_16 = {
    Text = "Bagaimana mungkin aku bisa meramalkan bahwa kalian akan secara tidak sengaja merusak film yang berharga?"
  },
  AvgDialog_4884_Content_17 = {
    Text = "Daphodel menyunggingkan senyum misterius yang tak terbaca, lalu meletakkan barang yang kalian inginkan di atas meja."
  },
  AvgDialog_4884_Content_18 = {
    Text = "Film yang telah diproses dengan larutan inti perak kemurnian tinggi, mampu merekam wujud Awakened dengan normal, sangat berharga. Toko kecil ini saat ini hanya punya satu lho."
  },
  AvgDialog_4884_Content_19 = {
    Text = "Bukankah film khusus itu <Yellow:penelitian baru Dor>? Dari mana kau mendapatkannya?"
  },
  AvgDialog_4884_Content_2 = {
    Text = "Ini terlalu ramai, bagaimana bisa wanita itu membuka toko di tempat seperti ini?"
  },
  AvgDialog_4884_Content_20 = {
    Text = [[
Pedagang yang melintasi dimensi, tentu punya jalur khusus.
Jangan menatapku dengan pandangan curiga seperti itu, aku bisa sedih lho.]]
  },
  AvgDialog_4884_Content_21 = {
    Text = "Bagaimana? Kalau tidak butuh, aku simpan kembali ya."
  },
  AvgDialog_4884_Content_22 = {
    Text = "Baik, kami ambil."
  },
  AvgDialog_4884_Content_23 = {
    Text = "Lily meremas tanganmu pelan, matanya menyiratkan sedikit kegelisahan."
  },
  AvgDialog_4884_Content_24 = {
    Text = "Toko pertukaran… harus memberikan imbalan kepada Nyonya."
  },
  AvgDialog_4884_Content_25 = {
    Text = "Wah, Lily masih ingat aturan di tempatku."
  },
  AvgDialog_4884_Content_26 = {
    Text = "Tenang, kali ini yang kuminta tidak banyak — aku ingin melihat \"cerita\"."
  },
  AvgDialog_4884_Content_27 = {
    Text = [[
Sebuah cerita yang menakjubkan, sempurna, dan tanpa penyesalan.
Itulah yang ingin kutukarkan.]]
  },
  AvgDialog_4884_Content_3 = {
    Text = "\"Kalau ingin menyembunyikan kartu 6 berlian, kocok saja ke dalam setumpuk kartu\"."
  },
  AvgDialog_4884_Content_4 = {
    Text = [[
Kassia membawa kalian ke samping department store dan mendorong pintu toko terlebih dahulu.
Sepuhan asap ungu menarik semua orang masuk ke dalam.]]
  },
  AvgDialog_4884_Content_5 = {
    Text = "Selamat datang kembali di \"Toko Tukar\" milikku, para tamu terhormatku, dan juga……"
  },
  AvgDialog_4884_Content_6 = {
    Text = [[
Dan juga "karyawan" kesayanganku.
Bagaimana kehidupan di Misagor, apakah kau sudah belajar tentang emosi yang sesungguhnya?]]
  },
  AvgDialog_4884_Content_7 = {
    Text = "Terima kasih atas kemurahan hati Nyonya, tapi dari tikus kecil yang berisik, organisme bersel satu yang tidak tahu apa-apa, maniak kekerasan yang sombong, dan si pendiam membosankan, memang tidak ada yang bisa dipelajari."
  },
  AvgDialog_4884_Content_8 = {
    Text = "Siapa yang berisik?!"
  },
  AvgDialog_4884_Content_9 = {
    Text = "Pendiam membosankan… itu tentang aku?"
  },
  AvgDialog_4885_Content_2 = {
    Text = "Berhenti! Lepaskan gadis itu!"
  },
  AvgDialog_4885_Content_3 = {
    Text = "Oh? Jangan-jangan Anda adalah yang termasyhur itu…… <Blue:Inspektur G dari Divisi Taman Kepolisian Londinium>."
  },
  AvgDialog_4885_Content_4 = {
    Text = "Ti, tidak salah lagi. Akulah <Blue:Kepala Divisi Tam— Kepolisian Londini— ugh!>"
  },
  AvgDialog_4885_Content_5 = {
    Text = "Gelar yang terlalu sulit diucapkan membuat sang inspektur menggigit lidahnya sendiri, tapi hal itu tidak akan menggoyahkan tekadnya untuk menyelamatkan warga sipil yang tak bersalah."
  },
  AvgDialog_4885_Content_6 = {
    Text = "Aku akan menyelamatkannya dari rencana jahatmu! Terimalah penghakiman ini! Penyihir jahat Houdini!"
  },
  AvgDialog_4886_Content_1 = {Text = "Ah…!"},
  AvgDialog_4886_Content_2 = {
    Text = "<Small:Rusak……>"
  },
  AvgDialog_4886_Content_3 = {
    Text = "Lagi, lagi! Cassia juga bersenang-senang, kan!"
  },
  AvgDialog_4886_Content_4 = {
    Text = "Dasar tidak sopan! Akan kucabik-cabik kau! Akan kubuat kau tak punya tempat lagi di dunia film!"
  },
  AvgDialog_4886_Content_5 = {
    Text = "Sst, sst! Jangan provokasi Nona Cassia lagi."
  },
  AvgDialog_4886_Content_6 = {
    Text = "Perhatian semua orang tersedot oleh pertarungan yang kacau, sehingga seruan kecil itu tidak menarik perhatian siapa pun."
  },
  AvgDialog_4886_Content_7 = {
    Text = "Lily menarik napas dalam-dalam dan berteriak sekuat tenaga."
  },
  AvgDialog_4886_Content_8 = {
    Text = "Rusak…… <BigShake:Mesinnya rusak!>"
  },
  AvgDialog_4887_Content_1 = {
    Text = [[
Perawat dengan cekatan menahan pasien yang mengamuk, dan dengan beberapa gerakan cepat mengikat tangan dan kaki pasien dengan tali kulit.
Setelah selesai, barulah ia teringat ada orang luar di sini, dan dengan agak malu menggaruk-garuk kepalanya.]]
  },
  AvgDialog_4887_Content_10 = {
    Text = "Di sana terdapat genangan besar Originium Slug yang tidak terlihat oleh orang biasa—mungkin, inilah sumber dari kegilaan itu."
  },
  AvgDialog_4887_Content_2 = {
    Text = "Kalian hati-hati ya, hari ini pasien-pasien mengamuk sangat parah. Jangan sampai kalian terluka."
  },
  AvgDialog_4887_Content_3 = {
    Text = "Mengamuk secara massal? Apakah hal seperti ini sering terjadi?"
  },
  AvgDialog_4887_Content_4 = {
    Text = "Orang-orang yang dibuang ke sanatorium ini, mentalnya rapuh seperti kertas yang dijemur tujuh hari tujuh malam—sedikit angin saja langsung hancur. Kegilaan massal yang tiba-tiba bukanlah hal aneh di sini."
  },
  AvgDialog_4887_Content_5 = {
    Text = "Ayo jalan, penanggung jawab seharusnya ada di lantai ini."
  },
  AvgDialog_4887_Content_6 = {
    Text = "Eh! Hati-hati!"
  },
  AvgDialog_4887_Content_7 = {
    Text = "Kau mendorong perawat itu dengan keras. Ia terhuyung beberapa langkah dan menatapmu dengan wajah bingung."
  },
  AvgDialog_4887_Content_8 = {
    Text = "Ada sedikit genangan air di sana. Sebaiknya kita lewat pinggir koridor saja."
  },
  AvgDialog_4887_Content_9 = {
    Text = "Perawat itu tidak banyak bertanya dan menghindari arah yang kau tunjukkan. Hanya kau yang diam-diam menghela napas lega."
  },
  AvgDialog_4888_Content_1 = {
    Text = [[
Tim keamanan, kalian bantu Nona Ellie membawa pasien di halaman kembali ke bangsal.
Daisy, kamu pergi siapkan perlengkapan penenang dan peralatan mandi untuk pasien.]]
  },
  AvgDialog_4888_Content_10 = {
    Text = "Terima kasih sudah membawa teman lama yang datang dari jauh ke hadapan saya."
  },
  AvgDialog_4888_Content_11 = {
    Text = "Kalau bilang \"terima kasih\" itu terlalu formal, kalau begitu kami pergi menangani insiden di bangsal dulu ya."
  },
  AvgDialog_4888_Content_12 = {
    Text = "Para staf medis satu per satu memberi isyarat kepada Nymphia, dan baru meninggalkan kantor setelah mendapat persetujuannya."
  },
  AvgDialog_4888_Content_13 = {
    Text = "Sepertinya setelah insiden Cerberus, kamu hidup dengan baik di sini."
  },
  AvgDialog_4888_Content_14 = {
    Text = "Berkat Anda dan Nona Ramona, sanatorium ini bisa berjalan dengan lancar dan stabil."
  },
  AvgDialog_4888_Content_15 = {
    Text = "Berkunjung larut malam begini, apakah ada sesuatu yang terjadi?"
  },
  AvgDialog_4888_Content_16 = {
    Text = "Kamu menjelaskan kepada gadis berwajah pucat itu, tentang syuting, tentang naskah, tentang Lily…"
  },
  AvgDialog_4888_Content_17 = {
    Text = "Begitu rupanya…ingin membuat cerita ya?\nSaya tidak bisa menulis puisi, juga tidak bisa menulis naskah, tapi saya sudah membaca cukup banyak cerita."
  },
  AvgDialog_4888_Content_18 = {
    Text = "Nymphia memejamkan mata, bertutur dengan lembut bagaikan melantunkan syair."
  },
  AvgDialog_4888_Content_19 = {
    Text = "Yang terpenting, bukankah <Yellow:mendengarkan>?\nDengarkan suara hati, ikuti aliran emosi…mereka akan membawamu menemukan jawabannya."
  },
  AvgDialog_4888_Content_2 = {
    Text = "Tuan Jackson, kamu…pergi bantu potong kentang untuk kari, jangan sampai terbuang sia-sia."
  },
  AvgDialog_4888_Content_20 = {
    Text = "Lily mendengarkan dan merenungkan dengan setengah paham, mencoba memahami kata-kata Nymphia."
  },
  AvgDialog_4888_Content_21 = {
    Text = "Di tengah percakapan, rintihan samar-samar terdengar dari lantai bawah. Lily yang sedang serius berpikir juga terkejut, dan menabrak kaki Nymphia dengan keras."
  },
  AvgDialog_4888_Content_22 = {
    Text = "Dia terdengar sangat kesakitan……"
  },
  AvgDialog_4888_Content_23 = {
    Text = "Pasien di sini, kondisinya bisa memburuk secara tiba-tiba dan tidak teratur, biasanya akan kembali normal setelah setengah hari……\nMaaf kalian harus melihat ini."
  },
  AvgDialog_4888_Content_24 = {
    Text = "Anda bisa menghubungi Universitas Misager untuk meminta bantuan menyelidiki penyebabnya. Lord Dexter seharusnya sudah meninggalkan informasi kontak."
  },
  AvgDialog_4888_Content_25 = {
    Text = "Saya tahu penyebab anomali ini, dan saya khawatir ini adalah masalah yang bahkan Misager pun tidak bisa selesaikan."
  },
  AvgDialog_4888_Content_26 = {
    Text = "Saya juga harus pergi membantu \"membersihkan\", apakah Anda ingin ikut bersama saya?"
  },
  AvgDialog_4888_Content_3 = {
    Text = "Ada yang melihat Tuan Robert? Ada yang pergi mencarinya? Setahu saya dia bertugas jaga di bangsal kedua malam ini…"
  },
  AvgDialog_4888_Content_4 = {
    Text = "Saya di sini, Nona Nymphia."
  },
  AvgDialog_4888_Content_5 = {
    Text = [[
Yang mengatur pekerjaan medis dengan teratur dan rapi itu adalah Nymphia, yang pernah kamu temui sebelumnya.
Melihat kemunculanmu di sanatorium, wajahnya juga menunjukkan ekspresi terkejut.]]
  },
  AvgDialog_4888_Content_6 = {
    Text = "Kamu…dan Lily juga."
  },
  AvgDialog_4888_Content_7 = {
    Text = "Kak Nymphia."
  },
  AvgDialog_4888_Content_8 = {
    Text = "Kalian berdua ternyata kenal Nona Polonaise, kenapa tidak bilang dari tadi? Saya kira kalian penipu entah dari mana."
  },
  AvgDialog_4888_Content_9 = {
    Text = "Nymphia tertawa pelan, lalu menggandeng tangan Lily."
  },
  AvgDialog_4889_Content_1 = {
    Text = "Akhir yang Paling Sempurna"
  },
  AvgDialog_4889_Content_10 = {
    Text = "Dia pernah melihat pameran lukisan, pergi ke kebun binatang, naik kereta bawah tanah dan kereta api. Mereka bahkan menaiki kapal menyusuri Sungai Isis, meluncur langsung menuju Lautan Selatan yang luas!"
  },
  AvgDialog_4889_Content_11 = {
    Text = "Setelah mengalami berbagai petualangan, keduanya menjalani kehidupan yang tenang dan damai… tetapi sang gadis tetap menyimpan rasa ingin tahu dan kerinduan terhadap hal-hal yang belum diketahui."
  },
  AvgDialog_4889_Content_12 = {
    Text = "Rasa ingin tahu… apakah itu hal yang buruk?"
  },
  AvgDialog_4889_Content_13 = {
    Text = "Tidak tidak tidak, itu pasti hal yang baik. Rasa ingin tahu adalah kekuatan abadi yang mendorong peradaban untuk terus maju——"
  },
  AvgDialog_4889_Content_14 = {
    Text = "Sayangnya kali ini, sang gadis menjadi penasaran terhadap sebuah bengkel misterius…"
  },
  AvgDialog_4889_Content_15 = {
    Text = "Memberi isyarat mata kepada Kassia"
  },
  AvgDialog_4889_Content_16 = {
    Text = "Kamu mengedipkan mata dan memberi isyarat kepada Kassia. Sang pesulap yang sejak tadi membeku setelah pengeras suaranya kamu rebut, akhirnya tersadar kembali."
  },
  AvgDialog_4889_Content_17 = {
    Text = "Kenapa peran penjahat besar ini selalu aku lagi yang harus memerankannya?"
  },
  AvgDialog_4889_Content_18 = {
    Text = "Demi mendukung pekerjaanmu——atau mungkin sekadar ingin berbuat jahil, meskipun mulutnya menggerutu tak puas, dia tetap dengan sangat kooperatif memunculkan ilusi sihirnya sekali lagi."
  },
  AvgDialog_4889_Content_19 = {
    Text = "Di dalam bengkel sihir, cahaya suram dan menyeramkan menyala, sinar aneh itu merampas vitalitas dunia orang hidup, membuat orang merasa seolah berada di alam baka."
  },
  AvgDialog_4889_Content_2 = {Text = "Ssshh—!"},
  AvgDialog_4889_Content_20 = {
    Text = "Aku adalah Ahli Sulap dari dunia orang mati, Houdini! Gadis kecil yang cantik ini adalah alat sulap favoritku——wahai para petualang pemberani, apakah kalian punya keberanian untuk menantangku!"
  },
  AvgDialog_4889_Content_21 = {
    Text = "Ka-Kassia…?"
  },
  AvgDialog_4889_Content_22 = {
    Text = "Houdini! Ahli Sulap Houdini! Seharusnya kamu ketakutan sampai menangis meraung-raung dan kehilangan akal sehatmu!"
  },
  AvgDialog_4889_Content_23 = {
    Text = "Di bawah tatapan penuh harap darimu dan Kassia, Lily menelan ludah beberapa kali secara mekanis——"
  },
  AvgDialog_4889_Content_24 = {
    Text = "Da-datanglah…"
  },
  AvgDialog_4889_Content_25 = {
    Text = "Lebih keras! Menangislah! Biarkan aku mendengar ketakutan dari lubuk jiwamu yang terdalam!"
  },
  AvgDialog_4889_Content_26 = {
    Text = "<BigShake:To, tolong!! Bantu aku—Ibu!>"
  },
  AvgDialog_4889_Content_3 = {
    Text = "Suara apa itu?!"
  },
  AvgDialog_4889_Content_4 = {
    Text = "Secara refleks, Rotan menghalangi para Awakened kecil di belakangnya, kedua tangannya mencengkeram gagang pedang dengan penuh kewaspadaan."
  },
  AvgDialog_4889_Content_5 = {
    Text = "Maaf, ini pertama kalinya aku menggunakan pengeras suara ini."
  },
  AvgDialog_4889_Content_6 = {
    Text = "Masih mau bermain sebentar lagi?"
  },
  AvgDialog_4889_Content_7 = {
    Text = "Kamu menggelengkan kepala, lalu menekan tombol pengeras suara sekali lagi, sekaligus mengarahkan lampu sorot kembali ke tengah panggung."
  },
  AvgDialog_4889_Content_8 = {
    Text = "Gadis pemberani dan Nyonya Petualang kembali ke kota. Sang petualang memperlakukan gadis itu seperti anaknya sendiri, membawanya mengalami berbagai hal dalam kehidupan sehari-hari——"
  },
  AvgDialog_4889_Content_9 = {
    Text = "Mata Lily tiba-tiba berbinar, ia membelalakkan matanya dengan ekspresi tak percaya."
  },
  AvgDialog_4890_Content_1 = {
    Text = "<Change>Aku tidak mau…pergi…dari rumah…"
  },
  AvgDialog_4890_Content_2 = {
    Text = "<Change>Kematian…tidak……"
  },
  AvgDialog_4890_Content_3 = {
    Text = "Emosi berat mencengkeram pergelangan kakimu, menyeretmu menuju jurang tak kasat mata, bahkan bernapas pun terasa sesak."
  },
  AvgDialog_4890_Content_4 = {
    Text = "Dada terasa berat, Lily merasa sangat tidak nyaman……"
  },
  AvgDialog_4890_Content_5 = {
    Text = "Maaf, membuatmu merasa tidak nyaman."
  },
  AvgDialog_4890_Content_6 = {
    Text = "Penjaga Rahasia, tolong bantu aku mengalahkannya."
  },
  AvgDialog_4891_Content_1 = {
    Text = "Penyair muda itu menggelengkan kepalanya, nada bicaranya sendu dan murung. Entah sejak kapan ia telah menyusut kembali ke balik kertas suratnya, memancarkan secercah kesedihan."
  },
  AvgDialog_4891_Content_2 = {
    Text = "Diselimuti oleh bayangan kesedihan, puisi dan inspirasiku… bagi Penjaga Rahasia dan Lily, sepertinya tidak akan banyak berguna."
  },
  AvgDialog_4891_Content_3 = {
    Text = "Bayangan… kesedihan?"
  },
  AvgDialog_4891_Content_4 = {
    Text = "Menghadapi ekspresi bingung Lily, Orla menghela napas pelan nyaris tak terdengar."
  },
  AvgDialog_4891_Content_5 = {
    Text = "Jika boleh, izinkan aku menunjukkannya kepada kalian…"
  },
  AvgDialog_4891_Content_6 = {
    Text = "Orla mendorong pintu kamar terbuka, dunia tak lagi terhalang di luar, udara pekat dan stagnan langsung membanjiri ruangan."
  },
  AvgDialog_4891_Content_7 = {
    Text = "Apa yang dimaksud dengan \"bayangan kesedihan\"."
  },
  AvgDialog_4892_Content_1 = {
    Text = "<Change>Orang yang baru pindah di ujung jalan…bakatnya……"
  },
  AvgDialog_4892_Content_2 = {
    Text = "<Change>Bunga terbaik…dia……"
  },
  AvgDialog_4892_Content_3 = {
    Text = "<Change>Bungaku…puisi…"
  },
  AvgDialog_4892_Content_4 = {
    Text = "<Gray:Kota Reini pernah mengalami bencana Erosi yang parah, mungkin, suara para penduduk yang menjadi korban selamanya tertinggal di sini……>"
  },
  AvgDialog_4893_Content_1 = {
    Text = "<Change>Sa-sakit…aku sakit……"
  },
  AvgDialog_4893_Content_2 = {
    Text = "Siapa itu?!"
  },
  AvgDialog_4893_Content_3 = {
    Text = "Di belakang tak ada apa pun, hanya angin yang membawa ratapan berat."
  },
  AvgDialog_4893_Content_4 = {
    Text = "Apakah Anda mendengar sesuatu?"
  },
  AvgDialog_4893_Content_5 = {
    Text = "Tidak…mungkin hanya halusinasi."
  },
  AvgDialog_4894_Content_1 = {
    Text = "Dasar tidak berguna! Tidak becus! Kalian sudah mengusir semua figuran Kassia!"
  },
  AvgDialog_4894_Content_10 = {
    Text = "Di saat-saat kritis, Augier mengayunkan tombaknya dan memukul kelinci yang melesat liar itu hingga kembali menjadi bayangan samar."
  },
  AvgDialog_4894_Content_11 = {
    Text = "Menyebalkan! Menyebalkan! Orang yang tidak mau bekerja sama tidak layak berada di lokasi syuting Sutradara Kassia!"
  },
  AvgDialog_4894_Content_12 = {
    Text = [[
Sepertinya, kalau tidak menghajarnya dulu, dia tidak akan berhenti melakukan "peniruan emosi".
Kali ini kamu tidak berhak menyebutku "maniak bertarung" lagi, kan?]]
  },
  AvgDialog_4894_Content_13 = {
    Text = "Lain kali jangan biarkan dia membaca majalah sembarangan lagi……"
  },
  AvgDialog_4894_Content_2 = {
    Text = "Figuran? Oreta tahu, Oreta tahu!"
  },
  AvgDialog_4894_Content_3 = {
    Text = "Oreta sendiri sudah seperti segerombolan aktor!"
  },
  AvgDialog_4894_Content_4 = {
    Text = "Kamu ini benar-benar——"
  },
  AvgDialog_4894_Content_5 = {
    Text = "\"Sutradara\" mengayunkan tongkat sulapnya dengan marah, kartu-kartu properti beterbangan ke segala arah, dan banyak benda di sekitar muncul goresan yang mencolok."
  },
  AvgDialog_4894_Content_6 = {
    Text = "Kyaa——!"
  },
  AvgDialog_4894_Content_7 = {
    Text = "Kelinci bayangan juga menabrak dekorasi panggung hingga berantakan, lalu akhirnya mengunci Oreta sebagai target dan melesat lurus ke arahnya."
  },
  AvgDialog_4894_Content_8 = {Text = "Hati-hati!"},
  AvgDialog_4895_Content_1 = {
    Text = "Orang yang Paling Dirindukan"
  },
  AvgDialog_4895_Content_10 = {
    Text = [[
Begitu ruangan dibuka, Anjing Dimensi yang terkurung di dalamnya akan menerobos garis segel waktu.
Kondisi Francesca yang berada di dalamnya sama sekali tidak bisa diketahui.]]
  },
  AvgDialog_4895_Content_11 = {
    Text = "Kamu tidak bisa memberikan janji apa pun kepada Lily, dan juga tidak ingin memberinya janji yang tidak bisa ditepati."
  },
  AvgDialog_4895_Content_2 = {
    Text = "Sudah cukup lama sejak terakhir kali kamu mengunjungi tempat ini. Meskipun pemandangannya tidak berubah, udara di sini tidak lagi dipenuhi suasana tegang dan mencekam."
  },
  AvgDialog_4895_Content_3 = {
    Text = "Tempat yang pernah diselimuti awan gelap \"Cerberus\" ini, tampaknya telah menyambut kembali kedamaian yang sesungguhnya."
  },
  AvgDialog_4895_Content_4 = {
    Text = "Lily, kamu baik-baik saja?"
  },
  AvgDialog_4895_Content_5 = {
    Text = "Meskipun Lily biasanya memang anak yang pendiam, tapi sejak memasuki wilayah Kota Kecil Rye, dia sama sekali tidak berkata apa-apa."
  },
  AvgDialog_4895_Content_6 = {
    Text = "Kamu merasakan sesak di dada, gelisah, gembira, takut… emosi yang bercampur aduk menyentuh sarafmu melalui tautan."
  },
  AvgDialog_4895_Content_7 = {
    Text = "Tuan… kali ini, bisakah Lily bertemu dengan Ibu?"
  },
  AvgDialog_4895_Content_8 = {
    Text = "Meskipun Lily tidak bertambah besar… tapi kita sudah pergi begitu lama, apakah dia masih bisa mengenali Lily?"
  },
  AvgDialog_4895_Content_9 = {
    Text = "Melihat mata Lily yang samar-samar berkilau penuh harapan, kamu mengelus rambutnya yang lembut bak sutra, lalu menggandengnya berjalan menuju ujung lain jembatan rel kereta—"
  },
  AvgDialog_4896_Content_1 = {
    Text = "Orang ini akhirnya tidak lagi seperti patung kayu."
  },
  AvgDialog_4896_Content_2 = {
    Text = "Tuan tidak pernah seperti patung kayu, {Male=dia,Female=dia}hanya, hanya sedikit……"
  },
  AvgDialog_4896_Content_3 = {
    Text = "Tenang? Dewasa? Atau kau mau bilang membosankan?"
  },
  AvgDialog_4896_Content_4 = {
    Text = "Aku sama sekali tidak bermaksud demikian!"
  },
  AvgDialog_4896_Content_5 = {
    Text = "Melihat Aughier wajahnya memerah hanya karena beberapa patah kata darinya, Lotthen tertawa terbahak-bahak, lalu mendorong ksatria muda itu ke bawah sorotan lampu."
  },
  AvgDialog_4896_Content_6 = {
    Text = "Pergilah bergabung dengan mereka, rekaman ini tidak boleh tanpa kehadiranmu."
  },
  AvgDialog_4897_Content_1 = {
    Text = "Kalian sudah menghina naskah sulap Kassia!! Sekarang kalian semua harus……<Big:Dengarkan kata sutradara, dan bekerjasamalah denganku dengan patuh!>"
  },
  AvgDialog_4897_Content_2 = {
    Text = "<Yellow:《Panduan Bergaul dengan Kassia oleh Dafudel》> halaman pertama tertulis, Kassia mengidap <Yellow:gangguan emosional>, semua ekspresi emosinya hanyalah peniruan dari dunia luar."
  },
  AvgDialog_4897_Content_3 = {
    Text = "Kalau begitu, dari mana dia bisa semarah ini?"
  },
  AvgDialog_4897_Content_4 = {
    Text = "<Big:Rasakan <Red:kekuatan Andy Johnson>!>"
  },
  AvgDialog_4897_Content_5 = {
    Text = "Andy Johnson? Nama yang terdengar familiar, di mana ya pernah dengar……"
  },
  AvgDialog_4897_Content_6 = {
    Text = "Aku tahu nama itu!! Dia sutradara besar dari Oakwood, Republik Yagro!"
  },
  AvgDialog_4897_Content_7 = {
    Text = "Aku pernah dengar ibu-ibu di pasar membicarakan dia, katanya tahun lalu dia memukul asisten fotografinya sampai masuk rumah sakit!!"
  },
  AvgDialog_4897_Content_8 = {
    Text = "Setidaknya sekarang kita tahu siapa yang sedang dia tiru……"
  },
  AvgDialog_4898_Content_1 = {
    Text = "Bunga Terbaik"
  },
  AvgDialog_4898_Content_10 = {
    Text = "Lily, kamu… tidak bisa membaca?"
  },
  AvgDialog_4898_Content_11 = {
    Text = "Lily… aku……"
  },
  AvgDialog_4898_Content_12 = {
    Text = "Lily menundukkan kepala dan ragu-ragu sejenak, akhirnya mengangguk, wajahnya penuh dengan kegelisahan."
  },
  AvgDialog_4898_Content_13 = {
    Text = "Menulis, ibu pernah mengajarkan. Tapi……Lily sudah tidak ingat lagi.\nCerita, naskah, Lily juga tidak bisa menulisnya."
  },
  AvgDialog_4898_Content_14 = {
    Text = [[
Jangan takut, aku tidak bermaksud memaksamu.
Ayo kita lakukan bersama-sama.]]
  },
  AvgDialog_4898_Content_15 = {
    Text = "Lily bisa ceritakan padaku, cerita ini tentang apa?"
  },
  AvgDialog_4898_Content_16 = {
    Text = "Ada cerita tentang ibu, Kumm, dan Lily."
  },
  AvgDialog_4898_Content_17 = {
    Text = "Ceritanya dimulai dengan alur seperti apa? Hmm… dengan kata lain, Lily ingin bercerita mulai dari kapan?"
  },
  AvgDialog_4898_Content_19 = {
    Text = "Tidak tahu……"
  },
  AvgDialog_4898_Content_2 = {
    Text = "Lily duduk di depan meja rias, kedua kakinya yang tidak menyentuh lantai berayun-ayun dengan susah payah."
  },
  AvgDialog_4898_Content_20 = {
    Text = "Penjaga Rahasia, ikut aku sebentar."
  },
  AvgDialog_4898_Content_21 = {
    Text = "Rotan langsung menarikmu ke pinggir lokasi syuting, menatapmu dengan pandangan tidak setuju."
  },
  AvgDialog_4898_Content_22 = {
    Text = "Masa lalu anak itu juga tidak ada yang layak dikenang, menyuruhnya menulis hal-hal itu menjadi cerita, bukankah itu kurang tepat?"
  },
  AvgDialog_4898_Content_23 = {
    Text = "Kalian duduk di sini setengah hari tapi tidak menghasilkan apa-apa, menurutku, lebih baik ajak Lily jalan-jalan keluar, cari inspirasi lain."
  },
  AvgDialog_4898_Content_24 = {
    Text = "Telinga yang tajam menangkap namanya sendiri, Lily memegang pena dan melompat turun dari kursi, berlari ke sisi kalian seperti hewan kecil."
  },
  AvgDialog_4898_Content_25 = {
    Text = "Rotan mengusap kepala kecil gadis itu, mengambil krayon dan menyerahkannya ke tanganmu."
  },
  AvgDialog_4898_Content_26 = {
    Text = "Pergi keluar lihat-lihat pemandangan, biarkan dia mengobrol dengan orang yang bisa menulis. Kalau kamu sih……"
  },
  AvgDialog_4898_Content_27 = {
    Text = "Ikut saja di belakang dan catat inspirasinya."
  },
  AvgDialog_4898_Content_28 = {
    Text = "Tuan, kita mau ke mana?"
  },
  AvgDialog_4898_Content_29 = {
    Text = "Berbicara soal \"orang yang bisa menulis\"… kita pasti harus menemui orang itu."
  },
  AvgDialog_4898_Content_3 = {
    Text = "Cerita… cerita……"
  },
  AvgDialog_4898_Content_30 = {
    Text = "\"Orang itu\"?"
  },
  AvgDialog_4898_Content_31 = {
    Text = "Seorang kakak perempuan yang sangat berbakat. Rotan telah menghubunginya untuk kita, kita bisa bertemu dengannya begitu kereta tiba di stasiun terakhir."
  },
  AvgDialog_4898_Content_32 = {
    Text = "Lily mengangguk dengan polos, menggenggam tanganmu dan tidak berkata apa-apa lagi."
  },
  AvgDialog_4898_Content_33 = {
    Text = "Ini adalah kali kedua dia naik kereta bawah tanah. Tanpa keceriaan dan rasa ingin tahu seperti sebelumnya, kali ini gadis kecil itu hanya menempel padamu dengan patuh dan waspada. Persis seperti hewan kecil yang bergantung pada pelukan ibunya."
  },
  AvgDialog_4898_Content_4 = {
    Text = "Dia memegang pena sambil bergumam, ujung pena bergeser, bersentuhan dengan permukaan kertas mengeluarkan suara gesekan."
  },
  AvgDialog_4898_Content_5 = {
    Text = "Ekspresinya serius dan sungguh-sungguh, goresan penanya kuat menembus kertas, kokoh dan bertenaga—"
  },
  AvgDialog_4898_Content_6 = {
    Text = "Namun yang terlihat di atas kertas bukanlah tulisan, melainkan hanya sebuah gambar sketsa sederhana yang kekanak-kanakan."
  },
  AvgDialog_4898_Content_7 = {
    Text = "Ini… Kum dan Francis?"
  },
  AvgDialog_4898_Content_8 = {Text = "Ya…!"},
  AvgDialog_4898_Content_9 = {
    Text = "Tu, Tuan……"
  },
  AvgDialog_4899_Content_1 = {
    Text = "Kamu dan Lily mengetuk sebuah pintu tak mencolok di sudut jalan."
  },
  AvgDialog_4899_Content_10 = {
    Text = "Tidak tidak tidak, Nona Aurla salah paham."
  },
  AvgDialog_4899_Content_11 = {
    Text = "Anda datang mengunjungi saya, bukankah untuk naskah?"
  },
  AvgDialog_4899_Content_12 = {
    Text = "Ya, tapi juga bukan."
  },
  AvgDialog_4899_Content_13 = {
    Text = "Kamu menunduk menatap Lily yang hampir bergelantungan di kakimu, lalu perlahan mendorongnya ke hadapan Aurla."
  },
  AvgDialog_4899_Content_14 = {
    Text = "<Italic:Kehidupan yang tak terduga, mekar di luar batas waktu…>"
  },
  AvgDialog_4899_Content_15 = {
    Text = "Halo, Lily."
  },
  AvgDialog_4899_Content_16 = {Text = "Ha, halo!"},
  AvgDialog_4899_Content_17 = {
    Text = "Kami ingin meminta petunjuk dari Anda, tentang cara menciptakan sebuah cerita."
  },
  AvgDialog_4899_Content_2 = {
    Text = "Datang dari jauh, maaf tidak bisa menyambut lebih awal…"
  },
  AvgDialog_4899_Content_3 = {
    Text = "Itu adalah aroma mawar yang membawa kesegaran embun pagi, mengalir keluar dari celah pintu yang terbuka, mengalir secara tersembunyi dan tak henti-hentinya."
  },
  AvgDialog_4899_Content_4 = {
    Text = "Lama tidak bertemu, <Blue:Nona Aurla>."
  },
  AvgDialog_4899_Content_5 = {
    Text = "Selamat pagi, Penjaga Rahasia."
  },
  AvgDialog_4899_Content_6 = {
    Text = "Tamu kecil ini adalah…?"
  },
  AvgDialog_4899_Content_7 = {
    Text = "Kamu menjelaskan kepada sang penyair, tentang pengambilan gambar, tentang naskah, tentang Lily…"
  },
  AvgDialog_4899_Content_8 = {
    Text = "Begitu rupanya, untuk menguji kamera yang telah dimodifikasi oleh Nona Dor, kalian perlu membuat sebuah film…"
  },
  AvgDialog_4899_Content_9 = {
    Text = "Tapi mungkin kamu masih ingat, aku hanyalah seorang penyair yang tidak berarti… dalam penulisan naskah film, aku sama sekali tidak bisa disebut \"memenuhi syarat\"."
  },
  AvgDialog_4900_Content_1 = {
    Text = "Ilusi yang Paling Megah"
  },
  AvgDialog_4900_Content_10 = {
    Text = "Kalau tidak, memangnya kenapa kenapa?"
  },
  AvgDialog_4900_Content_11 = {
    Text = "Kau akan menabrak dekorasi set yang sesungguhnya di balik ilusi sampai babak belur!"
  },
  AvgDialog_4900_Content_12 = {
    Text = "Kalian semua, pernah bertemu dengan wanita yang merangkap sebagai dokter kampus dan psikolog di Universitas Misage?"
  },
  AvgDialog_4900_Content_13 = {
    Text = "Dia itu raja iblis yang licik, culas, dan jahat. Konon orang yang terluka pergi ke tempatnya, akhirnya keluar dalam keadaan terbaring."
  },
  AvgDialog_4900_Content_14 = {
    Text = "I-ini tidak terekam, kan?"
  },
  AvgDialog_4900_Content_15 = {
    Text = "Augier menatap cemas ke arahmu yang memegang kamera, dan baru bernapas lega setelah mendapat jawaban yang meyakinkan."
  },
  AvgDialog_4900_Content_16 = {
    Text = "Nona Silvia sebenarnya sangat lembut dalam menangani murid yang terluka secara tidak sengaja…"
  },
  AvgDialog_4900_Content_17 = {
    Text = "Karena semua sudah siap, mari kita mulai syutingnya."
  },
  AvgDialog_4900_Content_18 = {
    Text = "Hore— syuting~ syuting~"
  },
  AvgDialog_4900_Content_19 = {
    Text = "Aureta, ke sini! Kita tidak perlu tampil di adegan ini, ayo tunggu di luar jangkauan kamera dulu——"
  },
  AvgDialog_4900_Content_2 = {
    Text = "Para aktor cilik, sudah siap?!"
  },
  AvgDialog_4900_Content_20 = {
    Text = "Para Awakened masing-masing mencari tempat bersembunyi di luar jangkauan kamera. Kamu melirik \"naskah\" yang hanya berisi beberapa baris kalimat untuk terakhir kalinya, lalu berjalan menuju posisi kemunculanmu yang telah ditentukan."
  },
  AvgDialog_4900_Content_3 = {
    Text = "Penjaga rahasia, sudah siap?!"
  },
  AvgDialog_4900_Content_4 = {
    Text = "Jangan berkedip, tahan napas— ah sudahlah, sekarang bernapas juga boleh."
  },
  AvgDialog_4900_Content_5 = {
    Text = "Karena sulap ilusi Cassia pasti akan membuat orang terpukau sampai tak bisa bernapas—!"
  },
  AvgDialog_4900_Content_6 = {
    Text = "Pemandangan berputar dan kabur, setelah sesaat hancur berkeping-keping, pecahan itu menyatu menjadi pemandangan nyata yang sangat kau kenal."
  },
  AvgDialog_4900_Content_7 = {
    Text = "I-ini sihir apa?!"
  },
  AvgDialog_4900_Content_8 = {
    Text = "Cit, cit cit cit!"
  },
  AvgDialog_4900_Content_9 = {
    Text = "Awasi baik-baik rekan pencuri kecilmu, sulap ilusi Cassia hanyalah tipuan… Bergeraklah dengan hati-hati di sini, jangan benar-benar melangkah ke dalam ilusi, kalau tidak……"
  },
  AvgDialog_4901_Content_1 = {
    Text = "Kemurahan Hati Sang Pedagang"
  },
  AvgDialog_4901_Content_10 = {
    Text = "Kotak hitam yang membungkus film itu terguling ke samping, dan cahaya masuk melalui celah yang terbuka akibat benturan."
  },
  AvgDialog_4901_Content_11 = {
    Text = "Dor sudah mengingatkan secara khusus bahwa film tidak boleh terkena cahaya…… Gawat!"
  },
  AvgDialog_4901_Content_12 = {
    Text = "<Shake:Misi kita kali ini kan menguji kamera yang sudah dimodifikasi oleh Dor!>"
  },
  AvgDialog_4901_Content_13 = {
    Text = "Apa susahnya, tinggal pergi ke department store dan beli film baru."
  },
  AvgDialog_4901_Content_14 = {
    Text = "\"Ash\"{Male=tuan,Female=nyonya} dompetnya tidak akan sekempis dulu kan?\""
  },
  AvgDialog_4901_Content_15 = {
    Text = "Kamu meraba-raba dompetmu yang malang, dalam hati menghitung kapan tunjangan investigasi berikutnya akan cair……"
  },
  AvgDialog_4901_Content_16 = {
    Text = "Kantongnya tidak bolong kan? Bagaimana kalau aku coba \"mendapatkan\" satu gulungan film entah-apa-itu?\""
  },
  AvgDialog_4901_Content_17 = {
    Text = "Tolong, sisakan sedikit martabat untuk hukum."
  },
  AvgDialog_4901_Content_18 = {
    Text = "Ayo kita langsung ke department store."
  },
  AvgDialog_4901_Content_2 = {Text = "Apa?!"},
  AvgDialog_4901_Content_3 = {
    Text = "Tch, merepotkan."
  },
  AvgDialog_4901_Content_4 = {
    Text = "Rotan tidak lagi berlarut-larut dalam pertarungan, ia membalikkan pedangnya dan memukul pingsan Cassia dengan gagang pedang, lalu dengan sigap menyarungkan pedangnya sambil berjalan ke sisi Lily."
  },
  AvgDialog_4901_Content_5 = {
    Text = "Mesin itu terkena dampak pertarungan dan terjatuh di antara reruntuhan properti latar."
  },
  AvgDialog_4901_Content_6 = {
    Text = "Apa? Apa? Mesinnya kenapa? Apakah dia kelelahan?"
  },
  AvgDialog_4901_Content_7 = {
    Text = "Ada sesuatu yang jatuh dari dalamnya, apakah rusak?"
  },
  AvgDialog_4901_Content_8 = {
    Text = "Kamu membantu mesin itu berdiri. Kamera tampaknya tidak mengalami kerusakan lain, hanya ada satu komponen berbentuk roda yang terlepas."
  },
  AvgDialog_4901_Content_9 = {
    Text = "Rusak! Filmnya!"
  },
  AvgDialog_4902_Content_1 = {
    Text = "Ber-berhenti! Jangan lari lagi!"
  },
  AvgDialog_4902_Content_10 = {
    Text = "Kalian keluarga siapa? Jam kunjungan sanatorium sudah lewat dari tadi!"
  },
  AvgDialog_4902_Content_11 = {
    Text = "<Small:Keamanan yang disediakan Yayasan Dexter benar-benar tidak berguna…>\nSudahlah, kalian tidak boleh tinggal di sini, aku akan memanggil keamanan untuk mengantar kalian keluar."
  },
  AvgDialog_4902_Content_12 = {
    Text = "Setelah insiden Cerberus, keluarga Dexter dengan murah hati mendanai Sanatorium Jiwa Rye. Dalam arti tertentu, sanatorium ini sudah menjadi milik pribadi sang Profesor."
  },
  AvgDialog_4902_Content_13 = {
    Text = "Saya murid Lord Dexter"
  },
  AvgDialog_4902_Content_14 = {
    Text = "Saya murid Lord Dexter di Londinium. Dalam perjalanan studi, saya kebetulan melewati Rai dan berharap bisa menginap semalam di sanatorium ini."
  },
  AvgDialog_4902_Content_15 = {
    Text = "Murid Lord Dexter? Datang jauh-jauh dari Londinium?"
  },
  AvgDialog_4902_Content_16 = {
    Text = "Kalaupun kau benar-benar kenalan Lord Dexter, dengan kondisi kami sekarang, mana bisa menampung tamu menginap!\nMerepotkan saja… Sudahlah, biar kuantar kalian menemui penanggung jawab."
  },
  AvgDialog_4902_Content_17 = {
    Text = "Saya Ramona Dexter"
  },
  AvgDialog_4902_Content_18 = {Text = "?!"},
  AvgDialog_4902_Content_19 = {
    Text = "Kau menahan bahu Lily, mengisyaratkannya agar tidak panik."
  },
  AvgDialog_4902_Content_2 = {
    Text = "Pasien lantai tiga bermain perang air di halaman, pasien lantai satu bermain kentang dan kari di dapur, lantai dua meraung-raung—ya ampun!!"
  },
  AvgDialog_4902_Content_20 = {
    Text = "Saya satu-satunya pewaris keluarga Dexter. Melakukan kunjungan inspeksi terhadap properti milik keluarga adalah hak saya yang sah."
  },
  AvgDialog_4902_Content_21 = {
    Text = "…Saya pernah bertemu Nona Dexter di sebuah perjamuan makan malam. Beliau adalah seorang wanita anggun dengan rambut perak yang berkilau."
  },
  AvgDialog_4902_Content_22 = {
    Text = "Kau… Sudahlah, sudahlah.\n<Small:Robert, tenangkan dirimu. Kau sudah melihat cukup banyak orang gila di sini, satu lagi juga tidak masalah.>"
  },
  AvgDialog_4902_Content_23 = {
    Text = [[
Baik untuk kunjungan maupun rawat inap, semuanya harus mendapat persetujuan penanggung jawab.
Biar kuantar kalian menemuinya.]]
  },
  AvgDialog_4902_Content_3 = {
    Text = "Aku berhenti! Aku mau berhenti!!"
  },
  AvgDialog_4902_Content_4 = {
    Text = "Alarm berbunyi keras, lampu merah berkedip-kedip. Sanatorium Jiwa Rye kacau balau dari dalam ke luar, pasien berlarian ke mana-mana sambil bermain, perawat yang kewalahan mengejar mereka di luar."
  },
  AvgDialog_4902_Content_5 = {Text = "……!"},
  AvgDialog_4902_Content_6 = {
    Text = "Sanatorium… Ibu!"
  },
  AvgDialog_4902_Content_7 = {
    Text = "Lily jangan terburu-buru, tenang dulu."
  },
  AvgDialog_4902_Content_8 = {
    Text = "Meskipun para tenaga medis terlihat kewalahan, dari tindakan mereka yang tetap teratur, mereka hanya mengeluh secara lisan tentang kesibukan dan kerumitan pekerjaan."
  },
  AvgDialog_4902_Content_9 = {
    Text = "Permisi, ada apa dengan sanatorium ini?"
  },
  AvgDialog_4903_Content_1 = {
    Text = "Apa yang terjadi dengan makhluk anomali ini?"
  },
  AvgDialog_4903_Content_10 = {
    Text = "Sejak kapan dia menghilang?!"
  },
  AvgDialog_4903_Content_11 = {
    Text = [[
Jangan khawatir, ini adalah rumah Lily, dia tidak akan dalam bahaya.
Mari kita membersihkan makhluk anomali ini sambil mencarinya.]]
  },
  AvgDialog_4903_Content_2 = {
    Text = "Apakah Anda masih ingat prajurit yang dikalahkan oleh Anda dan Nona Rotan?"
  },
  AvgDialog_4903_Content_3 = {
    Text = "Serahkan dia…… kepadaku!"
  },
  AvgDialog_4903_Content_4 = {
    Text = "Shilo… pembebas pertama bangsa Tiro, arwah pembalas dendam."
  },
  AvgDialog_4903_Content_5 = {
    Text = [[
Benar.
Sesuai keinginan Kepala Ozwood, yang terhubung dengan Nona Shilo adalah semua pasien di sanatorium ini.]]
  },
  AvgDialog_4903_Content_6 = {
    Text = "Aktivitasnya di luar menyebabkan anomali di sanatorium, biasanya akan kembali normal setelah fajar……\nMeminta Anda untuk melacak keberadaannya yang tidak diketahui hanya demi kekacauan semalam ini, sungguh terlalu memaksakan."
  },
  AvgDialog_4903_Content_7 = {
    Text = "Ada resonansi lemah di antara Awakened yang berasal dari sumber yang sama, mungkin Lily bisa merasakan keberadaan Shilo. Jika kondisi sanatorium semakin memburuk, pastikan untuk segera menghubungi kami."
  },
  AvgDialog_4903_Content_8 = {
    Text = "Terima kasih atas kebaikan Anda, saya akan melakukannya…… Eh?"
  },
  AvgDialog_4903_Content_9 = {Text = "Lily?"},
  AvgDialog_4904_Content_1 = {
    Text = "El@1……@4…!"
  },
  AvgDialog_4904_Content_2 = {
    Text = "Pasien di tempat tidur mengeluarkan jeritan kesakitan, suku katanya terhapus secara tiba-tiba, seolah-olah dunia ini menolak suaranya untuk terdengar."
  },
  AvgDialog_4904_Content_3 = {
    Text = "Sst, sst… dengarkan suara air laut yang mengalir……"
  },
  AvgDialog_4904_Content_4 = {
    Text = "Nymphia menenangkan pasien dengan suara lembut, aliran air tak kasat mata melilit tubuh pasien, dan tak lama kemudian dia pun terdiam, berbaring tenang dalam pelukan Nymphia."
  },
  AvgDialog_4904_Content_5 = {Text = "Ini…"},
  AvgDialog_4904_Content_6 = {
    Text = "Nymphia memberi isyarat diam kepadamu, lalu menyelimuti pasien dengan rapi sebelum membawamu kembali ke koridor."
  },
  AvgDialog_4904_Content_7 = {
    Text = "Jangan khawatir, itu hanya toksin laut dalam dosis sangat kecil. Tubuh akan memetabolismenya selama tidur."
  },
  AvgDialog_4904_Content_8 = {
    Text = "Mari terus maju, lewati koridor ini. Lily mungkin berada jauh di dalam sanatorium."
  },
  AvgDialog_4904_Content_9 = {
    Text = "Kamu memandang lorong yang familiar namun gelap itu, lalu mengangguk setuju."
  },
  AvgDialog_4905_Content_1 = {
    Text = "Kekuatan Andy Johnson"
  },
  AvgDialog_4905_Content_10 = {
    Text = "Suara langkah ringan terdengar dari sudut set. Rotten mengangkat alisnya ke arah Auretta, dan yang bersangkutan langsung mengerti lalu mengarahkan lampu sorot ke sudut itu."
  },
  AvgDialog_4905_Content_11 = {
    Text = "Cahaya terang membuat mata gadis itu menyipit tanpa sadar. Ia berjalan tanpa alas kaki ke tengah set, beberapa kali nyaris menabrak properti yang ditumpuk sembarangan."
  },
  AvgDialog_4905_Content_12 = {
    Text = "— \"Anjing Neraka\"!"
  },
  AvgDialog_4905_Content_13 = {
    Text = "Ku… auu……"
  },
  AvgDialog_4905_Content_14 = {
    Text = "Cakarnya lebih tajam dari pisau makan mewah di department store, matanya lebih terang dari lampu sorot menara penjara. Tanpa wajah, ia mengintai di sudut-sudut kota, mencari target untuk persembahan jahat…"
  },
  AvgDialog_4905_Content_15 = {
    Text = "Bu… bukan……"
  },
  AvgDialog_4905_Content_16 = {
    Text = "Kumu… bukan begitu……"
  },
  AvgDialog_4905_Content_17 = {
    Text = "Uhuk, uhuk uhuk!"
  },
  AvgDialog_4905_Content_18 = {
    Text = "Singkatnya, dia mencari target untuk persembahan jahat…"
  },
  AvgDialog_4905_Content_19 = {
    Text = "Naskah macam apa ini? Mana mungkin Londinium seberbahaya i… uhuk."
  },
  AvgDialog_4905_Content_2 = {
    Text = "Dahulu kala, sebuah banjir besar melanda kota."
  },
  AvgDialog_4905_Content_20 = {
    Text = "Memang Londinium itu berbahaya, tapi masa ada anjing neraka berkeliaran di jalanan!"
  },
  AvgDialog_4905_Content_21 = {
    Text = "Jenkin, naskah Nona Cassia hanyalah cerita…"
  },
  AvgDialog_4905_Content_22 = {
    Text = "Cerita juga tidak boleh asal tulis, kan? Sudah kubilang, tugas sepenting menulis naskah tidak boleh diserahkan pada orang luar."
  },
  AvgDialog_4905_Content_23 = {
    Text = "Keeper juga sama, bukankah kau sudah banyak dirugikan oleh Nyonya itu? Kenapa masih begitu percaya pada orang yang dia masukkan ke sekolah?"
  },
  AvgDialog_4905_Content_24 = {Text = "Cit cit!"},
  AvgDialog_4905_Content_25 = {
    Text = "Sudah sudah, tenang, semua tenang dulu."
  },
  AvgDialog_4905_Content_26 = {
    Text = "Nyonya Dauphindale sudah membuat kesepakatan dengan petinggi sekolah, Cassia sekarang adalah tamu yang tinggal sementara di Misage."
  },
  AvgDialog_4905_Content_27 = {
    Text = "Apa yang dikatakan tikus kecil itu ada benarnya. Cerita anjing neraka cukup menarik kalau diceritakan apa adanya, lagipula…"
  },
  AvgDialog_4905_Content_28 = {
    Text = "Rotten berkata sambil melirik Lily. Gadis itu masih berdiri di bawah sorotan lampu, kepalanya sedikit tertunduk, membuat ekspresinya tak terlihat jelas."
  },
  AvgDialog_4905_Content_29 = {
    Text = "Setidaknya pertimbangkan perasaan orang yang bersangkutan, Nona Pesulap."
  },
  AvgDialog_4905_Content_3 = {
    Text = "Jalanan terendam, menara-menara runtuh dihantam arus. Dari manusia hingga benda, seluruh kota Londinium mengalami sebuah \"Perombakan Besar\" yang menyeluruh!"
  },
  AvgDialog_4905_Content_30 = {
    Text = "Ugh… uughh!"
  },
  AvgDialog_4905_Content_31 = {
    Text = "Bayangan di tanah bergejolak, kawat-kawat di pinggiran topi tinggi putus satu per satu, membuka celah bercahaya redup, tampak persis seperti seringai seorang penjahat."
  },
  AvgDialog_4905_Content_32 = {
    Text = "Sebuah tongkat dilempar keluar dari celah itu, lalu muncul sebuah tangan, dan akhirnya seorang gadis."
  },
  AvgDialog_4905_Content_33 = {
    Text = "Wajah sang pesulap tampak kesal. Dia bangkit dari lantai, menepuk-nepuk debu dari tubuhnya, lalu memungut topi tingginya dan memakainya kembali."
  },
  AvgDialog_4905_Content_34 = {
    Text = "Kau bicara, dia bicara, kau bicara, dia bicara… <Big:Dasar kalian semua yang tidak punya rasa hormat terhadap seni pertunjukan!>"
  },
  AvgDialog_4905_Content_35 = {
    Text = "Di sudut yang sulit diperhatikan, \"kemarahan\" Cassia membuka ruang superdimensi, dan desakan misterius yang familiar terdengar samar dari kegelapan…"
  },
  AvgDialog_4905_Content_36 = {
    Text = "Keluar sekolah kali ini jelas-jelas hanya untuk menguji penemuan baru Dor… kenapa lagi-lagi berakhir dalam situasi yang mengharuskan kita bertarung."
  },
  AvgDialog_4905_Content_37 = {
    Text = "Bicara lebih banyak pun tak ada gunanya, siapkan diri kalian."
  },
  AvgDialog_4905_Content_4 = {
    Text = "Apa itu \"Perombakan Besar\"?"
  },
  AvgDialog_4905_Content_5 = {
    Text = "Sst, nanti kujelaskan setelah adegan ini selesai diambil."
  },
  AvgDialog_4905_Content_7 = {
    Text = "Setelah banjir surut, gejolak baru muncul di tepi Sungai Isis! Malapetaka kembali menimpa kota yang malang ini!"
  },
  AvgDialog_4905_Content_8 = {
    Text = "Kabut tebal menyelimuti permukaan Sungai Isis, begitu pekat hingga tangan di depan mata pun tak terlihat, langit pun tak tampak!\nDan di dalam kabut tebal itu, sesuatu mengintai, menunggu saat yang tepat untuk menyerang…"
  },
  AvgDialog_4905_Content_9 = {
    Text = "Itulah makhluk dari legenda kuno, \"Echidna sebagai ibu, Typhon sebagai ayah, berkepala tiga, <Yellow:barang siapa yang diburunya tiga kali, jiwanya pasti akan kembali ke alam baka>\" —"
  },
  AvgDialog_4906_Content_1 = {
    Text = "Mencari Cerita"
  },
  AvgDialog_4906_Content_10 = {
    Text = "Cerita seperti apa yang ingin kita sampaikan, apakah Tuan sudah punya gambaran?"
  },
  AvgDialog_4906_Content_11 = {Text = "Ngh..."},
  AvgDialog_4906_Content_12 = {
    Text = "Bengong di sini juga bukan solusi. Ayo kembali ke lokasi acara dulu, sambil jalan kita pikirkan pelan-pelan."
  },
  AvgDialog_4906_Content_2 = {
    Text = "Akhirnya keluar juga, toko itu baunya aneh, hidungku hampir rusak."
  },
  AvgDialog_4906_Content_3 = {Text = "Cit cit!"},
  AvgDialog_4906_Content_4 = {
    Text = "Kalau dia sampai mendengar itu, kita tidak akan bisa pergi dengan mudah hari ini lho."
  },
  AvgDialog_4906_Content_5 = {
    Text = "Kita kan sudah tiga puluh kaki dari toko! Dia tidak punya tiga pasang telinga, mana mungkin bisa mendengar kita bicara."
  },
  AvgDialog_4906_Content_6 = {
    Text = "Kau menimbang-nimbang film di tanganmu, beratnya sama persis dengan kotak yang kalian rusak.\nKau kembali teringat imbalan yang ingin diminta Daphodel……"
  },
  AvgDialog_4906_Content_7 = {
    Text = [[
Sebuah cerita yang menakjubkan, sempurna, dan tanpa penyesalan.
Itulah yang ingin kutukarkan.]]
  },
  AvgDialog_4906_Content_8 = {
    Text = "Kali ini kita tidak bisa memotret sesuka hati, harus membuat rencana dulu."
  },
  AvgDialog_4906_Content_9 = {
    Text = "Rencana~ Rencana untuk bercerita~"
  },
  AvgDialog_4907_Content_1 = {
    Text = "Bagian selanjutnya ini kenapa……"
  },
  AvgDialog_4907_Content_10 = {
    Text = "Lily mengatupkan bibirnya, seperti tikus kecil yang menjaga makanannya, ia menarik kertas itu ke dalam pelukannya. Kau tidak bisa melihat jelas apakah wajahnya menunjukkan rasa malu, takut, atau sedih."
  },
  AvgDialog_4907_Content_11 = {
    Text = "Ma-maaf… tapi begitu aku memikirkan ibu…"
  },
  AvgDialog_4907_Content_12 = {
    Text = "Kau tidak melakukan kesalahan apa pun, lagipula akhir cerita ini…"
  },
  AvgDialog_4907_Content_13 = {
    Text = "Cukup sampai di sini untuk hari ini, toh kita sudah cukup banyak mengambil gambar. Kalau Dor ada keluhan, suruh dia datang menemuiku."
  },
  AvgDialog_4907_Content_14 = {
    Text = "Hee—? Tapi Aureta belum tampil sama sekali!"
  },
  AvgDialog_4907_Content_15 = {
    Text = "Bukankah kau menghabiskan waktu makan camilan bersama Brown di belakang panggung? Kenapa sekarang baru ingin masuk ke kamera?"
  },
  AvgDialog_4907_Content_16 = {
    Text = "Aureta juga ingin difoto untuk lukisan cat minyak!"
  },
  AvgDialog_4907_Content_17 = {
    Text = "Jubahmu ditarik dengan kuat, kau menunduk ke arah kakimu dan melihat Lily dengan mata yang penuh kegelisahan dan rasa bersalah."
  },
  AvgDialog_4907_Content_18 = {
    Text = "Gadis kecil itu tidak ingin mengingat kembali perpisahan paksa dengan ibunya, dan tidak ada seorang pun yang bisa menyalahkannya untuk itu."
  },
  AvgDialog_4907_Content_19 = {
    Text = "Tapi adakah cara untuk membuatnya melupakan kesedihan ini? Meskipun hanya untuk sementara…"
  },
  AvgDialog_4907_Content_2 = {Text = "Cut! Cut!"},
  AvgDialog_4907_Content_20 = {
    Text = "Sebelumnya hanya ada kerangka cerita saja sudah cukup parah, tapi berkat kemampuan desain luar biasa dari Pesulap Agung, dia masih bisa menangani omong kosong kalian."
  },
  AvgDialog_4907_Content_21 = {
    Text = "<Yellow:Omong kosong>…"
  },
  AvgDialog_4907_Content_3 = {
    Text = "Untuk pertama kalinya, Kassia menghentikan pengambilan gambar. Ilusi Sihir memudar dan menghilang, naskah dikibaskannya dengan penuh amarah."
  },
  AvgDialog_4907_Content_4 = {
    Text = "Kenapa tiba-tiba berhenti? Kali ini jangan salahkan aku, aku dan Brown sama sekali tidak bersuara!"
  },
  AvgDialog_4907_Content_5 = {
    Text = "Sebelumnya hanya ada kerangka cerita saja sudah cukup parah, tapi berkat kemampuan desain luar biasa dari Pesulap Agung, dia masih bisa menangani omong kosong kalian."
  },
  AvgDialog_4907_Content_6 = {
    Text = "Tapi lihat naskah babak keempat ini, bahkan tidak bisa disebut kerangka cerita, bagaimana mungkin Nona Cassia bisa menyusunnya dari sini!"
  },
  AvgDialog_4907_Content_7 = {
    Text = "Cassia melemparkan naskah ke arahmu, lembaran-lembaran yang tidak terikat dengan baik pun terlepas dari binder."
  },
  AvgDialog_4907_Content_8 = {
    Text = "Selembar kertas yang hampir kosong jatuh di dekat kaki semua orang, di atasnya hanya tertulis dengan tulisan tangan kekanak-kanakan yang tidak rapi:"
  },
  AvgDialog_4907_Content_9 = {
    Text = "\"Gadis itu pun hidup bahagia bersama ibunya selamanya\""
  },
  AvgDialog_49091_Content_1 = {Text = "Taisses…"},
  AvgDialog_49091_Content_10 = {
    Text = "Dia mengangkat tangannya, galaksi raksasa terbelah menjadi dua oleh lengannya yang halus dan licin, namun aliran bintang itu melampaui halangannya, terus mengalir tanpa henti."
  },
  AvgDialog_49091_Content_11 = {
    Text = "Juga teringat padamu, teringat kegembiraan yang berdenyut dan getaran sesaat."
  },
  AvgDialog_49091_Content_12 = {
    Text = "Sebuah meteor meluncur jatuh dengan ekor panjang di belakangnya."
  },
  AvgDialog_49091_Content_13 = {
    Text = "Ayo, lanjutkan…"
  },
  AvgDialog_49091_Content_14 = {
    Text = "Jelajahi aku, selami aku, hingga mencapai alam kenikmatan itu…"
  },
  AvgDialog_49091_Content_15 = {
    Text = "Kobaran apinya bagai rayap yang berkerumun, menggerogoti akal sehatmu perlahan-lahan."
  },
  AvgDialog_49091_Content_16 = {
    Text = "Pengaruh banjir Sungai Suci terlalu dahsyat, aku tidak ingin dan tidak seharusnya melakukan ini sekarang…"
  },
  AvgDialog_49091_Content_17 = {
    Text = "Kamu ternyata mengkhawatirkan hal itu? Benar-benar anak yang penurut, ya."
  },
  AvgDialog_49091_Content_18 = {
    Text = "Tawa ringannya membawa pesona yang membuat hati gatal, melubangi perahu pikiran tersembunyi yang tak pernah kauungkapkan."
  },
  AvgDialog_49091_Content_19 = {
    Text = "Kekuatan Sungai Suci adalah kekuatanku sendiri, aku tidak pernah tergoda olehnya."
  },
  AvgDialog_49091_Content_2 = {
    Text = "Taisses bangkit dari tubuhmu dengan enggan, benang-benang kristal terbentang tipis di antara bibir kalian, menjadi bukti dari semua yang baru saja terjadi."
  },
  AvgDialog_49091_Content_20 = {
    Text = "Semua pilihan yang kubuat didasarkan pada hasratku sendiri."
  },
  AvgDialog_49091_Content_21 = {
    Text = "Air sungai itu merembes masuk dari lubang di lambung kapal, perlahan menenggelamkan ujung kakimu, lututmu, dadamu, lehermu, mulut dan hidungmu…"
  },
  AvgDialog_49091_Content_22 = {
    Text = "Sekarang, giliranmu untuk menjawab… Maukah kau tenggelam dalam lautan hasratku yang tak bertepi?"
  },
  AvgDialog_49091_Content_23 = {
    Text = "Pertanyaan itu mendarat, namun tanpa menunggu jawabanmu, bibir hangat telah membungkam jalan keluarnya kata-kata."
  },
  AvgDialog_49091_Content_24 = {
    Text = "Di saat seperti ini, kata-kata terlalu pucat."
  },
  AvgDialog_49091_Content_25 = {
    Text = "Gunakan tubuhmu… untuk menjawabku."
  },
  AvgDialog_49091_Content_3 = {
    Text = "Tatapannya sayu dan bergejolak, menyapu setiap inci tubuhmu dari ujung rambut hingga ujung kaki."
  },
  AvgDialog_49091_Content_4 = {
    Text = "Jari-jarinya yang bertautan dengan jarimu semakin erat, seolah takut kamu akan melarikan diri, mengurungmu dalam kedalaman yang dipenuhi kehangatan dan gairah."
  },
  AvgDialog_49091_Content_5 = {
    Text = "Lautan pasir putih yang membentang luas di depan mata berpadu dengan gemerlap bintang yang memenuhi pandangan, memukau dan memesona."
  },
  AvgDialog_49091_Content_6 = {
    Text = "Lautan bintang ini mengingatkanmu pada apa?"
  },
  AvgDialog_49091_Content_7 = {
    Text = "Kamu tidak bisa mengingat apa pun. Di dalam lautan memori yang bagai pecahan kaca, hanya ada kilauan bintang yang terpantul di pupil mata Taisses."
  },
  AvgDialog_49091_Content_8 = {
    Text = "Aku akan teringat Yalan."
  },
  AvgDialog_49091_Content_9 = {
    Text = "Teringat benih-benih kehidupan yang menyatu menjadi sungai besar, lalu mengalir deras menuju setiap pembuluh kapiler gurun pasir."
  },
  AvgDialog_49092_Content_1 = {
    Text = "Sehelai kain hitam diangkat dari kepalamu. Kamu mengucek-ucek matamu."
  },
  AvgDialog_49092_Content_10 = {
    Text = "Selanjutnya, silakan nikmati pertunjukan sulap dari Cassia, \"Malam yang Tak Bisa Dilupakan oleh Penjaga Rahasia\"……"
  },
  AvgDialog_49092_Content_11 = {
    Text = "Sepasang mata nakal berkedip-kedip di hadapanmu. Seolah ada satu momen, kau melihat wajah pesulap besar yang selalu tanpa beban ini memerah untuk pertama kalinya."
  },
  AvgDialog_49092_Content_12 = {
    Text = "A-apa……?"
  },
  AvgDialog_49092_Content_13 = {
    Text = "Sebelum kau sempat bereaksi, selembar kain hitam kembali menutupi kalian berdua. Di bawah cahaya bintang yang redup, tubuh yang hangat dan lembut bersandar di pelukanmu."
  },
  AvgDialog_49092_Content_14 = {
    Text = "Hei…… Cassia, tunggu dulu……"
  },
  AvgDialog_49092_Content_15 = {
    Text = "Sst, Penjaga Rahasia. Pertunjukan sulap, sudah dimulai……"
  },
  AvgDialog_49092_Content_16 = {
    Text = "Kau ingin mengatakan sesuatu lagi, tapi sesuatu yang lembut dan dingin membungkam mulutmu."
  },
  AvgDialog_49092_Content_17 = {
    Text = "Kau memejamkan mata. Tidak ada panggung, tidak ada penonton. Di dimensi ruang yang lain, hanya ada bintang-bintang, hanya ada kalian."
  },
  AvgDialog_49092_Content_18 = {
    Text = "Dalam ingatanmu, itu adalah pertunjukan sulap paling sukses yang pernah Cassia lakukan."
  },
  AvgDialog_49092_Content_2 = {
    Text = "Ini… di mana?"
  },
  AvgDialog_49092_Content_3 = {
    Text = "Tentu saja di dimensi ruang yang lain~ Penjaga Rahasia, tidak mengenali tempat ini lagi?"
  },
  AvgDialog_49092_Content_4 = {
    Text = "Hei, Kassia, aku setuju membantumu menampilkan trik teleportasi manusia, tapi bukan berarti kau boleh memindahkanku ke sini."
  },
  AvgDialog_49092_Content_5 = {
    Text = "Sebaiknya kita segera kembali dan melanjutkan pertunjukan ini, mengurangi pengaruh Sungai Suci terhadapmu…"
  },
  AvgDialog_49092_Content_6 = {
    Text = "Bukankah pertunjukannya sedang berlanjut? Kamu sudah setuju untuk membantuku menampilkan sulap, sekarang tidak boleh menarik kata-katamu, lho."
  },
  AvgDialog_49092_Content_7 = {
    Text = "Tapi para penonton masih menunggu di sana……"
  },
  AvgDialog_49092_Content_8 = {
    Text = "Pertunjukan sulap untuk penonton sudah berakhir. Pertunjukan kali ini, adalah persembahan untuk Sang Penjaga Rahasia."
  },
  AvgDialog_49092_Content_9 = {
    Text = "Cassia menyembunyikan kedua tangan di belakang punggung, kepalanya sedikit miring, lalu melompat ke hadapanmu."
  },
  AvgDialog_49093_Content_10 = {
    Text = "Cukup ditiup saja kan?"
  },
  AvgDialog_49093_Content_11 = {
    Text = "Huu————"
  },
  AvgDialog_49093_Content_12 = {Text = "Bagaimana?"},
  AvgDialog_49093_Content_13 = {
    Text = "Sudah tidak sakit, debunya seharusnya sudah tertiup. Ayo kita lanjutkan."
  },
  AvgDialog_49093_Content_14 = {
    Text = "Tidak, hari ini cukup sampai di sini."
  },
  AvgDialog_49093_Content_15 = {
    Text = "Menghentikan latihan tempur sebelum kau puas? Ini tidak seperti gayamu yang biasanya……"
  },
  AvgDialog_49093_Content_16 = {
    Text = "Hah…… Berkat Tolemwahi, kau yang sekarang tidak bisa membuatku \"puas\"."
  },
  AvgDialog_49093_Content_17 = {
    Text = "Anak rambut di dahi tersibak, jiwa yang berat mendaratkan sebuah ciuman angkuh di sudut dahi."
  },
  AvgDialog_49093_Content_18 = {Text = "Rotan?!"},
  AvgDialog_49093_Content_19 = {
    Text = "Rotan menepuk-nepuk wajahmu, menarik tanganmu dan mengangkatmu dari lantai yang keras dan dingin."
  },
  AvgDialog_49093_Content_2 = {
    Text = "Belum cukup, masih belum cukup!"
  },
  AvgDialog_49093_Content_20 = {
    Text = [[
Selama akal sehatku masih ada, hasrat-hasrat kacau itu tidak bisa mengendalikanku.
Jangan lupa, aku adalah ciptaan purba.]]
  },
  AvgDialog_49093_Content_21 = {
    Text = "Sekarang, kembalilah. Anak kecil."
  },
  AvgDialog_49093_Content_3 = {
    Text = "Inikah kemampuanmu? Satu tahun pelatihan, ditambah beberapa kali penempaan dari misi……"
  },
  AvgDialog_49093_Content_4 = {
    Text = "Serangan menghujam bagai hujan badai, ubin arena latihan hancur berkeping-keping tanpa ampun."
  },
  AvgDialog_49093_Content_5 = {
    Text = "Debu yang beterbangan masuk ke matamu, sensasi benda asing membuatmu tak bisa menahan diri untuk memejamkan mata."
  },
  AvgDialog_49093_Content_6 = {
    Text = "Rotan! Berhenti sebentar, aku——"
  },
  AvgDialog_49093_Content_7 = {
    Text = "Sang petarung dengan paksa membuka kelopak matamu atas dan bawah, serat kain sarung tangannya bergesekan di kulit yang sensitif dan rapuh, membuatmu tak bisa menahan diri untuk terus berkedip."
  },
  AvgDialog_49093_Content_8 = {
    Text = "Jangan bergerak."
  },
  AvgDialog_49093_Content_9 = {
    Text = "Rotan langsung meletakkan senjatanya, satu tangan menahan kepalamu, membuatmu tak bisa mundur menghindar mengikuti insting."
  },
  AvgDialog_49094_Content_1 = {
    Text = "Mur, batang besi…… Benar, sama seperti memperbaiki rangka motor."
  },
  AvgDialog_49094_Content_2 = {
    Text = "Eh? Tidak ada yang rusak, kenapa orang itu menyuruhku datang ke bangsal? Bukankah yang rusak seharusnya tempat tidur ini?"
  },
  AvgDialog_49094_Content_3 = {
    Text = "Gadis itu mengangkat kepalanya dengan bingung, tangan penuh noda oli menunjukkan bahwa dia sudah menyelesaikan inspeksi menyeluruh bangsal dengan sempurna."
  },
  AvgDialog_49094_Content_4 = {
    Text = "Snif… snif snif……"
  },
  AvgDialog_49094_Content_5 = {
    Text = "Orang ini memiliki bauku di tubuhnya……"
  },
  AvgDialog_49094_Content_6 = {
    Text = "Nodira membungkuk memandangi murid yang tertidur lelap di ranjang rumah sakit, tenggelam dalam pemikiran."
  },
  AvgDialog_49094_Content_7 = {
    Text = "Di sudut bibir dan wajah %hisorher% masing-masing terdapat noda hitam yang jelas, Nodira langsung mengenali bahwa itu adalah bekas oli mesin racikan khususnya."
  },
  AvgDialog_49094_Content_8 = {
    Text = "Hmm…… Aku pasti mengenal {Male=dia,Female=dia}, %hisorher%namanya adalah……"
  },
  AvgDialog_49094_Content_9 = {
    Text = "%player%……Benar, %player%."
  },
  AvgDialog_49095_Content_1 = {
    Text = "Kau jatuh semakin dalam ke kedalaman mimpi."
  },
  AvgDialog_49095_Content_10 = {
    Text = "Berhenti bernapas, Aku akan membawamu kembali ke kenyataan."
  },
  AvgDialog_49095_Content_11 = {
    Text = "Tulu?! Uhuk, uhuk…"
  },
  AvgDialog_49095_Content_12 = {
    Text = "Kemunculan Awakener membantumu memahami sedikit situasi saat ini. Kau tak sabar memanggil namanya, tetapi ide-ide aneh itu seketika berubah menjadi gelombang pasang yang menerobos saluran napasmu."
  },
  AvgDialog_49095_Content_13 = {
    Text = "…Aku baru saja bilang, berhenti bernapas."
  },
  AvgDialog_49095_Content_14 = {
    Text = "Sesaat kemudian, tentakel yang penuh dan dingin secara paksa menerobos masuk ke rongga mulut, mendorong ingatan kacau ke samping, mengusir suara-suara yang kini tak bermakna itu."
  },
  AvgDialog_49095_Content_15 = {
    Text = "Angin musim kenyataan berhembus di wajah, tubuh melemas dalam kelelahan yang belum pernah dirasakan sebelumnya, seolah akan segera memasuki tidur nyenyak tanpa mimpi…"
  },
  AvgDialog_49095_Content_16 = {
    Text = "Baru saja lolos dari maut di dalam mimpiku, dan masih berani langsung tertidur? Keberanian ini, sungguh membuatku terkesan."
  },
  AvgDialog_49095_Content_17 = {
    Text = "Tu, Tulu…"
  },
  AvgDialog_49095_Content_18 = {
    Text = "Kau tadi bilang, itu mimpimu?"
  },
  AvgDialog_49095_Content_19 = {
    Text = "Awakener memalingkan wajahnya dengan sedikit malu."
  },
  AvgDialog_49095_Content_2 = {
    Text = "Banjir secara tiba-tiba menghancurkan tiang-tiang mimpi, perbatasan antara mimpi dan kenyataan dipenuhi jeritan, lalu berubah menjadi batu-batu gelap basah yang tak terhitung jumlahnya."
  },
  AvgDialog_49095_Content_20 = {
    Text = "\"Saat daku tertidur, mimpi yang meluap akan memicu gejolak roh\"……Ketidaknormalan tubuh daku telah menyeretmu ke dalam mimpi, ini adalah kesalahan daku."
  },
  AvgDialog_49095_Content_21 = {
    Text = "Keanehan ini membuat mimpi daku tanpa sadar menyusup ke dalam mimpimu……Jika kau merasa keberatan karenanya, daku sepenuhnya bisa memahami perasaanmu."
  },
  AvgDialog_49095_Content_22 = {
    Text = "Ke-keberatan? Mana mungkin, kau tidak sengaja melakukannya. Lagipula, saat aku hampir tenggelam oleh suara Lemuria, bukankah kau datang tepat waktu?"
  },
  AvgDialog_49095_Content_23 = {Text = "Kau……"},
  AvgDialog_49095_Content_24 = {
    Text = "Setelah kembali ke sekolah, daku akan segera pergi ke Black Pool. Mungkin lingkungan di sana bisa sementara menekan……ketidaknormalan dalam tubuh daku."
  },
  AvgDialog_49095_Content_25 = {
    Text = "Dia dengan penuh pengendalian diri merapatkan tentakelnya ke sudut kabin, melirik ke arah kegelapan malam yang pekat di luar jendela."
  },
  AvgDialog_49095_Content_26 = {
    Text = "Namun lirikan yang berulang kali jatuh ke sudut bibirmu, tampaknya bukan tanpa maksud."
  },
  AvgDialog_49095_Content_3 = {
    Text = "Ini bukan mimpiku… Ini bukan milikku…"
  },
  AvgDialog_49095_Content_4 = {
    Text = "Kau bergumam ingin terbangun. Alveolus paru-parumu yang penuh air mengembang seperti perut pasien stadium akhir, tubuhmu sedang beradaptasi dengan lautan yang telah terlupakan."
  },
  AvgDialog_49095_Content_5 = {
    Text = "Namun arus air yang seharusnya tak terdengar menarik kepalamu untuk menoleh ke belakang."
  },
  AvgDialog_49095_Content_6 = {
    Text = "Musik, lukisan, cerita yang ditulis dalam aksara tak dikenal, tak terhitung ide-ide aneh membanjiri mimpimu di saat kau menoleh."
  },
  AvgDialog_49095_Content_7 = {
    Text = "Kau ingin membuka mulut, namun hanya bisa mengeluarkan suku kata acak tak bermakna—tetapi sebenarnya mereka memang bermakna."
  },
  AvgDialog_49095_Content_8 = {
    Text = "Mereka memang bermakna, di masa yang sangat lampau, mereka pernah menjadi—"
  },
  AvgDialog_49095_Content_9 = {
    Text = "Jangan terus menelan air di sini."
  },
  AvgDialog_49261_Content_1 = {
    Text = "Kepalaku sakit sekali…apa yang terjadi padaku……"
  },
  AvgDialog_49261_Content_10 = {
    Text = "<Small:Hiks……sudah kuduga, diriku yang seperti ini hanyalah tikus got di balik kemeja hitam yang tak dipedulikan siapa pun, embun di hari cerah yang akan menghilang……>"
  },
  AvgDialog_49261_Content_11 = {
    Text = "Nona Mason, Nona Mason!"
  },
  AvgDialog_49261_Content_12 = {
    Text = "Kau memegang bahunya dan mengguncangnya, mencoba menariknya keluar dari keraguan diri yang tak berujung."
  },
  AvgDialog_49261_Content_13 = {
    Text = "Tidak ada yang akan menolak menerimamu, kau adalah bagian dari kami."
  },
  AvgDialog_49261_Content_14 = {
    Text = "Tidak ada yang akan menolak menerimaku……"
  },
  AvgDialog_49261_Content_15 = {
    Text = "Dia mendongak menatapmu dengan tiba-tiba, sudut bibirnya tertarik membentuk lengkungan yang menyeramkan."
  },
  AvgDialog_49261_Content_16 = {
    Text = "Tepat sekali, jadilah bagian dariku, mari kita birth \"24\" yang baru!"
  },
  AvgDialog_49261_Content_17 = {
    Text = "Bahunya terbelah oleh retakan yang mengerikan, namun di dalamnya tidak ada otot maupun tulang. Gumpalan abu-abu pucat bergetar dan mengembang di bawah kulit, bagaikan sebuah alam semesta yang sedang terlahir."
  },
  AvgDialog_49261_Content_18 = {
    Text = "Lendir berkedut merangkak keluar dari retakan itu, melilit di sela-sela jarimu. Sensasi lembap dan licin itu seketika menarikmu kembali ke momen saat kau terbangun dari tidur panjang."
  },
  AvgDialog_49261_Content_19 = {
    Text = "\"24\" pupil matanya menyebar, dia mendambakanmu, mendambakan untuk menampungmu, menjadi bagian dari titik akhir."
  },
  AvgDialog_49261_Content_2 = {
    Text = "Di bawahmu adalah ranjang empuk yang sudah sangat kau kenal, dan rasa sakit yang tak asing lagi menjalar dari belakang kepalamu."
  },
  AvgDialog_49261_Content_20 = {
    Text = "Tidak peduli kau kepribadian baru Mason yang mana……sadarlah!"
  },
  AvgDialog_49261_Content_21 = {
    Text = "Kau berusaha meraih kunci perak yang tergantung di dada, tapi tanganmu baru bergerak sedikit sebelum dicengkeram oleh kekuatan luar biasa yang tak bisa dilawan."
  },
  AvgDialog_49261_Content_22 = {
    Text = "Kenapa harus melawan? Bukankah kau bilang akan sepenuhnya menerimaku?\"Orang itu\"begitu menyayangimu, dia pasti juga sangat mendambakan……"
  },
  AvgDialog_49261_Content_23 = {
    Text = "Saat bibir dingin itu menempel di sudut mulutmu, kau menyadari matanya telah sepenuhnya digerogoti kegilaan — dia bukan\"Mason\"yang kau kenal."
  },
  AvgDialog_49261_Content_24 = {Text = "Ugh!"},
  AvgDialog_49261_Content_25 = {
    Text = "\"24\" seluruh tubuhnya gemetar, tenggorokannya mengeluarkan napas terengah-engah seperti bellow yang rusak. Dia melepaskan belenggunya padamu, dan mulai mencakar lehernya yang ramping."
  },
  AvgDialog_49261_Content_26 = {
    Text = "Kenapa! Kenapa kau yang mengambil kendali——"
  },
  AvgDialog_49261_Content_27 = {
    Text = "Tidak, jangan, jangan jangan jangan jangan jangan jangan tidak tidak tidak tidak——"
  },
  AvgDialog_49261_Content_28 = {
    Text = "\"24\" mengeluarkan jeritan, keempat anggota tubuhnya terlipat balik lalu terkulai lemas di bahunya sendiri, akhirnya dia menundukkan kepala, kembali tenang."
  },
  AvgDialog_49261_Content_29 = {
    Text = "Ma-Mason? Apakah itu kau?"
  },
  AvgDialog_49261_Content_3 = {
    Text = "Kau menopang tubuhmu dengan kedua tangan di atas kasur, mencoba bangun, tetapi malah tenggelam ke dalam gumpalan jaringan yang lembap dan licin."
  },
  AvgDialog_49261_Content_30 = {
    Text = "Keeper! Sungguh, sungguh maafkan aku……Entah kenapa, kepribadian baru yang tiba-tiba muncul dalam diriku menyimpan perasaan abnormal terhadap Anda……"
  },
  AvgDialog_49261_Content_31 = {
    Text = "Mason dengan panik mengibas-ngibaskan kedua lengannya yang sepenuhnya terlepas dari sendi, tampak persis seperti dua potong adonan yang tergantung di bahu."
  },
  AvgDialog_49261_Content_32 = {
    Text = "Tidak perlu minta maaf padaku, kau hanya terpengaruh oleh Sungai Suci."
  },
  AvgDialog_49261_Content_33 = {
    Text = "Kau menopang tangannya — tangan bagian manusianya, dengan hati-hati membimbing sendi yang bergeser kembali ke posisi semula."
  },
  AvgDialog_49261_Content_34 = {
    Text = "Maaf merepotkanmu……"
  },
  AvgDialog_49261_Content_35 = {
    Text = "Suaranya nyaris tak terdengar, namun dalam nada bicaranya, sekilas tersirat kegembiraan yang melintas sesaat."
  },
  AvgDialog_49261_Content_4 = {
    Text = "Penjaga Rahasia, Penjaga Rahasia……"
  },
  AvgDialog_49261_Content_5 = {
    Text = "Melihatmu terbangun, wanita muda itu menunjukkan wajah penuh malu, mengeluarkan suara manja yang belum pernah kau dengar darinya."
  },
  AvgDialog_49261_Content_6 = {
    Text = "Me-Nona Mason?!"
  },
  AvgDialog_49261_Content_7 = {
    Text = "\"Mason\" berbaring miring di sisi lain tempat tidur, ujung jarinya yang menghitam menekan dadamu. Kedua tangannya yang tampak tak bertenaga, ternyata menahanmu dengan kuat di atas ranjang."
  },
  AvgDialog_49261_Content_8 = {
    Text = "Jangan pergi……kenapa harus pergi?"
  },
  AvgDialog_49261_Content_9 = {
    Text = "Atau mungkin, semua kata-kata manis dari \"24\" yang kuterima hanyalah halusinasi akibat kegilaanku?"
  },
  AvgDialog_49398_Content_1 = {
    Text = "Badai semakin ganas, tentara Aran menangis tersedu-sedu, kalap, berteriak keras, memohon, dan mengutuk."
  },
  AvgDialog_49398_Content_10 = {
    Text = "Banyak orang Aram menghadap ke arah Thais dengan khidmat, lalu berlutut penuh kesungguhan."
  },
  AvgDialog_49398_Content_11 = {
    Text = "Makhluk pasir yang gelisah perlahan mereda amarahnya di bawah pengaruh doa, dan badai pun mulai mereda."
  },
  AvgDialog_49398_Content_12 = {
    Text = "Ini Ratu! Ini Ratu!"
  },
  AvgDialog_49398_Content_13 = {
    Text = "Terima kasih atas perlindungan Ratu!"
  },
  AvgDialog_49398_Content_14 = {
    Text = "Mata sang ratu masih mengamati kita!"
  },
  AvgDialog_49398_Content_15 = {
    Text = "Kami… tiba!"
  },
  AvgDialog_49398_Content_2 = {
    Text = "Tidak jauh dari bukit pasir tersebut, kamu melihat sosok itu."
  },
  AvgDialog_49398_Content_3 = {
    Text = "Dari siluetnya, kamu mengenali bahwa itu Thais."
  },
  AvgDialog_49398_Content_4 = {
    Text = "Badai... apakah sudah mereda?"
  },
  AvgDialog_49398_Content_5 = {
    Text = "Dia melantunkan doa yang tak dikenal, membiarkan angin kencang menyeret jubah sutranya, melangkah perlahan namun mantap ke dalam badai pasir yang pekat."
  },
  AvgDialog_49398_Content_6 = {
    Text = "Dentuman terdengar memekakkan telinga, namun suara doa tetap terdengar dengan jelas, seolah-olah bergema di bagian dalam tengkorakmu."
  },
  AvgDialog_49398_Content_7 = {
    Text = "Di tengah badai yang menelan langit dan bumi, dia tampak seperti sedang berbicara dengan tenang kepada suatu makhluk hidup yang tinggal di gurun."
  },
  AvgDialog_49398_Content_8 = {
    Text = "Itu Ratu! Ratu datang untuk menyelamatkan kita, menyelamatkan Aran!"
  },
  AvgDialog_49398_Content_9 = {
    Text = "Tim Aran yang semula bersiap untuk melarikan diri tiba-tiba berhenti."
  },
  AvgDialog_49399_Content_1 = {
    Text = "Dinding badai"
  },
  AvgDialog_49399_Content_10 = {
    Text = "Itu, itu datang——!"
  },
  AvgDialog_49399_Content_11 = {
    Text = "Pada saat pandanganmu terfokus, kau memahami apa yang disebut \"Dinding badai\"."
  },
  AvgDialog_49399_Content_12 = {
    Text = "Itu adalah tirai abu-abu raksasa yang menelan langit dan bumi, bergulung mendekat dalam bentuk yang menutupi langit."
  },
  AvgDialog_49399_Content_13 = {
    Text = "Seharusnya itu seperti pasang surut, tetapi bukan pasang surut. Ia begitu besar dan sunyi, bergerak maju namun seolah-olah diam."
  },
  AvgDialog_49399_Content_14 = {
    Text = "Perbatasannya seperti binatang raksasa yang menjilat bumi, dan barisan Aran pun tertelan ke dalam Kabut, ditarik serta dicerna oleh perut badai."
  },
  AvgDialog_49399_Content_15 = {
    Text = "Terus melompat, jangan berhenti!"
  },
  AvgDialog_49399_Content_16 = {
    Text = "Utusan dari negeri asing telah tiba, Ratu akan membuka jalan bagi kita menuju Pohon Ibu!"
  },
  AvgDialog_49399_Content_17 = {
    Text = "Kamu memperhatikan Juliette di sebelahmu tersenyum tipis."
  },
  AvgDialog_49399_Content_18 = {
    Text = "Kepala Suku, Kepala Suku, badai hari ini terlalu hebat! Kami benar-benar tidak bisa kehilangan begitu banyak orang. Mari kita mundur dulu!"
  },
  AvgDialog_49399_Content_19 = {
    Text = "Tidak boleh!"
  },
  AvgDialog_49399_Content_2 = {
    Text = "Alva mengangkat bendera tinggi-tinggi, mereka serempak menyapukan tombak mereka melintasi padang pasir yang tandus, menimbulkan debu pasir yang membutakan mata, sambil melantunkan nyanyian yang aneh dan mistis."
  },
  AvgDialog_49399_Content_20 = {
    Text = "Nada suaranya penuh wibawa, namun kalimatnya bergetar karena suara angin."
  },
  AvgDialog_49399_Content_21 = {
    Text = "Tingkat kelainan dalam ritual api unggun semakin tinggi. Jika terus berlanjut seperti ini, sebelum menemukan Pohon Ibu, garis keturunan Alan akan punah di aliran waktu yang panjang."
  },
  AvgDialog_49399_Content_22 = {
    Text = "Juliette menempelkan dua jarinya membentuk lingkaran, lalu meniupkan peluit yang nyaring. Nada panjang itu dibawa oleh badai, mengalun menuju kejauhan yang tak terjangkau."
  },
  AvgDialog_49399_Content_23 = {
    Text = "Saya adalah utusan Juliette, saya telah mendengar titah Ratu. Hari ini, kita pasti bisa menembus Dinding Badai!"
  },
  AvgDialog_49399_Content_24 = {
    Text = "Semua orang, hanya maju, tidak boleh mundur!"
  },
  AvgDialog_49399_Content_25 = {
    Text = "Patuh pada perintah Tuan Utusan, hanya maju, tidak boleh mundur!"
  },
  AvgDialog_49399_Content_26 = {
    Text = "<Small:Ya... jalan mundur... memang sama sekali tidak ada...>"
  },
  AvgDialog_49399_Content_27 = {
    Text = "Tunggu, Penjaga, ada segerombolan besar Nubia di belakangmu…\nLihat jumlahnya… setidaknya ada… dua ratus!"
  },
  AvgDialog_49399_Content_28 = {
    Text = "Lihatlah! Ini adalah perintah Ratu! Kalian hanya bisa maju!"
  },
  AvgDialog_49399_Content_29 = {
    Text = "Nubia mengaum dan berlari ke arah kalian dengan ganas."
  },
  AvgDialog_49399_Content_3 = {
    Text = "Kematian sudah mendekat, kehancuran telah dimulai."
  },
  AvgDialog_49399_Content_4 = {
    Text = "Kerangka ibu tidak terlihat, darah dan benih hanyut di bumi, dilahap oleh binatang liar yang baru lahir."
  },
  AvgDialog_49399_Content_5 = {
    Text = "Langit dan para dewa dipenuhi awan mendung, hingga Kedatangan utusan dari negeri asing."
  },
  AvgDialog_49399_Content_6 = {
    Text = "Pohon Ibu melahirkan kembali Sungai Suci, memberikan mahkota kepada yang telah tiada, dan mengembalikan garis keturunan kepada Alen."
  },
  AvgDialog_49399_Content_7 = {
    Text = "Kembalikan darah… kepada Aran…"
  },
  AvgDialog_49399_Content_8 = {
    Text = "Entah sejak kapan, matahari terik di padang pasir menghilang, langit menjadi suram, dan suara angin berubah nada."
  },
  AvgDialog_49399_Content_9 = {
    Text = "Rasa takut yang tak terjelaskan menyergapmu, kamu tiba-tiba kehilangan fokus, lalu segera dibangun oleh sebuah teriakan."
  },
  AvgDialog_49400_Content_1 = {
    Text = "Tuan Alva, izinkan saya berbicara beberapa kata dengan {Male=dia,Female=dia}."
  },
  AvgDialog_49400_Content_10 = {
    Text = "Ekspresinya tampak luar biasa bersemangat, kecepatan bicaranya sangat cepat, tubuhnya tanpa sadar condong ke depan, dan matanya seperti hantu."
  },
  AvgDialog_49400_Content_11 = {
    Text = "Selamat tinggal, Mata Buta."
  },
  AvgDialog_49400_Content_13 = {
    Text = "Tidak, ini belum berakhir. Karena orang itu pernah dengan suara paling penuh semangat, meminta kamu untuk memanggil namanya."
  },
  AvgDialog_49400_Content_14 = {
    Text = "Mengingat tatapan Thais, kamu mengaktifkan Kunci perak."
  },
  AvgDialog_49400_Content_15 = {
    Text = "Benang perak bergoyang, menarik, dan mencari..."
  },
  AvgDialog_49400_Content_16 = {
    Text = "Di ujung benang itu, tidak ada apa pun."
  },
  AvgDialog_49400_Content_17 = {
    Text = "Fenomena yang disebut Pelarutan sepenuhnya menelan dirinya, bahkan kamu tidak dapat menemukan jejaknya."
  },
  AvgDialog_49400_Content_18 = {
    Text = "Apakah kau masih berharap dia akan kembali? Orang-orang Aram sudah tunduk padaku."
  },
  AvgDialog_49400_Content_19 = {
    Text = "Thais… Thais!"
  },
  AvgDialog_49400_Content_2 = {
    Text = "Saat kamu dan Alva saling berhadapan tanpa ada yang mengalah, Juliette bersuara untuk menghentikan kalian."
  },
  AvgDialog_49400_Content_20 = {
    Text = "Jika dia bisa muncul, jika dia bisa dengan kekuatan ilahi-Nya, menunjukkan masa depan bangsa Aran kepada Alva."
  },
  AvgDialog_49400_Content_21 = {
    Text = "Bahkan jika hanya mengeluarkan suara untuk membela diri, kamu tidak perlu berada di sini, berhadapan dengan pedang Alva."
  },
  AvgDialog_49400_Content_22 = {
    Text = "Thais… Thais—!"
  },
  AvgDialog_49400_Content_23 = {
    Text = "Tidak peduli seberapa sering kamu memanggil, itu tidak akan membantu. Percakapan terakhirmu dengannya berakhir pada tuduhan yang kamu lontarkan kepadanya."
  },
  AvgDialog_49400_Content_24 = {
    Text = "Keberadaan yang telah lenyap akibat pelarutan, tanpa jejak kontak dari Perak, mustahil bagi Anda untuk menyentuh sedikit pun keberadaannya."
  },
  AvgDialog_49400_Content_26 = {
    Text = "Apa, perjalanan sebelumnya membuatmu terlalu sombong?"
  },
  AvgDialog_49400_Content_27 = {
    Text = "Atau setelah meninggalkanku, apakah kamu menjadi orang yang menangis tersedu-sedu dan tak berguna?"
  },
  AvgDialog_49400_Content_28 = {
    Text = "Ketenangan gurun dilanggar oleh suara angin yang mendesak, langit dengan cepat menjadi gelap, seolah-olah semua warna terang telah dilahap oleh amukan badai yang akan datang."
  },
  AvgDialog_49400_Content_29 = {
    Text = "Badai pasir bagaikan binatang raksasa yang marah, meraung dan menyapu dengan kekuatan penuh, mengangkat jutaan ton pasir halus, menutupi langit dan matahari, membuat panas terik serta birunya langit lenyap sepenuhnya."
  },
  AvgDialog_49400_Content_3 = {
    Text = "Karena kamu memaksa seperti ini."
  },
  AvgDialog_49400_Content_30 = {
    Text = "Di tengah keganasan kekuatan alam ini, sebuah sosok raksasa tampak samar-samar, berkilauan tak menentu di antara debu pasir."
  },
  AvgDialog_49400_Content_31 = {
    Text = "Dinding Badai…"
  },
  AvgDialog_49400_Content_32 = {
    Text = "Dinding Badai adalah sesuatu yang pada awalnya kupanggil menggunakan kekuasaanku."
  },
  AvgDialog_49400_Content_33 = {
    Text = "Apakah kamu... Thais...?"
  },
  AvgDialog_49400_Content_34 = {
    Text = "Sepertinya ia memiliki kekuatan tanpa batas. Seiring dengan tarian gila pasir, bayangannya melompat dan berkelok, seperti seekor monster gurun kuno yang sedang mencari mangsa di tengah badai debu."
  },
  AvgDialog_49400_Content_35 = {
    Text = "Bentuknya sangat besar dan menakutkan, kepala yang besar dan berkelok, cakar serta taring yang tajam, dan empat kaki yang berat, semuanya samar-samar terlihat di tengah debu yang beterbangan."
  },
  AvgDialog_49400_Content_36 = {
    Text = "Memanggilnya seperti itu juga tidak bisa dianggap salah."
  },
  AvgDialog_49400_Content_37 = {
    Text = "Namun, aku bukanlah ratu yang kau harapkan."
  },
  AvgDialog_49400_Content_38 = {
    Text = "Jika kamu ingin meminjam kekuatanku, bacalah dengan lantang nama suciku ——"
  },
  AvgDialog_49400_Content_39 = {
    Text = "Bayangan besar dan aneh itu perlahan memudar, sosok yang selalu kamu rindukan muncul dari badai pasir yang menderu."
  },
  AvgDialog_49400_Content_4 = {
    Text = "Penjaga, jangan biarkan mereka melukai Tuan Utusan sedikit pun."
  },
  AvgDialog_49400_Content_40 = {
    Text = "Kerikil berderu dan menari liar tanpa ampun di sekitar tubuhnya, namun sedikit pun tidak menggoyahkan langkahnya."
  },
  AvgDialog_49400_Content_42 = {
    Text = "Ratu! Ratu telah kembali!"
  },
  AvgDialog_49400_Content_43 = {
    Text = "Ratu, pandangan Ratu terus tertuju pada kita!"
  },
  AvgDialog_49400_Content_44 = {
    Text = "Matanya terus tertuju pada Alan, menatap masa lalu dan masa depan yang mengalir dalam darahnya."
  },
  AvgDialog_49400_Content_45 = {
    Text = "Thais... Tuan..."
  },
  AvgDialog_49400_Content_46 = {
    Text = "Semua etnis Alan dengarkan baik-baik! Ramalan kuno telah digenapi, Pohon Ibu muncul kembali di dunia, dan kita harus memahkotai mereka yang telah tiada!"
  },
  AvgDialog_49400_Content_47 = {
    Text = "Ratu kembali melangkah di atas pasir, kembali ke Takhta!"
  },
  AvgDialog_49400_Content_48 = {
    Text = "Kepada satu-satunya Ratu Aran, Yang Mulia Thais——"
  },
  AvgDialog_49400_Content_49 = {
    Text = "Persembahkan kesetiaan dan tekad kalian!"
  },
  AvgDialog_49400_Content_5 = {Text = "Baik!"},
  AvgDialog_49400_Content_6 = {
    Text = "Juliette mendekat, berbisik padamu dari jarak satu lengan."
  },
  AvgDialog_49400_Content_7 = {
    Text = "Kembali ke Sungai Suci adalah takdir orang Aram. Aku hanya membantu mempercepat prosesnya sedikit."
  },
  AvgDialog_49400_Content_8 = {
    Text = "Ketika pandangan-Nya meliputi seluruh Kadath, mereka akan menyatu dengan Sungai Suci ke dalam dunia baru."
  },
  AvgDialog_49400_Content_9 = {
    Text = "Bukankah ini sudah menjadi kehendakmu sendiri?"
  },
  AvgDialog_49401_Content_1 = {
    Text = "Cabang-cabang Pohon Ibu seolah memiliki kehendak sendiri, berlomba-lomba menjulur ke segala arah. Kontur Tubuh manusia samar-samar terlihat di dalamnya, dengan gerakan yang kaku dan penuh penderitaan."
  },
  AvgDialog_49401_Content_10 = {
    Text = "Ramona, nyalakan Pohon Ibu dengan Api Chip Perak! Hanya kamu yang bisa melakukannya!"
  },
  AvgDialog_49401_Content_11 = {
    Text = "Fatamorgana perak menghantam akar Pohon Ibu, api perak menyala dalam sekejap, berubah menjadi kobaran api yang disebut Kehancuran."
  },
  AvgDialog_49401_Content_12 = {
    Text = "Lidah api seperti ular perak merambat naik di sepanjang cabang, dedaunan bergoyang dan berteriak dalam amukan api, mengeluarkan suara mendesis yang menusuk telinga, seolah-olah Pohon Ibu sedang merintih dan menangis dalam penderitaan."
  },
  AvgDialog_49401_Content_13 = {
    Text = "Tunggu, pohon akan tumbang, Penjaga belum turun!"
  },
  AvgDialog_49401_Content_14 = {
    Text = "Tenang saja, anak baik. Aku pasti akan mengembalikan {Male=dia,Female=dia} dengan selamat kepada mu."
  },
  AvgDialog_49401_Content_15 = {
    Text = "Pohon raksasa berguncang, langit dan bumi bergetar."
  },
  AvgDialog_49401_Content_16 = {
    Text = "Kamu kehilangan keseimbangan dan terjatuh lurus ke bawah——"
  },
  AvgDialog_49401_Content_17 = {
    Text = "Berapa tinggi di sini? Seribu kaki? Atau lebih?"
  },
  AvgDialog_49401_Content_18 = {
    Text = "Lalu, sebuah pelukan yang hangat dan lembut menyelimutimu."
  },
  AvgDialog_49401_Content_19 = {
    Text = "Anak baik, kamu sudah melakukan dengan sangat baik."
  },
  AvgDialog_49401_Content_2 = {
    Text = "Orang pertama yang berevolusi memiliki tenggorokan mengeluarkan erangan, dengan susah payah melepaskan diri dari ikatan Pohon Ibu, jatuh dari ketinggian ke Sungai Suci."
  },
  AvgDialog_49401_Content_20 = {
    Text = "Di dadanya, giok putih yang kau pasang sendiri bersinar terang, berpadu indah dengan kulitnya yang halus seperti sutra."
  },
  AvgDialog_49401_Content_21 = {
    Text = "Thais mengulurkan tangan untuk memetiknya, memasukkannya ke dalam mulut, lalu perlahan menggigitnya hingga pecah."
  },
  AvgDialog_49401_Content_22 = {
    Text = [[
Aku akan kembali ke Sungai Suci, memberi makan seluruh bumi.
Ini adalah hadiah perpisahan untukmu.]]
  },
  AvgDialog_49401_Content_23 = {
    Text = "Pada saat jatuh ke Sungai Suci yang bergelombang, bibirnya menyentuh bibirmu."
  },
  AvgDialog_49401_Content_24 = {
    Text = "Napas kalian saling bersilangan, jiwa menyatu."
  },
  AvgDialog_49401_Content_25 = {
    Text = "Ujung lidah mendorong masuk, hangat, lembap, penuh kasih sayang, dan tak terelakkan."
  },
  AvgDialog_49401_Content_26 = {
    Text = "Ciuman itu bercampur dengan manisnya cinta, bau amis darah, dan sebuah benda kecil yang bulat."
  },
  AvgDialog_49401_Content_27 = {
    Text = "Benih pohon."
  },
  AvgDialog_49401_Content_3 = {Text = "...Dong!"},
  AvgDialog_49401_Content_31 = {
    Text = "Meskipun tidak dalam bentuk yang kubayangkan… tapi sudah berakhir."
  },
  AvgDialog_49401_Content_32 = {
    Text = "Sebagai keturunan dari esensi keinginan, bangsa Alan sangat berdedikasi untuk melanjutkan garis keturunan mereka."
  },
  AvgDialog_49401_Content_33 = {
    Text = "Oleh karena itu, kami menyembah Pohon Ibu, mengintegrasikan susu Pohon Ibu ke dalam daging tulang kami, dan berdoa untuk kemampuan reproduksi yang melampaui manusia."
  },
  AvgDialog_49401_Content_34 = {
    Text = "Selama ada satu orang yang selamat dari malapetaka hitam, peradaban dapat terus berlanjut di generasi berikutnya."
  },
  AvgDialog_49401_Content_35 = {
    Text = "Namun, kami keliru."
  },
  AvgDialog_49401_Content_36 = {
    Text = "Yang melanjutkan keturunan bangsa Alan bukanlah salah satu etnis Alan. Dalam perjalanan waktu yang panjang, mereka terlalu bergantung pada konsep \"keturunan\" dan menjadi budak dari keinginan untuk berkembang biak."
  },
  AvgDialog_49401_Content_37 = {
    Text = "Selama ratusan tahun dalam pengasingan... adalah Alva yang menopang bangsa Aram untuk terus maju."
  },
  AvgDialog_49401_Content_38 = {
    Text = "Tawil, kamu benar. Kita harus percaya pada kehendak manusia."
  },
  AvgDialog_49401_Content_39 = {
    Text = "Meskipun malam yang panjang sulit terang, meskipun cahayanya lemah, Roh mereka yang tak pernah menyerahlah yang benar-benar dapat mengubah masa depan yang telah ditakdirkan."
  },
  AvgDialog_49401_Content_4 = {Text = "Dong!"},
  AvgDialog_49401_Content_40 = {
    Text = "Sekarang, aku sudah mendapatkan jawaban baru."
  },
  AvgDialog_49401_Content_41 = {
    Text = "Jadi, kamu juga harus bersikap murah hati dan meminjamkan Pewarismu padaku, oke?"
  },
  AvgDialog_49401_Content_42 = {
    Text = "Saya bersedia mempercayai orang ini dan menyerahkan api kepada {Male=dia,Female=dia}."
  },
  AvgDialog_49401_Content_43 = {
    Text = "Benih ini suatu hari nanti akan berakar dan bertunas, tumbuh menjadi pohon yang menjulang tinggi,"
  },
  AvgDialog_49401_Content_44 = {
    Text = "Tepat seperti hari ketika Pohon Ibu pertama kali dilahirkan."
  },
  AvgDialog_49401_Content_46 = {
    Text = "Ini adalah Benih terakhir, aku akan meninggalkannya di dalam tubuhmu."
  },
  AvgDialog_49401_Content_47 = {
    Text = "Sebelum ia menyebarkan darahku ke bumi, kau... jangan mati."
  },
  AvgDialog_49401_Content_48 = {
    Text = "Selalu ingat aku, jangan lupakan aku."
  },
  AvgDialog_49401_Content_49 = {
    Text = "Gelombang pasang bergelora."
  },
  AvgDialog_49401_Content_5 = {
    Text = "Dung! Dung!"
  },
  AvgDialog_49401_Content_50 = {
    Text = "Pelukan yang hangat itu mendorongmu menjauh."
  },
  AvgDialog_49401_Content_51 = {
    Text = "Di tengah hanyutanmu yang terombang-ambing oleh arus, kau melihatnya melayang ke arah yang lebih dalam di sungai."
  },
  AvgDialog_49401_Content_53 = {
    Text = "Sebuah tangan putih yang ramping menarikmu, kekuatan itu terasa akrab dan teguh."
  },
  AvgDialog_49401_Content_54 = {Text = "%player%!"},
  AvgDialog_49401_Content_6 = {
    Text = "Satu per satu orang Aram jatuh."
  },
  AvgDialog_49401_Content_7 = {
    Text = "Beberapa detik kemudian, beberapa kepala kecil muncul dengan susah payah di permukaan air dan berenang menuju tepi sungai."
  },
  AvgDialog_49401_Content_8 = {
    Text = "Cabang di bawah kaki mulai bergetar."
  },
  AvgDialog_49401_Content_9 = {
    Text = "Sudah waktunya!"
  },
  AvgDialog_49402_Content_1 = {Text = "Tari"},
  AvgDialog_49402_Content_10 = {
    Text = "Apa yang tersembunyi di dalam Dinding Badai?"
  },
  AvgDialog_49402_Content_11 = {
    Text = "Apa tujuan utusan misterius Juliette?"
  },
  AvgDialog_49402_Content_12 = {
    Text = "Apa maksud dari ritual Alan?"
  },
  AvgDialog_49402_Content_13 = {
    Text = "Dan Thais, apakah Thais di depan mata ini benar-benar bisa dipercaya?"
  },
  AvgDialog_49402_Content_14 = {
    Text = "Sejak datang ke Lemuwah, insiden aneh terus terjadi tanpa henti, satu demi satu misteri mengejar hingga kamu sulit bernapas."
  },
  AvgDialog_49402_Content_15 = {
    Text = "Kamu perlu tenang, dan perlu berpikir."
  },
  AvgDialog_49402_Content_16 = {
    Text = "Tidak perlu dipikirkan, kamu sangat lelah dan butuh istirahat."
  },
  AvgDialog_49402_Content_17 = {
    Text = "Ketika berbalik, hanya ada satu bulan purnama yang menyinari wajah Thais yang halus dan lembut, memberikan kesan tembus cahaya."
  },
  AvgDialog_49402_Content_18 = {
    Text = "Di sisi lain Dinding Badai… semua pertanyaanmu akan terjawab."
  },
  AvgDialog_49402_Content_19 = {
    Text = "Di sisi lain Dinding Badai."
  },
  AvgDialog_49402_Content_2 = {
    Text = "▼▼Dalam kekacauan, tak seorang pun mengetahui akhirnya. \nApa yang akan terjadi terkandung dalam ucapanku, namun pendengaran dan penglihatan manusia telah lenyap, \nhanya mereka yang membisu tersebar di seluruh bumi."
  },
  AvgDialog_49402_Content_20 = {
    Text = "Juliette juga mengatakan hal yang sama, apakah kamu harus mengikuti maksud orang di balik layar itu dan masuk ke dalam badai?"
  },
  AvgDialog_49402_Content_21 = {
    Text = "Apakah ada semacam kekuatan gaib yang mendorong semua orang untuk berbondong-bondong menuju pusat badai seperti peziarah?"
  },
  AvgDialog_49402_Content_22 = {
    Text = "Pikiran terus berkecamuk, menanamkan Benih keraguan dan kecemasan di Laut Pikiran-mu."
  },
  AvgDialog_49402_Content_23 = {
    Text = "Apakah hatimu tidak pernah tenang?"
  },
  AvgDialog_49402_Content_24 = {
    Text = "Tutuplah matamu."
  },
  AvgDialog_49402_Content_25 = {
    Text = "Napas Thais hanya berjarak beberapa sentimeter dari Anda."
  },
  AvgDialog_49402_Content_26 = {
    Text = "Tutuplah mata"
  },
  AvgDialog_49402_Content_27 = {
    Text = "Menolak untuk menutup mata"
  },
  AvgDialog_49402_Content_28 = {
    Text = "Mata yang begitu jernih… sama sekali tidak menjadi keruh meski setelah perjalanan yang melelahkan ini."
  },
  AvgDialog_49402_Content_29 = {
    Text = "Thais meletakkan jari telunjuknya di bibir atas Anda."
  },
  AvgDialog_49402_Content_3 = {
    Text = "Kamu perlahan membuka mata, yang pertama kali terlihat adalah langit penuh bintang yang sangat cerah dan berkilauan."
  },
  AvgDialog_49402_Content_30 = {
    Text = "Wajahnya begitu dekat denganmu, cahaya bulan memberikan semburat lembut pada kulitnya."
  },
  AvgDialog_49402_Content_31 = {
    Text = "Kamu merasakan napas yang mendekat, lembut dan hangat."
  },
  AvgDialog_49402_Content_32 = {
    Text = "Benar-benar aroma yang membawa kenangan lama."
  },
  AvgDialog_49402_Content_33 = {
    Text = "Berapa lama kita tidak sedekat ini satu sama lain?"
  },
  AvgDialog_49402_Content_34 = {
    Text = "Terasa sentuhan dingin di bibir."
  },
  AvgDialog_49402_Content_35 = {
    Text = [[
Kamu membuka mata, jari telunjuk Thais menyentuh bibir kamu.
Wajahnya begitu dekat denganmu, cahaya bulan memberikan semburat cahaya lembut pada kulitnya.]]
  },
  AvgDialog_49402_Content_36 = {
    Text = "Apakah kamu tahu? Aku melihat Clades di matamu, melihat abu dari zaman purba, dan melihat napas alam semesta."
  },
  AvgDialog_49402_Content_37 = {
    Text = "Perjalanan yang kau jalani sangat panjang, pasti sudah sangat lelah, bukan? Namun, tatapanmu masih begitu teguh, tanpa sedikit pun kekaburan."
  },
  AvgDialog_49402_Content_38 = {
    Text = "Bintang-bintang tidak dapat mengubahmu, dan Gurun Pasir mungkin juga tidak bisa."
  },
  AvgDialog_49402_Content_39 = {
    Text = "Saya tidak memahami maksudmu."
  },
  AvgDialog_49402_Content_4 = {
    Text = "Bagaimana aku bisa... tertidur?"
  },
  AvgDialog_49402_Content_40 = {
    Text = "Kamu belum perlu memahami sekarang."
  },
  AvgDialog_49402_Content_41 = {
    Text = "Thais bangkit dan berjalan santai menuruni bukit pasir."
  },
  AvgDialog_49402_Content_42 = {
    Text = "Di bawah langit berbintang seperti ini, hanya duduk diam tanpa menikmati pemandangan sungguh terlalu tidak romantis."
  },
  AvgDialog_49402_Content_43 = {
    Text = "Angin menopang kain putih transparan yang ringan, dia melangkah dengan gemulai di atas pasir lembut."
  },
  AvgDialog_49402_Content_44 = {
    Text = "Izinkan aku mempersembahkan tarian Aran ini untukmu."
  },
  AvgDialog_49402_Content_45 = {
    Text = "Bel berbunyi, dia mengangkat satu tangannya, bergoyang untuk memulai tarian."
  },
  AvgDialog_49402_Content_46 = {
    Text = "Dia membungkuk, meregangkan tubuh, terkadang ekspresif, terkadang penuh kesederhanaan."
  },
  AvgDialog_49402_Content_47 = {
    Text = "Aku selalu menantikan seseorang."
  },
  AvgDialog_49402_Content_48 = {
    Text = "Tubuhnya lembut seolah tanpa tulang, gerakan dansanya seperti ular yang meliuk."
  },
  AvgDialog_49402_Content_49 = {
    Text = "Seorang penjaga yang dapat memimpin Aran menuju \"masa depan\"."
  },
  AvgDialog_49402_Content_5 = {
    Text = "Setelah berjalan lama di padang pasir, kelelahan adalah hal yang sangat wajar."
  },
  AvgDialog_49402_Content_50 = {
    Text = "Dia berputar dan bergoyang, sisa-sisa bayangannya menunjukkan keanggunan alami serta kelenturan yang luar biasa."
  },
  AvgDialog_49402_Content_51 = {
    Text = "Bukankah Alva adalah orang itu?"
  },
  AvgDialog_49402_Content_52 = {
    Text = "Thais memutar tubuhnya, menundukkan kepala dan matanya, ujung jarinya menyentuh bunga yang tergenggam saat napas berat terhela di sudut bibirnya."
  },
  AvgDialog_49402_Content_53 = {
    Text = "Alva adalah anak yang baik, namun dia belum mampu membuka jalan baru."
  },
  AvgDialog_49402_Content_54 = {
    Text = "Bagaimana dengan Juliette? Bukankah dia utusan dari negeri asing?"
  },
  AvgDialog_49402_Content_55 = {
    Text = "Apa yang kamu katakan tadi, jalan yang diminta Juliette untuk suku Alan adalah keluar dari gurun, benar kan?"
  },
  AvgDialog_49402_Content_56 = {
    Text = "Thais mengulurkan kedua tangannya, pandangan kosongnya tertuju pada bulan di ujung jarinya, seolah-olah melepas burung tak terlihat yang terbang menjauh."
  },
  AvgDialog_49402_Content_57 = {
    Text = "Orang-orang yang mampu pergi, sudah lama pergi. Aran tak pernah membatasi siapa pun. Baik karena rindu kampung halaman maupun terbiasa dengan gaya hidup gurun, mereka yang tetap tinggal hanya bisa bertahan di sini."
  },
  AvgDialog_49402_Content_58 = {
    Text = "Lagipula, itu bukan jawaban yang aku harapkan."
  },
  AvgDialog_49402_Content_59 = {
    Text = "Jawaban yang kamu harapkan... seperti apa?"
  },
  AvgDialog_49402_Content_6 = {
    Text = "Saya masih memiliki banyak pertanyaan..."
  },
  AvgDialog_49402_Content_60 = {
    Text = "Sudah lama tercantum dalam lagu."
  },
  AvgDialog_49402_Content_61 = {
    Text = "Pohon Ibu melahirkan kembali Sungai Suci, memberikan mahkota kepada yang telah tiada, dan mengembalikan garis keturunan kepada Alen."
  },
  AvgDialog_49402_Content_62 = {
    Text = "Kelahiran kembali Pohon Ibu di Sungai Suci mudah dipahami, tetapi siapakah yang dimaksud dengan yang telah meninggal? Dan bagaimana cara mengembalikan darah ke Alan?"
  },
  AvgDialog_49402_Content_63 = {Text = "Ssst——"},
  AvgDialog_49402_Content_64 = {
    Text = "Detail-detail tersebut terlalu rumit, ramalan @1 tidak bisa memberikan semua jawaban."
  },
  AvgDialog_49402_Content_65 = {
    Text = [[
Satu-satunya hal yang perlu kamu lakukan adalah mempercayaiku sepenuhnya. 
Percayalah pada Ratu Aran.]]
  },
  AvgDialog_49402_Content_66 = {
    Text = "Bunga padang pasir mekar di malam bulan yang redup, dia mengangkat tangan, berputar, dan melangkah, menciptakan ritme kuno dan rumit di atas pasir."
  },
  AvgDialog_49402_Content_67 = {
    Text = "Selama kamu percaya padaku, aku adalah senjata rahasia mutlak, satu-satunya, dan hanya milikmu —— Rahasia."
  },
  AvgDialog_49402_Content_68 = {
    Text = "Di bawah cahaya bulan, siluetnya tampak lembut dan misterius. Matanya bergerak lincah, mengungkapkan perasaan yang tak terucapkan."
  },
  AvgDialog_49402_Content_69 = {
    Text = "Jika ini adalah mimpi yang akan segera berakhir——\nBintang-bintang yang jauh menjadi saksi bagi dirinya."
  },
  AvgDialog_49402_Content_7 = {
    Text = "Mimpi yang panjang tampaknya telah membawamu menjauh dari perjalanan yang penuh ketegangan, satu per satu pertanyaan mulai muncul di benakmu."
  },
  AvgDialog_49402_Content_70 = {
    Text = "Tunggu, Thais, di bawah kakimu——"
  },
  AvgDialog_49402_Content_71 = {
    Text = "Kamu berteriak dengan cemas."
  },
  AvgDialog_49402_Content_72 = {
    Text = "Dia melangkah di atas riak. Bukan, riak hitam yang menyebar dari ujung kakinya."
  },
  AvgDialog_49402_Content_73 = {
    Text = "Ujung kain putih berkibar seperti daun teratai yang bergoyang, menyebarkan butiran air yang berkilauan. Warna hitamnya pekat dan dalam seperti obsidian."
  },
  AvgDialog_49402_Content_74 = {
    Text = "Itu adalah... D-lendir...?"
  },
  AvgDialog_49402_Content_75 = {
    Text = "Dia menari di dalam kolam pelarutan yang seperti fatamorgana. Dia berulang kali melangkah di atas permukaan cairan hitam."
  },
  AvgDialog_49402_Content_78 = {
    Text = "Dia seakan-akan tidak mendengar panggilanmu, menari mengikuti ritme yang tak terduga."
  },
  AvgDialog_49402_Content_79 = {
    Text = "Dia berbalik ke arahmu, posturnya anggun dan terbuka. Kalung yang kau pasangkan di lehernya berkilauan cemerlang di dadanya."
  },
  AvgDialog_49402_Content_8 = {
    Text = "Mengapa air dalam kantung air Ramona berubah menjadi D-lendir?"
  },
  AvgDialog_49402_Content_80 = {
    Text = "Dia mengundangmu untuk menari, dan tanpa sadar kau meletakkan tanganmu di telapak tangannya."
  },
  AvgDialog_49402_Content_81 = {
    Text = "Dia menarik telapak tanganmu, membimbing ujung jarimu menyentuh batu giok putih yang tampak berdenyut seperti memiliki kehidupan."
  },
  AvgDialog_49402_Content_82 = {
    Text = [[
Di langit jauh, meteor jatuh. 
 Matanya lebih berkilau daripada bintang-bintang.]]
  },
  AvgDialog_49402_Content_84 = {
    Text = "Bibirnya sedikit terbuka, angin malam membawa bisikan lembutnya."
  },
  AvgDialog_49402_Content_85 = {
    Text = "Bisakah aku menitipkan mereka padamu dengan tenang?"
  },
  AvgDialog_49402_Content_86 = {
    Text = "Sensasi tarikan yang mirip dengan malam pesta api unggun itu menangkapmu, hampir tanpa sadar, kamu bergumam."
  },
  AvgDialog_49402_Content_87 = {
    Text = "Bisa, pasti bisa."
  },
  AvgDialog_49402_Content_88 = {Text = "Itu bagus."},
  AvgDialog_49402_Content_89 = {
    Text = "Thais tersenyum."
  },
  AvgDialog_49402_Content_9 = {
    Text = "Siapa sebenarnya yang menyebarkan Nubia?"
  },
  AvgDialog_49402_Content_90 = {
    Text = "Teman-temanmu sudah tiba."
  },
  AvgDialog_49402_Content_91 = {
    Text = "Kamu mengikuti pandangan Thais, dan melihat Ramona berlari ke arahmu. Ryker mengikuti di belakangnya, langkahnya cepat namun mantap, tetap mempertahankan sikap anggun dan elegan."
  },
  AvgDialog_49402_Content_92 = {
    Text = "Jangan lupa, malam ini adalah rahasia yang hanya milik kita."
  },
  AvgDialog_49402_Content_93 = {
    Text = "Ketika berbalik lagi, sosok Thais menghilang, hanya angin yang menderu melewati gurun."
  },
  AvgDialog_49402_Content_94 = {
    Text = "Di depanmu, jejak hitam D-lendir meresap ke dalam pasir yang mengalir, menyatu dengan tanah."
  },
  AvgDialog_49414_Content_1 = {
    Text = "Penjaga, fungsi Kenangan telah diaktifkan. Jika ingin menggunakannya, ketuk komunikator, dan setelah bunyi \"drip\" terdengar, panggil Erica untuk melakukan penelusuran."
  },
  AvgDialog_49414_Content_2 = {
    Text = "Kenangan... Apa ini?"
  },
  AvgDialog_49414_Content_3 = {
    Text = "Di sini tersimpan catatan memori Anda. Melalui fungsi Kenangan, Anda dapat lebih mudah mengingat pengalaman dalam berbagai acara penyelidikan."
  },
  AvgDialog_49414_Content_4 = {
    Text = "Perhatikan detail-detail yang pernah kamu abaikan. Manusia selalu harus belajar dari masa lalu untuk menghadapi tantangan di masa depan."
  },
  AvgDialog_49440_Content_1 = {
    Text = "(Hah, hah…)"
  },
  AvgDialog_49440_Content_2 = {
    Text = "Karen…? Apa yang sedang kau lakukan?"
  },
  AvgDialog_49440_Content_3 = {
    Text = "Di depan matamu gelap gulita. Sesuatu menutupi kedua matamu."
  },
  AvgDialog_49440_Content_4 = {
    Text = "Kau mencoba mengangkat kedua tanganmu, tetapi ikatan kain yang lembut mengunci kedua pergelanganmu, membuatmu hanya bisa bergerak dalam jangkauan yang sangat terbatas."
  },
  AvgDialog_49440_Content_5 = {
    Text = "Masih perlu ditanya? Tentu saja… bersih-bersih besar~"
  },
  AvgDialog_49440_Content_6 = {
    Text = "Bersih-bersih besar kenapa harus mengikatku?"
  },
  AvgDialog_49440_Content_7 = {
    Text = "Firasat buruk muncul dari dalam hatimu. Tindakan yang akan dilakukan pelayan kecil yang muncul dan menghilang sesuka hati ini di bawah pengaruh Sungai Suci sama sekali di luar dugaanmu."
  },
  AvgDialog_49440_Content_8 = {
    Text = "Ber—sih—ber—sih besar yang penting harus tuntas! Sang Penjaga Rahasia juga bagian dari bersih-bersih besar!"
  },
  AvgDialog_49440_Content_9 = {
    Text = "Di sini, di sana… setiap tempat harus dibersihkan sampai bersih~"
  },
  AvgDialog_49441_Content_1 = {
    Text = "Erica, bisakah kau menemukan di rak buku mana Surat No. A-617 berada?"
  },
  AvgDialog_49441_Content_10 = {Text = "Eri——"},
  AvgDialog_49441_Content_11 = {
    Text = "Suaramu terdorong kembali ke dalam perut oleh arus listrik yang samar, sensasi dari kedua tangan yang saling bertaut itu jauh melampaui apa yang bisa ditanggung manusia biasa."
  },
  AvgDialog_49441_Content_12 = {
    Text = "Arus listrik yang singkat namun menyilaukan membangkitkan seluruh indramu. Koneksi yang melampaui nalar membuat darahmu berdesir dengan hasrat yang tak terkatakan."
  },
  AvgDialog_49441_Content_14 = {
    Text = "Erica mengerjapkan mata dan menarik tangannya kembali."
  },
  AvgDialog_49441_Content_15 = {
    Text = "Baik. Surat No. A-617 terletak di area terlarang perpustakaan data. Sedang mengantar Penjaga Rahasia ke sana."
  },
  AvgDialog_49441_Content_16 = {
    Text = "Setelah berkata demikian, Erica langsung berjalan menuju area terlarang tanpa menoleh, meninggalkanmu dengan punggungnya yang berderik-derik oleh percikan listrik."
  },
  AvgDialog_49441_Content_17 = {
    Text = "…Boneka otomatis seharusnya tidak terpengaruh oleh anomali Sungai Suci, kan?"
  },
  AvgDialog_49441_Content_18 = {Text = "…Kan?"},
  AvgDialog_49441_Content_3 = {Text = "Erika?"},
  AvgDialog_49441_Content_4 = {
    Text = "Gadis mekanik itu berdiri diam di sudut ruangan, wajahnya menampilkan senyuman seperti biasa, namun keheningan ini membuat senyumannya terlihat semakin mengganggu."
  },
  AvgDialog_49441_Content_5 = {
    Text = "Kau melambaikan tangan di depan matanya dua kali, tetapi sepasang bola mata itu tidak menunjukkan tanda-tanda pergerakan sedikit pun."
  },
  AvgDialog_49441_Content_6 = {
    Text = "Aneh, Erica tidak pernah melamun… apakah tubuh mekanisnya bermasalah?"
  },
  AvgDialog_49441_Content_7 = {
    Text = "Kau bergumam sambil berjalan mengelilingi tubuh Erica."
  },
  AvgDialog_49441_Content_8 = {
    Text = "——Kretik."
  },
  AvgDialog_49441_Content_9 = {
    Text = "Suara letupan halus menarik perhatianmu. Secara refleks kau menoleh ke arah sumber suara, namun seseorang langsung menggenggam tanganmu."
  },
  AvgDialog_49442_Content_1 = {Text = "Mimpi"},
  AvgDialog_49442_Content_10 = {
    Text = "Byurrr——"
  },
  AvgDialog_49442_Content_11 = {
    Text = "Dunia kembali dipenuhi suara dan warna."
  },
  AvgDialog_49442_Content_12 = {
    Text = "Mereka satu per satu, tanpa ragu melompat ke Sungai Suci yang mengalir deras, berusaha sepenuhnya merentangkan lengan mereka untuk memeluk batang tubuh kering Pohon Ibu."
  },
  AvgDialog_49442_Content_13 = {
    Text = "Mereka berteriak dengan penuh semangat, memancarkan teriakan kegilaan yang tak terlukiskan."
  },
  AvgDialog_49442_Content_14 = {
    Text = "Kulit mereka menjadi kendur, seolah-olah lumpur yang meleleh; cairan tubuh mereka terpisah dari daging, mengalir deras membentuk aliran Sungai Suci."
  },
  AvgDialog_49442_Content_15 = {
    Text = "Tulang mereka seolah-olah melunak seperti daging, anggota tubuh mereka berkelok, memanjang, dan saling membentuk jalinan dengan cara yang bukan manusiawi, menggunakan Caro mereka sendiri untuk membentuk batang pohon suci yang besar dan bengkak."
  },
  AvgDialog_49442_Content_16 = {
    Text = "Mereka dengan lambat dan menyakitkan menyatu dengan Pohon Suci."
  },
  AvgDialog_49442_Content_2 = {
    Text = "Pada akhirnya, boneka itu tetap tidak sempurna, masih membutuhkan terlalu banyak kelelahan untuk dikendalikan."
  },
  AvgDialog_49442_Content_3 = {
    Text = "Seberapa teguh tekadmu untuk berkorban demi Alan, setelah menyadari kebenarannya, kamu akan memberontak dengan sangat hebat."
  },
  AvgDialog_49442_Content_4 = {
    Text = "Untungnya, aku sudah memperkirakan situasi seperti ini sejak awal."
  },
  AvgDialog_49442_Content_5 = {
    Text = "Waktunya hampir tiba, kalian semua, untuk Pohon Ibu yang paling kalian cintai…"
  },
  AvgDialog_49442_Content_6 = {
    Text = "Persembahkan Caro dan Hidupmu."
  },
  AvgDialog_49442_Content_7 = {
    Text = [[
Saya membuka mulut, terkejut karena menyadari bahwa saya tidak bisa mengeluarkan suara. 
Segala sesuatu di sekitar saya tiba-tiba terhenti dalam keheningan yang mencekam.]]
  },
  AvgDialog_49442_Content_8 = {
    Text = "Bukan, yang diam bukan dunia, melainkan persepsi saya. Setiap kedipan kecil terasa seperti berlalunya satu abad."
  },
  AvgDialog_49442_Content_9 = {
    Text = "Di dalam urutan yang terhenti dan berkepanjangan, hanya rekan-rekanku sebelumnya, satu per satu tentara Aran, yang berlari tanpa henti menuju Sungai Suci."
  },
  AvgDialog_49443_Content_1 = {
    Text = "Di bawah Pohon Ibu, Alva yang tak berdaya menangis sambil berlutut."
  },
  AvgDialog_49443_Content_10 = {
    Text = "Untung juga kamu ikut, kalau tidak, setiap menit untuk kembali menjemputmu akan membuat Lelah entah berapa banyak Hidup."
  },
  AvgDialog_49443_Content_11 = {
    Text = "Suara di dalam kepala saya... dia memberi tahu saya... aku harus tetap bertahan..."
  },
  AvgDialog_49443_Content_12 = {
    Text = [[
Namun, meskipun dia tidak mengatakannya...
Aku adalah asisten satu-satunya %player%, di saat-saat paling berbahaya, aku harus tetap berada di sisi {Male=dia,Female=dia}.]]
  },
  AvgDialog_49443_Content_13 = {
    Text = "Bukankah ini adalah tugasku sebagai satu-satunya asisten, kan?"
  },
  AvgDialog_49443_Content_14 = {
    Text = "Kata \"satu-satunya\" yang diucapkannya terdengar sangat tegas."
  },
  AvgDialog_49443_Content_15 = {
    Text = "Di tanah ini, bangun kekuatannya, pengaruh yang diterima tubuhmu akan semakin parah."
  },
  AvgDialog_49443_Content_16 = {
    Text = "Jika ada cara lain, saya juga tidak rela menggunakan cara ini."
  },
  AvgDialog_49443_Content_17 = {
    Text = "Mythag datang untuk menghentikan ritual. Saya adalah anggota Mythag, siap mati berkali-kali tanpa ragu!"
  },
  AvgDialog_49443_Content_18 = {
    Text = "Bagus! Ramona menekan esensi keinginan. %player%, kamu dan aku bersama-sama akan sepenuhnya menghancurkan Pohon Ibu!"
  },
  AvgDialog_49443_Content_19 = {
    Text = "Di langit yang luas terdengar suara melengkung yang memekakkan telinga, dan bayangan perak melintasi langit gurun yang tinggi."
  },
  AvgDialog_49443_Content_2 = {
    Text = "Bukankah aku menyembunyikan tubuh Pohon Ibu di Sungai Suci, dan dengan tubuhku menanggung pelarutan untuk menyembunyikan benih Pohon Ibu, semua ini demi menunggu saat ini?"
  },
  AvgDialog_49443_Content_21 = {
    Text = "Kamu merasakan tubuhmu menjadi ringan, detik berikutnya kamu sudah berada di depan gumpalan tumor yang kotor dan bau."
  },
  AvgDialog_49443_Content_22 = {
    Text = "Orang Aram yang ditelan oleh Pohon Ibu berkumpul di sini dalam bentuk telur. Di dalam lubang tembus cahaya, tak terhitung wajah yang terdistorsi dan kabur. Hanya cairan berwarna merah-hitam yang terus-menerus mengalir keluar dari lubang tersebut, bergabung ke dalam Sungai Suci yang tidak lagi jernih."
  },
  AvgDialog_49443_Content_3 = {
    Text = "Saatnya pertempuran penentuan!"
  },
  AvgDialog_49443_Content_4 = {
    Text = "Dengan nama Tifare Yessod yang berwujud keinginan, aku mengajukan permintaan kepada <Yellow:Tawil>, tolong jawab perjanjian kita dari seribu tahun yang lalu——"
  },
  AvgDialog_49443_Content_5 = {
    Text = "Ketika utusan dari negeri asing tiba, dengan wujudmu sebagai pengantar, untuk sementara mengusir bayangan yang menyelimuti Lemwahsi."
  },
  AvgDialog_49443_Content_6 = {
    Text = "Di langit terdengar ratapan sedih yang lantang."
  },
  AvgDialog_49443_Content_7 = {
    Text = "Thais membuka peti mati, dan yang bangkit dari dalamnya adalah Ramona dengan wajah memerah karena terbakar."
  },
  AvgDialog_49443_Content_8 = {
    Text = "Akhirnya... apakah kau membutuhkanku..."
  },
  AvgDialog_49443_Content_9 = {
    Text = "Bersembunyi di sini dan mengikuti, sungguh ide yang cerdas, Nona Kecil."
  },
  AvgDialog_49476_Content_1 = {
    Text = "Pintu terbuka perlahan, cahaya lampu memantulkan sebuah bayangan yang familiar."
  },
  AvgDialog_49476_Content_10 = {
    Text = "Sepertinya pengaruh Sungai Suci sudah merambat ke dimensi tempatmu berada… kamu baik-baik saja?"
  },
  AvgDialog_49476_Content_11 = {
    Text = "Bisakah kamu menemaniku, Penjaga Rahasia?"
  },
  AvgDialog_49476_Content_12 = {
    Text = "Tentu, tentu saja. Hanya saja, aku tidak tahu bagaimana cara membantumu…"
  },
  AvgDialog_49476_Content_13 = {
    Text = "Aku ingin membawamu ke suatu tempat."
  },
  AvgDialog_49476_Content_14 = {Text = "Ke mana?"},
  AvgDialog_49476_Content_15 = {
    Text = "Ramona duduk di sampingmu. Rona merah itu menyatu secara alami di bawah cahaya lampu dan kulit putihnya yang bersih, membuat napasmu tertahan sejenak."
  },
  AvgDialog_49476_Content_16 = {
    Text = "Saat dia menggenggam tanganmu, ruang di sekitarmu mulai berubah. Tak terhitung banyaknya gambaran membentuk sebuah pemandangan kacau yang tampak familiar, muncul di hadapanmu."
  },
  AvgDialog_49476_Content_17 = {
    Text = "Pemandangan di sini sangat kacau... Ini adalah gambaran dari ingatanmu?"
  },
  AvgDialog_49476_Content_18 = {
    Text = "Maaf... Aku telah mengalami pemandangan yang sama berkali-kali, ingatanku terlalu rumit... Tapi kupikir, kau bisa melihat tempat ini dengan jelas."
  },
  AvgDialog_49476_Content_19 = {
    Text = "Pemandangan dan aroma yang kabur itu, terasa familiar... Seperti reruntuhan setelah ledakan besar... Jangan-jangan tempat ini...?!"
  },
  AvgDialog_49476_Content_2 = {
    Text = "Ramona? Bukankah kamu bilang besok ada ujian, malam ini mau tidur lebih awal?"
  },
  AvgDialog_49476_Content_20 = {
    Text = "Akut, tempat di mana ingatan kehidupanmu dimulai... dan juga tempat di mana kau bertemu dengan diriku di dunia ini."
  },
  AvgDialog_49476_Content_21 = {Text = "!!!"},
  AvgDialog_49476_Content_22 = {
    Text = "Penjaga Rahasia, ada hal-hal yang sudah lama kau lupakan, tapi aku masih mengingatnya."
  },
  AvgDialog_49476_Content_23 = {
    Text = "Di sini, aku kehilanganmu, berulang kali. Setiap kali, aku mengingatnya dengan sangat jelas."
  },
  AvgDialog_49476_Content_24 = {
    Text = "Hanya satu kali itu, kau melangkah maju, menuju kehancuran tanpa batas, menuju satu-satunya titik cahaya yang menyimpan harapan... Tapi satu-satunya titik cahaya itu, tidak ada hubungannya denganku."
  },
  AvgDialog_49476_Content_25 = {
    Text = "Jantungmu seolah tertusuk pisau tajam, rasa sakit yang jelas menyerangmu. Kau merentangkan kedua lenganmu, merengkuh gadis itu dalam pelukanmu."
  },
  AvgDialog_49476_Content_26 = {
    Text = "Kali ini, gadis tenang yang telah bertempur di tak terhitung ruang dan waktu ini tidak menghindar."
  },
  AvgDialog_49476_Content_27 = {
    Text = "Dia dengan patuh bersandar dalam pelukanmu, perlahan menggosokkan kepalanya ke dadamu, seperti seekor kucing yang terluka yang akhirnya kembali ke pelukan tuannya."
  },
  AvgDialog_49476_Content_28 = {
    Text = "Di dimensi ini, kau memiliki banyak rekan di sisimu. Dor, Helet, Alistair... dan juga diriku di dunia ini, yang selalu menemanimu."
  },
  AvgDialog_49476_Content_29 = {
    Text = "Aku percaya, kalian pasti akan melangkah maju dengan lancar, menyelesaikan apa yang ingin kalian capai."
  },
  AvgDialog_49476_Content_3 = {
    Text = "Kebetulan, Profesor Dexter baru saja bilang padaku besok siang dia akan memasak makan siang di rumah, minta kita langsung ke sana setelah ujian selesai."
  },
  AvgDialog_49476_Content_30 = {
    Text = "Aku seharusnya tidak muncul seperti ini. Setelah pengalaman di begitu banyak ruang dan waktu, seharusnya aku sudah menjadi lebih dewasa."
  },
  AvgDialog_49476_Content_31 = {
    Text = "Tapi aku tidak ingin kehilanganmu lagi, Penjaga Rahasia."
  },
  AvgDialog_49476_Content_32 = {
    Text = "Cairan bening mengalir dari balik penutup mata gadis itu, melewati helai rambut pucat, melewati pipi yang merona merah."
  },
  AvgDialog_49476_Content_33 = {
    Text = "Dahinya menempel erat padamu, rambutnya perlahan menyapu pipimu. Napasmu terhenti, kau terpaku menatap melalui penutup mata yang lembut itu, memandang mata berkaca-kaca yang tak lagi ada miliknya."
  },
  AvgDialog_49476_Content_34 = {
    Text = "Suaranya yang dingin dan sedikit bergetar terdengar di telingamu, napas hangatnya menerpa telingamu, bagaikan igauan penuh kasih namun lemah dari tak terhitung ruang dan waktu."
  },
  AvgDialog_49476_Content_35 = {
    Text = "Seragam siswa Misag yang rusak akibat pertempuran tak terhitung, perlahan tergelincir ke tanganmu."
  },
  AvgDialog_49476_Content_36 = {
    Text = "Anggap saja ini pengaruh Sungai Suci, ya?"
  },
  AvgDialog_49476_Content_37 = {
    Text = "Hari ini, biarkan aku bersikap kekanak-kanakan sekali saja. Untuk yang terakhir kalinya."
  },
  AvgDialog_49476_Content_4 = {
    Text = "Aku juga sangat ingin pergi, Penjaga Rahasia. Sudah lama sekali aku tidak bertemu Ayah… tapi, aku khawatir tidak pantas muncul di rumah Ayah."
  },
  AvgDialog_49476_Content_5 = {
    Text = "Postur tubuh yang sama, warna suara yang sama, tetapi dalam suaranya tidak ada lagi kepolosan sedikit pun, yang ada hanyalah ketenangan setelah melewati berbagai cobaan, serta sedikit kegugupan yang entah datang dari mana."
  },
  AvgDialog_49476_Content_6 = {
    Text = "Yang muncul di bawah cahaya lampu mengikuti suara itu, adalah penutup mata yang tak terlupakan bagimu."
  },
  AvgDialog_49476_Content_7 = {Text = "Kamu?"},
  AvgDialog_49476_Content_8 = {
    Text = "Maaf, aku pernah bilang, tidak akan datang mengganggumu atas inisiatifku sendiri, hanya saja…"
  },
  AvgDialog_49476_Content_9 = {
    Text = "Di balik penutup mata hitam sang gadis, rona merah yang tidak biasa muncul di wajahnya yang semula pucat."
  },
  AvgDialog_49742_Content_1 = {
    Text = "Kau bertanya kepada semua orang: Doer, Erica, Sylvia, Holet, Hannah……"
  },
  AvgDialog_49742_Content_10 = {
    Text = "Penjaga Rahasia…"
  },
  AvgDialog_49742_Content_11 = {
    Text = "Ramona mundur setengah langkah tanpa disadari, menunjukkan ekspresi yang menjaga jarak padamu."
  },
  AvgDialog_49742_Content_12 = {
    Text = "Maaf, tolong jangan mendekat dulu, aku……"
  },
  AvgDialog_49742_Content_13 = {
    Text = "Anomali Sungai Suci telah memengaruhi banyak Awakened. Kupikir…… aku akan menjadi pengecualian, karena aku… identitasku……"
  },
  AvgDialog_49742_Content_14 = {
    Text = "Ramona tetaplah Ramona, itu tidak akan pernah berubah."
  },
  AvgDialog_49742_Content_15 = {
    Text = "Aku adalah aku……"
  },
  AvgDialog_49742_Content_16 = {Text = "Benar."},
  AvgDialog_49742_Content_17 = {
    Text = "Kau melangkah maju dua langkah dengan teguh ke hadapannya dan menggenggam tangannya."
  },
  AvgDialog_49742_Content_18 = {
    Text = "Baik di Kota Kecil Lai maupun di dalam mimpiku, berapa kali pun kau bertanya padaku, jawabanku akan selalu sama."
  },
  AvgDialog_49742_Content_19 = {
    Text = "Kekuatan yang tak tertahankan menarikmu ke arah Ramona. Dia menangkap tubuhmu yang terhuyung, kedua lengannya menyilang di punggungmu, dagunya bertumpu di bahu kirimu."
  },
  AvgDialog_49742_Content_2 = {
    Text = "Semua orang menunjukkan arah yang sama untukmu. Mereka menyuruhmu melewati halaman tengah kampus dan mendorong pintu besi berukir di ujung jalan batu."
  },
  AvgDialog_49742_Content_20 = {
    Text = "Dua kalimat sederhanamu saja sudah cukup menenangkan jiwaku…… Apa aku terlalu tegang akhir-akhir ini?"
  },
  AvgDialog_49742_Content_21 = {
    Text = "Kau hanya terlalu lelah, kita semua begitu."
  },
  AvgDialog_49742_Content_22 = {
    Text = "Kedua tanganmu merangkul pinggangnya sebagai balasan. Kalian berdua tenggelam dalam keheningan bersama dunia, hanya terdengar napas satu sama lain, namun tetap tak henti menyerap kehangatan mesra dari tubuh masing-masing."
  },
  AvgDialog_49742_Content_23 = {
    Text = "……Terima kasih, %player%."
  },
  AvgDialog_49742_Content_24 = {
    Text = "Ramona yang pertama melepaskan diri dari pelabuhan perlindungan itu. Ia memegang bahumu, ingin berkata namun ragu."
  },
  AvgDialog_49742_Content_25 = {
    Text = "Masih ada yang ingin kau katakan padaku?"
  },
  AvgDialog_49742_Content_26 = {
    Text = "Tidak, bukan sekarang."
  },
  AvgDialog_49742_Content_27 = {
    Text = "Ia menepuk bahumu, memberi isyarat arah untuk pergi."
  },
  AvgDialog_49742_Content_28 = {
    Text = "Kembalilah dulu, ya? Aku janji, besok kau akan melihat diriku yang sudah kembali normal."
  },
  AvgDialog_49742_Content_29 = {
    Text = "Untuk sementara ia membutuhkan lebih banyak waktu dan ruang, dan kau sepenuhnya bisa memahami itu."
  },
  AvgDialog_49742_Content_3 = {
    Text = "Saat kau memasuki Makam Kunci, awan mendung yang menggelayut di langit sepanjang hari akhirnya melepaskan raungan pertamanya. Kilat yang dingin dan tajam menyambar dari langit, melompat ke ujung cakrawala."
  },
  AvgDialog_49742_Content_30 = {
    Text = "Ramona memandangi punggung partnernya menghilang di antara deretan tugu, barulah ia menghembuskan napas berat."
  },
  AvgDialog_49742_Content_31 = {
    Text = "Tenggorokannya terasa terbakar seperti dilalap api, setiap hembusan napas bagaikan rintihan kesakitan seorang pasien yang tak tertahankan — namun di hadapan partnernya, ia mengerahkan seluruh tenaga untuk menyamarkan kejanggalannya."
  },
  AvgDialog_49742_Content_32 = {
    Text = "Ia perlahan duduk di depan tugu berbentuk kunci, seolah dituntun oleh takdir, sepuluh jarinya menekan nama yang terukir di sana."
  },
  AvgDialog_49742_Content_33 = {
    Text = "Ia memiringkan kepala, bibirnya perlahan mendekat ke permukaan batu nisan yang dingin, merasakan suhu takdir dengan bibirnya yang lembut."
  },
  AvgDialog_49742_Content_34 = {
    Text = "%player%......"
  },
  AvgDialog_49742_Content_35 = {
    Text = "Ini adalah nama yang tak akan pernah ia lupakan, tak akan pernah."
  },
  AvgDialog_49742_Content_4 = {
    Text = "Hujan akan segera turun…… Cuaca seperti ini, untuk apa dia datang ke Makam Kunci?"
  },
  AvgDialog_49742_Content_5 = {
    Text = "Dia orang yang cerdas, \"sedia payung sebelum hujan\" adalah nama tengahnya. Berziarah ke makam leluhur di hari yang akan diguyur hujan deras? Bukan gayanya sama sekali."
  },
  AvgDialog_49742_Content_6 = {
    Text = "Kau berjalan di antara nisan-nisan berbentuk kunci dengan berbagai gaya, dan akhirnya melihat sosok yang familiar itu dari kejauhan."
  },
  AvgDialog_49742_Content_7 = {
    Text = [[
Dia berdiri di tengah kelompok nisan kunci tahun Banjir 315, menundukkan kepala ke sebuah batu nisan.
Dia tampak tenggelam dalam emosi yang asing, tidak menyadari kedatanganmu.]]
  },
  AvgDialog_49742_Content_8 = {
    Text = "Angin dingin dan lembap sebelum hujan membawa pergi suara kehidupan. Makam Kunci adalah sebuah kuburan raksasa. Dan gadis itu berdiri di sana, jubah hitamnya tertiup angin membungkus tubuhnya, bagaikan seorang penjaga makam yang kesepian."
  },
  AvgDialog_49742_Content_9 = {
    Text = "Ramona, ini aku."
  },
  AvgDialog_49825_Content_1 = {
    Text = "Yang membangunkanmu dari tidur bukanlah sinar mentari pagi Missage, melainkan sensasi aneh yang mengalir dalam darahmu."
  },
  AvgDialog_49825_Content_10 = {
    Text = "<Big:Masih berani membantah!>"
  },
  AvgDialog_49825_Content_11 = {
    Text = "Hmph……prinsip 'tidak lebih dari tiga kali', hari ini akan kuajarkan padamu."
  },
  AvgDialog_49825_Content_2 = {
    Text = "Seperti tusukan jarum halus, atau seperti kaki-kaki artropoda yang merayap di sisi dalam pembuluh darahmu. Rasa gatal dan perih yang halus menusuk sarafmu, membuat seluruh tubuhmu kejang tanpa bisa dikendalikan."
  },
  AvgDialog_49825_Content_3 = {
    Text = "Berhenti **pura-pura tidur, aku tahu kau sudah bangun!"
  },
  AvgDialog_49825_Content_4 = {
    Text = "Dengan susah payah kau membuka mata, dan pemandangan yang tersaji membuatmu tak bisa menahan napas——"
  },
  AvgDialog_49825_Content_5 = {
    Text = "Labirin tanpa jalan keluar, sarang Sang Penguasa Pucat, gadis bermata ganda yang dikelilingi kawanannya."
  },
  AvgDialog_49825_Content_6 = {
    Text = "Bengong? Makhluk-makhluk kecil ini sepertinya tidak punya kemampuan untuk membuat orang jadi bodoh, kan?"
  },
  AvgDialog_49825_Content_7 = {
    Text = "Sudahlah, tidak usah membahas hal yang tidak penting……\nMasih ingat? Sebelum hari ini, kau sudah menolakku dua kali."
  },
  AvgDialog_49825_Content_8 = {
    Text = "Bergabung dalam perkembangbiakan Sang Penguasa Pucat……kau sudah menolakku dua kali!"
  },
  AvgDialog_49825_Content_9 = {
    Text = "Tubuh manusiaku ini tidak kuat menghadapi ulah laba-laba kecilmu itu……"
  },
  AvgDialog_49826_Content_1 = {
    Text = "Penjaga Rahasia, apa ini perbuatanmu?"
  },
  AvgDialog_49826_Content_10 = {
    Text = "Jika ini adalah bantuanmu……aku akan menyalurkan kekuatan ini kepadamu."
  },
  AvgDialog_49826_Content_11 = {
    Text = "Kita bisa berbagi kekuatan ini. Bergabunglah denganku, ikutilah evolusi yang melampaui batas."
  },
  AvgDialog_49826_Content_2 = {
    Text = "Memangnya aku melakukan apa? Jangan buru-buru mengacungkan senjata padaku, kalau ada sesuatu kita bisa bicarakan baik-baik—"
  },
  AvgDialog_49826_Content_3 = {
    Text = "Begitu memasuki ruang perawatan, sang pemuda langsung tak sabar menghampirimu."
  },
  AvgDialog_49826_Content_4 = {
    Text = "Sirip punggungku terasa panas……sirip telingaku juga."
  },
  AvgDialog_49826_Content_5 = {
    Text = "Ia menarik tanganmu, memintamu meraba sirip telinga sang Penerjang Lautan yang bergetar."
  },
  AvgDialog_49826_Content_6 = {
    Text = "Sirip telinga berwarna merah muda keabu-abuan itu dilapisi lendir pelembap, seharusnya terasa dingin dan basah saat disentuh, namun kini jari-jarimu justru merasakan gelombang panas yang membakar."
  },
  AvgDialog_49826_Content_7 = {
    Text = "Ini demam? Aku akan memanggil Nona Sylvia untuk memeriksanya. Untuk kondisi tubuh Awakened Body, kita perlu mencari Dor……"
  },
  AvgDialog_49826_Content_8 = {
    Text = "Caecus menghalangkan senjatanya di belakangmu, mengurungmu di ambang pintu. Napasnya terasa lembap dan berat seperti belum pernah sebelumnya."
  },
  AvgDialog_49826_Content_9 = {
    Text = "Tidak……ini adalah bukti bahwa aku sedang berevolusi menuju kekuatan laut dalam yang sempurna."
  },
  AvgDialog_49836_Content_1 = {
    Text = "Cium perpisahan"
  },
  AvgDialog_49836_Content_10 = {
    Text = "Namun, banyak orang telah mengorbankan hidup mereka untuk keyakinan yang sakit."
  },
  AvgDialog_49836_Content_11 = {
    Text = "Ini adalah takdir bangsa Aram, kami dilahirkan di sini, tumbuh di sini."
  },
  AvgDialog_49836_Content_12 = {
    Text = "Jadi, apakah kamu membiarkan mereka melakukan ritual terkutuk seperti itu, membiarkan mereka terjebak berulang kali di Dinding Badai?"
  },
  AvgDialog_49836_Content_13 = {
    Text = "Thais tidak menjawab pertanyaanmu."
  },
  AvgDialog_49836_Content_14 = {
    Text = "Dia hanya mendekat, lalu memelukmu dengan lembut."
  },
  AvgDialog_49836_Content_15 = {
    Text = "Aku tahu kamu sangat lelah, sangat marah…"
  },
  AvgDialog_49836_Content_16 = {
    Text = [[
Kamu memiliki rasa dendam dan ketidakpahaman terhadapku. 
Namun, aku juga punya alasan tersendiri.]]
  },
  AvgDialog_49836_Content_17 = {
    Text = "Aku akan menceritakan sebuah cerita kepadamu, sebuah cerita yang sangat, sangat panjang."
  },
  AvgDialog_49836_Content_18 = {
    Text = "Pada zaman dahulu kala, ribuan tahun sebelum terjadinya banjir besar, ada sebuah peradaban yang memuja dewa yang disebut Pohon Ibu."
  },
  AvgDialog_49836_Content_19 = {
    Text = "Namun, kehendak Pohon Ibu tidak dapat mengokohkan pemerintahan kekaisaran, maka mereka pun merancang sebuah rencana."
  },
  AvgDialog_49836_Content_2 = {
    Text = "Malam telah larut, dan William juga sudah beristirahat."
  },
  AvgDialog_49836_Content_20 = {
    Text = "Mereka memilih banyak gadis, memaksa mereka meminum susu merah segar dari Pohon Ibu, dan mandi dalam cairan pohon tersebut hingga gadis-gadis itu menyatu dengan pohon."
  },
  AvgDialog_49836_Content_21 = {
    Text = "Sejak saat itu, gadis yang seperti boneka tersebut mewakili kehendak pohon."
  },
  AvgDialog_49836_Content_22 = {
    Text = "Namun, tak seorang pun pernah mendengar suaranya atau menaati perkataannya. Karena gadis itu tidak memiliki suara maupun kehendaknya sendiri. Apa yang ia sampaikan hanyalah kata-kata yang diperintahkan oleh Raja Nineveh untuk dihafal dan diucapkan kembali."
  },
  AvgDialog_49836_Content_23 = {
    Text = "Seorang menteri yang baik hati menyelamatkannya dari cengkeraman kejahatan, dan memberitahunya bahwa dia bisa menjadi dirinya sendiri."
  },
  AvgDialog_49836_Content_24 = {
    Text = "Apakah gadis itu melarikan diri?"
  },
  AvgDialog_49836_Content_25 = {
    Text = "Melarikan diri."
  },
  AvgDialog_49836_Content_26 = {
    Text = "Namun, cerita ini belum berakhir."
  },
  AvgDialog_49836_Content_27 = {
    Text = "Gadis yang melarikan diri bercampur dengan kerumunan. Dia meringkuk di sudut dinding, ketakutan saat orang lain mendekat, namun yang dia terima hanyalah sepotong roti."
  },
  AvgDialog_49836_Content_28 = {
    Text = "Orang-orang memberinya roti, bukan karena dia adalah Ratu Kekaisaran, bukan karena dia adalah pelaksana Pohon Ibu… hanya karena dia seorang anak."
  },
  AvgDialog_49836_Content_29 = {
    Text = "Pada saat itu, kehendak gadis dan pohon tersebut beresonansi dengan mendalam."
  },
  AvgDialog_49836_Content_3 = {
    Text = "Kamu menarik napas dalam-dalam, tepat saat hendak kembali ke tenda, tiba-tiba Thais melambaikan tangan padamu dari belakang tenda."
  },
  AvgDialog_49836_Content_30 = {
    Text = "Kemudian, kehendak pohon bertanya kepadanya:"
  },
  AvgDialog_49836_Content_31 = {
    Text = "Apakah kamu bersedia menjadi pembawa pohon, melahirkan Caro dan Jiwa pohon?"
  },
  AvgDialog_49836_Content_32 = {
    Text = [[
Karena resonansi jiwa yang ajaib, gadis itu bisa mendengar suara pohon.
Pada malam itu, dia mengetahui tentang pengetahuan terkait <Red:Hari Kiamat Hitam>.]]
  },
  AvgDialog_49836_Content_33 = {
    Text = "Hari Kiamat Hitam... apakah itu merujuk pada Pelarutan?"
  },
  AvgDialog_49836_Content_34 = {
    Text = [[
Gadis itu kembali ke sisi pohon, namun tidak lagi menjalankan perintah raja. 
 Tidak... karena panggilan darah, semua rakyat hanya akan mengikuti kehendak pohon.]]
  },
  AvgDialog_49836_Content_35 = {
    Text = "Gadis adalah pohon, dan pohon adalah gadis. Dia lebih peduli tentang apakah seluruh spesiesnya dapat melarikan diri dari takdir kehancuran bersama dengan dunia, dibandingkan dengan kelangsungan hidupnya sendiri."
  },
  AvgDialog_49836_Content_36 = {
    Text = "Ketika kekaisaran runtuh, dia membawa sekelompok orang bersembunyi di kedalaman gurun yang paling terpencil, di tengah badai yang jarang dilalui manusia, hanya untuk menghindari pembantaian dan menyelamatkan garis keturunan terakhir."
  },
  AvgDialog_49836_Content_37 = {
    Text = "Ini adalah... suku nomaden Ailan?"
  },
  AvgDialog_49836_Content_38 = {
    Text = "Setelah waktu yang sangat lama, gadis itu menghilang sekali lagi."
  },
  AvgDialog_49836_Content_39 = {
    Text = "Masih belum ada yang mendengar suaranya, dan tak seorang pun lagi yang menyebut namanya."
  },
  AvgDialog_49836_Content_4 = {
    Text = "Yang Mulia... ada apa Anda memanggil saya?"
  },
  AvgDialog_49836_Content_40 = {
    Text = "Namun, semua orang berusaha keras untuk berkembang biak guna menghindari hari kiamat sesuai dengan keinginannya…"
  },
  AvgDialog_49836_Content_41 = {
    Text = "Hanya untuk menyimpan \"benih\" kemakmuran saat kedatangan hari kiamat."
  },
  AvgDialog_49836_Content_42 = {
    Text = "Namun, darah Aran terlalu bergantung pada kekuatan Pohon Ibu yang berlimpah."
  },
  AvgDialog_49836_Content_43 = {
    Text = "Ketergantungan ini seperti menara pasir yang rapuh, tampak kokoh, namun cukup satu kali hempasan ombak untuk sepenuhnya runtuh."
  },
  AvgDialog_49836_Content_44 = {
    Text = "Mungkin kamu belum mengerti sekarang, orang Aram tidak pernah memiliki pilihan lain."
  },
  AvgDialog_49836_Content_45 = {
    Text = "Namun, kamu pasti akan bersama mereka mencapai akhir dari perjalanan ini."
  },
  AvgDialog_49836_Content_46 = {
    Text = "Kamu kehilangan kata-kata untuk sesaat."
  },
  AvgDialog_49836_Content_47 = {
    Text = "Pada saat itu... harap pastikan untuk memanggil namaku."
  },
  AvgDialog_49836_Content_48 = {
    Text = [[
Dia mencium dahimu dengan lembut. 
 Kamu tersadar sejenak, dia melangkah beberapa langkah menjauh, kamu mengulurkan tanganmu, namun tak mampu menyentuhnya.]]
  },
  AvgDialog_49836_Content_49 = {
    Text = "Kamu mengamati sosoknya yang semakin menjauh dan mengecil, hingga akhirnya sekecil butiran pasir, menghilang di bawah cahaya bulan yang terang."
  },
  AvgDialog_49836_Content_5 = {
    Text = [[
Besok adalah upacara kebangkitan Pohon Ibu, jadi aku ingin melihatmu. 
 Monster kecilku, apakah kamu sudah siap?]]
  },
  AvgDialog_49836_Content_6 = {
    Text = "Daripada bertanya apakah saya sudah siap… Bukankah Yang Mulia Ratu seharusnya lebih siap?"
  },
  AvgDialog_49836_Content_7 = {
    Text = "Atau, apakah persiapanmu sudah cukup?"
  },
  AvgDialog_49836_Content_8 = {
    Text = "Wajah pucat Ramona yang sekarat muncul di depan mata Anda, amarah di dada Anda pun semakin memuncak."
  },
  AvgDialog_49836_Content_9 = {
    Text = "Saya tidak berniat untuk memberikan kerusakan kepada kalian, apalagi melakukan sesuatu yang merugikan kepentingan bangsa Alan."
  },
  AvgDialog_49837_Content_1 = {Text = "Titik Temu"},
  AvgDialog_49837_Content_11 = {
    Text = "Bekas luka di pelipisnya, konon akibat luka bakar dari ibunya yang gila, kini tampak seperti alur dangkal yang mengalirkan cairan merah segar."
  },
  AvgDialog_49837_Content_12 = {
    Text = "Kunci Perak hancur di dada, sarung tangan standar Mythag ternoda oleh noda darah, cairan lengket yang tidak menyenangkan menetes bebas melawan gravitasi."
  },
  AvgDialog_49837_Content_13 = {
    Text = "Di balik mimpi buruk yang bergoyang itu——"
  },
  AvgDialog_49837_Content_14 = {
    Text = "Gunungan daging raksasa terbuka seperti mulut tumbuhan venus."
  },
  AvgDialog_49837_Content_15 = {
    Text = "Lipatan plasenta di kedua sisi dan bayi dengan kelainan tampak jelas seperti cap berdarah yang terpatri di benakmu."
  },
  AvgDialog_49837_Content_16 = {
    Text = "Di tengah gumpalan daging yang bengkak dan terpilin, terbaring hadiah terakhir dari perjalanannya yang terus ia telusuri dan cari, dipersembahkan kepada kalian."
  },
  AvgDialog_49837_Content_17 = {
    Text = "Itulah kebenaran dari inti Nubia——"
  },
  AvgDialog_49837_Content_18 = {
    Text = "Sebuah lampu lentera kecil."
  },
  AvgDialog_49837_Content_2 = {
    Text = "Rasa gelisah tiba-tiba muncul, ketakutan seperti palu berat yang bertubi-tubi menghantam jiwa."
  },
  AvgDialog_49837_Content_3 = {
    Text = "Kalian berlari menuju perkemahan di bawah gundukan pasir."
  },
  AvgDialog_49837_Content_4 = {
    Text = "Pada saat ujung jari menyentuh tirai, rasa takut yang luar biasa langsung menghantui dirimu."
  },
  AvgDialog_49837_Content_6 = {
    Text = "Rasa takut ini berbeda dari saat menghadapi Anjing pemburu atau melawan janin suci…"
  },
  AvgDialog_49837_Content_7 = {
    Text = "Itu adalah ketakutan yang meresap hingga ke tulang sumsum, tak terhadapi dan tak dapat diperbaiki, sulit untuk diungkapkan."
  },
  AvgDialog_49837_Content_8 = {
    Text = "Itu adalah mimpi buruk mengambang, fantasi abnormal, kenyataan yang tak tertahankan dan menyulitkan untuk bertahan."
  },
  AvgDialog_49837_Content_9 = {
    Text = "Monster raksasa dan liar mengayunkan tentakel berlendirnya, sementara tubuh kurus William bergoyang seperti alang-alang yang rapuh di antaranya."
  },
  AvgDialog_49838_Content_1 = {Text = "Titik Temu"},
  AvgDialog_49838_Content_10 = {
    Text = "Kamu menarik napas dalam-dalam, tepat saat hendak kembali ke tenda, tiba-tiba Thais melambaikan tangan padamu dari belakang tenda."
  },
  AvgDialog_49838_Content_100 = {
    Text = "Namun, kamu pasti akan bersama mereka mencapai akhir dari perjalanan ini."
  },
  AvgDialog_49838_Content_101 = {
    Text = "Kamu kehilangan kata-kata untuk sesaat."
  },
  AvgDialog_49838_Content_102 = {
    Text = "Pada saat itu... harap pastikan untuk memanggil namaku."
  },
  AvgDialog_49838_Content_103 = {
    Text = "Dia mencium dahimu dengan lembut."
  },
  AvgDialog_49838_Content_104 = {
    Text = "Kamu tersadar sejenak, dia melangkah beberapa kali, kamu mengulurkan tanganmu, namun tak bisa menyentuhnya."
  },
  AvgDialog_49838_Content_105 = {
    Text = "Kamu mengamati sosoknya yang semakin menjauh dan mengecil, hingga akhirnya sekecil butiran pasir, menghilang di bawah cahaya bulan yang terang."
  },
  AvgDialog_49838_Content_11 = {
    Text = "Besok adalah upacara kebangkitan Pohon Ibu. \n Ada apa, Yang Mulia Ratu mencari saya pada saat seperti ini…?"
  },
  AvgDialog_49838_Content_12 = {
    Text = "Begitu kata-kata keluar, kamu menyadari bahwa nada suaramu tidak ramah."
  },
  AvgDialog_49838_Content_13 = {
    Text = [[
Saya... melihatnya. 
 Mengenai temanmu... aku turut berduka.]]
  },
  AvgDialog_49838_Content_14 = {
    Text = "Keheningan yang tak terelakkan mengambang di antara kalian."
  },
  AvgDialog_49838_Content_15 = {
    Text = "Ini tidak ada hubungannya dengan Aran."
  },
  AvgDialog_49838_Content_16 = {
    Text = "Ini bukan kesalahan Thais. Kamu mengingatkan diri sendiri dalam hati, tetapi kata-kata yang terucap masih seperti landak yang waspada di padang pasir."
  },
  AvgDialog_49838_Content_17 = {
    Text = "Upacara kebangkitan Pohon Ibu... kamu pasti juga punya persiapan yang harus dilakukan, kan?"
  },
  AvgDialog_49838_Content_18 = {
    Text = "Kamu mencoba memperbaikinya, tetapi kata-kata yang terucap tetap terdengar seperti penolakan yang dingin."
  },
  AvgDialog_49838_Content_19 = {
    Text = "Menurutmu, setelah Pohon Ibu hidup kembali, ke mana Suku Alan akan pergi?"
  },
  AvgDialog_49838_Content_2 = {
    Text = [[
Dalam perjalanan ini, kamu telah menyaksikan banyak orang pergi. 
Namun, tak satu pun kematian terasa begitu menyesakkan dengan nada yang begitu ringan.]]
  },
  AvgDialog_49838_Content_20 = {
    Text = "Kamu terdiam."
  },
  AvgDialog_49838_Content_21 = {
    Text = "Saya tahu tujuan Mythag datang ke Remwasi, dan saya juga tahu mengapa kalian belum bertindak."
  },
  AvgDialog_49838_Content_22 = {
    Text = "Saya sangat berterima kasih kepada kalian karena telah memberikan Alan sebuah kesempatan."
  },
  AvgDialog_49838_Content_23 = {
    Text = "Namun, kesempatan itu sudah tidak ada lagi."
  },
  AvgDialog_49838_Content_24 = {
    Text = "Thais, apakah kamu tahu bahwa Pohon Ibu sudah tercemar oleh pelarutan?"
  },
  AvgDialog_49838_Content_26 = {
    Text = "Aku tahu, aku... sudah mengetahuinya sejak lama."
  },
  AvgDialog_49838_Content_27 = {
    Text = "Jadi, kamu seharusnya tahu bahwa Mythag tidak akan membiarkan penyebaran Pelarutan terus berlanjut."
  },
  AvgDialog_49838_Content_28 = {
    Text = [[
Aku akan menghentikan kelahiran Pohon Ibu.
Thais, kita sudah menjadi musuh.]]
  },
  AvgDialog_49838_Content_29 = {
    Text = "Angin yang awalnya segar di lautan pasir tiba-tiba berubah menjadi kental dan lengket. Debu yang terhirup seakan menggores tenggorokanmu, membuat leher terasa nyeri."
  },
  AvgDialog_49838_Content_3 = {
    Text = "Apalagi itu William —\n Penyelidik legendaris Mythag, pembimbingmu di jalan menjadi seorang Penyelidik."
  },
  AvgDialog_49838_Content_30 = {
    Text = "Yang membuatmu terkejut, Thais tidak menghindar, melainkan mendekat dan memelukmu."
  },
  AvgDialog_49838_Content_31 = {
    Text = "Anak baik, aku bisa memahami pemikiranmu."
  },
  AvgDialog_49838_Content_32 = {
    Text = "Saya tidak berniat untuk memberikan kerusakan kepada kalian, apalagi melakukan sesuatu yang merugikan kepentingan bangsa Alan."
  },
  AvgDialog_49838_Content_33 = {
    Text = "Namun, orang Aram tidak memiliki pilihan. Beberapa tahun yang lalu, kekuatan ilahi sang ratu sudah mulai melemah, bahkan menjaga Pohon Ibu pun menjadi sulit."
  },
  AvgDialog_49838_Content_34 = {
    Text = "Hanya bisa meminjam kekuatan vena bumi dari Leremwah untuk menutupi keberadaan Pohon Ibu dengan Dinding Badai."
  },
  AvgDialog_49838_Content_35 = {
    Text = "Maksudmu... Dinding Badai, dipanggil oleh kekuatan Ratu?"
  },
  AvgDialog_49838_Content_36 = {
    Text = "Ya. Dinding badai… akan menolak utusan palsu."
  },
  AvgDialog_49838_Content_37 = {
    Text = "Namun, setiap kali upacara diadakan, banyak orang Aram yang mati!"
  },
  AvgDialog_49838_Content_38 = {
    Text = "Selama kekuatan regenerasi masih ada, suku Alan tidak akan punah."
  },
  AvgDialog_49838_Content_39 = {
    Text = "Jadi, apakah kamu membiarkan mereka melakukan ritual terkutuk seperti itu, membiarkan mereka terjebak berulang kali di Dinding Badai?"
  },
  AvgDialog_49838_Content_4 = {
    Text = "Siapa yang bisa membunuh seorang Penyelidik legendaris secara diam-diam dari jarak sedekat itu?"
  },
  AvgDialog_49838_Content_40 = {
    Text = "Ini adalah takdir bangsa Aram, kami dilahirkan di sini, tumbuh di sini."
  },
  AvgDialog_49838_Content_41 = {
    Text = "Begitu banyak orang telah mengorbankan hidup mereka untuk keyakinan sakitmu ini!"
  },
  AvgDialog_49838_Content_42 = {
    Text = "Sekarang, bukan hanya orang-orang dari sukumu, tetapi juga Kak William…"
  },
  AvgDialog_49838_Content_43 = {
    Text = "Nada akhir suaramu terdengar sedikit tercekat, hampir tak bisa kau kenali sebagai suaramu sendiri."
  },
  AvgDialog_49838_Content_44 = {
    Text = "Katakan padaku, Thais, kau tidak benar-benar berpikir seperti itu, kan?"
  },
  AvgDialog_49838_Content_45 = {
    Text = "Thais tidak menjawab pertanyaanmu."
  },
  AvgDialog_49838_Content_46 = {
    Text = "Dia hanya menarik lengan bajunya lebih erat."
  },
  AvgDialog_49838_Content_47 = {
    Text = "Aku tahu kamu sangat lelah, sangat marah…"
  },
  AvgDialog_49838_Content_48 = {
    Text = [[
Kamu memiliki rasa dendam dan ketidakpahaman terhadapku. 
Namun, aku juga punya alasan tersendiri.]]
  },
  AvgDialog_49838_Content_49 = {
    Text = "Aku akan menceritakan sebuah cerita kepadamu, sebuah cerita yang sangat, sangat panjang."
  },
  AvgDialog_49838_Content_5 = {
    Text = "Kamu terhuyung lemah mundur dua langkah, lalu menabrak sebuah sosok tinggi besar."
  },
  AvgDialog_49838_Content_50 = {
    Text = "Pada zaman dahulu kala, ribuan tahun sebelum terjadinya banjir besar, ada sebuah peradaban yang memuja dewa yang disebut Pohon Ibu."
  },
  AvgDialog_49838_Content_51 = {
    Text = "Namun, kehendak Pohon Ibu tidak dapat mengokohkan pemerintahan kekaisaran, maka mereka pun merancang sebuah rencana."
  },
  AvgDialog_49838_Content_52 = {
    Text = "Mereka memilih banyak gadis, memaksa mereka meminum susu merah segar dari Pohon Ibu, dan mandi dalam cairan pohon tersebut hingga gadis-gadis itu menyatu dengan pohon."
  },
  AvgDialog_49838_Content_53 = {
    Text = "Sejak saat itu, gadis yang seperti boneka tersebut mewakili kehendak pohon."
  },
  AvgDialog_49838_Content_54 = {
    Text = "Namun, tak seorang pun pernah mendengar suaranya atau menaati perkataannya. Karena gadis itu tidak memiliki suara maupun kehendaknya sendiri. Apa yang ia sampaikan hanyalah kata-kata yang diperintahkan oleh Raja Nineveh untuk dihafal dan diucapkan kembali."
  },
  AvgDialog_49838_Content_55 = {
    Text = "Pada usia lima belas tahun, gadis itu mulai menentang dengan suaranya."
  },
  AvgDialog_49838_Content_56 = {
    Text = "Kenapa? Kenapa harus membunuhnya, dia kan ayah Ameyette!"
  },
  AvgDialog_49838_Content_57 = {
    Text = "Dia melanggar Tabu, Thais. Dia melarikan diri di medan perang."
  },
  AvgDialog_49838_Content_58 = {
    Text = "Pertempuran itu telah berakhir dengan kekalahan total, hanya dia yang selamat. Dia tidak mungkin melawan begitu banyak musuh seorang diri!"
  },
  AvgDialog_49838_Content_59 = {
    Text = "Masalah perang, kamu masih terlalu muda untuk mengerti, Thais."
  },
  AvgDialog_49838_Content_6 = {
    Text = "Saya mengerti kesulitanmu sekarang, tapi ini bukan saatnya untuk menunjukkan kelemahan."
  },
  AvgDialog_49838_Content_60 = {
    Text = "Dia harus maju tanpa ragu, lalu mati dengan penuh kehormatan."
  },
  AvgDialog_49838_Content_61 = {
    Text = "Bukankah lebih baik jika satu orang bisa bertahan hidup? Selama satu orang tetap hidup... Ameyet bisa menjadi pejuang, adik Ameyet juga bisa menjadi pejuang, begitu pula anak-anak Ameyet di masa depan..."
  },
  AvgDialog_49838_Content_62 = {
    Text = "Lagi pula, berbicara pun tidak ada gunanya."
  },
  AvgDialog_49838_Content_63 = {
    Text = "Menyampaikan kehendak Pohon Ibu, orang berdosa harus menerima hukuman dimakan serangga."
  },
  AvgDialog_49838_Content_64 = {
    Text = "Saya tidak mengatakannya!"
  },
  AvgDialog_49838_Content_65 = {
    Text = "Menyampaikan kehendak Pohon Ibu, orang berdosa harus menerima hukuman dimakan serangga."
  },
  AvgDialog_49838_Content_66 = {
    Text = "Saya tidak mengatakannya!"
  },
  AvgDialog_49838_Content_67 = {
    Text = "Menyampaikan kehendak Pohon Ibu, orang berdosa harus menerima hukuman dimakan serangga."
  },
  AvgDialog_49838_Content_68 = {
    Text = "Tangisan putus asa dan lantang seorang gadis, tak seorang pun yang mendengarnya."
  },
  AvgDialog_49838_Content_69 = {
    Text = "Kamu, siapa kamu?"
  },
  AvgDialog_49838_Content_7 = {
    Text = "Dia… meninggalkan informasi kunci untuk kita."
  },
  AvgDialog_49838_Content_70 = {
    Text = "Anak baik, pelan-pelan saja, dengarkan aku, cepat ikut aku pergi."
  },
  AvgDialog_49838_Content_71 = {
    Text = "Kamu bukan gadis pertama yang dijadikan boneka pohon. Setiap kali gadis itu melawan kehendak mereka, mereka akan melakukan pengorbanan terhadap gadis itu kepada Sungai suci."
  },
  AvgDialog_49838_Content_72 = {
    Text = "Aku dilahirkan dengan meminum susu Pohon Ibu, aku abadi!"
  },
  AvgDialog_49838_Content_73 = {
    Text = "Anak bodoh, mereka menipumu. Setiap orang yang melompat ke sungai pasti akan tenggelam."
  },
  AvgDialog_49838_Content_74 = {
    Text = "Saya tidak akan melakukannya."
  },
  AvgDialog_49838_Content_75 = {
    Text = "Pada akhirnya, siapa kamu? Aku belum pernah melihatmu sebelumnya."
  },
  AvgDialog_49838_Content_76 = {
    Text = "Saya bertugas membersihkan tamanmu dan akan pergi sebelum fajar setiap hari, jadi kamu belum pernah melihatku."
  },
  AvgDialog_49838_Content_77 = {
    Text = "Tapi kau mengenal cucuku... namanya Amayet."
  },
  AvgDialog_49838_Content_78 = {
    Text = "Apakah gadis itu sudah pergi?"
  },
  AvgDialog_49838_Content_79 = {Text = "Tidak."},
  AvgDialog_49838_Content_8 = {
    Text = [[
Di balik Nubia, ada Gereja Penerang Kuil.
Apa yang dikatakan Dafude'er memang benar, sepertinya menghentikan ritual sudah menjadi suatu keharusan.]]
  },
  AvgDialog_49838_Content_80 = {
    Text = "Gadis itu memahami banyak hal dalam sekejap. Ternyata, taman yang kotor tidak akan membersihkan dirinya sendiri, dan ternyata tidak bisa mengeluarkan suara... itu sangat menyakitkan."
  },
  AvgDialog_49838_Content_81 = {
    Text = "Dia secara sukarela melompat ke Sungai suci."
  },
  AvgDialog_49838_Content_82 = {
    Text = "Pada saat itu, kehendak gadis dan pohon tersebut beresonansi dengan mendalam."
  },
  AvgDialog_49838_Content_83 = {
    Text = "Kemudian, kehendak pohon bertanya kepadanya:"
  },
  AvgDialog_49838_Content_84 = {
    Text = "Apakah kamu bersedia menjadi pembawa pohon, melahirkan Caro dan Jiwa pohon?"
  },
  AvgDialog_49838_Content_85 = {
    Text = [[
Karena resonansi jiwa yang ajaib, gadis itu bisa mendengar suara pohon.
Pada malam itu, dia mengetahui tentang pengetahuan terkait <Red:Hari Kiamat Hitam>.]]
  },
  AvgDialog_49838_Content_86 = {
    Text = "Hari Kiamat Hitam... apakah itu merujuk pada Pelarutan?"
  },
  AvgDialog_49838_Content_87 = {
    Text = [[
Gadis itu kembali ke sisi pohon, namun tidak lagi menjalankan perintah raja. 
 Tidak... karena panggilan darah, semua rakyat hanya akan mengikuti kehendak pohon.]]
  },
  AvgDialog_49838_Content_88 = {
    Text = "Gadis adalah pohon, dan pohon adalah gadis. Dia lebih peduli tentang apakah seluruh spesiesnya dapat melarikan diri dari takdir kehancuran bersama dengan dunia, dibandingkan dengan kelangsungan hidupnya sendiri."
  },
  AvgDialog_49838_Content_89 = {
    Text = "Ketika kekaisaran runtuh, dia membawa sekelompok orang bersembunyi di kedalaman gurun yang paling terpencil, di tengah badai yang jarang dilalui manusia, hanya untuk menghindari pembantaian dan menyelamatkan garis keturunan terakhir."
  },
  AvgDialog_49838_Content_9 = {
    Text = "Di langit yang luas, bintang-bintang berkedip. Angin malam di gurun akhirnya membuat napas tersengal-sengal Anda kembali normal."
  },
  AvgDialog_49838_Content_90 = {
    Text = "Ini adalah... suku nomaden Ailan?"
  },
  AvgDialog_49838_Content_91 = {
    Text = "Setelah waktu yang sangat lama, gadis itu menghilang sekali lagi."
  },
  AvgDialog_49838_Content_92 = {
    Text = "Masih belum ada yang mendengar suaranya, dan tak seorang pun lagi yang menyebut namanya."
  },
  AvgDialog_49838_Content_93 = {
    Text = "Namun, semua orang berusaha keras untuk berkembang biak guna menghindari hari kiamat sesuai dengan keinginannya…"
  },
  AvgDialog_49838_Content_94 = {
    Text = "Hanya untuk menyimpan \"benih\" kemakmuran saat kedatangan hari kiamat."
  },
  AvgDialog_49838_Content_95 = {
    Text = "Namun, darah Aran terlalu bergantung pada kekuatan Pohon Ibu yang berlimpah."
  },
  AvgDialog_49838_Content_96 = {
    Text = "Ketergantungan ini seperti menara pasir yang rapuh, tampak kokoh, namun cukup satu kali hempasan ombak untuk sepenuhnya runtuh."
  },
  AvgDialog_49838_Content_97 = {
    Text = "Meskipun hanya ada sedikit harapan, bahkan yang paling kecil dan samar, aku tidak bisa begitu saja membiarkan mereka menyerah."
  },
  AvgDialog_49838_Content_98 = {
    Text = "Aku tidak mengerti lagi..."
  },
  AvgDialog_49838_Content_99 = {
    Text = "Agar perpisahan tidak terlalu menyedihkan, pertemuan kembali menjadi sangat berharga... Kamu tak perlu mengerti."
  },
  AvgDialog_49865_Content_1 = {
    Text = "Pohon ibu menjulang tinggi hingga ke langit, tak terjangkau."
  },
  AvgDialog_49865_Content_2 = {
    Text = "Benjolan pohon yang membengkak melahirkan jutaan keturunan, jutaan Nubia merobek rahim pohon untuk dilahirkan."
  },
  AvgDialog_49865_Content_3 = {
    Text = "Pohon Ibu… sedang menciptakan Nubia."
  },
  AvgDialog_49865_Content_4 = {
    Text = "Caro Yalan, inti lentera, anak-anakku, anak-anak yang terinfeksi kesialan…"
  },
  AvgDialog_49865_Content_5 = {
    Text = "Dia menyentuh Nubia yang lemah dengan lembut, penuh kasih sayang, seolah-olah seorang ibu yang menenangkan bayi yang tertidur."
  },
  AvgDialog_49865_Content_6 = {
    Text = "Kemudian, kepala Nubia meledak di tangannya, cipratan darah mengotori pipinya, menampilkan kesan yang mengerikan."
  },
  AvgDialog_49865_Content_7 = {
    Text = "Kembali ke induk, kembali ke Sungai Suci, masa depan kalian yang belum selesai... pasti akan berlanjut hingga akhir dunia dalam bentuk keturunan."
  },
  AvgDialog_49865_Content_8 = {
    Text = "Aku berjanji kepada kalian."
  },
  AvgDialog_49869_Content_1 = {
    Text = "Huu……huu……"
  },
  AvgDialog_49869_Content_10 = {Text = "...?"},
  AvgDialog_49869_Content_11 = {
    Text = "Miriam! Pasti dia yang merencanakan ini di belakangku, membuatku tidak bisa……tidak bisa……"
  },
  AvgDialog_49869_Content_12 = {
    Text = "……Tidak bisa apa?"
  },
  AvgDialog_49869_Content_13 = {
    Text = "Tidak bisa mengendalikan diri untuk tidak mendekatimu, dan juga ingin……"
  },
  AvgDialog_49869_Content_14 = {Text = "BRAK!"},
  AvgDialog_49869_Content_15 = {
    Text = "Detik berikutnya, piyamamu dirobek menjadi dua."
  },
  AvgDialog_49869_Content_17 = {
    Text = "<Shake:Sial, jangan bilang ini seperti yang kupikirkan……>"
  },
  AvgDialog_49869_Content_18 = {
    Text = "Ya, benar begitu! Merobek pakaianmu, lalu……"
  },
  AvgDialog_49869_Content_19 = {
    Text = "Golya mencengkeram erat pergelangan tanganmu, wajahnya yang merona hampir menempel dengan wajahmu."
  },
  AvgDialog_49869_Content_2 = {
    Text = "Lagi-lagi malam yang tenang. Kau tenggelam dalam bantal bulu yang lembut, napasmu tenang dan damai."
  },
  AvgDialog_49869_Content_20 = {
    Text = "Napas panas menerpa sisi telingamu, mewarnai wajahmu dengan semburat merah mawar."
  },
  AvgDialog_49869_Content_21 = {
    Text = "Tidak ada waktu lagi, yang terpenting sekarang adalah @2 denganku, besok kita bersama-sama menuntut balas pada wanita itu."
  },
  AvgDialog_49869_Content_22 = {
    Text = "Malam ini kau harus sedikit berkorban……bukan, ini bukan pengorbanan, ini adalah kehormatan bagimu!"
  },
  AvgDialog_49869_Content_23 = {
    Text = "@2? Tuan Golya, tolong jaga sikapmu……jangan mendekat!"
  },
  AvgDialog_49869_Content_24 = {
    Text = "<Big:Ramona! Dor! Cepat selamatkan aku——!!>"
  },
  AvgDialog_49869_Content_4 = {Text = "Waaaaa!!!"},
  AvgDialog_49869_Content_5 = {
    Text = "Pedang besar yang berat membelah tempat tidur kecilmu menjadi dua. Kau terduduk di lantai, rasa kantukmu lenyap sepenuhnya."
  },
  AvgDialog_49869_Content_6 = {
    Text = "Apa yang terjadi?! Apakah Asosiasi Pematung menyerang lagi?!"
  },
  AvgDialog_49869_Content_7 = {
    Text = "Dari kegelapan terdengar suara napas yang gemetar, sosok tinggi besar berdiri tegak di sisi ranjang yang hancur."
  },
  AvgDialog_49869_Content_8 = {
    Text = "Begitu kuat, begitu asing……kekuatan yang meluap-luap ini……"
  },
  AvgDialog_49869_Content_9 = {
    Text = "Penjaga Rahasia, sepertinya aku diracuni oleh wanita gila itu."
  },
  AvgDialog_49870_Content_1 = {
    Text = "Badai di luar tidak mampu mengganggu mimpi yang tenang, dalam kegelapan, hanya suara napasmu yang damai yang bergema."
  },
  AvgDialog_49870_Content_10 = {
    Text = "Luar biasa… Luar biasa! Seperti inilah seharusnya!"
  },
  AvgDialog_49870_Content_11 = {
    Text = "Alat dengan kekerasan yang pas, tidak akan merobek kulitku. Kekuatan yang tepat, tidak akan meninggalkan bekas yang memalukan… Menakjubkan, pukulan Anda sungguh menakjubkan."
  },
  AvgDialog_49870_Content_12 = {
    Text = "Pujian Leya kepadamu hampir seperti sebuah aria, dia sama sekali tidak menyadari setetes darah mengalir turun dari garis rambutnya."
  },
  AvgDialog_49870_Content_13 = {
    Text = "…Biar kuobati lukamu dulu."
  },
  AvgDialog_49870_Content_14 = {
    Text = "Luka Nona Leya tidak serius, sebentar lagi lukanya akan sembuh dengan sendirinya."
  },
  AvgDialog_49870_Content_15 = {
    Text = "Tapi aku sangat ingin…"
  },
  AvgDialog_49870_Content_16 = {
    Text = "…Biarkan dia mengonsumsi darah dalam jumlah yang cukup."
  },
  AvgDialog_49870_Content_17 = {
    Text = "Benarkah? Bolehkah? Anda sungguh orang yang baik hati—"
  },
  AvgDialog_49870_Content_18 = {
    Text = "Dengan cara injeksi transfusi darah, jangan memanjakannya."
  },
  AvgDialog_49870_Content_19 = {
    Text = "Meskipun mendapatkan darah kesukaannya, Leya yang terikat di ranjang rumah sakit oleh jarum infus dan kantong darah tetap terlihat lesu, seperti bunga dahlia yang sedang layu."
  },
  AvgDialog_49870_Content_2 = {
    Text = "Sedetik sebelum guntur menggelegar, kilat pucat lebih dulu menembus malam, menyinari bayangan di dekat jendela."
  },
  AvgDialog_49870_Content_20 = {
    Text = "Tidak tahan melihat matanya yang penuh keluh kesah, akhirnya kau tidak bisa menahan diri untuk bertanya."
  },
  AvgDialog_49870_Content_21 = {
    Text = "Kenapa kau menerobos masuk ke kamarku malam ini?"
  },
  AvgDialog_49870_Content_22 = {
    Text = "…Aku… ingin…"
  },
  AvgDialog_49870_Content_23 = {
    Text = "Leya tiba-tiba bangkit, jarum infus terlempar keluar, darah dari kantong darah dan darahnya sendiri terciprat ke seluruh tubuhnya."
  },
  AvgDialog_49870_Content_24 = {
    Text = "Dia membenamkan kepalanya di lekuk lehermu, hembusan napasnya yang dingin membuatmu tak bisa menahan diri untuk bergidik."
  },
  AvgDialog_49870_Content_25 = {
    Text = "Ingin darah Penjaga Rahasia… Ingin darahmu."
  },
  AvgDialog_49870_Content_3 = {
    Text = "Bayangan itu muncul tiba-tiba, bergerak perlahan dalam kegelapan kamar tidur. Tepat saat ia membawa hawa dingin dan bau amis mendekati sisi tempat tidurmu, membuat bantalmu menjadi dingin dan lembap—"
  },
  AvgDialog_49870_Content_4 = {
    Text = "——BRAK!"
  },
  AvgDialog_49870_Content_5 = {
    Text = "Kau menyambar lampu meja dan menghantamkannya keras-keras ke kepala si penyusup."
  },
  AvgDialog_49870_Content_6 = {
    Text = "Ugh……uhmm……"
  },
  AvgDialog_49870_Content_7 = {Text = "Leya?!"},
  AvgDialog_49870_Content_8 = {
    Text = "Apa yang kau lakukan di kamarku?"
  },
  AvgDialog_49870_Content_9 = {Text = "Aku..."},
  AvgDialog_49871_Content_1 = {
    Text = "Penjaga, kamu seharusnya sudah memperhatikan keanehan di kampus belakangan ini."
  },
  AvgDialog_49871_Content_2 = {
    Text = "Saya sedang sibuk menyelesaikan laporan tentang Acara Lemuwah, jadi tidak terlalu memperhatikan hal-hal lain…"
  },
  AvgDialog_49871_Content_3 = {
    Text = "Namun, setelah Wakil Dekan menyebutkannya, memang benar ada banyak Pembangun yang berkumpul di ruang medis akhir-akhir ini… Apakah ada sesuatu yang terjadi?"
  },
  AvgDialog_49871_Content_4 = {
    Text = "Akibat <Yellow:Acara Lermuahi>, hampir semua Pembangun mengalami kecenderungan emosional yang abnormal."
  },
  AvgDialog_49871_Content_5 = {
    Text = "Sepertinya isi yang harus ditulis dalam laporan semakin bertambah... Apakah ada yang bisa aku bantu?"
  },
  AvgDialog_49871_Content_6 = {
    Text = "Sebagian besar Pembangun telah terpengaruh secara abnormal, bahkan Boneka pun tidak luput. Para peneliti sedang mencari cara untuk menenangkan semua orang."
  },
  AvgDialog_49871_Content_7 = {
    Text = "Sebelum dampaknya benar-benar mereda, jangan lengah terhadap Pembangun. Mereka mungkin menjadi sumber <Red:bahaya>."
  },
  AvgDialog_49880_Content_1 = {
    Text = "Sarung tangan baja bergerak di antara pipi dan leher, ujung tajam sarung tangan itu akhirnya membuka kait seragam sekolah, dan bantalan jari menekan tulang selangka yang terekspos."
  },
  AvgDialog_49880_Content_10 = {
    Text = "Wanda dengan kasar menarik lepas kain penutup matamu. Ia menyipitkan mata, sebuah tekanan aneh yang berbeda dari kebrutalannya mengalir di sekujur tubuhnya."
  },
  AvgDialog_49880_Content_11 = {
    Text = "Duri tulang belakang menggesek melewati tulang selangka, kulit tersayat oleh duri tulang yang kasar dan tajam. Wanda memejamkan mata, menghirup aroma darah yang menyebar di udara, ekspresinya penuh kepuasan."
  },
  AvgDialog_49880_Content_12 = {
    Text = "Tak lama setelah aku membunuh raja permaisuri keempat, kerajaanku di planet ini pun menghadapi kehancuran."
  },
  AvgDialog_49880_Content_13 = {
    Text = "Kalau dipikir-pikir, sudah sangat lama… sangat lama aku tidak bertemu dengan orang baru."
  },
  AvgDialog_49880_Content_14 = {
    Text = "Duri tulang belakang terangkat tinggi, cairan kental mengumpul di ujungnya, begitu dekat dengan luka terbuka di tubuhmu."
  },
  AvgDialog_49880_Content_15 = {
    Text = "Sekarang adalah waktu yang tepat, menurutmu bagaimana?"
  },
  AvgDialog_49880_Content_16 = {
    Text = "Jauh dari kekacauan dan wabah penyakit, tanpa kekhawatiran, tanpa tanggung jawab…… hanya orang-orang yang bisa dipercaya di sisimu. Ini benar-benar era terbaik!"
  },
  AvgDialog_49880_Content_17 = {
    Text = "Wanda, apakah itu benar-benar yang kaupikirkan?"
  },
  AvgDialog_49880_Content_18 = {
    Text = "Apa maksudmu?"
  },
  AvgDialog_49880_Content_19 = {
    Text = "Tanpa kekhawatiran, tanpa tanggung jawab……"
  },
  AvgDialog_49880_Content_2 = {
    Text = "Kau adalah… kau Awakened, kan?"
  },
  AvgDialog_49880_Content_20 = {
    Text = "Dirimu yang memilih untuk berakhir bersama Cambrian, tidak pernah menganggap tanggung jawab sebagai beban."
  },
  AvgDialog_49880_Content_21 = {
    Text = "Bagaimana kau bisa tahu tentang Cambrian—"
  },
  AvgDialog_49880_Content_22 = {
    Text = "Sang Ratu dari bintang asing, sebelum menjadikanku raja permaisuri yang baru, tolong rasakan baik-baik isi hatimu sendiri."
  },
  AvgDialog_49880_Content_23 = {
    Text = "Pengaruh Sungai Suci Lemvahi tidak akan mengubahmu menjadi sosok yang lain."
  },
  AvgDialog_49880_Content_25 = {
    Text = "Kau benar, peliharaan kecil."
  },
  AvgDialog_49880_Content_26 = {
    Text = "Suasana menggoda itu lenyap seketika, duri-duri punggungnya menyusut bak garis pantai saat air surut, berayun-ayun tak menentu di belakang Wanda."
  },
  AvgDialog_49880_Content_27 = {
    Text = "Ayo pergi, malam ini belum saatnya."
  },
  AvgDialog_49880_Content_28 = {
    Text = "Belum saatnya?"
  },
  AvgDialog_49880_Content_29 = {
    Text = "Para pelayan abadi bergegas mengerumuni dan mendorongmu menjauh, sementara Wanda mengeluarkan dengusan puas."
  },
  AvgDialog_49880_Content_3 = {
    Text = "Pandangan terhalang oleh kain sutra hitam, indra tubuh diperkuat hingga batasnya oleh kegelapan. Suara baju zirah yang bergesekan di atas kulit menyatu dengan deru napas, menimbulkan getaran yang berasal dari kedalaman jiwa."
  },
  AvgDialog_49880_Content_30 = {
    Text = "Sang Ratu tidak akan kehilangan akal sehatnya, dan tidak akan menarik kembali kata-katanya. Hanya saja, menjadikanmu penerusku yang berikutnya memang masih terlalu dini."
  },
  AvgDialog_49880_Content_31 = {
    Text = "Pergilah, peliharaan kecil. Tapi bersiaplah — saat waktunya tiba, aku akan memanggilmu kembali."
  },
  AvgDialog_49880_Content_4 = {
    Text = "Hei? Kau bisa mengerti ucapanku?"
  },
  AvgDialog_49880_Content_5 = {
    Text = "Tawa pelan terdengar dari atas kepalamu. Saat kau masih berusaha mencari tahu siapa pemilik tawa itu, sebuah duri tulang belakang sudah melingkari pinggangmu."
  },
  AvgDialog_49880_Content_6 = {
    Text = "Ia bagaikan ular piton raksasa yang tak bisa ditebak emosinya — saat marah, duri tulangnya akan menembus tubuhmu tanpa ampun, namun terkadang ia hanya bermalas-malasan menggantung di bahumu."
  },
  AvgDialog_49880_Content_7 = {
    Text = "Saat ini ia meluncur melewati tubuhmu, ujungnya menempel di tulang tenggorokanmu, seperti hewan yang bermanja meminta kasih sayang, sekaligus seperti pisau tajam yang berbahaya."
  },
  AvgDialog_49880_Content_8 = {
    Text = "Wanda…… itu kau, kan!"
  },
  AvgDialog_49880_Content_9 = {
    Text = "Hmph… ternyata selambat ini baru mengenali tuanmu, kau benar-benar peliharaan kecil yang tidak becus."
  },
  AvgDialog_50760_Content_1 = {
    Text = "Kau terpaku menatap tumpukan mayat hitam kental di hadapanmu. Rekan-rekan yang baru saja berjuang bersamamu kini terbaring di sini, selamanya tertinggal di gletser yang tertutup salju abadi ini."
  },
  AvgDialog_50760_Content_10 = {
    Text = "Kalian mendongak. Bagaikan awan hitam yang menutupi matahari, bayangan raksasa muncul dari sisi tebing, melayang di atas kalian."
  },
  AvgDialog_50760_Content_11 = {
    Text = "Di tubuh monster raksasa itu, terukir sebuah lambang besar—dalam mimpi, kau pernah melihatnya."
  },
  AvgDialog_50760_Content_12 = {
    Text = "Itu… Gereja Lentera!!!"
  },
  AvgDialog_50760_Content_13 = {Text = "BLARR!!!"},
  AvgDialog_50760_Content_14 = {
    Text = "<Shake:AAHH——>"
  },
  AvgDialog_50760_Content_15 = {
    Text = "Kak{Male=Tuan Penjaga Rahasia,Female=Nona Penjaga Rahasia}!!!"
  },
  AvgDialog_50760_Content_16 = {
    Text = "Benda raksasa yang melayang di udara menghantam ke bawah dengan brutal. Disertai dentuman dahsyat yang membelah puncak, menghancurkan batu di bawah kaki kalian menjadi berkeping-keping."
  },
  AvgDialog_50760_Content_17 = {
    Text = "Kakimu menginjak kekosongan, dan kau jatuh ke lembah dalam bersama Hilo."
  },
  AvgDialog_50760_Content_18 = {
    Text = "——Di tengah teriakan kalian yang penuh ketakutan, Hilo menyeringai lebar, untuk pertama kalinya tertawa terbahak-bahak."
  },
  AvgDialog_50760_Content_2 = {Text = "Hoek——"},
  AvgDialog_50760_Content_3 = {
    Text = "Penjelajah yang tewas di gunung bersalju tak terhitung jumlahnya, tetapi kematian yang begitu mengenaskan dengan korban sebanyak ini, bagi sang pemandu ini adalah yang pertama kalinya."
  },
  AvgDialog_50760_Content_4 = {
    Text = "Dia tak sanggup lagi bertahan, bahunya gemetar, muntah-muntah tanpa henti."
  },
  AvgDialog_50760_Content_5 = {
    Text = "Mereka juga terkena Erosi… Erosi di sini, ternyata berkembang secepat ini…"
  },
  AvgDialog_50760_Content_6 = {
    Text = "Monster-monster yang melarikan diri itu, dan reaksi para anggota tim ini, semuanya terlalu tidak normal…"
  },
  AvgDialog_50760_Content_7 = {
    Text = "Hanya tersisa kita, harus segera turun gunung, kalau tidak…"
  },
  AvgDialog_50760_Content_8 = {
    Text = "BLARR——"
  },
  AvgDialog_50760_Content_9 = {
    Text = "Kata-katanya belum selesai, tiba-tiba pandangannya menggelap."
  },
  AvgDialog_50761_Content_1 = {
    Text = "Gletser kembali mengeluarkan raungan bagaikan murka, mulai bergeser perlahan-lahan."
  },
  AvgDialog_50761_Content_10 = {
    Text = "Pergi... Kita tidak pernah punya hak untuk pergi."
  },
  AvgDialog_50761_Content_11 = {
    Text = "Obsesi dan kegilaan di mata \"Shilo\" yang lain tiba-tiba lenyap."
  },
  AvgDialog_50761_Content_12 = {
    Text = "Dia menatap Shilo, dengan sorot mata yang tenang dan jernih seperti belum pernah sebelumnya."
  },
  AvgDialog_50761_Content_13 = {
    Text = "Hal-hal yang pernah menyakitimu, kebencian yang menusuk tulang itu, apa kau sudah melupakannya, \"Shilo\"?"
  },
  AvgDialog_50761_Content_14 = {
    Text = "Aku tidak pernah melupakannya... Aku hanya..."
  },
  AvgDialog_50761_Content_15 = {
    Text = "Kau sedang kebingungan, \"Shilo\"."
  },
  AvgDialog_50761_Content_16 = {
    Text = "Hanya kekuatan yang cukup besar yang bisa menyelesaikan pembalasan dendam kita. Balas dendam, adalah satu-satunya makna keberadaan kita."
  },
  AvgDialog_50761_Content_17 = {
    Text = "Balas dendam... kepada siapa?"
  },
  AvgDialog_50761_Content_18 = {Text = "Takdir."},
  AvgDialog_50761_Content_19 = {
    Text = "Dua kata yang tenang itu membuat tubuh Shilo gemetar hebat."
  },
  AvgDialog_50761_Content_2 = {
    Text = "Kali ini, danau es yang telah lama tersembunyi akhirnya menampakkan wujud aslinya, kalian dapat melihat sosok kurus yang dipenuhi bisul hitam di atas danau es itu."
  },
  AvgDialog_50761_Content_20 = {
    Text = "Di mana pun kita berada, gunung ini akan memanggil kita, menelan kita."
  },
  AvgDialog_50761_Content_21 = {
    Text = "Ini adalah takdir kita, sama seperti hal-hal kotor yang pernah kita alami..."
  },
  AvgDialog_50761_Content_22 = {
    Text = "Kau sudah lama tahu jawabannya, tapi memilih untuk mengabaikannya. Bukan begitu?"
  },
  AvgDialog_50761_Content_23 = {
    Text = "Dibandingkan orang-orang dan hal-hal yang membuatmu membenci, takdir, adalah lawan yang begitu mengerikan..."
  },
  AvgDialog_50761_Content_24 = {
    Text = "Orang pengecut sepertimu, tidak layak disebut pejuang."
  },
  AvgDialog_50761_Content_25 = {
    Text = "Tubuhmu sudah tidak bisa bertahan lagi... kau akan mati di sini."
  },
  AvgDialog_50761_Content_26 = {
    Text = "Meskipun begitu... lalu kenapa?"
  },
  AvgDialog_50761_Content_27 = {
    Text = "Dia memalingkan wajahnya ke arah kalian dan menyeringai, memperlihatkan sepasang taring yang licik."
  },
  AvgDialog_50761_Content_28 = {
    Text = "Pembawa Lentera menipuku untuk datang ke sini, ingin memanfaatkanku untuk membangkitkan @3. Gunung ini memanggilku, ingin menelanku. Aku sudah tahu sejak awal, tapi aku tetap datang."
  },
  AvgDialog_50761_Content_29 = {
    Text = "Gunung ingin menemuiku, maka aku datang menemui-Nya."
  },
  AvgDialog_50761_Content_3 = {
    Text = "Retakan di danau es semakin besar, bagaikan luka panjang yang membentang di permukaan danau di bawah gletser yang membentang luas."
  },
  AvgDialog_50761_Content_30 = {
    Text = "Aku harus berterima kasih kepada Pembawa Lentera, yang memberiku kesempatan untuk menghadapi-Nya secara langsung……"
  },
  AvgDialog_50761_Content_31 = {
    Text = "Kau begitu pengecut, tapi kau juga datang, bukan?"
  },
  AvgDialog_50761_Content_32 = {
    Text = "Aku adalah masa depanmu, \"Shilo\". Ketika kau memiliki keberanian untuk mengangkat pedang di tanganmu melawan takdir, kau akan menjadi diriku."
  },
  AvgDialog_50761_Content_33 = {
    Text = "Bisul-bisul hitam semakin menumpuk, bagaikan sekumpulan makhluk purba yang kelaparan, dengan rakus menerjang tubuhnya, merayap naik ke pipinya."
  },
  AvgDialog_50761_Content_34 = {
    Text = "Dia tertawa, bagaikan binatang buas yang rakus merobek daging mentah, bagaikan seorang raja yang akan naik takhta."
  },
  AvgDialog_50761_Content_35 = {
    Text = "Lihatlah, \"Shilo\"…… Aku akan menelan-Nya, aku akan menjadi kuat, segala takdir tidak akan bisa menghalangiku lagi!"
  },
  AvgDialog_50761_Content_36 = {
    Text = "Tidak akan ada lagi belenggu…… tidak akan…… ada lagi pengkhianatan……"
  },
  AvgDialog_50761_Content_37 = {
    Text = "Bisul-bisul hitam terus menyebar dan menumpuk di tubuhnya, menembus tubuhnya yang sudah tak sanggup menanggung lagi, menutupi wajahnya yang tenang sekaligus gila……"
  },
  AvgDialog_50761_Content_38 = {
    Text = "Aku akan…… <Big:Membalas dendam!!!>"
  },
  AvgDialog_50761_Content_39 = {Text = "BRAK—"},
  AvgDialog_50761_Content_4 = {
    Text = "Bisul-bisul hitam terus bermunculan tanpa henti, menutupi tubuh \"Shilo\" yang lain."
  },
  AvgDialog_50761_Content_40 = {
    Text = "Bagaikan sebuah bisul yang ditusuk pecah, cairan hitam dan merah terciprat ke segala arah."
  },
  AvgDialog_50761_Content_41 = {
    Text = [[
Raungan terakhir sang binatang buas masih bergema di lembah yang kosong.
Di tempat dia berdiri tadi, selain genangan cairan, tidak ada apa pun.]]
  },
  AvgDialog_50761_Content_42 = {
    Text = "\"Membalas dendam\"…… ya……"
  },
  AvgDialog_50761_Content_43 = {
    Text = "Shilo mengangkat kepalanya dengan agak linglung, memandang langit yang kelabu pucat."
  },
  AvgDialog_50761_Content_44 = {
    Text = "Butiran salju kasar menggelinding melewati kulitnya, meleleh menjadi setitik noda air."
  },
  AvgDialog_50761_Content_45 = {
    Text = "Dia…… ditelan oleh gunung?"
  },
  AvgDialog_50761_Content_47 = {
    Text = "Tanpa menunggu Shilo berbicara, pertanyaanmu sudah mendapat jawaban——"
  },
  AvgDialog_50761_Content_48 = {
    Text = "Gunung di bawah kaki mulai bergetar. Dari kedalaman pegunungan, terdengar sebuah panggilan rendah yang najis……"
  },
  AvgDialog_50761_Content_5 = {
    Text = "Aku merasakannya…… Lebih banyak, berikan aku lebih banyak!"
  },
  AvgDialog_50761_Content_6 = {
    Text = "Bisul-bisul aneh ini merasakan panggilannya, berdengung dengan penuh semangat, berebutan memasuki mulutnya, dengan sukarela menyerahkan diri untuk ditelannya."
  },
  AvgDialog_50761_Content_7 = {
    Text = "Mereka tampak menikmati dicincang, memuja ditelan, dan mendambakan dimakan hingga habis."
  },
  AvgDialog_50761_Content_8 = {
    Text = "Kalian tiba di hadapan \"Shilo\" yang lain. Tubuhnya terendam dalam bisul hitam pekat, sosoknya sudah begitu samar bagaikan kabut tipis yang bisa buyar dengan mudah."
  },
  AvgDialog_50761_Content_9 = {
    Text = "Pergi dari sini sekarang, masih ada kesempatan..."
  },
  AvgDialog_50762_Content_1 = {
    Text = "Tidak ada waktu untuk berpikir. Naluri bertahan hidup mendorong kalian merangkak dengan tangan dan kaki melalui lendir yang disekresikan gua, menuju mulut gua yang perlahan menyempit."
  },
  AvgDialog_50762_Content_10 = {
    Text = "Debu bercampur butiran salju menyebar di depan matamu."
  },
  AvgDialog_50762_Content_11 = {
    Text = "Lorong yang gelap gulita dibelah paksa, membuka sebuah retakan. Cahaya putih terang menyinari bahumu."
  },
  AvgDialog_50762_Content_12 = {
    Text = "Pegangan yang erat, aku akan membawa kalian keluar."
  },
  AvgDialog_50762_Content_13 = {
    Text = "Dia menghancurkan bongkahan batu gua dan menarik kalian keluar dari tumpukan reruntuhan."
  },
  AvgDialog_50762_Content_14 = {
    Text = "Utang budi padamu, sekarang kulunas……"
  },
  AvgDialog_50762_Content_15 = {
    Text = "……Aah!!"
  },
  AvgDialog_50762_Content_16 = {
    Text = "Shilo!!……"
  },
  AvgDialog_50762_Content_17 = {
    Text = "Belum selesai bicara, kakinya tiba-tiba menginjak kekosongan."
  },
  AvgDialog_50762_Content_18 = {
    Text = "——Tanah yang dalam ingatan seharusnya berupa lereng bukit lenyap begitu saja, dalam sekejap berubah menjadi jurang tak berdasar."
  },
  AvgDialog_50762_Content_2 = {
    Text = "Hampir sampai, tepat di depan sana—"
  },
  AvgDialog_50762_Content_3 = {
    Text = "<Big:BLARR—>"
  },
  AvgDialog_50762_Content_4 = {
    Text = "Seluruh gunung berguncang dahsyat, sudut lorong berubah drastis, miring tajam ke bawah."
  },
  AvgDialog_50762_Content_5 = {
    Text = "Lendir di bawah tubuh begitu licin, kalian dengan susah payah mendekati mulut gua yang bercahaya, tapi gerakan peristaltik lorong semakin hebat."
  },
  AvgDialog_50762_Content_6 = {
    Text = "Lempengan batu yang hangat terus menyusut, menekan rongga dadamu. Kau merasa udara semakin menipis. Bahkan tubuh Lily pun terjepit di celah batu, tak bisa bergerak."
  },
  AvgDialog_50762_Content_7 = {
    Text = "Satu-satunya jalan keluar perlahan ditelan oleh bongkahan batu hitam. Jalan yang begitu dekat terputus, dan pandanganmu tenggelam dalam kegelapan tanpa harapan."
  },
  AvgDialog_50762_Content_8 = {
    Text = "Tidak boleh… di sini…"
  },
  AvgDialog_50762_Content_9 = {Text = "DUARR—"},
  AvgDialog_50763_Content_1 = {
    Text = "Shilo berjongkok, meniru caramu, dengan canggung mengelus puncak kepala Lily yang lembut."
  },
  AvgDialog_50763_Content_10 = {
    Text = "Dia menancapkan pedangnya ke batu karang. Helai rambut basahnya terjuntai di depan wajah, dengan cepat membeku menjadi beberapa untai es, bergoyang-goyang mengikuti bahunya yang gemetar."
  },
  AvgDialog_50763_Content_11 = {
    Text = "Angin dingin pegunungan bersalju terus mengamuk, suara gemuruh yang berat terdengar berturut-turut."
  },
  AvgDialog_50763_Content_12 = {
    Text = "Rasa sakit yang luar biasa menyerangnya bergelombang, tetapi saat ini, suara di dalam kepalanya terdengar sangat jelas."
  },
  AvgDialog_50763_Content_13 = {
    Text = "Ada banyak hal yang tidak ingin kulakukan, banyak… hal yang kupaksa dan didorong untuk kulakukan."
  },
  AvgDialog_50763_Content_14 = {
    Text = "<Change>Serahkan… dia… padaku!"
  },
  AvgDialog_50763_Content_15 = {
    Text = "Bahkan kemampuan berkomunikasi pun sudah hilang?"
  },
  AvgDialog_50763_Content_16 = {
    Text = [[
Kalau begitu, titipkanlah kata-kata dan perasaanmu pada pedang.
Biarkan pertarungan membuatku mendengar kemarahanmu!]]
  },
  AvgDialog_50763_Content_17 = {
    Text = "Aku pernah dikhianati berkali-kali… berkali-kali."
  },
  AvgDialog_50763_Content_18 = {
    Text = "Kenapa? Kenapa? Aku ingin bertemu Nyonya!"
  },
  AvgDialog_50763_Content_19 = {
    Text = "Jangan bermimpi, masih menganggap dirimu putri angkat Penguasa yang terhormat?"
  },
  AvgDialog_50763_Content_2 = {
    Text = "Setengah tubuh Lily sudah terbenam ke dalam badan gunung. Dalam keadaan tak terkendali, ia meneteskan air mata hitam pekat, menatap Shilo dengan pandangan kosong."
  },
  AvgDialog_50763_Content_20 = {
    Text = "Darah yang kotor, pada akhirnya hanya bisa membesarkan <Blue:pengkhianat> sepertimu."
  },
  AvgDialog_50763_Content_21 = {
    Text = [[
<BigShake:Jawab aku!>
Apakah aku sudah dibuang?!]]
  },
  AvgDialog_50763_Content_22 = {
    Text = "Dari hasilnya memang begitu, tapi…"
  },
  AvgDialog_50763_Content_23 = {
    Text = "Tangannya yang gemetar sudah tak mampu lagi menggenggam gagang pedang. Pedang panjangnya berbenturan dengan getaran batu karang, menghasilkan dengungan logam."
  },
  AvgDialog_50763_Content_24 = {
    Text = "Dulu aku mengira, balas dendam adalah segalanya bagiku… tapi baru hari ini aku menyadari, aku salah memahami maknanya, dan juga salah mencari lawan."
  },
  AvgDialog_50763_Content_25 = {
    Text = "Hanya kekuatan yang cukup besar yang bisa menyelesaikan pembalasan dendam kita. Balas dendam, adalah satu-satunya makna keberadaan kita."
  },
  AvgDialog_50763_Content_26 = {
    Text = "Gunung ingin menemuiku, maka aku datang menemui-Nya."
  },
  AvgDialog_50763_Content_27 = {
    Text = "Aku adalah masa depanmu, \"Shilo\". Ketika kau memiliki keberanian untuk mengangkat pedang di tanganmu melawan takdir, kau akan menjadi diriku."
  },
  AvgDialog_50763_Content_28 = {
    Text = [[
Jadi kau ingin membalas dendam pada para pengkhianat, ingin melindungi Francis yang menyelamatkanmu.
Tapi pertarungan bukanlah hal seperti itu.]]
  },
  AvgDialog_50763_Content_29 = {
    Text = [[
Bukan demi melindungi, bukan demi balas dendam, bukan demi mencari jawaban.
Pertarungan hanyalah pertarungan, tidak lebih.]]
  },
  AvgDialog_50763_Content_3 = {
    Text = "Dia sudah menanggung terlalu banyak penderitaan. Biarkan aku yang melakukannya."
  },
  AvgDialog_50763_Content_30 = {
    Text = "Duniamu terlalu sempit, makanya kau selalu seperti ngengat yang terpaku pada secercah cahaya kecil yang dinyalakan orang lain."
  },
  AvgDialog_50763_Content_31 = {
    Text = "Jika ada kesempatan, pergilah melihat dunia yang lebih luas."
  },
  AvgDialog_50763_Content_32 = {
    Text = "Lepaskan! Kau tidak akan bertahan lama."
  },
  AvgDialog_50763_Content_33 = {
    Text = "Aku……tidak akan……"
  },
  AvgDialog_50763_Content_34 = {
    Text = "Lepaskan……kalau begini terus kau juga akan mati!"
  },
  AvgDialog_50763_Content_35 = {
    Text = "Aku tidak akan meninggalkan rekan manapun……tidak akan pernah!"
  },
  AvgDialog_50763_Content_38 = {
    Text = "Rotan berkata, pertarungan hanyalah pertarungan, bukan demi melindungi, dan bukan pula demi balas dendam."
  },
  AvgDialog_50763_Content_39 = {
    Text = "Aku sudah lama memikirkannya, dan akhirnya mengerti, mengapa kau dan Tubuh Kebangkitanmu bisa sekuat itu..."
  },
  AvgDialog_50763_Content_4 = {
    Text = "Tidak……tidak boleh, seharusnya bukan hasil seperti ini……Pasti ada cara lain……"
  },
  AvgDialog_50763_Content_40 = {
    Text = "Kurasa, Rotan salah. Mungkin, bahkan dia sendiri pun tidak menyadarinya."
  },
  AvgDialog_50763_Content_41 = {
    Text = "Baik Rotan, Lily, maupun kau... kalian semua memiliki sesuatu yang ingin dilindungi."
  },
  AvgDialog_50763_Content_42 = {
    Text = "Melindungi, itulah takdir yang seharusnya kumiliki."
  },
  AvgDialog_50763_Content_43 = {
    Text = "Kebenaran ini, kaulah yang mengajarkannya padaku, Penjaga Rahasia."
  },
  AvgDialog_50763_Content_44 = {Text = "\"BRAKK—\""},
  AvgDialog_50763_Content_45 = {
    Text = "Gunung kembali berguncang hebat, lapisan es tebal di atas danau es retak berkeping-keping."
  },
  AvgDialog_50763_Content_46 = {
    Text = "Di bawah pecahan yang hancur, bisul-bisul hitam menggelembung liar, mendidih bagai kuah panas, terus menyebar ke segala arah."
  },
  AvgDialog_50763_Content_47 = {
    Text = "Shilo, aku tidak akan meninggalkan rekan seperjuanganku!"
  },
  AvgDialog_50763_Content_48 = {
    Text = "Aku tidak suka berutang budi. Kau menyelamatkanku, setelah hari ini, kita impas."
  },
  AvgDialog_50763_Content_49 = {
    Text = "Aku bisa merasakan aura \"Shilo\" yang lain... Dia menungguku di dalam gunung. Dia ingin bersama-sama denganku membalas dendam pada takdir."
  },
  AvgDialog_50763_Content_5 = {
    Text = "Tidak ada waktu lagi, Penjaga Rahasia."
  },
  AvgDialog_50763_Content_50 = {
    Text = "Kau tidak meninggalkan siapa pun. Jalan selanjutnya, biarkan kami yang melangkah sendiri."
  },
  AvgDialog_50763_Content_51 = {
    Text = "Kami adalah pejuang. Pejuang terlahir untuk bertempur."
  },
  AvgDialog_50763_Content_52 = {
    Text = "Ini adalah tempat kembali yang kami pilih sendiri... Ini adalah pertempuran antara kami dan gunung."
  },
  AvgDialog_50763_Content_53 = {
    Text = "Shilo mencabut Duri Hitam."
  },
  AvgDialog_50763_Content_54 = {
    Text = "Awan tebal menumpuk di atas gunung bersalju, tanpa setitik pun sinar matahari yang jatuh."
  },
  AvgDialog_50763_Content_55 = {
    Text = "Seluruh tubuh Shilo dibelit dan dibelenggu oleh cairan hitam pekat, kegilaan tanpa kesadaran menjelma menjadi rantai besi kokoh, mengikatnya di bawah belenggu berlapis-lapis."
  },
  AvgDialog_50763_Content_58 = {
    Text = "Bahu kurusnya memikul rantai, melangkah sendirian ke depan. Tubuhnya diikat oleh belenggu berat, napasnya semakin sesak, hingga ia berlutut jatuh di atas salju."
  },
  AvgDialog_50763_Content_59 = {Text = "Shilo..."},
  AvgDialog_50763_Content_6 = {
    Text = "Jika ingin kalian semua keluar dari Elworth dengan selamat, jika tidak ingin berubah menjadi monster di hadapanmu lagi, hanya ini satu-satunya cara……"
  },
  AvgDialog_50763_Content_60 = {
    Text = "Igauan terlarang tanpa henti mengalir masuk ke telinga, di antara suara kental dan gelap itu, Shilo mendengar resonansi antara puncak gunung dan detak jantungnya."
  },
  AvgDialog_50763_Content_61 = {
    Text = "Dung, dung, dung..."
  },
  AvgDialog_50763_Content_62 = {
    Text = "Di bawah lapisan batu keras dan tanah beku, makhluk raksasa yang terbangun mendengung dengan tak sabar, mendambakan kehadirannya."
  },
  AvgDialog_50763_Content_63 = {
    Text = "Dia berdiri di puncak gunung."
  },
  AvgDialog_50763_Content_64 = {
    Text = "Puncak gunung yang kacau bergejolak dengan penuh semangat, bumi bergetar hebat, angin dingin yang ganas merobek-robek pakaian tipis di tubuh Shilo, namun tak mampu menggoyahkannya sedikit pun."
  },
  AvgDialog_50763_Content_65 = {
    Text = "Cairan hitam pekat yang dahsyat menyembur dari puncak gunung bersalju, bagai gelombang raksasa yang menjulang, mengelilinginya sepenuhnya—"
  },
  AvgDialog_50763_Content_66 = {
    Text = "@3Kembalilah……Hancurkan@2……Lupakan@3@2……Kemarilah……Kembali ke@3……"
  },
  AvgDialog_50763_Content_67 = {
    Text = "……Kembali ke@3……"
  },
  AvgDialog_50763_Content_68 = {
    Text = "Jika kita menang, es dan salju Elworth akan mencair. Saat itu, kita akan bersama-sama, muncul kembali ke dunia."
  },
  AvgDialog_50763_Content_69 = {
    Text = "Tunggulah, Penjaga Rahasia."
  },
  AvgDialog_50763_Content_7 = {
    Text = "Kau akan mati di sini!"
  },
  AvgDialog_50763_Content_70 = {
    Text = "Shilo sejenak menoleh ke belakang. Kau seperti melihat senyuman di wajahnya yang lenyap dalam sekejap."
  },
  AvgDialog_50763_Content_71 = {
    Text = "Dia berbalik, menghadap kobaran api biru yang tak pernah padam itu, mengangkat Duri Hitam di tangannya—"
  },
  AvgDialog_50763_Content_72 = {
    Text = "Pertempuran, dimulai."
  },
  AvgDialog_50763_Content_74 = {
    Text = "Sebuah pernyataan, sekaligus perintah. Cairan hitam tak terhitung jumlahnya menghujam turun, menelan segalanya di puncak gunung."
  },
  AvgDialog_50763_Content_75 = {
    Text = "Pegunungan Elworth berguncang. Deretan pegunungan mengangkat kabut es putih susu, tubuh gunung yang kaku dan canggung meronta-ronta dengan putus asa, seolah melawan sesuatu."
  },
  AvgDialog_50763_Content_76 = {
    Text = "Awan yang terbakar tersapu angin kencang, pusaran raksasa menyelimuti seluruh puncak gunung. Kekuatan mengerikan meledak tanpa terkendali, seolah hendak menghancurkan langit itu sendiri……"
  },
  AvgDialog_50763_Content_78 = {
    Text = "Entah berapa lama telah berlalu. Asap dan debu akhirnya sirna, tanah di bawah kaki pun tak lagi bergetar."
  },
  AvgDialog_50763_Content_79 = {
    Text = "Lily yang telah kembali normal menghampiri dan menggenggam tanganmu."
  },
  AvgDialog_50763_Content_8 = {
    Text = "\"Meskipun begitu……memangnya kenapa?\""
  },
  AvgDialog_50763_Content_80 = {
    Text = "Kak Shilo……sudah tidak ada lagi."
  },
  AvgDialog_50763_Content_81 = {
    Text = "Pegunungan bernapas dengan tenang. Kau mendongak, menatap langit."
  },
  AvgDialog_50763_Content_82 = {
    Text = "Butiran salju kasar berjatuhan, menumpuk di kepalamu, mewarnai rambutmu menjadi putih kelabu."
  },
  AvgDialog_50763_Content_83 = {
    Text = "Elworth sunyi senyap, seolah tak pernah terjadi apa-apa."
  },
  AvgDialog_50764_Content_1 = {
    Text = "Minuman dan berita, kau pasti akan menyukainya. Istirahatlah yang baik, Penjaga Rahasia."
  },
  AvgDialog_50764_Content_2 = {
    Text = "Dexter membungkuk anggun kepada kalian, lalu menutup pintu dengan pelan."
  },
  AvgDialog_50764_Content_3 = {
    Text = "Berhadapan dengan Profesor Dexter, kadang aku menyesal tidak mempelajari retorika lebih mendalam."
  },
  AvgDialog_50764_Content_4 = {
    Text = "Dia mengambil koran yang ditinggalkan Dexter."
  },
  AvgDialog_50764_Content_5 = {
    Text = "\"Dikabarkan, pegunungan bersalju di pedalaman Elworth yang baru-baru ini mengalami longsoran salju besar dan tidak pernah mencair sepanjang tahun, kini menunjukkan tanda-tanda pencairan yang misterius…\""
  },
  AvgDialog_50764_Content_6 = {
    Text = "Kau langsung menoleh dan merebut koran itu."
  },
  AvgDialog_50764_Content_7 = {
    Text = "Di gambar buram yang tercetak tinta, badai salju di pegunungan telah berhenti."
  },
  AvgDialog_50764_Content_8 = {
    Text = "Sebatang taraxacum kecil dan kurus menembus lapisan salju tebal yang menutupi tanah sepanjang tahun, menjulurkan kepalanya keluar."
  },
  AvgDialog_50764_Content_9 = {
    Text = "Menyambut musim semi pertama Elworth."
  },
  AvgDialog_50895_Content_1 = {
    Text = "Tidak... aku sudah... tidak kuat lagi..."
  },
  AvgDialog_50895_Content_10 = {
    Text = "Suara melengkung yang akrab kembali bergema di langit tinggi Remwahi, yang membedakan kali ini adalah nadanya yang terdengar lebih lembut, seperti angin perak yang menyapu dengan lembut."
  },
  AvgDialog_50895_Content_11 = {
    Text = "Dalam keadaan kabur, seolah-olah kau melihat sosok di depan gerbang yang dulu menoleh padamu——"
  },
  AvgDialog_50895_Content_2 = {
    Text = "Ramona batuk mengeluarkan seteguk darah, dan darah itu langsung berubah menjadi hitam begitu menyentuh tanah."
  },
  AvgDialog_50895_Content_3 = {
    Text = "Dua kekuatan tajam bertabrakan di dalam pikirannya, deru perak dan denyut darah yang mengalir membuat lautan kesadarannya menjadi kekacauan."
  },
  AvgDialog_50895_Content_4 = {
    Text = "Apakah ini sudah berakhir..."
  },
  AvgDialog_50895_Content_5 = {
    Text = "Kamu terengah-engah, pandanganmu kabur akibat darah dan keringat yang menetes. Hanya tekad yang membuatmu tetap berdiri tanpa roboh."
  },
  AvgDialog_50895_Content_6 = {
    Text = "Apakah ini sudah berakhir? Kalian sudah kehabisan amunisi dan makanan, sementara Embrio Pohon Ibu terus mengembang, berubah, dan berkembang biak tanpa batas…"
  },
  AvgDialog_50895_Content_7 = {
    Text = "Ding Dong——"
  },
  AvgDialog_50895_Content_8 = {
    Text = "Bulu yang dingin dan lembut berubah menjadi tetesan cairan perak, bergulir diam-diam di pipi Anda yang ternoda darah, meninggalkan jejak seperti air mata perak murni."
  },
  AvgDialog_50895_Content_9 = {
    Text = "Untuk Mythag, untuk masa depan umat manusia, bertahanlah sedikit lagi."
  },
  AvgDialog_50896_Content_1 = {
    Text = "Tumor raksasa Pohon Ibu tertusuk oleh pedang tipis, cairan darah menyembur keluar, kalian mandi dalam hujan darah yang merintik."
  },
  AvgDialog_50896_Content_10 = {Text = "Juliette!"},
  AvgDialog_50896_Content_11 = {
    Text = "Juliette duduk di atas dahan pohon, menghela napas dengan nada tinggi. Dia dengan lembut membelai cabang Pohon Ibu yang bergoyang lebar seperti lengan, seolah-olah menenangkan semacam makhluk buas yang gelisah."
  },
  AvgDialog_50896_Content_12 = {
    Text = "Pohon Ibu yang agung, tolong serap sumber aliran Hidup."
  },
  AvgDialog_50896_Content_13 = {
    Text = "Tolong gunakan tubuhmu untuk menyebarkan Berkat hitam ke seluruh gurun, dan bangun tangga menuju dunia baru."
  },
  AvgDialog_50896_Content_14 = {
    Text = "Tidak perlu merasa iba kepada para pendosa, demi memohon penebusan, bangsa Aram telah lama memutuskan untuk mempersembahkan seluruh kesalehan mereka kepadamu."
  },
  AvgDialog_50896_Content_15 = {
    Text = "Kretek kretek, suara patah tulang terus-menerus bergema. Caro Alan dengan cepat menyatu ke dalam cabang di depan mata telanjang, tumor yang berdenyut bergerak, larut, lalu bergabung kembali."
  },
  AvgDialog_50896_Content_16 = {
    Text = "Ribuan keturunan dan Caro berkumpul menjadi ibu hamil yang cacat, batang pohon yang bergoyang perlahan menjadi kokoh."
  },
  AvgDialog_50896_Content_17 = {
    Text = "Semoga lampu selalu menyala terang."
  },
  AvgDialog_50896_Content_2 = {
    Text = "Hek, hek..."
  },
  AvgDialog_50896_Content_3 = {
    Text = "Hujan darah yang ganas itu memiliki dampak yang jauh lebih kuat pada Ramona dibandingkan dengan kalian. Ramona mengangkat tangannya untuk menghapus cairan darah dari poninya, lalu batuk hebat."
  },
  AvgDialog_50896_Content_4 = {
    Text = "Ramona, kamu…"
  },
  AvgDialog_50896_Content_5 = {
    Text = "Tidak apa-apa, aku masih bisa bertahan, kalian lihat gundukan pohon itu!"
  },
  AvgDialog_50896_Content_6 = {
    Text = "Gundukan pohon yang meledak terlihat seperti daging yang kehilangan darah, lemas dan lunglai. Batang Pohon ibu yang semula tegak dengan anggun juga ikut bergetar, seolah-olah menceritakan ketakutan dan kegelisahan yang aneh."
  },
  AvgDialog_50896_Content_7 = {
    Text = "Pohon ibu… apakah akan jatuh?"
  },
  AvgDialog_50896_Content_8 = {
    Text = "Tidak, belum……"
  },
  AvgDialog_50896_Content_9 = {
    Text = "Betapa menyedihkannya, mengapa kalian melakukan hal yang sia-sia seperti ini?"
  },
  AvgDialog_50897_Content_1 = {
    Text = "Pohon Ibu masih terus membelah Nubia…!"
  },
  AvgDialog_50897_Content_2 = {
    Text = "Maaf, polusi yang disebabkan oleh Juliette sudah terlalu mendalam. Sebelum pemurnian Tawil selesai, saya tidak bisa mengendalikan tindakan Pohon Ibu."
  },
  AvgDialog_50897_Content_3 = {
    Text = "Ini adalah kelalaian saya sebagai Esensi Keinginan. Oleh karena itu, dalam pertempuran yang akan datang, saya akan meminjamkan kemampuan saya kepada Anda."
  },
  AvgDialog_50897_Content_4 = {
    Text = "Kesempatan untuk mengendalikan kekuatan Tiferet·Yesod sangatlah langka."
  },
  AvgDialog_50897_Content_5 = {
    Text = "Gunakan dengan bebas, jangan sampai terbuang satu tetespun, oke?"
  },
  AvgDialog_51150_Content_1 = {Text = "Horla?"},
  AvgDialog_51150_Content_10 = {
    Text = "Semua hal ini pernah muncul di dalam puisi saya. Segala sesuatu di sini adalah seperti yang saya bayangkan dalam puisi saya…"
  },
  AvgDialog_51150_Content_11 = {
    Text = "Penjaga {Male=tuan,Female=nyonya}, ini bukan Cité yang sebenarnya."
  },
  AvgDialog_51150_Content_12 = {
    Text = "Di sini, adalah <Yellow:Cité dalam puisi saya>…"
  },
  AvgDialog_51150_Content_13 = {
    Text = "Di bawah taburan bintang di Jalan Maret, Horla perlahan berputar, memandangi segala sesuatu yang menjadi bagian dari puisinya."
  },
  AvgDialog_51150_Content_14 = {
    Text = "Sinar matahari jatuh seperti tirai kasa, menerangi wajahnya yang dipenuhi oleh rasa ingin tahu, kesedihan, dan kebingungan."
  },
  AvgDialog_51150_Content_15 = {
    Text = "Jadi begitu… tak heran di sini ada banyak hal aneh dan unik."
  },
  AvgDialog_51150_Content_16 = {
    Text = "Namun, bagaimana Cité seperti itu terbentuk……"
  },
  AvgDialog_51150_Content_17 = {
    Text = "Saya juga tidak tahu… Dan, ada beberapa hal di sini yang tidak sepenuhnya sama dengan yang kutulis dalam puisiku. Sang pelukis seharusnya adalah seorang kakek kecil yang sangat menggemaskan…"
  },
  AvgDialog_51150_Content_18 = {
    Text = "Namun, aku pikir jika ingin menangani masalah di sini, mungkin kita perlu menemukan puisi itu terlebih dahulu."
  },
  AvgDialog_51150_Content_19 = {
    Text = "Jalan, apakah kamu masih ingat?"
  },
  AvgDialog_51150_Content_2 = {
    Text = "Ah, maafkan saya, Penjaga {Male=tuan,Female=nyonya}, saya baru saja melamun…"
  },
  AvgDialog_51150_Content_20 = {
    Text = "Dalam puisi saya, Jalan Maret sangat dekat dengan rumah. Jalan untuk pulang, selalu ku ingat."
  },
  AvgDialog_51150_Content_21 = {
    Text = "Dia tersenyum ke arah pemukiman kumuh."
  },
  AvgDialog_51150_Content_22 = {
    Text = "Ayo pergi, Penjaga {Male=tuan,Female=nyonya}, kita ke Taman Mawar… ke tempat aku meninggal."
  },
  AvgDialog_51150_Content_3 = {
    Text = "Saya punya dugaan… bukan dugaan, saya yakin."
  },
  AvgDialog_51150_Content_4 = {
    Text = "Ini bukan Cité!"
  },
  AvgDialog_51150_Content_5 = {
    Text = "...Horla, apakah kamu mau mendengarkan dengan serius apa yang kamu katakan."
  },
  AvgDialog_51150_Content_6 = {
    Text = "Ah, maksud saya, ini bukan Cité yang sebenarnya."
  },
  AvgDialog_51150_Content_7 = {
    Text = "Bukan Cité yang sebenarnya…"
  },
  AvgDialog_51150_Content_8 = {
    Text = "Ulat bulu trem yang membutuhkan puisi untuk tiket, Nyonya Kupu-kupu, Jalan Maret dengan hanya nomor 99, Pelukis, Bintang Daisy…"
  },
  AvgDialog_51150_Content_9 = {
    Text = "Barang-barang yang kita lihat ini, selalu terasa sangat familiar bagi saya. Baru saja, saya akhirnya ingat."
  },
  AvgDialog_51254_Content_1 = {
    Text = "Pandangannya menyucikan jiwamu, kelelahan seketika lenyap, semangat juang yang membara terus berkobar tak henti di dalam dada."
  },
  AvgDialog_51254_Content_2 = {
    Text = "Terima kasih, Tawil…"
  },
  AvgDialog_51254_Content_3 = {
    Text = [[
Saya akan menjalankan tekadmu hingga detik terakhir.
Semoga Kunci perak menerangi jalan ke depan.]]
  },
  AvgDialog_51254_Content_4 = {
    Text = "Semoga Kunci Perak membimbing kita."
  },
  AvgDialog_51998_Content_1 = {
    Text = "Tawa ejekan orang Filistin bergema di seluruh ruangan. Kapten Filistin menggelengkan kepalanya, menjambak rambut Thalis, dan mengeluarkan belati dari tangannya."
  },
  AvgDialog_51998_Content_10 = {
    Text = "\"Kamu mengingatkanku, aku harus membuang semua barang Goliath agar Glen tidak curiga.\""
  },
  AvgDialog_51998_Content_11 = {
    Text = "\"Untuk ini, aku bisa membuatmu mati tanpa terlalu menyakitkan... Oh?\""
  },
  AvgDialog_51998_Content_2 = {
    Text = "Dia berdiri menyamping menghadap Miriam. Di pinggangnya, sebuah patung kecil bergoyang-goyang. Mata Miriam tiba-tiba terbelalak."
  },
  AvgDialog_51998_Content_3 = {
    Text = "\"Patung itu... dari mana kau mendapatkannya?\""
  },
  AvgDialog_51998_Content_4 = {
    Text = "\"Wah... ternyata kau bisa bicara, kukira kau orang bodoh.\""
  },
  AvgDialog_51998_Content_5 = {
    Text = "\"Patung itu, dari mana?\""
  },
  AvgDialog_51998_Content_6 = {
    Text = "Kapten Filistin menurunkan pisaunya. Dia menunduk menatap patung di pinggangnya."
  },
  AvgDialog_51998_Content_7 = {
    Text = "Patung tersebut terbuat dari bahan batu yang tampak sangat kuno dan suram, menggambarkan seorang pemuda duduk di atas Takhta. Beberapa tentakel aneh terentang secara acak, menutupi wajah pemuda itu."
  },
  AvgDialog_51998_Content_8 = {
    Text = "\"Hah… ini? Dulu ditemukan oleh Kepala Suku Goliath. Karena keberanianku, dia memberikannya padaku.\""
  },
  AvgDialog_51998_Content_9 = {
    Text = "\"Aku mempertaruhkan nyawaku untuknya, dan dia hanya memberiku benda seperti ini. Entah peninggalan peradaban bodoh mana, sebuah barang rongsokan yang tidak berguna.\""
  },
  AvgDialog_51999_Content_1 = {
    Text = "BLARR——"
  },
  AvgDialog_51999_Content_10 = {
    Text = "\"Kamu juga sedang dikejar dan diburu oleh kehendak yang lebih tinggi. Kamu dan aku sama, adalah jiwa-jiwa tanpa tuan.\""
  },
  AvgDialog_51999_Content_11 = {
    Text = "\"Orang-orang Lemuria, menyembah dewa yang tak berperasaan, dan raja yang lemah. Kerajaan Dewa…… hah, sungguh membosankan.\""
  },
  AvgDialog_51999_Content_2 = {
    Text = "Suara gemuruh yang teredam menembus tak terhitung dinding batu yang tebal, bergema di kamar peraduan sang kuil."
  },
  AvgDialog_51999_Content_3 = {
    Text = "Thulu menopang dagunya dengan satu tangan, duduk di atas takhta dengan lelah."
  },
  AvgDialog_51999_Content_4 = {
    Text = "Rakyat Lemuria telah terlelap dalam tidur panjang. Ia mengerahkan seluruh kekuatannya untuk menganugerahkan mereka sebuah mimpi yang indah."
  },
  AvgDialog_51999_Content_5 = {
    Text = "\"'Badai Lemuria akan mereda. Jurang Lemuria akan lenyap.'\""
  },
  AvgDialog_51999_Content_6 = {
    Text = "\"'Sang Raja akan melindungi rakyatnya yang saleh, dan membawa kerajaan para dewa...'\""
  },
  AvgDialog_51999_Content_7 = {
    Text = "\"Sungguh ironis. Apakah ini kehendak yang kau sampaikan, 'Dewa Lemuria'?\""
  },
  AvgDialog_51999_Content_8 = {
    Text = "Ia mendongak, tatapannya menembus lempengan batu di atas kepala, menembus badai dan awan gelap, hingga ke langit berbintang yang dalam, hingga ke mimpi yang lebih dalam dari langit berbintang itu sendiri."
  },
  AvgDialog_51999_Content_9 = {
    Text = "\"Kamu sudah lama mati. Kamu tak pernah peduli pada Lemuria.\""
  },
  AvgDialog_52000_Content_1 = {
    Text = "Kebajikan dari Kebohongan"
  },
  AvgDialog_52000_Content_10 = {
    Text = "Raja yang telah dipuji tanpa henti oleh bangsa Lemurian ini untuk pertama kalinya berdiri di hadapan Miryam."
  },
  AvgDialog_52000_Content_11 = {
    Text = "Setelah memasuki pintu ini, ada yang akan menangis, ada yang akan jatuh dalam kegilaan, dan ada juga yang pernah mencoba membunuh Yu."
  },
  AvgDialog_52000_Content_2 = {
    Text = "Ia menatap air kolam."
  },
  AvgDialog_52000_Content_3 = {
    Text = "Kepala-kepala licin bermunculan ke permukaan air, lalu tenggelam kembali, silih berganti, menimbulkan riak-riak kotor di permukaan kolam."
  },
  AvgDialog_52000_Content_4 = {
    Text = "Bola mata raksasa tumbuh di kedua sisi kepala manusia ikan, berputar tanpa arah, menatapnya. Bibir mereka terbuka dan tertutup, mengucapkan suku kata samar tak bermakna, seolah menanyakan sesuatu kepadanya."
  },
  AvgDialog_52000_Content_5 = {
    Text = "Di belakangnya, pintu batu bergeser terbuka."
  },
  AvgDialog_52000_Content_6 = {
    Text = "Terpujilah Tuanku... Lemuria, Raja yang agung..."
  },
  AvgDialog_52000_Content_7 = {
    Text = "Setiap kali Yu bertemu dengan para imam utama untuk pertama kalinya, dia selalu mendengar sindiran ini."
  },
  AvgDialog_52000_Content_8 = {
    Text = "Mahkota raksasa Lemuria memantulkan kilauan suram yang entah berasal dari mana di dalam ruangan, sangat tidak proporsional dengan tubuh anak muda itu. Namun, saat dipakai di kepalanya, tidak terlihat canggung, seolah-olah mahkota itu memang bagian alami dari tubuhnya."
  },
  AvgDialog_52000_Content_9 = {
    Text = "Mata yang masih mengantuk memandang Miriam, bagaikan lautan dalam yang bernapas perlahan. Di wajah mudanya yang masih kekanakan, tak terlihat emosi apa pun yang seharusnya dimiliki seorang pemuda."
  },
  AvgDialog_52001_Content_1 = {
    Text = "Namun, tidak apa-apa, Tuan-ku bisa memahami rasa takutmu. Persahabatan kita tidak akan berubah karena hinaan ini."
  },
  AvgDialog_52001_Content_10 = {
    Text = "Mari, berdoalah bersamaku, Deborah."
  },
  AvgDialog_52001_Content_11 = {
    Text = "Tidak……Miriam……aku mohon……"
  },
  AvgDialog_52001_Content_12 = {
    Text = "Ikuti aku: \"Segala yang menderita, Tuhan akan membalasnya.\""
  },
  AvgDialog_52001_Content_13 = {
    Text = "Segala……segala yang menderita……tidak, Miriam……"
  },
  AvgDialog_52001_Content_14 = {
    Text = "Ikuti aku. \"Segala yang berdosa, Tuhan akan menghukumnya.\""
  },
  AvgDialog_52001_Content_15 = {
    Text = "Miriam melantunkan doa, menghampiri sisinya."
  },
  AvgDialog_52001_Content_16 = {
    Text = "Biarkan aku bicara sepatah kata dengan Nord! Miriam……biarkan aku bicara sepatah kata dengannya……"
  },
  AvgDialog_52001_Content_17 = {
    Text = "AHHH!!!——"
  },
  AvgDialog_52001_Content_18 = {
    Text = "Rasa sakit yang luar biasa menjalar dari perutnya. Ia mendongak, melihat tangan Miriam yang pucat bagai ular membawa belati itu, menusuk ke dalam rongga perutnya, menggoreskan jejak merah darah di rongga perutnya."
  },
  AvgDialog_52001_Content_19 = {
    Text = "Miriam tidak mendengar jeritan memilukan Deborah, tidak melihat wajahnya yang terdistorsi oleh ketakutan dan rasa sakit yang luar biasa."
  },
  AvgDialog_52001_Content_2 = {
    Text = "Dengan penuh khidmat, dia meletakkan patung Thulu di tepi altar persembahan, lalu memberi hormat kepadanya."
  },
  AvgDialog_52001_Content_20 = {
    Text = "Belati itu bergerak dengan stabil, darah hangat menyembur ke wajah Miriam. Ia dengan khusyuk melantunkan doa, melangkah menaiki tangga menuju Kerajaan Tuhan."
  },
  AvgDialog_52001_Content_22 = {
    Text = "Bunuh Miriam! Bagi-bagi klan Orn! Persekutuan kita makmur sejahtera! Bersulang!!"
  },
  AvgDialog_52001_Content_23 = {
    Text = "Gelas-gelas beradu, keserakahan yang tak disembunyikan menyebar bersama aroma daging dan anggur."
  },
  AvgDialog_52001_Content_24 = {
    Text = "Goliath menjilat bibirnya, menikmati rasa yang membuatnya terpesona itu."
  },
  AvgDialog_52001_Content_25 = {
    Text = "Ayo, lanjutkan, ada apa denganmu?"
  },
  AvgDialog_52001_Content_26 = {
    Text = "Kau……wajahmu……"
  },
  AvgDialog_52001_Content_27 = {Text = "Wajahku?"},
  AvgDialog_52001_Content_28 = {
    Text = "Ia memandang ke ubin yang halus bagai cermin di sampingnya, dan melihat sebuah wajah yang menyerupai ikan."
  },
  AvgDialog_52001_Content_29 = {Text = "Aaaahhh!!!"},
  AvgDialog_52001_Content_3 = {
    Text = "Terpujilah Tuanku……Lemuria, sang Raja agung……malam ini, aku akan menyambut kepulangan-Mu."
  },
  AvgDialog_52001_Content_30 = {
    Text = "Luka demi luka muncul di dadanya, seolah digores oleh belati tak kasat mata. Telinga dan alis matanya menghilang, bola matanya membengkak dengan cepat, tumbuh melebar ke kedua sisi."
  },
  AvgDialog_52001_Content_31 = {
    Text = "Rasa sakit yang luar biasa menembus pengaruh alkohol dan adrenalin, menghantam otaknya. Ia jatuh tersungkur ke lantai, mengeluarkan jeritan kesakitan yang terlambat, kedua tangannya mencakar-cakar wajahnya sendiri secara membabi buta."
  },
  AvgDialog_52001_Content_32 = {
    Text = "Ini apa? Aakh!!——"
  },
  AvgDialog_52001_Content_33 = {
    Text = "Satu, dua, tiga…… Di dalam aula perjamuan yang mewah, para bangsawan berjatuhan satu per satu ke lantai."
  },
  AvgDialog_52001_Content_34 = {
    Text = "Luka-luka merah darah bermunculan silih berganti di tubuh mereka, darah dan daging melukiskan sebuah pola kuno di atas tubuh mereka."
  },
  AvgDialog_52001_Content_35 = {
    Text = "Jeritan kesakitan menyatu menjadi simfoni yang megah, darah menyembur, mengisi setiap gelas anggur hingga penuh."
  },
  AvgDialog_52001_Content_36 = {
    Text = "Ini…… ini…… ritual manusia ikan!"
  },
  AvgDialog_52001_Content_37 = {
    Text = "Benar, ritual Fishman. Kalian seharusnya sudah mengetahui keadaan tragis keluarga Aoen."
  },
  AvgDialog_52001_Content_38 = {
    Text = "Kenapa…… Goliya?"
  },
  AvgDialog_52001_Content_39 = {Text = "Kenapa?"},
  AvgDialog_52001_Content_4 = {
    Text = "Mohon bersabarlah. Saat bintang-bintang sejajar, akan segera tiba……"
  },
  AvgDialog_52001_Content_40 = {
    Text = "Goliya tampak seperti mendengar lelucon yang lucu. Ia berdiri dari kursi utamanya dan mengambil pisaunya."
  },
  AvgDialog_52001_Content_41 = {
    Text = "Bekerja sama dengan kalian, aku hanya mendapat sepotong kecil wilayah Keluarga Orn."
  },
  AvgDialog_52001_Content_42 = {
    Text = "Bekerja sama dengan Miriam, aku bisa mendapatkan kekuatan dahsyat yang tak bisa kalian bayangkan, bisa mengubah kalian semua menjadi bagian dari manusia ikan, menguasai seluruh kekayaan kalian……"
  },
  AvgDialog_52001_Content_43 = {
    Text = "Katakan padaku, Tuan Edmond, kalau kau jadi aku, apa yang akan kau pilih?"
  },
  AvgDialog_52001_Content_44 = {
    Text = "Aku…… kami tidak akan menyerah begitu saja!"
  },
  AvgDialog_52001_Content_45 = {
    Text = "Benar! Goliya, demi kehormatan Keluarga Enorm, kami akan…… Aakh——"
  },
  AvgDialog_52001_Content_46 = {
    Text = "Bilah raksasa itu jatuh menghujam secara vertikal, tubuh bangsawan muda itu terbelah menjadi dua dan roboh ke kedua sisi, kehilangan kemampuan untuk membuktikan kehormatannya."
  },
  AvgDialog_52001_Content_47 = {
    Text = "Pintu-pintu di sekeliling terbuka, manusia ikan yang tak terhitung jumlahnya membanjiri aula bagai gelombang pasang."
  },
  AvgDialog_52001_Content_48 = {
    Text = "……Ke mana para pengawal di luar?"
  },
  AvgDialog_52001_Content_49 = {
    Text = "Saat kalian asyik bersulang, para pengawal itu sudah kami habisi."
  },
  AvgDialog_52001_Content_5 = {
    Text = "Dia berdiri dan berjalan dengan lembut menuju Deborah. Di tangan pucatnya, belati persembahan dengan bentuk aneh berkilau dalam cahaya redup."
  },
  AvgDialog_52001_Content_50 = {
    Text = "Adapun pasukan di luar kota…… tak perlu lagi berharap untuk menghubungi mereka."
  },
  AvgDialog_52001_Content_51 = {
    Text = "Darah mewarnai setiap sudut aula menjadi merah, jeritan-jeritan memantul dan bergema liar di dinding-dinding, bagaikan simfoni dari neraka."
  },
  AvgDialog_52001_Content_52 = {
    Text = "Orang-orang yang tidak meminum anggur beracun dan masih dalam keadaan normal, tubuh mereka gemetar, bahkan tidak memiliki tenaga untuk mencabut pedang atau melarikan diri."
  },
  AvgDialog_52001_Content_53 = {
    Text = "Golia menikmati gulungan lukisan berdarah di aula besar ini, memandangi ekspresi ketakutan para bangsawan, menghela napas penuh kenikmatan, lalu mengangkat bilah pedang raksasa itu."
  },
  AvgDialog_52001_Content_54 = {
    Text = "Minum anggur beracun dan berubah menjadi manusia ikan, atau mati di sini. Pilih salah satu."
  },
  AvgDialog_52001_Content_56 = {
    Text = "AHHH!!!——"
  },
  AvgDialog_52001_Content_57 = {
    Text = "Jeritan memilukan menghantam lantai batu, menghasilkan gema yang suram."
  },
  AvgDialog_52001_Content_58 = {
    Text = "Dia ingin meronta, melarikan diri, tetapi tubuhnya dikendalikan oleh Miriam, tidak bisa bergerak sedikit pun."
  },
  AvgDialog_52001_Content_59 = {
    Text = "Dia ingin pingsan, tetapi otaknya sangat jernih, menyambut rasa sakit dan ketakutan."
  },
  AvgDialog_52001_Content_6 = {
    Text = "Tidak! Miriam!! Kumohon……kumohon……jangan lakukan hal sekejam ini……"
  },
  AvgDialog_52001_Content_60 = {
    Text = "Ucapkan bersamaku, \"Bagi yang beriman, Tuhanku akan memberkati…\""
  },
  AvgDialog_52001_Content_61 = {
    Text = "Darah Deborah memercik memenuhi tubuh Miriam. Dia teringat bertahun-tahun lalu, di atas altar persembahan kuil, dia juga seperti ini, melepas kepergian ayahnya."
  },
  AvgDialog_52001_Content_62 = {
    Text = "Perpisahan, adalah demi perjumpaan yang lebih baik, bukan begitu, Tuhanku?"
  },
  AvgDialog_52001_Content_63 = {
    Text = "Dia menatap penuh kasih ke perut Deborah, belati bergerak menggores, menyelesaikan goresan terakhir dari lukisan ini."
  },
  AvgDialog_52001_Content_64 = {
    Text = "Ayo, Deborah. Ucapkan bersamaku. Bagi yang berharap…"
  },
  AvgDialog_52001_Content_65 = {
    Text = "Tangan Miryam masuk ke dalam perut Miryam, mengaduk dan merobek."
  },
  AvgDialog_52001_Content_66 = {
    Text = "Tenggorokan Deborah yang parau menjerit kesakitan, mata merahnya terbuka lebar dengan gila, menatap lurus ke rongga perutnya sendiri."
  },
  AvgDialog_52001_Content_67 = {
    Text = "…\"Bagi yang berharap, Tuhanku akan mengabulkan.\""
  },
  AvgDialog_52001_Content_68 = {
    Text = "Miriam menarik putus sesuatu, mungkin seharusnya sangat menyakitkan, tetapi Deborah sudah tidak bisa merasakannya lagi."
  },
  AvgDialog_52001_Content_69 = {
    Text = "Otaknya sudah menjadi mati rasa, emosi dan persepsi telah meninggalkannya jauh."
  },
  AvgDialog_52001_Content_7 = {
    Text = "Tatap aku, Deborah. Tatap aku……"
  },
  AvgDialog_52001_Content_70 = {
    Text = "Dia melihat samar-samar, Miriam mengeluarkan gumpalan daging berlumuran darah dari rongga perutnya."
  },
  AvgDialog_52001_Content_71 = {
    Text = "Sa… Sa…"
  },
  AvgDialog_52001_Content_72 = {
    Text = "Sara. Miriam pernah memberitahunya, itu adalah nama adik perempuannya."
  },
  AvgDialog_52001_Content_73 = {
    Text = "Dia sudah membicarakannya dengan Nord, mereka akan menamai putri mereka dengan nama ini. Tapi dia belum sempat memberitahu Miriam."
  },
  AvgDialog_52001_Content_74 = {
    Text = "Namakan dia Sarah. Deborah bergumam lirih, tapi dia sudah tak mampu lagi mengeluarkan suara apa pun."
  },
  AvgDialog_52001_Content_75 = {
    Text = "\"Wahai Tuhan kami, semoga nyanyian kami menembus lautan dalam, bersama-Mu, menuju alam ketenangan dan kebahagiaan abadi.\""
  },
  AvgDialog_52001_Content_76 = {
    Text = "Miriam dengan penuh kasih mencium putri baptisnya, darah di tubuh bayi itu mewarnai bibirnya merah. Darah menetes dari sudut bibirnya, sementara ia perlahan menutup mata Deborah."
  },
  AvgDialog_52001_Content_8 = {
    Text = "Aku tahu, kau sangat ketakutan. Aku telah melihat banyak pengikut, saat menghadapi akhir kehidupan mereka, mereka semua akan merasa takut."
  },
  AvgDialog_52001_Content_9 = {
    Text = "Tapi, jangan khawatir. Kau adalah rakyat tertinggi Kerajaan Tuhan, semua penderitaan yang kau alami akan mendapat gantinya di Kerajaan Tuhan."
  },
  AvgDialog_52002_Content_1 = {
    Text = "Bintang-bintang telah mencapai posisi yang tepat. Janin suci Sang Raja telah ditanamkan ke dalam tubuh bayi suci. Segera, Sang Raja akan kembali hadir di dunia."
  },
  AvgDialog_52002_Content_10 = {
    Text = "Di tengah gemuruh seruan para manusia ikan yang memekakkan telinga, Miriam mengulurkan kedua tangannya, mengangkat tinggi-tinggi bayi dalam dekapannya."
  },
  AvgDialog_52002_Content_11 = {
    Text = "Di tempat yang semula menjadi jantungnya, Janin Suci bersinar dengan cahaya putih murni di bawah gemerlap bintang."
  },
  AvgDialog_52002_Content_12 = {
    Text = "Uwaaaa——"
  },
  AvgDialog_52002_Content_13 = {
    Text = "Segalanya menjadi hening. Bayi yang berlumuran darah menggeliatkan tubuhnya, dan di tengah reruntuhan kuno itu, bergema tangisan pertamanya yang terlambat."
  },
  AvgDialog_52002_Content_14 = {
    Text = "Bintang-bintang di langit terdiam, mendengarkan tangisan yang bagaikan wahyu ilahi. Sebuah bintang jatuh, menggoreskan catatan kaki yang memilukan di langit malam."
  },
  AvgDialog_52002_Content_15 = {
    Text = "——Kisah lain tentang bintang-bintang, akan segera dimulai."
  },
  AvgDialog_52002_Content_2 = {
    Text = "Sang Raja akan melindungi umat-Nya yang saleh, dan membawa Kerajaan Ilahi!"
  },
  AvgDialog_52002_Content_3 = {
    Text = "Kerajaan Ilahi! Kerajaan Ilahi!"
  },
  AvgDialog_52002_Content_4 = {
    Text = "Para manusia ikan bersorak dan menari dengan penuh kegilaan. Miriam tiba di tengah kerumunan. Cahaya bintang turun, menerangi wajahnya yang dipenuhi darah dan air mata."
  },
  AvgDialog_52002_Content_5 = {
    Text = "Ajaran Sang Raja akan tersebar ke seluruh dunia. Yang Mulia Pendeta Agung, berikanlah nama untuk aliran kepercayaan ini."
  },
  AvgDialog_52002_Content_6 = {
    Text = "Sepasang mata yang dingin namun membara berputar perlahan. Miriam memandang sekeliling kepada para prajurit dan rakyatnya. Dia mengulas senyum seorang Pendeta Agung kepada mereka."
  },
  AvgDialog_52002_Content_7 = {
    Text = "Kami melangkah ke lautan, mengejar jejak Sang Raja. Kami datang dari lautan, membawa kerajaan Sang Raja..."
  },
  AvgDialog_52002_Content_8 = {
    Text = "Dunia akan menyebut kami, Para Pengarung Lautan."
  },
  AvgDialog_52002_Content_9 = {
    Text = "Pengarung Lautan! Pengarung Lautan!!"
  },
  AvgDialog_52003_Content_1 = {
    Text = "Raja akan memberitahu kalian. Berdoalah."
  },
  AvgDialog_52003_Content_10 = {
    Text = "Dari waktu ke waktu, orang-orang di sekitarnya berjatuhan. Miriam menahan rasa sakit dengan sekuat tenaga dan membacakan doa yang tertulis di atas kertas itu."
  },
  AvgDialog_52003_Content_11 = {
    Text = "\"Di jurang kelam yang jauh, jiwa agung purba tertidur lelap...\""
  },
  AvgDialog_52003_Content_12 = {
    Text = "Miriam mengucapkan kata-kata itu dalam bahasa Lemuria biasa, tetapi begitu keluar dari mulutnya, kata-kata itu berubah menjadi bahasa lain."
  },
  AvgDialog_52003_Content_13 = {
    Text = "Pada saat yang sama, suaranya saling tumpang tindih dan terjalin, bergema dengan kompleksitas yang luar biasa. Seperti halnya tulisan itu, suaranya pun berubah menjadi struktur berdimensi tinggi, seolah bergema dari ruang-waktu yang tak dapat dibayangkan manusia."
  },
  AvgDialog_52003_Content_14 = {
    Text = "\"...Kehendak-Nya terjalin bagai jaring bintang, Dia menanti engkau bermimpi dalam kekosongan abadi...\""
  },
  AvgDialog_52003_Content_15 = {
    Text = "Miriam terus membacakan doa itu."
  },
  AvgDialog_52003_Content_16 = {
    Text = "Entah sejak kapan, dunia di hadapannya menghilang."
  },
  AvgDialog_52003_Content_17 = {
    Text = "Dia berada di dasar laut dalam, ke arah mana pun dia memandang, yang terlihat hanyalah hamparan air laut yang hampa."
  },
  AvgDialog_52003_Content_18 = {
    Text = "Di kedalaman laut itu, titik-titik cahaya bertebaran bagaikan bintang-bintang di alam semesta."
  },
  AvgDialog_52003_Content_19 = {
    Text = "Miriam merasa dirinya juga telah menjadi sebuah bintang, dan cahaya dari tubuhnya tengah mengalir berkumpul ke suatu tempat. Dia mengarahkan pandangannya ke sana."
  },
  AvgDialog_52003_Content_2 = {
    Text = "Pria tua itu meninggalkan ruangan, di dalam hanya tersisa seorang pendeta dan beberapa pengawal."
  },
  AvgDialog_52003_Content_20 = {
    Text = "Berkas-berkas cahaya yang tak terhitung mengalir deras dan berkumpul, membentuk siluet samar di sana. Itu adalah siluet yang terdiri dari tubuh manusia, takhta, dan tentakel."
  },
  AvgDialog_52003_Content_21 = {
    Text = "Itu... sang Raja?"
  },
  AvgDialog_52003_Content_22 = {Text = "Pak—"},
  AvgDialog_52003_Content_23 = {
    Text = "Tampaknya terganggu oleh suara tertentu, dia terbangun dari Takhta. Seiring dengan kebangunannya, seluruh ruang Ilusi tampak meredup sejenak."
  },
  AvgDialog_52003_Content_24 = {
    Text = "Di belakangnya, siluet samar seorang pria tua muncul."
  },
  AvgDialog_52003_Content_25 = {
    Text = "Anda mendengar suaranya, Tuanku."
  },
  AvgDialog_52003_Content_26 = {
    Text = "Orang yang ditunjukkan oleh bintang-bintang, apakah dia adalah dia?"
  },
  AvgDialog_52003_Content_27 = {
    Text = "Ya, dia orangnya. Saya sudah memeriksanya. Jika petunjuk bintang-bintang tidak salah, dia... adalah masa depan Lemuria."
  },
  AvgDialog_52003_Content_28 = {
    Text = "Kau tidak berpikir demikian."
  },
  AvgDialog_52003_Content_29 = {
    Text = "Berbakat, tapi pikirannya terpecah. Dia tidak akan bisa membantu Anda, Tuanku."
  },
  AvgDialog_52003_Content_3 = {
    Text = "Cahaya di dalam ruang doa menjadi redup, patung di depan berkilau dengan kemilau misterius yang samar."
  },
  AvgDialog_52003_Content_30 = {
    Text = "Dia tidak percaya pada doa-doa, tidak percaya pada Anda, dan juga tidak percaya pada masa depan Lemuria. Dia hanya percaya pada keluarganya."
  },
  AvgDialog_52003_Content_31 = {
    Text = "Miryam adalah seseorang yang hidup dalam kenyataan. Orang seperti itu tidak mampu memikul takdir Lemuria."
  },
  AvgDialog_52003_Content_32 = {
    Text = "Hidup dalam kenyataan dan bukan dalam ilusi, itulah justru harapanku."
  },
  AvgDialog_52003_Content_33 = {
    Text = "Harapan yang indah, Tuanku. Namun terlahir di Lemuria, kita semua memiliki tanggung jawab yang harus dipikul."
  },
  AvgDialog_52003_Content_34 = {
    Text = "Kita tidak bisa memilih. Baik dia, saya, maupun Anda, semuanya sama."
  },
  AvgDialog_52003_Content_35 = {
    Text = "...Membosankan. Aku mau istirahat."
  },
  AvgDialog_52003_Content_36 = {
    Text = "Dia melambaikan tangannya. Sang lelaki tua membungkuk memberi hormat kepadanya, lalu menghilang ke dalam kehampaan yang tak bertepi."
  },
  AvgDialog_52003_Content_37 = {
    Text = "Sebelum tertidur, dia melirik sekilas orang-orang yang mempersembahkan cahaya mereka kepadanya. Sebuah desahan yang tak terdengar siapa pun, lenyap ke dalam kekosongan yang tak berujung."
  },
  AvgDialog_52003_Content_38 = {Text = "Ah!"},
  AvgDialog_52003_Content_39 = {
    Text = "Menyusul sensasi jatuh yang mencekam hati, datanglah rasa sakit yang tajam dan menusuk."
  },
  AvgDialog_52003_Content_4 = {
    Text = "Miriam mengambil teks doa di hadapannya."
  },
  AvgDialog_52003_Content_40 = {
    Text = "Rasa sakit itu tidak berlangsung lama. Miriam meninggalkan ruang hampa itu dan memandang ke sekelilingnya."
  },
  AvgDialog_52003_Content_41 = {
    Text = "Beberapa orang yang tidak mampu membaca atau melafalkan doa telah diminta keluar dari ruang sembahyang. Dari separuh orang yang tersisa, beberapa tergeletak di lantai kesakitan, sementara yang lain memejamkan mata sambil berdoa, wajah mereka menampakkan senyum bahagia."
  },
  AvgDialog_52003_Content_42 = {
    Text = "Deborah duduk di sampingnya, tersenyum sambil perlahan membuka mata. Melihat keadaan Miriam, raut wajahnya berubah khawatir."
  },
  AvgDialog_52003_Content_5 = {Text = "Ah……"},
  AvgDialog_52003_Content_6 = {
    Text = "Yang tertulis di kertas itu bukanlah bahasa umum Lemuria, melainkan simbol hieroglif yang rumit, memiliki dimensi lebih banyak daripada ruang realitas."
  },
  AvgDialog_52003_Content_7 = {
    Text = "Simbol-simbol itu berasal dari zaman purba, atau bahkan dari dunia lain, yang belum pernah dilihat Miriam sebelumnya. Namun saat membaca simbol-simbol itu, maknanya secara otomatis memasuki benaknya."
  },
  AvgDialog_52003_Content_8 = {
    Text = "Setiap huruf mengandung informasi yang sangat besar, kitab suci yang tak terhitung jumlahnya membanjiri otak Miriam, membuat kepala manusia yang rapuh itu tak sanggup menanggung bebannya."
  },
  AvgDialog_52003_Content_9 = {
    Text = "<Shake:Ke... kepalaku sakit sekali...>"
  },
  AvgDialog_52004_Content_1 = {
    Text = "Selama kau beriman kepada Raja, Raja akan menjawab imanmu..."
  },
  AvgDialog_52004_Content_10 = {
    Text = [[
Semoga mata bijaksana-Mu melihat segala malapetaka,
Semoga kebijaksanaan-Mu menuntun umat-Mu.]]
  },
  AvgDialog_52004_Content_11 = {
    Text = [[
"Semoga mata bijak Anda menyingkap malapetaka, 
 semoga kebijaksanaan Anda memimpin rakyat Anda!"]]
  },
  AvgDialog_52004_Content_12 = {
    Text = [[
Badai tenang, riak air tidak bergelombang; 
 Gempa mereda, bumi tenteram.]]
  },
  AvgDialog_52004_Content_13 = {
    Text = [[
Malapetaka lenyap menjadi kehampaan dalam mimpi damai-Mu.
Dalam perlindungan-Mu, kami menyambut kerajaan para dewa.]]
  },
  AvgDialog_52004_Content_14 = {
    Text = "\"Malapetaka lenyap menjadi kehampaan dalam mimpi damai-Mu!\""
  },
  AvgDialog_52004_Content_15 = {
    Text = "\"Dalam perlindungan-Mu,\nkami menyambut kerajaan para dewa……\""
  },
  AvgDialog_52004_Content_16 = {Text = "Grrmm..."},
  AvgDialog_52004_Content_17 = {
    Text = "Di tengah gemuruh, beberapa tentakel raksasa menerobos keluar dari bawah kuil."
  },
  AvgDialog_52004_Content_18 = {
    Text = "Itu sang Raja! Mukjizat sang Raja telah menampakkan diri!!!"
  },
  AvgDialog_52004_Content_19 = {
    Text = "Para pengikut merentangkan kedua tangan, bersorak-sorai dengan penuh kegilaan."
  },
  AvgDialog_52004_Content_2 = {
    Text = "Jadi, katakan padaku, apakah kau beriman kepada Raja? Apakah kau bersedia mempersembahkan segalanya kepada Raja?"
  },
  AvgDialog_52004_Content_20 = {
    Text = "Tentakel-tentakel itu berayun perlahan di tengah badai. Seluruh penduduk Lemuria tidak sedikitpun meragukan bahwa dewa agung Lemuria ini memiliki kekuatan untuk menangkal segala bencana."
  },
  AvgDialog_52004_Content_21 = {
    Text = "Wahai Tuan kami, Thulu—"
  },
  AvgDialog_52004_Content_22 = {
    Text = "Wahai Tuan kami, Thulu!! Thulu!!!"
  },
  AvgDialog_52004_Content_23 = {
    Text = "Ia berbalik, memandang ke arah bagian dalam kuil, lalu berlutut di tanah."
  },
  AvgDialog_52004_Content_24 = {
    Text = "Di balik mata yang tak seorang pun dapat melihatnya, tak ada lagi harapan dan keagungan seorang Pendeta Agung, yang tersisa hanyalah kebingungan."
  },
  AvgDialog_52004_Content_25 = {
    Text = "Dengarkanlah seruan para pengikut-Mu. Bawalah bagi kami, kerajaan para dewa."
  },
  AvgDialog_52004_Content_26 = {
    Text = "Tolong bawakan kami, Kerajaan Tuhan!"
  },
  AvgDialog_52004_Content_27 = {
    Text = "Tuanku! Kerajaan Tuhan! Hahaha... Kerajaan Tuhan akan segera turun!"
  },
  AvgDialog_52004_Content_28 = {
    Text = "Diiringi teriakan Kegilaan, tentakel mulai bergerak. Aura tenang dari Aequor menyebar dari tentakel itu, memasuki indra setiap Lemurian."
  },
  AvgDialog_52004_Content_29 = {
    Text = "BLARR——"
  },
  AvgDialog_52004_Content_3 = {
    Text = "Aku beriman kepada Raja, Tuan Pendeta Agung! Aku bersedia mempersembahkan segalanya kepada Raja!"
  },
  AvgDialog_52004_Content_30 = {
    Text = "Di tengah gemuruh guntur, sorak-sorai mereda. Kilat menyambar dari langit, menerangi tanah Lemuria yang sunyi."
  },
  AvgDialog_52004_Content_31 = {
    Text = "Di momen pesta kegembiraan ini, gerakan para pengikut terhenti, membeku dalam pujian dan keimanan tertinggi kepada sang Raja, membeku dalam khayalan dan harapan tak terbatas akan masa depan."
  },
  AvgDialog_52004_Content_32 = {
    Text = "Di bawah hujan lebat, anak-anak Lemuria terlelap dalam mimpi."
  },
  AvgDialog_52004_Content_4 = {
    Text = "Aku adalah pengikut paling setia Raja!"
  },
  AvgDialog_52004_Content_5 = {
    Text = "Aku bersedia! Yang Mulia Pendeta Agung, aku bersedia!"
  },
  AvgDialog_52004_Content_6 = {
    Text = "Maka sekarang, ucapkanlah bersama denganku nama sang Raja—"
  },
  AvgDialog_52004_Content_7 = {
    Text = "Ia memandang ke sekeliling, menatap setiap orang di alun-alun."
  },
  AvgDialog_52004_Content_8 = {
    Text = "Di tengah badai dahsyat, semua orang berlutut, merentangkan kedua tangan, memandang ke arah takhta di dalam kuil."
  },
  AvgDialog_52004_Content_9 = {
    Text = "Di bawah cahaya bintang yang gemerlap, di atas pulau terpencil Aequor, aku berdoa dengan khidmat untuk Tuhanku:"
  },
  AvgDialog_52005_Content_1 = {
    Text = "Benar, Ayah... Kita akan bertemu lagi di kerajaan dewa! Kita sekeluarga akan hidup bersama di kerajaan dewa..."
  },
  AvgDialog_52005_Content_10 = {
    Text = "Kerajaan Tuhan akan segera turun, Ayah. Sebentar lagi, keluarga kita akan bersatu kembali…"
  },
  AvgDialog_52005_Content_11 = {Text = "Jleb——"},
  AvgDialog_52005_Content_12 = {
    Text = "Belati menghujam dada Inos dengan keras, Inos menjerit kesakitan. Darah menyembur, mewarnai separuh wajah kanan Miriam."
  },
  AvgDialog_52005_Content_13 = {
    Text = "Miriam membelalakkan matanya, menatap dengan saksama sayatan antara belati dan daging, seolah sedang memandangi sebuah mahakarya lukisan."
  },
  AvgDialog_52005_Content_14 = {
    Text = "Belati bergerak, meluncur, membelah kulit dan tulang. Inos meraung kesakitan, seperti seekor binatang buas yang sedang dicabik-cabik."
  },
  AvgDialog_52005_Content_15 = {
    Text = "Jeritan dan darah membanjiri ruang ritual, bagaikan duri-duri tak terhitung yang menembus wajah dan kulit Miriam, menusuk hingga ke jantung dan paru-parunya."
  },
  AvgDialog_52005_Content_17 = {
    Text = "\"Wahai pengikut Tuanku, bukalah hatimu, terimalah Tuanku…\""
  },
  AvgDialog_52005_Content_18 = {
    Text = "Darah dan air mata membasuh wajah Miriam yang terdistorsi mengerikan. Dia merapalkan doa, gerakan tangannya semakin cepat, semakin cepat."
  },
  AvgDialog_52005_Content_19 = {
    Text = "Belati berhenti. Di tubuh Inos, dengan tulang dan darahnya sendiri, terlukis simbol-simbol yang melambangkan kebahagiaan dan harapan."
  },
  AvgDialog_52005_Content_2 = {
    Text = "Dia mengusap air mata dari wajahnya, perlahan berdiri, dan mengambil belati di sampingnya."
  },
  AvgDialog_52005_Content_20 = {
    Text = "\"Yang beriman dengan tulus, Tuanku akan memberkati…\""
  },
  AvgDialog_52005_Content_21 = {
    Text = "<Big:\"Yang berharap dengan sungguh, Tuanku akan mengabulkan…\">"
  },
  AvgDialog_52005_Content_22 = {
    Text = "Dia menangkup darah suci itu dan menuangkannya ke dalam luka-luka berbentuk simbol di tubuh Inos."
  },
  AvgDialog_52005_Content_23 = {
    Text = "Saat darah dewa menyentuh simbol-simbol itu, seperti ular yang merasakan sumber panas mangsanya, darah itu menjadi hidup dan bergairah."
  },
  AvgDialog_52005_Content_24 = {
    Text = "Tanpa perlu arahan dari Miriam, darah itu mengikuti panduan sumber panas, meresap masuk ke tubuh Inos melalui luka-luka itu."
  },
  AvgDialog_52005_Content_25 = {
    Text = "Seiring mengalirnya darah dewa, jeritan kesakitan Inos semakin hebat. Luka-luka di tubuhnya sembuh dengan kecepatan yang kasat mata."
  },
  AvgDialog_52005_Content_26 = {
    Text = "Bersamaan dengan itu, wajahnya mulai berubah—kedua matanya membesar dan menonjol keluar, bibirnya menjadi berlendir, dan bentuk tengkoraknya menjadi pipih dan memanjang."
  },
  AvgDialog_52005_Content_27 = {
    Text = "Organ menyerupai insang muncul di lehernya, dan sisik menggantikan rambut, tumbuh dari berbagai bagian tubuhnya."
  },
  AvgDialog_52005_Content_28 = {
    Text = "Dia masih mengeluarkan suara kesakitan, dari lolongan pria dewasa manusia, perlahan berubah menjadi desisan yang membawa aura lembap dan kotor dari dasar laut..."
  },
  AvgDialog_52005_Content_29 = {
    Text = "Aku berhasil, Ayah... Aku tidak mengecewakanmu, kan?"
  },
  AvgDialog_52005_Content_3 = {
    Text = "Belati itu melengkung dalam sudut yang aneh, dengan simbol hieroglif rumit yang sama seperti pada doa-doa yang terukir di permukaannya."
  },
  AvgDialog_52005_Content_30 = {
    Text = "Desisan itu berhenti. Kesadaran lenyap, makhluk setengah ikan setengah manusia itu menatapnya dengan mata besar pucat yang kosong, memandanginya dengan linglung."
  },
  AvgDialog_52005_Content_31 = {
    Text = "Miriam berjalan ke sisi altar batu, membelai makhluk itu, merasakan bau amis ikan yang pekat di udara, serta sentuhan berlendir di tangannya."
  },
  AvgDialog_52005_Content_32 = {
    Text = "Bau amis dan sentuhan itu dulu membuatnya mual, tetapi sekarang, dia merasa semuanya begitu hangat."
  },
  AvgDialog_52005_Content_33 = {
    Text = "Aku sangat suka ikan. Saat kita bertemu kembali di Kerajaan Dewa, aku akan makan ikan buatanmu setiap hari..."
  },
  AvgDialog_52005_Content_34 = {
    Text = "Tunggulah aku, Ayah."
  },
  AvgDialog_52005_Content_35 = {
    Text = "Dia membungkuk dan mencium wajahnya yang licin dan lembap."
  },
  AvgDialog_52005_Content_4 = {
    Text = "Di dalam baskom batu di samping belati, darah yang berasal dari Dewa perlahan beriak. Cahaya lilin memantulkan kilauan merah kehijauan yang aneh."
  },
  AvgDialog_52005_Content_5 = {
    Text = "Delirium yang parah telah merenggut hampir seluruh kesadaran Inos. Dia membuka matanya, menatap Miriam dengan penasaran, seperti bayi yang baru lahir, memandangi dunia baru yang asing di hadapannya."
  },
  AvgDialog_52005_Content_6 = {
    Text = "Miriam, sekarang kau sudah menjadi pendeta… Apakah kau sudah bertanya kepada Raja? Apakah Raja memberitahumu, kapan Kerajaan Tuhan akan turun ke Lemuria?"
  },
  AvgDialog_52005_Content_7 = {
    Text = "Sudah kutanyakan, Ayah… Raja berkata, segera, segera…"
  },
  AvgDialog_52005_Content_8 = {
    Text = "Di antara air mata, muncul senyuman yang pilu. Dia mendekati Inos, membungkuk, dan membelai wajahnya."
  },
  AvgDialog_52005_Content_9 = {
    Text = "Aku tidak akan mengecewakanmu, Ayah."
  },
  AvgDialog_54067_Content_1 = {
    Text = "Mimpi Kembali ke Lemuria"
  },
  AvgDialog_54067_Content_10 = {
    Text = "Kebisingan itu bagaikan gerombolan ikan di lautan, berenang mengelilinginya. Di antara dirinya dan gerombolan ikan itu, hamparan air laut yang hampa mengalir dalam keheningan, dan suaranya sendiri muncul dengan jelas di antaranya."
  },
  AvgDialog_54067_Content_100 = {
    Text = "Hujan lebat menghantam tubuhnya yang kering kerontang, angin kencang hampir menumbangkannya. Di titik tertinggi Lemuria, sang lelaki tua memandang jauh ke pulau raksasa ini."
  },
  AvgDialog_54067_Content_101 = {
    Text = "Ketajaman dan ketuaan di matanya lenyap tak berbekas. Mata itu jernih, riang, penuh rasa ingin tahu, bagaikan bayi yang baru lahir, menatap penuh semangat ke tanah yang penuh luka ini."
  },
  AvgDialog_54067_Content_102 = {
    Text = "\"Hehehe... Lemuria, betapa indahnya tempat ini.\""
  },
  AvgDialog_54067_Content_103 = {
    Text = "\"Apa yang sedang Anda pikirkan sekarang, Tuanku?\""
  },
  AvgDialog_54067_Content_104 = {
    Text = "\"Anda selalu berkata bahwa Anda tidak tertarik menyelamatkan Lemuria, bahwa Anda hanya merasa lelah. Namun demi Lemuria, Anda mengurung diri di atas takhta, terjebak dalam mimpi Anda sendiri.\""
  },
  AvgDialog_54067_Content_105 = {
    Text = "\"Para dewa telah menghilang, namun Anda masih terus mencari... Saya hanyalah seorang penipu. Andalah pelindung terbesar Lemuria.\""
  },
  AvgDialog_54067_Content_106 = {
    Text = "\"Lihatlah sekali lagi, Tuanku. Lihatlah untuk terakhir kalinya. Lemuria, tanah air kita...\""
  },
  AvgDialog_54067_Content_107 = {
    Text = "Sang lelaki tua mendongakkan kepala, tatapannya berpindah dari rakyatnya yang tertidur lelap di pulau itu, ke lautan yang mendidih di cakrawala, ke guntur dan badai yang tak kenal ampun di langit."
  },
  AvgDialog_54067_Content_108 = {
    Text = "Ia berdiri dengan tubuh gemetar, kelembutan melebur dalam kedua matanya yang dalam. Janggut, rambut, dan jubahnya berkibar tertiup angin, sementara kedua matanya yang kembali tajam menusuk langit bagai mata pedang."
  },
  AvgDialog_54067_Content_109 = {
    Text = "\"Tipu daya yang rumit, misi yang membosankan, janji yang agung—biarkan semua itu pergi ke neraka.\""
  },
  AvgDialog_54067_Content_11 = {
    Text = "\"……Atas nama Thulu, Tuanku, aku bersumpah:\""
  },
  AvgDialog_54067_Content_110 = {
    Text = "Ia melempar tongkatnya, merentangkan kedua lengan, menyambut badai. Ia meraung."
  },
  AvgDialog_54067_Content_111 = {
    Text = "\"Datanglah, malapetaka! Datanglah, para dewa yang hina!\""
  },
  AvgDialog_54067_Content_112 = {
    Text = "\"Aku adalah kaki tangan kalian. Mari kita bersama-sama mengantar Lemuria ke peristirahatannya yang terakhir!\""
  },
  AvgDialog_54067_Content_114 = {
    Text = "BLARR——"
  },
  AvgDialog_54067_Content_115 = {
    Text = "Suara gemuruh yang teredam menembus tak terhitung dinding batu yang tebal, bergema di kamar peraduan sang kuil."
  },
  AvgDialog_54067_Content_116 = {
    Text = "Thulu menopang dagunya dengan satu tangan, duduk di atas takhta dengan lelah."
  },
  AvgDialog_54067_Content_117 = {
    Text = "Rakyat Lemuria telah terlelap dalam tidur panjang. Ia mengerahkan seluruh kekuatannya untuk menganugerahkan mereka sebuah mimpi yang indah."
  },
  AvgDialog_54067_Content_118 = {
    Text = "\"'Badai Lemuria akan mereda. Jurang Lemuria akan lenyap.'\""
  },
  AvgDialog_54067_Content_119 = {
    Text = "\"'Sang Raja akan melindungi rakyatnya yang saleh, dan membawa kerajaan para dewa...'\""
  },
  AvgDialog_54067_Content_12 = {
    Text = "\"Aku adalah hamba Lemuria. Aku adalah pengiring setia Sang Raja.\""
  },
  AvgDialog_54067_Content_120 = {
    Text = "\"Sungguh ironis. Apakah ini kehendak yang kau sampaikan, 'Dewa Lemuria'?\""
  },
  AvgDialog_54067_Content_121 = {
    Text = "Ia mendongak, tatapannya menembus lempengan batu di atas kepala, menembus badai dan awan gelap, hingga ke langit berbintang yang dalam, hingga ke mimpi yang lebih dalam dari langit berbintang itu sendiri."
  },
  AvgDialog_54067_Content_122 = {
    Text = "\"Kau sudah lama pergi... Kau tak pernah peduli pada Lemuria. Benar, kan?\""
  },
  AvgDialog_54067_Content_123 = {
    Text = "\"Kau juga dikejar, diburu, dan ditinggalkan oleh kehendak yang lebih tinggi. Kau sama seperti aku, jiwa tersesat tanpa tuan.\""
  },
  AvgDialog_54067_Content_124 = {
    Text = "\"Orang-orang Lemuria, menyembah dewa yang tak berperasaan, dan raja yang lemah. Kerajaan Dewa…… hah, sungguh membosankan.\""
  },
  AvgDialog_54067_Content_125 = {
    Text = "\"Maafkan aku. Tapi kali ini, aku benar-benar lelah.\""
  },
  AvgDialog_54067_Content_126 = {
    Text = "Dia duduk miring di atas takhta, satu tangan menopang dagu, lalu tertidur lelap."
  },
  AvgDialog_54067_Content_127 = {
    Text = "Dia memasuki mimpi yang sama dengan rakyatnya. Di sana, Lemuria dipenuhi sinar matahari yang cerah, penuh tawa dan kebahagiaan."
  },
  AvgDialog_54067_Content_128 = {
    Text = "Dia membawakan Kerajaan Dewa yang selama ini didambakan Lemuria. Dia membawakan kebohongan yang selama ini didambakan Lemuria."
  },
  AvgDialog_54067_Content_129 = {
    Text = "Mengucapkan selamat tinggal pada tanah air dengan kebohongan — itulah kekuasaan dan belas kasih terakhirnya sebagai Raja Lemuria."
  },
  AvgDialog_54067_Content_13 = {
    Text = "\"Aku akan memimpin rakyat Lemuria. Aku akan mendengarkan suara Tuanku, melaksanakan perintah Tuanku.\""
  },
  AvgDialog_54067_Content_131 = {Text = "Pak—"},
  AvgDialog_54067_Content_132 = {
    Text = "Pecahan batu berjatuhan dari patung itu. Patung raksasa yang membisu itu, kini sudah hancur tak berbentuk."
  },
  AvgDialog_54067_Content_133 = {
    Text = "\"Ayah, lihatlah…… itu adalah air mata Sang Raja. Tuanku, sedang berduka untuk Lemuria.\""
  },
  AvgDialog_54067_Content_134 = {
    Text = "Di dalam pelukannya, seekor manusia ikan memutar-mutar matanya yang besar, memandang ke sekeliling dengan bingung."
  },
  AvgDialog_54067_Content_135 = {
    Text = "Dia tidak bisa menemukan Inos, maka setiap manusia ikan adalah Inos baginya."
  },
  AvgDialog_54067_Content_136 = {
    Text = "Suara hujan lebat menembus dinding, semakin kuat, bau amis pekat dari para manusia ikan memenuhi ruangan. Dia membelainya dengan lembut."
  },
  AvgDialog_54067_Content_137 = {
    Text = "\"Guru, Sang Raja…… mereka semua tampaknya sudah menyerah.\""
  },
  AvgDialog_54067_Content_138 = {
    Text = "\"Aku…… tidak akan menyerah…… Aku bisa menyelamatkan Lemuria, aku bisa membawa Lemuria kembali. Ini yang dikatakan langsung oleh Sang Raja kepadaku.\""
  },
  AvgDialog_54067_Content_139 = {
    Text = "\"Ibu sudah meninggal, adik perempuan sudah meninggal, ayah…… juga sudah meninggal.\""
  },
  AvgDialog_54067_Content_14 = {
    Text = "\"Aku akan bersama seluruh umat beriman, menyambut Kerajaan Dewa.\""
  },
  AvgDialog_54067_Content_140 = {
    Text = "\"Aku sangat takut, Miriam. Aku takut semua yang kita lakukan ini…… tidak ada artinya……\""
  },
  AvgDialog_54067_Content_141 = {
    Text = "\"Begitu banyak bencana, Ayah hanyalah orang biasa, tapi dia tidak pernah takut, dan tidak pernah menyerah.\""
  },
  AvgDialog_54067_Content_142 = {
    Text = "\"Kita adalah pendeta agung Lemuria, kita juga tidak akan pernah menyerah…… inilah yang Ayah ajarkan kepadaku.\""
  },
  AvgDialog_54067_Content_143 = {
    Text = "Dia tersenyum, berbisik menenangkan. Air mata mengalir deras, bercampur dengan kata-kata yang bahkan dia sendiri tidak tahu benar atau palsu, menetes ke sisik manusia ikan, membiaskan cahaya yang redup."
  },
  AvgDialog_54067_Content_144 = {
    Text = "Duarrr duarrr duarrr——"
  },
  AvgDialog_54067_Content_145 = {
    Text = "Tanah di bawah kaki tiba-tiba bergetar hebat. Pilar-pilar batu kokoh kuil berusaha keras menopang, sementara lempengan batu di atas kepala perlahan retak, hancur, dan berjatuhan ke tanah."
  },
  AvgDialog_54067_Content_146 = {
    Text = "Dalam guncangan dahsyat ini, sisa-sisa patung hancur berkeping-keping. Suara badai dan gempa bumi menggedor gendang telinga Miriam bagaikan dentuman drum."
  },
  AvgDialog_54067_Content_147 = {
    Text = "Dia memejamkan mata, berlutut di hadapan patung yang hancur, dan menggenggam tangan Miriam kecil."
  },
  AvgDialog_54067_Content_148 = {
    Text = "\"Dengarkanlah Tuhanku, berserahlah kepada Tuhanku, pujilah Tuhanku...\""
  },
  AvgDialog_54067_Content_149 = {
    Text = [[
"Bagi yang menderita, Tuhanku akan membalas.
Bagi yang berdosa, Tuhanku akan menghukum..."]]
  },
  AvgDialog_54067_Content_15 = {
    Text = "BLARR——"
  },
  AvgDialog_54067_Content_150 = {
    Text = "Guncangan tak kunjung berhenti, cahaya seolah meredup. Dari lautan di kejauhan, menjulang sebuah dinding biru tua yang menjangkau langit—"
  },
  AvgDialog_54067_Content_151 = {
    Text = "Lautan bangkit berdiri, bagai raksasa yang terbangun, melangkah menuju Lemuria."
  },
  AvgDialog_54067_Content_152 = {
    Text = "Di hadapan lautan, kerajaan megah ini sekecil daun kering, serapuh daun kering."
  },
  AvgDialog_54067_Content_153 = {
    Text = "\"Yang beriman dengan tulus, Tuhan kami akan melindungi.\""
  },
  AvgDialog_54067_Content_154 = {
    Text = "\"Bagi yang berharap, Tuhanku akan mengabulkan... akan mengabulkan...\""
  },
  AvgDialog_54067_Content_155 = {
    Text = "Badai yang murka menerjang kuil yang rapuh, menyobek lempengan batu yang berat dan fondasi yang kokoh."
  },
  AvgDialog_54067_Content_156 = {
    Text = "Sisa cahaya terakhir hampir sepenuhnya terhalang oleh lautan yang berdiri tegak. Di antara reruntuhan yang gelap dan hancur, dia memeluk erat makhluk ikan dalam dekapannya."
  },
  AvgDialog_54067_Content_157 = {
    Text = "Napas kematian dari kedalaman lautan menyelimutinya. Air mata memenuhi kedua matanya."
  },
  AvgDialog_54067_Content_159 = {
    Text = "\"Tuhanku... imanku bersamaMu, hingga akhir bintang-bintang...\""
  },
  AvgDialog_54067_Content_16 = {
    Text = "Sebuah petir menggelegar di langit Lemuria."
  },
  AvgDialog_54067_Content_160 = {
    Text = "\"Engkau tidak membohongiku, kerajaan ilahi akan datang, bukan begitu, Tuhanku?\""
  },
  AvgDialog_54067_Content_161 = {
    Text = "Untuk terakhir kalinya, dia mendongakkan kepala, menatap putus asa ke tempat patung sang Raja pernah berdiri."
  },
  AvgDialog_54067_Content_162 = {
    Text = "Di sana tidak ada patung, juga tidak ada Raja."
  },
  AvgDialog_54067_Content_164 = {
    Text = "<Big:GRAAAAK————>"
  },
  AvgDialog_54067_Content_165 = {
    Text = "Lautan tiba di hadapan sang daun kering."
  },
  AvgDialog_54067_Content_167 = {
    Text = "Kalender Lama tahun @3, Lemuria tenggelam ke dasar laut, tak ada yang selamat."
  },
  AvgDialog_54067_Content_17 = {
    Text = "Suara dahsyat itu membuat kerumunan mulai terdiam."
  },
  AvgDialog_54067_Content_18 = {
    Text = "Bencana Alam... Bencana Alam datang lagi?"
  },
  AvgDialog_54067_Content_19 = {
    Text = "Tuan Pendeta Agung... apakah ini... Bencana Alam akan segera datang?"
  },
  AvgDialog_54067_Content_2 = {
    Text = "Angin kencang yang meraung membawa hujan lebat, menyiram orang-orang di alun-alun."
  },
  AvgDialog_54067_Content_20 = {
    Text = "Bencana Alam tidak pernah menghilang. Lemuria tertidur bersama Bencana Alam."
  },
  AvgDialog_54067_Content_21 = {
    Text = "Tapi Lemuria juga tetap ada selama ini, bukan?"
  },
  AvgDialog_54067_Content_22 = {
    Text = "Benar... benar..."
  },
  AvgDialog_54067_Content_23 = {
    Text = "Tuan Pendeta Agung, Kerajaan Ilahi... kapan Kerajaan Ilahi akan tiba?"
  },
  AvgDialog_54067_Content_24 = {
    Text = "Segera, temanku."
  },
  AvgDialog_54067_Content_25 = {Text = "Segera?!"},
  AvgDialog_54067_Content_26 = {
    Text = "Ya, segera..."
  },
  AvgDialog_54067_Content_27 = {
    Text = "Myriam meninggalkan perlindungan para pengawal dan menuju ke tepi altar persembahan."
  },
  AvgDialog_54067_Content_28 = {
    Text = "Tak terhitung tangan terulur, para pengikut berdesakan ke arahnya, ingin mendapatkan berkat dari Pendeta Agung Lemuria."
  },
  AvgDialog_54067_Content_29 = {
    Text = "Ia menyapukan pandangan, tatapannya tenang dengan senyum tersungging, namun sorot mata itu membuat kebisingan para pengikut segera mereda."
  },
  AvgDialog_54067_Content_3 = {
    Text = "Sudah lama orang-orang tidak melihat hujan lebat seperti ini, tetapi teriakan mereka masih mampu mengalahkan raungan pulau."
  },
  AvgDialog_54067_Content_30 = {
    Text = "Di tengah deru angin dan hujan, ia mengulurkan tangan dan menyentuh dahi pengikut itu."
  },
  AvgDialog_54067_Content_31 = {
    Text = "Sang pengikut menangkupkan kedua tangan di dada dan berlutut di tanah."
  },
  AvgDialog_54067_Content_32 = {
    Text = "Selama kau beriman kepada Raja, Raja akan menjawab imanmu..."
  },
  AvgDialog_54067_Content_33 = {
    Text = "Jadi, katakan padaku, apakah kau beriman kepada Raja? Apakah kau bersedia mempersembahkan segalanya kepada Raja?"
  },
  AvgDialog_54067_Content_34 = {
    Text = "Aku beriman kepada Raja, Tuan Pendeta Agung! Aku bersedia mempersembahkan segalanya kepada Raja!"
  },
  AvgDialog_54067_Content_35 = {
    Text = "Aku adalah pengikut paling setia Raja!"
  },
  AvgDialog_54067_Content_36 = {
    Text = "Aku bersedia! Yang Mulia Pendeta Agung, aku bersedia!"
  },
  AvgDialog_54067_Content_37 = {
    Text = "Maka sekarang, ucapkanlah bersama denganku nama sang Raja—"
  },
  AvgDialog_54067_Content_38 = {
    Text = "Ia memandang ke sekeliling, menatap setiap orang di alun-alun."
  },
  AvgDialog_54067_Content_39 = {
    Text = "Di tengah badai dahsyat, semua orang berlutut, merentangkan kedua tangan, memandang ke arah takhta di dalam kuil."
  },
  AvgDialog_54067_Content_4 = {
    Text = "Pendeta Agung! Pendeta Agung membawakan titah suci dari Sang Raja untuk kita!"
  },
  AvgDialog_54067_Content_40 = {
    Text = "Di bawah langit bertabur bintang, di atas kerajaan kuno dasar laut, kami berdoa dengan khusyuk kepada Tuan kami:"
  },
  AvgDialog_54067_Content_41 = {
    Text = [[
Semoga mata bijaksana-Mu melihat segala malapetaka,
Semoga kebijaksanaan-Mu menuntun umat-Mu.]]
  },
  AvgDialog_54067_Content_42 = {
    Text = [[
"Semoga mata bijaksana-Mu melihat segala malapetaka,
Semoga kebijaksanaan-Mu menuntun umat-Mu!"]]
  },
  AvgDialog_54067_Content_43 = {
    Text = [[
Badai mereda, air tenang tak bergelombang;
Guncangan berhenti, bumi damai sentosa.]]
  },
  AvgDialog_54067_Content_44 = {
    Text = [[
Malapetaka lenyap menjadi kehampaan dalam mimpi damai-Mu.
Dalam perlindungan-Mu, kami menyambut kerajaan para dewa.]]
  },
  AvgDialog_54067_Content_45 = {
    Text = "\"Malapetaka lenyap menjadi kehampaan dalam mimpi damai-Mu!\""
  },
  AvgDialog_54067_Content_46 = {
    Text = "\"Dalam perlindungan-Mu,\nkami menyambut kerajaan para dewa……\""
  },
  AvgDialog_54067_Content_47 = {Text = "Grrmm..."},
  AvgDialog_54067_Content_48 = {
    Text = "Di tengah gemuruh, beberapa tentakel raksasa menerobos keluar dari bawah kuil."
  },
  AvgDialog_54067_Content_49 = {
    Text = "Itu sang Raja! Mukjizat sang Raja telah menampakkan diri!!!"
  },
  AvgDialog_54067_Content_5 = {
    Text = "Puji Tuan kita! Puji Pendeta Agung!"
  },
  AvgDialog_54067_Content_50 = {
    Text = "Para pengikut merentangkan kedua tangan, bersorak-sorai dengan penuh kegilaan."
  },
  AvgDialog_54067_Content_51 = {
    Text = "Tentakel-tentakel itu berayun perlahan di tengah badai. Seluruh penduduk Lemuria tidak sedikitpun meragukan bahwa dewa agung Lemuria ini memiliki kekuatan untuk menangkal segala bencana."
  },
  AvgDialog_54067_Content_52 = {
    Text = "Wahai Tuan kami, Thulu—"
  },
  AvgDialog_54067_Content_53 = {
    Text = "Wahai Tuan kami, Thulu!! Thulu!!!"
  },
  AvgDialog_54067_Content_54 = {
    Text = "Ia berbalik, memandang ke arah bagian dalam kuil, lalu berlutut di tanah."
  },
  AvgDialog_54067_Content_55 = {
    Text = "Di balik mata yang tak seorang pun dapat melihatnya, tak ada lagi harapan dan keagungan seorang Pendeta Agung, yang tersisa hanyalah kebingungan."
  },
  AvgDialog_54067_Content_56 = {
    Text = "Dengarkanlah seruan para pengikut-Mu. Bawalah bagi kami, kerajaan para dewa."
  },
  AvgDialog_54067_Content_57 = {
    Text = "Tolong bawakan kami, Kerajaan Tuhan!"
  },
  AvgDialog_54067_Content_58 = {
    Text = "Tuanku! Kerajaan Tuhan! Hahaha... Kerajaan Tuhan akan segera turun!"
  },
  AvgDialog_54067_Content_59 = {
    Text = "Diiringi teriakan penuh kegilaan, tentakel-tentakel mulai menari. Aura ketenangan laut dalam mengalir dari tentakel itu, menyebar dari kuil ke setiap jengkal tanah Lemuria, merasuk ke dalam indra setiap penduduk Lemuria."
  },
  AvgDialog_54067_Content_6 = {
    Text = "Pendeta Agung akan membawa kita menuju Kerajaan Dewa!"
  },
  AvgDialog_54067_Content_60 = {
    Text = "BLARR——"
  },
  AvgDialog_54067_Content_61 = {
    Text = "Di tengah gemuruh guntur, sorak-sorai mereda. Kilat menyambar dari langit, menerangi tanah Lemuria yang sunyi."
  },
  AvgDialog_54067_Content_62 = {
    Text = "Di momen pesta kegembiraan ini, gerakan para pengikut terhenti, membeku dalam pujian dan keimanan tertinggi kepada sang Raja, membeku dalam khayalan dan harapan tak terbatas akan masa depan."
  },
  AvgDialog_54067_Content_63 = {
    Text = "Di bawah hujan lebat, anak-anak Lemuria terlelap dalam mimpi."
  },
  AvgDialog_54067_Content_65 = {
    Text = "Suara pintu batu yang menutup terasa panjang dan berat."
  },
  AvgDialog_54067_Content_66 = {
    Text = "Bau amis ikan yang menyengat memenuhi seluruh ruangan. Ruang doa yang semula lapang, kini terasa sangat sesak."
  },
  AvgDialog_54067_Content_67 = {
    Text = "Semua manusia ikan telah diangkat dari kolam dan diletakkan di lantai ruang doa."
  },
  AvgDialog_54067_Content_68 = {
    Text = "Para pengawal tidak tahu apa yang ingin dilakukan oleh pendeta agung baru ini, dan mereka juga tidak akan pernah punya kesempatan untuk mengetahuinya lagi."
  },
  AvgDialog_54067_Content_69 = {
    Text = "Miriam mendatangi sudut ruangan, berjongkok, dan membelai manusia ikan yang paling dekat dengannya."
  },
  AvgDialog_54067_Content_7 = {
    Text = "Sorak-sorai yang membara bagaikan gelombang laut, bergulung menuju altar persembahan."
  },
  AvgDialog_54067_Content_70 = {
    Text = "\"Ayah... apakah itu kau?\""
  },
  AvgDialog_54067_Content_71 = {
    Text = "\"Aku Miriam, putrimu.\""
  },
  AvgDialog_54067_Content_72 = {
    Text = "\"Jika kau bisa mendengarku, jawablah aku, ya? Ayah...\""
  },
  AvgDialog_54067_Content_73 = {
    Text = "\"...uuu...uuu...\""
  },
  AvgDialog_54067_Content_74 = {
    Text = "Insang manusia ikan itu membuka dan menutup, bibirnya bergerak-gerak, mengeluarkan rintihan tanpa makna, tidak berbeda sedikit pun dari suaranya di hari-hari biasa."
  },
  AvgDialog_54067_Content_75 = {
    Text = "Miriam berjalan menuju yang kedua, berjongkok, dan membelainya."
  },
  AvgDialog_54067_Content_76 = {
    Text = "\"Ayah, aku telah menjadi pendeta agung Lemuria. Aku melakukan lebih baik dari apa yang pernah kau impikan...\""
  },
  AvgDialog_54067_Content_77 = {
    Text = "\"Aku tidak mengecewakanmu, Ayah... Bukalah matamu dan lihatlah aku...\""
  },
  AvgDialog_54067_Content_78 = {
    Text = "Mata besar manusia ikan itu menatap ke sana kemari ke tempat asing ini, tanpa sedikit pun ketertarikan pada pendeta agung di hadapannya."
  },
  AvgDialog_54067_Content_79 = {
    Text = "Dia berjalan menuju yang ketiga."
  },
  AvgDialog_54067_Content_8 = {
    Text = "Kerumunan bergerak bergelombang, mengingatkan Miriam akan ikan-ikan bermata melotot di dalam kolam."
  },
  AvgDialog_54067_Content_80 = {
    Text = "\"Aku bertemu dengan Raja, Raja yang kita sembah... Tapi Raja memberitahuku, Lemuria akan segera musnah.\""
  },
  AvgDialog_54067_Content_81 = {
    Text = "\"Raja berkata, aku bisa menyelamatkan Lemuria, aku bisa membawa Lemuria kembali...\""
  },
  AvgDialog_54067_Content_82 = {
    Text = "\"Aku tak bisa memercayai kata-kata Raja, tapi kalau begitu, aku hanya bisa percaya bahwa kita selama ini hidup dalam kebohongan, semua yang kita lakukan, semua yang kulakukan padamu... hal-hal itu, semuanya tak berarti apa-apa.\""
  },
  AvgDialog_54067_Content_83 = {
    Text = "\"Aku tidak tahu, aku tidak tahu... Ayah, apa yang harus kulakukan?\""
  },
  AvgDialog_54067_Content_84 = {
    Text = "\"Buka matamu dan lihatlah aku, Ayah... Bicaralah padaku, usap kepalaku sekali lagi, sekali saja...\""
  },
  AvgDialog_54067_Content_85 = {
    Text = "Manusia ikan itu menatapnya. Tatapan kosong, seolah sedang menatap serumpun rumput laut ungu yang bergoyang."
  },
  AvgDialog_54067_Content_86 = {
    Text = "Miriam berjalan menuju yang berikutnya, lalu berikutnya lagi... Dia berjongkok, membelai mereka satu per satu, mencium mereka."
  },
  AvgDialog_54067_Content_87 = {
    Text = "Guru memberinya tanggung jawab, Raja memberinya harapan. Namun orang yang bisa mendengarkan kebingungan dan penderitaannya, orang yang bisa mengusap kepalanya untuk menghiburnya, sudah lama tiada."
  },
  AvgDialog_54067_Content_88 = {
    Text = "Dia mendekatkan diri ke telinga mereka satu per satu, mencurahkan isi hatinya, mencari di antara mereka."
  },
  AvgDialog_54067_Content_89 = {
    Text = "Apakah ayahnya masih hidup? Manusia ikan yang selamat itu, masih bisakah dianggap sebagai ayahnya?"
  },
  AvgDialog_54067_Content_9 = {
    Text = "Seolah tenggelam ke dasar laut, air laut memenuhi seluruh indranya. Gambaran menjadi kabur, suara menjadi kacau."
  },
  AvgDialog_54067_Content_90 = {
    Text = "Dia tidak tahu. Dia tidak peduli."
  },
  AvgDialog_54067_Content_91 = {
    Text = "Suara hujan lebat menembus dinding masuk ke dalam. Di ruang doa yang luas itu, tak terhitung manusia ikan berbaring di lantai, menggerakkan anggota tubuh dan sirip ekor mereka."
  },
  AvgDialog_54067_Content_92 = {
    Text = "Sosok berwarna ungu, berjalan di antara manusia-manusia ikan ini, mencari, bertutur."
  },
  AvgDialog_54067_Content_93 = {
    Text = "Separuh patung yang rusak, duduk tegak di atas singgasana yang tak utuh, menatapnya dalam diam."
  },
  AvgDialog_54067_Content_95 = {
    Text = "BLARR——"
  },
  AvgDialog_54067_Content_96 = {
    Text = "Petir menggelegar di atas kepala sang lelaki tua. Dia tak menghiraukannya, dan menaiki anak tangga batu yang terakhir."
  },
  AvgDialog_54067_Content_97 = {
    Text = "\"Hah... hah...\""
  },
  AvgDialog_54067_Content_98 = {
    Text = "Dia sudah terlalu tua, mendaki gunung ini sendirian adalah hal yang begitu sulit baginya."
  },
  AvgDialog_54067_Content_99 = {
    Text = "Dia terduduk lemas di puncak gunung yang gundul, terengah-engah dengan napas berat, rongga parunya bagaikan kincir angin berkarat, mengeluarkan rintihan tua yang pilu."
  },
  AvgDialog_54802_Content_1 = {Text = "Ah!——"},
  AvgDialog_54802_Content_10 = {
    Text = "Di sana... di sana adalah..."
  },
  AvgDialog_54802_Content_100 = {
    Text = "Tangan yang penuh luka itu menyodorkan sebuah mawar yang agak rusak namun tetap segar merah ke hadapan Horla."
  },
  AvgDialog_54802_Content_101 = {
    Text = "Sebuah puisi yang indah, Horla… Mulai sekarang, aku akan menukar bunga-bungaku dengan puisi-puisimu!"
  },
  AvgDialog_54802_Content_11 = {
    Text = "Kalian berdiri di alun-alun tepi taman. D-rongga yang terlihat jelas merambat dari bawah gedung ke atas, mencakup area kosong di tengah taman."
  },
  AvgDialog_54802_Content_12 = {
    Text = "Itu... taman kita... tidak... Colette, tidak..."
  },
  AvgDialog_54802_Content_13 = {
    Text = "Horla menundukkan kepalanya. Colette mendekatinya, mengangkat dagunya, dan membuatnya memandang ke arah tengah taman."
  },
  AvgDialog_54802_Content_14 = {
    Text = "Apakah kamu tahu, Horla? Banyak tahun yang lalu, di tempat inilah aku melihat api besar itu mulai menyala."
  },
  AvgDialog_54802_Content_15 = {
    Text = "Saya telah mengubah tempat ini menjadi alun-alun, dan di sini saya mendirikan patung saya sendiri… Lihat, saya juga paham akan simbolisme."
  },
  AvgDialog_54802_Content_16 = {
    Text = "Lihat. Lihat dengan jelas. Itulah tempat kita tinggal... itulah taman kita. Segera, segala sesuatu di sana akan lenyap."
  },
  AvgDialog_54802_Content_17 = {
    Text = "Hidupku, secara resmi dimulai pada hari kau meninggal. Hari ini, ia akan kembali menuju kejayaan di sini…"
  },
  AvgDialog_54802_Content_18 = {
    Text = "Celah hitam dengan cepat menyebar. Dalam waktu singkat, vila yang megah itu sepenuhnya ditelan."
  },
  AvgDialog_54802_Content_19 = {
    Text = "Taman, abu, gambar sketsa, puisi, memori, tawa, sumpah… semuanya tenggelam ke dalam kegelapan tanpa ujung."
  },
  AvgDialog_54802_Content_2 = {
    Text = "Serangan kalian berhasil menjatuhkan Colette, tetapi pada saat kalian mendekat, tak terhitung banyaknya sulur bunga muncul dari tanah di sekitar tubuhnya."
  },
  AvgDialog_54802_Content_20 = {Text = "Tik——"},
  AvgDialog_54802_Content_21 = {
    Text = "Eh? Mataku, ada apa ini……"
  },
  AvgDialog_54802_Content_22 = {
    Text = "Perasaan seperti tadi adalah... rasa sakit di hati? Mengapa bisa..."
  },
  AvgDialog_54802_Content_23 = {
    Text = "Sebuah tetesan air mata meluncur di wajah Horla."
  },
  AvgDialog_54802_Content_24 = {
    Text = "Air mata jatuh ke tanah, seperti jatuh ke permukaan danau yang tenang tanpa riak. Riak yang tenang itu menyebar tanpa suara, menyapu dunia ilusi ini dan melewati semua hati yang pucat."
  },
  AvgDialog_54802_Content_25 = {
    Text = "!! Tidak... perasaan ini.."
  },
  AvgDialog_54802_Content_26 = {
    Text = "Colette menyadari perubahan emosinya. Dia menatap Horla di sisinya dengan rasa heran."
  },
  AvgDialog_54802_Content_27 = {
    Text = "<LightGray:Ini adalah… kemampuan Horla untuk menyebarkan emosi?!>"
  },
  AvgDialog_54802_Content_28 = {
    Text = "<LightGray:Domain ini didasarkan pada puisi Horla… Kemampuan miliknya mungkin bisa berperan!>"
  },
  AvgDialog_54802_Content_29 = {
    Text = "Kau ingin membunuhku, menukar puisi untuk mendapatkan kehidupan yang kau inginkan… Apa pun yang kau lakukan, aku tak pernah membencimu, Colette."
  },
  AvgDialog_54802_Content_3 = {
    Text = "Duri-duri di tanaman merambat menusuk tubuh kalian dan mengikat kalian dengan kuat."
  },
  AvgDialog_54802_Content_30 = {
    Text = "Colette yang dulu adalah teman terbaikku. Namun, jika kau menghancurkan tempat ini... maka hanya Colette saat ini yang tersisa."
  },
  AvgDialog_54802_Content_31 = {
    Text = "Aku tidak bisa... melihat Colette yang dulu, dihapus olehmu..."
  },
  AvgDialog_54802_Content_32 = {
    Text = "Lihatlah dirimu, Horla... apa lagi yang bisa kau lakukan selain menulis puisi?"
  },
  AvgDialog_54802_Content_33 = {
    Text = "Kamu benar… aku tidak bisa apa-apa selain menulis puisi…"
  },
  AvgDialog_54802_Content_34 = {
    Text = "Cité adalah kota bunga dan puisi, rumah kita... tapi mawar di sini semua mati, Colette..."
  },
  AvgDialog_54802_Content_35 = {
    Text = "Mawar-mawar ini adalah yang pernah kau berikan padaku. Hari ini, aku mengembalikannya kepadamu."
  },
  AvgDialog_54802_Content_36 = {
    Text = "Dia melangkah maju."
  },
  AvgDialog_54802_Content_37 = {Text = "Horla!!!"},
  AvgDialog_54802_Content_38 = {
    Text = "Duri mawar raksasa menembus jantungnya."
  },
  AvgDialog_54802_Content_39 = {
    Text = "Darahnya mengalir menyusuri sulur-sulur hitam."
  },
  AvgDialog_54802_Content_4 = {
    Text = "Kamu... telah mengotori pakaianku..."
  },
  AvgDialog_54802_Content_40 = {
    Text = "Bunga hitam dengan cepat layu di ujung dahan."
  },
  AvgDialog_54802_Content_41 = {
    Text = "Mawar merah yang mulai menampakkan kuncupnya dari cabang, perlahan mekar, dan akhirnya sepenuhnya terbuka."
  },
  AvgDialog_54802_Content_42 = {
    Text = "Darah mengalir melalui sulur-sulur, seperti urat daun, ke seluruh penjuru kota."
  },
  AvgDialog_54802_Content_43 = {
    Text = "Di tempat yang dilaluinya, kegelapan hitam lenyap."
  },
  AvgDialog_54802_Content_44 = {
    Text = "Itu mengembalikan warna dan emosi, bunga serta puisi kepada Cité."
  },
  AvgDialog_54802_Content_45 = {
    Text = "Baik... sangat sakit..."
  },
  AvgDialog_54802_Content_46 = {
    Text = "Jantung... seperti tertusuk..."
  },
  AvgDialog_54802_Content_47 = {
    Text = "Itu... Ibu! Ibu..."
  },
  AvgDialog_54802_Content_48 = {
    Text = "Anak... anak saya telah lahir..."
  },
  AvgDialog_54802_Content_49 = {
    Text = "Seiring dengan menyebarluasnya darah, serangkaian gambaran muncul di hadapan orang-orang."
  },
  AvgDialog_54802_Content_5 = {
    Text = "Apakah kamu tahu berapa banyak uang yang dihabiskan untuk membeli pakaian ini?"
  },
  AvgDialog_54802_Content_50 = {
    Text = "Itu adalah kelahiran baru seorang bayi, nyanyian pengantar tidur seorang ibu, dan perpisahan terakhir para kekasih."
  },
  AvgDialog_54802_Content_51 = {
    Text = "Itu adalah momen paling berharga dalam hidup kalian."
  },
  AvgDialog_54802_Content_53 = {
    Text = "Rasa sakit yang luar biasa dialami oleh Horla, bersamaan dengan darahnya, menyebar seperti riak ke seluruh Cité."
  },
  AvgDialog_54802_Content_54 = {
    Text = "Duri mawar menembus tak terhitung banyaknya jantung. Bunga merah segar mekar di hati setiap orang."
  },
  AvgDialog_54802_Content_55 = {
    Text = "Ini adalah... puisi yang kau tulis, kan...?"
  },
  AvgDialog_54802_Content_56 = {
    Text = "Air mata menghapus riasan halusnya. Dia sama sekali tidak peduli, membiarkannya meninggalkan jejak kacau yang tidak pantas di wajahnya."
  },
  AvgDialog_54802_Content_57 = {
    Text = "Colette lupa, sejak kapan air matanya mulai mengalir."
  },
  AvgDialog_54802_Content_58 = {
    Text = "——Gambar-gambar masa lalu terbentang jelas di depan matanya. Ini adalah pertama kalinya dia benar-benar memahami puisi Horla. Akhirnya, dia mengerti apa yang paling dia hargai."
  },
  AvgDialog_54802_Content_59 = {
    Text = "Bukan hanya dia. Semua orang di Cité ini telah memahami puisi Horla."
  },
  AvgDialog_54802_Content_6 = {
    Text = "Kemarahan Colette segera menghilang. Dia kembali memasang senyuman anggun yang pantas bagi seorang bangsawan."
  },
  AvgDialog_54802_Content_60 = {
    Text = "Nafsu kekuasaan memudar, dan emosi mulai kembali. Fondasi yang membangun dunia ini lenyap tanpa jejak dalam sajak ini."
  },
  AvgDialog_54802_Content_61 = {
    Text = "Dia merasakan kekuatan menghilang. Dia merasakan kedatangan kegagalan. Dia memanggil duri tajam seperti belati dan melangkah menuju Horla."
  },
  AvgDialog_54802_Content_62 = {
    Text = "\"Collette\", kemenangan... Anjing Nyonya Tua telah mati, dan ketika dia memberikan nama anjing itu kepadaku, kamu berada di sampingku."
  },
  AvgDialog_54802_Content_63 = {
    Text = "Nama ini belum pernah aku ganti. Karena aku tidak mau kalah lagi, Horla…"
  },
  AvgDialog_54802_Content_64 = {
    Text = "Colette menangis dalam kesakitan, langkahnya tersaruk-saruk, perlahan mendekati Horla."
  },
  AvgDialog_54802_Content_65 = {
    Text = "Domain menghilang, rencanamu telah gagal, Colette!"
  },
  AvgDialog_54802_Content_66 = {
    Text = "Meskipun kamu bertindak terhadapnya sekarang, itu tidak akan mengubah apa pun!"
  },
  AvgDialog_54802_Content_67 = {
    Text = "Kamu berjuang, ingin mendekati Horla. Duri dan rasa sakit mengelilingi tubuhmu, membuatmu tak bisa bergerak."
  },
  AvgDialog_54802_Content_68 = {
    Text = "Duri menjulur ke arah kepala Horla."
  },
  AvgDialog_54802_Content_69 = {Text = "Tunggu!!"},
  AvgDialog_54802_Content_7 = {
    Text = "Tidak apa-apa, tidak apa-apa…"
  },
  AvgDialog_54802_Content_70 = {
    Text = "Kraak——"
  },
  AvgDialog_54802_Content_71 = {
    Text = "Sebuah mawar dipotong. Colette mengambilnya dan menyodorkannya kepada Horla."
  },
  AvgDialog_54802_Content_72 = {
    Text = "Sebuah puisi yang indah, Horla... Aku akan menukar bunga-bungaku dengan puisi-puisimu..."
  },
  AvgDialog_54802_Content_73 = {Text = "BRAK—"},
  AvgDialog_54802_Content_74 = {
    Text = "Mungkin karena lenyapnya Domain membuat Peramu Bunga berubah."
  },
  AvgDialog_54802_Content_75 = {
    Text = "Atau mungkin perubahan yang dibuat oleh tukang kebun menyebabkan Domain lenyap."
  },
  AvgDialog_54802_Content_76 = {
    Text = "Cité dalam kumpulan puisi perlahan memudar, kekuatan yang menopang Colette juga tidak ada lagi."
  },
  AvgDialog_54802_Content_77 = {
    Text = "Tubuhnya berubah menjadi genangan lumpur hitam yang bercampur dengan kelopak-kelopak bunga yang berserakan, lalu tenggelam ke dalam tanah di depan Horla."
  },
  AvgDialog_54802_Content_78 = {
    Text = "Colette, apakah kamu sudah selesai membaca?"
  },
  AvgDialog_54802_Content_79 = {
    Text = "Hmm… sudah selesai membacanya… tapi sepertinya aku tidak terlalu paham."
  },
  AvgDialog_54802_Content_8 = {
    Text = "Ingin mengalahkanku di tamanku, sangat berani, dan juga sangat bodoh."
  },
  AvgDialog_54802_Content_80 = {
    Text = "Ah, begitu ya… Ini adalah puisi pertama yang kutulis, tidak terlalu bagus…"
  },
  AvgDialog_54802_Content_81 = {
    Text = "Bukan salahmu, Horla. Aku tidak mengerti puisi siapa pun."
  },
  AvgDialog_54802_Content_82 = {
    Text = "Saya bertanya kepada banyak orang di sekitar saya, tetapi mereka juga tidak mengerti."
  },
  AvgDialog_54802_Content_83 = {
    Text = "Saya tidak terlalu mengerti, apa artinya sesuatu yang tidak bisa dimengerti oleh semua orang…"
  },
  AvgDialog_54802_Content_84 = {
    Text = "Hmm... menurut saya, puisi bukanlah sekadar kata-kata atau gambar, melainkan lebih seperti sebuah kunci."
  },
  AvgDialog_54802_Content_85 = {Text = "Kunci?"},
  AvgDialog_54802_Content_86 = {
    Text = "Benar! Hati setiap orang seperti sebuah kotak, di dalamnya terdapat banyak sekali perasaan. Kotak ini terkunci, dan perasaan-perasaan itu biasanya terkurung di dalam kotak, ingin mengambilnya pun tidak bisa."
  },
  AvgDialog_54802_Content_87 = {
    Text = "Puisi adalah kunci untuk membuka kotak ini."
  },
  AvgDialog_54802_Content_88 = {
    Text = "Sebenarnya, puisi tidak perlu dipahami, bahkan tidak perlu dibaca."
  },
  AvgDialog_54802_Content_89 = {
    Text = "Setiap orang, baik membaca puisi atau tidak, cepat atau lambat, pada suatu saat dalam hidup mereka, pasti akan menemukan kunci ini."
  },
  AvgDialog_54802_Content_9 = {
    Text = "Kalian telah menyia-nyiakan kesempatan terakhir untuk melarikan diri... Perayaan ini, kalian harus menemaniku sampai akhir."
  },
  AvgDialog_54802_Content_90 = {
    Text = "Kalau begitu, kamu pasti akan menjadi tukang Kunci terbaik!"
  },
  AvgDialog_54802_Content_91 = {
    Text = "Menipu... Baru saja kamu bilang tidak mengerti."
  },
  AvgDialog_54802_Content_92 = {
    Text = "Aku tidak mengerti apa yang kamu katakan. Namun, aku percaya padamu, Horla."
  },
  AvgDialog_54802_Content_93 = {
    Text = "Puisi pertamamu,\"Tempat Tinggal Mawar\", adalah karyamu yang pertama. Mulai hari ini, semua puisimu akan aku simpan dengan baik."
  },
  AvgDialog_54802_Content_94 = {
    Text = "Saya akan menggunakan peniti untuk merapikannya menjadi satu, dan jika saya punya uang nanti, saya akan mencetaknya menjadi sebuah kumpulan Puisi yang indah!"
  },
  AvgDialog_54802_Content_95 = {
    Text = "Dia mengulurkan tangan yang selama ini disembunyikan di belakang tubuhnya. Tangan itu penuh dengan luka bekas duri, hitam dan kasar, sehingga sepenuhnya tidak terlihat seperti tangan seorang gadis."
  },
  AvgDialog_54802_Content_96 = {
    Text = "I-ini... Ini adalah..."
  },
  AvgDialog_54802_Content_97 = {
    Text = "Menurut para bangsawan baru, Cité adalah kota bunga dan puisi. Sebuah puisi indah dapat ditukar dengan seikat mawar…"
  },
  AvgDialog_54802_Content_98 = {
    Text = "Mawar yang kutanam mekar hari ini. Meskipun tidak banyak, semuanya sudah kugunakan untuk membayar sewa rumah dan sewa tanah."
  },
  AvgDialog_54802_Content_99 = {
    Text = "Namun, saat mereka tidak memperhatikan, aku diam-diam meninggalkan satu bunga…"
  },
  AvgDialog_56163_Content_1 = {
    Text = "Karena belakangan ini para Awakened sering mengalami kondisi abnormal, pihak sekolah memutuskan untuk memperkuat pemantauan terhadap kondisi para Awakened, dengan inspeksi kamar rutin untuk mencegah insiden."
  },
  AvgDialog_56163_Content_10 = {
    Text = "Kau merasa lega, menghembuskan napas karena tidak perlu menghadapi wanita gila itu."
  },
  AvgDialog_56163_Content_11 = {
    Text = "Namun pengalaman dan instingmu sebagai penyelidik tiba-tiba merasakan kejanggalan. Kau menghentikan langkah dan mengamati cahaya lilin itu dengan saksama."
  },
  AvgDialog_56163_Content_12 = {
    Text = "Bayangan-bayangan gelap terpantul di dinding oleh cahaya lilin. Yang bergoyang-goyang itu bukanlah nyala lilin, melainkan jelas-jelas bayangan ular-ular yang meliuk dan berbelit-belit."
  },
  AvgDialog_56163_Content_13 = {
    Text = "Bayangan ular-ular mengelilingi cahaya lilin, seolah hendak merenggut satu-satunya kehangatan di dalam ruangan itu."
  },
  AvgDialog_56163_Content_14 = {
    Text = "Miriam menoleh, wajahnya dihiasi rona merah yang tak biasa. Suaranya lembut dan penuh kebahagiaan, bagai seseorang yang telah menerima anugerah ilahi."
  },
  AvgDialog_56163_Content_15 = {
    Text = "Oh, ternyata Anda, Penjaga Rahasia. Apakah Anda datang karena merasakan panggilan dari Kerajaan Tuhan?"
  },
  AvgDialog_56163_Content_16 = {
    Text = "Anggota tubuhnya yang pucat dan kurus dibelit bayangan ular yang bergerak-gerak, namun kedua tangannya tetap mempertahankan pose berdoa, bagaikan seorang biarawati yang terikat, terbekukan dalam misi yang abadi."
  },
  AvgDialog_56163_Content_17 = {
    Text = "Otakmu berteriak bahaya, tetapi keputusan untuk mundur sudah terlambat selangkah. Bayangan ular yang basah dan dingin telah lama merayap dalam kegelapan, membelit erat kedua kakimu, merambat naik ke pinggang dan punggungmu."
  },
  AvgDialog_56163_Content_18 = {
    Text = "Tubuh Anda sungguh hangat..."
  },
  AvgDialog_56163_Content_19 = {
    Text = "Jelas kau telah menggantikan cahaya lilin yang redup, menjadi sumber panas terbesar di ruangan ini."
  },
  AvgDialog_56163_Content_2 = {
    Text = "Untuk mengantisipasi kemungkinan Awakened mengamuk, tugas inspeksi kamar digilirkan kepada setiap penyelidik yang sedang senggang. Hari ini kebetulan giliranmu menjadi pengawas asrama."
  },
  AvgDialog_56163_Content_20 = {
    Text = "Tidak tidak tidak, kau pasti salah paham! Aku tidak mendengar panggilan dari Kerajaan Tuhan, aku hanya datang untuk memeriksa kamar!"
  },
  AvgDialog_56163_Content_21 = {
    Text = "Penjelasanmu yang panik tidak membuahkan hasil apa pun. Bayangan ular menyeretmu ke meja doa, mendudukkanmu di samping Miriam di hadapan patung bertentakel yang menjulur itu."
  },
  AvgDialog_56163_Content_22 = {
    Text = "Sudah lama sekali aku tidak merasakan kegembiraan dan keharuan seperti ini. Kerajaan Tuhan, Kerajaan Tuhan telah menjawabku!"
  },
  AvgDialog_56163_Content_23 = {
    Text = "Kau ingin sekali membuka mulut untuk menyangkal dan mengungkapkan kebenaran, tetapi melihat ekspresi penuh keterpesonaan di wajahnya, kau dengan bijak menelan kembali kata-katamu."
  },
  AvgDialog_56163_Content_24 = {
    Text = "Kerajaan Tuhan mendesakku untuk melakukan sesuatu. Aku harus mematuhi kehendak ini."
  },
  AvgDialog_56163_Content_25 = {
    Text = "Sekarang, kehendak ini telah mengirimkan Anda kepadaku."
  },
  AvgDialog_56163_Content_26 = {
    Text = "Dia memiringkan kepalanya, ujung jarinya yang sedikit gemetar menyentuh wajahmu, kedua tangannya menangkup pipimu, bagaikan sebuah penghiburan, bagaikan sebuah undangan."
  },
  AvgDialog_56163_Content_27 = {
    Text = "Marilah, berdoalah bersamaku, bersama-samaku... persembahkan segalanya demi kelanjutan Kerajaan Tuhan."
  },
  AvgDialog_56163_Content_28 = {
    Text = "Sentuhan dingin bayangan ular membuatmu menggigil karena kehilangan panas tubuh. Kekuatan penolakanmu diruntuhkan oleh belitan yang keras, memaksa tubuhmu ke dalam pose yang khusyuk."
  },
  AvgDialog_56163_Content_29 = {
    Text = "Bersama pendeta agung yang fanatik ini, kau memulai doa untuk menyenangkan sang dewa."
  },
  AvgDialog_56163_Content_3 = {
    Text = "Kau yang sudah berkali-kali diganggu mengetuk pintu kamar satu per satu dengan was-was, mencatat status normal satu demi satu."
  },
  AvgDialog_56163_Content_4 = {
    Text = "Akhirnya, saat mengetuk salah satu pintu kamar, yang tersisa hanyalah keheningan tanpa jawaban. Hatimu tak bisa menahan diri untuk tidak berdegup kencang, membunyikan alarm dalam batin: \"Akhirnya datang juga.\""
  },
  AvgDialog_56163_Content_5 = {
    Text = "Kau mendongak menatap nama Myriam di papan kamar, lalu membuka pintu dengan wajah serius dan dengan hati-hati menjulurkan setengah badanmu ke dalam."
  },
  AvgDialog_56163_Content_6 = {
    Text = "Myriam? Kau ada di dalam?"
  },
  AvgDialog_56163_Content_7 = {
    Text = "Di dalam ruangan gelap, hanya setitik cahaya lilin yang bergoyang menerangi sudut remang-remang, menyinari wajah sang biarawati yang sedang berdoa dengan khusyuk."
  },
  AvgDialog_56163_Content_8 = {
    Text = "Sosoknya dari belakang tampak tenang dan damai, seperti pertapaan yang telah dijalaninya selama ribuan tahun."
  },
  AvgDialog_56163_Content_9 = {
    Text = "Ternyata kau sedang berdoa, maaf mengganggu. Kalau kau baik-baik saja, aku akan melanjutkan inspeksi."
  },
  AvgDialog_56308_Content_1 = {
    Text = "Panas sekali..."
  },
  AvgDialog_56308_Content_10 = {
    Text = "Sulit untuk mengatakan apakah ini untuk mengalihkan perhatianmu sendiri, atau memang benar-benar penasaran. Kamu mengamati sekelilingmu."
  },
  AvgDialog_56308_Content_11 = {
    Text = "Bunga-bunga yang lebih semarak, cuaca yang lebih terik, arsitektur dan musik yang semakin menggugah hati."
  },
  AvgDialog_56308_Content_12 = {
    Text = "Dunia yang terwujud dari kata-kata, setiap sudutnya adalah metafora dan kiasan."
  },
  AvgDialog_56308_Content_13 = {
    Text = "Maaf, Penjaga Rahasia... Aku juga tidak tahu mengapa... Bait puisi yang kutulis hari ini, selalu... selalu..."
  },
  AvgDialog_56308_Content_14 = {
    Text = "Emosi menyebar seperti riak di ruang ini. Tenggorokanmu sedikit bergerak."
  },
  AvgDialog_56308_Content_15 = {
    Text = "Kamu mengulurkan tangan, melepaskan lembaran kulit domba dari kepala sang gadis."
  },
  AvgDialog_56308_Content_16 = {Text = "Ah!"},
  AvgDialog_56308_Content_17 = {
    Text = "Sang gadis seperti kelinci yang terkejut, sebagian besar sosoknya yang tersembunyi tampak gelisah, wajahnya yang terlihat memerah hingga ke telinga."
  },
  AvgDialog_56308_Content_18 = {
    Text = "Aurla, aku suka puisi ini."
  },
  AvgDialog_56308_Content_19 = {
    Text = "Tapi... tapi puisi ini belum selesai ditulis..."
  },
  AvgDialog_56308_Content_2 = {
    Text = "Rasa gerah yang entah datang dari mana membuatmu membuka mata."
  },
  AvgDialog_56308_Content_20 = {
    Text = "Kalau begitu, mari kita selesaikan bersama."
  },
  AvgDialog_56308_Content_21 = {
    Text = "Ba, baris selanjutnya... harus menulis apa ya..."
  },
  AvgDialog_56308_Content_22 = {
    Text = "Hari telah gelap, semua tatapan telah sirna..."
  },
  AvgDialog_56308_Content_23 = {
    Text = "Matahari dan bintang-bintang telah terbenam..."
  },
  AvgDialog_56308_Content_24 = {
    Text = "...hanya tersisa mawar, diam-diam bersandar di tamannya..."
  },
  AvgDialog_56308_Content_25 = {
    Text = "Kata-kata tak kasat mata muncul di sekelilingnya, taman dalam puisi perlahan meredup."
  },
  AvgDialog_56308_Content_26 = {
    Text = "Suara lembut Aurola semakin mendekat. Kau mendengar napasnya yang halus. Kau merasakan sisa kehangatan dari tubuhnya yang gemetar."
  },
  AvgDialog_56308_Content_27 = {
    Text = "——Di taman yang gelap, kau mengetahui rahasia setangkai mawar."
  },
  AvgDialog_56308_Content_3 = {Text = "!!!"},
  AvgDialog_56308_Content_4 = {
    Text = "Bukankah aku tidur di kamar tidur... Ini di mana?"
  },
  AvgDialog_56308_Content_5 = {
    Text = "Ma, maaf... Penjaga Rahasia..."
  },
  AvgDialog_56308_Content_6 = {
    Text = "Ternyata kamu... Pantas saja."
  },
  AvgDialog_56308_Content_7 = {
    Text = "Kemampuan menyebarkan emosi, bertemu dengan pengaruh Sungai Suci... Sungguh kombinasi yang tak terduga."
  },
  AvgDialog_56308_Content_8 = {
    Text = "Di bawah pengaruh Aurla, akhirnya kamu pun merasakan bagaimana rasanya dipengaruhi oleh Sungai Suci."
  },
  AvgDialog_56308_Content_9 = {
    Text = "Dunia dalam puisi kali ini, sepertinya sedikit berbeda dari sebelumnya?"
  },
  AvgDialog_57563_Content_1 = {
    Text = "Dalam perjalanan pulang setelah menyelesaikan misi lapangan, kau terjebak hujan lebat dan terdampar di pinggiran kota yang jauh dari pusat."
  },
  AvgDialog_57563_Content_10 = {
    Text = "Kau menatap wajah yang familiar di hadapanmu, dan dalam pergulatan, kau memanggil namanya dengan suara serak penuh keterkejutan."
  },
  AvgDialog_57563_Content_11 = {
    Text = "Uhuk… Hi… lo!"
  },
  AvgDialog_57563_Content_12 = {
    Text = "Gadis di hadapanmu sedikit mengangkat alisnya, namun mata merah darahnya tidak menunjukkan ekspresi reuni sahabat lama, hanya ada kedinginan sedalam jurang."
  },
  AvgDialog_57563_Content_13 = {
    Text = "Saat kau mengira nyawamu akan berakhir di tempat ini, sudut bibir gadis itu sedikit terangkat, dan tangan itu akhirnya melepaskan tenggorokanmu."
  },
  AvgDialog_57563_Content_14 = {
    Text = "Ternyata kau rupanya. Sepertinya aku pernah bilang, saat bertemu lagi denganmu, aku akan merobek-robekmu, kan."
  },
  AvgDialog_57563_Content_15 = {
    Text = "Kau berlutut menunduk di tanah, hampir saja batang tenggorokanmu terbatuk keluar, dan baru setelah beberapa saat kau berhasil membalikkan badan dengan susah payah."
  },
  AvgDialog_57563_Content_16 = {
    Text = "Kau tidak akan melakukannya, uhuk uhuk, karena kita adalah, teman…"
  },
  AvgDialog_57563_Content_17 = {
    Text = [[
Melihat jelas sosok utuh gadis di hadapanmu, kau terpaku di tempat.
Seluruh pakaiannya menempel di tubuh, terus meneteskan air hujan. Uap air yang lembap bercampur bau darah, wajah pucatnya masih menyisakan semburat merah yang tampak tidak sehat.]]
  },
  AvgDialog_57563_Content_18 = {
    Text = "Belenggu raksasa menyatu dengan tubuhnya, keempat anggota tubuh yang terhubung rantai besi dipenuhi warna hitam dan merah yang menyeramkan."
  },
  AvgDialog_57563_Content_19 = {
    Text = "Kamu teringat pertemuan di gunung bersalju, dan tanpa sadar menelan ludah."
  },
  AvgDialog_57563_Content_2 = {
    Text = "Untung dalam ketidakberuntungan, kau masih ingat alamat sebuah pabrik terbengkalai di sekitar sini, cukup untuk memberikan perlindungan sementara dari angin dan hujan bagi musafir sial sepertimu."
  },
  AvgDialog_57563_Content_20 = {
    Text = "Sepertinya kamu salah paham tentangku. Jangan samakan aku dengan si lemah itu."
  },
  AvgDialog_57563_Content_21 = {
    Text = "Melihat aura membunuh di matanya kembali menyala, kamu buru-buru menunjukkan kepedulian sebagai teman."
  },
  AvgDialog_57563_Content_22 = {
    Text = "Tidak tidak tidak, selama itu kamu, semuanya adalah temanku!"
  },
  AvgDialog_57563_Content_23 = {
    Text = "Lupakan itu dulu, kamu terluka?"
  },
  AvgDialog_57563_Content_24 = {
    Text = "Ekspresi aneh dan rumit tiba-tiba muncul di wajahnya—dingin, jengkel, dan sedikit kebingungan."
  },
  AvgDialog_57563_Content_25 = {
    Text = "Lukanya tidak parah, tapi sepertinya aku terkena racun. Tubuhku... terasa aneh."
  },
  AvgDialog_57563_Content_26 = {
    Text = "Kemudian keraguan dan kerentanan itu lenyap dalam sekejap, keganasan kembali memenuhi kedua matanya."
  },
  AvgDialog_57563_Content_27 = {
    Text = "Kalau sampai aku menangkap orang yang meracuniku, akan kuremukkan organ dalamnya satu per satu, semuanya."
  },
  AvgDialog_57563_Content_28 = {
    Text = "Kamu yang baru saja ingin menjelaskan tentang pengaruh Sungai Suci langsung berpura-pura tidak terjadi apa-apa, dan mengangguk setuju."
  },
  AvgDialog_57563_Content_29 = {Text = "Mm-hm..."},
  AvgDialog_57563_Content_3 = {
    Text = "Mendengarkan suara hujan yang menghantam atap pabrik dengan keras, kau duduk bersandar di sudut dinding tanpa ada hal yang bisa dilakukan."
  },
  AvgDialog_57563_Content_30 = {
    Text = "Tapi, aku tidak punya yang namanya teman."
  },
  AvgDialog_57563_Content_31 = {
    Text = "Kulit kepalamu langsung menegang."
  },
  AvgDialog_57563_Content_32 = {
    Text = "Tapi auramu bersih, tidak ada niat jahat, tidak ada bau kebohongan."
  },
  AvgDialog_57563_Content_33 = {
    Text = "Gadis itu mengamatimu sekali lagi, tampaknya dengan enggan mulai mempercayaimu."
  },
  AvgDialog_57563_Content_34 = {
    Text = "Dia bersandar di dinding dan duduk, mengambil posisimu yang sebelumnya."
  },
  AvgDialog_57563_Content_35 = {
    Text = "Mengingat kamu sudah membantuku sebelumnya, aku mau istirahat sebentar. Kamu jaga untukku."
  },
  AvgDialog_57563_Content_36 = {
    Text = "Kalau sampai aku tahu kamu melakukan sesuatu yang mencurigakan..."
  },
  AvgDialog_57563_Content_37 = {
    Text = "Kamu langsung menggelengkan kepala, wajahmu penuh kesetiaan."
  },
  AvgDialog_57563_Content_38 = {
    Text = "Mata gadis itu perlahan terpejam, tubuhnya yang basah tanpa sadar meringkuk, seperti binatang liar tanpa rumah di malam hujan."
  },
  AvgDialog_57563_Content_39 = {
    Text = "Tunggu sebentar!"
  },
  AvgDialog_57563_Content_4 = {
    Text = "Rasanya ingin sekali berbaring di kasur besar di asrama…"
  },
  AvgDialog_57563_Content_40 = {
    Text = "Sepasang mata merah yang buas menatapmu dengan penuh ketidak sabaran."
  },
  AvgDialog_57563_Content_41 = {
    Text = "Kamu melepas jaketmu dan dengan lembut meletakkannya di atas tubuh gadis itu."
  },
  AvgDialog_57563_Content_42 = {
    Text = "Dia menundukkan kepalanya dan melihat, lalu tidak menolak."
  },
  AvgDialog_57563_Content_43 = {
    Text = "Gadis yang kelelahan mencengkeram ujung bajumu dalam tidurnya, kebencian dan niat membunuh yang mendalam di antara alisnya untuk sementara lenyap."
  },
  AvgDialog_57563_Content_44 = {
    Text = "Hujan di luar mulai mereda, terdengar suara gemericik di atap."
  },
  AvgDialog_57563_Content_45 = {
    Text = "Di pabrik yang sunyi, hanya tersisa suara napas kalian yang saling tumpang tindih."
  },
  AvgDialog_57563_Content_46 = {
    Text = "Di malam hujan yang panjang, dua musafir kesepian sedang beristirahat."
  },
  AvgDialog_57563_Content_5 = {
    Text = [[
Baru saja hendak memejamkan mata untuk istirahat sejenak, tiba-tiba kau mendengar suara berderit yang membuat gigi ngilu.
Itu adalah suara pintu besar pabrik yang berkarat terbuka.]]
  },
  AvgDialog_57563_Content_6 = {
    Text = "Tidak mengetahui identitas pendatang, kau dengan hati-hati menahan napas dan perlahan berdiri."
  },
  AvgDialog_57563_Content_7 = {
    Text = "Belum sempat kau melakukan pengintaian, tiba-tiba suara tajam membelah udara menghujam di tengah keheningan yang luas."
  },
  AvgDialog_57563_Content_8 = {
    Text = "Kau segera berguling ke samping, dan tempat kau berdiri tadi langsung dihantam bola rantai raksasa hingga membentuk lubang dalam."
  },
  AvgDialog_57563_Content_9 = {
    Text = "Belum sempat kau melihat jelas siapa yang datang, sebuah kekuatan besar penuh niat membunuh seketika mencekik tenggorokanmu."
  },
  AvgDialog_57592_Content_1 = {
    Text = "Ketika Ryker hari ini memenangkan celana dari siswa ke-17 di meja judi, akhirnya ada yang menangis dan melaporkannya kepada Penjaga."
  },
  AvgDialog_57592_Content_10 = {
    Text = "Jangan begitu kejam lah, tidak masalah untuk berhenti. Asalkan kau bertaruh denganku untuk terakhir kalinya, hanya satu kali saja, dengan taruhan sesuatu yang paling berharga…"
  },
  AvgDialog_57592_Content_11 = {
    Text = "Ekor anjing Ryker bergoyang dengan riang, hidungnya yang basah terus mengendus-endus di sekitarmu, seakan-akan sedang mencari bagian paling lezat dari mangsanya. Bahkan tanpa sengaja, hidungnya menyentuh daun telingamu."
  },
  AvgDialog_57592_Content_12 = {
    Text = "Apa taruhannya?"
  },
  AvgDialog_57592_Content_13 = {
    Text = "Kamu tegang seperti lempeng baja yang dingin dan tidak bersahabat, waspada mengamati orc yang terlalu bersemangat di hadapanmu."
  },
  AvgDialog_57592_Content_14 = {
    Text = "Saat ini, belum ada orang di sekolah yang bisa mengalahkan Ryker di meja judi. Apa yang disebut taruhan itu tidak jauh berbeda dari perampasan terang-terangan. Kamu mulai memikirkan strategi negosiasi untuk bersiap menawar."
  },
  AvgDialog_57592_Content_15 = {
    Text = "Apa taruhannya?"
  },
  AvgDialog_57592_Content_16 = {
    Text = "Sepertinya ini adalah pertanyaan yang patut dipertimbangkan. Ryker berjalan mengitari kamu sambil bergumam sesuatu, sulit didengar dengan jelas."
  },
  AvgDialog_57592_Content_17 = {
    Text = "Ternyata, kau memang istimewa. Aku bisa menciumnya, tubuhmu sangat harum. Jika saja aku bisa menggigit sedikit, jika saja aku bisa merasakannya…"
  },
  AvgDialog_57592_Content_18 = {Text = "Apa?"},
  AvgDialog_57592_Content_19 = {
    Text = "Tak lama, napas hangat berhenti di dekat telingamu. Binatang rakus itu memperlihatkan taringnya, mengungkapkan keinginan terdalam dari lubuk hatinya."
  },
  AvgDialog_57592_Content_2 = {
    Text = "Ryker! Segera hentikan tindakan perjudian ilegalmu!"
  },
  AvgDialog_57592_Content_20 = {
    Text = "Aku bertaruh... satu ciuman darimu."
  },
  AvgDialog_57592_Content_3 = {
    Text = "Kamu mendorong pintu dengan suara 'bum', berteriak layaknya polisi keadilan."
  },
  AvgDialog_57592_Content_4 = {
    Text = "Di sekitar meja judi besar di tengah ruangan, para siswa dengan wajah kosong dan tubuh gemetar ketakutan berdesakan. Bahkan, beberapa dari mereka menangis dengan air mata kesedihan, seolah-olah cakar iblis telah merenggut hal terpenting dari mereka."
  },
  AvgDialog_57592_Content_5 = {
    Text = "Tidak menarik, tidak menarik! Taruhan yang begitu konservatif benar-benar tidak sepadan dengan keberanian kalian semua!"
  },
  AvgDialog_57592_Content_6 = {
    Text = "Binatang buas yang angkuh memukul-mukul meja, di belakangnya terdapat tumpukan jarahan aneh setinggi gunungan. Jelas sekali dia tidak menunjukkan rasa penyesalan."
  },
  AvgDialog_57592_Content_7 = {
    Text = "Ah, ini kamu, Watson-ku. Apakah kamu juga datang untuk bermain?"
  },
  AvgDialog_57592_Content_8 = {
    Text = "Biasanya, orc yang malas dan santai kini menunjukkan antusiasme yang tidak biasa. Melihat bahwa itu adalah kamu, matanya langsung bersinar, lalu dia segera mendekat, sepasang telinga berbulunya berdiri tegak ke depan dengan penuh semangat."
  },
  AvgDialog_57592_Content_9 = {
    Text = "Sebelum pihak sekolah datang dan menyegel tempat ini, saya sarankan kamu segera berhenti."
  },
  AvgDialog_57723_Content_1 = {
    Text = "Akhir-akhir ini, rumor tentang Acara mistis mulai beredar di kampus. Di ruang musik yang kosong pada tengah malam, sering terdengar suara musik yang dimainkan tanpa sumber yang jelas."
  },
  AvgDialog_57723_Content_10 = {
    Text = "Tuts piano hitam dan putih menarikmu seperti pusaran air."
  },
  AvgDialog_57723_Content_11 = {
    Text = "Indah sekali..."
  },
  AvgDialog_57723_Content_12 = {
    Text = "Kamu meletakkan kedua tanganmu di atas tuts, mengikuti dorongan naluri, dan mulai memainkan musik dengan kemampuan yang pas-pasan."
  },
  AvgDialog_57723_Content_13 = {
    Text = "Dari suara yang terbata-bata, melodi perlahan-lahan terbentuk. Musik mengalir seperti tetesan air yang berkumpul menjadi aliran halus, mengalir di aula musik yang luas dan kosong."
  },
  AvgDialog_57723_Content_15 = {
    Text = "Sepertinya ada sesuatu di udara yang mulai mengental. Kamu tetap sadar, terus memainkan dengan tenang tanpa menunjukkan ekspresi, dengan wajah khidmat seperti seorang peziarah musik."
  },
  AvgDialog_57723_Content_16 = {
    Text = "Akhirnya, entah dari mana terdengar sebuah desahan. Seolah-olah datang dari ujung langit, namun juga seakan tepat di samping telinga."
  },
  AvgDialog_57723_Content_17 = {
    Text = "Kamu memainkannya dengan salah."
  },
  AvgDialog_57723_Content_18 = {
    Text = "Sepasang tangan tak terlihat menutupi tanganmu, seolah-olah dalam genggaman yang intim, tetapi tetap menjaga jarak yang hampir menyentuh."
  },
  AvgDialog_57723_Content_19 = {
    Text = "Kamu merasakan sebuah kekuatan dengan lembut membimbing jari-jari kamu, memperbaiki nada-nada yang salah secara halus."
  },
  AvgDialog_57723_Content_2 = {
    Text = "Setelah melakukan penyelidikan berulang kali, tidak hanya tidak ada satu pun orang yang ditemukan, tetapi semua orang yang masuk ke ruang musik untuk mendengarkan lagu juga menunjukkan kecenderungan kegilaan dalam berbagai tingkatan."
  },
  AvgDialog_57723_Content_20 = {
    Text = "Gemuruh yang membuat pusing menyebar dari gendang telinga ke seluruh tubuh, penampilan yang hampir sempurna segera memperlihatkan keindahan penuh dari partitur ini."
  },
  AvgDialog_57723_Content_21 = {
    Text = "Napas Anda tanpa sadar terhenti, seolah-olah tenggelam dalam pusaran musik, perlahan tenggelam dalam gelombang yang kadang-kadang keras seperti baja dan kadang-kadang lembut seperti kapas."
  },
  AvgDialog_57723_Content_22 = {
    Text = "Agak... tidak bisa melihat dengan jelas..."
  },
  AvgDialog_57723_Content_23 = {
    Text = "Kamu menatap partitur itu, bayangan tuts piano bergerak dengan memusingkan di sudut pandangmu, dan tubuh bagian atasmu tanpa sadar mulai condong ke depan."
  },
  AvgDialog_57723_Content_24 = {
    Text = "Noda darah yang samar mulai terlihat di atas partitur. Dengan sepenuh hati, kamu ingin melihat lebih jelas partitur itu dan mengukirnya dalam ingatanmu."
  },
  AvgDialog_57723_Content_25 = {
    Text = "Kepalamu semakin dekat, semakin dekat dengan partitur."
  },
  AvgDialog_57723_Content_26 = {
    Text = "Desahan itu muncul kembali, kekuatan yang tak terelakkan mencengkeram kedua tanganmu."
  },
  AvgDialog_57723_Content_27 = {Text = "Berhenti."},
  AvgDialog_57723_Content_28 = {
    Text = "Dengan suara keras yang kacau menghantam tuts piano, semua musik tiba-tiba terhenti."
  },
  AvgDialog_57723_Content_29 = {
    Text = "Kamu berkeringat deras seperti hujan dan napasmu tersengal-sengal."
  },
  AvgDialog_57723_Content_3 = {
    Text = "Melihat bahwa tidak ada guru dan siswa yang berani tinggal di gedung sekolah pada malam hari, kamu yang memikul harapan terakhir akhirnya datang ke ruang musik misterius ini di tengah malam."
  },
  AvgDialog_57723_Content_30 = {
    Text = "Entah sejak kapan, sepasang tangan yang menutupi tanganmu mulai menampakkan bentuknya."
  },
  AvgDialog_57723_Content_31 = {
    Text = "Itu adalah sepasang tangan yang dibungkus oleh sarung tangan putih, ramping dan anggun."
  },
  AvgDialog_57723_Content_32 = {
    Text = "Kamu berbalik dan melihat pemilik tangan di belakangmu — wajah dingin Hameln menyiratkan rasa putus asa yang sekejap melintas."
  },
  AvgDialog_57723_Content_33 = {Text = "Itu kamu!"},
  AvgDialog_57723_Content_34 = {
    Text = "Kamu ingin berdiri, namun pusing yang membuatmu merasa dunia berputar menghentikanmu."
  },
  AvgDialog_57723_Content_35 = {
    Text = "Tangan yang mengenakan sarung tangan putih itu dengan lembut menekan pundakmu, lalu mengeluarkan sebuah seruling panjang dari kehampaan."
  },
  AvgDialog_57723_Content_36 = {
    Text = "Penampilan seruling itu samar dan sulit dibedakan, namun entah mengapa membuatmu merasa tenang."
  },
  AvgDialog_57723_Content_37 = {
    Text = "Silakan beristirahat, aku akan tetap berjaga di sampingmu."
  },
  AvgDialog_57723_Content_38 = {
    Text = "Hameln membawa seruling ke bibirnya, suara seruling yang lembut mengalun di telingamu, seperti pelukan tangan yang hangat."
  },
  AvgDialog_57723_Content_39 = {
    Text = "Rasa kantuk yang tak tertahankan melanda dirimu, lalu kamu membaringkan kepalamu di atas piano dan masuk ke dalam mimpi indah yang mendalam."
  },
  AvgDialog_57723_Content_4 = {
    Text = "Di balik pintu kedap suara yang tebal, segalanya sunyi senyap, seperti suasana malam yang seharusnya. Hanya suara langkah kakimu sendiri yang samar-samar bergema."
  },
  AvgDialog_57723_Content_40 = {
    Text = "Pandangan Hameln jatuh pada wajah tidurmu yang damai, sebuah gumaman pelan terdengar di malam yang hening, tanpa ada seorang pun yang mendengarnya."
  },
  AvgDialog_57723_Content_41 = {
    Text = "Selamanya, selamanya…"
  },
  AvgDialog_57723_Content_5 = {
    Text = "Aneh, tidak ada jejak pelarutan sama sekali…"
  },
  AvgDialog_57723_Content_6 = {
    Text = "Setelah melakukan pemeriksaan tanpa hasil, kamu tiba di samping piano yang berada di tengah kelas dan secara tidak sadar mengambil beberapa lembar partitur yang diletakkan di atas stand."
  },
  AvgDialog_57723_Content_7 = {
    Text = "Apakah ada yang menjatuhkan partitur?"
  },
  AvgDialog_57723_Content_8 = {
    Text = "Tampaknya ini adalah sebuah partitur musik yang belum selesai, tetapi melodi yang sudah ada di dalamnya sudah cukup untuk menjadi karya abadi yang menakjubkan dalam sejarah."
  },
  AvgDialog_57723_Content_9 = {
    Text = "Matamu terfokus erat pada setiap not, hampir seperti dalam keadaan terpesona, lalu kamu duduk dengan penuh perhatian."
  },
  AvgDialog_57804_Content_1 = {
    Text = "Terdengar suara Hameln"
  },
  AvgDialog_57804_Content_2 = {
    Text = "Jelas sudah tidak bisa dikendalikan, biar aku yang menurunkan tingkat fusi-nya terlebih dahulu!"
  },
  AvgDialog_57813_Content_1 = {
    Text = "Penjaga… … \"Boneka\" terlepas… Kolam hitam… kamu… bahaya… …"
  },
  AvgDialog_57813_Content_10 = {
    Text = "Sambil perlahan bangkit dan mundur, kamu dengan susah payah membuka suara untuk bertanya."
  },
  AvgDialog_57813_Content_11 = {
    Text = "Apakah kamu tiba-tiba datang menemuiku karena melihat masa depan yang baru?"
  },
  AvgDialog_57813_Content_12 = {
    Text = "\"Boneka\"hanya menatapmu, mengikuti setiap langkahmu yang semakin mendekat, seakan-akan kalian sedang menari dalam suatu tarian penuh keharmonisan."
  },
  AvgDialog_57813_Content_13 = {
    Text = "Masa depan tidak akan berubah, namun baru-baru ini tiba-tiba saya merasa pikiran saya sangat jernih dan penuh inspirasi. Akhirnya, saya memahami cara tercepat untuk mencapai tujuan."
  },
  AvgDialog_57813_Content_14 = {Text = "...Apa?"},
  AvgDialog_57813_Content_15 = {
    Text = "Kamu dengan patuh melanjutkan pertanyaannya yang belum selesai, namun tiba-tiba bagian belakangmu menyentuh dinding yang kokoh."
  },
  AvgDialog_57813_Content_16 = {
    Text = "Tentu saja… menyingkirkan Mythag, variabel terbesar di dunia ini."
  },
  AvgDialog_57813_Content_17 = {
    Text = "Pada saat suaranya belum selesai, tanpa ragu sedikit pun, kamu langsung berguling ke samping, melindungi kepala dengan kedua tangan, dan dengan cepat menerjang ke arah jendela di dinding."
  },
  AvgDialog_57813_Content_18 = {
    Text = "Kaca berderai pecah, di antara tak terhitung banyaknya fragmen yang berkilauan terpantul wajahmu dan \"Boneka\". Kamu jatuh ke tanah dengan postur pendaratan standar, tak memedulikan luka goresan di kulitmu, lalu mulai berlari sekuat tenaga."
  },
  AvgDialog_57813_Content_19 = {Text = "Kampus."},
  AvgDialog_57813_Content_2 = {
    Text = "Komunikasi Perak yang tiba-tiba terputus secara sporadis memadamkan suara terakhirnya. Dari beberapa kata yang terdengar, terungkap sebuah krisis yang membuat bulu kudukmu merinding."
  },
  AvgDialog_57813_Content_20 = {Text = "Koridor."},
  AvgDialog_57813_Content_21 = {
    Text = "Lorong bawah tanah."
  },
  AvgDialog_57813_Content_22 = {
    Text = "Berapa kali kamu nyaris terkena sabit maut itu, tersandung lalu menabrak dinding, jatuh di sudut, namun tak berani berhenti sejenak, hanya bisa melarikan diri dengan napas tersengal-sengal."
  },
  AvgDialog_57813_Content_23 = {
    Text = "Benar-benar murid yang baik, biar guru memberikanmu pelajaran latihan praktik terbaik."
  },
  AvgDialog_57813_Content_24 = {
    Text = "Tawa kegilaan yang tidak tersembunyi mengejarmu seperti hantu, niat membunuh hampir menembus punggungmu. Sekali lagi, kamu dengan susah payah menjatuhkan diri ke tanah, di belakangmu terdengar suara \"clang\" saat sabit tertancap ke dalam pipa logam."
  },
  AvgDialog_57813_Content_25 = {
    Text = "Uap dengan komponen tidak diketahui bocor dari pipa, memenuhi ruang sempit dengan panas dan menghalangi pandangan kalian."
  },
  AvgDialog_57813_Content_26 = {
    Text = "Kamu segera menyadari sesuatu dengan tajam, lalu mengikuti arah pipa dan bersembunyi di dalam laboratorium."
  },
  AvgDialog_57813_Content_27 = {
    Text = "Tak lama kemudian, pintu laboratorium yang tertutup rapat pun pecah setelah beberapa suara keras terdengar. Suara yang familiar mulai mendekat sedikit demi sedikit."
  },
  AvgDialog_57813_Content_28 = {
    Text = "\"Permainan petak umpet berakhir di sini saja. Kamu sudah cukup baik sampai tahap ini untuk mendapatkan tambahan sepuluh poin pada nilai akhir semester.\""
  },
  AvgDialog_57813_Content_29 = {
    Text = "\"Boneka\" menyapukan sabitnya di tanah, menghasilkan suara yang tajam."
  },
  AvgDialog_57813_Content_3 = {
    Text = "\"Boneka\" terbebas dari belenggu Kolam Hitam?"
  },
  AvgDialog_57813_Content_30 = {
    Text = "Jangan takut, setelah aku menghancurkanmu dengan tanganku sendiri, aku akan meletakkan mayatmu di peti es untuk disimpan dengan baik."
  },
  AvgDialog_57813_Content_31 = {
    Text = "Kamu akan menjadi penelitian paling berharga dan luar biasa bagi saya, kita masih memiliki banyak sekali waktu bersama…"
  },
  AvgDialog_57813_Content_32 = {
    Text = "Di tengah kabut tipis, dia melihat sekilas ujung pakaian di samping alat besar di pusat ruangan, dan sudut bibirnya sedikit terangkat."
  },
  AvgDialog_57813_Content_33 = {
    Text = "Di mana ya? Anak anjing, coba menggonggong dua kali."
  },
  AvgDialog_57813_Content_34 = {
    Text = "Gesekan logam yang menusuk telinga tiba-tiba menghilang, dan laboratorium diliputi oleh keheningan yang mencekam."
  },
  AvgDialog_57813_Content_35 = {
    Text = "Waktu hampir membeku dalam penantian yang menyiksa. Suaranya akhirnya terdengar kembali, lembut seperti bisikan."
  },
  AvgDialog_57813_Content_36 = {
    Text = "Ketemu kamu."
  },
  AvgDialog_57813_Content_38 = {
    Text = "Sabit menghantam dengan kekuatan mematikan ke arah perangkat, namun yang ambruk dengan lemas hanyalah seragam sekolah yang ringan."
  },
  AvgDialog_57813_Content_39 = {
    Text = "Saat sabit tersangkut di instrumen, kamu menekan tombol merah yang erat kamu genggam. Pintu pengisi tungku instrumen itu dengan cepat terbuka ke samping, memperlihatkan pemandangan magma neraka di dalamnya."
  },
  AvgDialog_57813_Content_4 = {
    Text = "Kamu teringat sepasang mata penuh kegilaan yang menatapmu, dan berdasarkan intuisi, segera bersiap untuk membuka pintu dan keluar, mempercepat waktu untuk bergabung dengan Pembangun lainnya."
  },
  AvgDialog_57813_Content_40 = {
    Text = "Kamu muncul di belakang \"Boneka\", dengan segenap kekuatan mendorongnya ke dalam Tungku."
  },
  AvgDialog_57813_Content_41 = {
    Text = "Lidah api melahapnya sepenuhnya, \"Boneka\"menoleh dengan terkejut. Matanya tampak masih menyimpan sedikit rasa kagum yang samar, serta seulas senyuman aneh."
  },
  AvgDialog_57813_Content_42 = {
    Text = "Dengan firasat buruk, kamu menundukkan kepala dan melihat tangan lain dari boneka itu mencengkeram sisa-sisa pakaian atasmu."
  },
  AvgDialog_57813_Content_43 = {
    Text = "Kedua tanganmu secara refleks menahan bingkai pintu instrumen, sisa panasnya langsung membakar kulit telapak tanganmu, menghasilkan rasa sakit yang menyengat disertai suara mendesis. Kamu menggigit erat gigimu dan melawan kekuatan besar yang menarik ke dalam."
  },
  AvgDialog_57813_Content_44 = {
    Text = "Kontur tubuh boneka sudah kabur dalam cahaya api yang menyilaukan, hanya sepasang mata itu yang tersisa. Mata yang lebih terang dari api masih menatapmu."
  },
  AvgDialog_57813_Content_45 = {
    Text = "Para guru dan murid Mythag akhirnya tiba terlambat setelah menerima sinyal darurat lokasimu, lalu segera menarikmu menjauh dari Tungku."
  },
  AvgDialog_57813_Content_46 = {
    Text = "Kalian saling bertatapan melalui api, dan dalam sekejap sebelum wajah itu berubah menjadi abu, kau berhasil membaca pesan terakhir yang terbentuk di bibirnya."
  },
  AvgDialog_57813_Content_47 = {
    Text = "Kami akan bertemu lagi di akhir."
  },
  AvgDialog_57813_Content_5 = {
    Text = "Pada saat tanganmu menyentuh gagang pintu, bulu-bulu di sekujur tubuhmu hampir berdiri karena peringatan insting, dan kamu merasakan jantungmu berdebar kencang saat tiba-tiba berjongkok."
  },
  AvgDialog_57813_Content_7 = {
    Text = "Pada saat yang sama, sebuah angin tajam melintas di atas kepalamu, memotong beberapa helai rambut yang berterbangan. Baru setelah itu, papan pintu asrama roboh dengan suara keras."
  },
  AvgDialog_57813_Content_8 = {
    Text = "Sayang sekali, tak disangka anak anjing itu ternyata berbaring di tanah. Ayo, beri salam?"
  },
  AvgDialog_57813_Content_9 = {
    Text = "Kamu mengangkat kepalamu, sepasang mata itu tumpang tindih antara memori dan kenyataan, menatapmu dari atas dengan senyuman gembira yang tak berubah seperti biasanya."
  },
  AvgDialog_57890_Content_1 = {
    Text = "Saya akan mempercepat proses fusi Tawil, Penjaga. Bagaimana Anda akan menghadapinya?"
  },
  AvgDialog_58289_Content_1 = {
    Text = "Tamu tak diundang"
  },
  AvgDialog_58289_Content_10 = {
    Text = "Tidak. Bagaimana jika sudah malam?!"
  },
  AvgDialog_58289_Content_11 = {
    Text = "Kamu dengan cepat berguling turun dari tempat tidur, menemukan posisi pena, kertas draft, dan penghapus dengan tepat, lalu memasukkan semuanya ke dalam tas sekolah."
  },
  AvgDialog_58289_Content_12 = {
    Text = "Setelah semuanya siap, kamu menarik napas dalam-dalam dan membuka pintu asrama——"
  },
  AvgDialog_58289_Content_13 = {
    Text = "Eh……? Ini bukan sekolah yang kukenal."
  },
  AvgDialog_58289_Content_15 = {
    Text = "Aku mengerti, ini pasti dalam mimpi! Bagus, aku akan kembali tidur lagi…"
  },
  AvgDialog_58289_Content_16 = {
    Text = "Kamu berbalik dengan cepat, namun pintu asrama — lebih tepatnya, seluruh gedung asrama telah menghilang tanpa jejak."
  },
  AvgDialog_58289_Content_18 = {
    Text = "Kamu harus berbalik lagi dan menatap jalan di hadapanmu."
  },
  AvgDialog_58289_Content_19 = {
    Text = "Ada orang di sini——Halo——"
  },
  AvgDialog_58289_Content_2 = {
    Text = "Berbagai macam hewan hidup dengan damai di sini, sesekali terdapat juga beberapa iblis."
  },
  AvgDialog_58289_Content_20 = {
    Text = "Selamat pagi, selamat siang, selamat malam——"
  },
  AvgDialog_58289_Content_21 = {
    Text = "Guruh, guruh!"
  },
  AvgDialog_58289_Content_22 = {
    Text = "Syukurlah, akhirnya ada sesuatu yang merespons aku!"
  },
  AvgDialog_58289_Content_23 = {
    Text = "Kamu dengan bersemangat bergegas menuju sumber suara, namun hanya menemukan bahwa di sini terdapat sebuah kotak pos merah kecil."
  },
  AvgDialog_58289_Content_24 = {
    Text = "Gluk gluk, gangguan pencernaan, tolong... tolong..."
  },
  AvgDialog_58289_Content_25 = {
    Text = "<BigShake:Uwaa, bleh!>"
  },
  AvgDialog_58289_Content_26 = {
    Text = "Kotak pos bergerak neurosis, kemudian mengeluarkan sepucuk surat yang basah kuyup."
  },
  AvgDialog_58289_Content_27 = {
    Text = "Apakah ini untukku? Tampaknya agak menjijikkan…"
  },
  AvgDialog_58289_Content_28 = {
    Text = "Ini adalah malam tanpa angin. Bangunan-bangunan tenggelam dalam cahaya bulan merah gelap, Pintu yang tertutup rapat melarang siapa pun untuk masuk."
  },
  AvgDialog_58289_Content_29 = {
    Text = "Kamu adalah satu-satunya makhluk hidup dalam radius ratusan mil ini."
  },
  AvgDialog_58289_Content_3 = {
    Text = "Ting ting ting——"
  },
  AvgDialog_58289_Content_30 = {
    Text = "Membuka amplop"
  },
  AvgDialog_58289_Content_31 = {
    Text = "Kamu berusaha mengabaikan sensasi lengket di ujung jari-jarimu, dengan hati-hati membuka amplop itu."
  },
  AvgDialog_58289_Content_32 = {
    Text = "Kepada penerima jauh di sana: \n\nHarap tiba di kediaman Franld sebelum tengah malam. \n<Red: Pastikan tepat waktu, jika tidak, akibatnya ditanggung sendiri (otak@2 meledak@3)!>\nAlamat kediaman: Rahasia. \n\n-▼-"
  },
  AvgDialog_58289_Content_33 = {
    Text = "Rumah Franter? Aku ingat itu adalah kediaman milik Tuan Dexter. Sejak kapan orang ini juga belajar bermain lelucon…"
  },
  AvgDialog_58289_Content_34 = {
    Text = "Lagipula, aku tidak membawa jam tangan, bahkan tidak tahu pukul berapa sekarang——"
  },
  AvgDialog_58289_Content_35 = {Text = "Tik. Tik."},
  AvgDialog_58289_Content_36 = {
    Text = "Entah sejak kapan, sebuah jam raksasa muncul di langit, dengan jarum jam dan jarum menit berhenti tepat pada pukul 11."
  },
  AvgDialog_58289_Content_37 = {
    Text = "Jarum detik yang ramping masih bergerak maju dengan dingin, tanpa cela, dan kecepatannya tetap stabil."
  },
  AvgDialog_58289_Content_38 = {
    Text = "Apa... yang terjadi..."
  },
  AvgDialog_58289_Content_39 = {
    Text = "Eh, apakah kamu juga menerima surat yang sama denganku?"
  },
  AvgDialog_58289_Content_4 = {
    Text = "Hmm... sangat mengantuk, jangan ganggu aku."
  },
  AvgDialog_58289_Content_40 = {
    Text = "Siapa itu?!"
  },
  AvgDialog_58289_Content_41 = {
    Text = "Maaf, Penjaga {Male=tuan,Female=nyonya}! Kamu tampaknya sangat fokus tadi. Aku sudah memanggilmu beberapa kali…"
  },
  AvgDialog_58289_Content_42 = {
    Text = "Apakah kamu tidak ingat aku? Aku Elsa, kita pernah mengikuti Pengenalan Pelarutan oleh Miss Boneka."
  },
  AvgDialog_58289_Content_43 = {
    Text = "Elsa… Aku ingat, dia sering meminjam catatan dari Ramona."
  },
  AvgDialog_58289_Content_44 = {
    Text = "<Small:Maaf, karena aku selalu gagal dalam ujian…>"
  },
  AvgDialog_58289_Content_45 = {
    Text = "Elsa menundukkan kepalanya dan dengan sedih memeluk erat bantal berbentuk hati di depan dadanya."
  },
  AvgDialog_58289_Content_46 = {
    Text = "Jangan sedih, Nona Elsa. Gagal dalam kelas Nona Boneka adalah jalan yang harus dilalui oleh kebanyakan Penyelidik."
  },
  AvgDialog_58289_Content_47 = {
    Text = "Ngomong-ngomong, tadi kamu bilang menerima surat yang sama, apakah kamu juga bisa melihatnya?"
  },
  AvgDialog_58289_Content_48 = {
    Text = "Kamu menunjuk jam raksasa yang tergantung di atas bulan purnama."
  },
  AvgDialog_58289_Content_49 = {
    Text = "Bisa dilihat. Namun, aku tersesat dan tidak peduli bagaimana aku mencoba, aku tetap tidak bisa menemukan arah yang benar. Sekarang, aku hanya punya kurang dari 1 menit tersisa."
  },
  AvgDialog_58289_Content_50 = {
    Text = "Aneh, countdown saya masih tersisa 1 jam. Apakah karena kamu masuk ke dunia ini lebih dulu?"
  },
  AvgDialog_58289_Content_51 = {
    Text = "Saya tidak tahu... ini hanya lelucon, kan, %player%{Male=tuan,Female=nyonya}?"
  },
  AvgDialog_58289_Content_52 = {
    Text = "Saya belum pernah bertugas di lapangan, jadi belum punya pengalaman dengan Acara abnormal……"
  },
  AvgDialog_58289_Content_53 = {
    Text = "Jujur, ini juga pertama kalinya saya menghadapi situasi seperti ini."
  },
  AvgDialog_58289_Content_54 = {
    Text = "Waktu hingga hitungan mundur berakhir: <Red:5> detik"
  },
  AvgDialog_58289_Content_55 = {
    Text = "Kamu dengan lembut menggenggam tangan Elsa."
  },
  AvgDialog_58289_Content_56 = {
    Text = "Jika hanya tersisa satu menit, mesin waktu pun tidak akan sempat. Namun, jangan takut."
  },
  AvgDialog_58289_Content_57 = {
    Text = "Waktu hingga hitungan mundur berakhir: <Red:0> detik"
  },
  AvgDialog_58289_Content_58 = {
    Text = "Apa pun yang akan terjadi selanjutnya, aku akan melindungi ——"
  },
  AvgDialog_58289_Content_59 = {
    Text = "Punya kamu..."
  },
  AvgDialog_58289_Content_6 = {
    Text = "Astaga, hari ini adalah hari ujian Pengantar Pelarutan. Jam berapa sekarang…"
  },
  AvgDialog_58289_Content_60 = {
    Text = "Kepala Elsa meledak menjadi genangan hangat dari otaknya. Cairan kental itu muncrat ke wajah, dan bau amis seperti karat menyebar di udara."
  },
  AvgDialog_58289_Content_61 = {
    Text = "%player%@2, selamatkan @3…"
  },
  AvgDialog_58289_Content_62 = {
    Text = "Dari leher yang patah terus mengalir cairan hitam kental, dengan cepat membentuk wajah lain yang pucat dan asing."
  },
  AvgDialog_58289_Content_63 = {
    Text = "<Change>Tolong, tolong aku…"
  },
  AvgDialog_58289_Content_64 = {
    Text = "Nona Elsa?! Bagaimana... bisa..."
  },
  AvgDialog_58289_Content_66 = {
    Text = "Bilah binatang mengiris udara, \"Elsa\" tubuhnya langsung terbelah menjadi dua, D-lendir hitam menyembur keluar seperti darah."
  },
  AvgDialog_58289_Content_67 = {
    Text = "Tidak ada gunanya, dia sudah kehilangan akal sehatnya."
  },
  AvgDialog_58289_Content_68 = {
    Text = "Tuan Ryker?!"
  },
  AvgDialog_58289_Content_69 = {
    Text = "Ryker menarik kembali cakarnya dan dengan langkah ringan berjalan mendekati Anda."
  },
  AvgDialog_58289_Content_7 = {
    Text = "Jam 6:37, masih pagi kan…"
  },
  AvgDialog_58289_Content_70 = {
    Text = "Kenapa ekspresi seperti mau menangis? Jangan khawatir, tempat ini mungkin adalah Domain seseorang."
  },
  AvgDialog_58289_Content_71 = {Text = "Domain…?"},
  AvgDialog_58289_Content_72 = {
    Text = "Mm. Artinya, dalam kenyataan, Elsa ini kemungkinan besar masih hidup dengan baik."
  },
  AvgDialog_58289_Content_73 = {
    Text = "Tidak salah lagi, memang detektif yang hebat, bisa langsung mengenali. Apa dasarnya?"
  },
  AvgDialog_58289_Content_74 = {
    Text = "Pertama kali aku bertemu dengan Elsa, malam itu juga seperti malam ini."
  },
  AvgDialog_58289_Content_75 = {
    Text = "Pada saat itu, dia dikejar sangat ketat oleh segerombolan monster Pelarutan. Aku baru saja keluar dari tavern, menunjukkan jalannya kepadanya, dan sekalian membunuh monster yang mengejarnya."
  },
  AvgDialog_58289_Content_76 = {
    Text = "Baru saja kita bertemu lagi. Waktu yang sama, tempat yang sama, tapi aku memberinya petunjuk yang salah, membuat kepalanya terluka parah. Dengan kata lain—"
  },
  AvgDialog_58289_Content_77 = {
    Text = "Apa maksudnya?"
  },
  AvgDialog_58289_Content_78 = {
    Text = "Keberuntunganku hilang! Ini adalah sesuatu yang tidak mungkin terjadi, jadi aku menyimpulkan secara logis bahwa ini bukan kenyataan."
  },
  AvgDialog_58289_Content_79 = {
    Text = "Atau kamu tampar aku dua kali, kita pastikan apakah ini mimpi atau bukan? Aku sudah menampar diriku sendiri beberapa kali tadi, tapi tidak ada gunanya."
  },
  AvgDialog_58289_Content_8 = {
    Text = "Kamu meraba-raba mencari tombol alarm, lalu kembali tertidur lelap."
  },
  AvgDialog_58289_Content_81 = {
    Text = "Saya hanya tahu bahwa baik di Domain maupun di dunia nyata, saya tidak ingin melihat kepala saya pecah."
  },
  AvgDialog_58289_Content_82 = {
    Text = "Kalau begitu, kamu sangat membutuhkan bantuanku! Aku bertemu banyak orang yang terlambat seperti Elsa di jalan, sebaiknya kita lewat udara."
  },
  AvgDialog_58289_Content_83 = {
    Text = "Ryker berkata sambil menunjuk ke arah atap bangunan terdekat."
  },
  AvgDialog_58289_Content_84 = {
    Text = "Maksudmu terbang melewati atap?"
  },
  AvgDialog_58289_Content_85 = {
    Text = "Sayang sekali, aku hanyalah seorang Penjaga yang biasa saja, tidak bisa menemanimu terbang di atap gedung——"
  },
  AvgDialog_58289_Content_86 = {
    Text = "Detik berikutnya, Ryker meletakkanmu di punggungnya dan meloncat ke udara."
  },
  AvgDialog_58289_Content_87 = {
    Text = "Berpeganganlah, Penjaga %player%{Male=tuan,Female=nyonya}!"
  },
  AvgDialog_58289_Content_88 = {
    Text = "<Shake: Uwaaaaa!!>"
  },
  AvgDialog_58289_Content_89 = {
    Text = "Kamu ketakutan dan segera meraih kerah baju Ryker. Detektif yang membungkuk dengan gesit melompati atap-atap besar dan kecil, berlari melewati gedung-gedung yang berjejer rapat di Londinium."
  },
  AvgDialog_58289_Content_90 = {
    Text = "Seorang manusia dan seekor serigala melakukan serangan dalam keheningan di bawah bulan."
  },
  AvgDialog_58289_Content_91 = {
    Text = "Hanya suara angin yang bersih terdengar di telinga. Kamu menundukkan tubuhmu dan menyandarkan diri pada bulu lembut di bawahmu."
  },
  AvgDialog_58289_Content_92 = {
    Text = "Bagaimana, apakah menyenangkan?"
  },
  AvgDialog_58289_Content_93 = {
    Text = "Tidak disangka kamu memiliki kemampuan seperti ini... <Big: Perlambat, ajukan permintaan perlambatan!>"
  },
  AvgDialog_58289_Content_94 = {
    Text = "Ryker tertawa terbahak-bahak, dadanya terus bergetar seolah-olah setiap sel di tubuhnya sedang bersorak gembira."
  },
  AvgDialog_58289_Content_95 = {
    Text = "Inilah yang seharusnya dilakukan oleh serigala! Aku hanya kembali ke keahlian lamaku, mengerti?"
  },
  AvgDialog_58289_Content_96 = {
    Text = "Aku sudah bilang, <BigShake: Perlambat!>"
  },
  AvgDialog_58289_Content_97 = {
    Text = "Pelan-pelan, jangan sembarangan mencabuti buluku!"
  },
  AvgDialog_58290_Content_1 = {
    Text = "Rumah Hantu"
  },
  AvgDialog_58290_Content_10 = {
    Text = "Di meja permainan, pertarungan sedang berlangsung sengit. Tidak ada yang memperhatikan pertanyaan kecil dari Anda."
  },
  AvgDialog_58290_Content_11 = {
    Text = "<BigShake:Mengganggu kesenangan semua orang!>"
  },
  AvgDialog_58290_Content_12 = {
    Text = "Tolong, siapa yang masih ingat bahwa kita terjebak di Domain milik dewa gila ini?"
  },
  AvgDialog_58290_Content_13 = {
    Text = "Memperbaiki sedikit, dewa yang gila dan lupa. Yang perlu kita lakukan sekarang adalah menghemat tenaga, menunggu sampai Dia ingat untuk memberi tahu kita soal pertanyaan itu, bukan?"
  },
  AvgDialog_58290_Content_14 = {
    Text = "Straight flush, bagus!"
  },
  AvgDialog_58290_Content_16 = {
    Text = "Baiklah, aku akan melakukan penyelidikan di sekitar sini."
  },
  AvgDialog_58290_Content_17 = {
    Text = [[
Rumah Franter
Perpustakaan Lantai 1]]
  },
  AvgDialog_58290_Content_18 = {
    Text = "Hmm… buku-buku milik orang ini ternyata semuanya adalah versi hardcover mewah yang belum pernah dibuka. Entah bagaimana dia bisa menjadi Profesor Mythag."
  },
  AvgDialog_58290_Content_19 = {
    Text = "Eh, apa ini?"
  },
  AvgDialog_58290_Content_2 = {
    Text = [[
Rumah Franter
Dua jam kemudian]]
  },
  AvgDialog_58290_Content_20 = {
    Text = "Di sudut yang tak terperhatikan, sebuah peti mati berwarna hitam menarik perhatianmu."
  },
  AvgDialog_58290_Content_21 = {
    Text = "Di kedua sisi peti mati terdapat pola dan simbol rumit yang digambar menggunakan pewarna emas, sementara kabut hitam pekat samar-samar menyembur keluar dari celah di tengahnya."
  },
  AvgDialog_58290_Content_22 = {
    Text = "Hmm——sama sekali tidak bisa didorong."
  },
  AvgDialog_58290_Content_23 = {
    Text = "Sepertinya gaya Gullemwah. Dari mana Dexter mendapatkannya?"
  },
  AvgDialog_58290_Content_24 = {
    Text = "Kamu dengan rasa ingin tahu mengulurkan tangan, perlahan menyentuh pola berlapis emas di sisi luar peti mati, namun ——"
  },
  AvgDialog_58290_Content_25 = {
    Text = [[
Apophis, firaun hitam ini adalah Karnak. 
 Kamu mempersembahkannya, dia hidup, dia hidup, dia hidup.]]
  },
  AvgDialog_58290_Content_26 = {
    Text = "Apophis, dia tidak mati, dia tidak mati, Apophis."
  },
  AvgDialog_58290_Content_28 = {
    Text = "Apa yang terjadi, Mulia? Kenapa wajahmu begitu pucat?"
  },
  AvgDialog_58290_Content_29 = {
    Text = "Maaf, ada urusan mendesak. Saya harus permisi sebentar."
  },
  AvgDialog_58290_Content_3 = {
    Text = "Sepertinya Dewi Keberuntungan tidak berpihak padamu malam ini, Tuan Ryker."
  },
  AvgDialog_58290_Content_30 = {
    Text = "Lari lagi satu, mata saya sudah hampir balik modal... Di mana asisten robot dan pesulap?"
  },
  AvgDialog_58290_Content_31 = {
    Text = "Hmm, tadi saya melihat Nyonya Erica pergi ke lantai atas. Adapun Casiah, setelah dia kembali, tidak ada yang pernah melihatnya lagi."
  },
  AvgDialog_58290_Content_32 = {
    Text = "Saya juga merasa agak lelah, ingin keluar untuk menikmati udara segar."
  },
  AvgDialog_58290_Content_33 = {
    Text = "Tapi di luar sedang turun salju lebat, Anda bisa kedinginan, Nyonya Sorel!"
  },
  AvgDialog_58290_Content_34 = {
    Text = "Ini bukan dunia nyata, jadi tidak perlu terlalu terpaku pada aturan. Lagipula, sesekali menikmati pemandangan salju juga cukup menyenangkan, bukan?"
  },
  AvgDialog_58290_Content_35 = {
    Text = "Sorel berjalan dengan langkah yang anggun dan meninggalkan aula, membuat ruangan yang tadinya ramai langsung menjadi sepi."
  },
  AvgDialog_58290_Content_36 = {
    Text = "<SmallShake: Bos, bermain kartu ini hanya kedok, kan? Aku tahu kamu pasti sudah punya rencana dari awal!>"
  },
  AvgDialog_58290_Content_37 = {Text = "Eh……"},
  AvgDialog_58290_Content_38 = {
    Text = "Benar! Barusan reaksi Tuan Dexter sangat aneh. Ayo, kita pergi ke kamarnya dan lihat."
  },
  AvgDialog_58290_Content_39 = {
    Text = "Wow, terima! Permainan detektif akhirnya dimulai!"
  },
  AvgDialog_58290_Content_4 = {
    Text = "Kolam sudah melebihi sepuluh ribu Taring, apakah ingin melanjutkan menaikkan taruhan?"
  },
  AvgDialog_58290_Content_40 = {
    Text = [[
Rumah Franter
Tangga]]
  },
  AvgDialog_58290_Content_41 = {
    Text = "Boss, apakah kamu yakin Tuan Dexter ada di kamar tidur? Aku merasa dia baru saja pergi ke arah ruang belajar."
  },
  AvgDialog_58290_Content_42 = {
    Text = "Hmm… Saya sulit menjelaskan proses deduksi saya. Kamu bisa memahaminya sebagai semacam intuisi yang aneh."
  },
  AvgDialog_58290_Content_43 = {
    Text = "Aku mengerti! Jadi ini yang disebut intuisi detektif legendaris!!"
  },
  AvgDialog_58290_Content_44 = {
    Text = "Tenang saja, Bos. Saya tidak akan meragukan satu kata pun dari Anda."
  },
  AvgDialog_58290_Content_45 = {
    Text = "Hanna menepuk dadanya, lalu mengeluarkan kaca pembesar yang selalu dibawanya untuk memeriksa sekitarnya."
  },
  AvgDialog_58290_Content_46 = {
    Text = "Operasi ke-215, dimulai secara resmi! Pertama-tama, di depan mata terdapat tangga yang diukir dari kayu hitam, sederhana, mewah, dan tidak mencari masalah…"
  },
  AvgDialog_58290_Content_47 = {
    Text = "Mempertimbangkan untuk beralih profesi, Nona Hanna? Tiba-tiba saya merasa Anda sangat cocok untuk bekerja di <Blue:Heinz Company> sebagai tenaga penjualan iklan."
  },
  AvgDialog_58290_Content_48 = {
    Text = "Jangan mengganggu penyelidikan orang lain! Terakhir, jendela ukiran di dekat tangga ——"
  },
  AvgDialog_58290_Content_5 = {Text = "…Tentu."},
  AvgDialog_58290_Content_50 = {
    Text = "Tidak jauh dari lensa yang menghadap ke depan, bayangan hitam yang samar-samar melintas cepat di luar jendela."
  },
  AvgDialog_58290_Content_51 = {
    Text = "Aaaaaa! Hu... hantu!"
  },
  AvgDialog_58290_Content_52 = {
    Text = "Tolong katakan sesuatu yang bisa saya pahami, Nona Hanna."
  },
  AvgDialog_58290_Content_53 = {
    Text = "<Shake:Hantu Pak Dexter! Tepat di pintu tangga! Terbang ke langit dan menghilang!>"
  },
  AvgDialog_58290_Content_54 = {
    Text = "Ryker maju dua langkah dan membuka jendela. Angin bertiup kencang, salju berterbangan di udara dengan gerakan yang kacau, jatuh ke segala arah tanpa tujuan yang jelas."
  },
  AvgDialog_58290_Content_55 = {
    Text = "Dia mengangkat kepalanya, cahaya hangat dari lampu di lantai dua memberikan lapisan oranye tipis pada serpihan salju."
  },
  AvgDialog_58290_Content_56 = {
    Text = "Menarik, tidak hanya satu ruangan yang lampunya menyala… Ayo naik dan lihat."
  },
  AvgDialog_58290_Content_57 = {
    Text = [[
Rumah Franter
Koridor Lantai Dua]]
  },
  AvgDialog_58290_Content_58 = {
    Text = "Eh, pintunya terkunci."
  },
  AvgDialog_58290_Content_59 = {
    Text = "Tuan Dexter, apakah Anda di dalam? Apakah Anda sudah merasa lebih baik sekarang?"
  },
  AvgDialog_58290_Content_6 = {
    Text = "Mendengar Anda mengatakan itu membuat saya lega, Tuan Ryker. Setelah keluar dari Domain, saya akan meminta manajer untuk mengirimkan semua tagihan kepada Anda."
  },
  AvgDialog_58290_Content_60 = {
    Text = "Di dalam ruangan hening bak kematian. Entah berapa lama telah berlalu, dari dalam terdengar suara Dexter yang samar."
  },
  AvgDialog_58290_Content_61 = {
    Text = "Maaf, aku sekarang merasa tidak enak badan. Bolehkah aku beristirahat sebentar?"
  },
  AvgDialog_58290_Content_62 = {
    Text = "Tebakanmu benar, dia memang ada di dalam. Sekarang apa yang harus dilakukan?"
  },
  AvgDialog_58290_Content_63 = {
    Text = "Lebih baik kita menarik diri. Ini adalah kediaman seorang bangsawan, jadi kita harus tetap menjaga etika dasar."
  },
  AvgDialog_58290_Content_64 = {
    Text = "Ryker, sambil berbicara, mundur beberapa langkah ke belakang."
  },
  AvgDialog_58290_Content_65 = {
    Text = "Kemudian dia tiba-tiba melompat dengan cepat dan menendang pintu dengan keras ——"
  },
  AvgDialog_58290_Content_66 = {Text = "BRASSHH!!"},
  AvgDialog_58290_Content_67 = {
    Text = "Pintu kayu ek yang kokoh tiba-tiba ditendang hingga terbentuk lubang besar. Ryker memasukkan tangannya ke dalam lubang itu, dengan mudah meraih gagang pintu, lalu membuka pintu itu dengan tenang."
  },
  AvgDialog_58290_Content_68 = {
    Text = "Silakan wanita terlebih dahulu, mohon ——"
  },
  AvgDialog_58290_Content_7 = {
    Text = "Tolong kirimkan tagihan kami bersama dengan miliknya, hehehe~"
  },
  AvgDialog_58290_Content_70 = {
    Text = "<Shake: Bagaimana dengan etika, kesopanan yang seharusnya?>"
  },
  AvgDialog_58290_Content_71 = {
    Text = "Maaf, sedikit tata krama yang saya miliki hanya berlaku untuk manusia. Lihat dengan jelas, apa itu?"
  },
  AvgDialog_58290_Content_72 = {
    Text = "Hanna mengikuti pandangan Ryker ke depan. Di samping meja, terdapat sebuah pemutar piringan hitam tegak, dengan piringan hitam yang berputar perlahan."
  },
  AvgDialog_58290_Content_73 = {
    Text = "Maaf, aku sekarang merasa tidak enak badan. Bolehkah aku beristirahat sebentar?"
  },
  AvgDialog_58290_Content_74 = {
    Text = "Maaf, @2 tidak terlalu nyaman... istirahat..."
  },
  AvgDialog_58290_Content_75 = {
    Text = "Istirahat sejenak @2 kali……"
  },
  AvgDialog_58290_Content_76 = {
    Text = "Harap semua orang segera pergi, jangan mengganggu waktu istirahat Tuan Dexter."
  },
  AvgDialog_58290_Content_77 = {
    Text = "<Shake:Wahhh!! Kamu dari kapan…>"
  },
  AvgDialog_58290_Content_78 = {
    Text = "Nona Erica, meskipun kamu sudah diubah menjadi bodoh oleh orang itu, aku tetap ingin mengingatkanmu..."
  },
  AvgDialog_58290_Content_79 = {
    Text = "Di sini tidak ada sehelai rambut pun dari Dexter."
  },
  AvgDialog_58290_Content_8 = {
    Text = "Sialan! N pasti sudah melakukan sesuatu padaku…"
  },
  AvgDialog_58290_Content_80 = {
    Text = "Harap semua orang segera pergi, jangan…"
  },
  AvgDialog_58290_Content_81 = {
    Text = "Lupakan dia untuk sekarang. Ada apa dengan pemutar rekaman hitam ini?"
  },
  AvgDialog_58290_Content_82 = {
    Text = "Sangat sederhana. Seseorang sedang membuat alibi, tapi sayangnya langsung ketahuan oleh saya."
  },
  AvgDialog_58290_Content_83 = {
    Text = "Begitu ya. Aku mengerti! Dalam novel detektif, di mana ada alibi, di situ ada kejahatan—"
  },
  AvgDialog_58290_Content_84 = {Text = "BRAK!"},
  AvgDialog_58290_Content_85 = {
    Text = "Sebuah suara tembakan yang tiba-tiba memecahkan keheningan malam."
  },
  AvgDialog_58290_Content_86 = {
    Text = "<Shake:Itu... dari lantai bawah, sepertinya...>"
  },
  AvgDialog_58290_Content_87 = {
    Text = "Lihat dulu. Sepertinya permainan… sudah dimulai."
  },
  AvgDialog_58290_Content_9 = {Text = "Permisi..."},
  AvgDialog_58291_Content_1 = {
    Text = "Tidak ada yang tersisa hidup"
  },
  AvgDialog_58291_Content_10 = {
    Text = [[
Rumah Franter
23:45]]
  },
  AvgDialog_58291_Content_100 = {
    Text = "Baiklah, baiklah, terserah kalian semua—"
  },
  AvgDialog_58291_Content_101 = {
    Text = "Baiklah, untuk waktu berikutnya Erica akan membawa kalian semua bermain. Masih ada 1124 makhluk yang menunggu untuk menandatangani Kontrak Iblis denganku."
  },
  AvgDialog_58291_Content_102 = {
    Text = "Ingatlah……"
  },
  AvgDialog_58291_Content_103 = {
    Text = "<Red:Orang jahat bersembunyi di antara semua orang, jadi jangan percaya siapa pun.>"
  },
  AvgDialog_58291_Content_104 = {Text = "?!"},
  AvgDialog_58291_Content_106 = {
    Text = "Apa yang kalian lihat? Aku belum sempat melakukan apa pun!"
  },
  AvgDialog_58291_Content_107 = {
    Text = "Oh? Coba jelaskan, apa rencanamu sebelumnya?"
  },
  AvgDialog_58291_Content_108 = {
    Text = "Luar biasa, teruskan semangat berdebat ini, jangan biarkan kehadiranku memengaruhi performa kalian!"
  },
  AvgDialog_58291_Content_109 = {
    Text = "Kode etik kami yang pertama, kekacauan! Kedua, kekacauan! Ketiga…"
  },
  AvgDialog_58291_Content_11 = {
    Text = "Pintu kayu yang berat terbuka dengan satu dorongan. Ryker membuka kedua tangannya, melangkah masuk ke aula dengan antusiasme yang sedikit berlebihan."
  },
  AvgDialog_58291_Content_110 = {
    Text = "Biarkan aku menebak, apakah masih kacau?"
  },
  AvgDialog_58291_Content_111 = {
    Text = "Salah! Itu <Red:kekacauan tanpa akhir>!"
  },
  AvgDialog_58291_Content_113 = {
    Text = "Kalau begitu, selamat bersenang-senang~"
  },
  AvgDialog_58291_Content_114 = {
    Text = "N berkata, lalu berubah menjadi kabut hitam pekat dan menghilang, meninggalkan semua orang saling berpandangan."
  },
  AvgDialog_58291_Content_115 = {
    Text = "%player%, siapa sebenarnya orang menyebalkan ini? Sepertinya kalian sudah lama mengenal-Nya?"
  },
  AvgDialog_58291_Content_116 = {
    Text = "Kamu merenung, ragu apakah akan memberitahu Hanna semua yang kamu ketahui. Namun, segera kamu menyadari bahwa kamu terlalu banyak berpikir."
  },
  AvgDialog_58291_Content_117 = {
    Text = "Bagi N, kamu juga tidak tahu apa-apa."
  },
  AvgDialog_58291_Content_118 = {
    Text = "Maaf, aku juga tidak tahu apa-apa tentang orang ini. Setelah berubah penampilan, kepribadiannya juga menjadi lebih..."
  },
  AvgDialog_58291_Content_119 = {
    Text = "Kamu sebenarnya ingin mengatakan \"ceria\", tapi kata-kata itu tertahan di ujung lidahmu dan akhirnya kembali ditelan."
  },
  AvgDialog_58291_Content_12 = {
    Text = "Dekster, teman lamaku! Baru beberapa hari tidak bertemu, kau sudah tak sabar mengundang kami ke mansion-mu untuk melanjutkan pertemuan kita?"
  },
  AvgDialog_58291_Content_120 = {
    Text = "Lebih menjengkelkan."
  },
  AvgDialog_58291_Content_121 = {
    Text = "Jika saya tidak salah paham, kita harus memecahkan teka-teki dan menemukan <Yellow:kebenaran terakhir>, bukan?"
  },
  AvgDialog_58291_Content_122 = {
    Text = "Hmm… memang begitu."
  },
  AvgDialog_58291_Content_123 = {
    Text = "Ada sedikit masalah. Sepertinya orang ini lupa menyebutkan topiknya."
  },
  AvgDialog_58291_Content_124 = {
    Text = "Memang kekacauan yang tak berujung."
  },
  AvgDialog_58291_Content_125 = {
    Text = "Kamu menatap jembatan putus di depan yang telah hancur tak tersisa. Lembah yang gelap tampak seperti jurang tanpa dasar, sepenuhnya memisahkan kalian dari pulau di kejauhan."
  },
  AvgDialog_58291_Content_126 = {
    Text = "Tuan Dexter, apakah Anda yakin bahwa ini adalah satu-satunya jalan menuju dunia luar?"
  },
  AvgDialog_58291_Content_127 = {
    Text = "Dexter mengangkat bahu dengan rasa pasrah."
  },
  AvgDialog_58291_Content_128 = {
    Text = "Saya memilih tempat ini karena lokasinya cukup terpencil, yang dapat membantu saya menghindari banyak interaksi sosial dan perhatian yang tidak penting."
  },
  AvgDialog_58291_Content_129 = {
    Text = "Tidak disangka malah menjadi bumerang."
  },
  AvgDialog_58291_Content_13 = {
    Text = "Tentu saja, saya harus mengingatkanmu bahwa cara mengundang seperti ini terbilang cukup ekstrem."
  },
  AvgDialog_58291_Content_130 = {
    Text = "Salju turun dengan lebat, segera menutupi jembatan kayu yang mengalami kerusakan."
  },
  AvgDialog_58291_Content_131 = {
    Text = "Hatsjoo! Badai salju, pondok terpencil, dan orang-orang yang entah bagaimana berkumpul bersama…"
  },
  AvgDialog_58291_Content_132 = {
    Text = "Saya memiliki firasat yang tidak terlalu baik."
  },
  AvgDialog_58291_Content_14 = {
    Text = "<Small:Hei, bagaimana dengan penyergapan yang dijanjikan!>"
  },
  AvgDialog_58291_Content_15 = {
    Text = "Saya tahu apa yang kalian maksud — bukan saya yang melakukannya."
  },
  AvgDialog_58291_Content_16 = {
    Text = "Dexter duduk di ujung meja panjang, dengan sedikit tidak sabar menggaruk rambutnya yang berantakan."
  },
  AvgDialog_58291_Content_17 = {
    Text = "<Gray:Sepertinya Ramona pernah berkata, suasana hati Tuan Dexter akan menjadi sangat buruk ketika tidurnya terganggu…>"
  },
  AvgDialog_58291_Content_18 = {
    Text = "Awalnya, aku sedang tidur nyenyak di rumah. Tiba-tiba, sekelompok orang datang mengetuk pintu, dan semua pelayan menghilang."
  },
  AvgDialog_58291_Content_19 = {
    Text = "Sampai sekarang, aku masih tidak paham apa yang terjadi."
  },
  AvgDialog_58291_Content_2 = {
    Text = [[
Rumah Franter
23:30]]
  },
  AvgDialog_58291_Content_20 = {
    Text = "Sekelompok orang...?"
  },
  AvgDialog_58291_Content_21 = {Text = "Kacha!"},
  AvgDialog_58291_Content_22 = {
    Text = "Sekejap cahaya putih berkedip di depan mata, lalu ruangan segera kembali ke kesunyian seperti semula."
  },
  AvgDialog_58291_Content_23 = {
    Text = "Hmm, tetap tidak bisa memotret apa pun. Di sini memang ada yang aneh…"
  },
  AvgDialog_58291_Content_24 = {
    Text = "Hanna?! Bagaimana kamu bisa di sini?"
  },
  AvgDialog_58291_Content_25 = {
    Text = "Hmph, gelar Wakil Presiden Asosiasi Penyelidikan bukanlah sesuatu yang diperoleh dengan mudah! Aku adalah yang paling ahli dalam menemukan jalan."
  },
  AvgDialog_58291_Content_26 = {
    Text = "Selamat malam, %player%{Male=tuan,Female=nyonya}, selamat malam, Bos!"
  },
  AvgDialog_58291_Content_27 = {Text = "Hmm."},
  AvgDialog_58291_Content_28 = {
    Text = "Boss...? Tak disangka kalian berdua ternyata saling kenal."
  },
  AvgDialog_58291_Content_29 = {
    Text = "Tuan Ryker adalah detektif terkenal di wilayah timur. Kami berdua bekerja sama dengan sempurna, penjahat yang melihat kami pasti akan menghindar!"
  },
  AvgDialog_58291_Content_3 = {
    Text = "Yohoo! Penurunan cepat berhasil~"
  },
  AvgDialog_58291_Content_30 = {
    Text = "Huh, tolong kendalikan kebiasaan profesionalmu. Sekarang bukan waktunya menulis artikel berita."
  },
  AvgDialog_58291_Content_31 = {
    Text = "Ryker mengangkat kedua tangannya dengan ekspresi putus asa ke arahmu."
  },
  AvgDialog_58291_Content_32 = {
    Text = "Aku kadang meminta dia untuk membantu mengurus beberapa kasus sebagai balasannya, dia mendapatkan banyak informasi dariku. Bisa dibilang ini saling menguntungkan."
  },
  AvgDialog_58291_Content_33 = {
    Text = "Berbicara tentang saling menguntungkan, apakah ada orang lain yang juga memiliki hubungan erat dengan Mythag?"
  },
  AvgDialog_58291_Content_34 = {
    Text = "Kamu mengikuti pandangan Ryker, dan di sudut bayangan, seorang wanita berpakaian mewah memegang gelas anggur merah sambil tersenyum dan memberi hormat kepadamu."
  },
  AvgDialog_58291_Content_35 = {
    Text = "Bertemu lagi, Penjaga {Male=tuan,Female=nyonya}."
  },
  AvgDialog_58291_Content_36 = {
    Text = "Nyonya Sorel?! Kamu, bagaimana bisa kamu juga..."
  },
  AvgDialog_58291_Content_37 = {
    Text = "Sangat disayangkan, aku sebenarnya berharap kita bisa bertemu lagi di kesempatan yang lebih formal."
  },
  AvgDialog_58291_Content_38 = {
    Text = "Sayangnya, di sini hanya ada rumah besar yang terpencil dan gelas kosong di tangan. Apa yang bisa dilakukan untuk menghabiskan waktu?"
  },
  AvgDialog_58291_Content_39 = {
    Text = "Tentu saja, mengisi gelas dengan penuh dan minum sepanjang malam~!"
  },
  AvgDialog_58291_Content_4 = {
    Text = "Apa kamu yakin Dexter tinggal di tempat yang mengerikan seperti ini? Mungkin dia sudah bangkrut."
  },
  AvgDialog_58291_Content_40 = {
    Text = "Diiringi suara wanita yang riang dan ceria, anggur merah di cangkir Sorel secara ajaib kembali terisi penuh."
  },
  AvgDialog_58291_Content_41 = {
    Text = "Benar-benar mengejutkan, aroma anggur Chardonnay... Bagaimana ini bisa terjadi?"
  },
  AvgDialog_58291_Content_42 = {
    Text = "Hihi, apa ini? Lihat yang ini —"
  },
  AvgDialog_58291_Content_43 = {
    Text = "Casiah mengetuk tepi cangkir dengan tongkatnya, dan anggur merah itu seketika mekar menjadi mawar-mawar merah segar yang bergetar lembut di bawah sorotan cahaya."
  },
  AvgDialog_58291_Content_44 = {
    Text = "Dia memetik salah satu bunga yang paling cantik, lalu dengan lembut menyematkannya di belakang telinga Sorel."
  },
  AvgDialog_58291_Content_45 = {
    Text = "Mawar paling cantik, dipersembahkan kepada kecantikan paling memesona di Londinium."
  },
  AvgDialog_58291_Content_46 = {
    Text = "Sangat mengesankan, Nona Pesulap! Apakah Anda tertarik dengan posisi di istana? Saya harus merekomendasikan Anda kepada Yang Mulia Ratu."
  },
  AvgDialog_58291_Content_47 = {
    Text = "Jika harga sesuai, semuanya bisa dibicarakan…"
  },
  AvgDialog_58291_Content_48 = {
    Text = "Eh, bukankah ini Penjaga {Male=tuan,Female=nyonya} dan Tuan Detektif?"
  },
  AvgDialog_58291_Content_49 = {
    Text = "Casiah terlihat sangat terkejut, seolah-olah baru saja melihat kalian."
  },
  AvgDialog_58291_Content_5 = {
    Text = "Maaf, ini adalah salah satu properti yang paling tidak mencolok dari lebih dari lima puluh properti atas namanya."
  },
  AvgDialog_58291_Content_50 = {
    Text = "Sejak berpisah di Aran, aku memikirkan kalian setiap hari."
  },
  AvgDialog_58291_Content_53 = {
    Text = "Tunggu sebentar! William bukan aku yang membunuhnya, Casiah hanyalah pekerja yang malang. Apakah kalian benar-benar ingin berbuat kejam di rumah tuan yang terhormat ini?"
  },
  AvgDialog_58291_Content_54 = {
    Text = "Tidak masalah, aku tidak keberatan kalau kita keluar dan berbicara dengan baik."
  },
  AvgDialog_58291_Content_55 = {
    Text = "Sss... perlu diingat, aku sudah sangat memahami medan di sini."
  },
  AvgDialog_58291_Content_56 = {
    Text = "Kalau tidak bisa menang, setidaknya bisa kabur…"
  },
  AvgDialog_58291_Content_57 = {
    Text = "Dong—— dong——"
  },
  AvgDialog_58291_Content_58 = {
    Text = "Jam raksasa tiba-tiba melayang di atas kepala semua orang, dengan jarum jam tepat menunjuk pukul dua belas tengah malam."
  },
  AvgDialog_58291_Content_59 = {
    Text = "Para wanita dan pria, selamat malam! Selamat datang di taman hiburan saya!"
  },
  AvgDialog_58291_Content_6 = {
    Text = "Sss… Tiba-tiba aku mendapat ide yang luar biasa —"
  },
  AvgDialog_58291_Content_60 = {
    Text = "Uwaaa! Anak ini kenapa tidak memiliki wajah!"
  },
  AvgDialog_58291_Content_61 = {
    Text = "Penampilan dan perasaan yang sudah tidak asing ini, mungkinkah itu……"
  },
  AvgDialog_58291_Content_62 = {
    Text = "Selamat kepada semua atas kecerdasan dan semangat kerja sama Roh yang telah membantu kalian berhasil melewati tantangan pertama yang saya buat."
  },
  AvgDialog_58291_Content_63 = {
    Text = "Waktu pemanasan telah berakhir, sekarang mari kita dengarkan topik utama ——"
  },
  AvgDialog_58291_Content_64 = {Text = "BRAK!"},
  AvgDialog_58291_Content_65 = {
    Text = "Peluru dengan tepat menembus wajah makhluk misterius itu, meninggalkan lubang besar di tengahnya."
  },
  AvgDialog_58291_Content_66 = {
    Text = "Maaf, pistolku tidak sengaja meletus. Apakah permainan pura-pura ini menyenangkan, N?"
  },
  AvgDialog_58291_Content_67 = {
    Text = "Ternyata benar Dia…"
  },
  AvgDialog_58291_Content_68 = {
    Text = "Sisa kabut hitam di wajah N terus bergerak, memutar, dan memanjang, dengan cepat mengisi kekosongan."
  },
  AvgDialog_58291_Content_69 = {
    Text = "Benar-benar membosankan, begitu cepat dikenali oleh semua orang."
  },
  AvgDialog_58291_Content_7 = {
    Text = "Sebelumnya, jangan bermain curang dengan Tuan Dexter. Dia tidak tertarik pada segala bentuk perjudian, investasi yang tidak jelas, dan usaha berisiko."
  },
  AvgDialog_58291_Content_70 = {
    Text = "Tuan Ryker sangat senang saat melakukan serangan di bawah bulan. Apakah kamu menyukai permainan pura-pura yang kubuat khusus untukmu?"
  },
  AvgDialog_58291_Content_71 = {
    Text = "Heh... cukup biasa. Apakah ini Domain-mu?"
  },
  AvgDialog_58291_Content_72 = {
    Text = "Tentu. Jika ingin keluar, tinggalkan aku di rumah ini dan dengan patuh pecahkan teka-teki yang kubuat."
  },
  AvgDialog_58291_Content_73 = {
    Text = "Hei, ini rumahku. Tidak ada yang meminta pendapatku?"
  },
  AvgDialog_58291_Content_74 = {
    Text = "Kresek… kresek…"
  },
  AvgDialog_58291_Content_75 = {Text = "Duaaarr!!"},
  AvgDialog_58291_Content_76 = {
    Text = "Bagus, asisten kecil saya sudah memotong satu-satunya jembatan menuju dunia luar."
  },
  AvgDialog_58291_Content_77 = {
    Text = "Sekarang kalian benar-benar tidak bisa pergi ke mana pun!"
  },
  AvgDialog_58291_Content_78 = {
    Text = "Apa?! Cepat keluar dan lihat——"
  },
  AvgDialog_58291_Content_79 = {
    Text = "Segala sesuatu begitu sunyi. Kalian berdiri di depan jembatan putus di tepi tebing, terdiam tanpa mengucapkan sepatah kata pun."
  },
  AvgDialog_58291_Content_8 = {
    Text = "Detektif yang terganggu dengan kasar menarik kembali tangannya dengan rasa kesal, hanya dengan keras kepala mengangkat dagunya dan menunjuk ke arah mansion yang tak jauh."
  },
  AvgDialog_58291_Content_80 = {
    Text = "Entah sejak kapan salju lebat mulai turun dari langit, melayang-layang di udara."
  },
  AvgDialog_58291_Content_81 = {
    Text = "Kamu menggenggam erat kunci perak yang redup di depan dada. Sejak melangkah ke tanah ini, hubungan antara kamu dan kunci itu telah sepenuhnya terputus."
  },
  AvgDialog_58291_Content_82 = {
    Text = "Tidak ada gunanya. Aku sudah memutuskan hubungan kalian dengan @2, sekarang kalian tidak memiliki kemampuan istimewa apa pun yang melebihi manusia biasa."
  },
  AvgDialog_58291_Content_83 = {
    Text = "Ternyata kau yang melakukannya..."
  },
  AvgDialog_58291_Content_84 = {
    Text = "Tenang saja, meskipun kamu membelalakkan mata sekuat tenaga juga tidak akan berguna, lho."
  },
  AvgDialog_58291_Content_85 = {
    Text = "Seorang pahlawan sejati harus menyelesaikan masalah seperti orang biasa. Apakah saya benar, Erica?"
  },
  AvgDialog_58291_Content_86 = {Text = "Erica…?"},
  AvgDialog_58291_Content_87 = {
    Text = "Langkah-langkah mekanis terdengar dari sudut."
  },
  AvgDialog_58291_Content_88 = {
    Text = "Erica memegang gergaji elektromagnetik raksasa, tiba-tiba mengulurkan lengan, tali elastis yang menghubungkan anggota tubuh bioniknya ditarik hingga jarak yang sangat jauh, bahkan membelah jembatan di depannya."
  },
  AvgDialog_58291_Content_89 = {Text = "...?"},
  AvgDialog_58291_Content_9 = {
    Text = "Huh, huh, apa yang kamu pikirkan? Maksudku, sebaiknya kita masuk lebih awal, lalu bersembunyi untuk mengumpulkan informasi..."
  },
  AvgDialog_58291_Content_90 = {
    Text = "Lengan mekaniknya sangat menarik. Harus mencari cara untuk mendapatkannya…"
  },
  AvgDialog_58291_Content_91 = {
    Text = "Erica mematikan sakelar gergaji mesin, berjalan ke belakang N, dan bahkan membungkuk dengan hormat."
  },
  AvgDialog_58291_Content_92 = {
    Text = "Melaporkan kepada Tuan, satu-satunya lorong yang menghubungkan Flanard ke dunia luar telah mengalami kerusakan. Total waktu yang dibutuhkan adalah 5 menit 40 detik, konsumsi listrik..."
  },
  AvgDialog_58291_Content_93 = {
    Text = "Kamu ini... apa yang telah kamu lakukan pada Erica?!"
  },
  AvgDialog_58291_Content_94 = {
    Text = "N melompat dengan ringan ke pundak Erica, lalu duduk santai sambil menyilangkan kakinya."
  },
  AvgDialog_58291_Content_95 = {
    Text = "Tenang saja, aku hanya sedikit memengaruhi kesadarannya dengan pesona pribadiku. Perkenalkan, ini asisten baruku, Erica."
  },
  AvgDialog_58291_Content_96 = {
    Text = "Erica, segera ucapkan selamat malam kepada semua orang."
  },
  AvgDialog_58291_Content_97 = {
    Text = "Selamat malam, untuk waktu yang akan datang Erica akan bertanggung jawab mengawasi dan merawat kalian semua. Silakan ikuti saya kembali ke mansion."
  },
  AvgDialog_58291_Content_98 = {
    Text = "Sebelumnya, saya ingin menyatakan bahwa jika ada yang berani melawan asisten kecil baru saya..."
  },
  AvgDialog_58291_Content_99 = {
    Text = "N menekan sakelar gergaji listrik di tangan Erica dengan lembut. Suara yang memekakkan telinga membuat semua orang segera menutup telinga mereka."
  },
  AvgDialog_58292_Content_1 = {
    Text = "Pertemuan Pertama"
  },
  AvgDialog_58292_Content_10 = {
    Text = "Eh, eh aku selalu bersama Tuan Ryker, kan, Bos?"
  },
  AvgDialog_58292_Content_11 = {
    Text = "Tidak ada yang menanggapi panggilan Hannah yang sedikit penuh rasa bersalah."
  },
  AvgDialog_58292_Content_12 = {
    Text = "Di sisi lain rumah, Tuan Detektif dan asisten sementaranya telah memulai penyelidikan di tempat kejadian."
  },
  AvgDialog_58292_Content_13 = {
    Text = "Kedua sepatu itu menghilang. Ada dua bekas cekikan di leher, sungguh aneh."
  },
  AvgDialog_58292_Content_14 = {
    Text = "Kamu menggunakan kaca pembesar untuk memeriksa dengan cermat dua bekas luka di leher Tuan Dexter. Pola kedua bekas itu hampir sama, hanya terdapat sedikit perbedaan dalam sudut kemiringannya."
  },
  AvgDialog_58292_Content_15 = {
    Text = "Dua bekas tali memiliki pola yang tidak konsisten. Di bagian dalam terdapat struktur berbentuk belah ketupat yang rapi, sedangkan di bagian luar lebih kasar…"
  },
  AvgDialog_58292_Content_16 = {
    Text = "Mungkin tali putus di tengah jalan, atau mungkin terkena darah, sehingga pelaku mengganti tali tersebut dengan yang baru."
  },
  AvgDialog_58292_Content_17 = {
    Text = "Bagaimanapun, dua bekas cekikan itu melintasi bagian depan leher, melewati dagu, lalu menjalar ke belakang telinga, dan secara bertahap menghilang menuju bagian belakang kepala…"
  },
  AvgDialog_58292_Content_18 = {
    Text = "Ini adalah bekas jeratan yang muncul akibat bunuh diri dengan cara gantung diri."
  },
  AvgDialog_58292_Content_19 = {
    Text = "Tidak, tidak tepat... Ada bekas cakaran di sekitar lebam, yang menunjukkan bahwa korban sempat mengalami perjuangan keras."
  },
  AvgDialog_58292_Content_2 = {
    Text = [[
Ruang Kerja Lantai Satu, Kediaman Flannder
Waktu tersisa hingga kasus selesai: <Red:90> menit]]
  },
  AvgDialog_58292_Content_20 = {
    Text = "Mungkin juga setelah mencoba bunuh diri dengan gantung diri, dia mulai menyesal? Saya pernah mendengar kasus serupa."
  },
  AvgDialog_58292_Content_21 = {
    Text = "Jika bukan karena piringan hitam itu, sembilan dari sepuluh polisi yang datang ke sini pasti akan menutup kasus ini sebagai bunuh diri."
  },
  AvgDialog_58292_Content_22 = {
    Text = "Dan aku adalah satu-satunya yang tersisa, sepuluh persen dengan pandangan tajam seperti api!"
  },
  AvgDialog_58292_Content_23 = {
    Text = "Piringan hitam?"
  },
  AvgDialog_58292_Content_24 = {
    Text = "Penjaga {Male=tuan,Female=nyonya} tidak berada di tempat saat itu! Ada sebuah rekaman piringan hitam yang terus memutar suara Tuan Dexter, seperti hantu…"
  },
  AvgDialog_58292_Content_25 = {
    Text = "Hanna tiba-tiba menyelip di antara kalian, dengan penuh semangat menggambarkan ceritanya, lalu tanpa sadar bergidik dan menggigil."
  },
  AvgDialog_58292_Content_26 = {
    Text = "Boss, tadi kami sudah mencari ke mana-mana tapi tidak melihat tanda-tanda Nyonya Sorel. Apakah dia sudah…"
  },
  AvgDialog_58292_Content_27 = {
    Text = "Ryker dengan percaya diri melambaikan tangannya."
  },
  AvgDialog_58292_Content_28 = {
    Text = "Segera kalian akan mengetahui di mana dia berada. Kasus ini hampir sama dengan kasus pembunuhan pertama yang pernah aku tangani."
  },
  AvgDialog_58292_Content_29 = {
    Text = "Apakah ini yang dimaksud bos tadi dengan \"intuisi\"…"
  },
  AvgDialog_58292_Content_3 = {
    Text = "Dia saat itu sedang berkeliaran di luar rumah, mencari jalan untuk meninggalkan tempat ini."
  },
  AvgDialog_58292_Content_30 = {
    Text = "Huh, maafkan aku. Memang benar."
  },
  AvgDialog_58292_Content_31 = {
    Text = "Piringan hitam, rumah kosong yang tandus, tuan rumah pria yang tergantung secara misterius… Hannah juga ingat!"
  },
  AvgDialog_58292_Content_32 = {
    Text = "\"Pria Misterius Berkepala Anjing Ungkap Skandal Keluarga Kaya\", sampai sekarang aku masih ingat headline berita dari tahun itu!"
  },
  AvgDialog_58292_Content_33 = {
    Text = "Kepala anjing? Judul ini pasti karanganmu sendiri. Di luar sana, aku selalu tampil sebagai seorang pria terhormat."
  },
  AvgDialog_58292_Content_34 = {
    Text = "Begitu menyebut masa lalu Ryker, kamu langsung tertarik dan menarik Hannah mendekat."
  },
  AvgDialog_58292_Content_35 = {
    Text = "<Small:Ngomong-ngomong, aku selalu merasa identitasnya sebagai detektif agak mencurigakan.>"
  },
  AvgDialog_58292_Content_36 = {
    Text = "<Small:Ketahuilah, di Londinium, imbalan untuk mengungkap sebuah kasus jauh lebih rendah dibandingkan dengan pendapatan dari duduk di meja judi selama sepuluh menit.>"
  },
  AvgDialog_58292_Content_37 = {
    Text = "<Small:Mungkin identitas detektif hanyalah kedok saja…>"
  },
  AvgDialog_58292_Content_38 = {
    Text = "Tolong tarik kembali serangan pribadimu terhadapku, Penjaga %player%. Penjudi juga bisa memiliki hobi dan karier mereka sendiri."
  },
  AvgDialog_58292_Content_39 = {
    Text = "Eh, kenapa ada peti mati di sini? Selera Dexter benar-benar tidak terpuji."
  },
  AvgDialog_58292_Content_4 = {
    Text = "Artinya, tidak ada alibi. Catat... Apakah kamu berhasil menemukan jalan nantinya, Nona Casiah?"
  },
  AvgDialog_58292_Content_40 = {Text = "!!!"},
  AvgDialog_58292_Content_41 = {
    Text = "Jangan sentuh itu!"
  },
  AvgDialog_58292_Content_42 = {
    Text = "Sebelum suaranya hilang, sang detektif sudah dengan santai menendang peti mati dua kali. Yang menjawabnya hanyalah keheningan seperti kematian."
  },
  AvgDialog_58292_Content_43 = {
    Text = "Aneh... sepertinya tidak ada reaksi terhadap sentuhanmu?"
  },
  AvgDialog_58292_Content_44 = {
    Text = "Oh? Kalau begitu, coba katakan, bagaimana seharusnya reaksinya?"
  },
  AvgDialog_58292_Content_45 = {
    Text = "Kamu menceritakan semua kejadian yang dialami sebelumnya kepada Ryker."
  },
  AvgDialog_58292_Content_46 = {
    Text = "Ternyata begitu… aku mengerti!"
  },
  AvgDialog_58292_Content_47 = {
    Text = "Di dalamnya pasti terdapat mumi agung yang misterius dan memiliki kekuatan sihir luar biasa!"
  },
  AvgDialog_58292_Content_48 = {
    Text = "Ryker tiba-tiba berjongkok, mulutnya mengucapkan \"bahasa asing\" yang sama sekali tidak kamu pahami."
  },
  AvgDialog_58292_Content_49 = {
    Text = "Lumpur! Lihatlah @3!"
  },
  AvgDialog_58292_Content_5 = {
    Text = "Gunakan otak kecilmu, Nona Detektif. Jika aku sudah menemukannya, apakah aku masih akan berdiri di hadapanmu sekarang?"
  },
  AvgDialog_58292_Content_50 = {
    Text = "...Apa yang kamu maksud?"
  },
  AvgDialog_58292_Content_51 = {
    Text = "Lemvasi berbicara. \"Siput memakan cangkang, apa yang kamu makan sebanyak ini?\""
  },
  AvgDialog_58292_Content_52 = {
    Text = "Meskipun menghadapi sapaan ramah namun agak sulit dipahami dari luar, Peti Hitam tetap kalem dan tidak mengucapkan sepatah kata pun."
  },
  AvgDialog_58292_Content_53 = {
    Text = "Baiklah, cukup bermain-main. Aku pernah mendengar bahasa kuno Aran, dan pelafalannya tidak ada kemiripan sedikit pun dengan milikmu."
  },
  AvgDialog_58292_Content_54 = {
    Text = "Hmm, membosankan sekali. Lanjutkan saja pekerjaan kita."
  },
  AvgDialog_58292_Content_55 = {
    Text = "Ryker bangkit dengan santai, meregangkan tubuhnya, lalu menjentikkan jarinya dua kali ke udara."
  },
  AvgDialog_58292_Content_56 = {
    Text = "Baiklah semuanya, aku sudah tahu siapa pelakunya. Untuk menghemat waktu, aku akan langsung membawa kalian menangkapnya tanpa menjelaskan proses deduksi."
  },
  AvgDialog_58292_Content_57 = {Text = "...?"},
  AvgDialog_58292_Content_58 = {
    Text = "Puff. Jika ada novelis yang berani mendorong alur cerita seperti Tuan Ryker, mungkin mereka sudah lama digantung di lampu jalan oleh para pembaca yang marah."
  },
  AvgDialog_58292_Content_59 = {
    Text = "Apakah kamu tidak bersedia berbagi sedikit pun petunjuk kecil?"
  },
  AvgDialog_58292_Content_6 = {
    Text = "Eh… masuk akal."
  },
  AvgDialog_58292_Content_60 = {
    Text = "Ryker dengan sedikit kesal menggaruk rambutnya."
  },
  AvgDialog_58292_Content_61 = {
    Text = "Piringan hitam. Keberadaannya kemungkinan besar adalah upaya pembunuh untuk menciptakan alibi, menunda waktu kejadian."
  },
  AvgDialog_58292_Content_62 = {
    Text = "Artinya, tepat saat suara korban diputar dari rekaman piringan hitam, pembunuh sebenarnya sedang berada di lokasi kejadian."
  },
  AvgDialog_58292_Content_63 = {
    Text = "Tipu daya yang cerdik, namun sayangnya, aku tidak mengikuti skenario yang direncanakan oleh pelaku. Setelah mendengar suara itu, alih-alih pergi, aku malah menendang pintu hingga terbuka."
  },
  AvgDialog_58292_Content_64 = {
    Text = "Detektif yang kompeten membongkar alibi penjahat, sedangkan detektif yang luar biasa memutus alibi penjahat dari akarnya!"
  },
  AvgDialog_58292_Content_65 = {
    Text = "Apakah kamu mencatat pepatah yang sangat bijak ini, Hanna?"
  },
  AvgDialog_58292_Content_66 = {
    Text = "Ah? A-aku mencatatnya, Bos!"
  },
  AvgDialog_58292_Content_67 = {
    Text = "Tapi, Bos, tadi kamu bilang pelaku ada di tempat kejadian… lalu…"
  },
  AvgDialog_58292_Content_68 = {
    Text = "Ryker mengeluarkan pistolnya, lalu melangkah maju dengan langkah santai."
  },
  AvgDialog_58292_Content_69 = {
    Text = "Selanjutnya, mari kita hadirkan pelaku yang sejak kejadian hingga saat ini belum pernah muncul, hanya bisa panik dan bersembunyi di tempat gelap, Nona Pelaku."
  },
  AvgDialog_58292_Content_7 = {
    Text = "Dapur lantai satu. Pemilik rumah meminta untuk menyiapkan makanan bagi semua orang."
  },
  AvgDialog_58292_Content_70 = {
    Text = "Detektif berhenti di depan lemari pakaian, lalu dengan lembut mengetuk pintu dua kali."
  },
  AvgDialog_58292_Content_71 = {
    Text = "Masih ingin bersembunyi sampai detik terakhir? Kalau begitu, aku tidak akan segan-segan lagi—"
  },
  AvgDialog_58292_Content_72 = {
    Text = "Detektif dengan cemas menggosokkan laras pistol di pelipisnya, lalu membuka pintu lemari dengan cepat."
  },
  AvgDialog_58292_Content_73 = {Text = "Sorel…"},
  AvgDialog_58292_Content_74 = {Text = "?!"},
  AvgDialog_58292_Content_75 = {
    Text = "Nyonya Sorel!!!"
  },
  AvgDialog_58292_Content_76 = {
    Text = "Tidak ada pembenaran yang canggung, tidak ada pelarian yang memalukan, dan tidak ada penyesalan dengan air mata bercucuran."
  },
  AvgDialog_58292_Content_77 = {
    Text = "Hanya mayat Sorel yang diam bersandar di sudut, lubang peluru di tengah alisnya tampak sangat mencolok, seolah-olah mengejek detektif atas kesombongannya yang berlebihan."
  },
  AvgDialog_58292_Content_78 = {
    Text = "Tidak... ini tidak mungkin..."
  },
  AvgDialog_58292_Content_79 = {
    Text = "Ting ting ting!"
  },
  AvgDialog_58292_Content_8 = {
    Text = "Tidak ada yang pergi ke dapur selama periode itu, artinya, Nona Erica juga tidak memiliki alibi…"
  },
  AvgDialog_58292_Content_80 = {
    Text = "Sepertinya aku mendengar seseorang memberikan kesimpulan yang salah!"
  },
  AvgDialog_58292_Content_81 = {
    Text = "Menuduh seseorang yang tidak bersalah adalah kejahatan berat yang tidak terampuni, sekarang saatnya untuk hukuman!"
  },
  AvgDialog_58292_Content_82 = {
    Text = "N dengan sedikit kebingungan menopang dagu bulat-Nya. Setiap kali Dia berpikir, kecepatan gerakan kabut di wajah-Nya juga akan melambat."
  },
  AvgDialog_58292_Content_83 = {
    Text = "Hukuman, hukuman... Siapa yang baik untuk dibunuh?"
  },
  AvgDialog_58292_Content_9 = {
    Text = "Sayang sekali, Nona Detektif. Dari sudut pandang kami, kamu, Penjaga, dan Tuan Ryker juga terlihat mencurigakan~"
  },
  AvgDialog_58293_Content_1 = {
    Text = "Dinding Peti"
  },
  AvgDialog_58293_Content_10 = {
    Text = "Ini seharusnya pertemuan terakhir, namun hatimu tidak sedikit pun bergelombang."
  },
  AvgDialog_58293_Content_12 = {
    Text = "Kanak, nama saya Kanak."
  },
  AvgDialog_58293_Content_13 = {Text = "!!"},
  AvgDialog_58293_Content_14 = {
    Text = "Hmm… mimpi yang sangat aneh. Kenapa aku berada di koridor… Sejak menyentuh peti mati itu, pikiranku terus kacau."
  },
  AvgDialog_58293_Content_15 = {
    Text = "Deng deng deng."
  },
  AvgDialog_58293_Content_16 = {
    Text = "Diiringi oleh suara langkah kaki yang terburu-buru, kamu bertabrakan dengan sebuah bayangan hitam."
  },
  AvgDialog_58293_Content_17 = {
    Text = "Aduh! Jangan menghalangi jalan... Eh, ternyata Penjaga{Male=tuan,Female=nyonya}!"
  },
  AvgDialog_58293_Content_18 = {
    Text = "Hu... untung kamu tidak apa-apa. Aku pikir..."
  },
  AvgDialog_58293_Content_19 = {
    Text = "Kenapa kalian berdua di sini? Apakah ada sesuatu yang terjadi?"
  },
  AvgDialog_58293_Content_20 = {
    Text = "Rahasia saja, permainan berburu sudah dimulai loh~"
  },
  AvgDialog_58293_Content_21 = {
    Text = "Tubuh yang ramping meluncur dari kegelapan, Casiah mendarat dengan ringan di hadapan kalian seperti sedang melakukan sulap."
  },
  AvgDialog_58293_Content_22 = {
    Text = "Aku tahu dari mana suara tembakan itu berasal. Mau ikut aku pergi melihat? Aku agak takut pergi sendirian."
  },
  AvgDialog_58293_Content_23 = {
    Text = "Dari mana kamu tiba-tiba muncul..."
  },
  AvgDialog_58293_Content_24 = {
    Text = "Casiah tadi sedang tidur di lampu gantung yang tergantung di langit-langit. Ada pepatah yang mengatakan, semakin tinggi posisi, semakin jauh pandangan…"
  },
  AvgDialog_58293_Content_25 = {
    Text = "Aku bisa melihat semuanya, lho~"
  },
  AvgDialog_58293_Content_26 = {
    Text = "Setelah Casiah selesai berbicara, dia tersenyum ceria dan melemparkan pandangan genit ke arahmu."
  },
  AvgDialog_58293_Content_28 = {
    Text = "Kenapa kalian semua diam saja? Tidakkah kalian ingin menjadi saksi pertama di tempat kejadian?"
  },
  AvgDialog_58293_Content_29 = {
    Text = [[
Rumah Franter
Perpustakaan Lantai 1]]
  },
  AvgDialog_58293_Content_3 = {
    Text = "Sampai di sini saja, setelah ini kita akan berpisah jalan. Apakah kamu masih ingin mencari <Yellow:Dinding Kebenaran> itu?"
  },
  AvgDialog_58293_Content_30 = {
    Text = "Kalian membuka pintu ruang belajar dengan satu dorongan."
  },
  AvgDialog_58293_Content_31 = {
    Text = "I-ini adalah..."
  },
  AvgDialog_58293_Content_32 = {
    Text = "Tuan Dexter?!"
  },
  AvgDialog_58293_Content_33 = {
    Text = "Pria itu tergantung di bawah balok atap dengan tali, seperti daun yang bergoyang ditiup angin. Wajahnya diselimuti oleh bayangan kebiruan dan keunguan, matanya hampir saja melotot keluar dari rongganya."
  },
  AvgDialog_58293_Content_34 = {
    Text = "Harap semua orang tetap tenang, agar tidak merusak tempat kejadian perkara."
  },
  AvgDialog_58293_Content_35 = {
    Text = "TKP... lokasi kejadian?"
  },
  AvgDialog_58293_Content_36 = {
    Text = "Jangan lihat lagi, orang ini sudah mati sepenuhnya. Biar aku tebak, ini adalah teka-teki yang ditinggalkan untuk kita, kan?"
  },
  AvgDialog_58293_Content_37 = {
    Text = "Semacam permainan detektif dan teka-teki?"
  },
  AvgDialog_58293_Content_38 = {
    Text = "Bingo! Jawaban benar~!"
  },
  AvgDialog_58293_Content_39 = {
    Text = "Lalu, siapakah yang dengan kejam membunuh seorang bangsawan terhormat di malam bersalju seperti ini?"
  },
  AvgDialog_58293_Content_4 = {
    Text = "\"Kamu\" mengangguk."
  },
  AvgDialog_58293_Content_40 = {
    Text = "Silakan coba temukan kebenarannya, para detektif handal."
  },
  AvgDialog_58293_Content_41 = {
    Text = "Aneh sekali, bukankah yang paling mencurigakan adalah Anda, Tuan N?"
  },
  AvgDialog_58293_Content_42 = {
    Text = "Ehem, izinkan saya lebih tepat — silakan temukan pembunuh yang menyamar sebagai tiruan saya!"
  },
  AvgDialog_58293_Content_43 = {
    Text = "Tepat di antara kalian semua!"
  },
  AvgDialog_58293_Content_44 = {
    Text = "Sepi seperti kematian."
  },
  AvgDialog_58293_Content_45 = {
    Text = "Ketakutan dan kecemasan diam-diam menyebar di antara kerumunan. Pandangan mata seperti tidak sengaja menyapu orang lain, lalu diam-diam merenungkan kebenaran dalam perkataan N."
  },
  AvgDialog_58293_Content_46 = {
    Text = "Bagaimana jika kita menolak permainan ini?"
  },
  AvgDialog_58293_Content_47 = {
    Text = "Apakah kalian tahu apa yang paling penting bagi seorang desainer game yang penuh idealisme dan semangat seperti saya?"
  },
  AvgDialog_58293_Content_48 = {
    Text = "Tentu saja partisipasi pemain! Jika tidak ada yang tertarik, maka dengan berat hati saya harus mengumumkan bahwa permainan berakhir!"
  },
  AvgDialog_58293_Content_49 = {
    Text = "Tidak ada yang menjawab. Semua orang sedang menunggu \"tetapi\" yang akan datang ——"
  },
  AvgDialog_58293_Content_5 = {
    Text = "Kalau begitu, aku tidak akan membujukmu lagi. Jujur saja, aku selalu bingung denganmu... Kau tampak muda, tapi seolah-olah sudah hidup selama ribuan tahun."
  },
  AvgDialog_58293_Content_50 = {Text = "Namun!"},
  AvgDialog_58293_Content_51 = {
    Text = "Kasihan Tuan Dexter dan Nona Elsa, kami hanya bisa mengucapkan selamat tinggal untuk selamanya."
  },
  AvgDialog_58293_Content_52 = {
    Text = "Ruang Medis Mythag\nSementara itu……"
  },
  AvgDialog_58293_Content_53 = {
    Text = "Bagaimana keadaannya?"
  },
  AvgDialog_58293_Content_54 = {
    Text = "Tidak optimis. Pendarahan di dalam kepala Elsa parah, tekanan cairan cerebrospinal terus meningkat, suhu tubuhnya tetap di atas 100 derajat Fahrenheit."
  },
  AvgDialog_58293_Content_55 = {
    Text = "Penjaga dan Hannah jatuh ke dalam semacam kondisi delirium. Meskipun mereka terus-menerus tertidur lelap, semua tanda vital tubuh mereka normal."
  },
  AvgDialog_58293_Content_56 = {
    Text = "Mengerti. Lalu... bagaimana dengan dia?"
  },
  AvgDialog_58293_Content_57 = {
    Text = "Gadis itu tidak menyebutkan nama, tetapi semua orang di sana tahu kepada siapa dia merujuk."
  },
  AvgDialog_58293_Content_58 = {
    Text = "Tuan Dexter... Diagnosis awal menunjukkan bahwa henti jantung refleks disebabkan oleh penekanan saraf, seolah-olah telah mengalami semacam asfiksia mekanis."
  },
  AvgDialog_58293_Content_59 = {
    Text = "Detak jantung berhenti?"
  },
  AvgDialog_58293_Content_6 = {
    Text = "Bagaimanapun, terima kasih. Aku sudah mendapatkan cara untuk membuka segel itu. Selanjutnya, aku akan pergi ke Roma dan melepaskan binatang buas itu…"
  },
  AvgDialog_58293_Content_60 = {
    Text = "Kerang mengangguk."
  },
  AvgDialog_58293_Content_61 = {
    Text = "Upaya penyelamatan tidak berhasil, napasnya sudah berhenti lima menit yang lalu. Secara teori…"
  },
  AvgDialog_58293_Content_62 = {
    Text = "Dia sudah meninggal."
  },
  AvgDialog_58293_Content_63 = {
    Text = [[
Rumah Franter
Perpustakaan Lantai 1]]
  },
  AvgDialog_58293_Content_64 = {
    Text = "Artinya, jika kita tidak mengikuti aturanmu, orang yang meninggal di sini juga tidak akan bisa bangun di dunia nyata?"
  },
  AvgDialog_58293_Content_65 = {
    Text = "N mengangguk dengan puas."
  },
  AvgDialog_58293_Content_66 = {
    Text = "Benar-benar yang paling mengerti aku!"
  },
  AvgDialog_58293_Content_67 = {
    Text = "...Heh, aku sama sekali tidak merasa bangga akan hal ini."
  },
  AvgDialog_58293_Content_68 = {
    Text = "Bagaimana jika ini hanyalah tipuan belaka? Bagaimana kamu bisa membuktikan bahwa kamu tidak berbohong?"
  },
  AvgDialog_58293_Content_69 = {
    Text = "Tentu saja aku bisa membuktikannya — tapi aku tidak mau, hihi."
  },
  AvgDialog_58293_Content_7 = {
    Text = "Penyihir dengan susah payah mengepak barang bawaannya, baru saja berjalan beberapa langkah, lalu tiba-tiba berbalik lagi."
  },
  AvgDialog_58293_Content_70 = {
    Text = "Atau kalian bisa mencoba bertaruh? Akhiri permainan sekarang, kembali ke dunia kecil yang lucu milik kalian, dan semuanya tetap seperti semula."
  },
  AvgDialog_58293_Content_71 = {
    Text = "Selimut selalu hangat, ujian terus berlangsung, dan semua orang tetap sehat."
  },
  AvgDialog_58293_Content_72 = {
    Text = "N melihat ke arah Ryker, dengan semangat mengembangkan kedua tangannya yang kecil."
  },
  AvgDialog_58293_Content_73 = {
    Text = "Bagaimana, mau bertaruh? Ini adalah hal yang paling kamu kuasai."
  },
  AvgDialog_58293_Content_74 = {
    Text = "Maaf, aku tidak pernah mempertaruhkan nyawa orang lain."
  },
  AvgDialog_58293_Content_75 = {
    Text = "Permainan baru saja dimulai, berakhir begitu cepat akan terasa sangat membosankan!"
  },
  AvgDialog_58293_Content_76 = {
    Text = "Casiah bangkit, lalu dengan cepat mengangkat tangan kanannya."
  },
  AvgDialog_58293_Content_77 = {
    Text = "Bip bip! Saya setuju untuk melanjutkan permainan~!"
  },
  AvgDialog_58293_Content_78 = {
    Text = "Setelah berdiskusi panjang, dengan alasan yang berbeda-beda, kali ini semua orang secara mengejutkan mencapai kesepakatan."
  },
  AvgDialog_58293_Content_79 = {
    Text = "Benar-benar menyentuh! Terima kasih kepada semua orang atas penghormatan tanpa syarat terhadap hasil desain saya!"
  },
  AvgDialog_58293_Content_8 = {
    Text = "Hei, kamu belum memberitahuku namamu."
  },
  AvgDialog_58293_Content_80 = {
    Text = "Maka dengan ini saya umumkan: <Red:Ujian putaran kedua dimulai!>"
  },
  AvgDialog_58293_Content_81 = {
    Text = "Kalian memiliki waktu dua jam penuh untuk memecahkan teka-teki~"
  },
  AvgDialog_58293_Content_82 = {
    Text = "Baru dua jam, ini tidak cukup…"
  },
  AvgDialog_58293_Content_83 = {
    Text = "Oh hehe, sementara beberapa orang meragukan Yang Terhormat N, sepuluh detik lagi berlalu begitu saja."
  },
  AvgDialog_58293_Content_84 = {
    Text = "Kalau begitu, selamat bersenang-senang~"
  },
  AvgDialog_58293_Content_85 = {
    Text = "N berkata, lalu berubah menjadi asap hitam pekat dan menghilang tanpa suara."
  },
  AvgDialog_58293_Content_87 = {
    Text = "Ryker termenung, lalu tiba-tiba ia mengulurkan tangan dan mencubit pipimu."
  },
  AvgDialog_58293_Content_88 = {
    Text = "Sakit... Hei, apa yang kamu lakukan?!"
  },
  AvgDialog_58293_Content_89 = {
    Text = "Tenanglah. Konfirmasi apakah kamu bukan orang palsu."
  },
  AvgDialog_58293_Content_9 = {
    Text = "Angin mengangkat gumpalan pasir emas yang halus. Penyihir berpakaian compang-camping bersandar di langit biru, wajahnya yang kemerahan jarang menunjukkan kebaikan."
  },
  AvgDialog_58293_Content_90 = {
    Text = "Hmm, kehati-hatian yang sewajarnya memang diperlukan. Lalu——"
  },
  AvgDialog_58293_Content_91 = {
    Text = "Kamu dengan cepat menangkap bulu-bulu lebat di wajah Ryker dan mencabut beberapa helai dengan keras."
  },
  AvgDialog_58293_Content_92 = {Text = "Sisss!!"},
  AvgDialog_58293_Content_93 = {
    Text = "Mengendus... Terasa seperti barang asli."
  },
  AvgDialog_58293_Content_94 = {
    Text = "Jangan sungkan, semuanya untukmu. Ingatlah untuk mencuci bersih, mengeringkan, lalu menyimpan dengan baik."
  },
  AvgDialog_58294_Content_1 = {
    Text = "Di bawah realitas"
  },
  AvgDialog_58294_Content_10 = {
    Text = "Dia dengan teguh melangkahkan kakinya dan berjalan mendekati N."
  },
  AvgDialog_58294_Content_11 = {
    Text = "Penalaran yang salah? Tidak mungkin, pasti kamu sudah melakukan sesuatu di suatu tempat."
  },
  AvgDialog_58294_Content_12 = {
    Text = "Apakah kamu benar-benar melupakan dua bekas tali yang berbeda dan sepatu yang hilang?"
  },
  AvgDialog_58294_Content_13 = {
    Text = "Saya bisa segera menyebutkan puluhan kemungkinan, tetapi apakah semuanya benar-benar penting? Atau mungkin, sebenarnya tidak penting, hanya saja dalam pengaturanmu——"
  },
  AvgDialog_58294_Content_14 = {
    Text = "\"Aslinya\"? Sungguh aneh, jika tujuanku adalah mengungkap kebenaran <Red:Domain>, maka Domain adalah satu-satunya kenyataan dan referensi yang kalian andalkan saat ini."
  },
  AvgDialog_58294_Content_15 = {
    Text = "Kenapa seseorang selalu saja mempermasalahkan \"masa lalu\" ya~"
  },
  AvgDialog_58294_Content_16 = {Text = "!!"},
  AvgDialog_58294_Content_17 = {
    Text = "Mungkin di masa lalu, kamu berhasil menyelesaikan kasus ini dengan gemilang, mendapatkan sedikit kebanggaan dan rasa eksistensi, dan masih mengenangnya hingga sekarang."
  },
  AvgDialog_58294_Content_18 = {
    Text = "Namun, sangat disayangkan, di sini kamu benar-benar gagal total. Tuan Detektif."
  },
  AvgDialog_58294_Content_19 = {
    Text = "N perlahan mengangkat tangannya, lalu dengan lembut menjentikkan jarinya."
  },
  AvgDialog_58294_Content_2 = {
    Text = "Siapa yang harus dibunuh ya..."
  },
  AvgDialog_58294_Content_20 = {Text = "……Eh?"},
  AvgDialog_58294_Content_21 = {
    Text = "Detik berikutnya, dari tubuh Casiah yang semula hanya mengamati dengan tenang, tiba-tiba muncul asap hitam tipis."
  },
  AvgDialog_58294_Content_22 = {
    Text = "Diputuskan, hukuman akan dimulai darimu."
  },
  AvgDialog_58294_Content_23 = {
    Text = "Hei… Bukankah orang yang seharusnya gagal dalam penyelidikan itu adalah dia? Mengapa Casiah harus menanggung hukuman untuknya!"
  },
  AvgDialog_58294_Content_24 = {
    Text = "Tidak... sangat sulit..."
  },
  AvgDialog_58294_Content_25 = {
    Text = "Apakah kamu melihat? Setiap keputusan bodoh yang kamu buat akan ada orang yang menanggung akibatnya untukmu, sama seperti yang terjadi di dunia nyata."
  },
  AvgDialog_58294_Content_26 = {Text = "?!"},
  AvgDialog_58294_Content_27 = {
    Text = "Huu hu hu, aku belum puas bermain... apa hubungannya denganku..."
  },
  AvgDialog_58294_Content_28 = {
    Text = "Casiah menatap Ryker dengan kemarahan di matanya dan membanting tongkatnya ke arahnya."
  },
  AvgDialog_58294_Content_29 = {
    Text = "Semua salahmu! Bodoh sekali——argh!"
  },
  AvgDialog_58294_Content_3 = {
    Text = "<Shake: Maaf, sangat maaf, N Tuan!> Penalaran sebelumnya adalah omong kosong belaka. Kami semua tidak setuju!"
  },
  AvgDialog_58294_Content_30 = {
    Text = "Sebelum suaranya hilang, Casiah lenyap sepenuhnya di hadapan kalian, seolah-olah seseorang telah menghapusnya dari gambar dengan penghapus."
  },
  AvgDialog_58294_Content_31 = {
    Text = "Nyonya Casiah!"
  },
  AvgDialog_58294_Content_32 = {
    Text = "Hiks... dia berjanji akan mengajari aku beberapa trik sulap..."
  },
  AvgDialog_58294_Content_33 = {
    Text = "Baiklah semuanya, kalian hanya punya satu jam lagi. Jika tidak ada pertanyaan lain, maka——"
  },
  AvgDialog_58294_Content_34 = {
    Text = "……Tunggu."
  },
  AvgDialog_58294_Content_35 = {
    Text = "Detektif menepuk pundakmu, lalu melangkah maju."
  },
  AvgDialog_58294_Content_36 = {
    Text = "%player%, kalian lanjutkan penyelidikan. Aku ada beberapa hal yang ingin aku bicarakan dengannya."
  },
  AvgDialog_58294_Content_37 = {
    Text = "... mengerti."
  },
  AvgDialog_58294_Content_38 = {
    Text = "Kerumunan yang terkumpul kembali berpisah, kegelapan kental terus mengalir keluar, dengan cepat menelan habis Domain."
  },
  AvgDialog_58294_Content_39 = {
    Text = "Baiklah, sekarang kita bisa berbicara bebas. Bagaimana, apakah kamu menyukai avatar baruku tadi?"
  },
  AvgDialog_58294_Content_4 = {
    Text = "Saya ingin membantahnya sejak awal, namun sayangnya tidak pernah mendapatkan kesempatan…"
  },
  AvgDialog_58294_Content_40 = {
    Text = "Saya masih lebih terbiasa dengan penampilanmu saat ini."
  },
  AvgDialog_58294_Content_41 = {
    Text = "Sayang sekali. Akhir-akhir ini, saya terus merenung apakah penampilan saya terlalu menakutkan sehingga semua orang menjadi takut kepada saya."
  },
  AvgDialog_58294_Content_42 = {
    Text = "Percayalah padaku, jika kamu bersedia meninggalkan permainanmu yang kelam dan menyimpang itu, kamu pasti akan lebih disukai, tanpa perlu melakukan operasi penggantian kepala."
  },
  AvgDialog_58294_Content_43 = {
    Text = "Itu mungkin tidak bisa. Apakah kamu akan berhenti bernapas?"
  },
  AvgDialog_58294_Content_45 = {
    Text = "Baiklah, mari kita kembali ke pembahasan utama."
  },
  AvgDialog_58294_Content_46 = {
    Text = "Kamu baru saja berkata... semua orang akan membayar untuk kesalahan penilaianku, sama seperti yang terjadi di dunia nyata."
  },
  AvgDialog_58294_Content_47 = {
    Text = "Bisakah dijelaskan dengan lebih mudah?"
  },
  AvgDialog_58294_Content_48 = {
    Text = "N memiringkan kepalanya, dan kabut hitam segera menyelimuti-Nya dengan erat."
  },
  AvgDialog_58294_Content_49 = {
    Text = "Detik berikutnya, Dia berubah lagi menjadi sosok lain."
  },
  AvgDialog_58294_Content_5 = {
    Text = "Nona Hannah, saya yakin Anda juga tidak setuju dengan penalaran Tuan Ryker tadi, bukan?"
  },
  AvgDialog_58294_Content_50 = {
    Text = "Benar-benar ingin tahu? Ingat, jangan menangis nanti. Aku benci air mata manusia!"
  },
  AvgDialog_58294_Content_51 = {
    Text = "Ryker menyilangkan kedua tangannya, dengan ekspresi datar menatap N."
  },
  AvgDialog_58294_Content_52 = {
    Text = "Hm, benar-benar tidak ada yang bisa kulakukan tentangmu. Harus mulai dari mana ya… Ah, apakah kamu masih ingat gadis bernama Elsa?"
  },
  AvgDialog_58294_Content_53 = {
    Text = "Dalam cerita, detektif yang berani menunjukkan jalan kepada gadis itu, lalu membantunya mengusir monster pelarutan."
  },
  AvgDialog_58294_Content_54 = {
    Text = "Di dunia nyata, gadis itu mengikuti petunjuk detektif dan masuk ke jalan buntu, lalu dibunuh oleh monster pelarutan yang mengejarnya."
  },
  AvgDialog_58294_Content_55 = {Text = "?!"},
  AvgDialog_58294_Content_56 = {
    Text = "Ssst... tenang, dengarkan aku sampai selesai. Dalam cerita, seorang penjudi yang kebetulan lewat berhasil mengungkap kasus pembunuhan di sebuah rumah misterius, dan berubah menjadi detektif terkenal."
  },
  AvgDialog_58294_Content_57 = {
    Text = "Dalam kenyataan, penjudi telah menyalahkan orang yang tidak bersalah dan membiarkan pembunuh sejati bebas berkeliaran."
  },
  AvgDialog_58294_Content_58 = {
    Text = "Contohnya seperti ini, saya bisa menyebutkan banyak sekali. Tuan Detektif, apakah Anda pernah mempertimbangkan bahwa \"keberuntungan\" yang menjadi sandaran hidup Anda bukanlah penyebab yang membawa Anda sampai di sini, melainkan hasil dari perjalanan Anda?"
  },
  AvgDialog_58294_Content_59 = {Text = "Hasil...?"},
  AvgDialog_58294_Content_6 = {
    Text = "Ah… Aku, aku juga tidak setuju! Ini benar-benar sesuatu yang hanya bisa dibuat oleh orang gila yang kehilangan akal sehat!"
  },
  AvgDialog_58294_Content_60 = {
    Text = "Hasil yang telah dimanipulasi. Dewa memberikan keberuntungan kepada manusia, dengan syarat bahwa sisanya harus menanggung penderitaan untuknya."
  },
  AvgDialog_58294_Content_61 = {
    Text = "Seperti yang aku katakan sebelumnya, Domain adalah realitasmu."
  },
  AvgDialog_58294_Content_62 = {
    Text = "Maksudmu, semua yang kudapatkan di masa lalu berkat keberuntungan, orang-orang yang telah kubantu... semuanya palsu?"
  },
  AvgDialog_58294_Content_63 = {
    Text = "Hei, kenapa kamu terlihat seperti ingin menangis? Ingatlah, hidup dalam kebohongan juga bisa menjadi sebuah kebahagiaan."
  },
  AvgDialog_58294_Content_64 = {
    Text = "Jika tidak percaya, lihatlah Aran yang pernah kalian selamatkan sebelumnya. Inilah penampilan aslinya——"
  },
  AvgDialog_58294_Content_65 = {
    Text = "Lidah api menjilat langit, jeritan dan bau kulit terbakar membuat kepala pusing."
  },
  AvgDialog_58294_Content_66 = {
    Text = "Pola merah darah yang menggumpal mekar dari bawah Pohon Ibu, dengan riang berlari menuju kejauhan tanpa ujung."
  },
  AvgDialog_58294_Content_67 = {
    Text = "Potongan tubuh bertumpuk tinggi, seperti altar raksasa di bawah langit kuning pucat, bahkan melahap cahaya matahari sekalipun."
  },
  AvgDialog_58294_Content_68 = {
    Text = "Tepat di tengah kuil, Ryker melihat wajahnya sendiri. Wajah itu kelabu, kelopak matanya lembut terkulai di atas bola mata, tampak sangat lembut."
  },
  AvgDialog_58294_Content_69 = {
    Text = "Jika bukan karena separuh tengkoraknya telah terkikis, memperlihatkan batang otak yang dipenuhi belatung, ini akan menjadi wajah yang sempurna, milik seorang santo."
  },
  AvgDialog_58294_Content_7 = {Text = "...gila?"},
  AvgDialog_58294_Content_70 = {
    Text = "<Red:Cerita yang sebenarnya:> Kamu tidak berhasil menghentikan Casiah, tidak berhasil menghentikan Herbert, bahkan kamu tidak melihat perkemahan Alan."
  },
  AvgDialog_58294_Content_71 = {
    Text = "Sebenarnya, kamu tidak mencapai apa pun. Karena kamu tidak mencapai apa pun, Alan berubah menjadi seperti ini."
  },
  AvgDialog_58294_Content_72 = {
    Text = "Apakah kenyataan seperti ini masih kamu inginkan? Tuan Penjudi Tercinta."
  },
  AvgDialog_58294_Content_74 = {
    Text = "\"Realitas\" surut seperti gelombang pasang, hanya menyisakan Ryker berdiri sendirian dalam kegelapan."
  },
  AvgDialog_58294_Content_75 = {
    Text = "Huh. Jadi, kau bersusah payah merancang permainan seperti ini hanya untuk mengingatkan saya akan kegagalan saya?"
  },
  AvgDialog_58294_Content_76 = {
    Text = "Ini benar-benar tidak perlu. Jika dunia ini mengajari saya satu kebenaran, mungkin hanya tiga hal berikut: Saya adalah sampah. Maafkan saya. Ini memalukan."
  },
  AvgDialog_58294_Content_77 = {
    Text = "Hanya sebuah peringatan kecil. Aku tidak ingin melihat kejadian di Alan terulang untuk kedua kalinya."
  },
  AvgDialog_58294_Content_78 = {
    Text = "Jika kalian mencoba lagi permainan bodoh yang mengancam nyawa di lain waktu, yang lenyap bukan hanya beberapa orang ini saja, paham?"
  },
  AvgDialog_58294_Content_79 = {
    Text = "... diterima."
  },
  AvgDialog_58294_Content_8 = {Text = "Diamlah!"},
  AvgDialog_58294_Content_80 = {
    Text = "Detektif menundukkan kepala dan menjawab dengan malas."
  },
  AvgDialog_58294_Content_81 = {
    Text = "Kegelapan menyingkap tirai, dan dia kembali ke ruang belajar yang sudah dikenalnya."
  },
  AvgDialog_58294_Content_82 = {
    Text = "Hu... akhirnya kamu sadar! Tadi kamu tiba-tiba berdiri di sini tanpa bergerak, kami semua sangat khawatir!"
  },
  AvgDialog_58294_Content_83 = {
    Text = "Ada apa, Tuan Ryker? Wajahmu terlihat sangat buruk."
  },
  AvgDialog_58294_Content_84 = {
    Text = "Tidak apa-apa. Saya butuh waktu sendiri sejenak, akan segera kembali."
  },
  AvgDialog_58294_Content_85 = {
    Text = "Detektif itu tampak tenang, bahkan memberikan senyuman ramah kepada kalian."
  },
  AvgDialog_58294_Content_86 = {
    Text = "Dia hampir tidak menoleh sama sekali saat meninggalkan kalian."
  },
  AvgDialog_58294_Content_87 = {
    Text = "Tuan Ryker...?"
  },
  AvgDialog_58294_Content_9 = {
    Text = "Kamu menginjak keras kaki detektif, namun detektif yang penuh ambisi tidak menggubris isyarat kuatmu."
  },
  AvgDialog_58326_Content_1 = {
    Text = "Penalaran mundur"
  },
  AvgDialog_58326_Content_10 = {
    Text = "Jika ya, ketuk sekali. Jika tidak, ketuk dua kali. Apakah kamu bisa melakukannya?"
  },
  AvgDialog_58326_Content_11 = {
    Text = "Melalui papan kayu sandalwood yang tebal, suara Ryker terdengar memiliki kelembutan yang tidak terlalu nyata."
  },
  AvgDialog_58326_Content_12 = {
    Text = "Kamu mengetuk dengan lembut."
  },
  AvgDialog_58326_Content_13 = {
    Text = "Bagus sekali! Sebenarnya sangat mudah, saya hanya punya tiga pertanyaan."
  },
  AvgDialog_58326_Content_14 = {
    Text = "Pertanyaan pertama, apakah kamu terperangkap di dalam sesuatu?"
  },
  AvgDialog_58326_Content_15 = {
    Text = "<Yellow:Dung.>"
  },
  AvgDialog_58326_Content_16 = {
    Text = "Pertanyaan kedua, apakah kamu salah satu dari kami? \"Kami\" di sini mengacu pada orang-orang yang memasuki Domain miliknya."
  },
  AvgDialog_58326_Content_17 = {
    Text = "<Yellow:Dung.>"
  },
  AvgDialog_58326_Content_18 = {
    Text = "Bagus, intuisi saya tidak akan menipu saya. Pertanyaan ketiga…"
  },
  AvgDialog_58326_Content_19 = {
    Text = "Apakah kamu %player%?"
  },
  AvgDialog_58326_Content_2 = {
    Text = "Suara ketukan masih terus berlanjut."
  },
  AvgDialog_58326_Content_20 = {
    Text = "Kamu mengetuk peti mati dengan keras, lalu mendengar sebuah tawa kecil."
  },
  AvgDialog_58326_Content_21 = {
    Text = "Ternyata benar kamu. Jangan takut, aku akan memecahkan semua teka-teki, lalu menyelamatkanmu. Tetaplah di sini dengan tenang, mengerti?"
  },
  AvgDialog_58326_Content_22 = {
    Text = "<Yellow:Dung.>"
  },
  AvgDialog_58326_Content_23 = {
    Text = "Baiklah, temanku. Sampai jumpa."
  },
  AvgDialog_58326_Content_24 = {
    Text = "Terdengar suara gesekan pakaian di telinga, langkah kaki semakin menjauh."
  },
  AvgDialog_58326_Content_25 = {
    Text = "Kamu menghela napas panjang dan menutup mata. Namun, tak lama kemudian, suara langkah kaki itu pergi dan kembali lagi."
  },
  AvgDialog_58326_Content_26 = {
    Text = "Maaf, aku benar-benar lupa pada pertanyaan terpenting itu. Hal ini sangat penting untuk tindakanku selanjutnya."
  },
  AvgDialog_58326_Content_27 = {
    Text = "Kamu dengan tenang menunggu \"pertanyaan penting\" itu."
  },
  AvgDialog_58326_Content_28 = {
    Text = "Apakah kamu percaya padaku?"
  },
  AvgDialog_58326_Content_29 = {
    Text = "<Gray: Pertanyaan macam apa ini…>"
  },
  AvgDialog_58326_Content_3 = {
    Text = "Hei, teman di dalam peti mati, apakah kamu baik-baik saja?"
  },
  AvgDialog_58326_Content_30 = {
    Text = "Kamu tersenyum, lalu mengulurkan tangan untuk meraba dinding peti mati yang halus."
  },
  AvgDialog_58326_Content_31 = {
    Text = "——Dong."
  },
  AvgDialog_58326_Content_32 = {
    Text = "Saya percaya kamu."
  },
  AvgDialog_58326_Content_33 = {
    Text = "Ternyata begitu. Intuisimu selalu tajam."
  },
  AvgDialog_58326_Content_34 = {
    Text = "Namun, sangat disayangkan... {Male=dia,Female=dia} terjebak dalam kesadaran <Yellow:orang itu>, meskipun kamu berhasil mengungkap kebenaran terakhir, itu tetap tidak akan ada gunanya."
  },
  AvgDialog_58326_Content_35 = {
    Text = "Realitanya adalah, {Male=dia,Female=dia} akan terjebak selamanya dalam kesadaran wadah yang telah saya pilih dengan cermat."
  },
  AvgDialog_58326_Content_36 = {Text = "?!"},
  AvgDialog_58326_Content_37 = {
    Text = "Kamu pernah berkata, \"Selama semua kebenaran terungkap...\""
  },
  AvgDialog_58326_Content_38 = {
    Text = "Mist hitam yang mengalir perlahan di wajah N melingkar dengan nyaman, seakan-akan sedang menikmati hidangan lezat."
  },
  AvgDialog_58326_Content_39 = {
    Text = "Heh… Ini pertama kalinya aku melihat ekspresi seperti itu darimu. Sayang sekali, kemarahan tidak bisa menyelesaikan apa pun."
  },
  AvgDialog_58326_Content_4 = {
    Text = "Suara yang lembut dan menyenangkan terdengar, seakan memiliki kekuatan magis yang langsung menghentikan air matamu."
  },
  AvgDialog_58326_Content_40 = {
    Text = "Aku hanya berjanji akan membuka Domain, tapi aku tidak mengatakan bahwa semua orang akan selamat."
  },
  AvgDialog_58326_Content_41 = {
    Text = "Katakan selamat tinggal kepada teman kecilmu, Tuan Detektif."
  },
  AvgDialog_58326_Content_42 = {
    Text = "N mengangkat jarinya dengan lembut, namun pada detik berikutnya——"
  },
  AvgDialog_58326_Content_43 = {
    Text = "<Red:Mimpi buruk telah berakhir, bukalah mata.>"
  },
  AvgDialog_58326_Content_44 = {
    Text = "Gemuruh……"
  },
  AvgDialog_58326_Content_45 = {
    Text = "Lantai di bawah kaki tiba-tiba retak, ular raja hitam pekat meluncur keluar dari jurang tanpa dasar, dengan cepat menembus tubuh N."
  },
  AvgDialog_58326_Content_46 = {Text = "...?"},
  AvgDialog_58326_Content_47 = {
    Text = "Penjelasan: 80% dari tubuhku terdiri dari kabut, dan 20% sisanya juga kabut. Permainan sia-sia ini——"
  },
  AvgDialog_58326_Content_48 = {
    Text = "Cahaya redup perak tiba-tiba menyala terang, seolah-olah lampu yang menandakan dimulainya pertunjukan secara resmi."
  },
  AvgDialog_58326_Content_49 = {
    Text = "Seorang siswa dengan rambut keriting mengusap bahu yang terasa kaku menggunakan satu tangan, sementara tangan lainnya memegang kunci perak, lalu melangkah keluar dari bayangan."
  },
  AvgDialog_58326_Content_5 = {
    Text = "Maafkan saya atas kata-kata kasar yang saya ucapkan sebelumnya."
  },
  AvgDialog_58326_Content_50 = {
    Text = "Hu... akhirnya berhasil menyusul."
  },
  AvgDialog_58326_Content_51 = {
    Text = "Tidak salah aku menaruh harapan besar padamu! Aku tahu kau tidak mudah terjebak."
  },
  AvgDialog_58326_Content_52 = {
    Text = "Hmm, tentu saja."
  },
  AvgDialog_58326_Content_53 = {
    Text = "Beruntung ada teman-teman baru yang kukenal di dalam peti mati."
  },
  AvgDialog_58326_Content_54 = {Text = "Sss……"},
  AvgDialog_58326_Content_55 = {Text = "Ular...?"},
  AvgDialog_58326_Content_57 = {
    Text = "Lama tidak bertemu, Apophis."
  },
  AvgDialog_58326_Content_6 = {
    Text = "Tapi sekarang saya punya banyak pertanyaan dan ingin bertanya padamu dengan jelas. Apakah kamu tidak nyaman berbicara sekarang?"
  },
  AvgDialog_58326_Content_7 = {
    Text = "<Change>Ya!!!"
  },
  AvgDialog_58326_Content_8 = {
    Text = "Kamu berbicara dengan segenap tenaga, namun kata-kata yang sampai di bibirmu berubah menjadi gumaman tak jelas."
  },
  AvgDialog_58326_Content_9 = {
    Text = "Itu sedikit sulit... Ngomong-ngomong, apakah tanganmu masih bisa bergerak?"
  },
  AvgDialog_58327_Content_1 = {
    Text = "Semoga beruntung!"
  },
  AvgDialog_58327_Content_10 = {
    Text = "Dexter dengan polos melebarkan kedua tangannya."
  },
  AvgDialog_58327_Content_11 = {
    Text = "Saya juga sangat ingin tahu. Sebelum menginterogasi saya, tolong pahami dulu perbedaan antara kenyataan dan Domain."
  },
  AvgDialog_58327_Content_12 = {
    Text = "Lagipula, dalam kenyataan, tidak pernah ada kasus pembunuhan di rumahku, kan?"
  },
  AvgDialog_58327_Content_14 = {
    Text = "Apakah ada yang melihat Ryker? Elsa baru saja bangun dan langsung meminta tanda tangan Ryker."
  },
  AvgDialog_58327_Content_15 = {
    Text = "Tidak disangka Mr. Ryker juga memiliki penggemar... sungguh mengejutkan."
  },
  AvgDialog_58327_Content_16 = {
    Text = "Bagaimanapun juga, dia adalah orang yang telah menyelamatkannya dari cengkeraman monster. Jika harus dikatakan…"
  },
  AvgDialog_58327_Content_17 = {
    Text = "Alasan Elsa memilih bersekolah di Mythag juga adalah karena ia berharap suatu hari bisa menjadi seperti Tuan Ryker —"
  },
  AvgDialog_58327_Content_18 = {
    Text = "Menjadi seorang penjudi?"
  },
  AvgDialog_58327_Content_19 = {
    Text = "Pergi untuk membantu orang lain."
  },
  AvgDialog_58327_Content_2 = {
    Text = [[
Kampus Mythag 
Seminggu kemudian]]
  },
  AvgDialog_58327_Content_20 = {
    Text = "Ryker tidak suka berada di sekolah pada waktu biasa. Adapun %player%… {Male=dia,Female=dia} sudah pergi sejak pagi-pagi sekali, katanya ada urusan penting."
  },
  AvgDialog_58327_Content_21 = {
    Text = "Selain itu... aku selalu merasa ada yang tidak beres. Apakah N benar-benar hanya membuat Domain ini untuk menggoda Ryker?"
  },
  AvgDialog_58327_Content_22 = {
    Text = "Mungkin iya, mungkin juga tidak. Pertanyaan ini sama sulitnya dengan interferensi celah ganda. Saya pikir kita harus memikirkan masalah yang lebih praktis."
  },
  AvgDialog_58327_Content_23 = {
    Text = "Sebagai contoh, bagaimana dengan flu berat yang diderita Hanna."
  },
  AvgDialog_58327_Content_24 = {
    Text = "Di dalam gua yang gelap gulita dan tak bertepi, tak terhitung banyaknya mata perlahan membuka dan menutup, mirip dengan cahaya hantu yang berkedip-kedip di kegelapan malam."
  },
  AvgDialog_58327_Content_25 = {
    Text = "Angin dingin melintas, segumpal kabut hitam yang samar-samar terlihat bergerak pelan di tengah gua, dengan susah payah membentuk sosok manusia yang tidak jelas."
  },
  AvgDialog_58327_Content_26 = {
    Text = "<Change>Hu hu... Tuan... Cedera..."
  },
  AvgDialog_58327_Content_27 = {
    Text = "Sudah lama tidak bertemu, anak-anakku yang kubenci sekaligus kucintai. Sudah ratusan tahun sejak terakhir kali aku datang ke sini."
  },
  AvgDialog_58327_Content_28 = {
    Text = "Biarkan aku lihat apakah kalian sudah dewasa… Oh, maaf. Aku lupa bahwa kalian hanya memiliki bagian mata saja."
  },
  AvgDialog_58327_Content_29 = {
    Text = "<Change>Tuan... kasih..."
  },
  AvgDialog_58327_Content_30 = {
    Text = "Baiklah, obrolan nostalgia bisa kita simpan untuk lain waktu. Kali ini aku berhasil memastikan sesuatu yang menarik."
  },
  AvgDialog_58327_Content_31 = {
    Text = "Penjaga itu ternyata benar-benar bisa beresonansi dengan kesadaran Kanak… menarik."
  },
  AvgDialog_58327_Content_32 = {
    Text = "<Change>Hihii... lalala..."
  },
  AvgDialog_58327_Content_33 = {
    Text = "Bising sekali... Kebetulan proyeksi saya terluka, butuh sedikit penyembuhan kecil."
  },
  AvgDialog_58327_Content_34 = {
    Text = "Diam semuanya."
  },
  AvgDialog_58327_Content_35 = {Text = "——!!"},
  AvgDialog_58327_Content_36 = {
    Text = "Diiringi suara tangisan yang menyayat hati, semua mata remuk menjadi serpihan, darah menetes perlahan ke tanah."
  },
  AvgDialog_58327_Content_37 = {
    Text = "Kabut hitam tiba-tiba membeludak, dengan rakus menelan kabut darah yang memenuhi udara. Perlahan-lahan, sosok manusia yang tadinya samar-samar akhirnya mendapatkan bentuk nyata."
  },
  AvgDialog_58327_Content_38 = {
    Text = "Rasanya sangat buruk..."
  },
  AvgDialog_58327_Content_39 = {
    Text = [[
Pemakaman Highgate
Londinium Timur, Kent]]
  },
  AvgDialog_58327_Content_4 = {
    Text = "Apakah kamu sudah merasa lebih baik? Miss Sylvia mengatakan bahwa nafsu makanmu sangat buruk."
  },
  AvgDialog_58327_Content_40 = {
    Text = "Nah, orang malang pertama yang aku kirim ke penjara dimakamkan di sini."
  },
  AvgDialog_58327_Content_41 = {
    Text = "Kalian berhenti di depan sebuah nisan yang berdiri sendiri di sudut."
  },
  AvgDialog_58327_Content_42 = {
    Text = "Jika mengikuti hasil penyimpulan di Domain, sepertinya kamu telah mengirim orang yang salah. Lagipula, kamu masih belum bisa menjelaskan dua bekas cekikan itu, serta sepatu yang hilang."
  },
  AvgDialog_58327_Content_43 = {
    Text = "Saya tidak berpikir begitu. Bagaimana kamu tahu kalau bukan tali yang terkena darah pembunuh, lalu diganti dengan tergesa-gesa?"
  },
  AvgDialog_58327_Content_44 = {
    Text = "Adapun sepatu yang hilang —— sungguh aneh, di tengah malam di rumah sendiri tidak memakai sepatu tampaknya bukan hal yang aneh."
  },
  AvgDialog_58327_Content_45 = {
    Text = "Lagipula, butuh kekuatan dan presisi sebesar apa untuk mengangkat seseorang dari jendela lantai satu? Perlu diingat bahwa malam itu, selain korban yang meninggal, yang lainnya hanyalah wanita dan anak-anak."
  },
  AvgDialog_58327_Content_46 = {
    Text = "Hmm, alasan ini bisa aku terima."
  },
  AvgDialog_58327_Content_47 = {Text = "Jadi——"},
  AvgDialog_58327_Content_48 = {
    Text = "Ryker tersenyum lembut sambil menepuk kepala kecilmu."
  },
  AvgDialog_58327_Content_49 = {
    Text = "Dunia nyata bukanlah novel misteri, Penjaga. Tidak ada yang akan membunuh dengan cara begitu berbelit-belit."
  },
  AvgDialog_58327_Content_5 = {
    Text = "Rasanya tidak enak dibangkitkan kembali setelah dicekik. Sekarang, aku selalu merasa ada batu yang tersangkut di tenggorokan."
  },
  AvgDialog_58327_Content_50 = {
    Text = "Heh. Bukan novel misteri, apakah itu keberuntunganmu?"
  },
  AvgDialog_58327_Content_51 = {
    Text = "Mungkin saja. Coba tebak, kenapa begitu kebetulan aku menemukan petunjuk-petunjuk ini? Apakah mereka benar-benar bisa berjalan?"
  },
  AvgDialog_58327_Content_52 = {
    Text = "Ketika orang melihat seorang matematikawan memecahkan soal, mereka selalu takjub akan kejeniusannya. Namun, yang disebut jenius hanyalah seseorang yang satu langkah lebih cepat daripada orang biasa."
  },
  AvgDialog_58327_Content_53 = {
    Text = "Ryker tertawa terbahak-bahak, lalu mengarahkan pose kemenangan ke arah kejauhan yang tak terlihat."
  },
  AvgDialog_58327_Content_54 = {
    Text = "Aku rasa kamu juga sama seperti aku, kan?"
  },
  AvgDialog_58327_Content_55 = {
    Text = "Tidak ada yang menanggapi tindakan detektif yang terkesan kekanak-kanakan. Angin berhembus, daun-daun mengeluarkan suara gemerisik yang lembut, dan langit perlahan-lahan mulai gelap."
  },
  AvgDialog_58327_Content_56 = {
    Text = "Benar-benar membosankan. Sepertinya akan segera turun hujan, ayo pergi."
  },
  AvgDialog_58327_Content_57 = {
    Text = "Kamu dan Ryker berjalan bergantian di antara makam, langkah kaki menginjak daun-daun kering yang menghasilkan suara gemeretak kecil. Tidak ada yang berbicara."
  },
  AvgDialog_58327_Content_58 = {
    Text = "Ngomong-ngomong… kita sudah bersama melewati begitu banyak hal. Sesuai dengan perkembangan dalam novel, bukankah seharusnya kamu menceritakan sedikit tentang masa lalumu kepadaku?"
  },
  AvgDialog_58327_Content_59 = {
    Text = "Misalnya, dari mana kampung halamanmu? Bagaimana bisa terjerumus dan akhirnya kecanduan berjudi…"
  },
  AvgDialog_58327_Content_6 = {
    Text = "Hiks hiks hiks..."
  },
  AvgDialog_58327_Content_60 = {Text = "Hei……"},
  AvgDialog_58327_Content_61 = {
    Text = "Sayang sekali, masa laluku sama biasa seperti kasus itu. Jika aku menceritakannya, mungkin akan merusak kesan misteriusku di matamu."
  },
  AvgDialog_58327_Content_62 = {
    Text = "Haha, pemahaman dirimu masih begitu kacau. Lihat, ini juga selalu menjadi hal yang membuatku penasaran."
  },
  AvgDialog_58327_Content_63 = {
    Text = "Benar-benar tak ada cara lain. Jika kamu bersikeras, kita bisa pergi ke kafe dan berbicara pelan-pelan…"
  },
  AvgDialog_58327_Content_64 = {
    Text = "Tawa perlahan memudar, dan pemakaman kembali ke keheningan."
  },
  AvgDialog_58327_Content_65 = {
    Text = "Di udara melayang partikel-partikel hitam yang samar, seolah-olah telah tersembunyi di dunia sejak jutaan tahun yang lalu dalam bentuk partikel tak kasat mata."
  },
  AvgDialog_58327_Content_66 = {
    Text = "Kabut mengamati kepergian detektif dan Penjaga dengan pandangan, lalu meregangkan diri dengan senang sesaat, sebelum akhirnya dengan berat hati surut dan menghilang."
  },
  AvgDialog_58327_Content_67 = {
    Text = "Seolah-olah itu tak pernah ada."
  },
  AvgDialog_58327_Content_7 = {
    Text = "Setelah Dexter selesai berbicara, dia batuk beberapa kali dengan cara yang berlebihan."
  },
  AvgDialog_58327_Content_8 = {
    Text = "Sepertinya sudah tidak ada masalah besar. Kalau begitu, mari bicara tentang hal yang serius: apa maksud dari peti mati yang diletakkan di rumahmu?"
  },
  AvgDialog_58327_Content_9 = {
    Text = "Jika saya tidak salah, itu adalah milik Firaun terakhir dari Leremvasi —— Karnak."
  },
  AvgDialog_58328_Content_1 = {
    Text = "Tuan Minggu Depan"
  },
  AvgDialog_58328_Content_10 = {
    Text = "Karena dia adalah \"Detektif Keberuntungan\" yang terkenal di wilayah timur."
  },
  AvgDialog_58328_Content_11 = {
    Text = "Selama dia terlibat dalam sebuah kasus, petunjuk akan segera muncul seperti memiliki kaki sendiri, dan pelaku pasti tidak bisa lolos lebih dari tiga hari!"
  },
  AvgDialog_58328_Content_12 = {
    Text = "Ada yang mengatakan bahwa dengan mengikuti Tuan Ryker selama satu hari saja, mereka bisa mendapatkan sepuluh Taring. Intinya, dia adalah dewa keberuntungan bagi semua orang."
  },
  AvgDialog_58328_Content_13 = {
    Text = "Hanya saja, keberuntungannya tidak lagi berguna di sini..."
  },
  AvgDialog_58328_Content_14 = {
    Text = "Apakah kasus ini mirip dengan salah satu kasus yang pernah ditangani oleh Tuan Ryker?"
  },
  AvgDialog_58328_Content_15 = {
    Text = "Ya. Meskipun Tuan Ryker tidak mengatakannya, dia sebenarnya sangat memperhatikan kasus itu."
  },
  AvgDialog_58328_Content_16 = {
    Text = "Perlu diingat, dia dulu memiliki julukan: <Blue:Tuan Senin Depan>."
  },
  AvgDialog_58328_Content_17 = {
    Text = "Senin depan, Tuan...?"
  },
  AvgDialog_58328_Content_18 = {
    Text = "Hanna membersihkan tenggorokannya dan mulai berbicara dengan suara yang sedikit dibuat-buat."
  },
  AvgDialog_58328_Content_19 = {
    Text = "\"Ryker, kapan kamu akan membayar utang judi?\" \"Senin depan!\""
  },
  AvgDialog_58328_Content_2 = {
    Text = [[
Kediaman Frande - Luar Rumah
Waktu tersisa hingga kasus selesai: <Red:60> menit]]
  },
  AvgDialog_58328_Content_20 = {
    Text = "\"Ryker, kapan kamu berencana mencari pekerjaan?\" \"Senin depan!\""
  },
  AvgDialog_58328_Content_21 = {
    Text = "\"Ryker, kapan kamu akan mati?\" \"Senin depan!\""
  },
  AvgDialog_58328_Content_22 = {
    Text = "Nah, begitulah. Pada saat itu, semua orang menertawakannya, anak-anak menirukan ekspresi hantu di belakangnya, pemilik bar langsung mengangkat kursi begitu melihatnya…"
  },
  AvgDialog_58328_Content_23 = {
    Text = "Intinya, tidak seorang pun menghormatinya."
  },
  AvgDialog_58328_Content_24 = {
    Text = "...sampai dia berhasil memecahkan kasus itu."
  },
  AvgDialog_58328_Content_25 = {
    Text = "Benar! Sepertinya hidupnya setelah itu telah diberi mantra, semua keberuntungan datang dengan sendirinya, dan semua orang semakin menyukainya."
  },
  AvgDialog_58328_Content_26 = {
    Text = "Aneh sekali. Apakah ada sihir seperti itu di dunia ini?"
  },
  AvgDialog_58328_Content_27 = {
    Text = "Siapa yang tahu, di dunia kita ini, apa pun bisa terjadi tanpa mengejutkan — eh, apa itu?"
  },
  AvgDialog_58328_Content_28 = {
    Text = "Di sudut dekat dinding di depan, sebuah sepatu kulit pria berwarna hitam tersembunyi setengah dalam salju lembut."
  },
  AvgDialog_58328_Content_29 = {
    Text = "Uwaa, ukiran yang sangat halus, tampaknya seperti sesuatu yang tak akan mampu kubeli seumur hidup..."
  },
  AvgDialog_58328_Content_3 = {
    Text = "Hatsji... Hatsji!"
  },
  AvgDialog_58328_Content_30 = {Text = "!!!"},
  AvgDialog_58328_Content_31 = {
    Text = "Sepatu kulit milik Tuan Dexter."
  },
  AvgDialog_58328_Content_32 = {
    Text = "Kamu menengadah ke atas. Dinding abu-abu dingin menjulang ke arah langit, dan cahaya kuning redup tampak seperti mercusuar yang melayang di dalamnya."
  },
  AvgDialog_58328_Content_33 = {
    Text = "Itu adalah kamar tidur Dexter."
  },
  AvgDialog_58328_Content_34 = {
    Text = "Kamu menundukkan kepala, ruang belajar berada tepat di depan. Melalui jendela berukir, bayangan Dexter yang tergantung diam-diam bertemu pandang denganmu."
  },
  AvgDialog_58328_Content_35 = {
    Text = "Dua kamar terletak pada satu garis vertikal."
  },
  AvgDialog_58328_Content_36 = {
    Text = "Hanna… aku tiba-tiba punya sebuah dugaan."
  },
  AvgDialog_58328_Content_37 = {
    Text = "Kamu langsung menyelipkan sepatu ke tangan Hannah."
  },
  AvgDialog_58328_Content_38 = {
    Text = "Ayo, kembali ke ruang belajar dan lihat."
  },
  AvgDialog_58328_Content_39 = {
    Text = [[
Ruang Kerja Lantai Satu, Kediaman Frande
Waktu tersisa hingga akhir kasus: <Red:30> menit]]
  },
  AvgDialog_58328_Content_4 = {
    Text = "Hanna membawa lampu minyak dan meringkuk menjadi bola kecil, bersandar di sisimu."
  },
  AvgDialog_58328_Content_40 = {
    Text = "Kamu memegang gagang pintu dan menariknya untuk membuka."
  },
  AvgDialog_58328_Content_41 = {
    Text = "Apa ini, kalian berdua tidak mungkin pergi keluar untuk berbelanja, kan?"
  },
  AvgDialog_58328_Content_42 = {
    Text = "Tuan Ryker?! Bukankah kamu..."
  },
  AvgDialog_58328_Content_43 = {
    Text = "Ya, aku baru saja sangat terpukul, lalu berlari ke sudut dan menangis dengan keras."
  },
  AvgDialog_58328_Content_44 = {
    Text = "Kamu melihat postur tubuhnya yang terlihat santai, lalu tiba-tiba menepuk pundaknya."
  },
  AvgDialog_58328_Content_45 = {
    Text = "Syukurlah kalau tidak apa-apa."
  },
  AvgDialog_58328_Content_46 = {
    Text = "Tsk. Ekspresi menjijikkan apa ini…"
  },
  AvgDialog_58328_Content_47 = {
    Text = "Baiklah, tidak ada waktu untuk bergumam! Tuan Ryker, kami baru saja menemukan sesuatu yang besar di lantai bawah!"
  },
  AvgDialog_58328_Content_48 = {
    Text = "Kalian menceritakan semua hasil pengamatan di lantai bawah kepada Ryker."
  },
  AvgDialog_58328_Content_49 = {
    Text = "...Begitu ya."
  },
  AvgDialog_58328_Content_5 = {
    Text = "Astaga, tidak ada jejak yang tersisa! Kita keluar terlalu terlambat."
  },
  AvgDialog_58328_Content_50 = {
    Text = "Ryker mendekati jendela ruang belajar. Sebuah jejak sepatu yang samar tercetak tipis di bingkai jendela putih."
  },
  AvgDialog_58328_Content_51 = {
    Text = "Dia mengeluarkan tubuhnya dan menatap ke atas."
  },
  AvgDialog_58328_Content_52 = {Text = "Ngh..."},
  AvgDialog_58328_Content_53 = {
    Text = "Jika saya tidak salah, kemungkinan besar sepatu lainnya berada di ruangan ini."
  },
  AvgDialog_58328_Content_54 = {Text = "?!"},
  AvgDialog_58328_Content_55 = {
    Text = "Namun, sebelum itu, ada satu hal yang ingin aku konfirmasi…"
  },
  AvgDialog_58328_Content_56 = {
    Text = "Detektif berjalan ke arah jasad Sorel, lalu dengan cermat mengamati bekas tembakan di dahinya selama beberapa saat."
  },
  AvgDialog_58328_Content_57 = {
    Text = "Tepiannya terdapat banyak jelaga dan bekas terbakar akibat serbuk mesiu — pelaku menembaknya dari jarak sangat dekat, tepat mengarah ke arahnya."
  },
  AvgDialog_58328_Content_58 = {
    Text = "Eh… ini menunjukkan apa lagi?"
  },
  AvgDialog_58328_Content_59 = {
    Text = "Detektif tiba-tiba tertawa terbahak-bahak. Sejak memasuki kediaman, ini adalah pertama kalinya dia tertawa begitu lepas."
  },
  AvgDialog_58328_Content_6 = {
    Text = "Rumah sudah hampir selesai disisir, sekarang hanya bisa keluar dan mencoba peruntungan."
  },
  AvgDialog_58328_Content_60 = {
    Text = "Menjelaskan semuanya. Ayo pergi, saatnya untuk pertunjukan deduksi."
  },
  AvgDialog_58328_Content_7 = {
    Text = "Ah... kalau saja Tuan Ryker ada di sini, dia pasti punya cara."
  },
  AvgDialog_58328_Content_8 = {
    Text = "Baru saja dia berkata ingin sendirian untuk menenangkan diri, lalu menghilang."
  },
  AvgDialog_58328_Content_9 = {
    Text = "Ngomong-ngomong, aku hanya tahu bahwa Tuan Ryker adalah seorang penjudi, tak disangka karier detektifnya ternyata cukup bagus…"
  },
  AvgDialog_58329_Content_1 = {
    Text = "Kebenaran satu macam"
  },
  AvgDialog_58329_Content_10 = {Text = "!!"},
  AvgDialog_58329_Content_11 = {
    Text = "Barusan kamu juga yang terburu-buru menyela aku untuk mengungkapkan kebenaran tentang kematian Sorel. Jangan bilang kamu benar-benar mengira aku akan menurunkan kewaspadaanku padamu hanya karena tampangmu ini?"
  },
  AvgDialog_58329_Content_12 = {
    Text = "<Red:Dear Mr. N?>"
  },
  AvgDialog_58329_Content_14 = {
    Text = "Darah berhenti mengalir. Mereka berubah menjadi kabut hitam pekat, menyelimuti \"kamu\" di dalamnya."
  },
  AvgDialog_58329_Content_15 = {
    Text = "Hingga akhirnya, siswa berambut keriting menghilang, dan seluruh kabut hitam masuk ke dalam tubuh N."
  },
  AvgDialog_58329_Content_16 = {
    Text = "Sepertinya kamu juga menikmati aktingmu, teman lama."
  },
  AvgDialog_58329_Content_17 = {
    Text = "Hanya sedikit inspirasi yang kuperoleh dari dirimu, kita saling mempengaruhi."
  },
  AvgDialog_58329_Content_18 = {
    Text = "Menarik... sangat menarik. Bagaimana kamu bisa mengetahuinya?"
  },
  AvgDialog_58329_Content_19 = {
    Text = "Bukankah kamu sudah mengatakannya di awal: jangan percaya siapa pun. Aku tidak punya kebiasaan buruk lainnya, tapi sifat curiga ini sudah melekat seumur hidup dan takkan bisa diubah."
  },
  AvgDialog_58329_Content_2 = {
    Text = "Tidak... mengapa..."
  },
  AvgDialog_58329_Content_20 = {
    Text = "Keraguan pertama kali muncul saat melihat jenazah Sorel. Dia tertembak di bagian depan, dan tidak ada luka lain di tubuhnya."
  },
  AvgDialog_58329_Content_21 = {
    Text = "Bekas peluru di dahi dipenuhi dengan jelaga tebal dan bekas terbakar akibat bubuk mesiu, yang menunjukkan dua hal."
  },
  AvgDialog_58329_Content_22 = {
    Text = "Pertama: Pembunuh menembak dari jarak yang sangat dekat dengan korban."
  },
  AvgDialog_58329_Content_23 = {
    Text = "Lalu yang kedua?"
  },
  AvgDialog_58329_Content_24 = {
    Text = "Menunjukkan bahwa pelaku adalah seseorang yang sangat dipercaya oleh korban dan tidak membuat korban waspada. Orang yang paling sesuai dengan kriteria ini di tempat kejadian hanya bisa menjadi %player%."
  },
  AvgDialog_58329_Content_25 = {
    Text = "Alasan kamu terburu-buru membunuhnya adalah karena aku mengetahui rahasia piringan hitam itu."
  },
  AvgDialog_58329_Content_26 = {
    Text = "Dan kamu tidak ingin permainan berakhir terlalu cepat. Apakah saya benar?"
  },
  AvgDialog_58329_Content_27 = {
    Text = "N mengangkat bahu dengan santai."
  },
  AvgDialog_58329_Content_28 = {
    Text = "Hanya karena beberapa dugaan yang tidak berdasar, kau sudah tega menembak Penjaga? Pantas saja kau adalah penjudi pilihan saya."
  },
  AvgDialog_58329_Content_29 = {
    Text = "Jika saya adalah Penjaga %player%{Male=tuan,Female=nyonya}, saat ini saya akan menangis karena kejamnya sikapmu yang dingin."
  },
  AvgDialog_58329_Content_3 = {
    Text = "Kamu jatuh berlutut. Rasa nyeri samar terus muncul di dada, dan darah berwarna merah gelap membasahi seragam luar."
  },
  AvgDialog_58329_Content_30 = {
    Text = "Hehe, aku tidak mungkin bercanda dengan nyawa %hisorher%. Alasan satu-satunya aku berani menembakmu hanyalah satu hal saja…"
  },
  AvgDialog_58329_Content_31 = {
    Text = "<Yellow:Saya sudah tahu sejak lama di mana {Male=dia,Female=dia} berada.>"
  },
  AvgDialog_58329_Content_32 = {Text = "?!"},
  AvgDialog_58329_Content_33 = {
    Text = "Tepat satu jam yang lalu."
  },
  AvgDialog_58329_Content_34 = {
    Text = [[
Rumah Frandel, Peti
Satu jam yang lalu]]
  },
  AvgDialog_58329_Content_35 = {
    Text = "Sebuah kekacauan yang asli dan penuh kehangatan."
  },
  AvgDialog_58329_Content_36 = {
    Text = "Kamu menutup kedua matamu dan menenggelamkan kesadaranmu ke tingkat paling rendah, bahkan hingga ke dasar."
  },
  AvgDialog_58329_Content_37 = {
    Text = "Hingga akhirnya, \"kamu\" tiba di bawah tembok tinggi itu."
  },
  AvgDialog_58329_Content_38 = {
    Text = "Inilah <Yellow:Dinding Kebenaran>. Itu ditutupi oleh tirai yang terlihat di depan matamu, dan hanya akan terbuka sedikit selama ritual yang berlangsung beberapa tahun sekali."
  },
  AvgDialog_58329_Content_39 = {
    Text = "Itu menyegel masa lalu, mencatat masa kini, dan meramalkan masa depan."
  },
  AvgDialog_58329_Content_4 = {
    Text = "Kamu bodoh... apa yang kau katakan..."
  },
  AvgDialog_58329_Content_40 = {
    Text = "Pendeta berbicara, dengan hormat berlutut di hadapanmu."
  },
  AvgDialog_58329_Content_41 = {
    Text = "Termasuk kedatanganmu, Kanak."
  },
  AvgDialog_58329_Content_42 = {
    Text = "Hujan mulai turun dari langit."
  },
  AvgDialog_58329_Content_43 = {
    Text = "Kamu jatuh berlutut di hadapan gulungan lukisan yang luas, mengeluarkan erangan seperti makhluk yang terbebas dari jeratan. Hujan mengalir melewati alismu, matamu, dan juga bercampur dengan air matamu."
  },
  AvgDialog_58329_Content_44 = {
    Text = "Ribuan tahun berlalu, akhirnya kamu menjadi Firaun Lemwasi."
  },
  AvgDialog_58329_Content_45 = {
    Text = "Kamu telah menunggu nasibmu sendiri."
  },
  AvgDialog_58329_Content_46 = {
    Text = "Kemudian..."
  },
  AvgDialog_58329_Content_47 = {
    Text = "Minggir. Aku akan merobek tirai sialan itu menjadi berkeping-keping!"
  },
  AvgDialog_58329_Content_48 = {
    Text = "Anak terhormat dari Amon, Anda tidak seharusnya berada di sini. Barang siapa yang melanggar hukum dari Dinding Kebenaran, malaikat maut akan membentangkan sayapnya dan Kedatangan-nya akan turun di atas kepalanya."
  },
  AvgDialog_58329_Content_49 = {
    Text = "Haha. Pertama-tama wabah, kelaparan, dan sekarang pasukan Apophis berada di luar kota. Buka matamu dan lihatlah dunia luar, wahai Pendeta buta — sang Dewa Kematian sudah Kedatangan."
  },
  AvgDialog_58329_Content_5 = {
    Text = "Ryker memeriksa pistol buatan tangan dengan saksama, lalu santai meniupkan napas ke arah moncong senjata."
  },
  AvgDialog_58329_Content_50 = {
    Text = "Saya dengan tulus mengikuti petunjuk dari dinding ini, namun justru mendatangkan malapetaka bagi masyarakat yang telah hidup selama berabad-abad di sepanjang sungai. Inilah konsekuensi dari ketaatan buta."
  },
  AvgDialog_58329_Content_51 = {
    Text = "Bersabarlah, Tuan Muda Lemwasi. Apa yang telah dilakukan adalah urusan kehidupan selanjutnya, dan apa yang akan dilakukan adalah urusan keabadian. Kehidupan selanjutnya hanyalah siang hari, sedangkan keabadian adalah malam."
  },
  AvgDialog_58329_Content_52 = {
    Text = "Dinding Kebenaran membawa baik madu dan papyrus, serta ular berbisa dan wabah."
  },
  AvgDialog_58329_Content_53 = {
    Text = "Hanya dengan menjalankan kehendak-Nya, setelah kematian jiwa kita dapat dengan damai melewati sungai malam, dan di tepi yang jauh berubah menjadi abadi——"
  },
  AvgDialog_58329_Content_54 = {
    Text = "Aku tidak peduli dengan \"keabadian\" yang kalian, kaum vampir pembohong, bicarakan. Aku hanya melihat tanah yang susah payah kurebut hilang dalam semalam, dan rakyatku sedang mati satu per satu."
  },
  AvgDialog_58329_Content_55 = {
    Text = "Bahkan anak buah terpercaya saya, <Blue:Apophis>, juga menghunus pedangnya melawan saya. Sekarang dia berdiri di luar, menunggu untuk memenggal kepala saya dan menggantungnya di dinding yang tinggi."
  },
  AvgDialog_58329_Content_56 = {
    Text = "Aku sudah kehilangan segalanya, Pendeta. Jika ini adalah takdir yang ditetapkan oleh Dinding Kebenaran atas nasib tragis saya, maka saya akan melihatnya dengan mata terbuka lebar, menyaksikan kematiannya."
  },
  AvgDialog_58329_Content_57 = {
    Text = "Setelah berkata, \"kamu\" mendorong Pendeta yang sudah tua dan dengan cepat menarik tirai penutup."
  },
  AvgDialog_58329_Content_58 = {
    Text = "Sejak itu, kebenaran dunia perlahan-lahan terbuka di hadapan \"kamu\"."
  },
  AvgDialog_58329_Content_59 = {
    Text = "Satu, dua..."
  },
  AvgDialog_58329_Content_6 = {
    Text = "Melihatmu dalam keadaan kacau, dia menyeringai dengan senyuman yang penuh niat jahat."
  },
  AvgDialog_58329_Content_60 = {
    Text = "Ribuan wajah tersenyum yang digambar dengan canggung menggunakan cat bata merah, menyeringai mencolok dengan mulut besar berdarah, bersama-sama menertawakan keputusasaan \"kamu\"."
  },
  AvgDialog_58329_Content_61 = {
    Text = "Begitu ya, jadi ini yang disebut kebenaran. Hehe… Hahahaha…"
  },
  AvgDialog_58329_Content_62 = {
    Text = "Tidak masuk akal. Merendahkan. Inilah kebenaran dunia."
  },
  AvgDialog_58329_Content_63 = {Text = "!!!"},
  AvgDialog_58329_Content_64 = {
    Text = "Detik berikutnya, gulungan lukisan di depan mata menghilang, dan kegelapan kembali."
  },
  AvgDialog_58329_Content_65 = {
    Text = "Tidak ada gurun, tidak ada pendeta dan gulungan lukisan. Kamu berbaring sendirian di dalam peti mati yang gelap gulita."
  },
  AvgDialog_58329_Content_66 = {
    Text = "Pikiranmu tampaknya masih terjebak dalam kenangan Kanak, kesedihan tanpa akhir menyelimuti dirimu."
  },
  AvgDialog_58329_Content_67 = {
    Text = "Air mata tak terbendung lagi, seperti tirai hujan yang tak ada habisnya."
  },
  AvgDialog_58329_Content_68 = {
    Text = "<Tidak>…aku…"
  },
  AvgDialog_58329_Content_69 = {
    Text = "<Change>Aku hanya ingin tetap hidup..."
  },
  AvgDialog_58329_Content_7 = {
    Text = "Alasan aku tidak menghentikanmu untuk mengirim Hannah pergi adalah karena aku khawatir dia tidak bisa menanggung kebenaran ini. Lagipula, dia hanyalah seorang siswa biasa."
  },
  AvgDialog_58329_Content_70 = {
    Text = "Dong. Dong dong."
  },
  AvgDialog_58329_Content_71 = {
    Text = "Suara ketukan terdengar dari kejauhan, mengganggu ritme abadi lautan yang penuh kesedihan ini. Kemudian, kamu mendengar suara yang familiar—"
  },
  AvgDialog_58329_Content_72 = {
    Text = "Hei, teman di dalam peti mati, apakah kamu baik-baik saja?"
  },
  AvgDialog_58329_Content_8 = {
    Text = "Dan kamu, teman saya ——"
  },
  AvgDialog_58329_Content_9 = {
    Text = "Aku sudah tahu, kau pasti tidak bisa menahan dorongan untuk berakting. Hei, apakah berakting menyenangkan?"
  },
  AvgDialog_58330_Content_1 = {
    Text = "Pertunjukan Tragedi"
  },
  AvgDialog_58330_Content_10 = {
    Text = "Mengenai hal ini, saya memiliki pendapat yang berbeda, namun mari kita lewati saja. Lalu, apa yang terjadi setelah Tuan Dexter keluar?"
  },
  AvgDialog_58330_Content_100 = {
    Text = "Karena kamu belum menemukan pelaku sebenarnya yang membunuh Nyonya Sorel. Semua penalaranmu sengaja menghindari kematiannya, bukan?"
  },
  AvgDialog_58330_Content_101 = {
    Text = "Apa yang kamu takuti?"
  },
  AvgDialog_58330_Content_103 = {
    Text = "Sangat disayangkan kamu kehilangan seorang teman lagi. Mungkin, keberuntungan di dunia ini memang selalu tetap."
  },
  AvgDialog_58330_Content_104 = {
    Text = "Kamu mendapatkan keberuntungan, hidupmu semakin membaik, namun ada orang lain yang malah mengalami nasib buruk karenanya."
  },
  AvgDialog_58330_Content_105 = {
    Text = "Hukum yang tak terlihat menggantung di atas kepala orang-orang. Apakah kamu benar-benar bisa menerimanya dengan tenang?"
  },
  AvgDialog_58330_Content_106 = {
    Text = "Haha... aturan macam apa ini, hanya permainan kecilmu sendiri."
  },
  AvgDialog_58330_Content_107 = {
    Text = "Kebencianmu terhadapku masih datang dengan begitu tulus dan menggemaskan, membuatku hanya bisa menghela napas."
  },
  AvgDialog_58330_Content_108 = {
    Text = "Meskipun kalian belum bisa memecahkan semua teka-teki, aku selalu bersikap pemaaf…"
  },
  AvgDialog_58330_Content_109 = {
    Text = "N mengangkat jarinya dengan lembut, kabut hitam pekat tiba-tiba menyelimuti dirimu dan mengikatmu erat."
  },
  AvgDialog_58330_Content_11 = {Text = "……!!"},
  AvgDialog_58330_Content_110 = {
    Text = "Tidak... uh!"
  },
  AvgDialog_58330_Content_111 = {Text = "!!"},
  AvgDialog_58330_Content_112 = {
    Text = "Tuan N, saya tahu tindakan saya di Alan telah membuatmu marah, dan sekarang saya dengan sungguh-sungguh meminta maaf kepadamu."
  },
  AvgDialog_58330_Content_113 = {
    Text = "Kamu bisa menghukumku sesukamu, tidak perlu melibatkan {Male=dia,Female=dia}."
  },
  AvgDialog_58330_Content_114 = {
    Text = "Detektif yang tergesa-gesa, dengarkan aku sampai selesai. Aku telah menyiapkan satu pertanyaan terakhir untukmu."
  },
  AvgDialog_58330_Content_115 = {
    Text = "...Baik, aku mendengarkan."
  },
  AvgDialog_58330_Content_116 = {
    Text = "Pilihan yang sangat sederhana: <Red:Membunuh %player%, maka aku akan menghidupkan kembali semua orang yang sebelumnya telah meninggal.>"
  },
  AvgDialog_58330_Content_117 = {
    Text = "Semuanya akan kembali seperti semula, kecuali orang sialan di sebelahmu ini. Tidak ada seorang pun yang menerima kerusakan."
  },
  AvgDialog_58330_Content_118 = {
    Text = "Atau kamu juga bisa memilih untuk tidak membunuh %player%, kalian berdua bisa meninggalkan Domain dengan selamat."
  },
  AvgDialog_58330_Content_119 = {
    Text = "Bagaimana, apakah sangat mudah?"
  },
  AvgDialog_58330_Content_12 = {
    Text = "Masih ingat hantu yang kulihat di tangga sebelumnya? Melayang di udara, hantu, gantung diri... Apakah mungkin..."
  },
  AvgDialog_58330_Content_120 = {Text = "?!"},
  AvgDialog_58330_Content_122 = {
    Text = "Apakah pistolmu masih ada di tubuhmu? Sekarang mulai hitung mundur. 10."
  },
  AvgDialog_58330_Content_123 = {
    Text = "Tidak, kamu tidak bisa…"
  },
  AvgDialog_58330_Content_124 = {Text = "9"},
  AvgDialog_58330_Content_125 = {
    Text = "Ryker menatapmu dengan sedikit bingung, seperti seorang anak yang telah melakukan kesalahan."
  },
  AvgDialog_58330_Content_126 = {
    Text = "Jangan pedulikan aku, batuk-batuk… Siapa tahu setelah aku mati, Mythag akan membuatku menjadi Pembangun."
  },
  AvgDialog_58330_Content_127 = {
    Text = "Kamu mencoba sekuat tenaga untuk menggerakkan semua otot di wajahmu, lalu memberikan senyuman yang dipaksakan kepada Ryker."
  },
  AvgDialog_58330_Content_128 = {Text = "... Ayo."},
  AvgDialog_58330_Content_129 = {Text = "6"},
  AvgDialog_58330_Content_13 = {
    Text = "Benar. Kebenarannya adalah: seseorang terlebih dahulu menarik perhatian Tuan Dexter, dan pada saat dia menjulurkan kepalanya, tali dilemparkan ke lehernya, lalu ditarik dengan keras ke atas——"
  },
  AvgDialog_58330_Content_130 = {
    Text = "Ryker perlahan berjalan ke arahmu, matanya tenang tanpa riak."
  },
  AvgDialog_58330_Content_131 = {
    Text = "Penglihatanmu mulai kabur, kamu menatap matanya, dan banyak kenangan tentang momen-momen yang kalian habiskan bersama muncul di benakmu."
  },
  AvgDialog_58330_Content_132 = {
    Text = "Ada yang saling mengejar dan bermain-main di padang pasir, ada yang bersama-sama melarikan diri dari perkumpulan ■■ orang Arlan, dan ada pula saat dia mempertaruhkan nyawanya untuk melukai Kassia parah…"
  },
  AvgDialog_58330_Content_133 = {
    Text = "Ada terlalu banyak kenangan di antara kalian."
  },
  AvgDialog_58330_Content_134 = {
    Text = "Tanpa terasa, Ryker sudah berdiri di depanmu. Kamu tidak bisa melihat wajahnya dengan jelas, tapi kamu tahu bahwa penderitaannya saat ini tidak kalah berat dibandingkan dengan milikmu."
  },
  AvgDialog_58330_Content_135 = {
    Text = "Detik berikutnya, dia mengangkat pistolnya."
  },
  AvgDialog_58330_Content_136 = {
    Text = "Tahukah kamu… aku tak pernah meragukanmu. Jadi——"
  },
  AvgDialog_58330_Content_137 = {
    Text = "Tembakan terdengar, tepat mengenai jantungmu, tidak meleset sedikit pun."
  },
  AvgDialog_58330_Content_138 = {
    Text = "A-apa……?"
  },
  AvgDialog_58330_Content_139 = {
    Text = "Ryker berdiri di hadapanmu dengan sikap angkuh, sudut bibirnya menyunggingkan senyuman penuh ejekan."
  },
  AvgDialog_58330_Content_14 = {
    Text = "Ryker mengangkat wajahnya dan menunjuk ke arah kamar tidur di lantai dua."
  },
  AvgDialog_58330_Content_140 = {
    Text = "Aku sudah menantikan saat ini untuk waktu yang lama, Penjaga."
  },
  AvgDialog_58330_Content_15 = {
    Text = "<Yellow:Pembunuh saat itu berada di kamar tidur Tuan Dexter.> Kedua ruangan ini kebetulan berada dalam satu garis lurus."
  },
  AvgDialog_58330_Content_16 = {
    Text = "Hebat! Dengan ini, kita bisa menjelaskan Acara hantu dan juga jejak kaki di bingkai jendela. Itu terjadi karena Mr. Dexter berusaha keras melawan saat ia diikat dengan tali."
  },
  AvgDialog_58330_Content_17 = {
    Text = "Namun, ini membutuhkan kekuatan lengan yang besar serta prediksi akurat terhadap sudut. Semua orang di sini telah disegel kemampuannya, bagaimana mungkin…"
  },
  AvgDialog_58330_Content_18 = {
    Text = "Hanna tiba-tiba berhenti di tengah kalimat, ada dugaan samar di dalam hatinya."
  },
  AvgDialog_58330_Content_19 = {
    Text = "Tapi… setelah Acara hantu, kami segera naik ke kamar tidur, dan selama waktu itu tidak ada suara lain yang terdengar. Pembunuh seharusnya masih berada di dalam kamar tidur."
  },
  AvgDialog_58330_Content_2 = {
    Text = "Hatsji... Hatsji!"
  },
  AvgDialog_58330_Content_20 = {
    Text = "Selain pemutar piringan hitam itu, tidak ada tempat lain yang terlihat mencurigakan... Hatsyoo, hatsyoo!"
  },
  AvgDialog_58330_Content_21 = {
    Text = "Hanna dengan cepat menyeka dua aliran ingus yang berkilauan."
  },
  AvgDialog_58330_Content_22 = {
    Text = "Ayah surgawi, bagaimana bisa terserang flu di dalam Domain!"
  },
  AvgDialog_58330_Content_24 = {
    Text = "Bagian tentang luar sudah dibahas dengan jelas. Kalau begitu, ayo segera masuk saja…"
  },
  AvgDialog_58330_Content_25 = {
    Text = "Coba ingat kembali dengan cermat, apa yang terjadi setelah kita menendang pintu masuk."
  },
  AvgDialog_58330_Content_26 = {
    Text = "Apa yang terjadi..."
  },
  AvgDialog_58330_Content_27 = {
    Text = "Maaf, aku sekarang merasa tidak enak badan. Bolehkah aku beristirahat sebentar?"
  },
  AvgDialog_58330_Content_28 = {
    Text = "Maaf, @2 tidak terlalu nyaman... istirahat..."
  },
  AvgDialog_58330_Content_29 = {
    Text = "Istirahat sejenak @2 kali……"
  },
  AvgDialog_58330_Content_3 = {
    Text = "Efek pendinginan di Domain ini sangat luar biasa. Bos, apakah kita tidak bisa melakukan deduksi di sekitar perapian di dalam ruangan?"
  },
  AvgDialog_58330_Content_30 = {
    Text = "Harap semua orang segera pergi, jangan mengganggu waktu istirahat Tuan Dexter."
  },
  AvgDialog_58330_Content_31 = {
    Text = "<Shake:Wahhh!! Kamu dari kapan…>"
  },
  AvgDialog_58330_Content_32 = {
    Text = "Ternyata memang begitu……"
  },
  AvgDialog_58330_Content_33 = {
    Text = "Hanna tiba-tiba mengangkat kepalanya dan langsung menatap Erica yang berdiri di belakang kerumunan."
  },
  AvgDialog_58330_Content_34 = {
    Text = "Kamu tidak muncul belakangan. Kamu sudah ada di dalam ruangan sepanjang waktu… mungkin bersembunyi di balik pintu, setelah perhatian kita semua teralihkan oleh pemain piringan hitam…"
  },
  AvgDialog_58330_Content_35 = {
    Text = "Ditolak. Erica tidak memiliki kemampuan untuk membelah diri, sehingga tidak bisa menjelaskan mengapa korban ditemukan di ruang belajar."
  },
  AvgDialog_58330_Content_36 = {
    Text = "Ya, kamu tidak memiliki kemampuan untuk membelah diri. Jadi, kamu masih punya seorang asisten."
  },
  AvgDialog_58330_Content_37 = {Text = "!!"},
  AvgDialog_58330_Content_38 = {
    Text = "Mencekik seorang pria dewasa di udara dengan lengan mekanis yang dapat diperpanjang adalah hal yang sangat mudah bagi Nona Erica."
  },
  AvgDialog_58330_Content_39 = {
    Text = "Sama seperti ketika kamu sebelumnya mengulurkan tangan untuk memotong jembatan kayu."
  },
  AvgDialog_58330_Content_4 = {
    Text = "Tenang, tidak akan memakan banyak waktu."
  },
  AvgDialog_58330_Content_40 = {
    Text = "Setelah Tuan Dexter menghembuskan napas terakhir, kamu bisa melemparkannya ke bawah, dan pembantu yang sudah menunggu lama akan membantumu menyeret mayatnya ke dalam ruang belajar."
  },
  AvgDialog_58330_Content_41 = {
    Text = "Ini juga menjelaskan mengapa ada dua bekas jerat pada mayat, serta rasa lembap pada pakaiannya—karena mayat itu pernah diseret di atas salju."
  },
  AvgDialog_58330_Content_42 = {
    Text = "Jadi, satu-satunya orang yang mungkin menjadi pembantu adalah orang yang tidak memiliki alibi dari saat tembakan terdengar hingga setelah kejadian…"
  },
  AvgDialog_58330_Content_43 = {
    Text = "Ryker berbicara sambil memandang lemari di sudut ruang belajar."
  },
  AvgDialog_58330_Content_44 = {
    Text = "Nyonya Sorel."
  },
  AvgDialog_58330_Content_45 = {
    Text = "Ternyata begitu. Aku hanya menebak bahwa Tuan Dexter dicekik di udara, tapi sama sekali tidak menduga ada seorang kaki tangan."
  },
  AvgDialog_58330_Content_46 = {
    Text = "Ditolak. Semua penalaran di atas hanyalah spekulasi, tanpa dukungan bukti nyata."
  },
  AvgDialog_58330_Content_47 = {
    Text = "Mau bukti? Itu sangat mudah."
  },
  AvgDialog_58330_Content_48 = {
    Text = "Apakah kamu masih ingat pola dua bekas cekikan di leher mayat itu?"
  },
  AvgDialog_58330_Content_49 = {
    Text = "Dua bekas tali memiliki pola yang tidak konsisten. Di bagian dalam terdapat struktur berbentuk belah ketupat yang rapi, sedangkan di bagian luar lebih kasar…"
  },
  AvgDialog_58330_Content_5 = {
    Text = "Pertama-tama, sepatu yang terjatuh di luar. Pertanyaan: Dalam situasi apa sepatu bisa berada di luar?"
  },
  AvgDialog_58330_Content_50 = {
    Text = "Mungkin tali putus di tengah jalan, atau mungkin terkena darah, sehingga pelaku mengganti tali tersebut dengan yang baru."
  },
  AvgDialog_58330_Content_51 = {Text = "!!"},
  AvgDialog_58330_Content_52 = {
    Text = "Berbentuk belah ketupat yang rapi. Nona Erica, tolong panjangkan lengan mekanikmu untuk diperlihatkan kepada semua orang, lihatlah pola Tautan yang bisa ditarik di dalamnya."
  },
  AvgDialog_58330_Content_54 = {
    Text = "Menggunakan tali untuk secara tepat melilit leher seorang pria dewasa yang waspada di lantai dua, bagaimana pun dipikirkan, tampaknya seperti tugas yang hampir mustahil untuk dilakukan."
  },
  AvgDialog_58330_Content_55 = {
    Text = "Tetapi jika tali itu sebenarnya adalah bagian dari tubuhmu, maka semuanya bisa dijelaskan."
  },
  AvgDialog_58330_Content_56 = {
    Text = "Ternyata benar kamu, Nona Erica…"
  },
  AvgDialog_58330_Content_57 = {
    Text = "Erica perlahan memanjangkan lengan kanannya. Di bawah sorotan lampu, Tautan antara lengan bawah dan tangannya memancarkan cahaya dingin yang mengerikan."
  },
  AvgDialog_58330_Content_58 = {
    Text = "Pola berbentuk belah ketupat tersusun rapi, seolah-olah sisik ikan di kedalaman Aequor."
  },
  AvgDialog_58330_Content_59 = {
    Text = "Ternyata... benar-benar sama..."
  },
  AvgDialog_58330_Content_6 = {
    Text = "Hmm... orang mati keluar, lalu mengalami kecelakaan?"
  },
  AvgDialog_58330_Content_60 = {
    Text = "Erica tidak memberikan tanggapan. Kabut hitam perlahan keluar dari tubuhnya, memudarkan sosok lain yang sudah tidak asing lagi."
  },
  AvgDialog_58330_Content_61 = {
    Text = "Penalaran yang bagus!"
  },
  AvgDialog_58330_Content_62 = {
    Text = "Ternyata, Miss Erica yang dimaksud adalah alter egomu… Ini berarti di dunia nyata, Miss Erica selamat!"
  },
  AvgDialog_58330_Content_63 = {
    Text = "Kalian tidak akan mengerti kesenangan dari bermain peran, hihi."
  },
  AvgDialog_58330_Content_64 = {
    Text = "Apakah penjelasan yang baru saja kalian berikan adalah jawaban akhir kalian?"
  },
  AvgDialog_58330_Content_65 = {Text = "...Ya."},
  AvgDialog_58330_Content_67 = {
    Text = "Haha... kalau begitu, sangat disayangkan. Masih ada satu langkah lagi."
  },
  AvgDialog_58330_Content_68 = {
    Text = "Ini bukanlah kebenaran terakhir, jadi——"
  },
  AvgDialog_58330_Content_69 = {
    Text = "N menjentikkan jarinya, dan tubuh Hannah segera mengeluarkan gulungan kabut hitam yang menyebar di dalam ruang belajar."
  },
  AvgDialog_58330_Content_7 = {
    Text = "Memang, ini adalah salah satu kemungkinan. Setelah melakukan perbandingan, kami menemukan bahwa pola sol sepatu ini sepenuhnya cocok dengan jejak kaki yang tertinggal di bingkai jendela."
  },
  AvgDialog_58330_Content_70 = {
    Text = "Dia dengan panik mencengkeram jaket Ryker."
  },
  AvgDialog_58330_Content_71 = {
    Text = "Bagaimana mungkin, Bukankah Erica juga tidak membantahnya?!"
  },
  AvgDialog_58330_Content_73 = {
    Text = "Hei hei hei, teman Penjaga-mu terlalu terburu-buru, lain kali ingatlah untuk berbicara sebelum {Male=dia,Female=dia} ya~"
  },
  AvgDialog_58330_Content_74 = {
    Text = "Maaf, Hanna. Aku..."
  },
  AvgDialog_58330_Content_75 = {
    Text = "Tolong aku…! Aku belum mendengar kebenaran terakhir, jangan…"
  },
  AvgDialog_58330_Content_76 = {
    Text = "Saat berikutnya, Hanna juga menghilang di hadapanmu."
  },
  AvgDialog_58330_Content_77 = {
    Text = "Hanna——!"
  },
  AvgDialog_58330_Content_78 = {
    Text = "Apa yang telah aku lakukan..."
  },
  AvgDialog_58330_Content_79 = {
    Text = "Tidak, ini semua salahku... aku terlalu gegabah."
  },
  AvgDialog_58330_Content_8 = {
    Text = "Mungkinkah Tuan Mulia Dexter, yang selalu menjunjung tinggi etika, akan keluar melalui jendela di rumahnya sendiri, apalagi saat kunci pintu masih utuh?"
  },
  AvgDialog_58330_Content_80 = {
    Text = "Hmm, sekarang hanya tersisa kita bertiga. Adapun yang lainnya, kemungkinan besar mereka sedang menderita di dunia nyata."
  },
  AvgDialog_58330_Content_81 = {
    Text = "Hihiihi, menarik, sangat menarik!"
  },
  AvgDialog_58330_Content_82 = {
    Text = "Ruang Medis Mythag\nSementara itu……"
  },
  AvgDialog_58330_Content_83 = {
    Text = "Bagaimana situasinya?"
  },
  AvgDialog_58330_Content_84 = {
    Text = "Kondisi Nyonya Hanna dan Penjaga juga mulai memburuk. Entah kenapa, organ dalam Nyonya Hanna mengalami keretakan di banyak tempat dan ada tanda-tanda berdarah di dalam tubuhnya."
  },
  AvgDialog_58330_Content_85 = {
    Text = "Penjaga juga mengalami gejala sesak napas yang parah. Jika terus dibiarkan seperti ini…"
  },
  AvgDialog_58330_Content_86 = {
    Text = "Kami telah mengunjungi banyak teman sekelas, dan rekan-rekan di departemen teknis juga sedang memeriksa semua fasilitas. Saat ini, tidak ada kelainan yang ditemukan."
  },
  AvgDialog_58330_Content_87 = {
    Text = "Bisa menimbulkan keributan sebesar ini tepat di depan mata semua orang..."
  },
  AvgDialog_58330_Content_88 = {Text = "...N."},
  AvgDialog_58330_Content_89 = {
    Text = "Ini adalah pandangan yang disepakati oleh saya dan Alistair. Jika itu tentang Dia, semuanya bisa dijelaskan."
  },
  AvgDialog_58330_Content_9 = {
    Text = "Dia melihat sesuatu di luar jendela, apakah dia buru-buru keluar?"
  },
  AvgDialog_58330_Content_90 = {
    Text = "Lalu apa yang harus kita lakukan? Kita sama sekali tidak memiliki tindakan balasan…"
  },
  AvgDialog_58330_Content_91 = {
    Text = "Boneka membelai kepala bulat di tangannya, lalu menghela napas pelan."
  },
  AvgDialog_58330_Content_92 = {
    Text = "Satu-satunya hal yang pasti adalah: Dia seharusnya belum terburu-buru untuk mengambil nyawa Penjaga."
  },
  AvgDialog_58330_Content_93 = {
    Text = "Adapun sisanya... Saran saya, berdoa bersama saya."
  },
  AvgDialog_58330_Content_94 = {
    Text = "Baiklah, semua orang yang tidak berkepentingan sudah pergi. Kita bisa saling terbuka sekarang."
  },
  AvgDialog_58330_Content_95 = {
    Text = "Dari tubuh N muncul kabut dingin yang menyelimuti wajah-Nya lapis demi lapis, hingga akhirnya sosok aslinya lenyap sepenuhnya."
  },
  AvgDialog_58330_Content_96 = {
    Text = "Tidak hanya itu, ruangan tempat kalian berada juga tiba-tiba menghilang, digantikan oleh gedung opera yang sudah familiar."
  },
  AvgDialog_58330_Content_97 = {
    Text = "Maaf, aku tidak terlalu suka dengan ruang yang sempit."
  },
  AvgDialog_58330_Content_98 = {
    Text = "Sudah lama tidak bertemu, teman-teman lamaku."
  },
  AvgDialog_58330_Content_99 = {
    Text = "Apa maksudmu tadi, ini bukan kebenaran terakhir...?"
  },
  AvgDialog_58331_Content_1 = {
    Text = "Sekarang, Apophis!"
  },
  AvgDialog_58331_Content_10 = {
    Text = "Ryker melangkah perlahan mendekati N."
  },
  AvgDialog_58331_Content_11 = {
    Text = "Tampaknya keberuntungan akhirnya berpihak kepada saya juga."
  },
  AvgDialog_58331_Content_12 = {
    Text = "Hati-hati, Tuan Detektif. Bagi seorang penjudi yang tak bisa diselamatkan, hal yang paling menakutkan dalam sebuah permainan bukanlah kalah, melainkan menang."
  },
  AvgDialog_58331_Content_13 = {
    Text = "Jika tidak percaya, cobalah tanyakan kepada pemilik ular hitam ini."
  },
  AvgDialog_58331_Content_14 = {
    Text = "Sepertinya kamu masih belum cukup memahamiku, namun ada satu hal yang kamu katakan dengan benar."
  },
  AvgDialog_58331_Content_15 = {
    Text = "Ryker mengangkat pistolnya, tepat mengarah ke wajah N yang diselimuti kabut."
  },
  AvgDialog_58331_Content_16 = {
    Text = "Memang, aku adalah seorang penjudi yang tak ada harapan. Tak peduli apakah keberuntungan berpihak padaku atau tidak, meskipun aku tahu akan kehilangan segalanya, aku tetap akan dengan senang hati menerima tantangan itu."
  },
  AvgDialog_58331_Content_17 = {
    Text = "Orang yang hanya mengandalkan keberuntungan dari takdir untuk bertaruh disebut orang normal, bukan penjudi. Bukankah kau juga melihat hal itu saat memilihku dulu?"
  },
  AvgDialog_58331_Content_18 = {
    Text = "Heh… hahaha… memang gila. Betapa bodoh dan naifnya dirimu tenggelam dalam keinginan instingmu sendiri, Tuan Penjudi."
  },
  AvgDialog_58331_Content_19 = {
    Text = "Sama-sama. Dibandingkan dengan penjudi lainnya, aku memiliki kelebihan terbesar, yaitu ——"
  },
  AvgDialog_58331_Content_2 = {
    Text = "Atas perintahmu, ular raja hitam pekat meluncur cepat dan melewati Tubuh N, mengikat-Nya dengan Jalinan erat-erat."
  },
  AvgDialog_58331_Content_21 = {
    Text = "Saya mengakui kekalahan saya."
  },
  AvgDialog_58331_Content_22 = {
    Text = "Pelatuk ditarik dengan lembut."
  },
  AvgDialog_58331_Content_23 = {
    Text = "Sebuah tembakan terdengar, kepala N perlahan jatuh ke samping."
  },
  AvgDialog_58331_Content_24 = {
    Text = "Benar-benar tidak sabar, aku sebenarnya sudah berniat untuk mengantarkan kalian pergi."
  },
  AvgDialog_58331_Content_25 = {
    Text = "Sebelum pergi, aku akan memberitahumu sebuah rahasia ——"
  },
  AvgDialog_58331_Content_26 = {
    Text = "Sebenarnya, aku tak pernah mengubah takdirmu. Permainan yang begitu menarik ini, berbuat curang tidak akan membawa kesenangan apa pun."
  },
  AvgDialog_58331_Content_27 = {
    Text = "Sampai jumpa lagi, Tuan Detektif."
  },
  AvgDialog_58331_Content_3 = {
    Text = "Kabut hitam yang mengalir dari tubuh Ular Raja terus bercampur dengan kabut hitam milik N, secara bertahap membuat-Nya memiliki wujud fisik."
  },
  AvgDialog_58331_Content_4 = {
    Text = "Lama tidak bertemu, hewan peliharaan yang dijaga oleh Kanak. Apakah tuanmu masih belum mereda kemarahannya?"
  },
  AvgDialog_58331_Content_5 = {
    Text = "Tuan tidak memiliki rasa benci terhadapmu. Apa yang dia lakukan juga dilakukan atas izinmu. Kami hanya dengan setia mengikuti skenario yang telah ditentukan."
  },
  AvgDialog_58331_Content_6 = {
    Text = "Begitu ya… menarik. Bahkan aku sendiri tidak menyadarinya sama sekali."
  },
  AvgDialog_58331_Content_7 = {
    Text = "Lidah ular raja yang panjang dan ramping bergerak perlahan, menyampaikan suara rendah dan lembut ke telinga kalian."
  },
  AvgDialog_58331_Content_8 = {
    Text = "Saya hanya bisa menahan proyeksi-Nya di Domain untuk sementara waktu. Setelah proyeksi menghilang, Domain akan segera terhapus."
  },
  AvgDialog_58331_Content_9 = {
    Text = "Selanjutnya… serahkan pada kalian."
  },
  AvgDialog_58332_Content_1 = {
    Text = "Penghormatan Terakhir"
  },
  AvgDialog_58332_Content_10 = {
    Text = "Seperti air mata."
  },
  AvgDialog_58332_Content_11 = {
    Text = "Lalu? Apa yang kamu lihat... setelah melihat kebenaran yang disebut-sebut itu."
  },
  AvgDialog_58332_Content_12 = {
    Text = "Kemudian... aku menumpas pemberontakan, Apep kujadikan seekor ular yang selamanya melingkar di bawah kakiku."
  },
  AvgDialog_58332_Content_13 = {
    Text = "Aku memerintahkan untuk sepenuhnya menutup Dinding Kebenaran, kemudian memulai pemerintahanku sendiri."
  },
  AvgDialog_58332_Content_14 = {
    Text = "Tidak ada ideologi, tidak ada sistem, tidak ada parlemen... Saya sembarangan menyusun sebuah daftar nama, lalu mengasingkan mereka satu per satu dan menyita harta benda mereka."
  },
  AvgDialog_58332_Content_15 = {
    Text = "Saya memberikan medali kepada rakyat yang telah mengunjungi kasino lebih dari 50 kali. Saya memerintahkan pembangunan piramida kaca di ibu kota yang tak akan pernah selesai…"
  },
  AvgDialog_58332_Content_16 = {
    Text = "Kamu ditertawakan oleh takdir, lalu memilih untuk menjadi seorang tiran. Apa yang terjadi selanjutnya? Apakah kamu akhirnya digulingkan?"
  },
  AvgDialog_58332_Content_17 = {
    Text = "Sebaliknya, negaraku sedang berkembang pesat. Apakah kamu tahu mengapa?"
  },
  AvgDialog_58332_Content_18 = {
    Text = "Kamu menggelengkan kepala. Kabut hitam tersenyum dengan puas."
  },
  AvgDialog_58332_Content_19 = {
    Text = "Karena perang terkecil yang dilancarkan oleh tiran yang rasional akan menelan biaya seribu kali lebih besar daripada harga yang harus dibayar rakyat akibat tindakanku yang semaunya."
  },
  AvgDialog_58332_Content_2 = {
    Text = "Sebelumnya……"
  },
  AvgDialog_58332_Content_21 = {
    Text = "Tapi kamu tidak bahagia, dan rakyatmu juga tidak akan puas dengan tindakan yang sembrono. Apa artinya melakukan ini?"
  },
  AvgDialog_58332_Content_22 = {
    Text = "Apa artinya? Mengejar kebahagiaan dan tujuan yang disebut-sebut hanya akan membuatku terjebak dalam jebakan orang dewasa itu. Aku tidak bahagia, juga tidak sedih."
  },
  AvgDialog_58332_Content_23 = {
    Text = "Aku hanya setia menjalani takdir, memainkan peran yang Dia inginkan dariku."
  },
  AvgDialog_58332_Content_24 = {Text = "Dia...?"},
  AvgDialog_58332_Content_25 = {
    Text = "Kamu menatap grafiti yang penuh kebencian namun terasa sedikit familiar di depanmu, dan tiba-tiba semuanya menjadi jelas."
  },
  AvgDialog_58332_Content_26 = {
    Text = "Ternyata N..."
  },
  AvgDialog_58332_Content_27 = {
    Text = "Jadi, kau juga menjadi korban yang bisa dia kendalikan sesuka hatinya. Sekarang kita berdua terjebak di sini, tidak bisa melakukan apa-apa…"
  },
  AvgDialog_58332_Content_28 = {
    Text = "Dengar? Suara tembakan tadi — temanmu belum menyerah."
  },
  AvgDialog_58332_Content_29 = {
    Text = "Saat kamu membaca memori-ku, aku juga telah membaca milikmu. Kamu dan Tuan Detektif itu... bagi-Nya, kalian berbeda."
  },
  AvgDialog_58332_Content_3 = {Text = "Bam——!"},
  AvgDialog_58332_Content_30 = {
    Text = "Jadi, aku tidak keberatan memberikan-Nya sebuah kejutan."
  },
  AvgDialog_58332_Content_31 = {
    Text = "Kabut hitam di sekitar Kanak terus bergerak, lalu perlahan-lahan berkumpul menjadi seekor ular kobra hitam pekat."
  },
  AvgDialog_58332_Content_32 = {
    Text = "Sebaiknya kau tidak datang mengganggu tidurku hanya karena tidak ada hal lebih baik untuk dilakukan, teman lamaku."
  },
  AvgDialog_58332_Content_33 = {
    Text = "Sudah lama tidak bertemu, Apophis. Ini teman baru saya, {Male=dia,Female=dia} membutuhkan bantuanmu."
  },
  AvgDialog_58332_Content_34 = {
    Text = "Apophis dengan anggun mengangkat tubuhnya tegak, lehernya melengkung lembut ke bawah, dan pupil vertikal berwarna hijau zamrudnya menatapmu dengan tenang."
  },
  AvgDialog_58332_Content_35 = {
    Text = "Rahasia keabadian hidup tidak lebih dari sekadar melupakan. Tuan saya telah melupakanmu lagi, sama seperti dia tidak ingat masa lalunya di Taranto."
  },
  AvgDialog_58332_Content_36 = {
    Text = "Namun, aku mengetahui jiwamu, mata buta yang pucat."
  },
  AvgDialog_58332_Content_37 = {
    Text = "Kalian... sudah pernah melihatku?"
  },
  AvgDialog_58332_Content_38 = {
    Text = "Bawa %player% pergi dari sini, Apophis."
  },
  AvgDialog_58332_Content_39 = {
    Text = "Ular hitam melilit tubuhmu dengan lembut, kabut mengalir ke dalam tubuhmu."
  },
  AvgDialog_58332_Content_4 = {
    Text = "Dari kejauhan, terdengar suara tembakan."
  },
  AvgDialog_58332_Content_40 = {
    Text = "Kamu menutup kedua matamu, tubuh yang kosong dipenuhi oleh kesadaran tanpa suara, dan cahaya redup Kunci Perak bersinar kembali."
  },
  AvgDialog_58332_Content_41 = {
    Text = "Detik berikutnya, peti mati di depanmu sudah menghilang. Kamu berdiri di sudut teater, tepat menghadap Ryker dan N di tengah panggung."
  },
  AvgDialog_58332_Content_42 = {
    Text = "Dari kedalaman pikiran, terdengar bisikan lembut dan rasional."
  },
  AvgDialog_58332_Content_43 = {
    Text = "Saya telah mematuhi perintah Tuan-ku untuk membawamu ke sini."
  },
  AvgDialog_58332_Content_44 = {
    Text = "Mimpi buruk telah berakhir, bukalah kedua matamu."
  },
  AvgDialog_58332_Content_5 = {
    Text = "Kamu membuka kedua matamu, di hadapanmu masih dinding yang dipenuhi dengan karakter-karakter yang terdistorsi."
  },
  AvgDialog_58332_Content_6 = {
    Text = "Entah sejak kapan, hujan mulai turun dari langit."
  },
  AvgDialog_58332_Content_7 = {
    Text = "Segumpal kabut hitam pekat melayang di sisimu. Kamu tidak bisa melihat dengan jelas bentuk kabut itu, namun merasakan keakraban yang aneh — itu adalah Kanak."
  },
  AvgDialog_58332_Content_8 = {
    Text = "Hujan terus turun, keheningan mengalir tanpa suara di antara kalian."
  },
  AvgDialog_58332_Content_9 = {
    Text = "Aneh sekali. Saat pertama kali dan terakhir kali aku melihat dinding ini, hujan yang sama turun dari langit."
  },
  AvgDialog_58879_Content_1 = {
    Text = "Sekarang, Apophis!"
  },
  AvgDialog_58879_Content_10 = {
    Text = "Ryker melangkah perlahan mendekati N."
  },
  AvgDialog_58879_Content_11 = {
    Text = "Tampaknya keberuntungan akhirnya berpihak kepada saya juga."
  },
  AvgDialog_58879_Content_12 = {
    Text = "Hati-hati, Tuan Detektif. Bagi seorang penjudi yang tak bisa diselamatkan, hal yang paling menakutkan dalam sebuah permainan bukanlah kalah, melainkan menang."
  },
  AvgDialog_58879_Content_13 = {
    Text = "Jika tidak percaya, cobalah tanyakan kepada pemilik ular hitam ini."
  },
  AvgDialog_58879_Content_14 = {
    Text = "Sepertinya kamu masih belum cukup memahamiku, namun ada satu hal yang kamu katakan dengan benar."
  },
  AvgDialog_58879_Content_15 = {
    Text = "Ryker mengangkat pistolnya, tepat mengarah ke wajah N yang diselimuti kabut."
  },
  AvgDialog_58879_Content_16 = {
    Text = "Memang, aku adalah seorang penjudi yang tak ada harapan. Tak peduli apakah keberuntungan berpihak padaku atau tidak, meskipun aku tahu akan kehilangan segalanya, aku tetap akan dengan senang hati menerima tantangan itu."
  },
  AvgDialog_58879_Content_17 = {
    Text = "Orang yang hanya mengandalkan keberuntungan dari takdir untuk bertaruh disebut orang normal, bukan penjudi. Bukankah kau juga melihat hal itu saat memilihku dulu?"
  },
  AvgDialog_58879_Content_18 = {
    Text = "Heh… hahaha… memang gila. Betapa bodoh dan naifnya dirimu tenggelam dalam keinginan instingmu sendiri, Tuan Penjudi."
  },
  AvgDialog_58879_Content_19 = {
    Text = "Sama-sama. Dibandingkan dengan penjudi lainnya, aku memiliki kelebihan terbesar, yaitu ——"
  },
  AvgDialog_58879_Content_2 = {
    Text = "Atas perintahmu, ular raja hitam pekat meluncur cepat dan melewati Tubuh N, mengikat-Nya dengan Jalinan erat-erat."
  },
  AvgDialog_58879_Content_21 = {
    Text = "Saya mengakui kekalahan saya."
  },
  AvgDialog_58879_Content_22 = {
    Text = "Pelatuk ditarik dengan lembut."
  },
  AvgDialog_58879_Content_23 = {
    Text = "Sebuah tembakan terdengar, kepala N perlahan jatuh ke samping."
  },
  AvgDialog_58879_Content_24 = {
    Text = "Panggung hancur, Domain runtuh, dan Ular Raja juga menghilang tanpa jejak."
  },
  AvgDialog_58879_Content_25 = {
    Text = "%player%, hati-hati dengan batu besar! Cepat lompat ke arahku!"
  },
  AvgDialog_58879_Content_26 = {
    Text = "Kamu dengan patuh melompat ke punggung Ryker, erat memegang kerah bajunya."
  },
  AvgDialog_58879_Content_27 = {
    Text = "Dari atas bahunya, tepi kosong di wajah N masih bergerak perlahan."
  },
  AvgDialog_58879_Content_28 = {
    Text = "Benar-benar tidak sabar, aku sebenarnya sudah berniat untuk mengantarkan kalian pergi."
  },
  AvgDialog_58879_Content_29 = {
    Text = "Sebelum pergi, aku akan memberitahumu sebuah rahasia ——"
  },
  AvgDialog_58879_Content_3 = {
    Text = "Kabut hitam yang mengalir dari tubuh Ular Raja terus bercampur dengan kabut hitam milik N, secara bertahap membuat-Nya memiliki wujud fisik."
  },
  AvgDialog_58879_Content_30 = {
    Text = "Sebenarnya, aku tak pernah mengubah takdirmu. Permainan yang begitu menarik ini, berbuat curang tidak akan membawa kesenangan apa pun."
  },
  AvgDialog_58879_Content_31 = {
    Text = "Sampai jumpa lagi, Tuan Detektif."
  },
  AvgDialog_58879_Content_4 = {
    Text = "Lama tidak bertemu, hewan peliharaan yang dijaga oleh Kanak. Apakah tuanmu masih belum mereda kemarahannya?"
  },
  AvgDialog_58879_Content_5 = {
    Text = "Tuan tidak memiliki rasa benci terhadapmu. Apa yang dia lakukan juga dilakukan atas izinmu. Kami hanya dengan setia mengikuti skenario yang telah ditentukan."
  },
  AvgDialog_58879_Content_6 = {
    Text = "Begitu ya… menarik. Bahkan aku sendiri tidak menyadarinya sama sekali."
  },
  AvgDialog_58879_Content_7 = {
    Text = "Lidah ular raja yang panjang dan ramping bergerak perlahan, menyampaikan suara rendah dan lembut ke telinga kalian."
  },
  AvgDialog_58879_Content_8 = {
    Text = "Saya hanya bisa menahan proyeksi-Nya di Domain untuk sementara waktu. Setelah proyeksi menghilang, Domain akan segera terhapus."
  },
  AvgDialog_58879_Content_9 = {
    Text = "Selanjutnya… serahkan pada kalian."
  },
  AvgDialog_58894_Content_1 = {
    Text = "Tamu tak diundang"
  },
  AvgDialog_58894_Content_10 = {
    Text = "Tidak. Bagaimana jika sudah malam?!"
  },
  AvgDialog_58894_Content_11 = {
    Text = "Kamu dengan cepat berguling turun dari tempat tidur, menemukan posisi pena, kertas draft, dan penghapus dengan tepat, lalu memasukkan semuanya ke dalam tas sekolah."
  },
  AvgDialog_58894_Content_12 = {
    Text = "Setelah semua persiapan selesai, kamu menarik napas dalam-dalam dan membuka pintu asrama."
  },
  AvgDialog_58894_Content_13 = {Text = "Eh…?"},
  AvgDialog_58894_Content_14 = {
    Text = "Sebuah bulan merah tergantung tinggi di langit, seluruh jalan tenggelam dalam cahaya merah yang redup, seolah-olah diselimuti oleh selapis kain tipis."
  },
  AvgDialog_58894_Content_15 = {
    Text = "Kesunyian melingkupi sekitar, lampu jalan di kedua sisi jalan berkedip dengan cahaya redup."
  },
  AvgDialog_58894_Content_16 = {
    Text = "Ini bukan sekolah yang aku kenal."
  },
  AvgDialog_58894_Content_18 = {
    Text = "Aku mengerti, ini pasti dalam mimpi. Bagus, aku akan kembali tidur…"
  },
  AvgDialog_58894_Content_19 = {
    Text = "Kamu berbalik dengan cepat, namun pintu asrama — lebih tepatnya, seluruh gedung asrama telah menghilang tanpa jejak."
  },
  AvgDialog_58894_Content_2 = {
    Text = "Berbagai macam hewan tinggal di sini, sesekali terdapat juga beberapa iblis. \n——Ian·@2,\"Kebangkitan Ikan Lele\""
  },
  AvgDialog_58894_Content_21 = {
    Text = "Kamu harus berbalik lagi dan menatap jalan di hadapanmu."
  },
  AvgDialog_58894_Content_22 = {
    Text = "Ada orang di sini——Halo——"
  },
  AvgDialog_58894_Content_23 = {
    Text = "Selamat pagi, selamat siang, selamat malam——"
  },
  AvgDialog_58894_Content_24 = {
    Text = "Guruh, guruh!"
  },
  AvgDialog_58894_Content_25 = {
    Text = "Syukurlah, akhirnya ada sesuatu yang merespons aku!"
  },
  AvgDialog_58894_Content_26 = {
    Text = "Kamu dengan bersemangat bergegas menuju sumber suara, namun hanya menemukan bahwa di sini terdapat sebuah kotak pos merah kecil."
  },
  AvgDialog_58894_Content_27 = {
    Text = "Gluk gluk, gangguan pencernaan, tolong... tolong..."
  },
  AvgDialog_58894_Content_28 = {
    Text = "<BigShake:Uwaa, bleh!>"
  },
  AvgDialog_58894_Content_29 = {
    Text = "Kotak pos bergerak neurosis, kemudian mengeluarkan sepucuk surat yang basah kuyup."
  },
  AvgDialog_58894_Content_3 = {
    Text = "Ting ting ting——"
  },
  AvgDialog_58894_Content_30 = {
    Text = "Apakah ini untukku? Tampaknya agak menjijikkan…"
  },
  AvgDialog_58894_Content_31 = {
    Text = "Mengamati sekeliling, semua bangunan terendam dalam cahaya bulan merah gelap, dengan pintu dan jendela tertutup rapat, mencegah siapa pun untuk masuk."
  },
  AvgDialog_58894_Content_32 = {
    Text = "Kamu adalah satu-satunya makhluk hidup dalam radius ratusan mil ini."
  },
  AvgDialog_58894_Content_33 = {
    Text = "Membuka amplop"
  },
  AvgDialog_58894_Content_34 = {
    Text = "Kamu berusaha mengabaikan sensasi lengket di ujung jarimu, lalu dengan tangan gemetar membuka amplop itu."
  },
  AvgDialog_58894_Content_35 = {
    Text = "Kepada penerima jauh di sana: \nHarap tiba di kediaman Franld sebelum tengah malam. Pastikan tepat waktu, jika tidak, akibatnya ditanggung sendiri (otak@2 meledak@3). \nAlamat: @2 Kabupaten \n-▼-"
  },
  AvgDialog_58894_Content_36 = {
    Text = "Rumah Franter? Aku ingat itu adalah kediaman milik Tuan Dexter. Sejak kapan orang ini juga belajar bermain lelucon…"
  },
  AvgDialog_58894_Content_37 = {
    Text = "Kamu mengangkat tanganmu dan melihat pergelangan tanganmu yang kosong."
  },
  AvgDialog_58894_Content_38 = {
    Text = "Lagipula, aku tidak membawa jam tangan, bahkan tidak tahu pukul berapa sekarang——"
  },
  AvgDialog_58894_Content_39 = {Text = "Tik. Tik."},
  AvgDialog_58894_Content_4 = {
    Text = "Hmm... sangat mengantuk, jangan ganggu aku."
  },
  AvgDialog_58894_Content_40 = {
    Text = "Entah sejak kapan, sebuah jam raksasa muncul di langit, dengan jarum jam dan jarum menit berhenti tepat pada pukul 11."
  },
  AvgDialog_58894_Content_41 = {
    Text = "Hanya jarum detik yang masih bergerak maju dengan dingin, teliti, dan kecepatan yang konsisten."
  },
  AvgDialog_58894_Content_42 = {
    Text = "Apa... yang terjadi..."
  },
  AvgDialog_58894_Content_43 = {
    Text = "Eh, apakah kamu juga menerima surat yang sama denganku?"
  },
  AvgDialog_58894_Content_44 = {
    Text = "Siapa itu?!"
  },
  AvgDialog_58894_Content_45 = {
    Text = "Maaf, sepertinya kamu sangat fokus tadi. Aku sudah memanggilmu beberapa kali…"
  },
  AvgDialog_58894_Content_46 = {
    Text = "Apakah kamu tidak ingat aku? Aku Elsa, kita pernah mengikuti Pengenalan Pelarutan oleh Miss Boneka."
  },
  AvgDialog_58894_Content_47 = {
    Text = "Elsa… Aku ingat, dia sering meminjam catatan dari Ramona."
  },
  AvgDialog_58894_Content_48 = {
    Text = "Maaf, karena aku selalu gagal dalam ujian…"
  },
  AvgDialog_58894_Content_49 = {
    Text = "Elsa menundukkan kepalanya dan dengan sedih memeluk erat bantal berbentuk hati di depan dadanya."
  },
  AvgDialog_58894_Content_50 = {
    Text = "Jangan sedih, Nona Elsa. Gagal dalam kelas Nona Boneka adalah jalan yang harus dilalui oleh kebanyakan Penyelidik."
  },
  AvgDialog_58894_Content_51 = {
    Text = "Ngomong-ngomong, tadi kamu bilang kalau kamu juga menerima surat yang sama, jadi apakah kamu bisa melihat itu juga?"
  },
  AvgDialog_58894_Content_52 = {
    Text = "Kamu menunjuk ke arah jam besar yang tergantung di atas bulan purnama. Elsa mengikuti pandanganmu dan mengangguk pelan."
  },
  AvgDialog_58894_Content_53 = {
    Text = "Bisa dilihat. Namun, aku tersesat dan tidak peduli bagaimana aku mencoba, aku tetap tidak bisa menemukan arah yang benar. Sekarang, aku hanya punya kurang dari 1 menit tersisa."
  },
  AvgDialog_58894_Content_54 = {
    Text = "Aneh, countdown saya masih tersisa 1 jam. Apakah karena kamu masuk ke dunia ini lebih dulu?"
  },
  AvgDialog_58894_Content_55 = {
    Text = "Saya tidak tahu. Ini hanya lelucon, kan, %player%%siormadam%? Saya belum pernah bertugas di lapangan dan tidak punya pengalaman dengan acara abnormal…"
  },
  AvgDialog_58894_Content_56 = {
    Text = "Jujur, ini juga pertama kalinya saya menghadapi situasi seperti ini."
  },
  AvgDialog_58894_Content_57 = {
    Text = "Waktu hingga hitungan mundur berakhir: <Red:3> detik"
  },
  AvgDialog_58894_Content_58 = {
    Text = "Kamu dengan lembut menggenggam tangan Elsa."
  },
  AvgDialog_58894_Content_59 = {
    Text = "Sekarang, bahkan lubang cacing pun tidak akan sempat membawamu ke Manor Franter, tapi jangan takut."
  },
  AvgDialog_58894_Content_6 = {
    Text = "Astaga, hari ini adalah hari ujian Pengantar Pelarutan. Jam berapa sekarang…"
  },
  AvgDialog_58894_Content_60 = {
    Text = "Waktu hingga hitungan mundur berakhir: <Red:0> detik"
  },
  AvgDialog_58894_Content_61 = {
    Text = "Apa pun yang akan terjadi selanjutnya, aku akan melindungi ——"
  },
  AvgDialog_58894_Content_62 = {
    Text = "Punya kamu..."
  },
  AvgDialog_58894_Content_63 = {
    Text = "Kepala Elsa meledak menjadi genangan hangat dari otak. Cairan kental itu muncrat ke wajah, dan ujung hidung mencium bau amis seperti karat."
  },
  AvgDialog_58894_Content_64 = {
    Text = "%player%@2, selamatkan @3…"
  },
  AvgDialog_58894_Content_65 = {
    Text = "Dari leher yang patah terus mengalir cairan hitam kental, dengan cepat membentuk wajah lain yang pucat dan asing."
  },
  AvgDialog_58894_Content_66 = {
    Text = "<Change>Tolong, tolong aku…"
  },
  AvgDialog_58894_Content_68 = {
    Text = "Bilah binatang mengiris udara, \"Elsa\" tubuhnya langsung terbelah menjadi dua, D-lendir hitam menyembur keluar seperti darah."
  },
  AvgDialog_58894_Content_69 = {
    Text = "Tidak ada gunanya, dia sudah kehilangan akal sehatnya."
  },
  AvgDialog_58894_Content_7 = {
    Text = "Jam 6:37, masih pagi kan…"
  },
  AvgDialog_58894_Content_70 = {
    Text = "Tuan Ryker?!"
  },
  AvgDialog_58894_Content_71 = {
    Text = "Ryker menarik kembali cakarnya dan dengan langkah ringan berjalan mendekati Anda."
  },
  AvgDialog_58894_Content_72 = {
    Text = "Kenapa ekspresi seperti mau menangis? Jangan khawatir, tempat ini mungkin adalah Domain seseorang."
  },
  AvgDialog_58894_Content_73 = {Text = "Domain…?"},
  AvgDialog_58894_Content_74 = {
    Text = "Mm. Artinya, dalam kenyataan, Elsa ini kemungkinan besar masih hidup dengan baik."
  },
  AvgDialog_58894_Content_75 = {
    Text = "Tidak salah lagi, Tuan Detektif. Dalam sekejap bisa membongkar Domain. Apa dasarnya?"
  },
  AvgDialog_58894_Content_76 = {
    Text = "Pertama kali aku bertemu dengan Elsa, malamnya juga seperti ini. Saat itu, dia dikejar oleh sekelompok monster Pelarutan hingga terdesak. Aku baru saja keluar dari tavern, memberinya petunjuk jalan, dan sekalian membunuh monster yang mengejarnya."
  },
  AvgDialog_58894_Content_77 = {
    Text = "Baru saja kami bertemu lagi, di waktu yang sama, di tempat yang sama. Namun, aku memberinya petunjuk yang salah, membuatnya mengalami cedera serius di kepala. Dengan kata lain—"
  },
  AvgDialog_58894_Content_78 = {
    Text = "Apa maksudnya?"
  },
  AvgDialog_58894_Content_79 = {
    Text = "Keberuntunganku hilang! Ini adalah sesuatu yang tidak mungkin terjadi, jadi aku menyimpulkan secara logis bahwa ini bukan kenyataan."
  },
  AvgDialog_58894_Content_8 = {
    Text = "Kamu meraba-raba mencari tombol alarm, lalu kembali tertidur lelap."
  },
  AvgDialog_58894_Content_80 = {
    Text = "Atau kamu tampar aku dua kali, kita pastikan apakah ini mimpi atau bukan? Aku sudah menampar diriku sendiri beberapa kali tadi, tapi tidak ada gunanya."
  },
  AvgDialog_58894_Content_82 = {
    Text = "Saya hanya tahu bahwa baik di Domain maupun di dunia nyata, saya tidak ingin melihat kepala saya pecah."
  },
  AvgDialog_58894_Content_83 = {
    Text = "Kalau begitu, kamu sangat membutuhkan bantuanku! Aku bertemu banyak orang yang terlambat seperti Elsa di jalan, sebaiknya kita lewat udara."
  },
  AvgDialog_58894_Content_84 = {
    Text = "Ryker berkata sambil menunjuk ke arah atap bangunan terdekat."
  },
  AvgDialog_58894_Content_85 = {
    Text = "Sayang sekali, aku hanyalah seorang Penjaga yang biasa saja, tidak bisa menemanimu terbang di atap gedung——"
  },
  AvgDialog_58894_Content_86 = {
    Text = "Detik berikutnya, Ryker meletakkanmu di punggungnya dan meloncat ke udara."
  },
  AvgDialog_58894_Content_87 = {
    Text = "Berpeganganlah, Penjaga %player%{Male=tuan,Female=nyonya}!"
  },
  AvgDialog_58894_Content_88 = {
    Text = "<Shake: Uwaaaaa!!>"
  },
  AvgDialog_58894_Content_89 = {
    Text = "Kamu ketakutan dan erat mencengkeram kerah baju Ryker. Detektif yang membungkuk itu dengan gesit melompati atap-atap besar dan kecil, berlarian di antara gedung-gedung yang berjejer rapat di Londinium."
  },
  AvgDialog_58894_Content_90 = {
    Text = "Seorang manusia dan seekor serigala meluncur dalam serangan di bawah bulan yang tenang. Di telinga, hanya terdengar suara angin yang bersih. Kamu menundukkan tubuhmu dan menyandarkan diri pada bulu lembut di bawahmu."
  },
  AvgDialog_58894_Content_91 = {
    Text = "Bagaimana, apakah menyenangkan?"
  },
  AvgDialog_58894_Content_92 = {
    Text = "Tidak disangka kau punya kemampuan seperti ini… Perlambat, ajukan permintaan untuk memperlambat!"
  },
  AvgDialog_58894_Content_93 = {
    Text = "Ryker tertawa terbahak-bahak, dadanya terus bergetar seolah-olah setiap sel di tubuhnya sedang bersorak gembira."
  },
  AvgDialog_58894_Content_94 = {
    Text = "Inilah yang seharusnya dilakukan oleh serigala! Aku hanya kembali ke keahlian lamaku, mengerti?"
  },
  AvgDialog_58894_Content_95 = {
    Text = "Aku sudah bilang, <BigShake: Perlambat!>"
  },
  AvgDialog_58894_Content_96 = {
    Text = "Pelan-pelan, jangan sembarangan mencabuti buluku!"
  },
  AvgDialog_58895_Content_1 = {
    Text = "Pertunjukan Tragedi"
  },
  AvgDialog_58895_Content_10 = {
    Text = "Mengenai hal ini, saya memiliki pendapat yang berbeda, namun mari kita lewati saja. Lalu, apa yang terjadi setelah Tuan Dexter keluar?"
  },
  AvgDialog_58895_Content_100 = {
    Text = "Sangat disayangkan kamu kehilangan seorang teman lagi. Mungkin, keberuntungan di dunia ini memang selalu tetap."
  },
  AvgDialog_58895_Content_101 = {
    Text = "Kamu mendapatkan keberuntungan, hidupmu semakin membaik, namun ada orang lain yang malah mengalami nasib buruk karenanya."
  },
  AvgDialog_58895_Content_102 = {
    Text = "Hukum misterius yang tak terlihat menggantung di atas kepala orang-orang. Apakah kamu benar-benar bisa menerimanya dengan tenang?"
  },
  AvgDialog_58895_Content_103 = {
    Text = "Haha... apa hukum misterius, ini hanya permainan kecil milikmu saja."
  },
  AvgDialog_58895_Content_104 = {
    Text = "Kebencianmu terhadapku masih datang dengan begitu tulus dan menggemaskan, membuatku hanya bisa menghela napas."
  },
  AvgDialog_58895_Content_105 = {
    Text = "Meskipun kalian belum bisa memecahkan semua teka-teki, aku selalu bersikap pemaaf…"
  },
  AvgDialog_58895_Content_106 = {
    Text = "N mengangkat jarinya dengan lembut, kabut hitam pekat tiba-tiba menyelimuti dirimu dan mengikatmu erat."
  },
  AvgDialog_58895_Content_107 = {
    Text = "Tidak... uh!"
  },
  AvgDialog_58895_Content_108 = {Text = "!!"},
  AvgDialog_58895_Content_109 = {
    Text = "Tuan N, saya tahu tindakan saya di Alan telah membuatmu marah, dan sekarang saya dengan sungguh-sungguh meminta maaf kepadamu."
  },
  AvgDialog_58895_Content_11 = {Text = "……!!"},
  AvgDialog_58895_Content_110 = {
    Text = "Kamu bisa menghukumku sesukamu, tapi {Male=dia,Female=dia} tidak bersalah!"
  },
  AvgDialog_58895_Content_111 = {
    Text = "Detektif yang tergesa-gesa, dengarkan aku sampai selesai. Aku telah menyiapkan satu pertanyaan terakhir untukmu."
  },
  AvgDialog_58895_Content_112 = {
    Text = "Baik, saya mendengarkan."
  },
  AvgDialog_58895_Content_113 = {
    Text = "Pilihan yang sangat sederhana: bunuh %player%, lalu aku akan menghidupkan kembali semua orang yang sebelumnya telah mati."
  },
  AvgDialog_58895_Content_114 = {
    Text = "Semuanya akan kembali seperti semula, kecuali orang sialan di sebelahmu ini. Tidak ada seorang pun yang menerima kerusakan."
  },
  AvgDialog_58895_Content_115 = {
    Text = "Atau kamu juga bisa memilih untuk tidak membunuh %player%, kalian berdua bisa meninggalkan Domain dengan selamat."
  },
  AvgDialog_58895_Content_116 = {
    Text = "Bagaimana, apakah sangat mudah?"
  },
  AvgDialog_58895_Content_117 = {Text = "?!"},
  AvgDialog_58895_Content_119 = {
    Text = "Apakah pistolmu masih ada di tubuhmu? Sekarang mulai hitung mundur. 10."
  },
  AvgDialog_58895_Content_12 = {
    Text = "Masih ingat hantu yang kulihat di tangga sebelumnya? Melayang di udara, hantu, gantung diri... Apakah mungkin..."
  },
  AvgDialog_58895_Content_120 = {
    Text = "Tidak, kamu tidak bisa…"
  },
  AvgDialog_58895_Content_121 = {Text = "9"},
  AvgDialog_58895_Content_122 = {
    Text = "Ryker menatapmu dengan sedikit bingung, seperti seorang anak yang telah melakukan kesalahan."
  },
  AvgDialog_58895_Content_123 = {
    Text = "Jangan pedulikan aku, batuk-batuk… Siapa tahu setelah aku mati, Mythag akan membuatku menjadi Pembangun."
  },
  AvgDialog_58895_Content_124 = {
    Text = "Kamu mencoba sekuat tenaga untuk menggerakkan semua otot di wajahmu, lalu memberikan senyuman yang dipaksakan kepada Ryker."
  },
  AvgDialog_58895_Content_125 = {Text = "... Ayo."},
  AvgDialog_58895_Content_126 = {Text = "6"},
  AvgDialog_58895_Content_127 = {
    Text = "Ryker perlahan berjalan ke arahmu, matanya tenang tanpa riak."
  },
  AvgDialog_58895_Content_128 = {
    Text = "Penglihatanmu mulai kabur, kamu menatap matanya, dan banyak kenangan tentang momen-momen yang kalian habiskan bersama muncul di benakmu."
  },
  AvgDialog_58895_Content_129 = {
    Text = "Ada yang saling mengejar dan bermain-main di padang pasir, ada yang melarikan diri bersama dari pertemuan ■■ Aram, dan ada juga dia yang menggunakan hidupnya sebagai umpan untuk memberikan luka fatal kepada Casiah…"
  },
  AvgDialog_58895_Content_13 = {
    Text = "Benar. Kebenarannya adalah: seseorang terlebih dahulu menarik perhatian Tuan Dexter, dan pada saat dia menjulurkan kepalanya, tali dilemparkan ke lehernya, lalu ditarik dengan keras ke atas——"
  },
  AvgDialog_58895_Content_130 = {
    Text = "Ada terlalu banyak kenangan di antara kalian."
  },
  AvgDialog_58895_Content_131 = {
    Text = "Tanpa terasa, Ryker sudah berdiri di depanmu. Kamu tidak bisa melihat wajahnya dengan jelas, tapi kamu tahu bahwa penderitaannya saat ini tidak kalah berat dibandingkan dengan milikmu."
  },
  AvgDialog_58895_Content_132 = {
    Text = "Detik berikutnya, dia mengangkat pistolnya."
  },
  AvgDialog_58895_Content_133 = {
    Text = "Tahukah kamu… aku tak pernah meragukanmu. Jadi——"
  },
  AvgDialog_58895_Content_134 = {
    Text = "Tembakan terdengar, tepat mengenai jantungmu, tidak meleset sedikit pun."
  },
  AvgDialog_58895_Content_135 = {
    Text = "A-apa……?"
  },
  AvgDialog_58895_Content_136 = {
    Text = "Ryker berdiri di hadapanmu dengan sikap angkuh, sudut bibirnya menyunggingkan senyuman penuh ejekan."
  },
  AvgDialog_58895_Content_137 = {
    Text = "Aku sudah menantikan saat ini untuk waktu yang lama, Penjaga."
  },
  AvgDialog_58895_Content_14 = {
    Text = "Ryker mengangkat wajahnya dan menunjuk ke arah kamar tidur di lantai dua."
  },
  AvgDialog_58895_Content_15 = {
    Text = "Pembunuh saat itu berada di dalam ruangan tersebut. Kedua ruangan itu kebetulan tersusun dalam satu garis lurus."
  },
  AvgDialog_58895_Content_16 = {
    Text = "Hebat! Dengan ini, kita bisa menjelaskan Acara hantu dan juga jejak kaki di bingkai jendela. Itu terjadi karena Mr. Dexter berusaha keras melawan saat ia diikat dengan tali."
  },
  AvgDialog_58895_Content_17 = {
    Text = "Ini membutuhkan kekuatan lengan yang kuat serta prediksi akurat terhadap sudut. Semua orang di sini telah disegel kemampuannya, bagaimana mungkin…"
  },
  AvgDialog_58895_Content_18 = {
    Text = "Hanna tiba-tiba berhenti di tengah kalimat, ada dugaan samar di dalam hatinya."
  },
  AvgDialog_58895_Content_19 = {
    Text = "Tapi… setelah Acara hantu, kami segera naik ke kamar tidur, dan selama waktu itu tidak ada suara lain yang terdengar. Pembunuh seharusnya masih berada di dalam kamar tidur."
  },
  AvgDialog_58895_Content_2 = {
    Text = "Hatsji... Hatsji!"
  },
  AvgDialog_58895_Content_20 = {
    Text = "Selain pemutar piringan hitam itu, tidak ada tempat lain yang terlihat mencurigakan… Hachoo, Hachoo!"
  },
  AvgDialog_58895_Content_21 = {
    Text = "Hanna dengan cepat menyeka dua aliran ingus yang berkilauan."
  },
  AvgDialog_58895_Content_22 = {
    Text = "Ayah surgawi, bagaimana bisa terserang flu di dalam Domain!"
  },
  AvgDialog_58895_Content_24 = {
    Text = "Bagian luar sudah dibahas dengan jelas. Ayo, semua masuk."
  },
  AvgDialog_58895_Content_25 = {
    Text = "Coba ingat kembali dengan cermat, apa yang terjadi setelah kita menendang pintu masuk."
  },
  AvgDialog_58895_Content_26 = {
    Text = "Apa yang terjadi..."
  },
  AvgDialog_58895_Content_27 = {
    Text = "Maaf, aku sekarang merasa tidak enak badan. Bolehkah aku beristirahat sebentar?"
  },
  AvgDialog_58895_Content_28 = {
    Text = "Maaf, @2 tidak terlalu nyaman... istirahat..."
  },
  AvgDialog_58895_Content_29 = {
    Text = "Istirahat sejenak @2 kali……"
  },
  AvgDialog_58895_Content_3 = {
    Text = "Efek pendinginan di Domain ini sangat luar biasa. Bos, apakah kita tidak bisa melakukan deduksi di sekitar perapian di dalam ruangan?"
  },
  AvgDialog_58895_Content_30 = {
    Text = "Harap semua orang segera pergi, jangan mengganggu waktu istirahat Tuan Dexter."
  },
  AvgDialog_58895_Content_31 = {
    Text = "<Shake:Wahhh!! Kamu dari kapan…>"
  },
  AvgDialog_58895_Content_32 = {
    Text = "Nona Erica, meskipun kamu sudah kehilangan akal sehatmu, aku tetap harus mengingatkanmu: di sini bahkan tidak ada sehelai rambut pun milik Dexter."
  },
  AvgDialog_58895_Content_33 = {
    Text = "Harap semua orang segera pergi, jangan…"
  },
  AvgDialog_58895_Content_34 = {
    Text = "Lupakan saja, jangan hiraukan dia untuk saat ini."
  },
  AvgDialog_58895_Content_35 = {
    Text = "Ternyata memang begitu……"
  },
  AvgDialog_58895_Content_36 = {
    Text = "Hanna tiba-tiba mengangkat kepalanya dan langsung menatap Erica yang berdiri di belakang kerumunan."
  },
  AvgDialog_58895_Content_37 = {
    Text = "Kamu tidak muncul belakangan. Kamu sudah ada di dalam ruangan sepanjang waktu… mungkin bersembunyi di balik pintu, setelah perhatian kita semua teralihkan oleh pemain piringan hitam…"
  },
  AvgDialog_58895_Content_38 = {
    Text = "Ditolak. Erica tidak memiliki kemampuan untuk membelah diri, sehingga tidak bisa menjelaskan mengapa korban ditemukan di ruang belajar."
  },
  AvgDialog_58895_Content_39 = {
    Text = "Ya, kamu tidak memiliki kemampuan untuk membelah diri. Jadi, kamu masih punya seorang asisten."
  },
  AvgDialog_58895_Content_4 = {
    Text = "Tenang, tidak akan memakan banyak waktu."
  },
  AvgDialog_58895_Content_40 = {Text = "!!"},
  AvgDialog_58895_Content_41 = {
    Text = "Mencekik seorang pria dewasa di udara dengan lengan mekanis yang dapat diperpanjang adalah hal yang sangat mudah bagi Nona Erica."
  },
  AvgDialog_58895_Content_42 = {
    Text = "Setelah Tuan Dexter menghembuskan napas terakhir, kamu bisa melemparkannya ke bawah, dan pembantu yang sudah menunggu lama akan membantumu menyeret mayatnya ke dalam ruang belajar."
  },
  AvgDialog_58895_Content_43 = {
    Text = "Ini juga menjelaskan mengapa ada dua bekas jeratan di tubuh serta kelembapan pada pakaian — karena mayat tersebut pernah diseret di salju."
  },
  AvgDialog_58895_Content_44 = {
    Text = "Jadi, satu-satunya orang yang mungkin menjadi pembantu adalah orang yang tidak memiliki alibi dari saat tembakan terdengar hingga setelah kejadian…"
  },
  AvgDialog_58895_Content_45 = {
    Text = "Ryker berbicara sambil memandang ke arah ruang belajar yang diterangi oleh cahaya kuning redup berkedip."
  },
  AvgDialog_58895_Content_46 = {
    Text = "Nyonya Sorel."
  },
  AvgDialog_58895_Content_47 = {
    Text = "Ternyata begitu. Aku hanya menebak bahwa Tuan Dexter dicekik di udara, tapi sama sekali tidak menduga ada seorang kaki tangan."
  },
  AvgDialog_58895_Content_48 = {
    Text = "Ditolak. Semua penalaran di atas hanyalah spekulasi, tanpa dukungan bukti nyata."
  },
  AvgDialog_58895_Content_49 = {
    Text = "Mau bukti? Itu sangat mudah."
  },
  AvgDialog_58895_Content_5 = {
    Text = "Pertama-tama, sepatu yang terjatuh di luar. Pertanyaan: Dalam situasi apa sepatu bisa berada di luar?"
  },
  AvgDialog_58895_Content_50 = {
    Text = "Apakah kamu masih ingat pola dua bekas cekikan di leher mayat itu?"
  },
  AvgDialog_58895_Content_51 = {
    Text = "Dua bekas tali memiliki pola yang tidak konsisten. Di bagian dalam terdapat struktur berbentuk belah ketupat yang rapi, sedangkan di bagian luar lebih kasar…"
  },
  AvgDialog_58895_Content_52 = {
    Text = "Mungkin tali putus di tengah jalan, atau mungkin terkena darah, sehingga pelaku mengganti tali tersebut dengan yang baru."
  },
  AvgDialog_58895_Content_53 = {Text = "!!"},
  AvgDialog_58895_Content_54 = {
    Text = "Berbentuk belah ketupat yang rapi. Nona Erica, tolong panjangkan lengan mekanikmu untuk diperlihatkan kepada semua orang, lihatlah pola Tautan yang bisa ditarik di dalamnya."
  },
  AvgDialog_58895_Content_56 = {
    Text = "Menggunakan tali untuk secara tepat melilit leher seorang pria dewasa yang waspada di lantai dua, bagaimana pun dipikirkan, tampaknya seperti tugas yang hampir mustahil untuk dilakukan."
  },
  AvgDialog_58895_Content_57 = {
    Text = "Tetapi jika tali itu sebenarnya adalah bagian dari tubuhmu, maka semuanya bisa dijelaskan."
  },
  AvgDialog_58895_Content_58 = {
    Text = "Ternyata benar kamu, Nona Erica…"
  },
  AvgDialog_58895_Content_59 = {
    Text = "Erica perlahan memanjangkan lengan kanannya. Di bawah sorotan lampu, Tautan antara lengan bawah dan tangannya memancarkan cahaya dingin yang mengerikan."
  },
  AvgDialog_58895_Content_6 = {
    Text = "Hmm... orang mati keluar, lalu mengalami kecelakaan?"
  },
  AvgDialog_58895_Content_60 = {
    Text = "Pola berbentuk belah ketupat tersusun rapi, seolah-olah sisik ikan di kedalaman Aequor."
  },
  AvgDialog_58895_Content_61 = {
    Text = "Ternyata... benar-benar sama..."
  },
  AvgDialog_58895_Content_62 = {
    Text = "Erica tidak memberikan tanggapan. Kabut hitam perlahan keluar dari tubuhnya, lalu ——"
  },
  AvgDialog_58895_Content_63 = {
    Text = "Penalaran yang bagus! Apakah ini adalah kesimpulan akhir yang kalian ajukan?"
  },
  AvgDialog_58895_Content_64 = {
    Text = "Tentu. Saya rasa tidak ada masalah lain di sini."
  },
  AvgDialog_58895_Content_66 = {
    Text = "Haha... kalau begitu, sangat disayangkan. Masih ada satu langkah lagi."
  },
  AvgDialog_58895_Content_67 = {
    Text = "Ini bukanlah kebenaran terakhir, jadi——"
  },
  AvgDialog_58895_Content_68 = {
    Text = "N menjentikkan jarinya, dan tubuh Hannah segera mengeluarkan gulungan kabut hitam yang menyebar di dalam ruang belajar."
  },
  AvgDialog_58895_Content_69 = {
    Text = "Dia dengan panik mencengkeram jaket Ryker."
  },
  AvgDialog_58895_Content_7 = {
    Text = "Memang, ini adalah salah satu kemungkinan. Setelah melakukan perbandingan, kami menemukan bahwa pola sol sepatu ini sepenuhnya cocok dengan jejak kaki yang tertinggal di bingkai jendela."
  },
  AvgDialog_58895_Content_70 = {
    Text = "Bagaimana mungkin, Bukankah Erica juga tidak membantahnya?!"
  },
  AvgDialog_58895_Content_71 = {
    Text = "Tunggu sebentar! Aku belum selesai bicara tadi…"
  },
  AvgDialog_58895_Content_72 = {
    Text = "Hei hei hei, teman Penjaga-mu terlalu terburu-buru, lain kali ingatlah untuk berbicara sebelum {Male=dia,Female=dia} ya~"
  },
  AvgDialog_58895_Content_73 = {
    Text = "Tolong selamatkan aku… Bos! Aku belum mendengar kebenaran terakhir, jangan…"
  },
  AvgDialog_58895_Content_74 = {
    Text = "Saat berikutnya, Hanna juga menghilang di hadapanmu."
  },
  AvgDialog_58895_Content_75 = {
    Text = "Nona Hanna!"
  },
  AvgDialog_58895_Content_76 = {
    Text = "Tidak, ini semua salahku..."
  },
  AvgDialog_58895_Content_77 = {
    Text = "Hmm, sekarang hanya tersisa kita bertiga. Adapun yang lainnya, kemungkinan besar mereka sedang menderita di dunia nyata."
  },
  AvgDialog_58895_Content_78 = {
    Text = "Hihiihi, menarik, sangat menarik!"
  },
  AvgDialog_58895_Content_79 = {
    Text = "Ruang Medis Mythag\nSementara itu……"
  },
  AvgDialog_58895_Content_8 = {
    Text = "Mungkinkah Tuan Mulia Dexter, yang selalu menjunjung tinggi etika, akan keluar melalui jendela di rumahnya sendiri, apalagi saat kunci pintu masih utuh?"
  },
  AvgDialog_58895_Content_80 = {
    Text = "Bagaimana situasinya?"
  },
  AvgDialog_58895_Content_81 = {
    Text = "Kondisi Nyonya Hanna dan Penjaga juga mulai memburuk. Entah kenapa, organ dalam Nyonya Hanna mengalami keretakan di banyak tempat dan ada tanda-tanda berdarah di dalam tubuhnya."
  },
  AvgDialog_58895_Content_82 = {
    Text = "Penjaga juga mengalami gejala sesak napas yang parah. Jika terus dibiarkan seperti ini…"
  },
  AvgDialog_58895_Content_83 = {
    Text = "Kami telah mengunjungi banyak teman sekelas, dan rekan-rekan di departemen teknis juga sedang memeriksa semua fasilitas. Saat ini, tidak ada kelainan yang ditemukan."
  },
  AvgDialog_58895_Content_84 = {
    Text = "Bisa menimbulkan keributan sebesar ini tepat di depan mata semua orang..."
  },
  AvgDialog_58895_Content_85 = {Text = "...N."},
  AvgDialog_58895_Content_86 = {
    Text = "Ini adalah pandangan yang disepakati oleh saya dan Alistair. Jika itu tentang Dia, semuanya bisa dijelaskan."
  },
  AvgDialog_58895_Content_87 = {
    Text = "Lalu apa yang harus kita lakukan? Kita sama sekali tidak memiliki tindakan balasan…"
  },
  AvgDialog_58895_Content_88 = {
    Text = "Boneka membelai kepala bulat di tangannya, lalu menghela napas pelan."
  },
  AvgDialog_58895_Content_89 = {
    Text = "Satu-satunya hal yang pasti adalah: Dia seharusnya belum terburu-buru untuk mengambil nyawa Penjaga."
  },
  AvgDialog_58895_Content_9 = {
    Text = "Dia melihat sesuatu di luar jendela, apakah dia buru-buru keluar?"
  },
  AvgDialog_58895_Content_90 = {
    Text = "Adapun sisanya... Saran saya, berdoa bersama saya."
  },
  AvgDialog_58895_Content_91 = {
    Text = "Baiklah, semua orang yang tidak berkepentingan sudah pergi. Kita bisa saling terbuka sekarang."
  },
  AvgDialog_58895_Content_92 = {
    Text = "Dari tubuh N muncul kabut dingin yang menyelimuti wajah-Nya lapis demi lapis, hingga akhirnya sosok aslinya lenyap sepenuhnya."
  },
  AvgDialog_58895_Content_93 = {
    Text = "Tidak hanya itu, medan salju tempat kalian berada juga tiba-tiba menghilang, digantikan oleh gedung opera yang sudah familiar."
  },
  AvgDialog_58895_Content_94 = {
    Text = "Membuat semua orang tersenyum. Saya selalu menjadi orang yang sangat memperhatikan kualitas lingkungan."
  },
  AvgDialog_58895_Content_95 = {
    Text = "Sudah lama tidak bertemu, teman-teman lamaku."
  },
  AvgDialog_58895_Content_96 = {
    Text = "Apa maksudmu tadi, ini bukan kebenaran terakhir...?"
  },
  AvgDialog_58895_Content_97 = {
    Text = "Karena kamu belum menemukan pelaku sebenarnya yang membunuh Nyonya Sorel. Semua penalaranmu sengaja menghindari kematiannya, bukan?"
  },
  AvgDialog_58895_Content_99 = {
    Text = "Maaf, aku terlalu terburu-buru menyela pembicaraanmu."
  },
  AvgDialog_59157_Content_1 = {
    Text = "Pemandu, Penyihir, dan Budak"
  },
  AvgDialog_60107_Content_10 = {
    Text = "Lotan bersandar di bangku panjang, mengangkat kepalanya, dan menggerakkan sendi-sendi tubuhnya."
  },
  AvgDialog_60107_Content_100 = {
    Text = "Rencana Lemwah gagal, sangat disayangkan, tetapi tidak terlalu penting."
  },
  AvgDialog_60107_Content_101 = {
    Text = "Yang benar-benar penting hanyalah hari ini——hari ini, dua puluh tahun kemudian."
  },
  AvgDialog_60107_Content_102 = {
    Text = "Merupakan hal yang menyenangkan bisa menyaksikan momen penting ini bersama seorang rekan seperti dirimu."
  },
  AvgDialog_60107_Content_103 = {
    Text = "Tujuan kita sama. Pertunjukan ini bukan dipersembahkan untukmu atau untukku."
  },
  AvgDialog_60107_Content_104 = {
    Text = "Demi mendengar kembali suara yang dibawa oleh keberadaan agung itu, semua pengorbanan terasa tidak berarti."
  },
  AvgDialog_60107_Content_105 = {
    Text = "Berbalik, berdiri tegak. Sang konduktor muda mengangkat kedua tangannya, memberi hormat kepada gedung teater yang kosong, serta kepada kedalaman galaksi yang tak terjangkau di luar teater."
  },
  AvgDialog_60107_Content_106 = {
    Text = "Semuanya sudah siap, mari kita berangkat, Nyonya Juliette."
  },
  AvgDialog_60107_Content_107 = {
    Text = "Pertunjukan yang sesungguhnya, akan segera dimulai."
  },
  AvgDialog_60107_Content_11 = {
    Text = "Sejak upacara kunci makam, Mythag terus mengalami masalah."
  },
  AvgDialog_60107_Content_12 = {
    Text = "Bertemu dengan lawan yang menarik memang menyenangkan, namun memiliki waktu untuk beristirahat juga tidak buruk."
  },
  AvgDialog_60107_Content_13 = {
    Text = "Ogier meletakkan tombak panjangnya, berdiri di samping dengan alis sedikit berkerut."
  },
  AvgDialog_60107_Content_14 = {
    Text = "Ngomong-ngomong... Nyonya Lotan, apakah Anda merasa bahwa akhir-akhir ini kita menghadapi kejadian yang terlalu sering?"
  },
  AvgDialog_60107_Content_15 = {
    Text = "Dari panti asuhan, museum lilin, hingga Rai, kapal Sonani, dan bukit pasir Sungai Suci di Lermwah…"
  },
  AvgDialog_60107_Content_16 = {
    Text = "Sejak Tuan menjadi Penjaga, semua hal ini terjadi bersamaan. Ini sama sekali tidak terlihat seperti kebetulan."
  },
  AvgDialog_60107_Content_17 = {
    Text = "Boneka juga pernah membicarakan hal ini denganku, tetapi aku tidak terlalu tertarik."
  },
  AvgDialog_60107_Content_18 = {
    Text = "Hal yang memerlukan pemikiran, biarlah Boneka dan yang lainnya yang menangani. Tugas kita bukan ini."
  },
  AvgDialog_60107_Content_19 = {
    Text = "Lotan dengan cekatan meletakkan tangannya di pedang raksasa yang berdiri di sampingnya."
  },
  AvgDialog_60107_Content_2 = {Text = "Masuk"},
  AvgDialog_60107_Content_20 = {
    Text = "Penjaga membawa Mythag berjalan di jalan yang benar. Yang perlu aku lakukan hanyalah muncul dengan pedangku di hadapan {Male=dia,Female=dia} ketika {Male=dia,Female=dia} membutuhkanku."
  },
  AvgDialog_60107_Content_21 = {
    Text = "Benar sekali, Nyonya Lotan! Saya percaya bahwa Tuan kita pasti akan membawa kita menemukan cara untuk mengatasi Pelarutan. Ketenangan di Mythag adalah bukti terbaik!"
  },
  AvgDialog_60107_Content_22 = {
    Text = "Ogier melihat ke belakang ke arah kampus yang penuh ketenangan, dengan penuh harap ia mengangkat tombak panjangnya kembali."
  },
  AvgDialog_60107_Content_23 = {
    Text = "Ayo pergi, Nyonya Lotan. Saya tahu banyak kegiatan menarik tentang pertandingan ksatria. Setelah patroli hari ini selesai, kita akan mengundang tuan kita untuk ikut serta..."
  },
  AvgDialog_60107_Content_24 = {
    Text = "Jika beruntung, bisakah kamu membawa kami juga?"
  },
  AvgDialog_60107_Content_25 = {Text = "!!!"},
  AvgDialog_60107_Content_26 = {
    Text = "Ogier tiba-tiba berbalik."
  },
  AvgDialog_60107_Content_27 = {
    Text = "Gerbang sekolah Mythag terbuka tanpa suara. Dari Kabut tebal yang seharusnya memisahkan Mythag dari dunia luar, sekelompok orang perlahan-lahan berjalan keluar."
  },
  AvgDialog_60107_Content_28 = {
    Text = "Di seragam mereka, lambang Komite perjanjian mystia terlihat jelas."
  },
  AvgDialog_60107_Content_29 = {
    Text = "Kamu... kalian adalah..."
  },
  AvgDialog_60107_Content_3 = {Text = "Ding——"},
  AvgDialog_60107_Content_30 = {
    Text = "Agen yang memimpin mengeluarkan selembar kertas dengan cap dan pola rahasia dari sakunya, lalu memberikannya kepada Ogier."
  },
  AvgDialog_60107_Content_31 = {
    Text = "Setelah diselidiki, anggota Mythag yang dipimpin oleh Alistair secara ilegal menggunakan Kolam hitam untuk penelitian pelarutan, yang secara serius mengancam keselamatan warga negara Leo."
  },
  AvgDialog_60107_Content_32 = {
    Text = "Unit Tindakan Khusus Komite Perjanjian Mystia, diperintahkan untuk mengambil alih Mishtag, menangkap pelaku pelanggaran hukum."
  },
  AvgDialog_60107_Content_33 = {
    Text = "Komite… penjahat… tapi kami tidak pernah menerima pemberitahuan!"
  },
  AvgDialog_60107_Content_34 = {
    Text = "Tindakan Komite tidak perlu memberi tahu sekolahmu, nak."
  },
  AvgDialog_60107_Content_35 = {
    Text = "Benarkah? Tapi aku ingat aturan Mythag tidak seperti ini."
  },
  AvgDialog_60107_Content_36 = {
    Text = "Lotan mengangkat pedangnya dan bangkit berdiri."
  },
  AvgDialog_60107_Content_37 = {
    Text = "Saya tidak tahu bagaimana kalian bisa menembus Kabut di luar sekolah. Sepertinya, sebelum kau dikalahkan, kau juga tidak akan begitu terbuka."
  },
  AvgDialog_60107_Content_38 = {
    Text = "Aturan Mythag, siapa pun yang masuk tanpa izin akan dianggap sebagai penyusup."
  },
  AvgDialog_60107_Content_39 = {
    Text = "Perhatikan kata-katamu, Nyonya. Kamu sedang berbicara dengan Komite!"
  },
  AvgDialog_60107_Content_4 = {
    Text = "Suara lonceng yang jernih terdengar, disertai dengan tawa siswa Mythag yang datang dari kejauhan, mengagetkan kawanan burung yang sedang beristirahat di atap."
  },
  AvgDialog_60107_Content_40 = {
    Text = "Maaf, pelajaran umumku tidak terlalu bagus. Apa itu Komite?"
  },
  AvgDialog_60107_Content_41 = {Text = "!!!"},
  AvgDialog_60107_Content_42 = {
    Text = "Sebelum dia sempat melihat dengan jelas, sosok Lotan sudah berada di belakangnya."
  },
  AvgDialog_60107_Content_43 = {
    Text = "Ogier dengan cekatan mengikuti Lotan, lalu memasang perisai di belakangnya."
  },
  AvgDialog_60107_Content_44 = {
    Text = "Mythag bukan tempat yang bisa kalian kunjungi sesuka hati, nak."
  },
  AvgDialog_60107_Content_45 = {
    Text = "Lotan memegang pedang raksasa terbalik dan dengan gagang pedang menyerang pemimpin Komite secara tak terbendung —"
  },
  AvgDialog_60107_Content_46 = {Text = "Ding——"},
  AvgDialog_60107_Content_47 = {
    Text = "Tenangkan amarahmu, dengarkan suara dari kedalaman kesadaran."
  },
  AvgDialog_60107_Content_48 = {
    Text = "Tenggelam dalam tidur yang damai, teman baikku. Semua kekacauan ini tidak ada hubungannya dengan kalian…"
  },
  AvgDialog_60107_Content_49 = {
    Text = "Suara lonceng angin yang jernih entah dari mana terdengar, meskipun lemah dan jauh, namun saat masuk ke telinga terdengar sangat jelas."
  },
  AvgDialog_60107_Content_5 = {
    Text = "Pada senja hari, cahaya yang berkabut melewati patung sang pendiri, menerpa wajah Lotan."
  },
  AvgDialog_60107_Content_50 = {
    Text = "Pedang raksasa Lotan dan senjata perisai Ogier jatuh ke tanah. Dalam sekejap setelah mendengar suara lonceng angin, kedua orang itu langsung kehilangan semua kekuatan mereka."
  },
  AvgDialog_60107_Content_51 = {
    Text = "Rasa kantuk yang kuat melanda tubuh mereka. Mereka berusaha keras untuk membuka mata."
  },
  AvgDialog_60107_Content_52 = {
    Text = "Dalam pandangan yang kabur, sosok seorang wanita perlahan-lahan muncul dari balik Kabut."
  },
  AvgDialog_60107_Content_53 = {
    Text = "Tidak salah lagi, ini Mythag. Pemandangan di sini sama memukau seperti yang dikabarkan."
  },
  AvgDialog_60107_Content_54 = {
    Text = "Kamu... kamu..."
  },
  AvgDialog_60107_Content_55 = {
    Text = "Kita pernah bertemu sekali, namun saya khawatir Tuan Muda mungkin sudah melupakannya."
  },
  AvgDialog_60107_Content_56 = {
    Text = "Panti asuhan… dokter…"
  },
  AvgDialog_60107_Content_57 = {
    Text = "Ah, meskipun sudah begitu lama, masih diingat oleh orang lain, sungguh suatu kehormatan."
  },
  AvgDialog_60107_Content_58 = {
    Text = "Maaf karena tidak bisa menemui kalian lebih awal, tetapi menghadapi Pembangun Mythag, memang diperlukan beberapa trik kecil untuk bisa masuk secara paksa."
  },
  AvgDialog_60107_Content_59 = {
    Text = "Beristirahatlah dengan baik."
  },
  AvgDialog_60107_Content_6 = {
    Text = "Cuaca yang langka. Ogier, ayo berlatih pedang denganku."
  },
  AvgDialog_60107_Content_60 = {
    Text = "Dia dengan lembut menepuk kepala Lotan dan Ogier. Mereka tidak mampu bertahan lebih lama dan akhirnya tertidur."
  },
  AvgDialog_60107_Content_61 = {
    Text = "Clementine bangkit berdiri, lengan terangkat sedikit, menunjuk ke arah dalam Mythag."
  },
  AvgDialog_60107_Content_62 = {
    Text = "Kampus yang selama ini berada di luar masalah, sekarang juga harus menghadapi takdirnya."
  },
  AvgDialog_60107_Content_63 = {
    Text = "Operasi Invasi Mythag, dimulai."
  },
  AvgDialog_60107_Content_64 = {
    Text = "12 yard jauhnya, Hanna bersembunyi di semak-semak, menutup mulutnya erat-erat, tidak berani mengeluarkan suara sedikit pun."
  },
  AvgDialog_60107_Content_65 = {
    Text = "Melalui celah di semak-semak, dia melihat Clementine memimpin anggota Komite berjalan menuju bagian dalam Mythag dari kedua sisi."
  },
  AvgDialog_60107_Content_66 = {
    Text = "Masalah besar... terjadi masalah besar..."
  },
  AvgDialog_60107_Content_67 = {
    Text = "Harus segera memberi tahu semua orang… dan Penjaga!"
  },
  AvgDialog_60107_Content_69 = {
    Text = "Tongkat konduktor meluncur di udara, membentuk busur yang anggun. Bagian penutup dari gerakan musik telah tiba."
  },
  AvgDialog_60107_Content_7 = {
    Text = "Nyonya Lotan, patroli kami belum selesai."
  },
  AvgDialog_60107_Content_70 = {
    Text = "Lanskap suara yang mendebarkan, dirajut oleh akor kuat dan polifoni kompleks, mulai mereda."
  },
  AvgDialog_60107_Content_71 = {
    Text = "Arpeggio dari seruling dan harpa perlahan mengalun, seperti cahaya senja yang memantul di antara awan."
  },
  AvgDialog_60107_Content_72 = {
    Text = "Akor harmonis yang panjang perlahan memudar di udara, tanda istirahat pada not terakhir membawa nada menuju akhir."
  },
  AvgDialog_60107_Content_73 = {
    Text = "Pada saat yang begitu lama ini, konduktor menaruh tongkat konduktornya. Dia terdiam sambil melakukan perhitungan."
  },
  AvgDialog_60107_Content_74 = {
    Text = "Sepuluh detik, penonton terpesona oleh alunan musik, dan teater akan tenggelam dalam keheningan yang mirip dengan fajar."
  },
  AvgDialog_60107_Content_75 = {
    Text = "Dalam satu menit lima belas detik, tepuk tangan penonton akan bergemuruh seperti guntur, berlangsung lama sebelum akhirnya perlahan memudar."
  },
  AvgDialog_60107_Content_76 = {
    Text = "Dalam dua puluh lima menit, orkestra dan penonton akan meninggalkan tempat."
  },
  AvgDialog_60107_Content_77 = {
    Text = "Waktu sama persis seperti yang diperkirakan, seperti pertunjukan kedua yang sangat presisi."
  },
  AvgDialog_60107_Content_78 = {
    Text = "Konduktor dengan puas mengangguk, lalu membungkuk memberi hormat kepada kursi penonton yang kosong."
  },
  AvgDialog_60107_Content_8 = {
    Text = "Kamu ini baik dalam segala hal, cuma terlalu serius."
  },
  AvgDialog_60107_Content_80 = {
    Text = "Di sudut yang tidak mencolok di sisi tempat duduk penonton, tepuk tangan kecil terdengar kembali."
  },
  AvgDialog_60107_Content_81 = {
    Text = "Sebuah pertunjukan yang luar biasa, Tuan Hameln."
  },
  AvgDialog_60107_Content_82 = {
    Text = "Mungkin bisa dianggap lengkap, namun masih jauh dari kata luar biasa. Pertunjukan yang benar-benar luar biasa berada di luar teater."
  },
  AvgDialog_60107_Content_83 = {
    Text = "Konduktor menyimpan tongkat konduktornya, mengerutkan alisnya sambil menatap seorang wanita di sisi panggung penonton."
  },
  AvgDialog_60107_Content_84 = {
    Text = "Kita sudah berbicara sebelumnya, kamu seharusnya tidak berada di dalam teater, Nyonya Juliette."
  },
  AvgDialog_60107_Content_85 = {
    Text = "Kerja sama kita tidak ada hubungannya dengan pertunjukan saya, dan saya tidak ingin ada gangguan apa pun terhadapnya. Saya pikir kamu sudah paham akan hal ini."
  },
  AvgDialog_60107_Content_86 = {
    Text = "Selain itu, kemunculanmu di sini dengan identitasmu akan menimbulkan masalah yang tidak perlu."
  },
  AvgDialog_60107_Content_87 = {
    Text = "Tentu saja, Tuan Hameln. Hanya saja, jika saya tidak datang untuk mendengarkan penampilanmu secara langsung, saya akan sangat menyesal."
  },
  AvgDialog_60107_Content_88 = {
    Text = "Juliette tersenyum dan mengangguk hormat, lalu dengan lembut merapikan kerutan pada ujung bajunya."
  },
  AvgDialog_60107_Content_89 = {
    Text = "Dia sudah terbiasa dengan cara Hameln berbicara dan tidak mempermasalahkannya."
  },
  AvgDialog_60107_Content_9 = {
    Text = "Waktu senggang yang begitu langka, jika tidak digunakan untuk mencari kegiatan hiburan, terasa sangat membosankan."
  },
  AvgDialog_60107_Content_90 = {
    Text = "Ngomong-ngomong, saya juga memiliki hal penting yang perlu disampaikan langsung kepada Anda."
  },
  AvgDialog_60107_Content_91 = {
    Text = "Apakah operasi sudah dimulai?"
  },
  AvgDialog_60107_Content_92 = {
    Text = "Bagus. Clementine berhasil menangani patroli Mythag dengan lancar, kita mendapatkan lebih banyak waktu daripada yang diperkirakan."
  },
  AvgDialog_60107_Content_93 = {
    Text = "Rencanamu sangat sukses."
  },
  AvgDialog_60107_Content_94 = {
    Text = "Hanya sebuah preludium yang tidak terlalu rumit. Masih terlalu dini untuk menyatakan keberhasilan saat ini."
  },
  AvgDialog_60107_Content_95 = {
    Text = "Saya percaya pada kebijaksanaanmu, Tuan Konduktor."
  },
  AvgDialog_60107_Content_96 = {
    Text = "Sudah berapa lama kita menantikan hari ini?"
  },
  AvgDialog_60107_Content_97 = {
    Text = "Hampir dua puluh tahun."
  },
  AvgDialog_60107_Content_98 = {
    Text = "Benar, hampir dua puluh tahun. Betapa lama waktu itu berlalu."
  },
  AvgDialog_60107_Content_99 = {
    Text = "Para pematung dan Pelaut telah menarik perhatian yang cukup bagi kami. Keberadaan kami tersembunyi dengan baik."
  },
  AvgDialog_60202_Content_1 = {
    Text = "Penelitian ilegal? Mengambil alih Mythag…"
  },
  AvgDialog_60202_Content_10 = {
    Text = "Meluncurkan serangan"
  },
  AvgDialog_60202_Content_11 = {
    Text = "Lindungi dirimu dengan baik, Hanna."
  },
  AvgDialog_60202_Content_2 = {
    Text = "Benar… orang dari Komite berkata seperti itu!"
  },
  AvgDialog_60202_Content_3 = {
    Text = "Ini mungkin bukan tindakan resmi dari Komite. Wanita itu, Clementine, pasti memiliki tujuan lain…"
  },
  AvgDialog_60202_Content_4 = {
    Text = "Bagaimana situasinya sekarang? Apakah yang lain sudah mengetahuinya?"
  },
  AvgDialog_60202_Content_5 = {
    Text = "Setelah mereka memasuki gerbang sekolah, mereka berpisah... Wanita itu membawa rombongan besar menuju gedung perkuliahan."
  },
  AvgDialog_60202_Content_6 = {
    Text = "Saya sudah menjelaskan situasinya kepada guru dan teman-teman yang saya temui di sepanjang jalan, beberapa Pembangun sudah bergegas ke sana…"
  },
  AvgDialog_60202_Content_7 = {
    Text = "Ah, Penjaga!"
  },
  AvgDialog_60202_Content_8 = {
    Text = "Di ujung koridor, beberapa anggota Komite sedang membawa hewan peliharaan untuk pencarian, sambil mengamati kelas terdekat."
  },
  AvgDialog_60202_Content_9 = {
    Text = "Sambil mempercepat langkah, kamu mengeluarkan kunci perak."
  },
  AvgDialog_60203_Content_1 = {
    Text = "Para siswa berbakat dari Mythag seharusnya tidak belajar dari para penjahat yang menghalangi tugas resmi."
  },
  AvgDialog_60203_Content_10 = {
    Text = "Jika ada kesempatan, aku berharap bisa mengobrol dengan kalian dengan tenang. Namun, bukan hari ini."
  },
  AvgDialog_60203_Content_11 = {Text = "Ayo mulai."},
  AvgDialog_60203_Content_12 = {Text = "Ya."},
  AvgDialog_60203_Content_13 = {
    Text = "Dia membuat sebuah isyarat."
  },
  AvgDialog_60203_Content_14 = {
    Text = "Agen-agen yang bergerak maju dengan rapat, mempersempit lingkaran pengepungan."
  },
  AvgDialog_60203_Content_15 = {
    Text = "Para Pembangun menggunakan seluruh kekuatan mereka untuk melawan rasa kantuk yang membanjiri. Mata pisaunya yang terletak di leher para siswa membuat mereka tidak berani bergerak sembarangan."
  },
  AvgDialog_60203_Content_16 = {Text = "Bertindak."},
  AvgDialog_60203_Content_17 = {
    Text = "Senjata Komite mengarah ke Pembangun di tengah, dan jari-jari sudah berada di pelatuk."
  },
  AvgDialog_60203_Content_18 = {
    Text = "Menggerakkan Kunci Perak"
  },
  AvgDialog_60203_Content_19 = {Text = "Ding——"},
  AvgDialog_60203_Content_2 = {
    Text = "Pemandangan di penjara tidak seindah di kampus."
  },
  AvgDialog_60203_Content_20 = {
    Text = "Melampaui batas!"
  },
  AvgDialog_60203_Content_21 = {
    Text = "Seiring dengan cahaya perak yang menyilaukan, tak terhitung jumlahnya tentakel muncul dari bawah tanah, menumbangkan para Agen yang sedang menahan siswa-siswa Mythag."
  },
  AvgDialog_60203_Content_22 = {
    Text = "Kamu akhirnya datang."
  },
  AvgDialog_60203_Content_23 = {
    Text = "Kamu ingat dia. Dokter di panti asuhan yang dengan mudah membuat kalian kehilangan kemampuan untuk melawan."
  },
  AvgDialog_60203_Content_24 = {
    Text = "Kamu waspada melihat alat hipnosis di tangannya."
  },
  AvgDialog_60203_Content_25 = {
    Text = "Bertemu lagi, Nona Clementine."
  },
  AvgDialog_60203_Content_26 = {
    Text = "Penjaga! Tulu!"
  },
  AvgDialog_60203_Content_27 = {
    Text = "Tidak terluka, kan?"
  },
  AvgDialog_60203_Content_28 = {
    Text = "Hal kecil, tidak ada apa-apanya!"
  },
  AvgDialog_60203_Content_29 = {
    Text = "Banyak orang berlari masuk ke sekolah, Lily tidak berhasil menahan mereka…"
  },
  AvgDialog_60203_Content_3 = {
    Text = "Wanita sepertimu... tidak ada satu kata pun yang benar! Jangan dengarkan dia, semuanya!"
  },
  AvgDialog_60203_Content_30 = {
    Text = "Jenkin mengusap jejak darah di wajahnya, lalu menundukkan kepalanya."
  },
  AvgDialog_60203_Content_31 = {
    Text = "Kamu dengan lembut menepuk kepala mereka."
  },
  AvgDialog_60203_Content_32 = {
    Text = "Cahaya Kunci Perak berkilauan, energi roh di dalam tubuhmu terus mengalir melalui Kunci Perak, memasuki tubuh Pembangun secara tak terputus."
  },
  AvgDialog_60203_Content_33 = {
    Text = "Kalian telah melakukan dengan baik. Untuk langkah selanjutnya, aku akan menyelesaikannya bersama kalian."
  },
  AvgDialog_60203_Content_34 = {
    Text = "Kamu mengangkat kepala dan melihat ke arah Clementine, serta para Agen Komite yang berdiri di sisinya."
  },
  AvgDialog_60203_Content_35 = {
    Text = "Penjaga {Male=tuan,Female=nyonya}, kamu bukan anak kecil lagi, tolong pertimbangkan dengan baik. Kami adalah petugas resmi, melakukan pencarian di Mythag, ini adalah perintah resmi."
  },
  AvgDialog_60203_Content_36 = {
    Text = "Masuk ke Mythag tanpa izin, menyebabkan kerusakan pada personel Mythag... Saya tidak melihat otoritas resmi, hanya melihat sekelompok perampok."
  },
  AvgDialog_60203_Content_37 = {
    Text = "Aku tidak peduli apa tujuan kalian sebenarnya. Terhadap perampok, Mythag hanya memiliki satu sikap."
  },
  AvgDialog_60203_Content_38 = {
    Text = "Mulai Counter"
  },
  AvgDialog_60203_Content_39 = {
    Text = "Pembangun, berbaris, hadapi musuh!"
  },
  AvgDialog_60203_Content_4 = {
    Text = "Mythag adalah rumahku, aku tidak akan mengizinkan kalian masuk!"
  },
  AvgDialog_60203_Content_5 = {
    Text = "Lily akan melindungi tempat ini!"
  },
  AvgDialog_60203_Content_6 = {
    Text = "Meskipun kemampuan untuk bergerak sudah dibatasi, masih bisa mengucapkan kata-kata yang begitu menyentuh. Sungguh membangkitkan rasa iba."
  },
  AvgDialog_60203_Content_7 = {
    Text = "Dia memandang sekilas beberapa anak Pembangun yang penuh luka di depannya, serta para siswa dan peneliti yang dikendalikan oleh Agen Komite."
  },
  AvgDialog_60203_Content_8 = {
    Text = "Namun, di Mythag ada begitu banyak orang biasa. Dengan hanya beberapa anak kecil seperti kalian, hal yang bisa dilakukan mungkin sangat terbatas."
  },
  AvgDialog_60203_Content_9 = {
    Text = "Kamu! Rendah... tak tahu malu!"
  },
  AvgDialog_60208_Content_1 = {Text = "Konduktor"},
  AvgDialog_60208_Content_10 = {
    Text = "Penjaga Mythag… Saya akhirnya mengerti, mengapa Patung dan Lentera begitu tertarik pada kemampuan tautan Pembangunmu."
  },
  AvgDialog_60208_Content_11 = {
    Text = "Bertemu dengan tergesa-gesa di panti asuhan, sungguh disayangkan tidak sempat berbicara lebih dalam denganmu."
  },
  AvgDialog_60208_Content_12 = {
    Text = "Namun, setelah tertunda begitu lama, seharusnya sudah hampir selesai…"
  },
  AvgDialog_60208_Content_13 = {
    Text = "Clementine dengan lembut menepuk debu dari tubuhnya, pandangannya melewati kamu, menatap jauh ke dalam Mythag."
  },
  AvgDialog_60208_Content_14 = {
    Text = "Dia melihat jam saku di tangannya, sebuah senyuman tipis terukir di sudut bibirnya."
  },
  AvgDialog_60208_Content_15 = {
    Text = "Waktunya telah tiba."
  },
  AvgDialog_60208_Content_17 = {Text = "Ah!——"},
  AvgDialog_60208_Content_18 = {Text = "Ngh..."},
  AvgDialog_60208_Content_19 = {
    Text = "Sepertinya ada ledakan kuat yang meledak di dalam pikiran kalian."
  },
  AvgDialog_60208_Content_2 = {
    Text = "Cokelat, di sini!"
  },
  AvgDialog_60208_Content_20 = {
    Text = "Pembangun yang baru saja penuh semangat tampaknya tiba-tiba mengalami pukulan berat, lalu jatuh berlutut."
  },
  AvgDialog_60208_Content_21 = {
    Text = "Rasa sakit yang tajam menusuk tubuhmu, secara naluriah kamu meraih kursi di sampingmu, dan dengan susah payah berhasil tetap berdiri."
  },
  AvgDialog_60208_Content_22 = {
    Text = "Jenkin! Tulu! Apakah kalian baik-baik saja?"
  },
  AvgDialog_60208_Content_23 = {
    Text = "Aku akan membantu kalian——"
  },
  AvgDialog_60208_Content_24 = {
    Text = "Kamu mencoba mentransmisikan energi rohmu kepada mereka."
  },
  AvgDialog_60208_Content_25 = {Text = "!!!"},
  AvgDialog_60208_Content_26 = {Text = "Ini…"},
  AvgDialog_60208_Content_27 = {
    Text = "Di Dimensi Roh, sosok-sosok yang tadinya familiar tiba-tiba menjadi kabur."
  },
  AvgDialog_60208_Content_28 = {
    Text = "Tautan yang dulunya sangat erat, tampaknya tersumbat oleh sesuatu. Tautan antara kamu dan bayangan-bayangan itu menjadi sangat kabur."
  },
  AvgDialog_60208_Content_29 = {
    Text = "Tautan antara aku dan Pembangun… melemah?"
  },
  AvgDialog_60208_Content_3 = {Text = "Cit cit!"},
  AvgDialog_60208_Content_30 = {
    Text = "Tidak... kau tidak mungkin memiliki Kekuatan seperti ini..."
  },
  AvgDialog_60208_Content_31 = {
    Text = "Kau memikirkan sesuatu, pupilmu tiba-tiba membesar."
  },
  AvgDialog_60208_Content_32 = {
    Text = "Kamu mengangkat kepala, terkejut menatap Clementine. Setetes keringat jatuh dari dahimu."
  },
  AvgDialog_60208_Content_33 = {
    Text = "Ini Kolam Hitam… Ada masalah dengan Kolam Hitam!"
  },
  AvgDialog_60208_Content_34 = {
    Text = "Begitu besar hingar-bingarnya, menarik perhatian kita ke sini. Tujuan sebenarnya adalah di Kolam Hitam…!"
  },
  AvgDialog_60208_Content_35 = {
    Text = "Benar. Kolam Hitam."
  },
  AvgDialog_60208_Content_36 = {
    Text = "Fenomena aneh di Dunia roh, guncangan kuat tersebut, hanya mungkin terkait dengan D-rongga dan Clades."
  },
  AvgDialog_60208_Content_37 = {
    Text = "Kolam Hitam, D-rongga pelarutan paling awal dan paling megah di dunia ini. Itu adalah sumber Kekuatan Perak, dan juga bencana yang paling ditakuti oleh Kekuatan Perak."
  },
  AvgDialog_60208_Content_38 = {
    Text = "Pikiranmu juga sangat mengagumkan, Penjaga {Male=tuan,Female=nyonya}."
  },
  AvgDialog_60208_Content_39 = {
    Text = "Jumlah tautan yang hampir tak terbatas, kekuatan roh yang membangkitkan iri…"
  },
  AvgDialog_60208_Content_4 = {
    Text = "Mengganggu tidurku, aku akan memberikan hukuman."
  },
  AvgDialog_60208_Content_40 = {
    Text = "Kamu memang sangat kuat. Namun, jika kehilangan kekuatan ini, apa yang masih bisa kamu lakukan?"
  },
  AvgDialog_60208_Content_41 = {
    Text = "Kakak {Male=Tuan Penjaga Rahasia,Female=Nona Penjaga Rahasia}, hati-hati!"
  },
  AvgDialog_60208_Content_42 = {
    Text = "Bola hitam berduri muncul di hadapanmu, dan seorang agen Komite yang menyerangmu terbentur lalu terpental."
  },
  AvgDialog_60208_Content_43 = {
    Text = "Bola hitam masih ingin melanjutkan serangan ke depan, tetapi setelah bergerak sejauh sedikit, bola itu langsung hancur."
  },
  AvgDialog_60208_Content_44 = {
    Text = "Lily tidak bisa bertahan lebih lama lagi, tubuhnya gemetar karena rasa sakit."
  },
  AvgDialog_60208_Content_45 = {
    Text = "Kamu menyapu pandanganmu ke sekeliling. Jenkin, Tulu, Lily… karena melemahnya Tautan, para Pembangun ini mulai menunjukkan tanda-tanda awal kehilangan kendali."
  },
  AvgDialog_60208_Content_46 = {
    Text = "Tidak bisa, harus mencari cara lain…"
  },
  AvgDialog_60208_Content_47 = {
    Text = "Aku punya ide... Brown!"
  },
  AvgDialog_60208_Content_48 = {Text = "Cit cit!"},
  AvgDialog_60208_Content_49 = {
    Text = "Cicit——Cicit——"
  },
  AvgDialog_60208_Content_5 = {
    Text = "Beberapa tentakel raksasa mengayun, menjatuhkan beberapa Agen yang mencoba melanjutkan serangan mereka."
  },
  AvgDialog_60208_Content_50 = {
    Text = "Apa... apa itu tikus?!"
  },
  AvgDialog_60208_Content_51 = {
    Text = "Tak terhitung banyaknya suara tikus yang membuat gigi ngilu terdengar."
  },
  AvgDialog_60208_Content_52 = {
    Text = "Koridor, saluran air, semak-semak… tak terhitung banyaknya tikus berlarian keluar dari segala arah, memenuhi lapangan dengan sangat padat."
  },
  AvgDialog_60208_Content_53 = {
    Text = "Cokelat memimpin gerombolan tikus, langsung menyerbu para Agen dari Komite."
  },
  AvgDialog_60208_Content_54 = {
    Text = "Penjaga, sekarang!"
  },
  AvgDialog_60208_Content_55 = {
    Text = "Mata! Mataku!"
  },
  AvgDialog_60208_Content_56 = {
    Text = "Pergi! Pergi!"
  },
  AvgDialog_60208_Content_57 = {
    Text = "Gerombolan tikus seperti gelombang pasang, menenggelamkan kerumunan di lapangan, menenggelamkan Cokelat."
  },
  AvgDialog_60208_Content_58 = {
    Text = "Tikus-tikus itu tidak takut mati. Tikus-tikus itu sangat lemah dan mudah dikalahkan. Gelombang tikus akhirnya surut, meninggalkan banyak mayat tikus di tanah."
  },
  AvgDialog_60208_Content_59 = {
    Text = "Pandangan Clementine menembus kekacauan di tanah, tak lagi melihat bayanganmu dan para Pembangun."
  },
  AvgDialog_60208_Content_6 = {
    Text = "Di atas alun-alun Mythag, para agen dari Komite terbaring seperti rerumputan kering di tanah."
  },
  AvgDialog_60208_Content_7 = {
    Text = "Agen yang tersisa mengelilingi kalian, tidak berani bertindak sembarangan."
  },
  AvgDialog_60208_Content_8 = {
    Text = "Menyerahlah, Clemetine, perintahkan Agenmu untuk mundur dan jangan mengganggu staf serta siswa di Mythag lagi."
  },
  AvgDialog_60208_Content_9 = {
    Text = "Pihak sekolah akan memberikanmu penyelesaian yang tepat."
  },
  AvgDialog_60209_Content_1 = {
    Text = "Peraturan sekolah"
  },
  AvgDialog_60209_Content_10 = {
    Text = "Hem... hem hem..."
  },
  AvgDialog_60209_Content_11 = {Text = "Guru!"},
  AvgDialog_60209_Content_12 = {
    Text = "Kursi roda bergetar. Kamu maju untuk menopang Alistair."
  },
  AvgDialog_60209_Content_13 = {
    Text = "Kalimat sederhana itu tampaknya telah menguras habis Roh-nya, membuat Tubuh-nya yang sudah cacat menjadi semakin lemah."
  },
  AvgDialog_60209_Content_14 = {
    Text = "Guru, hal-hal ini... bagaimana Anda bisa mengetahuinya?"
  },
  AvgDialog_60209_Content_15 = {
    Text = "Alistair memutar kursi rodanya ke arah jendela. Kamu mengikuti pandangannya, bersama-sama menatap titik cahaya di dalam Kolam Hitam."
  },
  AvgDialog_60209_Content_16 = {
    Text = "Tubuh Intelektual mengajarkan banyak pengetahuan kepada Tawil. Pengetahuan itu tidak tercatat dalam bentuk tulisan apa pun, karena jika dituliskan, akan mendatangkan bencana tanpa akhir."
  },
  AvgDialog_60209_Content_17 = {
    Text = "Yang tertinggal di Kolam Hitam adalah sebuah cangkang kosong yang sedang tidur. Kesadaran-Nya tidak berada di sini, atau lebih tepatnya, tidak berada di dimensi ini, pada waktu ini…"
  },
  AvgDialog_60209_Content_18 = {
    Text = "Ketika Dia sadar, Dia memberi tahu aku tentang pengetahuan ini... keukh keukh..."
  },
  AvgDialog_60209_Content_19 = {
    Text = "Tawil tidak berada di dimensi ini… Apakah Dia sedang menghindari sesuatu?"
  },
  AvgDialog_60209_Content_2 = {
    Text = "Bencana dari luar dunia? Guru, saya kurang mengerti…"
  },
  AvgDialog_60209_Content_20 = {
    Text = "Thais juga pernah memberitahuku, Dia sedang melarikan diri dari sebuah \"krisis akhir\"…"
  },
  AvgDialog_60209_Content_21 = {
    Text = "Apakah bencana ada hubungannya dengan keberadaan tertinggi?"
  },
  AvgDialog_60209_Content_22 = {
    Text = "Apakah ini bencana dari luar dunia yang Anda sebutkan tadi? Bahkan dua pelaku dari kedua massa itu merasa sangat takut."
  },
  AvgDialog_60209_Content_23 = {
    Text = "Apakah bencana ini ada hubungannya dengan keberadaan tertinggi itu?"
  },
  AvgDialog_60209_Content_24 = {
    Text = "Alistair memandangmu dengan pujian, lalu tersenyum dan mengangguk."
  },
  AvgDialog_60209_Content_25 = {
    Text = "Kamu sangat tajam, %player%, itu bagus."
  },
  AvgDialog_60209_Content_26 = {
    Text = "Ketajaman adalah kualitas yang sangat berharga bagi seorang Penjaga."
  },
  AvgDialog_60209_Content_27 = {
    Text = "Kamu benar. Mereka sedang merasa takut."
  },
  AvgDialog_60209_Content_28 = {
    Text = "Alistair duduk tegak, ekspresi di wajahnya berubah menjadi serius."
  },
  AvgDialog_60209_Content_29 = {
    Text = "Makhluk tertinggi itu, Tawil menyebut-Nya sebagai Kehendak Tertinggi…"
  },
  AvgDialog_60209_Content_3 = {
    Text = "Kamu menatap sisa-sisa Pohon ibu di atas meja. Setelah kembali dari gurun, ia tergeletak di atas meja Alistair, seperti sebuah perumpamaan yang buruk."
  },
  AvgDialog_60209_Content_30 = {
    Text = "Dia adalah satu-satunya penguasa di antara tak terhitung alam semesta. Tiga esensi utama lahir dari-Nya. Dia menciptakan segalanya, menguasai segalanya, dan membawa Kehancuran kepada segalanya."
  },
  AvgDialog_60209_Content_31 = {
    Text = "Dia, adalah Sumber dari semua Clades."
  },
  AvgDialog_60209_Content_32 = {
    Text = "Sumber semua Clades… Apakah yang Anda maksud…!"
  },
  AvgDialog_60209_Content_33 = {
    Text = "Benar. Hal yang selalu ingin kita pahami dan ingin kita kalahkan — Pelarutan."
  },
  AvgDialog_60209_Content_34 = {
    Text = "Apa hubungan antara Pelarutan dan Kehendak Tertinggi?"
  },
  AvgDialog_60209_Content_35 = {
    Text = "Tawil tidak memberi tahu saya. Mungkin, Tubuh intelektual menyembunyikan sesuatu dari-Nya."
  },
  AvgDialog_60209_Content_36 = {
    Text = "Kami memiliki sebuah dugaan bahwa Kehendak Tertinggi itu berkaitan dengan…"
  },
  AvgDialog_60209_Content_37 = {
    Text = "Alistair menatapmu. Tiba-tiba, alisnya berkerut dengan kuat."
  },
  AvgDialog_60209_Content_38 = {Text = "Guru?"},
  AvgDialog_60209_Content_39 = {
    Text = "Sebuah firasat kuat, seperti hari ketika Akut meledak. Firasat yang sangat tidak menguntungkan…"
  },
  AvgDialog_60209_Content_4 = {
    Text = "Alistair lama tidak menjawab. Dia menghadap ke arah Kolam Hitam yang kosong di luar jendela, tampaknya ada beberapa gagasan yang bertentangan sedang berjuang di dalam pikirannya."
  },
  AvgDialog_60209_Content_40 = {
    Text = "Bersiaplah, %player%. Mungkin, sebentar lagi akan ada hal besar yang terjadi."
  },
  AvgDialog_60209_Content_41 = {
    Text = "Sebuah peristiwa yang tak pernah kita bayangkan, yang membuat semua orang merasa takut dan menderita…"
  },
  AvgDialog_60209_Content_42 = {
    Text = "Dung dung dung——"
  },
  AvgDialog_60209_Content_43 = {
    Text = "Sebelum Alistair selesai berbicara, terdengar ketukan mendesak dari luar ruang penelitian bawah tanah."
  },
  AvgDialog_60209_Content_44 = {
    Text = "Alistair mengerutkan alisnya sambil berpikir. Dengan wajah penuh kebingungan, kamu membuka pintu."
  },
  AvgDialog_60209_Content_45 = {
    Text = "Ada... ada masalah!"
  },
  AvgDialog_60209_Content_46 = {
    Text = "Hanna? Bagaimana kamu bisa sampai di tempat ini?"
  },
  AvgDialog_60209_Content_47 = {
    Text = "Di sini dekat dengan Kolam Hitam, sangat berbahaya, hanya mereka yang memiliki Lewati khusus yang bisa…"
  },
  AvgDialog_60209_Content_48 = {
    Text = "Sebelum kamu selesai berbicara, Hanna menarikmu dan berlari menuju luar ruang penelitian bawah tanah."
  },
  AvgDialog_60209_Content_49 = {
    Text = "Hei! Hannah, apa sebenarnya…"
  },
  AvgDialog_60209_Content_5 = {
    Text = "Kamu sudah berinteraksi dengan para pelaku dari Tiga Besar Badan. Menurutku, sudah waktunya aku memberitahumu beberapa hal."
  },
  AvgDialog_60209_Content_50 = {
    Text = "Komite… Komite akan menyerbu sekolah!"
  },
  AvgDialog_60209_Content_51 = {Text = "!!!"},
  AvgDialog_60209_Content_6 = {
    Text = "Melihat tatapan Alistair, kamu dengan cekatan melangkah maju, memegang kursi roda Alistair, dan mendorongnya ke sisi meja."
  },
  AvgDialog_60209_Content_7 = {
    Text = "Mengenai Trinitas, sejauh mana kamu memahaminya sekarang?"
  },
  AvgDialog_60209_Content_8 = {
    Text = "Tidak sedikit. Aku tahu mereka masing-masing menguasai otoritas pengetahuan, keinginan, dan kesenangan, memiliki kekuatan luar biasa yang tak terbayangkan oleh kita, dan merupakan Dewa-Dewa paling kuat di alam semesta ini…"
  },
  AvgDialog_60209_Content_9 = {
    Text = "Tidak, %player%, di atas tiga besar plasmon, ada seorang yang tertinggi……"
  },
  AvgDialog_60210_Content_1 = {
    Text = "Tubuh yang cacat"
  },
  AvgDialog_60210_Content_10 = {
    Text = "Namun, baik dari segi nilai sebagai sandera maupun tingkat ketidaknyamanan dalam bergerak, ada seseorang yang lebih membutuhkan perlindunganmu dibandingkan denganku."
  },
  AvgDialog_60210_Content_100 = {
    Text = "Itu akan melapor! Hentikan dia!"
  },
  AvgDialog_60210_Content_11 = {
    Text = "Saya mengerti, Dekan. Setelah Anda tiba di zona aman, saya akan segera mencari Profesor Alistair."
  },
  AvgDialog_60210_Content_12 = {
    Text = "Pandangan ketiga orang itu serempak mengarah ke belakang, celah misterius dan berbahaya itu bagaikan mulut raksasa hitam milik siluman rakus, seolah-olah mampu menelan seluruh Mythag dalam sekali lahap."
  },
  AvgDialog_60210_Content_13 = {
    Text = "Semoga Alistair selamat…"
  },
  AvgDialog_60210_Content_14 = {
    Text = "Teh hitam yang diseduh pagi ini. Apakah kamu mau minum?"
  },
  AvgDialog_60210_Content_15 = {
    Text = "Bagi seorang penyandang disabilitas tanpa tangan dan kaki, mengonsumsi materi selain untuk mempertahankan tanda-tanda hidup hanya akan menambah masalah saja."
  },
  AvgDialog_60210_Content_16 = {
    Text = "Saya tidak ingin mengganggu diri sendiri, apalagi mengganggu orang lain. Silakan sesuka Anda, Profesor Boneka."
  },
  AvgDialog_60210_Content_17 = {
    Text = "Boneka meniupkan udara ke cangkir teh, lalu perlahan menyeruputnya."
  },
  AvgDialog_60210_Content_18 = {
    Text = "Air kolam berwarna hitam memasuki ruang penelitian bawah tanah, bergulung-gulung dengan berbahaya di bawah kaki mereka, seperti irama aneh di tengah acara minum teh."
  },
  AvgDialog_60210_Content_19 = {
    Text = "Iri? Tubuh ini bahkan dilengkapi dengan sensor bau, cukup untuk merasakan sensasi teh hitam hangat yang bergerak di ujung lidah."
  },
  AvgDialog_60210_Content_2 = {
    Text = "Ramona diam-diam mengintip, memeriksa Lorong pelarian dengan cermat."
  },
  AvgDialog_60210_Content_20 = {
    Text = "Lebih dari iri pada kemampuanmu untuk menyeruput teh merah yang harum, aku lebih iri pada kenyamananmu untuk bisa berpindah ke Tubuh buatan lain kapan saja."
  },
  AvgDialog_60210_Content_21 = {
    Text = "Sangat disayangkan, tubuh buatan tidak dapat menampung kekuatan rohmu. Menikmati keunggulan dari bakat luar biasa akan membawa konsekuensi luar biasa pula."
  },
  AvgDialog_60210_Content_22 = {
    Text = "Boneka meletakkan cangkir tehnya, lalu menatap Alistair."
  },
  AvgDialog_60210_Content_23 = {
    Text = "Profesor Alistair, apakah Anda bisa merasakan siapa itu?"
  },
  AvgDialog_60210_Content_24 = {
    Text = "Maksudmu, pengkhianat di dalam Mythag?"
  },
  AvgDialog_60210_Content_25 = {
    Text = "Tidak salah. Kabut ekstra di Mythag diciptakan oleh pendiri sekolah bersama dengan Tawil, dan keberadaan Kolam Hitam juga merupakan rahasia yang tidak dapat dipahami oleh orang biasa."
  },
  AvgDialog_60210_Content_26 = {
    Text = "Membubarkan kabut, meledakkan kolam hitam, orang yang mampu melakukan hal ini mungkin bisa dihitung dengan jari."
  },
  AvgDialog_60210_Content_27 = {
    Text = "Saya telah mengunci beberapa orang. Namun, hanya dengan informasi yang tersedia saat ini, akan sulit untuk mempersempit ruang lingkup lebih lanjut."
  },
  AvgDialog_60210_Content_28 = {
    Text = "Apakah saya juga termasuk orang yang terkunci?"
  },
  AvgDialog_60210_Content_29 = {
    Text = "Alistair sedikit menengadahkan kepalanya, cahaya yang ambigu berkilauan di dasar matanya."
  },
  AvgDialog_60210_Content_3 = {
    Text = "Di sini tidak ada orang dari Komite, ikuti jalan ini."
  },
  AvgDialog_60210_Content_30 = {
    Text = "Kamu adalah yang pertama."
  },
  AvgDialog_60210_Content_31 = {
    Text = "Boneka menyesap sedikit teh merah, asap yang berkeliling menutupi ekspresinya. Suasana di dalam ruang penelitian tiba-tiba membeku."
  },
  AvgDialog_60210_Content_32 = {
    Text = "Namun, sudah dikecualikan."
  },
  AvgDialog_60210_Content_33 = {
    Text = "Bukan kamu, kamu adalah \"inti\" dari Mythag. Ada lebih banyak cara untuk menghancurkan Mythag, tidak perlu repot-repot seperti ini."
  },
  AvgDialog_60210_Content_34 = {
    Text = "Dalam kekacauan ini, pengkhianat ini memainkan peran yang paling berbahaya."
  },
  AvgDialog_60210_Content_35 = {
    Text = [[
Kemampuanku tidak cocok untuk medan perang langsung. 
Menemukan mata-mata ini adalah tugasku. Aku membutuhkan pendapatmu.]]
  },
  AvgDialog_60210_Content_36 = {
    Text = "Sangat disayangkan, Profesor Boneka. Mengenai teman pengkhianat ini, saya tidak memiliki sedikit pun firasat."
  },
  AvgDialog_60210_Content_37 = {
    Text = "Ini seharusnya tidak terjadi. Seluruh Mythag, setiap getaran dari Perak, secara teori berada dalam domainmu."
  },
  AvgDialog_60210_Content_38 = {
    Text = [[
Memang benar. 
Dia tidak berada dalam jangkauan persepsi saya.]]
  },
  AvgDialog_60210_Content_39 = {
    Text = "Apakah ini berarti dia memiliki Kemampuan untuk melarikan diri dari persepsimu?"
  },
  AvgDialog_60210_Content_4 = {
    Text = "Dia berbalik dan memegang lengan Czort."
  },
  AvgDialog_60210_Content_40 = {
    Text = "Ada kemungkinan lainnya juga."
  },
  AvgDialog_60210_Content_41 = {
    Text = "Boneka terdiam selama beberapa saat, seolah-olah mengaitkannya dengan sesuatu."
  },
  AvgDialog_60210_Content_42 = {
    Text = "Saya mengerti. Ini akan menjadi arah pemikiran baru."
  },
  AvgDialog_60210_Content_43 = {
    Text = "Alistair mengangguk, menutup mata, lalu menghirup aroma wangi yang mengepul dari cangkir teh di depannya dan menghela napas dengan puas."
  },
  AvgDialog_60210_Content_44 = {
    Text = "Suasana hatimu tampaknya cukup santai. Mungkin sekarang seluruh Mythag sedang mengkhawatirkanmu."
  },
  AvgDialog_60210_Content_45 = {
    Text = "Saya adalah orang yang paling tidak perlu dikhawatirkan."
  },
  AvgDialog_60210_Content_46 = {
    Text = "Boneka menatap Alistair, dengan sedikit rasa iba tersirat di wajahnya yang tenang."
  },
  AvgDialog_60210_Content_47 = {
    Text = "Dari wajahmu, aku sama sekali tidak melihat ketidaknyamanan apa pun. Keteguhan hatimu sungguh mengagumkan."
  },
  AvgDialog_60210_Content_48 = {
    Text = "... Apakah rasa sakit yang kau tanggung sekarang sudah melampaui batas imajinasi kita, Profesor Alistair?"
  },
  AvgDialog_60210_Content_49 = {
    Text = "Aku... batuk-batuk..."
  },
  AvgDialog_60210_Content_5 = {
    Text = "Ramona, aku akan mengawal Dekan Czort saja. Ada masalah di Kolam Hitam, kondisimu saat ini juga tidak terlalu baik…"
  },
  AvgDialog_60210_Content_50 = {
    Text = "Alistair batuk hebat beberapa kali, kursi rodanya menabrak meja, teh tumpah dari cangkir dan jatuh ke dalam Kolam Hitam, lalu menghilang."
  },
  AvgDialog_60210_Content_51 = {
    Text = "Kolam Hitam meledak, kamu adalah orang yang paling dekat dengan Kolam Hitam, dan juga yang paling terpengaruh oleh getaran dari Kolam Hitam."
  },
  AvgDialog_60210_Content_52 = {
    Text = "Jika tidak meninggalkan tempat ini, tubuhmu tidak akan kuat menahan."
  },
  AvgDialog_60210_Content_53 = {
    Text = "Orang yang terkenal karena keberanian rasionalnya, tidak pantas mengucapkan kata-kata penuh emosi seperti ini."
  },
  AvgDialog_60210_Content_54 = {
    Text = "Nada bodoh yang kamu tunjukkan terdengar sangat kaku, Profesor Boneka."
  },
  AvgDialog_60210_Content_55 = {
    Text = "Alistair tertawa sambil menggelengkan kepalanya."
  },
  AvgDialog_60210_Content_56 = {
    Text = "Saat aku pergi, Kolam Hitam akan sepenuhnya kehilangan kendali. Pada saat itu, yang hancur bukan hanya Mythag."
  },
  AvgDialog_60210_Content_57 = {
    Text = "Boneka dengan jelas mendengar suara lembut Alistair mulai bergetar tak terkendali. Itu adalah penderitaan yang berasal dari kedalaman Roh, yang tidak bisa disembunyikan."
  },
  AvgDialog_60210_Content_58 = {
    Text = "Kata-kata perhatian selalu harus diucapkan."
  },
  AvgDialog_60210_Content_59 = {
    Text = "Selain etika yang tidak berguna ini, untuk sementara saya tidak dapat memikirkan cara lain untuk menunjukkan rasa hormat saya kepada seorang manusia."
  },
  AvgDialog_60210_Content_6 = {
    Text = "Orang-orang dari Komite bisa melukai Dekan czort, maka mereka bisa melakukan hal-hal yang lebih gila."
  },
  AvgDialog_60210_Content_60 = {
    Text = "Mendengar kata-kata seperti itu dari mulutmu bukanlah hal yang mudah. Ini adalah sebuah kehormatan bagiku."
  },
  AvgDialog_60210_Content_61 = {
    Text = "Orang yang bisa membantu saya, mungkin sedang dalam perjalanan. Tolong jangan khawatirkan saya."
  },
  AvgDialog_60210_Content_62 = {
    Text = [[
Ada tempat lain yang membutuhkanmu. Pergilah dari sini, Profesor Boneka. 
Di Kolam Hitam, satu orang tua sudah cukup.]]
  },
  AvgDialog_60210_Content_63 = {
    Text = "Boneka menutup matanya dan menghela napas. Tanpa berkata apa-apa lagi, dia meninggalkan ruang penelitian bawah tanah."
  },
  AvgDialog_60210_Content_64 = {
    Text = "Di belakangnya, Penjaga pertama Mythag duduk di kursi roda, dengan tenang menatap titik cahaya redup di Kolam Hitam."
  },
  AvgDialog_60210_Content_65 = {
    Text = "Tubuhnya yang tersisa bergetar lemah, keringat dan darah meresap dari perban, menetes, lalu bercampur ke dalam air kolam mendidih di bawah kakinya."
  },
  AvgDialog_60210_Content_66 = {
    Text = "Di kedalaman Roh yang tak terlihat, di Dimensi semu yang penuh bahaya, Alistair menghadapi Kolam Hitam seorang diri."
  },
  AvgDialog_60210_Content_68 = {
    Text = "Pemimpin Gereja Penerang Kuil? Juliette?! Sisah—"
  },
  AvgDialog_60210_Content_69 = {
    Text = [[
Tetap tenang. Semakin dekat dengan Kolam Hitam, semakin besar tekanan yang akan kamu rasakan secara Roh. 
Jika fluktuasi emosi terlalu kuat, suara musikku pun tidak dapat menekan penderitaanmu.]]
  },
  AvgDialog_60210_Content_7 = {
    Text = "Apapun tujuan mereka, baik itu menculik sandera atau lainnya, kalian membutuhkan orang dengan kemampuan pertempuran untuk mengawal."
  },
  AvgDialog_60210_Content_70 = {
    Text = "Para pematung, Pelaut… orang-orang ini…"
  },
  AvgDialog_60210_Content_71 = {
    Text = "Apa kamu terkejut? Di antara mereka memang sudah ada banyak hubungan yang rumit."
  },
  AvgDialog_60210_Content_72 = {
    Text = "Perubahan abnormal yang disebut Pelarutan menghubungkan mereka, mengelilingi penyebaran wabah hitam, dan membentuk jaringan padat yang melingkupi seluruh Kadath."
  },
  AvgDialog_60210_Content_73 = {
    Text = "Mythag mengejar kebenaran pelarutan dan keberlangsungan manusia, pada dasarnya adalah penentang pelarutan, dan tidak dapat berdamai dengan lentera yang berusaha menyebarkan pelarutan."
  },
  AvgDialog_60210_Content_74 = {
    Text = "Para pematung berharap untuk melampaui pelarutan dengan kekuatan individu, mengabaikan semua tatanan masyarakat manusia di bawahnya. Bahan dan sumber penelitian yang bisa disediakan oleh Gereja Penerang Kuil jauh lebih unggul daripada yang lainnya — kemungkinan besar, pelarian Herbert tidak terlepas dari hal ini."
  },
  AvgDialog_60210_Content_75 = {
    Text = "Adapun Pelaut, mereka hanyalah sekumpulan orang bodoh yang Roh mereka masih hidup di era lama."
  },
  AvgDialog_60210_Content_76 = {
    Text = "Keinginan adalah kelemahan. Bagi Juliette, memanipulasi kelompok ini hanyalah hal yang bisa dilakukan dengan mudah."
  },
  AvgDialog_60210_Content_77 = {
    Text = "Kamu tahu terlalu banyak."
  },
  AvgDialog_60210_Content_78 = {
    Text = "Tidak mengherankan. Kamu di masa lalu hanya belum mendapatkan \"izin\"."
  },
  AvgDialog_60210_Content_79 = {
    Text = "Informasi-informasi ini, kecuali kenaikan tak terduga Juliette dalam beberapa tahun terakhir, sisanya hanyalah bahan obrolan ringan setelah makan."
  },
  AvgDialog_60210_Content_8 = {
    Text = "Tenang saja, Profesor Sylvia. Saya tidak terlalu yakin dengan alasannya, tapi sepertinya fluktuasi Kolam Hitam tidak memengaruhi fungsi pertempuran saya."
  },
  AvgDialog_60210_Content_80 = {
    Text = "Tak disangka, ternyata dia yang merencanakan semua ini dari belakang… Jadi, Komite, mata-mata di Mythag, semuanya ada hubungannya dengan Gereja Penerang Kuil?"
  },
  AvgDialog_60210_Content_81 = {
    Text = "Hameln mengangguk pelan, sarung tangan putih dan tongkat konduktor tersembunyi di belakangnya, seperti pedang yang siap melancarkan serangan mematikan kapan saja."
  },
  AvgDialog_60210_Content_82 = {
    Text = "Seorang petinggi Komite, adalah orang yang ditempatkan oleh Juliette. Kekuatan yang dapat dia kendalikan sekarang kemungkinan besar sudah sepenuhnya terkonsentrasi di Mythag."
  },
  AvgDialog_60210_Content_83 = {
    Text = "Apakah kamu tahu siapa pengkhianat di Mythag?"
  },
  AvgDialog_60210_Content_84 = {
    Text = "Juliette dan dia memiliki hubungan linier, tidak ada yang tahu secara pasti siapa dia kecuali mereka sendiri."
  },
  AvgDialog_60210_Content_85 = {
    Text = "Bahkan kamu juga tidak tahu, sepertinya mencari pengkhianat ini akan menjadi hal yang rumit…"
  },
  AvgDialog_60210_Content_86 = {
    Text = "Apa tujuannya sebenarnya?"
  },
  AvgDialog_60210_Content_87 = {
    Text = "Apa tujuan sebenarnya Juliette begitu gegabah masuk ke Mythag?"
  },
  AvgDialog_60210_Content_88 = {
    Text = "Berapa banyak yang kamu ketahui tentang Rencana Kembar dari Gereja Penerang Kuil?"
  },
  AvgDialog_60210_Content_89 = {
    Text = "Hameln tidak langsung menjawab pertanyaanmu, melainkan mengajukan sebuah pertanyaan balik."
  },
  AvgDialog_60210_Content_9 = {
    Text = "Logikamu tidak ada masalah, Ramona."
  },
  AvgDialog_60210_Content_90 = {
    Text = "Pandangan dinginnya yang tajam menusukmu seperti pedang. Kamu mengerutkan alis dan berusaha keras untuk mengingat."
  },
  AvgDialog_60210_Content_91 = {
    Text = "Sebelumnya, saat berinteraksi dengan Lily dan Helot, saya sudah sedikit memahami."
  },
  AvgDialog_60210_Content_92 = {
    Text = "Mereka menyebut dua Pembangun yang berasal dari sumber yang sama sebagai \"Kembar Lentera\", mungkin dengan cara ini mereka ingin memanggil sesuatu……"
  },
  AvgDialog_60210_Content_93 = {
    Text = "Gereja Penerang Kuil percaya bahwa dengan menggabungkan dua Pembangun, mereka dapat menjadi wadah yang mampu menampung esensi ilahi."
  },
  AvgDialog_60210_Content_94 = {
    Text = "Mereka ingin menggunakan cara seperti ini untuk menciptakan Dewa."
  },
  AvgDialog_60210_Content_95 = {
    Text = "Menciptakan Dewa... Tapi, apa hubungannya dengan Mythag?"
  },
  AvgDialog_60210_Content_96 = {
    Text = "Karena……"
  },
  AvgDialog_60210_Content_97 = {
    Text = "Hameln tiba-tiba berhenti, pandangan tajamnya tertuju pada sebuah batu nisan di kejauhan."
  },
  AvgDialog_60210_Content_98 = {
    Text = "Di balik tablet batu berbentuk kunci yang berwarna abu-abu, terdengar suara gemerisik."
  },
  AvgDialog_60210_Content_99 = {
    Text = "Adalah anjing berwajah manusia milik Juliette. Hal yang aku bantu untukmu, tidak boleh diketahui oleh Juliette."
  },
  AvgDialog_60212_Content_1 = {
    Text = "Gladi bersih"
  },
  AvgDialog_60212_Content_10 = {
    Text = "Tidak disangka, Mythag dan Komite akan tertarik pada saya."
  },
  AvgDialog_60212_Content_11 = {
    Text = "Dalam penyelidikan kami, kami menemukan bahwa jejak turmu sangat bertepatan dengan aktivitas Gereja Penerang Kuil."
  },
  AvgDialog_60212_Content_12 = {
    Text = "Kamu waspada memandang Pembangun di depanmu."
  },
  AvgDialog_60212_Content_13 = {
    Text = "Kamu telah menyelamatkan aku dan Pembangun, aku sangat berterima kasih atas hal itu. Namun, saat ini Mythag sedang menghadapi krisis, aku harap kamu bisa memaafkan kewaspadaanku."
  },
  AvgDialog_60212_Content_14 = {
    Text = "Di jalan, saya bertanya bagaimana kamu bisa masuk ke Mythag, dan apa tujuanmu datang ke sini. Sekarang, kamu bisa menjawab saya."
  },
  AvgDialog_60212_Content_15 = {
    Text = "Apakah Pembangunmu sudah diselesaikan?"
  },
  AvgDialog_60212_Content_16 = {
    Text = "...Saya telah mengirim sebagian besar Pembangun ke dekat Kolam hitam. Hanya menyisakan beberapa di sini."
  },
  AvgDialog_60212_Content_17 = {
    Text = "Bagaimana pemulihan Tautan?"
  },
  AvgDialog_60212_Content_19 = {
    Text = "Berkat bantuan suara musikmu, tautan antara aku dan para Pembangun ini berhasil dipulihkan."
  },
  AvgDialog_60212_Content_2 = {
    Text = "Sudah tiba."
  },
  AvgDialog_60212_Content_20 = {
    Text = "Kondisimu istimewa, aku hanya bisa membuatmu mempertahankan Tautan dengan sejumlah kecil Pembangun. Seharusnya ini sudah cukup."
  },
  AvgDialog_60212_Content_21 = {
    Text = "Dia mengangkat tongkat konduktornya dengan lembut."
  },
  AvgDialog_60212_Content_22 = {
    Text = "Sekarang, serang aku."
  },
  AvgDialog_60212_Content_23 = {Text = "???"},
  AvgDialog_60212_Content_24 = {
    Text = "Apa katamu?"
  },
  AvgDialog_60212_Content_25 = {
    Text = "Pengucapan bahasa Leo saya seharusnya tidak ada masalah."
  },
  AvgDialog_60212_Content_26 = {
    Text = "Saya mendengarnya, maksud saya…"
  },
  AvgDialog_60212_Content_27 = {
    Text = "Tujuan lain datang ke ruang musik adalah karena terdapat banyak alat musik di sini. Resonansi antara alat-alat musik ini memungkinkan kemampuan saya bekerja dengan lebih baik."
  },
  AvgDialog_60212_Content_28 = {
    Text = "Tidak ingin menyerang, bertahan juga bisa. Persiapkan dirimu."
  },
  AvgDialog_60212_Content_29 = {
    Text = "Sebelum kamu sempat memahami apa yang terjadi, tongkat komando Hameln dengan cekatan menunjuk ke bawah."
  },
  AvgDialog_60212_Content_3 = {
    Text = "Ruang Musik? Apakah tempat ini aman?"
  },
  AvgDialog_60212_Content_30 = {
    Text = "Sebuah suara dawai yang jernih terdengar secara bersamaan di ruang musik dan dalam benakmu."
  },
  AvgDialog_60212_Content_31 = {
    Text = "Pertunjukan dimulai."
  },
  AvgDialog_60212_Content_4 = {
    Text = "Secara fungsional, tempat ini dekat dengan area penyelidikan Komite, sehingga tidak terlalu aman."
  },
  AvgDialog_60212_Content_5 = {
    Text = "Hmm, saya mengerti… Tempat paling berbahaya adalah tempat paling aman. Pemikiran yang sangat bagus."
  },
  AvgDialog_60212_Content_6 = {
    Text = "Kamu berpikir terlalu banyak. Aku di sini karena aku suka berada di tempat yang ada alat musiknya."
  },
  AvgDialog_60212_Content_7 = {
    Text = "...Karena sudah memilih untuk membantu, sebenarnya bisa saja mengikuti dan berbicara dengan lebih santai."
  },
  AvgDialog_60212_Content_8 = {
    Text = "Hameln, saya pernah mendengar tentangmu, konduktor terbaik di dunia saat ini, baru-baru ini sedang melakukan tur di Londinium."
  },
  AvgDialog_60212_Content_9 = {
    Text = "Mythag dan Komite pernah melakukan beberapa penyelidikan terhadapmu. Tak seorang pun menyangka bahwa kamu adalah seorang Pembangun."
  },
  AvgDialog_60213_Content_1 = {
    Text = "Hu... aku masih terluka, Tautan baru saja pulih, apakah perlu seperti ini?"
  },
  AvgDialog_60213_Content_10 = {
    Text = "Hameln berpikir sejenak, lalu menengadah ke arahmu."
  },
  AvgDialog_60213_Content_11 = {
    Text = "Aku pernah mendengar sebuah melodi yang luar biasa, suara itu berasal dari keberadaan yang tertinggi."
  },
  AvgDialog_60213_Content_12 = {
    Text = "Aku datang untuk nada paling sempurna di alam semesta ini."
  },
  AvgDialog_60213_Content_13 = {
    Text = "Tapi, apa hubungannya dengan saya? Nilai pelajaran musik saya tidak terlalu bagus…"
  },
  AvgDialog_60213_Content_14 = {
    Text = "...dan itu tidak ada hubungannya."
  },
  AvgDialog_60213_Content_15 = {
    Text = "Saya tidak terlalu mengerti..."
  },
  AvgDialog_60213_Content_16 = {
    Text = "Sekarang bukan waktunya untuk menjelaskan hal ini. Prioritasmu sekarang adalah bergegas ke Kolam Hitam dan menstabilkannya."
  },
  AvgDialog_60213_Content_17 = {
    Text = "Orang-orang dari Komite sudah pergi jauh, kita bisa berangkat."
  },
  AvgDialog_60213_Content_18 = {
    Text = "Mau ikut bertindak bersama kami?"
  },
  AvgDialog_60213_Content_19 = {
    Text = "Musikku memiliki batasan jarak. Tanpa bantuanku, kamu tidak bisa melakukan apa pun saat ini."
  },
  AvgDialog_60213_Content_2 = {
    Text = "Masih punya tenaga untuk bicara sebanyak ini, tampaknya kemampuanmu sudah pulih dengan baik."
  },
  AvgDialog_60213_Content_20 = {
    Text = "Kamu bisa menolak bantuan saya, tapi saya tidak menyarankan kamu untuk melakukannya."
  },
  AvgDialog_60213_Content_21 = {
    Text = "Pengetahuanku tentangmu sangat terbatas, tetapi sepertinya kamu mengetahui banyak hal……"
  },
  AvgDialog_60213_Content_22 = {
    Text = "Saya tidak suka perasaan diatur oleh orang lain."
  },
  AvgDialog_60213_Content_23 = {
    Text = "Tidak ada yang akan menyukainya. Namun, simfoni ini telah dimulai. Di atas panggung, setiap pemain harus menjalankan tugasnya masing-masing."
  },
  AvgDialog_60213_Content_24 = {
    Text = "Nada fals, absen... satu kesalahan saja akan membuat pertunjukan ini berakhir dalam kehancuran total."
  },
  AvgDialog_60213_Content_25 = {
    Text = "Dia menyimpan tongkat dirigenya dan berjalan keluar dari ruang kelas."
  },
  AvgDialog_60213_Content_26 = {
    Text = "Aku tidak keberatan dengan sikap bermusuhmu terhadapku. Namun, saat ini kau tidak punya pilihan lain."
  },
  AvgDialog_60213_Content_27 = {
    Text = "Apa yang ingin kau ketahui, akan kuungkapkan selama perjalanan. Mari kita berangkat…"
  },
  AvgDialog_60213_Content_28 = {
    Text = "Dia memalingkan kepalanya, dengan sorot mata dingin tersisa mengamati kamu."
  },
  AvgDialog_60213_Content_29 = {
    Text = "…Mata buta."
  },
  AvgDialog_60213_Content_3 = {
    Text = "Kamu mengusap keringat di dahimu, lalu mengerutkan alis sambil menatapnya."
  },
  AvgDialog_60213_Content_4 = {
    Text = "Latihan telah selesai. Pertanyaan tadi, kamu belum menjawab."
  },
  AvgDialog_60213_Content_5 = {
    Text = "Saya sudah memberikan jawabannya kepadamu. Saya tidak memiliki niat buruk terhadapmu."
  },
  AvgDialog_60213_Content_6 = {
    Text = "Kamu muncul di Mythag pada waktu ini tanpa alasan yang jelas, ditambah lagi dengan reaksi Clementine…"
  },
  AvgDialog_60213_Content_7 = {
    Text = "Acara ini tidak mungkin hanya melibatkan Clementine dan Komite. Saya tidak tahu siapa mereka sebenarnya, tetapi kau adalah salah satu dari mereka."
  },
  AvgDialog_60213_Content_8 = {
    Text = "Bisa dikatakan demikian."
  },
  AvgDialog_60213_Content_9 = {
    Text = "Jadi, kenapa membantu saya?"
  },
  AvgDialog_60217_Content_1 = {
    Text = "Kakak {Male=Tuan Penjaga Rahasia,Female=Nona Penjaga Rahasia}, Lily... kepala Lily sangat sakit..."
  },
  AvgDialog_60217_Content_10 = {Text = "Erica?!"},
  AvgDialog_60217_Content_11 = {
    Text = "Erica! Apakah kamu baik-baik saja?"
  },
  AvgDialog_60217_Content_12 = {
    Text = "Mendeteksi personel musuh... mohon menjauh... Penjaga..."
  },
  AvgDialog_60217_Content_13 = {
    Text = "Dia memegang kepalanya dengan kesakitan, suara mekanis tanpa emosi terdengar secara terputus-putus."
  },
  AvgDialog_60217_Content_14 = {
    Text = "Tautanku semakin melemah, Erica. Aku akan membawamu ke Kolam Hitam. Setelah kita sampai di sana, semuanya akan baik-baik saja…"
  },
  AvgDialog_60217_Content_15 = {
    Text = "Kamu mendekatinya, berniat menopang lengannya. Dengan sisa kesadaran terakhirnya, dia mundur ke belakang."
  },
  AvgDialog_60217_Content_16 = {
    Text = "Modifikasi... tidak terkendali... berbahaya, silakan menjauh..."
  },
  AvgDialog_60217_Content_17 = {Text = "Erika?"},
  AvgDialog_60217_Content_18 = {
    Text = "Kamu sepertinya mendengar suara notifikasi mekanis yang samar."
  },
  AvgDialog_60217_Content_19 = {
    Text = "Setelah suara itu, Erica mengangkat kepalanya, dengan mata tanpa Ekspresi menatap lurus ke arahmu."
  },
  AvgDialog_60217_Content_2 = {
    Text = "Yu... Roh Yu juga terpengaruh..."
  },
  AvgDialog_60217_Content_20 = {
    Text = "Mendeteksi personel musuh, memulai prosedur eliminasi."
  },
  AvgDialog_60217_Content_21 = {Text = "Hati-hati!"},
  AvgDialog_60217_Content_3 = {
    Text = "Tautan antara aku dan kalian semakin lemah… Jika terus seperti ini, kalian akan kehilangan kendali…"
  },
  AvgDialog_60217_Content_4 = {
    Text = "Saya memberi tahu Hannah, agar semua Pembangun berkumpul di Kolam Hitam."
  },
  AvgDialog_60217_Content_5 = {
    Text = "Kita juga perlu segera ke sana. Dengan bantuan Guru dan Tawil, kalian bisa stabil untuk sementara."
  },
  AvgDialog_60217_Content_6 = {
    Text = "Selagi orang-orang dari Komite belum mengejar kita, kita duluan…"
  },
  AvgDialog_60217_Content_7 = {
    Text = "Peringatan, mendeteksi personel musuh."
  },
  AvgDialog_60217_Content_8 = {
    Text = "Tingkat bahaya lebih dari 90%. Harap tinggalkan tempat ini, Penjaga."
  },
  AvgDialog_60217_Content_9 = {
    Text = "Di ujung koridor, Erica muncul dengan tubuh yang tidak stabil."
  },
  AvgDialog_60222_Content_1 = {Text = "Erika!"},
  AvgDialog_60222_Content_10 = {
    Text = "Reaksi Erica tadi... dia tidak terpengaruh oleh Kolam Hitam."
  },
  AvgDialog_60222_Content_11 = {
    Text = "Kamu menatap reruntuhan yang tersisa setelah ledakan Erica, sebuah instrumen berbentuk unik tergeletak di antara serpihan setelah ledakan."
  },
  AvgDialog_60222_Content_12 = {
    Text = "Instrumen berbentuk piramida itu tertanam di bagian otak Erica. Meskipun kamu tidak terlalu memahami konstruksi mekanis Erica, kamu tahu dengan jelas bahwa tidak ada instrumen seperti itu di otaknya."
  },
  AvgDialog_60222_Content_13 = {
    Text = "Membongkar Kabut, meledakkan Kolam Hitam, dan mengendalikan Erica…"
  },
  AvgDialog_60222_Content_14 = {
    Text = "Mythag, ada pengkhianat di antara kita."
  },
  AvgDialog_60222_Content_15 = {
    Text = "Siapa itu?! Aku menyuruh Cokelat untuk mengambilnya... uh..."
  },
  AvgDialog_60222_Content_16 = {
    Text = "Rasa sakit yang hebat memutus kata-kata penuh semangat Jenkin."
  },
  AvgDialog_60222_Content_17 = {
    Text = "Sebuah suara langkah kaki terdengar samar-samar dari kejauhan."
  },
  AvgDialog_60222_Content_18 = {
    Text = "Suara ledakan datang dari sana, pergi ke sana!"
  },
  AvgDialog_60222_Content_19 = {
    Text = "Mereka mengejar kita… Kita harus segera meninggalkan tempat ini!"
  },
  AvgDialog_60222_Content_2 = {Text = "Mundur!"},
  AvgDialog_60222_Content_20 = {
    Text = "{Male=Dia,Female=Dia} lari ke sana! Cari!"
  },
  AvgDialog_60222_Content_21 = {
    Text = "Huu……huu……"
  },
  AvgDialog_60222_Content_22 = {
    Text = "Langkah-langkah terburu-buru mendekat dari belakangmu, lalu perlahan menjauh."
  },
  AvgDialog_60222_Content_23 = {
    Text = "Kamu bersembunyi di balik tiang di sisi koridor, lalu mengambil kesempatan untuk bernapas dalam-dalam."
  },
  AvgDialog_60222_Content_24 = {
    Text = "Komite akan segera menemukan tempat ini, harus memikirkan cara... Ah!..."
  },
  AvgDialog_60222_Content_25 = {
    Text = "Kamu memegang kepalamu dengan rasa sakit yang menyiksa."
  },
  AvgDialog_60222_Content_26 = {
    Text = "Sebuah guncangan kuat menyebar di Dimensi Roh, kepalamu terasa sangat sakit, dan kamu hanya bisa berdiri dengan susah payah setelah memegang tiang penyangga."
  },
  AvgDialog_60222_Content_27 = {
    Text = "Pembangun yang mengikuti kamu hampir tidak memiliki tenaga untuk berbicara. Kamu menatap ke arah Kolam Hitam dengan ekspresi berat."
  },
  AvgDialog_60222_Content_28 = {
    Text = "Jika terus seperti ini, baik aku maupun Pembangun tidak akan bisa menahan. Harus mencari cara untuk menghindarinya…"
  },
  AvgDialog_60222_Content_29 = {
    Text = "Tertangkap kau, Penjaga."
  },
  AvgDialog_60222_Content_3 = {Text = "BRAK—"},
  AvgDialog_60222_Content_30 = {Text = "!!!"},
  AvgDialog_60222_Content_31 = {Text = "Minggir"},
  AvgDialog_60222_Content_32 = {
    Text = "Dengan dorongan kuat dari kedua kakimu, kamu menghindar ke samping."
  },
  AvgDialog_60222_Content_33 = {
    Text = "Sebuah pedang ramping jatuh di posisi tempat kamu berada sebelumnya, ujung pedang menyentuh tiang batu, menghasilkan suara yang renyah."
  },
  AvgDialog_60222_Content_34 = {
    Text = "Dampak pada Roh ditambah dengan luka pada Tubuh, ternyata masih bisa memiliki daya reaksi seperti ini."
  },
  AvgDialog_60222_Content_35 = {
    Text = "Penjaga Mythag, sejak menjabat telah menghadapi banyak situasi berbahaya."
  },
  AvgDialog_60222_Content_36 = {
    Text = "Dengan hanya mengandalkan sebilah pedang tipis, mustahil bisa menangkap {Male=dia,Female=dia}."
  },
  AvgDialog_60222_Content_37 = {
    Text = "Gerakanmu sangat cepat, Clementine."
  },
  AvgDialog_60222_Content_38 = {
    Text = "Sambil tetap waspada terhadap alat yang dia gunakan untuk hipnosis, kamu memindai para Agen Komite yang mulai mengelilingimu."
  },
  AvgDialog_60222_Content_39 = {
    Text = "Puluhan agen telah sepenuhnya memblokir setiap rute pelarian yang mungkin kamu gunakan."
  },
  AvgDialog_60222_Content_4 = {Text = "Ukh——"},
  AvgDialog_60222_Content_40 = {
    Text = "Sayang sekali, kali ini waktu terbatas, tidak bisa bercerita panjang dengan Penjaga."
  },
  AvgDialog_60222_Content_41 = {
    Text = "Namun, Penjaga tidak perlu khawatir. Orang-orang saya akan membawa Anda ke tempat yang aman, dan segera, kita akan memiliki cukup waktu untuk berbincang."
  },
  AvgDialog_60222_Content_42 = {
    Text = "Clementine melambaikan tangan."
  },
  AvgDialog_60222_Content_43 = {
    Text = "Melihat para Agen yang mulai mengelilingimu, jantungmu mulai berdetak kencang tak terkendali."
  },
  AvgDialog_60222_Content_44 = {
    Text = "Jika mereka menangkap kita sekarang dan Pembangun Mythag kehilangan kendali..."
  },
  AvgDialog_60222_Content_45 = {
    Text = "Tidak, aku tidak bisa membiarkan hal seperti ini terjadi…"
  },
  AvgDialog_60222_Content_46 = {
    Text = "Meskipun Kolam Hitam kehilangan kendali, meskipun Tautan dengan Pembangun melemah, pasti akan ada cara…"
  },
  AvgDialog_60222_Content_47 = {
    Text = "Kamu melangkah perlahan ke arah belakang menuju sudut mati, sambil erat memegang kunci perak di tangan dan menutupi luka yang ditinggalkan oleh ledakan Erica."
  },
  AvgDialog_60222_Content_48 = {
    Text = "Gelombang demi gelombang guncangan menghantam Rohmu, kamu bisa merasakan pergolakan di Kolam Hitam."
  },
  AvgDialog_60222_Content_49 = {
    Text = "Titik-titik cahaya yang pernah bersinar di dunia rohmu, melambangkan pembangun, kini telah menjadi sangat redup, bahkan menghilang dari dunia roh."
  },
  AvgDialog_60222_Content_5 = {
    Text = "Tulu mengulurkan tentakelnya, menarikmu keluar dari ledakan yang sangat kuat."
  },
  AvgDialog_60222_Content_50 = {
    Text = "Penjaga yang kehilangan Pembangun tidak bisa berbuat apa-apa."
  },
  AvgDialog_60222_Content_51 = {
    Text = "Tenang, berpikir…"
  },
  AvgDialog_60222_Content_52 = {
    Text = "Pasti... pasti ada cara lain..."
  },
  AvgDialog_60222_Content_53 = {
    Text = "Tenang, %player%. Tenang…"
  },
  AvgDialog_60222_Content_54 = {
    Text = "Asalkan bisa menggunakan cukup kekuatan roh untuk menggerakkan kunci perak, Pembangun di sekitar dapat memperoleh kembali kemampuan tempur yang kuat…"
  },
  AvgDialog_60222_Content_55 = {
    Text = "Benar, kamu tahu caranya. Kamu selalu tahu."
  },
  AvgDialog_60222_Content_56 = {
    Text = "Namun, dengan kondisi Rohmu saat ini, memaksa untuk mengaktifkan Pembangun akan menyebabkan kerusakan irreversibel seperti apa?"
  },
  AvgDialog_60222_Content_57 = {
    Text = "Kerusakan otak? Kehilangan kemampuan untuk bergerak, sepenuhnya menjadi seorang vegetatif? Atau..."
  },
  AvgDialog_60222_Content_58 = {
    Text = "Di dalam Roh, kamu mendengar teriakan lemah dari para Pembangun. Kamu memutar kepala, menatap Mythag, tangan yang erat mencengkeram Kunci perak bergetar pelan karena kekuatan."
  },
  AvgDialog_60222_Content_59 = {
    Text = "Mungkin konsekuensinya sudah tidak penting lagi. Kamu tahu, kamu tidak punya pilihan lain."
  },
  AvgDialog_60222_Content_6 = {
    Text = "Bagian-bagian tubuh Erica menyebar di lantai. Fragmen tajam meninggalkan luka tak terhitung di tubuhmu, darah mengalir keluar dan mewarnai seragam sekolahmu menjadi merah."
  },
  AvgDialog_60222_Content_60 = {
    Text = "Hanya ada satu cara ini..."
  },
  AvgDialog_60222_Content_61 = {
    Text = "Tangkap {Male=dia,Female=dia}."
  },
  AvgDialog_60222_Content_62 = {
    Text = "Memaksa mengaktifkan Kunci perak"
  },
  AvgDialog_60222_Content_63 = {
    Text = "Kamu mengangkat tanganmu yang memegang kunci perak."
  },
  AvgDialog_60222_Content_64 = {
    Text = "Aku tidak akan membiarkan kalian..."
  },
  AvgDialog_60222_Content_65 = {
    Text = "Gerakan kedua, dimulai."
  },
  AvgDialog_60222_Content_66 = {Text = "Ukh——"},
  AvgDialog_60222_Content_67 = {Text = "?!!!"},
  AvgDialog_60222_Content_68 = {
    Text = "Sebelum kunci perak di tanganmu memancarkan cahaya menyilaukan yang melukai dirimu dan musuhmu, sebuah suara dingin terdengar dari belakang."
  },
  AvgDialog_60222_Content_69 = {
    Text = "Suara itu adalah jejak yang digariskan oleh konduktor, sebuah hukum yang tak terbantahkan di dunia yang dibangun oleh not-not musik."
  },
  AvgDialog_60222_Content_7 = {
    Text = "{Male=Tuan Penjaga Rahasia,Female=Nona Penjaga Rahasia}!"
  },
  AvgDialog_60222_Content_70 = {
    Text = "Setelah suara ini, musik megah bergema dari kedalaman kesadaran kalian."
  },
  AvgDialog_60222_Content_72 = {Text = "!!!"},
  AvgDialog_60222_Content_73 = {Text = "Ini...?"},
  AvgDialog_60222_Content_74 = {
    Text = "Simpan kunci perakmu. Jika kamu mengaktifkannya sekarang, kamu akan mati."
  },
  AvgDialog_60222_Content_75 = {
    Text = "Irama. Melodi. Harmoni lembut dari senar mengisi pikiran kalian."
  },
  AvgDialog_60222_Content_76 = {
    Text = "Itu adalah frekuensi misterius. Anggota Komite jatuh kesakitan di tanah saat mendengar suara musik ini, sementara kamu merasa seperti sedang dibungkus dan dicuci oleh mata air hangat."
  },
  AvgDialog_60222_Content_77 = {
    Text = "Kamu dengan jelas merasakan bahwa tautan antara dirimu dan Pembangun telah pulih kembali. Getaran dari Kolam Hitam tampaknya juga telah sepenuhnya menghilang dalam alunan musik ini."
  },
  AvgDialog_60222_Content_78 = {
    Text = "Clementine menatap dengan terkejut ke arah pemilik suara itu."
  },
  AvgDialog_60222_Content_79 = {
    Text = "Itu kamu! Kenapa…"
  },
  AvgDialog_60222_Content_8 = {
    Text = "Aku baik-baik saja..."
  },
  AvgDialog_60222_Content_80 = {
    Text = "Pukulan, berhenti."
  },
  AvgDialog_60222_Content_81 = {
    Text = "Pria itu mengayunkan tongkat komando dengan lembut. Sebuah perintah pendek dan tegas terdengar, membawa keheningan sesaat."
  },
  AvgDialog_60222_Content_82 = {
    Text = "Clementine tidak kuat lagi dan jatuh ke tanah."
  },
  AvgDialog_60222_Content_83 = {
    Text = "Kamu... kamu..."
  },
  AvgDialog_60222_Content_84 = {
    Text = "Yang lainnya akan segera tiba, dan suara musikku tidak akan bertahan lama."
  },
  AvgDialog_60222_Content_85 = {
    Text = "Aku akan membawamu ke tempat yang aman."
  },
  AvgDialog_60222_Content_86 = {
    Text = "Dia berbalik, sedikit mengangguk ke arahmu, dengan ekspresi wajah yang tenang seperti sumur kuno."
  },
  AvgDialog_60222_Content_87 = {
    Text = "Konduktor Hameln, siap melayani Anda."
  },
  AvgDialog_60222_Content_9 = {
    Text = "Erica tampaknya tidak terpengaruh oleh Kolam Hitam."
  },
  AvgDialog_60223_Content_1 = {
    Text = "Tepat saat kalian bersiap untuk melangkah maju dan mengakhirinya, Anjing Bermuka Manusia yang tampak sekarat tiba-tiba meloncat dan melesat melewati kalian."
  },
  AvgDialog_60223_Content_10 = {
    Text = "Seorang wanita bertubuh tinggi muncul di hadapan kalian, memasukkan pisaunya ke dalam sarung."
  },
  AvgDialog_60223_Content_11 = {
    Text = "Alva! Apakah kamu baik-baik saja?"
  },
  AvgDialog_60223_Content_12 = {
    Text = "Menerima beberapa pengaruh, mengikuti arahan, sedang mundur ke dekat Kolam Hitam."
  },
  AvgDialog_60223_Content_13 = {Text = "Siapa ini?"},
  AvgDialog_60223_Content_14 = {
    Text = "Dia mengerutkan alisnya dan dengan erat memegang pisau di belakang punggungnya."
  },
  AvgDialog_60223_Content_15 = {
    Text = "Di tubuhnya, ada aroma Gereja penerang kuil."
  },
  AvgDialog_60223_Content_16 = {
    Text = "Ini adalah Hameln... Hal lainnya akan dijelaskan nanti, saat ini dia adalah sekutu Mythag."
  },
  AvgDialog_60223_Content_17 = {
    Text = "Kamu melangkah maju untuk memeriksa mayat anjing berwajah manusia."
  },
  AvgDialog_60223_Content_18 = {
    Text = "Memang benar itu adalah lambang Gereja Penerang Kuil. Arah yang ingin dituju adalah Kolam Hitam…"
  },
  AvgDialog_60223_Content_19 = {
    Text = "Juliette sudah tiba di Kolam Hitam. Kita perlu bergerak lebih cepat."
  },
  AvgDialog_60223_Content_2 = {
    Text = "Itu lari! Tangkap itu!"
  },
  AvgDialog_60223_Content_20 = {
    Text = [[
Kamu merapikan barang-barangmu, pandanganmu tertuju pada menara jam. 
 Selama tiga ratus tahun, Kolam Hitam diam-diam berada di Jurang di bawahnya.]]
  },
  AvgDialog_60223_Content_21 = {
    Text = "Hameln, apa hubungan antara Proyek Kembar dan Mythag?"
  },
  AvgDialog_60223_Content_22 = {
    Text = "Lentera menciptakan tiga pasang kembar, dan dua di antaranya gagal."
  },
  AvgDialog_60223_Content_23 = {
    Text = "Pasangan kembar pertama yang mereka buat, sekaligus yang paling menjanjikan untuk berhasil, berada di Mythag."
  },
  AvgDialog_60223_Content_24 = {Text = "Siapa itu?"},
  AvgDialog_60223_Content_25 = {
    Text = "Beberapa tahun yang lalu, pasangan kembar pertama yang dibuat oleh Gereja Penerang Kuil dengan seluruh Kekuatan mereka, salah satunya berhasil dicegat oleh Mulia Dexter yang dikirim oleh Mythag."
  },
  AvgDialog_60223_Content_26 = {
    Text = "Mendengar nama \"Dekster\", jantungmu langsung berdebar sampai ke tenggorokan."
  },
  AvgDialog_60223_Content_27 = {
    Text = "Hameln menundukkan bulu matanya yang panjang, lalu berkata dengan suara rendah tentang informasi yang menghantui pikiranmu dan enggan kau percayai."
  },
  AvgDialog_60223_Content_28 = {
    Text = "Namanya adalah Ramona."
  },
  AvgDialog_60223_Content_29 = {
    Text = "Kepalamu terasa pusing, segala sesuatu di sekitarmu terlihat semu seperti mimpi yang bisa saja tersadar kapan pun."
  },
  AvgDialog_60223_Content_3 = {
    Text = "Hameln dengan cepat mengayunkan tongkatnya, nada musik pun terdengar. Namun, kecepatan Anjing Bermuka Manusia sangat luar biasa, dalam sekejap ia sudah berlari sampai ke tepi jangkauan serangan Hameln."
  },
  AvgDialog_60223_Content_30 = {
    Text = "Maksudmu……"
  },
  AvgDialog_60223_Content_31 = {
    Text = "Teman sekelasmu, temanmu, sahabat dekatmu."
  },
  AvgDialog_60223_Content_32 = {
    Text = "Juliette menggunakan seluruh kekuatannya. Dia datang untuk Ramona."
  },
  AvgDialog_60223_Content_4 = {
    Text = "Suara musik membuatnya tersandung, namun tidak sepenuhnya menghentikannya."
  },
  AvgDialog_60223_Content_5 = {
    Text = "Jangan biarkan itu kabur!"
  },
  AvgDialog_60223_Content_6 = {
    Text = "Kamu mengejarnya dengan sia-sia. Kecepatan anjing berwajah manusia itu sangat tinggi, dan dalam sekejap ia hampir keluar dari jangkauan pandanganmu…"
  },
  AvgDialog_60223_Content_7 = {
    Text = "BYURRR——"
  },
  AvgDialog_60223_Content_8 = {
    Text = "Seberkas cahaya pedang tiba-tiba muncul dari balik semak-semak, melintasi kepala anjing berwajah manusia."
  },
  AvgDialog_60223_Content_9 = {
    Text = "Kepala terpisah dari tubuh, menggelinding di tanah, meninggalkan jejak darah yang kotor."
  },
  AvgDialog_60327_Content_1 = {
    Text = "BLARR——"
  },
  AvgDialog_60327_Content_10 = {
    Text = "Guncangan kuat mendorong kalian ke belakang. Si kembar mengeluarkan suara mendesis tajam yang hampir membuat gendang telingamu pecah."
  },
  AvgDialog_60327_Content_11 = {
    Text = "Simbol roda raksasa yang melambangkan waktu dan takdir hancur, lalu tubuh patung batu."
  },
  AvgDialog_60327_Content_12 = {
    Text = "Di tengah suara ringkikan, patung kembar itu hancur dan runtuh. Bagian-bagian besar tersebut berubah menjadi cairan pelarutan hitam, lalu jatuh ke dalam Kolam Hitam, tanpa meninggalkan jejak sedikit pun."
  },
  AvgDialog_60327_Content_13 = {
    Text = "Penjaga, kita... berhasil?"
  },
  AvgDialog_60327_Content_14 = {
    Text = "Benar, Ramona, kita berhasil!"
  },
  AvgDialog_60327_Content_15 = {
    Text = "Kamu memeluknya erat."
  },
  AvgDialog_60327_Content_16 = {
    Text = "Kali ini, Ramona tidak melawan. Dia berbaring di pelukanmu, menampilkan senyuman seperti bayi."
  },
  AvgDialog_60327_Content_17 = {
    Text = "Terima kasih, %player%."
  },
  AvgDialog_60327_Content_18 = {
    Text = "Kamu mengangkat kepalamu."
  },
  AvgDialog_60327_Content_19 = {
    Text = "Sosok yang berjaga di depan Pintu, sosok yang bertemu denganmu dalam ilusi, kini berdiri di hadapanmu."
  },
  AvgDialog_60327_Content_2 = {Text = "Ramona!"},
  AvgDialog_60327_Content_20 = {Text = "Tavy?!"},
  AvgDialog_60327_Content_21 = {
    Text = "Tawil? Kamu..."
  },
  AvgDialog_60327_Content_22 = {
    Text = "Kesadaran saya dan Tawil bergabung lalu terpisah di dalam patung dewa."
  },
  AvgDialog_60327_Content_23 = {
    Text = "Setelah patung dewi itu hancur, kesadaran miliknya juga kembali ke tubuhnya."
  },
  AvgDialog_60327_Content_24 = {
    Text = "Kekuatan Tubuh Intelektual di tubuh saya sudah hampir habis. Dimensi persembunyian juga telah dilahap oleh pelarutan."
  },
  AvgDialog_60327_Content_25 = {
    Text = "Untungnya, aku juga tidak perlu bersembunyi lagi. Kehendak Tertinggi sudah tidak bisa mendengar suaraku lagi."
  },
  AvgDialog_60327_Content_26 = {
    Text = "Tawil memberikanmu senyuman kecil. Cahaya redup melingkupi wajahnya yang penuh kelemahan dan lembut."
  },
  AvgDialog_60327_Content_27 = {
    Text = "Janji yang kau berikan padaku, kau telah memenuhinya, %player%."
  },
  AvgDialog_60327_Content_28 = {
    Text = "Kamu mengalahkan kami... kamu menyelamatkan kami."
  },
  AvgDialog_60327_Content_29 = {
    Text = "Penjaga, lihat."
  },
  AvgDialog_60327_Content_3 = {
    Text = "Kamu melompat ke depan, di antara reruntuhan patung dewa, dan menangkap sosok dengan kelemahan itu."
  },
  AvgDialog_60327_Content_30 = {
    Text = "Kamu mengikuti arah pandangan Ramona."
  },
  AvgDialog_60327_Content_31 = {
    Text = "Di belakang patung, dua Pintu batu raksasa itu berhenti bergerak, dan berbagai ilusi di dalamnya menjadi tenang."
  },
  AvgDialog_60327_Content_32 = {
    Text = "Warna-warni yang rumit mengalir perlahan di balik pintu, seperti mimpi yang tak pernah terbangun."
  },
  AvgDialog_60327_Content_4 = {
    Text = "Pe... Penjaga..."
  },
  AvgDialog_60327_Content_5 = {
    Text = "Ramona memandangmu. Kamu merasa bingung di dimensi mana dia berada, juga tidak bisa membedakan apakah dia Ramona, Tawil, atau siapa."
  },
  AvgDialog_60327_Content_6 = {
    Text = "Tapi itu tidak penting. Yang terpenting adalah dia telah kembali ke sisimu, seperti banyak kali sebelumnya."
  },
  AvgDialog_60327_Content_7 = {
    Text = "Kamu menggenggam tangannya, sama seperti hari pertama menjadi Penjaga."
  },
  AvgDialog_60327_Content_8 = {
    Text = "Kekuatan roh yang terus-menerus mengalir, seperti lautan yang memasuki kunci perak, lalu mengalir ke dalam tubuh Ramona."
  },
  AvgDialog_60327_Content_9 = {
    Text = "Uwaaa——"
  },
  AvgDialog_60340_Content_1 = {Text = "Jalan"},
  AvgDialog_60340_Content_10 = {
    Text = "Dia dan Sylvia sedang mengawal Czort, bergegas menuju gedung Fakultas Ilmu Biologi dari koridor samping barat…"
  },
  AvgDialog_60340_Content_11 = {
    Text = "Koridor di sebelah barat?"
  },
  AvgDialog_60340_Content_12 = {
    Text = "Mendengar perkataan Alva, Hameln sedikit mengerutkan alisnya."
  },
  AvgDialog_60340_Content_13 = {
    Text = "Sebelum aku mencarimu, Herbert pergi ke barat sekolah bersama beberapa orang. Tugasnya adalah menemukan Ramona."
  },
  AvgDialog_60340_Content_14 = {
    Text = "Ramona sangat cerdas. Hanya dengan Herbert, seharusnya tidak ada cara baginya untuk berbuat apa-apa terhadapnya…"
  },
  AvgDialog_60340_Content_15 = {
    Text = "Tidak semudah itu. Di dalam tubuh Ramona terdapat tanda yang ditinggalkan oleh Gereja Penerang Kuil."
  },
  AvgDialog_60340_Content_16 = {
    Text = "Mengikuti jejak, mereka tidak hanya dapat melacak posisi Ramona, tetapi juga secara aktif menghilangkan kemampuan geraknya."
  },
  AvgDialog_60340_Content_17 = {Text = "!!!"},
  AvgDialog_60340_Content_18 = {
    Text = "Aku akan menggunakan suara untuk sementara meningkatkan kekuatan Tautan rohmu ke level normal, kamu bisa mencoba mencarinya."
  },
  AvgDialog_60340_Content_19 = {
    Text = "Terima kasih!"
  },
  AvgDialog_60340_Content_2 = {
    Text = "Maksudmu... Ramona, diciptakan oleh lentera?!"
  },
  AvgDialog_60340_Content_20 = {
    Text = "Hameln mengangguk pelan. Tongkat komando diangkat tinggi, membentuk lengkungan sempurna di udara."
  },
  AvgDialog_60340_Content_21 = {
    Text = [[
Sebuah alunan musik penuh semangat membanjiri pikiranmu seiring gerakan cekatan darinya. 
 Kamu menutup mata, membiarkan gelombang melodi menuntun kesadaranmu yang melayang.]]
  },
  AvgDialog_60340_Content_22 = {
    Text = "Mencari sosok Ramona"
  },
  AvgDialog_60340_Content_23 = {
    Text = "Di Dimensi Roh, titik-titik cahaya yang sudah dikenal kembali menyala. Kamu berusaha keras untuk mencarinya."
  },
  AvgDialog_60340_Content_24 = {
    Text = "Di antara titik-titik cahaya ini, bagaimanapun kamu mencarinya, sosok yang sudah dikenal tidak akan ditemukan."
  },
  AvgDialog_60340_Content_26 = {
    Text = "Penjaga, bagaimana?"
  },
  AvgDialog_60340_Content_27 = {
    Text = "{Male=Dia,Female=Dia} tidak ditemukan."
  },
  AvgDialog_60340_Content_28 = {
    Text = "Lentera jelas menargetkan Ramona, kita harus menyelamatkan Ramona terlebih dahulu!"
  },
  AvgDialog_60340_Content_29 = {
    Text = "Sambil berbicara, kamu berjalan ke arah barat."
  },
  AvgDialog_60340_Content_3 = {
    Text = "Tubuh bergerak secara mekanis menuju Kolam Hitam, tetapi pikiranmu sepenuhnya terfokus pada kata-kata Hameln."
  },
  AvgDialog_60340_Content_30 = {
    Text = "Saya tahu betapa pentingnya Ramona bagi Anda. Namun, tenanglah, Penjaga."
  },
  AvgDialog_60340_Content_31 = {
    Text = "Menangani masalah Kolam Hitam lebih mendesak. Kamu saat ini juga tidak tahu di mana Ramona berada."
  },
  AvgDialog_60340_Content_32 = {
    Text = "Ini berbeda dari sebelumnya. Lentera datang untuknya, aku tidak bisa membiarkannya begitu saja."
  },
  AvgDialog_60340_Content_33 = {
    Text = "Asalkan pergi ke lokasi terakhir dia berada, kita akan segera bisa menemukannya…"
  },
  AvgDialog_60340_Content_34 = {
    Text = "Saya tahu di mana dia berada."
  },
  AvgDialog_60340_Content_35 = {Text = "!!!"},
  AvgDialog_60340_Content_36 = {
    Text = "Kamu tiba-tiba menghentikan langkahmu. Hameln mengangguk pelan, pakaiannya yang tersusun rapi bergerak dengan irama saat ia bergerak."
  },
  AvgDialog_60340_Content_37 = {
    Text = "Kamu tidak dapat menemukannya di Dimensi Roh, yang berarti dia sudah ditangkap."
  },
  AvgDialog_60340_Content_38 = {
    Text = "Sesuai rencana, Herbert akan membawa Ramona ke Kolam Hitam. Untuk sementara, dia tidak akan berada dalam bahaya hidup."
  },
  AvgDialog_60340_Content_39 = {Text = "Kenapa?"},
  AvgDialog_60340_Content_4 = {
    Text = "Hampir dua puluh tahun yang lalu, Gereja Penerang Kuil, dengan bantuan Herbert, menyusup ke Kolam Hitam dan menggunakan kesadaran ilahi Tawil untuk menciptakan tubuh suci kembar Ramona."
  },
  AvgDialog_60340_Content_40 = {
    Text = "Upacara penciptaan dewa dengan lentera membutuhkan kekuatan dari D-rongga Pelarutan. Mythag hanya memiliki satu D-rongga Pelarutan."
  },
  AvgDialog_60340_Content_41 = {
    Text = "——Selain menghalangi tindakanmu dan membuat Pembangun jatuh ke dalam kekacauan, tujuan Juliette meledakkan Kolam Hitam adalah untuk memunculkan lebih banyak Kekuatan dari Kolam Hitam."
  },
  AvgDialog_60340_Content_42 = {Text = "Ramona..."},
  AvgDialog_60340_Content_43 = {
    Text = "Ramona yang telah meninggal tidak memiliki arti. Ritual penciptaan dewa membutuhkan waktu persiapan yang lama, dan sebelum itu, Ramona berada dalam keadaan aman."
  },
  AvgDialog_60340_Content_44 = {
    Text = "Begitu rupanya… Aku mengerti sekarang."
  },
  AvgDialog_60340_Content_45 = {
    Text = "Kamu menarik napas dalam-dalam untuk menenangkan diri, lalu memandang ke arah pintu masuk lorong bawah tanah yang tak jauh."
  },
  AvgDialog_60340_Content_46 = {
    Text = "Ayo pergi… kita ke Kolam Hitam, temukan mereka!"
  },
  AvgDialog_60340_Content_5 = {
    Text = "Ketika bersiap untuk pergi, Ramona diselamatkan oleh seorang profesor dari Mythag. Sejak itu, dia selalu tinggal di Mythag."
  },
  AvgDialog_60340_Content_6 = {
    Text = "Profesor Dexter... benar, dia memang pernah menyebutkan asal-usul Ramona."
  },
  AvgDialog_60340_Content_7 = {
    Text = "Ternyata, Ramona adalah orang yang diselamatkan dari tangan Gereja Penerang Kuil pada tahun itu!"
  },
  AvgDialog_60340_Content_8 = {
    Text = "Karena Gereja Penerang Kuil datang untuk menemui Ramona, aku harus segera memberitahunya agar berhati-hati…"
  },
  AvgDialog_60340_Content_9 = {
    Text = "Di jalan ke sini, aku pernah bertemu dengannya."
  },
  AvgDialog_60341_Content_1 = {
    Text = "Setelah menyingkirkan agen Komite di jalan, kamu tiba di depan ruangan yang sudah familiar, lalu perlahan mendorong pintu tersebut."
  },
  AvgDialog_60341_Content_10 = {
    Text = "Alistair menghela napas dengan lembut."
  },
  AvgDialog_60341_Content_11 = {
    Text = "Guru, tolong beritahu saya... apa yang harus saya lakukan sekarang?"
  },
  AvgDialog_60341_Content_12 = {
    Text = "Kekuatan Trikorpora, aku bisa merasakannya... Mereka semua telah muncul di Kolam Hitam."
  },
  AvgDialog_60341_Content_13 = {
    Text = "Meskipun aku tidak tahu alasannya, aku melihat jalan yang akan kau jalani."
  },
  AvgDialog_60341_Content_14 = {
    Text = "Pergi ke Kolam Hitam, %player%. Pergi mencari tiga badan besar."
  },
  AvgDialog_60341_Content_15 = {
    Text = "Apakah mereka akan membantu kita?"
  },
  AvgDialog_60341_Content_16 = {
    Text = "Menghadapi bencana terakhir, ketiga entitas besar membuat pilihan yang sangat berbeda."
  },
  AvgDialog_60341_Content_17 = {
    Text = "Tubuh intelektual memilih untuk melawan. Dia memilih para pelaksana, mendirikan Mythag, dan mengajarkan teknologi chip perak kepada manusia."
  },
  AvgDialog_60341_Content_18 = {
    Text = "Substansi keinginan memilih untuk menghindar. Dia menggunakan pelaksanaannya untuk meninggalkan Benih di setiap tempat, berusaha bertahan hidup dari bencana terakhir dengan cara ini."
  },
  AvgDialog_60341_Content_19 = {
    Text = "Apa itu Esensi Kesenangan?"
  },
  AvgDialog_60341_Content_2 = {
    Text = "Kamu datang, %player%, khukh…"
  },
  AvgDialog_60341_Content_20 = {
    Text = "Tawil memberitahuku, Dia memilih untuk mengamati. Dia tidak peduli tentang kehidupan, juga tidak peduli tentang kematian. Selain menyenangkan diri-Nya sendiri, Dia tidak peduli tentang apa pun."
  },
  AvgDialog_60341_Content_21 = {
    Text = "Jadi, selain Tubuh Intelektual, sikap dua lainnya terhadap Mythag tidak jelas, belum tentu akan membantu saya…"
  },
  AvgDialog_60341_Content_22 = {
    Text = "Ini tidak penting. Kamu tidak pergi untuk meminta bantuan dari mereka, %player%."
  },
  AvgDialog_60341_Content_23 = {
    Text = "Dalam tatapan lembut Alistair, melintas seberkas cahaya yang tajam."
  },
  AvgDialog_60341_Content_24 = {
    Text = "Yang harus kamu lakukan adalah mendapatkan kemampuan mereka, dan menerima otoritas mereka!"
  },
  AvgDialog_60341_Content_25 = {
    Text = "Boleh... tapi itu adalah Triad..."
  },
  AvgDialog_60341_Content_26 = {
    Text = "Guru... ini..."
  },
  AvgDialog_60341_Content_27 = {
    Text = "Mereka bahkan tidak mau membantu, bagaimana mungkin mereka bersedia…"
  },
  AvgDialog_60341_Content_28 = {
    Text = "Lagipula, saya tidak tahu apa itu kekuasaan tersebut dan bagaimana cara menggunakannya."
  },
  AvgDialog_60341_Content_29 = {
    Text = "Ini adalah jalanmu. Kamu pasti akan mengetahuinya."
  },
  AvgDialog_60341_Content_3 = {
    Text = "Guru Alistair!"
  },
  AvgDialog_60341_Content_30 = {
    Text = "Senyuman Alistair seperti sepasang tangan yang lembut, mengusap kepalamu dengan hangat."
  },
  AvgDialog_60341_Content_31 = {
    Text = "Di jalan ini, kamu akan memiliki teman, serta musuh."
  },
  AvgDialog_60341_Content_32 = {
    Text = "Banjir besar akan datang, setiap orang harus memainkan peran yang seharusnya mereka jalani. Kita semua sama."
  },
  AvgDialog_60341_Content_33 = {
    Text = "Dia melirikmu dan Hameln, kata-kata penuh makna itu tidak jelas ditujukan untuk siapa."
  },
  AvgDialog_60341_Content_34 = {
    Text = "Hameln berdiri di dalam bayangan, sedikit menundukkan kepala ke arahnya sebagai bentuk penghormatan."
  },
  AvgDialog_60341_Content_35 = {
    Text = "Alistair tidak mengatakan apa-apa lagi. Dia berbalik dan terus menatap Kolam hitam yang tak terlihat batasnya."
  },
  AvgDialog_60341_Content_36 = {
    Text = "Jangan khawatir tentang Kolam Hitam, dan juga tidak perlu khawatir tentang saya."
  },
  AvgDialog_60341_Content_37 = {
    Text = "Hal yang seharusnya kau ketahui, akan segera kau pahami."
  },
  AvgDialog_60341_Content_38 = {
    Text = "Pergilah. Sudah waktunya bagi kau untuk melangkah di jalanmu sendiri."
  },
  AvgDialog_60341_Content_4 = {
    Text = "Darah menyembur dari mulut Alistair, mewarnai perban di tubuhnya menjadi merah gelap."
  },
  AvgDialog_60341_Content_5 = {
    Text = "Dalam waktu singkat beberapa jam, Alistair menjadi sangat lemah, tubuhnya bergetar sedikit karena dingin dan rasa sakit, hampir terjatuh dari kursi rodanya."
  },
  AvgDialog_60341_Content_6 = {
    Text = "Guru… aku terlambat… aku akan segera membawamu keluar!"
  },
  AvgDialog_60341_Content_7 = {
    Text = "Alistair tidak banyak bicara, hanya tersenyum tipis sambil menggelengkan kepalanya dengan lembut."
  },
  AvgDialog_60341_Content_8 = {
    Text = "Menekan Kolam Hitam adalah tugasku. Tugas kamu tidak di sini."
  },
  AvgDialog_60341_Content_9 = {
    Text = "Itu adalah jalan yang jauh lebih sulit, bahkan ribuan kali lebih berat daripada yang kujalani…"
  },
  AvgDialog_60342_Content_1 = {
    Text = "Sudah sampai!"
  },
  AvgDialog_60342_Content_10 = {
    Text = "Kamu melangkah maju dan mengulurkan tangan ke arahnya."
  },
  AvgDialog_60342_Content_11 = {
    Text = "Menjawab aku, Tawil…"
  },
  AvgDialog_60342_Content_12 = {Text = "!!!"},
  AvgDialog_60342_Content_13 = {
    Text = "Di sini adalah..."
  },
  AvgDialog_60342_Content_14 = {
    Text = "Pada saat menyentuh tubuh Tawil, Kolam Hitam menghilang dari pandanganmu."
  },
  AvgDialog_60342_Content_15 = {
    Text = "Kamu memandang zat yang mengalir di depanmu. Kamu tidak tahu apa itu, lalu kamu mengulurkan tanganmu, membiarkannya menembus Tubuhmu dan mengalir perlahan."
  },
  AvgDialog_60342_Content_16 = {
    Text = "Dalam cahaya ajaib ini, ilusi terbentang di depan matamu. Sebuah wajah yang familiar muncul di hadapanmu."
  },
  AvgDialog_60342_Content_17 = {
    Text = "Ramona! Ini adalah..."
  },
  AvgDialog_60342_Content_18 = {
    Text = "Kesadaran, mimpi, kumpulan tak terhitung waktu dan dimensi, titik pertemuan segala hal rasional dan irasional. Sebuah singularitas yang tidak ada…"
  },
  AvgDialog_60342_Content_19 = {
    Text = "Ramona yang ilusif membuka mulutnya dan menceritakan asal-usul tempat ini kepadamu, lalu dia menghilang."
  },
  AvgDialog_60342_Content_2 = {
    Text = "Ramona tampaknya tidak berada di sini…"
  },
  AvgDialog_60342_Content_20 = {Text = "Ramona!"},
  AvgDialog_60342_Content_21 = {
    Text = "Itu adalah bayangannya. Sebuah bayangan dari masa lalu."
  },
  AvgDialog_60342_Content_22 = {
    Text = "Sebuah suara, seakan-akan berasal dari kejauhan, atau mungkin dari dalam pikiranmu sendiri, terdengar."
  },
  AvgDialog_60342_Content_23 = {
    Text = "Selamat datang di tempat persembunyian saya. Penjaga."
  },
  AvgDialog_60342_Content_24 = {
    Text = "Tawil… Aku mengerti, ini adalah tempatmu bersembunyi dari Kehendak Tertinggi."
  },
  AvgDialog_60342_Content_25 = {
    Text = "Banyak hal terjadi di Mythag, aku mencarimu karena ingin..."
  },
  AvgDialog_60342_Content_26 = {
    Text = "Bencana akan segera tiba, Alistair telah memberitahumu segalanya. Tiffre Yosod dan Marukot telah menyerahkan kekuasaan mereka kepadamu."
  },
  AvgDialog_60342_Content_27 = {
    Text = "Apa yang terjadi di luar, apakah kamu sudah tahu?"
  },
  AvgDialog_60342_Content_28 = {
    Text = "Yang mengalir di ruang ini adalah segala sesuatu tentang masa lalu, sekarang, dan masa depan."
  },
  AvgDialog_60342_Content_29 = {
    Text = "Tubuh intelektual, mengetahui segala hal."
  },
  AvgDialog_60342_Content_3 = {
    Text = "Semua anggota Komite yang berpatroli di sekitar menunjukkan tanda-tanda Pelarutan dengan tingkat keparahan yang berbeda-beda."
  },
  AvgDialog_60342_Content_30 = {
    Text = "Agar tidak membangkitkan bencana terakhir, aku tidak bisa langsung ikut campur di duniamu. Oleh karena itu, aku membawamu ke sini untuk bertemu."
  },
  AvgDialog_60342_Content_31 = {
    Text = "Aku akan membantu Mythag. Aku akan membantu duniamu."
  },
  AvgDialog_60342_Content_32 = {
    Text = "Hebat sekali! Kalau begitu, sekarang…"
  },
  AvgDialog_60342_Content_33 = {
    Text = "Di musim semi Akut, aku melihatmu. Ada sesuatu dalam dirimu yang tidak bisa kulihat dengan jelas."
  },
  AvgDialog_60342_Content_34 = {
    Text = "Saya melakukan perhitungan di sini. Dari tak terhitung banyaknya masa depan, saya melihat jalan yang benar… Sekarang, saya bisa melihatmu dengan jelas."
  },
  AvgDialog_60342_Content_35 = {
    Text = "Dia perlahan membuka matanya, sepasang mata yang dingin karena kebijaksanaan penuh menatapmu."
  },
  AvgDialog_60342_Content_36 = {
    Text = "Zat di sekitarmu tiba-tiba berhenti mengalir, kamu tidak siap. Tekanan kuat seperti benda padat membungkus tubuhmu erat-erat, membuatmu sulit bernapas."
  },
  AvgDialog_60342_Content_37 = {
    Text = "Apa yang kamu... katakan..."
  },
  AvgDialog_60342_Content_38 = {
    Text = "Dalam semua perhitungan, kau adalah kesalahan."
  },
  AvgDialog_60342_Content_39 = {
    Text = "Untuk Mythag, demi kelangsungan dunia ini, aku akan berada di sini untuk memperbaiki kesalahan ini."
  },
  AvgDialog_60342_Content_4 = {
    Text = "Semakin dekat dengan Tawil, semakin parah erosi pelarutan yang dialami. Sebelum persiapan ritual selesai, Juliette tidak akan mendekat ke sini secara gegabah."
  },
  AvgDialog_60342_Content_40 = {Text = "!!!"},
  AvgDialog_60342_Content_5 = {
    Text = "Sebelum dia muncul, segera selesaikan pemulihan wewenang."
  },
  AvgDialog_60342_Content_6 = {
    Text = "Kamu menatap sosok ilusi di depanmu."
  },
  AvgDialog_60342_Content_7 = {
    Text = "Bulu putih yang bercahaya perlahan jatuh, menghilang di udara. Di tengah sayap raksasa yang membungkus, terlihat wajah yang sedang tidur nyenyak."
  },
  AvgDialog_60342_Content_8 = {
    Text = "Bayangan terang dan gelap saling bersilangan, seberapa pun kerasnya kamu berusaha, wajahnya tetap tak terlihat jelas, seolah-olah wajah itu tidak ada dalam dimensi waktu dan ruangmu."
  },
  AvgDialog_60342_Content_9 = {
    Text = "Menyentuh Tawil"
  },
  AvgDialog_60343_Content_1 = {
    Text = "Tidak buruk, Penjaga {Male=tuan,Female=nyonya}."
  },
  AvgDialog_60343_Content_2 = {
    Text = "Baru saja menyerap kekuasaan nafsu, masih bisa bertahan sampai sekarang… aku telah meremehkanmu."
  },
  AvgDialog_60343_Content_3 = {
    Text = "N bangkit dari kursi penonton, sedikit menarik ujung topinya, lalu dengan sopan memberi hormat kepadamu di atas panggung."
  },
  AvgDialog_60343_Content_4 = {
    Text = "Kalau begitu, sekarang giliran adegan lawan kita."
  },
  AvgDialog_60343_Content_5 = {
    Text = "Penjahat utama yang licik dan memesona akan segera muncul——"
  },
  AvgDialog_60344_Content_1 = {
    Text = "Siswa baik, siswa buruk"
  },
  AvgDialog_60344_Content_10 = {
    Text = "Ramona, maaf telah merepotkan kalian. Jika aku tidak terluka, mungkin aku bisa membantu meringankan bebanmu sedikit…"
  },
  AvgDialog_60344_Content_100 = {
    Text = "Dia bangkit berdiri, tersenyum sambil mengelus kucing tanpa bulu di atas pundaknya."
  },
  AvgDialog_60344_Content_101 = {
    Text = "Kucing mengangkat kepalanya, mata yang tampak bosan menyapu sekilas manusia di sekitarnya sebagai jawaban."
  },
  AvgDialog_60344_Content_11 = {
    Text = [[
Tidak perlu mengatakan hal seperti itu, Kepala Sekolah. 
Orang Mythag tidak pernah menganggap yang terluka sebagai beban.]]
  },
  AvgDialog_60344_Content_12 = {
    Text = "Setelah kami menempatkan kalian di gedung Fakultas Ilmu Hidup, kami bisa..."
  },
  AvgDialog_60344_Content_13 = {
    Text = "Apakah Anda membutuhkan tumpangan, Nona Ramona?"
  },
  AvgDialog_60344_Content_14 = {Text = "!!!"},
  AvgDialog_60344_Content_15 = {Text = "Hati-hati!"},
  AvgDialog_60344_Content_16 = {
    Text = "Ramona mengangkat pedangnya di depan tubuhnya."
  },
  AvgDialog_60344_Content_17 = {
    Text = "Di belakangnya, Sylvie mengerutkan kening, melindungi Czort yang lemah."
  },
  AvgDialog_60344_Content_18 = {
    Text = "Langkah kaki yang terburu-buru terdengar, tampaknya sudah lama bersembunyi di sini."
  },
  AvgDialog_60344_Content_19 = {
    Text = "Di kedua ujung lorong yang sempit, para agen berpakaian seragam Komite memadati jalan mereka."
  },
  AvgDialog_60344_Content_2 = {
    Text = "Di koridor yang sempit dan panjang, tidak terlihat satu pun bayangan manusia. Suara napas berat serta langkah kaki terdengar, bergema di sepanjang koridor."
  },
  AvgDialog_60344_Content_20 = {
    Text = "Pria bermata satu melangkah ke depan kerumunan sambil dengan lembut menggoda kucing tanpa bulu di pundaknya, yang memiliki dua kepala yang dijahit menjadi satu."
  },
  AvgDialog_60344_Content_21 = {
    Text = "Itu... itu kamu..."
  },
  AvgDialog_60344_Content_22 = {
    Text = "Melihat wajah ini muncul di depannya, tubuh Czort langsung menegang."
  },
  AvgDialog_60344_Content_23 = {
    Text = "Herbert... dasar brengsek..."
  },
  AvgDialog_60344_Content_24 = {
    Text = "Guru Crowley memperlakukanmu seperti anaknya sendiri, namun kau justru membunuhnya dan merebut hasil penelitiannya… Hingga sekarang, kau masih berani kembali…"
  },
  AvgDialog_60344_Content_25 = {
    Text = "Ssst, teman sekelas Czort... Ah tidak, seharusnya kupanggil kamu, Dekan Czort."
  },
  AvgDialog_60344_Content_26 = {
    Text = "Setelah aku pergi, posisi direktur pasti akan menjadi milikmu."
  },
  AvgDialog_60344_Content_27 = {
    Text = "Saya sangat ingin mengenang masa-masa indah saat kita menuntut ilmu dulu, tetapi hari ini saya datang ke sini juga memiliki urusan penting lain yang harus diselesaikan."
  },
  AvgDialog_60344_Content_28 = {
    Text = "Matanya tertuju pada Ramona."
  },
  AvgDialog_60344_Content_29 = {
    Text = "Sudah lama tidak bertemu, sungguh membuat rindu, Nona Ramona."
  },
  AvgDialog_60344_Content_3 = {
    Text = "Huu... Dekan Czort, tolong bertahan sebentar lagi, kita hampir sampai."
  },
  AvgDialog_60344_Content_30 = {
    Text = "Namun, hanya bertemu beberapa kali dalam periode ini, tidak perlu berbicara seolah-olah sudah sangat akrab."
  },
  AvgDialog_60344_Content_31 = {
    Text = "Selama ini? Tidak, tidak."
  },
  AvgDialog_60344_Content_32 = {
    Text = "Herbert mengangkat pandangannya, melewati Czort, melewati Ramona, dan akhirnya jatuh ke dalam kegelapan hampa, seolah-olah menatap sesuatu yang begitu jauh hingga tak terjangkau."
  },
  AvgDialog_60344_Content_33 = {
    Text = "Aku masih ingat pertama kali melihatmu, sepertinya itu terjadi di Lorong ini."
  },
  AvgDialog_60344_Content_34 = {
    Text = "Pada saat itu, kamu baru sebesar ini..."
  },
  AvgDialog_60344_Content_35 = {
    Text = "Herbert mengulurkan kedua tangannya, menirukan panjang seekor kucing tanpa bulu."
  },
  AvgDialog_60344_Content_36 = {
    Text = "Apa maksudmu...?"
  },
  AvgDialog_60344_Content_37 = {
    Text = "Relikku. Anakku."
  },
  AvgDialog_60344_Content_38 = {
    Text = [[
Helot adalah produk gagal, pasangan kembar yang lemah dari planet asing itu juga tidak mampu menanggung misi yang mulia. 
 Dalam kerja sama antara saya dan Gereja Penerang Kuil, kau adalah kristal terbaik yang sempurna.]]
  },
  AvgDialog_60344_Content_39 = {
    Text = "Saya tidak mengerti..."
  },
  AvgDialog_60344_Content_4 = {
    Text = "Ramona, harap berhati-hati dengan lukamu…"
  },
  AvgDialog_60344_Content_40 = {
    Text = "Apakah kamu masih belum mengerti, Ramona?"
  },
  AvgDialog_60344_Content_41 = {
    Text = "Orang-orang yang kau pedulikan, mengalami ketakutan, menderita kerusakan, menghadapi ancaman kehilangan kendali dan kematian… semua bencana yang dialami Mythag ini terjadi karena dirimu."
  },
  AvgDialog_60344_Content_42 = {
    Text = "Kamu... apa yang kamu katakan?"
  },
  AvgDialog_60344_Content_43 = {
    Text = "Melihat pedang yang bergetar dan mendengung di tangan Ramona, Herbert tersenyum dan melangkah maju dua langkah."
  },
  AvgDialog_60344_Content_44 = {
    Text = "Banyak tahun yang lalu, pencuri bernama Dexter mencurimu dari kami."
  },
  AvgDialog_60344_Content_45 = {
    Text = "Hari ini datang terlambat, namun tidak masalah — itu tiba tepat pada waktunya."
  },
  AvgDialog_60344_Content_46 = {
    Text = "Kamu adalah kembar yang berharga, Relik sempurna dari sang Pemegang Lampu."
  },
  AvgDialog_60344_Content_47 = {
    Text = "Kami datang kali ini untuk menemukanmu kembali."
  },
  AvgDialog_60344_Content_48 = {
    Text = "Jadi, ikutlah denganku, Ramona."
  },
  AvgDialog_60344_Content_49 = {
    Text = "Aku berjanji padamu, asalkan kamu tetap tenang dan mengikuti aku pergi, semua gangguan yang dialami Mythag akan berhenti."
  },
  AvgDialog_60344_Content_5 = {
    Text = "Dia mengeluarkan sapu tangan dan dengan hati-hati membersihkan noda darah di lengan Ramona."
  },
  AvgDialog_60344_Content_50 = {
    Text = "Ramona, kamu…"
  },
  AvgDialog_60344_Content_51 = {
    Text = "Apakah aku tampak begitu bodoh di matamu, Herbert?"
  },
  AvgDialog_60344_Content_52 = {
    Text = "Ini adalah Mythag. Apapun tujuan kalian, kami tidak akan membiarkannya tercapai."
  },
  AvgDialog_60344_Content_53 = {
    Text = "Melihat pedang tipis yang diangkat oleh Ramona, Herbert menggerakkan jarinya dengan lembut."
  },
  AvgDialog_60344_Content_54 = {
    Text = "Tentu saja kamu adalah orang yang cerdas, Ramona."
  },
  AvgDialog_60344_Content_55 = {
    Text = "Kamu perlu mengawal dua wanita yang kurang memiliki kemampuan untuk melindungi diri, jadi kamu memilih jalan yang jarang diketahui orang ini."
  },
  AvgDialog_60344_Content_56 = {
    Text = "Saya sepenuhnya percaya pada kemampuanmu untuk menembus kepungan. Jika kau datang sendirian ke sini, aku tidak yakin bisa menghentikanmu."
  },
  AvgDialog_60344_Content_57 = {
    Text = "Namun, cobalah melihat kembali kepada kedua guru yang kau hormati, Dekan Czort dan Guru Sylvia, Ramona."
  },
  AvgDialog_60344_Content_58 = {
    Text = "Ramona memandang sekelilingnya ke arah agen Komite yang mengamati dengan tatapan penuh ancaman, pedang di tangannya tetap tidak bergerak di depan dadanya."
  },
  AvgDialog_60344_Content_59 = {
    Text = "Keselamatan Mythag adalah yang paling utama. Lakukan hal yang benar, Ramona."
  },
  AvgDialog_60344_Content_6 = {
    Text = "Ah... maaf."
  },
  AvgDialog_60344_Content_60 = {
    Text = "Bisikan Czort masuk ke telinga Ramona. Dia berhenti sejenak, tanpa mengangguk."
  },
  AvgDialog_60344_Content_61 = {
    Text = "Sesaat kemudian, dia mengangkat kepalanya dan menatap Herbert."
  },
  AvgDialog_60344_Content_62 = {
    Text = "Aku berjanji padamu..."
  },
  AvgDialog_60344_Content_63 = {Text = "Ramona!"},
  AvgDialog_60344_Content_64 = {
    Text = "Namun, saya memiliki satu syarat."
  },
  AvgDialog_60344_Content_65 = {
    Text = "Silakan bicara."
  },
  AvgDialog_60344_Content_66 = {
    Text = "Suruh orang-orangmu mundur ke luar lorong, tunggu sampai Dekan Czort dan Guru Silvia pergi jauh, lalu aku akan ikut denganmu."
  },
  AvgDialog_60344_Content_67 = {
    Text = "Ah, tentu saja, tidak masalah——"
  },
  AvgDialog_60344_Content_68 = {
    Text = "Dia melambaikan tangannya. Di bawah arahannya, para Agen dari Komite membuka jalan."
  },
  AvgDialog_60344_Content_69 = {
    Text = "Ramona, tujuan mereka adalah membawamu pergi, kamu tidak bisa ikut dengan mereka!"
  },
  AvgDialog_60344_Content_7 = {
    Text = "Tadi saat bertarung dengan beberapa orang dariKomite, aku kehilangan konsentrasi sejenak……"
  },
  AvgDialog_60344_Content_70 = {
    Text = "Tenang saja, Dekan Czort. Aku sangat penting bagi mereka, jadi mereka tidak akan berbuat apa-apa padaku."
  },
  AvgDialog_60344_Content_71 = {Text = "Tapi..."},
  AvgDialog_60344_Content_72 = {
    Text = "Dekan Czort, ayo pergi."
  },
  AvgDialog_60344_Content_73 = {
    Text = "Ramona benar, Herbert tidak akan menyakitinya."
  },
  AvgDialog_60344_Content_74 = {
    Text = "Percayalah padanya."
  },
  AvgDialog_60344_Content_75 = {
    Text = "Dari matanya yang tersenyum, Czort memahami maksudnya. Dia pun mengangguk."
  },
  AvgDialog_60344_Content_76 = {
    Text = "Agen dari Komite menghindar ke samping, formasi yang semula utuh menjadi kacau. Di bagian depan dan belakang lingkaran pengepungan, muncul celah yang jelas."
  },
  AvgDialog_60344_Content_77 = {
    Text = "Agen-agen yang sedang bergerak secara bertahap mengalihkan perhatian mereka kepada perubahan formasi, dan tidak lagi memantau setiap gerakan Ramona secara real-time."
  },
  AvgDialog_60344_Content_78 = {Text = "Ah!!"},
  AvgDialog_60344_Content_79 = {
    Text = "Teriakan mengerikan dari dua Agen menarik perhatian semua orang."
  },
  AvgDialog_60344_Content_8 = {
    Text = "Kekacauan di Kolam Hitam, tetap saja tidak terhindarkan memberikan pengaruh padamu, kan?"
  },
  AvgDialog_60344_Content_80 = {
    Text = "Ketika kewaspadaan Komite mulai melonggar, Ramona dengan cepat dan tegas menyelesaikan dua Agen yang mengendalikannya menggunakan pedang."
  },
  AvgDialog_60344_Content_81 = {
    Text = "(Maaf, Dekan Czort, Profesor Sylvia. Saya tidak bisa membiarkan Mythag dalam bahaya.)"
  },
  AvgDialog_60344_Content_82 = {
    Text = "(Saya akan membawa Pembangun lain untuk menyelamatkan kalian. Sangat cepat!)"
  },
  AvgDialog_60344_Content_83 = {
    Text = "Ramona tidak punya waktu untuk mengucapkan kata-kata itu. Ini adalah satu-satunya kesempatan. Dari celah yang tiba-tiba muncul ini, dia melarikan diri."
  },
  AvgDialog_60344_Content_84 = {
    Text = "Beberapa agen dengan susah payah bereaksi, tetapi mereka sama sekali tidak mampu menahan serangan pedang Ramona. Czort dan Sylvia saling bertukar pandang, dengan ekspresi lega di wajah mereka."
  },
  AvgDialog_60344_Content_85 = {
    Text = "Dari sudut matanya, Herbert melihat ekspresi di wajah mereka, lalu tersenyum dan mengangkat tangannya, melambaikan dengan lembut."
  },
  AvgDialog_60344_Content_86 = {
    Text = "Kami dengan hormat menantikan kedatangan Anda di sini, wahai kehendak yang agung…"
  },
  AvgDialog_60344_Content_87 = {
    Text = "Untuk kelahiran Anda, berikanlah Berkat kepada kami dan hukumlah mereka yang tidak hormat…"
  },
  AvgDialog_60344_Content_88 = {
    Text = "Serangkaian suku kata aneh melayang dari kerumunan, dan saat sampai di telinga Ramona, organ dalamnya tiba-tiba terasa tegang, seolah-olah dijepit oleh tali tak terlihat yang menguras seluruh kekuatannya."
  },
  AvgDialog_60344_Content_89 = {
    Text = [[
Dia tidak bersiap, tiba-tiba terjatuh ke tanah. Pedang tipis di tangannya tergelincir ke samping, dan setelah suara logam kecil bergeser, berhenti tidak jauh darinya. 
 Ramona mengangkat tangannya, namun tak mampu menyentuhnya.]]
  },
  AvgDialog_60344_Content_9 = {
    Text = "Hanya beberapa saja."
  },
  AvgDialog_60344_Content_90 = {
    Text = "Ini... ini..."
  },
  AvgDialog_60344_Content_91 = {
    Text = "Bahkan Relik yang paling murah sekalipun akan meninggalkan jejak lentera di dalam tubuhnya. Apalagi kamu."
  },
  AvgDialog_60344_Content_92 = {
    Text = "Kamu harus mencari kesempatan untuk melarikan diri. Aku juga sedang menunggu orang-orang dari Gereja Penerang Kuil untuk mengaktifkan segel sihir di dalam tubuhmu. Ini membutuhkan waktu."
  },
  AvgDialog_60344_Content_93 = {
    Text = "Jika menggunakan kekerasan dan melukaimu, atau kamu berhasil melarikan diri, itu akan menjadi masalah."
  },
  AvgDialog_60344_Content_94 = {
    Text = "Kamu... sudah tahu sejak awal bahwa aku akan melarikan diri..."
  },
  AvgDialog_60344_Content_95 = {
    Text = "Aku tak pernah membayangkan kau akan menyerah begitu saja. Kau bukan orang yang sebodoh itu."
  },
  AvgDialog_60344_Content_96 = {
    Text = "Herbert mendekati Ramona, mengambil pedang tipis dan memainkannya di tangannya, lalu menghela napas dengan nada penuh penyesalan."
  },
  AvgDialog_60344_Content_97 = {
    Text = "Jika kamu memilih untuk melawan sejak awal, mungkin kami benar-benar tidak bisa menghentikanmu. Namun, kamu menginginkan segalanya: lebih banyak informasi dengan harga yang lebih kecil…"
  },
  AvgDialog_60344_Content_98 = {
    Text = "Aku memahami dirimu, Ramona. Kau terlalu mengejar kesempurnaan. Bahkan dalam situasi sesulit ini, kau masih ingin membantu Mythag sebanyak mungkin dan juga membantu Penjaga."
  },
  AvgDialog_60344_Content_99 = {
    Text = "Namun, ketika informasi tidak seimbang, semakin mengejar kesempurnaan, semakin mudah membuat kesalahan. Apakah kamu setuju?"
  },
  AvgDialog_60346_Content_1 = {
    Text = "Cara untuk bertahan hidup"
  },
  AvgDialog_60346_Content_10 = {Text = "Taisses…"},
  AvgDialog_60346_Content_11 = {
    Text = "Saya di sini."
  },
  AvgDialog_60346_Content_12 = {
    Text = "Thais, apakah kamu akan datang menemuiku?"
  },
  AvgDialog_60346_Content_13 = {
    Text = "Akan ada harganya."
  },
  AvgDialog_60346_Content_14 = {
    Text = "Saya bersedia menanggungnya!"
  },
  AvgDialog_60346_Content_15 = {Text = "Ukh——"},
  AvgDialog_60346_Content_16 = {
    Text = "Rasa sakit yang menyengat membuatmu jatuh berlutut. Sebutir Benih yang memancarkan cahaya redup muncul dari perutmu dan melayang di atas Kolam Hitam."
  },
  AvgDialog_60346_Content_17 = {
    Text = "Benih jatuh ke dalam Kolam Hitam, memicu riak yang bergerak perlahan. Saat riak itu menyebar, pemandangan di Kolam Hitam mulai berubah dan bergoyang. Bukit pasir yang sudah tidak asing lagi muncul di hadapanmu."
  },
  AvgDialog_60346_Content_18 = {
    Text = "Gumpalan pasir kuning yang luas diangkat oleh semilir angin manis, lalu berkumpul di hadapanmu."
  },
  AvgDialog_60346_Content_19 = {
    Text = "Segera, dengan Benih itu sebagai inti, pasir kuning sebagai daging dan tulang, sebuah makhluk berbentuk manusia muncul di hadapanmu."
  },
  AvgDialog_60346_Content_2 = {
    Text = "Cahaya dari laboratorium penelitian bawah tanah semakin menjauh dari kamu, perlahan menjadi seperti kunang-kunang yang redup."
  },
  AvgDialog_60346_Content_20 = {Text = "Thais...?"},
  AvgDialog_60346_Content_21 = {
    Text = "Sejak dia menghilang di Sungai Suci saat pasang surut setelah runtuhnya Pohon Ibu, tidak ada yang mengetahui keberadaannya lagi."
  },
  AvgDialog_60346_Content_22 = {
    Text = [[
Ini adalah... Kolam Hitam, tempat di mana Arus Hitam dari pusat bumi menyembul ke permukaan tanah di sini... 
 Hanya dia yang mampu menahan kegelapan abadi dan dalam di tempat ini.]]
  },
  AvgDialog_60346_Content_23 = {
    Text = "Thais tiba-tiba mendekat, dengan bibirnya yang penuh, alis matanya yang menggoda, serta senyumannya yang tanpa suara, semuanya sama seperti Remwahi."
  },
  AvgDialog_60346_Content_24 = {
    Text = "Jawab aku, Penjaga, mengapa kau Bangun aku di sini saat kita belum mencapai dunia baru?"
  },
  AvgDialog_60346_Content_25 = {
    Text = "Kamu menyampaikan semua pesan yang dipesan Alistair."
  },
  AvgDialog_60346_Content_26 = {
    Text = "Ekspresi Thais berubah dari bingung, menjadi panik, dan akhirnya berubah menjadi ketakutan."
  },
  AvgDialog_60346_Content_27 = {
    Text = "Tidak... ini bukan jalan yang layak ditempuh..."
  },
  AvgDialog_60346_Content_28 = {
    Text = "Dia pada akhirnya akan bangun, tidak ada yang mampu mengalahkan-Nya…"
  },
  AvgDialog_60346_Content_29 = {
    Text = "Namun, aku telah memutuskan."
  },
  AvgDialog_60346_Content_3 = {
    Text = "Kolam hitam mendidih di bawah kakimu, cahaya redup Tawil bergetar lemah di kejauhan, seperti cat putih murni yang jatuh ke dalam Aequor, segera menghilang tanpa jejak."
  },
  AvgDialog_60346_Content_30 = {
    Text = "Thais menghela napas pelan."
  },
  AvgDialog_60346_Content_31 = {
    Text = "Tolong pinjamkan aku wewenang dari esensi keinginan."
  },
  AvgDialog_60346_Content_32 = {
    Text = "Kamu melangkah maju, menatap langsung ke mata Thais."
  },
  AvgDialog_60346_Content_33 = {
    Text = "Ah, bocah kecil..."
  },
  AvgDialog_60346_Content_34 = {
    Text = [[
Aku telah lama menyerahkan kekuasaanku padamu. 
 Segalanya milikku tidak ada yang kusembunyikan darimu.]]
  },
  AvgDialog_60346_Content_35 = {
    Text = "Benih yang pernah kutanam di tubuhmu… kekuasaanku melekat padanya."
  },
  AvgDialog_60346_Content_36 = {
    Text = "Hanya saja, itu sudah kau cabut secara paksa. \n Itu merasa takut, marah…"
  },
  AvgDialog_60346_Content_37 = {
    Text = "Untuk menumbuhkannya kembali, pertama-tama harus membuatnya tenang…"
  },
  AvgDialog_60346_Content_4 = {
    Text = "Seiring dengan semakin dalamnya kamu, kegelisahan di Kolam Hitam juga menjadi semakin jelas."
  },
  AvgDialog_60346_Content_5 = {
    Text = "Sekarang, jika pergi menemui Tawil, Juliette pasti akan terkejut. Jadi, dia harus disisihkan untuk yang terakhir."
  },
  AvgDialog_60346_Content_6 = {
    Text = "Dua protoplasma lainnya, ke mana seharusnya aku mencarinya ……"
  },
  AvgDialog_60346_Content_7 = {
    Text = "Gurumu mengetahui banyak hal. Dia tidak memberitahumu tentang hal ini, mungkin, kau lebih pantas untuk mengetahuinya."
  },
  AvgDialog_60346_Content_8 = {
    Text = "Mengingat mereka, memanggil nama mereka, mungkin mereka akan meresponsmu."
  },
  AvgDialog_60346_Content_9 = {
    Text = "Dalam benakmu muncul wajah yang penuh senyuman, dia pernah datang menghampirimu di momen kritis di mana kamu menghadapi sisa pohon suci, melangkah di atas pasir, meratakan semua rintangan untukmu."
  },
  AvgDialog_60347_Content_1 = {
    Text = "Twist ala Dexter"
  },
  AvgDialog_60347_Content_10 = {
    Text = "Kamu merasakannya dengan cermat. Kekuatan dahsyat Thais mengamuk di dalam tubuhmu, dan kamu sama sekali tidak tahu bagaimana cara menyerapnya. Bahkan gerakan normalmu pun terpengaruh secara serius."
  },
  AvgDialog_60347_Content_11 = {
    Text = "Tidak tahu situasi ini akan berlangsung sampai kapan. Ramona masih terjebak di Kolam Hitam, aku harus mempercepat langkah…"
  },
  AvgDialog_60347_Content_12 = {
    Text = "Cuaca sedingin ini, berbaring di Kolam Hitam bisa membuatmu sakit."
  },
  AvgDialog_60347_Content_13 = {
    Text = "Profesor Dexter?"
  },
  AvgDialog_60347_Content_14 = {
    Text = "Profesor Dexter?!"
  },
  AvgDialog_60347_Content_15 = {
    Text = "Suara yang akrab, sosok yang akrab."
  },
  AvgDialog_60347_Content_16 = {
    Text = "Menyandarkan tongkat dengan tangan yang terawat rapi, datang ke hadapanmu."
  },
  AvgDialog_60347_Content_17 = {
    Text = "Profesor Dexter, sekarang di dalam Kolam Hitam sangat berbahaya, mohon Anda segera meninggalkan tempat ini!"
  },
  AvgDialog_60347_Content_18 = {
    Text = "Tolong jangan khawatirkan Ramona, sebentar lagi aku akan pergi untuk menyelamatkannya…"
  },
  AvgDialog_60347_Content_19 = {
    Text = "Kamu masih sangat peduli pada Ramona seperti biasanya, Penjaga."
  },
  AvgDialog_60347_Content_2 = {
    Text = "Bukit pasir... menghilang..."
  },
  AvgDialog_60347_Content_20 = {
    Text = "Terima kasih atas perhatianmu, aku baru saja bertemu dengan Ramona."
  },
  AvgDialog_60347_Content_21 = {
    Text = "Apakah Anda sudah...?"
  },
  AvgDialog_60347_Content_22 = {
    Text = "Benar. Dia sekarang sangat... nyaman."
  },
  AvgDialog_60347_Content_23 = {
    Text = "Dia sudah lama tidak tidur sepuas ini. Saya pikir, dia benar-benar membutuhkan tidur seperti ini."
  },
  AvgDialog_60347_Content_24 = {
    Text = "Dia... sekarang dalam bahaya besar... mengapa Anda tidak..."
  },
  AvgDialog_60347_Content_25 = {
    Text = "Mencari cara untuk menyelamatkannya? Benar juga, kenapa tidak... Dexter sangat mencintai putrinya, seharusnya dia berusaha sepenuhnya untuk menyelamatkannya."
  },
  AvgDialog_60347_Content_26 = {
    Text = "Meskipun harus mengorbankan nyawa sendiri, hal itu tetap tak terhindarkan…"
  },
  AvgDialog_60347_Content_27 = {
    Text = "Dekster mengangkat kepalanya, menghela napas pelan, seakan sedang mengingat sesuatu."
  },
  AvgDialog_60347_Content_28 = {
    Text = "Itu juga merupakan sebuah pilihan, sebuah alur cerita."
  },
  AvgDialog_60347_Content_29 = {
    Text = "Tapi jika dia benar-benar diselamatkan, bukankah cerita ini akan kehilangan satu adegan besar yang menarik untuk diikuti?"
  },
  AvgDialog_60347_Content_3 = {
    Text = "Ceritamu dengan Thais, aku pernah mendengarnya."
  },
  AvgDialog_60347_Content_30 = {
    Text = "Kepedulian, kerinduan, kesedihan… semua emosi menghilang dari wajah Dexter."
  },
  AvgDialog_60347_Content_31 = {
    Text = "Kamu melihat, dia memberimu senyuman yang sempurna, tanpa sedikit pun kehangatan."
  },
  AvgDialog_60347_Content_32 = {
    Text = "Profesor Dexter pasti tidak akan mengatakan hal seperti ini… Siapa sebenarnya kamu?!"
  },
  AvgDialog_60347_Content_33 = {
    Text = "Dia berdiri di hadapanmu, sepasang mata yang sudah tidak asing lagi memandangmu dengan senyuman yang terasa asing."
  },
  AvgDialog_60347_Content_34 = {
    Text = "Sebuah asap hitam mengepul dari tubuhnya, perlahan membungkusnya."
  },
  AvgDialog_60347_Content_35 = {
    Text = "Benar, siapa aku ini……"
  },
  AvgDialog_60347_Content_36 = {
    Text = "Pemegang saham yang royal. Ayah yang sangat mencintai putrinya. Playboy terkenal. Profesor Misashe yang cukup populer."
  },
  AvgDialog_60347_Content_37 = {
    Text = "Seorang aktor yang sangat berdedikasi. Selama dua puluh tahun, ia memerankan karakter yang sama demi keindahan perubahan dalam cerita, tanpa sedikit pun menunjukkan rasa malas."
  },
  AvgDialog_60347_Content_38 = {
    Text = "Sekarang……"
  },
  AvgDialog_60347_Content_39 = {
    Text = "Para penonton tercinta, tolong berikan saya tepuk tangan yang paling meriah."
  },
  AvgDialog_60347_Content_4 = {
    Text = "Maaf jika mengganggu, tapi sekarang bukan waktu yang tepat untuk tenggelam dalam perasaan ini."
  },
  AvgDialog_60347_Content_40 = {
    Text = "Kabut hitam menyelimuti, seperti sorakan."
  },
  AvgDialog_60347_Content_41 = {
    Text = "Yang muncul di hadapanmu adalah wajah yang pernah kau lihat, wajah yang telah membawa banyak mimpi buruk kepadamu."
  },
  AvgDialog_60347_Content_42 = {
    Text = "Di wajah tanpa fitur, mulut yang tersenyum itu terbuka lebar-lebar, menikmati rasa keterkejutan dan ketakutanmu dengan penuh nafsu."
  },
  AvgDialog_60347_Content_43 = {
    Text = "Kamu adalah… N!"
  },
  AvgDialog_60347_Content_44 = {
    Text = "Sebuah sebutan, bagi ribuan inkarnasi saya, ini adalah sebuah penghinaan… tapi terserah kamu mau memanggil saya apa."
  },
  AvgDialog_60347_Content_45 = {
    Text = "Apa yang telah kau lakukan terhadap Profesor Dexter!"
  },
  AvgDialog_60347_Content_46 = {
    Text = "Profesor Dexter? Siapa itu Profesor Dexter?"
  },
  AvgDialog_60347_Content_47 = {
    Text = "Penjaga, apakah kamu dan Ramona... apakah kalian benar-benar mengenal Dexter?"
  },
  AvgDialog_60347_Content_48 = {
    Text = "Apa maksudmu... bagaimana mungkin kita... apa?!"
  },
  AvgDialog_60347_Content_49 = {
    Text = "Kamu teringat perkataan N. Selama bertahun-tahun, dia selalu memerankan peran yang sama…"
  },
  AvgDialog_60347_Content_5 = {
    Text = "Aku dan dia bukan..."
  },
  AvgDialog_60347_Content_50 = {
    Text = "Murid berkontraksi dengan hebat. Kamu tiba-tiba mengangkat kepala dan menatap wajah N yang tanpa fitur."
  },
  AvgDialog_60347_Content_51 = {
    Text = "Hebat, Penjaga. Inilah Ekspresi yang tepat!"
  },
  AvgDialog_60347_Content_52 = {
    Text = "Jangan bergerak, tetap seperti itu. Ya, benar… biarkan aku mengingatmu seperti ini…"
  },
  AvgDialog_60347_Content_53 = {
    Text = "Sayang sekali, Ramona belum tersadar ketika dia mengetahui hal ini. Aku hanya melihat air matanya."
  },
  AvgDialog_60347_Content_54 = {
    Text = "Saya pikir, ekspresi di wajahnya saat itu pasti lebih hidup dan menarik daripada milikmu."
  },
  AvgDialog_60347_Content_55 = {
    Text = "Tubuh N bergetar sedikit, sepertinya dia sedang bertahan dari gelombang tawa yang sangat kuat."
  },
  AvgDialog_60347_Content_56 = {
    Text = "Dia membungkuk, mendekatkan wajahnya ke arahmu, dan mengamati dengan saksama."
  },
  AvgDialog_60347_Content_57 = {
    Text = "Kamu... mengapa mengendalikan Profesor Dexter?"
  },
  AvgDialog_60347_Content_58 = {
    Text = "Kontrol? Ah, tidak. Kontrol adalah bentuk hiburan yang rendah."
  },
  AvgDialog_60347_Content_59 = {
    Text = "Seorang aktor yang luar biasa harus memerankan dan menjadi."
  },
  AvgDialog_60347_Content_6 = {
    Text = "Tidak perlu penjelasan. Apa pun caranya, bisa mendapatkan kembali kekuasaan adalah hal yang baik."
  },
  AvgDialog_60347_Content_60 = {
    Text = "Dia mendekatkan diri ke telingamu, berbisik pelan seolah ingin berbagi rahasia besar denganmu——"
  },
  AvgDialog_60347_Content_61 = {
    Text = "Dexter sudah meninggal, dia meninggal pada hari dia menyelamatkan Ramona."
  },
  AvgDialog_60347_Content_62 = {
    Text = "Selama bertahun-tahun, kamu dan Ramona pasti sangat menikmati waktu bersamaku, kan?"
  },
  AvgDialog_60347_Content_63 = {
    Text = "Wajahnya menghadapmu. Di wajah yang kosong itu, kamu seolah-olah dengan jelas melihat fitur wajahnya yang sombong dan mendominasi."
  },
  AvgDialog_60347_Content_64 = {
    Text = "Dia membungkuk untuk mengamati dengan saksama, seolah-olah ingin mengingat setiap ekspresi, setiap gemetar yang tak terkendali."
  },
  AvgDialog_60347_Content_65 = {
    Text = "Seorang playboy yang flamboyan, sekaligus ayah yang penuh kasih. Awalnya, saya tidak terlalu tertarik pada karakter seperti ini."
  },
  AvgDialog_60347_Content_66 = {
    Text = "Yang aku minati hanyalah dia... \"anak\" ku. Relik kembar Tawil, Ramona."
  },
  AvgDialog_60347_Content_67 = {
    Text = "N tertawa sambil menatap ke arah tengah Kolam Hitam, ke arah Tawil."
  },
  AvgDialog_60347_Content_68 = {
    Text = "Kamu... kenapa kamu tega membunuhnya..."
  },
  AvgDialog_60347_Content_69 = {
    Text = "Betapa menyedihkannya kesalahpahamanmu, Penjaga."
  },
  AvgDialog_60347_Content_7 = {
    Text = "Saya... ah, malas berdiskusi denganmu tentang ini. Kita sebaiknya... aah!..."
  },
  AvgDialog_60347_Content_70 = {
    Text = "Rencana dari kembaran bersaudara dengan lentera, bukanlah sesuatu yang bisa dengan mudah dihadapi oleh seorang playboy lemah tanpa kekuatan. Namun, dia bahkan berhasil mencuri bayi perempuan itu."
  },
  AvgDialog_60347_Content_71 = {
    Text = "Saat melihatku, tatapannya seperti melihat penyelamat... Ha."
  },
  AvgDialog_60347_Content_72 = {
    Text = "N mengingat kembali cerita itu dan tersenyum dengan gembira."
  },
  AvgDialog_60347_Content_73 = {
    Text = "Dia membuat kesepakatan denganku. Apakah kamu berani mempercayainya? Seorang manusia biasa yang hampir mati, membuat kesepakatan denganku…"
  },
  AvgDialog_60347_Content_74 = {
    Text = "Dia memberikan segalanya kepadaku. Hartanya, statusnya, putrinya…"
  },
  AvgDialog_60347_Content_75 = {
    Text = "Dia meminta saya untuk berperan sebagai dirinya, sebagai ayah dari anaknya."
  },
  AvgDialog_60347_Content_76 = {
    Text = "Dia meninggal sambil memeluk bayi perempuan itu. Di detik-detik terakhirnya, dia terus bergumam tentang bagaimana seorang ayah akan melindunginya dengan baik dan hal-hal semacam itu…"
  },
  AvgDialog_60347_Content_77 = {
    Text = "Mata-mata di dalam Mythag… apakah itu kamu?"
  },
  AvgDialog_60347_Content_78 = {
    Text = "Melihat matamu yang dipenuhi keraguan dan kemarahan, N mengangkat bahu dengan sikap tak peduli."
  },
  AvgDialog_60347_Content_79 = {
    Text = "Itu aku, bukan aku, apa pentingnya? Sulit dipercaya bahwa sampai sekarang kamu masih punya suasana hati untuk memikirkan hal-hal seperti ini."
  },
  AvgDialog_60347_Content_8 = {
    Text = "Kamu baru saja bersiap untuk berdiri ketika rasa sakit yang menyayat di dalam tubuhmu membuatmu menghirup udara dingin."
  },
  AvgDialog_60347_Content_80 = {
    Text = "Berperan sebagai Dexter, bisa berada dekat dengan Mythag ternyata memberikan kemudahan yang cukup baik."
  },
  AvgDialog_60347_Content_81 = {
    Text = "Tempat ini benar-benar seperti taman bermain paling menarik di dunia."
  },
  AvgDialog_60347_Content_82 = {
    Text = "Lihatlah ekspresi kalian saat menyadari telah ditipu olehku. Lihatlah kehancuran Tawil saat rencananya gagal."
  },
  AvgDialog_60347_Content_83 = {
    Text = "Tentu saja, dan kamu juga."
  },
  AvgDialog_60347_Content_84 = {
    Text = "N menjentikkan jarinya. Air dari Kolam Hitam dengan lembut terangkat, membentuk panggung kejam di depan mata Anda."
  },
  AvgDialog_60347_Content_85 = {
    Text = "Dia menatapmu, menjilati bibirnya, seperti anak kecil yang tak berdosa, memandangi sebuah mainan yang akan segera hancur."
  },
  AvgDialog_60347_Content_86 = {
    Text = "Thais memberikan benihnya padamu, dia sungguh percaya bahwa kau bisa membantunya bertahan hidup… Hah, wanita gila ini."
  },
  AvgDialog_60347_Content_87 = {
    Text = "Sayang sekali, dia mempercayai orang yang salah. Kekuasaan atas Keinginan, aku akan mengambilnya."
  },
  AvgDialog_60347_Content_88 = {
    Text = "Mari aku lihat, ketika harapan yang berkobar direnggut, ekspresi seperti apa yang akan muncul di wajahmu?"
  },
  AvgDialog_60347_Content_9 = {
    Text = "Kekuatan dari tiga badan sangatlah besar, adaptasi tidak akan begitu cepat. Kamu perlu menunggu selama beberapa waktu."
  },
  AvgDialog_60348_Content_1 = {
    Text = "Ini adalah pintu masuk ke Kolam Hitam."
  },
  AvgDialog_60348_Content_10 = {
    Text = "Kamu menarik napas dalam-dalam, merenungkan langkah selanjutnya."
  },
  AvgDialog_60348_Content_11 = {Text = "Alistair"},
  AvgDialog_60348_Content_12 = {
    Text = "Sebelum mencari Juliette, kita perlu memahami situasi di dalam Kolam Hitam terlebih dahulu, kemudian berusaha semaksimal mungkin untuk menstabilkan Kolam Hitam dan memulihkan Kekuatan."
  },
  AvgDialog_60348_Content_13 = {
    Text = "Kedua hal ini membutuhkan bantuan Guru Alistair. Mari kita temukan dia terlebih dahulu."
  },
  AvgDialog_60348_Content_14 = {
    Text = "Penjaga Rahasia!"
  },
  AvgDialog_60348_Content_15 = {
    Text = "Alva membuat gestur untuk berdiam diri."
  },
  AvgDialog_60348_Content_16 = {
    Text = "Di arah yang dia tunjuk, seorang anggota Komite berada di pintu masuk Kolam Hitam."
  },
  AvgDialog_60348_Content_17 = {
    Text = "Tampaknya perjalanan ini tidak akan semudah itu… Bersiap untuk menyerang."
  },
  AvgDialog_60348_Content_2 = {
    Text = "Hameln, apakah kamu tahu di mana Juliette sekarang?"
  },
  AvgDialog_60348_Content_3 = {
    Text = [[
Mereka perlu menggunakan Kekuatan Tawil untuk Memanggil Anak Suci Kembar. 
 Persiapan untuk ritual tersebut seharusnya juga dilakukan di tempat yang paling mudah untuk meminjam Kekuatan Tawil.]]
  },
  AvgDialog_60348_Content_4 = {
    Text = "Di dekat Tawil, saya mengerti. Kita akan pergi sekarang…"
  },
  AvgDialog_60348_Content_5 = {
    Text = "Belum saatnya."
  },
  AvgDialog_60348_Content_6 = {
    Text = "Juliette kali ini datang ke Mythag dengan mengerahkan seluruh kekuatannya. Kemampuan yang dia miliki, bahkan aku pun tidak bisa sepenuhnya memahaminya."
  },
  AvgDialog_60348_Content_7 = {
    Text = "Kekuatanmu telah hilang secara signifikan. Seorang pemain musik dengan kelemahan tidak akan mampu memainkan melodi yang kuat."
  },
  AvgDialog_60348_Content_8 = {
    Text = "Jika kamu gagal, panggung Mythag ini akan lenyap."
  },
  AvgDialog_60348_Content_9 = {
    Text = "Kamu benar, aku tidak memiliki kesempatan kedua."
  },
  AvgDialog_60349_Content_1 = {
    Text = "Seiring dengan hilangnya cahaya Kunci perak, N terjatuh ke tanah."
  },
  AvgDialog_60349_Content_10 = {
    Text = "Kabut hitam kembali berkumpul di hadapanmu. N menatapmu dan menggelengkan kepala dengan penuh penyesalan."
  },
  AvgDialog_60349_Content_11 = {
    Text = "Waktu yang penuh kebahagiaan selalu terasa begitu singkat. Perpisahan seorang aktor hebat sungguh membuat orang merasa hampa..."
  },
  AvgDialog_60349_Content_12 = {
    Text = "Namun, sebagai seorang penonton yang bertanggung jawab, kita harus melupakan cerita sebelumnya dan dengan serius menantikan pertunjukan berikutnya."
  },
  AvgDialog_60349_Content_13 = {
    Text = "Ramona dan Tawil, pertunjukan yang luar biasa ini akan segera dimulai."
  },
  AvgDialog_60349_Content_14 = {
    Text = "Sebelumnya, Anda memiliki waktu tiga puluh detik untuk menyampaikan dialog penutup Anda, Penjaga {Male=tuan,Female=nyonya}."
  },
  AvgDialog_60349_Content_15 = {
    Text = "N sambil berbicara, memperbaiki bentuk mawar di tangannya, seakan-akan sedang menyiapkan sebuah hadiah perpisahan yang akan diberikan pada upacara pemakaman."
  },
  AvgDialog_60349_Content_16 = {
    Text = "Aku mengambil kembali kekuasaan untuk menyelamatkan Mythag, menyelamatkan orang-orang di sekitarku… dan juga segalanya di dunia ini, termasuk kamu!"
  },
  AvgDialog_60349_Content_17 = {
    Text = "Dua puluh detik."
  },
  AvgDialog_60349_Content_18 = {
    Text = "N mendekatkan hidungnya yang seolah-olah tak terlihat ke mawar itu, menghirup dalam-dalam, lalu menghela napas dengan puas."
  },
  AvgDialog_60349_Content_19 = {
    Text = "Dua puluh tahun… kamu sudah bersama Mythag selama dua puluh tahun. Meskipun kamu sama sekali tidak memedulikan orang lain, bagaimana dengan Ramona?"
  },
  AvgDialog_60349_Content_2 = {
    Text = "Hu... akhirnya..."
  },
  AvgDialog_60349_Content_20 = {
    Text = "Aku tidak percaya, kamu benar-benar tidak memiliki sedikit pun perasaan terhadap Ramona…"
  },
  AvgDialog_60349_Content_21 = {
    Text = "Sepuluh detik."
  },
  AvgDialog_60349_Content_22 = {
    Text = "Dia dengan lembut meletakkan mawar di atas dadamu."
  },
  AvgDialog_60349_Content_23 = {
    Text = "Keadilan? Tanggung jawab? Keinginan? Emosi?"
  },
  AvgDialog_60349_Content_24 = {
    Text = "Begitu banyak kata-kata yang menggerakkan manusia melintas di benakmu. Namun, tak satu pun dari mereka sesuai untuk N."
  },
  AvgDialog_60349_Content_25 = {
    Text = "Apa yang dia inginkan... Apa yang dia kejar..."
  },
  AvgDialog_60349_Content_26 = {
    Text = "Tiga detik."
  },
  AvgDialog_60349_Content_27 = {
    Text = "Dia mencabut sehelai kelopak mawar. Kelopak itu berubah menjadi mata pisau yang tajam, mengancam lehermu."
  },
  AvgDialog_60349_Content_28 = {
    Text = "Tawil memberitahuku, Dia memilih untuk mengamati. Dia tidak peduli tentang kehidupan, juga tidak peduli tentang kematian. Selain menyenangkan diri-Nya sendiri, Dia tidak peduli tentang apa pun."
  },
  AvgDialog_60349_Content_29 = {
    Text = "Mata pisaumu menggores lehermu. Kamu dengan jelas merasakan sensasi menyengat itu. Kamu tiba-tiba membuka mata lebar-lebar."
  },
  AvgDialog_60349_Content_3 = {
    Text = "N, aku ada sesuatu yang ingin..."
  },
  AvgDialog_60349_Content_30 = {
    Text = "Membosankan"
  },
  AvgDialog_60349_Content_31 = {
    Text = "Membosankan!"
  },
  AvgDialog_60349_Content_32 = {Text = "Hmm?"},
  AvgDialog_60349_Content_33 = {
    Text = "Pilihanmu... sangat membosankan..."
  },
  AvgDialog_60349_Content_34 = {Text = "Oh?"},
  AvgDialog_60349_Content_35 = {
    Text = "Mata pisaunya berhenti di lehermu. N sedang menunggu."
  },
  AvgDialog_60349_Content_36 = {
    Text = "Bencana terakhir akan datang... Dalam bencana ini, tidak ada seorang pun yang akan mendapat keuntungan..."
  },
  AvgDialog_60349_Content_37 = {
    Text = "Tetapi, bagaimana jika ada seseorang yang dapat menghentikan bencana ini?"
  },
  AvgDialog_60349_Content_38 = {
    Text = "Kamu... apa yang kamu katakan?"
  },
  AvgDialog_60349_Content_39 = {
    Text = "Aku bisa. Apapun bencana ini, aku akan menghentikan Kedatangannya!"
  },
  AvgDialog_60349_Content_4 = {Text = "!!!"},
  AvgDialog_60349_Content_40 = {
    Text = "Sukses, atau kegagalan... baik yang mana pun, bagi kamu, ini adalah sandiwara yang paling menarik."
  },
  AvgDialog_60349_Content_41 = {
    Text = "Hohoho... kamu? Hahahaha!"
  },
  AvgDialog_60349_Content_42 = {
    Text = "N seolah mendengar lelucon terbesar di dunia. Dia memegangi perutnya, tertawa terbahak-bahak hingga tubuhnya terguncang ke depan dan belakang."
  },
  AvgDialog_60349_Content_43 = {
    Text = "Tawa yang liar terus-menerus bergema di panggung Kolam Hitam yang kosong."
  },
  AvgDialog_60349_Content_44 = {
    Text = "Kamu benar-benar tidak tahu apa yang sedang kamu bicarakan!"
  },
  AvgDialog_60349_Content_45 = {
    Text = "Saya memang tidak tahu. Namun, hal itu tidak memengaruhi kebenaran pernyataan ini."
  },
  AvgDialog_60349_Content_46 = {
    Text = "N, sebenarnya kamu sudah memikirkannya sejak lama. Kamu tak pernah berniat untuk membunuhku."
  },
  AvgDialog_60349_Content_47 = {
    Text = "Berikan aku tiga puluh detik, aku hanya ingin mengatakannya. Benar, kan?"
  },
  AvgDialog_60349_Content_48 = {
    Text = "Setelah waktu yang lama, N akhirnya berhenti tertawa. Dia menghirup napas dalam-dalam dan menatapmu dengan serius."
  },
  AvgDialog_60349_Content_49 = {
    Text = "Maaf, saya kehilangan kendali…"
  },
  AvgDialog_60349_Content_5 = {
    Text = "Sebelum kamu sempat bereaksi, tubuh di tanah berubah menjadi kabut hitam dan menghilang di tempat."
  },
  AvgDialog_60349_Content_50 = {
    Text = "Kamu benar, Penjaga. Sangat tepat. Di dunia ini, tidak akan ada hal yang lebih menyenangkan dari ini."
  },
  AvgDialog_60349_Content_51 = {
    Text = "Dia tersenyum dan menyerahkan mawar ke tanganmu."
  },
  AvgDialog_60349_Content_52 = {Text = "Ini……?"},
  AvgDialog_60349_Content_53 = {
    Text = "Sambil bertanya, kamu tanpa sadar menyentuh mawar itu."
  },
  AvgDialog_60349_Content_54 = {
    Text = "Pada saat menyentuh kelopak bunga, tawa yang tak terhitung jumlahnya bergema di telingamu secara bersamaan."
  },
  AvgDialog_60349_Content_55 = {
    Text = "Kasar, anggun, tajam, membosankan... Berbagai macam tawa bergabung menjadi pasukan badut yang kacau, berpesta dansa di atas gendang telingamu."
  },
  AvgDialog_60349_Content_56 = {
    Text = "Pikiranmu terhenti, rasa sakit seperti mata pisaunya menusuk sarafmu."
  },
  AvgDialog_60349_Content_57 = {
    Text = "Di tengah tawa yang keras, kacau, dan hampir membuatmu terjerumus dalam kegilaan, kata-kata N masih jelas terdengar di benakmu."
  },
  AvgDialog_60349_Content_58 = {
    Text = "Hak untuk bersenang-senang, nikmatilah dengan baik."
  },
  AvgDialog_60349_Content_59 = {
    Text = "Aku akan menunggu dengan tenang. Saat pertunjukan besar ini dimulai, aku pasti akan berada di bawah panggung, memberikan tepuk tangan paling meriah untukmu."
  },
  AvgDialog_60349_Content_6 = {
    Text = "Akhirnya, kejatuhan sang pahlawan."
  },
  AvgDialog_60349_Content_7 = {Text = "BRAK—"},
  AvgDialog_60349_Content_8 = {
    Text = "Hantaman keras membuat tubuhmu hampir terlepas."
  },
  AvgDialog_60349_Content_9 = {
    Text = "Luka sepanjang jalan, tekanan berat dari kekuasaan nafsu, dan dampak roh yang dibawa oleh Kolam Hitam membuatmu tidak tahan lagi, jatuh tersungkur dalam penderitaan tanpa sedikit pun kekuatan untuk bangkit."
  },
  AvgDialog_60350_Content_1 = {
    Text = "Kekuatan Thais tampaknya tidak ada habisnya. Tekanan yang terus meningkat membuatmu merasa sesak napas."
  },
  AvgDialog_60350_Content_10 = {
    Text = "Saya tidak tahu, Thais. Tapi saya tahu, saya tidak akan menyerah."
  },
  AvgDialog_60350_Content_11 = {
    Text = "Apakah kamu bersedia menyerahkan kekuasaan padaku? Itu adalah pilihanmu, aku tidak akan memaksamu."
  },
  AvgDialog_60350_Content_12 = {
    Text = "Ini adalah benih paling berharga milikmu, berikanlah kepada orang yang paling berharap bisa melarikan diri dari sini…"
  },
  AvgDialog_60350_Content_13 = {
    Text = "Saya tidak akan pernah melepaskan tempat ini. Bagaimanapun, saya akan berjuang sampai akhir melawan setiap sesuatu yang ingin menghancurkan tempat ini……"
  },
  AvgDialog_60350_Content_14 = {
    Text = "Tapi... kenapa?"
  },
  AvgDialog_60350_Content_15 = {
    Text = "Apa ada hal yang lebih penting daripada bertahan hidup?"
  },
  AvgDialog_60350_Content_16 = {
    Text = "Membiarkan aku menyerah pada dunia ini, menyerah pada orang-orang di sekitarku, menyerah pada Pembangun, menyerah padamu, aku tidak bisa…"
  },
  AvgDialog_60350_Content_17 = {
    Text = "Seperti, kamu juga tidak pernah menyerah pada Alan."
  },
  AvgDialog_60350_Content_19 = {
    Text = "Sejak ledakan itu, semua memori saya berhubungan dengan kalian. Kalian adalah segalanya bagi saya."
  },
  AvgDialog_60350_Content_2 = {
    Text = "Anakku, hidupku, tak terbatas... Kau tak akan mampu mengalahkanku, Penjaga."
  },
  AvgDialog_60350_Content_20 = {
    Text = "Aku pernah kehilangan hidupku sekali. Mati demi melindungi segala yang kumiliki, atau hidup dengan melepaskan semuanya, aku hanya punya satu pilihan."
  },
  AvgDialog_60350_Content_21 = {
    Text = "Thais terdiam menatap matamu, menatapnya lama."
  },
  AvgDialog_60350_Content_22 = {
    Text = "Saya bisa membedakan kebohongan... apa yang kamu katakan adalah benar, Penjaga."
  },
  AvgDialog_60350_Content_23 = {
    Text = "Tampaknya, aku telah mempercayai orang yang salah. Kau memang bukan orang yang dapat membawaku ke dunia baru…"
  },
  AvgDialog_60350_Content_24 = {
    Text = "Thais menghela napas dengan rasa kecewa."
  },
  AvgDialog_60350_Content_25 = {
    Text = "Dia datang ke sisimu."
  },
  AvgDialog_60350_Content_26 = {
    Text = "Thais, kau ingin... uh—"
  },
  AvgDialog_60350_Content_27 = {
    Text = "Sebuah benda yang hangat dan lembut menyumbat mulutmu."
  },
  AvgDialog_60350_Content_28 = {
    Text = "Sebuah objek berbentuk bola perlahan-lahan muncul dari mulut Thais dan bergeser dengan pelan."
  },
  AvgDialog_60350_Content_29 = {
    Text = "Itu melewati mulutmu, tenggorokanmu, dan kerongkonganmu. Ia berubah menjadi angin musim semi yang menyapu setiap organ di dalam tubuhmu, hingga ke ujung-ujung pembuluh darahmu."
  },
  AvgDialog_60350_Content_3 = {
    Text = "Menyerahlah, semua usaha hanyalah sia-sia. Jangan coba melawan-Nya lagi."
  },
  AvgDialog_60350_Content_30 = {
    Text = "Entah berapa lama telah berlalu. Thais melepaskanmu, lalu menjulurkan lidahnya dan dengan lembut menjilat bibirnya."
  },
  AvgDialog_60350_Content_31 = {Text = "Thais...?"},
  AvgDialog_60350_Content_32 = {
    Text = "Barusan... itu..."
  },
  AvgDialog_60350_Content_33 = {
    Text = "Kamu adalah seorang pembohong, orang bodoh, %player%. Kamu sama sekali tidak mampu mengalahkan-Nya. Kamu tidak memiliki hak untuk menatap mata-Nya…"
  },
  AvgDialog_60350_Content_34 = {
    Text = "Tapi, kamu memang orang seperti itu. Apa lagi yang bisa aku lakukan?"
  },
  AvgDialog_60350_Content_35 = {
    Text = "Thais menghela napas pelan. Napasnya lembut menyapu wajahmu, semanis angin musim semi yang berembus di dalam tubuh."
  },
  AvgDialog_60350_Content_36 = {
    Text = "Di dalam benih ini, terdapat kekuasaan yang menguasai keinginan."
  },
  AvgDialog_60350_Content_37 = {
    Text = "Aku sudah memberikannya padamu lama... Hadiah yang sudah diberikan, tidak ada alasan untuk mengambilnya kembali."
  },
  AvgDialog_60350_Content_38 = {
    Text = "Dia menopang dagumu, memandangmu dengan rasa ingin tahu, lalu perlahan mengangkat sudut bibirnya."
  },
  AvgDialog_60350_Content_39 = {
    Text = "Aku akan mengamati kamu, Penjaga."
  },
  AvgDialog_60350_Content_4 = {
    Text = "Saya percaya padamu. Mari kita bersama-sama menuju dunia baru yang bebas dari kekhawatiran…"
  },
  AvgDialog_60350_Content_40 = {
    Text = "Aku akan mengamati kamu, dengan teguh melangkah di jalan ini yang tak terelakkan... Aku akan meratapi kamu di pemakamanmu."
  },
  AvgDialog_60350_Content_41 = {
    Text = "Tanpa adanya Benih sebagai penopang, tubuh yang terbuat dari pasir kuning tidak bisa lagi bertahan."
  },
  AvgDialog_60350_Content_42 = {
    Text = "Di tengah hembusan angin musim semi yang lembut, sosok Thais berubah menjadi butiran pasir yang menyebar dan jatuh, seperti sebuah desahan yang lembut."
  },
  AvgDialog_60350_Content_5 = {
    Text = "Sebelumnya, aku tidak mengerti tujuanmu menanam Benih."
  },
  AvgDialog_60350_Content_6 = {
    Text = "Aku tidak akan menyetujui permintaanmu, Thais."
  },
  AvgDialog_60350_Content_7 = {
    Text = "Lihat dirimu sendiri, Penjaga… bahkan aku, yang terbentuk dari Benih, dapat membuatmu jatuh ke dalam keadaan yang begitu memalukan."
  },
  AvgDialog_60350_Content_8 = {
    Text = "Meskipun kamu telah mengambil kembali semua kekuasaan, kamu hanyalah sebuah Fragmen saja… apa yang bisa kamu lakukan?"
  },
  AvgDialog_60350_Content_9 = {
    Text = "Aku tidak akan menyerah, Thais"
  },
  AvgDialog_60351_Content_1 = {
    Text = "Ayah dan Anak Perempuan"
  },
  AvgDialog_60351_Content_10 = {
    Text = "Tawil... aku... pernah melihatmu..."
  },
  AvgDialog_60351_Content_11 = {
    Text = "Herbert berkata, aku adalah Relik kembar dari penerang kuil, Gereja penerang kuil ada untukku…"
  },
  AvgDialog_60351_Content_12 = {
    Text = "Dia tidak berbohong. Di sisi lain dari kembar, adalah aku."
  },
  AvgDialog_60351_Content_13 = {
    Text = "...Begitu ya."
  },
  AvgDialog_60351_Content_14 = {
    Text = "Kamu tidak terkejut."
  },
  AvgDialog_60351_Content_15 = {
    Text = [[
Saya memiliki beberapa dugaan. 
 Herbert berkata bahwa saya adalah relik penting dari Gereja Penerang Kuil, dan saya dilahirkan di Kolam Hitam.]]
  },
  AvgDialog_60351_Content_16 = {
    Text = "Dan, aku pernah melihatmu. Melihat wajahmu..."
  },
  AvgDialog_60351_Content_17 = {
    Text = "Spekulasi kamu sepenuhnya benar."
  },
  AvgDialog_60351_Content_18 = {
    Text = "Di mana ini?"
  },
  AvgDialog_60351_Content_19 = {
    Text = "Kesadaran, mimpi, kumpulan tak terhitung waktu dan dimensi, tempat bertemunya segala hal rasional dan irasional."
  },
  AvgDialog_60351_Content_2 = {
    Text = "Cahaya. Warna."
  },
  AvgDialog_60351_Content_20 = {
    Text = "Ini adalah singularitas yang tak terbayangkan... tempat persembunyianku."
  },
  AvgDialog_60351_Content_21 = {
    Text = [[
Tempat persembunyian... 
 Apa yang kamu sembunyikan?]]
  },
  AvgDialog_60351_Content_22 = {
    Text = "Sebuah pandangan. Sebuah pandangan dari Kehendak Tertinggi."
  },
  AvgDialog_60351_Content_23 = {
    Text = "Sebuah... pandangan?"
  },
  AvgDialog_60351_Content_24 = {
    Text = "Berdasarkan pemahamanmu, kamu bisa membayangkan-Nya sebagai bayi yang sedang tidur."
  },
  AvgDialog_60351_Content_25 = {
    Text = [[
Semesta tempat kita berada, seluruh Planet dan peradaban, hanyalah sebuah Mimpi bagi-Nya. 
 Pada saat Dia terbangun, seluruh semesta akan lenyap tanpa bekas.]]
  },
  AvgDialog_60351_Content_26 = {
    Text = "Apa... alam semesta kita?!"
  },
  AvgDialog_60351_Content_27 = {
    Text = "Tawil tidak menunjukkan sedikit pun jeda karena keterkejutan Ramona. Suaranya terus terdengar dari setiap sudut ruang ini."
  },
  AvgDialog_60351_Content_28 = {
    Text = "Bagi-Nya, semua keberadaan adalah suara bising, dan keberadaan tiga massa utama terlalu kuat, sehingga sangat mudah membangunkan-Nya dari mimpi ilusi."
  },
  AvgDialog_60351_Content_29 = {
    Text = "Oleh karena itu, aku harus bersembunyi. Bersembunyi di luar Mimpi-Nya."
  },
  AvgDialog_60351_Content_3 = {
    Text = "Sebuah sungai ilusi mengalir di hadapan Ramona."
  },
  AvgDialog_60351_Content_30 = {
    Text = "Oleh karena itu, aku tidak dapat secara langsung ikut campur dalam segala sesuatu yang terjadi di dunia kalian."
  },
  AvgDialog_60351_Content_31 = {
    Text = "Gereja penerang kuil ingin memanggil patung kembar dewa, dan itu adalah kita…"
  },
  AvgDialog_60351_Content_32 = {
    Text = "Mereka… Apakah mereka ingin membangunkan Kehendak Tertinggi dengan membuat keributan?!"
  },
  AvgDialog_60351_Content_33 = {
    Text = "Wajah ilusi Tawil tampaknya memperlihatkan senyuman penuh pujian. Dia mengangguk kepada Ramona."
  },
  AvgDialog_60351_Content_34 = {
    Text = "Kamu adalah Fragmen yang terpisah dari kesadaranku, melalui kamu, mereka akan membawa kesadaranku meninggalkan tempat ini, masuk ke dalam Tubuhmu."
  },
  AvgDialog_60351_Content_35 = {
    Text = "Jika mereka berhasil, pandangan Kehendak Tertinggi akan segera mengunci duniamu…"
  },
  AvgDialog_60351_Content_36 = {
    Text = "Pada saat itu, adegan yang pernah disaksikan oleh Fragmen lain dari diriku akan terjadi lagi."
  },
  AvgDialog_60351_Content_37 = {
    Text = "Tolong beritahu saya, apa yang bisa saya lakukan! Selama bisa mengalahkan Juliette, maka bisa…"
  },
  AvgDialog_60351_Content_38 = {
    Text = "Lentera tidak penting, Ramona. Tanpa lentera, tanpa kembar, tetap akan ada hal lain."
  },
  AvgDialog_60351_Content_39 = {
    Text = "Kedatangan Kehendak Tertinggi tidak terhindarkan. Segala yang kulakukan hanyalah untuk menunda waktu kebangkitan-Nya."
  },
  AvgDialog_60351_Content_4 = {
    Text = "Yang terpampang di hadapan mata adalah waktu, dimensi, serta kesatuan dari rasionalitas dan irasionalitas."
  },
  AvgDialog_60351_Content_40 = {
    Text = "Orang yang dapat menyelamatkan Mythag, serta duniamu, hanyalah {Male=dia,Female=dia}."
  },
  AvgDialog_60351_Content_41 = {
    Text = "Apakah yang Anda maksud... Penjaga?"
  },
  AvgDialog_60351_Content_42 = {
    Text = "Sejak ledakan Akut, {Male=dia,Female=dia} sudah ditakdirkan untuk melangkah di jalan ini."
  },
  AvgDialog_60351_Content_43 = {
    Text = "Ketika patung kembar muncul di dunia, \"Gerbang\" akan muncul."
  },
  AvgDialog_60351_Content_44 = {
    Text = "Pada saat itu, {Male=dia,Female=dia} akan melangkah melewati Pintu, mengetahui semua yang seharusnya {Male=dia,Female=dia} ketahui."
  },
  AvgDialog_60351_Content_45 = {
    Text = "Penjaga… siapa sebenarnya?"
  },
  AvgDialog_60351_Content_46 = {
    Text = "Ekspresi di wajah Tawil kembali menjadi tidak jelas. Dia menggelengkan kepalanya."
  },
  AvgDialog_60351_Content_47 = {
    Text = "Saya adalah pelaksana Tubuh Intelektual, saya hanya mengetahui apa yang Dia izinkan untuk saya ketahui."
  },
  AvgDialog_60351_Content_48 = {
    Text = "Dia membuka matanya dan menatap Ramona dengan serius."
  },
  AvgDialog_60351_Content_49 = {
    Text = "Ramona, kelahiranmu adalah sebuah kesalahan. Hidupmu adalah hasil dari kesimpulan yang salah."
  },
  AvgDialog_60351_Content_5 = {
    Text = "Semua pemahaman bergabung menjadi sungai ilusi, mencuci tubuhnya yang ringan."
  },
  AvgDialog_60351_Content_50 = {
    Text = "Namun, gabungan dari dua kesalahan justru menghasilkan hasil yang benar."
  },
  AvgDialog_60351_Content_51 = {
    Text = "Di antara tak terhitung banyaknya masa depan, bantuanmu kepada {Male=dia,Female=dia} akan menjadi satu-satunya jalan untuk menghindari bencana ini…"
  },
  AvgDialog_60351_Content_52 = {
    Text = "Hmm… sepertinya aku mendengar dia sedang berbicara dengan seseorang?"
  },
  AvgDialog_60351_Content_53 = {
    Text = "Ramona tidak tahu apakah dia sedang terjaga atau tertidur. Suara Tawil sudah menghilang, dan suara lain yang akrab terdengar di telinganya."
  },
  AvgDialog_60351_Content_54 = {Text = "Siapa?!"},
  AvgDialog_60351_Content_55 = {
    Text = "Apa, teman lamaku, tidak mengenalku lagi?"
  },
  AvgDialog_60351_Content_56 = {
    Text = "(Profesor Dexter... Ayah?)"
  },
  AvgDialog_60351_Content_57 = {
    Text = "Herbert tidak tahu bagaimana pria itu bisa tiba-tiba muncul di sisinya."
  },
  AvgDialog_60351_Content_58 = {
    Text = "Di sisinya, Clementine dan anggota Komite mengelilingi Dexter."
  },
  AvgDialog_60351_Content_59 = {
    Text = "Dexter tampaknya tidak melihat pisau dan senjata yang diarahkan padanya, dia langsung berjalan ke sisi Ramona dan memeriksanya sejenak."
  },
  AvgDialog_60351_Content_6 = {
    Text = "Bangunlah. Wahai pembawaku. Fragmenku."
  },
  AvgDialog_60351_Content_60 = {
    Text = "Dulu kau, si pencuri kecil ini, yang merebutnya… Hari ini, kau dan dia tidak akan bisa pergi!"
  },
  AvgDialog_60351_Content_61 = {
    Text = "Aku memaafkan ketidaksopananmu. Lagipula, aku belum berniat untuk mengambil nyawa kalian saat ini."
  },
  AvgDialog_60351_Content_62 = {
    Text = "Tentu saja, kamu tidak perlu khawatir aku akan melakukan sesuatu. Melihat putriku selamat dan sehat membuatku merasa lega. Kalian sudah merawatnya dengan sangat baik, aku tidak menyerah membawanya pergi."
  },
  AvgDialog_60351_Content_63 = {
    Text = "Herbert mengerutkan alisnya, dengan serius menatap mata Dexter, berusaha memahami apa yang sedang dipikirkannya."
  },
  AvgDialog_60351_Content_64 = {
    Text = "Namun, di wajah itu, dia tidak bisa melihat apa pun selain senyuman elegan yang khas seorang pria terhormat."
  },
  AvgDialog_60351_Content_65 = {
    Text = "Dia merasakan semacam aura berbahaya dan membuat isyarat di belakangnya."
  },
  AvgDialog_60351_Content_66 = {
    Text = "Tidak perlu tegang, Tuan Herbert. Tuan Dexter adalah teman kita."
  },
  AvgDialog_60351_Content_67 = {Text = "Teman?"},
  AvgDialog_60351_Content_68 = {
    Text = "Tolong jangan salah paham, Nyonya Juliette. Bertahun-tahun yang lalu, aku sudah menjelaskan dengan sangat jelas kepadamu."
  },
  AvgDialog_60351_Content_69 = {
    Text = "Saya bukan teman kalian. Saya hanyalah seorang penonton."
  },
  AvgDialog_60351_Content_7 = {
    Text = "Ramona membelalakkan mata."
  },
  AvgDialog_60351_Content_70 = {
    Text = "Tipe favorit teater — membeli tiket tahunan untuk balkon, sopan santun, tidak pernah berisik, dan tidak pernah absen."
  },
  AvgDialog_60351_Content_71 = {
    Text = "Dia dengan lembut menepuk bahu Juliette, seperti seorang penonton terhormat yang menyampaikan pujian tulus kepada seorang aktor yang luar biasa."
  },
  AvgDialog_60351_Content_72 = {
    Text = "Nyonya Juliette, senang melihat Anda akhirnya datang untuk menepati janji Anda."
  },
  AvgDialog_60351_Content_73 = {
    Text = "Namun, kalian harus lebih berhati-hati. Aku hanya memiliki satu-satunya putri ini, jadi tolong, jangan biarkan sesuatu terjadi padanya."
  },
  AvgDialog_60351_Content_74 = {
    Text = "Saya sudah menantikan pertunjukan ini selama dua puluh tahun."
  },
  AvgDialog_60351_Content_75 = {
    Text = "Ramona berharap, berharap dia masih berada di ruang Tawil, dan berharap ini adalah mimpi yang absurd."
  },
  AvgDialog_60351_Content_76 = {
    Text = "Namun, dia tidak bisa mengendalikan gemetaran tubuhnya, juga tidak bisa menahan setetes air mata yang jatuh dari sudut matanya, masuk ke dalam Kolam Hitam yang sedang bergolak."
  },
  AvgDialog_60351_Content_77 = {
    Text = "Tetesan air mata yang berkilauan itu terpantul di mata Dexter, memancarkan seberkas cahaya yang mengalir."
  },
  AvgDialog_60351_Content_78 = {
    Text = "Saya masih punya tamu penting yang harus ditemui. Sampai jumpa lagi, semuanya."
  },
  AvgDialog_60351_Content_79 = {
    Text = "Dia tersenyum dan mengangguk kepada semua orang sebagai tanda hormat, lalu menghilang ke dalam Bayangan Kolam Hitam yang tanpa cahaya, tanpa sedikit pun berhenti untuk air mata itu."
  },
  AvgDialog_60351_Content_8 = {
    Text = "Di ruang khayalan ini, sosok yang tengah terbaring di dalam Kolam Hitam menampakkan wajahnya yang terselubung oleh kain tipis."
  },
  AvgDialog_60351_Content_9 = {
    Text = "——Wajah yang sama persis dengan Ramona."
  },
  AvgDialog_60352_Content_1 = {
    Text = "Thais mengangkat tangannya, lalu menaburkan titik-titik cahaya yang mirip dengan benih di hadapanmu."
  },
  AvgDialog_60352_Content_2 = {
    Text = "Titik cahaya menarik pasir kuning, berkumpul menjadi sekelompok Relik yang dikenal."
  },
  AvgDialog_60352_Content_3 = {
    Text = "Makhluk-makhluk yang pernah kamu temui di gurun muncul kembali di hadapanmu dalam wujud yang menakutkan."
  },
  AvgDialog_60352_Content_4 = {
    Text = "Thais! Tenanglah..."
  },
  AvgDialog_60352_Content_5 = {
    Text = "Saya sangat tenang, Penjaga."
  },
  AvgDialog_60352_Content_6 = {
    Text = [[
Hancurkan mereka, tenangkan mereka, meskipun kau melihat fatamorgana-ku, itu tidak masalah.
Setelah itu, aku akan kembali menjadi benih dan masuk ke dalam tubuhmu.]]
  },
  AvgDialog_60352_Content_7 = {
    Text = "Aku akan pergi ke dunia baru bersamamu..."
  },
  AvgDialog_60352_Content_8 = {
    Text = "Dia melambaikan tangan. Makhluk yang terbentuk dari Kolam Hitam menyerangmu dengan ganas…"
  },
  AvgDialog_60353_Content_1 = {Text = "Takdir"},
  AvgDialog_60353_Content_10 = {
    Text = "Durasi dari gerakan ini terbatas, harus disimpan untuk saat yang lebih penting. Dibandingkan dengan kegagalan, rasa sakit tidak ada artinya."
  },
  AvgDialog_60353_Content_11 = {
    Text = "Kamu menghela napas panjang."
  },
  AvgDialog_60353_Content_12 = {
    Text = "Angin musim semi yang lembut dan tawa liar saling bergulung, lalu perlahan mereda. Kemampuan gerakmu sudah pulih cukup banyak."
  },
  AvgDialog_60353_Content_13 = {
    Text = "Dua entitas yang sulit diyakinkan, keduanya telah memberikan kekuasaan kepada saya."
  },
  AvgDialog_60353_Content_14 = {
    Text = "Selanjutnya, hanya tersisa Tubuh Intelektual yang sejak awal berdiri di pihak Mythag…"
  },
  AvgDialog_60353_Content_15 = {
    Text = "Kamu menatap lurus ke depan, memegang erat tinjumu."
  },
  AvgDialog_60353_Content_16 = {
    Text = "Ayo, Hameln. Kita harus mempercepat langkah."
  },
  AvgDialog_60353_Content_17 = {
    Text = "Dekat posisi Tawil, Juliette akan menempatkan pasukan patroli dalam jumlah besar."
  },
  AvgDialog_60353_Content_18 = {
    Text = "Berhati-hatilah."
  },
  AvgDialog_60353_Content_2 = {
    Text = "Ekspresimu terlihat lebih rileks. Pemulihan kekuasaan untuk kedua kalinya, sepertinya kamu beradaptasi dengan baik."
  },
  AvgDialog_60353_Content_3 = {
    Text = "Kamu menahan tawa kegilaan di telinga, tidak bisa menahan diri untuk memutar mata ke arah Hameln."
  },
  AvgDialog_60353_Content_4 = {
    Text = "Masih punya muka untuk bicara... Saat N mengancamku tadi, kenapa aku tidak melihatmu keluar untuk membantuku?"
  },
  AvgDialog_60353_Content_5 = {
    Text = "Meyakinkan N adalah tugasmu. Kamu bisa menanganinya."
  },
  AvgDialog_60353_Content_6 = {
    Text = "N adalah orang yang sombong. Cara komunikasi saya hanya akan menambah kesulitanmu dalam mencapai tujuan."
  },
  AvgDialog_60353_Content_7 = {
    Text = "Kamu cukup memiliki pemahaman yang jelas tentang dirimu sendiri..."
  },
  AvgDialog_60353_Content_8 = {
    Text = "Setiap orang memiliki posisi masing-masing. Jika tidak dapat menjalankan tugas di posisinya, pertunjukan pun tidak akan bisa dilaksanakan."
  },
  AvgDialog_60353_Content_9 = {
    Text = "Kalau begitu, setidaknya gunakan musik untuk meringankan sedikit penderitaanku… Apakah kamu tahu betapa tidak nyamannya hal yang diberikan N kepadaku?"
  },
  AvgDialog_60354_Content_1 = {
    Text = "Huu……huu……"
  },
  AvgDialog_60354_Content_10 = {
    Text = "Perutmu terasa seperti diaduk-aduk dengan kuat. Kamu membuka mulut, dan segumpal kabut pekat keluar dari tubuhmu, menyebar seperti tinta yang menyebar di sungai."
  },
  AvgDialog_60354_Content_11 = {
    Text = "Kabut seperti entitas fisik, berkumpul menjadi sebuah objek berbentuk oval, mirip dengan mata makhluk tertentu."
  },
  AvgDialog_60354_Content_12 = {
    Text = "Mata itu belum sempat terbuka, lalu lenyap dalam cahaya Tawil."
  },
  AvgDialog_60354_Content_13 = {Text = "Ini…"},
  AvgDialog_60354_Content_14 = {
    Text = "Kamu perlahan menurunkan kedua tangan yang menutupi mata. Di depanmu berdiri sosok Tawil yang samar, lalu mengangguk pelan."
  },
  AvgDialog_60354_Content_15 = {
    Text = "Kesalahan pada dirimu telah diperbaiki."
  },
  AvgDialog_60354_Content_16 = {
    Text = "Kesalahan yang kamu maksud, bukan aku? …"
  },
  AvgDialog_60354_Content_17 = {
    Text = "Kesalahan telah menginfeksi tubuhmu. Itu adalah mata yang digunakan oleh Kehendak Tertinggi untuk mengamati dunia ini."
  },
  AvgDialog_60354_Content_18 = {
    Text = "N menyadari keberadaannya. Dia memberikanmu tidak hanya kekuasaan, tetapi juga sebuah kehendak untuk mengendalikanmu."
  },
  AvgDialog_60354_Content_19 = {
    Text = "Saat ini, semua kesalahan tersebut telah diperbaiki. Kamu untuk sementara aman."
  },
  AvgDialog_60354_Content_2 = {
    Text = "Kamu berhasil menahan serangan Tawil."
  },
  AvgDialog_60354_Content_20 = {
    Text = "Ternyata begitu, aku pikir... aku terlalu banyak berpikir."
  },
  AvgDialog_60354_Content_21 = {
    Text = "Kamu menghela napas panjang, lalu berdiri."
  },
  AvgDialog_60354_Content_22 = {
    Text = "Terima kasih……"
  },
  AvgDialog_60354_Content_23 = {
    Text = "Tidak perlu berterima kasih, aku hanya melakukan apa yang seharusnya kulakukan. Hal selanjutnya akan diselesaikan olehmu."
  },
  AvgDialog_60354_Content_24 = {
    Text = "Ada satu hal yang tidak saya pahami."
  },
  AvgDialog_60354_Content_25 = {
    Text = "Kehendak Tertinggi, apa hubungannya dengan aku... kenapa aku yang dipilih? Siapa sebenarnya aku ini?"
  },
  AvgDialog_60354_Content_26 = {
    Text = "Kamu mengerutkan alis, lalu menatap Tawil."
  },
  AvgDialog_60354_Content_27 = {
    Text = "Kebenaran sering kali berarti tanggung jawab, serta juga berarti penderitaan."
  },
  AvgDialog_60354_Content_28 = {
    Text = "Saya bersedia menanggung"
  },
  AvgDialog_60354_Content_29 = {
    Text = "Saya adalah Penjaga Mythag, saya telah bersumpah di depan Key Mound."
  },
  AvgDialog_60354_Content_3 = {
    Text = "Dampak yang begitu kuat membuatmu kehilangan semua tenaga, lalu jatuh berlutut di tanah."
  },
  AvgDialog_60354_Content_30 = {
    Text = "Jika ini adalah sesuatu yang harus aku tanggung, aku bersedia menanggungnya."
  },
  AvgDialog_60354_Content_31 = {
    Text = "Tawil memandangmu dengan mata yang penuh keyakinan, wajahnya berkilauan sedikit, seakan-akan teringat akan sesuatu yang jauh."
  },
  AvgDialog_60354_Content_32 = {
    Text = "Dia adalah Kekacauan primordial, sang Penghancur tanpa kesadaran... Sebagai salah satu Fragmennya, kau berbeda dari Dia."
  },
  AvgDialog_60354_Content_33 = {Text = "?!!"},
  AvgDialog_60354_Content_34 = {
    Text = "Musim semi Akut, kedatanganmu di dunia ini. Aku tidak dapat melihat takdir yang akan kau bawa. Aku pernah berpikir bahwa kau akan menjadi awal dari kehancuran dunia ini."
  },
  AvgDialog_60354_Content_35 = {
    Text = "Aku salah, Penjaga. Kehancuran tidak membutuhkan pemicu. Fragmen Roh-Nya, kesadaran akan keberlangsungan-Nya yang masih samar, akan menjadi satu-satunya solusi."
  },
  AvgDialog_60354_Content_36 = {
    Text = "Fragmen... dari Kehendak Tertinggi..."
  },
  AvgDialog_60354_Content_37 = {
    Text = "Jantung tiba-tiba berdetak kencang. Yang menggelayuti pikiran tampaknya adalah getaran yang berasal dari kedalaman alam semesta."
  },
  AvgDialog_60354_Content_38 = {
    Text = "Bakatmu, sikap tiga kualitas besar terhadapmu… Kamu pasti sudah memikirkan hal ini sebelumnya. Namun, ketika jawabannya benar-benar ada di depanmu, kamu tetap merasakan getaran yang mendalam."
  },
  AvgDialog_60354_Content_39 = {
    Text = "Namun, kamu juga mengerti bahwa ada masalah yang lebih mendesak sekarang, dan kamu perlu menemukan jawabannya."
  },
  AvgDialog_60354_Content_4 = {
    Text = "Kenapa……"
  },
  AvgDialog_60354_Content_40 = {
    Text = "Tawil, tolong beritahu aku, bagaimana aku bisa mendapatkan Kekuatan-Nya… Bagaimana aku bisa menghentikan Kedatangan-Nya!"
  },
  AvgDialog_60354_Content_41 = {
    Text = "Kedatangan Kehendak Tertinggi tidak dapat dihentikan. Penjaga."
  },
  AvgDialog_60354_Content_42 = {
    Text = [[
Tubuh intelektual memahami segala sesuatu, tetapi Dia tidak memberikan semua pengetahuan kepadaku. 
 Mengetahui segalanya bukanlah sebuah kebahagiaan, terkadang hanya akan membawa bencana yang lebih besar.]]
  },
  AvgDialog_60354_Content_43 = {
    Text = "Dalam hal-hal yang saya ketahui, tidak ada jawaban yang kamu butuhkan."
  },
  AvgDialog_60354_Content_44 = {
    Text = "Semua jawaban, semua bencana, berada di balik pintu..."
  },
  AvgDialog_60354_Content_45 = {
    Text = "Sebuah suara bising samar-samar memotong perkataan Tawil. Dia dengan tenang berbalik, tatapannya seolah-olah menembus ruang ini, jatuh ke suatu tempat di luar ruang tersebut."
  },
  AvgDialog_60354_Content_46 = {
    Text = "Di wajah yang indah dan khayal itu, terlihat senyuman penuh kelegaan."
  },
  AvgDialog_60354_Content_47 = {
    Text = "Akhirnya, dia berhasil menemukanku."
  },
  AvgDialog_60354_Content_48 = {
    Text = "Tiba-tiba, sebuah Pelarutan muncul di ruang tersembunyi ini."
  },
  AvgDialog_60354_Content_49 = {
    Text = "Dia? Maksudmu... Juliette?"
  },
  AvgDialog_60354_Content_5 = {
    Text = "Menghilanglah."
  },
  AvgDialog_60354_Content_50 = {
    Text = "Pelarutan dengan kecepatan luar biasa meningkat, secara rakus mencemari setiap sudut ruang ini."
  },
  AvgDialog_60354_Content_51 = {
    Text = "Begitu banyak cairan pelarutan menyerang Tawil seperti predator, berusaha membungkus, mengikat, dan menenggelamkannya."
  },
  AvgDialog_60354_Content_52 = {Text = "Tawil!!"},
  AvgDialog_60354_Content_53 = {
    Text = "Sayap raksasa tiba-tiba terentang, dalam tarikan Pelarutan, dia meloncat ke arahmu dengan cepat ——"
  },
  AvgDialog_60354_Content_54 = {
    Text = "Tarikan cairan pelarutan meninggalkan luka besar di tubuhnya. Cairan hitam di dalam tubuh-Nya bercampur dengan pelarutan, mengubah-Nya menjadi lukisan minyak yang hampa dan kotor."
  },
  AvgDialog_60354_Content_55 = {
    Text = "Di tengah rasa sakit dan kotor ini, Dia dengan tenang menatapmu dan mengulurkan tangan-Nya kepadamu——"
  },
  AvgDialog_60354_Content_56 = {
    Text = "Aku dan Ramona, akan mati untuk sementara atau selamanya."
  },
  AvgDialog_60354_Content_57 = {
    Text = "Setelah kamu meninggalkan tempat ini, kita akan menjadi musuh."
  },
  AvgDialog_60354_Content_58 = {
    Text = "Ujung jari-Nya dengan lembut menyentuh dahi Anda."
  },
  AvgDialog_60354_Content_59 = {
    Text = "Seberkas cahaya murni menyusup ke dalam benakmu, menerangi setiap ujung saraf. Otakmu dipenuhi oleh tak terhitung banyaknya pengetahuan."
  },
  AvgDialog_60354_Content_6 = {
    Text = "Dia mengangkat tangannya."
  },
  AvgDialog_60354_Content_60 = {
    Text = "Kekuatan Thais dan N sebelumnya masih mengamuk di dalam tubuhmu, namun saat cahaya ini masuk, angin yang meraung dan tawa itu tiba-tiba mereda."
  },
  AvgDialog_60354_Content_61 = {
    Text = "Seperti melengkapi potongan puzzle terakhir, tiga Kekuatan mencapai keseimbangan dan kesatuan di dalam dirimu, berkumpul menjadi galaksi yang tenang dan luas."
  },
  AvgDialog_60354_Content_62 = {
    Text = "Tak ada tempat untuk memohon belas kasihan. Tak ada jalan untuk melarikan diri. Inilah takdir dunia ini."
  },
  AvgDialog_60354_Content_63 = {
    Text = "Aku berikan seluruh kekuatan dan otoritas kepadamu, Penjaga."
  },
  AvgDialog_60354_Content_64 = {
    Text = "Kalahkan kami. Bunuh kami. Lalu, selamatkan kami."
  },
  AvgDialog_60354_Content_7 = {
    Text = "Tunggu!——"
  },
  AvgDialog_60354_Content_8 = {
    Text = [[
Cahaya putih yang menyilaukan meledak dari tubuh Tawil.
Kamu tidak bisa melawan, hanya bisa membiarkan cahaya terang itu menembus tubuhmu.]]
  },
  AvgDialog_60354_Content_9 = {Text = "Ukh——"},
  AvgDialog_60356_Content_1 = {
    Text = "Huu……huu……"
  },
  AvgDialog_60356_Content_10 = {
    Text = "Bagaimanapun, aku pasti tidak akan membiarkan rencanamu yang licik berhasil!"
  },
  AvgDialog_60356_Content_11 = {
    Text = "Hameln, lindungi aku!"
  },
  AvgDialog_60356_Content_12 = {
    Text = "Tangan Hameln yang memegang tongkat komando terangkat dengan lembut."
  },
  AvgDialog_60356_Content_13 = {
    Text = "Juliette tidak menunjukkan perubahan ekspresi apapun, tidak peduli berapa banyak bawahannya yang jatuh, dia tetap tersenyum menatapmu, seolah-olah mereka hanyalah bahan-bahan murah untuk menghabiskan kekuatan rohmu."
  },
  AvgDialog_60356_Content_14 = {
    Text = "Kamu tidak berani menunda dan memberikan perintah kepada para Pembangun. Ini adalah kesempatan yang tidak boleh dilewatkan, kamu harus menghancurkannya sekaligus!"
  },
  AvgDialog_60356_Content_15 = {
    Text = "Kamu mengangkat tinggi-tinggi tangan yang memegang kunci perak. Kunci perak itu memancarkan cahaya yang menyilaukan, dan energi roh yang besar mengalir masuk ke dalam tubuh para Pembangun."
  },
  AvgDialog_60356_Content_16 = {
    Text = "Bersiap untuk menyerang!"
  },
  AvgDialog_60356_Content_17 = {
    Text = "Pembangun, siapkan…"
  },
  AvgDialog_60356_Content_18 = {
    Text = "Symphony keempat, berhenti."
  },
  AvgDialog_60356_Content_19 = {
    Text = [[
Suara yang sudah dikenal. Dingin, tegas, dan tak terbantahkan. 
 Tongkat di belakangmu mengetuk dengan lembut, sama anggun dan stabilnya seperti saat berada di atas panggung teater.]]
  },
  AvgDialog_60356_Content_2 = {
    Text = "Tubuhmu gemetar karena kelelahan berlebihan, dan tekanan besar dari tautan roh juga membuat kepalamu terasa sakit secara berkala."
  },
  AvgDialog_60356_Content_20 = {
    Text = "Di bawah instruksi ini, melodi yang menopang stabilitas Roh-mu menghilang, digantikan oleh suara tajam yang menusuk dan berisik."
  },
  AvgDialog_60356_Content_21 = {
    Text = "Suara musik itu pernah menjadi kubah yang melindungi Dunia rohmu, melindungimu dari gelombang Kolam hitam yang mengamuk."
  },
  AvgDialog_60356_Content_22 = {
    Text = "Pada saat itu, kubah tiba-tiba runtuh, berubah menjadi serpihan-serpihan yang tajam, bercampur dengan Kolam hitam yang mendidih, dan bersama-sama menyerang Dunia rohmu."
  },
  AvgDialog_60356_Content_23 = {
    Text = "Aah!!——"
  },
  AvgDialog_60356_Content_24 = {
    Text = "Rasa sakit yang luar biasa membuatmu tak tahan. Tautan lorong antara dirimu dan Pembangun terputus, para Pembangun kehilangan semua Kekuatan mereka seketika, satu per satu jatuh di kaki Juliette."
  },
  AvgDialog_60356_Content_25 = {
    Text = "Kehabisan tenaga akibat pertempuran yang berkepanjangan, ditambah tanpa persiapan apa pun, perubahan mendadak ini membuatmu tidak memiliki kesempatan untuk melawan."
  },
  AvgDialog_60356_Content_26 = {
    Text = "Misi saya telah selesai."
  },
  AvgDialog_60356_Content_27 = {
    Text = "Konduktor menyimpan tongkat konduktornya. Bersih, elegan, tanpa sedikit pun ragu-ragu."
  },
  AvgDialog_60356_Content_28 = {
    Text = "Penilaianmu sangat tepat, Tuan Hameln."
  },
  AvgDialog_60356_Content_29 = {
    Text = "Penjaga adalah ancaman terbesar bagi kita. Ini adalah wilayah %hisorher%, jika kita membiarkan {Male=dia,Female=dia} lepas kendali, rencana kita akan menghadapi ancaman besar."
  },
  AvgDialog_60356_Content_3 = {
    Text = "Banyak tentara dan pendeta Komite terbaring di Kolam Hitam di sisimu, dan jika dilihat dari atas, tampak seperti lukisan yang dibuat dari tumpukan mayat."
  },
  AvgDialog_60356_Content_30 = {
    Text = "Mendapatkan kepercayaan %hisorher% tidak hanya akan membuat {Male=dia,Female=dia} membantu kita menemukan Tawil, tetapi juga memungkinkan kita untuk mengamati setiap gerakan %hisorher% saat berada di dekat {Male=dia,Female=dia}."
  },
  AvgDialog_60356_Content_31 = {
    Text = "Jika bukan karena strategi Anda, rencana kami pasti tidak akan berjalan semulus ini. Bekerja sama dengan seseorang yang luar biasa seperti Anda adalah sebuah kehormatan bagi saya."
  },
  AvgDialog_60356_Content_32 = {
    Text = "Tidak perlu sungkan."
  },
  AvgDialog_60356_Content_33 = {
    Text = "Hameln sedikit mengangguk sebagai respons terhadap Juliette."
  },
  AvgDialog_60356_Content_34 = {
    Text = "Dengan sisa tenagamu, kamu mengangkat kepala dan memandang ke arah orang di sebelahmu."
  },
  AvgDialog_60356_Content_35 = {Text = "Hameln...?"},
  AvgDialog_60356_Content_36 = {
    Text = "Hameln, kamu..."
  },
  AvgDialog_60356_Content_37 = {
    Text = "Tautan rohmu telah sepenuhnya hancur, saat ini kamu tidak berdaya."
  },
  AvgDialog_60356_Content_38 = {
    Text = "Sudah sampai pada titik ini, bicara lebih banyak tidak akan ada gunanya. Terimalah, lalu tunggu."
  },
  AvgDialog_60356_Content_39 = {
    Text = "Menunggu kedatangan melodi luar biasa itu."
  },
  AvgDialog_60356_Content_4 = {
    Text = "Sungguh sulit dipercaya, Penjaga… bakatmu sungguh mengagumkan dan membangkitkan rasa iri."
  },
  AvgDialog_60356_Content_40 = {
    Text = "Suara Hameln tenang seperti permukaan danau es, bersih dan kosong, kamu tidak bisa melihat apa pun di dalamnya."
  },
  AvgDialog_60356_Content_41 = {
    Text = "Langkah kaki terdengar, sekelompok imam muncul di hadapanmu sambil membawa seseorang."
  },
  AvgDialog_60356_Content_42 = {
    Text = "Ramona…!!"
  },
  AvgDialog_60356_Content_43 = {
    Text = "Kamu ingin melawan, tapi tubuhmu tidak bisa bergerak sedikit pun, hanya bisa menyaksikan mereka meletakkan tubuh Ramona ke dalam tubuh Tawil."
  },
  AvgDialog_60356_Content_44 = {
    Text = "Seiring tubuh Ramona masuk ke dalam Kolam Hitam, sebuah lingkaran sihir raksasa yang terukir dengan lambang lentera muncul di bawahnya."
  },
  AvgDialog_60356_Content_45 = {
    Text = "Juliette tersenyum dan meletakkan lampu dengan bentuk aneh di atas kepala Ramona."
  },
  AvgDialog_60356_Content_46 = {
    Text = "Dia perlahan mengangkat tangannya, senyuman di wajahnya secara bertahap berubah menjadi khidmat."
  },
  AvgDialog_60356_Content_47 = {
    Text = "Hambatan terakhir telah diatasi, semua persiapan sudah selesai."
  },
  AvgDialog_60356_Content_48 = {
    Text = "Pencipta Relik yang luhur, tolong jawab panggilan kami…"
  },
  AvgDialog_60356_Content_49 = {
    Text = "Bersihkan dunia ini dengan pemurnian yang agung!"
  },
  AvgDialog_60356_Content_5 = {
    Text = "Namun, sangat disayangkan, kamu bukan lawanku."
  },
  AvgDialog_60356_Content_50 = {Text = "BYUR—"},
  AvgDialog_60356_Content_51 = {
    Text = "Kolam hitam yang tak berbatas mulai berguncang dengan hebat."
  },
  AvgDialog_60356_Content_52 = {
    Text = "Di bawah lingkaran sihir yang besar, di dalam matamu yang penuh keputusasaan, sebuah patung dewa putih yang sangat megah perlahan menampakkan puncak kepalanya."
  },
  AvgDialog_60356_Content_6 = {
    Text = "Kekuatan dari tiga besar protoplasma sudah stabil, dan kekuatanku telah pulih."
  },
  AvgDialog_60356_Content_7 = {
    Text = "Aku sudah bertarung denganmu, kemampuanmu sangat kumengerti, Juliette."
  },
  AvgDialog_60356_Content_8 = {
    Text = "Aku tahu kau sangat kuat, dan aku juga tahu bahwa kau masih memiliki kekuatan tersembunyi yang belum digunakan… Tapi jika kau berniat melawan Mythag, kau telah memilih lawan yang salah."
  },
  AvgDialog_60356_Content_9 = {
    Text = "Kamu menggenggam Perak dengan erat, para Pembangun di sekitarmu menerima instruksi dan mengelilingi Juliette."
  },
  AvgDialog_60357_Content_1 = {
    Text = "Gerakan Ketiga"
  },
  AvgDialog_60357_Content_10 = {
    Text = "Fungsi tubuh dan kekuatan roh telah pulih!"
  },
  AvgDialog_60357_Content_11 = {
    Text = "Pengaruh Kolam Hitam juga sudah hampir menghilang, hanya saja saya masih belum tahu cara memanggil kekuasaan dari ketiga badan utama itu…"
  },
  AvgDialog_60357_Content_12 = {
    Text = "Cara menyerap kekuasaan ada di balik pintu."
  },
  AvgDialog_60357_Content_13 = {
    Text = "Baru saja di ruang Tawil, Dia juga memberitahuku tentang hal ini... Bagaimana kamu tahu?"
  },
  AvgDialog_60357_Content_14 = {Text = "Tebakan."},
  AvgDialog_60357_Content_15 = {
    Text = "Memutus suara sekarang berisiko, sebelum kekuasaan dari ketiga badan besar sepenuhnya berfungsi, saya akan terus membantu Anda menjaga stabilitas Roh."
  },
  AvgDialog_60357_Content_16 = {
    Text = "Terima kasih banyak… Hameln, jika bukan karena bantuanmu, aku tidak mungkin bisa sampai sejauh ini."
  },
  AvgDialog_60357_Content_17 = {
    Text = "Saya memiliki tujuan saya sendiri."
  },
  AvgDialog_60357_Content_18 = {
    Text = "Kamu sudah membantu aku. Hal yang ingin kamu temukan, aku pasti akan berusaha semaksimal mungkin untuk membantu menemukannya."
  },
  AvgDialog_60357_Content_19 = {
    Text = "Tentu saja kamu akan melakukannya. Aku tidak pernah meragukan hal itu."
  },
  AvgDialog_60357_Content_2 = {
    Text = "Sensasi sentuhan jari menghilang dari dahimu. Kamu membuka mata, Tawil dan ruang-Nya menghilang, dan Kolam Hitam kembali muncul di bawah kakimu."
  },
  AvgDialog_60357_Content_20 = {
    Text = "Sekarang kita pergi mencari Juliette dulu, lalu menyelamatkan Ramona…"
  },
  AvgDialog_60357_Content_21 = {
    Text = "Haha, saya datang untuk mengunjungi Mythag, mana mungkin membebani tuan rumah untuk mencari saya."
  },
  AvgDialog_60357_Content_22 = {Text = "!!!"},
  AvgDialog_60357_Content_23 = {
    Text = "Rasa krisis yang kuat membuatmu langsung tegang. Kamu dan Hameln berbalik badan, saling mempercayakan punggung satu sama lain, lalu masing-masing mengamati setengah area."
  },
  AvgDialog_60357_Content_24 = {
    Text = "Sebuah topi kasa ungu yang familiar berkilauan dalam cahaya redup Kolam Hitam."
  },
  AvgDialog_60357_Content_25 = {
    Text = "Lagi-lagi kita bertemu, Penjaga. Dan kamu juga, Tuan Pengkhianat."
  },
  AvgDialog_60357_Content_27 = {
    Text = "Wanita di bawah tudung kasa memberikan senyuman hangat kepadamu, sama seperti saat pertama kali bertemu di padang pasir."
  },
  AvgDialog_60357_Content_28 = {
    Text = "Bersamaan dengan suaranya terdengar, banyak Agen dan pendeta berbaju ungu muncul di sekitar kalian, mengelilingi kalian sepenuhnya."
  },
  AvgDialog_60357_Content_29 = {
    Text = "Mereka tidak tahu sudah berapa lama mereka berada di dalam Kolam Hitam yang mendidih. Berada di pusat Pelarutan membuat mereka menanggung kerusakan yang sangat besar. Tidak jarang seseorang jatuh, berubah menjadi cairan hitam akibat Pelarutan, dan menyatu ke dalam Kolam Hitam."
  },
  AvgDialog_60357_Content_3 = {
    Text = "Aku... sudah kembali?"
  },
  AvgDialog_60357_Content_30 = {
    Text = "Baik itu orang di sekitar mereka maupun diri mereka sendiri yang jatuh, wajah-wajah mereka tetap tanpa ekspresi."
  },
  AvgDialog_60357_Content_31 = {
    Text = "Mereka adalah anjing milik Juliette. Yang mereka patuhi hanyalah kehendak lentera."
  },
  AvgDialog_60357_Content_32 = {
    Text = "Kamu... selalu menungguku?"
  },
  AvgDialog_60357_Content_33 = {
    Text = "Saya sudah menunggumu begitu lama, untungnya penantianku tidak sia-sia. Terima kasih banyak, Penjaga {Male=tuan,Female=nyonya}."
  },
  AvgDialog_60357_Content_34 = {
    Text = "Mencari Tawil bagi orang biasa sulit seperti mendaki langit. Jika bukan karena Tawil membawamu ke ruang-Nya, mungkin aku harus menghabiskan beberapa minggu untuk menemukan-Nya."
  },
  AvgDialog_60357_Content_35 = {Text = "!!!"},
  AvgDialog_60357_Content_36 = {
    Text = "Ini... apakah kamu sengaja melakukannya?"
  },
  AvgDialog_60357_Content_37 = {
    Text = "Tidak mungkin... di pemakaman, Anjing Berwajah Manusia sudah kita bunuh. Kau tidak mungkin mengetahui keberadaanku dan rencanaku..."
  },
  AvgDialog_60357_Content_38 = {
    Text = "Manusia tidak dapat memahami seluruh gambaran suatu hal. Inilah keterbatasan sebagai manusia."
  },
  AvgDialog_60357_Content_39 = {
    Text = "Penjaga {Male=tuan,Female=nyonya}, kamu telah memberikan kontribusi luar biasa untuk kedatangan Dewa. Di dunia baru yang diciptakan oleh Dewa, kamu pasti akan mendapatkan perhatian yang membanggakan."
  },
  AvgDialog_60357_Content_4 = {
    Text = "Kamu tampaknya baru saja kehilangan kesadaran untuk sesaat."
  },
  AvgDialog_60357_Content_40 = {
    Text = "Dia melambaikan tangannya. Para pendeta dan prajurit yang mengelilingi kalian, dengan Ekspresi kosong, menyerangmu…"
  },
  AvgDialog_60357_Content_5 = {
    Text = "Aku... dibawa oleh Tawil ke sebuah ruang yang aneh..."
  },
  AvgDialog_60357_Content_6 = {
    Text = "Tampaknya, kamu sudah berhasil mengumpulkan semua kekuasaan dari ketiga badan besar."
  },
  AvgDialog_60357_Content_7 = {
    Text = "Kamu menutup mata, merasakan aliran Kekuatan di dalam tubuhmu."
  },
  AvgDialog_60357_Content_8 = {
    Text = "Ketiga kekuatan yang berkembang pesat itu saling menyeimbangkan di dalam dirimu, bergabung menjadi lautan harmoni yang naik dan turun dengan tenang mengikuti napasmu."
  },
  AvgDialog_60357_Content_9 = {
    Text = "Kamu bangkit dan memeriksa kondisi kesehatan tubuhmu."
  },
  AvgDialog_60358_Content_1 = {
    Text = "Banyak bayangan menyebar keluar dari tubuh N."
  },
  AvgDialog_60358_Content_10 = {
    Text = "Jadi, tolong bawakan aku pertunjukan yang luar biasa ini, Penjaga {Male=tuan,Female=nyonya}."
  },
  AvgDialog_60358_Content_2 = {
    Text = "Bayangan jatuh ke panggung, segera berubah menjadi makhluk pelarutan yang berbahaya dan mengelilingi dirimu."
  },
  AvgDialog_60358_Content_3 = {
    Text = "Bagaimana, teman saya?"
  },
  AvgDialog_60358_Content_4 = {
    Text = "Bagaimana rasanya berhasil mendapatkan kembali otoritas esensi keinginan, tetapi sekarang harus menyaksikan hal itu direbut?"
  },
  AvgDialog_60358_Content_5 = {
    Text = "Apa yang ingin kamu lakukan, N!"
  },
  AvgDialog_60358_Content_6 = {
    Text = "Kekuasaan ini tidak berguna bagimu!"
  },
  AvgDialog_60358_Content_7 = {
    Text = "Memang tidak berguna... namun, melihatmu kehilangan kekuasaan sangat bermanfaat bagiku."
  },
  AvgDialog_60358_Content_8 = {
    Text = "Apa maksudmu..."
  },
  AvgDialog_60358_Content_9 = {
    Text = "Sebagai aktor, sebagai penonton, konflik drama yang menarik harus menjadi kejaran seumur hidup kita…"
  },
  AvgDialog_60596_Content_1 = {
    Text = "Lentera telah muncul di dunia. Kehendak yang luhur, izinkan aku menyalakan cahaya untukmu ——"
  },
  AvgDialog_60596_Content_2 = {
    Text = "Patung dewa sedang melahap Tawil dan Ramona."
  },
  AvgDialog_60596_Content_3 = {
    Text = "Musikku telah dimainkan untukmu. Hancurkan fusi mereka, Penjaga!"
  },
  AvgDialog_60842_Content_1 = {Text = "Teori Lupa"},
  AvgDialog_60842_Content_10 = {
    Text = "Ketemu kamu... Tawil!"
  },
  AvgDialog_60842_Content_11 = {
    Text = "Deru tajam bergema di seluruh Kolam Hitam. Kekuasaan yang mewakili pengetahuan dalam tubuhnya bergetar seiring dengan deru itu."
  },
  AvgDialog_60842_Content_12 = {
    Text = "Tak terhitung jumlah bayangan putih, tertangkap dari dimensi dan ruang waktu yang berbeda, mengalir ke dalam patung hitam-putih itu."
  },
  AvgDialog_60842_Content_13 = {
    Text = "Segera, semua deru dan getaran itu menghilang."
  },
  AvgDialog_60842_Content_14 = {
    Text = "Bahkan tanpa lampu lentera, akan ada orang lain. Tidak ada yang bisa menghindari-Nya, Tawil."
  },
  AvgDialog_60842_Content_15 = {
    Text = "Ayo, bersama-sama kita menyambut kelahiran-Nya!"
  },
  AvgDialog_60842_Content_16 = {
    Text = "Seiring dengan berhentinya gerakan Juliette, patung kembar lentera raksasa itu mulai berkumpul ke arah tengah, seperti mencari tempat untuk jiwa mereka, dengan penuh keinginan ingin menyatu bersama patung hitam putih di tengah."
  },
  AvgDialog_60842_Content_17 = {
    Text = "Tawil! Ramona!! Ah——"
  },
  AvgDialog_60842_Content_18 = {
    Text = "Seberkas cahaya terang tiba-tiba mekar. Di belakang Relik kembar raksasa, muncul sebuah celah."
  },
  AvgDialog_60842_Content_19 = {
    Text = "Kamu perlahan-lahan menyingkirkan kedua tanganmu yang menutupi mata."
  },
  AvgDialog_60842_Content_2 = {
    Text = "Kamu berada di tengah badai."
  },
  AvgDialog_60842_Content_20 = {
    Text = "Itu adalah... pintu?"
  },
  AvgDialog_60842_Content_21 = {
    Text = "Di belakang Tawil, pintu ilusi itu pada saat ini menjadi nyata."
  },
  AvgDialog_60842_Content_22 = {
    Text = "Cahaya memancar dari celah pintu yang semakin melebar, dingin seperti alam semesta, murni seperti kebenaran."
  },
  AvgDialog_60842_Content_23 = {
    Text = "Juliette terpaku memandang cahaya itu, dua aliran air mata meluncur di bawah cahaya terang tanpa ia sadari. Dia tak mampu mengalihkan pandangannya lagi."
  },
  AvgDialog_60842_Content_24 = {
    Text = "Pintu... Pintu yang menopang segala sesuatu... Tempat tinggal para Dewa..."
  },
  AvgDialog_60842_Content_25 = {
    Text = "Akhirnya, akhirnya hari ini tiba!"
  },
  AvgDialog_60842_Content_26 = {
    Text = "Tidak, pintu tidak boleh terbuka…"
  },
  AvgDialog_60842_Content_27 = {
    Text = "Apa yang ingin kamu lakukan? Kamu berusaha keras menggunakan Kunci Perak, tetapi Kekuatan Roh-mu saat ini tertekan sepenuhnya, dan Kunci Perak tidak menunjukkan reaksi apa pun."
  },
  AvgDialog_60842_Content_29 = {
    Text = "Kamu menatap dengan putus asa saat pintu itu berangsur-angsur berubah dari buram menjadi jelas, lalu terbuka sedikit celah."
  },
  AvgDialog_60842_Content_3 = {
    Text = "Getaran kuat membuat air di Kolam Hitam bergetar hebat, memunculkan gelombang besar yang menghantam tubuhmu."
  },
  AvgDialog_60842_Content_30 = {
    Text = "Kekuatan yang luar biasa itu, seperti banjir yang akan menenggelamkan dunia, mengalir dari dalam pintu menuju patung kembar pemegang lampu."
  },
  AvgDialog_60842_Content_31 = {
    Text = "Juliette membelalakkan mata menatap pintu dan patung dewa, senyuman di wajahnya semakin menyeramkan."
  },
  AvgDialog_60842_Content_32 = {
    Text = "Kekuatan, adalah kekuatan di balik pintu... Patung Kembar, akan segera menyelesaikan fusi."
  },
  AvgDialog_60842_Content_33 = {
    Text = "Mythag… Penjaga… dan dunia penuh dosa ini, terimalah pemurnian terakhir!"
  },
  AvgDialog_60842_Content_34 = {Text = "Ding——"},
  AvgDialog_60842_Content_35 = {
    Text = "Bermainlah, mulai."
  },
  AvgDialog_60842_Content_36 = {Text = "!!!"},
  AvgDialog_60842_Content_37 = {
    Text = "Bagaikan puluhan ribu musisi memainkan alat musik mereka secara bersamaan, suara dawai, tiup, dan perkusi bergabung menjadi satu, membentuk aliran sungai yang bergelora dan mengalir deras."
  },
  AvgDialog_60842_Content_38 = {
    Text = "Sungai mengalir deras, tiba-tiba menerjang ke arah tautan yang lemah di antara gerbang dan patung kembar."
  },
  AvgDialog_60842_Content_39 = {Text = "Hek——"},
  AvgDialog_60842_Content_4 = {
    Text = "Kolam Hitam bergoyang. Kubah bergoyang. Sepertinya seluruh Mythag, bahkan seluruh benua, bergetar dalam nyanyian Juliette."
  },
  AvgDialog_60842_Content_40 = {
    Text = "Sebuah semburan darah keluar dari mulut Hameln, mengotori bajunya dan tongkat komandonya dengan warna merah."
  },
  AvgDialog_60842_Content_41 = {
    Text = "Suara musik bertabrakan dengan kekuatan pintu, dampak kuatnya membuat tubuh Hameln sulit untuk menahan."
  },
  AvgDialog_60842_Content_42 = {
    Text = "Dirigen yang biasanya sangat rapi sama sekali tidak mempedulikan keadaannya yang kacau saat ini. Dia dengan penuh konsentrasi menatap pintu, gerakan mengayunkan tongkat konduktornya tidak menunjukkan sedikit pun keraguan."
  },
  AvgDialog_60842_Content_43 = {
    Text = "Aliran musik yang deras terus-menerus menghantam dinding yang kokoh."
  },
  AvgDialog_60842_Content_44 = {
    Text = "BLARR——"
  },
  AvgDialog_60842_Content_45 = {
    Text = "Patung kembar bergetar hebat. Di bawah terjangan arus musik, pada saat yang paling kritis dan rapuh dalam pembentukan patung dewa kembar, muncul sedikit celah pada tautan antara pintu dan patung."
  },
  AvgDialog_60842_Content_46 = {
    Text = "Aura berbahaya yang berasal dari patung dewa menjadi lebih tipis. Patung batu yang bergerak menuju pusat, menghentikan gerakannya."
  },
  AvgDialog_60842_Content_47 = {
    Text = "Wajah yang sudah dikenal itu melangkah keluar dari bayangan, kembali berdiri di sisimu."
  },
  AvgDialog_60842_Content_48 = {
    Text = "Saatnya telah tiba. Pertunjukan terakhir, segera dimulai."
  },
  AvgDialog_60842_Content_49 = {
    Text = "Dia mengayunkan tongkatnya dengan lembut. Sebuah melodi lembut mengalir ke dalam Dunia rohmu."
  },
  AvgDialog_60842_Content_5 = {
    Text = "Di tengah guncangan yang mengguncang langit dan bumi, kamu mengangkat kepalamu dan melihat Relik yang semakin megah di hadapanmu."
  },
  AvgDialog_60842_Content_50 = {
    Text = "Belenggu dan penderitaan yang berat itu tiba-tiba menghilang, kamu kembali berendam di dalam sumber air panas, dan pikiranmu dipenuhi kembali dengan energi roh yang lebih besar daripada sebelumnya."
  },
  AvgDialog_60842_Content_51 = {
    Text = "Kamu... kamu tidak merusak Tautan rohku?"
  },
  AvgDialog_60842_Content_52 = {
    Text = "Sebelumnya, kemampuan tautanmu untuk sementara diputus. Sebuah cara untuk menyesatkan Juliette."
  },
  AvgDialog_60842_Content_53 = {
    Text = "Batasanmu telah dicabut. Sekarang, pintu sudah terbuka, dan semua persiapan telah rampung."
  },
  AvgDialog_60842_Content_54 = {
    Text = "Dia berdiri di hadapanmu, di matanya yang tenang menyala api yang membara."
  },
  AvgDialog_60842_Content_55 = {
    Text = "Dia meletakkan tongkat komando di belakang punggungnya, lalu membungkuk memberi hormat kepadamu."
  },
  AvgDialog_60842_Content_56 = {
    Text = "Mata buta, pelaksana Kehendak Tertinggi. Hameln, sang konduktor, siap melayani Anda."
  },
  AvgDialog_60842_Content_57 = {
    Text = "Aku akan membantu kamu untuk mengambil kembali kekuasaan yang menjadi hakmu."
  },
  AvgDialog_60842_Content_58 = {
    Text = "Kamu... kamu tahu..."
  },
  AvgDialog_60842_Content_59 = {
    Text = "Kedatangan Kehendak Tertinggi tidak terhindarkan, hanya kamu yang dapat melawannya."
  },
  AvgDialog_60842_Content_6 = {
    Text = "Kembar... Patung dewa..."
  },
  AvgDialog_60842_Content_60 = {
    Text = "Biarkan kembaran muncul, pintu terbuka, maka kamu akan mendapatkan kembali kemampuan untuk melawan-Nya."
  },
  AvgDialog_60842_Content_61 = {
    Text = "Dalam keadaan mendesak, mohon maafkan kelakuanku yang kurang sopan sebelumnya."
  },
  AvgDialog_60842_Content_62 = {
    Text = "Hameln! Apa... apa yang sedang kamu lakukan?!!!"
  },
  AvgDialog_60842_Content_63 = {
    Text = "Lakukan apa yang harus aku lakukan."
  },
  AvgDialog_60842_Content_64 = {
    Text = "Patung itu hancur pada saat yang paling rapuh. Dewa-mu akan sulit mendengar panggilanmu lagi."
  },
  AvgDialog_60842_Content_65 = {
    Text = "{Male=Dia,Female=Dia} hanyalah sepotong fragmen! Hanya dengan caraku, kehendak tertinggi yang sebenarnya dapat bangkit……"
  },
  AvgDialog_60842_Content_66 = {
    Text = "Bukankah kau ingin mendengar suara musik tertinggi dari Kehendak Tertinggi? Hameln, kau telah melakukan penghianatan terhadap apa yang kau percayai!"
  },
  AvgDialog_60842_Content_67 = {
    Text = "Dewa belum tentu lebih agung daripada Fragmennya. Lagipula, ini bukanlah hal yang saya pedulikan, Nyonya Juliette."
  },
  AvgDialog_60842_Content_68 = {
    Text = "Saya juga pernah berpikir bahwa Requiem dari Kehendak Tertinggi adalah suara paling agung di alam semesta ini. Namun, kemudian saya menyadari bahwa seni yang benar-benar luhur akan melampaui dirinya sendiri."
  },
  AvgDialog_60842_Content_69 = {
    Text = "Dia mengangkat kepalanya, sepasang mata yang menyala dengan api ganas itu diam-diam menatap Juliette."
  },
  AvgDialog_60842_Content_7 = {
    Text = "Dua patung batu berbentuk manusia berwarna putih perlahan muncul dari bawah Kolam Hitam, membuat seluruh Kolam Hitam bergetar."
  },
  AvgDialog_60842_Content_70 = {
    Text = "Itu akan bergema dalam perjuangan — pertarungan antara manusia dan Dewa. Pertarungan antara Fragmen dan asal."
  },
  AvgDialog_60842_Content_71 = {
    Text = "Melawan Kehendak Tertinggi, berpadu dengan Kehendak Tertinggi... ini akan menjadi suara yang lebih luhur daripada Requiem Kehendak Tertinggi!"
  },
  AvgDialog_60842_Content_72 = {
    Text = "Sejak kapan kamu..."
  },
  AvgDialog_60842_Content_73 = {
    Text = "Musim semi Akut, kami menyaksikan ledakan itu."
  },
  AvgDialog_60842_Content_74 = {
    Text = "Pada hari itu, aku mendengarnya... suara yang kucari, lebih abadi daripada Requiem."
  },
  AvgDialog_60842_Content_75 = {
    Text = "Pada saat itu, aku hanya mendengar intro-nya. Hari ini, ia akan bergema sepenuhnya di dunia ini."
  },
  AvgDialog_60842_Content_76 = {
    Text = "Suara Hameln yang biasanya tenang tidak bisa menahan gemetar."
  },
  AvgDialog_60842_Content_77 = {
    Text = "Jadi, sejak hari itu, kau sudah merencanakan penghianatan…"
  },
  AvgDialog_60842_Content_78 = {
    Text = "Dewa telah melupakan musik-Nya. Dia hanyalah tubuh Kekacauan tanpa kesadaran, sebuah bencana besar."
  },
  AvgDialog_60842_Content_79 = {
    Text = "Semua keindahan-Nya, semua kebenaran tertinggi-Nya, terdapat pada Fragmen-Nya."
  },
  AvgDialog_60842_Content_8 = {
    Text = "Di celah tengah patung, tubuh Ramona dililit dan dibungkus oleh jalinan tubuh Tawil."
  },
  AvgDialog_60842_Content_80 = {
    Text = "Saya setia pada musik, pada keindahan dan kebenaran. Saya tak pernah melakukan penghianatan, Juliette."
  },
  AvgDialog_60842_Content_81 = {
    Text = "Tindakanmu tidak dapat dimaafkan"
  },
  AvgDialog_60842_Content_82 = {
    Text = "Kenapa… jika kamu membantuku sejak awal, Ramona tidak akan…"
  },
  AvgDialog_60842_Content_83 = {
    Text = "Hameln, aku tidak bisa memaafkan apa yang telah kau lakukan."
  },
  AvgDialog_60842_Content_84 = {
    Text = "Kenapa harus melakukan ini?"
  },
  AvgDialog_60842_Content_85 = {
    Text = "Kenapa… jika kamu membantuku sejak awal, Ramona tidak akan…"
  },
  AvgDialog_60842_Content_86 = {
    Text = "Dia dengan tenang menatap Juliette, patung raksasa. serta pintu di belakang patung raksasa itu."
  },
  AvgDialog_60842_Content_87 = {
    Text = "Dia berdiri di sisimu."
  },
  AvgDialog_60842_Content_88 = {
    Text = "Penjaga {Male=tuan,Female=nyonya}, menghentikan Juliette hanya akan memperlambat kedatangan Kehendak Tertinggi. Kematian perlahan, tidak ada artinya."
  },
  AvgDialog_60842_Content_89 = {
    Text = "Membiarkan Juliette memanggil, sehingga kamu dapat dengan lancar mendapatkan kembali kekuasaan, adalah satu-satunya jalan."
  },
  AvgDialog_60842_Content_9 = {
    Text = "Dua sosok tanpa pemilik terus berubah dan menyatu, menjadi sebuah patung raksasa berwarna hitam dan putih, melayang di antara patung-patung batu setengah badan yang besar."
  },
  AvgDialog_60842_Content_90 = {
    Text = "Apa yang kita cari berbeda, tetapi baik suara tertinggi maupun kelangsungan dunia, kesempatan ini hanya datang sekali."
  },
  AvgDialog_60842_Content_91 = {
    Text = "Dalam pertunjukan yang tak terelakkan ini, kamu, aku, Nyonya Ramona, semua orang di sini hanyalah pemain musik."
  },
  AvgDialog_60842_Content_92 = {
    Text = "Aku tidak mengharapkan pengertian atau pengampunan darimu, aku bertanggung jawab atas setiap nada yang kumainkan."
  },
  AvgDialog_60842_Content_93 = {
    Text = "Sebelum itu, aku akan membantu kamu menghentikan Juliette dan menyelamatkan Ramona."
  },
  AvgDialog_60842_Content_94 = {
    Text = [[
Kamu tahu, Hameln benar. Demi kelangsungan dunia, Ramona tidak pernah ragu untuk mengorbankan dirinya sendiri. 
Namun, kamu merasa berbeda.]]
  },
  AvgDialog_60842_Content_95 = {
    Text = "Merasakan energi roh yang semakin deras di dalam tubuhmu, kamu mengangkat kepala dan menatap patung dewa yang megah itu."
  },
  AvgDialog_60842_Content_96 = {
    Text = "Tidak ada yang bisa mendekati-Nya... pengikutku, \"anjing\"-ku, hentikan mereka!"
  },
  AvgDialog_60886_Content_1 = {
    Text = "Itu juga merupakan sebuah pilihan, sebuah alur cerita."
  },
  AvgDialog_60886_Content_10 = {
    Text = "Seorang aktor yang penuh dedikasi. Selama sembilan belas tahun memerankan karakter yang sama, demi perubahan indah dalam cerita, tidak pernah sedikit pun bersantai."
  },
  AvgDialog_60886_Content_11 = {
    Text = "Sekarang……"
  },
  AvgDialog_60886_Content_12 = {
    Text = "Para penonton tercinta, tolong berikan saya tepuk tangan yang paling meriah."
  },
  AvgDialog_60886_Content_13 = {
    Text = "Kabut hitam menyelimuti, seperti sorakan."
  },
  AvgDialog_60886_Content_14 = {
    Text = "Yang muncul di hadapanmu adalah wajah yang pernah kau lihat, wajah yang telah membawa banyak mimpi buruk kepadamu."
  },
  AvgDialog_60886_Content_15 = {
    Text = "Di wajah tanpa fitur, mulut yang tersenyum itu terbuka lebar-lebar, menikmati rasa keterkejutan dan ketakutanmu dengan penuh nafsu."
  },
  AvgDialog_60886_Content_16 = {
    Text = "Kamu adalah… N!"
  },
  AvgDialog_60886_Content_17 = {
    Text = "Sebuah sebutan, bagi ribuan inkarnasi saya, ini adalah sebuah penghinaan… tapi terserah kamu mau memanggil saya apa."
  },
  AvgDialog_60886_Content_18 = {
    Text = "Apa yang telah kau lakukan terhadap Profesor Dexter!"
  },
  AvgDialog_60886_Content_19 = {
    Text = "Profesor Dexter? Siapa itu Profesor Dexter?"
  },
  AvgDialog_60886_Content_2 = {
    Text = "Tapi jika dia benar-benar diselamatkan, bukankah cerita ini akan kehilangan satu adegan besar yang menarik untuk diikuti?"
  },
  AvgDialog_60886_Content_20 = {
    Text = "Penjaga, apakah kamu dan Ramona... apakah kalian benar-benar mengenal Dexter?"
  },
  AvgDialog_60886_Content_21 = {
    Text = "Apa maksudmu... bagaimana mungkin kita... apa?!"
  },
  AvgDialog_60886_Content_22 = {
    Text = "Kamu teringat perkataan N. Selama sembilan belas tahun, dia terus memerankan peran yang sama…"
  },
  AvgDialog_60886_Content_23 = {
    Text = "Murid berkontraksi dengan hebat. Kamu tiba-tiba mengangkat kepala dan menatap wajah N yang tanpa fitur."
  },
  AvgDialog_60886_Content_24 = {
    Text = "Hebat, Penjaga. Inilah Ekspresi yang tepat!"
  },
  AvgDialog_60886_Content_25 = {
    Text = "Jangan bergerak, tetap seperti itu. Ya, benar… biarkan aku mengingatmu seperti ini…"
  },
  AvgDialog_60886_Content_26 = {
    Text = "Sayang sekali, Ramona belum tersadar saat mengetahui hal ini, aku tidak bisa melihat ekspresinya."
  },
  AvgDialog_60886_Content_27 = {
    Text = "Saya rasa, ekspresi wajahnya mungkin sama menariknya dengan ekspresimu."
  },
  AvgDialog_60886_Content_28 = {
    Text = "Tubuh N bergetar sedikit, sepertinya dia sedang bertahan dari gelombang tawa yang sangat kuat."
  },
  AvgDialog_60886_Content_29 = {
    Text = "Dia membungkuk, mendekatkan wajahnya ke arahmu, dan mengamati dengan saksama."
  },
  AvgDialog_60886_Content_3 = {
    Text = "Kepedulian, kerinduan, kesedihan… semua emosi menghilang dari wajah Dexter."
  },
  AvgDialog_60886_Content_30 = {
    Text = "Kamu... mengapa mengendalikan Profesor Dexter?"
  },
  AvgDialog_60886_Content_31 = {
    Text = "Kontrol? Ah, tidak. Kontrol adalah bentuk hiburan yang rendah."
  },
  AvgDialog_60886_Content_32 = {
    Text = "Seorang aktor yang luar biasa harus memerankan dan menjadi."
  },
  AvgDialog_60886_Content_33 = {
    Text = "Dia mendekatkan diri ke telingamu, berbisik pelan seolah ingin berbagi rahasia besar denganmu——"
  },
  AvgDialog_60886_Content_34 = {
    Text = "Dexter sudah meninggal, dia meninggal pada hari dia menyelamatkan Ramona."
  },
  AvgDialog_60886_Content_35 = {
    Text = "Selama bertahun-tahun, kamu dan Ramona pasti sangat menikmati waktu bersamaku, kan?"
  },
  AvgDialog_60886_Content_36 = {
    Text = "Wajahnya menghadapmu. Di wajah yang kosong itu, kamu seolah-olah dengan jelas melihat fitur wajahnya yang sombong dan mendominasi."
  },
  AvgDialog_60886_Content_37 = {
    Text = "Dia membungkuk, mendekatkan wajahnya di depanmu, memperhatikan dengan cermat, seakan ingin mengingat setiap ekspresi, setiap gemetar yang tak terkendali."
  },
  AvgDialog_60886_Content_38 = {
    Text = "Seorang playboy yang flamboyan, sekaligus ayah yang penuh kasih. Awalnya, saya tidak terlalu tertarik pada karakter seperti ini."
  },
  AvgDialog_60886_Content_39 = {
    Text = "Yang aku minati hanyalah dia... \"anak\" ku. Relik kembar Tawil, Ramona."
  },
  AvgDialog_60886_Content_4 = {
    Text = "Kamu melihat, dia memberimu senyuman yang sempurna, tanpa sedikit pun kehangatan."
  },
  AvgDialog_60886_Content_40 = {
    Text = "N tertawa sambil menatap ke arah tengah Kolam Hitam, ke arah Tawil."
  },
  AvgDialog_60886_Content_41 = {
    Text = "Kamu... kenapa kamu tega membunuhnya..."
  },
  AvgDialog_60886_Content_42 = {
    Text = "Betapa menyedihkannya kesalahpahamanmu, Penjaga."
  },
  AvgDialog_60886_Content_43 = {
    Text = "Rencana dari kembaran bersaudara dengan lentera, bukanlah sesuatu yang bisa dengan mudah dihadapi oleh seorang playboy lemah tanpa kekuatan. Namun, dia bahkan berhasil mencuri bayi perempuan itu."
  },
  AvgDialog_60886_Content_44 = {
    Text = "Saat melihatku, tatapannya seperti melihat penyelamat... Ha."
  },
  AvgDialog_60886_Content_45 = {
    Text = "N mengingat kembali cerita itu dan tersenyum dengan gembira."
  },
  AvgDialog_60886_Content_46 = {
    Text = "Dia membuat kesepakatan denganku. Apakah kamu berani mempercayainya? Seorang manusia biasa yang hampir mati, membuat kesepakatan denganku…"
  },
  AvgDialog_60886_Content_47 = {
    Text = "Dia memberikan segalanya kepadaku. Hartanya, statusnya, putrinya…"
  },
  AvgDialog_60886_Content_48 = {
    Text = "Dia meminta saya untuk berperan sebagai dirinya, sebagai ayah dari anaknya."
  },
  AvgDialog_60886_Content_49 = {
    Text = "Dia meninggal sambil memeluk bayi perempuan itu. Di detik-detik terakhirnya, dia terus bergumam tentang bagaimana seorang ayah akan melindunginya dengan baik dan hal-hal semacam itu…"
  },
  AvgDialog_60886_Content_5 = {
    Text = "Profesor Dexter pasti tidak akan mengatakan hal seperti ini… Siapa sebenarnya kamu?!"
  },
  AvgDialog_60886_Content_50 = {
    Text = "Mata-mata di dalam Mythag… apakah itu kamu?"
  },
  AvgDialog_60886_Content_51 = {
    Text = "Melihat matamu yang dipenuhi keraguan dan kemarahan, N mengangkat bahu dengan sikap tak peduli."
  },
  AvgDialog_60886_Content_52 = {
    Text = "Itu aku, bukan aku, apa pentingnya? Sulit dipercaya bahwa sampai sekarang kamu masih punya suasana hati untuk memikirkan hal-hal seperti ini."
  },
  AvgDialog_60886_Content_53 = {
    Text = "Berperan sebagai Dexter, bisa berada dekat dengan Mythag tetap memberikan kemudahan yang cukup baik."
  },
  AvgDialog_60886_Content_54 = {
    Text = "Tempat ini benar-benar seperti taman bermain paling menarik di dunia."
  },
  AvgDialog_60886_Content_55 = {
    Text = "Lihatlah ekspresi kalian saat menyadari telah ditipu olehku. Lihatlah kehancuran Tawil saat rencananya gagal."
  },
  AvgDialog_60886_Content_56 = {
    Text = "Tentu saja, dan kamu juga."
  },
  AvgDialog_60886_Content_57 = {
    Text = "Dia menatapmu, menjilati bibirnya, seperti anak kecil yang tak berdosa, memandangi sebuah mainan yang akan segera hancur."
  },
  AvgDialog_60886_Content_58 = {
    Text = "Thais memberikan benihnya padamu, dia sungguh percaya bahwa kau bisa membantunya bertahan hidup… Hah, wanita gila ini."
  },
  AvgDialog_60886_Content_59 = {
    Text = "Sayang sekali, dia mempercayai orang yang salah. Hak untuk berkembang biak, aku akan mengambilnya."
  },
  AvgDialog_60886_Content_6 = {
    Text = "Dia berdiri di hadapanmu, sepasang mata yang sudah tidak asing lagi memandangmu dengan senyuman yang terasa asing."
  },
  AvgDialog_60886_Content_60 = {
    Text = "Mari aku lihat, ketika harapan yang berkobar direnggut, ekspresi seperti apa yang akan muncul di wajahmu?"
  },
  AvgDialog_60886_Content_7 = {
    Text = "Sebuah asap hitam mengepul dari tubuhnya, perlahan membungkusnya."
  },
  AvgDialog_60886_Content_8 = {
    Text = "Benar, siapa aku ini……"
  },
  AvgDialog_60886_Content_9 = {
    Text = "Pemegang saham yang royal. Ayah yang sangat mencintai putrinya. Playboy terkenal. Profesor Misashe yang cukup populer."
  },
  AvgDialog_60887_Content_1 = {
    Text = "Hanya ada satu cara ini..."
  },
  AvgDialog_60887_Content_10 = {
    Text = "Setelah suara ini, musik megah bergema dari kedalaman kesadaran kalian."
  },
  AvgDialog_60887_Content_12 = {Text = "!!!"},
  AvgDialog_60887_Content_13 = {
    Text = "Ini... ini..."
  },
  AvgDialog_60887_Content_14 = {
    Text = "Simpan kunci perakmu. Jika kamu mengaktifkannya sekarang, kamu akan mati."
  },
  AvgDialog_60887_Content_15 = {
    Text = "Irama. Melodi. Harmoni lembut dari senar mengisi pikiran kalian."
  },
  AvgDialog_60887_Content_16 = {
    Text = "Itu adalah frekuensi misterius. Anggota Komite jatuh kesakitan di tanah saat mendengar suara musik ini, sementara kamu merasa seperti sedang dibungkus dan dicuci oleh mata air hangat."
  },
  AvgDialog_60887_Content_17 = {
    Text = "Kamu dengan jelas merasakan bahwa tautan antara dirimu dan Pembangun telah pulih kembali. Getaran dari Kolam Hitam tampaknya juga telah sepenuhnya menghilang dalam alunan musik ini."
  },
  AvgDialog_60887_Content_18 = {
    Text = "Clementine menatap dengan terkejut ke arah pemilik suara itu."
  },
  AvgDialog_60887_Content_19 = {
    Text = "Itu kamu! Kenapa…"
  },
  AvgDialog_60887_Content_2 = {
    Text = "Tangkap {Male=dia,Female=dia}."
  },
  AvgDialog_60887_Content_20 = {
    Text = "Pukulan, berhenti."
  },
  AvgDialog_60887_Content_21 = {
    Text = "Pria itu mengayunkan tongkat komando dengan lembut. Sebuah perintah pendek dan tegas terdengar, membawa keheningan sesaat."
  },
  AvgDialog_60887_Content_22 = {
    Text = "Clementine tidak kuat lagi dan jatuh ke tanah."
  },
  AvgDialog_60887_Content_23 = {
    Text = "Kamu... kamu..."
  },
  AvgDialog_60887_Content_24 = {
    Text = "Yang lainnya akan segera tiba, dan suara musikku tidak akan bertahan lama."
  },
  AvgDialog_60887_Content_25 = {
    Text = "Aku akan membawamu ke tempat yang aman."
  },
  AvgDialog_60887_Content_26 = {
    Text = "Dia berbalik, sedikit mengangguk ke arahmu, dengan ekspresi wajah yang tenang seperti sumur kuno."
  },
  AvgDialog_60887_Content_27 = {
    Text = "Konduktor Hameln, siap melayani Anda."
  },
  AvgDialog_60887_Content_3 = {
    Text = "Kamu mengangkat tanganmu."
  },
  AvgDialog_60887_Content_4 = {
    Text = "Aku tidak akan membiarkan kalian..."
  },
  AvgDialog_60887_Content_5 = {
    Text = "Gerakan kedua, dimulai."
  },
  AvgDialog_60887_Content_6 = {Text = "Ukh——"},
  AvgDialog_60887_Content_7 = {Text = "?!!!"},
  AvgDialog_60887_Content_8 = {
    Text = "Sebelum kunci perak di tanganmu memancarkan cahaya menyilaukan yang melukai dirimu dan musuhmu, sebuah suara dingin terdengar dari belakang."
  },
  AvgDialog_60887_Content_9 = {
    Text = "Suara itu adalah jejak yang digariskan oleh konduktor, sebuah hukum yang tak terbantahkan di dunia yang dibangun oleh not-not musik."
  },
  AvgDialog_60888_Content_1 = {
    Text = "Masalah besar... terjadi masalah besar..."
  },
  AvgDialog_60888_Content_10 = {
    Text = "Dalam satu menit lima belas detik, tepuk tangan penonton akan bergemuruh seperti guntur, berlangsung lama sebelum akhirnya perlahan memudar."
  },
  AvgDialog_60888_Content_11 = {
    Text = "Dalam dua puluh lima menit, orkestra dan penonton akan meninggalkan tempat."
  },
  AvgDialog_60888_Content_12 = {
    Text = "Waktu sama persis seperti yang diperkirakan, seperti pertunjukan kedua yang sangat presisi."
  },
  AvgDialog_60888_Content_13 = {
    Text = "Konduktor dengan puas mengangguk, lalu membungkuk memberi hormat kepada kursi penonton yang kosong."
  },
  AvgDialog_60888_Content_15 = {
    Text = "Di sudut yang tidak mencolok di sisi tempat duduk penonton, tepuk tangan kecil terdengar kembali."
  },
  AvgDialog_60888_Content_16 = {
    Text = "Sebuah pertunjukan yang luar biasa, Tuan Hameln."
  },
  AvgDialog_60888_Content_17 = {
    Text = "Mungkin bisa dianggap lengkap, namun masih jauh dari kata luar biasa. Pertunjukan yang benar-benar luar biasa berada di luar teater."
  },
  AvgDialog_60888_Content_18 = {
    Text = "Konduktor menyimpan tongkat konduktornya, mengerutkan alisnya sambil menatap seorang wanita di sisi panggung penonton."
  },
  AvgDialog_60888_Content_19 = {
    Text = "Kita sudah berbicara sebelumnya, kamu seharusnya tidak berada di dalam teater, Nyonya Juliette."
  },
  AvgDialog_60888_Content_2 = {
    Text = "Harus segera memberi tahu semua orang… dan Penjaga!"
  },
  AvgDialog_60888_Content_20 = {
    Text = "Kerja sama kita tidak ada hubungannya dengan pertunjukan saya, dan saya tidak ingin ada gangguan apa pun terhadapnya. Saya pikir kamu sudah paham akan hal ini."
  },
  AvgDialog_60888_Content_21 = {
    Text = "Selain itu, kemunculanmu di sini dengan identitasmu akan menimbulkan masalah yang tidak perlu."
  },
  AvgDialog_60888_Content_22 = {
    Text = "Tentu saja, Tuan Hameln. Hanya saja, jika saya tidak datang untuk mendengarkan penampilanmu secara langsung, saya akan sangat menyesal."
  },
  AvgDialog_60888_Content_23 = {
    Text = "Juliette tersenyum dan mengangguk hormat, lalu dengan lembut merapikan kerutan pada ujung bajunya."
  },
  AvgDialog_60888_Content_24 = {
    Text = "Dia sudah terbiasa dengan cara Hameln berbicara dan tidak mempermasalahkannya."
  },
  AvgDialog_60888_Content_25 = {
    Text = "Selain itu, saya juga memiliki hal penting yang perlu disampaikan langsung kepadamu."
  },
  AvgDialog_60888_Content_26 = {
    Text = "Apakah operasi sudah dimulai?"
  },
  AvgDialog_60888_Content_27 = {
    Text = "Bagus. Clementine berhasil menangani patroli Mythag dengan lancar, kita mendapatkan lebih banyak waktu daripada yang diperkirakan."
  },
  AvgDialog_60888_Content_28 = {
    Text = "Rencanamu sangat sukses."
  },
  AvgDialog_60888_Content_29 = {
    Text = "Hanya sebuah preludium yang tidak terlalu rumit. Masih terlalu dini untuk menyatakan keberhasilan saat ini."
  },
  AvgDialog_60888_Content_30 = {
    Text = "Saya percaya pada kebijaksanaanmu, Tuan Konduktor."
  },
  AvgDialog_60888_Content_31 = {
    Text = "Sudah berapa lama kita menantikan hari ini?"
  },
  AvgDialog_60888_Content_32 = {
    Text = "Sembilan belas tahun."
  },
  AvgDialog_60888_Content_33 = {
    Text = "Benar, sembilan belas tahun. Sebuah waktu yang sangat lama."
  },
  AvgDialog_60888_Content_34 = {
    Text = "Para pematung dan Pelaut telah menarik perhatian yang cukup bagi kami. Keberadaan kami tersembunyi dengan baik."
  },
  AvgDialog_60888_Content_35 = {
    Text = "Rencana Lemwah gagal, sangat disayangkan, tetapi tidak terlalu penting."
  },
  AvgDialog_60888_Content_36 = {
    Text = "Yang benar-benar penting hanyalah hari ini——hari ini, sembilan belas tahun kemudian."
  },
  AvgDialog_60888_Content_37 = {
    Text = "Merupakan hal yang menyenangkan bisa menyaksikan momen penting ini bersama seorang rekan seperti dirimu."
  },
  AvgDialog_60888_Content_38 = {
    Text = "Tujuan kita sama. Pertunjukan ini bukan dipersembahkan untukmu atau untukku."
  },
  AvgDialog_60888_Content_39 = {
    Text = "Demi mendengar kembali suara yang dibawa oleh keberadaan agung itu, semua pengorbanan terasa tidak berarti."
  },
  AvgDialog_60888_Content_4 = {
    Text = "Tongkat konduktor meluncur di udara, membentuk busur yang anggun. Bagian penutup dari gerakan musik telah tiba."
  },
  AvgDialog_60888_Content_40 = {
    Text = "Berbalik, berdiri tegak. Sang konduktor muda mengangkat kedua tangannya, memberi hormat kepada gedung teater yang kosong, serta kepada kedalaman galaksi yang tak terjangkau di luar teater."
  },
  AvgDialog_60888_Content_41 = {
    Text = "Semuanya sudah siap, mari kita berangkat, Nyonya Juliette."
  },
  AvgDialog_60888_Content_42 = {
    Text = "Pertunjukan yang sesungguhnya, akan segera dimulai."
  },
  AvgDialog_60888_Content_5 = {
    Text = "Lanskap suara yang mendebarkan, dirajut oleh akor kuat dan polifoni kompleks, mulai mereda."
  },
  AvgDialog_60888_Content_6 = {
    Text = "Arpeggio dari seruling dan harpa perlahan mengalun, seperti cahaya senja yang memantul di antara awan."
  },
  AvgDialog_60888_Content_7 = {
    Text = "Akor harmonis yang panjang perlahan memudar di udara, tanda istirahat pada not terakhir membawa nada menuju akhir."
  },
  AvgDialog_60888_Content_8 = {
    Text = "Pada saat yang begitu lama ini, konduktor menaruh tongkat konduktornya. Dia terdiam sambil melakukan perhitungan."
  },
  AvgDialog_60888_Content_9 = {
    Text = "Sepuluh detik, penonton terpesona oleh alunan musik, dan teater akan tenggelam dalam keheningan yang mirip dengan fajar."
  },
  AvgDialog_60889_Content_1 = {
    Text = "Di koridor yang sempit dan panjang, tidak terlihat satu pun bayangan manusia. Suara napas berat serta langkah kaki terdengar, bergema di sepanjang koridor."
  },
  AvgDialog_60889_Content_10 = {
    Text = "Tidak perlu bicara seperti itu, Dekan."
  },
  AvgDialog_60889_Content_11 = {
    Text = "Setelah kami menempatkan kalian di gedung Fakultas Ilmu Hidup, kami bisa..."
  },
  AvgDialog_60889_Content_12 = {
    Text = "Apakah Anda membutuhkan tumpangan, Nona Ramona?"
  },
  AvgDialog_60889_Content_13 = {Text = "!!!"},
  AvgDialog_60889_Content_14 = {Text = "Hati-hati!"},
  AvgDialog_60889_Content_15 = {
    Text = "Ramona mengangkat pedangnya di depan tubuhnya."
  },
  AvgDialog_60889_Content_16 = {
    Text = "Di belakangnya, Sylvie mengerutkan kening, melindungi Czort yang lemah."
  },
  AvgDialog_60889_Content_17 = {
    Text = "Langkah kaki yang terburu-buru terdengar, tampaknya sudah lama bersembunyi di sini."
  },
  AvgDialog_60889_Content_18 = {
    Text = "Di kedua ujung lorong yang sempit, para agen berpakaian seragam Komite memadati jalan mereka."
  },
  AvgDialog_60889_Content_19 = {
    Text = "Pria bermata satu melangkah ke depan kerumunan sambil dengan lembut menggoda kucing tanpa bulu di pundaknya, yang memiliki dua kepala yang dijahit menjadi satu."
  },
  AvgDialog_60889_Content_2 = {
    Text = "Huu... Dekan Czort, tolong bertahan sebentar lagi, kita hampir sampai."
  },
  AvgDialog_60889_Content_20 = {
    Text = "Itu... itu kamu..."
  },
  AvgDialog_60889_Content_21 = {
    Text = "Melihat wajah ini muncul di depannya, tubuh Czort langsung menegang."
  },
  AvgDialog_60889_Content_22 = {
    Text = "Herbert... dasar brengsek..."
  },
  AvgDialog_60889_Content_23 = {
    Text = "Guru Crowley memperlakukanmu seperti anaknya sendiri, dan kamu benar-benar melakukan hal yang tidak pantas padanya. Masih berani datang kembali…"
  },
  AvgDialog_60889_Content_24 = {
    Text = "Ssst, teman sekelas Czort... Ah tidak, seharusnya kupanggil kamu, Dekan Czort."
  },
  AvgDialog_60889_Content_25 = {
    Text = "Setelah aku pergi, posisi direktur pasti akan menjadi milikmu."
  },
  AvgDialog_60889_Content_26 = {
    Text = "Saya sangat ingin mengenang masa-masa indah saat kita menuntut ilmu dulu, tetapi hari ini saya datang ke sini juga memiliki urusan penting lain yang harus diselesaikan."
  },
  AvgDialog_60889_Content_27 = {
    Text = "Matanya tertuju pada Ramona."
  },
  AvgDialog_60889_Content_28 = {
    Text = "Sudah lama tidak bertemu, sangat merindukanmu, Nona Ramona."
  },
  AvgDialog_60889_Content_29 = {
    Text = "Namun, hanya bertemu beberapa kali dalam periode ini, tidak perlu berbicara seolah-olah sudah sangat akrab."
  },
  AvgDialog_60889_Content_3 = {
    Text = "Ramona, lukamu..."
  },
  AvgDialog_60889_Content_30 = {
    Text = "Selama ini? Tidak, tidak."
  },
  AvgDialog_60889_Content_31 = {
    Text = "Aku masih ingat pertama kali melihatmu, sepertinya itu terjadi di Lorong ini."
  },
  AvgDialog_60889_Content_32 = {
    Text = "Pada saat itu, kamu baru sebesar ini..."
  },
  AvgDialog_60889_Content_33 = {
    Text = "Herbert mengulurkan kedua tangannya, menirukan panjang seekor kucing tanpa bulu."
  },
  AvgDialog_60889_Content_34 = {
    Text = "Apa maksudmu...?"
  },
  AvgDialog_60889_Content_35 = {
    Text = "Relikku. Anakku."
  },
  AvgDialog_60889_Content_36 = {
    Text = "Helot adalah produk gagal. Dalam kerja sama antara aku dan Gereja Penerang Kuil, kau adalah kristal terbaik yang sempurna."
  },
  AvgDialog_60889_Content_37 = {
    Text = "Saya tidak mengerti..."
  },
  AvgDialog_60889_Content_38 = {
    Text = "Apakah kamu masih belum mengerti, Ramona?"
  },
  AvgDialog_60889_Content_39 = {
    Text = "Orang-orang yang kau pedulikan, mengalami ketakutan, menderita kerusakan, menghadapi ancaman kehilangan kendali dan kematian… semua bencana yang dialami Mythag ini terjadi karena dirimu."
  },
  AvgDialog_60889_Content_4 = {
    Text = "Dia mengeluarkan sapu tangan dan membersihkan noda darah di lengan Ramona."
  },
  AvgDialog_60889_Content_40 = {
    Text = "Kamu... apa yang kamu katakan?"
  },
  AvgDialog_60889_Content_41 = {
    Text = "Melihat pedang yang bergetar di tangan Ramona, Herbert tersenyum dan melangkah maju dua langkah."
  },
  AvgDialog_60889_Content_42 = {
    Text = "Banyak tahun yang lalu, pencuri bernama Dexter mencurimu dari kami."
  },
  AvgDialog_60889_Content_43 = {
    Text = "Hari ini datang terlambat, namun tidak masalah — itu tiba tepat pada waktunya."
  },
  AvgDialog_60889_Content_44 = {
    Text = "Kamu adalah kembar yang berharga, Relik sempurna dari sang Pemegang Lampu."
  },
  AvgDialog_60889_Content_5 = {
    Text = "Ah... maaf."
  },
  AvgDialog_60889_Content_6 = {
    Text = "Tadi saat bertarung dengan beberapa orang dariKomite, aku kehilangan konsentrasi sejenak……"
  },
  AvgDialog_60889_Content_7 = {
    Text = "Kekacauan di Kolam Hitam, tetap berdampak padamu, kan?"
  },
  AvgDialog_60889_Content_8 = {
    Text = "Hanya beberapa saja."
  },
  AvgDialog_60889_Content_9 = {
    Text = "Ramona, maaf telah merepotkan kalian. Jika aku tidak terluka, mungkin aku bisa membantu meringankan bebanmu sedikit…"
  },
  AvgDialog_60890_Content_1 = {
    Text = "Kamu berada di tengah badai."
  },
  AvgDialog_60890_Content_10 = {
    Text = "Deru tajam bergema di seluruh Kolam Hitam. Kekuasaan yang mewakili pengetahuan dalam tubuhnya bergetar seiring dengan deru itu."
  },
  AvgDialog_60890_Content_11 = {
    Text = "Tak terhitung jumlah bayangan putih, tertangkap dari dimensi dan ruang waktu yang berbeda, mengalir ke dalam patung hitam-putih itu."
  },
  AvgDialog_60890_Content_12 = {
    Text = "Segera, semua deru dan getaran itu menghilang."
  },
  AvgDialog_60890_Content_13 = {
    Text = "Tidak ada yang bisa menghindari-Nya, Tawil."
  },
  AvgDialog_60890_Content_14 = {
    Text = "Ayo, bersama-sama kita menyambut kelahiran-Nya!"
  },
  AvgDialog_60890_Content_15 = {
    Text = "Seiring dengan berhentinya gerakan Juliette, patung kembar lentera raksasa itu mulai mendekat ke arah tengah, seperti cangkang yang mencari Jiwa, dengan penuh keinginan untuk menyatu dengan Patung hitam putih di tengah."
  },
  AvgDialog_60890_Content_16 = {
    Text = "Tawil! Ramona!! Ah——"
  },
  AvgDialog_60890_Content_17 = {
    Text = "Seberkas cahaya terang tiba-tiba mekar. Di belakang Relik kembar raksasa, muncul sebuah celah."
  },
  AvgDialog_60890_Content_18 = {
    Text = "Kamu perlahan-lahan menyingkirkan kedua tanganmu yang menutupi mata."
  },
  AvgDialog_60890_Content_19 = {
    Text = "Itu adalah... pintu?"
  },
  AvgDialog_60890_Content_2 = {
    Text = "Getaran kuat membuat air di Kolam Hitam bergetar hebat, memunculkan gelombang besar yang menghantam tubuhmu."
  },
  AvgDialog_60890_Content_20 = {
    Text = "Di belakang Tawil, pintu ilusi itu pada saat ini menjadi nyata."
  },
  AvgDialog_60890_Content_21 = {
    Text = "Cahaya memancar dari celah pintu yang semakin melebar, dingin seperti alam semesta, murni seperti kebenaran."
  },
  AvgDialog_60890_Content_22 = {
    Text = "Kamu menatap kosong ke arah cahaya itu, dua aliran air mata mengalir di bawah cahaya terang tanpa kamu sadari. Kamu tak bisa memalingkan pandangan lagi."
  },
  AvgDialog_60890_Content_23 = {
    Text = "Pintu... Pintu yang menopang segala sesuatu... Tempat tinggal para Dewa..."
  },
  AvgDialog_60890_Content_24 = {
    Text = "Akhirnya, akhirnya hari ini tiba!"
  },
  AvgDialog_60890_Content_25 = {
    Text = "Tidak, pintu tidak boleh terbuka…"
  },
  AvgDialog_60890_Content_26 = {
    Text = "Apa yang ingin kamu lakukan? Kamu berusaha keras menggunakan Kunci Perak, tetapi Kekuatan Roh-mu saat ini tertekan sepenuhnya, dan Kunci Perak tidak menunjukkan reaksi apa pun."
  },
  AvgDialog_60890_Content_28 = {
    Text = "Kamu menatap dengan putus asa saat pintu itu berangsur-angsur berubah dari buram menjadi jelas, lalu terbuka sedikit celah."
  },
  AvgDialog_60890_Content_29 = {
    Text = "Kekuatan yang luar biasa itu, seperti banjir yang akan menenggelamkan dunia, mengalir dari dalam pintu menuju patung kembar pemegang lampu."
  },
  AvgDialog_60890_Content_3 = {
    Text = "Kolam Hitam bergoyang. Kubah bergoyang. Sepertinya seluruh Mythag, bahkan seluruh benua, bergetar dalam nyanyian Juliette."
  },
  AvgDialog_60890_Content_30 = {
    Text = "Juliette membelalakkan mata menatap pintu dan patung dewa, senyuman di wajahnya semakin menyeramkan."
  },
  AvgDialog_60890_Content_31 = {
    Text = "Kekuatan, adalah kekuatan di balik pintu... Patung Kembar, akan segera menyelesaikan fusi."
  },
  AvgDialog_60890_Content_32 = {
    Text = "Mythag… Penjaga… dan dunia penuh dosa ini, terimalah pemurnian terakhir!"
  },
  AvgDialog_60890_Content_33 = {Text = "Ding——"},
  AvgDialog_60890_Content_34 = {
    Text = "Symphony keempat, dimulai."
  },
  AvgDialog_60890_Content_35 = {Text = "!!!"},
  AvgDialog_60890_Content_36 = {
    Text = "Seperti puluhan ribu musisi memainkan instrumen mereka secara bersamaan, suara dari alat musik dawai, tiup, dan perkusi saling bertautan dan berkumpul menjadi sebuah aliran yang megah."
  },
  AvgDialog_60890_Content_37 = {
    Text = "Sungai mengalir deras, tiba-tiba menerjang ke arah tautan yang lemah di antara gerbang dan patung kembar."
  },
  AvgDialog_60890_Content_38 = {
    Text = "Reaksi balik dari Kekuatan di balik pintu membuat kembaran itu bergetar hebat. Aura berbahaya yang berasal dari patung dewa menjadi jelas lebih tipis."
  },
  AvgDialog_60890_Content_39 = {
    Text = "Patung batu yang bergerak menuju pusat, menghentikan gerakannya."
  },
  AvgDialog_60890_Content_4 = {
    Text = "Di tengah guncangan hebat ini, kamu mengangkat kepala dan melihat Relik di depanmu yang semakin megah."
  },
  AvgDialog_60890_Content_40 = {
    Text = "Wajah yang sudah dikenal itu keluar dari bayangan dan kembali muncul di hadapanmu."
  },
  AvgDialog_60890_Content_41 = {
    Text = "Saatnya telah tiba. Pertunjukan terakhir, segera dimulai."
  },
  AvgDialog_60890_Content_42 = {
    Text = "Dia mengayunkan tongkatnya dengan lembut. Sebuah melodi lembut mengalir ke dalam Dunia rohmu."
  },
  AvgDialog_60890_Content_43 = {
    Text = "Belenggu dan penderitaan yang berat itu tiba-tiba menghilang, kamu kembali berendam di dalam sumber air panas, dan pikiranmu dipenuhi kembali dengan energi roh yang lebih besar daripada sebelumnya."
  },
  AvgDialog_60890_Content_44 = {
    Text = "Kamu... kamu tidak merusak Tautan roh-ku..."
  },
  AvgDialog_60890_Content_45 = {
    Text = "Sebelumnya, kemampuan tautanmu untuk sementara diputus. Sebuah cara untuk menyesatkan Juliette."
  },
  AvgDialog_60890_Content_46 = {
    Text = "Batasanmu telah dicabut. Sekarang, pintu sudah terbuka, dan semua persiapan telah rampung."
  },
  AvgDialog_60890_Content_47 = {
    Text = "Dia berdiri di hadapanmu, di matanya yang tenang menyala api yang membara."
  },
  AvgDialog_60890_Content_48 = {
    Text = "Dia meletakkan tongkat komando di belakang punggungnya, lalu membungkuk memberi hormat kepadamu."
  },
  AvgDialog_60890_Content_49 = {
    Text = "Mata buta, pelaksana Kehendak Tertinggi. Aku akan membantu kamu untuk mengambil kembali kekuasaan yang menjadi hakmu."
  },
  AvgDialog_60890_Content_5 = {
    Text = "Kembar... Patung dewa..."
  },
  AvgDialog_60890_Content_50 = {
    Text = "Kamu... apa yang kamu katakan?"
  },
  AvgDialog_60890_Content_51 = {
    Text = "Kedatangan Kehendak Tertinggi tidak terhindarkan, hanya kamu yang dapat melawannya."
  },
  AvgDialog_60890_Content_52 = {
    Text = "Biarkan kembaran muncul, pintu terbuka, maka kamu akan mendapatkan kembali kemampuan untuk melawan-Nya."
  },
  AvgDialog_60890_Content_53 = {
    Text = "Dalam keadaan mendesak, mohon maafkan kelakuanku yang kurang sopan sebelumnya."
  },
  AvgDialog_60890_Content_54 = {
    Text = "Hameln! Apa... apa yang sedang kamu lakukan?!!!"
  },
  AvgDialog_60890_Content_55 = {
    Text = "Lakukan apa yang harus aku lakukan."
  },
  AvgDialog_60890_Content_56 = {
    Text = "Dia hanyalah sebuah fragmen! Hanya dengan caraku, kehendak tertinggi yang sebenarnya dapat bangkit…"
  },
  AvgDialog_60890_Content_57 = {
    Text = "Bukankah kau ingin mendengar suara musik tertinggi dari Kehendak Tertinggi? Hameln, kau telah melakukan penghianatan terhadap apa yang kau percayai!"
  },
  AvgDialog_60890_Content_58 = {
    Text = "Dewa belum tentu lebih agung daripada Fragmennya. Lagipula, ini bukanlah hal yang saya pedulikan, Nyonya Juliette."
  },
  AvgDialog_60890_Content_59 = {
    Text = "Saya dulu juga berpikir bahwa Requiem dari Kehendak Tertinggi adalah suara paling agung di alam semesta ini, tetapi akhirnya saya menyadari. Seni yang benar-benar luhur akan melampaui dirinya sendiri."
  },
  AvgDialog_60890_Content_6 = {
    Text = "Dua patung batu berbentuk manusia berwarna putih perlahan muncul dari bawah Kolam Hitam, membuat seluruh Kolam Hitam bergetar."
  },
  AvgDialog_60890_Content_60 = {
    Text = "Dia mengangkat kepalanya, sepasang mata yang menyala dengan api ganas itu diam-diam menatap Juliette."
  },
  AvgDialog_60890_Content_61 = {
    Text = "Itu akan bergema dalam perjuangan — pertarungan antara manusia dan Dewa. Pertarungan antara Fragmen dan asal."
  },
  AvgDialog_60890_Content_62 = {
    Text = "Melawan Kehendak Tertinggi, berpadu dengan Kehendak Tertinggi... ini akan menjadi suara yang lebih luhur daripada Requiem Kehendak Tertinggi!"
  },
  AvgDialog_60890_Content_63 = {
    Text = "Sejak kapan kamu..."
  },
  AvgDialog_60890_Content_64 = {
    Text = "Musim semi Akut, kami menyaksikan ledakan itu."
  },
  AvgDialog_60890_Content_65 = {
    Text = "Pada hari itu, aku mendengarnya... apa yang kucari lebih abadi daripada requiem, musik yang bergema dalam perjuangan."
  },
  AvgDialog_60890_Content_66 = {
    Text = "Pada saat itu, aku hanya mendengar intro-nya. Hari ini, ia akan bergema sepenuhnya di dunia ini."
  },
  AvgDialog_60890_Content_67 = {
    Text = "Suara Hameln yang biasanya tenang tidak bisa menahan gemetar."
  },
  AvgDialog_60890_Content_68 = {
    Text = "Jadi, sejak hari itu, kau sudah merencanakan penghianatan…"
  },
  AvgDialog_60890_Content_69 = {
    Text = "Dewa telah melupakan musik-Nya. Dia hanyalah tubuh Kekacauan tanpa kesadaran, sebuah bencana besar."
  },
  AvgDialog_60890_Content_7 = {
    Text = "Di celah tengah patung, tubuh Ramona dililit dan dibungkus oleh tubuh Tawil."
  },
  AvgDialog_60890_Content_70 = {
    Text = "Semua keindahan-Nya ada pada Fragmen-fragmen-Nya."
  },
  AvgDialog_60890_Content_71 = {
    Text = "Saya setia pada musik, saya tak pernah melakukan penghianatan, Juliette."
  },
  AvgDialog_60890_Content_72 = {
    Text = "Dia dengan tenang menatap Juliette, patung raksasa. serta pintu di belakang patung raksasa itu."
  },
  AvgDialog_60890_Content_73 = {
    Text = "Dia berdiri di sisimu."
  },
  AvgDialog_60890_Content_74 = {
    Text = "Kenapa… jika kamu membantuku sejak awal, Ramona tidak akan…"
  },
  AvgDialog_60890_Content_75 = {
    Text = "Penjaga %player%, kedatangan Kehendak Tertinggi tidak dapat dihentikan. Membiarkan Juliette memanggil pintu keluar, sehingga kamu dapat dengan lancar memulihkan kekuasaan, adalah satu-satunya jalan."
  },
  AvgDialog_60890_Content_76 = {
    Text = "Apa yang kita cari berbeda, tetapi baik suara tertinggi maupun kelangsungan dunia, kesempatan ini hanya datang sekali."
  },
  AvgDialog_60890_Content_77 = {
    Text = "Dalam pertunjukan ini, kamu, aku, Nyonya Ramona, semua orang di sini hanyalah pemain musik."
  },
  AvgDialog_60890_Content_78 = {
    Text = "Nyonya Ramona akan memahaminya."
  },
  AvgDialog_60890_Content_79 = {
    Text = "Kamu tahu, Hameln benar. Ramona pasti akan mengerti. Demi kelangsungan dunia, dia tidak pernah keberatan untuk mengorbankan dirinya sendiri."
  },
  AvgDialog_60890_Content_8 = {
    Text = "Dua sosok tanpa pemilik terus berubah dan menyatu, menjadi sebuah patung raksasa berwarna hitam dan putih, melayang di antara patung-patung batu setengah badan yang besar."
  },
  AvgDialog_60890_Content_80 = {
    Text = "Dexter sudah menghilang, namun di dunia ini, pasti masih ada orang yang memperhatikan."
  },
  AvgDialog_60890_Content_81 = {
    Text = "——Setidaknya, dia masih hidup sekarang."
  },
  AvgDialog_60890_Content_82 = {
    Text = "Merasakan energi roh yang semakin deras di dalam tubuhmu, kamu mengangkat kepala dan menatap patung hitam-putih itu."
  },
  AvgDialog_60890_Content_83 = {
    Text = "Ayo pergi, Penjaga %player%. Pergi hancurkan patung itu, dan selamatkan temanmu."
  },
  AvgDialog_60890_Content_84 = {
    Text = "Tunjukkan kekuasaanmu kepada dunia ini... Ingatlah kembali segalanya tentang Kehendak Tertinggi."
  },
  AvgDialog_60890_Content_9 = {
    Text = "Ketemu kamu... Tawil!"
  },
  AvgDialog_60897_Content_1 = {
    Text = "Penjaga... kami berhasil!"
  },
  AvgDialog_60897_Content_10 = {
    Text = "Dia menoleh ke arah yang sedang kamu lihat—"
  },
  AvgDialog_60897_Content_11 = {
    Text = "Di balik pintu yang terbuka, tak terhitung jumlahnya gelembung pecah secara bersamaan. Waktu, ruang, dan pengetahuan hancur menjadi fragmen-fragmen, seperti noda minyak yang kacau, mewarnai dimensi ini dengan warna-warna rumit dan kotor."
  },
  AvgDialog_60897_Content_12 = {
    Text = "Di balik fragmen-fragmen yang melambangkan segala sesuatu, sebuah mata perlahan terbuka, seperti bayi yang baru lahir, dengan rasa ingin tahu memandang dunia ini."
  },
  AvgDialog_60897_Content_13 = {
    Text = "Di mana pun pandangan mata memandang, tak terhitung banyaknya objek yang semula ada di dunia ini berubah menjadi cairan pelarutan, mengalir masuk ke dalam Kolam Hitam."
  },
  AvgDialog_60897_Content_14 = {
    Text = "Pandangan itu bergerak, dan akhirnya tertuju padamu."
  },
  AvgDialog_60897_Content_15 = {
    Text = "Bangun…@3…Bangun!…"
  },
  AvgDialog_60897_Content_16 = {
    Text = "Murid-Nya tiba-tiba membesar, dan seluruh alam semesta seolah-olah bergetar sesaat bersamaan dengan-Nya."
  },
  AvgDialog_60897_Content_17 = {
    Text = "Kamu menatap-Nya. Tatapan semacam itu tanpa diragukan adalah sebuah penghinaan. Segala sesuatu di dunia ini lenyap dari kesadaranmu."
  },
  AvgDialog_60897_Content_18 = {
    Text = "Ketakutan. Ketakutan yang paling asli, paling murni, tak terbayangkan, dan tak terelakkan, memenuhi seluruh tubuhmu."
  },
  AvgDialog_60897_Content_2 = {
    Text = "Di wajah Ramona, senyuman merekah."
  },
  AvgDialog_60897_Content_20 = {
    Text = "Hohoho... Hahaha!"
  },
  AvgDialog_60897_Content_21 = {
    Text = "Aku tidak salah menilaimu, %player%. Aku tidak salah menilaimu!"
  },
  AvgDialog_60897_Content_22 = {
    Text = "Suara N datang dari bayangan Kolam Hitam. Pemandangan di depan membuat-Nya sepenuhnya melupakan untuk menjaga keanggunan-Nya. Dia tertawa dengan Kegilaan, memandang ke arah pintu dengan penuh Kegilaan."
  },
  AvgDialog_60897_Content_23 = {
    Text = "Dia bangun. Dia bangun! Ha!"
  },
  AvgDialog_60897_Content_24 = {
    Text = "Lalu, %player%, Fragmen, tiruan..."
  },
  AvgDialog_60897_Content_25 = {
    Text = "Dia berbalik, mulut jahatnya terbuka lebar. Wajahnya yang hitam pekat tanpa mata menatapmu dengan penuh rasa ingin tahu."
  },
  AvgDialog_60897_Content_26 = {
    Text = "Katakan padaku... sekarang, apa yang bisa kau lakukan?"
  },
  AvgDialog_60897_Content_3 = {
    Text = "Penjaga, sekarang kita bisa…"
  },
  AvgDialog_60897_Content_4 = {Text = "?!!!"},
  AvgDialog_60897_Content_5 = {
    Text = "Penjaga Rahasia?"
  },
  AvgDialog_60897_Content_6 = {
    Text = "Ramona memandangmu dengan rasa penasaran."
  },
  AvgDialog_60897_Content_7 = {
    Text = "Di saat-saat penuh kebahagiaan ini, dia melihat ekspresi yang belum pernah dilihatnya di wajahmu ——"
  },
  AvgDialog_60897_Content_8 = {
    Text = "Itu adalah ketika seseorang menghadapi keruntuhan alam semesta yang megah..."
  },
  AvgDialog_60897_Content_9 = {
    Text = "Kedinginan, ketakutan, keputusasaan, dan kelemahan yang terungkap."
  },
  AvgDialog_61921_Content_1 = {
    Text = "Kamu dikelilingi oleh mimpi buruk yang amorf, pikiran aneh menjepit kesadaranmu, membuat mimpi menjadi terbalik dan keruh."
  },
  AvgDialog_61921_Content_10 = {
    Text = "Dia menoleh, tatapannya tenang dan dingin, namun kamu tak mampu menolak kata-katanya."
  },
  AvgDialog_61921_Content_11 = {
    Text = "Lebih dekat lagi."
  },
  AvgDialog_61921_Content_12 = {
    Text = "Dia bersandar di dadamu, dan kamu merasakan napasmu semakin cepat."
  },
  AvgDialog_61921_Content_13 = {
    Text = "Tawil memegang tanganmu, lalu menyentuh permukaan air di Kolam Hitam. Riak-riak melingkar mulai menyebar ke luar."
  },
  AvgDialog_61921_Content_14 = {
    Text = "Apakah kamu mendengarnya? Ini adalah detak jantungmu."
  },
  AvgDialog_61921_Content_15 = {
    Text = "Tidak peduli di era apa atau ruang mana pun aku berada... napas dan detak jantungmu akan tersampaikan padaku melalui kolam ini."
  },
  AvgDialog_61921_Content_16 = {
    Text = [[
Ini adalah pertama kalinya aku mendengarkan detak jantungmu seperti ini. 
Bersamaan dengan frekuensi yang sama yang kudengar siang dan malam, begitu memekakkan telinga.]]
  },
  AvgDialog_61921_Content_17 = {
    Text = "Dia mengangkat matanya dan menatapmu, dengan pikiran yang tidak jelas tersebar di dalam muridnya yang berwarna abu-abu kehijauan."
  },
  AvgDialog_61921_Content_18 = {
    Text = [[
Kamu merasa di sekitarmu seperti hujan lagi.
Apakah Kolam Hitam juga bisa hujan?]]
  },
  AvgDialog_61921_Content_19 = {
    Text = [[
Benang hujan perak membungkus kalian berdua dengan lembut dan rapat. 
 Ini adalah waktu dan ruang yang hanya milikmu dan dia.]]
  },
  AvgDialog_61921_Content_2 = {
    Text = [[
Setetes cairan dingin jatuh di pelipismu seperti ciuman lembut, disusul oleh hujan perak yang memenuhi langit. 
 Kamu Bangun oleh benang-benang hujan itu.]]
  },
  AvgDialog_61921_Content_20 = {
    Text = "Apakah kamu tahu? Dia akan menyesal menyebarkan hasrat seperti itu…"
  },
  AvgDialog_61921_Content_21 = {
    Text = "Tautan di antara kita jauh lebih dalam dan lebih jauh... daripada yang dia coba lakukan untuk menodaimu."
  },
  AvgDialog_61921_Content_3 = {
    Text = "Hah, hah……"
  },
  AvgDialog_61921_Content_4 = {
    Text = "Malam di asrama seperti diselimuti oleh lapisan kasa tipis, suara yang samar-samar bergema di telinga Anda."
  },
  AvgDialog_61921_Content_5 = {
    Text = "Saya menunggumu di Kolam hitam."
  },
  AvgDialog_61921_Content_7 = {
    Text = "Kain sutra putih menutupi sisi wajahnya, uap air yang mengelilingi Kolam Hitam seolah menjadi perpanjangan dirinya, menarikmu ke dalam mimpi seperti fatamorgana."
  },
  AvgDialog_61921_Content_8 = {
    Text = "Di antara ribuan mimpi, dia berdiri di depan pintu kehampaan, mengajukan pertanyaan tanpa suara kepadamu."
  },
  AvgDialog_61921_Content_9 = {
    Text = "Ayo, datanglah ke sisiku."
  },
  AvgDialog_62163_Content_1 = {
    Text = "Ramona dilahap kembali oleh patung dewa…?!"
  },
  AvgDialog_62163_Content_2 = {
    Text = "Ini adalah kekuatan dari \"Prinsip Penghapusan\"... Kesadaran saya sudah terpengaruh, dan saya tidak bisa lagi memberikan suara lengkap untukmu. Pertempuran berikutnya akan sangat keras..."
  },
  AvgDialog_62163_Content_3 = {
    Text = "Dia sama seperti kita, juga telah mencapai batasnya… Aku tidak akan… jatuh di sini!"
  },
  AvgDialog_62164_Content_1 = {
    Text = "Ramona dilahap kembali oleh patung dewa…?!"
  },
  AvgDialog_62164_Content_2 = {
    Text = "Ini adalah kekuatan dari \"Prinsip Penghapusan\"... Kesadaran saya sudah terpengaruh, dan saya tidak bisa lagi memberikan suara lengkap untukmu."
  },
  AvgDialog_62164_Content_3 = {
    Text = "Sebelum dilahap, kesadaran Ramona juga membuat-Nya mengalami luka parah. Dia masih berdiri di sisimu, Penjaga."
  },
  AvgDialog_62164_Content_4 = {
    Text = "Seutas benang di dalam pikiranmu bergetar lembut, dan kamu mendengar suara yang samar."
  },
  AvgDialog_62164_Content_5 = {
    Text = "Mengingat masa lalu... tidak bisa... melupakan..."
  },
  AvgDialog_62164_Content_6 = {
    Text = "Biarkan aku dan kamu... berdiri bersama..."
  },
  AvgDialog_62165_Content_1 = {
    Text = "Penjaga Rahasia…"
  },
  AvgDialog_62165_Content_2 = {
    Text = "Ramona?! Kamu... sudah sadar?!"
  },
  AvgDialog_62165_Content_3 = {
    Text = "Maaf, kali ini aku tidak bisa berjuang bersamamu lagi... tapi sekarang aku tidak akan melanggar janjiku lagi."
  },
  AvgDialog_62165_Content_4 = {
    Text = [[
Dari tautan pertama, memori yang menjadi milik kita, kita tidak akan membiarkan siapa pun mengambilnya. 
Benar, Penjaga?]]
  },
  AvgDialog_62165_Content_5 = {
    Text = "Seiring dengan suara Ramona yang bergema di benakmu, patung dewa itu mengeluarkan deru keras, seakan-akan sebuah pisau tajam menusuk saraf-Nya."
  },
  AvgDialog_62165_Content_6 = {
    Text = "Seberkas cahaya memancar dari bunga perak di atas kepalanya, lalu jatuh tepat pada tubuhmu."
  },
  AvgDialog_62165_Content_7 = {
    Text = "Kamu tahu, dia tak pernah melupakan. Dia telah datang ke sisimu — seperti yang telah dilakukannya berkali-kali sebelumnya."
  },
  AvgDialog_62166_Content_1 = {
    Text = "Hanya kita tidak bisa menghentikan patung dewa itu… Aku akan menggunakan suara musik untuk membantu kamu membuat Tautan dengan Ramona. Tutup matamu, dan panggillah dia dengan kesadaranmu!"
  },
  AvgDialog_62166_Content_10 = {
    Text = "Ramona mengangkat kepalanya dan memandang ke arah datangnya suara."
  },
  AvgDialog_62166_Content_11 = {
    Text = "Aku sudah berjanji kepada {Male=dia,Female=dia}. Apapun waktu atau situasi yang dihadapi… aku akan selalu berdiri di sisi {Male=dia,Female=dia}."
  },
  AvgDialog_62166_Content_12 = {
    Text = [[
Di antara suara musik Hameln dan panggilanmu, fusi patung dewa tiba-tiba berhenti. 
Sebuah bunga perak yang cacat namun berkilauan dengan cahaya mengalir, melayang meninggalkan tubuh patung hitam-putih.]]
  },
  AvgDialog_62166_Content_13 = {
    Text = "Ramona, tunggu aku!"
  },
  AvgDialog_62166_Content_14 = {
    Text = "Aku pasti akan menyelamatkanmu! … Ramona, tunggu aku!!"
  },
  AvgDialog_62166_Content_15 = {
    Text = "Kau berteriak pada bunga perak itu. Melalui dunia roh yang kosong, bayangan perak itu tersenyum padamu."
  },
  AvgDialog_62166_Content_16 = {
    Text = "Saya percaya kamu, Penjaga."
  },
  AvgDialog_62166_Content_17 = {
    Text = "...Aku akan menunggumu."
  },
  AvgDialog_62166_Content_2 = {Text = "Ramona!"},
  AvgDialog_62166_Content_3 = {
    Text = "Ada suara... sangat familiar, itu..."
  },
  AvgDialog_62166_Content_4 = {
    Text = "Patung dewa sedang melahap kesadaran kita. Memori kita hampir menghilang, Ramona. Menghilang dari setiap dimensi, setiap ruang waktu di dunia ini, seolah-olah tidak pernah ada."
  },
  AvgDialog_62166_Content_5 = {
    Text = "Ayah, kekuatan, kebebasan, hidup… kamu akan kehilangan lebih banyak lagi, Ramona."
  },
  AvgDialog_62166_Content_6 = {
    Text = "Tidak, Tawil... Ada sesuatu yang tidak bisa aku kehilangan. Setidaknya saat ini, aku masih memiliki {Male=dia,Female=dia}..."
  },
  AvgDialog_62166_Content_7 = {
    Text = "Belenggu patung dewa tidak dapat dihancurkan. Jika kamu memaksakan diri untuk melepaskannya, kamu akan menanggung rasa sakit yang luar biasa, dan bantuan yang diberikan oleh {Male=dia,Female=dia} juga sangat terbatas."
  },
  AvgDialog_62166_Content_8 = {
    Text = "Meskipun begitu, apakah kamu tetap bersedia?"
  },
  AvgDialog_62166_Content_9 = {
    Text = "Jika tidak, kita hanya bisa membiarkan patung dewa terbentuk. Benar, kan?"
  },
  AvgDialog_62167_Content_1 = {
    Text = "Game berakhir di sini, Penjaga {Male=tuan,Female=nyonya}."
  },
  AvgDialog_62167_Content_10 = {
    Text = "Dia tidak lagi memperhatikan sikapnya dan membungkuk untuk muntah."
  },
  AvgDialog_62167_Content_11 = {
    Text = "Tidak, tidak mungkin... Anda adalah kehendak yang agung... Anda adalah yang membawa pemurnian bagi dunia ini..."
  },
  AvgDialog_62167_Content_12 = {
    Text = "Mimpi… Kehancuran… Tidak… Tidak!"
  },
  AvgDialog_62167_Content_13 = {
    Text = "Dia terkulai di depan pintu, memeluk erat lengan sendiri, Tubuhnya gemetar tak terkendali."
  },
  AvgDialog_62167_Content_14 = {
    Text = "Juliette? Apa yang kamu lihat?!"
  },
  AvgDialog_62167_Content_15 = {
    Text = "Kebenaran... Ternyata... Inilah kebenarannya..."
  },
  AvgDialog_62167_Content_16 = {
    Text = "Juliette tidak menghiraukan teriakanmu. Setelah melihat pintu itu sesaat, segala sesuatu di dunia ini tampaknya tidak lagi berhubungan dengannya."
  },
  AvgDialog_62167_Content_17 = {
    Text = "Patung batu!…"
  },
  AvgDialog_62167_Content_18 = {
    Text = "Kamu mengangkat kepalamu——"
  },
  AvgDialog_62167_Content_19 = {
    Text = "Aroma yang meluap dari pintu telah sepenuhnya diserap, patung yang awalnya terhalang oleh kalian tiba-tiba bergabung bersama."
  },
  AvgDialog_62167_Content_2 = {
    Text = "Di depan Juliette, pintu terbuka dengan celah yang cukup untuk seseorang melewatinya."
  },
  AvgDialog_62167_Content_20 = {
    Text = "Patung batu raksasa itu tampak seperti makhluk hidup, berdiri dengan penuh wibawa di hadapanmu."
  },
  AvgDialog_62167_Content_21 = {
    Text = "Juliette dengan Kelemahan mengangkat kepalanya, memandang Relik raksasa di depannya yang tak bisa lagi ia kendalikan, dan dengan sisa tenaganya, dia menyeringai dengan penuh kesedihan."
  },
  AvgDialog_62167_Content_22 = {
    Text = "Awal yang salah, akhir yang salah. Akhir, juga merupakan pemurnian... Biarlah semuanya berakhir di sini."
  },
  AvgDialog_62167_Content_23 = {
    Text = "Juliette perlahan jatuh. Dia jatuh tepat sebelum kebenaran di balik pintu terungkap."
  },
  AvgDialog_62167_Content_24 = {
    Text = "Sebelum tubuhnya, patung batu raksasa dengan aura Jurang yang pekat perlahan bangkit di hadapanmu ——"
  },
  AvgDialog_62167_Content_3 = {
    Text = "Kehendak kalian sungguh mengagumkan, sayangnya, kehendak yang salah arah tidak berguna sama sekali."
  },
  AvgDialog_62167_Content_4 = {
    Text = "Semua pengetahuan dan kekuatan tersembunyi di balik pintu ini. Pintu akan membantu saya menyelesaikan fusi patung kembar dewa."
  },
  AvgDialog_62167_Content_5 = {
    Text = "Aku akan berada di sini, menyambut Dewa tertinggi yang akan menyucikan dunia ini ——"
  },
  AvgDialog_62167_Content_6 = {
    Text = "Dia berdiri di depan Pintu, tersenyum sambil mengintip ke dalam."
  },
  AvgDialog_62167_Content_7 = {
    Text = "Juliette... Tunggu!"
  },
  AvgDialog_62167_Content_8 = {
    Text = "AHHH!!!——"
  },
  AvgDialog_62167_Content_9 = {
    Text = "Hampir hanya melihat sekilas ke dalam, Juliette berteriak dan mundur."
  },
  AvgDialog_62168_Content_1 = {
    Text = "Fusi patung batu hampir selesai…!"
  },
