  },
  AvgDialog_62168_Content_3 = {
    Text = "Tongkat komando Hameln jatuh dengan keras, sepenuhnya mengabaikan darah yang memancar deras dari mulutnya."
  },
  AvgDialog_62168_Content_4 = {
    Text = "Patung batu yang hampir sepenuhnya menyatu tiba-tiba terbelah, membentuk celah akibat dampak dari suara musik."
  },
  AvgDialog_62168_Content_5 = {
    Text = "Juliette melihat adegan ini, tersenyum tipis, lalu menggelengkan kepalanya."
  },
  AvgDialog_62168_Content_6 = {
    Text = "Game berakhir di sini, Penjaga {Male=tuan,Female=nyonya}."
  },
  AvgDialog_62168_Content_7 = {
    Text = "Di depan Juliette, pintu terbuka dengan celah yang cukup untuk seseorang melewatinya."
  },
