  },
  AvgDialog_62169_Content_1 = {
    Text = "Patung itu bergerak... Aku akan membantumu berhubungan dengan Ramona menggunakan musik. Tutup matamu, panggil dia dengan kesadaranmu."
  },
  AvgDialog_62169_Content_10 = {
    Text = "Ramona, tunggu aku!"
  },
